-- ----------------------------
-- 趣味模块：古诗文相关
-- ----------------------------
-- 1) 新增「古诗文闯关」（七种玩法合一，见 EduPoemChallengeController）
--    fun_config_grade_level 为 NULL 表示各学段通用；唯一索引含可空列时 NULL 互不相等，
--    因此用 WHERE NOT EXISTS 保证重复执行不产生重复行。
     fun_config_show_badge, module_name, module_desc, module_icon, module_path, enabled, sort_order)
SELECT 'poem-challenge', NULL, '七种玩法读懂一首诗', '#6d5dfc', '#9b8cff',
       0, '古诗文闯关', '诗句排序 / 飞花令 / 看句猜题 / 诗归其主 / 朝代溯源 / 题材归类 / 炼字填空',
       'Medal', '/edu/fun/poem-challenge', 1, 3
WHERE NOT EXISTS (
    SELECT 1 FROM edu_fun_config WHERE module_code = 'poem-challenge' AND fun_config_grade_level IS NULL
);

-- 2) 新增「古诗补全」（选下一句；此前只有路由、未登记为模块）
     fun_config_show_badge, module_name, module_desc, module_icon, module_path, enabled, sort_order)
SELECT 'poem-game', NULL, '给上句，选下句', '#409eff', '#79bbff',
       0, '古诗补全', '从四个选项里选出紧接的下一句', 'Reading', '/edu/fun/poem', 1, 4
WHERE NOT EXISTS (
    SELECT 1 FROM edu_fun_config WHERE module_code = 'poem-game' AND fun_config_grade_level IS NULL
);

-- 3) 修复悬空模块：数据库里注册了「诗词大会」指向 /edu/fun/poetry，
--    但前端从未有该路由（点开必然 404）。指向已落地的「古诗文闯关」，
--    文案同步，避免再出现「有模块没页面」。
UPDATE edu_fun_config
SET module_path = '/edu/fun/poem-challenge',
    module_desc = '诗句排序 / 飞花令 / 看句猜题 / 诗归其主 / 朝代溯源 / 炼字填空'
WHERE module_code = 'poetry'
  AND module_path = '/edu/fun/poetry';

-- ----------------------------
-- 唐诗名篇（含人工译文/注释/创作背景）74 首
-- ----------------------------
-- 数据来源：公开 gist soyaine/TangPoetry.json（74 首唐诗名篇，含人工译文与注释）。
-- chinese-poetry 语料只有正文、没有译文，学生无法对照学习，故补入这份带译文的数据集。
-- 形态：每条先 INSERT IGNORE 新诗，再 UPDATE 回填译文/注释/背景 ——
--      这些名篇可能与已采集的诗同标题同作者，只 INSERT 的话已存在的那批永远补不上译文。
-- 学段：这批是唐诗名篇（静夜思/春晓/登鹳雀楼/相思/江雪…），主体属小学必背范围，
--      故标「小学」——既符合实际教学，也让小学端有可玩内容（采集语料全标高中）。
--      个别篇目（如行宫、新嫁娘词）更接近初中，可在页面按需调整。

VALUES ('行宫', '元稹', '唐代', '寥落古行宫，宫花寂寞红。白头宫女在，闲坐说玄宗。', 2);
UPDATE edu_poem SET poem_translation = '空旷冷落的古旧行宫，只有宫花寂寞地艳红。\n几个满头白发的宫女，闲坐无事谈论唐玄宗。', poem_notes = '（1）寥（liáo）落：寂寞冷落。\n（2）行宫：皇帝在京城之外的宫殿。这里指当时东都洛阳的皇帝行宫上阳宫。\n（3）宫花：行宫里的花。\n（4）白头宫女：据白居易《上阳白发人》，一些宫女天宝末年被“潜配”到上阳宫，在这冷宫里一闭四十多年，成了白发宫人。\n（5）说：谈论。\n（6）玄宗：指唐玄宗。', poem_appreciation = '元稹生活在中唐年代，正值唐朝经历过安史之乱不久，国力的各个方面都在走下坡路之时。该诗就是以小见大地点明了唐朝衰败的重要原因。' WHERE poem_title = '行宫' AND poem_author = '元稹';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '行宫' AND p.poem_author = '元稹';
VALUES ('登鹳雀楼', '王之涣', '唐代', '白日依山尽，黄河入海流。欲穷千里目，更上一层楼。', 2);
UPDATE edu_poem SET poem_translation = '夕阳依傍着西山慢慢地沉没， 滔滔黄河朝着东海汹涌奔流。\n若想把千里的风光景物看够， 那就要登上更高的一层城楼。', poem_notes = '1．鹳雀楼：旧址在山西永济县，楼高三层，前对中条山，下临黄河。传说常有鹳雀在此停留，故有此名。\n2．白日：太阳。\n3．依：依傍。\n4．尽：消失。 这句话是说太阳依傍山峦沉落。\n5。欲：想要得到某种东西或达到某种目的的愿望，但也有希望、想要的意思。\n6．穷：尽，使达到极点。\n7．千里目：眼界宽阔。\n8．更：替、换。（不是通常理解的“再”的意思）', poem_appreciation = '该诗是唐代诗人王之涣仅存的六首绝句之一。　　作者早年及第，曾任过冀州衡水（今河北衡水）县的主薄，不久因遭人诬陷而罢官，不到三十岁的王之涣从此过上了访友漫游的生活。写这首诗的时候，王之涣只有三十五岁。' WHERE poem_title = '登鹳雀楼' AND poem_author = '王之涣';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '登鹳雀楼' AND p.poem_author = '王之涣';
VALUES ('新嫁娘词', '王建', '唐代', '三日入厨下，洗手作羹汤。未谙姑食性，先遣小姑尝。', 2);
UPDATE edu_poem SET poem_translation = '新婚三天来到厨房，洗手亲自来作羹汤。\n不知婆婆什么口味，做好先让小姑品尝。', poem_notes = '1.三日：古代风俗，新媳妇婚后三日须下厨房做饭菜。\n2.羹：泛指做成浓的菜肴。\n3.“未谙”句：意思是还不熟悉婆婆的口味。谙：熟悉。姑食性：婆婆的口味。\n4.遣：让。小姑：一作“小娘”。丈夫的妹妹。也称小姑子。' WHERE poem_title = '新嫁娘词' AND poem_author = '王建';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '新嫁娘词' AND p.poem_author = '王建';
VALUES ('相思', '王维', '唐代', '红豆生南国，春来发几枝。愿君多采撷，此物最相思。', 2);
UPDATE edu_poem SET poem_translation = '鲜红浑圆的红豆，生长在阳光明媚的南方，春暖花开的季节，不知又生出多少？\n希望思念的人儿多多采集，小小红豆引人相思。', poem_notes = '⑴相思：题一作“相思子”，又作“江上赠李龟年”。\n⑵红豆：又名相思子，一种生在江南地区的植物，结出的籽像豌豆而稍扁，呈鲜红色。\n⑶“春来”句：一作“秋来发故枝”。\n⑷“愿君”句：一作“劝君休采撷”。采撷（xié）：采摘。\n⑸相思：想念。', poem_appreciation = '此诗一作《江上赠李龟年》，可见为怀念友人之作。据载，天宝末年安史之乱时，李龟年流落江南曾演唱此诗，可证此诗为天宝年间所作。' WHERE poem_title = '相思' AND poem_author = '王维';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '相思' AND p.poem_author = '王维';
VALUES ('杂诗', '王维', '唐代', '君自故乡来，应知故乡事。来日绮窗前，寒梅著花未？', 2);
UPDATE edu_poem SET poem_translation = '您是刚从我们家乡来的，一定了解家乡的人情世态。\n请问您来的时候我家雕画花纹的窗户前，那一株腊梅花开了没有？', poem_notes = '①来日：来的时候。\n②绮(qǐ)窗：雕画花纹的窗户。\n③著花未：开花没有?著（zhuó）花，开花。未，用于句末，相当于“否”，表疑问。' WHERE poem_title = '杂诗' AND poem_author = '王维';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '杂诗' AND p.poem_author = '王维';
VALUES ('鹿柴', '王维', '唐代', '空山不见人，但闻人语响。返景入深林，复照青苔上。', 2);
UPDATE edu_poem SET poem_translation = '空寂的山中不见一个人，只听到一阵人语声。\n太阳的一抹余晖返人深林，又照到林中的青苔上。', poem_notes = '鹿柴（zhài）：王维\n辋川别墅之一（在今陕西省蓝田县西南）。柴：通“寨”、“砦”，用树木围成的栅栏。\n但：只。\n返景（yǐng）：同“返影”，太阳将落时通过云彩反射的阳光。\n复：又。', poem_appreciation = '唐天宝年间，王维在终南山下购置辋川别业。鹿柴是王维在辋川别业的胜景之一。辋川有胜景二十处，王维和他的好友裴迪逐处作诗，编为《辋川集》，这首诗是其中的第五首。' WHERE poem_title = '鹿柴' AND poem_author = '王维';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '鹿柴' AND p.poem_author = '王维';
VALUES ('竹里馆', '王维', '唐代', '独坐幽篁里，弹琴复长啸。深林人不知，明月来相照。', 2);
UPDATE edu_poem SET poem_translation = '独自闲坐幽静竹林，时而弹琴时而长啸。\n密林之中何人知晓我在这里？只有一轮明月静静与我相伴。', poem_notes = '⑴竹里馆：辋川别墅胜景之一，房屋周围有竹林，故名。\n⑵幽篁（huáng）：幽深的竹林。\n⑶啸（xiào）：嘬口发出长而清脆的声音，类似于打口哨。\n⑷深林：指“幽篁”。\n⑸相照：与“独坐”相应，意思是说，左右无人相伴，唯有明月似解人意，偏来相照。\n⑹长啸：撮口而呼，这里指吟咏、歌唱。古代一些超逸之士常用来抒发感情。魏晋名士称吹口哨为啸。', poem_appreciation = '《竹里馆》当作于王维晚年隐居蓝田辋川时期。王维早年信奉佛教，思想超脱，加之仕途坎坷，四十岁以后就过着半官半隐的生活。正如他自己所说：“晚年惟好静，万事不关心。”因而常常独自坐在幽深的竹林之中，弹着古琴以抒寂寞的情怀。诗人是在意兴清幽、心灵澄净的状态下与竹林、明月本身所具有的清幽澄净的属性悠然相会，而命笔成篇的。' WHERE poem_title = '竹里馆' AND poem_author = '王维';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '竹里馆' AND p.poem_author = '王维';
VALUES ('山中送别', '王维', '唐代', '山中相送罢，日暮掩柴扉。春草明年绿，王孙归不归？', 2);
UPDATE edu_poem SET poem_translation = '在深山中送走了好友，夕阳落下把柴门半掩。\n春草到明年催生新绿，朋友啊你能不能回还？', poem_notes = '⑴掩：关闭。柴扉：柴门。\n⑵明年：一作“年年”。\n⑶王孙：贵族的子孙，这里指送别的友人。' WHERE poem_title = '山中送别' AND poem_author = '王维';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '山中送别' AND p.poem_author = '王维';
VALUES ('问刘十九', '白居易', '唐代', '绿蚁新醅酒，红泥小火炉。晚来天欲雪，能饮一杯无？', 2);
UPDATE edu_poem SET poem_translation = '新酿的米酒，色绿香浓；小小红泥炉，烧得殷红。\n天快黑了，大雪将要来。能否共饮一杯？朋友！\n我家新酿的米酒还未过滤，酒面上泛起一层绿泡，香气扑鼻。用红泥烧制成的烫酒用的小火炉也已准备好了。\n天色阴沉，看样子晚上即将要下雪，能否留下与我共饮一杯？', poem_notes = '①刘十九：白居易留下的作中，提到刘十九的不多，仅两首。但提到刘二十八、二十八使君的，就很多了。刘二十八就是刘禹锡。刘十九乃其堂兄刘禹铜，系洛阳一富商，与白居易常有应酬。\n②绿蚁：指浮在新酿的没有过滤的米酒上的绿色泡沫。醅（pēi）：酿造。\n绿蚁新醅酒：酒是新酿的酒。新酿酒未滤清时，酒面浮起酒渣，色微绿，细如蚁，称为“绿蚁”。\n③雪：下雪，这里作动词用。\n④无：表示疑问的语气词，相当于“么”或“吗”。' WHERE poem_title = '问刘十九' AND poem_author = '白居易';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '问刘十九' AND p.poem_author = '白居易';
VALUES ('哥舒歌', '西鄙人', '唐代', '北斗七星高，哥舒夜带刀。至今窥牧马，不敢过临洮。', 2);
UPDATE edu_poem SET poem_translation = '黑夜里北斗七星挂得很高；哥舒翰夜带宝刀勇猛守边。\n至今吐蕃族的牧马只敢远望；他们再不敢南来越过临洮。', poem_notes = '⑴ 窥：窃伺。\n⑵ 临洮：秦筑长城西起于此。\n⑶ 哥舒：指哥舒翰，是唐玄宗的大将，突厥族哥舒部的后裔。' WHERE poem_title = '哥舒歌' AND poem_author = '西鄙人';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '哥舒歌' AND p.poem_author = '西鄙人';
VALUES ('怨情', '李白', '唐代', '美人卷珠帘，深坐颦蛾眉。但见泪痕湿，不知心恨谁。', 2);
UPDATE edu_poem SET poem_translation = '美人卷起珠帘，深闺独坐还皱着蛾眉。\n只见玉颜上泪痕斑斑，不知她心里究竟恨的是谁。', poem_notes = '⑴卷珠帘：意指其卷帘相望。珠帘：珠串的帷帘。\n⑵深坐：长久的坐。颦（pín）：皱眉。蛾眉：蚕蛾触须弯而细长，故以称女子之眉。《\n·硕人》：“螓首蛾眉。”' WHERE poem_title = '怨情' AND poem_author = '李白';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '怨情' AND p.poem_author = '李白';
VALUES ('登乐游原', '李商隐', '唐代', '向晚意不适，驱车登古原。夕阳无限好，只是近黄昏。', 2);
UPDATE edu_poem SET poem_translation = '傍晚时心情不快，驾着车登上古原。\n夕阳啊无限美好，只不过接近黄昏。', poem_notes = '⑴乐游原：在长安（今西安）城南，是唐代长安城内地势最高地。汉宣帝立乐游庙，又名乐游苑。登上它可望长安城。乐游原在秦代属宜春苑的一部分，得名于西汉初年。《汉书·宣帝纪》载，“神爵三年，起乐游苑”。汉宣帝第一个皇后许氏产后死去葬于此，因“苑”与“原”谐音，乐游苑即被传为“乐游原”。对此《关中记》有记载：“宣帝许后葬长安县乐游里，立庙于曲江池北，曰乐游庙，因苑（《长安志》误作葬字）为名。”\n⑵向晚：傍晚。不适：不悦， 不快。\n⑶古原：指乐游原。\n⑷近：快要。', poem_appreciation = '乐游原是唐代游览胜地，直至中晚唐之交，乐游原仍然是京城人游玩的好去处。同时因为地理位置高便于览胜，文人墨客也经常来此做诗抒怀。唐代诗人们在乐游原留下了近百首珠玑绝句，历来为人所称道，诗人李商隐便是其中之一。　　李商隐所处的时代是国运将尽的晚唐，尽管他有抱负，但是无法施展，很不得志。李商隐二十五岁时由令狐楚的儿子令狐绹推举得中进士，不久令狐楚死，他得到王茂之的器重，王将女儿嫁给了他。因为王茂之是李党的重要人物，李商隐从此陷入牛李党争不能自拔，在官场之中异常失意，这首《乐游原》正是他心境郁闷的真实写照。　　程梦星《李义山诗集笺注》：“此诗当作于会昌四、五年（844、845）间，时义山去河阳退居太原，往来京师，过乐游原而作是诗，盖为武宗忧也。武宗英敏特达，略似汉宣，其任德裕为相，克泽潞，取太原，在唐季世可谓有为，故曰‘夕阳无限好’也。而内宠王才人，外筑望仙台，封道士刘玄静为学士，用其术以致身病不复自惜。识者知其不永，故义山忧之，以为‘近黄昏\'也。”' WHERE poem_title = '登乐游原' AND poem_author = '李商隐';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '登乐游原' AND p.poem_author = '李商隐';
VALUES ('听筝', '李端', '唐代', '鸣筝金粟柱，素手玉房前。欲得周郎顾，时时误拂弦。', 2);
UPDATE edu_poem SET poem_translation = '金粟轴的古筝发出优美的声音，那素手拨筝的美人坐在玉房前。\n想尽了办法为博取周郎的青睐，你看她故意地时时拨错了琴弦。', poem_notes = '⑴听筝：弹奏筝曲。\n⑵金粟：古也称桂为金粟，这里当是指弦轴之细而精美。\n⑶柱：定弦调音的短轴。\n⑷素手：指弹筝女子纤细洁白的手。\n⑸玉房：指玉制的筝枕。房，筝上架弦的枕。\n⑹周郎：指三国时吴将周瑜。他二十四岁为大将，时人称其为“周郎”。他精通音乐，听人奏错曲时，即使喝得半醉，也会转过头看一下奏者。当时人称：“曲有误，周郎顾。”\n⑺拂弦：拨动琴弦。' WHERE poem_title = '听筝' AND poem_author = '李端';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '听筝' AND p.poem_author = '李端';
VALUES ('渡汉江', '宋之问', '唐代', '岭外音书断，经冬复历春。近乡情更怯，不敢问来人。', 2);
UPDATE edu_poem SET poem_translation = '流放岭南与亲人断绝了音信，熬过了冬天又经历一个新春。\n越走近故乡心里就越是胆怯，不敢打听从家那边过来的人。', poem_notes = '⑴汉江：汉水。长江最大支流，源出陕西，经湖北流入长江。\n⑵岭外：五岭以南的广东省广大地区，通常称岭南。唐代常作罪臣的流放地。书：信。\n⑶来人：渡汉江时遇到的从家乡来的人。', poem_appreciation = '此诗一说作于宋之问神龙二年（706年）途经汉水时。宋之问媚附武则天的男宠张易之，武氏去世后，唐中宗将其贬为泷州参军。泷州在岭南，唐时，属于极为边远的地区，贬往那里的官员因不适应当地的自然地理条件和生活习俗，往往不能生还。神龙元年（705年）十月宋之问过岭，次年春即冒险逃回洛阳，途经汉江（指襄阳附近的一段汉水）时写下了此诗。　　另一说，此诗是李频由贬所泷州逃归洛阳，途经汉江（指襄阳附近的汉水）时所作。' WHERE poem_title = '渡汉江' AND poem_author = '宋之问';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '渡汉江' AND p.poem_author = '宋之问';
VALUES ('八阵图', '杜甫', '唐代', '功盖三分国，名成八阵图。江流石不转，遗恨失吞吴。', 2);
UPDATE edu_poem SET poem_translation = '三国鼎立你建立了盖世功绩，创八阵图你成就了永久声名。\n江水东流推不转你布阵石头，千古遗恨你灭吴失策功未就。', poem_notes = '⑴八阵图：由八种阵势组成的图形，用来操练军队或作战。\n⑵盖：超过。三分国：指三国时魏、蜀、吴三国。\n⑶石不转：指涨水时，八阵图的石块仍然不动。\n⑷失吞吴：是吞吴失策的意思。', poem_appreciation = '杜甫在唐代宗大历元年（766年）夏迁居夔州，夔州有武侯庙，江边有八阵图，传说为三国时诸葛亮在夔州江滩所设。向来景仰诸葛亮的杜甫用了许多笔墨记咏古迹抒发情怀。《八阵图》便是其中一首。' WHERE poem_title = '八阵图' AND poem_author = '杜甫';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '八阵图' AND p.poem_author = '杜甫';
VALUES ('宿建德江', '孟浩然', '唐代', '移舟泊烟渚，日暮客愁新。野旷天低树，江清月近人。', 2);
UPDATE edu_poem SET poem_translation = '把小船停靠在烟雾迷蒙的小洲，日暮时分新愁又涌上客子心头。\n旷野无边无际远天比树还低沉，江水清清明月来和人相亲相近。', poem_notes = '⑴建德江：指新安江流经建德（今属浙江）西部的一段江水。\n⑵移舟：划动小船。泊：停船靠岸。烟渚（zhǔ）：指江中雾气笼罩的小沙洲。烟：一作“幽”。渚：水中小块陆地。《尔雅·释水》：“水中可居者曰洲，小洲曰渚。”\n⑶客：指作者自己。愁：为思乡而忧思不堪。\n⑷野：原野。旷：空阔远大。天低树：天幕低垂，好像和树木相连。\n⑸月近人：倒映在水中的月亮好像来靠近人。', poem_appreciation = '孟浩然于唐玄宗开元十八年（730年）离乡赴洛阳，再漫游吴越，借以排遣仕途失意的悲愤。《宿建德江》当作于作者漫游吴越时，与《问舟子》是同一时期的作品。' WHERE poem_title = '宿建德江' AND poem_author = '孟浩然';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '宿建德江' AND p.poem_author = '孟浩然';
VALUES ('春晓', '孟浩然', '唐代', '春眠不觉晓，处处闻啼鸟。夜来风雨声，花落知多少。', 2);
UPDATE edu_poem SET poem_translation = '春夜酣睡天亮了也不知道，醒来只听到到处有鸟儿啼叫。\n想起昨夜里风声紧雨声潇潇，花儿不知道被打落了多少？', poem_notes = '⑴不觉晓：不知不觉天就亮了。晓：早晨，天明，天刚亮的时候。\n⑵闻：听见。啼鸟：鸟啼，鸟的啼叫声。\n⑶“夜来”句：一作“欲知昨夜风”。\n⑷“花落”句：一作“花落无多少”。知多少：不知有多少。知：不知，表示推想。' WHERE poem_title = '春晓' AND poem_author = '孟浩然';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '春晓' AND p.poem_author = '孟浩然';
VALUES ('春怨', '金昌绪', '唐代', '打起黄莺儿，莫教枝上啼。啼时惊妾梦，不得到辽西。', 2);
UPDATE edu_poem SET poem_translation = '我敲打树枝，赶走树上的黄莺，不让它在树上乱叫。\n它清脆的叫声，惊醒了我的梦，害得我在梦中不能赶到辽西，与戍守边关的亲人相见。', poem_notes = '①辽西：古郡名，在今辽宁省辽河以西地方。\n②妾：女子的自称。\n③莫：不。' WHERE poem_title = '春怨' AND poem_author = '金昌绪';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '春怨' AND p.poem_author = '金昌绪';
VALUES ('江雪', '柳宗元', '唐代', '千山鸟飞绝，万径人踪灭。孤舟蓑笠翁，独钓寒江雪。', 2);
UPDATE edu_poem SET poem_translation = '所有的山，飞鸟全都断绝；所有的路，不见人影踪迹。\n江上孤舟，渔翁披蓑戴笠；独自垂钓，不怕冰雪侵袭。', poem_notes = '绝：无，没有。\n万径：虚指，指千万条路。\n人踪：人的脚印。\n孤：孤零零。\n蓑笠（suō lì）：蓑衣和斗笠　笠：用竹篾编成的帽子。（“蓑” ，古代用来防雨的衣服；“笠” ，古代用来防雨的帽子。）\n独：独自。', poem_appreciation = '唐顺宗永贞元年，柳宗元参加了王叔文为首的政治革新运动。由于保守势力与宦官的联合反攻，致使革新失败。因此，柳宗元被贬官到有“南荒”之称的永州。他在任所名为司马，实际上是毫无实权而受地方官员监视的“罪犯”。官署里没有他的住处，不得不在和尚庙——龙兴寺的西厢里安身。　　柳宗元自从被贬到永州之后，精神上受到很大刺激和压抑，他就借描写山水景物，借歌咏隐居在山水之间的渔翁，来寄托自己清高而孤傲的情感，抒发自己在政治上失意的郁闷苦恼。于是，他怀着幽愤的心情，写下了这首令人传颂的名诗。' WHERE poem_title = '江雪' AND poem_author = '柳宗元';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '江雪' AND p.poem_author = '柳宗元';
VALUES ('秋夜寄邱员外', '韦应物', '唐代', '怀君属秋夜，散步咏凉天。空山松子落，幽人应未眠。', 2);
UPDATE edu_poem SET poem_translation = '怀念你竟在这深秋的夜晚，散步咏叹多么寒凉的霜天。\n想此刻空山中正掉落松子，幽居的友人一定还未安眠。', poem_notes = '⑴丘二十二员外：名丹，苏州人，曾拜尚书郎，后隐居平山上。一作“邱二十二员外”。\n⑵属：正值，适逢，恰好。\n⑶幽人：幽居隐逸的人，悠闲的人，此处指丘员外。' WHERE poem_title = '秋夜寄邱员外' AND poem_author = '韦应物';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '秋夜寄邱员外' AND p.poem_author = '韦应物';
VALUES ('终南望余雪', '祖咏', '唐代', '终南阴岭秀，积雪浮云端。林表明霁色，城中增暮寒。', 2);
UPDATE edu_poem SET poem_translation = '遥望终南，北山秀丽，皑皑白雪，若浮云间。\n雪后初晴，林梢之间闪烁着夕阳余晖，晚时分，长安城内又添了几分积寒。', poem_notes = '⑴终南：山名，在唐京城长安（今陕西西安）南面六十里处。余雪：指未融化之雪。《全唐\n》此诗题下有小字注：“有司试此题，咏赋四句即纳，或诘之，曰‘意尽’。”\n⑵阴岭：北面的山岭，背向太阳，故曰阴。\n⑶林表：林外\n，林梢。霁（jì）：雨、雪后天气转晴。', poem_appreciation = '这是一首应试诗。《唐诗纪事》记载，祖咏年轻时去长安应考，文题是“终南望余雪”，必须写出一首六韵十二句的五言长律。祖咏看完后思考了一下，写出了四句就搁笔了。他感到这四句已经表达完整，若按照考官要求写成六韵十二句的五言体，则有画蛇添足的感觉。当考官让他重写时，他还是坚持了自己的看法，考官很不高兴。结果祖咏未被录取。' WHERE poem_title = '终南望余雪' AND poem_author = '祖咏';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '终南望余雪' AND p.poem_author = '祖咏';
VALUES ('宫词', '张祜', '唐代', '故国三千里，深宫二十年。一声何满子，双泪落君前。', 2);
UPDATE edu_poem SET poem_translation = '故乡和亲人远在千里之外，我已被幽闭在这深宫里二十年了，听一声曲子《何满子》，忍不住掉下眼泪。', poem_notes = '①故国：故乡。\n②何满子：唐玄宗时著名歌手，据说她因故得罪了皇帝，被推出就刑。就刑前她张口高歌，曲调悲愤，使“苍天白日黯然失色”。结果皇帝闻之，终因惜其技艺难得而降旨缓刑。因为何满子出色的技艺，大人元稹、白居易、杜牧等都相继为之赋诗，其中以张祜的《何满子》宫词：“故国三千里，深宫二十年。一声何满子，双泪落君前”最为感人。这首宫词后来流传甚广，其唱来异常悲怨。据说唐武宗时，有一孟才人，因有感于武宗让其殉情之意，为奄奄一息的武宗唱了一曲《何满子》，唱毕，竟气绝身亡。一作“河满子”，舞曲名。题又作“宫词”。白居易《何满子》诗：“世传满子是人名，临就弄时曲始成。一曲四词歌八叠，从头便是断肠声。”“何满子”声调哀婉。《乐府集》引白居易《何满子》诗的自注说：“何满子，开元中沧州歌者，临弄进此曲以赎死，竟不得免。”\n③君：指皇帝。这里是指唐武宗。据《唐诗纪事》，张祜《宫词》：“传入宫禁，武宗疾笃，目孟才人曰：‘吾即不讯，尔何为哉？’指笙囊泣曰：‘请以此就缢。’上悯然。复曰：‘妾尝艺歌，请对上歌一曲，以泄其愤。’上许。乃歌一声《何满子》，气亟立殒。上令候之，曰：‘脉尚温而肠已绝。’”后来张祜别有咏《孟才人叹》一绝，词云：“偶因歌态咏娇嚬，传唱宫中十二春。却为一声何满子，下泉须吊旧才人。”' WHERE poem_title = '宫词' AND poem_author = '张祜';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '宫词' AND p.poem_author = '张祜';
VALUES ('寻隐者不遇', '贾岛', '唐代', '松下问童子，言师采药去。只在此山中，云深不知处。', 2);
UPDATE edu_poem SET poem_translation = '苍松下，我询问隐者的童子他的师傅到哪里去了？\n他说，师傅已经采药去了。\n还指着高山说，就在这座山中，\n可是林深云密，我也不知道他到底在哪。', poem_notes = '①寻：寻访。\n②隐者：古代指不肯做官而隐居在山野之间的人。\n③不遇：没有见到。\n④童子：小孩。这是指隐者的弟子。\n⑤言：回答,说。\n⑥云深：指山上云雾缭绕。\n⑦处：地方。' WHERE poem_title = '寻隐者不遇' AND poem_author = '贾岛';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '寻隐者不遇' AND p.poem_author = '贾岛';
VALUES ('送崔九', '裴迪', '唐代', '归山深浅去，须尽丘壑美。莫学武陵人，暂游桃源里。', 2);
UPDATE edu_poem SET poem_translation = '你若要归山无论深浅都要去看看；\n山峦沟壑清净秀美要尽情地赏玩。\n千万别学陶渊明笔下那个武陵人，\n只在桃花源游了几天就匆匆出山。', poem_notes = '武陵人：指陶潜《桃花源记》的武陵渔人。' WHERE poem_title = '送崔九' AND poem_author = '裴迪';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '送崔九' AND p.poem_author = '裴迪';
VALUES ('送灵澈上人', '刘长卿', '唐代', '苍苍竹林寺，杳杳钟声晚。荷笠带斜阳，青山独归远。', 2);
UPDATE edu_poem SET poem_translation = '青苍的竹林寺，近晚时传来深远的钟声。\n背着斗笠披着斜阳，独回青山渐行渐远。', poem_notes = '⑴灵澈上人：唐代著名僧人，本姓杨，字源澄，会稽（今浙江绍兴）人，后为云门寺僧。上人，对僧人的敬称。\n⑵苍苍：深青色。竹林寺：在现在江苏丹徒南。\n⑶杳（yǎo）杳：深远的样子。\n⑷荷（hè）笠：背着斗笠。荷，背着。' WHERE poem_title = '送灵澈上人' AND poem_author = '刘长卿';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '送灵澈上人' AND p.poem_author = '刘长卿';
VALUES ('听弹琴', '刘长卿', '唐代', '泠泠七弦上，静听松风寒。古调虽自爱，今人多不弹。', 2);
UPDATE edu_poem SET poem_translation = '七弦琴奏出清凉的曲调悠扬起伏，细细倾听就像那滚滚的松涛声。\n我虽然很喜爱这首古时的曲调，但在今天人们大多已不去弹奏了。', poem_notes = '⑴泠（líng）泠：形容清凉、清淡，也形容声音清越。丝：一作“弦”。\n⑵松风：以风入松林暗示琴声凄凉。琴曲中有《风入松》的调名。\n⑶古调：古时的曲调。' WHERE poem_title = '听弹琴' AND poem_author = '刘长卿';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '听弹琴' AND p.poem_author = '刘长卿';
VALUES ('送上人', '刘长卿', '唐代', '孤云将野鹤，岂向人间住。莫买沃洲山，时人已知处。', 2);
UPDATE edu_poem SET poem_translation = '孤云陪伴着野鹤，怎么能在人间居住。不要买下沃洲山，现在已经有人知道那儿了。\n你是行僧象孤云和野鹤，怎能在人世间栖居住宿？\n要归隐请别买沃洲名山，那里是世人早知的去处。', poem_notes = '上人：对 僧人的敬称。\n孤云、野鹤：都用来比喻方外上人。将：与共。\n沃洲山：在浙江新昌县东，上有支遁岭，放鹤峰、养马坡，相传为晋代名僧支遁放鹤、养马之地。时人：指时俗之人。\n将：伴随。' WHERE poem_title = '送上人' AND poem_author = '刘长卿';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '送上人' AND p.poem_author = '刘长卿';
VALUES ('玉台体', '权德舆', '唐代', '昨夜裙带解，今朝蟢子飞。铅华不可弃，莫是藁砧归。', 2);
UPDATE edu_poem SET poem_translation = '昨晚我裙带忽然松弛解开，早晨又看见蟢子双双飞来。\n要赶紧描眉擦粉梳妆打扮，莫非是我的丈夫快要回来。', poem_notes = '（1）蟢子：小蜘蛛脚长者，俗称蟢子。\n（2）铅华：指脂粉。\n（3）藁砧：丈夫的隐语。' WHERE poem_title = '玉台体' AND poem_author = '权德舆';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '玉台体' AND p.poem_author = '权德舆';
VALUES ('芙蓉楼送辛渐', '王昌龄', '唐代', '寒雨连江夜入吴，平明送客楚山孤。洛阳亲友如相问，一片冰心在玉壶。', 2);
UPDATE edu_poem SET poem_translation = '迷蒙的烟雨，连夜洒遍吴地江天；清晨送走你，孤对楚山离愁无限！\n朋友啊，洛阳亲友若是问起我来；就说我依然冰心玉壶，坚守信念！', poem_notes = '1.芙蓉楼：原名西北楼，在润州（今江苏省镇江市）西北。登临可以俯瞰长江，遥望江北。据《元和郡县志》卷二十六《江南道·润州》丹阳：“晋王恭为刺史，改创西南楼名万岁楼，西北楼名芙蓉楼。”丹阳在今江苏省西南部，东北滨长江，大运河斜贯，属镇江市。辛渐：人的一位朋友。\n2.寒雨：秋冬时节的冷雨。连江：雨水与江面连成一片，形容雨很大。吴：古代国名，这里泛指江苏南部、浙江北部一带。江苏镇江一带为三国时吴国所属。\n3.平明：天亮的时候。客：指作者的好友辛渐。楚山：楚地的山。这里的楚也指南京一带，因为古代吴、楚先后统治过这里，所以吴、楚可以通称。孤：独自，孤单一人。\n4.洛阳：现位于河南省西部、黄河南岸。\n5.冰心，比喻纯洁的心。玉壶，道教概念妙真道教义，专指自然无为虚无之心。', poem_appreciation = '此诗当作于天宝元年（742年），王昌龄当时为江宁（今江苏南京）丞。辛渐是王昌龄的朋友，这次拟由润州渡江，取道扬州，北上洛阳。王昌龄可能陪他从江宁到润州（今江苏镇江），然后在此分手。此诗原题共两首，第二首说到头天晚上诗人在芙蓉楼为辛渐饯别，这一首写的是第二天早晨在江边离别的情景。' WHERE poem_title = '芙蓉楼送辛渐' AND poem_author = '王昌龄';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '芙蓉楼送辛渐' AND p.poem_author = '王昌龄';
VALUES ('闺怨', '王昌龄', '唐代', '闺中少妇不知愁，春日凝妆上翠楼。忽见陌头杨柳色，悔教夫婿觅封侯。', 2);
UPDATE edu_poem SET poem_translation = '译文一\n闺中少妇未曾有过相思离别之愁，在明媚的春日，她精心妆饰，登上高楼。忽然看到路边的杨柳春色，惆怅之情涌上心头。她后悔当初不该让丈夫从军边塞，建功封侯。\n译文二\n闺阁中的少妇，从来不知忧愁；\n春来细心打扮，独自登上翠楼。\n忽见陌头杨柳新绿，心里难受；\n呵，悔不该叫夫君去觅取封侯。', poem_notes = '1.闺怨：少妇的幽怨。闺，女子卧室，借指女子。一般指少女或少妇。古人“闺怨“之作，一般是写少女的青春寂寞，或少妇的离别相思之情。以此题材写的称“闺怨诗”。\n2.“不知愁“一作“不曾愁“，则诗意大减。\n3. 凝妆：盛妆。\n4.陌头：路边。\n5.觅封侯：为求得封侯而从军。觅，寻求。\n6.悔教：后悔让' WHERE poem_title = '闺怨' AND poem_author = '王昌龄';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '闺怨' AND p.poem_author = '王昌龄';
VALUES ('春宫曲', '王昌龄', '唐代', '昨夜风开露井桃，未央前殿月轮高。 平阳歌舞新承宠，帘外春寒赐锦袍。', 2);
UPDATE edu_poem SET poem_translation = '昨夜的春风吹开了露井边的桃花，未央宫前的明月高高地挂在天上。\n平阳公主家的歌女新受武帝宠幸，见帘外略有春寒皇上特把锦袍赐给她。', poem_notes = '⑴春宫曲：一作“殿前曲”。\n⑵露井：指没有井亭覆盖的井。\n⑶未央：即未央宫​，汉宫殿名，汉高祖刘邦所建。也指唐宫。\n⑷平阳歌舞：平阳公主​家中的歌女。新承：一作“承新”。' WHERE poem_title = '春宫曲' AND poem_author = '王昌龄';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '春宫曲' AND p.poem_author = '王昌龄';
VALUES ('九月九日忆山东兄弟', '王维', '唐代', '独在异乡为异客，每逢佳节倍思亲。遥知兄弟登高处，遍插茱萸少一人。', 2);
UPDATE edu_poem SET poem_translation = '独自远离家乡难免总有一点凄凉，每到重阳佳节倍加思念远方的亲人。\n远远想到兄弟们身佩茱萸登上高处，也会因为少我一人而生遗憾之情。', poem_notes = '⑴九月九日：即重阳节。古以九为阳数，故曰重阳。忆：想念。山东：王维迁居于蒲县（今山西永济县），在函谷关与华山以东，所以称山东。\n⑵异乡：他乡、外乡。 为异客：作他乡的客人。\n⑶佳节：美好的节日。\n⑷登高：古有重阳节登高的风俗。\n⑸茱萸（zhūyú）：一种香草，即草决明。古时人们认为重阳节插戴茱萸可以避灾克邪。', poem_appreciation = '此诗原注：“时年十七。”说明这是王维十七时的作品。王维当时独自一人漂泊在洛阳与长安之间，他是蒲州（今山西永济）人，蒲州在华山东面，所以称故乡的兄弟为山东兄弟。九月九日是重阳节，中国有些地方有登高的习俗。《太平御览》卷三十二引《风土记》云：“俗于此日，以茱萸气烈成熟，尚此日，折萸房以插头，言辟热气而御初寒。”' WHERE poem_title = '九月九日忆山东兄弟' AND poem_author = '王维';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '九月九日忆山东兄弟' AND p.poem_author = '王维';
VALUES ('凉州词', '王翰', '唐代', '葡萄美酒夜光杯，欲饮琵琶马上催。醉卧沙场君莫笑，古来征战几人回？', 2);
UPDATE edu_poem SET poem_translation = '酒筵上甘醇的葡萄美酒盛满在精美的夜光杯之中，歌伎们弹奏起急促欢快的琵琶声助兴催饮，想到即将跨马奔赴沙场杀敌报国，战士们个个豪情满怀。\n今日一定要一醉方休，即使醉倒在战场上又何妨？此次出征为国效力，本来就打算马革裹尸，没有准备活着回来。', poem_notes = '1.凉州词：唐乐府名，属《近代曲辞》，是《凉州曲》的唱词，盛唐时流行的一种曲调名。凉州词：王翰写有《凉州词》两首，慷慨悲壮，广为流传。而这首《凉州词》被明代王世贞推为唐代七绝的压卷之作。\n2.夜光杯：用白玉制成的酒杯，光可照明，这里指华贵而精美的酒杯。据《海内十洲记》所载，为周穆王时西胡所献之宝。\n3.欲：将要。\n4.琵琶：这里指作战时用来发出号角的声音时用的。\n5.催：催人出征；也有人解作鸣奏助兴。\n6.沙场：平坦空旷的沙地，古时多指战场。\n7.君：你。\n8.征战：打仗。' WHERE poem_title = '凉州词' AND poem_author = '王翰';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '凉州词' AND p.poem_author = '王翰';
VALUES ('后宫词', '白居易', '唐代', '泪湿罗巾梦不成，夜深前殿按歌声。 红颜未老恩先断，斜倚薰笼坐到明。', 2);
UPDATE edu_poem SET poem_translation = '泪水湿透了罗巾无法入睡好梦难成，深夜时分听到前殿传来按着节拍唱歌的声音。红颜尚未老去已经失去了君王的恩宠，斜靠着熏笼一直坐到天明。\n泪水湿透罗巾，好梦却难做成；\n深夜，前殿传来有节奏的歌声。\n红颜尚未衰减，恩宠却已断绝；\n她独倚着熏笼，一直坐到天明。', poem_notes = '1，宫词：此题又作《后宫词》。\n2，按歌声：依照歌声的韵律打拍子。\n3，红颜：此指宫宫女。\n4，恩：君恩。\n5，熏笼：覆罩香炉的竹笼。香炉用来熏衣被，为宫中用物。', poem_appreciation = '诗的主人公是一位不幸的宫女。她一心盼望君王的临幸而终未盼得，时已深夜，只好上床，已是一层怨怅。宠幸不可得，退而求之好梦；辗转反侧，竟连梦也难成，见出两层怨怅。梦既不成，索性揽衣推枕，挣扎坐起。正当她愁苦难忍，泪湿罗巾之时，前殿又传来阵阵笙歌，原来君王正在那边寻欢作乐，这就有了三层怨怅。倘使人老珠黄，犹可解说；　　偏偏她盛鬓堆鸦，红颜未老，生出四层怨怅。要是君王一直没有发现她，那也罢了；事实是她曾受过君王的恩宠，而现在这种恩宠却无端断绝，见出五层怨怅。夜已深沉，濒于绝望，但一转念，犹翼君王在听歌赏舞之后，会记起她来。于是，斜倚熏笼，浓熏翠袖，以待召幸。不料，一直坐到天明，幻想终归破灭，见出六层怨怅。一种情思，六层写来，尽缠绵往复之能事。而全诗却一气浑成，如笋破土，苞节虽在而不露；　　如茧抽丝，幽怨似缕而不绝。短短四句，细腻地表现了一个失宠宫女复杂矛盾的内心世界。夜来不寐，等候君王临幸，写其希望；听到前殿歌声，君王正在寻欢作乐，写其失望；君恩已断，仍斜倚熏笼坐等，写其苦望；天色大明，君王未来，写其绝望。泪湿罗巾，写宫女的现实；求宠于梦境，写其幻想；恩断而仍坐等，写其痴想；坐到天明仍不见君王，再写其可悲的现实。全诗由希望转到失望，由失望转到苦望，由苦望转到最后绝望；由现实进入幻想，由幻想进入痴想，由痴想再跌入现实，千回百转，倾注了诗人对不幸者的深挚同情。' WHERE poem_title = '后宫词' AND poem_author = '白居易';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '后宫词' AND p.poem_author = '白居易';
VALUES ('宫中词', '朱庆馀', '唐代', '寂寂花时闭院门，美人相并立琼轩。 含情欲说宫中事，鹦鹉前头不敢言。', 2);
UPDATE edu_poem SET poem_translation = '百花盛开，宫院却寂寂地紧闭大门；\n俏丽宫女，相依相并伫立廊下赏春。\n满怀幽情，都想谈谈宫中忧愁的事，\n鹦鹉面前，谁也不敢吐露自己苦闷。', poem_notes = '琼轩：对廊台的美称。' WHERE poem_title = '宫中词' AND poem_author = '朱庆馀';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '宫中词' AND p.poem_author = '朱庆馀';
VALUES ('近试上张水部', '朱庆馀', '唐代', '洞房昨夜停红烛，待晓堂前拜舅姑。 妆罢低声问夫婿，画眉深浅入时无。', 2);
UPDATE edu_poem SET poem_translation = '洞房里昨夜花烛彻夜通明，等待拂晓拜公婆讨个好评。\n打扮好了轻轻问丈夫一声：我的眉画得浓淡可合时兴？', poem_notes = '⑴张水部：即张籍，曾任水部员外郎。\n⑵洞房：新婚卧室。停红烛：让红烛通宵点着。停：留置。\n⑶舅姑：公婆。\n⑷深浅：浓淡。入时无：是否时髦。这里借喻文章是否合适。', poem_appreciation = '此诗为宝历（唐敬宗年号，825—827）年间朱庆馀参加进士考试前夕所作。唐代士子在参加进士考试前，时兴“行卷”，即把自己的诗篇呈给名人，以希求其称扬和介绍于主持考试的礼部侍郎。朱庆馀此诗投赠的对象，是时任水部郎中的张籍。张籍当时以擅长文学而又乐于提拔后进与韩愈齐名。朱庆馀平日向他行卷，已经得到他的赏识，临到要考试了，还怕自己的作品不一定符合主考的要求，因此写下此诗，看看是否投合主考官的心意。此诗便是行卷之作。' WHERE poem_title = '近试上张水部' AND poem_author = '朱庆馀';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '近试上张水部' AND p.poem_author = '朱庆馀';
VALUES ('逢入京使', '岑参', '唐代', '故园东望路漫漫，双袖龙钟泪不干。 马上相逢无纸笔，凭君传语报平安。', 2);
UPDATE edu_poem SET poem_translation = '东望家乡路程又远又长，热泪湿双袖还不断流淌。\n在马上与你相遇无纸笔，请告家人说我平安无恙。', poem_notes = '⑴入京使：进京的使者。\n⑵故园：指长安和自己在长安的家。漫漫：形容路途十分遥远。\n⑶龙钟：涕泪淋漓的样子。卞和《退怨之歌》：“空山歔欷泪龙钟。”这里是沾湿的意思。\n⑷凭：托，烦，请。传语：捎口信。', poem_appreciation = '根据刘开扬《岑参诗集编年笺注·岑参年谱》，此诗作于公元749年（天宝八载）诗人赴安西（今新疆维吾尔自治区库车县）上任途中。这是岑参第一次远赴西域，充安西节度使高仙芝幕府书记。此时诗人34岁，前半生功名不如意，无奈之下，出塞任职。他告别了在长安的妻子，跃马踏上漫漫征途，西出阳关，奔赴安西。　　岑参也不知走了多少天，就在通西域的大路上，他忽地迎面碰见一个老相识。立马而谈，互叙寒温，知道对方要返京述职，不免有些感伤，同时想到请他捎封家信回长安去安慰家人，报个平安。此诗就描写了这一情景。' WHERE poem_title = '逢入京使' AND poem_author = '岑参';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '逢入京使' AND p.poem_author = '岑参';
VALUES ('黄鹤楼送孟浩然之广陵', '李白', '唐代', '故人西辞黄鹤楼，烟花三月下扬州。孤帆远影碧空尽，唯见长江天际流。', 2);
UPDATE edu_poem SET poem_translation = '老朋友向我频频挥手，告别了黄鹤楼，在这柳絮如烟、繁花似锦的阳春三月去扬州远游。\n友人的孤船帆影渐渐地远去，消失在碧空的尽头，只看见一线长江，向邈远的天际奔流。', poem_notes = '⑴黄鹤楼：中国著名的名胜古迹，故址在今湖北武汉市武昌蛇山的黄鹄矶上，属于长江下游地带，传说三国时期的费祎于此登仙乘黄鹤而去，故称黄鹤楼。原楼已毁，现存楼为1985年修葺。孟浩然\n：李白\n的朋友。之：往、到达。广陵：即扬州。\n⑵故人：老朋友，这里指孟浩然。其年龄比李白大，在\n坛上享有盛名。李白对他很敬佩，彼此感情深厚，因此称之为“故人”。辞：辞别。\n⑶烟花：形容柳絮如烟、鲜花似锦的春天景物，指艳丽的春景。下：顺流向下而行。\n⑷碧空尽：消失在碧蓝的天际。尽：尽头，消失了。碧空：一作“碧山”。\n⑸唯见：只看见。天际流：流向天边 天际：天边，天边的尽头。', poem_appreciation = '《黄鹤楼送孟浩然之广陵》是李白出蜀壮游期间的作品。李白是一位热爱自然、喜欢交友的诗人，他“一生好入名山游”，在漫游和飘泊中走完了自己的一生，足迹遍布中原内外，留下了许多歌咏自然美、歌颂友情的作品。　　唐玄宗开元十五年（727年），李白东游归来，至湖北安陆，年已二十七岁。他在安陆住了有十年之久，不过很多时候都是以诗酒会友，在外游历，用他自己的话说就是“酒隐安陆，蹉跎十年”。也就是寓居安陆期间，李白结识了长他十二岁的孟浩然。孟浩然对李白非常赞赏，两人很快成了挚友。开元十八年（730年）三月，李白得知孟浩然要去广陵（今江苏扬州），便托人带信，约孟浩然在江夏（今武汉市武昌区）相会。几天后，孟浩然乘船东下，李白亲自送到江边。送别时写下了这首《黄鹤楼送孟浩然之广陵》。' WHERE poem_title = '黄鹤楼送孟浩然之广陵' AND poem_author = '李白';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '黄鹤楼送孟浩然之广陵' AND p.poem_author = '李白';
VALUES ('早发白帝城', '李白', '唐代', '朝辞白帝彩云间，千里江陵一日还。两岸猿声啼不住，轻舟已过万重山。', 2);
UPDATE edu_poem SET poem_translation = '清晨，朝霞满天，我就要踏上归程。从江上往高处看，可以看见白帝城彩云缭绕，如在云间，景色绚丽！千里之遥的江陵，一天之间就已经到达。\n两岸猿猴的啼声不断，回荡不绝。猿猴的啼声还回荡在耳边时，轻快的小船已驶过连绵不绝的万重山峦。\n译文二\n清晨，我告别高入云霄的白帝城江陵远在千里，船行只一日时间。\n两岸猿声，还在耳边不停地啼叫不知不觉，轻舟已穿过万重青山。', poem_notes = '⑴发：启程。白帝城：故址在今重庆市奉节县白帝山上。杨齐贤注：“白帝城，公孙述所筑。初，公孙述至鱼复，有白龙出井中，自以承汉土运，故称白帝，改鱼复为白帝城。”王琦注：“白帝城，在夔州奉节县，与巫山相近。所谓彩云，正指巫山之云也。”\n⑵朝：早晨。辞：告别。彩云间：因白帝城在白帝山上，地势高耸，从山下江中仰望，仿佛耸入云间。\n⑶江陵：今湖北荆州市。从白帝城到江陵约一千二百里，其间包括七百里三峡。郦道元\n《三峡》：“自三峡七百里中，两岸连山，略无阙处。重岩叠障，隐天蔽日，自非亭午时分，不见曦月。至于夏水襄陵，沿溯（或泝）阻绝。或王命急宣，有时朝发白帝，暮到江陵，其间千二百时里，虽乘奔御风，不以疾也。春冬之时，则素湍绿潭，回清倒影。绝巘（或巚）多生怪柏，悬泉瀑布，飞漱其间。清荣峻茂，良多趣味。每至晴初霜旦，林寒涧肃，常有高猿长啸，属引凄异。空谷传响，哀啭久绝。故渔者歌曰：‘巴东三峡巫峡长，猿鸣三声泪沾裳。’”还：归；返回。\n⑷猿：猿猴。啼：鸣、叫。住：停息。\n⑸万重山：层层叠叠的山，形容有许多。', poem_appreciation = '唐肃宗乾元二年（759年）春天，李白因永王李璘案，流放夜郎，取道四川赶赴被贬谪的地方。行至白帝城的时候，忽然收到赦免的消息，惊喜交加，随即乘舟东下江陵。此诗即回舟抵江陵时所作，所以诗题一作《下江陵》。　　前人曾认为这首诗是李白青年出蜀时所作。然而根据“千里江陵一日还”的诗意，李白曾从江陵上三峡，因此，这首诗应当是他返还时所作。' WHERE poem_title = '早发白帝城' AND poem_author = '李白';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '早发白帝城' AND p.poem_author = '李白';
VALUES ('夜上受降城闻笛', '李益', '唐代', '回乐峰前沙似雪，受降城外月如霜。不知何处吹芦管，一夜征人尽望乡。', 2);
UPDATE edu_poem SET poem_translation = '回乐峰前的沙地白得像雪，受降城外的月色有如秋霜。\n不知何处吹起凄凉的芦管，一夜间征人个个眺望故乡。', poem_notes = '⑴受降城：唐初名将张仁愿​为了防御突厥，在黄河以北筑受降城，分东、中、西三城，都在今内蒙古自治区境内。另有一种说法是：公元646年（贞观二十年），唐太宗亲临灵州接受突厥一部的投降,“受降城”之名即由此而来。\n⑵回乐峰：唐代有回乐县​，灵州治所，在今宁夏回族自治区灵武县西南。回乐峰即当地山峰。一作“回乐烽”：指回乐县附近的烽火台。\n⑶城下：一作“城上”，一作“城外”。\n⑷芦管：笛子。一作“芦笛”。\n⑸征人：戍边的将士。尽：全。' WHERE poem_title = '夜上受降城闻笛' AND poem_author = '李益';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '夜上受降城闻笛' AND p.poem_author = '李益';
VALUES ('贾生', '李商隐', '唐代', '宣室求贤访逐臣，贾生才调更无伦。可怜夜半虚前席，不问苍生问鬼神。', 2);
UPDATE edu_poem SET poem_translation = '汉文帝在宣室求问被贬谪的贤臣，贾谊的才华和格调更是无可比伦。\n谈至深夜汉文帝挪动双膝靠近他，可惜他不关心百姓只是关心鬼神。', poem_notes = '(1)贾生：指贾谊（前200—前168），西汉著名的政论家、文学家，力主改革弊政，提出了许多重要政治主张，但却遭谗被贬，一生抑郁不得志。\n(2)宣室：汉代长安城中未央宫前殿的正室。\n(3)逐臣：被放逐之臣，指贾谊曾被贬谪。\n(4)才调：才华气质。\n(5)可怜：可惜，可叹。\n(6)虚：徒然，空自。\n(7)前席：在坐席上移膝靠近对方。\n(8)苍生：百姓。\n(9)问鬼神：事见《史记·屈原贾生列传》。汉文帝接见贾谊，“问鬼神之本。贾生因具道所以然之状。至夜半，文帝前席。”', poem_appreciation = '关于本诗的写作年代，有两种说法。其一为冯浩在《玉溪生诗集笺注》中所言，“此盖至昭州修祀事，故以借慨”，意谓此诗为李商隐在大中二年（848年）正月受桂州刺史郑亚之命，赴昭州任郡守时所作。因李商隐时为一郡之长，故须主奉祭祀大事，于是借题发挥，创作了本诗。另一说为杨柳提出，认为此诗当于大中二年三、四月间李商隐离开桂林北上后滞留荆巴时期所作。(见《李商隐评传》）　　这首诗的作者李商隐生活在唐王朝日趋衰败的晚唐时期，他对皇帝昏庸、宦官当权与藩镇跋扈深为不满。而且李商隐被卷入了牛李党争，屡受排挤，怀才不遇。于是他借吊贾谊来抒发自己的感慨，通过讽刺汉文帝虽能求贤却又不知贤的行为，反映了晚唐的社会现实——即晚唐帝王也像文帝一般，表似开明，实则昏聩无能。' WHERE poem_title = '贾生' AND poem_author = '李商隐';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '贾生' AND p.poem_author = '李商隐';
VALUES ('隋宫', '李商隐', '唐代', '乘兴南游不戒严，九重谁省谏书函。 春风举国裁宫锦，半作障泥半作帆。', 2);
UPDATE edu_poem SET poem_translation = '隋炀帝为南游江都不顾安全，\n九重宫中有谁理会劝谏书函。\n春游中全国裁制的绫罗锦缎，\n一半作御马障泥一半作船帆。', poem_notes = '①.张《笺》编此\n于大中十一年（857），时商隐因柳仲郢推荐，任盐铁推官，游江东。隋宫：隋炀帝杨广\n建造的行宫。《舆地纪胜》：“淮南东路，扬州江都宫，炀帝于江都郡置宫，号江都宫。“《嘉庆一统志》：“江苏省扬州府古迹：临江宫在江都县南二十里，隋大业七年，炀帝升钓台临扬子津，大燕百僚，寻建临江宫于此。显福宫在甘泉县东北，隋城外离宫。……江都宫在甘泉县西七里，故广陵城内。中有成象殿，水精殿及流珠堂，皆隋炀帝建。……十宫在甘泉县北五里，隋炀帝建。《寰宇记》：十宫在江都县北五里，长阜苑内，依林傍涧，高跨冈阜，随城形置焉。曰归雁、回流、九里、松林、枫林、大雷、小雷、春草、九华、光汾。“\n②.乘兴句：《晋书·舆服志》：“凡车驾亲戎，中外戒严。“此言不戒严，意谓炀帝骄横无忌，毫无戒备。\n③.九重：指皇帝居住的深宫。省：明察，懂得。谏书函：给皇帝的谏书。《隋书·炀帝纪》载：隋炀帝巡游，大臣上表劝谏者皆斩之，遂无人敢谏。大业十四年（618），在行宫里被其部下宇文化及所杀。\n④.宫锦：供皇家使用的高级锦缎。\n⑤.障泥：马鞯，垫在马鞍的下面，两边下垂至马蹬，用来挡泥土。《隋书·食货志》：“大业元年，造龙舟，凤榻、黄龙、赤舰、楼船、篾舫……幸江都……舳舻相接，二百余里' WHERE poem_title = '隋宫' AND poem_author = '李商隐';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '隋宫' AND p.poem_author = '李商隐';
VALUES ('瑶池', '李商隐', '唐代', '瑶池阿母绮窗开，黄竹歌声动地哀。 八骏日行三万里，穆王何事不重来。', 2);
UPDATE edu_poem SET poem_translation = '韵义\n西王母在瑶池上把绮窗打开；\n只听得黄竹歌声音动地悲哀。\n八骏神马的车子日行三万里；\n周穆王为了何事违约不再来？', poem_notes = '1、瑶池阿母：《穆天子传》卷三：“天子宾于西王母，天子觞西王母于瑶池之上。西王母为天子谣曰：‘白云在天，山陵自出。道里悠远，山川间之。将子无死，尚能复来。’天子答之曰：‘予归东土，和治诸夏。万民平均，吾顾见汝。比及三年，将复而野。’”《武帝内传》称王母为“玄都阿母”。\n2、黄竹歌声：《穆天子传》卷五：“日中大寒，北风雨雪，有冻人。天子作三章以哀民。”\n3、八骏：传说周穆王有八匹骏马，可日行三万里。《列子》、《穆天子传》等记载不一。\n4、穆王：西周人，姓姬名满，传说他曾周游天下。\n此诗讽刺求仙之虚妄。首句写西王母倚窗伫望，候穆王而不至。次句借黄竹歌声暗示穆王已死。三四句则写西王母因穆王不来而心生疑问。斥神仙而以神仙（王母）的口气写出，句句对比，以见长生之虚妄，求仙之荒诞。《李义山诗集笺注》引程梦星曰：“此追叹武宗之崩也。武宗好仙，又好游猎，又宠王才人。此诗熔铸其事而出之，只用穆王一事，足概武宗三端。用思最深，措辞最巧。”' WHERE poem_title = '瑶池' AND poem_author = '李商隐';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '瑶池' AND p.poem_author = '李商隐';
VALUES ('嫦娥', '李商隐', '唐代', '云母屏风烛影深，长河渐落晓星沉。嫦娥应悔偷灵药，碧海青天夜夜心。', 2);
UPDATE edu_poem SET poem_translation = '透过装饰着云母的屏风，烛影渐渐暗淡下去。银河也在静静地消失，晨星沉没在黎明的曙光里。\n月宫的嫦娥恐怕后悔偷了后羿的长生不老药，现在只有那青天碧海夜夜陪伴着她一颗孤独的心。\n云母屏风染上一层浓浓的烛影，银河逐渐斜落启明星也已下沉。\n嫦娥想必悔恨当初偷吃下灵药，如今独处碧海青天而夜夜寒心。', poem_notes = '1．嫦娥：古代神话中的月中仙女，江苏人。《淮南子·览冥训》：“羿请不死之药于西王母，恒娥窃以奔月。”恒又作姮。\n2．云母屏风：嵌着云母石的屏风。此言嫦娥在月宫居室中独处，夜晚，唯烛影和屏风相伴。\n3．长河句：银河逐渐向西倾斜，晓星也将隐没，又一个孤独的夜过去了。\n4．碧海：《十洲记》：“扶桑在东海之东岸，岸直，陆行登岸一万里，东复有碧海，海阔狭浩汗，与东海等，水既不咸苦，正作碧色。”', poem_appreciation = '诗作创作背景，永远离不开作者本人的政治生活背景：作者终身处于牛李党争的夹缝之中，一生很不得志。牛李党争是在宦官专权的日子里，唐朝朝廷的官员中反对宦官的大都遭到排挤打击。依附宦官的又分为两派——以牛僧孺为首领的牛党和以李德裕为首领的李党，这两派官员互相倾轧，争吵不休，从唐宪宗时期（805年）开始，到唐宣宗时期（846年）才结束，闹了将近40年，历史上把这次朋党之争称为“牛李党争”。牛李党争的实质就是太监当权，本诗就是讽刺太监当权的黑暗、讽刺宪宗的皇权旁落。子曰：“邦有道，则仕；邦无道，则可卷而怀之。”《嫦娥》即是“邦无道，则可卷而怀之”这类诗的典型。' WHERE poem_title = '嫦娥' AND poem_author = '李商隐';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '嫦娥' AND p.poem_author = '李商隐';
VALUES ('夜雨寄北', '李商隐', '唐代', '君问归期未有期，巴山夜雨涨秋池。 何当共剪西窗烛，却话巴山夜雨时。', 2);
UPDATE edu_poem SET poem_translation = '您问归期，归期实难说准，巴山连夜暴雨，涨满秋池。\n何时归去，共剪西窗烛花，当面诉说，巴山夜雨况味。', poem_notes = '1.寄北：写\n寄给北方的人。诗人当时在巴蜀（现在四川省），他的亲友在长安，所以说“寄北”。这首诗表达了诗人对亲友的深刻怀念。\n2.君：对对方的尊称，等于现代汉语中的“您”。\n3.归期：指回家的日期。\n4.巴山：指大巴山，在陕西南部和四川东北交界处。这里泛指巴蜀一带。\n5.秋池：秋天的池塘。\n6.何当：什么时候。\n7.共：副词，用在谓语前，表示动作行为是由两个或几个施事者共同发生的。可译为“一起”。\n8.剪西窗烛：剪烛，剪去燃焦的烛芯，使灯光明亮。这里形容深夜秉烛长谈。“西窗话雨”“西窗剪烛”用作成语，所指也不限于夫妇，有时也用以写朋友间的思念之情。\n9.却话：回头说，追述。', poem_appreciation = '这首诗选自《玉溪生诗》卷三，是李商隐留滞巴蜀（今四川省）时寄怀长安亲友之作。因为长安在巴蜀之北，故题作《夜雨寄北》。　　在南宋洪迈编的《万首唐人绝句》里，这首诗的题目为《夜雨寄内》，意思是诗是寄给妻子的。他们认为，李商隐于大中五年（851）七月赴东川节度使柳仲郢梓州幕府，而王氏是在这一年的夏秋之交病故，李商隐过了几个月才得知妻子的死讯。　　现传李诗各本题作《夜雨寄北》，“北”就是北方的人，可以指妻子，也可以指朋友。有人经过考证认为它作于作者的妻子王氏去世之后，因而不是“寄内”诗，而是写赠长安友人的。　　就诗的内容看，按“寄内”解，便情思委曲，悱恻缠绵；作“寄北”看，便嫌细腻恬淡，未免纤弱。' WHERE poem_title = '夜雨寄北' AND poem_author = '李商隐';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '夜雨寄北' AND p.poem_author = '李商隐';
VALUES ('寄令狐郎中', '李商隐', '唐代', '嵩云秦树久离居，双鲤迢迢一纸书。 休问梁园旧宾客，茂陵秋雨病相如。', 2);
UPDATE edu_poem SET poem_translation = '你是嵩山云我是秦川树，长久离居；\n千里迢迢，你寄来一封慰问的书信。\n请别问我这个梁园旧客生活的甘苦；\n我就像茂陵秋雨中多病的司马相如。', poem_notes = '⑴嵩：中岳嵩山，在今河南。\n⑵双鲤：指书信。\n⑶梁园：梁孝王在梁地大兴土木，以睢阳为中心，根据自然景色，修建了一个很大的花园，称东苑，也叫菟园，后人称为梁园。\n⑷茂陵：今陕西兴平县东北，以汉武帝陵墓而得名。' WHERE poem_title = '寄令狐郎中' AND poem_author = '李商隐';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '寄令狐郎中' AND p.poem_author = '李商隐';
VALUES ('为有', '李商隐', '唐代', '为有云屏无限娇，凤城寒尽怕春宵。 无端嫁得金龟婿，辜负香衾事早朝。', 2);
UPDATE edu_poem SET poem_translation = '云母屏风后面的美人格外娇，京城寒冬已过却怕短暂春宵。\n无端地嫁了个做高官的丈夫，不恋温暖香衾只想去上早朝。', poem_notes = '⑴云屏：雕饰着云母图案的屏风，古代皇家或富贵人家所用。\n⑵凤城：此指京城。\n⑶无端：没来由。金龟婿：佩带金龟（即作官）的丈夫。《新唐书·车服志》：“天授二年，改佩鱼皆为龟，其后三品以上龟袋饰以金。”' WHERE poem_title = '为有' AND poem_author = '李商隐';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '为有' AND p.poem_author = '李商隐';
VALUES ('江南逢李龟年', '杜甫', '唐代', '岐王宅里寻常见，崔九堂前几度闻。 正是江南好风景，落花时节又逢君。', 2);
UPDATE edu_poem SET poem_translation = '当年在岐王宅里，常常见到你的演出；在崔九堂前，也曾多次欣赏你的艺术。\n没有想到，在这风景一派大好的江南；正是落花时节，能巧遇你这位老相熟。', poem_notes = '1.李龟年：唐朝开元、天宝年间的著名乐师，擅长唱歌。因为受到皇帝唐玄宗的宠幸而红极一时。“安史之乱”后，李龟年流落江南，卖艺为生。\n2.岐王：唐玄宗李隆基\n的弟弟，名叫李范，以好学爱才著称，雅善音律。\n3.寻常：经常。\n4.崔九：崔涤，在兄弟中排行第九，中书令崔湜的弟弟。玄宗时，曾任殿中监，出入禁中，得玄宗宠幸。崔姓，是当时一家大姓，以此表明李龟年原来受赏识。\n5.江南：这里指今湖南省一带。\n6.落花时节：暮春，通常指阴历三月。落花的寓意很多，人衰老飘零，社会的凋弊丧乱都在其中。\n7.君：指李龟年。' WHERE poem_title = '江南逢李龟年' AND poem_author = '杜甫';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '江南逢李龟年' AND p.poem_author = '杜甫';
VALUES ('赠别·其二', '杜牧', '唐代', '多情却似总无情，唯觉樽前笑不成。蜡烛有心还惜别，替人垂泪到天明。', 2);
UPDATE edu_poem SET poem_translation = '聚首如胶似漆作别却象无情；\n只觉得酒筵上要笑笑不出声。\n案头蜡烛有心它还依依惜别；\n你看它替我们流泪流到天明。', poem_notes = '多情句：意谓多情者满腔情绪，一时无法表达，只能无言相对，倒象彼此无情。\n樽：酒杯。' WHERE poem_title = '赠别·其二' AND poem_author = '杜牧';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '赠别·其二' AND p.poem_author = '杜牧';
VALUES ('金谷园', '杜牧', '唐代', '繁华事散逐香尘，流水无情草自春。日暮东风怨啼鸟，落花犹似坠楼人。', 2);
UPDATE edu_poem SET poem_translation = '繁华往事，已跟香尘一样飘荡无存；流水无情，野草却年年以碧绿迎春。啼鸟悲鸣，傍晚随着东风声声传来；落花纷纷，恰似那为石崇\n坠楼的绿珠美人。', poem_notes = '1、香尘：石崇为教练家中舞妓步法，以沉香屑铺象牙床上，使她们践踏，无迹者赐以珍珠。\n2、坠楼人：指石崇爱妾绿珠，曾为石崇坠楼而死。' WHERE poem_title = '金谷园' AND poem_author = '杜牧';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '金谷园' AND p.poem_author = '杜牧';
VALUES ('寄扬州韩绰判官', '杜牧', '唐代', '青山隐隐水迢迢，秋尽江南草未凋。二十四桥明月夜，玉人何处教吹箫？', 2);
UPDATE edu_poem SET poem_translation = '青山隐约绿水悠悠长流，江南深秋草木还未凋零。\n明亮月光映照二十四桥，你是否还在听美人吹箫？', poem_notes = '⑴韩绰：事不详，杜牧另有《哭韩绰》。判官：观察使、节度使的属官。时韩绰似任淮南节度使判官。公元833年（唐文宗大和七年）至835年（大和九年），杜牧曾任淮南节度使掌书记，与韩绰是同僚。\n⑵迢迢：指江水悠长遥远。一作“遥遥”。\n⑶草未凋（diāo）：一作“草木凋”。凋：凋谢。\n⑷二十四桥：一说为二十四座桥。北宋沈括《梦溪笔谈·补笔谈》卷三中对每座桥的方位和名称一一做了记载。一说有一座桥名叫二十四桥，清李斗《扬州画舫录》卷十五：“廿四桥即吴家砖桥，一名红药桥，在熙春台后，……扬州鼓吹词序云，是桥因古二十四美人吹箫于此，故名。”\n⑸玉人：貌美之人。这里指韩绰。一说指扬州歌妓。教：使，令。\n(6)箫：一种乐器。', poem_appreciation = '唐文宗大和七年四月到九年初，杜牧曾在淮南节度使（使府在扬州）牛僧孺幕中作过推官和掌书记，和当时在幕任节度判官的韩绰相识。此诗是杜牧离开扬州以后，在江南怀念昔日同僚韩绰判官而作。，具体写作时间约在大和九年秋或开成元年秋。杜牧在韩绰死后作过《哭韩绰》诗，可见他与韩绰有深厚的友谊。\n此诗是杜牧被任为监察御史，由淮南节度使幕府回长安供职后所作，具体写作时间约在唐文宗大和九年（835年）或开成元年（836年）秋。唐文宗大和七年（833年）至大和九年（835年），杜牧曾任淮南节度使掌书记，与韩绰是同僚。　　唐代的扬州，是长江中下游繁荣的都会，店肆林立，商贾如云，酒楼舞榭，比比皆是，“每重城向夕，倡楼之上，常有绛纱灯数万，辉罗耀列空中，九里三十步街中，珠翠填咽，邈若仙境”（《太平广记》卷273引《唐阙文》）。“性疏野放荡”的杜牧，在这样的环境中，常出没于青楼倡家，有不少风流韵事，韩绰在这方面是他同道，所以回到长安后写诗寄赠。' WHERE poem_title = '寄扬州韩绰判官' AND poem_author = '杜牧';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '寄扬州韩绰判官' AND p.poem_author = '杜牧';
VALUES ('遣怀', '杜牧', '唐代', '落魄江南载酒行，楚腰纤细掌中轻。十年一觉扬州梦，赢得青楼薄幸名。', 2);
UPDATE edu_poem SET poem_translation = '失意潦倒，携酒漂泊江湖，沉湎于楚灵王喜好的细腰女子和赵飞燕的轻盈舞姿。扬州十年的纵情声色，好像一场梦，醒悟回头，却在青楼女子这中落得一个薄情的名声。', poem_notes = '⑴落魄：仕宦潦倒不得意，飘泊江湖。魄一作拓。楚腰：指细腰美女。《韩非子·二柄》：“楚灵王好细腰，而国中多饿人。”\n⑵掌中轻：汉成帝皇后赵飞燕“体轻，能为掌上舞”（《飞燕外传》）。\n⑶十年：一作三年。\n⑷青楼：旧指精美华丽的楼房，也指妓院。薄幸：薄情。' WHERE poem_title = '遣怀' AND poem_author = '杜牧';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '遣怀' AND p.poem_author = '杜牧';
VALUES ('将赴吴兴登乐游原一绝', '杜牧', '唐代', '清时有味是无能，闲爱孤云静爱僧。 欲把一麾江海去，乐游原上望昭陵。', 2);
UPDATE edu_poem SET poem_translation = '太平时闲游有趣却是无能，闲爱天上孤云安静爱山僧。\n我愿手持旌麾去吴兴上任，乐游原上再望望风雨昭陵。', poem_notes = '⑴吴兴：即今浙江省湖州市。乐游原：在长安城南，地势高敞，可以眺望，是当时的游览胜地。\n⑵“清时”句：意谓当这清平无所作为之时，自己所以有此闲情。\n⑶一麾（huī）：旌旗。\n⑷昭陵：唐太宗的陵墓。' WHERE poem_title = '将赴吴兴登乐游原一绝' AND poem_author = '杜牧';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '将赴吴兴登乐游原一绝' AND p.poem_author = '杜牧';
VALUES ('赤壁', '杜牧', '唐代', '折戟沉沙铁未销，自将磨洗认前朝。东风不与周郎便，铜雀春深锁二乔。', 2);
UPDATE edu_poem SET poem_translation = '一支折断了的铁戟（古代兵器）沉没在水底的沙中还没有销蚀掉，经过自己又磨又洗发现这是当年赤壁之战的遗留之物。\n假如东风不给周瑜以方便，结局恐怕是\n曹操\n取胜，二乔被关进铜雀台了。', poem_notes = '⑴折戟：折断的戟。戟，古代兵器。\n⑵销：销蚀。\n⑶将：拿起。\n⑷磨洗：磨光洗净。\n⑸认前朝：认出戟是东吴破曹时的遗物。\n⑹东风：指三国时期的一个战役──火烧赤壁。\n⑺周郎：指周瑜，字公瑾，年轻时即有才名，人乎周郎。后任吴军大都督，曾参与赤壁之战并为此战役中的主要人物。\n⑻铜雀：即铜雀台，曹操在今河北省临漳县建造的一座楼台，楼顶里有大铜雀，台上住姬妾歌妓，是曹操暮年行乐处。\n⑼二乔：东吴乔公的两个女儿，一嫁前国主孙策（孙权兄），称大乔，一嫁军事统帅周瑜，称小乔，合称“二乔”。', poem_appreciation = '这首诗是诗人经过赤壁（今湖北省武昌县西南赤矶山）这个著名的古战场，有感于三国时代的英雄成败而写下的。发生于汉献帝建安十三年（208年）十月的赤壁之战，是对三国鼎立的历史形势起着决定性作用的一次重大战役。其结果是孙、刘联军击败了曹军，而三十四岁的孙吴军统帅周瑜，乃是这次战役中的头号风云人物。诗人观赏了古战场的遗物，对赤壁之战发表了独特的看法，有感而作。' WHERE poem_title = '赤壁' AND poem_author = '杜牧';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '赤壁' AND p.poem_author = '杜牧';
VALUES ('泊秦淮', '杜牧', '唐代', '烟笼寒水月笼沙，夜泊秦淮近酒家。 商女不知亡国恨，隔江犹唱后庭花。', 2);
UPDATE edu_poem SET poem_translation = '迷离月色和轻烟笼罩寒水和白沙，夜晚船泊在秦淮靠近岸上的酒家。\n卖唱的歌女不懂什么叫亡国之恨，隔着江水还高唱着《玉树后庭花》。', poem_notes = '⑴秦淮：即秦淮河，发源于江苏句容大茅山与溧水东庐山两山间，经南京流入长江。相传为秦始皇南巡会稽时开凿的，用来疏通淮水，故称秦淮河。历代均为繁华的游赏之地。\n⑵烟：烟雾。\n⑶泊：停泊。\n⑷商女：以卖唱为生的歌女。\n⑸后庭花：歌曲《玉树后庭花》的简称。南朝陈皇帝陈叔宝\n（即陈后主）溺于声色，作此曲与后宫美女寻欢作乐，终致亡国，所以后世把此曲作为亡国之音的代表。', poem_appreciation = '唐朝著名诗人杜牧游秦淮，在船上听见歌女唱《玉树后庭花》，绮艳轻荡，男女之间互相唱和，歌声哀伤，是亡国之音。当年陈后主长期沉迷于这种萎靡的生活，视国政为儿戏，终于丢了江山。陈国虽亡，这种靡靡的音乐却留传下来，还在秦淮歌女中传唱，这使杜牧非常感慨。他的诗说：这些无知歌女连亡国恨都不懂，还唱这种亡国之音！其实这是借题发挥，他讥讽的实际是晚唐政治：群臣们又沉湎于酒色，快步陈后主的后尘了。秦淮一隅，寄至如此深沉的兴亡感，足见金陵在当时全国政治中心已经移向长安的情况下，影响仍然很大。　　杜牧前期颇为关心政治，对当时百孔千疮的唐王朝表示忧虑，他看到统治集团的腐朽昏庸，看到藩镇的拥兵自固，看到边患的频繁，深感社会危机四伏，唐王朝前景可悲。这种忧时伤世的思想，促使他写了好些具有现实意义的诗篇。《泊秦淮》也就是在这种思想基础上产生的。当他来到当时还是一片繁华的秦淮河上，听到酒家歌女演唱《后庭花》曲，便感慨万千，写下了这首诗。诗中说，金陵歌女“不知亡国恨”，还唱着那《后庭花》曲。其实，这是作者借陈后主(陈叔宝）因追求荒淫享乐终至亡国的历史，讽刺晚唐那般醉生梦死的统治者不从中汲取教训，表现了作者对国家命运的无比关怀和深切忧虑。\n杜牧前期颇为关心政治，对当时百孔千疮的唐王朝表示忧虑，他看到统治集团的腐朽昏庸，看到藩镇的拥兵自固，看到边患的频繁，深感社会危机四伏，唐王朝前景可悲。这种忧时伤世的思想，促使他写了许多具有现实意义的诗篇。《泊秦淮》也就是在这种思想基础上产生的。　　六朝古都金陵的秦淮河两岸历来是达官贵人们享乐游宴的场所，“秦淮”也逐渐成为奢靡生活的代称。诗人夜泊于此，眼见灯红酒绿，耳闻淫歌艳曲，触景生情，又想到唐朝国势日衰，当权者昏庸荒淫，便感慨万千，写下了这首诗：《泊秦淮》。' WHERE poem_title = '泊秦淮' AND poem_author = '杜牧';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '泊秦淮' AND p.poem_author = '杜牧';
VALUES ('征人怨', '柳中庸', '唐代', '岁岁金河复玉关，朝朝马策与刀环。 三春白雪归青冢，万里黄河绕黑山。', 2);
UPDATE edu_poem SET poem_translation = '年年岁岁戍守金河保卫玉关，日日夜夜挥舞马鞭手握刀环。\n时届暮春白雪飘飞归来塞外，万里奔波渡过黄河绕过黑山。', poem_notes = '⑴岁岁：年复一年，年年月月。金河：即黑河，在今呼和浩特市城南。玉关：即甘肃玉门关。\n⑵朝（zhāo）朝：每天，日日夜夜。马策：马鞭。刀环：刀柄上的铜环，喻征战事。\n⑶三春：春季的三个月或暮春，此处指暮春。青冢（zhǒng）：西汉时王昭君\n的坟墓，在今内蒙古呼和浩特之南，当时被认为是远离中原的一处极僻远荒凉的地方。传说塞外草白，惟独昭君墓上草色发青，故称青冢。\n⑷黑山：一名杀虎山，在今内蒙古呼和浩特市东南。' WHERE poem_title = '征人怨' AND poem_author = '柳中庸';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '征人怨' AND p.poem_author = '柳中庸';
VALUES ('金陵图', '韦庄', '唐代', '谁谓伤心画不成，画人心逐世人情。 君看六幅南朝事，老木寒云满故城。', 2);
UPDATE edu_poem SET poem_translation = '谁说画不出六朝古都的伤心事，只不过是那些画家为了迎合当权者的心态而不画伤心图而已。\n你看这六幅描摹南朝往事的画中，枯老的树木和寒凉的云朵充满了整个金陵城。', poem_notes = '⑴金陵：古地名，即今江苏南京及江宁等地，为六朝故都。\n⑵逐：随，跟随。《玉篇》：“逐，从也。”这里可作迎合解。\n⑶老木：枯老的树木。’' WHERE poem_title = '金陵图' AND poem_author = '韦庄';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '金陵图' AND p.poem_author = '韦庄';
VALUES ('滁州西涧', '韦应物', '唐代', '独怜幽草涧边生，上有黄鹂深树鸣。 春潮带雨晚来急，野渡无人舟自横。', 2);
UPDATE edu_poem SET poem_translation = '最是喜爱涧边生长的幽幽野草，还有那树丛深处婉转啼唱的黄鹂。\n春潮不断上涨，还夹带着密密细雨。荒野渡口无人，只有一只小船悠闲地横在水面。', poem_notes = '⑴滁州：在今安徽滁州以西。西涧：在滁州城西，俗名称上马河。\n⑵独怜：唯独喜欢。幽草：幽谷里的小草。幽，一作“芳”。生：一作“行”。\n⑶深树：枝叶茂密的树。深，《才调集》作“远”。树，《全唐》注“有本作‘处’”。\n⑷春潮：春天的潮汐。\n⑸野渡：郊野的渡口。横：指随意飘浮。', poem_appreciation = '一般认为《滁州西涧》这首诗是唐德宗建中二年（781年）韦应物任滁州刺史时所作。他时常独步郊外，滁州西涧便是他常光顾的地方。作者喜爱西涧清幽的景色，一天游览至滁州西涧（在滁州城西郊野），写下了这首诗情浓郁的小诗。' WHERE poem_title = '滁州西涧' AND poem_author = '韦应物';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '滁州西涧' AND p.poem_author = '韦应物';
VALUES ('桃花溪', '张旭', '唐代', '隐隐飞桥隔野烟，石矶西畔问渔船。 桃花尽日随流水，洞在清溪何处边。', 2);
UPDATE edu_poem SET poem_translation = '一座高桥隔着云烟出现，在岩石的西畔询问渔船。\n桃花整天随着流水流淌，桃源洞口在清溪的哪边？', poem_notes = '⑴桃花溪：水名，在湖南省桃源县桃源山下。\n⑵飞桥：高桥。\n⑶石矶：水中积石或水边突出的岩石、石堆。渔船：源自陶渊明《桃花源记》中语句。\n⑷尽日：整天，整日。\n⑸洞：指《桃花源记》中武陵渔人找到的洞口。' WHERE poem_title = '桃花溪' AND poem_author = '张旭';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '桃花溪' AND p.poem_author = '张旭';
VALUES ('题金陵渡', '张祜', '唐代', '金陵津渡小山楼，一宿行人自可愁。 潮落夜江斜月里，两三星火是瓜州。', 2);
UPDATE edu_poem SET poem_translation = '夜宿金陵渡口的小山楼，辗转难眠心中满怀旅愁。\n斜月朦胧江潮正在下落，对岸星火闪闪便是瓜洲。', poem_notes = '⑴金陵渡：渡口名，在今江苏省镇江市附近。\n⑵津：渡口。小山楼：渡口附近小楼，作者住宿之处。\n⑶宿：过夜。行人：旅客，指作者自己。可：当。\n⑷斜月：下半夜偏西的月亮。星火：形容远处三三两两像星星一样闪烁的火光。\n⑸瓜州：在长江北岸，今江苏省邗江县南部，与镇江市隔江相对，向来是长江南北水运的交通要冲。' WHERE poem_title = '题金陵渡' AND poem_author = '张祜';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '题金陵渡' AND p.poem_author = '张祜';
VALUES ('赠内人', '张祜', '唐代', '禁门宫树月痕过，媚眼惟看宿鹭窠。斜拔玉钗灯影畔，剔开红焰救飞蛾。', 2);
UPDATE edu_poem SET poem_translation = '月光由宫门移到宫树梢，媚眼只看那宿鹭的窝巢。\n在灯影旁拔下头上玉钗，挑开灯焰救出扑火飞蛾。', poem_notes = '⑴内人：指宫女。因皇宫又称大内，故宫女称内人。\n⑵禁门：宫门。\n⑶宿鹭：指双栖之鸳鸯。\n⑷红焰：指灯芯。' WHERE poem_title = '赠内人' AND poem_author = '张祜';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '赠内人' AND p.poem_author = '张祜';
VALUES ('集灵台·其一', '张祜', '唐代', '日光斜照集灵台，红树花迎晓露开。 昨夜上皇新授箓，太真含笑入帘来。', 2);
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '集灵台·其一' AND p.poem_author = '张祜';
VALUES ('集灵台·其二', '张祜', '唐代', '虢国夫人承主恩，平明骑马入宫门。却嫌脂粉污颜色，淡扫峨眉朝至尊。', 2);
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '集灵台·其二' AND p.poem_author = '张祜';
VALUES ('枫桥夜泊', '张继', '唐代', '月落乌啼霜满天，江枫渔火对愁眠。姑苏城外寒山寺，夜半钟声到客船。', 2);
UPDATE edu_poem SET poem_translation = '月亮已落下乌鸦啼叫寒气满天， 对着江边枫树和渔火忧愁而眠。\n姑苏城外那寂寞清静寒山古寺， 半夜里敲钟的声音传到了客船。', poem_notes = '枫桥：在今苏州市阊门外。\n夜泊：夜间把船停靠在岸边。\n乌啼：一说为乌鸦啼鸣，一说为乌啼镇。\n霜满天：霜，不可能满天，这个“霜”字应当体会作严寒；霜满天，是空气极冷的形象语。\n江枫：一般解释作“江边枫树”，江指吴淞江，源自太湖，流经上海，汇入长江，俗称苏州河。另外有人认为指“江村桥”和“枫桥”。“枫桥”在吴县南门（阊阖门）外西郊，本名“封桥”，因张继此而改为“枫桥”。\n渔火：通常解释，“鱼火”就是渔船上的灯火；也有说法指“渔火”实际上就是一同打渔的伙伴。\n对愁眠：伴愁眠之意，此句把江枫和渔火二词拟人化。就是后世有不解诗的人，怀疑江枫渔火怎么能对愁眠，于是附会出一种讲法，说愁眠是寒山寺对面的山名。\n姑苏：苏州的别称，因城西南有姑苏山而得名。\n寒山寺：在枫桥附近，始建于南朝梁代。相传因唐代僧人寒山、拾得\n曾住此而得名。在今苏州市西枫桥镇。本名“妙利普明塔院”，又名枫桥寺；另一种说法，“寒山”乃泛指肃寒之山，非寺名。寺曾经数次重建，现在的寺宇，为太平天国以后新建。寺钟在第二次世界大战时，被日本人运走，下落不明。\n夜半钟声：当今的佛寺（春节）半夜敲钟，但当时有半夜敲钟的习惯，也叫「无常钟」或「分夜钟」。宋朝大文豪欧阳修\n曾提出疑问表示：“诗人为了贪求好句，以至于道理说不通，这是作文章的毛病，如张继诗句“夜半钟声到客船”，句子虽好，但那有三更半夜打钟的道理？”可是经过许多人的实地查访，才知苏州和邻近地区的佛寺，有打半夜钟的风俗。' WHERE poem_title = '枫桥夜泊' AND poem_author = '张继';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '枫桥夜泊' AND p.poem_author = '张继';
VALUES ('陇西行', '陈陶', '唐代', '誓扫匈奴不顾身，五千貂锦丧胡尘。可怜无定河边骨，犹是春闺梦里人！', 2);
UPDATE edu_poem SET poem_translation = '唐军将士誓死横扫匈奴奋不顾身，\n五千身穿锦袍的精兵战死在胡尘。\n真可\n怜呵那无定河边成堆的白骨，\n还是少妇们梦中相依相伴的丈夫。', poem_notes = '①貂锦：这里指战士，指装备精良的精锐之师。\n②无定河：在陕西北部。\n③春闺：这里指战死者的妻子。\n④匈奴：指西北边境部族。' WHERE poem_title = '陇西行' AND poem_author = '陈陶';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '陇西行' AND p.poem_author = '陈陶';
VALUES ('杂诗', '不详', '唐代', '近寒食雨草萋萋，著麦苗风柳映堤。等是有家归未得，杜鹃休向耳边啼。', 2);
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '杂诗' AND p.poem_author = '不详';
VALUES ('回乡偶书·其一', '贺知章', '唐代', '少小离家老大回，乡音无改鬓毛衰。儿童相见不相识，笑问客从何处来。', 2);
UPDATE edu_poem SET poem_translation = '我在年少时离开家乡，到了迟暮之年才回来。我的乡音虽未改变，但鬓角的毛发却已经疏落。儿童们看见我，没有一个认识的。他们笑着询问：这客人是从哪里来的呀？', poem_notes = '(1)偶书：随便写的。偶：说明诗写作得很偶然，是随时有所见、有所感就写下来的。\n(2)少小离家：贺知章三十七岁中进士，在此以前就离开家乡。老大：年纪大了。贺知章回乡时已年逾八十。\n(3)乡音：家乡的口音。无改：没什么变化。一作“难改”。鬓毛：额角边靠近耳朵的头发。一作“面毛”。衰（cui）：减少，疏落。鬓毛衰：指鬓毛减少，疏落。\n(4)相见：即看见我；相：带有指代性的副词。不相识：即不认识我。\n(5)笑问：一本作“却问”，一本作“借问”。' WHERE poem_title = '回乡偶书·其一' AND poem_author = '贺知章';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '回乡偶书·其一' AND p.poem_author = '贺知章';
VALUES ('瑶瑟怨', '温庭筠', '唐代', '冰簟银床梦不成，碧天如水夜云轻。 雁声远过潇湘去，十二楼中月自明。', 2);
UPDATE edu_poem SET poem_translation = '秋夜床席冰冷梦也难以做成，天空碧蓝如水夜云像沙样轻。\n雁声凄厉远远地飞过潇湘去，十二楼中的明月空自放光明。', poem_notes = '⑴瑶瑟：玉镶的华美的瑟。\n⑵冰簟：清凉的竹席。银床：指洒满月光的床。\n⑶远：一作“还”。过：一作“向”。潇湘：二水名，在今湖南境内。此代指楚地。\n⑷十二楼：原指神仙的居所，此指女子的住所。' WHERE poem_title = '瑶瑟怨' AND poem_author = '温庭筠';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '瑶瑟怨' AND p.poem_author = '温庭筠';
VALUES ('月夜', '刘方平', '唐代', '更深月色半人家，北斗阑干南斗斜。 今夜偏知春气暖，虫声新透绿窗纱。', 2);
UPDATE edu_poem SET poem_translation = '夜静更深，月光只照亮了人家房屋的一半，另一半隐藏在黑夜里。北斗星倾斜了，南斗星也倾斜了。\n今夜才知春天的来临，因为你听那被树叶映绿的窗纱外，唧唧的虫鸣，头一遭儿传到了屋子里来了。', poem_notes = '⑴更深：古时计算时间，一夜分成五更。更深，夜深了。\n⑵月色半人家：月光只照亮了人家房屋的一半，另一半隐藏在黑暗里。\n⑶北斗：在北方天空排列成斗形的七颗亮星。\n⑷阑干：这里指横斜的样子。\n⑸南斗：有星六颗。在北斗星以南，形似斗，故称“南斗”。\n⑹偏知：才知，表示出乎意料。\n⑺新：初。新透：第一次透过。' WHERE poem_title = '月夜' AND poem_author = '刘方平';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '月夜' AND p.poem_author = '刘方平';
VALUES ('春怨', '刘方平', '唐代', '纱窗日落渐黄昏，金屋无人见泪痕。 寂寞空庭春欲晚，梨花满地不开门。', 2);
UPDATE edu_poem SET poem_translation = '纱窗外的阳光淡去，黄昏渐渐降临；\n锁闭华屋，无人看见我悲哀的泪痕。\n庭院空旷寂寞，春天景色行将逝尽；\n梨花飘落满地，无情无绪把门关紧。', poem_notes = '金屋：原指汉武帝少时欲金屋藏阿娇事。这里指妃嫔所住的华丽宫室。' WHERE poem_title = '春怨' AND poem_author = '刘方平';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '春怨' AND p.poem_author = '刘方平';
VALUES ('乌衣巷', '刘禹锡', '唐代', '朱雀桥边野草花，乌衣巷口夕阳斜。 旧时王谢堂前燕，飞入寻常百姓家。', 2);
UPDATE edu_poem SET poem_translation = '翻译\n朱雀桥边一些野草开花，乌衣巷口唯有夕阳斜挂。当年王导、谢安檐下的燕子，如今已飞进寻常百姓家中。', poem_notes = '【朱雀桥】在金陵城外，乌衣巷在桥边。 在今南京市东南，在文德桥南岸，是三国东吴时的禁军驻地。由于当时禁军身着黑色军服，所以此地俗语称乌衣巷。在东晋时以王导、谢安两大家族，都居住在乌衣巷，人称其子弟为“乌衣郎”。入唐后，乌衣巷沦为废墟。现为民间工艺品的汇集之地。\n【乌衣】燕子，旧时王谢之家庭多燕子。今江苏省南京市江宁区，横跨秦淮河。\n【寻常】平常。\n【王谢】王导、谢安，晋相，世家大族，贤才众多，皆居巷中，冠盖簪缨，为六朝(吴、东晋、宋齐梁陈先后建都于建康即今之南京)巨室。至唐时，则皆衰落不知其处。\n【旧时】晋代。' WHERE poem_title = '乌衣巷' AND poem_author = '刘禹锡';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '乌衣巷' AND p.poem_author = '刘禹锡';
VALUES ('春词', '刘禹锡', '唐代', '新妆宜面下朱楼，深锁春光一院愁。 行到中庭数花朵，蜻蜓飞上玉搔头。', 2);
UPDATE edu_poem SET poem_translation = '浓妆艳抹打扮一新下红楼，深深庭院春光虽好只添愁。\n走到庭中查数新开的花朵，蜻蜓有情飞到了玉簪上头。', poem_notes = '⑴春词：春怨之词。“春词”为白居易原题目。\n⑵宜面：脂粉和脸色很匀称。一作“粉面”。朱楼：髹以红漆的楼房，多指富贵女子的居所。\n⑶蜻蜓：暗指头上之香。玉搔头：玉簪，可用来搔头，故称。' WHERE poem_title = '春词' AND poem_author = '刘禹锡';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '春词' AND p.poem_author = '刘禹锡';
VALUES ('寒食', '韩翃', '唐代', '春城无处不飞花，寒食东风御柳斜。 日暮汉宫传蜡烛，轻烟散入五侯家。', 2);
UPDATE edu_poem SET poem_translation = '暮春时节，长安城处处柳絮飞舞、落红无数，寒食节东风吹拂着皇家花园的柳枝。\n夜色降临，宫里忙着传蜡烛，袅袅炊烟散入王侯贵戚的家里。', poem_notes = '①春城：暮春时的长安城。\n②寒食：古代在清明节前两天的节日，焚火三天，只吃冷食，所以称寒食。御柳：御苑之柳，皇城中的柳树。\n③汉宫：这里指唐朝皇官。传蜡烛：寒食节普天下禁火，但权贵宠臣可得到皇帝恩赐而得到燃烛。《唐辇下岁时记》“清明日取榆柳之火以赐近臣”。\n④五侯：汉成帝时封王皇后的五个兄弟王谭、王商、王立、王根、王逢时皆为候，受到特别的恩宠。这里泛指天子近幸之臣。', poem_appreciation = '寒食是中国古代一个传统节日，一般在冬至后一百零五天，清明前两天。古人很重视这个节日，按风俗家家禁火，只吃现成食物，故名寒食。唐代制度，到清明这天，皇帝宣旨取榆柳之火赏赐近臣，以示皇恩。这仪式用意有二：一是标志着寒食节已结束，可以用火了；二是藉此给臣子官吏们提个醒，让大家向有功也不受禄的介子推学习，勤政为民。唐代诗人窦叔向有《寒食日恩赐火》诗纪其实：“恩光及小臣，华烛忽惊春。电影随中使，星辉拂路人。幸因榆柳暖，一照草茅贫。”正可与韩翃这一首诗参照。　　中唐以后，几任昏君都宠幸宦官，以致他们的权势很大，败坏朝政，排斥朝官，正直人士对此都极为愤慨。有意见认为此诗正是因此而发。' WHERE poem_title = '寒食' AND poem_author = '韩翃';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '寒食' AND p.poem_author = '韩翃';
VALUES ('已凉', '韩偓', '唐代', '碧阑干外绣帘垂，猩血屏风画折枝。 八尺龙须方锦褥，已凉天气未寒时。', 2);
UPDATE edu_poem SET poem_translation = '翠绿色的栏杆外绣帘儿低垂，猩红的屏风上画着草木花卉。\n龙须草织成的席子铺上锦褥，天气已凉却还未到寒冷时候。', poem_notes = '⑴绣帘：一作“翠帘”。\n⑵猩血：一作“猩色”，猩红色。屏风：一种用来遮挡和做隔断的东西。画折枝：一作“画柘枝”，指图绘花卉草木。\n⑶龙须：属灯心草科，茎可织席。这里指草席。' WHERE poem_title = '已凉' AND poem_author = '韩偓';
SELECT p.poem_id, '小学', NULL FROM edu_poem p
WHERE p.poem_title = '已凉' AND p.poem_author = '韩偓';

-- ----------------------------
-- 古诗文全集（chinese-gushiwen 全量 10000 首）
-- ----------------------------
-- 数据源：gitee waleslau/chinese-gushiwen guwen/（10 个 JSONL，共 10000 首）。
-- 收录策略：全量入库 —— 有译文/注释/赏析/标签就补，没有的也只收正文与朝代，
--          不因缺译文而丢弃条目。字段覆盖约为 译文 25%、注释 24%、赏析 20%、标签 100%。
-- 形态：INSERT IGNORE 新诗 + UPDATE 只补空缺字段（不覆盖已有内容、不改正文与作者）。
-- 学段：按 type 里的「小学/初中/高中」教材标记归类，无标记按 初中。

UPDATE edu_poem SET poem_translation = '你难道看不见那黄河之水从天上奔腾而来，波涛翻滚直奔东海，从不再往回流。\n你难道看不见那年迈的父母，对着明镜悲叹自己的白发，早晨还是满头的黑发，怎么才到傍晚就变成了雪白一片。\n（所以）人生得意之时就应当纵情欢乐，不要让这金杯无酒空对明月。\n每个人的出生都一定有自己的价值和意义，黄金千两（就算）一挥而尽，它也还是能够再得来。\n我们烹羊宰牛姑且作乐，（今天）一次性痛快地饮三百杯也不为多！\n岑夫子，丹丘生啊！快喝酒吧！不要停下来。\n让我来为你们高歌一曲，请你们为我倾耳细听：\n整天吃山珍海味的豪华生活有何珍贵，只希望醉生梦死而不愿清醒。 \n自古以来圣贤无不是冷落寂寞的，只有那会喝酒的人才能够留传美名。\n陈王曹植当年宴设平乐观的事迹你可知道，斗酒万千也豪饮，让宾主尽情欢乐。\n主人呀，你为何说钱不多？只管买酒来让我们一起痛饮。\n那些什么名贵的五花良马，昂贵的千金狐裘，把你的小儿喊出来，都让他拿去换美酒来吧，让我们一起来消除这无穷无尽的万古长愁！', poem_notes = '将进酒：属乐府旧题。将（qiāng）：请。\n君不见：乐府中常用的一种夸语。天上来：黄河发源于青海，因那里地势极高，故称。\n高堂：高堂：房屋的正室厅堂。一说指父母。一作“床头”。青丝：喻柔软的黑发。一作“青云”。成雪：一作“如雪”。\n得意：适意高兴的时候。\n金樽（zūn）：中国古代的盛酒器具。\n会须：正应当。\n岑夫子：岑勋。丹丘生：元丹丘。二人均为李白的好友。\n杯莫停：一作“君莫停”。\n与君：给你们，为你们。君，指岑、元二人。\n倾耳听：一作“侧耳听”。\n钟鼓：富贵人家宴会中奏乐使用的乐器。馔（zhuàn）玉：形容食物如玉一样精美。\n不复醒：也有版本为“不用醒”或“不愿醒”。\n陈王：指陈思王曹植。平乐：观名。在洛阳西门外，为汉代富豪显贵的娱乐场所。恣\n业书法《将进酒》季深业书法《将进酒》 \n恣（zì）：纵情任意。谑（xuè）：戏。言少钱：一作“言钱少”。\n径须：干脆，只管。沽：买。\n五花马：指名贵的马。一说毛色作五花纹，一说颈上长毛修剪成五瓣。\n尔：你。销：同“消”。', poem_appreciation = '这首诗非常形象的表现了李白桀骜不驯的性格：一方面对自己充满自信，孤高自傲；一方面在政治前途出现波折后，又流露出纵情享乐之情。在这首诗里，他演绎庄子的乐生哲学，表示对富贵、圣贤的藐视。而在豪饮行乐中，实则深含怀才不遇之情。全诗气势豪迈，感情奔放，语言流畅，具有很强的感染力，李白“借题发挥”借酒浇愁，抒发自己的愤激情绪。\n\n　　时光流逝，如江河入海一去无回；人生苦短，看朝暮间青丝白雪；生命的渺小似乎是个无法挽救的悲剧，能够解忧的惟有金樽美酒。这便是李白式的悲哀：悲而能壮，哀而不伤，极愤慨而又极豪放。表是在感叹人生易老，里则在感叹怀才不遇。诗篇开头是两组排比长句，如挟天风海雨向读者迎面扑来，气势豪迈。“君不见黄河之水天上来，奔流到海不复回”，李白此时在颍阳山，距离黄河不远，登高纵目，所以借黄河来起兴。黄河源远流长，落差极大，如从天而降，一泻千里，东走大海。景象之壮阔，并不是肉眼可见，所以此情此景是李白幻想的，“自道所得”，言语中带有夸张。上句写大河之来，势不可挡；下句写大河之去，势不可回。一涨一消，形成舒卷往复的咏叹味，是短促的单句（如“黄河落天走东海”）所没有的。\n\n　　紧接着，“君不见高堂明镜悲白发，朝如青丝暮成雪”，恰似一波未平、一波又起。前二句为空间范畴的夸张，这二句则是时间范畴的夸张。悲叹人生短促；而不直接说出自己感伤生命短暂而人一下就会变老，却说“高堂明镜悲白发”，显现出一种对镜自照手抚两鬓、却无可奈何的情态。将人生由青春至衰老的全过程说成“朝”、“暮”之事，把本来短暂的说得更短暂，与前两句把本来壮浪的说得更壮浪，是“反向”的夸张。于是，开篇的这组排比长句既有比意——以河水一去不返喻人生易逝，又有反衬作用；以黄河的伟大永恒形出生命的渺小脆弱。这个开端可谓悲感已极，却不堕纤弱，可说是巨人式的感伤，具有惊心动魄的艺术力量，同时也是由长句排比开篇的气势感造成的。这种开篇的手法作者常用，他如“弃我去者，昨日之日不可留；乱我心者，今日之日多烦忧”（《宣城谢朓楼饯别校书叔云》），沈德潜说：“此种格调，太白从心化出”，可见其颇具创造性。此诗两作“君不见”的呼告（一般乐府诗只于篇首或篇末偶一用之），又使诗句感情色彩大大增强。诗有所谓大开大阖者，此可谓大开。 “夫天地者，万物之逆旅也；光阴者，百代之过客也”（《春夜宴从弟桃李园序》），悲感虽然不免，但悲观却非李白性分之所近。在他看来，只要“人生得意”便无所遗憾，当纵情欢乐。\n\n　　五六两句便是一个逆转，由“悲”而翻作“欢“”乐”。从此直到“杯莫停”，诗情渐趋狂放。“人生达命岂暇愁，且饮美酒登高楼”（《梁园吟》），行乐不可无酒，这就入题。但句中没有直写杯中之物，而用“金樽”、“对月”的形象语言来突出隐喻，更将饮酒诗意化了；未直写应该痛饮狂欢，而以“莫使”、“空”的双重否定句式代替直陈，语气更为强调。“人生得意须尽欢”，这似乎是宣扬及时行乐的思想，然而只不过是现象而已。诗人此时郁郁不得志。“凤凰初下紫泥诏，谒帝称觞登御筵”（《玉壶吟》），奉诏进京、皇帝赐宴的时候似乎得意过，然而那不过是一场幻影。再到“弹剑作歌奏苦声，曳裾王门不称情”（《行路难·其二》），古时冯谖在孟尝君门下作客，觉得孟尝君对自己不够礼遇，开始时经常弹剑而歌，表示要回去。李白希望“平交王侯”的，而在长安，权贵们并不把他当一回事，李白借冯谖的典故比喻自己的处境。这时又似乎并没有得意，有的是失望与愤慨。 但并不就此消沉。诗人于是用乐观好强的口吻肯定人生，肯定自我：“天生我材必有用”，这是一个令人击节赞叹的句子。“有用”而“必”，非常自信，简直像是人的价值宣言，而这个人——“我”——是须大写的。于此，从貌似消极的现象中露出了深藏其内的一种怀才不遇而又渴望入世的积极的本质内容来。正是“长风破浪会有时”，实现自我理想的这一天总会来到的，应为这样的未来痛饮高歌，破费又算得了什么。“千金散尽还复来！”这又是一个高度自信的惊人之句，能驱使金钱而不为金钱所使，真足令一切凡夫俗子们咋舌。诗如其人，想诗人“曩者（过去）游维扬，不逾一年（不到一年），散金三十余万”（《上安州裴长史书》），是何等豪举。故此句深蕴在骨子里的豪情，绝非装腔作势者可得其万一。\n\n　　与此气派相当，作者描绘了一场盛筵，那决不是“菜要一碟乎，两碟乎？酒要一壶乎，两壶乎？”而是整头整头地“烹羊宰牛”，不喝上“三百杯”决不甘休。筵宴中展示的痛快气氛，诗句豪壮。\n\n　　至此，狂放之情趋于高潮，诗的旋律加快。诗人那眼花耳热的醉态跃然纸上，恍然使人如闻其高声劝酒：“岑夫子，丹丘生，将进酒，杯莫停！”几个短句忽然加入，不但使诗歌节奏富于变化，而且写来逼肖席上声口。既是生逢知己，又是酒逢对手，不但“忘形到尔汝”，诗人甚而忘却是在写诗，笔下之诗似乎还原为生活，他还要“与君歌一曲，请君为我倾耳听”。以下八句就是诗中之歌了。这着想奇之又奇，纯系神来之笔。 “钟鼓馔玉”意即富贵生活（富贵人家吃饭时鸣钟列鼎，食物精美如玉），可诗人以为“不足贵”，并放言“但愿长醉不复醒”。诗情至此，便分明由狂放转而为愤激。这里不仅是酒后吐狂言，而且是酒后吐真言了。以“我”天生有用之才，本当位至卿相，飞黄腾达，然而“大道如青天，我独不得出”（《行路难》）。说富贵“不足贵”，乃出于愤慨。以下“古来圣贤皆寂寞”二句亦属愤语。李白曾喟叹“自言管葛竟谁许”，称自己有管仲之才，诸葛亮之智却没人相信，所以说古人“寂寞”，同时表现出自己“寂寞”。因此才情愿醉生梦死长醉不醒了。这里，诗人已是用古人酒杯，浇自己块垒了。\n\n　　说到“唯有饮者留其名”，便举出“陈王”曹植作代表。并化用其《名都篇》“归来宴平乐，美酒斗十千”之句。古来酒徒历历，而偏举“陈王”，这与李白一向自命不凡分不开，他心目中树为榜样的是谢安之类高级人物，而这类人物中，“陈王”与酒联系较多。这样写便有气派，与前文极度自信的口吻一贯。三国诗人曹植在《名都篇》中描写洛阳饮宴时说：“归来宴平乐，美酒斗十千。”曹植被称为才高八斗（朝宋文学家谢灵运：“天下才有一石，曹子建独占八斗，我得一斗，天下共分一斗。”），尽管身怀利器，抱负不凡，却在政治上受到来自亲哥哥魏文帝曹丕的打击，郁郁不得志。“陈王”曹植于丕、睿两朝备受猜忌，有志难展，亦激起诗人的同情。一提“古来圣贤”，二提“陈王”曹植，满纸不平之气。此诗开始似只涉人生感慨，而不染政治色彩，其实全篇饱含一种深广的忧愤和对自我的信念。诗情所以悲而不伤，悲而能壮，即根源于此。\n\n　　刚露一点深衷，又回到说酒了，酒兴更高。以下诗情再入狂放，而且愈来愈狂。“主人何为言少钱”，既照应“千金散尽”句，又故作跌宕，引出最后一番豪言壮语：即便千金散尽，也当不惜将出名贵宝物——“五花马”（毛色作五花纹的良马）、“千金裘”来换取美酒，图个一醉方休。这结尾之妙，不仅在于“呼儿”、“与尔”，口气甚大；而且具有一种作者一时可能觉察不到的将宾作主的任诞情态。须知诗人不过是被友招饮的客人，此刻他却高踞一席，气使颐指，提议典裘当马，几令人不知谁是“主人”。浪漫色彩极浓。快人快语，非不拘形迹的豪迈知交断不能出此。诗情至此狂放至极，令人嗟叹咏歌，直欲“手之舞之，足之蹈之”。情犹未已，诗已告终，突然又迸出一句“与尔同销万古愁”，与开篇之“悲”关合，而“万古愁”的含义更其深沉。这“白云从空，随风变灭”的结尾，显见诗人奔涌跌宕的感情激流。通观全篇，真是大起大落，非如椽巨笔不办。 《将进酒》篇幅不算长，却五音繁会，气象不凡。它笔酣墨饱，情极悲愤而作狂放，语极豪纵而又沉着。诗篇具有震动古今的气势与力量，这诚然与夸张手法不无关系，比如诗中屡用巨额数目字（“千金”、“三百杯”、“斗酒十千”、“千金裘”、“万古愁”等等）表现豪迈诗情，同时，又不给人空洞浮夸感，其根源就在于它那充实深厚的内在感情，那潜在酒话底下如波涛汹涌的郁怒情绪。此外，全篇大起大落，诗情忽翕忽张，由悲转乐、转狂放、转愤激、再转狂放、最后结穴于“万古愁”，回应篇首，如大河奔流，有气势，亦有曲折，纵横捭阖，力能扛鼎。其歌中有歌的包孕写法，又有鬼斧神工、“绝去笔墨畦径”之妙，既不是刻意刻画和雕凿能学到的，也不是草率就可达到的境界。通篇以七言为主，而以三、五十言句“破”之，极参差错综之致；诗句以散行为主，又以短小的对仗语点染（如“岑夫子，丹丘生”，“五花马，千金裘”），节奏疾徐尽变，奔放而不流易。', poem_tags = '乐府,唐诗三百首,咏物,抒情,哲理,宴饮' WHERE poem_title = '将进酒' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '丙辰年的中秋节，高兴地喝酒直到第二天早晨，喝到大醉，写了这首词，同时思念弟弟苏辙。\n\n明月从什么时候才开始出现的？我端起酒杯遥问苍天。不知道在天上的宫殿，何年何月。我想要乘御清风回到天上，又恐怕在美玉砌成的楼宇，受不住高耸九天的寒冷。翩翩起舞玩赏着月下清影，哪像是在人间。\n月儿转过朱红色的楼阁，低低地挂在雕花的窗户上，照着没有睡意的自己。明月不该对人们有什么怨恨吧，为什么偏在人们离别时才圆呢？人有悲欢离合的变迁，月有阴晴圆缺的转换，这种事自古来难以周全。只希望这世上所有人的亲人能平安健康，即便相隔千里，也能共享这美好的月光。', poem_notes = '丙辰：指公元1076年（宋神宗熙宁九年）。这一年苏轼在密州(今山东省诸城市)任太守。\n达旦：到天亮。\n子由：苏轼的弟弟苏辙的字。\n把酒：端起酒杯。把，执、持。\n天上宫阙（què）：指月中宫殿。阙，古代城墙后的石台。\n归去：回去，这里指回到月宫里去。\n琼（qióng）楼玉宇：美玉砌成的楼宇，指想象中的仙宫。\n不胜（shèng,旧时读shēng）：经受不住。胜：承担、承受。\n弄清影：意思是月光下的身影也跟着做出各种舞姿。弄：赏玩。\n何似：何如，哪里比得上。\n转朱阁，低绮（qǐ）户，照无眠：月儿移动，转过了朱红色的楼阁，低低地挂在雕花的窗户上，照着没有睡意的人（指诗人自己）。朱阁：朱红的华丽楼阁。绮户： 雕饰华丽的门窗。\n不应有恨，何事长（cháng）向别时圆：（月儿）不该（对人们）有什么怨恨吧，为什么偏在人们分离时圆呢？何事：为什么。\n此事：指人的“欢”“合” 和月的“晴”“圆”。\n但：只。\n千里共婵（chán ）娟（juān）：只希望两人年年平安﹐虽然相隔千里，也能一起欣赏这美好的月光。共：一起欣赏。婵娟：指月亮。', poem_appreciation = '此词是中秋望月怀人之作，表达了对胞弟苏辙的无限怀念。词人运用形象描绘手法，勾勒出一种皓月当空、亲人千里、孤高旷远的境界氛围，反衬自己遗世独立的意绪和往昔的大醉，作此篇，兼怀子由。”丙辰，是公元1076年（北宋神宗熙宁九年）。当时苏轼在密州（今山东诸城）做太守，中秋之夜他一边赏月一边饮酒，直到天亮，于是做了这首《水调歌头》。苏轼一生，以崇高儒学、讲究实务为主。但他也“龆龀好道”，中年以后，又曾表示过“归依佛僧”，是经常处在儒释道的纠葛当中的。每当挫折失意之际，则老庄思想上升，借以帮助自己解释穷通进退的困惑。公元1071年（熙宁四年），他以开封府推官通判杭州，是为了权且避开汴京政争的漩涡。公元1074年（熙宁七年）调知密州，虽说出于自愿，实质上仍是处于外放冷遇的地位。尽管当时“面貌加丰”，颇有一些旷达表现，也难以遮掩深藏内心的郁愤。这首中秋词，正是此种宦途险恶体验的升华与总结。“大醉”遣怀是主，“兼怀子由”是辅。对于一贯秉持“尊主泽民”节操的作者来说，手足分离和私情，比起廷忧边患的国势来说，毕竟属于次要的伦理负荷。此点在题序中并有深微的提示。\n\n　　在大自然的景物中，月亮是很有浪漫色彩的，很容易启发人们的艺术联想。一钩新月，可联想到初生的萌芽事物；一轮满月，可联想到美好的团圆生活；月亮的皎洁，让人联想到光明磊落的人格。在月亮这一意象上集中了人类无限美好的憧憬与理想。苏轼是一位性格豪放、气质浪漫的文学家，当他抬头遥望中秋明月时，其思想情感犹如长上了翅膀，天上人间自由翱翔。反映到词里，遂形成了一种豪放洒脱的风格。\n\n　　此词上片望月，既怀逸兴壮思，高接混茫，而又脚踏实地，自具雅量高致。一开始就提出一个问题：明月是从什么时候开始有的——“明月几时有？把酒问青天。”把酒问天这一细节与屈原的《天问》和李白的《把酒问月》有相似之处。其问之痴迷、想之逸尘，确实是有一种类似的精、气、神贯注在里面。从创作动因上来说，屈原《天问》洋洋170余问的磅礴诗情，是在他被放逐后彷徨山泽、经历陵陆，在楚先王庙及公卿祠堂仰见“图画天地山川神灵”及“古贤圣怪物行事”后“呵而问之”的（王逸《楚辞章句·天问序》）。是情景触碰激荡的产物。李白的《把酒问月》诗自注是：“故人贾淳令予问之。”当也是即兴遣怀之作。苏轼此词正如小序中所言是中秋望月，欢饮达旦后的狂想之曲，亦属“伫兴之作”（王国维《人间词话》）。它们都有起得突兀、问得离奇的特点。从创作心理上来说，屈原在步入先王庙堂之前就已经是“嗟号昊旻，仰天叹息”（王逸《楚辞章句·天问序》），处于情感迷狂的精神状态，故呵问青天，“似痴非痴，愤极悲极”（胡浚源《楚辞新注求确》）。李白是“唯愿当歌对酒时，月光长照金樽里”（《把酒问月》），那种因失意怅惘的郁勃意绪，也是鼻息可闻的。苏轼此词作于丙辰年，时因反对王安石新法而自请外任密州。既有对朝廷政局的强烈关注，又有期望重返汴京的复杂心情，故时逢中秋，一饮而醉，意兴在阑珊中饶有律动。三人的创作心理实是脉络暗通的。\n\n　　苏轼把青天当做自己的朋友，把酒相问，显示了他豪放的性格和不凡的气魄。李白的《把酒问月》诗说：“青天有月来几时？我今停杯一问之。”不过李白这里的语气比较舒缓，苏轼因为是想飞往月宫，所以语气更关注、更迫切。“明月几时有？”这个问题问得很有意思，好像是在追溯明月的起源、宇宙的起源；又好像是在惊叹造化的巧妙。读者从中可以感到诗人对明月的赞美与向往。\n\n　　接下来两句：“不知天上宫阙，今夕是何年。”把对于明月的赞美与向往之情更推进了一层。从明月诞生的时候起到现在已经过去许多年了，不知道在月宫里今晚是一个什么日子。诗人想象那一定是一个好日子，所以月才这样圆、这样亮。他很想去看一看，所以接着说：“我欲乘风归去，又恐琼楼玉宇，高处不胜寒。”唐人称李白为“谪仙”，黄庭坚则称苏轼与李白为“两谪仙”，苏轼自己也设想前生是月中人，因而起 “乘风归去”之想。他想乘风飞向月宫，又怕那里的琼楼玉宇太高了，受不住那儿的寒冷。“琼楼玉宇”，语出《大业拾遗记》：“瞿乾祐于江岸玩月，或谓此中何有？瞿笑曰：‘可随我观之。’俄见月规半天，琼楼玉宇烂然。”“不胜寒”，暗用《明皇杂录》中的典故：八月十五日夜，叶静能邀明皇游月宫。临行，叶叫他穿皮衣。到月宫，果然冷得难以支持。这几句明写月宫的高寒，暗示月光的皎洁，把那种既向往天上又留恋人间的矛盾心理十分含蓄地写了出来。这里还有两个字值得注意，就是“我欲乘风归去”的“归去”。飞天入月，为什么说是归去呢？也许是因为苏轼对明月十分向往，早已把那里当成自己的归宿了。从苏轼的思想看来，他受道家的影响较深，抱着超然物外的生活态度，又喜欢道教的养生之术，所以常有出世登仙的想法。他的《前赤壁赋》描写月下泛舟时那种飘飘欲仙的感觉说：“浩浩乎如冯虚御风，而不知其所止；飘飘乎如遗世独立，羽化而登仙。”也是由望月而想到登仙，可以和这首词互相印证。词人之所以有这种脱离人世、超越自然的奇想，一方面来自他对宇宙奥秘的好奇，另一方面更主要的是来自对现实人间的不满。人世间有如此多的不称心、不满意之事，迫使词人幻想摆脱这烦恼人世，到琼楼玉宇中去过逍遥自在的神仙生活。苏轼后来贬官到黄州，时时有类似的奇想，所谓“小舟从此逝，江海寄余生”。然而，在词中这仅仅是一种打算，未及展开，便被另一种相反的思想打断：“又恐琼楼玉宇，高处不胜寒”。这两句急转直下，天上的“琼楼玉宇”虽然富丽堂皇，美好非凡，但那里高寒难耐，不可久居。词人故意找出天上的美中不足，来坚定自己留在人间的决心。一正一反，更表露出词人对人间生活的热爱。同时，这里依然在写中秋月景，读者可以体会到月亮的美好，以及月光的寒气逼人。这一转折，写出词人既留恋人间又向往天上的矛盾心理。这种矛盾能够更深刻地说明词人留恋人世、热爱生活的思想感情，显示了词人开阔的心胸与超远的志向，因此为歌词带来一种旷达的作风。\n\n　　但苏轼毕竟更热爱人间的生活，“起舞弄清影，何似在人间！”与其飞往高寒的月宫，还不如留在人间趁着月光起舞呢！“清影”，是指月光之下自己清朗的身影。“起舞弄清影”，是与自己的清影为伴，一起舞蹈嬉戏的意思。李白《月下独酌》说：“我歌月徘徊，我舞影零乱。”苏轼的“起舞弄清影”就是从这里脱胎出来的。“高处不胜寒”并非作者不愿归去的根本原因，“起舞弄清影，何似在人间”才是根本之所在。与其飞往高寒的月宫，还不如留在人间，在月光下起舞，最起码还可以与自己清影为伴。这首词从幻想上天写起，写到这里又回到热爱人间的感情上来。从“我欲”到“又恐”至“何似”的心理转折开阖中，展示了苏轼情感的波澜起伏。他终于从幻觉回到现实，在出世与入世的矛盾纠葛中，入世思想最终占了上风。“何似在人间”是毫无疑问的肯定，雄健的笔力显示了情感的强烈。\n\n　　下片怀人，即兼怀子由，由中秋的圆月联想到人间的离别，同时感念人生的离合无常。“转朱阁，低绮户，照无眠。”转和低都是指月亮的移动，暗示夜已深沉。月光转过朱红的楼阁，低低地穿过雕花的门窗，照到了房中迟迟未能入睡之人。这里既指自己怀念弟弟的深情，又可以泛指那些中秋佳节因不能与亲人团圆以至难以入眠的一切离人。“无眠”是泛指那些因为不能和亲人团圆而感到忧伤，以致不能入睡的人。月圆而人不能圆，这是多么遗憾的事啊！于是词人便无理地埋怨明月说：“不应有恨，何事长向别时圆？”明月您总不该有什么怨恨吧，为什么老是在人们离别的时候才圆呢？相形之下，更加重了离人的愁苦了。这是埋怨明月故意与人为难，给人增添忧愁，无理的语气进一步衬托出词人思念胞弟的手足深情，却又含蓄地表示了对于不幸的离人们的同情。\n\n　　接着，诗人把笔锋一转，说出了一番宽慰的话来为明月开开脱：“人有悲欢离合，月有阴晴圆缺，此事古难全。”人固然有悲欢离合，月也有阴晴圆缺。她有被乌云遮住的时候，有亏损残缺的时候，她也有她的遗憾，自古以来世上就难有十全十美的事。既然如此，又何必为暂时的离别而感到忧伤呢？词人毕竟是旷达的，他随即想到月亮也是无辜的。既然如此，又何必为暂时的离别而忧伤呢？这三句从人到月、从古到今做了高度的概括。从语气上，好像是代明月回答前面的提问；从结构上，又是推开一层，从人、月对立过渡到人、月融合。为月亮开脱，实质上还是为了强调对人事的达观，同时寄托对未来的希望。因为，月有圆时，人也有相聚之时。很有哲理意味。\n\n　　词的最后说：“但愿人长久，千里共婵娟。”“婵娟”是美好的样子，这里指嫦娥，也就是代指明月。“共婵娟”就是共明月的意思，典故出自南朝谢庄的《月赋》：“隔千里兮共明月。”既然人间的离别是难免的，那么只要亲人长久健在，即使远隔千里也还可以通过普照世界的明月把两地联系起来，把彼此的心沟通在一起。“但愿人长久”，是要突破时间的局限；“千里共婵娟”，是要打通空间的阻隔。让对于明月的共同的爱把彼此分离的人结合在一起。古人有“神交”的说法，要好的朋友天各一方，不能见面，却能以精神相通。“千里共婵娟”也可以说是一种神交了！这两句并非一般的自慰和共勉，而是表现了作者处理时间、空间以及人生这样一些重大问题所持的态度，充分显示出词人精神境界的丰富博大。王勃有两句诗：“海内存知己，天涯若比邻。”意味深长，传为佳句，与“千里共婵娟”有异曲同工之妙。另外，张九龄的《望月怀远》说：“海上生明月，天涯共此时。”许浑的《秋霁寄远》说：“唯应待明月，千里与君同。”都可以互相参看。但愿人人年年平安，相隔千里也能共享着美好的月光，表达了作者的祝福和对亲人的思念，表现了作者旷达的态度和乐观的精神。苏轼就是把前人的诗意化解到自己的作品中，熔铸成一种普遍性的情感。正如词前小序所说，这首词表达了对弟弟苏辙（字子由）的怀念之情，但并不限于此。可以说这首词是苏轼在中秋之夜，对一切经受着离别之苦的人表示的美好祝愿。\n\n　　此篇是苏词代表作之一。从艺术成就上看，它构思奇拔，畦径独辟，极富浪漫主义色彩，是历来公认的中秋词中的绝唱。从表现方面来说，词的前半纵写，后半横叙。上片高屋建瓴，下片峰回路转。前半是对历代神话的推陈出新，也是对魏晋六朝仙诗的递嬗发展。后半纯用白描，人月双及。它名为演绎物理，实则阐释人事。笔致错综回环，摇曳多姿。从布局方面来说，上片凌空而起，入处似虚；下片波澜层叠，返虚转实。最后虚实交错，纡徐作结。全词设景清丽雄阔，以咏月为中心表达了游仙“归去”与直舞“人间”、离欲与入世的 盾和困惑，以及旷达自适，人生长久的乐观枋度和美好愿望，极富哲理与人情。立意高远，构思新颖，意境清新如画。最后以旷达情怀收束，是词人情怀的自然流露。情韵兼胜，境界壮美，具有很高的审美价值。此词全篇皆是佳句，典型地体现出苏词清雄旷达的风格。\n\n　　作者既标举了“ 绝尘寰的宇宙意识”，又摒弃那种“在神奇的永恒面前的错愕”情态（闻一多评《春江花月夜》语）。他并不完全超然地对待自然界的变化发展，而是努力从自然规律中寻求“随缘自娱”的生活意义。所以，尽管这首词基本上是一种情怀寥落的秋的吟咏，读来却并不缺乏“触处生春”、引人向上的韵致。\n\n　　对于这首《水调歌头》历来都是推崇备至。胡仔《苕溪渔隐丛话》认为此词是写中秋的词里最好的一首。这首词仿佛是与明月的对话，在对话中探讨着人生的意义。既有理趣，又有情趣，很耐人寻味。因此九百年来传诵不衰。吴潜《霜天晓角》：“且唱东坡《水调》，清露下，满襟雪。”《水浒传》第三十回写八月十五“可唱个中秋对月对景的曲儿”，唱的就是这 “一支东坡学士中秋《水调歌》。”可见宋元时传唱之盛。全词意境豪放而阔大，情怀乐观而旷达，对明月的向往之情，对人间的眷恋之意，以及那浪漫的色彩，潇洒的风格和行云流水一般的语言，至今还能给人们以健康的美学享受。', poem_tags = '宋词三百首,宋词精选,初中古诗,高中古诗,豪放,中秋节,月亮,怀人,祝福' WHERE poem_title = '水调歌头·明月几时有' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '东晋太元年间，武陵有个人以打渔为生。（一天）他沿着溪水划船，忘记了路程的远近。忽然遇到一片桃林，在小溪两岸几百步之内，中间没有别的树，花草鲜嫩美丽，地上的落花繁多交杂。渔人对此感到十分诧异。便继续往前走，想要走到林子的尽头。\n\n　　桃林的尽头就是溪水的源头，渔人发现了一座小山，山上有个小洞口，洞里隐隐约约的好像有点光亮。（渔人）便舍弃了船，从洞口进去。最初，山洞很狭窄，只容一个人通过；又走了几十步，突然变得开阔明亮了。（呈现在渔人眼前的是）一片平坦宽广的土地，一排排整齐的房舍，还有肥沃的田地、美丽的池塘，有桑树、竹林这类的植物。田间小路交错相通，鸡鸣狗吠的声音此起彼伏。在田野里来来往往耕种劳作的人们，男女的穿着打扮和外面的人都一样。老人和小孩，都怡然并自得其乐。\n\n　　（村里的人）看见了渔人，感到非常惊讶，问他是从哪儿来的。（渔人）把自己知道的事都详细的一一作了回答。村中人就邀请渔人到自己家里去，摆了酒、杀了鸡做饭来款待他。村子里的人听说来了这么一个人，都来打听消息。他们自己说他们的祖先为了躲避秦时的战乱，领着妻子儿女和乡邻们来到这个与世人隔绝的地方，不再从这里出去，所以跟桃花源外面的人断绝了来往。（这里的人）问如今是什么朝代，他们竟然不知道有过汉朝，更不用说魏、晋两朝了。渔人把自己所知道的事一一详细地告诉了他们。听完，他们都感叹惋惜。其余的人各自又把渔人邀请到自己家中，拿出酒菜来款待他。渔人逗留了几天后，向村里人告辞。村里的人告诉他：“（这里的情况）不值得对桃花源外的人说啊。”\n\n　　（渔人）出来以后，找到了他的船，就顺着来时的路回去，处处都做了记号。他到了郡城，去拜见太守，说了这番经历。太守立即派人跟着他去，寻找先前所做的记号，最终迷路了，再也找不到通往桃花源的路了。\n\n　　南阳有个名叫刘子骥的人，是位高尚的读书人，他听到这个消息，高兴地计划着前往桃花源。但是没有实现，他不久就病死了。后来就再也没有探访桃花源的人了。', poem_notes = '太元：东晋孝武帝的年号（376-396）\n武陵：郡名，现在湖南常德市一带。\n为业：把……作为职业，以……为生。为：作为。\n缘：沿着，顺着。\n行：前行，走。\n远近：偏义复词，仅指远。\n忽逢：忽然遇到。逢：遇到，碰见。\n夹岸：溪流两岸。\n杂：别的，其他的。\n芳草鲜美：芳香的青草鲜嫩美丽，芳：花；鲜美：鲜艳美丽。\n落英：落花。一说，初开的花。\n缤纷：繁多的样子。\n甚：很，非常。\n异之：即“以之为异”，对见到的景象感到诧异。异，意动用法，形作动，以······为异，对······感到惊异，认为······是奇异的。之，代词，指见到的景象。\n复：继续。\n前：名词活用为状语，向前。（词类活用）\n欲：想要。\n穷：形容词用做动词，穷尽，走到······的尽头。\n林：代指桃花林。\n林尽水源：林尽于水源，意思是桃林在溪水发源的地方就到头了。尽：消失（词类活用）\n便：于是，就。\n得：发现。\n仿佛：隐隐约约，形容看得不真切的样子。\n若：好像……似的。\n舍：舍弃，丢弃，文中指离开。\n初：起初，刚开始。\n才通人：仅容一人通过。才：副词，仅。\n复：又，再。\n行：行走。\n豁然开朗：形容由狭窄幽暗突然变得开阔明亮的样子。然，……的样子。豁然：形容开阔的样子；开朗：开阔明亮。\n平：平坦。\n旷：开阔；宽阔。\n屋舍：房屋。\n俨（yǎn)然：（古今异义）古义：整齐的样子。今义：形容很像;形容齐整；形容庄严。\n之：这。\n属：类。\n阡陌交通：田间小路交错相通。阡陌，田间小路，南北走向的叫阡，东西走向的叫陌。交通，交错相通。\n鸡犬相闻：（村落间）可以互相听到鸡鸣狗叫的声音。相闻：可以互相听到。\n种作：指世代耕种劳作的人。\n衣着：穿着打扮。\n悉：全，都。\n外人：指桃花源以外的世人。（有更好的翻译：另外一个世界的人，因为桃花源人从秦到晋一直与世隔绝）\n黄发垂髫(tiáo)：指老人和小孩。黄发，古时认为老人头发由白转黄是长寿的象征，这指老人。垂髫，古时小孩不扎结头发，头发下垂，这里指小孩子。（借代修辞）髫，小孩垂下的短发。\n并：都。\n怡然：愉快、高兴的样子。\n乃大惊：于是很惊讶。乃：于是。大：很，非常。\n从来：从……地方来。\n具：全都。\n之：代词，指代桃源人所问问题。\n要(yāo)：通“邀”，邀请。（通假字）\n咸：副词，都，全。\n问讯：打听消息。\n云：说。\n先世：祖先。\n率：率领。\n妻子：（古今异义）古义：指妻子、儿女。“妻”“子”是两个词，不是现代汉语的“妻子”今义：男子的配偶。\n邑人：同县的人\n绝境：（古今异义）古义：与人世隔绝的地方。 今义：没有明显出路的困境；进退维谷的境地。 绝：绝处。\n复：再，又。\n焉：兼词，相当于“于之”，“于此”，从这里。\n遂：于是。\n间隔：隔断，隔绝。\n今：现在。\n乃（乃不知有汉的乃）：竟，竟然。\n无论：不要说，（更）不必说。“无”“论”是两个词，不同于现在汉语的“无论”（古今异义）。\n为：给。\n具言：详细地说。\n所闻：指渔人所知道的世事。闻：知道，听说。\n叹惋：感叹，惋惜。\n余：其余，剩余。\n延至：邀请到。延，邀请。\n至：到。\n停：停留。\n辞：辞别。\n去：离开。\n语：告诉。\n不足：不值得。（古今异义）\n为：介词，向、对。\n既：已经。\n便扶向路：就顺着旧的路（回去）。扶：沿着、顺着。向：从前的、旧的。\n处处志之：处处都做了标记。志：动词，做标记。（词类活用)\n及：到达。\n郡下：太守所在地，指武陵。\n诣(yì)太守：指拜见太守。诣，到。特指到尊长那里去。\n如此：像这样，指在桃花源的见闻。\n即：立即。\n遣：派遣。\n寻向所志：寻找先前所做的标记。寻，寻找。 向，先前。 志（名词）,标记。（所+动词译为名词）\n遂：终于。\n复：再。\n得：取得，获得，文中是找到的意思。\n高尚：品德高尚。\n士：隐士。\n也：表判断。\n欣然：高兴的样子。\n规： 计划，打算。（词类活用）\n未：没有。\n果：实现。\n未果：没有实现。\n寻：不久。\n终：死亡。\n问津：问路，这里是探访，访求的意思。津：本义渡口。', poem_appreciation = '陶渊明作诗，擅长白描，文体省净，语出自然。《桃花源记》也具有这种艺术风格。它虽是虚构的世外仙境，但由于采用写实手法，虚景实写，给人以真实感，仿佛实有其人，真有其事。全文以武陵渔人行踪为线索，像小说一样描述了溪行捕鱼、桃源仙境、重寻迷路三段故事。第一段以“忘”、“忽逢”、“甚异”、“欲穷”四个相承续的词语生动揭示出武陵渔人一连串的心理活动。“忘”字写其一心捕鱼，无意于计路程远近，又暗示所行已远。其专注于一而忘其余的精神状态，与“徐行不记山深浅”的妙境相似。“忽逢”与“甚异”相照应，写其意外见到桃花林的惊异神情，又突出了桃花林的绝美景色。“芳草鲜美，落英缤纷”两句，乃写景妙笔，色彩绚丽，景色优美，仿佛有阵阵清香从笔端溢出，造语工丽而又如信手拈来。第二段先以数语描述发现仙境经过。“林尽水源，便得一山”，点明已至幽迥之地；“山有小口，仿佛若有光”，暗示定非寻常去处。渔人的搜寻目光、急切心情也映带出来。及至通过小口狭道，写到“豁然开朗”，又深有柳暗花明的韵致。进入桃源仙境之后，先将土地、屋舍、良田、美池、桑竹、阡陌、鸡鸣犬吠诸景一一写来，所见所闻，历历在目。然后由远而近，由景及人，描述桃源人物的往来种作、衣着装束和怡然自乐的生活，勾出一幅理想的田园生活图景。最后写桃源人见到渔人的情景，由“大惊”而“问所从来”，由热情款待到临别叮嘱，写得情真意切，洋溢着浓郁的生活气息。第三段先写渔人在沿着来路返回途中“处处志之”，暗示其有意重来。“诣太守，说如此”，写其违背桃源人“不足为外人道也”的叮嘱。太守遣人随往的“不复得路”和刘子骥的规往不果，都是着意安排的情节，明写仙境难寻，暗写桃源人不愿“外人”重来。对桃源仙境，世俗之人寻访无着也不再问津了，而陶渊明自己却从来没有停止过追求，在《桃花源诗》的结尾处就剖露了“愿言蹑轻风，高举寻吾契”的心愿。他以桃花源人为志趣相合的契友，热切期望与之共同生活于桃花源中。\n\n　　陶渊明成功地运用了虚景实写的手法，使人感受到桃源仙境是一个真实的存在，显示出高超的叙事写景的艺术才能。但《桃花源记》的艺术成就和魅力绝不仅限于此，陶渊明也不仅仅是企望人们确认其为真实的存在。所以，在虚景实写的同时，又实中有虚，有意留下几处似无非无，似有非有，使人费尽猜想也无从寻求答案的话题。桃源人的叮嘱和故事结尾安排的“不复得路”、“规往未果”等情节，虚虚实实，徜恍迷离，便是这些话题中最堪寻味之笔。它所暗示于世人的是似在人间非在人间，不是人间胜似人间，只可于无意中得之而不可于有意中求之，似乎与“此中有真意，欲辨已忘言”有着某种微妙的内在联系。这虚渺灵奥之区始终蒙着一层神秘的面纱，“借问游方士，焉测尘嚣外”，世人是难以揭晓的。它的开而复闭，渔人的得而复失，是陶渊明有意留下的千古之谜，“惹得诗人说到今”。可是，他又在《桃花源诗》中透露了一点消息，说“一朝敞神界”之所以“旋复还幽蔽”，乃是因为“淳薄既异源”！原来桃源民风淳厚，人间世风浇薄，惟恐“使武陵太守至焉，化为争夺之场”（苏轼《和桃花源诗序》），玷污了这块化外的净土，即使像刘子骥那样的人间高尚之士，也得不到一睹仙境的机缘。\n\n　　《桃花源记》的故事和其他仙境故事有相似之处，描写了一个美好的世外仙界。不过应当强调的是，陶渊明所提供的理想模式有其特殊之处：在那里生活着的其实是普普通通的人，一群避难的人，而不是神仙，只是比世人多保留了天性的真淳而已；他们的和平、宁静、幸福，都是通过自己的劳动取得的。古代的许多仙话，描绘的是长生和财宝，桃花源里既没有长生也没有财宝，只有一片农耕的景象。陶渊明归隐之初想到的还只是个人的进退清浊，写《桃花源记》时已经不限于个人，而想到整个社会的出路和广大人民的幸福。陶渊明迈出这一步与多年的躬耕和贫困的生活体验有关。虽然桃花源只是空想，只是作者理想当中的社会，但是能提出这个空想是难能可贵的。\n\n　　此文艺术构思精巧，借武陵渔人行踪这一线索，把现实和理想境界联系起来。采用虚写、实写相结合手法，也是其一个特点。增添了神秘感。语言生动简练、隽永，看似轻描淡写，但其中的描写使得景物历历在目，令人神往。文章有详有略，中心突出。', poem_tags = '初中文言文,古文观止,生活,理想' WHERE poem_title = '桃花源记' AND poem_author = '陶渊明';
UPDATE edu_poem SET poem_translation = '山不在于高，有了神仙就出名。水不在于深，有了龙就显得有了灵气。这是简陋的房子，只是我（住屋的人）品德好（就感觉不到简陋了）。长到台阶上的苔痕颜色碧绿；草色青葱，映入帘中。到这里谈笑的都是知识渊博的大学者，交往的没有知识浅薄的人，可以弹奏不加装饰的古琴，阅读佛经。没有奏乐的声音扰乱双耳，没有官府的公文使身体劳累。南阳有诸葛亮的草庐，西蜀有扬子云的亭子。孔子说：有什么简陋的呢?', poem_notes = '陋室：简陋的屋子。铭：古代刻在器物上用来警戒自己或称述功德的文字，叫“铭”，后来就成为一种文体。这种文体一般都是用骈句，句式较为整齐，朗朗上口。\n在：在于，动词。\n名：出名，著名，名词用作动词。\n灵（líng）：名词作动词，显得有灵气。\n斯是陋室（lòu shì）：这是简陋的屋子。斯：指示代词，此，这。是：表肯定的判断动词。陋室：简陋的屋子，这里指作者自己的屋子。\n惟吾德馨（xīn）：只因为（陋室铭）的铭文（就不感到简陋了）。惟：只。吾：我，这里是指（陋室铭）的铭文。馨：散布很远的香气，这里指（品德）高尚。《尚书·君陈》：“黍稷非馨，明德惟馨。”。\n苔痕上阶绿，草色入帘青：苔痕碧绿，长到阶上；草色青葱，映入帘里。上：长到；入：映入。\n鸿儒（hóng rú）：大儒，这里指博学的人。鸿：同“洪”，大。儒，旧指读书人。\n白丁：平民。这里指没有什么学问的人。\n调（tiáo）素琴：弹奏不加装饰的琴。调：调弄，这里指弹（琴）。素琴：不加装饰的琴。\n金经：现今学术界仍存在争议，有学者认为是指佛经（《金刚经》），也有人认为是装饰精美的经典（《四书五经》），但就江苏教育出版社的语文书则指的是佛经（《金刚经》）而安徽考察则是后者。金：珍贵的。金者贵义，是珍贵的意思，儒释道的经典都可以说是金经。\n丝竹：琴瑟、箫管等乐器的总称，“丝”指弦乐器，“竹”指管乐器。这里指奏乐的声音。\n之：语气助词，不译。用在主谓间，取消句子的独立性。\n乱耳：扰乱双耳。乱：形容词的使动用法，使……乱，扰乱。\n案牍（dú）：（官府的）公文，文书。\n劳形：使身体劳累（“使”动用法）。劳：形容词的使动用法，使……劳累。形：形体、身体。\n南阳：地名，今河南省南阳市。诸葛亮在出山之前，曾在南阳卧龙岗中隐居躬耕。\n诸葛亮，字孔明，三国时蜀汉丞相，著名的政治家和军事家，出仕前曾隐居南阳卧龙岗中。扬雄：字子云，西汉时文学家，蜀郡成都人。庐：简陋的小屋子。\n孔子云：孔子说，云在文言文中一般都指说。\n何陋之有：即“有何之陋”，属于宾语前置。之，助词，表示强烈的反问，宾语前置的标志，不译。\n谈笑有鸿儒：谈笑间都是学识渊博的人。鸿：大', poem_appreciation = '整体评析 　　铭是古代一种刻于金石上的押韵文体，多用于歌功颂德与警戒自己。明白了铭的意思，也就明白了题意，作者托物言志，通过对居室的描绘，极力形容陋室的不陋，“斯是陋室，惟吾德馨”这一中心，实际上也就是借陋室之名行歌颂道德品质之实，表达出室主人高洁傲岸的节操和安贫乐道的情趣。\n\n　　《陋室铭》即开篇以山水起兴，水可以不在深，只要有了仙龙就可以出名，那么居处虽然简陋，却因主人的有“德”而“馨”，也就是说陋室因为有道德品质高尚的人存在当然也能出名，声名远播，刻金石以记之。山水的平凡因仙龙而生灵秀，那么陋室当然也可借道德品质高尚之士播洒芬芳。此种借力打力之技，实为绝妙，也可谓作者匠心独具。特别是以仙龙点睛山水，构思奇妙。“斯是陋室，唯吾德馨”，由山水仙龙入题，作者笔锋一转，直接切入了主题，看引论铺下了基础。也点出了陋室不陋的原因，其原因是德馨二字。\n\n　　在此点看出，作者写此随笔是经过反复思考的，绝对不是一时的灵感冲动。绝句可以是灵光乍现，而连接无暇却是平时的功底积累与反复推敲了。4—7句刁难下祭出此文，并将其刻于石上，具有很强烈的针锋相对的性质。从全文的写作手法来看，通篇以“比”的手法一气呵成，而不是烘托。那么“苔痕”和“谈笑”二句究竟在说什么呢？ 青苔在石阶上（照样）绿意盎然，野草在荒地里（依然）郁郁青青。言下之意是什么呢？我刘禹锡在哪里都不改本色，我所交往的都是有修养的饱学之士，没有（你们这些）无学之辈。作者以青苔和野草来比喻自己独立的人格，这是气节的写照，是不屈的宣言。\n\n　　如果说本文的1~3句是一种铺垫，那么4~7句则进入了真正的对抗。作者以诗一般优美的语言展示了自己的铮铮傲骨，同时，也对势利小人进行了无情的鞭挞。\n\n　　“南阳诸葛庐，西蜀子云亭”作者借诸葛亮的草庐，西蜀扬子云的玄亭作类比，引出自己的陋室，及人为自己的楷模，希望自己也能如同他们一样拥有高尚的德操，反映自己以古代贤人自况的思想，同时暗示了陋室不陋。实际上刘禹锡这样写还有另一层深意，即诸葛亮是闲居卧龙草庐以待明主出山。而扬雄呢？却是淡薄于功名富贵，潜心修学之士，虽官至上品，然他对于官职的起起落落与金钱的淡泊，却是后世的典范。作者引用此二人之意，他想表达的意思是：处变不惊、处危不屈、坚守节操、荣辱从容的意思。既不愿与世俗同流合污，又想逢明主一展抱负，若无明主，也甘于平淡的那种志向吧。这结合作者官场的起起落落，是比较符合实际情况的。\n\n　　结句引用“孔子云：何陋之有？”，引古人之言， 收束全篇， 说明陋室“不陋”。表达了他对当时封建礼教的最高道德品质的追求。用圣人肯定的操守来规范要求自己，也许就是刘禹锡对自己的道德品质的最高要求。这样的结句，不说其中的内容是何种意思，但结合题意，却是妙手天成。因为封建礼教是以儒家的道德标准为最高道德标准的，孔圣人的肯定，也就为他道德品质的论注下了最好的定论，论文当有论据，而引孔圣人言作为论据，无疑在当时是最好的论据，充分而不可辩驳。\n\n分层评析 　　文章内容包括三层意思。\n\n　　第一层（从开头至“惟吾德馨”）以类比的方式引出文章主旨。文章开篇即以“山不在高，有仙则名。水不在深，有龙则灵”的大气之语开篇，既显得出手不凡，也为以后的陋室歌功颂德埋下了伏笔。山可以不在高低，水可以不在深浅，只要有了仙、龙就可以出名，那么陋室因为有道德品质高尚的人存在当然也能出名。“斯是陋室，惟吾德馨”，由山、水、仙、龙入题，作者笔锋一转，直接切入了主题，看似有些突兀，但回头一看，却又浑然一体，因为上面的对比句恰好为这句的引论铺下了基础。山、水的平凡因仙、龙而生灵秀，那么陋室当然也可借道德品质高尚之士播洒芬芳。以类比的方式开头，引出陋室的寓意，以“德馨”统领全篇。以下文字皆由此生发。\n\n　　第二层（“苔痕上阶绿“至无案牍之劳形”）描写居室环境即日常生活。作者从周围景色入手 ，“苔痕上阶绿，草色入帘青。“描写环境宁静、雅致，令人赏心悦目。“淡笑有鸿儒，往来无白丁”是写室主人交往之雅。来来往往的都是饱学之士，没有平头百姓。这些人可以高谈阔论，纵情畅怀。“可以调素琴，阅金经。无丝竹之乱耳，无案牍之劳形”闲下来在室中可以抚琴弄弦，展卷读经修身养性。以上是作者从三方面对于一个道德品质高尚之士的生活总结。他以“苔痕上阶绿”的淡雅之色，隐寓作者的恬淡之心，又马上以“草色入帘青”的生机盎然点明恬淡中充满生机的鲜活生活状态。交朋识友，皆是同道高洁之士，抚琴研经，生活从容且又多姿。远离嘈杂的音乐，远离伤神的公务，这种闲暇的生活实在让人羡慕。这种既像隐士，又存在尘世的生活方式，是道德高尚之士羡慕的，也是凡夫俗子们向往的。也让我们看到了作者高洁傲岸的节操和安贫乐道的情趣。\n\n　　第三层：（南阳诸葛庐，西蜀子云亭），运用类比，指出此室可以与古代名贤的居室比美。作者借南阳诸葛亮的草庐，西蜀扬雄的旧居来对比自己的陋室，有引诸葛亮与扬雄为自己同道的意思，也表明了作者以这二人为自己的楷模，说明自已也有他们一样的德操与才能。以陋室比古贤的居室，不仅说明了陋室不陋，又进一步表达了作者的高洁傲岸的志趣与抱负。从诸葛亮闲居卧龙草庐以待明主、扬雄淡薄于功名富贵，潜心修学来看，刘禹锡引用此二人之意，是否还有既不愿与世俗同流合污，又想逢明主一展抱负，若无明主，也甘于平淡的那种志向呢？第四层（最后一句），总结全文，说明陋室不陋。“何陋之有？”一句，语出《论语·子罕》，原话是“君子居之，何陋之有？”作者截取后一句引为证据，作全文的总结，暗含着以“君子”自居的意思而又不陋痕于文字上，更进一步突出了他那高洁傲岸的志趣与抱负。“何陋之有”回应上文。陋室不陋，关键在于“君子居之”，也即铭文一开头所说“惟吾德馨”。这个结语引经据典，显得警策有力，把个“陋”字彻底翻过来了。铭文一般都压韵，并常用排比、对偶句。本文为骈体文，就用了名、灵、馨、青、丁、经、形、亭等字韵脚，使文章句式整齐，节奏分明，音韵谐美;而又变化有致，不拘一格，读起来抑扬顿挫，毫无呆板之感。除末句外，全篇都是骈句，韵脚是 名、灵、馨、青、丁、经、形、亭等字。', poem_tags = '初中文言文,古文观止,咏物,赞美,品格' WHERE poem_title = '陋室铭' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '水上、陆地上各种草本木本的花，值得喜爱的非常多。晋代的陶渊明唯独喜爱菊花。从李氏唐朝以来，世人大多喜爱牡丹。我唯独喜爱莲花从积存的淤泥中长出却不被污染，经过清水的洗涤却不显得妖艳。（它的茎）中间贯通外形挺直，不牵牵连连也不枝枝节节，香气传播更加清香，笔直洁净地竖立在水中。（人们）可以远远地观赏（莲），而不可轻易地玩弄它啊。\n　　我认为菊花，是花中的隐士；牡丹，是花中的富贵者；莲花，是花中（品德高尚）的君子。唉！（对于）菊花的喜爱，陶渊明以后就很少听到了。（对于）莲花的喜爱，像我一样的还有什么人呢？（对于）牡丹的喜爱，人数当然就很多了!', poem_notes = '甚：很，十分。\n说：一种议论文的文体，可以直接说明事物或论述道理，也可以借人、借事或借物的记载来论述道理。\n之：的。\n可爱：值得怜爱。\n者：花。\n甚：很，非常。\n蕃：多。\n自：自从。\n李唐：指唐朝。唐朝皇帝姓李所以称为“李唐”。\n独：只，仅仅。\n之：主谓之间取消句子独立性。\n出：长出。\n淤（yū）泥：污泥。\n染：沾染（污秽）。\n濯（zhuó）：洗涤。\n清涟（lián）：水清而有微波，这里指清水\n妖：美丽而不端庄。\n通：贯通；通透。\n直：挺立的样子。\n中通外直：（它的茎）内空外直。\n不蔓（màn）不枝：不生蔓，不长枝\n香远益清：香气远播，愈加使人感到清雅。\n益：更加。\n清：清芬。\n亭亭净植：笔直地洁净地立在那里。　亭亭：耸立的样子。\n植：树立。\n可：只能。\n亵玩:玩弄。\n亵（xiè）：亲近而不庄重。\n焉：句末语气词，这里指当于现代汉语的‘‘啊’’ ‘‘呀’’，助词。\n谓：认为。\n隐逸者：指隐居的人。在封建社会里，有些人不愿意跟统治者同流合污，就隐居避世；\n盛：广。\n君子：指道德品质高尚的人。\n者：……的人或物。随着前面的名词而变化。\n噫：感叹词，相当于现在的“唉“。\n菊之爱：对于菊花的喜爱。之：语气助词，的。（一说为“宾语提前的标志”）\n鲜（xiǎn）：少。\n闻：听说。\n同予者何人：像我一样的还有什么人呢？\n宜乎众矣：（爱牡丹的）应当有很多人吧。\n宜乎：当然（应该）。\n宜：当。\n众：众多。', poem_appreciation = '“说”是古代的一种议论文文体，大多是借事物或一种现象来抒发作者的感想，写法上不拘一格，行文崇尚自由活泼，波澜起伏，篇幅一般长短不定，跟现代杂文颇为相似。它可以直接说明事物，阐述事理，也可以托物寓意，借物抒情。\n\n　　《爱莲说》是我国古代散文之精品。全文119字，结构严谨，笔意超越，言简意赅，情景交融，其采用“借影”笔法，以莲自喻，有着深邃的思想内容。值得知道的是，这篇选入教材的佳作是宋代哲人周敦颐于1063年（嘉佑八年）5月在虔州（今赣州）道判署内写作的。\n\n　　正如《爱莲说》抒意，周敦颐虽身居官场，却始终未曾放弃读书治学，著书立说，教育青年提携后进。宋代著名哲学家、教育家二程——程颐、程颢，便是他在赣州一手培养出来的弟子。他做官也和别人不同，“为政精密，务尽道理”，他在1045年任南安（今大余）司理参军（一种小官）时，为了一个法不当死的囚犯，和顶头上司转运使王逵据理力争，并递上辞呈，不愿为官，终于使刚愎自用的王逵有所感悟，承认自己的错误，囚不得死。周敦颐在赣州为官多年，清廉勤勉。《爱莲说》据传系他一次游览于都罗汉岩之后所作。\n\n　　从《爱莲说》一文来看，“……予独爱莲之出淤泥而不染，濯清涟而不妖，中通外直，不蔓不枝，香远益清，亭亭净植……莲，花之君子者也。”以莲喻道德高尚的人。且正是文如其人，了专祠，并在祠后建“濂溪书院”，书院内还凿有“爱莲池”。由于几经兵燹，原来书院、祠和池均已无存。此篇文章写出了作者洁身自好、不甘屈服于世俗的高尚情操，表现了作者的“出淤泥而不染”，从而与文章中所讽刺的庸人、俗人构成了鲜明的对比。\n\n　　淳熙六年（1179年），朱熹任南康（今星子县）郡守，曾在庐山的濂溪书院中赞叹周敦颐一生不与黑暗势力同流合污；黄庭坚亦称赞他“人品甚高”，如“光风霁月”。后来，赣州人为纪念他，建立了濂溪祠，刻周敦颐的图像及一些文章于石壁。此时，周敦颐的曾孙周直卿来到九江，把他曾祖写的《爱莲说》墨本送赠，于是赣州人就在书院莲池旁壁上摹刻了此文，流传千古。', poem_tags = '初中文言文,莲花,品格,抒怀' WHERE poem_title = '爱莲说' AND poem_author = '周敦颐';
UPDATE edu_poem SET poem_translation = '北方的风光，千万里冰封冻，千万里雪花飘。望长城内外，只剩下无边无际白茫茫一片；宽广的黄河上下，顿时失去了滔滔水势。山岭好像银白色的蟒蛇在飞舞，高原上的丘陵好像许多白象在奔跑，它们都想试一试与老天爷比比高。要等到晴天的时候，看红艳艳的阳光和白皑皑的冰雪交相辉映，分外美好。\n　　江山如此媚娇，引得无数英雄竞相倾倒。只可惜秦始皇、汉武帝，略差文学才华；唐太宗、宋太祖，稍逊文治功劳。称雄一世的人物成吉思汗，只知道拉弓射大雕。这些人物全都过去了，数一数能建功立业的英雄人物，还要看今天的人们。', poem_notes = '北国：该词源于中国古代的分裂时期，如宋称辽、金为北国，东晋称十六国等为北国，南北朝时代南方的各朝代称在北方与之对抗的各朝代为北国等。毛泽东诗中的“北国”使人在不觉中产生出一种我国疆土广大的民族自豪感。\n雪：这首词作于红一方面军一九三六年二月由陕北准备东渡黄河进入山西省西部的时候。作者在一九四五年十月七日给柳亚子信中说，这首词作于“初到陕北看见大雪时”。\n惟：只。\n馀：剩下。此字一作“余”，但目前刊出的书法作品中写作“馀”，以此为准。\n莽莽：无边无际。\n大河上下：大河，指黄河。大河上下，犹言整条黄河。\n顿失滔滔：（黄河）立刻失去了波涛滚滚的气势。描写黄河水结冰的景象。\n山舞银蛇，原驰蜡象：群山好像（一条条）银蛇在舞动。高原（上的丘陵）好像（许多）白象在奔跑。“原”指高原，即秦晋高原。蜡象，白色的象。\n天公：指天，即命运。\n须：等到；需要。\n红装素裹：形容雪后天晴，红日和白雪交相辉映的壮丽景色。红装，原指妇女的艳装，这里指红日为大地披上了红装。素裹，原指妇女的淡装，这里指皑皑白雪覆盖着大地。\n分外妖娆：格外婀娜多姿。\n竞折腰：折腰，倾倒，躬着腰侍候。这里是说争着为江山奔走操劳。\n秦皇：秦始皇嬴政（前259~前210），秦朝的创业皇帝。\n汉武：汉武帝刘彻（前156~前87），汉朝功业最盛的皇帝。\n略输文采：文采本指辞藻、才华。“略输文采”，是说秦皇汉武，武功甚盛，对比之下，文治方面的成就略有逊色。\n唐宗：唐太宗李世民（599~649），唐朝的建立统一大业的皇帝。\n宋祖：宋太祖赵匡胤（927~976），宋朝的创业皇帝。\n稍逊风骚：意近“略输文采”。风骚，本指《诗经》里的《国风》和《楚辞》里的《离骚》，后来泛指文章辞藻。\n一代天骄：指可以称雄一世的英雄人物，泛指非常著名，有才能的人物。天骄，“天之骄子”的省略语。意思是上天所骄纵宠爱的人，成吉思汗即是。汉时匈奴自称。后来也泛称强盛的少数名族或其首领。\n成吉思汗（hán）：元太祖铁木真（1162~1227）在1206年统一蒙古后的尊称，意为“强者之汗”（汗是可汗的省称，即王）。后蒙古于1271年改国号为元，成吉思汗被尊为建立元朝的始祖。成吉思汗除占领中国黄河以北地区外，还曾向西远征，占领中亚和南俄，建立了庞大的蒙古帝国。\n只识弯弓射大雕：雕，一种属于鹰类的大型猛禽，善飞难射，古代因用“射雕手”比喻高强的射手。“只识弯弓射大雕”，是说只以武功见长。\n俱往矣：都已经过去了。 俱，都。\n数风流人物：称得上能建功立业的英雄人物。数，数得着、称得上的意思。', poem_appreciation = '北国风光，千里冰封，万里雪飘\n\n　　这三句总写北国雪景，把读者引入一个冰天雪地、广袤无垠的银色世界。“北国风光”是上片内容的总领句。“千里”“万里”两句是交错说的，即千万里都是冰封，千万里都是雪飘。诗人登高远望，眼界极为广阔，但是“千里”“万里”都远非目力所及，这是诗人的视野在想像之中延伸扩展，意境更加开阔，气魄非常宏大。天地茫茫，纯然一色，包容一切。“冰封”凝然安静，“雪飘”舞姿轻盈，静动相衬，静穆之中又有飘舞的动态。\n\n　　望长城内外，惟余莽莽；大河上下，顿失滔滔\n\n　　“望”字统领下文，直至“欲与天公试比高”句。这里的“望”，有登高远眺的意思并有很大的想像成分，它显示了诗人自身的形象，使人感受到他那豪迈的意兴。“望”字之下，展现了长城、黄河、山脉、高原这些最能反映北国风貌的雄伟景观，这些景观也正是我们伟大祖国的形象。“长城内外”，这是从南到北，“大河上下”，这是自西向东，地域如此广袤，正与前面“千里”“万里”两句相照应。意境的大气磅礴，显示了诗人博大的胸怀，雄伟的气魄。“惟余莽莽”“顿失滔滔”分别照应“雪飘”“冰封”。“惟余”二字，强化了白茫茫的壮阔景象。“顿失”二字，则写出变化之速，寒威之烈，又使人联想到未冰封时大河滚滚滔滔的雄壮气势。这四句用视觉形象，赋予冰封雪飘的风光以更为具体更为丰富的直觉，更显气象的奇伟雄浑。\n\n　　山舞银蛇，原驰蜡象，欲与天公试比高\n\n　　“山舞银蛇，原驰蜡象”的动态描写，都有活泼奔放的气势。加上“欲与天公试比高”一句，表现“山”“原”与天相连，更有一种奋发的态势和竞争的活力。“山”“原”都是静物，写它们“舞”“驰”，这化静为动的浪漫想像，固然因在大雪飘飞中远望山势和丘陵绵延起伏，确有山舞原驰的动感，更因诗人情感的跃动，使他眼前的大自然也显得生气勃勃，生动活跃。\n\n　　须晴日，看红装素裹，分外妖娆\n\n　　前十句写了眼前的实景，而这三句写的是虚景，想像雪后晴日当空的景象，翻出一派新的气象。雪中的景象在苍茫中显得雄伟，雪后的景象则显得娇艳。“看”字与“望”字照应；“红装素裹”，把江山美景比做少女的衣装，形容红日与白雪交相辉映的艳丽景象。“分外妖娆”，赞美的激情溢于言表。\n\n　　江山如此多娇，引无数英雄竞折腰\n\n　　这两句是上文写景与下文议论之间的过渡。“江山如此多娇”承上，总括上片的写景，对“北国风光”作总评；“引无数英雄竞折腰”启下，展开对历代英雄的评论，抒发诗人的抱负。这一过渡使全词浑然一体，给人严丝合缝、完整无隙的感受。\n\n　　祖国的山河如此美好，难怪引得古今许多英雄人物为之倾倒，争着为统一天下而奋斗。一个“竞”字，写出英雄之间激烈的争斗，写出一代代英雄的相继崛起和衰落的经历。“折腰”的形象，展示了每位英雄人物为之倾倒的姿态，并揭示了为之奋斗的动机。\n\n　　惜秦皇汉武，略输文采；唐宗宋祖，稍逊风骚。一代天骄，成吉思汗，只识弯弓射大雕\n\n　　以“惜”字总领七个句子，展开对历代英雄人物的评论。诗人于历代帝王中举出五位很有代表性的人物，展开一幅幅历史画卷，使评论得以具体形象地展开，如同翻阅一部千秋史册，一一加以评说。一个“惜”字，定下对历代英雄人物的评论基调，饱含惋惜之情而又有批判。然而措词极有分寸，“略输文采”“稍逊风骚”，并不是一概否定。至于成吉思汗，欲抑先扬，在起伏的文势中不但有惋惜之极的意味，而且用了“只识”二字而带有嘲讽之意。“弯弓射大雕”，非常传神地表现了成吉思汗只恃武功而不知文治的形象。\n\n　　俱往矣，数风流人物，还看今朝\n\n　　“俱往矣”三字，将中国封建社会的历史一笔带过，转向诗人所处的当今时代，点出全词“数风流人物，还看今朝”的主题。“今朝”是一个新的时代，新的时代需要新的风流人物来带领。“今朝”的风流人物不负历史的使命，超越于历史上的英雄人物，具有更卓越的才能，并且必将创造空前伟大的业绩，这是诗人坚定的自信和伟大的抱负。\n\n　　这首词画面雄伟壮阔而又妖娆美好，意境壮美雄浑，气势磅礴，感情奔放，胸怀豪迈，颇能代表毛泽东诗词的豪放风格，是中国词坛杰出的咏雪抒怀之作。', poem_tags = '写雪,言志,抒情,哲理' WHERE poem_title = '沁园春·雪' AND poem_author = '毛泽东';
UPDATE edu_poem SET poem_translation = '我愤怒得头发竖了起来，帽子被顶飞了。独自登高凭栏远眺，骤急的风雨刚刚停歇。抬头远望天空，禁不住仰天长啸，一片报国之心充满心怀。三十多年来虽已建立一些功名，但如同尘土微不足道，南北转战八千里，经过多少风云人生。好男儿，要抓紧时间为国建功立业，不要空空将青春消磨，等年老时徒自悲切。\n靖康之变的耻辱，至今仍然没有被雪洗。作为国家臣子的愤恨，何时才能泯灭！我要驾着战车向贺兰山进攻，连贺兰山也要踏为平地。我满怀壮志，打仗饿了就吃敌人的肉，谈笑渴了就喝敌人的鲜血。待我重新收复旧日山河，再带着捷报向国家报告胜利的消息！', poem_notes = '怒发冲冠：气得头发竖起，以至于将帽子顶起。形容愤怒至极，冠是指帽子而不是头发竖起。\n潇潇：形容雨势急骤。\n长啸：感情激动时撮口发出清而长的声音,为古人的一种抒情举动。\n三十功名尘与土：年已三十，建立了一些功名，不过很微不足道。\n八千里路云和月：形容南征北战、路途遥远、披星戴月。\n等闲：轻易，随便。\n靖康耻：宋钦宗靖康二年（1127年），金兵攻陷汴京，虏走徽、钦二帝。\n贺兰山：贺兰山脉位于宁夏回族自治区与内蒙古自治区交界处。\n胡虏（lǔ）：秦汉时匈奴为胡虏,后世用为与中原敌对的北方部族之通称。\n朝天（阙）：朝见皇帝。天阙：本指宫殿前的楼观，此指皇帝生活的地方。', poem_appreciation = '上片写作者悲愤中原重陷敌手，痛惜前功尽弃的局面，也表达自己继续努力，争取壮年立功的心愿。\n\n　　开头五句“怒发冲冠，凭栏处、潇潇雨歇。抬望眼，仰天长啸，壮怀激烈”。起势突兀，破空而来。胸中的怒火在熊熊燃烧，不可阻遏。这时，一阵急雨刚刚停止，词人站在楼台高处，正凭栏远望。他看到那已经收复却又失掉的国土，想到了重陷水火之中的百姓，不由得“怒发冲冠”，“仰天长啸”、“壮怀激烈”。“怒发冲冠”是艺术夸张，是说由于异常愤怒，以致头发竖起，把帽子也顶起来了。“怒发冲冠”，表现出如此强烈的愤怒的感情并不是偶然的，这是作者的理想与现实发生尖锐激烈的矛盾的结果。“壮怀激烈”！啸是蹙口发出的叫声。“壮怀”，奋发图强的志向。他面对投降派的不抵抗政策，真是气愤填膺，“怒发冲冠”。岳飞之怒，是金兵侵扰中原，烧杀虏掠的罪行所激起的雷霆之怒；岳飞之啸，是无路请缨，报国无门的忠愤之啸；岳飞之怀，是杀敌为国的宏大理想和豪壮襟怀。这几句一气贯注，为我们生动地描绘了一位忠臣义士和忧国忧民的英雄形象。\n\n　　接着四句激励自己，不要轻易虚度这壮年光阴，争取早日完成抗金大业。“三十功名尘于土”，是对过去的反省。表现作者渴望建立功名、努力抗战的思想。三十岁左右正当壮年，古人认为这时应当有所作为，可是，岳飞悔恨自己功名还与尘土一样，没有什么成就。“三十”是约数，当时岳飞三十二岁。“功名”，即前面说到的攻克襄阳六郡以后建节晋升之事。宋朝以“三十之节”为殊荣。然而，岳飞梦寐以求的并不是建节封侯，身受殊荣，而是渡过黄河，收复国土，完成抗金救国的神圣事业。正如他自己所说“誓将直节报君仇”，“不问登坛万户侯”，对功名感到不过象尘土一样，微不足道。“八千里路云和月”，是说不分阴晴，转战南北，在为收复中原而战斗。是对未来的瞻望。“八千”是约数，极言沙场征战行程之远。“云和月”是特意写出，是说出师北伐是十分艰苦的，任重道远，尚须披星戴月，日夜兼程，才能“北逾沙漠，喋血虏廷”（《五岳祠盟记》），赢得最后抗金的胜利，上一句写视功名为尘土，这一句写杀敌任重道远，个人为轻，国家为重，生动地表现了作者强烈的爱国热忱。“莫等闲、白了少年头，空悲切”，这与“少壮不努力，老大徒伤悲”的意思相同，反映了作者积极进取的精神。这对当时抗击金兵，收复中原的斗争，显然起到了鼓舞斗志的作用。与主张议和，偏安江南，苟延残喘的投降派，形成了鲜明的对照。“等闲”，作随便解释。“空悲切”，即白白的痛苦。“莫等闲，白了少年头，空悲切”。这既是岳飞的自勉之辞，也是对抗金将士的鼓励和鞭策。\n\n　　词的下片运转笔端，抒写词人对于民族敌人的深仇大恨，统一祖国的殷切愿望，忠于朝廷即忠于祖国的赤诚之心。\n\n　　“靖康”是宋钦宗赵桓的年号。“靖康耻，犹未雪；臣子恨，何时灭？”突出全诗中心，由于没有雪“靖康”之耻，岳飞发出了心中的恨何时才能消除（“臣子恨，何时灭”）的感慨。这也是他要“驾长车踏破贺兰山缺”的原因。又把“驾长车、踏破贺兰山缺，”具体化了。从“驾长车”到“笑谈渴饮匈奴血”都以夸张的手法表达了对凶残敌人的愤恨之情，同时表现了英勇的信心和无畏的乐观精神。\n\n　　“壮志饥餐胡虏肉，笑谈渴饮匈奴血。”“待从头、收拾旧山河，朝天阙。”以此收尾，把收复山河的宏愿，把艰苦的征战，以一种乐观主义精神表现出来，既表达要胜利的信心，也说了对朝庭和皇帝的忠诚。岳飞在这里不直接说凯旋、胜利等，而用了“收拾旧山河”，显得有诗意又形象。\n\n　　这首词代表了岳飞“精忠报国”的英雄之志，表现出一种浩然正气、英雄气质，表现了报国立功的信心和乐观主义精神。词里句中无不透出雄壮之气，充分表现作者忧国报国的壮志胸怀。这首爱国将领的抒怀之作，情调激昂，慷慨壮烈，充分表现的中华民族不敢屈辱，奋发图强，雪耻若渴的神威，从而成为反侵略战争的名篇。', poem_tags = '宋词三百首,爱国,壮志,励志' WHERE poem_title = '满江红·写怀' AND poem_author = '岳飞';
UPDATE edu_poem SET poem_translation = '阵阵轰鸣的爆竹声中，旧的一年已经过去；和暖的春风吹来了新年，人们欢乐地畅饮着新酿的屠苏酒。\n初升的太阳照耀着千家万户，他们都忙着把旧的桃符取下，换上新的桃符。', poem_notes = '元日：农历正月初一，即春节。\n爆竹：古人烧竹子时使竹子爆裂发出的响声。用来驱鬼避邪，后来演变成放鞭炮。一岁除：一年已尽。除，逝去。\n屠苏：“指屠苏酒，饮屠苏酒也是古代过年时的一种习俗，大年初一全家合饮这种用屠苏草浸泡的酒，以驱邪避瘟疫，求得长寿。\n千门万户：形容门户众多，人口稠密。曈曈：日出时光亮而温暖的样子。\n桃：桃符，古代一种风俗，农历正月初一时人们用桃木板写上神荼、郁垒两位神灵的名字，悬挂在门旁，用来压邪。也作春联。', poem_appreciation = '此诗描写春节除旧迎新的景象。一片爆竹声送走了旧的一年，饮着醇美的屠苏酒感受到了春天的气息。初升的太阳照耀着千家万户，家家门上的桃符都换成了新的。\n\n　　这是一首写古代迎接新年的即景之作，取材于民间习俗，敏感地摄取老百姓过春节时的典型素材，抓住有代表性的生活细节：点燃爆竹，饮屠苏酒，换新桃符，充分表现出年节的欢乐气氛，富有浓厚的生活气息。\n\n　　“爆竹声中一岁除，春风送暖入屠苏。”逢年遇节燃放爆竹，这种习俗古已有之，一直延续至今。古代风俗，每年正月初一，全家老小喝屠苏酒，然后用红布把渣滓包起来，挂在门框上，用来“驱邪”和躲避瘟疫。\n\n　　第三句“千门万户曈曈日”，承接前面诗意，是说家家户户都沐浴在初春朝阳的光照之中。结尾一句描述转发议论。挂桃符，这也是古代民间的一种习俗。“总把新桃换旧符”，是个压缩省略的句式，“新桃”省略了“符”字，“旧符”省略了“桃”字，交替运用，这是因为七绝每句字数限制的缘故。\n\n　　诗是人们的心声。不少论诗者注意到，这首诗表现的意境和现实，还自有它的比喻象征意义，王安石这首诗充满欢快及积极向上的奋发精神，是因为他当时正出任宰相，推行新法。王安石是北宋时期著名的改革家，他在任期间，正如眼前人们把新的桃符代替旧的一样，革除旧政，施行新政。王安石对新政充满信心，所以反映到诗中就分外开朗。这首诗，正是赞美新事物的诞生如同“春风送暖”那样充满生机；“曈曈日”照着“千门万户”，这不是平常的太阳，而是新生活的开始，变法带给百姓的是一片光明。结尾一句“总把新桃换旧符”，表现了诗人对变法胜利和人民生活改善的欣慰喜悦之情。其中含有深刻哲理，指出新生事物总是要取代没落事物的这一规律。\n\n　　这首诗虽然用的是白描手法，极力渲染喜气洋洋的节日气氛，同时又通过元日更新的习俗来寄托自己的思想，表现得含而不露。', poem_tags = '古诗三百首,小学古诗,春节,风俗,抱负,早教古诗100首' WHERE poem_title = '元日' AND poem_author = '王安石';
UPDATE edu_poem SET poem_translation = '叹息声一声接着一声传出，木兰对着房门织布。听不见织布机织布的声音，只听见木兰在叹息。问木兰在想什么？问木兰在惦记什么？（木兰答道）我也没有在想什么，也没有在惦记什么。昨天晚上看见征兵文书，知道君主在大规模征兵，那么多卷征兵文册，每一卷上都有父亲的名字。父亲没有大儿子，木兰（我）没有兄长，木兰愿意为此到集市上去买马鞍和马匹，就开始替代父亲去征战。\n\n　　在集市各处购买马具。第二天早晨离开父母，晚上宿营在黄河边，听不见父母呼唤女儿的声音，只能听到黄河水流水声。第二天早晨离开黄河上路，晚上到达黑山头，听不见父母呼唤女儿的声音，只能听到燕山胡兵战马的啾啾的鸣叫声。\n\n　　不远万里奔赴战场，翻越重重山峰就像飞起来那样迅速。北方的寒气中传来打更声，月光映照着战士们的铠甲。将士们身经百战，有的为国捐躯，有的转战多年胜利归来。\n\n　　胜利归来朝见天子，天子坐在殿堂（论功行赏）。给木兰记很大的功勋，得到的赏赐有千百金还有余。天子问木兰有什么要求，木兰说不愿做尚书郎，希望骑上千里马，回到故乡。\n\n　　父母听说女儿回来了，互相搀扶着到城外迎接她；姐姐听说妹妹回来了，对着门户梳妆打扮起来；弟弟听说姐姐回来了，忙着霍霍地磨刀杀猪宰羊。每间房都打开了门进去看看，脱去打仗时穿的战袍，穿上以前女孩子的衣裳，当着窗子、对着镜子整理漂亮的头发，对着镜子在面部贴上装饰物。走出去看一起打仗的火伴，火伴们很吃惊，（都说我们）同行数年之久，竟然不知木兰是女孩。\n\n　　（提着兔子耳朵悬在半空中时）雄兔两只前脚时时动弹、雌兔两只眼睛时常眯着，所以容易分辨。雄雌两兔一起并排跑，怎能分辨哪个是雄兔哪个是雌兔呢？', poem_notes = '唧唧（jī jī）：纺织机的声音。一说为叹息声，意思是木兰无心织布，停机叹息。\n当户（dāng hù）：对着门。\n机杼（zhù）声：织布机发出的声音。机：指织布机。杼：织布梭（suō）子。\n惟：只。\n何：什么。\n忆：思念，惦记\n军帖（tiě)：征兵的文书。\n可汗（kè hán）：古代西北地区民族对君主的称呼\n军书十二卷：征兵的名册很多卷。十二，表示很多，不是确指。下文的“十二转”、“十二年”，用法与此相同。\n爷：和下文的“阿爷”一样，都指父亲。\n愿为市鞍(ān）马：为，为此。市，买。鞍马，泛指马和马具。\n鞯（jiān）：马鞍下的垫子。\n辔（pèi)头：驾驭牲口用的嚼子、笼头和缰绳。\n辞：离开，辞行。\n溅溅（jiān jiān）：水流激射的声音。\n旦：早晨。\n但闻：只听见\n胡骑（jì）：胡人的战马。胡，古代对北方少数民族的称呼。\n啾啾（jiū jiū）：马叫的声音。\n天子：即前面所说的“可汗”。\n万里赴戎机：不远万里，奔赴战场。戎机：指战争。\n关山度若飞：像飞一样地跨过一道道的关，越过一座座的山。度，越过。\n朔(shuò)气传金柝：北方的寒气传送着打更的声音。朔，北方。金柝（tuò），即刁斗。古代军中用的一种铁锅，白天用来做饭，晚上用来报更。\n寒光照铁衣：冰冷的月光照在将士们的铠甲上。\n明堂：明亮的的厅堂，此处指宫殿\n策勋十二转(zhuǎn)：记很大的功。策勋，记功。转，勋级每升一级叫一转，十二转为最高的勋级。十二转：不是确数，形容功劳极高。\n赏赐百千强(qiáng）：赏赐很多的财物。百千：形容数量多。强，有余。\n问所欲：问（木兰）想要什么。\n不用：不愿意做。\n尚书郎：尚书省的官。尚书省是古代朝廷中管理国家政事的机关。\n愿驰千里足：希望骑上千里马。\n郭：外城。\n扶：扶持。将：助词，不译。\n姊（zǐ）：姐姐。\n理：梳理。\n红妆（zhuāng）：指女子的艳丽装束。\n霍霍（huò huò）：模拟磨刀的声音。\n著(zhuó)：通假字 通“着”，穿。\n云鬓（bìn）：像云那样的鬓发，形容好看的头发。\n帖（tiē）花黄：帖”通假字 通“贴”。花黄，古代妇女的一种面部装饰物。\n雄兔脚扑朔，雌兔眼迷离：据说，提着兔子的耳朵悬在半空时，雄兔两只前脚时时动弹，雌兔两只眼睛时常眯着，所以容易辨认。扑朔，爬搔，扑腾。迷离，眯着眼。\n双兔傍地走，安能辨我是雄雌：两只兔子贴着地面跑，怎能辨别哪个是雄兔，哪个是雌兔呢？　42. “火”：通“伙”。古时一起打仗的人用同一个锅吃饭，后意译为同行的人。\n行：读háng。\n傍(bàng)地走：贴着地面并排跑。', poem_appreciation = '北朝长篇叙事民歌。它的产生年代及作者，从宋代起，就有不同记载和争议。始见于《文苑英华》，题为《木兰歌》，以为唐代韦元甫所作。《古文苑》题为《木兰诗》，以为“唐人诗”。宋代程大昌《演繁露》据诗中“可汗大点兵”语，认为木兰“生世非隋即唐”；而南宋严羽《沧浪诗话》则认为“朔气传金柝，寒光照铁衣”之类，“已似太白，必非汉魏人诗”。此后，历代都有人持“隋、唐人作”之说，但宋代黄庭坚已指出此诗并非韦元甫所作，而是韦“得于民间”（《题乐府〈木兰诗〉后》）。《乐府诗集》列入《梁鼓角横吹曲》，亦题《木兰诗》，云是“古辞”，并引陈释智匠《古今乐录》说：“木兰，不知名。”按《旧唐书·韦元甫传》载，韦曾任浙西观察使、淮南节度使等职（黄庭坚谓韦任朔方节度使，误）。又据《旧唐书·音乐志》所载，可知梁代和北朝乐府歌曲中都存有“燕、魏之际鲜卑歌”，且多“可汗之辞”。因此，《木兰诗》原先也可能是一首鲜卑歌。流传江南，译为汉语，曾入梁代乐府，后又散落民间，而到唐代为韦元甫重新发现，并拟作《木兰歌》一首（《文苑英华》）。至于“朔气”二句这样的对偶诗句，齐、梁诗中已经习见，自是文人加工痕迹。所以现代学者大多认为《木兰诗》产生于北魏，创作于民间。\n\n　　《木兰诗》记述了木兰女扮男装，代父从军，在战场上建立功勋，回朝后不愿做官，显然也冲击了封建社会重男轻女的偏见。它“事奇诗奇”（沈德潜《古诗源》），富有浪漫色彩，风格也比较刚健古朴，基本上保持了民歌特色。\n\n　　《木兰诗》的思想内容和艺术技巧，对后世都有深远影响。宋代乐史《太平寰宇记》载，黄州黄冈县（今湖北黄陂）有木兰山、木兰草原、木兰湖，木兰天池等木兰八景，并引杜牧《木兰庙》为证。其后，据地方志所载，在今安徽亳州、河南商丘、河北完县等地，都曾立庙奉祀木兰，反映出《木兰诗》的深刻影响。直到今天，舞台银幕上的木兰形象仍然激励人们的爱国情操。同时，早在韦元甫拟作之前，杜甫《草堂》诗抒写迁居草堂的欢欣情景，已明显汲取了《木兰诗》描述全家欢迎木兰归来的表现手法。', poem_tags = '初中古诗,初中文言文,乐府,叙事,民歌,赞美,女子,战争' WHERE poem_title = '木兰诗 / 木兰辞' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '长安沦陷，国家破碎，只有山河依旧；春天来了，人烟稀少的长安城里草木茂密。\n感伤国事，不禁涕泪四溅，鸟鸣惊心，徒增离愁别恨。\n连绵的战火已经延续了半年多，家书难得，一封抵得上万两黄金。\n愁绪缠绕，搔头思考，白发越搔越短，简直要不能插簪了。', poem_notes = '国：国都，指长安（今陕西西安）。破：陷落。山河在：旧日的山河仍然存在。\n城：长安城。草木深：指人烟稀少。\n感时：为国家的时局而感伤。溅泪：流泪。\n恨别：怅恨离别。\n烽火：古时边防报警的烟火，这里指安史之乱的战火。三月：正月、二月、三月。\n抵：值，相当。\n白头：这里指白头发。搔：用手指轻轻的抓。\n浑：简直。欲：想，要，就要。胜：经受，承受。簪：一种束发的首饰。古代男子蓄长发，成年后束发于头顶，用簪子横插住，以免散开。', poem_appreciation = '“国破山河在，城春草木深。”诗篇一开头描写了春望所见：山河依旧，可是国都已经沦陷，城池也在战火中残破不堪了，乱草丛生，林木荒芜。诗人记忆中昔日长安的春天是何等的繁华，鸟语花香，飞絮弥漫，烟柳明媚，游人迤逦，可是那种景象今日已经荡然无存了。一个“破”字使人怵目惊心，继而一个“深”字又令人满目凄然。诗人写今日景物，实为抒发人去物非的历史感，将感情寄寓于物，借助景物反托情感，为全诗创造了一片荒凉凄惨的气氛。“国破”和“城春”两个截然相反的意象，同时存在并形成强烈的反差。“城春”当指春天花草树木繁盛茂密，烟景明丽的季节，可是由于“国破”，国家衰败，国都沦陷而失去了春天的光彩，留下的只是颓垣残壁，只是“草木深”。“草木深”三字意味深沉，表示长安城里已不是市容整洁、井然有序，而是荒芜破败，人烟稀少，草木杂生。这里，诗人睹物伤感，表现了强烈的黍离之悲。\n\n　　“感时花溅泪，恨别鸟惊心。”花无情而有泪，鸟无恨而惊心，花鸟是因人而具有了怨恨之情。春天的花儿原本娇艳明媚，香气迷人；春天的鸟儿应该欢呼雀跃，唱着委婉悦耳的歌声，给人以愉悦。“感时”、“恨别”都浓聚着杜甫因时伤怀，苦闷沉痛的忧愁。这两句的含意可以这样理解：我感于战败的时局，看到花开而泪落潸然；我内心惆怅怨恨，听到鸟鸣而心惊胆战。人内心痛苦，遇到乐景，反而引发更多的痛苦，就如“营我往矣，杨柳依依；今我来思，雨雪霏霏”那样。杜甫继承了这种以乐景表现哀情的艺术手法，并赋予更深厚的情感，获得更为浓郁的艺术效果。诗人痛感国破家亡的苦恨，越是美好的景象，越会增添内心的伤痛。这联通过景物描写，借景生情，移情于物。表现了诗人忧伤国事，思念家人的深沉感情。\n\n　　“烽火连三月，家书抵万金。”诗人想到：战火已经连续不断地进行了一个春天，仍然没有结束。唐玄宗都被迫逃亡蜀地，唐肃宗刚刚继位，但是官军暂时还没有获得有利形势，至今还未能收复西京，看来这场战争还不知道要持续多久。又想起自己流落被俘，扣留在敌军营，好久没有妻子儿女的音信，他们生死未卜，也不知道怎么样了。要能得到封家信多好啊。“家书抵万金”，含有多少辛酸、多少期盼，反映了诗人在消息隔绝、久盼音讯不至时的迫切心情。战争是一封家信胜过“万金”的真正原因，这也是所有受战争追害的人民的共同心理，反映出广大人民反对战争，期望和平安定的美好愿望，很自然地使人产生共鸣。\n\n　　“白头搔更短，浑欲不胜簪。”烽火连月，家信不至，国愁家忧齐上心头，内忧外患纠缠难解。眼前一片惨戚景象，内心焦虑至极，不觉于极无聊赖之时刻，搔首徘徊，意志踌躇，青丝变成白发。自离家以来一直在战乱中奔波流浪，而又身陷于长安数月，头发更为稀疏，用手搔发，顿觉稀少短浅，简直连发簪也插不住了。诗人由国破家亡、战乱分离写到自己的衰老。 “白发”是愁出来的，“搔”欲解愁而愁更愁。头发白了、疏了，从头发的变化，使读者感到诗人内心的痛苦和愁怨，读者更加体会到诗人伤时忧国、思念家人的真切形象，这是一个感人至深、完整丰满的艺术形象。\n\n　　这首诗全篇情景交融，感情深沉，而又含蓄凝练，言简意赅，充分体现了“沉郁顿挫”的艺术风格。且这首诗结构紧凑，围绕“望”字展开，前四句借景抒情，情景结合。诗人由登高远望到焦点式的透视，由远及近，感情由弱到强，就在这感情和景色的交叉转换中含蓄地传达出诗人的感叹忧愤。由开篇描绘国都萧索的景色，到眼观春花而泪流，耳闻鸟鸣而怨恨；再写战事持续很久，以致家里音信全无，最后写到自己的哀怨和衰老，环环相生、层层递进，创造了一个能够引发人们共鸣、深思的境界。表现了在典型的时代背景下所生成的典型感受，反映了同时代的人们热爱国家、期待和平的美好愿望，表达了大家一致的内在心声。也展示出诗人忧国忧民、感时伤怀的高尚情感。', poem_tags = '唐诗三百首,初中古诗,写鸟,爱国,思乡,战争,忧国忧民,早教古诗100首' WHERE poem_title = '春望' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '风雨把春天送归这里，飞舞的雪花又在迎接春天的来到。已经是冰封雪冻最寒冷的时候，悬崖边上还盛开着俏丽的梅花。\n梅花虽然俏丽，但并不炫耀自己，只是为了向人们报告春天到来的消息。等到百花盛开的时候，她将会感到无比欣慰。', poem_notes = '冰：形容极度寒冷。\n丛中笑：百花盛开时，感到欣慰和高兴。\n犹：还，仍然。\n俏：俊俏，美好的样子；（此处既能表现梅花的俏丽，又能表现革命者面对困难坚强不屈的美好情操。）\n烂漫：颜色鲜明而美丽。（文中指花全部盛开的样子）', poem_appreciation = '中国文学上，歌咏梅花的诗词作品难以计数。上自帝王贵族，下至平民文士，咏梅之作层出不穷。咏梅者或倾心于梅花之香艳，着力刻画摹写其绰约风姿；或倾慕其高洁的品质，于描写之中注入作者个人的某种情怀。富贵显达之人可咏梅以示其安逸优雅，或雕章琢句以逞才学，穷苦不遇之士亦多藉梅以寄托情怀，或抒不平之感，或表脱俗之志。梅花，因此也就以其丰富多彩的面目出现在中国古代诗词作品中，或风神绰约，动人心魄，或顾影自怜，凄清抑郁，或傲然，或妩媚，或清雅，或禾农艳，总之，因作者创作环境与意图的不同而有着不同的形态和人格情趣，毛泽东的这首《咏梅》词写于1961年月12月，词前作者自序云“读陆游咏梅词，反其意而用之”，因此，在分析这首词前，就很有必要先了解陆游原词表现了什么样的情感。\n\n　　陆游是南宋著名爱国诗人，一生创作了大量诗词作品。他的诗词作品有不少表达了爱国情感，同时，由于他的爱国主张始终遭到压制，因而他的作品中也有不得志的悲愤抑郁。这首《卜算子·咏梅》词便是一例。词中，陆游以梅花自比，表现出孤芳自赏的凄凉情调。词中的梅花虽然清香无比，但为“群芳”所妒，更兼“风”“雨”的摧残，最后“零落成泥碾作尘”，只有清香依旧。这里的梅花无疑是陆游自己的处境与人品的写照，从中既体现了他不愿苟合于流俗的清高孤傲，又有遭遇打击后的凄凉与无奈。全词悲剧气氛浓重，“断桥”、“黄昏”、“风”、“雨”，一片落寞孤寂，凄凉压抑，读之使人感到阴郁低沉。时代的悲剧，个人的不幸，使陆游《咏梅》词蒙上了深重的阴影。\n\n　　毛泽东的这首《卜算子·咏梅》词是读了陆游作品后写的，用了陆词的原调原题。同样是咏梅，正如作者自序所云，是“反其意而用之”，词中梅花的形象及词之格调情趣与陆游原词完全相反，在咏梅词中，毛泽东这首词可谓别具一格。\n\n　　开首两句“风雨送春归，飞雪迎春到”，点明梅花开放的时节，此时严冬即将过去，春之神正翩翩来临。句中虽有“风雨”、“飞雪”，但给人的感觉迥异于陆词的阴冷压抑，而是欣喜舒朗，尤其是“飞雪迎春到”，为全词定下了明快而富有生机的基调。“已是悬崖百丈冰，犹有花枝俏”，大地仍银装素裹，严冬的痕迹尚未消退，悬崖上有百丈坚冰尚未融化，可春的气息却已早早地透露了，那便是冰雪中傲然绽开的梅花。这两句将梅花放在严寒的环境中去表现，有力地衬出了梅花不畏寒冷的特性。皑皑白雪将梅花俏丽的形象衬托得更加鲜艳夺目，同时，坚冰百丈的环境也点出了梅花开放之“早”，为下面写梅花的报春作了铺垫。\n\n　　梅花先于百花而将春回大地的信息传播给了人们，所以说“俏也不争春，只把春来报”，可以想见，经历了寒冬之后的人们，猛然间看到这冰雪中俏丽的梅花时，将会多么的惊喜振奋啊。这“花枝俏”无疑是春的使者，是生命的象征，是春之女神所到之处最先撒下的花瓣，与群芳相比，她是最得风气之先的，因而也引人注目，可她却是那么谦逊，不急于要供，却默默、谦逊的的“丛中笑”，没有一丝一毫的骄矜自得，这是何等的气度！作者这里将梅花充分地人格化了，并且赋予了她以崇高的品格，读之使人倍感亲切。“待到山花烂漫时，她在丛中笑”，最后两句将梅花的形象表现得更臻完美。春之女神的足迹终于遍布大地，所到之处，鲜花烂漫，姹紫嫣红，分外绚丽。先于百花而发的梅花此刻却只是和众多的山花一样在春风中欢笑，她无意计较得失，也不追逐名利，更不愿出人头地、独占春色，这是胸襟坦荡者的豁达大度，是无私奉献者的真实写照。作者从梅花的特性中发掘出了这种高贵的品质。\n\n　　全词格调明朗轻快，拟人化的写法突出了梅花鲜明生动的品性。语言也平易流畅，显得清丽自然，毫无雕琢禾农艳之气，意境高远，耐人寻味，使人在赞赏梅花的同时，感悟到高尚的情操。在历代众多的咏梅词中，这首词立意新颖，别出机杼，独标高格，富有强烈的时代气息，给人以独特的美感。', poem_tags = '咏物,梅花,品格' WHERE poem_title = '卜算子·咏梅' AND poem_author = '毛泽东';
UPDATE edu_poem SET poem_translation = '庆历四年的春天，滕子京被降职到巴陵郡做太守。到了第二年，政事顺利，百姓和乐，各种荒废的事业都兴办起来了。于是重新修建岳阳楼，扩大它原有的规模，把唐代名家和当代人的诗赋刻在它上面。嘱托我写一篇文章来记述这件事情。\n\n　　我观看那巴陵郡的美好景色，全在洞庭湖上。它连接着远处的山，吞吐长江的水流，浩浩荡荡，无边无际，一天里阴晴多变，气象千变万化。这就是岳阳楼的雄伟景象。前人的记述（已经）很详尽了。虽然如此，那么向北面通到巫峡，向南面直到潇水和湘水，降职的官吏和来往的诗人，大多在这里聚会，（他们)观赏自然景物而触发的感情大概会有所不同吧？\n\n　　像那阴雨连绵，接连几个月不放晴，寒风怒吼，浑浊的浪冲向天空；太阳和星星隐藏起光辉，山岳隐没了形体；商人和旅客（一译：行商和客商）不能通行，船桅倒下，船桨折断；傍晚天色昏暗，虎在长啸，猿在悲啼，（这时）登上这座楼啊，就会有一种离开国都、怀念家乡，担心人家说坏话、惧怕人家批评指责，满眼都是萧条的景象，感慨到了极点而悲伤的心情。\n\n　　到了春风和煦，阳光明媚的时候，湖面平静，没有惊涛骇浪，天色湖光相连，一片碧绿，广阔无际；沙洲上的鸥鸟，时而飞翔，时而停歇，美丽的鱼游来游去，岸上的香草和小洲上的兰花，草木茂盛，青翠欲滴。有时大片烟雾完全消散，皎洁的月光一泻千里，波动的光闪着金色，静静的月影像沉入水中的玉璧，渔夫的歌声在你唱我和地响起来，这种乐趣（真是）无穷无尽啊！（这时）登上这座楼，就会感到心胸开阔、心情愉快，光荣和屈辱一并忘了，端着酒杯，吹着微风，那真是快乐高兴极了。\n\n　　唉！我曾经探求古时品德高尚的人的思想感情 ，或许不同于（以上）两种人的心情，这是为什么呢？（是由于）不因外物好坏和自己得失而或喜或悲。在朝廷上做官时，就为百姓担忧；在江湖上不做官时，就为国君担忧。这样来说在朝廷做官也担忧，在僻远的江湖也担忧。既然这样，那么他们什么时候才会感到快乐呢？他们一定会说：“在天下人忧之前先忧，在天下人乐之后才乐”。唉！没有这种人，我同谁一道呢 ？\n\n　　写于庆历六年九月十五日。', poem_notes = '记：一种文体。可以写景、叙事，多为议论。但目的是为了抒发作者的情怀和抱负（阐述作者的某些观念）。\n庆历四年：公元1044年。庆历，宋仁宗赵祯的年号。\n滕子京谪（zhé）守巴陵郡（jùn）：滕子京降职任岳州太守。滕子京，名宗谅，子京是他的字，范仲淹的朋友。古时朋友间多以字相称。\n谪戍：把被革职的官吏或犯了罪的人充发到边远的地方。在这里作为<动>被贬官，降职解释。\n守：指做州郡的长官\n越明年：到了第二年，就是庆历五年（1045）。越，到了，及。\n政通人和：政事顺利，百姓和乐。政，政事；通，通顺；和，和乐。这是赞美滕子京的话。\n百废具兴：各种荒废的事业都兴办起来了。百，不是确指，形容其多。废，这里指荒废的事业。具，通“俱”，全，皆。兴，复兴。\n乃重修岳阳楼，增其旧制：乃，于是；增，扩大。制：规模。\n唐贤今人：唐代和宋代的名人。\n属（zhǔ）予（yú）作文以记之：属，通“嘱”，嘱托、嘱咐。予，我。作文，写文章。以，用来，连词。记，记述。\n予观夫巴陵胜状：夫，指示代词，相当于“那”。胜状，胜景，好景色。\n衔（xián）远山，吞长江，浩浩汤汤：衔，衔接。吞，吞没。浩浩汤汤（shāng）：水波浩荡的样子。\n横无际涯：宽阔无边。横：广远。际涯：边。（际、涯的区别：际专指陆地边界，涯专指水的边界）。\n朝晖夕阴：或早或晚（一天里）阴晴多变化。朝，在早晨，名词做状语。晖：日光。气象，景象。万千，千变万化。\n此则岳阳楼之大观也：这就是岳阳楼的雄伟景象。此，这。则，就。大观，雄伟景象。\n前人之述备矣：前人的记述很详尽了。前人之述，指上面说的“唐贤今人诗赋”。备，详尽，完备。矣，语气词“了”。之，的。\n然则北通巫峡：然则：虽然如此，那么。\n南极潇湘：南面直到潇水、湘水。潇水是湘水的支流。湘水流入洞庭湖。南，向南。极，尽。\n迁客骚人，多会于此：迁客，被贬谪流迁的人。骚人，诗人。战国时屈原作《离骚》，因此后人也称诗人为骚人。多：大多。会，聚集。于，在。此，这里。\n览物之情，得无异乎：饱览这里景色时的感想，恐怕会有所不同吧。览：观看，欣赏。物：景物。之情：情感。,得无：恐怕/是不是。异：差别，不同。乎\n若夫淫（yín）雨霏霏（fēifēi）：若夫，用在一段话的开头以引起下文。下文的“至若”同此。“若夫”近似“像那”。“至若”近似“至于”。淫（yín）雨霏霏，连绵不断的雨。霏霏，雨（或雪）繁密的样子。\n开：解除，这里指天气放晴。\n阴风怒号（háo），浊浪排空：阴，阴冷。号，呼啸；浊，浑浊。排空，冲向天空。\n日星隐曜（yào）：太阳和星星隐藏起光辉。曜（不为耀，古文中以此曜做日光）光辉；日光。\n山岳潜形：山岳隐没了形体。岳，高大的山。潜，隐没。形，形迹。\n商旅不行：走，此指前行。\n樯（qiáng）倾楫（jí）摧：桅杆倒下，船桨折断。樯，桅杆。楫，船桨。倾，倒下。摧，折断\n薄暮冥冥（míng míng）：傍晚天色昏暗。薄，迫近。冥冥：昏暗的样子。\n斯：这，在这里指岳阳楼。\n则有去国怀乡，忧谗畏讥：则，就。有，产生……（的情感）。去国怀乡，忧谗畏讥：离开国都，怀念家乡，担心（人家）说坏话，惧怕（人家）批评指责。去，离开。国，国都，指京城。去国，离开京都，也即离开朝廷。忧，担忧。谗，谗言。畏，害怕，惧怕。讥，嘲讽。\n满目萧然，感极而悲者矣：萧然，萧条的样子。感极，感慨到了极点。而，表示顺接。者，代指悲伤感情，起强调作用。\n至若春和景明：如果到了春天气候和暖，阳光普照。至若，至于。春和，春风和煦。景，日光。明，明媚。（借代修辞）。\n波澜不惊：湖面平静，没有惊涛骇浪。惊：这里有“起”“动”的意思。\n上下天光，一碧万顷：天色湖光相接，一片碧绿，广阔无际。一，全。万顷，极言其广。\n沙鸥翔集，锦鳞游泳：沙鸥时而飞翔时而停歇，美丽的鱼在水中游来游去。沙鸥，沙洲上的鸥鸟。翔集：时而飞翔，时而停歇。集，栖止，鸟停息在树上。锦鳞，指美丽的鱼。鳞，代指鱼。游泳：或浮或沉。游：贴着水面游。泳，潜入水里游。\n岸芷（zhǐ）汀（tīng）兰：岸上与小洲上的花草。芷：香草的一种。汀：小洲,水边平地。\n郁郁：形容草木茂盛。\n而或长烟一空：有时大片烟雾完全消散。或：有时。长：大片。一，全。空：消散。\n皓月千里：皎洁的月光照耀千里。\n浮光跃金：波动的光闪着金色。这是描写月光照耀下的水波。\n静影沉璧：静静的月影像沉入水中的璧玉。这里是写无风时水中的月影。璧，圆形正中有孔的玉。\n渔歌互答：渔人唱着歌互相应答。互答，一唱一和。\n何极：哪有穷尽。何：怎么。极：穷尽。\n心旷神怡：心情开朗，精神愉快。旷，开阔。怡，愉快。\n宠辱偕（xié）忘：荣耀和屈辱一并都忘了。偕：一起。宠：荣耀。辱：屈辱。\n把酒临风：端酒面对着风，就是在清风吹拂中端起酒来喝。把：持，执。临，面对。\n洋洋：高兴得意的样子。\n嗟（jiē）夫：唉。嗟夫为两个词，皆为语气词。\n予尝求古仁人之心：尝，曾经。求，探求。古仁人，古时品德高尚的人。之，的。心，思想感情（心思）。\n或异二者之为：或许不同于（以上）两种心情。或，近于“或许”“也许”的意思，表委婉口气。异，不同于。为，这里指心理活动。二者，这里指前两段的“悲”与“喜”。\n不以物喜，不以己悲：不因为外物（好坏）和自己（得失）而或喜或悲（此句为互文）。以，因为。\n居庙堂之高则忧其民：在朝中做官担忧百姓。意为在朝中做官。庙，宗庙。堂，殿堂。庙堂：指朝廷。下文的“进”，对应“居庙堂之高”。进：在朝廷做官。\n处江湖之远则忧其君：处在僻远的地方做官则为君主担忧。处江湖之远：处在偏远的江湖间，意思是不在朝廷上做官。下文的“退”，对应“处江湖之远”。之：定语后置的标志。是：这样。退：不在朝廷做官。\n其必曰“先天下之忧而忧，后天下之乐而乐”：那一定要说“在天下人担忧之前先担忧，在天下人享乐之后才享乐”吧。先，在……之前；后，在……之后。其：指“古仁人”。而，顺承。必：一定。\n）微斯人，吾谁与归：如果没有这样的人，那我同谁一道呢？微，没有。斯人，这样的人。谁与归，就是“与谁归”。归，归依。\n时六年：庆历六年（1046年）', poem_appreciation = '洞庭天下水，岳阳天下楼。八百里洞庭湖，南接湘、资、沅、澧，北分松滋、太平等长江支流，烟波浩淼，湖山辉映，自古以 来就是令人神往的江山胜地；岳阳古称巴陵，位于洞庭湖与长江汇合之处，枕山带湖，为巴、蜀、荆、襄之要冲。北宋庆历六年（1046），一代名臣范仲淹应朋友之约，为重修的岳阳楼作记，千古名文《岳阳楼记》于是诞生。\n\n　　文章开头即切入正题，叙述事情的本末缘起。以“庆历四年春”点明时间起笔，格调庄重雅正；说滕子京为“谪守”，已暗喻对仕途沉浮的悲慨，为后文抒情设伏。下面仅用“政通人和，百废具兴”八个字，写出滕子京的政绩，引出重修岳阳楼和作记一事，为全篇文字的导引。\n\n　　第2段，格调振起，情辞激昂。先总说“巴陵胜状，在洞庭一湖”，设定下文写景范围。以下“衔远山，吞长江”寥寥数语，写尽洞庭湖之大观胜概。一“衔”一“吞”，何等的气势！“浩浩汤汤，横无际涯”，极言水波壮阔；“朝晖夕阴，气象万千”，概说阴晴变化，简练而又生动。前四句从空间角度，后两句从时间角度，写尽了洞庭湖的壮观景象。“前人之述备矣”一句承前启后，并回应前文“唐贤今人诗赋”一语。这句话既是谦虚，也暗含转机，经“然则”一转，引出新的意境，由单纯写景，到以情景交融的笔法来写“迁客骚人”的“览物之情”，从而构出全文的主体。\n\n　　3～4两段是两个排比段，并行而下，一悲一喜，一暗一明，像两股奔涌跳跃的情感之流，传达出景与情互相感应的两种截然相反的人生情境。\n\n　　第3段以“若夫”起笔，意味深长。这是一个引发议论的词，又表明了虚拟的情调，而这种虚拟又是对无数实境的浓缩、提炼和升华，颇有典型意义。“若夫”以下描写了一种悲凉的情境，由天气的恶劣写到人心的凄楚。这里用四字短句，层层渲染，渐次铺叙。淫雨、阴风、浊浪构成了主景，不但使日星无光，山岳藏形，也使商旅不前；或又值暮色沉沉、“虎啸猿啼”之际，怎能不令过往的“迁客骚人”有“去国怀乡”之慨、“忧谗畏讥”之惧、“感极而悲”之情呢？\n\n　　第4段以“至若”领起，打开了一个阳光灿烂的画面。“至若”尽管也是列举性的语气，但从音节上已变得高亢嘹亮，格调上已变得明快有力。下面的描写，虽然仍为四字短句，色调却为之一变，绘出春风和畅、景色明丽、水天一碧的良辰美景。更有鸥鸟在自由翱翔，鱼儿在欢快游荡，连无知的水草兰花也充满活力。作者以极为简练的笔墨，描摹出一幅湖光春色图，读之如在眼前。值得注意的是，这一段的句式、节奏与上一段大体相仿，却也另有变奏。“而或”一句就进一步扩展了意境，增强了叠加咏叹的意味，把“喜洋洋”的气氛推向高潮，而“登斯楼也”的心境也变成了“宠辱偕忘”的超脱和“把酒临风”的挥洒自如。\n\n　　第5段是全篇的重心，以“嗟夫”开启，兼有抒情和议论的意味。作者在列举了悲喜两种情境后，笔调突然激扬，道出了超乎这两者之上的一种更高的理想境界，那就是“不以物喜，不以己悲”！感物而动，因物悲喜虽然是人之常情，但并不是做人的最高境界。古代的仁人，就有坚定的意志，不为外界条件的变化动摇。无论是“居庙堂之高”还是“处江湖之远”，忧国忧民之心不改，“进亦忧，退亦忧”。这似乎有悖于常理，有些不可思议。作者也就此拟出一问一答，假托古圣立言，发出了“先天下之忧而忧，后天下之乐而乐”的誓言，曲终奏雅，点明了全篇的主旨。“噫！微斯人，吾谁与归”一句结语，“如怨如慕，如泣如诉”，悲凉慷慨，一往情深，令人感喟。文章最后标明写作时间，与篇首照应。\n\n　　《古文观止》的作者总评本文说：“岳阳楼大观，已被前人写尽。先生更不赘述，止将登楼者览物之情写出悲喜二意，只是翻出后文忧乐一段正论。”这一评语确实道出了本文的精神实质。', poem_tags = '辞赋精选,初中文言文,古文观止,写景,抒情,爱国' WHERE poem_title = '岳阳楼记' AND poem_author = '范仲淹';
UPDATE edu_poem SET poem_translation = '唐明皇偏好美色，当上皇帝后多年来一直在寻找美女，却都是一无所获。\n杨家有个女儿刚刚长大，十分娇艳，养在深闺中，外人不知她美丽绝伦。\n天生丽质、倾国倾城让她很难埋没世间，果然没多久便成为了唐明皇身边的一个妃嫔。\n她回眸一笑时，千姿百态、娇媚横生；六宫妃嫔，一个个都黯然失色。\n春寒料峭时，皇上赐她到华清池沐浴，温润的泉水洗涤着凝脂一般的肌肤。\n侍女搀扶她，如出水芙蓉软弱娉婷，由此开始得到皇帝恩宠。\n鬓发如云颜脸似花，头戴着金步摇。温暖的芙蓉帐里，与皇上共度春宵。\n情深只恨春宵短，一觉睡到太阳高高升起。君王深恋儿女情温柔乡，从此再也不早朝。\n承受君欢侍君饮，忙得没有闲暇。春日陪皇上一起出游，晚上夜夜侍寝。\n后宫中妃嫔不下三千人，却只有她独享皇帝的恩宠。\n金屋中梳妆打扮，夜夜撒娇不离君王；玉楼上酒酣宴罢，醉意更添几许风韵。\n兄弟姐妹都因她列土封侯，杨家门楣光耀令人羡慕。\n于是使得天下的父母都改变了心意，变成重女轻男。\n骊山上华清宫内玉宇琼楼高耸入云，清风过处仙乐飘向四面八方。\n轻歌曼舞多合拍，管弦旋律尽传神，君王终日观看，却百看不厌。\n渔阳叛乱的战鼓震耳欲聋，宫中停奏霓裳羽衣曲。\n九重宫殿霎时尘土飞扬，君王带着大批臣工美眷向西南逃亡。\n车队走走停停，西出长安才百余里。\n六军停滞不前，要求赐死杨玉环。君王无可奈何，只得在马嵬坡下缢杀杨玉环。\n贵妃头上的饰品，抛撒满地无人收拾。翠翘金雀玉搔头，珍贵头饰一根根。\n君王欲救不能，掩面而泣，回头看贵妃惨死的场景，血泪止不住地流。\n秋风萧索扫落叶，黄土尘埃已消遁，回环曲折穿栈道，车队踏上了剑阁古道。\n峨眉山下行人稀少，旌旗无色，日月无光。\n蜀地山清水秀，引得君王相思情。行宫里望月满目凄然，雨夜听曲声声带悲。\n叛乱平息后，君王重返长安，路过马嵬坡，睹物思人，徘徊不前。\n萋萋马嵬坡下，荒凉黄冢中，佳人容颜再不见，唯有坟茔躺山间。\n君臣相顾，泪湿衣衫，东望京都心伤悲，信马由缰归朝堂。\n回来一看，池苑依旧，太液池边芙蓉仍在，未央宫中垂柳未改。\n芙蓉开得像玉环的脸，柳叶儿好似她的眉，此情此景如何不心生悲戚?\n春风吹开桃李花，物是人非不胜悲；秋雨滴落梧桐叶，场面寂寞更惨凄。\n兴庆宫和甘露殿，处处萧条，秋草丛生。宫内落叶满台阶，长久不见有人扫。\n戏子头已雪白，宫女红颜尽褪。晚上宫殿中流萤飞舞，孤灯油尽君王仍难以入睡。\n细数迟迟钟鼓声，愈数愈觉夜漫长。遥望耿耿星河天，直到东方吐曙光。\n鸳鸯瓦上霜花重生，冰冷的翡翠被里谁与君王同眠?\n阴阳相隔已一年，为何你从未在我梦里来过?\n临邛道士正客居长安，据说他能以法术招来贵妃魂魄。\n君王思念贵妃的情意令他感动。他接受皇命，不敢怠慢，殷勤地寻找，八面御风。\n驾驭云气入空中，横来直去如闪电，升天入地遍寻天堂地府，都毫无结果。\n忽然听说海上有一座被白云围绕的仙山。\n玲珑剔透楼台阁，五彩祥云承托起。天仙神女数之不尽，个个风姿绰约。\n当中有一人字太真，肌肤如雪貌似花，好像就是君王要找的杨贵妃。\n道士来到金阙西边，叩响玉石雕做的院门轻声呼唤，让小玉叫侍女双成去通报。\n太真听说君王的使者到了，从帐中惊醒。穿上衣服推开枕头出了睡帐。逐次地打开屏风放下珠帘。\n半梳着云鬓刚刚睡醒，来不及梳妆就走下坛来，还歪带着花冠。\n轻柔的仙风吹拂着衣袖微微飘动，就像霓裳羽衣的舞姿，袅袅婷婷。寂\n寞忧愁颜，面上泪水长流，犹如春天带雨的梨花。\n含情凝视天子使，托他深深谢君王。马嵬坡上长别后，音讯颜容两渺茫。\n昭阳殿里的姻缘早已隔断，蓬莱宫中的孤寂，时间还很漫长。\n回头俯视人间，长安已隐，只剩尘雾。\n只有用当年的信物表达我的深情，钿盒金钗你带去给君王做纪念。\n金钗留下一股，钿盒留下一半，金钗劈开黄金，钿盒分了宝钿。\n但愿我们相爱的心，就像黄金宝钿一样忠贞坚硬，天上人间总有机会再见。\n临别殷勤托方士，寄语君王表情思，语中誓言只有君王与我知。\n当年七月七日长生殿中，夜半无人，我们共起山盟海誓。\n在天愿为比翼双飞鸟，在地愿为并生连理枝。\n即使是天长地久，也总会有尽头，但这生死遗恨，却永远没有尽期。', poem_notes = '汉皇：原指汉武帝刘彻。此处借指唐玄宗李隆基。唐人文学创作常以汉称唐。\n重色：爱好女色。倾国：绝色女子。汉代李延年对汉武帝唱了一首歌：“北方有佳人，绝世而独立。一顾倾人城，再顾倾人国。宁不知倾国与倾城，佳人难再得。”后来，“倾国倾城”就成为美女的代称。\n御宇：驾御宇内，即统治天下。汉贾谊《过秦论》：“振长策而御宇内”\n杨家有女：蜀州司户杨玄琰，有女杨玉环，自幼由叔父杨玄珪抚养，十七岁（开元二十三年）被册封为玄宗之子寿王李瑁之妃。二十七岁被玄宗册封为贵妃。白居易此谓“养在深闺人未识”，是作者有意为帝王避讳的说法。\n丽质：美丽的姿质。\n六宫粉黛：指宫中所有嫔妃。粉黛：粉黛本为女性化妆用品，粉以抹脸，黛以描眉。此代指六宫中的女性。无颜色：意谓相形之下，都失去了美好的姿容。\n华清池：即华清池温泉，在今西安市临潼区南的骊山下。唐贞观十八年（644）建汤泉宫，咸亨二年（671）改名温泉宫，天宝六载（747）扩建后改名华清宫。唐玄宗每年冬、春季都到此居住。\n凝脂：形容皮肤白嫩滋润，犹如凝固的脂肪。《诗经·卫风·硕人》语“肤如凝脂”。\n侍儿：宫女。\n新承恩泽：刚得到皇帝的宠幸。\n云鬓：《木兰诗》：“当窗理云鬓，对镜贴花黄”。形容女子鬓发盛美如云。金步摇：一种金首饰，用金银丝盘成花之形状，上面缀着垂珠之类，插于发鬓，走路时摇曳生姿。\n芙蓉帐：绣着莲花的帐子。形容帐之精美。萧纲《戏作谢惠连体十三韵》：珠绳翡翠帷，绮幕芙蓉帐。\n春宵：新婚之夜。\n佳丽三千：《后汉书·皇后纪》：自武元之后，世增淫费，乃至掖庭三千。言后宫女子之多。\n金屋：《汉武故事》记载，武帝幼时，他姑妈将他抱在膝上，问他要不要她的女儿阿娇作妻子。他笑着回答说：“若得阿娇，当以金屋藏之。”\n列土：分封土地。\n可怜：可爱，值得羡慕。\n骊宫：骊山华清宫。骊山在今陕西临潼。\n凝丝竹：指弦乐器和管乐器伴奏出舒缓的旋律。\n渔阳：郡名，辖今北京市平谷县和天津市的蓟县等地，当时属于平卢、范阳、河东三镇节度史安禄山的辖区。天宝十四载（755）冬，安禄山在范阳起兵叛乱。鼙鼓：古代骑兵用的小鼓，此借指战争。\n霓（ní）裳羽衣曲：舞曲名，据说为唐开元年间西凉节度使杨敬述所献，经唐玄宗润色并制作歌词，改用此\n名。乐曲着意表现虚无缥缈的仙境和仙女形象。\n九重城阙：九重门的京城，此指长安。烟尘生：指发生战事。阙，，意为古代宫殿门前两边的楼，泛指宫殿或帝王的住所。《楚辞·九辩》：君之门以九重。\n乘：一人一骑为一乘。\n翠华：用翠鸟羽毛装饰的旗帜，皇帝仪仗队用。司马相如《上林赋》：建翠华之旗，树灵鼍之鼓。百余里：指到了距长安一百多里的马嵬坡。\n六军：指天子军队。\n宛转：形容美人临死前哀怨缠绵的样子。蛾眉：古代美女的代称，此指杨贵妃。《诗经·卫风·硕人》：螓首蛾眉。\n花钿：用金翠珠宝等制成的花朵形首饰。委地：丢弃在地上。\n翠翘：首饰，形如翡翠鸟尾。金雀：金雀钗，钗形似凤（古称朱雀）。玉搔头：玉簪。《西京杂记》卷二：武帝过李夫人，就取玉簪搔头。自此后宫人搔头皆用玉。\n云栈：高入云霄的栈道。萦纡（yíngyū）：萦回盘绕。剑阁：又称剑门关，在今四川剑阁县北，是由秦入蜀的要\n道。此地群山如剑，峭壁中断处，两山对峙如门。诸葛亮相蜀时，凿石驾凌空栈道以通行。\n峨嵋山：在今四川峨眉山市。玄宗奔蜀途中，并未经过峨嵋山，这里泛指蜀中高山。\n行宫：皇帝离京出行在外的临时住所。\n天旋地转：指时局好转。肃宗至德二年（757），郭子仪军收复长安。回龙驭：皇帝的车驾归来。\n信马：意思是无心鞭马，任马前进。\n太液：汉宫中有太液池。未央：汉有未央宫。此皆借指唐长安皇宫。\n西宫南苑：皇宫之内称为大内。西宫即西内太极宫，南内为兴庆宫。玄宗返京后，初居南内。上元元年（760），权宦李辅国假借肃宗名义，胁迫玄宗迁往西内，并流贬玄宗亲信高力士、陈玄礼等人。\n梨园弟子：指玄宗当年训练的乐工舞女。梨园：据《新唐书·礼乐志》：唐玄宗时宫中教习音乐的机构，曾选“坐部伎“三百人教练歌舞，随时应诏表演，号称“皇帝梨园弟子”。\n椒房：后妃居住之所，因以花椒和泥抹墙，故称。阿监：宫中的侍从女官。青娥：年轻的宫女。据《新唐书·百官志》，内官宫正有阿监、副监，视七品。\n孤灯挑尽：古时用油灯照明，为使灯火明亮，过了一会儿就要把浸在油中的灯草往前挑一点。挑尽，说明夜已深。按，唐时宫延夜间燃烛而不点油灯，此处旨在形容玄宗晚年生活环境的凄苦。\n迟迟：迟缓。报更钟鼓声起止原有定时，这里用以形容玄宗长夜难眠时的心情。\n耿耿：微明的样子。欲曙天：长夜将晓之时。\n鸳鸯瓦：屋顶上俯仰相对合在一起的瓦。房瓦一俯一仰相合，称阴阳瓦，亦称鸳鸯瓦。霜华：霜花。\n翡翠衾：布面绣有翡翠鸟的被子谁与共：与谁共。\n临邛：今四川邛崃县。鸿都：东汉都城洛阳的宫门\n名，这里借指长安。《后汉书·灵帝纪》：光和元年二月，始置鸿都门学士。\n致魂魄：招来杨贵妃的亡魂。\n方士：有法术的人。这里指道士。殷勤：尽力。\n排空驭气：即腾云驾雾。\n穷：穷尽，找遍。碧落：即天空。黄泉：指地下。\n海上仙山：《史记·封禅书》：自威、宣、燕昭使人人海求蓬莱、方丈、瀛洲，此三神山者，其传在渤海中。\n玲珑：华美精巧。五云：五彩云霞。\n绰约：体态轻盈柔美。《庄子·逍遥游》：藐姑射之山，有神人居焉，肌肤若冰雪，绰约如处子。\n参差：仿佛，差不多。\n金阙：《太平御览》卷六六。引《大洞玉经》：上清宫门中有两阙，左金阙，右玉阙。西厢：《尔雅·释宫》：室有东西厢日庙。西厢在右。玉扃（jiong）：玉门。即玉阙之变文。\n小玉：吴王夫差女。双成：传说中西王母的侍女。这里皆借指杨贵妃在仙山的侍女。\n九华帐：绣饰华美的帐子。九华：重重花饰的图案。言帐之精美。《宋书·后妃传》：自汉氏昭阳之轮奂，魏室九华之照耀。\n珠箔：珠帘。银屏：饰银的屏风。逦迤：接连不断地。\n新睡觉：刚睡醒。觉，醒。\n袂（mèi）：衣袖。\n玉容寂寞：此指神色黯淡凄楚。阑干：纵横交错的样子。这里形容泪痕满面。\n凝睇（dì）：凝视。\n昭阳殿：汉成帝宠妃赵飞燕的寝宫。此借指杨贵妃住过的宫殿。\n蓬莱宫：传说中的海上仙山。这里指贵妃在仙山的居所。\n人寰（huán）：人间。\n旧物：指生前与玄宗定情的信物。\n寄将去：托道士带回。\n钗留二句：把金钗、钿盒分成两半，自留一半。擘：分开。合分钿：将钿盒上的图案分成两部分。\n重寄词：贵妃在告别是重又托他捎话。\n两心知：只有玄宗、贵妃二人心里明白。\n长生殿：在骊山华清宫内，天宝元年（742）造。按“七月”以下六句为作者虚拟之词。而所谓长生殿者，亦非华清宫之长生殿，而是长安皇宫寝殿之习称。\n比翼鸟：传说中的鸟名，据说只有一目一翼，雌雄并在一起才能飞。\n连理枝：两株树木树干相抱。古人常用此二物比喻情侣相爱、永不分离。\n恨：遗憾。绵绵：连绵不断。', poem_appreciation = '《长恨歌》是白居易诗作中脍炙人口的名篇，作于元和元年（806），当时诗人正在盩厔县（今陕西周至）任县尉。这首诗是他和友人陈鸿、王质夫同游仙游寺，有感于唐玄宗、杨贵妃的故事而创作的。在这首长篇叙事诗里，作者以精炼的语言，优美的形象，叙事和抒情结合的手法，叙述了唐玄　宗、杨贵妃在安史之乱中的爱情悲剧：他们的爱情被自己酿成的叛乱断送了，正在没完没了地吃着这一精神的苦果。唐玄宗、杨贵妃都是历史上的人物，诗人并不拘泥于历史，而是借着历史的一点影子，根据当时人们的传说，街坊的歌唱，从中蜕化出一个回旋曲折、宛转动人的故事，用回环往复、缠绵悱恻的艺术形式，描摹、歌咏出来。由于诗中的故事、人物都是艺术化的，是现实中人的复杂真实的再现，所以能够在历代读者的心中漾起阵阵涟漪。　\n\n　　《长恨歌》就是歌“长恨”，“长恨”是诗歌的主题，故事的焦点，也是埋在诗里的一颗牵动人心的种子。而“恨”什么，为什么要“长恨”，诗人不是直接铺叙、抒写出来，而是通过他笔下诗化的故事，一层一层地展示给读者，让人们自己去揣摸，去回味，去感受。　诗歌开卷第一句：“汉皇重色思倾国”，看来很寻常，好像故事原就应该从这里写起，不需要作者花什么心思似的，事实上这七个字含量极大，是全篇纲领，它既揭示了故事的悲剧因素，又唤起和统领着全诗。紧接着，诗人用极其省俭的语言，叙述了安史之乱前，唐玄宗如何重色、求色，终于得到了“回眸一笑百媚生，六宫粉黛无颜色”的杨贵妃。描写了杨贵妃的美貌、娇媚，进宫后因有色而得宠，不但自己“新承恩泽”，而且“姊妹弟兄皆列土”。反复渲染唐玄宗得贵妃以后在宫中如何纵欲，如何行乐，如何终日沉湎于歌舞酒色之中。所有这些，就酿成了安史之乱：“渔阳鼙鼓动地来，惊破霓裳羽衣曲”。这一部分写出了“长恨”的内因，是悲剧故事的基础。诗人通过这一段宫中生活的写实，不无讽刺地向我们介绍了故事的男女主人公：一个重色轻国的帝王，一个娇媚恃宠的妃子。还形象地暗示我们，唐玄宗的迷色误国，就是这一悲剧的根源。　\n\n　　下面，诗人具体的描述了安史之乱发生后，皇帝兵马仓皇逃入西南的情景，特别是在这一动乱中唐玄宗和杨贵妃爱情的毁灭。“六军不发无奈何，宛转蛾眉马前死。花钿委地无人收，翠翘金雀玉搔头。君王掩面救不得，回看血泪相和流”，写的就是他们在马嵬坡生离死别的一幕。“六军不发”，要求处死杨贵妃，是愤于唐玄宗迷恋女色，祸国殃民。杨贵妃的死，在整个故事中，是一个关键性的情节，在这之后，他们的爱情才成为一场悲剧，接着，从“黄埃散漫风萧索”起至“魂魄不曾来入梦”，诗人抓住了人物精神世界里揪心的“恨”，用酸恻动人的语调，宛转形容和描述了杨贵妃死后唐玄宗在蜀中的寂寞悲伤，还都路上的追怀忆旧，回宫以后睹物思人，触景生情，一年四季物是人非事事休的种种感触。缠绵悱恻的相思之情，使人觉得回肠荡气。正由于诗人把人物的感情渲染到这样的程度，后面道士的到来，仙境的出现，便给人一种真实感，不以为纯粹是一种空中楼阁了。　\n\n　　从“临邛道士鸿都客”至诗的末尾，写道士帮助唐玄宗寻找杨贵妃。诗人采用的是浪漫主义的手法，忽而上天，忽而入地，“上穷碧落下黄泉，两处茫茫皆不见”。后来，在海上虚无缥缈的仙山上找到了杨贵妃，让她以“玉容寂寞泪阑干，梨花一枝春带雨”的形象在仙境中再现，殷勤迎接汉家的使者，含情脉脉，托物寄词，重申前誓，照应唐玄宗对她的思念，进一步深化、渲染“长恨”的主题。诗歌的末尾，用“天长地久有时尽，此恨绵绵无绝期”结笔，点明题旨，回应开头，而且做到“清音有余”，给读者以联想、回味的余地。　\n\n　　《长恨歌》首先给我们艺术美的享受的是诗中那个宛转动人的故事，是诗歌精巧独特的艺术构思。全篇中心是歌“长恨”，但诗人却从“重色”说起，并且予以极力铺写和渲染。“日高起”、“不早朝”、“夜专夜”、“看不足”等等，看来是乐到了极点，象是一幕喜剧，然而，极度的乐，正反衬出后面无穷无尽的恨。唐玄宗的荒淫误国，引出了政治上的悲剧，反过来又导致了他和杨贵妃的爱情悲剧。悲剧的制造者最后成为悲剧的主人公，这是故事的特殊、曲折处，也是诗中男女主人公之所以要“长恨”的原因。过去许多人说《长恨歌》有讽喻意味，这首诗的讽喻意味就在这里。那么，诗人又是如何表现“长恨”的呢？马嵬坡杨贵妃之死一场，诗人刻画极其细腻，把唐玄宗那种不忍割爱但又欲救不得的内心矛盾和痛苦感情，都具体形象地表现出来了。由于这“血泪相和流”的死别，才会有那没完没了的恨。随后，诗人用许多笔墨从各个方面反复渲染唐玄宗对杨贵妃的思念，但诗歌的故事情节并没有停止在一个感情点上，而是随着人物内心世界的层层展示，感应他的景物的不断变化，把时间和故事向前推移，用人物的思想感情来开拓和推动情节的发展。唐玄宗奔蜀，是在死别之后，内心十分酸楚愁惨；还都路上，旧地重经，又勾起了伤心的回忆；回宫后，白天睹物伤情，夜晚辗转难眠。日思夜想而不得，所以寄希望于梦境，却又是“悠悠生死别经年，魂魄不曾来入梦”。诗至此，已经把“长恨”之“恨”写得十分动人心魄，故事到此结束似乎也可以。然而诗人笔锋一折，别开境界，借助想象的彩翼，构思了一个妩媚动人的仙境，把悲剧故事的情节推向高潮，使故事更加回环曲折，有起伏，有波澜。这一转折，既出人意料，又尽在情理之中。由于主观愿望和客观现实不断发生矛盾、碰撞，诗歌把人物千回百转的心理表现得淋漓尽致，故事也因此而显得更为宛转动人。　\n\n　　《长恨歌》是一首抒情成份很浓的叙事诗，诗人在叙述故事和人物塑造上，采用了中国传统诗歌擅长的抒写手法，将叙事、写景和抒情和谐地结合在一起，形成诗歌抒情上回环往复的特点。诗人时而把人物的思想感情注入景物，用景物的折光来烘托人物的心境；时而抓住人物周围富有特征性的景物、事物，通过人物对它们的感受来表现内心的感情，层层渲染，恰如其分地表达人物蕴蓄在内心深处的难达之情。唐玄宗逃往西南的路上，四处是黄尘、栈道、高山，日色暗淡，旌旗无光，秋景凄凉，这是以悲凉的秋景来烘托人物的悲思。在蜀地，面对着青山绿水，还是朝夕不能忘情，蜀中的山山水水原是很美的，但是在寂寞悲哀的唐玄宗眼中，那山的“青”，水的“碧”，也都惹人伤心，大自然的美应该有恬静的心境才能享受，他却没有，所以就更增加了内心的痛苦。这是透过美景来写哀情，使感情又深入一层。行宫中的月色，雨夜里的铃声，本来就很撩人意绪，诗人抓住这些寻常但是富有特征性的事物，把人带进伤心、断肠的境界，再加上那一见一闻，一色一声，互相交错，在语言上、声调上也表现出人物内心的愁苦凄清，这又是一层。还都路上，“天旋地转”，本来是高兴的事，但旧地重过，玉颜不见，不由伤心泪下。叙事中，又增加了一层痛苦的回忆。回长安后，“归来池苑皆依旧，太液芙蓉未央柳。芙蓉如面柳如眉，对此如何不泪垂”。白日里，由于环境和景物的触发，从景物联想到人，景物依旧，人却不在了，禁不住就潸然泪下，从太液池的芙蓉花和未央宫的垂柳仿佛看到了杨贵妃的容貌，展示了人物极其复杂微妙的内心活动。“夕殿萤飞思悄然，孤灯挑尽未成眠。迟迟钟鼓初长夜，耿耿星河欲曙天”。从黄昏写到黎明，集中地表现了夜间被情思萦绕久久不能入睡的情景。这种苦苦的思恋，“春风桃李花开日”是这样，“秋雨梧桐叶落时”也是这样。及至看到当年的“梨园弟子”、“阿监青娥”都已白发衰颜，更勾引起对往日欢娱的思念，自是黯然神伤。从黄埃散漫到蜀山青青，从行宫夜雨到凯旋回归，从白日到黑夜，从春天到秋天，处处触物伤情，时时睹物思人，从各个方面反复渲染诗中主人公的苦苦追求和寻觅。现实生活中找不到，到梦中去找，梦中找不到，又到仙境中去找。如此跌宕回环，层层渲染，使人物感情回旋上升，达到了高潮。诗人正是通过这样的层层渲染，反复抒情，回环往复，让人物的思想感情蕴蓄得更深邃丰富，使诗歌“肌理细腻”，更富有艺术的感染力。　\n\n　　人们对白居易《长恨歌》的主题思想历来争论不休，有所谓爱情说、政治主题说、双重主题说等等。本文作者持爱情说。首先从作品的四个层次来分析，肯定白居易并非像陈鸿写《长恨歌传》那样板着说教的脸孔去描写李杨故事，而是以“情”作为主旋律，让主人公的情去感动读者，使之产生共鸣，取得审美上的极大成功。本文还结合作者生平经历和社会历史分析他在处理历史题材、政治题材和来自民间的人性题材、心理题材的关系问题上的独到之处，进一步说明唐明皇杨贵妃形象的审美意义。　\n\n　　《长恨歌》一出，关于其主题，便成为历来读者争论的焦点。观点也颇具分歧。大抵分三种：其一为爱情主题。是颂扬李杨的爱情诗作。并肯定他们对爱情的真挚与执著；其二为政治主题说。认为诗的重点在于讽喻，在于揭露“汉皇重色思倾国”必然带来的“绵绵长恨”，谴责唐明皇荒淫导致安史之乱以垂诫后世君主；其三为双重主题说。认为它是揭露与歌颂统一，讽谕和同情交织，既洒一掬同情泪，又责失政遗恨。究竟如何，还需从作品本身去分析。\n\n　　可将诗分为四个层次：第一层从“汉皇重色思倾国”至“尽日君王看不足”，叙述了安史之乱前，唐玄宗如何重色、求色，终于得到了“回眸一笑百媚生”的杨贵妃。贵妃进宫后恃宠而骄，不但自己“新承恩泽”，而且“姊妹弟兄皆列土”，反复渲染唐玄宗得贵妃后完全沉湎于歌舞酒色。开卷首句既提示了故事的悲剧因素，又唤起和统领着全诗；　第二层从“渔阳鼙鼓动地来”至“回看血泪相和流”，写安史之乱，玄宗逃难，被迫赐死贵妃，写出了“长恨”的内因，是悲剧故事的基础。诗人有意将因玄宗荒淫误国所造成的安史之乱进行了淡化处理，对二人的生离死别则着意形容，读者受到的是悲剧气氛的感染而不是历史的理性批判。陈鸿《长恨歌传》“惩尤物，窒乱阶”之说是板着面孔做文章，故不能视为此诗的写作动机；第三层从“黄埃散漫风萧索”至“魂魄不曾来人梦”，描述了杨贵妃死后，唐玄宗在蜀中的寂寞悲伤还都路上的追怀忆旧，行宫见月，夜雨闻铃，是一片“伤心色”和“断肠声”。长安收复以后回朝时，重过马嵬，“不见玉颜空死处”。回宫后，池苑依旧，物是人非，缠绵悱恻的相思之情，使人觉得荡气回肠；第四层从“临邛道士鸿都客”至“此恨绵绵无绝期”，写玄宗派方士觅杨贵妃之魂魄，重在表现唐玄宗的孤寂和对往日爱情生活的忧伤追忆。诗人运用浪漫主义手法，上天入地，后终在虚无缥缈的仙山上让贵妃以“玉容寂寞泪阑干，梨花一枝春带雨”的形象再现于仙境。“情”的宣泄已超脱于帝王妃子间的感情纠葛，而更多地带有诗人的主观的理想成分，并早已超出了历史事实的范围，将主观愿望与客观现实的矛盾冲突表现无余。结尾“天长地久有时尽，此恨绵绵无绝期”二句，是爱情的叹息与呼声，是对于爱情受命运播弄，和爱情被政治伦理摧残的痛惜，此恨之深，已超越时空而进入无极之境。这样，诗人便以“长恨”表现了爱情的长存，亦即点明全诗的主题。　\n\n　　应该说，写作之初，白居易至少在主观上是同意陈鸿的“惩尤物、窒乱阶”之说的，后来在《新乐府》的《李夫人》、《古家狐》中还重复强调了“尤物惑人”、“狐媚害人”的主题，明确宣扬性爱之为害，但是又承认“人非木石皆有情”，性爱是消灭不了的，所以解决问题的途径只好是“不如不遇倾城色”。但在《长恨歌》的实际写作当中，他又服从了民间爱情故事所表达的人类的向美本能和情感欲望。这样，整个故事便具有了更为深刻复杂的涵义：既写了真美，又写了真恶，并将两者直接联系在一起；《丽情集》本《长恨歌传》有一段话：叔向母曰：“甚美必甚恶。”李延年歌曰：“倾国复倾城。”此之谓也。　这段话大概可以代表中唐士人对这一　问题的最后思考。白居易写作《长恨歌》时遵循的一条基本原则是：不因为“甚恶”而抹煞“甚美”。尽管其主题最后似偏离了对“甚恶”的谴责，但“甚恶”内容本身毕竟没有被抹煞，反过来又丰富了“甚美”的涵义。　\n\n　　《长恨歌》一方面是一个重大的历史题材和政治题材，另一方面又是一个来自民间的具有悠久传统的人性题材、心理题材。白居易在创作中服从于民族的文化心理和诗人的个性思想，即传统模式与作者主观能动作用同时并存，这固然是与诗人的生活经历和人生观是分不开的。白居易一生跨中晚唐，他的思想以贬官江州司马为界，经历了由积极入世到消极出世两个阶段，实践了他所信奉的“达则兼济天下，穷则独善其身”的儒家人生模式。白居易所谓“独善”的基本内涵是乐天知命、知足保和，并由此而与释、老相通，以随缘任运、委顺自然为应世态度。在他的整个思想体系中，“独善”与“兼济”并行不悖，“施之乃伊吕事业，蓄之则庄老道德”(《君子不器赋》)，它们是一个完整人生观的两个侧面。还在遭贬以前，他努力为云龙、为风鹏，并与元稹大力倡导新乐府运动。也正是因为他年轻时候的胸怀大志，颇有挽唐室于既衰，拯生民于水火的政治气概，才使得他有足够的气魄处理这样一个重大的历史题材，并以“不惑”来总结唐明皇后半生的政治得失，写就了《长恨歌》。这样，在他心目中对唐明皇的一分为二，必然要在塑造形象中反映出来。正是因为一往情深的唐明皇同重色轻国的唐明皇是对立统一体，所以，白居易把这个故事写成一个好皇帝的悲剧。好皇帝有所惑，终于造成了自己和百姓的悲哀。我们从作品中看到的唐明皇性格的塑造已排斥了理想化，乃是另一种理想化的结果。排斥的是封建统治阶级为皇帝们头上加足光圈使其上升为半神的理想化。而这排斥本身，就包含了城市居民的另一种理想在内，他们从现实生活中皇帝权威下降的土壤出发，把封建统治阶级的头子想象为和他们自己一样的普通人，一个有爱欲、有苦恼、有错误、有缺点的人情味十足的痴情皇帝，简直同一般爱情故事中的主人公并无差别！他们从另一角度把皇帝理想化了，理想化的皇帝应该和百姓一样是有血有肉的人，不是神！而白居易从民本思想出发，有条件、并有所扬弃地接受了城市居民的这种对唐明皇的理想化，这样完成了对唐明皇形象的塑造。诗人被贬江州以后，“独善”与“兼济”的地位才发生了转化，他的精神生活与仕宦生涯逐渐转轨，终于以“独善”消释了“兼济”，在精神自救的过程中，白居易逐渐从关注社会政治转向关注个体生命，对于自由人格的钟爱逐渐超越了对道德人格的执著。 　　 　　作为一首千古绝唱的叙事诗，《长恨歌》在艺术上的成就是很高的。古往今来，许多人都肯定这首诗的特殊的艺术魅力。《长恨歌》在艺术上以什么感染和诱惑着读者呢？宛转动人，缠绵悱恻，恐怕是它最大的艺术个性，也是它能吸住千百年来的读者，使他们受感染、被诱惑的力量。', poem_tags = '唐诗三百首,写人,爱情,讽喻,叙事,长诗' WHERE poem_title = '长恨歌' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '环绕滁州的都是山。那西南的几座山峰，树林和山谷尤其优美。一眼望去树木茂盛，又幽深又秀丽的，那是琅琊山。沿着山路走六七里，渐渐听到潺潺的水声，看到流水从两座山峰之间倾泻而出的，那是酿泉。泉水沿着山峰折绕，沿着山路拐弯，有一座亭子像飞鸟展翅似地，飞架在泉上，那就是醉翁亭。建造这亭子的是谁呢？是山上的和尚智仙。给它取名的又是谁呢？太守用自己的别号（醉翁）来命名。太守和他的宾客们来这儿饮酒，只喝一点儿就醉了；而且年纪又最大，所以自号“醉翁”。醉翁的情趣不在于喝酒，而在欣赏山水的美景。欣赏山水美景的乐趣，领会在心里，寄托在酒上。\n\n　　至于太阳的升起，山林里的雾气散了；烟云聚拢来，山谷就显得昏暗了；朝则自暗而明，暮则自明而暗，或暗或明，变化不一，这就是山中的朝暮。野花开了，有一股清幽的香味；好的树木枝繁叶茂，形成一片浓密的绿荫；风高霜洁，天高气爽，水落石出，这就是山中的四季。清晨前往，黄昏归来，四季的风光不同，乐趣也是无穷无尽的。\n\n　　至于背着东西的人在路上欢唱，来去行路的人在树下休息，前面的招呼，后面的答应；老人弯着腰走，小孩子由大人领着走。来来往往不断的行人，是滁州的游客。到溪边钓鱼，溪水深并且鱼肉肥美；用酿泉造酒，泉水清并且酒也清；野味野菜，横七竖八地摆在面前的，那是太守主办的宴席。宴会喝酒的乐趣，不在于音乐；投射的中了，下棋的赢了，酒杯和酒筹交互错杂；时起时坐大声喧闹的人，是欢乐的宾客们。一个脸色苍老的老人，醉醺醺地坐在众人中间，是太守喝醉了。\n\n　　不久，太阳下山了，人影散乱，宾客们跟随太守回去了。树林里的枝叶茂密成林，鸟儿到处叫，是游人离开后鸟儿在欢乐地跳跃。但是鸟儿只知道山林中的快乐，却不知道人们的快乐。而人们只知道跟随太守游玩的快乐，却不知道太守以游人的快乐为快乐啊。醉了能够和大家一起欢乐，醒来能够用文章记述这乐事的人，那就是太守啊。太守是谁呢？是庐陵欧阳修吧。', poem_notes = '环：环绕。\n皆：副词，都。\n环滁：环绕着滁州城。\n滁：滁州，今安徽省滁州市琅琊区。\n其：代词，它，指滁州城。\n壑：山谷。\n尤：格外，特别。\n蔚然而深秀者，琅琊也：树木茂盛，又幽深又秀丽的，是琅琊山。蔚然：草木茂盛的样子。而：表并列。\n峰回路转：山势回环，路也跟着拐弯。比喻事情经历挫折失败后，出现新的转机。\n山：名词作状语，沿着山路。\n潺潺：流水声。\n而：表承接。\n酿泉：泉的名字。因水清可以酿酒，故名。\n回：回环，曲折环绕。\n翼然：像鸟张开翅膀一样。\n然：......的样子。\n临：居高面下，由上看下。。\n于：在。\n作：建造。\n名：名词作动词，命名。\n自谓：自称，用自己的别号来命名。\n号：名词作动词，取别号。\n曰：叫做。\n辄：就。\n年又最高：年纪又是最大的。\n意：这里指情趣。“醉翁之意不在酒”，后来用以比喻本意不在此而另有目的。\n乎：相当于“于”。\n得：领会。\n寓：寄托。\n林霏：树林中的雾气。霏，原指雨、雾纷飞，此处指雾气。\n开：消散，散开。\n归：聚拢。\n暝：昏暗。\n晦：阴暗。\n 晦明：指天气阴晴明暗。\n芳：香花。\n 发：开放。\n佳木秀而繁阴，好的树木枝繁叶茂，形成一片浓密的绿荫。\n秀：茂盛，繁茂。\n繁阴：一片浓密的树荫。\n风霜高洁：就是风高霜洁。天高气爽，霜色洁白。\n至于：连词，于句首，表示两段的过渡，提起另事。\n负者：背着东西的人。\n休于树：在树下休息。\n伛偻：腰弯背曲的样子，这里指老年人\n提携：指搀扶着走的小孩子。\n临：靠近，这里是“……旁”的意思。\n渔：捕鱼。\n酿泉：一座泉水的名字，原名玻璃泉，在琅邪山醉翁亭下。\n洌：水（酒）清。\n山肴：野味。\n野蔌：野菜。蔌，菜蔬。\n杂然：众多而杂乱的样子。\n陈：摆放，摆设。\n酣：尽情地喝酒。\n丝：琴、瑟之类的弦乐器。\n竹：箫、笛之类的管乐器。非丝非竹：不在于琴弦管箫。\n射：这里指投壶，宴饮时的一种游戏，把箭向壶里投，投中多的为胜，负者照规定的杯数喝酒。\n弈：下棋。这里用做动词，下围棋。\n觥筹交错：酒杯和酒筹相错杂。形容喝酒尽欢的样子。\n觥：酒杯。\n筹：酒筹，用来计算饮酒数量的筹子。\n苍颜：脸色苍老。\n颓然乎其间：醉醺醺地坐在众人中间。颓然，原意是精神不振的样子，这里形容醉态。\n归：回家。\n已而：不久。\n阴翳：形容枝叶茂密成阴。\n翳：遮蔽。\n鸣声上下：意思是鸟到处叫。上下，指高处和低处的树林。\n乐①其乐②：以游人的快乐为快乐 乐①：意动用法，以…为乐。乐②：快乐。\n醉能同其乐，醒能述以文者：醉了能够同大家一起欢乐，醒了能够用文章记述这乐事的人。\n谓：为，是。\n庐陵：庐陵郡，就是吉洲。今江西省吉安市，欧阳修先世为庐陵大族。', poem_appreciation = '《醉翁亭记》作于宋仁宗庆历六年（1046），当时欧阳修正任滁州太守。欧阳修是从庆历五年被贬官到滁州来的。被贬前曾任太常丞知谏院、右正言知制诰、河北都转运按察使等职。被贬官的原因是由于他一向支持韩琦、范仲淹、富弼等人推行新政，而反对保守之流。韩范诸人早在庆历五年一月之前就已经被先后被贬，到这年的八月，欧阳修又被加了一个亲戚中有人犯罪，事情与之有牵连的罪名，落去朝职，贬放滁州。\n\n　　欧阳修在滁州实行宽简政治，发展生产、使当地人过上了一种和平安定的生活，年丰物阜，而且又有一片令人陶醉的山水，这是使欧阳修感到无比快慰的。但是当时整个的北宋王朝却是政治昏暗，奸邪当道，一些有志改革图强的人纷纷受到打击，眼睁睁地看着国家的积弊不能消除，衰亡的景象日益增长，这又不能不使他感到沉重的忧虑和痛苦。这是他写作《醉翁亭记》时的心情，这两方面是融和一起、表现在他的作品里的。\n\n　　《醉翁亭记》写得格调清丽，富有诗情画意。这篇散文写了两部分内容：第一部分，重点是写亭；第二部分，重点是写游。而贯穿全篇的却是一个“乐”字。为了领悟这醉翁之意，就让我们来共同观赏一下醉翁亭的山水之美吧。\n\n　　文章一开头是“环滁皆山也”这浓荫蔽日；秋天，风霜高洁；冬天，水落石出。四季变幻，奇景叠山。欣赏醉翁亭的山景，乐趣是无穷无尽的。\n\n　　观赏醉翁亭变幻的山景，固然其乐无穷，但在醉翁亭观看人们行游，并在那里宴饮，更是别有一番乐趣。背着东西的，边走边唱；走累了的，在树下休息，怡然自得。人们前呼后应，老人小孩，往来不绝。这里有静有动，有声有态，描绘了一幅生动的滁人游乐图。接着又写到肥鱼泉酒、山肴野蔌的太守宴，以及夹杂在众人一片欢乐之中的“苍颜白发，颓然乎其间”的太守醉态。在极写欢乐中，把太守复杂的心境，也微妙地表达出来了。\n\n　　最后作者从禽鸟之乐，宾客之乐及太守之乐的不同内容和感情的对比中，推论出“禽鸟知山林之乐，而不知人之乐；人知从太守游而乐，而不知太守之乐其乐也。”醉了，能与民同乐；醒了，能写《醉翁亭记》一文的，就是太守欧阳修。笔墨简练含蓄，寓意深远。\n\n　　《 醉翁亭记》确是一篇风格清新、摇曳生姿、优美动人的抒情散文。作者对滁州优美山水风景的讴歌，对建设和平安定、与民同乐的理想社会的努力和向往，尤其是作者委婉而含蓄地所吐露的苦闷，这对宋仁宗时代的昏暗政治，无疑在客观上是一种揭露，这些自然都闪烁着思想光芒。尤其是这篇文章的语言，准确、鲜明、生动、优美，句式整齐而有变化，全文重复运用“……者……也”的句式，并且连用二十一个“也”字，增强文章特有的韵律。这些方面，都是可资借鉴的\n\n　　《醉翁亭记》中“而”字的妙用\n\n　　《醉翁亭记》是散文中别出一格特具风采的名篇，也是体现欧阳修散文风格的代表作，历来为人们称赞。文中多用陈述句，并以二十一个“也”作结。但“而”字的位置不同，句子结构节奏也随之产生变化，不显得呆板。文中第三、四小节是描写山间朝暮、四时不同的景色和人们游山之乐的，共分六层（“朝而往，……而乐亦无穷也”，作为过渡句，不列入层次内。）除第一层和第六层用“……者，……也”句式作结束句外，中间四层都用“……而……者，……也”句式作结束句。每一层最后一句的句式基本一致，但句子长短参差不一，结束句中都用了“而”字，显得整齐中有错落，节奏略有变化。\n\n　　第四小节中有一处似乎可能用“而”却用了“为”。原句为“临溪而渔，溪深而鱼肥；酿泉为酒，泉香而酒洌。”加黑的“为”若作动词解，则“酿泉为酒”与“临溪而渔”就对不起来了。其实这个“为”该作“而”字解。《古书虚词集释》：“‘为’犹‘而’也”。这两句中的“为”“而”为互文。这样，就与“临溪而渔”对得很工整了。此处“为”作“而”解，则全文实际用了二十六个“而”字。\n\n　　《醉翁亭记》读来朗朗上口，娓娓动听，这与25个“而”字的运用也是分不开的。“而”字恰到好处的运用，使文章舒缓从容，把作者欣赏“山水之乐得之心”的闲情雅致充分表现出来了。如“朝而往，暮而归”，若去掉“而”，成“朝往，暮归”，就显得紧迫短促，有早上匆匆而去傍晚急急而归之感，插入两个“而”字，就把游玩者欣赏山水之乐的从容之态、欢乐之情、悠雅之兴全表现出来了。文中不少句子由于用了“而”字，语气轻重分明，诵读时极富抑扬顿挫之致。如“临溪而渔”句，重音在谓语“渔”上，读重些，长些，作为状语的“临溪”则读轻些，短些。若不用“而”，成“临溪渔”，不仅别扭滞涩，而且语气轻重不分明。“临溪而渔，溪深而鱼肥；酿泉为酒，泉香而酒洌。”读来真使人感到有内在的类似诗歌的那种韵律美。', poem_tags = '辞赋精选,初中文言文,古文观止,宴饮,山水,抒情' WHERE poem_title = '醉翁亭记' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '关关和鸣的雎鸠，相伴在河中的小洲。那美丽贤淑的女子，是君子的好配偶。\n参差不齐的荇菜，从左到右去捞它。那美丽贤淑的女子，醒来睡去都想追求她。\n追求却没法得到，白天黑夜便总思念她。长长的思念哟，叫人翻来覆去难睡下。\n参差不齐的荇菜，从左到右去采它。那美丽贤淑的女子，奏起琴瑟来亲近她。\n参差不齐的荇菜，从左到右去拔它。那美丽贤淑的女子，敲起钟鼓来取悦她。', poem_notes = '关关：象声词，雌雄二鸟相互应和的叫声。雎鸠（jū jiū）：一种水鸟名，即王鴡。\n洲：水中的陆地。\n窈窕（yǎo tiǎo）淑女：贤良美好的女子。窈窕，身材体态美好的样子。窈，深邃，喻女子心灵美；窕，幽美，喻女子仪表美。淑，好，善良。\n好逑（hǎo qiú）：好的配偶。逑，“仇”的假借字，匹配。\n参差：长短不齐的样子。荇（xìng）菜：水草类植物。圆叶细茎，根生水底，叶浮在水面，可供食用。\n左右流之：时而向左、时而向右地择取荇菜。这里是以勉力求取荇菜，隐喻“君子”努力追求“淑女”。流，义同“求”，这里指摘取。之：指荇菜。\n寤寐（wù mèi）：醒和睡。指日夜。寤，醒觉。寐，入睡。又，马瑞辰《毛诗传笺注通释》说：“寤寐，犹梦寐。”也可通。\n思服：思念。服，想。 《毛传》：“服，思之也。”\n悠哉（yōu zāi）悠哉：意为“悠悠”，就是长。这句是说思念绵绵不断。悠，感思。见《尔雅·释诂》郭璞注。哉，语气助词。悠哉悠哉，犹言“想念呀，想念呀”。\n辗转反侧：翻覆不能入眠。辗，古字作展。展转，即反侧。反侧，犹翻覆。\n琴瑟友之：弹琴鼓瑟来亲近她。琴、瑟，皆弦乐器。琴五或七弦，瑟二十五或五十弦。友：用作动词，此处有亲近之意。这句说，用琴瑟来亲近“淑女”。\n芼（mào）：择取，挑选。\n钟鼓乐之：用钟奏乐来使她快乐。乐，使动用法，使……快乐。', poem_appreciation = '《关雎》是一首意思很单纯的诗。大概它第一好在音乐，此有孔子的评论为证，《论语·泰伯》：“师挚之始，《关雎》之乱，洋洋乎盈耳哉。”乱，便是音乐结束时候的合奏。它第二好在意思。《关雎》不是实写，而是虚拟。戴君恩说：“此诗只‘窈窕淑女，君子好逑’便尽了，却翻出未得时一段，写个牢骚忧受的光景；又翻出已得时一段，写个欢欣鼓舞的光景，无非描写‘君子好逑’一句耳。若认做实境，便是梦中说梦。”牛运震说：“辗转反侧，琴瑟钟鼓，都是空中设想，空处传情，解诗者以为实事，失之矣。”都是有得之见。《诗》写男女之情，多用虚拟，即所谓“思之境”，如《汉广》，如《月出》，如《泽陂》，等等，而《关雎》一篇最是恬静温和，而且有首有尾，尤其有一个完满的结局，作为乐歌，它被派作“乱”之用，正是很合适的。 然而不论作为乐还是作为歌，它都不平衍，不单调。贺贻孙曰：“‘求之不得，寤寐思服。悠哉悠哉，辗转反侧’，此四句乃诗中波澜，无此四句，则不独全诗平叠直叙无复曲折，抑且音节短促急弦紧调，何以被诸管弦乎。忽于‘窈窕淑女’前后四叠之间插此四句，遂觉满篇悠衍生动矣。”邓翔曰：“得此一折，文势便不平衍，下文‘友之’‘乐之’乃更沉至有味。‘悠哉悠哉’，叠二字句以为句，‘辗转反侧’，合四字句以为句，亦着意结构。文气到此一住，乐调亦到此一歇拍，下章乃再接前腔。”虽然“歇拍”、“前腔”云云，是以后人意揣度古人，但这样的推测并非没有道理。依此说，则《关雎》自然不属即口吟唱之作，而是经由一番思索安排的功夫“作”出来。其实也可以说，“诗三百”，莫不如是。 “关关雎鸠，在河之洲”，毛传：“兴也。”但如何是兴呢，却是一个太大的问题。若把古往今来关于“兴”的论述统统编辑起来，恐怕是篇幅甚巨的一部大书，则何敢轻易来谈。然而既读《诗》，兴的问题就没办法绕开，那么只好敷衍几句最平常的话。所谓“兴”，可以说是引起话题吧，或者说是由景引起情。这景与情的碰合多半是诗人当下的感悟，它可以是即目，也不妨是浮想；前者是实景，后者则是心象。但它仅仅是引起话题，一旦进入话题，便可以放过一边，因此“兴”中并不含直接的比喻，若然，则即为“比”。至于景与情或曰物与心的关联，即景物所以为感为悟者，当日于诗人虽是直接，但如旁人看则已是微妙，其实即在诗人自己，也未尝不是转瞬即逝难以捕捉；时过境迁，后人就更难找到确定的答案。何况《诗》的创作有前有后，创作在前者，有不少先已成了警句，其中自然包括带着兴义的句子，后作者现成拿过来，又融合了自己的一时之感，则同样的兴，依然可以有不同的含义。但也不妨以我们所能感知者来看。罗大经说：“杜少陵绝句云：‘迟日江山丽，春风花草香。泥融飞燕子，沙暖睡鸳鸯。’或谓此与儿童之属对何以异，余曰不然。上二句见两间莫非生意，下二句见万物莫不适性。于此而涵泳之，体认之，岂不足以感发吾心之真乐乎。”我们何妨以此心来看《诗》之兴。两间莫非生意，万物莫不适性，这是自然予人的最朴素也是最直接的感悟，因此它很可以成为看待人间事物的一个标准：或万物如此，人事亦然，于是喜悦，如“桃之夭夭，灼灼其华”(《周南·桃夭》)，如“呦呦鹿鸣，食野之苹”(《小雅·鹿鸣》)，如此诗之“关关雎鸠，在河之洲”；或万物如此，人事不然，于是悲怨，如“雄雉于飞，泄泄其羽”(《邶风·雄雉》)，如“习习谷风，以阴以雨”(《邶风·谷风》)，如“毖彼泉水，亦流于淇”(《邶风·泉水》)。《诗》中以纯粹的自然风物起倡的兴，大抵不出此意。总之，兴之特殊，即在于它于诗人是如此直接，而于他人则往往其意微渺，但我们若解得诗人原是把天地四时的瞬息变化，自然万物的死生消长，都看作生命的见证，人生的比照，那么兴的意义便很明白。它虽然质朴，但其中又何尝不有体认生命的深刻。 “钟鼓乐之”，是身分语，而最可含英咀华的则是“琴瑟友之”一句。朱熹曰：“‘友’者，亲爱之意也。”辅广申之曰：“以友为亲爱之意者，盖以兄友弟之友言也。”如此，《邶风·谷风》“宴尔新昏，如兄如弟”的形容正是这“友”字一个现成的注解。若将《郑风·女曰鸡鸣》《陈风·东门之池》等篇合看，便知“琴瑟友之”并不是泛泛说来，君子之“好逑”便不但真的是知“音”，且知情知趣，而且更是知心。春秋时代以歌诗为辞令，我们只认得当日外交之风雅，《关雎》写出好婚姻之一般，这日常情感生活中实在的谐美和欣欣之生意，却是那风雅最深厚的根源。那时候，《诗》不是装饰，不是点缀，不是只为修补生活中的残阙，而真正是“人生的日用品”(顾颉刚语)，《关雎》便好像是人生与艺术合一的一个宣示，栩栩然翩翩然出现在文学史的黎明。 关雎，是《诗经》的开篇之作，向来有赞誉。为什么用关雎作为这篇充满爱意的诗的题目呢？在孔子编辑《诗经》时，分为风雅颂三部分，其中雅又分为大雅和小雅。风，为民间传唱的诗，《孟子见梁惠王》中有关于民间的歌曲的记载，风，大体相当于现在的流行歌曲。雅，中的部分来自民间，部分来自贵族的歌颂诗。颂，便是贵族用来祭司时歌颂上天，先祖的诗。所以，大部分的诗是没有名字的，而编辑一部书，为了让人们便于查阅必将为每部分添加题目。当然，孔子比较谦虚采取了取诗每句开头的词作为诗的题目。《关雎》取自关关雎鸠 ，“关关”是指雎鸠的叫声，拟声词。后世多用这种的命名方法，如唐李商隐的《无题》，因为有多首，所以采取了孔子发明的命名方法，如《锦瑟》取自：锦瑟无端五十弦。', poem_tags = '古诗三百首,初中古诗,诗经,爱情' WHERE poem_title = '关雎' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '从小丘向西走一百二十多步，隔着竹林，可以听到水声，就像人身上佩带的佩环相碰击发出的声音，（我）心里感到高兴。砍倒竹子，开辟出一条道路（走过去），沿路走下去看见一个小潭，潭水格外清凉。小潭以整块石头为底，靠近岸边，石底有些部分翻卷过来露出水面。成为了水中高地、小岛、不平的岩石和石岩等各种不同的形状。青翠的树木，翠绿的藤蔓，遮掩缠绕，摇动下垂，参差不齐，随风飘拂。\n　　潭中的鱼大约有一百来条，都好像在空中游动，什么依靠都没有。阳光直照（到水底），(鱼的）影子映在石上，呆呆地（停在那里）一动不动，忽然间(又)向远处游去了，来来往往，轻快敏捷，好像和游玩的人互相取乐。\n　　向小石潭的西南方望去，看到溪水像北斗星那样曲折，水流像蛇那样蜿蜒前行，时而看得见，时而看不见。两岸的地势像狗的牙齿那样相互交错，不能知道溪水的源头。\n　　我坐在潭边，四面环绕合抱着竹林和树林，寂静寥落，空无一人。使人感到心情凄凉，寒气入骨，幽静深远，弥漫着忧伤的气息。 因为这里的环境太凄清，不可长久停留，于是记下了这里的情景就离开了。\n　　一起去游玩的人有吴武陵、龚古、我的弟弟宗玄。跟着同去的有姓崔的两个年轻人。一个叫做恕己，一个叫做奉壹。', poem_notes = '小丘：在小石潭东面。\n篁竹：竹林。\n如鸣佩 环：好像人身上佩带的佩环相碰击发出的声音。鸣：发出的声音。佩、环：都是玉制的装饰品。\n水尤清冽：水格外清凉。尤，格外。清，清澈。冽，凉。\n全石以为底：（潭）以整块石头为底。以为：把...当做...\n近岸，卷石底以出：靠近岸边，石头从水底向上弯曲露出水面。以：连词，相当于“而”，不译。\n为坻，为屿，为嵁，为岩：成为坻、屿、嵁、岩各种不同的形状。坻，水中高地。屿，小岛。嵁，高低不平的岩石。岩，岩石。\n翠蔓：碧绿的茎蔓。\n蒙络摇缀，参差披拂：（树枝藤蔓）遮掩缠绕，摇动下垂，参差不齐，随风飘拂。\n可百许头：大约有一百来条。可，大约。许，用在数词后表示约数，相当于同样用法的“来”。\n皆若空游无所依：（鱼）都好像在空中游动，什么依靠都没有。\n日光下彻，影布石上：阳光照到水底，鱼的影子好像映在水底的石头上。\n佁然不动：（鱼）呆呆地一动不动。佁然，呆呆的样子。\n俶尔远逝：忽然间向远处游去了。俶尔，忽然。\n往来翕忽：来来往往轻快敏捷。翕忽；轻快敏捷的样子。\n斗折蛇行，明灭可见：看到溪水像北斗星那样曲折，像蛇那样蜿蜒前行，时隐时现。斗折，像北斗七星的排列那样曲折。蛇行，像蛇爬行那样蜿蜒。明灭可见，时而看得见，时而看不见。\n犬牙差互：像狗的牙齿那样参差不齐。犬牙：像狗的牙齿一样。差互，交相错杂。\n凄神寒骨，悄怆幽邃：使人感到心情凄凉，寒气透骨，幽静深远，弥漫着忧伤的气息。凄、寒：使动用法，使……感到凄凉 ，使……感到寒冷。悄怆，寂静得使人感到忧伤。邃，深。悄怆，忧伤的样子。\n以其境过清：因为这里环境太冷清了。以，因为。清，凄清。\n吴武陵：作者的朋友，也被贬在永州。\n龚古：作者的朋友。\n宗玄：作者的堂弟。\n隶而从者，崔氏二小生：跟着我一同去的，有姓崔的两个年轻人。隶而从：跟着同去的。隶：随从。而：表并列。崔氏，指柳宗元姐夫崔简。二小生，两个年轻人，指崔简的两个儿子。\n卷石底以出；以，而。', poem_appreciation = '柳宗元的山水游记在中国文学史上具有独特的地位。其中最著名的，是他被贬谪到永州以后写的《始得西山宴游记》 《钴鉧潭记》 《钴鉧潭西小丘记》《至小丘西小石潭记》《袁家渴记》《石渠记》《石涧记》《小石城山记》，这些作品并称为《永州八记》。这些作品，画廊式地展现了湘桂之交一幅幅山水胜景，继承了郦道元《水经注》的传统而有所发展。而柳宗元的山水游记则把自己的身世遭遇、思想感情融合于自然风景的描绘中，投入作者本人的身影，借被遗弃于荒远地区的美好风物，寄寓自己的不幸遭遇，倾注怨愤抑郁的心情。本文是柳宗元《永州八记》中的第四篇，保持了《永州八记》一贯的行文风格，观察入微，描摹细致。肖其貌，传其神。文章先写所见景物，然后以特写镜头描绘游鱼和潭水，再写潭上景物和自己的感受，写出了小石潭及其周围幽深冷寂的景色和气氛。 　此外，作者还在写景中传达出他贬居生活中孤凄悲凉的心境，是一篇情景交融的佳作。乐是忧的另一种表现形式。柳宗元参与改革，失败被贬，心中愤懑难平，所以凄苦是他感情的主调。然而寄山水正是为了摆脱这种抑郁的心情。可是欢乐毕竟是暂时的，一经凄清环境的触发，忧伤悲凉的心情就又会流露出来。抒发了作者在寂寞处境中悲凉凄怆的心绪。语言简练、生动，景物刻画细腻、逼真，巧用比喻寓情于景，。该篇为散文。散文可以叙事，写景和状物。其目的是抒发作者的情怀抱负，阐述作者的某些观点。《小石潭记》则是《永州八记》中的经典名篇，寄情山水之意尤为明显。\n\n　　写作者对小石潭总印象和感受。\n\n　　“坐潭上，四面竹树环合，寂寥无人，凄神寒骨，悄怆幽邃。以其境过清，不可久居，乃记之而去。”\n\n　　坐在小石潭上，四周环抱着密密的竹子和树木，非常寂静，见不到人，令人神色凄凉，骨彻心寒，精神上也不免悲怆幽凉。因为它的境况太幽清了，不适宜让人长久地呆下去，便题了字后离去。在这一段中，作者突出地写了一个“静”字，并把环境中的静深入到心神中去，情景相融，写出了一种凄苦孤寂的心境。这无疑是作者被贬后心情的曲折反映。', poem_tags = '初中文言文,纪游,写景,孤独,忧伤' WHERE poem_title = '小石潭记' AND poem_author = '柳宗元';
UPDATE edu_poem SET poem_translation = '江南清明时节细雨纷纷飘洒，路上羁旅行人个个落魄断魂。\n借问当地之人何处买酒浇愁？牧童笑而不答遥指杏花山村。', poem_notes = '清明：二十四节气之一，在阳历四月五日前后。旧俗当天有扫墓、踏青、插柳等活动。宫中以当天为秋千节，坤宁宫及各后宫都安置秋千，嫔妃做秋千之戏。\n纷纷：形容多。\n欲断魂：形容伤感极深，好像灵魂要与身体分开一样。断魂：神情凄迷，烦闷不乐。这两句是说，清明时候，阴雨连绵，飘飘洒洒下个不停；如此天气，如此节日，路上行人情绪低落，神魂散乱。\n借问：请问。\n杏花村：杏花深处的村庄。今在安徽贵池秀山门外。受此诗影响，后人多用“杏花村”作酒店名。', poem_appreciation = '这一天正是清明佳节。诗人小杜，在行路中间，可巧遇上了雨。清明，虽然是柳绿花红、春光明媚的时节，可也是气候容易发生变化的期间，常常赶上“闹天气”。远在梁代，就有人记载过：在清明前两天的寒食节，往往有“疾风甚雨”。若是正赶在清明这天下雨，还有个专名叫作“泼火雨”。诗人杜牧遇上的，正是这样一个日子。\n\n　　诗人用“纷纷”两个字来形容那天的“泼火雨”，真是好极了。怎见得呢？“纷纷”，若是形容下雪，那该是大雪，所谓“纷纷扬扬，降下好一场大雪来”。但是临到雨，情况却正相反，那种叫人感到“纷纷”的，绝不是大雨，而是细雨。这细雨，也正就是春雨的特色。细雨纷纷，是那种“天街小雨润如酥”样的雨，它不同于夏天的如倾如注的暴雨，也和那种淅淅沥沥的秋雨绝不是一个味道。这“雨纷纷”，正抓住了清明“泼火雨”的精神，传达了那种“做冷欺花，将烟困柳”的凄迷而又美丽的境界。\n\n　　这“纷纷”在此自然毫无疑问是形容那春雨的意境；可是它又不止是如此而已，它还有一层特殊的作用，那就是，它实际上还在形容着那位雨中行路者的心情。\n\n　　且看下面一句：“路上行人欲断魂”。“行人”，是出门在外的行旅之人，“行人”不等于“游人”，不是那些游春逛景的人。那么什么是“断魂”呢？“魂”就是“三魂七魄”的灵魂吗？不是的。在诗歌里，“魂”指的多半是精神、情绪方面的事情。“断魂”，是极力形容那一种十分强烈、可是又并非明白表现在外面的很深隐的感情，比方相爱相思、惆怅失意、暗愁深恨等等。当诗人有这类情绪的时候，就常常爱用“断魂”这一词语来表达他的心境。\n\n　　清明这个节日，在古人感觉起来，和我们今天对它的观念不是完全一样的。在当时，清明节是个色彩情调都很浓郁的大节日，本该是家人团聚，或游玩观赏，或上坟扫墓，是主要的礼节风俗。除了那些贪花恋酒的公子王孙等人之外，有些头脑的，特别是感情丰富的诗人，他们心头的滋味是相当复杂的。倘若再赶上孤身行路，触景伤怀，那就更容易惹动了他的心事。偏偏又赶上细雨纷纷，春衫尽湿，这给行人就又增添了一层愁绪。这样来体会，才能理解为什么诗人在这当口儿要写“断魂”两个字；否则，下了一点小雨，就值得“断魂”，那不太没来由了吗？\n\n　　这样，我们就又可回到“纷纷”二字上来了。本来，佳节行路之人，已经有不少心事，再加上身在雨丝风片之中，纷纷洒洒，冒雨趱行，那心境更是加倍的凄迷纷乱了。所以说，纷纷是形容春雨，可也形容情绪；甚至不妨说，形容春雨，也就是为了形容情绪。这正是我国古典诗歌里寓情于景、情景交融的一种绝艺，一种胜境。\n\n　　前二句交代了情景，问题也发生了。怎么办呢？须得寻求一个解决的途径。行人在这时不禁想到：往哪里找个小酒店才好。事情很明白：寻到一个小酒店，一来歇歇脚，避避雨；二来小饮三杯，解解料峭中人的春寒，暖暖被雨淋湿的衣服；最要紧的是，借此也就能散散心头的愁绪。于是，向人问路了。\n\n　　是向谁问路的呢？诗人在第三句里并没有告诉我们，妙莫妙于第四句：“牧童遥指杏花村”。在语法上讲，“牧童”是这一句的主语，可它实在又是上句“借问”的宾词——它补足了上句宾主问答的双方。牧童答话了吗？我们不得而知，但是以“行动”为答复，比答话还要鲜明有力。我们看《小放牛》这出戏，当有人向牧童哥问路时，他将手一指，说：“您顺着我的手儿瞧！”是连答话带行动——也就是连“音乐”带“画面”，两者同时都使观者获得了美的享受；如今诗人手法却更简捷，更高超：他只将“画面”给予读者，而省去了“音乐”。不，不如说是包括了“音乐”，读者欣赏了那一指路的优美“画面”，同时也就隐隐听到了答话的“音乐”。\n\n　　“遥”，字面意义是远。但我们读诗的人，切不可处处拘守字面意义，认为杏花村一定离这里还有十分遥远的路程。这一指，已经使我们如同看到，隐约红杏梢头，分明挑出一个酒帘——“酒望子”来了。若真的距离遥远，就难以发生艺术联系，若真的就在眼前，那又失去了含蓄无尽的兴味：妙就妙在不远不近之间。《红楼梦》里大观园中有一处景子题作“杏帘在望”，那“在望”的神情，正是由这里体会脱化而来，正好为杜郎此句作注脚。《小放牛》里的牧童也说，“我这里，用手儿一指，……前面的高坡，有几户人家，那杨柳树上挂着一个大招牌”，然后他叫女客人“你要吃好酒就在杏花村”，也是从这里脱化出来的。“杏花村”不一定是真村名，也不一定即指酒家。这只需要说明指往这个美丽的杏花深处的村庄就够了，不言而喻，那里是有一家小小的酒店在等候接待雨中行路的客人的。\n\n　　不但如此。在实际生活中，问路只是手段，目的是得真的奔到了酒店，而且喝到了酒，才算一回事。在诗里就不必然了，它恰恰只写到“遥指杏花村”就戛然而止，再不多费一句话。剩下的，行人怎样地闻讯而喜，怎样地加把劲儿趱上前去，怎样地兴奋地找着了酒店，怎样地欣慰地获得了避雨、消愁两方面的满足和快意……，这些诗人就能“不管”了。他把这些都含蓄在篇幅之外，付与读者的想象，由读者自去寻求领会。他只将读者引入一个诗的境界，他可并不负责导游全景；另一面，他却为读者开展了一处远比诗篇语文字句所显示的更为广阔得多的想象余地。这就是艺术的“有余不尽”。\n\n　　这才是诗人和我们读者的共同享受，这才是艺术，这也是我国古典诗歌所特别擅场的地方。古人曾说过，好的诗，能够“状难写之景，如在目前；含不尽之意，在于言外”。拿这首《清明》绝句来说，在一定意义上，也是当之无愧的。\n\n　　这首小诗，一个难字也没有，一个典故也不用，整篇是十分通俗的语言，写得自如之极，毫无经营造作之痕。音节十分和谐圆满，景象非常清新、生动，而又境界优美、兴味隐跃。诗由篇法讲也很自然，是顺序的写法。第一句交代情景、环境、气氛，是“起”；第二句是“承”，写出了人物，显示了人物的凄迷纷乱的心境；第三句是一“转”，然而也就提出了如何摆脱这种心境的办法；而这就直接逼出了第四句，成为整篇的精彩所在—“合”。在艺术上，这是由低而高、逐步上升、高潮顶点放在最后的手法。所谓高潮顶点，却又不是一览无余，索然兴尽，而是余韵邈然，耐人寻味。这些，都是诗人的高明之处，也就是值得我们学习继承的地方吧！', poem_tags = '清明节,写雨,写人,行路,早教古诗100首' WHERE poem_title = '清明' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '明亮的月光洒在床前的窗户纸上，好像地上泛起了一层霜。\n我禁不住抬起头来，看那天窗外空中的一轮明月，不由得低头沉思，想起远方的家乡。\n\n韵译\n皎洁月光洒满床，恰似朦胧一片霜。\n仰首只见月一轮，低头教人倍思乡。', poem_notes = '静夜思：静静的夜里，产生的思绪 。\n床：今传五种说法。\n一指井台。已经有学者撰文考证过。中国教育家协会理事程实将考证结果写成论文发表在刊物上，还和好友创作了《诗意图》。\n二指井栏。从考古发现来看，中国最早的水井是木结构水井。古代井栏有数米高，成方框形围住井口，防止人跌入井内，这方框形既像四堵墙，又像古代的床。因此古代井栏又叫银床，说明井和床有关系，其关系的发生则是由于两者在形状上的相似和功能上的类同。古代井栏专门有一个字来指称，即“韩”字。《说文》释“韩”为“井垣也”，即井墙之意。\n三“床”即“窗”的通假字。本诗中的‘床’字，是争论和异议的焦点。我们可以做一下基本推理。本诗的写作背景是在一个明月夜，很可能是月圆前后，作者由看到月光，再看到明月，又引起思乡之情。 \n既然作者抬头看到了明月，那么作者不可能身处室内，在室内随便一抬头，是看不到月亮的。因此我们断定，‘床’是室外的一件物什，至于具体是什么，很难考证。从意义上讲，‘床’可能与‘窗’通假，而且在窗户前面是可能看到月亮的。但是，参照宋代版本，‘举头望山月’，便可证实作者所言乃是室外的月亮。从时间上讲，宋代版本比明代版本在对作者原意的忠诚度上，更加可靠。 \n四取本义，即坐卧的器具，《诗经·小雅·斯干》有“载寐之牀”，《易·剥牀·王犊注》亦有“在下而安者也。”之说，讲得即是卧具。\n五马未都等认为，床应解释为胡床。胡床，亦称“交床”、“交椅”、“绳床”。古时一种可以折叠的轻便坐具，马扎功能类似小板凳，但人所坐的面非木板，而是可卷折的布或类似物，两边腿可合起来。现代人常为古代文献中或诗词中的“胡床”或“床”所误。至迟在唐时，“床”仍然是“胡床”（即马扎，一种坐具）。\n疑：好像。 \n举头：抬头。', poem_appreciation = '这是写远客思乡之情的诗，诗以明白如话的语言雕琢出明静醉人的秋夜的意境。\n\n　　它不追求想象的新颖奇特，也摒弃了辞藻的精工华美；它以清新朴素的笔触，抒写了丰富深曲的内容。境是境，情是情，那么逼真，那么动人，百读不厌，耐人寻绎。无怪乎有人赞它是“妙绝古今”。\n\n　　胡应麟说：“太白诸绝句，信口而成，所谓无意于工而无不工者。”（《诗薮·内编》卷六）王世懋认为：“（绝句）盛唐惟青莲（李白）、龙标（王昌龄）二家诣极。李更自然，故居王上。”（《艺圃撷馀》）怎样才算“自然”，才是“无意于工而无不工”呢？这首《静夜思》就是个样榜。所以胡氏特地把它提出来，说是“妙绝古今”。\n\n　　这首小诗，既没有奇特新颖的想象，更没有精工华美的辞藻；它只是用叙述的语气，写远客思乡之情，然而它却意味深长，耐人寻绎，千百年来，如此广泛地吸引着读者。\n\n　　一个作客他乡的人，大概都会有这样的感觉吧：白天倒还罢了，到了夜深人静的时候，思乡的情绪，就难免一阵阵地在心头泛起波澜；何况是月明之夜，更何况是明月如霜的秋夜！\n\n　　月白霜清，是清秋夜景；以霜色形容月光，也是古典诗歌中所经常看到的。例如梁简文帝萧纲《玄圃纳凉》诗中就有“夜月似秋霜”之句；而稍早于李白的唐代诗人张若虚在《春江花月夜》里，用“空里流霜不觉飞”来写空明澄澈的月光，给人以立体感，尤见构思之妙。可是这些都是作为一种修辞的手段而在诗中出现的。这诗的“疑是地上霜”，是叙述，而非摹形拟象的状物之辞，是诗人在特定环境中一刹那间所产生的错觉。为什么会有这样的错觉呢？不难想象，这两句所描写的是客中深夜不能成眠、短梦初回的情景。这时庭院是寂寥的，透过窗户的皎洁月光射到床前，带来了冷森森的秋宵寒意。诗人朦胧地乍一望去，在迷离恍惚的心情中，真好象是地上铺了一层白皑皑的浓霜；可是再定神一看，四周围的环境告诉他，这不是霜痕而是月色。月色不免吸引着他抬头一看，一轮娟娟素魄正挂在窗前，秋夜的太空是如此的明净！这时，他完全清醒了。\n\n　　秋月是分外光明的，然而它又是清冷的。对孤身远客来说，最容易触动旅思秋怀，使人感到客况萧条，年华易逝。凝望着月亮，也最容易使人产生遐想，想到故乡的一切，想到家里的亲人。想着，想着，头渐渐地低了下去，完全浸入于沉思之中。\n\n　　从“疑”到“举头”，从“举头”到“低头”，形象地揭示了诗人内心活动，鲜明地勾勒出一幅生动形象的月夜思乡图。\n\n　　短短四句诗，写得清新朴素，明白如话。它的内容是单纯的，但同时却又是丰富的。它是容易理解的，却又是体味不尽的。诗人所没有说的比他已经说出来的要多得多。它的构思是细致而深曲的，但却又是脱口吟成、浑然无迹的。从这里，我们不难领会到李白绝句的“自然”、“无意于工而无不工”的妙境。', poem_tags = '唐诗三百首,小学古诗,月亮,思乡,早教古诗100首' WHERE poem_title = '静夜思' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '大江浩浩荡荡向东流去，滔滔巨浪淘尽千古英雄人物。\n那旧营垒的西边，人们说那就是三国周瑜鏖战的赤壁。\n陡峭的石壁直耸云天，如雷的惊涛拍击着江岸，激起的浪花好似卷起千万堆白雪。\n雄壮的江山奇丽如图画，一时间涌现出多少英雄豪杰。\n遥想当年的周瑜春风得意，绝代佳人小乔刚嫁给他，他英姿奋发豪气满怀。\n手摇羽扇头戴纶巾，谈笑之间，强敌的战船烧得灰飞烟灭。\n我今日神游当年的战地，可笑我多情善感，过早地生出满头白发。\n人生犹如一场梦，且洒一杯酒祭奠江上的明月。', poem_notes = '念奴娇：词牌名。又名“百字令”“酹江月”等。赤壁：此指黄州赤壁，一名“赤鼻矶”，在今湖北黄冈西。而三国古战场的赤壁，文化界认为在今湖北赤壁市蒲圻县西北。\n大江：指长江。\n淘：冲洗，冲刷。\n风流人物：指杰出的历史名人。\n故垒：过去遗留下来的营垒。\n周郎：指三国时吴国名将周瑜，字公瑾，少年得志，二十四为中郎将，掌管东吴重兵，吴中皆呼为“周郎”。下文中的“公瑾”，即指周瑜。\n雪：比喻浪花。\n遥想：形容想得很远；回忆。\n小乔初嫁了（liǎo）：《三国志·吴志·周瑜传》载，周瑜从孙策攻皖，“得桥公两女，皆国色也。策自纳大桥，瑜纳小桥。”乔，本作“桥”。其时距赤壁之战已经十年，此处言“初嫁”，是言其少年得意，倜傥风流。\n雄姿英发（fā）：谓周瑜体貌不凡，言谈卓绝。英发，谈吐不凡，见识卓越。\n羽扇纶（guān）巾：古代儒将的便装打扮。羽扇，羽毛制成的扇子。纶巾，青丝制成的头巾。\n樯橹（qiánglǔ）：这里代指曹操的水军战船。樯，挂帆的桅杆。橹，一种摇船的桨。“樯橹”一作“强虏”，又作“樯虏”，又作“狂虏”。\n故国神游：“神游故国”的倒文。故国：这里指旧地，当年的赤壁战场。神游：于想象、梦境中游历。\n“多情”二句：“应笑我多情，早生华发”的倒文。华发（fà）：花白的头发。\n一尊还（huán）酹（lèi）江月：古人祭奠以酒浇在地上祭奠。这里指洒酒酬月，寄托自己的感情。尊：通“樽”，酒杯。\n强虏：强大之敌，指曹军。虏：对敌人的蔑称。', poem_appreciation = '《核舟记》 　　苏东坡的词《念奴娇·赤壁怀古》逸怀浩气、举首高歌，意境开阔博大，感慨隐约深沉，为我们开拓了一个新的世界。他借用怀古抒情，以旷达之心关注历史和人生，文辞高妙精绝，生动感人，因此《念奴娇·赤壁怀古》不但成为后世广为诵读的文学名篇，而且也成为各类艺术广为表现的内容，涌现了许多艺术精品，《核舟记》就是这样一篇反映“苏轼游赤壁怀古抒情”艺术珍品的著名文章。《核舟记》是由明代作家魏学洢所作，由同时代学者张潮编选到《虞初新志》。《核舟记》生动的描述了一件精巧绝伦的微雕工艺品（用桃核雕刻成的小船），刻的是苏东坡与黄庭坚、佛印泛舟游赤壁的情景。小核舟只有两个黄米粒那么高，船舱、小窗、栏杆如真的一般。总计一条船，刻了五个人，八扇窗户；箬竹叶做的船篷、船桨、炉子、茶壶、手卷、念珠各一件；对联、题名和篆文，文字共计三十四字。可是计算它的长度，还不满一寸。文章语言平实、洗练，生动的表现了历史上苏东坡携好友泛舟游赤壁，面对“大江东去”，“ 遥想公瑾当年”，吟诵“赤壁怀古”那段著名的文学故事。本文使用从两头到中间，从正面到背面的空间顺序，介绍了“核舟”的构件、雕刻和精湛，热情赞扬了中国古代的民间工艺匠人的雕刻艺术和才能.表现了作者对明代艺人王毅精湛工艺的赞美。《核舟记》也从另一个侧面通过精妙的微雕工艺品，向人们直观展现了“赤壁怀古”所营造的“江山如画”那优美意境。然而，由于时代较久远，王毅的《东坡游赤壁》核舟没有实物传世。\n\n　　在后来的核舟作品中，《东坡夜游赤壁》历来是雕刻工艺家们常用的题材。至清代，广东的宫廷工艺家陈祖章在学习、借鉴前人的基础上，创作《东坡夜游赤壁》核舟，并在技艺、内涵上都有所发展，人物除苏东坡外，有客人、客妇、艄公、书童等7人，个个刻画精致，人物神态自然、宁静、超逸。陈祖章的核舟有一件传世，现藏于台北故宫博物院，成为镇馆之宝。上海文化出版社的《国宝大观》上是这样介绍的：“此舟呈稍深的橘红色，高1.6厘米，长3.4厘米。舟上设备齐全，舱中备有桌椅，并摆着杯盘菜肴，小窗镂空，可开可闭。舟上八人，异彩纷呈，为苏东坡泛舟夜游赤壁故事。舟底镌刻着细字《念奴娇·赤壁怀古》全文，下有“乾隆丁巳五月臣陈祖掌”款。\n\n另一读本 　　除上述《念奴娇·赤壁怀古》原文外，有另一读法，即：“乱石崩云，惊涛裂岸”。\n\n　　“乱石穿空，惊涛拍岸”的“穿”和“拍”是一组动词，使整个画面充满了动感和力度感，极富冲击力；而“乱石崩云，惊涛裂岸”的“崩”和“裂”，则强调了这种力量所带来的效果：乱石直插云霄，使云霞崩开了；惊涛怒卷江岸，使土石裂碎了，这些明显带有夸张想象的成分。好坏就看读者个人的喜好了。\n\n　　“樯橹”和“强虏”，前者字面意义为“舟楫船桨”，后者为“强劲的敌人”。在前一句中，词作者使用了借代的手法，即不直接说出某物，而以与之密切相关的事物来替代的修辞手法。用“樯橹”指代使用“樯橹”的强劲的敌人。', poem_tags = '宋词三百首,豪放,长江,咏史怀古,抒怀,怀才不遇,人生' WHERE poem_title = '念奴娇·赤壁怀古' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '风和日丽游春在泗水之滨，无边无际的风光焕然一新。\n谁都可以看出春天的面貌，春风吹得百花开放、万紫千红，到处都是春天的景致。', poem_notes = '春日：春天。\n胜日：天气晴朗的好日子，也可看出人的好心情。\n寻芳：游春，踏青。\n泗水：河名，在山东省。\n滨：水边，河边。\n光景：风光风景。\n等闲：平常、轻易。“等闲识得”是容易识别的意思。\n东风：春风。', poem_appreciation = '人们一般都认为这是一首咏春诗。从诗中所写的景物来看，也很像是这样。首句“胜日寻芳泗水滨”，“胜日”指晴日，点明天气。“泗水滨”点明地点。“寻芳”，即是寻觅美好的春景，点明了主题。下面三句都是写“寻芳”所见所得。次句“无边光景一时新”，写观赏春景中获得的初步印象。用“无边”形容视线所及的全部风光景物。“一时新”，既写出春回大地，自然景物焕然一新，也写出了作者郊游时耳目一新的欣喜感觉。第三句“等闲识得东风面”，句中的“识”字承首句中的“寻”字。“等闲识得”是说春天的面容与特征是很容易辨认的。“东风面”借指春天。第四句“万紫千红总是春”，是说这万紫千红的景象全是由春光点染而成的，人们从这万紫千红中认识了春天。感受到了春天的美。这就具体解答了为什么能“等闲识得东风面”。而此句的“万紫千红”又照应了第二句中的“光景一时新”。第三、四句是用形象的语言具体写出光景之新，寻芳所得。\n\n　　从字面上看，这首诗好像是写游春观感，但细究寻芳的地点是泗水之滨，而此地在宋南渡时早被金人侵占。朱熹未曾北上，当然不可能在泗水之滨游春吟赏。其实诗中的的“泗水”是暗指孔门，因为春秋时孔子曾在洙、泗之间弦歌讲学，教授弟子。因此所谓“寻访”即是指求圣人之道。“万紫千红”喻孔学的丰富多彩。诗人将圣人之道比作催发生机、点燃万物的春风。这其实是一首寓理趣于形象之中的哲理诗。', poem_tags = '古诗三百首,小学古诗,春天,写景,哲理,早教古诗100首' WHERE poem_title = '春日' AND poem_author = '朱熹';
UPDATE edu_poem SET poem_translation = '天色黄昏，一群乌鸦落在枯藤缠绕的老树上，发出凄厉的哀鸣。\n小桥下流水哗哗作响，小桥边庄户人家炊烟袅袅。\n古道上一匹瘦马，顶着西风艰难地前行。\n夕阳渐渐地失去了光泽，从西边落下。\n凄寒的夜色里，只有孤独的旅人漂泊在遥远的地方。', poem_notes = '枯藤：枯萎的枝蔓。昏鸦：黄昏时归巢的乌鸦。昏：傍晚。\n人家：农家。此句写出了诗人对温馨的家庭的渴望。\n古道：已经废弃不堪再用的古老驿道（路）或年代久远的驿道。西风：寒冷、萧瑟的秋风。瘦马：瘦骨如柴的马。\n断肠人：形容伤心悲痛到极点的人，此指漂泊天涯、极度忧伤的旅人。\n天涯：远离家乡的地方。', poem_appreciation = '这首小令很短，一共只有五句二十八个字，全曲无一秋字，但却描绘出一幅凄凉动人的秋郊夕照图，并且准确地传达出旅人凄苦的心境。被赞为秋思之祖这首成功的曲作，从多方面体现了中国古典诗歌的艺术特征。\n\n　　一、以景托情，寓情于景，在景情的交融中构成一种凄凉悲苦的意境。\n\n　　中国古典诗歌十分讲究意境的创造。意境是中国古典诗歌美学中的一个重要范畴，它的本质特征在于情景交融、心物合一。情与景能否妙合，成为能否构成意境的关键。清王夫之《萱斋诗话》曰：“情景名为二，而实不可离。神于诗者，妙合无垠。”王国维《人间词话删稿》云：“一切景语皆情语也。”马致远这首小令，前四句皆写景色，这些景语都是情语，“枯”“老”“昏”“瘦”等字眼使浓郁的秋色之中蕴含着无限凄凉悲苦的情调。而最后一句“断肠人在天涯”作为曲眼更具有画龙点睛之妙，使前四句所描之景成为人活动的环境，作为天涯断肠人内心悲凉情感的触发物。曲上的景物既是马致远旅途中之所见，乃眼中物。但同时又是其情感载体，乃心中物。全曲景中有情，情中有景，情景妙合，构成了一种动人的艺术境界。\n\n　　二、使用众多密集的意象来表达作者的羁旅之苦和悲秋之恨，使作品充满浓郁的诗情。\n\n　　意象是指出现在诗歌之中的用以传达作者情感，寄寓作者思想的艺术形象。中国古典诗歌往往具有使用意象繁复密集的特色。中国古代不少诗人常常在诗中紧密地排列众多的意象来表情达意。马致远此曲明显地体现出这一特色。短短的二十八字中排列着十种意象，这些意象既是断肠人生活的真实环境，又是他内心沉重的忧伤悲凉的载体。如果没有这些意象，这首曲也就不复存在了。\n\n　　与意象的繁复性并存的是意象表意的单一性。在同一作品之中，不同的意象的地位比较均衡，并无刻意突出的个体，其情感指向趋于一致，即众多的意象往往共同传达着作者的同一情感基调。此曲亦如此。作者为了表达自己惆怅感伤的情怀，选用众多的物象入诗。而这些物象能够传达作者的内心情感，情与景的结合，便使作品中意象的情感指向呈现一致性、单一性。众多的意象被作者的同一情感的线索串联起来，构成一幅完整的图画。\n\n　　意象的繁复性与单一性的结合，是造成中国古典诗歌意蕴深厚、境界和谐、诗味浓重的重要原因。\n\n　　古典诗歌中意象的安排往往具有多而不乱，层次分明的特点，这种有序性的产生得力于作者以时间、空间的正常顺序来安排意象的习惯。\n\n　　今天有人称马致远的这首《天净沙·秋思》为“并列式意象组合”，其实并列之中依然体现出一定的顺序来。全曲十个意象，前九个自然地分为三组。藤缠树，树上落鸦，第一组是由下及上的排列；桥、桥下水、水边住家，第二组是由近由远的排列；古驿道、道上西风瘦马，第三组是从远方而到目前的排列，中间略有变化。由于中间插入“西风”写触感，变换了描写角度，因而增加了意象的跳跃感，但这种跳跃仍是局部的，不超出秋景的范围。最后一个意象“夕阳西下”，是全曲的大背景，它将前九个意象全部统摄起来，造成一时多空的场面。由于它本身也是放远目光的产物，因此作品在整体上也表现出由近及远的空间排列顺序。从老树到流水，到古道，再到夕阳，作者的视野层层扩大，步步拓开。这也是意象有序性的表现之一。\n\n　　三、善于加工提炼，用极其简练的白描手法，勾勒出一由游子深秋远行图。\n\n　　马致远《天净沙·秋思》小令中出现的意象并不新颖。其中“古道”一词，最早出现在署名为李白《忆秦娥·箫声咽》词中“乐游原上清秋节，咸阳古道音尘绝”。宋张炎《壶中天·扬舲万里》词中也有“老柳官河，斜阳古道，风定波犹直”。\n\n　　董解元《西厢记》中有一曲【仙吕·赏花时】：“落日平林噪晚鸦，风袖翩翩吹瘦马，一经入天涯，荒凉古岸，衰草带霜滑。瞥见个孤林端入画，蓠落萧疏带浅沙。一个老大伯捕鱼虾，横桥流水。茅舍映荻花。”其中有六个意象出现在马曲之中。\n\n　　又有元代无名氏小令《醉中天》（见《乐府新声》）：“老树悬藤挂，落日映残霞。隐隐平林噪晓鸦。一带山如画，懒设设鞭催瘦马。夕阳西下，竹篱茅舍人家。”也有六个意象与马曲相同。\n\n　　十分明显，《醉中天》是从《赏花时》中脱化而来，模拟痕迹犹在，二曲中出现的意象虽与马曲多有相同之处，但相比之下，皆不如《天净沙·秋思》纯朴、自然、精练。\n\n　　马致远在创作《天净沙·秋思》时受到董曲的影响和启发，这是无疑的，但他不是一味模仿，而是根据自己的生活体验与审美目光进行了重新创作。在景物的选择上，他为了突出与强化凄惨凉悲苦的情感，选取了最能体现秋季凄凉萧条景色，最能表现羁旅行人孤苦惆怅情怀的十个意象入曲，将自己的情感浓缩于这十个意象之中，最后才以点晴之笔揭示全曲主题。他删了一些虽然很美，但与表达的情感不合的景物。如茅舍映荻花，落日映残霞，一带山如画，使全曲的意象在表达情感上具有统一性。\n\n　　在词句的锤炼上，马致远充分显示了他的才能，前三句十八个字中，全是名词和形容词，无一动词，各种景物的关系以及它们各自的动态与形状，全靠读者根据意象之间的组织排列顺序以及自己的生活经验去把握。这种奇妙的用字法，实在为古之所罕见，温庭筠《商山早行》中“鸡声茅店月，人迹板桥霜”与马曲用字法相似，但其容量仍不如马曲大。马曲用字之简练已达到不能再减的程度，用最少的文字来表达丰富的情感，这正是《天净沙·秋思》这首小令艺术上取得成功的原因之一。\n\n　　四、采用悲秋这一审美情感体验方式，来抒发羁旅游子的悲苦情怀，使个人的情感获得普遍的社会意义。\n\n　　悲秋，是人们面对秋景所产生的一种悲哀忧愁的情绪体验，由于秋景（特别是晚秋）多是冷落、萧瑟、凄暗，多与黄昏、残阳、落叶、枯枝相伴，成为万物衰亡的象征，故秋景一方面确能给人以生理上的寒感，另一方面又能引发人心之中固有的种种悲哀之情。宋玉首开中国以悲秋为主要审美体验形式的感伤主义文学先河，他通过描写秋日“草木摇落而变衰”的萧瑟景象，抒发自己对人生仕途的失意之感，而且他将自己面对秋色所产生的凄苦悲凉的意绪形容成犹如远行一般，“僚僳兮（凄凉），若在远行”，“廓落兮（孤独空寂），羁旅而无友生”。这就说明悲秋与悲远行在情绪体验上有着相同之处。宋玉之后悲秋逐渐成为中国文人最为普遍的审美体验形式之一，而且将悲秋与身世之叹紧密地联系在一起。杜甫“万里悲秋常作客”便是一例。马致远这首小令也是如此。虽然曲中的意象不算新颖，所表达的情感也不算新鲜，但是由于它使用精练的艺术表达方式，表达出中国文人一种传统的情感体验，因此它获得了不朽的生命力，可以引起后世文人的共鸣。\n\n　　通过以上分析可以看出，《天净沙·秋思》属于中国古典诗歌之中最为成熟的作品之一。尽管它属于曲体，但实际上，在诸多方面体现着中国古典诗歌的艺术特征。', poem_tags = '初中古诗,秋天,写景,羁旅,悲秋' WHERE poem_title = '天净沙·秋思' AND poem_author = '马致远';
UPDATE edu_poem SET poem_translation = '驿站之外的断桥边，梅花孤单寂寞地绽开了花，无人过问。暮色降临，梅花无依无靠，已经够愁苦了，却又遭到了风雨的摧残。\n梅花并不想费尽心思去争艳斗宠，对百花的妒忌与排斥毫不在乎。即使凋零了，被碾作泥土，又化作尘土了，梅花依然和往常一样散发出缕缕清香。', poem_notes = '卜（bǔ）算子·咏梅：选自吴氏双照楼影宋本《渭南词》卷二。“卜算子”是词牌名。又名《百尺楼》《眉峰碧》《楚天遥》《缺月挂疏桐》等。万树《词律》卷三《卜算子》：“毛氏云：‘骆义鸟（骆宾王）诗用数名，人谓为“卜算子”，故牌名取之。’按山谷词，‘似扶著卖卜算’，盖取义以今卖卜算命之人也。”\n驿（yì）外：指荒僻、冷清之地。驿：驿站，供驿马或官吏中途休息的专用建筑。\n断桥：残破的桥。一说“断”通“簖”，簖桥乃是古时在为拦河捕鱼蟹而设簖之处所建之桥。\n寂寞：孤单冷清。\n无主：自生自灭，无人照管和玩赏。\n更：副词，又，再。著（zhuó）：同“着”，遭受，承受。更著：又遭到。\n无意：不想，没有心思。自己不想费尽心思去争芳斗艳。\n苦：尽力，竭力。\n争春：与百花争奇斗艳。此指争权。\n一任：全任，完全听凭；一：副词，全，完全，没有例外。任：动词，任凭。\n群芳：群花、百花。百花，这里借指诗人政敌──苟且偷安的主和派。\n妒(dù)：嫉妒。\n零落：凋谢，陨落。\n碾（niǎn）：轧烂，压碎。\n作尘：化作灰土。\n香如故：香气依旧存在。', poem_appreciation = '陶渊明爱菊，为的是 “采菊东篱下，悠然见南山” 的闲适；周敦颐喜莲，为的是“出淤泥而不染，濯清涟而不妖”的高洁；而陆游重梅，则为的是“雪虐风饕愈凛然，花中气节最高坚”的坚贞。这可以从他的《卜算子·咏梅》中得到印证。驿外断桥边，寂寞开无主。已是黄昏独自愁，更着风和雨。无意苦争春，一任群芳妒。零落成泥碾作尘，只有香如故。\n\n　　读罢此诗，我们也不禁会生出“天下可忧非一事，书生无地效孤忠”的感慨来。作为一代伟大的爱国诗人，陆游很早就有“上马击狂胡，下马草君书”的爱国之志，二十九岁时，他以状元秀的身份登上仕途可他面对的不仅仅是一部分卖国求荣的投降派，更面对着苟且偏安的昏帝王。因此面对积贫积弱的现实，诗人只能眼睁睁看着南宋走“以地事秦，犹抱薪救火，薪不尽，火不灭”的破亡之路。一而再，再而三的打击、排挤、贬谪，使诗人不得不发出“胡未灭，鬓先秋，泪空流，此生谁料，心在天山，身老沧州”的浩然长叹了。尽管如此，但是诗人忧国忧民的情怀，不从俗媚的节操没有丝毫的改变。即便到了“食且不继”，因为没钱，药也停了吃；因为省灯油，书也没的读，甚至不得不连自己常用的酒杯都忍痛卖掉的地步，他仍然足迹不踏权门，他依旧胸怀杜稷，心系百姓。我们从中仿佛听到了屈原那“路漫漫其修远兮，吾将上下而求索”的执着与坚定，我们仿佛看到了杜甫那“穷年忧黎园，叹息肠内热”的抑郁与沉重。真可谓“居庙堂之高，则忧其民，处江湖之远，则忧其君，进亦忧，退亦忧”也正是有这样的社会背景，有这样的思想根基，使我们在品读《咏梅》时，更能清楚地看到诗人那至死不渝的追求。\n\n　　纵观全词，诗人以物喻人，托物言志，巧借饱受摧残，花粉犹香的梅花，比喻自己虽终生坎坷，绝不媚俗的忠贞，这也正象他在一首咏梅诗中所写的“过时自合飘零去，耻向东君更气怜”。陆游以他饱满的爱国热情，谱写一曲曲爱国主义诗篇，激励了并激励着一代又一代人，真可谓“双鬓多年作雪，寸心至死如丹”。', poem_tags = '宋词三百首,宋词精选,初中古诗,咏物,梅花,言志' WHERE poem_title = '卜算子·咏梅' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '苦苦地寻寻觅觅，却只见冷冷清清，怎不让人凄惨悲戚。乍暖还寒的时节，最难保养休息。喝三杯两杯淡酒，怎么能抵得住早晨的寒风急袭？一行大雁从眼前飞过，更让人伤心，因为都是旧日的相识。\n园中菊花堆积满地，都已经憔悴不堪，如今还有谁来采摘？冷清清地守着窗子，独自一个人怎么熬到天黑？梧桐叶上细雨淋漓，到黄昏时分，还是点点滴滴。这般情景，怎么能用一个“愁”字了结！', poem_notes = '寻寻觅觅：意谓想把失去的一切都找回来，表现非常空虚怅惘、迷茫失落的心态。\n凄凄惨惨戚戚：忧愁苦闷的样子。\n乍暖还（huán）寒：指秋天的天气，忽然变暖，又转寒冷。\n将息：旧时方言，休养调理之意。\n怎敌他：对付，抵挡。晚：一本作“晓”。\n损：表示程度极高。\n堪：可。\n著：亦写作“着”。\n怎生：怎样的。生：语助词。\n梧桐更兼细雨：暗用白居易《长恨歌》“秋雨梧桐叶落时”诗意。\n这次第：这光景、这情形。\n怎一个愁字了得：一个“愁”字怎么能概括得尽呢？', poem_appreciation = '靖康之变后，李清照国破，家亡，夫死，伤于人事。这时期她的作品再没有当年那种清新可人，浅斟低唱，而转为沉郁凄婉，主要抒写她对亡夫赵明诚的怀念和自己孤单凄凉的景况。此词便是这时期的典型代表作品之一。\n\n　　这首词起句便不寻常，一连用七组叠词。不但在填词方面，即使在诗赋曲也绝无仅有。但好处不仅在此，这七组叠词还极富音乐美。宋词是用来演唱的，因此音调和谐是一个很重要的内容。李清照对音律有极深造诣，所以这七组叠词朗读起来，便有一种大珠小珠落玉盘的感觉。只觉齿舌音来回反复吟唱，徘徊低迷，婉转凄楚，有如听到一个伤心之极的人在低声倾诉，然而她还未开口就觉得已能使听众感觉到她的忧伤，而等她说完了，那种伤感的情绪还是没有散去。一种莫名其妙的愁绪在心头和空气中弥漫开来，久久不散，余味无穷。\n\n　　心情不好，再加上这种乍暖还寒天气，词人连觉也睡不着了。如果能沉沉睡去，那么还能在短暂的时间内逃离痛苦，可是越想入眠就越难以入眠，于是词人就很自然想起亡夫来。披衣起床，喝一点酒暖暖身子再说吧。可是寒冷是由于孤独引起的，而饮酒与品茶一样，独自一人只会觉得分外凄凉。\n\n　　端着一杯淡酒，而在这天暗云低，冷风正劲的时节，却突然听到孤雁的一声悲鸣，那种哀怨的声音直划破天际，也再次划破了词人未愈的伤口，头白鸳鸯失伴飞。词人感叹：唉，雁儿，你叫得这样凄凉幽怨，难道你也像我一样，老年失偶了吗？难道也像我一样，余生要独自一人面对万里层山，千山暮雪吗？胡思乱想之下，泪光迷蒙之中，蓦然觉得那只孤雁正是以前为自己传递情书的那一只。无可奈何花落去，似曾相识燕归来。旧日传情信使仍在，而秋娘与萧郎已死生相隔，人鬼殊途了，物是人非事事休，欲语泪先流。这一奇思妙想包含着无限无法诉说的哀愁。\n\n　　这时看见那些菊花，才发觉花儿也已憔悴不堪，落红满地，再无当年那种“东篱把酒黄昏后，有暗香盈袖”的雅致了。词人想：以往丈夫在世时的日子多么美好，诗词唱和，整理古籍，可如今呢？只剩下自己一个人在受这无边无际的孤独的煎熬了。故物依然，人面全非。“旧时天气旧时衣，只有情怀，不得似往时。”独对着孤雁残菊，更感凄凉。手托香腮，珠泪盈眶。怕黄昏，捱白昼。对着这阴沉的天，一个人要怎样才能熬到黄昏的来临呢？漫长使孤独变得更加可怕。独自一人，连时间也觉得开始变慢起来。\n\n　　好不容易等到了黄昏，却又下起雨来。点点滴滴，淅淅沥沥的，无边丝雨细如愁，下得人心更烦了。再看到屋外那两棵梧桐，虽然在风雨中却互相扶持，互相依靠，两相对比，自己一个人要凄凉多了。\n\n　　急风骤雨，孤雁残菊梧桐，眼前的一切，使词人的哀怨重重叠叠，直至无以复加，不知怎样形容，也难以表达出来。于是词人再也不用什么对比，什么渲染，什么赋比兴了，直截了当地说：“这次第，怎一个愁字了得？”简单直白，反而更觉神妙，更有韵味，更堪咀嚼。相形之下，连李煜的“问君能有几多愁，恰似一江春水向东流”也稍觉失色。一江春水虽然无穷无尽，但毕竟还可形容得出。而词人的愁绪则非笔墨所能形容，自然稍胜一筹。\n\n　　前人评此词，多以开端三句用一连串叠字为其特色。但只注意这一层，不免失之皮相。词中写主人公一整天的愁苦心情，却从“寻寻觅觅”开始，可见她从一起床便百无聊赖，如有所失，于是东张西望，仿佛飘流在海洋中的人要抓到点什么才能得救似的，希望找到点什么来寄托自己的空虚寂寞。下文“冷冷清清”，是“寻寻觅觅”的结果，不但无所获，反被一种孤寂清冷的气氛袭来，使自己感到凄惨忧戚。于是紧接着再写了一句“凄凄惨惨戚戚”。仅此三句，一种由愁惨而凄厉的氛围已笼罩全篇，使读者不禁为之屏息凝神。这乃是百感迸发于中，不得不吐之为快，所谓“欲罢不能”的结果。\n\n　　“乍暖还寒时候”这一句也是此词的难点之一。此词作于秋天，但秋天的气候应该说“乍寒还暖”，只有早春天气才能用得上“乍暖还寒”。这是写一日之晨，而非写一季之候。秋日清晨，朝阳初出，故言“乍暖”；但晓寒犹重，秋风砭骨，故言“还寒”。至于“时候”二字，有人以为在古汉语中应解为“节候”；但柳永《永遇乐》云：“薰风解愠，昼景清和，新霁时候。”由阴雨而新霁，自属较短暂的时间，可见“时候”一词在宋时已与现代汉语无殊了。“最难将息”句则与上文“寻寻觅觅”句相呼应，说明从一清早自己就不知如何是好。\n\n　　下面的“三杯两盏淡酒，怎敌他晓来风急”，正与上文“乍暖还寒”相合。古人晨起于卯时饮酒，又称“扶头卯酒”。这里说用酒消愁是不抵事的。至于下文“雁过也”的“雁”，是南来秋雁，正是往昔在北方见到的，所以说“正伤心，却是旧时相识”了。《唐宋词选释》说：“雁未必相识，却云‘旧时相识’者，寄怀乡之意。赵嘏《寒塘》：‘乡心正无限，一雁度南楼。’词意近之。”\n\n　　上片从一个人寻觅无着，写到酒难浇愁；风送雁声，反而增加了思乡的惆怅。于是下片由秋日高空转入自家庭院。园中开满了菊花，秋意正浓。这里“满地黄花堆积”是指菊花盛开，而非残英满地。“憔悴损”是指自己因忧伤而憔悴瘦损，也不是指菊花枯萎凋谢。正由于自己无心看花，虽值菊堆满地，却不想去摘它赏它，这才是“如今有谁堪摘”的确解。然而人不摘花，花当自萎；及花已损，则欲摘已不堪摘了。这里既写出了自己无心摘花的郁闷，又透露了惜花将谢的情怀，笔意比唐人杜秋娘所唱的“有花堪折直须折，莫待无花空折枝”要深远多了。\n\n　　从“守著窗儿”以下，写独坐无聊，内心苦闷之状，比“寻寻觅觅”三句又进一层。“守著”句如依张惠言《词选》断句，以“独自”连上文。秦观（一作无名氏）《鹧鸪天》下片：“无一语，对芳樽，安排肠断到黄昏。甫能炙得灯儿了，雨打梨花深闭门”，与此词意境相近。但秦词从人对黄昏有思想准备方面着笔，李则从反面说，好像天有意不肯黑下来而使人尤为难过。“梧桐”两句不仅脱胎淮海，而且兼用温庭筠《更漏子》下片“梧桐树，三更雨，不道离情正苦；一叶叶，一声声，空阶滴到明”词意，把两种内容融而为一，笔更直而情更切。最后以“怎一个愁字了得”句作收，也是蹊径独辟之笔。自庾信以来，或言愁有千斛万斛，或言愁如江如海（分别见李煜、秦观词），总之是极言其多。这里却化多为少，只说自己思绪纷茫复杂，仅用一个“愁”字如何包括得尽。妙在又不说明于一个“愁”字之外更有什么心情，即戛然而止，仿佛不了了之。表面上有“欲说还休”之势，实际上已倾泻无遗，淋漓尽致了。\n\n　　这首词大气包举，别无枝蔓，相关情事逐一说来，却始终紧扣悲秋之意，深得六朝抒情小赋之神髓，而以接近口语的朴素清新的语言谱入新声，运用凄清的音乐性语言进行抒情，又却体现了倚声家的不假雕饰的本色，诚属个性独具的抒情名作。', poem_tags = '宋词三百首,宋词精选,高中古诗,婉约,闺怨,孤独,怀人' WHERE poem_title = '声声慢·寻寻觅觅' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '河边芦苇青苍苍，秋深露水结成霜。 意中之人在何处？就在河水那一方。\n逆着流水去找她，道路险阻又太长。 顺着流水去找她，仿佛在那水中央。\n河边芦苇密又繁，清晨露水未曾干。 意中之人在何处?就在河岸那一边。\n逆着流水去找她，道路险阻攀登难。 顺着流水去找她，仿佛就在水中滩。\n河边芦苇密稠稠，早晨露水未全收。 意中之人在何处?就在水边那一头。\n逆着流水去找她，道路险阻曲难求。 顺着流水去找她，仿佛就在水中洲。', poem_notes = '蒹（jiān）：没长穗的芦苇。葭（jiā）：初生的芦苇。苍苍：鲜明、茂盛貌。下文“萋萋”、“采采”义同。\n苍苍： 茂盛的样子。\n为：凝结成。\n所谓：所说的，此指所怀念的。\n伊人：那个人，指所思慕的对象。\n一方：那一边。\n溯洄：逆流而上。下文“溯游”指顺流而下。一说“洄”指弯曲的水道，“游”指直流的水道。\n从：追寻。\n阻：险阻，（道路）难走。\n宛：宛然，好像。\n晞（xī）：干。\n湄：水和草交接的地方，也就是岸边。\n跻（jī）：水中高地。\n坻（chí）：水中的沙滩\n涘（sì）：水边。\n右：迂回曲折。\n沚（zhǐ）：水中的沙滩。', poem_appreciation = '东周时的秦地大致相当于今天的陕西大部及甘肃东部。其地“迫近戎狄”，这样的环境迫使秦人“修习战备，高尚气力”（《汉书·地理志》），而他们的情感也是激昂粗豪的。保存在《秦风》里的十首诗也多写征战猎伐、痛悼讽劝一类的事，似《蒹葭》、《晨风》这种凄婉缠绵的情致却更像郑卫之音的风格。 　　诗中“白露为霜”给读者传达出节序已是深秋了，而天才破晓，因为芦苇叶片上还存留着夜间露水凝成的霜花。就在这样一个深秋的凌晨，诗人来到河边，为的是追寻那思慕的人儿，而出现在眼前的是弥望的茫茫芦苇丛，呈出冷寂与落寞，诗人所苦苦期盼的人儿在哪里呢？只知道在河水的另外一边。但这是一个确定性的存在吗？从下文看，并非如此。是诗人根本就不明伊人的居处，还是伊人像“东游江北岸，夕宿潇湘沚”的“南国佳人”（曹植《杂诗七首》之四）一样迁徙无定，也无从知晓。这种也许是毫无希望但却充满诱惑的追寻在诗人脚下和笔下展开。把“溯洄”、“溯游”理解成逆流而上和顺流而下或者沿着弯曲的水道和沿着直流的水道，都不会影响到对诗意的理解。在白居易《长恨歌）中，杨贵妃消殒马嵬坡后，玄宗孤灯独守，寒衾难眠，通过道士鸿都客“上穷碧落下黄泉”的寻找，仍是“两处茫茫皆不见”，但终究在“虚无缥缈”的海外仙山上找到了已成仙的杨贵妃，相约重逢于七夕。而《蒹葭》中，诗人一番艰劳的上下追寻后，伊人仿佛在河水中央，周围流淌着波光，依旧无法接近。《周南·汉广》中诗人也因为汉水太宽无法横渡而不能求得“游女”，陈启源说：“夫说（悦）之必求之，然惟可见而不可求，则慕说益至。”（《毛诗稽古编·附录》）“可见而不可求”，可望而不可即，加深着渴慕的程度。诗中“宛”字表明伊人的身影是隐约缥缈的，或许根本上就是诗人痴迷心境下生出的幻觉。以下两章只是对首章文字略加改动而成，这种仅对文字略加改动的重章叠唱是《诗经》中常用的手法。具体到此诗，这种改动都是在韵脚上——首章“苍、霜、方、长、央”属阳部韵，次章“凄、唏、湄、跻、坻”属脂微合韵，三章“采、已、涣、右、浊”属之部韵——如此而形成各章内部韵律协和而各章之间韵律参差的效果，给人的感觉是：变化之中又包涵了稳定。同时，这种改动也造成了语义的往复推进。如“白露为霜”、“白露未晞”、“白露未已”——夜间的露水凝成霜花，霜花因气温升高而融为露水，露水在阳光照射下蒸发——表明了时间的延续。 　　此诗曾被认为是用来讥刺秦襄公不能用周礼来巩固他的国家（《毛诗序》、郑笺），或惋惜招引隐居的贤士而不可得（姚际恒《诗经通论》、方玉润《诗经原始》）。但跟《诗经》中多数诗内容往往比较具体实在不同，此诗并没有具体的事件与场景，甚至连“伊人”的性别都难以确指。上述两种理解也许当初是有根据的，但这些根据或者没有留存下来，或者不足以服人，因而他们的结论也就让人怀疑了。《诗经》的历代注家往往是求之愈深，却得到失之愈远的相反结果。况且“一切历史都是当代史”（见英国哲学家、历史学家科林伍德《历史观念》），对文本的阐释也具有当代性。现代大多数学者都把它看作是一首爱情诗，先以苍苍的蒹葭起兴，再写男子追求意中人，所追的人在何方?在茂密的蒹葭丛里，似见非见，时隐时现。这首诗用反复重章来表现悬念迭起。“苍苍”、“萋萋”、“采采”近义；白露“未霜”“未晞”、“未已”，内容也差不多。总之，这首诗的重章整齐、浅显，读起来节奏明快、动听。 　　诗意的空幻虚泛给阐释带来了麻烦，但也因而扩展了其内涵的包容空间。读者触及隐藏在描写对象后面的东西，就感到这首诗中的物象，不只是被诗人拿来单纯地歌咏，其中更蕴育着某些象征的意味。“在水一方”为企慕的象征，钱钟书《管锥编》已申说甚详。“溯洄”、“溯游”、“道阻且长”、“宛在水中央”也不过是反覆追寻与追寻的艰难和渺茫的象征。诗人上下求索，而伊人虽隐约可见却依然遥不可及。《西厢记》中莺莺在普救寺中因母亲的拘系而不能与张生结合，叹惜“隔花阴人远天涯近”，《蒹葭》中的诗人也是同样的感觉罢。 　　诗人的追寻似乎就要成功了，但终究还是水月镜花。古希腊神话中有一则说坦塔罗斯王因自我吹嘘犯下罪过而遭受惩罚——忍受永远的焦渴和饥饿之苦。他站在大湖中，湖水深及他的下颔，湖岸长着果树，累累果实就悬在他的头顶。可是，当他口渴低头喝水时，湖水便退去；当他腹饥伸手摘果时，树枝便荡开，清泉佳果他始终可望而不可即。目标的切近反而使失败显得更为让人痛苦、惋惜，最让人难以接受的失败是距离成功仅一步之遥的失败。 　　探索人生深刻体验的作品总在后代得到不断的回应。“蒹葭之思”（省称“葭思”）、“蒹葭伊人”成为旧时书信中怀人的套语。曹植《洛神赋》、李商隐的《无题》诗也是《蒹葭》所表现的主题的回应。而当代台湾通俗小说家琼瑶的一部言情小说就叫做《在水一方》，同名电视剧的主题歌就是以此诗为本改写的。\n\n事实的虚化 　　一般说来，抒情诗的创作是导发于对具体事物的感触，因而在它的意境中，总可看到一些实实在在的人事场景。然而（蒙蒙）的作者却似乎故意把其中应有的主要人物事件都虚化了。追寻者是 什么人？他为什么而追寻？我们不知道；被追寻的“伊人”是什么 身份？为什么他那么难以得到？我们也不知道；以至于连他们是 男是女也无从确认。特别是“伊人”，音容体貌均无，一会儿在河的上游，一会儿在河的下游，一忽儿在水中央，一忽儿在水边草地，飘忽不定，来去渺茫，简直令人怀疑他是否真有实体存在。无疑，由于追寻者、特别是被追寻者的虚化，使整个追寻人物、追寻事件、追寻内容都变得虚幻愿陇起来；然而也正是由于这事实的虚化、膜犹，诗的意境才显得那么空灵而富有象征意味。作品所表达的情感：追“伊人”的男子在经过了三次的追寻没有追寻到他的“伊人”由此可见所谓的伊人不过是可望而不可即的梦幻与虚境。但是追梦男子并没有放弃，而是为了梦想而上下追寻,不怕艰难险阻。\n\n意象的空灵 　　实际上，诗中所描述的景象，并非目之所存的现实人事，而是一种心象。这种心象，也不是对曾经阅历过的某件真事的回忆，而是由许多类似事件、类似感受所综合、凝聚、虚化成的一种典型化的心理情境。这种心理情境的最大特点，是不粘不滞、空灵多蕴。“在水一方”，可望难即，就是这种空灵的心理情境的艺术显现。在这里，由于追寻者和被追寻者的虚化，那看来是真景物的河水、道路险阻，乃至逆流、顺流的追寻路线，以及伊人所在的“水中央”等诸种地点，也都成了虚拟的象征性意象。对它们均不可作何时何地、河山何水的深究，否则，伊人既在河的上游又在河的下游就自相矛盾，连两个人何以都不渡过河去也成了问题。《蒹葭》的成功，就在于诗人准确地抓住了人的心象，创造出似花非花、空灵蕴藉的心理情境，才使诗的意境呈现为整体性象征。', poem_tags = '古诗三百首,诗经,初中古诗,高中古诗,怀人,爱情' WHERE poem_title = '蒹葭' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '这年的时光什么时候才能了结，往事知道有多少！昨夜小楼上又吹来了春风，在这皓月当空的夜晚，怎承受得了回忆故国的伤痛。\n精雕细刻的栏杆、玉石砌成的台阶应该还在，只是所怀念的人已衰老。要问我心中有多少哀愁，就像这不尽的滔滔春水滚滚东流。', poem_notes = '此调原为唐教坊曲，初咏项羽宠姬虞美人死后地下开出一朵鲜花，因以为名。又名《一江春水》、《玉壶水》、《巫山十二峰》等。双调，五十六字，上下片各四句，皆为两仄韵转两平韵。\n了：了结，完结。\n砌：台阶。雕栏玉砌：指远在金陵的南唐故宫。\n应犹：一作“依然”。　\n朱颜改：指所怀念的人已衰老。　\n君：作者自称。能：或作“都”、“那”、“还”、“却”。', poem_appreciation = '这首词，是李煜被俘到汴京后所作。开头说，春花秋月的美好时光，何时了结。因为一看到春花秋月，就有无数往事涌上心头，想到在南唐时欣赏春花秋月的美好日子，不堪回首，所以怕看见春花秋月。在东风吹拂的月明之夜，金陵的故国生活不堪回顾了。那里宫殿的雕栏玉砌应该还在，只是人的容貌因愁苦变得憔悴了。倘若要问有多少愁苦，恰恰象一江春水的向东流去，无穷无尽。一江指长江，用一江春水来比愁，跟南唐故国金陵在长江边相结合，充满怀念故国之情。宋代王绖《默记》卷上：“又后主在赐第，因七夕，命故妓作乐，声闻于外。太宗闻之，大怒。又传‘小楼昨夜又东风’及‘一江春水向东流’之句，并坐之，遂被祸云。’王国维《人间词话》：“尼采谓一切文学，余爱以血书者。后主之词，真所谓以血书者也。宋道君皇帝(徽宗)《燕山亭》词亦略似之。然道君不过自道身世之戚，后主则俨然有释迦，基督担荷人类罪恶之意，其大小固不同矣。”李煜被毒死，跟他写这首词有关，这真是用血写的。所谓“有释迦、基督担荷人类罪恶之意”，就是说，李煜这样的词，不光是写他个人的愁苦，还有极大的概括性，概括了所有具亡国之痛的人的痛苦感情：如怕看到春花秋月，怕想到过去的美好生活。再如故国的美好景物已经不堪回顾。故国的景物象雕栏玉砌等还在，但人的容颜因愁苦改变，这里还含有人事的改变，人的主奴关系的改变。再象以一江春水来比愁。整首词正是反映了有亡国之痛的人的感情，担负了所有这些人的感情痛苦。这正说明这首词具有高度的概括性、代表性，这正是这首词的杰出成就。\n\n　　宋朝陈郁《藏一话腴》：“太白(李白)曰：‘请君试问东流水，别意与之谁短长。’(《金陵酒肆留别》)江南李主曰：‘问君还有几多愁，恰似一江春水向东流。’略加融点，已觉精采。至寇莱公(准)则谓‘愁情不断如春水(《夜度娘》)，少游(秦观)云‘落红万点愁如海’(《千秋岁》)，肯出于蓝而胜于蓝矣。”这里对这首词用“一江春水向东流”来比愁作了评论。李白的诗句是写别情的长可以跟东流水比，诗在金陵写的，这个东流水是指长江。李煜的词，是在汴京被拘禁中写的，他看不到长江，长江成为他怀念故国的一部分。因此李白的诗是用眼前景物来作比，李煜的词是用远离自己的长江来作比，在这个比喻里就有怀念故国之情，情思更为深厚。再说，“一江春水向东流”，比东流水”的形象更为鲜明。又“东流水”是比“别意”的“短长”，“一江春水向东流”是比愁的无穷无尽。这是两者的不同处，说明李煜的故国之痛更为深沉，并不是“略加融点”。寇准的词：“日暮汀洲一望时，柔情不断如春水。”这是用春水来比柔情，这个柔情也指别意，跟李白的句意相同，可以说是摹仿李白的词意。“如春水”，也不能与李煜词句相比。秦观的词句：“春去也，落红万点愁如海。”是写“离别宽衣带”的离情别绪，再加上伤春，加上“镜里朱颜改”的憔悴，配上“落红万点”，确是名句。不过李煜的词写的是亡国之痛，比离情别绪更为深沉，也写“朱颜改’，是结合亡国之痛来的，加上“一江春水向东流”的形象鲜明壮阔，从情思到形象，也不是秦观的词句所能比。（田德义）', poem_tags = '宋词三百首,婉约,思念,感叹,哲理' WHERE poem_title = '虞美人·春花秋月何时了' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '八月里秋深，狂风怒号，狂风卷走了我屋顶上好几层茅草。茅草乱飞，渡过浣花溪，散落在对岸江边。飞得高的茅草缠绕在高高的树梢上，飞得低的飘飘洒洒沉落到池塘和洼地里。\n南村的一群儿童欺负我年老没力气，竟忍心这样当面做“贼”抢东西，毫无顾忌地抱着茅草跑进竹林去了。我嘴唇干燥也喝止不住，回来后拄着拐杖，独自叹息。\n一会儿风停了，天空中乌云像墨一样黑，深秋天空阴沉迷蒙渐渐黑下来了。布被盖了多年，又冷又硬，像铁板似的。孩子睡觉姿势不好，把被子蹬破了。一下雨屋顶漏水，屋内没有一点儿干燥的地方，房顶的雨水像麻线一样不停地往下漏。自从安史之乱之后，我睡眠的时间很少，长夜漫漫，屋漏床湿，怎能挨到天亮。\n如何能得到千万间宽敞高大的房子，普遍地庇覆天下间贫寒的读书人，让他们开颜欢笑，房子在风雨中也不为所动，安稳得像是山一样？唉！什么时候眼前出现这样高耸的房屋，到那时即使我的茅屋被秋风所吹破，我自己受冻而死也心甘情愿！', poem_notes = '秋高：秋深。怒号（háo）：大声吼叫。\n三重（chóng）茅：几层茅草。三，泛指多。\n挂罥（juàn）：挂着，挂住。罥，挂。长（cháng）：高。\n塘坳（ào）：低洼积水的地方（即池塘）。塘，一作”堂“。坳，水边低地。\n忍能对面为盗贼：竟忍心这样当面做“贼”。忍能，忍心如此。对面，当面。为，做。\n入竹去：进入竹林。\n呼不得：喝止不住。\n俄顷（qǐng）：不久，一会儿，顷刻之间。\n秋天漠漠向昏黑（古音念hè）：指秋季的天空阴沉迷蒙，渐渐黑了下来。\n布衾（qīn）：布质的被子。衾，被子。\n恶卧：睡相不好。裂：使动用法，使……裂。\n屋漏：根据《辞源》释义，指房子西北角，古人在此开天窗，阳光便从此处照射进来。“床头屋漏”，泛指整个屋子。\n雨脚如麻：形容雨点不间断，像下垂的麻线一样密集。雨脚，雨点。\n丧（sāng）乱：战乱，指安史之乱。\n沾湿：潮湿不干。何由彻：如何才能挨到天亮。彻，彻晓。\n安得：如何能得到。广厦（shà）：宽敞的大屋。\n大庇（bì）：全部遮盖、掩护起来。庇，遮盖，掩护。寒士：“士”原指士人，即文化人，但此处是泛指贫寒的士人们。俱：都。欢颜：喜笑颜开。\n呜呼：书面感叹词，表示叹息，相当于“唉”。\n突兀（wù）：高耸的样子，这里用来形容广厦。见（xiàn）：通“现”，出现。\n庐：茅屋。亦：一作“意”。足：值得。', poem_appreciation = '此诗载于《全唐诗》卷二百一十九。下面是中国古典文学专家、文艺理论家、陕西师范大学文学研究所所长霍松林教授对此诗的赏析要点。\n\n　　此诗写的是自己的数间茅屋，表现的却是忧国忧民的情感。\n\n　　这首诗可分为四节。第一节五句，句句押韵，“号”、“茅”、“郊”、“梢”、“坳”五个开口呼的平声韵脚传来阵阵风声。“八月秋高风怒号，卷我屋上三重茅。”起势迅猛。“风怒号”三字，音响宏大，读之如闻秋风咆哮。一个“怒”字，把秋风拟人化，从而使下一句不仅富有动作性，面且富有浓烈的感情色彩。诗人好容易盖了这座茅屋，刚刚定居下来，秋风却故意同他作对似的，怒吼而来，卷起层层茅草，怎能不使诗人万分焦急？“茅飞渡江洒江郊”的“飞”字紧承上句的“卷”字，“卷”起的茅草没有落在屋旁，却随风“飞”走，“飞”过江去，然后分散地、雨点似地“洒”在“江郊”：“高者挂罥长林梢”，很难弄下来；“下者飘转沉塘坳”，也很难收回。“卷”、“飞”、“渡”、“洒”、“挂罥”、“飘转”，一个接一个的动态不仅组成一幅幅鲜明的图画，而且紧紧地牵动诗人的视线，拨动诗人的心弦。诗人的高明之处在于他并没有抽象地抒情达意，而是寓情意于客观描写之中。读这几句诗，读者分明看见一个衣衫单薄、破旧的干瘦老人拄着拐杖，立在屋外，眼巴巴地望着怒吼的秋风把他屋上的茅草一层又一层地卷了起来，吹过江法，稀里哗啦地洒在江郊的各处；而他对大风破屋的焦灼和怨愤之情，也不能不激起读者心灵上的共鸣。\n\n　　第二节五句。这是前一节的发展，也是对前一节的补充。前节写“洒江郊”的茅草无法收回。还有落在平地上可以收回的，然而却被“南村群童”抱跑了。“欺我老无力”五字宜着眼。如果诗人不是“老无力”，而是年当壮健有气力，自然不会受这样的欺侮。“忍能对面为盗贼”，意谓：竟然忍心在我的眼前做盗贼！这不过是表现了诗人因“老无力”而受欺侮的愤懑心情而已，决不是真的给“群童”加上“盗贼”的罪名，要告到官府里去办罪。所以，“唇焦口燥呼不得”，也就无可奈何了。用诗人《又呈吴郎》一诗里的话说，这正是“不为困穷宁有此”。诗人如果不是十分困穷，就不会对大风刮走茅草那么心急如焚；“群童”如果不是十分困穷，也不会冒着狂风抱那些并不值钱的茅草。这一切，都是结尾的伏线。“安得广厦千万间，大庇天下寒士俱欢颜”的崇高愿望，正是从“四海困穷”的现实基础上产生出来的。\n\n　　“归来倚杖自叹息”总收一、二两节。诗人大约是一听到北风狂叫，就担心盖得不够结实的茅屋发生危险，因而就拄杖出门，直到风吹屋破，茅草无法收回，这才无可奈何地走回家中。“倚杖”，当然又与“老无力”照应。“自叹息”中的“自”字，下得很沉痛！诗人如此不幸的遭遇只有自己叹息，未引起别人的同情和帮助，则世风的浇薄，就意在言外了，因而他“叹息”的内容，也就十分深广。当他自己风吹屋破，无处安身，得不到别人的同情和帮助的时候，分明联想到类似处境的无数穷人。\n\n　　第三节八句，写屋破又遭连夜雨的苦况。“俄顷风定云墨色，秋天漠漠向昏黑”两句，用饱蘸浓墨的大笔渲染出暗淡愁惨的氛围，从而烘托出诗人暗淡愁惨的心境，而密集的雨点即将从漠漠的秋空洒向地面，已在预料之中。“布衾多年冷似铁，娇儿恶卧踏里裂”两句，没有穷困生活体验的作者是写不出来的。值得注意的是这不仅是写布被又旧又破，而是为下文写屋破漏雨蓄势。成都的八月，天气并不“冷”，正由于“床头屋漏无干处，雨脚如麻未断绝”，所以才感到冷。“自经丧乱少睡眠，长夜沾湿何由彻”两句，一纵一收。一纵，从眼前的处境扩展到安史之乱以来的种种痛苦经历，从风雨飘摇中的茅屋扩展到战乱频仍、残破不堪的国家；一收，又回到“长夜沾湿”的现实。忧国忧民，加上“长夜沾湿”，难以入睡。“何由彻”和前面的“未断绝”照应，表现了诗人既盼雨停，又盼天亮的迫切心情。而这种心情，又是屋破漏雨、布衾似铁的艰苦处境激发出来的。于是由个人的艰苦处境联想到其他人的类似处境，水到渠成，自然而然地过渡到全诗的结尾。\n\n　　“安得广厦千万间，大庇天下寒士俱欢颜，风雨不动安如山”，前后用七字句，中间用九字句，句句蝉联而下，而表现阔大境界和愉快情感的词儿如“广厦”、“千万间”、“大庇”、“天下”、“欢颜”、“安如山”等等，又声音宏亮，从而构成了铿锵有力的节奏和奔腾前进的气势，恰切地表现了诗人从“床头屋漏无干处”、“长夜沾湿何由彻”的痛苦生活体验中迸发出来的奔放的激情和火热的希望。这种奔放的激情和火热的希望，咏歌之不足，故嗟叹之，“呜呼！何时眼前突兀见此屋，吾庐独破受冻死亦足！”诗人的博大胸襟和崇高理想，至此表现得淋漓尽致。\n\n　　别林斯基曾说：“任何一个诗人也不能由于他自己和靠描写他自己而显得伟大，不论是描写他本身的痛苦，或者描写他本身的幸福。任何伟大诗人之所以伟大，是因为他们的痛苦和幸福的根子深深地伸进了社会和历史的土壤里，因为他是社会、时代、人类的器官和代表。”杜甫在这首诗里描写了他本身的痛苦，但当读者读完最后一节的时候，就知道他不是孤立地、单纯地描写他本身的痛苦，而是通过描写他本身的痛苦来表现“天下寒士”的痛苦，来表现社会的苦难、时代的苦难。在狂风猛雨无情袭击的秋夜，诗人脑海里翻腾的不仅是“吾庐独破”，而且是“天下寒士”的茅屋俱破。杜甫这种炽热的忧国忧民的情感和迫切要求变革黑暗现实的崇高理想，千百年来一直激动读者的心灵，并发生过积极的作用。', poem_tags = '初中古诗,秋天,写风,励志,忧国忧民' WHERE poem_title = '茅屋为秋风所破歌' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '春天的江潮水势浩荡，与大海连成一片，一轮明月从海上升起，好像与潮水一起涌出来。\n月光照耀着春江，随着波浪闪耀千万里，所有地方的春江都有明亮的月光。\n江水曲曲折折地绕着花草丛生的原野流淌，月光照射着开遍鲜花的树林好像细密的雪珠在闪烁。\n月色如霜，所以霜飞无从觉察。洲上的白沙和月色融合在一起，看不分明。\n江水、天空成一色，没有一点微小灰尘，明亮的天空中只有一轮孤月高悬空中。\n江边上什么人最初看见月亮，江上的月亮哪一年最初照耀着人？\n人生一代代地无穷无尽，只有江上的月亮一年年地总是相像。\n不知江上的月亮等待着什么人，只见长江不断地一直运输着流水。\n游子像一片白云缓缓地离去，只剩下思妇站在离别的青枫浦不胜忧愁。\n哪家的游子今晚坐着小船在漂流？什么地方有人在明月照耀的楼上相思？\n可怜楼上不停移动的月光，应该照耀着离人的梳妆台。\n月光照进思妇的门帘，卷不走，照在她的捣衣砧上，拂不掉。\n这时互相望着月亮可是互相听不到声音，我希望随着月光流去照耀着您。\n鸿雁不停地飞翔，而不能飞出无边的月光；月照江面，鱼龙在水中跳跃，激起阵阵波纹。\n（此二句写月光之清澈无边，也暗含鱼雁不能传信之意。）\n昨天夜里梦见花落闲潭，可惜的是春天过了一半自己还不能回家。\n江水带着春光将要流尽，水潭上的月亮又要西落。\n斜月慢慢下沉，藏在海雾里，碣石与潇湘的离人距离无限遥远。\n不知有几人能趁着月光回家，唯有那西落的月亮摇荡着离情，洒满了江边的树林。', poem_notes = '滟（yàn）滟：波光荡漾的样子。\n芳甸(diàn）：芳草丰茂的原野。甸，郊外之地。\n霰（xiàn）：天空中降落的白色不透明的小冰粒。形容月光下春花晶莹洁白。\n流霜：飞霜，古人以为霜和雪一样，是从空中落下来的，所以叫流霜。在这里比喻月光皎洁，月色朦胧、流荡，所以不觉得有霜霰飞扬。\n汀（tīng）：沙滩。\n纤尘：微细的灰尘。\n月轮：指月亮，因为月圆时像车轮，所以称为月轮。\n穷已：穷尽。\n江月年年只相似：另一种版本为“江月年年望相似”。 \n但见：只见、仅见。\n悠悠：渺茫、深远。\n青枫浦上：青枫浦 地名 今湖南浏阳县境内有青枫浦。这里泛指游子所在的地方。\n浦上：水边。\n扁舟子：飘荡江湖的游子。扁舟，小舟。\n明月楼：月夜下的闺楼。这里指闺中思妇。\n月徘徊：指月光偏照闺楼，徘徊不去，令人不胜其相思之苦。\n离人：此处指思妇。\n妆镜台：梳妆台。\n玉户：形容楼阁华丽，以玉石镶嵌。\n捣衣砧（zhēn ）：捣衣石、捶布石。\n相闻：互通音信。\n逐：追随。\n月华：月光。\n文：同“纹”。\n闲潭：幽静的水潭。\n复西斜：此中“斜”应为押韵读作“xiá”（洛阳方言是当时的标准国语，斜在洛阳方言中就读作xiá）。\n潇湘:湘江与潇水。\n碣(jié)石、潇湘：一南一北，暗指路途遥远，相聚无望。\n无限路：极言离人相距之远。\n乘月：趁着月光。\n摇情：激荡情思，犹言牵情。', poem_appreciation = '这首诗以写月作起，以写月落结，把从天上到地下这样寥廓的空间，从明月、江流、青枫、白云到水纹、落花、海雾等等众多的景物，以及客子、思妇种种细腻的感情，通过环环紧扣、连绵不断的结构方式组织起来。由春江引出海，由海引出明月，又由江流明月\n\n　　引出花林，引出人物，转情换意，前后呼应，若断若续，使诗歌既完美严密，又有反复咏叹的艺术效果。\n\n　　前半部重在写景，是写实，但如“何处春江无月明”、“空里流霜不觉飞”等句子，同时也体现了人物的想象和感觉。后半部重在抒情，这情是在景的基础上产生的，如长江流水、青枫白云、帘卷不去、拂砧还来等句，景中亦自有情，结尾一句，更是情景交融的名句。全篇有情有景，亦情亦景，情景交织成有机整体。\n\n　　诗歌写了许多色彩鲜明的形象，如皎月、白沙、白云、青枫等等，这些景物共同造成了柔和静谧的诗境，这种意境与所抒发的绵邈深挚的情感，十分和谐统一。\n\n　　诗歌每四句一换韵，平仄相间，韵律婉转悠扬。为了与缠绵的感情相适应，语言采用了一些顶针连环句式，如“春江潮水连海平，海上……”“江月何年初照人。人生……”“何处相思明月楼，可怜楼上……”“江潭落月复西斜，斜月……”。一唱三叹，情味无穷。对偶句的使用如“谁家今夜扁舟子？何处相思明月楼？”“鸿雁长飞光不度，鱼龙潜跃水成文”等等。句中平仄的讲求如“滟滟随波千万里，何处春江无月明？江流婉转绕芳甸，月照花林皆似霰”，平仄变换与律诗相同，使诗歌语言既抑扬顿挫，又清新流畅。\n\n　　“暮江平不动，春花满正开。流波将月去，潮水带星来。”杨广此首借题生义，一扫艳媚。黄昏远眺长江岸，暮霭沉沉，江水浩淼。“平不动”是水波不兴。江面平坦宁静，江边春花如火，开得满满当当。他写春夜潮生，江水滔滔。“将月去”，“带星来”将水波激荡，月星交辉的情景写得极宏大，于写景的壮阔中写出了时间的流逝。寥寥四句诗，将春江花月夜收纳其间，绘出一幅江月胜景图。“流波将月去，潮水带星来”，缓缓读来，如欣赏清秋月夜之画，风致婉然。此句好在平实，一个“将”字，一个“带”字，都是比较虚的动词，不会破了月明星稀的安稳美感。\n\n　　总而言之，诗人凭借对春江花月夜的描绘，尽情赞叹大自然的绮丽景色，讴歌人间纯洁爱情把游子对思妇的同情扩大开来，与对人生哲理的追求、对宇宙奥秘的探索结合而来，从而汇成一种情、景、理水乳交融的优美而邈远的意境。', poem_tags = '春天,写花,月亮,思念,乐府' WHERE poem_title = '春江花月夜' AND poem_author = '张若虚';
UPDATE edu_poem SET poem_translation = '在三峡七百里之间，两岸都是连绵的高山，完全没有中断的地方；重重叠叠的悬崖 峭壁，遮挡了天空和太阳。若不是在正午半夜的时候，连太阳和月亮都看不见。\n\n　　等到夏天水涨，江水漫上小山丘的时候，下行或上行的船只都被阻挡了，不能通航。有时候皇帝的命令要紧急传达，这时只要早晨从白帝城出发，傍晚就到了江陵，这中间有一千二百里，即使骑上飞奔的马，驾着疾风，也不如它快。\n\n　　等到春天和冬天的时候，就可以看见白色的急流,回旋的清波。碧绿的潭水倒映着各种景物的影子。极高的山峰上生长着许多奇形怪状的柏树，山峰之间有悬泉瀑布飞流冲荡。水清，树荣，山高，草盛，确实趣味无穷。\n\n　　在秋天，每到初晴的时候或下霜的早晨，树林和山涧显出一片清凉和寂静，经常有高处的猿猴拉长声音鸣叫，声音持续不断，非常凄凉怪异，空荡的山谷里传来猿叫的回声，悲哀婉转，很久才消失。所以三峡中渔民的歌谣唱道：“巴东三峡巫峡长，猿鸣三声泪沾裳。”', poem_notes = '自：在，从\n三峡：指长江上游重庆、湖北两个省级行政单位间的瞿塘峡、巫峡和西陵峡。三峡全长实际只有四百多里。\n略无：毫无，完全没有。阙：通“缺”，缺口，空隙。\n嶂(zhàng)：直立如屏障一样的山峰。\n自非：如果不是。自：如果。非：不是\n亭午：正午。夜分：半夜。\n曦(xī)：日光，这里指太阳。\n襄（xiāng）：上，这里指漫上。 陵：大的土山，这里泛指山陵。\n沿：顺流而下（的船）。溯：逆流而上（的船）。\n或：有的时候。王命：皇帝的圣旨。宣：宣布，传达。\n朝发白帝：早上从白帝城出发。白帝：城名，在重庆奉节县东。朝：早晨\n江陵：今湖北省荆州市。\n虽：即使。 奔：奔驰的快马。御：驾着，驾驶\n不以：不如。此句谓和行船比起来，即使是乘奔御风也不被认为是（比船）快，或为“以”当是“似”之误。(见清赵一清《水经注刊误》) 疾：快。\n素湍：白色的急流。素：白色的。绿潭：碧绿的潭水。\n回清倒影：回旋的清波，倒映出（山石林木）的倒影。\n绝巘(yǎn):极高的山峰。绝：极。巘：高峰\n悬泉：悬挂着的泉水瀑布。飞漱：急流冲荡。漱：冲荡。\n清荣峻茂：水清，树荣（茂盛），山高，草盛。\n良：实在，的确，确实。\n晴初：（雨后或雪后）天刚刚放晴的时候。霜旦：下霜的早晨。\n属引：连续不断。属(zhǔ)：动词。连接。引：延长。凄异：凄凉怪异。\n哀转久绝：悲哀婉转，猿鸣声很久才消失。绝：消失，停止。转：通“啭”鸣叫。\n巴东：汉郡名，在今重庆东部云阳，奉节，巫山一带。\n三声：几声。这里不是确数。\n沾：打湿。\n 裳（cháng）：衣服。', poem_appreciation = '本文是《水经注》中《江水》中的“（江水）又东过巫县南，盐水从县东南流注之”的一条注。记叙了长江三峡雄伟壮丽的奇景，能激发人们热爱祖国大好河山的感情。\n\n　　“自三峡七百里中，两岸连山，略无阙处。重岩叠嶂，隐天蔽日，自非亭午夜分，不见曦月。”总写三峡的特点：山高岭连，中间狭窄。“自三峡七百里中”，交代峡之长，接着指出两岸山的特点在于“连”。“略无阙处”，毫无残缺的地方，进一步写“连”。下面接着写山的“高”。山峰相重，群山复叠，山上垒山，说明山高。山隐，遮蔽住太阳匿于天空，从另一个角度写山的高。“重”和“叠”，就山本身的状态写其高，是俯瞰而得；“隐”和“蔽”，以天和日来衬其高，乃仰视所见。下面两句，则以特定条件下的情景形象地综合表现以上特点。只有正午和半夜的时候才能见到太阳和月亮。如果不是“两岸”连山，哪怕只有一岸连山，也不会形成这种状况；如果连山有缺，其他时间于缺处也能见到日月；如果连山不高，也不必待到这时才见日月；如果三峡不窄，其他时候也可见到日月。正午见日，夜半见月，由特定条件充分显示了三峡特点。\n\n　　“至于夏水襄陵，沿溯阻绝。或王命急宣，有时朝发白帝，暮到江陵，其间千二百里，虽乘奔御风，不以疾也。”写夏季三峡情景：水涨流速，交通阻断。夏季水涨，淹了山陵，上行和下航的船只都被阻绝了。这里所写的是水势大水流速情况下的通例。下举一特例，以进一步证明水速。只有王朝的紧急命令要向各地传达时，才会有航船。这一方面照应了平常情况下是“沿溯阻绝”的，同时借此可写出船行之快。朝发白帝，暮到江陵，补笔交代“其间千二百里”，则时速约为百里，加上更用奔马和疾风作比较，给人的感受也就更为形象而深刻了。\n\n　　本节承上段而来。上段写三峡山的特点，为本节写水设置了条件。山高，则水的落差大，山高自然流急。山连，则水不得他泄，必然尽在漕中。峡窄，则断面小，单位面积里的水的流量也就大。水“涨”的因素和峡的特点及条件，构成了水流的湍急。作者是为江水作注，重点是写水，而水以夏季为盛，故先写“夏水”。为写水势，先写山势，这既能揭示水速的原因，又能使急流和峻岭相互映衬，能形成一幅险峻壮奇的图画。\n\n　　“春冬之时，则素湍绿潭，回清倒影，绝巘多生怪柏，悬泉瀑布，飞漱其间，清荣峻茂，良多趣味。”写春冬时三峡情景：水退潭清，风景秀丽。以“春冬之时”领起，很自然地转换了描写对象，时易则景异，镜头中摇出了另外一种景象。白色的急流回映着清光，绿色的水潭倒映着景物的影子。这里先写俯视江中所见。“湍”是动态，“潭”为静境。以“素”饰“湍”，水如白练，明净轻快，上有清光回照，白中间青，水光变幻。深水为潭，以“绿”饰“潭”，益见深沉宁静。水中有影，则水平如镜，倒影入潭，更觉风光秀丽。急流上波光粼粼，深潭里景物重重，动静相杂，色彩各异，相映成趣，堪称秀丽隽逸。下文即写仰视所见，由峡底写到山上。以“绝”状山，以“怪”写柏，道出了当地的自然特征。山岩陡削，高耸入云，故为“绝”。山上的柏树，托足于岩石之间，正午之时方见日光，它要曲体向阳，加之峡窄风大，自然枝干扭曲，何况年代久远，当然要变成“怪”形。在这人迹罕至、鸟兽少见的境地，“怪柏”显示着旺盛的生命力和坚强的意志，给山水之间投进了一股生命的活流，使人顿觉生意盎然。作者写此，还只是给“悬泉瀑布”勾勒出一个背景。山静、泉飞、柏怪、水奇，静中有动，声色纷沓，山水相配，构成了一幅挺拔超脱的图画，这和“素湍绿潭，回清倒影”又大为异趣。最后作者总括说：水清、木荣、山峻、草茂，实在富有趣味。以极为精练的四字，状写了四种景物，且各具特色，由景境导出了作者的心境。\n\n　　作者将冬春二季放在一道写，要兼及两季的特点。冬季水竭，才会出现“素湍绿潭”，春天物鲜，始有草木“荣茂”。本节所写与上节所述，意趣迥异。夏水急猛，春水潺；夏水多险，春水富趣。作者认为三峡风光“良多趣味”，和封建士大夫对三峡“悉以临惧相戒”的思想感情大相径庭。\n\n　　“每至晴初霜旦，林寒涧肃，常有高猿长啸，属引凄异，空谷传响，哀转久绝。故渔者歌曰：‘巴东三峡巫峡长，猿鸣三声泪沾裳!’”写秋天三峡情景：水枯气寒，猿鸣凄凉。以“霜旦”的“霜”暗指秋季，开笔多变。接着以实景补足前意，林涧之间，清冷肃穆。这时已无江水喧腾，也不见草木争荣，而是充满了凄清肃杀的气氛。写秋峡以代表性事物猿来表现，写猿又分两层，一是直接叙述，一是引渔歌为证。写猿又围绕着“山”和“哀”两个重点，从而显示秋峡的特色。以“高”形容猿，指明是高山上的猿，以“长”形容啸，送声长远，暗示是在长峡之中。“空谷传响”，直言在山中。“久绝”，回应“两岸连山，略无阙处”。写渔歌也是一言“峡长”，一言声哀。从猿鸣之中，使人进一步体会到山高、岭连、峡窄、水长，同时山猿哀鸣，渲染了秋天的萧瑟气氛。也让人从这句渔歌中体会到了，渔者们的辛苦和生活的艰苦。\n\n　　本文虽属节选，但全文结构严谨，布局巧妙，浑然一体，尤其作者在描山摹水上更见功力。由于作者曾“践跻此境”，有具体感受，所以能掌握三峡的特点和不同季节的风貌。首先，作者采取先大而小，先总后分的办法，按季节分层次，写得起讫分明，各具特色。其次，善于选取富有特征性的事物，寥寥几笔，使境界全出，叫读者恍如身临其境。如以“朝发白帝，暮到江陵”表现水流湍急，以“素湍绿潭，回清倒影”形容江水澄澈，风光妩媚，以“空谷传响，哀转久绝”渲染猿鸣幽凄、山谷空旷，都言简意赅，情景交融。再次，各个部分，各有侧重，互相映衬，互相补充，从不同角度写出了三峡特色，而下面的三个部分，又都围绕着首段关于山峡总的特点来写。最后，作者运笔富于变化，有正面落笔，有侧面烘托，有粗线勾勒，有工笔细描，有明言直写，有隐喻暗示，有全景鸟瞰，有特写镜头，有仰观远景，有俯察近物，有绘形写貌，有摹声录音，有自己立言，有由人代语，虽只几百字的短文，却概括千里，包容四季，收纳山水草木，罗入清猿怪柏，真可谓片言敌万语，尺素罗千里。', poem_tags = '初中文言文,写水,长江,写景,热爱' WHERE poem_title = '三峡' AND poem_author = '郦道元';
UPDATE edu_poem SET poem_translation = '回想我早年由科举入仕历尽辛苦，如今战火消歇已熬过了四个年头。\n国家危在旦夕恰如狂风中的柳絮，自己一生的坎坷如雨中浮萍漂泊无根时起时沉。\n惶恐滩的惨败让我至今依然惶恐，零丁洋身陷元虏可叹我孤苦零丁。\n人生自古以来有谁能够长生不死？我要留一片爱国的丹心映照史册。', poem_notes = '零丁洋：零丁洋即”伶丁洋“。现在广东省珠江口外。1278年底，文天祥率军在广东五坡岭与元军激战，兵败被俘，囚禁船上曾经过零丁洋。\n遭逢：遭遇。起一经，因为精通一种经书，通过科举考试而被朝廷起用作官。文天祥二十岁考中状元。\n干戈：指抗元战争。寥（liáo）落：荒凉冷落。一作“落落”。四周星：四周年。文天祥从1275年起兵抗元，到1278年被俘，一共四年。\n絮：柳絮。\n萍：浮萍。\n惶恐滩：在今江西省万安县，是赣江中的险滩。1277年，文天祥在江西被元军打败，所率军队死伤惨重，妻子儿女也被元军俘虏。他经惶恐滩撤到福建。\n零丁：孤苦无依的样子。\n丹心：红心，比喻忠心。\n汗青：同汗竹，史册。古代用简写字，先用火烤干其中的水分，干后易写而且不受虫蛀，也称汗青。', poem_appreciation = '首联“辛苦遭逢起一经，干戈寥落四周星。”“起一经”当指天祥二十岁中进士说的，四周星即四年。天祥于德祐元年（1275），起兵勤王，至祥兴元年（1278）被俘，恰为四个年头。此自叙生平，思今忆昔。从时间说，拈出“入世”和“勤王”，一关个人出处，一关国家危亡，两件大事，一片忠心。唐宋时期，一个人要想替国家做出一番事业，必须入仕，要入仕，作为知识分子必须通过科举考选，考选就得读经，文天祥遇难时，衣带中留有个自赞文说：“读圣贤书，所学何事，而今而后，庶几无愧”，就是把这两件事拴在一起的。圣人著作就叫经，经是治国安邦的。这两句诗，讲两件事，似可分开独立，而实质上是连结在一起的。干戈寥落一作干戈落落，意思相近。《后汉书·耿弁传》“落落难合”注云：“落落犹疏阔也。”疏阔即稀疏、疏散，与寥落义同。《宋史》说当时谢后下勤王诏，响应的人很少，这里所讲情况正合史实。\n\n　　颔联接着说“山河破碎风飘絮，身世浮沉雨打萍。”还是从国家和个人两方面展开和深入加以铺叙。宋朝自临安弃守，恭帝赵昰被俘，事实上已经灭亡。剩下的只是各地方军民自动组织起来抵抗。文天祥、张世杰等人拥立的端宗赵昱逃难中惊悸而死，陆秀夫复立八岁的赵昺建行宫于崖山，各处流亡，用山河破碎形容这种局面，加上说“风飘絮”，形象生动，而心情沉郁。这时文天祥自己老母被俘，妻妾被囚，大儿丧亡，真像水上浮萍，无依无附，景象凄凉。\n\n　　颈联继续追述今昔不同的处境和心情，昔日惶恐滩边，忧国忧民，诚惶诚恐；今天零丁洋上孤独一人，自叹伶仃。皇恐滩是赣江十八滩之一，水流湍急，令人惊恐，也叫惶恐滩。原名黄公滩，因读音相近，讹为皇恐滩。滩在今江西省万安县境内赣江中，文天祥起兵勤王时曾路过这里。零丁洋在今广东省珠江15里外的崖山外面，现名伶丁洋，文天祥兵败被俘，押送过此。前者为追忆，后者乃当前实况，两者均亲身经历。一身为战将，一为阶下囚。故作战将，面对强大敌人，恐不能完成守土复国的使命，惶恐不安。而作为阶下囚，孤苦伶仃，只有一人。这里“风飘絮”、“雨打萍”、“惶恐滩”、“零丁洋”都是眼前景物，信手拈来，对仗工整，出语自然，而形象生动，流露出一腔悲愤和盈握血泪。\n\n　　尾联笔势一转，忽然宕进，由现在渡到将来，拨开现实，露出理想，如此结语，有如撞钟，清音绕梁。全诗格调，顿然一变，由沉郁转为开拓、豪放、洒脱。“人生自古谁无死，留取丹心照汗青。”让赤诚的心如一团火，照耀史册，照亮世界，照暖人生。用一照字，显示光芒四射，英气逼人。据说张弘范看到文天祥这首诗，尤其是尾联这两句，连称：“好人，好诗！”诚然文天祥把做诗与做人，诗格与人格，浑然一体。千秋绝唱，情调高昂，激励和感召古往今来无数志士仁人为正义事业英勇献身。', poem_tags = '古诗三百首,初中古诗,爱国,励志,忧国忧民,早教古诗100首' WHERE poem_title = '过零丁洋' AND poem_author = '文天祥';
UPDATE edu_poem SET poem_translation = '北风席卷大地把白草吹折，胡地天气八月就纷扬落雪。\n忽然间宛如一夜春风吹来，好像是千树万树梨花盛开。\n雪花散入珠帘打湿了罗幕，狐裘穿不暖锦被也嫌单薄。\n将军都护手冻得拉不开弓，铁甲冰冷得让人难以穿着。\n沙漠结冰百丈纵横有裂纹，万里长空凝聚着惨淡愁云。\n主帅帐中摆酒为归客饯行，胡琴琵琶羌笛合奏来助兴。\n傍晚辕门前大雪落个不停，红旗冻僵了风也无法牵引。\n轮台东门外欢送你回京去，你去时大雪盖满了天山路。\n山路迂回曲折已看不见你，雪上只留下一行马蹄印迹。', poem_notes = '武判官：名不详。判官，官职名。唐代节度使等朝廷派出的持节大使，可委任幕僚协助判处公事，称判官，是节度使、观察使一类的僚属。\n白草：西域牧草名，秋天变白色。\n胡天：指塞北的天空。胡，古代汉民族对北方各民族的通称。\n梨花：春天开放，花作白色。这里比喻雪花积在树枝上，像梨花开了一样。\n珠帘：用珍珠串成或饰有珍珠的帘子。形容帘子的华美。罗幕：用丝织品做成的帐幕。形容帐幕的华美。这句说雪花飞进珠帘，沾湿罗幕。“珠帘”“罗幕”都属于美化的说法。\n狐裘（qiú）：狐皮袍子。锦衾（qīn）：锦缎做的被子。锦衾薄（bó）：丝绸的被子（因为寒冷）都显得单薄了。形容天气很冷。\n角弓：两端用兽角装饰的硬弓，一作“雕弓”。不得控：（天太冷而冻得）拉不开（弓）。控：拉开。\n都（dū）护：镇守边镇的长官此为泛指，与上文的“将军”是互文。铁衣：铠甲。难着（zhuó）：一作“犹着”。着：亦写作“著”。\n瀚（hàn）海：沙漠。阑干：纵横交错的样子。百丈：一作“百尺”，一作“千尺”。\n惨淡：昏暗无光。\n中军：称主将或指挥部。古时分兵为中、左、右三军，中军为主帅的营帐。饮归客：宴饮归京的人，指武判官。饮，动词，宴饮。\n胡琴琵琶与羌（qiāng）笛：胡琴等都是当时西域地区兄弟民族的乐器。羌笛：羌族的管乐器。\n辕门：军营的门。古代军队扎营，用车环围，出入处以两车车辕相向竖立，状如门。这里指帅衙署的外门。\n风掣（chè）：红旗因雪而冻结，风都吹不动了。掣：拉，扯。冻不翻：旗被风往一个方向吹，给人以冻住之感。\n轮台：唐轮台在今新疆维吾尔自治区米泉县境内，与汉轮台不是同一地方。\n满：铺满。形容词活用为动词。\n山回路转：山势回环，道路盘旋曲折。', poem_appreciation = '此诗是一首咏雪送人之作。杜甫在《渼陂行》诗中说：“岑参兄弟皆好奇”。此诗就处处都体现出一个“奇”字。\n\n　　此诗开篇就奇突。未及白雪而先传风声，所谓“笔所未到气已吞”——全是飞雪之精神。大雪必随刮风而来，“北风卷地”四字，妙在由风而见雪。“白草”，据《汉书·西域传》颜师古注，乃西北一种草名，王先谦补注谓其性至坚韧。然经霜草脆，故能断折（如为春草则随风俯仰不可“折”）。“白草折”又显出风来势猛。八月秋高，而北地已满天飞雪。“胡天八月即飞雪”，一个“即”字，维妙维肖地写出由南方来的人少见多怪的惊奇口吻。\n\n　　塞外苦寒，北风一吹，大雪纷飞。诗人以“春风”使梨花盛开，比拟“北风”使雪花飞舞，极为新颖贴切。“忽如”二字下得甚妙，不仅写出了“胡天”变幻无常，大雪来得急骤，而且，再次传出了诗人惊喜好奇的神情。“千树万树梨花开”的壮美意境，颇富有浪漫色彩。南方人见过梨花盛开的景象，那雪白的花不仅是一朵一朵，而且是一团一团，花团锦簇，压枝欲低，与雪压冬林的景象极为神似。春风吹来梨花开，竟至“千树万树”，重叠的修辞表现出景象的繁荣壮丽。“春雪满空来，触处似花开”（东方虬《春雪》），也以花喻雪，匠心略同，但无论豪情与奇趣都得让此诗三分。诗人将春景比冬景，尤其将南方春景比北国冬景，几使人忘记奇寒而内心感到喜悦与温暖，着想、造境俱称奇绝。要品评这咏雪之千古名句，恰有一个成语——“妙手回春”。\n\n　　以写野外雪景作了漂亮的开端后，诗笔从帐外写到帐内。那片片飞“花”飘飘而来，穿帘入户，沾在幕帏上慢慢消融……“散入珠帘湿罗幕”一语承上启下，转换自然从容，体物入微。“白雪”的影响侵入室内，倘是南方，穿“狐裘”必发炸热，而此地“狐裘不暖”，连裹着软和的“锦衾”也只觉单薄。“一身能擘五雕弧”的边将，居然拉不开角弓；平素是“将军金甲夜不脱”，而此时是“都护铁衣冷难着”。二句兼都护（镇边都护府的长官）将军言之，互文见义。这四句，有人认为表现着边地将士苦寒生活，仅着眼这几句，谁说不是？但从“白雪歌”歌咏的主题而言，这主要是通过人和人的感受，通过种种在南来人视为反常的情事写天气的奇寒，写白雪的威力。这真是一支白雪的赞歌呢。通过人的感受写严寒，手法又具体真切，不流于抽象概念。诗人对奇寒津津乐道，使人不觉其苦，反觉冷得新鲜，寒得有趣。这又是诗人“好奇”个性的表现。\n\n　　场景再次移到帐外，而且延伸向广远的沙漠和辽阔的天空：浩瀚的沙海，冰雪遍地；雪压冬云，浓重稠密，虽暂停，但看来天气不会在短期内好转。“瀚海阑干百丈冰，愁云惨淡万里凝”，二句以夸张笔墨，气势磅礴地勾出瑰奇壮丽的沙塞雪景，又为“武判官归京”安排了一个典型的送别环境。如此酷寒恶劣的天气，长途跋涉将是艰辛的呢。“愁”字隐约对离别分手作了暗示。\n\n　　于是写到中军帐（主帅营帐）置酒饮别的情景。如果说以上主要是咏雪而渐有寄情，以下则正写送别而以白雪为背景。“胡琴琵琶与羌笛”句，并列三种乐器而不写音乐本身，颇似笨拙，但仍能间接传达一种急管繁弦的场面，以及“总是关山旧别情”的意味。这些边地之器乐，对于送者能触动乡愁，于送别之外别有一番滋味。写饯宴给读者印象深刻而落墨不多，这也表明作者根据题意在用笔上分了主次详略。\n\n　　送客送出军门，时已黄昏，又见大雪纷飞。这时看见一个奇异景象：尽管风刮得挺猛，辕门上的红旗却一动也不动──它已被冰雪冻结了。这一生动而反常的细节再次传神地写出天气奇寒。而那白雪为背景上的鲜红一点，那冷色基调的画面上的一星暖色，反衬得整个境界更洁白，更寒冷；那雪花乱飞的空中不动的物象，又衬得整个画面更加生动。这是诗中又一处精彩的奇笔。\n\n　　送客送到路口，这是轮台东门。尽管依依不舍，毕竟是分手的时候了。诗人心想：大雪封山，路可怎么走啊！路转峰回，行人消失在雪地里，诗人还在深情地目送。这最后的几句是极其动人的，成为此诗出色的结尾，与开篇悉称。结束处留下了很大的思索空间：看着“雪上空留”的马蹄迹，诗人在想些什么？是对行者难舍而生留恋，是为其“长路关山何时尽”而发愁，还是为自己归期未卜而惆怅？这里有悠悠不尽之情，形成了一个艺术空白，其意境与汉代古诗“步出城东门，遥望江南路。前日风雪中，故人从此去”名句差近，但用在诗的结处，效果更见佳妙。\n\n　　充满奇情妙思，是此诗主要的特色（这很能反映诗人创作个性）。作者用敏锐的观察力和感受力捕捉边塞奇观，笔力矫健，有大笔挥酒（如“瀚海”二句），有细节勾勒（如“风掣红旗冻不翻”），有真实生动的摹写，也有浪漫奇妙的想象（如“忽如”二句），再现了边地瑰丽的自然风光，充满浓郁的边地生活气息。全诗融合着强烈的主观感受，在歌咏自然风光的同时还表现了雪中送人的真挚情谊。诗情内涵丰富，意境鲜明独特，具有极强的艺术感染力。诗的语言明朗优美，又利用换韵与场景画面交替的配合，形成跌宕生姿的节奏旋律。诗中或二句一转韵，或四句一转韵，转韵时场景必更新：开篇入声起音陡促，与风狂雪猛画面配合；继而音韵轻柔舒缓，随即出现“春暖花开”的美景；以下又转沉滞紧涩，出现军中苦寒情事；……末四句渐入徐缓，画面上出现渐行渐远的马蹄印迹，使人低回不已。全诗音情配合极佳，当得“有声画”的称誉。', poem_tags = '唐诗三百首,初中古诗,冬天,送别,友情,咏物,写雪,古诗里的十二个月' WHERE poem_title = '白雪歌送武判官归京' AND poem_author = '岑参';
UPDATE edu_poem SET poem_translation = '像东风吹散千树繁花一样，又吹得烟火纷纷，乱落如雨。豪华的马车满路芳香。悠扬的凤箫声四处回荡，玉壶般的明月渐渐西斜，一夜鱼龙灯飞舞笑语喧哗。\n美人头上都戴着亮丽的饰物，笑语盈盈地随人群走过，身上香气飘洒。我在人群中寻找她千百回，猛然一回头，不经意间却在灯火零落之处发现了她。', poem_notes = '青玉案：词牌名。“案”读wan，第三声，与“碗”同音。\n元夕：夏历正月十五日为上元节，元宵节，此夜称元夕或元夜。\n“东风”句：形容元宵夜花灯繁多。花千树，花灯之多如千树开花。\n星如雨：指焰火纷纷，乱落如雨。星，指焰火。形容满天的烟花。\n宝马雕车：豪华的马车。\n“凤箫”句：指笙、箫等乐器演奏。凤箫，箫的美称。\n玉壶：比喻明月。亦可解释为指灯。\n鱼龙舞：指舞动鱼形、龙形的彩灯，如鱼龙闹海一样。\n“蛾儿”句：写元夕的妇女装饰。蛾儿、雪柳、黄金缕，皆古代妇女元宵节时头上佩戴的各种装饰品。这里指盛装的妇女。\n盈盈：声音轻盈悦耳，亦指仪态娇美的样子。暗香：本指花香，此指女性们身上散发出来的香气。\n他：泛指第三人称，古时就包括“她”。千百度：千百遍。\n蓦然：突然，猛然。\n阑珊：零落稀疏的样子。', poem_appreciation = '阴历正月十五为上元节，这日晚上称元夕，亦称元宵，元夜。我国古代有元夕观灯的风俗。玉壶：指月亮。鱼龙舞：指舞鱼灯、龙灯之类。这是一首别有寄托的词作。词人假借对一位厌恶热闹、自甘寂寞的女子的寻求，含蓄地表达了自己的高洁志向和情怀．梁启超《艺蘅馆胡词选》云：“自怜幽独，伤心人别有怀抱。”其体会是可信的。词的上片，极写元夕灯火辉煌、歌舞繁盛的热闹景象。“东风夜放花千树，更吹落、星如雨，”前一句写灯，后一句写焰火。上元之夜，满城灯火，就象一夜春风吹开了千树万树的繁花，满天的焰火明灭，又象是春风把满天星斗吹落。真是一片灯的海洋，焰火的世界，令人眼花缭乱。\n\n　　“花千树”、“星如雨”，不仅写出了灯火之盛、之美，而且也给人热闹非凡的感觉，渲染出了节日的热烈气氛。“宝马雕车香满路”，是写游人之盛。但这里主要还是为了渲染气氛，所以，作者并没有对游人作具体描绘，只是从整体印象上概括地勾勒了一笔。然而，游人如织、仕女如云的景象却已跃然纸上；最后三句描绘歌舞之乐。节日的夜晚，一片狂欢景象，到处是笙箫齐鸣，到处是彩灯飞舞，人们在忘情地欢乐着，\n\n　　“一夜鱼龙舞”，写出了人们彻夜狂欢的情景。 下片写寻觅意中人的过程。“蛾儿雪柳黄金缕，笑语盈盈暗香去。“观灯看花”的妇女，头上戴着“蛾儿”、“雪柳”、“黄金缕”等装饰品，一个个打扮得花枝招展，整整齐齐，漂漂亮亮。她们一路笑语，带着幽香，从词人眼前走过，这里作者具体地描写了观灯的游人，也是对上片“宝马雕车香满路”描写的一个补充，同时，一个“去”字也暗传出对意中人的寻觅。在熙熙攘攘的游人中，他寻找着，辩认着，一个个少女美妇从他眼前过去了，可是，却没有一个人是他要寻找的。那么他所要寻找的意中人在哪里呢?\n\n　　“众里寻他千百度，蓦然回首，那人却在、灯火阑珊处。”经过千百次的寻觅，终于在灯火冷落的地方发现了她。人们都在尽情的狂欢，陶醉在热闹场中，可是她却在热闹圈外；独自站在“灯火阑珊处”，充分显示了“那人”的与众不同和孤高。“众里寻她千百度”极写寻觅之苦，而“蓦然”二字则写出了发现意中人后的惊喜之情。这里作者以含蓄的语言，表现了人物内心的活动。\n\n　　这首词先用大量笔墨渲染了元夕的热闹景象，最后突然把笔锋一转，以冷清作结，形成了鲜明强烈的对比。这种对比，不仅造成了境界上的强烈反差，深化了全词的意境，而且很好地起到了加强突出人物形象的作用。\n\n　　灯火写得愈热闹，则愈显“那人”的孤高，人写得愈忘情，愈见“那人”的不同流俗。 全词就是通过这种强烈的对比手法，反衬出了一个自甘寂寞、独立不移、性格孤介的女性形象。作者写这样—个不肯随波逐流、自甘淡泊的女性形象，是有所寄托的。辛弃疾力主抗战，屡受排挤，但他矢志不移，宁可过寂寞的闲居生活，也不肯与投降派同流合污，这首词是他这种思想的艺术反映。“众里寻他千百度，蓦然回首，那人却在，灯火阑珊处”，历来也为人传诵。\n\n　　清王国维在《人间词话》中说，这三句也是“古今之成大事业、大学问者”，必然经过三境界的第三境，并以此作比喻，对做学问、做人、成事业者，在经历了第一境界和第二境界之后，才能有所发现，自己所追寻的东西往往会在不经意的时候，没想到的地方出现。', poem_tags = '宋词三百首,婉约,元宵节,写人' WHERE poem_title = '青玉案·元夕' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '醉梦里挑亮油灯观看宝剑，梦中回到了当年的各个营垒，接连响起号角声。把烤牛肉分给部下，乐队演奏北疆歌曲。这是秋天在战场上阅兵。\n战马像的卢马一样跑得飞快，弓箭像惊雷一样，震耳离弦。(我)一心想替君主完成收复国家失地的大业，取得世代相传的美名。可怜已成了白发人！', poem_notes = '醉里：醉酒之中。\n挑灯：拨动灯火，点灯。 看剑：查看宝剑。准备上战场杀敌的形象。说明作者即使在醉酒之际也不忘抗敌。\n八百里：指牛。\n麾：军旗。麾下：指部下。\n炙：烤肉。\n五十弦：本指瑟，泛指乐器。 翻：演奏。 塞外声：以边塞作为题材的雄壮悲凉的军歌。\n沙场：战场\n点兵：检阅军队。\n马作的卢（dì lú）飞快：战马像的卢马那样跑得飞快；作，像…一样；的卢，马名。一种额部有白色斑点性烈的快马。相传刘备曾乘的卢马从襄阳城西的檀溪水中一跃三丈，脱离险境。\n作：像，如。\n霹雳(pī lì)：特别响的雷声，比喻拉弓时弓弦响如惊雷。\n了(liǎo)却：了结，完成。\n天下事：此指恢复中原之事。.\n赢得：博得。\n身后：死后。\n可怜：可惜', poem_appreciation = '此词以两个二、二、二的对句开头，通过具体、生动的描述，表现了多层情意。第一句，只六个字，却用三个连续的、富有特征性的动作，塑造了一个壮士的形象，让读者从那些动作中去体会人物的内心活动，去想象人物所处的环境，意味无穷。为什么要吃酒，而且吃“醉”？既“醉”之后，为什么不去睡觉，而要“挑灯”？“挑”亮了“灯”，为什么不干别的，偏偏抽出宝剑，映着灯光看了又看？……这一连串问题，只要细读全词，就可能作出应有的回答，因而不必说明。“此时无声胜有声”。用什么样的“说明”也难以比这无言的动作更有力地展现人物的内心世界。\n\n　　“挑灯”的动作又点出了夜景。那位壮士在夜深人静、万籁俱寂之时，思潮汹涌，无法入睡，只好独自吃酒。吃“醉”之后，仍然不能平静，便继之以“挑灯”，又继之以“看剑”。翻来覆去，总算睡着了。而刚一入睡，方才所想的一切，又幻为梦境。“梦”了些什么，也没有明说，却迅速地换上新的镜头：“梦回吹角连营。”壮士好梦初醒，天已破晓，一个军营连着一个军营，响起一片号角声。这号角声，富有催人勇往无前的力量。而那位壮士，也正好是统领这些军营的将军。于是，他一跃而起，全副披挂，要把他“醉里”、“梦里”所想的一切统统变为现实。\n\n　　三、四两句，可以不讲对仗，词人也用了偶句。偶句太多，容易显得呆板；可是在这里恰恰相反。两个对仗极工、而又极其雄健的句子，突出地表现了雄壮的军容，表现了将军及士兵们高昂的战斗情绪。“八百里分麾下炙，五十弦翻塞外声”：兵士们欢欣鼓舞，饱餐将军分给的烤牛肉；军中奏起振奋人心的战斗乐曲。牛肉一吃完，就排成整齐的队伍。将军神采奕奕，意气昂扬，“沙场秋点兵”。这个“秋”字下得好。正当“秋高马壮”的时候，“点兵”出征，预示了战无不胜的前景。\n\n　　按谱式，《破阵子》是由句法、平仄、韵脚完全相同的两“片”构成的。后片的起头，叫做“过片”，一般的写法是：既要和前片有联系，又要“换意”，从而显示出这是另一段落，形成“岭断云连”的境界。辛弃疾却往往突破这种限制，《贺新郎·别茂嘉十二弟》如此，这首《破阵子》也是如此。“沙场秋点兵”之后，大气磅礴，直贯后片“马作的卢飞快，弓如霹雳弦惊”：将军率领铁骑，快马加鞭，神速奔赴前线，弓弦雷鸣，万箭齐发。虽没作更多的描写，但从“的卢马”的飞驰和“霹雳弦”的巨响中，仿佛看到若干连续出现的画面：敌人纷纷落马；残兵败将，狼狈溃退；将军身先士卒，乘胜追杀，一霎时结束了战斗；凯歌交奏，欢天喜地，旌旗招展。\n\n　　这是一场反击战。那将军是爱国的，但也是追求功名的。一战获胜，功成名就，既“了却君王天下事”，又“赢得生前身后名”，当为“壮”也。\n\n　　如果到此为止，那真够得上“壮词”。然而在那个被投降派把持朝政的时代，并没有产生真正“壮词”的条件，以上所写，不过是词人孜孜以求的理想而已。词人展开丰富的想象，化身为词里的将军，刚攀上理想的高峰，忽然一落千丈，跌回冷酷的现实，沉痛地慨叹道：“可怜白发生！”白发已生，而收复失地的理想成为泡影。想到自己徒有凌云壮志，而“报国欲死无战场”（借用陆游《陇头水》诗句），便只能在不眠之夜吃酒，只能在“醉里挑灯看剑”，只能在“梦”中驰逐沙场，快意一时。……这处境，的确是“悲哀”的。然而没有谁“可怜”他。于是，他写了这首“壮词”，寄给处境同样“可怜”的陈同甫。\n\n　　同甫是陈亮的字。学者称为龙川先生。为人才气豪迈，议论纵横。自称能够“推倒一世之智勇，开拓万古之心胸”。他先后写了《中兴五论》和《上孝宗皇帝书》，积极主张抗战，因而遭到投降派的打击。宋孝宗淳熙十五年冬天，他到上饶访辛弃疾，留十日。别后辛弃疾写《贺新郎》词寄他，他和了一首；以后又用同一词牌反复唱和。这首《破阵子》大约也是这一时期写的。\n\n　　全词从意义上看，前九句是一段，十分生动地描绘出一位披肝沥胆，忠一不二，勇往直前的将军的形象，从而表现了词人的远大抱负。末一句是一段，以沉痛的慨叹，抒发了“壮志难酬”的悲愤。壮和悲，理想和现实，形成强烈的反差。从这反差中，可以想到当时南宋朝廷的腐败无能，想到人民的水深火热，想到所有爱国志士报国无门的苦闷。由此可见，极其豪放的词，同时也可以写得极其含蓄，只不过和婉约派的含蓄不同罢了。\n\n　　这首词在声调方面有一点值得注意。《破阵子》上下两片各有两个六字句，都是平仄互对的，即上句为“仄仄平平仄仄”，下句为“平平仄仄平平”，这就构成了和谐的、舒缓的音节。上下片各有两个七字句，却不是平仄互对，而是仄仄平平平仄仄，仄仄平平仄仄平，这就构成了拗怒的、激越的音节。和谐与拗怒，舒缓与激越，形成了矛盾统一。作者很好地运用了这种矛盾统一的声调，恰当地表现了抒情主人公复杂的心理变化和梦想中的战斗准备、战斗进行、战斗胜利等许多场面的转换，收到了绘声绘色、声情并茂的艺术效果。\n\n　　这首词在布局方面也有一点值得注意。“醉里挑灯看剑”一句，突然发端，接踵而来的是闻角梦回、连营分炙、沙场点兵、克敌制胜，有如鹰隼突起，凌空直上。而当翱翔天际之时，陡然下跌，发出了“可怜白发生”的感叹，使读者不能不为作者的壮志难酬洒下惋惜怜悯之泪。这种陡然下落，同时也嘎然而止的写法，如果运用得好，往往因其出人意外而扣人心弦，产生强烈的艺术效果。这样的结构不但宋词中少有，在古代诗文中也很少见。这种艺术手法也正表现了辛词的豪放风格和他的独创精神。但是辛弃疾运用这样的艺术手法，不是故意卖弄技巧、追求新奇，这种表达手法正密切结合他的生活感情、政治遭遇。由于他的恢复大志难以实现，心头百感喷薄而出，便自然打破了形式上的常规，这绝不是一般只讲究文学形式的作家所能做到的。\n\n　　李白有首叫《越中览古》的诗。诗中写道：“越王勾践破吴归，战士还家尽锦衣。宫女好花满春殿，只今惟有鹧鸪飞！”这首七言诗中，有三句写到越王勾践的强盛，最后一句才点出越国的衰败景象，虽然表达的感情显然不同，但在谋篇布局方面又有相通之处，可以参看。', poem_tags = '宋词三百首,初中古诗,豪放,记梦,战争,抒情,壮志难酬' WHERE poem_title = '破阵子·为陈同甫赋壮词以寄之' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '迷蒙的烟雨，连夜洒遍吴地江天；清晨送走你，孤对楚山离愁无限！\n朋友啊，洛阳亲友若是问起我来；就说我依然冰心玉壶，坚守信念！', poem_notes = '芙蓉楼：原名西北楼，在润州（今江苏省镇江市）西北。登临可以俯瞰长江，遥望江北。丹阳在今江苏省西南部，东北滨长江，大运河斜贯，属镇江市。辛渐：诗人的一位朋友。\n寒雨：秋冬时节的冷雨。连江：雨水与江面连成一片，形容雨很大。吴：古代国名，这里泛指江苏南部、浙江北部一带。江苏镇江一带为三国时吴国所属。\n平明：天亮的时候。客：指作者的好友辛渐。楚山：楚地的山。这里的楚也指南京一带，因为古代吴、楚先后统治过这里，所以吴、楚可以通称。孤：独自，孤单一人。\n洛阳：现位于河南省西部、黄河南岸。\n冰心，比喻纯洁的心。玉壶，道教概念妙真道教义，专指自然无为虚无之心。', poem_appreciation = '“寒雨连江夜入吴”，迷蒙的烟雨笼罩着吴地江天（今南京一带，此地是三国孙吴故地。），织成了一张无边无际的愁网。夜雨增添了萧瑟的秋意，也渲染出了离别的黯淡气氛。那寒意不仅弥漫在满江烟雨之中，更沁透在两个离别友人的心头上。”连”字和”入”字写出雨势的平稳连绵，江雨悄然而来的动态能为人分明地感知，则诗人因离情萦怀而一夜未眠的情景也自可想见。 但是，这一幅水天相连、浩渺迷茫的吴江夜雨图，正好展现了一种极其高远壮阔的境界。中晚唐诗和婉约派宋词往往将雨声写在窗下梧桐、檐前铁马、池中残荷等等琐物上，而王昌龄却并不实写如何感知秋雨来临的细节，他只是将听觉、视觉和想象概括成连江入吴的雨势，以大片淡墨染出满纸烟雨，这就用浩大的气魄烘托了”平明送客楚山孤”的开阔意境。清晨，天色已明，辛渐即将登舟北归。诗人遥望江北的远山，想到友人不久便将隐没在楚山之外，孤寂之感油然而生。在辽阔的江面上，进入诗人视野的当然不止是孤峙的楚山，浩荡的江水本来是最易引起别情似水的联想的，唐人由此而得到的名句也多得不可胜数。 然而王昌龄没有将别愁寄予随友人远去的江水，却将离情凝注在矗立于苍莽平野的楚山之上。因为友人回到洛阳，即可与亲友相聚，而留在吴地的诗人，却只能像这孤零零的楚山一样，伫立在江畔空望着流水逝去。一个”孤”字如同感情的引线，自然而然牵出了后两句临别叮咛之辞：”洛阳亲友如相问，一片冰心在玉壶。”诗人从清澈无瑕、澄空见底的玉壶中捧出一颗晶亮纯洁的冰心以告慰友人，这就比任何相思的言辞都更能表达他对洛阳亲友的深情。\n\n　　早在六朝刘宋时期，诗人鲍照就用”清如玉壶冰”（《代白头吟》）来比喻高洁清白的品格。自从开元宰相姚崇作《冰壶诫》以来，盛唐诗人如王维、崔颢、李白等都曾以冰壶自励，推崇光明磊落、表里澄澈的品格。王昌龄托辛渐给洛阳亲友带去的口信不是通常的平安竹报，而是传达自己依然冰清玉洁、坚持操守的信念，是大有深意的。\n\n　　诗人在这以晶莹透明的冰心玉壶自喻，正是基于他与洛阳诗友亲朋之间的真正了解和信任，这决不是洗刷谗名的表白，而是蔑视谤议的自誉。因此诗人从清澈无瑕、澄空见底的玉壶中捧出一颗晶亮纯洁的冰心以告慰友人，这就比任何相思的言辞都更能表达他对洛阳亲友的深情。\n\n　　即景生情，情蕴景中，本是盛唐诗的共同特点，而深厚有余、优柔舒缓、“尽谢炉锤之迹”（胡应麟《诗薮》）又是王诗的独特风格。本诗那苍茫的江雨和孤峙的楚山，不仅烘托出诗人送别时的凄寒孤寂之情，更展现了诗人开朗的胸怀和坚强的性格。屹立在江天之中的孤山与冰心置于玉壶的比象之间又形成一种有意无意的照应，令人自然联想到诗人孤介傲岸、冰清玉洁的形象，使精巧的构思和深婉的用意融化在一片清空明澈的意境之中，所以天然浑成，不着痕迹，含蓄蕴藉，余韵无穷。\n\n　　《新唐书》王昌龄本传称”其诗绪密而思清”。他的绝句大都有这一特点，此首也不例外，特别是”洛阳亲友如相问，一片冰心在玉壶”二句，细致精密，给人以冰清玉洁之感。\n\n　　“一片冰心在玉壶”，即所谓”自明高志”。其中”冰心”二字见于《宋书》卷九十二：”冰心与贪流争激，霜情与晚节弥茂”。这是刘宋时代”清平无私”、”为上民所爱咏”的良吏陆徽的话，王昌龄取用”冰心”二字，当表示自己与”厉志廉洁，历任恪勤，奉公尽诚，克己无倦”的陆徽志同。”玉壶‘‘二字见于鲍照《代白头吟》：”直如朱丝绳，清如玉壶冰”。是高洁的象征。此外，陆机《汉高祖功臣颂》的”周苛慷慨，心若怀冰”、姚崇《冰壶诫序》的”夫洞澈无瑕，澄空见底，当官明白者，有类是乎。故内怀冰清，外涵玉润，此君子冰壶之德也”，大致都是”不牵于宦情”之意。王昌龄的这一名句不仅包蕴了”冰心”、”玉壶”、”心若怀冰”、”玉壶之德”等语意，而且深情而含蓄地表达了自己的品格和德行。', poem_tags = '唐诗三百首,小学古诗,送别,写雨,抒情,早教古诗100首' WHERE poem_title = '芙蓉楼送辛渐' AND poem_author = '王昌龄';
UPDATE edu_poem SET poem_translation = '两人一生一死，隔绝十年，相互思念却很茫然，无法相见。不想让自己去思念，自己却难以忘怀。妻子的孤坟远在千里，没有地方跟她诉说心中的凄凉悲伤。即使相逢也应该不会认识，因为我四处奔波，灰尘满面，鬓发如霜。\n晚上忽然在隐约的梦境中回到了家乡，只见妻子正在小窗前对镜梳妆。两人互相望着，千言万语不知从何说起，只有相对无言泪落千行。料想那明月照耀着、长着小松树的坟山，就是与妻子思念年年痛欲断肠的地方。', poem_notes = '乙卯：公元1075年，即北宋熙宁八年。\n十年：指结发妻子王弗去世已十年。\n思量：想念。\n千里：王弗葬地四川眉山与苏轼任所山东密州，相隔遥远，故称“千里”。\n孤坟：其妻王氏之墓。\n幽梦：梦境隐约，故云幽梦。\n小轩窗：指小室的窗前，轩：门窗\n顾：看。\n明月夜，短松冈：苏轼葬妻之地，短松：矮松。', poem_appreciation = '苏东坡十九岁时，与年方十六的王弗结婚。王弗年轻美貌，且侍亲甚孝，二人恩爱情深。可惜天命无常，王弗二十七岁就去世了。这对东坡是绝大的打击，其心中的沉痛，精神上的痛苦，是不言而喻的。苏轼在《亡妻王氏墓志铭》里说：“治平二年（1065）五月丁亥，赵郡苏轼之妻王氏（名弗），卒于京师。六月甲午，殡于京城之西。其明年六月壬午，葬于眉之东北彭山县安镇乡可龙里先君、先夫人墓之西北八步。”于平静语气下，寓绝大沉痛。公元1075年（熙宁八年），东坡来到密州，这一年正月二十日，他梦见爱妻王氏，便写下了这首“有声当彻天，有泪当彻泉 ”（陈师道语）且传诵千古的悼亡词。\n\n　　中国文学史上，从《诗经》开始，就已经出现“悼亡诗”。从悼亡诗出现一直到北宋的苏轼这期间，悼亡诗写得最有名的有西晋的潘岳和中唐的元稹。晚唐的李商隐亦曾有悼亡之作。他们的作品悲切感人。或写爱侣去后，处孤室而凄怆，睹遗物而伤神；或写作者既富且贵，追忆往昔，慨叹世事乖舛、天命无常；或将自己深沉博大的思念和追忆之情，用恍惚迷离的文字和色彩抒发出来，读之令人心痛。而用词写悼亡，是苏轼的首创。苏轼的这首悼亡之作与前人相比，它的表现艺术却另具特色。这首词是“记梦”，而且明确写了做梦的日子。但虽说是“记梦”，其实只有下片五句是记梦境，其他都是抒胸臆，诉悲怀的，写得真挚朴素，沉痛感人。\n\n　　题记中“乙卯”年指的是公元1075年（宋神宗熙宁八年），其时苏东坡任密州（今山东诸城）知州，年已四十。这首“记梦”词，实际上除了下片五句记叙梦境，其他都是抒情文字。开头三句，排空而下，真情直语，感人至深。“十年生死两茫茫”生死相隔，死者对人世是茫然无知了，而活着的人对逝者呢，不也同样吗？恩爱夫妻，撒手永诀，时间倏忽，转瞬十年。“不思量，自难忘”，人虽云亡，而过去美好的情景“自难忘”怀呵！王弗逝世转瞬十年了，想当初年方十六的王弗嫁给了十九岁的苏东坡，少年夫妻情深意重自不必说，更难得她蕙质兰心，明事理。这十年间，东坡因反对王安石的新法，颇受压制，心境悲愤；到密州后，又逢凶年，忙于处理政务，生活困苦到食杞菊以维持的地步，而且继室王润之（或许正是出于对爱妻王弗的深切思念，东坡续娶了王弗的堂妹王润之，据说此女颇有其堂姐风韵）及儿子均在身旁，哪能年年月月，朝朝暮暮都把逝世的妻子老挂在心间呢？不是经常想念，但绝不是已经忘却。这种深深地埋在心底的感情，是难以消除的。因为作者时至中年，那种共担忧患的夫妻感情，久而弥笃，是一时一刻都不能消除的。作者将“不思量”与“自难忘”并举，利用这两组看似矛盾的心态之间的张力，真实而深刻地揭示自己内心的情感。十年忌辰，触动人心的日子里，他又怎能“不思量”那聪慧明理的贤内助呢。往事蓦然来到心间，久蓄的情感潜流，忽如闸门大开，奔腾澎湃难以遏止。于是乎有梦，是真实而又自然的。“千里孤坟，无处话凄凉”。想到爱妻华年早逝，感慨万千，远隔千里，无处可以话凄凉，话说得极为沉痛。其实即便坟墓近在身边，隔着生死，就能话凄凉了吗？这是抹煞了生死界线的痴语、情语，极大程度上表达了作者孤独寂寞、凄凉无助而又急于向人诉说的情感，格外感人。接着，“纵使相逢应不识，尘满面，鬓如霜。”这三个长短句，又把现实与梦幻混同了起来，把死别后的个人种种忧愤，包括在容颜的苍老，形体的衰败之中，这时他才四十岁，已经“鬓如霜”了。明明她辞别人世已经十年，却要“纵使相逢”，这是一种绝望的、不可能的假设，感情是深沉、悲痛，而又无奈的，表现了作者对爱侣的深切怀念，也把个人的变化做了形象的描绘，使这首词的意义更加深了一层。\n\n　　苏东坡曾在《亡妻王氏墓士铭》记述了“妇从汝于艰难，不可忘也”的父训。而此词写得如梦如幻，似真非真，其间真情恐怕不是仅仅依从父命，感于身世吧。作者索于心，托于梦的确实是一份“不思量，自难忘”的患难深情。\n\n　　下片的头五句，才入了题开始记梦，“夜来幽梦忽还乡。 ”是记叙，写自己在梦中忽然回到了时在念中的故乡，在那个两人曾共度甜蜜岁月的地方相聚、重逢。“小轩窗，正梳妆。”那小室，亲切而又熟悉，她情态容貌，依稀当年，正在梳妆打扮。这犹如结婚未久的少妇，形象很美，带出苏轼当年的闺房之乐。作者以这样一个常见而难忘的场景表达了爱侣在自己心目中的永恒的印象。夫妻相见，没有出现久别重逢、卿卿我我的亲昵，而是“相顾无言，唯有泪千行”！这正是东坡笔力奇崛之处，妙绝千古。正唯“无言”，方显沉痛；正为“无言”，才胜过了万语千言；正唯无言，才使这个梦境令人感到无限凄凉。“此时无声胜有声”，无声之胜，全在于此。别后种种从何说起？只有任凭泪水倾盈。一个梦，把过去拉了回来，但当年的美好情景，并不存在。这是把现实的感受溶入了梦中，使这个梦也令人感到无限凄凉。结尾三句，又从梦境落回到现实上来。“料得年年肠断处；明月夜，短松冈。”料想长眠地下的爱侣，在年年伤逝的这个日子，为了眷恋人世、难舍亲人，该是柔肠寸断了吧？推己至人，作者设想此时亡妻一个人在凄冷幽独的“明月”之夜的心境，可谓用心良苦。在这里作者设想死者的痛苦，以寓自己的悼念之情。这种表现手法，有点像杜甫的名作《月夜》，不说自己如何，反说对方如何，使得诗词意味，更加蕴蓄。东坡此词最后这三句，意深，痛巨，余音袅袅，让人回味无穷。特别是“明月夜，短松冈”二句，凄凉清幽独，黯然魂销。正所谓“天长地久有时尽，此恨绵绵无绝期”（白居易语）。这番痴情苦心实可感天动地。\n\n　　这首词运用分合顿挫，虚实结合以及叙述白描等多种艺术的表现方法，来表达作者怀念亡妻的思想感情，在对亡妻的哀思中又糅进自己的身世感慨，因而将夫妻之间的情感表达得深婉而挚着，使人读后无不为之动情而感叹哀惋。\n\n　　宋神宗驾崩后，宋哲宗继位，任用司马光为宰相，苏东坡又被召回京城升任龙图阁学士，兼任小皇帝的侍读。这时的苏东坡，十分受宣仁皇太后和年仅十二岁的小皇帝的赏识，政治上春风得意。苏东坡不时怀念起死去的结发妻子王弗：“十年生死两茫茫，不思量，自难忘。千里孤坟，无处话凄凉。纵使相逢应不识，尘满面，鬓如霜。夜来幽梦忽还乡，小轩窗，正梳妆。相顾无言，唯有泪千行。料得年年肠断处，明月夜，短松冈。”由此成就了一阙悼妻怀思的传世之作。\n\n　　苏东坡对于王弗是痛彻心肺的悲情。“夜来幽梦忽还乡，小轩窗，正梳妆。相顾无言，唯有泪千行。” 阴阳相隔，重逢只能期于梦中，也只有梦是没有时空限制的，可以超越一切的界限和有限。朴素真挚的深情，沉痛的生离死别，每读一次就更为其中的深情所感动。\n\n　　应该说，苏东坡再次得宠多少有些幸运的成分。这么个大词人，大文学家，被政治牵绊得头晕目眩，苏子的一生常常让人有点啼笑皆非的意思，所以我们有理由相信，在这一段相对安稳适意的生活中，苏东坡的精神状态是轻松和愉悦的，但苏东坡也断断不能忘记王弗曾经陪伴着自己度过的那些艰难的时光。王弗在苏东坡的一生中作扮演的角色绝非一个主妇那么简单，在林语堂的《苏东坡传》中也曾有过这样的落笔：……苏东坡……由气质和自然的爱好所促使，要变成一个隐士。社会，文化，学问，读历史的教训，外在的本分责任，只能隐藏人的本来面目。若把一个人由时间和传统所赋予他的那些虚饰剥除净尽，此人的本相便呈现于你之前了。……他偶尔喝醉，甚至常常喝醉而月夜登城徘徊。这时他成了自然中伟大的顽童——也许造物主根本就希望人是这副面貌吧。“顽童”，这里林语堂先生固然是在一种嘉许的语气在点评苏东坡的自由性灵，然而苏东坡实际上又何尝不是一个顽皮的孩子呢？不谙世事，兴致所至，聪明有余而内敛不足。\n\n　　夫人稳健，而丈夫往往不能。丈夫往往急躁，灰心丧气，喜怒无常。高兴了把酒言欢，不高兴了也要骂骂娘。麻烦的是丈夫有了旷世的才气，就不是骂骂娘这么简单了。苏东坡常常会在自己的诗作里流露一些“不合时宜”的论调，自找祸端。由此可见在日常的生活起居，待人接物中，这等人物将是何等的低才。倘若没有一个得体大度，端庄典雅的夫人为丈夫张罗这些“不入眼”俗事，怕苏先生不会有几天清闲。在密州，他们正过苦日子，苏东坡对新所得税至为愤怒，孩子揪着他的衣裳对他晓晓不休。他说：“孩子们真傻！”苏夫人说：“你才傻。你一天闷坐，有什么好处？好了。我给弄点儿酒喝吧。”在一首诗里记这件事时，苏东坡觉得自己很丢脸，这时妻子洗杯子给他热酒。这当然使他很欢喜，他说他妻子比诗人刘伶的妻子贤德。因为刘伶的妻子不许丈夫喝酒。苏夫人也是用了好几年的工夫才摸清楚丈夫性格，那是多方面的个性，既是乐天达观随遇而安，可是有时又激烈而固执。苏夫人聪明解事，办事圆通。 她是进士的女儿，能读能写，但是并非一个“士”。做妻子的也知道要管家事，要抚养孩子，要过日子。正因为如此，苏东坡的生活中是不能没有一个这样的女人把握船舵的。只有在妻子的无微不至的照顾下，苏东坡才有更多的闲情逸致去“浴乎沂，风乎舞雩”。也正因为如此苏夫人也成为苏东坡最为信任依赖的人，很多事情埋藏在苏东坡的心灵深处，别人大都不知道，苏东坡的妻子一定知道。同过患难，共过生死，日日的关心和爱护，充满信任的等待和抚慰。王弗给与苏东坡的是所谓“相濡以沫”的质朴而深厚的情感。\n\n　　在这首小词中，读不到一句令人感觉“矫情”之语，词语的运用简练凝重。每一个音节的连接都有冷涩凝绝之感，犹如声声咽泣，压抑沉重的气氛就在这“幽咽泉流”中弥散开来，让人艰与呼吸，又难以逃避。\n\n　　苏东坡用了十年都舍弃不下的，是那种相濡以沫的亲情。他受不了的不是没有了轰轰烈烈的爱情，而是失去了伴侣后孤单相吊的寂寞。“纵使相逢应不识，尘满面，鬓如霜”在梦里能够看见的，也全是逝去亲人往日生活里的琐碎片断。因为在那些琐碎里，凝结着化不去的亲情。 在红尘中爱的最高境界是什么？执子之手是一种境界，相濡以沫是一种境界，生死相许也是一种境界。在这世上有一种最为凝重、最为浑厚的爱叫相依为命。那是天长日久的渗透，是一种融入了彼此之间生命中的温暖。\n\n　　面对这样的深情，解读都似乎是一种伤害，那是需要在生命里反复吟唱，静夜中不断怀思的乐音。无数的人毫不吝惜地把“绝唱”这个词赠与了这首词，然而，时光流转了千年，我们又听到了一声相似的叹息，那叹息给予了我们有一篇值得反复玩味的美文，也让我们更深切地领会了苏子心中的创痛，两个文人千年的唱和，诉说着人世间最值得感念的深情。这就是巴金先生所写的《怀念肖珊》和《再忆肖珊》。不再过多的评说什么，我摘录了其中两个段落，作为本文的结尾，这是《江城子》最深沉的诠释，在这样一个滥情的年代，我们庆幸还有这样的情感值得我们永远的祭奠：\n\n　　她不仅分担了我的痛苦，还给了我不少的安慰和鼓励。……我进了门看到她的面容，满脑子的乌云都消散了。我有什么委屈、牢骚都可以向她尽情倾吐。……她不断地给我安慰，对我表示信任，替我感到不平。……今天回想当时的情景，她那张满是泪痕的脸还历历在我眼前。我多么愿意让她的泪痕消失，笑容在她那憔悴的脸上重现，即使减少我几年的生命来换取我们家庭生活中一个宁静的夜晚，我也心甘情愿！\n\n　　她离开我十二年了。十二年，多么长的日日夜夜。每次我回到家门口，眼前就出现一张笑脸，一个亲切的声音向我迎来，可是走进院子，却只见一些高高矮矮的、没有花的绿树。上了台阶，我环顾四周，她最后一次离家的情景还历历在目……\n\n　　我仿佛还站在台阶上等待着车子的驶近，等待着一个人回来。这样长的等待。十二年了。甚至在梦里我也听不见她那清脆的笑声。我记得的只是孩子们捧着她的骨灰盒回家的情景。这骨灰盒起初给放在楼下我的寝室内、床前五斗橱上。\n\n　　悲伤没有用。我必须结束那一切梦景。我应当振作起来，哪怕是最后的一次。骨灰盒还放在我的家中，亲爱的面容还印在我的心上，她不会离开我，也从未离开我。做了十年的“牛鬼”，我并不感到孤单。我还有勇气迈步走向我的最终目标——死亡。我的遗物将献给国家，我的骨灰将同她的骨灰搅拌在一起，撒在园中给花树作肥料。', poem_tags = '宋词三百首,婉约,悼亡,爱情,记梦,思念' WHERE poem_title = '江城子·乙卯正月二十日夜记梦' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '高高的柳树长满了翠绿的新叶，轻柔的柳枝垂下来，就像万条轻轻飘动的绿色丝带。\n这细细的嫩叶是谁的巧手裁剪出来的呢？原来是那二月里温暖的春风，它就像一把灵巧的剪刀。', poem_notes = '碧玉：碧绿色的玉。这里用以比喻春天嫩绿的柳叶。\n妆：装饰，打扮。\n一树：满树。一：满，全。在中国古典诗词和文章中，数量词在使用中并不一定表示确切的数量。下一句的“万”，就是表示很多的意思。\n绦（tāo）：用丝编成的绳带。这里指像丝带一样的柳条。\n裁：裁剪。\n似：如同，好像。', poem_appreciation = '杨柳的形象美是在于那曼长披拂的枝条。一年一度，它长出了嫩绿的新叶，丝丝下垂，在春风吹拂中，有着一种迷人的意态。这是谁都能欣赏的。古典诗词中，借用这种形象美来形容、比拟美人苗条的身段，婀娜的腰身，也是读者所经常看到的。这诗别出新意，翻转过来。“碧玉妆成一树高”，一开始，杨柳就化身为美人而出现：“万条垂下绿丝绦”，这千条万缕的垂丝，也随之而变成了她的裙带。上句的“高”字，衬托出美人婷婷袅袅的风姿；下句的“垂”字，暗示出纤腰在风中款摆。诗中没有“杨柳”和“腰支”字样，然而这早春的垂柳以及柳树化身的美人，却给写活了。《南史》说刘悛之为益州刺史，献蜀柳数株，“条甚长，状若丝缕。”齐武帝把这些杨柳种植在太昌云和殿前，玩赏不置，说它“风流可爱”。这里把柳条说成“绿丝绦”，可能是暗用这个关于杨柳的著名典故。但这是化用，看不出一点痕迹的。\n\n　　“碧玉妆成”引出了“绿丝绦”，“绿丝绦”引出了“谁裁出”，最后，那视之无形的不可捉摸的“春风”，也被用“似剪刀”形象化地描绘了出来。这“剪刀”裁制出嫩绿鲜红的花花草草，给大地换上了新妆，它正是自然活力的象征，是春给予人们美的启示。从“碧玉妆成”到“剪刀”，读者可以看出诗人艺术构思一系列的过程。诗歌里所出现的一连串的形象，是一环紧扣一环的。\n\n　　我国古代有不少著名的美女，柳，为什么单单要用碧玉来比呢？这有两层意思：一是碧玉这名字和柳的颜色有关，“碧”和下句的“绿”是互相生发、互为补充的。二是碧玉这个人在人们头脑中永远留下年轻的印象。提起碧玉，人们就会联想到“碧玉破瓜时”这首广泛流传的《碧玉歌》，还有“碧玉小家女”（肖绎《采莲赋》）之类的诗句。碧玉在古代文学作品里，几乎成了年轻貌美的女子的泛称。用碧玉来比柳，人们就会想象到这美人还未到丰容盛鬋的年华；这柳也还是早春稚柳，没有到密叶藏鸦的时候；和下文的“细叶”“二月春风”又是有联系的。\n\n　　“碧玉妆成一树高，万条垂下绿丝绦”，深深地抓着了垂柳的特征，在诗人的眼中，它似美女的化身。高高的树干，就像她亭亭玉立的风姿，下垂的柳条，就像她裙摆上的丝带。在这里，柳就是人，人就是柳，两者之间仿佛没有什么截然的分别。而且“碧玉”也有双关的意义。既在字面上与柳树的翠色相合，又指年轻貌美的少女，与下面的“二月春风”恰相呼应——这是早春的垂柳，还未到夏秋之际亭亭如盖、树荫清圆的时候。然而，更妙的以下两句：“不知细叶谁载出，二月春风似剪刀。”在贺知章之前，有谁想过春风像剪刀？把乍暖还寒的二月春风由无形化为有形，它显示了春风的神奇灵巧，并使《咏柳》成为咏物诗的典范之作。\n\n　　此诗借柳树歌咏春风，把春风比作剪刀，说她是美的创造者，赞美她裁出了春天。诗中洋溢着人逢早春的欣喜之情。比拟和比喻新奇贴切是此诗的成功之处。因此《唐诗笺注》云：“赋物入妙，语意温柔。”', poem_tags = '小学古诗,写景,咏物,春天,写风,柳树,早教古诗100首,古诗里的十二个月' WHERE poem_title = '咏柳 / 柳枝词' AND poem_author = '贺知章';
UPDATE edu_poem SET poem_translation = '泉眼悄然无声是因舍不得细细的水流，树荫倒映水面是喜爱晴天和风的轻柔。\n娇嫩的小荷叶刚从水面露出尖尖的角，早有一只调皮的小蜻蜓立在它的上头。', poem_notes = '泉眼：泉水的出口。惜：吝惜。\n照水：映在水里。晴柔：晴天里柔和的风光。\n尖尖角：初出水端还没有舒展的荷叶尖端。\n上头：上面，顶端。为了押韵，“头”不读轻声。', poem_appreciation = '这首诗小巧、精致，宛如一幅花草虫鸟彩墨画。画面之中，池、泉、流、荷和蜻蜓，落笔都小，却玲珑剔透，生机盎然。\n\n　　第一句，紧扣题目写小池的源泉，一股涓涓细流的泉水。泉水从洞口流出，没有一丝声响，当然是小之又小的。流出的泉水形成一股细流，更是小而又小了。这本来很寻常，然而作者却凭空加一“惜”字，说好像泉眼很爱惜这股细流，吝啬地舍不得多流一点儿。于是这句诗就立刻飞动起来，变得有情有趣，富有人性。\n\n　　第二句，写树阴在晴朗柔和的风光里，遮住水面。这也是极平常之事，可诗人加一“爱”字，似乎用她的阴凉盖住小池，以免水分蒸发而干涸，这样就化无情为有情了。而且，诗舍形取影，重点表现水面上的柔枝婆娑弄影，十分空灵。\n\n　　三、四句把焦点缩小，写池中一株小荷以及荷上的蜻蜓。小荷刚把她的含苞待放的嫩尖露出水面，显露出勃勃生机，可在这尖尖嫩角上却早有一只小小蜻蜓立在上面，它似乎要捷足先登，领略春光。小荷与蜻蜓，一个“才露”，一个“早有”，以新奇的眼光看待身边的一切，捕捉那稍纵即逝的景物。\n\n　　诗人触物起兴，用敏捷灵巧的手法，描绘充满情趣的特定场景，把大自然中的极平常的细小事物写得相亲相依，和谐一体，活泼自然，流转圆活，风趣诙谐，通俗明快。且将此诗写的犹如一幅画，画面层次丰富：太阳、树木、小荷、小池，色彩艳丽，还有明亮的阳光、深绿的树荫、翠绿的小荷、鲜活的蜻蜓，清亮的泉水。画面充满动感：飞舞的蜻蜓、影绰的池水，充满了诗情画意。', poem_tags = '古诗三百首,小学古诗,夏天,写水,池塘' WHERE poem_title = '小池' AND poem_author = '杨万里';
UPDATE edu_poem SET poem_translation = '行至孤山寺北，贾公亭西，暂且歇脚，举目远眺，但见水面平涨，白云低垂，秀色无边。\n几只黄莺，争先飞往向阳树木，谁家燕子，为筑新巢衔来春泥？\n鲜花缤纷，几乎迷人眼神，野草青青，刚刚遮没马蹄。\n湖东景色，令人流连忘返，最为可爱的，还是那绿杨掩映的白沙堤。', poem_notes = '钱塘湖：即杭州西湖。\n孤山寺：南北朝时期陈文帝（522～565）初年建，名承福，宋时改名广华。孤山：在西湖的里、外湖之间，因与其他山不相接连，所以称孤山。上有孤山亭，可俯瞰西湖全景。贾亭：又叫贾公亭。西湖名胜之一，唐朝贾全所筑。唐贞元（唐德宗年号，785～805）中，贾全出任杭州刺史，于钱塘湖建亭。人称“贾亭”或“贾公亭”，该亭至唐代末年。\n水面初平：湖水才同堤岸齐平，即春水初涨。初：在古汉语里用作副词，常用来表示时间，是指不久。云脚低：白云重重叠叠，同湖面上的波澜连成一片，看上去，浮云很低，所以说“云脚低”。点明春游起点和途径之处，着力描绘湖面景色。多见于将雨或雨初停的时候。云脚：接近地面的云气，多见于将雨或雨初停时。“脚”的本义指人和动物行走的器官。这里指低垂的云。\n 早莺：初春时早来的黄鹂。莺：黄鹂，鸣声婉转动听。争暖树：争着飞到向阳的树枝上去。暖树：向阳的树。\n新燕：刚从南方飞回来的燕子。啄：衔取。燕子衔泥筑巢。春行仰观所见，莺歌燕舞，生机动人。侧重禽鸟。\n乱花：纷繁的花。渐：副词，渐渐地。欲：副词，将要，就要。迷人眼：使人眼花缭乱。\n浅草：浅浅的青草。才能：刚够上。没（mò）：遮没，盖没。春行俯察所见，花繁草嫩，春意盎然。侧重花草。浅浅的青草刚够没过马蹄。\n湖东：以孤山为参照物，白沙堤（即白堤）在孤山的东北面。行不足：百游不厌。足，满足。\n阴：同“荫”，指树荫。白沙堤：即今白堤，又称沙堤、断桥堤，在西湖东畔，唐朝以前已有。白居易在任杭州刺史时所筑白堤在钱塘门外，是另一条。', poem_appreciation = '白居易在杭州时，有关湖光山色的题咏很多。这诗处处扣紧环境和季节的特征，把刚刚披上春天外衣的西湖，描绘得生意盎然，恰到好处。\n\n　　诗的首联紧扣题目总写湖水。前一句点出钱塘湖的方位和四周“楼观参差”景象，两个地名连用，显示出一种动感，说明诗人是在一边走，一边观赏。后一句正面写湖光水色：春水初涨，水面与堤岸齐平，空中舒卷的白云和湖面荡漾的波澜连成一片，正是典型的江南春湖的水态天容。颔联写仰视所见禽鸟。莺在歌，燕在舞，显示出春天的勃勃生机。黄莺和燕子都是春天的使者，黄莺用它婉转流利的歌喉向人间传播春回大地的喜讯；燕子穿花贴水，衔泥筑巢，又启迪人们开始春日的劳作。“几处”二字，勾画出莺歌的此呼彼应和诗人左右寻声的情态。“谁家”二字的疑问，又表现出诗人细腻的心理活动，并使读者由此产生丰富的联想。颈联写俯察所见花草。因为是早春，还未到百花盛开季节，所以能见到的尚不是姹紫嫣红开遍，而是东一团，西一簇，用一个“乱”字来形容。而春草也还没有长得丰茂，仅只有没过马蹄那么长，所以用一个“浅”字来形容。这一联中的“渐欲”和“才能”又是诗人观察、欣赏的感受和判断，这就使客观的自然景物化为带有诗人主观感情色彩的眼中景物，使读者受到感染。这两联细致地描绘了西湖春行所见景物，以“早”“新”“争”“啄”表现莺燕新来的动态；以“乱”“浅”“渐欲”“才能”，状写花草向荣的趋势。这就准确而生动地把诗人边行边赏的早春气象透露出来，给人以清新之感。前代诗人谢灵运“池塘生春草，园柳变鸣禽”（《登池上楼》）二句之所以妙绝古今，受到激赏，正是由于他写出了季节更换时这种乍见的喜悦。《钱塘湖春行》以上两联在意境上颇与之相类，只是白诗铺展得更开些。尾联略写诗人最爱的湖东沙堤。白堤中贯钱塘湖，在湖东一带，可以总揽全湖之胜。只见绿杨荫里，平坦而修长的白沙堤静卧碧波之中，堤上骑马游春的人来往如织，尽情享受春日美景。诗人置身其间，饱览湖光山色之美，心旷而神怡。以“行不足”说明自然景物美不胜收，诗人也余兴未阑。\n\n　　中国历史上，在天堂杭州当剌史或知州的可以说是不乏名人，不过，最有名的要算是唐朝和宋朝的两位大文豪白居易和苏东坡了。他们不但在杭州任上留下了叫后人敬仰的政绩，而且也流传下来许多描写杭州及其西湖美景的诗词文章与传闻轶事，所以又有人们称他们为“风流太守”。白居易的七律《钱塘湖春行》就是为人们所熟知的一篇，这首诗不但描绘了西湖旖旎骀荡的春光，以及世间万物在春色的沐浴下的勃勃生机，而且将诗人本身陶醉在这良辰美景中的心态和盘托出。 “孤山寺北贾亭西，水面初平云脚低。”诗歌的第一句是地点，第二句是远景。孤山坐落在西湖的后湖与外湖之间，峰峦叠翠，上有孤山寺，登山观景，美不胜收。据《唐语林》卷六载，贾公亭建于贞元年间，未五六十年后废。白居易写此诗时，其亭尚在，也算是西湖的一处名胜。白居易一开始来到了孤山寺的北面，贾公亭的西畔，放眼望去，只见冬水荡漾，云幕低垂，湖光山色，尽收眼底。“初平”所表达的是白居易对冬日里西湖的一种特有的感受。由于连绵不断的春雨，使得如今的湖面看上去比起冬日来上升了不少，似乎眼看着就要与视线持平了，这种水面与视线持平的感觉只有人面对广大的水域才可能有的感觉，也是一个对西湖有着深刻了解和喜爱的人才能写出的感受。此刻，脚下平静的水面与天上低垂的云幕构成了一副宁静的水墨西湖图，而正当诗人默默地观赏西湖那静如处子的神韵时，耳边却传来了阵阵清脆的鸟鸣声，打破了他的沉思，于是他把视线从水云交界处收了回来，从而发现了自己实际上是早已置身于一个春意盎然的美好世界中了。 “几处早莺争暖树，谁家新燕啄春泥。乱花渐欲迷人眼，浅草才能没马蹄。”这四句是白居易此诗的核心部分，也就是最为抢眼的句子，同时也是白诗描写春光特别是描写西湖春光的点睛之笔。几处，是好几处，甚至也可以是多处的意思。用“早”来形容黄莺，体现了白居易对这些充满生机的小生命的由衷的喜爱：树上的黄莺一大早就忙着抢占最先见到阳光的“暖树”，生怕一会儿就会赶不上了。一个“争”字，让人感到春光的难得与宝贵。而不知是谁家檐下的燕子，此时也正忙个不停地衔泥做窝，用一个“啄”字，来描写燕子那忙碌而兴奋的神情，似乎把小燕子也写活了。这两句着意描绘出莺莺燕燕的动态，从而使得全诗洋溢着春的活力与生机。黄莺是公认的春天歌唱家，听着它们那婉转的歌喉，使人感到春天的妩媚；燕子是候鸟，它们随着春天一起回到了家乡，忙着重建家园，迎接崭新的生活，看着它们飞进飞出地搭窝，使人们倍加感到生命的美好。在对天空中的小鸟进行了形象的拟人化描写之后，白居易又把视线转向了脚下的植被，“乱花渐欲迷人眼，浅草才能没马蹄。”这也是一联极富情感色彩与生命活力的景物描写，充分显示了白居易对描写对象的细致观察以及准确把握其特征的能力。花而言其乱，乃至要乱得迷了赏花人的目光，在旁人的诗句中，很少有这种写法，而这种独到的感受，却正是白居易在欣赏西湖景色时切身的体验，五颜六色的鲜花，漫山野地开放，在湖光山色的映衬下，千姿百态，争奇斗艳，使得白居易简直不知把视线投向哪里才好，也无从分辨出个高下优劣来，只觉得眼也花了，神也迷了，真是美不胜收，应接不暇。“乱花渐欲迷人眼”一句是驻足细看，而“浅草才能没马蹄”，则已经是骑马踏青了，在绿草如茵、繁花似锦的西子湖畔，与二三友人，信马由缰，自由自在地游山逛景，是一件非常惬意的事情，马儿似乎也体会到了背上主人那轻松闲逸的兴致，便不紧不慢地，踩着那青青的草地，踏上那长长的白堤。诗人在指点湖山、流连光景的不经意间，偶然瞥到了，马蹄在草地上亦起亦落、时隐时现的情景，觉得分外有趣，将其写入了诗中，就是这随意的一笔，却为全诗增添了多少活泼情趣和雅致闲情。\n\n　　著名美学家别林斯基曾说过，“无论在哪一种情况下，美都是从灵魂深处发出的，因为大自然的景象是不可能绝对的美，这美隐藏在创造或者观察它们的那个人的灵魂里。”白居易的《钱塘湖春行》恰恰说明了这一美学欣赏真理。因为西湖的景色再美，也会有不尽人意之处，但是在白居易的眼中，它无疑是天下最美的景致，因为他不但善于观察，而且更善于发现和体验。或是在影视风光片中，听说和看到名胜山水美不胜收，心中不由得生起无限向往之情，可是往往一旦身临其境，面对真山真水，却反而觉得远没有预期的那样动人美丽。这就是因为人们不能带着一种发现欣赏的眼光去看待自然山水，而是带着一种先入为主的过高的甚至是带有几分挑剔的眼光去游山玩水的原因。古往今来，西湖向人们展示了无比美妙的春光，有很多人见证了西子湖的春色。可是到头来，仍然只有几首作品能广为传诵。白居易就是因为有着一副难得的美学家的欣赏眼光，才能在无数西湖的游客中，独具慧眼地发现它的动人之处，才能真正享受到大自然赐予人类的这一人间天堂。白居易并没有看到很多的“早莺”和“新燕”，只有“几处”、只见“谁家”而已，要是其他人，说不定还会因为没有到“处处”闻莺、“家家”有燕的时节，而感到遗憾，心想要是再晚来十天半个月就好了。可是白居易却不这样认为，少有少的好处，正因为少，才是“早莺”，才是“新燕”，才有一种感知春天到来的喜悦，如果诗人没有一种年轻的心态和热爱生命与春天的胸怀，恐怕就不会被这为数不多的报春者所打动，所陶醉，而欣然写下这动人的诗篇了。也正因为如此，他才能闻花花香，见草草美，为四处点缀的各色野花而心乱神迷，为没过马蹄的草地而唏嘘感叹了。白居易是幸运的，因为他有一双发现美、发现春天的眼睛，所以他会在西湖美景中，不能自已，乃至流连忘返：“最爱湖东行不足，绿杨阴里白沙堤。”白居易任杭州剌史时，也确曾修堤蓄水，灌溉民田，不过其堤在钱塘门之北，可是后人多误以白堤为白氏所修之堤了。\n\n　　这首诗就像一篇短小精悍的游记，从孤山、贾亭开始，到湖东、白堤止，一路上，在湖青山绿那美如天堂的景色中，诗人饱览了莺歌燕舞，陶醉在鸟语花香，最后，才意犹未尽地沿着白沙堤，在杨柳的绿阴底下，一步三回头，恋恋不舍地离去了。耳畔还回响着由世间万物共同演奏的春天的赞歌，心中便不由自主地流泻出一首饱含着自然融合之趣的优美诗歌来。\n\n　　前人说“乐天之诗，情致曲尽，入人肝脾，随物赋形，所在充满”（王若虚《滹南诗话》），又说“乐天诗极深厚可爱，往往以眼前事为见得语，皆他人所未发”（田雯《古欢堂集》）。这首诗语言平易浅近，清新自然，用白描手法把精心选择的镜头写入诗中，形象活现，即景寓情，从生意盎然的早春湖光中，体现出作者游湖时的喜悦心情，是当得起以上评语的。', poem_tags = '初中古诗,春天,西湖,写景,喜悦' WHERE poem_title = '钱塘湖春行' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '东行登上碣石山，来观赏那苍茫的海。\n海水多么宽阔浩荡，山岛高高地挺立在海边。\n树木和百草丛生，十分繁茂，\n秋风吹动树木发出悲凉的声音，海中涌着巨大的海浪。\n太阳和月亮的运行，好像是从这浩瀚的海洋中发出的。\n银河星光灿烂，好像是从这浩瀚的海洋中产生出来的。\n我很高兴，就用这首诗歌来表达自己内心的志向。', poem_notes = '临：登上，有游览的意思。\n碣（jié）石：山名。碣石山，河北昌黎碣石山。公元207年秋天，曹操征乌桓得胜回师时经过此地。\n沧：通“苍”，青绿色。\n海：渤海\n何：多么\n澹澹（dàn dàn）：水波摇动的样子。\n竦峙（sǒng zhì）：耸立。竦 ，通耸，高。\n萧瑟：树木被秋风吹的声音。\n洪波：汹涌澎湃的波浪\n日月：太阳和月亮\n若：如同.好像是.\n星汉：银河，天河。\n幸：庆幸。\n甚：极点。\n至：非常，\n幸甚至哉，歌以咏志：太值得庆幸了！就用诗歌来表达心志吧。\n（最后两句每章都有，与本诗正文的内容没有的直接关系。）', poem_appreciation = '《观沧海》这首诗，前六句写的是实景,而后四句则是曹操的想象,最后两句跟本诗原文没有直接关系。这首诗不但通篇写景，且独具一格，堪称中国山水诗的最早佳作，特别受到文学史家的厚爱。这首诗写秋天的大海，能够一洗悲秋的感伤情调，写得沉雄健爽，气象壮阔，这与曹操的气度、品格乃至美学情趣都是紧密相关的。 在这首诗中，情景紧密相连。作者通过写沧海，表达了他统一中国建功立业的抱负。这种感情在诗中并没有直接表露，而是把它蕴藏在对景物的描写当中来抒发情感，寓情于景中，句句写景，又是句句抒情。“水何”六句虽然是在描绘生机勃勃的大海风光，实际上在歌颂祖国壮丽的山河，透露出作者热爱祖国的感情。目睹祖国山河壮丽的景色，更加激起了诗人要统一祖国的强烈愿望。于是借助丰富的想象，来充分表达这种愿望。作者以沧海自比，通过写大海吞吐宇宙的气势，来表现诗人自己宽广的胸怀和豪迈的气魄，感情奔放，却很含蓄。“日月”四句是写景的高潮，也是作者感情发展的高潮。宋人敖陶孙说曹诗“如幽燕老将，气韵沉雄”。《观沧海》这首诗意境开阔，气势雄浑，这与一个雄心勃勃的政治家和军事家的风度是一致的，真是使人读其诗如见其人。\n\n　　建安十二年（207），曹操率领大军征伐当时东北方的大患乌桓。这是曹操统一北方大业中的一次重要战争。远征途中，他写下了乐府歌辞《步出夏门行》（属于《相和歌·瑟调曲》）。这一组诗包括五个部分，开头为“艳”辞，即序诗，以下各篇分别取诗句命名，依次为《观沧海》、《冬十月》、《河朔寒》（亦作《土不同》）、《龟虽寿》。从音乐曲调上说，五个部分是一个整体，从歌词内容上看，四篇则可以独立成篇。\n\n　　首二句“东临碣石，以观沧海”，写诗人于挥师北伐之际来到碣石山下，登高观海。碣石山原位于今河北省乐亭县西南（一说在今河北省昌黎县西北），汉时还在陆上，面对着渤海，六朝时由于地质变动，沉于海中。诗人登上碣石山，俯视大海，只见的：“水何澹澹，山岛竦峙”。澹澹，水波动荡。竦峙，岛屿高耸的样子。诗人登高远眺，举目所及只见一望无垠的大海波摇浪涌，海中的岛屿高高矗立。这是多么辽阔、多么壮观的景象！在历史上，秦始皇、汉武帝都曾东巡至此，刻石观海。如今诗人站在秦皇、汉武游踪所到之处，居高临下，望着水天相连的苍茫大海和海中高耸的岛屿，想到中原地区已经平定，北伐乌桓也已取得决定性胜利，北方统一即将实现，心情该是何等激奋！这时，诗人的目光注视着海上的岛屿，眼前是一派生机盎然的景象：“树木丛生，百草丰茂。秋风萧瑟，洪波涌起。”树木百草，生长十分繁茂，一阵萧瑟的秋风吹过，海面上涌起滚滚的波涛。尽管萧瑟的秋风给人以悲凉萧杀之感，但是疾风劲草，方显其英雄本色；洪波汹涌，愈见其生命不息！这是对自然环境的真实描绘，也是诗人主观感受的具体写照。曹操在取得一连串的战争胜利之后，他觉得自己的雄图伟业犹如这树木百卉一样，生机勃发，也为这洪波涌起的大海，充满生命的活力。以下，诗人又展开其丰富的想象，进一步描绘了大海吞吐日月、包蕴星汉的宏伟气魄和博大胸怀。“日月之行，若出其中；星汉灿烂，若出其里。”日月的运行好像出没于大海的怀抱之中，灿烂的银河群星好像包孕于大海的母腹之内。请看，这就是大海的气魄，大海的胸怀。真是太壮观、太奇伟了。 《观沧海》是一首写景抒情诗。诗人勾画了大海吞吐日月、包蕴万千的壮丽景象，表现了开阔的胸襟，抒发了统一中原建功立业的抱负。虽然其中并无直抒胸臆的感慨之词，但是诵读全诗，仍能令人感到它所深深寄托的诗人的情怀。通过诗人对波涛汹涌、吞吐日月的大海的生动描绘，使我们仿佛看到了曹操奋发进取，立志统一国家的伟大抱负和壮阔胸襟，触摸到了作为一个诗人、政治家、军事家的曹操，在一种典型环境中思想感情的流动。全诗语言质朴，想象丰富，气势磅礴，苍凉悲壮，为历代读者所激赏。沈德潜在《古诗源》中评论此诗“有吞吐宇宙气象”。这是很精当的。\n\n　　汉代乐府诗一般无标题，“观沧海”这个题目是后人加的。乐府诗原来是可以歌唱的，诗的最后两句“幸甚至哉！歌以咏志.”是和乐时加的，是诗的附文，跟诗的内容没有联系。', poem_tags = '古诗三百首,初中古诗,乐府,写景,抒情,抱负' WHERE poem_title = '观沧海' AND poem_author = '曹操';
UPDATE edu_poem SET poem_translation = '好雨似乎会挑选时辰，降临在万物萌生之春。\n伴随和风，悄悄进入夜幕。细细密密，滋润大地万物。\n浓浓乌云，笼罩田野小路，点点灯火，闪烁江上渔船。\n明早再看带露的鲜花，成都满城必将繁花盛开。', poem_notes = '知：明白，知道。说雨知时节，是一种拟人化的写法。\n乃：就。发生：萌发生长。\n发生：萌发生长。\n潜（qián）：暗暗地，悄悄地。这里指春雨在夜里悄悄地随风而至。\n润物：使植物受到雨水的滋养。\n野径：田野间的小路。\n晓：天刚亮的时候。红湿处：雨水湿润的花丛。\n红湿处：指有带雨水的红花的地方。\n花重：花沾上雨水而变得沉重。\n重：读作zhòng（重在这里的意思是：沉重。所以读作第四声。）\n锦官城：成都的别称。', poem_appreciation = '平常之景最为难写，能写难状之景如在目前，且如此真切入微，令人如临其境，只有大诗人能够做到。这是一首五律。前两联用流水对，把春雨的神韵一气写下，末联写一种骤然回首的惊喜，格律严谨而浑然一体。诗人是按先“倾耳听雨“、再“举首望雨“、后“闭目想象“的过程和角度，去表现春夜好雨的。诗从听觉写至视觉，乃至心理感觉，从当夜想到清晨，结构严谨，描写细腻;语言锤炼精工;巧妙地运用了拟人、对比等具有较强表现力的艺术手法。诗中句句绘景，句句写情，不用喜悦欢愉之类词汇，却处处透露出喜悦的气息、明快的情调。《瀛奎律髓汇评》引纪昀语:“此是名篇，通体精妙，后半尤有神。“\n\n　　在择韵上，诗人以韵就情，他选择的“庚“韵，是后鼻韵母，其发音过程较长，客观上拖慢了整首诗涵咏的时间和语调，这恰恰宜于表达诗中喜悦而不冲动、醇厚而不奔放的绵长细腻的情感。', poem_tags = '小学古诗,春天,咏物,写雨,喜悦,早教古诗100首' WHERE poem_title = '春夜喜雨' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '风和烟都消散了，天和山变成相同的颜色。（我乘着船）随着江流漂荡，随意的向东或向西漂流。从富阳到桐庐，一百里左右，奇异的山，灵异的水，天下独一无二的。\n\n　　水都是青白色的，清澈的水千丈也可以看见底。游动的鱼儿和细小的石头，可以直接看见，毫无障碍。湍急的水流比箭还快，凶猛的巨浪就像奔腾的骏马。\n\n　　夹江两岸的高山上，都生长着密而绿的树，高山凭依着高峻的山势，争着向上，这些高山彼此都争着往高处和远处伸展；群山竞争着高耸，笔直地向上形成了无数个山峰。泉水飞溅在山石之上，发出清悦泠泠的响声；美丽的鸟相互和鸣，鸣声嘤嘤，和谐动听。蝉儿长久地叫个不停，猿猴长时间地叫个不停。像凶猛的鸟飞到天上为名利极力追求高位的人，看到这些雄奇的高峰，追逐功名利禄的心也就平静下来。那些整天忙于政务的人，看到这些幽美的山谷，就会流连忘返。横斜的树枝在上面遮蔽着，即使在白天，也像黄昏时那样阴暗；稀疏的枝条交相掩映，有时也可以见到阳光。', poem_notes = '书：是古代的一种文体。\n风烟俱净：烟雾都消散尽净。风烟，指烟雾。俱，全，都。净，消散尽净。\n共色：一样的颜色。共，一样。\n从流飘荡：乘船随着江流漂荡。从，顺，随。\n任意东西：情境任凭船按照自己的意愿，时而向东，时而向西。东西，方向，在此做动词，向东漂流，向西漂流。\n自：从。\n至：到。\n许：表示大约的数量，上下，左右。\n独绝：独一无二。独，只。绝，绝妙。\n皆：全，都。\n缥（piǎo）碧：原作“漂碧”，据其他版本改为此，青白色。\n游鱼细石：游动的鱼和细小的石头。\n直视无碍：一直看下去，可以看得很清楚，毫无障碍。这里形容江水清澈见底。\n急湍（tuān）：急流的水。急，迅速，又快又猛。湍，水势急速。\n甚箭：“甚于箭”，比箭还快。甚，胜过，超过。为了字数整齐，中间的“于”字省略了。\n若：好像。\n奔：动词活用作名词，文中指飞奔的骏马。\n寒树：使人看了有寒意的树，形容树密而绿。\n负势竞上：高山凭依高峻的地势，争着向上。负，凭借。竞，争着。上，向上。这一句说的是“高山”，不是“寒树”，这从下文“千百成峰”一语可以看得出来。\n轩邈（miǎo）：意思是这些高山仿佛都在争着往高处和远处伸展。轩，向高处伸展。邈，向远处伸展。这两个词在这里形容词活用为动词用。\n直指：笔直地向上，直插云天。指，向，向上。\n千百成峰：意思是形成无数山峰。\n激：冲击，拍打。\n泠（líng）泠作响：泠泠地发出声响。泠泠，拟声词，形容水声的清越。\n好：美丽的。\n相鸣：互相和鸣，互相鸣叫。\n嘤（yīng）嘤成韵：鸣声嘤嘤，和谐动听。嘤嘤，鸟鸣声。韵，和谐的声音。\n蝉则千转（zhuàn）不穷：蝉儿长久不断地鸣叫。则，助词，没有实在意义。千转：长久不断地叫。千，表示多，“千”与下文“百”都表示很多。转，通“啭”鸟鸣声。这里指蝉鸣。穷，穷尽。\n无绝：就是“不绝”。与上句中的“不穷”相对。绝，停止。\n鸢（yuān）飞戾（lì）天：出自《诗经·大雅·旱麓》。老鹰高飞入天，这里比喻追求名利极力攀高的人。鸢，俗称老鹰，善高飞，是一种凶猛的鸟。戾，至。\n望峰息心：意思是看到这些雄奇的山峰，追逐名利的心就会平静下来。息，使……平息，使动用法。\n经纶（lún）世务者：治理社会事务的人。经纶，筹划、治理。世务，政务。\n窥谷忘反：看到这些幽美的山谷，就会流连忘返。窥，看。反，通“返”，返回。\n横柯（kē）上蔽：横斜的树木在上面遮蔽着。柯，树木的枝干。上，方位名词作状语，在上面。蔽，遮蔽。\n在昼犹昏：在白天，也好像黄昏时那样阴暗。昼，白天。犹，好像。\n疏条交映：稀疏的枝条互相掩映。疏条，稀疏的小枝。交映，互相遮掩。交，相互。\n见：看见。\n日：太阳，阳光。', poem_appreciation = '江山如此多娇，引无数文人墨客，吟诗作文，为后人留下了众多脍炙人口的山水佳作。其中，南朝梁文学家吴均的《与朱元思书》，这是一篇山水小品，作者以简练明快的笔墨，描绘了一幅充满生机的大自然画卷，且仅用一百四十四字便生动逼真地描绘出富春江沿途的绮丽风光，被视为骈文中写景的精品。吟诵此文，但觉景美、情美、词美、章美，如此短的篇幅，却给人以美不胜收之感，令人叹为观止。阅读时要注意作者是怎样抓住山光水色的特点模山范水的。\n\n意境美 　　文章开篇以简洁的笔触，给人们勾画了富春江山水的背景：阳光明媚，天高云淡，空气清新，山色苍翠，并总述自富阳至桐庐水上之游的总体印象：“奇山异水，天下独绝”。 第二段写“异水”。先抓住其“缥碧”的特点，写出了其晶莹清澈的静态美：这水仿佛透明似的，可以一眼见底，连那倏来忽去的游鱼，水底累累的细石，都可以一览无余。然后以比喻夸张的手法，勾勒其急湍猛浪的动态美：这水有时又迅猛奔腾，一泻千里，使人感到惊心动魄。这样描写，静中有动，动静结合，显示出了富春江水的秀丽之美和壮观之美，突出地表现了一个“异”字。 　　第三段写“奇特的山”。首先从形的角度写山势本身之奇，奇在“负势竞上”、“争高直指”。山本是静止的，而在作者笔下，却仿佛有无穷的奋发向上的生命力，它们仿佛要挣脱大地，直上青天，欲上不能，便“千百成峰”，层峦叠嶂。其次从声的角度写空山天籁之奇。空山幽谷之中，泉水叮咚，百鸟和鸣，知了叫个不停，猿猴啼个不住，这些欢快的声音，汇成一曲对生命的颂歌，把这寂静的山谷，变成一个热闹、和谐、欢乐、祥和的世界。山包容了这些生命，这些生命给这山以无限生气。再次从色的角度写山林中有日无光之奇。山外虽然晴光万里，山中却别有景象。作者笔锋又从动到静，写出了谷中枝密林茂，浓荫蔽目，在白天也只是“有时见日”的幽暗的景象。这一段写山之形之声之色，都紧扣一个“奇”字。 　　作者抓住此山此水特征，把动与静、声与色、光与影巧妙结合，为读者描绘出一幅充满生命力的山水图，让读者充分享受到了富春江两岸的“山川之美”。\n\n志趣美 　　该文重在写景，直接抒情写志的语言很少。但历来优秀的文章都讲究情景相生，人们可从作者对景物的描写中，从寥寥几句写观感的语句中，领略到作者高雅的志趣、高洁的情怀。可以从首段“从流飘荡，任意东西”一句中，感受到一种享受自由、无拘无束、无牵无挂的轻松惬意；从对山水的描写中，体会到作者对自然、自由的热爱，对生命力的赞颂。更令人赞赏的是，在描绘山景时，作者插入两句观感：“鸢飞戾天者，望峰息心；经纶世务者，窥谷忘反”。这几句感受，不仅从侧面衬托出险峰幽谷的夺人心魄的魅力，更是传达出作者对功名利禄的鄙弃，对官场政务的厌倦。 　　细细品味，作者的这种志趣，既不同于“知其不可而为之”的积极入世，又不同于“采菊东篱下，悠然见南山”的消极遁世，它是一种对轻松自然的崇尚，对自由和谐的向往，对欢乐生命的礼赞。它比前者少了份严肃，多了份潇洒，比后者少了份悲观，多了份开朗，因而更具一份常人心态，也就更容易使人接受并感到亲切。\n\n语言美 　　本文是用骈体写成的一篇山水小品。骈文常用四字六字组织，故亦称“四六文”。本文只140多个字。作者用清新的笔调和形象的描绘，把他从富春江富阳到桐庐一段看到的山光水色告诉了他的朋友，让朋友分享富春山川之美。 　　骈（pián）文是一种讲究形式的文体，作者吴均是南朝知名骈文家，其代表作《与朱元思书》自然保持了骈文的特点。文章基本上遵循骈文的要求，主要采用四字句和六字句，并于文章后半部分大量运用对偶句， 如“泉水激石，泠泠作响；好鸟相鸣，嘤嘤成韵”、 “蝉则千转不穷，猿则百叫无绝”。这就取得了句式整齐、音韵和谐、对比立意、相映成趣的表达效果，读来朗朗上口，节奏感极强。 　　但文章又有异于当时一般的骈文，它在一定程度上打破了骈文形式上的束缚，体现了可贵的突破与创新。其一，在四字句、六字句中运用了“鸢飞戾天者，望峰息心；经纶世务者，窥谷忘反”这样的五字与四字交替运用的句式，这就避免了骈文刻板划一的弊病，使语言显得活泼洒脱；其二，文章前半部分几乎没有对偶，无异于一般散文( 尤其是第一节)，后半部分则基本上都是工整的对偶句，这样骈散结合、疏密相间的安排， 使语言灵活多变，更具韵律美；其三，文章没有像一般骈文那样堆砌典故，甚至故意用冷字僻字，写景状物，力求准确传神，这使文章语言显得清新自然，生动流畅，在当时以绮丽浮靡为主流的骈文中显得卓尔不群，超凡脱俗。\n\n结构美 　　《与朱元思书》篇幅虽短，但很讲究章法。 　　文章首段以“奇山异水， 天下独绝”八字总领全篇，二、三两段分承“异水”和“奇山”两方面，环绕“独绝”二字展开生发和描摹，结构上纲举目张，脉络分明。 写景顺序上先“水”后“山”，由近及远，逐层展开，符合“从流飘荡”的观景习惯，条理清楚。 　　写景重点上， 全文详写“山”略写“水”；写“水”的部分，详写静态略写动态；写“山”的部分，详写动态略写静态。这样既突出景物主要特征，又显得详略适宜，轻重有度。 　　读《与朱元思书》，如读一首好诗，因为它不仅有词采隽永、音节和谐的诗一般的语言，更洋溢着清新淡雅的诗情；读《与朱元思书》，如赏一幅山水写意，因为它有特色鲜明的景物，更有明朗洒脱的画意。总之，该文情景兼美，辞章俱佳，能给人以美的享受、心灵的愉悦。\n\n文学结构：骈（pián） 　　也称“骈体文”、“骈俪文”或“骈偶文”；因其常用四字、六字句，故也称“四六文”或“骈四俪六”。中国古代魏晋以后产生的一种文体。又称骈俪文。南北朝是骈体文的全盛时期。全篇以双句（俪句、偶句）为主，讲究对仗的工整和声律的铿锵。中国的散文从汉代到六朝，出现了“文”、“笔”的对立。所谓“文”，就是专尚辞藻华丽，受字句和声律约束的骈文。所谓“笔”，就是专以达意明快为主，不受字句和声律约束的散文。(此处所述不当。据刘勰《文心雕龙 总述》引录颜延之观点称：笔之为体，言之为文也；经典则言而非笔，传记则笔而非言。而刘勰本人的观点是：“今之常言，有文有笔，以为无韵者笔也，有韵者文也”可见发生于宋齐时期的文笔之辩着眼点在于有韵与否，而非散文骈体之别。而况，南北朝时期的散文也多有押韵，故加修正。) 　　魏晋以来产生的一种文体，又称骈俪文。骈文是与散文相对而言的。其主要特点是以四六句式为主，讲究对仗，因句式两两相对，犹如两马并驾齐驱，故被称为骈体。在声韵上，则讲究运用平仄，韵律和谐；修辞上注重藻饰和用典。由于骈文注重形式技巧，故内容的表达往住受到束缚，但运用得当，也能增强文章的艺术效果。而南北朝时期，亦不乏内容深刻的作品，如庾信的《哀江南赋》，他一方面描写了自己身世之悲，一方面则谴责了梁朝君臣的昏庸，表达对故国怀念之情。唐以后。骈文的形式日趋完善，出现了通篇四、六句式的骈文，所以宋代一般又称骈文为四六文。直至清末，骈文仍十分流行。 　　文笔分裂后，骈文就成为和散文相对举的一种文体。骈文盛行于六朝，代表作家有徐陵、庾信。中唐古文运动以后，稍告衰落。在元明两代成为绝响。至清初，作者接踵而起，以清末王闿运为最后一个作家。\n\n总概句 　　奇山异水，天下独绝。\n\n情感 　　1、淡薄名利，流连山水。 　　2、劝友归林。（友：指朱元思）', poem_tags = '初中文言文,书信,写景,山水' WHERE poem_title = '与朱元思书' AND poem_author = '吴均';
UPDATE edu_poem SET poem_translation = '鲁庄公十年的春天，齐国军队攻打我们鲁国。鲁庄公将要迎战。曹刿请求拜见鲁庄公。他的同乡说：“当权的人自会谋划这件事，你又何必参与呢？”曹刿说：“当权的人目光短浅，不能深谋远虑。”于是入朝去见鲁庄公。曹刿问：“您凭借什么作战？”鲁庄公说：“衣食（这一类）养生的东西，我从来不敢独自专有，一定把它们分给身边的大臣。”曹刿回答说：“这种小恩小惠不能遍及百姓，老百姓是不会顺从您的。”鲁庄公说：“祭祀用的猪牛羊和玉器、丝织品等祭品，我从来不敢虚报夸大数目，一定对上天说实话。”曹刿说：“小小信用，不能取得神灵的信任，神灵是不会保佑您的。”鲁庄公说：“大大小小的诉讼案件，即使不能一一明察，但我一定根据实情（合理裁决）。”曹刿回答说：“这才尽了本职一类的事，可以（凭借这个条件）打一仗。如果作战，请允许我跟随您一同去。”\n\n　　到了那一天，鲁庄公和曹刿同坐一辆战车，在长勺和齐军作战。鲁庄公将要下令击鼓进军。曹刿说：“现在不行。”等到齐军三次击鼓之后。曹刿说：“可以击鼓进军了。”齐军大败。鲁庄公又要下令驾车马追逐齐军。曹刿说：“还不行。”说完就下了战车，察看齐军车轮碾出的痕迹，又登上战车，扶着车前横木远望齐军的队形，这才说：“可以追击了。”于是追击齐军。\n\n　　打了胜仗后，鲁庄公问他取胜的原因。曹刿回答说：“作战，靠的是士气。第一次击鼓能够振作士兵们的士气。第二次击鼓士兵们的士气就开始低落了，第三次击鼓士兵们的士气就耗尽了。他们的士气已经消失而我军的士气正旺盛，所以才战胜了他们。像齐国这样的大国，他们的情况是难以推测的，怕他们在那里设有伏兵。后来我看到他们的车轮的痕迹混乱了，望见他们的旗帜倒下了，所以下令追击他们。”', poem_notes = '曹刿（guì）：春秋时鲁国大夫。著名的军事理论家。\n十年：鲁庄公十年（公元前684年）。\n齐师：齐国的军队。齐，在今山东省中部。师，军队。\n伐：攻打。\n我：指鲁国。《左传》根据鲁史而写，故称鲁国为“我”。\n公：诸侯的通称，这里指鲁庄公。\n肉食者：吃肉的人，指当权者。\n谋：谋议。\n间（jiàn）：参与。\n鄙：鄙陋，目光短浅。\n乃：于是，就。\n何以战：就是“以何战”，凭借什么作战？以，用，凭，靠。\n衣食所安，弗敢专也：衣食这类养生的东西，不敢独自享用。安：有“养”的意思。弗：不。专：独自专有，个人专有。\n必以分人：省略句，省略了“之“，完整的句子是“必以之分人”。一定把它分给别人。以，把。人：指鲁庄公身边的近臣或贵族。\n遍：一作“徧”，遍及，普遍。\n牺牲玉帛（bó）：古代祭祀用的祭品。牺牲，祭祀用的猪、牛、羊等。玉，玉器。帛，丝织品。\n加：虚报夸大。\n小信未孚（fú）：（这只是）小信用，未能让神灵信服。孚，使人信服。\n福：名词作动词，赐福，保佑。\n狱：（诉讼）案件。\n察：明察。\n情：实情。\n忠之属也：这是尽了职分（的事情）。忠，尽力做好分内的事。属，种类。\n可以一战：就是“可以之一战”，可以凭借这个条件打一仗。可，可以。以，凭借。\n战则请从：（如果）作战，请允许（我）跟从去。从：随行，跟从。\n公与之乘：鲁庄公和他共坐一辆战车。之，指曹刿。\n长勺：鲁国地名，今山东莱芜东北。\n败绩：军队溃败。\n驰：驱车追赶。\n辙（zhé）：车轮碾出的痕迹。\n轼：古代车厢前做扶手的横木。\n遂：于是，就。\n逐：追赶，这里指追击。\n既克：已经战胜。既，已经。\n夫战，勇气也：作战，（是靠）敢作敢为毫不畏惧的气概。夫（fú），放在句首，表示将发议论，没有实际意义。\n一鼓作气：第一次击鼓能振作士气。作，振作。\n再：第二次。\n三：第三次。\n彼竭我盈：他们的勇气已尽，我们的勇气正盛。彼，代词，指齐军方面。盈，充沛，饱满，这里指士气旺盛。\n难测：难以推测。测，推测，估计。\n伏：埋伏。\n靡（mǐ）：倒下。\n曹刿论战：选自《左传·庄公十年》。题目是（教材编写者）后加的。', poem_appreciation = '战争题材在《左传》中写得最好，详略得当，而且都有声有色，这篇文章就是一例。曹刿论战以“肉食者鄙”即当官的见识浅薄，不能考虑周全为理论基础，而他的深谋远虑开始的出发点是鲁庄公能否以百姓利益为重，所以他并不看重鲁庄公对侍从施舍小恩惠和祭神的诚实，而非常注重鲁庄公以民情审判大大小小的案件，认为这属于对百姓忠心，可以一战。\n\n　　面对实力强大的齐国军队，曹刿没有贸然行事，当齐军三次击鼓进军，才建议击鼓，一鼓作气，战胜齐军于长勺，这件事也成为以弱胜强的典范。《左传》对这场战争没有细致的描绘，简单地用曹刿的“未可”“可矣”概括了战争的经过，以便使战前战后的论战更加突出。如果说战前论战体现了曹刿的以民为战争之本的基本战略思想，那么，战后论战则体现了他的战术思想，“一鼓作气”成为作战打仗的经典理论。不过他不是只凭借勇力，“夫大国难测也，惧有伏焉。吾视其辙乱，望其旗靡，故逐之”，则体现了他谨慎的态度。\n\n　　本文意在表现曹刿的“远谋”，故紧紧围绕“论战”来选取材料。第一段通过曹刿与鲁庄公的对话，强调人心向背是取决于战争胜负的首要条件，突出了曹刿“取信于民”的战略思想；第二段简述曹刿指挥鲁军进行反攻、追击和最后取得胜利的过程，显示曹刿的军事指挥才能，为下文分析取胜原因作伏笔；第三段论述取胜的原因，突出曹刿善于抓住战机，谨慎而又果断的战术思想。全文叙事清楚，详略得当，人物对话准确生动，要言不烦，是《左传》中脍炙人口的名篇。', poem_tags = '初中文言文,古文观止,对话,赞美,写人' WHERE poem_title = '曹刿论战' AND poem_author = '左丘明';
UPDATE edu_poem SET poem_translation = '这里是汉代的豫章郡城，如今是洪州的都督府，天上的方位属于翼，轸两星宿的分野，地上的位置连结着衡山和庐山。以三江为衣襟，以五湖为衣带、控制着楚地，连接着闽越。物类的精华，是上天的珍宝，宝剑的光芒直冲上牛、斗二星的区间。人中有英杰，因大地有灵气，陈蕃专为徐孺设下几榻。雄伟的洪州城，房屋像雾一般罗列，英俊的人才，像繁星一样地活跃。城池座落在夷夏交界的要害之地，主人与宾客，集中了东南地区的英俊之才。都督阎公，享有崇高的名望，远道来到洪州坐镇，宇文州牧，是美德的楷模，赴任途中在此暂留。正逢十日休假的日子，杰出的友人云集，高贵的宾客，也都不远千里来到这里聚会。文坛领袖孟学士，文章的气势像腾起的蛟龙，飞舞的彩凤，王将军的武库里，藏有像紫电、青霜这样锋利的宝剑。由于父亲在交趾做县令，我在探亲途中经过这个著名的地方。我年幼无知，竟有幸亲身参加了这次盛大的宴会。\n　　时当九月，秋高气爽。积水消尽，潭水清澈，天空凝结着淡淡的云烟，暮霭中山峦呈现一片紫色。在高高的山路上驾着马车，在崇山峻岭中访求风景。来到昔日帝子的长洲，找到仙人居住过的宫殿。这里山峦重叠，青翠的山峰耸入云霄。凌空的楼阁，红色的阁道犹如飞翔在天空，从阁上看不到地面。白鹤，野鸭停息的小洲，极尽岛屿的纡曲回环之势，雅浩的宫殿，跟起伏的山峦配合有致。\n　　打开雕花精美的阁门，俯视彩饰的屋脊，山峰平原尽收眼底，湖川曲折令人惊讶。遍地是里巷宅舍，许多钟鸣鼎食的富贵人家。舸舰塞满了渡口，尽是雕上了青雀黄龙花纹的大船。正值雨过天晴，虹消云散，阳光朗煦，落霞与孤雁一起飞翔，秋水和长天连成一片。傍晚渔舟中传出的歌声，响彻彭蠡湖滨，雁群感到寒意而发出的惊叫，鸣声到衡阳之浦为止。\n　　放眼远望，胸襟刚感到舒畅，超逸的兴致立即兴起，排箫的音响引来的徐徐清风，柔缓的歌声吸引住飘动的白云。像睢园竹林的聚会，这里善饮的人，酒量超过彭泽县令陶渊明，像邺水赞咏莲花，这里诗人的文采，胜过临川内史谢灵运。（音乐与饮食，文章和言语）这四种美好的事物都已经齐备，（良辰美景，赏心乐事）这两个难得的条件也凑合在一起了，向天空中极目远眺，在假日里尽情欢娱。苍天高远，大地寥廓，令人感到宇宙的无穷无尽。欢乐逝去，悲哀袭来，我知道了事物的兴衰成败是有定数的。西望长安，东指吴会，南方的陆地已到尽头，大海深不可测，北方的北斗星多么遥远，天柱高不可攀。关山重重难以越过，有谁同情不得志的人？萍水偶尔相逢，大家都是异乡之客．怀念着君王的宫门，但却不被召见，什么时候才能够去侍奉君王呢？\n　　呵，各人的时机不同，人生的命运多有不顺。冯唐容易衰老，李广难得封侯。使贾谊遭受委屈，贬于长沙，并不是没有圣明的君主，使梁鸿逃匿到齐鲁海滨，难道不是政治昌明的时代？只不过由于君子安于贫贱，通达的人知道自己的命运罢了。年纪虽然老了，但志气应当更加旺盛，怎能在白头时改变心情？境遇虽然困苦，但节操应当更加坚定，决不能抛弃自己的凌云壮志。即使喝了贪泉的水，心境依然清爽廉洁；即使身处于干涸的主辙中，胸怀依然开朗愉快。北海虽然十分遥远，乘着羊角旋风还是能够达到，早晨虽然已经过去，而珍惜黄昏却为时不晚。孟尝君心地高洁，但白白地怀抱着报国的热情，阮籍为人放纵不羁，我们怎能学他那种穷途的哭泣！\n　　我地位卑微，只是一个书生。虽然和终军一样年已二十一，却无处去请缨杀敌。我羡慕宗悫那种“乘长风破万里浪”的英雄气概，也有投笔从戎的志向。如今我抛弃了一生的功名，不远万里去朝夕侍奉父亲。虽然称不上谢家的“宝树”，但是能和贤德之士相交往。不久我将见到父亲，聆听他的教诲。今天我侥幸地奉陪各位长者，高兴地登上龙门。假如碰不上杨得意那样引荐的人，就只有抚拍着自己的文章而自我叹惜。既然已经遇到了钟子期，就弹奏一曲《流水》又有什么羞愧呢？\n　　呵！名胜之地不能常存，盛大的宴会难以再逢。兰亭宴集已为陈迹，石崇的梓泽也变成了废墟。承蒙这个宴会的恩赐，让我临别时作了这一篇序文，至于登高作赋，这只有指望在座诸公了。我只是冒昧地尽我微薄的心意，作了短短的引言。在座诸位都按各自分到的韵字赋诗，我已写成了四韵八句。请在座诸位施展潘岳，陆机一样的才笔，各自谱写瑰丽的诗篇吧！！\n　　巍峨高耸的滕王阁俯临着江心的沙洲，想当初佩玉、鸾铃鸣响的豪华歌舞已经停止了。\n　　早晨，画栋飞上了南浦的云；黄昏，珠帘卷入了西山的雨。\n　　悠闲的彩云影子倒映在江水中，整天悠悠然地漂浮着；时光易逝，人事变迁，不知已经度过几个春秋。\n　　昔日游赏于高阁中的滕王如今已不知哪里去了，只有那栏杆外的滔滔江水空自向远方奔流。', poem_notes = '豫章：滕王阁在今江西省南昌市。南昌，为汉豫章郡治。唐代宗当政之后，为了避讳唐代宗的名（李豫），“豫章故郡”被替换为“南昌故郡”。所以现在滕王阁内的石碑以及苏轼的手书都作“南昌故郡”。\n故：以前的。\n洪都：汉豫章郡，唐改为洪州，设都督府。\n星分翼轸：古人习惯以天上星宿与地上区域对应，称为“某地在某星之分野”。据《晋书·天文志》，豫章属吴地，吴越扬州当牛斗二星的分野，与翼轸二星相邻。翼、轸，星宿名，属二十八宿。\n衡：衡山，此代指衡州（治所在今湖南省衡阳市）。\n庐：庐山，此代指江州（治所在今江西省九江市）。\n襟：以……为襟。因豫章在三江上游，如衣之襟，故称。\n三江：太湖的支流松江、娄江、东江，泛指长江中下游的江河。\n带：以……为带。五湖在豫章周围，如衣束身，故称。\n五湖：一说指太湖、鄱阳湖、青草湖、丹阳湖、洞庭湖，又一说指菱湖、游湖、莫湖、贡湖、胥湖，皆在鄱阳湖周围，与鄱阳湖相连。以此借为南方大湖的总称。\n蛮荆：古楚地，今湖北、湖南一带。\n引：连接。\n瓯越：古越地，即今浙江地区。古东越王建都于东瓯（今浙江省永嘉县），境内有瓯江。\n物华天宝：地上的宝物焕发为天上的宝气。\n龙光射牛斗之墟：龙光，指宝剑的光辉。牛、斗，星宿名。墟、域，所在之处。据《晋书·张华传》，晋初，牛、斗二星之间常有紫气照射。张华请教精通天象的雷焕，雷焕称这是宝剑之精，上彻于天。张华命雷焕为丰城令寻剑，果然在丰城（今江西省丰城市，古属豫章郡）牢狱的地下，掘地四丈，得一石匣，内有龙泉、太阿二剑。后这对宝剑入水化为双龙。\n杰：俊杰，豪杰。灵：灵秀。\n徐孺：徐孺子的省称。徐孺子名稚，东汉豫章南昌人，当时隐士。据《后汉书·徐稚传》，东汉名士陈蕃为豫章太守，不接宾客，惟徐稚来访时，才设一睡榻，徐稚去后又悬置起来。\n雄：雄伟。州：大洲。\n雾列：雾，像雾一样，名词作状语。喻浓密、繁盛，雾列形容繁华。“星”的用法同“雾”\n采：“采”同“寀”，官员，这里指人才。\n枕：占据，地处。尽：都是。\n东南之美：泛指各地的英雄才俊。《诗经-尔雅-释地》：“东南之美，有会稽之竹箭；西南之美，有华山之金石。”会稽就是今天的绍兴，后用“东箭南金” 泛指各地的英雄才俊。\n都督：掌管督察诸州军事的官员，唐代分上、中、下三等。\n阎公：阎伯屿，时任洪州都督。\n雅望：崇高声望。\n棨戟：外有赤黑色缯作套的木戟，古代大官出行时用。这里代指仪仗。\n遥临：远道来临。\n宇文新州：复姓宇文的新州（在今广东境内）刺史，名未详。\n懿范：好榜样。\n襜帷：车上的帷幕，这里代指车马。\n暂驻：暂时停留。\n十旬休假：唐制，十日为一旬，遇旬日则官员休沐，称为“旬休”。\n胜友：才华出众的友人\n腾蛟起凤：宛如蛟龙腾跃、凤凰起舞，形容人很有文采。《西京杂记》：“董仲舒梦蛟龙入怀，乃作《春秋繁露》。”又：“扬雄著《太玄经》，梦吐凤凰集《玄》之上，顷而灭。”\n孟学士：名未详。学士是朝廷掌管文学撰著的官员。\n词宗：文坛宗主。也可能是指南朝文学家、史学家沈约。\n紫电青霜：《古今注》：“吴大皇帝（孙权）有宝剑六，二曰紫电。”《西京杂记》：“高祖（刘邦）斩白蛇剑，刃上常带霜雪。”《春秋繁露》亦记其事。\n王将军：王姓的将军，名未详。\n武库：武器库。也可能是指西晋军事家杜预，即杜武库。\n家君作宰：王勃之父担任交趾县的县令。\n路出名区：（自己因探望父亲）路过这个有名的地方（指洪州）。出：过。\n童子何知，躬逢胜饯：年幼无知，（却有幸）参加这场盛大的宴会。\n维：在。又有一说此字为语气词，不译。\n序：时序（春夏秋冬）\n三秋：古人称七、八、九月为孟秋、仲秋、季秋，三秋即季秋，九月。\n此句被前人誉为“写尽九月之景”。\n潦水：雨后的积水。\n尽：没有\n俨：整齐的样子。\n骖騑：驾车的马匹。\n上路：高高的道路。\n访：看\n崇阿：高大的山陵。\n临、得：到。\n帝子、天人：都指滕王李元婴。有版本为“得仙人之旧馆”。\n长洲：滕王阁前赣江中的沙洲。\n旧馆：指滕王阁\n层：重叠。上：上达。\n飞阁流丹：飞檐涂饰红漆。有版本为“飞阁翔丹”。（新课改上对“流丹”给出的注解是：朱红的漆彩鲜艳欲滴）\n飞阁：架空建筑的阁道\n流：形容彩画鲜艳欲滴\n丹：丹漆，泛指彩绘\n临：从高处往下探望。\n鹤汀凫渚：鹤所栖息的水边平地，野鸭聚处的小洲。\n汀：水边平地\n凫：野鸭\n渚：水中小洲\n萦回：曲折\n即冈峦之体势：依着山岗的形式（而高低起伏）。\n桂，兰：两种名贵的树，形容宫殿的华丽，讲究\n披：开\n绣闼：绘饰华美的门。\n雕甍：雕饰华美的屋脊。\n旷：辽阔\n盈视：极目远望，满眼都是\n纡：迂回曲折\n骇瞩：对所见的景物感到惊骇。\n闾阎：里门，这里代指房屋。\n扑：满\n钟鸣鼎食：古代贵族鸣钟列鼎而食，所以用钟鸣鼎食指代名门望族。\n舸：船《方言》：“南楚江、湘，凡船大者谓之舸。”\n弥：满。\n青雀黄龙：船的装饰形状，船头作鸟头型，龙头型。\n舳：船尾把舵处，这里代指船只。\n销：“销”通“消”，消散。\n霁：雨过天晴\n彩：日光。\n区：天空。\n彻：通贯。\n化用庾信《马射赋》：“落花与芝盖同飞，杨柳共春旗一色。”\n一说，“霞”为一种小飞蛾，“落“的意思为孤单，孤单的飞蛾与孤独的野鸭一起飞翔，自有一种孤寂之情。\n(宋代吴曾《能改斋漫录.变霞鹜》）\n穷：穷尽，引申为“直到”。\n彭蠡：古代大泽，即今鄱阳湖。\n衡阳：今属湖南省，境内有回雁峰，相传秋雁到此就不再南飞，待春而返。\n断：止\n浦：水边、岸边。\n登高望远，胸怀顿时舒畅，超逸的兴致迅速升起。\n遥：远望。襟：胸襟。甫：顿时。畅：舒畅。\n兴：兴致。遄：迅速。\n爽籁：清脆的排箫音乐。籁，管子参差不齐的排箫。\n遏：阻止，引申为“停止”。\n白云遏：形容音响优美，能驻行云。《列子·汤问》：“薛谭学讴于秦青，未穷青之技，自谓尽之，遂辞归。秦青弗止，饯于郊衢。抚节悲歌，声振林木，响遏行云。”\n睢园绿竹：睢园，即汉梁孝王菟园，梁孝王曾在园中聚集文人饮酒赋诗。《水经注》：“睢水又东南流，历于竹圃……世人言梁王竹园也。”\n凌：超过。\n彭泽：县名，在今江西湖口县东，此代指陶潜。陶潜，即陶渊明，曾官彭泽县令，世称陶彭泽。\n樽：酒器。陶渊明《归去来兮辞》有“有酒盈樽”之句。\n睢园绿竹，气凌彭泽之樽：今日盛宴好比当年梁园雅集，大家酒量也胜过陶渊明。\n邺水：在邺下（今河北省临漳县）。邺下是曹魏兴起的地方，三曹常在此雅集作诗。曹植在此作《公宴诗》。\n朱华：荷花。曹植《公宴诗》：“秋兰被长坂，朱华冒绿池。”\n光照临川之笔：临川，郡名，治所在今江西省抚州市，代指即谢灵运。谢灵运曾任临川内史，《宋书》本传称他“文章之美，江左莫逮”。\n四美：指良辰、美景、赏心、乐事。另一说，四美：音乐、饮食、文章、言语之美。刘琨《答卢谌诗》：“音以赏奏，味以殊珍，文以明言，言以畅神。之子之往，四美不臻。”\n二难：指贤主、嘉宾难得。谢灵运《拟魏太子邺中集诗序》：“天下良辰、美景、赏心、乐事，四者难并。”王勃说“二难并”活用谢文，良辰、美景为时地方面的条件，归为一类；赏心、悦目为人事方面的条件，归为一类。\n睇眄：看。\n中天：长天。\n穷睇眄于中天：极目远望天空\n宇宙：喻指天地。《淮南子·原道训》高诱注：“四方上下曰‘宇’，古往来今曰‘宙’。”\n迥：大\n盈虚：消长，指变化。\n数：定数，命运。\n识盈虚之有数：知道万事万物的消长兴衰是有定数的。\n吴会(kuài)：古代绍兴的别称，绍兴古称吴会、会稽，是三吴之首（吴会、吴郡、吴兴），唐代绍兴是国际大都市，与长安齐名。同时期的诗人宋之问也有意思相近的一首诗：”薄游京都日，遥羡稽山名“。\n《世说新语·排调》：荀鸣鹤、陆士龙二人未相识，俱会张茂先坐。张令共语。以其并有大才，可勿作常语。陆举手曰：“云间陆士龙。”荀答曰：“日下荀鸣鹤。”\n《古代汉 语》解释:“陆云,字士龙,三国吴承相陆逊 孙。陆逊封华亭侯,陆氏世居华亭。华亭古 称‘云间’。荀隐,颖川人。颖川,地近京城。 后以‘日下’喻‘京都’。”\n字面意思是：远望长安在夕阳下,遥看吴越在云海间。\n南溟：南方的大海。事见《庄子·逍遥游》。\n天柱：传说中昆仑山高耸入天的铜柱。《神异经》：“昆仑之山，有铜柱焉。其高入天，所谓天柱也。”\n北辰：北极星，比喻国君。《论语·为政》：“为政以德，譬如北辰，居其所而众星共（拱）之。”\n关山：险关和高山。\n悲：同情,可怜\n失路：仕途不遇。\n萍水相逢：浮萍随水漂泊，聚散不定。比喻向来不认识的人偶然相遇。\n帝阍：天帝的守门人。屈原《离骚》：“吾令帝阍开关兮，倚阊阖而望予。”此处借指皇帝的宫门\n奉宣室，代指入朝做官。贾谊迁谪长沙四年后，汉文帝复召他回长安，于宣室中问鬼神之事。宣室，汉未央宫正殿，为皇帝召见大臣议事之处。\n命途：命运\n齐（qí）：整齐，平坦，与......一致。\n不齐：就是坎坷，坑坑洼洼。王勃是指自己的仕途之路不是很顺利，怀才不遇。后有“时运不济”一词乃出自于此，实乃后人误以为是通假字而杜撰之，以讹传讹，何可胜道！《礼记·学记》便有“大时不齐”一词！\n冯唐易老：冯唐在汉文帝、汉景帝时不被重用，汉武帝时被举荐，已是九十多岁。《史记·冯唐列传》：“（冯）唐以孝著，为中郎署长，事文帝。……拜唐为车骑都尉，主中尉及郡国车士。七年，景帝立，以唐为楚相，免。武帝立，求贤良，举冯唐。唐时年九十余，不能复为官。”\n李广难封：李广，汉武帝时名将，多次与匈奴作战，军功卓著，却始终未获封爵。\n屈贾谊于长沙：贾谊在汉文帝时被贬为长沙王太傅。\n圣主：指汉文帝，泛指圣明的君主。\n梁鸿：东汉人，作《五噫歌》讽刺朝廷，因此得罪汉章帝，避居齐鲁、吴中。\n明时：指汉章帝时代，泛指圣明的时代。\n机：“机”通“几”，预兆，细微的征兆。《易·系辞下》：“君子见几（机）而作。”\n达人知命：通达事理的人。《易·系辞上》：“乐天知命故不忧。”\n老当益壮：年纪虽大，但志气更旺盛，干劲更足。《后汉书·马援传》：“丈夫为志，穷当益坚，老当益壮。”\n坠：坠落，引申为“放弃”。\n青云之志：《续逸民传》：“嵇康早有青云之志。”\n酌贪泉而觉爽：贪泉，在广州附近的石门，传说饮此水会贪得无厌，吴隐之喝下此水操守反而更加坚定。据《晋书·吴隐之传》，廉官吴隐之赴广州刺史任，饮贪泉之水，并作诗说：“古人云此水，一歃怀千金。试使（伯）夷（叔）齐饮，终当不易心。”\n处涸辙：干涸的车辙，比喻困厄的处境。《庄子·外物》有鲋鱼处涸辙的故事。\n北海虽赊，扶摇可接：语意本《庄子·逍遥游》。\n东隅已逝，桑榆非晚：东隅，日出处，表示早晨，引申为“早年”。桑榆，日落处，表示傍晚，引申为“晚年”。早年的时光消逝，如果珍惜时光，发愤图强，晚年并不晚。《后汉书·冯异传》：“失之东隅，收之桑榆。”\n孟尝：据《后汉书·孟尝传》，孟尝字伯周，东汉会稽上虞人。曾任合浦太守，以廉洁奉公著称，后因病隐居。桓帝时，虽有人屡次荐举，终不见用。\n阮籍：字嗣宗，晋代名士，不满世事，佯装狂放，常驾车出游，路不通时就痛哭而返。《晋书·阮籍传》：籍“时率意独驾，不由径路。车迹所穷，辄恸哭而反。”\n三尺：衣带下垂的长度，指幼小。古时服饰制度规定束在腰间的绅的长度，因地位不同而有所区别，士规定为三尺。古人称成人为“七尺之躯”，称不大懂事的小孩儿为“三尺童儿”。\n微命：即“一命”，周朝官阶制度是从一命到九命，一命是最低级的官职。\n一介：一个。\n终军：据《汉书·终军传》，终军字子云，汉代济南人。武帝时出使南越，自请“愿受长缨，必羁南越王而致之阙下”，时仅二十余岁\n等：相同，用作动词。\n弱冠，古人二十岁行冠礼，表示成年，称“弱冠”。\n投笔：事见《后汉书·班超传》，用汉班超投笔从戎的故事。\n宗悫：据《宋书·宗悫传》，宗悫字元干，南朝宋南阳人，年少时向叔父自述志向，云“愿乘长风破万里浪”。后因战功受封。\n簪笏：冠簪、手版。官吏用物，这里代指官职地位。\n百龄：百年，犹“一生”。\n奉晨昏：侍奉父母。《礼记·曲礼上》：“凡为人子之礼……昏定而晨省。”\n非谢家之宝树：指谢玄，比喻好子弟。《世说新语·言语》：“谢太傅（安）问诸子侄‘子弟亦何预人事，而正欲使其佳？’诸人莫有言者。车骑（谢玄）答曰：‘譬如芝兰玉树，欲使其生于庭阶耳。’”\n接孟氏之芳邻：“接”通“结”，结交。见刘向《列女传·母仪篇》。据说孟轲的母亲为教育儿子而三迁择邻，最后定居于学宫附近。\n他日趋庭，叨陪鲤对：鲤，孔鲤，孔子之子。趋庭，受父亲教诲。《论语·季氏》：“（孔子）尝独立，（孔）鲤趋而过庭。（子）曰：‘学诗乎？’对曰：‘未也。’‘不学诗，无以言。’鲤退而学诗。他日，又独立，鲤趋而过庭。（子）曰：‘学礼乎？’对曰：‘未也。’‘不学礼，无以立。’鲤退而学礼。闻斯二者”\n捧袂：举起双袖，表示恭敬的姿势。\n喜托龙门：《后汉书·李膺传》：“膺以声名自高，士有被其容接者，名为登龙门。”\n杨意不逢，抚凌云而自惜：杨意，杨得意的省称。凌云，指司马相如作《大人赋》。据《史记·司马相如列传》，司马相如经蜀人杨得意引荐，方能入朝见汉武帝。又云：“相如既奏《大人》之颂，天子大悦，飘飘有凌云之气。”\n钟期即遇，奏流水以何惭：钟期，钟子期的省称。《列子·汤问》：“伯牙善鼓琴，钟子期善听。伯牙鼓琴……志在流水，钟子期曰：‘善哉！洋洋兮若江河。’”\n胜：名胜。不：不能。常：长存。难：难以。再：再次遇到。\n兰亭：位于中国绍兴。晋穆帝永和九年（353）三月三日上巳节，王羲之与群贤宴集于此，行修禊礼，祓除不祥。\n梓泽：即晋·石崇的金谷园，故址在今河南省洛阳市西北。\n临别赠言：临别时赠送正言以互相勉励，在此指本文。\n恭疏短引：恭敬地写下一篇小序，在此指本文。\n一言均赋：每人都写一首诗。\n四韵俱成：（我的）四韵一起写好了。四韵，八句四韵诗，指王勃此时写下的《滕王阁诗》：“滕王高阁临江渚，佩玉鸣鸾罢歌舞。画栋朝飞南浦云，珠帘暮卷西山雨。闲云潭影日悠悠，物换星移几度秋。阁中帝子今何在？槛外长江空自流。”\n请洒潘江，各倾陆海云尔：钟嵘《诗品》：“陆（机）才如海，潘（岳）才如江。”这里形容各宾客的文采。', poem_appreciation = '本文在构思上也有独到之处，文思缜密，层层扣题。各段衔接科学，思路清晰，由地及人，由人及景，由景及情，步步递进。全文充分发挥了骈文的特点，融对偶、声韵、用典于一炉，表现了比较丰富的内容，流露出作者的真情实感，具有很强的艺术感染力。\n\n　　第一节点题——第二节近境——第三节远近结合——第四节远境感悟——第五节抒怀励志——第六节自我介绍兼回收题意——第七节收篇致谢。\n\n　　这是一个由浅入深的问题。先通过点题，让读者明了当时所处的境况。接下去描写近境，以人的眼目为支点，由近至远，第二、三、四节也就顺理成章的现形出来了，这是一个层次感的问题。这样的处理，条理清楚，而且让人觉得自然。同样，抒怀也是如此，从第四节下半截浅述至第五节加深到第六节先深又转浅，到第七节不着痕迹的收篇。都是充满着层次感。', poem_tags = '咏史怀古,辞赋精选,高中文言文,古文观止,写景,抒情,典故,励志' WHERE poem_title = '滕王阁序' AND poem_author = '王勃';
UPDATE edu_poem SET poem_translation = '天边的明月升上了树梢，惊飞了栖息在枝头的喜鹊。清凉的晚风仿佛传来了远处的蝉叫声。在稻花的香气里，人们谈论着丰收的年景，耳边传来一阵阵青蛙的叫声，好像在说着丰收年。\n天空中轻云漂浮，闪烁的星星时隐时现，山前下起了淅淅沥沥的小雨，从前那熟悉的茅店小屋依然坐落在土地庙附近的树林中，山路一转，曾经那记忆深刻的溪流小桥呈现在他的眼前。', poem_notes = '西江月：词牌名。\n黄沙：黄沙岭，在江西上饶的西面。\n别枝惊鹊：惊动喜鹊飞离树枝。\n鸣蝉：蝉叫声。\n旧时：往日。\n茅店：茅草盖的乡村客店。\n社林：土地庙附近的树林。社，土地神庙。古时，村有社树，为祀神处，故曰社林。\n见：同“现”，显现，出现。', poem_appreciation = '明月别枝惊鹊 ， 清风半夜鸣蝉。\n\n　　词的前两句，由六个名词词组组成，描绘出了一幅清新的乡村夏日夜景：夜空晴朗，月亮悄悄升起，投下如水的月光，惊起了枝头的乌鹊；夜半时分，清风徐徐吹来，把蝉的鸣叫声也送了过来。以动衬静，表现了乡村夏夜的宁静和优美。\n\n　　喜鹊对光线的变化极其敏感，月上时分，它们常会被月光惊起，乱飞乱啼。曹操《短歌行》有“月明星稀，喜鹊南飞。绕树三匝，无枝可依”,苏轼《杭州牡丹》有“月明惊鹊未安枝”.\n\n　　首句中“别枝”之意，一直众说纷纭。有解作“远枝”;有解作“斜伸的树枝”;有解为“乌鹊要离开树枝飞走”;有解为“乌鹊拣选树枝”;还有人解为“月亮离别了树枝”.虽然难有定论，但从一二两句对偶考虑，“别枝”对应“半夜”,“别”字当是形容、修饰“枝”的，故解释为“远枝”或“斜伸的树枝”似乎更为恰当。\n\n　　词人虽是夜行，却似乎一点也不着急。我们仿佛看见他不紧不慢地行走在山路上，一会儿看看明月走到哪里了，一会儿听鸟啼蝉鸣，悠闲自得。此时的他，没有需要快马加鞭的紧急公务要处理，也不用为他人的指责、诽谤而彻夜难眠。虽然遭弹劾免职，胸中还有诸多愤懑愁苦，但美丽的自然和恬淡的乡村生活替他化解了部分的愤激之情。所以，在这美好的夏日夜晚，走在宁静的山间小路上，他已经完全沉浸于清风明月之中，融于天地。\n\n　　稻花香里说丰年，听取蛙声一片。\n\n　　路旁的稻田里，稻花飘香，预告着又一个丰年的到来。田里的青蛙也耐不住寂寞，阵阵叫声此起彼伏，连成一片，写出作者热爱自然，夏天的生机勃勃。\n\n　　七八个星天外，两三点雨山前。\n\n　　月光下，嗅着稻花的香味，听着蝉鸣蛙叫，轻松愉快的词人继续信步前行。抬头望空，“七八个星”挂在天边，稀稀落落，原来星星们都叫乌云给遮挡住了。突然，山前下起小雨来，“两三点雨”滴落到了词人身上。\n\n　　这一来，刚才还闲情逸致的词人不禁有些着急了。夏日的天，说变就变，也许一场倾盆大雨就会继之而来呢？他加快了脚步，赶着寻找避雨之所。\n\n　　旧时茅店社林边，路转溪桥忽见。\n\n　　从山岭小路转过弯，过了一座溪桥，就在土地庙旁的树林外，一座茅屋现在词人眼前。高兴的他细细一看，竟然就是从前落过脚的那家小店！“社”,土地庙附近的树林。', poem_tags = '宋词三百首,小学古诗,初中古诗,婉约,豪放,夏天,农村,' WHERE poem_title = '西江月·夜行黄沙道中' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '恼人的风雨停歇了，枝头的花朵落尽了，只有沾花的尘土犹自散发出微微的香气。抬头看看，日已高，却仍无心梳洗打扮。春去夏来，花开花谢，亘古如斯，唯有伤心的人、痛心的事，令我愁肠百结，一想到这些，还没有开口我就泪如雨下。\n听人说双溪的春色还不错，那我就去那里划划船，姑且散散心吧。唉，我真担心啊，双溪那叶单薄的小船，怕是载不动我内心沉重的忧愁啊！', poem_notes = '此词在《诗词杂俎本·漱玉词》、《类编草堂诗余》、《汇选历代名贤词府全集》、《文体明辨》、《古今名媛汇诗》、《词的》、《啸余集》、《古今女史》、《古今词统》、《古今诗余醉》、《历城县志》、《花镜隽声》、《见山亭古今词选》、《诗余神髓》、《古今图书集成》、《同情词集选》题作“春晚”，《彤管遗编》、《彤管摘奇》、《名媛玑隽》题作“暮春”，《词学筌蹄》题作“春暮”，《词汇》题作“春晓”，《词鹄》调作“武陵春第二体”。赵万里辑《漱玉词》云：“至正本《草堂诗余》前集上如梦令后接引此阕，不注撰人。玩意境颇似李作，姑存之。”（案明成化本、荆聚本、陈钟秀本、杨金本《草堂诗余》前集卷上，此首俱无撰人，与至正本同），《古今断肠词选》卷二又误以此首为马洪所作。\n“尘香”，落花触地，尘土也沾染上落花的香气。“花已尽”，《词谱》、清万树《词律》作“春已尽”。\n“日晚”，《花草粹编》作“日落”，《词谱》、《词汇》、清万树《词律》作“日晓”。\n“物是人非”，事物依旧在，人不似往昔了。三国曹丕《与朝歌令吴质书》：“节同时异，物是人非，我劳如何？”宋贺铸《雨中花》：“人非物是，半晌鸾肠易断，宝勒空回。”\n“泪先”，《彤管遗编》、《彤管摘奇》作“泪珠”，沈际飞《本草堂诗余》注：“一作珠，误”。《崇祯历城县志》作“欲泪先流”，误删“语”字。\n“闻说”，清叶申芗辑《天籁轩词选》作“闻道”。“春尚好”，明程明善辑《啸余谱》作“春向好”。“双溪”，水名，在浙江金华，是唐宋时有名的风光佳丽的游览胜地。有东港、南港两水汇于金华城南，故曰“双溪”。《浙江通志》卷十七《山川九》引《名胜志》：“双溪，在（金华）城南，一曰东港，一曰南港。东港源出东阳县大盆山，经义乌西行入县境，又汇慈溪、白溪、玉泉溪、坦溪、赤松溪，经石碕岩下，与南港会。南港源出缙云黄碧山，经永康、义乌入县境，又合松溪、梅溪水，绕屏山西北行，与东港会与城下，故名。”\n“拟”，准备、打算。“也拟”，也想、也打算。宋姜夔《点绛唇》：“第四桥边，拟共天随住。”辛弃疾《摸鱼儿》：“长门事，准拟佳期又误。”“轻舟”，《汇选历代名贤词府》、清陆昶《历朝名媛诗词》作“扁舟”。\n“舴艋”，小舟也，见《玉篇》及《广韵》。“舴艋舟”，小船，两头尖如蚱蜢。《艺文类聚》卷七一·南朝宋《元嘉起居注》：“余姚令何玢之造作平牀，乘船舴艋一艘，精丽过常。”唐张志和《渔夫》词：“钓台渔父褐为裘，两两三三舴艋舟”，又“霅溪湾里钓鱼翁，舴艋为家西复东。”宋《金奁集·黄钟宫·渔夫词（十五首）》：“舴艋为家无姓名，胡芦中有瓮头青。”元吴镇《渔夫》词：“舴艋为舟力几多。江头云雨半相和。”\n“载”，清万树《词律》：“《词统》、《词汇》俱注‘载’字是衬，误也。词之前后结，多寡一字者颇多，何以见其为衬乎？查坦庵作，尾句亦云‘流不尽许多愁’可证。沈选有首句三句，后第三句平仄全反者，尾云‘忽然又起新愁’者，“愁从酒畔生”者，奇绝！案：‘流不尽’句，见赵师侠《武陵春·信丰揖翠阁》词。赵师侠，又名师使，有《坦庵长短句》。”“载不动”句，宋郑文宝《杨柳词》：“不管烟波与风雨，载将离恨过江南。”', poem_appreciation = '这首词是宋高宗绍兴五年（1135）作者避难浙江金华时所作。当年她是五十三岁。那时，她已处于国破家亡之中，亲爱的丈夫死了，珍藏的文物大半散失了，自己也流离异乡，无依无靠，所以词情极其悲苦。\n\n　　首句写当前所见，本是风狂花尽，一片凄清，但却避免了从正面描写风之狂暴、花之狼藉，而只用“风住尘香”四字来表明这一场小小灾难的后果，则狂风摧花，落红满地，均在其中，出笔极为蕴藉。而且在风没有停息之时，花片纷飞，落红如雨，虽极不堪，尚有残花可见；风住之后，花已沾泥，人践马踏，化为尘土，所余痕迹，但有尘香，则春光竟一扫而空，更无所有，就更为不堪了。所以，“风住尘香”四字，不但含蓄，而且由于含蓄，反而扩大了容量，使人从中体会到更为丰富的感情。次句写由于所见如彼，故所为如此。日色已高，头犹未梳，虽与《凤凰台上忆吹箫》中“起来慵自梳头”语意全同，但那是生离之愁，这是死别之恨，深浅自别。\n\n　　三、四两句，由含蓄而转为纵笔直写，点明一切悲苦，由来都是“物是人非”。而这种“物是人非”，又决不是偶然的、个别的、轻微的变化，而是一种极为广泛的、剧烈的、带有根本性的、重大的变化，无穷的事情、无尽的痛苦，都在其中，故以“事事休”概括。这，真是“一部十七史，从何说起”？所以正要想说，眼泪已经直流了。\n\n　　前两句，含蓄；后两句，真率。含蓄，是由于此情无处可诉；真率，则由于虽明知无处可诉，而仍然不得不诉。故似若相反，而实则相成。\n\n　　上片既极言眼前景色之不堪、心情之凄楚，所以下片便宕开，从远处谈起。这位女词人是最喜爱游山玩水的。据周辉《清波杂志》所载，她在南京的时候，“每值天大雪，即顶笠、披蓑，循城远览以寻诗”。冬天都如此，春天就可想而知了。她既然有游览的爱好，又有需要借游览以排遣的凄楚心情，而双溪则是金华的风景区，因此自然而然有泛舟双溪的想法，这也就是《念奴娇》中所说的“多少游春意”。但事实上，她的痛苦是太大了，哀愁是太深了，岂是泛舟一游所能消释？所以在未游之前，就又已经预料到愁重舟轻，不能承载了。设想既极新颖，而又真切。下片共四句，前两句开，一转；后两句合，又一转；而以“闻说”、“也拟”、“只恐”六个虚字转折传神。双溪春好，只不过是“闻说”；泛舟出游，也只不过是“也拟”，下面又忽出“只恐”，抹杀了上面的“也拟”。听说了，也动念了，结果呢，还是一个人坐在家里发愁罢了。\n\n　　王士稹《花草蒙拾》云：“‘载不动许多愁’与‘载取暮愁归去’、‘只载一船离恨向两州’，正可互观。‘双桨别离船，驾起一天烦恼’，不免径露矣。”这一评论告诉我们，文思新颖，也要有个限度。正确的东西，跨越一步，就变成错误的了；美的东西，跨越一步，就变成丑的了。象“双桨”两句，又是“别离船”，又是“一天烦恼”，惟恐说得不清楚，矫揉造作，很不自然，因此反而难于被人接受。所以《文心雕龙?定势篇》说：“密会者以意新得巧，苟异者以失体成怪。”“巧”之与“怪”，相差也不过是一步而已。\n\n　　李后主《虞美人》云：“问君能有几多愁？恰似一江春水向东流。”只是以愁之多比水之多而已。秦观《江城子》云：“便做春江都是泪，流不尽许多愁。”则愁已经物质化，变为可以放在江中，随水流尽的东西了。李清照等又进一步把它搬上了船，于是愁竟有了重量，不但可随水而流，并且可以用船来载。董解元《西厢记诸宫调》中的《仙吕?点绛唇缠令?尾》云：“休问离愁轻重，向个马儿上驮也驮不动。”则把愁从船上卸下，驮在马背上。王实甫《西厢记》杂剧《正宫?端正好?收尾》云：“遍人间烦恼填胸臆，量这些大小车儿如何载得起。”又把愁从马背上卸下，装在车子上。从这些小例子也可以看出文艺必须有所继承，同时必须有所发展的基本道理来。\n\n　　这首词的整个布局也有值得注意之处。欧阳修《采桑子》云：“群芳过后西湖好，狼藉残红，飞絮蒙蒙，垂柳栏干尽日风。笙歌散尽游人去，始觉春空，垂下帘栊，双燕归来细雨中。”周邦彦《望江南》云：“游妓散，独自绕回堤。芳草怀烟迷水曲，密云衔雨暗城西，九陌未沾泥。桃李下，春晚未成蹊。墙外见花寻路转，柳阴行马过莺啼，无处不凄凄。”作法相同，可以类比。谭献《复堂词话》批欧词首句说：“扫处即生。”这就是这三首词在布局上的共有特点。扫即扫除之扫，生即发生之生。从这三首的第一句看，都是在说以前一阶段情景的结束，欧、李两词是说春光已尽，周词是说佳人已散。在未尽、未散之时，芳菲满眼，花艳掠目，当然有许多动人的情景可写，可是在已尽、已散之后，还有什么可写的呢？这样开头，岂不是把可以写的东西都扫除了吗？及至读下去，才知道下面又发生了另外一番情景。欧词则写暮春时节的闲淡愁怀，周词则写独步回堤直至归去的凄凉意绪，李词则写由风住尘香而触发的物是人非的深沉痛苦。而这些，才是作家所要表现的，也是最动人的部分，所以叫做“扫处即生”。这好比我们去看一个多幕剧，到得晚了一点，走进剧场时，一幕很热闹的戏刚刚看了一点，就拉幕了，却不知道下面一幕内容如何，等到再看下去，才发现原来自己还是赶上了全剧中最精采的高潮部分。任何作品所能反映的社会人生都只能是某些侧面。抒情诗因为受着篇幅的限制，尤其如此。这种写法，能够把省略了的部分当作背景，以反衬正文，从而出人意外地加强了正文的感染力量，所以是可取的。（沈祖棻）', poem_tags = '宋词三百首,宋词精选,初中古诗,婉约,女子,闺怨,感伤' WHERE poem_title = '武陵春·春晚' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '慈母用手中的针线，为远行的儿子赶制身上的衣衫。\n临行前一针针密密地缝缀，怕的是儿子回来得晚衣服破损。\n有谁敢说，子女像小草那样微弱的孝心，能够报答得了像春晖普泽的慈母恩情呢？', poem_notes = '游子：古代称远游旅居的人。吟：诗体名称。\n游子：指诗人自己，以及各个离乡的游子。\n临：将要。\n意恐：担心。归：回来，回家。\n谁言：一作“难将”。言：说。寸草：小草。这里比喻子女。心：语义双关，既指草木的茎干，也指子女的心意。\n报得：报答。三春晖：春天灿烂的阳光，指慈母之恩。三春：旧称农历正月为孟春，二月为仲春，三月为季春，合称三春。晖：阳光。形容母爱如春天温暖、和煦的阳光照耀着子女。', poem_appreciation = '深挚的母爱，无时无刻不在沐浴着儿女们。然而对于孟郊这位常年颠沛流离、居无定所的游子来说，最值得回忆的，莫过于母子分离的痛苦时刻了。此诗描写的就是这种时候，慈母缝衣的普通场景，而表现的，却是诗人深沉的内心情感。\n\n　　开头两句“慈母手中线，游子身上衣”，用“线”与“衣”两件极常见的东西将“慈母”与“游子”紧紧联系在一起，写出母子相依为命的骨肉感情。三、四句“临行密密缝，意恐迟迟归”，通过慈母为游子赶 制出门衣服的动作和心理的刻画，深化这种骨肉之情。母亲千针万线“密密缝”是因为怕儿子“迟迟”难归。伟大的母爱正是通过日常生活中的细节自然地流露出来。前面四句采用白描手法，不作任何修饰，但慈母的形象真切感人。\n\n　　最后两句“谁言寸草心，报得三春晖”，是作者直抒胸臆，对母爱作尽情的讴歌。这两句采用传统的比兴手法：儿女像区区小草，母爱如春天阳光。儿女怎能报答母爱于万一呢？悬绝的对比，形象的比喻，寄托着赤子对慈母发自肺腑的爱。\n\n　　这是一首母爱的颂歌，在宦途失意的境况下，诗人饱尝世态炎凉，穷愁终身，故愈觉亲情之可贵。“诗从肺腑出，出辄愁肺腑”（苏轼《读孟郊诗》）。这首诗，虽无藻绘与雕饰，然而清新流畅，淳朴素淡中正见其诗味的浓郁醇美。\n\n　　这首诗艺术地再现了人所共感的平凡而又伟大的人性美，所以千百年来赢得了无数读者强烈的共鸣。直到清朝，溧阳有两位诗人又吟出了这样的诗句：“父书空满筐，母线萦我襦”（史骐生《写怀》），“向来多少泪，都染手缝衣”（彭桂《建初弟来都省亲喜极有感》），足见此诗给后人的深刻印象。', poem_tags = '唐诗三百首,乐府,赞颂,母亲,母爱,早教古诗100首' WHERE poem_title = '游子吟' AND poem_author = '孟郊';
UPDATE edu_poem SET poem_translation = '透过装饰着云母的屏风，烛影渐渐暗淡下去。银河也在静静地消失，晨星沉没在黎明的曙光里。\n月宫的嫦娥恐怕后悔偷了后羿的长生不老药，现在只有那青天碧海夜夜陪伴着她一颗孤独的心。\n\n韵译\n云母屏风染上一层浓浓的烛影，银河逐渐斜落启明星也已下沉。\n嫦娥想必悔恨当初偷吃下灵药，如今独处碧海青天而夜夜寒心。', poem_notes = '嫦娥：古代神话中的月中仙女，江苏人。恒又作姮。\n云母屏风：嵌着云母石的屏风。此言嫦娥在月宫居室中独处，夜晚，唯烛影和屏风相伴。', poem_appreciation = '就内容而论，这是一首咏嫦娥的诗。然而各家看法不一。有人以为歌咏意中人的私奔，有人以为是直接歌咏主人公处境孤寂，有人以为是借咏嫦娥另外有所寄托，有人以为是歌咏女子学道求仙，有人以为应当作“无题”来看。兹且当作歌咏幽居寂处，终夜不眠的女子。以此而论，着实写得贴情贴理。语言含蕴，情调感伤。\n\n　　前两句描绘主人公的环境和永夜不寐的情景。室内，烛光越来越黯淡，云母屏风上笼罩着一层深深的暗影，越发显出居室的空寂清冷，透露出主人公在长夜独坐中黯然的心境。室外，银河逐渐西移垂地，牛郎、织女隔河遥望，本来也许可以给独处孤室的不寐者带来一些遐想，而这一派银河即将消失。那点缀着空旷天宇的寥落晨星，仿佛默默无言地陪伴着一轮孤月，也陪伴着永夜不寐者，此时连这最后的伴侣也行将隐没。“沉”字正逼真地描绘出晨星低垂、欲落未落的动态，主人公的心也似乎正在逐渐沉下去。“烛影深”“长河落”“晓星沉”，表明时间已到将晓未晓之际，着一“渐”字，暗示了时间的推移流逝。索寞中的主人公，面对冷屏残烛、青天孤月，又度过了一个不眠之夜。尽管这里没有对主人公的心理作任何直接的抒写刻画，但借助于环境氛围的渲染，主人公的孤清凄冷情怀和不堪忍受寂寞包围的意绪却几乎可以触摸到。\n\n　　在寂寥的长夜，天空中最引人注目、引人遐想的自然是一轮明月。看到明月，也自然会联想起神话传说中的月宫仙子──嫦娥。据说她原是后羿的妻子，因为偷吃了西王母送给后羿的不死药，飞奔到月宫，成了仙子。“嫦娥孤栖与谁邻？”在孤寂的主人公眼里，这孤居广寒宫殿、寂寞无伴的嫦娥，其处境和心情不正和自己相似吗？于是，不禁从心底涌出这样的意念：嫦娥想必也懊悔当初偷吃了不死药，以致年年夜夜，幽居月宫，面对碧海青天，寂寥清冷之情难以排遣吧。“应悔”是揣度之词，这揣度正表现出一种同病相怜、同心相应的感情。由于有前两句的描绘渲染，这“应”字就显得水到渠成，自然合理。因此，后两句与其说是对嫦娥处境心情的深情体贴，不如说是主人公寂寞的心灵独白。\n\n　　至于这位寂处幽居、永夜不寐的主人公究竟是谁，诗中并无明确交待。诗人在《送宫人入道》诗中，曾把女冠比作“月娥孀独”，在《月夜重寄宋华阳姊妹》诗中，又以“窃药”喻指女子学道求仙。因此，说这首诗是代困守宫观的女冠抒写凄清寂寞之情，也许不是无稽之谈。唐代道教盛行，女子入道成为风气，入道后方体验到宗教清规对正常爱情生活的束缚而产生精神苦闷，三、四两句，正是对她们处境与心情的真实写照。\n\n　　但是，诗中所抒写的孤寂感以及由此引起的“悔偷灵药”式的情绪，却融入了诗人独特的现实人生感受，而含有更丰富深刻的意蕴。在黑暗污浊的现实包围中，诗人精神上力图摆脱尘俗，追求高洁的境界，而追求的结果往往使自己陷于更孤独的境地。清高与孤独的孪生，以及由此引起的既自赏又自伤，既不甘变心从俗，又难以忍受孤孑寂寞的煎熬这种微妙复杂的心理，在这里被诗人用精微而富于含蕴的语言成功地表现出来了。这是一种含有浓重伤感的美，在旧时代的清高文士中容易引起广泛的共鸣。诗的典型意义也正在这里。\n\n　　孤栖无伴的嫦娥，寂处道观的女冠，清高而孤独的诗人，尽管仙凡悬隔，同在人间者又境遇差殊，但在高洁而寂寞这一点上却灵犀暗通。诗人把握住了这一点，塑造了三位一体的艺术形象。这种艺术概括的技巧，是李商隐的特长。', poem_tags = '唐诗三百首,小学古诗,写人,孤独' WHERE poem_title = '嫦娥' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '不要笑农家腊月里酿的酒浊而又浑，在丰收的年景里待客菜肴非常丰繁。\n山峦重叠水流曲折正担心无路可走，柳绿花艳忽然眼前又出现一个山村。\n吹着箫打起鼓春社的日子已经接近，村民们衣冠简朴古代风气仍然保存。\n今后如果还能乘大好月色出外闲游，我一定拄着拐杖随时来敲你的家门。', poem_notes = '腊酒：腊月里酿造的酒。\n足鸡豚（tún）：意思是准备了丰盛的菜肴。足：足够，丰盛。豚，小猪，诗中代指猪肉。\n山重水复：一座座山、一道道水重重叠叠。\n柳暗花明：柳色深绿，花色红艳。\n箫鼓：吹箫打鼓。春社：古代把立春后第五个戊日做为春社日，拜祭社公（土地神）和五谷神，祈求丰收。\n古风存：保留着淳朴古代风俗。\n若许：如果这样。闲乘月：有空闲时趁着月光前来。\n无时：没有一定的时间，即随时。叩（kòu）门：敲门。', poem_appreciation = '首联：“莫笑农家腊酒浑，丰年留客足鸡豚。”描写丰收年景，农民热情好客的淳厚品行。\n\n　　颔联：“山重水复疑无路，柳暗花明又一村。”这句描绘山村风光，被后世用来形容已陷入绝境，忽又出现转机。\n\n　　颈联：“箫鼓追随春社近，衣冠简朴古风存。”既写出春社欢快，又表达民风的淳朴可爱。\n\n　　尾联：“从今若许闲乘月，拄杖无时夜叩门。”写出诗人乘月闲游，夜访村民。\n\n　　首联渲染出丰收之年农村一片宁静、欢悦的气象。腊酒，指腊月酿制的酒。豚，是猪。足鸡豚，意谓鸡猪足。这两句是说农家酒味虽薄，而待客情意却十分深厚。一个“足”字，表达了农家款客尽其所有的盛情。“莫笑”二字，道出了诗人对农村淳朴民风的赞赏。\n\n　　次联写山间水畔的景色，写景中寓含哲理，千百年来广泛被人引用。“山重水复疑无路，柳暗花明又一村。”读了如此流畅绚丽、开朗明快的诗句，仿佛可以看到诗人在青翠可掬的山峦间漫步，清碧的山泉在曲折溪流中汩汩穿行，草木愈见浓茂，蜿蜒的山径也愈益依稀难认。正在迷惘之际，突然看见前面花明柳暗，几间农家茅舍，隐现于花木扶疏之间，诗人顿觉豁然开朗。其喜形于色的兴奋之状，可以想见。当然这种境界前人也有描摹，这两句却格外委婉别致，所以钱钟书说“陆游这一联才把它写得‘题无剩义’”(《宋诗选注》)。人们在探讨学问、研究问题时，往往会有这样的情况：山回路转、扑朔迷离，出路何在?于是顿生茫茫之感。但是，如果锲而不舍，继续前行，忽然间眼前出现一线亮光，再往前行，便豁然开朗，发现了一个前所未见的新天地。这就是此联给人们的启发，也是宋诗特有的理趣。人们读后，都会感到，在人生某种境遇中，与诗句所写有着惊人的契合之处，因而更觉亲切。这里描写的是诗人置身山阴道上，信步而行，疑若无路，忽又开朗的情景，不仅反映了诗人对前途所抱的希望，也道出了世间事物消长变化的哲理。于是这两句诗就越出了自然景色描写的范围，而具有很强的艺术生命力。\n\n　　此联展示了一幅春光明媚的山水图；下一联则由自然入人事，描摹了南宋初年的农村风俗画卷。读者不难体味出诗人所要表达的热爱传统文化的深情。“社”为土地神。春社，在立春后第五个戊日。这一天农家祭社祈年，热热闹闹，吹吹打打，充满着丰收的期待。这个节日来源很古，《周礼》里就有记载。苏轼《蝶恋花·密州上元》也说：“击鼓吹箫，却入农桑社。”到宋代还很盛行。而陆游在这里更以“衣冠简朴古风存”，赞美着这个古老的乡土风俗，显示出他对吾土吾民之爱。\n\n　　前三联写了外界情景，并和自己的情感相融。然而诗人似乎意犹未足，故而笔锋一转：“从今若许闲乘月，拄杖无时夜叩门。”无时，随时。诗人已“游”了一整天，此时明月高悬，整个大地笼罩在一片淡淡的清光中，给春社过后的村庄也染上了一层静谧的色彩，别有一番情趣。于是这两句从胸中自然流出：但愿而今而后，能拄杖乘月，轻叩柴扉，与老农亲切絮语，此情此景，不亦乐乎!一个热爱家乡，与农民亲密无间的诗人跃然纸上。\n\n　　诗人被投降派弹劾罢归故里，心中当然愤愤不平。对照诈伪的官场，于家乡纯朴的生活自然会产生无限的欣慰之情。此外，诗人虽貌似闲适，却未能忘情国事。秉国者目光短浅，无深谋长策，然而诗人并未丧失信心，深信总有一天否极泰来。这种心境和所游之境恰相吻合，于是两相交涉，产生了传诵千古的“山重”“柳暗”一联。\n\n　　陆游七律最工。这首七律结构严谨，主线突出，全诗八句无一“游”字，而处处切“游”字，游兴十足，游意不尽。又层次分明。尤其中间两联，对仗工整，善写难状之景，如珠落玉盘，圆润流转，达到了很高的艺术水平。', poem_tags = '小学古诗,初中古诗,写景,山水,乡村,生活,哲理,早教古诗100首' WHERE poem_title = '游山西村' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '那墙角的几枝梅花，冒着严寒独自盛开。\n为什么远望就知道洁白的梅花不是雪呢？因为梅花隐隐传来阵阵的香气。', poem_notes = '凌寒：冒着严寒。\n遥：远远地。知：知道。\n为（wèi）：因为。暗香：指梅花的幽香。', poem_appreciation = '“墙角数枝梅”，“墙角”不引人注目，不易为人所知，更未被人赏识，却又毫不在乎。“墙角“这个环境突出了数枝梅身居简陋，孤芳自开的形态。体现出诗人所处环境恶劣，却依旧坚持自己的主张的态度。\n\n　　“凌寒独自开”，“独自”，语意刚强，无惧旁人的眼光，在恶劣的环境中，依旧屹立不倒。体现出诗人坚持自我的信念。\n\n　　“遥知不是雪”，“遥知”说明香从老远飘来，淡淡的，不明显。诗人嗅觉灵敏，独具慧眼，善于发现。“不是雪”，不说梅花，而梅花的洁白可见。意谓远远望去十分纯净洁白，但知道不是雪而是梅花。诗意曲折含蓄，耐人寻味。暗香清幽的香气。\n\n　　“为有暗香来”，“暗香”指的是梅花的香气，以梅拟人，凌寒独开，喻典品格高贵；暗香沁人，象征其才气谯溢。\n\n　　首二句写墙角梅花不惧严寒，傲然独放，末二句写梅花洁白鲜艳，香气远布，赞颂了梅花的风度和品格，这正是诗人幽冷倔强性格的写照。诗人通过对梅花不畏严寒的高洁品性的赞赏，用雪喻梅的冰清玉洁，又用“暗香”点出梅胜于雪，说明坚强高洁的人格所具有的伟大的魅力。作者在北宋极端复杂和艰难的局势下，积极改革，而得不到支持，其孤独心态和艰难处境，与梅花自然有共通的地方。这首小诗意味深远，而语句又十分朴素自然，没有丝毫雕琢的痕迹。', poem_tags = '古诗三百首,写景,咏物,梅花,寓人,人格,早教古诗100首' WHERE poem_title = '梅花' AND poem_author = '王安石';
UPDATE edu_poem SET poem_translation = '老朋友向我频频挥手，告别了黄鹤楼，在这柳絮如烟、繁花似锦的阳春三月去扬州远游。\n友人的孤船帆影渐渐地远去，消失在碧空的尽头，只看见一线长江，向邈远的天际奔流。', poem_notes = '黄鹤楼：中国著名的名胜古迹，故址在今湖北武汉市武昌蛇山的黄鹄矶上，属于长江下游地带，传说三国时期的费祎于此登仙乘黄鹤而去，故称黄鹤楼。原楼已毁，现存楼为1985年修葺。孟浩然：李白的朋友。之：往、到达。广陵：即扬州。\n故人：老朋友，这里指孟浩然。其年龄比李白大，在诗坛上享有盛名。李白对他很敬佩，彼此感情深厚，因此称之为“故人”。辞：辞别。\n烟花：形容柳絮如烟、鲜花似锦的春天景物，指艳丽的春景。下：顺流向下而行。\n碧空尽：消失在碧蓝的天际。尽：尽头，消失了。碧空：一作“碧山”。\n唯见：只看见。天际流：流向天边 天际：天边，天边的尽头。', poem_appreciation = '李白是一位热爱自然、喜欢交游的诗人，他“一生好入名山游”，足迹几乎遍及整个中国，留下了许多歌咏自然美、歌颂友情的作品。《黄鹤楼送孟浩然之广陵》是历来传颂的名篇，这首诗是李白出蜀壮游期间的作品，写诗人送别友人时无限依恋的感情，也写出祖国河山的壮丽美好。\n\n　　诗的起句“故人西辞黄鹤楼”紧扣题旨，点明送行的地点及自己与被送者的关系。“故人”一词说明了两位诗人的深厚情谊。“黄鹤楼”是天下名胜，是诗人墨客流连聚会之所，又是传说中仙人乘鹤升天之处。而今两位潇洒飘逸的诗人在此道别，更带有诗意和浪漫色彩。第二句“烟花三月下扬州”，紧承首句，写送行的时令与被送者要去的地方。“扬州”是东南都会，自古繁华，而“三月”又正是春光明媚，百花争艳的季节。诗人用“烟花”修饰“三月”，不仅传神地写出烟雾迷蒙、繁花似锦的阳春特色，也使人联想到处在开元盛世的扬州，那花团锦簇、绣户珠帘，繁荣而又太平的景象。孟浩然要去的地方真是好地方，时间也选择得恰当。李白对友人的这次旅游自然十分欣羡。“烟花三月下扬州”这清丽明快的诗句，正表达了诗人内心的愉快与向往。但李白又是富于感情的诗人，当友人扬帆远去的时候，惜别之情油然而生。从《李太白集》里，我们可以看到李白、孟浩然之间有着不少赠答诗。在《赠孟浩然》中，李白写道：“吾爱孟夫子，风流天下闻。红颜弃轩冕，白首卧松云。”可见李白对孟浩然是多么敬佩，两人的情谊是多么深厚。\n\n　　诗的第三、四句正是写李白送别诗友时的惜别深情。“孤帆远影碧空尽，唯见长江天际流。”表面看来这两句诗全是写景，其实却有着诗人鲜明的形象。“孤帆”绝不是说浩瀚的长江上只有一只帆船，而是写诗人的全部注意力和感情只集中在友人乘坐的那一只帆船上。诗人在黄鹤楼边送行，看着友人乘坐的船挂起风帆，渐去渐远，越去越小，越去越模糊了，只剩下一点影子了，最后终于消失在水天相接之处，而诗人仍然久久伫立，目送流向天际的江水，似乎要把自己的一片情意托付江水，陪随行舟，将友人送到目的地。这两句诗表达了多么深挚的友情，然而在诗句中却找不到“友情”这个字眼。诗人巧妙地将依依惜别的深情寄托在对自然景物的动态描写之中，将情与景完全交融在一起了，真正做到了含吐不露而余味无穷。\n\n　　另外在诗歌的用韵上，诗人也颇具匠心地选择了“楼”“州”“流”三个声调悠扬的韵脚，吟诵起来余音袅袅。这与孤帆远去、江流天际的景象以及诗人目送神驰、情意绵绵的神态十分吻合。再加上语言清丽自然，意境雄浑开阔，这首诗真是令人越读越爱，百读不厌，无怪乎千古传颂。\n\n　　清人沈德潜在《唐诗别裁》中品评李太白七绝的艺术特色时说：“七言绝句以语近情遥，含吐不露为贵。只眼前景，口头语而有弦外音，使人神远，太白有焉。”李太白的七绝在诗坛上的确是独步了。\n\n　　这首送别诗有它自己特殊的情味。它不同于王勃《送杜少府之任蜀川》那种少年刚肠的离别，也不同于王维《渭城曲》那种深情体贴的离别。这首诗，可以说是表现一种充满诗意的离别。其所以如此，是因为这是两位风流潇洒的诗人的离别。还因为这次离别跟一个繁华的时代、繁华的季节、繁华的地区相联系，在愉快的分手中还带着诗人李白的向往，这就使得这次离别有着无比的诗意。\n\n　　李白与孟浩然的交往，是在他刚出四川不久，正当年轻快意的时候，他眼里的世界，还几乎象黄金一般美好。比李白大十多岁的孟浩然，这时已经诗名满天下。他给李白的印象是陶醉在山水之间，自由而愉快，所以李白在《赠孟浩然》诗中说：“吾爱孟夫子，风流天下闻。红颜弃轩冕，白首卧松云。”再说这次离别正是开元盛世，太平而又繁荣，季节是烟花三月、春意最浓的时候，从黄鹤楼到扬州，这一路都是繁花似锦。而扬州呢？更是当时整个东南地区最繁华的都会。李白是那样一个浪漫、爱好游览的人，所以这次离别完全是在很浓郁的畅想曲和抒情诗的气氛里进行的。李白心里没有什么忧伤和不愉快，相反地认为孟浩然这趟旅行快乐得很，他向往扬州，又向往孟浩然，所以一边送别，一边心也就跟着飞翔，胸中有无穷的诗意随着江水荡漾。\n\n　　“故人西辞黄鹤楼”，这一句不光是为了点题，更因为黄鹤楼乃天下名胜，可能是两位诗人经常流连聚会之所。因此一提到黄鹤楼，就带出种种与此处有关的富于诗意的生活内容。而黄鹤楼本身呢？又是传说仙人飞上天空去的地方，这和李白心目中这次孟浩然愉快地去扬州，又构成一种联想，增加了那种愉快的、畅想曲的气氛。\n\n　　“烟花三月下扬州”，在“三月”上加“烟花”二字，把送别环境中那种诗的气氛涂抹得尤为浓郁。烟花者，烟雾迷蒙，繁花似锦也。给人的感觉决不是一片地、一朵花，而是看不尽、看不透的大片阳春烟景。三月，固然是烟花之时，而开元时代繁华的长江下游，又何尝不是烟花之地呢？“烟花三月”，不仅再现了那暮春时节、繁华之地的迷人景色，而且也透露了时代气氛。此句意境优美，文字绮丽，清人孙洙誉为“千古丽句”。\n\n　　“孤帆远影碧空尽，唯见长江天际流。”诗的后两句看起来似乎是写景，但在写景中包含着一个充满诗意的细节。李白一直把朋友送上船，船已经扬帆而去，而他还在江边目送远去的风帆。李白的目光望着帆影，一直看到帆影逐渐模糊，消失在碧空的尽头，可见目送时间之长。帆影已经消逝了，然而李白还在翘首凝望，这才注意到一江春水，在浩浩荡荡地流向远远的水天交接之处。“唯见长江天际流”，是眼前景象，可是谁又能说是单纯写景呢？李白对朋友的一片深情，李白的向往，不正体现在这富有诗意的神驰目注之中吗？诗人的心潮起伏，不正象浩浩东去的一江春水吗？\n\n　　总之，这一场极富诗意的、两位风流潇洒的诗人的离别，对李白来说，又是带着一片向往之情的离别，被诗人用绚烂的阳春三月的景色，用放舟长江的宽阔画面，用目送孤帆远影的细节，极为传神地表现出来', poem_tags = '唐诗三百首,小学古诗,写景,写水,长江,地名,离别,友情,送别,早教古诗100首,古诗里的十二个月' WHERE poem_title = '黄鹤楼送孟浩然之广陵' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '秋天到了，西北边塞的风光和江南不同。大雁又飞回衡阳了，一点也没有停留之意。黄昏时，军中号角一吹，周围的边声也随之而起。层峦叠嶂里，暮霭沉沉，山衔落日，孤零零的城门紧闭。\n饮一杯浊酒，不由得想起万里之外的家乡，未能像窦宪那样战胜敌人，刻石燕然，不能早作归计。悠扬的羌笛响起来了，天气寒冷，霜雪满地。夜深了，将士们都不能安睡：将军为操持军事，须发都变白了；战士们久戍边塞，也流下了伤心的眼泪。', poem_notes = '渔家傲：又名《吴门柳》、《忍辱仙人》、《荆溪咏》、《游仙关》。\n塞：边界要塞之地，这里指西北边疆。\n衡阳雁去：传说秋天北雁南飞，至湖南衡阳回雁峰而止，不再南飞。\n边声：边塞特有的声音，如大风、号角、羌笛、马啸的声音。\n千嶂：绵延而峻峭的山峰；崇山峻岭。\n燕然未勒：指战事未平，功名未立。燕然：即燕然山，今名杭爱山，在今蒙古国境内。据《后汉书·窦宪传》记载，东汉窦宪率兵追击匈奴单于，去塞三千余里，登燕然山，刻石勒功而还。\n羌管：即羌笛，出自古代西部羌族的一种乐器。\n悠悠：形容声音飘忽不定。\n寐：睡，不寐就是睡不着。', poem_appreciation = '范仲淹是当时的著名的军事家、政治家，官至副宰相。他了解民间疾苦，深知宋王朝在政治、经济、军事等方面存在的问题，主张革除积弊，但因统治集团内部守旧派的反对，没能实现。\n\n　　他也是著名的文学家。这首《渔家傲》是他的代表作，反映的是他亲身经历的边塞生活。古代把汉族政权和少数民族政权之间的交界地方叫做“塞”或“塞上”、“塞下”。这首词所说的塞下，指的是北宋和西夏交界的陕北一带。\n\n　　从词史上说，此词沉雄开阔的意境和苍凉悲壮的气概，对苏轼、辛弃疾等也有影响。\n\n　　任何一首诗词的审美价值，是由多种艺术功能构成的。这首《渔家傲》并非以军事征战为题材，而是写边塞将士对家乡的怀念，因之不能生硬地用政治的尺度来衡量，而应该用艺术的尺度来衡量。它的艺术功能、艺术力量，在于抒情写景，但即使从政治上要求，此词的意义也并不消极。“燕然未勒归无计”一句，正是这首词最本质的思想亮点。燕然山，即今之杭爱山。后汉时，将军窦宪追击匈奴，曾登上燕然山刻碑（勒石）纪功。词中霜雪满头的老将军，已擦干思乡之泪，在恋家与报国的矛盾中，他是以戍边军务为重。他尽忠职守，不建功勋于边陲，虽有时思乡心切，也是不打算归去的。\n\n　　词的上阕侧重写景。秋来风景异，雁去无留意，是借雁去衡阳回雁峰的典故，来反映人在塞外的思归之情。思归不是因为厌弃边塞生活，不顾国家安危。而是边防凄厉的号角声以及周遭的狼嗥风啸声，令人心寒。更奈何日落千嶂，长烟锁山，孤城紧闭，此情此景甚是令人怀念故乡的温馨。人非草木，孰能无情。一个长期戍边的老将，惦念亲人和家乡也是很自然的。“千嶂里，长烟落日孤城闭”，此句写得最成功，仅10个字便勾勒出一派壮阔苍茫的边塞黄昏景致。\n\n　　写景是为了抒情。因此下阕一开头就是“浊酒一杯家万里，燕然未勒归无计”。浊酒，本是乳白色的米酒，这里也暗喻心情重浊。因为思归又不能归以致心情重浊。“归无计”，是说没有两全其美的可能性。正在这矛盾的心绪下，远方羌笛悠悠，搅得征夫们难以入梦，不能不苦思着万里之遥的家乡，而家乡的亲人可能也在盼望白发人。“人不寐，将军白发征夫泪”，这10个字扣人心弦，写出了深沉忧国爱国的复杂感情。\n\n　　这首《渔家傲》不是令人消沉斗志之词，它真实地表现了戍边将士思念故乡，而更热爱祖国，矢志保卫祖国的真情。范仲淹曾在《岳阳楼记》一文中，倡导“先天下之忧而忧，后天下之乐而乐”的崇高精神。词中的白发老将军，正是这种崇高精神的生动写照。黄蓼园说它“读之凛凛有生气”，倒是深得其旨趣。\n\n　　“千嶂里，长烟落日孤城闭”。只此两句便抵得上那首有名的《敕勒歌》，虽然彼此取材不同。伟大的诗人杜甫曾写过“孤城早闭门”的佳句，但气势的雄浑似不及范词。那是人烟稀少的边塞，光秃的山峰重重叠叠，上空飘浮着一缕缕的青烟，悲壮的号角和着杂乱的边声在四野回荡。太阳还没有收起它金色的余晖，远远望去，山腰里一座孤零零的城池早已把城门关闭。这就像一幅中世纪边塞景象的艺术摄影。\n\n　　一幅野性十足的边塞图画。“塞下秋来风景异，衡阳雁去无留意，四面边声连角起，千嶂里，长烟落日孤城闭。”这样的“边塞情绪”，往往当人物置身特定场景之后，自然流露出来；此时才明白，长烟落日的边塞，对于生命个体而言，并不仅仅是“戍边苦”，还会产生极大的心理满足。\n\n　　词是范仲淹守边愿望和复杂心态的真实袒露。词中反映了边塞生活的艰苦和词人巩固边防的决心和意愿，同时还表现出外患未除、功业未建、久戍边地、士兵思乡等复杂矛盾的心情。在有着浓郁思乡情绪的将士们的眼中，塞外之景色失去了宽广的气魄、欢愉的气氛，画面上笼罩着一种旷远雄浑、苍凉悲壮的气氛。在边塞熬白黑发，滴尽思乡泪，却又不能抛开国事不顾，将士们的心理是矛盾复杂的。范仲淹虽然守边颇见成效，然而，当时在北宋与西夏的军事力量对比上，北宋处于下风，只能保持守势。范仲淹守边的全部功绩都体现在“能够维持住守势”这样一个局面上，时而还有疲于奔命之感。这对有远大政治志向的范仲淹来说肯定是不能满足的，但又是十分无奈的。所以，体现在词中的格调就不会是昂扬慷慨的。\n\n　　此前，很少有人用词来写边塞生活。唐代韦应物的《调笑》虽有“边草无穷日暮”之句，但没有展开，且缺少真实的生活基础。所以，这首词实际上是边塞词的首创。\n\n　　上片描绘边地的荒凉景象。首句指出“塞下”这一地域性的特点，并以“异”字领起全篇，为下片怀乡思归之情埋下了伏线。“衡阳雁去”是“塞下秋来”的客观现实，“无留意”虽然是北雁南飞的具体表现，但更重要的是这三个字来自戍边将士的内心，它衬托出雁去而人却不得去的情感。以下十七字通过“边声”“角起”“千嶂”“孤城”等具有特征性的事物，把边地的荒凉景象描绘得有声有色。首句中的“异”字通过这十七个宇得到了具体的发挥。\n\n　　下片写戍边战士厌战思归的心情。前两句含有三层意思：“浊酒一杯”扑不灭思乡情切；长期戍边而破敌无功；所以产生“归无计”的慨叹。接下去，“羌管悠悠霜满地”一句，再次用声色加以点染并略加顿挫，此时心情，较黄昏落日之时更加令人难堪。“人不寐”三字绾上结下，其中既有白发“将军”，又有落泪“征夫”。“不寐”又紧密地把上景下情联系在一起。“羌管悠悠”是“不寐”时之所闻；“霜满地”是“不寐”时之所见。内情外景达到了水乳交融的艺术境界。', poem_tags = '宋词三百首,初中古诗,秋天,边塞,思乡,爱国' WHERE poem_title = '渔家傲·秋思' AND poem_author = '范仲淹';
UPDATE edu_poem SET poem_translation = '自古以来每逢秋天都会感到悲凉寂寥，我却认为秋天要胜过春天。\n万里晴空，一只鹤凌云飞起，就引发我的诗兴到了蓝天上了。', poem_notes = '悲寂寥：悲叹萧条。\n春朝：春天。\n排：推，有冲破的意思。\n碧霄：青天。', poem_appreciation = '“自古逢秋悲寂寥”，诗人开篇，即以议论起笔，断然否定了前人悲秋的观念，表现出一种激越向上的诗情。首句即明确指出自古以来，人们每逢到了秋天就感叹秋天的寂寞萧索。“自古”和“逢”，极言悲秋的传统看法的时代久远和思路模式的顽固。接着一句用“我言”直抒胸臆，态度鲜明，说出的是诗人的自信，这种自信，尽管染上的，是一种不幸的色彩，然而，诗人阔大的胸襟却非凡地溶解了这种不幸。“秋日胜春朝”，用对比手法，热情赞美秋天，说秋天比那万物萌生，欣欣向荣的春天更胜过一筹，这是对自古以来那种悲秋的论调的有力否定。\n\n　　第三句选择了典型事物具体生动地勾勒了一幅壮美的画面。诗人抓住秋天“一鹤凌云”，这一别致的景观的描绘，展现的是秋高气爽，万里晴空，白云漂浮的开阔景象。那凌云的鹤，也载着诗人的诗情，一同遨游到了云霄。虽然，这鹤是孤独的，然而它所呈现出来的气势，却是非凡的。一个“排”字，所蕴涵的深意，尽在不言中了。也许，诗人是以“鹤”自喻，也许是诗人视“鹤”为不屈的化身。这里，有哲理的意蕴，也有艺术的魅力，发人深思，耐人吟咏。这幅画面是对“秋日胜春朝”的生动注脚。第四句紧接上句直接抒写自己的感受，看到这一壮美的情境作者心中那激荡澎湃的诗情勃发出来，也像白鹤凌空一样，直冲云霄了。字里行间作者那乐观的情怀，昂扬的斗志国安呼之欲出。如果说，上句侧重写秋的“形美”，那么这句则突出秋的“神韵”，使“秋日胜春朝”的观点表现得更鲜明，更有力度。\n\n　　“晴空一鹤排云上，便引诗情到碧霄”展现的，不仅仅是秋天的生机和素色，更多的是一种高扬的气概和高尚的情操。这样的诗，没有什么悲凉的气息，诗人随着自己的“诗情”，和想象驰骋于碧空之上。于是，鹤飞之冲霄，诗情之旷远，“实”和“虚”便融合在了一起，所获得的全然是一种励志冶情的美的感受。全诗气势雄浑，意境壮丽，融情、景、理于一炉，不仅仅表现出是秋天的生机和素色，更多的是一种高扬精神和开阔胸襟，唱出的那曲非同凡响的秋歌，留下的是一份难能可贵的精神财富。', poem_tags = '初中古诗,秋天,悲秋' WHERE poem_title = '秋词' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '金溪有个叫方仲永的百姓，家中世代以耕田为业。仲永长到五岁时，不曾认识书写工具。忽然有一天仲永哭着索要这些东西。他的父亲对此感到诧异，就向邻居那里把那些东西借来给他。仲永立刻写下了四句，并自己题上自己的名字。这首诗以赡养父母和团结同宗族的人为主旨，给全乡的秀才观赏。从此，指定事物让他作诗，方仲永立刻就能完成，并且诗的文采和道理都有值得欣赏的地方。同县的人们对此都感到非常惊奇，渐渐地都以宾客之礼对待他的父亲，有的人花钱求取仲永的诗。方仲永父亲认为这样有利可图，就每天带领着仲永四处拜访同县的人，不让他学习。\n\n　　我听到这件事很久了。明道年间，我跟随先父回到家乡，在舅舅家见到方仲永，他已经十二三岁了。我叫他作诗，写出来的诗已经不能与从前的名声相称。又过了七年，我从扬州回来，再次到舅舅家去，问起方仲永的情况，回答说：“他的才能消失了，和普通人没有什么区别了。”\n\n　　王安石说：方仲永的通达聪慧，是先天得到的。他的天赋，比一般有才能的人要优秀得多；但最终成为一个平凡的人，是因为他后天所受的教育还没有达到要求。他得到的天资是那样的好，没有受到正常的后天教育，尚且成为平凡的人；那么，现在那些本来就不天生聪明，本来就是平凡的人，又不接受后天的教育，难道成为普通人就为止了吗？', poem_notes = '伤：哀伤，叹息。\n金溪：地名，今在江西金溪。\n隶：属于。\n生：生长到。\n识：认识。\n书具：书写的工具（笔、墨、纸、砚等）。\n求：要。\n异：对······感到诧异。\n借旁近：就近借来。旁近，附近，这里指邻居。\n与：给。.\n养：奉养，赡养。\n收族：团结宗族，和同一宗族的人搞好关系。收，聚，团结。\n意：主旨（中心，或文章大意）。\n一：全。\n指：指定。\n就：完成。\n文：文采。\n理：道理。\n邑人：同（乡）县的人。\n奇：对······感到惊奇（奇怪）。\n稍稍：渐渐。\n宾客：这里是以宾客之礼相待的意思，宾，本文的意思是状语。\n乞：求取。\n利其然：认为这样是有利可图的。利，认为······有利可图。\n日：每天。\n扳：通“攀”，牵，引。\n环：四处，到处。\n谒：拜访。\n明道：宋仁宗赵祯年号（1032－1033年）。\n从：跟随。\n先人：指王安石死去的父亲。\n前时之闻：以前的名声。\n复：又，再。\n泯然众人矣：完全如同常人了。泯然：消失，指原有的特点完全消失了。众人，常人。\n王子：王安石的自称。\n通：通达。\n悟：聪慧。\n受：接受。\n天：先天。\n贤：胜过，超过。\n于：比。\n材：同“才”，才能。\n卒：最终。\n于：被。\n不至：没有达到要求。.至，达到。\n彼其：他。\n已：停止。\n耶：表示反问，相当于“吗”、“呢”。', poem_appreciation = '本文见闻得当，借事说理，以方仲永的实例，说明后天教育对成才的重要性。文章分两部分：叙事部分写方仲永幼年时天资过人，却因其父“不使学”而最终“泯然众人”，变得平庸无奇；议论部分则表明作者的看法，指出方仲永才能衰退是由于“受于人者不至”，强调了后天教育的重要。文章通过方仲永这一实例说明具有普遍借鉴意义的道理，给人以深长的思考。\n\n　　本文的语言十分精当。叙事部分仅以二百三十四字就完整地叙述了方仲永从五岁到二十岁间才能变化的过程，议论部分也不过七十余字，文中的每一词、句都有其确切的表达作用，而不是可有可无。例如第一段，首句交代籍贯、身份、姓名、家世，这不仅是必不可少的一般介绍，而且“世隶耕”三字是对“未尝识书具”“不使学”的必要铺垫，既衬托了方仲永的非凡天资，又暗示了造成他命运的家庭背景；一个“啼”字，生动地写出方仲永索求书具的儿童情态；“忽”“即”“立”三个副词，使一个天资非凡、文思敏捷的神童形象跃然纸上；“日扳仲永环谒于邑人”，仅一句话就刻画出方仲永父亲贪图小利而自得的可悲可叹的愚昧无知之态；“不使学”三字，看似平淡，却为方仲永的变化埋下伏笔，点出方仲永命运变化的关键。第二段叙事极为简要，仅以一“见”一“闻”一“问”就交代了方仲永后来的变化和结局。结尾的议论部分，言简意深，说理严谨。对本文语言精当的特点，可以逐词逐句体察、品味。\n\n　　本文语言平实而又不乏感情色彩。字里行间流露着作者对一个神童最终“泯然众人”的惋惜之情，突出了主题，对“受之天”而“受于人者不至”者的哀伤之情，并以鲜明的态度表明作者的观点。', poem_tags = '初中文言文,学习,哲理,故事' WHERE poem_title = '伤仲永' AND poem_author = '王安石';
UPDATE edu_poem SET poem_translation = '见面的机会真是难得，分别时更是难舍难分，况且又兼东风将收的暮春天气，百花残谢，更加使人伤感。\n春蚕结茧到死时丝才吐完，蜡烛要燃尽成灰时像泪一样的蜡油才能滴干。\n女子早晨妆扮照镜，只担忧丰盛如云的鬓发改变颜色，青春的容颜消失。男子晚上长吟不寐，必然感到冷月侵人。\n对方的住处就在不远的蓬莱山，却无路可通，可望而不可及。希望有青鸟一样的使者殷勤地为我去探看情人。', poem_notes = '无题：唐代以来，有的诗人不愿意标出能够表示主题的题目时，常用“ 无题”作诗的标题。\n东风无力百花残：这里指百花凋谢的暮春时节。东风，春风。残，凋零。\n丝方尽：丝，与“思”谐音，以“丝”喻“思”，含相思之意。\n蜡炬：蜡烛。\n泪始干：泪，指燃烧时的蜡烛油，这里取双关义，指相思的眼泪。\n晓镜：早晨梳妆照镜子。镜，用作动词，照镜子的意思。\n云鬓：女子多而美的头发，这里比喻青春年华。\n应觉：设想之词。\n月光寒：指夜渐深。\n蓬山：蓬莱山，传说中海上仙山，指仙境。\n青鸟：神话中为西王母传递音讯的信使。\n殷勤：情谊恳切深厚。\n探看（kān）：探望。', poem_appreciation = '相见时难别亦难，说的是义山当时的处境艰难，离开徐州到长安后想进翰林院，向令狐綯说明此时，也就是找熟人走个后门，令狐陶升官之后，为了避嫌谢绝见客，致使义山处境尴尬，相见难，离别又不甘心，所以出此名句。\n\n　　东风无力百花残，当时义山已经很大年纪，东风无回天之力挽救百花的凋零，映射自己留不住青春春蚕到死丝方尽，蜡炬成灰泪始干，此名句献给所有为理想奋斗终生之人。\n\n　　晓镜但愁云鬓改，夜吟应觉月光寒，和上句呼应，青春难留，云鬓斑白，蜡炬燃尽，月光甚寒。\n\n　　蓬山此去无多路，青鸟殷勤为探看，最后一句起死回生，由深深地“到死”,“成灰“的绝望，到‘无多路’，可见作者还是对綯抱有希望，不肯决绝。\n\n　　从现在来看，此诗不难看出也是写给令狐綯，希望他看到之后体会到自己的心情，也希望綯能感受到自己并没有绝望，而是继续等待綯这个救命稻草的帮助。', poem_tags = '唐诗三百首,初中古诗,爱情,思念,早教古诗100首' WHERE poem_title = '无题·相见时难别亦难' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '所有的山，飞鸟全都断绝；所有的路，不见人影踪迹。\n江上孤舟，渔翁披蓑戴笠；独自垂钓，不怕冰雪侵袭。', poem_notes = '绝：无，没有。\n万径：虚指，指千万条路。\n人踪：人的脚印。\n孤：孤零零。\n蓑笠（suō lì）：蓑衣和斗笠　笠：用竹篾编成的帽子。\n独：独自。', poem_appreciation = '柳宗元笔下的山水诗有个显著的特点，那就是把客观境界写得比较幽僻，而诗人的主观的心情则显得比较寂寞，甚至有时不免过于孤独，过于冷清，不带一点人间烟火气。这首《江雪》正是这样，诗人只用了二十个字，就描绘了一幅幽静寒冷的画面：在下着大雪的江面上，一叶小舟，一个老渔翁，独自在寒冷的江心垂钓。诗人向读者展示的，是这样一些内容：天地之间是如此纯洁而寂静，一尘不染，万籁无声；渔翁的生活是如此清高，渔翁的性格是如此孤傲。其实，这正是柳宗元由于憎恨当时那个一天天在走下坡路的唐代社会而创造出来的一个幻想境界，比起陶渊明《桃花源记》里的人物，恐怕还要显得虚无缥缈，远离尘世。诗人所要具体描写的本极简单，不过是一条小船，一个穿蓑衣戴笠帽的老渔翁，在大雪的江面上钓鱼，如此而已。可是，为了突出主要的描写对象，诗人不惜用一半篇幅去描写它的背景，而且使这个背景尽量广大寥廓，几乎到了浩瀚无边的程度。背景越广大，主要的描写对象就越显得突出。首先，诗人用“千山”、“万径”这两个词，目的是为了给下面两句的“孤舟”和“独钓”的画面作陪衬。没有“千”、“万”两字，下面的“孤”、“独”两字也就平淡无奇，没有什么感染力了。其次，山上的鸟飞，路上的人踪，这本来是极平常的事，也是最一般化的形象。可是，诗人却把它们放在“千山”、“万径”的下面，再加上一个“绝”和一个“灭”字，这就把最常见的、最一般化的动态，一下子给变成极端的寂静、绝对的沉默，形成一种不平常的景象。因此，下面两句原来是属于静态的描写，由于摆在这种绝对幽静、绝对沉寂的背景之下，倒反而显得玲珑剔透，有了生气，在画面上浮动起来、活跃起来了。也可以这样说，前两句本来是陪衬的远景，照一般理解，只要勾勒个轮廓也就可以了，不必费很大气力去精雕细刻。可是，诗人却恰好不这样处理。这好像拍电影，用放大了多少倍的特写镜头，把属于背景范围的每一个角落都交代得、反映得一清二楚。写得越具体细致，就越显得概括夸张。而后面的两句，本来是诗人有心要突出描写的对象，结果却使用了远距离的镜头，反而把它缩小了多少倍，给读者一种空灵剔透、可见而不可即的感觉。只有这样写，才能表达作者所迫切希望展示给读者的那种摆脱世俗、超然物外的清高孤傲的思想感情。至于这种远距离感觉的形成，主要是作者把一个“雪”字放在全诗的最末尾，并且同“江”字连起来所产生的效果。\n\n　　在这首诗里，笼罩一切、包罗一切的东西是雪，山上是雪，路上也是雪，而且“千山”、“万径”都是雪，才使得“鸟飞绝”、“人踪灭”。就连船篷上，渔翁的蓑笠上，当然也都是雪。可是作者并没有把这些景物同“雪”明显地联系在一起。相反，在这个画面里，只有江，只有江心。江，当然不会存雪，不会被雪盖住，而且即使雪下到江里，也立刻会变成水。然而作者却偏偏用了“寒江雪”三个字，把“江”和“雪”这两个关系最远的形象联系到一起，这就给人以一种比较空蒙、比较遥远、比较缩小了的感觉，这就形成了远距离的镜头。这就使得诗中主要描写的对象更集中、更灵巧、更突出。因为连江里都仿佛下满了雪，连不存雪的地方都充满了雪，这就把雪下得又大又密、又浓又厚的情形完全写出来了，把水天不分、上下苍茫一片的气氛也完全烘托出来了。至于上面再用一个“寒”字，固然是为了点明气候；但诗人的主观意图却是在想不动声色地写出渔翁的精神世界。试想，在这样一个寒冷寂静的环境里，那个老渔翁竟然不怕天冷，不怕雪大，忘掉了一切，专心地钓鱼，形体虽然孤独，性格却显得清高孤傲，甚至有点凛然不可侵犯似的。这个被幻化了的、美化了的渔翁形象，实际正是柳宗元本人的思想感情的寄托和写照。由此可见，这“寒江雪”三字正是“画龙点睛”之笔，它把全诗前后两部分有机地联系起来，不但形成了一幅凝炼概括的图景，也塑造了渔翁完整突出的形象。\n\n　　用具体而细致的手法来摹写背景，用远距离画面来描写主要形象；精雕细琢和极度的夸张概括，错综地统一在一首诗里，是这首山水小诗独有的艺术特色。', poem_tags = '唐诗三百首,写景,冬天,写雪,山水,写鸟,早教古诗100首' WHERE poem_title = '江雪' AND poem_author = '柳宗元';
UPDATE edu_poem SET poem_translation = '金杯里装的名酒，每斗要价十千； 玉盘中盛的精美菜肴，收费万钱。\n胸中郁闷啊，我停杯投箸吃不下； 拔剑环顾四周，我心里委实茫然。\n想渡黄河，冰雪堵塞了这条大川； 要登太行，莽莽的风雪早已封山。\n像吕尚垂钓溪，闲待东山再起； 又像伊尹做梦，他乘船经过日边。\n世上行路呵多么艰难，多么艰难； 眼前歧路这么多，我该向北向南？\n相信总有一天，能乘长风破万里浪； 高高挂起云帆，在沧海中勇往直前！', poem_notes = '行路难：选自《李白集校注》，乐府旧题。金樽（zūn）：古代盛酒的器具，以金为饰。清酒：清醇的美酒。斗十千：一斗值十千钱（即万钱），形容酒美价高。\n玉盘：精美的食具。珍羞：珍贵的菜肴。羞：同“馐”，美味的食物。直：通“值”，价值。\n投箸：丢下筷子。箸（zhù）：筷子。不能食：咽不下。茫然：无所适从。\n太行：太行山。\n碧：一作“坐”。忽复：忽然又。\n多岐路，今安在：岔道这么多，如今身在何处？岐：一作“歧”，岔路。安：哪里。\n长风破浪：比喻实现政治理想。会：当。\n云帆：高高的船帆。船在海里航行，因天水相连，船帆好像出没在云雾之中。济：渡。', poem_appreciation = '诗的前四句写朋友出于对李白的深厚友情，出于对这样一位天才被弃置的惋惜，不惜金钱，设下盛宴为之饯行。“嗜酒见天真”的李白，要是在平时，因为这美酒佳肴，再加上朋友的一片盛情，肯定是会“一饮三百杯”的。然而，这一次他端起酒杯，却又把酒杯推开了；拿起筷子，却又把筷子撂下了。他离开座席，拔下宝剑，举目四顾，心绪茫然。停、投、拔、顾四个连续的动作，形象地显示了内心的苦闷抑郁，感情的激荡变化。\n\n　　接着两句紧承“心茫然”，正面写“行路难”。诗人用“冰塞川”、“雪满山”象征人生道路上的艰难险阻，具有比兴的意味。一个怀有伟大政治抱负的人物，在受诏入京、有幸接近皇帝的时候，皇帝却不能任用，被“赐金还山”，变相撵出了长安，这正像是遇到了冰塞黄河、雪拥太行。但是，李白并不是那种软弱的性格，从“拔剑四顾”开始，就表示着不甘消沉，而要继续追求。“闲来垂钓碧溪上，忽复乘舟梦日边。”诗人在心境茫然之中，忽然想到两位开始在政治上并不顺利，而最后终于大有作为的人物：一位是吕尚，九十岁在磻溪钓鱼，得遇文王；一位是伊尹，在受商汤聘前曾梦见自己乘舟绕日月而过。想到这两位历史人物的经历，又给诗人增加了信心。\n\n　　“行路难，行路难，多歧路，今安在？”吕尚、伊尹的遇合，固然增加了对未来的信心，但当他的思路回到眼前现实中来的时候，又再一次感到人生道路的艰难。离筵上瞻望前程，只觉前路崎岖，歧途甚多，不知道他要走的路，究竟在哪里。这是感情在尖锐复杂的矛盾中再一次回旋。但是倔强而又自信的李白，决不愿在离筵上表现自己的气馁。他那种积极用世的强烈要求，终于使他再次摆脱了歧路彷徨的苦闷，唱出了充满信心与展望的强音：“长风破浪会有时，直挂云帆济沧海！”他相信尽管前路障碍重重，但仍将会有一天要像南朝宋时宗悫（que）所说的那样，乘长风破万里浪，挂上云帆，横渡沧海，到达理想的彼岸。\n\n　　这首诗一共十四句，八十二个字，在七言歌行中只能算是短篇，但它跳荡纵横，具有长篇的气势格局。其重要的原因之一，就在于它百步九折地揭示了诗人感情的激荡起伏、复杂变化。诗的一开头，“金樽美酒”，“玉盘珍羞”，让人感觉似乎是一个欢乐的宴会，但紧接着“停杯投箸”、“拔剑四顾”两个细节，就显示了感情波涛的强烈冲击。中间四句，刚刚慨叹“冰塞川”、“雪满山”，又恍然神游千载之上，仿佛看到了吕尚、伊尹由微贱而忽然得到君主重用。诗人心理上的失望与希望、抑郁与追求，急遽变化交替。“行路难，行路难，多歧路，今安在？”四句节奏短促、跳跃，完全是急切不安状态下的内心独白，逼肖地传达出进退失据而又要继续探索追求的复杂心理。结尾二句，经过前面的反复回旋以后，境界顿开，唱出了高昂乐观的调子，相信他自己的理想抱负总有实现的一天。通过这样层层迭迭的感情起伏变化，既充分显示了黑暗污浊的政治现实对诗人的宏大理想抱负的阻遏，反映了由此而引起的诗人内心的强烈苦闷、愤郁和不平，同时又突出表现了诗人的倔强、自信和他对理想的执着追求，展示了诗人力图从苦闷中挣脱出来的强大精神力量。\n\n　　思想感情（中心)：抒发了作者怀才不遇的愤慨，也表达了作者人生前途充满乐观的豪迈气概。', poem_tags = '唐诗三百首,初中古诗,乐府,友情,宴饮,怀才不遇,励志,哲理' WHERE poem_title = '行路难·其一' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '在深秋一个秋高气爽的日子里，我独自伫立在橘子洲头，眺望着湘江碧水缓缓北流。\n看万千山峰全都变成了红色，一层层树林好像染过颜色一样，江水清澈澄碧，一艘艘大船乘风破浪，争先恐后。\n广阔的天空里鹰在矫健有力地飞，鱼在清澈的水里轻快地游着，万物都在秋光中争着过自由自在的生活。\n面对着无边无际的宇宙，（千万种思绪一齐涌上心头）我要问：这苍茫大地的盛衰兴废，由谁决定主宰呢?\n回想过去，我和我的同学，经常携手结伴来到这里游玩。在一起商讨国家大事，那无数不平凡的岁月至今还萦绕在我的心头。\n同学们正值青春年少，风华正茂；大家踌躇满志，意气奔放，正强劲有力。 \n评论国家大事，写出这些激浊扬清的文章，把当时那些军阀官僚看得如同粪土。\n可曾记得，当年我们在那浪花大得可以阻止飞奔而来的船舟的激流中一起游泳？', poem_notes = '沁园春：词牌名，“沁园”为东汉明帝为女儿沁水公主修建的皇家园林，据《后汉书 窦宪传》记载，沁水公主的舅舅窦宪倚仗其妹贵为皇后之势，竟强夺公主园林，后人感叹其事，多在诗中咏之，渐成“沁园春”这一词牌。\n湘（xiāng）江：一名湘水，湖南省最大的河流，源出广西壮族自治区陵川县南的海洋山，长1752里，向东北流贯湖南省东部，经过长沙，北入洞庭湖。　所以说是湘江北去。\n寒秋：就是深秋、晚秋。秋深已有寒意，所以说是寒秋。\n橘子洲：地名，又名水陆洲，是长沙城西湘江中一个狭长小岛，西面靠近岳麓山。南北长约11里，东西最宽处约一里。毛泽东七律《答友人》中所谓长岛，指此。自唐代以来，就是游览胜地。\n以上三句是说：在寒秋季节，独立在橘子洲头目送着湘江水汩汩北流。 \n万山：指湘江西岸岳麓山和附近许多山峰。\n层林尽染：山上一层层的树林经霜打变红，像染过一样。\n漫江：满江。漫：满，遍。\n舸（gě）：大船。这里泛指船只。\n争流：争着行驶。\n鹰击长空，鱼翔浅底：鹰在广阔的天空里飞，鱼在清澈的水里游。击，搏 击。这里形容飞得矫健有力。翔，本指鸟盘旋飞翔，这里形容鱼游得轻快自由。\n万类霜天竞自由：万物都在秋光中竞相自由地生活。万类：指一切生物。霜天：指深秋。\n怅寥廓(chàng liáo kuò）：面对广阔的宇宙惆怅感慨。怅：原意是失意，这里用来表达由深思而引发激昂慷慨的心绪。\n寥廓（liáo kuò）：广远空阔，这里用来描写宇宙之大。\n苍茫：旷远迷茫。\n主：主宰。\n沉浮：同“升沉”（上升和没落）意思相近，比喻事物盛衰、消长，这里指兴衰。由上文的俯看游鱼，仰看飞鹰，纳闷地寻思（“怅”）究竟是谁主宰着世间万物的升沉起伏。\n这句问话在这里可以理解为：在这军阀统治下的中国，到底应该由谁来主宰国家兴衰和人民祸福的命运呢？\n百侣：很多的伴侣。侣，这里指同学（也指战友)。\n峥嵘(zhēng róng）岁月稠：不平常的日子是很多的。峥嵘：山势高峻，这里是不平凡，不寻常的意思。稠：多。\n恰：适逢，正赶上。\n同学少年：毛泽东于1913年至1918年就读于湖南第一师范学校。1918年毛泽东和萧瑜、蔡和森等组织新民学会，开始了他早期的政治活动。\n风华正茂：风采才华正盛。\n书生：读书人，这里指青年学生。\n意气：意志和气概。\n挥斥方遒（qiú）：挥斥，奔放。《庄子·田子方》：“挥斥八极”。郭象注：“挥斥，犹纵放也。”遒，强劲有力。方：正。挥斥方遒，是说热情奔放，劲头正足。\n指点江山，激扬文字：评论国家大事，用文字来抨击丑恶的现象，赞扬美好的事物。写出激浊扬清的文章。指点，评论。江山，指国家。激扬，激浊扬清，抨击恶浊的，褒扬善良的。\n粪土当年万户侯：把当时的军阀官僚看得同粪土一样。粪土，作动词用，视……如粪土。万户侯，汉代设置的最高一级侯爵，享有万户农民的赋税。此借指大军阀，大官僚。万户，指侯爵封地内的户口，要向受封者缴纳租税，服劳役。\n中流：江心水深流急的地方。\n击水：作者自注：“击水：游泳。那时初学，盛夏水涨，几死者数，一群人终于坚持，直到隆冬，犹在江中。当时有一篇诗，都忘记了，只记得两句：自信人生二百年，会当水击三千里。”这里引用祖逖（tì）的“中流击楫”典故。（祖逖因为国家政权倾覆，时刻怀着振兴光复的心志。元帝就让他担任奋威将军、豫州刺史，供给他一千人的军粮，三千匹布，但不给战衣和兵器，让他自行招募士众。祖逖仍就率领随自己流亡的部属一百多家，渡过长江，到江心时他扣击船桨发誓说：“我祖逖不能平定中原并再次渡江回来的话，就像长江的水一去不返！”言辞激昂神色悲壮，众人都为他的誓言感慨赞叹。）这里指游泳。\n遏（è）：阻止。\n沁园春·长沙押OU（IU）韵。韵脚为：秋、头、透、流、由、游、稠、遒、侯、否、舟。', poem_appreciation = '毛泽东创作的秋景词《沁园春·长沙》，历来备受世人推崇，这是一首别具特色的秋之歌。该词脱尽了古人悲秋的窠臼，一扫衰颓萧瑟之气，以其绚丽多彩的湘江秋景、壮阔高远的深秋境界，引领读者去感受词人毛泽东的博大情怀和革命的豪情壮志，从而独步诗坛。\n\n　　《沁园春·长沙》是一首长调，他以传统的形式反映现代的生活内容，颇有创意，可见词人的匠心独运。词中描绘的“独立寒秋图”、“湘江秋景图”、“峥嵘岁月图”、“中流击水图”拼成了一幅色彩绚丽、生动活泼的全景式写意风景画。全词共分上、下两片，上片主要写寒秋景物，描绘了一幅壮丽的湘江寒秋图画，并即景抒情，大胆发问，“谁主沉浮”。词的开篇“独立寒秋,湘江北去，橘子洲头”，既点明了时令和地点，又为读者勾勒出了特定的环境。“独立”二字，进一步突现了词人雄立橘子洲头、凝望湘江奔流的英姿，一代伟人的青年风采由此跃然纸上，横空而出。接下来的七句由一个“看”字总领，通过“万山”、“漫江”、“霜天”、“飞鹰”、“游鱼”等一系列意象，不断地变换“看”的视角，将“远眺”、“近观”、“仰视”、“俯瞰”四个角度所见景物有机地揉合起来，形成了远近相间，动静结合，色彩鲜明的艺术张力，寒秋景物因此而生动、活泼、壮丽起来了。上片的后三句，通过一“怅”一“问”，则更道出了词人的雄心壮志，表现了他的博大胸怀。\n\n　　秋天，是万物凋零的季节，是萧杀、感伤的季节，是文人骚客容易产生“悲秋”情调的季节。“自古文人多悲秋”，“悲哉秋之为气也，萧瑟兮草木摇落而变衰”。而毛泽东同志面对“寒秋”，他欣然命笔的《沁园春·长沙》一词，则一反传统手法，描绘的是色彩斑斓的秋之壮景，展示出他阔大的胸襟和卓尔不群的抱负。正如王国维所说“一切景语皆情语”。\n\n　　“携来百侣曾游，忆往昔峥嵘岁月稠”。这一句开启下片，以“峥嵘”形容岁月，新颖，形象，将无形的不平凡的岁月，化为座座有形的峥嵘的山峰,给人以巍峨奇丽的崇高美。一个“忆”字，使词人从上片的独往旧地重游，自然引起对往昔生活的回忆。那时候，同学们正当青春年少，意气风发，才华横溢，激情奔放，敢说敢干，革命斗志十分旺盛。面对祖国大好河山，指点评论，激扬文字，视军阀统治者如粪土。一个：“记”字，词人为我们勾勒出了一幅“中流击水图”，手法极为夸张，壮志豪情万丈，一代敢于改造旧世界的革命青年形象，横空出世：他们有自信，“自信人生二百年，会当击水三千里”；他们有理想、有抱负，“以天下为己任”；他们有胆识、有志气，“粪土当年万户侯”，———他们就是主宰中国命运和前途的“同学少年”。\n\n　　清代的吴乔在《围炉诗话》中说：“夫诗以情为主，景为宾...情哀则景哀，情乐则景乐”。景是客观存在的，情则是主观的，因事而生的。情和景不是平行的，更不是对立的。作者在描写客观景物的时候，都是带着自己的主观情感去观察、描绘的，作者情感的哀乐则直接笼罩在他所描写的客观景物上，或哀或乐，或喜或悲。大多数人，尤其是古代作家,写寒秋常常离不开“其意萧条，山川寂寥”的萧杀之气，而毛泽东的《沁园春·长沙》中展示在读者眼前的是一片色彩鲜明、生机勃勃的壮丽秋景，一派“万类霜天竞自由”的活泼场面。在词中，我们可以感受到词人在以一种昂扬向上的精神，面对这大好的自然，有一种勇敢地投身于革命的风浪中，急流勇进，担负起主宰国家命运前途大任的大无畏精神。整首词的情调是慷慨激昂的，风格是豪爽奔放的。至此词中豪情的抒发与壮景的描写是和谐统一的，正所谓“情乐则景乐”。\n\n　　“独立寒秋”，毛泽东为我们描绘了一幅生动、活泼、壮丽的湘江秋景图；“浪遏飞舟”，毛泽东同志以天下为己任，于改造旧世界的壮志豪情，力透纸背，今天，我们诵读、鉴赏、品味《沁园春. 长沙》一词，面对祖国如此多娇的江山，我们仍能为一代伟人的才情所叹服。', poem_tags = '高中古诗,写景,抒怀,壮志' WHERE poem_title = '沁园春·长沙' AND poem_author = '毛泽东';
UPDATE edu_poem SET poem_translation = '巍峨的泰山，到底如何雄伟？走出齐鲁，依然可见那青青的峰顶。\n神奇自然汇聚了千种美景，山南山北分隔出清晨和黄昏。\n层层白云，荡涤胸中沟壑；翩翩归鸟，飞入赏景眼圈。\n定要登上泰山顶峰，俯瞰群山，豪情满怀。', poem_notes = '岱宗：泰山亦名岱山或岱岳，五岳之首，在今山东省泰安市城北。古代以泰山为五岳之首，诸山所宗，故又称“岱宗”。历代帝王凡举行封禅大典，皆在此山，这里指对泰山的尊称。夫：读“fú”。句首发语词，无实在意义，语气词，强调疑问语气。如何：怎么样。\n齐、鲁：古代齐鲁两国以泰山为界，齐国在泰山北，鲁国在泰山南。原是春秋战国时代的两个国名，在今山东境内，后用齐鲁代指山东地区。青未了：指郁郁苍苍的山色无边无际，浩茫浑涵，难以尽言。青：指苍翠、翠绿的美好山色。未了：不尽，不断。\n造化：大自然。钟：聚集。神秀：天地之灵气，神奇秀美。\n阴阳：阴指山的北面，阳指山的南面。这里指泰山的南北。割：分。夸张的说法。此句是说泰山很高，在同一时间，山南山北判若早晨和晚上。昏晓：黄昏和早晨。极言泰山之高，山南山北因之判若清晓与黄昏，明暗迥然不同。\n荡胸：心胸摇荡。曾：同“层”，重叠。\n决眦（zì）：眦：眼角。眼角（几乎）要裂开。这是由于极力张大眼睛远望归鸟入山所致。决：裂开。入：收入眼底，即看到。\n会当：终当，定要。凌：登上。凌绝顶，即登上最高峰。\n小：形容词的意动用法，意思为“以······为小，认为······小”。', poem_appreciation = '这首诗是杜甫青年时代的作品，充满了诗人青年时代的浪漫与激情。全诗没有一个“望”字，却紧紧围绕诗题“望岳”的“望”字着笔，由远望到近望，再到凝望，最后是俯望。诗人描写了泰山雄伟磅礴的气象，抒发了自己勇于攀登，傲视一切的雄心壮志，洋溢着蓬勃向上的朝气。\n\n　　首句“岱宗夫如何？”写乍一望见泰山时，高兴得不知怎样形容才好的那种揣摹劲和惊叹仰慕之情，非常传神。岱是泰山的别名，因居五岳之首，故尊为岱宗。“夫如何”，就是“到底怎么样呢？”“夫”字在古文中通常是用于句首的语气助词，这里把它融入诗句中，是个新创，很别致。这个“夫”字，虽无实在意义，却少它不得，所谓“传神写照，正在阿堵中”。可谓匠心独具。\n\n　　接下来“齐鲁青未了”一句，是经过一番揣摹后得出的答案。它没有从海拔角度单纯形容泰山之高，也不是像谢灵运《泰山吟》那样用“崔崒刺云天”这类一般化的语言来形容，而是别出心裁地写出自己的体验──在古代齐鲁两大国的国境外还能望见远远横亘在那里的泰山，以距离之远来烘托出泰山之高。泰山之南为鲁，泰山之北为齐，所以这一句描写出的地理特点，在写其他山岳时不能挪用。明代莫如忠《登东郡望岳楼》特别提出这句诗，并认为无人能继。\n\n　　“造化钟神秀，阴阳割昏晓”两句，写近望中所见泰山的神奇秀丽和巍峨高大的形象，是上句“青未了”的注脚。一个“钟”宇把天地万物一下写活了，整个大自然如此有情致，把神奇和秀美都给了泰山。山前向日的一面为“阳”，山后背日的一面为“阴”（山南水北为“阳”，山北水南为阴），由于山高，天色的一昏一晓被割于山的阴、阳面，所以说“割昏晓”。这本是十分正常的自然现象，可诗人妙笔生花，用一个“割”字，则写出了高大的泰山一种主宰的力量，这力量不是别的，泰山以其高度将山南山北的阳光割断，形成不同的景观，突出泰山遮天蔽日的形象。这里诗人此用笔使静止的泰山顿时充满了雄浑的力量，而那种“语不惊人死不休”的创作风格，也在此得到显现。\n\n　　“荡胸生曾云，决眦入归鸟”两句，是写细望。见山中云气层出不穷，故心胸亦为之荡漾。“决眦”二字尤为为传神，生动地体现了诗人在这神奇缥缈的景观而前像着了迷似的，想把这一切看个够，看个明白，因而使劲地睁大眼睛张望，故感到眼眶有似决裂。这情景使泰山迷人的景色表现得更为形象鲜明。“归鸟”是投林还巢的鸟，可知时已薄暮，诗人还在望。其中蕴藏着诗人对祖国河山的热爱和对祖国山河的赞美之情。\n\n　　末句的“会当凌绝顶，一览众山小”两句，写诗人从望岳产生了登岳的想法，体现了中华民族自强不息的仙字精神。此联号为绝响，再一次突出了泰山的高峻，写出了雄视一切的雄姿和气势，也表现出诗人的心胸气魄。“会当”是唐人口语，意即“一定要”。如果把“会当”解作“应当”，便欠准确，神气索然。众山的小和高大的泰山进行对比，表现出诗人不怕困难、敢于攀登绝顶、俯视一切的雄心和气概。 这正是杜甫能够成为一个伟大诗人的关键所在， 也是一切有所作为的人们所不可缺少的。 这就是这两句诗一直为人们所传诵的原因。正因为泰山的崇高伟大不仅是自然的也是人文的，所以登上的极顶的想望本身，当然也具备了双重的含义。\n\n　　全诗以诗题中的“望”字统摄全篇，句句写望岳，但通篇并无一个“望”字，而能给人以身临其境之感，可见诗人的谋篇布局和艺术构思是精妙奇绝的。这首诗寄托虽然深远，但通篇只见登览名山之兴会，丝毫不见刻意比兴之痕迹。若论气骨峥嵘，体势雄浑，更以后出之作难以企及。', poem_tags = '唐诗三百首,初中古诗,写景,写山,写鸟,励志,哲理,早教古诗100首' WHERE poem_title = '望岳' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '空旷的群山沐浴了一场新雨，夜晚降临，空气凉爽，仿佛已经到了秋天。\n皎皎明月从松隙间洒下清光，清清泉水在山石上淙淙淌流。\n竹林喧响知是洗衣姑娘归来，莲叶轻摇想是上游荡下轻舟。\n春日的芳菲不妨任随它消歇，秋天的山中王孙自可以久留。', poem_notes = '暝（míng）：日落，天色将晚。\n空山：空旷，空寂的山野。新：刚刚。\n清泉石上流：写的正是雨后的景色。\n竹喧：竹林中笑语喧哗。喧：喧哗，这里指竹叶发出沙沙声响。浣（huàn）女：洗衣服的姑娘。浣：洗涤衣物。\n随意：任凭。春芳：春天的花草。歇：消散，消失。\n王孙：原指贵族子弟，后来也泛指隐居的人。留：居。', poem_appreciation = '这首诗为山水名篇，于诗情画意之中寄托着诗人高洁的情怀和对理想境界的追求。\n\n　　“空山新雨后，天气晚来秋。”诗中明确写有浣女渔舟，诗人怎下笔说是“空山”呢？原来山中树木繁茂，掩盖了人们活动的痕迹，正所谓“空山不见人，但闻人语响”（《鹿柴》）。由于这里人迹罕至，“峡里谁知有人来，世中遥望空云山”（《桃源行》）；自然不知山中有人来了。“空山”两字点出此外有如世外桃源，山雨初霁，万物为之一新，又是初秋的傍晚，空气之清新，景色之美妙，可以想见。\n\n　　“明月松间照，清泉石上流。”天色已暝，却有皓月当空；群芳已谢，却有青松如盖。山泉清冽，淙淙流泻于山石之上，有如一条洁白无瑕的素练，在月光下闪闪发光，多么幽清明净的自然美啊！王维的《济上四贤咏》曾经赞叹两位贤士的高尚情操，谓其“息阴无恶木，饮水必清源”。诗人自己也是这种心志高洁的人，他曾说:”宁息野树林，宁饮涧水流，不用坐梁肉，崎岖见王侯。”（《献始兴公》）这月下青松和石上清泉，不正是他所追求的理想境界吗？这两句写景如画，随意洒脱，毫不着力。像这样又动人又自然的写景，达到了艺术上炉火纯青的地步，非一般人所能学到。　“竹喧归浣女，莲动下渔舟。”竹林里传来了一阵阵的歌声笑语，那是一些天真无邪的姑娘们洗罢衣服笑逐着归来了；亭亭玉立的荷叶纷纷向两旁披分，掀翻了无数珍珠般晶莹的水珠，那是顺流而下的渔舟划破了荷塘月色的宁静。在这青松明月之下，在这翠竹青莲之中，生活着这样一群无忧无虑、勤劳善良的人们。这纯洁美好的生活图景，反映了诗人过安静纯朴生活的理想，同时也从反面衬托出他对污浊官场的厌恶。这两句写的很有技巧，而用笔不露痕迹，使人不觉其巧。诗人先写“竹喧““莲动“，因为浣女隐在竹林之中，渔舟被莲叶遮蔽，起初未见，等到听到竹林喧声，看到莲叶纷披，才发现浣女、莲舟。这样写更富有真情实感，更富有诗意。\n\n　　诗的中间两联同是写景，而各有侧重。颔联侧重写物，以物芳而明志洁；颈联侧重写人，以人和而望政通。同时，二者又互为补充，泉水、青松、翠竹、青莲，可以说都是诗人高尚情操的写照，都是诗人理想境界的环境烘托。\n\n　　既然诗人是那样地高洁，而他在那貌似“空山”之中又找到了一个称心的世外桃源，所以就情不自禁地说：“随意春芳歇，王孙自可留！”本来，《楚辞·招隐士》说：“王孙兮归来，山中兮不可久留！”诗人的体会恰好相反，他觉得“山中”比“朝中”好，洁净纯朴，可以远离官场而洁身自好，所以就决然归隐了。\n\n　　这首诗一个重要的艺术手法，是以自然美来表现诗人的人格美和一种理想中的社会之美。表面看来，这首诗只是用“赋”的方法模山范水，对景物作细致感人的刻画，实际上通篇都是比兴。诗人通过对山水的描绘寄慨言志，含蕴丰富，耐人寻味。', poem_tags = '唐诗三百首,山水,写景,写人,秋雨,早教古诗100首' WHERE poem_title = '山居秋暝' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '秋后的蝉叫得是那样地凄凉而急促，面对着长亭，正是傍晚时分，一阵急雨刚停住。在京都城外设帐饯别，却没有畅饮的心绪，正在依依不舍的时候，船上的人已催着出发。握着手互相瞧着，满眼泪花，直到最后也无言相对，千言万语都噎在喉间说不出来。想到这回去南方，这一程又一程，千里迢迢，一片烟波，那夜雾沉沉的楚地天空竟是一望无边。\n自古以来多情的人最伤心的是离别，更何况又逢这萧瑟冷落的秋季，这离愁哪能经受得了！谁知我今夜酒醒时身在何处？怕是只有杨柳岸边，面对凄厉的晨风和黎明的残月了。这一去长年相别，相爱的人不在一起，我料想即使遇到好天气、好风景，也如同虚设。即使有满腹的情意，又能和谁一同欣赏呢？', poem_notes = '长亭：古代在交通要道边每隔十里修建一座长亭供行人休息，又称“十里长亭”。靠近城市的长亭往往是古人送别的地方。\n凄切：凄凉急促。\n骤雨：急猛的阵雨。\n都门：国都之门。这里代指北宋的首都汴京（今河南开封）。\n帐饮：在郊外设帐饯行。\n无绪：没有情绪。\n兰舟：古代传说鲁班曾刻木兰树为舟（南朝梁任昉《述异记》。这里用做对船的美称。\n凝噎：喉咙哽塞，欲语不出的样子。\n去去：重复“去”字，表示行程遥远。\n暮霭：傍晚的云雾。沈沈：即“沉沉”，深厚的样子。楚天：指南方楚地的天空。\n暮霭沈沈（沉沉）楚天阔：傍晚的云雾笼罩着南天，深厚广阔，不知尽头。\n今宵：今夜。\n经年：年复一年。\n纵：即使。风情：情意。男女相爱之情，深情蜜意。情：一作“流”。\n更：一作“待”。', poem_appreciation = '词的上片写一对恋人饯行时难分难舍的别情。起首三句写别时之景，点明了地点和节序。《礼记·月令》云：“孟秋之月，寒蝉鸣。”可见时间大约在农历七月。然而词人并没有纯客观地铺叙自然景物，而是通过景物的描写，氛围的渲染，融情入景，暗寓别意。时当秋季，景已萧瑟；且值天晚，暮色阴沉；而骤雨滂沱之后，继之以寒蝉凄切：词人所见所闻，无处不凄凉。加之当中“对长亭晚”一句，句法结构是一、二、一，极顿挫吞咽之致，更准确地传达了这种凄凉况味。\n\n　　前三句通过景色的铺写，也为后两句的“无绪”和“催发”设下伏笔。“都门帐饮”，语本江淹《别赋》：“帐饮东都，送客金谷。”他的恋人在都门外长亭摆下酒筵给他送别，然而面对美酒佳肴，词人毫无兴致。可见他的思绪正专注于恋人，所以词中接下去说：“留恋处、兰舟催发”。这七个字完全是写实，然却以精炼之笔刻画了典型环境与典型心理：一边是留恋情浓，一边是兰舟催发，这样的矛盾冲突何其尖锐！林逋《相思令》云：“君泪盈，妾泪盈，罗带同心结未成，江头潮欲平。”仅是暗示船将启碇，情人难舍。刘克庄《长相思》云：“烟迢迢，水迢迢，准拟江边驻画挠，舟人频报潮。”虽较明显，但仍未脱出林词窠臼。可是这里的“兰舟催发”，却以直笔写离别之紧迫，虽没有他们含蕴缠绵，但却直而能纤，更能促使感情的深化。于是后面便迸出“执手相看泪眼，竟无语凝噎”二句。语言通俗而感情深挚，形象逼真，如在眼前。寥寥十一字，真是力敌千钧！后来传奇戏曲中常有“流泪眼看流泪眼，断肠人对断肠人”的唱词，然却不如柳词凝炼有力。那么词人凝噎在喉的是什么话呢？“念去去”二句便是他的内心独白。词是一种依附于音乐的抒情诗体，必须讲究每一个字的平仄阴阳，而去声字尤居关键地位。这里的去声“念”字用得特别好。清人万树《词律发凡》云：“名词转折跌荡处，多用去声，何也？三声之中，上、入二者可以作平，去则独异。……当用去者，非去则激不起。”此词以去声“念”字作为领格，上承“凝噎”而自然一转，下启“千里”以下而一气流贯。“念”字后“去去”二字连用，则愈益显示出激越的声情，读时一字一顿，遂觉去路茫茫，道里修远。“千里”以下，声调和谐，景色如绘。既日“烟波”，又日“暮霭”，更曰“沉沉”，着色可谓浓矣；既曰“千里”，又曰“阔”，空间可谓广矣。在如此广阔辽远的空间里，充满了如此浓密深沉的烟霭，其离愁之深，令人可以想见。\n\n　　上片正面话别，到此结束；下片则宕开一笔，先作泛论，从个别说到一般，得出一条人生哲理：“多情自古伤离别”。意谓伤离惜别，并不自我始，自古皆然。接以“更那堪冷落清秋节”一句，则为层层加码，极言时当冷落凄凉的秋季，离情更甚于常时。“清秋节”一辞，映射起首三句，前后照应，针线极为绵密；而冠以“更那堪”三个虚字，则加强了感情色彩，比起首三句的以景寓情更为明显、深刻。“今宵”三句蝉联上句而来，是全篇之警策，后来竟成为苏轼相与争胜的对象。据俞文豹《吹剑录》云：“东坡在玉堂日，有幕士善歌，因问：‘我词何如柳七？’对日：‘柳郎中词，只合十七八女郎，执红牙板，歌“杨柳岸晓风残月”。学士词，须关西大汉，（执）铜琵琶，铁绰板，唱“大江东去”。’”这三句本是想象今宵旅途中的况味：一舟临岸，词人酒醒梦回，只见习习晓风吹拂萧萧疏柳，一弯残月高挂杨柳梢头。整个画面充满了凄清的气氛，客情之冷落，风景之清幽，离愁之绵邈，完全凝聚在这画面之中。比之上片结尾二句，虽同样是写景，写离愁，但前者仿佛是泼墨山水，一片苍茫；这里却似工笔小帧，无比清丽。词人描绘这清丽小帧，主要采用了画家所常用的点染笔法。清人刘熙载在《艺概》中说：“‘多情自古伤离别，更那堪冷落清秋节。今宵酒醒何处？杨柳岸、晓风残月。’上二句点出离别冷落，‘今宵’二句乃就上二句意染之。点染之间，不得有他语相隔，隔则警句亦成死灰矣。”也就是说，这四句密不可分，相互烘托，相互陪衬，中间若插上另外一句，就破坏了意境的完整性，形象的统一性，而后面这两个警句，就将失去光彩。\n\n　　“此去经年”四句，构成另一种情境。因为上面是用景语，此处则改用情语。他们相聚之日，每逢良辰好景，总感到欢娱；可是别后非止一日，年复一年，纵有良辰好景，也引不起欣赏的兴致，只能徒增帐触而已。“此去”二字，遥应上片“念去去”；“经年”二字，近应“今宵”，在时间与思绪上均是环环相扣，步步推进，可见结构之严密。“便纵有千种风情，更与何人说”，益见钟情之殷，离愁之深。而归纳全词，犹如奔马收缰，有住而不住之势；又如众流归海，有尽而未尽之致。其以问句作结，更留有无穷意味，耐人寻绎。\n\n　　耆卿词长于铺叙，有些作品失之于平直浅俗，然而此词却能做到“曲处能直，密处能疏，鼻处能平，状难状之景，达难达之情，而出之以自然”（冯煦《六十一家词选例言》论柳永词）。像“兰舟催发”一语，可谓兀傲排鼻，但其前后两句，却于沉郁之中自饶和婉。“今宵”三句，寄情于景，可称曲笔，然其前后诸句，却似直抒胸臆。前片自第四句起，写情至为缜密，换头却用提空之笔，从远处写来，便显得疏朗清远。词人在章法上不拘一格，变化多端，因而全词起伏跌宕，声情双绘，付之歌喉，亦能奕奕动人。', poem_tags = '宋词三百首,宋词精选,高中古诗,婉约,离别,爱情,写景,惜别' WHERE poem_title = '雨霖铃·寒蝉凄切' AND poem_author = '柳永';
UPDATE edu_poem SET poem_translation = '游玩蕲水的清泉寺，寺庙在兰溪的旁边，溪水向西流淌。山脚下刚生长出来的幼芽浸泡在溪水中，松林间的沙路被雨水冲洗的一尘不染，傍晚，下起了小雨，布谷鸟的叫声从松林中传出。\n谁说人生就不能再回到少年时期？ 门前的溪水还能向西边流淌！不要在老年感叹时光的飞逝啊！', poem_notes = '蕲qí水：县名，今湖北浠水县。\n浸：泡在水中。\n萧萧：形容雨声。\n子规：杜鹃，又叫杜宇、 布谷、子规、望帝、蜀鸟等。\n无再少：不能回到少年时代。\n白发：老年。\n唱黄鸡：感慨时光的流逝。因黄鸡可以报晓，表示时光的流逝。', poem_appreciation = '这是一首触景生慨、蕴含人生哲理的小词，体现了作者热爱生活、乐观旷达的性格。\n\n　　上片写暮春游清泉寺所见之幽雅景致。山下溪水潺湲，溪边的兰草才抽出嫩芽，蔓延浸泡在溪水中。松柏夹道的沙石小路，经过春雨的冲刷，洁净无泥。时值日暮，松林间的杜鹃在潇潇细雨中啼叫着。这是一幅多么幽美宁静的山林景致啊！首七字既点出游清泉寺时的时令，也点明兰溪之名的由来。“浸”字与“皋兰被径兮，斯路渐”（《楚辞·招魂》）中的“渐”字一样，均有“蔓延”之意。兰草此际始出“芽”，其芽尚“短”，但生机勃勃，长势很快，已由岸边蔓延至溪水中矣。杜鹃啼声凄婉，本是易引发羁旅之愁的。但作者此际漫步溪边，触目无非生意，浑然忘却尘世的喧嚣和官场的污秽，心情是愉悦的。兼之疾病始愈，有医者相伴游赏，故杜鹃的啼叫亦未能搅乱作者此时之清兴。总之，上片只是写实景，其内心所唤起的应是对大自然的喜爱及对人生的回味，这就引出了下片的对人生的哲思。\n\n　　下片就眼前“溪水西流”之景生发感慨和议论。“百川东到海，何时复西归”（汉·《长歌行》）。“花有重开日，人无再少时”。江水的东流不返，正如人的青春年华只有一次一样，都是不可抗拒的自然规律，曾使古今无数人为之悲叹。而作者此际面对着眼前西流的兰溪水，却产生奇妙的遐想：既然溪水可以西流，人为什么不可以重新拥有青春年华呢？人生之“再少”，非如道教徒所企求的“返老还童”，乃是说应保持一种年轻的乐观的心态。因为人并不能改变这个世界；人所能改变的，仅仅是对这个世界的态度和看法。白居易《醉歌》诗有“谁道使君不解饮，听唱黄鸡与白日。黄鸡催晓丑时鸣，白日催年酉前没。腰间红绶系未稳，镜里朱颜看已失”诸句，乃嗟老叹衰之词也。作者尾句反用其意，认为即使到了暮年，也不应有那种“黄鸡催晓”、朱颜已失的衰颓心态，体现了作者在贬谪期间旷达振作的精神状态。\n\n　　全词的特点是即景抒慨，写景纯用白描，细致淡雅；抒慨昂扬振拔，富有哲理。此前，作者于熙宁六年（1073）曾有诗云：“江边身世两悠悠，久与沧波共白头。造物亦知人易老，故教江水向西流”（《八月十五日看潮五绝》其三）。乃是在钱塘潮来江水回流时所生发的感慨，与此词旨趣有相近之处。但当时作者是自请外任，以太常博士直史馆的头衔到美丽富庶的杭州作通判，是京官下派作地方官，仕途失意之感并不浓。此时则是以待罪之官的身份被安置在偏僻的黄州，孤寂苦楚的心情不是轻易可以摆脱的。因此，此词下片所表现出来的对青春活力的呼唤，对老而无为的观点的否弃，便显得尤为可贵。可以说，这种在“命压人头不奈何”的逆境中的乐观奋发的精神，是苏轼之所以受到后世尊崇的重要原因之一。', poem_tags = '宋词三百首,小学古诗,写景,感叹,人生,哲理' WHERE poem_title = '浣溪沙·游蕲水清泉寺' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '我姑且抒发一下少年的豪情壮志，左手牵着黄犬，右臂擎着苍鹰，戴着华美鲜艳的帽子，穿着貂皮做的衣服，带着上千骑的随从疾风般席卷平坦的山冈。为了报答满城的人跟随我出猎的盛情厚意，我要像孙权一样，亲自射杀猛虎。\n我痛饮美酒，心胸开阔，胆气更为豪壮，（虽然）两鬓微微发白，（但）这又有何妨？什么时候皇帝会派人下来，就像汉文帝派遣冯唐去云中赦免魏尚的罪（一样信任我）呢？我将使尽力气拉满雕弓就像满月一样，朝着西北瞄望，射向西夏军队。', poem_notes = '江城子：词牌名。\n密州：今山东诸城。\n老夫：作者自称，时年三十八。\n聊：姑且，暂且。\n狂：豪情。\n左牵黄，右擎苍：左手牵着黄犬，右臂擎着苍鹰，形容围猎时用以追捕猎物的架势。\n黄：黄犬。\n苍：苍鹰。\n锦帽貂裘：名词作动词使用，头戴着华美鲜艳的帽子。貂裘，身穿貂鼠皮衣。是汉羽林军穿的服装。\n千骑卷平冈：形容马多尘土飞扬，把山冈像卷席子一般掠过。\n千骑：上千个骑马的人，形容随从乘骑之多。\n倾城：全城的人都出来了。形容随观者之众。\n太守：指作者自己。\n看孙郎：孙郎，孙权。这里借以自喻。\n酒酣胸胆尚开张：极兴畅饮，胸怀开阔，胆气横生。\n尚：更。\n微霜：稍白。\n节：兵符，传达命令的符节。\n持节：是奉有朝廷重大使命。\n云中：汉时郡名，今内蒙古自治区托克托县一带，包括山西省西北一部分地区。\n会：定将。\n挽：拉。\n雕弓：弓背上有雕花的弓。\n满月：圆月。\n天狼：星名，又称犬星，旧说指侵掠，这里隐指西夏。词中以之隐喻侵犯北宋边境的辽国与西夏。', poem_appreciation = '出猎对于苏轼这样的文人来说，或许是偶然的一时豪兴，但他平素报国立功的信念却因这次小试身手而得到鼓舞，以至信心十足地要求前赴西北疆场弯弓杀敌了。苏轼任密州知州刚四十岁。他是四年前因与王安石政见不合自愿请求外任，自杭州来至这北方边郡的。除了他在各地任上致力于地方政绩外，一直要求大用于世。当时西北边事紧张。熙宁三年（1070），西夏大举进攻环、庆二州。四年，陷抚宁诸城。“会挽雕弓如满月，西北望，射天狼。”就是指宋与西夏的战事。\n\n　　这首词上片出猎，下片请战，不但场面热烈，音节嘹亮，而且情豪志壮，顾盼自雄，精神百倍。同苏轼其他豪放词相比，它是一首豪而能壮的壮词。把词中历来软媚无骨的儿女情换成有胆有识、孔武刚建的英雄气了。苏轼对此也颇为自负，他在密州写给好友鲜于侁的信中说：“近却颇作小词，虽无柳七郎风味，亦自是一家。数日前，猎于郊外，所获颇多。作是一阕，令东州壮士抵掌顿足而歌之，吹笛击鼓以为节，颇壮观也。”就是指的这首词。', poem_tags = '宋词三百首,初中古诗,豪放,狩猎,爱国,猖狂' WHERE poem_title = '江城子·密州出猎' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '两只黄鹂在翠绿的柳树间婉转地歌唱，一队整齐的白鹭直冲向蔚蓝的天空。\n我坐在窗前，可以望见西岭上堆积着终年不化的积雪，门前停泊着自万里外的东吴远行而来的船只。', poem_notes = '西岭：西岭雪山。\n千秋雪：指西岭雪山上千年不化的积雪。\n泊：停泊。\n东吴：古时候吴国的领地，江苏省一带。\n万里船：不远万里开来的船只。', poem_appreciation = '赏析 　　“两个黄鹂鸣翠柳，一行白鹭上青天”两个黄鹂在鸣，这就有声音了。“一行白鹭上青天”，这就有一个行为、一个行动。一横一纵，“两”和“一”相对；一横一纵，就展开了一个非常明媚的自然景色。这句诗中以“鸣”字最为传神，运用了拟人的手法把黄鹂描写的更加生动活泼。那么接下来杜甫又讲到“窗含西岭千秋雪”，我的窗子里包含了岷山千万年累积的雪，西面的岷山，是千年的积雪的一个岷山。“门泊东吴万里船”我的门口停着长万里的船只。这样就形成了一迎一送，迎这个积雪的山头来进入你的视野，送这个船到下游去。那么这个“万里船”能够通行，也说明这个“安史之乱”已经进入了尾声了，已经接近要平定了，这个时候那航船也可以通行了，做生意的人可以在这条江上来来往往了。 那么这么一首诗，它本身是非常有修饰之美的，在加之它四句都是对仗的。从六朝开始就有绝句，到了唐代以后绝句就形成了非常圆熟的一种艺术，我们很多著名的诗都用绝句。绝句就是四句，四句往往或者四句都不对仗，或者四句前面两句写景对仗后面两句抒情不对仗，或者是前面两句不对仗后面两句对仗，那么现在他这首诗四句都对仗，可以说是一首非常工整的、写得非常认真的一首诗。杜甫有一个写诗的时候让人“语不惊人誓不休”，所以他就把这首诗千锤百炼。 ▲', poem_tags = '小学古诗,写景,写雪,写鸟,早教古诗100首' WHERE poem_title = '绝句' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '在秋夜里烛光映照着画屏，手拿着小罗扇扑打萤火虫。\n夜色里的石阶清凉如冷水，静坐寝宫凝视牛郎织女星。', poem_notes = '秋夕：秋天的夜晚。\n银烛：银色而精美的蜡烛。银，一作“红”。画屏：画有图案的屏风。\n轻罗小扇：轻巧的丝质团扇。流萤：飞动的萤火虫。\n天阶：露天的石阶。天，一作“瑶”。\n坐看：坐着朝天看。坐：一作“卧”。牵牛织女星：两个星座的名字，指牵牛星、织女星。亦指古代神话中的人物牵牛和织女。', poem_appreciation = '此诗写失意宫女孤独的生活和凄凉的心境。\n\n　　前两句已经描绘出一幅深宫生活的图景。在一个秋天的晚上，银白色的蜡烛发出微弱的光，给屏风上的图画添了几分暗淡而幽冷的色调。这时，一个孤单的宫女正用小扇扑打着飞来飞去的萤火虫。“轻罗小扇扑流萤”，这一句十分含蓄，其中含有三层意思：第一，古人说腐草化萤，虽然是不科学的，但萤总是生在草丛冢间那些荒凉的地方。如今，在宫女居住的庭院里竟然有流萤飞动，宫女生活的凄凉也就可想而知了。第二，从宫女扑萤的动作可以想见她的寂寞与无聊。她无事可做，只好以扑萤来消遣她那孤独的岁月。她用小扇扑打着流萤，一下一下地，似乎想驱赶包围着她的孤冷与索寞，但这是无用的。第三，宫女手中拿的轻罗小扇具有象征意义，扇子本是夏天用来挥风取凉的，秋天就没用了，所以古诗里常以秋扇比喻弃妇。相传汉成帝妃班婕妤为赵飞燕所谮，失宠后住在长信宫，写了一首《怨歌行》：“新裂齐纨素，皎洁如霜雪。裁为合欢扇，团团似明月。出入君怀袖，动摇微风发。常恐秋节至，凉飙夺炎热。弃捐箧笥中，恩情中道绝。”此说未必可信，但后来诗词中出现团扇、秋扇，便常常和失宠的女子联系在一起了。如王昌龄的《长信秋词》：“奉帚平明金殿开，且将团扇共徘徊”，王建的《宫中调笑》：“团扇，团扇，美人病来遮面”，都是如此。这首诗中的“轻罗小扇”，也象征着持扇宫女被遗弃的命运。\n\n　　第三句，“天阶夜色凉如水”。“天阶”指皇宫中的石阶。“夜色凉如水”暗示夜已深沉，寒意袭人，该进屋去睡了。可是宫女依旧坐在石阶上，仰视着天河两旁的牵牛星和织女星。民间传说，织女是天帝的孙女，嫁与牵牛，每年七夕渡河与他相会一次，有鹊为桥。汉代《古诗十九首》中的“迢迢牵牛星”，就是写他们的故事。宫女久久地眺望着牵牛织女，夜深了还不想睡，这是因为牵牛织女的故事触动了她的心，使她想起自己不幸的身世，也使她产生了对于真挚爱情的向往。可以说，满怀心事都在这举首仰望之中了。\n\n　　梅圣俞说：“必能状难写之景如在目前，含不尽之意见于言外，然后为至矣。”（见《六一诗话》）这两句话恰好可以说明此诗在艺术上的特点。一、三句写景，把深宫秋夜的景物十分逼真地呈现在读者眼前。“冷”字，形容词当动词用，很有气氛。“凉如水”的比喻不仅有色感，而且有温度感。二、四两句写宫女，含蓄蕴藉，很耐人寻味。诗中虽没有一句抒情的话，但宫女那种哀怨与期望相交织的复杂感情见于言外，从一个侧面反映了封建时代妇女的悲惨命运。\n\n　　这首诗写失意宫女生活的孤寂幽怨。首句写秋景，用一“冷”字，暗示寒秋气氛，又衬出主人公内心的孤凄。二句写借扑萤以打发时光，排遣愁绪。三句写夜深仍不能眠，以待临幸，以天街如水，暗喻君情如冰。末句借羡慕牵牛织女，抒发心中悲苦。', poem_tags = '唐诗三百首,写景,秋天,七夕节,闺怨,早教古诗100首' WHERE poem_title = '秋夕' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '听一支新曲喝一杯美酒，还是去年的天气旧日的亭台，西落的夕阳何时再回来？\n那花儿落去我也无可奈何，那归来的燕子似曾相识，在小园的花径上独自徘徊。', poem_notes = '浣溪沙：唐玄宗时教坊曲名，后用为词调。沙，一作“纱”。\n一曲：一首。因为词是配合音乐唱的，故称“曲”。新词，刚填好的词，意指新歌。酒一杯，一杯酒。\n去年天气旧亭台：是说天气、亭台都和去年一样。去年天气：跟去年此日相同的天气。旧亭台，曾经到过的或熟悉的亭台楼阁。旧，旧时。\n夕阳：落日。西下：向西方地平线落下。几时回：什么时候回来。\n无可奈何：不得已，没有办法。\n似曾相识：好像曾经认识。形容见过的事物再度出现。后用作成语，即出自晏殊此句。燕归来：燕子从南方飞回来。燕归来，春中常景，在有意无意之间。\n小园香径：花草芳香的小径，或指落花散香的小径。因落花满径，幽香四溢，故云香径。香径，带着幽香的园中小径。独：副词，用于谓语前，表示“独自”的意思。徘徊：来回走。', poem_appreciation = '这是晏殊词中最为脍炙人口的篇章。此词虽含伤春惜时之意，却实为感慨抒怀之情。词之上片绾合今昔，叠印时空，重在思昔；下片则巧借眼前景物，重在伤今。全词语言圆转流利，通俗晓畅，清丽自然，意蕴深沉，启人神智，耐人寻味。词中对宇宙人生的深思，给人以哲理性的启迪和美的艺术享受。\n\n　　起句“一曲新词酒一杯，去年天气旧亭台。”写对酒听歌的现境。从复叠错综的句式、轻快流利的语调中可以体味出，词人面对现境时，开始是怀着轻松喜悦的感情，带着潇洒安闲的意态的，似乎主人公十分醉心于宴饮涵咏之乐。的确，作为安享尊荣而又崇文尚雅的“太平宰相”，以歌侑酒，是作者习于问津、也乐于问津的娱情遣兴方式之一。但边听边饮，这现境却又不期然而然地触发对“去年”所历类似境界的追忆：也是和“今年”一样的暮春天气，面对的也是和眼前一样的楼台亭阁，一样的清歌美酒。然而，似乎一切依旧的表象下又分明感觉到有的东西已经起了难以逆转的变化，这便是悠悠流逝的岁月和与此相关的一系列人事。此句中正包蕴着一种景物依旧而人事全非的怀旧之感。在这种怀旧之感中又糅合着深婉的伤今之情。这样，作者纵然襟怀冲澹，又怎能没有些微的伤感呢？于是词人不由得从心底涌出这样的喟叹：“夕阳西下几时回？”夕阳西下，是眼前景。但词人由此触发的，却是对美好景物情事的流连，对时光流逝的怅惘，以及对美好事物重现的微茫的希望。这是即景兴感，但所感者实际上已不限于眼前的情事，而是扩展到整个人生，其中不仅有感性活动，而且包含着某种哲理性的沉思。夕阳西下，是无法阻止的，只能寄希望于它的东升再现，而时光的流逝、人事的变更，却再也无法重复。细味“几时回”三字，所折射出的似乎是一种企盼其返、却又情知难返的纡细心态。\n\n　　下片仍以融情于景的笔法申发前意。“无可奈何花落去，似曾相识燕归来。”为天然奇偶句，此句工巧而浑成、流利而含蓄，声韵和谐，寓意深婉，缠绵哀感，用虚字构成工整的对仗、唱叹传神方面表现出词人的巧思深情，宛如天成，也是这首词出名的原因。但更值得玩味的倒是这一联所含的意蓄。花的凋落，春的消逝，时光的流逝，都是不可抗拒的自然规律，虽然惋惜流连也无济于事，所以说“无可奈何”，这一句承上“夕阳西下”；然而这暮春天气中，所感受到的并不只是无可奈何的凋衰消逝，而是还有令人欣慰的重现，那翩翩归来的燕子不就像是去年曾此处安巢的旧时相识吗？这一句应上“几时回”。花落、燕归虽也是眼前景，但一经与“无可奈何”、“似曾相识”相联系，它们的内涵便变得非常广泛，意境非常深刻，带有美好事物的象征意味。惋惜与欣慰的交织中，蕴含着某种生活哲理：一切必然要消逝的美好事物都无法阻止其消逝，但消逝的同时仍然有美好事物的再现，生活不会因消逝而变得一片虚无。只不过这种重现毕竟不等于美好事物的原封不动地重现，它只是“似曾相识”罢了。渗透在句中的是一种混杂着眷恋和怅惆，既似冲澹又似深婉的人生怅触。唯其如此，此联作者既用于此词，又用于《示张寺丞王校勘》一诗。“小园香径独徘徊”，即是说他独自一人在花间踱来踱去，心情无法平静。这里伤春的感情胜于惜春的感情，含着淡淡的哀愁，情调是低沉的。\n\n　　此词之所以脍炙人口，广为传诵，其根本的原因于情中有思。\n\n　　词中似乎于无意间描写司空见惯的现象，却有哲理的意味，启迪人们从更高层次思索宇宙人生问题。词中涉及到时间永恒而人生有限这样深广的意念，却表现得十分含蓄。', poem_tags = '宋词三百首,宋词精选,初中古诗,婉约,伤春,惜时,抒怀,人生,哲理' WHERE poem_title = '浣溪沙·一曲新词酒一杯' AND poem_author = '晏殊';
UPDATE edu_poem SET poem_translation = '香炉峰在阳光的照射下生起紫色烟霞，远远望见瀑布似白色绢绸悬挂在山前。\n高崖上飞腾直落的瀑布好像有几千尺，让人恍惚以为银河从天上泻落到人间。', poem_notes = '香炉：指香炉峰。紫烟：指日光透过云雾，远望如紫色的烟云。\n遥看：从远处看。挂：悬挂。前川：一作“长川”。川：河流，这里指瀑布。\n直：笔直。三千尺：形容山高。这里是夸张的说法，不是实指。\n疑：怀疑。银河：古人指银河系构成的带状星群。九天：一作“半天”。', poem_appreciation = '这首诗是七言绝句。此诗中的香炉，即第一首诗开头提到的香炉峰，“在庐山西北，其峰尖圆，烟云聚散，如博山香炉之状”（乐史《太平寰宇记》）。可是，到了诗人李白的笔下，便成了另一番景象：一座顶天立地的香炉，冉冉地升起了团团白烟，缥缈于青山蓝天之间，在红日的照射下化成一片紫色的云霞。这不仅把香炉峰渲染得更美，而且富有浪漫主义色彩，为不寻常的瀑布创造了不寻常的背景。接着诗人才把视线移向山壁上的瀑布。“遥看瀑布挂前川”，前四字是点题。“挂前川”，这是“望”的第一眼形象，瀑布像是一条巨大的白练高挂于山川之间。“挂”字很妙，它化动为静，惟妙惟肖地表现出倾泻的瀑布在“遥看”中的形象。第一首诗说，“壮哉造化功！”正是这“造化”才能将这巨物“挂”起来，所以这“挂”字也包含着诗人对大自然的神奇伟力的赞颂。第三句又极写瀑布的动态。“飞流直下三千尺”，一笔挥洒，字字铿锵有力。“飞”字，把瀑布喷涌而出的景象描绘得极为生动；“直下”，既写出山之高峻陡峭，又可以见出水流之急，那高空直落，势不可挡之状如在眼前。然而，诗人犹嫌未足，接着又写上一句“疑是银河落九天”，真是想落天外，惊人魂魄。“疑是”值得细味，诗人明明说得恍恍惚惚，而读者也明知不是，但是又都觉得只有这样写，才更为生动、逼真，其奥妙就在于诗人前面的描写中已经孕育了这一形象。巍巍香炉峰藏在云烟雾霭之中，遥望瀑布就如从云端飞流直下，临空而落，这就自然地联想到像是一条银河从天而降。可见，“疑是银河落九天”这一比喻，虽是奇特，但在诗中并不是凭空而来，而是在形象的刻画中自然地生发出来的。它夸张而又自然，新奇而又真切，从而振起全篇，使得整个形象变得更为丰富多彩，雄奇瑰丽，既给人留下了深刻的印象，又给人以想象的余地，显示出李白那种“万里一泻，末势犹壮”的艺术风格。\n\n　　宋人魏庆之说：“七言诗第五字要响。……所谓响者，致力处也。”（《诗人玉屑》）这个看法在这首诗里似乎特别有说服力。比如一个“生”字，不仅把香炉峰写“活”了，也隐隐地把山间的烟云冉冉上升、袅袅浮游的景象表现出来了。“挂”字前面已经提到了，那个“落”字也很精彩，它活画出高空突兀、巨流倾泻的磅礴气势。很难设想换掉这三个字，这首诗将会变成什么样子。\n\n　　中唐诗人徐凝也写了一首《庐山瀑布》。诗云：“虚空落泉千仞直，雷奔入江不暂息。千古长如白练飞，一条界破青山色。”场景虽也不小，但还是给人局促之感，原因大概是它转来转去都是瀑布，瀑布，显得很实，很板，虽是小诗，却颇有点大赋的气味。比起李白那种入乎其内，出乎其外，有形有神，奔放空灵，相去实在甚远。苏轼说：“帝遣银河一派垂，古来唯有谪仙词。飞流溅沫知多少，不与徐凝洗恶诗。”（《戏徐凝瀑布诗》）话虽不无过激之处，然其基本倾向还是正确的，表现了苏轼不仅是一位著名的诗人，也是一位颇有见地的鉴赏家。\n\n　　第一首五古因篇幅无限制，所以诗人任意挥洒，写“海风”，写“江月”，写“穹石”，写得大起大落，大开大阖，转折如意，挥洒自如，一气呵成。第二首七绝因篇幅较小，诗人用夸张的比喻把景物升腾到更高的境界，达到写瀑布的极致，极为夸张，但又清新自然，浅显生动，同时具有动荡开阔的气势，飞动流走的章法，跳跃腾挪，纵横捭阖，亦有歌行的气势和特点。\n\n　　两首诗都是李白之作，同是写庐山瀑布之景，李白一生好入名山游在庐山秀丽的山水之中，更显诗人标名之灵气。其想象丰富，奇思纵横，气势恢宏，感情奔放，似江河奔腾，又自然清新，似云卷风清，其诗歌的审美特征是自然美、率真美和无拘无束的自由美。这两首诗歌都具有这样的审美特征。', poem_tags = '小学古诗,写景,山水,瀑布,早教古诗100首' WHERE poem_title = '望庐山瀑布' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '乘单车想去慰问边关，路经的属国已过居延。\n千里飞蓬也飘出汉塞，北归大雁正翱翔云天。\n浩瀚沙漠中孤烟直上，无尽黄河上落日浑圆。\n到萧关遇到侦候骑士，告诉我都护已在燕然。', poem_notes = '使至塞上：奉命出使边塞。使：出使。\n单车：一辆车，车辆少，这里形容轻车简从。问边：到边塞去察看，指慰问守卫边疆的官兵。\n属国：有几种解释：一指少数民族附属于汉族朝廷而存其国号者。汉、唐两朝均有一些属国。二指官名，秦汉时有一种官职名为典属国，苏武归汉后即授典属国官职。唐人有时以“属国”代称出使边陲的使臣。居延：地名，汉代称居延泽，唐代称居延海，在今内蒙古额济纳旗北境。又西汉张掖郡有居延县（参《汉书·地理志》），故城在今额济纳旗东南。又东汉凉州刺史部有张掖居延属国，辖境在居延泽一带。此句一般注本均言王维路过居延。然而王维此次出使，实际上无需经过居延。因而林庚、冯沅君主编的《中国历代诗歌选》认为此句是写唐王朝“边塞的辽阔，附属国直到居延以外”。\n征蓬：随风飘飞的蓬草，此处为诗人自喻。\n归雁：雁是候鸟，春天北飞，秋天南行，这里是指大雁北飞。胡天：胡人的领空。这里是指唐军占领的北方地方。\n大漠：大沙漠，此处大约是指凉州之北的沙漠。孤烟：赵殿成注有二解：一云古代边防报警时燃狼粪，“其烟直而聚，虽风吹之不散”。二云塞外多旋风，“袅烟沙而直上”。据后人有到甘肃、新疆实地考察者证实，确有旋风如“孤烟直上”。又：孤烟也可能是唐代边防使用的平安火。长河：指流经凉州（今甘肃武威）以北沙漠的一条内陆河，这条河在唐代叫马成河，疑即今石羊河。\n萧关：古关名，又名陇山关，故址在今宁夏固原东南。候骑：负责侦察、通讯的骑兵。王维出使河西并不经过萧关，此处大概是用何逊诗“候骑出萧关，追兵赴马邑”之意，非实写。\n都护：唐朝在西北边疆置安西、安北等六大都护府，其长官称都护，每府派大都护一人，副都护二人，负责辖区一切事务。这里指前敌统帅。燕然：燕然山，即今蒙古国杭爱山。东汉窦宪北破匈奴，曾于此刻石记功。《这里代指前线。\n“单车”两句：一作“衔命辞天阙，单车欲问边”。\n候骑：骑马的侦察兵。', poem_appreciation = '此诗载于《全唐诗》卷一百二十六。下面是中国古代文学研究专家、中国作家协会会员、原首都师范大学中文系博士生导师张燕瑾先生对此诗的赏析。\n\n　　《使至塞上》描绘了塞外奇特壮丽的风光，表现了诗人对不畏艰苦，以身许国的守边战士的爱国精神的赞美；此诗叙事精练简洁，画面奇丽壮美。\n\n　　“单车欲问边”，轻车前往，向哪里去呢——“属国过居延”，居延在今甘肃张掖县西北，远在西北边塞。\n\n　　“征蓬出汉塞，归雁入胡天”，诗人以“蓬”、“雁”自比，说自己像随风而去的蓬草一样出临“汉塞”，像振翮北飞的“归雁”一样进入“胡天”。古诗中多用飞蓬比喻漂流在外的游子，这里却是比喻一个负有朝廷使命的大臣，正是暗写诗人内心的激愤和抑郁。与首句的“单车”相呼应。万里行程只用了十个字轻轻带过。\n\n　　然后抓住沙漠中的典型景物进行刻画：“大漠孤烟直，长河落日圆”。\n\n　　最后两句写到达边塞：“萧关逢候骑，都护在燕然”。到了边塞，却没有遇到将官，侦察兵告诉使臣：首将正在燕然前线。\n\n　　诗人把笔墨重点用在了他最擅长的方面——写景。作者出使，恰在春天。途中见数行归雁北翔，诗人即景设喻，用归雁自比，既叙事，又写景，一笔两到，贴切自然。尤其是“大漠孤烟直，长河落日圆”一联，写进入边塞后所看到的塞外奇特壮丽的风光，画面开阔，意境雄浑，近人王国维称之为“千古壮观”的名句。边疆沙漠，浩瀚无边，所以用了“大漠“的“大”字。边塞荒凉，没有什么奇观异景，烽火台燃起的那一股浓烟就显得格外醒目，因此称作“孤烟”。一个“孤”字写出了景物的单调，紧接一个“直”字，却又表现了它的劲拔、坚毅之美。沙漠上没有山峦林木，那横贯其间的黄河，就非用一个“长”字不能表达诗人的感觉。落日，本来容易给人以感伤的印象，这里用一“圆”字，却给人以亲切温暖而又苍茫的感觉。一个“圆”字，一个“直”字，不仅准确地描绘了沙漠的景象，而且表现了作者的深切的感受。诗人把自己的孤寂情绪巧妙地溶化在广阔的自然景象的描绘中。《红楼梦》第四十八回香菱学诗里说的那段话可算道出了这两句诗高超的艺术境界。', poem_tags = '初中古诗,边塞,写景,赞美,战士,早教古诗100首' WHERE poem_title = '使至塞上' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '一边喝酒一边高歌，人生短促日月如梭。好比晨露转瞬即逝，失去的时日实在太多！\n席上歌声激昂慷慨，忧郁长久填满心窝。靠什么来排解忧闷？唯有狂饮方可解脱。\n那穿着青领（周代学士的服装）的学子哟，你们令我朝夕思慕。只是因为您的缘故，让我沉痛吟诵至今。\n阳光下鹿群呦呦欢鸣，悠然自得啃食在绿坡。一旦四方贤才光临舍下，我将奏瑟吹笙宴请嘉宾。\n当空悬挂的皓月哟，什么时候才可以拾到；我久蓄于怀的忧愤哟，突然喷涌而出汇成长河。\n远方宾客踏着田间小路，一个个屈驾前来探望我。彼此久别重逢谈心宴饮，争着将往日的情谊诉说。\n月光明亮星光稀疏，一群寻巢乌鹊向南飞去。绕树飞了三周却没敛翅，哪里才有它们栖身之所？\n高山不辞土石才见巍峨，大海不弃涓流才见壮阔。我愿如周公一般礼贤下士，愿天下的英杰真心归顺与我。', poem_notes = '对酒当歌：一边喝着酒，一边唱着歌。当，是对着的意思。\n几何：多少。\n去日苦多：跟（朝露）相比一样痛苦却漫长。有慨叹人生短暂之意。\n慨当以慷：指宴会上的歌声激昂慷慨。当以，这里“应当用”的意思。全句意思是，应当用激昂慷慨（的方式来唱歌）。\n杜康：相传是最早造酒的人，这里代指酒。\n青青子衿（jīn），悠悠我心：这里用来比喻渴望得到有才学的人。子，对对方的尊称。衿，古式的衣领。青衿，是周代读书人的服装，这里指代有学识的人。悠悠，长久的样子，形容思虑连绵不断。\n沉吟：原指小声叨念和思索，这里指对贤人的思念和倾慕。\n呦（yōu）呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙（shēng）：出自《诗经·小雅·鹿鸣》。呦呦：鹿叫的声音。苹：艾蒿。\n鼓：弹。\n何时可掇（duō）：什么时候可以摘取呢？掇，拾取，摘取。另解：掇读chuò，为通假字，掇，通“辍” ，即停止的意思。\n越陌度阡：穿过纵横交错的小路。陌，东西向田间小路。阡，南北向的小路。\n枉用相存：屈驾来访。枉，这里是“枉驾”的意思；用，以。存，问候，思念。\n讌（yàn）：通“宴”（原文中讌为“䜩”）。\n三匝（zā）：三周。匝，周，圈。\n海不厌深：一本作“水不厌深”。意思是表示希望尽可能多地接纳人才。', poem_appreciation = '《短歌行》是汉乐府的旧题，属于《相和歌辞·平调曲》。这就是说它本来是一个乐曲的名称。最初的古辞已经失传。乐府里收集的同名有24首，最早的是曹操的这首。这种乐曲怎么唱法，现在当然是不知道了。但乐府《相和歌·平调曲》中除了《短歌行》还有《长歌行》，唐代吴兢《乐府古题要解》引证古诗“长歌正激烈”，魏文帝曹丕《燕歌行》“短歌微吟不能长”和晋代傅玄《艳歌行》“咄来长歌续短歌”等句，认为“长歌”、“短歌”是指“歌声有长短”。现在也就只能根据这一点点材料来理解《短歌行》的音乐特点。《短歌行》这个乐曲，原来当然也有相应的歌辞，就是“乐府古辞”，但这古辞已经失传了。现在所能见到的最早的《短歌行》就是曹操所作的拟乐府《短歌行》。所谓“拟乐府”就是运用乐府旧曲来补作新词，曹操传世的《短歌行》共有两首，这里要介绍的是其中的第一首。\n\n　　这首《短歌行》的主题非常明确，就是作者希望有大量人才来为自己所用。曹操在其政治活动中，为了扩大他在庶族地主中的统治基础，打击反动的世袭豪强势力，曾大力强调“唯才是举”，为此而先后发布了“求贤令”、“举士令”、“求逸才令”等；而《短歌行》实际上就是一曲“求贤歌”、又正因为运用了诗歌的形式，含有丰富的抒情成分，所以就能起到独特的感染作用，有力地宣传了他所坚持的主张，配合了他所颁发的政令。\n\n　　《短歌行》原来有“六解”（即六个乐段），按照诗意分为四节来读。\n\n　　“对酒当歌，人生几何？譬如朝露，去日苦多。慨当以慷，忧思难忘。何以解忧，唯有杜康。”\n\n　　在这八句中，作者强调他非常发愁，愁得不得了。那么愁的是什么呢？原来他是苦于得不到众多的“贤才”来同他合作，一道抓紧时间建功立业。试想连曹操这样位高权重的人居然在那里为“求贤”而发愁，那该有多大的宣传作用。假如庶族地主中真有“贤才”的话，看了这些话就不能不大受感动和鼓舞。他们正苦于找不到出路呢，没有想到曹操却在那里渴求人才，于是那真正有才或自以为有才的许许多多人，就很有可能跃跃欲试，向他“归心”了。 “对酒当歌”八句，猛一看很像是《古诗十九首》中的消极调子，而其实大不相同。这里讲“人生几何”，不是叫人“及时行乐”，而是要及时地建功立业。又从表面上看，曹操是在抒个人之情，发愁时间过得太快，恐怕来不及有所作为。实际上却是在巧妙地感染广大“贤才”，提醒他们人生就像“朝露”那样易于消失，岁月流逝已经很多，应该赶紧拿定主意，到我这里来施展抱负。所以一经分析便不难看出，诗中浓郁的抒情气氛包含了相当强烈的政治目的。这样积极的目的而故意要用低沉的调子来发端，这固然表明曹操真有他的愁思，所以才说得真切；但另一方面也正因为通过这样的调子更能打开处于下层、多历艰难、又急于寻找出路的人士的心扉。所以说用意和遣词既是真切的，也是巧妙的。在这八句诗中，主要的情感特征就是一个“愁”字，“愁”到需要用酒来消解（“杜康”相传是最早造酒的人，这里就用他的名字来作酒的代称）。“愁”这种感情本身是无法评价的，能够评价的只是这种情感的客观内容，也就是为什么而“愁”。由于自私、颓废、甚至反动的缘故而愁，那么这愁就是一种消极的感情；反之，为着某种有进步意义的目的而愁，那就成为一种积极的情感。放到具体的历史背景中看，曹操在这里所表达的愁绪就是属于后者，应该得到恰当的历史评价。清人陈沆在《诗比兴笺》中说：“此诗即汉高祖《大风歌》思猛士之旨也。‘人生几何’发端，盖传所谓古之王者知寿命之不长，故并建圣哲，以贻后嗣。”这可以说基本上懂得了曹操发愁的含意；不过所谓“并建圣哲，以贻后嗣”还未免说得迂远。曹操当时考虑的是要在他自己这一生中结束战乱，统一全中国。与汉高祖唱《大风歌》是既有相通之处，也有不同之处的。\n\n　　“青青子衿，悠悠我心。但为君故，沉吟至今。呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙。”\n\n　　这八句情味更加缠绵深长了。“青青”二句原来是《诗经·郑风·子衿》中的话，原诗是写一个姑娘在思念她的爱人，其中第一章的四句是：“青青子衿，悠悠我心。纵我不往，子宁不嗣音？”（你那青青的衣领啊，深深萦回在我的心灵。虽然我不能去找你，你为什么不主动给我音信？）曹操在这里引用这首诗，而且还说自己一直低低地吟诵它，这实在是太巧妙了。他说“青青子衿，悠悠我心”，固然是直接比喻了对“贤才”的思念；但更重要的是他所省掉的两句话：“纵我不往，子宁不嗣音？”曹操由于事实上不可能一个一个地去找那些“贤才”，所以他便用这种含蓄的方法来提醒他们：“就算我没有去找你们，你们为什么不主动来投奔我呢？”由这一层含而不露的意思可以看出，他那“求才”的用心实在是太周到了，的确具有感人的力量。而这感人力量正体现了文艺创作的政治性与艺术性的结合。他这种深细婉转的用心，在《求贤令》之类的文件中当然无法尽情表达；而《短歌行》作为一首诗，就能抒发政治文件所不能抒发的感情，起到政治文件所不能起的作用。紧接着他又引用《诗经·小雅·鹿鸣》中的四句，描写宾主欢宴的情景，意思是说只要你们到我这里来，我是一定会待以“嘉宾”之礼的，我们是能够欢快融洽地相处并合作的。这八句仍然没有明确地说出“求才”二字，因为曹操所写的是诗，所以用了典故来作比喻，这就是“婉而多讽”的表现方法。同时，“但为君故”这个“君”字，在曹操的诗中也具有典型意义。本来在《诗经》中，这“君”只是指一个具体的人；而在这里则具有了广泛的意义：在当时凡是读到曹操此诗的“贤士”，都可以自认为他就是曹操为之沈吟《子衿》一诗的思念对象。正因为这样，此诗流传开去，才会起到巨大的社会作用。\n\n　　“明明如月，何时可掇？忧从中来，不可断绝。越陌度阡，枉用相存。契阔谈讌，心念旧恩。”\n\n　　这八句是对以上十六句的强调和照应。以上十六句主要讲了两个意思，即为求贤而愁，又表示要待贤以礼。倘若借用音乐来作比，这可以说是全诗中的两个“主题旋律”，而“明明如月”八句就是这两个“主题旋律”的复现和变奏。前四句又在讲忧愁，是照应第一个八句；后四句讲“贤才”到来，是照应第二个八句。表面看来，意思上是与前十六句重复的，但实际上由于“主题旋律”的复现和变奏，因此使全诗更有抑扬低昂、反复咏叹之致，加强了抒情的浓度。再从表达诗的文学主题来看，这八句也不是简单重复，而是含有深意的。那就是说“贤才”已经来了不少，我们也合作得很融洽；然而我并不满足，我仍在为求贤而发愁，希望有更多的“贤才”到来。天上的明月常在运行，不会停止（“掇”通“辍”，“晋乐所奏”的《短歌行》正作“辍”，即停止的意思；高中课本中“掇”的解释为：拾取，采取。何时可掇：什么时候可以摘取呢）；同样，我的求贤之思也是不会断绝的。说这种话又是用心周到的表现，因为曹操不断在延揽人才，那么后来者会不会顾虑“人满为患”呢？所以曹操在这里进一步表示，他的求贤之心就象明月常行那样不会终止，人们也就不必要有什么顾虑，早来晚来都一样会受到优待。关于这一点作者在下文还要有更加明确的表示，这里不过是承上启下，起到过渡与衬垫的作用。\n\n　　“月明星稀，乌鹊南飞，绕树三匝，何枝可依？山不厌高，海不厌深，周公吐哺，天下归心。”\n\n　　“月明”四句既是准确而形象的写景笔墨，同时也有比喻的深意。清人沈德潜在《古诗源》中说：“月明星稀四句，喻客子无所依托。”这说明他看出了这四句是比喻，但光说“客子”未免空泛；实际上这是指那些犹豫不定的人才，他们在三国鼎立的局面下一时无所适从。所以曹操以乌鹊绕树、“何枝可依”的情景来启发他们，不要三心二意，要善于择枝而栖，赶紧到自己这一边来。这四句诗生动刻画了那些犹豫彷徨者的处境与心情，然而作者不仅丝毫未加指责，反而在浓郁的诗意中透露着对这一些人的关心和同情。这恰恰说明曹操很会做思想工作，完全是以通情达理的姿态来吸引和争取人才。而像这样一种情味，也是充分发挥了诗歌所特有的感染作用。最后四句画龙点睛，明明白白地披肝沥胆，希望人才都来归我，确切地点明了此诗的主题。“周公吐哺”的典故出于《韩诗外传》，据说周公自言：“吾文王之子，武王之弟，成王之叔父也；又相天下，吾于天下亦不轻矣。然一沐三握发，一饭三吐哺，犹恐失天下之士。”周公为了接待天下之士，有时洗一次头，吃一顿饭，都曾中断数次，这种传说当然是太夸张了。不过这个典故用在这里却是突出地表现了作者求贤若渴的心情。“山不厌高，海不厌深”二句也是通过比喻极有说服力地表现了人才越多越好，决不会有“人满之患”。借用了《管子·形解》中陈沆说：“鸟则择木，木岂能择鸟？天下三分，士不北走，则南驰耳。分奔蜀吴，栖皇未定，若非吐哺折节，何以来之？山不厌土，故能成其高；海不厌水，故能成其深；王者不厌士，故天下归心。”（亦见《诗比兴笺》）这些话是很有助于说明此诗的背景、主题以及最后各句之意的。\n\n　　总起来说，《短歌行》正像曹操的其它诗作如《蒿里行》、《对酒》、《苦寒行》等一样，是政治性很强的诗作，主要是为曹操当时所实行的政治路线和政治策略服务的；然而它那政治内容和意义却完全熔铸在浓郁的抒情意境之中，全诗充分发挥了诗歌创作的特长，准确而巧妙地运用了比兴手法，来达到寓理于情，以情感人的目的。在曹操的时代，他就已经能够按照抒情诗的特殊规律来取得预期的社会效果，这一创作经验显然是值得借鉴的。同时因为曹操在当时强调“唯才是举”有一定的进步意义，所以他对“求贤”这一主题所作的高度艺术化的表现，也应得到历史的肯定。', poem_tags = '古诗三百首,乐府,抒情,寓理' WHERE poem_title = '短歌行' AND poem_author = '曹操';
UPDATE edu_poem SET poem_translation = '舜从田野耕作之中被起用，傅说从筑墙的劳作之中被起用，胶鬲从贩鱼卖盐中被起用，管夷吾被从狱官手里救出来并受到任用，孙叔敖从海滨隐居的地方被起用，百里奚被从奴隶市场里赎买回来并被起用。\n\n　　所以上天要把重任降临在某人的身上，一定先要使他心意苦恼，筋骨劳累，使他忍饥挨饿，身体空虚乏力，使他的每一行动都不如意，这样来激励他的心志，使他性情坚忍，增加他所不具备的能力。\n\n　　一个人，常常出错，然后才能改正；心意困苦，思虑阻塞．然后才能奋发；别人愤怒表现在脸色上，怨恨吐发在言语中，然后你就会知道。一个国家，如果在国内没有坚守法度的大臣和足以辅佐君王的贤士，在国外没有与之匹敌的邻国和来自外国的祸患，就常常会有覆灭的危险。\n\n　　这样，就知道忧愁患害足以使人生存，安逸享乐足以使人灭亡的道理了。', poem_notes = '1、舜：姚姓，名重华。唐尧时耕于历山（在今山东济南东南，一说在今山西永济东南），“父顽，母嚣，弟傲，能和以孝”，尧帝使其人山林川泽，遇暴风雷雨，舜行不迷，于是传以天子之位。国名虞，史称虞舜。事迹见于《尚书·尧典》及《史记·五帝本纪》等。\n2、发：起，指任用。\n3、畎（quǎn）亩：田亩，此处意为耕田。畎，田间水渠。\n4、傅说（fù yuè）：殷商时为胥靡（一种刑徒），筑于傅险（又作傅岩，在今山西平陆东）。商王武丁欲兴殷，梦得圣人，名曰说，视群臣皆非，使人求于野，得傅说。见武丁，武丁曰：“是也。”与之语，果圣人，举以为相，殷国大治。遂以傅险为姓，名为傅说。事迹见于《史记·殷本纪》等。\n5、举：被选拔。\n6、版筑：筑墙的时候在两块夹板中间放土，用杵捣土，使它坚实。筑，捣土用的杵。\n7、胶鬲（gé）：商纣王大臣，与微子、箕子、王子比干同称贤人。\n8、鱼盐：此处意为在海边捕鱼晒盐。《史记》称燕在渤碣之间，有鱼盐之饶；齐带山海，多鱼盐。\n9、管夷吾：管仲，颍上（今河南许昌）人，家贫困。辅佐齐国公子纠，公子纠未能即位，公子小白即位，是为齐桓公。齐桓公知其贤，释其囚，用以为相，尊称之为仲父。《史记·管晏列传》：“管仲既用，任政于齐，齐桓公以霸。九合诸侯，一匡天下，管仲之谋也。”\n10、士：狱官。\n11、孙叔敖（áo）：蒍姓，名敖，字孙叔，一字艾猎。春秋时为楚国令尹（宰相）。本为“期思之鄙人”，期思在今河南固始，偏僻之地称为鄙。\n12、海：海滨。\n13、百里奚（xī）：又作百里傒。本为虞国大夫。晋国灭虞国，百里奚与虞国国君一起被俘至晋国。晋国嫁女于秦，百里奚被当作媵臣陪嫁到秦国。百里奚逃往楚国，行至宛（今河南南阳），为楚国边界之鄙人所执。秦穆公闻其贤，欲重赎之，恐楚人不与，乃使人谓楚曰：“吾媵臣百里奚在焉，请以五羖羊皮赎之。”楚人于是与之。时百里奚年已七十余，至秦，秦穆公亲释其囚，与语国事三日，大悦。授以国政，号称“五羖大夫”。史称秦穆公用百里奚、蹇叔、由余为政，“开地千里，遂霸西戎”，成为“春秋五霸”之一。事迹见于《史记·秦本纪》。\n14、市：市井。\n15、故：所以。\n16、任：责任，担子。\n17、是：代词，这，这些。\n18、也：助词，用在前半句的末尾，表示停顿一下，后半句将要加以解说。\n19、必：一定。\n20、苦：动词的使动用法，使……苦恼。\n21、心志：意志。\n22、劳：动词的使动用法，使……劳累。\n23、饿：动词的使动用法，使……饥饿。\n24、体肤：肌肤。\n25、空乏：形容词的使动用法，使……穷困。\n26、拂乱：形容词的使动用法，使……颠倒错乱。拂，违背，不顺。乱，错乱。\n27、所为：所行。\n28、所以：用来（通过那样的途径来……）。\n29、动：动词的使动用法，使……惊动。\n30、忍：形容词的使动用法，使……坚韧。\n31、曾益：增加。曾，通“增”。\n32、能：才干。\n33、恒：常常，总是。\n34、过：过错，过失。\n35、困于心：心中有困苦。\n36、衡于虑：思虑堵塞。衡，通“横”，梗塞，指不顺。\n37、作：奋起，指有所作为。\n38、征于色：面色上有征验，意为面容憔悴。征，征验，征兆。色，颜面，面色。赵岐《孟子注》：“若屈原憔悴，渔父见而怪之。”《史记·屈原贾谊列传》：“屈原至于江滨，被发行吟泽畔，颜色憔悴，形容枯槁。渔父见而问之曰： ‘子非三闾大夫与？何故而至此？’屈原曰：‘举世混浊我独清，众人皆醉我独醒，是以见放。’”\n39、发于声：言语上有抒发，意为言语愤激。赵岐《孟子注》：“若甯戚商歌，桓公异之。”甯戚，春秋时卫国人。家贫，为人挽车。至齐，喂牛于车下，齐桓公夜出迎客，甯戚见之，疾击其牛角而商歌。歌曰：“南山矸，白石烂，生不逢尧与舜禅。短布单衣适至骭，从昏饭牛薄夜半，长夜漫漫何时旦。”齐桓公召与语，悦之，以为大夫。\n40、而后喻：然后人们才了解他。喻，知晓，明白。\n41、入：名词活用作状语，在国内。\n42、法家：有法度的世臣。\n43、拂（bì）士：辅佐君主的贤士。拂，通“弼”，辅佐。\n44、出：名词活用作状语，在国外。\n45、敌国：实力相当、足以抗衡的国家。\n46、外患：来自国外的祸患。\n47、恒：常常。\n48、亡：灭亡。\n49、生于忧患：忧患使人生存发展。\n50、死于安乐：享受安乐使人萎靡死亡。', poem_appreciation = '文章开头，作者一连列举了六位古代圣贤在困难忧患中崛起的事例，来证明“天将降大任于是人也，必先苦其心志，劳其筋骨，饿其体肤，空乏其身，行拂乱其所为，所以动心忍性，曾益其所不能”这一著名论断。这个推理过程属于逻辑学上的归纳推理，即由前面六个特殊的事例，归纳出后面带普通意义的结论；又通过后面的结论，说明了前面六个人物所以成功的原因：艰苦的环境，一方面给人们以困苦、饥饿、贫困、疲乏、忧虑，每每就不如人意，但另一方面，也正是这些困难，坚定、振奋人们的意志，使人们在不断克服困难，求得生存的过程中增加了聪明才干。然而道理在此还没有说完，上面只谈到，在人与客观环境这一对矛盾中，客观环境对人的触动，反过来，针对人的主观世界对此又是怎样做出反应，孟子接着指出：“人恒过，然后能改；困于心，衡于虑，而后作；征于色，发于声，而后喻。”客观环境的困难和自身判断的失误，造成人在改造客观的过程中的错误，而他也就在不断克服困难的过程中积累了经验教训，从而达到“能改”的境界——这个“能”，从语义上讲，不仅体现了人的愿望、决心，也体现了人的能力。他因为自身所遭遇的困难而忧虑、痛苦、困惑，造成内心的压抑，而他也就在不断冲破这些心理压抑的尝试中，活跃了自己的思维，激发了自己的创造力。更重要的一点，人是有感情的，又是社会性的，他有痛苦，有忧虑，想发愤，想创造，必然表现在形色上，吐发在言辞中，期望得到理解与同情、启发与帮助。人就在这一切与忧患的斗争中，一方面求得了物质的生存可能，另一方面更求得了精神的生存，表现了他的活力、意志、情感、创造能力，一句话，表现了他“生”的价值。这，就是“生于忧患，死于安乐”的全部含义。\n\n　　刘熙载在《艺概·文概》里指出：“昌黎（韩愈）以‘是’、‘异’二字论文，然二者仍须合一。若不‘异’之‘是’，则庸而已；若不‘是’之‘异’，则妄而已。”这种主张，实在起于孟子的影响。孟子在提出“生于忧患”这一“是”命题的同时，也提出了它的“异”命题： “死于安乐”。“入则无法家拂士，出则无敌国外患”。在内没有能干的大臣，时时注意修明法度；没有敢于直谏的贤士，处处提醒国君克己慎终。在外又没有敌国的抗衡、外寇的侵扰。如此安适的环境，首先带来的必然是精神的怠惰和意志的消沉。这是精神上的死亡。紧接着必然是物质上的死亡——“国恒亡”。\n\n　　“生于忧患，死于安乐”，一反一正，一是一异，相辅相成地说明了同一人生哲理的两面。既不使人因正面说教而感沉闷，又不为邀人眷顾而故发惊人之谈；既娓娓动听，又给人警策；既不庸，又不妄。\n\n　　尤其值得注意的是：“生于忧患，死于安乐”这一命题的明确提出，在孟子也许只是为了给人以政治道德上的启迪。但作为一条具普遍意义的人生哲理，其影响绝不仅仅表现在政治道德上。特别是“困于心，衡于虑，而后作；征于色，发于声，而后喻”两句，直接导引了中国古典文学艺术创造的一条极重要的美学原则的形成，这就是“发愤抒情”这一美学创作原则。这亦是千百年来，孟子此篇所以脍炙人口的原因。\n\n　　在修辞上，此文也很有特色。《孟子》善用排比句，往往采用一连串结构相同的句式，对于同一论题，进行多角度多层次的说明，有如千流万壑，一时俱下，形成滔滔万里不可阻挡的气势。孟子文之称雄辩，这类句式的采用是很重要的一个原因。《生于忧患，死于安乐》，配合归纳的推理方式，便采用了这种句式，一起首连举六位圣贤的成功事迹，从数量上给人以深刻印象，使人觉得“生于忧患”确是一种普遍存在的社会现象；接着又极力铺排艰难环境给人们带来的磨难，反衬了圣贤成功的不易；然后再历述圣贤面对艰难忧患的正确态度与处理方法，最终得出“生于忧患，死于安乐”的结论，很有说服力。一般说来，铺陈排比的写法，固可造成宏大气势；若处理不当，也可致繁复拖沓之虞。其后的汉大赋，由于片面强调了这一特点，往往使人难以卒读。而孟子的这篇文章，虽通篇采用排比句式，却仍给人以行文简洁的印象。原因在于，孟子十分注意遣词用字，尽量扩充每一词语，尤其是动词的容量。以起首一段为例，共六句话，六个动词，包括一个“发”，五个“举”，既表现了人物由微贱趋向显达的运动过程，又暗示了人物身份：舜君子，是圣人，他的成功，固然因为尧的赏识，但主要靠的是他自身的才能与努力，故曰“发”；傅说等是臣，是贤人，他们的成功，固然因为自身的才能与努力，但主要靠的是明主的知遇，故曰“举”。\n\n　　如同所有成就辉煌的文人学者一样，孟子的一生也是不甚得意的。此文写得如此出色，诚为“发愤抒情”的结果。', poem_tags = '初中文言文,议论,哲理' WHERE poem_title = '生于忧患，死于安乐' AND poem_author = '孟子及其弟子';
UPDATE edu_poem SET poem_translation = '先帝开创的大业未完成一半却中途去世了。现在天下分为三国，益州地区民力匮乏，这确实是国家危急存亡的时期啊。不过宫廷里侍从护卫的官员不懈怠，战场上忠诚有志的将士们奋不顾身，大概是他们追念先帝对他们的特别的知遇之恩（作战的原因），想要报答在陛下您身上。（陛下）你实在应该扩大圣明的听闻，来发扬光大先帝遗留下来的美德，振奋有远大志向的人的志气，不应当随便看轻自己，说不恰当的话，以致于堵塞人们忠心地进行规劝的言路。 \n　　皇宫中和朝廷里的大臣，本都是一个整体，奖惩功过，好坏，不应该有所不同。如果有做奸邪事情，犯科条法令和忠心做善事的人，应当交给主管的官，判定他们受罚或者受赏，来显示陛下公正严明的治理，而不应当有偏袒和私心，使宫内和朝廷奖罚方法不同。\n　　侍中、侍郎郭攸之、费祎、董允等人，这些都是善良诚实的人，他们的志向和心思忠诚无二，因此先帝把他们选拔出来辅佐陛下。我认为（所有的）宫中的事情，无论事情大小，都拿来跟他们商量，这样以后再去实施，一定能够弥补缺点和疏漏之处，可以获得很多的好处。\n　　将军向宠，性格和品行善良公正，精通军事，从前任用时，先帝称赞说他有才干，因此大家评议举荐他做中部督。我认为军队中的事情，都拿来跟他商讨，就一定能使军队团结一心，好的差的各自找到他们的位置。\n　　亲近贤臣，疏远小人，这是西汉之所以兴隆的原因；亲近小人，疏远贤臣，这是东汉之所以衰败的原因。先帝在世的时候，每逢跟我谈论这些事情，没有一次不对桓、灵二帝的做法感到叹息痛心遗憾的。侍中、尚书、长史、参军，这些人都是忠贞诚实、能够以死报国的忠臣，希望陛下亲近他们，信任他们，那么汉朝的兴隆就指日可待了。\n　　我本来是平民，在南阳务农亲耕，在乱世中苟且保全性命，不奢求在诸侯之中出名。先帝不因为我身份卑微，见识短浅，降低身份委屈自己，三次去我的茅庐拜访我，征询我对时局大事的意见，我因此有所感而情绪激动，就答应为先帝奔走效劳。后来遇到兵败，在兵败的时候接受任务，在危机患难之间奉行使命，那时以来已经有二十一年了。\n　　先帝知道我做事小心谨慎，所以临终时把国家大事托付给我。接受遗命以来，我早晚忧愁叹息，只怕先帝托付给我的大任不能实现，以致损伤先帝的知人之明，所以我五月渡过泸水，深入到人烟稀少的地方。现在南方已经平定，兵员装备已经充足，应当激励、率领全军将士向北方进军，平定中原，希望用尽我平庸的才能，铲除奸邪凶恶的敌人，恢复汉朝的基业，回到旧日的国都。这就是我用来报答先帝，并且尽忠陛下的职责本分。至于处理事务，斟酌情理，有所兴革，毫无保留地进献忠诚的建议，那就是郭攸之、费祎、董允等人的责任了。\n　　希望陛下能够把讨伐曹魏，兴复汉室的任务托付给我，如果没有成功，就惩治我的罪过，（从而）用来告慰先帝的在天之灵。如果没有振兴圣德的建议，就责罚郭攸之、费祎、董允等人的怠慢,来揭示他们的过失；陛下也应自行谋划，征求、询问治国的好道理，采纳正确的言论，深切追念先帝临终留下的教诲。我感激不尽。\n　　今天(我)将要告别陛下远行了，面对这份奏表禁不住热泪纵横，也不知说了些什么。', poem_notes = '表：古代向帝王上书陈情言事的一种文体。\n出：出征。\n师：军队。\n先帝：这里指刘备。\n创：开创，创立。\n业：统一中原的大业。\n而：表转折。\n赏：受赏。\n刑：受罚。\n中道：中途。\n崩殂(cú)：死。崩，古代称帝王、皇后之死。殂，死亡。\n益州疲弊：指蜀汉国力薄弱，处境艰难。益州，这里指蜀汉。疲弊，人力疲惫，民生凋敝，困苦穷乏。\n三分：天下分为三个国家（即魏、蜀、吴三国)。\n此：这。\n诚：确实，实在。\n之：结构助词，的。\n秋：时候。\n然：但是\n侍：侍奉。\n卫：守卫\n懈：懈怠，放松。\n于：在。\n忠：忠诚。\n内：朝廷上。\n外：朝廷外，指战场上。\n士：将士。\n忘身：奋不顾身。\n盖：连词。连接上一句或上一段，表示原因。\n追：追念。\n殊遇：特殊的对待，即优待、厚遇。\n欲：想要。\n报：报答。\n之：代词。\n于：向，对。\n诚：实在，确实。\n宜，应该。\n开张圣听：扩大圣明的听闻，意思是要后主广泛地听取别人的意见。开张：扩大。圣：圣明\n以：来。\n光：发扬光大。\n遗德：遗留的美德。\n恢弘：这里是动词，形作动，意思是发扬扩大。也作“恢宏”。恢：大。弘：大、宽。\n气：志气。\n妄自菲薄：过分看轻自己。妄：随便，胡乱，轻率。菲薄：微薄。\n引喻失义：说话不恰当。引喻：引用、比喻。这里是说话的意思。义：适宜，恰当。\n以：因而。\n塞；阻塞。\n忠：忠诚。\n谏：直言规劝，使改正错误。这里指进谏。\n俱：全，都。\n宫中：指皇宫中。\n府中：指朝廷中。\n体：整体。\n陟(zhì)：提升，提拔。\n罚：惩罚。\n臧否(pǐ)：善恶，这里形容词用作动词。意思是“评论人物的好坏”。臧否：善恶。\n异同：这里偏重在异。\n作奸犯科：做奸邪事情，犯科条法令。\n作奸：为非作歹。\n科：科条，法令。\n及：和。\n为：做。\n付：交给。\n有司:职有专司，就是专门管理某种事情的官。\n论：凭定。\n刑：罚。\n以：来。\n昭：彰显，显扬。\n平：公平。\n明：严明。\n理：治。\n偏私：偏袒私情，不公正。\n内外异法：宫内和朝廷刑赏之法不同。\n内外：指宫内和朝廷。\n异法：刑赏之法不同。法：法制。\n侍中、侍郎郭攸之、费祎（yī）、董允：郭攸之、费祎是侍中，董允是侍郎。侍中、侍郎，都是官名。\n此皆良实，志虑忠纯：这些都是善良、诚实的人，他们的志向和心思忠诚无二。\n良实：善良诚实，这里形容词做名词，指善良诚实的人。\n志：志向。\n虑：思想，心思。\n忠纯：忠诚纯正。\n简拔：选拔。简：挑选。拔：选拔。\n遗（wèi）：给予。\n悉以咨之：都拿来问问他们。悉：副词，都，全。咨：询问，征求意见。\n之：指郭攸之等人。\n必能裨补阙漏：一定能够弥补缺点和疏漏之处。\n裨(bì)：弥补，补救。阙，通“缺”， 缺点。\n有所广益：得到更多的好处。\n广益：很多的益处。\n益：好处、益处。\n性行：性情品德。\n性行（xíng)淑均：性情品德善良平正。\n淑：善。\n均：公平，平均。\n晓畅：谙熟，精通。\n试用：任用。\n能：能干，有才能。\n是以：因为这，因此。\n众：大家。\n举：推举。\n督：武职，向宠曾为中部督。\n营：军营、军队。\n行(háng)阵：指部队。\n和睦：团结和谐。\n优劣:才能高的和才能低的。\n亲：亲近。\n信：信任。\n得所：得到恰当的位置。\n先汉：西汉。 兴隆：兴盛。\n后汉：东汉。 倾颓：衰败。\n每：常常。\n桓、灵：东汉末年的桓帝和灵帝。他们都因信任宦官，加深了政治的腐败。\n叹息：感叹惋惜。\n痛恨：感到痛心遗憾。\n恨：遗憾，不满意。\n尚书、长史、参军：都是官名。尚书指陈震，长史指张裔，参军指蒋琬。\n此悉贞良死节之臣：这些都是坚贞可靠，能够以死报国的忠臣。\n悉：全、都。\n贞：坚贞。\n良：善良可靠。\n死节：能够以死报国。死：为……而死。\n隆：兴盛。\n计日：计算着日子。\n布衣：平民百姓。\n躬：亲自，自身。\n耕：耕种。\n躬耕：亲自耕种，实指隐居农村。\n南阳：东汉郡名。即今河南省南阳市。\n苟：苟且。\n全：保全。\n于：在。\n求：谋求。\n闻达：闻名显达。\n以：认为。\n卑鄙：身份低微，见识短浅。卑，身份低下。鄙，见识短浅。与今义不同。\n猥(wěi)：辱，这里有降低身份的意思。\n枉屈：委屈。\n顾：拜访，探望。\n咨：询问。\n由是：因此。\n感激：感动奋激。\n许：答应。\n驱驰：驱车追赶。这里是奔走效劳的意思。\n后值倾覆：后来遇到兵败。汉献帝建安十三年（公元208年）曹操追击刘备，在当阳长坂大败刘军；诸葛亮奉命出使东吴，联合孙权打败曹操于赤壁才转危为安。\n值：遇到。\n倾覆：指兵败。\n尔来：那时以来。\n二十有一年：从刘备访诸葛亮于隆中到此次出师北伐已经二十一年。\n有：通“又”，跟在数词后面表示约数。\n故：所以。\n寄：托付。\n以：把。\n临崩寄臣以大事：刘备在临死的时候，把国家大事托付给诸葛亮，并且对刘禅说：“汝与丞相从事，事之如父。”临：将要。\n夙夜忧叹：早晚/整天担忧叹息。夙，清晨。忧，忧愁焦虑。夙夜：早晚。\n泸：水名，即金沙江。\n不毛：不长草。这里指人烟稀少的地方。毛，庄稼，苗。\n兵：武器。\n甲：装备。\n奖率：激励率领，奖励统帅。奖，鼓励。\n庶：希望。\n竭：竭尽。\n驽(nú）钝：比喻才能平庸，这是诸葛亮自谦的话。\n驽 ，劣马，走不快的马，指才能低劣。\n钝，刀刃不锋利，指头脑不灵活，做事迟钝。\n攘(rǎng)除：排除，铲除。\n奸凶：奸邪凶恶之人，此指曹魏政权。\n还：回。\n于：到。\n旧都：指东汉都城洛阳或西汉都城长安。\n所以：用来……的。\n此臣所以报先帝而忠陛下之职分也：这是我用来报答先帝，效忠陛下的职责本分。\n斟酌：考虑，权衡。\n损：除去。\n益：兴办，增加。\n损益：增减，兴革。\n斟酌损益：斟情酌理、有所兴办。比喻做事要掌握分寸。（处理事务）斟酌情理，有所兴革。\n托臣以讨贼兴复之效：把讨伐曹魏复兴汉室的任务交给我。\n托，委托，交给。\n效，效命的任务。\n不效则治臣之罪：没有成效就治我的罪。\n效，取得成效。\n告：告慰，告祭。\n兴：发扬。\n德：道德。\n言：言论。\n兴德之言：发扬圣德的言论。\n慢：怠慢，疏忽，指不尽职。\n彰其咎：揭示他们的过失。\n彰：表明，显扬。\n咎：过失，罪。\n咨诹(zōu)善道：询问（治国的）好道理。诹(zōu)，询问。\n察纳：认识采纳。察：明察。\n雅言：正确的言论，正言，合理的意见。\n深追：深切追念。\n先帝遗诏：刘备给后主的遗诏，见《三国志·蜀志·先主传》注引《诸葛亮集》，诏中说：‘勿以恶小而为之，勿以善小而不为。惟贤惟德，能服于人。’\n遗诏：皇帝在临终时所发的诏令。\n当：在……时候。\n临：面对\n涕：眼泪。\n零：落下。\n不知所言：不知道该说些什么话。这是表示自己可能失言。谦词。', poem_appreciation = '从文章结构上来看，全文可以分为4部分：\n\n　　Part1，由前两个自然段组成。\n\n　　指出当今天下的基本形势和执政的基本原则，接着提出了基本政策。\n\n　　按逆向思维来分析，似乎小皇帝的某些作为让老丞相有些不满，结合历史上的情况，应该与刘禅偏信宦官有关。于是开宗名义，告诉小皇帝应该端正态度，内外一体。\n\n　　《英雄志》22卷第九章《天之历数在尔躬》中曾对一国兴衰发表过一些看法，似乎是暗合此处的，兹录于此：\n\n　　“欲知一国之兴衰，必先观何处？观一物，必先观其内。何为一国之内？为百姓。何为百姓之内？为法制风气。那法制风气之内呢？天下之风气，必起于天子。那天子之内呢？还有什么？私心。天子的私心都藏于何处？这帝王私心之所在，便在后宫。那儿有他最心爱的人，故而在他心中的份量，足与天下等值。”\n\n　　<Remark>在帝制独裁体制下，在家天下，以伦理学为执政理论基础的执政机制必然受皇帝的后宫影响极大。远如吕后、武则天，近如慈禧。\n\n　　Part2，第3、4、5自然段。\n\n　　告诉小皇帝可以依靠谁，文官是郭攸之、费祎、董允等，武将是向宠。同时告诉小皇帝一般人别信他，都是小人，来祸害你的。\n\n　　<Remark>往好的方向来说，这是在向皇帝推荐优秀干部；反过来也可以说你是在结党，是否营私待定。\n\n　　Part3，第6、7自然段。\n\n　　可能诸葛亮也意识到上面的语气不太合适，有点像老爸教训自己的儿子，虽然叫你相父，你也别当真啊！而且在人事方面有点搞党争的嫌疑，于是开始打苦情牌，追溯自己与老皇帝的关系，这些都是老皇帝让我告诉你的！\n\n　　<Remark>确实是用心良苦，不过小皇帝完全可以这样想，“妈的，这老东西又拿我死去的老爹来压我！”\n\n　　Part4，第8、9自然段。\n\n　　说的差不多了，该结束了。要出征了，向小皇帝立个军令状，也再次告诫小皇帝要听人劝吃饱饭，要有主见。\n\n　　<Remark>罗里吧嗦，絮絮叨叨，保姆真不是好当的啊。\n\n　　整体感知：\n\n　　本文言辞恳切，将军国大事、执政原则都非常清晰地表述出来，可以说是手把手地在教小皇帝。但是通篇都在说自己要报先帝知遇之恩，众将士也是为了报先帝知遇之恩，似乎忽略了小皇帝的个人感受。如果他所用的人都只是冲着自己老爸的面子给自己干活，并不怎么真心服自己，估计他干起来也不会怎么乐意。虽然在以孝治天下的古代社会总是要推崇下先帝，但也不能这么干啊，再怎么孝顺，也得是一朝天子一朝臣啊，康熙、雍正、乾隆莫不如是，并不是一定要用先帝的臣子才能保证国家兴旺、政治稳定。所谓“江山代有人才出”，或许正是诸葛亮对人才梯队建设的忽视，导致了三国后期蜀国再无杰出之士可用。\n\n　　另外，本文中似乎只是泛泛地进行告诫小皇帝要亲贤臣远小人，并没有提出什么具体的政策，更没有告诉小皇帝如何自己去发现人才，只是说“看看，这几个人都是先帝给你选的，你要听他们的话哦”。这就略显扯淡了，不谈人才的标准，这就导致，小皇帝若非天赋异禀，不懂潜规则的话，将永远无法自己发现真正需要的人才。\n\n　　综合来看，这个真是“今当远离，临表涕零，不知所言”了。', poem_tags = '初中文言文,古文观止,励志,劝勉' WHERE poem_title = '出师表 / 前出师表' AND poem_author = '诸葛亮';
UPDATE edu_poem SET poem_translation = '老朋友预备丰盛的饭菜，邀请我到他好客的农家。\n翠绿的树林围绕着村落，苍青的山峦在城外横卧。\n推开窗户面对谷场菜园，手举酒杯闲谈庄稼情况。\n等到九九重阳节到来时，再请君来这里观赏菊花。', poem_notes = '过：拜访。故人庄：老朋友的田庄。庄，田庄。\n具：准备，置办。鸡黍：指农家待客的丰盛饭食（字面指鸡和黄米饭）。黍（shǔ）：黄米，古代认为是上等的粮食。\n邀：邀请。至：到。\n合：环绕。\n郭：古代城墙有内外两重，内为城，外为郭。这里指村庄的外墙。斜（xié）：倾斜。因古诗需与上一句押韵，所以应读xiá。\n开：打开，开启。轩：窗户。面：面对。场圃：场，打谷场、稻场；圃，菜园。\n把酒：端着酒具，指饮酒。把：拿起。端起。话桑麻：闲谈农事。桑麻：桑树和麻。这里泛指庄稼。\n重阳日：指夏历的九月初九。古人在这一天有登高、饮菊花酒的习俗。\n还（huán）：返，来。就菊花：指饮菊花酒，也是赏菊的意思。就，靠近，指去做某事。', poem_appreciation = '这是一首田园诗，描写农家恬静闲适的生活情景，也写老朋友的情谊。通过写田园生活的风光，写出作者对这种生活的向往。全文十分押韵。诗由“邀”到“至”到“望”又到“约”一径写去，自然流畅。语言朴实无华，意境清新隽永。作者以亲切省净的语言，如话家常的形式，写了从往访到告别的过程。其写田园景物清新恬静，写朋友情谊真挚深厚，写田家生活简朴亲切。\n\n　　全诗描绘了美丽的山村风光和平静的田园生活，用语平淡无奇，叙事自然流畅，没有渲染的雕琢的痕迹，然而感情真挚，诗意醇厚，有“清水出芙蓉，天然去雕饰”的美学情趣，从而成为自唐代以来田园诗中的佳作。\n\n　　一、二句从应邀写起，“故人”说明不是第一次做客。三、四句是描写山村风光的名句，绿树环绕，青山横斜，犹如一幅清淡的水墨画。五、六句写山村生活情趣。面对场院菜圃，把酒谈论庄稼，亲切自然，富有生活气息。结尾两句以重阳节还来相聚写出友情之深，言有尽而意无穷。\n\n　　“故人具鸡黍，邀我至田家。”这一开头就像是日记本上的一则记事。故人“邀”而作者“至”，文字上毫无渲染，开门见山，招之即来，简单而随便。这正是不用客套的至交之间所可能有的形式。而以“鸡黍”相邀，既显出田家特有风味，又见待客之简朴。正是这种不讲虚礼和排场的招待，朋友的心扉才往往更能为对方敞开。这个开头，不是很着力，平静而自然，但对于将要展开的生活内容来说，却是极好的导入，显示了气氛特征，又有待下文进一步丰富、发展。\n\n　　“绿树村边合，青山郭外斜。”走进村里，作者顾盼之间竟是这样一种清新愉悦的感受。这两句上句漫收近境，绿树环抱，显得自成一统，别有天地；下句轻宕笔锋，郭外的青山依依相伴，则又让村庄不显得孤独，并展示了一片开阔的远景。由此运用了由近及远的顺序描写景物。这个村庄坐落平畴而又遥接青山，使人感到清淡幽静而绝不冷傲孤僻。正是由于“故人庄”出现在这样的自然和社会环境中，所以宾主临窗举杯。\n\n　　“开轩面场圃，把酒话桑麻”，才更显得畅快。这里“开轩”二字也似乎是很不经意地写入诗的，但上面两句写的是村庄的外景，此处叙述人在屋里饮酒交谈，轩窗一开，就让外景映入了户内，更给人以心旷神怡之感。对于这两句，人们比较注意“话桑麻”，认为是“相见无杂言”（陶渊明《归园田居》）。但有了轩窗前的一片打谷场和菜圃，在绿阴环抱之中，又给人以宽敞、舒展的感觉。话桑麻，就更让读者感到是田园。于是，读者不仅能领略到更强烈的农村风味、劳动生产的气息，甚至仿佛可以嗅到场圃上的泥土味，看到庄稼的成长和收获，乃至地区和季节的特征。有这两句和前两句的结合，绿树、青山、村舍、场圃、桑麻和谐地打成一片，构成一幅优美宁静的田园风景画，而宾主的欢笑和关于桑麻的话语，都仿佛萦绕在读者耳边。它不同于纯然幻想的桃花源，而是更富有盛唐社会的现实色采。正是在这样一个天地里，这位曾经慨叹过“当路谁相假，知音世所稀”的诗人，不仅把政治追求中所遇到的挫折，把名利得失忘却了，就连隐居中孤独抑郁的情绪也丢开了。从他对青山绿树的顾盼、与朋友对酒而共话桑麻中可以看出，他的思绪舒展了，甚至连他的举措都灵活自在了。农庄的环境和气氛，在这里显示了它的征服力，使得孟浩然有几分皈依了。\n\n　　“待到重阳日，还来就菊花。”孟浩然深深为农庄生活所吸引，于是临走时，向主人率真地表示将在秋高气爽的重阳节再来观赏菊花和品菊花酒。淡淡两句诗，故人相待的热情，作客的愉快，主客之间的亲切融洽，都跃然纸上了。杜甫的《遭田父泥饮美严中丞》中说：“月出遮我留，仍嗔问升斗。”杜甫诗中田父留人，情切语急；孟浩然诗中与故人再约，意舒词缓。杜甫的郁结与孟浩然的恬淡之别，读者从这里可以窥见一些消息。\n\n　　一个普通的农庄，一回鸡黍饭的普通款待，被表现得富有诗意。描写的是眼前景，使用的是口头语，描述的层次也是完全任其自然，笔笔都显得很轻松，连律诗的形式也变得自由和灵便了。这种淡淡的平易近人的风格，与作者描写的对象——朴实的农家田园和谐一致，表现了形式对内容的高度适应，恬淡亲切却又不是平浅枯燥。它是在平淡中蕴藏着深厚的情味。一方面固然是每个句子都几乎不见费力锤炼的痕迹，另一方面每个句子又都不曾显得薄弱。比如诗的头两句只写友人邀请，却能显出朴实的农家气氛；三四句只写绿树青山却能见出一片天地；五六句只写把酒闲话，却能表现心情与环境的惬意的契合；七八句只说重阳再来，却自然地流露出对这个村庄和故人的依恋。这些句子平衡均匀，共同构成一个完整的意境，把恬静秀美的农村风光和淳朴诚挚的情谊融成一片。这是所谓“篇法之妙，不见句法”（沈德潜《唐诗别裁》），“不钩奇抉异……若公输氏当巧而不巧者”（皮日休《郢州孟亭记》）。他把艺术美融入整个诗作的血肉之中，显得自然天成。这种不炫奇猎异，不卖弄技巧，也不光靠一两个精心制作的句子去支撑门面，是艺术水平高超的表现。正是因为有真彩内映，所以出语洒落，浑然省净，使全诗从“淡抹”中显示了它的魅力，而不再需要“浓饰盛妆”了。', poem_tags = '唐诗三百首,初中古诗,田园,生活,友情,早教古诗100首' WHERE poem_title = '过故人庄' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '神龟的寿命即使十分长久，但也还有生命终结的时候。\n螣蛇尽管能乘雾飞行，终究也会死亡化为土灰。 \n年老的千里马躺在马棚里，它的雄心壮志仍然是能够驰骋千里。\n有远大抱负的人士到了晚年，奋发思进的雄心不会止息。\n人的寿命长短，不只是由上天所决定的。\n只要自己调养好身心，也可以益寿延年。\n我非常庆幸，就用这首诗歌来表达自己内心的志向。', poem_notes = '该于建安十二年(207)，这时曹操五十三岁。选自《先秦汉魏晋南北朝诗》（中华书局1983年版）。这首诗是曹操所作乐府组诗《步出夏门行》中的第四章。诗中融哲理思考、慷慨激情和艺术形象于一炉，表现了老当益壮、积极进取的人生态度。此诗是曹操的乐府诗《步出夏门行》四章中的最后一章。\n“神龟”二句：神龟虽能长寿，但也有死亡的时候。神龟，传说中的通灵之龟，能活几千岁。寿，长寿。　 3.竟：终结，这里指死亡。\n“螣(téng)蛇”二句：腾蛇即使能乘雾升天，最终也得死亡，变成灰土。腾蛇，传说中与龙同类的神物，能乘云雾升天。\n骥(jì)：良马，千里马。\n伏：趴，卧。\n枥(lì)：马槽。\n烈士：有远大抱负的人。暮年：晚年。\n已：停止。\n盈缩：指人的寿命长短。盈，满，引申为长。缩，亏，引申为短。\n但：仅，只。\n养怡：指调养身心，保持身心健康。怡，愉快、和乐。\n永：长久。永年：长寿，活得长。\n幸甚至哉，歌以咏志：两句是附文，跟正文没关系，只是抒发作者感情，是乐府诗的一种形式性结尾。', poem_appreciation = '这是一首充满诗人对生活的真切体验的哲理诗，因而写得兴会淋漓，有着一种真挚而浓烈的感情力量；哲理与诗情又是通过形象化的手法表现出来的，因而述理、明志、抒情在具体的艺术形象中实现了完美的结合。\n\n　　诗中“神龟虽寿，犹有竟时。腾蛇乘雾，终为土灰。”作者从朴素的唯物论和辩证法的观点出发，否定了神龟、腾蛇一类神物的长生不老，说明了生死存亡是不可违背的自然规律。“ 犹有 ”和“ 终为 ” 两个词组下得沉着。而 “ 老骥 ” 以下四句，语气转为激昂，笔挟风雷，使这位 “ 时露霸气 ” 的盖世英豪的形象跃然纸上。\n\n　　“ 老骥伏枥，志在千里，烈士暮年，壮心不已。” 笔力遒劲，韵律沉雄，内蕴着一股自强不息的豪迈气概，深刻地表达了曹操老当益壮、锐意进取的精神面貌。“壮心不已”表达了要有永不停止的理想追求和积极进取精神，永远乐观奋发，自强不息，保持思想上的青春，曹操以切身体验揭示了人的精神因素对健康的重要意义。\n\n　　“盈缩之期，不但在天；养怡之福，可得永年。”表现出一种深沉委婉的风情，给人一种亲切温馨之感。全诗跌宕起伏，又机理缜密，闪耀出哲理的智慧之光，并发出奋进之情，振响着乐观声调。艺术风格朴实无华，格调高远，慷慨激昂，显示出诗人自强不息的进取精神，热爱生活的乐观精神。\n\n　　人寿命的长短不完全决定于天，只要保持身心健康就能延年益寿。曹操所云“养怡之福”，不是指无所事事，坐而静养，而是说一个人精神状态是最重要的，不应因年暮而消沉。这里可见诗人对天命持否定态度，而对事在人为抱有信心的乐观主义精神，抒发了诗人不甘衰老、不信天命、奋斗不息、对伟大理想的追求永不停止的壮志豪情。', poem_tags = '古诗三百首,初中古诗,咏志,哲理' WHERE poem_title = '龟虽寿' AND poem_author = '曹操';
UPDATE edu_poem SET poem_translation = '浩浩荡荡的离别愁绪向着日落西斜的远处延伸, 离开北京，马鞭向东一挥，感觉就是人在天涯一般。\n我辞官归乡，有如从枝头上掉下来的落花，但它却不是无情之物，化成了春天的泥土，还能起着培育下一代的作用。', poem_notes = '选自《龚自珍全集》\n浩荡离愁：离别京都的愁思浩如水波，也指作者心潮不平。浩荡：无限。\n吟鞭：诗人的马鞭。 东指：东方故里。 天涯：指离京都遥远。\n落红：落花。花朵以红色者为尊贵，因此落花又称为落红。\n花：比喻国家。即：到。', poem_appreciation = '作者当时愤然辞官，离别亲朋好友，愁肠百结。“浩荡”一词，除了说明愁绪之浓，还蕴蓄着对当时社会的不满、对当政者的愤然、对人民生活的担忧等各种复杂的思想感情。\n\n　　“浩荡离愁白日斜”。别离愁绪已经充塞天地、浩浩难禁，何况正值夕阳西坠，日暮摇落之际，诗人此时的心绪，便可想而知。如果借用词组结构方式分析其中的意蕴，以“离愁”为中心词的话，那么，“浩荡”是“离愁”的定语，而“白日斜”则是“离愁”的补语。“白日斜”是说作者带着离愁南归，因为愁绪郁积在胸中，所以感觉上时间过得很快，不知不觉已日薄西山。这里不说“夕阳”而取“白日”，正好与作者当时的心情相吻合，也隐喻当时国势渐颓的社会现实。 在中国古典诗歌中，诗人们常常喜欢用落日作为自然现象和象征韶光易逝的双重手法来显示相思之烈或别离之苦。“携手上河梁，游子暮何之”（《古诗》）；“浮云游子意，落日故人情”（李白《送友人》）；“念去去，千里烟波，暮霭沉沉楚天阔”（柳永《雨霖铃》）；“斜阳却在，烟柳断肠处”（辛弃疾《摸鱼儿》）。“吟鞭东指即天涯”。“吟鞭”是指诗人的马鞭，“东指”点明了此行的目的地——故乡（浙江）。“即天涯”是说距离故乡还很远。 马鞭举处，前面便是离京师越来越远的海角天涯。元人马致远的《天净沙》写秋思：“枯藤老树昏鸦，小桥流水人家。古道西风瘦马。夕阳西下，断肠人在天涯。”龚自珍以“浩荡”修饰离愁，以“白日斜”烘托离愁，以“天涯”映衬离愁，这种多层次的描写方法和马致远的“夕阳西下，断肠人在天涯”有异曲同工之妙。只不过龚自珍的“吟鞭东指即天涯”没有直接说自己是“断肠人”而已。\n\n　　按理说，龚自珍不满于死气沉沉的礼部衙门生活，毅然辞去礼部主事之职，准备回家乡杭州干一番事业，只身出都，有的只是对旧势力的决裂之感和憎恶之情，不应产生浩荡的离愁。唐诗人刘皂《旅次朔方》云：“无端更渡桑干水，却望并州是故乡。”说由于迁谪到更远的地方，因此连客舍地也成为故乡了。不同之处在于，龚自珍虽说是浙江仁和（今杭州）人，但小时候在北京住过，又在礼部和其他机构做了十余年京官，京城早已成了他的第二故乡。虽然龚自珍是主动要求辞职，但辞职的原因却是因为沉沦下僚，生活拮据，事出无奈，客观上是被迫离京出都。因此，“浩荡离愁”中，含有些许仕途蹭蹬，不为世用的感叹和在政治上、思想上的孤独感。兼之龚自珍当时与妓女灵箫关系十分密切，《己亥杂诗》十分之一的主题都与灵箫有关，其中一首说自己正堕入“红似相思绿似愁”的情场里，虽说灵箫并不在京师，但在这种情况下，与过去的生活告别，缠绵悱恻、依依不舍的“离愁”也就难排难遣。可见，龚自珍的“离愁”内涵是丰富、复杂和多方面的。\n\n　　日暮的片片飞花，撩起诗人的离愁。事业未竟，岁月蹉跎，青春已逝，红日西沉，今番出都，也许不再回还，作为描摹落花的能手，诗人爱“探春”，更爱“送春”，爱花开，也许更爱看花落，他曾在《西郊落花歌》中说纷飞的海棠花是到人间飘泊逗留的奇龙怪凤，把大风中海棠纷谢的奇景比作“如钱塘潮夜澎湃；如昆阳战晨披靡；如八万四千天女洗脸罢，齐向此地倾胭脂”。“又闻净土落花深四寸，冥目观想尤神驰”，想像“安得树有不尽之花更雨新好者，三百六十日长是落花时”。他对落花作过那么多美妙的比喻，而如今，诗人突然感到自己像一片飘飞的落花。辞别京都，诗人乘马车出都，一路情不能已，对着无边的落花，展开丰富的想像。官场的倾轧，沉重的氛围，窒息的人性，拮据的生活，诗人把自己的身世与落花完全融为一体。\n\n　　“落红不是无情物”，这里的“落红”两字。在全诗中地位十分重要。它上承“浩荡离愁”，诗人的离愁不仅有“浩荡”修饰，“白日斜”烘托，“天涯”映衬，还被动态的，由时时拂面而过的“落红”撩起。这一笔是隐藏在诗内的，因此，“落红”既是对前面离愁内涵的补充，而作为转折，它又使整首诗从离愁中解脱出来，转入下层，为全诗主题升华作了铺垫。此时诗人在想落红护花。“落红”即落花，全句的本义是说从树上飘落的花瓣并不是无情之物，而是依附地表，腐烂成泥，化作精魂，养育来年的春花。作者借自然的循环法则来自比，表示自己虽然辞官，但仍会关心国家的前途命运。这富有哲理的一句话，传达出诗人“不在其位，亦谋其政”的难能可贵的精神，表明了诗人无比坚定的决心，成为千古名句，激励着许多人“老骥伏枥，志在千里”。落花决不是无情的废物，诗人辞去礼部主事之职，正是为了到家乡主掌书院，聚徒讲学，把自己的学业和思想传给生徒，以变革的热情和未来的憧憬启迪他们，为国为民尽自己的最后一点力量。花落归根，化为春泥，正可以孕育新的春天，色彩、芬芳，正可以献给后之来者。诗人从大自然生生不息的规律中得到启发。大自然里花开花落，本来风雨由之，无感情可言，落红说不上是“有情物”还是“无情物”，只是诗人把自己的身世与落花完全结合起来，把感情移向落花，才使落花也具有人的感情，从而变成有情物。落花有情，表现在去酿造新的彩色的世界——“化作春泥更护花”。至此，诗人终于把飞花般纷乱的思绪捉住，从愁思中摆脱出来，带着时代的使命感，上升到一种庄严神圣的境界。“化作春泥更护花”，这是飞花的独自，也是诗人与腐败的官场决裂，向黑暗的势力抗争的庄严而神圣的宣誓。为了国家和黎民百姓，为了似锦繁花，不惜献身化为春泥。\n\n　　古代诗人描写落花，一种是怨啼鸟，怪东风，叹年华，面对落花，嘘唏感叹。“流水落花春去也，天上人间”（李煜《浪淘沙》）；“花自飘零水自流，一种相思，两处闲愁”（李清照《一剪梅》）；《红楼梦》中林黛玉葬花词：“依今葬花人笑痴，他年葬侬知是谁？”杜牧《金谷园》甚至把落花比作堕楼美人：“繁华事散逐香尘，流水无情草自春；日暮东风怨啼鸟，落花犹似堕楼人。”把风吹花落悄无声的自然景象与美人堕楼联系在一起，以粉红的花瓣从枝头飘落比拟红粉佳人堕楼，寓有美人如花，红颜薄命，美好的事物殒于一旦的感叹，讽刺了石崇“金谷园”繁华事散，好景不长的可悲结局，而把花落比作美人堕楼，有些凄楚肃杀，充满浓郁的感伤之情。另一种把落花作为自然景物来描写，其中不乏昂扬向上的精神。“时有落花至，远随流水香”（刘慎虚《阙题》）；“春城无处不飞花”（韩翃《寒食》）；“花落春仍在”（俞樾试帖诗），孟浩然的《春晓》“夜来风雨声，花落知多少”也只见童子的浑朴天真和烂漫之趣，而无伤春惜花之情。有的充满勃勃生机，有的在飒衰中现出昂奋。但是，无论是“春城无处不飞花”，还是“花落春仍在”，比起龚自珍的“落红不是无情物，化作春泥更护花”来，境界上要略逊一筹。即使化做春泥，也甘愿培育美丽的春花成长。不为独香，而为护花。表现诗人虽然脱离官场，依然关心着国家的命运，不忘报国之志，以此来表达他至死仍牵挂国家的一腔热情；充分表达诗人的壮怀，成为传世名句。\n\n　　这首小诗将政治抱负和个人志向融为一体，将抒情和议论有机结合，形象地表达了诗人复杂的情感。龚自珍论诗曾说“诗与人为一，人外无诗，诗外无人”（《书汤海秋诗集后》），他自己的创作就是最好的证明。', poem_tags = '古诗三百首,初中古诗,叙事,抒情,爱国,抱负,早教古诗100首' WHERE poem_title = '己亥杂诗·其五' AND poem_author = '龚自珍';
UPDATE edu_poem SET poem_translation = '京口和瓜洲不过一水之遥，钟山也只隔着几重青山。\n温柔的春风又吹绿了大江南岸，可是，天上的明月呀，你什么时候才能够照着我回家呢？', poem_notes = '泊船：停船。泊，停泊。指停泊靠岸。\n绿：吹绿。\n京口：古城名。故址在江苏镇江市。\n瓜洲：镇名，在长江北岸，扬州南郊，即今扬州市南部长江边,京杭运河分支入江处。\n一水：一条河。古人除将黄河特称为“河”，长江特称为“江”之外，大多数情况下称河流为“水”，如\n汝水、汉水、浙水、湘水、澧水等等。这里的“一水”指长江。一水间指一水相隔之间。\n钟山：在江苏省南京市区东。', poem_appreciation = '这首诗作于1075年（熙宁八年）二月。当时王安石第二次拜相，奉诏进京，舟次瓜洲。首句“京口瓜洲一水间”，以愉快的笔调写他从京口渡江，抵达瓜洲。“一水间”三字，形容舟行迅疾，顷刻就到。次句“钟山只隔数重山沙，以依恋的心情写他对钟山的回望，王安石于1037年(景佑四年)随父王益定居江宁(今江苏南京)，从此江宁便成了他的息肩之地，第一次罢相后即寓居江宁钟山(今南京紫金山)。“只隔”两字极言钟山之近在咫尺。把“数重山刀的间隔说得如此平常，反映了诗入对于钟山依恋之深;而事实上，钟山毕竟被“数重山”挡住了，因此诗人的视线转向了江岸。\n\n　　古人云：“望秋云神飞扬，临春风思浩荡。”第三句“春风又绿江南岸”，描绘了江岸美丽的春色，寄托了诗人浩荡的情思。其中“绿”字是经过精心筛选的，极其富于表现力。洪迈《多斋续笔》卷八云：“吴中士人家藏其草。初云‘又到江南岸’，圈去’到‘字，注曰‘不好’。改为‘过’，复圈去而改为’入‘。旋改‘满’。凡如是十许字，始定为‘绿’。”作者认为“到”、“过”、“入”、“满“等字都不理想，只有“绿”字最为精警。这是因为：一、前四字都只从风本身的流动着想，粘皮带骨，以此描写看不见的春风，依然显得抽象，也缺乏个性；“绿”字则开拓一层，从春风吹过以后产生的奇妙的效果着想，从而把看不见的春风转换成鲜明的视觉形象——春风拂煦，百草始生，千里江岸，一片新绿。这就写出了春风的精神，诗思也深沉得多了。二、本句描绘的生机盎然的景色与诗人奉召回京的喜悦心情相谐合，”春风”一词，既是写实，又有政治寓意。“春风”实指皇恩。宋神宗下诏恢复王安石的相位，表明他决心要把新法推行下去。对此，诗人感到欣喜。他希望凭借这股温暖的春风驱散政治上的寒流，开创变法的新局面。这种心情，用“绿”字表达，最微妙，最含蓄。三、‘绿”字还透露了诗人内心的矛盾，而这正是本诗的主旨。鉴于第一次罢相前夕朝廷上政治斗争的尖锐复杂，对于这次重新入相，他不能不产生重里的顾虑。变法图强，遐希翟契是他的政治理想;退居林下，吟咏情性，是他的生活理想。由于变法遇到强大阻力，他本人也受到反对派的猛烈攻击，秀丽的钟山、恬静的山林，对他产生了很大的吸引力。《楚辞·招隐士》：“王孙游兮不归，春草生兮凄凄”王维《送别》：“春草年年绿，王孙归不归?”，都是把草绿与思归联系在一起的。本句暗暗融入了前人的诗意，表达了作者希望早日辞官归家的心愿。这种心愿，至结句始明白揭出。\n\n　　毋庸讳言，用绿字描写春风，唐人不乏其例。李白《侍从宜春苑奉诏赋龙池柳色初晴听新莺百啭歌》：“春风已绿瀛洲草，紫段红楼觉春好。”丘为《题农父庐舍》：“春风何时至?已绿湖上山。”温庭筠《敬答李先生》：“绿昏晴气春风岸，红漾轻轮野水天”，常建的《闲斋卧雨行药至山管稍次湖庭》：“主人山门绿，小隐湖中花”。等，都为王安石提供了借鉴，但从表现思想感情的深度来说，上述数例，而“山门”“山”“草”皆可绿，而江南岸的绿却是颇有动感，青出于蓝而胜于蓝。\n\n　　结句“明月何时照我还”，从时间上说，已是夜晚。诗人回望既久，不觉红日西沉，皓月初上。隔岸的景物虽然消失在朦胧的月色之中，而对钟山的依恋却愈益加深。他相信自己投老山林，终将有日，故结尾以设问句式表达了这一想法。\n\n　　“文字频改，工夫自出。”（《童蒙诗训》）本诗曾获得“超然迈伦，能追逐李杜陶谢“（《彦周诗话》)的赞誉。这正是“频改”所致。但这首诗的佳处，并不限于一字之工，当玩赏其全篇的精神所在，方能得其体要。', poem_tags = '古诗三百首,小学古诗,春天,写景,抒怀,思乡,早教古诗100首' WHERE poem_title = '泊船瓜洲' AND poem_author = '王安石';
UPDATE edu_poem SET poem_translation = '您问归期，归期实难说准，巴山连夜暴雨，涨满秋池。\n何时归去，共剪西窗烛花，当面诉说，巴山夜雨况味。', poem_notes = '寄北：写诗寄给北方的人。诗人当时在巴蜀（现在四川省），他的亲友在长安，所以说“寄北”。这首诗表达了诗人对亲友的深刻怀念。\n君：对对方的尊称，等于现代汉语中的“您”。\n归期：指回家的日期。\n巴山：指大巴山，在陕西南部和四川东北交界处。这里泛指巴蜀一带。\n秋池：秋天的池塘。\n何当：什么时候。\n共：副词，用在谓语前，表示动作行为是由两个或几个施事者共同发生的。可译为“一起”。\n剪西窗烛：剪烛，剪去燃焦的烛芯，使灯光明亮。这里形容深夜秉烛长谈。“西窗话雨”“西窗剪烛”用作成语，所指也不限于夫妇，有时也用以写朋友间的思念之情。 \n却话：回头说，追述。', poem_appreciation = '在南宋洪迈编的《万首唐人绝句》里，这首诗的题目为《夜雨寄内》，意思是诗是寄给妻子的。从诗中“巴山”一语看来，诗写于巴蜀之地。李商隐曾经应聘到四川，任东川节度柳仲郢的幕僚，时间是唐宣宗大中六年（公元852年）。先于此一年，李商隐的妻子却已故去。给李商隐诗集作笺注的清代人冯浩，尽管认为诗题不必改作“寄内”（因为“集中寄内诗皆不明标题”），但内容却是“寄内”的。为此，他把诗的写作时间，推前至大中二年（公元848年）。按冯浩考证，李商隐这一年是在桂州（今广西桂林）郑亚的幕府。当年郑亚由于政敌的诬陷，被贬为循州刺史。李商隐未去循州，由水路经长沙，于次年回到长安。冯浩认为在归途中李商隐曾经“徘徊江汉、往来巴蜀”，“于巴蜀间兼有水陆之程”。《夜雨寄北》就是写在归途中经过巴蜀时。近人岑仲勉、陈寅恪曾经指出关于巴蜀之程的说法是不正确的。其实，冯浩也没有说得太死。他含糊地说，李商隐这时到过巴蜀，“玩诸诗自见，但无可细分确指”。可见，通常把《夜雨寄北》，说是李商隐寄给自己妻子的；这一说，似还可再斟酌。\n\n　李商隐的一生是不幸的。他刚刚踏入仕途，就被卷进了牛、李的朋党之争中。（牛，牛僧孺；李，李德裕。朋党，官僚集团。）852年随柳仲郢入蜀，实属迫不得已。仕途多艰，妻子早逝，心境是悲凉的。几年以前，当他在徐州卢循正幕府时，他颇为踌躇满志。“且吟王粲从军乐，不赋渊明归去来。”（《赠四同舍》）到四川以后，这种乐观情绪消失了。“三年苦雾巴江水，不为离人照屋梁。”（《初起》）他断绝了与外界的交往，甚至与同府的幕僚也没有什么交谊。《夜雨寄北》，写得一往情深，而且诗寄的“君”，关切地问着他的归期，他也盼着与“君”“共剪西窗烛”。这个“君”，至少具备三个条件。一，以往过从较密；二，此刻仍有诗书交往；三，彼此心心相印。从现存的李商隐的诗文看来，有一个人可以成为这样的“君”，那就是晚唐的词人温庭筠。李商隐在徐州幕时，温曾有诗“秋日旅舍寄义山李侍御”。李商隐在四川时，也有三首诗寄赠温。温的出身较李要名贵些，是唐初宰相温彦博的裔孙，但他也同样受到牛党令狐绹的排挤和压抑，晚年才做了方城尉与国子助教。如果没有相反的证据，大概可以说，《夜雨寄北》，是李商隐在梓州幕府时写给温庭筠的。这样，或许能更为精细地品味出诗中蕴含的情感内容。\n\n　　“君问归期未有期”，诗一开始，就摆出了不可解脱的矛盾。归期的希望与未有期的失望，两相对立。悲怆沉痛，笼罩全篇。“巴山夜雨涨秋池”，表面上看，是即景点题。但是这一景象把归期未有期的沉痛情绪，渲染得更形象、更浓郁了。独在他乡异域的巴山，是秋天，又是深夜，又是夜雨。这一情境本身就是令人伤感的。尤其是“涨秋池”三字，秋雨绵绵，把池水都涨满了。诗人抓住了这一精细的而又富于生活实感的画面，调动读者的想象，似乎秋池里涨的不是秋水，而是诗人难以解脱的痛苦。\n\n　　绝句虽属短制，但也讲究结构的技艺。前人有言，绝句大抵起承二句困难，然不过平直叙起为佳，从容承之为是。至如宛转变化工夫，全在第三句。这首诗的第三句，就显示了这种工夫。“何当共剪西窗烛”，宕开一笔，从眼前跳脱到将来，从巴山跳脱到北方（长安），用示现的修辞方法，写出诗人的遐想。“共剪西窗烛”，可能溶化了杜甫《羌村三首》中“夜阑更秉烛，相对如梦寐”的诗境，但是由夫妇化为友朋，活用了，情味更浓。“何当”二字，意思是“什么时候才能够”，照应首句“未有期”，既有热切地盼望，又有难以料定的惆怅。在情意上，与前两句，似断非断。\n\n　　第四句显得更为精彩。“却话巴山夜雨时”，是承“共剪西窗”而来，为顺流之舟。在短小得只能有四句的绝句体裁里，毫不可惜地运用了重复句意，不能不谓之大胆。然而，再次出现的“巴山夜雨”，无单调之嫌，文意反而曲折深厚。如果说，前一句“巴山夜雨”是以景写情，那么这一句的“巴山夜雨”却是以情写景。它与“西窗剪烛”，组成一幅温暖的动态画面，表现了诗人对于归期的向往，对于“君”的深厚友情。这给诗中增添了欢欣感。这种欢欣只是一种难以卜料的期待，因而示现于将来的欣慰，又加剧了眼前归期未有期的痛苦。我们可以感受到诗人的情感不断起伏、跳跃，但是通篇的情感色调又是和谐、统一的。\n\n　　李商隐的诗，特别是他晚年的诗，感伤情绪很浓。这种感伤反映了时代的黑暗，反映了他个人遭遇的不幸。《夜雨寄北》，虽然有些欢欣的折光，总的看来，也是感伤的。只是这种感伤表现得很曲折、很深沉。一句“巴山夜雨涨秋池”，隐含了多少丰富的潜台词。这里似乎不是由于夫妻分离而感到的痛苦，实在是深深包含了诗人此时此地回顾一生的哀愁，隐含着对于现实的愤懑与绝望。\n\n　　这首诗即兴写来，写出了诗人刹那间情感的曲折变化。语言是朴实的，在遣词、造句上看不出修饰的痕迹。李商隐的大部分诗，辞藻华美，用典精巧，长于象征、暗示。这首《夜雨寄北》，表现了李商隐诗的另一种风格：质朴、自然，却同样具有“寄托深而措辞婉”的艺术特色。', poem_tags = '唐诗三百首,初中古诗,高中古诗,写雨,写景,思念,爱情' WHERE poem_title = '夜雨寄北' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '我本来知道，当我死后，人间的一切就都和我无关了；但唯一使我痛心的，就是我没能亲眼看到祖国的统一。\n因此，当大宋军队收复了中原失地的那一天到来之时，你们举行家祭，千万别忘把这好消息告诉我！', poem_notes = '示儿：写给儿子们看。\n元知：原本知道。元，通“原”。本来。在苏教版等大部分教材中本诗第一句为“死去元知万事空”，但在老的人教版等教材中为“死去原知万事空”，因为是通假字，所以并不影响本诗的意境，尚有争议。人教版等教材多为“元”，不常用通假字。\n万事空：什么也没有了。\n但：只是。\n悲：悲伤\n九州：这里代指宋代的中国。古代中国分为九州，所以常用九州指代中国。\n同：统一。\n王师：指南宋朝廷的军队。\n北定：将北方平定。\n中原：指淮河以北被金人侵占的地区。\n家祭：祭祀家中先人。\n无忘：不要忘记。\n乃翁：你的父亲，指陆游自己。', poem_appreciation = '此诗是陆游爱国诗中的又一首名篇。陆游一生致力于抗金斗争，一直希望能收复中原。虽然频遇挫折，却仍然未改变初衷。从诗中可以领会到诗人的爱国激情是何等的执着、深沉、热烈、真挚！也凝聚着诗人毕生的心事，诗人始终如一地抱着当时汉民族必然要光复旧物的信念，对抗战事业具有必胜的信心。题目是《示儿》，相当于遗嘱。在短短的篇幅中，诗人披肝沥胆地嘱咐着儿子，无比光明磊落，激动人心！浓浓的爱国之情跃然纸上。\n\n　　诗人在写此诗的十一年以前，叹息过“死前恨不见中原”，在热烈地期待着旧业的光复。直到临终之际，诗人仍然抱有这样坚定的信念，宋朝的抗敌部队要挥戈北上，赶走敌人，收复失地，平定中原。这对于诗人自己，当然是看不到了，只有后代的儿孙们能看到。于是深情地嘱咐儿子，当皇朝的军队收复中原的时候，不要忘记把“北定中原”这个大好的消息告诉诗人，以求了结一桩重大的心事。\n\n　　首句“死去元知万事空”，表明诗人即将离开人世，就什么都没有了，万事皆空，用不着牵挂了，从中体会诗人那种悲哀凄凉之心情。但从诗人的情感流向来看，有着更加重要的一面，“元知万事空”这话看来平常，但就全诗来说非常重要。它不但表现了诗人生死所恋，死无所畏的生死观，更重要的是为下文的“但悲”起到了有力的反衬作用。“元”、“空”二字更加强劲有力，反衬出诗人那种“不见九州同”则死不瞑目的心情。\n\n　　第二句“但悲不见九州同”描写诗人的悲怆心境。此句诗意是诗人向儿子们交代他至死也无法排除的极大悲痛的心境，那就是没有亲眼看到祖国的统一而深深感到遗憾。这一句中的“悲”字是句眼，诗人临终前悲怆的不是个人生死，而是没有看见祖国的统一。表明自己心有不甘，因为“不见九州同”。“悲”引擢文盟字深刻反映了诗人内心的悲哀、遗感之情。\n\n　　第三句“王师北定中原日”，诗人以热切期望的语气表达了渴望收复失地的信念。表明诗人虽然沉痛，但并未绝望。诗人坚信总有一天宋朝的军队必定能平定中原，光复失地。有了这一句，诗的情调便由悲痛转化为激昂。\n\n　　最后一句“家祭无忘告乃翁”，情绪又一转，无奈自己已经看不到祖国统一的那一天，只好把希望寄托于后代子孙。于是深情地嘱咐儿子，在家祭时千万别忘记把“北定中原”的喜讯告诉你的父亲。表达的诗人坚定的信念和悲壮的心愿，充分体现了年迈衰老的陆游爱国、报国之情，从中受到感染，加深热爱祖国的情感。\n\n　　此诗“悲壮沉痛”、“可泣鬼神”，歌颂陆游爱国精神光照千秋。用笔曲折，行文多变，情真意切地表达了诗人临终时复杂的思想情绪和诗人忧国忧民的爱国情怀，既有对抗金大业未就的无穷遗恨，也有对神圣事业必成的坚定信念。全诗有悲的成分，但基调是激昂的。语言浑然天成，没有丝毫雕琢，全是真情的自然流露，但比着意雕琢的诗更美、更感人。', poem_tags = '古诗三百首,爱国,忧国忧民,早教古诗100首' WHERE poem_title = '示儿' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '元丰六年十月十二日夜晚（或公元1083年十月十二日夜，可不译），（我）脱下衣服准备睡觉时，恰好看见月光照在门上，（于是我就）高兴地起床出门散步。想到没有和我一起游乐的人，于是（我）前往承天寺寻找张怀民。怀民也没有睡，我们便一同在庭院中散步。月光照在庭院里像积满了清水一样澄澈透明，水中的水藻、荇菜纵横交错，原来是竹子和柏树的影子。哪一个夜晚没有月光？（又有）哪个地方没有竹子和柏树呢？只是缺少像我们两个这样清闲的人罢了。', poem_notes = '选自<<东坡志林>>。此文写于作者贬官黄州期间。承天寺，在今湖北黄冈市南。\n元丰六年：公元1083年。元丰，宋神宗年号。当者被贬黄州已经四年。\n解：把系着的腰带解开。\n欲：想要，准备。\n月色：月光。\n入：照入，映入。\n户：堂屋的门；单扇的门。\n起：起身。\n欣然：高兴、愉快的样子。欣，高兴，愉快。然，……的样子。\n行：出行。\n念无与为乐者：想到没有和我一起游乐的人。念，想到。 无与为乐者，没有可以共同交谈（游乐或赏月）的人。者：……的人。\n遂：于是，就。\n至：到。\n寻：寻找。\n张怀民：作者的朋友。名梦得，字怀民，清河（今河北清河）人。元丰六年贬谪到黄州，寄居承天寺。\n亦：也。\n寝：睡，卧。\n相与步于中庭：（我们）一同在庭院中散步，相与，共同，一同。步，散步。于：在。中庭，庭院里。\n空明：清澈透明。\n藻荇：泛指生长在水中的绿色植物。藻，藻类植物。荇，荇菜。这里借指月色下的竹柏影。\n交横（héng）：交错纵横。\n盖：承接上文，解释原因，表示肯定，相当于‘大概’，这里解释为‘原来是’。\n也：句末语气词，表判断。（盖……也：原来是。）\n为：动词。做。\n但少闲人如吾两人者耳：只是很少有像我们两个这样的闲人罢了。但，只（是）仅仅。\n闲人：闲散的人。这里是指不汲汲于名利而能从容流连光景的人。苏轼这时被贬为黄州团练副使，这里是一个有职无权的官，所以他十分清闲，自称“闲人”。首先“闲人”指具有情趣雅致，能欣赏美景的人。其次“闲人”反映了作者仕途失意的苦闷心境。\n耳：语气词,“罢了”。', poem_appreciation = '整体赏析 　　这里的“美”首先来自内容的“真”。东月朗照，激发了作者的游兴，想到没有“与乐者”，未免美中不足，因而寻伴，这时错觉生趣，情感触动，于是记下此景此情，顺理成章，一切是那么的和谐自然，毫无雕饰造作之感。这“美”来自语言的“纯”。笔记如同拉家常，娓娓叙来。虽然没有奇景之处，但却不能增删或改动什么字眼儿。点明日期，是笔记体游记所必须的，“月色入户”与“欣然起行”互为因果，寥寥数字，何其洗练！写庭下景色，用“空明”一词，不枝不蔓，体现出空灵、坦荡的意境，将竹柏影子比作水中藻荇，已然十分贴切，“交横”一词更准确地表现了藻荇姿态，仿佛触手可及。接着，作者笔锋陡转，连发二问，既亲切自然，富于韵律，又拓展时空，发人思绪。《记承天寺夜游》表达的感情是微妙而复杂的 　　苏轼自己评论他的文学创作，有一段话很精辟： 　　吾文如万斛泉源，不择地皆可出。在平地，滔滔汩汩，虽一日千里无难。及其与山石曲折，随物赋形，而不可知也。所可知者，常行于所当行，常止于不可不止，如是而已矣!其他，虽吾亦不能知也。（《文说》） 　　这段话，可与他的另一段话相补充：“夫昔之为文者，非能为之为工，乃不能不为之为工也。山川之有云雾，草木之有华实，充满勃郁而见于外，夫虽欲无有，其可得耶？”（《江行唱和集序》） 　　这“美”来自结尾的“精”。从文章结构看，结句属“合”，就此打住。从语意上看，它包蕴丰富。“闲人”一词，表面上是自嘲地说自己和张怀民是清闲的人，闲来无事才出来赏月的，实际上却为自己的行为而自豪——月夜处处都有，却是只有情趣高雅的人能欣赏的，有了人的欣赏才有美，只有此时此地的月夜才是最幸运的，因为有情趣高雅的人来欣赏它。其次，“闲人”包含了作者郁郁不得志的悲凉心境，作者在政治上有远大的抱负，但是却被一贬再贬，流落黄州，在内心深处，他又何尝愿做一个“闲人”呢？赏月“闲人”的自得只不过是被贬“闲人”的自慰罢了。 　　总之，游记以真情实感为依托，信笔写来，起于当起，止于当止，犹如行云流水，于无技巧中见技巧，达到了“一语天然万古新，豪华落尽见真纯”的境界。\n\n分层赏析 　　全文分三层。 　　第一层叙事：交待了时间，地点和夜游原因。 　　首句即点明事件时间“元丰六年十月十二日”，时苏轼因“乌台诗案”被贬至黄州为团练副使已经四年了。这天夜里，月光照入他的房间，作者本欲就寝，怎奈被这美好的月色所迷，顿起雅兴，但想到没有同乐之人，遂动身去不远的承天寺寻张怀民。张怀民和苏轼一样，亦是被贬至黄州来的贬官，他和苏轼的友谊相当笃厚。当晚，张怀民也还未睡，于是二人一起来到院子中间散步。这一层叙事，朴素、淡泊而有自然流畅。(寻友夜游) 　　第二层写景：描绘庭中月光的澄清。 　　作者惜墨如金，只用十八个字，就营造出一个月光澄碧、竹影斑驳、幽静迷人的夜景。读者自可以发挥想象：月光清朗，洒落庭中，那一片清辉白茫茫一片好似积水空潭一般，更妙的是，“水”中还有水草漂浮，游荡，于是乎恍恍然便如仙境一般了。作者的高妙之处在于，以竹、柏之影与月光两种事物互相映衬、比拟、比喻手法精当，新颖，恰如其分地渲染了景色的幽美肃穆。更体现出了月光清凉明净的特点，衬托出作者闲适的心境。(庭中夜色) 　　第三层：惋惜无人赏月 　　便转入议论。作者感慨到，何夜无月，何处无竹柏，可是有此闲情雅致来欣赏这番景色的，除了他与张怀民外，恐怕就不多了，整篇的点睛之笔是“闲人”二字，苏轼谪居黄州，“不得签书公事”，所担任的只是个有名无实的官，与儒家的“经世济民”之理想相去甚远，即所谓“闲人”之表层意义，它委婉地反映了苏轼宦途失意的苦闷；从另一个方面来看，月光至美，竹影至丽，而人不能识，唯此二人能有幸领略，岂非快事！苏轼的思想横跨儒释道三家，这便使他的处世态度有极大的包容性，可以说是宠辱不惊，进退自如。当然，他在逆境中的篇章更能折射出他的人格魅力！(月下抒情)\n\n细化赏析 　　“月色入户”：寒夜寂寥，“解衣欲睡”，这当儿，月光悄悄地进了门。“入户”二字，把月光拟人化。月光似乎懂得这位迁客的孤独寂寞，主动来与他做伴。 　　“欣然起行”：是作者的反应；写出他睡意顿消，披衣而起，见月光如见久违的知心朋友，欣然相迎。一个被朝廷所贬谪的“罪人”，我们可以想见他这时交游断绝、门庭冷落的境况；只有月光毫无势利之情，在寂寥的寒夜里，依然来拜访他。四字写出了作者的喜悦和兴奋。 　　“念无与为乐者，遂至承天寺寻张怀民。”：作者与张怀民同是被贬之人，于是作者便想到了张怀民。 　　“怀民亦未寝，相与步于中庭。”：作者与张怀民心有灵犀，及其友情之深厚。 　　“何夜无月？何处无竹柏？但少闲人如吾两人者耳。”：一是感慨世人忙于名利而辜负了良辰美景，二是表现了作者安闲自适的心境，三是透露出自己不能为朝廷尽忠的抱怨 　　“庭下如积水空明，水中藻荇交横，盖竹柏影也。”：“庭下如积水空明，水中藻、荇交横，盖竹柏影也”。此句运用了比喻的修辞，将澄澈的月光比成积水，用交错相生的水草比喻竹柏的影子，虚实相生，相映成趣，化无形为有形。“积水空明”写出了月光的皎洁，空灵，“藻荇交横”写出了竹柏倒影的清丽淡雅。前者给人以一池春水的静谧之感，后者则具有水草摇曳的动态之美，整个意境静中有动，动中愈见其静，一正写，一侧写，从而创造出一个冰清玉洁的透明世界，也折射出作者光明磊落、胸无尘俗的襟怀。作者以高度凝练的笔墨，点染出一个空明澄澈、疏影摇曳、似真似幻的美妙境界。\n\n写作技巧 　　1.比喻传神：庭下如积水空明，水中藻荇交横，盖竹柏影也。 　　2.正面/侧面描写相结合：庭下如积水空明，水中藻荇交横，盖竹柏影也。 　　3.抓住了瞬间的感受：何夜无月？何处无竹柏？但少闲人如吾两人者耳。 　　4.虚实（动、静）结合：把竹柏（实、静）比作了水中的荇藻（虚、动）。\n\n文章写作特点 　　1.信笔疏意，随物赋形。 　　2.描写月色，如诗如画。 　　3.语言凝练含蓄，饶有余味。\n\n作者心境 　　虽然自己有欣赏美景的乐趣，但是并不得意。将自己寄情于山水之间，有失意的自我排解。 　　——本文体现二人友情的句子：念无与为乐者，遂至承天寺寻张怀民（唯张怀民可与同乐）；怀民亦未寝（两人遭遇相同，心境也相同）； 相与步于中庭（两人亲密无间）； 但少闲人如吾两人者耳（两人遭遇相同，心境相同，志趣也相同，是真正志同道合的朋友）。 　　“水中藻、荇交横”说明了当时月色之浓、清、亮。 　　闲人：苏轼这时被贬为黄州团练副使，有名无实，所以自称“闲人”。 　　写月突出其明，写境突出其静，写影突出其形，写人突出其闲，写情突出其空。', poem_tags = '初中文言文,纪游,写景,感叹,人生' WHERE poem_title = '记承天寺夜游 / 记承天夜游' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '草屋的茅檐又低又小，溪边长满了碧绿的小草。\n含有醉意的吴地方言，听起来温柔又美好，那满头白发的老人是谁家的呀？\n大儿子在溪东边的豆田锄草，二儿子正忙于编织鸡笼。\n最令人喜爱的是小儿子，他正横卧在溪头草丛，剥着刚摘下的莲蓬。', poem_notes = '清平乐（yuè）：词牌名。村居：题目\n茅檐：茅屋的屋檐。\n吴音：吴地的方言。作者当时住在信州（今上饶），这一带的方言为吴音。相媚好：指相互逗趣，取乐。\n翁媪（ǎo）：老翁、老妇。\n锄豆：锄掉豆田里的草。\n织：编织，指编织鸡笼。\n亡（wú）赖：这里指小孩顽皮、淘气。亡，通“无”。\n卧：趴。', poem_appreciation = '辛弃疾词中有不少作品是描写农村生活的佳作，其中，有风景画，也有农村的风俗画。这首《清平乐·村居》就是一幅栩栩如生、有声有色的农村风俗画。\n\n　　刘熙载说 ，“词要清新”，“澹语要有味”（《艺概·词曲概》）。作者的此作正具有“澹语清新”、诗情画意的特点。它表现在描写手法、结构和构思三个方面。\n\n　　在描写手法上，这首词，没有一句使用浓笔艳墨，只是用纯粹的白描手法，描绘了农村一个五口之家的环境和生活画面。作者能够把这家老小的不同面貌和情态，描写得维妙维肖，活灵活现，具有浓厚的生活气息，如若不是大手笔，是难能达到此等艺术意境的。\n\n　　上阕头两句，写这个五口之家，有一所矮小的茅草房屋、紧靠着房屋有一条流水淙淙、清澈照人的小溪。溪边长满了碧绿的青草。在这里，作者只用了淡淡的两笔，就把由茅屋、小溪、青草组成的清新秀丽的环境勾画出来了。不难看出，这两句在全首词中，还兼有点明环境和地点的使命。\n\n　　三四两句，描写了一对满头白发的翁媪，亲热地坐在一起 ，一边喝酒，一边聊天的优闲自得的画面，这几句尽管写得很平淡，但是，它却把一对白发翁媪，乘着酒意，彼此“媚好 ”，亲密无间，那种和协、温暖、惬意的老年夫妻的幸福生活，形象地再现出来了。\n\n　　这就是无奇之中的奇妙之笔。当然，这里并不仅仅是限于这对翁媪的生活，它概括了农村普遍的老年夫妻生活乐趣，是有一定的典型意义。“吴音”，指吴地的地方话。作者写这首词时，是在江西上饶，此地，春秋时代属于吴国。“媪”，是对老年妇女的代称。\n\n　　下阕四句，采用白描手法，直书其事，和盘托出三个儿子的不同形象。大儿子是家中的主要劳力，担负着溪东豆地里锄草的重担。二儿子年纪尚小，只能做占铺助劳动，所以在家里编织鸡笼。三儿子不懂世事，只知任意地调皮玩耍，看他躺卧在溪边剥莲蓬吃的神态，即可知晓。这几句虽然极为通俗易懂，但却刻画出鲜明的人物形象，描绘出耐人寻味的意境。尤其是小儿无拘无束地剥莲蓬吃的那种天真活泼的神情状貌，饶有情趣，栩栩如生，可谓是神来之笔，古今一绝！“无赖”，谓顽皮，是爱称，并无贬意 。“卧”字的用得极妙它把小儿天真、活泼、顽皮的劲儿，和盘托出，跃然纸上。所谓一字千金，即是说使用一字，恰到好处，比坐、躺、趴等用的更妙，就更能给全句或全词增辉。这里的“卧”字正是如此。\n\n　　在艺术结构上，全词紧紧围绕着小溪，布置画面，展开人物的活动。从词的意境来看，茅檐是靠近小溪的。另外 ，“溪上青青草”、“大儿锄豆溪东”、“最喜小儿无赖，溪头卧剥莲蓬 ”四句，连用了三个“溪”字，使得画面的布局紧凑。所以，“溪”字的使用，在全词结构上起着关键作用。\n\n　　在写景方面，茅檐、小溪、青草，这本来是农村中司空见惯的东西，然而作者把它们组合在一个画面里，却显得格外清新优美。在写人方面，翁媪饮酒聊天，大儿锄草，中儿编鸡笼，小儿卧剥莲蓬。通过这样简单的情节安排，就把一片生机勃勃和平宁静、朴素安适的农村生活，真实地反映出来了。给人一种诗情画意 ，清新悦目的感觉，这样的构思巧妙、新颖，色彩协和、鲜明，给人留下了难忘的印象。\n\n　　从作者对农村清新秀丽 、朴素雅静的环境描写，对翁媪及其三子形象的刻画，表现出词人喜爱农村和平宁静的生活。\n\n　　这首词 ，是作者晚年遭受议和派排斥和打击，志不得伸，归隐上饶地区闲居农村时写的，词作描写农村和平宁静、朴素安适的生活，并不能说是作者对现实的粉饰。从作者一生始终关心宋朝恢复大业来看，他向往这样的农村生活 ，因而会更加激起他抗击金兵、收复中原、统一祖国的爱国热忱。就当时的情况来说，在远离抗金前线的村庄，这种和平宁静的生活，也是存在的，此作并非是作者主观想象的产物，而是现实生活的反映。', poem_tags = '宋词三百首,小学古诗,初中古诗,向往,乡村,生活' WHERE poem_title = '清平乐·村居' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '荷已残，香已消，冷滑如玉的竹席，透出深深的凉秋。轻轻的脱下罗绸外裳，一个人独自躺上眠床。仰头凝望远天，那白云舒卷处，谁会将锦书寄来？正是雁群排成“人”字，一行行南归时候。月光皎洁浸人，洒满这西边独倚的亭楼。\n花，自顾地飘零，水，自顾地漂流。一种离别的相思，牵动起两处的闲愁。啊，无法排除的是——这相思，这离愁，刚从微蹙的眉间消失，又隐隐缠绕上了心头。', poem_notes = '红藕：红色的荷花。玉簟（diàn）：光滑似玉的精美竹席。\n裳（cháng）：古人穿的下衣，也泛指衣服。\n兰舟：此处为船的雅称。\n锦书：前秦苏惠曾织锦作《璇玑图诗》，寄其夫窦滔，计八百四十字，纵横反复，皆可诵读，文词凄婉。后人因称妻寄夫为锦字，或称锦书；亦泛为书信的美称。\n雁字：群雁飞时常排成“一”字或“人”字，诗文中因以雁字称群飞的大雁。\n月满西楼：意思是鸿雁飞回之时，西楼洒满了月光。\n一种相思，两处闲愁：意思是彼此都在思念对方，可又不能互相倾诉，只好各在一方独自愁闷着。\n才下眉头，却上心头：意思是，眉上愁云刚消，心里又愁了起来。', poem_appreciation = '这是一首倾诉相思、别愁之苦的词。这首词在黄昇《花庵词选》中题作“别愁”，是李清照写给新婚未久即离家外出的丈夫赵明诚的，她诉说了自己独居生活的孤独寂寞，急切思念丈夫早日归来的心情。伊世珍《琅嬛记》说：“易安结褵（婚）未久，明诚即负笈远游。易安殊不忍别，觅锦帕书《一剪梅》词以送之。”作者在词中以女性特有的敏感捕捉稍纵即逝的真切感受，将抽象而不易捉摸的思想感情，以素淡的语言表现出具体可感、为人理解、耐人寻味的东西。\n\n词的上阕首句“红藕香残玉簟秋”写荷花凋谢、竹席浸凉的秋天，空灵蕴藉。“红藕”，即粉红荷花。“玉簟”，是精美的竹席。这一句涵义极其丰富，它不仅点明了萧疏秋意的时节，而且渲染了环境气氛，对作者的孤独闲愁起了衬托作用。表面上写出荷花残，竹席凉这些寻常事情，实质上暗含青春易逝，红颜易老，“人去席冷”之意境。梁绍壬《两般秋雨庵随笔》赞美此句“有吞梅嚼雪，不食人间烟火气象”。“轻解罗裳，独上兰舟”是写其白天泛舟水上之事：词人解开绫罗裙，换着便装，独自划着小船去游玩。“轻解”与“独上”，栩栩如生地表现出她的神态、举动。“轻”，写手脚动作的轻捷灵敏，表现出生怕惊动别人，小心而又有几分害羞的少妇心情。正因为是“轻”，所以谁也不知道，连侍女也没让跟上。“独”字就是回应上句的“轻”字，点明了下阕“愁”字的症结。“独上兰舟”，正是她想借泛舟以消愁，并非闲情逸致的游玩。昔日也许双双泛舟，而今独自击楫，恩爱情深、朝夕相伴的的丈夫久盼不归，怎不教她愁情满怀。“云中谁寄锦书来？”惦念丈夫，望眼欲穿，真是一封“家书抵万金”。“雁字回时，月满西楼”是她思夫的迫切心情，突然自现的外在表现。作者借助于鸿雁传书的传说，画面清晰，形象鲜明，它渲染了一个月光照满楼头的美好夜景，然而在喜悦的背后，蕴藏着相思的泪水。“月满西楼”写月夜思妇凭栏望眺。月已西斜，足见她站立楼头已久，这就表明了她思夫之情更深，愁更极。盼望音讯的她仰头叹望，竟产生了雁足回书的遐想。难怪她不顾夜露浸凉，呆呆伫立凝视，直到月满西楼而不知觉。\n\n下阕“花自飘零水自流”，言眼前的落花流水可不管你的心情如何，自是飘零东流。其实，这一句含有两个意思：“花自飘零”，是说她的青春象花那样空自凋残；“水自流”，是说她丈夫远行了，象悠悠江水空自流。只要我们仔细玩味，就不难发觉，李清照既为自己的红颜易老而感慨，更为丈夫不能和自己共享青春而让它白白地消逝而伤怀。这种复杂而微妙的感情，正是从两个“自”字中表现出来的。这就是她之所以感叹“花自飘零水自流”的关键所在，也是她俩真挚爱情的具体表现。当然，它所喻的人世的一切诸如离别，均给人以无可奈何之感。“一种相思，两处闲愁。”由己及人，互相思念，这是有情人的心灵感应，相互爱慕，温存备致，她想到丈夫一定也同样因离别而苦恼着。这种独特的构思体现了李清照与赵明诚夫妇二人心心相印、情笃爱深，相思却又不能相见的无奈思绪流诸笔端。“此情无计可消除，才下眉头，却上心头。”这种相思之情笼罩心头，无法排遣，蹙着的愁眉方才舒展，而思绪又涌上心头，其内心的绵绵愁苦挥之不去，遣之不走。“才下”、“却上”两个词用得很好，把真挚的感情由外露转向内向，迅疾的情绪变化打破了故作平静的心态，把相思之苦表现得极其真实形象，表达了绵绵无尽的相思与愁情，独守空房的孤独与寂寞充满字里行间，感人至深。这和李煜《乌夜啼》“剪不断，理还乱，是离愁，别是一般滋味在心头”，有异曲同工之妙境，成为千古绝唱。\n\n总之，《一剪梅》笔调清新，风格细腻，给景物以情感，景语即情语，景物体现了她的心情，显示着她的形象特征。词人移情入景，借景抒情，情景交融，耐人寻味。', poem_tags = '宋词三百首,宋词精选,婉约,思念,闺怨,写景' WHERE poem_title = '一剪梅·红藕香残玉簟秋' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '旅途在青山外，在碧绿的江水前行舟。\n潮水涨满，两岸之间水面宽阔，顺风行船恰好把帆儿高悬。\n夜幕还没有褪尽，旭日已在江上冉冉升起，还在旧年时分，江南已有了春天的气息。\n寄出去的家信不知何时才能到达，希望北归的大雁捎到洛阳去。\n\n英文\nIn Castle Peak Road outside, in front of the Green River.\nThe tide flat, broad between the two sides of the water, happened to hoist heavy.\nResidual night has not yet subsided, the sun rises from the sea, bye-bye is not behind the river has been revealed of spring.\nLetter to send out not knowing when to arrive, the geese are sent to Luoyang to hope that the North.', poem_notes = '次：旅途中暂时停宿，这里是停泊的意思。\n北固山：在今江苏镇江北，三面临长江。\n客路：旅途。\n潮平两岸阔：潮水涨满时，两岸之间水面宽阔。\n风正：顺风。\n悬：挂。\n海日：海上的旭日。\n残夜：夜将尽之时。\n江春：江南的春天。\n归雁：北归的大雁。大雁每年秋天飞往南方，春天飞往北方。古代有用大雁传递书信的传说。\n青山：指北固山。\n乡书：家信。', poem_appreciation = '从海日东升，春意萌动，放舟于绿水之上，联想起“雁足传书”的故事，表达了淡淡的乡思愁绪。全诗和谐而优美。 此诗载于《全唐诗》卷一百一十五。下面是中华诗词学会、中国唐代文学学会副会长霍松林先生对此诗的赏析。\n\n　　这首《次北固山下》唐人殷璠选入《河岳英灵集》时题为《江南意》，但有不少异文：“南国多新意，东行伺早天。潮平两岸失，风正数帆悬。海日生残夜，江春入旧年。从来观气象，惟向此中偏。”\n\n　　王湾是洛阳人，生中，“尝往来吴楚间”。“北固山”，在今江苏镇江市以北，三面临江。上引《江南意》中首二句为“南国多新意，东行伺早天。”其“东行”，当是经镇江到江南一带去。诗人一路行来，当舟次北固山下的时候，潮平岸阔，残夜归雁，触发了心中的情思，吟成了这一千古名篇。\n\n　　诗以对偶句发端，既工丽，又跳脱。“客路”，指作者要去的路。“青山”点题中“北固山”。作者乘舟，正朝着展现在眼前的“绿水”前进，驶向“青山”，驶向“青山”之外遥远的“客路”。 这一联先写“客路”而后写“行舟”，其人在江南、神驰故里的飘泊羁旅之情，已流露于字里行间，与末联的“乡书”、“归雁”，遥相照应。\n\n　　次联的“潮平两岸阔”，“阔”，是表现“潮平”的结果。春潮涌涨，江水浩渺，放眼望去，江面似乎与岸平了，船上人的视野也因之开阔。这一句，写得恢弘阔大，下一句“风正一帆悬”，便愈见精采。“悬”是端端直直地高挂着的样子。诗人不用“风顺”而用“风正”，是因为光“风顺”还不足以保证“一帆悬”。风虽顺，却很猛，那帆就鼓成弧形了。只有既是顺风，又是和风，帆才能够“悬”。那个“正”字，兼包“顺”与“和”的内容。这一句写小景已相当传神。但还不仅如此，如王夫之所指出，这句诗的妙处，还在于它“以小景传大景之神”《姜斋诗话》卷上。可以设想，如果在曲曲折折的小河里行船，老要转弯子，这样的小景是难得出现的。如果在三峡行船，即使风顺而风和，却依然波翻浪涌，这样的小景也是难得出现的。诗句妙在通过“风正一帆悬”这一小景，把平野开阔、大江直流、风平浪静等等的大景也表现出来了。\n\n　　读到第三联，就知道作者是于岁暮腊残，连夜行舟的。潮平而无浪，风顺而不猛，近看可见江水碧绿，远望可见两岸空阔。这显然是一个晴明的、处处透露着春天气息的夜晚，孤舟扬帆，缓行江上，不觉已到残夜。这第三联，就是表现江上行舟，即将天亮时的情景。\n\n　　这一联历来脍炙人口。“海日生残夜，江春入旧年”：当残夜还未消退之时，一轮红日已从海上升起；当旧年尚未逝去，江上已呈露春意。“日生残夜”、“春入旧年”，都表示时序的交替，而且是那样匆匆不可待，这怎不叫身在“客路”的诗人顿生思乡之情呢？这两句炼字炼句也极见功夫。作者从炼意着眼，把“日”与“春”作为新生的美好事物的象征，提到主语的位置而加以强调，并且用“生”字“入”字使之拟人化，赋予它们以人的意志和情思。妙在作者无意说理，却在描写景物、节令之中，蕴含着一种自然的理趣。海日生于残夜，将驱尽黑暗；江春，那江上景物所表现的“春意”，闯入旧年，将赶走严冬。不仅写景逼真，叙事确切，而且表现出具有普遍意义的生活真理，给人以乐观、积极、向上的艺术鼓舞力量。此句与“沉舟侧畔千帆过，病树前头万木春”有异曲同工之妙。\n\n　　海日东升，春意萌动，诗人放舟于绿水之上，继续向青山之外的客路驶去。这时候，一群北归的大雁正掠过晴空。雁儿正要经过洛阳的啊！诗人想起了“雁足传书”的故事，还是托雁捎个信吧：雁儿啊，烦劳你们飞过洛阳的时候，替我问候一下家里人。这两句紧承三联而来，遥应首联，全篇笼罩着一层淡淡的乡思愁绪。这首五律虽然以第三联驰誉当时，传诵后世，但并不是只有两个佳句而已；从整体看，也是相当和谐优美的。', poem_tags = '唐诗三百首,初中古诗,地点,思乡,哲理' WHERE poem_title = '次北固山下' AND poem_author = '王湾';
UPDATE edu_poem SET poem_translation = '剑门关外，喜讯忽传，官军收复冀北一带。高兴之余，泪满衣裳。\n回望妻子儿女，也已一扫愁云，随手卷起诗书，全家欣喜若狂。\n老夫想要纵酒高歌，结伴春光同回故乡。\n我的心魂早已高飞，就从巴峡穿过巫峡，再到襄阳直奔洛阳。', poem_notes = '闻：听说。官军：指唐朝军队。\n剑外：剑门关以南，这里指四川。蓟北：泛指唐代幽州、蓟州一带，今河北北部地区，是安史叛军的根据地。\n涕：眼泪。\n却看：回头看。妻子：妻子和孩子。愁何在：哪还有一点的忧伤？愁已无影无踪。\n漫卷(juǎn)诗书喜欲狂：胡乱地卷起。是说杜甫已经迫不及待地去整理行装准备回家乡去了。喜欲狂：高兴得简直要发狂。\n放歌：放声高歌。须：应当。纵酒：开怀痛饮。\n青春：指明丽的春天的景色。作伴：与妻儿一同。\n巫峡：长江三峡之一，因穿过巫山得名。\n便：就的意思。襄阳：今属湖北。洛阳：今属河南，古代城池。', poem_appreciation = '杜甫在这首诗下自注：“余田园在东京。”诗的主题是抒写忽闻叛乱已平的捷报，急于奔回老家的喜悦。“剑外忽传收蓟北”，起势迅猛，恰切地表现了捷报的突然。诗人多年飘泊“剑外”，备尝艰苦，想回故乡而不可能，就是由于“蓟北”未收，安史之乱未平。如今“忽传收蓟北”，惊喜的洪流，一下子冲开了郁积已久的情感闸门，令诗人心中涛翻浪涌。“初闻涕泪满衣裳”，“初闻”紧承“忽传”，“忽传”表现捷报来得太突然，“涕泪满衣裳”则以形传神，表现突然传来的捷报在“初闻”的一刹那所激发的感情波涛，这是喜极而悲、悲喜交集的真实表现。“蓟北”已收，战乱将息，乾坤疮痍、黎民疾苦，都将得到疗救，诗人颠沛流离、感时恨别的苦日子，总算熬过来了。然而痛定思痛，诗人回想八年来熬过的重重苦难，又不禁悲从中来，无法压抑。可是，这一场浩劫，终于像噩梦一般过去了，诗人可以返回故乡了，人们将开始新的生活，于是又转悲为喜，喜不自胜。这“初闻”捷报之时的心理变化、复杂感情，如果用散文的写法，必需很多笔墨，而诗人只用“涕泪满衣裳”五个字作形象的描绘，就足以概括这一切。\n\n　　颔联以转作承，落脚于“喜欲狂”，这是惊喜的更高峰。“却看妻子”、“漫卷诗书”，这是两个连续性的动作，带有一定的因果关系。当诗人悲喜交集，“涕泪满衣裳”之时，自然想到多年来同受苦难的妻子儿女。“却看”就是“回头看”。“回头看”这个动作极富意蕴，诗人似乎想向家人说些什么，但又不知从何说起。其实，无需说什么了，多年笼罩全家的愁云不知跑到哪儿去了，亲人们都不再是愁眉苦脸，而是笑逐颜开，喜气洋洋。亲人的喜反转来增加了诗人的喜，诗人再也无心伏案了，随手卷起诗书，大家同享胜利的欢乐。\n\n　　“白日放歌须纵酒，青春作伴好还乡”一联，就“喜欲狂”作进一步抒写。“白日”，指晴朗的日子，点出人已到了老年。老年人难得“放歌”，也不宜“纵酒”；如今既要“放歌”，还须“纵酒”，正是“喜欲狂”的具体表现。这句写“狂”态，下句则写“狂”想。“青春”指春天的景物，春天已经来临，在鸟语花香中与妻子儿女们“作伴”，正好“还乡”。诗人想到这里，自然就会“喜欲狂”了。\n\n　　尾联写诗人“青春作伴好还乡”的狂想，身在梓州，而弹指之间，心已回到故乡。诗人的惊喜达到高潮，全诗也至此结束。这一联，包涵四个地名。“巴峡”与“巫峡”，“襄阳”与“洛阳”，既各自对偶（句内对），又前后对偶，形成工整的地名对；而用“即从”、“便下”绾合，两句紧连，一气贯注，又是活泼流走的流水对。再加上“穿”、“向”的动态与两“峡”两“阳”的重复，文势、音调，迅急有如闪电，准确地表现了诗人想象的飞驰。“巴峡”、“巫峡”、“襄阳”、“洛阳”，这四个地方之间都有很漫长的距离，而一用“即从”、“穿”、“便下”、“向”贯串起来，就出现了“即从巴峡穿巫峡，便下襄阳向洛阳”的疾速飞驰的画面，一个接一个地从读者眼前一闪而过。这里需要指出的是：诗人既展示想象，又描绘实境。从“巴峡”到“巫峡”，峡险而窄，舟行如梭，所以用“穿”；出“巫峡”到“襄阳”，顺流急驶，所以用“下”；从“襄阳”到“洛阳”，已换陆路，所以用“向”，用字高度准确。\n\n　　全诗感情奔放，痛快淋漓地抒发了作者无比喜悦的心情。后代诗论家都极为推崇此诗，浦起龙赞其为杜甫“生平第一首快诗也”（《读杜心解》）。\n\n　　此诗除第一句叙事点题外，其余各句，都是抒发诗人忽闻胜利消息之后的惊喜之情。诗人的思想感情出自胸臆，奔涌直泻。仇兆鳌在《杜少陵集详注》中引王嗣奭的话说：“此诗句句有喜跃意，一气流注，而曲折尽情，绝无妆点，愈朴愈真，他人决不能道。”', poem_tags = '唐诗三百首,小学古诗,思归' WHERE poem_title = '闻官军收河南河北' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '太阳渐渐西沉，已衔着西山了，天边的晚霞也逐渐开始消散，只残留有几分黯淡的色彩，映照着远处安静的村庄是多么的孤寂，拖出那长长的影子。雾淡淡飘起，几只乌黑的乌鸦栖息在佝偻的老树上，远处的一只大雁飞掠而下，划过天际。山清水秀；霜白的小草、火红的枫叶、金黄的花朵，在风中一齐摇曳着，颜色几尽妖艳。', poem_notes = '天净沙：曲牌名。\n秋：题目。\n残霞：快消散的晚霞。\n寒鸦：天寒即将归林的乌鸦。\n飞鸿：天空中的鸿雁。\n飞鸿影下：雁影掠过。\n白草：枯萎而不凋谢的白草。\n黄花：菊花。\n红叶：枫叶。', poem_appreciation = '白朴这首小令《天净沙·秋》与马致远的《天净沙·秋思》，无论写法还是构成的意境都有相似之处。此曲题目虽为“秋”，并且写尽秋意，却找不着一个“秋”字。 此曲开篇先绘出了一幅秋日黄昏图，营造出一种宁静、寂寥的氛围，再以名词并列组合的形式，选取典型的秋天景物，由远及近，描绘出一幅色彩绚丽的秋景图。秋景也由先前的萧瑟、寂寥变为明朗、清丽了。\n\n　　这首小令，只五句二十八个字，篇幅虽短，却以神来之笔捅绘出了一幅绝妙的秋景图。前三句着力渲染出一派深秋凄凉之景。黄昏时：如血的残霞映照着一座孤零零的小村庄，夕阳淡淡的炊烟袅袅，几只归巢的寒鸦，静静的站立在老树枝头，忽然，一只哀鸣的孤鸿，在人边晚霞影里远远的飞翔，而后两句，作者却将笔锋一转，写到：青山静静、绿水悠悠，白草绵绵，红叶片片，黄花朵朵，在暮色中，这些明丽的色彩，为这萧杀的气氛平添了许多生机活力。一扫前人一悲到底的俗套。\n\n　　白朴在写秋景选词语辞精炼，其词并不是单纯的突出秋的悲凉。前二句的“孤村落日残霞，轻烟老树寒鸦”，共用了六个图景：“孤村”、“落日”、“残霞”、“轻烟”、“老树”、“寒鸦”，而其中任何一个图景，都代表着秋日秋景的萧瑟气氛。为了要使这种萧瑟气氛活泼起来，于是作者接下来选用了“一点飞鸿影下”作为上半段的结语。如此一来，原本萧瑟的画面转成了活跃，寂寞的秋景彷佛也展现了另一种鲜活的生气。最后为了加强作者心目中秋景是美丽而有韵味的形象，因此再以“青山绿水，白草红叶黄花”作为曲文的结束语。这两句用了“青”、“绿”、“白”、“红”、“黄”五种颜色，而且“白草红叶黄花”这三种颜色，是交杂在“青山绿水”二种颜色之中；“青山绿水”是广大的图景，“白草红叶黄花”是细微的图景，如此交杂相错，于是原本是寂寞萧瑟的秋景，突然变得五颜六色而多彩多姿。由此可见，白朴的散曲写作技巧的高明了。\n\n　　如果联系白朴不愿在元朝做官的态度，读者就不难理解同样的秋景会有如此巨大反差的原因。画面中的“一点飞鸿”，与李白的《送裴十八图南归嵩山》其一：“举手指飞鸿，此情难具论。同归无早晚，颍水有清原”中的“飞鸿”有着异曲同工之妙，都暗喻作者本人。白朴不愿在朝廷中谋职，却希望自己像一只展翅高飞的鸿雁，飞离那种萧瑟、冷清、没有生气的地方，寻找到自己感到满意，有生机的乐土，还表示了作者的人生得到了美好的转折。因此“影下”的这片“青山绿水、白草红叶黄花”之地，读者可以理解为是作者的归隐之地，是作者的心中之景。情调开朗平和，没有一点消极之感，表现了作者对隐居生活的热爱之情，应属于虚写。在这支曲子中，作者非常巧妙地、不露痕迹地把“心中之景”与当时真实的环境放在一起，产生强烈的对比效果，含蓄地流露出自己的爱恨之情。\n\n　　描绘秋景，历来是中国古代文人喜爱的一个题材，为表现它而不惜笔墨的诗人骚客代代有之，留下的作品更是多不胜举，但许多作品易于流入俗套。白朴却能根据自己的观察和体验，在作品中，层次分明的描写了秋天的自然景象，虽然，在开始时，有些许的萧瑟之意，然而后来以缤纷的色彩作结，终究是赏心悦目、的韵味无穷的。他用笔精深，作品风格独具，婉约清丽，意境新颖，可与被誉为“秋思之祖”的马志远的《天净沙·秋思》媲美。这首小令不仅不俗，还很是典雅。词、曲有雅、俗之别，一般来说，词尚妩媚、含蓄，而曲贵尖新、直率。白朴的这支小令却有词的意境。曲中虽无“断肠人在天涯”之类句子，抒情主人公却时隐时现，在烟霞朦胧之中，传达出一种“地老天荒”的寂静。', poem_tags = '小学古诗,秋天,写景' WHERE poem_title = '天净沙·秋' AND poem_author = '白朴';
UPDATE edu_poem SET poem_translation = '在灿烂的阳光照耀下，西湖水微波粼粼，波光艳丽，看起来很美；雨天时，在雨幕的笼罩下，西湖周围的群山迷迷茫茫，若有若无，也显得非常奇妙。\n若把西湖比作古美女西施，淡妆浓抹都是那么得十分适宜。', poem_notes = '湖：即杭州西湖。\n潋滟(liàn yàn) ：水面波光闪动的样子。\n方好：正是显得很美。\n空濛：细雨迷茫的样子。\n西子：西施，春秋时代越国有名的美女，原名施夷光，或称 先施 ，居古代四大美女（西施、王昭君、貂蝉、杨玉环）之首。家住浣纱溪村（在今浙江诸暨市）西，所以称为西施。\n相宜：也显得十分美丽。', poem_appreciation = '诗的上半首既写了西湖的水光山色，也写了西湖的晴姿雨态。“水光潋滟晴方好”描写西湖晴天的水光：在灿烂的阳光照耀下，西湖水波荡漾，波光闪闪，十分美丽。“山色空濛雨亦奇”描写雨天的山色：在雨幕笼罩下，西湖周围的群山，迷迷茫茫，若有若无，非常奇妙。从第一首诗可知，这一天诗人陪着客人在西湖游宴终日，早晨阳光明艳，后来转阴，入暮后下起雨来。而在善于领略自然并对西湖有深厚感情的诗人眼中，无论是水是山，或晴或雨，都是美好奇妙的。从“晴方好”“雨亦奇”这一赞评，可以想见在不同天气下的湖山胜景，也可想见诗人即景挥毫时的兴会及其洒脱的性格、开阔的胸怀。上半首写的景是交换、对应之景，情是广泛、豪宕之情，情景交融，句间情景相对，西湖之美概写无余，诗人苏轼之情表现无遗。\n\n　　下半首诗里，诗人没有紧承前两句，进一步运用他的写气图貌之笔来描绘湖山的晴光雨色，而是遗貌取神，只用一个既空灵又贴切的妙喻就传出了湖山的神韵。喻体和本体之间，除了从字面看，西湖与西子同有一个“西”字外，诗人的着眼点所在只是当前的西湖之美，在风神韵味上，与想象中的西施之美有其可意会而不可言传的相似之处。而正因西湖与西子都是其美在神，所以对西湖来说，晴也好，雨也好，对西子来说，淡妆也好，浓抹也好，都无改其美，而只能增添其美。对这个比喻，存在有两种相反的解说：一说认为诗人“是以晴天的西湖比淡妆的西子，以雨天的西湖比浓妆的西子”；一说认为诗人是“以晴天比浓妆，雨天比淡妆”。两说都各有所见，各有所据。但就才情横溢的诗人而言，这是妙手偶得的取神之喻，诗思偶到的神来之笔，只是一时心与景会，从西湖的美景联想到作为美的化身的西子，从西湖的“晴方好”“雨亦奇”，想象西子应也是“淡妆浓抹总相宜”，当其设喻之际、下笔之时，恐怕未必拘泥于晴与雨二者，何者指浓妆，何者指淡妆。欣赏这首诗时，如果一定要使浓妆、淡妆分属晴、雨，可能反而有损于比喻的完整性、诗思的空灵美。', poem_tags = '古诗三百首,小学古诗,西湖,写雨,写景,早教古诗100首' WHERE poem_title = '饮湖上初晴后雨二首·其二' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '荆溪潺湲流过白石粼粼显露，天气变得寒冷红叶落落稀稀。\n弯曲的山路上原本没有雨，但苍翠的山色却浓得仿佛就要润湿了人的衣裳一样。', poem_notes = '荆溪：本名长水，又称浐水、荆谷水，源出陕西蓝田县西南秦岭山中，北流至长安东北入灞水。参见《水经注·渭水》《长安志》卷一六。一作“溪清”。\n红叶：秋天，枫、槭、黄栌等树的叶子都变成红色，统称红叶。\n元：原，本来。\n“空翠”句：形容山中翠色浓重，似欲流出，使人有湿衣之感。空翠：指山间青色的潮湿的雾气。', poem_appreciation = '这首小诗以诗人山行时所见所感，描绘了初冬时节的山中景色。\n\n　　首句写山中溪水。荆溪，本名长水，又称浐水，源出陕西蓝田县西南秦岭山中，北流至长安东北入灞水。这里写的大概是穿行在山中的上游一段。山路往往傍着溪流，山行时很容易首先注意到蜿蜒曲折、似乎与人作伴的清溪。天寒水浅，山溪变成涓涓细流，露出磷磷白石，显得特别清浅可爱。由于抓住了冬寒时山溪的主要特征，读者不但可以想见它清澄莹澈的颜色，蜿蜒穿行的形状，甚至仿佛可以听到它潺潺流淌的声音。\n\n　　次句写山中红叶。绚烂的霜叶红树，本是秋山的特点。入冬天寒，红叶变得稀少了；这原是不大引人注目的景色。但对王维这样一位对大自然的色彩有特殊敏感的诗人兼画家来说，在一片浓翠的山色背景上（这从下两句可以看出），这里那里点缀着的几片红叶，有时反倒更为显眼。它们或许会引起诗人对刚刚逝去的绚烂秋色的遐想呢。所以，这里的“红叶稀”，并不给人以萧瑟、凋零之感，而是引起对美好事物的珍重和流连。\n\n　　如果说前两句所描绘的是山中景色的某一两个局部，那么后两句所展示的却是它的全貌。尽管冬令天寒，但整个秦岭山中，仍是苍松翠柏，蓊郁青葱，山路就穿行在无边的浓翠之中。苍翠的山色本身是空明的，不像有形的物体那样可以触摸得到，所以说“空翠”。“空翠”自然不会“湿衣”，但它是那样的浓，浓得几乎可以溢出翠色的水分，浓得几乎使整个空气里都充满了翠色的分子，人行空翠之中，就像被笼罩在一片翠雾之中，整个身心都受到它的浸染、滋润，而微微感觉到一种细雨湿衣似的凉意，所以尽管“山路元无雨”，却自然感到“空翠湿人衣”了。这是视觉、触觉、感觉的复杂作用所产生的一种似幻似真的感受，一种心灵上的快感。“空”字和“湿”字的矛盾，也就在这种心灵上的快感中统一起来了。\n\n　　张旭的《山中留客》说：“纵使晴明无雨色，入云深处亦沾衣。”“沾衣”是实写，展示了云封雾锁的深山另一种美的境界；王维这首《山中》的“湿衣”却是幻觉和错觉，抒写了浓翠的山色给人的诗意感受。同样写山中景物，同样写到了沾衣，却同工异曲，各臻其妙。真正的艺术是永远不会重复的。\n\n　　这幅由白石磷磷的小溪、鲜艳的红叶和无边的浓翠所组成的山中冬景，色泽斑斓鲜明，富于诗情画意，毫无萧瑟枯寂的情调。和作者某些专写静谧境界而不免带有清冷虚无色彩的小诗比较，这一首所流露的感情与美学趣味都似乎要更健康一些。', poem_tags = '秋天,纪行,写景' WHERE poem_title = '山中' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '酒筵上甘醇的葡萄美酒盛满在精美的夜光杯之中，歌伎们弹奏起急促欢快的琵琶声助兴催饮，想到即将跨马奔赴沙场杀敌报国，战士们个个豪情满怀。\n今日一定要一醉方休，即使醉倒在战场上又何妨？此次出征为国效力，本来就打算马革裹尸，没有准备活着回来。', poem_notes = '凉州词：唐乐府名，属《近代曲辞》，是《凉州曲》的唱词，盛唐时流行的一种曲调名。凉州词：王翰写有《凉州词》两首，慷慨悲壮，广为流传。而这首《凉州词》被明代王世贞推为唐代七绝的压卷之作。\n夜光杯：用白玉制成的酒杯，光可照明，这里指华贵而精美的酒杯。据《海内十洲记》所载，为周穆王时西胡所献之宝。\n欲：将要。\n琵琶：这里指作战时用来发出号角的声音时用的。\n催：催人出征；也有人解作鸣奏助兴。\n沙场：平坦空旷的沙地，古时多指战场。\n君：你。\n征战：打仗。', poem_appreciation = '七言绝句《凉州曲》：“葡萄美酒夜光杯，欲饮琵琶马上催，醉卧沙场君莫笑，古来征战几人回。”作者王翰，字子羽，唐时并州晋阳人。对于此诗，《唐诗三百首》编者“蘅塘退士”孙洙的批语是：“作旷达语，倍觉悲痛。”孙洙不愧知音之士，八个字批语，准确道出了此诗意蕴。\n\n　　这首诗不仅意蕴深远，边塞风光也如在眼前，真是诗中有画，画中有诗。在音乐高度发达的李唐王朝，不仅诗中有画，画中有诗，而且诗中有乐，乐中有诗。\n\n　　如果熟悉唐朝音乐，就会明白，“欲饮琵琶马上催”，是指“琵琶”、“马上”两种不同乐调。诗中“马上”，是“马上乐”之略。所谓“马上乐”，是“鼓角横吹”的军乐。追溯历史，融合了北狄、西域音乐的“鼓角横吹”始于汉代。史称：“张骞入西域，传其法于西京，唯得《摩诃兜勒》一曲。李延年因之更造新声二十八解，乘舆以为武乐。”\n\n　　这种“鼓角横吹”的“武乐”（即军乐），在殿庭之上，称作“横吹”；于军旅行中，则称“骑吹”。后世因“骑吹”是在马上演奏，亦称“马上乐”。如西晋傅玄《琵琶赋序》即有“作马上之乐”的说法。《旧唐书·音乐志》也说：“北狄乐，其可知者鲜卑、吐谷浑、部落稽三国，皆马上乐也。鼓吹本军旅之音，马上奏之。故自汉以来，北狄乐总归鼓吹署。”\n\n　　魏晋隋唐，“马上乐”已成为融会北狄、西域音乐而形成之“鼓角横吹”军乐的专有名词。\n\n　　明白了“马上”二字典故，我们可以知晓：《凉州曲》中描写的乐调，除了用“琵琶”一类乐器演奏的马下俗乐以外，还有“马上”军乐，二者形成强烈对比。所谓“欲饮琵琶马上催”是说：边塞将士正欲欣赏琵琶一类乐器奏出的悠扬乐调，以就痛饮，突然远处传来金鼓钲钲、号角齐鸣的马上军乐，这马上军乐，使他们又回到即将出征的现实之中。\n\n　　《凉州曲》不仅是“诗中有乐”的佳作，而且是“乐中有诗”的绝唱。诗中乐调的强烈对比，自有一番深意。如于音乐不甚了了，很难领会其中滋味。\n\n　　根据以上分析，可以把《凉州曲》这首意蕴深邃的古诗，译为如下白话：\n\n　　葡萄美酒，直向夜光玉杯里倾来， 　　琵琶悠曲，助我们痛饮开怀。 　　忽听得，马上乐已高奏催征， 　　将士们，要喝酒的还不赶快。 　　醇浆急饮，好一阵头晕脚歪， 　　诸君止笑，即令醉倒，又何足怪？ 　　不见我足下这千古沙场， 　　早成了战尸狼藉的所在。', poem_tags = '唐诗三百首,豪放,边塞,战争,宴饮,早教古诗100首' WHERE poem_title = '凉州词二首·其一' AND poem_author = '王翰';
UPDATE edu_poem SET poem_translation = '李白坐上小船刚刚要离开，忽然听到岸上传来告别的歌声。\n即使桃花潭水有一千尺那么深，也不及汪伦送别我的一片情深。', poem_notes = '踏歌：民间的一种唱歌形式，一边唱歌，一边用脚踏地打拍子，可以边走边唱。\n桃花潭：在今安徽泾县西南一百里。《一统志》谓其深不可测。\n深千尺：诗人用潭水深千尺比喻汪伦与他的友情，运用了夸张的手法（潭深千尺不是实有其事）写深情厚谊，十分动人。\n不及：不如。\n汪伦：李白的朋友。李白游泾（jīng）县（在今安徽省）桃花潭时，附近贾村的汪伦经常用自己酿的美酒款待李白，两人便由此结下深厚的友谊。历代出版的《李白集》、《唐诗三百首》、《全唐诗》注解，都认定汪伦是李白游历泾县时遇到的一个普通村民，这个观点一直延续至今，今人安徽学者汪光泽和李子龙先后研读了泾县《汪氏宗谱》、《汪渐公谱》、《汪氏续修支谱》，确知“汪伦又名凤林，为唐时知名士”，与李白、王维等人关系很好，经常以诗文往来赠答。开元天宝年间，汪伦为泾县令，李白“往候之，款洽不忍别”（详见《李白学刊》第二辑李子龙《关于汪伦其人》）。按此诗或为汪伦已闲居桃花潭时，李白来访所作。李白于公元754年（天宝十三载）自广陵、金陵至宣城，则此诗当不早于此前。', poem_appreciation = '中国诗的传统主张含蓄蕴藉。宋代诗论家严羽提出作诗四忌：“语忌直，意忌浅。脉忌露，味忌短。”清人施补华也说诗“忌直贵曲”。然而，李白《赠汪伦》的表现特点是：坦率，直露，绝少含蓄。其“语直”，其“脉露”，而“意”不浅，味更浓。古人写诗，一般忌讳在诗中直呼姓名，以为无味。而《赠汪伦》从诗人直呼自己的姓名开始，又以称呼对方的名字作结，反而显得真率，亲切而洒脱，很有情味。\n\n　　诗的前半是叙事：先写要离去者，继写送行者，展示一幅离别的画面。起句“乘舟”表明是循水道。“将欲行”表明是在轻舟待发之时。这句使读者仿佛见到李白在正要离岸的小船上向人们告别的情景。\n\n　　“忽闻岸上踏歌声”，接下来就写送行者。次句却不像首句那样直叙，而用了曲笔，只说听见歌声。一群村人踏地为节拍，边走边唱前来送行了。这似出乎李白的意料，所以说“忽闻”而不用“遥闻”。这句诗虽说得比较含蓄，只闻其声，不见其人，但人已呼之欲出。汪伦的到来，确实是不期而至的。人未到而声先闻。这样的送别，侧面表现出李白和汪伦这两位朋友同是不拘俗礼、快乐自由的人。\n\n　　诗的后半是抒情。第三句遥接起句，进一步说明放船地点在桃花潭。“深千尺”既描绘了潭的特点，又为结句预伏一笔。桃花潭水是那样地深湛，更触动了离人的情怀，难忘汪伦的深情厚意，水深情深自然地联系起来。结句迸出“不及汪伦送我情”，以比物手法形象性地表达了真挚纯洁的深情。潭水已“深千尺”，那么汪伦送李白的情谊必定更深，此句耐人寻味。这里妙就妙在“不及”二字，好就好在不用比喻而采用比物手法，变无形的情谊为生动的形象，空灵而有余味，自然而又情真。诗人很感动，所以用“桃花潭水深千尺，不及汪伦送我情”两行诗来极力赞美汪伦对诗人的敬佩和喜爱，也表达了李白对汪伦的深厚情谊。', poem_tags = '小学古诗,写水,离别,友情,送别,早教古诗100首' WHERE poem_title = '赠汪伦' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '与意中人相处应当总像刚刚相识的时候，是那样地甜蜜，那样地温馨，那样地深情和快乐。但你我本应当相亲相爱，却为何成了今日的相离相弃？\n如今轻易地变了心，你却反而说情人间就是容易变心的。\n我与你就像唐明皇与杨玉环那样，在长生殿起过生死不相离的誓言，却又最终作决绝之别，即使如此，也不生怨。\n但你又怎比得上当年的唐明皇呢，他总还是与杨玉环有过比翼鸟、连理枝的誓愿。', poem_notes = '柬：给……信札。\n“何事”句：用汉朝班婕妤被弃的典故。班婕妤为汉成帝妃，被赵飞燕谗害，退居冷宫，后有诗《怨歌行》，以秋扇闲置为喻抒发被弃之怨情。南北朝梁刘孝绰《班婕妤怨》诗又点明“妾身似秋扇”，后遂以秋扇见捐喻女子被弃。这里是说本应当相亲相爱，但却成了相离相弃。\n故人：指情人。却道故人心易变（出自娱园本），一作“却道故心人易变”。\n“骊山”二句：用唐明皇与杨玉环的爱情典故。《太真外传》载，唐明皇与杨玉环曾于七月七日夜，在骊山华清宫长生殿里盟誓，愿世世为夫妻。白居易《长恨歌》：“在天愿作比翼鸟，在地愿作连理枝。”对此作了生动的描写。后安史乱起，明皇入蜀，于马嵬坡赐死杨玉环。杨死前云：“妾诚负国恩，死无恨矣。”又，明皇此后于途中闻雨声、铃声而悲伤，遂作《雨霖铃》曲以寄哀思。这里借用此典说即使是最后作决绝之别，也不生怨。\n“何如”二句：化用唐李商隐《马嵬》诗中“如何四纪为天子，不及卢家有莫愁”之句意。薄幸：薄情。锦衣郎：指唐明皇。', poem_appreciation = '词题说这是一首拟古之作，其所拟之《决绝词》本是古诗中的一种，是以女子的口吻控诉男子的薄情，从而表态与之决绝。如古辞《白头吟》、唐元稹《古决绝词三首》等。纳兰性德的这首拟作是借用汉唐典故而抒发“闺怨”之情。\n\n　　用“决绝”这个标题，很可能就是写与初恋情人的绝交这样一个场景的。这首词确实也是模拟被抛弃的女性的口吻来写的。第一句“人生若只如初见”是整首词里最平淡又是感情最强烈的一句，一段感情，如果在人的心里分量足够重的话，那么无论他以后经历了哪些变故，初见的一刹那，永远是清晰难以忘怀的。而这个初见，词情一下子就拽回到初恋的美好记忆中去了。\n\n　　“何事秋风悲画扇”一句用汉朝班婕妤被弃的典故。扇子是夏天用来趋走炎热，到了秋天就没人理睬了，古典诗词多用扇子的来比喻被冷落的女性。这里是说本应当相亲相爱，但却成了相离相弃。又将词情从美好的回忆一下子拽到了残酷的现实当中。\n\n　　“等闲变却故人心，却道故人心易变”二句：因为此词是模拟女性的口吻写的，所以从这两句写出了主人公深深地自责与悔恨。纳兰不是一个负心汉，只是当时十多岁的少年还没主宰自己的命运。其实像李隆基这样的大唐皇帝都保不住心爱的恋人，更何况是纳兰。\n\n　　“骊山语罢清宵半，泪雨零铃终不怨”二句用唐明皇与杨玉环的爱情典故。七夕的时候，唐杨二人在华清宫里山盟海誓。山盟海誓言犹在，马嵬坡事变一爆发，杨贵妃就成了政治斗争的牺牲品。据说后来唐明皇从四川回长安的路上，在栈道上听到雨中的铃声，又勾起了他对杨贵妃的思恋，就写了著名的曲子《雨霖铃》。这里借用此典说即使是最后作决绝之别，也不生怨。\n\n　　“何如薄幸锦衣郎，比翼连枝当日愿” 二句化用唐李商隐《马嵬》诗句，承接前二句句意，从另一面说明主人公情感之坚贞。\n\n　　全词以一个女子的口吻，抒写了被丈夫抛弃的幽怨之情。词情哀怨凄婉，屈曲缠绵。“秋风悲画扇”即是悲叹自己遭弃的命运，“骊山”之语暗指原来浓情蜜意的时刻，“夜雨霖铃”写像唐玄宗和杨贵妃那样的亲密爱人也最终肠断马嵬坡，“比翼连枝”出自《长恨歌》诗句，写曾经的爱情誓言已成为遥远的过去。而这“闺怨”的背后，似乎更有着深层的痛楚，“闺怨”只是一种假托。故有人认为此篇别有隐情，词人是用男女间的爱情为喻，说明与朋友也应该始终如一，生死不渝。', poem_tags = '闺怨,悲叹,命运,分手' WHERE poem_title = '木兰花·拟古决绝词柬友' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '园中的葵菜都郁郁葱葱，晶莹的朝露阳光下飞升。\n春天把希望洒满了大地，万物都呈现出一派繁荣。\n常恐那肃杀的秋天来到，树叶儿黄落百草也凋零。\n百川奔腾着东流到大海，何时才能重新返回西境？\n少年人如果不及时努力，到老来只能是悔恨一生。', poem_notes = '长歌行：汉乐府曲题。这首诗选自《乐府诗集》卷三十，属相和歌辞中的平调曲。\n葵：“葵”作为蔬菜名，指中国古代重要蔬菜之一。《诗经·豳风·七月》：“七月亨葵及菽。”李时珍《本草纲目》说“葵菜古人种为常食，今之种者颇鲜。有紫茎、白茎二种，以白茎为胜。大叶小花，花紫黄色，其最小者名鸭脚葵。其实大如指顶，皮薄而扁，实内子轻虚如榆荚仁。”此诗“青青园中葵”即指此。\n朝露：清晨的露水。晞：天亮，引申为阳光照耀。\n”阳春“句：阳是温和。阳春是露水和阳光都充足的时候，露水和阳光都是植物所需要的，都是大自然的恩惠，即所谓的”德泽“。 布：布施，给予。 德泽：恩惠。\n秋节：秋季。\n焜黄：形容草木凋落枯黄的样子。 华（huā）：同“花”。 衰：一说读“cuī”，因为古时候没有“shuāi”这个音；一说读shuāi，根据语文出版社出版的《古代汉语》，除了普通话的规范发音之外，任何其他的朗读法都是不可取的。\n百川：大河流。\n少壮：年轻力壮，指青少年时代。\n老大：指年老了，老年。徒：白白地。', poem_appreciation = '这是一首咏叹人生的歌。唱人生而从园中葵起调，这在写法上被称作“托物起兴”，即“先言他物以引起所咏之辞也”。园中葵在春天的早晨亭亭玉立，青青的叶片上滚动着露珠，在朝阳下闪着亮光，像一位充满青春活力的少年。诗人由园中葵的蓬勃生长推而广之，写到整个自然界，由于有春天的阳光、雨露，万物都在闪耀着生命的光辉，到处是生机盎然、欣欣向荣的景象。这四句，字面上是对春天的礼赞，实际上是借物比人，是对人生最宝贵的东西──青春的赞歌。人生充满青春活力的时代，正如一年四季中的春天一样美好。这样，在写法上它同时又有比喻的意义，即所谓“兴而比”。\n\n　　自然界的时序不停交换，转眼春去秋来，园中葵及万物经历了春生、夏长，到了秋天，它们成熟了，昔日奕奕生辉的叶子变得焦黄枯萎，丧失了活力。人生也是如此，由青春勃发而长大，而老死，也要经历一个新陈代谢的过程。这是一个不可移易的自然法则。诗人用“常恐秋节至”表达对“青春”稍纵即逝的珍惜，其中一个“恐”字，表现出人们对自然法则的无能为力，青春凋谢的不可避免。接着又从时序的更替联想到宇宙的无尽时间和无垠空间，时光像东逝的江河，一去不复返。由时间尺度来衡量人的生命也是老死以后不能复生。在这永恒的自然面前，人生岂不就像叶上的朝露一见太阳就被晒干了吗？岂不就像青青葵叶，一语秋风就枯黄凋谢了吗？诗歌由对宇宙的探寻转入对人生价值的思考，终于推出“少壮不努力，老大徒伤悲”这一发聋振聩的结论，结束全诗。这个推理的过程，字面上没有写出来，但读者可循着诗人思维的轨迹，用自己的人生体验来补足：自然界的万物有一个春华秋实的过程，人生也有一个少年努力、老有所成的过程；自然界的万物只要有阳光雨露，秋天自能结实，人却不同，没有自身努力是不能成功的；万物经秋变衰，但却实现了生命的价值，因而不足伤悲；人则不然，因“少壮不努力”而老无所成，岂不等于空走世间一趟。调动读者思考，无疑比代替读者思考高明。正由于此，使这首诗避免了容易引人生厌的人生说教，使最后的警句显得浑厚有力，深沉含蓄，如洪钟长鸣一般，深深地打动了读者的心。句末中的“徒”字意味深长：一是说老大无成，人生等于虚度了;二是说老年时才醒悟将于事无补，徒叹奈何，意在强调必须及时努力。\n\n　　读这首诗，我们很自然会联想到《钢铁是怎样炼成的》那段关于人的生命应该如何度过的名言。“人最宝贵的东西是生命。每个人只有一次生命。因此，一个人的一生应该这样度过：当他回顾已逝的年华时，不因虚度时光而悔恨，也不因一事无成而羞愧;这样，在他即将离开人世的时候，就可以坦然地说：我把整个生命和全部的精力，都奉献给了人世间最壮丽的事业——为人类的解放而奋斗。”引导读者少壮及时努力，不要虚度光阴，这种人生态度无疑是积极的。\n\n　　这是汉代乐府古诗中的一首名作。诗中用了一连串的比喻，来说明应该好好珍惜时光，及早努力。诗的前四句，向我们描绘了一幅明媚的春景，园子里绿油油的葵菜上还带着露水，朝阳升起之后，晒干了露水，葵菜又沐浴在一片阳光中。世上的万物都在春天受到大自然雨露的恩惠，焕发出无比的光彩。可是，秋天一到，它们都要失去鲜艳的光泽，变得枯黄衰落了。万物都有盛衰的变化，人也有由少年到老年的过程。时间就像大江大河的水一样，一直向东流入大海，一去不复返了。我们在年少力强的时候如果不珍惜时光，好好努力的话，到老的时候就只能白白地悲伤了！', poem_tags = '古诗三百首,初中古诗,咏物,励志,哲理,惜时' WHERE poem_title = '长歌行' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '青翠的山峦横卧在城墙的北面，波光粼粼的流水围绕着城的东边。\n在此地我们相互道别，你就像孤蓬那样随风飘荡，到万里之外远行去了。\n浮云像游子一样行踪不定，夕阳徐徐下山，似乎有所留恋。\n挥挥手从此分离，友人骑的那匹将要载他远行的马萧萧长鸣，似乎不忍离去。', poem_notes = '郭：古代在城外修筑的一种外墙。\n白水：清澈的水。\n一：助词，加强语气。名做状。\n别：告别。\n蓬：古书上说的一种植物，干枯后根株断开，遇风飞旋，也称“飞蓬”。诗人用“孤蓬”喻指远行的朋友。\n征：远行。\n浮云游子意：曹丕《杂诗》：“西北有浮云，亭亭如车盖。惜哉时不遇，适与飘风会。吹我东南行，行行至吴会。”后世用为典实，以浮云飘飞无定喻游子四方漂游。浮云，飘动的云。游子，离家远游的人。\n兹：声音词。此。\n萧萧：马的呻吟嘶叫声。\n班马：离群的马，这里指载人远离的马。班，分别；离别，一作“斑”。', poem_appreciation = '这是一首情意深长的送别诗，作者通过送别环境的刻画、气氛的渲染，表达出依依惜别之意。首联的“青山横北郭，白水绕东城”，交代出了告别的地点。诗人已经送友人来到了城外，然而两人仍然并肩缓辔，不愿分离。只见远处，青翠的山峦横亘在外城的北面，波光粼粼的流水绕城东潺潺流过。这两句中“青山”对“白水”，“北郭”对“东城”，首联即写成工丽的对偶句，别开生面；而且“青”、“白”相间，色彩明丽。“横”字勾勒青山的静姿，“绕”字描画白水的动态，用词准确而传神。诗笔挥洒自如，描摹出一幅寥廓秀丽的图景。未见“送别”二字，其笔端却分明饱含着依依惜别之情。\n\n　　接下去两句写情。诗人借孤蓬来比喻友人的漂泊生涯，说：此地一别，离人就要象那随风飞舞的蓬草，飘到万里之外去了。此联从语意上看可视为流水对形式，即两联语义相承。但纯从对的角度看不是工对，甚至可以说不“对”，它恰恰体现了李白“天然去雕饰”的诗风，也符合古人不以形式束缚内容的看法。此联出句“此地一为别”语意陡转，将上联的诗情画意扯破，有一股悲剧的感人力量。古人常以飞蓬、转蓬、飘蓬喻飘泊生涯，因为二者都有屈从大自然、任它物调戏而不由自主的共同特征。所以，此句想到“逢”的形象时十分沉重，有不忍之情，非道一声珍重可比。太白集王琦注云：“浮云一往而无定迹，故以比游子之意；落日衔山而不遽去，故以比故人之情。”这两句诗表达了诗人对友人的深切关心，写得流畅自然，感情真挚。\n\n　　颈联“浮云游子意，落日故人情”，大笔挥洒出分别时的寥阔背景：天边一片白云飘然而去，一轮红日正向着地平线徐徐而下。此时此景，更令诗人感到离别的不舍。这两句“浮云”对“落日”，“游子意”对“故人情”，也对得很工整，切景切题。诗人不仅是写景，而且还巧妙地用“浮云”来比喻友人：就象天边的浮云，行踪不定，任意东西，谁知道会飘泊到何处呢？无限关切之意自然溢出，而那一轮西沉的红日落得徐缓，把最后的光线投向青山白水，仿佛不忍遽然离开。而这正是诗人此刻心情的象征。\n\n　　此句也可理解为游子将行未行的恋旧情意，有欲行又止，身行心留之复杂意绪。落目的形象既可理解为故人的眷恋之情，亦可理解为对友人的祝福之情。“夕阳无限好”、“长河落日圆”，但愿友人前路阳光灿烂，诸事圆满遂心，呼应了“孤蓬万里征”一句。\n\n　　尾联两句，情意更切。“挥手自兹去，萧萧班马鸣。”送君千里，终须一别。“挥手”，是写了分离时的动作，诗人内心的感受没有直说，只写了“萧萧班马鸣”的动人场景。诗人和友人在马上挥手告别，频频致意。那两匹马仿佛懂得主人心情，也不愿脱离同伴，临别时禁不住萧萧长鸣，似有无限深情。末联借马鸣之声犹作别离之声，衬托离情别绪。李白化用古典诗句，用一个“班”字，便翻出新意，烘托出缱绻情谊，是鬼斧神工的手笔。\n\n　　这首送别诗写得新颖别致，不落俗套。诗中青山，流水，红日，白云，相互映衬，色彩璀璨。班马长鸣，形象新鲜活泼，组成了一幅有声有色的画面。自然美与人情美交织在一起，写得有声有色，气韵生动，画面中流荡着无限温馨的情意，感人肺腑。', poem_tags = '唐诗三百首,初中古诗,送别,写景,惜别,友情' WHERE poem_title = '送友人' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '我家洗砚池边有一棵梅树，朵朵开放的梅花都显出淡淡的墨痕。\n不需要别人夸它的颜色好看，只需要梅花的清香之气弥漫在天地之间。', poem_notes = '墨梅：用墨笔勾勒出来的梅花。\n吾家：我家。因王羲之与王冕同姓，所以王冕便认为王姓自是一家。\n洗砚池：写字、画画后洗笔洗砚的池子。王羲之有“临池学书，池水尽黑”的传说。这里化用这个典故。\n池头：池边。头 ：边上。\n淡墨：水墨画中将墨色分为四种，如，清墨、淡墨、浓墨、焦墨。这里是说那朵朵盛开的梅花，是用淡淡的墨迹点化成的。\n痕：痕迹。\n清气:梅花的清香之气。\n满乾坤：弥漫在天地间。满：弥漫。乾坤：天地间。', poem_appreciation = '这是一首题画诗。诗人赞美墨梅不求人夸，只愿给人间留下清香的美德，实际上是借梅自喻，表达自己对人生的态度以及不向世俗献媚的高尚情操。\n\n　　开头两句“吾家洗砚池头树，朵朵花开淡墨痕”直接描写墨梅。画中小池边的梅树，花朵盛开，朵朵梅花都是用淡淡的墨水点染而成的。“洗砚池”，化用王羲之“临池学书，池水尽黑”的典故。\n\n　　三、四两句盛赞墨梅的高风亮节。它由淡墨画成，外表虽然并不娇艳，但具有神清骨秀、高洁端庄、幽独超逸的内在气质；它不想用鲜艳的色彩去吸引人，讨好人，求得人们的夸奖，只愿散发一股清香，让它留在天地之间。这两句正是诗人的自我写照。王冕自幼家贫，白天放牛，晚上到佛寺长明灯下苦读，终于学得满腹经纶，而且能诗善画，多才多艺。但他屡试不第，又不愿巴结权贵，于是绝意功名利禄，归隐浙东九里山，作画易米为生。“不要人夸颜色好，只留清气满乾坤”两句，表现了诗人鄙薄流俗，独善其身，不求功勋的品格。\n\n　　这首诗题为“墨梅”，意在述志。诗人将画格、诗格、人格有机地融为一体。字面上在赞誉梅花，实际上是赞赏自己的立身之德。\n\n　　在这首诗中，一“淡”一“满”尽显个性，一方面，墨梅的丰姿与诗人傲岸的形象跃然纸上；另一方面令人觉得翰墨之香与梅花的清香仿佛扑面而来。从而使“诗格”、“画格”、人格巧妙地融合在一起。\n\n　　《墨梅》盛赞梅花的高风亮节，诗人也借物抒怀，借梅自喻，表明了自己的人生态度和高尚情操。有意见认为，该题画诗，点出创作意图，强调操守志趣，在艺术史上甚至比《墨梅图》本身还要出名。', poem_tags = '古诗三百首,题画,咏物,梅花,寓人,言志' WHERE poem_title = '墨梅' AND poem_author = '王冕';
UPDATE edu_poem SET poem_translation = '独自远离家乡无法与家人团聚，每到重阳佳节倍加思念远方的亲人。\n远远想到兄弟们身佩茱萸登上高处，也会因为少我一人而生遗憾之情。', poem_notes = '九月九日：即重阳节。古以九为阳数，故曰重阳。忆：想念。山东：王维迁居于蒲县（今山西永济县），在函谷关与华山以东，所以称山东。\n异乡：他乡、外乡。 为异客：作他乡的客人。\n佳节：美好的节日。\n登高：古有重阳节登高的风俗。\n茱萸（zhūyú）：一种香草，即草决明。古时人们认为重阳节插戴茱萸可以避灾克邪。', poem_appreciation = '王维这首《九月九日忆山东兄弟》诗载于《全唐诗》卷一百二十八。下面是唐代文学研究会常务理事刘学锴先生对此诗的赏析。\n\n　　王维是一位早熟的作家，少年时期就创作了不少优秀的诗篇。这首诗就是他十七岁时的作品。和他后来那些富于画意、构图设色非常讲究的山水诗不同，这首抒情小诗写得非常朴素。但千百年来，人们在作客他乡的情况下读这首诗，却都强烈地感受到了它的力量。这种力量，首先来自它的朴质、深厚和高度的概括。\n\n　　诗因重阳节思念家乡的亲人而作。王维家居蒲州，在华山之东，所以题称“忆山东兄弟”。写这首诗时他大概正在长安谋取功名。繁华的帝都对当时热中仕进的年轻士子虽有很大吸引力，但对一个少年游子来说，毕竟是举目无亲的“异乡”；而且越是繁华热闹，在茫茫人海中的游子就越显得孤孑无亲。第一句用了一个“独”字，两个“异”字，分量下得很足。对亲人的思念，对自己孤孑处境的感受，都凝聚在这个“独”字里面。“异乡为异客”，不过说他乡作客，但两个“异”字所造成的艺术效果，却比一般地叙说他乡作客要强烈得多。在自然经济占主要地位的封建时代，不同地域之间的风土、人情、语言、生活习惯差别很大，离开多年生活的故乡到异地去，会感到一切都陌生、不习惯，感到自己是漂浮在异地生活中的一叶浮萍。“异乡”“异客”，正是朴质而真切地道出了这种感受。作客他乡者的思乡怀亲之情，在平日自然也是存在的，不过有时不一定是显露的，但一旦遇到某种触媒──最常见的是“佳节”──就很容易爆发出来，甚至一发而不可抑止。这就是所谓“每逢佳节倍思亲”。佳节，往往是家人团聚的日子，而且往往和对家乡风物的许多美好记忆联结在一起，所以“每逢佳节倍思亲”就是十分自然的了。这种体验，可以说人人都有，但在王维之前，却没有任何诗人用这样朴素无华而又高度概括的诗句成功地表现过。而一经诗人道出，它就成了最能表现客中思乡感情的格言式的警句。\n\n　　前两句，可以说是艺术创作的“直接法”。几乎不经任何迂回，而是直插核心，迅即形成高潮，出现警句。但这种写法往往使后两句难以为继，造成后劲不足。这首诗的后两句，如果顺着“佳节倍思亲”作直线式的延伸，就不免蛇足；转出新意而再形成新的高潮，也很难办到。作者采取另一种方式：紧接着感情的激流，出现一泓微波荡漾的湖面，看似平静，实则更加深沉。\n\n　　重阳节有登高的风俗，登高时佩带茱萸囊，据说可以避灾。茱萸，又名越椒，一种有香气的植物。三四两句，如果只是一般化地遥想兄弟如何在重阳日登高，佩带茱萸，而自己独在异乡，不能参与，虽然写出了佳节思亲之情，但会显得平直，缺乏新意与深情。诗人遥想的却是：“遍插茱萸少一人。”意思是说，远在故乡的兄弟们今天登高时身上都佩上了茱萸，却发现少了一位兄弟──自己不在内。好像遗憾的不是自己未能和故乡的兄弟共度佳节，反倒是兄弟们佳节未能完全团聚；似乎自己独在异乡为异客的处境并不值得诉说，反倒是兄弟们的缺憾更须体贴。这就曲折有致，出乎常情。而这种出乎常情之处，正是它的深厚处、新警处。杜甫的《月夜》：“遥怜小儿女，未解忆长安”，和这两句异曲同工，而王诗似乎更不着力。', poem_tags = '唐诗三百首,小学古诗,重阳节,思乡,早教古诗100首' WHERE poem_title = '九月九日忆山东兄弟' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '独自远离家乡无法与家人团聚，每到重阳佳节倍加思念远方的亲人。\n远远想到兄弟们身佩茱萸登上高处，也会因为少我一人而生遗憾之情。', poem_notes = '九月九日：即重阳节。古以九为阳数，故曰重阳。忆：想念。山东：王维迁居于蒲县（今山西永济县），在函谷关与华山以东，所以称山东。\n异乡：他乡、外乡。 为异客：作他乡的客人。\n佳节：美好的节日。\n登高：古有重阳节登高的风俗。\n茱萸（zhūyú）：一种香草，即草决明。古时人们认为重阳节插戴茱萸可以避灾克邪。', poem_appreciation = '王维这首《九月九日忆山东兄弟》诗载于《全唐诗》卷一百二十八。下面是唐代文学研究会常务理事刘学锴先生对此诗的赏析。\n\n　　王维是一位早熟的作家，少年时期就创作了不少优秀的诗篇。这首诗就是他十七岁时的作品。和他后来那些富于画意、构图设色非常讲究的山水诗不同，这首抒情小诗写得非常朴素。但千百年来，人们在作客他乡的情况下读这首诗，却都强烈地感受到了它的力量。这种力量，首先来自它的朴质、深厚和高度的概括。\n\n　　诗因重阳节思念家乡的亲人而作。王维家居蒲州，在华山之东，所以题称“忆山东兄弟”。写这首诗时他大概正在长安谋取功名。繁华的帝都对当时热中仕进的年轻士子虽有很大吸引力，但对一个少年游子来说，毕竟是举目无亲的“异乡”；而且越是繁华热闹，在茫茫人海中的游子就越显得孤孑无亲。第一句用了一个“独”字，两个“异”字，分量下得很足。对亲人的思念，对自己孤孑处境的感受，都凝聚在这个“独”字里面。“异乡为异客”，不过说他乡作客，但两个“异”字所造成的艺术效果，却比一般地叙说他乡作客要强烈得多。在自然经济占主要地位的封建时代，不同地域之间的风土、人情、语言、生活习惯差别很大，离开多年生活的故乡到异地去，会感到一切都陌生、不习惯，感到自己是漂浮在异地生活中的一叶浮萍。“异乡”“异客”，正是朴质而真切地道出了这种感受。作客他乡者的思乡怀亲之情，在平日自然也是存在的，不过有时不一定是显露的，但一旦遇到某种触媒──最常见的是“佳节”──就很容易爆发出来，甚至一发而不可抑止。这就是所谓“每逢佳节倍思亲”。佳节，往往是家人团聚的日子，而且往往和对家乡风物的许多美好记忆联结在一起，所以“每逢佳节倍思亲”就是十分自然的了。这种体验，可以说人人都有，但在王维之前，却没有任何诗人用这样朴素无华而又高度概括的诗句成功地表现过。而一经诗人道出，它就成了最能表现客中思乡感情的格言式的警句。\n\n　　前两句，可以说是艺术创作的“直接法”。几乎不经任何迂回，而是直插核心，迅即形成高潮，出现警句。但这种写法往往使后两句难以为继，造成后劲不足。这首诗的后两句，如果顺着“佳节倍思亲”作直线式的延伸，就不免蛇足；转出新意而再形成新的高潮，也很难办到。作者采取另一种方式：紧接着感情的激流，出现一泓微波荡漾的湖面，看似平静，实则更加深沉。\n\n　　重阳节有登高的风俗，登高时佩带茱萸囊，据说可以避灾。茱萸，又名越椒，一种有香气的植物。三四两句，如果只是一般化地遥想兄弟如何在重阳日登高，佩带茱萸，而自己独在异乡，不能参与，虽然写出了佳节思亲之情，但会显得平直，缺乏新意与深情。诗人遥想的却是：“遍插茱萸少一人。”意思是说，远在故乡的兄弟们今天登高时身上都佩上了茱萸，却发现少了一位兄弟──自己不在内。好像遗憾的不是自己未能和故乡的兄弟共度佳节，反倒是兄弟们佳节未能完全团聚；似乎自己独在异乡为异客的处境并不值得诉说，反倒是兄弟们的缺憾更须体贴。这就曲折有致，出乎常情。而这种出乎常情之处，正是它的深厚处、新警处。杜甫的《月夜》：“遥怜小儿女，未解忆长安”，和这两句异曲同工，而王诗似乎更不着力。', poem_tags = '唐诗三百首,小学古诗,重阳节,思乡,早教古诗100首' WHERE poem_title = '九月九日忆山东兄弟' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '应是常常想起一次郊游，一玩就到日暮时分，沉醉在其中不想回家。\n一直玩到没了兴致才乘舟返回，却迷途进入藕花池的深处。\n怎么才能把船划出去，不小心，却惊起了一群的鸥鹭。\n\n译文二\n经常记起在溪边的亭子游玩直到太阳落山的时候，被美景陶醉而流连忘返。\n游兴满足了，天黑往回划船，不小心划进了荷花池深处。\n划呀，划呀，惊动满滩的水鸟，都飞起来了。\n\n译文三\n曾记得一次溪亭饮酒到日暮，喝得大醉回家找不着了道路。\n兴尽之后很晚才往回划船，却不小心进入了荷花深处。\n怎么渡，怎么渡？（最终）惊起水边满滩鸥鹭。', poem_notes = '常记：时常记起。“难忘”的意思。\n溪亭：临水的亭台。\n日暮：黄昏时候。\n沉醉：比喻沉浸在某事物或某境界中。\n兴尽：尽了兴致。\n晚：比合适的时间靠后，这里意思是天黑路暗了。\n回舟：乘船而回。\n误入：不小心进入。\n藕花：荷花。\n争渡：怎渡，怎么才能划出去。争（zen)，怎样才能\n惊：惊动。\n起：飞起来。\n一滩：一群。\n鸥鹭：这里泛指水鸟。', poem_appreciation = '简评 　　这首词在南宋人黄升的《花庵词选》中题为“酒兴”。玩词意，似为回忆一次愉快的郊游而作。词人命舟备酒，畅游于清溪，因沉酣竟不知日之夕矣。沉沉暮霭中，回舟误入曲港横塘，藕花深处。这是一个清香流溢，色彩缤纷的，幽杳而神秘的世界。它给词人带来的是巨大的惊喜和深深的陶醉。花香、酒气，使词人暂时摆脱了封建社会名门闺秀的重重枷锁，显现出她贪玩活泼天性。于是有争渡之举。当轻舟穿行于荷花之中，看着栖息在花汀渔浦的鸥鹭惊飞，她感受到了一种强烈的生命的活力。这种活力就从词短促的节奏和响亮的韵脚中洋溢而出。 这首词杨金本《65+草堂诗余》误作苏轼词，《词林万选》误作无名氏词，《古今词话》、《唐词纪》误作吕洞宾词。从“误作”之多，也可看出此词之放逸已超出了“闺秀词”的范围，所以有人把它列入男性作者的名下。但南宋人黄升的《花庵词选》、曾慥的《乐府雅词》都把它作李清照词，应当是可信的。 ▲', poem_tags = '宋词三百首,宋词精选,初中古诗,纪游' WHERE poem_title = '如梦令·常记溪亭日暮' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '当初，孙权对吕蒙说：“你现在当权管事，不可以不学习！”吕蒙用军中事务繁多来推托。孙权说：“我难道想要你研究儒家经典，成为博士（专掌经学传授的学官）吗？我只是让你粗略地阅读，了解历史罢了。你说军务繁多，谁比得上我（事务多）呢？我经常读书，自己觉得获益很多。”吕蒙于是开始学习。当鲁肃到寻阳的时候，鲁肃和吕蒙一起谈论议事，鲁肃十分吃惊地说：“你现在的军事方面和政治方面的才能和谋略，不再是原来的那个吴县的（没有学识的）阿蒙了！”吕蒙说：“志士（君子）分别几天，就重新另眼看待了，长兄你认清事物怎么这么晚呢？”于是鲁肃拜见吕蒙的母亲，和吕蒙结为朋友后分别了。', poem_notes = '初：当初，起初，这里是追述往事的习惯用词。\n权：指孙权，字仲谋，吴郡富春（浙江富阳）人，黄龙元年（公元222年）称王于武昌（今湖北鄂城），国号吴，不久迁都建业，（今江苏南京）。229年称帝。\n谓……曰：谓，告诉；连用表示“对……说”。\n吕蒙：字子明，三国时吴国名将，汝南富陂（今安徽省阜南县东南）人。\n卿：古代君对臣或朋友之间的爱称。\n今：当今。\n当涂：当道，当权。\n掌事：掌管政事。\n辞：推托。\n以：介词，用。\n务：事务。\n孤：古时王侯的自称。\n岂：难道。\n治经：研究儒家经典。治，研究。“经”指《诗经》《尚书》《礼记》《周易》《春秋》等书。\n博士：当时专掌经学传授的学官。\n邪（yé）：通“耶”，语气词，表示反问或疑问的语气。\n但：只，仅。\n当：应当。\n涉猎：粗略地阅读。\n见往事：了解历史。见，了解；往事，指历史。\n耳：语气词，表示限制语气，罢了。\n多务：事务多，杂事多。务，事务。\n孰若：与……相比如何；谁像（我）。孰：谁，哪个；若：比得上。\n益：好处。\n乃：于是，就。\n始：开始。\n就学：指从事学习。就，单独翻译为 从事。\n及：到了……的时候。\n过：到。\n寻阳： 县名，在湖北黄梅西南。\n论议：讨论议事。\n大：非常，十分。\n惊：惊奇。\n者：用在时间词后面，不译。\n才略：军事方面或政治方面的才干和谋略。\n非复：不再是。复：再，又。\n吴下阿蒙：指在吴下时的没有才学的吕蒙。吴下，指吴县，如今江苏苏州。阿蒙，指吕蒙，名字前加“阿“，有亲昵的意味。现指才识尚浅的人。\n士别三日：与读书的人分别几天。三：几天，这里指“几”。士，读书人。\n即：就。\n更（gēng）：重新。\n刮目相待：另眼相看，用新的眼光看待。 刮目：擦擦眼。待：看待。\n大兄：长兄，这里是对同辈年长者的尊称。\n何：为什么。\n见事：认清事物。见，认清，识别。\n乎：啊。表感叹或反问语气。\n遂：于是，就。\n拜：拜见。\n别：离开。', poem_appreciation = '该文是根据先前的史书改写的。因先前的史书已有较详细的记载，而又无新的史料可以补充，所以文章是根据从略的原则对先前史书的有关记载进行改写的。文章篇幅小，仅119字，虽极简略但剪裁精当，不仅保留了原文的精华和故事的完整性，而且以更精练的文笔突出了人物的风采，是一篇成功的改写之作。\n\n　　该文以对话为主，其他内容均简说或不说。如对吕蒙的学习情况，仅以“蒙乃始就学”一句加以概括，至于他读了哪些书，又如何用功则只字未提。后文中吕蒙二人的谈话，只用一句“与蒙论议”来交代，两人谈论的是什么话题，吕蒙的哪些见解让鲁肃起敬的都略去不写。详略的安排极其精当。 除对话外的其他语言也非常简省而意赅。情节发展上，孙权的刻意劝学终使吕蒙就学，他就学后的渊博学识又使鲁肃惊叹，吕蒙又紧承其叹发出“士别三日，即更刮目相待”的自信之语，上下文衔接自然，前因后果，井然有序。\n\n　　该文写的是吕蒙在孙权劝说下“乃始就学”。孙权劝学，先向吕蒙指出“学”的必要性，即因其“当涂掌事”的重要身份而“不可不学”；继而现身说法，指出“学”的可能性。使吕蒙无可推辞、“乃始就学”。从孙权的话中，既可以看出他的善劝，又可以感到他对吕蒙的亲近、关心和期望，而又不失人主的身份。“卿今者才略，非复吴下阿蒙”，是情不自禁的赞叹，可见鲁肃十分惊奇的神态，以他眼中吕蒙变化之大竟然判若两人，表现吕蒙因“学”而使才略有了令人难以置信的惊人长进。需要指出的是，鲁肃不仅地位高于吕蒙，而且很有学识，由他说出这番话，更可表明吕蒙的长进确实非同一般。“士别三日，即更刮目相待，大兄何见事之晚乎？”是吕蒙对鲁肃赞叹的巧妙接应。从吕蒙的答话中可见吕蒙颇为自得的神态，吕蒙以当之无愧的坦然态度，表明自己才略长进之快之大。孙权的话是认真相劝，鲁肃、吕蒙的话则有调侃的意味，二者的情调是不同的。其才略很快就有惊人的长进而令鲁肃叹服并与之“结友”的故事，说明了人只要肯学习就会有长进，突出了学习重要性。\n\n　　读书使吕蒙的言谈大有智慧，所以鲁肃的语气重在惊叹：“卿今者才略，非复吴下阿蒙!”吕蒙也仅说了一句话：“士别三日，即更刮目相待，大兄何见事之晚乎!”话中既有对鲁肃大惊小怪的不以为然，更有一种书中多阅历，胸中有丘壑的自信，令人油然而生一种敬羡之情。吕蒙读书的功效是通过鲁肃的与吕蒙的对话从侧面展现出来的，他的惊叹衬托出了吕蒙今非昔比的事实。而话中的“吴下阿蒙”又将吕蒙的过去与现在进行了一个纵向的对比，得出了“变”的结论，而吕蒙之“变”的核心正是“才略”的猛增。\n\n　　吕蒙的谦虚好学， 鲁肃的英雄惜英雄，三位一体，足显作者的文笔功架之深厚。', poem_tags = '初中文言文,学习,哲理' WHERE poem_title = '孙权劝学' AND poem_author = '司马光 撰';
UPDATE edu_poem SET poem_translation = '到底是西湖六月天的景色，风光与其它季节确实不同。\n荷叶接天望不尽一片碧绿，阳光下荷花分外艳丽鲜红。', poem_notes = '晓出：太阳刚刚升起。\n净慈寺：全名“净慈报恩光孝禅寺”，与灵隐寺为杭州西湖南北山两大著名佛寺。\n林子方：作者的朋友，官居直阁秘书。\n毕竟： 到底。\n六月中：六月的时候。\n四时：春夏秋冬四个季节。在这里指六月以外的其他时节。\n同：相同。\n接天：像与天空相接。\n无穷：无边无际。无穷碧：因莲叶面积很广，似与天相接，故呈现无穷的碧绿。\n映日：太阳映照。\n别样：宋代俗语，特别，不一样。别样红：红得特别出色。', poem_appreciation = '这是一首描写杭州西湖六月美丽景色的诗。全诗通过对西湖美景的赞美，曲折地表达对友人深情的眷恋。\n\n　　“毕竟西湖六月中，风光不与四时同”，诗人开篇即说毕竟六月的西湖，风光不与四时相同，这两句质朴无华的诗句，说明六月西湖与其他季节不同的风光，是足可留恋的。这两句是写六月西湖给诗人的总的感受。“毕竟”二字，突出了六月西湖风光的独特、非同一般，给人以丰富美好的想象。首句看似突兀，实际造句大气，虽然读者还不曾从诗中领略到西湖美景，但已能从诗人赞叹的语气中感受到了。诗句似脱口而出，是大惊大喜之余最直观的感受，因而更强化了西湖之美。\n\n　　然后，诗人用充满强烈色彩对比的句子，给读者描绘出一幅大红大绿、精彩绝艳的画面：“接天莲叶无穷碧，映日荷花别样红。”这两句具体地描绘了“毕竟”不同的风景图画：随着湖面而伸展到尽头的荷叶与蓝天融合在一起，造成了“无穷”的艺术空间，涂染出无边无际的碧色；在这一片碧色的背景上，又点染出阳光映照下的朵朵荷花，红得那么娇艳、那么明丽。连天“无穷碧”的荷叶和映日“别样红”的荷花，不仅是春、秋、冬三季所见不到，就是夏季也只在六月中荷花最旺盛的时期才能看到。诗人抓住了这盛夏时特有的景物，概括而又贴切。这种在谋篇上的转化，虽然跌宕起伏，却没有突兀之感。看似平淡的笔墨，给读者展现了令人回味的艺术境地。\n\n　　杨万里的诗以白描见长，就这点来说，这是诗不失为他的代表作之一。从艺术上来说，出了白描以外，此诗还有两点值得注意：一是虚实相生。前两句直陈，只是泛说，为虚；后两句描绘，展示具体形象，为实。虚实结合，相得益彰。二是刚柔相济。后两句所写的莲叶荷花，一般归入阴柔美一类，而诗人却把它写得非常壮美，境界阔大，有“天”，有“日”。语言也很有气势：“接天”“无穷”。这样，阳刚与柔美，就在诗歌中得到了和谐统一。', poem_tags = '古诗三百首,夏天,西湖,写景,荷花,离别,友情,送别,早教古诗100首,古诗里的十二个月' WHERE poem_title = '晓出净慈寺送林子方' AND poem_author = '杨万里';
UPDATE edu_poem SET poem_translation = '不知道五柳先生是什么地方的人，也不清楚他的姓字。因为住宅旁边有五棵柳树，就把这个作为号了。他安安静静，很少说话，也不羡慕荣华利禄。他喜欢读书，不在一字一句的解释上过分深究；每当对书中的内容有所领会的时候，就会高兴得连饭也忘了吃。他生性喜爱喝酒，家里穷经常没有酒喝。亲戚朋友知道他这种境况，有时摆了酒席叫他去喝。他去喝酒就喝个尽兴，希望一定喝醉；喝醉了就回家，竟然说走就走。简陋的居室里空空荡荡，遮挡不住严寒和烈日，粗布短衣上打满了补丁，盛饭的篮子和饮水的水瓢里经常是空的，可是他还是安然自得。常常写文章来自娱自乐，也稍微透露出他的志趣。他从不把得失放在心上，从此过完自己的一生。\n\n　　赞语说：黔娄的妻子曾经说过：“不为贫贱而忧愁，不热衷于发财做官。这话大概说的是五柳先生这一类的人吧？一边喝酒一边作诗，因为自己抱定的志向而感到无比的快乐。不知道他是无怀氏时代的人呢？还是葛天氏时代的人呢？', poem_notes = '何许人：何处人。也可解作哪里人。许，处所。\n详：知道。\n姓字：姓名。古代男子二十而冠，冠后另立别名称字。\n因以为号焉：就以此为号。以为，以之为。焉，语气助词。\n不求甚解：这里指读书只求领会要旨，不在一字一句的解释上过分探究。\n会意：指对书中的有所体会。会：体会、领会。\n欣然：高兴的样子。\n嗜：喜好。\n亲旧：亲戚朋友。旧，这里指旧交，旧友。\n如此：像这样，指上文所说的“性嗜酒，家贫不能常得。”\n或：有时。\n造饮辄尽：去喝酒就喝个尽兴。造，往，到。辄（zhé），就。\n期在必醉：希望一定喝醉。期，期望。\n既：已经。\n曾不吝情去留：五柳先生态度率真，来了就喝酒，喝完就走。曾（zēng）不，竟不。吝情，舍不得。去留，意思是离开。\n环堵萧然：简陋的居室里空空荡荡。环堵（dǔ）：周围都是土墙，形容居室简陋。堵，墙壁。萧然，空寂的样子。\n短褐穿结：粗布短衣上打了个补丁。短褐，粗布短衣，穿结，指衣服破烂。穿，破。结，缝补。\n箪瓢屡空：形容贫困，难以吃饱。箪（dān），盛饭的圆形竹器。瓢（piáo），饮水用具。屡：经常。\n晏如：安然自若的样子。\n自终：过完自己的一生。\n赞：传记结尾的评论性文字。\n黔（qián）娄：战国时期齐稷下先生，齐国有名的隐士和著名的道家学，无意仕进，屡次辞去诸侯聘请。他死后，曾子前去吊丧，黔娄的妻子称赞黔娄“甘天下之淡味，安天下之卑位，不戚戚于贫贱，不汲汲于富贵。求仁而得仁，求义而得义。”\n戚戚：忧愁的样子。\n汲汲：极力营求的样子、心情急切的样子。\n其言：推究她所说的话。\n兹：这。\n若人：此人，指五柳先生。\n俦（chóu）：辈，同类。\n觞（shāng）：酒杯。\n以乐其志：为自己抱定的志向感到快乐。以，用来。\n无怀氏：与下面的“葛天氏”都是传说中的上古帝王。据说在那个时代，人民生活安乐，恬淡自足，社会风气淳厚朴实。', poem_appreciation = '这篇文章可分为两部分。第一部分是正文。第二部分是赞语。\n\n　　正文部分又可分为四小节。第一节自开头至“因以为号焉”，交代“五柳先生”号的由来，开篇点题。“先生不知何许人也”，文章开头第一句，即把这位先生排除在名门望族之外，不仅不知他的出身和籍贯，“亦不详其姓字”，五柳先生是一位隐姓埋名的人。晋代是很讲究门第的，而五柳先生竟与这种风气背道而驰，这就暗示五柳先生是一位隐士。“宅边有五柳树，因以为号焉”，就这样随便地取了一个字号。五柳先生不仅隐姓埋名，而且根本就不重视姓字，用庄子的话说，“名者，实之宾也”，本就无关紧要。但他看中五柳树的原因也许五柳先生宅边并无桃李，只有这么几棵柳树，这与后面所写“环堵萧然”是一致的。五柳先生的房屋简陋，生活贫穷，这五柳树带一点清静、淡雅、简朴的色彩。以五柳为号也就显示了五柳先生的性格。\n\n　　第二节自“闲补少言”至“欣然忘食”，写五柳先生的禀性志趣。接着写五柳先生的生活、性格。“闲静少言，不慕荣利”，这是五柳先生最突出的地方。闲静少言是五柳先生的外在表现，不慕荣利，才是五柳先生的真实面貌。因为不追求荣利，五柳先生就无须奔忙，不用烦躁，自然也就闲，也就静，用不着喋喋不休。但这种闲静少言，并不等于五柳先生没有志趣。但这一节主要是写其“好读书”而善读书。但五柳先生“好读书，不求甚解”，不求甚解就与五柳先生的“不慕荣利”有关。五柳先生读书的目的，是一种求知的满足，精神的享受，所以“每有会意，便欣然忘食”。这表明了五柳先生是一位有知识的人，和那个时代的社会对他的限制和迫害。\n\n　　第三节自“性嗜洒”至“不吝情去留”，写“五柳先生”的饮酒嗜好。作者强调他的嗜洒是出于天性，而非门阀之士的放荡纵酒，自我麻醉。但嗜洒与家贫又是矛盾的，他不慕荣利，不能摆脱贫困，便“不能常得”到酒。这说明他不因嗜酒而失节。至于亲友请他吃酒，他却毫无拘束，一去即饮，一醉方休，又反映了他的坦率与认真，并没有当时所谓名士的虚伪与矫情。饮酒是他在那种时代环境里使自己得到解脱的一种方法。\n\n　　第四节自“环堵萧然”至“以此自终”，写“五柳先生”的安贫与著文。他虽然居室破漏，衣食不足，但却安然自得。这正是他安贫乐道的表现。而“常著文章自娱”，不入尘网，则是他读书“每有会意”的结果。并且，“忘怀得失”又是他“不慕荣利”的性格使然。这些既与前文相照应，又收束了全篇。\n\n　　对五柳先生的生活、志趣作了叙述以后，第二部分文章结尾也仿史家笔法，加个赞语。这个赞语的实质就是黔娄之妻的两句话：“不戚戚于贫贱，不汲汲于富贵。”这两句话与前面写到的“不慕荣利”相照应，这是五柳先生最大的特点和优点。陶渊明正是通过五柳先生“颇示己志”，表达自己的思想感情。文章最后有两句设问的话：“无怀氏之民欤？葛天氏之民欤？”既表达了他对上古社会淳朴风尚的向往之情，又说明他是一位有着美好现想的隐士。同时也是对世风日卜的黑暗现实的针砭与嘲飒。', poem_tags = '初中文言文,古文观止,赞美,写人,传记' WHERE poem_title = '五柳先生传' AND poem_author = '陶渊明';
UPDATE edu_poem SET poem_translation = '鱼是我所喜爱的，熊掌也是我所喜爱的，如果这两种东西不能同时都得到的话，那么我就只好放弃鱼而选取熊掌了。生命是我所喜爱的，道义也是我所喜爱的，如果这两样东西不能同时都具有的话，那么我就只好牺牲生命而选取道义了。生命是我所喜爱的，但我所喜爱的还有胜过生命的东西，所以我不做苟且偷生的事；死亡是我所厌恶的，但我所厌恶的还有超过死亡的事，所以有的灾祸我不躲避。如果人们所喜爱的东西没有超过生命的，那么凡是能够用来求得生存的手段，哪一样不可以采用呢?如果人们所厌恶的事情没有超过死亡的，那么凡是能够用来逃避灾祸的坏事，哪一桩不可以干呢?采用某种手段就能够活命，可是有的人却不肯采用；采用某种办法就能够躲避灾祸，可是有的人也不肯采用。由此可见，他们所喜爱的有比生命更宝贵的东西（那就是“义”）；他们所厌恶的，有比死亡更严重的事（那就是“不义”）。不仅贤人有这种本性，人人都有，只不过有贤能的人不丧失罢了。\n　　一碗饭，一碗汤，得到它就能活下去，不得到它就会饿死。可是轻蔑地呼喝着给人吃，饥饿的行人也不愿接受；用脚踢给别人吃，乞丐也因轻视而不肯接受。\n　　高官厚禄却不辨是否合乎礼义就接受了它。这样，高官厚禄对我有什么好处呢?是为了住宅的华丽，妻妾的侍奉和认识的穷人感激我吗?以前（有人）宁肯死也不愿接受，现在（有人）却为了住宅的华丽却接受了它；以前（有人）宁肯死也不愿接受，现在（有人）却为了妻妾的侍奉却接受了它；以前（有人）宁肯死也不愿接受，现在（有人）为了认识的穷人感激自己却接受了它。这种做法不是可以让它停止了吗?这就叫做丧失了人所固有的本性。', poem_notes = '选自《孟子·告子上》。\n苟得：苟且取得，这里是“苟且偷生”的意思。\n患：祸患，灾难。\n辟：通“避”，躲避。\n如使：假如，假使。\n何不用也：什么手段不可用呢？\n勿丧：不丢掉。', poem_appreciation = '本文节选自《孟子·告子上》。《告子上》的主要内容是阐明“性善说”，即人性里天生就有向善的种子，所谓“恻隐之心，人皆有之；羞恶之心，人皆有之；恭敬之心，人皆有之；是非之心，人皆有之”。这种善的天性，就是人的“本心”。“本心”不可小视，因为它们分别是仁义礼智这几种道德的萌芽形态：“恻隐之心，仁之端也；羞恶之心，义之端也；辞让（意近“恭敬”）之心，礼之端也；是非之心，义之端也。”人应该推求本心，顺着“本心”的方向发展，并将它发扬光大，从而成为道德上完善的人。\n\n　　放到《告子上》全文里看，本文讲的是每个人都有“本心”，无论在什么情况下，人都应该保有自己的“本心”。只要“本心”在，即使在生死关头，人也能经受住考验；而如果丧失了“本心”，人就会做出亏心事来。其实，仅对本文的结构进行一番分析，我们也可以看出，它的主旨是讲每个人都有“本心”和保有“本心”的重要性。\n\n　　简要分析如下：在第1段里，作者用比喻的方式引出“舍生取义”的观点，并分别从正面和反面加以阐明。行文至“所恶有甚于死者”，作者对这个观点的论述就结束了。紧接着“非独贤者有是心也，人皆有之，贤者能勿丧耳”，提出了新的命题：人人都有“是心”（即本心），只是“贤者”能够保有它。第2段就是对这个命题的论说和阐明。作者用一般的人和乞丐都不肯接受“嗟来之食”的故事证明人人都有“本心”，用“不辩礼义”接受“万钟”的故事概括失去“本心”的人的惯有行为，并对此进行批评和嘲讽。\n\n　　需要注意的是，作者举的失去“本心”的事例，并不牵涉生死，而只是富贵与“义”之间的矛盾与对立，所以，它和“舍生取义”的说法没有什么关系。从课文整体上看，人应该保有“本心”是本文论述的中心。“舍生取义”的观点和不受嗟来之食的故事讲的都是“本心”赋予人的极大力量，属正面论证；“不辩礼义”接受“万钟”的故事讲的是失去“本心”的人的可悲可耻，属反面论证。\n\n　　朱熹说：“此章言羞恶之心，人所固有，或能决死生于危迫之际，而不免计丰约于宴安之时，是以君子不可顷刻不省察于斯焉。”（《四书章句集注》）这段概括主旨的话，还是比较恰切的。', poem_tags = '初中文言文,生死,道德,修养' WHERE poem_title = '鱼我所欲也' AND poem_author = '孟子及其弟子';
UPDATE edu_poem SET poem_translation = '锅里煮着豆子，豆秸在锅底下燃烧，豆子在锅里面哭泣。\n豆子和豆秸本来是同一条根上生长出来的，豆秸怎能这样急迫地煎熬豆子呢？（版本一）\n\n锅里煮着豆子，是想把豆子的残渣过滤出去，留下豆汁来作羹。\n豆秸在锅底下燃烧，豆子在锅里面哭泣。\n豆子和豆秸本来是同一条根上生长出来的，豆秸怎能这样急迫地煎熬豆子呢！ ！（版本二）', poem_notes = '持：用来。\n羹：用肉或菜做成的糊状食物。\n漉：过滤。\n菽（豉）：豆。这句的意思是说把豆子的残渣过滤出去，留下豆汁作羹。\n萁：豆类植物脱粒后剩下的茎。\n釜：锅。\n燃：燃烧\n泣：小声哭\n本：原本，本来。\n煎：煎熬，这里指迫害。\n何：何必。', poem_appreciation = '此诗纯以比兴的手法出之，语言浅显，是寓意明畅，无庸多加阐释，只须于个别词句略加疏通，其意自明。诗人取譬之妙，用语之巧，而且在刹那间脱口而出，实在令人叹为观止。“本是同根生，相煎何太急”二语，千百年来已成为人们劝戒避免兄弟阋墙、自相残杀的普遍用语，说明此诗在人民中流传极广。\n\n　　通过燃萁煮豆这一日常现象，抒发了曹植内心的悲愤。\n\n　　真实度\n\n　　七步诗的真假向来为人所争议。其中郭沫若说的比较有理。他认为曹植的《七步诗》：“过细考察起来，恐怕附会的成分要占多数。多因后人同情曹植而不满意曹丕，故造为这种小说。其实曹丕如果要杀曹植，何必以逼他作诗为借口?子建才捷，他又不是不知道。而且果真要杀他的话，诗作成了依然可以杀，何至于仅仅受了点讥刺而便‘深惭’?所以此诗的真实性实在比较少。然而就因为写了这首诗，曹植却维系了千载的同情，而曹丕也就膺受了千载的厌弃。这真是所谓‘身后是非谁管得’了。”但是他的说法也有人质疑，有人说，当初曹丕让曹植七步成诗只是作为一个借口，想杀他，他认为曹植肯定不能成功，但他没料到，曹植才华如此出众，当时，就连曹丕本人也被感动了些许，并且为了保住名声，以安天下，他才放过了曹植。', poem_tags = '古诗三百首,小学古诗,劝诫,亲情' WHERE poem_title = '七步诗' AND poem_author = '曹植';
UPDATE edu_poem SET poem_translation = '崇祯五年（公元1632年）十二月，我住在西湖边。大雪接连下了多天，湖中的行人、飞鸟的声音都消失了。这一天晚上八点左右，我撑着一叶小舟，穿着毛皮衣，带着火炉，独自前往湖心亭看雪。（湖面上）冰花一片弥漫，天和云和山和水，天光湖色全是白皑皑的。湖上的影子，只有一道长堤的痕迹，一点湖心亭的轮廓，和我的一叶小舟，舟中的两三粒人影罢了。\n\n　　到了湖心亭上，看见有两个人铺好毡子，相对而坐，一个小孩正把酒炉（里的酒）烧得滚沸。（他们）看见我，非常高兴地说：“想不到在湖中还会有您这样的人！”（他们）拉着我一同饮酒。我尽情的喝了三大杯酒，然后和他们道别。（我）问他们的姓氏，（得知他们）是南京人，在此地客居。等到了下船的时候，船夫喃喃地说：“不要说相公您痴，还有像相公您一样痴的人啊！”', poem_notes = '崇祯五年：公元1632年。崇祯，是明思宗朱由检的年号（1628-1644）。\n俱：都。\n绝：消失。\n是日更（gēng）定：是，代词，这。更定：指初更以后。晚上八点左右。定：停止，结束。\n余：第一人称代词，我 。\n拏：通“桡”，撑（船）。\n拥毳（cuì）衣炉火：穿着细毛皮衣，带着火炉。毳衣：细毛皮衣。毳：鸟兽的细毛。\n雾凇沆砀：冰花一片弥漫。雾，从天上下罩湖面的云气。凇，从湖面蒸发的水汽。沆砀，白气弥漫的样子。曾巩《冬夜即事诗》自注：“齐寒甚，夜气如雾，凝于水上，旦视如雪，日出飘满阶庭，齐人谓之雾凇。\n上下一白：上上下下全白。一白，全白。一，全或都，一概。\n惟：只有。\n长堤一痕：形容西湖长堤在雪中只隐隐露出一道痕迹。堤，沿河或沿海的防水建筑物。这里指苏堤。一，数词。痕，痕迹。\n一芥：一棵小草。芥，小草，比喻轻微纤细的事物；（像小草一样微小）。\n而已：罢了。\n毡：毛毯。\n焉得更有此人：意思是：想不到还会有这样的人。焉得，哪能。更，还。\n拉：邀请。\n强（qiǎng）饮：尽情喝。强，尽力，勉力，竭力。一说，高兴地，兴奋地。\n大白：大酒杯。白；古人罚酒时用的酒杯，也泛指一般的酒杯，这里的意思是三杯酒。\n客此：客，做客，名词作动词。在此地客居。\n及：等到。\n舟子：船夫。\n喃喃：低声嘟哝。\n莫：不要。\n相公：原意是对宰相的尊称，后转为对年轻人的敬称及对士人的尊称。\n更：还。\n痴似：痴于，痴过。痴，特有的感受，来展示他钟情山水，淡泊孤寂的独特个性，本文为痴迷的意思。', poem_appreciation = '开头二句点明时间、地点。张岱文集中凡纪昔年游踪之作，大多标明朝纪年，以示不忘故国。这里标“祟侦五年”，也是如此。“十二月”，正当隆冬多雪之时；“余住西湖”，则点明所居邻西湖。这开头的闲闲二句，却从时、地两个方面不着痕迹地引逗出下文的大雪和湖上看雪。下文“大雪三日，湖中人鸟声俱绝”，紧承开头。只此二句，大雪封湖之状就令人可想，读来如觉寒气逼人。作者妙在不从视觉写大雪，而通过听觉来写。“湖中人鸟声俱绝”，写出大雪后湖山封冻，人、鸟都瑟缩着不敢外出，寒嗦得不敢作声，连空气也仿佛冻结了。一个“绝”字，传出冰天雪地、万籁无声的森然寒意。这是高度的写意手法，巧妙地从人的听觉和心理感受上写出了大雪的威严。它使我们联想起唐人柳宗元那首有名的《江雪》诗：“千山鸟飞绝，万径人踪灭。孤舟蓑笠翁，独钓寒江雪。”柳宗元这幅江天大雪图是从视觉着眼的，江天茫茫，人鸟无踪，江雪中独有一位垂钓的渔翁。而张岱笔下则是“人鸟无声”，但这无声却正是人的听觉感受，因而无声中仍有人在。如果说，《江雪》中的“千山鸟飞绝，万径人踪灭”，是为了渲染和衬托寒江独钓的渔翁，那么这里“湖中人鸟声俱绝”，则为下文有人冒寒看雪作映照。\n\n　　“是日，更定矣，余挚一小舟，拥龚衣炉火，独往湖心亭看雪。”“是日”者，“大雪三日”后，严寒之日也；“更定”者，夜深人静，寒气倍增之时也。“拥磊衣炉火”一句，则以御寒之物反衬寒气贬骨。在“人鸟声俱绝”的冰天雪地里，竟有人夜深出门，“独往湖心亭看雪”，表现出作者迥绝流俗的孤怀雅兴。“独往湖心亭看雪”的“独”字，正不妨与“独钓寒江雪”的“独”字互参。作者那种独抱冰雪之操守和孤高自赏的情调，已经溢于言外了。其所以要夜深独往，大约是既不欲人见，也不欲见人；那么，这种孤寂的情怀中，正蕴含着避世的幽愤。\n\n　　请看作者以的空灵之笔来写描绘湖中雪景：“雾淞沉场，天与云、与山、与水，上下一白；湖上影子，惟长堤一痕、湖心亭一点与余舟一芥、舟中人两。三粒而已。”这真是一幅水墨模糊的湖山夜雪图。“雾淞坑场”是形容湖上雪光水气，混檬不分。“天与云、与山、与水，上下一白”，叠用三个“与少’字，似觉天、云、山、水一齐活动起来，较之单纯写“天、云、山、水，上下一白”，多了一点意趣。天、云，上也；山、水，下也。这两句生动地写出天空、云层、群山、湖水之间白茫茫浑然难辨的景象。作者先总写一句，犹如摄取了一个“上下皆白”的全景，从看雪来说，很符合第一眼的总感觉、总印象。接着变换视角，化为一个个诗意盎然的特写镜头：“长堤一痕”、“湖心亭一点”、“余舟一芥’、“舟中人两三粒”等等，这是朦胧的画，梦幻般的诗，给人一种似有若无、依稀恍惚之感。作者对数量词的锤炼功夫，不得不使我们惊叹。你看，“上下一白”之“一”字，是形容混茫难辨，使人唯觉其大；而“一痕”、“一点”、“一芥”之“一”字，则是状其依稀可辨，使人唯觉其小。此真可谓着一“一”字而境界全出矣。同时，由“长堤一痕”到“湖心亭一点”，到“余舟一芥”，到“舟中人两三粒”，其镜头则是从小而更小，直至微乎其微。这“痕”、“点”、“芥”、“粒”等量词，一个小似一个，写出视线的移动，小船的荡漾，景物的变化，着笔空灵，使人浑然不觉。这一段是写景，却又不止于写景；我们从这个混沌一片的冰雪世界中，不难感受到作者那种人生天地间茫茫如“太仓梯米”的深沉感慨。\n\n　　下面移步换形，又开出一个境界。“独往湖心亭看雪”，却不意亭上已有人先我而至；这意外之笔，写忠了作者意外的惊喜产也引起读者意外的惊异。但作者并不说自己惊喜，反写二客“见余大喜”，背面敷粉，反客为主，足见其用笔之夭矫善变。“湖中焉得更有此人！’这一惊叹虽发之于二客，实为作者心声，作者妙在不发一语，而“尽得风流”。二客“拉余同饮”，鼎足而三，颇有幸逢知己之乐。这似乎给冷寂的湖山增添了一分暖色，然而骨子里依然不改其凄清的基调。这有如李白的“举杯邀明月，对影成三人”，不过是一种虚幻的慰藉罢了。“焉得更有”者，正言其人之不可多得。“强饮三大白”，是为了酬谢知己，也为了不负此湖山胜景。“强饮”者，本不能饮，但对此景，当此时，逢此人夕却不可不饮。饮罢相别，始“问其姓氏”，却又妙在语焉不详，只说：“是金陵人，客此。”可见这二位湖上知己，原是他乡游子，萍水相逢，后约难期。这一补叙之笔，透露出作者的无限怅惘：茫茫六合，知己难逢，人生如雪泥鸿爪，转眼各复西东。言念及此，岂不沧神。\n\n　　文章做到这里，也算得神完意足、毫发无憾了。但作者意犹未尽：“及下，舟子喃喃日：‘莫说相公痴，更有痴似相公者！’”前人论词，有点、染之说。这个尾声，可谓融点、染于一体。借舟子之口，点出一个“痴”字；又以相公之“痴”与“痴似相公者”相比较、相浸染，把一个“痴”字写透。所谓“痴似相公”，并非减损相公之“痴”，而是以同调来映衬相公之“痴”。“喃喃”二字，形容舟子自言自语、大惑不解之状，如闻其声，如见其人。这种地方，也正是作者的得意处和感慨处。文情荡漾，余味无穷。', poem_tags = '初中文言文,写雪,感叹,抒怀' WHERE poem_title = '湖心亭看雪' AND poem_author = '张岱';
UPDATE edu_poem SET poem_translation = '从正面、侧面看庐山山岭连绵起伏、山峰耸立，从远处、近处、高处、低处看庐山，庐山呈现各种不同的样子。\n我之所以认不清庐山真正的面目，是因为我人身处在庐山之中。', poem_notes = '题西林壁：写在西林寺的墙壁上。西林寺在庐山西麓。题：书写，题写。西林：西林寺，在江西庐山。\n横看：从正面看。庐山总是南北走向，横看就是从东面西面看.\n侧：侧面。\n各不同：各不相同。\n不识：不能认识，辨别。\n真面目：指庐山真实的景色，形状。\n缘：因为；由于。\n此山：这座山，指庐山。\n西林：西林寺，在现在江西省的庐山上。这首诗是题在寺里墙壁上的。', poem_appreciation = '此诗描写庐山变化多姿的面貌，并借景说理，指出观察问题应客观全面，如果主观片面，就得不出正确的结论。\n\n　　开头两句“横看成岭侧成峰，远近高低各不同”，实写游山所见。庐山是座丘壑纵横、峰峦起伏的大山，游人所处的位置不同，看到的景物也各不相同。这两句概括而形象地写出了移步换形、千姿万态的庐山风景。\n\n　　结尾两句“不识庐山真面目，只缘身在此山中”，是即景说理，谈游山的体会。之所以不能辨认庐山的真实面目，是因为身在庐山之中，视野为庐山的峰峦所局限，看到的只是庐山的一峰一岭一丘一壑，局部而已，这必然带有片面性。这两句奇思妙发，整个意境浑然托出，为读者提供了一个回味经验、驰骋想象的空间。这不仅仅是游历山水才有这种理性认识。游山所见如此，观察世上事物也常如此。这两句诗有着丰富的内涵，它启迪人们认识为人处事的一个哲理——由于人们所处的地位不同，看问题的出发点不同，对客观事物的认识难免有一定的片面性；要认识事物的真相与全貌，必须超越狭小的范围，摆脱主观成见。\n\n　　仁者见仁，智者见智。一首小诗激起人们无限的回味和深思。所以，《题西林壁》不单单是诗人歌咏庐山的奇景伟观，同时也是苏轼以哲人的眼光从中得出的真理性的认识。由于这种认识是深刻的，是符合客观规律的，所以诗中除了有谷峰的奇秀形象给人以美感之外，又有深永的哲理启人心智。因此，这首小诗格外来得含蓄蕴藉，思致渺远，使人百读不厌。\n\n　　这首诗寓意十分深刻，但所用的语言却异常浅显。深入浅出，这正是苏轼的一种语言特色。苏轼写诗，全无雕琢习气。诗人所追求的是用一种质朴无华、条畅流利的语言表现一种清新的、前人未曾道的意境；而这意境又是不时闪烁着荧荧的哲理之光。从这首诗来看，语言的表述是简明的，而其内涵却是丰富的。也就是说，诗语的本身是形象性和逻辑性的高度统一。诗人在四句诗中，概括地描绘了庐山的形象的特征，同时又准确地指出看山不得要领的道理。鲜明的感性与明晰的理性交织一起，互为因果，诗的形象因此升华为理性王国里的典型，这就是人们为什么千百次的把后两句当作哲理的警句的原因。\n\n　　如果说宋以前的诗歌传统是以言志、言情为特点的话，那么到了宋朝尤其是苏轼，则出现了以言理为特色的新诗风。这种诗风是宋人在唐诗之后另辟的一条蹊径，用苏轼的话来说，便是“出新意于法度之中，寄妙理于豪放之外”。形成这类诗的特点是：语浅意深，因物寓理，寄至味于淡泊。《题西林壁》就是这样的一首好诗。', poem_tags = '古诗三百首,小学古诗,纪游,写景,写山,庐山,哲理,早教古诗100首' WHERE poem_title = '题西林壁' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '京城里有个擅长表演口技的人。一天正赶上有一家人宴请宾客，在客厅的东北角，安放了一座八尺高的屏风，表演口技的艺人坐在屏风里面，里面只放了一张桌子、一把椅子、一把扇子、一块醒木罢了。客人们围绕着屏风而坐。一会儿，只听见屏风里面醒木一拍，全场静悄悄的，没有人敢大声说话。 \n听到远远的深巷中传来一阵狗叫声，就有妇女惊醒后打呵欠和伸懒腰的声音，她的丈夫在说梦话。过了一会儿孩子醒了，大声哭着。丈夫也醒了。妇人抚慰孩子喂奶，孩子含着乳头哭，妇女又轻声哼唱着哄他入睡。又有一个大儿子醒了，絮絮叨叨地说个不停。在这时候，妇女用手拍孩子的声音，口里哼着哄孩子的声音，孩子边含乳头边哭的声音，大孩子刚醒过来的声音，丈夫责骂大孩子的声音，同时响起，各种声音都模仿得像极了。满座的宾客没有一个不伸长脖子，偏着头仔细听，微笑，默默赞叹，认为奇妙极了。\n过了一会儿，丈夫打起了呼噜声，妇女拍孩子的声音也渐渐消失。隐隐听到有老鼠作作索索的声音，盆子、器皿翻倒倾斜，妇女在梦中发出了咳嗽声。宾客们的心情稍微放松了些，渐渐端正了坐姿。\n忽然有一个人大声呼叫：“着火啦”，丈夫起来大声呼叫，妇人也起来大声呼叫。两个小孩子一齐哭了起来。一会儿，有成百上千人大声呼叫，成百上千的小孩哭叫，成百上千条狗汪汪地叫。中间夹杂着劈里啪啦，房屋倒塌的声音，烈火燃烧发出爆裂的声音，呼呼的风声，千百种声音一齐发出；又夹杂着成百上千人的求救的声音，救火的人们拉倒燃烧着的房屋时许许的声音，抢救东西的声音，救火的声音。凡是在这种情况下应该有的声音，没有一样没有的。即使一个人有上百只手，每只手有上百个指头，也不能指出其中的任何一种声音来；即使一个人有上百张嘴，每张嘴里有上百条舌头，也不能说出其中的一个地方来啊。在这种情况下，客人们没有不吓得变了脸色，离开座位，捋起衣袖露出手臂，两条大腿哆嗦打抖，几乎要争先恐后地逃跑。\n忽然醒木一拍，各种声响全部消失了。撤去屏风一看里面，(只有)一个人、一张桌子、一把椅子、一把扇子、一块醒木罢了。', poem_notes = '京：京城。\n善：擅长，善于。\n者：……的人。\n口技：杂技的一种。用口腔发音技巧来模仿各种声音。\n会：适逢，正赶上。\n宴：举行宴会，名词动用。\n于：在。\n厅事：大厅，客厅。\n施：设置，安放。\n屏障：指屏风、围帐一类用来挡住视线的东西。\n抚尺：艺人表演用的道具，也叫“醒木”。\n而已：罢了。\n团坐：相聚而坐。团，聚集、集合。\n少（shǎo）顷（qǐng）：不久，一会儿。\n但：只。\n闻：听见。\n下：拍。\n满坐寂然：全场静悄悄的。坐，通“座”。寂然，安静的样子。然：用在形容词的词尾，表示：……的样子。\n哗：喧哗，大声说话。\n坐：通“座”，座位，这里指座位上的人。\n寂然：静悄悄的样子。\n深巷：幽深的巷子。\n深：很长。\n犬吠：狗叫（声）。\n遥：远远地。\n惊觉（旧读jiào)：惊醒。\n欠伸：欠：打呵欠 ，伸：伸懒腰。\n呓（yì）语：说梦话。\n既而：不久，紧接着。而，这里作表时间的副词的词尾。\n啼：哭。\n抚：抚摸，安慰。\n儿乳：乳：作动词用，喂奶。\n含乳：乳头\n呜：指轻声哼唱着哄小孩入睡。\n絮絮：连续不断地说话。\n当是时：在这个时候。\n初：刚，刚开始。\n叱（chì）：大声呵斥，严厉批评。\n一时：同一时候。\n齐发：一齐发出。\n众妙毕备：各种妙处都具备，意思是各种声音都模仿得极像。毕：全、都。备：具备。\n无不：没有一个不，否定加否定表示肯定。\n伸颈：伸长脖子。\n侧目：偏着头看，形容听得入神，名词动用。\n默叹：默默地赞叹。\n以为：认为。\n妙绝：奇妙极了，好极了。绝：到了极点。\n未几：不多久。\n齁（hōu）：打鼾（hān），打呼噜。\n（2）渐：慢慢地。\n微闻：隐约地听到。\n作作索索：老鼠活动的声音。（拟声词）\n盆器：指盆一类的盛物的器皿。\n倾侧：翻倒倾斜。\n意少舒：心情稍微放松了些。意：心情。少（shǎo）：稍微。舒：伸展、松弛。\n稍稍：时间副词，据《词源》释为“随即”，这里是渐渐。\n正坐：端正坐的姿势。\n忽：忽然，突然。\n火起：起火，失火。\n齐：一齐。\n俄而：一会儿，不久。\n中间（jiàn）：其中夹杂着。中：其中 间：夹杂\n力拉崩倒：劈里啪啦，房屋倒塌。\n力拉：拟声词。\n火爆声：烈火燃烧物品爆裂的声音。\n齐作：一齐发出。\n曳（yè）屋许许（hǔhǔ）声：（众人）拉塌（燃烧着的）房屋时一齐用力的呼喊声。曳：拉。许许：拟声词，呼喊声。\n凡所应有，无所不有：凡是（在这种情况下）应该有的声音，没有没有的。\n虽：即使。\n不能指其一端：不能指明其中的（任何）一种（声音）。形容口技模拟的各种声响同时发出，交织成一片，使人来不及一一辨识。一端：一头，这里是“一种”的意思。\n口：嘴巴。\n名：作动词用，说出。\n于：在。\n是：这。\n变色：变了脸色，惊慌失措。\n离席：离开座位。\n奋袖出臂：捋起袖子，露出手臂 奋：张开、展开 出：露出。\n股：大腿。\n战战：打哆嗦；打战。\n几(jī)：几乎，差点儿。\n先走：抢先逃跑。走：跑。\n群响毕绝：各种声音全都消失了。\n毕绝：都消失了。\n撤屏：撤去屏风。\n是：这。\n奋：扬起，举起，撩起。', poem_appreciation = '一、熟读课文，根据提示，画出文中描摹音响的语句。\n\n　　设题目的在于使学生熟悉课文的主体部分，体会文中声响描写的精妙，对口技艺人的高超技艺获得丰富的感性印象。我们让学生根据提示填写描摹声响的语句，以使学生更好地理解口技艺人的艺术构思，从而真正进入口技艺人所设计的“规定情景”之中，所以填空是手段，而不是目的。要注意引导学生细心体会各种声音所表现的情景，并合理地补充一些细节，以培养学生的想象力。要求学生在完成这道题和熟悉首尾两段的基础上背诵全文。\n\n　　1．表现深夜一家四口由睡到醒、由醒入睡的过程。\n\n　　①由远而近，由外而内，由小而大，由分而合。\n\n　　遥闻深巷中犬吠……众妙毕备。\n\n　　②由大而小，由密而疏，微闻余声。\n\n　　夫齁声起……妇梦中咳嗽。\n\n　　2．表现从失火到救火的情况。\n\n　　①响声大作，由少而多。\n\n　　忽一人大呼“火起”……百千犬吠。\n\n　　②百千齐作，应有尽有。\n\n　　中间力拉崩倒之声……无所不有。\n\n　　体会课文的写作技巧，回答下列问题。\n\n　　1．找出课文中描述听众反应的语句，说说这些描述起什么作用。\n\n　　2．文中前后两次清楚地交代了极简单的道具，这对文章的结构和表现艺人的演技有什么作用？\n\n　　提示：设题目的是使学生理解侧面描写手法的作用。指导学生答题时不要孤立地讲侧面描写。例如写表演，除了要写到表演者和表演内容，往往还会自然地写到欣赏表演的人的反应，而后者就是在运用侧面描写。又如开头和结尾相照应，除了使结构保持完整而外，也具有侧面烘托、强调意图的作用。侧面描写是一种常用的手法，应有所了解，但关键在于自觉、恰当地运用。\n\n　　1答：描述听众反应的语句有：“满坐宾客无不伸颈，侧目，微笑，默叹，以为妙绝。”“宾客意少舒，稍稍正坐。”“宾客无不变色离席，奋袖出臂，两股战战，几欲先走。”这样写，层层深入，写明宾客们从尚可自持到难以自持到不能自持的过程，从侧面突出表演的效果，烘托出表演技艺的高超。\n\n　　2答：开头提到“一桌、一椅、一扇、一抚尺而已”，从内容上看，点明文章中心，极言道具之简，意在为后文表演复杂的声响做烘托、对比。结尾重现道具，则在证实、强调刚才的一切声响都是从一张嘴中发出的，从而更突出表演者技艺的高超，也具有烘托的作用。从结构上看，首尾呼应，使文章浑然一体。\n\n　　解释下列句子中的划线词。\n\n　　这些句子中的划线词，大致可分为两类：一类是古今意义不同的，如“会”（正好赶上、恰巧、正好）、“但”（只）、“闻”（听见）、“少”（稍微）、“虽”（即使）、“走”（逃跑）；二是古今用法不同的，如“宴”（举行宴会）、“乳”（喂奶）、“名”（说出）在课文中都用作动词，都用作名词。对这些容易理解错的词，应提醒学生注意。\n\n　　1．会宾客大宴\n\n　　会：适逢，正赶上，恰巧。 宴：举行宴会。\n\n　　2．但闻屏障中抚尺一下\n\n　　但：只，仅。 闻：听见。\n\n　　3．妇抚儿乳\n\n　　乳：喂奶。\n\n　　4．宾客意少舒\n\n　　少：同“稍”，稍微。\n\n　　5．人有百口，口有百舌，不能名其一处也\n\n　　名：说出。\n\n　　6．几欲先走\n\n　　走：逃跑。\n\n　　辨析下列表示时间的词语，将它们分别填在横线上。\n\n　　文言文中表示时间的词语较多，到一定阶段需要加以整理，这样才能有效地掌握它们的用法，获得牢固的记忆。这道题实际上是给学生提供一种整理的方式，还可以采用其他的整理方式。\n\n　　少顷 既而 是时 一时 未几 忽 俄而 忽然\n\n　　1．表示突然发生：忽 忽然\n\n　　2．表示同时发生：一时\n\n　　3．表示相继发生：既而\n\n　　4．表示在特定的时间内发生：是时\n\n　　5．表示过了很短时间就发生：俄而 少顷 未几', poem_tags = '初中文言文,叙事,写人,表演,艺术' WHERE poem_title = '口技' AND poem_author = '林嗣环';
UPDATE edu_poem SET poem_translation = '夜静更深，月光只照亮了人家房屋的一半，另一半隐藏在黑夜里。北斗星倾斜了，南斗星也倾斜了。\n今夜才知春天的来临，因为你听那被树叶映绿的窗纱外，唧唧的虫鸣，头一遭儿传到了屋子里来了。', poem_notes = '更深：古时计算时间，一夜分成五更。更深，夜深了。\n月色半人家：月光只照亮了人家房屋的一半，另一半隐藏在黑暗里。\n北斗：在北方天空排列成斗形的七颗亮星。\n阑干：这里指横斜的样子。\n南斗：有星六颗。在北斗星以南，形似斗，故称“南斗”。\n偏知：才知，表示出乎意料。\n新：初。新透：第一次透过。', poem_appreciation = '唐诗中，以春和月为题的不少。或咏春景而感怀，或望明月而生情思。此诗写春，不唯不从柳绿桃红之类的事物着笔，反借夜幕将这似乎最具有春天景色特点的事物遮掩起来，写月，也不细描其光影，不感叹其圆缺；而只是在夜色中调进半片月色，这样，夜色不至太浓，月色也不至太明，造成一种蒙胧而和谐的旋律。\n\n　　此诗首揭“更深”二字，为以下景色的描绘确定了基调，也给全诗笼罩一种特殊氛围。“月色半人家”是“更深”二字的具体化，接下的一句“北斗阑干南斗斜”，是“更深”于夜空的征象，两句一起造成春夜的静穆，意境深邃。月光半照，是因为月轮西斜，诗以星斗阑干为映衬，这就构成两句之间的内在关联。\n\n　　恬谧的春夜，万物的生息迁化在潜行。“今夜偏知春气暖．虫声新透绿窗纱”，正是诗人全身心地去体察大自然的契机而得到的佳句。从虫介之微而知寒暖之候，说明诗人有着深厚的乡村生活的根柢。因此。这两句非一般人所能道。没有长期乡村生活经验的人固然说不出；便是生活在乡村，也并非人人都说得出来。今夜虫鸣，究竟是第一回还是第几回，谁去注意它，这须得有心人，还应该有一颗诗心。一个“新”字，饱含对乡村生活的深情，既是说清新，又有欣悦之意。\n\n　　诗中说“春气暖”自“今夜”始，表明对节候变化十分敏感，“偏知”一语洋溢着自得之情。写隔窗听到虫声，用“透”。给人以生机勃发的力度感。窗纱的绿色，夜晚是看不出的。这绿意来自诗人内心的盎然春意。至此，我们就可以明白：诗人之所以不描写作为春天表征的鲜明的外在景观。而是借助深夜景色气氛来烘托诗的意境，就是因为这诗得之于诗人的内心。诗人是以一颗纯净的心灵体察自然界的细微变化的。诗的前二句写景物，不着一丝春的色彩．却暗中关合春意，颇具蕴藉之致。第三句的“春气暖”。结句的“虫声”，“绿窗纱”互为映发。于是春意俱足。但这声与色，仍从“意”(感觉)中来。诗人并非唯从“虫声”才知道春气已暖，“春气暖”是诗人对“今夜”的细微感觉，而“虫声”只是与其感觉冥合的一个物候。因此，诗的意蕴是深厚的。构思的新颖别致，决定于感受的独特。唐代田园诗成为一个重要流派，也不乏名家。然而。能仿佛陶诗一二者并不多见。象本诗这样深得陶体真趣的。就更为寥寥。至于说本诗有无隐微之情的寄托，于字面无证，不好去穿凿。', poem_tags = '唐诗三百首,初中古诗,春天,月亮,田园' WHERE poem_title = '月夜' AND poem_author = '刘方平';
UPDATE edu_poem SET poem_translation = '巍巍长安，雄踞三秦之地；渺渺四川，却在迢迢远方。\n你我命运何等相仿，奔波仕途，远离家乡。\n只要有知心朋友，四海之内不觉遥远。即便在天涯海角，感觉就像近邻一样。\n岔道分手，实在不用儿女情长，泪洒衣裳。', poem_notes = '少府：官名。之：到、往。蜀州：今四川崇州。\n城阙（què ）辅三秦：城阙，即城楼，指唐代京师长安城。辅，护卫。三秦，指长安城附近的关中之地，即今陕西省潼关以西一带。秦朝末年，项羽破秦，把关中分为三区，分别封给三个秦国的降将，所以称三秦。这句是倒装句，意思是京师长安三秦作保护。五津：指岷江的五个渡口白华津、万里津、江首津、涉头津、江南津。这里泛指蜀川。辅三秦：一作“俯西秦”。\n风烟望五津：“风烟”两字名词用作状语，表示行为的处所。全句意为江边因远望而显得迷茫如啼眼，是说在风烟迷茫之中，遥望蜀州。\n君：对人的尊称，相当于“您”。\n同：一作“俱”。宦（huàn）游：出外做官。\n海内：四海之内，即全国各地。古代人认为我国疆土四周环海，所以称天下为四海之内。\n天涯：天边，这里比喻极远的地方。比邻：并邻，近邻。\n无为：无须、不必。歧（qí）路：岔路。古人送行常在大路分岔处告别。\n沾巾：泪水沾湿衣服和腰带。意思是挥泪告别。', poem_appreciation = '首联属“工对”中的“地名对”，极壮阔，极精整。第一句写长安的城垣、宫阙被辽阔的三秦之地所“辅”（护持、拱卫），气势雄伟，点送别之地。第二句里的“五津”指岷江的五大渡口白华津、万里津、江首津、涉头津、江南津，泛指“蜀川”，点杜少府即将宦游之地；而“风烟”、“望”，又把相隔千里的秦、蜀两地连在一起。自长安遥望蜀川，视线为迷蒙的风烟所遮，微露伤别之意，已摄下文“离别”、“天涯”之魂。\n\n　　因首联已对仗工稳，为了避免板滞，故次联以散调承之，文情跌宕。“与君离别意”承首联写惜别之感，欲吐还吞。翻译一下，那就是：“跟你离别的意绪啊！……”那意绪怎么样，没有说；立刻改口，来了个转折，用“同是宦游人”一句加以宽解。意思是：我和你同样远离故土，宦游他乡；这次离别，只不过是客中之别，又何必感伤！\n\n　　三联推开一步，奇峰突起。从构思方面看，很可能受了曹植《赠白马王彪》“丈夫志四海，万里犹比邻；恩爱苟不亏，在远分日亲”的启发。但高度概括，自铸伟词，便成千古名句。\n\n　　尾联紧接三联，以劝慰杜少府作结。“在歧路”，点出题面上的那个“送”字。歧路者，岔路也，古人送行，常至大路分岔处分手，所以往往把临别称为“临歧”。作者在临别时劝慰杜少府说：只要彼此了解，心心相连，那么即使一在天涯，一在海角，远隔千山万水，而情感交流，不就是如比邻一样近吗？可不要在临别之时哭鼻子、抹眼泪，象一般小儿女那样。\n\n　　作品点评：南朝的著名文学家江淹在《别赋》里写了各种各样的离别，都不免使人“黯然消魂”。古代的许多送别诗，也大都表现了“黯然消魂”的情感。王勃的这一首，却一洗悲酸之态，意境开阔，音调爽朗，独标高格。是初唐四杰之一的王勃在京城长安送别一位姓杜的朋友到蜀地任县令时所作的抒情诗。朋友即将上任，诗人劝慰他不要为远别而悲伤：虽然远隔天涯，但友谊不会因为距离的遥远而淡薄，他们的心是连在一起的。虽为送别诗，但全诗却无伤感之情，诗人的胸襟开朗，语句豪放清新，委婉亲切，表现了友人间真挚深厚的友情。\n\n　　全诗结构严谨，起承转合章法井然，用朴素的语言直抒胸臆，具有很高的艺术造诣。', poem_tags = '唐诗三百首,初中古诗,友情,送别,哲理,早教古诗100首' WHERE poem_title = '送杜少府之任蜀州 / 送杜少府之任蜀川' AND poem_author = '王勃';
UPDATE edu_poem SET poem_translation = '邹忌身长五十四·寸左右，而且形象外貌光艳美丽。早晨，（邹忌）穿戴好衣帽，照了一下镜子，对他妻子说：“我和城北徐公比，谁更美呢?”他的妻子说：“您非常美，徐公怎么能比得上您呢?” 城北的徐公是齐国的最美的男子。邹忌不相信自己（比徐公美），而又问他的妾：“我和徐公相比，谁更美呢?”妾说：“徐公哪能比得上您呢?” 第二天，有客人从外面来（拜访），（邹忌）与他相坐而谈，问他：“我和徐公比，谁更美呢?”客人说：“徐公不如您美丽。” 又一天，徐公来了，邹忌仔细地看着他，自己认为不如徐公美；照着镜子里的自己，更是觉得自己与徐公相差甚远。傍晚，他躺在床上休息时想这件事，说：“我的妻子赞美我漂亮，是偏爱我；我的妾赞美我美，是害怕我；客人赞美我美，是有事情要求于我。”\n　　在这种情况下，邹忌上朝拜见齐威王，说：“我知道自己确实比不上徐公美。可是我的妻子偏爱我，我的妾害怕我，我的客人有事想要求助于我，（所以）他们都认为我比徐公美。如今齐国有方圆千里的疆土，一百二十座城池。宫中的姬妾及身边的近臣，没有一个不偏爱大王的，朝中的大臣没有一个不惧怕大王的，全国范围内的百姓没有一个不有事想求助于大王。由此看来，大王您受到的蒙蔽太严重了！”\n　　齐威王说：“你说的很好！”于是就下了命令：“大小的官吏，大臣和百姓们，能够当面批评我的过错的人，给予上等奖赏；上书直言规劝我的人，给予中等奖赏；能够在众人集聚的公共场所指责议论我的过失，并传到我耳朵里的人，给予下等奖赏。” 命令刚下达，许多大臣都来进献谏言，宫门和庭院像集市一样热闹；几个月以后，还不时地有人偶尔进谏；满一年以后，即使有人想进谏，也没有什么可说的了。燕、赵、韩、魏等国听说了这件事，都到齐国朝拜齐威王。这就是身居朝廷，不必用兵就战胜了敌国。', poem_notes = '邹忌：战国时的齐国人，曾任相国。\n讽：讽谏，用暗示，比喻之类的方法，委婉的规劝。\n齐王：即齐威王，威王。\n纳谏：接受规劝。纳，接受，接纳\n修：长，这里指身高。\n八尺：战国时一尺约合今天的七寸左右。\n昳丽：光艳美丽。\n朝服衣冠：早晨穿戴好衣帽。（服，名词作动词活用，意为穿戴，在句中作状语。）\n窥镜：照镜子。\n孰：谁，什么。\n与：和……比。\n及：比得上\n旦日：明天。这里指第二天。\n明日：即上文“旦日”的后一天。\n若：如。\n孰视之，孰：通“熟”，仔细。之：代城北徐公。\n弗如远甚：远不如。弗：不。\n又：更。\n寝：躺着。\n美我者：赞美/认为……美\n私：动词，偏爱。\n诚知：确实知道。\n皆以美于徐公：都认为（我）比徐公美。“以”的后边省去了“我”。以：认为。于：比。\n地：土地，疆域。\n方：方圆。\n宫妇：宫里的姬妾。\n左右：身边的近臣。\n四境之内：全国范围内（的人）。\n之：用于主谓之间取消句子独立性。\n蔽：形容词用作动词，指受蒙蔽。\n善：好。\n乃：于是，就。\n面刺：当面指责。面，当面，名词作状语。\n受上赏：给予，付予。通“授”\n谤讥于市朝：在公众场所议论（君王的过失）。谤：公开指责别人的过错。讥，讽喻。谤讥，在这里指“指责，议论”，没有贬意。市朝，众人集聚的公共场所。\n闻：这里是“使……听到”的意思。使动用法。\n时时而间(jiàn)进：有时候偶然进谏。间进：偶然有人进谏。间，间或，偶然，有时候。\n期（jī）年：满一年。期，满。\n朝于齐：到齐国来朝见（齐王）。\n此所谓战胜于朝廷：这就是身居朝廷，不必用兵，就战胜了敌国。\n而形貌昳（yì）丽：而，表并列关系。', poem_tags = '初中文言文,古文观止,哲理,故事' WHERE poem_title = '邹忌讽齐王纳谏' AND poem_author = '刘向 撰';
UPDATE edu_poem SET poem_translation = '山川景色的美丽，自古以来就是文人雅士共同欣赏赞叹的。巍峨的山峰耸入云端，明净的溪流清澈见底。两岸的石壁色彩斑斓，交相辉映。青葱的林木，翠绿的竹丛，四季常存。清晨的薄雾将要消散的时候，传来猿、鸟此起彼伏的鸣叫声；夕阳快要落山的时候，潜游在水中的鱼儿争相跳出水面。这里实在是人间的仙境啊。自从南朝的谢灵运以来，就再也没有人能够欣赏这种奇丽的景色了。', poem_notes = '答：回复。谢中书：即谢微（一说谢徵），字元度，陈郡阳夏（河南太康）人。曾任中书鸿胪（掌朝廷机密文书），所以称之为谢中书。书：即书信，古人的书信又叫“尺牍”或“信札”，是一种应用性文体，多记事陈情。\n山川：山河。之：的。\n共谈：共同谈赏的。\n五色交辉：这里形容石壁色彩斑斓。五色，古代以青黄黑白赤为正色，交辉，指交相辉映。\n青林：青葱的树林。翠竹：翠绿的竹子。\n四时：四季。俱：都。\n歇：消。\n乱：此起彼伏。\n夕日欲颓：太阳快要落山了。颓，坠落。\n沉鳞竞跃：潜游在水中的鱼争相跳出水面。沉鳞，潜游在水中的鱼。竞跃，竞相跳跃。\n实：确实，的确。欲界之仙都：即人间仙境。欲界，佛家语，佛教把世界分为欲界，色界、无色界。欲界是没有摆脱世俗的七情六欲的众生所处境界，即指人间。仙都，仙人生活在其中的美好世界。\n康乐：指南朝著名山水诗人谢灵运，他继承他祖父的爵位，被封为康乐公。是南朝文学家。\n复：又。与（yù）：参与，这里有欣赏领略之意。奇：指山水之奇异。', poem_appreciation = '《答谢中书书》是作者寄给谢微谈山水之美的一封信笺。全文结构巧妙，语言精奇。短短六十八字，即已集江南之美于一身，切切实实地道出了山川之自然美。\n\n　　起首之句“山川之美，古来共谈”，虽然平和却很自然，且立意高远；接着的“高峰入云，清流见底”至“夕日欲颓，沉鳞竞跃”，不足五十个字，却涉及到了山川草木，飞禽走兽。静物和动物，各自跃然在目，声响不绝于耳；形态各异，却浑然一体，鲜活如生。阅读全文，则朗朗爽口，美文丽句脱口而出，顿时吐气如兰。“实是欲界之仙都”，这归纳之句又回首返顾，使得全文前后呼应，上下贯通。就是最后简短的议论，也是言简意赅，切中文义。\n\n　　统观全文，语言精练。其一字一句，均是文章的重要组成一部分，少一字会断章离义，多一字便画蛇添足。一个景物，仅仅四字，便描绘恰当，津津有味。清清楚楚，明明白白，一个心声一句话，不多也不少。“夕日欲颓”，势在必然。“沉鳞竞跃”，变化突然。分析文章结构，亦不失巧妙，杂而不乱，结合有序。\n\n　　《答谢中书书》一文，反映了作者娱情山水的清高思想。南北朝是中国历史上最强黑暗的时期，因为各种矛盾非常尖锐，政局极度动荡，因此不少文人往往遁迹山林，旨图从自然美中去寻求精神上的慰藉和解脱，因而他们常在书信中描述山水，来表明自己之所好，并从而作为对友人的问候和安慰，这类作品虽然没有表现出多么积极进步的政治观点，但是却以其高超的艺术笔触，创作了具有相当高的美学价值的文学精品，至今仍然具有较高的鉴赏意义。', poem_tags = '初中文言文,书信,写景' WHERE poem_title = '答谢中书书' AND poem_author = '陶弘景';
UPDATE edu_poem SET poem_translation = '明朝(有一个）有特殊技艺（技艺精巧）的人名字叫王叔远。（他）能用直径一寸的木头，雕刻出宫殿、器具、人物，还有飞鸟、走兽、树木、石头，没有一件不是根据木头原来的样子模拟那些东西的形状，各有各的神情姿态。（他）曾经送给我一个用桃核雕刻成的小船，刻的是苏轼乘船游赤壁（的情形）。\n船头到船尾大约长八分多一点，大约有两个黄米粒那么高。中间高起而开敞的部分是船舱，用箬竹叶做的船篷覆盖着它。旁边有小窗，左右各四扇，一共八扇。打开窗户来看，雕刻着花纹的栏杆左右相对。关上窗户，就看到一副对联，右边刻着“山高月小，水落石出”八个字，左边刻着“清风徐来，水波不兴”八个字，用石青涂在字的凹处。\n船头坐着三个人，中间戴着高高的帽子，胡须浓密的人是苏东坡（苏轼），佛印（苏轼的好友）位于右边，鲁直(黄庭坚)位于左边。苏东坡、黄鲁直共同看着一幅书画长卷。苏东坡右手拿着卷的右端，左手轻按在鲁直的背上。鲁直左手拿着卷的左端，右手指着手卷，好像在说些什么。苏东坡露出右脚，鲁直露出左脚，（身子都）略微侧斜，他们互相靠近的两膝，都被遮蔽在手卷下边的衣褶里（意思是说，从衣褶上可以看出相并的两膝的轮廓）佛印极像佛教的弥勒菩萨，袒着胸脯，露出乳头，抬头仰望，神情和苏东坡、鲁直不相类似。佛印卧倒右膝，弯曲着右臂支撑在船上，竖着他的左膝，左臂上挂着一串念珠，靠在左膝上——念珠简直可以清清楚楚地数出来。\n船尾横放着一支船桨。船桨的左右两边各有一名撑船的人。位于右边的撑船者梳着椎形发髻，仰着脸，左手倚着一根横木上，右手扳着右脚趾头，好像在大声呼喊的样子。在左边的人右手拿着一把蒲葵扇，左手轻按着火炉，炉上有一把水壶，那个人的眼光正视着（茶炉），神色平静，好像在听茶水声音似的。\n船的背面较平，作者在上面提上自己的名字，文字是“天启壬戌秋日，虞山王毅叔远甫刻”，笔画像蚊子的脚一样细小，清清楚楚，它的颜色是黑的。还刻着一枚篆书图章，文字是：“初平山人”，字的颜色是红的。\n总计一条船，刻了五个人，八扇窗户；箬竹叶做的船篷、船桨、炉子、茶壶、手卷、念珠各一件；对联、题名和篆文，刻的字共计三十四个。可是计算它的长度，还(竟然，尚且）不满一寸。原来是挑选长而窄的桃核雕刻而成的。嘻，技艺也真灵巧奇妙啊！', poem_notes = '奇：奇特。\n曰：叫。\n以：用。\n径：直径。\n之：的。\n为：做，这里指雕刻。\n罔：无，没有。\n因：依据。\n势：样子。\n象：模似，仿照。\n具：具有。\n情：神情。\n各：各自。\n态：姿态。\n尝：曾经。\n贻：赠。\n余：我。\n盖：大概，原来是。\n泛：泛舟。\n云：句尾语气词，无意。\n约：大约。\n有奇（jī）：有，念yòu，放在整数与零数之间，意思同“又”。奇，零数。\n黍：又叫黍子，去皮后叫黄米。\n可：大约。\n许：上下。\n轩：高。\n敞：宽敞。\n为：是。\n箬篷：用箬竹叶做成的船篷。名词作状语，用箬篷。\n覆：覆盖。\n之：代词，代指“船舱”。\n开：开设。\n启：打开。\n而：表修饰。\n相望：左右相对。\n焉：语气词。\n之：代窗。\n则：就。\n徐：缓缓地。\n石青：一种矿物质的蓝色颜料，这里译为用石青。\n糁：涂染，名作动。\n峨冠：戴着高高的帽子。\n而：表并列，并且。\n髯：两腮的胡须。这里泛指胡须。\n居：位于。\n为：是。\n阅：阅读，看。\n执卷端：拿着画卷的右端。执：拿着。卷端：画卷的右端。\n抚：轻按。\n卷末：画卷的左端。\n如：好像\n语：说话。\n现：露出。\n侧：侧转。\n其：他们的。\n比：靠近。\n绝：极，非常。\n类：像。\n矫：举。\n属（zhǔ）：相类似。\n诎：同“屈“，弯曲。\n而：表并列，并且。\n倚：倚靠。\n之：代左脚。\n可：可以。\n历历：分明可数的样子。\n楫：船桨。\n舟子：撑船的人。\n状：的样子。\n其：那。\n椎髻：梳着椎形发髻，名作动词。髻，在脑上或脑后挽束起来。\n衡：通“横”，与纵相对。\n攀：扳。\n若：好像。\n视：目光。\n端：正。\n容：神情。\n寂：平静\n若：好像。\n然：的样子。\n其：那。\n夷：平\n题：题写。\n其：船的背面，船底。\n曰：刻。\n 甫：同“父”，古代男子的美称。\n钩画：笔画。\n了了：清楚明白。\n其：代字。\n墨：黑。\n用：刻着。\n篆章：篆字图章。\n丹：朱红色。\n通：总。\n为：刻。\n并：和。\n有：同“又”，连接零数和整数。\n而：表转折。\n计：计算。\n曾：尚，还。（读“zēng”，见古文字典）\n盈：满。\n简：通“拣”，挑选。\n修狭：长而窄。\n为：做，这里指雕刻。\n之：代“核舟”。\n以径寸之木：直径一寸的木头。\n罔不因势象形，各具情态：无不按照材料原来的形状刻成各种事物的形象，各有各的情态。\n技亦灵怪矣哉：技艺也真奇妙啊！矣哉：表示惊叹的语气词，相当于“了啊”。\n盖大苏泛赤壁云：刻的应当是苏轼游赤壁的情景。大苏，苏轼。人们称他和他的弟弟为“大苏”、“小苏”。泛，泛舟，坐着船在水上游览。苏轼曾游赤壁，写过《赤壁赋》、《后赤壁赋》等作品。', poem_appreciation = '生动传神的语言 　　本文语言平实、洗练，特别是摹写舟中人物情状，画相结合的写法，不只貌似，而且传神。例如：写苏东坡与黄右手执卷端，左手扶鲁直背。鲁直左手执卷末，右手指卷，如有所语。”这令人不只现左足，各微侧，其两膝相比者，各隐卷底段，又是极细腻的文笔。写佛印是“绝类弥勒，袒胸露乳，矫首昂视”，突出了这个出家人形象的特征，与读书人苏、黄神情不属。 　　这些描地感到核舟雕刻技艺的精妙，使读者深为赞叹。 　　开头，概述雕刻家王叔远的精湛技艺，点出“核舟”所雕刻的内容。第一句就介绍这位“奇巧人”及其“奇巧”的所在——在很小的木头上能雕出各色各样的景物，而且形神毕肖，第二句点明“核舟”所雕刻的内容是“大苏泛赤壁”，为下文张本。\n\n文题背景 　　本文题目末字“记”，系指文体而言。“记”这种体裁出现得很早，至唐宋而大盛。它可以记人和事，可以记山川名胜，可以记器物建筑，故又称“杂记”。在写法上大多以记叙为主，兼有议论、抒情成分。\n\n拓展：新核舟记 　　明代名篇《核舟记》把中国古代民间艺术的高深、精巧描述得真切而生动，读起来感人至深。王叔远的核舟更是吸引了一代又一代民间艺人为之神牵梦绕，不断复制和再创造。核舟这一巧技在现代又得到发扬光大，新核舟记不但在技艺上有所创新，而且在内容上更贴近了时代。欣赏新核舟记，对于深刻理解名篇《核舟记》很有帮助，同时通过欣赏实物、图片、影像等可以使读者在整体上全面读懂《核舟记》。 　　以往人们所了解的《核舟记》表现的多是古代人物，核舟“南湖红船”把写真肖像人物引入核舟创作中，写实刻画了党的一大代表，展现了“日出东方、开天辟地”的伟大创举，当为别开生面，既是古为今用，也是推陈出新，使古老的核舟艺术赋予了新的内涵。 　　2006年是中国共产党建党95周年，也是党的一大代表毛泽东逝世30周年、董必武诞辰120周年、何叔衡诞辰130周年、陈潭秋诞辰110周年、邓恩铭诞辰105周年和李达逝世40周年，因此，2006年具有特殊的纪念意义。 　　为了更好地纪念这一特殊时刻，河北省秦皇岛市的省级工艺美术大师杨洪武，用5个多月的时间精心刻制了一枚题为“南湖红船”的核舟作品。该核舟选用上好橄榄核为原料，以嘉兴南湖画舫为原型，细致入微的刻画了参加党的一大代表们，在画舫上创建中国共产党的历史瞬间。嘉兴南湖画舫长16米、宽3米，分前、中、后三舱，中共一大就是在画舫的中舱内举行的。核舟虽仅长3.9厘米、宽1.4厘米、高1.3厘米，也按画舫的行止，刻制了前中后三舱，宽敞的舱室、舱顶瓦楞线、舱窗以及桅杆等都一一展现出来。为增强艺术效果，前舱顶还精刻了党旗、后舱顶刻制了和平鸽。船舱两旁分别刻制小窗5扇，共10扇，每扇小窗都能开启。小核舟的舱顶、舱壁、小窗等都刻制了精美的花纹，把核舟装扮得富丽堂皇。船头坐4人，毛泽东坐在船头右侧，他目光睿智、慈祥坚定，风吹动着他头发，身上穿的长衫衣纹清晰可辨，手中的文件纸卷页翻，页页可数；何叔衡侧身靠近毛泽东讨论着；董必武还坐在船头左侧，手捧书籍思考着问题；李达在阅读，他还习惯地用手推了推眼镜，犹如身临其境。打开前舱两旁的小窗，临窗而坐的是陈潭秋、王尽美；坐在中舱两旁小窗前的是邓恩铭、刘仁静和李汉俊、包惠僧。船尾右侧是一位船工，正在用力摇橹；左侧是李达的夫人王会悟，她一面照料会务、烧水沏茶；一面警惕地观察着四周，为会议做好保卫工作。王会悟左手提壶、右手端杯，神态自然。壶上的花草纹理似隐似现。核舟的每一个人物，都是按照当时参加党一大的人物肖像写真刻制的，人物虽不足2毫米，但都生动传神，栩栩如生。核舟船底刻一大党纲98字，题款7字，共105字。字是按竖式书写阴刻的，填成黑色，笔画细如毫丝，一行一行的小字好似船行时荡漾起的涟漪。此外，为真实再现南湖画舫的全面，在核舟“红船”后面也拖一小舟。小舟长2.3厘米，高1.1厘米，宽1.0厘米。舟顶分为两层，箬篷顶周边雕刻着精美的文饰，两侧透雕的篷壁玲珑剔透、精巧可人。小舟底部刻的是一大闭幕时代表们呼的口号：“共产党万岁！第三国际万岁！共产主义——人类的解放者万岁！”共23个字。大舟与小舟之间用一条链环联接，也是用核材精刻而成的。 　　整个“南湖红船”共刻核舟2、人物12人、小窗10扇、舱室4、壶2、杯皿2、书籍文件5、橹、炉、小桌各1、链环1条、文字128字，此外12人中有5人还佩带了眼镜，均都一一俱足。', poem_tags = '初中文言文,咏物,赞美,技艺' WHERE poem_title = '核舟记' AND poem_author = '魏学洢';
UPDATE edu_poem SET poem_translation = '一年一度的秋风，又吹到了洛阳城中，身居洛阳城内的游子，不知家乡的亲人怎么样了；写封家书问候平安，要说的话太多了，又不知从何说起。\n信写好了，又担心匆匆中没有把自己想要说的话写完；当捎信人出发时，又拆开信封，再还给他。', poem_notes = '⑴意万重：极言心思之多；\n⑵复恐：又恐怕；\n⑶行人：指捎信的人；\n⑷临发：将出发；\n⑸开封：拆开已经封好的家书。', poem_appreciation = '这是乡愁诗。通过叙述写信前后的心情，表达乡愁之深。第一句交代“作家书”的原因（“见秋风”），以下三句是描写作书前、作书后的心理活动。作书前是“意万重”，作书后是“复恐说不尽”。“临发开封”这个细节把“复恐说不尽”的心态表现得栩栩如生，意形相融。写的是人人意中常有之事，却非人人所能道出。作客他乡，见秋风而思故里，托便人捎信。临走时怕遗漏了什么，又连忙打开看了几遍。事本子平，而一经入诗，特别是一经张籍这样的高手入诗，便臻妙境。这在诗坛上并不是常有的。 当然以家书为题材的作品，在唐诗中也不乏佳作。像岑参的《逢入京使》：“马上相逢无纸笔，凭君传语报平安。”写作者戎马倥偬，路遇使者，托传口信以慰家人。杜甫的《春望》：“烽火连三月，家书抵万金。”写作者身陷安禄山占领下的长安，不知战乱中的家人是否安吉，切盼来书以慰远情。他们都用独特的技巧表达了思家的心情。这首诗与众不同的是寄深沉于浅淡，寓曲折于平缓，乍看起来，寥寥数语，细细吟味，却有无穷意味。\n\n　　王安石《题张司业》诗说：“看似寻常最奇崛，成如容易却艰辛。”颇能道出这首诗的艺术风格和创作甘苦。诗以秋风起兴，这是自《诗经》以来常用的手法。秋风一起，北雁南飞，他乡羁旅，易触归思。例如刘禹锡的《秋风引》就曾说：“何处秋风至，萧萧送雁群。朝来入庭树，孤客最先闻。”我们再来看看诗人的历史，原来他本籍吴中（今江苏苏州），这又使人想起晋人张翰的故事。据《晋书·张翰传》说：“因见秋风起，乃思吴中菰菜、莼羹、鲈鱼脍，曰：‘人生贵得适志，何能羁宦数千里以要名爵乎！’遂命驾而归。”张籍与张翰异代同里，且俱宦游北方。张翰因预测到齐王司马冏即将作乱，知机引退，张籍未必有什么政治上的原因，但在见秋风而思故乡这一点上，却极其相似。他虽不能像张翰那样马上“命驾而归”，但却把一腔思乡之情倾泻在纸上。这种感物缘情的创作冲动，虽然用的是传统的手法“起兴”，但其中包括如许丰富的内涵，不能不是此诗的一个特色。\n\n　　“欲作家书意万重”，其中的“欲”字紧承“见秋风”。原来诗人的心情是平静的，像一泓清水。秋风乍起，吹起他感情上的阵阵涟漪。行文顺畅自如，一气流贯，然而句末“意万重”三字，忽又来一个逆折，犹如书法上的无垂不缩。因此这里诗人的感情并未顺流而下，而是向更深的地方去开掘。这种手法，看似寻常，实极高超。我们细玩诗意：诗人因见秋风而生乡思，于是欲作家书，可是千言万语，又不知从何写起。“意万重”，乃是以虚带实。刘禹锡《视刀环歌》云：“今朝两相视，脉脉万重心。”“万重心”、“万重意”，俱是极言思想感情的复杂。其中究竟有多少心意，每一个有生活经验的读者，都能体会得到。因为是“意万重”，这家书怎么写呢？写了没有？作者没有明言，让读者去想象，这就叫做含蓄不尽，耐人寻味。\n\n　　尽管“意万重”，无从下笔，但就文意看，家书还是写了，问题在于匆匆着笔，意犹未尽。“匆匆”二字，生动如画，既写了自己一方，也反映出捎信者一方。联系下文来看，那个捎信人是在行期在即时遇到的：也许就要上马、上船，即便不像岑参与入京使“马上相逢”那样急迫，总还是行色匆匆不能久停的。由于捎信人是这样行色匆匆，写信人不得不匆匆落笔。由于匆匆落笔，万重心意一下子很难表达清楚。在这种符合逻辑的描绘之中，诗人的急遽之情，匆忙之色，栩栩然如在目前。“说不尽”三字，也与上文“意万重”紧相呼应，由于“意万重”，所以才“说不尽”。而“意万重”也与“见秋风”引起的乡思相关联。黄叔灿《唐诗笺注》说：“首句羁人摇落之意已概见，正家书所说不尽者。‘行人临发又开封’，妙更形容得出。试思如此下半首如何领起，便知首句之难落笔矣。”说明下半首的起头与全诗的起句，环环紧扣，首尾相应。结句更是造语入妙，写情入微，可称一篇之警策。近人俞陛云评论说：“已作家书，而长言不尽，临发开封，极言其怀乡之切。”又说：“此类之诗，皆至性语也。”（《诗境浅说续编》）所谓“至性语”，就是说写出了最真挚的人类共有的感情，而且达于极致。在结构上，上句说“匆匆说不尽”，下句说“临发又开封”，渲染足了“匆匆”的气氛。', poem_tags = '小学古诗,秋天,思乡' WHERE poem_title = '秋思' AND poem_author = '张籍';
UPDATE edu_poem SET poem_translation = '在杨花落完，子规啼鸣的时候，听说你路过五溪。我把我忧愁的心思寄托给明月，希望能随着风一直陪着你到夜郎以西。', poem_notes = '王昌龄：唐代诗人，天宝（唐玄宗年号，742～756）年间被贬为龙标县尉。左迁：贬谪，降职。古人尊右卑左，因此把降职称为左迁。龙标：古地名，唐朝置县，今湖南省黔阳县。\n杨花：柳絮。子规：即杜鹃鸟，相传其啼声哀婉凄切。杨花落尽：一作“扬州花落”。\n龙标：诗中指王昌龄，古人常用官职或任官之地的州县名来称呼一个人。五溪：是武溪、巫溪、酉溪、沅溪、辰溪的总称，在今湖南省西部。\n与：给。\n随风：一作“随君”。夜郎：汉代中国西南地区少数民族曾在今贵州西部、北部和云南东北部及四川南部部分地区建立过政权，称为夜郎。唐代在今贵州桐梓和湖南沅陵等地设过夜郎县。这里指湖南的夜郎（在今新晃侗族自治县境，与黔阳邻近）。李白当时在东南，所以说“随风直到夜郎西”。', poem_appreciation = '《新唐书.文艺传》载王昌龄左迁龙标尉（古人尚右，故称贬官为左迁），是因为“不护细行”，也就是说，他的得罪贬官，并不是由于什么重大问题，而只是由于生活小节不够检点。在《芙蓉楼送辛渐》中，王昌龄也对他的好友说：“洛阳亲友如相问，一片冰心在玉壶。”即沿用鲍照《白头吟》中“清如玉壶冰”的比喻，来表明自己的纯洁无辜。李白在听到他不幸的遭遇以后，写了这一首充满同情和关切的诗篇，从远道寄给他，是完全可以理解的。\n\n　　首句写景兼点时令。于景物独取漂泊无定的杨花、叫着“不如归去”的子规，即含有飘零之感、离别之恨在内，切合当时情事，也就融情入景。 因首句已于景中见情，所以次句便直叙其事。“闻道”，表示惊惜。“过五溪”，见迁谪之荒远，道路之艰难。不着悲痛之语，而悲痛之意自见。\n\n　　后两句抒情。人隔两地，难以相从，而月照中天，千里可共，所以要将自己的愁心寄与明月，随风飘到夜郎。这两句诗所表现的意境，已见于前此的一些名作中。如谢庄《月赋》：“美人迈兮音尘缺，隔千里兮共明月。临风叹兮将焉歇，川路长兮不可越。”曹植《杂诗》：“愿为南流景，驰光见我君。”张若虚《春江花月夜》：“此时相望不相闻，愿逐月华流照君。”都与之相近。而细加分析，则两句之中，又有三层意思，一是说自己心中充满了愁思，无可告诉，无人理解，只有将这种愁心托之于明月；二是说惟有明月分照两地，自己和朋友都能看见她；三是说，因此，也只有依靠她才能将愁心寄与，别无它法。\n\n　　诗人李白通过丰富的想象，用男女情爱的方式以抒写志同道合的友情，给予抽象的“愁心”以物的属性，它竟会随风逐月到夜郎西。本来无知无情的明月，竟变成了一个了解自己，富于同情的知心人，她能够而且愿意接受自己的要求，将自己对朋友的怀念和同情带到辽远的夜郎之西，交给那不幸的迁谪者。\n\n　　这种将自己的感情赋予客观事物，使之同样具有感情，也就是使之人格化，乃是形象思维所形成的巨大的特点之一和优点之一。当诗人们需要表现强烈或深厚的情感时，常常用这样一种手段来获得预期的效果。', poem_tags = '初中古诗,写景,思乡,友情' WHERE poem_title = '闻王昌龄左迁龙标遥有此寄' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '巴山楚水凄凉之地，二十三年默默谪居。\n回来物是人非，我像烂柯之人，只能吹笛赋诗，空自惆怅不已。\n沉舟侧畔，千帆竞发；病树前头，万木逢春。\n今日听你高歌一曲，暂借杯酒振作精神。', poem_notes = '酬：答谢，酬答，这里是指以诗相答的意思。用诗歌赠答。\n乐天：指白居易，字乐天。\n见赠：送给（我）。\n巴山楚水：指四川、湖南、湖北一带。古时四川东部属于巴国，湖南北部和湖北等地属于楚国。刘禹锡被贬后，迁徙于朗州、连州、夔州、和州等边远地区，这里用“巴山楚水”泛指这些地方。\n二十三年：从唐顺宗永贞元年（805年）刘禹锡被贬为连州刺史，至宝历二年（826）冬应召，约22年。因贬地离京遥远，实际上到第二年才能回到京城，所以说23年。\n弃置身：指遭受贬谪的诗人自己。置：放置。弃置：贬谪（zhé）。\n怀旧：怀念故友。\n吟：吟唱。\n闻笛赋：指西晋向秀的《思旧赋》。三国曹魏末年，向秀的朋友嵇康 、吕安因不满司马氏篡权而被杀害。后来，向秀经过嵇康、吕安的旧居，听到邻人吹笛，不禁悲从中来，于是作《思旧赋》。 序文中说：自己经过嵇康旧居，因写此赋追念他。刘禹锡借用这个典故怀念已死去的王叔文、柳宗元等人。\n到：到达。\n翻似：倒好像。翻：副词，反而。\n烂柯人：指晋人王质。相传晋人王质上山砍柴，看见两个童子下棋，就停下观看。等棋局终了，手中的斧柄（柯）已经朽烂。回到村里，才知道已过了一百年。同代人都已经亡故。作者以此典故表达自己遭贬23年的感慨。刘禹锡也借这个故事表达世事沧桑，人事全非，暮年返乡恍如隔世的心情。 \n沉舟：这是诗人以沉舟、病树自比。\n侧畔：旁边。\n歌一曲：指白居易的《醉赠刘二十八使君》。\n长（zhǎng）精神：振作精神。长：增长，振作。', poem_appreciation = '《酬乐天扬州初逢席上见赠》是显示自己对世事变迁和仕宦升沉的豁达襟怀，表现了诗人的坚定信念和乐观精神，同时又暗含哲理，表明新事物必将取代旧事物。\n\n　　刘禹锡这首酬答诗，接过白居易诗的话头，着重抒写这特定环境中自己的感情。白的赠诗中，白居易对刘禹锡的遭遇无限感慨，最后两句说：“亦知合被才名折，二十三年折太多。”一方面感叹刘禹锡的不幸命运，另一方面又称赞了刘禹锡的才气与名望。这两句诗，在同情之中又包含着赞美，显得十分委婉。因为白居易在诗的末尾说到二十三年，所以刘禹锡在诗的开头就接着说：“巴山楚水凄凉地，二十三年弃置身。”自己谪居在巴山楚水这荒凉的地区，算来已经二十三年了。一来一往，显出朋友之间推心置腹的亲切关系。\n\n　　接着，诗人很自然地发出感慨道：“怀旧空吟闻笛赋，到乡翻似烂柯人。”说自己在外二十三年，如今回来，许多老朋友都已去世，只能徒然地吟诵“闻笛赋”表示悼念而已。此番回来恍如隔世，觉得人事全非，不再是旧日的光景了。后一句用王质烂柯的典故，既暗示了自己贬谪时间的长久，又表现了世态的变迁，以及回归之后生疏而怅惘的心情，涵义十分丰富。\n\n　　白居易的赠诗中有“举眼风光长寂寞，满朝官职独蹉跎”这样两句，意思是说同辈的人都升迁了，只有你在荒凉的地方寂寞地虚度了年华，颇为刘禹锡抱不平。对此，刘禹锡在酬诗中写道：“沉舟侧畔千帆过，病树前头万木春。”刘禹锡以沉舟、病树比喻自己，固然感到惆怅，却又相当达观。沉舟侧畔，有千帆竞发；病树前头，正万木皆春。他从白诗中翻出这二句，反而劝慰白居易不必为自己的寂寞、蹉跎而忧伤，对世事的变迁和仕宦的升沉，表现出豁达的襟怀。这两句诗意又和白诗“命压人头不奈何”、“亦知合被才名折”相呼应，但其思想境界要比白诗高，意义也深刻得多了。二十三年的贬谪生活，并没有使他消沉颓唐。正像他在另外的诗里所写的：“莫道桑榆晚，为霞犹满天。”他这棵病树仍然要重添精神，迎上春光。因为这两句诗形象生动，至今仍常常被人引用，并赋予它以新的意义，说明新事物必将取代旧事物。\n\n　　正因为“沉舟”这一联诗突然振起，一变前面伤感低沉的情调，尾联便顺势而下，写道：“今日听君歌一曲，暂凭杯酒长精神。”点明了酬答白居易的题意。诗人也没有一味消沉下去，他笔锋一转，又相互劝慰，相互鼓励了。他对生活并未完全丧失信心。诗中虽然感慨很深，但读来给人的感受并不是消沉，相反却是振奋。\n\n　　总体来说，诗的首联以伤感低沉的情调，回顾了诗人的贬谪生活。颔联，借用典故暗示诗人被贬时间之长，表达了世态的变迁以及回归以后人事生疏而怅惘的心情。颈联是全诗感情升华之处，也是传诵千古的警句。诗人把自己比作“沉舟”和“病树”，意思是自己虽屡遭贬低，新人辈出，却也令人欣慰，表现出他豁达的胸襟。尾联顺势点明了酬答的题意，表达了诗人重新投入生活的意愿及坚韧不拔的意志。', poem_tags = '初中古诗,贬谪,励志,哲理,早教古诗100首' WHERE poem_title = '酬乐天扬州初逢席上见赠' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '茫茫的海上升起一轮明月，此时你我都在天涯共相望。\n有情之人都怨恨月夜漫长，整夜里不眠而把亲人怀想。\n熄灭蜡烛怜爱这满屋月光，我披衣徘徊深感夜露寒凉。\n不能把美好的月色捧给你，只望能够与你相见在梦乡。', poem_notes = '怀远：怀念远方的亲人。\n首二句：辽阔无边的大海上升起一轮明月，使人想起了远在天涯海角的亲友，此时此刻也该是望着同一轮明月。谢庄《月赋》：“隔千里兮共明月”。\n情人：多情的人，指作者自己；一说指亲人。遥夜：长夜。怨遥夜：因离别而幽怨失眠，以至抱怨夜长。竟夕：终宵，即一整夜。\n怜：爱。滋：湿润。怜光满：爱惜满屋的月光。这里的灭烛怜光满，很显然根据上下文，这应该是个月明的时候，应该在农历十五左右。此时月光敞亮，就是在现在今天，熄掉油灯仍然感受得到月光的霞美。当一个人静静的在屋子里面享受月光，就有种“怜”的感觉，这只是一种发自内心的感受而已，读诗读人，应该理解当时诗人的心理才能读懂诗词。光满自然就是月光照射充盈的样子，“满”描写了一个状态，应该是月光直射到屋内。\n末两句：月华虽好但是不能相赠，不如回入梦乡觅取佳期。陆机《拟明月何皎皎》：“照之有余辉，揽之不盈手。”盈手：双手捧满之意。盈：满（指那种满荡荡的充盈的状态）。', poem_appreciation = '《望月怀远》是一首月夜怀念远人的诗，是作者在离乡时，望月而思念远方亲人而写的。起句“海上生明月”意境雄浑阔大，是千古佳句。它和谢灵运的“池塘生春草”，鲍照的“明月照积雪”，谢朓的“大江流日夜”以及作者自己的“孤鸿海上来”等名句一样，看起来平淡无奇，没有一个奇特的字眼，没有一分点染的色彩，脱口而出，却自然具有一种高华浑融的气象。这一句完全是景，点明题中的“望月”。第二句“天涯共此时”，即由景入情，转入“怀远”。前乎此的有谢庄《月赋》中的“隔千里兮共明月”，后乎此的有苏轼《水调歌头·明月几时有》词中的“但愿人长久，千里共婵娟”，都是写月的名句，其旨意也大抵相同，但由于各人以不同的表现方法，表现在不同的体裁中，谢庄是赋，苏轼是词，张九龄是诗，相体裁衣，各极其妙。这两句把诗题的情景，一起就全部收摄，却又毫不费力，仍是张九龄作古诗时浑成自然的风格。\n\n　　从月出东斗直到月落鸟啼，是一段很长的时间，诗中说是“竟夕”，亦即通宵。这通宵的月色对一般人来说，可以说是漠不相关的，而远隔天涯的一对情人，因为对月相思而久不能寐，只觉得长夜漫漫，故而落出一个“怨”字。三四两句，就以怨字为中心，以“情人”与“相思”呼应，以“遥夜”与“竟夕”呼应，上承起首两句，一气呵成。这两句采用流水对，自然流畅，具有古诗气韵。\n\n　　竟夕相思不能入睡，或许是怪屋里烛光太耀眼，于是灭烛，披衣步出门庭，光线还是那么明亮。这天涯共对的一轮明月竟是这样撩人心绪，使人见到它那姣好圆满的光华，更难以入睡。夜已深了，气候更凉一些了，露水也沾湿了身上的衣裳。这里的“滋”字不仅是润湿，而且含滋生不已的意思。“露滋”二字写尽了“遥夜”、“竟夕”的精神。“灭烛怜光满，披衣觉露滋”，两句细巧地写出了深夜对月不眠的实情实景。\n\n　　相思不眠之际，没有什么可以相赠，只有满手的月光。诗人说：“这月光饱含我满腔的心意，可是又怎么赠送给你呢？还是睡罢！睡了也许能在梦中与你欢聚。”“不堪”两句，构思奇妙，意境幽清，没有深挚情感和切身体会，恐怕是写不出来的。这里诗人暗用晋陆机“照之有余辉，揽之不盈手”两句诗意，翻古为新，悠悠托出不尽情思。诗至此戛然而止，只觉余韵袅袅，令人回味不已。', poem_tags = '唐诗三百首,月亮,中秋节,思乡,思念,早教古诗100首' WHERE poem_title = '望月怀远 / 望月怀古' AND poem_author = '张九龄';
UPDATE edu_poem SET poem_translation = '居住在人世间，却没有车马的喧嚣。\n问我为何能如此，只要心志高远，自然就会觉得所处地方僻静了。\n在东篱之下采摘菊花，悠然间，那远处的南山映入眼帘。\n山中的气息与傍晚的景色十分好，有飞鸟，结着伴儿归来。\n这里面蕴含着人生的真正意义，想要辨识，却不知怎样表达。', poem_notes = '结庐：建造住宅，这里指居住的意思。\n车马喧：指世俗交往的喧扰。\n君：指作者自己。\n何能尔：为什么能这样。 尔：如此、这样。\n悠然：自得的样子。\n见：看见（读jiàn），动词。\n南山：泛指山峰，一说指庐山。\n日夕：傍晚。相与：相交，结伴。\n相与还：结伴而归。', poem_appreciation = '这首诗的意境可分为两层，前四句为一层，写诗人摆脱世俗烦恼后的感受。后六句为一层，写南山的美好晚景和诗人从中获得的无限乐趣。表现了诗人热爱田园生活的真情和高洁人格。\n\n　　“结庐在人境，而无车马喧”诗起首作者言自己虽然居住在人世间，但并无世俗的交往来打扰。为何处人境而无车马喧的烦恼？因为“心远地自偏”，只要内心能远远地摆脱世俗的束缚，那么即使处于喧闹的环境里，也如同居于僻静之地。陶渊明早岁满怀建功立业的理想，几度出仕正是为了要实现匡时济世的抱负。但当他看到“真风告逝，大为斯兴”（《感士不遇赋》），官场风波险恶，世俗伪诈污蚀，整个社会腐败黑暗，于是便选择了洁身自好、守道固穷的道路，隐居田园，躬耕自资。“结庐在人境”四句，就是写他精神上在摆脱了世俗环境的干扰之后所产生的感受。所谓“心远”，即心不念名利之场，情不系权贵之门，绝进弃世，超尘脱俗。由于此四句托意高妙，寄情深远，因此前人激赏其“词彩精拔”。\n\n　　“问君何能尔？心远地自偏” 中的“心远”是远离官场，更进一步说，是远离尘俗，超凡脱俗。排斥了社会公认的价值尺度，探询作者在什么地方建立人生的基点，这就牵涉到陶渊明的哲学思想。这种哲学可以称为“自然哲学”，它既包含自耕自食、俭朴寡欲的生活方式，又深化为人的生命与自然的统一和谐。在陶渊明看来，人不仅是在社会、在人与人的关系中存在的，而且，甚至更重要的，每一个个体生命作为独立的精神主体，都直接面对整个自然和宇宙而存在。\n\n　　这些道理，如果直接写出来，诗就变成论文了。所以作者只是把哲理寄寓在形象之中。诗人在自己的庭园中随意地采摘菊花，偶然间抬起头来，目光恰与南山相会。“悠然见南山”，按古汉语法则，既可解为“悠然地见到南山”，亦可解为“见到悠然的南山”。所以，这“悠然”不仅属于人，也属于山，人闲逸而自在，山静穆而高远。在那一刻，似乎有共同的旋律从人心和山峰中一起奏出，融为一支轻盈的乐曲。\n\n　　“采菊东篱下，悠然见南山”中“悠然”写出了作者那种恬淡闲适、对生活无所求的心境。“采菊”这一动作不是一般的动作，它包含着诗人超脱尘世，热爱自然的情趣。将“见”改为“望”不好。“见”字表现了诗人看山不是有意之为，而是采菊时，无意间，山入眼帘。\n\n　　见南山之物有：日暮的岚气，若有若无，浮绕于峰际；成群的鸟儿，结伴而飞，归向山林。这一切当然是很美的。但这也不是单纯的景物描写。在陶渊明的诗文中，读者常可以看到类似的句子：“云无心以出岫，鸟倦飞而知还”（《归去来辞》）；“卉木繁荣，和风清穆”（《劝农》）等等，不胜枚举。这都是表现自然的运动，因其无意志目的、无外求，所以平静、充实、完美。人既然是自然的一部分，也应该具有自然的本性，在整个自然运动中完成其个体生命。这就是人与自然的和谐统一。\n\n　　“山气日夕佳，飞鸟相与还”这两句是景物描写。这时我们隐隐可知诗人不光在勉励自己“还”，含蓄寄托了与山林为伍的情意，还在规劝其他人；两句虽是写景，实是抒情悟理。\n\n　　“此中有真意，欲辨已忘言。”诗末两句，诗人言自己的从大自然的美景中领悟到了人生的意趣，表露了纯洁自然的恬淡心情。诗里的“此中”，我们可以理解为此时此地（秋夕篱边），也可理解为整个田园生活。所谓“忘言”，实是说恬美安闲的田园生活才是自己真正的人生，而这种人生的乐趣，只能意会，不可言传，也无需叙说。这充分体现了诗人安贫乐贱、励志守节的高尚品德。 这两句说的是这里边有人生的真义，想辨别出来，却忘了怎样用语言表达。“忘言”通俗地说，就是不知道用什么语言来表达，只可意会，不可言传。“至情言语即无声”，这里强调一个“真”字，指出辞官归隐乃是人生的真谛。\n\n　　这首诗也是陶诗艺术风格的一个典范代表。它除了具有陶诗的一般特色之外，更富于理趣，诗句更流畅，语气更自然，情貌更亲切。', poem_tags = '古诗三百首,初中古诗,高中古诗,闲适,生活,理想,哲理' WHERE poem_title = '饮酒·其五' AND poem_author = '陶渊明';
UPDATE edu_poem SET poem_translation = '唉呀呀！多么高峻伟岸！\n蜀道真太难攀登，简直难于上青天。\n传说中蚕丛和鱼凫建立了蜀国，开国的年代实在久远无法详谈。\n自从那时至今约有四万八千年，秦蜀被秦岭所阻从不沟通往返。\n西边太白山有飞鸟能过的小道。从那小路走可横渡峨眉山顶端。\n山崩地裂蜀国五壮士被压死了，两地才有天梯栈道开始相通连。\n上有挡住太阳神六龙车的山巅，下有激浪排空迂回曲折的大川。\n善于高飞的黄鹤尚且无法飞过，即使猢狲要想翻过也愁于攀援。\n青泥岭多么曲折绕着山峦盘旋，百步之内萦绕岩峦转九个弯弯。\n屏住呼吸仰头过参井皆可触摸，用手抚胸惊恐不已徒长吁短叹。\n好朋友呵请问你西游何时回还？\n可怕的岩山栈道实在难以登攀！\n只见那悲鸟在古树上哀鸣啼叫；雄雌相随飞翔在原始森林之间。\n月夜听到的是杜鹃悲惨的啼声，令人愁思绵绵呵这荒荡的空山！\n蜀道真难走呵简直难于上青天，叫人听到这些怎么不脸色突变？\n山峰座座相连离天还不到一尺；枯松老枝倒挂倚贴在绝壁之间。\n漩涡飞转瀑布飞泻争相喧闹着；水石相击转动像万壑鸣雷一般。\n那去处恶劣艰险到了这种地步；\n唉呀呀你这个远方而来的客人，为了什么而来到这险要的地方？\n剑阁那地方崇峻巍峨高入云端，只要一人把守千军万马难攻占。\n驻守的官员若不是自己的近亲；难免要变为豺狼踞此为非造反。\n清晨你要提心吊胆地躲避猛虎；傍晚你要警觉防范长蛇的灾难。\n豺狼虎豹磨牙吮血真叫人不安；毒蛇猛兽杀人如麻即令你胆寒。\n锦官城虽然说是个快乐的所在；如此险恶还不如早早地把家还。\n蜀道太难走呵简直难于上青天；侧身西望令人不免感慨与长叹！', poem_notes = '《蜀道难》：古乐府题，属《相和歌·瑟调曲》。\n噫吁嚱：惊叹声，蜀方言，表示惊讶的声音。宋庠《宋景文公笔记》卷上：“蜀人见物惊异，辄曰‘噫吁嚱’。”\n蚕丛、鱼凫：传说中古蜀国两位国王的名字。何茫然：难以考证。何：多么。茫然：渺茫遥远的样子。指古史传说悠远难详，茫昧杳然。据西汉扬雄巜蜀本王纪>记载：“蜀王之先，名蚕丛、柏灌、鱼凫，蒲泽、开明。……从开明上至蚕丛，积三万四千岁。“\n尔来：从那时以来。四万八千岁：极言时间之漫长，夸张而大约言之。秦塞：秦的关塞，指秦地。秦地四周有山川险阻，故称“四塞之地“。通人烟：人员往来。\n西当：西对。当：对着，向着。太白：太白山，又名太乙山，在长安西（今陕西眉县、太白县一带）。鸟道：指连绵高山间的低缺处，只有鸟能飞过，人迹所不能至。横绝：横越。峨眉巅：峨眉顶峰。\n摧：倒塌。天梯：非常陡峭的山路。石栈：栈道。\n高标：指蜀山中可作一方之标识的最高峰。 冲波：水流冲击腾起的波浪，这里指激流。逆折：水流回旋。回川：有漩涡的河流。\n黄鹤：黄鹄（Hú），善飞的大鸟。尚：尚且。得：能。猿猱（náo）：蜀山中最善攀援的猴类。\n青泥：青泥岭，在今甘肃徽县南，陕西略阳县北。盘盘：曲折回旋的样子。百步九折：百步之内拐九道弯。萦：盘绕。岩峦：山峰。\n扪参历井：参(shēn)、井是二星宿名。古人把天上的星宿分别指配于地上的州国，叫做“分野”，以便通过观察天象来占卜地上所配州国的吉凶。参星为蜀之分野，井星为秦之分野。扪(mén)：用手摸。历：经过。胁息：屏气不敢呼吸。膺：胸。坐：徒，空。\n君：入蜀的友人。畏途：可怕的路途。巉岩：险恶陡峭的山壁。\n但见：只听见。号古木：在古树木中大声啼鸣。从：跟随。\n子规：即杜鹃鸟，蜀地最多，鸣声悲哀，若云“不如归去”。\n凋朱颜：红颜带忧色，如花凋谢。凋，使动用法，使.....凋谢，这里指脸色由红润变成铁青。\n去：距离。盈：满。\n飞湍（tuān）：飞奔而下的急流。喧豗（huī）：喧闹声，这里指急流和瀑布发出的巨大响声。砯（pīng）崖：水撞石之声。砯，水冲击石壁发出的响声，这里作动词用，冲击的意思。转，使滚动。 壑：山谷。\n嗟：感叹声。尔：你。胡为：为什么。来：指入蜀。\n剑阁：又名剑门关，在四川剑阁县北，是大、小剑山之间的一条栈道，长约三十余里。峥嵘、崔嵬，都是形容山势高大雄峻的样子。一夫：一人。当关：守关。莫开：不能打开。\n所守：指把守关口的人。或匪亲：倘若不是可信赖的人。匪，同“非”。\n朝：早上。吮：吸。\n锦城：成都古代以产棉闻名，朝廷曾经设官于此，专收棉织品，故称锦城或锦官城。今四川成都市。\n咨嗟：叹息。', poem_appreciation = '整体评析 　　这首诗是袭用乐府旧题，意在送友人入蜀。诗人以浪漫主义的手法，展开丰富的想象，艺术地再现了蜀道峥嵘，突兀，强悍、崎岖等奇丽惊险和不可凌越的磅礴气势，借以歌咏蜀地山川的壮秀，显示出祖国山河的雄伟壮丽。\n\n　　至于本诗是否有更深的寓意，历代有各种不同看法。然而就诗论诗，不一定强析有寓意。但从诗中，“所守或匪亲，化为狼与豺”看，却是在写蜀地山川峻美的同时，告诫当局，蜀地险要，应好好用人防守。\n\n　　诗采用律体与散文间杂，文句参差，笔意纵横，豪放洒脱。全诗感情强烈，一唱三叹，回环反复，读来令人心潮激荡。\n\n整体把握 　　这首诗大约是天宝（唐玄宗年后，742～756）初年，李白第一次到长安时写的。《蜀道难》是他袭用乐府古题，展开丰富的想象，着力描绘了秦蜀道路上奇丽惊险的山川，并从中透露了对社会的某些忧虑与关切。\n\n　　诗人大体按照由古及今，自秦入蜀的线索，抓住各处山水特点来描写，以展示蜀道之难。\n\n　　从“噫吁嚱”到“然后天梯石栈相钩连”为一个段落。一开篇就极言蜀道之难，以感情强烈的咏叹点出主题，为全诗奠定了雄放的基调。以下随着感情的起伏和自然场景的变化，“蜀道之难，难于上青天”的咏叹反复出现，像一首乐曲的主旋律一样激荡着读者的心弦。\n\n　　说蜀道的难行比上天还难，这是因为自古以来秦、蜀之间被高山峻岭阻挡，由秦入蜀，太白峰首当其冲，只有高飞的鸟儿能从低缺处飞过。太白峰在秦都咸阳西南，是关中一带的最高峰。民谚云：“武公太白，去天三百。”诗人以夸张的笔墨写出了历史上不可逾越的险阻，并融汇了五丁开山的神话，点染了神奇色彩，犹如一部乐章的前奏，具有引人入胜的妙用。下面即着力刻画蜀道的高危难行了。\n\n　　从“上有六龙回日之高标”至“使人听此凋朱颜”为又一段落。这一段极写山势的高危，山高写得愈充分，愈可见路之难行。你看那突兀而立的高山，高标接天，挡住了太阳神的运行；山下则是冲波激浪、曲折回旋的河川。诗人不但把夸张和神话融为一体，直写山高，而且衬以“回川”之险。唯其水险，更见山势的高危。诗人意犹未足，又借黄鹤与猿猱来反衬。山高得连千里翱翔的黄鹤也不得飞度，轻疾敏捷的猿猴也愁于攀援，不言而喻，人行走就难上加难了。以上用虚写手法层层映衬，下面再具体描写青泥岭的难行。\n\n　　青泥岭，“悬崖万仞，山多云雨”（《元和郡县志》），为唐代入蜀要道。诗人着重就其峰路的萦回和山势的峻危来表现人行其上的艰难情状和畏惧心理，捕捉了在岭上曲折盘桓、手扪星辰、呼吸紧张、抚胸长叹等细节动作加以摹写，寥寥数语，便把行人艰难的步履、惶悚的神情，绘声绘色地刻画出来，困危之状如在目前。\n\n　　至此蜀道的难行似乎写到了极处。但诗人笔锋一转，借“问君”引出旅愁，以忧切低昂的旋律，把读者带进一个古木荒凉、鸟声悲凄的境界。杜鹃鸟空谷传响，充满哀愁，使人闻声失色，更觉蜀道之难。诗人借景抒情，用“悲鸟号古木”、“子规啼夜月”等感情色彩浓厚的自然景观，渲染了旅愁和蜀道上空寂苍凉的环境气氛，有力地烘托了蜀道之难。\n\n　　然而，逶迤千里的蜀道，还有更为奇险的风光。自“连峰去天不盈尺”至全篇结束，主要从山川之险来揭示蜀道之难，着力渲染惊险的气氛。如果说“连峰去天不盈尺”是夸饰山峰之高，“枯松倒挂倚绝壁”则是衬托绝壁之险。\n\n　　诗人先托出山势的高险，然后由静而动，写出水石激荡、山谷轰鸣的惊险场景。好像一串电影镜头：开始是山峦起伏、连峰接天的远景画面；接着平缓地推成枯松倒挂绝壁的特写；而后，跟踪而来的是一组快镜头，飞湍、瀑流、悬崖、转石，配合着万壑雷鸣的音响，飞快地从眼前闪过，惊险万状，目不暇接，从而造成一种势若排山倒海的强烈艺术效果，使蜀道之难的描写，简直达到了登峰造极的地步。如果说上面山势的高危已使人望而生畏，那此处山川的险要更令人惊心动魄了。\n\n　　风光变幻，险象丛生。在十分惊险的气氛中，最后写到蜀中要塞剑阁，在大剑山和小剑山之间有一条三十里长的栈道，群峰如剑，连山耸立，削壁中断如门，形成天然要塞。因其地势险要，易守难攻，历史上在此割据称王者不乏其人。诗人从剑阁的险要引出对政治形势的描写。他化用西晋张载《剑阁铭》中“形胜之地，匪亲勿居”的语句，劝人引为鉴戒，警惕战乱的发生，并联系当时的社会背景，揭露了蜀中豺狼的“磨牙吮血，杀人如麻”，从而表达了对国事的忧虑与关切。唐天宝初年，太平景象的背后正潜伏着危机，后来发生的安史之乱，证明诗人的忧虑是有现实意义的。\n\n　　李白以变化莫测的笔法，淋漓尽致地刻画了蜀道之难，艺术地展现了古老蜀道逶迤、峥嵘、高峻、崎岖的面貌，描绘出一幅色彩绚丽的山水画卷。诗中那些动人的景象宛如历历在目。\n\n　　李白之所以描绘得如此动人，还在于融贯其间的浪漫主义激情。诗人寄情山水，放浪形骸。他对自然景物不是冷漠的观赏，而是热情地赞叹，借以抒发自己的理想感受。那飞流惊湍、奇峰险壑，赋予了诗人的情感气质，因而才呈现出飞动的灵魂和瑰伟的姿态。诗人善于把想象、夸张和神话传说融为一体进行写景抒情。言山之高峻，则曰“上有六龙回日之高标”；状道之险阻，则曰“地崩山摧壮士死，然后天梯石栈相钩连”。诗人“驰走风云，鞭挞海岳”（陆时雍《诗镜总论》评李白七古语），从蚕丛开国说到五丁开山，由六龙回日写到子规夜啼，天马行空般地驰骋想象，创造出博大浩渺的艺术境界，充满了浪漫主义色彩。透过奇丽峭拔的山川景物，仿佛可以看到诗人那“落笔摇五岳、笑傲凌沧洲”的高大形象。\n\n　　唐以前的《蜀道难》作品，简短单薄。李白对东府古题有所创新和发展，用了大量散文化诗句，字数从三言、四言、五言、七言，直到十一言，参差错落，长短不齐，形成极为奔放的语言风格。诗的用韵，也突破了梁陈时代旧作一韵到底的程式。后面描写蜀中险要环境，一连三换韵脚，极尽变化之能事。所以殷璠编《河岳英灵集》称此诗“奇之又奇，自骚人以还，鲜有此体调”。\n\n　　关于此篇，前人有种种寓意之说，断定是专为某人某事而作的。明人胡震亨、顾炎武认为，李白“自为蜀咏”，“别无寓意”。今人有谓此诗表面写蜀道艰险，实则写仕途坎坷，反映了诗人在长期漫游中屡逢踬碍的生活经历和怀才不遇的愤懑，迄无定论。\n\n逐段分析 　　第一段从开头到“相钩连”，用了四韵，为全诗定下豪放的基调，并用五丁开山的神话，点染了神奇色彩。《蜀王本纪》中记载了一个关于蜀道的神话。据说当年秦惠王时，蜀王部下有五个大力士，称为“五丁力士”。他们力大无穷。于是秦惠王送给蜀王五个美女，蜀王就命五丁力士移山开路，迎娶美女。在回行路上，见一条大蛇蹿入山洞，五丁力士上前拉住蛇尾，用力往外拖，忽然地动山摇，山岭崩塌，压死了五丁力士。秦国的五个美女都奔上山去，化为石人。这个神话，反映着古代有许多劳动人民，凿山开路，牺牲了不少人，终于打开了秦蜀通道。李白运用这个神话的母题，写了第五韵二句：“地崩山摧壮士死”，也可以说是指五丁力士，也可以说是指成千累万为开山辟路而牺牲的劳动人民。他们死了，然后从秦入蜀才有山路和栈道连接起来。第一段诗到此为止，用四韵八句叙述了蜀道的起源。\n\n　　第二段共享九个韵，描写天梯石栈的蜀道。“六龙回日”也是一个神话故事，据说太阳之神羲和驾着六条龙每天早晨从扶桑西驰，直到若木。左思《蜀都赋》有两句描写蜀中的高山：“羲和假道于峻坂，阳乌回翼乎高标。”羲和和阳乌都是太阳的代词。文意是说：太阳也得向高山借路。而最高的山还使太阳回飞避开。“上有六龙回日之高标”，这一句就是说：上面有连太阳都过不去的高峰。“高标”是高举、高耸之意，但作名词用，因而可以解作高峰。萧士赟注引《图经》云：高标是山名。这是后代人误读李白诗，或有意附会，硬把一座山名为高标。原诗以“高标”和“回川”对举，可知决不是专名。\n\n　　这两句诗有一个不同的文本。《河岳英灵集》、《极玄集》这两个唐人的选本、敦煌石室中发现的唐人写本，还有北宋初的《唐文粹》，这两句却不是“上有六龙回日之高标，下有冲波逆折之回川”，而是“上有横河断海之浮云，下有逆折冲波之流川”。从对偶来看，后者较为工整，若论句子的气魄，则前者更为壮健。可能后者是当时流传的初稿，而前者是作者的最后改定本。故当时的选本作“横河断海”，而李阳冰编定的集本作“六龙回日”。\n\n　　以下一大段又形容蜀山之高且险。黄鹤都飞不过，猿猴也怕攀缘之苦。青泥岭，在陕西略阳县，是由秦入蜀的必经之路。这条山路百步九曲，在山岩上纡回盘绕，行旅极为艰苦。参和井都是二十八宿之一。蜀地属于参宿的分野，秦地属于井宿的分野。在高险的山路上，从秦入蜀，就好似仰面朝天，屏住呼吸，摸着星辰前进。在这样艰难困苦的旅程中，行人都手按着胸膛，为此而长叹。这个“坐”字，不是坐立的坐，应该讲作“因此”。\n\n　　以上是第二段的前半，四韵八句，一气贯注，渲染了蜀道之难。下面忽然接一句“问君西游何时还”，这就透露了赠行的主题。作者不像作一般送行诗那样，讲些临别的话，而在描写蜀道艰难中间，插入一句“你什么时候才能回来呀？”由此反映了来去都不容易。这一句本身也成为蜀道难的描写部分了。\n\n　　“畏途巉岩”以下四韵七句，仍然紧接着上文四韵写下去，不过改变了描写的对象。现在不写山高路险，而写山中的禽鸟了。诗人说：这许多不可攀登的峥嵘的山岩，真是旅人怕走的道路（畏途）。在这一路上，你能见到的只是古树上悲鸣的鸟，雌的跟着雄的在幽林中飞绕。还有蜀地著名的子规鸟，常在月下悲鸣。据说古代有一个蜀王，名叫杜宇，号为望帝。他因亡国而死，死后化为子规鸟，每天夜里在山中悲鸣，好像哭泣一样。\n\n　　以下还有一韵二句，是第二段的结束语。先重复一句“蜀道之难难于上青天”，接着说：使人听了这些情况，会惊骇得变了脸色。“凋朱颜”在这里只能讲作因惊骇而“色变”的意思，虽然在别处应当讲作“衰老”。\n\n　　第二段以下，韵法与章法似乎有点参差。依韵法来写，分为三段。但如果从思想内容的结构来看，实在只能说是两段。从“连峰去天不盈尺”到“胡为乎来哉”是一段，即全诗的第三段。从“剑阁峥嵘而崔嵬”到末句是又一段，即全诗的第四段，第三段前四句仍是描写蜀道山水之险，但作者分用两个韵。“尺”、“壁”一韵，只有二句，接下去立刻就换韵，使读者到此，有气氛短促之感。在长篇歌行中忽然插入这样的短韵句法，一般都认为是缺点。尽管李白才气大，自由用韵，不受拘束，但这两句韵既急促，思想又不成段落，在讲究诗法的人看来，终不是可取的。\n\n　　这一段前二句形容高山绝壁上有倒挂的枯松，下二句形容山泉奔瀑，冲击崖石的猛势，如万壑雷声。最后结束一句“其险也如此”。这个“如此”，并不单指上面二句，而是总结“上有六龙回日之高标”以下的一切描写。在山水形势方面的蜀道之险，到此结束。此下就又接一个问句：你这个远路客人为什么到这里来呢?这又是出人意外的句子。如果从蜀中人的立场来讲，就是说：我们这地方，路不好走，你何必来呢？如果站在送行人的立场来讲，就是说：如此危险的旅途，你有什么必要到那里去呢？\n\n　　接下去转入第四段，忽然讲到蜀地的军事形势。“一夫当关，万夫莫开”，易于固守，难于攻入。像这样的地方，如果没有亲信可靠的人去镇守，就非常危险了。这几句诗完全用晋代张载的《剑阁铭》中四句：“一人荷戟，万夫趑趄，形胜之地，匪亲弗居。”李白描写蜀道之难行，联系到蜀地形势所具有的政治意义，事实上已越出了乐府旧题“蜀道难”的范围。巴蜀物产富饶，对三秦的经济供应，甚为重要。所以王勃《送杜少府之任蜀川》诗第一句就说蜀地“城阙辅三秦”，也是指出了这一点。李白作乐府诗，虽然都用旧题，却常常注入有现实意义的新意。这一段诗反映了初唐以来，蜀地因所守非亲，屡次引起吐蕃、南蛮的入侵，导致生灵涂炭的战争，使三秦震动。\n\n　　这一段诗，在李白是顺便提到，作为描写蜀道难的一部分。但却使后世读者误认为全诗的主题所在。有人以为此诗讽刺章仇兼琼，有人以为讽刺严武，有人以为讽刺一般恃险割据的官吏，都是为这一段诗所迷惑，而得出这些结论。但是，这几句诗，确是破坏了全诗的统一性，写在赠友人入蜀的诗中，实在使人有主题两歧之感。然诗作本是诗人感情之流露：蜀中势力盘根错节，险要的地势更成为滋生割据野心的土壤，李白害怕友人误入是非之地，命丧宵小之手，故有“一夫当关，万夫莫开”“锦城虽云乐，不如早还家”之语。', poem_tags = '唐诗三百首,山水,抒情' WHERE poem_title = '蜀道难' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '长长的原上草是多么茂盛，每年秋冬枯黄春来草色浓。\n无情的野火只能烧掉干叶，春风吹来大地又是绿茸茸。\n野草野花蔓延着淹没古道，艳阳下草地尽头是你征程。\n我又一次送走知心的好友，茂密的青草代表我的深情。', poem_notes = '赋得：借古人诗句或成语命题作诗。诗题前一般都冠以“赋得”二字。这是古代人学习作诗或文人聚会分题作诗或科举考试时命题作诗的一种方式，称为“赋得体“。\n离离：青草茂盛的样子。\n一岁一枯荣：枯，枯萎。荣，茂盛。野草每年都会茂盛一次，枯萎一次。\n远芳侵古道：芳，指野草那浓郁的香气。远芳：草香远播。侵，侵占，长满。远处芬芳的野草一直长到古老的驿道上。\n晴翠：草原明丽翠绿。\n王孙：本指贵族后代，此指远方的友人。\n萋萋：形容草木长得茂盛的样子。', poem_appreciation = '首句即破题面“古原草”三字。多么茂盛（“离离”）的原上草，抓住“春草”生命力旺盛的特征，可说是从“春草生兮萋萋”脱化而不着迹，为后文开出很好的思路。就“古原草”而言，何尝不可开作“秋来深径里”（僧古怀《原是秋草》），那通篇也就将是另一种气象了。野草是一年生植物，春荣秋枯，岁岁循环不已。“一岁一枯荣”意思似不过如此。然而写作“枯──荣”，与作“荣──枯”就大不一样。如作后者，便是秋草，便不能生发出三、四的好句来。两个“一”字复叠，形成咏叹，又先状出一种生生不已的情味，三、四句就水到渠成了。\n\n　　“野火烧不尽，春风吹又生。”这是“枯荣”二字的发展，由概念一变而为形象的画面。古原草的特性就是具有顽强的生命力，它是斩不尽锄不绝的，只要残存一点根须，来年会更青更长，很快蔓延原野。作者抓住这一特点，不说“斩不尽锄不绝”，而写作“野火烧不尽”，便造就一种壮烈的意境。野火燎原，烈焰可畏，瞬息间，大片枯草被烧得精光。而强调毁灭的力量，毁灭的痛苦，是为着强调再生的力量，再生的欢乐。烈火是能把野草连茎带叶统统“烧尽”的，然而作者偏说它“烧不尽”，大有意味。因为烈火再猛，也无奈那深藏地底的根须，一旦春风化雨，野草的生命便会复苏，以迅猛的长势，重新铺盖大地，回答火的凌虐。看那“离离原上草”，不是绿色的胜利的旗帜么！“春风吹又生”，语言朴实有力，“又生”二字下语三分而含意十分。宋吴曾《能改斋漫录》说此两句“不若刘长卿‘春入烧痕青’语简而意尽”，实未见得。\n\n　　此二句不但写出“原上草”的性格，而且写出一种从烈火中再生的理想的典型，一句写枯，一句写荣，“烧不尽”与“吹又生”是何等唱叹有味，对仗亦工致天然，故卓绝千古。而刘句命意虽似，而韵味不足，远不如白句为人乐道。\n\n　　如果说这两句是承“古原草”而重在写“草”，那么五、六句则继续写“古原草”而将重点落到“古原”，以引出“送别”题意，故是一转。上一联用流水对，妙在自然；而此联为的对，妙在精工，颇觉变化有致。“远芳”、“睛翠”都写草，而比“原上草”意象更具体、生动。芳曰“远”，古原上清香弥漫可嗅；翠曰“晴”，则绿草沐浴着阳光，秀色如见。“侵”、“接”二字继“又生”，更写出一种蔓延扩展之势，再一次突出那生存竞争之强者野草的形象。“古道”、“荒城”则扣题面“古原”极切。虽然道古城荒，青草的滋生却使古原恢复了青春。比较“乱蛬鸣古堑，残日照荒台”僧古怀《原上秋草》的秋原，就显得生气勃勃。\n\n　　作者并非为写“古原”而写古原，同时又安排一个送别的典型环境：大地春回，芳草芊芊的古原景象如此迷人，而送别在这样的背景上发生，该是多么令人惆怅，同时又是多么富于诗意呵。“王孙”二字借自楚辞成句，泛指行者。“王孙游兮不归，春草生兮萋萋”说的是看见萋萋芳草而怀思行游未归的人。而这里却变其意而用之，写的是看见萋萋芳草而增送别的愁情，似乎每一片草叶都饱含别情，那真是：“离恨恰如春草，更行更远还生”（李煜《清平乐》）。这是多么意味深长的结尾啊！诗到此点明“送别”，结清题意，关合全篇，“古原”、“草”、“送别”打成一片，意境极浑成。\n\n　　全诗措语自然流畅而又工整，虽是命题作诗，却能融入深切的生活感受，故字字含真情，语语有余味，不但得体，而且别具一格，故能在“赋得体”中称为绝唱。', poem_tags = '唐诗三百首,小学古诗,送别,咏物,写草,早教古诗100首' WHERE poem_title = '草 / 赋得古原草送别' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '日暮时投宿石壕村，夜里有差役来强征兵。老翁越墙逃走，老妇出门应付。\n差役喊叫得是那样凶狠，老妇人啼哭得是那样悲伤。我听到老妇上前说：“我的三个儿子去参加邺城之战。其中一个儿子捎信回来，说另外两个儿子刚刚战死。活着的人姑且活一天算一天，死去的人就永远不会复生了！\n老妇我家里再也没有其他的人了，只有个正在吃奶的小孙子。因为有小孙子在，他母亲还没有离去，但进进出出连一件完好的衣裳都没有。\n老妇虽然年老力衰，但请允许我跟从你连夜赶回营去。赶快到河阳去应征，还能够为部队准备早餐。”\n夜深了，说话的声音逐渐消失，隐隐约约听到低微断续的哭泣声。天亮后我继续赶路，只能与返回家中的那个老翁告别。', poem_notes = '暮：在傍晚。\n投：投宿。\n吏：官吏，低级官员，这里指抓壮丁的差役。\n夜：时间名词作状语，在夜里。\n逾（yú）：越过；翻过。\n走：跑，这里指逃跑。\n呼：诉说，叫喊。\n一何：何其、多么。\n怒：恼怒，凶猛，粗暴，这里指凶狠。\n啼：哭啼。\n苦：凄苦。\n前：上前，向前。\n致：对……说。\n前致词：指老妇走上前去（对差役）说话。\n邺城：即相州，在今河南安阳。\n戍（shù）：防守，这里指服役。\n附书至：捎信回来。书，书信。至，回来。\n新：最近，刚刚。\n存：活着，生存着。\n且偷生：姑且活一天算一天。且：姑且，暂且。偷生：苟且活着。\n长已矣：永远完了。已：停止，这里引申为完结。\n室中：家中。\n更无人：再没有别的（男）人了。更：再。\n惟：只，仅。\n乳下孙：正在吃奶的孙子。\n未：还没有。\n去：离开，这里指改嫁。\n完裙：完整的衣服。\n老妪（yù）：老妇人。\n衰：弱。\n请从吏夜归：请让我和你晚上一起回去。请：请求。从：跟从，跟随。\n应：响应。\n河阳：今河南省洛阳市吉利区（原河南省孟县），当时唐王朝官兵与叛军在此对峙。\n急应河阳役：赶快到河阳去服役。\n犹得：还能够。得：能够。\n备：准备。\n晨炊：早饭。\n夜久：夜深了。\n绝：断绝；停止。\n如：好像，仿佛。\n闻：听。\n泣幽咽：低微断续的哭声。有泪无声为“泣”，哭声哽塞低沉为“咽”。\n明：天亮之后。\n登前途：踏上前行的路。登：踏上。前途：前行的路。\n独：唯独、只有。\n石壕：今河南三门峡市东南。', poem_appreciation = '《石壕吏》是一首杰出的现实主义的叙事诗，写了差吏到石壕村乘夜捉人征兵,连年老力衰的老妇也被抓服役的故事,揭露了官吏的残暴和兵役制度的黑暗,对安史之乱中人民遭受的苦难深表同情。艺术上,精炼是这首诗的一大特点,把抒情和议论寓于叙事之中,爱憎分明。场面和细节描写自然真实。善于裁剪,中心突出。\n\n　　前四句可看作第一段。首句“暮投石壕村”，单刀直入，直叙其事。“暮”字、“投”字、“村”字都需玩味，读者不能轻易放过。在封建社会里，由于社会秩序混乱和旅途荒凉等原因，旅客们都“未晚先投宿”，更何况在兵祸连接的时代。而杜甫，却于暮色苍茫之时才匆匆忙忙地投奔到一个小村庄里借宿，这种异乎寻常的情景就富于暗示性。他或者是压根儿不敢走大路；或者是附近的城镇已荡然一空，无处歇脚。总之，寥寥五字，不仅点明了投宿的时间和地点，而且和盘托出了兵荒马乱、鸡犬不宁、一切脱出常轨的景象，为悲剧的演出提供了典型环境。浦起龙指出这首诗“起有猛虎攫人之势”（《读杜心解》），这不仅是就“有吏夜捉人”说的，而且是就头一句的环境烘托说的。“有吏夜捉人”一句，是全篇的提纲，以下情节，都从这里生发出来。不说“征兵”、“点兵”、“招兵”而说“捉人”，已于如实描绘之中寓揭露、批判之意。再加上一个“夜”字，含意更丰富。第一、表明官府“捉人”之事时常发生，人民白天躲藏或者反抗，无法“捉”到；第二、表明县吏“捉人”的手段狠毒，于人民已经入睡的黑夜，来个突然袭击。同时，诗人是“暮”投石壕村的，从“暮”到“夜”，已过了几个小时，这时当然已经睡下了；所以下面的事件发展，他没有参与其间，而是隔门听出来的。“老翁逾墙走，老妇出门看”两句，表现了人民长期以来深受抓丁之苦，昼夜不安；即使到了深夜，仍然寝不安席，一听到门外有了响动，就知道县吏又来“捉人”，老翁立刻“逾墙”逃走，由老妇开门周旋。\n\n　　从“吏呼一何怒”至“犹得备晨炊”这十六句，可看作第二段。“吏呼一何怒！妇啼一何苦！”两句，极其概括、极其形象地写出了“吏”与“妇”的尖锐矛盾。一“呼”、一“啼”，一“怒”、一“苦”，形成了强烈的对照；两个状语“一何”，加重了感情色彩，有力地渲染出县吏如狼似虎，叫嚣隳突的横蛮气势，并为老妇以下的诉说制造出悲愤的气氛。矛盾的两方面，具有主与从、因与果的关系。“妇啼一何苦”，是“吏呼一何怒”逼出来的。下面，诗人不再写“吏呼”，全力写“妇啼”，而“吏呼”自见。“听妇前致词”承上启下。那“听”是诗人在“听”，那“致词”是老妇“苦啼”着回答县吏的“怒呼”。写“致词”内容的十三句诗，多次换韵，表现出多次转折，暗示了县吏的多次“怒呼”、逼问。这十三句诗，不是“老妇”一口气说下去的，而县吏也决不是在那里洗耳恭听。实际上，“吏呼一何怒，妇啼一何苦！”不仅发生在事件的开头，而且持续到事件的结尾。从“三男邺城戍”到“死者长已矣”，是第一次转折。读者可以想见，这是针对县吏的第一次逼问诉苦的。在这以前，诗人已用“有吏夜捉人”一句写出了县吏的猛虎攫人之势。等到“老妇出门看”，便扑了进来，贼眼四处搜索，却找不到一个男人，扑了个空。于是怒吼道：\n\n　　“你家的男人都到哪儿去了？快交出来！”老妇泣诉说：“三个儿子都当兵守邺城去了。一个儿子刚刚捎来一封信，信中说，另外两个儿子已经牺牲了！……”泣诉的时候，可能县吏不相信，还拿出信来交县吏看。\n\n　　总之，“存者且偷生，死者长已矣！”处境是够使人同情的，她很希望以此博得县吏的同情，高抬贵手。不料县吏又大发雷霆：“难道你家里再没有别人了？快交出来！”她只得针对这一点诉苦：“室中更无人，惟有乳下孙。”这两句，也不是一口气说下去的，因为“更无人”与下面的回答发生了明显的矛盾。合理的解释是：老妇先说了一句：“家里再没人了！”而在这当儿，被儿媳妇抱在怀里躲到什么地方的小孙儿，受了怒吼声的惊吓，哭了起来，掩口也不顶用。于是县吏抓到了把柄，威逼道：“你竟敢撒谎！不是有个孩子哭吗？”老妇不得已，这才说：“只有个孙子啊！还吃奶呢，小得很！”“吃谁的奶？总有个母亲吧！还不把她交出来！”老妇担心的事情终于发生了！她只得硬着头皮解释：“孙儿是有个母亲，她的丈夫在邺城战死了，因为要喂奶给孩子，没有改嫁。可怜她衣服破破烂烂，怎么见人呀！还是行行好吧！”（“有孙母未去，出入无完裙”两句，有的版本为“孙母未便出，见吏无完裙”，所以县吏是要她出来的。）但县吏仍不肯罢手。老妇生怕守寡的儿媳被抓，饿死孙子，只好挺身而出：“老妪力虽衰，请从吏夜归。急应河阳役，犹得备晨炊。”老妇的“致词”，到此结束，表明县吏勉强同意，不再“怒吼”了。\n\n　　最后一段虽然只有四句，却照应开头，涉及所有人物，写出了事件的结局和作者的感受。“夜久语声绝，如闻泣幽咽。”表明老妇已被抓走，走·时低声哭泣，越走越远，便听不到哭声了。“夜久”二字，反映了老妇一再哭诉、县吏百般威逼的漫长过程。“如闻”二字，一方面表现了儿媳妇因丈夫战死、婆婆被“捉”而泣不成声，另一方面也显示出诗人以关切的心情倾耳细听，通夜未能入睡。“天明登前途，独与老翁别”两句，收尽全篇，于叙事中含无限深情。前一天傍晚投宿之时，老翁、老妇双双迎接诗人，而时隔一夜，老妇被捉走，儿媳妇泣不成声，只能与逃走归来的老翁作别了。老翁的心情怎样，诗人作何感想，这些都给读者留下了想象的余地。\n\n　　仇兆鳌在《杜少陵集详注》里说：“古者有兄弟始遣一人从军。今驱尽壮丁，及于老弱。诗云：三男戍，二男死，孙方乳，媳无裙，翁逾墙，妇夜往。一家之中，父子、兄弟、祖孙、姑媳惨酷至此，民不聊生极矣！当时唐祚，亦岌岌乎危哉！”就是说，“民为邦本”，把人民整成这个样子，统治者的宝座也就岌岌可危了。诗人杜甫面对这一切，没有美化现实，却如实地揭露了政治黑暗，发出了“有吏夜捉人”的呼喊，这是值得高度评价的。\n\n　　在艺术表现上，这首诗最突出的一点则是精炼。陆时雍称赞道：“其事何长！其言何简！”就是指这一点说的。全篇句句叙事，无抒情语，亦无议论语；但实际上，作者却巧妙地通过叙事抒了情，发了议论，爱憎十分强烈，倾向性十分鲜明。寓褒贬于叙事，既节省了很多笔墨，又丝毫没有给读者概念化的感觉。诗中还运用了藏问于答的表现手法。“吏呼一何怒！妇啼一何苦！”概括了双方的矛盾之后，便集中写“妇”，不复写“吏”，而“吏”的蛮悍、横暴，却于老妇“致词”的转折和事件的结局中暗示出来。诗人又十分善于剪裁，叙事中藏有不尽之意。一开头，只用一句写投宿，立刻转入“有吏夜捉人”的主题。又如只写了“老翁逾墙走”，未写他何时归来；只写了“如闻泣幽咽”，未写泣者是谁；只写老妇“请从吏夜归”，未写她是否被带走；却用照应开头、结束全篇、既叙事又抒情的“独与老翁别”一句告诉读者：老翁已经归家，老妇已被捉走；那么，那位吞声饮泣、不敢放声痛哭的，就是给孩子喂奶的年轻寡妇了。正由于诗人笔墨简洁、洗炼，用了较短的篇幅，在惊人的广度与深度上反映了生活中的矛盾与冲突，这是十分难能可贵的。', poem_tags = '初中古诗,叙事,战争,同情,人民' WHERE poem_title = '石壕吏' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '过去的仙人已经驾着黄鹤飞走了，这里只留下一座空荡荡的黄鹤楼。\n黄鹤一去再也没有回来，千百年来只看见悠悠的白云。\n阳光照耀下的汉阳树木清晰可见，鹦鹉洲上有一片碧绿的芳草覆盖。\n天色已晚，眺望远方，故乡在哪儿呢？眼前只见一片雾霭笼罩江面，给人带来深深的愁绪。', poem_notes = '黄鹤楼：故址在湖北省武汉市武昌区，民国初年被火焚毁，1985年重建，传说\n古代有一位名叫费祎的仙人，在此乘鹤登仙。\n昔人：指传说中的仙人子安。因其曾驾鹤过黄鹤山〔又名蛇山〕，遂建楼。\n乘：驾。\n去：离开。\n空：只。\n返：通返，返回。\n空悠悠：深，大的意思\n悠悠：飘荡的样子。\n川：平原。\n历历：清楚可数。\n汉阳：地名，现在湖北省武汉市汉阳区，与黄鹤楼隔江相望。\n萋萋：形容草木长得茂盛。\n鹦鹉洲：在湖北省武汉市武昌区西南，根据后汉书记载，汉黄祖担任江夏太守时，在此大宴宾客，有人献\n上鹦鹉，故称鹦鹉洲。唐朝时在汉阳西南长江中，后逐渐被水冲没。\n乡关：故乡。', poem_appreciation = '这首诗前写景，后抒情，一气贯注，浑然天成，即使有一代“诗仙”之称的李白，也不由得佩服得连连赞叹，觉得自己还是暂时止笔为好。为此，李白还遗憾得叹气说：“眼前好景道不得，崔颢题诗在上头！”\n\n　　黄鹤楼因其所在之武昌黄鹤山（又名蛇山）而得名。传说古代仙人子安乘黄鹤过此（见《齐谐志》）；又云费文伟登仙驾鹤于此（见《太平寰宇记》引《图经》）。诗即从楼的命名之由来着想，借传说落笔，然后生发开去。仙人跨鹤，本属虚无，现以无作有，说它“一去不复返”，就有岁月不再、古人不可见之憾；仙去楼空，唯余天际白云，悠悠千载，正能表现世事茫茫之慨。诗人这几笔写出了那个时代登黄鹤楼的人们常有的感受，气概苍莽，感情真挚。\n\n　　前人有“文以气为主”之说，此诗前四句看似随口说出，一气旋转，顺势而下，绝无半点滞碍。“黄鹤”二字再三出现，却因其气势奔腾直下，使读者“手挥五弦，目送飞鸿”，急忙读下去，无暇觉察到它的重叠出现，而这是律诗格律上之大忌，诗人好像忘记了是在写“前有浮声，后须切响”、字字皆有定声的七律。试看：首联的五、六字同出“黄鹤”；第三句几乎全用仄声；第四句又用“空悠悠”这样的三平调煞尾；亦不顾什么对仗，用的全是古体诗的句法。这是因为七律在当时尚未定型吗？不是的，规范的七律早就有了，崔颢自己也曾写过。是诗人有意在写拗律吗？也未必。他跟后来杜甫的律诗有意自创别调的情况也不同。看来还是知之而不顾，如《红楼梦》中林黛玉教人做诗时所说的，“若是果有了奇句，连平仄虚实不对都使得的”。在这里，崔颢是依据诗以立意为要和“不以词害意”的原则去进行实践的，所以才写出这样七律中罕见的高唱入云的诗句。沈德潜评此诗，以为“意得象先，神行语外，纵笔写去，遂擅千古之奇”（《唐诗别裁》卷十三），也就是这个意思。\n\n　　此诗前半首用散调变格，后半首就整饬归正，实写楼中所见所感，写从楼上眺望汉阳城、鹦鹉洲的芳草绿树并由此而引起的乡愁，这是先放后收。倘只放不收，一味不拘常规，不回到格律上来，那么，它就不是一首七律，而成为七古了。此诗前后似成两截，其实文势是从头一直贯注到底的，中间只不过是换了一口气罢了。这种似断实续的连接，从律诗的起、承、转、合来看，也最有章法。元杨载《诗法家数》论律诗第二联要紧承首联时说：“此联要接破题（首联），要如骊龙之珠，抱而不脱。”此诗前四句正是如此，叙仙人乘鹤传说，颔联与破题相接相抱，浑然一体。杨载又论颈联之“转”说：“与前联之意相避，要变化，如疾雷破山，观者惊愕。”疾雷之喻，意在说明章法上至五、六句应有突变，出人意外。此诗转折处，格调上由变归正，境界上与前联截然异趣，恰好符合律法的这个要求。叙昔人黄鹤，杳然已去，给人以渺不可知的感觉；忽一变而为晴川草树，历历在目，萋萋满洲的眼前景象，这一对比，不但能烘染出登楼远眺者的愁绪，也使文势因此而有起伏波澜。使诗意重归于开头那种渺茫不可见的境界，这样能回应前面，如豹尾之能绕额的“合”，也是很符合律诗法度的。\n\n　　正由于此诗艺术上出神入化，取得极大成功，它被人们推崇为题黄鹤楼的绝唱，就是可以理解的了。\n\n　　后来李白登楼时，也诗兴大发，当他在楼中发现崔颢一诗，连称“绝妙、绝妙！”相传李白写下了四句“打油诗”来抒发自己的感怀：“一拳捶碎黄鹤楼，一脚踢翻鹦鹉洲，眼前有景道不得，崔颢题诗在上头。”便搁笔不写了。有个少年丁十八讥笑李白：“黄鹤楼依然无恙，你是捶不碎了的。”李白又作诗辩解：“我确实捶碎了，只因黄鹤仙人上天哭诉玉帝，才又重修黄鹤楼，让黄鹤仙人重归楼上。”真是煞有介事，神乎其神。后人乃在黄鹤楼东侧，修建一亭，名曰李白搁笔亭，以志其事。重檐复道，成为燕游之所。实际上，李白热爱黄鹤楼，到了无以复加的程度，他高亢激昂，连呼“一忝青云客，三登黄鹤楼”。山川人文，相互倚重，黄鹤楼之名更加显赫。', poem_tags = '唐诗三百首,初中古诗,写景,地名,怀古,思乡,早教古诗100首' WHERE poem_title = '黄鹤楼 / 登黄鹤楼' AND poem_author = '崔颢';
UPDATE edu_poem SET poem_translation = '秋风凌清，秋月明朗。\n风中的落叶时聚时散，寒鸦本已栖息，又被明月惊起。\n朋又盼着相见，却不知在何日，这个时节，这样的夜晚，相思梦难成。\n走入相思之门，知道相思之苦，\n永远的相思永远的回忆，短暂的相思却也无止境，\n早知相思如此的在心中牵绊，不如当初就不要相识。', poem_notes = '落叶聚还（huán）散：写落叶在风中时而聚集时而扬散的情景。\n寒鸦：《本草纲目》：“慈鸟，北人谓之寒鸦，以冬日尤盛。”\n绊（bàn）：牵绊，牵扯，牵挂。', poem_appreciation = '此诗写在深秋的夜晚，诗人望见了高悬天空的明月，和栖息在已经落完叶子的树上的寒鸦，也许在此时诗人正在思念一个旧时的恋人， 此情此景， 不禁让诗人悲伤和无奈。这是典型的悲秋之作，秋风、秋月、落叶、寒鸦烘托出悲凉的氛围 加上诗人的奇丽的想象，和对自己内心的完美刻画让整首诗显的凄婉动人。\n\n　　此诗的体式许多人认为很像一首小词，具有明显的音乐特性。赵翼的《陔余丛考》卷二十三云：“三五七言诗起于李太白：‘秋风清，秋月明。……’此其滥觞也。刘长卿《送陆澧》诗云：‘新安路，人来去。早潮复晚潮,明日知何处？潮水无情亦解归，自怜长在新安住。’宋寇莱公《江南春》诗云：‘波渺渺，柳依依。孤林芳草远，斜日沓花飞。江南春尽离肠断，苹满汀洲人未归。’……”指出了它和“江南春”词牌的渊源关系。南宋邓深曾依此调式填写词作，名为“秋风清”。清人还把李白这首诗当作是一首创调词而收入《钦定词谱》，云：“本三五七言诗，后人采入词中。”\n\n　　此诗只题作“三五七言”而不言及诗歌内容主题，可知诗人的创作意图本是偏重作品的形式特征，即只要满足全篇两句三言、两句五言、两句七言的体式要求就能成诗了。可以说，诗题中已经包含了明确的诗体形式内涵。严羽的《沧浪诗话》中的“诗体”一章就说道：“有三五七言。”自注云：“自三言而终以七言，隋世郑世翼有此诗：‘秋风清，秋月明。落叶聚还散，寒鸦栖复惊。相思相见知何日，此时此夜难为情。’”郭绍虞先生校释曰：“沧浪所谓郑世翼有三五七言，不知何据。案《诗人玉屑》无‘秋风清’以下各句，以从《玉屑》为是。‘秋风清’云云,见《李太白集》，当是李作。”\n\n　　但李白这首诗也不能算是创体之作，因为初唐时僧人义净作有一首《在西国怀王舍城》，此诗因其体式特征而名为《一三五七九言》。李白的《三五七言》只是《一三五七九言》的变体，省去起首的“一言”和收尾的“九言”，即为“三五七言”。王昆吾在《唐代酒令艺术》中论证义净诗为“唱和之作”。李白这首《三五七言》可能也是他与其他诗人的“唱和诗”。“三五七言”是对所酬和诗歌格式的限制，这是一个“总题”，众人在具体创作时可根据所写内容再命一个相应的诗题。\n\n　　此诗即使不是创体之作，也是李白最终确立了“三三五五七七”格式作为一种独特的曲辞格甚至成为一种时兴诗体的地位。这不仅是因为他借鉴和总结了许多人应用三五七字句式的经验，更得力于他自身歌辞创作中灵活运用此类格式的实践体悟，因而他的《三五七言》能表现出“哀音促节，凄若繁弦”（《唐宋诗醇》卷八）的艺术魅力。', poem_tags = '宋词三百首,秋天,抒情,思念,爱情' WHERE poem_title = '三五七言 / 秋风词' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '我扈驾赴辽东巡视，随行的千军万马一路跋山涉水，浩浩荡荡，向山海关进发。入夜，营帐中灯火辉煌，宏伟壮丽。\n夜已深，帐篷外风雪交加，阵阵风雪声搅得人无法入睡。作者思乡心切，孤单落寞，不由得生出怨恼之意：家乡怎么没有这么烦乱的声音呢？', poem_notes = '走过一条条山路，走过一条条水路，正向榆关那边走去。夜深了，人们在帐篷里点灯。晚上又刮风又下雪，声音嘈杂打碎了思乡的梦，家乡没有这样的声音。 \n【程】道路、路程，山一程、水一程，即山长水远。\n【榆关】即今山海关，在今河北秦皇岛东北。\n【那畔】即山海关的另一边，指身处关外。\n【帐】军营的帐篷，千帐言军营之多。\n【更】旧时一夜分五更，每更大约两小时。风一更、雪一更，即言整夜风雪交加也。\n【聒（guō）】声音嘈杂，这里指风雪声。\n【故园】故乡，这里指北京。\n【此声】指风雪交加的声音。', poem_appreciation = '清初词人于小令每多新创意境。这首《长相思》以具体的时空推移过程，及视听感受，既表现景象的宏阔观感，更抒露着情思深苦的绵长心境，是即小见大的佳作。\n\n　　上片在“一程”又“一程”的复叠吟哦中，展示出与家园的空间阻隔不断地随着时间的推移而严重增大，空间感与乡情构成尖锐冲突。正在这种行进方向和心绪逆反背离中驻营夜宿，“夜深千帐灯”，似是壮伟景观，实乃情心深苦之写。白日行军，跋涉山水，到夜深时仍灯火通明，难入梦乡，这是因思乡而失眠。于是转入下片乡情思恋之笔。\n\n　　“一更”又“一更”的重叠复沓，于听风听雪的感觉中推移着时间过程，时间感知于乡情的空间阻隔而心烦意乱，怨夜太长。说“聒碎乡心梦不成”，其实是作者乡心聒碎梦难成，情苦不寐，只觉得风声雪声，声声扣击入心窝，难以承受。在“乡园”时是不会有这种令人痛苦的声响的。将主观因素推诿客观，语似平淡，意更深沉。此类迁怒归咎于风雪声写法，心理情态能充分表现出来。看似无理，反见情痴，愈是无理之怨，其怨愈显沉重。叠句和数字“一”、“千”的运用强化着视、听觉感受中的焦虑，怨怼，幽苦，亦是此词值得辨味的佳处。纳兰性德身为一等侍卫，却极厌烦“扈从”公差，于是构成传统羁旅题材的又一种类型。', poem_tags = '小学古诗,婉约,羁旅,写景,思乡' WHERE poem_title = '长相思·山一程' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '长江犹如巨斧劈开天门雄峰，碧绿江水东流到此回旋澎湃。\n两岸青山对峙美景难分高下，遇见一叶孤舟悠悠来自天边。', poem_notes = '天门山：位于安徽省和县与芜湖市长江两岸，在江北的叫西梁山，在江南的叫东梁山（古代又称博望山）。两山隔江对峙，形同天设的门户，天门由此得名。\n中断：江水从中间隔断两山。楚江：即长江。因为古代长江中游地带属楚国，所以叫楚江。开：劈开，断开。\n至此：意为东流的江水在这转向北流。一作“直北”。回：回漩，回转。指这一段江水由于地势险峻方向有所改变，并更加汹涌。\n两岸青山：分别指东梁山和西梁山。出：突出，出现。\n日边来：指孤舟从天水相接处的远方驶来，远远望去，仿佛来自日边。', poem_appreciation = '“望”字统领全诗\n\n　　这是一首江行写景的七绝诗，题为“望天门山”，可见作为描写对象的天门山风光，系诗人舟中放眼而“望”之所得。全诗在“望”字统领下展开，“天门”之山形水色融为一体，雄奇壮伟的景象得到充分的展现。诗人身在船上，眼望两岸青山，有船不动而山在动的错觉，故写出“两岸青山相对出”的佳句，似青山有情，欣然出迎远来的孤帆，颇富情趣。\n\n　　山水互为映衬\n\n　　诗中的山水是紧密关联，互为映衬的。楚江浩荡，似乎把“天门”冲“开”，而“天门中断”使楚江得以奔腾而出。天门两峰横夹楚江，而楚江激流穿越天门。山依水立，水由山出，山水相连，景象壮观。“碧水东流”为山峰所遏制，故至天门而回旋，山为水开，水为山回，互为制约，又融为了一体。“相对出”的“两岸青山”，与水中的“孤帆一片”，点面结合，动静相衬，构成一幅完整而动人的画面。通览全诗，山形水势，或合说，或分写，或明提，或暗示，密切相关，互映互衬，展现出了极为宏阔壮观的景象。', poem_tags = '小学古诗,写景,山水,长江,早教古诗100首' WHERE poem_title = '望天门山' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '（石灰石）只有经过千万次锤打才能从深山里开采出来，它把熊熊烈火的焚烧当作很平常的一件事。\n即使粉身碎骨也毫不惧怕，甘愿把一身清白留在人世间。', poem_notes = '石灰吟：赞颂石灰。吟：吟颂。指古代诗歌体裁的一种名称（古代诗歌的一种形式）。\n千锤万凿：无数次的锤击开凿，形容开采石灰非常艰难。千、万：虚词，形容很多。锤：锤打。凿：开凿。\n若等闲：好像很平常的事情。若：好像、好似；等闲：平常，轻松。\n浑：全。\n清白：指石灰洁白的本色，又比喻高尚的节操。人间：人世间。', poem_appreciation = '这是一首托物言志诗。作者以石灰作比喻，表达自己为国尽忠，不怕牺牲的意愿和坚守高洁情操的决心。\n\n　　作为咏物诗，若只是事物的机械实录而不寄寓作者的深意，那就没有多大价值。这首诗的价值就在于处处以石灰自喻，咏石灰即是咏自己磊落的襟怀和崇高的人格。\n\n　　首句“千锤万凿出深山”是形容开采石灰石很不容易。次句“烈火焚烧若等闲”。“烈火焚烧”，当然是指烧炼石灰石。加“若等闲”三字，又使人感到不仅是在写烧炼石灰石，它还象征着志士仁人无论面临着怎样严峻的考验，都从容不迫，视若等闲。第三句“粉身碎骨浑不怕”。“粉身碎骨”极形象地写出将石灰石烧成石灰粉，而“浑不怕”三字又使我们联想到其中可能寓有不怕牺牲的精神。至于最后一句“要留清白在人间”更是作者在直抒情怀，立志要做纯洁清白的人。\n\n　　于谦为官廉洁正直，曾平反冤狱，救灾赈荒，深受百姓爱戴。明英宗时，瓦剌入侵，明英宗被俘。于谦议立明景帝，亲自率兵固守北京，击退瓦剌，使人民免遭蒙古贵族再次野蛮统治。但英宗复辟后却以“谋逆罪”诬杀了这位民族英雄。这首《石灰吟》可以说是于谦生平和人格的真实写照。', poem_tags = '古诗三百首,小学古诗,咏物,爱国,励志,早教古诗100首' WHERE poem_title = '石灰吟' AND poem_author = '于谦';
UPDATE edu_poem SET poem_translation = '昨天夜里雨点虽然稀疏，但是风却劲吹不停，我酣睡一夜，然而醒来之后依然觉得还有一点酒意没有消尽。于是就问正在卷帘的侍女，外面的情况如何，她只对我说：“海棠花依旧如故”。知道吗？知道吗？应是绿叶繁茂，红花凋零。', poem_notes = '疏：指稀疏。\n卷帘人：有学者认为此指侍女。\n绿肥红瘦：绿叶繁茂，红花凋零。\n浓睡不消残酒：虽然睡了一夜，仍有余醉未消。浓睡：酣睡 残酒：尚未消散的醉意。\n雨疏风骤：雨点稀疏，晚风急猛。', poem_appreciation = '这首小令，有人物，有场景，还有对白，充分显示了宋词的语言表现力和词人的才华。\n\n　　“昨夜雨疏风骤”指的是昨宵雨狂风猛。疏，正写疏放疏狂，而非通常的稀疏义。当此芳春，名花正好，偏那风雨就来逼迫了，心绪如潮，不得入睡，只有借酒消愁。酒吃得多了，觉也睡得浓了。功效一醒觉来，天已大亮。但昨夜之神情，却已然如隔在胸，所以一路身便要询问意中悬悬之事。因而，她急问清算衡宇，启户卷帘的侍女：海棠花若何样了？侍女看了一看，笑回道：“还不错，一夜风雨，海棠一点儿没变！”女主人听了，嗔叹道；“傻丫头，你可知道那海棠花丛已是红的见少，绿的见多了吗！？”\n\n　　这句对白写出了诗画所不能道，写出了伤春易春的闺中人复杂的神气口吻，可谓“传神之笔。\n\n　　作者以“浓睡”、“残酒”搭桥，写出了白夜至晨的时间变化和心理演变。然后一个“卷帘”，点破日曙天明，巧妙得当。然而，问卷帘之人，却一字不提所问何事，只于答话中透露出谜底。\n\n　　真是绝妙工巧，不着痕迹。词人为花而喜，为花而悲、为花而醉、为花而嗔，实则是伤春惜春，以花自喻，慨叹自己的青春易逝。\n\n　　本篇是李清照早期的词作之一。词中充分体现出作者对大自然、对春天的热爱。这是一首小令，内容也很简单。它写的是春夜里大自然经历了一场风吹雨打，词人预感到庭园中的花木必然是绿叶繁茂，花事凋零了。因此，翌日清晨她急切地向“卷帘人”询问室外的变化，粗心的“卷帘人”却答之以“海棠依旧”。对此，词人禁不住连用两个“知否”与一个“应是”来纠正其观察的粗疏与回答的错误。“绿肥红瘦”一句，形象地反映出作者对春天将逝的惋惜之情。', poem_tags = '宋词三百首,宋词精选,婉约,惜花,伤春' WHERE poem_title = '如梦令·昨夜雨疏风骤' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '三月七日，在沙湖道上赶上了下雨，拿着雨具的仆人先前离开了，同行的人都觉得很狼狈，只有我不这么觉得。过了一会儿天晴了，就做了这首词。\n\n不用注意那穿林打叶的雨声，不妨一边吟咏长啸着，一边悠然地行走。竹杖和草鞋轻捷得胜过骑马，有什么可怕的？一身蓑衣任凭风吹雨打，照样过我的一生。\n春风微凉，将我的酒意吹醒，寒意初上，山头初晴的斜阳却应时相迎。回头望一眼走过来遇到风雨的地方，回去吧，对我来说，既无所谓风雨，也无所谓天晴。', poem_notes = '定风波：词牌名。\n沙湖：在今湖北黄冈东南三十里，又名螺丝店。\n狼狈：进退皆难的困顿窘迫之状。\n已而：过了一会儿。\n穿林打叶声：指大雨点透过树林打在树叶上的声音。\n吟啸：放声吟咏。\n芒鞋：草鞋。\n一蓑烟雨任平生：披着蓑衣在风雨里过一辈子也处之泰然。一蓑（suō）：蓑衣，用棕制成的雨披。\n料峭：微寒的样子。\n斜照：偏西的阳光。\n向来：方才。萧瑟：风雨吹打树叶声。\n也无风雨也无晴：意谓既不怕雨，也不喜晴。', poem_appreciation = '读罢全词，令人心情振奋，心境豁然，心灵净化。人生的沉浮、情感的忧乐，在读者的理念中自会有一番全新的体悟。从心理学“白日梦”的角度看，此词实际是作者描绘的一个淡泊从容、旷达超脱的白日梦，在多个方面都非常符合白日梦的特征。\n\n　　第一，心情符合白日梦之条件——郁闷不爽。\n\n　　写此词前三年，即公元1079年，作者因被诬作诗“谤讪朝廷”遭御史弹劾，被捕入狱，后又被贬为黄州团练副使，宦海沉浮，经历坎坷，理想不竟，抱负未果，使作者几年来一直郁郁不得志，思想上陷入出世与入世的矛盾之中，心情烦闷。\n\n　　第二，意境符合白日梦之真谛——宁静自由。\n\n　　作者对现实的官场险恶生活非常厌倦，渴望摆脱这种生活，退隐江湖，过一种淡泊宁静、无忧无患、无欲无求、轻松自由的生活，也即“归去”。\n\n　　第三，结构具备白日梦之特征——自然完整。\n\n　　入梦的引子是“饮酒”和“下雨”。酒的微醉让作者晕晕乎乎，这是白日梦形成的主要基础。烟雨的迷蒙让天气灰暗朦胧，创设了入梦的良好氛围。\n\n　　入梦句是“莫听穿林打叶声”，梦境为“何妨吟啸且徐行，竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生”。这里作者用“竹杖”“芒鞋”“蓑衣”“烟雨”等意象及雨中“吟啸”“徐行”等动作创设了一个极为美妙的白日梦梦境，活脱脱地勾勒出了一个隐居江湖过着从容淡泊生活的隐士形象，他虽无荣华富贵之享受，但亦无宦海浮沉之忧患，心情得以平静，心境得以安宁。\n\n　　梦醒句为“料峭春风吹酒醒，微冷，山头斜照却相迎”。料峭的春风吹醒了醉酒，作者感到冷，一个激凌，头脑清醒了，梦结束了，作者又回到现实之中。这“冷”既是实写酒醒后身体感到冷，也是写梦醒后又想到自己的遭遇而产生的心冷。正在这时，远处山头温暖的夕阳让作者感到了些许暖意，也增添了他战胜逆境的信心。\n\n　　过渡句为“回首向来萧瑟处”。虽然“相迎”的斜阳给作者带了一丝温暖，但一想到自己饱含萧瑟风雨的坎坷仕途路——“回首向来萧瑟处”，心中燃起的希望之火又熄灭了！\n\n　　梦破后寻梦句为“归去，也无风雨也无晴”。仕途的风雨就如同这自然界的风雨一样变幻无常，他所期盼的仕途阳光又会在多长的风雨之后？与其终日忍受这种提心吊胆之痛，还不如“归去”，退隐江湖，一切平静，无悲无喜，“无雨无晴”。\n\n　　第四，情节显露白日梦之特色——亦真亦幻。\n\n　　首先，序言中说“同行皆狼狈”，已证明雨之大，而“莫听穿林打叶声，何妨吟啸且徐行”却又描写诗人置身雨中，对雨听而不闻，从容高歌，潇洒徐行，全然没感到淋漓之苦的状态，这怎么可能是实写呢？接下来的“竹杖芒鞋轻胜马”也不太合常理。用竹杖芒鞋行泥泞之路，拖泥带水，怎比得上骑着高头大马急行如飞来得轻快？因此这“轻”恐怕不是写现实行路之轻，而应是无官一身轻。“一蓑烟雨任平生”也让人生疑。序言中已说“雨具先去”，怎会又出现了披蓑在雨中穿行？看来应是想象之景。“回首向来萧瑟处，归去，也无风雨也无晴”若按自然的逻辑也很难解释得通。雨过天晴，应该是“已无风雨正是晴”，怎会是“也无晴”？所以，这里的“晴”不会单纯指天晴。\n\n　　由此可见，这些都是写作者心中想象之事而非眼前之景，全词就是作者着力刻画的一个“也无风雨也无晴”的“归去”白日梦！\n\n　　纵观全词，一种醒醉全无、无喜无悲、胜败两忘的人生哲学和处世态度呈现在读者面前。“也无风雨也无晴”，是一种宠辱不惊、胜败两忘、旷达潇洒的境界，是一种“至人无己，神人无功，圣人无名”的境界，是一种回归自然，天人合一，宁静超然的大彻大悟。', poem_tags = '宋词三百首,春天,写雨,豪放' WHERE poem_title = '定风波·莫听穿林打叶声' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '桃红柳绿的春山，煦暖的阳光照耀，和柔的东风吹拂，楼阁上高卷起帘拢，倚栏干远望。杨柳垂条，秋千轻晃，院子里静悄悄。院外黄莺啼鸣，春燕飞舞； 小桥之下流水飘满落红。', poem_notes = '和风：多指春季的微风。\n阑干：即栏杆。\n帘栊（lóng）：窗户上的帘子。栊，窗户。\n啼莺舞燕：即莺啼燕舞，意思是黄莺在歌唱，春燕在飞舞。\n飞红：花瓣飞舞，指落花。', poem_appreciation = '这支曲子运用绘画技法，从不同空间层次描写春天的景物，具体来说，整个画面的背景，是远景，第二句是人物的立足点是近景，第三句庭院中喧闹的景象，展示了一幅充满生机、春意盎然的画面,是中景。最能够体现春天特征的两个形容词是暖和啼莺，而最能庭院中生机的景物是舞燕和飞红。 这支曲的人物应该是一位女子，她站在栏杆之旁，帘栊之下，窥探着春天的景致，她眼中的春天要更加细腻，更加秀美.......\n\n　　这首词曲全由列锦组成，列锦是中国古典诗歌中特殊的修辞方式。这个名称是当代修辞学家谭永祥提出的，他对列锦的解释是：古典诗歌作品中一种奇特的句式，即全句以名词或名词短语组成，里面没有动词或形容词谓语，却同样能起到写景抒情、叙事述怀的效果。（《修辞新格》，福建教育出版社）\n\n　　运用“列锦”，可以收到很好的表达效果。正如人们分析的那样，列锦具有凝炼美、简约美、含蓄美、空灵美和意境美。拿今天的艺术品类来比方，列锦获得了影视镜头巧妙剪辑（即蒙太奇）的某些效果，能激发读者丰富的想象和联想，言有尽而意无穷。', poem_tags = '散曲,春天,写景' WHERE poem_title = '天净沙·春' AND poem_author = '白朴';
UPDATE edu_poem SET poem_translation = '什么地方可以看见中原呢？在北固楼上，满眼都是美好的风光。从古到今，有多少国家兴亡大事呢？不知道。往事连绵不断，如同没有尽头的长江水滚滚地奔流不息。\n当年孙权在青年时代，做了三军统帅。他能占据东南，坚持抗战，没有向敌人低头和屈服过。天下英雄谁是孙权的敌手呢？只有曹操和刘备而已。这样也就难怪曹操说：“要是能有个孙权那样的儿子就好了！”', poem_notes = '南乡子：词牌名。\n京口：今江苏省镇江市。北固亭：在今镇江市北固山上，下临长江，三面环水。\n望：眺望。神州：这里指中原地区。\n北固楼：即北固亭。\n兴亡：指国家兴衰，朝代更替。\n悠悠：形容漫长、久远。\n年少：年轻。指孙权十九岁继父兄之业统治江东。兜鍪（dōu móu）：指千军万马。原指古代作战时兵士所带的头盔，这里代指士兵。\n坐断：坐镇，占据，割据。东南：指吴国在三国时地处东南方。休：停止。\n敌手：能力相当的对手。\n曹刘：指曹操与刘备。\n生子当如孙仲谋：曹操率领大军南下，见孙权的军队雄壮威武 ，喟然而叹：“生子当如孙仲谋，刘景升儿子若豚犬耳。”', poem_appreciation = '收回遥望的视线，看这北固楼近处的风物：“千古江山，英雄无觅，孙仲谋处。舞榭歌台，风流总被，雨打风吹去。”（《永遇乐·京口北固亭怀古》）这不禁引起了词人千古兴亡之感。因此，词人接下来再问一句：“千古兴亡多少事？”这句问语纵观千古成败，意味深长，回味无穷。然而，往事悠悠，英雄往矣，只有这无尽的江水依旧滚滚东流。“悠悠，不尽长江滚滚流！”“悠悠”者，兼指时间之漫长久远，和词人思绪之无穷也。\n\n　　“不尽长江滚滚流”，借用杜甫《登高》诗句：“无边落木萧萧下，不尽长江滚滚来。”词人胸中倒来倒去的不尽愁思和感慨，犹如长流不息的江水。“年少万兜鍪，坐断东南战未休。”三国时代的孙权年纪轻轻就统率千军万马，雄据东南一隅，奋发自强，战斗不息。据历史记载：孙权十九岁继父兄之业统治江东，西征黄祖，北拒曹操，独据一方。赤壁之战大破曹兵，年方二十七岁。因此可以说，上面这两句是实写史事，因为它是千真万确的历史，因而更具有说服力和感染力。作者在这里一是突出了孙权的年少有为，“年少”而敢于与雄才大略、兵多将广的强敌曹操较量，这就需要非凡的胆识和气魄。二是突出了孙权的盖世武功，他不断征战，不断壮大。而他之“坐断东南”，形势与南宋政权相似。显然，稼轩热情歌颂孙权的不畏强敌，坚决抵抗，并战而胜之，正是反衬当朝文武之辈的庸碌无能、懦怯苟安。\n\n　　接下来，辛弃疾为了把这层意思进一步发挥，不惜以夸张之笔极力渲染孙权不可一世的英姿。他异乎寻常地第三次发问，以提醒人们注意：“天下英雄谁敌手？”作者自问又自答曰：“曹刘”，唯曹操与刘备耳！据《三国志·蜀书·先主传》记载：曹操曾对刘备说：“今天下英雄，惟使君（刘备）与操耳。”辛弃疾便借用这段故事，把曹操和刘备请来给孙权当配角，说天下英雄只有曹操、刘备才堪与孙权争胜。曹、刘、孙三人，论智勇才略，孙权未必在曹刘之上。稼轩在《美芹十论》中对孙权的评价也并非称赞有加，然而，在这首词里，词人却把孙权作为三国时代第一流叱咤风云的英雄来颂扬，其所以如此用笔，实借凭吊千古英雄之名，慨叹当今南宋无大智大勇之人执掌乾坤。这种用心，更于篇末见意。 作者在这里极力赞颂孙权的年少有为，突出他的盖世武功，其原因是孙权“坐断东南”，形势与南宋极似，作者这样热情赞颂孙权的不畏强敌，其实是对苟且偷安、毫无振作的南宋朝廷的鞭挞。\n\n　　《三国志·吴书·吴主传》注引《吴历》说：曹操有一次与孙权对垒，见吴军乘着战船，军容整肃，孙权仪表堂堂，威风凛凛，乃喟然叹曰：“生子当如孙仲谋，刘景升（刘表）儿子若豚犬耳！”一世之雄如曹操，对敢于与自己抗衡的强者，投以敬佩的目光，而对于那种不战而请降的懦夫，如对刘景升儿子刘琮则十分轻视，斥为任人宰割的猪狗。把大好江山拱手奉献敌人，还要为敌人耻笑辱骂。 作者在这里引用了前半句，没有明言后半句，实际上是借曹操之口，讽刺当朝主议的大臣们都是刘景升儿子一类的猪狗，这种别开生面的表现手法，曲尽其妙，而又意在言外。\n\n　　曹操所一褒一贬的两种人，形成了极其鲜明、强烈的对照，在南宋摇摇欲坠的政局中，也有着主战与主和两种人。聪明的词人只做正面文章，对刘景升儿子这个反面角色，便不指名道姓以示众了。然而纵然作者不予道破，而又能使人感到不言而喻。因为上述曹操这段话众所周知，虽然辛弃疾只说了前一句赞语，人们马上就会联想起后面那句骂人的话，从而使人意识到辛弃疾的潜台词：可笑当朝主和议的众多王公大臣，都是刘景升儿子之类的猪狗。词人此种别开生面的表现手法，颇类似歇后语的作用。而且在写法上这一句与上两句意脉不断，衔接得很自然。上两句说，天下英雄中只有曹操、刘备配称孙权的对手。连曹操都这样说，生儿子要像孙权这个样。再从“生子当如孙仲谋”这句话的蕴含和思想深度来说，南宋时代人，如此看重孙权，实是那个时代特有的社会心理的反映。因为南宋朝廷实在太萎靡庸碌了，在历史上，孙权能称雄江东于一时，而南宋经过了好几代皇帝，却没有出一个像孙权一样的人。所以，“生子当如孙仲谋”这句话，本是曹操的语言，而由辛弃疾口中说出，却是代表了南宋人民要求奋发图强的时代的呼声。\n\n　　这首词通篇三问三答，互相呼应，感怆雄壮，意境高远。它与稼轩同时期所作另一首登北固亭词《永遇乐·京口北固亭怀古》相比，一风格明快，一沉郁顿挫，同是怀古伤今，写法大异其趣，而都不失为千古绝唱，亦可见辛弃疾丰富多彩之大手笔也。', poem_tags = '宋词三百首,初中古诗,豪放,咏史怀古,爱国,典故,讽刺' WHERE poem_title = '南乡子·登京口北固亭有怀' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '我是古帝高阳氏的子孙，我已去世的父亲字伯庸。\n岁星在寅那年的孟春月，正当庚寅日那天我降生。\n父亲仔细揣测我的生辰，于是赐给我相应的美名：\n父亲把我的名取为正则，同时把我的字叫作灵均。\n天赋给我很多良好素质，我不断加强自己的修养。\n我把江离芷草披在肩上，把秋兰结成索佩挂身旁。\n光阴似箭我好像跟不上，岁月不等待人令我心慌。\n早晨我在大坡采集木兰，傍晚在小洲中摘取宿莽。\n时光迅速逝去不能久留，四季更相代谢变化有常。\n我想到草木已由盛到衰，恐怕自己身体逐渐衰老。\n何不利用盛时扬弃秽政，为何还不改变这些法度？\n乘上千里马纵横驰骋吧，来呀，我在前引导开路！\n从前三后公正德行完美，所以群贤都在那里聚会。\n杂聚申椒菌桂似的人物，岂止联系优秀的茝和蕙。\n唐尧虞舜多么光明正直，他们沿着正道登上坦途。\n夏桀殷纣多么狂妄邪恶，贪图捷径必然走投无路。\n结党营私的人苟安享乐，他们的前途黑暗而险阻。\n难道我害怕招灾惹祸吗，我只担心祖国为此覆没。\n前前后后我奔走照料啊，希望君王赶上先王脚步。\n你不深入了解我的忠心，反而听信谗言对我发怒。\n我早知道忠言直谏有祸，原想忍耐却又控制不住。\n上指苍天请它给我作证．一切都为了君王的缘故。\n你以前既然和我有成约，现另有打算又追悔当初。\n我并不难于与你别离啊，只是伤心你的反反复复。\n我已经栽培了很多春兰，又种植香草秋蕙一大片。\n分垄培植了留夷和揭车，还把杜衡芳芷套种其间。\n我希望它们都枝繁叶茂，等待着我收割的那一天。\n它们枯萎死绝有何伤害，使我痛心的是它们质变。\n大家都拚命争着向上爬，利欲熏心而又贪得无厌。\n他们猜疑别人宽恕自己，他们勾心斗角相互妒忌。\n急于奔走钻营争权夺利，这些不是我追求的东西。\n只觉得老年在渐渐来临，担心美好名声不能树立。\n早晨我饮木兰上的露滴，晚上我用菊花残瓣充饥。\n只要我的情感坚贞不易，形消骨立又有什么关系。\n我用树木的根编结茝草，再把薜荔花蕊穿在一起。\n我拿菌桂枝条联结蕙草，胡绳搓成绳索又长又好。\n我向古代的圣贤学习啊，不是世间俗人能够做到。\n我与现在的人虽不相容，我却愿依照彭咸的遗教。\n我揩着眼泪啊声声长叹，可怜人生道路多么艰难。\n我虽爱好修洁严于责己，早晨被辱骂晚上又丢官。\n他们攻击我佩带蕙草啊，又指责我爱好采集茝兰。\n这是我心中追求的东西，就是多次死亡也不后悔。\n怨就怨楚王这样糊涂啊，他始终不体察别人心情。\n那些女人妒忌我的丰姿，造谣诬蔑说我妖艳好淫。\n庸人本来善于投机取巧，背弃规矩而又改变政策。\n违背是非标准追求邪曲，争着苟合取悦作为法则。\n忧愁烦闷啊我失意不安，现在孤独穷困多么艰难。\n宁可马上死去魂魄离散，媚俗取巧啊我坚决不干。\n雄鹰不与那些燕雀同群，原本自古以来就是这般。\n方和圆怎能够互相配各，志向不同何能彼此相安。\n宁愿委曲心志压抑情感，宁把斥责咒骂统统承担。\n保持清白节操死于直道，这本为古代圣贤所称赞！\n后悔当初不曾看清前途，迟疑了一阵我又将回头。\n调转我的车走回原路啊，趁着迷途未远赶快罢休。\n我打马在兰草水边行走，跑上椒木小山暂且停留。\n既然进取不成反而获罪，那就回来把我旧服重修。\n我要把菱叶裁剪成上衣，我并用荷花把下裳织就。\n没有人了解我也就罢了，只要内心真正馥郁芳柔。\n把我的帽子加得高高的，把我的佩带增得长悠悠。\n虽然芳洁污垢混杂一起，只有纯洁品质不会腐朽。\n我忽然回头啊纵目远望，我将游观四面遥远地方。\n佩着五彩缤纷华丽装饰，散发出一阵阵浓郁清香。\n人们各有自己的爱好啊，我独爱好修饰习以为常。\n即使粉身碎骨也不改变，难道我能受警戒而彷徨！\n姐姐对我遭遇十分关切，她曾经一再地向我告诫。\n她说“鲧太刚直不顾性命，结果被杀死在羽山荒野。\n你何忠言无忌爱好修饰，还独有很多美好的节操。\n满屋堆着都是普通花草，你却与众不同不肯佩服。\n众人无法挨家挨户说明，谁会来详察我们的本心。\n世上的人都爱成群结伙，为何对我的话总是不听？”\n我以先圣行为节制性情，愤懑心情至今不能平静。\n渡过沅水湘水向南走去，我要对虞舜把道理讲清：\n“夏启偷得《九辩》和《九歌》啊，他寻欢作乐而放纵忘情。\n不考虑将来看不到危难，因此武观得以酿成内乱。\n后羿爱好田猎溺于游乐，对射杀大狐狸特别喜欢。\n本来淫乱之徒无好结果，寒浞杀羿把他妻子霸占。\n寒浇自恃有强大的力气，放纵情欲不肯节制自己。\n天天寻欢作乐忘掉自身，因此他的脑袋终于落地。\n夏桀行为总是违背常理，结果灾殃也就难以躲避。\n纣王把忠良剁成肉酱啊，殷朝天下因此不能久长。\n商汤夏禹态度严肃恭敬，正确讲究道理还有文王。\n他们都能选拔贤者能人，遵循一定准则不会走样。\n上天对一切都公正无私，见有德的人就给予扶持。\n只有古代圣王德行高尚，才能够享有天下的土地。\n回顾过去啊把将来瞻望，看到了做人的根本道理。\n哪有不义的事可以去干，哪有不善的事应该担当。\n我虽然面临死亡的危险，毫不后悔自己当初志向。\n不度量凿眼就削正榫头，前代的贤人正因此遭殃。”\n我泣声不绝啊烦恼悲伤，哀叹自己未逢美好时光。\n拿着柔软蕙草揩抹眼泪，热泪滚滚沾湿我的衣裳。\n铺开衣襟跪着慢慢细讲，我已获得正道心里亮堂。\n驾驭着玉虬啊乘着凤车，在风尘掩翳中飞到天上。\n早晨从南方的苍梧出发，傍晚就到达了昆仑山上。\n我本想在灵琐稍事逗留，夕阳西下已经暮色苍茫。\n我命令羲和停鞭慢行啊，莫叫太阳迫近崦嵫山旁。\n前面的道路啊又远又长，我将上上下下追求理想。\n让我的马在咸池里饮水，把马缰绳拴在扶桑树上。\n折下若木枝来挡住太阳，我可以暂且从容地徜徉。\n叫前面的望舒作为先驱，让后面的飞廉紧紧跟上。\n鸾乌凤凰为我在前戒备，雷师却说还没安排停当。\n我命令凤凰展翅飞腾啊，要日以继夜地不停飞翔。\n旋风结聚起来互相靠拢，它率领着云霓向我迎上。\n云霓越聚越多忽离忽合，五光十色上下飘浮荡漾。\n我叫天门守卫把门打开，他却倚靠天门把我呆望。\n日色渐暗时间已经晚了，我纽结着幽兰久久徜徉。\n这个世道混浊善恶不分，喜欢嫉妒别人抹煞所长。\n清晨我将要渡过白水河，登上阆风山把马儿系着。\n忽然回头眺望涕泪淋漓，哀叹高丘竟然没有美女。\n我飘忽地来到春宫一游，折下玉树枝条增添佩饰。\n趁琼枝上花朵还未凋零，把能受馈赠的美女找寻。\n我命令云师把云车驾起，我去寻找宓妃住在何处。\n解下佩带束好求婚书信，我请蹇修前去给我做媒。\n云霓纷纷簇集忽离忽合，很快知道事情乖戾难成。\n晚上宓妃回到穷石住宿，清晨到洧盘把头发洗濯。\n宓妃仗着貌美骄傲自大，成天放荡不羁寻欢作乐。\n她虽然美丽但不守礼法，算了吧放弃她另外求索。\n我在天上观察四面八方，周游一遍后我从天而降。\n遥望华丽巍峨的玉台啊，见有娀氏美女住在台上。\n我请鸩鸟前去给我做媒，鸩鸟却说那个美女不好。\n雄鸠叫唤着飞去说媒啊，我又嫌它过分诡诈轻佻。\n我心中犹豫而疑惑不定，想自己去吧又觉得不妙。\n凤凰已接受托付的聘礼，恐怕高辛赶在我前面了。\n想到远方去又无处安居，只好四处游荡流浪逍遥。\n趁少康还未结婚的时节，还留着有虞国两位阿娇。\n媒人无能没有灵牙利齿，恐怕能说合的希望很小。\n世间混乱污浊嫉贤妒能，爱障蔽美德把恶事称道。\n闺中美女既然难以接近，贤智君王始终又不醒觉。\n满腔忠贞激情无处倾诉，我怎么能永远忍耐下去！\n我找来了灵草和细竹片，请求神巫灵氛为我占卜。\n“听说双方美好必将结合看谁真正好修必然爱慕。\n想到天下多么辽阔广大，难道只在这里才有娇女？”\n“劝你远走高飞不要迟疑，谁寻求美人会把你放弃？\n世间什么地方没有芳草，你又何必苦苦怀恋故地？\n世道黑暗使人眼光迷乱，谁又能够了解我们底细？\n人们的好恶本来不相同，只是这邦小人更加怪异。\n人人都把艾草挂满腰间，说幽兰是不可佩的东西。\n对草木好坏还分辨不清，怎么能够正确评价玉器？\n用粪土塞满自己的香袋，反说佩的申椒没有香气。”\n想听从灵氛占卜的好卦，心里犹豫迟疑决定不下。\n听说巫咸今晚将要降神，我带着花椒精米去接他。\n天上诸神遮天蔽日齐降，九疑山的众神纷纷迎迓。\n他们灵光闪闪显示神灵，巫咸又告诉我不少佳话。\n他说“应该努力上天下地，去寻求意气相投的同道。\n汤禹为人严正虚心求贤，得到伊尹皋陶君臣协调。\n只要内心善良爱好修洁，又何必一定要媒人介绍？\n傅说拿祷杵在傅岩筑墙，武丁毫不犹豫用他为相。\n太公吕望曾经做过屠夫，他被任用是遇到周文王。\n宁戚喂牛敲着牛角歌唱，齐桓公听见后任为大夫。\n趁现在年轻大有作为啊，施展才能还有大好时光。\n只怕杜鹃它叫得太早啊，使得百草因此不再芳香。”\n为什么这样美好的琼佩，人们却要掩盖它的光辉。\n想到这邦小人不讲信义，恐怕出于嫉妒把它摧毁。\n时世纷乱而变化无常啊，我怎么可以在这里久留。\n兰草和芷草失掉了芬芳，荃草和惠草也变成茅莠。\n为什么从前的这些香草，今天全都成为荒蒿野艾。\n难道还有什么别的理由，不爱好修洁造成的祸害。\n我还以为兰草最可依靠，谁知华而不实虚有其表。\n兰草抛弃美质追随世俗，勉强列入众芳辱没香草。\n花椒专横谄媚十分傲慢，茱萸想进香袋冒充香草。\n它们既然这么热心钻营，又有什么香草重吐芳馨。\n本来世态习俗随波逐流，又还有谁能够意志坚定？\n看到香椒兰草变成这样，何况揭车江离能不变心。\n只有我的佩饰最可贵啊，保持它的美德直到如今。\n浓郁的香气难以消散啊，到今天还在散发出芳馨。\n我调度和谐地自我欢娱，姑且飘游四方寻求美女。\n趁着我的佩饰还很盛美，我要周游观访上天下地。\n灵氛已告诉我占得吉卦，选个好日子我准备出发。\n折下玉树枝叶作为肉脯，我舀碎美玉把干粮备下。\n给我驾车啊用飞龙为马，车上装饰着美玉和象牙。\n彼此不同心怎能配合啊，我将要远去主动离开他。\n我把行程转向昆仑山下，路途遥远继续周游观察。\n云霞虹霓飞扬遮住阳光，车上玉铃丁当响声错杂。\n清晨从天河的渡口出发，最远的西边我傍晚到达。\n凤凰展翅承托着旌旗啊，长空翱翔有节奏地上下。\n忽然我来到这流沙地段，只得沿着赤水行进缓缓。\n指挥蛟龙在渡口上架桥，命令西皇将我渡到对岸。\n路途多么遥远又多艰险，我传令众车在路旁等待。\n经过不周山向左转去啊，我的目的地已指定西海。\n我再把成千辆车子聚集，把玉轮对齐了并驾齐驱。\n驾车的八龙蜿蜒地前进，载着云霓旗帜随风卷曲。\n定下心来啊慢慢地前行，难控制飞得远远的思绪。\n演奏着《九歌》跳起《韶》舞啊，且借大好时光寻求欢娱。\n太阳东升照得一片明亮，忽然看见我思念的故乡。\n我的仆从悲伤马也感怀，退缩回头不肯走向前方。\n尾声：“算了吧！\n国内既然没有人了解我，我又何必怀念故国旧居。\n既然不能实现理想政治，我将追随彭成安排自己。”', poem_notes = '高阳：颛顼之号。\n苗裔（yì）：苗，初生的禾本植物。裔，衣服的末边。此苗裔连用，喻指子孙后代。\n朕：我。\n皇：美。\n考：已故的父亲。\n摄提：太岁在寅时为摄提格。此指寅年。\n贞：正。\n孟：开始。\n陬（zōu）：正月。\n庚寅（gēng yín）：指庚寅之日。古以干支相配来纪日。\n降（hōng）：降生。\n揆（kuí）：推理揣度。\n肇（zhào）：开始。\n锡（cì）：通“赐”。\n名：命名。\n字：表字，这里活用作动词，起个表字。\n内美：内在的美好品质。\n重（chóng）：再。\n扈（hù）：楚方言，披挂。\n江离芷：均为香草名。\n纫（rèn）：草有茎叶可做绳索。\n秋兰：香草名。即泽兰，秋季开花。\n汩（gǔ）：水疾流的样子，此处用以形容时光飞逝。\n不吾与：宾语前置，即“不与吾”，不等待我。\n搴（qiān）：拔取。\n揽（lǎn）：采摘。\n宿莽：草名，经冬不死。\n忽：迅速的样子。\n代序：指不断更迭。\n惟：思虑。\n迟暮：衰老。\n抚：趁。\n此度：指现行的政治法度。\n骐骥（qí jì）：骏马。\n道：通“导”，引导。\n三后：夏禹商汤周文王。\n固：本来。\n申椒菌桂：均为香木名。\n蕙（huì）茞（chén）：均为香草名。\n耿介：光明正大。\n遵道：遵循正道。\n猖披：猖狂。\n捷径：邪道。\n偷乐：苟且享乐。\n幽昧（mèi）：黑暗。\n殃（yāng）：灾祸。\n败绩：喻指君国的倾危。\n踵武：足迹，即脚印。\n荃（quán）：香草名，喻楚怀王。\n齌（jì）怒：暴怒。\n謇謇（jiǎn jiǎn）：形容忠贞直言的样子。\n九天：古人认为天有九重，故言。\n正：通“证”。\n期：约定。\n羌：楚语，表转折，相当于现在的“却”。\n成言：诚信之言。\n既：本来。\n数化：多次变化。\n滋：栽种。\n树：种植。\n亩（mǔ）：二百四十步为亩。\n畦（qí）：五十亩为畦。\n留夷揭车：均为香草名。\n冀（jì）：希望。\n峻：长。\n刈（yì）：收获。\n萎：枯萎。\n绝：落尽。\n芜（wú）：荒芜。\n秽（huì）：污秽。\n竞：并。\n羌（qiāng）：楚人语气词。\n兴：生。\n忽：急。\n驰骛（wù）：乱驰。\n冉冉（rǎn rǎn）：渐渐。\n英：花。\n苟：确实。\n信姱（kuā）：诚信而美好。\n练要：心中简练合于要道。\n掔（qiān）：持取。\n贯：拾取。\n矫：举起。\n索：草有茎叶可做绳索。此作动词，意为搓绳。\n纚纚（xǐ xǐ）：绳索美好貌。\n法：效法。\n周：合。\n彭咸：殷贤大夫，谏其君，不听，投江而死。\n民生：万民的生存。\n艰：难。\n修姱（kuā）：洁净而美好。\n谇（suì）：进谏。\n替：废。\n纕（xiāng）：佩带。\n申：重复。\n悔：怨恨。\n灵修：指楚怀王。\n众女：喻群臣。\n谣：诋毁。\n诼（zhuó）：诽谤。\n偭（miǎn）：违背。\n改：更改。\n错：通“措”，措施，指先圣之法。\n绳墨：正曲直之具。\n曲：斜曲。\n周容：苟合取容，指以求容媚为常法。\n侘傺（chà chì）：失志貌。\n流亡：随水漂流而去。\n此态：苟合取容之态。\n不群：指不与众鸟同群。\n前世：古代。\n异道：不同的道路。\n屈：委屈。\n尤：过错。\n攘：除去。\n诟（gòu）：耻辱。\n伏：通“服”，保持，坚守。\n厚：厚待。\n相道：观看。\n延：长。\n回：调转。\n行迷：指迷途。\n步：徐行。\n皋（gāo）：水边高地。\n止息：休息一下。\n尤：罪过。\n修吾初服：指修身洁行。\n制：裁制。\n芙蓉：莲花。\n不吾知：宾语前置，即“不知吾”，不了解我。\n苟：如果。\n高：指帽高。\n陆离：修长而美好的样子。\n芳：指芬芳之物。\n惟：通“唯”，只有。\n游目：纵目瞭望。\n往观：前去观望。\n缤纷：极言多。\n章：明显。\n民生：人生。\n常：恒常之法。\n犹：尚且。\n惩：惧怕。\n女嬃（xū）：屈原的姐姐。\n婵媛（chán yuán）：牵挂。\n申申：反反复复。\n婞（xìng）直：刚正。\n羽之野：羽山的郊野。\n博謇：过于刚直。\n姱（kuā）节：美好的节操。\n盈室：满屋。\n判：区别。\n众：众人。\n云：助词，无实义。\n朋：朋党。\n茕（qióng）：孤独。\n前圣：前代圣贤。\n喟：叹息声。\n济：渡过。\n就：靠近。\n启：禹之子。夏朝的开国君主。\n《九辩》《九歌》：相传是启从天上偷带到人间的乐曲。\n夏康：启子太康。\n图：图谋。\n五子：指夏康等兄弟五人。\n用：因此。\n羿：指后羿。\n封狐：大狐。\n鲜：少。\n浞（zhuó）：寒浞，羿相。\n浇（ào）：寒浞之子。\n强圉（yǔ）：强壮多力。\n不忍：不能加以克制。\n日：天天。\n用夫：因此。\n夏桀（jié）：夏之亡国之君。\n辛：殷纣王之名。\n菹醢（zū hǎi）：肉酱，名词动用，指剁成肉酱。\n用而：因而。\n俨（yǎn）：庄严。\n莫差：没有丝毫差错。\n授：任用。\n颇：倾斜。\n私阿：偏私。\n错：置。\n茂行：美好的德行。\n下土：天下。\n瞻前而顾后：观察古往今来的成败。\n相观：观察。\n非义：不行仁义。\n非善：不行善事。\n阽（diàn）：临危，遇到危险。\n览：反观。\n量：度。\n前修：前贤。\n曾：屡次。\n当：遇。\n茹（rú）：柔软。\n浪浪：泪流不止的样子。\n敷（fū）：铺开。\n中正：治国之道。\n驷：驾车。\n上征：上天远行。\n发轫（rèn）：出发。\n苍梧：舜所葬之地。\n县圃（pǔ）：神山，在昆仑山之上。\n灵琐：神之所在处。\n令：命令。\n羲和：神话中的太阳神。\n崦嵫（yān zī）：神话中日所入之山。\n漫漫：路遥远的样子。\n修远：长远。\n咸池：日浴处。\n扶桑：日所拂之木。\n若木：日所入之处的树木。\n逍遥：自由自在的样子。\n相羊：徘徊。\n前：在前面。\n后：在后面。\n先戒：在前面警戒。\n雷师：雷神。\n飞腾：腾空而飞。\n日夜：指日夜兼程。\n飘风：旋风。\n帅：率领。\n离合：忽散忽聚。\n斑：文彩杂乱，五彩缤纷。\n帝：天帝。\n阊阖（chāng hé）：天门。\n（ài ài）暧暧：昏暗的样子。\n结：编结。\n溷（hùn）浊：混乱污浊。\n蔽：掩盖。\n白水：神话中的水名。\n绁（xiè）：拴，系。\n反顾：回头望。\n高丘：高山。\n春宫：东方青帝的居舍。\n琼（qióng）枝：玉树的花枝。\n荣华：花朵。\n可诒（yí）：可以赠送。\n丰隆：云神。\n宓（fú）妃：神女，伏羲氏之女。\n结言：约好之言。\n謇（jiǎn）修：伏羲氏之臣。\n离合：言辞未定。\n纬繣（wěi huà）：不相投合。\n次：住宿。\n濯发：洗头发。\n保：依仗。\n淫游：过分的游乐。\n虽：诚然。\n改求：另外寻求。\n览相观：细细观察。\n周流：周游。\n瑶台：以玉砌成的台。\n有娀（sōng）：传说中的上古国名。\n鸩（zhèn）：鸟名。\n鸣逝：边叫边飞。\n佻（tiāo）：轻浮。\n犹豫：拿不定主意。\n自适：亲自去。\n受诒：指完成聘礼之事。\n远集：远止。\n浮游：漫游。\n及：趁着。\n有虞（yú）：传说中的上古国名。\n理弱：指媒人软弱。\n导言：媒人撮合的言辞。\n嫉贤：嫉妒贤能。\n称恶：称赞邪恶。\n闺中：女子居住的内室。\n哲王：明智的君王。\n怀：怀抱。\n终古：永久。\n琼茅：灵草。\n筳（tíng）：小竹片。\n灵氛：传说中的上古神巫。\n信修：诚然美好。\n九州：泛指天下。\n女：美女。\n勉：努力。\n释：舍弃。\n何所：何处。\n故宇：故国。\n昡曜（yào）：惑乱浑浊。\n察：明辨。\n民：指天下众人。\n党人：朋党之人。\n服：佩用。\n览察：察看。\n珵美：即“美珵”，美玉。\n粪壤：粪土。\n申椒：申地之椒。\n巫咸：古神巫。\n夕降：傍晚从天而降。\n怀：馈。\n百神：指天上的众神。\n并迎：一起来迎接。\n皇：皇天。\n吉故：明君遇贤臣的吉祥故事。\n矱（yuē）：度。\n合：志同道合的人。\n挚（zhì）：伊尹名。\n咎繇（jiù yáo）：夏禹之臣。\n苟：如果。\n用：凭借。\n操：持，拿。\n用：重用。\n吕望：指吕尚。\n举：举用。\n宁戚：春秋时卫人，齐桓公认为贤人，以他为卿。\n该：周详。\n晏：晚。\n未央：未尽。\n鹈鴂（tí jué）：鸟名，即伯劳。一说杜鹃。\n为之：因此。\n偃蹇（yǎn jiǎn）：盛多美丽的样子。\n薆（ài）：遮蔽。\n谅：信。\n折：摧毁。\n变易：变化。\n茅：比喻已经蜕化变质的谗佞之人。\n直：竟然。\n他故：其他的理由。\n害：弊端。\n无实：不结果实。\n委：丢弃。\n得：能够。\n椒（jiāo）：楚大夫子椒。\n樧（shā）：茱萸。\n干进：求进。\n务入：钻营。\n祗（zhī）：散发。\n揭车与江离：比喻自己培育的一般人才。\n兹佩：喻指屈原的内美与追求。\n历兹：到如今这一地步。\n芳菲菲：指香气浓郁。\n沬（mèi）：消失。\n和调度：指调节自己的心态，缓和自己的心情\n自娱：自乐。\n聊：姑且。\n求女：寻求志同道合的人。\n方：正。\n上下：到处。\n吉占：指两美必合而言。\n历：选择。\n羞：通“馐”，指美食。\n琼爢（mí）：玉屑。\n飞龙：长翅膀的龙。\n象：象牙。\n离心：不同的去向。\n远逝：远去。\n邅（zhān）：楚地方言，转向。\n晻蔼（ǎn ǎi）：旌旗蔽日貌。\n鸣：响起。\n天津：天河的渡口。在东极萁斗之间。\n西极：西方的尽头。\n翼：古代一种旗帜。\n翼翼：和貌。\n流沙：指西极，其处流沙如水。\n赤水：出昆仑山。\n容与：游戏貌。\n麾（huī）：指挥。\n西皇：帝少嗥。\n艰：指路途艰险。\n腾：飞驰。\n不周：山名，在昆仑西北。\n西海：神话中西方之海。\n屯：聚集。\n轪（dài）：车轮。\n婉婉：在前进时蜿蜒曲折的样子。\n委蛇（wēi yí）：旗帜飘扬舒卷的样子。\n志：通“帜”，旗帜。\n弭（mǐ）节：放下赶车的马鞭，使车停止。\n神：神思，指人的精神。\n邈邈（miǎo miǎo）：浩渺无际的样子。\n假日：犹言借此时机。\n皇：天。\n赫戏：形容光明。\n旧乡：指楚国。\n仆：御者。\n怀：思。\n蜷（quán）局：卷屈不行貌。\n乱：终篇的结语。\n已矣：绝望之词，谓“算了吧”。\n国无人：国家无人。\n足：足以。\n为：实行。\n居：住所，这里是指一生所选择的道路和归宿。', poem_appreciation = '深深植根于现实盼积极浪漫主义 　　中国文学观实主义和浪漫主义这两种创作方法源远流长，现实主义导源于《诗经》，浪漫主义导源于《楚辞》。《离骚》的浪漫主义表现在两个方面。第一是强烈的浪漫主义精神。《离骚》展现了作者爱国主义的崇高理想和为实现这种理想而百折不挠的斗争精神。他殷切希望楚国能实行修明法度、举贤授能的“美政”，再现尧舜禹汤文武和三后那样的自己心目中的盛世，所以他极力赞颂道：“彼尧舜之耿介兮，既遵道而得路”，“汤禹俨而祗敬兮，周论道而莫差”，“昔三后之纯粹兮，固众芳之所在”。他为了理想，坚持不懈，上下求索，九死未悔。第二是大量的浪漫主义手法。作者插上幻想的翅膀，尽情驰骋，这在诗的第二、三两大段里有充分的表现。如上款帝阍一节，诗人幻想在太空中翱翔，早晨从南方的苍梧山出发，傍晚便到了西北昆仑山上的悬圃。他在太阳洗澡的咸池给马喂水，在太阳升起的扶桑树下总辔启行。月神、风神、雷师、凤鸟、飘风、云霓一大群神物前呼后拥。神游西天一节，写他驾飞龙、鸣玉鸾，从天津启程，取道昆仑，渡赤水，过流沙，经不周，到西海。想象丰富奇特，境界恍惚迷离，场面宏伟壮丽。\n\n　　比兴手法的运用 　　《离骚》继承并发展了《诗经》的比兴传统。其具体表现为：在广度上，它较多地应用比喻，构成庞大的比兴系统；在深度上，较之《诗经》更为注意比兴中“此物”与“彼物”的内在联系，用作比喻的事物与全篇所表达的内容统一，富有象征性。如诗中用“美人”喻指楚怀王，用“众芳”喻指群贤，用“椒、桂、蕙、茝”四种植物喻群贤，用香草“荃”喻楚怀王等等，把比兴与表现的内容合而为一，使诗中的意名胜具有了象征意义。\n\n　　对比手法的运用 　　屈原在其诗篇中，以远古的尧、舜贤君的“耿介”、“既遵道而得路”与桀、纣暴君的“猖披”、“夫唯捷径以窘步”相对照，用以劝谏楚王要走正确的治国之路。又以“恐年岁之不吾与”和“惟夫党人之偷乐兮”相对照，使自己的热心为国与小人的苟且偷安形成鲜明对比。\n\n　　抒情中有故事情节的叙述。 　　抒情诗一般没有故事情节。《离骚》是一首长篇政治抒情诗，抒发其忠而被疏的愤懑之情。但是诗中的前一部分里叙述了自己的家世、出生和被疏的事实，后两部分里更虚构了女嬃詈原、陈辞于舜，上款帝阍、历访神妃，灵氛占卜、巫咸降神、神游西天等一系列幻境，使这首抒情诗具有了故事情节的成分。看来似乎山穷水尽，眨眼又是一番新的景象，波澜起伏，百转千回，从而把叙事诗和抒情诗融为一炉。', poem_tags = '高中文言文,楚辞,写人,爱国,励志,忧国忧民' WHERE poem_title = '离骚' AND poem_author = '屈原';
UPDATE edu_poem SET poem_translation = '历经千古的江山，再也难找到像孙权那样的英雄。当年的舞榭歌台还在，英雄人物却随着岁月的流逝早已不复存在。斜阳照着长满草树的普通小巷，人们说那是当年刘裕曾经住过的地方。回想当年，他领军北伐、收复失地的时候是何等威猛！\n然而刘裕的儿子刘义隆好大喜功，仓促北伐，却反而让北魏太武帝拓跋焘乘机挥师南下，兵抵长江北岸而返，遭到对手的重创。我回到南方已经有四十三年了，看着原仍然记得扬州一带烽火连天的战乱场景。怎么能回首啊，当年拓跋焘的行宫外竟有百姓在那里祭祀，乌鸦啄食祭品，人们过着社日，只把他当作一位神祇来供奉，而不知道这里曾是一个皇帝的行宫。还有谁会问，廉颇老了，饭量还好吗？\n\n韵译\n江山如画、历经千年仍如故，但是找不到东吴英雄孙权在此的定都处。昔日的舞榭歌台、显赫人物，都被风吹雨打化为土。斜阳照着草和树，普通的街巷和小路，人们说，武帝刘裕曾在这个地方住。想当年，他骑战马披铁甲，刀枪空中舞，气吞万里如猛虎。\n宋文帝草率用兵学黩(dú)武，效法汉将伐匈奴，没能够封山纪功狼居胥，却要仓皇向南逃，时时回头向北顾。我登上山亭望江北，还记得四十三年前的旧事一幕幕：烽火连天鏖(áo)战苦，扬州一带遭荼(tú)毒。往事怎忍再回顾？拓跋焘(tào)祠堂香火盛，乌鸦啄祭品，祭祀擂大鼓。谁能派人来探问：廉颇将军虽年老，还能吃饭吗？', poem_notes = '京口：古城名，即今江苏镇江。因临京岘山、长江口而得名。\n孙仲谋：三国时的吴王孙权，字仲谋，曾建都京口。孙权（182年——252年），字仲谋。东吴大帝，三国时期吴国的开国皇帝。吴郡富春县（今浙江富阳）人。生于公元182年（光和五年），卒于公元252年（太元二年）。长沙太守孙坚次子，幼年跟随兄长吴侯孙策平定江东，公元200年孙策早逝。孙权继位为江东之主。\n寄奴：南朝宋武帝刘裕小名。 刘裕（363年4月——422年6月），字德舆，小名寄奴，汉族，先祖是彭城人（今江苏徐州市），后来迁居到京口（江苏镇江市），南北朝时期宋朝的建立者，史称宋武帝。中国历史上杰出的政治家、卓越的军事家、统帅。\n“想当年”三句：刘裕曾两次领兵北伐，收复洛阳、长安等地。\n元嘉：刘裕子刘义隆年号。草草：轻率。封狼居胥：公元前119年（汉武帝元狩四年）霍去病远征匈奴，歼敌七万余，封狼居胥山而还。狼居胥山，在今蒙古境内。\n赢得：剩得，落得。\n烽火扬州路：指当年扬州路上，到处是金兵南侵的战火烽烟。\n“四十三年”句：作者于1162年（宋高宗绍兴三十二年）南归，到写该词时正好为四十三年。\n佛（bì）狸祠：北魏太武帝拓跋焘小名佛狸。公元450年，他曾反击刘宋，两个月的时间里，兵锋南下，五路远征军分道并进，从黄河北岸一路穿插到长江北岸。在长江北岸瓜步山建立行宫，即后来的佛狸祠。\n神鸦：指在庙里吃祭品的乌鸦。社鼓：祭祀时的鼓声。\n廉颇：战国时赵国名将。', poem_appreciation = '词以“京口北固亭怀古”为题。京口是三国时吴大帝孙权设置的重镇，并一度为都城，也是南朝宋武帝刘裕生长的地方。面对锦绣江山，缅怀历史上的英雄人物，正是像辛弃疾这样的志士登临应有之情，题中应有之意，词正是从这里着笔的。\n\n　　上片怀古抒情。第一第二句中，“千古”，是时代感，照应题目“怀古”；“江山”是现实感，照应题目“京口北固亭”。作者站在北固亭上瞭望眼前的一片江山，脑子里一一闪过千百年来曾经在这片土地上叱咤风云的英雄人物，他首先想到三国时吴国的皇帝孙权，他有着统一中原的雄图大略，在迁都建业以前，于建安十四年（209）先在京口建“京城”，作为新都的屏障，并且打垮了来自北方的侵犯者曹操的军队，保卫了国家。可是如今，像孙权这样的英雄已无处寻觅的了。诗人起笔便抒发其江山依旧，英雄不再、后继无人的感慨。而后的“舞榭歌台，风流总被雨打风吹去”在上句的基础上推进一层，非但再也找不到孙权这样的英雄人物，连他当年修建的“舞榭歌台”，那些反映他光辉功业的遗物，也都被“雨打风吹去”，杳无踪迹了。下三句写眼前景，词人联想起与京口有关的第二个历史人物刘裕。写孙权，先想到他的功业再寻觅他的遗迹；写刘裕，则由他的遗迹再联想起他的功业。然后在最后三句回忆刘裕的功业。刘裕以京口为基地，削平了内乱，取代了东晋政权。他曾两度挥戈北伐，先后灭掉南燕、后秦，收复洛阳、长安，几乎可以克复中原，作者想到刘裕的功勋，非常钦佩，最后三句，表达了词人无限景仰的感情。英雄人物留给后人的印象是深刻的，可是刘裕这样的英雄，他的历史遗迹，如今也是同样地找不到了，只有那“斜阳草树，寻常巷陌”。\n\n　　词的上片借古意以抒今情，还比较轩豁呈露，在下片里，作者通过典故所揭示的历史意义和现实感慨，就更加意深而味隐了。\n\n　　“元嘉草草”三句，用古事影射现实，尖锐地提出一个历史教训。史称南朝宋文帝刘义隆“自践位以来，有恢复河南之志”。他曾三次北伐，都没有成功，特别是元嘉二十七年（450年）最后一次，失败得更惨。用兵之前，他听取彭城太守王玄谟陈北伐之策，非常激动，说：“闻玄谟陈说，使人有封狼居胥意。”“有封狼居胥意”谓有北伐必胜的信心。当时分据在北中国的北魏，并非无隙可乘；南北军事实力的对比，北方也并不占优势。倘能妥为筹划，虑而后动，是能打胜仗，收复部分失地的。无如宋文帝急于事功，轻启兵端。结果不仅没有得到预期的胜利，反而招致北魏拓跋焘大举南侵，弄得国势一蹶而不振了。这一历史事实，对当时现实所提供的历史鉴戒，是发人深省的。作者援用古事近事影射现实，尖锐地提醒南宋统治者吸取前人的和自己的历史教训。\n\n　　从“四十三年，望中犹记，烽火扬州路”开始，词由怀古转入伤今，联系自己，联系当今的抗金形势，抒发感慨。作者回忆四十三年前北方人民反抗异族统治的斗争此起彼伏，如火如荼，自己也在战火弥漫的扬州以北地区参加抗金斗争。后来渡淮南归，原想凭借国力，恢复中原，不期南宋朝廷昏聩无能，使他英雄无用武之地。如今自己已成了老人，而壮志依然难酬。辛弃疾追思往事，不胜身世之感。\n\n　　下三句中的“回首”应接上句，由回忆往昔转入写眼前实景。这里值得探讨的是，佛狸是北魏的皇帝，距南宋已有七八百年之久，北方的百姓把他当作神来供奉，辛弃疾看到这个情景，不忍回首当年的“烽火扬州路”。辛弃疾是用“佛狸”代指金主完颜亮。四十三年前，完颜亮发兵南侵，曾以扬州作为渡江基地，而且也曾驻扎在佛狸祠所在的瓜步山上，严督金兵抢渡长江。以古喻今，佛狸很自然地就成了完颜亮的影子。如今“佛狸祠下，一片神鸦社鼓”与“四十三年，烽火扬州路”形成鲜明的对比，当年沦陷区的人民与异族统治者进行不屈不挠的斗争，烽烟四起，但如今的中原早已风平浪静，沦陷区的人民已经安于异族的统治，竟至于对异族君主顶礼膜拜，这是痛心的事。不忍回首往事，实际就是不忍目睹眼前的事实。以此正告南宋统治者，收复失土，刻不容缓，如果继续拖延，民心日去，中原就收不回了。\n\n　　最后作者以廉颇自比，这个典用得很贴切，内蕴非常丰富，一是表白决心，和廉颇当年服事赵国一样，自己对朝廷忠心耿耿，只要起用，当仁不让，奋勇争先，随时奔赴疆场，抗金杀敌。二是显示能力，自己虽然年老，但仍然和当年廉颇一样，老当益壮，勇武不减当年，可以充任北伐主帅；三是抒写忧虑。廉颇曾为赵国立下赫赫战功，可为奸人所害，落得离乡背井，虽愿为国效劳，却是报国无门，词人以廉颇自况，忧心自己有可能重蹈覆辙，朝廷弃而不用，用而不信，才能无法施展，壮志不能实现。辛弃疾的忧虑不是空穴来风，果然韩侂胄一伙人不能采纳他的意见，对他疑忌不满，在北伐前夕，以“用人不当”为名免去了他的官职。辛弃疾渴盼为恢复大业出力的愿望又一次落空。\n\n　　在这首词中用典虽多，然而这些典故却用得天衣无缝，恰到好处，它们所起的作用，在语言艺术上的能量，不是直接叙述和描写所就这首词而论，用典多并小是辛弃疾的缺点，而这首词正体现了他在语言艺术上的特殊成就。\n\n　　全词豪壮悲凉，义重情深，放射着爱国主义的思想光辉。词中用典贴切自然，紧扣题旨，增强了作品的说服力和意境美。', poem_tags = '宋词三百首,豪放,咏史怀古,爱国,讽刺,慨叹' WHERE poem_title = '永遇乐·京口北固亭怀古' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '纤薄的云彩在天空中变幻多端，天上的流星传递着相思的愁怨，遥远无垠的银河今夜我悄悄渡过。在秋风白露的七夕相会，就胜过尘世间那些长相厮守却貌合神离的夫妻。\n共诉相思，柔情似水，短暂的相会如梦如幻，分别之时不忍去看那鹊桥路。只要两情至死不渝，又何必贪求卿卿我我的朝欢暮乐呢。', poem_notes = '纤云：轻盈的云彩。弄巧：指云彩在空中幻化成各种巧妙的花样。\n飞星：流星。一说指牵牛、织女二星。\n银汉：银河。迢迢：遥远的样子。暗度：悄悄渡过。\n金风玉露：指秋风白露。\n忍顾：怎忍回视。\n朝朝暮暮：指朝夕相聚。语出宋玉《高唐赋》。', poem_appreciation = '借牛郎织女的故事，以超人间的方式表现人间的悲欢离合，古已有之，如《古诗十九首·迢迢牵牛星》，曹丕的《燕歌行》，李商隐的《辛未七夕》等等。宋代的欧阳修、张先、柳永、苏轼等人也曾吟咏这一题材，虽然遣辞造句各异，却都因袭了“欢娱苦短”的传统主题，格调哀婉、凄楚。相形之下，秦观此词堪称独出机杼，立意高远。\n\n　　这是一首咏七夕的节序词，起句展示七夕独有的抒情氛围，“巧”与“恨”，则将七夕人间“乞巧”的主题及“牛郎、织女”故事的悲剧性特征点明，练达而凄美。借牛郎织女悲欢离合的故事，歌颂坚贞诚挚的爱情。结句“两情若是久长时，又岂在朝朝暮暮”最有境界，这两句既指牛郎、织女的爱情模式的特点，又表述了作者的爱情观，是高度凝练的名言佳句。这首词因而也就具有了跨时代、跨国度的审美价值和艺术品位。 此词熔写景、抒情与议论于一炉，叙写牵牛、织女二星相爱的神话故事，赋予这对仙侣浓郁的人情味，讴歌了真挚、细腻、纯洁、坚贞的爱情。词中明写天上双星，暗写人间情侣；其抒情，以乐景写哀，以哀景写乐，倍增其哀乐，读来荡气回肠，感人肺腑。\n\n　　词一开始即写“纤云弄巧”，轻柔多姿的云彩，变化出许多优美巧妙的图案，显示出织女的手艺何其精巧绝伦。可是，这样美好的人儿，却不能与自己心爱的人共同过美好的生活。“飞星传恨”，那些闪亮的星星仿佛都传递着他们的离愁别恨，正飞驰长空。\n\n　　关于银河，《古诗十九首》云：“河汉清且浅，相去复几许？盈盈一水间，脉脉不得语。”“盈盈一水间，近咫尺，似乎连对方的神情语态都宛然目。这里，秦观却写道：”银汉迢迢暗渡“，以”迢迢“二字形容银河的辽阔，牛女相距之遥远。这样一改，感情深沉了，突出了相思之苦。迢迢银河水，把两个相爱的人隔开，相见多么不容易！”暗渡“二字既点”七夕“题意，同时紧扣一个”恨“字，他们踽踽宵行，千里迢迢来相会。\n\n　　接下来词人宕开笔墨，以富有感情色彩的议论赞叹道：“金风玉露一相逢，便胜却人间无数！”一对久别的情侣金风玉露之夜，碧落银河之畔相会了，这美好的一刻，就抵得上人间千遍万遍的相会。词人热情歌颂了一种理想的圣洁而永恒的爱情。“金风玉露”用李商隐《辛未七夕》诗：“恐是仙家好别离，故教迢递作佳期。由来碧落银河畔，可要金风玉露时。”用以描写七夕相会的时节风光，同时还另有深意，词人把这次珍贵的相会，映衬于金风玉露、冰清玉洁的背景之下，显示出这种爱情的高尚纯洁和超凡脱俗。\n\n　　“柔情似水”，那两情相会的情意啊，就象悠悠无声的流水，是那样的温柔缠绵。“柔情似水”，“似水”照应“银汉迢迢”，即景设喻，十分自然。一夕佳期竟然象梦幻一般倏然而逝，才相见又分离，怎不令人心碎！“佳期如梦”，除言相会时间之短，还写出爱侣相会时的复杂心情。“忍顾鹊桥归路”，转写分离，刚刚借以相会的鹊桥，转瞬间又成了和爱人分别的归路。不说不忍离去，却说怎忍看鹊桥归路，婉转语意中，含有无限惜别之情，含有无限辛酸眼泪。 回顾佳期幽会，疑真疑假，似梦似幻，及至鹊桥言别，恋恋之情，已至于极。词笔至此忽又空际转身，爆发出高亢的音响：“两情若是久长时，又岂在朝朝暮暮！”秦观这两句词揭示了爱情的真谛：爱情要经得起长久分离的考验，只要能彼此真诚相爱，即使终年天各一方，也比朝夕相伴的庸俗情趣可贵得多。这两句感情色彩很浓的议论，成为爱情颂歌当中的千古绝唱。它们与上片的议论遥相呼应，这样上、下片同样结构，叙事和议论相间，从而形成全篇连绵起伏的情致。这种正确的恋爱观，这种高尚的精神境界，远远超过了古代同类作品，是十分难能可贵的。\n\n　　这首词的议论，自由流畅，通俗易懂，却又显得婉约蕴藉，余味无穷。作者将画龙点睛的议论与散文句法与优美的形象、深沉的情感结合起来，起伏跃宕地讴歌了人间美好的爱情，取得了极好的艺术效果。', poem_tags = '宋词三百首,宋词精选,七夕节,爱情,哲理,婉约,抒情' WHERE poem_title = '鹊桥仙·纤云弄巧' AND poem_author = '秦观';
UPDATE edu_poem SET poem_translation = '竹子抓住青山一点也不放松，它的根牢牢地扎在岩石缝中。\n经历成千上万次的折磨和打击，它依然那么坚强，不管是酷暑的东南风，还是严冬的西北风，它都能经受得住，还会依然坚韧挺拔。', poem_notes = '竹石：扎根在石缝中的竹子。诗人是著名画家，他画的竹子特别有名，这是他题写在竹石画上的一首诗。\n咬定：比喻根扎得结实，像咬着青山不松口一样。\n立根：扎根，生根。\n原：本来,原本，原来。\n破岩：裂开的山岩，即岩石的缝隙。\n磨：折磨，挫折，磨炼。\n击：打击。\n坚劲：坚强有力。\n任：任凭，无论，不管。\n尔：你。', poem_appreciation = '这首诗是一首题画诗，题于作者郑板桥自己的《竹石图》上。这首诗在赞美岩竹的坚韧顽强中，隐寓了作者藐视俗见的刚劲风骨。\n\n　　诗的第一句：“咬定青山不放松”，首先把一个挺立峭拔的、牢牢把握着青山岩缝的翠竹形象展现在了读者面前。一个“咬”字使竹人格化。”咬”是一个主动的，需要付出力量的动作。它不仅写出了翠竹紧紧附着青山的情景，更表现出了竹子那种不畏艰辛，与大自然抗争，顽强生存的精神。紧承上句，第二句“立根原在破岩中”道出了翠竹能傲然挺拔于青山之上的基础是它深深扎根在破裂的岩石之中。在作者郑板桥诗、画中的竹又往往与“石”是分不开的。有时侯，石构成竹的对立面，如“画根竹枝插块石，石比竹枝高一尺，虽然一尺让它高，年来看我掀天力”；有时候石成为竹的背景，如”秋风昨夜渡潇湘，触石穿林惯作狂；惟有竹枝浑不怕，挺然相斗一千场”。在这首诗里，竹石则形成了一个浑然的整体，无石竹不挺，无竹山不青。这两句诗也说明了一个简单而深刻的哲理：根基深力量才强。\n\n　　有了前两句的铺垫，很自然地引出了下面两句：“千磨万击还坚劲，任尔东西南北风”。这首诗里竹有个特点，它不是孤立的竹，也不是静止的竹，而是岩竹，是风竹。在作者郑板桥的诗画中，竹往往是高尚品行和顽强意志的象征，而风则往往是恶势力的代表，如前面提到的“秋风昨夜渡潇湘”这几句，又如：“一阵狂风倒卷来，竹枝翻回向天开。扫云扫雾真吾事，岂屑区区扫地埃。”在这首诗中同样竹子经受着“东西南北风”一年四季的千磨万击。但是由于它深深扎根于岩石之中而仍岿然不动，坚韧刚劲。什么样的风都对它无可奈何。诗人用”千”、“万”两字写出了竹子那种坚韧无畏、从容自信的神态，可以说全诗的意境至此顿然而出。这时挺立在我们面前的已不再是几杆普通的竹子了，我们感受到的已是一种顽强不息的生命力，一种坚韧不拔的意志力，而这一切又都蕴涵在那萧萧风竹之中。\n\n　　诗中的竹实际上也是作者郑板桥高尚人格的化身，在生活中，诗人正是这样一种与下层百姓有着较密切的联系，嫉恶如仇、不畏权贵的岩竹。作者郑板桥的题画诗如同其画一样有着很强的立体感，可作画来欣赏。这首诗正是这样，无论是竹还是石在诗人笔下都形象鲜明，若在眼前。那没有实体的风也被描绘得如同拂面而过一样。但诗人追求的并不仅在外在的形似，而是在每一根瘦硬的岩竹中灌注了自己的理想，融进了自己的人格，从而使这竹石透露出一种畜外的深意和内在的神韵。\n\n　　这是一首借物喻人、托物言志的诗，也是一首咏物诗。这首诗着力表现了竹子那顽强而又执着的品质，托岩竹的坚韧顽强，言自己刚正不阿、正直不屈、铁骨铮铮的骨气。全诗语言简易明快，执著有力。', poem_tags = '古诗三百首,小学古诗,题画,咏物,竹子,励志,早教古诗100首' WHERE poem_title = '竹石' AND poem_author = '郑燮';
UPDATE edu_poem SET poem_translation = '我长时间倚靠在高楼的栏杆上，微风拂面一丝丝一细细，望不尽的春日离愁，沮丧忧愁从遥远无边的天际升起。碧绿的草色，飘忽缭绕的云霭雾气掩映在落日余晖里，默默无言谁理解我靠在栏杆上的心情。\n打算把放荡不羁的心情给灌醉，举杯高歌，勉强欢笑反而觉得毫无意味。我日渐消瘦下去却始终不感到懊悔，宁愿为她消瘦得精神萎靡神色憔悴。', poem_notes = '伫倚危楼：长时间依靠在高楼的栏杆上。伫，久立。危楼，高楼。\n望极：极目远望。\n黯黯：迷蒙不明，形容心情沮丧忧愁。\n生天际：从遥远无边的天际升起\n烟光：飘忽缭绕的云霭雾气。\n会：理解。\n阑：同“栏”。\n拟把：打算。\n疏狂：狂放不羁。\n强（qiǎng）乐：勉强欢笑。强，勉强。\n衣带渐宽：指人逐渐消瘦。\n消得：值得，能忍受得了。', poem_appreciation = '这是一首怀人之作。词人把漂泊异乡的落魄感受，同怀念意中人的缠绵情思结合在一起写，采用“曲径通幽”的表现方式，抒情写景，感情真挚。\n\n　　上片首先说登楼引起了“春愁”：“伫倚危楼风细细。”全词只此一句叙事，便把主人公的外形像一幅剪纸那样突现出来了。“风细细”，带写一笔景物，为这幅剪影添加了一点背景，使画面立刻活跃起来了。\n\n　　“望极春愁，黯黯生天际”，极目天涯，一种黯然魂销的“春愁”油然而生。“春愁”，又点明了时令。对这“愁”的具体内容，词人只说“生天际”，可见是天际的什么景物触动了他的愁怀。从下一句“草色烟光”来看，是春草。芳草萋萋，刬尽还生，很容易使人联想到愁恨的连绵无尽。柳永借用春草，表示自己已经倦游思归，也表示自己怀念亲爱的人。至于那天际的春草，所牵动的词人的“春愁”究竟是哪一种，词人却到此为止，不再多说。\n\n　　“草色烟光残照里，无言谁会凭栏意”写主人公的孤单凄凉之感。前一句用景物描写点明时间，可以知道，他久久地站立楼头眺望，时已黄昏还不忍离去。“草色烟光”写春天景色极为生动逼真。春草，铺地如茵，登高下望，夕阳的余辉下，闪烁着一层迷蒙的如烟似雾的光色。一种极为凄美的景色，再加上“残照”二字，便又多了一层感伤的色彩，为下一句抒情定下基调。“无言谁会凭栏意”，因为没有人理解他登高远望的心情，所以他默默无言。有“春愁”又无可诉说，这虽然不是“春愁”本身的内容，却加重了“春愁”的愁苦滋味。作者并没有说出他的“春愁”是什么，却又掉转笔墨，埋怨起别人不理解他的心情来了。词人在这里闪烁其辞，让读者捉摸不定。\n\n　　下片作者把笔宕开，写他如何苦中求乐。“愁”，自然是痛苦的，那还是把它忘却，自寻开心吧。“拟把疏狂图一醉”，写他的打算。他已经深深体会到了“春愁”的深沉，单靠自身的力量是难以排遣的，所以他要借酒浇愁。词人说得很清楚，目的是“图一醉”。为了追求这“一醉”，他“疏狂”，不拘形迹，只要醉了就行。不仅要痛饮，还要“对酒当歌”，借放声高歌来抒发他的愁怀。但结果却是“强乐还无味”，他并没有抑制住“春愁”。故作欢乐而“无味”，更说明“春愁”的缠绵执着。\n\n　　至此，作者才透露这种“春愁”是一种坚贞不渝的感情。他的满怀愁绪之所以挥之不去，正是因为他不仅不想摆脱这“春愁”的纠缠，甚至心甘情愿为“春愁”所折磨，即使渐渐形容憔悴、瘦骨伶仃，也决不后悔。“为伊消得人憔悴”才一语破的：词人的所谓“春愁”，不外是“相思”二字。（其中伊指深爱的女子，也指自己的人生理想）\n\n　　这首词妙紧拓“春愁”即“相思”，却又迟迟不肯说破，只是从字里行间向读者透露出一些消息，眼看要写到了，却又煞住，调转笔墨，如此影影绰绰，扑朔迷离，千回百折，直到最后一句，才使真相大白。在词的最后两句相思感情达到高潮的时候，戛然而止，激情回荡，又具有很强的感染力。', poem_tags = '宋词三百首,婉约,抒情,爱情,思念' WHERE poem_title = '蝶恋花·伫倚危楼风细细' AND poem_author = '柳永';
UPDATE edu_poem SET poem_translation = '江南的风景多么美好，如画的风景久已熟悉。春天到来时，太阳从江面升起，把江边的鲜花照得比火红，碧绿的江水绿得胜过蓝草。怎能叫人不怀念江南？', poem_notes = '忆江南：唐教坊曲名。作者题下自注说：“此曲亦名‘谢秋娘’，每首五句。”按《乐府诗集》：“‘忆江南’一名‘望江南’，因白氏词，后遂改名‘江南好’。”至晚唐、五代成为词牌名。这里所指的江南主要是长江下游的江浙一带。\n谙（ān）：熟悉。作者年轻时曾三次到过江南。\n江花：江边的花朵。一说指江中的浪花。红胜火：颜色鲜红胜过火焰。\n绿如蓝：绿得比蓝还要绿。如，用法犹“于”，有胜过的意思。蓝，蓝草，其叶可制青绿染料。', poem_appreciation = '白居易曾经担任杭州刺史，在杭州呆了两年，后来又担任苏州刺史，任期也一年有余。在他的青年时期，曾漫游江南，旅居苏杭，应该说，他对江南有着相当的了解，故此江南在他的心目中留有深刻印象。当他因病卸任苏州刺史，回到洛阳后十二年，他六十七岁时，写下了这三首忆江南，可见江南胜景仍在他心中栩栩如生。\n\n　　要用十几个字来概括江南春景，实属不易，白居易却巧妙地做到了。他没有从描写江南惯用的“花”、“莺”着手，而是别出心裁地从“江”为中心下笔，又通过“红胜火”和“绿如蓝”，异色相衬，展现了鲜艳夺目的江南春景。异色相衬的描写手法，在大诗人杜甫的诗里常常可见，如“两个黄鹂鸣翠柳，一行白鹭上青天”、“江碧鸟逾白，山青花欲燃”，两种不同的颜色互相映衬，使诗意明丽如画。白居易走的也是这条路，从他的诗里也可见端倪，“夕照红于烧，晴空碧胜蓝”、“春草绿时连梦泽，夕波红处近长安”、“绿浪东西南北水，红栏三百九十桥”。因而江南的春色，在白居易的笔下，从初日，江花，江水之中获得了色彩，又因烘染、映衬的手法而形成了人们想象中的图画，色彩绚丽耀眼，层次丰富，几乎无需更多联想，江南春景已跃然眼前。\n\n　　此词写江南春色，首句“江南好”，以一个既浅切又圆活的“好”字，摄尽江南春色的种种佳处，而作者的赞颂之意与向往之情也尽寓其中。同时，唯因“好”之已甚，方能“忆”之不休，因此，此句又已暗逗结句“能不忆江南”，并与之相关阖。次句“风景旧曾谙”，点明江南风景之“好”，并非得之传闻，而是作者出牧杭州时的亲身体验与亲身感受。这就既落实了“好”字，又照应了“忆”字，不失为勾通一篇意脉的精彩笔墨。三、四两句对江南之“好”进行形象化的演绎，突出渲染江花、江水红绿相映的明艳色彩，给人以光彩夺目的强烈印象。其中，既有同色间的相互烘托，又有异色间的相互映衬，充分显示了作者善于着色的技巧。篇末，以“能不忆江南”收束全词，既托出身在洛阳的作者对江南春色的无限赞叹与怀念，又造成一种悠远而又深长的韵味，把读者带入余情摇漾的境界中。', poem_tags = '宋词三百首,小学古诗,婉约,景点,早教古诗100首' WHERE poem_title = '忆江南·江南好' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '清晨的微雨湿润了渭城地面的灰尘，馆驿青堂瓦舍柳树的枝叶翠嫩一新。\n真诚地奉劝我的朋友再干一杯美酒，向西出了阳关就难以遇到故旧亲人。', poem_notes = '渭城曲：另题作《送元二使安西》，或名《阳关曲》或《阳关三叠》。\n渭城：在今陕西省西安市西北，即秦代咸阳古城。浥（yì）：润湿。\n客舍：旅馆。柳色：柳树象征离别。\n阳关：在今甘肃省敦煌西南，为自古赴西北边疆的要道。', poem_appreciation = '此诗以“渭城曲”为题载于《全唐诗》卷一百二十八。下面是唐代文学研究会常务理事、李商隐研究会会长刘学锴先生对此诗的赏析。\n\n　　此诗前两句写送别的时间，地点，环境气氛。清晨，渭城客舍，自东向西一直延伸、不见尽头的驿道，客舍周围、驿道两旁的柳树。这一切，都仿佛是极平常的眼前景，读来却风光如画，抒情气氛浓郁。“朝雨”在这里扮演了一个重要的角色。早晨的雨下得不长，刚刚润湿尘土就停了。从长安西去的大道上，平日车马交驰，尘上飞扬，朝雨乍停，天气晴朗，道路显得洁净、清爽。“浥轻尘”的“浥”字是湿润的意思，在这里用得很有分寸，显出这雨澄尘而不湿路，恰到好处，仿佛天从人愿，特意为远行的人安排一条轻尘不扬的道路。客舍，本是羁旅者的伴侣；杨柳，更是离别的象征。选取这两件事物，自然有意关合送别。它们通常总是和羁愁别恨联结在一起而呈现出黯然销魂的情调。而今天，却因一场朝雨的洒洗而别具明朗清新的风貌──“客舍青青柳色新”。平日路尘飞扬，路旁柳色不免笼罩着灰蒙蒙的尘雾，一场朝雨，才重新洗出它那青翠的本色，所以说“新”，又因柳色之新，映照出客舍青青来。总之，从清朗的天宇，到洁净的道路，从青青的客舍，到翠绿的杨柳，构成了一幅色调清新明朗的图景，为这场送别提供了典型的自然环境。这是一场深情的离别，但却不是黯然销魂的离别。相反地，倒是透露出一种轻快而富于希望的情调。“轻尘”、“青青”、“新”等词语，声韵轻柔明快，加强了读者的这种感受。\n\n　　绝句在篇幅上受到严格限制。这首诗，对如何设宴饯别，宴席上如何频频举杯，殷勤话别，以及启程时如何依依不舍，登程后如何瞩目遥望等等，一概舍去，只剪取饯行宴席即将结束时主人的劝酒辞：再干了这一杯吧，出了阳关，可就再也见不到老朋友了。诗人像高明的摄影师，摄下了最富表现力的镜头。宴席已经进行了很长一段时间，酿满别情的酒已经喝过多巡，殷勤告别的话已经重复过多次，朋友上路的时刻终于不能不到来，主客双方的惜别之情在这一瞬间都到达了顶点。主人的这句似乎脱口而出的劝酒辞就是此刻强烈、深挚的惜别之情的集中表现。\n\n　　三四两句是一个整体。要深切理解这临行劝酒中蕴含的深情，就不能不涉及“西出阳关”。处于河西走廊尽西头的阳关，和它北面的玉门关相对，从汉代以来，一直是内地出向西域的通道。唐代国势强盛，内地与西域往来频繁，从军或出使阳关之外，在盛唐人心目中是令人向往的壮举。但当时阳关以西还是穷荒绝域，风物与内地大不相同。朋友“西出阳关”，虽是壮举，却又不免经历万里长途的跋涉，备尝独行穷荒的艰辛寂寞。因此，这临行之际“劝君更尽一杯酒”，就像是浸透了诗人全部丰富深挚情谊的一杯浓郁的感情琼浆。这里面，不仅有依依惜别的情谊，而且包含着对远行者处境、心情的深情体贴，包含着前路珍重的殷勤祝愿。对于送行者来说，劝对方“更尽一杯酒”，不只是让朋友多带走自己的一分情谊，而且有意无意地延宕分手的时间，好让对方再多留一刻。“西出阳关无故人”之感，不只属于行者。临别依依，要说的话很多，但千头万绪，一时竟不知从何说起。这种场合，往往会出现无言相对的沉默，“劝君更尽一杯酒”，就是不自觉地打破这种沉默的方式，也是表达此刻丰富复杂感情的方式。诗人没有说出的比已经说出的要丰富得多。总之，三四两句所剪取的虽然只是一刹那的情景，却是蕴含极其丰富的一刹那。\n\n　　这首诗所描写的是一种最有普遍性的离别。它没有特殊的背景，而自有深挚的惜别之情，这就使它适合于绝大多数离筵别席演唱，后来编入乐府，成为最流行、传唱最久的歌曲。', poem_tags = '唐诗三百首,小学古诗,初中古诗,乐府,友情,送别,早教古诗100首' WHERE poem_title = '送元二使安西 / 渭城曲' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '在大道施行的时候，天下是人们所共有的，把品德高尚的人、能干的人选拔出来，讲求诚信，培养和睦（气氛）。所以人们不单奉养自己的父母，不单抚育自己的子女，要使老年人能终其天年，中年人能为社会效力，幼童能顺利地成长，使老而无妻的人、老而无夫的人、幼年丧父的孩子、老而无子的人、残疾人都能得到供养。男子有职务，女子有归宿。对于财货，人们憎恨把它扔在地上的行为，却不一定要自己私藏；人们都愿意为公众之事竭尽全力，而不一定为自己谋私利。因此奸邪之谋不会发生，盗窃、造反和害人的事情不发生。所以大门都不用关上了，这叫做理想社会。', poem_notes = '选自《礼记·礼运》。《礼记》，儒家经典之一，西汉戴圣对秦汉以前各种礼仪论著加以辑录、编纂而成，共49篇。礼 运，《礼记》篇名，大约是战国末年或秦汉之际儒家学者托名孔子答问的著作。大道，指古代政治上的最高理想。 行：施行。\n大道：古代指政治上的最高理想。\n之行：之，助词取消句子之间的独立性。行，施行\n为：是，表判断。\n〔选贤与(jǔ)能〕把品德高尚的人、能干的人选拔出来。与，通“举”，推举，选举。\n〔讲信修睦(mù)〕讲求诚信，培养和睦(气氛)。 信：诚信。修：培养。\n独：单独。\n〔亲〕意动用法，用如动词，以……为亲，抚养。下文“子其子”中的第一个“子”也是动词。\n亲其亲：第一个亲，名词的意动用法，以……为亲人；第二个亲，父母。\n终：终老，终其天年。\n养：供养。\n有所养：得到供养。\n〔矜(guān)、寡、孤、独、废疾者〕矜，老而无妻的人。矜，通“鳏”。寡，老而无夫的人。孤，幼而无父的人。独，老而无子的人。废疾，残疾人。\n〔男有分(fèn)〕男子有职务。分，职分，指职业、职守。\n〔女有归〕意思是女子有归宿。归，指女子出嫁。\n〔货恶(wù)其弃于地也，不必藏于己〕意思是，对于财货，人们憎恨把它扔在地上的行为，却不一定要自己私藏。恶（wù），憎恶。 藏：私藏。于：在。货恶：宾语前置。\n〔力恶其不出于身也，不必为己〕意思是，人们都愿意为公众之事竭尽全力，而不一定为自己谋私利。力恶：宾语前置。\n是故：即“故是”，可译为“因此”“所以”“这样一来”。\n〔谋闭而不兴〕奸邪之谋不会发生。闭，杜绝。兴，发生。\n〔盗窃乱贼而不作〕盗窃、造反和害人的事情不发生。乱，指造反。贼，指害人。作，兴起。\n 故：所以。\n〔外户〕泛指大门。\n 而〔是故谋闭而不兴〕：连词，表并列。\n〔闭〕用门闩插门。\n 谓：是。\n〔大同〕指理想社会。同，有和平的意思。\n\n重点注释\n1、 课文中所提到的“大道“、“大同“各指什么，我们应该如何理解和认识？\n答：文中“大道“就是指治理社会的最高准则，其治理的效果就是国泰民安的理想状态。 　“大同“可以理解为儒家的理想社会或是人类社会的最高阶段。 　“大道“和“大同“都是当时人们头脑中的理想境界，两个词中带有明显的理想色彩，寄托着人们对未来生活的美好向往。\n2.．本文从哪三个方面来说明“大同”社会的基本特征的？答：①人人都能受到全社会的关爱；②人人都能安居乐业；③人人都珍惜劳动成果，却毫无自私自利之心。（物尽其用，人尽其力）\n3、 怎样理解孔子关于“大同“社会的思想？ 　答：“大同“社会是夏以前的社会形态，过去有“孔子以五帝之世为大同“的说法。由此可见，“大同“社会是以“五帝之世“的传说为依据，经过加工提炼而后构想出来的一个理想社会模式，孔子的原意是建立一个合理的社会，以消除现实社会中的黑暗现象和不合理的地方，因此，孔子“大同“理想社会源自于“五帝之世“，同时又高于“五帝之世“。\n4、“故人不独亲其亲，不独子其子，使老有所终，壮有所用，幼有所长，鳏、寡、孤、独、废疾者皆有所养，男有分，女有归。”同《孟子》中的哪句名言有异曲同工之妙？ 　答：“老吾老以及人之老； 幼吾幼以及人之幼。“\n5.文章表达了作者怎样的思想感情? 　答：文章表达了作者迫切希望出现一个太平盛世的思想感情。\n6、写出表现人人都能关爱他人，人人都能得到他人关爱、能安居乐业的句子？ 　③故（16）人不独（17）亲④其亲（18），不独子其子，⒂使老有所终，壮有所用，幼有所长，鳏、寡、孤、独、废疾者⑤皆有所养（19），男有分，⑥女有归。\n7，《大道之行也》中与“路不拾遗,夜不闭户”的意思相同的是哪一句？ 　是故谋闭而不兴，盗窃乱贼而不作，故外户而不闭，是谓大同\n一、“大道”“大同”都属于特殊概念：“大道”，政治上的最高理想，指放之四海而皆准的道理或真理，可以有各种各样的解释；“大同”，指儒家的理想社会或人类社会的最高阶段，也可以有种种解释。这一类字眼是不能翻译也是译不好的。\n二、有些词语在一定语境中往往具有特殊含义，如“归”指女子出嫁，但在“男有分，女有归”这句话中就有了“及时婚配”的意思；“亲”有亲近义，但“亲其亲”跟“子其子”是对文，前一个“亲”就有了“奉养”义，后一个“亲”就专指父母了。\n三、文中凡能直译的语句一概用直译，但也有一些地方用了意译。\n与：通“举”，推举，选举。\n谋：谋划，指不好的东西\n贼，盗窃，这里引伸为指害人。', poem_appreciation = '天下为公 发音 tiān xià wéi gōng 解释 原意是不把君位当做一家的私有物。旧民主主义革命时期孙中山借用来作为对“民权主义”的解释，意思是政权为一般平民所公有。 出处 《礼记·礼运》：“大道之行也，天下为公。” 示例 《礼记·礼运》：“大道之行也，天下为公。” 万古千秋业，～器。陈毅《湖海诗社开征引》诗 【近义词】：天下一家 【反义词】：天下为家 【语法】：主谓式；作谓语、定语；用于人\n\n不独亲其亲，不独子其子 【近义词】：老吾老以及人之老，幼吾幼以及人之幼。\n\n老有所终 发音 lǎo yǒu suǒ zhōng 解释 年老者能有个合适的归宿。 出处 《礼记·礼运》：“故人不独亲其亲，不独子其子，使老有所终，壮有所用，幼有所长，矜寡孤独，废疾者，皆有所养。”\n\n矜（鳏）寡孤独 发音 guān guǎ gū dú 解释 泛指没有劳动力而又没有亲属供养的人。（让年老的各有适当的归宿，年轻的各有一定的用处，年幼的各有应得的成长条件，鳏寡孤独和废疾人，都有受到赡养的权利。这是儒家设想的所谓“大同世界”的景象。） 出处 《礼记·礼运》：“矜寡孤独，废疾者，皆有所养。” 概况 释义 ：天下是天下人的天下，为大家所共有，天子之位，传贤而不传子，只有实现天下为公，彻底铲除私天下带来的社会弊端，才能使社会充满光明，百姓得到幸福。后成为一种美好社会的政治理想。 成语：物尽其用 【解释】：各种东西凡有可用之处，都要尽量利用。指充分利用资源，一点不浪费。 【示例】：这家化工厂大搞综合利用，做到了变废为宝，物尽其用。 【近义词】：人尽其才 【语法】：紧缩式；作宾语、定语；含褒义 【翻译】：to make the best use of everything; to let all things serve their proper purpose', poem_tags = '初中文言文,理想,生活,哲理' WHERE poem_title = '大道之行也' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '依旧是秦汉时期的明月和边关，守边御敌鏖战万里征人未回还。\n倘若龙城的飞将卫青如今还在，绝不许匈奴南下牧马度过阴山。', poem_notes = '但使：只要。\n龙城飞将：《汉书·卫青霍去病传》载，元光六年（前129年），卫青为车骑将军，出上谷，至笼城，斩首虏数百。笼城，颜师古注曰：“笼”与“龙”同。龙城飞将指的是卫青奇袭龙城的事情。其中，有人认为龙城飞将中飞将指的是汉飞将军李广，龙城是唐代的卢龙城（卢龙城就是汉代的李广练兵之地，在今河北省喜峰口附近一带，为汉代右北平郡所在地），纵观李广一生主要的时间都在抗击匈奴，防止匈奴掠边，其中每次匈奴重点进攻的汉地天子几乎都是派遣李广为太守，所以这种说法也不无道理。\n不教：不叫，不让。教，让。\n胡马：指侵扰内地的外族骑兵。\n度：越过。在漫长的边防线上，战争一直没有停止过，去边防线打仗的战士也还没有回来。 要是攻袭龙城的大将军卫青和飞将军李广今天还依然健在，绝不会让敌人的军队翻过阴山。', poem_appreciation = '本诗被人们称为：“唐朝七绝之首”。\n\n　　这是一首慨叹边战不断，国无良将的边塞诗。诗的首句最耐人寻味。说的是此地汉关，明月秦时，大有历史变换，征战未断的感叹。二句写征人未还，多少儿男战死沙场，留下多少悲剧。三、四句写出千百年来人民的共同意愿，冀望有“龙城飞将”出现，平息胡乱，安定边防。全诗以平凡的语言，唱出雄浑豁达的主旨，气势流畅，一气呵成，吟之莫不叫绝。明人李攀龙曾推奖它是唐代七绝压卷之作，实不过分。\n\n　　塞当作求取功名的一种出路。一些大都有边塞生活经历的知识分子，他们的诗歌以描写边塞生活为主要内容，这就形成了所谓“边塞诗派”。 王昌龄是这个流派中的重要成员。\n\n　　诗从写景入手。“秦时明月汉时关”，皓月当空，照耀着万里边疆的关塞，显示了边疆的寥廓和景物的萧条。在“月”和“关”的前面用“秦汉时”加以修饰，使意境更加高远，把我们引到了遥远的古代，更引人深思：秦汉以来边防战争连续不断，一直持续至今，真是拖得太久了！这是从时间上描写边塞的悠久。\n\n　　面对这样的景象，边人触景生情，自然联想起秦汉以来无数献身边疆、至死未归的人们。“万里长征人未还”，又从空间角度点明边塞的遥远。这里的“人”，既是指已经战死的士卒，也指还在戍守不能回归的士卒。“人未还”，一是说明边防不巩固，二是对士卒表示同情。这本是一个问题的两个方面，前者是因，后者是果。这是从秦到汉乃至于唐代，都没有解决的大问题，怎样来解决这个问题呢？第三、四两句就是诗人的回答。\n\n　　“但使龙城飞将在，不教胡马度阴山”，直接抒发了边防士卒巩固边防的愿望和保卫国家的壮志：只要有卫青李广那样的名将，敌人的马队就不会度过阴山。这两句写得意在言外。意思就是说：由于朝廷用人不当，使将帅不得其人，才造成了烽火长燃、征人不还的局面。\n\n　　这首诗虽然只有短短四行，但是通过对边疆景物和征人心理的描绘，表现的内容是复杂的。既有对久戍士卒的浓厚同情和结束这种边防不顾局面的愿望；又流露了对朝廷不能选贤任能的不满，同时又以大局为重，认识到战争的正义性，因而个人利益服从国家安全的需要，发出了“不教胡马度阴山”的誓言，洋溢着爱国激情。\n\n　　诗人并没有对边塞风光进行细致的描绘，他只是选取了征戍生活中的一个典型画面来揭示士卒的内心世界。景物描写只是用来刻画人物思想感情的一种手段，汉关秦月，无不是融情入景，浸透了人物的感情色彩。把复杂的内容熔铸在四行诗里，深沉含蓄，耐人寻味。这首诗意境雄浑，格调昂扬，语言凝炼明快。', poem_tags = '唐诗三百首,边塞,写景,战争,爱国,忧国忧民,早教古诗100首' WHERE poem_title = '出塞二首·其一' AND poem_author = '王昌龄';
UPDATE edu_poem SET poem_translation = '有位卖炭的老翁，整年在南山里砍柴烧炭。\n他满脸灰尘，显出被烟熏火燎的颜色，两鬓头发灰白，十个手指也被炭烧得很黑。\n卖炭得到的钱用来干什么？买身上穿的衣裳和嘴里吃的食物。\n可怜他身上只穿着单薄的衣服，心里却担心炭卖不出去，还希望天更寒冷。\n夜里城外下了一尺厚的大雪，清晨，老翁驾着炭车碾轧冰冻的车轮印往集市上赶去。\n牛累了，人饿了，但太阳已经升得很高了，他们就在集市南门外泥泞中歇息。\n那得意忘形的骑着两匹马的人是谁啊？是皇宫内的太监和太监的手下。\n太监手里拿着文书，嘴里却说是皇帝的命令，吆喝着牛朝皇宫拉去。\n一车的炭，一千多斤，太监差役们硬是要赶着走，老翁是百般不舍，但又无可奈何。\n那些人把半匹红纱和一丈绫，朝牛头上一挂，就充当炭的价钱了。', poem_notes = '卖炭翁：此篇是组诗《新乐府》中的第32首，题注云：“苦宫市也。”宫市，指唐代皇宫里需要物品，就向市场上去拿，随便给点钱，实际上是公开掠夺。唐德宗时用太监专管其事。\n伐：砍伐。薪：柴。南山：城南之山。\n烟火色：烟熏色的脸。此处突出卖炭翁的辛劳。\n苍苍：灰白色，形容鬓发花白。\n得：得到。何所营：做什么用。营，经营，这里指需求。\n可怜：使人怜悯。\n愿：希望。\n晓：天亮。辗（niǎn）：同“碾”，压。辙：车轮滚过地面辗出的痕迹。\n困：困倦，疲乏。\n市：长安有贸易专区，称市，市周围有墙有门。\n翩翩：轻快洒脱的情状。这里形容得意忘形的样子。骑（jì）：骑马的人。\n黄衣使者白衫儿：黄衣使者，指皇宫内的太监。白衫儿，指太监手下的爪牙。\n把：拿。称：说。敕（chì）：皇帝的命令或诏书。\n回：调转。叱：喝斥。牵向北：指牵向宫中。\n千余斤：不是实指，形容很多。\n驱：赶着走。将：语助词。惜不得：舍不得。得，能够。惜，舍。\n半匹红绡一丈绫：唐代商务交易，绢帛等丝织品可以代货币使用。当时钱贵绢贱，半匹纱和一丈绫，比一车炭的价值相差很远。这是官方用贱价强夺民财。\n系（jì）：绑扎。这里是挂的意思。直：通“值”，指价格。', poem_appreciation = '现实意义 　　白居易在《新乐府》中每首诗的题目下面都有一个序，说明这首诗的主题。《卖炭翁》的序是“苦宫市也”，就是要反映宫市给人民造成的痛苦。唐代皇宫里需要物品，就派人去市场上拿，随便给点钱，实际上是公开掠夺。唐德宗时用太监专管其事。白居易写作《新乐府》是在宫市为害最深的时候，他对宫市有十分的了解，对人民又有深切的同情，所以才能写出这首感人至深的《卖炭翁》来。这首诗的意义，远不止于对宫市的揭露。诗人在卖炭翁这个典型形象上，概括了唐代劳动人民的辛酸和悲苦，在卖炭这一件小事上反映出了当时社会的黑暗和不平。读着这首诗，读者所看到的决不仅仅是卖炭翁一个人，透过他，还能看到有许许多多种田的、打渔的、织布的人出现在眼前。他们虽然不是“两鬓苍苍十指黑”，但也各自带着劳苦生活的标记；他们虽然不会因为卖炭而受到损害，但也各自在田租或赋税的重压下流着辛酸和仇恨的泪水。《卖炭翁》这首诗不但在当时有积极意义，即使对于今天的读者也有一定的教育作用。 ▲', poem_tags = '冬天,乐府' WHERE poem_title = '卖炭翁' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '江南大地鸟啼声声绿草红花相映，水边村寨山麓城郭处处酒旗飘动。\n南朝遗留下的四百八十多座古寺，无数的楼台全笼罩在风烟云雨中。', poem_notes = '莺啼：即莺啼燕语。\n郭：外城。此处指城镇。\n酒旗：一种挂在门前以作为酒店标记的小旗。\n南朝：指先后与北朝对峙的宋、齐、梁、陈政权。\n四百八十寺：南朝皇帝和大官僚好佛，在京城（今南京市）大建佛寺。这里说四百八十寺，是虚数。\n楼台：楼阁亭台。此处指寺院建筑。\n烟雨：细雨蒙蒙，如烟如雾。', poem_appreciation = '首句“千里莺啼绿映红”，一开始就展现了江南大自然风光。“千里”是对广阔的江南的概括。这里到处是莺啼，无边的绿叶映衬着鲜艳的红花。这种有声有色、生机勃勃的景色自然是江南特有的。次句“水村山郭酒旗风”写了江南独特的地形风貌，临水有村庄，依山有城郭，在春天的和风中，酒旗在轻轻地招展。这是多么明丽的江南啊！\n\n　　一二句写的是晴景，三四句写的是雨景。“南朝四百八十寺，多少楼台烟雨中。”在春天的微雨中，则另有一番风光。在山明水秀之处，还有南朝遗留下来的数以百计的佛寺。这些金碧辉煌、屋宇重重的佛寺，被迷蒙的烟雨笼罩着，若隐若现，似有似无，给江南的春天更增添了朦胧迷离的色彩。“四百八十”是虚数，不是实指，突出佛寺之多，讽刺了皇帝依赖佛教。其中应指现存于江阴青阳镇的悟空寺。\n\n　　全诗以高度概括的笔法，勾勒了江南地区的风物，描绘了江南明丽而迷蒙的春景。色彩鲜明，情味隽永。一首七言绝句，能展现出这样一幅广阔的画卷，真可谓“尺幅千里”了。\n\n　　同时杜牧还留下了一首《芙蓉湖》），赞誉江阴美景：\n\n　　丹树村边烟火微，碧波深处雁初飞。萧条落叶垂杨岸，隔水寥寥闻捣衣。', poem_tags = '春天,写景,寺庙,抒情' WHERE poem_title = '江南春' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '黄河好像从白云间奔流而来，玉门关孤独地耸峙在高山中。\n将士何须哀怨那柳树不发芽，春风根本吹不到玉门关外。\n\n译文二\n纵目望去，黄河渐行渐远，好像奔流在缭绕的白云中间，就在黄河上游的万仞高山之中，一座孤城玉门关耸峙在那里，显得孤峭冷寂。\n何必用羌笛吹起那哀怨的杨柳曲去埋怨春光迟迟不来呢，原来玉门关一带春风是吹不到的啊！', poem_notes = '凉州词：又名《出塞》。为当时流行的一首曲子（《凉州词》）配的唱词。\n原题二首，此其一，郭茂倩《乐府诗集》卷七十九《近代曲词》载有《凉州歌》，并引《乐苑》云：“《凉州》，宫调曲，开元中西凉府都督郭知运进”。凉州，唐陇右道凉州治所在姑臧县（今甘肃省武威市凉州区）。\n远上；远远向西望去。“远”一作“直”。\n黄河远上：远望黄河的源头。\n孤城：指孤零零的戍边的城堡。\n仞：古代的长度单位，一仞相当于七尺或八尺(等于231cm或264cm,约等于2.3m或2.6m)。\n羌笛：古羌族主要分布在甘、青、川一带。羌笛是羌族乐器，属横吹式管乐。属于一种乐器。\n何须：何必。何须怨：何必埋怨。\n杨柳：杨树的柳条，又指的是《杨柳曲》。\n度：吹到过。不度：吹不到\n玉门关：汉武帝置，因西域输入玉石取道于此而得名。故址在今甘肃敦煌西北小方盘城,是古代通往西域的要道。六朝时关址东移至今安西双塔堡附近。', poem_appreciation = '据唐人薛用弱《集异记》记载：开元（唐玄宗年号，公元713—741年）间，王之涣与高适、王昌龄到旗亭饮酒，遇梨园伶人唱曲宴乐，三人便私下约定以伶人演唱各人所作诗篇的情形定诗名高下。王昌龄的诗被唱了两首，高适也有一首诗被唱到，王之涣接连落空。轮到诸伶中最美的一位女子演唱了，她所唱则为“黄河远上白云间”。王之涣甚为得意。这就是著名的“旗亭画壁”故事。此事未必实有。但表明王之涣这首诗在当时已成为广为传唱的名篇。\n\n　　诗的前两句描绘了西北边地广漠壮阔的风光。首句抓住自下（游）向上（游）、由近及远眺望黄河的特殊感受，描绘出“黄河远上白云间”的动人画面：汹涌澎湃波浪滔滔的黄河竟象一条丝带迤逦飞上云端。写得真是神思飞跃，气象开阔。诗人的另一名句“黄河入海流”，其观察角度与此正好相反，是自上而下的目送；而李白的“黄河之水天上来”，虽也写观望上游，但视线运动却又由远及近，与此句不同。“黄河入海流”和“黄河之水天上来”，同是着意渲染黄河一泻千里的气派，表现的是动态美。而“黄河远上白云间”，方向与河的流向相反，意在突出其源远流长的闲远仪态，表现的是一种静态美。同时展示了边地广漠壮阔的风光，不愧为千古奇句。\n\n　　次句“一片孤城万仞山”出现了塞上孤城，这是此诗主要意象之一，属于“画卷”的主体部分。“黄河远上白云间”是它远大的背景，“万仞山”是它靠近的背景。在远川高山的反衬下，益见此城地势险要、处境孤危。“一片”是唐诗习用语词，往往与“孤”连文（如“孤帆一片”、“一片孤云”等等），这里相当于“一座”，而在词采上多一层“单薄”的意思。这样一座漠北孤城，当然不是居民点，而是戌边的堡垒，同时暗示读者诗中有征夫在。“孤城”作为古典诗歌语汇，具有特定涵义。它往往与离人愁绪联结在一起，如“夔府孤城落日斜，每依北斗望京华”（杜甫《秋兴》）、“遥知汉使萧关外，愁见孤城落日边”（王维《送韦评事》）等等。第二句“孤城”意象先行引入，为下两句进一步刻划征夫的心理作好了准备。\n\n　　诗起于写山川的雄阔苍凉，承以戌守者处境的孤危。第三句忽而一转，引入羌笛之声。羌笛所奏乃《折杨柳》曲调，这就不能不勾起征夫的离愁了。此句系化用乐府《横吹曲辞·折杨柳歌辞》“上马不捉鞭，反折杨柳枝。蹀座吹长笛，愁杀行客儿”的诗意。折柳赠别的风习在唐时最盛。“杨柳”与离别有更直接的关系。所以，人们不但见了杨柳会引起别愁，连听到《折杨柳》的笛曲也会触动离恨。而“羌笛”句不说“闻折柳”却说“怨杨柳”，造语尤妙。这就避免直接用曲调名，化板为活，且能引发更多的联想，深化诗意。玉门关外，春风不度，杨柳不青，离人想要折一枝杨柳寄情也不能，这就比折柳送别更为难堪。征人怀着这种心情听曲，似乎笛声也在“怨杨柳”，流露的怨情是强烈的，而以“何须怨”的宽解语委婉出之，深沉含蓄，耐人寻味。这第三句以问语转出了如此浓郁的诗意，末句“春风不度玉门关”也就水到渠成。用“玉门关”一语入诗也与征人离思有关。《后汉书·班超传》云：“不敢望到酒泉郡，但愿生入玉门关。”所以末句正写边地苦寒，含蓄着无限的乡思离情。如果把这首《凉州词》与中唐以后的某些边塞诗（如张乔《河湟旧卒》）加以比较，就会发现，此诗虽极写戌边者不得还乡的怨情，但写得悲壮苍凉，没有衰飒颓唐的情调，表现出盛唐诗人广阔的心胸。即使写悲切的怨情，也是悲中有壮，悲凉而慷慨。“何须怨”三字不仅见其艺术手法的委婉蕴藉，也可看到当时边防将士在乡愁难禁时，也意识到卫国戌边责任的重大，方能如此自我宽解。也许正因为《凉州词》情调悲而不失其壮，所以能成为“唐音”的典型代表。', poem_tags = '唐诗三百首,边塞,写景,将士,思乡,早教古诗100首' WHERE poem_title = '凉州词二首·其一' AND poem_author = '王之涣';
UPDATE edu_poem SET poem_translation = '我年幼时就非常爱好读书。（因为）家里贫穷，（所以）没有办法买书来阅读，常常向藏书的人家去借，亲自抄录，计算着日期按时送还。冬天非常寒冷，砚台里的墨汁像冰一样坚硬，手指（冻得）不能弯曲伸直，也不敢懈怠。抄完后，便马上跑去还书，不敢稍微超过约定的期限。因此有很多人都愿意把书借给我，于是我能够遍观群书。到了成年以后，我更加仰慕古代圣贤的学说，又担心没有才学渊博的人同我来往，曾经跑到百里以外，拿着经书向乡里有道德学问的前辈请教。前辈道德和声望高，门人弟子挤满了他的屋子，他不曾把言辞放委婉些，把脸色放温和些。我站着侍候在他左右，提出疑难，询问道理，俯下身子，侧着耳朵请教；有时遇到他大声斥责，（我的）表情更加恭顺，礼节更加周到，不敢说一个字反驳；等到他高兴了，则又去请教。所以我虽然愚笨，但最终获得学识。\n　　当我外出求师的时候，背着书箱，拖着鞋子，行走在深山峡谷之中。隆冬时节，刮着猛烈的寒风，雪有好几尺深，脚上的皮肤都冻裂却不知道。回到旅舍，四肢僵硬动弹不得。服侍的仆人拿着热水（为我）浇洗，用被子裹着我，很久才暖和起来。我寄住在旅舍，旅店老板每天提供两顿伙食，没有新鲜肥美的东西来享用。与我同住别的同学都穿着华丽的衣服，戴着用红色帽带和珠宝装饰的帽子，腰间系着白玉制成的环，左边佩戴宝刀，右边挂着香囊，光鲜亮丽好像神仙一样；我却穿着破破烂烂的衣服和他们生活在一起，但我毫无羡慕的心。因为心中有足以快乐的事情，所以不觉得吃的、穿的享受不如别人。我求学的辛勤和艰苦就是像这个样子啊!', poem_notes = '选自《宋学士文集》（上海古籍出版社1985年版）。\n宋濂：（1310-1381）字景濂，号潜溪，浦江（今浙江义乌西北），明初文学家。\n东阳，地名，在今浙江东阳。 \n生，长辈对晚辈的称呼。\n序：文体名，这是一篇赠序\n余：我。\n嗜：喜欢、特别爱好。\n无从：没有办法。\n致书：得到书。致：得到。\n每假借于藏书之家，手自笔录：每：常常。\n假借：同义复合词。 借。\n假，借。\n于：介词，从。\n笔：名词作状语，用笔。\n手：名词活用为动词，动手。\n弗之怠(dài)：即弗怠之，不懈怠，不放松读书。\n弗：不。之：指代抄书。\n走：跑。\n逾约：超过约定的期限。\n以是：因此。以：以为；是：这样。\n加冠（guān）：古代男子二十岁举行加冠礼，表示已经成人。\n后人常用“冠”或“加冠”表示年已二十。\n患：担心。.\n硕师：学问渊博的老师。\n硕，大。\n游：交往。\n尝：曾经。\n趋：赶到。\n从乡之先达执经叩问：拿着经书向当地有道德有学问的前辈请教。\n先达：有道德有学问的前辈。叩，请教。\n执：拿着\n德隆望尊：道德声望高。\n望，声望，名望。\n隆：高。\n门人弟子填其室：学生挤满了他的屋子。\n门人、弟子，学生。\n填，充。这里是拥挤的意思。\n稍降辞色：把言辞放委婉些，把脸色放温和些。\n辞色，言语和脸色。色：脸色。\n援疑质理：提出疑难，询问道理。\n援，提出。\n质，询问。\n俯身倾耳以请：弯下身子，侧着耳朵（恭敬地）请教（表现尊敬而专心）。\n以：连词，而，来。\n或：有时。\n叱(chì)咄(duō)：训斥，呵责。\n色愈恭：表情更加恭顺。色：表情。 恭：恭敬\n至：周到。\n复：这里指辩解，反驳。\n俟（sì）：等待。\n卒：最终。\n负箧（qiè）曳屣（yè xǐ）：背着书箱，拖着鞋子（表示鞋破）。\n曳：拖。\n箧：书箱。\n屣：鞋。\n穷冬：隆冬。\n皲（jūn）裂：皮肤因寒冷干燥而开裂。\n舍：指学舍，书馆。\n支：通“肢”，肢体。\n媵（yìng）人：这里指服侍的人。\n汤：热水。\n沃灌：洗浴。沃，浇水洗（四肢）。灌通“盥”。\n衾（qīn）：被子。\n拥：盖着。\n而：表承接。\n乃：才。\n日再食（SI）：每天供应两顿饭。再：两次。\n寓逆旅：寄居在旅店里。\n寓，寄居。\n逆，迎。\n逆旅，旅店。\n被（pī）绮（qǐ）绣：穿着漂亮的丝绸衣服。\n被，通“披”，穿着。\n朱缨：红色的帽带。\n缨：帽带。\n腰：腰佩。\n腰，名词作动词。\n容臭（xiù）：香袋。\n臭，气味，这里指香气。\n烨（yè）然：光彩照人的样子。\n缊（yùn）袍敝（bì）衣：破旧的衣服。\n缊，旧絮。敝，破旧。\n略无慕艳意：毫无羡慕的意思。\n略无：毫无。\n慕艳，羡慕。\n以中有足乐者，不知口体之奉不若人也：因为内心有足以快乐的事（指读书），不觉得吃的穿的不如别人。\n中：内心。\n口体之奉：指吃的穿的。\n盖：发语词，用来引领一句话，常是感慨或议论之类的，属语气助词；翻译为“大概”。', poem_appreciation = '宋濂少时勤苦好学，元时曾受业于文豪吴莱、柳贯、黄之门，得其薪传。于书无所不窥；自少至老，未尝一日释卷，故学识、文才俱登峰造极。及事明太祖，凡国家祭祀、朝会、诏谕、封赐之文，多出其手。相传明太祖尝以文学之臣问于刘基，基对曰：“当今文章第一，舆论所属，实在翰林学士臣濂，华夷无间言者。其次臣基，不敢他有听让。”（《跋张孟兼文稿序后》）当时日本、高丽使臣来京朝贡者，每问“宋先生安否”，且以重金购其文集而归。著有《宋学士集》《宋文宪全集》并行于世。宋濂文雍容高华，醇厚演迤，而多变化。《四库全书总目提要》谓：“濂文雍容浑穆，如天闲良骥，鱼鱼雅雅，自中节度。”刘基于其所著《宋景濂学士文集序》中引欧阳玄赞濂之言曰：“先生天分极高，极天下之书无不尽读；以其所蕴，大肆厥辞。其气韵沈雄，如淮阴出师，百战百胜，志不少慑；其神思飘逸，如列子御风，飘然骞举，不沾尘土；其词调清雅，如殷卣周彝，龙纹漫灭，古意独存。其态度多变，如晴霁终南，众驺前陈，应接不暇，非具众长，识迈千古，安能与此!”他在文学上主张崇实务本，“必有其实，而后文随之”；强调“随物赋形”、“人能养气则情深文明，气盛而化神”（《文原》）。著名篇章有《秦士录》《王冕传》《胡长孺传》《李疑传》《环翠亭记》《看松庵记》等，《送东阳马生序》也是他的代表作之一。\n\n　　叙自己“为学之难”，先揭示“嗜学，家贫”的主客观情况。“嗜学”，有强烈的读书愿望，浓烈的读书兴趣，而“家贫”则无力购书，无资聘师，无法结友。在这种处境下，唯有靠自己的“专心”、“劳苦”予以克服。作者先叙无书之苦。“家贫，无从致书以观”，好读书却买不起书，只有走借书之途。再写借书之难，借来的书，不能污损，不可久待，只有“手自笔录，计日以还”。为了不逾约，即使是“天大寒”，“砚冰坚，手指不可屈伸”，也“弗之怠”，仍要“笔录”。复写求师之艰。先写“从乡之先达执经叩问”，“尝趋百里外”求教，不辞劳苦。乡贤因门人弟子众多，对他“未尝稍降辞色”，他不因冷遇而灰心，不因疏淡而反感，相反的却是“俯身倾耳以请”；甚至会遇到“叱咄”，而他却“色愈恭，礼愈至，不敢出一言以复”，“俟其欣悦，则又请焉”。乡先达的态度愈差，他的态度却愈敬，可见求知的心诚。再写外出从师的“勤且艰”。“负箧曳屣行深山巨谷中，穷冬烈风，大雪深数尺”，道路、环境、季节、气候，都极恶劣，而他“足肤皲裂”、“四肢僵劲”，则置天寒地冻于不顾，山高路远而不管。对于衣、食、住也不讲究。寄居旅舍，一天两顿饭，无甘美肥鲜；一身粗布破袍，无光鲜锦绣。作者于前面以环境的恶劣突显其坚苦不移，这里则以“烨然若神人”的纨绔子弟为对比，反衬其独得其乐。正由于如此，不计客观条件的艰苦，执着追求，虚心求教，他才能“遍观群书”，而列于君子之列，居天子之侧，四海称其姓氏。从封建社会的“学而优则仕”的观点看，宋濂可谓学有所成的了。接着写诸生学习条件优裕而懈怠，回应上文，又明揭意图。作者仍然从食、住、书、师四个方面予以对比。太学生无衣食之患，相反的是鲜服美食；高堂大厦，群书毕集，师随左右，不像自己当年的学习，有“冻馁之患”、“奔走之劳”、“求而不得”之苦，可是条件好了，却有“业有不精，德有不成”者。条件的优裕和效果的不佳又形成对照。作者在充分比照的基础上其理颖然而出：“非天质之卑，则心不若余之专耳，岂他人之过哉!”显示了不容置辩的力量。最后一节文字写作这篇序的目的：“勉乡人以学”。作者和马君则系同乡关系，又是位勤奋好学的青年，加之以长信为进见礼，言和色夷，是个流辈称其贤的“善学者”，因而才诚恳地以“为学之难以告之”。由于文中是以个人的经历和体会为例证的，因而要申说一下无“夸际遇之盛而骄乡人”的意思。作者在行文中也一直注意防止骄矜之意，写向人请教，说“余虽愚，卒获有所闻”，称自己“今虽耄老，未有所成”，以及“幸预”、“缀”、“谬称”等谦让之辞，纯然是长者之风，学者之范。\n\n　　作者勖勉后生马君则，语重心长，寓理于事，其事一为己事，一为人事。叙己事，娓娓动听；述人事，头头是道。以己事与人事相比照，其理煜然。人事即为太学生事，马生系太学生中之一员。但又不同于一般的太学生，是个“用心於学甚劳”的“善学者”，因而具有劝勉的基础，否则也不必如此谆谆告诫。这篇劝学篇，因为作者现身说法和严密对比，事繁而不芜。语简而意昭，不愧是宋濂的力作之一，也是明文中的佼佼者。\n\n　　宋濂不仅学识丰赡，文才彪炳，而且政治经验富足，马生原是个用心于学的人，也已取得了一定的成绩，那作者又为何还要如此教诲？作者不说太学使人养尊处优，不求上进，而讲条件优越，要充分运用。这是因为他深知朱元璋登上宝座后一直妒贤嫉能、杀戮功臣，以巩固其统治。他的亲信谋士、开国功臣刘基就死于朱元璋的阴谋，开国元勋徐达、太师韩国公李善长、中丞涂节、吏部尚书詹徽、开国公常升等都被朱元璋以各种借口而杀害。宋濂可谓知时识世，在朱元璋大清洗之前就告老还乡，退居林泉。他这次“朝京师”，马生“撰长书以为贽”，对他加以赞颂，他为了避免朱元璋的疑忌，在赠序中不讲为国为民之类的涉嫌的话，而讲万年百处可说的读书问题。谈读书，还不忘赞扬一下太学，对皇帝主办的学校条件说了一番好话。从这里可见宋濂不仅饱有学识，而且老于世故。宋濂虽然如此小心谨慎，可是后来他的孙子与一案有牵，最后也诛及了他。', poem_tags = '初中文言文,送别,劝勉,学习' WHERE poem_title = '送东阳马生序(节选)' AND poem_author = '宋濂';
UPDATE edu_poem SET poem_translation = '独自闲坐幽静竹林，时而弹琴时而长啸。\n密林之中何人知晓我在这里？只有一轮明月静静与我相伴。', poem_notes = '竹里馆：辋川别墅胜景之一，房屋周围有竹林，故名。\n幽篁（huáng）：幽深的竹林。\n啸（xiào）：嘬口发出长而清脆的声音，类似于打口哨。\n深林：指“幽篁”。\n相照：与“独坐”相应，意思是说，左右无人相伴，唯有明月似解人意，偏来相照。\n长啸：撮口而呼，这里指吟咏、歌唱。古代一些超逸之士常用来抒发感情。魏晋名士称吹口哨为啸。', poem_appreciation = '此诗收录于《王右丞集笺注》，为《辋川集》二十首中的第十七首。诗写山林幽居情趣，属闲情偶寄。\n\n　　这首小诗总共四句。拆开来看，既无动人的景语，也无动人的情语；既找不到哪个字是诗眼，也很难说哪一句是警策。且诗的用字造语、写景（幽篁、深林、明月），写人（独坐、弹琴、长啸）都极平淡无奇。然而它的妙处也就在于以自然平淡的笔调，描绘出清新诱人的月夜幽林的意境，夜静人寂融情景为一体，蕴含着一种特殊的美的艺术魅力，使其成为千古佳品。以弹琴长啸，反衬月夜竹林的幽静，以明月的光影，反衬深林的昏暗，表面看来平平淡淡，似乎信手拈来，随意写去其实却是独具匠心，妙手回春的大手笔。\n\n　　这首诗表现了一种清静安详的境界。前两句写诗人独自一人坐在幽深茂密的竹林之中，一边弹着琴弦，一边又发出长长的啸声。其实，不论“弹琴”还是“长啸”，都体现出诗人高雅闲淡、超拔脱俗的气质，而这却是不容易引起别人共鸣的。所以后两句说：“深林人不知，明月来相照。”意思是说，自己僻居深林之中，也并不为此感到孤独，因为那一轮皎洁的月亮还在时时照耀自己。这里使用了拟人化的手法，把倾洒着银辉的一轮明月当成心心相印的知己朋友，显示出诗人新颖而独到的想象力。全诗的格调幽静闲远，仿佛诗人的心境与自然的景致全部融为一体了。\n\n　　诗中写到景物，只用六个字组成三个词，就是：“幽篁”、“深林”、“明月”。对普照大地的月亮，用一个“明”字来形容其皎洁，并无新意巧思可言，是人人惯用的陈词。至于第一句的“篁”与第三句的“林”，其实是一回事，是重复写诗人置身其间的竹林，而在竹林前加“幽”、“深”两字，不过说明其既非庾信《小园赋》所说的“三竿两竿之竹”，也非柳宗元《青水驿丛竹》诗所说的“檐下疏篁十二茎”，而是一片既幽且深的茂密的竹林。这里，象是随意写出了眼前景物，没有费什么气力去刻画和涂饰。\n\n　　诗中写人物活动，也只用六个字组成三个词，就是：“独坐、弹琴、长啸”。对人物，既没有描绘其弹奏舒啸之状，也没有表达其喜怒哀乐之情；对琴音与啸声，更没有花任何笔墨写出其音调与声情。　表面看来，四句诗的用字造语都是平平无奇的。但四句诗合起来，却妙谛自成，境界自出，蕴含着一种特殊的艺术魅力。作为王维《辋川集》中的一首名作，它的妙处在于其所显示的是那样一个令人自然而然为之吸引的意境。它不以字句取胜，而从整体见美。它的美在神不在貌，领略和欣赏它的美，也应当遗貌取神，而其神是包孕在意境之中的。就意境而言，它不仅如施补华所说，给人以“清幽绝俗”（《岘佣说诗》）的感受，而且使人感到，这一月夜幽林之景是如此空明澄净，在其间弹琴长啸之人是如此安闲自得，尘虑皆空，外景与内情是抿合无间、融为一体的。而在语言上则从自然中见至味、从平淡中见高韵。它的以自然、平淡为特征的风格美又与它的意境美起了相辅相成的作用。\n\n　　可以想见，诗的意境的形成，全赖人物心性和所写景物的内在素质相一致，而不必借助于外在的色相。因此，诗人在我与物会、情与景合之际，就可以如司空图《诗品·自然篇》中所说，“俯拾即是，不取诸邻，俱道适往，著手成春”，进入“薄言情悟，悠悠天钧”的艺术天地。当然，这里说“俯拾即是”，并不是说诗人在取材上就一无选择，信手拈来；这里说“著手成春”，也不是说诗人在握管时就一无安排，信笔所之。诗中描写周围景色，选择了竹林与明月，是取其与所要显示的那一清幽澄净的环境原本一致；诗中抒写自我情怀，选择了弹琴与长啸，则取其与所要表现的那一清幽澄净的心境互为表里。这既是即景即事，而其所以写此景，写此事，自有其酝酿成熟的诗思。更从全诗的组合看，诗人在写月夜幽林的同时，又写了弹琴、长啸，则是以声响托出静境。至于诗的末句写到月来照，不仅与上句的“人不知”有对照之妙，也起了点破暗夜的作用。这些音响与寂静以及光影明暗的衬映，在安排上既是妙手天成，又是有匠心运用其间的。', poem_tags = '唐诗三百首,月亮,初中古诗,归隐,孤独,生活' WHERE poem_title = '竹里馆' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '孔子向东游历，见到两个小孩在争辩，就问他们在争辩的原因。\n一个小孩子说：“我认为太阳刚刚升起的时候距离人近，而正午的时候距离人远。”\n另一个小孩子认为太阳刚刚升起的时候距离人比较远，而正午的时候距离人比较近。\n一个小孩儿说：“太阳刚出时像车的车盖一样大，到了中午时就如同盘子一般小了，这不是远小近大的道理吗？”\n另一个小孩儿说：“太阳刚出来时凉爽，到了中午的时候热得如同把手伸进热水中，这不是近的就感觉热，而远就觉得凉的道理吗？”\n孔子听了之后不能判断他们俩谁对谁错。\n两个小孩子笑着对孔子说：“是谁说你智慧多呢？”', poem_notes = '东：东方。\n游：游历、游学。\n见：看见。\n辩斗：辩论，争论.\n辩：争。\n其：代词，他们。\n故：缘故，原因。\n以：认为。\n始：刚刚，才。\n去：离；距离。\n日中：正午。\n初：刚刚。\n车盖：古时车上的篷盖，像雨伞一样，呈圆形。\n及：到。\n则：就。\n盘盂：盛物的器皿。圆者为盘，方者为盂。\n为：是。\n沧沧凉凉：形容清凉的感觉。沧沧：寒冷的意思。\n探汤：把手伸向热水里。汤，热水，开水。（古时还特指沐浴时用的热水。）在文中的意思是天气很热。\n决：决断，判定，判断。\n孰：谁。\n为：同“谓”，说，认为。\n汝：你。\n知：zhì，通假字。“知”通 “智”聪明、智慧。\n笑：在这里不是嘲笑，在这里突出了孩子们的天真可爱\n沧沧凉凉:形容清凉而略带寒意。', poem_appreciation = '教材简析\n\n　　《两小儿辩日》是人教版大修订教材第十二册中的一篇文言课文。文章讲的是古时候两个小孩凭自己的直觉，一个认为太阳在早晨离人近，一个认为太阳在中午离人近，为此，各持一端，争执不下，就连孔子这样博学的人也不能作出判断。这个故事既渗透了要主动认识自然、探求客观真理，并大胆质疑的科学态度；也说明了知识无穷，学无止境，再博学的人也会有所不知，应该实事求是的道理。\n\n　　文言文是中国传统文化的宝贵遗产。借助《两小儿辩日》这篇文章，学生将初步感受到文言文的语言特点，产生学习文言文的兴趣，了解祖国悠久灿烂的文化，增强学习祖国语言文字的信心，并为今后学习文言文打下基础。\n\n　　学习目标\n\n　　1．根据课后注释理解文章内容，掌握重点字词，并反复诵读课文，产生自己的独特感受，力争达到“熟读成诵”。\n\n　　2．初步感受文言文的特点，产生学习文言文的兴趣。\n\n　　3．感受两小儿的聪明可爱及孔子实事求是的科学态度，体会学无止境的道理。\n\n　　教学过程\n\n　　一、温故知新，解破课题\n\n　　1．齐读课题。\n\n　　2．借已学过的古诗词引出对“日”字的理解。\n\n　　〖教师〗根据“温故而知新”的古训，引导学生背诵含有“日”字的诗句。\n\n　　〖学生〗背诵诗词，并简释诗句中“日”字的意思。\n\n　　〖教师〗引导学生在已有知识的基础上，理解课题，并导出“两小儿在争论太阳的什么”这个问题，便于下一步展开对课文的深入学习。\n\n　　[设计意图]\n\n　　构成文言文主体的汉字与现代文的字意有近似之处。就从课文的标题来看，古今含义就大致相同。因此，假以耳熟能详的古诗词，启发学生“温故知新”，就可以悟出题旨，并消除学习文言文的畏难情绪，对学好课文充满信心。\n\n　　二、千里之行，始于足下\n\n　　1．畅谈感受，明确方向。\n\n　　〖教师〗给出机会让学生畅谈初次接触文言文的感受，并及时归纳和小结，启发学生思考解决学习疑难的方法。\n\n　　〖学生〗根据各自已有的经验，提出学习课文的方法。\n\n　　2．合作学习，疏通文章。\n\n　　〖教师〗提示学生采用适当的方法，把课文读懂、读通顺。\n\n　　〖学生〗选取适当的学习方法，通过小组协作，疏通文章。\n\n　　3．检查学习效果。\n\n　　〖教师〗请学生参考注释，用现代口语复述故事，并根据学生复述的状况进行即席点拨。\n\n　　〖学生〗复述故事。\n\n　　〖教师〗出示一组选择题，让学生选定两小儿辩斗的焦点，即解开上课之初的问题——“两小儿在争论太阳的什么？”\n\n　　〖学生〗通过“写题板”的形式，快速表达各自的选择结果。\n\n　　〖教师〗在学生基本读懂课文的基础上，引导学生“浅谈”对重点词——“笑”的理解，并适时点拨。\n\n　　〖师生同步〗借助画面为竹简样式的媒体展示全文，反复诵读，共同感受古文的“韵律美”，以期达到熟读的效果，为深入理解课文铺平道路。\n\n　　[设计意图]\n\n　　“千里之行”是喻指对课文的深入理解，而“始于足下”是指以让学生读通、读顺、读出滋味为学习文言文的起点。在教师的“陪伴”下，学生动口、动脑，自我磨练诵读古文的能力，同时也感受到诵读古文的乐趣。在多次诵读中，学生既能感悟文言文的特点，又能明确下一步学习的方向。\n\n　　三、书读百遍，其义自见\n\n　　1．小组合作，弄清“辩斗”的观点及理由。\n\n　　〖教师〗从文言文“简洁”的特点入手，引导学生弄清两小儿“辩斗”的内容，分清“辩斗”的观点和理由。\n\n　　〖学生〗通过小组协作，分清“辩斗”的观点和理由。\n\n　　2．检查学习效果并品读课文。\n\n　　〖教师〗在学生分别汇报两小儿观点和理由的同时，完成板书。并再次指导学生反复品读。\n\n　　〖学生〗反复品读，品出对“笑”字的深入感悟。\n\n　　[设计意图]\n\n　　在合作学习中让学生分清观点和理由，并感受两小儿争论的氛围，激发学生边读边想。在反复诵读之后，促使学生对两小儿之“笑”有深入、独特的感悟。从而明确“书读百遍，其义自见”的道理，并通过谈论、诵读等形式，展现学生对课文的“个性化感悟”。\n\n　　3．尝试性背诵，力争达到“熟读成诵”。（机动环节）\n\n　　四、知识无穷，学无止境\n\n　　1．解开“辩日”之谜。\n\n　　〖教师〗提出“辩日”孰是孰非的问题。\n\n　　〖学生〗通力协作，解开“辩日”之谜。\n\n　　〖教师〗运用媒体手段“印证”学生的解释。\n\n　　2．理性看待“孔子不能决”。\n\n　　〖教师〗引导学生谈论对“孔子不能决”的看法。\n\n　　〖学生〗针对“孔子不能决”各抒己见，从而感受两小儿的聪明可爱及孔子实事求是的科学态度，体会学无止境的道理。\n\n　　[设计意图]\n\n　　教学中为体现对“情感态度和价值观”这一目标的落实，精心组织“如何看待孔子不能决”的教学活动，促使学生联系生活实际，在热烈的讨论之中使学生悟出“知识无穷、学无止境”的道理。\n\n　　五、回味“辩日”，师生漫谈\n\n　　1．回味“学习历程”，书写心得。\n\n　　〖教师〗小结本节课的“学习历程”，启发学生写出各自的收获和体会。\n\n　　〖学生〗通过“写题板”的形式，简明小结自己 “个性化”的情感体验。\n\n　　2．漫谈体会。\n\n　　〖师生同步〗进行高效的思维互动与交流，拓展各自“个性化”的情感体验。\n\n　　[设计意图]\n\n　　引导学生回味本节课的“学习历程”，为的是启发他们从不同的角度、不同的层面去体验，并用最简洁的表达形式来表达自己的体验。这种体验是自主和个性化的；它始于“辩日”，但期盼孩子们能超越“辩日”水平。', poem_tags = '初中文言文,儿童,对话,哲理,寓言' WHERE poem_title = '两小儿辩日 / 两小儿辩斗' AND poem_author = '列御寇';
UPDATE edu_poem SET poem_translation = '乘船远行，路过荆门一带，来到楚国故地。\n青山渐渐消失，平野一望无边。长江滔滔奔涌，流入广袤荒原。\n月映江面，犹如明天飞镜；云彩升起，变幻无穷，结成了海市蜃楼。\n故乡之水恋恋不舍，不远万里送我行舟。', poem_notes = '荆门：山名，位于今湖北省宜都县西北长江南岸，与北岸虎牙三对峙，地势险要，自古即有楚蜀咽喉之称。\n远：远自。\n楚国：楚地，指湖北一带，春秋时期属楚国。\n平野：平坦广阔的原野。\n江：长江。大荒：广阔无际的田野。\n月下飞天镜：明月映入江水，如同飞下的天镜。下：移下。\n海楼：海市蜃楼，这里形容江上云霞的美丽景象。\n仍：依然。怜：怜爱。一本作“连”。故乡水：指从四川流来的长江水。因诗人从小生活在四川，把四川称作故乡。\n万里：喻行程之远。', poem_appreciation = '这首诗是李白出蜀时所作。李白这次出蜀，由水路乘船远行，经巴渝，出三峡，直向荆门山之外驶去，目的是到湖北、湖南一带楚国故地游览。“渡远荆门外，来从楚国游”，指的就是这一壮游。这时候的青年诗人，兴致勃勃，坐在船上沿途纵情观赏巫山两岸高耸云霄的峻岭，一路看来，眼前景色逐渐变化，船过荆门一带，已是平原旷野，视域顿然开阔，别是一番景色：\n\n　　“山随平野尽，江入大荒流。”\n\n　　“山随平野尽”，形象地描绘了船出三峡、渡过荆门山后长江两岸的特有景色：山逐渐消失了，眼前是一望无际的低平的原野。著一“随”字，化静为动，将群山与平野的位置逐渐变换、推移，真切地表现出来。这句好比用电影镜头摄下的一组活动画面，给人以流动感与空间感，将静止的山岭摹状出活动的趋向来。\n\n　　“江入大荒流”，写出江水奔腾直泻的气势，从荆门往远处望去，仿佛流入荒漠辽远的原野，显得天空寥廓，境界高远。后句著一“入”字，写出了气势的博大，充分表达了诗人的万丈豪情，充满了喜悦和昂扬的激情，力透纸背，用语贴切。景中蕴藏着诗人喜悦开朗的心情和青春的蓬勃朝气。\n\n　　颔联这两句不仅由于写进“平野”、“大荒”这些辽阔原野的意象，而气势开阔；而且还由于动态的描写而十分生动。大江固然是流动的，而山脉却本来是凝固的，“随、尽”的动态感觉，完全是得自舟行的实际体验。在陡峭奇险，山峦叠嶂的三峡地带穿行多日后，突见壮阔之景，豁然开朗的心情可想而知。它用高度凝炼的语言。极其概括地写出了诗人整个行程的地理变化。\n\n　　写完山势与流水，诗人又以移步换景手法，从不同角度描绘长江的近景与远景：\n\n　　“月下飞天镜，云生结海楼。”\n\n　　长江流过荆门以下，河道迂曲，流速减缓。晚上，江面平静时，俯视月亮在水中的倒影，好象天上飞来一面明镜似的；日间，仰望天空，云彩兴起，变幻无穷，结成了海市蜃楼般的奇景。这正是从荆门一带广阔平原的高空中和平静的江面上所观赏到的奇妙美景。如在崇山峻岭的三峡中，自非亭午夜分，不见曦月，夏水襄陵，江面水流湍急汹涌，那就很难有机会看到“月下飞天镜”的水中影像；在隐天蔽日的三峡空间，也无从望见“云生结海楼”的奇景。这一联以水中月明如圆镜反衬江水的平静，以天上云彩构成海市蜃楼衬托江岸的辽阔，天空的高远，艺术效果十分强烈。颔颈两联，把生活在蜀中的人，初次出峡，见到广大平原时的新鲜感受极其真切地写了出来。\n\n　　颈联两句反衬江水平静，展现江岸辽阔，天空高远，充满了浪漫主义色彩。\n\n　　李白在欣赏荆门一带风光的时候，面对那流经故乡的滔滔江水，不禁起了思乡之情：\n\n　　“仍怜故乡水，万里送行舟。”\n\n　　诗人顺着长江远渡荆门，江水流过的蜀地也就是曾经养育过他的故乡，初次离别，他怎能不无限留恋，依依难舍呢？但诗人不说自己思念故乡，而说故乡之水恋恋不舍地一路送我远行，怀着深情厚意，万里送行舟，从对面写来，越发显出自己思乡深情。诗以浓重的怀念惜别之情结尾，言有尽而情无穷。诗题中的“送别”应是告别故乡而不是送别朋友，诗中并无送别朋友的离情别绪。清沈德潜认为“诗中无送别意，题中二字可删”（《唐诗别裁》），这并不是没有道理的。\n\n　　这首诗首尾行结，浑然一体，意境高远，风格雄健。“山随平野尽，江入大荒流”，写得逼真如画，有如一幅长江出峡渡荆门长轴山水图，成为脍炙人口的佳句。如果说优秀的山水画“咫尺应须论万里”，那么，这首形象壮美瑰玮的五律也可以说能以小见大，以一当十，容量丰富，包涵长江中游数万里山势与水流的景色，具有高度集中的艺术概括力。', poem_tags = '唐诗三百首,初中古诗,长江,送别,思乡' WHERE poem_title = '渡荆门送别' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '农民终年没有闲暇，到了五月加倍繁忙。\n夜里吹来暖暖南风，地里小麦盖垄熟黄。\n妇女用筐挑着食物，孩子提壶盛满水汤。\n相伴到田里送饭食，男人劳作在南山冈。\n脚被地面热气熏蒸，背烤着火辣的阳光。\n精疲力竭不觉酷热，只是珍惜夏日天长。\n又见一位贫苦农妇，抱着孩子跟在人旁。\n右手拿着捡的麦穗，左臂挂着一个破筐。\n听她回头述说家境，听的人都为她悲伤。\n为了缴税家田卖尽，靠捡麦穗填充饥肠。\n如今我有什么功德，从来没有种田采桑。\n一年俸禄有三百石，到了年底还有余粮。\n想到这些暗自惭愧，整日整夜念念不忘。', poem_notes = '（yì）：割。题下注“时任盩厔县尉”。\n覆（fù）陇（lǒng）黄：小麦黄熟时遮盖住了田埂。覆：盖。陇：同“垄”，这里指农田中种植作物的土埂，这里泛指麦地。\n妇姑：媳妇和婆婆，这里泛指妇女。荷（hè）箪（dān）食（shí）：用竹篮盛的饭。荷：背负，肩担。箪食：装在箪笥里的饭食。《左传·宣公二年》：“而为之箪食与肉，寘诸橐以与之。”\n童稚（zhì）携壶浆（jiāng）：小孩子提着用壶装的汤与水。浆：古代一种略带酸味的饮品，有时也可以指米酒或汤。\n饷（xiǎng）田：给在田里劳动的人送饭。\n丁壮：青壮年男子。南冈（gāng）：地名。\n足蒸暑土气，背灼炎天光：双脚受地面热气熏蒸，脊背受炎热的阳光烘烤。\n但：只。惜：盼望。\n其：指代正在劳动的农民。傍：同“旁”。\n秉（bǐng）遗穗：拿着从田里拾取的麦穗。秉，拿着。遗穗，指收获农作物后遗落在田的麦穗。\n悬：挎着。敝（bì）筐：破篮子。\n相顾言：互相看着诉说。顾：视，看。\n闻者：白居易自指。为（wèi）悲伤：为之悲伤（省略“之”）。\n输税（shuì）：缴纳租税。输，送达，引申为缴纳，献纳。\n我：指作者自己。\n曾（céng）不事农桑：一直不从事农业生产。曾：一直、从来。事：从事。农桑：农耕和蚕桑。\n吏（lì）禄（lù）三百石（dàn）：当时白居易任周至县尉，一年的薪俸大约是三百石米。石：古代容量单位，十斗为一石。吏禄：官吏的俸禄。《史记·平准书》：“量吏禄，度官用，以赋于民。”\n岁晏（yàn）：一年将尽的时候。晏，晚。\n念此：想到这些。\n尽日：整天，终日。', poem_appreciation = '这首诗是元和二年（807）作者任盩厔（今陕西周至）县尉时写的，是作者早期一首著名讽谕诗。\n\n　　这首诗叙事明白，结构自然，层次清楚，顺理成章。诗一开头，先交代背景，标明是五月麦收的农忙季节。接着写妇女领着小孩往田里去，给正在割麦的青壮年送饭送水。随后就描写青壮年农民在南冈麦田低着头割麦，脚下暑气熏蒸，背上烈日烘烤，已经累得筋疲力尽还不觉得炎热，只是珍惜夏天昼长能够多干点活。写到此处，这一家农民辛苦劳碌的情景已经有力地展现出来。接下来又描写了另一种令人心酸的情景：一个贫妇人怀里抱着孩子，手里提着破篮子，在割麦者旁边拾麦。为什么要来拾麦呢？因为她家的田地已经“输税尽”──为缴纳宫税而卖光了，如今无田可种，无麦可收，只好靠拾麦充饥。这两种情景交织在一起，有差异又有关联：前者揭示了农民的辛苦，后者揭示了赋税的繁重。繁重的赋税既然已经使贫妇人失掉田地，那就也会使这一家正在割麦的农民失掉田地。今日的拾麦者，乃是昨日的割麦者；而今日的割麦者，也可能成为明日的拾麦者。强烈的讽谕意味，自在不言之中。诗人由农民生活的痛苦联想到自己生活的舒适，感到惭愧，内心里久久不能平静。这段抒情文字是全诗的精华所在。它是作者触景生情的产物，表现了诗人对劳动人民的深切同情。白居易写讽谕诗，目的是“唯歌生民病，愿得天子知”。在这首诗中，他以自己切身的感受，把农民和作为朝廷官员的自己作鲜明对比，就是希望“天子”有所感悟，手法巧妙而委婉，可谓用心良苦。\n\n　　白居易是一位最擅长写叙事诗的艺术巨匠。他的叙事诗能曲尽人情物态，把其中所叙的事件写得曲折详尽，娓娓动听。而且，他的叙事诗里总是有着心灵的揭示，因而总是蕴含着感情的。在《观刈麦》里，他虽然着墨不多，但是却把割麦者与拾麦者在夏收时那种辛勤劳碌而又痛苦的生活情景，描写得生动真切，历历如画。不仅写了事，而且写了心，包括作者本人的心和劳动人民的心。诗人的心弦显然是被耳闻目睹的悲惨景象振动了，颤栗了，所以才提起笔来直歌其事，所以在字里行间都充满对劳动者的同情和怜悯。像“足蒸暑土气，背灼炎天光”、“家田输税尽，拾此充饥肠”这样的诗句，里面包含着作者多少同情之感、怜悯之意啊！因而这首《观刈麦》在叙事当中是有着作者情的渗透、心的跳动的，作者的心同他所叙的事是融为一体的。值得称道的是，作者在真实地写劳动人民之事的同时，还能够真实地写出劳动人民之心，尤其是刻画出劳动人民在某种特定情况下的变态心理，深刻地揭示诗的主题。《卖炭翁》中“可怜身上衣正单，心忧炭贱愿天寒”，写的是卖炭老人为衣食所迫而产生的变态心理。《观刈麦》中的“力尽不知热，但惜夏日长”，同样也是一种变态心理。这类描写把劳动人民之心刻画入微，深入底蕴。诗中写事与写心的完美统一，较之一般的叙事与抒情的统一，更能震撼人心。白居易又是运用对比手法的能手。他在诗歌创作中，不仅把劳动人民的贫困、善良与地主阶级的奢侈、暴虐作了对比，而且还把自己的舒适与劳动人民的穷苦作了对比。这首诗在写了农民在酷热的夏天的劳碌与痛苦之后，诗人同样也联想到自己，感到自己没有“功德”，又“不事农桑”，可是却拿“三百石”俸禄，到年终还“有余粮”，因而“念此私自愧，尽日不能忘”。诗人在那个时代能够主动去和农民对比，十分难得。这样一种对比，真是新颖精警，难能可贵，发人深省，因而更显出这首诗的思想高度。', poem_tags = '初中古诗,夏天,农民,生活,讽喻,古诗里的十二个月' WHERE poem_title = '观刈麦' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '生时应当做人中豪杰，死后也要做鬼中英雄。\n到今天人们还在怀念项羽，因为他不肯苟且偷生，退回江东。', poem_notes = '人杰：人中的豪杰。汉高祖曾称赞开国功臣张良、萧何、韩信是“人杰”。\n鬼雄：鬼中的英雄。\n项羽：秦末时自立为西楚霸王，与刘邦争夺天下，在垓下之战中，兵败自杀。\n江东：项羽当初随叔父项梁起兵的地方。', poem_appreciation = '李清照这首诗，手起笔落处，端正凝重，力透人胸臆，直指人脊骨。“生当作人杰，死亦为鬼雄”这不是几个字的精致组合，不是几个词的巧妙润色；是一种精髓的凝练，是一种气魄的承载，是一种所向无惧的人生姿态。那种凛然风骨，浩然正气，充斥天地之间，直令鬼神徒然变色。“当作”之所“亦为”，一个女子啊！纤弱无骨之手，娇柔无力之躯，演绎之柔美，绕指缠心，凄切入骨，细腻感人无以复加。透过她一贯的文笔风格，在她以“婉约派之宗”而著称文坛的光环映彻下。笔端劲力突起，笔锋刚劲显现时，这份刚韧之坚，气势之大，敢问世间须眉几人可以匹敌？“至今思项羽，不肯过江东。”女诗人追思那个叫项羽的楚霸枭雄，追随项羽的精神和气节，痛恨宋朝当权者苟且偷安的时政。都说退一步海阔天空。仅一河之遥，却是生死之界，仅一念之间，却是存亡之抉。项羽，为了无愧于英雄名节，无愧七尺男儿之身，无愧江东父老所托，以死相报。“不肯”！不是“不能”、不是“不想”、不是“不愿”、不是“不去”。一个“不肯”笔来神韵，强过鬼斧神工，高过天地造化。一种“可杀不可辱”、“死不惧而辱不受”的英雄豪气，漫染纸面，力透纸背，令人叫绝称奇而无复任何言语！\n\n　　这首诗起调高亢，鲜明地提出了人生的价值取向：人活着就要做人中的豪杰，为国家建功立业；死也要为国捐躯，成为鬼中的英雄。爱国激情，溢于言表，在当时确有振聋发聩的作用。南宋统治者不管百姓死活，只顾自己逃命；抛弃中原河山，苟且偷生。因此，诗人想起了项羽。项羽突围到乌江，乌江亭长劝他急速渡江，回到江东，重整旗鼓。项羽自己觉得无脸见江东父老，便回身苦战，杀死敌兵数百，然后自刎。诗人鞭挞南宋当权派的无耻行径，借古讽今，正气凛然。全诗仅二十个字，连用了三个典故，但无堆砌之弊，因为这都是诗人的心声。如此慷慨雄健、掷地有声的诗篇，出自女性之手，实在是压倒须眉了。', poem_tags = '古诗三百首,地名,咏史怀古,爱国,典故,励志,早教古诗100首' WHERE poem_title = '夏日绝句' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '梅花和雪花都认为各自占尽了春色，谁也不肯服输。难坏了诗人，难写评判文章。\n说句公道话，梅花须逊让雪花三分晶莹洁白，雪花却输给梅花一段清香。', poem_notes = '卢梅坡，宋诗人。生卒年不详。“梅坡”不是他的名字，而是他自号为梅坡。\n降（xiáng），服输。\n骚人：诗人。\n阁笔：放下笔。阁，同“搁”放下。评章，评议的文章，这里指评议梅与雪的高下。', poem_appreciation = '赏析 　　古今不少诗人往往把雪、梅并写。雪因梅，透露出春的信息，梅因雪更显出高尚的品格。如毛泽东《卜算子·咏梅》中就曾写道：“风雨送春归，飞雪迎春到。已是悬崖百丈冰，犹有花枝俏。俏也不争春，只把春来报。待到山花烂漫时，她在丛中笑。”雪、梅都成了报春的使者、冬去春来的象征。但在诗人卢梅坡的笔下，二者却为争春发生了“磨擦”，都认为各自占尽了春色，装点了春光，而且谁也不肯相让。这种写法，实在是新颖别致，出人意料，难怪诗人无法判个高低。诗的后两句巧妙地托出二者的长处与不足：梅不如雪白，雪没有梅香，回答了“骚人阁笔费评章”的原因，也道出了雪、梅各执一端的根据。读完全诗，我们似乎可以看出作者写这首诗是意在言外的：借雪梅的争春，告诫我们人各有所长，也各有所短，要有自知之明。取人之长，补己之短，才是正理。这首诗既有情趣，也有理趣，值得咏思。 ▲', poem_tags = '古诗三百首,冬天,写雪,梅花,励志,哲理' WHERE poem_title = '雪梅·其一' AND poem_author = '卢梅坡';
UPDATE edu_poem SET poem_translation = '薄雾弥漫，云层浓密，日子过得愁烦，龙脑香在金兽香炉中缭袅。又到了重阳佳节，卧在玉枕纱帐中，半夜的凉气刚将全身浸透。\n在东篱边饮酒直到黄昏以后，淡淡的黄菊清香溢满双袖。莫要说清秋不让人伤神，西风卷起珠帘，帘内的人儿比那黄花更加消瘦。', poem_notes = '云：《古今词统》等作“雰”，《全芳备祖》作：“阴”。永昼：漫长的白天。\n瑞脑：一种薰香名。又称龙脑，即冰片。消：一本作“销”，《花草粹编》等作“喷”。金兽：兽形的铜香炉。\n重阳：农历九月九日为重阳节。\n纱厨：即防蚊蝇的纱帐。橱：《彤管遗篇》等作“窗”。\n凉：《全芳备祖》等作“秋”。\n东篱：泛指采菊之地。\n暗香：这里指菊花的幽香。\n消魂：形容极度忧愁、悲伤。 消：一作“销”。\n西风：秋风。\n比：《花草粹编》等作“似”。黄花：指菊花。鞠，本用菊。', poem_appreciation = '这首词是作者婚后所作，抒发的是重阳佳节思念丈夫的心情。传说李清照将此词寄给赵明诚后，惹得明诚比试之心大起，遂三夜未眼，作词数阕，然终未胜过清照的这首《醉花阴》。\n\n　　“薄雾浓云愁永昼”，这一天从早到晚，天空都是布满着“薄雾浓云”，这种阴沉沉的天气最使人感到愁闷难捱。外面天气不佳，只好待在屋里。永昼，一般用来形容夏天的白昼，这首词写的是重阳，即农历九月九日，已到秋季时令，白昼越来越短，还说“永昼”，这只是词人的一种心理感觉。时间对于欢乐与愁苦的心境分别具有相对的意义，在欢乐中时间流逝得快，在愁苦中则感到时间的步履是那样缓慢。一个人若对“薄雾浓云”特别敏感，担心白天总也过不完，那么，她的心境定然不舒畅。李清照结婚不久，就与相爱至深的丈夫赵明诚分离两地，这时她正独守空房，怪不得感到日长难捱了。这里虽然没有直抒离愁，但仍可透过这层灰蒙蒙的“薄雾浓云”，窥见女词人的内心苦闷。“瑞脑消金兽”一句，便是转写室内情景：她独自个儿看着香炉里瑞脑香的袅袅青烟出神，真是百无聊赖。又是重阳佳节了，天气骤凉，睡到半夜，凉意透入帐中枕上，对比夫妇团聚时闺房的温馨，真是不可同日而语。上片寥寥数句，把一个闺中少妇心事重重的愁态描摹出来。她走出室外，天气不好；待在室内又闷得慌；白天不好过，黑夜更难挨；坐不住，睡不宁，真是难以将息。“佳节又重阳”一句有深意。古人对重阳节十分重视。这天亲友团聚，相携登高，佩茱萸，饮菊酒。李清照写出“瑞脑消金兽”的孤独感后，马上接以一句“佳节又重阳”，显然有弦外之音，暗示当此佳节良辰，丈夫不在身边，“遍插茱萸少一人”，不禁叫她“每逢佳节倍思亲”。“佳节又重阳”一个“又”字，是有很浓的感情色彩的，突出地表达了她的伤感情绪。紧接着两句：“玉枕纱厨，半夜凉初透。”丈夫不在家，玉枕孤眠，纱帐内独寝，难免有孤寂之感。“半夜凉初透”，不只是时令转凉，而是别有一番凄凉滋味。\n\n　　下片写重阳节这天黄昏赏菊东篱、借酒浇愁的情景。把酒赏菊本是重阳佳节的一个主要节目，大概为了应景，李清照在屋里闷坐了一天，直到傍晚，才强打精神“东篱把酒”来了。可是，这并未能宽解一下愁怀，反而在她的心中掀起了更大的感情波澜。重阳是菊花节，菊花开得极盛极美，她一边饮酒，一边赏菊，染得满身花香。然而，她又不禁触景伤情，菊花再美，再香，也无法送给远在异地的亲人。“有暗香盈袖”一句，化用了《古诗十九首》“馨香盈怀袖，路远莫致之”句意。“暗香”，通常指梅花。“疏影横斜水清浅，暗香浮动月黄昏”，就是北宋诗人林逋咏梅花的名句。这里则以“暗香”指代菊花。菊花经霜不落，傲霜而开，风标与梅花相似，暗示词人高洁的胸襟和脱俗的情趣。同时也流露出“馨香满怀袖，路远莫致之”的深深遗憾。这是暗写她无法排遣的对丈夫的思念。她实在情不自禁，再无饮酒赏菊的意绪，于是匆匆回到闺房。“莫道不消魂”句写的是晚来风急，瑟瑟西风把帘子掀起了，人感到一阵寒意。联想到刚才把酒相对的菊花，菊瓣纤长，菊枝瘦细，而斗风傲霜，人则悲秋伤别，消愁无计，此时顿生人不如菊之感。以“人比黄花瘦”作结，取譬多端，含蕴丰富。\n\n　　此词在艺术上的一个特点是“物皆著我之色彩”，从天气到瑞脑金兽、玉枕纱厨、帘外菊花，词人用她愁苦的心情来看这一切，无不涂上一层愁苦的感情色彩。在结构上自起句至“有暗香盈袖”，都是铺叙笔法；而把节日离索的刻挚深情留在结拍，使它如高峰突起。“莫道不消魂，帘卷西风，人比黄花瘦”，成为全篇最精彩之笔。以花木之“瘦”，比人之瘦，诗词中不乏类似的句子，这是因为正是“莫道不消魂，帘卷西风，人比黄花瘦”这三句，才共同创造出一个凄清寂寥的深秋怀人的境界。“莫道不消魂”，直承“东篱把酒”以“人拟黄花”的比喻，与全词的整体形象相结合。“帘卷西风”一句，更直接为“人比黄花瘦”句作环境气氛的渲染，使人想象出一幅画面：重阳佳节佳人独对西风中的瘦菊。有了时令与环境气氛的烘托，“人比黄花瘦”才有了更深厚的寄托，此句也才能为千古传诵的佳句。\n\n　　此词的另一个特点是含蓄。唐司空图认为含蓄的主要特征是：“不著一字，尽得风流。语不涉及，若不堪忧。”（《诗品·含蓄》）从字面上看，这首《醉花阴》没有写离别之苦，相思之情，但仔细寻味，它的每个字都浸透了这一点。从她不时去看香炉里的瑞脑燃烧了多少（也即时间过去了多少）的细节中，读者可以感到她简直是度日如年。白天好不容易挨过去了，晚上更加难捱。李清照不直接写“每逢佳节倍思亲”，而是写失眠，写一直到半夜都没有睡着。看来她不只是身体感到凉，主要的还是内心感到凉。于是她对赵明诚那苦苦思念之情便从字里行间洋溢而出。读罢全词，一位不堪忍受离别之苦的少妇形象生动地立在读者眼前。\n\n　　全词明白如话，没有冷涩难懂之处，表达的感情却十分深沉细腻。畅达与深沉相结合，这正是李清照词风的一个重要特点。', poem_tags = '宋词三百首,宋词精选,初中古诗,婉约,重阳节,怀人,菊花' WHERE poem_title = '醉花阴·薄雾浓云愁永昼' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '提一壶美酒摆在花丛间，自斟自酌无友无亲。\n举杯邀请明月，对着身影成为三人。\n明月当然不会喝酒，身影也只是随着我身。\n我只好和他们暂时结成酒伴，要行乐就必须把美好的春光抓紧。\n我唱歌明月徘徊，我起舞身影零乱。\n醒时一起欢乐，醉后各自分散。\n我愿与他们永远结下忘掉伤情的友谊，相约在缥缈的银河边。', poem_notes = '酌：饮酒。独酌：一个人饮酒。\n间：一作“下”，一作“前”。\n无相亲：没有亲近的人。\n“举杯”二句：我举起酒杯招引明月共饮，明月和我以及我的影子恰恰合成三人。一说月下人影、酒中人影和我为三人。\n既：已经。不解：不懂，不理解。三国魏嵇康《琴赋》：“推其所由，似元不解音声。”\n徒：徒然，白白的。徒：空。\n将：和，共。\n及春：趁着春光明媚之时。\n月徘徊：明月随我来回移动。\n影零乱：因起舞而身影纷乱。\n同交欢：一起欢乐。一作“相交欢”。\n无情游：月、影没有知觉，不懂感情，李白与之结交，故称“无情游”。\n相期邈（miǎo）云汉：约定在天上相见。期：约会。邈：遥远。云汉：银河。这里指遥天仙境。“邈云汉”一作“碧岩畔”。', poem_appreciation = '这是一个精心剪裁出来的场面，写来却是那么自然。李白月下独酌，面对明月与影子，似乎在幻觉中形成了三人共饮的画面。在这温暖的春夜，李白边饮边歌舞，月与影也紧随他那感情的起伏而起伏，仿佛也在分享他饮酒的欢乐与忧愁。从逻辑上讲，物与人的内心世界并无多少关系。但从诗意的角度上看，二者却有密不可分的关系。这也正是中国诗歌中的“兴”之起源。它从《诗经》开始就一直赋予大自然以拟人的动作、思想与情感，如“月出皎兮，佼人僚兮”，“愁月”“悲风”等等。李白此诗正应了这“兴”之写法，赋明月与影子以情感。正如林语堂所说：“它是一种诗意的与自然合调的信仰，这使生命随着人类情感的波动而波动。”\n\n　　但在诗之末尾，李白又流露出一种独而不独，不独又独的复杂情思，他知道了月与影本是无情物，只是自己多情而已。面对这个无情物，李白依然要永结无情游，意思是月下独酌时，还是要将这月与影邀来相伴歌舞，哪怕是“相期邈云汉”，也在所不辞。可见太白之孤独之有情已到了何等地步！斯蒂芬·欧文曾说：“诗歌是一种工具，诗人通过诗歌而让人了解和叹赏他的独特性。”李白正是有了这首“对影成三人”的《月下独酌》，才让人们了解和叹赏他的独特性的。无论男女老少，任何一个中国人，只要他举杯浅酌，都会吟咏“举杯邀明月，对影成三人”，以表他对所谓风雅与独饮的玩味。而这首诗的独特性，早已化入民族的集体无意识之中了。', poem_tags = '唐诗三百首,初中古诗,孤独,月下,饮酒,抒情' WHERE poem_title = '月下独酌四首·其一' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '瑟本有二十五根弦，但此诗创作于李商隐妻子死后，故五十弦有断弦之意\n但即使这样它的每一弦、每一音节，足以表达对那美好年华的思念。（此句为转折句。）\n庄周其实知道自己只是向往那自由自在的蝴蝶。（本句是对“华年”的阐释。）\n望帝那美好的心灵和作为可以感动杜鹃。（本句亦是对“华年”的阐释。）\n大海里明月的影子像是眼泪化成的珍珠。（喻指诗人的悲哀，即使是一个明媚的夜晚，依然想到的是眼泪。）\n只有在彼时彼地的蓝田才能生成犹如生烟似的良玉。（暗指诗人对当时社会局势的不满。）\n那些美好的事和年代，只能留在回忆之中了。（亦指自己对青春年华的追思之情。）\n而在当时那些人看来那些事都只是平常罢了，却并不知珍惜。（亦指自己在年轻时对生活的态度也是那样不知珍惜。）', poem_notes = '⑴锦瑟无端五十弦，一弦一柱思华年：《周礼·乐器图》：“雅瑟二十三弦，颂瑟二十五弦，饰以宝玉者曰宝瑟，绘文如锦者曰锦瑟。”《汉书·郊祀志上》：“秦帝使素女鼓五十弦瑟，悲，帝禁不止，故破其瑟为二十五弦。”古瑟大小不等，弦数亦不同。义山《回中牡丹为雨所败》诗有“锦瑟惊弦破梦频”；《七月二十八日夜与王郑二秀才听雨后梦作》诗有“雨打湘灵五十弦”。无端：没来由，无缘无故。此隐隐有悲伤之感，乃全诗之情感基调。历代解义山诗者，多以此诗为晚年之作。李商隐妻子故去，所以二十五根弦断后变为五十弦。“思”字变读去声（sì），律诗中不许有一连三个平声的出现。\n⑵庄生晓梦迷蝴蝶：《庄子·齐物论》：“庄周梦为蝴蝶，栩栩然蝴蝶也；自喻适志与！不知周也。俄然觉，则蘧蘧然周也。不知周之梦为蝴蝶与？蝴蝶之梦为周与。”商隐此引庄周梦蝶故事，以言人生如梦，往事如烟之意。\n佳人锦瑟，一曲繁弦，惊醒了诗人的梦景，不复成寐。这里面隐约包涵着美好的情境，却又是虚缈的梦境。也有着人生如梦的惆怅和迷惘。\n⑶望帝春心托杜鹃：《华阳国志·蜀志》：“杜宇称帝，号曰望帝。……其相开明，决玉垒山以除水害，帝遂委以政事，法尧舜禅授之义，遂禅位于开明。帝升西山隐焉。时适二月，子鹃鸟鸣，故蜀人悲子鹃鸟鸣也。”子鹃即杜鹃，又名子规。蔡梦弼《杜工部草堂诗笺》一九《杜鹃》诗注引《成都记》：“望帝死，其魂化为鸟，名曰杜鹃，亦曰子规。”传说蜀国的杜宇帝因水灾让位于自己的臣子，而自己则隐归山林，死后化为杜鹃日夜悲鸣直至啼出血来.。\n⑷沧海月明珠有泪：《博物志》：“南海外有鲛人，水居如鱼，不废绩织，其眼泣则能出珠。”《新唐书·狄仁杰传》：“仁杰举明经，调汴州参军，为吏诬诉黜陟，使闫立本如讯，异其才，谢曰：‘仲尼称观过知仁，君可谓沧海遗珠矣。’”\n⑸蓝田日暖玉生烟：《元和郡县志》：“关内道京兆府蓝田县：蓝田山，一名玉山，在县东二十八里。”《文选》陆机《文赋》：“石韫玉而山辉，水怀珠而川媚。”《困学纪闻》卷十八：司空表圣云：“戴容州谓诗家之景，如蓝田日暖，良玉生烟，可望而不可置于眉睫之前也。李义山玉生烟之句盖本于此。”\n⑹此情可待成追忆，只是当时已惘然：拢束全篇，明白提出“此情”二字，与开端的“华年”相为呼应。诗句是说：如此情怀，岂待今朝回忆始感无穷怅恨，即在当时早已是令人不胜惘然惆怅了.那么今朝追忆，其为怅恨，又当如何！诗人用这两句诗表达出了几层曲折，而几层曲折又只是为了说明那种怅惘的苦痛心情。\n五十的锦瑟乃是天神所用，世间用的锦瑟乃是二十五弦的。五十弦的锦瑟，音律太丰富，音域太广阔，音韵太悲美而让凡人享受不了，五十弦的锦瑟是作者自喻：才高志远却难为世用。', poem_appreciation = '这首诗历来注释不一，莫衷一是。或以为是悼亡之作，或以为是爱国之篇或以为是自比文才之论，或以为是抒写思念侍儿锦瑟。但以为是悼亡死者为最多。有人认为，开首以瑟弦五十折半为二十五，隐指亡妇华年二十五岁。这话未免有嫌牵强。但是，首联哀悼早逝却是真实。颔联以庄子亡妻鼓盆而歌和期效望帝化成子规而啼血，间接地描写了人生的悲欢离合。颈联以鲛人泣珠和良玉生烟的典故，隐约地描摹了世间风情迷离恍惚，可望而不可至。最后抒写生前情爱漫不经心，死后追忆已经惘然的难以排遣的情绪。\n\n　　宋刘攽《贡父诗话》云：“《锦瑟》诗，人莫晓其意，或谓是令狐楚家青衣也。”《苕溪渔隐丛话》前集卷二十二引黄朝英《缃素杂记》曰：“义山《锦瑟》诗云……山谷道人读此诗，殊不解其意，后以问东坡。东坡云：‘此出《古今乐志》，云：锦瑟之为器也，其弦五十，其柱如之。其声也适、怨、清、和。’案李诗‘庄生……’，适也；‘望帝……’，怨也；‘沧海……’，清也；‘蓝田……’，和也。一篇之中，曲尽其意。史称其瑰迈奇古，信然。”元好问《论诗绝句》云：“望帝春心托杜鹃，佳人锦瑟怨华年。诗家总爱西昆好，独恨无人作郑笺”；以上咏“青衣”（艳情）说乃小说家言；咏锦瑟说颇得宋人赞同。明人胡应麟于此二说皆疑之。其后说者纷纭，大抵有“自伤生平”（清何焯、汪师韩、薛雪、宋翔凤）说、“悼亡”（清朱鹤龄、朱彝尊、何焯、冯浩、程梦星、姚培谦、近人张采田、孟森等）说、“政治寄托”（清杜诏，近人张采田、岑仲勉等）说、“诗序”（清何焯、王应奎、）说、“寄托不明”（清屈复、近人梁启超）说、“自寓创作”（钱钟书）说等。其中持“悼亡”或“自伤”说者较多。然“悼亡”实际上也是“自伤”的内涵之一，故“自伤”说似更圆通。兹引刘、余《集解》以备参读：“自伤身世之说，较为切实合理。……首联谓见此五十弦之锦瑟，闻其弦弦所发之悲音，不禁怅然而忆己之华年往事。……颔腹二联，即‘思华年’而写回忆中之华年往事，……‘庄生’句系状瑟声之如梦似幻，令人迷惘，用意在‘梦’字‘迷’字。而此种境界亦即以象征诗人身世之如梦似幻，惘然若迷。……‘望帝’句系写瑟声之凄迷哀怨，如泣鹃啼血，着意在‘春心’字、‘托’字。‘春心’本指爱情之向往追求，常用以喻指对理想之追求。……‘望帝’句殆谓己之壮心雄图及伤时忧国、感伤身世之情均托之哀怨凄断之诗歌，如望帝之化鹃以自抒哀怨也。杜鹃即作者之诗魂。……‘沧海’句写瑟声之清寥悲苦……正含沧海遗珠之意。……‘蓝田’句似写瑟声之缥缈朦胧……或以喻己所向往追求者，皆望之若有，近之则无。……要之，颔、腹二联并非具体叙述其华年往事，而系借瑟声之迷幻、哀怨、清寥、缥缈以概括抒写其华年所历之种种人生遭际、人生境界、人生感受。……末联含义明白……谓上述失意哀伤情事岂待今日追忆方不胜怅恨，即在当时亦惘然若失矣。”\n\n　　关于这首诗的解读主要分为两类：\n\n　　一是认为这是一首评悼妻子王氏的诗，首联为“景”，看到素女弹五十弦瑟而触景生情；颔联为比“喻”，借庄周化蝶，杜鹃啼血比喻妻子的死亡；颈联为“幻”，珍珠为之落泪，宝玉为之忧伤；尾联为“感”，情已逝，追思也是惘然！\n\n　　二是认为这是诗人对逝去年华的追忆，首联为“起”，借五十弦之瑟喻人生之五十年华；颔联为比“承”，在浑然不觉间人生将走到尽头；颈联为“转”，以明珠宝玉比喻自己的才能；尾联为“合”，岁月催人老，一切都是惘然！', poem_tags = '唐诗三百首,思念,爱情,抒情' WHERE poem_title = '锦瑟' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '古人做学问是不遗余力的，往往要到老年才取得成就。\n从书本上得来的知识，毕竟是不够完善的。如果想要深入理解其中的道理，必须要亲自实践才行。', poem_notes = '示：训示、指示。子聿(yù)：陆游的小儿子。\n学问：指读书学习，就是学习的意思。遗：保留，存留。无遗力：用出全部力量，没有一点保留，不遗余力、竭尽全力。\n少壮：青少年时代。工夫：做事所耗费的时间。始：才。\n纸：书本。终：到底，毕竟。觉：觉得。浅：肤浅，浅薄，有限的。\n绝知：深入、透彻的理解。行：实践。躬行：亲身实践。', poem_appreciation = '首联诗人赞扬了古人刻苦做学问精神。颔联是说做学问的艰难。诗的前两句，赞扬了古人刻苦学习的精神以及做学问的艰难。说明只有少年时养成良好的学习习惯，竭尽全力地打好扎实基础，将来才能成就一番事业。诗人从古人做学问入手娓娓道来，其中“无遗力”三个字，形容古人做学问勤奋用功、孜孜不倦的程度，既生动又形象。诗人语重心长地告诫儿子，趁着年少精力旺盛，抓住美好时光奋力拼搏，莫让青春年华付诸东流。\n\n　　后两联，强调了做学问的功夫要下在哪里的重要性。孜孜不倦、持之以恒地做学知识，固然很重要，但仅此还不够，因为那只是书本知识，书本知识是前人实践经验的总结，不能纸上谈兵，要“亲身躬行”。一个既有书本知识，又有实践经验的人，才是真正有学问的人。书本知识是前人实践经验的总结，能否符合此时此地的情况，还有待实践去检验。只有经过亲身实践，才能把书本上的知识变成自己的实际本领。诗人从书本知识和社会实践的关系着笔，强调实践的重要性，凸显其真知灼见。“要躬行”包含两层意思：一是学习过程中要“躬行”，力求做到“口到、手到、心到”，二是获取知识后还要“躬行”，通过亲身实践化为己有，转为己用。诗人的意图非常明显，旨在激励儿子不要片面满足于书本知识，而应在实践中夯实和进一步获得升华。\n\n　　这是一首教子诗，诗人在书本与实践的关系上强调了实践的重要性。间接经验是人们从书本中汲取营养，学习前人的知识和技巧的途径。直接经验是直接从实践中产生的认识，是获取知识更加重要的途径。只有通过“躬行”，把书本知识变成实际知识，才能发挥所学知识对实践的指导作用。本诗通过写陆游对儿子子聿的教育，告诉读者做学问要有孜孜不倦、持之以恒的精神。一个既有书本知识，又有实践精神的人，才是真正有学问的人。', poem_tags = '励志,读书,哲理,早教古诗100首' WHERE poem_title = '冬夜读书示子聿' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '天空黑暗，大风卷着江湖上的雨，四周的山上哗哗大雨像巨浪翻滚之声。\n溪柴烧的小火和裹在身上的毛毡都很暖和，我和猫儿都不愿出门。\n\n我直挺挺躺在孤寂荒凉的乡村里，没有为自己的处境而感到悲哀，心中还想着替国家防卫边疆。\n夜将尽了，我躺在床上听到那风雨的声音，迷迷糊糊地梦见，自己骑着披着铁甲的战马跨过冰封的河流出征北方疆场。', poem_notes = '溪柴：若耶溪所出的小束柴火。\n蛮毡：中国西南和南方少数民族地区出产的毛毡，宋时已有生产。宋范成大《桂海虞衡志·志器》：“蛮毡出西南诸番，以大理者为最，蛮人昼披夜卧，无贵贱，人有一番。”\n狸奴：指生活中被人们驯化而来的猫的昵称。\n僵卧：躺卧不起。这里形容自己穷居孤村，无所作为。僵，僵硬。\n孤村：孤寂荒凉的村庄。\n不自哀：不为自己哀伤。\n思：想着，想到。\n戍（shù）轮台：在新疆一带防守，这里指戍守边疆。戍，守卫。轮台：在今新疆境内，是古代边防重地。此代指边关。\n夜阑（lán）：夜深。\n风吹雨：风雨交加，和题目中“风雨大作”相呼应；当时南宋王朝处于风雨飘摇之中，“风吹雨”也是时局写照，故诗人直到深夜尚难成眠。\n铁马：披着铁甲的战马。\n冰河：冰封的河流，指北方地区的河流。', poem_appreciation = '此诗作于宋光宗绍熙三年(公元1192年),时年诗人67岁,闲居在故乡山阴(今浙江省绍兴市).原诗共两首,此处所选的是其中的第二首.与诗人其他的老年诗相比,这首诗在写法上别具一格.其主要特色在于以梦境抒发情怀.写到梦境的诗词,在陆游之前已有不少佳作.李白的诗《梦游天姥吟留别》,描绘的是光怪陆离、异彩纷呈的梦;杜甫的诗《梦李白二首》,摹写的是渗透了诗人与李白形离神合、肝胆相照友谊的梦;苏轼的词《江城子》(“十年生死两茫茫“),记叙的是诗人悼念亡妻、寄托哀思的梦.而陆游诗中的梦,大都是爱国之梦.在陆游的《剑南诗稿》中有近百首记梦的诗.清代赵翼《瓯北诗话》卷六曾评陆游诗道:“即如记梦诗,核计全集,共九十九首.人生安得有如许梦!此必有诗无题,遂托之于梦耳.“此评语认为陆游的诗记梦并非全是写真梦,有的属于托梦咏怀.这是颇有见地的.事实上,陆游的诗记梦,有的是写真梦,而更多的还是托梦咏怀,当然,也不排除二者兼而有之.这首《十一月四日风雨大作》似可视为既写真梦又托梦咏怀之作.\n\n　　此诗前三句,写梦因.“僵卧“:躺着不动.“孤村“:一作荒村.“轮台“:汉代西域地名,即今新疆维吾尔自治区轮台县;诗中泛指边防重镇.个中包含三个层次.一是梦境产生的前提:“僵卧“、“夜阑“.俗话说:“日有所思,夜有所梦.“诗人白日忧国忧民,才会在夜阑卧床睡眠中“有所梦“,而倘若不是“僵卧“,不是“夜阑“,就不可能有梦的出现.故“僵卧“与“夜阑“是梦境产生的前提.二是梦境产生的主观因素:“尚思为国戍轮台.“如果诗人没有为国戍边的情怀,就不可能有“铁马冰河入梦来“.三是梦境产生的外界条件:“风吹雨.“可以说,正是有了“风吹雨“这一外界条件,诗人才在似睡非睡、模模糊糊之中生出“铁马冰河“的梦境来.\n\n　　最后一句,写梦境.与诗人那些通篇记梦的诗作有别,此诗写梦境也独树一帜.全诗由梦因引出“铁马冰河“的梦境之后便戛然而止,给人留下更多联想、想象的空间.人们尽可以据此梦境展开丰富的想象,具体想象诗人当年是如何身披铁甲,手持兵器,骑那披着铁甲的战马驰骋沙场、英勇杀敌,作此诗时他又是如何梦绕神牵“九州同“的.\n\n　　可见,思想性与艺术性较为完美的统一,使得此诗成为陆游的代表作之一,也成为中国古代包括老年诗在内的所有诗歌的代表作之一.', poem_tags = '古诗三百首,初中古诗,爱国,壮志' WHERE poem_title = '十一月四日风雨大作二首' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '我是在无花可观赏，无酒可饮的情况下过这个清明节的，这样寂寞清苦的生活，就像荒山野庙的和尚，一切对于我来说都显得很萧条寂寞。\n昨天从邻家讨来新燃的火种，在清明节的一大早，就在窗前点灯，坐下来潜心读书。', poem_notes = '兴味：兴趣、趣味。 \n萧然：清净冷落。 \n新火：唐宋习俗，清明前一日禁火寒食，到清明节再起火，称为“新火”。', poem_tags = '清明节,生活,凄苦' WHERE poem_title = '清明' AND poem_author = '王禹偁';
UPDATE edu_poem SET poem_translation = '春日里贪睡不知不觉天已破晓，搅乱我酣眠的是那啁啾的小鸟。\n昨天夜里风声雨声一直不断，那娇美的春花不知被吹落了多少？', poem_notes = '晓：天刚亮的时候，春晓：春天的早晨。\n不觉晓：不知不觉天就亮了。\n啼鸟：鸟的啼叫声。\n知多少：不知有多少。', poem_appreciation = '《春晓》这首小诗，初读似觉平淡无奇，反复读之，便觉诗中别有天地。它的艺术魅力不在于华丽的辞藻，不在于奇绝的艺术手法，而在于它的韵味。整首诗的风格就像行云流水一样平易自然，然而悠远深厚，独臻妙境。千百年来，人们传诵它，探讨它，仿佛在这短短的四行诗里，蕴涵着开掘不完的艺术宝藏。\n\n　　自然而无韵致，则流于浅薄；若无起伏，便失之平直。《春晓》既有悠美的韵致，行文又起伏跌宕，所以诗味醇永。诗人要表现他喜爱春天的感情，却又不说尽，不说透，“迎风户半开”，让读者去捉摸、去猜想，处处表现得隐秀曲折。\n\n　　“情在词外曰隐，状溢目前曰秀。”（张戒《岁寒堂诗话》引）写情，诗人选取了清晨睡起时刹那间的感情片段进行描写。这片段，正是诗人思想活动的启始阶段、萌芽阶段，是能够让人想象他感情发展的最富于生发性的顷刻。诗人抓住了这一刹那，却又并不铺展开去，他只是向读者透露出他的心迹，把读者引向他感情的轨道，就撒手不管了，剩下的，该由读者沿着诗人思维的方向去丰富和补充了。写景，他又只选取了春天的一个侧面。春天，有迷人的色彩，有醉人的芬芳，诗人都不去写。他只是从听觉角度着笔，写春之声：那处处啼鸟，那潇潇风雨。鸟声婉转，悦耳动听，是美的。加上“处处”二字，啁啾起落，远近应和，就更使人有置身山阴道上，应接不暇之感。春风春雨，纷纷洒洒，但在静谧的春夜，这沙沙声响却也让人想见那如烟似梦般的凄迷意境，和微雨后的众卉新姿。这些都只是诗人在室内的耳闻，然而这阵阵春声却逗露了无边春色，把读者引向了广阔的大自然，使读者自己去想象、去体味那莺啭花香的烂熳春光，这是用春声来渲染户外春意闹的美好景象。这些景物是活泼跳跃的，生机勃勃的。它写出了诗人的感受，表现了诗人内心的喜悦和对大自然的热爱。\n\n　　宋人叶绍翁《游园不值》诗中的“春色满园关不住，一枝红杏出墙来”，是古今传诵的名句。其实，在写法上是与《春晓》有共同之处的。叶诗是通过视觉形象，由伸出墙外的一枝红杏，把人引入墙内、让人想象墙内；孟诗则是通过听觉形象，由阵阵春声把人引出屋外、让人想象屋外。只用淡淡的几笔，就写出了晴方好、雨亦奇的繁盛春意。两诗都表明，那盎然的春意，自是阻挡不住的，你看，它不是冲破了围墙屋壁，展现在你的眼前、萦回在你的耳际了吗？\n\n　　施补华曰：“诗犹文也，忌直贵曲。”（《岘佣说诗》）这首小诗仅仅四行二十个字，写来却曲屈通幽，回环波折。首句破题，“春”字点明季节，写春眠的香甜。“不觉”是朦朦胧胧不知不觉。在这温暖的春夜中，诗人睡得真香，以至旭日临窗，才甜梦初醒。流露出诗人爱春的喜悦心情。次句写春景，春天早晨的鸟语。“处处”是指四面八方。鸟噪枝头，一派生机勃勃的景象。“闻啼鸟”即“闻鸟啼”，古诗为了押韵，词序作了适当的调整。三句转为写回忆，诗人追忆昨晚的潇潇春雨。末句又回到眼前，联想到春花被风吹雨打、落红遍地的景象，由喜春翻为惜春，诗人把爱春和惜春的情感寄托在对落花的叹息上。爱极而惜，惜春即是爱春──那潇潇春雨也引起了诗人对花木的担忧。时间的跳跃、阴晴的交替、感情的微妙变化，都很富有情趣，能给人带来无穷兴味。\n\n　　《春晓》的语言平易浅近，自然天成，一点也看不出人工雕琢的痕迹。而言浅意浓，景真情真，就像是从诗人心灵深处流出的一股泉水，晶莹透澈，灌注着诗人的生命，跳动着诗人的脉搏。读之，如饮醇醪，不觉自醉。诗人情与境会，觅得大自然的真趣，大自然的神髓。“文章本天成，妙手偶得之”，这是最自然的诗篇，是天籁。', poem_tags = '唐诗三百首,小学古诗,写景,惜春,早教古诗100首' WHERE poem_title = '春晓' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '黄四娘家花儿茂盛把小路遮蔽，万千花朵压弯枝条离地低又低。\n眷恋芬芳花间彩蝶时时在飞舞，自由自在娇软黄莺恰恰欢声啼。', poem_notes = '黄四娘：杜甫住成都草堂时的邻居。蹊（xī）：小路。\n留连：即留恋，舍不得离去。\n娇：可爱的样子。恰恰：象声词，形容鸟叫声音和谐动听。一说“恰恰”为唐时方言，恰好之意。', poem_appreciation = '第六首写寻花到了黄四娘家。这首诗记叙在黄四娘家赏花时的场面和感触，描写草堂周围烂漫的春光，表达了对美好事物的热爱之情和适意之怀。春花之美、人与自然的亲切和谐，都跃然纸上。首句点明寻花的地点，是在“黄四娘家”的小路上。此句以人名入诗，生活情趣较浓，颇有民歌味。次句“千朵万朵”，是上句“满”字的具体化。“压枝低”，描绘繁花沉甸甸地把枝条都压弯了，景色宛如历历在目。“压”、“低”二字用得十分准确、生动。第三句写花枝上彩蝶蹁跹，因恋花而“留连”不去，暗示出花的芬芳鲜妍。花可爱，蝶的舞姿亦可爱，不免使漫步的人也“留连”起来。但他也许并未停步，而是继续前行，因为风光无限，美景尚多。“时时”，则不是偶尔一见，有这二字，就把春意闹的情趣渲染出来。正在赏心悦目之际，恰巧传来一串黄莺动听的歌声，将沉醉花丛的诗人唤醒。这就是末句的意境。“娇”字写出莺声轻软的特点。“自在”不仅是娇莺姿态的客观写照，也传出它给作者心理上的愉快轻松的感觉。诗在莺歌“恰恰”声中结束，饶有余韵。此诗写的是赏景，这类题材，盛唐绝句中屡见不鲜。但像此诗这样刻画十分细微，色彩异常秾丽的，则不多见。如“故人家在桃花岸，直到门前溪水流”（常建《三日寻李九庄》），“昨夜风开露井桃，未央前殿月轮高”（王昌龄《春宫曲》），这些景都显得“清丽”；而杜甫在“花满蹊”后，再加“千朵万朵”，更添蝶舞莺歌，景色就秾丽了。这种写法，可谓前无古人。其次，盛唐人很讲究诗句声调的和谐。他们的绝句往往能被诸管弦，因而很讲协律。杜甫的绝句不为歌唱而作，纯属诵诗，因而常常出现拗句。如此诗“千朵万朵压枝低”句，按律第二字当平而用仄。但这种“拗”决不是对音律的任意破坏，“千朵万朵”的复叠，便具有一种口语美。而“千朵”的“朵”与上句相同位置的“四”字，虽同属仄声，但彼此有上、去声之别，声调上仍具有变化。诗人也并非不重视诗歌的音乐美。这表现在三、四两句双声词、象声词与叠字的运用。“留连”、“自在”均为双声词，如贯珠相联，音调宛转。“时时”、“恰恰”为叠字，即使上下两句形成对仗，使语意更强，更生动，更能表达诗人迷恋在花、蝶之中，忽又被莺声唤醒的刹那间的快意。这两句除却“舞”、“莺”二字，均为舌齿音，这一连串舌齿音的运用造成一种喁喁自语的语感，维妙维肖地状出看花人为美景陶醉、惊喜不已的感受。声音的效用极有助于心情的表达。在句法上，盛唐诗句多天然浑成，杜甫则与之异趣。比如“对结”（后联骈偶）乃初唐绝句格调，盛唐绝句已少见，因为这种结尾很难做到神完气足。杜甫却因难见巧，如此诗后联既对仗工稳，又饶有余韵，用得恰到好处：在赏心悦目之际，听到莺歌“恰恰”，增添不少感染力。此外，这两句按习惯文法应作：戏蝶留连时时舞，娇莺自在恰恰啼。把“留连”、“自在”提到句首，既是出于音韵上的需要，同时又在语意上强调了它们，使含义更易体味出来，句法也显得新颖多变。\n\n　　最后一首：“不是爱花即欲死”。痛快干脆，毫不藏伏。杜甫惯于一拚到底，常用狠语，如“语不惊人死不休”，即是如此。他又写道：“只恐花尽老相催。”怕的是花谢人老。下两句则是写景，写花枝之易落，花蕊的慢开，景中寓借花之深情，以对句出之，更是加倍写法，而又密不透风，情深语细。', poem_tags = '小学古诗,写景,写花' WHERE poem_title = '江畔独步寻花·其六' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '风急天高猿猴啼叫显得十分悲哀，水清沙白的河洲上有鸟儿在盘旋。\n无边无际的树木萧萧地飘下落叶，望不到头的长江水滚滚奔腾而来。 　\n悲对秋景感慨万里漂泊常年为客，一生当中疾病缠身今日独上高台。 　\n历尽了艰难苦恨白发长满了双鬓，衰颓满心偏又暂停了浇愁的酒杯。', poem_notes = '诗题一作《九日登高》。古代农历九月九日有登高习俗。选自《杜诗详注》。作于唐代宗大历二年（767）秋天的重阳节。\n啸哀：指猿的叫声凄厉。\n渚(zhǔ)：水中的小洲；水中的小块陆地。鸟飞回：鸟在急风中飞舞盘旋。回：回旋。\n落木：指秋天飘落的树叶。萧萧：模拟草木飘落的声音。\n万里：指远离故乡。常作客：长期漂泊他乡。\n百年：犹言一生，这里借指晚年。\n艰难：兼指国运和自身命运。苦恨：极恨，极其遗憾。苦，极。繁霜鬓：增多了白发，如鬓边着霜雪。 繁，这里作动词，增多。\n潦倒：衰颓，失意。这里指衰老多病，志不得伸。新停：刚刚停止。杜甫晚年因病戒酒，所以说“新停”。', poem_appreciation = '此诗载于《杜工部集》，全诗通过登高所见秋江景色，倾诉了诗人长年漂泊、老病孤愁的复杂感情，慷慨激越、动人心弦。\n\n　　此诗前四句写登高见闻。首联对起。诗人围绕夔州的特定环境，用“风急”二字带动全联，一开头就写成了千古流传的佳句。夔州向以猿多著称，峡口更以风大闻名。秋日天高气爽，这里却猎猎多风。诗人登上高处，峡中不断传来“高猿长啸”之声，大有“空谷传响，哀转久绝”（《水经注·江水》）的意味。诗人移动视线，由高处转向江水洲渚，在水清沙白的背景上，点缀着迎风飞翔、不住回旋的鸟群，真是一幅精美的画图。其中天、风，沙、渚，猿啸、鸟飞，天造地设，自然成对。不仅上下两句对，而且还有句中自对，如上句“天”对“风”，“高”对“急”；下句“沙”对“渚”，“白”对“清”，读来富有节奏感。经过诗人的艺术提炼，十四个字，字字精当，无一虚设，用字遣辞，“尽谢斧凿”，达到了奇妙难名的境界。更值得注意的是：对起的首句，末字常用仄声，此诗却用平声入韵。沈德潜因有“起二句对举之中仍复用韵，格奇而变”（《唐诗别裁》）的赞语。\n\n　　颔联集中表现了夔州秋天的典型特征。诗人仰望茫无边际、萧萧而下的木叶，俯视奔流不息、滚滚而来的江水，在写景的同时，便深沉地抒发了自己的情怀。“无边”“不尽”，使“萧萧”“滚滚”更加形象化，不仅使人联想到落木窸窣之声，长江汹涌之状，也无形中传达出韶光易逝，壮志难酬的感怆。透过沉郁悲凉的对句，显示出神入化之笔力，确有“建瓴走坂”、“百川东注”的磅礴气势。前人把它誉为“古今独步”的“句中化境”，是有道理的。\n\n　　前两联极力描写秋景，直到颈联，才点出一个“秋”字。“独登台”，则表明诗人是在高处远眺，这就把眼前景和心中情紧密地联系在一起了。“常作客”，指出了诗人飘泊无定的生涯。“百年”，本喻有限的人生，此处专指暮年。“悲秋”两字写得沉痛。秋天不一定可悲，只是诗人目睹苍凉恢廓的秋景，不由想到自己沦落他乡、年老多病的处境，故生出无限悲愁之绪。诗人把久客最易悲愁，多病独爱登台的感情，概括进一联“雄阔高浑，实大声弘”的对句之中，使人深深地感到了他那沉重地跳动着的感情脉搏。此联的“万里”“百年”和上一联的“无边”“不尽”，还有相互呼应的作用：诗人的羁旅愁与孤独感，就象落叶和江水一样，推排不尽，驱赶不绝，情与景交融相洽。诗到此已给作客思乡的一般含意，添上久客孤独的内容，增入悲秋苦病的情思，加进离乡万里、人在暮年的感叹，诗意就更见深沉了。\n\n　　尾联对结，并分承五六两句。诗人备尝艰难潦倒之苦，国难家愁，使自己白发日多，再加上因病断酒，悲愁就更难排遣。本来兴会盎然地登高望远，此时却平白无故地惹恨添悲，诗人的矛盾心情是容易理解的。前六句“飞扬震动”，到此处“软冷收之，而无限悲凉之意，溢于言外”（《诗薮》）。\n\n　　诗前半写景，后半抒情，在写法上各有错综之妙。首联着重刻画眼前具体景物，好比画家的工笔，形、声、色、态，一一得到表现。次联着重渲染整个秋天气氛，好比画家的写意，只宜传神会意，让读者用想象补充。三联表现感情，从纵（时间）、横（空间）两方面着笔，由异乡飘泊写到多病残生。四联又从白发日多，护病断饮，归结到时世艰难是潦倒不堪的根源。这样，杜甫忧国伤时的情操，便跃然张上。\n\n　　此诗八句皆对。粗略一看，首尾好像“未尝有对”，胸腹好象“无意于对”。仔细玩味，“一篇之中，句句皆律，一句之中，字字皆律”。不只“全篇可法”，而且“用句用字”，“皆古今人必不敢道，决不能道者”。它能博得“旷代之作”（均见胡应麟《诗薮》）的盛誉，就是理所当然的了。', poem_tags = '唐诗三百首,秋天,登高,写景,抒情,忧国忧民,早教古诗100首' WHERE poem_title = '登高' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '很少有人活动只有桂花无声地飘落，夜里一片静谧春日的山谷寂寂空空。\n明月升起光辉照耀惊动了山中栖鸟，不时地高飞鸣叫在这春天的溪涧中。', poem_notes = '鸟鸣涧：鸟儿在山涧中鸣叫。\n人闲：指没有人事活动相扰。闲：安静、悠闲，含有人声寂静的意思。桂花：此指木樨，有春花、秋花等不同品种，这里写的是春天开花的一种。\n春山：春日的山。亦指春日山中。空：空寂、空空荡荡。空虚。这时形容山中寂静，无声，好像空无所有。\n月出：月亮升起。惊：惊动，扰乱。山鸟：山中的鸟。\n时鸣：偶尔（时而）啼叫。时：时而，偶尔。', poem_appreciation = '关于这首诗中的桂花，颇有些分歧意见。一种解释是桂花有春花、秋花、四季花等不同种类，此处所写的当是春日开花的一种。另一种意见认为文艺创作不一定要照搬生活，传说王维画的《袁安卧雪图》，在雪中还有碧绿的芭蕉，现实生活中不可能同时出现的事物，在文艺创作中是允许的。不过，这首诗是王维题友人所居的《皇甫岳云溪杂题五首》之一。五首诗每一首写一处风景，接近于风景写生，而不同于一般的写意画，因此，以解释为山中此时实有的春桂为妥。\n\n　　桂树枝叶繁茂，而花瓣细小。花落，尤其是在夜间，并不容易觉察。因此，开头“人闲”二字不能轻易看过。“人闲”说明周围没有人事的烦扰，说明诗人内心的闲静。有此作为前提，细微的桂花从枝上落下，才被觉察到了。诗人能发现这种“落”，或仅凭花落在衣襟上所引起的触觉，或凭声响，或凭花瓣飘坠时所发出的一丝丝芬芳。总之，“落”所能影响于人的因素是很细微的。而当这种细微的因素，竟能被从周围世界中明显地感觉出来的时候，诗人则又不禁要为这夜晚的静谧和由静谧格外显示出来的空寂而惊叹了。这里，诗人的心境和春山的环境气氛，是互相契合而又互相作用的。\n\n　　在这春山中，万籁都陶醉在那种夜的色调、夜的宁静里了。因此，当月亮升起，给这夜幕笼罩的空谷，带来皎洁银辉的时候，竟使山鸟惊觉起来。鸟惊，当然是由于它们已习惯于山谷的静默，似乎连月出也带有新的刺激。但月光之明亮，使幽谷前后景象顿时发生变化，亦可想见。所谓“月明星稀，乌鹊南飞”（曹操《短歌行》）是可以供读者联想的。但王维所处的是盛唐时期，不同于建安时代的兵荒马乱，连鸟兽也不免惶惶之感。王维的“月出惊山鸟”，大背景是安定统一的盛唐社会，鸟虽惊，但决不是“绕树三匝，无枝可依”。它们并不飞离春涧，甚至根本没有起飞，只是在林木间偶而发出叫声。“时鸣春涧中”，它们与其说是“惊”，不如说是对月出感到新鲜。因而，如果对照曹操的《短歌行》，在王维这首诗中，倒不仅可以看到春山由明月、落花、鸟鸣所点缀的那样一种迷人的环境，而且还能感受到盛唐时代和平安定的社会气氛。\n\n　　王维在他的山水诗里，喜欢创造静谧的意境，这首诗也是这样。但诗中所写的却是花落、月出、鸟鸣，这些动的景物，既使诗显得富有生机而不枯寂，同时又通过动，更加突出地显示了春涧的幽静。动的景物反而能取得静的效果，这是因为事物矛盾着的双方，总是互相依存的。在一定条件下，动之所以能够发生，或者能够为人们所注意，正是以静为前提的。“鸟鸣山更幽”，这里面是包含着艺术辩证法的。', poem_tags = '小学古诗,春天,写山,写鸟,早教古诗100首' WHERE poem_title = '鸟鸣涧' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '浩渺寒江之上弥漫着迷蒙的烟雾，皓月的清辉洒在白色沙渚之上。入夜，我将小舟泊在秦淮河畔，临近酒家。金陵歌女似乎不知何为亡国之恨黍离之悲，竟依然在对岸吟唱着淫靡之曲《玉树后庭花》。\n\n英译\nMist veils the cold stream, and moonlight the sand, as I moor in the shadow of a river-tavern,\nWhere girls, with no thought of a perished Kingdom, gaily echo a song of courtyard flowers.', poem_notes = '选自冯集梧《樊川文集》卷四。（上海古籍出版社1978年版）。秦淮，即秦淮河，发源于江苏句容大茅山与溧（lì）水东庐山两山间，经南京流入长江。相传为秦始皇南巡会稽时开凿的，用来疏通淮水，故称秦淮河。\n泊：停泊。\n商女：以卖唱为生的歌女。\n后庭花：歌曲《玉树后庭花》的简称。南朝陈皇帝陈叔宝（即陈后主）溺于声色，作此曲与后宫美女寻欢作乐，终致亡国，所以后世称此曲为“亡国之音”。', poem_appreciation = '《泊秦淮》是杜牧的代表作之一，载于《全唐诗》卷五百二十三。下面是安徽师范大学文学院教授赵其钧先生对此诗的赏析。\n\n　　建康是六朝都城，秦淮河穿过城中流入长江，两岸酒家林立，是当时豪门贵族、官僚士大夫享乐游宴的场所。唐王朝的都城虽不在建康，然而秦淮河两岸的景象却一如既往。\n\n　　有人说作诗“发句好尤难得”（严羽《沧浪诗话》）。这首诗中的第一句就是不同凡响的，那两个“笼”字就很引人注目。烟、水、月、沙四者，被两个“笼”字和谐地溶合在一起，绘成一幅极其淡雅的水边夜色。它是那么柔和幽静，而又隐含着微微浮动流走的意态，笔墨是那样轻淡，可那迷蒙冷寂的气氛又是那么浓。首句中的“月、水”，和第二句的“夜泊秦淮”是相关联的，所以读完第一句，再读“夜泊秦淮近酒家”，就显得很自然。但如果就诗人的活动来讲，该是先有“夜泊秦淮”，方能见到“烟笼寒水月笼沙”的景色，不过要真的掉过来一读，反而会觉得平板无味了。诗中这种写法的好处是：首先它创造出一个很具有特色的环境气氛，给人以强烈的吸引力，造成先声夺人的艺术效果，这是很符合艺术表现的要求的。其次，一、二句这么处理，就很像一幅画的画面和题字的关系。平常人们欣赏一幅画，往往是先注目于那精彩的画面（这就犹如“烟笼寒水月笼沙”），然后再去看那边角的题字（这便是“夜泊秦淮”）。所以诗人这样写也是颇合人们艺术欣赏的习惯。\n\n　　“夜泊秦淮近酒家”，看似平平，却很值得玩味。这句诗内里的逻辑关系是很强的。由于“夜泊秦淮”才“近酒家”。然而，前四个字又为上一句的景色点出时间、地点，使之更具有个性，更具有典型意义，同时也照应了诗题；后三个字又为下文打开了道路，由于“近酒家”，才引出“商女”、“亡国恨”和“后庭花”，也由此才触动了诗人的情怀。因此，从诗的发展和情感的抒发来看，这“近酒家”三个字，就像启动了闸门，那江河之水便汩汩而出，滔滔不绝。这七个字承上启下，网络全篇，诗人构思的细密、精巧，于此可见。\n\n　　商女，是侍候他人的歌女。她们唱什么是由听者的趣味而定，可见诗说“商女不知亡国恨”，乃是一种曲笔，真正“不知亡国恨”的是那座中的欣赏者——封建贵族、官僚、豪绅。《后庭花》，即《玉树后庭花》，据说是南朝荒淫误国的陈后主所制的乐曲，这靡靡之音，早已使陈朝寿终正寝了。可是，如今又有人在这衰世之年，不以国事为怀，反用这种亡国之音来寻欢作乐，这不禁使诗人产生历史又将重演的隐忧。“隔江”二字，承上“亡国恨”故事而来，指当年隋兵陈师江北，一江之隔的南朝小朝廷危在旦夕，而陈后主依然沉湎声色。“犹唱”二字，微妙而自然地把历史、现实和想象中的未来串成一线，意味深长。“商女不知亡国恨，隔江犹唱《后庭花》”，于婉曲轻利的风调之中，表现出辛辣的讽刺，深沉的悲痛，无限的感慨，堪称“绝唱”。这两句表达了较为清醒的封建知识分子对国事怀抱隐忧的心境，又反映了官僚贵族正以声色歌舞、纸醉金迷的生活来填补他们腐朽而空虚的灵魂，而这正是衰败的晚唐现实生活中两个不同侧面的写照。', poem_tags = '唐诗三百首,初中古诗,咏史怀古,抒怀,爱国,写景,早教古诗100首' WHERE poem_title = '泊秦淮' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '唐宪宗元和十年，我被贬为九江郡司马。第二年秋季的一天，送客到湓浦口，夜里听到船上有人弹琵琶。听那声音，铮铮铿铿有京都流行的声韵。探问这个人，原来是长安的歌女，曾经向穆、曹两位琵琶大师学艺。后来年纪大了，红颜退尽，嫁给商人为妻。于是命人摆酒叫她畅快地弹几曲。她弹完后，有些闷闷不乐的样子，自己说起了少年时欢乐之事，而今漂泊沉沦，形容憔悴，在江湖之间辗转流浪。我离京调外任职两年来，随遇而安，自得其乐，而今被这个人的话所感触，这天夜里才有被降职的感觉。于是撰写一首长诗赠送给她，共六百一十六字，题为《琵琶行》。\n\n秋夜我到浔阳江头送一位归客，冷风吹着枫叶和芦花秋声瑟瑟。\n我和客人下马在船上饯别设宴，举起酒杯要饮却无助兴的音乐。\n酒喝得不痛快更伤心将要分别，临别时夜茫茫江水倒映着明月。\n忽听得江面上传来琵琶清脆声；我忘却了回归客人也不想动身。\n寻着声源探问弹琵琶的是何人？琵琶停了许久却迟迟没有动静。\n我们移船靠近邀请她出来相见；叫下人添酒回灯重新摆起酒宴。\n千呼万唤她才缓缓地走出来，怀里还抱着琵琶半遮着脸面。\n转紧琴轴拨动琴弦试弹了几声；尚未成曲调那形态就非常有情。\n弦弦凄楚悲切声音隐含着沉思；似乎在诉说着她平生的不得志；\n她低着头随手连续地弹个不停；用琴声把心中无限的往事说尽。\n轻轻地拢，慢慢地捻，一会儿抹，一会儿挑。初弹《霓裳羽衣曲》接着再弹《六幺》。\n大弦浑宏悠长嘈嘈如暴风骤雨；小弦和缓幽细切切如有人私语。\n嘈嘈声切切声互为交错地弹奏；就像大珠小珠一串串掉落玉盘。\n琵琶声一会儿像花底下宛转流畅的鸟鸣声，一会儿又像水在冰下流动受阻艰涩低沉、呜咽断续的声音。\n好像水泉冷涩琵琶声开始凝结，凝结而不通畅声音渐渐地中断。\n像另有一种愁思幽恨暗暗滋生；此时闷闷无声却比有声更动人。\n突然间好像银瓶撞破水浆四溅；又好像铁甲骑兵厮杀刀枪齐鸣。\n一曲终了她对准琴弦中心划拨；四弦一声轰鸣好像撕裂了布帛。\n东船西舫人们都静悄悄地聆听；只见江心之中映着白白秋月影。\n她沉吟着收起拨片插在琴弦中；整顿衣裳依然显出庄重的颜容。\n她说我原是京城负有盛名的歌女；老家住在长安城东南的虾蟆陵。\n弹奏琵琶技艺十三岁就已学成；教坊乐团第一队中列有我姓名。\n每曲弹罢都令艺术大师们叹服；每次妆成都被同行歌妓们嫉妒。\n京都豪富子弟争先恐后来献彩；弹完一曲收来的红绡不知其数。\n钿头银篦打节拍常常断裂粉碎；红色罗裙被酒渍染污也不后悔。\n年复一年都在欢笑打闹中度过；秋去春来美好的时光白白消磨。\n兄弟从军姊妹死家道已经破败；暮去朝来我也渐渐地年老色衰。\n门前车马减少光顾者落落稀稀；青春已逝我只得嫁给商人为妻。\n商人重利不重情常常轻易别离；上个月他去浮梁做茶叶的生意。\n他去了留下我在江口孤守空船；秋月与我作伴绕舱的秋水凄寒。\n更深夜阑常梦少年时作乐狂欢；梦中哭醒涕泪纵横污损了粉颜。\n我听琵琶的悲泣早已摇头叹息；又听到她这番诉说更叫我悲凄。\n我们俩同是天涯沦落的可悲人；今日相逢何必问是否曾经相识！\n自从去年我离开繁华长安京城；被贬居住在浔阳江畔常常卧病。\n浔阳这地方荒凉偏僻没有音乐；一年到头听不到管弦的乐器声。\n住在湓江这个低洼潮湿的地方；第宅周围黄芦和苦竹缭绕丛生。\n在这里早晚能听到的是什么呢？尽是杜鹃猿猴那些悲凄的哀鸣。\n春江花朝秋江月夜那样好光景；也无可奈何常常取酒独酌独饮。\n难道这里就没有山歌和村笛吗？只是那音调嘶哑粗涩实在难听。\n今晚我听你弹奏琵琶诉说衷情，就像听到仙乐眼也亮来耳也明。\n请你不要推辞坐下来再弹一曲；我要为你创作一首新诗《琵琶行》。\n被我的话所感动她站立了好久；回身坐下再转紧琴弦拨出急声。\n凄凄切切不再像刚才那种声音；在座的人重听都掩面哭泣不停。\n要问在座之中谁流的眼泪最多？我江州司马泪水湿透青衫衣襟！', poem_notes = '左迁：贬官，降职。古以左为卑，故称“左迁”。\n明年：第二年。\n铮铮：形容金属、玉器等相击声。\n京都声：指唐代京城流行的乐曲声调。\n倡女：歌女。倡，古时歌舞艺人。\n善才：当时对琵琶师或曲师的通称。是“能手”的意思。\n委身：托身，这里指嫁的意思。\n为：做。\n贾（gǔ）人：商人。\n命酒：叫（手下人）摆酒。\n快：畅快。\n悯然：忧郁的样子。\n漂沦：漂泊沦落。\n出官：（京官）外调。\n恬然：淡泊宁静的样子。\n迁谪：贬官降职或流放。\n为：创作。\n长句：指七言诗。\n歌：作歌。\n凡：总共。\n言：字。\n命：命名，题名。\n浔阳江：据考究，为流经浔阳城中的湓水，即今九江市中的龙开河（97年被人工填埋），经湓浦口注入长江。瑟瑟：形容枫树、 芦荻被秋风吹动的声音。\n瑟瑟：形容枫树、芦荻被秋风吹动的声音。\n主人：诗人自指。\n回灯：重新拨亮灯光。回：再。\n转轴拨弦：将琵琶上缠绕丝弦的轴，以调音定调。\n掩抑：掩蔽，遏抑。\n思：悲，伤。\n信手：随手。\n续续弹：连续弹奏。\n拢：左手手指按弦向里（琵琶的中部）推。\n捻：揉弦的动作。\n抹：向左拔弦，也称为“弹”。\n挑：反手回拨的动作。\n《霓裳》：即《霓裳羽衣曲》，本为西域乐舞，唐开元年间西凉节度使杨敬述依曲创声后流入中原。\n《六幺》：大曲名，又叫《乐世》《绿腰》《录要》，为歌舞曲。\n大弦：指最粗的弦。\n嘈嘈：声音沉重抑扬。\n小弦：指最细的弦。\n切切：细促轻幽，急切细碎。\n间关：莺语流滑叫“间关”。鸟鸣声。\n幽咽：遏塞不畅状。\n冰下难：泉流冰下阻塞难通，形容乐声由流畅变为冷涩。\n凝绝：凝滞。\n迸：溅射。\n曲终：乐曲结束。\n拔：弹奏弦乐时所用的拔工具。\n当心画：用拔子在琵琶的中部划过四弦，是一曲结束时经常用到的右手手法。\n舫：船。\n敛容：收敛（深思时悲愤深怨的）面部表情。\n虾（há）蟆陵：在长安城东南，曲江附近，是当时有名的游乐地区。\n教坊：唐代官办管领音乐杂技、教练歌舞的机关。\n秋娘：唐时歌舞妓常用的名字。\n五陵：在长安城外，汉代五个皇帝的陵墓。\n缠头：用锦帛之类的财物送给歌舞妓女。\n绡：精细轻美的丝织品。\n钿（diàn）头银篦（bì）：此指镶嵌着花钿的篦形发饰。\n击节：打拍子。\n颜色故：容貌衰老。\n浮梁：古县名，唐属饶州。在今江西省景德镇市，盛产茶叶。\n去来：走了以后。\n梦啼妆泪：梦中啼哭，匀过脂粉的脸上带着泪痕。\n阑干：纵横散乱的样子。\n重：重新，重又之意。\n唧唧：叹声。\n呕哑嘲哳：形容声音噪杂。\n琵琶语：琵琶声，琵琶所弹奏的乐曲。\n暂：突然。\n却坐：退回到原处。\n促弦：把弦拧得更紧。\n向前声：刚才奏过的单调。\n掩泣：掩面哭泣。\n青衫：唐朝八品、九品文官的服色。白居易当时的官阶是将侍郎，从九品，所以服青衫。', poem_appreciation = '宋人洪迈认为夜遇琵琶女事未必可信，作者是通过虚构的情节，抒发他自己的“天涯沦落之恨”（《容斋随笔》卷七），这是抓住了要害的。但那虚构的情节既然真实地反映了琵琶女的不幸遭遇，那么就诗的客观意义说，它也抒发了“长安故倡”的“天涯沦落之恨”。看不到这一点，同样有片面性。\n\n　　诗人着力塑造了琵琶女的形象。\n\n　　从开头到“犹抱琵琶半遮面”，写琵琶女的出场。\n\n　　首句“浔阳江头夜送客”，只七个字，就把人物（主人和客人）、地点（浔阳江头）、事件（主人送客人）和时间（夜晚）一一作概括的介绍；再用“枫叶荻花秋瑟瑟”一句作环境的烘染，而秋夜送客的萧瑟落寞之感，已曲曲传出。惟其萧瑟落寞，因而反跌出“举酒欲饮无管弦”。“无管弦”三字，既与后面的“终岁不闻丝竹声”相呼应，又为琵琶女的出场和弹奏作铺垫。因“无管弦”而“醉不成欢惨将别”，铺垫已十分有力，再用“别时茫茫江浸月”作进一层的环境烘染，就使得“忽闻水上琵琶声”具有浓烈的空谷足音之感，无怪乎“主人忘归客不发”，要“寻声暗问弹者谁”“移船相近邀相见”了。\n\n　　从“夜送客”之时的“秋萧瑟”“无管弦”“惨将别”一转而为“忽闻”“寻声”“暗问”“移船”，直到“邀相见”，这对于琵琶女的出场来说，已可以说是“千呼万唤”了。但“邀相见”还不那么容易，又要经历一个“千呼万唤”的过程，她才肯“出来”。这并不是她在意身份。正象“我”渴望听仙乐一般的琵琶声，是“直欲摅写天涯沦落之恨”一样，她“千呼万唤始出来”，也是由于有一肚子“天涯沦落之恨”，不便明说，也不愿见人。诗人正是抓住这一点，用“琵琶声停欲语迟”“犹抱琵琶半遮面”的肖像描写来表现她的难言之痛的。\n\n　　下面的一大段，通过描写琵琶女弹奏的乐曲来揭示她的内心世界。\n\n　　先用“转轴拨弦三两声”一句写校弦试音，接着就赞叹“未成曲调先有情”，突出了一个“情”字。“弦弦掩抑声声思”以下六句，总写“初为《霓裳》后《六幺》”的弹奏过程，其中既用“低眉信手续续弹”“轻拢慢捻抹复挑”描写弹奏的神态，更用“似诉平生不得志”“说尽心中无限事”概括了琵琶女借乐曲所抒发的思想情感。此后十四句，在借助语言的音韵摹写音乐的时候，兼用各种生动的比喻以加强其形象性。“大弦嘈嘈如急雨”，既用“嘈嘈”这个叠字词摹声，又用“如急雨”使它形象化。“小弦切切如私语”亦然。这还不够，“嘈嘈切切错杂弹”，已经再现了“如急雨”“如私语”两种旋律的交错出现，再用“大珠小珠落玉盘”一比，视觉形象与听觉形象就同时显露出来，令人眼花缭乱，耳不暇接。旋律继续变化，出现了先“滑”后“涩”的两种意境。“间关”之声，轻快流利，而这种声音又好象“莺语花底”，视觉形象的优美强化了听觉形象的优美。“幽咽”之声，悲抑哽塞，而这种声音又好象“泉流冰下”，视觉形象的冷涩强化了听觉形象的冷涩。由“冷涩”到“凝绝”，是一个“声渐歇”的过程，诗人用“别有幽愁暗恨生，此时无声胜有声”的佳句描绘了余音袅袅、余意无穷的艺术境界，令人拍案叫绝。弹奏至此，满以为已经结束了。谁知那“幽愁暗恨”在“声渐歇”的过程中积聚了无穷的力量，无法压抑，终于如“银瓶乍破”，水浆奔迸，如“铁骑突出”，刀枪轰鸣，把“凝绝”的暗流突然推向高潮。才到高潮，即收拨一画，戛然而止。一曲虽终，而回肠荡气、惊心动魄的音乐魅力，却并没有消失。诗人又用“东船西舫悄无言，唯见江心秋月白”的环境描写作侧面烘托，给读者留下了涵泳回味的广阔空间。\n\n　　如此绘声绘色地再现千变万化的音乐形象，已不能不使我们惊佩作者的艺术才华。但作者的才华还不仅表现在再现音乐形象，更重要的是通过音乐形象的千变万化，展现了琵琶女起伏回荡的心潮，为下面的诉说身世作了音乐性的渲染。\n\n　　正象在“邀相见”之后，省掉了请弹琵琶的细节一样；在曲终之后，也略去了关于身世的询问，而用两个描写肖像的句子向“自言”过渡：“沉吟”的神态，显然与询问有关，这反映了她欲说还休的内心矛盾；“放拨”“插弦中”，“整顿衣裳”“起”“敛容”等一系列动作和表情，则表现了她克服矛盾、一吐为快的心理活动。“自言”以下，用如怨如慕、如泣如诉的抒情笔调，为琵琶女的半生遭遇谱写了一曲扣人心弦的悲歌，与“说尽心中无限事”的乐曲互相补充，完成了女主人公的形象塑造。\n\n　　女主人公的形象塑造得异常生动真实，并具有高度的典型性。通过这个形象，深刻地反映了封建社会中被侮辱、被损害的乐伎们、艺人们的悲惨命运。面对这个形象，怎能不一洒同情之泪！\n\n　　作者在被琵琶女的命运激起的情感波涛中坦露了自我形象。“我从去年辞帝京，谪居卧病浔阳城”的那个“我”，是作者自己。作者由于要求革除暴政、实行仁政而遭受打击，从长安贬到九江，心情很痛苦。当琵琶女第一次弹出哀怨的乐曲、表达心事的时候，就已经拨动了他的心弦，发出了深长的叹息声。当琵琶女自诉身世、讲到“夜深忽梦少年事，梦啼妆泪红阑干”的时候，就更激起他的情感的共鸣：“同是天涯沦落人，相逢何必曾相识”。同病相怜，同声相应，忍不住说出了自己的遭遇。\n\n　　写琵琶女自诉身世，详昔而略今；写自己的遭遇，则压根儿不提被贬以前的事。这也许是意味着以彼之详，补此之略吧！比方说，琵琶女昔日在京城里“曲罢常教善才伏，妆成每被秋娘妒”的情况和作者被贬以前的情况是不是有某些相通之处呢？同样，他被贬以后的处境和琵琶女“老大嫁作商人妇”以后的处境是不是也有某些类似之处呢？看来是有的，要不然，怎么会发出“同是天涯沦落人”的感慨？', poem_tags = '唐诗三百首,高中古诗,乐府,写人,愤懑' WHERE poem_title = '琵琶行 / 琵琶引' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '陈太丘和朋友相约同行，约定的时间在中午，过了中午朋友还没有到，陈太丘不再等候他而离开了，陈太丘离开后朋友才到。元方当时年龄七岁，在门外玩耍。陈太丘的朋友问元方：“你的父亲在吗？”元方回答道：“我父亲等了您很久您却还没有到，已经离开了。”友人便生气地说道：“真不是人啊！和别人相约同行，却丢下别人先离开了。”元方说：“您与我父亲约在正午，正午您没到，就是不讲信用；对着孩子骂父亲，就是没有礼貌。”朋友感到惭愧，下了车想去拉元方的手，元方头也不回地走进家门。', poem_notes = '元方: 即陈纪，字元方，陈寔的长子。\n陈太丘: 陈寔（shí），字仲弓，东汉颍川许（现在河南许昌）人，做过太丘县令。太丘：古地名。\n期行: 相约同行。期，约定。\n期日中: 约定的时间是正午。日中，正午时分。\n过中：过了正午。\n舍去：不再等候就走了。去，离开。舍：舍弃，抛弃。\n乃至:（友人）才到。乃，才。\n戏：嬉戏。\n尊君在不(fǒu)：你父亲在吗？尊君，对别人父亲的一种尊称。不，通“否”\n家君：谦词，对人称自己的父亲。\n引：拉，要和元方握手\n信：诚信，讲信用。\n时年：今年。\n非：不是。\n相委而去：丢下我走了；相 偏指一方对另一方的行为，代词，通“之”，我；委，丢下，舍弃。\n君：对对方父亲的一种尊称。\n已去：已经 离开。\n曰：说。\n则：就是。\n顾：回头看。\n惭：感到惭愧。\n\n古今异义词\n1.去 古意：离开 ；今意：往、到。\n2.委 古意：丢下、舍弃 ； 今意：委屈、委托。\n3.顾 古意：回头看 ；今意：照顾\n4儿女 古意：子侄辈 今意：儿子女儿', poem_appreciation = '《陈太丘与友期》全文仅有103个字，却叙述了一个完整的故事（关于守信与不守信的一场辩论），刻画了三个有鲜明个性的人物，说明了为人处世，应该讲礼守信的道理。如此有限的文字，却包含了这样丰富的内容，真可谓言简意赅了。如果不是在语言的精炼上造诣高深，要做到这一点是很难的。\n\n　　《陈太丘与友期》的精炼语言，体现在文章的始终。一开头，文章以“期行”、“期日中”、“不至”、“舍去” 、“乃至” 等几个关键词语，把事情、时间、起因交代得清清楚楚，而且，在这些交代中，还把两个不同的人物形象（一个守信，一个不守信）一下子推到了读者面前。\n\n　　文章的结尾，虽只客寥数语，但却字字生辉。“惭”、“下“、“引”三个动词，把友人知错欲改的心态及行为刻画得入木三分。对元方鄙弃“无信”的那股倔强劲儿，也用“人门，不顾”四个字，描绘得维妙维肖。就在最能体现文章中心思想的第二层 （子斥友人）中，尽管作者用了比开头和结尾要多得多的笔墨，但文字仍然十分精炼。单就叙述的句子来说，在叙述友人问元方时，由“问”到“怒”，感情急剧变化，充分表现了友人那粗鲁无礼的性格。而在叙述元方批驳友人的怒斥时，则选用语气平和的“答曰”、“曰”这类词，这对表现元方不惧怕友人的怒斥、知书达理、善于应对的性格，起到了绝好的作用。\n\n　　《陈太丘与友期》的主题思想，主要是通过人物的对话来揭示的。这些人物对话，虽然只有三言两语，但句句都紧扣文章中心，紧扣人物性格，具有鲜明的个性特征。文章写友人与元方的对话有三句。第一句“尊君在不？”开门见山，问得直截了当，毫无谦恭之意，初露性格的鲁莽。第二句“非人哉！”出言不逊，当着儿子骂父亲，这是不讲礼仪的行为，再露性格的粗鲁。第三句“与人期行，相委而去！”看似有理，实则无理。不自责自己失约误期的错误，反而委过于人，怒斥对方如约而行的正确做法，这就更加暴露出友人不讲道理的性格特征。\n\n　　文章写元方与友人的对话也有三句。第一句“待君久，不至，已去。”这是针对友人的间话而答的。元方不是正面回答友人提出的问题，在，还是不在。而是先说“等君久”“不至”，再说“已去”，把父亲的 “去”与“等君久”和友人的“不至”联系起来。这样的回答，不仅把父亲为什么走说清楚了，为后面批驳友人的怒斥作了准备，而且话中有话，流露出对友人失约的反感。第二、三两句是对友人无理怒斥的反驳。第二句“君与家君期日中，日中不至，则是无信。”这是针对友人强调“期行”而说的。守信还是失信，关键在于“期日中”，“日中不至”，当然就是失信了。抓住实质，击中要害，\n\n　　使友人失去辫驳的根据。第三句“对子骂父，则是无礼。”这是针对友人出言不逊而说的。在指出友人“无信”的基础上，又指出友人“无礼”。一步紧逼一步，把友人通到了无以言对的狼狈境地，以至最后不得不“惭”而“下车引之”。由于这些对话具有鲜明的个性特征，因此，虽然只有短短几句，也可以看出元方—陈太丘性格的折光，是多么聪颖仁慧、知书达理。\n\n　　《陈太丘与友期》一文细节微言、涵泳无穷。“陈太丘与友期行，期日中，过中不至，太丘舍去，去后乃至。”尺寸之间起波澜，与下文问答中“待君久不至，已去”“君与家君期日中，日中不至 ”呼应。友人“问”“便怒”“惭”“下车引之”，一波三折。其间，先称 “尊君”，骤然口不择言 “非人哉”，人物情态，栩栩如生。元方“门外戏”、一答一日、“入门不顾”，应对自如，宛若成人，表现出鲜明个性与独立人格。不论是情节上的起伏变化，还是人物情态上的自然生动，乃至文字之下隐藏着的本真性情、坦率品质，都值得我们琢磨品味。', poem_tags = '初中文言文,诚信,哲理,故事' WHERE poem_title = '陈太丘与友期 / 期行' AND poem_author = '刘义庆';
UPDATE edu_poem SET poem_translation = '春天将尽，百花凋零，杏树上已经长出了青涩的果实。燕子飞过天空，清澈的河流围绕着村落人家。柳枝上的柳絮已被吹得越来越少，怛不要担心，到处都可见茂盛的芳草。\n围墙里面，有一位少女正在荡秋千，少女发出动听的笑声，墙外的行人都可听见。慢慢地，围墙里边的笑声就听不见了，行人惘然若失，仿佛多情的自己被无情的少女所伤害。', poem_notes = '“蝶恋花·春景”，原本无题，傅本存目缺词。\n“花褪残红”：褪，脱去，小：毛本作“子”。\n“子”，毛本误作“小”。“飞”，《二妙集》、毛本注“一作来。”\n“绕”，元本注“一作晓。”\n“柳绵”：即柳絮。\n“何处无芳草”句：谓春光已晚，芳草长遍天涯。\n多情：这里代指墙外的行人。无情：这里代指墙内的佳人。', poem_appreciation = '本词是伤春之作。苏轼长于豪放。亦最擅婉约，本词写春景清新秀丽。同时，景中又有情理，我们仍用“何处无芳草（知音）”以自慰自勉。作者的“多情却被无情恼”，也不仅仅局限于对“佳人”的相思。本词下片所写的是一个爱情故事的片段，未必有什么寄托。只是一首很好的婉约词。王士祯所说的“枝上柳绵，恐屯田缘情绮靡。未必能过。”《花草蒙拾》指出本词与风格婉约的柳永词不相上下。\n\n　　“花褪残红青杏小。”褪对旨颜色变浅或消失。开头一句描写的是暮春景象，句意为：暮春时节，杏花凋零枯萎，枝头只挂着又小又青的杏子。作者的视线是从一棵杏树开始的：花儿已经凋谢，所余不多的红色也正在一点一点褪去，树枝上开始结出了幼小的青杏。“残红”，他特别注意到初生的“青杏”，语气中透出怜惜和喜爱，有意识地冲淡了先前浓郁的伤感之情。“燕子飞时，绿水人家绕。”燕子在空中飞来飞去，绿水环绕着一户人家。这两句又描绘了一幅美丽而生动的春天画面，但缺少了花树的点缀，仍显美中不足。“绕”字，曾有人以为应是“晓”。通读全词，并没有突出的景物表明这是清晨的景色，因而显得没有着落。而燕子绕舍而飞，绿水绕舍而流，行人绕舍而走，着一“绕”字，则非常真切。“枝上柳棉吹又少，天涯何处无芳草？”。两句大意是：树上的柳絮在风的吹拂下越来越少，春天行将结束，难道天下之大，竞找不到一处怡人的景色吗？柳絮纷飞，春色将尽，固然让人伤感；而芳草青绿，又自是一番境界。苏轼的旷达于此可见。“天涯”一句，语本屈原《离骚》“何所独无芳草兮，尔何怀乎故宇”，是卜者灵氛劝屈原的话，其思想与苏轼在《定风波》中所说的“此心安处是吾乡”一致。最后竟被远谪到万里之遥的岭南。此时，他已人到晚年，遥望故乡，几近天涯。这境遇和随风飘飞的柳絮何其相似。\n\n　　上阕描写了一组暮春景色，虽也有些许亮色，但由于缺少了花草，他感到更多的是衰败和萧索，这正如作者此时的心境。作者被贬谪在外，仕途失意又远离家人，所以他感到孤独惆怅，想寻找一些美好的景物来排解心中的郁闷，谁知佳景难觅，心情更糟。上阕表达了作者的惜春之情及对美好事物的追求。\n\n　　“墙里秋千墙外道。墙外行人，墙里佳人笑。”墙外是一条道路，行人从路中经过，只听见墙里有荡秋千的声音，一阵阵悦耳的笑声不时从里面传出，原来是名女子在荡秋千。这一场景顿扫上阕之萧索，充满了青春的欢快旋律，使行人禁不住止步，用心地欣赏和聆听着这令人如痴如醉的欢声笑语。作者在艺术处理上十分讲究藏与露的关系。这里，他只写露出墙头的秋千和佳人的笑声，其它则全部隐藏起来，让“行人”去想象，在想象中产生无穷意味。小词最忌词语重复，但这三句总共十六字，“墙里”、“墙外”分别重复，竟占去一半。而读来错落有致，耐人寻味。墙内是家，墙外是路；墙内有欢快的生活，年轻而富有朝气的生命；墙外是赶路的行人。行人的心情和神态如何，作者留下了空白。不过，在这无语之中，让人感受到一种冷落寂寞。“笑渐不闻声渐悄，多情却被无情恼。”也许是行人伫立良久，墙内佳人已经回到房间；也许是佳人玩乐依旧，而行人已渐渐走远。总之，佳人的笑声渐渐听不到了，四周显得静悄悄。但是行人的心却怎么也平静不下来。墙院里女子的笑声渐渐地消失了，而墙外的行人听到笑声后却心绪难平。他听到女子甜美的笑声，却一直无法看到女子的模样；心情起伏跌宕不已，而女子也并不知道墙外有个男子正为她苦恼。男子多情，女子无情。这里的“多情”与“无情”常被当爱情来解释，有感怀身世之情，有思乡之情，有对年轻生命的向往之情，有报国之情，等等，的确可谓是“有情”之人；而佳人年轻单纯、无忧无虑，既没有伤春感时，也没有为人生际遇而烦恼，真可以说是“无情”。作者发出如此深长的感慨，那“无情”之人究竟会撩拨起他什么样的思绪呢？也许是勾起他对美好年华的向往，也许是对君臣关系的类比和联想，也许倍增华年不再的感慨，也许是对人生哲理的一种思索和领悟，作者并未言明，却留下了丰富的空白，让人回味、想象。\n\n　　下阕写人，描述了墙外行人对墙内佳人的眷顾及佳人的淡漠，让行人更加惆怅。在这里，“佳人”即代表上阕作者所追求的“芳草”，“行人”则是词人的化身。词人通过这样一组意象的刻画，表现了其抑郁终不得排解的心绪。\n\n　　综观全词，词人写了春天的景，春天的人，而后者也可以算是一种特殊的景观。词人意欲奋发有为，但终究未能如愿。全词真实地反映了词人的一段心理历程，意境朦胧，令人回味无穷。', poem_tags = '宋词三百首,婉约,写景,伤春' WHERE poem_title = '蝶恋花·春景' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '敌兵滚滚而来，犹如黑云翻卷，想要摧倒城墙；我军严待以来，阳光照耀铠甲，一片金光闪烁。\n秋色里，响亮军号震天动地；黑夜间战士鲜血凝成暗紫。\n红旗半卷，援军赶赴易水；夜寒霜重，鼓声郁闷低沉。\n只为报答君王恩遇，手携宝剑，视死如归。', poem_notes = '雁门太守行：古乐府曲调名。雁门，郡名。古雁门郡大约在今山西省西北部，是唐王朝与北方突厥部族的边境地带。\n黑云：此形容战争烟尘铺天盖地，弥漫在边城附近，气氛十分紧张。摧：毁。甲光：指铠甲迎着太阳发出的闪光。金鳞：是说像金色的鱼鳞。这句形容敌军兵临城下的紧张气氛和危急形势。\n甲光：铠甲迎着太阳闪出的光。甲，指铠甲，战衣。向日：迎着太阳。亦有版本写作“向月”。向：向着，对着。金鳞开：（铠甲）像金色的鱼鳞一样闪闪发光。金：像金子一样的颜色和光泽。开：打开，铺开。\n角：古代军中一种吹奏乐器，多用兽角制成，也是古代军中的号角。\n塞上燕脂凝夜紫：燕脂，即胭脂，这里指暮色中塞上泥土有如胭脂凝成。凝夜紫，在暮色中呈现出暗紫色。凝，凝聚。“燕脂”、“夜紫”暗指战场血迹。\n临：逼近，到，临近。易水：河名，大清河上源支流，源出今河北省易县，向东南流入大清河。易水距塞上尚远，此借荆轲故事以言悲壮之意。不起：是说鼓声低沉不扬。\n霜重鼓寒：天寒霜降，战鼓声沉闷而不响亮。声不起：形容鼓声低沉；不响亮。此句一作“霜重鼓声寒不起”。\n报：报答。黄金台：故址在今河北省易县东南，相传战国燕昭王所筑。意：信任，重用。\n玉龙：宝剑的代称。君：君王。', poem_appreciation = '李贺的不少诗向称难解，这一首解者纷纭，却莫衷一是。对于诗意的理解也异常分歧。\n\n　　这首短诗，后面写兵临易水、提剑誓死？其主题确与战斗有关。但前四句　着重写景，除“甲花”、“角声”表明此处有兵士而外，围城、突围等等全无　明确描写。因此，解说之分歧，多出于对“言外之意”的不同体会。“言”外　之“意”虽在“言”外，仍然来自“言”。一首诗积字成句，积句成篇，成为　有内在联系的整体。这篇诗前四句颇难碓解，后四句却比较显豁。说清后四句，　再反观前四句，通篇的意义便不难领会。\n\n　　先看后四句。“半卷红旗临易水”，暗示“临易水”之前有一段进军过程。“半卷红旗” 是为减少阻力，是进军的特征，如“红旗半卷出辕门” 之类。“临”字也表现行军的动势。那么，“临易水”之后是否遇上敌军？如果遇到的话，力量对比如何？形势对谁有利？这一切，后三句都未作正面描述，而言外之意却比较明晰：一、“临易水”表明前进受阻，又令人联想起《易水歌》：“风萧萧兮易水寒，壮士一去兮不复还。”二、击鼓为了进军，而“霜重鼓寒声不起”通过自然条件的不利暗示出战争形势的严峻。三、末尾两句，写主将提剑上阵，誓作殊死战斗以报君恩，则大敌当前，已不言可知。\n\n　　首句于“云”上着“黑”字，已感气氛沉重。而这“黑云”又“压城”以至压得“城欲摧”，明显有象征意义。“云”上特加“黑”字，自然不会用以象征我军而是象征敌军。敌军压境围城如此凶猛，则我军只有杀出重围，才有生路。“甲光向日金鳞开”，在色彩和形相上与上句形成强烈对比，明含欣喜、赞美之情，当然是指我军。始而黑云压城，适度围逼，既而黑云崩溃、红日当空，我军将士的金甲在日光下犹如片片金鳞，耀人眼目。就是说己经杀出孤城，击败敌兵。\n\n　　一、二两句写围城与突围，构成一个意义单位。以下八句写乘胜追杀，直至兵临易水，是又一个意义单位。“角”，古代军用乐器。《北史·齐安德王延宗传》有“吹角收兵”的记载。联系上下文看，“角声满天秋色里”一句，正是以虚写实。在读者想象中展现敌退我追的壮阔场景。“塞上胭脂凝夜紫”中的“夜”字照应第一句中的“日”字，表明从突围至此，已过了较长一段时间，双方互有杀伤。“塞上胭脂”，旧注引《古今注》“秦筑长城，土色皆紫、故曰紫塞”解释，大致不错。紧承“角声”、“秋色”描绘塞土赤紫，已令人想见战血；于“紫”前加一“凝”字，更强化了这种联想。\n\n　　由“日”到“夜”，以至夜深“霜重”，追兵已临易水，敌军自然先到易水。追兵尾随，敌军倘要渡水，便可能全军覆役，因而只能背水一战。“陷之死地而后生”，想到韩信的背水阵，就知道追兵面临的形势何等严峻！鼓声不起，主将誓死，正是这种严峻形势的反映。至于快战的结果如何，却让读者去想象。诗人运用特殊的艺术手法表现独特的艺术想象，或用象征，或用暗示，或用烘托，或以虚见实、以声显形、以部分代全体，给读者留下了过于广阔的想象空间，所以读者的理解因人而异。\n\n　　意象新奇，设色鲜明，造型新颖，想象丰富而奇特，这是李贺诗歌的突出特点。在《雁门太守行》里，这些特点得到了全面而充分的体现。仅以后两句为例，看看他如何注意设色和造型。这两句写主将为报君主的知遇之恩，誓死决战，却不用概念化语言，而通过造型、设色、突出主将的外在形象和内心活动。战国时燕昭王曾筑台置千金于其上以延揽人才，因称此台为“黄金台”。“玉龙”，唐人用以称剑。 黄金、 白玉， 其质地和色泽， 都为世人所重。“龙”，是古代传说中的高贵动物，“黄金台”，是求贤若渴的象征。诗人选用“玉龙”和“黄金台”造型设色，创造出“报君黄金台上意，提携玉龙为君死”的诗句，一位神采奕奕的主将形象便宛然在目。其不惜为国捐躯的崇高精神，以及君主重用贤才的美德，都给读者以强烈而美好的感受。', poem_tags = '初中古诗,乐府,拟古,边塞,战争' WHERE poem_title = '雁门太守行' AND poem_author = '李贺';
UPDATE edu_poem SET poem_translation = '君子的行为操守，从宁静来提高自身的修养，以节俭来培养自己的品德。不恬静寡欲无法明确志向，不排除外来干扰无法达到远大目标。学习必须静心专一，而才干来自学习。所以不学习就无法增长才干，没有志向就无法使学习有所成就。放纵懒散就无法振奋精神，急躁冒险就不能陶冶性情。年华随时光而飞驰，意志随岁月而流逝。最终枯败零落，大多不接触世事、不为社会所用，只能悲哀地坐守着那穷困的居舍，其时悔恨又怎么来得及？', poem_notes = '诫：警告，劝人警惕。\n夫（fú）：段首或句首发语词，引出下文的议论，无实在的意义。君子：品德高尚的人。指操守、品德、品行。\n修身：个人的品德修养。\n养德：培养品德。\n澹（dàn）泊：也写做“淡泊”，清静而不贪图功名利禄。内心恬淡，不慕名利。清心寡欲。明志：表明自己崇高的志向。\n宁静：这里指安静，集中精神，不分散精力。致远：实现远大目标。\n才：才干。\n广才：增长才干。\n成：达成，成就。\n慆（tāo）慢：漫不经心。慢：懈怠，懒惰。励精：尽心，专心，奋勉，振奋。\n险躁：冒险急躁，狭隘浮躁，与上文“宁静”相对而言。冶性：陶冶性情。\n与：跟随。驰：疾行，这里是增长的意思。\n日：时间。去：消逝，逝去。\n遂：于是，就。枯落：枯枝和落叶，此指像枯叶一样飘零，形容人韶华逝去。\n多不接世：意思是对社会没有任何贡献。接世，接触社会，承担事务，对社会有益。有“用世”的意思。\n穷庐：破房子。\n将复何及：又怎么来得及。\n淫慢：过度的享乐，懈怠。淫：过度。', poem_appreciation = '古代家训，大都浓缩了作者毕生的生活经历、人生体验和学术思想等方面内容，不仅他的子孙从中获益颇多，就是今人读来也大有可借鉴之处。三国时蜀汉丞相诸葛亮被后人誉为“智慧之化身”，他的《诫子书》也可谓是一篇充满智慧之语的家训，是古代家训中的名作。文章阐述修身养性、治学做人的深刻道理，读来发人深省。它也可以看作是诸葛亮对其一生的总结，后来更成为修身立志的名篇。\n\n　　《诫子书》的主旨是劝勉儿子勤学立志，修身养性要从淡泊宁静中下功夫，最忌怠惰险躁。文章概括了做人治学的经验，着重围绕一个“静”字加以论述，同时把失败归结为一个“躁”字，对比鲜明。\n\n　　在《诫子书》中，诸葛亮教育儿子，要“澹泊”自守，“宁静”自处，鼓励儿子勤学励志，从澹泊和宁静的自身修养上狠下功夫。他说，“夫学须静也，才须学也，非学无以广才，非志无以成学”。意思是说，不安定清静就不能为实现远大理想而长期刻苦学习，要学得真知必须使身心在宁静中研究探讨，人们的才能是从不断的学习中积累起来的；不下苦功学习就不能增长与发扬自己的才干；没有坚定不移的意志就不能使学业成功。《诸葛亮教育儿子切忌心浮气躁，举止荒唐。在书信的后半部分，他则以慈父的口吻谆谆教导儿子：少壮不努力，老大徒伤悲。这话看起来不过是老生常谈罢了，但它是慈父教诲儿子的，字字句句是心中真话，是他人生的总结，因而格外令人珍惜。\n\n　　这篇《诫子书》，不但讲明修身养性的途径和方法，也指明了立志与学习的关系；不但讲明了宁静淡泊的重要，也指明了放纵怠慢、偏激急躁的危害。诸葛亮不但在大的原则方面对其子严格要求，循循善诱，甚至在一些具体事情上也体现出对子女的细微关怀。在这篇《诫子书》中，有宁静的力量：“静以修身”，“非宁静无以致远”；有节俭的力量：“俭以养德”；有超脱的力量：“非澹泊无以明志”；有好学的力量：“夫学须静也，才须学也”；有励志的力量：“非学无以广才，非志无以成学”；有速度的力量：“淫慢则不能励精”；有性格的力量：“险躁则不能治性”；有惜时的力量：“年与时驰，意与岁去”；有想象的力量：“遂成枯落，多不接世，悲守穷庐，将复何及”；有简约的力量。这篇文章短短几十字，传递出的讯息，比起长篇大论，诫子效果好得多。\n\n　　文章短小精悍，言简意赅，文字清新雅致，不事雕琢，说理平易近人，这些都是这篇文章的特出之处。', poem_tags = '修身,立志' WHERE poem_title = '诫子书' AND poem_author = '诸葛亮';
UPDATE edu_poem SET poem_translation = '江南的风景多么美好，如画的风景久已熟悉。春天到来时，太阳从江面升起，把江边的鲜花照得比火红，碧绿的江水绿得胜过蓝草。怎能叫人不怀念江南？\n\n江南的回忆，最能唤起追思的是像天堂一样的杭州：游玩灵隐寺寻找皎洁月亮中的桂子，登上郡亭，枕卧其上，欣赏那起落的钱塘江大潮。什么时候能够再次去游玩？\n\n江南的回忆，再来就是回忆苏州的吴宫，喝一喝吴宫的美酒春竹叶，看一看吴宫的歌女双双起舞像朵朵迷人的芙蓉。不知何时会再次相逢。', poem_notes = '忆江南：唐教坊曲名。作者题下自注说：“此曲亦名‘谢秋娘’，每首五句。”按《乐府诗集》：“‘忆江南’一名‘望江南’，因白氏词，后遂改名‘江南好’。”至晚唐、五代成为词牌名。这里所指的江南主要是长江下游的江浙一带。\n谙（ān）：熟悉。作者年轻时曾三次到过江南。\n江花：江边的花朵。一说指江中的浪花。红胜火：颜色鲜红胜过火焰。\n绿如蓝：绿得比蓝还要绿。如，用法犹“于”，有胜过的意思。蓝，蓝草，其叶可制青绿染料。\n桂子：桂花。宋柳永《望海潮·东南形胜》词：“有三秋桂子，十里荷花。”\n郡亭：疑指杭州城东楼。看潮头：钱塘江入海处，有二山南北对峙如门，水被夹束，势极凶猛，为天下名胜。\n吴宫：指吴王夫差为西施所建的馆娃宫，在苏州西南灵岩山上。\n竹叶：酒名。即竹叶青。亦泛指美酒。\n吴娃：原为吴地美女名。此词泛指吴地美女。醉芙蓉：形容舞伎之美。\n早晚：犹言何日，几时。', poem_appreciation = '第一首泛忆江南，兼包苏、杭，写春景。全词五句。一开口即赞颂“江南好！”正因为“好”，才不能不“忆”。“风景旧曾谙”一句，说明那江南风景之“好”不是听人说的，而是当年亲身感受到的、体验过的，因而在自己的审美意识里留下了难忘的记忆。既落实了“好”字，又点明了“忆”字。接下去，即用两句词写他“旧曾谙”的江南风景：“日出江花红胜火，春来江水绿如蓝。”“日出”、“春来”，互文见义。春来百花盛开，已极红艳；红日普照，更红得耀眼。在这里，因同色相烘染而提高了色彩的明亮度。春江水绿，红艳艳的阳光洒满了江岸，更显得绿波粼粼。在这里，因异色相映衬而加强了色彩的鲜明性。作者把“花”和“日”联系起来，为的是同色烘染；又把“花”和“江”联系起来，为的是异色相映衬。江花红，江水绿，二者互为背景。于是红者更红，“红胜火”；绿者更绿，“绿如蓝”。\n\n　　杜甫写景，善于着色。如“江碧鸟逾白，山青花欲燃”（《绝句》）、“两个黄鹂鸣翠柳，一行白鹭上青天”诸句，都明丽如画。而异色相映衬的手法，显然起了重要作用。白居易似乎有意学习，如“夕照红于烧，晴空碧胜蓝”（《秋思》）、“春草绿时连梦泽，夕波红处近长安”（《题岳阳楼》）、“绿浪东西南北水，红栏三百九十桥”（《正月三日闲行》）诸联，都因映衬手法的运用而获得了色彩鲜明的效果。至于“日出”、“春来”两句，更在师承前人的基础上有所创新：在明媚的春光里，从初日、江花、江水、火焰、蓝叶那里吸取颜料，兼用烘染、映衬手法而交替综错，又济之以贴切的比喻，从而构成了阔大的图景。不仅色彩绚丽，耀人眼目；而且层次丰富，耐人联想。\n\n　　题中的“忆”字和词中的“旧曾谙”三字还说明了此词还有一个更重要的层次：以北方春景映衬江南春景。全词以追忆的情怀，写“旧曾谙”的江南春景。而此时，作者却在洛阳。比起江南来，洛阳的春天来得晚。作者写于洛阳的《魏王堤》七绝云：“花寒懒发鸟慵啼，信马闲行到日西。何处未春先有思，柳条无力魏王堤。”在江南“日出江花红胜火”的季节，洛阳却“花寒懒发”，只有魏王堤上的柳丝，才透出一点儿春意。\n\n　　花发得比江南晚，水也有区别。洛阳有洛水、伊水，离黄河也不远。但即使春天已经来临，这些水也不可能像江南春水那样碧绿。因此作者竭力追忆江南春景，从内心深处赞叹“江南好”，而在用生花妙笔写出他“旧曾谙”的江南好景之后，又不禁以“能不忆江南”的眷恋之情，收束全词。这个收束既托出身在洛阳的作者对江南春色的无限赞叹与怀念，又造成一种悠远而又深长的韵味。词虽收束，而余情摇漾，凌空远去，自然引出第二首和第三首。\n\n　　第二首词以“江南忆，最忆是杭州”领起，前三字“江南忆”和第一首词的最后三字“忆江南”勾连，形成词意的连续性。后五字“最忆是杭州”又突出了作者最喜爱的一个江南城市。如果说第一首词像画家从鸟瞰的角度大笔挥洒而成的江南春意图，那么，第二首词便像一幅杭州之秋的画作了。\n\n　　作者很爱西湖的春天，他在词里偏偏不写杭州之春，这可能是为了避免和第一首词所写的春景重复。他写杭州之秋，一写灵隐寺赏月赏桂，一写高亭之上观钱塘江潮。两句词就写出两种境界。“山寺月中寻桂子”的“山寺”，指的是西湖西边的灵隐寺。这座古刹有许多传说，有的还蒙上一层神话色彩：传说灵隐寺的桂花树是从月宫中掉下来的。作者曾在寺中赏月，中秋节桂花飘香，那境界使他终身难忘。山、寺、月影下，寻桂子，写出了幽美的环境，也写了置身其间的词人的活动。然而，词人回忆杭州还有另一种境界使人难忘。那就是“郡亭枕上看潮头”，钱塘江潮是大自然的奇观，潮头可高达数丈，所以白居易写他躺在他郡衙的亭子里，就能看见那卷云拥雪的潮头了，显得趣意盎然。“郡亭枕上看潮头”，以幽闲的笔墨带出惊涛骇浪的景色，与上句“山寺月中寻桂子”的静谧而朦胧的美的境界形成鲜明的对照，相辅相成，相得益彰。白居易是热爱杭州的，所以他在回到北方以后，又产生了“何日更重游”的愿望。\n\n　　第三首词在思想艺术上都不及第一、二首，加上他又写到歌舞生活，因而许多选本都不介绍它。其实它在写法上也并不是全无可取之处的。前两首词虽然也写到人，但主要还是写景。第三首点到吴宫，但主要却是写人，写苏州的歌舞伎和词人自己。从整体上看，意境的变化使连章体词显得变化多姿，丰富多彩。\n\n　　吴酒一杯春竹叶一句，一来，竹叶是为了与下句的芙蓉对偶，二来，“春”在这里是形容词，所谓春竹叶并非一定是指竹叶青酒，而是指能带来春意的酒。白居易在另一诗里就有“瓮头竹叶经春熟”的说法，唐代有不少名酒以春字命名，文人大多爱酒，白居易应该也不例外，喝着吴酒，观“吴娃双舞”犹如醉酒芙蓉的舞姿。“娃”，即是美女，西施就被称为“娃”，吴王夫差为她建的房子就叫“馆娃宫”。白居易这样写，就是出于对西施这位绝代佳人的联想。作者不是纵情声色的人，他欣赏的是吴娃的歌舞，希望能重睹演出，因而回到洛阳后说：“早晚复相逢。”\n\n　　这三首词，从今时忆往日，从洛阳忆苏杭。今、昔、南、北、时间、空间的跨度都很大。每一首的头两句，都抚今追昔，身在洛阳，神驰江南。每一首的中间两句，都以无限深情，追忆最难忘的江南往事。结句呢？则又回到今天，希冀那些美好的记忆有一天能够变成活生生的现实。因此，整个组词不过寥寥数十字，却从许多层次上吸引读者进入角色，想象主人公今昔南北所经历的各种情境，体验主人公今昔南北所展现的各种精神活动，从而获得寻味无穷的审美享受。\n\n　　这三首词，每首自具首尾，有一定的独立性；而各首之间，又前后照应，脉络贯通，构成有机的整体大“联章”诗词中，显示出作者谋篇布局的高超艺术技巧。', poem_tags = '乐府,写景,地名,春天' WHERE poem_title = '忆江南词三首' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '我在年少时离开家乡，到了迟暮之年才回来。我的乡音虽未改变，但鬓角的毛发却已经疏落。儿童们看见我，没有一个认识的。他们笑着询问：这客人是从哪里来的呀？', poem_notes = '偶书：随便写的诗。偶：说明诗写作得很偶然，是随时有所见、有所感就写下来的。 \n少小离家：贺知章三十七岁中进士，在此以前就离开家乡。老大：年纪大了。贺知章回乡时已年逾八十。\n乡音：家乡的口音。无改：没什么变化。一作“难改”。鬓毛：额角边靠近耳朵的头发。一作“面毛”。衰（cui）：减少，疏落。鬓毛衰：指鬓毛减少，疏落。\n相见：即看见我；相：带有指代性的副词。不相识：即不认识我。\n笑问：一本作“却问”，一本作“借问”。', poem_appreciation = '这是一首久客异乡、缅怀故里的感怀诗。写于初来乍到之时，抒写久客伤老之情。在第一、二句中，诗人置身于故乡熟悉而又陌生的环境之中，一路迤逦行来，心情颇不平静：当年离家，风华正茂；今日返归，鬓毛疏落，不禁感慨系之。首句用“少小离家”与“老大回”的句中自对，概括写出数十年久客他乡的事实，暗寓自伤“老大”之情。次句以“鬓毛衰”顶承上句，具体写出自己的“老大”之态，并以不变的“乡音”映衬变化了的“鬓毛”，言下大有“我不忘故乡，故乡可还认得我吗”之意，从而为唤起下两句儿童不相识而发问作好铺垫。\n\n　　三四句从充满感慨的一幅自画像，转而为富于戏剧性的儿童笑问的场面。“笑问客从何处来”，在儿童，这只是淡淡的一问，言尽而意止；在诗人，却成了重重的一击，引出了他的无穷感慨，自己的老迈衰颓与反主为宾的悲哀，尽都包含在这看似平淡的一问中了。全诗就在这有问无答处悄然作结，而弦外之音却如空谷传响，哀婉备至，久久不绝。\n\n　　就全诗来看，一二句尚属平平，三四句却似峰回路转，别有境界。后两句的妙处在于背面敷粉，了无痕迹：虽写哀情，却借欢乐场面表现；虽为写己，却从儿童一面翻出。而所写儿童问话的场面又极富于生活的情趣，即使读者不为诗人久客伤老之情所感染，也不能不被这一饶有趣味的生活场景所打动。\n\n　　杨衡《对床夜语》诗云：“正是忆山时，复送归山客。”张籍云：“长因送人处，忆得别家时。”卢象《还家诗》云：“小弟更孩幼，归来不相识。”贺知章云：“儿童相见不相识，笑问客从何处来。”语益换而益佳，善脱胎者宜参之。', poem_tags = '唐诗三百首,小学古诗,思乡,感慨,伤老,早教古诗100首' WHERE poem_title = '回乡偶书二首·其一' AND poem_author = '贺知章';
UPDATE edu_poem SET poem_translation = '夕阳依傍着西山慢慢地沉没， 滔滔黄河朝着东海汹涌奔流。\n若想把千里的风光景物看够， 那就要登上更高的一层城楼。', poem_notes = '鹳雀楼：旧址在山西永济县，楼高三层，前对中条山，下临黄河。传说常有鹳雀在此停留，故有此名。\n白日：太阳。\n依：依傍。\n尽：消失。 这句话是说太阳依傍山峦沉落。\n欲：想要得到某种东西或达到某种目的的愿望，但也有希望、想要的意思。\n穷：尽，使达到极点。\n千里目：眼界宽阔。\n更：替、换。（不是通常理解的“再”的意思）', poem_appreciation = '诗的前两句“白日依山尽，黄河入海流”，写的是登楼望见的景色，写得景象壮阔，气势雄浑。这里，诗人运用极其朴素、极其浅显的语言，既高度形象又高度概括地把进入广大视野的万里河山，收入短短十个字中；而我们在千载之下读到这十个字时，也如临其地，如见其景，感到胸襟为之一开。首句写遥望一轮落日向着楼前一望无际、连绵起伏的群山西沉，在视野的尽头冉冉而没。这是天空景、远方景、西望景。次句写目送流经楼前下方的黄河奔腾咆哮、滚滚南来，又在远处折而东向，流归大海。这是由地面望到天边，由近望到远，由西望到东。这两句诗合起来，就把上下、远近、东西的景物，全都容纳进诗笔之下，使画面显得特别宽广，特别辽远。就次句诗而言，诗人身在鹳雀楼上，不可能望见黄河入海，句中写的是诗人目送黄河远去天边而产生的意中景，是把当前景与意中景溶合为一的写法。这样写，更增加了画面的广度和深度。\n\n　　杜甫在《戏题王宰画山水图歌》中有“尤工远势古莫比，咫尺应须论万里”两句，虽是论画，也可以用来论诗。王之涣的这两句写景诗就做到了缩万里于咫尺，使咫尺有万里之势。\n\n　　诗笔到此，看似已经写尽了望中的景色，但不料诗人在后半首里，以“欲穷千里目，更上一层楼”这样两句即景生意的诗，把诗篇推引入更高的境界，向读者展示了更大的视野。这两句诗，既别翻新意，出人意表，又与前两句诗承接得十分自然、十分紧密；同时，在收尾处用一“楼”字，也起了点题作用，说明这是一首登楼诗。从这后半首诗，可推知前半首写的可能是在第二层楼所见，而诗人还想进一步穷目力所及看尽远方景物，更登上了楼的顶层。诗句看来只是平铺直叙地写出了这一登楼的过程，而含意深远，耐人探索。这里有诗人的向上进取的精神、高瞻远瞩的胸襟，也道出了要站得高才看得远的哲理。\n\n　　就全诗而言，这首诗是日僧空海在《文镜秘府论》中所说的“景入理势”。有人说，诗忌说理。这应当只是说，诗歌不要生硬地、枯燥地、抽象地说理，而不是在诗歌中不能揭示和宣扬哲理。象这首诗，把道理与景物、情事溶化得天衣无缝，使读者并不觉得它在说理，而理自在其中。这是根据诗歌特点、运用形象思维来显示生活哲理的典范。\n\n　　这首诗在写法上还有一个特点：它是一首全篇用对仗的绝句。沈德潜在《唐诗别裁》中选录这首诗时曾指出：“四语皆对，读来不嫌其排，骨高故也。”绝句总共只有两联，而两联都用对仗，如果不是气势充沛，一意贯连，很容易雕琢呆板或支离破碎。这首诗，前一联用的是正名对，所谓“正正相对”，语句极为工整，又厚重有力，就更显示出所写景象的雄大；后一联用的是流水对，虽两句相对，而没有对仗的痕迹。诗人运用对仗的技巧也是十分成熟的。\n\n　　《梦溪笔谈》中曾指出，唐人在鹳雀楼所留下的诗中，“惟李益、王之涣、畅当三篇，能状其景”。李益的诗是一首七律；畅当的诗也是一首五绝，也题作《登鹳雀楼》。全诗如下：“迥临飞鸟上，高出世尘间。天势围平野，河流入断山。”诗境也很壮阔，不失为一首名作，但有王之涣的这首诗在前，比较之下，终输一筹，不得不让王诗独步千古。', poem_tags = '唐诗三百首,登楼,写景,山水,黄河,励志,哲理,早教古诗100首' WHERE poem_title = '登鹳雀楼' AND poem_author = '王之涣';
UPDATE edu_poem SET poem_translation = '我在南山下种植豆子，地里野草茂盛豆苗豌稀。\n清晨早起下地铲除杂草，夜幕降披月光扛锄归去。\n狭窄的山径草木丛生，夜露沾湿了我的衣。\n衣衫被沾湿并不可惜．只希望不违背我归耕田园的心意。', poem_notes = '南山：指庐山。\n稀： 稀少。\n兴： 起床。\n荒秽：形容词作名词，荒芜，指豆苗里的杂草。秽：肮脏。这里指田中杂草\n荷锄：扛着锄头。荷，扛着。\n狭： 狭窄。\n草木长：草木丛生。长，生长\n夕露：傍晚的露水。\n沾：（露水）打湿。\n足： 值得。\n但使愿无违： 只要不违背自己的意愿就行了。但：只。愿： 指向往田园生活，“不为五斗米折腰”，不愿与世俗同流合污的意愿。违： 违背。', poem_appreciation = '这首“种豆南山下”八句短章，在普普通通、平平常常四十个字的小空间里，表达出了深刻的思想内容，描写了诗人隐居之后躬耕劳动的情景。\n\n　　本诗共分为两层，前四句为第一层。反映了作者躬耕劳动的生活。暗用杨恽诗作。\n\n　　“种豆南山下，苗盛豆苗稀”。此二句引用了杨恽的“田彼南山，芜秽不治”，是对其劳作情况做总体交待，先指明耕种的是“豆”，再说劳作的地点在“南山下”，五个寻常字，将事情叙说得非常清楚。诗人毕竟是“少学琴书”，士人出身，躬耕田亩缺乏经验，“草盛豆苗稀”的劳动后果，也就不足为怪了。\n\n　　“晨兴理荒秽，带月荷锄归。”可怜的劳动成果并没使诗人灰心丧气，牢骚满腹。这两句写出了他勤勤恳恳，乐此不疲地从清早到夜晚，躬身垄亩铲锄荒草的状貌。它体现了中华民族自古以来的吃苦耐劳，坚韧不拔的精神。\n\n　　后四句是本诗的第二层，抒写的则是作者经过生活的磨励和对社会与人生深刻思索之后，对真善美理想的执着追求和与现实社会污浊官场的决裂。\n\n　　“道狭草木长，夕露沾我衣”。通过道窄草深，夕露沾衣的具体细节描绘，显示出了从事农业劳动的艰苦。诗人身体力行终日劳作在田野，所以他深深地体验到了农业劳动的艰辛，它绝不像那些脱离劳动的文人墨客所描写的那般轻松潇洒。但是作者仍不辞劳苦，继续坚持下去，正像他在《庚戌岁九月中于西田获早稻》诗中所说：“田家岂不苦?弗获辞此难。”\n\n　　“衣沾不足惜，但使愿无违。”对于诗人来说，人生的道路只有两条任他选择：一条是出仕做官，有俸禄保证其生活，可是必须违心地与世俗同流合污；另一条是归隐田园，靠躬耕劳动维持生存，这样可以做到任性存真坚持操守。当他辞去彭泽县令解绶印归田之际，就已经做出了抉择，宁可肉体受苦，也要保持心灵的纯洁，他坚决走上了归隐之路。为了不违背躬耕隐居的理想愿望，农活再苦再累又有何惧?那么“夕露沾衣”就更不足为“惜”了。这种思想已经成了他心中牢不可破的坚定信念，本诗结尾两句’，可谓全篇的诗眼，一经它的点化，篇中醇厚的旨意便合盘现出。\n\n　　在本诗中陶渊明却勇敢地反对了传统观念，冲破了陈旧的精神枷锁，毅然地告别官场，辞去了彭泽县令，不做劳心治人的“君子”；决然地返回家园，心甘情愿地扛起了锄头，辛勤地躬耕垄亩，偏要做个劳力的“小人”。这等无畏的精神，美好的人格，高尚的境界，赢得了后世多少人的称赞、钦佩乃至效仿。', poem_tags = '古诗三百首,初中古诗,田园,生活' WHERE poem_title = '归园田居·其三' AND poem_author = '陶渊明';
UPDATE edu_poem SET poem_translation = '古代求学的人一定有老师。老师，是（可以）依靠来传授道理、教授学业、解答疑难问题的。人不是生下来就懂得道理的，谁能没有疑惑？（有了）疑惑，如果不跟从老师（学习），那些成为疑难问题的，就最终不能理解了。生在我前面，他懂得道理本来就早于我，我（应该）跟从（他）把他当作老师；生在我后面，（如果）他懂得的道理也早于我，我（也应该）跟从（他）把他当作老师。我（是向他）学习道理啊，哪管他的生年比我早还是比我晚呢？因此，无论地位高低贵贱，无论年纪大小，道理存在的地方，就是老师存在的地方。\n\n　　唉，（古代）从师（学习）的风尚不流传已经很久了，想要人没有疑惑难啊!古代的圣人，他们超出一般人很远，尚且跟从老师而请教；现在的一般人，他们（的才智）低于圣人很远，却以向老师学习为耻。因此圣人就更加圣明，愚人就更加愚昧。圣人之所以能成为圣人，愚人之所以能成为愚人，大概都出于这吧？（人们）爱他们的孩子，就选择老师来教他，（但是）对于他自己呢，却以跟从老师（学习）为可耻，真是糊涂啊!那些孩子们的老师，是教他们读书，（帮助他们）学习断句的，不是我所说的能传授那些道理，解答那些疑难问题的。（一方面）不通晓句读，（另一方面）不能解决疑惑，有的（句读）向老师学习，有的（疑惑）却不向老师学习；小的方面倒要学习，大的方面反而放弃（不学），我没看出那种人是明智的。巫医乐师和各种工匠这些人，不以互相学习为耻。士大夫这类人，（听到）称“老师”称“弟子”的，就成群聚在一起讥笑人家。问他们（为什么讥笑），就说：“他和他年龄差不多，道德学问也差不多，（以）地位低（的人为师），就觉得羞耻，（以）官职高（的人为师），就近乎谄媚了。”唉!（古代那种）跟从老师学习的风尚不能恢复，（从这些话里就）可以明白了。巫医乐师和各种工匠这些人，君子们不屑一提，现在他们的见识竟反而赶不上（这些人），真是令人奇怪啊!\n\n　　圣人没有固定的老师。孔子曾以郯子、苌弘、师襄、老聃为师。郯子这些人，他们的贤能都比不上孔子。孔子说：“几个人一起走，（其中）一定有（可以当）我的老师（的人）。”因此学生不一定不如老师，老师不一定比学生贤能，听到的道理有早有晚，学问技艺各有专长，如此罢了。\n\n　　李家的孩子蟠，年龄十七，喜欢古文，六经的经文和传文都普遍地学习了，不受时俗的拘束，向我学习。我赞许他能够遵行古人（从师）的途径，写这篇《师说》来赠送他。', poem_notes = '学者：求学的人。\n师者，所以传道受业解惑也：老师，是用来传授道理、交给学业、解释疑难问题的人。所以，用来……的。道，指儒家之道。受，通“授”，传授。业，泛指古代经、史、诸子之学及古文写作。惑，疑难问题\n人非生而知之者：人不是生下来就懂得道理。之，指知识和道理。《论语·季氏》：“生而知之者，上也；学而知之者，次也；困而学之，又其次之；困而不学，民斯为下矣。” 知，懂得。\n其为惑也：他所存在的疑惑。\n生乎吾前：即生乎吾前者。乎：相当于“于”，与下文“先乎吾”的“乎”相同。\n闻：听见，引申为知道，懂得。\n从而师之：跟从（他），拜他为老师。师，意动用法，以……为师。从师，跟从老师学习。\n吾师道也：我（是向他）学习道理。师，用做动词。\n夫庸知其年之先后生于吾乎：哪里去考虑他的年龄比我大还是小呢？庸，发语词，难道。知，了解、知道。之，取独。\n是故：因此，所以。\n无：无论、不分。\n道之所存，师之所存也：意思说哪里有道存在，哪里就有我的老师存在。\n师道：从师的传统。即上文所说的“古之学者必有师”。\n出人：超出于众人之上。\n犹且：尚且。\n众人：普通人，一般人。\n下：不如，名作动。\n耻学于师：以向老师学习为耻。耻，以……为耻\n是故圣益圣，愚益愚：因此圣人更加圣明，愚人更加愚昧。益，更加、越发。\n于其身：对于他自己。身，自身、自己。\n惑矣：（真是）糊涂啊！\n彼童子之师：那些教小孩子的（启蒙）老师。\n授之书而习其句读（dòu）：教给他书，（帮助他）学习其中的文句。之，指童子。习，使……学习。其，指书。句读，也叫句逗，古人指文辞休止和停顿处。文辞意尽处为句，语意未尽而须停顿处为读（逗）。古代书籍上没有标点，老师教学童读书时要进行句读（逗）的教学。\n句读之不知：不知断句风逗。与下文“惑之不解”结构相同。之，提宾标志。\n或师焉，或不焉：有的（指“句读之不知”这样的小事）从师，有的（指“惑之不解”这样的大事）不从师。不，通“否”。\n小学而大遗：学了小的（指“句读之不知”）却丢了大的（指“惑之不解”）。遗，丢弃，放弃。\n巫医：古时巫、医不分，指以看病和降神祈祷为职业的人。\n百工：各种手艺。\n相师：拜别人为师。\n族：类。\n曰师曰弟子云者：说起老师、弟子的时候。\n年相若：年岁相近。\n位卑则足羞，官盛则近谀：以地位低的人为师就感到羞耻，以高官为师就近乎谄媚。足，可，够得上。盛，高大。谀，谄媚。\n复：恢复。\n君子：即上文的“士大夫之族”。\n不齿：不屑与之同列，即看不起。或作“鄙之”。\n乃：竟，竟然。\n其可怪也欤：难道值得奇怪吗。其，难道，表反问。欤，语气词，表感叹。\n圣人无常师：圣人没有固定的老师。常，固定的。\n郯（tán）子：春秋时郯国（今山东省郯城县境）的国君，相传孔子曾向他请教官职。\n苌（cháng）弘：东周敬王时候的大夫，相传孔子曾向他请教古乐。\n师襄：春秋时鲁国的乐官，名襄，相传孔子曾向他学琴。\n老聃（dān）：即老子，姓李名耳，春秋时楚国人，思想家，道家学派创始人。相传孔子曾向他学习周礼。聃是老子的字。\n之徒：这类。\n三人行，则必有我师：三人同行，其中必定有我的老师。《论语·述而》原话：“子曰：‘三人行，必有我师焉。择其善者而从之，其不善者而改之。’”\n不必：不一定。\n术业有专攻：在业务上各有自己的专门研究。攻，学习、研究。\n李氏子蟠（pán）：李家的孩子名蟠。李蟠，韩愈的弟子，唐德宗贞元十九年（803年）进士。\n六艺经传（zhuàn）皆通习之：六艺的经文和传文都普遍的学习了。六艺，指六经，即《诗》《书》《礼》《乐》《易》《春秋》六部儒家经典。《乐》已失传，此为古说。经，两汉及其以前的散文。传，古称解释经文的著作为传。通，普遍。\n不拘于时：指不受当时以求师为耻的不良风气的束缚。时，时俗，指当时士大夫中耻于从师的不良风气。于，被。\n余嘉其能行古道：赞许他能遵行古人从师学习的风尚。嘉：赞许，嘉奖。\n贻：赠送，赠予。', poem_appreciation = '韩愈作《师说》的时候，有人以为是在唐德宗贞元十八年（802），这大致是可信的。这年韩愈35岁，刚由洛阳闲居进入国子监，为四门学博士，这是一个“从七品”的学官。但他早已有名。他所提倡和不断实践的古文运动，在那一两年内，正走出少数爱好者的范围，形成一个广泛性的运动，他俨然成为这个运动的年轻的领袖。他用古文来宣传他的主张。维护先秦儒家的思想，反对当代特别盛行的佛老思想；提倡先秦两汉的古文，反对“俗下文字”即魏晋以来“饰其辞而遗其意”的骈文：这就是古文运动的内容。这个运动所以逐渐形成于唐德宗统治的后期，是有现实的社会条件的。它是为维护唐王朝的统一、反对藩镇割据的政治目的服务的。而这除军阀、大地主外，正是当时广大社会阶层的现实利益的要求。韩愈的积极努力，对这个运动的开展与形成，起了不断促进的作用。就古文来说，他不仅自己刻苦努力，从理论到实践，表现了优秀的成绩；更重要的是他不顾流俗的非笑，努力提倡，特别表现在给青年们热情的鼓励和指示。《师说》正是这种努力所引起的一篇具有进步意义和解放精神的文章。\n\n　　韩愈由于幼年的家庭教养和天宝以来复古主义思潮的影响，从青年时代起，就以一个传道的古文家自命。这也是他在科举和仕宦的阶梯上十年不能得意的一个重要原因。但是他并不悔，还愈来愈有自信。最初他到汴州参加宣武节度使董晋幕府的时候（796—798），先教李翱学古文；由于孟郊的介绍，不久又教张籍学古文。后来逃难到徐州（799），徐泗濠节度使张建封安置他在符离，又教一个青年人张彻读古书，学古文。张建封死后，仕途不通，到洛阳闲居（800—801）。向他请教的青年愈来愈多，他对青年们非常热情，奖励有加。他在《重答李翊书》中说：“言辞之不酬，礼貌之不答，虽孔子不得行于互乡，宜乎余之不为也。苟来者，吾斯进之而已矣，乌待其礼逾而情过乎？”为了“广圣人之道”，他以热情的、有礼貌的态度对待一切向他请教的青年，他认为这并不是什么“礼逾”和“情过”的问题。他回答许多青年的信，指示怎样做人，怎样作文。在韩愈看来，文章是作者的人格修养的表现，做人与作文应该是一致的。他进了国子监后，对待青年依然非常热情。\n\n　　韩愈这样不断地同青年后学交往，给他们奖励和指示，这是魏晋以后所没有的现象，当然要引起人们的奇怪，以至纷纷议论和责难。一切向韩愈投书请益的青年便自然地被目为韩门弟子，因而韩愈“好为人师”的古怪面貌也就非常突出了。但韩愈是早有自信的，他不管人们怎样诽谤，依然大胆地回答青年们的来信。他在《答胡生书》中说：“夫别是非，分贤与不肖，公卿贵位者之任也，愈不敢有意于是。如生之徒，于我厚者，知其贤，时或道之，于生未有益也。不知者乃用是为谤！不敢自爱，惧生之无益而有伤也，如之何？”他对那些恶意中伤的诽谤，表示愤慨，也为向他请教的青年担忧。《师说》的最后一段，声明写作的由来，说这是为了一个“好古文”“能行古道”，跟他学习的青年李蟠而作的。实际上他是借此对那些诽谤者来一个公开的答复和严正的驳斥。他是有的放矢的。\n\n　　在这篇文章里，他首先（第1段）肯定从古以来师对于任何人总是不可少的，因为人不能“生而知之”，谁也不能没有“惑”──茫然不解的东西。因此，他认为师并不是什么特殊人物，而是一种“传道受业解惑”的人。他还认为人人都可以为师，没有社会地位（贵贱）或年龄（长少）的限制，只问他有没有“道”，有就可以为师，所谓“道之所存，师之所存也”。接着（第2段），他慨叹古来的“师道”久已失传。现在一般人，既不能“无惑”，又“耻学于师”，所以越来越愚蠢。然后列举事例，论证这种“耻学于师”的风气实在是愚蠢而奇怪的。他说有一种人，即士大夫，对于儿子，则“择师而教之”；但对于自己，“则耻师焉”：这就是他们的不明。又有一种现象，广大的各行各业的人，即“巫医乐师百工之人”不以彼此相师为耻；而“士大夫之族”，如果有人谈到谁是师，谁是弟子，则大家共同非笑，问其理由，无非是年龄、地位云云，这又证明了他们的智慧反而在他们所瞧不起的巫医等等之下，这不是很奇怪吗？再看（第3段），“士大夫之族”所崇拜的“圣人”没有一定的师，孔子的师有郯子、苌弘等，这些人都“不及孔子”。而且孔子还说过，三个人里面，一定有一个人是他的师。因此，作者得到另一个重要的论点，师和弟子的关系是相对的，“弟子不必不如师，师不必贤于弟子”。这就是说，弟子可以为师，师也可以为弟子。所以师和弟子的关系的存在，最后结论很简单，不过是因为“闻道有先后，术业有专攻”的缘故。这也还是前文所提出的论点，即能者为师。\n\n　　由此可见，《师说》不仅严正地驳斥了那些愚蠢的诽谤者，更可贵的是提出了三点崭新的、进步的“师道”思想：师是“传道受业解惑”的人；人人都可以为师，只要具有那样的能力；师和弟子的关系是相对的，某一方面比我好，在这一方面他就是我的师。这些思想把师的神秘性、权威性、封建性大大地减轻了；把师和弟子的关系合理化了，平等化了，把师法或家法的保守的壁垒打破了。这些思想是和他后来发展的“道统”思想矛盾的。这些思想是具有解放精神、具有深刻的人民性的思想。这是唐德宗时代在相对的稳定局面之下，城市繁荣、商业经济发展的反映。\n\n　　因此，可以想象，这篇《师说》的流布，鼓舞和吸引了更多的青年后学，也因而招致了更多的顽固的“士大夫之族”的反对。实际上，韩愈也确乎因此官更难作，不断地遭到当权者的排挤。柳宗元在《答韦中立论师道书》中说：“今之世不闻有师，有，辄哗笑之，以为狂人。独韩愈奋不顾流俗，犯笑侮，收召后学，作《师说》，因抗颜而为师。世果群怪聚骂，指目牵引，而增与为言辞。愈以是得狂名。居长安，炊不暇熟，又挈挈而东，如是者数矣。”贞元十九年（803），韩愈在监察御史的职位，第一次被当权的官僚集团赶出了长安，贬到阳山（今广东阳山），就是在作《师说》一年后。他这次被贬，原因可能很复杂，但照柳宗元所说，这篇《师说》至少是重要的原因之一，因为他由此“狂名”更大，为更多的顽固派所疾恶，更容易遭到莫名的排挤。然而韩愈在奖励后学这一点上，态度始终不变，只是到了元和以后，声势没有在贞元末年那么大就是了。到了宋代，有人为韩愈辩解，说他“非好为人师者也”（《五百家注音辩昌黎先生文集》卷十二引“洪曰”），这是说，由于学者归附，韩愈是不得已而“作之师”的。又有人以为韩愈“作《师说》，盖以师道自任”，但充其量不过“以传道受业解惑为事，则世俗训导之师，口耳之学耳”（俞文豹《吹剑三录》），这是指韩愈把师的封建作用大大地降低了。可见这篇《师说》的解放精神是不容易为一般封建士大夫所接受的。因此，它在当时的重大意义也就不难理解了。', poem_tags = '高中文言文,古文观止,议论,老师' WHERE poem_title = '师说' AND poem_author = '韩愈';
UPDATE edu_poem SET poem_translation = '英译 Silence, are lonely, alone on the empty slowly west wing. Looked up days, only one curved like the hook of the company. Lower the head to look, see buttonwood isolated and lonely in the yard, deep courtyard was enveloped in the autumn cold and desolate. That cut cut constantly, also the principle, reason not clear, let a person afflicted with, it is of national subjugation. The long melancholy wrapped around the heart, but is another kind of an ineffable painful. ▲', poem_appreciation = '首句“无言独上西楼”将人物引入画面。“无言”二字活画出词人的愁苦神态，“独上”二字勾勒出作者孤身登楼的身影，孤独的词人默默无语，独自登上西楼。神态与动作的描写，揭示了词人内心深处隐寓的很多不能倾诉的孤寂与凄婉。\n\n　　“……月如钩，寂寞梧桐深院，锁清秋”，寥寥12个字，形象地描绘出了词人登楼所见之景。仰视天空，缺月如钩。“如钩”不仅写出月形，表明时令，而且意味深长：那如钩的残月经历了无数次的阴晴圆缺，见证了人世间无数的悲欢离合，如今又勾起了词人的离愁别恨。俯视庭院，茂密的梧桐叶已被无情的秋风扫荡殆尽，只剩下光秃秃的树干和几片残叶在秋风中瑟缩，词人不禁“寂寞”情生。然而，“寂寞”的不只是梧桐，即使是凄惨秋色，也要被“锁”于这高墙深院之中。而“锁”住的也不只是这满院秋色，落魄的人，孤寂的心，思乡的情，亡国的恨，都被这高墙深院禁锢起来，此景此情，用一个愁字是说不完的。\n\n　　缺月、梧桐、深院、清秋，这一切无不渲染出一种凄凉的境界，反映出词人内心的孤寂之情，同时也为下片的抒情做好铺垫。作为一个亡国之君，一个苟延残喘的囚徒，他在下片中用极其婉转而又无奈的笔调，表达了心中复杂而又不可言喻的愁苦与悲伤。\n\n　　“剪不断，理还乱，是离愁。”用丝喻愁，新颖而别致。前人以“丝”谐音“思”，用来比喻思念，如李商隐“春蚕到死丝方尽，蜡炬成灰泪始干”（《无题》）就是大家熟悉的名句。李煜用“丝”来比喻“离愁”，别有一番新意。然而丝长可以剪断，丝乱可以整理，而那千丝万缕的“离愁”却是“剪不断，理还乱”。这位昔日的南唐后主心中所涌动的离愁别绪，是追忆“红日已高三丈后，金炉次第添金兽，红锦地衣随步皱”（《浣溪沙》）的荣华富贵，是思恋“风阁龙楼连霄汉，玉树琼枝作烟萝”（《破阵子》）的故国家园，是悔失“四十年来家国，三千里地山河”（《破阵子》）的帝王江山。然而，时过境迁，如今的李煜已是亡国奴、阶下囚，荣华富贵已成过眼烟云，故国家园亦是不堪回首，帝王江山毁于一旦。阅历了人间冷暖、世态炎凉，经受了国破家亡的痛苦折磨，这诸多的愁苦悲恨哽咽于词人的心头难以排遣。作者尝尽了愁的滋味，而这滋味，是难以言喻、难以说完的。\n\n　　末句“别是一番滋味在心头”，紧承上句写出了李煜对愁的体验与感受。以滋味喻愁，而味在酸甜之外，它根植于人的内心深处，是一种独特而真切的感受。“别是”二字极佳，昔日唯我独尊的天子，如今成了阶下囚徒，备受屈辱，遍历愁苦，心头淤积的是思、是苦、是悔、还是恨……词人自己也难以说清，常人更是体会不到。若是常人，倒可以嚎啕倾诉，而李煜不能。他是亡国之君，即使有满腹愁苦，也只能“无言独上西楼”，眼望残月如钩、梧桐清秋，将心头的哀愁、悲伤、痛苦、悔恨强压在心底。这种无言的哀伤更胜过痛哭流涕之悲。\n\n　　沈际飞在《草堂诗余续集》中评价说：“七情所至，浅尝者说破，深尝者说不破。破之浅，不破之深。‘别是一般滋味在心头’句妙。”唐圭璋在《唐宋词简释》中说：“此词写别愁，凄惋已极。‘无言独上西楼’一句，叙事直起，画出后主愁容。其下两句，画出后主所处之愁境。举头见新月如钩，低头见桐阴深锁俯仰之间，万感萦怀矣。此片写景亦妙，惟其桐阴深黑，新月乃愈显明媚也。下片，因景抒情。换头三句，深刻无匹，使有千丝万缕之离愁，亦未必不可剪，不可理，此言‘剪不断，理还乱’，则离愁之纷繁可知。所谓‘别是一般滋味’，是无人尝过之滋味，唯有自家领略也。后主以南朝天子，而为北地幽囚；其所受之痛苦，所尝之滋味，自与常人不同，心头所交集者，不知是悔是恨，欲说则无从说起，且亦无人可说，故但云‘别是一般滋味’。”\n\n　　李煜的这首词情景交融，感情沉郁。上片选取典型的景物为感情的抒发渲染铺垫，下片借用形象的比喻委婉含蓄地抒发真挚的感情。此外，运用声韵变化，做到声情合一。下片押两个仄声韵（“断”、“乱”），插在平韵中间，加强了顿挫的语气，似断似续；同时在三个短句之后接以九言长句，铿锵有力，富有韵律美，也恰当地表现了词人悲痛沉郁的感情。', poem_tags = '宋词三百首,初中古诗,婉约,登楼,写景,孤独,思念' WHERE poem_title = '相见欢·无言独上西楼' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '沿着弯弯曲曲的小路上山，在那白云深处，居然还有人家。\n停下车来，是因为喜爱这深秋枫林晚景。枫叶秋霜染过，艳比二月春花。', poem_notes = '山行：在山中行走。\n远上：登上远处的。\n寒山：深秋季节的山。\n石径：石子的小路。\n斜：为倾斜的意思。\n深：另有版本作“生”。（“深”可理解为在云雾缭绕的的深处； “生”可理解为在形成白云的地方）\n车：轿子。\n坐：因为。\n霜叶：枫树的叶子经深秋寒霜之后变成了红色。\n枫林晚：傍晚时的枫树林。\n红于：比……更红，本文指霜叶红于二月花。', poem_appreciation = '这首诗描绘的是秋之色，展现出一幅动人的山林秋色图。诗里写了山路、人家、白云、红叶，构成一幅和\n\n　　谐统一的画面。这些景物不是并列的处于同等地位，而是有机地联系在一起，有主有从，有的处于画面的中心，有的则处于陪衬地位。简单来说，前三句是宾，第四句是主，前三句是为第四句描绘背景、创造气氛，起铺垫和烘托作用的。 “远上寒山石径斜”，写山，写山路。一条弯弯曲曲的小路蜿蜓伸向山头。“远”字写出了山路的绵长，“斜”字与“上”字呼应，写出了高而缓的山势。\n\n　　“白云深处有人家”，写云，写人家。诗人的目光顺着这条山路一直向上望去，在白云飘浮的地方，有几处山石砌成的石屋石墙。这里的“人家”照应了上句的“石径”，—这一条山间小路，就是那几户人家上上下下的通道。这样就把两种景物有机地联系在一起了。有白云缭绕，说明山很高。诗人用横云断岭的手法，让这片片白云遮住读者的视线，却给人留下了想象的空间：在那白云之上，云外有山，一定会有另一种景色。\n\n　　对这些景物，诗人只是在作客观的描述。虽然用了一个“寒”字，也只是为了逗出下文的“晚”字和“霜”字，并不表现诗人的感情倾向。它毕竟还只是在为后面的描写蓄势—勾勒枫林所在的环境。\n\n　　“停车坐爱枫林晚”便不同了，倾向性已经很鲜明，很强烈了。那山路、白云、人家都没有使诗人动心，这枫林晚景却使得他惊喜之情难以抑制。为了要停下来领略这山林风光，竟然顾不得驱车赶路。这句中的“晚”字用得无比精妙，它蕴含多层意思：（1）点明前两句是白天所见，后两句则是傍晚之景。（2）因为傍晚才有夕照，绚丽的晚霞和红艳的枫叶互相辉映，枫林才格外美丽。（3）诗人流连忘返，到了傍晚，还舍不得登车离去，足见他对红叶喜爱之极。（4）因为停车甚久，观察入微，才能悟出第四句“霜叶红于二月花”这样富有理趣的警句。\n\n　　前两句所写的景物已经很美，但诗人爱的却是枫林。通过前后映衬，已经为描写枫林铺平垫稳，蓄势已足，于是水到渠成，引出了第四句，点明喜爱枫林的原因。“霜叶红于二月花”，把第三句补足，一片深秋枫林美景具体展现出来了。诗人惊喜地发现在夕晖晚照下，枫叶流丹，层林如染，真是满山云锦，如烁彩霞，它比江南二月的春花还要火红，还要艳丽。难能可贵的是，诗人通过这一片红色，看到了秋天象春天一样的生命力使秋天的山林呈现一种热烈的、生机勃勃的景象。\n\n　　诗人没有象一般封建文人那样，在秋季到来的时候，哀伤叹息，他歌颂的是大自然的秋色美，体现出了豪爽向上的精神，有一种英爽俊拔之气拂拂笔端，表现了诗人的才气，也表现了诗人的见地。这是一首秋色的赞歌。\n\n　　第四句是全诗的中心，是诗人浓墨重彩、凝聚笔力写出来的。不仅前两句疏淡的景致成了这艳丽秋色的衬托，即使“停车坐爱枫林晚”一句，看似抒情叙事，实际上也起着写景衬托的作用：那停车而望、陶然而醉的诗人，也成了景色的一部分，有了这种景象，才更显出秋色的迷人。而一笔重写之后，戛然便止，又显得情韵悠扬，余味无穷。\n\n　　全诗构思新颖，布局精巧，于萧瑟秋风中摄取绚丽秋色，与春光争胜，令人赏心悦目，精神发越。兼之语言明畅，音韵和谐。', poem_tags = '小学古诗,秋天,写景,言志,早教古诗100首' WHERE poem_title = '山行' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '碧云飘悠的蓝天，黄叶纷飞的大地，秋景连接着江中水波，波上弥漫着苍翠寒烟。群山映着斜阳蓝天连着江水。芳草不谙人情，一直延绵到夕阳照不到的天边。\n默默思念故乡黯然神伤，缠人的羁旅愁思难以排遣，除非夜夜都做好梦才能得到片刻安慰。不想在明月夜独倚高楼望远，只有频频地将苦酒灌入愁肠，化作相思的眼泪。', poem_notes = '苏幕遮：原唐教坊曲名，来自西域，后用作词牌名。又名“云雾敛”“鬓云松令”。双调，六十二字，上下片各五句。\n“波上”句：江波之上笼罩着一层翠色的寒烟。烟本呈白色，因其上连碧天，下接绿波，远望即与碧天同色，正所谓“秋水共长天一色”。\n“芳草”二句：意思是，草地绵延到天涯，似乎比斜阳更遥远。“芳草”常暗指故乡，因此，这两句有感叹故乡遥远之意。\n黯乡魂：因思念家乡而黯然伤神。黯，形容心情忧郁。乡魂，即思乡的情思。语出江淹 《别赋》：“黯然销魂者，唯别而已矣。“\n追旅思（sì）：撇不开羁旅的愁思。追，追随，这里有缠住不放的意思。旅思，旅居在外的愁思。思，心绪，情怀。', poem_appreciation = '这首词抒写了羁旅乡思之情，题材基本上不脱传统的离愁别恨的范围，但意境的阔大却为这类词所少有。\n\n　　上片写秾丽阔远的秋景，暗透乡思。起首“碧云天，黄叶地”两句，即从大处落笔，浓墨重彩，展现出一派长空湛碧、大地橙黄的高远境界，而无写秋景经常出现的衰飒之气。\n\n　　“秋色连波，波上寒烟翠”两句，从碧天广野到遥接天地的秋水。秋色，承上指碧云天、黄叶地。这湛碧的高天、金黄的大地一直向远方伸展，连接着天地尽头的淼淼秋江。江波之上，笼罩这一层翠色的寒烟。烟霭本呈白色，但由于上连碧天，下接绿波，远望即与碧天同色而莫辩，如所谓“秋水共长天一色”，所以说“寒烟翠”。“寒”字突出了这翠色的烟霭给与人的秋意感受。这两句境界悠远，与前两句高广的境界互相配合，构成一幅极为辽阔而多彩的秋色图。\n\n　　“山映斜阳天接水，芳草无情，更在斜阳外。”傍晚，夕阳映照着远处的山峦，碧色的遥天连接这秋水绿波，凄凄芳草，一直向远处延伸，隐没在斜阳映照不到的天边。这三句进一步将天、地、山、水通过斜阳、芳草组接在一起，景物自目之所及延伸到想象中的天涯。这里的芳草，虽未必有明确的象喻意义，但这一意象确可引发有关的联想。自从《楚辞·招隐士》写出了“王孙游兮不归，春草生兮萋萋”以后，在诗词中，芳草就往往与乡思别情相联系。这里的芳草，同样是乡思离情的触媒。它遥接天涯，远连故园，更在斜阳之外，使瞩目望乡的客子难以为情，而它却不管人的情绪，所以说它“无情”。到这里，方由写景隐逗出乡思离情。\n\n　　整个上片所写的阔远秾丽、毫无衰飒情味的秋景，在文人的笔下是少见的，在以悲秋伤春为常调的词中，更属罕见。而悠悠乡思离情，也从芳草天涯的景物描写中暗暗透出，写来毫不着迹。这种由景及情的自然过渡手法也很高妙。\n\n　　过片紧承芳草天涯，直接点出“乡魂”“旅思”。“乡魂”与“旅思”意思相近。两句是说自己思乡的情怀黯然凄怆，羁旅的愁绪重叠相续。上下互文对举，带有强调的意味，而主人公羁泊异乡时间之久与乡思离愁之深自见。\n\n　　“夜夜除非，好梦留人睡”，九字作一句读。说“除非”，足见只有这个，别无他计。言外之意是说，好梦做得很少，长夜不能入眠。这就逗出下句：“明月高楼休独倚。”月明中正可倚楼凝思，但独倚明月映照下的高楼，不免愁怀更甚，不由得发出“休独倚”的慨叹。从“斜阳”到“明月”，显示出时间的推移，而主人公所处的地方依然是那座高楼，足见乡思离愁之深重。“楼高”“独倚”点醒上文，暗示前面所写的都是倚楼所见。这样写法，不仅避免了结构与行文的平直，而且使上片的写景与下片的抒情融为一体。\n\n　　“酒入愁肠，化作相思泪。”因为夜不能寐，故借酒浇愁，但酒一入愁肠都化作了相思泪，这真是欲遣乡思反而更增乡思之苦了。结拍两句，抒情深刻，造语生新。作者另一首《御街行·纷纷坠叶飘香砌》则翻进一层，说：“愁肠已断无由醉，酒未到，先成泪。”写得似更奇警深至，但微有做作态，不及这两句自然。写到这里，郁积的乡思旅愁在外物的触发下发展到高潮，词也就在这难以为怀的情绪中黯然收束。\n\n　　这首词上片写景，下片抒情，这本是词中常见的结构和情景结合的方式，其特殊性在于丽景与柔情的统一，更准确地说，是阔远之境、秾丽之景、深挚之情的统一。写乡思离愁的词，往往借萧瑟的秋景来表达，这首词所描绘的景色却阔远而秾丽。它一方面显示了词人胸襟的广阔和对生活对自然的热爱，反过来衬托了离情的可伤，另一方面又使下片所抒之情显得柔而有骨，深挚而不流于颓靡。整体说来，这首词的用语与手法虽与一般的词类似，意境情调却近于传统的诗。这说明，抒写离愁别恨的小词是可以写得境界阔远，不局限于闺阁庭院。', poem_tags = '宋词三百首,宋词精选,婉约,秋天,写景,怀旧,思念' WHERE poem_title = '苏幕遮·怀旧' AND poem_author = '范仲淹';
UPDATE edu_poem SET poem_translation = '小时候不认识月亮， 把它称为白玉盘。\n又怀疑是瑶台仙镜，飞在夜空青云之上。\n月中的仙人是垂着双脚吗？月中的桂树为什么长得圆圆的？\n白兔捣成的仙药，到底是给谁吃的呢？\n蟾蜍把圆月啃食得残缺不全，皎洁的月儿因此晦暗不明。\n后羿射下了九个太阳，天上人间免却灾难清明安宁。\n月亮已经沦没而迷惑不清，没有什么可看的不如远远走开吧。\n心怀忧虑啊又何忍一走了之，凄惨悲伤让我肝肠寸断。\n\n韵译\n小时不识天上明月，把它称为白玉圆盘。怀疑它是瑶台仙镜，飞在夜空青云上边。\n月中仙人垂下双脚？月中桂树多么圆圆！白兔捣成不老仙药，借问一声给谁用餐？\n蟾蜍食月残缺不全，皎洁月儿因此晦暗。后羿射落九个太阳，天上人间清明平安。\n月亮沦没迷惑不清，不值观看想要离开。心怀忧虑不忍远去，凄惨悲伤肝肠寸断。', poem_notes = '呼作：称为。\n白玉盘：指晶莹剔透的白盘子。\n疑：怀疑。\n瑶台：传说中神仙居住的地方。出处：《穆天子传》卷三：“天子宾于西王母，天子觞西王母于瑶池之上。西王母为天子谣曰：‘白云在天，山陵自出。道里悠远，山川间之。将子无死，尚能复来。’天子答之曰：‘予归东土，和治诸夏。万民平均，吾顾见汝。比及三年，将复而野。’”《武帝内传》称王母为“玄都阿母”。\n仙人垂两足：意思是月亮里有仙人和桂树。当月亮初生的时候，先看见仙人的两只脚，月亮渐渐圆起来，就看见仙人和桂树的全形。仙人，传说驾月的车夫，叫舒望，又名纤阿。\n团团：圆圆的样子。\n白兔捣药成，问言与谁餐：白兔老是忙着捣药，究竟是给谁吃呢？言外有批评长生不老药之意。问言，问。言，语助词，无实意。与谁，一作“谁与”\n蟾蜍：《五经通义》：“月中有兔与蟾蜍。”蟾蜍，传说月中有三条腿的蟾蜍，因此古诗文常以“蟾蜍”指代月亮。但本诗中蟾蜍则另有所指。\n圆影：指月亮。\n羿：我国古代神话中射落九个太阳的英雄。《淮南子·本经训》记载：尧时十日并出，草木皆枯。尧命羿仰射十日，中其九。下面的“乌”即日，《五经通义》：“日中有三足乌。”所以日又叫阳乌。\n天人：天上人间。\n阴精：《史记·天官书》：“月者，天地之阴，金之精也。”阴精也指月。\n沦惑：沉沦迷惑。\n去去：远去，越去越远。\n凄怆：悲愁伤感。', poem_appreciation = '这是一首乐府诗。“朗月行”，是乐府古题，属《杂曲歌辞》。\n\n　　李白有《古朗月行》　鲍照有《朗月行》，写佳人对月弦歌。李白采用这个题目，故称《古朗月行》，但没有因袭旧的内容。诗人运用浪漫主义的创作方法，通过丰富的想象，神话传说的巧妙加工，以及强烈的抒情，构成瑰丽神奇而含意深蕴的艺术形象。诗中先写儿童时期对月亮稚气的认识：“小时不识月，呼作白玉盘。又疑瑶台镜，飞在青云端。”以“白玉盘”、“瑶台镜”作比喻，生动地表现出月亮的形状和月光的皎洁可爱，使人感到非常新颖有趣。“呼”、“疑”这两个动词，传达出儿童的天真烂漫之态。这四句诗，看似信手写来，却是情采俱佳。然后，又写月亮的升起：“仙人垂两足，桂树何团团？白兔捣药成，问言与谁餐？”古代神话说，月中有仙人、桂树、白兔。当月亮初升的时候，先看见仙人的两只脚，而后逐渐看见仙人和桂树的全形，看见一轮圆月，看见月中白兔在捣药。诗人运用这一神话传说，写出了月亮初生时逐渐明朗和宛若仙境般的景致。然而好景不长，月亮渐渐地由圆而蚀：“蟾蜍蚀圆影，大明夜已残。”蟾蜍，俗称癞蛤蟆；大明，指月亮。传说月蚀就是蟾蜍食月所造成，月亮被蟾蜍所啮食而残损，变得晦暗不明。“羿昔落九乌，天人清且安”，表现出诗人的感慨和希望。古代善射的后羿，射落了九个太阳，只留下一个，使天、人都免除了灾难。诗人在这里引出这样的英雄来，既是为现实中缺少这样的英雄而感慨，也是希望能有这样的英雄来扫除天下。然而，现实毕竟是现实，诗人深感失望：“阴精此沦惑，去去不足观。”月亮既然已经沦没而迷惑不清，就没有什么可看的了，不如趁早走开吧。这是无可奈何的办法，心中的忧愤不仅没有解除，反而加深了：“忧来其如何？凄怆摧心肝。”诗人不忍一走了之，内心矛盾重重，忧心如焚。\n\n　　这首诗，大概是李白针对当时朝政黑暗而发的。唐玄宗晚年沉湎声色，宠幸杨贵妃，权奸、宦官、边将擅权，把国家搞得乌烟瘴气。诗中“蟾蜍蚀圆影，大明夜已残”似是讽刺这一昏暗局面。沈德潜说，这是“暗指贵妃能惑主听”。（《唐诗别裁》）然而诗人的主旨却不明说，而是通篇作隐语，化现实为幻景，以蟾蜍蚀月影射现实，说得十分深婉曲折。诗中一个又一个新颖奇妙的想象，展现出诗人起伏不平的感情，文辞如行云流水，富有魅力，发人深思，体现出李白诗歌的雄奇奔放、清新俊逸的风格。', poem_tags = '乐府,月亮,抒情' WHERE poem_title = '古朗月行' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '山坡田野间草木茂盛，稻田里的水色与天光相辉映。天空中烟雨蒙蒙，杜鹃声声啼叫，大地一片欣欣向荣的景象。\n四月到了，没有人闲着，刚刚结束了蚕桑的事又要插秧了。', poem_notes = '山原：山陵和原野。白满川：指稻田里的水色映着天光。川：平地。\n子规：鸟名，杜鹃鸟。\n才了：刚刚结束。蚕桑：种桑养蚕。插田：插秧。', poem_appreciation = '赏析二 　　绿遍山原白满川，子规声里雨如烟。乡村四月闲人少，才了蚕桑又插田。这是一首田园诗，描写的是江浙一带乡村四月的风光。作者是南宋诗人，被称为“永嘉四灵”之一的翁卷。第一次读到这首诗，竟被它纯美的田园风光所迷醉：山坡上草木葳蕤，一片青葱翠绿。江南插禾早，蓄满水的稻田里水色与天光交相辉映，满目亮白。杜鹃声声啼叫，江南的天空烟雨迷蒙。四月到了，庄稼人都开始忙农活，没有一个闲人。庄稼活像稻草垛一样堆起多高，一件接着一件，哪有做完的时候？刚结束了蚕桑的事又要插秧了。还是喜欢陕南的四月天。在形色上，它一点也不比江南差。比起翁卷的家乡来，我的家乡陕南的物候总要迟二十天左右。那是一个正在发育的夏天，像一个刚刚长大的女孩，一件件脱去青涩和单薄的外衣，骤然间显得丰满、成熟和性感。立夏一过，阳光一天比一天明媚，熏风一天比一天柔软，天空像复写纸一样的蓝。放眼望乡村，满眼是绿色，每一棵草都在开花，每一棵苗都在拔节。这时候，油菜和小麦还长在田地里，离收割还有一段时间，蚕豆和樱桃却早已摆上了农家的餐桌。芬芳的槐花一串串挂在窗外，装饰着露水明亮的家园。做秧田是一件细致活，得投进去技术和时间。正开花的紫云英被翻埋进田土里，再引来渠水沤田。阳光加热了满田的水，发酵了泥土里的生命，直到田泥变得无比柔软。这时候，退去一部分肥水，再将软泥做成一畦畦的温床，撒上草灰后再抹平。稻种的生命起初只是针尖大的一星点，在温室里长出两片叶子后方可移栽。那种农活叫“栽小秧”，是将一棵棵的小秧苗轻轻地摁进秧畦里去。栽小秧的时候，全家总动员，一幅又一幅点彩派的画作在田地里展开。最后别忘了在田头插个稻草人。麻雀嘴馋，它们虽然对那些已经生根发芽的小秧无技可施，但还得提防它们饥不择食地糟践。接下来，等待秧苗青麦子黄，割了麦子好插秧。那是一段暂时无事可做的时间，是大会战之前相对宁静的时刻。不妨到城里逛半天，归途中男人手里攥一把新买的镰刀，头上戴一顶簇新的草帽，女人腋下是一件新买的夏衣。下雨的时候，男人打了雨伞去串门，或者干脆在家睡懒觉；老人在屋檐下搓草绳，望着满天乌云盼天晴；女人在厨房里煮腊肉，裹挟着肉香的炊烟和迷蒙的雨雾永远纠缠不清。雨雾挡住我眺望远方的视线，却又将我的思念发酵到浓郁。妈妈这时候应该又在给我们做鞋垫吧，这是她每年四月坐在乡村滴雨的屋檐下必定要做的功课。她老人家这些年视力大不如前了，可勤劳的品质使她一直不肯浪费每一寸光阴。她搬个凳子坐在屋檐下，地上放个针线笸箩，伴着檐滴的声音扎进一针又一针，针针是对儿孙的牵挂和叮咛——她试图使我们的行走更加平稳和舒适。她在心里计划着哪四双是给我儿子的，哪两双是给我的，哪一双是给我媳妇的。她清楚地记得我们每一个人身体的尺码，而我们至今不知道她究竟穿多大的鞋。最喜欢是还是那句“子规声里雨如烟”。乡村四月，挥之不去的是愁情。　 ▲', poem_tags = '古诗三百首,小学古诗,乡村,劳动,生活,古诗里的十二个月' WHERE poem_title = '乡村四月' AND poem_author = '翁卷';
UPDATE edu_poem SET poem_translation = '人年少时不知道忧愁的滋味，喜欢登高远望。喜欢登高远望，为写一首新词无愁而勉强说愁。\n现在尝尽了忧愁的滋味，想说却说不出。想说却说不出，却说好一个凉爽的秋天啊！', poem_notes = '丑奴儿：词牌名。\n博山：在今江西省广丰县西南。因状如庐山香炉峰，故名。淳熙八年（1181）辛弃疾罢职退居上饶，常过博山。\n少年：指年轻的时候。不识：不懂，不知道什么是。\n“为赋”句：为了写出新词，没有愁而硬要说有愁。强（qiǎng）：勉强地，硬要。\n识尽：尝够，深深懂得。\n欲说还（huán）休：表达的意思可以分为两种：1.男女之间难于启齿的感情。2.内心有所顾虑而不敢表达。\n休：停止。', poem_appreciation = '全词通过回顾少年时不知愁苦，衬托“而今”深深领略了愁苦的滋味，却又说不出道不出，写出两种截然不同的思想感情的变化。\n\n　　上片说，少年时代思想单纯，没有经历过人世艰辛，喜欢登上高楼（层楼），赏玩景致，本来没有愁苦可言，但是“为赋新词”，只好装出一副斯文样子，勉强写一些“愁苦”的字眼应景。上片生动地写出少年时代纯真幼稚的感情。“不识”写少年人根本“不知道”什么是“愁”，十分真切。\n\n　　下片笔锋一转，写出历尽沧桑，饱尝愁苦滋味之后，思想感情的变化。“识尽愁滋味”概括了作者半生的经历，积极抗金，献谋献策，力主恢复中原，这些不仅未被朝廷重视，反而遭受投降派的迫害、打击。他这“愁”郁结心头已久，是很想对人倾诉一番，求得别人的同情和支持的，但是一想到朝廷昏庸黑暗，投降派把持政权，说了也于事无补，就不再说了。“欲说还休”深刻地表现了作者这种痛苦矛盾的心情，悲愤愁苦溢于言表。值得注意的是，“欲说还休”四字重复出现，用迭句的形式渲染了“有苦无处诉”的气氛，加强了艺术效果，使读者体会到，作者为国事忧愁，极端痛苦，竟至不能对人诉说，这是因为“恐言未脱口而祸不旋踵”（辛弃疾：《论盗赋札子》），作者实在有难言的苦衷啊！怎么办呢？只好“顾左右而言它”，“却道天凉好个秋”句，意思就是说作者无可奈何，只得回避不谈，说些言不由衷的话聊以应景！\n\n　　此词构思巧妙，写少年时无愁“强说愁”和谙练世故后满怀是愁却又故意避而不谈，生动真切。此词上下片里的“愁”含义是不尽相同的。“强说”的是春花秋月无病呻吟的闲愁；下片说的是关怀国事，怀才不遇的哀愁。\n\n　　在平易浅近的语句中，表现出作者内心深处的痛楚和矛盾，包含着深沉、忧郁、激愤的感情，说明辛词具有意境阔大，内容含量丰富的特色。\n\n　　上片：描绘出少年涉世未深，纯真无知故作深沉的情态\n\n　　下片：写出词人满腹愁苦却无处倾诉的抑郁，显示了词人深沉的愁苦', poem_tags = '宋词三百首,宋词精选,婉约,写人,少年,抒怀,愁苦' WHERE poem_title = '丑奴儿·书博山道中壁' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '最是喜爱涧边生长的幽幽野草，还有那树丛深处婉转啼唱的黄鹂。\n春潮不断上涨，还夹带着密密细雨。荒野渡口无人，只有一只小船悠闲地横在水面。', poem_notes = '⑴滁州：在今安徽滁州以西。西涧：在滁州城西，俗名称上马河。　\n⑵独怜：唯独喜欢。幽草：幽谷里的小草。幽，一作“芳”。生：一作“行”。\n⑶深树：枝叶茂密的树。深，《才调集》作“远”。树，《全唐诗》注“有本作‘处’”。\n⑷春潮：春天的潮汐。\n⑸野渡：郊野的渡口。横：指随意飘浮。', poem_appreciation = '滁州，治所在今安徽滁县。西涧，在滁州城西，俗名上马河。此诗作于唐德宗建中二年(781)，时韦应物出任滁州刺史。\n\n　　诗写暮春景物。“独怜幽草涧边生，上有黄鹂深树鸣“。开头二句是写日间所见。暮春之际，群芳已过，诗人闲行至涧，但见一片青草萋萋。幽草，虽然不及百花妩媚娇艳，但它那青翠欲滴的身姿，那自甘寂寞、不肯趋时悦人的风标， 自然而然地赢得了诗人的喜爱。这里，“独怜“二字，感情色彩至为浓郁，是诗人别有会心的感受。它表露了作者闲适恬淡的心境。王安石有“绿阴幽草胜花时“之句，写初夏之景，与此同一立意。首句，写静;次句，则写动。莺啼婉啭，在树丛深处间关滑动。莺啼似乎打破了刚才的沉寂和悠闲，其实在诗人静谥的心田荡起更深一层涟漪。次句前头着一“上“字，不仅仅是写客观景物的时空转移，重要的是写出了诗人随缘自适、怡然自得的开朗和豁达。\n\n　　接下来两句，侧重写荒津野渡之景。景物虽异，但仍然循此情愫作展衍:“春潮带雨晚来急，野渡无人舟自横“。到傍晚时分，春潮上涨，春雨淅沥，西涧水势顿见湍急。郊野渡口，本来就荒凉冷漠，此刻愈发难觅人踪。只有空舟随波纵横。二句诗所描绘的情境，未免有些荒凉，但用一“自“字，却体现着悠闲和自得。韦应物为诗好用“自“字。“欲啭不啭意自娇“，此写莺啼。“恬然自安流“，此咏百川分流。这类“自“字皆可释为“自在““自然“之意，含有“自我欣赏“、“自我怜爱“的意蕴。“野渡“句当作如是解。舍此，便与一二句相悖谬了。\n\n　　这两句在结构安排上也很精当。“春潮带雨晚来急“，构成典型环境，与下文形成因果关系;“急“与“自“两字互为照应，准确地传达出诗人内心的情感意识，把客观景物和抒情主体有机地融为一体。状出难写之景，达出难言之情。\n\n　　旧注以为这首诗有政治寄托，说是写“君子在下，小人在上之象“，过于穿凿附会，难以自圆其说。', poem_tags = '唐诗三百首,初中古诗,写景,山水,抒情' WHERE poem_title = '滁州西涧' AND poem_author = '韦应物';
UPDATE edu_poem SET poem_translation = '你红润酥腻的手里，捧着盛上黄縢酒的杯子。满城荡漾着春天的景色，你却早已像宫墙中的绿柳那般遥不可及。春风多么可恶，欢情被吹得那样稀薄。满杯酒像是一杯忧愁的情绪，离别几年来的生活十分萧索。遥想当初，只能感叹：错，错，错！\n美丽的春景依然如旧，只是人却白白相思地消瘦。泪水洗尽脸上的胭脂红，又把薄绸的手帕全都湿透。满春的桃花凋落在寂静空旷的池塘楼阁上。永远相爱的誓言还在，可是锦文书信再也难以交付。遥想当初，只能感叹：莫，莫，莫！', poem_notes = '黄縢（téng）：酒名。或作“黄藤”。\n宫墙：南宋以绍兴为陪都，因此有宫墙。\n离索：离群索居的简括。\n浥（yì）：湿润。鲛绡（jiāo xiāo）：神话传说鲛人所织的绡，极薄，后用以泛指薄纱，这里指手帕。绡，生丝，生丝织物。\n池阁：池上的楼阁。\n山盟：旧时常用山盟海誓，指对山立盟，指海起誓。\n锦书：写在锦上的书信。', poem_appreciation = '这首词写的是陆游自己的爱情悲剧。\n\n　　词的上片通过追忆往昔美满的爱情生活，感叹被迫离异的痛苦，分两层意思。\n\n　　开头三句为上片的第一层，回忆往昔与唐氏偕游沈园时的美好情景：“红酥手，黄縢酒。满城春色宫墙柳。”虽说是回忆，但因为是填词，而不是写散文或回忆录之类，不可能把整个场面全部写下来，所以只选取一个场面来写，而这个场面，又只选取了一两个最富有代表性和特征性的情事细节来写。“红酥手”，不仅写出了唐氏为词人殷勤把盏时的美丽姿态，同时还有概括唐氏全人之美（包括她的内心美）的作用。然而，更重要的是，它具体而形象地表现出这对恩爱夫妻之间的柔情密意以及他们婚后生活的美满与幸福。第三句又为这幅春园夫妻把酒图勾勒出一个广阔而深远的背景，点明了他们是在共赏春色。而唐氏手臂的红润，酒的黄封以及柳色的碧绿，又使这幅图画有了明丽而又和谐的色彩感。\n\n　　“东风恶”数句为第二层，写词人被迫与唐氏离异后的痛苦心情。上一层写春景春情，无限美好，到这里突然一转，激愤的感情潮水一下子冲破词人心灵的闸门，无可遏止地宣泄下来。“东风恶”三字，一语双关，含蕴很丰富，是全词的关键所在，也是造成词人爱情悲剧的症结所在。本来，东风可以使大地复苏，给万物带来勃勃的生机，但是，当它狂吹乱扫的时候，也会破坏春容春态，下片所云“桃花落，闲池阁”，就正是它狂吹乱扫所带来的严重后果，因此说它“恶”。然而，它主要是一种象喻，象喻造成词人爱情悲剧的“恶”势力。至于陆母是否也包含在内，答案应该是不能否认的，只是由于不便明言，而又不能不言，才不得不以这种含蓄的表达方式出之。下面一连三句，又进一步把词人怨恨“东风”的心理抒写了出来，并补足一个“恶”字：“欢情薄。一怀愁绪，几年离索。”美满姻缘被迫拆散，恩爱夫妻被迫分离，使他们两人在感情上遭受巨大的折磨和痛苦，几年来的离别生活带给他们的只是满怀愁怨。这正如烂漫的春花被无情的东风所摧残而凋谢飘零。接下来，“错，错，错”，一连三个“错”字，连迸而出，是错误，是错落，更是错责，感情极为沉痛。但这到底是谁错了呢？是对自己当初“不敢逆尊者意”而终“与妇诀”的否定吗？是对“尊者”的压迫行为的否定吗？是对不合理的婚姻制度的否定吗？词人没有明说，也不便于明说，这枚“千斤重的橄榄”（《红楼梦》语）留给了读者来噙，来品味。这一层虽直抒胸臆，激愤的感情如江河奔泻，一气贯注；但又不是一泻无余，其中“东风恶”和“错，错，错”几句就很有味外之味。\n\n　　词的下片，由感慨往事回到现实，进一步抒写妻被迫离异的巨大哀痛，也分为两层。\n\n　　换头三句为第一层，写沈园重逢时唐氏的表现。“春如旧”承上片“满城春色”句而来，这又是此时相逢的背景。依然是从前那样的春日，但是，人却今非昔比了。以前的唐氏，肌肤是那样红润，焕发着青春的活力；而此时的她，经过“东风”的无情摧残，憔悴了，消瘦了。“人空瘦”句，虽说写的只是唐氏容颜方面的变化，但分明表现出“几年离索”给她带来的巨大痛苦。像词人一样，她也为“一怀愁绪”折磨着；像词人一样，她也是旧情不断，相思不舍。不然，就不会如此消瘦。写容颜形貌的变化来表现内心世界的变化，原是文学作品中的一种很常用的手法，而在“人”“瘦”之间加一个“空”字却另有深意。“使君自有妇，罗敷自有夫。”（《古诗·陌上桑》）从婚姻关系说，两人早已各不相干了，事已至此，那这个“瘦”就是白白为相思而折磨自己。著此一字，就把词人那种怜惜之情、抚慰之意、痛伤之感等等，全都表现了出来。“泪痕”句通过刻画唐氏的表情动作，进一步表现出此次相逢时她的心情状态。旧园重逢，念及往事，她不能不哭，不能不泪流满面。但词人没直接写泪流满面，而是用了白描的手法，写她“泪痕红浥鲛绡透”，显得更委婉，更沉着，也更形象，更感人。而一个“透”字，不仅见其流泪之多，亦见其伤心之甚。上片第二层写词人自己，用了直抒胸臆的手法；这里写唐氏时却改变了手法，只写了她容颜体态的变化和她痛苦的心情由于这一层所写的都是词人眼中看出的，所以又具有了“一时双情俱至”的艺术效果。可见词人，不仅深于情，而且深于言。\n\n　　词的最后几句，是下片的第二层，写词人与唐氏相遇以后的痛苦心情。“桃花落”两句与上片的“东风恶”句前后照应，又突出写景虽是写景，但同时也隐含出人事。桃花凋谢，园林冷落，这只是物事的变化，而人事的变化却更甚于物事的变化。像桃花一样美丽姣好的唐氏，也被无情的“东风”摧残折磨得憔悴消瘦了；词人自己的心境，也像“闲池阁”一样凄寂冷落了。一笔而兼有二意很巧妙，也很自然。下面又转入直接赋情：“山盟虽在，锦书难托。”这两句虽只寥寥八字，却很能表现出词人自己内心的痛苦之情。虽说自己情如山石，痴心不改，但是，这样一片赤诚的心意，却难以表达。明明在爱，却又不能去爱；明明不能去爱，却又割不断这爱缕情丝。刹那间，有爱，有恨，有痛，有怨，再加上看到唐氏的憔悴容颜和悲戚情状所产生的怜惜之情、抚慰之意，真是百感交集，万箭簇心，一种难以名状的悲哀，再一次冲胸破喉而出：“莫，莫，莫！”意谓：事已至此，再也无可补救、无法挽回了，这万千感慨还想它做什么，说它做什么？于是快刀斩乱麻：罢了，罢了，罢了！明明言犹未尽，意犹未了，情犹未终，却偏偏这么不了了之，而在极其沉痛的喟叹声中全词也就由此结束了。\n\n　　这首词始终围绕着沈园这一特定的空间来安排自己的笔墨，上片由追昔到抚今，而以“东风恶”转捩；过片回到现实，以“春如旧”与上片“满城春色”句相呼应，以“桃花落，闲池阁”与上片“东风恶”句相照应，把同一空间不同时间的情事和场景历历如绘地叠映出来。全词多用对比的手法，如上片，越是把往昔夫妻共同生活时的美好情景写得逼切如现，就越使得他们被迫离异后的凄楚心境深切可感，也就越显出“东风”的无情和可憎，从而形成感情的强烈对比。\n\n　　再如上片写“红酥手”，下片写“人空瘦”，在形象、鲜明的对比中，充分地表现出“几年离索”给唐氏带来的巨大精神折磨和痛苦。全词节奏急促，声情凄紧，再加上“错，错，错”和“莫，莫，莫”先后两次感叹，荡气回肠，大有恸不忍言、恸不能言的情致。\n\n　　总而言之，这首词达到了内容和形式的完美统一，是一首别开生面、催人泪下的作品。', poem_tags = '宋词三百首,宋词精选,追忆,感叹,爱情,感伤' WHERE poem_title = '钗头凤·红酥手' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '戍楼上的更鼓声隔断了人们的来往，边塞的秋天里，一只孤雁正在鸣叫。\n从今夜就进入了白露节气，月亮还是故乡的最明亮。\n有兄弟却都分散了，没有家无法探问生死。\n寄往洛阳城的家书常常不能送到，何况战乱频繁没有停止。', poem_notes = '舍弟：谦称自己的弟弟。\n戍鼓：戍楼上的更鼓。戍，驻防。\n断人行：指鼓声响起后，就开始宵禁。\n边秋：一作“秋边”，秋天的边地，边塞的秋天\n露从今夜白：指在气节“白露”的一个夜晚。\n有弟皆分散，无家问死生：弟兄分散，家园无存，互相间都无从得知死生的消息。\n长：一直，老是。\n达：到。\n况乃：何况是。\n未休兵：战争还没有结束。', poem_appreciation = '这首诗首联即突兀不平。题目是“月夜”，作者却不从月夜写起，而是首先描绘了一幅边塞秋天的图景：“戍鼓断人行，边秋一雁声。”路断行人，写出所见；戍鼓雁声，写出所闻。耳目所及皆是一片凄凉景象。沉重单调的更鼓和天边孤雁的叫声不仅没有带来一丝活气，反而使本来就荒凉不堪的边塞显得更加冷落沉寂。“断人行”点明社会环境，说明战事仍然频繁、激烈，道路为之阻隔。两句诗渲染了浓重悲凉的气氛，点明“月夜”的背景。\n\n　　颔联点题。“露从今夜白”，既写景，也点明时令。那是在白露节的夜晚，清露盈盈，令人顿生寒意。“月是故乡明”，也是写景，却与上句略有不同。作者所写的不完全是客观实景，而是融入了自己的主观感情。明明是普天之下共一轮明月，本无差别，偏要说故乡的月亮最明；明明是作者自己的心理幻觉，偏要说得那么肯定，不容质疑。然而，这种以幻作真的手法却使人觉得合乎情理，这是因为它深刻地表现了作者微妙的心理，突出了对故乡的感怀。这两句在炼句上也很见功力，它要说的不过是“今夜露白”，“故乡月明”，只是将词序这么一换，语气便分外矫健有力。\n\n　　上两联信手挥写，若不经意，看似与忆弟无关，其实不然。不仅望月怀乡写出“忆”，就是闻戍鼓，听雁声，见寒露，也无不使作者感物伤怀，引起思念之情。所以是字字忆弟，句句有情。\n\n　　颈联由望月转入抒情，过渡十分自然。月光常会引人遐想，更容易勾起思乡之念。诗人今遭逢离乱，又在这清冷的月夜，更是别有一番滋味在心头。在他的绵绵愁思中夹杂着生离死别的焦虑不安，语气也分外沉痛。“有弟皆分散，无家问死生”，上句说弟兄离散，天各一方；下句说家已不存，生死难卜，写得伤心折肠，感人至深。这两句诗也概括了安史之乱中人民饱经忧患丧乱的普遍遭遇。\n\n　　尾联紧承颈联进一步抒发内心的忧虑之情。亲人们四处流散，平时寄书尚且常常不达，更何况战事频仍，生死茫茫当更难逆料。含蓄蕴藉，一结无限深情。\n\n　　全诗层次井然，首尾照应，承转圆熟，结构严谨。“未休兵”则“断人行”，望月则“忆舍弟”，“无家”则“寄书不达”，人“分散”则“死生”不明，一句一转，一气呵成。怀乡思亲之情凄楚哀感，沉郁顿挫。', poem_tags = '唐诗三百首,边塞,秋天,月夜,思乡,怀人' WHERE poem_title = '月夜忆舍弟' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '不要求见面只是希望通过拜贴来问候，因此我的屋中早上堆满了各种名贵的拜贴。\n我也随潮流向他人投送拜贴，人们只会嫌弃简慢，而不会嫌弃这其实只是空虚的礼节。', poem_notes = '谒：名帖。\n敝：用于与自己有关的事物。', poem_tags = '节日,春节' WHERE poem_title = '拜年' AND poem_author = '文征明';
UPDATE edu_poem SET poem_translation = '豆苗采了又采，薇菜刚刚冒出地面。说回家了回家了，但已到了年末仍不能实现。没有妻室没有家，都是为了和猃狁打仗。 没有时间安居休息，都是为了和猃狁打仗。\n\n豆苗采了又采，薇菜柔嫩的样子。说回家了回家了，心中是多么忧闷。忧心如焚，饥渴交加实在难忍。驻防的地点不能固定，无法使人带信回家。\n\n豆苗采了又采，薇菜的茎叶变老了。说回家了回家了，又到了十月小阳春。征役没有休止， 哪能有片刻安身。心中是那么痛苦，到如今不能回家。\n\n那盛开着的是什么花？是棠棣花。那驶过的是什么人的车？当然是将帅们的从乘。兵车已经驾起，四匹雄马又高又大。哪里敢安然住下？因为一个月多次交战！\n\n驾起四匹雄马，四匹马高大而又强壮。将帅们坐在车上，士兵们也靠它隐蔽遮挡。四匹马训练得已经娴熟，还有象骨装饰的弓和鲨鱼皮箭囊（指精良的装备）。怎么能不每天戒备呢？猃狁之难很紧急啊。\n\n回想当初出征时，杨柳依依随风吹。如今回来路途中，大雪纷纷满天飞。道路泥泞难行走，又饥又渴真劳累。满腔伤感满腔悲，我的哀痛谁体会！', poem_notes = '薇：豆科野豌豆属的一种，学名救荒野豌豆，又叫大巢菜，种子、茎、叶均可食用。《史记卷六十一 伯夷列传》记载：“武王已平殷乱，天下宗周，而伯夷、叔齐耻之，义不食周粟，隐于首阳山，采薇而食之。”说的是伯夷、叔齐隐居山野，义不仕周的故事。《史记 周本纪第四》记载：懿王之时，王室遂衰，诗人作刺。刺就是指《采薇》。《汉书·匈奴传》记载：至穆王之孙懿王时，王室遂衰，戎狄交侵，暴虐中国。中国被其苦，诗人始作，疾而歌之，曰：“‘靡室靡家，猃狁之故’，‘岂不日戒，猃狁孔棘’。”\n作：指薇菜冒出地面。\n止：句末助词，无实意。\n曰：句首、句中助词，无实意。\n莫：通“暮”，也读作“暮”。本文指年末。\n靡（mǐ）室靡家：没有正常的家庭生活。靡，无。室，与“家”义同。\n不遑（huáng）：不暇。遑，闲暇。\n启居：跪、坐，指休息、休整。启，跪、跪坐。居，安坐、安居。古人席地而坐，两膝着席，危坐时腰部伸直，臀部与足离开；安坐时臀部贴在足跟上。\n猃（xiǎn）狁（yǔn）：中国古代少数民族名。\n柔：柔嫩。“柔”比“作”更进一步生长。指刚长出来的薇菜柔嫩的样子。\n烈烈：炽烈，形容忧心如焚。\n载（zài）饥载渴：则饥则渴、又饥又渴。载……载……，即又……又……。\n戍（shù）：防守，这里指防守的地点。\n聘（pìn）：问候的音信。\n刚：坚硬。\n阳：农历十月，小阳春季节。今犹言“十月小阳春”。\n靡：无。\n盬（gǔ）：止息，了结。\n启处：休整，休息。\n孔：甚，很。\n疚：病，苦痛。\n我行不来：意思是：我不能回家。来，回家。（一说，我从军出发后，还没有人来慰问过）\n常：常棣（棠棣），既芣苡，植物名。\n路：高大的战车。斯何，犹言维何。斯，语气助词，无实义。\n君子：指将帅。\n小人：指士兵。\n戎（róng）：车，兵车。\n牡（mǔ）：雄马。\n业业：高大的样子。\n定居：犹言安居。\n捷：胜利。谓接战、交战。一说，捷，邪出，指改道行军。此句意谓，一月多次行军。\n骙（kuí）：雄强，威武。这里的骙骙是指马强壮的意思。\n腓（féi）：庇护，掩护。\n翼翼：整齐的样子。谓马训练有素。\n弭（mǐ）：弓的一种，其两端饰以骨角。一说弓两头的弯曲处。象弭，以象牙装饰弓端的弭。鱼服，鲨鱼鱼皮制的箭袋。\n日戒：日日警惕戒备。\n棘（jí）：急。孔棘，很紧急。\n昔：从前，文中指出征时。\n依依：形容柳丝轻柔、随风摇曳的样子。\n思：用在句末，没有实在意义　雨：音同玉，为 “下” 的意思。\n霏（fēi）霏：雪花纷落的样子。\n迟迟：迟缓的样子。\n往：当初从军。', poem_appreciation = '第一部分的三章采用重章叠句的形式，反复表达戍卒远别家室、历久不归的凄苦心情。这三章的第一句都是“采薇采薇”，以此来引起下文。诗歌的一开始就给读者展示了一幅凄凉的戍边生活画面，我们仿佛看到戍卒一边在荒野漫坡上采集野菜，一边思念着久别的家乡，屈指计算着返家的日期……第一章开头两句写道：“采薇采薇，薇亦作止”，这是写春天，薇菜刚刚绽出嫩绿的芽尖；第二章写道：“采薇采薇，薇亦柔止”，这是写夏天，薇菜的叶片肥嫩；第三章则是：“采薇采薇，薇亦刚止”，这是写秋天，薇菜的叶茎将老而粗硬。从春到秋，薇菜由嫩而老，时光无情地流逝了；戍卒思归，从春到秋，一年将尽，何时才能归家呢？其实在诗里，诗人原是把天地四时的瞬息变化，自然生物的生死消长，都看作是生命的见证，人生的比照。因此，兴是自然予人的最朴素也最直接的感悟，其中有着体认生命的深刻之义。于是在“采薇”这样一个凝固在戍卒记忆里的姿势里，看到的不只是四季的轮回，光阴的流逝，还看到思念的成长，看到生命走向苍老的痕迹。\n\n　　前三章的前后两层，同时交织着恋家思亲的个人情和为国赴难的责任感，这是两种互相矛盾又同样真实的思想感情。这样的豪迈和悲凉的交织构成了全诗的情感基调，只是思归的个人情愫和战斗的责任感，在不同的章节有不同的表现。\n\n　　四、五章追述行军作战的紧张生活。写出了军容之壮，戒备之严，全篇气势为之一振。其情调，也由忧伤的思归之情转而为激昂的战斗之情。这两章同样四句一意，可分四层读。四章前四句，诗人自问自答，以“维常之华”，兴起“君子之车”，流露出军人特有的自豪之情。接着围绕战车描写了两个战斗场面：“戎车既驾，四牡业业。岂敢定居，一月三捷。”这概括地描写了威武的军容、高昂的士气和频繁的战斗；“驾彼四牡，四牡骙骙。君子所依，小人所腓。”这又进而具体描写了在战车的掩护和将帅的指挥下，士卒们紧随战车冲锋陷阵的场面。最后，由战斗场面又写到将士的装备：“四牡翼翼，象弭鱼服。”战马强壮而训练有素，武器精良而战无不胜。将士们天天严阵以待，只因为猃狁实在猖狂，“岂不日戒，猃狁孔棘”，既反映了当时边关的形势，又再次说明了久戍难归的原因。而这两章的色调如此的华美，那密密层层的棠棣之花，雄俊高大的战马，威风凛凛的将军，华贵的弓箭，齐整的战车，这里洋溢着一种报效国家，不惜血酒疆场的豪放情怀。而在残酷战争之中无法把握自己的命运的悲哀，以及对遥远的故乡的浓得化不开的思念，这些阴暗的色调就在这里被冲淡了。因为当自己在战场上浴血奋战的时候，正因为身后有如此承载着自己的温暖思念的美丽的家园。\n\n　　从手法上说，这首诗的特点还在于选择了一个最佳角度，即“在路上”，这是一条世界上最远最长的路，它如此之长，长得足以承载一场战争，长得足以装满一个人年年岁岁的思念，长得足以盛满一个人生命中的苦乐悲欣。\n\n　　“昔我往矣，杨柳依依。今我来思，雨雪霏霏。”让那一股缠绵的、深邃的、飘忽的情思，从风景画面中自然流出，含蓄深永，味之无尽。这四句诗被后人誉为《诗经》中最好的句子。这是写景记时，更是抒情伤怀。这几句诗句里有着悲欣交集的故事，也仿佛是个人生命的寓言。是谁曾经在那个春光烂漫的春天里，在杨柳依依中送别我？而当我在大雪飘飞的时候经历九死一生返回的时候，还有谁在等我？是《木兰辞》里亲人欢迎的盛况，还是《十五从军征》里荒草萋萋的情景？别离时的春光，回归时的大雪，季节在变换，时光在流逝，我们离去，我们归来，而在来来去去里，失去了什么又得到了什么呢？没有答案，只有漫天的飞雪中一个被沉重的相思和焦虑烧灼的又饥又渴的征人孤独的身影，步履蹒跚地，战战兢兢地走向他不知道的未来。\n\n　　这一首诗与《诗经》中的其它篇章如《击鼓》《东山》《无衣》对读，可以读出更完整的故事，更真切的生命感受。如果我们可以想象，这个戍卒，是那位吟出“死生契阔，与子成悦。执子之手，与子偕老”的士兵，也是那唱着昂扬的战歌“岂曰无衣，与子同袍。王于兴师，修我戈矛，与子同行”的士兵，同时还是那位在蒙蒙的细雨里唱着归乡的“我徂东山，滔滔不归。我来自东，零雨其蒙”的士兵。那么，《采薇》的故事就更丰富了，事实上，这一首诗里的确有着太丰富的色彩，太深沉的情怀。相思之情与报国之志，豪放与苍凉如此和谐地交织在一起，奏响的是真实的生命乐章。在后来的如陈陶《陇西行》，如范仲淹的《渔家傲》等伟大的作品里，也能依稀地听到这首诗在时间和生命的河流里所激起的辽远而空旷的回音。', poem_tags = '古诗三百首,诗经,战争,思乡' WHERE poem_title = '采薇' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '黄初三年，我来到京都朝觐，归渡洛水。古人曾说此水之神名叫宓妃。因有感于宋玉对楚王所说的神女之事，于是作了这篇赋。赋文云：\n\n　　我从京都洛阳出发，向东回归封地鄄城，背着伊阙，越过轘辕，途经通谷，登上景山。这时日已西下，车困马乏。于是就在长满杜蘅草的岸边卸了车，在生着芝草的地里喂马。自己则漫步于阳林，纵目眺望水波浩渺的洛川。于是不觉精神恍惚，思绪飘散。低头时还没有看见什么，一抬头，却发现了异常的景象，只见一个绝妙佳人，立于山岩之旁。我不禁拉着身边的车夫对他说：“你看见那个人了吗？那是什么人，竟如此艳丽！”车夫回答说：“臣听说河洛之神的名字叫宓妃，然而现在君王所看见的，莫非就是她！她的形状怎样，臣倒很想听听。”\n\n　　我告诉他说：她的形影，翩然若惊飞的鸿雁，婉约若游动的蛟龙。容光焕发如秋日下的菊花，体态丰茂如春风中的青松。她时隐时现像轻云笼月，浮动飘忽似回风旋雪。远而望之，明洁如朝霞中升起的旭日；近而视之，鲜丽如绿波间绽开的新荷。她体态适中，高矮合度，肩窄如削，腰细如束，秀美的颈项露出白皙的皮肤。既不施脂，也不敷粉，发髻高耸如云，长眉弯曲细长，红唇鲜润，牙齿洁白，一双善于顾盼的闪亮的眼睛，两个面颧下甜甜的酒窝。她姿态优雅妩媚，举止温文娴静，情态柔美和顺，语辞得体可人。洛神服饰奇艳绝世，风骨体貌与图上画的一样。她身披明丽的罗衣，带着精美的佩玉。头戴金银翡翠首饰，缀以周身闪亮的明珠。她脚著饰有花纹的远游鞋，拖着薄雾般的裙裾，隐隐散发出幽兰的清香，在山边徘徊倘佯。忽然又飘然轻举，且行且戏，左面倚着彩旄，右面有桂旗庇荫，在河滩上伸出素手，采撷水流边的黑色芝草。\n\n　　我钟情于她的淑美，不觉心旌摇曳而不安。因为没有合适的媒人去说情，只能借助微波来传递话语。但愿自己真诚的心意能先于别人陈达，我解下玉佩向她发出邀请。可叹佳人实在美好，既明礼义又善言辞，她举着琼玉向我作出回答，并指着深深的水流以为期待。我怀着眷眷之诚，又恐受这位神女的欺骗。因有感于郑交甫曾遇神女背弃诺言之事，心中不觉惆怅、犹豫和迟疑，于是敛容定神，以礼义自持。\n\n　　这时洛神深受感动，低回徘徊，神光时离时合，忽明忽暗。她像鹤立般地耸起轻盈的躯体，如将飞而未翔；又踏着充满花椒浓香的小道，走过杜蘅草丛而使芳气流动。忽又怅然长吟以表示深沉的思慕，声音哀惋而悠长。于是众神纷至杂沓，呼朋引类，有的戏嬉于清澈的水流，有的飞翔于神异的小渚，有的在采集明珠，有的在俯拾翠鸟的羽毛。洛神身旁跟着娥皇、女英南湘二妃，她手挽汉水之神，为瓠瓜星的无偶而叹息，为牵牛星的独处而哀咏。时而扬起随风飘动的上衣，用长袖蔽光远眺，久久伫立；时而又身体轻捷如飞凫，飘忽游移无定。她在水波上行走，罗袜溅起的水沫如同尘埃。她动止没有规律，像危急又像安闲；进退难以预知，像离开又像回返。她双目流转光亮，容颜焕发泽润，话未出口，却已气香如兰。她的体貌婀娜多姿，令我看了茶饭不思。\n\n　　在这时风神屏翳收敛了晚风，水神川后止息了波涛，冯夷击响了神鼓，女娲发出清泠的歌声。飞腾的文鱼警卫着洛神的车乘，众神随着叮当作响的玉鸾一齐离去。六龙齐头并进，驾着云车从容前行。鲸鲵腾跃在车驾两旁，水禽绕翔护卫。车乘走过北面的沙洲，越过南面的山冈，洛神转动白洁的脖颈，回过清秀的眉目，朱唇微启，缓缓地陈诉着往来交接的纲要。只怨恨人神有别，彼此虽然都处在盛年而无法如愿以偿。说着不禁举起罗袖掩面而泣，止不住泪水涟涟沾湿了衣襟，哀念欢乐的相会就此永绝，如今一别身处两地，不曾以细微的柔情来表达爱慕之心，只能赠以明珰作为永久的纪念。自己虽然深处太阴，却时时怀念着君王。洛神说毕忽然不知去处，我为众灵一时消失隐去光彩而深感惆怅。\n\n　　于是我舍低登高，脚步虽移，心神却仍留在原地。余情绻缱，不时想象着相会的情景和洛神的容貌；回首顾盼，更是愁绪萦怀。满心希望洛神能再次出现，就不顾一切地驾着轻舟逆流而上。行舟于悠长的洛水以至忘了回归，思恋之情却绵绵不断，越来越强，以至整夜心绪难平无法入睡，身上沾满了浓霜直至天明。我不得已命仆夫备马就车，踏上向东回返的道路，但当手执马缰，举鞭欲策之时，却又怅然若失，徘徊依恋，无法离去。', poem_notes = '洛神：传说古帝宓（fú）羲氏之女溺死洛水而为神，故名洛神，又名宓妃。\n黄初：魏文帝曹丕年号，公元—年。\n京师：京城，指魏都洛阳。\n济：渡。洛川：即洛水，源出陕西，东南入河南，流经洛阳。\n斯水：此水，指洛川。\n宋玉对楚王神女之事：传为宋玉所作的《高唐赋》和《神女赋》，都记载宋玉与楚襄王对答梦遇巫山神女事。\n京域：京都地区，指洛阳。\n言：语助词。东藩：东方藩国，指曹植的封地。黄初三年，曹植被立为鄄（juàn）城（即今山东鄄城县）王，城在洛阳东北方向，故称东藩。\n伊阙：山名，又称阙塞山、龙门山，在河南洛阳南。\n轘（huán）辕：山名，在今河南偃师县东南。\n通谷：山谷名。在洛阳城南。\n陵：登。景山：山名，在今偃师县南。\n殆：通“怠”，懈怠。一说指危险。烦：疲乏。\n尔乃：承接连词，于是就。税驾：停车。税，舍、置。驾，车乘总称。蘅皋：生着杜蘅的河岸。蘅，杜蘅，香草名。皋，岸。\n秣驷：喂马。驷，一车四马，此泛指驾车之马。芝田：种着灵芝草的田地，此处指野草繁茂之地。一说为地名，指河南巩县西南的芝田镇。\n容与：悠然安闲貌。阳林：地名。\n流眄：纵目四望。眄，斜视。一作“流盼”，目光流转顾盼。\n精移神骇：神情恍惚。骇，散。\n忽焉：急速貌。思散：思绪分散，精神不集中。\n殊观：少见的异常现象。\n岩之畔：山岩边。\n援：以手牵引。御者：车夫。\n觌（dí）：看见。\n“翩若”二句：翩然若惊飞的鸿雁，蜿蜒如游动的蛟龙。翩，鸟疾飞的样子，此处指飘忽摇曳的样子。惊鸿，惊飞的鸿雁。婉，蜿蜒曲折。这两句是写洛神的体态轻盈宛转。\n“荣曜（yào）”二句：容光焕发如秋日下的菊花，体态丰茂如春风中的松树。荣，丰盛。曜，日光照耀。华茂，华美茂盛。这两句是写洛神容光焕发充满生气。\n“仿佛”二句：时隐时现象轻云遮住月亮，浮动飘忽似回风旋舞雪花。仿佛，若隐若现的样子。飘飖，飞翔貌。回，回旋，旋转。这两句是写洛神的体态婀娜，行动飘忽。\n皎：洁白光亮。太阳升朝霞：太阳升起于朝霞之中。\n迫：靠近。灼：鲜明，鲜艳。芙蕖：一作“芙蓉”，荷花。渌（lù）：水清貌。以上两句是说，不论远远凝望还是靠近观看，洛神都是姿容绝艳。\n秾：花木繁盛。此指人体丰腴。纤：细小。此指人体苗条。\n修短：长短，高矮。以上两句是说洛神的高矮肥瘦都恰到好处。\n“肩若”二句：肩窄如削，腰细如束。削成，形容两肩瘦削下垂的样子。约素，一束白绢。素，白细丝织品。这两句是写洛神的肩膀和腰肢线条圆美。\n延、秀：均指长。颈：脖子的前部。项：脖子的后部。\n皓：洁白。呈露：显现，外露。\n“芳泽”二句：既不施脂，也不敷粉。泽，润肤的油脂。铅华，粉。古代烧铅成粉，故称铅华。不御，不施。御，用。\n云髻：发髻如云。峨峨：高耸貌。\n联娟：微曲貌。\n“丹唇”二句：红唇鲜润，牙齿洁白。朗，明润。鲜，光洁。\n眸：目中瞳子。睐（lài）：顾盼。\n靥（yè）：酒窝。辅：面颊。承权：在颧骨之下。权，颧骨。\n瓌：同“瑰”，奇妙。艳逸：艳丽飘逸。\n仪：仪态。闲：娴雅。\n绰：绰约，美好。\n奇服：奇丽的服饰。旷世：举世唯有。旷，空。\n骨像：骨格形貌。应图：指与画中人相当。\n璀粲：鲜明貌。一说为衣动的声音。\n珥：珠玉耳饰。此用作动词，作佩戴解。瑶、碧：均为美玉。华琚：刻有花纹的佩玉。琚：佩玉名。\n翠：翡翠。首饰：指钗簪一类饰物。\n践：穿，着。远游：鞋名。文履：饰有花纹图案的鞋。\n曳：拖。雾绡：轻薄如雾的绡。绡，生丝。裾：裙边。\n微：轻微。芳蔼：香气。\n踟蹰：徘徊。隅：角。\n“于是”二句：忽然又飘然轻举，且行且戏。纵体，身体轻举貌。遨，游。\n采旄（máo）：彩旗。采，同“彩”。旄，旗竿上旄牛尾饰物，此处指旗。\n桂旗：以桂木做旗竿的旗，形容旗的华美。\n攘：此指挽袖伸出。神浒：为神所游之水边地。浒，水边泽畔。\n湍濑：石上急流。玄芝：黑色芝草，相传为神草。\n“余情”二句：我喜欢她的淑美，又担心不被接受，不觉心旌摇曳而不安。振荡，形容心动荡不安。怡，悦。\n“无良媒”二句：没有合适的媒人去通接欢情，就只能借助微波来传递话语。微波，一说指目光。\n诚素：真诚的情意。素，同“愫”，情愫。\n要：同“邀”，约请。\n信修：确实美好。修，美好。\n羌：发语词。习礼：懂得礼法。明诗：善于言辞。这句意指有很好的文化教养。\n抗：举起。琼珶（dì）：美玉。和：应答。\n“指潜川”句：指深水发誓，约期相会。潜川，深渊，一说指洛神所居之地。期，会。\n眷眷：依恋貌。款实：诚实。\n斯灵：此神，指宓妃。我欺：即欺我。\n交甫：郑交甫。《文选》李善注引《神仙传》：“切仙一出，游于江滨，逢郑交甫。交甫不知何人也，目而挑之，女遂解佩与之。交甫行数步，空怀无佩，女亦不见。”弃言：背弃承诺。\n狐疑：疑虑不定。因为想到郑交甫曾经被仙女遗弃，故此内心产生了疑虑。\n收和颜：收起和悦的容颜。静志：镇定情志。\n申：施展。礼防：礼法，礼能防乱，故称礼防。自持：自我约束。\n徙倚：留连徘徊。\n“神光”二句：洛神身上放出的光彩忽聚忽散，忽明忽暗。\n竦（sǒng）：耸。鹤立：形容身躯轻盈飘举，如鹤之立。\n椒途：涂有椒泥的道路，一说指长满香椒的道路。椒，花椒，有浓香。\n蘅薄：杜蘅丛生地。流芳：散发香气。\n“超长吟”二句：怅然长吟以表示深沉的思慕，声音哀惋而悠长。超，惆怅。永慕，长久思慕。厉，疾。弥，久。\n众灵：众仙。杂沓：纷纭，多而乱的样子。\n命俦啸侣：招呼同伴。俦，伙伴、同类。\n渚：水中高地。\n翠羽：翠鸟的羽毛。\n南湘之二妃：指娥皇和女英。据刘向《列女传》载，尧以长女娥皇和次女女英嫁舜，后舜南巡，死于苍梧。二妃往寻，自投湘水而死，为湘水之神。\n汉滨之游女：汉水之女神，即前注中郑交甫所遇之神女。\n“叹匏瓜”二句：为匏瓜星的无偶而叹息，为牵牛星的独处而哀咏。匏瓜，星名，又名天鸡，在河鼓星东。无匹，无偶。牵牛，星名，又名天鼓，与织女星各处天河之旁。相传每年七月七日才得一会。\n袿（guī）：妇女的上衣。猗（yī）靡：随风飘动貌。\n翳（yì）：遮蔽。延伫：久立。\n凫：野鸭。\n“凌波”二句：在水波上细步行走，溅起的水沫附在罗袜上如同尘埃。凌，踏。尘，指细微四散的水沫。\n难期：难料。\n“转眄”句：转眼顾盼之间流露出奕奕神采。流精，形容目光流转而有光彩。\n“气若”句：形容气息香馨如兰。\n屏翳：传说中的众神之一，司职说法不一，或以为是云师，或以为是雷师，或以为是雨师，在此篇中被曹植视作风神。川后：传说中的河神。\n冯（píng）夷：传说中的水神。\n女娲：女神名，相传笙簧是她所造，所以这里说“女娲清歌”。\n“腾文鱼”二句：飞腾的文鱼警卫着洛神的车乘，众神随着叮当作响的玉鸾一齐离去。腾，升。文鱼，神话中一种能飞的鱼。警乘，警卫车乘。玉銮，鸾鸟形的玉制车铃，动则发声。偕逝，俱往。\n六龙：相传神出游多驾六龙。俨：庄严的样子。齐首：六龙齐头并进。\n云车：相传神以云为车。容裔：即“容与”，舒缓安详貌。\n鲸鲵（ní）：即鲸鱼。水栖哺乳动物，雄者称鲸，雌者称鲵。毂（gǔ）：车轮中用以贯轴的圆木，这里指车。\n沚：水中小块陆地。\n“纡素领”二句：洛神不断回首顾盼。纡，回。素领，白皙的颈项。清扬，形容女性清秀的眉目。\n交接：结交往来。\n盛年：少壮之年。莫当：无匹，无偶，即两人不能结合。\n“抗罗袂”二句：举起罗袖掩面而泣，止不住泪水涟涟沾湿了衣襟。抗，举。袂，衣袖。浪浪，水流不断貌。\n“悼良会”二句：痛惜这样美好的相会永不再有，哀叹长别从此身处两地。\n效爱：致爱慕之意。\n明珰：以明月珠作的耳珰。\n“虽潜”二句：虽然幽居于神仙之所，但将永远怀念着君王。潜处，深处，幽居。太阴，众神所居之处。君王，指曹植。\n“忽不悟”二句：洛神说毕忽然不知去处，我为众灵一时消失隐去光彩而深感惆怅。不悟，不见，未察觉。所舍，停留、止息之处。宵，通“消”，消失。蔽光，隐去光彩。\n背下：离开低地。陵高：登上高处。\n遗情：留情，情思留连。想象：指思念洛神的美好形象。\n灵体：指洛神。\n上溯：逆流而上。\n长川：指洛水。\n耿耿：心神不安的样子。\n“揽騑辔”二句：当手执马缰，举鞭欲策之时，却又怅然若失，徘徊依恋，无法离去。騑（fēi），车旁之马。古代驾车称辕外之马为騑或骖，此泛指驾车之马。辔，马缰绳。抗策，犹举鞭。盘桓，徘徊不进貌。', poem_appreciation = '曹植在诗歌和辞赋创作方面有杰出成就，其赋继承两汉以来抒情小赋的传统，又吸收楚辞的浪漫主义精神，为辞赋的发展开辟了一个新的境界。《洛神赋》为曹植辞赋中杰出作品。作者以浪漫主义的手法，通过梦幻的境界，描写人神之间的真挚爱情，但终因“人神殊道”无从结合而惆怅分离。\n\n　　作品从记述离开京城，“背伊阙，越轘辕，经通谷，陵景山”的行程开始，描写了作者与侍从们到达洛滨时的情景。当时“日既西倾，车殆马烦”，他们税驾蘅皋，秣驷芝田，容与阳林，流眄洛川。在一片静谧的气氛中，作者神思恍惚，极目远眺波光潋滟的洛水。就在他偶尔抬头的一刹那，奇迹出现了：一个瓌姿艳逸的女神站立在对面的山崖上。这使作者惊愕万分，他不自觉地拉住身旁的御者，急切地问道：“尔有觌于彼者乎？彼何人斯，若此之艳也！”在这里，山边水畔落日前的优美景色衬托出人物意外发现的惊喜之情，创造了一种引人入胜的意境。接下去御者的回答也十分巧妙，他避开作者第一个问题——“尔有觌于彼者乎”不答，而以“臣闻”“无乃”等猜测的口吻，郑重其事地提出洛神宓妃，这在有意为下文对洛神的描绘留下伏笔的同时，又给本已蹊跷的邂逅蒙上了一层神秘的色彩。洛神宓妃，相传为远古时代宓羲氏的女儿，因溺死于洛水而为水神。关于这个古老传说中的女神，屈原在《天问》和《离骚》中都曾提及。以后司马相如和张衡，又在赋中对她作了这样的描绘：“若夫青琴宓妃之徒，绝殊离俗，妖冶娴都，靓妆刻饰，便环绰约。……芬芳沤郁，酷烈淑郁；皓齿灿烂，宜笑的皪；长眉连娟，微睇绵藐”（《上林赋》）；“载太华之玉女兮，召洛浦之宓妃。咸姣丽以蛊媚兮，增嫮眼而蛾眉。舒婧之纤腰兮，扬杂错之袿徽。离朱唇而微笑兮，颜的以遗光……”（《思玄赋》）。与前人的这种直接描写不同，作品首先以一连串生动奇逸的比喻，对洛神初临时的情状作了精彩纷呈的形容：“其形也，翩若惊鸿，婉若游龙，荣曜秋菊，华茂春松。仿佛兮若轻云之蔽月，飘颻兮若流风之回雪。远而望之，皎若太阳升朝霞；迫而察之，灼若芙蓉出渌波。”其形象之鲜明，色彩之艳丽，令人目不瑕接。其中“翩若惊鸿，婉若游龙”，尤为传神地展现了洛神飘然而至的风姿神韵。它与下面的“轻云之蔽月”和“流风之回雪”，都从姿态方面，给人以轻盈、飘逸、流转、绰约的动感；而“秋菊”、“春松”与“太阳升朝霞”和“芙蓉出渌波”，则从容貌方面，给人以明丽、清朗、华艳、妖冶的色感。这种动感与色感彼此交错和互相浸淫，织成了一幅流光溢彩的神奇景象，它将洛神的绝丽至艳突出地展现在人们的面前。在这种由反复比喻造成的强烈艺术效果的基础上，作者进一步使用传统手法，对洛神的体态、容貌、服饰和举止进行了细致的刻画。这位宓羲氏之女身材适中，垂肩束腰，丽质天生，不假粉饰；她云髻修眉，唇齿鲜润，明眸隐靥，容光焕发；加之罗衣灿烂，佩玉凝碧，明珠闪烁，轻裾拂动，更显得“瓌姿艳逸，仪静体闲”。作者的这些描绘，使人联想起《诗经》对卫庄公夫人庄姜的赞美：“手如柔荑，肤如凝脂，领如蝤蛴，齿如瓠犀，螓首娥眉，巧笑倩兮，美目盼兮”（《卫风·硕人》）；也使人联想起宋玉对东邻女的称道：“增之一分则太长，减之一分则太短，著粉则太白，施朱则太赤”（《登徒子好色赋》）。作者显然受了他们的影响，但是他比前人更重视表现人物的动态美。下面，他着重描写了洛神天真活泼的举止：“践远游之文履，曳雾绡之轻裾。微幽兰之芳蔼兮，步踟蹰于山隅。于是忽焉纵体，以遨以嬉。左倚采旄，右荫桂旗。攘皓腕于神浒兮，采湍濑之玄芝。”至此，洛神的形象已神态兼备，呼之欲出了。“余情悦其淑美兮，心振荡而不怡”，作者为眼前这位美貌的女神深深打动了。他初为无以传递自己的爱慕之情而苦闷，继而“愿诚素之先达”，“解玉佩以要之”。在得到宓妃的应和，“执眷眷之款实”之后，他又想起传说中郑交甫汉滨遗佩之事，对她的“指潜渊而为期”产生了怀疑。作者在感情上的这种一波三折的变化，形象地反映出他当时内心的微妙状况。与其相应，洛神也感动了。不过作品没有像写作者那样，直接写她的心理变化，而是通过对她一系列行动的精细刻画，表现出激荡在她内心的炽热的爱，以及这种爱不能实现的强烈的悲哀。她“徙倚彷徨。神光离合，乍阴乍阳”，一会儿耸身轻举，似鹤立欲飞而未起；一会儿从椒涂蘅薄中经过，引来阵阵浓郁的芳香；一会儿又怅然长啸，声音中回荡着深长的相思之哀……当洛神的哀吟唤来了众神，她们无忧无虑地“或戏清流，或翔神渚，或采明珠，或拾翠羽”时，她虽有南湘二妃、汉滨游女陪伴，但仍不免“叹匏瓜之无匹兮，咏牵牛之独处”，站在那里出神。刹那间，她又如迅飞的水鸟，在烟波浩渺的水上徘徊飘忽，行踪不定。只有那转盼流动、含情脉脉的目光，以及欲言还止的唇吻，似乎在向作者倾吐内心的无穷眷恋和哀怨。作者对洛神或而彷徨，或而长吟，或而延竚，或而飘忽的这种描写，就好似一幕感情激烈、姿态优美的舞剧。人物以她那变化不定、摇曳多姿的舞步，展现了内心的爱慕、矛盾、惆怅和痛苦。尤其是“体迅飞凫，飘忽若神。凌波微步，罗袜生尘。动无常则，若危若安。进止难期，若往若还”一段，更将这幕舞剧推向了高潮，人物的心理矛盾、感情波澜在此得到了最充分的表现。正当作者与洛神相对无语、两情依依之时，离别的时刻终于到了。这是一个构想奇逸、神彩飞扬的分别场面：屏翳收风，川后静波，在冯夷、女娲的鼓乐声中，由六龙驾驭的云车载着宓妃，在鲸鲵夹毂、异鱼翼輈的护卫下，开始出发了。美丽的洛神坐在渐渐远去的车上，还不断地回过头来，向作者倾诉自己的一片衷肠。“悼良会之永绝兮，哀一逝而异乡”，深深的哀怨笼罩着这个充满神话色彩的画面。在陈述了“恨人神之道殊兮，怨盛年之莫当”的“交接之大纲”之后，洛神还信誓旦旦地表示：“虽潜处于太阴，长寄心于君王。”最后，洛神的艳丽形象终于消失在苍茫的暮色之中，而作者却依然站在水边，怅怅地望着洛神逝去的方向，恍然若失。他驾着轻舟，溯川而上，希望能再次看到神女的倩影。然而，烟波渺渺，长夜漫漫，更使他情意悠悠、思绪绵绵。天亮后，作者不得不“归乎东路”了，但仍“揽騑辔以抗策，怅盘桓而不能去”。作品这段文字洋溢着浓厚的抒情气氛，具有一种勾魂摄魄的力量，它把洛神的形象在人们心中勾勒、烘托得更加突出、更加完美。\n\n　　此赋的主要特点有三：特点一，想象丰富。作者从京城洛阳启程，东归封地鄄城。途中，在洛川之边，停车饮马，在阳林漫步之时，看到了洛神宓妃，这就是想象。她的体态摇曳飘忽像惊飞的大雁，婉曲轻柔像是水中的游龙，鲜美、华丽较秋菊、茂松有过之，姣如朝霞，纯洁如芙蓉，风华绝代。随后他对她产生爱慕之情，托水波以传意，寄玉佩以定情。然她的神圣高洁使他不敢造次。洛神终被他的真情所感动，与之相见，倾之以情。但终因人神殊途，结合无望，与之惜别。想象绚烂，浪漫凄婉之情淡而不化，令人感叹，惆怅丝丝。但这想象并不离奇，因此赋是有感于宋玉的《神女赋》《高唐赋》两篇赋而作。\n\n　　特点二，词藻华丽而不浮躁，清新之气四逸，令人神爽。讲究排偶，对仗，音律，语言整饬、凝炼、生动、优美。取材构思汉赋中无出其右。此赋起笔便是平中蕴奇的氛围创造。开头平平的叙述，正与陶渊明《桃花源记》叙武陵人的行舟之始一样，奇境的显现在事前一无征兆。但在此刻，作者刹那间目睹了一幕终身难忘的景象：一位俏丽的女子，即洛神现身。接着作者像要与宋玉笔下的巫山神女争辉似的着力描摹洛神的神采姣容以及痛苦情状。然后写洛神率众离去，与屈原《离骚》抒写主人公悲怆远逝的景象有异曲同工之妙。\n\n　　特点三，传神的描写刻画，兼之与比喻、烘托共用，错综变化巧妙得宜，给人一种浩而不烦、美而不惊之感，使人感到就如在看一幅绝妙丹青，个中人物有血有肉，而不会使人产生一种虚无之感。在对洛神的体型、五官、姿态等描写时，给人传递出洛神的沉鱼之貌、落雁之容。同时，又有“清水出芙蓉，天然去雕饰”的清新高洁。在对洛神与之会面时的神态的描写刻画，使人感到斯人浮现于眼前，风姿绰约。而对于洛神与其分手时的描写“屏翳收风，川后静波，冯来鸣鼓，女娲清歌。”爱情之真挚、纯洁，一切都是这样美好，以致离别后，人去心留，情思不断，洛神的倩影和相遇相知时的情景历历在目，浪漫而苦涩，心神为之不宁徘徊于洛水之间不忍离去。\n\n　　对《洛神赋》的思想、艺术成就前人都曾予以极高的评价，最明显的是常把它与屈原的《九歌》和宋玉的《神女》诸赋相提并论。其实，曹植此赋兼二者而有之，它既有《湘君》《湘夫人》那种浓厚的抒情成分，同时又具宋玉诸赋对女性美的精妙刻画。此外，它的情节完整，手法多变和形式隽永等妙处，又为以前的作品所不及。', poem_tags = '辞赋精选,写人,爱情,神话' WHERE poem_title = '洛神赋' AND poem_author = '曹植';
UPDATE edu_poem SET poem_translation = '水像美人流动的眼波，山如美人蹙起的眉毛。想问行人去哪里？到山水交汇的地方。\n刚送走了春天，又要送你回去。假如你到江南，还能赶上春天的话，千万要把春天的景色留住。', poem_notes = '卜算子：词牌名。北宋时盛行此曲。万树《词律》以为取义于“卖卜算命之人”。双调，四十四字，上下片各两仄韵。两结亦可酌增衬字，化五言句为六言句，于第三字豆。宋教坊复演为慢曲，《乐章集》入“歇指调”。八十九字，前片四仄韵，后片五仄韵。\n鲍浩然：生平不详，词人的朋友，家住浙江东路，简称浙东。\n水是眼波横：水像美人流动的眼波。古人常以秋水喻美人之眼，这里反用。眼波：比喻目光似流动的水波。\n山是眉峰聚：山如美人蹙起的眉毛。《西京杂记》载卓文君容貌姣好，眉色如望远山，时人效画远山眉。后人遂喻美人之眉为远山，这里反用。\n欲：想，想要。\n行人：指词人的朋友（鲍浩然）。\n眉眼盈盈处： 一说比喻山水交汇的地方，另有说是指鲍浩然前去与心上人相会。盈盈：美好的样子。\n才始：方才。', poem_appreciation = '这是一首送别词，词中以轻松活泼的笔调，巧妙别致的比喻，风趣俏皮的语言，表达了作者在越州大都督府送别友人鲍浩然时的心绪。\n\n　　词的上片着重写人。起首两句，运用风趣的笔墨，把景语变成情语，把送别诗所见自然山水化成为有情之物。当这位朋友归去的时候，路上的一山一水，对他都显出了特别的感情。那些清澈明亮的江水，仿佛变成了他所想念的人的流动的眼波；而一路上团簇纠结的山峦，也似乎是她们蹙攒的眉峰了。正因为友人鲍浩然在归途中怀着深厚的怀人感情，山水都变成了有感情之物。\n\n　　三、四两句点出行人此行的目的：他的去处，是“眉眼盈盈处”。“眉眼盈盈”四字有两层意思：一指江南的山水，清丽明秀，有如女子的秀眉和媚眼；二指有着盈盈眉眼的那个人。因此“眉眼盈盈处”，既写了江南山水，也同时写了他要见到的人物。此两句写送别时的一往情深却又含而不露。春语意双关。\n\n　　最后两句是词人对鲍浩然的祝愿：希望他生活在“春”里。这个“春”既是反映鲜花如锦的春天季节，也喻指他与心上人生活在一起。\n\n　　这是一首送别词。 起拍“水是”、“山是”两句，含意丰富，启人遐想。词人把明澈的水流比喻为美人的眼波，把青黛的山峦喻为美人的眉峰，极言浙东山水的漂亮可爱。同时，也可以理解为词人对鲍浩然心事的设想：波光漾动的流水是他心上人的眼波，脉脉传情；青黛的山峦是心上人的眉峰，因思念自己而满怀愁怨，眉头都蹙起来了。词人通过这一设想来写出了鲍浩然“之浙东”的心切。与此相应，上片结句“眉眼盈盈处”也可以有两层理解：一是鲍浩然是去山水透丽得像美人“眉眼盈盈”的地方，一是他是去与“眉眼盈盈”的心上人相会。', poem_tags = '宋词三百首,小学古诗,初中古诗,婉约,送别,山水,写人' WHERE poem_title = '卜算子·送鲍浩然之浙东' AND poem_author = '王观';
UPDATE edu_poem SET poem_translation = '九曲黄河从遥远的地方蜿蜒奔腾而来，一路裹挟着万里的黄沙。\n既然你从天边而来，如今好像要直飞上高空的银河，请你带上我扶摇直上，汇集到银河中去，一同到牛郎和织女的家里做客吧。', poem_notes = '浪淘沙：唐教坊曲名。创自刘禹锡、白居易，其形式为七言绝句。后又用为词牌名。\n九曲：自古相传黄河有九道弯。形容弯弯曲曲的地方很多。\n万里沙：黄河在流经各地时挟带大量泥沙。\n浪淘风簸：黄河卷着泥沙，风浪滚动的样子。浪淘：波浪淘洗。簸：掀翻，上下簸动。\n自天涯：来自天边。牵牛织女：银河系的两个星座名。自古相传，织女为天上仙女，下凡到人间，和牛郎结为夫妇。后西王母召回织女，牛郎追上天，西王母罚他们隔河相望，只准每年七月七日的夜晚相会一次。牵牛：即传说中的牛郎。', poem_appreciation = '这首绝句模仿淘金者的口吻，表明他们对淘金生涯的厌恶和对美好生活的向往。同是在河边生活，牛郎织女生活的天河恬静而优美，黄河边的淘金者却整天在风浪泥沙中讨生活。直上银河，同访牛郎织女，寄托了他们心底对宁静的田园牧歌生活的憧憬。这种浪漫的理想，以豪迈的口语倾吐出来，有一种朴素无华的美。\n\n　　“九曲黄河万里沙，浪淘风簸自天涯”见唐·刘禹锡《浪淘沙》。淘：用水冲洗。簸：摇动。自：来自。这两句大意是：九曲黄河之中有无数的抄砾，它们随同黄河流经万里，经受了浪涛的冲洗和狂风的簸荡，从天涯一直来到这里。\n\n　　诗人歌咏九曲黄河中的万里黄沙，赞扬它们冲风破浪，一往无前的顽强性格。我们引用时可取其象征意义，歌颂与它们有着共同特点的事物或人们。\n\n　　“九曲黄河万里沙，浪淘风簸自天涯。如今直上银河去，同到牵牛织女家。”这是唐代诗人刘禹锡见黄河后留下的感慨，也是他对宁静生活的一种向往，而时间让世事变得复杂，追逐静已是现代人的一种精神渴求。九曲黄河沉积下来的是一种文化，而这种文化最大的特点就是静，它们深埋在河水转弯处的山坳里，在浮华背后深深地拽住民族的根，使我们在追逐中不会迷失方向。\n\n　　唐代大诗人刘禹锡一阕《浪淘沙》，生动形象地写出了滔滔黄河的来龙去脉和雄伟气势。其中，还诗情画意地联想到随着层层波浪，去美丽传说中的天仙佳侣之家做客。', poem_tags = '向往,田园,生活,早教古诗100首' WHERE poem_title = '浪淘沙·九曲黄河万里沙' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '悠闲地住在这里很少有邻居来，杂草丛生的小路通向荒芜小园。\n鸟儿自由地栖息在池边的树上，皎洁的月光下僧人正敲着山门。\n走过桥去看见原野迷人的景色，云脚在飘动山石也好像在移动。\n我暂时离开这里但是还会回来，按约定的日期与朋友一起隐居。', poem_notes = '⑴少（shǎo）：不多。\n⑵池边：一作“池中”。\n⑶分野色：山野景色被桥分开。\n⑷云根：古人认为“云触石而生”，故称石为云根。这里指石根云气。\n⑸幽期：时间非常漫长。负言：指食言，不履行诺言，失信的意思。', poem_appreciation = '这首诗以“鸟宿池边树，僧敲月下门”一联著称。全诗只是抒写了作者走访友人李凝未遇这样一件寻常小事。\n\n　　首联“闲居少邻并，草径入荒园”，诗人用很经济的手法，描写了这一幽居的周围环境：一条杂草遮掩的小路通向荒芜不治的小园；近旁，亦无人家居住。淡淡两笔，十分概括地写了一个“幽”字，暗示出李凝的隐士身分。\n\n　　“鸟宿池边树，僧敲月下门”，是历来广为传诵的名句。这两句诗，粗看有些费解。诗人当然不可能连夜晚宿在池边树上的鸟都能看到。其实，这正见出诗人构思之巧，用心之苦。正由于月光皎洁，万籁俱寂，因此老僧（或许即指作者）一阵轻微的敲门声，就惊动了宿鸟，或是引起鸟儿一阵不安的噪动，或是鸟从窝中飞出转了个圈，又栖宿巢中了。作者抓住了这一瞬即逝的现象，来刻画环境之幽静，响中寓静，有出人意料之胜。倘用“推”字，当然没有这样的艺术效果了。\n\n　　颈联“过桥分野色，移石动云根”，是写回归路上所见。过桥是色彩斑斓的原野；晚风轻拂，云脚飘移，仿佛山石在移动。“石”是不会“移”的，诗人用反说，别具神韵。这一切，又都笼罩着一层洁白如银的月色，更显出环境的自然恬淡，幽美迷人。\n\n　　尾联”暂去还来此，幽期不负言“，表明诗人不负归隐的约定。前三联都是叙事与写景，最后一联点出诗人心中幽情，托出诗的主旨。正是这种幽雅的处所，悠闲自得的情趣，引起作者对隐逸生活的向往。\n\n　　诗中的草径、荒园、宿鸟、池树、野色、云根，无一不是寻常所见景物；闲居、敲门、过桥、暂去等等，无一不是寻常的行事。然而诗人偏于寻常处道出了人所未道之境界，语言质朴，冥契自然，而又韵味醇厚。', poem_tags = '访友,写景,早教古诗100首' WHERE poem_title = '题李凝幽居' AND poem_author = '贾岛';
UPDATE edu_poem SET poem_translation = '有利于作战的天气、时令，比不上有利于作战的地理形势；有利于作战的地理形势，比不上作战中的人心所向、内部团结。\n比如一座）方圆三里的小城，只有方圆七里的外城，四面包围起来攻打它，却不能取胜。采用四面包围的方式攻城，一定是得到有利于作战的天气、时令了，可是不能取胜，这是因为有利于作战的天气、时令比不上有利于作战的地理形势呀。\n城墙并不是不高啊，护城河并不是不深呀，武器装备也并不是不精良，粮食供给也并不是不充足啊，但是，守城一方还是弃城而逃，这是因为作战的地理形势再好），也比不上人心所向、内部团结啊。\n\n　　所以说，使人民定居下来而不迁到别的地方去，不能靠划定的边疆的界限，巩固国防不能靠山河的险要，震慑天下不能靠武力的强大。能行“仁政”的君王，帮助支持他的人就多，不施行“仁政”的君主，支持帮助他的人就少。支持帮助他的人少到了极点，连内外亲属也会背叛他；支持帮助他的人多到了极点，天下所有人都会归顺他。凭着天下人都归顺他的条件，去攻打那连亲属都反对背叛的君王，所以，君子要么不战斗，如果）战斗就一定会取得胜利。', poem_notes = '天时：包括时令、气候，乃至政治形势等非人力所能及的条件。\n地利：指有利于作战的地理形势。\n人和：指作战中的人心有所向，内部团结。\n三里之城：方圆三里的内城。城：内城。　城非不高也：城墙并不是不高啊。\n郭：外城。在城外加筑的一道城墙。\n环：围。\n之：代这座城\n而：连词表转折。\n夫：句首发语词，不译。\n而：连词表递进。\n是：这。\n也：表判断语气，“是”。\n非：不是。\n池：护城河。\n兵革：泛指武器装备。兵，武器；革，甲胄，用以护身的盔甲之类。\n坚利：精良。坚，坚固。利，锋利。\n米粟：粮食。\n多：充足。\n委：放弃。\n而：连词表顺承。\n去：离开。\n之：代词，代“城”。\n故：所以。\n域：这里用作动词，是限制的意思。\n以：凭借。\n封疆之界：划定的边疆界线。封，划定。疆，边疆。界，界限。\n固：巩固。\n国：国防。\n山溪：山河。\n险：险要。\n威：震慑，树立威望。\n得道者：实施“仁政”的君主。者，……的人，此处特指君主。道，正义。下同。\n失道者：不实施“仁政”的君主。\n寡：少。\n之至：到达极点。\n畔：通“叛”，背叛。\n顺：归顺，服从\n以：凭借。\n之：主谓间取消句子独立性。\n故：所以。\n有：要么，或者。\n固国不以山溪之险：巩固国防不能靠山河的险要。\n威天下不以兵革之利：震慑天下不能靠武力的强大。\n亲戚：内外亲属，包括父系亲属和母系亲属。', poem_appreciation = '我们通常用“得道多助，失道寡助”这句话来表示：合乎正义者就能得到多方面的支持与帮助，违背正义的就会陷入孤立无援的境地。在这里，我们把“道”理解为“正义”。那么，什么叫“正义”？《现代汉语词典》中说：“正义”是指“公正的、有利于人民的道理”。这是富于现代气息的理解，然而是和它最初的含义一脉相承的。\n\n　　“得道多助，失道寡助”是孟子的一个著名论断。《孟子·公孙丑下》中说：“得道者多助，失道者寡助。寡助之至，亲戚畔之；多助之至，天下顺之。以天下之所顺，攻亲戚之所畔，故君子有不战，战必胜矣。”这里的“畔”字通“叛”，是背叛、反对的意思。这段话是说，对得道的人，帮助他的人就多；对失道的人，帮助他的人就少。帮助的人少到极点时，就连亲戚都会反对他；帮助的人多到极点时，全天下的人都会顺从他。拿全天下都顺从的力量，来攻打连亲戚都反对的人，要么不战，一战必胜。\n\n　　孟子在这里说的“得道”和“失道”的人，都不是指普通的个人，而是指一国之君。一国之君既是战争的总指挥，也是政治上的领袖。孟子通过论述战争胜负的问题，引出了“得道多助，失道寡助”的观点，然而在孟子看来，“民心向背”对于战争具有根本性的意义，对于政治也具有同样重要的意义。孟子说：“得天下有道：得其民，斯得天下矣；得其民有道：得其心，斯得民矣。”意思是说，得天下必先得民，得民必先得民心。所谓的“得民”，就是得到人民的支持、拥护和帮助。所谓的“得天下”，是指通过施行仁政来“王天下”，而不是单靠武力来争夺天下。仁政，是以德服人，使人心悦诚服，自动来归附；而以力服人，不能服人之心。在孟子看来，得天下之道，即是施行仁政。因为仁政，是“得其心”之政。\n\n　　那么，如何“得其心”，即如何行仁政呢？孟子提出了“保民”的思想。保民，就是关爱和保护人民，它要求君主做到“所欲与之聚之，所恶勿施”，就是人民所希望的，就替他们聚积起来，人民所厌恶的，不要强加给他们。人民所希望的是什么呢，当然是富裕、幸福的生活。孟子认为，这是行仁政的根本着眼点。做到了这一点，然后民心归服、天下归服，是任何力量都阻止不了的。\n\n　　“战必胜矣”的主要原因：“天时不如地利，地利不如人和”、“多助之至，天下顺之”。', poem_tags = '初中文言文,议论,哲理' WHERE poem_title = '得道多助，失道寡助' AND poem_author = '孟子及其弟子';
UPDATE edu_poem SET poem_translation = '一支折断了的铁戟（古代兵器）沉没在水底的沙中还没有销蚀掉，经过自己又磨又洗发现这是当年赤壁之战的遗留之物。\n假如东风不给周瑜以方便，结局恐怕是曹操取胜，二乔被关进铜雀台了。', poem_notes = '折戟：折断的戟。戟，古代兵器。\n销：销蚀。\n将：拿起。\n磨洗：磨光洗净。\n认前朝：认出戟是东吴破曹时的遗物。\n东风：指三国时期的一个战役──火烧赤壁。\n周郎：指周瑜，字公瑾，年轻时即有才名，人乎周郎。后任吴军大都督，曾参与赤壁之战并为此战役中的主要人物。\n铜雀：即铜雀台，曹操在今河北省临漳县建造的一座楼台，楼顶里有大铜雀，台上住姬妾歌妓，是曹操暮年行乐处。\n二乔：东吴乔公的两个女儿，一嫁前国主孙策（孙权兄），称大乔，一嫁军事统帅周瑜，称小乔，合称“二乔”。', poem_appreciation = '“折戟沉沙铁未销，自将磨洗认前朝。”这两句意为折断的战戟沉在泥沙中并未被销蚀，自己将它磨洗后认出是前朝遗物。在这里，这两句描写看似平淡实为不平。沙里沉埋着断戟，点出了此地曾有过历史风云。战戟折断沉沙却未被销蚀，暗含着岁月流逝而物是人非之感。正是由于发现了这一件沉埋江底六百多年，锈迹斑斑的“折戟”，使得诗人思绪万千，因此他要磨洗干净出来辨认一番，发现原来是赤壁之战遗留下来的兵器。这样前朝的遗物又进一步引发作者浮想联翩的思绪，为后文抒怀作了很好的铺垫。\n\n　　“东风不与周郎便，铜雀春深锁二乔。”这后两句久为人们所传诵的佳句，意为倘若当年东风不帮助周瑜的话，那么铜雀台就会深深地锁住东吴二乔了。这里涉及到历史上著名的赤壁之战。在赤壁战役中，周瑜主要是用火攻战胜了数量上远远超过己方的敌人，而其能用火攻则是因为在决战的时刻，恰好刮起了强劲的东风，所以诗人评论这次战争成败的原因，只选择当时的胜利者—周郎和他倚以致胜的因素—东风来写，而且因为这次胜利的关键，最后不能不归到东风，所以又将东风放在更主要的地位上。但他并不从正面来描摹东风如何帮助周郎取得了胜利，却从反面落笔：假使这次东风不给周郎以方便，那么，胜败双方就要易位，历史形势将完全改观。因此，接着就写出假想中曹军胜利，孙、刘失败之后的局面。但又不直接铺叙政治军事情势的变迁，而只间接地描绘两个东吴著名美女将要承受的命运。如果曹操成了胜利者，那么，大乔和小乔就必然要被抢去，关在铜雀台上，以供他享受了。这里的铜雀台，就表现了曹操风流的一面，又言“春深”更加深了风流韵味，最后再用一个“锁”字，进一步突显其金屋藏娇之意。把硝烟弥漫的战争胜负写得很是蕴藉。\n\n　　诗中的大乔、二乔两位女子，并不是平常的人物，而是属于东吴统治阶级中最高阶层的贵妇人。大乔是东吴前国主孙策的夫人，当时国主孙权的亲嫂，小乔则是正在带领东吴全部水陆兵马和曹操决一死战的军事统帅周瑜的夫人。她们虽与这次战役并无关系，但她们的身分和地位，代表着东吴作为一个独立政治实体的尊严。东吴不亡，她们决不可能归于曹操；连她们都受到凌辱，则东吴社稷和生灵的遭遇也就可想而知了。所以诗人用“铜雀春深锁二乔”这样一句诗来描写在“东风不与周郎便”的情况之下，曹操胜利后的骄恣和东吴失败后的屈辱，正是极其有力的反跌，不独以美人衬托英雄，与上句周郎互相辉映，显得更有情致而已。诗的创作必须用形象思维，而形象性的语言则是形象思维的直接现实。用形象思维观察生活，别出心裁地反映生活，乃是诗的生命。杜牧在此诗里，通过“铜雀春深”这一富于形象性的诗句，即小见大，这正是他在艺术处理上独特的成功之处。另外，此诗过分强调东风的作用，又不从正面歌颂周瑜的胜利，却从反面假想其失败。杜牧通晓政治军事，对当时中央与藩镇、汉族与吐蕃的斗争形势，有相当清楚的了解，并曾经向朝廷提出过一些有益的建议。如果说，孟轲在战国时代就已经知道“天时不如地利，地利不如人和”的原则，而杜牧却还把周瑜在赤壁战役中的巨大胜利，完全归之于偶然的东风，这是很难想象的。他之所以这样地写，恐怕用意还在于自负知兵，借史事以吐其胸中抑郁不平之气。其中也暗含有阮籍登广武战场时所发出的“时无英雄，使竖子成名”那种慨叹在内，不过出语非常隐约，不容易看出。', poem_tags = '唐诗三百首,初中古诗,咏史怀古,战争,怀才不遇' WHERE poem_title = '赤壁' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '京城大道上空丝雨纷纷，它像酥油般细密而滋润，远望草色依稀连成一片，近看时却显得稀疏零星。\n这是一年中最美的季节，远胜过绿柳满城的春末。', poem_notes = '呈：恭敬地送给。水部张十八员外：指张籍（766—830年）唐代诗人。在同族兄弟中排行第十八，曾任水部员外郎。\n天街：京城街道。润如酥：细腻如酥。酥，动物的油，这里形容春雨的细腻。\n最是：正是。处：时。\n绝胜：远远胜过。皇都：帝都，这里指长安。', poem_appreciation = '这首小诗是写给水部员外郎张籍的一首描写和赞美早春美景的七言绝句。张籍在兄弟辈中排行十八，故称张十八。诗的风格清新自然，简直是口语化的。看似平淡，实则是绝不平淡的。韩愈自己说：艰穷怪变得，往往造平淡（《送无本师归范阳》）。原来他的平淡是来之不易的。\n\n　　首句点出初春小雨，以“润如酥”来形容它的细滑润泽，准确地捕捉到了它的特点。造句清新优美。与杜甫的“好雨知时节，当春乃发生。随风潜入夜，润物细无声”有异曲同工之妙。\n\n　　第二句紧承首句，写草沾雨后的景色。以远看似有 ，近看却无 ，描画出了初春小草沾雨后的朦胧景象。写出了春草刚刚发芽时，若有若无，稀疏，矮小的特点。可与王维的“青霭入看无”、“山色有无中”相媲美。\n\n　　第三、四句对初春景色大加赞美：“最是一年春好处，绝胜烟柳满皇都。”这两句意思是说：早春的小雨和草色是一年春光中最美的东西，远远超过了烟柳满城的衰落的晚春景色。写春景的诗，在唐诗中，多取明媚的晚春，这首诗却取早春咏叹，认为早春比晚春景色优胜，别出心裁。前两句体察景物之精细已经令人称赞，后两句如骑兵骤至更在人意料之外。\n\n　　这首小诗，诗人只运用简朴的文字 ，就常见的“小雨”和“草色”，描绘出了早春的独特景色。刻画细腻，造句优美，构思新颖，给人一种早春时节湿润、舒适和清新之美感。表达作者充满对春天的热爱和赞美之情。\n\n　　全篇中绝妙佳句便是那“草色遥看近却无”了。早春二月，在北方，当树梢上、屋檐下都还挂着冰凌儿的时候，春天连影儿也看不见。但若是下过一番小雨后，第二天，春天就来了。雨脚儿轻轻地走过大地，留下了春的印记，那就是最初的春草芽儿冒出来了，远远望去，朦朦胧胧，仿佛有一片极淡极淡的青青之色，这是早春的草色。看着它，人们心里顿时充满欣欣然的生意。可是当人们带着无限喜悦之情走近去看个仔细，地上是稀稀朗朗的极为纤细的芽，却反而看不清什么颜色了。诗人像一位高明的水墨画家，挥洒着他饱蘸水分的妙笔，隐隐泛出了那一抹青青之痕，便是早春的草色。远远望去，再像也没有，可走近了，反倒看不出。这句“草色遥看近却无”，真可谓兼摄远近，空处传神。\n\n　　这设色的背景，是那落在天街上的纤细小雨。透过雨丝遥望草色，更给早春草色增添了一层朦胧美。而小雨又滋润如酥。酥就是奶油。受了这样的滋润，那草色自然是新的；又有这样的背景来衬托，那草色自然也美了。\n\n　　在最后，诗人还来个对比：“绝胜烟柳满皇都”。诗人认为初春草色比那满城处处烟柳的景色不知要胜过多少倍。因为，“遥看近却无”的草色，是早春时节特有的，它柔嫩饱含水分，象征着大地春回、万象更新的欣欣生意。而烟柳已经是“杨柳堆烟”时候，何况“满”城皆是，不稀罕了。到了暮春三月，色彩浓重，反倒不那么惹人喜爱了。像这样运用对比手法，与一般不同，这是一种加倍写法，为了突出春色的特征。\n\n　　“物以稀为贵”，早春时节的春草之色也是很娇贵的。“新年都未有芳华，二月初惊见草芽”（韩愈《春雪》）。这是一种心理状态。严冬方尽\\余寒犹厉，突然看到这美妙的草色，心头不由得又惊又喜。这一些轻淡的绿，是当时大地唯一的装饰；可是到了晚春则“草树知春不久归”（韩愈《晚春》），这时那怕柳条儿绿得再好，人们也无心看，因为已缺乏那一种新鲜感。\n\n　　所以，诗人就在第三句转折时提醒说：“最是一年春好处。”一年之际在于春，而春天的最好处却又在早春。\n\n　　这首诗既咏早春，又能摄早春之魂，给读者以无穷的美感趣味，甚至是绘画所不能及的。诗人没有彩笔，但他用诗的语言描绘出极难描摹的色彩——一种淡素的、似有却无的色彩。如果没有锐利深细的观察力和高超的诗笔，便不可能把早春的自然美提炼为艺术美。', poem_tags = '初中古诗,写景,春天,写雨,柳树' WHERE poem_title = '早春呈水部张十八员外 / 初春小雨' AND poem_author = '韩愈';
UPDATE edu_poem SET poem_translation = '是谁家精美的笛子暗暗地发出悠扬的笛声。随着春风飘扬，传遍洛阳全城。\n就在今夜的曲中，听到故乡的《折杨柳》，哪个人的思乡之情不会因此而油然而生呢？', poem_notes = '洛城：今河南洛阳。\n玉笛：笛子的美称。③暗飞声：声音不知从何处传来。声：声音。\n春风：指春天的风，比喻恩泽，融和的气氛等引申涵义\n闻：听;听见。\n折柳：即《折杨柳》笛曲，乐府“鼓角横吹曲”调名，内容多写离情别绪。曲中表达了送别时的哀怨感情。\n故园：指故乡，家乡。', poem_appreciation = '开元二十三年(735)，李白客东都(洛阳)。《春夜洛城闻笛》一诗，当即这次客东都有感而作。\n\n　　这首诗写乡思，题作《春夜洛城闻笛》，明示诗因闻笛声而\n\n　　感发。题中“洛城“表明是客居，“春夜“点出季节及具体时间。起句即从笛声落笔。已经是深夜，诗人难于成寐，忽而传来几缕断续的笛声。这笛声立刻触动诗人的羁旅情怀。诗人不说闻笛，而说笛声“暗飞“，变客体为主体。“暗“字为一句关键。注家多忽略这个字。已故沈祖棻先生说:“……‘谁家’、‘暗飞声’，写出‘闻’时的精神状态，先听到飞声，踪迹它的来处，却不知何人所吹，从何而来，所以说是暗中飞出。“(《唐人七绝诗浅释》)可为一种理解。因为不知笛声来自何处，更不见吹笛者为何人，下此“暗“字，自是十分确当。这里“暗“字有多重意蕴。主要是说笛声暗送，似乎专意飞来给在外作客的人听，以动其离愁别恨。全句表现出一种难于为怀的心绪，所谓以主观写客观。此外，“暗“也有断续、隐约之意，这与诗的情境是一致的。“谁家“，意即不知谁家，“谁“与“暗“照应。第二句着意渲染笛声，说它“散入春风“，“满洛城“，仿佛无处不在，无处不闻。这自然是有心人的主观感觉的极度夸张。“散“字用得妙。“散“是均匀、遍布。笛声“散入春风“，随着春风传到各处，无东无西，无南无北。即为“满洛城“的“满“字预设地步;“满“字从“散“字引绎而出，二者密合无间。\n\n　　为什么闻笛声诗人会触动乡思呢?第三句点出《折柳》曲。古人送别时折柳，盼望亲人来归也折柳。据说“柳“谐“留“音，故折柳送行表示别情。长安灞桥即为有名的送别之地，或云其地杨柳为送行人攀折殆尽。《折杨柳》曲伤离惜别，其音哀怨幽咽。晋太康末，京洛流行《折杨柳》歌，有“兵革苦辛“之词。北朝《折杨柳歌》曰:“上马不捉鞭，反拗杨柳枝;蹀坐吹长笛，愁杀行客儿。“大约都是据曲意填的歌词。所以，诗人听到这《折柳》曲，便引起客愁乡思。一般说，久居他乡的人，白天还没有什么，可是一到日暮天晚，就容易想念家乡。在春秋季节，\n\n　　人们也常是多愁善感。《折柳》为全诗点睛，亦即“闻笛“的题义所在。三，四两句写诗人自己情怀，却从他人反说。强调“此夜“，是面对所有客居洛阳城的人讲话，为结句“何人不起故园情“作势。这是主观情感的推衍，不言“我“，却更见“我“感触之深，乡思之切。\n\n　　短短的一首七言绝句，倒颇能显现李太白的风格特点，即艺术表现上的主观倾向。', poem_tags = '初中古诗,音乐,思乡' WHERE poem_title = '春夜洛城闻笛 / 春夜洛阳城闻笛' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '月亮已落下乌鸦啼叫寒气满天， 对着江边枫树和渔火忧愁而眠。\n姑苏城外那寂寞清静寒山古寺， 半夜里敲钟的声音传到了客船。', poem_notes = '枫桥：在今苏州市阊门外。\n夜泊：夜间把船停靠在岸边。\n乌啼：一说为乌鸦啼鸣，一说为乌啼镇。\n霜满天：霜，不可能满天，这个“霜”字应当体会作严寒；霜满天，是空气极冷的形象语。\n江枫：一般解释作“江边枫树”，江指吴淞江，源自太湖，流经上海，汇入长江，俗称苏州河。另外有人认为指“江村桥”和“枫桥”。“枫桥”在吴县南门（阊阖门）外西郊，本名“封桥”，因张继此诗而改为“枫桥”。\n渔火：通常解释，“鱼火”就是渔船上的灯火；也有说法指“渔火”实际上就是一同打渔的伙伴。\n对愁眠：伴愁眠之意，此句把江枫和渔火二词拟人化。就是后世有不解诗的人，怀疑江枫渔火怎么能对愁眠，于是附会出一种讲法，说愁眠是寒山寺对面的山名。\n姑苏：苏州的别称，因城西南有姑苏山而得名。\n寒山寺：在枫桥附近，始建于南朝梁代。相传因唐代僧人寒山、拾得曾住此而得名。在今苏州市西枫桥镇。本名“妙利普明塔院”，又名枫桥寺；另一种说法，“寒山”乃泛指肃寒之山，非寺名。寺曾经数次重建，现在的寺宇，为太平天国以后新建。寺钟在第二次世界大战时，被日本人运走，下落不明。\n夜半钟声：当今的佛寺（春节）半夜敲钟，但当时有半夜敲钟的习惯，也叫「无常钟」或「分夜钟」。宋朝大文豪欧阳修曾提出疑问表示：“诗人为了贪求好句，以至于道理说不通，这是作文章的毛病，如张继诗句“夜半钟声到客船”，句子虽好，但那有三更半夜打钟的道理？”可是经过许多人的实地查访，才知苏州和邻近地区的佛寺，有打半夜钟的风俗。', poem_appreciation = '月落乌啼霜满天，江枫渔火对愁眠。姑苏城外寒山寺，夜半钟声到客船。”据当代人考证，“月落”不是月亮已落或将落未落，而是村庄名或桥名，“乌啼”并非是乌鸦夜啼，而是山名。而“江枫”也不是江边的枫树，亦为桥名。于是乎，朦胧的月色、渔火间若隐若现的枫树以及让人心动的乌啼都已不复存在，一首流传千年的古诗竟然变得那么具体而实在，那幅朦胧静谧、清冷幽美的江南水乡秋夜图也消失殆尽，只剩下一连串村庄名或桥名的罗列。不可否认，我仍然喜欢童年读到的那种意境和况味，尽管是误读。记得多年前曾有一首流行歌曲《涛声依旧》，歌词中有这样的句子：“带走一盏灯火，让它温暖我的双眼；留下一段真情，让它停泊在枫桥边”，“流连的钟声还在敲打我的无眠”，“月落乌啼总是千年的风霜……”等等。虽然这是两件不同的艺术作品，但显然《涛声依旧》与《枫桥夜泊》被误读的意境有着千丝万缕的联系。看来，更多的人还是认同那种误读的诗意。 还有很多人把歌词“长亭外，古道边，芳草碧连天，晚风拂柳笛声残，夕阳山外山……”中的“长亭外”唱成“长城外”。台湾女作家席幕蓉曾经在一篇题为《燕子》的文章中写过这样一件事：她的父亲喜欢这首歌，也常常哼唱这首歌。而当有一天女儿纠正他说歌中的“长城外”错了，应该是“长亭外”，他连连说：“怎么是长亭外?怎么不是长城外呢?我一直以为是长城外啊，好可惜!我一直以为是长城外，以为写的是我们的老家……以往这么多年是听错了，好可惜!”是啊，对于那些游子来说，想到长城自然就想到了故乡，想到了祖国。（《美丽的错误》）但也有的资料上说这些山和桥正是因这首诗而得名的。\n\n　　鲜为人知的唐代诗人张继留下的诗并不多，但一首《枫桥夜泊》伴随苏州城，伴随寒山寺流传千年。', poem_tags = '唐诗三百首,秋天,写景,思乡' WHERE poem_title = '枫桥夜泊' AND poem_author = '张继';
UPDATE edu_poem SET poem_translation = '乌云上涌，就如墨汁泼下，却又在天边露出一段山峦，明丽清新，大雨激起的水花如白珠碎石，飞溅入船。\n忽然间狂风卷地而来，吹散了满天的乌云，而那西湖的湖水碧波如镜，明媚温柔。\n\n放生出去的鱼鳖追赶着人们来，到处都开着不知谁种的荷花。\n躺在船里的枕席上可以觉得山在一俯一仰地晃动，飘荡在风里的船也知道和月亮徘徊留连不已。\n\n湖里生长的乌菱和白芡不用论钱，水中的雕胡米就像包裹在绿盘里。\n忽然回忆起在会灵观尝食新谷之事，如要滞留在江海之上需多进饮食，保重身体啊。\n\n兰舟上的采莲女把湖上的荷花采下来送给游人，在细雨斜风里，她们头上的翠翘被打湿。\n芳草丛生的小洲上长满了香草，这些采莲女又如何能一一认识？\n\n做不到隐居山林，暂时先做个闲官吧，这样尚可得到长期的悠闲胜过暂时的休闲。\n我本来就没有家，不安身在这里又能到哪里去呢?何况就算是故乡，也没有像这里这样优美的湖光山色。', poem_notes = '六月二十七日：指宋神宗熙宁五年（1072）六月二十七日。望湖楼：古建筑名，又叫看经楼。位于杭州西湖畔，五代时吴越王钱弘俶（又名钱弘）所建。醉书：饮酒醉时写下的作品。\n翻墨：打翻的黑墨水，形容云层很黑。遮：遮盖，遮挡。\n白雨：指夏日阵雨的特殊景观，因雨点大而猛，在湖光山色的衬托下，显得白而透明。跳珠：跳动的水珠（珍珠），用“跳珠”形容雨点，说明雨点大，杂乱无序。\n卷地风来：指狂风席地卷来。又如，韩退之《双鸟》诗：“春风卷地起，百鸟皆飘浮。”忽：突然。\n水如天：形容湖面像天空一般开阔而且平静。\n放生鱼鳖：北宋时杭州的官吏曾规定西湖为放生地，不许人打鱼，替皇帝延寿添福。\n“水枕”句：躺在船里看山，不觉得水波起落，只见山头忽上忽下。水枕，等于“载在水面的枕席”。\n风船：指的是“飘荡在风里的船”。裴回：即徘徊。\n乌菱：指老菱。菱角老则壳黑，故名。芡（qiàn）：大型水生植物。\n青菰（gū）：俗称茭白。生于河边、沼泽地。可作蔬菜。其实如米，称雕胡米，可作饭。\n尝新：古代于孟秋以新收获的五谷祭祀祖先，然后尝食新谷。\n游女：出游的女子。 木兰桡：常用为船的美称，并非实指木兰木所制。桡（ráo）：划船的桨，这里指小船。\n翠翘：古代妇女首饰的一种，状似翠鸟尾上的长羽，故名。\n芳洲：芳草丛生的小洲。杜若：香草名。多年生草本，高一二尺。叶广披针形，味辛香。\n吴儿：指吴地之人，这里也代指采莲女。吴地，指现中国长江下游南岸一带地域的一个总称。\n小隐：谓隐居山林。', poem_appreciation = '第一首诗第一句写云：黑云像打翻了的黑墨水，还未来得及把山遮住。中把乌云比作“翻墨”，形象逼真。第二句写雨：白亮亮的雨点落在湖面溅起无数水花，乱纷纷地跳进船舱。用“跳珠”形容雨点，有声有色。一个“未”字，突出了天气变化之快；一个“跳”字，一个“乱”字，写出了暴雨之大，雨点之急。第三句写风：猛然间，狂风席卷大地，吹得湖面上刹时雨散云飞。“忽”字用得十分轻巧，却突出天色变化之快，显示了风的巨大威力。最后一句写天和水：雨过天晴，风平浪息，诗人舍船登楼，凭栏而望，只见湖面上无入水，水映天，水色和天光一样的明净，一色的蔚蓝。风呢？云呢？统统不知哪儿去了，方才的一切好像全都不曾发生似的。\n\n　　诗人苏轼先在船中，后在楼头，迅速捕捉住湖上急剧变化的自然景物：云翻、雨泻、风卷、天晴，写得有远有近，有动有静，有声有色，有景有情，令人读来油然产生一种身临其境的感觉——仿佛自己也在湖心经历了一场突然来去的阵雨，又来到望湖楼头观赏那水天一色的美丽风光。诗用“翻墨”写出云的来势，用“跳珠”描绘雨的特点，说明是骤雨而不是久雨。“未遮山”是骤雨才有的景象；“卷地风”说明雨过得快的原因，都是如实描写，却分插在第一、第三句中，彼此呼应，烘托得好。最后用“水如天”写一场骤雨的结束，又有悠然不尽的情致。句中又用“白雨”和“黑云”映衬，用“水如天”和“卷地风”对照，用“乱入船“与“未遮山”比较，都显出作者构思时的用心。\n\n　　此诗描绘了望湖楼的美丽雨景。好的诗人善于捕捉自己的灵感，此诗的灵感可谓突现于一个“醉”字上。醉于酒，更醉于山水之美，进而激情澎湃，才赋成即景佳作。才思敏捷的诗人用诗句捕捉到西子湖这一番别具风味的“即兴表演”，绘成一幅“西湖骤雨图”。乌云骤聚，大雨突降，倾刻又雨过天晴，水天一色。又是山，又是水，又是船，这就突出了泛舟西湖的特点。其次，作者用“黑云翻墨”，“白雨跳珠”形成强烈的色彩对比，给人以很强的质感。再次，用“翻墨”写云的来势，用“跳珠”描绘雨点飞溅的情态，以动词前移的句式使比喻运用得灵活生动却不露痕迹。而“卷地风来忽吹散，望湖楼下水如天”两句又把天气由骤雨到晴朗前转变之快描绘得令人心清气爽，眼前陡然一亮，境界大开。\n\n　　第二首诗是写乘船在湖中巡游的情景。北宋时，杭州西湖由政府规定作为放生池。王注引张栻的话说：“天禧四年（指1020年），太子太保判杭州王钦若奏：以西湖为放生池，‘禁捕鱼鸟，为人主祈福。’”这是相当于现代的禁捕禁猎区；所不同的，只是从前有人卖鱼放生，还要弄个“祈福”的名堂罢了。西湖既是禁捕区，所以也是禁植区，私人不得占用湖地种植。诗的开头，就写出这个事实。那些被人放生、自由成长的鱼鳖之类，不但没有受到人的威胁，反而受到人的施与，游湖的人常常会把食饵投放水里，引那些小家伙围拢来吃。便是不去管它们，它们凭着条件反射，也会向人追赶过来。至于满湖的荷花，也没有谁去种植，自己凭着自然力量生长，东边一丛，西边一簇，自开自落，反而显示出一派野趣。\n\n　　然而此诗的趣味却在后面两句。“水枕能令山俯仰”——山本来是不能俯仰的，杜甫有“风雨不动安如山”（《茅屋为秋风所破歌》）的句子，杜牧也有“古训屹如山”（《池州送孟迟》）的说法，苏轼却偏要说“山俯仰”。诗人认为，山是能俯仰的，理由就在“水枕”。所谓“水枕”，就是枕席放在水面上。准确地说，是放在船上。船一颠摆，躺在船上的人就看到山的一俯一仰。这本来并不出奇，许多人都有过这种经验。问题在于诗人把“神通”交给了“水枕”，如同这个“水枕”能有绝大的神力，足以把整座山颠来倒去。这样的构思，就显出了一种妙趣来。\n\n　　“风船解与月裴回”——同样是写出一种在船上泛游的情趣。湖上刮起了风，小船随风飘荡。这也是常见的，不足为奇。人们坐在院子里抬头看月亮，月亮在云朵里慢慢移动，就像在天空里徘徊。因此李白说：“我歌月徘徊，我舞影零乱。”（《月下独酌》）这也不算新奇。不同的地方是，苏轼把船的游荡和月的徘徊轻轻牵拢，拉到一块来，那就生出了新意。船在徘徊，月也在徘徊，但诗人不知是月亮引起船的徘徊，还是船儿逗得月亮也欣然徘徊起来。诗人想，如果是风的力量使船在水上徘徊，那又是什么力量让月亮在天上徘徊呢？还有，这两种徘徊，到底是相同呢还是不同呢？他把“船”和“月”两种“徘徊”联系起来，就产生了许多问题，其中包含了一些哲理，他要定下神来，好好想一想。所以说，诗句写得饶有情趣。\n\n　　第四首诗首句中的“游女”当是采莲女。因为从这一组五首诗看，苏轼应该始终都在望湖楼上，所以木兰桡上的该是“游女”。旁人不可能跳到水里给她们献花。倒是她们近水楼台，可以采了荷花献给别人。所以这第一句是写“游女”们献花给游客。水里采花的“游女”，应该就是采莲女了。天上下雨了，采莲女在湖中，首饰未免被打湿了。“无限芳洲生杜若”，屈原在《湘夫人》里有写过“搴汀洲兮杜若”，杜若代指各种香草。而“香草美人”是楚辞中最重要的意象，倒推可知，楚辞招在这里就是代指“香草”。“吴儿不识楚辞招”，是感慨采莲女不认识《楚辞》中的各种香草。杜甫《归梦》诗中有“梦归归未得，不用楚辞招”之句，“不用楚辞招”切合“有家难回”之意，与这里的“楚辞招”的意思完全不同。', poem_tags = '西湖,写雨' WHERE poem_title = '六月二十七日望湖楼醉书' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '韵译\n听说在飞来峰极高的塔上，鸡鸣时分可看到旭日初升。\n不怕浮云会遮住我的视线，只因为如今我身在最高层。\n\n散译\n\n飞来峰顶有座高耸入云的塔，听说鸡鸣时分可以看见旭日升起。\n不怕层层浮云遮住我那远眺的视野，只因为我站在飞来峰顶，登高望远心胸宽广。', poem_notes = '飞来峰：有两说：一说在浙江绍兴城外的林山。唐宋时其中有座应天塔。传说此峰是从琅即郡东武县飞来的，故名飞来峰。一说在今浙江杭州西湖灵隐寺前。\n千寻塔：很高很高的塔。寻，古时长度单位，八尺为寻。\n闻说：听说。\n浮云：在山间浮动的云雾。望眼：视线。\n缘：因为。', poem_appreciation = '山是高耸的，塔是高耸的，山顶上的塔更是高高耸立的。飞来峰和它上面的宝塔总共多高？不知道。诗人只告诉我们，单是塔身就是八千多尺——这当然是夸张的说法。诗人还讲了一个传说：站在塔上，鸡鸣五更天就可以看见海上日出。请想想飞来峰那耸云天的气势吧！\n\n　　从全诗看，“不畏浮云遮望眼，只缘身在最高层”的胸襟境界，只有登上天外飞来的高峰才能触发得出；但无“闻说鸡鸣见日升”作铺垫，亦引不出此等胸襟境界。\n\n　　只有登上“飞来山上千寻塔”，才能用见日出闻天鸡的故实；也只有在天外飞来的高峰见日出闻天鸡，才能导出不畏末俗乱真、站得高看得远的胆识气概。思绪条贯，勾连紧密；天衣无缝，一气呵成；前后关照，浑然一体。', poem_tags = '古诗三百首,初中古诗,登高,哲理' WHERE poem_title = '登飞来峰' AND poem_author = '王安石';
UPDATE edu_poem SET poem_translation = '秋夜明月清辉，遍洒澄净湖面，湖面平静无风，犹如铁磨铜镜。\n遥望美丽洞庭的湖光山色。真的令人浮想联翩。那翠绿的君山，真像银盘里的一枚玲珑青螺。', poem_notes = '洞庭：湖名，在今湖南省北部。\n湖光：湖面的波光。两：指湖光和秋月。和：和谐。指水色与月光互相辉映。\n潭面：指湖面。镜未磨：古人的镜子用铜制作、磨成。这里一说是湖面无风，水平如镜；一说是远望湖中的景物，隐约不清，如同镜面没打磨时照物模糊。\n山水翠：也作“山水色”。山：指洞庭湖中的君山。\n白银盘：形容平静而又清的洞庭湖面。白银：一作“白云”。青螺：这里用来形容洞庭湖中的君山。', poem_appreciation = '这是诗人遥望洞庭湖而写的风景诗，明白如话而意味隽永。第一句从水光月色的交融不分写起，表现湖面的开阔廖远，这应该是日暮时分的景象，天还没黑但月亮已经出来，如果天黑就看不出两者色彩的融合了。第二句用镜子的比喻表现夜晚湖面的平静，因为太阳已落，湖水不反光，像镜子没磨时光泽暗淡的样子。第三句写远望湖中君山翠绿的色彩，这里的“山水”实际只是指山，即湖中的君山。用“山水”属于古代汉语中“偏义复词”的用法。第四句再用一个比喻，将浮在水中的君山比作搁在白银盘子里的青螺。全诗纯然写景，既有描写的细致，又有比喻的生动，读来饶有趣味。\n\n　　秋夜皎皎明月下的洞庭湖水是澄彻空明的。与素月的清光交相辉映，俨如琼田玉鉴，是一派空灵、缥缈、宁静、和谐的境界。这就是“湖光秋月两相和”一句所包蕴的诗意。“和”字下得工炼，表现出了水天一色、玉宇无尘的融和的画境。而且，似乎还把一种水国之夜的节奏——荡漾的月光与湖水吞吐的韵律，传达给读者了。接下来描绘湖上无风，迷迷蒙蒙的湖面宛如未经磨拭的铜镜。“镜未磨”三字十分形象贴切地表现了千里洞庭风平浪静的安宁温柔的景象，在月光下别具一种朦胧美。“潭面无风镜未磨”以生动形象的比喻补足了“湖光秋月两相和”的诗意。因为只有“潭面无风”，波澜不惊，湖光和秋月才能两相协调。否则，湖面狂风怒号，浊浪排空，湖光和秋月便无法辉映成趣，也就无有“两相和”可言了。\n\n　　三四两句诗想象丰富，比喻恰当，色调淡雅，银盘与青螺互相映衬，相得益彰。诗人笔下的秋月之中的洞庭山水变成了一件精美绝伦的工艺美术珍品，给人以莫大的艺术享受。“白银盘里一青螺”，真是匪夷所思的妙句。然而，它的擅胜之处，不止表现在设譬的精警上，尤其可贵的是它所表现的壮阔不凡的气度和它所寄托的高卓清奇的情致。在诗人眼里，千里洞庭不过是妆楼奁镜、案上杯盘而已。举重若轻，自然凑泊，毫无矜气作色之态，这是十分难得的。把人与自然的关系表现得这样亲切，把湖山的景物描写得这样高旷清超，这正是作者性格、情操和美学趣味的反映。没有荡思八极、纳须弥于芥子的气魄，没有振衣千仞、涅而不缁的襟抱，是难以措笔的。一首山水小诗，见出诗人富有浪漫色彩的奇思壮采，这是很难得的。只有真心观察，才能读出这首诗的情意。', poem_tags = '小学古诗,写景,山水,景点' WHERE poem_title = '望洞庭' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '壬戌年秋，七月十六日，苏轼与友人在赤壁下泛舟游玩。清风阵阵拂来，水面波澜不起。举起酒杯向同伴敬酒，吟诵着与明月有关的文章，歌颂窈窕这一章。不多时，明月从东山后升起，徘徊在斗宿与牛宿之间。白茫茫的雾气横贯江面，清泠泠的水光连着天际。任凭小船儿在茫无边际的江上飘荡，越过苍茫万顷的江面。（我的情思）浩荡，就如同凭空乘风，却不知道在哪里停止，飘飘然如遗弃尘世，超然独立，成为神仙，进入仙境。\n　　这时候喝酒喝得高兴起来，用手叩击着船舷，应声高歌。歌中唱道：“桂木船棹呵香兰船桨，迎击空明的粼波，逆着流水的泛光。我的心怀悠远，想望伊人在天涯那方”。有吹洞箫的客人，按着节奏为歌声伴和，洞箫呜呜作声：像是怨恨，又像是思慕，像是哭泣，又像是倾诉，尾声凄切、婉转、悠长，如同不断的细丝。能使深谷中的蛟龙为之起舞，能使孤舟上的寡妇听了落泪。\n　　苏轼的容色忧愁凄怆，（他）整好衣襟坐端正，向客人问道：“（曲调）为什么这样（悲凉）呢？”同伴回答：“‘月明星稀，乌鹊南飞’，这不是曹公孟德的诗么？（这里）向西可以望到夏口，向东可以望到武昌，山河接壤连绵不绝，（目力所及）一片苍翠。这不正是曹孟德被周瑜所围困的地方么？当初他攻陷荆州，夺得江陵，沿长江顺流东下，麾下的战船延绵千里，旌旗将天空全都蔽住，在江边持酒而饮，横执矛槊吟诗作赋，委实是当世的一代枭雄，而今天又在哪里呢？何况我与你在江边的水渚上捕鱼砍柴，与鱼虾作伴，与麋鹿为友，（我们）驾着这一叶小舟，举起杯盏相互敬酒。（我们）如同蜉蝣置身于广阔的天地中，像沧海中的一颗粟米那样渺小。（唉，）哀叹我们的一生只是短暂的片刻，（不由）羡慕长江没有穷尽。（我想）与仙人携手遨游各地，与明月相拥而永存世间。（我）知道这些不可能屡屡得到，只得将憾恨化为箫音，托寄在悲凉的秋风中罢了。”\n　　苏轼说：“你可也知道这水与月？不断流逝的就像这江水，其实并没有真正逝去；时圆时缺的就像这月，但是最终并没有增加或减少。可见，从事物易变的一面看来，天地间没有一瞬间不发生变化；而从事物不变的一面看来，万物与自己的生命同样无穷无尽，又有什么可羡慕的呢？何况天地之间，凡物各有自己的归属，若不是自己应该拥有的，即令一分一毫也不能求取。只有江上的清风，以及山间的明月，送到耳边便听到声音，进入眼帘便绘出形色，取得这些不会有人禁止，享用这些也不会有竭尽的时候。这是造物者（恩赐）的没有穷尽的大宝藏，你我尽可以一起享用。”\n　　于是同伴高兴的笑了，清洗杯盏重新斟酒。菜肴和果品都被吃完，只剩下桌上的杯碟一片凌乱。（苏子与同伴）在船里互相枕着垫着睡去，不知不觉天边已经显出白色（指天明了）。', poem_notes = '选自《经进东坡文集事略》卷一(《四部丛刊》本），这篇散文作于宋神宗元丰五年（1082），在此之前苏轼因乌台诗案（元丰二年）被贬谪黄州（今湖北黄冈）。因后来还写过一篇同题的赋，故称此篇为《前赤壁赋》，十月十五日写的那篇为《后赤壁赋》。赤壁：实为黄州赤鼻矶，并不是三国时期赤壁之战的旧址，当地人因音近亦称之为赤壁，苏轼知道这一点，将错就错，借景以抒发自己的怀抱。\n壬戌：宋神宗元丰五年（1082），岁在壬戌。\n既望：既，过了；望，农历十五日。“既望”指农历十六日。\n徐：舒缓地。\n兴：起，作。\n属：通“嘱（zhǔ ），致意，此处引申为“劝酒”的意思。\n少焉：一会儿。\n白露：白茫茫的水气。横江：笼罩江面。横，横贯。\n纵一苇之所如，凌万顷之茫然：任凭小船在宽广的江面上飘荡。纵：任凭。一苇：像一片苇叶那么小的船，比喻极小的船。《诗经·卫风·河广》：“谁谓河广，一苇杭（航）之。“如：往，去。凌：越过。万顷：形容江面极为宽阔。茫然，旷远的样子。\n冯虚御风：（像长出羽翼一样）驾风凌空飞行。冯：通“凭“，乘。虚：太空。御：驾御（驭）。\n遗世独立：遗弃尘世,独自存在。\n扣舷：敲打着船边，指打节拍，舷，船的两边。\n击空明兮溯流光：船桨拍打着月光浮动的清澈的水，溯流而上。溯：逆流而上。空明、流光：指月光浮动清澈的江水。\n渺渺兮予怀：主谓倒装。我的心思飘得很远很远。渺渺，悠远的样子。化用目眇眇兮愁予__《湘夫人》怀，心中的情思。\n美人：此为苏轼借鉴的屈原的文体。用美人代指君主。古诗文多以指自己所怀念向往的人。\n倚歌而和(hè)之：合着节拍应和。倚：随，循 和：应和。\n如怨如慕，如泣如诉：像是哀怨，像是思慕，像是啜泣，像是倾诉。怨：哀怨。慕：眷恋。\n余音：尾声。袅袅：形容声音婉转悠长。\n缕：细丝。\n舞幽壑之潜蛟：幽壑：这里指深渊。此句意谓：使深谷的蛟龙感动得起舞。\n泣孤舟之嫠（lí 离）妇：使孤舟上的寡妇伤心哭泣。嫠：孤居的妇女，在这里指寡妇。\n愀（qiǎo 巧）然：容色改变的样子。\n正襟危坐：整理衣襟，严肃地端坐着 危坐：端坐。\n何为其然也：曲调为什么会这么悲凉呢？\n月明星稀，乌鹊南飞：所引是曹操《短歌行》中的诗句。\n缪：通“缭“盘绕。\n郁乎苍苍：树木茂密，一片苍绿繁茂的样子。郁：茂盛的样子。\n舳舻（zhú lú 逐卢）：战船前后相接。这里指战船。\n酾（shī）酒：斟酒。\n横槊（shuò ）：横执长矛。\n侣鱼虾而友麋鹿：以鱼虾为伴侣，以麋鹿为友。侣 ：以...为伴侣，这里是名词的意动用法。麋（mí）：鹿的一种。\n扁（piān ）舟：小舟。\n寄：寓托。\n蜉（fú)蝣：一种昆虫，夏秋之交生于水边，生命短暂，仅数小时。此句比喻人生之短暂。\n渺沧海之一粟：渺：小。沧海：大海。此句比喻人类在天地之间极为渺小。\n须臾(yú)：片刻，时间极短。\n长终：至于永远。\n骤：数次。\n托遗响于悲风：余音，指箫声。悲风：秋风。\n逝者如斯：语出《论语·子罕》：“子在川上曰：\'逝者如斯夫，不舍昼夜。\'“逝：往。斯：此，指水。\n盈虚者如彼：指月亮的圆缺。\n卒：最终。消长：增减。长：增长\n则天地曾不能以一瞬：语气副词。以：用。一瞬：一眨眼的工夫。\n是造物者之无尽藏也：这。造物者：天地自然。无尽藏（zàng ）：佛家语。指无穷无尽的宝藏。\n共食：共享。苏轼手中《赤壁赋》作“共食”，明代以后多“共适”，义同\n更酌：再次饮酒。\n肴核既尽：荤菜和果品。既：已经。\n狼籍：又写作“狼藉”，凌乱的样子。\n枕藉：相互枕着垫着。\n既白：已经显出白色（指天明了）。', poem_appreciation = '此赋通过月夜泛舟、饮酒赋诗引出主客对话的描写，既从客之口中说出了吊古伤今之情感，也从苏子所言中听到矢志不移之情怀，全赋情韵深致、理意透辟，实是文赋中之佳作。\n\n　　第一段，写夜游赤壁的情景。作者“与客泛舟游于赤壁之下”，投入大自然怀抱之中，尽情领略其间的清风、白露、高山、流水、月色、天光之美，兴之所至，信口吟诵《诗经·月出》首章“月出皎兮，佼人僚兮。舒窈纠兮，劳心悄兮。”把明月比喻成体态娇好的美人，期盼着她的冉冉升起。与《月出》诗相回应，“少焉，月出于东山之上，徘徊于斗牛之间。”并引出下文作者所自作的歌云：“望美人兮天一方”，情感、文气一贯。“徘徊”二字，生动、形象地描绘出柔和的月光似对游人极为依恋和脉脉含情。在皎洁的月光照耀下白茫茫的雾气笼罩江面，天光、水色连成一片，正所谓“秋水共长天一色”（王勃《滕王阁序》）。游人这时心胸开阔，舒畅，无拘无束，因而“纵一苇之所如，凌万顷之茫然”，乘着一叶扁舟，在“水波不兴”浩瀚无涯的江面上，随波飘荡，悠悠忽忽地离开世间，超然独立。浩瀚的江水与洒脱的胸怀，在作者的笔下腾跃而出，泛舟而游之乐，溢于言表。这是此文正面描写“泛舟”游赏景物的一段，以景抒情，融情入景，情景俱佳。\n\n　　第二段，写作者饮酒放歌的欢乐和客人悲凉的箫声。作者饮酒乐极，扣舷而歌，以抒发其思“美人”而不得见的怅惘、失意的胸怀。这里所说的“美人”实际上乃是作者的理想和一切美好事物的化身。歌曰：“桂棹兮兰桨，击空明兮溯流光。渺渺兮予怀，望美人兮天一方。”这段歌词全是化用《楚辞·少司命》：“望美人兮未来，临风恍兮浩歌”之意，并将上文“诵明月之诗，歌窈窕之章”的内容具体化了。由于想望美人而不得见，已流露了失意和哀伤情绪，加之客吹洞箫，依其歌而和之，箫的音调悲凉、幽怨，“如怨如慕，如泣如诉，余音袅袅，不绝如缕”，竟引得潜藏在沟壑里的蛟龙起舞，使独处在孤舟中的寡妇悲泣。一曲洞箫，凄切婉转，其悲咽低回的音调感人至深，致使作者的感情骤然变化，由欢乐转入悲凉，文章也因之波澜起伏，文气一振。\n\n　　第三段，写客人对人生短促无常的感叹。此段由赋赤壁的自然景物，转而赋赤壁的历史古迹。主人以“何为其然也”设问，客人以赤壁的历史古迹作答，文理转折自然。但文章并不是直陈其事，而是连用了两个问句。首先以曹操的《短歌行》问道：“此非曹孟德之诗乎？”又以眼前的山川形胜问道：“此非孟德之困于周郎者乎？”两次发问使文章又泛起波澜。接着，追述了曹操破荆州、迫使刘琮投降的往事。当年，浩浩荡荡的曹军从江陵沿江而下，战船千里相连，战旗遮天蔽日。曹操志得意满，趾高气扬，在船头对江饮酒，横槊赋诗，可谓“一世之雄”。如今他在哪里呢？曹操这类英雄人物，也只是显赫一时，何况是自己，因而如今只能感叹自己生命的短暂，羡慕江水的长流不息，希望与神仙相交，与明月同在。但那都是不切实际的幻想，所以才把悲伤愁苦“托遗响于悲风”，通过箫声传达出来。客的回答表现了一种虚无主义思想和消极的人生观，这是苏轼借客人之口流露出自己思想的一个方面。\n\n　　第四段，是苏轼针对客之人生无常的感慨陈述自己的见解，以宽解对方。客曾“羡长江之无穷”，愿“抱明月而长终”。苏轼即以江水、明月为喻，提出“逝者如斯，而未尝往也；盈虚者如彼，而卒莫消长也”的认识。如果从事物变化的角度看，天地的存在不过是转瞬之间；如果从不变的角度看，则事物和人类都是无穷尽的，不必羡慕江水、明月和天地。自然也就不必“哀吾生之须臾”了。这表现了苏轼豁达的宇宙观和人生观，他赞成从多角度看问题而不同意把问题绝对化，因此，他在身处逆境中也能保持豁达、超脱、乐观和随缘自适的精神状态，并能从人生无常的怅惘中解脱出来，理性地对待生活。而后，作者又从天地间万物各有其主、个人不能强求予以进一步的说明。江上的清风有声，山间的明月有色，江山无穷，风月长存，天地无私，声色娱人，作者恰恰可以徘徊其间而自得其乐。此情此景乃缘于李白的《襄阳歌》：“清风明月不用一钱买，玉山自倒非人推”，进而深化之。\n\n　　第五段，写客听了作者的一番谈话后，转悲为喜，开怀畅饮，“相与枕藉乎舟中，不知东方之既白”。照应开头，极写游赏之乐，而至于忘怀得失、超然物外的境界。\n\n　　这篇赋在艺术手法上有如下特点：\n\n　　“情、景、理”融合。全文不论抒情还是议论始终不离江上风光和赤壁故事，形成了情、景、理的融合。通篇以景来贯串，风和月是主景，山和水辅之。作者抓住风和月展开描写与议论。文章分三层来表现作者复杂矛盾的内心世界：首先写月夜泛舟大江，饮酒赋诗，使人沉浸在美好景色之中而忘怀世俗的快乐心情；再从凭吊历史人物的兴亡，感到人生短促，变动不居，因而跌入现实的苦闷；最后阐发变与不变的哲理，申述人类和万物同样是永久地存在，表现了旷达乐观的人生态度。写景、抒情、说理达到了水乳交融的程度。\n\n　　“以文为赋”的体裁形式。此文既保留了传统赋体的那种诗的特质与情韵，同时又吸取了散文的笔调和手法，打破了赋在句式、声律的对偶等方面的束缚，更多是散文的成分，使文章兼具诗歌的深致情韵，又有散文的透辟理念。散文的笔势笔调，使全篇文情郁郁顿挫，如“万斛泉涌”喷薄而出。与赋的讲究对偶不同，它相对更为自由，如开头的一段“壬戌之秋，七月既望，苏子与客泛舟游于赤壁之下”，全是散句，参差疏落之中又有整饬之致。以下直至篇末，大多押韵，但换韵较快，而且换韵处往往就是文意的一个段落，这就使本文特别宜于诵读，并且极富声韵之美，体现了韵文的长处。\n\n　　意象连贯，结构严谨。景物的连贯，不仅在结构上使全文俨然一体，精湛缜密，而且还沟通了全篇的感情脉络，起伏变化。起始时写景，是作者旷达、乐观情状的外观；“扣舷而歌之”则是因“空明”、“流光”之景而生，由“乐甚”向“愀然”的过渡；客人寄悲哀于风月，情绪转入低沉消极；最后仍是从眼前的明月、清风引出对万物变异、人生哲理的议论，从而消释了心中的感伤。景物的反复穿插，丝毫没有给人以重复拖沓的感觉，反而在表现人物悲与喜的消长的同时再现了作者矛盾心理的变化过程，最终达到了全文诗情画意与议论理趣的完美统一。', poem_tags = '辞赋精选,高中文言文,古文观止,写景,饮酒,感叹,哲理' WHERE poem_title = '前赤壁赋' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '滚滚长江向东流，多少英雄像翻飞的浪花般消逝。\n不管是与非，还是成与败（古今英雄的功成名就），到现在都是一场空，都已经随着岁月的流逝消逝了。\n当年的青山（江山）依然存在，太阳依然日升日落。\n在江边的白发隐士，早已看惯了岁月的变化。\n和老友难得见了面，痛快地畅饮一杯酒。\n古往今来的多少事，都付诸于（人们的）谈笑之中。', poem_notes = '淘尽：荡涤一空。 \n渔樵：此处并非指渔翁、樵夫，联系前后文的语境而为动词：隐居。此处作名词，指隐居不问世事的人。\n渚（zhǔ）：原意为水中的小块陆地，此处意为江岸边。\n蓦（mù）：愿意为上马、超越，此处意为“突然”。\n在廿一史弹词第三段《 说秦汉》中，原文共11句，因为受各影视、文学、音乐等作品（主要是三国演义）的影响，广为流传的是前四句。', poem_appreciation = '词的开首两句令人想到杜甫的“无边落木萧萧下，不尽长江滚滚来”和苏轼的“大江东去，浪淘尽，千古风流人物”，以一去不返的江水比喻历史的进程，用后浪推前浪来比喻英雄叱咤风云的丰功伟绩。然而这一切终将被历史的长河带走。“是非成败转头空”是对上两句历史现象的总结，从中也可看出作者旷达超脱的人生观。“青山依旧在，几度夕阳红”，青山和夕阳象征着自然界和宇宙的亘古悠长，尽管历代兴亡盛衰、循环往复，但青山和夕阳都不会随之改变，一种人生易逝的悲伤感悄然而生。\n\n　　词中“长江”、“逝水”、“浪花”、“英雄”、“青山”、“夕阳”、“渔樵”、“江渚”、“秋月”、“春风”、“浊酒”，意境高远而淡泊。衬托这些意象的还有“滚滚”、“淘尽”、“转头空”、“依旧在”、“几度”、“惯看”、“喜相逢”、“笑谈”这些生动的字眼，给这首词宁静的气氛中增加了几份动感。', poem_tags = '咏史,抒怀,人生,哲理' WHERE poem_title = '临江仙·滚滚长江东逝水' AND poem_author = '杨慎';
UPDATE edu_poem SET poem_translation = '桃花怒放千万朵，色彩鲜艳红似火。这位姑娘要出嫁，喜气洋洋归夫家。\n桃花怒放千万朵，果实累累大又多。这位姑娘要出嫁，早生贵子后嗣旺。\n桃花怒放千万朵，绿叶茂盛永不落。这位姑娘要出嫁，齐心协手家和睦。', poem_notes = '夭夭：花朵怒放，美丽而繁华的样子。\n灼灼：花朵色彩鲜艳如火，明亮鲜艳的样子。华：同“花”。\n之子：这位姑娘。于归：姑娘出嫁。古代把丈夫家看作女子的归宿，故称“归”。于：去，往。\n宜：和顺、亲善。\n蕡（fén）：草木结实很多的样子。此处指桃实肥厚肥大的样子。有蕡即蕡蕡。\n蓁（zhēn）：草木繁密的样子，这里形容桃叶茂盛。', poem_appreciation = '这是一首祝贺年青姑娘出嫁的诗。据《周礼》云：“仲春，令会男女。”周代一般在春光明媚桃花盛开的时候姑娘出嫁，故诗人以桃花起兴，为新娘唱了一首赞歌。旧说如《毛序》等以为与后妃君王有关，为今人所不取。\n\n　　全诗分为三章。第一章以鲜艳的桃花比喻新娘的年青娇媚。人们常说：第一个用花比美人的是天才，第二个用花比美人的是庸才，第三个用花比美人的是蠢才。《诗经》是中国第一部诗歌总集，所以说这里是第一个用花来比美人，并不为过。自此以后用花、特别是用桃花来比美人的层出不穷，如魏·阮籍《咏怀·昔日繁华子》：“天天桃李花，灼灼有辉光。”唐·崔护《题都城南庄》：“去年今日此门中，人面桃花相映红。”宋·陈师道《菩萨蛮》词：“玉腕枕香腮，桃花脸上开。”他们皆各有特色，自然不能贬之为庸才、蠢才，但他们无不受到《诗经》这首诗的影响，只不过影响有大小，运用有巧妙而已。这里所写的是鲜嫩的桃花，纷纷绽蕊，而经过打扮的新嫁娘此刻既兴奋又羞涩，两颊飞红，真有人面桃花，两相辉映的韵味。诗中既写景又写人，情景交融，烘托了一股欢乐热烈的气氛。这种场面，即使在今天还能在农村的婚礼上看到。第二章则是表示对婚后的祝愿。桃花开后，自然结果。诗人说它的果子结得又肥又大，此乃象征着新娘早生贵子，养个白白胖胖的娃娃。第三章以桃叶的茂盛祝愿新娘家庭的兴旺发达。以桃树枝头的累累硕果和桃树枝叶的茂密成荫，来象征新嫁娘婚后生活的美满幸福，真是最美的比喻，最好的颂辞。朱熹《诗集传》认为每一章都是用的“兴”，固然有理，然细玩诗意，确是兴中有比，比兴兼用。全诗三章，每章都先以桃起兴，继以花、果、叶兼作比喻，极有层次：由花开到结果，再由果落到叶盛；所喻诗意也渐次变化，与桃花的生长相适应，自然浑成，融为一体。\n\n　　诗人在歌咏桃花之后，更以当时的口语，道出贺辞。第一章云：“之子于归，宜其室家。”也就是说这位姑娘要出嫁，和和美美成个家。第二、三章因为押韵关系，改为“家室”和“家人”，其实含义很少区别。古礼男以女为室，女以男为家，男女结合才组成家庭。女子出嫁，是组成家庭的开始。朱熹《诗集传》释云：“宜者，和顺之意。室谓夫妇所居，家谓一门之内。”实际上是说新婚夫妇的小家为室，而与父母等共处为家。今以现代语释为家庭，更易为一般读者所了解。\n\n　　此篇语言极为优美，又极为精炼。不仅巧妙地将“室家”变化为各种倒文和同义词，而且反覆用一“宜”字。一个“宜”字，揭示了新嫁娘与家人和睦相处的美好品德，也写出了她的美好品德给新建的家庭注入新鲜的血液，带来和谐欢乐的气氛。这个“宜”字，掷地有声，简直没有一个字可以代替。\n\n　　对《国风·周南·桃夭》一诗的主旨，也有人提出了新的说法，认为这首诗是先民进行驱鬼祭祀时的唱词，其内容是驱赶鬼神，使之回到归处，并祈求它赐福人间亲人。', poem_tags = '古诗三百首,诗经,桃花,民谣' WHERE poem_title = '桃夭' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '清晨，朝霞满天，我就要踏上归程。从江上往高处看，可以看见白帝城彩云缭绕，如在云间，景色绚丽！千里之遥的江陵，一天之间就已经到达。\n两岸猿猴的啼声不断，回荡不绝。猿猴的啼声还回荡在耳边时，轻快的小船已驶过连绵不绝的万重山峦。\n\n译文二\n清晨，我告别高入云霄的白帝城江陵远在千里，船行只一日时间。\n两岸猿声，还在耳边不停地啼叫不知不觉，轻舟已穿过万重青山。', poem_notes = '发：启程。白帝城：故址在今重庆市奉节县白帝山上。杨齐贤注：“白帝城，公孙述所筑。初，公孙述至鱼复，有白龙出井中，自以承汉土运，故称白帝，改鱼复为白帝城。”王琦注：“白帝城，在夔州奉节县，与巫山相近。所谓彩云，正指巫山之云也。”\n朝：早晨。辞：告别。彩云间：因白帝城在白帝山上，地势高耸，从山下江中仰望，仿佛耸入云间。\n江陵：今湖北荆州市。从白帝城到江陵约一千二百里，其间包括七百里三峡。郦道元《三峡》：“自三峡七百里中，两岸连山，略无阙处。重岩叠障，隐天蔽日，自非亭午时分，不见曦月。至于夏水襄陵，沿溯（或泝）阻绝。或王命急宣，有时朝发白帝，暮到江陵，其间千二百时里，虽乘奔御风，不以疾也。春冬之时，则素湍绿潭，回清倒影。绝巘（或巚）多生怪柏，悬泉瀑布，飞漱其间。清荣峻茂，良多趣味。每至晴初霜旦，林寒涧肃，常有高猿长啸，属引凄异。空谷传响，哀啭久绝。故渔者歌曰：‘巴东三峡巫峡长，猿鸣三声泪沾裳。’”还：归；返回。\n猿：猿猴。啼：鸣、叫。住：停息。\n万重山：层层叠叠的山，形容有许多。', poem_appreciation = '首句“彩云间”三字，描写白帝城地势之高，为全篇描写下水船走得快这一动态蓄势。“彩云间”的“间”字当作隔断之意，诗人回望云霞之上的白帝城，以前的种种恍如隔世。一说形容白帝城之高，水行船速全在落差。如果不写白帝城之高，则无法体现出长江上下游之间斜度差距之大。白帝城地势高入云霄，于是下面几句中写舟行的迅捷、行期的短暂、耳（猿声）目（万重山）的不暇迎送，才一一有着落。“彩云间”也是写早晨景色，显示出从晦暝转为光明的大好气象，而诗人便在这曙光初灿的时刻，怀着兴奋的心情匆匆告别白帝城。\n\n　　第二句的“千里”和“一日”，以空间之远与时间之短作悬殊对比。这里，巧妙的地方在于那个“还”字上。“还”，归来的意思。它不仅表现出诗人“一日”而行“千里”的痛快，也隐隐透露出遇赦的喜悦。江陵本非李白的家乡，而“还”字却亲切得如同回乡一样。一个“还”字，暗处传神，值得读者细细玩味。\n\n　　第三句的境界更为神妙。古时长江三峡，“常有高猿长啸”。诗人说“啼不住”，是因为他乘坐飞快的轻舟行驶在长江上，耳听两岸的猿啼声，又看见两旁的山影，猿啼声不止一处，山影也不止一处，由于舟行人速，使得啼声和山影在耳目之间成为“浑然一片”，这就是李白在出峡时为猿声山影所感受的情景。身在这如脱弦之箭、顺流直下的船上，诗人感到十分畅快和兴奋。清代桂馥称赞：“妙在第三句，能使通首精神飞越。”（《札朴》）\n\n　　瞬息之间，“轻舟”已过“万重山”。为了形容船快，诗人除了用猿声山影来烘托，还给船的本身添上了一个“轻”字。直说船快，那便显得笨拙；而这个“轻”字，却别有一番意蕴。三峡水急滩险，诗人溯流而上时，不仅觉得船重，而且心情更为滞重，“三朝上黄牛，三暮行太迟。三朝又三暮，不觉鬓成丝”（《上三峡》）。如今顺流而下，行船轻如无物，船的快速读者可想而知。而“危乎高哉”的“万重山”一过，轻舟进入坦途，诗人历尽艰险、进入康庄旅途的快感，也自然而然地表现出来了。这最后两句，既是写景，又是比兴，既是个人心情的表达，又是人生经验的总结，因物兴感，精妙无伦。\n\n　　全诗给人一种锋棱挺拔、空灵飞动之感。然而只看这首诗的气势的豪爽，笔姿的骏利，还不能完备地理解全诗。全诗洋溢的是诗人经过艰难岁月之后突然迸发的一种激情，所以在雄峻和迅疾中，又有豪情和欢悦。快船快意，给读者留下了广阔的想象余地。为了表达畅快的心情，诗人还特意用上平“删”韵的“间”、“还”、“山”来作韵脚，使全诗显得格外悠扬、轻快，回味悠长。', poem_tags = '唐诗三百首,写山,长江,地名,喜悦,早教古诗100首' WHERE poem_title = '早发白帝城 / 白帝下江陵' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '永和九年，时在癸丑之年，三月上旬，我们会集在会稽郡山阴城的兰亭，为了做禊事。众多贤才都汇聚到这里，年龄大的小的都聚集在这里。兰亭这个地方有高峻的山峰，茂盛的树林，高高的竹子。又有清澈湍急的溪流，辉映环绕在亭子的四周，我们引溪水作为流觞的曲水，排列坐在曲水旁边，虽然没有演奏音乐的盛况，但喝点酒，作点诗，也足够来畅快叙述幽深内藏的感情了。\n\n　　这一天，天气晴朗，空气清新，和风温暖，仰首观览到宇宙的浩大，俯看观察大地上众多的万物，用来舒展眼力，开阔胸怀，足够来极尽视听的欢娱，实在很快乐。\n\n　　人与人相互交往，很快便度过一生。有的人在室内畅谈自己的胸怀抱负；有的人就着自己所爱好的事物，寄托情怀，放纵无羁地生活。虽然各有各的爱好，安静与躁动各不相同，但当他们对所接触的事物感到高兴时，一时感到自得。感到高兴和满足，竟然不知道衰老将要到来。等到对得到或喜爱的东西已经厌倦，感情随着事物的变化而变化，感慨随之产生。过去所喜欢的东西，转瞬间，已经成为旧迹，尚且不能不因为它引发心中的感触，况且寿命长短，听凭造化，最后归结于消灭。古人说：“死生毕竟是件大事啊。”怎么能不让人悲痛呢？\n\n　　每当看到前人所发感慨的原因，其缘由像一张符契那样相和，总难免要在读前人文章时叹息哀伤，不能明白于心。本来知道把生死等同的说法是不真实的，把长寿和短命等同起来的说法是妄造的。后人看待今人，也就像今人看待前人，可悲呀。所以一个一个记下当时与会的人，录下他们所作的诗篇。纵使时代变了，事情不同了，但触发人们情怀的原因，他们的思想情趣是一样的。后世的读者，也将对这次集会的诗文有所感慨。', poem_notes = '永和：东晋皇帝司马聃（晋穆帝）的年号，从公元345—356年共12年。永和九年上巳节，王羲之与谢安，孙绰等41人。举行禊礼，饮酒赋诗，事后将作品结为一集，由王羲之写了这篇序总述其事。\n暮春：阴历三月。暮，晚。\n会：集会。\n会稽（kuài jī）：郡名，今浙江绍兴。\n山阴：今绍兴越城区。\n修禊（xì）事也：（为了做）禊礼这件事。古代习俗，于阴历三月上旬的巳日（魏以后定为三月三日），人们群聚于水滨嬉戏洗濯，以祓除不祥和求福。实际上这是古人的一种游春活动。\n群贤：诸多贤士能人。指谢安等三十二位社会的名流。贤：形容词做名词。\n毕至：全到。毕，全、都。\n少长：如王羲之的儿子王凝之、王徽之是少；谢安、王羲之等是长。\n咸：都。\n崇山峻岭：高峻的山岭。\n修竹：高高的竹子。修，高高的样子。\n激湍：流势很急的水。\n映带左右：辉映点缀在亭子的周围。映带，映衬、围绕。\n流觞（shāng）曲（qū）水：用漆制的酒杯盛酒，放入弯曲的水道中任其飘流，杯停在某人面前，某人就引杯饮酒。这是古人一种劝酒取乐的方式。流，使动用法。曲水，引水环曲为渠，以流酒杯。\n列坐其次：列坐在曲水之旁。列坐，排列而坐。次，旁边，水边。\n丝竹管弦之盛：演奏音乐的盛况。盛，盛大。\n一觞一咏：喝着酒作着诗。\n幽情：幽深内藏的感情。\n是日也：这一天。\n惠风：和风。\n和畅，缓和。\n品类之盛：万物的繁多。品类，指自然界的万物。\n所以：用来。\n骋：使······奔驰。\n极：穷尽。\n信：实在。\n夫人之相与，俯仰一世：人与人相交往，很快便度过一生。夫，句首发语词，不译。相与，相处、相交往。俯仰，表示时间的短暂。\n取诸：取之于，从······中取得。\n悟言：面对面的交谈。悟，通“晤”，指心领神会的妙悟之言。\n因寄所托，放浪形骸之外：就着自己所爱好的事物，寄托自己的情怀，不受约束，放纵无羁的生活。因，依、随着。寄，寄托。所托，所爱好的事物。放浪，放纵、无拘束。形骸，身体、形体。\n趣（qǔ）舍万殊：各有各的爱好。趣舍，即取舍，爱好。趣，通“取”。万殊，千差万别。\n静躁：安静与躁动。\n暂：短暂，一时。\n快然自足：感到高兴和满足。然，······的样子。\n不知老之将至：（竟）不知道衰老将要到来。语出《论语·述而》：“其为人也，发愤忘食，乐以忘忧，不知老之将至云尔。”一本有“曾”在句前。\n所之既倦：（对于）所喜爱或得到的事物已经厌倦。之，往、到达。\n情随事迁：感情随着事物的变化而变化。迁，变化。\n感慨系之：感慨随着产生。系，附着。\n向：过去、以前。\n陈迹：旧迹。\n以之兴怀：因它而引起心中的感触。以，因。之，指“向之所欣……以为陈迹”。兴，发生、引起。\n修短随化：寿命长短听凭造化。化，自然。\n期：至，及。\n死生亦大矣：死生是一件大事啊。语出《庄子·德充符》。\n契：符契，古代的一种信物。在符契上刻上字，剖而为二，各执一半，作为凭证。\n临文嗟（jiē）悼：读古人文章时叹息哀伤。临，面对。\n喻：明白。\n固知一死生为虚诞，齐彭殇为妄作：本来知道把死和生等同起来的说法是不真实的，把长寿和短命等同起来的说法是妄造的。固，本来、当然。一，把……看作一样；齐，把……看作相等，都用作动词。虚诞，虚妄荒诞的话。殇，未成年死去的人。妄作，妄造、胡说。一生死，齐彭殇，都是庄子的看法。出自《齐物论》。\n列叙时人：一个一个记下当时与会的人。\n录其所述：录下他们作的诗。\n其致一也：人们的思想情趣是一样的。\n后之览者：后世的读者。\n斯文：这次集会的诗文。', poem_appreciation = '《兰亭集序》，又题为《临河序》、《禊帖》、《三月三日兰亭诗序》等。晋穆帝永和九年（公元353）三月三日，时任会稽内史的王羲之与友人谢安、孙绰等四十一人会聚兰亭，赋诗饮酒。王羲之将诸人名爵及所赋诗作编成一集，并作序一篇，记述流觞曲水一事，并抒写由此而引发的内心感慨。这篇序文就是《兰亭集序》。此序受石崇《金谷诗序》影响很大，其成就又远在《金谷诗序》之上。《兰亭集序》.\n\n　　文章首先记述了集会的时间、地点及与会人物，言简意赅。接着描绘兰亭所处的自然环境和周围景物，语言简洁而层次井然。描写景物，从大处落笔，由远及近，转而由近及远，推向无限。先写崇山峻岭，渐写清流激湍，再顺流而下转写人物活动及其情态，动静结合。然后再补写自然物色，由晴朗的碧空和轻扬的春风，自然地推向寥廓的宇宙及大千世界中的万物。意境清丽淡雅，情调欢快畅达。兰亭宴集，真可谓“四美俱，二难并”。\n\n　　但天下没有不散的宴席，有聚合必有别离，所谓“兴尽悲来”当是人们常有的心绪，尽管人们取舍不同，性情各异。刚刚对自己所向往且终于获致的东西感到无比欢欣时，但刹那之间，已为陈迹。人的生命也无例外，所谓“不知老之将至”（孔子语）、“老冉冉其将至兮”（屈原语）、“人生天地间，奄忽若飙尘”（《古诗十九首》），这不能不引起人的感慨。每当想到人的寿命不论长短，最终归于寂灭时，更加使人感到无比凄凉和悲哀。如果说前一段是叙事写景，那么这一段就是议论和抒情。作者在表现人生苦短、生命不居的感叹中，流露着一腔对生命的向往和执着的热情。\n\n　　魏晋时期，玄学清谈盛行一时，士族文人多以庄子的“齐物论”为口实，故作放旷而不屑事功。王羲之也是一个颇具辩才的清谈文人，但在政治思想和人生理想上，王羲之与一般谈玄文人不同。他曾说过：“虚谈废务，浮文妨要”（《世说新语·言语篇》）在这篇序中，王羲之也明确地指斥“一死生”、“齐彭殇”是一种虚妄的人生观，这就明确地肯定了生命的价值。\n\n　　这篇文章具有清新朴实、不事雕饰的风格。语言流畅，清丽动人，与魏晋时期模山范水之作“俪采百字之偶，争价一句之奇”（《文心雕龙·明诗篇》）迥然不同。句式整齐而富于变化，以短句为主，在散句中参以偶句，韵律和谐，乐耳动听。\n\n　　总之，这篇文章体现了王羲之积极入世的人生观，和老庄学说主张的无为形成了鲜明的对比。给后人以启迪、思考。', poem_tags = '高中文言文,古文观止,宴饮,离别,感伤,感叹,人生' WHERE poem_title = '兰亭集序 / 兰亭序' AND poem_author = '王羲之';
UPDATE edu_poem SET poem_translation = '六国的君主灭亡了，全国（为秦所）统一；蜀地的山（树木被砍尽，）光秃秃的，阿房宫建造出来了。它（面积广大，）覆压着三百多里地面，（宫殿高耸，）把天日都隔离了。它从骊山向北建筑，再往西转弯，一直走向咸阳。渭水、樊川浩浩荡荡的，流进宫墙里边。五步一座楼，十步一个阁，走廊如绸带般萦回，牙齿般排列的飞檐像鸟嘴向高处啄着。楼阁各依地势的高低倾斜而建筑，（低处的屋角）钩住（高处的）屋心，（并排相向的）屋角彼此相斗。盘结交错，曲折回旋，（远观鸟瞰，）建筑群如密集的蜂房，如旋转的水涡，高高地耸立着，不知道它有几千万座。没有起云，为什么有龙？原来是一座长桥躺在水波上。不是雨过天晴，为什么出虹？原来是天桥在空中行走。（房屋）忽高忽低，幽深迷离，使人不能分辨东西。歌台上由于歌声响亮而充满暖意，有如春光融和；舞殿上由于舞袖飘拂而充满寒意，有如风雨凄凉。一天里边，一座宫殿中间，气候却不一样。\n\n　　六国的宫妃和王子王孙。辞别六国的宫楼，走下六国的宫殿，坐着辇车来到秦国。他们早上歌唱，晚上奏乐，成为秦国的宫人。明亮的星星晶莹闪烁，这是宫妃们打开了梳妆的镜子；乌青的云朵纷纷扰扰，这是宫妃们在梳理晨妆的发髻；渭水涨起一层油腻，这是宫妃们抛弃了的胭脂水；烟霭斜斜上升，云雾横绕空际，这是宫中在焚烧椒、兰制的香料；雷霆突然震响，这是宫车驶过去了；辘辘的车声越听越远，无影无踪，不知道它去到什么地方。每一片肌肤，每一种容颜，都美丽娇媚得无以复加。宫妃们久久地站着，远远地探视，盼望着皇帝来临。有的宫女竟整整三十六年没能见到皇帝。\n\n　　燕赵收藏的金玉，韩魏营谋的珍宝，齐楚的精华物资，在多少世代多少年中，从他们的人民那里掠夺来，堆叠得像山一样。一下子不能保有了，都运送到阿房宫里边来。宝鼎被当作铁锅，美玉被当作顽石，黄金被当作土块，珍珠被当作沙砾，丢弃得到处接连不断，秦人看起来，也并不觉得可惜。\n\n　　唉，一个人的意愿，也就是千万人的意愿啊。秦皇喜欢繁华奢侈，人民也顾念他们自己的家。为什么掠取珍宝时连一锱一铢都搜刮干净，耗费起珍宝来竟像对待泥沙一样。（秦皇如此奢侈浪费，）致使承担栋梁的柱子，比田地里的农夫还多；架在梁上的椽子，比织机上的女工还多；梁柱上的钉头光彩耀目，比粮仓里的粟粒还多；瓦楞长短不一，比全身的丝缕还多；或直或横的栏杆，比九州的城郭还多；管弦的声音嘈杂，比市民的言语还多。使天下的人民，口里不敢说，心里却敢愤怒。（可是）失尽人心的秦始皇的思想，一天天更加骄傲顽固。（结果）戍边的陈涉、吴广一声呼喊，函谷关被攻下，楚项羽放一把火，可惜（华丽的阿房宫）化为了一片焦土。\n\n　　唉！灭亡六国的是六国自己，不是秦国啊。族灭秦王朝的是秦王朝自己，不是天下的人啊。可叹呀！假使六国各自爱护它的人民，就完全可以依靠人民来抵抗秦国。假使秦王朝又爱护六国的人民，那就顺次传到三世还可以传到万世做皇帝，谁能够族灭它呢？（秦王朝灭亡得太迅速）秦人还没工夫哀悼自己，可是后人哀悼他；如果后人哀悼他却不把他作为镜子来吸取教训，也只会使更后的人又来哀悼这后人啊。', poem_notes = '六王毕：六国灭亡了。齐、楚、燕、韩、赵、魏六国的国王，即指六国。毕 ，完结，指为秦国所灭。\n一：统一。\n蜀山兀，阿房出：四川的山光秃了，阿房宫出现了。兀，山高而上平。这里形容山上树木已被砍伐净尽。出，出现，意思是建成。蜀，四川。\n覆压三百余里：（从渭南到咸阳）覆盖了三百多里地（里是面积单位，不是长度单位。古代五户为一邻，五邻为一里。三百余下里，约合7500户人家的面积。300里地，即150公里，现代人也无法做到，夸张过度，难以令人信服）。这是形容宫殿楼阁接连不断，占地极广。覆压，覆盖（覆压：应当是指“层层叠叠”）。\n隔离天日：遮蔽了天日。这是形容宫殿楼阁的高大。\n骊山北构而西折，直走咸阳：（阿房宫）从骊山北边建起，折而向西，一直通到咸阳（古咸阳在骊山西北）。走，趋向。\n二川溶溶：二川，指渭水和樊川。溶溶，河水缓流的样子。\n廊腰缦回：走廊长而曲折。廊腰，连接高大建筑物的走廊，好像人的腰部，所以这样说。缦，萦绕。回，曲折。\n檐牙高啄：（突起的）屋檐（像鸟嘴）向上撅起。檐牙，屋檐突起，犹如牙齿。\n各抱地势：各随地形。这是写楼阁各随地势的高下向背而建筑的状态。\n钩心斗角：指宫室结构的参差错落，精巧工致。钩心，指各种建筑物都向中心区攒聚。斗角，指屋角互相对峙。如今指各自用尽心机互相排挤。\n盘盘焉，囷囷（qūn qūn）焉，蜂房水涡：盘旋，屈曲，像蜂房，像水涡。焉，相当于“凛然”“欣然”的“然”，意为...的样子。楼阁依山而筑，所以说像蜂房，像水涡。盘盘，盘旋的样子。囷囷，屈曲的样子，曲折回旋的样子。\n矗不知其几千万落：矗立着不知它们有几千万座。矗，形容建筑物高高耸立的样子。下文“杳不知其所之也”的“杳”，用法与此相同。落，相当于“座”或者“所”。\n长桥卧波，未云何龙：长桥卧在水上，没有云怎么（出现了）龙？《易经》有“云从龙”的话，所以人们认为有龙就应该有云。这是用故作疑问的话，形容长桥似龙。\n复道：在楼阁之间架木筑成的通道。因上下都有通道，叫做复道。霁：雨后天晴\n冥迷：分辨不清。\n歌台暖响，春光融融：意思是说，人们在台上唱歌，歌乐声响起来，好像充满着暖意。如同春光那样融和。融融，和乐。\n舞殿冷袖，风雨凄凄：意思是说，人们在殿中舞蹈，舞袖飘拂，好像带来寒气，如同风雨交加那样凄冷。（19）妃嫔媵嫱（feīpín yìng qiáng）：统指六国王侯的宫妃。她们各有等级（妃的等级比嫔、嫱高）。媵是陪嫁的侍女，也可成为嫔、嫱。下文的“王子皇孙”指六国王侯的女儿，孙女。\n辞楼下殿，辇（niǎn）来于秦：辞别（六国的）楼阁宫殿，乘辇车来到秦国。\n明星荧荧，开妆镜也：（光如）明星闪亮，是（宫人）打开梳妆的镜子。荧荧，明亮的样子。下文紧连的四句，句式相同。\n涨腻：涨起了（一层）脂膏（含有胭脂、香粉的洗脸的“脂水”）。\n椒兰：两种香料植物，焚烧以熏衣物。\n辘辘远听：车声越听越远。辘辘，车行的声音。\n杳：遥远得踪迹全无。\n一肌一容，尽态极妍：任何一部分肌肤，任何一种姿容，都娇媚极了。态，指姿态的美好。妍，美丽。\n缦立：久立。缦，通“慢”\n幸：封建时代皇帝到某处，叫“幸”。妃，嫔受皇帝宠爱，叫“得幸”。\n三十六年：秦始皇在位共三十六年。按秦始皇二十六年（前221年）统一中国，到三十七年（前209年）死，做了十二年皇帝，这里说三十六年，指其在位年数，形容阿房宫很大，有36年都没有见到皇帝的宫女。\n收藏：指收藏的金玉珍宝等物。下文的“经营”也指金玉珍宝等物。“精英”，形容词作名词，精品，也有金玉珍宝等物的意思。\n摽（piāo）掠其人：从人民那里抢来。摽 ，抢劫，掠夺。人，民。唐避唐太宗李世民讳，改民为人。下文“人亦念其家”“六国各爱其人”“秦复爱六国之人”的“人”，与此相同。\n倚叠：积累。\n鼎铛（chēng）玉石，金块珠砾：把宝鼎看作铁锅，把美玉看作石头，把黄金看作土块，把珍珠看作石子。铛，平底的浅锅。\n逦迤（lǐ yǐ）：连续不断。这里有“连接着”、“到处都是”的意思。\n一人之心，千万人之心也：心，心意，意愿.\n奈何：怎么，为什么。\n锱铢（zīzhū）：古代重量名，一锱等于六铢，一铢约等于后来的一两的二十四分之一。锱、铢连用，极言其细微。\n负栋之柱：承担栋梁的柱子。\n磷磷：水中石头突立的样子。这里形容突出的钉头。\n庾（yǔ）：露天的谷仓。\n九土：九州。\n独夫：失去人心而极端孤立的统治者。这里指秦始皇。\n固：顽固。\n戍卒叫：指陈胜、吴广起义。\n函谷举：刘邦于公元前206年率军先入咸阳，推翻秦朝统治，并派兵守函谷关。举，被攻占。\n楚人一炬：指项羽（楚将项燕的后代）也于公元前206年入咸阳，并焚烧秦的宫殿，大火三月不灭。\n使：假使。\n递：传递，这里指王位顺着次序传下去。\n万世：《史记·秦始皇本纪》载：秦始皇统一六国后，“下诏曰：“朕为始皇帝，后世以计数，二世，三世至于万世，传之无穷。”然而秦朝仅传二世便亡。\n族：使……灭族。\n不暇：来不及。\n哀：哀叹。', poem_tags = '辞赋精选,古文观止,高中文言文,咏物,议论,借古讽今' WHERE poem_title = '阿房宫赋' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '农历二月，村子前后的青草已经渐渐发芽生长，黄莺飞来飞去。杨柳披着长长的绿枝条，随风摆动，好像在轻轻地抚摸着堤岸。在水泽和草木间蒸发的水汽，如同烟雾般凝集着。杨柳似乎都陶醉在这浓丽的景色中。\n村里的孩子们放了学急忙跑回家，趁着东风把风筝放上蓝天。', poem_notes = '村居：在乡村里居住时见到的景象。\n杨柳拂堤：像杨柳一样抚摸堤岸。醉：迷醉，陶醉。春烟：春天水泽、草木间蒸发形成的烟雾般的水汽。\n散学：放学。\n纸鸢：泛指风筝，它是一种纸做的形状像老鹰的风筝。鸢：老鹰。', poem_appreciation = '首联写时间和自然景物。生动地描写了春天时的大自然，写出了春日农村特有的明媚、迷人的景色。早春二月，小草长出了嫩绿的芽儿，黄莺在天上飞着，欢快地歌唱。堤旁的柳树长长的枝条，轻轻地拂着地面，仿佛在春天的烟雾里醉得直摇晃。“草长莺飞”四个字，把春在的景物写活，使读者仿佛感受到那种万物复苏、欣欣向荣的气氛，读者的眼前也好像涌动着春的脉搏。\n\n　　颔联写村中的原野上的杨柳，“拂”，“醉”，把静止的杨柳人格化了。枝条柔软而细长，轻轻地拂扫着堤岸。春日的大地艳阳高照，烟雾迷蒙，微风中杨柳左右摇摆。诗人用了一个“醉”字，写活了杨柳的娇姿；写活了杨柳的柔态；写活了杨柳的神韵。这是一幅典型的春景图。\n\n　　颈联和尾联写人物活动。描述了一群活泼的儿童在大好的春光里放风筝的生动情景。孩子们放学早，趁着刮起的东风，放起了风筝。儿童正处在人生早春，儿童的欢声笑语，兴致勃勃地放风筝，使春天更加生机勃勃，富有朝气。儿童、东风、纸鸢，诗人选写的人和事为美好的春光平添了几分生机和希望。结尾两句由前两句的物写到人，把早春的迷人渲染得淋漓尽致。\n\n　　《村居》这首诗写的是诗人居住农村亲眼看到的景象，诗人勾画出一幅生机勃勃，色彩缤纷的“乐春图”。全诗充满了生活情趣，诗情画意。诗人采用了动静结合的手法，将早春二月的勃勃生机展露无遗。本诗落笔明朗，用词洗练。全诗洋溢着欢快的情绪，字里行间透出了诗人对春天来临的喜悦和赞美。', poem_tags = '古诗三百首,小学古诗,春天,乡村,写景,儿童,早教古诗100首' WHERE poem_title = '村居' AND poem_author = '高鼎';
UPDATE edu_poem SET poem_translation = '世上（先）有伯乐，然后有千里马。千里马经常有，但是伯乐不常有。所以即使有名贵的马，只是辱没在仆役的手中，（跟普通的马）一同死在槽枥之间，不以千里马著称。\n\n　　（日行）千里的马，吃一顿有时能吃完一石粮食。喂马的人不知道它能（日行）千里而（像普通的马一样）来喂养它。这样的马，虽然有（日行）千里的能力，但吃不饱，力气不足，才能和美德不能表现在外面。想要和普通的马一样尚且做不到，怎么能够要求它（日行）千里呢?\n\n　　不按照（驱使千里马的）正确方法鞭打它，喂养它却不能竭尽它的才能，听千里马嘶鸣，却不能通晓它的意思，拿着鞭子面对它，说：“天下没有千里马！“唉，难道真的没有千里马吗？大概是真的不认识千里马吧！', poem_notes = '伯乐：孙阳。春秋时人，擅长相（xiàng）马（现指能够发现人才的人）。\n千里马：原指善跑的骏马，可以日行千里。现在常用来比喻人才；特指有才华的人。\n而：表转折。可是，但是。\n故虽有名马：所以即使有名贵的马。故：因此 。 虽：即使。名：名贵的。\n祗辱于奴隶人之手： 也只能在马夫的手里受到屈辱（或埋没）。祗（zhǐ）：只是。奴隶人：古代也指仆役，这里指喂马的人。\n辱：这里指受屈辱而埋没才能。\n骈（pián）死于槽（cáo）枥（lì）之间：（和普通的马）一同死在马厩里。骈，两马并驾。骈死：并列而死。于：在。槽枥：喂牲口用的食器，引申为马厩。\n不以千里称也：不因日行千里而著名。指马的千里之能被埋没。以：用。 称：出名。\n马之千里者：之，定语后置的标志。\n一食：吃一顿。食，吃。\n或：有时。\n尽全，这里作动词用，是“吃尽”的意思。\n粟（sù）：本指小米，也泛指粮食。\n石（dàn），容量单位，十斗为一石，一石约等于一百二十斤。三十斤为钧,四钧为石。\n食马者：食，通“饲”，喂。\n其：指千里马，代词。\n是：这样，指示代词。\n虽：虽然（与前面的虽不一样，这里指虽然)\n能：本领。\n足：足够。\n才 ：才能。\n美：美好的素质。\n外见（xiàn）：表现在外面。 见：通“现”，表现；显现。\n且：犹，尚且。\n欲：想要。\n等：等同，一样。\n不可得：不能够得到。得：能，表示客观条件允许。\n安：怎么，哪里，疑问代词。\n求：要求。\n策之：驱使它。策：马鞭，引申为鞭打，这里指鞭策，驾驭。之：代词，指千里马。\n以其道：按照（驱使千里马的）正确的方法。以：按照。道：正确的方法。\n食之：食，通“饲”，喂。\n尽其材：竭尽它的才能。这里指喂饱马，使它日行千里的能力充分发挥出来。 材：通“才”，才能。尽（2）：竭尽，发挥出。\n鸣：马嘶。\n通其意：通晓它的意思。\n执：拿。\n策：马鞭。\n临：面对。\n呜呼：表示惊叹，相当于“唉”。\n其（1）：难道，表反问语气。\n其（2）：大概，表推测语气。\n邪：通“耶”，表示疑问的语气词，意为“吗”\n知：懂得，了解，认识。', poem_appreciation = '韩愈是唐代散文巨匠，同时也是对宋代作家极有影响的诗人。人们对他的“以文为诗”（把诗歌写得散文化）谈得比较多，却很少注意他那更为突出的“以诗为文”的特点。\n\n　　所谓“以诗为文”，是指用具有诗的情调、韵味等特色来写散文，即是说把散文给诗化了（但这并不等于从西方引进的新文体“散文诗”）。我们说把散文诗化，或者说把散文写得很带诗意，并不限于写自然景物、抒情小品或对人物进行典型塑造和对事态进行艺术描绘；而是也可以用诗的情调、韵味来写说理文或评论文。韩愈的散文特点之一就在这里。\n\n　　据说伯乐姓孙名阳，是春秋时代秦国人，会给马看相，善于识别什么是千里马。这原是《战国策·楚策》中一个名叫汗明的人对春申君黄歇讲的一个故事里的人物。这故事可能是古代传说，也可能就是汗明用艺术虚构手法创造出来的寓言。伯乐的典故曾几次被韩愈引用（见他所作的《为人求荐书》及《送温处士赴河阳序》），可见由于韩愈本人命运的坎坷，对伯乐能识别千里马的故事是很有感情的。但平心而论，还是他的这篇《马说》写得最好，读者也最爱读，因为这篇文章写得太像一首诗了。\n\n　　诗的主要特点之一就是诉诸形象思维，它的创作手法也常以比兴为主。当然，一首好诗总要比散文写得更加含蓄曲折，余味无穷。而从常识论，一篇说理散文，基本上总是以逻辑思维为主的，韩愈的《马说》肯定是一篇说理文，但它似寓言而实非寓言，用比喻说理却并未把所持的论点正面说穿，更没有把个人意见强加给读者。全篇几乎始终通过形象思维来描述千里马的遭遇，只摆出活生生的事实却省却了讲大道理的笔墨，这已经可以说是诗的写法了。更巧妙地是作者利用了古汉语中不可缺少的虚词（语助词、感叹词和连接词），体现出抒情诗应有的一唱三叹的滋味和意境，尽管我们读起来是一篇散文，但仔细品评，却俨然是一首发挥得淋漓尽致的抒情诗。这种“以诗为文”的本领，始自西汉的司马迁（谁也不曾承认过司马迁是诗人），到了韩愈、柳宗元，乃得到进一步的发展；至宋代的欧阳修、苏轼（尤其是欧阳修）而达到一个新的高度。这是我们研究中国文学史和学习古典散文应该注意的新课题。\n\n　　文章的第一句是大前提：“世有伯乐然后有千里马。”可这个命题本身就不合逻辑。因为存在决定意识，伯乐善相马的知识和经验，必须从社会上（或说自然界）存在着大量的千里马身上取得，然后逐渐总结出来的。所以过去有人就认为韩愈这句话是本末倒置，是唯心主义的。我们并不否认，从唯物主义原则来看，他这句话是错误的。但把它作为诗的语言，它却是发人深省的警句，是感慨万千的名言。因为世上有伯乐这种知识和本领的人实在太少了。于是作者紧接着在下文从正面点明主旨，一泻无余地把千里马的无限委屈倾诉出来。正由于“伯乐不常有”，不少的千里马不仅找不到一个一般水平的牧马人，而是“祇辱于奴隶人之手”，受尽了无知小人的腌气。更令人悲愤的是这些宝马竟然成双作对地一群群死于槽枥之间，其遭遇之不幸、结局之惨痛真非笔墨所能形容。当然，结果更是死不瞑目，谁也不把这些有价值的神骏称为千里马，它们的死也自然是毫无所谓的了。“不以千里称也”这句话，包含着这样的意思：连同情它们的人都没有，更谈不上对它们的死表示遗憾、惋惜和悔恨痛心了。从文章表面看，作者说得已相当透彻；而实际上这里面不知有多少辛酸痛楚还没有尽情吐露，看似奔放而其内涵则甚为丰富，其实倒是含蓄不尽的（说他写得婉约，或许读者不能接受，可作者确实没有把话说尽）。这真是抒情诗的写法了。\n\n　　作者着力刻画“食（饲）马者”与千里马之间的矛盾，两相对照，既写出千里马的抑郁不平，也写出不识真才者的愚昧专横。千里马在无人给它创造有利的客观条件时，英雄无用武之地；或虽欲一展所长而有力无处使，甚至到了无力可使的程度。这样，它连一匹普通马也比不上，又怎么能实现它日行千里的特异功能呢？因此它的待遇自然也就比不上一匹“常马”，而它的受辱和屈死也就更不足为奇，不会引起人们的注意了。不仅如此像这样连“常马”都比不上的千里马，由于不能恪尽职守，还会受到极度的责难和惩罚，往往被无辜地痛打一顿（“策之不以其道”，打得它不合理），当然在待遇上也就更加糟糕了（“食之不能尽其材”）。表面看“食马者”不是伯乐，不懂马语；骨子里却蕴涵着怀才不遇的人面对那些愚昧专横的统治者就是申诉也无用这一层意思。\n\n　　文章写到这里，作者似乎还觉得不够解渴，于是又接着用“鸣之而不能通其意”的意思，从“人”的方面再做深入一层的刻画。这不仅使文章更生动深刻，也表现出作者的感情更为愤激了。作者并没有立即谴责这种不识马的“人”有眼无珠，反而让他面对着这匹千里马不懂装懂，发出了仿佛悲天悯人般的慨叹：“天下无马!”意思说，这样的“人”在主观动机方面还是自以为不错的，他并非不想选拔人才，并非没有求贤用贤之心，无奈贤人贤才太“少”了，既无处可寻觅，也无地可安插：“天下哪里有真正的人才啊!”明明是“人”的主观上出了毛病，却把这种局面的形成推给客观条件的不如意、不理想。眼前就是一匹被作践得不成样子的千里马，却对它发出了“天下无马”的慨叹，认为这不过是一匹连“常马”也不如的驽骀之辈。这不仅是绝妙的讽刺，而且也是极其严峻猛厉的诛心之论。文章写至此已经水到渠成，作者这才站出来点题，用“呜呼”以下三句作结，把“无马”和“不知马”这一对矛盾（“无马”是先天的自然缺陷，“不知马”则是后天人为的犯罪）尖锐地摆出来形成一个高潮，极尽沉郁顿挫之致。\n\n　　典故　：传说中，天上管理马匹的神仙叫伯乐。在人间，人们把精于鉴别马匹优劣的人，也称为伯乐。\n\n　　第一个被称作伯乐的人本名孙阳，他是春秋时代的人。由于他对马的研究非常出色，人们便忘记了他本来的名字，干脆称他为伯乐，延续到现在。\n\n　　一次，伯乐受楚王的委托，购买能日行千里的骏马。伯乐向楚王说明，千里马少有，找起来不容易，需要到各地巡访，请楚王不必着急，他尽力将事情办好。\n\n　　伯乐跑了好几个国家，连素以盛产名马的燕赵一带，都仔细寻访，辛苦倍至，还是没发现中意的良马。一天，伯乐从齐国返回，在路上，看到一匹马拉着盐车，很吃力地在陡坡上行进。马累得呼呼喘气，每迈一步都十分艰难。伯乐对马向来亲近，不由走到跟前。马见伯乐走近，突然昂起头来瞪大眼睛，大声嘶鸣，好像要对伯乐倾诉什么。伯乐立即从声音中判断出，这是一匹难得的骏马。 伯乐对驾车的人说：“这匹马在疆场上驰骋，任何马都比不过它，但用来拉车，它却不如普通的马。你还是把它卖给我吧。”\n\n　　驾车人认为伯乐是个大傻瓜，他觉得这匹马太普通了，拉车没气力，吃得太多，骨瘦如柴，毫不犹豫地同意了。伯乐牵走千里马，直奔楚国。伯乐牵马来到楚王宫，拍拍马的脖颈说：“我给你找到了好主人。”千里马像明白伯乐的意思，抬起前蹄把地面震得咯咯作响，引颈长嘶，声音洪亮，如大钟石磐，直上云霄。楚王听到马嘶声，走出宫外。伯乐指着马说：“大王，我把千里马给您带来了，请仔细观看。” 楚王一见伯乐牵的马瘦得不成样子，认为伯乐愚弄他，有点不高兴，说：“我相信你会看马，才让你买马，可你买的是什么马呀，这马连走路都很困难，能上战场吗？”\n\n　　伯乐说：“这确实是匹千里马，不过拉了一段车，又喂养不精心，所以看起来很瘦。只要精心喂养，不出半个月，一定会恢复体力。”\n\n　　楚王一听，有点将信将疑，便命马夫尽心尽力把马喂好，果然，马变得精壮神骏。楚王跨马扬鞭，但觉两耳生风，喘息的功夫，已跑出百里之外。 后来千里马为楚王驰骋沙场，立下不少功劳。楚王对伯乐更加敬重。\n\n　　伯乐是古代有名的相马（鉴别马的好坏）专家。当他年老的时候，他的儿子很想将这项专门技能继承下来，以免失传。于是他把伯乐写的《相马经》读得烂熟。《相马经》上描写千里马的外形是“额头隆起，双眼突出，蹄子好像垒起的酒药饼。”他就依照这一条，拿着经文出去“相马”了。\n\n　　伯乐的儿子把所见到事物的外形和《相马经》上描绘的图形一一对照，结果找到了一只很大的蛤蟆。他兴冲冲地跑回家报告父亲，说：“总算找到好马了，额头和双眼同书上说的差不多，就是蹄子的形状和书上写的有区别。”\n\n　　伯乐听了，只好哭笑不得地对这个好心而不聪明的独生子说；“你倒是找到了一匹好马，只是它太喜欢跳，你可驾驭不了啊！”\n\n　　正是，世有伯乐才得千里马。如果千里马没能遇见“伯乐”，终究会被埋没。', poem_tags = '初中文言文,古文观止,写马,寓人,哲理' WHERE poem_title = '杂说四·马说' AND poem_author = '韩愈';
UPDATE edu_poem SET poem_translation = '篱笆稀稀落落，一条小路通向远方，树上的花瓣纷纷飘落，却还尚未形成树阴。\n小孩子飞快地奔跑着追赶黄色的蝴蝶，可是蝴蝶突然飞入菜花丛中，再也找不到了。', poem_notes = '篱：篱笆。\n疏疏：稀疏。\n径：小路。\n阴：树叶茂盛浓密而形成的树荫。\n急走：奔跑。', poem_appreciation = '这首诗是描写农村早春风光的，诗人把景物与人物融为一体描绘，别有情趣。\n\n　　第一句是纯景物的静态描写。篱笆和小路，点明这是农村，“篱落”是有宽度的，用“疏疏”指出它的状态，显见其中有间隔，才能看见篱笆外面的山道。“一径深”，表明山道只有一条，并且很长很长，延伸向远方。宽广的篱落与窄小的一径相对照，稀稀疏疏与绵绵长长相对照，互相映衬，突出了农村清新与宁静。\n\n　　第二句也是纯景物的静态描写。路旁，树枝上的桃花、李花已经落了，但树叶还没有长得茂密，展示出农村自然、朴素的风貌。\n\n　　第三句是人物动态描写。“急走”与“追”相结合，儿童们那种双手扑扑打打，两脚跌跌撞撞追蝶的兴奋、欢快场面就历历在目了，反映了儿童们的天真活泼。\n\n　　第四句，菜花是黄的，又是繁茂的一片，一只小小的蝴蝶，飞入这黄色的海洋里，自然是无处寻了。读者可以想象，这时儿童们东张西望，四处搜寻的焦急状态，以及搜寻不着的失望情绪等等，更表现出儿童们的天真和稚气。\n\n　　本诗通过对春末夏初季节交替时景色的描写，体现了万物勃发的生命力。全诗所摄取的景物极为平淡，所描绘人物的活动也极为平常，但由于采取景物与人物相结合，动静相间的写作手法，成功地刻画出农村恬淡自然，宁静清新的早春风光。', poem_tags = '古诗三百首,小学古诗,农村,写景,写花,儿童' WHERE poem_title = '宿新市徐公店' AND poem_author = '杨万里';
UPDATE edu_poem SET poem_translation = '我居住在长江上游，你居住在长江尾底。日日夜夜想你，却不能见你，你和我啊...同饮一江绿水，两情相爱相知。\n悠悠不尽的江水什么时候枯竭，别离的苦恨，什么时候消止。只愿你的心，如我的心相守不移，就不会辜负了我一番痴恋情意。\n\n译文二\n我居住在长江上游，你居住在长江下游。 天天想念你却见不到你，共同喝着长江的水。\n长江之水，悠悠东流，不知道什么时候才能休止，自己的相思离别之恨也不知道什么时候才能停歇。只希望你的心思像我的意念一样， 就一定不会辜负这互相思念的心意。', poem_notes = '选自《姑溪词》，作者李之仪。\n已：完结,停止\n休：停止\n定：此处为衬字。\n思：想念，思念', poem_appreciation = '李之仪这首《卜算子》深得民歌的神情风味，明白如话，复叠回环，同时又具有文人词构思新巧、深婉含蓄的特点，可以说是一种提高和净化了的通俗词。\n\n　　此词以长江起兴。开头两句，“我”“君”对起，而一住江头，一住江尾，见双方空间距离之悬隔，也暗寓相思之情的悠长。重叠复沓的句式，加强了咏叹的情味，仿佛可以感触到主人公深情的思念与叹息，在阁中翘首思念的女子形象于此江山万里的悠广背景下凸现出来。\n\n　　三、四两句，从前两句直接引出。江头江尾的万里遥隔，引出了“日日思君不见君”这一全词的主干；而同住长江之滨，则引出了“共饮长江水”。如果各自孤立起来看，每一句都不见出色，但联起来吟味，便觉笔墨之外别具一段深情妙理。这就是两句之间含而未宣、任人体味的那层转折。字面意思浅直：日日思君而不得见，却又共饮一江之水。深味之下，似可知尽管思而不见，毕竟还能共饮长江之水。这“共饮”又似乎多少能稍慰相思离隔之恨。词人只淡淡道出“不见”与“共饮”的事实，隐去它们之间的转折关系的内涵，任人揣度吟味，反使词情分外深婉含蕴。\n\n　　“此水几时休，此恨何时已。”换头仍紧扣长江水，承上“思君不见”进一步抒写别恨。长江之水，悠悠东流，不知道什么时候才能休止，自己的相思离别之恨也不知道什么时候才能停歇。用“几时休”“何时已”这样的口吻，一方面表明主观上祈望恨之能已，另一方面又暗透客观上恨之无已。江水永无不流之日，自己的相思隔离之恨也永无销歇之时。此词以祈望恨之能已反透恨之不能已，变民歌、民间词之直率热烈为深挚婉曲，变重言错举为简约含蓄。\n\n　　写到这里，词人翻出一层新的意蕴：“只愿君心似我心，定不负相思意。”恨之无已，正缘爱之深挚。“我心”既是江水不竭，相思无已，自然也就希望“君心似我心”，我定不负我相思之意。江头江尾的阻隔纵然不能飞越，而两相挚爱的心灵却相通。这样一来，单方面的相思便变为双方的期许，无已的别恨便化为永恒的相爱与期待。这样，阻隔的双方心灵上便得到了永久的滋润与慰藉。从“此恨何时已”翻出“定不负相思意”，江头江尾的遥隔这里反而成为感情升华的条件了。这首词的结拍写出了隔绝中的永恒之爱，给人以江水长流情长的感受。\n\n　　全词以长江水为贯串始终的抒情线索，以“日日思君不见君”为主干。分住江头江尾，是“不见君”的原因；“此恨何时已”，是“不见君”的结果；“君心似我心”“不负相思意”是虽有恨而无恨的交织。有恨的原因是“不见君”，无恨.的原因是“不相负”。悠悠长江水，既是双方相隔千里的天然障碍，又是一脉相通、遥寄情思的天然载体；既是悠悠相思、无穷别恨的触发物与象征，又是双方永恒相爱与期待的见证。随着词情的发展，它的作用也不断变化，可谓妙用无穷。这样新巧的构思和深婉的情思、明净的语言、复沓的句法的结合，构成了这首词特有的灵秀隽永、玲珑晶莹的风神。', poem_tags = '宋词三百首,宋词精选,婉约,长江,思念,爱情' WHERE poem_title = '卜算子·我住长江头' AND poem_author = '李之仪';
UPDATE edu_poem SET poem_translation = '郁孤台下这赣江的水，水中有多少行人的眼泪。我举头眺望西北的长安，可惜只看到无数青山。\n但青山怎能把江水挡住？江水毕竟还会向东流去。夕阳西下我正满怀愁绪，听到深山里传来鹧鸪的鸣叫声。', poem_notes = '⑴菩萨蛮：词牌名。\n⑵造口：一名皂口，在江西万安县南六十里。\n⑶郁孤台：今江西省赣州市城区西北部贺兰山顶，又称望阙台，因“隆阜郁然，孤起平地数丈”得名。清江：赣江与袁江合流处旧称清江。\n⑷长安：今陕西省西安市，为汉唐故都。此处代指宋都汴京。\n⑸愁余：使我发愁。\n(6)无数山：很多座山。\n(7)鹧鸪：鸟名。传说其叫声如云“行不得也哥哥”，啼声凄苦。', poem_appreciation = '“造口”，即造口镇，在今江西省万安县西南。宋孝宗淳熙三年（一一七六），作者任江西提点刑狱（掌管刑法狱讼的官吏）时，途经造口。在宋高宗建炎三年（一一二九），金兵南下，攻入江西。隆裕太后由南昌仓皇南逃，金兵一直深入到造口。作者想起当时人民的苦难，写了这首词，题在墙壁上。\n\n　　从这首词里可以看出，作者怀念中原故土的感情和广大人民是一致的。\n\n　　它反映了四十年来，由于金兵南侵，祖国南北分裂，广大人民妻离子散，流离失所的痛苦生活，也反映了作者始终坚持抗金立场，并为不能实现收复中原的愿望而感到无限痛苦的心情。这种强烈的爱国思想，也正是辛弃疾作品中人民性的具体表现。\n\n　　上片四句在写法上，由近及远，又由远及近。“郁孤台下清江水，中间多少行人泪。”意思是说：郁孤台下清江里的流水呵！你中间有多少逃难的人们流下的眼泪啊！作者把眼前清江的流水，和四十年前人民在兵荒马乱中流下的眼泪联系在一起，这就更能够表现出当时人民受到的极大痛苦。四十年来，广大人民多么盼望着能恢复故土、统一祖国啊！然而，南宋当局根本不打算收复失地，只想在杭州过苟延残喘、偷安一时的生活。因此，作者抚今忆昔，感慨很深，在悲愤交集的感情驱使下，又写出了“西北望长安，可怜无数山”两句，以抒发对中原沦陷区的深切怀念。“郁孤台”，古台名，在今江西省赣州市西南贺兰山顶。“清江”，即赣江，流经赣州市和郁孤台下，向东北流入鄱阳湖。“长安”，即今陕西省西安市，西汉、隋、唐都建都在此。唐朝李勉曾经登上郁孤台想望长安。这里的“西北望长安”，是想望北方沦陷区，反映作者的爱国感情。“可怜无数山”意思是说：很可惜被千山万岭遮住了视线。“可怜”，作可惜讲。从望不见长安到视线被无数山遮住，里边含有收复中原的壮志受到种种阻碍、无法实现的感叹。\n\n　　下片紧接着上片，继续抒发对中原故土的怀念。“青山遮不住，毕竟东流去”两句是比喻句，意思是说：滚滚的江水，冲破了山峦叠嶂，在奔腾向前。它象征着抗金的正义事业，必然会克服一切阻力，取得最后的胜利。这里表明作者对恢复中原充满了坚定的信心。但是，作者并没有脱离现实，沉醉于未来理想的幻想之中。十几年来，他目睹了抗金事业受到的重重阻力，不禁又愁绪满怀。“江晚正愁余，山深闻鹧鸪”两句说：傍晚，我在江边徘徊，正在为了不能实现恢复大计愁苦着呢，可是恰巧，又从山的深处，传来鹧鸪鸟的哀鸣。这叫声听起来，仿佛是“行不得也哥哥”。从鹧鸪的悲鸣声中，恰好透露出作者想收复失地，但又身不由己的矛盾心情。\n\n　　这首词写得非常质朴、自然、流畅。尤其“青山遮不住，毕竟东流去”\n\n　　两句，十分含蓄，耐人寻味。', poem_tags = '宋词三百首,豪放,山水,抒怀,爱国' WHERE poem_title = '菩萨蛮·书江西造口壁' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '西塞山前白鹭在自由地翱翔，江水中，肥美的鳜鱼欢快地游着，漂浮在水中的桃花是那样的鲜艳而饱满。\n江岸一位老翁戴着青色的箬笠，披着绿色的蓑衣，冒着斜风细雨，悠然自得地垂钓，他被美丽的春景迷住了，连下了雨都不回家。', poem_notes = '渔歌子：词牌名。此调原为唐教坊名曲。分单调、双调二体。单调二十七字，平韵，以张氏此调最为著名。双调，五十字，仄韵。《渔歌子》又名《渔父》或《渔父乐》，大概是民间的渔歌。据《词林纪事》转引的记载说，张志和曾谒见湖州刺史颜真卿，因为船破旧了，请颜真卿帮助更换，并作《渔歌子》。词牌《渔歌子》即始于张志和写的《渔歌子》而得名。“子”即是“曲子”的简称。\n西塞山：浙江湖州。\n白鹭：一种白色的水鸟。\n桃花流水：桃花盛开的季节正是春水盛涨的时候，俗称桃花汛或桃花水。\n鳜（guì）鱼：淡水鱼，江南又称桂鱼，肉质鲜美。\n箬（ruò）笠：竹叶或竹蔑做的斗笠。\n蓑（suō）衣：用草或棕编制成的雨衣。\n不须：不一定要。', poem_appreciation = '张志和的词保存下来的只有《渔歌子》（原题叫《渔父》）五首，这是其中的第一首。西塞山在今浙江省吴兴县境内的西苕溪上，从前叫道士矶，是一座突出在河边的大石岩。西苕溪北通太湖，南邻莫干山，风景很优美。张志和这首词描绘春汛期的景物，反映了太湖流域水乡的可爱。\n\n　　白鹭就是平常人们叫做鹭鸶的那种水鸟。远远望去，它的外形有点象白鹤，腿和脖子特别长，便于在水中寻找食物。“西塞山前白鹭飞”，它们在西塞山前，展翅飞翔，使这个鱼米之乡更显得生趣洋溢了。“桃花流水”就是桃花水。南方每年二三月间，桃花盛开，天气暖和，雨水比冬天多，下几场春雨，河水就会上涨，于是逆水而上的鱼群便多起来了。作者没有简单地说春汛到来，而是用“桃花流水鳜鱼肥”来描写，这就更能勾起读者的想象，使人们似乎看见了两岸盛开的、红艳艳的桃花；河水陡涨时，江南特有的鳜鱼不时跃出水面，多肥大呀。“鳜鱼”是一种味道特别鲜美的淡水鱼，嘴大鳞细，颜色呈黄褐色。春汛来了，渔夫当然不会闲着，他们也忙碌开了。“青箬笠，绿蓑衣，斜风细雨不须归”写的都是他们。“箬笠”就是用竹丝和青色箬竹叶编成的斗笠。“蓑衣”是用植物的茎叶或皮制成的雨衣。如果以龙须草（蓑草）为原料，它就是绿色的。“归”，回家。“不须归”，是说也不须回家了。作者在词里虽然只是概括地叙述了渔夫捕鱼的生活，但是，读者通过自己的想象，完全可以体会到词的言外之意。从渔翁头戴箬笠，身披蓑衣，在斜风细雨里欣赏春天水面的景物，读者便可以体会到渔夫在捕鱼时的愉快心情。\n\n　　作者是一位山水画家，据说他曾将《渔歌子》画成图画。确实，这首词是富于画意的。苍岩，白鹭，鲜艳的桃林，清澈的流水，黄褐色的鳜鱼，青色的斗笠，绿色的蓑衣，色彩多么鲜明，构思也很巧妙，意境优美，使人读作品时，仿佛是在看一幅出色的水乡春汛图。\n\n　　此词在秀丽的水乡风光和理想化的渔人生活中，寄托了作者爱自由、爱自然的情怀。词中更吸引读者的不是一蓑风雨，从容自适的渔父，而是江乡二月桃花汛期间春江水涨、烟雨迷蒙的图景。雨中青山，江上渔舟，天空白鹭，两岸红桃，色泽鲜明但又显得柔和，气氛宁静但又充满活力。而这既体现了作者的艺术匠心，也反映了他高远、冲澹、悠然脱俗的意趣。此词吟成后，不仅一时唱和者甚众，而且还流播海外，为东邻日本的汉诗作者开启了填词门径，嵯峨天皇的《渔歌子》五首及其臣僚的奉和之作七首，即以此词为蓝本改制而成。\n\n　　苏子瞻极爱此词，患声不可歌，乃稍损益，寄《浣溪纱》曰：“西塞山前白鹭飞，散花洲外片帆微。桃花流水鳜鱼肥。自蔽一身青箬笠，相随到处绿蓑衣。斜风细雨不须归。”黄鲁直闻而继作。江湖间谓山连亘入水为矶，太平州有矶曰新妇，池州有浦曰女儿。鲁直好奇，偶以名对而未有所付。适作此词，乃云：“新妇矶头眉黛愁，女儿浦口眼波秋。惊鱼错认月沉钩。青箬笠前无限事，绿蓑衣底一时休。斜风细雨转船头。”子瞻闻而戏曰：“才出新妇矶，便入女儿浦，志和得无一浪子渔父耶!”人皆传以为笑。前辈风流略尽，念之慨然。小楼谷隐，要不可无方外之士时相周旋。余非鲁公，固不能致志和，然亦安得一似之者而与游也。（叶梦得《岩下放言》）\n\n　　山谷（黄庭坚）晚年亦悔前作之未工，因表弟李如篪言《渔父词》，以《鹧鸪天》歌之甚协律，恨语少声多耳。因以宪宗遗像求玄真子文章，及玄真之兄松龄劝归之意，足前后数句云：“西塞山前白鹭飞，桃花流水鳜鱼肥。朝廷尚觅玄真子，何处如今更有诗？青箬笠，绿蓑衣，斜风细雨不须归。人间欲避风波险，一日风波十二时。”东坡笑曰：鲁直乃欲平地起风波也。 （摘自《白香词谱笺》）', poem_tags = '宋词三百首,小学古诗,水乡,写景,写人,抒怀' WHERE poem_title = '渔歌子·西塞山前白鹭飞' AND poem_author = '张志和';
UPDATE edu_poem SET poem_translation = '高峻的峨眉山前，悬挂着半轮秋月。流动的平羌江上，倒映着月影。\n夜间乘船出发，离开清溪直奔三峡。想你却难相见，恋恋不舍去向渝州。', poem_notes = '峨眉山：在今四川峨眉县西南。\n半轮秋：半圆的秋月，即上弦月或下弦月。\n影：月光的影子。平羌：即青衣江，在峨眉山东北。源出四川芦山，流经乐山汇入岷江。\n夜：今夜。发：出发。清溪：指清溪驿，属四川犍为，在峨眉山附近。三峡：指长江瞿塘峡、巫峡、西陵峡，今在四川、湖北两省的交界处。一说指四川乐山的犁头、背峨、平羌三峡，清溪在黎头峡的上游。\n君：指峨眉山月。一说指作者的友人。下：顺流而下。渝州：治所在巴县，今重庆一带。', poem_appreciation = '峨眉山，在今四川成都西南峨眉县。山中多寺观。李白涉及峨眉山的诗。人们比较熟悉的有三首，一首是《登峨眉山》，这是作者早期居蜀时所作，另一首是写于晚年的《峨眉山月歌送蜀僧晏入中京》;这一首则是写于作者二十六岁(726)离开蜀地时。如果说李白早期是为了访道求仙而登峨眉山，那么在他即将离蜀和离蜀后写的关于峨眉山月歌的诗，则主要是借以表达豪情壮志及其对友人的思念。这首诗人们很欣赏，但理解却有很大不同。\n\n　　第一，是对作者写此诗时的心情说法不一。明高棅《唐诗品汇》卷四十七引刘须溪谓此诗“含情凄婉“，而程千帆《古诗考索·古典诗歌描写与结构中的一与多》则云:“李白的构思是在以孤悬空中的月与自己所要随着江水东下而经过的许多地方对比。来展现自己乘流而下的轻快心情。“如果我们联系李白出川的动机来分析此诗，对以上两种理解的正误便不难做出判断。作者当时抱着四方之志出蜀远游，犹大鹏将展其翅。此时没有什么“凄婉“之情可言，相反，倒是大有与明月争胜之心。峨眉山月本来随着江水东流，作者乘轻舟顺流而下。所经之处有时可以看到山月，有时看不到，明月时隐时现，仿佛在紧紧追赶自己。看不到时，就像远远地将山月抛在身后。假如把上述刘须溪所谓“含情“的“情“，理解为作者与山月相嬉的情趣或得以出川的喜悦心情，似乎比“凄婉“二字更接近原意。\n\n　　第二，是对“秋“字的不同理解。一种认为是指秋天，另一种认为“是指峨眉山月上弦或下弦呈半圆形的时候“。揆度其意，当然以后一种说法较合理。不过可以肯定，李诗中的“半轮“，不会是指上弦月，因为峨眉山此时在作者的西南方向，自然是指阴历月终的时候了。同时，将“秋“字解作“时候“，可以在训诂方面找到根据，即“秋“字可训为“时期“、“日子“。\n\n　　此外，“秋“字还训作飞动的样子，或腾跃的样子，如《汉书·礼乐志·安世房中歌》之七:“飞龙秋，游上天。“据此，将这句解作弯月飞挂峨眉山，似亦说得通。\n\n　　第三，是对“三峡“的不同解说。一说这里的“三峡“是指鄂川交界的瞿唐峡、巫峡、西陵峡;一说指四川乐山县的黎头、背峨、平羌所谓小三峡。要辨别哪一个更合理。不妨先考察一下李白的出川路线。作者看到峨眉山月的倒影映在平羌江里，说明是从峨眉山的方面启程的。平羌江即青衣江，源出四川芦山县西北，至乐山县入岷江。第三句的“清溪“即清溪驿，在四川犍为县。“清溪“在乐山三峡的下游，作者夜间从这里出发。目标是“向三峡气显然不是指乐山县的三峡。否则不仅“向“字失去了着落，行人便成了走回头路。所以。此处的“三峡“必定是指著名的巴东三峡。这里是人们向往的地方，也是由乐山经渝州(今重庆一带)出川的必由之路。\n\n　　第四，是对二联对句中“君“字的不同解说。有的说是指作者怀念的友人，或为其“送行之人“;沈德潜则云:“月在清溪三峡之间，半轮亦不复见矣。君字即指月。“(《唐诗别裁》)看来后一种说法更合情理。峨眉山是作者实际上的故乡，月是故乡圆。作者对峨眉山月的怀念。无疑也是对故乡的依恋。如果把“思君“解作“思友“，便嫌平直，倒不如看作以月拟人更有诗意。俞陛云认为:“以秋宵之残月，映青峭之峨眉。江上停桡，风景幽绝。无奈轻舟夜发，东下巴渝。回看斜月沉山，思君不见，好山隔面，等于良友分襟也。“(《诗境浅说续编》)所以“思君“不是单指对某一友人的思念，而是一种宽泛的乡情。以象征着故乡的山月为友，不是比指某一具体的友人更有深意吗?\n\n　　古人论此诗，最称道它对地名的妙用。明人王世懋说:“谈艺者有谓七言律一句不可两入故事，一篇中不可重犯故事。此病犯者故少，能拈出亦见精严。然我以为皆非妙悟也。作诗到神情传处，随分自佳，下得不觉痕迹，纵使一句两入，两句重犯，亦自无伤。如太白《峨眉山月歌》，四句入地名者五，然古今目为绝唱，殊不厌重。“(《艺圃撷金》)王世贞称此诗是太白佳境，并说:“二十八字中。有峨眉山、平羌江、清溪、三峡，渝州，使后人为之，不胜痕迹矣，益见此老炉锤之妙。“(《艺苑卮言》)。\n\n　　这里需要补充的是，作者不仅擅用地名，不露痕迹，更值得注意的是其对于绝句诗艺的娴熟，尤其是第三句，承转很见工夫。作者是从平羌江顺流而来，所以第三句的“夜发清溪“是实接，如果再是实转，由清溪直下渝州，则成了水上码头名称的罗列，便可能诗味索然，而“向三峡“却是在虚实之间，作为地名，“三峡“属实，但此时诗人尚未抵达。它又是在想像之中。由于第三句承转得妙，第四句便成了顺水之舟，并把一系列普通地名赋予浓郁的诗情画意。变成了诗中的佳境。全篇说来亦巧亦壮，不愧为古今绝唱。', poem_tags = '初中古诗,秋天,游历,写景,地名' WHERE poem_title = '峨眉山月歌' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '（华山的）山峰从四面八方会聚，（黄河的）波涛像发怒似的汹涌。潼关外有黄河，内有华山，山河雄伟，地势险要。遥望古都长安，陷于思索之中。\n从秦汉宫遗址经过，引发无限伤感，万间宫殿早已化作了尘土。一朝兴盛，百姓受苦；一朝灭亡，百姓依旧受苦。', poem_notes = '山坡羊：曲牌名，是这首散曲的格式；“潼关怀古”是标题。\n峰峦如聚：形容群峰攒集，层峦叠嶂。聚：聚拢；包围\n波涛如怒：形容黄河波涛的汹涌澎湃。怒：指波涛汹涌。\n“山河”句：外面是山，里面是河，形容潼关一带地势险要。具体指潼关外有黄河，内有华山。表里：即内外。《左传·僖公二十八年》：“表里山河，必无害也。”注：“晋国外河而内山。”潼关：古关口名，在今陕西省潼关县，关城建在华山山腰，下临黄河，扼秦、晋、豫三省要冲，非常险要，为古代入陕门户，是历代的军事重地。\n西都：指长安（今陕西西安）。这是泛指秦汉以来在长安附近所建的都城。秦、西汉建都长安，东汉建都洛阳，因此称洛阳为东都，长安为西都。\n踌躇：犹豫、徘徊不定，心事重重，此处形容思潮起伏，，感慨万端陷入沉思，表示心里不平静。一作“踟蹰（chí chú）”。\n“伤心”二句：谓目睹秦汉遗迹，旧日宫殿尽成废墟，内心伤感。伤心：令人伤心的事， 形容词作动词。秦汉经行处：秦朝（前221年~前206年）都城咸阳和西汉（前208~8）的都城长安都在陕西省境内潼关的西面。经行处，经过的地方。指秦汉故都遗址。宫阙：宫，宫殿；阙，皇宫门前面两边的楼观。\n兴：指政权的统治稳固。兴、亡：指朝代的盛衰更替。', poem_appreciation = '此曲是张养浩晚年的代表作，也是元散曲中思想性、艺术性完美结合的名作。在他的散曲集《云庄乐府》中，以“山坡羊”曲牌写下的怀古之作有七题九首，其中尤以《潼关怀古》韵味最为沉郁，色彩最为浓重。\n\n　　全曲分三层：第一层（头三句），写潼关雄伟险要的形势。张养浩途经潼关，看到的是“峰峦如聚，波涛如怒”的景象。这层描写潼关壮景，生动形象。第一句写重重叠叠的峰峦，潼关在重重山峦包围之中，一“聚”字让读者眼前呈现出华山飞奔而来之势、群山攒立之状；因地势险要，为古来兵家必争之地。山本是静止的，“如聚”化静为动，一个“聚”字表现了峰峦的众多和动感。第二句写怒涛汹涌的黄河，潼关外黄河之水奔腾澎湃，一“怒”字让读者耳边回响千古不绝的滔滔水声。黄河水是无生命的，而“如怒”则赋予河水以人的情感和意志，一个“怒”字，写出了波涛的汹涌澎湃。“怒”字还把河水人格化，“怒”字注入了诗人吊古伤今而产生的满腔悲愤之情。为此景所动，第三句写渲关位于群山重重包围、黄河寒流其间那除隘之处。“山河表里潼关路”之感便油然而生，至此潼关之气势雄伟窥见一斑，如此险要之地，暗示潼关的险峻，乃为历代兵家必争之地，也由此引发了下文的感慨。\n\n　　第二层（四一七句），写作者途径潼关时的所见之感，主要写从关中长安万间宫阙化为废墟而产生的深沉的感慨。第四、五句点出作者遥望古都长安，凭吊古迹，思绪万千，激愤难平。“望西都，意踌躇”，写作者驻马远望、感慨横生的样子。作家身处潼关，西望旧朝故都长安，西都”即长安，长安不仅是秦汉都城，魏、晋、隋、唐都建都长安。作为六朝古都，当年是何等的繁华、昌盛。昔日的奢华早已灰飞烟灭不复存，只剩下一片残垣断壁的衰败景象，不禁令诗人踌蹰伤心。 曾经是好几个朝代的都城，它的繁荣昌盛的景象在古籍中也曾有过记载，可如今眼前只剩下一片荒凉，万千滋味涌上心头，遥想当年，秦之阿房，汉之未央，规模宏大，弥山纵谷，可如今崇丽之宫阙，寸瓦尺专皆荡然无存，想到今番前去的任务，他不禁感慨万千。第六、七句“伤心秦汉经行处，宫阙万间都做了土”点出无限伤感的原因。“宫阙万间都作了土”，便是这由盛到衰的过程的真实写照，是令人“伤心”的。这一层看起来只是回顾历史，而没有直接提到战争，然而历代改朝换代的战争的惨烈图景触目惊心。在这里概括了历代帝业盛衰兴亡的沧桑变化。这里作者面对繁华过后的废墟所发出的“伤心”实乃悲凉。为秦汉旧朝统治者悲凉，恐怕“宫阙万间都做了土”（《三辅黄图》：“阿房宫，亦曰阿城。惠文王造宫未成而亡，始皇广其宫，规恢三百余里。离宫别馆，弥山跨谷，辇道相属，阁道通骊山八百余里。”后来项羽引兵西屠咸阳，“烧秦宫室，火三月不灭”。见《史记·项羽本纪》。故曰：“阿房一炬”。） 这种局面是他们不曾想到的吧！同时亦为百姓悲凉，秦汉的一宫一阙都凝聚了天下无数百姓的血和汗，像秦汉王朝为彰显一个时代的辉煌，集国之全力塑起阿房、未央之建筑，但它却随着秦汉王朝的灭亡而化为焦土。辉煌过去，随即而来是朝代的变换，百姓在战争中苦不堪言。此情此景，让作家沉重地说出第三层“兴，百姓苦；亡，百姓苦”这句千古流传的语句。\n\n　　第三层（末四句），总写作者沉痛的感慨：历史上无论哪一个朝代，它们兴盛也罢，败亡也罢，老百姓总是遭殃受苦。一个朝代兴起了，必定大兴土木，修建奢华的宫殿，从而给人民带来巨大的灾难；一个朝代灭亡了，在战争中遭殃的也是人民。他指出历代王朝的或兴或亡，带给百姓的都是灾祸和苦难。这是作者从历代帝王的兴亡史中概括出来的一个结论。三层意思环环相扣，层层深入，思想越来越显豁，感情越来越强烈，浑然形成一体。全曲景中藏情情中有景，情景交融。\n\n　　兴，百姓苦；亡，百姓苦。”是全曲之眼，是全曲主题的开拓和深化。如果这首曲子的曲意仅仅停留在 “宫阙万间都做了土”上，那么它仅仅宣扬了佛家“一切皆空的思想”，它与其它怀古诗（与《洛阳怀古》“功，也不久长！名，也不久长！” 陈草庵《山坡羊 叹世》“兴，也任他；亡，也任他。” 《骊山怀古》“赢，都变做了土；输，都变做了土。”赵庆善《长安怀古》“山，空自愁；河，空自流。”杨慎《临江仙》“是非成败转头空”）的主题并无多大区别。在否定历史的同时，也否定了积极有为的人生态度。正因为最后两句就使得这首曲的境界大大高出同题材的其它作品。这首曲可贵之处在于它有深切的人文关怀，有对老百姓疾苦深切同情与关怀。\n\n　　“亡，百姓苦”好理解。王朝灭亡之际战乱频仍，民不聊生。“兴，百姓苦”的原因则是：王朝之“兴”必大兴土木，搜刮民脂民膏，百姓不堪其苦。像秦王朝兴起时，筑长城，开驰道，造官室，劳役繁重，百姓受尽了苦。“兴，百姓苦”一句，发人所未发，深刻而警策。兴则大兴土木，亡则兵祸连结，不论“兴”、“亡”受苦的都是百姓。归纳总结：这首小令语言精练，形象鲜明且富有人民性，是整个元散曲中的优秀作品。\n\n　　《潼关怀古》中对历史的概括，显指元代现实生活：怀古实乃伤今，沉重实乃责任。这种复杂的感情要结合作家的生平经历才能理解。张养浩特殊的仕途经历，决定了他的怀古散曲中有一种参破功名富贵的思想，《骊山怀古》中写到“赢，都做了土；输，都做了土。” 《洛阳怀古》中写到“功，也不长；名，也不长。” 《北邙山怀古》中写到“便是君，也唤不应；便是臣，也唤不应。”这些曲中张养浩把胜负之数、功名之分、生死之际，看成了毫无差别的，只是借古人古事述说富贵无常、人生如梦。只有《潼关怀古》以难得的沉重，以深邃的目光，揭示了封建社会里一条颠扑不破的真理“兴，百姓苦；亡，百姓苦。” 在写法上，作者采用的是层层深入的方式，由写景而怀古，再引发议论，将苍茫的景色、深沉的情感和精辞的议论三者完美结合，让这首小令有了强烈的感染力。字里行间中充满着历史的沧桑感和时代感，既有怀古诗的特色，又有与众不同的沉郁风格。\n\n　　从作品内容、作家其他怀古作品、同时期其他作家怀古作品三个层面上看，《山坡羊·潼关怀古》都表现为 一份难得的沉重。', poem_tags = '初中古诗,高中古诗,怀古,同情,忧民' WHERE poem_title = '山坡羊·潼关怀古' AND poem_author = '张养浩';
UPDATE edu_poem SET poem_translation = '何处去寻找武侯诸葛亮的祠堂？在成都城外那柏树茂密的地方。\n碧草照映台阶自当显露春色，树上的黄鹂隔枝空对婉转鸣唱。\n定夺天下先主曾三顾茅庐拜访，辅佐两朝开国与继业忠诚满腔。\n可惜出师伐魏未捷而病亡军中，常使历代英雄们对此涕泪满裳！', poem_notes = '蜀相：三国蜀汉丞相，指诸葛亮（孔明)。诗题下有注：诸葛亮祠在昭烈庙西。\n丞相祠堂：即诸葛武侯祠，在现在成都，晋李雄初建。\n锦官城：成都的别名。柏（bǎi）森森：柏树茂盛繁密的样子。\n映阶碧草自春色，隔叶黄鹂空好（hǎo）音：这两句写祠内景物。杜甫极推重诸葛亮，他此来并非为了赏玩美景，“自”“空”二字含情。是说碧草映阶，不过自为春色；黄鹂隔叶，亦不过空作好音，他并无心赏玩、倾听。因为他所景仰的人物已不可得见。空：白白的。\n三顾频繁天下计：意思是刘备为统一天下而三顾茅庐，问计于诸葛亮。这是在赞美在对策中所表现的天才预见。频烦，犹“频繁”，多次。\n两朝开济：指诸葛亮辅助刘备开创帝业，后又辅佐刘禅。两朝：刘备、刘禅父子两朝。开：开创。济：扶助。\n出师未捷身先死，长使英雄泪满襟（jīn）：出师还没有取得最后的胜利就先去世了，常使后世的英雄泪满衣襟。指诸葛亮多次出师伐魏，未能取胜，至蜀建兴十二年（234年）卒于五丈原（今陕西岐山东南）军中。出师：出兵。', poem_appreciation = '这首七律《蜀相》，抒发了诗人对诸葛亮才智品德的崇敬和功业未遂的感慨。全诗熔情、景、议于一炉，既有对历史的评说，又有现实的寓托，在历代咏赞诸葛亮的诗篇中，堪称绝唱。\n\n　　古典诗歌中常以问答起句，突出感情的起伏不平。这首诗的首联也是如此。“丞相祠堂何处寻？锦官城外柏森森。”一问一答，一开始就形成浓重的感情氛围，笼罩全篇。上句“丞相祠堂”直切题意，语意亲切而又饱含崇敬。“何处寻”，不疑而问，加强语势，并非到哪里去寻找的意思。诸葛亮在历史上颇受人民爱戴，尤其在四川成都，祭祀他的庙宇很容易找到。“寻”字之妙在于它刻画出诗人那追慕先贤的执著感情和虔诚造谒的悠悠我思。下句“锦官城外柏森森”，指出诗人凭吊的是成都郊外的武侯祠。这里柏树成荫，高大茂密，呈现出一派静谧肃穆的气氛。柏树生命长久，常年不凋，高大挺拔，有象征意义，常被用作祠庙中的观赏树木。作者抓住武侯祠的这一景物，展现出柏树那伟岸、葱郁、苍劲、朴质的形象特征，使人联想到诸葛亮的精神，不禁肃然起敬。接着展现在读者面前的是茵茵春草，铺展到石阶之下，映现出一片绿色；只只黄莺，在林叶之间穿行，发出宛转清脆的叫声。\n\n　　第二联“映阶碧草自春色，隔叶黄鹂空好音”所描绘的这些景物，色彩鲜明，音韵浏亮，静动相衬，恬淡自然，无限美妙地表现出武侯祠内那春意盎然的景象。然而，自然界的春天来了，祖国中兴的希望却非常渺茫。想到这里，诗人不免又产生了一种哀愁惆怅的感觉，因此说是“自春色”、“空好音”。“自”和“空”互文，刻画出一种静态和静境。诗人将自己的主观情意渗进了客观景物之中，使景中生意，把自己内心的忧伤从景物描写中传达出来，反映出诗人忧国忧民的爱国精神。透过这种爱国思想的折射，诗人眼中的诸葛亮形象就更加光彩照人。\n\n　　“三顾频烦天下计，两朝开济老臣心。”第三联浓墨重彩，高度概括了诸葛亮的一生。上句写出山之前，刘备三顾茅庐，诸葛亮隆中对策，指出诸葛亮在当时就能预见魏蜀吴鼎足三分的政治形势，并为刘备制定了一整套统一国家之策，足见其济世雄才。下句写出山之后，诸葛亮辅助刘备开创蜀汉、匡扶刘禅，颂扬他为国呕心沥血的耿耿忠心。两句十四个字，将人们带到战乱不已的三国时代，在广阔的历史背景下，刻划出一位忠君爱国、济世扶危的贤相形象。怀古为了伤今。此时，安史之乱尚未平定，国家分崩离析，人民流离失所，使诗人忧心如焚。他渴望能有忠臣贤相匡扶社稷，整顿乾坤，恢复国家的和平统一。正是这种忧国思想凝聚成诗人对诸葛亮的敬慕之情；在这一历史人物身上，诗人寄托自己对国家命运的美好憧憬。\n\n　　诗的最后一联“出师未捷身先死，长使英雄泪满襟”，咏叹了诸葛亮病死军中功业未成的历史不幸。诸葛亮赍志以殁的悲剧性结局无疑又是一曲生命的赞歌，他以行动实践了“鞠躬尽瘁，死而后已”的誓言，使这位古代杰出政治家的精神境界得到了进一步的升华，产生使人奋发兴起的力量。\n\n　　这首诗分两部分，前四句凭吊丞相祠堂，从景物描写中感怀现实，透露出诗人忧国忧民之心；后四句咏叹丞相才德，从历史追忆中缅怀先贤，又蕴含着诗人对祖国命运的许多期盼与憧憬。全诗蕴藉深厚，寄托遥深，造成深沉悲凉的意境。概言之，这首七律话语奇简，但容量颇大，具有高度的概括力，短短五十六字，诉尽诸葛亮生平，将名垂千古的诸葛亮展现在读者面前。后代的爱国志士及普通读者一吟诵这首诗时，对诸葛亮的崇敬之情油然而生。特别是一读到“出师未捷身先死，长使英雄泪满襟”二句时，不禁黯然泪下。\n\n　　在艺术表现上，设问自答，以实写虚，情景交融，叙议结合，结构起承转合、层次波澜，又有炼字琢句、音调和谐的语言魅力，使人一唱三叹，余味不绝。人称杜诗“沉郁顿挫”，《蜀相》就是典型代表。\n\n　　本诗借游览古迹，表达了对诸葛亮雄才大略，忠心报国的赞颂，以及对他出师未捷而身先死的惋惜。', poem_tags = '唐诗三百首,咏史怀古,忧国忧民,赞颂,写人' WHERE poem_title = '蜀相' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '东望家乡路程又远又长，热泪湿双袖还不断流淌。\n在马上与你相遇无纸笔，请告家人说我平安无恙。', poem_notes = '入京使：进京的使者。\n故园：指长安和自己在长安的家。漫漫：形容路途十分遥远。\n龙钟：涕泪淋漓的样子。卞和《退怨之歌》：“空山歔欷泪龙钟。”这里是沾湿的意思。\n凭：托，烦，请。传语：捎口信。', poem_appreciation = '这是一首边塞诗，盛唐时代，是边塞诗空前繁荣的时代，出现了以高适、岑参为代表的边塞诗派，他们的创作为百花齐放的盛唐诗坛，增添了一支奇葩。\n\n　　此诗约写于天宝八载(749)，这年岑参第一次从军西征，他辞别了居住在长安的妻子，跃马踏上了漫漫的征途，充任安西节度使高仙芝的幕府书记，西出阳关，奔赴安西。岑参的从军，思想上有两根精神支柱:一个支柱是建功边陲的理想在鼓舞着他，他曾自言:“功名只应马上取，真正英雄一丈夫。“(《送李副使赴碛西官军》)另一个支柱是，他认为从军出塞。是为了报效祖国，赴国家之急。他曾自我表白:“万里奉王事，一身无所求，也知塞垣苦，岂为妻子谋。“(《初过陇山途中呈宇文判官》)正是基于这两点，所以他的边塞诗多数是昂扬乐观的，表现出唐军高昂的士气和震撼大地的声威。但当一个战士踏上征途之后，他们不可能没有思乡的感情，也不可能不思念父母妻子。高适《燕歌行》云:“铁衣远戌辛勤久，玉筋应啼别离后。少妇城南欲断肠，征人蓟北空回首“。岑参的《逢入京使》所表现的就是对故园和家人的思念，这是真挚健康的感情，虽然调子不怎么高昂。但不能认为是消极的、悲观的，尽管他流下了思乡之泪。\n\n　　诗的第一句“故园东望路漫漫“是写眼前的实景。“故园“指自己的家园，“东望“点明家园的位置，也说明自己在走马西行。“路漫漫“三字，说明离家之远。诗人辞家远征，回首望故乡，自觉长路漫漫，平沙莽莽，真不知家山何处?“漫漫“二字，给人以茫茫然的感觉。下句诗“双袖龙钟泪不干“写思乡的情状。思乡之泪，龙钟交横，涕泗滂沱，这多少有点夸张，但“夸而有节，饰而不诬“(《文心雕龙·夸饰》篇)。仍不失为真实，我们仍然可以说上句写的是实景，下句写的是实情。\n\n　　“马上相逢无纸笔“句，“逢“字点出了题目，在赴安西的途中，遇到作为入京使者的故人，彼此都鞍马倥偬，交臂而过，一个继续西行，一个东归长安，而自己的妻子也正在长安，正好托故人带封平安家信回去，可偏偏又无纸笔，彼此行色匆匆，只好托故人带个口信，“凭君传语报平安“吧。这最后一句诗。处理得很简单，收束得很干净利落，但简净之中寄寓着诗人的一片深情，寄至味于淡薄，颇有韵味。\n\n　　如果将这四句诗比高下的话，我以为后两句诗更有味，这两句诗好就好在诗人提炼出特定环境下的典型情节，既自然、合情合理，又别出心裁，诗人摄取的生活镜头，有浓厚的边塞生活气息。“马上相逢“的情节，很有军旅生活的特色，描绘出彼此行色匆匆的情景，因无纸笔而用口信代家书，既合情合理，又给人以新鲜之感。\n\n　　此诗语言自然质朴，不假雕琢，好似信手拈来，随口而出，既有生活味，又有人情味，清新隽永，耐人寻味。', poem_tags = '唐诗三百首,初中古诗,思乡,边塞,生活' WHERE poem_title = '逢入京使' AND poem_author = '岑参';
UPDATE edu_poem SET poem_translation = '北京一带气候寒冷，花朝节过后，冬天余下的寒气还很厉害。冷风时常刮起，刮起就飞沙走石。拘束在一室之中，想出去不可得。每次冒风疾行，不到百步就（被迫）返回。\n　　二十二日天气略微暖和，偕同几个朋友出东直门，到满井。高大的柳树夹立堤旁，肥沃的土地有些湿润，一望空旷开阔，（觉得自己）好像是逃脱笼子的天鹅。这时河的冰面刚刚融化，波光才刚刚开始明亮，像鱼鳞似的浪纹一层一层，清澈得可以看到河底，光亮的样子，好像明镜新打开，清冷的光辉突然从镜匣中射出来一样。山峦被晴天融化的积雪洗过，美好的样子，好像刚擦过一样；娇艳光亮，（又）像美丽的少女洗了脸刚梳好的髻寰一样。柳条将要舒展却还没有舒展，柔软的梢头在风中散开，麦苗破土而出，短小如兽颈上的毛，才一寸左右。游人虽然还不旺盛，（但）用泉水煮茶喝的，拿着酒杯唱歌的，身着艳装骑驴的，也时时能看到。风力虽然还很强，然而走路就汗流浃背。举凡（那些）在沙滩上晒太阳的鸟，浮到水面上戏水的鱼，都悠然自得，一切动物都透出喜悦的气息。（我这）才知道郊野之外未曾没有春天，可住在城里的人（却）不知道啊。\n　　不会因为游玩而耽误公事，能无拘无束潇洒在山石草木之间游玩的，恐怕只这个职位了。而此地正好离我近，我将从现在开始出游，怎能没有记述？（这是）明万历二十七年二月啊。', poem_notes = '第一段\n满井，明清时期北京东北角的一个游览地，因有一口古井，“井高于地，泉高于井，四时不落”，所以叫“满井”。\n燕（yān）指今河北北部、辽宁西部、北京一带。这一地区原为周代诸侯国燕国故地。\n花朝（zhāo）节:旧时以阴历二月十二日为花朝节，据说这一天是百花生日。\n犹：仍然。\n冻风时作（zuò）：冷风时常刮起来。作，起。\n砾：小石块。\n局促：拘束。\n第二段\n和：暖和。\n偕：一同。\n东直：北京东直门，在旧城东北角。满井在东直门北三四里。\n土膏：肥沃的土地。膏，肥沃。\n脱笼之鹄：从笼中飞出去的天鹅。\n冰皮：冰层，指水面凝结的冰层犹如皮肤。\n乍：刚刚，开始。\n鳞浪：像鱼鳞似的细浪纹。\n晶晶然：光亮的样子。\n新开：新打开。\n冷光：清冷的光。\n乍出于匣也：乍，突然。匣，指镜匣。\n山峦为晴雪所洗：山峦被融化的雪水洗干净。为，被。晴雪，晴空之下的积雪。\n娟然：美好的样子。\n拭（shì）：擦拭\n如倩女之靧（huì）面而髻（jì）鬟（huán）之始掠也：像美丽的少女洗好了脸刚梳好髻鬟一样。倩，美丽的女子。\n靧，洗脸。\n掠，梳掠。\n舒：舒展。\n梢：柳梢。\n披风：在风中散开。\n披，开、分散。\n麦田浅鬣（liè）寸许：意思是麦苗高一寸左右。 鬣：兽颈上的长毛，这里形容不高的麦苗。\n泉而茗（míng）者，罍（léi）而歌者，红装而蹇（jiǎn）者：汲泉水煮茶喝的，端着酒杯唱歌的，穿着艳装骑驴的。\n茗，茶。罍，酒杯。\n蹇，这里指 驴。\n泉、茗、罍、蹇都是名词作动词用。\n泉，用泉水煮。\n茗，煮茶。\n罍，端着酒杯。\n蹇，骑驴。\n劲：猛、强有力。读jìng。\n虽：注意，这里的虽指虽然，而不是即使。\n浃（jiā）：湿透。\n悠然自得：悠然，闲适的样子。自得，内心得意舒适。\n曝沙之鸟，呷（xiā）浪之鳞：在沙滩上晒太阳的鸟，浮到水面戏水的鱼。\n呷，吸，这里用其引申义。\n鳞，代鱼。\n毛羽鳞鬣：毛，指虎狼兽类；羽，指鸟类；鳞，指鱼类和爬行动物；鬣，指马一类动物。合起来，泛指一切动物。 未始无春：未尝没有春天。这是对第一段“燕地寒”等语说的。\n第三段\n夫（fu）：用于句子开头，可翻译为大概。\n堕（huī）事：耽误公事。堕，坏、耽误。\n潇然：悠闲自在的样子。\n惟：只\n此官：当时作者任顺天府儒学教授，是个闲职。\n而此地适与余近：适，正好。\n恶（wū）能：怎能。恶，怎么。\n纪：记录。\n己亥：明万历二十七年（1599年）', poem_tags = '初中文言文,小品,春天,纪游,写景,抒情' WHERE poem_title = '满井游记' AND poem_author = '袁宏道';
UPDATE edu_poem SET poem_translation = '暮春时节，长安城处处柳絮飞舞、落红无数，寒食节东风吹拂着皇家花园的柳枝。\n夜色降临，宫里忙着传蜡烛，袅袅炊烟散入王侯贵戚的家里。', poem_notes = '春城：暮春时的长安城。\n寒食：古代在清明节前两天的节日，焚火三天，只吃冷食，所以称寒食。御柳：御苑之柳，皇城中的柳树。\n汉宫：这里指唐朝皇官。传蜡烛：寒食节普天下禁火，但权贵宠臣可得到皇帝恩赐而得到燃烛。《唐辇下岁时记》“清明日取榆柳之火以赐近臣”。\n五侯：汉成帝时封王皇后的五个兄弟王谭、王商、王立、王根、王逢时皆为候，受到特别的恩宠。这里泛指天子近幸之臣。', poem_appreciation = '寒食是我国古代一个传统的节日，在清明前两天，是从春秋时传下来的，是晋文公为了怀念抱木焚死的介子推而定的。\n\n　　据孟棨《本事诗》记载：德宗时制诰缺乏人才，中书省提名请求御批，德宗批复说：“与韩翃”，当时有两个韩翃，于是中书省又以两人的名字同时进呈。\n\n　　德宗便批与写“春城无处不飞花”的韩翃。这虽是一段佳话，但足见《寒食》这首诗的广泛流传和受到的赏识。\n\n　　这是一首讽刺诗，但诗人的笔法巧妙含蓄。从表面上看，似乎只是描绘了一幅寒食节长安城内富于浓郁情味的风俗画。实际上，透过字里行间可感受到作者怀着强烈的不满，对当时权势显赫、作威作福的宦官进行了深刻的讽刺。中唐以后，几任昏君都宠幸宦官，以致他们的权势很大，败坏朝政，排斥朝官，正直人士对此都极为愤慨。本诗正是因此而发。\n\n　　“春城无处不飞花，寒食东风御柳斜”，这两句描写春日长安城花开柳拂的景色。“无处”指花开既多又广、“飞花”写花开的盛况，时值春日，长安城到处是飞花柳絮，一派缤纷绚烂的景象。“东风”指春风，“御柳斜”是状摹宫苑杨柳在春风吹拂下的摇摆姿态。“斜”字用得妙，生动地写出了柳枝的摇曳之神。这是寒食节京城的白天景色。景色由大而小，由全城而入宫苑。下面接着写宫苑傍晚的景象。“日暮汉宫传蜡烛，轻烟散入五侯家”，是写天黑时分，宫苑里传送着一支支由皇帝恩赐给宦官的蜡烛。蜡烛燃烧通明，升腾起淡淡的烟雾，袅袅娜娜地萦绕在宦官家，到处弥漫着威福恩加的气势！使人如见他们那种炙手可热、得意洋洋的骄横神态。在封建习俗的统治下，不要说全城百姓，就连那些不是宠臣的朝官之家，在禁止烟火的寒食之夜，恐怕也都是漆黑一片。\n\n　　唯独这些宦官之家，烛火通明，烟雾缭绕。由一斑而见全豹，仅此一点，足见这些宦官平日如何弄权倚势，欺压贤良。作者在这里仅用两句诗，写了一件传蜡烛的事情，就对皇帝的厚待亲信宦官，宦官的可恶可憎的面目暴露无遗，达到了辛辣讽刺的目的。', poem_tags = '唐诗三百首,寒食节,典故,讽刺,早教古诗100首' WHERE poem_title = '寒食' AND poem_author = '韩翃';
UPDATE edu_poem SET poem_translation = '往前不见古代招贤的圣君，向后不见后世求才的明君。\n只有那苍茫天地悠悠无限，止不住满怀悲伤热泪纷纷。', poem_notes = '幽州：古十二州之一，现今北京市。幽州台：即黄金台，又称蓟北楼，故址在今北京市大兴，是燕昭王为招纳天下贤士而建。\n前：过去。古人：古代那些能够礼贤下士的圣君。\n后：未来。来者：后世那些重视人才的贤明君主。\n念：想到。悠悠：形容时间的久远和空间的广大。\n怆（chuàng）然：悲伤凄恻的样子。涕：古时指眼泪。', poem_appreciation = '《登幽州台歌》这首短诗，深刻地表现了诗人怀才不遇、寂寞无聊的情绪。语言苍劲奔放，富有感染力，成为历来传诵的名篇。\n\n　　“前不见古人，后不见来者。”这里的古人是指古代那些能够礼贤下士的贤明君主。《蓟丘览古赠卢居士藏用》与《登幽州台歌》是同时之作，其内容可资参证。《蓟丘览古赠卢居士藏用》七首，对战国时代燕昭王礼遇乐毅、郭隗，燕太子丹礼遇田光等历史事迹，表示无限钦慕。但是，像燕昭王那样前代的贤君既不复可见，后来的贤明之主也来不及见到，自己真是生不逢时；当登台远眺时，只见茫茫宇宙，天长地久，不禁感到孤单寂寞，悲从中来，怆然流泪了。因此以“山河依旧，人物不同”来抒发自己“生不逢辰”的哀叹。这里免不了有对时世的感伤，但也有诗人对诗坛污浊的憎恶。诗人看不见前古贤人，古人也没来得及看见诗人；诗人看不见未来英杰，未来英杰同样看不见诗人，诗人所能看见以及能看见诗人的，只有眼前这个时代。这首诗以慷慨悲凉的调子，表现了诗人失意的境遇和寂寞苦闷的情怀。这种悲哀常常为旧社会许多怀才不遇的人士所共有，因而获得广泛的共鸣。\n\n　　这首诗没有对幽州台作一字描写，而只是登台的感慨，却成为千古名篇。诗篇风格明朗刚健，是具有“汉魏风骨”的唐代诗歌的先驱之作，对扫除齐梁浮艳纤弱的形式主义诗风具有拓疆开路之功。在艺术上，其意境雄浑，视野开阔，使得诗人的自我形象更加鲜亮感人。全诗语言奔放，富有感染力，虽然只有短短四句，却在人们面前展现了一幅境界雄浑，浩瀚空旷的艺术画面。诗的前三句粗笔勾勒，以浩茫宽广的宇宙天地和沧桑易变的古今人事作为深邃、壮美的背景加以衬托。第四句饱蘸感情，凌空一笔，使抒情主人公——诗人慷慨悲壮的自我形象站到了画面的主位上，画面顿时神韵飞动，光彩照人。从结构脉络上说，前两句是俯仰古今，写出时间的绵长；第三句登楼眺望，写空间的辽阔无限；第四句写诗人孤单悲苦的心绪。这样前后相互映照，格外动人。\n\n　　在用辞造语方面，此诗深受《楚辞》特别是其中《远游》篇的影响。《远游》有云：“惟天地之无穷兮，哀人生之长勤。往者余弗及兮，来者吾不闻。”此诗语句即从此化出，然而意境却更苍茫遒劲。\n\n　　同时，在句式方面，采取了长短参错的楚辞体句法。上两句每句五字，三个停顿，其句式为：\n\n　　前──不见──古人，后──不见──来者；\n\n　　后两句每句六字，四个停顿，其句式为：\n\n　　念──天地──之──悠悠，独──怆然──而──涕下。\n\n　　前两句音节比较急促，传达了诗人生不逢时、抑郁不平之气；后两句各增加了一个虚字（“之”和“而”），多了一个停顿，音节就比较舒徐流畅，表现了他无可奈何、曼声长叹的情景。全篇前后句法长短不齐，音节抑扬变化，互相配合，增强了艺术感染力。', poem_tags = '唐诗三百首,初中古诗,伤怀' WHERE poem_title = '登幽州台歌' AND poem_author = '陈子昂';
UPDATE edu_poem SET poem_translation = '身经沙场百战铁甲已破碎，城池南面被敌人重重包围。\n突进营垒，射杀呼延大将，独自率领残兵千骑而归。', poem_notes = '沙场：胡三省《通鉴注》：“唐人谓沙漠之地为沙场。“碎铁衣：指身穿的盔甲都支离破碎。\n呼延：呼延，是匈奴四姓贵族之一，这里指敌军的一员悍将。', poem_appreciation = '赏析二 　　这是一首用乐府古题写的边塞诗,其内容已基本失去专写“军旅苦辛”的古义,也无法合乐歌唱,因而,有别于汉魏乐府曲辞中的(从军行》。唐人以“从军行”为诗题,一般来说,旨在标明诗歌题材属“边塞”一类而已。盛唐边塞诗,从总体上看,大多气势磅礴,极富悲壮崇高之美。李白的这首诗就写得辞健气壮,慷慨激昂,有撼人心族的艺术魅力。 首句“百战沙场碎铁衣”,诗人用平直叙起的笔法写出了征战环境之“苦”。“百战”,意谓战事频繁。“碎铁衣”,形容气候恶劣,斗争严酷。其中,“碎”字下得绝妙,颇值玩味。将士的恺甲都已冻碎难着,令人宛见“瀚海阑干百丈冰,愁云惨淡万里凝”(岑参《白雪歌送武判官归京))的塞外荒寒景象。此外,唐军将士因长期作战,来不及休整,给养十分困难的情形,也可由此一“碎”字思而得之。 ▲', poem_tags = '边塞,战争' WHERE poem_title = '从军行·其二' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '门帘外传来雨声潺潺，浓郁的春意又要凋残。罗织的锦被受不住五更时的冷寒。只有迷梦中忘掉自身是羁旅之客，才能享受片时的欢娱。\n独自一人在太阳下山时在高楼上倚靠栏杆遥望远方，因为想到旧时拥有的无限江山，心中便会泛起无限伤感。离别它是容易的，再要见到它就很艰难。像流失的江水凋落的红花跟春天一起回去也，今昔对比，一是天上一是人间。', poem_notes = '此词原为唐教坊曲，又名《浪淘沙令》、《卖花声》等。唐人多用七言绝句入曲，南唐李煜始演为长短句。双调，五十四字（宋人有稍作增减者），平韵，此调又由柳永、周邦彦演为长调《浪淘沙漫》，是别格。\n潺潺：形容雨声。\n阑珊：衰残。一作“将阑”。\n罗衾（音qīn）：绸被子。\n不耐：受不了。一作“不暖”。\n身是客：指被拘汴京，形同囚徒。\n一晌（音shǎng）：一会儿，片刻。一作“饷”（音xiǎng）\n贪欢：指贪恋梦境中的欢乐。\n凭栏：靠着栏杆。\n江山：指南唐河山。', poem_appreciation = '此词基调低沉悲怆，透露出李煜这个亡国之君绵绵不尽的故土之思，可以说这是一支宛转凄苦的哀歌。\n\n　　上片用倒叙，先写梦醒再写梦中。起首说五更梦回，薄薄的罗衾挡不住晨寒的侵袭。帘外，是潺潺不断的春雨，是寂寞零落的残春；这种境地使他倍增凄苦之感。“梦里”两句，回过来追忆梦中情事，睡梦里好象忘记自己身为俘虏，似乎还在故国华美的宫殿里，贪恋着片刻的欢娱，可是梦醒以后，“想得玉楼瑶殿影，空照秦淮”（《浪淘沙》），却加倍地感到痛苦。\n\n　　过片三句自为呼应。说“独自莫凭栏”，是因为“凭栏”而不见“无限江山”，又将引起“无限伤感”。“别时容易见时难”，是当时常用的语言。《颜氏家训·风操》有“别易会难”之句，曹丕《燕歌行》中也说“别日何易会日难”。然而作者所说的“别”，并不仅仅指亲友之间，而主要是与故国“无限江山”分别；至于“见时难”，即指亡国以后，不可能见到故土的悲哀之感，这也就是他不敢凭栏的原因。在另一首《虞美人》词中，他说：“凭栏半日独无言，依旧竹声新月似当年。”眼前绿竹眉月，还一似当年，但故人、故土，不可复见，“凭栏”只能引起内心无限痛楚，这和“独自莫凭栏”意思相仿。\n\n　　“流水”两句，叹息春归何处。张泌《浣溪沙》有“天上人间何处去，旧欢新梦觉来时”之句，“天上人间”，是说相隔遥远，不知其处。这是指春，也兼指人。词人长叹水流花落，春去人逝，故国一去难返，无由相见。\n\n　　这首词，情真意切、哀婉动人，深刻地表现了词人的亡国之痛和囚徒之悲，生动地刻画了一个亡国之君的艺术形象。正如李煜后期词反映了他亡国以后囚居生涯中的危苦心情，确实是“眼界始大，感慨遂深”。且能以白描手法诉说内心的极度痛苦，具有撼动读者心灵的惊人艺术魅力。此词就是一个显著的例子。', poem_tags = '宋词三百首,婉约,记梦,感伤' WHERE poem_title = '浪淘沙令·帘外雨潺潺' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '也许是园主担心我的木屐踩坏他那爱惜的青苔，轻轻地敲柴门，久久没有人来开。\n可是这满园的春色毕竟是关不住的，你看，那儿有一枝粉红色的杏花伸出墙头来。', poem_notes = '游园不值：想游园没能进门儿。值，遇到；不值，没得到机会。\n应怜：概是感到心疼吧。应，表示猜测；怜，怜惜。屐（jī）齿：屐是木鞋，鞋底前后都有高跟儿，叫屐齿。\n小扣：轻轻地敲门。柴扉（fēi）：用木柴、树枝编成的门。', poem_appreciation = '头两句“应怜屐齿印苍苔，小扣柴扉久不开”，交代作者访友不遇，园门紧闭，无法观赏园内的春花。但写得很幽默风趣，说大概是园主人爱惜园内的青苔，怕我的屐齿在上面留下践踏的痕迹，所以“柴扉”久扣不开。将主人不在家，故意说成主人有意拒客，这是为了给下面的诗句作铺垫。由于有了“应怜屐齿印苍苔”的设想，才引出后两句更新奇的想象：虽然主人自私地紧闭园门，好像要把春色关在园内独赏，但“春色满园关不住，一枝红杏出墙来”。这后两句诗形象鲜明，构思奇特，“春色”和“红杏”都被拟人化，不仅景中含情，而且景中寓理，能引起读者许多联想，受到哲理的启示：“春色”是关锁不住的，“红杏”必然要“出墙来”宣告春天的来临。同样，一切新生的美好的事物也是封锁不住、禁锢不了的，它必能冲破任何束缚，蓬勃发展。\n\n　　因游赏受阻而扫兴又得兴，这应该看作是一种精神奇遇。此诗就是记录这种精神奇遇的，它是一首无法成游、却胜于成游的别具一格的记游诗。首句又作“应嫌屐齿印苍苔”，我却嫌这“嫌”字不好，它似乎在表现园主人闭门谢客、远离尘嚣的清高，但清高得有点做作。倒是“怜”字有情致，高齿的木板鞋（屐，音jī）不避苔滑路僻，去探访春天消息，其锲而不舍的精神是值得怜惜、同情，尽管它吃了“闭门羹，轻拍木编门扇（柴扉，音fēi）而久久不见打开。“嫌”是从推测园主人感情的角度落笔，“怜”则是从探访春色者的 游兴的角度落笔，后者更贴合“游园不值”、无缘进门的诗题。无缘 进得园门，游赏的愿望受阻，未免有点扫兴。但扫兴之余惊喜地发现奇遇、奇兴，由一枝红杏出墙，想象着墙内满园春色灿烂夺目，这就把“屐齿游园”转化为“精神游园”了。失望后的意外精神补偿，弥足珍贵。春色在这么一“关”一“出”之间，冲破围墙，溢出园外，显示出一种蓬蓬勃勃、关锁不住的生命力度。到底自然界比园主人更能体贴游人的情趣，这就不仅是游人怜屐，而且春色派遣红杏使者也 来怜屐了。从某些语句上看，此诗点化了陆游的《马上作》一诗：“平桥小陌雨初收，淡日穿云翠霭浮。杨柳不遮春色断，一枝红杏出墙头。”不过陆游此作未免平展，有点马上观花，不及叶绍翁之作那么精神专注，在深挚的精神体验和心理波折中，迸发出春光难锁、喜从天降的生命力度，以及情趣盎然的精神哲学的启悟了。可见名家之诗不一定都能省心地成为名作，非名家一旦对生命与诗进行精诚开发，也可能出现奇迹。\n\n　　诗以“游园不值”为题，本是说自己游园的目的没有达到。可是诗人却由此生发感想。他想，这可能是因为主人怕踩坏园中的青苔，怕破坏了园中的美景，因此才不让自己进来的缘故吧。短短两句，写出了诗人的善解人意，也写出了他那一片怜春惜春的情怀！但这首诗更为脍炙人口的还是后两句。柴门虽然不开，满园春色却难以关住，你看一枝红杏探出墙头，不正在向人们炫耀着春天的美丽吗？“关不住”、“出墙来”，简单的几个字，写出的并不仅仅是园中美丽的春色，还写出了春天的勃勃生机，写出了一片春意盎然。尽管主人没有访到，但作者的心灵已经被这动人的早春景色完全占满了！', poem_tags = '古诗三百首,春天,游园,写景,哲理,早教古诗100首' WHERE poem_title = '游园不值' AND poem_author = '叶绍翁';
UPDATE edu_poem SET poem_translation = '长江向东滚滚而去，我也在外滞留太久。故乡远隔万里，令我时时思念。\n何况秋风已经劲吹，山山飘零枯黄秋叶。', poem_notes = '⑴滞（zhì）：淹留。一说停滞，不流通。\n⑵万里：形容归程之长。念将归：有归乡之愿，但不能成行。\n⑶况属：何况是。属：恰逢，正当。高风：山中吹来的风。一说即秋风，指高风送秋的季节。', poem_appreciation = '这是一首抒写旅愁归思的诗，大概作于王勃被废斥后在巴蜀作客期间。\n\n　　诗的前半首是一联对句。诗人以“万里”对“长江”，是从地理概念上写远在异乡、归路迢迢的处境；以“将归”对“已滞”，是从时间概念上写客旅久滞、思归未归的状况。两句中的“悲”和“念”二字，则是用来点出因上述境况而产生的感慨和意愿。诗的后半首，即景点染，用眼前“高风晚”、“黄叶飞”的深秋景色，进一步烘托出这个“悲”和“念”的心情。\n\n　　首句“长江悲已滞”，在字面上也许应解释为因长期滞留在长江边而悲叹。可以参证的有他的《羁游饯别》诗中的“游子倦江干”及《别人四首》之四中的“雾色笼江际”、“何为久留滞”诸句。但如果与下面“万里”句合看，可能诗人还想到长江万里、路途遥远而引起羁旅之悲。这首诗的题目是《山中》，也可能是诗人在山上望到长江而起兴，是以日夜滚滚东流的江水来对照自己长期滞留的旅况而产生悲思。与这句诗相似的有杜甫《成都府》诗中的名句“大江东流去，游子日月长”，以及谢脁的名句“大江流日夜，客心悲未央”。这里，“长江”与“已滞”以及“大江”与“游子”、“客心”的关系，诗人自己可以有各种联想，也任读者作各种联想。在一定范围内，理解可以因人而异，即所谓“诗无达诂”。\n\n　　次句“万里念将归”，似出自宋玉《九辩》“登山临水兮送将归”句，而《九辩》的“送将归”，至少有两种不同的解释：一为送别将归之人；一为送别将尽之岁。至于这句诗里的“将归”，如果从前面提到的《羁游饯别》、《别人四首》以及《王子安文集》中另外一些客中送别的诗看，可以采前一解释；如果从此诗后半首的内容看，也可以取后一解释。但联系此句中的“念”字，则以解释为思归之念较好，也就是说，这句的“将归”和上句的“已滞”一样，都指望远怀乡之人，即诗人自己。但另有一说，把上句的“已滞”看作在异乡的客子之“悲”，把这句的“将归”看作万里外的家人之“念”，似也可通。这又是一个“诗无达诂”的例子。\n\n　　三四两句“况属高风晚，山山黄叶飞”，写诗人在山中望见的实景，也含有从《九辩》“悲哉秋之为气也，萧瑟兮草木遥落而变衰”两句化出的意境。就整首诗来说，这两句所写之景是对一二两句所写之情起衬映作用的，而又有以景喻情的成分。这里，秋风萧瑟、黄叶飘零的景象，既用来衬映旅思乡愁，也可以说是用来比拟诗人的萧瑟心境、飘零旅况。当然，这个比拟是若即若离的。同时，把“山山黄叶飞”这样一个纯景色描写的句子安排在篇末，在写法上又是以景结情。南宋沈义父在《乐府指迷》中说：“结句须要放开，含有余不尽之意，以景结情最好。”这首诗的结句就有宕出远神、耐人寻味之妙。\n\n　　诗歌在艺术上常常是抒情与写景两相结合、交织成篇的。明代谢榛在《四溟诗话》中说：“作诗本乎情、景。……景乃诗之媒，情乃诗之胚，合而为诗。”这首诗，前半抒情，后半写景。但诗人在山中、江边望见的高风送秋、黄叶纷飞之景，正是产生久客之悲、思归之念的触媒；而他登山临水之际又不能不是以我观物，执笔运思之时也不能不是缘情写景，因此，后半首所写之景又必然以前半首所怀之情为胚胎。诗中的情与景是互相作用、彼此渗透、融合为一的。前半首的久客思归之情，正因深秋景色的点染而加浓了它的悲怆色彩；后半首的风吹叶落之景，也因旅思乡情的注入而加强了它的感染力量。\n\n　　王勃还有一首《羁春》诗：“客心千里倦，春事一朝归。还伤北园里，重见落花飞。”诗的韵脚与这首《山中》诗完全相同，抒写的也是羁旅之思，只是一首写于暮春，一首写于晚秋，季节不同，用来衬托情意的景物就有“落花飞”与“黄叶飞”之异。两诗参读，有助于进一步了解诗人的感情并领会诗笔的运用和变化。', poem_tags = '山水,思乡' WHERE poem_title = '山中' AND poem_author = '王勃';
UPDATE edu_poem SET poem_translation = '道残阳铺水中，半江瑟瑟半江红：\n\n　　诗人抓住了傍晚夕阳斜射下的江面上呈现出的两种不同的颜色，表现出江面微波粼粼、光色瞬息变化的绚烂景象。\n\n　　这句诗的意思是：傍晚时分，快要落山的夕阳，柔和地铺在江水之上。晚霞斜映下的江水看上去好似鲜红色的，而绿波却又在红色上面滚动。\n\n　　可怜九月初三夜，露似真珠月似弓：\n\n　　诗人在这里把天上地上的两种景象压缩在诗里，通过对“露”和“月”的视觉形象的描写，创造出秋夜一派和谐宁静的意境。\n\n　　这句诗的意思是：九月初三这个夜晚多么可爱啊，岸边草茎树叶上的露珠像稀少的珍珠一样，而升起的一弯新月像一张精巧的弯弓。 ▲', poem_appreciation = '赏析二 　　《暮江吟》并非始终写“暮色江景”。如果只从《暮江吟》的标题看，此诗似乎应始终歌吟“日落前后”的暮色江景，但诗中“可怜九月初三夜”的“夜”字，以及“露似真珠月似弓”，则明显地是在写“夜晚”。按《辞海》里的解释：“露是空气中水汽因地面或地物表面散发热量，使得地面或地物表面的温度低于气温（但仍高于0℃），而凝结在其上的水珠。常见于晴朗无风的夜间或清晨。”由此可见，此诗标题与内容有不相吻合的地方，并非始终写暮色江景。理解此诗时一定要把握住这个特点，不能机械地只从标题去理解内容。有人认为，此诗的标题与内容中的时间不完全相符是作者的疏忽或失笔。其实，这种情况在唐诗中是很常见的，如杜甫的《日暮》就从黄昏时分一直写到“草露滴秋根”；贾岛的《暮过山村》也从日落写到明月高悬。所以，不能完全用自然科学的研究方法去研究文学作品。 ▲', poem_tags = '写景,写水,长江,古诗里的十二个月' WHERE poem_title = '暮江吟' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '你在秋天盛开，从不与百花为丛。独立在稀疏的篱笆旁边，你的情操意趣并未衰穷。\n宁可在枝头上怀抱着清香而死，绝不会吹落于凛冽北风之中！', poem_notes = '不并：不合、不靠在一起。并，一起。\n疏篱：稀疏的篱笆。\n未穷：未尽，无穷无尽。\n抱香死：菊花凋谢后不落，仍系枝头而枯萎，所以说抱香死。\n何曾：哪曾、不曾。\n北风：寒风，此处语意双关，亦指元朝的残暴势力。', poem_appreciation = '这首自题《寒菊》图诗，集中表现了郑思肖的思想品格和胸怀襟抱。诗从晚香着笔：百花在春光明媚的时节盛开，独有菊花挺立在凌厉的风霜之中，不与百花争妍斗艳。郑接着，诗人又写百花已经凋零，只有菊花立于疏篱旁，意趣无穷。这里的“趣”，既指菊花的傲风拒霜、独放光华的自然之趣，也是画家融入菊花形象中的高洁坚贞、真淳自得的主观之趣。诗句融入了陶渊明的“采菊东篱下”、 “此中有真意”的意趣。范成大在《范村菊谱序》里提到“以菊比君子”的说法，云： 岁华晼晚，草木变衰，乃独晔然秀发，傲睨风露，此幽人逸士之操。”范成大序文与郑思肖诗句的题旨是相同的，范文可以帮助我们领悟郑思肖诗歌意象的深刻内蕴。\n\n　　后两句诗意深转一层。菊花盛开后，在枝头逐渐枯萎，花瓣并不凋谢落地，故云“枝头抱香死”。北风在南宋文学家的笔下象喻来自北方的贵族统治集团的侵扰。诗句用隐喻手法，是说宁可为坚持气节而死去，不愿屈服于蒙元统治集团，表现了“宁为玉碎，不为瓦全”的凛然正气，真诚地剖白了诗人自己的至死不渝的崇高民族气节。这两句诗有所本，宋代朱淑真《菊花》诗：“宁可抱香枝头老，不随黄叶舞秋风”，郑思肖略事点化，使诗的意蕴更为深化，带有强烈的时代气息。\n\n　　这首诗题咏的对象是画上的菊，诗歌的重点是托物言志，不在于发挥画理，因此具有咏物诗的特征。全诗写菊花之形貌，得菊花之神理，又能超乎其上，在充分表现菊花自然属性的同时，摅写了郑思肖的爱国情操，既表现出菊花的自然美，菊画的绘画美，又表现了画家兼诗人的人格美，使菊花形象的自然性与社会性得到和谐的统一，这首题画诗也便有了崇高的审美体验和深睿的哲理含蕴，使读者从中获得美感愉悦和生活启迪。', poem_tags = '古诗三百首,秋天,写花,菊花,言志' WHERE poem_title = '寒菊 / 画菊' AND poem_author = '郑思肖';
UPDATE edu_poem SET poem_translation = '迢迢万里的银河朝西南方向下坠，喔喔的鸡叫之声在邻家不断长鸣。\n疾病折磨我几乎把救亡壮志消尽，出门四望不禁手搔白发抱憾平生。\n\n三万里长的黄河奔腾向东流入大海，五千仞高的华山耸入云霄上摩青天。\n中原人民在胡人压迫下眼泪已流尽，他们盼望王师北伐盼了一年又一年。', poem_notes = '将晓：天将要亮。篱门：竹子或树枝编的门。迎凉：出门感到一阵凉风。\n天汉：银河。《诗经·小雅·大东》：“维天有汉，监亦有光。”毛传：“汉，天河也。”\n搔首：以手搔头。焦急或有所思貌。怆（chuàng）：悲伤。\n三万里：长度，形容它的长，是虚指。河：指黄河。\n五千仞（rèn）：形容它的高。仞，古代计算长度的一种单位，周尺八尺或七尺，周尺一尺约合二十三厘米。岳：指五岳之一西岳华山。黄河和华山都在金人占领区内。一说指北方泰、恒、嵩、华诸山。摩天：迫近高天，形容极高。摩，摩擦、接触或触摸。\n遗民：指在金占领区生活的汉族人民，却认同南宋王朝统治的人民。泪尽：眼泪流干了，形容十分悲惨、痛苦。胡尘：指金人入侵中原，也指胡人骑兵的铁蹄践踏扬起的尘土和金朝的暴政。胡，中国古代对北方和西方少数民族的泛称。\n南望：远眺南方。王师：指宋朝的军队。', poem_appreciation = '组诗的第一首落笔写银河西坠，鸡鸣欲曙，从所见所闻渲染出一种苍茫静寂的气氛。“一再鸣”三字，可见百感已暗集毫端。三四句写“有感”正面。一个“欲”字，一个“怆”字表现了有心杀敌无力回天的感慨。\n\n　　第一首以沉郁胜，第二首则以雄浑胜。第一首似一支序曲，第二首才是主奏，意境更为辽阔，感情也更为沉痛。\n\n　　要想理解第二首诗，必须理解“五千仞岳”，于此有人说是泰山，因为泰山最高，被列在五岳之首，历代君王也多要去泰山封禅，用黄河与泰山作为中原大好山河的象征似乎是再恰当不过的了；赖汉屏认为岳指华山，理由是黄河与华山都在金人占领区内。陆游诗中的“岳”是指华山，可以从《宋史·陆游传》以及陆游的诗词中找到证据。《宋史·陆游传》中有这样的记载：“王炎宣抚川、陕，辟为干办公事。游为炎陈进取之策，以为经略中原必自长安始，取长安必自陇右始。”从中可以看出陆游收复中原的策略，就是通过四川进入陇右，先夺取长安，然后凭借关中的屏障进攻退守，像秦一样收复中原。这样的例子还有很多，陆游把这么多心思用在这一块土地上，可见他的主张是横贯其诗歌创作的始终的，那么“五千仞山上摩天”中的岳指华山自然就最恰当了。“三万里河东入海，五千仞岳上摩天。”两句一横一纵，北方中原半个中国的形胜，便鲜明突兀、苍莽无垠地展现出来了。奇伟壮丽的山河，标志着祖国的可爱，象征着民众的坚强不屈，已留下丰富的想象空间。然而，大好河山，陷于敌手，使人感到无比愤慨。这两句意境扩大深沉，对仗工整犹为余事。\n\n　　下两句笔锋一转，顿觉风云突起，诗境向更深远的方向开拓。“泪尽”一词，千回万转，更含无限酸辛。眼泪流了六十多年，早已尽了。但即使“眼枯终见血”，那些心怀故国的遗民依然企望南天；金人马队扬起的灰尘，隔不断他们苦盼王师的视线。中原广大人民受到压迫的沉重，经受折磨历程的长久，期望恢复信念的坚定不移与迫切，都充分表达出来了。以“胡尘”作“泪尽”的背景，感情愈加沉痛。结句一个“又”字扩大了时间的上限。他们年年岁岁盼望着南宋能够出师北伐，可是岁岁年年此愿落空。他们不知道，南宋君臣早已把他们忘记得干干净净。诗人极写北地遗民的苦望，实际上是在表露自己心头的失望。当然，他们还是不断地盼望下去。人民的爱国热忱真如压在地下的跳荡火苗，历久愈炽；而南宋统治集团则正醉生梦死于西子湖畔，把大好河山、国恨家仇丢在脑后，可谓心死久矣。诗人为遗民呼号，目的还是想引起南宋当国者的警觉，激起他们的恢复之志。', poem_tags = '古诗三百首,爱国,忧国忧民,同情' WHERE poem_title = '秋夜将晓出篱门迎凉有感二首' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '刚开始听到远行去南方的大雁的鸣叫声，蝉鸣就已经销声匿迹了，我登上百尺高楼，极目远眺，水天连成一片。\n霜神青女和月中嫦娥不怕寒冷，在寒月冷霜中争艳斗俏，比一比冰清玉洁的美好姿容。', poem_notes = '征雁：大雁春到北方，秋到南方，不惧远行，故称征雁。此处指南飞的雁。\n无蝉：雁南飞时。已听不见蝉鸣。\n楼南：一作“楼台”。\n水接天：水天一色，不是实写水。是形容月、霜和夜空如水一样明亮。\n青女：主管霜雪的女神。《淮南子·天文训》，青女乃出，以降霜雪”。\n素娥：即嫦娥。\n斗：比赛的意思。\n婵娟：美好，古代多用来形容女子，也指月亮。', poem_appreciation = '仅从文本看，诗写深秋月夜景色，然不作静态描写，而借神话传说宛言月夜冷艳之美。首句以物候变化说明霜冷长天，深秋已至。次句言月华澄明，天穹高迥。三四句写超凡神女，争美竞妍。诗以想像为主，意境清幽空灵，冷艳绝俗。颇可说明义山诗之唯美倾向。\n\n　　文学作品，特别是诗歌，它的特点在于即景寓情，因象寄兴。诗人不仅是写生的妙手，而应该是随物赋形的画工。最通常的题材，在杰出的诗人的笔底，往往能够创造出一种高超优美的意境。李商隐的这首《霜月》，就会有这样的特点。\n\n　　这首诗写的是深秋季节，在一座临水高楼上观赏霜月交辉的夜景。它的意思只不过说，月白霜清，给人们带来了寒凉的秋意而已。这样的景色，会使人心旷神怡。然而这诗所给予读者美的享受，却大大超过了人们在类似的实际环境中所感受到的那些。诗的形象明朗单纯，它的内涵是饱满而丰富的。\n\n　　秋天，草木摇落而变衰，眼里看到的一切，都是萎约枯黄，黯然无色；可是清宵的月影霜痕，却显得分外光明皎洁。“青女素娥俱耐冷，月中霜里斗婵娟。”尽管“琼楼玉宇，高处不胜寒”，可是冰肌玉骨的绝代佳人，愈是在宵寒露冷之中，愈是见出雾鬓风鬟之美。她们的绰约仙姿之所以不同于庸脂俗粉，正因为她们具有耐寒的特性，所以才经得起寒冷的考验。\n\n　　写霜月，不从霜月本身着笔，而写月中霜里的素娥和青衣；青女、素娥在诗里是作为霜和月的象征的。这样，诗人所描绘的就不仅仅是秋夜的自然景象，而是勾摄了清秋的魂魄，霜月的精神。这精神是诗人从霜月交辉的夜景里发掘出来的自然之美，同时也反映了诗人在混浊的现实环境里追求美好、向往光明的深切愿望；是他性格中高标绝俗、耿介不随的一面的自然流露。当然不能肯定这耐寒的素娥、青女，就是诗人隐以自喻；或者说，它另有所实指。诗中寓情寄兴，是不会如此狭隘的。王夫之说得好：“兴在有意无意之间。”（《姜斋诗话》）倘若刻舟求剑，理解得过于窒实，反而会缩小它的意义，降低它的美学价值。\n\n　　范元实云：“义山诗，世人但称其巧丽，至与温庭筠齐名。盖俗学只见其皮肤，其高情远意，皆不识也。”他引了《筹笔驿》、《马嵬》等篇来说明。（见魏庆之《诗人玉屑》卷十五引《诗眼》）其实，不仅咏史诗以及叙志述怀之作是如此，在更多的即景寄兴的小诗里，同样可以见出李商隐的“高情远意”。叶燮是看到了这点的，所以他特别指出李商隐的七言绝句，“寄托深而措辞婉”（《原诗》外编下）。于此诗，也可见其一斑。\n\n　　这首诗在艺术手法上有一点值得注意：诗人的笔触完全在空际点染盘旋，诗境如海市蜃楼，弹指即逝；诗的形象是幻想和现实交织在一起而构成的完美的整体。秋深了，树枝上已听不到聒耳的蝉鸣，辽阔的长空里，时时传来雁阵惊寒之声。在月白霜清的宵夜，高楼独倚，水光接天，望去一片澄澈空明。“初闻征雁已无蝉”二句，是实写环境背景。这环境是美妙想象的摇篮，它会唤起人们脱俗离尘的意念。正是在这个摇篮里，诗人的灵府飞进月地云阶的神话世界中去了。后两句想象中的意境，是从前两句生发出来的。', poem_tags = '秋天,月亮,抒情,早教古诗100首' WHERE poem_title = '霜月' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '竹林外两三枝桃花初放，鸭子在水中游戏，它们最先察觉了初春江水的回暖。\n河滩上已经满是蒌蒿，芦笋也开始抽芽，而河豚此时正要逆流而上，从大海回游到江河里来了。\n\n大雁北飞，就像要回到北方家乡的人那样，但是由于依恋，差一点掉了队。\n还没有飞到北方时，就已经知道北方的沙漠多风雪了，还是再在江南渡过半月的春光时节吧。', poem_notes = '惠崇（亦为慧崇）：福建建阳僧，宋初九僧之一，能诗能画。《春江晚景》是惠崇所作画名，共两幅，一幅是鸭戏图，一幅是飞雁图。钱钟书《宋诗选注》中为“晓景”。诸多注本，有用“晓景”、有用“晚景”，此从《东坡全集》及清以前注本用“晚景”。这两诗是作者元丰八年春天在靖江欲南返时江边情景的写照。\n蒌蒿：草名，有青蒿、白蒿等种。芦芽：芦苇的幼芽，可食用。\n河豚：鱼的一种，学名“鲀”，肉味鲜美，但是卵巢和肝脏有剧毒。产于我国沿海和一些内河。每年春天逆江而上，在淡水中产卵。上：指逆江而上。\n归鸿：归雁。破群：离开飞行队伍。\n依依：不舍之貌。归人：回家的人。\n朔漠：北方沙漠之地。杜甫诗：“一去紫台连朔漠。”\n更待：再等；再过。', poem_appreciation = '惠崇是个和尚，宋代画家。这首诗是苏轼题在惠崇所画的《春江晓景》上的。惠崇原画已失，这首诗有的版本题作《春江晓景》，现已无从考证。\n\n　　画以鲜明的形象，使人有具体的视觉感受，但它只能表现一个特定的画面，有一定的局限性。而一首好诗，虽无可视的图像，却能用形象的语言，吸引读者进入一个通过诗人独特构思而形成的美的意境，以弥补某些画面所不能表现的东西。\n\n　　这首题画诗既保留了画面的形象美，也发挥了诗的长处。诗人用他饶有风味、虚实相间的笔墨，将原画所描绘的春色展现得那样令人神往。在根据画面进行描写的同时，苏轼又有新的构思，从而使得画中的优美形象更富有诗的感情和引人入胜的意境。\n\n　　竹林外两三枝桃花初放，鸭子在水中游戏，它们最先察觉了初春江水的回暖。河滩上已经满是蒌蒿，芦笋也开始抽芽，而此时河豚正是上市的好时节，可以在市场上销售了。（一作沿潮水而上的时节）\n\n　　好的题画诗，既要扣合绘画主题，又不能拘于画面内容，既要能再现画境，同时又能跳出画外，别开生面，离开绘画而不失其独立的艺术生命。苏轼这首诗可以说做到了这一点。诗的前三句咏画面景物，最后一句是由画面景物引起的联想。整首诗又如同诗人即景言情，当下所得，意象妙会而自然。说前三句再现画境，其实两者也不全然等同。第二句中“水暖”(温度)、“鸭先知”(知觉)云云，是不能直接画出的。诗能描写如画，诗咏物性物理又过于画。这是因为绘画属于视觉艺术，而诗是语言艺术，有着表现上的绝对自由。最后一句进一步发挥联想，在前三句客观写景的基础上作出画中景物所属时令的判断，从而增添了南方风物之美的丰富感觉，这更是画所不能的。有关河豚的应时风味，梅尧臣《范饶州坐中客语食河豚鱼》一诗写首：“春洲生荻芽，春岸飞杨花。河豚当是时，贵不数鱼虾。”欧阳修《六一诗话》说：“河豚常出于春暮，群游水上，食柳絮而肥，南人多与荻芽为羹，云最美。”苏轼的学生张耒在《明道杂志》中也记载长江一带土人食河豚，“但用蒌蒿、荻笋(即芦芽)、菘菜三物”烹煮，认为这三样与河豚最适宜搭配。由此可见，苏轼的联想是有根有据的，也是自然而然的。诗意之妙，也有赖于此。\n\n　　诗人先从身边写起：初春，大地复苏，竹林已被新叶染成一片嫩绿，更引人注目的是桃树上也已绽开了三两枝早开的桃花，色彩鲜明，向人们报告春的信息。接着，诗人的视线由江边转到江中，那在岸边期待了整整一个冬季的鸭群，早已按捺不住，抢着下水嬉戏了。\n\n　　然后，诗人由江中写到江岸，更细致地观察描写初春景象：由于得到了春江水的滋润，满地的蒌蒿长出新枝了，芦芽儿吐尖了；这一切无不显示了春天的活力，惹人怜爱。诗人进而联想到，这正是河豚肥美上市的时节，引人更广阔地遐想。全诗洋溢着一股浓厚而清新的生活气息。', poem_tags = '古诗三百首,题画,想象,写景,春天,写水,早教古诗100首' WHERE poem_title = '惠崇春江晚景二首 / 惠崇春江晓景二首' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '青海湖上乌云密布，连绵雪山一片黯淡。边塞古城，玉门雄关，远隔千里，遥遥相望。\n守边将士，身经百战，铠甲磨穿，壮志不灭，不打败进犯之敌，誓不返回家乡。', poem_notes = '青海：指青海湖，在今青海省。唐朝大将哥舒翰筑城于此，置神威军戍守。长云：层层浓云。雪山：即祁连山，山巅终年积雪，故云。\n孤城：即玉门关。玉门关：汉置边关名，在今甘肃敦煌西。一作“雁门关”。\n破：一作“斩”。楼兰：汉时西域国名，即鄯善国，在今新疆维吾尔自治区鄯善县东南一带。西汉时楼兰国王与匈奴勾通，屡次杀害汉朝通西域的', poem_appreciation = '唐代边塞诗的读者，往往因为诗中所涉及的地名古今杂举、空间悬隔而感到困惑。怀疑作者不谙地理，因而不求甚解者有之，曲为之解者亦有之。这第四首诗就有这种情形。\n\n　　前两句提到三个地名。雪山即河西走廊南面横亘廷伸的祁连山脉。青海与玉门关东西相距数千里，却同在一幅画面上出现，于是对这两句就有种种不同的解说。有的说，上句是向前极目，下句是回望故乡。这很奇怪。青海、雪山在前，玉门关在后，则抒情主人公回望的故乡该是玉门关西的西域，那不是汉兵，倒成胡兵了。另一说，次句即“孤城玉门关遥望”之倒文，而遥望的对象则是“青海长云暗雪山”，这里存在两种误解：一是把“遥望”解为“遥看”，二是把对西北边陲地区的概括描写误解为抒情主人公望中所见，而前一种误解即因后一种误解而生。\n\n　　一、二两句，不妨设想成次第展现的广阔地域的画面：青海湖上空，长云弥温；湖的北面，横亘着绵廷千里的隐隐的雪山；越过雪山，是矗立在河西走廊荒漠中的一座孤城；再往西，就是和孤城遥遥相对的军事要塞——玉门关。这幅集中了东西数千里广阔地域的长卷，就是当时西北边戍边将士生活、战斗的典型环境。它是对整个西北边陲的一个鸟瞰，一个概括。之所以特别提及青海与玉关，这跟当时民族之间战争的态势有关。唐代西、北方的强敌，一是吐蕃，一是突厥。河西节度使的任务是隔断吐蕃与突厥的交通，一镇兼顾西方、北方两个强敌，主要是防御吐蕃，守护河西走廊。“青海”地区，正是吐蕃与唐军多次作战的场所；而“玉门关”外，则是突厥的势力范围。所以这两句不仅描绘了整个西北边陲的景象，而且点出了“孤城”西拒吐蕃，北防突厥的极其重要的地理形势。这两个方向的强敌，正是戍守“孤城”的将士心之所系，宜乎在画面上出现青海与玉关。与其说，这是将士望中所见，不如说这是将士脑海中浮现出来的画面。这两句在写景的同时渗透丰富复杂的感情：戍边将士对边防形势的关注，对自己所担负的任务的自豪感、责任感，以及戍边生活的孤寂、艰苦之感，都融合在悲壮、开阔而又迷蒙暗淡的景色里。\n\n　　三、四两句由情景交融的环境描写转为直接抒情。“黄沙百战穿金甲”，是概括力极强的诗句。戍边时间之漫长，战事之频繁，战斗之艰苦，敌军之强悍，边地之荒凉，都于此七字中概括无遗。“百战”是比较抽象的，冠以“黄沙”二字，就突出了西北战场的特征，令人宛见“日暮云沙古战场”的景象；“百战”而至“穿金甲”，更可想见战斗之艰苦激烈，也可想见这漫长的时间中有一系列“白骨掩蓬蒿”式的壮烈牺牲。但是，金甲尽管磨穿，将士的报国壮志却并没有销磨，而是在大漠风沙的磨炼中变得更加坚定。“不破楼兰终不还”，就是身经百战的将士豪壮的誓言。上一句把战斗之艰苦，战事之频繁越写得突出，这一句便越显得铿锵有力，掷地有声。一二两句，境界阔大，感情悲壮，含蕴丰富；三四两句之间，显然有转折，二句形成鲜明对照。“黄沙”句尽管写出了战争的艰苦，但整个形象给人的实际感受是雄壮有力，而不是低沉伤感的。因此末句并非嗟叹归家无日，而是在深深意识到战争的艰苦、长期的基础上所发出的更坚定、深沉的誓言，盛唐优秀边塞诗的一个重要的思想特色，就是在抒写戍边将士的豪情壮志的同时，并不回避战争的艰苦，此篇就是一个显例。可以说，三四两句这种不是空洞肤浅的抒情，正需要有一二两句那种含蕴丰富的大处落墨的环境描写。典型环境与人物感情高度统一，是王昌龄绝句的一个突出优点，这在此篇中也有明显的体现。', poem_tags = '高中古诗,边塞,战争,壮志,早教古诗100首,猖狂' WHERE poem_title = '从军行七首·其四' AND poem_author = '王昌龄';
UPDATE edu_poem SET poem_translation = '把小船停靠在烟雾迷蒙的小洲，日暮时分新愁又涌上客子心头。\n旷野无边无际远天比树还低沉，江水清清明月来和人相亲相近。', poem_notes = '建德江：指新安江流经建德（今属浙江）西部的一段江水。\n移舟：划动小船。泊：停船靠岸。烟渚（zhǔ）：指江中雾气笼罩的小沙洲。烟：一作“幽”。渚：水中小块陆地。《尔雅·释水》：“水中可居者曰洲，小洲曰渚。”\n客：指作者自己。愁：为思乡而忧思不堪。\n野：原野。旷：空阔远大。天低树：天幕低垂，好像和树木相连。\n月近人：倒映在水中的月亮好像来靠近人。', poem_appreciation = '这首诗不以行人出发为背景，也不以船行途中为背景，而是以舟泊暮宿为背景。它虽然露出一个“愁”字，但立即又将笔触转到景物描写上去了。可见它在选材和表现上都是很有特色的。诗的起句“移舟泊烟渚”，“移舟”，就是移舟近岸的意思；“泊”，这里有停船宿夜的含意。行船停靠在江中的一个烟雾朦胧的小洲边，这一面是点题，另一面也就为下文的写景抒情作了准备。\n\n　　第二句“日暮客愁新”,中的“日暮”显然和上句的“泊”、“烟”有联系，因为日暮，船需要停宿；也因为里的一段：“君子于役，不知其期，曷至哉？鸡栖于埘，日之夕矣，羊牛下来，君子于役，如之何勿思？”（《诗经·王风·君子于役》）这里写一位妇女，每当到夕阳西下、鸡进笼舍、牛羊归栏的时刻，她就更加思念在外服役的丈夫。\n\n　　远处的天空显得比近处的树木还要低，“低”和“旷”是相互依存、相互映衬的。第四句写夜已降临，高挂在天上的明月，映在澄清的江水中，和舟中的人是那么近，“近”和“清”也是相互依存、相互映衬的。“野旷天低树，江清月近人”。这种极富特色的景物，只有人在舟中才能领略得到的。诗的第二句就点出“客愁新”，这三四句好似诗人怀着愁心，在这广袤而宁静的宇宙之中，经过一番上下求索，终于发现了还有一轮孤月此刻和他是那么亲近。寂寞的愁心似乎寻得了慰藉，诗也就戛然而止了。\n\n　　然而，言虽止，意未尽。“皇皇三十载，书剑两无成。山水寻吴越，风尘厌洛京”（《自洛之越》）。诗人曾带着多年的准备、多年的希望奔入长安，而今却只能怀着一腔被弃置的忧愤南寻吴越。此刻，他孑然一身，面对着这四野茫茫、江水悠悠、明月孤舟的景色，那羁旅的惆怅，故乡的思念，仕途的失意，理想的幻灭，人生的坎坷……千愁万绪，不禁纷来沓至，涌上心头。“江清月近人”，这画面展示的是清澈平静的江水，以及水中的明月伴着船上的诗人；可那画面背后却是诗人的愁心已经随着江水流入思潮翻腾的海洋。“人禀七情，应物斯感；感物吟志，莫非自然”（刘勰《文心雕龙·明诗》）。孟浩然的这首小诗正是在这种情景相生、思与境谐的“自然流出”之中，显示出一种风韵天成、淡中有味、含而不露的艺术美。\n\n　　此诗先写羁旅夜泊，再叙日暮添愁；然后写到宇宙广袤宁静，明月伴人更亲。一隐一现，虚实相间，两相映衬，互为补充，构成一个特殊的意境。诗中虽只有一个愁字，却把诗人内心的忧愁写得淋漓尽致，然野旷江清，秋色历历在目。', poem_tags = '唐诗三百首,写景,月亮,写水,思乡' WHERE poem_title = '宿建德江' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '在梁国，有一户姓杨的人家，家里有个九岁的儿子，非常聪明。孔君平来拜见杨氏子的父亲，可是父亲不在，于是便叫杨氏子出来。杨氏子为孔君平端来水果，水果中有杨梅，孔君平指着杨梅对杨氏之子，并说：“这是你家的水果。”杨氏子马上回答说：“我可没有听说孔雀是先生您家的鸟。”', poem_notes = '孔君平：孔坦，字君平，官至延尉\n氏：姓氏，表示家族的姓。\n夫子：旧时对学者或老师的尊称。\n设：摆放，摆设。\n甚：非常。\n诣：拜见。\n未闻：没有听说过。\n示：给……看。\n惠：惠同“慧”，智慧的意思。\n乃：就；于是。\n曰：说。\n未：没有', poem_appreciation = '《杨氏之子》选自南朝刘义庆的《世说新语》，该书是一部主要记载汉末至晋代士族。\n\n　　阶层言谈轶事的小说。本文讲述了梁国姓杨的人家里面九岁的小男孩的一个故事。故事的意思是这样的：\n\n　　在梁国，有一户姓杨的人家，家里有个九岁的儿子，他非常聪明。有一天，孔君平来拜见他的父亲，恰巧他父亲不在家，孔君平就把这个孩子叫了出来。孩子端水果来招待孔君平，水果里面有杨梅。孔君平指着杨梅给孩子看，并说：“这是你家的水果。”孩子马上回答说：“我可没听说孔雀是先生您家的鸟。”\n\n　　故事情节简单，语言幽默，颇有趣味。\n\n　　这是小学生初次接触到的文言文。学习本文应重点指导学生把文章读正确。特别要注意停顿的恰当。举例如下：\n\n　　梁国/杨氏子/九岁，甚/聪惠。孔君平/诣/其父，父/不在，乃/呼儿出。为/设果，果/有杨梅。孔/指以示儿/曰：“此/是/君家果。”儿/应声答/曰：“未闻/孔雀/是夫子家禽。”\n\n　　本文虽行文简洁，不足百字，但古今字义不同是学生阅读理解的难点。要采取以下步骤帮助学生理解短文的意思：文中的“家禽”吴说的“家禽”吗?使学生能贯通上下文。\n\n　　在学生了解课文内容后，指导学生有感情地朗读课文，背诵课文。在读中体会九岁孩子的回答妙在什么地方，交流对这个问题的体会。教师可相机引导学生对比：“孔雀是夫子家禽”“未闻孔雀是夫子家禽”有什么不一样，体会这个孩子回答的委婉和机智。\n\n　　孔君平看到杨梅，联想到孩子的姓，就故意逗孩子：“这是你家的水果。”意思是，你姓杨，它叫杨梅，你们本是一家嘛!这信手拈来的玩笑话，很幽默，也很有趣。孩子应声答道：“没听说孔雀是先生您家的鸟。”这回答巧妙在哪里呢?孔君平在姓上做文章，孩子也在姓上做文章，由孔君平的“孔”姓想到了孔雀；最妙的是，他没有生硬地直接说“孔雀是夫子家禽”，而是采用了否定的方式，说“未闻孔雀是夫子家禽”，婉转对答，既表现了应有的礼貌，又表达了“既然孔雀不是您家的鸟，杨梅不是我家的果，所以请您知道这个道理”这个意思，因为他要承认孔雀是他家的鸟，他说的话才立得住脚。这足以反映出孩子思维的敏捷，语言的机智幽默。使孔君平无语可答了。这是故事中的重点部分！', poem_tags = '儿童,小学文言文' WHERE poem_title = '杨氏之子' AND poem_author = '刘义庆';
UPDATE edu_poem SET poem_translation = '秦王派人对安陵君（安陵国的国君）说：“我打算要用方圆五百里的土地交换安陵，安陵君一定要答应我！”安陵君说：“大王给以恩惠，用大的地盘交换我们小的地盘，实在是善事；即使这样，但我从先王那里接受了封地，愿意始终守卫它，不敢交换！”秦王知道后（很）不高兴。因此安陵君就派遣唐雎出使到秦国。\n\n　　秦王对唐雎说：“我用方圆五百里的土地交换安陵，安陵君却不听从我，为什么？况且秦国使韩国魏国灭亡，但安陵却凭借方圆五十里的土地幸存下来的原因，就是因为我把安陵君看作忠厚的长者，所以不打他的主意。现在我用安陵十倍的土地，让安陵君扩大自己的领土，但是他违背我的意愿，这不是看不起我吗？”唐雎回答说：“不，并不是这样的。安陵君从先王那里继承了封地所以守护它，即使（是）方圆千里的土地（也）不敢交换，更何况只是这仅仅的五百里的土地呢？”\n\n　　秦王勃然大怒，对唐雎说：“先生也曾听说过天子发怒的情景吗？”唐雎回答说：“我未曾听说过。”秦王说：“天子发怒（的时候），会倒下数百万人的尸体，鲜血流淌数千里。”唐雎说：“大王曾经听说过百姓发怒吗？”秦王说：“百姓发怒，也不过就是摘掉帽子，光着脚，把头往地上撞罢了。”唐雎说：“这是平庸无能的人发怒，不是有才能有胆识的人发怒。专诸刺杀吴王僚的时候，彗星的尾巴扫过月亮；聂政刺杀韩傀的时候，一道白光直冲上太阳；要离刺杀庆忌的时候，苍鹰扑在宫殿上。他们三个人，都是平民中有才能有胆识的人，心里的愤怒还没发作出来，上天就降示了吉凶的征兆。（现在专诸、聂政、要离）连同我，将成为四个人了。假若有胆识有能力的人（被逼得）一定要发怒，那么就让两个人的尸体倒下，五步之内淌满鲜血，天下百姓（将要）穿丧服，现在就是这个时候。”说完，拔剑出鞘立起。\n\n　　秦王变了脸色，直身而跪，向唐雎道歉说：“先生请坐！怎么会到这种（地步）！我明白了：韩国、魏国灭亡，但安陵却凭借方圆五十里的地方幸存下来，就是因为有先生您在啊！”', poem_notes = '唐雎（jū），也作唐且，人名。不辱使命，意思是完成了出使的任务。辱，辱没、辜负。\n秦王：即秦始皇嬴政，当时他还没有称皇帝。\n使：派遣，派出。\n谓...曰：对...说。\n欲：想。\n以：用，用作介词。\n之：的。\n安陵君：安陵国的国君。安陵是当时的一个小国，在河南鄢（yān）陵西北，原是魏国的附属国。战国时魏襄王封其弟为安陵君。\n守：守护。\n易：交换。\n直：只，仅仅。\n怫然：盛怒的样子。\n公：相当于“先生”，古代对人的客气称谓。\n布衣：指平民。古代没有官职的人都穿布衣服，所以称布衣。\n亦免冠徒跣（xiǎn)，以头抢（qiāng)地耳：也不过是摘掉帽子，光着脚，把头往地上撞罢了。抢，撞。徒，光着。\n庸夫：平庸无能的人。\n士：这里指有才能有胆识的人。\n专诸之刺王僚也，彗星袭月：专诸刺杀吴王僚（的时候），彗星的尾巴扫过月亮。\n聂政之刺韩傀（guī）也，白虹贯日：聂政刺杀韩傀（的时候），一道白光直冲上太阳。\n要离之刺庆忌也，仓鹰击于殿上：要离刺杀庆忌（的时候），苍鹰扑到宫殿上。仓，通“苍”，苍鹰。\n怀怒未发，休祲（jìn）降于天，与臣而将（jiāng）四矣：心里的愤怒还没发作出来，上天就降示了征兆。（专诸、聂政、要离）加上我，将成为四个人了。这是唐雎暗示秦王，他将效仿专诸、聂政、要离三人，刺杀秦王。休祲，吉凶的征兆。休，吉祥。祲，不祥。于，从。\n若：如果。\n必：将要。\n缟（gǎo）素：白色的丝织品，这里指穿丧服。\n是：此，这样。\n秦王色挠：秦王变了脸色。挠，屈服。\n长跪而谢之：长跪，古人席地而坐，两膝着地，臀部压在脚跟上。如果跪着则耸身挺腰，身体就显得高（长）起来，所以叫“长跪”。谢，认错，道歉。\n谕：通“喻”，明白，懂得。\n以：凭借。\n存：幸存\n者：原因。\n徒：只。\n以：因为。', poem_tags = '初中文言文,古文观止,赞美,写人,谋略' WHERE poem_title = '唐雎不辱使命' AND poem_author = '刘向 撰';
UPDATE edu_poem SET poem_translation = '弈秋是全国最善于下围棋的人。让弈秋教导两个人下围棋，其中一人专心致志的学习，只听弈秋的教导；另一个人虽然也在听弈秋的教导，却一心以为有天鹅要飞来，想要拉弓箭去把它射下来。虽然和前一个人一起学棋，但棋艺不如前一个人好。难道是因为他的智力不如前一个人吗？说：不是这样的。', poem_notes = '弈秋：弈：下棋。（围棋）\n秋，人名，因他善于下棋，所以称为弈秋。\n通国：全国。\n通：全。\n之：的。\n善：善于，擅长。\n使：让。\n诲：教导。\n其：其中。\n惟弈秋之为听：只听弈秋（的教导）。\n虽听之：虽然在听讲。\n以为：认为，觉得。\n鸿鹄：天鹅。（大雁）\n援：引，拉。\n将至：将要到来。\n思：想。\n弓缴：弓箭。\n缴：古时指带有丝绳的箭。\n之：谓，说。\n虽与之俱学：虽然这个人和那个专心致志的人在一起学习。\n弗若之矣：成绩却不如另外一个人。\n为是其智弗若与：因为他的智力比别人差吗？\n曰：说。\n非然也：不是这样的。\n矣：了。\n弗：不如。', poem_appreciation = '弈秋是第一个史上有记载的的围棋专业棋手，也是史上第一个有记载的从事教育的围棋名人。关于弈秋的姓名，清代学者焦循《孟子正义》里作有说明：古之以技传者，每称之为名，如医和、卜徒父是也。此名弈秋，故知秋为其名，因通国皆谓之善弈，故以弈加名称之。\n\n　　弈秋是幸运的，春秋战国延续五百年，他是留下名字的唯一的一位围棋手，也是我们所知的第一位棋手。 　　 　　围棋见于我国史籍最早的记载，是春秋时期，至今已有二千六七百年的历史了。弈秋是见于史籍记载的第一位棋手，而且是位“通国之善弈者”。关于他的记载，最早见于《孟子》。由此推测，弈秋可能是与孟子同时代的人，也可能稍早一些，由此也可以推测他大约生活在战国初期。出现弈秋这样的高手，说明当时围棋已相当普及，可以肯定，像弈秋这样的国手不只一人。\n\n　　孟子称弈秋为“通国之善弈者”。所赞通国善弈，虽未明定专称，已类似后代所称国手，并成为象征性名词。后世称某高手为“当代弈秋”者，即意味着其水平与国手相当。弈秋是当时诸侯列国都知晓的国手，棋艺高超，《弈旦评》推崇他为国棋“鼻祖”。\n\n　　由于弈秋棋术高明，当时就有很多年青人想拜他力师。弈秋收下了两个学生。一个学生诚心学艺，听先生讲课从不敢怠慢，十分专心。另一个学生大概只图弈秋的名气，虽拜在门下，并不下功夫。弈秋讲棋时，他心不在焉，探头探脑地朝窗外看，想着鸿鹄（天鹅）什么时候才能飞来。飞来了，好张弓搭箭射两下试试。两个学生同在学棋，同拜一个师，前者学有所成，后者未能领悟棋艺。学棋要专心，下棋也得如此，即使是弈秋这样的大师，偶然分心也不行。有一日，弈秋正在下棋，一位吹笙的人从旁边路过。悠悠的笙乐，飘飘忽忽的，如从云中撒下。弈秋一时走了神，侧着身子倾心聆听。此时，正是棋下到决定胜负的时候，笙突然不响了，吹笙人探身向弈秋请教围棋之道，弈秋竟不知如何对答。不是弈秋不明围棋奥秘，而是他的注意力此刻不在棋上。\n\n　　这两则小故事都记载在史书上。人们把它记下来，大概是想告诫后人们，专心致志是下好围棋的先决条件，做事情要一心一意。', poem_tags = '小学文言文,寓言,故事,学习,哲理' WHERE poem_title = '学弈' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '在南浦凄凉愁苦的分别，秋风萧索黯淡。\n回头看一次就肝肠寸断，好好离去吧，不要再回头了。', poem_notes = '南浦：南面的水边。后常用称送别之地。\n别：分别，别离。\n袅袅（niǎo）：吹拂，这里形容西风吹拂。\n好去：放心前去。\n莫：不要。', poem_appreciation = '诗的前两句，不仅点出送别的地点和时间，而且以景衬情，渲染出浓厚的离情别绪。“南浦”，是送别之处的代名词，于是一见“南浦”，令人顿生离忧。而送别的时间，又正当“西风袅袅”的秋天。秋风萧瑟，木叶飘零，此情此景，不能不令人倍增离愁。\n\n　　这里“凄凄”、“袅袅”两个叠字，用得传神。前者形容内心的凄凉、愁苦；后者形容秋景的萧瑟、黯淡。正由于送别时内心“凄凄”，故格外感觉秋风“袅袅”；而那如泣如诉的“袅袅”风声，又更加烘托出离人肝肠寸断的“凄凄”之情，两者相生相衬。而且“凄”、“袅”声调低促，一经重叠，读来格外令人回肠咽气，与离人的心曲合拍。\n\n　　后二句写得更是情意切切，缠绵悱恻。送君千里，终须一别。最后分手，是送别的高潮。分手后，离人虽已登舟而去，但离人频频回过头来，默默而“看”。“看”，本是很平常的动作，但此时此地，离人心中用言语难以表达的千种离愁、万般情思，都从这默默一“看”中表露出来，真是“此时无声胜有声”。从这个“看”字，读者仿佛看到那离人踽踽的身影，愁苦的面容和睫毛间闪动的泪花。离人的每“一看”，自然引起送行人“肠一断”，涌起阵阵酸楚。诗人连用两个“一”，把去留双方的离愁别绪和真挚情谊都表现得淋漓尽致。最后，诗人劝慰离人安心的去，不要再回头了。此句粗看似乎平淡，细细咀嚼，却意味深长。诗人并不是真要离人赶快离去，他只是想借此控制一下双方不能自抑的情感，而内心的悲楚恐怕已到了无以复加的地步。\n\n　　这首送别小诗，清淡如水，款款地流泻出依依惜别的深情。诗人精心刻画了送别过程中最传情的细节，其中的描写又似乎“人人心中所有”，如离人惜别的眼神，送别者亲切又悲凉的话语，一般人都有亲身体会，因而能牵动读者的心弦，产生强烈的共鸣，给人深刻难忘的印象。', poem_tags = '送别,写景,惜别' WHERE poem_title = '南浦别' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '长安城内一片月光，千户万户都在捣衣。\n秋风吹送捣衣声声，家家怀念戍边之人。\n何时才能平息边境战争，让我丈夫结束远征。', poem_notes = '一片月：一片皎洁的月光。\n万户：千家万户。捣衣：把衣料放在石砧上用棒槌捶击，使衣料绵软以便裁缝；将洗过头次的脏衣放在石板上捶击，去浑水，再清洗。\n吹不尽：吹不散。\n玉关：玉门关，故址在今甘肃省敦煌县西北，此处代指良人戍边之地。\n平胡虏：平定侵扰边境的敌人。\n良人：古时妇女对丈夫的称呼。《诗·唐风·绸缪》：“今夕何夕，见此良人。”罢：结束。', poem_appreciation = '全诗写征夫之妻秋夜怀思远征边陲的良人，希望早日结束战争，丈夫免于离家去远征。虽未直写爱情，却字字渗透着真挚情意；虽没有高谈时局，却又不离时局。情调用意，都没有脱离边塞诗的风韵。\n\n　　月色如银的京城，表面上一片平静，但捣衣声中却蕴含着千家万户的痛苦；秋风不息，也寄托着对边关思念的深情。读来让人怦然心动。结句是闺妇的期待，也是征人的心声。\n\n　　笼统而言，诗人的手法是先景语后情语，而情景始终交融。“长安一片月”是写景，同时又是紧扣题面，写出了“秋月扬明辉”的季节特点。而见月怀人是古典诗歌传统的表现方法，加之秋来是赶制征衣的季节，所以写月也有起兴的意义。此外，月明如昼，正好捣衣，而那“玉户帘中卷不去，捣衣砧上拂还来”的月光，也容易勾起思妇的相思之情。制衣的布帛须先置砧上，用杵捣平捣软，是谓“捣衣”。这明朗的月夜，长安城就沉浸在一片此起彼落的砧杵声中，而这种特殊的“秋声”，对于思妇又是一种难耐的挑拨。“一片”、“万户”，写光写声，似对非对，措辞天然而得咏叹味。秋风，也是撩人愁绪的，“秋风入窗里，罗帐起飘扬”，便是对思妇的第三重挑拨。月朗风清，风送砧声，声声都是怀念玉关征人的深情。用“总是”二字，情思益见深长。这里，秋月秋声与秋风织成浑成的境界，见境不见人，而人物却好像真的在，“玉关情”也很浓。王夫之评价说：“前四句是天壤间生成好句，被太白拾得。”（《唐诗评选》）此情之浓，不可遏止，于是有了末二句直表思妇的心声：“何日平胡虏，良人罢远征？”后世的某些人偏爱“含蓄”，如田同之就曾说：“余窃谓删去末二句作绝句，更觉浑含无尽。”（《西圃诗说》）其实未必是这样。“不知歌谣妙，声势出口心”（《大子夜歌》），慷慨天然，是民歌本色，原本不必故意使用那种吞吞吐吐的用语。而从内容上看，正如沈德潜指出的“本闺情语而忽冀罢征”（《说诗晬语》），使诗歌思想内容大大深化，更具社会意义，表现出古代劳动人民冀求能过和平生活的善良愿望。全诗手法如同电影，有画面，有“画外音”。月照长安万户、风送砧声、化入玉门关外荒寒的月景、插曲：“何日平胡虏，良人罢远征。”……这是十分有意味的诗境，读者须知，这种犹如女声合唱的“插曲”决不多余，它是画面的有机组成部分，在画外也在画中，它回肠荡气，激动人心。因此，《秋歌》从正面写到思情，而有不尽之情。', poem_tags = '唐诗三百首,乐府,秋天,月亮,妇女,闺怨,思念' WHERE poem_title = '子夜吴歌·秋歌' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '秀的女子啊，我见了她的容貌，就此难以忘怀。\n一日不见她，心中牵念得像是要发狂一般。\n我就像那在空中回旋高飞的凤鸟，在天下各处寻觅著凰鸟。\n可惜那美人啊不在东墙邻近。\n我以琴声替代心中情语，姑且描写我内心的情意。\n何时能允诺婚事，慰藉我往返徘徊?\n希望我的德行可以与你相配，携手同在一起。\n不知如何是好的心情无法与你比翼偕飞、百年好合，这样的伤情结果，令我沦陷於情愁而欲丧亡。\n\n凤鸟啊凤鸟，回到了家乡，行踪无定，游览天下只为寻求心中的凰鸟。\n未遇凰鸟时啊，不知所往，怎能悟解今日登门后心中所感?\n有位美丽而娴雅贞静的女子在她的居室，居处虽近，这美丽女子却离我很远，思念之情，正残虐着我的心肠。\n如何能够得此良缘，结为夫妇，做那恩爱的交颈鸳鸯，但愿我这凤鸟，能与你这凰鸟一同双飞，天际游翔。\n凰鸟啊凰鸟愿你与我起居相依，形影不离，哺育生子，永远做我的配偶。\n情投意合，两心和睦谐顺。半夜里与我互相追随，又有谁会知晓?\n展开双翼远走高飞，徒然为你感念相思而使我悲伤。▲', poem_appreciation = '卓文君，一个美丽聪明，精诗文，善弹琴的女子。可叹的是十七岁年纪轻轻，便在娘家守寡。某日席间，只因司马相如一曲《凤求凰》，多情而又大胆的表白，让久慕司马相如之才的卓文君，一听倾心，一见钟情。可是他们之间的爱恋受到了父亲的强烈阻挠。卓文君凭着自己对爱情的憧憬，对追求幸福的坚定，以及非凡的勇气，毅然在漆黑之夜，逃出卓府，与深爱的人私奔。当垆卖酒为生。生活艰难，但两人感情日深。这也是一直流传至今的爱情故事里最浪漫的夜奔之佳话。\n\n　　自古至今，大多数男人总是令人失望。司马相如自然也不例外。当他在事业上略显锋芒，终于被举荐做官后，久居京城，赏尽风尘美女，加上官场得意，竟然产生了弃妻纳妾之意。曾经患难与共，情深意笃的日子此刻早己忘却。哪里还记得千里之外还有一位日夜倍思丈夫的妻子。文君独守空房，日复一日年复一年地过着寂寞的生活。一首《白头吟》 ，“……闻君有二意，故来相决绝。愿得一人心，终老不相负。……”表达了她对爱情的执着和向往以及一个女子独特的坚定和坚韧。也为她们的故事增添了几分美丽的哀伤。\n\n　　终于某日，司马相如给妻子送出了一封十三字的信：一二三四五六七八九十百千万。聪明的卓文君读后，泪流满面。一行数字中唯独少了一个“亿”，无亿岂不是表示夫君对自己“无意”的暗示？她，心凉如水。怀着十分悲痛的心情，回了一封《怨郎诗》。\n\n　　其诗曰：一别之后，二地相悬。虽说是三四月，谁又知五六年。七弦琴无心弹，八行书无可传，九连环从中折断，十里长亭望眼欲穿。百思想，千系念，万般无奈把郎怨。\n\n　　(万语千言说不完，百无聊赖十倚栏。重九登高看孤雁，八月中秋月圆人不圆。七月半，秉烛烧香问苍天，六月伏天人人摇扇我心寒。五月榴花红似火，偏遇阵阵冷雨浇花端。四月枇杷黄，我欲对镜心意乱。三月桃花飘零随水转，二月风筝线儿断。噫，郎呀郎，巴不得下一世，你为女来我做男。)\n\n　　(此段疑为不是卓文君所作，“百无聊赖”一段在卓文君死后数百年才出现，且当时转世这一说法并未流入中原)\n\n　　司马相如看完妻子的信，不禁惊叹妻子之才华横溢。遥想昔日夫妻恩爱之情，羞愧万分，从此不再提遗妻纳妾之事。这首诗也便成了卓文君一生的代表作数字诗。细细品读，其爱恨交织之情跃然纸上。\n\n　　卓文君用自己的智慧挽回了丈夫的背弃。她用心经营着自己的爱情和婚姻，终于苦尽甘来。他们之间最终没有背弃最初的爱恋和最后的坚守。这也使得他们的故事千转百回，成为世俗之上的爱情佳话。\n\n　　这首《凤求凰》表达了司马相如对卓文君的无限倾慕和热烈追求。相如自喻为凤，比文君为皇（凰），在本诗的特定背景中具有特殊的含义。全诗言浅意深，音节流畅明亮，感情热烈奔放而又深挚缠绵，融合了楚辞骚体的旖旎绵邈和汉代民歌的清新明快于一炉，为后人所不能逾越。后来的人根据二人的爱情故事，谱成了经久不衰的琴谱“凤求凰”，千年以来吟唱不已。\n\n　　第一首表达相如对文君的无限倾慕和热烈追求。相如自喻为凤，比文君为皇（凰），在本诗的特定背景中有多重含义。其一凤凰是传说中的神鸟，雄曰凤，雌曰凰。古人称麟、凤、龟、龙为天地间“四灵”，（《礼记·礼运》）凤凰则为鸟中之王。《大戴礼·易本名》云：“有羽之虫三百六十而凤凰为之长。”长卿自幼慕蔺相如之为人才改名“相如”，又在当时文坛上已负盛名；文君亦才貌超绝非等闲女流。故此处比为凤凰，正有浩气凌云、自命非凡之意。“遨游四海”更加强了一层寓意，既紧扣凤凰“出于东方君子之国，翱翔四海之外，过昆仑，饮砥柱，羽弱水，莫（暮）宿风穴”（郭璞注《尔雅》引天老云）的神话传说，又隐喻相如的宦游经历：此前他曾游京师，被景帝任为武骑常侍，因景帝不好辞赋，相如志不获展，因借病辞官客游天梁。梁孝王广纳文士，相如在其门下“与诸生游士居数岁”。后因梁王卒，这才反“归故乡”。足见其“良禽择木而栖。”其二，古人常以“凤凰于飞”、“鸾凤和鸣”喻夫妻和谐美好。如《左传·庄公廿二年》：“初，懿氏卜妻敬仲。其妻占之曰：吉，是谓凤凰于飞，和鸣铿锵。”此处则以凤求凰喻相如向文君求爱，而“遨游四海”，则意味着佳偶之难得。其三，凤凰又与音乐相关。如《尚书·益稷》：“箫韶九成，凤凰来仪。”又《列仙传》载：秦穆公女弄玉与其夫萧史吹箫，凤凰皆来止其屋，穆公为作凤台，后弄玉夫妇皆乘凤而去。故李贺尝以“昆山玉碎凤凰叫”（《李凭箜篌引》）比音乐之美。文君雅好音乐，相如以琴声“求其凰”，正喻以琴心求知音之意，使人想起俞伯牙与钟子期“高山流水”的音乐交浪，从而发出芸芸人海，知音难觅之叹。\n\n　　第二首写得更为大胆炽烈，暗约文君半夜幽会，并一起私奔。“孳尾”，指鸟兽雌雄交媾。《尚书·尧典》：“厥民析，鸟兽孳尾。”《传》云：“乳化曰孳，交接曰尾。”“妃”，配偶。《说文》：“妃，匹也。”“交情通意”，交流沟通情意，即情投意合。“中夜”，即半夜。前两句呼唤文君前来幽媾结合，三四句暗示彼此情投意合连夜私奔，不会有人知道；五六句表明远走高飞，叮咛对方不要使我失望，徒然为你感念相思而悲伤。盖相如既已事前买通文君婢女暗通殷勤，对文君寡居心理状态和爱情理想亦早有了解，而今复以琴心挑之，故敢大胆无忌如此。\n\n　　这两首琴歌之所以赢得后人津津乐道，首先在于“凤求凰”表现了强烈的反封建思想。相如文君大胆冲破了封建礼教的罗网和封建家长制的樊篱，什么“不待父母之命，媒妁之言，钻穴隙相窥，逾墙相从，则父母国人皆贱之。”（《孟子·滕文公下》）什么“妇人有三从之义，无专用之道。”（《仪礼·丧服》）什么“夫有再娶之义，妇无二适之文。”（班昭《女诫》）什么“男女……无币不相见，”（《礼记·坊记》）“门当户对”等等神圣礼法，统统被相如文君的大胆私奔行动崐踩在脚下，成为后代男女青年争取婚姻自主、恋爱自由的一面旗帜。试看榜样的力量在后代文学中的影响吧：《西厢记》中张生亦隔墙弹唱《凤求凰》，说：“昔日司马相如得此曲成事，我虽不及相如，愿小姐有文君之意。”《墙头马上》中李千金，在公公面前更以文君私奔相如为自己私奔辩护；《玉簪记》中潘必正亦以琴心挑动陈妙常私下结合；《琴心记》更是直接把相如文君故事搬上舞台……足见《凤求凰》反封建之影响深远。\n\n　　其次，在艺术上，这两首琴歌，以“凤求凰”为通体比兴，不仅包含了热烈的求偶，而且也象征着男女主人公理想的非凡，旨趣的高尚，知音的默契等丰富的意蕴。全诗言浅意深，音节流亮，感情热烈奔放而又深挚缠绵，融楚辞骚体的旖旎绵邈和汉代民歌的清新明快于一炉。即使是后人伪托之作，亦并不因此而减弱其艺术价值。', poem_tags = '思念,爱情' WHERE poem_title = '凤求凰' AND poem_author = '司马相如';
UPDATE edu_poem SET poem_translation = '一轮明月从祁连山升起，穿行在苍茫云海之间。\n浩荡的长风吹越几万里，吹过将士驻守的玉门关。\n当年汉兵直指白登山道，吐蕃觊觎青海大片河山。\n这里就是历代征战之地，出征将士很少能够生还。\n戍守兵士远望边城景象，思归家乡不禁满面愁容。\n此时将士的妻子在高楼，哀叹何时能见远方亲人。', poem_notes = '关山月：乐府旧题，属横吹曲辞，多抒离别哀伤之情。\n天山：即祁连山。在今甘肃、新疆之间，连绵数干里。因汉时匈奴称”天“为”祁连“，所以祁连山也叫做天山。\n玉门关：故址在今甘肃敦煌西北，古代通向西域的交通要道。此二句谓秋风自西方吹来，吹过玉门关。\n下：指出兵。白登：今山西大同东有白登山。汉高祖刘邦领兵征匈奴，曾被匈奴在白登山围困了七天。胡：此指吐蕃。窥：有所企图，窥伺，侵扰。青海湾：即今青海省青海湖，湖因青色而得名。\n由来：自始以来；历来。戍客：征人也。驻守边疆的战士。边色：一作“边邑”。\n高楼：古诗中多以高楼指闺阁，这里指戍边兵士的妻子。', poem_appreciation = '这首诗描绘了边塞的风光，戍卒的遭遇，更深一层转入戍卒与思妇两地相思的痛苦。开头的描绘都是为后面作渲染和铺垫，而侧重写望月引起的情思。\n\n　　开头四句，可以说是一幅包含着关、山、月三种因素在内的辽阔的边塞图景。在一般文学作品里，常见“月出东海”或“月出东山”一类描写，而天山在中国西部，似乎应该是月落的地方，何以说“明月出天山”呢？原来这是就征人角度说的。征人戍守在天山之西，回首东望，所看到的是明月从天山升起的景象。天山虽然不靠海，但横亘在山上的云海则是有的。诗人把似乎是在人们印象中只有大海上空才更常见的云月苍茫的景象，与雄浑磅礴的天山组合到一起，显得新鲜而壮观。这样的境界，在一般才力薄弱的诗人面前，也许难乎为继，但李白有的是笔力。接下去“长风几万里，吹度玉门关”，范围比前两句更为广阔。宋代的杨齐贤，好像唯恐“几万里”出问题，说是：“天山至玉门关不为太远，而曰几万里者，以月如出于天山耳，非以天山为度也。”用想象中的明月与玉门关的距离来解释“几万里”，看起来似乎稳妥了，但李白是讲“长风”之长，并未说到明月与地球的距离。其实，这两句仍然是从征戍者角度而言的，士卒们身在西北边疆，月光下伫立遥望故园时，但觉长风浩浩，似掠过几万里中原国土，横度玉门关而来。如果联系李白《子夜吴歌》中“秋风吹不尽，总是玉关情”来进行理解，诗的意蕴就更清楚了。这样，连同上面的描写，便以长风、明月、天山、玉门关为特征，构成一幅万里边塞图。这里表面上似乎只是写了自然景象，但只要设身处地体会这是征人东望所见，那种怀念乡土的情绪就很容易感觉到了。\n\n　　“汉下白登道，胡窥青海湾。由来征战地，不见有人还。”这是在前四句广阔的边塞自然图景上，迭印出征战的景象。汉高祖刘邦曾被匈奴在白登山围困了七天。而青海湾一带，则是唐军与吐蕃连年征战之地。这种历代无休止的战争，使得从来出征的战士，几乎见不到有人生还故乡。这四句在结构上起着承上启下的作用，描写的对象由边塞过渡到战争，由战争过渡到征戍者。\n\n　　“戍客望边邑，思归多苦颜。高楼当此夜，叹息未应闲。”战士们望着边地的景象，思念家乡，脸上多现出愁苦的颜色，他们推想自家高楼上的妻子，在此苍茫月夜，叹息之声当是不会停止的。“望边色”三个字在李白笔下似乎只是漫不经心地写出，但却把以上那幅万里边塞图和征战的景象，跟“戍客”紧紧连系起来了。所见的景象如此，所思亦自是广阔而渺远。战士们想象中的高楼思妇的情思和他们的叹息，在那样一个广阔背景的衬托下，也就显得格外深沉了。\n\n　　诗人放眼于古来边塞上的漫无休止的民族冲突，揭示了战争所造成的巨大牺牲和给无数征人及其家属所带来的痛苦，但对战争并没有作单纯的谴责或歌颂，诗人像是沉思着一代代人为它所支付的沉重代价。在这样的矛盾面前，诗人，征人，乃至读者，很容易激起一种渴望。这种渴望，诗中没有直接说出，但类似“乃知兵者是凶器，圣人不得已而用之”（《战城南》）的想法，是读者在读这篇作品时很容易产生的。\n\n　　离人思妇之情，在一般诗人笔下，往往写得纤弱和过于愁苦，与之相应，境界也往往狭窄。但李白却用“明月出天山，苍茫云海间。长风几万里，吹度玉门关”的万里边塞图景来引发这种感情。这只有胸襟如李白这样浩渺的人，才会如此下笔。这几句并不是局促于一时一事，而是带着一种更为广远、沉静的思索。用广阔的空间和时间做背景，并在这样的思索中，把眼前的思乡离别之情融合进去，从而展开更深远的意境，这是其他一些诗人所难以企及的。', poem_tags = '唐诗三百首,写山,边塞,征人,思乡' WHERE poem_title = '关山月' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '当年在岐王宅里，常常见到你的演出；在崔九堂前，也曾多次欣赏你的艺术。\n没有想到，在这风景一派大好的江南；正是落花时节，能巧遇你这位老相熟。', poem_notes = '李龟年：唐朝开元、天宝年间的著名乐师，擅长唱歌。因为受到皇帝唐玄宗的宠幸而红极一时。“安史之乱”后，李龟年流落江南，卖艺为生。\n岐王：唐玄宗李隆基的弟弟，名叫李范，以好学爱才著称，雅善音律。\n寻常：经常。\n崔九：崔涤，在兄弟中排行第九，中书令崔湜的弟弟。玄宗时，曾任殿中监，出入禁中，得玄宗宠幸。崔姓，是当时一家大姓，以此表明李龟年原来受赏识。\n江南：这里指今湖南省一带。\n落花时节：暮春，通常指阴历三月。落花的寓意很多，人衰老飘零，社会的凋弊丧乱都在其中。\n君：指李龟年。', poem_appreciation = '诗是感伤世态炎凉的。李龟年是唐玄宗初年的著名歌手，常在贵族豪门歌唱。杜甫少年时才华卓著，常出入于岐王李隆范和中书监崔涤的门庭，得以欣赏李龟年的歌唱艺术。诗的开首二句是追忆昔日与李龟年的接触，寄寓诗人对开元初年鼎盛的眷怀；后两句是对国事凋零，艺人颠沛流离的感慨。仅仅四句却概括了整个开元时期（注：开元时期为713年—741年）的时代沧桑，人生巨变。语极平淡，内涵却无限丰满。\n\n　　李龟年是开元时期“特承顾遇”的著名歌唱家。杜甫初逢李龟年，是在“开口咏凤凰”的少年时期，正值所谓“开元全盛日”。当时王公贵族普遍爱好文艺，杜甫即因才华早著而受到岐王李隆范和中书监崔涤的延接，得以在他们的府邸欣赏李龟年的歌唱。而一位杰出的艺术家，既是特定时代的产物，也往往是特定时代的标志和象征。在杜甫心目中，李龟年正是和鼎盛的开元时代、也和他自己充满浪漫情调的青少年时期的生活，紧紧联结在一起的。几十年之后，他们又在江南重逢。这时，遭受了八年动乱的唐王朝业已从繁荣昌盛的顶峰跌落下来，陷入重重矛盾之中；杜甫辗转漂泊到潭州，“疏布缠枯骨，奔走苦不暖”，晚境极为凄凉；李龟年也流落江南，“每逢良辰胜景，为人歌数阕，座中闻之，莫不掩泣罢酒”（《明皇杂录》）。这种会见，自然很容易触发杜甫胸中原本就郁积着的无限沧桑之感。\n\n　　“岐王宅里寻常见，崔九堂前几度闻。”诗人虽然是在追忆往昔与李龟年的接触，流露的却是对“开元全盛日”的深情怀念。这两句下语似乎很轻，含蕴的感情却深沉而凝重。“岐王宅里”、“崔九堂前”，仿佛信口道出，但在当事者心目中，这两个文艺名流经常雅集之处，是鼎盛的开元时期丰富多彩的精神文化的集中的地方，它们的名字就足以勾起诗人对“全盛日”的美好回忆。当年诗人出入其间，接触李龟年这样的艺术明星，是“寻常”而不难“几度”的，多年过后回想起来，简直是不可企及的梦境了。这里所蕴含的天上人间之隔的感慨，读者是要结合下两句才能品味出来的。两句诗在迭唱和咏叹中，流露了诗人对开元全盛日的无限眷恋，犹如要拉长回味的时间。\n\n　　梦一样的回忆，毕竟改变不了眼前的现实。“正是江南好风景，落花时节又逢君。”风景秀丽的江南，在承平时代，原是诗人们所向往的作快意之游的所在。诗人真正置身其间，所面对的竟是满眼凋零的“落花时节”和皤然白首的流落艺人。“落花时节”，如同是即景书事，又如同是别有寓托，寄兴在有意无意之间。这四个字，暗喻了世运的衰颓、社会的动乱和诗人的衰病漂泊，但诗人丝毫没有在刻意设喻，这种写法显得特别浑成无迹。加上两句当中“正是”和“又”这两个虚词一转一跌，更在字里行间寓藏着无限感慨。江南好风景，恰恰成了乱离时世和沉沦身世的有力反衬。一位老歌唱家与一位老诗人在飘流颠沛中重逢了，落花流水的风光，点缀着两位形容憔悴的老人，成了时代沧桑的一幅典型画图。它无情地证实“开元全盛日”已经成为历史陈迹，一场翻天覆地的大动乱，使杜甫和李龟年这些经历过盛世的人，沦落到了不幸的地步。感慨是很深的，但诗人写到“落花时节又逢君”，却黯然而收，在无言中包孕着深沉的慨叹，痛定思痛的悲哀。这样“刚开头却又煞了尾”，连一句也不愿多说，显得蕴藉之极。清代沈德潜评此诗：“含意未申，有案未断。”诗人这种“未申”之意对于有着类似经历的当事者李龟年，是不难领会的；对于后世善于知人论世的读者，也不难把握。像《长生殿·弹词》中李龟年所唱的“当时天上清歌，今日沿街鼓板”，“唱不尽兴亡梦幻，弹不尽悲伤感叹，凄凉满眼对江山”等等，尽管反复唱叹，意思并不比杜诗更多，倒很像是剧作家从杜甫的诗中抽绎出来的一样。\n\n　　四句诗，从岐王宅里、崔九堂前的“闻”歌，到落花江南的重“逢”，“闻”、“逢”之间，联结着四十年的时代沧桑、人生巨变。尽管诗中没有一笔正面涉及时世身世，但透过诗人的追忆感喟，却表现出了给唐代社会物质财富和文化繁荣带来浩劫的那场大动乱的阴影，以及它给人们造成的巨大灾难和心灵创伤。可以说“世运之治乱，华年之盛衰，彼此之凄凉流落，俱在其中”（孙洙评）。正如同旧戏舞台上不用布景，观众通过演员的歌唱表演，可以想象出极广阔的空间背景和事件过程；又像小说里往往通过一个人的命运，反映一个时代一样。这首诗的成功创作表明：在具有高度艺术概括力和丰富生活体验的大诗人那里，绝句这样短小的体裁可以具有很大的容量，而在表现如此丰富的内容时，又能达到举重若轻、浑然无迹的艺术境界。', poem_tags = '唐诗三百首,初中古诗,感伤,怀念' WHERE poem_title = '江南逢李龟年' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '以前的日子就听说洞庭湖波澜壮阔，今日如愿终于登上岳阳楼。\n浩瀚的湖水把吴楚两地撕裂，似乎日月星辰都漂浮在水中。\n亲朋好友们音信全无，我年老多病，乘孤舟四处漂流。\n北方边关战事又起，我倚着栏杆远望泪流满面。', poem_notes = '洞庭水：即洞庭湖。在今湖南北部，长江南岸，是我国第二大淡水湖。\n岳阳楼：在今湖南省岳阳市，下临洞庭湖，为游览胜地。\n吴楚：春秋时二国名（吴国和楚国）其地略在今湖南、湖北、江西、安徽、江苏、浙江一带。下瞰洞庭，碧湖万顷，遥望君山，气象万千，唐张说建，宋滕子京修。以范仲淹千古名篇《岳阳楼记》驰名。 坼（chè）：分裂，这里引申为划分。这句是说：辽阔的吴楚两地被洞庭湖一水分割。\n乾坤（qián kūn）日夜（一作“月”）浮：日月星辰和大地昼夜都飘浮在洞庭湖上。据《水经注》卷三十八：“湖水广圆五百余里，日月出没于其中。”乾坤：天地，此指日月。\n无一字：杳无音讯。 字：这里指书信。\n老病：年老多病。杜甫时年五十七岁，身患肺病，风痹，右耳已聋。有孤舟：唯有孤舟一叶飘零无定。诗人生平的最后三年里大部分时间是在船上度过的。这句写的是杜甫生活的实况。\n戎（róng）马关山北：北方边关战事又起。当时吐蕃侵扰宁夏灵武、陕西邠（bīn）州一带，朝廷震动，匆忙调兵抗敌。戎马：军马借指军事、战争，战乱。这年秋冬，吐蕃又侵扰陇右、关中一带。\n凭轩：倚着楼窗。涕泗流：眼泪禁不住地流淌。涕泗：眼泪和鼻涕，偏义复指，即眼泪。', poem_appreciation = '首联“昔闻洞庭水，今上岳阳楼”。有一点是很清楚的，诗人对洞庭湖向往已久，这是在叙事写景的行文中，自然地流露出来的感情。但这毕竟是过去的向往，登上了岳阳楼，其感情似乎应当是高兴。因为多年的向往实现了，一定高兴。但仔细品味，句中又见不到高兴的字眼，抽不出如愿以偿的情思。联系下文更是如此。实际上在这两句中“昔”与“今”之间，是一段漫长的时间距离，作者把这段距离拉开，没有用简单的“喜”“悲”之词来填充它，而是留给读者去想象、回味。古人说“律诗之妙全在无字处”，这里就是无字处。“昔”与“今”之间，天在变，地在变，国在变，人也在变。安史之乱，唐王朝由盛转衰，人民的深重灾难，杜甫个人的悲惨遭遇，这一切都凝聚在一起，凝聚在杜甫的心头，并随着诗人—起登上了岳阳楼。他高兴不起来。应当说“今上岳阳楼”是向往了多年不得登，如今才算是登上来了，这是一声长叹，长叹的内里是一团忧国忧民、伤时伤世的感慨。这一声长叹，就像那咏叹调的引子，开启了下面一个个乐章。这里还要注意到一个“水”字，题目是“登岳阳楼”，头一句却先写洞庭湖，第二句才写岳阳楼，而且是“洞庭水”不是洞庭湖。这个“水”字显然是要突出的，这是抓住了洞庭风光的主要特点，说明了下文主要是在“水”上做文章。\n\n　　颔联“吴楚东南坼，乾坤日夜浮”。这两句紧扣上联的“水”字，虽没出现水字，却是专门写洞庭水。诗人站在岳阳楼上，向东南方向极目眺望，只见洞庭湖水茫茫一片，一眼望不到头，而吴地则被挤向了远远的东边，楚地则被远远地挤向了西边、南边。这景象，就好像洞庭湖水向东南伸展，把本来连在一起的吴地和楚地，一下子分裂成为两块。“坼”字用的很好，有动态感。仿佛湖水在延伸，大地被切割开。后一句“乾坤”就是天地，包括天地万物。“乾坤日夜浮”是说诗人站在岳阳楼上，四面眺望，到处都是无边无际的洞庭水，仿佛整个天地万物都被湖水漂浮起来，仿佛天地万物都日日夜夜地在洞庭湖水上浮动漂游。“浮”字也有动态感。使人想到整个苍穹都被湖水托住的—个半球，而万物的运动，都是湖水荡动的结果。这两句都是写洞庭水，境界宏阔。一是极写水面的宽阔，二是极写水的力量。能够割裂大地，能够浮动乾坤，这是极写它的力量。而被割裂、被浮动东西之庞大，则显示出湖水的宽阔。这不是简单的夸张手法，这里有个视觉、感觉和想象的问题。由于地球是圆的，人的视觉是有限的，面对茫茫的湖水可能看不到岸边，即使看到了，远远望去也只是一条线，这就造成了湖水无限大，而远地十分狭小的感觉。诗人准确、真实地抓住了这视觉和感觉上的错觉，就把湖水描写成了四际无垠，仿佛大地四处都是水乡泽国，这是视觉感觉的真实。但诗人又借助想象，把本来看不到的吴楚大地和整个乾坤四际，也融进了这个视觉和感觉的画面。从而构成了一个想象的吴地楚地被裂开，整个乾坤被浮动的广阔无垠的画面。这就是借助想象而形成的意象。这是将想象中的更广阔的景象纳进了视觉画面的结果。这是说“吴楚东南坼，乾坤日夜浮”是视觉错觉加上想象的产物，这是一个很成功的宏观意象。它的主要特点是境界广阔、气魄宏大。像这样大的宏观意象、气魄在中国古代诗歌中是很少见的。如孟浩然也有咏叹洞庭湖的诗句“气蒸云梦泽，波撼岳阳城”，但没有杜诗境界更为高远。这两句是写景，但不能看成是纯写景，写景中渗透着诗人的胸怀。“吴楚东南坼，乾坤日夜浮”透露唐王朝的分裂衰败和国势的不安定。\n\n　　颈联“亲朋无一字，老病有孤舟”这两句是写诗人自己的处境。“无一字”指的是没有一点消息，一点音信。“亲朋无一字”写出了诗人的孤苦，但主要是音信断绝，自己不了解朝里和地方上的情况，即整个国家的情况。这对一个念念不忘君王，不忘国家，不忘人民的诗人来说，是一种被社会忘记的孤独感，他在精神上无疑是很痛苦的。“孤舟”是指诗人全家挤在一条小船上飘泊度日，消息断绝，年老多病，孤舟漂泊，其精神上、生活上的惨苦可以想见。理解这两句应与前两句联系起来看，前两句是远望，随着湖水向四际望去，水天相接，联想到吴楚，联想到整个乾坤。这两句近看，看到了孤舟，孤舟是近景中映入眼帘最能触动他的东西。于是使他联想到自己的身世、遭遇和处境。可以说这两联都是由观景引出，只不过前两句以写观景所见为主，后两句以写观望所见而引起的联想为主。这两联在内涵上也是一脉相通的。表面看起来毫无联系，实际上是一脉相通的。既然这后两句是写他的孤苦悲惨处境，由此应推想到前两句也绝非是单单写景，实际上前两句是借写远景象征性地、比拟性地暗示国势的动荡不安。这里包含着安史之乱的后遗症：唐王朝的衰败，人民的痛苦，外族的侵扰，国家的四分五裂和社会的不安定，栋梁之臣的缺乏等等，这一切都是杜甫飘泊中念念不忘的大事。正是由于诗人心中牵挂着国事民事，才牵肠挂肚。所以当他看到广阔无垠洞庭湖水时，也会想到仿佛大地裂开了，乾坤在日夜不停地浮动。从杜甫一贯的优国忧民的思想境界来看，他登上岳阳楼极目远眺，也必定会想到这些。可以说没想到这些就不是杜甫。也正是由于诗人胸中翻腾着叫人牵肠挂肚的国事民事，所以就很自然地勾起了自己不能再施展抱负的痛心。于是这孤舟飘泊，老弱多病，消息也听不到的可悲处境，也就顺理成章地涌上心头。这两联中，上联境界极大，下联境界却很小，大小相映成趣，其间也包孕着诗人的无限感慨。就景象来说，上联展现的是浩瀚的洞庭湖水，下联则画出了水面上的一点孤舟。湖水动荡，孤舟飘浮，虽然大小悬殊，却统一在一幅画中。如果将洞庭湖水比作整个国家，那么那一点孤舟就是诗人杜甫自己。这里是象征，这鲜明对照的谐调之中，既包含着诗人对自己终身遭遇的痛心和不平，也体现了诗人将自己的命运、国家的命运紧紧地联系在一起。诗人站在岳阳楼上，望望湖水，看看孤舟，想到国家，想到自己，万种感慨，萦绕心头。“不阔则狭处不苦，能狭则阔境愈空”，“乾坤”与“孤舟”对比，阔大者更为浩渺，狭小者更显落寞。\n\n　　尾联“戎马关山北。”“戎马”，就是战马、兵马，指战争。“关山”，泛指，并非专指那道关，那座山。“关山北”，指打仗的地方。从诗人来说，从洞庭湖向长安望去，隔着一道道关，一座座山，而战火就在北面燃烧。“戎马关山北”，具体指的是当时吐蕃入侵，威胁长安，战争不息，国家不得安宁。“凭轩涕泗流”是说杜甫倚靠岳阳楼的窗户，向北眺望，虽然隔着道道关山，他看不到长安，也看不到战火，但在他心中却呈现出吐蕃入侵，长安危急，人民遭难的情景，于是他就禁不住伤心的老泪纵横了。这两句是两个景象：一个是西北长安附近的战火，一个是岳阳楼上倚窗眺望的老诗人。两者构成了一幅画，前者是诗人心中想到的，后者是诗人自身实景。长安与岳阳楼相距千里，但在诗人心中却没有这个距离。这真是身在洞庭，心在长安。孤舟虽小却装着整个天下。衰老多病的躯体中，仍然跳动着—颗忧国忧民的志诚之心。同时“戎马关山北”一句，明确写出了诗人在登岳阳楼时心中想的是国家的不安宁。这就更可以说明了第二联绝非仅仅是写景。第三联也决不只是写自己的孤苦无依。“凭轩涕泗流” 一句中，则凝聚着诗人对国家时局、自己孤苦处境比照后，感到无可奈何，感到万分压抑的感情，非常形象而深刻地显示出杜甫晚年时的精神痛苦。精神痛苦主要是无可奈何。\n\n　　这首诗的主要艺术成就表现为以下两点。\n\n　　第一，作品运用了变化多样的表现手法。作品虽然只有八句话，但是却运用了多种表现手法。开篇两句运用的是叙述的手法，交代的是登临岳阳楼的缘由。三四两句运用的是描绘的手法，绘制了岳阳楼的宏阔壮观图景，并且在描绘中，又运用了形象的比喻，增强了作品的生动性。作品最后两句又运用了抒情的写法，揭示出诗人的内心世界，开拓了作品的意境。\n\n　　第二，作品内容和感情两方面大跨度的跳跃。从内容方面说，开篇一联写的是诗人登楼的过程，其中蕴含了“昔”与“今”的时间跳跃过程。颔联中，诗人由上联的写自己推进到写洞庭湖，这里有一个从小到大的跨度。在写景中，又由吴、楚之地面到日、月之天空的空间跳跃。到了颈联，诗人又转回自身的描写，前后联之间有一个从大到小的跨越。到了尾联，诗人又从个人身世遭际的描写扩展到国事的描写，上下联又是一个从小到大的跨越。在写国事时，又有一个从国难的跳跃到诗人感情抒发的过程。这就构成了纵横开阔，跳跃性强的特点。从诗人的感情发展脉络上说，首联蕴含喜悦，颔联带有雄壮，颈联转为凄苦，尾联变为悲伤。诗人的感情随着诗篇的进展，显示出不断变化，跳跃性强的艺术特点。', poem_tags = '唐诗三百首,山水,抱负' WHERE poem_title = '登岳阳楼' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '懒得摇动白羽扇来祛暑，裸着身子呆在青翠的树林中。\n脱下头巾挂在石壁上，任由松树间的凉风吹过头顶。', poem_notes = '裸袒（tǎn）：指诗人在青林里脱去头巾，不拘礼法的形态。青林：指山中树木苍翠、遮天蔽日。\n脱巾：摘下帽子。\n露顶：露出头顶。松风：松树间吹过的凉风。', poem_tags = '夏天,写山' WHERE poem_title = '夏日山中' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '只有狂雷炸响般的巨大力量才能使中国大地发出勃勃生机，然而社会政局毫无生气终究是一种悲哀。\n我奉劝上天要重新振作精神，不要拘泥一定规格以降下更多的人才。', poem_notes = '九州：中国的别称之一。分别是：冀州、兖州、青州、徐州、扬州、荆州、梁州、雍州和豫州。王昌龄《放歌行》：“清乐动千门，皇风被九州”。生气：生气勃勃的局面。恃（shì）：依靠。\n万马齐喑：比喻社会政局毫无生气。喑（yīn），沉默，不说话。\n天公：造物主。抖擞：振作，奋发。\n降：降生，降临。', poem_appreciation = '在这首诗中，诗人对死气沉沉、缺乏生机的社会现状，深表痛心，急切地希望巨大的社会变革迅速到来。\n\n　　“九州生气恃风雷，万马齐喑究可哀”：这两句以比喻修辞格，表明只有依靠一场急风惊雷，才能打破在清朝统治下，到处呈现着的为时已久的一片死气沉沉的局面。“风雷”，比喻革命风暴。鲁迅先生“于无声处听惊雷”（《无题》）中“惊霄”、毛泽东“一从大地起风雷”（《七律·和郭沫若同志》）中“风雷”，都是这个意思。“风雷”之上冠以“恃”字，表明挽救危亡，振兴国家，急风惊雷而外，别无他途，足以见出诗人的敏锐眼光和斗争梢神。“万马齐喑”，比喻在清朝统治下，人们不敢讲话，到处是一种令人窒息的沉闷气氛。这里用了一个典故。苏轼《三马图赞引》：“时（宋元祐初）西域贡马，首高八尺，龙颅而风骨，虎背而豹章，出东华门，入天驷监，振鬣长鸣，万马齐喑。”对于“万马齐喑”的局面，用一“哀”字，表明诗人痛惜之情与爱国之心。诗人于1810年到北京做官，满怀经世之志、治国之略，但是仕途的失意。政治主张的破灭，使他清醒地认识到他处在“平生进退两颠簸”（《十月廿夜大风不寐起而书怀》）的境遇中。像诗人这样先进的思想家、政治家，面对此情此境，必会痛心疾首。\n\n　　“我功天公重抖擞，不拘一格降人才”两句，运用移花接木的手法，表现了诗人渴望砸烂黑暗统治，出现一个崭新世界的愿望。“天公”，即玉皇，亦即世俗所谓老天爷。诗人揭露时弊，忽然就劝起老天爷来了，诗末自注云：“过镇江，见赛玉皇及风神、雷神者，祷祠数万，道士乞撰青词。”这个自注说明了诗人写这首诗的具体环境，看出了诗人是借“道士乞撰青词”之机，用民间迷信活动来为自己所要表达的思想感情服务。“不拘一格”，充分表现了诗人开阔的胸怀，远大的目光，具有战略性的设想。当时的清政府，腐朽无能，内忧外患，特别是帝国主义侵略者，虎视耽耽，奴役中国民族、灭亡中国国家之心不死，瓜分风潮，迫在眉睫，要拯救暴风中破船似的中国，非有各方面的大批人才，是无济午事的，所以诗人劝天公重新振作精神，不拘一格而降大批人才，共挽即倒的狂澜，将倾的大厦。“劝”字，颇具积极意义。它是奉劝，而不是乞求，表现了诗人处于踞离临下的地位，也显示出诗人变革的信心。\n\n　　整首诗中选用“九州”、“风雷”、“万马”、“天公”这样的具有壮伟特征的主观意象，是诗人用奇特的想象表现了他热烈的希望，他期待着杰出人才的涌现，期待着改革大势形成新的“风雷”、新的生机，一扫笼罩九州的沉闷和迟滞的局面，既揭露矛盾、批判现实，更憧憬未来、充满理想。它独辟奇境，别开生面，呼唤着变革，呼唤未来。寓意深刻，气势不凡。\n\n　　全诗以一种热情洋溢的战斗姿态，对清朝当政者以讽荐，表达了作者心中对国家未来命途的关切，和希望当政者能够广纳人才的渴望，具有很深刻的历史背景和很强的现实意义。', poem_tags = '古诗三百首,小学古诗,励志,早教古诗100首' WHERE poem_title = '己亥杂诗·其二百二十' AND poem_author = '龚自珍';
UPDATE edu_poem SET poem_translation = '孔子说：“学了（知识）然后按一定的时间复习它，不也是很愉快吗？有志同道合的人从远方来，不也是很快乐吗？人家不了解我，我却不恼怒，不也是道德上有修养的人吗？”\n\n曾子说：“我每天多次反省自己：替别人办事是不是尽心竭力了呢？同朋友交往是不是诚实可信了呢？老师传授的知识是不是复习了呢？”\n\n孔子说：“我十五岁开始有志于做学问，三十岁能独立做事情，四十岁（遇事）能不迷惑，五十岁知道哪些是不能为人力所支配的事情，六十岁能听得进不同的意见，到七十岁才做事才能随心所欲，不会超过规矩。”\n\n孔子说：“温习学过的知识，可以从中获得新的理解与体会，那么就可以凭借这一点去做老师了。”\n\n孔子说：“只学习却不思考，就会迷惑;只空想却不学习，就会疑惑。”\n\n孔子说：“颜回的品质是多么高尚啊！一竹篮饭，一瓢水，住在简陋的小巷子里，别人都忍受不了这种穷困清苦，颜回却没有改变他好学的乐趣。颜回的品质是多么高尚啊！”\n\n孔子说：“知道学习的人比不上爱好学习的人；爱好学习的人比不上以学习为乐趣的人。”\n\n孔子说：“我整天吃粗粮，喝冷水，弯着胳膊做枕头，也自得其乐。用不正当的手段得来的富贵，我把它看作天上的浮云。”\n\n孔子说：“多个人同行，其中必定有人可以做我的老师。我选择他好的方面向他学习，看到他不善的方面就对照自己改正自己的缺点。”\n\n孔子在河边感叹道：“时光像流水一样消逝， 日夜不停。”\n\n孔子说：“军队的主帅可以改变，普通人的志气却不可改变。”\n\n子夏说：“博览群书广泛学习，而且能坚守自己的志向，恳切地提问，多考虑当前的事，仁德就在其中了。”', poem_notes = '子：先生，指孔子。\n时习：按一定的时间复习。\n{不亦说乎}乎：语气词。\n说：通“悦”，愉快。\n愠：生气，发怒。\n君子：这里指道德上有修养的人。\n吾:人称代词，我。\n日：每天。\n立：站立，站得住。\n惑：迷惑，疑惑。\n罔：迷惑，意思是感到迷茫而无所适从', poem_tags = '初中文言文,学习,哲理' WHERE poem_title = '论语十二章' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '诸葛亮亲自在田地中耕种，喜爱吟唱《梁父吟》，他身高八尺，常常把自己和管仲、乐毅相比，当时人们都不承认这件事。只有博陵的崔州平，颍川（河南禹州）的徐庶与诸葛亮关系甚好，说确实是这样。\n\n　　适逢先帝刘备驻扎在新野。徐庶拜见刘备，刘备很器重他，徐庶对刘备说：“诸葛孔明这个人，是人间卧伏着的龙啊，将军可愿意见他？”刘备说：“您和他一起来吧。”徐庶说：“这个人只能你去他那里拜访，不可以委屈他，召他上门来，将军你应该屈尊亲自去拜访他”。\n\n　　因此先帝就去隆中拜访诸葛亮，总共去了三次，才见到诸葛亮。于是刘备叫旁边的人退下，说：“汉室的统治崩溃，奸邪的臣子盗用政令，皇上蒙受风尘遭难出奔。我不能衡量自己的德行能否服人，估计自己的力量能否胜任，想要为天下人伸张大义，然而我才智与谋略短浅，就因此失败，弄到今天这个局面。但是我的志向到现在还没有罢休，您认为该采取怎样的办法呢？”\n\n　　诸葛亮回答道：“自董卓独掌大权以来，各地豪杰同时起兵，占据州、郡的人数不胜数。曹操与袁绍相比，声望少之又少，然而曹操最终之所以能打败袁绍，凭借弱小的力量战胜强大的原因，不仅依靠的是天时好，而且也是人的谋划得当。现在曹操已拥有百万大军，挟持皇帝来号令诸侯，这确实不能与他争强。孙权占据江东，已经历三世了，地势险要，民众归附，又任用了有才能的人，孙权这方面只可以把他作为外援，但是不可谋取他。荆州北靠汉水、沔水，一直到南海的物资都能得到，东面和吴郡、会稽郡相连，西边和巴郡、蜀郡相通，这是大家都要争夺的地方，但是它的主人却没有能力守住它，这大概是天拿它用来资助将军的，将军你可有占领它的意思呢？益州地势险要，有广阔肥沃的土地，自然条件优越，高祖凭借它建立了帝业。刘璋昏庸懦弱，张鲁在北面占据汉中，那里人民殷实富裕，物产丰富，刘璋却不知道爱惜，有才能的人都渴望得到贤明的君主。将军既是皇室的后代，而且声望很高，闻名天下，广泛地罗致英雄，思慕贤才，如饥似渴，如果能占据荆、益两州，守住险要的地方，和西边的各个民族和好，又安抚南边的少数民族，对外联合孙权，对内革新政治；一旦天下形势发生了变化，就派一员上将率领荆州的军队直指中原一带，将军您亲自率领益州的军队从秦川出击，老百姓谁敢不用竹篮盛着饭食，用壶装着酒来欢迎将军您呢？如果真能这样做，那么称霸的事业就可以成功，汉室天下就可以复兴了。”\n\n　　刘备说：“好！”从此与诸葛亮的关系一天天亲密起来。关羽、张飞等人不高兴了，刘备劝解他们说：“我有了孔明，就像鱼得到水一样。希望你们不要再说什么了。”关羽、张飞于是不再说什么了。', poem_notes = '隆中：地名，今襄阳城西13公里古隆中。\n对：回答、应对。\n亮：即诸葛亮（181-234），字孔明，徐州琅琊阳都人。\n躬：亲自。陇亩：田地。\n好（hào）：喜爱。为：唱。\n《梁父（fǔ）吟》：又作《梁甫吟》，古歌曲名。传说诸葛亮曾经写过一首《梁父吟》歌词。\n管仲：名夷吾，春秋时齐桓公的国相，帮助桓公建立霸业。\n乐（yuè）毅：战国时燕昭王的名将，曾率领燕、赵、韩、魏、楚五国兵攻齐，连陷七十余城。\n莫之许：就是“莫许之”。莫，没有人。之，代词，指诸葛亮“自比于管仲、乐毅”。许，承认同意。\n惟：只有。友善：友好，关系好。\n信然：确实这样。\n先主：先，先帝，主，刘备。屯：驻扎。\n新野：现河南省新野县。\n器：器重、重视。\n谓：对，说，告诉。\n岂：大概，是否。\n之：代词，代诸葛亮。\n与俱来：与（之）俱来，和（他）一起来。俱。一起。\n就见：意思是到诸葛亮那里去拜访。就，接近、趋向。\n屈致：委屈（他），召（他上门）来。致，招致、引来。\n枉（wǎng）驾：屈尊。枉：委屈。驾：车马，借车马指刘备。\n顾：拜访。由是：因此。\n遂（suì）：于是，就。\n诣：去，到。这里是拜访的意思。凡：总共。\n乃见：才见到。因：于是，就。\n屏：这里是命人退避的意思。\n汉室倾颓：指汉朝统治崩溃、衰败。\n奸臣：指董卓、曹操等。窃命：盗用皇帝的政令。\n蒙尘：蒙受风尘，专指皇帝遭难出奔。\n东汉的京城本来在洛阳，董卓强迫汉献帝刘协迁都到陕西长安，曹操又强迫他迁都到河南许昌。\n孤：古代王侯的自称。这里是刘备自称。\n度（duó）德量力：衡量（自己的）德行（能否服人）估计（自己的）力量（能否胜人）。\n欲信：通“伸”，伸张。想。而：表转折。智术：智谋，才识。用：因此。\n猖蹶：这里是失败的意思。然：然而。犹：仍，还。已：停止，罢休。\n谓：认为。计：计策。安：疑问代词，怎么。\n出：产生。自：从。\n已来：已，通“以”，表时间。跨：占据。\n不可胜数：数也数不清。胜，尽。\n比于：同，相比。\n众寡：人少。意思是兵力薄弱。\n克：战胜。为：以为，变成。者：的原因。\n非惟：不仅。抑：而且；亦：也。\n谋：筹划。今：现 在。\n挟（xié）：挟持，控制。\n令：号令。\n诸侯：这里指当时割据一方的军阀。\n此：这。诚：的确。\n争锋：争强，争胜。已历：已经经历。\n国险而民附：地势险要，民众归附。\n贤能为之用：为：被。\n可以为援：为：作为。援：外援。\n图：谋取。据：占据。利：物资。\n尽：全部取得。连：连接。通：到达。\n此用武之国：这是用兵之地，国：地方。意思是兵家必争之地。\n殆（dài）：大概。\n资：资助，给予。\n所以：用来。\n岂有意乎：可有意思吗？\n险塞（sài） ：险峻的要塞。\n天府之土：指自然条件优越，物产丰饶，形势险固的地方。\n高祖：刘邦。\n因：依靠，凭。\n刘璋暗弱：刘璋（当时的益州牧）昏庸懦弱。\n殷：兴旺富裕。\n而：但是。\n存恤：爱抚、爱惜。恤：体恤、体谅。\n胄：后代。刘备是中山靖王刘胜（汉景帝刘启的儿子）的后代，所以称它“帝室之胄”。\n信义：信用道义。\n著：闻名。\n总揽：广泛地罗致。揽，这里有招致的意思。\n岩阻：险阻，指形势险要的地方。\n西和诸戎：向西和中国西部各族的和好。\n南抚夷越：向南安抚中国南部各族。\n内：对内。\n修：治理。\n政理：政治。\n将荆州之军：将：率领。\n宛、洛：河南南阳和洛阳这里泛指中原一带。\n身：亲自。\n川：平野。\n（80）箪食壶浆：形容人民群众热情迎接和款待自己所爱戴的军队。\n（81）诚如是：如果真像这样。\n（82）日：一天天。\n（83）悦：高兴。\n（84）之：代词，代与诸葛亮关系变好这件事。\n（85）之：主谓之间取消句子的独立性。\n（86）犹：好像。\n（87）愿：希望。', poem_tags = '初中文言文,赞美,写人' WHERE poem_title = '隆中对' AND poem_author = '陈寿';
UPDATE edu_poem SET poem_translation = '远看高山色彩明亮，走近一听水却没有声音。\n春天过去，可是依旧有许多花草争奇斗艳，人走近，可是鸟却依然没有被惊动。', poem_notes = '色：颜色，也有景色之意 。\n惊：吃惊，害怕。', poem_appreciation = '看远处的山往往是模糊的，但画上的山色却很清楚，在近处听流水，应当听到水声，但画上的流水却无声。在春天盛开的花，随着春天的逝去就凋谢了。而画上的花，不管在什么季节，它都盛开着。人走近停在枝头上的鸟，它就会受惊飞走。但画上的鸟，即使你走近了，它也不会惊飞。全诗读起来似乎行行违反自然规律，其实正是暗中设谜，写出了画的特点。\n\n　　远看山有色，\n\n　　远山含笑，有色便是好山，何为有色？清秀俊朗红湿绿垂是色，寒色苍苍亦是佳色，奇傀峭拔也是异色，只因其距离而产生美感，让人觉其有无限的风光。此乃是“静境”，静境之美出乎首句，在于有静心者能品之。这就好比是阳春白雪，一开始就将下里巴人给赶出了艺术空间。取消了浮躁者的欣赏美的资格。在这里，任何的浮躁都不行，有的只是心静如水.但不是死水而是活水.你看画中有水呢?一汪春水有着挡不住的盛情倾泻而出.一种流动之美跳跃于诗人的眼中。\n\n　　近听水无声。\n\n　　源头活水本是“动境”，而无声二字又进入静境，宁静致远.和首句并无矛盾之处.动静的取舍上诗人可以说是能够做到游刃有余.是什么如此神奇？静的如此让人难以放弃去一探究竟，这样，我们就会接近此诗此画，这样心神和山水便靠近了。一切的妙处只是因为“无声”，无声是一种美。王羲之的诗中有“在山阴道上行，如在镜中游”，便也是这种美。有声无声都溶在一起，完美的天籁之声！庄子所提的“天籁”之声就是如此，当“天籁”与“人籁”“地籁”一起时，便共同构成一个常人无法言语的自然之声。\n\n　　春去花还在，人来鸟不惊。\n\n　　花儿在那个最美的季节里尽情的开放，并最终将自己的生命燃烧般的开到最美。美到极致后，飘然而去。但此中花儿不谢，只因在画中。不仅仅是如此，写的近近是画中的花，是春尽之时，花儿尽逝，无处得美而伤怀的感触在里面 。\n\n　　鸟儿不惊，不知青春已尽，岁月已逝。徒留下多少悔恨。\n\n　　诗中的画似乎代表着一种梦想，一种可见而不可得的梦想，但那种梦想只是在人的心灵处于一种安静的状态中我们才能够想起。但不可得已是事实，诗人唯有带着淡淡的幽思去寻觅世间最后的能够寄托情怀的东西。人已去，空留花，鸟未惊，人又来，没有永恒的美丽，而一切的美丽都将隐于虚幻。', poem_tags = '古诗三百首,小学古诗,山水,梦想,早教古诗100首' WHERE poem_title = '画' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '一丛一丛的秋菊环绕着房屋，看起来好似诗人陶渊明的家。绕着篱笆观赏菊花，不知不觉太阳已经快落山了。\n不是因为百花中偏爱菊花，只是因为菊花开过之后便不能够看到更好的花了。', poem_notes = '秋丛：指丛丛秋菊。\n舍（shè）：居住的房子。\n陶家：陶渊明的家。陶，指东晋诗人陶渊明。\n遍绕：环绕一遍。\n篱（lí）：篱笆。\n日渐斜（xiá）：太阳渐渐落山。斜，倾斜。因古诗需与上一句押韵，所以应读xiá。\n尽：完。\n更（gèng）：再。', poem_appreciation = '东晋大诗人陶渊明写了“采菊东篱下，悠然见南山”的名句，其爱菊之名，无人不晓，而菊花也逐渐成了超凡脱俗的隐逸者之象征。历代文人墨客爱菊者不乏其人，其中咏菊者也时有佳作。中唐诗人元稹的七绝《菊花》便是其中较有情韵的一首。\n\n　　第一句“秋丛绕舍似陶家”的“绕”字写屋外所种菊花之多，给人以环境幽雅，如陶渊明家之感。诗人将种菊的地方比作陶家，可见秋菊之多，花开之盛。这么多美丽的菊花，让人心情愉悦。\n\n　　第二句“遍绕篱边日渐斜”表现了诗人专注地看花的情形。第二句中的“绕”字写赏菊兴致之浓，不是到东篱便驻足，而是“遍绕篱边”，直至不知日之将夕，表现了诗人赏菊时悠闲的情态。诗人被菊花深深吸引住了，其爱菊之情，似较五柳先生有过之而无不及。“遍绕”“日渐斜”，把诗人赏菊入迷，流连忘返的情态和诗人对菊花的由衷喜爱真切地表现了出来，字里行间充满了喜悦的心情。前两句短短的十四个字，有景、有情、有联想，活脱脱地勾勒出一幅诗人在秋日傍晚漫步菊丛赏花吟诗而乐不思返的画面。\n\n　　三四两句“不是花中偏爱菊，此花开尽更无花”，点明了诗人爱菊的原因。这两句以否定句式陡地一转，指出自己并非没来由地钟情菊花。时至深秋，百花尽谢，唯有菊花能凌风霜而不凋，独立支持，为世界平添了盎然的生机。诗人热爱生活、热爱自然，这四季中最后开放的菊花使他忘情，爱不能舍了。诗人从菊花凋谢最晚这个角度出发，写出了自己独特的爱菊花的理由。其中也暗含了对菊花历尽寒冷最后凋零的坚强品格的赞美之情。中国古典诗词常借物咏怀喻志，如屈原的《桔颂》，陈子昂的《感遇》，都是范例。元稹《菊花》一诗赞菊花高洁的操守、坚强的品格，也是这种写作手法，寓有深意。\n\n　　这首七言绝句诗，虽然写的是咏菊这个寻常的题材，但用笔巧妙，别具一格，诗人独特的爱菊花理由新颖自然，不落俗套，并且发人思考。诗人没有正面写菊花，却通过爱菊，侧面烘托它的优秀品格，美妙灵动，意趣盎然。该诗取陶诗的意境，且也以淡雅朴素的语言吟咏，便不似陶公全用意象，蕴藉之至；而是在描绘具象之后，以自述的方式道出爱菊之由而又不一语说尽，留下了想象空间去回味咀嚼，这就增强了它的艺术感染力。', poem_tags = '咏物,菊花,抒怀' WHERE poem_title = '菊花' AND poem_author = '元稹';
UPDATE edu_poem SET poem_translation = '兰陵美酒甘醇，就像郁金酒的香气芬芳四溢。兴来盛满玉碗，泛出琥珀光晶莹迷人。\n主人端出如此好酒，定能醉倒他乡之客。最后哪能分清，何处才是家乡？', poem_notes = '客中：指旅居他乡。唐孟浩然《早寒江上有怀》诗：“我家襄水上，遥隔楚云端，乡泪客中尽，孤帆天际看。”\n兰陵：今山东省临沂市苍山县兰陵镇；一说位于今四川省境内。郁金香：散发郁金的香气。郁金，一种香草，用以浸酒，浸酒后呈金黄色。\n玉椀（wǎn）：玉制的食具，亦泛指精美的碗。椀，同“碗”。琥珀（hǔpò）：一种树脂化石，呈黄色或赤褐色，色泽晶莹。这里形容美酒色泽如琥珀。\n但使：只要。醉客：让客人喝醉酒。醉，使动用法。\n他乡：异乡，家乡以外的地方。', poem_appreciation = '这首诗赞美了美酒的清醇、主人的热情，表现了诗人豪迈洒脱的精神境界，同时也反映了盛唐社会的繁荣景象。\n\n　　抒写离别之悲、他乡作客之愁，是古代诗歌创作中一个很普遍的主题。然而这首诗虽题为“客中”作，抒写的却是作者的另一种感受。“兰陵美酒郁金香，玉碗盛来琥珀光。”兰陵，点出作客之地，但把它和美酒联系起来，便一扫令人沮丧的外乡异地凄楚情绪，而带有一种使人迷恋的感情色彩了。著名的兰陵美酒，是用香草郁金加工浸制，带着醇浓的芬芳，又是盛在晶莹润泽的玉碗里，看去犹如琥珀般的光艳。诗人面对美酒，愉悦兴奋之情自可想见了。\n\n　　“但使主人能醉客，不知何处是他乡。”这两句诗，可以说既在人意中，又出人意外。说在人意中，因为它符合前面描写和感情发展的自然趋向；说出人意外，是因为《客中行》这样一个似乎是暗示要写客愁的题目，在李白笔下，完全是另一种表现。这样诗就显得特别耐人寻味。诗人并非没有意识到是在他乡，当然也并非丝毫不想念故乡。但是，这些都在兰陵美酒面前被冲淡了。一种流连忘返的情绪，甚至乐于在客中、乐于在朋友面前尽情欢醉的情绪完全支配了他。由身在客中，发展到乐而不觉其为他乡，正是这首诗不同于一般羁旅之作的地方。\n\n　　全诗语奇意也奇，形象潇洒飘逸，充分表现了李白豪放不羁的个性，并从一个侧面反映出盛唐时期的时代气氛。', poem_tags = '赞美,豪迈,离别' WHERE poem_title = '客中行 / 客中作' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '中秋月圆，月光洒在庭院，院中梧桐树影婆娑，我一人羁旅异乡，节日里看这月亮下的树影，时间缓缓过去，影子不知不觉的移动着。\n遥看天上明月，想那月宫中的婵娟，现在也未尝不感遗憾吧，陪伴她的，毕竟只有那清冷月亮和孤寂桂树。', poem_notes = '羁人：旅人。\n隅：角落。\n素娥：指嫦娥。\n玉蟾：月亮的别称。', poem_tags = '中秋节,赏月,羁旅,孤寂,惆怅' WHERE poem_title = '中秋月' AND poem_author = '晏殊';
UPDATE edu_poem SET poem_translation = '水天相接，晨雾蒙蒙笼云涛。银河欲转，千帆如梭逐浪飘。梦魂仿佛回天庭，天帝传话善相邀。殷勤问：归宿何处请相告。\n我回报天帝说：路途漫长啊，又叹日暮时不早。学做诗，枉有妙句人称道。长空九万里，大鹏冲天飞正高。风啊!千万别停息，将我这一叶轻舟，直送往蓬莱三岛去。', poem_notes = '星河：银河。\n转：《历代诗余》作“曙”。\n帝所：天帝居住的地方。\n天语：天帝的话语。\n嗟：慨叹。\n报：回答。谩：徒，空。惊人句，化用《江上值水如海上势聊短述》有“语不惊人死不休”诗句。\n九万里：《庄子·逍遥游》中说大鹏乘风飞上九万里高空。\n鹏：古代神话传说中的大鸟。\n蓬舟：像蓬蒿被风吹转的船。古人以蓬根被风吹飞，喻飞动。\n吹取：吹得。\n三山：《史记·封禅书》记载：渤海中有蓬莱，方丈，瀛洲三座仙山，相传为仙人所居住，可以望见，但乘船前往，临近时就被风吹开，终无人能到。', poem_appreciation = '李清照是一位可以代表婉约派的女作家，她的《声声慢》、《醉花阴》等是大家熟悉的名作。这些词多半写闺情幽怨，它的风格是含蓄、委婉的。但是在她的词作中也有一首风格特殊的《渔家傲》，这是一首豪放的词，她用《离骚》、《远游》的感情来写小令，不但是五代词中所没有的，就是北宋词中也很少见。一位婉约派的女词人，而能写出这样有气魄的作品，确实值得注意。\n\n　　整首词都是描写梦境。开头两句写拂晓时候海上的景象。在李清照以前还没有人在词里描写过大海。“天接云涛”两句用“接”、“转”、“舞”三个动词，来写海天动宕的境界。“星河欲转”，点出时间已近拂晓。“千帆舞”写大风，这不是江河中的景象。可能因为李清照是山东人，对海的见闻比较多，所以写得出这样的境界。上片第三句“仿佛梦魂归帝所”，意思是说：我原来就是天帝那儿来的人，现在又回到了天帝处所。这和苏轼《水调歌头》中秋词：“我欲乘风归去”之“归”字意义相同。“归何处”句，着“殷勤”二字，写出天帝的好意，引起下片换头“我报路长嗟日暮”二句的感慨。《离骚》：“欲少留此灵琐兮，日忽忽其将暮。……路曼曼其修远兮，吾将上下而求索”。这就是李清照“路长日暮”句的出处。这句子的意思是说人世间不自由，尤其是封建时代的妇女，纵使学诗有惊人之句（“谩有”是“空有”的意思），也依然是“路长日暮”，找不到她理解的境界。末了几句说：看大鹏已经高翔于九万里风之上；大风呵，不住地吹吧，把我的帆船吹送到蓬莱三岛去吧（“九万里风”句用《庄子?逍遥游》，说大鹏“抟扶摇而上者九万里”，扶摇，旋风，九是虚数）！\n\n　　李清照是婉约派的女作家，何以能写出这样豪放的作品呢？在封建社会中，女子生活于种种束缚之下，即使象李清照那样有高度修养和才华的女作家也不能摆脱这种命运，这无疑会使她感到烦闷和窒息。她作了两首《临江仙》词，都用欧阳修的成语“庭院深深深几许”作为起句，这很可能是借它表达她的烦闷的心情。她要求解脱，要求有广阔的精神境界。这首词中就充分表示她对自由的渴望，对光明的追求。但这种愿望在她生活的时代的现实生活中是不可能实现的，因此她只有把它寄托于梦中虚无缥缈的神仙境界，在这境界中寻求出路。然而在那个时代，一个女子而能不安于社会给她安排的命运，大胆地提出冲破束缚、向往自由的要求，确实是很难得的。在历史上，在封建社会的妇女群中是很少见的。\n\n　　这首风格豪放的词，意境阔大，想象丰富，确实是一首浪漫主义的好作品。出之于一位婉约派作家之手，那就更为突出了。其所以有此成就，无疑是决定于作者的实际生活遭遇和她那种渴求冲决这种生活的思想感情；这绝不是没有真实生活感情而故作豪语的人所能写得出的。', poem_tags = '宋词三百首,宋词精选,豪放,感伤,怀念' WHERE poem_title = '渔家傲·天接云涛连晓雾' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '庭院深深，不知有多深？杨柳依依，飞扬起片片烟雾，一重重帘幕不知有多少层。豪华的车马停在贵族公子寻欢作乐的地方，她登楼向远处望去，却看不见那通向章台的大路。 \n春已至暮，三月的雨伴随着狂风大作，再是重门将黄昏景色掩闭，也无法留住春意。泪眼汪汪问落花可知道我的心意，落花默默不语，纷乱的，零零落落一点一点飞到秋千外。', poem_notes = '几许：多少。许，估计数量之词。\n堆烟：形容杨柳浓密。\n玉勒：玉制的马衔。\n雕鞍：精雕的马鞍。\n游冶处：指歌楼妓院。\n章台：汉长安街名。《汉书·张敞传》有“走马章台街”语。唐许尧佐《章台柳传》，记妓女柳氏事。后因以章台为歌妓聚居之地。\n乱红：凌乱的落花。', poem_appreciation = '这首词亦见于冯延巳的《阳春集》。清人刘熙载说：“冯延巳词，晏同叔得其俊，欧阳永叔得其深。”（《艺概·词曲概》）在词的发展史上，宋初词风承南唐，没有太大的变化，而欧与冯俱仕至宰执，政治地位与文化素养基本相似。因此他们两人的词风大同小异，有些作品，往往混淆在一起。此词据李清照《临江仙》词序云：“欧阳公作《蝶恋花》，有‘深深深几许’之句，予酷爱之，用其语作‘庭院深深’数阕。”李清照去欧阳修未远，所云当不误。\n\n　　此词写闺怨。词风深稳妙雅。所谓深者，就是含蓄蕴藉，婉曲幽深，耐人寻味。此词首句“深深深”三字，前人尝叹其用叠字之工；兹特拈出，用以说明全词特色之所在。不妨说这首词的景写得深，情写得深，意境也写得深。\n\n　　先说景深。词人像一位舞台美术设计大师一样，首先对女主人公的居处作了精心的安排。读着“杨柳堆烟，帘幕无重数”这两句，似乎在眼前出现了一组电影摇镜头，由远而近，逐步推移，逐步深入。随着镜头所指，读者先是看到一丛丛杨柳从眼前移过。“杨柳堆烟”，说的是早晨杨柳笼上层层雾气的景象。着一“堆”字，则杨柳之密，雾气之浓，宛如一幅水墨画。随着这一丛丛杨柳过去，词人又把镜头摇向庭院，摇向帘幕。这帘幕不是一重，而是过了一重又是一重。究竟多少重，他不作琐屑的交代，一言以蔽之日“无重数”。“无重数”，即无数重。秦观《踏莎行》“驿寄梅花，鱼传尺素，砌成此恨无重数”，与此同义。一句“无重数”，令人感到这座庭院简直是无比幽深。可是词人还没有让你立刻看到人物所在的地点。他先说一句“玉勒雕鞍游冶处”，宕开一笔，把读者的视线引向她丈夫那里；然后折过笔来写道：“楼高不见章台路”。原来这词中女子正独处高楼，她的目光正透过重重帘幕，堆堆柳烟，向丈夫经常游冶的地方凝神远望。这种写法叫做欲扬先抑，做尽铺排，造足悬念，然后让人物出场，如此便能予人以深刻的印象。\n\n　　再说情深。词中写情，通常是和景结合，即景中有情，情中有景，但也有所侧重。此词将女主人公的感情层次挖得很深，并用工笔将抽象的感情作了细致入微的刻画。词的上片着重写景，但“一切景语，皆情语也”（王国维《人间词话》），在深深庭院中，人们仿佛看到一颗被禁锢的与世隔绝的心灵。词的下片着重写情，雨横风狂，催送着残春，也催送女主人公的芳年。她想挽留住春天，但风雨无情，留春不住。于是她感到无奈，只好把感情寄托到命运同她一样的花上：“泪眼问花花不语，乱红飞过秋千去。”这两句包含着无限的伤春之感。清人毛先舒评曰：“词家意欲层深，语欲浑成。作词者大抵意层深者，语便刻画；语浑成者，意便肤浅，两难兼也。或欲举其似，偶拈永叔词云：‘泪眼问花花不语，乱红飞过秋千去。’此可谓层深而浑成。”（王又华《古今词论》引）他的意思是说语言浑成与情意层深往往是难以兼具的，但欧词这两句却把它统一起来。所谓“意欲层深”，就是人物的思想感情要层层深入，步步开掘。且看这两句是怎样进行层层开掘的。第一层写女主人公因花而有泪。见花落泪，对月伤情，是古代女子常有的感触。此刻女子正在忆念走马章台（汉长安章台街，后世借以指游冶之处）的丈夫，可是望而不可见，眼中惟有在狂风暴雨中横遭摧残的花儿，由此联想到自己的命运，不禁伤心泪下。第二层是写因泪而问花。泪因愁苦而致，势必要找个发泄的对象。这个对象此刻已幻化为花，或者说花已幻化为人。于是女主人公向着花儿痴情地发问。第三层是花儿竟一旁缄默，无言以对。是不理解她的意思呢，还是不肯给予同情，殊令人纳闷。紧接着词人写第四层，花儿不但不语，反而像故意抛舍她似的纷纷飞过秋千而去。人儿走马章台，花儿飞过秋千，有情之人，无情之物对她都报以冷漠，她不可能不伤心。这种借客观景物的反应来烘托、反衬人物主观感情的写法，正是为了深化感情。词人一层一层深挖感情，并非刻意雕琢，而是像竹笋有苞有节一样，自然生成，逐次展开。在自然浑成、浅显易晓的语言中，蕴藏着深挚真切的感情，这是此篇一大特色。\n\n　　最后是意境深。词中写了景，写了情，而景与情又是那样的融合无间，浑然天成，构成了一个完整的意境。读此词，总的印象便是意境幽深，不徒名言警句而已。词人刻画意境也是有层次的。从环境来说，它是由外景到内景，以深邃的居室烘托深邃的感情，以灰暗凄惨的色彩渲染孤独伤感的心情。从时间来说，上片是写浓雾弥漫的早晨，下片是写风狂雨暴的黄昏，由早及晚，逐次打开人物的心扉。过片三句，近人俞平伯评日：“‘三月暮’点季节，‘风雨，点气候，‘黄昏’点时刻，三层渲染，才逼出‘无计’句来。”（《唐宋词选释》）暮春时节，风雨黄昏；闭门深坐，情尤怛恻。个中意境，仿佛是诗，但诗不能写其貌；是画，但画不能传其神；惟有通过这种婉曲的词笔才能恰到好处地勾画出来。尤其是结句，更臻于妙境：“一若关情，一若不关情，而情思举荡漾无边。”（沈际飞《草堂诗余正集》）王国维认为这是一种“有我之境”。所谓“有我之境”，便是“以我观物，故物皆著我之色彩”（《人间词话》）。也就是说，花儿含悲不语，反映了词中女子难言的苦痛；乱红飞过秋千，烘托了女子终鲜同情之侣、怅然若失的神态。而情思之绵邈，意境之深远，尤令人神往。', poem_tags = '宋词三百首,宋词精选,婉约,孤独,闺怨' WHERE poem_title = '蝶恋花·庭院深深深几许' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '我家贫穷，种田不能够自给。孩子很多，米缸里没有存粮，维持生活所需的一切，没有办法解决。亲友大都劝我去做官，我心里也有这个念头，可是求官缺少门路。正赶上有奉使外出的官吏，地方大吏以爱惜人才为美德，叔父也因为我家境贫苦（替我设法），我就被委任到小县做官。那时社会上动荡不安，心里惧怕到远地当官。彭泽县离家一百里，公田收获的粮食，足够造酒饮用，所以就请求去那里。等到过了一些日子，便产生了留恋故园的怀乡感情。那是为什么？本性任其自然，这是勉强不得的；饥寒虽然来得急迫，但是违背本意去做官，身心都感痛苦。过去为官做事，都是为了吃饭而役使自己。于是惆怅感慨，深深有愧于平生的志愿。只再等上一年，便收拾行装连夜离去。不久，嫁到程家的妹妹在武昌去世，去吊丧的心情像骏马奔驰一样急迫，自己请求免去官职。自立秋第二个月到冬天，在职共80多天。因辞官而顺遂了心愿，写了一篇文章，题目叫《归去来兮》。这时候正是乙巳年（晋安帝义熙元年）十一月。\n\n正文译文\n　　回家去吧！田园快要荒芜了，为什么不回去呢？既然自己的心灵为形体所役使，为什么如此失意而独自伤悲？认识到过去的错误已经不可挽回，知道未来的事还来得及补救。确实走入了迷途大概还不远，已觉悟到现在的做法是对的而曾经的行为是错的。船在水上轻轻飘荡，微风吹拂着衣裳。向行人打听前面的路，遗憾的是天亮得太慢。\n　　刚刚看到自己简陋的家门，我心中欣喜，奔跑过去。孩子们欢快地迎接，孩子们守候在门前或院子里。院子里的小路快要荒芜了，松树菊花还长在那里；带着孩子们进了屋，美酒已经盛满了酒樽。我端起酒壶酒杯自斟自饮，观赏着庭树（使我）露出愉快的神色；倚着南窗寄托我的傲世之情，深知这狭小之地容易使我心安。每天（独自）在园中散步，成为乐趣,小园的门经常地关闭着；拄着拐杖走走歇歇，时时抬头望着远方（的天空）。白云自然而然地从山峰飘浮而出，倦飞的小鸟也知道飞回巢中；日光暗淡，即将落山，我流连不忍离去，手抚着孤松徘徊不已。\n　　回去吧！让我同外界断绝交游。他们的一切都跟我的志趣不合，还要驾车出去追求什么？跟亲戚朋友谈心使我愉悦，弹琴读书能使我忘记忧愁；农夫把春天到了的消息告诉了我，将要去西边的田地耕作。有时驾着有布篷的小车，有时划着一条小船，既要探寻那幽深的沟壑，又要走过那高低不平的山丘。树木欣欣向荣，泉水缓缓流动，（我）羡慕万物恰逢繁荣滋长的季节，感叹自己一生行将告终。\n　　算了吧！身体寄托在天地间还能有多少时候？为什么不随心所欲，听凭自然的生死？为什么心神不定，还想去什么地方？富贵不是我所求，升入仙界也没有希望。爱惜那良辰美景我独自去欣赏，要不就扶杖锄草耕种；登上东边山坡我放声长啸，傍着清清的溪流把诗歌吟唱；姑且顺随自然的变化，度到生命的尽头。乐安天命，还有什么可疑虑的呢？\n\n序文', poem_notes = '（1）耕植不足以自给：耕：耕田。植：植桑。以：来。给：供给。自给：供给自己生活。\n（2）幼稚盈室，瓶无储粟：幼稚：指孩童。盈：满。瓶：指盛米用的陶制容器、如甏（bèng），瓮之类。\n（3）生生所资，未见其术：生生：犹言维持生计。前一“生”字为动词，后一“生”字为名词。资：凭借。术：这里指经营生计的本领。\n（4）长吏：较高职位的县吏。指小官。\n（5）脱然：不经意的样子。有怀：心有所动（指有了做官的念头）。\n（6）靡途：没有门路。\n（7）会有四方之事：刚巧碰上有出使到外地去的事情。会：适逢。四方：意为到各处去\n（8）诸侯：指州郡长官。\n（9）家叔：指陶夔（kuí），当时任太常卿。以：因为。\n（10）见：被。\n（11）风波：指军阀混战。静：平。\n（12）惮：害怕。役：服役。\n（13）彭泽：县名。在今江西省湖口县东。\n（14）眷然：思恋的样子。归欤（yú）之情：回去的心情。\n（15）何：什么。则：道理。\n（16）质性：本性。矫厉：造作勉强。\n（17）切：迫切。违己：违反自己本心。 交病：指思想上遭受痛苦。\n（18）尝：曾经。从人事：从事于仕途中的人事交往。指做官。\n（19）口腹自役：为了满足口腹的需要而驱使自己。\n（20）怅然：失意。\n（21）犹：踌躇、犹疑。望：观望。一稔（rěn）：公田收获一次。稔，谷物成熟。\n（22）敛裳：收拾行装。宵：星夜。逝：离去。\n（23）寻：不久。程氏妹：嫁给程家的妹妹。武昌：今湖北省鄂城县。\n（24）情：吊丧的心情。在：像。骏奔：急着前去奔丧。\n（25）仲秋：农历八月。\n（26）事：辞官。顺：顺遂。心：心愿。\n（27）乙巳岁：晋安帝义熙元年。\n\n正文注释\n（1）归去来兮：意思是“回去吧”。来，助词，无义。兮，语气词。\n（2）田园将芜胡不归：田园将要荒芜了，为什么不回去？芜，田地荒废。胡，同“何”，为什么。\n（3）既自以心为形役：让心神为形体所役使。意思是本心不愿出仕，但为了免于饥寒，违背本意做了官。心，意愿。形，形体，指身体。役，奴役。既，表示动作、行为已经完成，此处可做“曾经”解。\n（4）奚惆怅而独悲：为什么悲愁失意。奚，何，为什么。惆怅，失意的样子。\n（5）悟已往之不谏：认识到过去的错误（指出仕）已经不可挽回。谏，谏止，劝止。\n（6）知来者之可追：知道未来的事（指归隐）还来得及补救。谏，劝止，挽回。追，补救。\n（7）实迷途其未远：确实走入了迷途大概还不太远。迷途，指出来做官。\n（8）是：正确。非：错误。\n（9）舟遥遥以轻飏（yáng）：船在水面上轻轻地飘荡着前进。遥遥，飘摇放流的样子。以，表修饰。飏，飞扬，形容船行驶轻快。\n（10）问征夫以前路：向行人问前面的路程。征夫，行人。\n（11）恨晨光之熹微：遗憾的是天刚刚放亮。恨:遗憾。熹微，天色微明。\n（12）乃瞻衡宇，：刚刚看见了自家的房子。乃，于是、然后。瞻，远望。衡宇，横木为门的房屋，指简陋的房屋。衡，通“横”。宇，屋檐，这里指居处。\n载（zài）欣载奔：一边高兴，一边奔跑。\n（13）稚子：幼儿。\n（14）三径就荒，松菊犹存：院子里的小路快要荒芜了，松菊还长在那里。三径，院中小路。汉朝蒋诩（xǔ） 隐居之后，在院里竹下开辟三径，只于少数友人来往。后来，三径变成了隐士住处的代称。就，接近。\n（15）盈樽：满杯。\n（16）引：拿来。 觞（shāng）。眄（miǎn）庭柯以怡颜：看看院子里的树木，觉得很愉快。眄，斜看。这里是“随便看看”的意思。柯，树枝。以：为了。怡颜，使面容现出愉快神色。\n（17）寄傲：寄托傲然自得的心情。傲，指傲世。\n（18）审容膝之易安：觉得住在简陋的小屋里也非常舒服。审，觉察。容膝，只能容下双膝的小屋，极言其狭小。\n（19）园日涉以成趣：天天到园里行走，自成一种乐趣。涉，涉足，走到。\n（20）策扶老以流憩（qì）：拄着拐杖出去走走，随时随地休息。策，拄着。扶老，手杖。憩，休息。流憩，游息，就是没有固定的地方，到处走走歇歇。\n（21）时矫首而遐观：时时抬起头向远处望望。矫，举。遐，远。\n（22）云无心以出岫（xiù）：云气自然而然地从山里冒出。无心，无意地。岫，有洞穴的山，这里泛指山峰。\n（23）景翳（yì）翳以将入：阳光黯淡，太阳快落下去了。景，日光。翳翳，阴暗的样子。\n（24）抚孤松而盘桓：手扶孤松徘徊。盘桓：盘旋，徘徊，留恋不去。\n（25）请息交以绝游：息交，停止与人交往断绝交游。意思是不再同官场有任何瓜葛。\n（26）世与我而相违，复驾言兮焉求：世事与我所想的相违背，还能努力探求什么呢？驾，驾车，这里指驾车出游去追求想要的东西。言，助词。\n（27）情话：知心话。\n（28）春及：春天到了。\n（29）将有事于西畴：西边田野里要开始耕种了。有事，指耕种之事。事，这里指农事。畴，田地。\n（30）或命巾车：有时叫上一辆有帷的小车。巾车，有车帷的小车。或，有时。\n（31）或棹（zhào）孤舟：有时划一艘小船。棹，本义船桨。这里名词做动词，意为划桨。\n（32）既窈窕以寻壑：经过幽深曲折的山谷。窈窕，幽深曲折的样子。壑，山沟。\n（33）亦崎岖而经丘：走过高低不平的山路。\n（34）木欣欣以向荣：草木茂盛。欣欣，向荣，都是草木滋长茂盛的意思。\n（35）涓涓：水流细微的样子。\n（36）善万物之得时，感吾生之行休：羡慕自然界万物一到春天便及时生长茂盛，感叹自己的一生行将结束。善，欢喜，羡慕。行休，行将结束。\n（37）已矣乎：算了吧!助词“矣”与“乎”连用，加强感叹语气。\n（38）寓形宇内复几时，曷（hé）不委心任去留：活在世上能有多久，何不顺从自己的心愿，管它什么生与死呢？寓形，寄生。宇内，天地之间。曷，何。委心，随心所欲。去留，指生死。\n（39）胡为乎遑遑欲何之：为什么心神不定，想到哪里去呢？遑遑，不安的样子。之，往。\n（40）帝乡不可期：仙境到不了。帝乡，仙乡，神仙居住的地方。期，希望，企及。\n（41）怀良辰以孤往：爱惜美好的时光，独自外出。怀，留恋、爱惜。良辰，指上文所说万物得时的春天。孤独，独自外出。\n（42）或植杖而耘耔：有时扶着拐杖除草培苗。植，立，扶着。耘，除草。籽，培土。\n（43）登东皋（gāo）以舒啸：登上东面的高地放声长啸，皋，高地。啸，撮口发出的长而清越的一种声音。舒，放。\n（44）聊乘化以归尽：姑且顺其自然走完生命的路程。聊：姑且。乘化，随顺大自然的运转变化。归尽：到死。尽，指死亡。\n（45）乐夫天命复奚疑：乐安天命，还有什么可疑虑的呢？ 复：还有。疑：疑虑。', poem_appreciation = '东晋安帝义熙元年（405），陶渊明弃官归田，作《归去来兮辞》。陶渊明从29岁起开始出仕，任官十三年，一直厌恶官场，向往田园。他在义熙元年41岁时，最后一次出仕，做了八十多天的彭泽令即辞官回家。以后再也没有出来做官。据《宋书.陶潜传》和萧统《陶渊明传》云，陶渊明归隐是出于对腐朽现实的不满。当时郡里一位督邮来彭泽巡视，官员要他束带迎接以示敬意。他气愤地说：“我不愿为五斗米折腰向乡里小儿！”即日挂冠去职，并赋《归去来兮辞》，以明心志。\n\n　　陶渊明从晋孝武帝太元十八年（393）起为州祭酒，到义熙元年作彭泽令，十三年中，他曾经几次出仕，几次归隐。渊明有过政治抱负，但是当时的政治社会已极为黑暗。晋安帝元兴二年（403），军阀桓玄篡晋，自称楚帝。元兴三年，另一个军阀刘裕起兵讨桓，打进东晋都城建康（今江苏南京）。至义熙元年，刘裕完全操纵了东晋王朝的军政大权。这时距桓玄篡晋，不过十五年。伴随着这些篡夺而来的，是数不清的屠杀异己和不义战争。渊明天性酷爱自由，而当时官场风气又极为腐败，谄上骄下，胡作非为，廉耻扫地。一个正直的士人，在当时的政洽社会中决无立足之地，更谈不上实现理想抱负。渊明经过十三年的曲折，终于彻底认清了这一点。渊明品格与政治社会之间的根本对立，注定了他最终的抉择——归隐。', poem_tags = '高中文言文,古文观止,抒情,向往,归隐,田园' WHERE poem_title = '归去来兮辞·并序' AND poem_author = '陶渊明';
UPDATE edu_poem SET poem_translation = '韵译\n青山无尽楼阁连绵望不见头，西湖上的歌舞几时才能停休？\n暖洋洋的香风吹得贵人如醉，简直是把杭州当成了那汴州。\n散译\n远处青山叠翠，近处楼台重重，西湖的歌舞何时才会停止？\n淫靡的香风陶醉了享乐的贵人们，简直是把偏安的杭州当作昔日的汴京！', poem_notes = '临安：现在浙江杭州市，金人攻陷北宋首都汴京后，南宋统治者逃亡到南方，建都于临安。邸（dǐ）：旅店。\n西湖：杭州的著名风景区。几时休：什么时候休止。\n熏（xūn）：吹，用于温暖馥郁的风。\n直：简直。汴州：即汴京，今河南开封市。', poem_appreciation = '这是一首写在临安城一家旅店墙壁上，不但通过描写乐景来表哀情，使情感倍增，而且在深邃的审美境界中，蕴含着深沉的意蕴。同时，诗人以讽刺的语言中，不漏声色地揭露了“游人们”的反动本质，也由此表现出诗人的愤激之情。\n\n　　诗的头句“山外青山楼外楼” ，诗人抓住临安城的特征——重重叠叠的青山，鳞次栉比的楼台。这样首先描写了祖国大好山河，起伏连绵的青山，楼阁接着一个，这是多么美好的自然。从诗歌创作来说，诗人描写山河的美好，表现出的是一种乐景。接着写到：“西湖歌舞几时休？”诗人面对国家的现实处境，触景伤情。这样美好的大好山河，却被金人占有。诗句中一个“休”字，不但暗示了诗人对现实社会处境的心痛，更为重要的是表现出诗人对当政者一味“休”战言和、不思收复中原失地、只求苟且偏安、一味纵情声色、寻欢作乐的愤慨之情。在诗人的心中，“西湖歌舞”正是消磨抗金斗志的淫靡歌舞。他此时是多么希望这样的歌舞快“休”了。这里，诗人运用反问手法，不但强化了自己的对这些当政者不思收复失地的愤激之情，也更加表现出诗人对国家命运的担忧而产生的忧伤之感。\n\n　　后两句“暖风熏得游人醉，直把杭州作汴州”。“游人”在这里不能仅仅理解为一般游客，它是主要特指那些忘了国难，苟且偷安，寻欢作乐的南宋统治阶级。这句紧承上“西湖歌舞几时休”而来。诗人面对这不停的歌舞，看着这些“游人们”陶醉其中，不由得表现出自己的感慨之情。其中，“暖风”一语双关，在诗歌中，既指自然界的春风，又指社会上淫靡之风。在诗人看在，正是这股“暖风”把“游人”的头脑吹得如醉如迷，忘记了自己的国家正处于危难之中。其中的“熏”、“醉”两字用得很精妙。首先，一个“熏”字，暗示了那些歌舞场面的庞大与热闹，为“游人们”营造了靡靡之音的氛围。接着一个“醉”字，承接上一个“熏”字，把那些纵情声色的“游人们”的精神状态刻画得惟妙惟肖。一个“醉”字，留下了丰富的审美想象空间——“游人们”在这美好的“西湖”环境中的丑态。在这样的状态下，诗人为了进一步表现出“游人醉”，在结尾中写道：“直把杭州作汴州。”宋朝原来建都于汴梁，时已为金侵占。就是说，纸醉金迷中，这些“游人”们简直把杭州当成了故都汴州。这里，诗人不用“西湖”而用“杭州”是很有意义的。因为“西湖”虽在杭州，但说到“西湖”，美景之地，是游山玩水的最佳去处，而且也仅仅是杭州的一个景点。而诗人用“杭州”，就很好地与宋都“汴州”（“汴州”已经被金人占有）对照。在对照中，不但引出“汴州”这一特殊的、富有政治意义的名称，而且更有助于抒发诗人的情感——揭露那些“游人们”无视国家前途与命运，沉醉在醉生梦死、不顾国计民生的卑劣行为，同时，也表达诗人对国家民族命运的深切忧虑，及其对统治者只求苟且偏安，对外屈膝投降的愤怒之情。', poem_tags = '古诗三百首,写景,地名,讽刺,生活' WHERE poem_title = '题临安邸' AND poem_author = '林升';
UPDATE edu_poem SET poem_translation = '能吹落秋天金黄的树叶，能吹开春天美丽的鲜花。\n刮过江面能掀千尺巨浪，吹进竹林能使万竿倾斜。', poem_notes = '解落：吹落，散落。解：解开，这里指吹。三秋：秋季。一说指农历九月。\n能：能够。二月：农历二月，指春季。\n过：经过。\n斜：倾斜。', poem_appreciation = '解落三秋叶,能开二月花,过江千尺浪,入竹万竿斜.这是一首描写风的小诗,它是从动态上对风的一种诠释和理解。\n\n　　风无形,空气流动形成风.但它又是有形的, 一阵微风掠过,小草含笑向人们点头,花儿在风中摇曳着,变着法儿撒欢儿,炊烟随着风的节奏跳起直上重霄的舞蹈,纤细的柳枝轻拂着树下游人的脸庞。\n\n　　风也有自己的思想和感情,当它欢欣的时候,往往伴着细雨洋洋洒洒飘落,春天来临的时候,风过千山秀、二月春风似剪刀,春风拂拂，像“飞天”的裙裾在梳理着，春风吹醒冬眠的柳绦，春风送来翩飞的燕子，春风吹绿了千沟万壑，春风摇醒了小草的青春，也在人们心中播下了盎然的春意。\n\n　　当它发怒的时候，过江卷起漫天狂澜，有苏轼的《赤壁怀古》来证明：乱石穿空，惊涛拍岸，卷起千堆雪。它引发海啸，将参天大树连根拨起，用掌击碎轿车甩向路沟，用衣袖挥断成片树木，狂笑着，轻蔑地看着对它束手无策的人们，视自己为一列战车，而世上万物如螳臂。\n\n　　当它悲哀的时候，会发出呜呜咽咽的声音，似在诉说心中的悲怨与委屈，似小孩在哭泣，听之也不得不为之动容。\n\n　　风是神奇的，风是千变万化的，风是柔弱的，风又是强悍的。敏感的风，多情的风，凄婉的风，千姿百态的风，你是人类的朋友，却也给人类带来无尽的灾难，风，你让人不得不爱，同时也让人惧之三分。', poem_tags = '写风,励志' WHERE poem_title = '风' AND poem_author = '李峤';
UPDATE edu_poem SET poem_translation = '幽静的山谷里看不见人，只能听到那说话的声音。\n落日的影晕映入了深林，又照在青苔上景色宜人。', poem_notes = '鹿柴（zhài）：“柴”同“寨“，栅栏。此为地名。\n但：只。闻：听见。\n返景：夕阳返照的光。“景”古时同“影”。\n照：照耀(着)。', poem_appreciation = '这首诗描绘的是鹿柴附近的空山深林在傍晚时分的幽静景色。诗的绝妙处在于以动衬静，以局部衬全局，清新自然，毫不做作。落笔先写空山寂绝人迹，接着以但闻一转，引出人语响来。空谷传音，愈见其空；人语过后，愈添空寂。最后又写几点夕阳余晖的映照，愈加触发人幽暗的感觉。\n\n　　大凡写山水，总离不开具体景物，或摹状嶙峋怪石，或描绘参天古木，或渲染飞瀑悬泉，其着眼点在于景物之奇。而此诗则从一个奇特的现象着笔：“空山不见人，但闻人语响。”层岩迭嶂，看去空无一人。可是有时会突然听得朗朗笑语，但由于回声的多重反射，一时间很难判断人声究竟从何而起。人们大约都有类似的经验，本来很平常。但是将这种视觉与听觉互补的观察事物的方法以诗的形式加以表现，就不能不说是一个创造。从诗的表现说，它别出新意，不蹈故常；从作品的接受者说，是那样新奇有趣，俨如身临其境，由此引起积极的情感活动。前两句诗用直白的语言，略作点染，境界即出。诗开头的“空山”，二字，是相对于无人而言，同时表明诗人的视野比较开阔，可以一视无碍；如果置身于隐天蔽日的原始森林中，就得不到“空山”的意象。从这两个字，也可以窥见山中的景物形势特点。对句的“响”字与“空山”相呼应：只有在没有太多障碍物的情况下，声音才能在山谷中往复回荡，方才可以说“人语响”。因此，周遭景物必是疏朗的。前二句写幽静，因声传神；后二句写幽深，以光敷色。山中景色会因朝夕晦暝、风雨因时而变化。此诗则选取傍晚时分的景色作为描写对象。这时夕阳返照射入树林深处，又有一部分光线落到青苔上面。天色就要暗下来，各类景物斑斑驳驳的，明暗对比鲜明。近处，投在地面上的蓊郁的树影渐渐拉长；树林深处，因黝暗而显得十分幽邃。这种景观的最佳时期是夏末秋初，而且必须是晴朗的傍晚，阴雨绵绵是不行的。诗的第一个透视点是深林。人的感官无法直接测知树林深处，此诗以不可见即想象中的“无限”和“神秘莫测”写幽深之感。而幽深之感唯在夏末秋初夕阳明天中为最深。第二个透视点是青苔。这一景色即在目底，可以观其形，可以辨其色。青苔生于阴暗潮湿之处，它的生长，是浓密的树木遮住日光的结果，而此刻却在夕照中。这两个透视点合在一起，互相映发，使诗意虚实相生。\n\n　　这首诗创造了一种幽深而光明的象征性境界，表现了作者在深幽的修禅过程中的豁然开朗。诗中虽有禅意，却不诉诸议论说理，而全渗透于自然景色的生动描绘之中。\n\n　　王维是诗人、画家兼音乐家。这首诗正体现出诗、画、乐的结合。他以音乐家对声的感悟，画家对光的把握，诗人对语言的提炼，刻画了空谷人语、斜辉返照那一瞬间特有的寂静清幽，耐人寻味。', poem_tags = '唐诗三百首,写山,写景' WHERE poem_title = '鹿柴' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '秋风吹冷，孤独的情怀有谁惦念？看片片黄叶飞舞遮掩了疏窗，伫立夕阳下，往事追忆茫茫。\n酒后小睡，春日好景正长，闺中赌赛，衣襟满带茶香，昔日平常往事，已不能如愿以偿。', poem_notes = '谁：此处指亡妻。\n萧萧：风吹叶落发出的声音。\n疏窗：刻有花纹的窗户。\n被酒：中酒、酒醉。\n春睡：醉困沉睡，脸上如春色。\n赌书：此处为李清照和赵明诚的典故。李清照《金石录后序》云：“余性偶强记，每饭罢，坐归来堂，烹茶，指堆积书史，言某事在某书某卷第几页第几行，以中否角胜负，为饮茶先后。中即举杯大笑，至茶倾覆怀中，反不得饮而起，甘心老是乡矣！故虽处忧患困穷而志不屈。”此句以此典为喻说明往日与亡妻有着像李清照一样的美满的夫妻生活。\n消得：消受，享受。', poem_appreciation = '纳兰性德此词，上阕是此时此地的沉思，下阕是对往时往事的回忆；上阕是纳兰性德此时此地的孤独，下阕是纳兰性德和妻子在曾经的短短三年之中那一些短暂而无边的欢乐。\n\n　　上阕写丧妻后的孤单凄凉。首句从季节变换的感受发端。西风渐紧，寒意侵人。值此秋深之际，若在往日，卢氏便会催促作者添加衣裳，以免着凉生病。但今年此时，卢氏已长眠黄土，阴阳阻隔，天壤之别，她再也不能来为作者铺床叠被，问寒问暖地关心他了。“谁念西风独自凉？”这句反问的答案尽在不言之中，混合了期待与失望的矛盾情绪。王国维在《人间词话》中说：“一切景语，皆情语也。”开篇“西风”便已奠定了整首词哀伤的基调。在西风吹冷、黄叶萧萧的冬天日子里，作者紧闭着窗子，独自觉得特别寒冷，但有谁关心呢？词人明知已是“独自凉”，无人念及，却偏要生出“谁念”的诘问。仅此起首一句，便已伤人心髓，后人读来不禁与之同悲。而“凉”字描写的绝不只是天气，更是词人的心境。\n\n　　次句“萧萧黄叶”是秋天的典型景象。在秋风劲吹之下，枯黄的树叶纷纷扬扬地通过窗户飘进屋内，给作者心头更添一层秋意。于是，他便关上窗户，把那触绪神伤的黄叶挡在窗外。窗户关上了，黄叶自然不会再来叨扰，但作者因此也同外界完全隔绝，因而处境更加孤独。孤寂的感受使作者触景生情。他独立在空荡荡的屋中，任夕阳斜照在身上，把身影拖得很长很长。这时，他的整个身心全部沉浸在对往事的回忆中。次句平接，面对萧萧黄叶，又生无限感伤，“伤心人”哪堪重负？纳兰性德或许只有一闭“疏窗”，设法逃避痛苦以求得内心短时的平静。“西风”、“黄”、“疏窗”、“残阳”、“沉思往事”的词人，到这里，词所列出的意向仿佛推向了一个定格镜头，凄凉的景物衬托着作者凄凉的回忆，长久地锲入读者的脑海，并为之深深感动。\n\n　　下阕很自然地写出了词人对往事的追忆。前两句回忆妻子在时的生活的两个片断：前一句写妻子对自己无微不至的体贴和关心，自己在春天里酒喝得多了，睡梦沉沉，妻子怕扰了他的好梦，动作说话都轻轻的，不敢惊动；后一句写夫妻风雅生活的乐趣，夫妻以茶赌书，互相指出某事出在某书某页某行，谁说得准就举杯饮茶为乐，以至乐得茶泼了地，满室洋溢着茶香。这生活片断极似当年著名女词人李清照和她的丈夫赵明诚赌书的情景，说明他们的生活充满着诗情和雅趣，十分美满和幸福。纳兰性德以赵明诚、李清照夫妇比自己与卢氏，意在表明白己对卢氏的深深爱恋以及丧失这么一位才情并茂的妻子的无限哀伤。纳兰性德是个痴情的人，已是“生死两茫茫”，阴阳相隔，而他仍割舍不下这份情感，性情中人读来不禁潸然。伤心的纳兰性德明知无法挽同一切，只有把所有的哀思与无奈化为最后一句“当时只道是寻常”。这七个字更是字字皆血泪。卢氏生前，作者沉浸在人生最大的幸福之中，但他却毫不觉察，只道理应如此，平平常常。言外之意，蕴含了作者追悔之情。\n\n　　全词情景相生。由西风、黄叶，生出自己孤单寂寞和思念亡妻之情；继由思念亡妻之情，生出对亡妻在时的生活片断情景的回忆；最后则由两个生活片断，产生出无穷的遗憾。景情互相生发，互相映衬，一层紧接一层，虽是平常之景之事，却极其典型，生动地表达了作者沉重的哀伤，故能动人。', poem_tags = '悼亡,回忆,爱情,感伤' WHERE poem_title = '浣溪沙·谁念西风独自凉' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '太行、王屋两座山，方圆七百里，高七八千丈，本来在冀州南边，黄河北岸的北边。\n\n　　北山下面有个名叫愚公的人，年纪快到90岁了，在山的正对面居住。他苦于山区北部的阻塞，出来进去都要绕道，就召集全家人商量说：“我跟你们尽力挖平险峻的大山，（使道路）一直通到豫州南部，到达汉水南岸，好吗？”大家纷纷表示赞同。他的妻子提出疑问说：“凭你的力气，连魁父这座小山都不能削平，能把太行、王屋怎么样呢？再说，往哪儿搁挖下来的土和石头？”众人说：“把它扔到渤海的边上，隐土的北边。”于是愚公率领儿孙中能挑担子的三个人（上了山），凿石头，挖土，用箕畚运到渤海边上。邻居京城氏的寡妇有个孤儿，刚七八岁，蹦蹦跳跳地去帮助他。冬夏换季，才能往返一次。\n\n　　河湾上的智叟讥笑愚公，阻止他干这件事，说：“你简直太愚蠢了！就凭你残余的岁月、剩下的力气连山上的一棵草都动不了，又能把泥土石头怎么样呢？”北山愚公长叹说：“你的心真顽固，顽固得没法开窍，连孤儿寡妇都比不上。即使我死了，还有儿子在呀；儿子又生孙子，孙子又生儿子；儿子又有儿子，儿子又有孙子；子子孙孙无穷无尽，可是山却不会增高加大，还怕挖不平吗？”河曲智叟无话可答。\n\n　　握着蛇的山神听说了这件事，怕他没完没了地挖下去，向天帝报告了。天帝被愚公的诚心感动，命令大力神夸娥氏的两个儿子背走了那两座山，一座放在朔方的东部，一座放在雍州的南部。从这时开始，冀州的南部直到汉水南岸，再也没有高山阻隔了。', poem_notes = '太行山：在黄土高原和华北平原之间。\n王屋山：在山西阳城、垣曲与河南济源之间。\n方：指面积。\n仞：古代长度单位，以七尺或八尺为一仞。\n冀州：古地名，包括现在河北省，山西省，河南省黄河以北，辽宁省辽河以西的地区。\n河阳：黄河北岸。山的北面和江河的南面叫做阴，山的南面和江河的北面叫做阳。\n且：副词，将近。\n面山而居：面对着山居住。\n惩（chéng）：戒，这里是“苦于、为......所苦”的意思。\n塞（sè）：阻塞。\n迂（yū）：曲折、绕远。\n聚室而谋：集合全家来商量。室，家。\n汝：你。这里做复数看，为“你们”的意思。\n毕力平险：尽全力铲除险峻的大山。\n指通豫南：一直通向豫州的南部。指，直。豫州，古地名，在今河南省黄河以南。\n汉阴：汉，就是汉水；阴，山的北面或水的南面叫阴。\n献疑：提出疑问。\n以：凭借。\n杂然相许：纷纷表示赞成。杂然，纷纷的样子。许，赞同。\n损：：削减。\n曾（céng）：副词，加强否定语气，可译为“连……也……”，常与“不”连用。\n魁父：古代一座小山的名称，在现今河南省开封县陈留镇境内。魁（kuí）。\n丘：土堆。\n置：安放。\n且：况且。\n焉：疑问代词，哪里。\n荷（hè）：扛的意思。\n夫：成年男子。\n箕畚（jī běn）簸箕，一种用竹片或柳条编成的器具。这里是用箕畚装土石的意思。\n孀（shuāng） ：孀妻，寡妇。\n遗男：遗孤，单亲孤儿，遗腹子。\n龀（chèn）：儿童换牙齿，乳齿脱落后重新长恒齿。这里始龀表示年龄，约七八岁。龀，换牙。\n寒暑易节：冬夏换季，指一年的时间。易，交换。节，季节。\n始一反焉：才往返一次。反，通“返”往返。焉，语气助词。\n河曲：古地名，在今山西省芮城县西。\n叟（sǒu）：老头。\n惠：同“慧”，聪明；不惠，指愚蠢。\n其：在“如……何”前面加强反问语气。\n长息：长叹。\n一毛：一草一木，地面所生的草木，这里指山的一小部分。\n汝心之固，固不可彻：你思想顽固，顽固到了不可改变的地步。彻，通。\n匮（kuì）：竭尽的意思。\n虽我之死：即使我死了。虽，即使。之，用在主谓之间，无实意。\n苦：愁。\n亡（wú）以应：没有话来回答。亡，通“无”。\n操蛇之神：神话中的山神，手里拿着蛇，所以叫操蛇之神。操，持。\n惧其不已：怕他不停地干下去。其，愚公。已，停止。\n帝：神话中的天帝。\n感其诚：被他的诚心所感动。感，被……感动。\n夸娥氏：神话中力气很大的神。\n负：背。\n厝（cuò）：同“措”，放置。\n朔东：就是朔方以东地区，指山西省的东部。\n雍：就是雍州，在现今陕西、甘肃省一带地区。\n陇断：即垄断，山冈高地\n列子：这是一部古书的名称，属于中国先秦时期道家的著作。关于这部书，有两种说法：一种认为是战国初年的列御寇著的；另一种认为是后来晋代的人著的，没有定论。书中记载了许多寓言和传说故事。', poem_appreciation = '愚公移山的故事发生在王屋山，王屋山上有王屋乡，王屋乡里有愚公村，而愚公村便是传说中愚公的故乡。 　出济源市区，西行35公里便是王屋乡。\n\n　　沿济邵(邵原镇为济源市最西的一个镇)公路西行，王屋山的俊秀挺拔与山势陡峭尽入眼中，不由得感慨王屋乡之偏远及王屋乡人出行的诸多不便，由此更明白老愚公在年且九十之际，扣石垦壤，要移走太行、王屋二山愿望之迫切。\n\n　　眼前的济邵公路，双向两车道，虽随山势变化而曲折弯转，但路面十分平坦。一路西行，公路两边的防护林连绵不断，风景秀丽。\n\n　　同行的赵公文不断感慨，感叹这条道路的贯通给愚公后人带来的巨大变化。\n\n　　赵公文是济源市记者协会秘书长，老家在济源市西的邵原镇，距市区55公里，他对济邵公路开通前后山区的变化感受最深：“我1986年离开邵原镇，在这之前，从邵原镇到市区只有一条弯弯曲曲的山路，我父亲那时候是村支书，每次到县里开会都要在山上走100多里。村民养些猪、羊也卖不出去，贫穷落后是自然的。”\n\n　　1987年，济邵公路修成。1997年、2000年，济邵公路两次大修，扩整路面，济源西部的几个乡镇彻底告别了交通闭塞的落后状况。 　40分钟后，汽车停靠在王屋乡愚公村村口。正对村口的是愚公移山纪念广场，广场高高的平台上立着巨大的愚公移山群雕，老愚公左手叉腰，右肩荷锄，正对着愚公村村口蜿蜒而来的柏油公路。\n\n　　相隔两千年后，愚公出山的梦终于圆了。\n\n　　愚公移山，若是象征性地去理解，把山比喻为毒瘤般的人事物的话，则值得学习其精神，否则不敢苟同了。愚公移山，从头到尾就是表现了愚公的愚不可及以及不听智叟的劝说而进行的一番巧辩罢了。大自然有其天地之造化，人力亦有圆润之道可以为之。人生短暂如蜉蝣一瞬，面对一些情况实是可以绕道而行，或迁移便可。比如愚公以及乡民，生在大山之中，本身就不便于交通行走，在这个情况下完全可以举村而迁，住到大山外面的平坦之地岂不是更好，这样既省力又省时，而且没有破坏自然，这何其不是智者之道？把宝贵的时间让自己与子孙都浪费在移山之中，岂不是莫大的悲哀？好在现在的政策是有“移民”一说，没有生搬硬套。', poem_tags = '初中文言文,寓言,故事' WHERE poem_title = '愚公移山' AND poem_author = '列御寇';
UPDATE edu_poem SET poem_translation = '靠近边境一带居住的人中有一个精通术数的人，他们家的马无缘无故跑到了胡人的住地。人们都前来慰问他。那个老人说：“这怎么就不能是一件好事呢？”过了几个月，那匹马带着胡人的良马回来了。人们都前来祝贺他们一家。那个老人说：“这怎么就不能是一件坏事呢？”他家中有很多好马，他的儿子喜欢骑马，结果从马上掉下来摔得大腿骨折。人们都前来安慰他们一家。那个老人说：“这怎么就不能是一件好事呢？”过了一年，胡人大举入侵边境一带，壮年男子都拿起弓箭去作战。靠近边境一带的人，绝大部分都死了。唯独这个人因为腿瘸的缘故免于征战，父子得以保全生命。', poem_notes = '塞上：长城一带\n善术者：精通术数的人。术，术数，推测人事吉凶祸福的法术，如看相，占卜等，这是迷信活动。\n亡：逃跑\n吊：对其不幸表示安慰。\n何遽（jù）：怎么就，表示反问。\n居：经过\n将：带领\n富：多\n髀：（bì）大腿', poem_appreciation = '《塞翁失马》通过一个循环往复的极富戏剧性故事，阐述了祸与福的对立统一关系，揭示了“祸兮福所倚，福兮祸所伏”的道理。如果单从哲学角度去看，这则寓言启发人们用发展的眼光辩证地去看问题：身处逆境不消沉，树立“柳暗花明”的乐观信念；身处顺境不迷醉，保持“死于安乐”的忧患意识。\n\n　　从寓言本身包含的思想倾向来看，存在与主流思想不和谐的因素：“居一年，胡人大入塞，丁壮者引弦而战。近塞之人，死者十九。此独以跛之故，父子相保。”胡人大举入侵，国难当头，青壮年都拿起武器去打仗了，而且有那么多的人在战场上献出了宝贵的生命，足见战争之惨烈。在这种严峻的形势下，“善术者”父子没有尽匹夫之责，倒是“以跛之故”保全了性命。\n\n　　问题不在于“父子”是否上战场，毕竟年老和腿瘸的客观现实给了他们没上战场的理由。问题的关键是作者把“父子”因为没有上战场而保全了性命当做了莫大的“福”分，并为之而庆幸。这与培养爱国主义感情、道德品质，逐步形成积极的人生态度和正确的价值观”的要求很不一致。\n\n　　国家有难，匹夫有责。“善术者”因为腿被摔瘸了而没有为国尽力，理当感到遗憾甚至惭愧，特别是在有那么多战死者的情况下，作为苟活者，应该感到内疚甚至耻辱才是。但“父子”没有，他们只是庆幸，庆幸“堕而折其髀”的灾祸，庆幸逃脱了去战场捐躯”，庆幸继续活下去的福气。\n\n　　这里没办法去讨论战争的正义与否，毕竟只是一则寓言，是为了诠释一个道理而演绎的故事。如果单从祸福相互转化的关系去看，对这则寓言不能有什么非议。但既然选入了中国的学生教材，就应该特别在乎是否有“积极的人生态度和正确的价值观”了。\n\n　　在一定的条件下，好事和坏事是可以互相转换的，坏事可以变成好事，好事可以变成坏事。“塞翁失马”的故事在民间流传了千百年。无论遇到福还是祸，要调整自己的心态，要超越时间和空间去观察问题，要考虑到事物有可能出现的极端变化。', poem_tags = '初中文言文,哲理,故事' WHERE poem_title = '塞翁失马' AND poem_author = '刘安';
UPDATE edu_poem SET poem_translation = '去年正月十五元宵节，花市灯光像白天一样明亮。\n月儿升起在柳树梢头，他约我黄昏以后同叙衷肠。\n今年正月十五元宵节，月光与灯光仍同去年一样。\n再也看不到去年的故人，泪珠儿不觉湿透了衣裳。', poem_notes = '元夜：元宵之夜。农历正月十五为元宵节。自唐朝起有观灯闹夜的民间风俗。北宋时从十四到十六三天，开宵禁，游灯街花市，通宵歌舞，盛况空前，也是年轻人蜜约幽会，谈情说爱的好机会。\n花市：民俗每年春时举行的卖花、赏花的集市。\n灯如昼：灯火像白天一样。\n月上：一作“月到”。\n见：看见。\n泪湿：一作“泪满”。\n春衫：年少时穿的衣服，也指代年轻时的自己。', poem_appreciation = '明代徐士俊认为，元曲中“称绝”的作品，都是仿效此作而来，可见其对这首《生查子》的赞誉之高。此词言语浅近，情调哀婉，用“去年元夜”与“今年元夜”两幅元夜图景，展现相同节日里的不同情思，仿佛影视中的蒙太奇效果，将不同时空的场景贯穿起来，写出一位女子悲戚的爱情故事。\n\n　　上阌描绘“去年元夜时”女主人公与情郎同逛灯市的欢乐情景。“去年元夜时，花市灯如昼。”起首两句写去年元宵夜的盛况美景，大街上热闹非凡，夜晚的花灯通明，仿佛白昼般明亮。“月上柳梢头，人约黄昏后”，女主人公追忆与情郎月下约定的甜蜜情景，情人间互诉衷情的温馨幸福溢于纸上。从如昼灯市到月上柳梢，光线从明变暗，两人约定的时间又是“黄昏”这一落日西斜、素来惹人愁思的时刻，皆暗示女主人公的情感故事会朝着悲剧发展。\n\n　　下阕写“今年元夜时”女主人公孤独一人面对圆月花灯的情景。“今年元夜时，月与灯依旧。”一年过去，眼前的景象与去年没有两样，圆月仍然高挂夜空，花灯仍然明亮如昼，但是去年甜蜜幸福的时光已然不再，女主人公心里只有无限相思之苦。之所以伤感，是因为“不见去年人”，往日的山盟海誓早已被恋人抛诸脑后，如今物是人非，不禁悲上心头。令人肝肠寸断的相思化作行行清泪、浸湿衣衫。“泪满春衫袖”一句是点题句，将女主人公的情绪完全宣泄出来，饱含辛酸蕴藏无奈，更有无边无际的苦痛。\n\n　　此词的艺术构思近似于唐人崔护的《题都城南庄》诗，却较崔诗更见语言的回环错综之美，也更具民歌风味。全词在字句上讲求匀称一致，有意错综穿插，它用上阕写过去，下阕写现在，上四句与下四句分别提供不同的意象以造成强烈的对比。上下阕的第一句“去年元夜时”与“今年元夜时”，第二句“花市灯如昼”与“月与灯依旧”，两两相对，把“元夜”“灯”作了强调；而“人约黄昏后”与“不见去年人”，则是上阕第四句与下阕第三句交叉相对，虽是重叠了“人”字，却从参差错落中显示了“人”的有无、去留的天差地别及感情上由欢愉转入忧伤的大起大落，从而表现了抒情主人公内心的起伏变化。\n\n　　词作通过主人公对去年今日的往事回忆，抒写了物是人非之感。既写出了伊人的美丽和当日相恋的温馨甜蜜，又写出了今日伊人不见的怅惘和忧伤。词的语言通俗，构思巧妙，上片写去年，下片写今日，重叠对应，回旋咏叹，具有明快、自然的民歌风味。结尾“泪满春衫袖”一句，则通过描写将物是人非、旧情难续的感伤表现得十分充分。全词以独特的艺术构思，运用今昔对比、抚今追昔的手法，从而巧妙地抒写了物是人非、不堪凹首之感。语言平淡，意味隽永，有效地表达了词人所欲吐露的爱情遭遇上的伤感和苦痛体验，体现了真实、朴素与美的统一。语短情长，形象生动，又适于记诵，因此流传限广。', poem_tags = '宋词三百首,宋词精选,婉约,元宵节,追忆,爱情,思念' WHERE poem_title = '生查子·元夕' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '黄师塔前那一江的碧波春水滚滚向东流，春天给人一种困倦让人想倚着春风小憩的感觉。\n江畔盛开的那一簇无主的桃花映入眼帘，究竟是爱深红色的还是更爱浅红色的呢？', poem_notes = '江畔：指成都锦江之滨。\n独步：独自散步。\n塔：墓地。\n一簇：一丛，无主--没有主人。', poem_tags = '写景,赏花,桃花' WHERE poem_title = '江畔独步寻花·其五' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '大清早我走进这古老寺院，旭日初升映照着山上树林。\n竹林掩映小路通向幽深处，禅房前后花木繁茂又缤纷。\n山光明媚使飞鸟更加欢悦，潭水清澈也令人爽神净心。\n此时此刻万物都沉默静寂，只留下了敲钟击磬的声音。', poem_notes = '破山寺：即兴福寺，在今江苏常熟市西北虞山上。南朝齐邑人郴州刺史倪德光舍宅所建。\n清晨：早晨。入：进入。古寺：指破山寺。\n初日：早上的太阳。照：照耀。高林：高树之林。\n竹径：一作“曲径”，又作“一径”。通：一作“遇”。幽：幽静。\n禅房：僧人居住修行的地方。\n悦：此处为使动用法，使……高兴。\n潭影：清澈潭水中的倒影。空：此处为使动用法，使……空。此句意思是，潭水空明清澈，临潭照影，令人俗念全消。\n万籁（lài）：各种声音。籁，从孔穴里发出的声音，泛指声音。此：在此，即在后禅院。都：一作“俱”。\n但余：只留下。一作“惟余”，又作“唯闻”。钟磬（qìng）：佛寺中召集众僧的打击乐器。磬，古代用玉或金属制成的曲尺形的打击乐器。', poem_tags = '唐诗三百首,初中古诗,写景,咏物' WHERE poem_title = '题破山寺后禅院' AND poem_author = '常建';
UPDATE edu_poem SET poem_translation = '一树树梅子变得金黄，杏子也越长越大了；荞麦花一片雪白，油菜花倒显得稀稀落落。\n白天长了，篱笆的影子随着太阳的升高变得越来越短，没有人经过；只有蜻蜓和蝴蝶绕着篱笆飞来飞去。', poem_notes = '篱落：篱笆。', poem_tags = '田园,写景,劳作' WHERE poem_title = '四时田园杂兴·其二' AND poem_author = '范成大';
UPDATE edu_poem SET poem_translation = '傍晚时分站在东皋纵目远望，我徘徊不定不知该归依何方，\n层层树林都染上秋天的色彩，重重山岭披覆着落日的余光。\n牧人驱赶着那牛群返还家园，猎人带着猎物驰过我的身旁。\n大家相对无言彼此互不相识，我长啸高歌真想隐居在山冈！', poem_notes = '东皋（gāo）：诗人隐居的地方。薄暮：傍晚。薄，迫近。\n徙倚（xǐyǐ）：徘徊，来回地走。依：归依。\n秋色：一作“春色”。\n落晖：落日。\n犊（dú）：小牛，这里指牛群。\n禽：鸟兽，这里指猎物。\n采薇：薇，是一种植物。相传周武王灭商后 ，伯夷、叔齐不愿做周的臣子，在首阳山上采薇而食，最后饿死。古时“采薇”代指隐居生活。', poem_appreciation = '这是一首描写秋天山野景致的五言律诗。诗风疏朴自然，于平淡中表现出诗人“相顾无相识“的抑郁苦闷的心情，同齐梁以来绮靡浮艳的文学风习大异其趣。全诗洗尽铅华，为唐初诗苑吹进一股清新的气息，是王绩的代表作之一。\n\n　　“东皋薄暮望，徙倚欲何依。“首二句以抒写情性为主。“东皋“，泛指王绩家乡绛州龙门附近的水边高地，借用陶渊明(归去来辞)“登东皋以舒啸“的诗句，暗含诗人归隐之后，尝耕东皋之意，故而自号“东皋子“。“徙倚“，是徘徊的意思。“欲何依“，化用曹操《短歌行》“绕树三匝，何枝可依“的诗句。这两句诗以平平淡淡的叙述，首先推出薄薄暮色之中，诗人兀立在东皋之上，举目四望，一种莫可明状的孤寂无依的愁绪涌上心头，使之无法平静下来，以此观景自然会涂上一层心理上的不平衡色彩，并为中间四句写景提供巧妙的铺垫。\n\n　　“树树皆秋色，山山唯落晖“。这是诗人对眼前景观的粗线条的描绘，着重于色彩的透明度，层层树林已染上萧瑟的金黄的秋色，起伏的山峦惟见落日的余晖，这是多么宁静、开阔、美丽的画面。纵使在淡淡的暮霭之中，人们还是能够感觉到山野间秋林、落晖的光与色的强烈辉映。接着，诗人的笔锋又转向动的叙写:“牧人驱犊返。猎马带禽归。“着力刻划视野所见山野放归的生动场景，为整个静谧的画面，注进一股跳动的情致和欣然的意趣。句中的几个动词“驱“、“返“、“带“、“归“。用得自然而精警。这种动态式的描写愈发衬托出秋日晚景的安详宁静，诗人于一静一动的描写之中，把山山树树、牛犊猎马交织成一幅绝妙的艺术画卷。光线与色彩的调和，远景与近景的搭配，都显得那么白然和谐，令人不能不产生某种遐想，甚至忘情在安逸闲适的田野之中。\n\n　　可是，身临其境的王绩，他的感受远不能象田园诗人那样得到精神上的慰藉，油然而生的却是某种茫然若失、孤独无依的情绪。“相顾无相识，长歌怀采薇“。这最后两句完全道出诗人内心的苦闷和怅惘，既然在现实中找不到相知相识的朋友，那就只好追怀伯夷、叔齐那样不食周粟、上山釆薇的隐逸之士。有人评曰:“读《野望》篇，固知高士胸襟，超然物外，一腔隐情。千古自有知己。“((删补唐诗选脉笺释会通评林》)正深得本诗的主旨。\n\n　　本诗首尾两联抒情言事。中间两联写景，经过以情写景、借景言情的层层深化描写，把诗人的孤寂彷徨之情与笼罩四野的秋色暮景巧妙的联结起来，给读者带来直觉的艺术观感和美的愉悦。诗中所蕴含的不尽之意，更使人们长久地咀嚼、回味。全诗语言质直清新，自然流畅，言浅味深，句句有力，为唐诗及后代诗歌语言的创新开辟先路。', poem_tags = '初中古诗,秋天,写景,抒情' WHERE poem_title = '野望' AND poem_author = '王绩';
UPDATE edu_poem SET poem_translation = '每天三更半夜到鸡啼叫的时候，是男孩子们读书的最好时间。\n少年时只知道玩，不知道要好好学习，到老的时候才后悔自己年少时为什么不知道要勤奋学习。', poem_notes = '更：古时夜间计算时间的单位，一夜分五更，每更为两小时。午夜11点到1点为三更。\n五更鸡：天快亮时，鸡啼叫。\n黑发：年少时期，指少年。\n白首：头发白了，这里指老年。方：才。', poem_appreciation = '《劝学》中的“劝”起着统领全篇的作用。“劝”解释为“勉励”的意思。作者在这篇以《劝学》为的诗歌中，勉励人们要不停止地坚持学习，只有这样才能增长知识，发展才能，培养高尚的品德。\n\n　　“三更灯火五更鸡”是指勤劳的人、勤奋学习的学生在三更半夜时还在工作、学习，三更时灯还亮着，熄灯躺下稍稍歇息不久，五更的鸡就叫了，这些勤劳的人又得起床忙碌开了。第一句用客观现象写时间早，引出第二句学习要勤奋，要早起。第二句为第一句作补充，表达了年少学习时应该不分昼夜学习，通过努力学习才能报家报国，建功立业。\n\n　　第三、四句写的是年轻的时候不好好学习到了年纪大了，在想要学习也晚了。句子中“黑发”，“白首”是采用借代的修辞方法，借指青年和老年。通过对比的手法，突出读书学习要趁早，不要到了老了后悔了才去学习。从结构上看，三、四句为对偶句，“黑发”与“白首”前后呼应，互相映衬，给读者留下深刻的印象。\n\n　　这首诗深入浅出，自然流畅，富含哲理。核心是“黑发早勤学，白首读书迟”。作为有志气的人，要注意抓紧时间读书学习修身养性，最好的读书时间是在三更五更，晨读不息；而且只有年年月月刻苦坚持，才能真正学到报国兴家立业的本领。从学习的时间这一角度立意，劝勉年轻人不要虚度光阴，要及早努力学习，免得将来后悔。诗人是从学习的意义，作用和学习应持的态度方法等角度立意，希望人们重视后天学习，以加强自身的行为修养。', poem_tags = '励志,惜时,读书,哲理,早教古诗100首' WHERE poem_title = '劝学' AND poem_author = '颜真卿';
UPDATE edu_poem SET poem_translation = '茅草房庭院经常打扫，洁净得没有一丝青苔。花草树木成行成垄，都是主人亲手栽种。\n庭院外一条小河保护着农田，并且环绕着农田；两座大山打开门来为人们送去绿色。\n\n桑树枝叶繁茂，楝花也十分繁盛。清风吹送楝花余香，悄悄地送过墙头。 \n黄莺几声清脆的啼叫 ，惊醒了我的午觉。一梦醒来，我恍恍惚惚还觉得自己好像仍然在旧日所住的半山园中。', poem_notes = '书：书写，题诗。湖阴先生：本名杨德逢，隐居之士，是王安石晚年居住金陵紫金山（今江苏南京）时的邻居。\n茅檐：茅屋檐下，这里指庭院。无苔：没有青苔。\n成畦（qí ）：成垄成行。 畦：经过修整的一块块田地。\n护田：这里指护卫环绕着园田。⑸排闼（tà）：开门。闼：小门。送青来：送来绿色。\n楝(liàn)花：“二十四番花信”里的楝花，指的就是北方常见的苦楝花。', poem_appreciation = '这两首诗是题写在湖阴先生家屋壁上的，其中第一首很著名。这一首诗用典十分精妙，读者不知典故内容，并不妨碍对诗歌大意的理解；而诗歌的深意妙趣，则需要明白典故的出处才能更深刻地体会。\n\n　　首二句赞美杨家庭院的清幽。“茅檐”代指庭院。“静”即净。怎样写净呢？诗人摒绝一切平泛的描绘，而仅用“无苔”二字，举重若轻，真可谓别具只眼。何以见得？江南地湿，又时值初夏多雨季节，这对青苔的生长比之其他时令都更为有利。况且，青苔性喜阴暗，总是生长在僻静之处，较之其他杂草更难于扫除。而今庭院之内，连青苔也没有，不正表明无处不净、无时不净吗?在这里，平淡无奇的形象由于恰当的用字却具有了异常丰富的表现力。“花木”是庭院内最引人注目的景物。因为品种繁多，所以要分畦栽种。这样，“成畦”二字就并非仅仅交代花圃的整齐，也有力地暗示出花木的丰美，既整齐又不单调。\n\n　　这清幽环境令人陶醉，所以当诗人的目光从院内花木移向院外的山水时，他的思致才会那样悠远、飘逸，才会孕育出下面一联的警句，门前的景物是一条河流，一片农田，两座青山，在诗人眼里，山水对这位志趣高洁的主人也有情谊。诗人用拟人手法，将“一水”“两山”写成富有人情的亲切形象。弯弯的河流环绕着葱绿的农田，正像母亲用双手护着孩子一样。“护”字，“绕”字显得那么有情。门前的青山见到庭院这样整洁，主人这样爱美，也争相前来为主人的院落增色添彩：推门而入，奉献上一片青翠。诗人以神来之笔，留下千古传诵的名句。\n\n　　“一水”“两山”被转化为富于生命感情的亲切的形象，而为千古传诵。但后二句所以广泛传诵，主要还在于这样两点：一、拟人和描写浑然一体，交融无间。“一水护田”加以“绕”字，正见得那小溪曲折生姿，环绕着绿油油的农田，这不恰像一位母亲双手护着小孩的情景吗?著一“护”字，“绕”的神情明确显示。至于“送青”之前冠以“排闼”二字，更是神来之笔。它既写出了山色不只是深翠欲滴，也不只是可掬，而竟似扑向庭院而来!这种描写给予读者的美感极为新鲜、生动。它还表明山的距离不远，就在杨家庭院的门前，所以似乎伸手可及。尤其动人的，是写出了山势若奔，仿佛刚从远方匆匆来到，兴奋而热烈。所有这些都把握住了景物的特征，而这种种描写，又都和充分的拟人化结合起来那情调、那笔致，完全像在表现“有朋自远方来”的情景：情急心切，竟顾不得敲门就闯进庭院送上礼物。二者融合无间，相映生色，既奇崛又自然，既经锤炼又无斧凿之痕，清新隽永，韵味深长。二、这两句诗也与杨德逢的形象吻合。在前联里，已可看到一个人品高洁、富于生活情趣的湖阴先生。所居仅为“茅檐”，他不仅“扫”，而且“长扫”（即常扫），以至于“静无苔”；“花木成畦”，非赖他人，而是亲“手自栽”。可见他清静脱俗，朴实勤劳。这样一位高士，徜徉于山水之间，当然比别人更能欣赏到它们的美，更感到“一水”“两山”的亲近；诗人想象山水有情，和湖阴先生早已缔结了深厚的交谊。诗以“书湖阴先生壁”为题，处处关合，处处照应，由此也可见出诗人思致的绵密。 此诗对于“一水”“两山”的拟人化，既以自然景物的特征为基础，又与具体的生活内容相吻合，所以气足神完，浑化无迹，成为古今传诵的名句。\n\n　　在修辞技巧上，“一水护田将绿绕，两山排闼送青来”两句也堪作范例。诗人运用了对偶的句式，又采用了拟人的手法，给山水赋予人的感情，化静为动，显得自然化境既生机勃勃又清静幽雅。', poem_tags = '写景,写人,典故' WHERE poem_title = '书湖阴先生壁' AND poem_author = '王安石';
UPDATE edu_poem SET poem_translation = '云收雨停，雨过天晴，水面增高并增添了波澜，远处高楼显得比平时更高了，水让人感觉到比平时更凉爽了，雨后的瓜也似乎显得比平时更甜了，绿树的树阴一直遮到画檐。纱帐中的藤席上，有一个芳龄女孩，身着轻绢夏衣，手执罗扇，静静地享受着宜人的夏日时光。', poem_notes = '越调：宫调名。天净沙：曲牌名，入越调。\n画檐：有画饰的屋檐。\n纱厨：用纱做成的帐子。簟（diàn）：竹席，苇席。\n缣（jiān)：细的丝绢。', poem_tags = '夏天,写景,写人' WHERE poem_title = '天净沙·夏' AND poem_author = '白朴';
UPDATE edu_poem SET poem_translation = '弃我而去的昨日，早已不可挽留。\n乱我心思的今日，令人烦忧多多。\n万里长风，送走行行秋雁。面对美景，正可酣饮高楼。\n先生的文章正有建安风骨，又不时流露出小谢诗风的清秀。\n你我满怀超宜兴致，想上青天揽住明月。\n抽刀切断水流，水波奔流更畅；举杯想要销愁，愁思更加浓烈。\n人生在世，无法称心如意，不如披头散发，登上长江一叶扁舟。', poem_notes = '此诗《文苑英华》题作《陪侍御叔华登楼歌》，则所别者为李云（官秘书省校书郎)，李华(文学家)。李白另有五言诗《饯校书叔云》，作于某春季，且无登楼事，与此诗无涉。宣州：今安徽宣城一带。谢朓（tiǎo）楼：又名北楼、谢公楼，在陵阳山上，谢朓任宣城太守时所建，并改名为叠嶂楼。饯别：以酒食送行。校（jiào）书：官名，即秘书省校书郎，掌管朝廷的图书整理工作。叔云：李白的叔叔李云。\n长风：远风，大风。\n此：指上句的长风秋雁的景色。酣（hān）高楼：畅饮于高楼。\n蓬莱：此指东汉时藏书之东观。《后汉书》卷二三《窦融列传》附窦章传：“是时学者称东观为老氏藏室，道家蓬莱山”。李贤注：“言东观经籍多也。蓬莱，海中神山，为仙府，幽经秘籍并皆在也。”蓬莱文章：借指李云的文章。建安骨：汉末建安（汉献帝年号，196—220）年间，“三曹”和“七子”等作家所作之诗风骨遒上，后人称之为“建安风骨”。\n小谢：指谢朓，字玄晖，南朝齐诗人。后人将他和谢灵运并称为大谢、小谢。这里用以自喻。清发（fā）：指清新秀发的诗风。发：秀发，诗文俊逸。\n俱怀：两人都怀有。逸兴（xìng）：飘逸豪放的兴致，多指山水游兴，超远的意兴。王勃《滕王阁序》：“遥襟甫畅，逸兴遄飞”。李白《送贺宾客归越》：“镜湖流水漾清波，狂客归舟逸兴多。”壮思飞：卢思道《卢记室诔》：“丽词泉涌，壮思云飞。”壮思：雄心壮志，豪壮的意思。\n览：通“揽”，摘取。览明月：《唐诗鉴赏辞典》（上海辞书出版社1983年版）作“揽明月”。另一版本为揽。\n销：另一版本为“消”。。\n称（chèn）意：称心如意。\n明朝（zhāo）：明天。散发（fà）：不束冠，意谓不做官。这里是形容狂放不羁。古人束发戴冠，散发表示闲适自在。弄扁（piān）舟：乘小舟归隐江湖。扁舟：小舟，小船。春秋末年，范蠡辞别越王勾践，“乘扁舟浮于江湖”（《史记·货殖列传》）。', poem_appreciation = '这是一首饯别抒怀诗。在诗中，诗人感怀万端，既满怀豪情逸兴，又时时掩抑不住郁闷与不平，感情回复跌宕，一波三折，表达了自己遗世高蹈的豪迈情怀。\n\n　　此诗发端既不写楼，更不叙别，而是陡起壁立，直抒郁结。“昨日之日”与“今日之日”，是指许许多多个弃我而去的“昨日”和接踵而至的“今日”。也就是说，每一天都深感日月不居，时光难驻，心烦意乱，忧愤郁悒。这里既蕴含了“功业莫从就，岁光屡奔迫”的精神苦闷，也融铸着诗人对污浊的政治现实的感受。他的“烦忧”既不自“今日”始，他所“烦忧”者也非止一端。不妨说，这是对他长期以来政治遭遇和政治感受的一个艺术概括。忧愤之深广、强烈，正反映出天宝以来朝政的愈趋腐败和李白个人遭遇的愈趋困窘。理想与现实的尖锐矛盾所引起的强烈精神苦闷，在这里找到了适合的表现形式。破空而来的发端，重叠复沓的语言（既说“弃我去”，又说“不可留”；既言“乱我心”，又称“多烦忧”），以及一气鼓荡、长达十一字的句式，都极生动形象地显示出诗人郁结之深、忧愤之烈、心绪之乱，以及一触即发、发则不可抑止的感情状态。\n\n　　三四两句突作转折：而对着寥廓明净的秋空，遥望万里长风吹送鸿雁的壮美景色，不由得激起酣饮高楼的豪情逸兴。这两句在读者面前展现出一幅壮阔明朗的万里秋空画图，也展示出诗人豪迈阔大的胸襟。从极端苦闷忽然转到朗爽壮阔的境界，仿佛变化无端，不可思议。但这正是李白之所以为李白。正因为他素怀远大的理想抱负，又长期为黑暗污浊的环境所压抑，所以时刻都向往着广大的可以自由驰骋的空间。目接“长风万里送秋雁”之境，不觉精神为之一爽，烦忧为之一扫，感到一种心、境契合的舒畅，“酣饮高楼”的豪情逸兴也就油然而生了。\n\n　　下两句承高楼饯别分写主客双方。东汉时学者称东观（政府的藏书机构）为道家蓬莱山，唐人又多以蓬山，蓬阁指秘书省，李云是秘书省校书郎，所以这里用“蓬莱文章”借指李云的文章。建安骨，指刚健遒劲的“建安风骨”。上句赞美李云的文章风格刚健，下句则以“小谢”（即谢朓）自指，说自己的诗像谢朓那样，具有清新秀发的风格。李白非常推崇谢朓，这里自比小谢，正流露出对自己才能的自信。这两句自然地关合了题目中的谢朓楼和校书。\n\n　　七、八两句就“酣高楼”进一步渲染双方的意兴，说彼此都怀有豪情逸兴、雄心壮志，酒酣兴发，更是飘然欲飞，想登上青天揽取明月。前面方写晴昼秋空，这里却说到“明月”，可见后者当非实景。“欲上”云云，也说明这是诗人酒酣兴发时的豪语。豪放与天真，在这里得到了和谐的统一。这正是李白的性格。上天揽月，固然是一时兴到之语，未必有所寓托，但这飞动健举的形象却让读者分明感觉到诗人对高洁理想境界的向往追求。这两句笔酣墨饱，淋漓尽致，把面对“长风万里送秋雁”的境界所激起的昂扬情绪推向最高潮，仿佛现实中一切黑暗污浊都已一扫而光，心头的一切烦忧都已丢到了九霄云外。\n\n　　然而诗人的精神尽管可以在幻想中遨游驰骋，诗人的身体却始终被羁束在污浊的现实之中。现实中并不存在“长风万里送秋雁”这种可以自由飞翔的天地，他所看到的只是“夷羊满中野，菉葹盈高门这种可憎的局面。因此，当他从幻想中回到实里，就更强烈地感到了理想与现实的矛盾不可调和，更加重了内心的烦忧苦闷。“抽刀断水水更流，举杯销愁愁更愁”，这一落千丈的又一大转折，正是在这种情况下必然出现的。“抽刀断水水更流”的比喻是奇特而富于独创性的，同时又是自然贴切而富于生活气息的。谢朓楼前，就是终年长流的宛溪水，不尽的流水与无穷的烦忧之间本就极易产生联想，因而很自然地由排遣烦忧的强烈愿望中引发出“抽刀断水”的意念。由于比喻和眼前景的联系密切，从而使它多少具有“兴”的意味，读来便感到自然天成。尽管内心的苦闷无法排遣，但“抽刀断水”这个细节却生动地显示出诗人力图摆脱精神苦闷的要求，这就和沉溺于苦闷而不能自拔者有明显区别。\n\n　　“人生在世不称意，明朝散发弄扁舟。”李白的进步理想与黑暗现实的矛盾，在当时历史条件下，是无法解决的，因此，他总是陷于“不称意”的苦闷中，而且只能找到“散发弄扁舟”这样一条摆脱苦闷的出路。这结论当然不免有些消极，甚至包含着逃避现实的成分。但历史与他所代表的社会阶层都规定了他不可能找到更好的出路。\n\n　　李白的可贵之处在于，尽管他精神上经受着苦闷的重压，但并没有因此放弃对进步理想的追求。诗中仍然贯注豪迈慷慨的情怀。“长风”二句，“俱怀”二句，更象是在悲怆的乐曲中奏出高昂乐观的音调，在黑暗的云层中露出灿烂明丽的霞光。“抽刀”二句，也在抒写强烈苦闷的同时表现出倔强的性格。因此，整首诗给人的感觉不是阴郁绝望，而是忧愤苦闷中显现出豪迈雄放的气概。这说明诗人既不屈服于环境的压抑，也不屈服于内心的重压。\n\n　　思想感情的瞬息万变，波澜迭起，和艺术结构的腾挪跌宕，跳跃发展，在这首诗里被完美地统一起来了。诗一开头就平地突起波澜，揭示出郁积已久的强烈精神苦闷；紧接着却完全撇开“烦忧”，放眼万里秋空，从“酣高楼”的豪兴到“揽明月”的壮举，扶摇直上九霄，然后却又迅即从九霄跌入苦闷的深渊。直起直落，大开大合，没有任何承转过渡的痕迹。这种起落无端、断续无迹的结构，最适宜于表现诗人因理想与现实的尖锐矛盾而产生的急遽变化的感情。\n\n　　自然与豪放和谐结合的语言风格，在这首诗里也表现得相当突出。必须有李白那样阔大的胸襟抱负、豪放坦率的性格，又有高度驾驭语言的能力，才能达到豪放与自然和谐统一的境界。这首诗开头两句，简直象散文的语言，但其间却流注着豪放健举的气势。“长风”二句，境界壮阔，气概豪放，语言则高华明朗，仿佛脱口而出。这种自然豪放的语言风格，也是这首诗虽极写烦忧苦闷，却并不阴郁低沉的一个原因。\n\n　　全诗如歌如诉，情感起伏涨落，韵味深长，一波三折，章法腾挪跌宕，起落无端，断续无迹，语言明朗朴素，音调激越高昂，达到了豪放与自然和谐统一的境界。', poem_tags = '唐诗三百首,初中古诗,哲理,离别,抒怀,豪迈' WHERE poem_title = '宣州谢脁楼饯别校书叔云' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '群鸟高飞无影无踪，孤云独去自在悠闲。\n你看我，我看你，彼此之间两不相厌，只有我和眼前的敬亭山了。', poem_notes = '敬亭山：在今安徽宣城市北。\n尽：没有了。\n孤云：陶渊明《咏贫士诗》中有“孤云独无依”的句子。独去闲：独去，独自去。 闲，形容云彩飘来飘去，悠闲自在的样子。孤单的云彩飘来飘去。\n两不厌：指诗人和敬亭山而言。厌：满足。', poem_appreciation = '此诗前两句“众鸟高飞尽，孤云独去闲”，看似写眼前之景，其实，把伤心之感写尽了：天上几只鸟儿高飞远去，直至无影无踪；寥廓的长空还有一片白云，却也不愿停留，慢慢地越飘越远，似乎世间万物都在厌弃诗人。“尽”、“闲”两个字，把读者引入一个“静”的境界：仿佛是在一群山鸟的喧闹声消除之后格外感到清静；在翻滚的厚云消失之后感到特别的清幽平静,尽既有消失的意思，又有慢慢消失在天际的感觉。闲，主要是为了表达闲适的感情，是以孤云的闲适衬托作者心境的闲适。这两个词对“独”有意境上的烘托作用。主要是为了写作者此刻独坐但情意悠然，很符合李白本人的仙道思想。\n\n　　因此，这两句是写“动”见“静”，以“动”衬“静”。这种“静”，正烘托出诗人心灵的孤独和寂寞。这种生动形象的写法，能给读者以联想，并且暗示了诗人在敬亭山游览观望之久，勾画出他“独坐”出神的形象，为下联“相看两不厌”作了铺垫。\n\n　　这两句的意象以“众星拱月”式并置，前句中心词“鸟”是中心意象，加上“飞”字形成一个复合意象，强化动态表现意义。“众鸟”原可以让读者联想到山中闲静宁谧的场景，群鸟儿在空山中婉转鸣啼，有一种格外的逸趣，而眼前，众鸟高飞，离人越来越远，“高”字起到一个拓展空间的作用，抬头仰望，空阔的蓝天上，鸟儿在远走高飞，直至看不见。一个“尽”字，增强了此句的表现力度，表现出李白此时的万般惆怅。后句“云”为中心词，与“去”复合，默默的云也在渐渐飘走。而云并非满天白云，原本就只是“孤云”无伴，偏偏还悠闲地慢慢地飘离。诗人以“闲”写出了孤云的状态，突出了离去的过程，让读者在品味孤云离去的状态时，感知诗人内心的不忍和无奈。\n\n　　“尽”、“闲”两个字，把读者引入一个“静”的境界：仿佛是在一群山鸟的喧闹声消除之后格外感到清静；在薄云离散之后感到特别的清幽平静。它们都似乎有灵性，不愿与诗人为伴，远离诗人而去，只留下一个阔大茫茫的空间，诗人坐在这样的空间之中，更显孤独和渺小。其实，山林的鸟是飞不尽的，云也不会飘游到天外。在诗中，众鸟孤云都离诗人而去，这是诗人情感外射的结果，是诗人有意创造为表现自己的孤独情感的茫茫空间。这种生动形象的写法，能给读者以联想：李白坐在那里已经有一段时间了，他眼看着众鸟、孤云渐渐飞去，众鸟和孤云都离开了敬亭山，只有他自己依旧坐在那里欣赏着它，勾画出他“独坐”出神的形象，为下联“相看两不厌”作了铺垫。\n\n　　三、四两句“相看两不厌，只有敬亭山”用浪漫主义手法，将敬亭山人格化、个性化。尽管鸟飞云去，诗人仍没有回去，也不想回去，他久久地凝望着幽静秀丽的敬亭山，觉得敬亭山似乎也正含情脉脉地看着他自己。他们之间不必说什么话，已达到了感情上的交流。“相看两不厌”表达了诗人与敬亭山之间的深厚感情。“相”、“两”二字同义重复，把诗人与敬亭山紧紧地联系在一起，表现出强烈的感情。同时，“相看”也点出此时此刻唯有“山”和“我”的孤寂情景与“两”字相重，山与人的相依之情油然而生。结句中“只有”两字也是经过锤炼的，更突出诗人对敬亭山的喜爱。“人生得一知己足矣”，鸟飞云去对诗人来说不足挂齿。这两句诗所创造的意境仍然是“静”的，表面看来，是写了诗人与敬亭山相对而视，脉脉含情。实际上，诗人愈是写山的“有情”，愈是表现出人的“无情”；而他那横遭冷遇，寂寞凄凉的处境，也就在这静谧的场面中透露出来了。\n\n　　“众鸟”、“孤云”这种动的意象与“敬亭山”这种静的意象相反并置，时间和空间的维度里仅仅出现了量的变化，而心理的维度却产生着质的变化：有理想、有才能而在政治上遭受压抑的士大夫往往对“逝去”，对“消散”有着特殊的敏感，人事短暂，宇宙永恒，常常是他们不遇时发出的慨叹。诗人引恒久的山为知己，可能是“长安不得见”后，不得已而为之的一种方式了。就算长安招引他，他也不知道自己会不会随“众鸟高飞”而去。\n\n　　诗人笔下，不见敬亭山秀丽的山色、溪水、小桥，并非敬亭山无物可写，因为敬亭山“东临宛溪，南俯城闉，烟市风帆，极目如画”。从诗中来看，无从知晓诗人相对于山的位置，或许是在山顶，或许在空阔地带，然而这些都不重要了。这首诗的写作目的不是赞美景物，而是借景抒情，借此地无言之景，抒内心无奈之情。诗人在被拟人化了的敬亭山中寻到慰藉，似乎少了一点孤独感。然而，恰恰在这里，诗人内心深处的孤独之情被表现得更加突出。人世间的深重的孤独之情，诗人人生悲剧的气氛充溢在整首诗中。全诗似乎全是景语，无一情语，然而，由于景是情所造，因而，虽句句是景，却句句是情，就像王夫之所说，是“情中景，景中情”。', poem_tags = '小学古诗,写景,写山,孤独,无奈' WHERE poem_title = '独坐敬亭山' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '树林间的红花已经凋谢，花开花落，才有几时，实在是去得太匆忙了。也是无可奈何啊，花儿怎么能经得起那凄风寒雨昼夜摧残呢？\n飘落遍地的红花，被雨水淋过，像是美人双颊上的胭脂在和着泪水流淌。花儿和怜花人相互留恋，如醉如痴，什么时候才能再重逢呢？人生从来就是令人怨恨的事情太多，就像那东逝的江水，不休不止，永无尽头。', poem_notes = '相见欢：原为唐教坊曲名，后用为词牌名。又名“乌夜啼”“秋夜月”“上西楼”。三十六字，上片三平韵，下片两仄韵两平韵。　\n谢：凋谢。\n无奈朝来寒雨：一作“常恨朝来寒重”。\n胭脂泪：原指女子的眼泪，女子脸上搽有胭脂，泪水流经脸颊时沾上胭脂的红色，故云。在这里，胭脂是指林花着雨的鲜艳颜色，指代美好的花。\n相留醉：一本作“留人醉”。　\n几时重：何时再度相会。', poem_appreciation = '南唐后主的这种词，都是短幅的小令，况且明白如话，不待讲析，自然易晓。他所“依靠”的，不是粉饰装做，扭捏以为态，雕琢以为工，这些在他都无意为之；所凭的只是一片强烈直爽的情性。其笔亦天然流丽，如不用力，只是随手抒写。这些自属有目共见。但如以为他这“随手”就是任意“胡来”，文学创作都是以此为“擅场”，那自然也是一个笑话。即如首句，先出“林花”，全不晓毕竟是何林何花，继而说是“谢了春红”，乃知是春林之红花，——而此春林红花事，已经凋谢。可见这所谓“随手”“直写”，正不啻书家之“一波三过折”，全任“天然”，“不加修饰”，意欲成“文”，诚梦呓之言也。\n\n　　且说以春红二字代花，即是修饰，即是艺术，天巧人工，总须“两赋而不来”方可。此春红者，无待更言，乃是极美好可爱之名花无疑，可惜竟已凋谢。调零倘是时序推迁，自然衰谢，虽是可惜，毕竟理所当然，尚可开解；如今却是朝雨暮风，不断摧残之所致。名花之凋零，如美人之夭逝，其为可怜可痛，不止倍蓰。以此可知，“太匆匆”一句，叹息中着一“太”字；“风雨”一然，愤慨中着一“无奈”字，皆非普通字眼，质具千钧，情同一恸矣。若明此义，则上片三句，亦千回百转之情怀，又匪特一笔三过折也。讲说文学之事，切宜细思寻玩，方不致误认古人皆荒率浅薄之妄人，方能于人于己两有所益。\n\n　　过片三字句三叠句，前二句换暗韵仄韵，后一句归原韵，别有风致。但“胭脂泪”三字，异样哀艳，尤宜着眼。于是让人们想到杜甫的名句“林花着雨胭脂湿”（《曲江对雨》），此乃南唐后主也熟读杜诗之证也。后主分明从杜少陵的“林花”而来，而且因朝来寒“雨”竟使“胭脂”尽“湿”，其思路十分清楚，但是假若后主在过片竟也写下“胭脂湿”三个大字，便成了老大一个笨伯，鹦鹉学舌，难有意味。他毕竟是艺苑才人，他将杜句加以消化，提炼，只运化了三字而换了一个“泪”字来代“湿”，于是便青出于蓝，而大胜于蓝，便觉全幅因此一字而生色无限。\n\n　　“泪”字已是神奇，但“醉”亦非趁韵谐音的妄下之字。此醉，非陶醉俗义，盖悲伤凄惜之甚，心如迷醉也。\n\n　　末句略如上片歇拍长句，也是运用叠字衔联法：“朝来”“晚来”，“长恨”，“长东”，前后呼应更增其异曲而同工之妙，即加倍具有强烈的感染力量。顾随先生论后主，以为“问君能有几多愁，恰似一江春水向东流”，其美中不足在“恰似”，盖明喻不如暗喻，一语道破“如”“似”，意味便浅。按这种说法，则“自是人生长恨水长东”，恰好免去此一微疵，使尽泯“比喻”之迹，而笔致转高一层矣。学文者于此，宜自寻味，美意不留，芳华难驻，此恨无穷，而无情东逝之水，不舍昼夜，“淘尽”之悲，苏轼亦云，只是表现之风格手法不同，非真有异也。', poem_tags = '宋词三百首,写花,人生' WHERE poem_title = '相见欢·林花谢了春红' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '力量可以拔起大山，豪气世上无人能比。但时局对我不利啊，乌骓马跑不起来了。\n乌骓马不前进啊，我该怎么办？虞姬啊！虞姬啊！我又该把你怎么办？', poem_notes = '兮：文言助词，相当于现代的“啊”或“呀”\n奈何：怎么办\n奈何：怎样；怎么办\n若：你', poem_appreciation = '《垓下歌》是西楚霸王项羽在进行必死战斗的前夕所作的绝命词。《垓下歌》中既洋溢着无与伦比的豪气，又蕴含着满腔深情；既显示出罕见的自信，却又为人的渺小而沉重地叹息。以短短的四句，表现出如此丰富的内容和复杂的感情，真可说是个奇迹。\n\n　　“力拔山兮气盖世”一句，项羽概括了自己叱吒风云的业绩。项羽是将门之子，少年气盛，力能扛鼎，才气超群。他胸怀大志，面对不可一世的秦始皇，敢于喊出“彼可取而代之”的豪言壮语。项羽是顶天立地的英雄，23岁跟随叔父项梁起兵反秦，率领江东八千子弟投入起义的大潮，成了诸路起义首领中妁佼佼者。巨鹿一战，项羽破釜沉舟，与几倍于己的秦军进行浴血奋战，奇迹般地灭了秦军主力，被各路诸侯推举为“上将军”。此后，项所向披靡，直至进军咸阳，自封为西楚霸王。但从这一句诗中也可以看出，项羽夸大了个人的力量，这是他失败的一个重要原因。\n\n　　“时不利兮稚不逝”，天时不利，连乌骓马也不肯前进了。项羽不是新时代的骄子，而是旧制度的牺牲品。在四年的楚汉战争之中，他虽然与汉军大战七十，小战半百，打了不少胜仗，但仍是匹夫之男，既不善于用人，更不会审时度势，他的失败根本不是什么天意，全是咎由自取。\n\n　　“骓不逝兮可奈何，虞兮虞兮奈若何？”这是项羽面临绝境时的悲叹。项羽被汉军追及，撤至垓下，陷人汉军重围，以致众叛亲离，帐内只剩下他心爱的虞美人。他夜不能寐，与虞姬悄然相对，借酒浇愁。突然，四面传来阵阵楚歜，项羽愕然失色，惊呼 “汉皆得楚乎？是何楚人之多？”项羽明白自己到了穷途末日，绝望的痛苦袭击着他。王位、天下，得而复失，连自己心爱的女人和战马都保不住了。项羽关心他们的命运，不忍弃之而去。虞姬也很悲伤，眼含热泪，起而舞剑，边舞边歌，唱道：“汉兵已略地，四方楚歌声。大王意气尽，贱妾何聊生？ ”歌罢，自刎身亡，好不悲壮！\n\n　　读完《垓下歌》，掩卷回味，使人悟出无论是谁，无论他曾经怎样的不可一世，煊赫一时，如果他办事违背了事物发展的客观规律，使事态发展到不可收抬的地步，到那时，即便有移山倒海之力，也不可避免地要走上失败的道路。', poem_tags = '古诗三百首,写人,励志,哲理' WHERE poem_title = '垓下歌' AND poem_author = '项羽';
UPDATE edu_poem SET poem_translation = '钱塘江的潮水，是天下雄伟的景观。从（农历）八月十六日到十八日潮水是最壮观的。当潮水远远地从钱塘江入海口涌起的时候，（远看）几乎像一条银白色的线；不久（潮水）越来越近，玉城雪岭一般的潮水连天涌来，声音大得像雷霆万钧，震撼天地，激扬喷射 ，吞没天空，冲荡太阳，气势极其雄伟豪壮。杨万里的诗中说的“海涌银为郭，江横玉系腰”就是指这样的景象。\n\n　　每年（农历八月）京都临安府长官来到浙江亭教阅水军，几百艘战船分列两岸；不久水军的战船演习五阵的阵势，忽而疾驶，忽而腾起，忽而分，忽而合，极尽种种变化，同时有在水面上骑马、舞旗、举枪、挥刀的人，好像踩在平地上一样安稳。忽然黄色的烟雾从四面升起，人和物彼此一点儿也看不见，只听得水爆的轰鸣声，声音像山崩塌一样。（等到）烟雾消散，水波平静，就一条船的踪影也没有了，只剩下被火烧毁的“敌船”，随波而去。\n\n　　几百个善于泅水的吴地健儿，披散着头发，身上画着文彩，手里拿着十幅大彩旗，争先恐后，鼓足勇气，逆流迎着潮水而上，在万仞高的巨浪中忽隐忽现，翻腾着身子变换各种姿态，但是旗尾却一点也不被水沾湿，凭借这种表演来显示他们高超的技能。\n\n　　江岸上下游十多里的地方，满眼都是穿着华丽的服饰的观众，车马堵塞道路，吃喝等各种物品（的价钱）比平时要高出很多倍。租用看棚的人(非常多)，中间即使是一席之地也不容有。', poem_notes = '浙江：就是钱塘江。\n自既望以至十八日：从农历（八月）十六日到十八日。既望，农历十六日（十五日叫望）。\n方其远出海门：当潮从入海口涌起的时候。方，当……时。其，代词，指潮。出，发、起。海门，浙江入海口，那里两边的山对峙着。\n仅如银线：几乎像一条（横画的）银白色的线。仅，几乎，将近。\n玉城雪岭：形容泛着白沫的潮水像玉砌的城墙和白雪覆盖的山岭。际天：连接着天。\n沃日（wò rì）：冲荡太阳。形容波浪大。沃，用水淋洗，冲荡。\n海涌银为郭，江横玉系腰这两句诗是《浙江观潮》一诗里的句子，意思是，海水涌起来，成为银子堆砌的城郭；浙江横着，潮水给系上一条白玉的腰带。“……是也”：就是指这样的景象。\n每岁京尹（yǐn）出浙江亭教阅水军：每年（农历八月）京都临安府长官来到浙江亭教阅水军。岁，年。京尹，京都临安府（今浙江杭州）的长官。浙江亭，馆驿名，在城南钱塘江岸。\n艨艟（méng chōng）：战船。\n既而尽奔腾分合五阵之势：演习五阵的阵势，忽而疾驶，忽而腾起，忽而分，忽而合，极尽种种变化。尽，穷尽。五阵，指两、伍、专、参、偏五种阵法。\n乘骑（chéng jì）弄旗标枪舞刀：乘马、舞旗、举枪、挥刀。骑，马。弄，舞动。标，树立、举。\n略不相睹：彼此一点也看不见。睹，看。\n水爆：水军用的一种爆炸武器。\n一舸无迹（yì gě wú jì）：一条船的踪影也没有了。舸，船。\n敌船：指假设的敌方战船。\n逝：去，往。\n吴儿善泅（qiú）者数百：几百个擅于泅水的吴地健儿。吴地即今江苏、浙江一带。因春秋时为吴国之地，故称。善，善于。泅，游泳、浮水（可不翻译）。\n披发文（wén）身：披散着头发，身上画着花纹。文，动词，画着文彩。\n溯（sù）迎而上：逆流迎着潮水而上。溯，逆流而上。而，表修饰。\n鲸波万仞（rèn）：万仞高的巨浪。鲸波，巨浪。鲸所到之处，波涛汹涌，所以称巨浪为鲸波。万仞，形容浪头极高，不是实指。\n腾身百变：翻腾着身子变换尽各种姿态。\n江干（gān）：江岸。\n珠翠罗绮（qǐ）溢目：满眼都是华丽的服饰。珠翠罗绮，泛指妇女的首饰和游人的华丽衣服。溢目，满眼。\n倍穹（qióng）：（价钱）加倍的高。穹，动词，高；倍，形容词，指很多倍。\n而僦（jiù）赁（lìn）看幕：租用看棚的人（非常多）。而，表转折。僦、赁，都是租用的意思。看幕，为观潮而特意搭的帐棚。\n虽席地不容间也：中间即使是一席之地的空地也不容有容。许，使。间（jiān）空间。虽，即使。席地，一席之地，仅容一个座位的地方。', poem_tags = '初中文言文,写景,散文' WHERE poem_title = '观潮' AND poem_author = '周密';
UPDATE edu_poem SET poem_translation = '四更天初至时，北风带来一场大雪；这上天赐给我们的瑞雪正好在除夕之夜到来，兆示着来年的丰收。\n盛了半盏屠苏酒的杯子还没有来得及举起庆贺，我依旧在灯下用草字体赶写着迎春的桃符。', poem_notes = '嘉：好\n瑞：指瑞雪\n天教：天赐\n岁除：即除夕', poem_tags = '春节,写雪' WHERE poem_title = '除夜雪' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '刚满十五岁的少年就出去打仗，到了八十岁才回来。\n路上碰到一个乡下的邻居，问：“我家里还有什么人？”\n（他说）“你家那个地方现在已是松树柏树林中的一片坟墓。”\n走到家门前看见野兔从狗洞里出进，野鸡在屋脊上飞来飞去。\n院子里长着野生的谷子，野生的葵菜环绕着井台。\n用捣掉壳的野谷来做饭，摘下葵叶来煮汤。\n汤和饭一会儿都做好了，却不知赠送给谁吃。\n走出大门向着东方张望，老泪纵横，洒落在征衣上。\n注：“遥望是君家，松柏冢累累。”原为“遥望是君家，松柏冢垒垒。”', poem_notes = '始：才。\n归：回家。\n道逢：在路上遇到。\n道：路途上。\n阿：语气词，没有意思。\n君：你，表示尊敬的称呼。\n遥望：远远地望去。\n松柏（bǎi）：松树、柏树。\n冢（zhǒng）：坟墓。\n累累：与“垒垒”通，形容丘坟一个连一个的样子。\n狗窦（gǒu dòu）：给狗出入的墙洞，窦，洞穴。\n雉（zhì）：野鸡。\n中庭：屋前的院子。\n生：长。\n旅：旅生，植物未经播种而野生。\n旅谷：野生的谷子。\n旅葵（kuí）：即野葵。\n舂（chōng）：把东西放在石臼或乳钵里捣掉谷子的皮壳或捣碎。\n持：用。\n作：当做。\n羹（gēng）：就是饭菜的意思。\n一时：一会儿就。\n贻（yí）：送，赠送。\n沾：渗入。', poem_appreciation = '这是一首叙事诗，描绘了一个“少小离家老大回”的老兵返乡途中与到家之后的情景，抒发了这一老兵的情感，也反映了当时的社会现实，具有一定的典型意义。开篇便不同凡响：“十五从军征，八十始得归。”这两句，直言老兵“十五”岁从军，“八十”岁方回，看似平淡无奇，像不经意间道来，实却耐人寻味，颇见功力。他“十五从军征”，奔赴何处，诗中未作说明；其军旅生活如何，战况怎样，诗中也均未交代。这就给读者留下众多想象的空间。但有一点是明确的，那就是他“从军征”，系出于战事，而且这一去就是数十年！“八十”与“十五”相对照，突出其“从军征”时间之久；“始得归”与“从军征”相呼应，则表明他中途一直未能回来。\n\n　　《十五从军征》，是一首暴露封建社会不合理的兵役制度的汉代乐府民歌，反映了劳动人民在当时黑暗的兵役制度下的不平和痛苦。作品真实、深刻、令人感愤，催人泣下。\n\n　　“道逢乡里人，‘家中有阿谁？’”主人公的思想脉络由六十五年的征战生活进入邈邈旷野、漫漫古道，对亲人家园的现状由茫然无际的想象到急切地、盼知又怕知地询问，读者由开头两句诗展开的遐想的翅翼也在主人公焦急的劈头问话声中收束。，一句“家中有阿谁”的追问，推出了作品的聚光点——家。六十五年了，岂敢奢望家人安然无恙、亲人健在？能有一二幸存者已是不幸中之万幸了。所以他只问，家中还有谁侥幸苟活人世呢？可是，“乡里人”的回答却如站在雪地里浇下的一盆冰水：“遥看是君家，松柏冢累累。”在这动乱的年月，我的亲人们竟无一幸存者？多少年来积压心底的感情，向谁倾诉、向谁表达啊？唯有那青青松柏、垒垒坟冢吗？那，就是我的家吗？不，不，不可能！\n\n　　摆在他面前的现实是：“兔从狗窦入，雉从梁上飞；中庭生旅谷，井上生旅葵。”由遥看到近见，满眼更加荒凉凄楚的景象。作者没说室空无人，而是抓住野兔见人钻进家畜窝中自以为得所，野鸡惊飞落到屋内梁上自以为安的情景；作者没有直书庭园荒芜杂乱，只摄取了井边、中庭随意生长的葵菜和谷物两个“镜头”，人去屋空，人亡园荒，更其形象，倍伤人心神。一个风尘仆仆的老人，站在曾经炊火融融、庭园整洁的“家”的面前，站在盼望了六十五年可又无一亲人相迎的家的面前，竟然比想象的还不堪十倍、百倍……这是怎样一种情境，将掀起读者怎样的感情波澜呢？\n\n　　“出门东向看，泪落沾我衣。”他走出年久失修的破门，向东方看去，他也许还抱着希望，他看到了谁？看到了什么呢？他也许看到了久别的亲人？也许什么也没有看到。他茫然地从幻想中走出来，低声哭了起来 “泪落沾我衣”五个字，饱和了多么丰富、多么深厚、多么沉痛的感情内涵啊！ 主人公和他的家的相互映衬的叙写，把作品的主题和艺术水平都推向了一个新的高度：服了整整六十五年兵役的人，竟然还是全家唯一的幸存者，那些没有服兵役的亲人们，坟上松柏都已葱葱郁郁，可以想见他们生前贫寒凄苦的生活还不如每时每刻都可能牺牲的士卒；作品具体写的是主人公为国征战六十五载却有家归不得，等到归时却又无家可归的不幸遭遇和惨痛心情，而他的不幸与那些苟生且不能只有走进静默、暗湿、冰冷的坟墓的亲人们相比，他又是“幸运者”了。作品就不仅仅暴露了封建兵役制度的黑暗、罪恶，不仅仅表现了八十老翁一人的不幸，而且反映了当时整个社会现实的黑暗，表现了比个人不幸更深广的全体人民的不幸和社会的凋敝、时代的动乱，\n\n　　诗的最后两句于对老兵的动作描绘中进一步抒发老兵心中的悲哀。这里，突出老兵出门张望（“出门东向看”）与老泪纵横（“泪落沾我衣”）这一细节，将举目无亲、孤身一人的老兵形象刻画得栩栩如生，将其悲痛欲绝的茫然之情抒发得淋漓尽致。试想，他“十五从军征，八十始得归”，家中已了无亲人，而只有荒凉的景象，怎能不悲从中来？以后的生活，又当如何呢？他又怎能不感到茫然呢？他向远方望去，难道自己的祖国里，只有自己一家是这样的吗？不是的。其悲惨的遭遇是谁造成的，尽管诗中未明言直说，但我们只要联系到此诗产生的时代背景，则不难看出这一点。根据吴兢《乐府古题要解》的说法，此诗晋时已谱入乐府，当可视之为汉魏战乱之际的作品。正是当时穷兵黩武的统治者与无休无止的战争，造成了该老兵的悲惨遭遇。反映该老兵的悲惨遭遇，也就反映了当时在沉重的徭役压迫之下的平民百姓的悲惨遭遇，深刻地揭露了当时黑暗的社会现实。\n\n　　此诗围绕老兵的返乡经历及其情感变化谋篇结构，巧妙自然。其返乡经历是：始得归→归途中→返回家中→“出门东向看”；情感变化为：急想回家，急想知道“家中有阿谁？”，充满与亲人团聚的希望（归途中）→希望落空→彻底失望（返回家中，景象荒凉，了无一人）→悲哀流泪，心茫然（“出门东向看”）。这些又归结为表现揭露黑暗社会现实的诗之主题。全诗运用白描手法绘景写人，层次分明，语言质朴，且以哀景写哀情，情真意切，颇具特色，也颇能体现汉乐府即景抒情的艺术特点。', poem_tags = '古诗三百首,乐府,民歌,叙事,忧国忧民' WHERE poem_title = '十五从军征' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '牧童骑在黄牛背上，嘹亮的歌声在林中回荡。\n忽然想要捕捉树上鸣叫的知了，就马上停止唱歌，一声不响地站立在树旁。', poem_notes = '牧童：指放牛的孩子。\n振：振荡；回荡。说明牧童的歌声嘹亮。\n林樾（yuè）：指道旁成阴的树。\n欲：想要。\n捕：捉。\n鸣：叫。\n立：站立。', poem_appreciation = '这首诗的第一句平平而起，不着痕迹。第二句调子突然高昂，旋律突然加快，从而形成一个高潮。一二句描写了小牧童的天真活泼、悠然自得的可爱模样和他的愉快心情，“骑”字直接写出了牧童的姿势，“振”字则间接点出他的心情。通过“骑”和“振”两个动词,把牧童那种悠闲自在、无忧无虑的心情和盘托了出来。他几乎完全陶醉在大自然的美景之中，简直不知道世间还有“忧愁”二字。正因为心中欢乐，才不禁引吭高歌，甚至于遏行云，“振林樾”。\n\n　　三四句仍然是继续描写神态。第三句是过渡，是作势。写牧童的心理活动，交代了他“闭口立”的原因，也是全诗的转折点。第四句，急转直下，如千尺悬瀑坠入深潭，戛然而止。“忽然”一词，把这个牧童发现树上鸣蝉时的惊喜心情和机警性格栩栩如生地表现了出来。“忽然”发生了变化：由响而静、由行而停，把小牧童闭口注目鸣蝉的瞬间神态写得韵味十足。而“闭”和“立”两个动词，则把这个牧童天真的神态和孩子式的机智刻划得淋漓尽致。全诗纯用白描手法，紧紧抓住小牧童一刹那间的表现，逼真地写出小牧童非常机灵的特点，让人倍觉小牧童的纯真可爱。\n\n　　这是一首反映儿童生活的诗篇，诗人在诗中赞美了小牧童充满童趣的生活画面。诗人先写小牧童的动态，那高坐牛背、大声唱歌的派头，何等散漫、放肆；后写小牧童的静态，那屏住呼吸，眼望鸣蝉的神情，显得特别专注。“此时无声胜有声”。这从动到静的变化，写得既突然又自然，把小牧童天真烂漫、好听多事的形象，刻画得活灵活现。这首诗正是在这种起伏变化中获得了巨大的艺术效果。诗的语言，明白如话，质朴无华，十分本色。至于下一步的动静，小牧童怎样捕蝉，捕到没有，诗人没有写，留给读者去体会、去遐想、去思考。\n\n　　这首诗通过对自然环境和社会生活的描写，直接抒发生活的感受，看似闲情逸致，实则寄托情思。同时这首诗不顾及格律，活泼自由，语言浅显明了，形象自然生动。综观全诗，它所描绘的和平、宁静和优美如画的田园风光，所刻划的活泼、自在和天真无邪的牧童形象，表现了诗人的一种“真性情”。诗人曾经说过 “诗人者，不失其赤子之心也。”毋庸讳言，诗所描绘、所刻划的，正是诗人毕生追求的境界，也正是他所一再强调的“真性情”。', poem_tags = '古诗三百首,小学古诗,儿童,早教古诗100首' WHERE poem_title = '所见' AND poem_author = '袁枚';
UPDATE edu_poem SET poem_translation = '黎明起床，车马的铃铎已震动；一路远行，游子悲思故乡。\n鸡声嘹亮，茅草店沐浴着晓月的余辉；足迹依稀，木板桥覆盖着早春的寒霜。\n枯败的槲叶，落满了荒山的野路；淡白的枳花，鲜艳地开放在驿站的泥墙上。\n因而想起昨夜梦见杜陵的美好情景；一群群鸭和鹅，正嬉戏在岸边弯曲的湖塘里。', poem_notes = '商山：山名，又名尚阪、楚山，在今陕西商洛市东南山阳县与丹凤县辖区交汇处 。作者曾于大中（唐宣宗年号，847～860）末年离开长安，经过这里。\n动征铎：震动出行的铃铛。征铎：车行时悬挂在马颈上的铃铛。铎：大铃。\n槲（hú）：陕西山阳县盛长的一种落叶乔木。叶子在冬天虽枯而不落，春天树枝发芽时才落。每逢端午用这种树叶包出的槲叶粽也成为了当地特色。\n明：使……明艳。枳（zhǐ）：也叫“臭橘”，一种落叶灌木或小乔木。春天开白花，果实似橘而略小，酸不可吃，可用作中药。驿（yì）墙：驿站的墙壁。驿：古时候递送公文的人或来往官员暂住、换马的处所。这句意思是说：枳花鲜艳地开放在驿站墙边。\n杜陵：地名，在长安城南（今陕西西安东南），古为杜伯国，秦置杜县，汉宣帝筑陵于东原上，因名杜陵，这里指长安。作者此时从长安赴襄阳投友，途经商山。\n凫（fú）雁：凫，野鸭；雁，一种候鸟，春往北飞，秋往南飞。回塘：岸边曲折的池塘。\n回塘：岸边弯曲的湖塘。', poem_appreciation = '这首诗之所以为人们所传诵，是因为它通过鲜明的艺术形象，真切地反映了封建社会里一般旅人的某些共同感受。\n\n　　首句表现“早行”的典型情景，概括性很强。清晨起床，旅店里外已经响起了车马的铃铎声，旅客们套马、驾车之类的许多活动已暗含其中。第二句固然是作者讲自己，但也适用于一般旅客。“在家千日好，出外一时难。”在封建社会里，一般人由于交通困难、人情淡薄等许多原因，往往安土重迁，怯于远行。“客行悲故乡”这句诗，很能够引起读者情感上的共鸣。\n\n　　三、四两句，历来脍炙人口。宋代梅尧臣曾经对欧阳修说：最好的诗，应该“状难写之景如在目前，含不尽之意见于言外”。欧阳修请他举例说明，他便举出这两句和贾岛的“怪禽啼旷野，落日恐行人”，并反问道：“道路辛苦，羁旅愁思，岂不见于言外乎？”（《六一诗话》）明代李东阳进一步分析说：“二句中不用一二闲字，止提掇出紧关物色字样，而音韵铿锵，意象具足，始为难得。”“音韵铿锵”，“意象具足”，是一切好诗的必备条件。李东阳把这两点作为“不用一二闲字，止提掇紧关物色字样”的从属条件提出，很可以说明这两句诗的艺术特色。所谓“闲字”，指的是名词以外的各种词；所谓“提掇紧关物色字样”，指的是代表典型景物的名词的选择和组合。这两句诗可分解为代表十种景物的十个名词：鸡、声、茅、店、月、人、迹、板、桥、霜。虽然在诗句里，“鸡声”、“茅店”、“人迹”、“板桥”都结合为“定语加中心词”的“偏正词组”，但由于作定语的都是名词，所以仍然保留了名词的具体感。例如“鸡声”一词，“鸡”和“声”结合在一起，完全可以唤起引颈长鸣的视觉形象。“茅店”、“人迹”、“板桥”，也与此相类似。\n\n　　古时旅客为了安全，一般都是“未晚先投宿，鸡鸣早看天”。诗人既然写的是早行，那么鸡声和月是必然要体现的。而茅店又是山区有特征性的景物。“鸡声茅店月”，把旅人住在茅店里，听见鸡声就爬起来看天色，看见天上有月，就收拾行装，起身赶路的特征都有声有色地表现了出来。\n\n　　同样，对于早行者来说，板桥、霜和霜上的人迹也都是有特征性的景物。作者于雄鸡报晓、残月未落之时上路，也算得上“早行”了；然而已经是“人迹板桥霜”，这真是“莫道君行早，更有早行人”啊！这两句纯用名词组成的诗句，写早行情景宛然在目，确实称得上“意象具足”的佳句。\n\n　　“槲叶落山路，枳花明驿墙”两句，写的是刚上路的景色。商县、洛南一带，枳树、槲树很多。槲树的叶片很大，冬天虽干枯，却存留枝上；直到第二年早春树枝将发嫩芽的时候，才纷纷脱落。而这时候，枳树的白花已在开放。因为天还没有大亮，驿墙旁边的白色枳花，就比较显眼，所以用了个“明”字。可以看出，诗人始终没有忘记“早行”二字。\n\n　　旅途早行的景色，使诗人想起了昨夜在梦中出现的故乡景色：“凫雁满回塘。”春天来了，故乡杜陵，回塘水暖，凫雁自得其乐；而自己，却离家日远，在茅店里歇脚，在山路上奔波。“杜陵梦”，补出了夜间在茅店里思家的心情，与“客行悲故乡”首尾照应；而梦中的故乡景色与旅途上的景色又形成鲜明的对照。眼里看的是“槲叶落山路”，心里想的是“凫雁满回塘”。“早行”之景与情，都得到了完美的表现。', poem_tags = '初中古诗,写景,思乡' WHERE poem_title = '商山早行' AND poem_author = '温庭筠';
UPDATE edu_poem SET poem_tags = '端午节,写花,抒怀,怀才不遇' WHERE poem_title = '已酉端午' AND poem_author = '贝琼';
UPDATE edu_poem SET poem_translation = '在人间四月里百花凋零已尽，高山古寺中的桃花才刚刚盛开。\n我常为春光逝去无处寻觅而怅恨，却不知它已经转到这里来。', poem_notes = '大林寺：在庐山大林峰，相传为晋代僧人昙诜所建，为中国佛教胜地之一。\n人间：指庐山下的平地村落。芳菲：盛开的花，亦可泛指花，花草艳盛的阳春景色。尽：指花凋谢了。\n山寺：指大林寺。始：才；刚刚。\n长恨：常常惋惜。春归：春天回去了。觅：寻找。\n不知：岂料，想不到。转：反。此中：这深山的寺庙里。', poem_appreciation = '该诗只有短短的四句，从内容到语言都似乎没有什么深奥、奇警的地方，只不过是把“山高地深，时节绝晚” 、“与平地聚落不同”的景物节候，做了一番纪述和描写。但细读之，就会发现这首平淡自然的小诗，却写得意境深邃，富于情趣。\n\n　　诗的开首“人间四月芳菲尽，山寺桃花始盛开”两句，是写诗人登山时已届孟夏，正属大地春归，芳菲落尽的时候了。但不期在高山古寺之中，又遇上了意想不到的春景 —— 一片始盛的桃花。从紧跟后面的“长恨春归无觅处”一句可以得知，诗人在登临之前，就曾为春光的匆匆不驻而怨恨，而恼怒，而失望。因此当这始所未料的一片春景冲入眼帘时，该是使人感到多么的惊异和欣喜。诗中第一句的“芳菲尽”，与第二句的“始盛开” ，是在对比中遥相呼应的。它们字面上是纪事写景，实际上也是在写感情和思绪上的跳跃 —— 由一种愁绪满怀的叹逝之情，突变到惊异、欣喜，以至心花怒放。而且在首句开头，诗人着意用了“人间” 二字，这意味着这一奇遇、这一胜景，给诗人带来一种特殊的感受，即仿佛从人间的现实世界，突然步入到一个什么仙境，置身于非人间的另一世界。\n\n　　正是在这一感受的触发下，诗人想象的翅膀飞腾起来了。“长恨春归无觅处，不知转入此中来。” 诗人想到，自己曾因为惜春、恋春，以至怨恨春去的无情，但谁知却是错怪了春，原来春并未归去，只不过像小孩子跟人捉迷藏一样，偷偷地躲到这块地方来罢了。\n\n　　这首诗中，既用桃花代替抽象的春光，把春光写得具体可感，形象美丽；而且还把春光拟人化，把春光写得仿佛真是有脚似的，可以转来躲去。不，岂只是有脚而已，看它简直还具有顽皮惹人的性格呢。在这首短诗中，自然界的春光被描写得是如此的生动具体，天真可爱，活灵活现，如果没有对春的无限留恋、热爱，没有诗人的一片童心，是写不出来的。这首小诗的佳处，正在立意新颖，构思灵巧，而戏语雅趣，又复启人神思，惹人喜爱，可谓唐人绝句小诗中的又一珍品。\n\n　　人间四月芳菲尽， 山寺桃花始盛开。 长恨春归无觅处， 不知转入此中来。海拔越高，温度越低，所以季节的出现也较陆地晚这里就提出了一个问题：大林寺的桃花在季节上为什么比山下要开得迟？从气象的角度来解释，答案只有一个，这就是“受了气温垂直差异的影响。也就是说，大林寺桃花之所以开得迟，原因是由于这里是“山地气候” 的缘故。\n\n　　常识告诉我们，在山地地区，气温是随着地势的高度的上升而相应递减的。一般说， 高度每升高100米，气温就下降0.6℃。当山地垂直起伏到几干米时，气温的垂直差异就更为明显。加上植物对气温的适应能力不同，这样，处于不同高度地段的植物景观必然就会出现差异。庐山海拔高度约1 400米，山顶气温比山麓平川地区一般要低8～9℃；大林寺位于今日庐山“花径风景区”，比山下平原高出1 100余米，气温较山下的九江市一带低6～7℃；加以庐山地处长江与郡阳湖之间，江湖水汽郁结，云雾弥漫，日照不足，更使山上的气温降低，春天当然就来得迟了。\n\n　　对于这个道理，生活在一千多年前的白居易自然是无法理解的。这从他在《游大林寺序》中所写的一段话“大林穷远，山高地深，时节绝晚，于时孟夏(四月)，正如正、二月天，梨桃始花，人物风候，与平地聚落不同，初到恍然若别一世界者”，可以证明。 其实，气温垂直变化对植物的影响，不仅在庐山是这样，就是在别处也不例 外。试以喜马拉雅山在我国境内一段山地为例，位于山地东南谷地的察隅、墨脱一带，由于海拔较低，日照充足，气温较高，可以种植水稻、玉米、柑桔等喜高温作物；由此往上，到海拔3 000米处，气温下降、雨水减少，只能种青裸、小麦一类作物；再往上，则是草木稀疏的高山牧场；雪线以上则因终年积雪、气候恶劣，除了偶尔长着几棵雪莲以外，啥植物也长不了。可见，在山地地区，植物在垂直分布上的差异性是与山地气候要素一一气温和降水的垂直变异分不开的。所以山地地区的气候就表现出了“一山有四季，十里不同天”的特色了。', poem_tags = '写景,写花,早教古诗100首' WHERE poem_title = '大林寺桃花' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '谢安在寒冷的雪天举行家庭聚会，和他子侄辈的人讲解诗文。不久，雪下得大了，太傅高兴地说：“这纷纷扬扬的白雪像什么呢?”他哥哥的长子谢朗说：“在空中撒盐差不多可以相比。”谢安大哥的女儿说：“不如比作柳絮凭借着风飞舞。”太傅大笑起来。她就是谢安大哥谢无奕的女儿谢道韫，左将军王凝之的妻子。', poem_notes = '谢太傅：即谢安（.320年－385年），字安石，晋朝陈郡阳夏（现在河南太康）人。做过吴兴太守、侍 中、吏部尚书、中护军等官职。死后追赠为太傅。\n内集：家庭聚会。\n儿女：子侄辈。\n讲论文义：讲解诗文。\n俄而：不久，不一会儿。\n骤：急，紧。\n欣然：高兴的样子。\n何所似：像什么。何，什么；似，像。\n胡儿：即谢朗。谢朗，字长度，谢安哥哥的长子。做过东阳太守。\n差可拟：差不多可以相比。差，大致，差不多；拟，相比。\n未若：倒不如。\n因：凭借。\n 即：是。\n无奕女：指谢道韫（yùn），东晋有名的才女，以聪明有才著称。无奕，指谢奕，字无奕。\n王凝之：字叔平，大书法家王羲之的第二个儿子，做过江州刺史、左将军、会稽内史等。', poem_appreciation = '这是一则千古佳话，表现了女才子谢道韫杰出的诗歌才华、对事物细致的观察和具有灵活想象力。\n\n　　据《晋书·王凝之妻谢氏传》及《世说新语·言语》篇载，谢安寒雪日尝内集，与儿女讲论文义，俄而雪骤，安欣然唱韵，兄子朗及兄女道韫赓歌（诗即如上），安大笑乐。\n\n　　谢安所乐，在于裙钗不让须眉，侄女之诗才，更在侄子之上。按谢朗少有文名，《世说新语·言语》篇引《续晋阳秋》称他“文义艳发”，《文学》篇引《中兴书》说他“博涉有逸才”。所以叔父出韵起题，侄子即为唱和，正见其才思敏捷也。平心而论，“撒盐空中”亦不失为一种比方，雪，以其粉白晶莹飘散而下，谢朗就近取譬，用撤盐空中拟之，虽不高明，也差可形容了。\n\n　　然而，聪颖的妹妹并不迷信兄长的才名。她觉得，以盐拟雪固然不错，但没有形容出雪花六瓣，随风飘舞，纷纷扬扬，无边无际的根本特征。于是，针对兄长的原句，她作了大胆的修正：“未若柳絮因风起。”\n\n　　柳絮，作为春时景物，有似花非花，因风而起，飘忽无根，满天飞舞的特征。晋伍辑之《柳花赋》曾形容：“扬零花而雪飞，或风回而游薄，或雾乱而飙零，野净秽而同降，物均色而齐明。”谢道韫将此来比拟北风吹起漫天飞雪，堪称契合无间。取柳絮可比其形言其大，点明当时的“雪骤”之景，而“因风起”更指出它随风飘舞，漫无边际的自然特点。（宋代的贺铸《青玉案》词有“满城风絮”句。）由此较之，雪花柳絮，可谓是异迹而同趣了。如此再看“撒盐空中”的比方，则未免有局促见肘之诮了。\n\n　　清人沈德潜说：“事难显陈，理难言罄，每托物连类以形之。”（《说诗晬语》卷下）比喻是诗歌的基本修辞手法。其要在于贴切传神，新颖入妙。这正是谢道韫此句高于他兄长的地方。\n\n　　但是，真正的佳句名句之所以千古流传，播传人口，更重要还在于它能通过形象传达出作者内心的思想感情。谢道韫的这句诗，其佳处不仅在工干设譬，还在于透露出女才子热爱生活、热爱自然的情怀。她将北风飞雪的严寒冬景，比作东风吹绵的和煦春色，正表现出女作者开朗乐观的胸襟以及对美好春光的由衷向往。\n\n　　据《晋书》本传，谢道韫的联句不仅得到她叔父的称赏，而且还受到在场嘉宾的一致赞许。这次联句，遂传为一时佳话，谢道韫从此也赢得了“咏絮才”的美名。后来南朝梁刘孝绰写过一首《对雪诗》，其中有“桂华殊皎皎，柳絮亦霏霏。讵比咸池曲，飘飖千里飞”。也许是受到谢道韫的启发。\n\n　　须要说明的是，谢道韫的出色联句。并不是一时之功，刹那灵感，而是有她平时深厚的文学修养作基础的。《世说新语·言语》篇引《妇人集》称她“有文才，所著诗、赋、诔，颂传于世”。可惜绝大部分没有保存到今天。', poem_tags = '初中文言文,冬天,咏物,写雪,赞美,女子' WHERE poem_title = '咏雪 / 咏雪联句' AND poem_author = '刘义庆';
UPDATE edu_poem SET poem_translation = ':学习方法\n　　子曰：“学而时习之，不亦说乎？有朋自远方来，不亦乐乎？人不知而不愠(yùn)，不亦君子乎?” (《学而》) \n　　孔子说:“学习并且按时地去复习，不也很快乐吗？有志同道合的人从远方来，不也很高兴吗？别人不了解我但我不生气，不也是道德上有修养的人吗？“ \n　　重点字词解释:　(1)子：先生，指孔子。中国古代对于有地位、有学问的男子的尊称，有时也泛称男子。《论语》书中“子曰”的子，都是指孔子而言。孔子（前551——前479），名丘，字仲尼，春秋时鲁国陬邑（现在山东曲 阜）人。是儒家学派的创始人，我国古代的思想家、教育家。 \n　　(2)学：孔子在这里所讲的“学”，主要是指学习西周的礼、乐、诗、书等传统文化典籍。 \n　　(3)时习：按时地去复习。在周秦时代，“时”字用作副词，意为“在一定的时候”或者“在适当的时候”。但朱熹在《论语集注》一书中把“时”解释为“时常”。“习”，指演习礼、乐；复习诗、书。也含有温习、实习、练习的意思。 \n　　(4)说：通假字，音yuè，实意“悦”的古体字，愉快的意思。 \n　　(5)朋：上古朋和友是有区别的：同门（师）为朋，同志为友。 \n　　(6)乐：与说有所区别。旧注说，悦在内心，乐则见于外。 \n　　(7)人不知：此句不完整，没有说出人不知道什么。缺少宾语。一般而言，知，是了解的意思。人不知，是说别人不了解自己。 \n　　(8)愠：拼音：yùn，生气，发怒。 \n　　（9）君子：道德上有修养的人。 \n　　补充词解释： \n　　而：连词。(可译为并且）例：学而时习之。 \n　　转折。(可译为却) 例：人不知而不愠。 \n　　亦（yì）：同样、也是。 \n　　乎：语气助词，表疑问语气，可译“吗”。 \n　　自：从。 \n　　知：了解。　 \n　　本段理解： \n　　第1句话讲的是学习方法。对于知识，“学”只是一个认识过程，“习”是一个巩固的过程，要想获得更多的知识，必须“学”与“习”统一起来。 \n　　第2句话讲的是学习乐趣。志同道合的人来访可以增进友谊，并且可互相学习、共同提高。 \n　　第3句话讲的是为人态度。“人不知”，后面省略了宾语“之”，可译为“我”或“自己”\n\n第二则:为人处事\n　　曾子曰：“吾（wú）日三省(xǐng)吾(wú)身：为（wèi）人谋而不忠乎?与朋友交而不信乎?传（chuán）不习乎?” (《学而》) \n　　 曾子说:“我每天多次地反省自己:替别人办事是不是尽心尽力呢 ？跟朋友交往是不是真诚，诚实呢？ 老师传授的知识是否复习过了呢？ “ \n　　重点字词解释: \n　　(1)曾子：曾子姓曾名参（shēn）字子舆，生于公元前505~前436年，春秋战国间鲁国南武城(现在山东费县人)，是被鲁国灭亡了的鄫国贵族的后代。曾参是孔子的得意门生，以孝子出名。据说《孝经》就是他撰写的。 \n　　(2)三省（xǐng）：多次反省。注：三省有几种解释：一是多次检查；二是从多个方面检查。其实，古代在有动作性的动词前加上数字，表示动作频率多，不必认定为三次。 三：泛指多次。 多次进行自我检查反省。 \n　　(3)忠：旧注曰：尽己之谓忠。此处指对人应当尽心竭力。 \n　　(4)信：旧注曰：信者，诚也。以诚实之谓信。要求人们按照礼的规定相互守信，以调整人们之间的关系。意思是：真诚、诚实 \n　　(5)传不习：传（动词用做名词），旧注曰：“受之于师谓之传。老师传授给自己的。习，与“学而时习之”的“习”字一样，指温习、实习、演习等。 \n　　补充词解释： \n　　吾：我。 \n　　日：每天。 \n　　三：多次。 \n　　省：检查，反省。 \n　　为：替。 \n　　谋：谋划。 \n　　忠：尽心尽力。 \n　　信：诚信 \n　　传：老师传授的知识\n\n第三则:学习方法\n　　子曰：“温故而知新，可以为师矣。”(《为政》) \n　　孔子说：“复习学过的知识，可从中获得新的见解与体会,凭借这点就可以当老师了。” \n　　重点字词解释:　注：本章的“温故而知新”有两解。一为“温故才知新”：温习已闻之事，并且由其中获得新的领悟；二为“温故及知新”：一方面要温习典章故事，另一方面又努力撷取新的知识。 \n　　我以为合并这两种解法，也许更为完整：在能力范围以内，尽量广泛阅览典籍，反复思考其中的涵义，对已经听闻的知识，也要定期复习，期能有心得、有领悟；并且也要尽力吸收新知；如此则进可以开拓人类知识的领域，退也可以为先贤的智能赋予时代的意义。像这样融会新旧、贯通古今方可称是“温故而知新”。 \n　　也有学者以为作“温故及知新”解不太合适，因为按字面上解释，仅做到吸收古今知识而未有领悟心得，只像是知识的买卖者，不足以为师。所以我们就来看看“师”的意义。在论语中师字一共见于14章，其中意义与今日的老师相近者。 \n　　故：旧的知识（形容词用作名词）。 \n　　而：连词，表顺承，就 \n　　知：领悟。 \n　　可：可以。 \n　　以：凭借。 \n　　为：作为。 \n　　另外词解释： \n　　温故知新（成语）： \n　　请注意不是温故而知新 \n　　【解释】：温：温习；故：旧的。温习旧的知识，得到新的理解和体会。也指回忆过去，能更好地认识现在。 \n　　【出自】：《论语·为政》：“温故而知新，可以为师矣。”汉·班固《东都赋》：“温故知新已难，而知德者鲜矣。” \n　　【示例】：～是学习上的重要方法。 \n　　【语法】：连动式；作谓语、定语；用于学习、工作或其他\n\n第四则:学习与思考的辩证关系\n　　子曰：“学而不思则罔，思而不学则殆。”(《为政》) \n　　孔子说:“只学习却不思考,就会感到迷茫而无所适从，只是思考而不学习，就会疑惑而无所得。” \n　　重点字词解释： \n　　而：连词，表转折。 \n　　则：连词，相当于“就”、“便”。 \n　　罔（wǎng）：通“惘”，意思是感到迷茫而无所适从。 \n　　殆（dài）：这里指有害。本意：危险。 \n　　本段讲了学习与思考的的辩证关系，认为二者不可偏废。\n\n第五则:学习态度\n　　子曰：“由，诲女知之乎!知之为知之，不知为不知，是知（zhì）也。”(《为政》) \n　　孔子说：“仲由啊，让为师教导你对待知与不知的态度吧！知道就是知道，不知道就是不知道，这才是聪明的。” \n　　1、诲女知之乎！ \n　　教给你对待知或不知的正确态度吧！（杨伯峻《论语译注》） \n　　2、诲女知之乎！ \n　　我告诉你什么叫求知吧！（李泽厚《论语今读》） \n　　3、诲女知之乎！ \n　　我教你怎么算知道吧！（钱穆《论语新解》） \n　　4、诲，女知之乎？ \n　　教育（教诲），你知道吗？（南怀谨《论语别裁》） \n　　5、诲女，知之乎？ \n　　我教导你的知识，你都知道了吗？（徐志刚《论语通译》） \n　　6、诲女知之乎！ \n　　（我）教给你的，（你)懂得了吗！（薛金星《中学生教材全解》） \n　　7、让我来教教你吧，你可懂得这个道理？（杨润根《发现论语》） \n　　孔子说：“仲由，教给你对待知与不知的态度吧：知道就是知道，不知道就是不知道——这才是聪明智慧。 \n　　重点字词解释： \n　　女：通假字“女”通“汝”，你。 \n　　知（zhì）：通〝智〞本字指“是知（通“智”zhì）也”：通“智”聪明，智慧。 \n　　之：代孔子教的东西 \n　　诲：教，传授。 \n　　乎：语音助词。 \n　　由:仲由字(子路)（前542～前480）春秋时期鲁国卞（今山东泗水县泉林镇卞桥村）人，孔子得意门生，以政事见称。 \n　　本段理解：孔子说这段话意思是言行要谨慎，不要夸大自己的知识和本领。要有诚实、谦虚的态度，不要不懂装懂。\n\n第六则:学习态度\n　　子曰：“见贤思齐焉，见不贤而内自省也。” (《里仁》)　 \n　　孔子说：“看见有才能的人（德才兼备的人）就向他学习，希望能向他看齐；看见不贤的人，就反省自己有没有和他一样的缺点，有要改正。” \n　　重点字词解释: \n　　思:希望,想着。 \n　　省：指反省有没有相同的毛病。 \n　　齐：看齐 \n　　贤：德才兼备的人 \n　　焉：句末语气词 \n　　本段理解：要向一切人学习，随时随地都要注意学习。虚心学习，以人为鉴，取长补短。\n\n第七则:学习态度\n　　子曰：“三人行，必有我师焉。择其善者而从之，其不善者而改之。”(《述而》) \n　　孔子说：“几个人在一起行走,其中必定有可作为我的老师的人，要选择他们的长处 来学习，如果看到他们的缺点要反省自己有没有像他们一样的缺点，若有，要一起加以改正。” \n　　重点字词解释： \n　　必有我师焉：其中必定有可作为我的老师的人。焉，相当于“于之”，即“在其中”的意思。 \n　　三：泛指多次； \n　　焉：兼词“于之”，在那里； \n　　之：字指择其善者而从之：代善者； \n　　之：字指其不善者而改之：代不善者。\n\n第八则:修身做人\n　　曾子曰：“士不可以不弘毅，任重而道远。仁以为己任，不亦重乎？死而后已，不亦远乎？” （《泰伯》） \n　　曾子说：“有抱负的人不可以不胸怀宽广，意志坚定，因为他肩负着重大的使命（或责任），路途又很遥远。把实现‘仁’的理想看作自己的使命，不也很重大吗？直到死才停止，这不也是很遥远吗？” \n　　词语解释： \n　　弘毅：胸怀宽广，意志坚强 ：刚强，勇毅 \n　　仁：这里指儒家的推己及人，仁爱待人 \n　　已：结束\n\n第九则:修身做人\n　　子曰：“岁寒，然后知松柏之后凋也。” (《子罕》) \n　　孔子说:“直到每年中最寒冷的季节,才知道松柏(bǎi)是最后落叶的。“ 深刻含义：人们要经受得住时间的考验，也以松柏为喻，谈人应当具备坚毅的品格！ \n　　之：这里的之是结构助词，用在主谓之间，取消句子的独立性，变成偏正结构，不译或勉强译作“的”。 \n　　岁寒：一年中的寒冷季节,深冬 \n　　然后（古今词）：然 ，后。意思是分开来解释的。然，这样。后，以后。 \n　　士：有抱负的人。 \n　　本段理解：本段借松柏之后凋比喻一种坚贞不屈、不随俗流、保持节操、坚韧不拔的社会现象。\n\n第十则:修身做人\n　　子贡问曰：“有一言而可以终身行之者乎?”子曰：“其恕乎!己所不欲，勿施于人。”(《卫灵公》) \n　　子贡问道:“有没有可以终身奉行的一个字呢? ”孔子说：“那大概就是‘恕’字吧！自己不喜欢的事物，不要强行加于别人身上。” \n　　重点字词解释: \n　　一言：一个字。 \n　　行：奉行。 \n　　其恕乎：其：大概，也许。恕：用自己的心来推想别人的心，指儒家的推己及人，仁爱待人。 \n　　欲：喜欢，想。想要（做的事）。 \n　　施：施加。 \n　　其：大概 \n　　评析本段：“己所不欲，勿施于人”意思是自己不愿意的事情的不要施加给别人。它在今天的社会道德修养方面有积极意义，已成为警世格言。 ▲', poem_appreciation = '所涉成语 【不亦乐乎】：指快乐得无法形容。 【死而后已】：死了以后才停止。形容为完成一种责任而奋斗终身。 【温故知新】 ：温习旧的知识，得到新的理解和体会。也指回忆过去，能更好地认识现在。 【任重道远】：比喻责任重大，要经历长期的奋斗。 【择善而从】：指选择好的学，按照好的做。 【见贤思齐 】：见到德才兼备的人就想向他学习，和他一样。 【三人行,必有我师】：一些人中必定有可以作为我的老师的人。指应该虚心地向一切有长处的人学习。 【己所不欲，勿施于人】：自己不想做的事情，不要强加给别人。 【岁寒松柏】：比喻在艰苦困难的条件下节操高尚。 【三省吾身】：省：检查、反省；身：自身。原指每日从多个（三和九在文言文中有多个的意思。）方面检查自己，后指多次自觉地检查自己。 ▲', poem_tags = '初中文言文,对话,学习,哲理' WHERE poem_title = '论语十则' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '江山沐浴着春光，多么秀丽，春风送来花草的芳香。\n燕子衔着湿泥忙筑巢，暖和的沙子上睡着成双成对的鸳鸯。\n\n江水碧波浩荡，衬托水鸟雪白羽毛，山峦郁郁苍苍，红花相映，便要燃烧。\n今年春天眼看就要过去，何年何月才是我归乡的日期？', poem_notes = '迟日：春天日渐长，所以说迟日。\n泥融：这里指泥土滋润、湿润。\n鸳鸯：一种水鸟，雄鸟与雌鸟常双双出没。\n花欲燃：花红似火。', poem_appreciation = '其一 　　清代的诗论家陶虞开在《说杜》一书中指出，杜集中有不少“以诗为画”的作品。这一首写于成都草堂的五言绝句，就是极富诗情画意的佳作。诗一开始，就从大处着墨，描绘出在初春灿烂阳光的照耀下，浣花溪一带明净绚丽的春景，用笔简洁而色彩浓艳。“迟日”即春日，语出《诗经·豳风·七月》“春日迟迟”。这里用以突出初春的阳光，以统摄全篇。同时用一“丽”字点染“江山”，表现了春日阳光普照，四野青绿，溪水映日的秀丽景色。这虽是粗笔勾画，笔底却是春光骀荡。\n\n　　第二句诗人进一步以和煦的春风，初放的百花，如茵的芳草，浓郁的芳香来展现明媚的大好春光。因为诗人把春风、花草及其散发的馨香有机地组织在一起，所以通过联想，可以有惠风和畅、百花竞放、风送花香的感受，收到如临其境的艺术效果。在明丽阔远的图景之上，三、四两句转向具体而生动的初春景物描绘。\n\n　　第三句诗人选择初春最常见，也是最具有特征性的动态景物来勾画。春暖花开，泥融土湿，秋去春归的燕子，正繁忙地飞来飞去，衔泥筑巢。这生动的描写，使画面更加充满勃勃生机，春意盎然，还有一种动态美。杜甫对燕子的观察十分细致，“泥融”紧扣首句，因春回大地，阳光普照才“泥融”；紫燕新归，衔泥做巢而不停地飞翔，显出一番春意闹的情状。\n\n　　第四句是勾勒静态景物。春日冲融，日丽沙暖，鸳鸯也要享受这春天的温暖，在溪边的沙洲上静睡不动。这也和首句紧相照应，因为“迟日”才沙暖，沙暖才引来成双成对的鸳鸯出水，沐浴在灿烂的阳光中，是那样悠然自适。从景物的描写来看，和第三句动态的飞燕相对照，动静相间，相映成趣。这两句以工笔细描衔泥飞燕、静睡鸳鸯，与一、二两句粗笔勾画阔远明丽的景物相配合，使整个画面和谐统一，构成一幅色彩鲜明，生意勃发，具有美感的初春景物图。就诗中所含蕴的思想感情而言，反映了诗人经过“一岁四行役”、“三年饥走荒山道”的奔波流离之后，暂时定居草堂的安适心情，也是诗人对初春时节自然界一派生机、欣欣向荣的欢悦情怀的表露。\n\n　　这首五言绝句，意境明丽悠远，格调清新。全诗对仗工整，但又自然流畅，毫不雕琢；描摹景物清丽工致，浑然无迹，是杜集中别具风格的篇章。\n\n其二 　　此诗为杜甫入蜀后所作，抒发了羁旅异乡的感慨。“江碧鸟逾白，山青花欲燃”，这是一幅镶嵌在镜框里的风景画，濡饱墨于纸面，施浓彩于图中，有令人目迷神夺的魅力。漫江碧波荡漾，显露出白翎的水鸟，掠翅江面，一派怡人的风光。满山青翠欲滴，遍布的朵朵鲜花红艳无比，简直就像燃烧着一团旺火，十分旖旎，十分灿烂。\n\n　　以江碧衬鸟翎的白，碧白相映生辉；以山青衬花葩的红，青红互为竞丽。一个“逾”字，将水鸟借江水的碧色衬底而愈显其翎毛之白，写得深中画理；而一个“欲”字，则在拟人化中赋花朵以动态，摇曳多姿。两句诗状江、山、花、鸟四景，并分别敷碧绿、青葱、火红、洁白四色，景象清新，令人赏心悦目。可是，诗人的旨意却不在此，紧接下去，笔路陡转，慨而叹之。“今春看又过，何日是归年？”句中“看又过”三字直点写诗时节。春末夏初景色不可谓不美，然而可惜岁月荏苒，归期遥遥，非但引不起游玩的兴致，却反而勾起了漂泊的感伤。此诗的艺术特点是以乐景写哀情，唯其极言春光融洽，才能对照出诗人归心殷切。它并没有让思归的感伤从景象中直接透露出来，而是以客观景物与主观感受的不同来反衬诗人乡思之深厚，别具韵致。', poem_tags = '写景,春天,山水,思乡,组诗' WHERE poem_title = '绝句二首' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '梅子黄时，家家都被笼罩在雨中，长满青草的池塘边上，传来阵阵蛙声。\n时间已过午夜，已约请好的客人还没有来，我无聊地轻轻敲着棋子，震落了点油灯时灯芯结出的疙瘩。', poem_notes = '约客：邀请客人来相会。\n黄梅时节：五月，江南梅子熟了，大都是阴雨绵绵的时候，称为“梅雨季节”，所以称江南雨季为“黄梅时节”。意思就是夏初江南梅子黄熟的时节。家家雨：家家户户都赶上下雨。形容处处都在下雨。\n处处蛙：到处是蛙声。\n有约：即为邀约友人。\n落灯花：旧时以油灯照明，灯心烧残，落下来时好像一朵闪亮的小花。落，使……掉落。灯花，灯芯燃尽结成的花状物。', poem_appreciation = '赏析 　　首句“黄梅时节家家雨”，交待了当时的环境。黄梅时节乃是立夏后数日梅子由青转黄之时，江南多雨，俗称黄梅天。其时细雨绵绵，正所谓“自在飞花轻似梦，无边丝雨细如愁”。对于视觉，是一种低沉的安慰。至于雨敲在鳞鳞千瓣的瓦上，由远而近，轻轻重重轻轻，夹着一股股的细流沿瓦槽与屋檐潺潺泄下，各种敲击音与滑音密织成网”，仿佛“谁的千指百指在按摩耳轮”，心情异常恬静安详。“青草池塘处处蛙”这句，诗人的注意力从霏霏淫雨，自然而然地转到了远远近近，此起彼伏的片片蛙声，正是这处处蛙声，烘托出了当时周遭的清静，试想，如非心如止水，神游物外，而是焦灼烦躁，何以知微渺“虫声”今夜“新透绿窗纱”？再看第三句“有约不来过夜半”。我猜想，书中之所以得出“焦灼”结论，多半便依了这句。朋友过了夜半还不来，倘若你是我，当然不免焦灼。但这是赵师秀，是“永嘉四灵”之一，人称“鬼才”的赵师秀。赵师秀，字紫芝，又字灵芝，光宗绍熙元年进士，曾任上元县主薄，筠州推官。他虽寄身仕宦，但失意消沉，常与僧道同游山水之间，向往恬静淡泊的生活，甚至还想与陶渊明一样“归寻故园”（《九客一羽衣泛舟，分韵得尊字，就送朱几仲》）。他死后，江湖派巨子戴复古作《哭赵紫芝》，说他是“东晋时人物”。当不致于“有约不来过夜半”便焦灼不安吧？最后一句“闲敲棋子落灯花”中。“闲敲”之“闲”，应当仿佛我们偶凭小几，百无聊赖，适见案头笔墨，于是顺手拿过，随随便便，漫不经心，信笔涂去，一如陆游“矮纸斜行闲作草”之意趣。赵师秀也便这样坐于灯前，遥等客人不至，百无聊赖，适见局中棋子，于是顺手拈起，随随便便，漫不经心，信手敲去，何来焦灼之感？ ▲', poem_tags = '古诗三百首,初中古诗,夏天,写景,写雨,生活' WHERE poem_title = '约客' AND poem_author = '赵师秀';
UPDATE edu_poem SET poem_translation = '赵国的侠客帽上随便点缀着胡缨，吴钩宝剑如霜雪一样明亮。\n银鞍与白马相互辉映，飞奔起来如飒飒流星。\n十步之内，稳杀一人，千里关隘，不可留行。\n完事以后，拂衣而去，不露一点声，深藏身名。\n有时空闲，步过信陵郡，来点酒饮，脱剑横在膝前。\n与朱亥一起大块吃肉，与侯嬴一道大碗喝酒。\n三杯下肚，一诺千金，义气重于五岳。\n酒后眼花耳热，意气勃勃劲生，气吞虹霓。\n朱亥挥金槌杀大将窃兵符救赵，使邯郸军民大为震惊。\n朱亥与侯嬴真千秋万古二壮士，声名煊赫大梁城。\n身为侠客纵死侠骨也留香，不愧为一世英豪。\n谁能学杨雄那个儒生，终身在书閤上，头发白了，还在书写《太玄经》。', poem_notes = '这是一首描写和歌颂侠客的古体五言诗，是李白乐府三一首中的一首。行，这里不是行走的行，而是歌行体的行，等于说“侠客的歌”。\n赵客，燕赵之地的侠客。自古燕赵多慷慨悲歌之士。《庄子·说剑》：“昔赵文王好剑，剑士夹门而客三千余人。”缦，没有花纹。胡缨，古时将北方少数民族通称为胡；缨，系冠帽的带子。缦胡缨，即少数民族做工粗糙的没有花纹的带子。这句写侠客的冠带。\n吴钩，宝刀名。霜雪明，谓宝刀的锋刃像霜雪一样明亮。\n飒沓，群飞的样子，形容马跑得快。\n这两句原自《庄子·说剑》：“臣之剑十步一人，千里不留行。”这里是说侠客剑术高强，而且勇敢。\n信陵，信陵君，战国四公子之一，为人礼贤下士，门下食客三千余人。\n朱亥、侯嬴都是信陵君的门客。朱本是一屠夫，侯原是魏国都城大梁东门的门官，两人都受到信陵君的礼遇，都为信陵君所用。炙，烤肉。啖，吃。啖朱亥，让朱亥来吃。\n这两句说，几杯酒下肚（古诗文中，三、九常是虚指）就作出了承诺，并且把承诺看得比五岳还重。\n素霓，白虹。古人认为，凡要出现不寻常的大事，就会有不寻常的天象出现，如“白虹贯日”。这句意思是，侠客重然诺、轻死生的精神感动了上天。也可以理解为，侠客这一承诺，天下就要发生大事了。这样与下文扣得更紧。\n这两句是说的朱亥锤击晋鄙的故事。信陵君是魏国大臣，魏、赵结成联盟共同对付秦国，这就是合纵以抗秦。信陵君是积极主张合纵的。邯郸，赵国国都。秦军围邯郸，赵向魏求救。魏王派晋鄙率军救赵，后因秦王恐吓，又令晋鄙按兵不动。这样，魏赵联盟势必瓦解。信陵君准备亲率家丁与秦军一拚，去向侯嬴辞行（实际是试探侯嬴），侯不语。信陵君行至半路又回来见侯嬴。侯笑着说：“我知道你会回来的。”于是为信陵君设计，串通魏王宠姬，盗得虎符，去到晋鄙军中，假托魏王令代晋鄙领军。晋鄙生疑，朱亥掏出40斤重的铁锥，击毙晋鄙。信陵君遂率魏军进击秦军，解了邯郸的围。\n扬雄曾在皇帝藏书的天禄阁任校刊工作。《太玄经》是扬雄写的一部哲学著作。', poem_appreciation = '李白这一首《侠客行》古风，抒发了他对侠客的倾慕，对拯危济难、用世立功生活的向往。\n\n　　前四句从侠客的装束、兵刃、坐骑描写侠客的外貌。\n\n　　第二个四句写侠客高超的武术和淡泊名利的行藏。\n\n　　第三个四句引入信陵君和侯嬴、朱亥的故事来进一步歌颂侠客，同时也委婉地表达了自己的抱负。侠客得以结识明主，明主借助侠客的勇武谋略去成就一番事业，侠客也就功成名就了。\n\n　　最后四句表示，即使侠客的行动没有达到目的，但侠客的骨气依然流芳后世，并不逊色于那些功成名就的英雄，写史的人应该为他们也写上一笔。\n\n　　有人认为这首《侠客行》仅仅是写朱亥、侯嬴，是不对的。前八句写的侠客的形象就与朱、侯两人不符。朱并不会剑术，而是力气大、勇敢。侯主要是智谋取胜。一句“闲过信陵饮”不过是将侠客与信陵君这样的“明君”联系起来罢了，因朱、侯都不是以这种方式结识信陵君的。李白正是想结识像信陵君这样的明主以成就自己“申管晏之谈，谋帝王之术，奋其智能，愿为辅弼，使寰区大定，海县靖一”的政治抱负。\n\n　　前人有曰：借他人故事，浇自己块垒。李白这首诗亦当如是！\n\n　　我们知道，唐代游侠之风颇为盛行，这是与唐代西域交通发达，全国经济日益繁荣，城市商业兴旺的盛唐时代有关，所以，下仅是燕赵传统的多任侠而已。特别是关陇一带的风习“融胡汉为一体，文武不殊途。”（陈寅恪：《唐代政治史述论论稿》）更促成了少年喜剑术、尚任侠的风气。李白少年时代，颇受关陇文化风习的影响，因此，他自幼勤苦读书“观百家”外，“十五好剑术”（《与韩州书》）“高冠佩雄剑”（《忆襄阳旧游赠马少府巨》）甚至，他一生都不离剑的：“抚剑夜吟啸，雄心日千里。”（《赠张相镐》其二）“长剑一杯酒，男儿方寸心。”（《赠崔侍御》）堪称是“文武不殊途”，兼备于李白一身了。那么，诗人李白何以如此爱剑呢？这和他轻财重义，尚任侠分不开。他说；“十五好剑术，遍于诸侯。”正是当时任侠流行的社会意识，为了事业心和抱负的驱使，尚任侠的少年都企求干一番豪纵、快意的事，得到社会上的普遍赞誉。李白这首《侠客行》就是以这任侠意识为旨的。\n\n　　《侠客行》是诗人李白以夸张的笔墨，从游侠的服饰开始：“赵客缦胡缨，吴钩霜雪明。银鞍照白马，飒沓如流星。”仅二十个字，仿佛全是写物而不写人。但当时游侠儿的气势、风貌，就栩栩如生的展现在目前了。因为诗人并不是为物而夸张的写物，而是处处着眼于人的精神气势而写物。“缦胡”的“缨’，“霜雪明”的”吴钩”，“飒沓如流星”的“白马”这些当时流行的任侠服饰，不仅具有典型性，而且流露出主人豪纵、慷慨之气，把物都写活了。\n\n　　诗人进而写游侠的行为：“十步杀一人，千里不留行。事了拂衣去，深藏身与名。”也仅是二十字，就高度概括了排忧解难、不图名利、尚义气、重承诺等等的高尚人格。诗人是以“纵死侠骨香，不惭世上英”的思想，加以歌赞的。事实上，诗人之所以少好任侠，乃是以此为理想人格而向往的，故能把一般的任侠社会意识，写得如此深刻而生动。\n\n　　最后，诗人以战国时“窃符救赵夺晋鄙军”中的侯赢、朱亥”二壮士”例，阐明“纵死侠骨香，不惭世上英”之旨。“闲过信陵饮，脱剑膝前横。将炙啖朱亥，持觞劝侯赢。三杯吐然诺，五岳倒为轻。眼花耳热后，意气紫霓生。救赵挥金槌，邯郸先震惊。千秋二壮士，恒赫大梁城。纵死侠骨香，不惭世上英”这“三杯吐然诺，五岳为之轻。眼花耳热后，意气紫霓生。”重然诺，尚意气的任侠，真是“慷慨成素霓，啸咤起清风。”（张华《壮士篇》）的。震撼了大梁城：“千秋二壮士”，是当之而不愧。“不惭世上英”！诗人对“二壮士”叹服不已，情见于词了。\n\n　　然而，诗人不仅在热烈的颂唱“二壮士”，同时也对校书天禄阁草《太玄经》的扬雄辈，无情地加以蔑视：“谁能书阁下，白首《太玄经》”是为壮夫所不为！\n\n　　《侠客行》诗，虽在歌颂任侠，但由于诗人就是尚任侠的，所以把诗人少年的豪情壮志，表现无遗了。\n\n　　侠客一道，是中国文化自远古遗留下来的宝贵的文化基因。这个文化基因的作用是，对于体制的强权保持一种个人的挑战，无论是真正武力上的，还是思想上的，使得体制的强权无法控制一切，使得这个文化不会完全丧失活力。到了宋代之后，在长期的王权的压制下，这个基因已经在很大程度上休眠了；而到了近代，更是又来了强势的西方文明的压制，中国人吃饭、穿衣、一举手、一投足、一动念，都变得要想一想是否符合西方人的规范，是否有“绅士风度”。因此，侠客一道的文化基因在现代中国也是离死不远了。现今的中国人还是非常喜欢武侠小说和武侠电影，但如果你真仔细想想武侠小说和武侠电影里的侠客，你会发觉那都只不过是一些可爱的小男人和小女人。作为消闲，可爱固然是可爱，但与李白诗中的那种豪侠境界却根本不能相提并论。承平世界，一切都已经由别人安排好了，管理好了，自己消闲就够了；但如果我在前面所说的新的极权世界果真降临，我们恐怕就更需要唤醒远古的基因了：“十步杀一人，千里不留行。事了拂衣去，深藏身与名。”“侠客行”，就算是某一种“眼花耳热后”的梦话吧！', poem_tags = '乐府,写人,赞颂,猖狂' WHERE poem_title = '侠客行' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '荷花凋谢连那擎雨的荷叶也枯萎了，只有那开败了菊花的花枝还傲寒斗霜。\n一年中最好的景致你一定要记住，那就是在橙子金黄、橘子青绿的秋末冬初的时节啊。', poem_notes = '刘景文：刘季孙，字景文，工诗，时任两浙兵马都监，驻杭州。苏轼视他为国士，曾上表推荐，并以诗歌唱酬往来。\n荷尽：荷花枯萎，残败凋谢。擎：举，向上托。雨盖：旧称雨伞，诗中比喻荷叶舒展的样子。\n菊残：菊花凋谢。犹：仍然。傲霜：不怕霜冻寒冷，坚强不屈。\n君：原指古代君王，后泛指对男子的敬称，您。须记：一定要记住。\n正是：一作“最是”。橙黄橘绿时：指橙子发黄、橘子将黄犹绿的时候，指农历秋末冬初。', poem_appreciation = '诗中所咏为初冬景物。为了突出“橙黄橘绿”这一年中最好的景致，诗人先用高度概括的笔墨描绘了一幅残秋的图景：那曾经碧叶接天、红花映日的渚莲塘荷，早已翠减红衰，枯败的茎叶再也不能举起绿伞，遮挡风雨了；独立疏篱的残菊，虽然蒂有余香，却亦枝无全叶，唯有那挺拔的枝干斗风傲霜，依然劲节。自然界千姿万态，一年之中，花开花落，可说是季季不同，月月有异。这里，诗人却只选择了荷与菊这两种分别在夏、秋独领风骚的花，写出它们的衰残，来衬托橙橘的岁寒之心。诗人的高明还在于，他不是简单地写出荷、菊花朵的凋零，而将描写的笔触伸向了荷叶和菊枝。终荷花之一生，荷叶都是为之增姿，不可或缺的。苏轼用擎雨无盖说荷败净尽真可谓曲笔传神！同样，菊之所以被誉为霜下之杰，不仅因为它蕊寒香冷，姿怀贞秀，还因为它有挺拔劲节的枝干。花残了，枝还能傲霜独立，才能充分体现它孤标傲世的品格。诗人的观察可谓细致矣，诗人把握事物本质的能力亦可谓强矣！这两句字面相对，内容相连，是谓“流水对”。“已无”、“犹有”，一气呵成，写出二花之异。\n\n　　可是，不论是先谢还是后凋，它们毕竟都过时了，不得不退出竞争，让位于生机盎然的初冬骄子──橙和橘。至此，诗人才满怀喜悦地提醒人们：请记住，一年中最美好的风光还是在“青黄杂糅，文章烂兮”（屈原《橘颂》）的初冬时节！这里橙橘并提，实则偏重于橘。从屈原的《橘颂》到张九龄的《感遇（江南有丹橘）》，橘树一直是诗人歌颂的“嘉树”，橘实则“可以荐嘉客”。橘树那“经冬犹绿林”、“自有岁寒心”的坚贞节操，岂止荷、菊不如，直欲与松柏媲美了。难怪诗人要对它特别垂青！\n\n　　这首诗写的是初冬的景色。作者说，虽然秋去冬来，荷尽菊残，但仍是橙黄橘绿的美好时光。诗中用“傲霜枝”作比，意在歌颂刘景文孤高傲世的高洁品格。“菊残犹有傲霜枝”，后来有人借用它比喻坚贞不屈的人。', poem_tags = '古诗三百首,小学古诗,写景,勉励,惜时' WHERE poem_title = '赠刘景文' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '（僖公三十年）晋文公和秦穆公联合围攻郑国，因为郑国曾对文公无礼，并且郑国同时依附于楚国与晋国。晋军驻扎在函陵，秦军驻扎在氾水的南面。\n\n　　佚之狐对郑伯说：“郑国处于危险之中了！假如让烛之武去见秦伯，（秦国的）军队一定会撤退。”郑伯同意了。烛之武推辞说：“我年轻时，尚且不如别人；现在老了，也不能有什么作为了。”郑文公说：“我早先没有重用您，现在由于情况危急因而求您，这是我的过错。然而郑国灭亡了，对您也不利啊！”烛之武就答应了这件事。\n\n　　在夜晚（有人）用绳子（将烛之武）从城上放下去，见到了秦伯，烛之武说：“秦、晋两国围攻郑国，郑国已经知道要灭亡了。假如灭掉郑国对您有好处，怎敢冒昧地拿这件事情来麻烦您。越过邻国把远方的郑国作为（秦国的）东部边邑，您知道这是困难的，（您）为什么要灭掉郑国而给邻邦晋国增加土地呢？邻国的势力雄厚了，您秦国的势力也就相对削弱了。如果您放弃围攻郑国而把它当作东方道路上接待过客的主人，出使的人来来往往，（郑国可以随时）供给他们缺少的东西，对您也没有什么害处。而且您曾经给予晋惠公恩惠，惠公曾经答应给您焦、瑕二座城池。 （然而）惠公早上渡过黄河回国，晚上就修筑防御工事，这是您知道的。晋国，怎么会满足呢？（现在它）已经在东边使郑国成为它的边境，又想要向西扩大边界。如果不使秦国土地亏损，将从哪里得到（他所奢求的土地）呢？削弱秦国对晋国有利，希望您考虑这件事！”秦伯非常高兴，就与郑国签订了盟约。派遣杞子、逢孙、杨孙戍守郑国，于是秦国就撤军了。\n\n　　晋大夫子犯请求出兵攻击秦军。晋文公说：“不行！假如没有那个人（秦伯）的力量，我是不会到这个地步的。依靠别人的力量而又反过来损害他，这是不仁义的；失掉自己的同盟者，这是不明智的；用散乱（的局面）代替整齐（的局面），这是不符合武德的。我们还是回去吧！”晋军也就离开了郑国。', poem_notes = '晋侯、秦伯：指晋文公和秦穆公。\n以其无礼于晋：指晋文公即位前流亡国外经过郑国时，没有受到应有的礼遇。倒装句，于晋无礼。以，因为，连词。其，代词，它，指郑国。于，对于。\n且贰于楚：并且从属于晋的同时又从属于楚。且，并且，表递进。贰，从属二主。于，对，介词。\n晋军函陵：晋军驻扎在函陵。军，名词作动词，驻军。函陵，郑国地名，在今河南新郑北。\n氾（fán）南：氾水的南面，也属郑地。（古汉语字典注，氾作水命是念作第二声。）\n佚（yì）之狐：郑国大夫。\n若：假如。使：派。见：拜见进见。从：听从。\n辞：推辞。\n臣之壮也：我壮年的时候。\n犹：尚且。\n无能为也已：不能干什么了。为，做。已，同“矣”，语气词，了。\n用：任用。\n是寡人之过也：这是我的过错。是，这。过，过错。\n然：然而。\n许之：答应这件事。许，答应。\n缒（zhuì）：用绳子拴着人（或物）从上往下运。\n既：已经。\n敢以烦执事：冒昧地拿（亡郑这件事）麻烦您手下的人。这是客气的说法。敢，冒昧的。执事，执行事务的人，对对方的敬称。\n越国以鄙（bǐ）远：（然而）越过别国而把远地（郑国）当做边邑。越，越过。鄙，边邑。\n焉用亡郑以陪邻：为什么要灭掉郑国而给邻国增加土地呢？焉：何。用：介词，表原因。陪：增加。邻：邻国，指晋国。\n邻之厚，君之薄也：邻国的势力雄厚了，您秦国的势力也就相对削弱了。之：主谓之间取消句子独立性。厚，雄厚。\n若舍郑以为东道主：如果您放弃围攻郑国而把它作为东方道路上（招待过客）的主人。舍：放弃（围郑）。\n行李：古今异义，出使的人。\n共（gōng）其乏困：供给他们缺乏的东西。共，通“供”，供给。其：代指使者。\n尝为晋君赐矣：曾经给予晋君恩惠（指秦穆公曾派兵护送晋惠公回国）。尝，曾经。为，给予。赐，恩惠。为···赐：施恩。\n许君焦、瑕：（晋惠公）许诺给您焦、瑕两城。\n朝济而夕设版焉：指晋惠公早上渡过黄河回国，晚上就修筑防御工事。济，渡河。设版，修筑防御工事。版，筑土墙用的夹板。朝，在早晨。\n厌：通“餍”，满足。\n东封郑：在东边让郑国成为晋国的边境。封，疆界。这里作用动词。\n肆其西封：扩展它西边的疆界。指晋国灭郑以后，必将图谋秦国。肆，延伸，扩张。封：疆界。\n阙（quē）：侵损，削减。盟：结盟。戍：守卫。还：撤军回国。[注：在古汉语词典中明确标注为“缺”音，仁者见仁智者见智。\n说：“说”同“悦”，喜欢，高兴。\n微夫人之力不及此：假如没有那个人的力量，我是不会到这个地步的。微：没有。夫人：远指代词，那人，指秦穆公。\n因人之力而敝之，不仁：依靠别人的力量，又返回来损害他，这是不仁道的。因：依靠。敝，损害。\n失其所与，不知：失掉自己的同盟者，这是不明智的。与，结交，亲附。知：通“智”。\n以乱易整，不武：用混乱相攻取代联合一致，是不符合武德的。易，代替。武，指使用武力是所应遵守的道义准则。不武，不符合武德。整，指一致的步调。\n吾其还也：我们还是回去吧。其，表商量或希望的语气，还是。\n去之：离开郑国。之，指代郑国。', poem_appreciation = '《烛之武退秦师》选自《春秋左传》\n\n　　说客在春秋之战中扮演着重要角色，他们穿梭来往于各国之间，或穿针引线，搭桥过河，或挑拨离间，挖敌方墙角，或施缓兵之计，赢得喘息之机。可以说，缺少了这些用现代文言汉语称为外 交家的角色，春秋舞台所上演的戏剧，必定没有这么惊心动魄，精 彩纷呈，波澜迭宕。有了他们，台前。台后两条战线上真是热闹 非凡，你方唱罢我登台，演出了古代战争史上独一无二的一幕。\n\n　　我们发现，说客或外交家除了有高超的言辞辩才，善于动之以情晓之以理之外，往往善于抓住利害关系这个关键，在利害关系上寻找弱点和突破口，从而大获成功。烛之武凭三寸不烂之舌 说退秦军，不费一兵一卒为郑国解了围，便是一桩典型的范例。\n\n　　在一个没有权威、各自为利益纷争的时代，利益原则便是行 动的最高原则，精明的说客或外交家必定深谐此道。以利益作为交往原则，关系不可能牢不可破，不可能无懈可击。甚至可以说， 晓之以利益，动之以利益，往往比其它手段更见效。即使在现代社会，国与国之闯的交往，也首先是从利益原则出发的。这个原则，恐怕比仁义原则更实际，更能长久，尽管仁义原则更值得赞 赏，可是这世上有几个讲仁义的人呢？\n\n　　讲利益原则，首先要以平等为基础。没有平等，也就在根本上取消了利益。利益必须通过交往实现，一个人不同他人发生联系，就无所谓利益；交往也意味着交换，付出多少，便得到多少， 不付出就无所获。只想获得而不愿付出，就破坏了交换，也没有了平等，也就很难再获取利益。 　　 　　交换，实质上也是让对方有利可图。烛之武去游说秦穆公，如果秦穆公觉得无利可图，会甘愿罢休吗？所谓挑拨离间，多半也要利用人们觉得有利可图的心理。离开这一点，挑拨挑间是难以成功的。搞阴谋诡计的人也常常利用这一点。“将欲取之，必先予 之”，这也是说用给予好处引人上钩，然后再将其吃掉。\n\n　　中国传统的谋咯，可以说把利益原则发挥到了极致。除了上面说的之外，还有所谓借刀杀人、过河拆桥、上屋拔梯、赏一安百、欲擒故纵、美人诱惑、坐收渔利、奇货可居、害一利百等等， 都是从不同角度利用或发挥利益原则。可以毫不夸张他说，处世为人的方方面面都与利益原则有千丝万缕的。', poem_tags = '高中文言文,古文观止,赞美,写人,谋略' WHERE poem_title = '烛之武退秦师' AND poem_author = '左丘明';
UPDATE edu_poem SET poem_translation = '大风劲吹啊浮云飞扬，\n我统一了天下啊衣锦还乡，\n怎样才能得到勇士啊为国家镇守四方！', poem_notes = '大风歌：这是汉高祖刘邦（公元前256-前195）在击破英布军以后，回长安时，途径故乡（沛县）时，邀集父老乡亲饮酒。酒酣，刘邦击筑（一种打击乐器）高歌，唱了这首《大风歌》。表达了他维护天下统一的豪情壮志。\n兮：语气词，相当于现代汉语中的语气助词“啊”。\n威：威望，权威。\n加：施加。\n海内：四海之内，即“天下”。我国古人认为天下是一片大陆，四周大海环绕，海外则荒不可知。\n安得：怎样得到。安，哪里，怎样。\n守：守护，保卫。\n四方：指代国家。', poem_appreciation = '《大风歌》整首诗仅有三句构成，这在中国历代诗歌史上是极其罕见的，三句诗中每一句都代表一个广大的不同的场景与心境，而且作者对这三句诗真可谓惜墨如金、高度凝炼。其中第一句的大风起兮云飞扬，是最令古今拍案叫绝的诗句。作者并没有直接描写他与他的麾下在恢宏的战场上是如何歼剿重创叛乱的敌军，而是非常高明巧妙地运用大风和飞扬狂卷的乌云来暗喻这场惊心动魄的战争画面。假如说项羽的《垓下歌》表现了失败者的悲哀，那么《大风歌》就显示了胜利者的悲哀。而作为这两种悲哀的纽带的，则是对于人的渺小的感伤。同样的，对第一句“大风起兮云飞扬”，唐代的李善曾解释说：“风起云飞，以喻群雄竞逐，而天下乱也。”（见汲古阁本李善注《文选》卷二十八）这是对的。“群雄竞逐而天下乱”，显然是指秦末群雄纷起、争夺天下的情状。“群雄竞逐”的“雄”，《文选》的有些本子作“凶”。倘原文如此，则当指汉初英布等人的反乱。但一则这些反乱乃是陆续发动的，并非同时并起，不应说“群凶竞逐”；再则那都是局部地区的反乱，并未蔓延到全国，不应说“天下乱”。故当以作“雄”为是。第二句，威加海内兮归故乡，只一个“威”字就是那样生动贴切地阐明了各路诸侯臣服于大汉天子刘邦的脚下，一个“威”字也直抒了刘邦的威风凛凛、所向披糜，天下无人能与之匹敌的那种巨无霸的冲天豪迈气概。这样的荣归故里，刘邦的心情是何等的荣耀与八面威风！刘邦是在说自己在这样的形势下夺得了帝位，因而能够衣锦荣归。所以，在这两句中，刘邦无异坦率承认：他之得以“威加海内”，首先有赖于“大风起兮云飞扬”的局面。但是，正如风云并非人力所能支配，这种局面也不是刘邦所造成的，他只不过运道好，碰上了这种局面而已。从这一点来说，他之得以登上帝位，实属偶然。尽管他的同时代人在这方面都具有跟他同样的幸运，而他之终于获得成功乃是靠了他的努力与才智；但对于刘邦这样出身于低微的人来说，若不是碰上如此的时代，他的努力与才智又有多少用处呢？所以，无论怎么说，他之得以当皇帝，首先是靠机运，其次才是自己的努力与才智。他以当进的人对之根本无能为力的自然界的风云变化，来比喻把他推上皇帝宝座的客观条件，至少是不自觉地显示了他的某种心理活动吧！\n\n　　姑且不论刘邦把他的这种机运看作是上天的安排抑或是一种纯粹的偶然性，但那都不是他自己所能决定的。换言之，最大限度地发挥自己的才智；但这一切到底有多大效果，还得看机运。作为皇帝，要保住天下，必须有猛士为他守卫四方，但世上有没有这样的猛士？如果有，他能否找到他们并使之为自己服务？这就并非完全取决于他自己了。第三句，安得猛士兮守四方，这最后一句比照上一句，都是直抒胸臆，写他的心情与思想，但这最后一句，刘邦关没有继续沉浸在胜利后的巨大喜悦与光环之中，而且是笔峰一转，写出内心又将面临的另一种巨大的压力。打江山难，守江山更难！居安思危，如何让自己与将士们辛劳打下的江山基业，不在日后他人觊觎中得而复失，回到故里后，去哪里挑选出更加精良的勇士来巩固自己的大好河山？ 使之大汉江山固若金汤！所以，第三句的“安得猛士兮守四方”，既是希冀，又是疑问。他是希望做到这一点的，但真的做得到吗？他自己却无从回答。可以说，他对于是否找得到捍卫四方的猛士，也即自己的天下是否守得住，不但毫无把握，而且深感忧虑和不安。也正因此，这首歌的前二句虽显得踌躇满志，第三句却突然透露出前途未卜的焦灼和恐惧。假如说，作为失败者的项羽曾经悲慨于人定无法胜天，那么，在胜利者刘邦的这首歌中也响彻着类似的悲音，这就难怪他在配合着歌唱而舞蹈时，要“慷慨伤怀，泣数行下”（《汉书·高帝纪》）了。', poem_tags = '古诗三百首,写风' WHERE poem_title = '大风歌' AND poem_author = '刘邦';
UPDATE edu_poem SET poem_translation = '在一个冬天的黄昏，城门一声轻响，一轮新月挂在半空，带着雪的山前水流缓缓。竹子做的篱笆和篱笆内的茅舍，在孤村之中一片安详的和谐。', poem_notes = '越调：宫调名。天净沙：曲牌名，入越调。\n画角：古代军中用以昏晓报警的号角。谯门：建有望楼的城门，古代为防盗和御敌，京城和州郡皆在城门建有望楼。\n水滨：靠近水的场所。\n淡烟：轻淡的烟雾。', poem_appreciation = '这首小令运用诗歌创作的传统手法，构成了诗的意境。王夫之云：“情、景名为二，而实不可离。神于诗者，妙合无垠。”白朴的这首小令，在情、景之间，正追求着“妙合无垠”的境界。\n\n　　此曲选择一个黄昏的城郊作为描绘冬景的具体环境。冷月黄昏，雪山水滨，已是清寒凛冽；淡烟衰草，茅舍孤村，又显寂寥冷落，更有谯门一声寒角，平添一分悲凉，空气中弥漫的是孤寂和无助的忧伤。它与《天净沙·秋》的写法上相近。其一，都是字字写景，全未直接抒发、陈述作者的情感。作品所要表现的情绪意蕴，是在对景物的描述中透露、折射出来的。其二，也都是通过一组自然景物的意象组合，来构成一幅富有特征的画面。另外，这支曲子所表现的情感，也不是一时一地有特定具体内容的情感，它所传达的，是一种情调，一种意绪，一种内心状态。从时序上说，《天净沙·秋》写了落日残霞，而这首曲子写的是落日已经隐没山后，新月已经现于天际。从“秋”到“冬”，从“情”到“景”，都是从寥落、凄清进一步发展为悲凉和无望的孤寂。人们或许可以把《天净沙》四首，不仅理解为对季节更替的描绘，而且进一步理解为对情感和人生体验，从欢快而明净到寥落、孤寂之间的发展。这样，这四支曲子所构成的便是内部情感联系的整体了。', poem_tags = '冬天,孤独,忧伤' WHERE poem_title = '天净沙·冬' AND poem_author = '白朴';
UPDATE edu_poem SET poem_translation = '阴山脚下啊，有敕勒族生活的大平原。敕勒川的天空啊，它的四面与大地相连，看起来好像牧民们居住的毡帐一般。\n蓝天下的草原啊，都翻滚着绿色的波澜，那风吹到草低处，有一群群的牛羊时隐时现。\n\n译文二\n辽阔的敕勒平原，就在千里阴山下，天空仿佛圆顶帐篷，广阔无边，笼罩着四面的原野。\n天空蓝蓝的，原野辽阔无边。风儿吹过，牧草低伏，显露出原来隐没于草丛中的众多牛羊。', poem_notes = '《敕勒歌》：敕勒（chì lè）：种族名，北齐时居住在朔州（今山西省北部）一带。\n敕勒川：川：平川、平原。敕勒族居住的地方，在现在的山西、内蒙一带。北魏时期把今河套平原至土默川一带称为敕勒川。\n阴山：在今内蒙古自治区北部。\n穹庐（qióng lú）：用毡布搭成的帐篷，即蒙古包。\n笼盖四野（yǎ）：笼盖，另有版本作“笼罩”（洪迈《容斋随笔》卷一和胡仔《苕溪渔隐丛话》后集卷三十一）；四野，草原的四面八方。\n天苍苍：苍苍：青色。苍，青，天苍苍，天蓝蓝的。\n茫茫：辽阔无边的样子。\n见（xiàn）：同“现”，显露。', poem_appreciation = '这是一首敕勒人唱的民歌，是由鲜卑语译成汉语的。它歌唱了大草原的景色和游牧民族的生活。\n\n　　开头两句“敕勒川，阴山下”，交代敕勒川位于高耸云霄的阴山脚下，将草原的背景衬托得十分雄伟。接着两句“天似穹庐，笼盖四野”，敕勒族人用自己生活中的“穹庐”作比喻，说天空如毡制的圆顶大帐篷，盖住了草原的四面八方，以此来形容极目远望，天野相接，无比壮阔的景象。这种景象只在大草原或大海上才能见到。最后三句“天苍苍，野茫茫，风吹草低见牛羊”是一幅壮阔无比、生机勃勃的草原全景图。“风吹草低见牛羊”，一阵风儿吹弯了牧草，显露出成群的牛羊，多么形象生动地写出了这里水草丰盛、牛羊肥壮的景象。全诗寥寥二十余字，就展现出我国古代牧民生活的壮丽图景。\n\n　　这首诗具有北朝民歌所特有的明朗豪爽的风格，境界开阔，音调雄壮，语言明白如话，艺术概括力极强。宋诗人黄庭坚说这首民歌的作者“仓卒之间，语奇如此，盖率意道事实耳”（《山谷题跋》卷七）。因为作者对草原牧民生活非常熟悉，所以能一下抓住特点，不必用力雕饰，艺术效果就很好。', poem_tags = '古诗三百首,乐府,赞美,民歌' WHERE poem_title = '敕勒歌' AND poem_author = '乐府诗集';
UPDATE edu_poem SET poem_translation = '瑟瑟的秋风吹动梧桐树叶，送来阵阵寒意，江上吹来秋风，使出门在外的我不禁思念起自己的家乡。\n家中几个小孩还在兴致勃勃地斗蟋蟀呢！夜深人静了还亮着灯不肯睡眠。', poem_notes = '萧萧：风声。\n客情：旅客思乡之情。\n挑：挑弄、引动。\n促织：俗称蟋蟀，有的地区又叫蛐蛐。\n篱落：篱笆。', poem_appreciation = '情感评析\n\n　　①作者抒发了一种思乡念亲、怀想故园的感情。\n\n　　诗中一、二两句写梧叶飘飞，寒声阵阵，秋风瑟瑟，江船漂泊，有力地烘托出诗人客居他乡、辗转漂泊的凄凉心境。三、四两句描写儿童挑灯夜游、捉弄蟋蟀的生活场景，自然容易引发诗人的联想。他会想起自己童年时代也是如此天真浪漫，开心有趣；他会想起故土家园的温馨美好；他会想起亲人朋友的音容笑貌，一种如归故里，如返童年的亲切感油然而生。\n\n　　②诗歌抒发了作者客居他乡、归无定所的孤寂落寞之感。\n\n　　一二两句写景，借落叶飘飞、秋风瑟瑟、寒气袭人烘托游子漂泊流浪、孤单寂寞的凄凉之感。一江秋水，满天黑暗，触耳寒声，诗人彻夜难眠必定是心有郁结，意有不顺。三四两句写儿童夜捉蟋蟀，兴致高昂，巧妙地反衬悲情，更显客居他乡的孤寂无奈。\n\n　　③诗歌抒发了作者对童年生活的怀念留恋的思想感情。\n\n　　通观全诗，整体而论，三、四两句写诗人客舟所见。儿童夜捉蟋蟀，兴致勃动，忘记了瑟瑟秋风、阵阵寒意，忽略了落木纷纷、秋江冷冷，深更半夜了，还津津有味地抓蟋蟀。那份专注痴迷，那份谨慎小心，那份起落不定的敏感，全在一举手一投足的举止中展露无遗。这种欢快有趣的生活场景自然容易勾起诗人对自己童年生活的追亿、留恋。一二两句也可以作这样的理解，萧萧寒声、梧叶摇落的秋景，流露出一种漂泊不定、愁绪莫名的感觉，更反衬出诗人客居他乡对童年无忧无虑生活的留恋、思念。\n\n写作手法\n\n　　①借景抒情，情景交融。全诗四句均是写景。一二两句写自然环境，三四两句写生活场子景。落木萧萧，寒声阵阵，秋风秋江，传达漂泊不定、凄怆落寞之感；秉灯夜游，捉弄蟋蟀，儿童欢悦，流露忘乎所以、得鱼忘筌之意。一悲一喜，相互映衬，均是不着痕迹地融汇在环境描写之中。\n\n　　②动静结合，以动衬静。秋叶、秋风、秋声、秋江、秋灯、秋童、秋舟、秋意，均是写动，动得有声有色、有光有影；漆黑如墨，幽深莫测，黑暗无边，这是写静，静得凄神寒骨、惆怅满怀。萧萧风声，顽皮儿童，这些动态情景巧妙地反衬出深秋半夜的幽深寂静，更引发人们对寒凉静夜中诗人那颗愁绪难眠的苦况心灵的体味。\n\n　　③ 悲欢对比，以欢衬悲。一二句写景，秋风扫落叶，长天送寒意，是悲景，传悲情；三四句写人，深夜挑促织，明灯照篱落，是乐景，传欢情。悲喜交加，以欢衬悲，更显游子流浪天涯的孤寂无奈、惆怅无眠。\n\n　　④传情达意，暗用典故。“江上秋风动客情”暗用张翰典故。据传晋人张翰官居洛阳，见秋风起而思念故乡，于是辞官回乡，了却心愿。诗句传达了诗人久居在外、归家不得、思家念亲的思想感情。\n\n　　⑤ 拟人、通感，增辉添彩。“萧萧梧叶送寒声，江上秋风动客情”，一“送”一“动”，寓情于物，赋予梧叶、秋风以人的情态意绪。这些物态声情的诗文，似乎把读者带进了一种风送寒凉、情动秋江的意境之中，痴迷难返，惆怅满怀。“萧萧梧叶送寒声”妙用通感，以萧萧之声催发寒秋之感，用听觉形象沟通触觉感受，意味深长。\n\n　　⑥ 字斟句酌，“寒”“挑”传神。“寒”字一语双方，既有秋风袭来寒凉逼人之感，更有落泊天涯心神凄清之意。“挑”字于细节逼真见妙趣。儿童的专注敏感、精挑细翻，儿童的屏息观察、惊喜兴奋，全在一“挑”。\n\n　　⑦ 虚实结合，以实映虚。全诗四句写景写人，所见所闻，或明或暗，全是写实。满耳秋声，满目秋夜，一江秋水，一群儿童，犹如场景写真，给人以如闻其声，如见其人，如临其境之感。这活灵活现的场景写实巧妙地传达出诗人愁绪满怀、长夜难眠的凄清孤寂之情。实中有虚（客情），寓虚（情）于实，以实映虚，言有尽而意无穷！', poem_tags = '小学古诗,写景,思念' WHERE poem_title = '夜书所见' AND poem_author = '叶绍翁';
UPDATE edu_poem SET poem_translation = '少小时就没有随俗气韵，自己的天性是热爱自然。\n偶失足落入了仕途罗网，转眼间离田园已十余年。\n笼中鸟常依恋往日山林，池里鱼向往着从前深渊。\n我愿在南野际开垦荒地，保持着拙朴性归耕田园。\n绕房宅方圆有十余亩地，还有那茅屋草舍八九间。\n榆柳树荫盖着房屋后檐，争春的桃与李列满院前。\n远处的邻村舍依稀可见，村落里飘荡着袅袅炊烟。\n深巷中传来了几声狗吠，桑树顶有雄鸡不停啼唤。\n庭院内没有那尘杂干扰，静室里有的是安适悠闲。\n久困于樊笼里毫无自由，我今日总算又归返林山。', poem_notes = '少：指少年时代。适俗：适应世俗。韵：本性、气质。一作“愿”。\n尘网：指尘世，官府生活污浊而又拘束，犹如网罗。这里指仕途。\n三十年：有人认为是“十三年”之误（陶渊明做官十三年）。一说，此处是三又十年之意（习惯说法是十又三年），诗人意感“一去十三年”音调嫌平，故将十三年改为倒文。\n羁（ji）鸟：笼中之鸟。恋：一作“眷”。\n池鱼：池塘之鱼。鸟恋旧林、鱼思故渊，借喻自己怀恋旧居。\n野：一作“亩”。际：间。\n守拙（zhuō）：意思是不随波逐流，固守节操。\n方宅：宅地方圆。一说，“方”通“旁”。\n荫（yìn）：荫蔽。\n罗：罗列。\n暧暧（ài）：昏暗，模糊。\n依依：轻柔而缓慢的飘升。墟里：村落。\n户庭：门庭。尘杂：尘俗杂事。\n虚室：空室。余闲：闲暇。\n樊（fán）笼：蓄鸟工具，这里比喻官场生活。樊，藩篱，栅栏。\n返自然：指归耕园田。', poem_appreciation = '陶渊明因无法忍受官场的污浊与世俗的束缚，坚决地辞官归隐，躬耕田园。脱离仕途的那种轻松之感，返回自然的那种欣悦之情，还有清静的田园、淳朴的交往、躬耕的体验，使得这组诗成为杰出的田园诗章。\n\n　　这组诗生动地描写了诗人归隐后的生活和感受，抒发了作者辞官归隐后的愉快心情和乡居乐趣，从而表现了他对田园生活的热爱，表现出劳动者的喜悦；同时又隐含了对官场黑暗腐败的生活的厌恶之感，表现了作者不愿同流合污，为保持完整的人格和高尚的情操而甘受田间生活的艰辛。组诗集中体现了陶渊明追求自由、安于清贫、隐逸山野、洁身自好、远离官场、超脱世俗的美好情操。陶渊明写“归园田居”其实是写作者自己理想的故居。\n\n　　《归园田居》是一个不可分割的有机整体。其所以是如此，不仅在于每首诗分别从辞官场，聚亲朋，乐农事，访故旧，欢夜饮几个侧面描绘了诗人丰富充实的隐居生活，更重要的是，就其所抒发的感情而言，是以质性自然，乐在其中的情趣来贯穿这一组诗篇的。诗中虽有感情的动荡，转折，但那种欢愉，达观的明朗色彩是辉映全篇的。\n\n　　第一首诗主要是以追悔开始，以庆幸结束，追悔自己“误落尘网”、“久在樊笼”的压抑与痛苦，庆幸自己终“归园田”、复“返自然”的惬意与欢欣，真切表达了诗人对污浊官场的厌恶，对山林隐居生活的无限向往与怡然陶醉。\n\n　　“少无适俗韵，性本爱丘山。”所谓“适俗韵”无非是逢迎世俗、周旋应酬、钻营取巧的那种情态、那种本领，这是诗人从来就未曾学会的东西。作为一个真诚率直的人，其本性与淳朴的乡村、宁静的自然，似乎有一种内在的共通之处，所以“爱丘山”。前二句表露了作者清高孤傲、与世不合的性格，看破官场后，执意离开，对官场黑暗的不满和绝望。为全诗定下一个基调，同时又是一个伏笔，它是诗人进入官场却终于辞官归田的根本原因。\n\n　　“误落尘网中，一去三十年。”人生常不得已。作为一个官宦人家的子弟，步入仕途乃是通常的选择；作为一个熟读儒家经书、欲在社会中寻求成功的知识分子，也必须进入社会的权力组织；便是为了供养家小、维持较舒适的日常生活，也需要做官。所以不能不违逆自己的“韵”和“性”，奔波于官场。回头想起来，那是误入歧途，误入了束缚人性而又肮脏无聊的世俗之网。“一去三十年”，当是“十三年”之误。从陶渊明开始做官到最终归隐，正好是十三年。这一句看来不过是平实的纪述，但仔细体味，却有深意。诗人对田园，就像对一位情谊深厚的老朋友似地叹息道：“呵，这一别就是十三年了！”心中无限感慨，无限眷恋，但写来仍是隐藏不露。\n\n　　“羁鸟恋旧林，池鱼思故渊。”虽是“误入尘网”，却是情性未移。这两句集中描写做官时的心情，从上文转接下来，语气顺畅，毫无阻隔。因为连用两个相似的比喻，又是对仗句式，便强化了厌倦旧生活、向往新生活的情绪。\n\n　　“开荒南野际，守拙归园田”，“守拙”回应“少无适俗韵”——因为不懂得钻营取巧，不如抱守自己的愚拙，无须勉强混迹于俗世；“归园田”回应“性本爱丘山”——既有此天性，便循此天性，使这人生自然舒展，得其所好。开始所写的冲突，在这里得到了解决。\n\n　　“方宅十余亩，草屋八九间”，是简笔的勾勒，以此显出主人生活的简朴。但虽无雕梁画栋之堂皇宏丽，却有榆树柳树的绿荫笼罩于屋后，桃花李花竞艳于堂前，素淡与绚丽交掩成趣。\n\n　　“暧暧远人村，依依墟里烟。”暧暧，是模糊不清的样子，村落相隔很远，所以显得模糊，就像国画家画远景时，往往也是淡淡勾上几笔水墨一样。依依，形容炊烟轻柔而缓慢地向上飘升。这两句所描写的景致，给人以平静安详的感觉，好像这世界不受任何力量的干扰。\n\n　　“狗吠深巷中，鸡鸣桑树颠”，一下子将这幅美好的田园画活起来了。这二句套用汉乐府《鸡鸣》“鸡鸣高树颠，狗吠深宫中”而稍加变化。但诗人绝无用典炫博的意思，不过是信手拈来。他不写虫吟鸟唱，却写了极为平常的鸡鸣狗吠，因为这鸡犬之声相闻，才最富有农村环境的特征，和整个画面也最为和谐统一。隐隐之中，是否也渗透了《老子》所谓“小国寡民”、“鸡犬之声相闻，民老死不相往来”的理想社会观念，那也难说。单从诗境本身来看，这二笔是不可缺少的。它恰当地表现出农村的生活气息，又丝毫不破坏那一片和平的意境，没有喧嚣和烦躁之感。以此比较王籍的名句“蝉噪林逾静，鸟鸣山更幽”，那种为人传诵的所谓“以动写静”的笔法，未免太强调、太吃力。\n\n　　“户庭无尘杂，虚室有余闲。”尘杂是指尘俗杂事，虚室就是静室。既是做官，总不免有许多自己不愿干的蠢事，许多无聊应酬吧。如今可是全都摆脱了，在虚静的居所里生活得很悠闲。不过，最令作者愉快的，倒不在这悠闲，而在于从此可以按照自己的意愿生活。\n\n　　“久在樊笼里，复得返自然。”自然，既是指自然的环境，又是指顺适本性、无所扭曲的生活。这两句再次同开头“少无适俗韵，性本爱丘山”相呼应，同时又是点题之笔，揭示出《归园田居》的主旨。但这一呼应与点题，丝毫不觉勉强。全诗从对官场生活的强烈厌倦，写到田园风光的美好动人，新生活的愉快，一种如释重负的心情自然而然地流露了出来。这样的结尾，既是用笔精细，又是顺理成章。\n\n　　这首诗最突出的是写景———描写园田风光运用白描手法远近景相交，有声有色；其次，诗中多处运用对偶句，如：“榆柳荫后檐，桃李罗堂前。”还有对比手法的运用，将“尘网”“樊笼”与“园田居”对比，从而突出诗人对官场的厌恶、对自然的热爱；再有语言明白清新，几如白话，质朴无华。这首诗呈现出一个完整的意境，诗的语言完全为呈现这意境服务，不求表面的好看，于是诗便显得自然。总之，这是经过艺术追求、艺术努力而达到的自然。', poem_tags = '古诗三百首,田园,生活,写狗古诗18首' WHERE poem_title = '归园田居·其一' AND poem_author = '陶渊明';
UPDATE edu_poem SET poem_translation = '朱雀桥边一些野草开花，乌衣巷口唯有夕阳斜挂。\n当年王导、谢安檐下的燕子，如今已飞进寻常百姓家中。', poem_notes = '朱雀桥：在金陵城外，乌衣巷在桥边。 在今南京市东南，在文德桥南岸，是三国东吴时的禁军驻地。由于当时禁军身着黑色军服，所以此地俗语称乌衣巷。在东晋时以王导、谢安两大家族，都居住在乌衣巷，人称其子弟为“乌衣郎”。入唐后，乌衣巷沦为废墟。现为民间工艺品的汇集之地。\n乌衣燕子，旧时王谢之家庭多燕子。今江苏省南京市江宁区，横跨秦淮河。\n寻常：平常。\n王谢：王导、谢安，晋相，世家大族，贤才众多，皆居巷中，冠盖簪缨，为六朝(吴、东晋、宋齐梁陈先后建都于建康即今之南京)巨室。至唐时，则皆衰落不知其处。\n旧时：晋代。', poem_appreciation = '《乌衣巷》这是唐朝诗人 刘禹锡感慨藏而不露，寄物咏怀的名篇，是组诗《金陵五题》中的一篇。诗人当时还没到过金陵，始终对这个六朝古都怀着憧憬，正好有友人将自己写的五首咏金陵古迹诗给他看，他便乘兴和了五首。乌衣巷原是六朝贵族居住的地方，最为繁华，如今有名的朱雀桥边竟长满野草，乌衣巷口也不见车马出入，只有夕阳斜照在昔日的深墙上。\n\n　　这是一首怀古诗。凭吊东晋时南京秦淮河上朱雀桥和南岸的乌衣巷的繁华鼎盛，而今野草丛生，荒凉残照。感慨沧海桑田，人生多变。以燕栖旧巢唤起人们想象，含而不露；以“野草花”、“夕阳斜”涂抹背景，美而不俗。语虽极浅，味却无限。\n\n　　施补华的《岘佣说诗》评这首诗的三、四句时说：“若作燕子他去，便呆。盖燕子仍入此堂，王谢零落，已化作寻常百姓矣。如此则感慨无穷，用笔极曲。本诗感慨藏而不露，寄物咏怀的名篇，是组诗《金陵五题》中的一篇。\n\n　　首句“朱雀桥边野草花”，朱雀桥横跨南京秦淮河上，是由市中心通往乌衣巷的必经之路。桥同河南岸的乌衣巷，不仅地点相邻，历史上也有瓜葛。东晋时，乌衣巷是高门土族的聚居区，开国元勋王导和指挥淝水之战的谢安都住在这里。旧日桥上装饰着两只铜雀的重楼，就是谢安所建。在字面上，朱雀桥又同乌衣巷偶对天成。用朱雀桥来勾画乌衣巷的环境，既符合地理的真实，又能造成对仗的美感，还可以唤起有关的历史联想，是“一石三鸟”的选择。句中引人注目的是桥边丛生的野草和野花。草长花开，表明时当春季。“草花”前面按上一个“野”字，这就给景色增添了荒僻的气象。再加上这些野草野花是滋蔓在一向行旅繁忙的朱雀桥畔，这就使我们想到其中可能包含深意。\n\n　　记得作者在“万户千门成野草”（《台城》）的诗句中，就曾用“野草”象征衰败。现在，在这首诗中，这样突出“野草花”，不正是表明，昔日车水马龙的朱雀桥，今天已经荒凉冷落了吗！\n\n　　第二句“乌衣巷口夕阳斜”，表现出乌衣巷不仅是映衬在败落凄凉的古桥的背景之下，而且还呈现在斜阳的残照之中。句中作“斜照”解的“斜”字，同上句中作“开花”解的“花”字相对应，全用作动词，它们都写出了景物的动态。“夕阳”，这西下的落日，再点上一个“斜”字，便突出了日薄西山的惨淡情景。本来，鼎盛时代的乌衣巷口，应该是衣冠来往、车马喧阗的。而现在，作者却用一抹斜晖，使乌衣巷完全笼罩在寂寥、惨淡的氛围之中。\n\n　　经过环境的烘托、气氛的渲染之后，按说，似乎该转入正面描写乌衣巷的变化，抒发作者的感慨了。但作者没有采用过于浅露的写法，诸如，“乌衣巷在何人住，回首令人忆谢家”（孙元宴《咏乌衣巷》）、“无处可寻王谢宅，落花啼鸟秣陵春”（无名氏）之类；而是继续借助对景物的描绘，写出了脍炙人口的名句：“旧时王谢堂前燕，飞入寻常百姓家”。他出人意料地忽然把笔触转向了乌衣巷上空正在就巢的飞燕，让人们沿着燕子飞行的去向去辨认，如今的乌衣巷里已经居住着普通的百姓人家了。\n\n　　为了使读者明白无误地领会诗人的意图，作者特地指出，而今这些飞入普通老百姓家筑巢的燕子，以往却是栖息在王导、谢安两家权门高大厅堂的檐檩之上的旧燕。“旧时”两个字，赋予燕子以历史见证人的身份。“寻常”两个字，又特别强调了今日的老百姓是多么不同于往昔。从中，我们可以清晰地听到作者对这一变化发出的沧海桑田的无限感慨。飞燕形象的设计，好像信手拈来，实际上凝聚着作者的艺术匠心和丰富的想象力。晋傅咸《燕赋序》说：“有言燕今年巢在此，明年故复来者。其将逝，剪爪识之。其后果至焉。”当然生活中，即使是寿命极长的燕子也不可能是四百年前“王谢堂前”的老燕。但是作者抓住了燕子作为候鸟有栖息旧巢的特点，这就足以唤起读者的想象，暗示出乌衣巷昔日的繁荣，起到了突出今昔对比的作用。《乌衣巷》在艺术表现上集中描绘乌衣巷的现况；对它的过去，仅仅巧妙地略加暗示。诗人的感慨更是藏而不露，寄寓在景物描写之中。因此它虽然景物寻常，语言浅显，却有一种蕴藉含蓄之美，使人读起来余味无穷。\n\n　　这首诗写诗人对盛衰兴败的深沉感慨。朱雀桥和乌衣巷依然如故，但野草丛生，夕阳已斜。荒凉的景象，已经暗含了诗人对荣枯兴衰的敏感体验。后二句藉燕子的栖巢，表达作者对世事沧桑、盛衰变化的慨叹，用笔尤为曲折。此诗为刘禹锡著名的咏史诗《金陵五题》中的第二首。', poem_tags = '唐诗三百首,地名,怀古,早教古诗100首' WHERE poem_title = '乌衣巷' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '风萧萧地响把易水岸边吹得很冷，壮士荆轲去了就再也不回来了。刺杀秦王就像是到虎穴到龙宫一样危险啊，但是我们的英雄英勇的气概，连仰天吐气都能形成白虹．史书上说，高渐离击筑，荆轲悲歌“风萧萧兮易水寒，壮士一去兮不复还”，唱得太悲壮了，以至于听者嗔目，发尽上指。\n一段唱毕，只听见荆轲仰头长叹一声，天空中居然出现一道七彩虹。高渐离趁势变了一个调，乐音显得更为激昂，荆轲继而唱道：探虎穴兮入蛟宫，仰天呼气兮成白虹。太子丹最后被彻底地感动了，跪在地上向荆轲敬了一杯酒。', poem_notes = '萧萧：指风声。易水：指水名，源出河北省易县，是当时燕国的南界。\n兮：语气助词。\n壮士：在这里指荆轲。', poem_tags = '古诗三百首,爱国,悲歌' WHERE poem_title = '荆轲歌 / 渡易水歌' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '曾经到临过沧海，别处的水就不足为顾；除了巫山，别处的云便不称其为云。\n仓促地由花丛中走过，懒得回头顾盼；这缘由，一半是因为修道人的清心寡欲，一半是因为曾经拥有过的你。', poem_notes = '曾经：曾经到临。经：经临，经过。\n难为：这里指“不足为顾”“不值得一观”的意思。\n除却：除了，离开。这句意思为：相形之下，除了巫山，别处的云便不称其为云。此句与前句均暗喻自己曾经接触过的一段恋情。\n取次：草草，仓促，随意。这里是“匆匆经过”“仓促经过”或“漫不经心地路过”的样子。不应解释为“按次序走过”。例：宋陆游《秋暑夜兴》诗：“呼童持烛开藤纸，一首清诗取次成。”元朱庭玉《青杏子·送别》曲：“肠断处，取次作别离。”\n花丛：这里并非指自然界的花丛，乃借喻美貌女子众多的地方，暗指青楼妓馆。\n半缘：此指“一半是因为……”。\n修道：指修炼道家之术。此处阐明的是修道之人讲究清心寡欲。\n君：此指曾经心仪的恋人。', poem_appreciation = '“曾经沧海难为水，除却巫山不是云。”这句话的意思：经历过无比深广的沧海的人，别处的水再难以吸引他；除了云蒸霞蔚的巫山之云，别处的云都黯然失色。\n\n　　以沧海之水和巫山之云隐喻爱情之深广笃厚，见过大海、巫山，别处的水和云就难以看上眼了，除了诗人所念、钟爱的女子，再也没有能使我动情的女子了。诗人的这个“心上人”，据说是双文，即诗人所写传奇《莺莺传》中莺莺的原型，诗人因双文出身寒门而抛弃她后，有八九年“不向花回顾”（《梦游春七十韵》）。又有人说此诗是为悼念亡妻韦丛而作，韦丛出身高门，美丽贤慧，二十七岁早逝后，诗人曾表示誓不再娶（《遣悲怀·之三》）。两句诗化用典故，取譬极高。前句典出《孟子·尽心上》“观于海者难为水”；后句典出宋玉《高唐赋序》“妾在巫山之阳，高丘之阻、旦为朝云、暮为行雨。后人引用这两句诗，多喻指对爱情的忠诚，说明非伊莫属、爱不另与。这两句诗还简缩为成语“曾经沧海”，还可比喻曾经经历过很大的场面，眼界开阔，见多识广，对比较平常的事物不放在眼里。', poem_tags = '爱情,哲理,悼亡,早教古诗100首' WHERE poem_title = '离思五首·其四' AND poem_author = '元稹';
UPDATE edu_poem SET poem_translation = '桂花从天而降，好像是月上掉下来似的。拾起殿前的桂花，只见其颜色洁白、新鲜。\n我到现在也不明白吴刚为什么要跟桂花树过不去。这桂花大概是嫦娥撒下来给予众人的吧。', poem_notes = '天竺寺：今称法镜寺，位于灵隐山（飞来峰）山麓。\n桂子：特指为桂花，本质是樟科植物天竺桂的果实。\n露华新：桂花瓣带着露珠更显湿润。\n嫦娥：多种说法，有说中国神话人物、后羿之妻等。', poem_appreciation = '第一句，描述了桂花像是月上掉下来似的场景，交待了诗人所处的时间是中秋之夜，奠定了全诗是充满了轻松，了联想的基调。\n\n　　第二句，诗人捡起殿前的桂花，桂花的颜色洁白而新鲜，阐述了诗人是享受中秋之夜的景色的，也表明了诗人此时在人生道路上是顺畅的。\n\n　　第三句，通过传说透露出了诗人对桂花的怜惜，展现了诗人对美好事物的向往，阐述了诗人是热爱自然，怜惜自然的。\n\n　　第四句，感叹到桂花飘落是因为传说中的嫦娥撒下来给予众人的吧，通过丰富的联想，烘托出诗人是拥有包含万事万物的心境的。\n\n　　这首绝句描状桂花，那珊珊而落的桂花，本洁如玉，映于月光更显晶莹，拾起花犹带露更觉滋润，想来当是嫦娥撒于人间。全诗以中秋一事出中秋佳节玩月之全情，有以小见大之妙。综合此诗，神话传说中吴刚学仙有过，遭天帝惩罚到月宫砍伐桂树，其树随砍随合，所以必须不断砍伐，却始终砍不倒这棵树。但此诗并不如其它描写中秋诗作一般凄凉，凋零，或是额怅、哀绵，全诗给人的感觉是轻松自在，毫无忧愁的。虽只描写了一幅“夜赏月桂图”，却让读者得知民俗——中秋必看月赏桂。内容是诗人的联想，却不让人觉得有空虚之意。巧妙的联想反而为“寂静”的诗作平添了几分“俏皮”。不禁让人对古人的中秋佳节浮想联翩。', poem_tags = '小学古诗,中秋节,桂花' WHERE poem_title = '天竺寺八月十五日夜桂子' AND poem_author = '皮日休';
UPDATE edu_poem SET poem_translation = '江南又到了适宜采莲的季节了，莲叶浮出水面，挨挨挤挤，重重叠叠，迎风招展。在茂密如盖的荷叶下面，欢快的鱼儿在不停的嬉戏玩耍。\n一会儿在这儿，一会儿又忽然游到了那儿，说不清究竟是在东边，还是在西边，还是在南边，还是在北边。', poem_notes = '汉乐府：原是汉初采诗制乐的官署，后来又专指汉代的乐府诗。汉惠帝时，有乐府令一官，可能当时已设有乐府。武帝时乐府规模扩大，成为一个专设的官署，掌管郊祀、巡行、朝会、宴飨时的音乐，兼管采集民间歌谣，以供统治者观风察俗，了解民情厚薄。这些采集来的歌谣和其他经乐府配曲入乐的诗歌即被后人称为乐府诗。\n田田：荷叶茂盛的样子。\n可：在这里有“适宜” 、“ 正好”的意思。', poem_appreciation = '这是一首汉代乐府民歌中的采莲歌，全诗没有一字一句直接描写采莲人采莲时的愉快心情，而是通过对莲叶和鱼儿的描绘，将它们的欢乐之情充分透露了出来，仿佛亲耳听到和亲眼看见许多采莲男女的歌声和笑语声融成一片，许多小伙子和采莲姑娘们还在调情求爱。\n\n　　首先，此歌起句“江南可采莲”，其中的“可”字已透露出消息。莲花本来是大江南北湖泽沟塘中常见的人工栽培植物，可这位歌者（亦即诗中未露的男主人公）却偏要说“江南可采莲”，这是因为莲花栽培的地区虽然很广，但却以江南最盛；而江南采莲人大都是青年男女，尤以青年妇女为主；同时江南民风柔靡，青年男女在采莲时调情求爱之事极为常见，故盛行于南朝时期的民间情歌，在汉代的江南实际上就很流行。在这类民间情歌中常用比兴、双关手法，以“莲”谐“怜”，象征爱情。由此可见，此歌用的显然也是比兴、双关手法。起句中的“采莲”，也含有寻欢求爱的意思。由此可推知这位歌者乃是一个风流小生，他可能不是江南人，而是从外乡来到江南的。他来江南名为采莲，实际上是“醉翁之意不在酒”，否则何处不可采莲，而独留恋于江南，可见“可”字之中的寓意。\n\n　　其次，紧承上句而来的第二句“莲叶何田田”，显然也是明写莲叶茂美，暗喻采莲姑娘们人数众多，姿态丰美的。而第三句“鱼戏莲叶间”和后四句“鱼戏莲叶东，鱼戏莲叶西，鱼戏莲叶南，鱼戏莲叶北”，则是以鱼儿戏水于莲叶间暗喻采莲男女调情求爱的欢乐情景。这也是民间情歌中常用的表现手法。由此可见，这首采莲歌实际上乃是一首与劳动相结合的情歌。\n\n　　这首歌辞只有七句，明白如话，而后四句又基本上是第三句的重复，它的妙处究主要在于运用民歌中常用的比兴、双关手法，把男女之间调情求爱的欢乐之情写得极其委婉、含蓄，耐人寻味，而无轻佻、庸俗之弊。全诗一气呵成，但在结构上又可分为两个部分：前三句揭示题旨；后四句进一步展示采莲时的欢乐情景和广阔场面。而诗中第三句又在全诗中起着承上启下的作用，使上下相连，不着痕迹。诗的意境清新、开朗，寓情于景，景中寓人，如闻其声，如见其人，如临其境，感到美景如画，心旷神怡，呈现出一派生意盎然的景象。\n\n　　这首诗在乐府分类中属《相和歌辞》，“相和歌”本是两人唱和，或一个唱、众人和的歌曲，故“鱼戏莲叶东”四句，可能为和声。故此诗的前两句可能为男歌者领唱；第三句为众男女合唱；后四句当是男女的分组和唱。如此，则采莲时的情景，更加活泼有趣，因而也更能领会到此歌表现手法的高妙。\n\n　　诗中“东”、“西”、“南”、“北”并列，极易流于呆板，但此歌如此铺排，却显得文情恣肆，极为生动，从而充分体现了歌曲反复咏唱，余味无穷之妙。', poem_tags = '古诗三百首,民歌,写景,写人,爱情' WHERE poem_title = '江南' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '臣李密陈言：我因命运不好，很早就遭遇到了不幸，刚出生六个月，父亲就弃我而死去。我四岁的时候，舅父强迫母亲改变了守节的志向。我的祖母刘氏，怜悯我年幼丧父，便亲自抚养。臣小的时候经常生病，九岁时不能走路。孤独无靠，一直到成人自立。既没有叔叔伯伯，又缺少兄弟，门庭衰微、福分浅薄，很晚才有儿子。在外面没有比较亲近的亲戚，在家里又没有照应门户的童仆，生活孤单没有依靠，只有自己的身体和影子相互安慰。但祖母刘氏又早被疾病缠绕，常年卧床不起，我侍奉她吃饭喝药，从来就没有离开她。\n　　到了晋朝建立，我蒙受着清明的政治教化。先前有名叫逵的太守，察举臣为孝廉，后来又有名叫荣的刺史推举臣为优秀人才。臣因为供奉赡养祖母的事无人承担，辞谢不接受任命。朝廷又特地下了诏书，任命我为郎中，不久又蒙受国家恩命，任命我为太子的侍从。我凭借卑微低贱的身份，担当侍奉太子的职务，这实在不是我杀身所能报答朝廷的。我将以上苦衷上表报告，加以推辞不去就职。但是诏书急切严峻，责备我怠慢不敬。郡县长官催促我立刻上路；州县的长官登门督促，比流星坠落还要急迫。我很想奉旨为皇上奔走效劳，但祖母刘氏的病却一天比一天重；想要姑且顺从自己的私情，但报告申诉不被允许。我是进退两难，十分狼狈。\n　　我想晋朝是用孝道来治理天下的，凡是年老而德高的旧臣，尚且还受到怜悯养育，况且我孤单凄苦的程度更为严重呢。况且我年轻的时候曾经做过蜀汉的官，担任过郎官职务，本来就希望做官显达，并不顾惜名声节操。现在我是一个低贱的亡国俘虏，十分卑微浅陋，受到过分提拔，恩宠优厚，怎敢犹豫不决而有非分的企求呢？只是因为祖母刘氏寿命即将终了，气息微弱，生命垂危，早上不能想到晚上怎样。我如果没有祖母，无法达到今天的地位；祖母如果没有我的照料，也无法度过她的余生。祖孙二人，互相依靠而维持生命，因此我不能废止侍养祖母而远离。\n　　我现在的年龄四十四岁了，祖母现在的年龄九十六岁了，这样看来我在陛下面前尽忠尽节的日子还很长，而在祖母刘氏面前尽孝尽心的日子很短。我怀着乌鸦反哺的私情，乞求能够准许我完成对祖母养老送终的心愿。我的辛酸苦楚，并不仅仅是蜀地的百姓及益州、梁州的长官所能明白知晓的，天地神明，实在也都能明察。希望陛下能怜悯我的诚心，满足我微不足道的心愿，使祖母刘氏能够侥幸地保全她的余生。我活着应当杀身报效朝廷，死了也要结草衔环来报答陛下的恩情。我怀着像犬马一样不胜恐惧的心情，恭敬地呈上此表来使陛下知道这件事。', poem_notes = '“表”是一种文体，是古代奏章的一种，是臣下对君王指陈时事、直言规劝抑或使之改正错误的文体。\n【臣以险衅，夙遭闵凶】\n以：因险衅(xiǎnxìn)：凶险祸患(这里指命运不好)。 险，艰难，祸患；衅，灾祸\n夙：早时， 这里指年幼的时候。\n闵：通“悯”，指可忧患的事（多指疾病死丧）\n凶：这里指他家中不幸的事\n【慈父见背】\n见背：背离我，离我而去。这是死的委婉说法。指弃我而死去。\n【行年四岁，舅夺母志】\n行年：经历的年岁\n舅夺母志：舅舅强行改变母亲想要守节的志愿。这是母亲改嫁的委婉说法\n【祖母刘悯臣孤弱，躬亲抚养】\n悯：怜悯。苏教版作“愍”。\n躬亲：亲自\n【至于成立】\n至于：直到。\n于：介词，引出对象\n成立： 成人自立\n【终鲜兄弟】\n终：又；\n鲜：少，这里指“无”的意思\n【门衰祚薄，晚有儿息】\n门：家门。\n门衰祚薄：家门衰微，福分浅薄；祚（zuò）：福分\n儿息：同子息、生子；息：亲生子女。又如：息子(亲生儿子)；息女(亲生女儿)；息男(亲生儿子)\n【外无期功强近之亲】\n期：满一周年。\n功：服丧九月为大功，服丧五月为小功。这都指关系比较近的亲属。“期功”意为“穿一周年孝服的人”。\n强近：勉强算是接近的\n【内无应门，五尺之僮】\n应门：照应门户。\n五尺之僮：五尺高的小孩。僮：童仆\n【茕茕孑立，形影相吊】\n茕茕：孤单的样子\n孑：孤单 孑立：苏教版作“独立”\n吊：安慰\n【夙婴疾病，常在床蓐】\n婴：缠绕，这里指疾病缠身\n蓐：陈草复生。引申为草垫子、草席。\n【臣侍汤药，未曾废离】\n废：废止，停止服侍\n离：离开\n【逮奉圣朝，沐浴清化】\n逮：及，到\n奉：承奉\n圣朝：指晋朝\n沐浴清化：恭维之辞，指蒙受清平的政治教化\n【前太守臣逵察臣孝廉，后刺史臣荣举臣秀才】\n察：考察和推举\n孝廉：汉代以来选拔人才的一种察举科目，即每年由地方官考察当地的人物，向朝廷推荐孝顺父母、品行廉洁的人出来做官\n举：推举\n秀才：汉代以来选拔人才的一种察举科目。这里是优秀人才的意思，与后代科举的“秀才”含义不同。\n【辞不赴命】\n辞：辞谢。\n赴：接受。\n命：任命。\n【拜臣郎中】\n拜：授予官职\n郎中：尚书省的属官\n【寻蒙国恩，除臣洗马】\n寻：不久\n除：拜官受职\n洗马：即太子冼马（xiǎn)，太子的侍从官\n【猥以微贱，当侍东宫，非臣陨首所能上报】\n猥：自谦之词，犹“鄙”\n微贱：卑微低贱\n当：担任\n东宫：指太子，因太子居住在东宫，这里是借代\n陨首：头落地，指杀身。陨，落\n【诏书切峻，责臣逋慢】\n切峻：急切而严厉\n逋慢：有意回避，怠慢上命。逋：逃脱 慢：怠慢，轻慢。\n【急于星火】\n急于星火：于星火急。于：比 星火：流星的光 比流星的坠落还要急。指催逼的十分紧迫。\n【刘病日笃】\n笃：病重,沉重\n日：一天比一天\n【欲苟顺私情，则告诉不许】\n苟：姑且\n告诉不许：申诉不被允许，告诉：申诉（苦衷）\n【实为狼狈】\n实为：总结上文\n狼狈：形容进退两难的情形\n【伏惟圣朝以孝治天下，凡在故老，犹蒙矜育】\n伏惟：俯状思量。古时下级对上级表示恭敬的词语，奏疏和书信里常用。\n故老：年老而德高的旧臣\n蒙：受\n矜育：怜惜养育\n【且臣少仕伪朝】\n伪朝：蔑称，指被灭亡蜀朝\n【历职郎署，本图宦达，不矜名节】\n历职：连续任职\n郎署：郎官的衙署。李密在蜀国曾任郎中和尚书郎。 署：官署，衙门\n图：希图。\n宦达：官职显达。宦，做官；达，显贵\n不矜：不看重。矜，自夸\n【过蒙拔擢，宠命优渥（南朝《文选》加），岂敢盘桓，有所希冀】\n拔擢(zhuó)：提拔\n宠命：恩命\n优渥(wò)：优厚\n盘桓：犹疑不决的样子，指拖延不就职\n希冀：企图，这里指非分的愿望\n【日薄西山】\n日薄西山：太阳接近西山，喻人的寿命即将终了。薄，迫近\n【人命危浅】\n危浅：活不长，指生命垂危。危：微弱 浅：指不长\n浅：不长\n【更相为命，是以区区不能废远】\n更(gēng)相：交互\n是以：因此\n区区：拳拳,形容自己的私情（古今异义）；另一说指“我”，自称的谦词\n废远：废止远离。\n【乌鸟私情，愿乞终养】\n乌鸟私情：乌鸦反哺之情，比喻人的孝心\n终养：养老至终\n【臣之辛苦】\n辛苦：辛酸悲苦，这里指辛酸苦楚的处境（古今异义）\n【二州牧伯】\n二州：指梁州(在今陕西省汉中地区)、益州(在今四川省)\n牧：古代称州的长管；伯：长\n【皇天后土，实所共鉴】\n皇天后土：文中指天地神明\n鉴：审察，识别\n【矜悯愚诚，听臣微志，庶刘侥幸，以保卒余年】\n矜悯：怜恤。\n听：任，这里是准许、成全\n庶：庶几，或许，表示希望或推测\n保：安；卒：终\n【死当结草】\n结草：指报恩。\n典故，出自《左传·宣公十五年》。见成语“结草衔环”，说春秋时，晋大夫魏武子有爱妾，武子病时，嘱咐其子魏夥说，自己死后，令妾改嫁。到了病危时，又说令妾殉葬。武子死后，魏夥把父妾嫁出，说是遵守父亲神志清醒时的遗命。传说后来魏夥和秦将杜回作战，看见一老人结草绊倒了杜回，夜间魏夥梦见老人说是魏武子妾的父亲，帮助他是为了报答不令女儿殉葬的恩德。现在表示死后也会像结草老人一样来报答恩情。\n【臣不胜犬马怖惧之情，谨拜表以闻】\n不胜：禁不住。胜（shēng），承受，承担。\n犬马怖惧之情：这是臣子谦卑的话，用犬马自比\n拜表：拜上表章\n闻：使动用法，使…知道。与上文“具以表闻”的“闻”用法相同。', poem_appreciation = '第一段\n\n　　作者陈述家庭的特殊不幸和作者与祖母更相为命，以使武帝化严为慈，化对立态度的逞威为同一立场的体恤。“臣密言”，是奏表开头的一般格式。“臣以险衅，夙遭闵凶”，是第一段的综述，又是全文陈述苦情的总冒。“险”，不同于今天的“危险”义，《说文》：“险，阻难也。”贾逵《国语》注：“衅，兆也。”“险衅”，险恶的兆头。“闵”，病困，凶丧。“险衅”“闵凶”这两个词儿含义程度很重，很快就把读者导入惨苦的境域。什么“险衅”?什么“闵凶”?“生孩六月，慈父见背”。小孩儿出世主要依靠父母抚养，竟然“慈父见背”，是一大不幸。《文子》：“慈父之爱子，非求报。”可见父慈于子是人之本性。作者不用第一人称“臣”，而用第三人称“孩”，旨在客观陈述苦情以使武帝动心。父亲死了，固然痛苦，如果还有慈爱的母亲一道过着孤儿寡母的生活，那还只是比较艰苦而已，竟然又“行年四岁，舅夺母志”，是又一个大不幸!《晋书·李密传》：“父早亡，母何氏改醮。”四岁的孩子，既经失怙，又已失恃，宛然一只被猎人击毙父母的没有羽翎的乌鸟，其寒伧、蒙昧、本能地求居觅食而又不可得的苦状可以想像得之。《毛诗序》：“卫世子蚤死，其妻守义，父母欲夺而嫁之。”“舅夺母志”典出于此，但这是托词(因为封建社会里人们把妇女在亡夫以后的改嫁视为丑事)，也是作者对母亲宽解的一种孝行。从心理的通常情况看，似乎长者特别喜欢第三代，似乎祖父祖母喜欢孙子胜过儿、媳喜欢子女；如果这种判断不误，那么，祖母刘氏对作者的特别喜欢是很自然的，再加上作者是一个失怙失恃的孩子，当然特别喜欢又加上特别同情了，这样，“悯臣孤弱”的“悯”其含义之深、程度之重可以贴切体会，祖母当然“躬亲抚养”了。《晋书·李密传》：“密时年数岁，感恋弥至，烝烝之情，遂以成疾。”“九岁不行”，也许是软骨病之类。如果孩子身体健康，祖母操心费力可能少些，现在竟是“九岁不行”，特异的体弱是又一种大不幸，是祖母格外操心费力的又一个因素。以上一句写“弱”，以下集中写“孤”。尽管有三种大不幸，如果家里人丁较多、外面亲戚不少，那还可以有若干圆通的余地，现在是“零丁孤苦，至于成立”。“孤”得够痛苦了，够奇特了，够长久了：一，从作者的父辈看，没有叔叔又没有伯伯。二，从作者的平辈看，没有哥哥又没有弟弟。《诗经·郑风·扬之水》：“终鲜兄弟，维予与女(汝)。”郑玄笺：“鲜，寡也。”作者借用《诗经》一句，但“鲜”并不作“少”讲而作“无”讲，是在特殊的语言环境下跟“既无叔伯”的“无”避免重复的一种特殊词义。从外亲看，既没有为祖母、兄弟、妻子等穿孝服的亲眷，也没有为曾祖父母、伯叔祖父母穿孝服的家族，也没有为堂兄弟、为未出嫁的堂姊妹穿孝服的同姓，单枝独芽寡人一个。从经济看，门庭衰败，连个使唤的童仆也没有。最后以“茕茕孑立，形影相吊”来简括、有力、形象地刻画作者幼年时经历的那种寂寞、清贫、孤独、悲怆、冷酷、凄厉无告、遭人白眼的惨境。封建社会的世俗观念跟今天不同，今天男女平等又以独生(无分男女)为正为荣，封建社会重男轻女又提倡多子(男子)，作者这个“九岁不行”，又是“既无叔伯，终鲜兄弟”，又是缺亲无故，又没有童仆的清贫之家的几世单传的孤根弱苗的成长，饱蘸着祖母刘氏多少关顾之爱，倾注了祖母刘氏多少矜悯之情，耗费了祖母刘氏多少操劳之力!不妨说，祖母虔诚不渝地把自己全部的智慧、热血、精力乃至生命都放在抚养作者上面，读者怎不被浸透在一种寻寻觅觅、冷冷清清、凄凄惨惨戚戚的氛围之中而对作者产生深切的同情呢?如果祖母刘氏身心康泰，操作便利，那还可以有些周旋。大不幸又一次在必然中发生了，──祖母刘氏经受不了许多家庭变故的摧残，经受不了许多社会人心的冷遇，经受不了许多对孤弱孙儿的哀悯和担心，喂养和抱持，事必躬亲，因而“夙”婴疾病，“常”在床褥，失去独立生活的能力。祖母所唯一依靠的是一根弱苗而已，“臣侍汤药，未尝废离”，概括而又具体地写出了作者对祖母的孝谨备至。《晋书·李密传》：“密奉事以孝谨闻。刘氏有疾，则涕泣侧息，未尝解衣，饮膳汤药必先尝后进。”可见作者对祖母感情的深切、侍奉的殷勤和依附的紧密。从“而刘”到“废离”不过寥寥几句，却勾勒出陈情不仕的一个很重要的画面。以下论列紧紧把这几句当作唯一的事实根据。\n\n　　第二段\n\n　　历叙朝廷多次征召，优礼有加，都由于“刘病日笃”而有着“报国恩”和“徇私情”的不可调和的矛盾，作者旨在消除晋武帝的疑虑，为下文请求“终养”埋下伏线。“逮奉圣朝，沐浴清化”，其中有对晋武帝的最高颂词；更有对作者深受其恩的最大感激，“沐浴”一词隐喻作者犹如禾苗蒙受雨露滋润因而茁壮成长。武帝担心作者以事奉祖母为借口，实在是对新朝持反对或观望的态度，作者更担心如果措词失当会引起武帝疑虑将有杀身之虞。“奉圣朝”，臣仆称君之词，“沐浴清化”，臣仆无比感激新朝的话，称呼和感激都能使晋武帝敏锐地感觉到这是一个宠臣对君主说话，因而心弦为之一弛。“逮奉圣朝，沐浴清化”，又作为一个过渡引导到“陈情”上来，以下具体地陈述“沐浴清化”的事实：一是太守推举作者为“孝廉”，这是褒德；二是刺史荐拔作者为“秀才”，这是称才，但是“臣以供养无主，辞不赴命”。“辞不赴命”乍一看来并非“沐浴清化”，其实是最好的“沐浴清化”，因为晋朝的地方官吏不但承认并且大力表彰了作者的孝顺和与事有原则和有才干，而且体谅了作者的惨苦处境，通情达理，言到行成。由于是地方官吏，又由于是以前的事，只用“供养无主，辞不赴命”简单交代一下就行了。“沐浴清化”的更重要的事实是“诏书特下，拜臣郎中，寻蒙国恩，除臣洗马”。武帝“特下”诏书，而且要作者做特别亲信的宫廷侍卫之长；不久又授予辅佐太子的官职。面对最高统治者一再提拔，作为降臣的李密越发不能简单从事了，于是“具以表闻”。在武帝看来，李密对这种厚爱竟然“辞不就职”，难免身在曹营心在汉。但是作者巧妙地写道：“猥以微贱，当侍东宫，非臣陨首所能上报。”作者主动说出武帝心中想要说的，而且是这样委婉，这样诚恳，武帝当然会心平气和了。但这话毕竟是作者所说，从以前的情况看，并没有获得武帝的谅解，而是遭到强迫手段：“诏书切峻，责臣逋慢。”“切”，“峻”，“责”，“逋”，“慢”，都准确鲜明地刻画了武帝当时的恼怒情态。郡县风驰电掣地执行王命，是“逼迫”，是“催”臣上道，州司具体贯彻王命，是“临门”，是“急于星火”，先后六个四字句，非常精练形象地描绘了一幅雷厉风行无可阻遏的催命图，这与上文所写“茕茕孑立，形影相吊”成为鲜明的对照。“臣欲奉诏奔驰”的“奔驰”用得绝妙，它有力地显示了作者非常急切地希望立刻赴京为皇家奔走效劳的焦急心情，“刘病日笃”的“日”字又准确地显示了苦情日深而且是为时不久，它跟下文“苟循私情”的“苟(姑且)”相得益彰。作者巧妙地应用了二难推理：“欲奉命奔驰，则刘病日笃；欲苟循私情，则告诉不许”。二难推理是假言推理和选言推理联合起来的推理，它的前提既然有两个，结论就是或此或彼，因此说，“臣之进退，实为狼狈”。这个结论含蕴精警，表面看来它有对武帝的忠敬之心，又有对祖母的孝顺之情，使武帝意识到作者的真情实感一一出自肺腑，句句有理，处处合情，部分地消除了对作者的某些疑虑。其实呢，辩证地看，这里的根本观点是“先徇私情，后报国恩”。如果是先直截了当地提出“愿乞终养”，很可能激怒武帝遂致罹难，这里形式上提出两难，正是作者与事为文的高超所在。怎样进一步说服武帝呢?作者留下了一个悬念，而把读者引向下面的关键的即是高潮的一段。\n\n　　第三段\n\n　　提出晋朝“以孝治天下”这个治国纲领，陈述作者特别孤苦的处境和作者的从政历史、人生态度以及政治思想，以便进一步打消晋武帝的疑虑。《韩非子·说难》：“凡说之务，在知饰所说之所矜，……有欲矜以智能，则为之举异事之同类者，多为之地。”作者紧扣治国纲领大做文章，使武帝感到“大意无所拂悟，辞言无所系縻”(见《说难》)。圣朝“以孝治天下”，并且做到“凡在故老，犹蒙矜育”，是热切称颂朝廷褒扬孝行态度坚决、措置得当，却更是为“愿乞终养”设置根据。于是说出了“况臣孤苦，特为尤甚”，副词“特”和两个形容词“尤”“甚”集中有力地写出了作者的情况是异乎寻常的特殊，那就越发应当而且必须“蒙矜育”了。如果是粗心的作者，行文至此，也许可以认为提出“愿乞终养”了，那仍然要把事情弄坏，因为“以孝治天下”是讲法，“凡在故老……”是说理，都还只是一般的论辩艺术，都还没能进一步打开武帝的心扉。聪明而又耐心的作者忽然宕开一笔，索性刺刀见红，把情节推向高潮!他勇敢坦率而又十分机警地把自己的历史问题、人生态度以及从政思想来一个彻底交代，全盘亮相：“且臣少仕伪朝，历职郎署。”“少”“仕”“历”职说明了仕臣之久，供职之勤，但它的根本目的不是为了尽忠守节于西蜀，而是为了“图宦达”。既然“图宦达”，就说不上“矜名节”，就较多地打消了武帝的疑虑。另一方面，武帝的措施又使作者这个“至微至陋”的“亡国贱俘”深感“过蒙拔擢，宠命优渥”，完全应当“士为知己者死”，怎么可能徘徊犹豫、另有所图呢?这又进一步打消了武帝的一些疑虑。在武帝看来，皇君至高无上，降臣至卑无下，动不动就可以非常方便地施以高压。作者看准了这种心理状态，尽量把自己压低，把国恩抬高：“今臣亡国贱俘，至微至陋”。一个“贱”字，仍旧感到不足，再加上一个“微”字和一个“陋”字，而且是“至微至陋”。与此同时，国恩深重是“过”蒙拔擢，是“宠”命“优”“渥”(“优”“渥”同义)，前朝降臣恩荣加身，必然要欣慰，惶恐，感奋无已，效忠不二，这正是武帝所急切希望的。接着用反诘句“岂敢盘桓，有所希冀”，只能是增强陈情语气而不会激怒武帝，降臣对新主竟能如此措词这是少见。也不是守节蜀汉，也不是拒官新朝，那是为什么呢?唯一的原因除了前文所说，作者勾勒了又一幅惨苦图，亦即祖母刘氏的病笃图：“日薄西山，气息奄奄，人命危浅，朝不虑夕。”“日薄西山，气息奄奄”这个隐喻形象地表白了祖母大限临头，而且是很快地临头，作者只是竭力捕捉一刹那的时机，完足一刹那的义务，享受一刹那的幸福而已，这已为下文“报刘之日短也”张本。文章至此，完全可以提出“愿乞终养”了，但聪明而又极其细心的作者还怕武帝认为以一般的孝敬长上为借口实在为的消极抗拒皇命，作者又一次综述了自己跟祖母血肉相连不可或离的紧密关系，“臣无祖母，无以至今日；祖母无臣，无以终余年”，是一种意思，一种说法；“母、孙二人，更相为命”，还是这种意思，但是另一种说法，强调中具有错综变化，又自然地得出了“区区不能废远”的结论。“区区”，拳拳，一片真情，也就是“不能废远”，用“区区”又用“不能废远”，也是强调中具有错综变化。以上两句出自肺腑，动人神魄，从悉心说服武帝体恤下情看，“区区不能废远”明确表示不能分离，比上文“臣之进退，实为狼狈”的两可之说前进了一步。\n\n　　第四段\n\n　　明确提出“愿乞终养”，表示要先尽孝后尽忠，以期感动武帝达到陈情目的。\n\n　　尽管作者从法从理从情写得娓娓动人，但他仍然清醒地、审慎地料到武帝不能满足于“区区不能废远”的说法，还会采取一些相应的高压手段。作者又清醒地、审慎地估计到尽管上文已经有种种刘氏大限不远的表白，但武帝还会认为“徇私情”跟“报国恩”的抵触，作者仍旧不能提出“愿乞终养”的请求，本段开头就亮出具体的时限说：“臣密今年四十有四，祖母刘今年九十有六”。四十四岁，是中年人，风华正茂，报国多日；九十六岁，古来稀有，风烛瓦霜，瞬息可灭，很自然地得出“尽节于陛下之日长，报刘之日短也”的结论，这结论清楚地陈述“报国恩”跟“徇私情”只有为时极短的矛盾，稍稍从长远着眼就根本没有矛盾，也是合情合理地提出解决尽忠跟尽孝暂时发生矛盾的措施的有力依据。从武帝设想，可以把成全李密作为“以孝治天下”的一个范例，更可以达到李密出仕新朝的目的，冠冕堂皇，惠而不费，何乐而不为?!老练深沉的作者这才水到渠成地提出了“乌鸟私情，愿乞终养”的请求。“乌鸟私情”，是比喻也是比拟，它是“愿乞终养”的根据，又回溯到这是动物本性所在，治天下的本性所在，完全符合“以孝治天下”的纲领；又是恳切、谦抑的天真流露，这种措词委婉得体，曲折有致，连铁石人也得回心转意，武帝当然不能拒绝。《尔雅·释诂》：“愿，欲也。”它不同于现代汉语的“愿意”，应作“很希望”讲，表示愿欲之深。用了“愿”又用“乞”，同义的语词反复表示分外强烈。精妙的是，作者明确提出请求以后，还害怕武帝不相信他所说的“况臣孤苦，特为尤甚”，为了印证所说句句属实，了无欺诈，再作出了以下印证：“臣之辛苦，非独蜀之人士及二州牧伯所见明知，皇天后土实所共鉴。”“所见”，“明知”，“共鉴”，异词同义，有力地显示了作者的辛苦如日之光，如火之煌。当然，印证的作用远不在于使武帝深信其事，更可以使武帝感到，即使不从作者的处境考虑，而从“以孝治天下”这个手段出发，成全了作者为时短暂的请求，可以收民心，可以服官吏，又可以动神灵，更可以慰作者，一举四得，何乐而不为?!奇妙的是，作者还觉得意犹未遂，言犹未尽，情犹未达，理犹未顺，再一次请求“矜悯愚诚，听臣微志”，以便刘氏意外地免除不幸，以便自己意外地获得成功。“愚诚”，“微志”，“侥幸”，“保卒”，一连串的词语，表示作者以最谦恭、最虔诚的口吻含泪哀求，催促武帝彻底动情。更妙的是，为了再一次使武帝放心，作者最后提出“生当陨首，死当结草”的保证，这比“尽节于陛下之日长”又大大进了几步：活着不惜人头落地，死了也要结草衔环。尽管实质是为了作者对祖母的高谊隆情，但作者对武帝的极其忠爱、无比尊崇、十分殷勤的心情溢于言表，使武帝越发深信作者陈情的诚挚和急切。最后又以一个降臣的口吻概括地表达了格外恭谨的想法：是“犬马”，是“怖惧”，更是“不胜”，宛然适合一个新朝君主所希望听到的降臣的朴实、真切而能扣人心弦、令人怜悯的语言，怎不使武帝叹为观止、霁怒为怜、予以怀柔呢?!《晋书·李密传》：“武帝览之曰：‘士之有名，不虚然哉!’”《华阳国志》：“嘉其诚，赐奴婢二人，使郡县供其祖母奉膳。”《晋书·李密传》：“后刘终，服阕，复以洗马征至洛。”可见李密是情真意切。', poem_tags = '高中文言文,古文观止,抒情,散文' WHERE poem_title = '陈情表' AND poem_author = '西晋·李密';
UPDATE edu_poem SET poem_translation = '爱情应该像山上的雪一般纯洁，像云间月亮一样光明。\n听说你怀有二心，所以来与你决裂。 \n今日犹如最后的聚会，明日便将分手沟头。\n我缓缓的移动脚步沿沟走去，过去的生活宛如沟水东流，一去不返。\n当初我毅然离家随君远去，就不像一般女孩凄凄啼哭。\n满以为嫁了一个情意专心的称心郎，可以相爱到老永远幸福了。\n男女情投意合就像钓竿那样轻细柔长，鱼儿那样活波可爱。\n男子应当以情意为重，失去了真诚的爱情是任何钱财珍宝都无法补偿的。', poem_notes = '白头吟：乐府《楚调曲》调名。据《西京杂记》卷三载，蜀地巨商卓王孙的女儿卓文君，聪明美丽，有文采，通音乐。孀居在家时，与司马相如相爱，私奔相如，因生计艰难，曾得到卓王孙的资助。司马相如得势后，准备娶茂陵的一个女子为妾，卓文君得知就写了一首《白头吟》给他，表达自己的哀怨之情，相如因此打消了娶妾的念头。后世多用此调写妇女的被遗弃。\n皑：白。\n皎：白。\n两意：就是二心（和下文“一心”相对），指情变。\n决：别。\n斗：盛酒的器具。这两句是说今天置酒作最后的聚会，明早沟边分手。\n明旦：明日。\n躞（xiè）蹀（dié）：走貌。御沟：流经御苑或环绕宫墙的沟。\n东西流，即东流。“东西”是偏义复词。这里偏用东字的意义。以上二句是设想别后在沟边独行，过去的爱情生活将如沟水东流，一去不返。\n凄凄：悲伤状。\n竹竿：指钓竿。袅袅：动摇貌。一说柔弱貌。\n簁（shāi）簁：形容鱼尾像濡湿的羽毛。在中国歌谣里钓鱼是男女求偶的象征隐语。这里用隐语表示男女相爱的幸福。\n意气：这里指感情、恩义。\n钱刀：古时的钱有铸成马刀形的，叫做刀钱。所以钱又称为钱刀。', poem_appreciation = '晋人葛洪《西京杂记》载:“司马相如将聘茂陵人女为妾,卓文君作《白头吟》以自绝,相如乃止。”但《宋书·乐志》言《白头吟》等“并汉世街陌谣讴”,即民歌。《玉台新咏》载此诗,题作《皑如山上雪》,则连题目亦与卓氏无关了。《西京杂记》乃小说家言,且相如、文君关系亦未尝至此,故云文君作,显系附会。此诗当属民歌,以女子口吻写其因见弃于用情不专的丈夫而表示出的决绝之辞。 首二句是一篇起兴,言男女爱情应该是纯洁无瑕的,犹如高山的白雪那样一尘不染；应该是光明永恒的,好似云间的月亮皎皎长在。这不仅是一般人情物理的美好象征,也当是女主人公与其丈夫当初信誓旦旦的见证吧。诚如清人王尧衢云:“如雪之洁,如月之明,喻昔日信誓之明也。”(《古诗合解》)但也有解为“以‘山上雪’,‘云间月’之易消易蔽,比起有两意人。”(张玉谷《古诗赏析》)意亦可通。细玩诗意,解为反面起兴,欲抑先扬,似更觉有味。故“闻君”二句突转:既然你对我的爱情已掺上杂质,既然你已心怀二心而不专一持恒,所以我特来同你告别分手,永远断绝我们的关系。“有两意”,既与首二句“雪”“月”相乖,构成转折,又与下文“一心人”相反,形成对比,前后照应自然,而谴责之意亦彰,揭示出全诗的决绝之旨。“今日”四句,承上正面写决绝之辞:今天喝杯诀别酒,是我们最后一次聚会,明晨就将在御沟(环绕宫墙的水渠)旁边徘徊(躞蹀)分手,就像御沟中的流水一样分道扬镳了。“东西流”以渠水分岔而流喻各奔东西；或解作偏义复词,形容爱情如沟水东流,一去不复返了,义亦可通。\n\n　　“凄凄”四句忽一笔宕开,言一般女子出嫁,总是悲伤而又悲伤地啼哭,其实这是大可不必的；只要嫁得一个情意专一的男子,白头偕老,永不分离,就算很幸福了。言外之意,自己今日遭到遗弃才最堪凄惨悲伤,这是初嫁女子无法体会到的滋味。作者泛言他人而暗含自己,辞意婉约而又见顿挫；已临决绝而犹望男方转变,感情沉痛而不失温厚。诚如清人张玉谷所评:“凄凄四句,脱节暗转,盖终冀其变两意为一心而白头相守也。妙在从人家嫁娶时凄凄啼哭,凭空指点一妇人同有之愿,不着已身说,而己身在里许。用笔能于占身分中,留得勾留之意,最为灵警。”(《古诗赏析》)堪称深得诗旨。\n\n　　结尾四句,复用两喻,说明爱情应以双方意气相投为基础,若靠金钱关系,则终难持久,点破前文忽有“两意”的原故。“竹竿”,指钓鱼竿；“嫋嫋”,形容柔长而轻轻摆动的样子；“簁簁”(shāi)即“漇漇”的假借字,形容鱼尾像沾湿的羽毛。“钱刀”,即古代刀形钱币,此处泛指金钱。以鱼竿的柔长轻盈摆动和鱼尾的滋润鲜活,比喻男女求偶,两情欢洽。《诗经》这类比兴较多,如《卫风·竹竿》:“籊籊竹竿,以钓于淇；岂不尔思,远莫致之。”《毛传》:“钓以得鱼,如妇人待礼以成为室家。”但此处联下文之意,似又隐含爱情若不以意气(义)相知,仅以香饵诱鱼上钩,恰似只靠金钱引诱,那爱情是靠不住的。故清人朱嘉微评曰:“何以得鱼？须芳其饵。若一心人意气自合,何须芳饵为!”(《乐府广序》)结句点破男子“有两意”是因为金钱关系。但究竟是他利用金钱为诱饵去另图新欢呢？还是那位“新欢”家资颇富,致使这位男子贪图富贵而厌弃糟糠呢？这只有留给读者去猜想了。\n\n　　这首诗塑造了一位个性鲜明的弃妇形象,不仅反映了封建社会妇女的婚姻悲剧,而且着力歌颂了女主人公对于爱情的高尚态度和她的美好情操。她重视情义,鄙夷金钱；要求专一,反对“两意”。当她了解到丈夫感情不专之后,既没有丝毫的委曲求全,也没有疯狂的诅咒和软弱的悲哀,表现出了妇女自身的人格尊严。她是把痛苦埋在心底,冷静而温和地和负心丈夫置酒告别,气度何等闲静,胸襟何等开阔！虽然她对旧情不无留念和幻想,但更多的却是深沉的人生反思。因此,她较之古诗中一般的弃妇形象又迥然不同,显示出“这一个”的个性。\n\n　　全诗多用比兴和对偶,雪、月、沟水、竹竿、鱼尾等喻象鲜明生动而又耐人寻味。一、二、五、六、十三、十四等句皆工对而又自然。此外四句一解,每解换韵,而诗意亦随之顿挫,声情与辞情达到完美的统一。', poem_tags = '乐府,民歌,女子,爱情,分手' WHERE poem_title = '白头吟' AND poem_author = '卓文君';
UPDATE edu_poem SET poem_translation = '宋国有个富人，因下大雨，墙坍塌下来。他儿子说：“如果不（赶紧）修筑它，一定有盗贼进来。”他们隔壁的老人也这么说。这天晚上果然丢失了大量财物，这家人很赞赏儿子聪明，却怀疑偷盗是隔壁那个老人干的。', poem_notes = '智其子：以为他的儿子很聪明，聪慧，机智。\n宋：宋国。 \n雨：下雨（名词作动词）。.\n坏：毁坏，损坏。\n筑：修补。\n盗：偷盗。动词活用作名词。\n富人；富裕的人。\n亦云：也这样说。云：说。亦：也。\n暮：晚上。\n而：无义。表示承接关系。\n果：果然。\n亡：丢失。\n父：（fǚ，第3声，译为“老人”指邻居家的老人）邻居家的老人。\n甚：很。\n而（疑邻人之父）：表示转折关系。15、家：家里的人。\n\n古今异义\n1、亡古意：丢失 今意：死亡\n2、其邻人之父亦云古意：说 今意：常做“云朵”讲，在空中悬浮的有水滴、冰晶凝聚形成的物体\n\n一词多义\n1.暮：\n夜晚（暮而果大亡其财）\n年老（烈士暮年，壮心不已）\n2.果：\n果然（暮而果大亡其财）\n结果（ 未果， 寻病终）\n3.亡：\n丢失（暮而果大亡其财）\n逃跑（今亡亦死，举大计亦死）\n通“无”没有（河曲智叟亡以应）\n4.其：\n其子曰（代词；代他的）\n其家甚智其子（代词；代这）\n5.之：\n他/她。（的//语气助词：不译//去、到）\n6.而：\n暮而果大亡其财（表承接）\n而疑邻人之父（表转折；却）\n告诫人们，如果不尊重事实，只用亲疏和感情作为判断是非的标准，就会主观臆测，得出错误的结论。', poem_appreciation = '从邻人的老人说，好心没好报，归到交浅言深上，从此人情练达，沉默是金。这一层不说。这摆明了是批评主人家不对，同样的意见因为亲疏远近而态度迥异，所谓“薄者见疑”。意即亲疏厚薄是一种妨碍，妨碍了主人家对真相正误的认识。\n\n　　其实韩非本意倒非批评“智其子疑其邻”的主人家，这则寓言见于《说难》篇，意思是劝说别人是何等的困难，因为每个人所处的位置不同。这是被韩非当做一个事实接受的，所以他的主要目标是研究那些能够有助于让别人听取自己意见的注意事项。交浅不可言深就是注意事项之一，所以韩非这则寓言的本意是批评富人的做法——因两人身份不同而受到不同的待遇。\n\n　　被韩非当做事实接受的“薄者见疑”，在今天有更加技术化的解释。“每个人所处位置不同”的说法换成经济学语言，就是因信息的不对称状态而导致交易费用的迥异，从而影响每个人的判断和行为选择。韩非子在《说难》中的一切努力，就是今天信息经济学企图解决的问题，即如何在信息不对称的情况下让对方说真话，让对方相信自己的话，最终与对方达成契约。\n\n　　其实除了上帝，没人能够批评失窃者的怀疑。因为上帝知道究竟是谁干的，我们都不知道，所以破案之前不能说三道四。而韩非子讲故事很缺德，最后没说案子破是没破。这怀疑就一直都很合理。“亲疏”的差别这里有两个意义，两方面都构成我们判价分析问题的重要进路，而非妨碍。其一是利益立场的分殊。之所以智其子而不疑其子，因为他儿子是财产权的共同受益人和继承人，除非爷俩的关系另出问题，他儿子显然缺乏盗窃的合理利益动机。其二则是信息的不对称。交易费用中有相当一部分是了解对方和建立信任机制的成本。“亲”意味着这一成本很低，“疏”意味着成本的高昂。所以建立起现代法治秩序和信用体系之前，交易的半径总不太可能超越“亲疏”的圈子（差序格局），而延伸到陌生人环境中去。\n\n　　儿子是什么样的人老子自然很清楚，邻人是怎么样的人却不了解。这是怀疑的合理基础。一个重要细节是案发之前，主人对二人的建议并没有因为亲疏远近而厚此薄彼。邻人“见疑”是在案发之后。我们设想一番，墙坏和失窃之间，只有短短几个小时。半天时间知道这一事实并利用这一事实的人很有限，古人地广人稀，邻里原本很少。人口流动性又差，外来人口会非常引人注目。这案子交给美利坚、不列颠、俄罗斯或者爪哇国哪一家警察局，根据已有线索，这位邻人也必将是最重要的嫌疑人。\n\n　　在一种非法治文化中，“被怀疑”是一种羞辱，甚至会直接导致司法的有罪推定或人际中的歧视。其实这才是“智子疑邻”遭到批评的深层文化心理因素。在一种法治文化中，“怀疑”是一种合理的、大方得体的态度。不怀疑对方可能违约，就不用签合同。不怀疑政府会滥用权力，就不需要宪政民主。而和自己爹妈做生意，也可以不签合同，你不能没来由的说人家法律意识差。因为不签合同的成本可能更低。这和智子疑邻是一个道理。\n\n　　启示：两个人会因为身份和关系的不同，而遭到不同的对待。', poem_tags = '初中文言文,哲理,故事' WHERE poem_title = '智子疑邻' AND poem_author = '韩非';
UPDATE edu_poem SET poem_translation = '绿树葱郁浓阴夏日漫长，楼台的倒影映入了池塘。\n水精帘在抖动微风拂起，满架蔷薇惹得一院芳香。', poem_notes = '浓：指树丛的阴影很浓稠（深）。\n水精帘：又名水晶帘，是一种质地精细而色泽莹澈的帘。比喻晶莹华美的帘子。蔷薇：植物名。落叶灌木，茎细长，蔓生，枝上密生小刺，羽状复叶，小叶倒卵形或长圆形，花白色或淡红色，有芳香。花可供观赏，果实可以入药。亦指这种植物的花。', poem_tags = '夏天,写景' WHERE poem_title = '山亭夏日' AND poem_author = '高骈';
UPDATE edu_poem SET poem_translation = '半亩大的方形池塘像一面镜子一样打开，清澈明净，天光、云影在水面上闪耀浮动。\n要问池塘里的水为何这样清澈呢？是因为有永不枯竭的源头源源不断地为它输送活水。', poem_notes = '方塘：又称半亩塘，在福建尤溪城南郑义斋馆舍（后为南溪书院）内。朱熹父亲朱松与郑交好，故尝有《蝶恋花·醉宿郑氏别墅》词云：“清晓方塘开一境。落絮如飞，肯向春风定。”\n鉴：一说为古代用来盛水或冰的青铜大盆。镜子；也有学者认为镜子。指像鉴（镜子）一样可以照人。\n“天光”句：是说天的光和云的影子反映在塘水之中，不停地变动，犹如人在徘徊。\n徘徊：来回移动。\n为：因为。\n渠：它，第三人称代词，这里指方塘之水。\n那得：怎么会。\n那：怎么的意思。\n清如许：这样清澈。\n如：如此，这样。\n清：清澈。\n源头活水：比喻知识是不断更新和发展的，从而不断积累，只有在人生的学习中不断地学习、运用和探索，才能使自己永保先进和活力，就像水源头一样。', poem_appreciation = '这是一首抒发读书体会的哲理诗，“半亩方塘一鉴开，天光云影共徘徊”，半亩的“方塘”不算大，只有半亩地的一个方方的池塘，但它像一面镜子那样地澄澈明净，“一鉴”的“鉴”，就是“镜”，照人的镜子，“镜”和“鉴”是一个意思。“半亩方塘”像一面镜子那样打开了。“半亩方塘”虽然不算大，但它却像一面镜子那样地澄澈明净，“天光云影”都被它反映出来了。闪耀浮动，情态毕见。作为一种景物的描写，这也可以说是写得十分生动的。这两句展现的形象本身就能给人以美感，能使人心情澄净，心胸开阔。这一种感性的形象本身，它还蕴涵着一种理性的东西。很明显的一点是，“半亩方塘”里边的水很深、很清，所以它能够反映“天光云影”；反之，如果很浅、很污浊，它就不能反映，或者是不能准确地反映。\n\n　　诗人正是抓住了这一点作进一步的挖掘，写出了颇有哲理的三、四两句：“问渠那得清如许？为有源头活水来。”“问渠”的“渠”，不是“一渠水”的“渠”，它相当于“它”的意思，这里是指方塘。“问渠”就是“问它”。在这个地方“它”指代的是“方塘”。诗人并没有说“方塘”有多深，第三句诗里边突出了一个“清”字，“清”就已经包含了“深”。因为塘水如果没有一定的深度的话，即使很“清”也反映不出“天光云影共徘徊”的情态。诗人抓住了塘水“深”而且“清”，就能反映“天光云影”的特点。但是到此诗人并没有结束，他进一步地提出了一个问题。“问”那个“方塘”“那得清如许？”问它为什么这么“清”，能够反映出“天光云影”来。而这个问题孤立地看这个“方塘”的本身没有法子来回答。诗人于是放开了眼界，从远处看，终于，他看到了“方塘”的“源头”，找到了答案。就因为“方塘”不是无源之水，而是有那永不枯竭的“源头”，源源不断地给它输送了“活水”。这个“方塘”由于有“源头活水”的不断输入，所以它永不枯竭，永不陈腐，永不污浊，永远“深”而且“清”。“清”得不仅能反映出“天光云影”，而且能反映出“天光”和“云影”“共徘徊”这么一种细致的情态。这就是这一首小诗所展现的形象和它的思想意义。', poem_tags = '古诗三百首,初中古诗,写景,读书,哲理,早教古诗100首' WHERE poem_title = '观书有感二首·其一' AND poem_author = '朱熹';
UPDATE edu_poem SET poem_translation = '一个头发蓬乱、面孔青嫩的小孩在河边学着大人钓鱼，侧着身子坐在草丛中，野草掩映了他的身影。\n听到有过路的人问路，小孩漠不关心地摆了摆手，生怕惊动了鱼儿，不敢回应过路人。', poem_notes = '蓬头：形容小孩可爱。稚子：年龄小的、懵懂的孩子。垂纶：钓鱼。纶：钓鱼用的丝线。\n莓：一种野草。苔：苔藓植物。映：遮映。\n借问：向人打听。\n鱼惊：鱼儿受到惊吓。应：回应，答应，理睬。', poem_appreciation = '《小儿垂钓》是一首以儿童生活为题材的诗作，诗写一“蓬头稚子”学钓鱼，“侧坐莓苔草映身”，路人向小儿招手，想借问打听一些事情，那小儿却“怕得鱼惊不应人”（怕惊了鱼而不置一词），真是活灵活现、惟妙惟肖，形神兼备，意趣盎然。其艺术成就丝毫不亚于杜牧著名的《清明》一诗。\n\n　　此诗分垂钓和问路两层，第一、二句重在写垂钓（形），第三、四句重在问路（传神）。\n\n　　第一、二句，稚子，小孩也。“蓬头”写其外貌，突出了小孩的幼稚顽皮，天真可爱。“纶”是钓丝，“垂纶”即题目中的“垂钓”，也就是钓鱼。诗人对这垂钓小儿的形貌不加粉饰，直写出山野孩子头发蓬乱的本来面目，使人觉得自然可爱与真实可信。“学”是这首诗的诗眼。这个小孩子初学钓鱼，所以特别小心。在垂钓时，“侧坐”姿态，草映其身，行为情景，如在眼前。“侧坐”带有随意坐下的意思。侧坐，而非稳坐，正与小儿初学此道的心境相吻合。这也可以想见小儿不拘形迹地专心致志于钓鱼的情景。“莓苔”，泛指贴着地面生长在阴湿地方的低等植物，从“莓苔”不仅可以知道小儿选择钓鱼的地方是在阳光罕见人迹罕到的所在，更是一个鱼不受惊、人不暴晒的颇为理想的钓鱼去处，为后文所说“怕得鱼惊不应人”做了铺垫。“草映身”，也不只是在为小儿画像，它在结构上，对于下句的“路人借问”还有着直接的承接关系──路人之向小儿打问，就因为看得见小儿。\n\n　　后两句中“遥招手”的主语还是小儿。当路人问道，小儿害怕应答惊鱼，从老远招手而不回答。这是从动作和心理方面来刻划小孩，有心计，有韬略，机警聪明。小儿之所以要以动作来代替答话，是害怕把鱼惊散。小儿的动作是“遥招手”，说明小儿对路人的问话并非漠不关心。小儿在“招手”以后，又怎样向“路人”低声耳语，那是读者想象中的事，诗人再没有交代的必要，所以，在说明了“遥招手”的原因以后，诗作也就戛然而止。\n\n　　在唐诗中，写儿童的题材比较少，因而显得可贵。这首七绝写小儿垂钓别有情趣。诗中没有绚丽的色彩，没有刻意的雕饰，就似一枝清丽的出水芙蓉，在平淡浅易的叙述中透露出几分纯真、无限童趣和一些专注。 此诗不失为一篇情景交融、形神兼备的描写儿童的佳作。', poem_tags = '儿童,垂钓' WHERE poem_title = '小儿垂钓' AND poem_author = '胡令能';
UPDATE edu_poem SET poem_translation = '鲜红浑圆的红豆，生长在阳光明媚的南方，春暖花开的季节，不知又生出多少？\n希望思念的人儿多多采集，小小红豆引人相思。', poem_notes = '相思：题一作“相思子”，又作“江上赠李龟年”。\n红豆：又名相思子，一种生在江南地区的植物，结出的籽像豌豆而稍扁，呈鲜红色。\n“春来”句：一作“秋来发故枝”。\n“愿君”句：一作“劝君休采撷”。采撷（xié）：采摘。\n相思：想念。', poem_appreciation = '这是借咏物而寄相思的诗，是眷怀友人之作。起句因物起兴，语虽单纯，却富于想象；接着以设问寄语，意味深长地寄托情思；第三句暗示珍重友谊，表面似乎嘱人相思，背面却深寓自身相思之重；最后一语双关，既切中题意，又关合情思，妙笔生花，婉曲动人。全诗情调健美高雅，怀思饱满奔放，语言朴素无华，韵律和谐柔美。可谓绝句的上乘佳品。\n\n　　红豆产于南方，结实鲜红浑圆，晶莹如珊瑚，南方人常用以镶嵌饰物。传说古代有一位女子，因丈夫死在边地，哭于树下而死，化为红豆，于是人们又称呼它为“相思子”。唐诗中常用它来关合相思之情。而“相思”不限于男女情爱范围，朋友之间也有相思的，如苏李诗“行人难久留，各言长相思”即著例。此诗题一作《江上赠李龟年》，可见诗中抒写的是眷念朋友的情绪。\n\n　　“南国”（南方）既是红豆产地，又是朋友所在之地。首句以“红豆生南国”起兴，暗逗后文的相思之情。语极单纯，而又富于形象。次句“春来发几枝”轻声一问，承得自然，寄语设问的口吻显得分外亲切。然而单问红豆春来发几枝，是意味深长的，这是选择富于情味的事物来寄托情思。“来日绮窗前，寒梅著花未？”（王维《杂诗》）对于梅树的记忆，反映出了客子深厚的乡情。同样，这里的红豆是赤诚友爱的一种象征。这样写来，便觉语近情遥，令人神远。\n\n　　第三句紧接着寄意对方“多采撷”红豆，仍是言在此而意在彼。以采撷植物来寄托怀思的情绪，是古典诗歌中常见手法，如汉代古诗：“涉江采芙蓉，兰泽多芳草，采之欲遗谁？所思在远道”即著例。“愿君多采撷”似乎是说：“看见红豆，想起我的一切吧。”暗示远方的友人珍重友谊，语言恳挚动人。这里只用相思嘱人，而自己的相思则见于言外。用这种方式透露情怀，婉曲动人，语意高妙。宋人编《万首唐人绝句》，此句“多”字作“休”。用“休”字反衬离情之苦，因相思转怕相思，当然也是某种境况下的人情状态。用“多”字则表现了一种热情饱满、一往情深的健美情调。此诗情高意真而不伤纤巧，与“多”字关系甚大，故“多”字比“休”字更好。末句点题，“相思”与首句“红豆”呼应，既是切“相思子”之名，又关合相思之情，有双关的妙用。“此物最相思”就像说：只有这红豆才最惹人喜爱，最叫人忘不了呢。这是补充解释何以“愿君多采撷”的理由。而读者从话中可以体味到更多的东西。诗人真正不能忘怀的，不言自明。一个“最”的高级副词，意味极深长，更增加了双关语中的含蕴。\n\n　　全诗洋溢着少年的热情，青春的气息，满腹情思始终未曾直接表白，句句话儿不离红豆，而又“超以象外，得其圜中”，把相思之情表达得入木三分。它“一气呵成，亦须一气读下”，极为明快，却又委婉含蓄。在生活中，最情深的话往往朴素无华，自然入妙。王维很善于提炼这种素朴而典型的语言来表达深厚的思想感情。所以此诗语浅情深，当时就成为流行名歌是毫不奇怪的。', poem_tags = '唐诗三百首,咏物,抒情,思念,早教古诗100首' WHERE poem_title = '相思' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '带着一丝寒意，独自登上小楼，清晨的阴凉，令人厌烦，仿佛已是深秋。回望画屏，淡淡烟雾，潺潺流水，意境幽幽。\n窗外，花儿自由自在地轻轻飞舞，恰似梦境，雨淅淅沥沥的下着，漫无边际地飘洒着，就像愁绪飞扬。再看那缀着珠宝的帘子正随意悬挂在小小银钩之上。', poem_notes = '《浣溪沙》原唐教坊曲名，本为舞曲。“沙”又写作“纱”。又称《小庭花》、《满院春》。另有一体五十六字。 \n漠漠：像清寒一样的冷漠。轻寒：薄寒，有别于严寒和料峭春寒。\n晓阴：早晨天阴着。无赖：词人厌恶之语。穷秋：秋天走到了尽头。\n淡烟流水：画屏上轻烟淡淡，流水潺潺。幽：意境悠远。\n丝雨：细雨。\n宝帘：缀着珠宝的帘子，指华丽的帘幕。闲挂：很随意地挂着。', poem_appreciation = '这首词以轻浅的色调、幽渺的意境，描绘一个女子在春阴的清晨里所生发的淡淡哀愁和轻轻寂寞。全词意境怅静悠闲，含蓄有味。\n\n　　每一次春来，就是一次伤春的体验。词人之心，很早就发出了“为问新愁，何事年年有”的愁怨。然而他们的命运也往往是一年年地品尝春愁。此词抒写的是淡淡的春愁。它以轻淡的色笔、白描的手法，十分熨贴地写出了环境氛围，即把那一腔淡淡的哀怨变为具体可感的艺术形象渗透出来，表情深婉、幽缈。“一片自然风景就是一种心情”。索漠轻寒中袅袅而升的是主人公那轻轻的寂寞和百无聊赖的闲愁。即景生情，因情生景，情恰能称景，景也恰能传情，这便是词作的境界。\n\n　　上片写晨起之感和室内之景，语言幽婉而含意深邃。词的起调很轻，很淡，而于轻淡中带着作者极为纤细锐敏的一种心灵上的感受。漠漠轻寒，似雾如烟，以“漠漠”二字状漫弥而上小楼的轻寒，一下子给春寒萧索的清晨带来寥廓冷落的气氛。与“暝色入高楼，有人楼上愁”意蕴相似，而情调之婉妙幽微过之。不说人愁，但云“漠漠轻寒上小楼”。回味“上”字，那淡淡愁思，不是正随这薄薄春寒无声无息地在人的心头轻轻漾起？仅词的首句，就为全词烘托出一个色调凄清的景。紧接着加上“晓阴无赖似穷秋”，在凄清的背景上涂抹一层暗淡的色彩。无赖，令人讨厌，无可奈何的憎语。时届暮春，却感到竟像深秋那样的寒冷，原来这是一个春阴的早晨。春阴寒薄，不能不使人感到抑闷无聊。然而词人不说心情之无聊，却咒晓阴之无赖，进一层渲染了气氛之寂寞凄寒。主人公也许刚刚从梦中醒来，睡眼惺忪，室内画屏闲展：淡淡的烟霭，轻轻的流水。在周围阴氛的罩笼下，幽迷淡远。凝神恍惚中，他仿佛消失在清迷幽幽的画景之中，又仿佛还依回于渺茫、流动的梦境之中。这种主观幻觉，正是由于幽迷宁静的氛围与主人公此时此刻心境的浑然一体所致。是情与景融、意与境浑的佳句。\n\n　　下片写倚窗所见，转入对春愁的正面描写。不期然而然中，他的视线移向了窗外：飞花袅袅，飘忽不定，迷离惝恍；细雨如丝，迷迷蒙蒙，迷漫无际。见飞花之飘缈，不禁忆起残梦之无凭，心中顿时悠起的是细雨蒙蒙般茫无边际的愁绪。本写春梦之无凭与愁绪之无际，却透过窗户摄景着笔于远处的飞花细雨，将情感距离故意推远，越发感生出一种飘缈朦胧、不即不离之美。亦景亦情而柔婉曲折，是“虽不识字人，亦知是天生好言语”（《人玉屑》卷二十一引晁无咎语）的佳例。词人将“梦”与“愁”这种抽象的情感编织在“飞花”、“丝雨”交织的自然画面之中。这种现象，约翰·鲁斯金称为“感情误置”，而这在中国诗词中则为司空见惯。如“感时花溅泪，恨别鸟惊心”、“问君能有几多愁，恰似一江春水向东流”、“便做春江都是泪，流不尽，许多愁”。诗人们心中存有一种感情，移情入景，便往往设想自然也带着这份感情。“以我观物，而物皆著我之色彩”。“自在飞花”，无情无思，格外惹人恼恨，而反衬梦之有情有思。最后，词以“宝帘闲挂小银钩”作结，尤觉摇曳多姿。细推词脉，此句应为过片之倒装句。沉迷于一时之幻境，不经意中瞥向已经挂起的窗帘外面，飞花丝雨映入眼帘，这便引出“自在”二句之文。而在结构艺术上，词人作如是倒装，使得词之上、下片对称工整，显得精巧别致，极富回环变化的结构之美。同时，也进一步唤醒全篇，使帘外的种种愁境，帘内的愁人更为分明，不言愁而愁自现。《续编草堂诗余》曰：“后叠精研，夺南唐席。”正是对此章法技巧的高度评赞。句中“闲”字，本是形容物态，而读者返观全篇，知此正是全词感情基调──百无聊赖的情感意绪。作为红线贯串打通全词，一气运转，跌宕昭彰。张炎说：“秦少游词体制淡雅，气骨不衰，清丽中不断意脉，咀嚼无滓，久而知味。”（《词源》卷下）试观此作，正是如此。\n\n　　此词以柔婉曲折之笔，写一种淡淡的闲愁。在生活中，每个人都会拥有自己的一份闲愁。不知何时何处，它即从你心底无端地升起，说不清也拂不去，令人寂寞难耐。词人们又总是能更敏锐地感受到它，捕捉住它，并流诸笔底。而此时，又必然会渗透进他们对时世人生的独特感受。冯延巳的《鹊踏枝》写出了人人心中皆有的这般闲情，却也包蕴着一种由时代氛围所酿成的说不清、排不开的愁绪。“古之伤心人也”的秦观，年少丧父，仕途抑塞，于新旧党迭为消长之际，一再受到排抑，满腹满腔人生的遭际感慨，泛化为一种凄怨感伤的心境意绪而弥漫于词作之中，呈现出含蓄蕴藉、窈深幽约之美。此词曲折传情而凄清婉美，《词则大雅集》卷二称“宛转幽怨，温韦嫡派”。作为婉约派词人，他正是远祖温韦，近承晏柳，融各家所长为一体，成其细腻含蓄而又凄怨感伤之风格，吟唱出较“花间”、“尊前”更为绸缪凄婉的角声，别具一番魅力。\n\n　　就思想内容来说，秦观的词多写艳情，与晏几道、柳永相似，但却能以语言的翻新、情致的幽趣历来受人激赏。这首词写的是春愁，一种细微幽渺的、不容易捉摸的感情，但作者以他非凡的功力，借具体的景物描写和形象的比喻，将它表现了出来。最具代表性的是它的“自在飞花轻似梦，无边丝雨细如愁。”它将细微的景物与幽渺的感情极为巧妙而和谐地结合在一起，使难以捕捉的抽象的梦与愁成为可以接触的具体形象。沈祖棻《宋词赏析》分析这两句时，说：“它的奇，可以分两层说。第一，‘飞花’和‘梦’， ‘丝雨’和‘愁’，本来不相类似，无从类比。但词人却发现了它们之间有‘轻’和‘细’这两个共同点，就将四样原来毫不相干的东西联成两组，构成了既恰当又新奇的比喻。第二，一般的比喻，都是以具体的事物去形容抽象的事物，或者说，以容易捉摸的事物去比譬难以捉摸的事物。但词人在这里却是反其道而行之。他不说梦似飞花，愁如丝雨，而说飞花似梦，丝雨如愁也同样很新奇。”这两句用语奇绝，特别具有一种音乐美、诗意美和画境美。\n\n　　在文学大家的笔下，对情、意表达的处理常见“举重若轻”和“举轻若重”两种方式。它们都会有理想的表达效果，但秦观在这里的幽情轻吐却有如此的效果，依赖于其善于渲染、语言精美、比喻神奇，但更关键的是内中的那种情致。冯煦称赞说：“他人之词，词才也；少游，词心也。得之于内，不可以传。”（《宋六十一家词选例言》）秦观的个人气质与文体特征已经融而为一。这首词没有一处用重笔，没有痛苦的呐喊，没有深情的倾诉，没有放纵自我的豪兴，没有沉湎往事的不堪。只有对自然界“漠漠轻寒”的细微感受，对“晓阴无赖”的敏锐体察，对“淡烟流水”之画屏的无限感触。这春愁，既没有涉及政治，又没有涉及爱情、友谊，或者其他什么。它其实只是写了一种生活的空虚之感。在一个敏感文人的心里，这种空虚寂寞伴随生命的全程，它和愿望、和理想、和对生命的珍视成正比，无边无际，无计可除。', poem_tags = '宋词三百首,婉约,伤春,春愁' WHERE poem_title = '浣溪沙·漠漠轻寒上小楼' AND poem_author = '秦观';
UPDATE edu_poem SET poem_translation = '葛草长得长又长，漫山遍谷都有它，藤叶茂密又繁盛。黄鹂上下在飞翔，飞落栖息灌木上，鸣叫婉转声清丽。\n葛草长得长又长，漫山遍谷都有它，藤叶茂密又繁盛。割藤蒸煮织麻忙，织细布啊织粗布，做衣穿着不厌弃。\n告诉管家心理话，说我心想回娘家。快把内衣洗干净。洗和不洗分清楚，回娘家去看父母。', poem_notes = '葛：多年生草本植物，花紫红色，茎可做绳，纤维可织葛布，俗称夏布，其藤蔓亦可制鞋（即葛屦），夏日穿用。覃（tán）：本指延长之意，此指蔓生之藤。\n施（yì）：蔓延。中谷：山谷中。\n维：发语助词，无义。萋萋：茂盛貌。\n黄鸟：一说黄鹂，一说黄雀。于：作语助，无义。于飞，即飞。\n集：栖止。\n喈喈（jiē）：鸟鸣声。\n莫莫：茂盛貌。\n刈（yì）：斩，割。濩（huò）：煮。此指将葛放在水中煮。\n絺（chī）：细的葛纤维织的布。綌（xì）：粗的葛纤维织的布。\n斁（yì）：厌。\n言：一说第一人称，一说作语助词。师氏：类似管家奴隶，或指保姆。\n归：本指出嫁，亦可指回娘家。\n薄：语助词。污（wù）：洗去污垢。私：贴身内衣。\n澣（huàn）：浣，洗。衣：上曰衣，下曰裳。此指外衣。\n害（hé）：通“曷”，盍，何，疑问词。否：不。\n归宁：回家慰安父母，或出嫁以安父母之心。', poem_appreciation = '人们常爱用“多义性”来解说诗意，这其实并不准确。“诗言志，歌永言”（《尚书·尧典》）。当诗人作诗以抒写情志之时，其表达意向应该是明确的，不可能存在迥然不同的多种含义。但是，诗人用以表达情志的词语，却往往是多义的。倘若在诗之上下文中，那多种含义均可贯通，说诗者就很难判断，究竟何义为作者所欲表达的“原意”了。为了不至过于武断，人们只好承认：那首诗本有着“多种含义”。对于《葛覃》，遇到的也正是这样一个难题。这首诗的主旨，全在末章点示的“归宁父母”一句。然而“归”在古代，既可指称女子之出嫁，如《桃夭》的“之子于归”；又可指称出嫁女子的回返娘家，如《左传·庄公二十七年》记“冬，杞伯姬来，归宁也”。所以，《毛诗序》定此诗为赞美“后妃”出嫁前“志在女工之事，躬俭节用，服澣濯之衣，尊敬师傅”的美德，其出嫁可以“安父母，化天下以妇道也”；而今人余冠英等则以为，这是抒写一贵族女子准备归宁（回娘家）之情的诗。二者对主旨的判断相去甚远，但在诗意上又均可圆通。究竟取“出嫁”说好呢，还是“回娘家”说好，也实在无法与诗人对证，只能留下一个悬案。\n\n　　不管抒情主人公是待嫁女还是新嫁娘，她此刻正处在喜悦而急切的企盼之中却毫无疑问。诗分三章，展出的是跳跃相接的三幅画境。首章似乎无人，眼间只见一派清碧如染的葛藤，蔓延在幽静的山沟；然而这幽静的清碧，又立即为一阵“喈喈”的鸣啭打破，抬眼一看，原来是美丽的黄雀，在灌木丛上啁哳。这“无人”的境界只是作者营造的一种画境，在那绿葛、黄雀背后，还有一位喜悦的女主人公，在那里顾盼、聆听。次章终于让女主人公走进了诗中，但那身影却是飘忽的：刚看到她弯腰“刈”藤的情景，转眼间又见她在家中“濩”葛、织作了。于是那萋萋满谷的葛藤，又幻化成一匹匹飘拂的葛布；而女主人公，则已在铜镜前披着这“絺綌”，正喜孜孜试身。那一句“服之无斁”，透露着辛勤劳作后无限的快慰和自豪。三章的境界却又一变，诗行中多了位慈祥的“师氏”。她似乎在倾听，又似乎在指点，因为她的女主人，此刻正央求她告知急需澣洗的衣物。“害澣？害否？归宁父母”——那便是情急的女主人公，带着羞涩和抑制不住的喜悦，终于向师氏透露的内心的秘密。这里终于透露出，这位女主人公，原来是一位急切待“归”（出嫁或者回娘家）的新人。这样，前两章的似断似续，山谷中葛藤、黄雀的美好春景，和“刈濩”、织作的繁忙劳动，就不仅传达着女主人公期盼中的喜悦，而且表现着一种熟习女工、勤劳能干的自夸自赞了。这样的女子，无论是嫁到夫家还是回返娘家，都是足以令夫家爱怜并带给父母莫大安慰的。\n\n　　在中国的传统中，对女子的要求从来是严苛的。所谓“妇德、妇言、妇功、妇容”，便是古代的男子世界所强加给女子必须习练的“妇教”。其要在于规定女子必须“贞顺”、“婉媚”和勤于丝麻织作之劳，老老实实作男子的附庸和婢妾，若非如此，便不配为人之妇。此诗所表现的，便正是一位“待归”女子勤于“妇功”的情景。', poem_tags = '诗经,写人' WHERE poem_title = '葛覃' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '回忆当年鹏程万里为了寻找建功立业的机会，单枪匹马奔赴边境保卫梁州。如今防守边疆要塞的从军生活只能在梦中出现，梦一醒不知身在何处？灰尘已经盖满了旧时出征的貂裘。\n胡人还未消灭，鬓边已呈秋霜，感伤的眼泪白白地淌流。这一生谁能预料，原想一心一意抗敌在天山，如今却一辈子老死于沧洲！', poem_notes = '诉衷情：词牌名。\n万里觅封侯：奔赴万里外的疆场，寻找建功立业的机会。\n戍（shù）：守边。梁州：治所在南郑。陆游著作中，称其参加四川宣抚使幕府所在地，常杂用以上地名。\n关河：关塞、河流。一说指潼关黄河之所在。此处泛指汉中前线险要的地方。梦断：梦醒。\n尘暗旧貂裘：貂皮裘上落满灰尘，颜色为之暗淡。这里借用苏秦典故，说自己不受重用，未能施展抱负。\n胡：古泛称西北各族为胡，亦指来自彼方之物。南宋词中多指金人。此处指金入侵者。\n鬓：鬓发。秋：秋霜，比喻年老鬓白。\n天山：在中国西北部，是汉唐时的边疆。这里代指南宋与金国相持的西北前线。\n沧洲：靠近水的地方，古时常用来泛指隐士居住之地。这里是指作者位于镜湖之滨的家乡。', poem_appreciation = '陆游四十八岁，应四川宣抚使王炎之邀，从夔州前往当时西北前线重镇南郑（今陕西汉中）军中任职，度过了八个多月的戎马生活。　开篇两句，怀着自豪的心情回忆从戎南郑的生活。起处用“当年”二字领起，化实为虚，点出所叙系指往事。“觅封侯”，谓寻找杀敌立功以取封侯的机会。“匹马”既是纪实，也刻划出作者从军时的勃勃英姿。“戍梁州”，具体指出驻守的地方。南郑属古梁州，故曰。那是乾道八年（1172）的春天，陆游接到王炎的邀请书后，便匹马单身离开夔州，风尘仆仆地奔赴前线，去任“四川宣抚使司干办公事兼检法官”。当时他十分兴奋，希望能在万里边防线上找到杀敌报国的机会。来到南郑之后，他身披铁甲，跨上战马，腰悬利剑，手挽长枪，冒着酷暑严寒，踏着崎岖坎坷的山路，奔驰于岐渭蜀陇之间，调查地形，了解敌情，积极为北伐进行准备。他曾向王炎陈进取之策，对收复失地、统一祖国充满了胜利的信心。诗人回忆这段生活，是为了与后文对照，揭示英雄末路的悲哀。\n\n　　“关河”两句一转，回笔描写现实。杀敌报国的理想破灭了，而今只有在梦中才能重返前线。可是梦醒之后，一切都消失了，那雄伟险峻的关山江河又在什么地方呢？只有当年从军时穿过的那件“旧貂裘”，积满灰尘，还挂在墙上，作为“匹马戍梁州”的纪念。陆游对这件“旧貂裘”十分珍视，因为他曾穿着它在前线冲锋陷阵：“貂裘半脱马如龙，举鞭指麾气吐虹。”（《醉歌》）还穿着它在荒滩上亲手剌死过一只猛虎：“百骑河滩猎盛秋，至今血溅短貂裘”。（《醉歌》）所以当他离开南郑后，一直把它藏在身边保存着。“旧貂裘”是此篇中唯一展现在作者眼前的物象，虽然词中只用一句轻轻带过，但却是理解此词的关键。原来诗人是睹物伤情，因见貂裘而引起对往事的回忆和感慨。也可以说，“旧貂裘”是这首词灵感的触媒。\n\n　　换头三句，紧承上片结拍，写梦醒后的悲凉心情。“胡未灭”，谓入侵中原的金人尚未被消灭，半壁河山还在敌寇的铁蹄蹂躏之下；“鬓先秋”，慨叹自己发如秋霜，年迈体衰，不能重返前线；“泪空流”，是说壮志成空，忧国忧民的眼泪等于白流。这里连用“未”、“先”、“空”三个虚词，表达作者对现实的幻灭感，一唱一叹，感人至深。 “未”表达了作者逆胡（金入侵者）没有消灭，功业没有建成，感到无比遗恨之情；“先”表达了作者岁月不多，两鬓已苍，雄心虽在，壮志难酬的沉痛之情；“空”表达了作者对朝廷的不满和愤慨，内心的失望和痛苦之情。\n\n　　最后三句，通过自身的遭遇反映现实和理想的矛盾，抒发对南宋统治集团误国误民政策的无比愤慨。谁会料到，像他这样一生志在恢复中原，时刻准备奔赴疆场，为国献身的人，却落得如此下场！此时被罢官回乡，只得披上渔蓑，去作江边的无名隐士，终老于镜湖之滨了。这种“心在天山，身老沧洲”的矛盾，不仅体现在陆游身上，南宋许多爱国志士同样也有切身的体验。因此陆游所抒发的悲愤之情，具有一定的代表性。梁启超《读陆放翁集》（之二）说：“辜负胸中十万兵，百无聊赖以诗名。谁怜爱国千行泪，说到胡尘意不平。”这首词虽然没有从正面揭露和谴责南宋投降派，仅就个人的身世经历和遭遇而言，但通过诗人饱含热泪的诉说，不难看到投降派迫害爱国志士的罪行，从而激起读者对他们的愤恨。\n\n　　此篇语言明白晓畅，用典自然，不着痕迹，感情自胸臆流出，不加雕饰，如叹如诉，沉郁苍凉，有较强的艺术感染力，是陆游爱国词作的名篇之一。', poem_tags = '宋词三百首,宋词精选,爱国,豪放' WHERE poem_title = '诉衷情·当年万里觅封侯' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '我在高大的古树阴下拴好了小船；拄着拐杖，走过小桥，恣意欣赏这美丽的春光。\n丝丝细雨，淋不湿我的衣衫；它飘洒在艳丽的杏花上，使花儿更加灿烂。阵阵微风，吹着我的脸已不使人感到寒；它舞动着嫩绿细长的柳条，格外轻飏。', poem_notes = '系（xì）：联接。短篷：小船。篷，船帆，船的代称。\n杖藜：“藜杖”的倒文。藜，一年生草本植物，茎杆直立，长老了可做拐杖。\n杏花雨：清明前后杏花盛开时节的雨。\n杨柳风：古人把应花期而来的风，称为花信风。从小寒到谷雨共二十四候，每候应一种花信，总称“二十四花信风”。其中清明节尾期的花信是柳花，或称杨柳风。', poem_appreciation = '这是一首脍炙人口的七绝名诗。诗僧志南亦因这首描写二月春景的诗而名留千古。\n\n　　首二句写诗人的行踪，尾二句写诗人眼中的春光。首二句用笔精妙，予人以清凉幽静的美感：斑驳的古木、汩汩的溪水、轻巧的篷船、虬曲的杖藜、古朴的小桥和无事的老僧，构成一幅浑然天成的游春图。一句“杖藜扶我过桥东”，诗意地表现了禅宗所崇尚的物我合一的佳境。尾二句造语疏清，予人以清新悠然的体味：小桥东边，杏花如烟，杨柳如线，细雨如酥，和风如丝。那杏花烟雨，欲沾人衣而不湿，何其令人惬意；那杨柳和风，吹在脸上凉美而不觉寒冷，它们是何等善解人意。这清凉的春意，不正是春天清凉的禅意的昭示么？这迷人的春景，正是诗人眼中迷人的禅境。\n\n　　在诗人眼中，禅就在古木中、溪水里、篷船上、杖藜头，在小桥东边，在老僧心头，在杏花雨中，在杨柳风里，在那沾而欲湿的凉意中，在吹面不寒的清柔里，禅就是春天，就是一切的一切，就是绝句，就是诗！\n\n　　“诗有四种高妙：一曰理高妙，二曰意高妙，三曰想高妙，四曰自然高妙。碍而实通，曰理高妙；出自意外，曰意高妙；写出幽微，如清潭见底，曰想高妙；非奇非怪，剥落文采，知其妙而不知其所以妙，曰自然高妙。”(宋·姜夔《白石道人诗说》)不说理，也不说禅，却极有禅趣，本诗可谓是自然高妙！', poem_tags = '古诗三百首,春游,写风,写雨' WHERE poem_title = '绝句·古木阴中系短篷' AND poem_author = '志南';
UPDATE edu_poem SET poem_translation = '青青的是你的衣领，悠悠的是我的思念。纵然我不曾去会你，难道你不把音信传？\n青青的是你的佩带，悠悠的是我的情怀。纵然我不曾去找你，难道你不能主动来？\n来来往往张眼望啊，在这高高的城楼上。一天不见你的面啊，好像有三月那样长！', poem_notes = '子衿：周代读书人的服装。子，男子的美称，这里即指“你”。衿，即襟，衣领。\n悠悠：忧思不断的样子。\n宁（nìng）：岂，难道。嗣（yí）音：寄传音讯。嗣，通“贻”，给、寄的意思 。\n佩：这里指系佩玉的绶带。\n挑（táo）兮达（tà）兮：独自走来走去的样子。挑，也作“佻”。\n城阙：城门两边的观楼。', poem_appreciation = '这首诗写一个女子在城楼上等候她的恋人。全诗三章，采用倒叙手法。前两章以“我”的口气自述怀人。“青青子衿”，“青青子佩”，是以恋人的衣饰借代恋人。对方的衣饰给她留下这么深刻的印象，使她念念不忘，可想见其相思萦怀之情。如今因受阻不能前去赴约，只好等恋人过来相会，可望穿秋水，不见影儿，浓浓的爱意不由转化为惆怅与幽怨：“纵然我没有去找你，你为何就不能捎个音信？纵然我没有去找你，你为何就不能主动前来？”第三章点明地点，写她在城楼上因久候恋人不至而心烦意乱，来来回回地走个不停，觉得虽然只有一天不见面，却好像分别了三个月那么漫长。\n\n　　全诗五十字不到，但女主人公等待恋人时的焦灼万分的情状宛然如在目 前。这种艺术效果的获得，在于诗人在创作中运用了大量的心理描写。诗中表现这个女子的动作行为仅用“挑”“达”二字，主要笔墨都用在刻划她的心理活动上，如前两章对恋人既全无音问、又不见影儿的埋怨，末章“一日不见，如三月兮”的独白。两段埋怨之辞，以“纵我”与“子宁”对举，急盼之情中不无矜持之态，令人生出无限想像，可谓字少而意多。末尾的内心独自，则通过夸张修辞技巧，造成主观时间与客观时间的反差，从而将其强烈的情绪心理形象地表现了出来，可谓因夸以成状，沿饰而得奇。心理描写手法，在后世文坛已发展得淋漓尽致，而上溯其源，此诗已开其先。\n\n　　这首诗是《诗经》众多情爱诗歌作品中较有代表性的一篇，它鲜明地体现了那个时代的女性所具有的独立、自主、平等的思想观念和精神实质，女主人公在诗中大胆表达自己的情感，即对情人的思念。这在《诗经》以后的历代文学作品中是少见的。', poem_tags = '诗经' WHERE poem_title = '子衿' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '一个小孩撑着小船，偷偷地采了白莲回来。\n他不知道怎么掩藏踪迹，水面的浮萍上留下了一条船儿划过的痕迹。', poem_notes = '小娃：男孩儿或女孩儿。艇：船。\n白莲：白色的莲花。\n踪迹：指被小艇划开的浮萍。\n浮萍：水生植物，椭圆形叶子浮在水面，叶下面有须根，夏季开白花。', poem_appreciation = '这首诗写一个小孩儿偷采白莲的情景。从诗的小主人公撑船进入画面，到他离去只留下被划开的一片浮萍，有景有色，有行动描写，有心理刻画，细致逼真，富有情趣；而这个小主人公的天真幼稚、活泼淘气的可爱形象，也就栩栩如生，跃然纸上了。\n\n　　诗人在诗中叙述一个小娃娃生活中的一件小事，准确地捕捉了小娃娃瞬间的心情，勾画出一幅采莲图。莲花盛开的夏日里，天真活泼的儿童，撑着一条小船，偷偷地去池中采摘白莲花玩。兴高采烈地采到莲花，早已忘记自己是瞒着大人悄悄地去的，不懂得或是没想到去隐蔽自己的踪迹，得意忘形地大摇大摆划着小船回来，小船把水面上的浮萍轻轻荡开，留下了一道清晰明显的水路痕迹。诗人以他特有的通俗风格将诗中的小娃娃描写得非常可爱、可亲，整首诗如同大白话，富有韵味。\n\n　　白居易是一位擅长写叙事诗的大诗人。他的长篇叙事诗，将所叙事物写得曲折详尽、娓娓动听，饱含着诗人自己的情感。同样的，他的诗中小品，更通俗平易。《池上二绝》就是这样一组描写一种平凡生活的小诗。诗人以他特有的通俗风格，将两个小景写得可爱、可亲、可信。', poem_tags = '儿童,生活,早教古诗100首' WHERE poem_title = '池上' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '明天又一个明天，明天何等的多。\n我的一生都在等待明日，什么事情都没有进展。\n世人和我一样辛苦地被明天所累，一年年过去马上就会老。\n早晨看河水向东流逝，傍晚看太阳向西坠落才是真生活。\n百年来的明日能有多少呢？请诸位听听我的《明日歌》。', poem_notes = '①复：又。\n②何其：多么。这句说：明日是何等的多啊。\n③待：等待。\n④蹉跎（cuō tuó）：光阴虚度。以上两句说：如果天天只空等明天，那么只会空度时日，一事无成。\n⑤若：一作“苦”，有些版本为“世人苦被明日累。”\n⑥累（lěi）：带累，使受害。这句说：世上的人都受“待明日”的害处。\n⑦请君：请诸位。', poem_appreciation = '这一首诗七次提到“明日”，反复告诫人们要珍惜时 间，今日的事情今日做，不要拖到明天，不要蹉跎岁月。诗歌的意思浅显，语言明白如话，说理通俗易懂，很有教育意义。\n\n　　这一首《明日歌》给人的启示是：世界上的许多东西都能尽力争取和失而复得，只有时间难以挽留。人的生命只有一次，时间永不回头。不要今天的事拖明天，明天拖后天。要“今天的事，今日毕。”\n\n　　《明日歌》自问世至今，数百年来广为世人传颂，经久不衰。诗人在作品中告诫和劝勉人们要牢牢地抓住稍纵即逝的今天，今天能做的事一定要在今天做，不要把任何计划和希望寄托在未知的明天。今天才是最宝贵的，只有紧紧抓住今天，才能有充实的明天，才能有所作为，有所成就。否则，“明日复明日，”到头来只会落得个“万事成蹉跎”，一事无成，悔恨莫及。因此，无论做什么事都应该牢牢铭记：一切从今天开始，一切从现在开始。\n\n　　这首诗内容充实，语言流畅，释理通俗明了，说服力强。', poem_tags = '小学古诗,劝诫,惜时,哲理' WHERE poem_title = '明日歌' AND poem_author = '钱福';
UPDATE edu_poem SET poem_translation = '那遥远而亮洁的牵牛星，那皎洁而遥远的织女星。\n织女正摆动柔长洁白的双手，织布机札札不停地响个不停。\n因为相思而整天也织不出什么花样，她哭泣的泪水零落如雨。\n只隔了道清清浅浅的银河，他俩相界离也没有多远。\n相隔在清清浅浅的银河两边，含情脉脉相视无言地痴痴凝望。', poem_notes = '迢（tiáo）迢：遥远的样子。牵牛星：河鼓三星之一，隔银河和织女星相对，俗称“牛郎星”，是天鹰星座的主星，在银河东。\n皎皎：明亮的样子。河汉女：指织女星，是天琴星座的主星，在银河西，与牵牛星隔河相对。河汉，即银河。\n纤纤：纤细柔长的样子。擢（zhuó）：引，抽，接近伸出的意思。素：洁白。\n札（zhá）札：象声词，机织声。弄：摆弄。杼（zhù）：织布机上的梭子。\n章：指布帛上的经纬纹理，这里指整幅的布帛。此句是用《诗经·小雅·大东》语意，说织女终日也织不成布。《诗经》原意是织女徒有虚名，不会织布。而这里则是说织女因相思，而无心织布。\n涕：眼泪。零：落下。\n清且浅：清又浅。\n相去：相离，相隔。去，离。复几许：又能有多远。\n盈盈：水清澈、晶莹的样子。一说形容织女，《文选》六臣注：“盈盈，端丽貌。”一水：指银河。间（jiàn）：间隔。\n脉（mò）脉：含情相视的样子。一作“默默”，默默地用眼神或行动表达情意。', poem_appreciation = '这首诗借神话传说中牛郎、织女被银河相隔而不得相见的故事，抒发了因爱情遭受挫折而痛苦忧伤的心情。\n\n　　此诗描写天上的一对夫妇牵牛和织女，视点却在地上，是以第三者的角度观察他们夫妇的离别之苦。开头两句分别从两处落笔，言牵牛曰“迢迢” 状织女曰“皎皎”。迢迢、皎皎互文见义，不可执着。牵牛也皎皎，织女也迢迢。他们都是那样的遥远，又是那样的明亮。但以迢迢属之牵牛，则很容易让人联想到远在他乡的游子，而以皎皎属之织女，则很容易让人联想到女性的美。如此说来，似乎又不能互换了。如果因为是互文，而改为“皎皎牵牛星，迢迢河汉女”，其意趣就减去了一半。诗歌语言的微妙于此可见一斑。称织女为“河汉女”是为了凑成三个音节，而又避免用“织女星”在三字。上句已用了“牵牛星”，下句再说“织女星”，既不押韵，又显得单调。“河汉女”就活脱多了。“河汉女”的意思是银河边上的那个女子，这说法更容易让人联想到一个真实的女人，而忽略了她本是一颗星。不知作者写诗时是否有这番苦心，反正写法不同，艺术效果亦迥异。总之，“迢迢牵牛星，皎皎河汉女”这十个字的安排，可以说是最巧妙的安排而又具有最浑成的效果。\n\n　　以下四句专就织女这一方面来写，说她虽然整天在织，却织不成匹，因为她心里悲伤不已。“纤纤擢素手”意谓擢纤纤之素手，为了和下句“札札弄机杼”对仗，而改变了句子的结构。“擢”者，引也，抽也，接近伸出的意思 “札札”是机杼之声。“杼”是织布机上的梭子。诗人在这里用了一个“弄”字。《诗经·小雅·斯干》：“乃生女子，载弄之瓦。”这弄字是玩、戏的意思。织女虽然伸出素手，但无心于机织，只是抚弄着机杼，泣涕如雨水一样滴下来 “终日不成章”化用《诗经·大东》语意：“彼织女，终日七襄。虽则七襄，不成报章。”\n\n　　最后四句是诗人的慨叹：“河汉清且浅，相去复几许？盈盈一水间，脉脉不得语。”那阻隔了牵牛和织女的银河既清且浅，牵牛与织女相去也并不远，虽只一水之隔却相视而不得语也。“盈盈”或解释为形容水之清浅，或者不是形容水，字和下句的“脉脉”都是形容织女。《文选》六臣注：“盈盈 端丽貌。”是确切的。人多以为“盈盈”既置于“一水”之前，必是形容水的 但盈的本意是满溢，如果是形容水，那么也应该是形容水的充盈，而不是形容水的清浅。把盈盈解释为清浅是受了上文“河汉清且浅”的影响，并不是盈盈的本意。《文选》中出现“盈盈”除了这首诗外，还有“盈盈楼上女 皎皎当窗牖”。亦见于《古诗十九首》。李善注：“《广雅》曰：‘赢，容也。’盈与赢同，古字通。”这是形容女子仪态之美好，所以五臣注引申为“端丽”。又汉乐府《陌上桑》：“盈盈公府步，冉冉府中趋。”也是形容人的仪态。织女既被称为河汉女，则其仪容之美好亦映现于河汉之间，这就是“盈盈一水间”的意思。“脉脉”，李善注 “《尔雅》曰‘脉，相视也’。郭璞曰‘脉脉谓相视貌也’。”“脉脉不得语”是说河汉虽然清浅，但织女与牵牛只能脉脉相视而不得语。', poem_tags = '古诗三百首,古诗十九首,七夕节,离别' WHERE poem_title = '迢迢牵牛星' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '暮色苍茫，更觉前行山路遥远。天寒地冻，倍觉投宿人家清贫。\n忽然听得柴门狗叫，应是主人风雪夜归。', poem_notes = '逢：遇上。\n宿：投宿；借宿。\n芙蓉山主人：芙蓉山，各地以芙蓉命山名者甚多，这里大约是指湖南桂阳或宁乡的芙蓉山。主人，即指留诗人借宿者。这首诗通过雪夜借宿山村的情形，巧妙地写出山村景象与农家生活。\n日暮：傍晚的时候。\n苍山远：青山在暮色中影影绰绰显得很远。苍：青色。\n白屋：未加修饰的简陋茅草房。一般指贫苦人家。\n犬吠：狗叫。\n夜归人：夜间回来的人。', poem_appreciation = '这首诗用极其凝炼的诗笔，描画出一幅以旅客暮夜投宿、山家风雪人归为素材的寒山夜宿图。诗是按时间顺序写下来的。首句写旅客薄暮在山路上行进时所感，次句写到达投宿人家时所见，后两句写入夜后在投宿人家所闻。每句诗都构成一个独立的画面，而又彼此连属。诗中有画，画外见情。\n\n　　诗的开端，以“日暮苍山远”五个字勾画出一个暮色苍茫、山路漫长的画面。诗句中并没有明写人物，直抒情思，但其人呼之欲出，其情浮现纸上。这里，点活画面、托出诗境的是一个“远”字，从这一个字可以推知有行人在暮色来临的山路上行进时的孤寂劳顿的旅况和急于投宿的心情。接下来，诗的次句使读者的视线跟随这位行人，沿着这条山路投向借宿人家。“天寒白屋贫”是对这户人家的写照；而一个“贫”字，应当是从遥遥望见茅屋到叩门入室后形成的印象。上句在“苍山远”前先写“日暮”，这句则在“白屋贫”前先写“天寒”，都是增多诗句层次、加重诗句分量的写法。漫长的山路，本来已经使人感到行程遥远，又眼看日暮，就更觉得遥远；简陋的茅屋，本来已经使人感到境况贫穷，再时逢寒冬，就更显出贫穷。而联系上下句看，这一句里的“天寒”两字，还有其承上启下作用。承上，是进一步渲染日暮路遥的行色；启下，是作为夜来风雪的伏笔。\n\n　　这前两句诗，合起来只用了十个字，已经把山行和投宿的情景写得神完气足了。后两句诗“柴门闻犬吠，风雪夜归人”，写的是借宿山家以后的事。在用字上，“柴门”上承“白屋”，“风雪”遥承“天寒”，而“夜”则与“日暮”衔接。这样，从整首诗来说，虽然下半首另外开辟了一个诗境，却又与上半首紧紧相扣。但这里，在承接中又有跳越。看来，“闻犬吠”既在夜间，山行劳累的旅人多半已经就寝；而从暮色苍茫到黑夜来临，从寒气侵人到风雪交作，从进入茅屋到安顿就寝，中间有一段时间，也应当有一些可以描写的事物，可是诗笔跳过了这段时间，略去了一些情节，即使诗篇显得格外精炼，也使承接显得更加紧凑。诗人在取舍之间是费了一番斟酌的。如果不下这番剪裁的功夫，也许下半首诗应当进一步描写借宿人家境况的萧条，写山居的荒凉和环境的静寂，或写夜间风雪的来临，再不然，也可以写自己的孤寂旅况和投宿后静夜所思。但诗人撇开这些不去写，出人意外地展现了一个在万籁俱寂中忽见喧闹的犬吠人归的场面。这就在尺幅中显示变化，给人以平地上突现奇峰之感。\n\n　　就写作角度而言，前半首诗是从所见之景着墨，后半首诗则是从所闻之声下笔的。因为，既然夜已来临，人已就寝，就不可能再写所见，只可能写所闻了。“柴门”句写的应是黑夜中、卧榻上听到的院内动静：“风雪”句应也不是眼见，而是耳闻，是因听到各种声音而知道风雪中有人归来。这里，只写“闻犬吠”，可能因为这是最先打破静夜之声，也是最先入耳之声，而实际听到的当然不只是犬吠声，应当还有风雪声、叩门声、柴门启闭声、家人回答声，等等。这些声音交织成一片，尽管借宿之人不在院内，未曾目睹，但从这一片嘈杂的声音足以构想出一幅风雪人归的画面。\n\n　　全诗纯用白描手法，语言朴实无华，格调清雅淡静，却具有悠远的意境与无穷的韵味。', poem_tags = '山村,写景,冬天,写雪,写风,写人,早教古诗100首,写狗古诗18首' WHERE poem_title = '逢雪宿芙蓉山主人' AND poem_author = '刘长卿';
UPDATE edu_poem SET poem_translation = '去年春天，就在这扇门里，姑娘脸庞，相映鲜艳桃花。\n今日再来此地，姑娘不知去向何处，只有桃花依旧，含笑怒放春风之中。', poem_notes = '都：国都，指唐朝京城长安。\n人面：指姑娘的脸。第三句中“人面”指代姑娘。\n不知：一作“秖（zhǐ）今”。去：一作“在”。\n笑：形容桃花盛开的样子。', poem_appreciation = '全诗四句，这四句诗包含着一前一后两个场景相同、相互映照的场面。\n\n　　第一个场面：寻春遇艳——“去年今日此门中，人面桃花相映红。”诗人抓住了“寻春遇艳”整个过程中最美丽动人的一幕。“人面桃花相映红”，不仅为艳若桃花的“人面”设置了美好的背景，衬出了少女光彩照人的面影，而且含蓄地表现出诗人目注神驰、情摇意夺的情状，和双方脉脉含情、未通言语的情景。\n\n　　第二个场面：重寻不遇。还是春光烂漫、百花吐艳的季节，还是花木扶疏、桃树掩映的门户，然而，使这一切都增光添彩的“人面”却不知何处去，只剩下门前一树桃花仍旧在春风中凝情含笑。桃花在春风中含笑的联想，本从“人面桃花相映红”得来。去年今日，伫立桃树下的那位不期而遇的少女，想必是凝睇含笑，脉脉含情的；而今，人面杳然，依旧含笑的桃花只能引动对往事的美好回忆和好景不常的感慨了。“依旧”二字，正含有无限怅惘。\n\n　　整首诗其实就是用“人面”、“桃花”作为贯串线索，通过“去年”和“今日”同时同地同景而“人不同”的映照对比，把诗人因这两次不同的遇合而产生的感慨，回环往复、曲折尽致地表达了出来。对比映照，在这首诗中起着极重要的作用。因为是在回忆中写已经失去的美好事物，所以回忆便特别珍贵、美好，充满感情，这才有“人面桃花相映红”的传神描绘；正因为有那样美好的记忆，才特别感到失去美好事物的怅惘，因而有“人面不知何处去，桃花依旧笑春风”的感慨。\n\n　　尽管这首诗有某种情节性，有富于传奇色彩的“本事”，甚至带有戏剧性，但它并不是一首小叙事诗，而是一首抒情诗。“本事”可能有助于它的广泛流传，但它本身所具的典型意义却在于抒写了某种人生体验，而不在于叙述了一个人们感兴趣的故事。它诠释了一种普遍性的人生体验：在偶然、不经意的情况下遇到某种美好事物，而当自己去有意追求时，却再也不可复得。这也许正是这首诗保持经久不衰的艺术生命力的原因之一。\n\n　　“寻春遇艳”和“重寻不遇”是可以写成叙事诗的。作者没有这样写，正说明唐人更习惯于以抒情诗人的眼光、感情来感受生活中的情事。', poem_tags = '写景,故事,抒情' WHERE poem_title = '题都城南庄' AND poem_author = '崔护';
UPDATE edu_poem SET poem_translation = '秋水胜涨，几乎与岸平，水天含混迷茫与天空浑然一体。云梦大泽水气蒸腾白白茫茫，波涛汹涌似乎把岳阳城撼动。\n我想渡水苦于找不到船与桨，圣明时代闲居委实羞愧难容。闲坐观看别人辛勤临河垂钓，只能白白羡慕被钓上来的鱼。', poem_notes = '张丞相：指张九龄（673-740），唐玄宗时宰相，后贬为荆州长史。\n涵虚：包含天空，指天倒映在水中。涵：包容。虚：虚空，空间。\n混太清：与天混成一体。清：指天空。\n云梦泽：古时云泽和梦泽指湖北南部、湖南北部一代低洼地区。洞庭湖是它南部的一角。岳阳城：在洞庭湖东岸。\n济：渡。\n端居：安居。\n耻(chǐ)圣明：有愧于圣明之世。圣明：指太平盛世，古时认为皇帝圣明社会就会安定。\n徒：只能。\n楫：（jí）划船用具，船桨', poem_appreciation = '洞庭湖，是中国第二大淡水湖，在湖南北部。张丞相指张九龄。这是一首投赠之作，诗人希望时任中书令的张九龄予以援引，但是，诗人却没有直说，而是通过面临烟波浩淼的洞庭欲渡无舟的感叹以及临渊而羡鱼的情怀而曲折地表达出来，已具浓郁的诗意，同时，对于在此本来是藉以表意的洞庭湖，在诗人的笔下却得到泼墨山水般的大笔渲绘，呈现出八百里洞庭的阔大境象与壮伟景观，实际上已成为山水杰作。\n\n　　首先点明时令，时值“八月”，湖水泛溢，可见当年秋汛汹涌，一个“平”字，可见湖水涨漫，已溢出堤岸，造成湖水与湖岸相平的景象。洞庭本来就号称八百里，加上这样的浩大水势，其水岸相接、广阔无垠的情状更增浩瀚气势。此时，诗人面对洞庭，极目远望，则不仅水岸相平，而且呈现出水天相接的景象，仰观俯瞰，天空映照湖中，似乎是湖水包孕了天宇，“涵虚”，足见其大，“混太清”，足见其阔。如此壮阔的湖面，自然风云激荡，波涛汹涌，古老的云梦泽似乎在惊涛中沸滚蒸腾，雄伟的岳阳城似乎被巨浪冲撞得摇荡不已，一个“蒸”字，一个“撼”字，力重千钧，自然的湖泊一下子具有了自觉的意识，静态的地理由此取得了飞扬的动势，足见其非凡的艺术表现力和撼人心魄的艺术效果。', poem_tags = '唐诗三百首,初中古诗,山水,写水,地名' WHERE poem_title = '望洞庭湖赠张丞相 / 临洞庭湖赠张丞相' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '我被囚禁在北国的都城，住在一间土屋内。土屋有八尺宽，大约四寻深。有一道单扇门又低又小，一扇白木窗子又短又窄，地方又脏又矮，又湿又暗。碰到这夏天，各种气味都汇聚在一起：雨水从四面流进来，甚至漂起床、几，这时屋子里都是水气；屋里的污泥因很少照到阳光，蒸熏恶臭，这时屋子里都是土气；突然天晴暴热，四处的风道又被堵塞，这时屋子里都是日气；有人在屋檐下烧柴火做饭，助长了炎热的肆虐，这时屋子里都是火气；仓库里储藏了很多腐烂的粮食，阵阵霉味逼人，这时屋子里都是霉烂的米气；关在这里的人多，拥挤杂乱，到处散发着腥臊汗臭，这时屋子里都是人气；又是粪便，又是腐尸，又是死鼠，各种各样的恶臭一起散发，这时屋子里都是秽气。这么多的气味加在一起，成了瘟疫，很少有人不染病的。可是我以虚弱的身子在这样坏的环境中生活，到如今已经两年了，却没有什么病。这大概是因为有修养才会这样吧。然而怎么知道这修养是什么呢？孟子说：“我善于培养我心中的浩然之气。“它有七种气，我有一种气，用我的一种气可以敌过那七种气，我担忧什么呢！况且博大刚正的，是天地之间的凛然正气。 （因此）写成这首《正气歌》。\n\n天地之间有一股堂堂正气，它赋予万物而变化为各种体形。\n在下面就表现为山川河岳，在上面就表现为日月辰星。\n在人间被称为浩然之气，它充满了天地和寰宇。\n国运清明太平的时候，它呈现为祥和的气氛和开明的朝廷。\n时运艰危的时刻义士就会出现，他们的光辉形象一一垂于丹青。\n在齐国有舍命记史的太史简，在晋国有坚持正义的董狐笔。\n在秦朝有为民除暴的张良椎，在汉朝有赤胆忠心的苏武节。\n它还表现为宁死不降的严将军的头，表现为拼死抵抗的嵇侍中的血。\n表现为张睢阳誓师杀敌而咬碎的齿，表现为颜常山仗义骂贼而被割的舌。\n有时又表现为避乱辽东喜欢戴白帽的管宁，他那高洁的品格胜过了冰雪。\n有时又表现为写出《出师表》的诸葛亮，他那死而后已的忠心让鬼神感泣。\n有时表现为祖逖渡江北伐时的楫，激昂慷慨发誓要吞灭胡羯。\n有时表现为段秀实痛击奸人的笏，逆贼的头颅顿时破裂。\n这种浩然之气充塞于宇宙乾坤，正义凛然不可侵犯而万古长存。\n当这种正气直冲霄汉贯通日月之时，活着或死去根本用不着去谈论！\n大地靠着它才得以挺立，天柱靠着它才得以支撑。\n三纲靠着它才能维持生命，道义靠着它才有了根本。\n可叹的是我遭遇了国难的时刻，实在是无力去安国杀贼。\n穿着朝服却成了阶下囚，被人用驿车送到了穷北。\n如受鼎镬之刑对我来说就像喝糖水，为国捐躯那是求之不得。\n牢房内闪着点点鬼火一片静谧，春院里的门直到天黑都始终紧闭。\n老牛和骏马被关在一起共用一槽，凤凰住在鸡窝里像鸡一样饮食起居。\n一旦受了风寒染上了疾病，那沟壑定会是我的葬身之地，\n如果能这样再经历两个寒暑，各种各样的疾病就自当退避。\n可叹的是如此阴暗低湿的处所，竞成了我安身立命的乐土住地。\n这其中难道有什么奥秘，一切寒暑冷暖都不能伤害我的身体。\n因为我胸中一颗丹心永远存在，功名富贵对于我如同天边的浮云。\n我心中的忧痛深广无边，请问苍天何时才会有终极。\n先贤们一个个已离我远去，他们的榜样已经铭记在我的心里。\n屋檐下我沐着清风展开书来读，古人的光辉将照耀我坚定地走下去。', poem_notes = '予：我，一作余。北庭：指元朝首都大都（今北京）。\n寻：古时八尺为一寻。\n单扉：单扇门。\n白间：窗户。\n污下：低下。\n萃然：聚集的样子。\n雨潦：下雨形成的地上积水。\n涂泥半朝：“朝”当作“潮”，意思是狱房墙上涂的泥有一半是潮湿的。\n蒸沤历澜：热气蒸，积水沤，到处都杂乱不堪。澜：澜漫，杂乱。\n乍晴：刚晴，初晴。\n风道四塞：四面的风道都堵塞了。\n薪爨（cuàn）：烧柴做饭。\n炎虐：炎热的暴虐。\n仓腐寄顿：仓库里储存的米谷腐烂了。\n陈陈逼人：陈旧的粮食年年相加，霉烂的气味使人难以忍受。陈陈：陈陈相因，《史记·平准书》：“太仓之粟，陈陈相因。”\n骈肩杂遝（tà）：肩挨肩，拥挤杂乱的样子。\n腥臊：鱼肉发臭的气味，此指囚徒身上发出的酸臭气味。\n圊溷（qīng hún）：厕所。\n毁尸：毁坏的尸体。\n秽：肮脏。\n叠是数气：这些气加在一起。\n侵沴（lì）：恶气侵人。沴：恶气。\n鲜不为厉：很少有不生病的。厉：病。\n孱弱：虚弱。\n俯仰其间：生活在那里。\n于兹：至今。\n无恙：没有生病。\n是殆有养致然：这大概是因为会保养正气才达到这样的吧。殆：大概。有养：保有正气。语本《孟子·公孙丑》：“我善养吾浩然之气。”致然：使然，造成这样子。\n然尔亦安知所养何哉：然而又怎么知道所保养的内容是什么呢？\n孟子：名轲，战国时代的思想家，其弟子将孟子言行变成《孟子》一书，为儒家经典。\n浩然之气：纯正博大而又刚强之气。见《孟子·公孙丑》。\n吾何患焉：我还怕什么呢。中国古代的许多思想家都认为浩然正气对于人身有无所不能的巨大力量。\n杂然：纷繁，多样。\n“下则为河岳”两句：是说地上的山岳河流，天上的日月星辰，都是由正气形成的。\n“于人曰浩然”两句：赋予人的正气叫浩然之气，它充满天地之间。沛乎：旺盛的样子。苍冥：天地之间。\n皇路：国运，国家的局势。清夷：清平，太平。\n吐：表露。\n见：同“现”，表现，显露。\n垂丹青：见于画册，传之后世。垂：留存，流传。丹青：图画，古代帝王常把有功之臣的肖像和事迹叫画工画出来。\n太史：史官。简：古代用以写字的竹片。\n张良椎：《史记·留侯传》载，张良祖上五代人都做韩国的丞相，韩国被秦始皇灭掉后，他一心要替韩国报仇，找到一个大力士，持一百二十斤的大椎，在博浪沙（今河南省新乡县南）伏击出巡的秦始皇，未击中。后来张良辅佐刘邦建立汉朝，封留侯。\n苏武节：《汉书·李广苏建传》载，汉武帝时，苏武出使匈奴，匈奴人要他投降，他坚决拒绝，被流放到北海（今西伯利亚贝加尔湖）边牧羊。为了表示对祖国的忠诚，他一天到晚拿着从汉朝带去的符节，牧羊十九年，始终贤贞不屈，后来终于回到汉朝。\n严将军：《三国志·蜀志·张飞传》载，严颜在刘璋手下做将军，镇守巴郡，被张飞捉住，要他投降，他回答说：“我州但有断头将军，无降将军！”张飞见其威武不屈，把他释放了。\n嵇侍中：嵇绍，嵇康之子，晋惠帝时做侍中（官名）。《晋书·嵇绍传》载，晋惠帝永兴元年（304），皇室内乱，惠帝的侍卫都被打垮了，嵇绍用自己的身体遮住惠帝，被杀死，血溅到惠帝的衣服上。战争结束后，有人要洗去惠帝衣服上的血，惠帝说：“此嵇侍中血，勿去！”\n张睢阳：即唐朝的张巡。《旧唐书·张巡传》载，安禄山叛乱，张巡固守睢阳（今河南省商丘市），每次上阵督战，大声呼喊，牙齿都咬碎了。城破被俘，拒不投降，敌将问他：“闻君每战，皆目裂，嚼齿皆碎，何至此耶？”张巡回答说：“吾欲气吞逆贼，但力不遂耳。”敌将视其齿，存者不过三数。\n颜常山：即唐朝的颜杲卿，任常山太守。《新唐书·颜杲卿传》载，安禄山叛乱时，他起兵讨伐，后城破被俘，当面大骂安禄山，被钩断舌头，仍不屈，被杀死。\n辽东帽：东汉末年的管宁有高节，是在野的名士，避乱居辽东（今辽宁省辽阳市），一再拒绝朝廷的征召，他常戴一顶黑色帽子，安贫讲学，名闻于世。\n清操厉冰雪：是说管宁严格奉守清廉的节操，凛如冰雪。厉：严肃，严厉。\n出师表：诸葛亮出师伐魏之前，上表给蜀汉后主刘禅，表明白己为统一事业奋斗到底的决心。表文中有“鞠躬尽力，死而后已”的名言。\n鬼神泣壮烈：鬼神也被诸葛亮的壮烈精神感动得流泪。\n渡江楫：东晋爱国志士祖逖率兵北伐，渡长江时，敲着船桨发誓北定中原，后来终于收复黄河以南失地。楫：船桨。\n胡羯：古代对北方少数民族的称呼。过去史书上曾称匈奴、鲜卑、羯、氐、羌为五胡。这句是形容祖逖的豪壮气概。\n击贼笏：唐德宗时，朱泚谋反，召段秀实议事，段秀实不肯同流合污，以笏猛击朱泚的头，大骂：“狂贼，吾恨不斩汝万段，岂从汝反耶？”笏：古代大臣朝见皇帝时所持的手板。\n逆竖：叛乱的贼子，指朱眦。\n是气：这种“浩然之气”。磅礴：充塞。\n凛烈：庄严、令人敬畏的样子。\n“当其贯日月”两句：当正气激昂起来直冲日月的时候，个人的生死还有什么值得计较的。\n“地维赖以立”两句：是说地和天都依靠正气支撑着。地维：古代人认为地是方的，四角有四根支柱撑着。天柱：古代传说，昆仑山有铜柱，高人云天，称为天柱，又说天有人山为柱。\n三纲实系命：是说三纲实际系命于正气，即靠正气支撑着。\n道义为之根：道义以正气为根本。\n嗟：感叹词。遘：遭逢，遇到。阳九：即百六阳九，古人用以指灾难年头，此指国势的危亡。\n隶也实无力：是说我实在无力改变这种危亡的国势。隶：地位低的官吏，此为作者谦称。\n楚囚缨其冠：《左传·成公九年》载，春秋时被俘往晋国的楚国俘虏钟仪戴着一种楚国帽子，表示不忘祖国，被拘囚着，晋侯问是什么人，旁边人回答说是“楚囚”。这里作者是说，自己被拘囚着，把从江南戴来的帽子的带系紧，表示虽为囚徒仍不忘宋朝。\n传车：官办交通站的车辆。穷北：极远的北方。\n鼎镬甘如饴：身受鼎镬那样的酷刑，也感到像吃糖一样甜，表示不怕牺牲。鼎镬：大锅。古代一种酷刑，把人放在鼎镬里活活煮死。\n阴房阒鬼火：囚室阴暗寂静，只有鬼火出没。阴房：见不到阳光的居处，此指囚房。阒：幽暗、寂静。\n春院閟天黑：虽在春天里，院门关得紧紧的，照样是一片漆黑。閟（bì）：关闭。\n“牛骥同一皂”两句：牛和骏马同槽，鸡和凤凰共处，比喻贤愚不分，杰出的人和平庸的人都关在一起。骥：良马。皂：马槽。鸡栖：鸡窝。\n一朝蒙雾露：一旦受雾露风寒所侵。蒙：受。\n分作沟中瘠：料到自己一定成为沟中的枯骨。分：料，估量。沟中瘠：弃于沟中的枯骨。\n如此再寒暑：在这种环境里过了两年了。\n百沴自辟易：各种致病的恶气都自行退避了。这是说没有生病。\n沮洳场：低下阴湿的地方。\n缪（miù）巧：智谋，机巧。贼：害。\n顾此耿耿在：只因心中充满正气。顾：但，表示意思有转折的连接词。此：指正气。耿耿：光明貌。\n仰视浮云白：对富贵不屑一顾，视若浮云。\n曷：何，哪。极：尽头。\n哲人日以远：古代的圣贤一天比一天远了。哲人：贤明杰出的人物，指上面列举的古人。\n典型：榜样，模范。夙昔：从前，讨去。\n风檐展书读：在临风的廊檐下展开史册阅读。\n古道照颜色：古代传统的美德，闪耀在面前。', poem_appreciation = '这首诗歌中，首先是作者所列举的许多历史人物，既不仅是民族英雄，也不一定都是对历史对人民有过什么重大贡献的英雄人物。如“为嵇侍中血”诗句中的嵇绍，不过是由于皇室内讧，他为了保卫一个昏庸皇帝晋惠帝而牺牲了的一个封建社会的忠臣。至于管宁更不过是一位逃避现实，独善其身的隐士；虽然作者把他们都当做历史上英雄人物来歌颂，但其实是不可取的。\n\n　　其次，作者文天祥虽然是中国历史上一位不可多得的民族英雄，但是他的英勇牺牲的出发点很大程度是来自封建社会的忠君思想。他自幼就羡慕古代忠臣、义士的行为：在江西学宫看到一些忠臣画象，就慨然说：“设不俎豆其间，非丈夫也。“并且在临刑时还以学习古代圣贤，成仁取义，作为自己为国尽忠的信条。出此可见，他的思想基础，基本上是建立在忠君之上的。正因为他具有这种封建的忠君思想，才限制了他的视野，使他作品的积极内容，受到了限制。因而，在评价他的积极意义的同时，对于不与人民利益相符的思想是应该加以批判的。他在被捕之后能够坚持民族气节，不为威屈，不为利诱，终于为国牺牲，保持了崇高的民族气节，为祖国保持了“正气”，自然也应该肯定。但是作者文天祥的爱国思想，毕竟和无产阶级的爱国主义和国际主义的思想，还是有本质上的区别。\n\n　　最后，正因为作者文天祥受到了封建忠君思想的限制，因此在诗中也就很自然地流露出一些宣传儒家教义和封建伦理观念的东西，如“三纲实系命，道义为之根“等，都是封建教条，是不可取的。', poem_tags = '咏史怀古,爱国' WHERE poem_title = '正气歌' AND poem_author = '文天祥';
UPDATE edu_poem SET poem_translation = '世事炎凉，黄昏中下着雨，打落片片桃花，这凄凉的情景中人的心也不禁忧伤。晨风吹干了昨晚的泪痕，当我想把心事写下来的时候，却不能够办到，只能倚着斜栏，心底里向着远方的你呼唤；和自己低声轻轻的说话，希望你也能够听到。难、难、难。\n今时不同往日，咫尺天涯，我身染重病，就像秋千索。夜风刺骨，彻体生寒，听着远方的角声，心中再生一层寒意，夜尽了，我也很快就像这夜一样了吧? 怕人询问，我忍住泪水，在别人面前强颜欢笑。瞒、瞒、瞒。', poem_notes = '笺：写出。\n斜阑：指栏杆。\n病魂一句：描写精神忧惚，似飘荡不定的秋千索。\n阑珊：衰残，将尽。', poem_appreciation = '唐婉是我国历史上常被人们提起的美丽多情的才女之一。她与大诗人陆游喜结良缘，夫妇之间伉俪相得，琴瑟甚和。这实为人间美事。遗憾的是身为婆婆的陆游母亲对这位有才华的儿媳总是看不顺眼，硬要逼着陆游把他相亲相爱的她给休了。陆游对母亲的干预采取了敷衍的态度；把唐婉置于别馆，时时暗暗相会。不幸的是，陆母发现了这个秘密，并采取了断然措施，终于把这对有情人拆散了。有情人未成终生的眷属，唐婉后来改嫁同郡宗人赵士程，但内心仍思念陆游不已。在一次春游之中，恰巧与陆游相遇于沈园。唐婉征得赵士程同意后，派人给陆游送去了酒肴。陆游感念旧情，怅恨不已，写了著名的《钗头凤》词以致意。唐婉则以此词相答。\n\n　　词的上片交织着十分复杂的感情内容。“世情薄，人情恶”两句，抒写了对于在封建礼教支配下的世故人情的愤恨之情。“世情”所以“薄”，“人情”所以“恶”，皆因“情”受到封建礼教的腐蚀。《礼记·内则》云：“子甚宜其妻，父母不悦，出。”陆母就是根据这一条礼法，把一对好端端的恩爱夫妻拆散了。用“恶”、“薄”两字来抨击封建礼教的害人本质，极为准确有力，作者对于封建礼教的深恶痛绝之情，也借此两字得到了充分的宣泄。“雨送黄昏花易落”，采用象征的手法，暗喻自己备受摧残的悲惨处境。阴雨黄昏时的花，原是陆游词中爱用的意象。其《卜算子曾借以自况。唐婉把这一意象吸入己作，不仅有自悲自悼之意，而且还说明了她与陆游心心相印，息息相通。“晓风干，泪痕残”，写内心的痛苦，极为深切动人。被黄昏时分的雨水打湿的了花花草草，经晓风一吹，已经干了，而自己流淌了一夜的泪水，至天明时分，犹擦而未干，残痕仍在。这是多么的痛心啊！以雨水喻泪水，在古代诗词中不乏其例，但以晓风吹得干雨水来反衬手帕擦不干泪水，借以表达出内心的永无休止的悲痛，这无疑是唐婉的独创。“欲笺心事，独语斜阑”两句是说，她想把自己内心的别离相思之情用信笺写下来寄给对方，要不要这样做呢？她在倚栏沉思独语。“难、难、难！”均为独语之词。由此可见，她终于没有这样做。只因封建礼教的残酷不仁。这一叠声的“难”字，由千种愁恨，万种委屈合并而成，因此似简实繁，以少总多，既上承开篇两句而来，以表现出处此衰薄之世做人之难，做女人之更难；又开启下文，以表现出做一个被休以后再嫁的女人之尤其难。\n\n　　过片“人成各，今非昨，病魂常似秋千索”，这三句艺术概括力极强。“人成各”是就空间角度而言的。作者从陆游与自己两方面设想：自己在横遭离异之后固然感到孤独，而深深爱着自己的陆游不也感到形单影只吗？“今非昨”是就时间角度而言的。其间包含着多重不幸。从昨日的美满婚烟到今天的两地相思，从昨日的被迫离异到今天的被迫改嫁，这是多么不幸！但不幸的事儿还在继续：“病魂常似秋千索。”说“病魂”而不说“梦魂”，显然是经过考虑的。梦魂夜驰，积劳成疾，终于成了“病魂”。昨日方有梦魂，至今日却只剩“病魂”。这也是“今非昨”的不幸。更为不幸的是，改嫁以后，竟连悲哀和流泪的自由也丧失殆尽，只能在晚上暗自伤心。“角声寒，夜阑珊，怕人寻问，咽泪装欢”四句，具体倾诉出了这种苦境。“寒”字状角声之凄凉怨慕，“阑珊”状长夜之将尽。这是彻夜难眠的人方能感受得如此之真切。\n\n　　大凡长夜失眠，愈近天明，心情愈感烦躁，而此词中的女主人公不仅无暇烦躁，反而还要咽下泪水，强颜欢笑。其心境之苦痛可想而知。结句以三个“瞒”字作结，再次与开头相呼应。既然可恶的封建礼教不允许纯洁高尚的爱情存在，那就把它珍藏在心底吧！因此愈瞒，愈能见出她对陆游的一往情深和矢志不渝的忠诚。\n\n　　与陆游的原词比较而言，陆游把眼前景、见在事融为一体，又灌之以悔恨交加的心情，着力描绘出一幅凄怆酸楚的感情画面，故颇能以特有的声情见称于后世。而唐婉则不同，她的处境比陆游更悲惨。自古“愁思之声要妙”，而“穷苦之言易好也”（韩愈《荆潭唱和诗序》）。她只要把自己所遭受的愁苦真切地写出来，就是一首好词。因此，此词纯属自怨自泣、独言独语的感情倾诉，主要以缠绵执着的感情和悲惨的遭遇感动古今。两词所采用的艺术手段虽然不同，但都切合各自的性格、遭遇和身分。可谓各造其极，俱臻至境。合而读之，颇有珠联璧合、相映生辉之妙。\n\n　　世传唐婉的这首词，在宋人的记载中只有“世情薄，人情恶”两句，并说当时已“惜不得其全阕”（详陈鹄《耆旧续闻》卷十）。此词最早见于明代卓人月所编《古今词统》卷十及清代沈辰垣奉敕编之《历代诗余》卷一一八所引夸娥斋主人说。由于时代略晚，故俞平伯怀疑这是后人依据残存的两句补写而成。', poem_tags = '宋词三百首,宋词精选,爱情,相思' WHERE poem_title = '钗头凤·世情薄' AND poem_author = '唐婉';
UPDATE edu_poem SET poem_translation = '山与天相接的地方缭绕着阵阵云烟，从竹林的缝隙里看洒落下余晖的夕阳。\n鸟儿欢快地向房檐上飞去，洁白的云儿竟然从窗户里轻轻地飘了出来。', poem_notes = '山际：山边；山与天相接的地方。\n烟：指山里面的雾气。\n竹中：竹林丛中。\n窥（kuī）：从缝隙中看。\n檐（yán）：房檐。\n这句是说山上的房屋地势很高，所以云从窗户里面穿进穿出。', poem_appreciation = '这首小诗经单纯白描的手法，展现出了一片山村的景象，俨然是一幅绝妙的写生画。用以形成一种特殊的环境，给人以新鲜的感觉，用的就是这种格调。\n\n　　诗歌描写的是诗人住在山中的有趣生活：山峰环绕，竹木茂盛，鸟在人家的房檐上飞，云彩从窗里飘出来。作者的幽居荡尽了人间的尘滓，随意而传神地表达了诗人惬意闲适的心情。全诗不过短短四句，一句一景，然句句不离“山中”的主题。烟岚弥漫着山谷，在山峰间飘来荡去，这正是幽静深邃的山中所常见的现象。落日西沉，只能在竹林的间隙中窥见其脉脉的斜晖，由此可见竹林的茂密青葱，山间的幽趣在首两句中已曲曲传出。屋檐上的飞鸟来来往往，白云穿窗而过，都说明诗人所居之处地势非常高，而且在茂林修竹之中。\n\n　　开头两句说，但见阵阵烟雾从山与山的交接处飘来，又见太阳在竹丛后渐渐落下。“来”、“落”两字写出了动态。“见”、“窥”两字用得很恰当：烟来则举目可见；日落则是透过竹子间的空隙所见，所以用“窥”字。“见”和“窥”，都说明在景的背后分明有人，所写之景只是人所见之景，并不是纯客观的描绘。三、四句说，鸟儿向着屋檐上飞翔，白云从窗户里轻轻流出。这两句都使人想到山中屋宇所处地势的高峻。尤其是后一句：云本不可能生于屋内，但因屋宇处于白云缭绕之中，云气从屋后、屋侧飘过，所以看起来就像从窗中飞出。“檐上”和“窗里”就更明白地透出人的存在。而且在写景中已暗示了诗人的山居之乐，他的恬淡超然的心境也于此可见。\n\n　　诗写得十分精炼。四句写出四个各自独立的画面，如同电影镜头的连接那样，合起来使人感到高而深的山中是那么清幽，甚至冷寂。烟、日、鸟、云都在动，但给人的印象却是无限的静。由这一片寂静，又使人感到诗人心中是那么清静。他没有一点儿杂念，只是静静地观赏着这一切。如果细细吟味，还可感到三、四句隐隐流露出诗人的几分新奇感。高飞的鸟与屋檐齐高，白云由窗间流出，这种景象在平地上见不到，因而使诗人感到有趣。\n\n　　四句是两副对子。前两句“见”、“窥”的主体是诗人，后两句的主体则是“鸟”和“云”。前两句的节奏是二、一、二，后两旬是二、二、一。这样，全诗虽然篇幅短小，内容单纯，却因旬式的不同而有所变化，以至于不显得单调了。\n\n　　此诗写作极有章法，动静结合。前两句形成大的环境氛围和背景；后两句点染出具体生动的景物，造成巨细相衬的艺术效果。同时，景物动静结合，构成山居特有的景物环境氛围。诗人又运用景中有人、景中含情、情景交融的手法来观察写出景物，寄托自己的情志于景物环境之中，体现了山居的清静超脱，远离尘嚣，表达了诗人安贫乐道的思想，也表达了诗人对大自然的热爱之情。', poem_tags = '古诗三百首,初中古诗,山村,写景,生活' WHERE poem_title = '山中杂诗' AND poem_author = '吴均';
UPDATE edu_poem SET poem_translation = '上天呀！我渴望与你相知相惜，长存此心永不褪减。除非巍巍群山消逝不见，除非滔滔江水干涸枯竭。除非凛凛寒冬雷声翻滚，除非炎炎酷暑白雪纷飞，除非天地相交聚合连接，直到这样的事情全都发生时，我才敢将对你的情意抛弃决绝！', poem_notes = '上邪（yé）！：天啊！。上，指天。邪，语气助词，表示感叹。 \n相知：相爱。\n命：古与“令”字通，使。衰（cuī）：衰减、断绝。这两句是说，我愿与你相爱，让我们的爱情永不衰绝。 \n陵(líng)：山峰、山头。 \n震震：形容雷声。 \n雨（yù）雪：降雪。雨，名词活用作动词。 \n天地合：天与地合二为一。 \n乃敢：才敢,“敢”字是委婉的用语。', poem_appreciation = '“上邪！我欲与君相知，长命无绝衰。”\n\n　　“上邪”犹言“天哪” ，“相知”即相亲相爱。此句说：“天哪！我要和君相爱，让我们的感情永久不破裂，不衰减。”为了证实她的矢志不褕，她接连 举五种自然界的不可能出现的变异，“山无陵，江水为竭，冬雷震震，夏雨雪，天地合。”意思是：要想背叛我们的誓言，除非出现山平了，江水干了，冬日里雷雨阵阵，夏天里大雪纷纷，天与地合而为一！。女主人公充分发挥她的想象力，一件比一件想得离奇，一桩比一桩令人难以思议。到“天地合”时，她的想象已经失去控制，漫无边际地想到人类赖以生存的一切环境都不复存在了。这种缺乏理智、夸张怪诞的奇想，是这位痴情女子表示爱情的特殊形式。而这些根本不可能实现的自然现象都被抒情女主人公当作“与君绝”的条件，无异于说“与君绝”是绝对不可能的。结果呢？只有自己和“君”永远地相爱下去。\n\n　　全诗写情不加点缀铺排。“上邪”三句，笔势突兀，气势不凡，指天发誓，直吐真言，既见情之炽烈，又透出压抑已久的郁愤。“长命无绝衰”五字，铿锵有力，于坚定之中充满忠贞之意。一个“欲” 字，把不堪礼教束缚，追求幸福生活的反抗女性性格表现的淋漓尽致。此三句虽未进行形象刻画，但一个情真志坚，忠贞刚烈的女子形象已清晰地站在读者面前。\n\n　　清代王先谦说：“五者皆必无之事，则我之不能绝君明矣。”这古今中外无与伦比的表达爱情的方式，可以说是绝唱之作。诗中女主人公以誓言的形式剖白内心，以不可能实现的自然现象反证自己对爱情的忠贞，确实具有一种强烈的主观色彩。诗短情长，撼人心魄。正如胡应麟所说：“上邪言情，短章中神品！”\n\n　　清代张玉谷《古诗赏析》卷五评此诗说：“首三，正说，意言已尽，后五，反面竭力申说。如此，然后敢绝，是终不可绝也。迭用五事，两就地维说，两就天时说，直说到天地混合，一气赶落，不见堆垛，局奇笔横。”可谓句句在理。\n\n　　从艺术上看，《上邪》的抒情极富浪漫主义色彩，其间的爱情欲火犹如岩浆喷发不可遏制，气势雄放，激情逼人。读《上邪》，仿佛可以透过明快的诗句，倾听到女子急促的呼吸之声。《上邪》是一首用热血乃至生命铸就的爱情篇章，其语言句式短长错杂，随情而布。音节短促缓急，字句跌宕起伏。\n\n　　《上邪》对后世的影响很大。敦煌曲子词中的《菩萨蛮》在思想内容和艺术表现手法上明显地受到它的启发：“枕前发尽千般愿,要休且待青山烂。水面上秤锤浮,直待黄河彻底枯。白日参辰现,北斗回南面,休即未能休,且待三更见日头。”不仅对坚贞专一的爱情幸福的追求是如出一辙的，并且连续用多种不可能来说明一种不可能的艺术构思也是完全相同的。', poem_tags = '古诗三百首,乐府,爱情,民歌' WHERE poem_title = '上邪' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '凤凰台上曾经有凤凰来悠游，凤去台空只有江水依旧东流。\n吴宫鲜花芳草埋着荒凉小径，晋代多少王族已成荒冢古丘。\n三山云雾中隐现如落青天外，江水被白鹭洲分成两条河流。\n总有奸臣当道犹如浮云遮日，长安望不见心中郁闷长怀愁。', poem_notes = '凤凰台：在金陵凤凰山上。\n江：长江。\n吴宫：三国时孙吴曾于金陵建都筑宫。\n晋代：指东晋，南渡后也建都于金陵。衣冠：指的是东晋文学家郭璞的衣冠冢。现今仍在南京玄武湖公园内。一说指当时豪门世族。衣冠，士大夫的穿戴，借指士大夫、官绅。成古丘：晋明帝当年为郭璞修建的衣冠冢豪华一时，然而到了唐朝诗人来看的时候，已经成为一个丘壑了。现今这里被称为郭璞墩，位于南京玄武湖公园内\n三山：山名。今三山街为其旧址，明初朱元璋筑城时，将城南的三座无名小山也围在了城中。这三座山正好挡住了从城北通向南门──聚宝门的去路。恰逢当时正在城东燕雀湖修筑宫城，于是将这三座山填进了燕雀湖。三山挖平后，在山基修了一条街道，取名为三山街。半落青天外：形容极远，看不大清楚。\n二水：一作“一水”。指秦淮河流经南京后，西入长江，被横截其间的白鹭洲分为二支。白鹭洲：白鹭洲：古代长江中的沙洲，洲上多集白鹭，故名。今已与陆地相连，位于今南京市江东门外。\n浮云蔽日：比喻谗臣当道障蔽贤良。浮云：比喻奸邪小人。日：一语双关，因为古代把太阳看作是帝王的象征。\n长安：这里用京城指代朝廷和皇帝。', poem_appreciation = '《登金陵凤凰台》是唐代的律诗中脍炙人口的杰作。开头两句写凤凰台的传说，十四字中连用了三个凤字，却不觉得重复，音节流转明快，极其优美。“凤凰台”在金陵凤凰山上，相传南朝刘宋永嘉年间有凤凰集于此山，乃筑台，山和台也由此得名。在封建时代，凤凰是一种祥瑞。当年凤凰来游象征着王朝的兴盛；而“如今”凤去台空，就连六朝的繁华也一去不复返了，只有长江的水仍然不停地流着，大自然才是永恒的存在。 　三四句就“凤去台空”这一层意思进一步发挥。三国时的吴和后来的东晋都建都于金陵。诗人感慨万分地说，吴国昔日繁华的宫廷已经荒芜，东晋的一代风流人物也早已进入坟墓。那一时的烜赫，在历史上也没有留下了什么有价值的东西。\n\n　　诗人没有让自己的感情沉浸在对历史的凭吊之中，他把目光又投向大自然，投向那不尽的江水：“三山半落青天外，二水中分白鹭洲。”“三山”在金陵西南长江边上，三峰并列，南北相连。据陆游的《入蜀记》载：“三山自石头及凤凰台望之，杳杳有无中耳，及过其下，则距金陵才五十余里。”陆游所说的“杳杳有无中”正好注释“半落青天外”。李白把三山半隐半现、若隐若现的景象写得恰到好处。“白鹭洲”，在金陵西长江中，把长江分割成两道，所以说“二水中分白鹭洲”。这两句诗气象壮丽，对仗工整，是难得的佳句。\n\n　　李白毕竟是关心现实的，他想看得更远些，从六朝的帝都金陵看到唐的都城长安。但是，“总为浮云能蔽日，长安不见使人愁。”这两句诗寄寓着深意。长安是朝廷的所在，日是帝王的象征。陆贾《新语·慎微篇》曰：“邪臣之蔽贤，犹浮云之障日月也。”李白这两句诗暗示皇帝被奸邪包围，而自己报国无门，他的心情是十分沉痛的。“不见长安”暗点诗题的“登”字，触境生愁，意寓言外，饶有余味。相传李白很欣赏崔颢《黄鹤楼》诗，欲拟之较胜负，乃作《登金陵凤凰台》诗。《苕溪渔隐丛话》、《唐诗纪事》都有类似的记载，或许可信。该诗与崔诗工力悉敌，正如方回《瀛奎律髓》所说：“格律气势，未易甲乙。”在用韵上，二诗都是意到其间，天然成韵。语言也流畅自然，不事雕饰，潇洒清丽。作为登临吊古之作，李诗更有自己的特点，它写出了自己独特的感受，把历史的典故，眼前的景物和诗人自己的感受，交织在一起，抒发了忧国伤时的怀抱，意旨尤为深远。\n\n　　李白是天才诗人，并且是属于那种充满创造天才的大诗人。然而，惟独李白临黄鹤楼时，没能尽情尽意，“驰志”千里。原因也很简单，所谓“眼前有景道不得，崔颢题诗在上头”。因而，“谪仙诗人”难受、不甘心，要与崔颢一比高低；于是他“至金陵，乃作凤凰台诗以拟之”，直到写出可与崔颢的《黄鹤楼》等量齐观的《登金陵凤凰台》时，才肯罢休。 这虽然是传言，但也挺恰切李白性格。《登金陵凤凰台》博得了“与崔颢黄鹤楼相似，格律气势未易甲乙”的赞扬。其实，李白的《登金陵凤凰台》，崔颢的《黄鹤楼》，它们同为登临怀古的双璧。\n\n　　李白《登金陵凤凰台》的艺术特点，首先在于其中所回荡着的那种充沛、浑厚之气。气原本是一个哲学上的概念，从先秦时代起就被广泛运用。随着魏晋时期的曹丕以气论文，气也就被当做一个重要的内容而在许多的艺术门类里加以运用。虽然，论者对气的理解、认识不完全相同，但对所含蕴的思想性情、人格精神与艺术情调，又都一致认同。李白《登金陵凤凰台》中明显地充溢着一股浑厚博大之气，它使李白观古阅今，统揽四海于一瞬之间，且超然物外，挥洒自如。浑厚博大之气使李白渊深的思想，高妙的见解，阔大的心胸，成为编织巨大艺术境界的核心与精神内含。就像透过“三山半落青天外，二水中分白鹭洲”的巨大立体时空，可以感受到历史的脉搏跳动与诗人的呼吸一样，通过李白的举重若轻，从容自在，以浩然雄大之气充塞整个诗歌境界的努力，也能更进一步感受到他整个诗歌以气夺人的艺术特点。 李白此诗的艺术特点，又在于对时空观念的完美表达。这既体现在对历史与自然的认识上，也体现在他构造时空艺术境界的表达方法上。李白强调的自然永恒不朽，一方面是宣传他的以自然为中心的“物我为一”的世界观，另一方面也是为了揭露历史上的统治神话。因为从古而来，几乎所有的统治者他们都宣扬自己的世代永存与精神不灭，并且还把这样一种模式灌输到人们的意识形态当中，使人深信不疑。但是，李白则对此不以为然。他认为即或是极为强有力的统治者，就像秦始皇，他可以“挥剑决浮云，诸侯尽西来。明断自天启，大略驾群才”，然而他终归也要“但见三泉下，金棺葬寒灰”（《古风·秦王扫六合》），烟消云散是不可避免的。所以，在李白看来，宇宙万物之中，能够获得永恒存在的只有自然。一切的繁华与骄奢淫逸都会烟消云散；如果说它们还存在，似乎也只是作为自然的反衬而存在的。另外，李白在表现自然力量的雄大与变化的时空观时，则选取了最为典型的事物，即“三山半落”之混茫与“二水中分”之辽阔，从而构造出阔大的境界，并且把历史的变迁，即时间的改变与地点的依旧，即空间的不改整体地表现出来，启发人们作更深的思考。\n\n　　李白《登金陵凤凰台》的艺术特点，还在于别致自然的遣词造句。由于诗以寓目山河为线索，于是追求情随景生，意象谐成也就显得特别重要。“凤凰”的高飞与“凤凰台”的“空”，洁净、疏朗，与诗人潇洒的气质和略带感伤的情怀相一致，且意到笔到，词义契合，起到了内外呼应的作用。另外，整首“登临”的内在精神，与“埋幽径”“成古丘”的冷落清凉，与“三山”“二水”的自然境界，与忧谗畏讥的“浮云”惆怅和不见“长安”无奈凄凉，都被恰切的语词链条紧紧地钩连在一起，从而当得起“古今题咏，惟谪仙为绝唱”的赞誉。', poem_tags = '唐诗三百首,高中古诗,咏史怀古' WHERE poem_title = '登金陵凤凰台' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '陈胜，是阳城人，字涉。吴广，是阳夏人，字叔。陈胜年轻时，曾同别人一起被雇佣给人耕地，（一天他）停止耕作走到田埂高地上休息，因失望而叹息了许久，说：“如果有谁富贵了，不要忘记大家呀。”一起耕作的同伴笑着回答说：“你一个受雇耕作的人，哪来的富贵呢？”陈涉长叹一声说：“唉，燕雀怎么能知道鸿鹄的志向呢？”\n\n　　秦二世元年七月，朝廷征发贫民调派去驻守渔阳，驻扎在大泽乡。陈胜吴广都被编入谪戍的队伍里面，担任戍守队伍的小头目。恰巧遇到天下大雨，道路不通，估计已经误期。误了期限，按（秦朝的）法律都应当斩首。陈胜吴广于是商量说：“即使现在逃跑（被抓回来）也是死，发动起义也是死，同样是死，为国事而死，可以么？”陈胜说：“天下百姓受秦朝统治逼迫已经很久了。我听说秦二世是始皇帝的小儿子，不应立为皇帝，应立的是公子扶苏。扶苏因为屡次劝谏的缘故，皇上派（他）在外面带兵。现在有人听说他没什么罪，秦二世却杀了他。老百姓大都听说他很贤明，而不知道他死了。项燕是楚国的将领，曾多次立下战功，又爱护士兵，楚国人都很爱戴他。有人认为他死了，有人认为他逃跑了。现在如果把我们的人假称是公子扶苏和项燕的队伍，号召天下百姓反秦，应当会有很多响应的人。”吴广认为他讲得对。于是二人就去占卜（来预测吉凶）。占卜的人了解了他们的意图，就说：“你们的大事都能成功，可以建立功业。然而你们把事情向鬼神卜问过吗？”陈胜吴广很高兴，考虑卜鬼的事情，说：“这是教我们利用鬼神来威服众人罢了。”于是就用丹砂在绸子上写上“陈胜王”（三个字），放在别人所捕的鱼的肚子里。士兵们买鱼回来烹食，发现鱼肚子里面的帛书，本来已经对这事感到奇怪了。陈胜又暗地里派吴广到驻地旁边丛林里的神庙中，在夜间提着灯笼，作狐狸嗥叫的凄厉的声音大喊：“大楚将兴，陈胜为王。”士兵们整夜惊恐不安。第二天，士兵们中间议论纷纷，只是指指点点，互相以目示意看着陈胜。\n\n　　吴广向来爱护士兵，士兵大多愿意听（他）差遣，（一天）押送戍卒的将尉喝醉了，吴广故意多次说想要逃跑，使将尉恼怒，让他侮辱自己，以便激怒那些士兵们。将尉果真用竹板打吴广。将尉拔剑出鞘想杀吴广，吴广跳起来，夺过利剑杀了将尉。陈胜帮助他，一起杀了两个将尉。（于是陈胜）召集并号令部属的人说：“你们诸位遇上大雨，都已误了期限，误期是要杀头的。假使仅能免于斩刑，可是去守卫边塞死掉的本来也会有十分之六七。况且壮士不死便罢了，要死就该成就伟大的名声啊，王侯将相难道有天生的贵种么？”部属的人都说：“愿意听从您的号令。”于是就假称是公子扶苏项燕的队伍，顺从人民的愿望。个个露出右臂（作为起义的标志），号称大楚。用土筑成高台并在台上宣誓，用（两个）将尉的头祭天。陈胜自立为将军，吴广任都尉。他们攻打大泽乡，收编大泽乡的义军之后攻打蕲县。攻下蕲以后，就派符离人葛婴率军巡行蕲县以东的地方，陈胜则攻打铚酂苦柘谯等地，都攻占下来。行军中沿路收纳兵员。等到到达陈县，已有战车六七百辆，骑兵一千多，士兵好几万。攻陈县时，那里的郡守和县令都不在，只有守丞带兵在城门洞里同起义军作战。守丞不能胜，被人杀死了，起义军才进城占领了陈县。过了几天，陈胜下令召集当地管教化的乡官和才能出众的乡绅一起来集会议事。乡官乡绅都说：“将军您亲身披着战甲，拿着锐利的武器，讨伐不义的暴君，消灭残暴的秦朝，重建楚国的江山，按照功劳应当称王。” 陈涉于是自立为王，定国号叫张楚。在这时，各郡县中吃尽秦朝官吏苦头的百姓，都起来惩罚当地郡县长官，杀死他们来响应陈胜（的号召）。\n\n　　于是就以吴广为代理王，督率各将领向西进攻荥阳（在今河南郑州市辖区内）。命令陈县人武臣张耳陈馀去攻占原来赵国的辖地，命令汝阴（今安徽阜阳）人邓宗攻占九江郡（今安徽寿县）。这时候，楚地几千人聚集在一起起义的，多得不计其数。\n\n　　葛婴到达东城（今安徽定远），立襄强为楚王。葛婴后来听说陈胜已自立为王，接着就杀了襄强，回来向陈胜报告。一到陈县，陈胜就杀了葛婴。陈胜命令魏人周市北上攻取原属魏国的地方。吴广包围了荥阳。李由任三川郡（今河南洛阳东白马寺东。李由，李斯之子）守，防守荥阳，吴广久攻不下。陈胜召集国内的豪杰商量对策，任命上蔡（在今河南驻马店市辖区内）人房君蔡赐做上柱国。\n\n　　周文（《史记集解》作周章），是陈县有名的贤人，曾经是项燕军中的占卜望日官，也在楚相春申君黄歇手下做过事，他自称熟习用兵，陈王就授给他将军印，带兵西去攻秦。他一路上边走边召集兵马，到达函谷关（河南灵宝）的时候，有战车千辆，士兵几十万人，到了戏亭（今陕西临潼东北，距咸阳四十千米）时，就驻扎了下来。秦王朝派少府章邯赦免了因犯罪而在骊山服役的人以及家奴所生的儿子，全部调集来攻打张楚的大军，把楚军全给打败了，周文失败之后，逃出了函谷关，在曹阳（今河南三门峡西南）驻留了两三个月。章邯又追来把他打败了，再逃到渑池（今河南三门峡）驻留了十几天。章邯又来追击，把他打得惨败。周文自杀，他的军队也就不能作战了。\n\n　　武臣到达邯郸，就自立为赵王，陈馀做大将军，张耳召骚任左右丞相。陈王知道后非常生气，就把武臣等人的家属逮捕囚禁了起来，打算杀死他们。上柱国蔡赐说：“秦王朝还没有灭亡就杀了赵王将相的家属，这等于是又生出一个与我们为敌的秦国来。不如就此封立他好些。”陈王于是就派遣使者前往赵国去祝贺，同时把武臣等人的家属迁移到宫中软禁起来，又封张耳的儿子张敖做成都君，催促赵国的军队速进军函谷关。赵王武臣的将相们商议说：“大王您在赵国称王，并不是楚国的本意。等到楚灭秦以后，一定会来攻打赵国。最好的办法莫过于不派兵向西进军，而派人向北攻取原来燕国的辖地以扩大我们自己的土地。赵国南面据黄河天险，北面又有燕代的广大土地，楚国即使战胜了秦国，也不敢来压制赵国。如果楚国不能战胜秦国，必定就会借重赵国。到时候赵国趁着秦国的疲敝，就可以得志于天下了。”赵王认为说得有道理，因而不向西出兵，而派了原上谷郡卒史韩广领兵北上去攻取燕地。\n\n　　燕国原来的贵族豪杰劝告韩广说：“楚国已经立了王，赵国也已立了王。燕国地方虽然小，过去也是个拥有万辆兵车的国家，希望将军您自立做燕王。”韩广回答说：“我的母亲还留在赵国，使不得。”燕人说：“赵国现在正西面担忧秦，南面担忧楚，他的力量不能来限制我们。况且以楚国的强大，都不敢杀害赵王将相的家属，赵国又怎敢杀害将军您的家属呢？”韩广认为他们说的有道理，于是就自立做了燕王。过了几个月，赵国派人护送燕王的母亲及其家属来到了燕国。\n\n　　在这个时候，到各地去攻城占地的将领，数不胜数。（《资治通鉴》：陈胜既派出周章，认为秦政府混乱，有轻视秦政府的意思，不再设立防备。博士孔鲋劝谏说：“臣听说兵法：‘不恃仗敌人不来进攻，而恃仗我们不怕进攻。’今天大王只恃仗敌人不来进攻，而不恃仗自己的防备，一旦兵败，后悔都来不及。”陈胜说：“我的军事行动，先生不必辛苦担心！”）周市北上攻城掠地到达了狄县（今山东高青东南），狄县人田儋杀死了狄县县令，自立为齐王，凭借齐地的力量来反击周市。周市的军队溃散了，退回到了魏地，打算立魏王的后代宁陵君咎做魏王。其时咎在陈王那里，不能回到魏地去。魏地平定以后，大家想共同拥立周市做魏王，周市不肯接受。使者先后五次往返于陈王与周市之间，陈王乃答应立宁陵君咎做魏王，遣送他回到魏国去。周市最后做了魏国的相。\n\n　　将军田臧等人一起谋划说：“周文的军队已经溃散，秦国的军队早晚就要到来，我们包围荥阳城久攻不下，如果秦国的军队到来，一定会被打得大败。不如留下少量的部队，足以守住荥阳就可以了，把其余精锐的军队全部拿来迎击秦军。现在代理王吴广骄横，又不懂用兵权谋，这样的人无法和他商量议事，不杀了他，我们的计划恐怕会被搞坏。”于是他们就假冒陈王的命令杀掉了吴广，把吴广的头献给了陈王。陈王就派使者赐给田臧楚令尹的大印，任命他做上将军。田臧就派部将李归等人驻守荥阳城，自己带了精锐的部队西进到敖仓迎战秦军。双方交战时，田臧战死，军队溃散。章邯领兵趁机到荥阳城下来攻打李归这些人，打败了他们，李归等人战死。\n\n　　阳城人邓说领兵驻扎在郏城（原文作郯城，据《史记索隐》《史记正义》改。今河南郏县），被章邯部将所带的一支部队击败，邓说率军溃逃到陈县。铚人伍徐率兵驻扎在许县（今河南许昌东），也被章邯的军队击溃了他。伍徐的军队都溃散逃到了陈县。陈王杀了邓说。\n\n　　陈胜刚刚自为王时，陵县（今江苏泗阳）人秦嘉铚县人董緤符离（今安徽宿州东北）人朱鸡石取虑（今江苏睢宁西南）人郑布徐县（今江苏省泗洪东南）人丁疾等都单独起兵反秦，他们领兵把东海郡守名叫庆的围困在郯城（东海郡郡治，在今山东临沂市辖区内）。陈王听说后，就派武平君名叫畔的做将军，督率郯城下的各路军队。秦嘉拒不接受这个命令，自立为大司马，讨厌隶属于武平君畔。便告诉他的军吏说：“武平君年轻，不懂得军事，不要听他的！”接着就假托陈王的命令杀死了武平畔。\n\n　　章邯打败伍徐以后，接着进攻陈县，陈王的上柱国房君蔡赐战死了。章邯又领兵进攻驻守在陈县西面的张贺部队。陈王亲自出来督战，结果楚军还是战败，张贺阵亡。\n\n　　十二月，陈王退到了汝阴（今安徽阜阳），在回到下城父（今安徽涡阳）时，他的车夫庄贾杀了他投降秦军。陈胜死后安葬在砀县（今河南永城东北），谥号叫隐王。\n\n　　陈王从前的侍臣吕臣将军组织了一支青巾裹头的“苍头军”，从新阳（今安徽界首北）起兵攻打陈县，攻克后，杀死了庄贾，又以陈县为楚都。\n\n　　当初，陈王刚到陈县的时候，曾命令铚县人宋留领兵去平定南阳（今河南省地级市），再进兵武关（今陕西丹凤东）。宋留攻占了南阳之后，传来了陈王被杀的消息，于是南阳又被秦军夺了回去。宋留不能进入武关，就往东到了新蔡（今河南驻马店市辖区内），不料又遇上了秦军，宋留带着部队投降了秦军。秦军押解宋留到了咸阳，将他五马分尸示众。\n\n　　秦嘉等人听说陈王的军队已经兵败逃走了，就立景驹做了楚王，率兵到了方与（今山东鱼台西），准备在定陶（今山东菏泽市辖区内）附近袭击秦军。于是派公孙庆出使齐国去会见齐王田儋，想联合他一同进兵。齐王说：“听说陈王战败了，至今生死不明，楚国怎么能不来向我请示就自立为王呢？”公孙庆说：“齐国不请示楚国而立王，楚国为什么要向齐国请示才能立王呢？何况楚是首先起义反秦的，理当号令天下。”田儋杀死了公孙庆。\n\n　　秦的左右校尉率领部队再次进攻陈县，并占领了它。将军吕臣失败逃跑后，重新集结兵马。并与当年在鄱阳为盗后被封为当阳君的黥布所率领的军队联合起来，又攻击秦左右校尉的军队，在青波把他们打败了，再度以陈县为楚都。这时正好项梁立楚怀王的孙子名叫心的做了楚王。\n\n　　陈胜称王总共六个月的时间。当了王之后，以陈县为国都。从前一位曾经与他一起雇佣给人家耕田的伙计听说他做了王，来到了陈县，敲着宫门说：“我要见陈涉。”守宫门的长官要把他捆绑起来。经他反复解说，才放开他，但仍然不肯为他通报。等陈王出门时，他拦路呼喊陈涉的名字。陈王听到了，才召见了他，与他同乘一辆车子回宫。走进宫殿，看见殿堂房屋帷幕帐帘之后，客人说：“夥颐！陈涉大王的宫殿高大深邃啊！”楚地人把“多”叫做“夥”，所以天下流传“夥涉为王”的俗语，就是从陈涉开始的。这客人在宫中出出进进越来越随便放肆，常常跟人讲陈涉从前的一些旧事。有人就对陈王说：“您的客人愚昧无知，专门胡说八道，有损于您的威严。”陈王就把来客杀死了。从此之后，陈王的故旧知交都纷纷自动离去，没有再亲近陈王的人了。（《史记索隐》：陈胜当了国王，岳父和妻兄都前去投靠。陈胜以普通宾客的礼节对待他们。岳父愤怒地说：“依仗强势怠慢长者，不能长久！”于是不辞而别。）陈王任命朱房做中正，胡武做司过，专门督察群臣的过失。将领们攻占了地方回到陈县来，命令稍不服从，就抓起来治罪，以苛刻地寻求群臣的过失作为对陈王的忠心。凡是他俩不喜欢的人，一旦有错，不交给负责司法的官吏去审理，就擅自予以惩治。陈王却很信任他们。将领们因为这些缘故就不再亲近依附他了。这就是陈王所以失败的原因。\n\n　　陈胜虽然已经死了，他所封立派遣的侯王将相终于灭掉了秦王朝，这是由于陈涉首先起义反秦的结果。汉高祖时，在砀县安置了三十户人家为陈涉看守坟墓，到汉武帝时仍按时杀牲祭祀他。（《汉书》：王莽战败，才断绝。）\n\n　　褚先生（褚少孙）说：地形险阻，是便于用来固守的；武器装备和法制规章，是便于统治国家的。但这些还不是最可靠的。先王以仁义道德作为治国的根本，而把巩固边塞制定法律条文看成枝叶，难道不是这样吗？我曾经听说贾谊的文章说：\n\n　　“秦孝公占据崤山和函谷的险固地势，拥有整个雍州地区（今陕西甘肃一带），君臣牢固把守，随时窥视着周王朝的政权，大有席卷天下，包举宇内，囊括四海的劲头儿，并吞八方极远之地的心气儿。就在这个时候，商鞅辅佐秦孝公，对内建立法令制度，致力于耕种纺织，整治攻守的武器，对外用连横的策略使诸侯们互相争斗。于是秦国像两手相合那样容易毫不费力地取得了黄河以西的大片土地。\n\n　　秦孝公死后，秦惠文王武王昭襄王承接了秦孝公的治国事业，遵循着先人留下来的策略，向南面夺取了汉中，向西南夺取了巴蜀，向东面割得了肥沃的土地，向北面夺得了冲要险阻的郡邑。诸侯们因此而恐惧惊慌，相会结盟商量对策来削弱秦国。他们不吝惜珍贵的财宝和富饶的土地，用来招纳天下的人才。采取合纵策略缔结盟约，互相支援，为一体。在这个时候，齐国有孟尝君，赵国有平原君，楚国有春申君，魏国有信陵君：这四位公子，都英明智慧而忠诚信义，宽宏厚道而爱惜人才，尊重贤者而器重士人。他们互相约定实行合纵联合抗秦，破坏秦国的连横策略，联合韩魏燕楚齐赵宋卫中山等国的有关人士。于是六国的人才，有宁越徐尚苏秦杜赫这些人替他们策划；有齐明周最陈轸邵滑楼缓翟景苏厉乐毅这些人沟通他们的意见；有吴起孙膑带佗倪良王廖田忌廉颇赵奢这些人统率他们的军队。诸侯们曾经用相当于秦国十倍的土地，百万的大军，攻打函谷关而进击秦国。秦国开关迎敌，九国的军队反逃跑而不敢前进。秦国没有耗费一个箭头，而天下的诸侯却已经疲惫不堪了。于是合纵解散，盟约破坏，各自争相割地贿赂秦国。秦国有充余的力量来利用诸侯的弱点，追赶逃亡败走的敌人，杀得他们横尸百万，流的血把大盾牌都漂浮起来；秦国趁着有利的形势，方便的时机，分割土地山河，因而强国请求臣服，弱国前来朝拜称臣了。\n\n　　延续到秦孝文王庄襄王的时候，他们在位的时间短暂，国家没有什么事。\n\n　　到了秦始皇，他发扬六代传下来的功业，像驾车似的挥动长鞭来驾御各诸侯国，吞并了东周和西周两个小国，灭亡了六国诸侯，登上了皇帝的宝座而控制天下，手持刑杖来鞭笞天下的人民，声威震慑四海。向南方夺取了百越的土地，把它设为桂林郡（今广西百色东北）和象郡（今广西崇左）；百越的君长们，低着头，用绳子拴住自己的脖子来投降，把自己的性命交给秦王朝的下级官吏掌握。于是派蒙恬到北方去修筑万里长城，作为边疆上的屏障来防守，把匈奴向北驱赶了七百多里；匈奴人不敢到南边来牧马，兵士也不敢搭起弓箭来报仇。于是废除了先王的治国之道，焚烧了诸子百家的著作，以图使老百姓愚昧无知；他还毁坏各地的名城，杀戮豪杰，收集天下的武器集中到咸阳，熔化刀剑和箭头，铸成十二个金属人像，来削弱天下人民的反抗力量。然后依凭华山当作城墙，凭借黄河作为护城河，依据亿丈高的华山，临守着深险莫测的黄河，作为守卫的险要之地。良将拿着强弓，防守重要的地方，可靠的大臣带领精干的士兵，摆列着锋利的武器，严厉盘查过往的行人是谁。天下已经平定，秦始皇的心中，自以为关中的坚固，是千里金城，可以作为子子孙孙万世当皇帝的基业了。\n\n　　秦始皇死了以后，他的余威还震慑着远方。然而陈涉是一个用破瓮作窗户，用草绳拴门轴的穷苦人家的子弟，是耕田的人，是供人役使的人，是被征发戍守边境的人。他的才能比不上一般平常的人，既没有孔子墨子那样的贤明，也没有陶朱（范蠡）猗顿那样的富有，置身在戍卒的行列之中，兴起在乡野之间，带领着疲乏散乱的戍卒，统率着几百个人，转身攻打秦国，砍下木棍做武器，高举竹竿为旗帜，天下的人就像风云那样迅速汇集起来，像回响那样应声而起，挑着粮食，如影随形地跟着他。崤山函谷关以东的英雄豪杰一齐起来，就把秦王朝推翻了。\n\n　　再说，那秦王朝的天下并没有缩小削弱；雍州的土地，崤山函谷关的险要坚固，还像从前一样。陈涉的地位，并不比齐楚燕赵韩宋卫中山的国君尊贵；锄耙戟柄，并不比钩戟长矛锋利；被征发戍守边地的民众，并不比九国的军队强大；深谋远虑，行军与指挥作战的本领，也比不上先前六国的那些才智之士。但是成功失败完全不同，；功业完全相反，这是什么原因呢？假使拿崤山函谷关以东各国诸侯来跟陈涉量量长短，比比大小，比较一下他们的权威，衡量衡量他们的实力，那简直不能够同年而语，相提并论。然而秦国当初凭借很小的地方，发展为有万辆兵车的强国，进而控制了其它八州，使来与它地位相同的诸侯国都来向秦国朝拜称臣，已经有一百多年的历史了。然后把天地四方当作家，把崤山函谷关当作宫墙。可是陈涉一个人首倡起义，秦王朝的七代宗庙就被毁坏，连秦王子婴也死在别人手中，被天下的人所讥笑，这是什么原因呢？这是因为不施行仁政，而攻取天下和后来防守天下的形势是不同的啊。”', poem_notes = '世家，《史记》传记的一种，主要是为王侯将相所作的传记。陈胜虽出身雇农，但他首事反秦，功大，又曾建立“张楚”政权，故给予他重要的历史地位，列入“世家”。\n阳城：今河南登封东南。\n阳夏(jiǎ)：今河南太康县。\n尝与人佣耕：曾经同别人一道被雇佣耕地。佣，被雇佣。\n辍耕之垄上：停止耕作走到田埂高地上休息。之：动词，去往。\n怅恨久之：因失望而叹恨了很久。怅，失意，不痛快。\n若：代词，你，指陈胜。\n燕雀安知鸿鹄之志哉：燕雀怎么知道鸿鹄的志向呢！燕雀，麻雀，这里比喻见识短浅的人。鸿鹄，天鹅，这里比喻有远大抱负的人。\n二世元年：公元前年。秦始皇死后，他的小儿子胡亥继位，称为二世。\n发闾左谪戍渔阳：征发贫苦人民去驻守渔阳。闾左，指贫民，古时贫者居住闾左，富者居住闾右。谪：适戍，发配去守边。\n皆次当行：都被编入谪戍的队伍。当行，当在征发之列。\n屯长：戍守队伍的小头目。\n亡：逃跑；逃走。\n举大计：发动大事，指起义。下文的“举大名”意思与此相同。\n等：同样。\n死国：为国事而死。\n苦秦：苦于秦（的统治）。\n以数谏故：因为屡次劝谏的缘故。数，屡次。谏，古代下级对上级提意见或建议，劝诫。\n上使外将兵：皇上派（他）在外面带兵。上：臣下对皇帝的尊称，指秦始皇嬴政。\n项燕：战国末年楚国著名将领，项梁之父西楚霸王项羽的祖父，曾大败秦将李信。\n怜：爱戴。\n诚以吾众：如果把我们的人。诚：果真，表假设。\n唱：通“倡”，首发。\n宜多应者：应当（有）很多响应的人。宜：应当。\n足下：指对方，古人对于别人的敬称。\n卜之鬼乎：把事情向鬼神卜问一下吧！卜之鬼，就是“卜之于鬼”，“于”字省略。\n念鬼：考虑卜鬼的事。念，考虑思索。\n乃丹书帛曰“陈胜王”：于是（用）丹砂（在）绸子上写“陈胜王”（三个字）。丹，朱砂。这里是“用朱砂”的意思。书，写。王，称王。\n置人所罾鱼腹中：放在别人所捕的鱼的肚子里。罾（zēng）：鱼网。这里作动词，是“用鱼网捕”的意思。\n固以怪之矣：自然就诧怪这件事了。以，通“已”，已经。\n间令：暗使。间，私自，偷着。\n之次所旁丛祠中：往驻地旁边的丛林里的神庙中。次所：旅行或行军时临时驻扎的地方。丛祠，树木荫蔽的神庙。\n旦日：明天，第二天。\n往往语：到处谈论。\n指目：指指点点，互相以目示意。\n将尉：押送（戍卒）的军官。\n忿恚（fèn huì）尉：使尉愤怒。\n笞：用鞭杖或竹板打。\n剑挺：拔剑出鞘。\n召令徒属：召集并号令所属的人。\n公等：你们诸位。公，对对方的敬称。\n藉第令毋斩：即使能免于斩刑。“藉”“第”“令”都是“即使假若”的意思。\n十六七：十分之六七。\n王侯将相宁有种乎：王侯将相难道有天生的贵种吗？宁，难道。\n受命：听从（你的）号令。\n袒右：露出右臂（做为起义的标志）。\n：祭以尉首：用两（尉）的头祭天。\n蕲：今安徽宿州南。\n符离：今安徽宿州。\n徇：指率军巡行，使人降服。\n铚（zhì）酂（cuó）苦（hù）柘（zhè）谯（qiáo）：秦时地名，铚谯，在今安徽。酂苦柘，在今河南。\n行收兵：行军中沿路收纳兵源。\n比：等到。陈，秦时县名，今河南淮阳。\n守令皆不在：郡守县令都不在。秦时，陈县属于砀郡，是郡府县府所在地，所以有守有令。\n守丞：守城的当地行政助理官。\n谯门中：城门洞里。\n三老：封建社会里管教化的乡官。豪杰，指当地有声望的人。\n被（pī）坚执锐：披着铠甲，拿着兵器。比喻亲自投身战斗，冲锋陷阵。被，通“披”，穿。坚，指铁甲。锐，指武器。\n社稷：“社”是土地神，“稷”是谷神。后来社稷就用来做国家的代称。\n号为张楚：对外宣称要张大楚国，即复兴楚国之意。一说定国号为“张楚”。\n刑其长吏：惩罚当地的郡县长官。刑，惩罚。\n荥阳：位于今河南省，是古代的军事重镇。\n楚兵：指楚地的起义军。 为聚，结成一伙。聚，集合在一起。\n还报：回去向陈胜汇报。\n视日：占卜日子吉凶的官。\n春申君：战国时楚相黄歇的封号。\n关：指函谷关。\n郦山徒：指发配在骊山服劳役的人。郦，今作“骊”。奴产子生，家人奴婢所生的儿子。\n捕系：逮捕拘禁。\n柱国：指蔡赐。\n此生一秦也：这样做又制造出一个像秦一样的敌国来。\n王王：前一个“王”字是名词，指武臣，后一个“王”字是动词，称王的意思。\n计莫如毋西兵：最好的计策莫过于不向西方（指秦国）出兵。\n使使：前一个“使”字是动词，派遣；后一个“使”字是名词，使者。\n燕故贵人：过去燕国的贵族。\n居数月：过了几个月。\n五反：指往返了五次。反，同“返”。\n周章：即上文中的周文。\n旦暮至：早晚就要到。\n兵权：指用兵的计谋策略。\n矫王令：假传陈王的命令。矫，假托。\n敖仓：秦代在敖山上筑仓储粮，所以叫敖仓，也叫敖庾。故地在今河南郑州西北氓山上。\n郯：在今山东省郯城县西，当时章邯的军队并没有到达那里，不当在郯交战。“郯”当为“郏（jiá）”。郏，在今河南郏县，与邓说家乡阳城临近。\n皆特起：都各自起兵反秦。特，单独。\n御：驾车的人。\n谥：古人有地位的人死后，按其生平事迹给予的称号。隐：有功业未显使人哀伤之意。\n仓头军：以青巾裹头的军队。\n车裂：古代的一种酷刑，用五马分尸。徇，这里是示众的意思。\n首事：指首先起兵反秦。\n左右校：即左右校尉，次于将军的军官，这里指他们所率领的军队。\n鄱盗：黥布在陈胜起义前曾在鄱阳一带的长江中为盗，故称“鄱盗”。相收，指吕臣与黥布的军队互相联合。\n怀王孙心：楚怀王的孙子，名心。\n王：称王。凡，总共。\n王陈：即“王于陈”，在陈地做王。\n宫门令：守卫宫门的官。\n辩数：反复解说。\n夥颐：意思是“真多呀”。夥，多。颐，语气助词，相当于“呀”。\n沈沈：形容宫室高大深邃，富丽堂皇。\n夥涉为王：这是当时流传的口头语，意思是一朝得志就变得十分阔气。\n发舒：放肆，随便。\n颛：通“专”。妄言，胡说。\n令之不是者：命令他而不顺从的。\n系：拘捕。罪之，把他判罪。\n其所不善者：指与朱房胡武关系不好的人。\n下吏：交给执法官吏。\n血食：享受祭祀。古时祭祀要宰杀牲畜作祭品，所以叫“血食”。\n兵革刑法：指武器装备和法制规章。\n固塞文法：坚固关塞，文饰法律条文。\n贾生：指贾谊。以下文字引自贾谊的《过秦论》上篇。', poem_appreciation = '《陈涉世家》是秦末农民起义领袖陈胜、吴广的传记。文中真实、完整地记述了爆发这次农民大起义的原因、经过和结局，表现了陈涉在反对秦王朝暴政斗争的关键时刻所发挥的重要作用，以显示他洞察时局的能力和卓越的组织领导才干，从中反映了农民阶级的智慧、勇敢和大无畏的斗争精神。文章也比较生动地描写了陈涉和吴广的形象。陈涉出身雇农，胸怀大志，有政治远见，他要求人民从“苦秦”中解放出来；他聪明果断，具有组织群众、制定策略、指挥战争的卓越才干，是农民阶级的杰出领袖。吴广虽然刻画简略，但从他与谋起义、诱杀将尉等事迹中，也表现了非凡的机智勇敢和反抗精神。在他们身上，都充分地表现了中国古代劳动人民以不甘忍受黑暗统治而敢于斗争的英雄气概。文章也写到了起义军内部的不和及自相残杀，陈涉称王之后的贪图享受、信用奸邪、脱离群众，表明了农民阶级的局限性。作者善于把握历史事件的发展进程，又善于运用语言、动作、神态描写等多种技巧来塑造人物形象，从而生动真实地再现了这一场伟大斗争的图景。\n\n　　《陈涉世家》一文在写作上按事件的发展顺序记事。写起义过程，先写起义的原因和起义前的谋划，再写起义的爆发和发展，直至政权的建立，脉络非常清晰。在记述中，则采取了先因后果的写法。写起义的动机，则先写暴秦的严刑峻法；写起义的发生，则又先写将尉的残酷等等。都入情入理，有力地突出了起义的正义性。文中还通过典型细节的描写，对起义的过程、浩大的声势以及起义领袖的精神面貌，进行了较为充分的展现，从而给人留下了深刻的印象。\n\n　　此文生动地记述了从大泽乡起义到张楚政权建立这一段历史进程，再现了陈胜、吴广两位起义领袖的英雄本色。陈胜有很高的阶级觉悟，并且怀有“鸿鹄之志”。这表现在佣耕时与同伴的对话中，表现在并杀两尉之后面对徒属所作的讲演中，尤其是“王侯将相宁有种乎”的话语，是对封建世袭制度的有力否定和批判。正是由于他富有远见，他的话具有鼓动性，才能收到徒属皆日“敬受命”的效果。作为起义领袖，陈胜和吴广都能审时度势、机智果断，为起义作出周密的谋划和部署。“会天大雨，道不通，度已失期。失期，法皆斩”是陈涉等人起义的直接原因。面临必死处境时，陈胜和吴广当机立断，密谋起义，决心率众闯出一条生路来，说明他们对起义的时机把握得很好。二人密谋中，陈胜对时局作了精辟的分析，把握了“天下苦秦久矣”这一社会背景。在这种分析的基础上，决定打出公子扶苏和项燕的旗号——因为“百姓多闻其贤，未知其死也”，“项燕数有功，爱士卒，楚人怜之”，“或以为死，或以为亡”，提出这一口号，则“宜多应者”。他们在卜者启发下，精心策划丹书鱼腹和篝火狐鸣两件“灵异”事件，骗过了其他戍卒的耳目。他们合演的杀将尉的双簧戏，成功地点燃了起义的导火线，这些都能说明他们善于谋划。后文中的“诸郡县，苦秦吏者”照应上文“天下苦秦久矣”，“皆刑其长吏，杀之以应陈涉”与上文“宜多应者”相呼应，这两句话的前后照应说明了陈胜的分析完全正确，体现了他洞察时局的能力。也正是陈涉这种谋划、洞察的能力，才造成起义一呼百应，并迅速遍及全国局面。\n\n　　陈胜、吴广在密谋起义之时曾找人算卦，后来又在卜者暗示下演出了丹书和狐鸣两出骗局。这种为推翻一个政权而造舆论的骗术，在中国历史的改朝换代关头屡见不鲜。当广大群众畏天命的意识很浓厚的时候，举事者想要“威众”，以种种骗术把自己表现成受命于天的超人是最取巧、最见效的手法。然而，陈胜、吴广自己并不迷信天命，“王侯将相宁有种乎”才是他们的真实思想。作者司马迁更在记叙陈胜、吴广行卜时，特意点破“卜者知其指意”，既“知其指意”，则“足下事皆成，有功”云云，至于“卜之鬼乎”，分明是在参与密谋。《陈涉世家》在行文中使此类骗术昭然若揭，《高祖本纪》中对刘邦制造的斩蛇之类的神话也持保留态度，这都体现了司马迁进步的的历史观。\n\n　　两个将尉在大泽乡起义中并没有过失，他们和吴广的一场冲突是起义领袖预谋的，但最终仍不免一死。这是因为他们是秦王朝势力的代表人物，在残酷的阶级斗争面前，充当了起义军的对立面，故难逃成为牺牲品的命运。攻下蕲县这第一个县城后，陈胜和吴广及时派葛婴带领人马到蕲县以东开辟新战场，以便迅速打开局面，同时不失时机地立国称王，建立起农民政权。这些都说明他们在起义初期战略战术运用得当，成功地担当了领袖的责任。陈胜在战斗中披坚执锐、身先士卒，吴广“素爱人，士卒多为用者”，这些都是领袖人物不可或缺的素质，在陈胜、吴广身上明显地体现出来。\n\n　　上述人物性格特点是通过具体事件或细节的记叙表现出来的，不难看出，《史记》在为一个个历史人物立传时，不仅记录其生平大端，而且注意揭示人物的精神风貌，同时展示与人物活动相关的背景、环境，从而再现当时社会生活的真实画面，这正是《史记》文学性的主要体现。', poem_tags = '初中文言文,咏史,传记,叙事' WHERE poem_title = '陈涉世家' AND poem_author = '司马迁';
UPDATE edu_poem SET poem_translation = '烽火照耀京都长安，不平之气油然而生。\n辞别皇宫，将军手执兵符而去；围敌攻城，精锐骑兵勇猛异常。\n大雪纷飞，军旗黯然失色；狂风怒吼，夹杂咚咚战鼓。\n我宁愿做个低级军官为国冲锋陷阵，也胜过当个白面书生只会雕句寻章。', poem_notes = '从军行：为乐府《相和歌·平调曲》旧题，多写军旅生活。\n烽火：古代边防告急的烟火。西京：长安。\n牙璋：古代发兵所用之兵符，分为两块，相合处呈牙状，朝廷和主帅各执其半。指代奉命出征的将帅凤阙：阙名。汉建章宫的圆阙上有金凤，故以凤阙指皇宫。\n龙城：又称龙庭，在今蒙古国鄂尔浑河的东岸。汉时匈奴的要地。汉武帝派卫青出击匈奴，曾在此获胜。这里指塞外敌方据点。\n凋：原意指草木枯败凋零，此指失去了鲜艳的色彩。\n百夫长：一百个士兵的头目，泛指下级军官。', poem_appreciation = '这首诗借用乐府旧题“从军行”，描写一个读书士子从军边塞、参加战斗的全过程。仅仅四十个字，既揭示出人物的心理活动，又渲染了环境气氛，笔力极其雄劲。\n\n　　前两句写边报传来，激起了志士的爱国热情。诗人并不直接说明军情紧急，却说“烽火照西京”，通过“烽火”这一形象化的景物，把军情的紧急表现出来了。一个“照”字渲染了紧张气氛。“心中自不平”，是由烽火而引起的，国家兴亡，匹夫有责，他不愿再把青春年华消磨在笔砚之间。一个“自”字，表现了书生那种由衷的爱国激情，写出了人物的精神境界。首二句交待了整个事件展开的背景。第三句“牙璋辞凤阙”，描写军队辞京出师的情景。这里，诗人用“牙璋”、“凤阙”两词，显得典雅、稳重，既说明出征将士怀有崇高的使命，又显示出师场面的隆重和庄严。第四句“铁骑绕龙城”，说明唐军已经神速地到达前线，并把敌方城堡包围得水泄不通。“铁骑”、“龙城”相对，渲染出龙争虎斗的战争气氛。一个“绕”字，又形象地写出了唐军包围敌人的军事态势。五六两句开始写战斗，诗人却没有从正面着笔，而是通过景物描写进行烘托。“雪暗凋旗画，风多杂鼓声”，前句从人的视觉出发：大雪弥漫，遮天蔽日，使军旗上的彩画都显得黯然失色；后句从人的听觉出发：狂风呼啸，与雄壮的进军鼓声交织在一起。两句诗，有声有色，各臻其妙。诗人别具机抒，以象征军队的“旗”和“鼓”，表现出征将士冒雪同敌人搏斗的坚强无畏精神和在战鼓声激励下奋勇杀敌的悲壮激烈场面。诗的最后两句：“宁为百夫长，胜作一书生。”直接抒发从戎书生保边卫国的壮志豪情。艰苦激烈的战斗，更增添了他对这种不平凡的生活的热爱，他宁愿驰骋沙场，为保卫边疆而战，也不愿作置身书斋的书生。\n\n　　这首短诗，写出书生投笔从戎，出塞参战的全过程。能把如此丰富的内容，浓缩在有限的篇幅里，可见诗人的艺术功力。首先诗人抓住整个过程中最有代表性的片断，作了形象概括的描写，至于书生是怎样投笔从戎的，他又是怎样告别父老妻室的，一路上行军的情况怎样，诗人一概略去不写。其次，诗采取了跳跃式的结构，从一个典型场景跳到另一个典型场景，跳跃式地发展前进。如第三句刚写了辞京，第四句就已经包围了敌人，接着又展示了激烈战斗的场面。然而这种跳跃是十分自然的，每一个跨度之间又给人留下了丰富的想象余地。同时，这种跳跃式的结构，使诗歌具有明快的节奏，如山崖上飞流惊湍，给人一种一气直下、一往无前的气势，有力地突现出书生强烈的爱国激情和唐军将士气壮山河的精神面貌。', poem_tags = '初中古诗,边塞,战争,励志' WHERE poem_title = '从军行' AND poem_author = '杨炯';
UPDATE edu_poem SET poem_translation = '枣花纷纷落在衣襟上。村南村北响起车缫丝的声音，古老的柳树底下有一个穿牛衣的农民在叫卖黄瓜。\n路途遥远，酒意上心头，昏昏然只想小憩一番。艳阳高照，无奈口渴难忍，想随便去哪找点水喝。于是敲开一家村民的屋门，问：可否给碗茶？', poem_notes = '徐门：即徐州。\n谢雨：雨后谢神。\n簌簌：纷纷下落的样子，一作“蔌蔌”，音义皆同。\n缫车：纺车。缫，一作“缲”，把蚕茧浸在热水里，抽出蚕丝。\n牛衣：蓑衣之类。这里泛指用粗麻织成的衣服。《汉书.食货志》有“贫民常衣牛马之衣”的话。\n漫思茶：想随便去哪儿找点茶喝。漫，随意，一作“谩”。', poem_appreciation = '这首词是苏轼在徐州作官的时候写的。按照当时的迷信风俗，一个关心农事的地方官，天大旱，要向“龙王爷”求雨；下了雨，又要向“龙王爷”谢雨。这首词就是苏轼有一次途经农村去谢雨，记下的见闻之一。\n\n　　此词描述他乡间的见闻和感受。艺术上颇具匠心，词中从农村习见的典型事物入手，意趣盎然地表现了淳厚的乡村风味。清新朴实，明白如话，生动真切，栩栩传神，是此词的显著特色。此词上片写景，下片抒情。需要指出的是，这首词中所写的景，并不是一般情况下通过视觉形象构成的统一的画面，而是通过传入耳鼓的各种不同的音响在诗人意识的屏幕上折射出的一组联续不断的影象。\n\n　　“簌簌衣巾落枣花”从枣花落到衣巾上的声音开端，反映了一位关心人民生活的太守对雨后农村新景象的喜悦之情。作者在“谢雨道上”，经过长途跋涉，加之酒意未消，日高人困，不免有些倦意。突然，“簌簌”之声传来耳际，并好像有什么东西打在身上和头巾上。这时，他才意识到：这是枣花落在身上。枣花落在衣巾上的声音是轻微的，但在作者的耳里却是那么真切。接着，耳边又传来吱吱呀呀的声响，越往前走，这响声便越浓，从南，从北，从四面八方传来，不用看也不用问，这是作者熟悉的缫车的响声。“村南村北”概括“缫车”声，说明作者听得多么认真，多么细心，多么兴奋。从响声中，作者意识到，他已进入村中了。这时，突然一阵叫卖声传入耳鼓，定睛一看，原来是一位披着“牛衣”的农民坐在古老的柳树荫中，面前摆着一堆黄瓜。“牛衣古柳”，作者换一个角度来写他对蔬菜丰收的喜悦心情。三句话，三个画面，似乎东鳞西爪，毫无联系。可是用谢雨的路上这条线串起来，就让人感到这幅连环画具有很强的立体感。这一组画面，不仅色彩美，而且有音乐美。无论是簌簌的落花声，嗡嗡的缲车声，还是瓜农的叫卖声，都富有浓郁的生活气息，生动地展现出农村一派欣欣向荣的景象。\n\n　　上片写的是农村生产劳动的繁忙景象，下片转入写谢雨途中行路的艰辛，突出作者的感受和意识活动。“酒困路长惟欲睡”是对上片的补充。在结构上，这一句又是倒叙，它说明前三句之所以从听觉方面来写，主要是因为酒意未消，路途遥远，人体困乏，故而写下来的只不过是睡眼朦胧中听来的片断，并非是视觉构成的完整统一的画面。“日高人渴”两句，虽然写的是由于口渴而急于到农民家里觅水的意识活动，但同时也反映了作者不拘小节、随遇而安的性格特征。走了一村又一村，这时已是日高天热，人也走得口干舌燥，加上酒困，睡意也上来了，不由得想起以茶解渴，以茶提神。“试问”一词用得十分讲究，既写出了作者满怀希望想讨杯茶解渴的心情，又担心农忙季节，农家无人，自己不便贸然而入的心情。信笔写来，不事雕琢，但却栩栩如生，刻画出一位谦和平易近人的知州形象，将一位太守与普通农民的关系写得亲切自然。“敲门试问野人家”，词到这里就戛然而止了。词人敲门的结果怎样，喝到茶没有，农民是怎样招待他的，词中未作一个字的交代，留给读者去想像，更是余味无穷。这就是古典诗词中所讲究的“含不尽之意，见于言外”。\n\n　　《浣溪沙》词中“簌簌衣巾落枣花”一句，实为“枣花簌簌落衣巾”的倒文；杜甫《秋兴》一诗中有“香稻啄余鹦鹉粒，碧梧栖老凤凰枝”，原意为：鹦鹉啄余香稻粒，凤凰栖老碧梧枝。主宾倒置的同时，宾语“香稻粒”、“碧梧枝”还被拆开分属主宾位置。对于古典诗歌诗句的倒置，清人洪亮吉说：“诗家例用倒句法，方觉奇峭生动”。\n\n　　全词绘景逼真形象，栩栩如生，叙事清新淡雅，脉脉含情，为宋词词境的拓展作出了贡献。', poem_tags = '宋词三百首,初中古诗,乡村,生活,风俗' WHERE poem_title = '浣溪沙·簌簌衣巾落枣花' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '驾驭着白马向西北驰去，马上佩带着金色的马具。有人问他是谁家的孩子，边塞的好男儿游侠骑士。\n年纪轻轻就离别了家乡，到边塞显身手建立功勋。楛木箭和强弓从不离身，下苦功练就了一身武艺。\n拉开弓如满月左右射击，一箭箭中靶心不差毫厘。飞骑射裂了箭靶“月支”，转身又射碎箭靶“马蹄”。\n他灵巧敏捷赛过猿猴，又勇猛轻疾如同豹螭。听说国家边境军情紧急，侵略者一次又一次进犯内地。\n告急信从北方频频传来，游侠儿催战马跃上高堤。随大军平匈奴直捣敌巢，再回师扫鲜卑驱逐敌骑。\n上战场面对着刀山剑树，从不将安和危放在心里。连父母也不能孝顺服侍，更不能顾念那儿女妻子。\n名和姓既列上战士名册，早已经忘掉了个人私利。为国家解危难奋勇献身，看死亡就好像回归故里。', poem_notes = '白马篇：又名“游侠篇”，是曹植创作的乐府新题，属《杂曲歌·齐瑟行》，以开头二字名篇。\n金羁（jī）：金饰的马笼头。\n连翩（piān）：连续不断，原指鸟飞的样子，这里用来形容白马奔驰的俊逸形象。\n幽并：幽州和并州。在今河北、山西、陕西一带。\n去乡邑：离开家乡。\n扬声：扬名。垂：同“陲”，边境。\n宿昔：早晚。秉：执、持。\n楛（hù）矢：用楛木做成的箭。何：多么。参差（cēncī）：长短不齐的样子。\n控弦：开弓。的：箭靶。\n摧：毁坏。月支：箭靶的名称。左、右是互文见义。\n接：接射。飞猱（náo）：飞奔的猿猴。猱，猿的一种，行动轻捷，攀缘树木，上下如飞。\n散：射碎。马蹄：箭靶的名称。\n狡捷：灵活敏捷。\n勇剽（piāo）：勇敢剽悍。螭（chī）：传说中形状如龙的黄色猛兽。\n虏骑（jì）：指匈奴、鲜卑的骑兵。数（shuò）迁移：指经常进兵人侵。数，经常。\n羽檄（xí）：军事文书，插鸟羽以示紧急，必须迅速传递。\n厉马：扬鞭策马。\n长驱：向前奔驰不止。蹈：践踏。\n顾：看。陵：压制。鲜卑：中国东北方的少数民族，东汉末成为北方强族。\n弃身：舍身。\n怀：爱惜。\n籍：名册。\n中顾私：心里想着个人的私事。中，内心。\n捐躯：献身。赴：奔赴。', poem_appreciation = '这是羁旅怀乡之作。离家久远，目睹旅馆门外的渔船即加以艳羡。幽恨乡愁、委实凄绝。颈联“远梦归侵晓，家书到隔年”意思曲折多层，实乃千锤百炼的警句。\n\n　　首联起，直接破题，点明情境，羁旅思乡之情如怒涛排壑，劈空而来。可以想见，离家久远，独在异乡，没有知音，家书也要隔年才到，此时孤客对寒灯，浓厚深沉的思乡之情油然而生，必会陷入深深的忧郁之中。“凝情自悄然”是此时此地此情此景中抒情主人公神情态度的最好写照：静对寒灯，专注幽独，黯然伤神，将诗人的思念之情写到极致。\n\n　　颔联承，是首联“凝情自悄然”的具体化，诗人融情于景，寒夜孤灯陪伴孤客，思念故乡旧年往事，失群孤雁声声鸣叫，羁旅之人深愁难眠，细致地描绘出了一幅寒夜孤客思乡图景。“思”字和“警”字极富炼字功夫。灯不能思，却要寒夜愁思陈年旧事，物尤如此，人何以堪。由灯及人，显然用意在人不在物。“警”字也极富情味。旅人孤灯，长夜难眠，一声雁叫，引孤客嫠妇愁思惊梦，归思难收。\n\n　　首联与颔联极言乡关遥远，幽愁满怀。梦见自己回到家中，因路途遥远，梦醒时分天已大明，家书须隔年才能寄到旅馆，可见离家之远，表达出对家乡深沉的思念。\n\n　　颈联转，用设想之词，虚实结合，想象奇特，表现出此时此地此情此景中诗人因愁思难耐、归家无望而生出的怨恨。故乡远在千里，只能梦中相见，也许是短梦，也许是长梦，但梦中醒来却已到天明。字里行间，流露出梦短情长的幽怨。而这一切又都由于“家书到隔年”的实际情况。作为诗歌由写景向抒情的过渡，转句用梦境写旅宿思愁哀怨，亦虚亦实，虚中写实，以实衬虚的特点读来回肠荡气。\n\n　　尾联合，收拢有力，却并非直抒胸意，而是以设想之词，勾勒家乡美丽的生活图景，融情于景，借景抒情，把浓烈的归思之情融入家乡优美的风景之中。沧江烟霭，云霞明灭，月色溶溶，家门外系着钓鱼船，一幅优美宁静祥和的家乡风光图景。画面中虽然没有写人物，但一条静静地系于家门外的钓鱼船却让人产生丰富的联想。面对这样一幅家乡优美的画面，谁人不梦绕魂牵，更何况旅宿在外的诗人呢！家乡远隔千里，旅人归思难收，如此优美的家乡风光图景非但没有给诗人以慰藉，反而加深了诗人的思乡愁苦。这是用乐景反衬哀情的典型。美景幽思、怨恨乡愁、委实凄绝。除却个中人，任何人也难以深味个中情。不过，“烟月”在此实际上是借代，并非一定就是“烟”，就是“月”。正所谓，文学作品的形象大于思维，此处一个“烟月”可以触发不同的旅人思妇产生不同的意象联想，从而产生强大的艺术感染力。\n\n　　颈联与尾联看似跳出了乡愁，艳羡门外沧江鱼船的清闲自在，其实是借他乡之物，更曲折地表达出诗人思乡之情。全诗层层推进，写景抒情都有独到之处。', poem_tags = '古诗三百首,乐府,写人,爱国,抒怀' WHERE poem_title = '白马篇' AND poem_author = '曹植';
UPDATE edu_poem SET poem_translation = '空荡的秋空虽火红似火，可是我心中却千里冷落凄凉，冷清的江水只能伴随着天空流去，何处会是尽头，这秋天无边无际。无奈的眺望远处的山岭，为何，报国又比登天难，为何，国家又如此腐败，只能怪人间正道是沧桑。那群山像女人头上的玉簪和螺髻，难道说，这王朝只剩下花天酒地了吗？斜下的太阳照着这亭子，在长空远飞离群。孤雁伴着它那凄惨绝望声从天空划过，或许是映照着我这流落江南思乡游子。我看着这宝刀，却不曾沾染着敌人的鲜血，我狠狠地把亭上的栏杆都拍遍了，也没有人领会我现在登楼的心意，天下知我者，还能有谁呢？。\n我可不会像张翰那样，为家乡之景而归。那刘备天下为怀，斥责许氾，辞气激扬，令人佩服。只可惜时光如流水一般过去，我真担心着风雨飘荡中的国家，时间如白驹过隙！连一拭英雄泪的红巾翠袖也无人唤取了。\n\n译文二\n辽阔的南国秋空千里冷落凄凉，江水随天空流去，秋天更无边无际。极目遥望远处的山岭，只引起我对国土沦落的忧愁和愤恨，还有那群山像女人头上的玉簪和螺髻。西下的太阳斜照着这楼头，在长空远飞离群孤雁的悲鸣声里，还有我这流落江南的思乡游子。我看着这宝刀，狠狠地把楼上的栏杆都拍遍了，也没有人领会我现在登楼的心意。\n别说鲈鱼切碎了能烹成佳肴美味，西风吹遍了，不知张季鹰已经回来了没？像只为自己购置田地房产的许汜，应怕惭愧去见才气双全的刘备。可惜时光如流水一般过去，我真担心着风雨飘荡中的国家，真像桓温所说树也已经长得这么大了！叫谁去请那些披红着绿的歌女，来为我擦掉英雄失意的眼泪！', poem_notes = '建康：今江苏南京。\n遥岑：岑，音cén。远山。\n玉簪螺髻：簪，音zān；髻，音jì。玉簪、螺髻：玉做的簪子，像海螺形状的发髻，这里比喻高矮和形状各不相同的山岭。\n断鸿：失群的孤雁。\n吴钩，古代吴地制造的一种宝刀。这里应该是以吴钩自喻，空有一身才华，但是得不到重用。\n了：音liǎo。\n鲈鱼堪脍：用西晋张翰典。\n季鹰：张翰，字季鹰。\n求田问舍：置地买房。刘郎：刘备。才气：胸怀、气魄。\n流年：流逝的时光。\n忧愁风雨：风雨，比喻飘摇的国势。\n树犹如此：用西晋桓温典。\n倩：请托。读音qìng\n红巾翠袖：女子装饰，代指女子。\n揾：wèn。擦拭。', poem_appreciation = '这首词是作者在建康通判任上所作。上阕开头以无际楚天与滚滚长江作背景，境界阔大，触发了家国之恨和乡关之思。“落日楼头”以下，表现词人如离群孤雁、像弃置的宝刀难抑胸中郁闷。下阕用三个典故对于四位历史人物进行褒贬，从而表白自己以天下为己任的抱负。叹惜流年如水，壮志成灰。最后流下英雄热泪。\n\n　　这是稼轩早期词中最负盛名的一篇，艺术上也渐趋成熟境界：豪而不放，壮中见悲，力主沉郁顿挫。上片以山水起势，雄浑而不失清丽。“献愁供恨”用倒卷之笔，迫近题旨。以下七个短句，一气呵成。落日断鸿，把看吴钩，拍遍栏杆，在阔大苍凉的背景上，凸现出一个孤寂的爱国者的形象。下片抒怀，写其壮志难酬之悲。不用直笔，连用三个故实，或反用，或正取，或半句缩住，以一波三折、一唱三叹手腕出之。结尾处叹无人唤取红巾“搵英雄泪”，遥应上片“无人会，登临意”，抒慷慨呜咽之情，也别具深婉之致。', poem_tags = '宋词精选,高中古诗,豪放,写景,爱国,壮志' WHERE poem_title = '水龙吟·登建康赏心亭' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '昨夜星光灿烂，夜半却有习习凉风；\n我们酒筵设在画楼西畔、桂堂之东。\n身上无彩凤的双翼，不能比翼齐飞；\n内心却像灵犀一样，感情息息相通。\n互相猜钩嬉戏，隔座对饮春酒暖心；\n分组来行酒令，决一胜负烛光泛红。\n可叹呵，听到五更鼓应该上朝点卯；\n策马赶到兰台，像随风飘转的蓬蒿。', poem_notes = '画楼、桂堂：都是比喻富贵人家的屋舍。\n灵犀：旧说犀牛有神异，角中有白纹如线，直通两头。\n送钩：也称藏钩。古代腊日的一种游戏，分二曹以较胜负。把钩互相传送后，藏于一人手中，令人猜。\n分曹：分组。\n射覆：在覆器下放着东西令人猜。分曹、射覆未必是实指，只是借喻宴会时的热闹。\n鼓：指更鼓。\n应官：犹上班。\n兰台：即秘书省，掌管图书秘籍。李商隐曾任秘书省正字。这句从字面看，是参加宴会后，随即骑马到兰台，类似蓬草之飞转，实则也隐含自伤飘零意。', poem_appreciation = '首联两句，交明时间和地点。叠言昨夜，更有追思不止的意思，同时给人阅读上的审美享受。首句以“昨夜”明点追忆旧事。先说明宴会时间，再说宴会地点，三四句以他物作比，“身无彩凤”写昨夜之情，在宴会上恨无彩凤之翼飞到所爱的人的身旁，“心有灵犀”指犀角中央白色，两头相通，故曰一点通。两心相印，虽身无飞翼，并不能阻挡两人情感的默默交流。“彩凤”、“灵犀”成爱情暗喻，形象婉蓄，色彩明丽，富音乐性。五六句从两人的默契转到对整个宴会的描绘。描写隔座行藏钩之戏，分拨猜测谜底，极写宴会的热闹欢快气氛，为相恋的欢悦涂上了更加丽艳的色彩，与恋人欢快之情和拍。再往深处看，诗人为何会在首句独独写到星辰和风这两个概念性意象。星辰在古代不仅是星星的意思，“中夜登高楼，忆我旧星辰”（唐 孟郊《感怀》），夜晚登上高楼思念往昔的美好，有岁月的意思；“新欢继明烛，梁栋星辰飞”（唐 杜甫《奉送魏六丈佑少府之交广》），喻指辉煌的灯火；古人还称入朝为郎为“上星辰”。自然界的风有暖风、凉风、冷风、阴风等，与人类社会联系起来，又有了风化、风度、风骨、黑风，甚至还暗合了男女情爱之意。这样一来，仅开头这一句，就给人以无限的遐想和疑惑。\n\n　　画楼西畔桂堂东，雕画的阁楼，以桂木为材的厅堂，极言其奢华绮丽。画楼为辅，桂堂是主，引画楼西为桂堂东穿针引线，“隐然有一人影在内”，带领读者顺着诗人的眼光走向桂堂，值得注意的是，诗人是不在桂堂内的，他身处的环境是星辰高挂的静谧幽深的夜空下。\n\n　　后二句圆转溢辉，精工富丽，脍炙人口，是一组绝妙的对句。灵犀，如淳曰：“谓中央色白，通两头”。彩凤和灵犀都是神明之物，足见这里感情的高洁清明。诗句的意思就是叹息自己身无双翼化彩凤，只留得灵明一点与之心意两相通。这种虽不能至心向往之的追求令人感动不已。\n\n　　颈联写送钩覆射酒暖灯红之乐。送钩来自汉代的一个传说，相传钩弋夫人小时候双手一直都是握成拳的姿势，没有办法松开，后来武帝见到，掰开她的手，一块玉钩从手中掉下，从此双手不再蜷曲，被封为“钩弋夫人”，后人对此传说效仿改编，在酒席上藏钩行酒令让人猜玩。覆射也是唐代酒席上的一种游戏，众人在酒令中以字句隐寓事物令人猜度。两个游戏都是需要多人参加配合才能完成的，与前两联诗联系起来，前面还是星辰高挂，泠然清风的空旷夜幕，这里却人影憧憧，酒暖灯红。“暖”字和“红”字，一个形容春酒，一个形容蜡灯，充溢着恣荡欢笑，一派和谐景象。前后对比，令人心生不安。林庚在《唐诗综述》中说：“红是暖色，它是流动的，热闹的，所以近于复杂”，颜色的暗示性在文艺上最富感染力，诗歌中的红色有时是反着说的，古有“寥落古行宫，宫花寂寞红”（唐 元稹《行宫》），“斜拔玉钗灯影畔，别开红焰救飞蛾”（唐 张祜《赠内人》），红花后面有人寂寞，红焰影中只能与飞蛾作伴，枯索之况弥观，惋伤之态弥切。满堂的红影衬托出作者的萧索孤独，让读者惊异于一个世界中竟有反差如此大的两种景象，诗人的寂寞，是深藏在热闹里的寂寞，红，是和谐外表下的激流涌动。\n\n　　诗的最后两句走马兰台的凄凉痛苦也便是水到渠成了，听鼓而起，恰如蓬草，今朝的寂寞萧索，使人念及昨日的灯红酒暖。诗人“嗟”叹自己为“听鼓应官”，而官身却“类转蓬”， 象蓬草那样飘泊不定，因而两人后会难期，欢情难再，令人感伤。这是一种反结法。前面极言欢情，结尾时欢情化为乌有，反衬诗人对这段恋情的难以磨灭，刻骨铭心。', poem_tags = '唐诗三百首,爱情,相思,宴饮,感慨' WHERE poem_title = '无题·昨夜星辰昨夜风' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '栈里，独对残灯，睡不着觉。不知什么缘故，诗人的心情变得十分凄凉悲伤。\n在这除夕之夜，想象故乡人思念千里之外的自己的情景，而明天又要增加一岁，新添不少白发啊。佳节思亲是常情，历来如此。但除夕之夜，“独不眠”、“转凄然”、“思千里”，还有一层意思：到了明天，就又增加一岁，包含了诗人年复一年老大无成的伤感。', poem_appreciation = '除夕之夜，传统的习惯是一家欢聚，“达旦不眠，谓之守岁”（《风土记》）。诗题《除夜作》，本应唤起作者对这个传统佳节的美好记忆，然而这首诗中的除夕夜却是另一种情景。\n\n　　诗的开头就是“旅馆”二字，看似平平，却不可忽视，全诗的感情就是由此而生发开来的。这是一个除夕之夜，诗人眼看着外面家家户户灯火通明，欢聚一堂，而他却远离家人，身居客舍。两相对照，诗人触景生情，连眼前那盏同样有着光和热的灯，也变得“寒”气袭人了。“寒灯”二字，渲染了旅馆的清冷和诗人内心的凄寂。除夕之夜，寒灯只影，诗人难于入眠，而“独不眠”又会想到一家团聚，其乐融融的守岁景象，这更让诗人内心难耐。所以这一句看上去是写眼前景、眼前事，但是却处处从反面扣紧诗题，描绘出一个孤寂清冷的意境。第二句“客心何事转凄然”，这是一个转承的句子，用提问的形式将思想感情更明朗化，因身在客中，故称“客”。诗中问道：“是什么使得客人心里面变得凄凉悲伤？”原因就是他身处除夕之夜。晚上那一片浓厚的除夕气氛，把诗人包围在寒灯只影的客舍之中，他的孤寂凄然之感便油然而生了。此句中“转凄然”三个字写出了在除夕之夜，作者单身一人的孤苦；对千里之外故乡亲人的思念；以及对时光流逝之快的感叹。\n\n　　诗中写完一二句后，诗人似乎要倾吐他此刻的心绪了，可是，他却又撇开自己，从远方的故乡写来：“故乡今夜思千里。”“故乡”，是借指故乡的亲人；“千里”，借指千里之外的诗人自己。意思是说：“故乡的亲人在这个除夕之夜定是在想念着千里之外的我，想着我今夜不知落在何处，想着我一个人如何度过今晚。”其实，这也正是“千里思故乡”的一种表现。诗人并没有直接表达对故乡的思念，而是表达的更加含蓄委婉。\n\n　　“霜鬓明朝又一年”，“今夜”是除夕，所以明朝又是一年了，由旧的一年又将“思”到新的一年，这漫漫无边的思念之苦，又要为诗人增添新的白发。清代沈德潜评价说：“作故乡亲友思千里外人，愈有意味。”（《唐诗别裁》）之所以“愈有意味”，就是因为诗人巧妙地运用“对写法”，把深挚的情思抒发得更为婉曲含蕴。这在古典诗歌中也是一种常见的表现手法，如杜甫的《月夜》：“今夜鄜州月，闺中只独看。”诗中写的是妻子思念丈夫，其实恰恰是诗人自己感情的折射。\n\n　　明代胡应麟认为，绝句“对结者须意尽。如……高达夫‘故乡今夜思千里，霜鬓明朝又一年’，添著一语不得乃可”（《诗薮·内编》卷六）。所谓“意尽”，是指诗意的完整；所谓“添著一语不得”，也就是指语言的精炼。“故乡今夜思千里，霜鬓明朝又一年”，正是把双方思之久、思之深、思之苦，集中地通过除夕之夜抒写出来了，完满地表现了诗的主题思想。因此，就这首诗的高度概括和精炼含蓄的特色而言，已经收到了“意尽”和“添著一语不得”的艺术效果。', poem_tags = '春节,孤独,思乡,岁月' WHERE poem_title = '除夜作' AND poem_author = '高适';
UPDATE edu_poem SET poem_translation = '喇叭和唢呐，吹的曲子虽短，声音却很响亮。官船来往频繁如乱糟糟的麻，全凭借你抬高名誉地位。\n军队听了军队发愁，百姓听了百姓害怕。哪里会去辨别什么真和假？\n眼看着使有的人家倾家荡产，使有的人家元气大伤，直吹得水流干鹅飞跑，家破人亡啊！\n\n译文二\n喇叭锁呐呜呜哇哇，曲儿小来腔儿大。官船来往乱如麻，全凭你来抬声价。\n军人听了军人愁，百姓听了百姓怕。能到哪里去分真和假？\n眼睁睁吹翻了这家，吹伤了那家，只吹得江水枯竭鹅飞罢！', poem_notes = '1.朝天子：曲牌名。\n2.喇叭：铜制管乐器，上细下粗，最下端的口部向四周扩张，可以扩大声音。\n3.唢呐：写作“锁呐”，管乐器，管身正面有七孔，背面一孔。前接一个喇叭形扩声器。民乐中常用。\n4.曲儿小：（吹的）曲子很短。腔儿大：（吹出的）声音很响。曲儿小腔儿大是喇叭、唢呐的特征。本事很小、官腔十足是宦官的特征。\n5.官船：官府衙门的船只。乱如麻：形容来往频繁，出现次数很多。\n6.仗：倚仗，凭借。你：指喇叭、唢呐。抬：抬高。声价：指名誉地位。（宦官装腔作势，声价全靠喇叭来抬。而喇叭其所以能抬声价，又因为它传出的是皇帝的旨意。矛头所指，更深一层。也暗示其狐假虎威的嘴脸。）\n7.军：指军队。愁：发愁。因受搅扰而怨忿。旧时皇帝为了加强对军队统帅的控制，常派宦官监军，以牵制军队长官的行动，十分讨厌。\n8.哪里：同“那里”。辨：分辨、分别。甚么：同“什么”，疑问代词。共：和。\n9.眼见的：眼看着。吹翻了这家：意思是使有的人家倾家荡产。\n10.吹伤了那家：使有的人家元气大伤。\n11.水尽鹅飞罢：水干了，鹅也飞光了。比喻民穷财尽，家破人亡。这是宦官害民的严重后果。水尽鹅飞，“官船”就不能长久来往，这也是对最高统治者的警告，比喻家破人亡。', poem_appreciation = '这首散曲作于明代武宗正德年间，它真实地反映了当时宦官装腔作势地丑恶面目，同时也揭露了他们给人民带来的深重灾难。据蒋一葵《尧山堂外记》中载：“正德间阉寺当权，往来河下无虚日，每到辄吹号头，齐征夫，民不堪命，西楼乃作《咏喇叭》以嘲之。”从这里，我们可以看出王磐作这首散曲的用意。\n\n　　从写作上看，这首散曲可分为三层。前六句状物，其中“曲儿小”二句抓住“喇叭”，“唢呐”的特征，通过“曲儿”的“小”和“腔儿”的“大”的对比描写，给人留下了深刻的印象。“曲儿”本来很小，很细，但是声音经过“腔儿”的放大，就能传扬四方。这里借“曲儿小，腔儿大”来比喻宦官出行的形态，讽刺宦官,貌合神投。宦官原属宫廷中供使唤的奴才，地位本来低下，却倚仗帝王的宠信大摆威风。他们一出皇宫，就狐假虎威，装腔作势，气焰嚣张，先前的唯唯诺诺，奴颜婢膝烟消云散，前后判若两人。“ 曲儿小，腔儿大”最能表现宦官的无耻情态，极富讽刺性。“官船”一句抓住“乱如麻”的特点，“乱”表现了宦官酷吏 的趾高气扬，不可一世的丑恶面目。他们在河中横冲直撞，为非作歹，如入无人之境；“如麻”极言其多，更加突出其骄横野蛮的情态。官船越多，人民受害越深。“全仗你抬身价”一句指的是宦官装腔作势的丑态。“你”表面上是指“喇叭”，“唢呐”；实际上是直戳封建最高统治者，藏而不露，含而不显。宦官如此放肆，正因为有最高统治者做他们的靠山。这里作者对当权者进行了有力的批判，对宦官剥削人民欺压百姓进行了无情的揭露。进一步说明社会风气的腐败。\n\n　　中间三句从听觉方面分别就“军”和“民”两个方面剖析了宦官给社会带来的巨大危害。“愁”是这一层的中心。“军”为何而愁？原来，明代中叶，社会黑暗，宦官当权，他们不仅是皇帝的侍从，也是皇帝的耳目和鹰犬。因此宦官在封建统治集团中有着特殊的地位。他们惯于搬弄是非，颠倒黑白。所以，军官士兵一听说宦官要来，都提心吊胆，小心谨慎地恭维捧场，深怕万一有什么闪失， 被他们抓住把柄，遭到迫害。“民”为何而愁？原因不外乎这几种：抽丁，征税，纳捐。这些宦官“手把文书口称敕”（白居易《卖炭翁》），以王命自居，以势压人，同时表面上又装出堂而皇之，名正言顺的样子，手段阴险而毒辣。“哪里”一句依前两句而来，宦官的危害使人民闻风而“惊”，闻声而“怕”。这样，地痞流氓有机可乘，以假乱真，冒名顶替，趁火打劫。这一句是前两句的延伸和总结。作者猛烈地抨击了宦官专权的罪恶，他们把整个社会搞得乌烟瘴气，使得人人自危。揭露有力，批判深刻。\n\n　　如果说上面一层，作者是从整个社会这一角度来反映宦官的罪恶，那么，最后三句是从宦官对劳动人民造成的灾难来着笔的。\n\n　　“吹翻了这家”是近指，“吹伤了那家”是远指，远近结合，可见范围之大，危害之大。“只吹的水尽鹅飞罢”，这一句从危害的程度来说。“水尽鹅飞”这里有两层意思：首先，这里是借“水尽鹅飞”比喻民财全部被搜刮干净，人民为了缴粮纳税，已经倾家荡产，粮无粟粒，钱无分文。其次，这儿的“水尽鹅飞”跟”竭泽而渔“是同意语，作者严整地警告统治者，你们这样做，只能进一步加重人民的负担，激起人民的反抗，只能是搬起石头砸自己的脚，自寻苦果。这一层作者从广和深两方面分析了宦官给人民带来的灾难，讽刺了宦官在运河沿岸装腔作势，，鱼肉百姓的罪恶行径，传达了人民对宦官的恨。\n\n　　王磬的《朝天子•咏喇叭》托物言志，反映深刻。在结构上，全面围绕“吹”字来组织文字，言“吹”之状，写“吹”之果，绘统治者爪牙“吹”之形，吐人民群众对“吹”之恨。层层推进，有条不紊。以“乐”声来抒“愤”情，一针见血地揭示了封建统治者与百姓的对立，反映了人民的痛苦和不幸。在写法上，运用夸张和讽刺的手法将喇叭与宦官相联系，“性发于此而义归于彼”，把所咏的物于所讽的人关合的相当巧妙，使人读后非常痛快。这首散曲取材精当，比拟恰当，很富有讽刺性，像这样针对当权者嬉笑怒骂的作品，在曲坛上是比较少见的。', poem_tags = '初中古诗,咏物' WHERE poem_title = '朝天子·咏喇叭' AND poem_author = '王磐';
UPDATE edu_poem SET poem_translation = '君子说：学习不可以停止的。\n　　譬如靛青这种染料是从蓝草里提取的，然而却比蓝草的颜色更青；冰块是冷水凝结而成的，然而却比水更寒冷。木材笔直，合乎墨线，但是(用火萃取）使它弯曲成车轮，（那么）木材的弯度（就）合乎（圆到）如圆规画的一般的标准了，即使又晒干了，（木材）也不会再挺直，用火萃取使它成为这样的。所以木材经墨线比量过就变得笔直，金属制的刀剑拿到磨刀石上去磨就能变得锋利，君子广博地学习，并且每天检验反省自己，那么他就会智慧明理并且行为没有过错了。\n　　因此，不登上高山，就不知天多么高；不面临深涧，就不知道地多么厚；不懂得先代帝王的遗教，就不知道学问的博大。干越夷貉之人，刚生下来啼哭的声音是一样的，而长大后风俗习性却不相同，这是教育使之如此。《诗经》上说：“你这个君子啊，不要总是贪图安逸。恭谨对待你的本职，爱好正直的德行。神明听到这一切，就会赐给你洪福 祥瑞。”精神修养没有比受道德熏陶感染更大了，福分没有比无灾无祸更长远了。\n　　我曾经一天到晚地冥思苦想，（却）比不上片刻学到的知识（收获大）；我曾经踮起脚向远处望，（却）不如登到高处见得广。登到高处招手，手臂并没有加长，可是远处的人却能看见；顺着风喊，声音并没有加大，可是听的人却能听得很清楚。借助车马的人，并不是脚走得快，却可以达到千里之外，借助舟船的人，并不善于游泳，却可以横渡长江黄河。君子的资质秉性跟一般人没什么不同，（只是君子）善于借助外物罢了。\n　　南方有一种叫“蒙鸠”的鸟，用羽毛作窝，还用毛发把窝编结起来，把窝系在嫩芦苇的花穗上，风一吹苇穗折断，鸟窝就坠落了，鸟蛋全部摔烂。不是窝没编好，而是不该系在芦苇上面。西方有种叫“射干”的草，只有四寸高，却能俯瞰百里之遥，不是草能长高，而是因为它长在了高山之巅。蓬草长在麻地里，不用扶持也能挺立住，白沙混进了黑土里，就再不能变白了，兰槐的根叫香艾，一但浸入臭水里，君子下人都会避之不及，不是艾本身不香，而是被浸泡臭了。所以君子居住要选择好的环境，交友要选择有道德的人，才能够防微杜渐保其中庸正直。\n　　事情的发生都是有起因的，荣辱的降临也与德行相应。肉腐了生蛆，鱼枯死了生虫，懈怠疏忽忘记了做人准则就会招祸。太坚硬物体易断裂，太柔弱了又易被束缚，与人不善会惹来怨恨，干柴易燃，低洼易湿，草木丛生，野兽成群，万物皆以类聚。所以靶子设置好了就会射来弓箭，树长成了森林就会引来斧头砍伐，树林繁茂荫凉众鸟就会来投宿，醋变酸了就会惹来蚊虫，所以言语可能招祸，行为可能受辱，君子为人处世不能不保持谨慎。\n　　堆积土石成了高山，风雨就从这里兴起了；汇积水流成为深渊，蛟龙就从这里产生了；积累善行养成高尚的品德，自然会心智澄明，也就具有了圣人的精神境界。所以不积累一步半步的行程，就没有办法达到千里之远；不积累细小的流水，就没有办法汇成江河大海。骏马一跨跃，也不足十步远；劣马拉车走十天，（也能到达，）它的成绩来源于走个不停。（如果）刻几下就停下来了，（那么）腐烂的木头也刻不断。（如果）不停地刻下去，（那么）金石也能雕刻成功。蚯蚓没有锐利的爪子和牙齿，强健的筋骨，却能向上吃到泥土，向下可以喝到土壤里的水，这是由于它用心专一啊。螃蟹有六条腿，两个蟹钳，（但是）如果没有蛇、鳝的洞穴它就无处存身，这是因为它用心浮躁啊。\n　　因此没有刻苦钻研的心志，学习上就不会有显著成绩；没有埋头苦干的实践，事业上就不会有巨大成就。在歧路上行走达不到目的地，同时事奉两个君主的人，两方都 不会容忍他。眼睛不能同时看两样东西而看明白，耳朵不能同时听两种声音而听清楚。螣蛇没有脚但能飞，鼫鼠有五种本领却还是没有办法。《诗》上说：“布谷鸟筑巢在桑树上，它的幼鸟儿有七只。善良的君子们，行为要专一不偏邪。行为专一不偏邪，意志才会如磐石坚。”所以君子的意志坚定专一。\n　　古有瓠巴弹瑟，水中鱼儿也浮出水面倾听，伯牙弹琴，拉车的马会停食仰头而听。所以声音不会因为微弱而不被听见，行为不会因为隐秘而不被发现。宝玉埋在深山，草木就会很润泽，珍珠掉进深渊，崖岸就不会干枯。行善可以积累，哪有积善成德而不被广为传诵的呢？\n　　学习究竟应从何入手又从何结束呢？答：按其途径而言，应该从诵读《诗》、《书》等经典入手到《礼记》结束；就其意义而言，则从做书生入手到成为圣人结束。真诚力行，这样长期积累，必能深入体会到其中的乐趣，学到死方能后已。所以学习的教程虽有尽头，但进取之愿望却不可以有片刻的懈怠。毕生好学才成其为人，反之又与禽兽何异？《尚书》是政事的记录；《诗经》是心声之归结；《礼记》是法制的前提、各种条例的总纲，所以要学到《礼经》才算结束，才算达到了道德之顶峰。《礼经》敬重礼仪，《乐经》讲述中和之声，《诗经》《尚书》博大广阔，《春秋》微言大义，它们已经将天地间的大学问都囊括其中了。\n　　君子学习，是听在耳里，记在心里，表现在威仪的举止和符合礼仪的行动上。一举一动，哪怕是极细微的言行，都可以垂范于人。小人学习是从耳听从嘴出，相距不过四寸而已，怎么能够完美他的七尺之躯呢？古人学习是自身道德修养的需求，现在的人学习则只是为了炫耀于人。君子学习是为了完善自我，小人学习是为了卖弄和哗众取宠，将学问当作家禽、小牛之类的礼物去讨人好评。所以，没人求教你而去教导别人叫做浮躁；问一答二的叫啰嗦；浮躁啰嗦都是不对的，君子答问应象空谷回音一般，不多不少、恰到好处。\n　　学习没有比亲近良师更便捷的了。《礼经》、《乐经》有法度但嫌疏略；《诗经》、《尚书》古朴但不切近现实；《春秋》隐微但不够周详；仿效良师学习君子的学问，既崇高又全面，还可以通达世理。所以说学习没有比亲近良师更便捷的了。\n　　崇敬良师是最便捷的学习途径，其次就是崇尚礼仪了。若上不崇师，下不尚礼，仅读些杂书，解释一下《诗经》《尚书》之类，那么尽其一生也不过是一介浅陋的书生而已。要穷究圣人的智慧，寻求仁义的根本，从礼法入手才是能够融会贯通的捷径。就像弯曲五指提起皮袍的领子，向下一顿，毛就完全顺了。如果不究礼法，仅凭《诗经》《尚书》去立身行事，就如同用手指测量河水，用戈舂黍米，用锥子到饭壶里取东西吃一样，是办不到的。所以，尊崇礼仪，即使对学问不能透彻明了，不失为有道德有修养之士；不尚礼仪，即使明察善辩，也不过是身心散漫无真实修养的浅陋儒生而已。\n　　如果有人前来向你请教不合礼法之事，不要回答；前来诉说不合礼法之事，不要去追问；在你面前谈论不合礼法之事，不要去参与；态度野蛮好争意气的，别与他争辩。所以，一定要是合乎礼义之道的，才给予接待；不合乎礼义之道的，就回避他；因此，对于恭敬有礼的人，才可与之谈道的宗旨；对于言辞和顺的人，才可与之谈道的内容；态度诚恳的，才可与之论及道的精深义蕴。所以，跟不可与之交谈的交谈，那叫做浮躁；跟可与交谈的不谈那叫怠慢；不看对方回应而随便谈话的叫盲目。因此，君子不可浮躁，也不可怠慢，更不可盲目，要谨慎地对待每位前来求教的人。《诗经》说：“不浮躁不怠慢才是天子所赞许的。”说的就是这个道理。\n　　射出的百支箭中有一支不中靶，就不能算是善射；驾驭车马行千里的路程，只差半步而没能走完，这也不能算是善驾；对伦理规范不能融会贯通、对仁义之道不能坚守如一，当然也不能算是善学。学习本是件很需要专心志致的事情，学一阵又停一阵那是市井中的普通人。好的行为少而坏的行为多，桀、纣、拓就是那样的人。能够全面彻底地把握所学的知识，才算得上是个学者。\n　　君子知道学得不全不精就不算是完美，所以诵读群书以求融会贯通，用思考和探索去理解，效仿良师益友来实践，去掉自己错误的习惯性情来保持养护。使眼不是正确的就不想看、耳不是正确的就不想听，嘴不是正确的就不想说，心不是正确的就不愿去思虑。等达到完全醉心于学习的理想境地，就如同眼好五色，耳好五声，嘴好五味那样，心里贪图拥有天下一样。如果做到了这般地步，那么，在权利私欲面前就不会有邪念，人多势众也不会屈服的，天下万物都不能动摇信念。活着是如此，到死也不变。这就叫做有德行、有操守。有德行和操守，才能做到坚定不移，有坚定不移然后才有随机应对。能做到坚定不移和随机应对，那就是成熟完美的人了。到那时天显现出它的光明，大地显现出它的广阔，君子的可贵则在于他德行的完美无缺。\n\n注音\n木直中（zhòng)绳\n其曲（qu第一声）中（zhòng）规\n揉（róu）\n槁（gǎo)暴(pù)\n就砺（lì）\n参（cān通“叁”)省(xǐng)\n知（zhì）明\n须臾（yú)\n跂（qǐ）\n假舟楫者 假(jiǎ)\n楫（jí）\n生（xìng)非异也\n跬（kuǐ )步\n骐骥（qí jì)\n驽（nú)马十驾\n锲（qiè)而舍之\n金石可镂（lòu)\n螯（áo )\n蛇鳝（shàn）\n朽（xiǔ）\n假舆（yú）\n善假（jiǎ）于物\n朽木不 折（zhé）\n爪（zhǎo） 牙', poem_notes = '1．君子：指有学问有修养的人。\n2．学不可以已：学习不能停止。\n3．青取之于蓝：靛青，从蓝草中取得。青，靛青，一种染料。蓝，蓼蓝。蓼（liǎo）蓝：一年生草本植物,茎红紫色，叶子长椭圆形,干时暗蓝色。花淡红色，穗状花序，结瘦果，黑褐色。叶子含蓝汁，可以做蓝色染料。于：从\n4．青于蓝：比蓼蓝（更）深。于：比。\n5、中绳：（木材）合乎拉直的墨线。木工用拉直的墨线来取直。\n6．輮以为轮：輮 ：通“煣”，用火烤使木条弯曲（一种手工艺）。以：把。为：当作。\n7．规：圆规，测圆的工具。\n8．虽有槁暴：即使又被风吹日晒而干枯了。有，通“又”。槁，枯。暴，同“曝”，晒干。槁暴，枯干。\n9．挺：直。\n10．受绳：用墨线量过。\n11．金：指金属制的刀剑等。\n12．就砺：拿到磨刀石上去磨。砺，磨刀石。就，动词，接近，靠近。\n13．君子博学而日参省乎己，则知明而行无过矣：参省乎己：对自己检查、省察。参，一译检验，检查；二译同“叁”，多次。省，省察。乎，介词，于。博学：广泛地学习。日：每天。知：通“智”，智慧。明：明达。行无过：行动没有过错。\n14．吾尝终日而思矣：而，表修饰\n15．须臾：片刻，一会儿。\n16．跂：提起脚后跟。\n17．博见：看见的范围广，见得广。\n18．而见者远：意思是远处的人也能看见。而，表转折。\n19．疾：快，速，这里引申为“洪亮”，指声音宏大。\n20．彰：清楚。\n21．假：借助，利用。舆：车。\n22．利足：脚走得快。致：达到。\n23．水：指游泳。名词，用作动词。\n24．绝：横渡。\n25．生非异：本性（同一般人）没有差别。生，通“性”，资质，禀赋。\n26．善假于物也：于：向。物：外物，指各种客观条件。\n27．兴：起,兴盛。\n28．焉：于之，在那里。\n29．渊：深水。\n30．蛟：一种似龙的生物。\n31．积善成德，而神明自得，圣心备焉：积累善行而养成品德，达到很高的境界，通明的思想（也就）具备了。得，获得。而，表因果关系。\n32．跬：古代的半步。古代称跨出一脚为“跬”，跨两脚为“步”。\n33．无以：没有用来……的（办法）\n34．骐骥：骏马，千里马。\n35．驽马十驾：劣马拉车连走十天，（也能走得很远。）驽马，劣马。驾，马拉车一天所走的路程叫“一驾”。\n36．功在不舍：（它的）成功在于不停止。舍，停。\n37．锲：用刀雕刻。\n38．金石可镂：金：金属。石：石头。镂：原指在金属上雕刻，泛指雕刻。\n39．用心一也：（这是）因为用心专一（的缘故）。用，以，因为。\n40．六跪：六条腿，蟹实际上是八条腿。跪，蟹脚。（一说，海蟹后面的两条腿只能划水，不能用来走路或自卫，所以不能算在“跪”里。另一说，“六”虚指。这两说高中课本中没有提到）\n41．螯：螃蟹的大钳子。\n42．躁：浮躁，不专心。\n43．神明：精神智慧。\n44．跪：脚，蟹腿。', poem_appreciation = '课文可分为三部分。\n\n　　①第一部分（第一段）：提出中心论点“学不可以已“，并加以论述。“学不可以已“强调学习的重要性，接着具体论述其重要性，即学习可以提高、改变素质，使人智慧明达、言行无过。这一部分运用了比喻论证的方法，共用了“青，取之于蓝而青于蓝“等5个比喻。\n\n　　②第二部分（第二段）：论证学习的重要作用。阐述学习的重要作用是：学习可使人增长才干的本领，可以改变人的品性。\n\n　　这一部分也运用了比喻论述的方法，共用了“吾尝跂而望矣，不如登高之博见也“等5个比喻。\n\n　　③第三部分（第三段）：论述学习应持的态度。阐述学习应持的态度是：逐渐积累、坚持不懈、专一不躁。这一部分仍运用了比喻论证的方法，共用了“积土成山，风雨兴焉“等10个比喻。', poem_tags = '高中文言文,议论,学习,勉励' WHERE poem_title = '劝学' AND poem_author = '荀子';
UPDATE edu_poem SET poem_translation = '年少的时候，歌楼上听雨，红烛盏盏，昏暗的灯光下罗帐轻盈。人到中年，在异国他乡的小船上，看蒙蒙细雨，茫茫江面，水天一线，西风中，一只失群的孤雁阵阵哀鸣。\n而今，人已暮年，两鬓已是白发苍苍，独自一人在僧庐下，听细雨点点。人生的悲欢离合的经历是无情的，还是让台阶前一滴滴的小雨下到天亮吧。', poem_notes = '虞美人：著名词牌之一。唐教坊曲。兹取两格，一为五十六字，上下片各两仄韵，两平韵。一为五十八字，上下片各两仄韵，三平韵。 \n昏：昏暗，罗帐：古代床上的纱幔。\n断雁：失群孤雁\n僧庐：僧寺，僧舍。\n星星：白发点点如星，形容白发很多。无情：无动于衷。\n一任：听凭。', poem_appreciation = '历代诗人的笔下，绵绵不断的细雨总是和“愁思”难解难分的，如：“梧桐更兼细雨，到黄昏，点点滴滴，这次第，怎一个愁字了得？”“欲黄昏，雨打梨花深闭门。”但是在蒋捷词里，同是“听雨”，却因时间不同、地域不同、环境不同而有着迥然不同的感受。词人从“听雨”这一独特视角出发，通过时空的跳跃，依次推出了三幅“听雨”的画面，而将一生的悲欢歌哭渗透、融汇其中。\n\n　　第一幅画面：“少年听雨歌楼上，红烛昏罗帐。”它展现的虽然只是一时一地的片断场景，但具有很大的艺术容量。“歌楼”、“红烛”、“罗帐”等绮艳意象交织出现，传达出春风骀荡的欢乐情怀。少年时候醉生梦死，一掷千金，在灯红酒绿中轻歌曼舞，沉酣在自己的人生中。一个“昏”字，把那种“风箫吹断水云间，重按霓裳歌遍彻”的奢靡生活表现出来。这时听雨是在歌楼上，他听的雨就增加了歌楼、红烛和罗帐的意味。尽管这属于纸醉金迷的逐笑生涯，毕竟与忧愁悲苦无缘，而作者着力渲染的只是“不识愁滋味”的青春风华。这样的阶段在词人心目中的印象是永恒而短暂的。以这样一个欢快的青春图，反衬后面的处境的凄凉。\n\n　　第二幅画面：“壮年听雨客舟中，江阔云低，断雁叫西风。”一个客舟中听雨的画面，一幅水大辽阔、风急云低的江秋雨图，一只失群孤飞的大雁。这里的“客舟”不是《枫桥夜泊》中的客船，也不是“惊起一滩鸥鹭”里的游船，而是孤独的天涯羁旅，孤独、忧愁、怀旧时时涌在心头。这时的雨伴随着断雁的叫声。这一个“断”字，联系了诸多意境，同断肠联系在一起，同亲情的斩断联系在一起，有一种人生难言的孤独和悔恨。“客舟”及其四周点缀的“江阔”、“云低”、“断雁”、“西风”等衰瑟意象，映现出风雨飘摇中颠沛流离的坎坷遭际和悲凉心境。壮年之后，兵荒马乱之际，词人常常在人生的苍茫大地上踽踽独行，常常尔奔曲走，四方漂流。一腔旅恨、万种离愁都已包孕在他所展示的这幅江雨图中。\n\n　　“而今听雨”的画面，是一幅显示他当前处境的自我画像。一个白发老人独自在僧庐下倾听着夜雨。处境之萧索，心境之凄凉，在十余字中，一览无余。江山己易主，壮年愁恨与少年欢乐，已如雨打风吹去。此时此地再听到点点滴滴的雨声，却已木然无动于衷了。“悲欢离合总无情”，是追抚一生经历得出的结论，蕴有无限感伤，不尽悲慨。“一任阶前点滴到天明”，似乎已心如止水，波澜不起，但彻夜听雨本身，却表明他并没有真正进入超脱沉静的大彻大悟之境，只不过饱经忧患，已具有“欲说还休”的情感控制能力。\n\n　　三幅画面前后衔接而又相互映照，艺术地概括了作者由少到老的人生道路和由春到冬的情感历程。其中，既有个性烙印，又有时代折光：由作者的少年风流、壮年飘零、晚年孤冷，分明可以透见一个历史时代由兴到衰、由衰到亡的嬗变轨迹，而这正是此词的深刻、独到之处。', poem_tags = '宋词三百首,宋词精选,婉约,写雨,感叹,岁月,伤怀' WHERE poem_title = '虞美人·听雨' AND poem_author = '蒋捷';
UPDATE edu_poem SET poem_translation = '一重又一重，重重叠叠的山啊。山是那么远，天是那么高，烟云水气又冷又寒，可我的思念像火焰般的枫叶那样。\n菊花开了又落了，日子一天天过去。塞北的大雁在高空振翅南飞，思念的人却还没有回来。悠悠明月照在帘子上，随风飘飘然。', poem_notes = '《长相思》：调名取自南朝乐府“上言长相思，下言久离别”句，多写男女相思之情。又名《相思令》、《双红豆》、《吴山青》、《山渐青》、《忆多娇》、《长思仙》、《青山相送迎》等。此调有几种不同格体，俱为双调，此词为三十六字体。\n重：量词。层，道。\n烟水：雾气蒙蒙的水面。\n枫叶：枫树叶。枫，落叶乔木，春季开花，叶子掌状三裂。其叶经秋季而变为红色，因此称“丹枫”。古代诗文中常用枫叶形容秋色。丹：红色。\n塞雁：塞外的鸿雁，也作“塞鸿”。塞雁春季北去，秋季南来，所以古人常以之作比，表示对远离故乡的亲人的思念。\n帘：帷帐，帘幕。\n风月：风声月色。', poem_appreciation = '《长相思·一重山》这首小令，《新刻注释草堂诗余评林》在词调下题作“秋怨”。这“秋怨”，便是统贯全词的抒情中心。虽然通篇未曾出现“秋”、“怨”字眼，但仔细吟诵一遍，便会觉得“秋怨”二字确实最为简洁、准确地概括了本词的旨意。 全词写了一个思妇在秋日里苦忆离人、急盼归来，然而最终没有盼来的怨恨心绪。上片写她望中所见之景。那远行在外的征人而今身处何方呢?他是否正跋涉在返乡的路上呢?怀着这种焦迫不安的心情，她不时地企足遥望，希望能够有所发现。可是，进入视野的除了重重叠叠的山岭峰峦外，还有的就是辽阔高远的青冥和天际处的迷离烟水了。第三句描写了一幅荒寂寥廓的群山秋色图，层次极为分明：“一重山”，是近景，“二重山”，是中景；“山远天高烟水寒”，是远景。这一切都是跟着思妇眺望目光的由近及远渐次展开的。清初词人纳兰性德的名作《长相思》曰：“山一程，水一程。身向榆关那畔行。”写主人公越山过水，渐去渐远，很可能是受了该词的启发。需注意的是，“烟水寒”的“寒”，并非仅仅用来形容“烟水”，而且还曲折传出了思妇的心理感觉。正因为久望不见，更添哀伤，心头才滋生了寒意。如此，则目中所见，自然皆带寒意了。上片结句说她“望尽天涯路”而无所得，便收束眼光，不经意地扫视周遭景物，瞥见不远处有枫叶如火，灼人眼目。这使她猛然想起：时令又到了丹枫满山的秋天，自己经年累月的相思之情何日才能了结啊?“相思”一词的出现，使得词旨豁然显现。\n\n　　下片便顺着“相思”折入，着重刻画她的心理活动，写她思中所念之事。“菊花开，菊花残”，用短促、相同的句式，点出时间流逝之速，暗示了她相思日久，怨愁更多。紧连着的“塞雁高飞人未还”，可视为她的直接抒情，也可以看作她在触景生情。塞外大雁尚且知道逢秋南归，那飘泊在外的游子为什么还见不到他的踪影呢?用雁知“归”来反衬人不知“还”，就更深一层地表现出了她的内心怨苦。怨恨尽可以怨恨，但它毕竟是产生于“相思”基础上的，如今良人未还，说不定他碰上了什么意外，或是在路途上染上了风疾。这些想法涌上心头，使得女主人公在怨恨之余，又深深地为他担忧起来了。“一帘风月闲”，刻画出了思妇由于离人不归，对帘外风晨月夕的美好景致无意赏玩的心境。柳永《雨霖铃》词写一对恋人分别后的意绪说：“此去经年，应是良辰好景虚设。便纵有千种风情，更与何人说”，含意正与此同。\n\n　　这首词的最大特点是，句句写思妇“秋怨”，“秋怨”二字却深藏不露。对思妇的外貌、形象、神态、表情未作任何描摹，而是侧重于表现出她的眼中之景，以折现其胸中之情，用笔极其空灵。李煜词的语言锤炼功夫很深，他善于用单纯明净、简洁准确的语言生动地再现物象，展示意境。这个特点在该词里也有鲜明的体现，象“山远天高烟水寒”句，自然明朗，形象丰富，立体感强，境界阔远，并且景中蕴情，耐人寻味。对这首词，前人评价颇多，其中以俞陛云之说为精当：“此词以轻淡之笔，写深秋风物，而兼葭怀远之思，低回不尽，节短而格高，五代词之本色也。”（《南唐二主词辑述评》）', poem_tags = '宋词三百首,秋天,写山,相思' WHERE poem_title = '长相思·一重山' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '千里黄云蔽天日色暗昏昏，北风吹着归雁大雪纷纷。\n不要担心前路茫茫没有知己，普天之下哪个不识君？\n\n就像鸟儿六翮飘摇自伤自怜，离开京洛已经十多年。\n大丈夫贫贱谁又心甘情愿，今天相逢可掏不出酒钱。', poem_notes = '董大：指董庭兰，是当时有名的音乐家　。在其兄弟中排名第一，故称“董大”。\n黄云：天上的乌云，在阳光下，乌云是暗黄色，所以叫黄云。曛 ：昏暗。白日曛，即太阳黯淡无光。\n谁人：哪个人。君：你，这里指董大。\n翮（hé）：鸟的羽翼。飘飖（yáo）：飘动。六翮飘飖，比喻四处奔波而无结果。\n京洛：长安和洛阳。', poem_appreciation = '在唐人赠别诗篇中，那些凄清缠绵、低徊留连的作品，固然感人至深，但另外一种慷慨悲歌、出自肺腑的诗作，却又以它的真诚情谊，坚强信念，为灞桥柳色与渭城风雨涂上了另一种豪放健美的色彩。高适的《别董大二首》便是后一种风格的佳篇。\n\n　　这两首送别诗作于公元747年（天宝六年），当时高适在睢阳，送别的对象是著名的琴师董庭兰。盛唐时盛行胡乐，能欣赏七弦琴这类古乐的人不多。崔珏有诗道：“七条弦上五音寒，此艺知音自古难。惟有河南房次律，始终怜得董庭兰。”这时高适也很不得志，到处浪游，常处于贫贱的境遇之中。但在这两首送别诗中，高适却以开朗的胸襟，豪迈的语调把临别赠言说得激昂慷慨，鼓舞人心。\n\n　　从诗的内容来看，这两篇作品当是写高适与董大久别重逢，经过短暂的聚会以后，又各奔他方的赠别之作。而且，两个人都处在困顿不达的境遇之中，贫贱相交自有深沉的感慨。诗的第二首可作如是理解。第一首却胸襟开阔，写别离而一扫缠绵忧怨的老调，雄壮豪迈，堪与王勃“海内存知己，天涯若比邻”的情境相媲美。\n\n　　“千里黄云白日曛，北风吹雁雪纷纷。”这两句以其内心之真，写别离心绪，故能深挚；以胸襟之阔，叙眼前景色，故能悲壮。曛，即曛黄，指夕阳西沉时的昏黄景色。\n\n　　落日黄云，大野苍茫，唯北方冬日有此景象。此情此景，若稍加雕琢，即不免斫伤气势。高适于此自是作手。日暮黄昏，且又大雪纷飞，于北风狂吹中，唯见遥空断雁，出没寒云，使人难禁日暮天寒、游子何之之感。以才人而沦落至此，几使人无泪可下，亦唯如此，故知己不能为之甘心。头两句以叙景而见内心之郁积，虽不涉人事，已使人如置身风雪之中，似闻山巅水涯有壮士长啸。此处如不用尽气力，则不能见下文转折之妙，也不能见下文言辞之婉转，用心之良苦，友情之深挚，别意之凄酸。\n\n　　“莫愁前路无知己，天下谁人不识君。” 这两句是对朋友的劝慰：此去你不要担心遇不到知己，天下哪个不知道你董庭兰啊！话说得多么响亮，多么有力，于慰藉中充满着信心和力量，激励朋友抖擞精神去奋斗、去拼搏。于慰藉之中充满信心和力量。因为是知音，说话才朴质而豪爽。又因其沦落，才以希望为慰藉。\n\n　　“六翮飘飖私自怜，一离京洛十余年。丈夫贫贱应未足，今日相逢无酒钱。”可见他当时也还处于“无酒钱”的“贫贱”境遇之中。这两首早期不得意时的赠别之作，不免“借他人酒杯，浇自己块垒”。但诗人于慰藉中寄希望，因而给人一种满怀信心和力量的感觉。 诗人在即将分手之际，全然不写千丝万缕的离愁别绪，而是满怀激情地鼓励友人踏上征途，迎接未来。诗之所以卓绝，是因为高适“多胸臆语，兼有气骨”（殷璠《河岳英灵集》）、“以气质自高”（《唐诗纪事》），因而能为志士增色，为游子拭泪。如果不是诗人内心的郁积喷薄而出，则不能把临别赠语说得如此体贴入微，如此坚定不移，也就不能使此朴素无华之语言，铸造出这等冰清玉洁、醇厚动人的诗情。', poem_tags = '赠别,写景,抒情,豪迈,友情,劝慰,早教古诗100首' WHERE poem_title = '别董大二首' AND poem_author = '高适';
UPDATE edu_poem SET poem_translation = '清明时节，春雷万钧，惊醒万物，宇宙给大地带来了勃勃生机。 春雨绵绵，使大地上一片芳草萋萋，桃李盛开。 野田荒芜之处，是埋葬着死者的墓地，死去的人们长眠地下，使活着的人心里感到难过。 诗人由清明的美景想到死者，从死想到了生，想到人生的意义。 诗人指出，人生各不相同。 古代的某个齐人天天到墓地偷吃别人祭奠亲人的饭菜，吃得油嘴腻脸。回到家里，还要对妻子和小妾撒谎吹嘘，他是在某个当大官的朋友家里吃喝，主人如何盛情招待他。 这种人的人生萎琐卑下，毫无人格尊严。 而另有一些高士，如春秋战国时代的介子推，他帮助晋文公建国以后，不要高官厚禄，宁可隐居山中。 晋文公想让他出来做官，下令放火烧山，但是，介子推其志不可动摇，意抱树焚死在绵山中。 黄庭坚由清明的百花盛开想到荒原的逝者，想到人生的价值。他感叹地说，虽然无论智愚高低， 最后都是篷蒿一丘，但是人生的意义却大不相同。', poem_notes = '桃李笑：用拟人手法形容盛开的桃、李花。\n“雷惊”句：意思是清明早已过了惊蛰的节气，万物正欣欣向荣。\n蛰：动物冬眠。\n“人乞”一句：《孟子》中有一则寓言。说齐国有一人每天出外向扫墓者乞讨祭祀后留下的酒饭。回家后却向妻妾夸耀是刖人请自己吃饭。这是一个贪鄙愚蠢的形象。\n“士甘”句：用春秋时介子推宁愿被烧死也不愿再出仕的典故。\n蓬蒿(hao)：杂草。丘?指坟墓。', poem_tags = '清明节,写景,感叹,人生' WHERE poem_title = '清明' AND poem_author = '黄庭坚';
UPDATE edu_poem SET poem_translation = '清晨栏杆外的菊花笼罩着一层愁惨的烟雾，兰花沾露似乎是饮泣的露珠。罗幕之间透露着缕缕轻寒，一双燕子飞去。明月不明白离别之苦，斜斜的银辉直到破晓还穿入朱户。\n昨天夜里西风惨烈，凋零了绿树。我独自登上高楼，望尽那消失在天涯的道路。想给我的心上人寄一封信。但是高山连绵，碧水无尽，又不知道我的心上人在何处。', poem_notes = '蝶恋花：又名“凤栖梧”“鹊踏枝”等。唐教坊曲，后用为词牌。《乐章集》《张子野词》并入“小石调”，《清真集》入“商调”。赵令畤有《商调蝶恋花》，联章作《鼓子词》，咏《会真记》事。双调，六十字，上下片各四仄韵。\n槛（jiàn）：古建筑常于轩斋四面房基之上围以木栏，上承屋角，下临阶砌，谓之槛。至于楼台水榭，亦多是槛栏修建之所。\n罗幕：丝罗的帷幕，富贵人家所用。\n不谙（ān）：不了解，没有经验。谙：熟悉，精通。离恨：一作“离别”。\n朱户：犹言朱门，指大户人家。\n凋：衰落。碧树：绿树。\n彩笺：彩色的信笺。尺素：书信的代称。古人写信用素绢，通常长约一尺，故称尺素，语出《古诗十九首》“客从远方来，遗我双鲤鱼。呼儿烹鲤鱼，中有尺素书”。兼：一作“无”。', poem_appreciation = '婉约派词人许多伤离怀远之作中，这是一首颇负盛名的词。它不仅具有情致深婉的共同特点，而且具有一般婉约词少见的寥阔高远的特色。它不离婉约词，却又某些方面超越了婉约词。\n\n　　起句“槛菊愁烟兰泣露”，写秋晓庭圃中的景物。菊花笼罩着一层轻烟薄雾，看上去似乎脉脉含愁；兰花上沾有露珠，看起来又像默默饮泣。兰和菊本就含有某种象喻色彩（象喻品格的幽洁），这里用“愁烟”“泣露”将它们人格化，将主观感情移于客观景物，透露女主人公自己的哀愁。“愁”“泣”二字，刻画痕迹较显，与大晏词珠圆玉润的语言风格有所不同，但借外物抒写心情、渲染气氛、塑造主人公形象方面自有其作用。\n\n　　次句“罗幕轻寒，燕子双飞去”，写新秋清晨，罗幕之间荡漾着一缕轻寒，燕子双双穿过帘幕飞走了。\n\n　　这两种现象之间本不一定存联系，但充满哀愁、对节候特别敏感的主人公眼中，那燕子似乎是因为不耐罗幕轻寒而飞去。这里，与其说是写燕子的感觉，不如说是写帘幕中人的感受，而且不只是生理上感到初秋的轻寒，而且心理上也荡漾着因孤孑凄凄而引起的寒意。燕的双飞，更反托出人的孤独。这两句纯写客观物象，表情非常微婉含蓄。接下来两句“明月不谙离恨苦，斜光到晓穿朱户”，从今晨回溯昨夜，明点“离恨”，情感也从隐微转为强烈。明月本是无知的自然物，它不了解离恨之苦，而只顾光照朱户，原很自然；既如此，似乎不应怨恨它，但却偏要怨。这种仿佛是无理的埋怨，却有力地表现了女主人公离恨的煎熬中对月彻夜无眠的情景和外界事物所引起的怅触。\n\n　　“昨夜西风凋碧树，独上高楼，望尽天涯路。”过片承上“到晓”，折回写今晨登高望远。“独上”应上“离恨”，反照“双飞”，而“望尽天涯”正从一夜无眠生出，脉理细密。“西风凋碧树”，不仅是登楼即目所见，而且包含有昨夜通宵不寐卧听西风落叶的回忆。碧树因一夜西风而尽凋，足见西风之劲厉肃杀，“凋”字正传出这一自然界的显著变化给予主人公的强烈感受。景既萧索，人又孤独，几乎言尽的情况下，作者又出人意料地展现出一片无限广远寥廓的境界：“独上高楼，望尽天涯路。”这里固然有凭高望远的苍茫之感，也有不见所思的空虚怅惘，但这所向空阔、毫无窒碍的境界却又给主人公一种精神上的满足，使其从狭小的帘幕庭院的忧伤愁闷转向对广远境界的骋望，这是从“望尽”一词中可以体味出来的。这三句尽管包含望而不见的伤离意绪，但感情是悲壮的，没有纤柔颓靡的气息；语言也洗净铅华，纯用白描。这三句是此词中流传千古的佳句。\n\n　　高楼骋望，不见所思，因而想到音书寄远：“欲寄彩笺兼尺素，山长水阔知何处！”彩笺，这里指题诗的诗笺；尺素，指书信。两句一纵一收，将主人公音书寄远的强烈愿望与音书无寄的可悲现实对照起来写，更加突出了“满目山河空念远”的悲慨，词也就这渺茫无着落的怅惘中结束。“山长水阔”和“望尽天涯”相应，再一次展示了令人神往的境界，而“知何处”的慨叹则更增加摇曳不尽的情致。', poem_tags = '宋词三百首,婉约,闺怨,写景,思念' WHERE poem_title = '蝶恋花·槛菊愁烟兰泣露' AND poem_author = '晏殊';
UPDATE edu_poem SET poem_translation = '我在京城小住时日，转眼间就又到了中秋佳节。篱笆下面的菊花都已盛开，秋色明净，就像刚刚擦洗过一般。四面的歌声渐歇，我也终如汉之破楚，突破了家庭的牢笼，如今一个人思量着在浙江时那八年的生活况味。他们苦苦地想让我做一个贵妇人，其实，我是多么的不屑啊！\n\n今生我虽然不能身为男子，加入他们的行列。但是我的心，要比男子的心还要刚烈。想想平日，我的一颗心，常为别人而热。那些俗人，心胸狭窄，怎么能懂我呢？英雄在无路可走的时候，难免要经受磨难挫折。在这莽莽红尘之中，哪里才能觅到知音呢？眼泪打湿了我的衣襟。', poem_notes = '满江红：词牌名。唐朝名《上江虹》，后改今名。\n小住京华：到京不久。小住，暂时居住。京华，京城的美称，这里指北京。\n秋容如拭：秋色明净，就像刚刚擦洗过一般。\n四面歌残终破楚：列强逼近，中国前途危殆。此处用《史记·项羽本纪》“夜闻汉军四面皆楚歌，项王乃大惊”故事。\n八年风味徒思浙：八年来空想着故乡浙江的风味。八年，作者光绪二十二年（1896）在湖南结婚，到作词时恰好八年。徒，空，徒然。\n苦将侬：苦苦地让我。\n蛾眉：美女的代称，这里指女子。\n殊未屑：仍然不放在心上。殊，还，仍然。未，不。屑，顾惜，介意。\n烈：刚正，不轻易屈服。\n因人常热：为别人而屡屡激动。热，激动。\n末路：路途的终点，比喻失意潦倒或没有前途的境地。\n莽（mǎng）：广大。\n青衫湿：失意伤心。用唐白居易《琵琶行》“座中泣下谁最多？江州司马青衫湿”诗义。青衫，唐代文官八品、九品服以青，为官职最低的服色。', poem_appreciation = '这首《满江红》作者是秋瑾，她在词中说自己“身不得男儿列，心却比男儿烈。”这年秋瑾三十岁，有感于民族危机，抛家别子，女扮男装，东渡日本，去追求另样的人生，去寻求民族振兴的道路。\n\n　　自从精忠爱国的民族英雄岳飞首创气壮山河的《满江红》一词以来，已成为千古不朽的绝唱和杰作，历代文人志士莫不把它当作楷模，仿效学作，但大都是望尘莫及！看过古今许多人写的《满江红》，谁也没有岳飞那种气吞牛斗的英雄气概和爱国热情。只有鉴湖女侠的一首《满江红》词，颇有一些男子汉大丈夫的气魄，显示着她不甘雌伏的巾帼英雄的本色。\n\n　　这是她在1903年中秋节的述怀之作，反映了她在封建婚姻家庭和旧礼教的束缚中，走向革命道路前夕的苦闷彷徨和雄心壮志的开阔胸怀。', poem_tags = '豪放,抒怀,壮志' WHERE poem_title = '满江红·小住京华' AND poem_author = '秋瑾';
UPDATE edu_poem SET poem_translation = '太阳出来就去耕作田地，太阳落山就回家去休息。\n凿一眼井就可以有水喝，种出庄稼就不会饿肚皮。\n这样的日子有何不自在，谁还去羡慕帝王的权力。', poem_notes = '壤：据论是古代儿童玩具，以木做成，前宽后窄，长一尺多，形如鞋。玩时，先将一壤置于地，然后在三四十步远处，以另一壤击之，中者为胜。\n作：劳动。\n息：休息。\n帝力句：一说为”帝何德与我哉“。帝力：尧帝的力量。何有：有什么（影响）。如果是”何德“，那就是有什么（恩惠）。', poem_appreciation = '这首歌谣的前四句概括描述了当时农村最原始的生产方式和生活方式。前两句“日出而作，日入而息”，作者用极其简朴的语言描述了远古农民的生存状况——劳动生活。每天看着太阳作息，或劳作或休息。生活简单，无忧无虑。后两句“凿井而饮，耕田而食”，描述的是远古农民的生存状况的另一方面——吃和喝。自己凿井，自己种地，生活虽然劳累辛苦，但自由自在，不受拘束。在前面叙事的基础上，最后一句抒发情感：“帝力于我何有哉！”这样安闲自乐，谁还去向往那帝王的权力？帝王的权力对我有什么用呢？这句诗反映了远古农民旷达的处世态度，反映了当时人们对自然古朴的生产生活方式的自豪和满足，反映了农民对自我力量的充分肯定，也反映了对帝王力量的大胆蔑视。\n\n　　这首歌谣描述了远古时代人们的生存状况，表现了原始社会中人们朴素唯物主义的思想感情。从中可以看到老子“小国寡民……甘其食，美其服，安其居，乐其俗。邻国相望，鸡犬之声相闻，民至老死，不相往来”的影子。语言简朴，叙事简练并结合抒情议论，开头四句连续使用排比句式，语势充沛。整首歌谣风格极为质朴，没有任何渲染和雕饰，艺术形象鲜明生动。歌者无忧无虑的生活状态、怡然自得的神情，都表现得十分自然真切。', poem_tags = '古诗三百首,赞颂,生活,民谣' WHERE poem_title = '击壤歌' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '梳洗完毕，独自一人登上望江楼，倚靠着楼柱凝望着滔滔江面。上千艘船过去了，所盼望的人都没有出现。太阳的余晖脉脉地洒在江面上，江水慢慢地流着，思念的柔肠萦绕在那片白蘋洲上。', poem_notes = '望江南：又名“梦江南”“忆江南”，原唐教坊曲名，后用为词牌名。段安节《乐府杂录》：“《望江南》始自朱崖李太尉（德裕）镇浙日，为亡妓谢秋娘所撰，本名“谢秋娘”，后改此名。”《金奁集》入“南吕宫”。小令，单调二十七字，三平韵。\n梳洗：梳头、洗脸、化妆等妇女的生活内容。\n独：独自，单一。望江楼：楼名，因临江而得名。\n千帆：上千只帆船。帆：船上使用风力的布蓬，又作船的代名词。皆：副词，都。\n斜晖：日落前的日光。晖：阳光。脉脉：本作“眽眽”，凝视貌。《古诗十九首》有“盈盈一水间，脉脉不得语”。后多用以示含情欲吐之意。\n肠断：形容极度悲伤愁苦。白蘋（pín）：水中浮草，色白。古时男女常采蘋花赠别。洲：水边陆地。', poem_appreciation = '此词写一女子登楼远眺、盼望归人的情景，表现了她从希望到失望以致最后的“肠断”的感情。\n\n　　这是一首小令，只有二十七个字。“词之难于令曲，如诗之难于绝句”，“一句一字闲不得”（《白香词谱笺》）。起句“梳洗罢”，看似平平，“语不惊人”。但这三个字内容丰富，给读者留了许多想像的余地。这不是一般人早晨起来的洗脸梳头，而是特定的人物（思妇），在特定条件（准备迎接久别的爱人归来）下，一种特定情绪（喜悦和激动）的反映。\n\n　　在中国古典诗歌中，常以“炉薰阖不用，镜匣上尘生。绮罗失常色，金翠暗无精”之类的描写来表现思妇孤寂痛苦的生活和心情。本篇用法有所不同，离别的痛苦，相思的寂寞，孤独的日子似乎就要过去，或者说她希望中的美好日子似乎就要来到，于是，临镜梳妆，顾影自怜，着意修饰一番。结果是热烈的希望之火遇到冰冷的现实，带来了深一层的失望和更大的精神痛苦，重新又要回到“明镜不治”“首如飞蓬”的苦境中去。这三个字，把这个女子独居的环境，深藏内心的感情变化和对美好生活的向往，不是生动地表现出来了吗？\n\n　　接着，出现了一幅广阔、多彩的艺术画面：“独倚望江楼。”江为背景，楼为主体，焦点是独倚的人。这时的女子，感情是复杂的；随着时间的推移，情绪是变化的。初登楼时的兴奋喜悦，久等不至的焦急，还有对往日的深沉追怀……这里，一个“独”字用得很传神。“独”字，既无色泽，又无音响，却意味深长。这不是恋人昵昵情语的“互倚”，也不是一群人叽叽喳喳的“共倚”，透过这无语独倚的画面，反映了人物的精神世界。一幅美人凭栏远眺图，却是“误几回天际识归舟”的“离情正苦”。把人、景、情联系起来，画面上就有了盛妆女子和美丽江景调和在一起的斑斓色彩，有了人物感情变化和江水流动的交融。\n\n　　“过尽千帆皆不是”，是全词感情上的大转折。这句和起句的欢快情绪形成对照，鲜明而强烈；又和“独倚望江楼”的空寂焦急相连结，承上而启下。船尽江空，人何以堪!希望落空，幻想破灭，这时映入她眼帘的是“斜晖脉脉水悠悠”，落日流水本是没有生命的无情物，但在此时此地的思妇眼里，成了多愁善感的有情者。这是她的痛苦心境移情于自然物而产生的一种联想类比。斜阳欲落未落，对失望女子含情脉脉，不忍离去，悄悄收着余晖；不尽江水似乎也懂得她的心情，悠悠无语流去。它像一组电影镜头：一位着意修饰的女子，倚楼凝眸烟波浩淼的江水，等待久别不归的爱人，从日出到日落，由希望变失望，把这个女子的不幸，表现得多么动人。\n\n　　至此，景物的描绘，感情的抒发，气氛的烘托，都已成熟，最后弹出了全曲的最强音：“肠断白苹洲。”“末句最当留意，有余不尽之意始佳。”和全词“不露痕迹”相较，末句点出主题似太直，但在感情的高潮中结句，仍有“有余不尽之意”。白苹洲在何处？俞平伯先生说，不要“过于落实，似泛说较好”，（俞平伯《唐宋词选释》），这是极为深刻的见解。但在本篇的艺术描写中，应该是江中确有白洲在的，不是比喻、想像，也不是泛指，而是实写。独倚望江楼，一眼就可看到此洲，但那时盼人心切，只顾看船而不见有洲了。千帆过尽，斜晖脉脉，江洲依旧，不见所思，能不肠断!\n\n　　词是注重作家主观抒情的艺术形式。这首小令，情真意切，生动自然，没有矫饰之态和违心之语。词中出现的楼头、船帆、斜晖、江水、小洲，这些互不相干的客观存在物，思妇的由盼郎归来的喜悦到“肠断白苹洲”的痛苦失望，这些人物感情神态的复杂变化，作家经过精巧的艺术构思，使之成为浑然一体的艺术形象。作家的思想感情像一座桥梁，把这些景物、人物联系了起来，而且渗透到了景物描绘和人物活动之中，成了有机的艺术整体，使冰冷的楼、帆、水、洲好像有了温度，有了血肉生命，变得含情脉脉；使分散孤立的风景点，融合成了具有内在逻辑联系的艺术画面；使人物的外在表现和内在的心理活动完美统一地显示出来。这正是现实生活中的思妇的怨和恨，血和泪，深深地感动了作家；在这些似乎平静的字句中，跳动着作家真挚热烈的心。\n\n　　这首小令，像一幅清丽的山水小轴，画面上的江水没有奔腾不息的波涛，发出的只是一种无可奈何的叹息，连落日的余晖，也缺乏峻刻的寓意，盘旋着一股无名的愁闷和难以排遣的怨恨。还有那临江的楼头，点点的船帆，悠悠的流水，远远的小洲，都惹人遐想和耐人寻味，有着一种美的情趣，一种情景交融的意境。这首小令，看似不动声色，轻描淡写中酝酿着炽热的感情，而且宛转起伏，顿挫有致，于不用力处看出“重笔”。\n\n　　思妇题材写的人很多，可说是个“热门题材”，但这首小令，不落俗套，很有特色。这也是个软题材，但这首小令不是软绵绵的，情调积极、健康、朴素。在有着绮靡侧艳“花间”气的温词中，这首小令可说是情真意切，清丽自然，别具一格的精品。', poem_tags = '宋词三百首,初中古诗,闺怨,无奈,思念' WHERE poem_title = '望江南·梳洗罢' AND poem_author = '温庭筠';
UPDATE edu_poem SET poem_translation = '傍晚时心情不快，驾着车登上古原。\n夕阳啊无限美好，只不过已是黄昏。', poem_notes = '乐游原：在长安（今西安）城南，是唐代长安城内地势最高地。汉宣帝立乐游庙，又名乐游苑。登上它可望长安城。乐游原在秦代属宜春苑的一部分，得名于西汉初年。《汉书·宣帝纪》载，“神爵三年，起乐游苑”。汉宣帝第一个皇后许氏产后死去葬于此，因“苑”与“原”谐音，乐游苑即被传为“乐游原”。对此《关中记》有记载：“宣帝许后葬长安县乐游里，立庙于曲江池北，曰乐游庙，因苑（《长安志》误作葬字）为名。”\n向晚：傍晚。不适：不悦， 不快。\n古原：指乐游原。\n近：快要。', poem_appreciation = '玉溪诗人，另有一首七言绝句，写道是：“万树鸣蝉隔断虹，乐游原上有西风，羲和自趁虞泉〔渊〕宿，不放斜阳更向东！”那也是登上古原，触景萦怀，抒写情志之作。看来，乐游原是他素所深喜、不时来赏之地。这一天的傍晚，不知由于何故，玉溪意绪不佳，难以排遣，他就又决意游观消散，命驾驱车，前往乐游原而去。　乐游原之名，我们并不陌生，原因之一是有一篇千古绝唱《忆秦娥》深深印在我们的“诗的摄相”宝库中，那就是：“……乐游原上清秋节，咸阳古道音尘绝。—音尘绝，西风残照，汉家陵阙。”玉溪恰恰也说是“乐游原上有西风”　。何其若笙磬之同音也！那乐游原，创建于汉宣帝时，本是一处庙苑，—应称“乐游苑”才是，只因地势轩敞，人们遂以“原”呼之了。此苑地处长安的东南方，一登古原，全城在览。　自古诗人词客，善感多思，而每当登高望远，送目临风，更易引动无穷的思绪：家国之悲，身世之感，古今之情，人天之思，往往错综交织，所怅万千，殆难名状。陈子昂一经登上幽州古台，便发出了“念天地之悠悠”的感叹，恐怕是最有代表性的例子了。如若罗列，那真是如同陆士衡所说“若中原之有菽”了吧。至于玉溪，又何莫不然。可是，这次他驱车登古原，却不是为了去寻求感慨，而是为了排遣他此际的“向晚意不适”的情怀。知此前提，则可知“夕阳”两句乃是他出游而得到的满足，至少是一种慰藉—这就和历来的纵目感怀之作是有所不同的了。所以他接着说的是：你看，这无边无际、灿烂辉煌、把大地照耀得如同黄金世界的斜阳，才是真的伟大的美，而这种美，是以将近黄昏这一时刻尤为令人惊叹和陶醉！　我想不出哪一首诗也有此境界。或者，东坡的“闲庭曲槛皆拘窘，一看郊原浩荡春！”庶乎有神似之处吧？　可惜，玉溪此诗却久被前人误解，他们把“只是”解成了后世的“只不过”、“但是”之义，以为玉溪是感伤哀叹，好景无多，是一种“没落消极的心境的反映”，云云。殊不知，古代“只是”，原无此义，它本来写作“祗是”，意即“止是”、“仅是”，因而乃有“就是”、“正是”之意了。别家之例，且置不举，单是玉溪自己，就有好例，他在《锦瑟》篇中写道：“此情可待（义即何待）成追忆，只是当时已惘然！”其意正谓：就是（正是）在那当时之下，已然是怅惘难名了。有将这个“只是当时”解为“即使是在当时”的，此乃成为假设语词了，而“只是”是从无此义的，恐难相混。　细味“万树鸣蝉隔断虹”，既有断虹见于碧树鸣蝉之外，则当是雨霁新晴的景色。玉溪固曾有言曰：“天意怜幽草，人间重晚晴。”大约此二语乃玉溪一生心境之写照，故屡于登高怀远之际，情见乎词。那另一次在乐游原上感而赋诗，指羲和日御而表达了感逝波，惜景光，绿鬓不居，朱颜难再之情—这正是诗人的一腔热爱生活、执着人间、坚持理想而心光不灭的一种深情苦志。若将这种情怀意绪，只简单地理解为是他一味嗟老伤穷、残光末路的作品，未知其果能获玉溪之诗心句意乎。毫厘易失，而赏析难公，事所常有，焉敢固必。愿共探讨，以期近是。　（周汝昌）', poem_tags = '唐诗三百首,哲理,惜时,早教古诗100首' WHERE poem_title = '乐游原 / 登乐游原' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '今晚是怎样的晚上啊河中漫游。\n今天是什么日子啊与王子同舟。\n承蒙王子看的起，不（因为我是舟子的身份而）嫌弃我，责骂我。\n心绪纷乱不止啊能结识王子。\n山上有树木啊树木有丫枝，心中喜欢你啊你却不知此事。', poem_notes = '搴（qiān千）：拔。搴舟，犹言荡舟。洲：当从《北堂书钞》卷一O六所引作“舟”。\n被（pi）：同“披”，覆盖。訾（zǐ紫）：说坏话。诟（gòu）耻：耻辱。\n几（jī）：同“机”。王子：此处指公子黑肱（？－前529年），字子皙，春秋时期楚国的王子，父亲楚共王。\n悦：喜欢。', poem_appreciation = '起首两句“今夕何夕兮搴洲中流，今日何日兮得与王子同舟”，“洲”，当从《北堂书钞》卷一O六引作“舟”。“搴洲中流”即在河中荡舟之意。这是记事，记叙了这天晚上荡舟河中，又有幸能与王子同舟这样一件事。在这里，诗人用了十分情感化的“今夕何夕兮”、“今日何日兮”的句式。“今夕”、“今日”本来已经是很明确的时间概念，还要重复追问“今夕何夕”、“今日何日”，这表明诗人内心的激动无比，意绪已不复平静有序而变得紊乱无序，难以控抑。这种句式及其变化以后常为诗人所取用，著名的如宋张孝祥《念奴娇·过洞庭》的末两句“扣舷独啸，不知今夕何夕”。\n\n　　进入诗的中间两句行文用字和章法都明显地由相对平易转为比较艰涩了。这是诗人在非常感情化的叙事完毕之后转入了理性地对自己的心情进行描述。“蒙羞被好兮不訾诟耻，心几烦而不绝兮得知王子”，是说我十分惭愧承蒙王子您的错爱，王子的知遇之恩令我心绪荡漾。\n\n　　最后两句是诗人在非常情感化的叙事和理性描述自己心情之后的情感抒发，此时的诗人已经将激动紊乱的意绪梳平，因此这种情感抒发十分艺术化，用字平易而意蕴深长，余韵袅袅。“山有木兮木有枝”是一个比兴句，既以“山有木”、“木有枝”兴起下面一句的“心悦君”、“君不知”，又以“枝”谐音比喻“知”。在自然界，山上有树树上有枝，顺理成章；但在人间社会，自己对别人的感情深浅归根到底却只有自己知道，许多时候你会觉得自己对别人的感情难以完全表达，因此越人唱出了这样的歌词。而借“枝”与“知”的谐音双关关系做文章的比兴手法，也是《诗经》所惯用的。如《卫风·芄兰》“芄兰之支，童子佩觽；虽则佩觽，能不我知”，《小雅·小弁》“譬彼坏木，疾用无枝；心之忧矣，宁莫之知”，即是。这种谐音双关对后代的诗歌如南朝乐府民歌《子夜歌》等恐怕不无影响。而“山有木兮木有枝，心悦君兮君不知”二句，与《九歌·湘夫人》中“沅有茝兮醴有兰，思公子兮未敢言”二句相仿佛（然“山”句为“A有B兮B有C”句式，“沅”句为“A有B兮C有D”句式，亦有不同），也可见出此楚译《越人歌》深受楚声的影响。虽然今人所读到的《越人歌》是翻译作品，但仍可这样说：《越人歌》的艺术成就表明，两千多年前，古越族的文学已经达到了相当高的水平。', poem_tags = '民谣,爱情' WHERE poem_title = '越人歌' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '燕子飞来正赶上社祭之时，清明节后梨花纷飞。几片碧苔点缀着池中清水，黄鹂的歌声萦绕着树上枝叶，只见那柳絮飘飞。\n在采桑的路上邂逅巧笑着的东邻女伴。怪不得我昨晚做了个春宵美梦，原来它是预兆我今天斗草获得胜利啊!不由得脸颊上也浮现出了笑意。', poem_notes = '破阵子：词牌名，原为唐教坊曲名。又名《十拍子》。双调六十二字，平韵。\n新社：社日是古代祭土地神的日子，以祈丰收，有春秋两社。新社即春社，时间在立春后、清明前。\n碧苔：碧绿色的苔草。\n飞絮：飘荡着的柳絮。\n巧笑：形容少女美好的笑容。逢迎：碰头，相逢。\n疑怪：诧异、奇怪。这里是“怪不得”的意思。\n斗草：古代妇女的一种游戏，也叫“斗百草”。\n双脸：指脸颊。', poem_tags = '宋词三百首,初中古诗,春天,写人,生活' WHERE poem_title = '破阵子·春景' AND poem_author = '晏殊';
UPDATE edu_poem SET poem_translation = '一只渔船上，有两个小孩子，他们收起了竹竿，停下了船桨，坐在船中。\n怪不得没下雨他们就张开了伞，原来他们不是为了遮雨，而是想利用伞当帆让船前进啊。', poem_notes = '安仁：县名，1914年因与湖南安仁县同名而改名余江县。\n篙：撑船用的竹竿或木杆。\n棹：船桨。\n怪生：怪不得。\n使风：诗中指两个小孩用伞当帆，让风来帮忙，促使渔船向前行驶。', poem_appreciation = '“一叶渔船两小童，收篙停棹坐船中。”这是诗人看到的情景。两个小孩之所以引起了诗人的注意，是因为他们虽坐在船上，却没有划船，撑船用的竹竿收起来了，船桨也停在那里，这是奇怪的事。由此可见，此时诗人的心情是闲适的，也是比较愉快的，所以才注意到两个孩童的所作所为。\n\n　　“怪生无雨都张伞，不是遮头是使风。”这里省略了诗人看到的两个孩子撑伞的事，省略了诗人心中由此产生的疑问，而直接把疑窦顿解的愉悦写了出来。疑窦的解开，可能是诗人看到孩童异常的行为，就开始更认真地观察、思考，结果是恍然大悟：两个小孩没下雨也张开伞，原来不是为了遮雨，而是舞动伞柄使风吹动小船使船前进。也可能是直接就问两个孩子，孩子把原因讲给他听的。不管怎样，知道了原因，诗人一定是哑然失笑，为孩童的聪明，也为他们的童真和稚气。\n\n　　在这首诗中，诗人看到在一叶小渔船上，有两个小孩子，他们收起竹篙，停下船桨，张开了伞。而诗人悟到了两个小孩之所以没下雨也张开伞，原来不是为了遮雨，而是想利用风让船前进。\n\n　　诗人直接把目光聚焦到儿童身上，全诗都是写儿童的稚气行为。诗人非常善于利用儿童稚态，起到点化诗境的效果。诗人对儿童的喜爱之情溢于言表，对两个小童子玩耍中透出的聪明伶俐赞赏有加。当然，从中也可以看出诗人的童心不泯。表达了诗人对孩童的喜爱和赞赏。', poem_tags = '古诗三百首,小学古诗,行舟,赞美,儿童' WHERE poem_title = '舟过安仁' AND poem_author = '杨万里';
UPDATE edu_poem SET poem_translation = '您是刚从我们家乡来的，一定了解家乡的人情世态。\n请问您来的时候我家雕画花纹的窗户前，那一株腊梅花开了没有？', poem_notes = '来日：来的时候。\n绮(qǐ)窗：雕画花纹的窗户。\n著花未：开花没有?著（zhuó）花，开花。未，用于句末，相当于“否”，表疑问。', poem_appreciation = '这首诗通篇运用借问法，以第一人称叙写。四句都是游子向故乡来人的询问之辞。游子离家日久，不免思家怀内。遇到故乡来人，迫不及待地打听家中情事。他关心的事情一定很多，其中最关心的是他的妻子。但他偏偏不直接问妻子的情况，也不问其他重大的事，却问起窗前的那株寒梅开花了没有，似乎不可思议。细细品味，这一问，确如前人所说，问得“淡绝妙绝”。窗前着一“绮”字，则窗中之人，必是游子魂牵梦绕的佳人爱妻。清黄叔灿《唐诗笺评》说：“‘绮窗前’三字，含情无限。”体味精妙。而这株亭亭玉立于绮窗前的“寒梅”，更耐人寻味。它或许是爱妻亲手栽植，或许倾听过他们夫妻二人的山盟海誓，总之，是他们爱情的见证或象征。因此，游子对它有着深刻的印象和特别的感情。他不直接说思念故乡、亲人，而对寒梅开花没有这一微小的却又牵动着他情怀的事物表示关切，而把对故乡和妻子的思念，对往事的回忆眷恋，表现得格外含蓄、浓烈、深厚。\n\n　　王维深谙五言绝句篇幅短小，宜于以小见大、以少总多的艺术特点，将抒情主人公交集的百感一一芟除，只留下一点情怀，将他灵视中所映现出的故乡种种景物意象尽量删减，只留下窗前那一树梅花，正是在这净化得无法再净化的情思和景物的描写中，透露出无限情味，引人生出无穷遐想。清人宋顾乐《唐人万首绝句选》评此诗：“以微物悬念，传出件件关心，思家之切。”说得颇中肯。\n\n　　罗宗强先生在论述盛唐诗人善于将情思和境界高度净化时，将王维这首诗与初唐诗人王绩《在京思故园见乡人问》诗作了比较。两诗的题材内容十分类似。\n\n　　王维诗写得质朴自然，感情也真挚动人，但诗中写自己遇到故乡来人询问故乡情事，一连问了子侄、栽树、建茅斋、植竹、种桷、水渠、石苔、果园、林花等一系列问题，“他把见到故乡人那种什么都想了解的心情和盘托出，没有经过删汰，没有加以净化。因此，这许多问，也就没有王维的一问所给人的印象深。”通过这一比较，足以显示出“王维是一位在意境创造中追求情思与景物的净化的高手”（罗宗强《唐诗小史》）。', poem_tags = '唐诗三百首,思乡,思亲,写景,梅花' WHERE poem_title = '杂诗三首·其二' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '都说瑞雪兆丰年，丰年情况将如何？\n长安城里有穷人，我说瑞雪不宜多。', poem_notes = '尽：全。道：讲，说。丰年瑞：瑞雪兆丰年。\n若何：如何，怎么样。\n宜：应该。', poem_appreciation = '题目是“雪”，诗却非咏雪，而是发了一通雪是否瑞兆的议论。绝句长于抒情而拙于议论，五绝篇幅极狭，尤忌议论。作者偏用其短，看来是有意造成一种特殊的风格。　\n\n　　瑞雪兆丰年。辛勤劳动的农民看到飘飘瑞雪而产生丰年的联想与期望，是很自然的。但眼下是在繁华的帝都长安，这“尽道丰年瑞”的声音就颇值得深思。“尽道”二字，语含讥讽。联系下文，可以揣知“尽道丰年瑞”者是和“贫者”不同的另一世界的人们。这些安居深院华屋、身袭蒙茸皮裘的达官显宦、富商大贾，在酒酣饭饱、围炉取暖、观赏一天风雪的时候，正异口同声地大发瑞雪兆丰年的议论，他们也许会自命是悲天悯人、关心民生疾苦的仁者呢！　\n\n　　正因为是此辈“尽道丰年瑞”，所以接下去的是冷冷的一问：“丰年事若何？”即使真的丰年，情况又怎样呢？这是反问，没有作答，也无须作答。“尽道丰年瑞”者自己心里清楚。唐代末叶，苛重的赋税和高额地租剥削，使农民无论丰歉都处于同样悲惨的境地。“二月卖新丝，五月粜新谷”，“六月禾未秀，官家已修仓”，“山前有熟稻，紫穗袭人香。细获又精舂，粒粒如玉珰。持之纳于官，私室无仓箱”。这些诗句对“事若何”作出了明确的回答。但在这首诗里，不道破比道破更有艺术力量。它好象当头一闷棍，打得那些“尽道丰年瑞”者哑口无言。　\n\n　　三、四两句不是顺着“丰年事若何”进一步抒感慨、发议论，而是回到开头提出的雪是否为瑞的问题上来。因为作者写这首诗的主要目的，并不是抒写对贫者虽处丰年仍不免冻馁的同情，而是向那些高谈丰年瑞者投一匕首。“长安有贫者，为瑞不宜多。”好象在一旁冷冷地提醒这些人：当你们享受着山珍海味，在高楼大厦中高谈瑞雪兆丰年时，恐怕早就忘记了这帝都长安有许许多多食不果腹、衣不蔽体、露宿街头的“贫者”。他们盼不到“丰年瑞”所带来的好处，却会被你们所津津乐道的“丰年瑞”所冻死。一夜风雪，明日长安街头会出现多少“冻死骨”啊！“为瑞不宜多”，仿佛轻描淡写，略作诙谐幽默之语，实际上这里面蕴含着深沉的愤怒和炽烈的感情。平缓从容的语调和犀利透骨的揭露，冷隽的讽刺和深沉的愤怒在这里被和谐地结合起来了。\n\n　　雪究竟是瑞兆，还是灾难，离开一定的前提条件，是很难辩论清楚的，何况这根本不是诗的任务。诗人无意进行这样一场辩论。他感到憎恶和愤慨的是，那些饱暖无忧的达官贵人们，本与贫者没有任何共同感受、共同语言，却偏偏要装出一副对丰年最关心、对贫者最关切的面孔，因而他抓住“丰年瑞”这个话题，巧妙地作了一点反面文章，扯下了那些“仁者”的假面具，让他们的尊容暴露在光天化日之下。\n\n　　诗里没有直接出现画面，也没有任何形象的描绘。但读完了全诗，诗人自已的形象却鲜明可触。这是因为，诗中那些看来缺乏形象性的议论，不仅饱含着诗人的憎恶、蔑视、愤激之情，而且处处显示出诗人幽默诙谐、愤世疾俗的性格。从这里可以看出，对诗歌的形象性是不宜作过分偏狭的理解的。', poem_tags = '写雪,忧国忧民' WHERE poem_title = '雪' AND poem_author = '罗隐';
UPDATE edu_poem SET poem_translation = '他把家迁徙到了城郭一带，乡间小路通向桑麻的地方。近处篱笆边都种上了菊花，秋天到了却尚未见它开放。\n敲门竟连一声犬吠都没有，要去向西家邻居打听情况。邻人报说他是到山里去了，回来时总要西山映着斜阳。', poem_notes = '陆鸿渐：名羽，终生不仕，隐居在苕溪（今浙江湖州境内），以擅长品茶著名，著有《茶经》一书，被后人奉为“茶圣”、“茶神”。\n虽：一作“唯”。带：近。郭：外城，泛指城墙。\n篱边菊：语出陶渊明《饮酒》诗：“采菊东篱下，悠然见南山。”\n著花：开花。\n扣门：敲门。\n西家：西邻。\n报道：回答道，报，回报，回答。去：一作“出”。\n归时每日斜：一作“归来日每斜”。日斜：日将落山，暮时也。', poem_appreciation = '此诗载于《全唐诗》卷八一五。下面是中国人民公安大学中国文学教研室主任唐永德教授对此诗的赏析。\n\n　　陆羽和皎然是好友。这首诗当是陆羽迁居后，皎然过访不遇所作。\n\n　　陆羽的新居离城不远，但已很幽静，沿着野外小径，直走到桑麻丛中才能见到。开始两句，颇有陶渊明“结庐在在人境，而无车马喧”的隐士风韵。\n\n　　陆羽住宅外的菊花，大概是迁来以后才种上的，虽到了秋天，还未曾开花。这二句，自然平淡，点出诗人造访的时间是在清爽的秋天。然后，诗人又去敲他的门，不但无人应答，连狗吠的声音都没有。此时的诗人也许有些茫然，立刻就回转去，似有些眷恋不舍，还是问一问西边的邻居吧。邻人回答：陆羽往山中去了，经常要到太阳西下的时候才回来。这二句和贾岛的《寻隐者不遇》的后二句“只在此山中，云深不知处”恰为同趣。“每日斜”的“每”字，活脱地勾画出西邻说话时，对陆羽整天流连山水而迷惑不解和怪异的神态，这就从侧面烘托出陆羽不以尘事为念的高人逸士的襟怀和风度。\n\n　　这首诗前半写陆羽隐居之地的景；后半写不遇的情况，似都不在陆羽身上着笔，而最终还是为了咏人。偏僻的住处，篱边未开的菊花，无犬吠的门户，西邻对陆羽行踪的叙述，都刻画出陆羽生性疏放不俗。全诗四十字，清空如话，别有隽味。', poem_tags = '唐诗三百首,访友,隐士,生活' WHERE poem_title = '寻陆鸿渐不遇' AND poem_author = '皎然';
UPDATE edu_poem SET poem_translation = '夜幕降临，云气收尽，天地间充满了寒气，银河流泻无声，皎洁的月儿转到了天空，就像玉盘那样洁白晶莹。\n我这一生中每逢中秋之夜，月光多为风云所掩，很少碰到像今天这样的美景，真是难得啊！可明年的中秋，我又会到何处观赏月亮呢？', poem_notes = '阳关曲：本名《渭城曲》。单调二十八字，四句三平韵。宋秦观云：《渭城曲》绝句，近世又歌入《小秦王》，更名《阳关曲》。属双调，又属大石调。按，唐教坊记，有《小秦王曲》，即《秦王小破阵乐》也，属坐部伎。\n溢：满出。暗寓月色如水之意。\n银汉：银河。\n玉盘：喻月。', poem_appreciation = '这首小词，题为“中秋月”，自然是写“人月圆”的喜悦；调寄《阳关曲》，则又涉及别情。记述的是作者与其胞弟苏辙久别重逢，共赏中秋月的赏心乐事，同时也抒发了聚后不久又得分手的哀伤与感慨。\n\n　　首句言月到中秋分外明之意，但并不直接从月光下笔，而从“暮云”说起，用笔富于波折。明月先被云遮，一旦“暮云收尽”，转觉清光更多。句中并无“月光”、“如水”等字面，而“溢”字，“清寒”二字，都深得月光如水的神趣，全是积水空明的感觉。\n\n　　月明星稀，银河也显得非常淡远。“银汉无声”并不只是简单的写实，它似乎说银河本来应该有声的，但由于遥远，也就“无声”了，天宇空阔的感觉便由此传出。此夜明月显得格外圆，恰如一面“白玉盘”似的。语本李白《古朗月行》：“小时不识月，呼作白玉盘。”此处用“玉盘”的比喻写出月儿冰清玉洁的美感，而“转”字不但赋予它神奇的动感，而且暗示它的圆。两句并没有写赏月的人，但全是赏心悦目之意，而人自在其中。\n\n　　明月圆，更值兄弟团聚，难怪词人要赞叹“此生此夜”之“好”了。从这层意思说，“此生此夜不长好”大有佳会难得，当尽情游乐，不负今宵之意。不过，恰如明月是暂满还亏一样，人生也是会难别易的。兄弟分离即，又不能不令词人慨叹“此生此夜”之短。从这层意思说，“此生此夜不长好”又直接引出末句的别情。说“明月明年何处看”，当然含有“未必明年此会同”的意思，是抒“离扰”。同时，“何处看”不仅就对方发问，也是对自己发问，实寓行踪萍寄之感。末二句意思衔接，对仗天成。“此生此夜”与“明月明年”作对，字面工整，假借巧妙。“明月”之“明”与“明年”之“明”义异而字同，借来与二“此”字对仗，实是妙手偶得。叠字唱答，再加上“不长好”、“何处看”一否定一疑问作唱答，便产生出悠悠不尽的情韵。\n\n　　这首词从月色的美好写到“人月圆”的愉快，又从当年当夜推想次年中秋，归结到别情。形象集中，境界高远，语言清丽，意味深长。《阳关曲》原以王维《送元二使安西》诗为歌词，苏轼此词与王维诗平仄四声，大体切合，是词家依谱填词之作。', poem_tags = '宋词精选,中秋节,月亮,离别' WHERE poem_title = '阳关曲·中秋月' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '无论是在平地，还是在那高山，哪里鲜花迎风盛开，哪里就有蜜蜂奔忙。\n蜜蜂啊，你采尽百花酿成了花蜜，到底为谁付出辛苦，又想让谁品尝香甜？', poem_notes = '山尖：山峰。\n尽：都。\n占：占其所有。\n甜：醇香的蜂蜜。', poem_appreciation = '蜂与蝶在诗人词客笔下，成为风韵的象征。然而小蜜蜂毕竟与花蝴蝶不同，它是为酿蜜而劳苦一生，积累甚多而享受甚少。诗人罗隐着眼于这一点，写出这样一则寄慨遥深的诗的“动物故事”。仅其命意就令人耳目一新。此诗艺术表现上值得注意的有三点：\n\n　　一、欲夺故予，反跌有力。此诗寄意集中在末二句的感喟上，慨蜜蜂一生经营，除“辛苦”而外并无所有。然而前两句却用几乎是矜夸的口吻，说无论是平原田野还是崇山峻岭，凡是鲜花盛开的地方，都是蜜蜂的领地。这里作者运用极度的副词、形容词──“不论”、“无限”、“尽”等等，和无条件句式，极称蜜蜂“占尽风光”，似与题旨矛盾。其实这只是正言欲反、欲夺故予的手法，为末二句作势。俗话说：抬得高，跌得重。所以末二句对前二句反跌一笔，说蜂采花成蜜，不知究属谁有，将“尽占”二字一扫而空，表达效果就更强。如一开始就正面落笔，必不如此有力。\n\n　　二、叙述反诘，唱叹有情。此诗采用了夹叙夹议的手法，但议论并未明确发出，而运用反诘语气道之。前二句主叙，后二句主议。后二句中又是三句主叙，四句主议。“采得百花”已示“辛苦”之意，“成蜜”二字已具“甜”意。但由于主叙主议不同，末二句有反复之意而无重复之感。本来反诘句的意思只是：为谁甜蜜而自甘辛苦呢？却分成两问：“为谁辛苦”？“为谁甜”？亦反复而不重复。言下辛苦归自己、甜蜜属别人之意甚显。而反复咏叹，使人觉感慨无穷。诗人矜惜怜悯之意可掬。\n\n　　三、寓意遥深，可以两解。此诗抓住蜜蜂特点，不做作，不雕绘，不尚词藻，虽平淡而有思致，使读者能从这则“动物故事”中若有所悟，觉得其中寄有人生感喟。有人说此诗实乃叹世人之劳心于利禄者；有人则认为是借蜜蜂歌颂辛勤的劳动者，而对那些不劳而获的剥削者以无情讽刺。两种解会似相龃龉，其实皆允。因为“寓言”诗有两种情况：一种是作者为某种说教而设喻，寓意较浅显而确定；另一种是作者怀着浓厚感情观物，使物著上人的色彩，其中也能引出教训，但“寓意”就不那么浅显和确定。如此诗，大抵作者从蜂的“故事”看到那时苦辛人生的影子，但他只把“故事”写下来，不直接说教或具体比附，创造的形象也就具有较大灵活性。而现实生活中存在着不同意义的苦辛人生，与蜂相似的主要有两种：一种是所谓“终朝聚敛苦无多，及到多时眼闭了”（《红楼梦》“好了歌”）；一种是“运锄耕劚侵星起”而“到头禾黍属他人”。这就使得读者可以在两种意义上作不同的理解了。但是，随着时代的前进，劳动光荣成为普遍观念，“蜂”越来越成为一种美德的象征，人们在读罗隐这诗的时候，自然更多地倾向于后一种解会了。可见，“寓言”的寓意并非一成不变，古老的“寓言”也会与日俱新。', poem_tags = '寓言,咏物,怜悯' WHERE poem_title = '蜂' AND poem_author = '罗隐';
UPDATE edu_poem SET poem_translation = '小时候每年下雪，我常常会沉醉在插梅花的兴致中。后来虽然梅枝在手，却无好心情去赏玩，只是漫不经心地揉搓着，却使得泪水沾满了衣裳。\n今年梅花又开放的时候，我却一个人住在很偏远的地方，而我耳际短而稀的头发也已斑白。看着那晚来的风吹着开放的梅花，大概也难见它的绚烂了。', poem_notes = '挼（ruó）：揉搓。\n海角天涯：犹天涯海角。本指僻远之地，这里当指临安。\n萧萧两鬓生华：形容鬓发华白稀疏的样子。\n看取：是观察的意思。观察自然界的“风势”。故应：还应。', poem_appreciation = '这首词处处跳动着词人生活的脉搏。她早年的欢乐，中年的幽怨，晚年的沦落，在词中都约略可见。饱经沧桑之后，内中许多难言之苦，通过抒写赏梅的不同感受倾诉了出来。词意含蓄蕴藉，感情悲切哀婉。\n\n　　上片忆旧。分为两层：开头两句回忆早年与赵明诚共赏梅花的生活情景：踏雪寻梅折梅插鬓多么快乐！多么幸福！这“醉”字，不仅是酒醉，更表明女词人为梅花、为爱情、为生活所陶醉。她早年写下的咏梅词《渔家傲》中有句云：“雪里已知春信至，寒梅点缀琼枝腻……共赏金尊沉绿蚁，莫辞醉，此花不与群花比。”可作为“年年雪里，常插梅花醉”的注脚。三四句当写丧偶之后。李清照在抒情时善于将无形的内心感情通过有形的外部动作表现出来，如“倚楼无语理瑶琴”（《浣溪沙》），“更挼残芯，更捻余香，更得些时”（《诉衷情》），“夜阑犹剪烛花弄”（《蝶恋花》）。花还是昔日的花，然而花相似，人不同，物是人非，怎不使人伤心落泪呢？李清照婚后，夫妻志同道合、伉俩相得，生活美满幸福。但是，时常发生的短暂离别使她识尽离愁别苦。在婚后六、七年的时间里，李赵两家相继罹祸，紧接着就开始了长期的“屏居乡里”的生活。生活的坎坷使她屡处忧患，饱尝人世的艰辛。当年那种赏梅的雅兴大减。这两句写的就是词人婚后的这段生活，表现的是一种百无聊赖、忧伤怨恨的情绪。本词中“挼尽”二句，说把梅花揉碎，心情很不好，眼泪把衣襟都湿透了。插梅与挼梅，醉赏梅花与泪洒梅花，前后相比，一喜一悲，反映了不同的生活阶段与不同的心情。\n\n　　下片伤今。“生华”意为生长白发。词人漂泊天涯，远离故土，年华飞逝，两鬓斑白，与上片第二句所描写的梅花簪发的女性形象遥相对照。三四句又扣住赏梅，以担忧的口吻说出：“看取晚来风势，故应难看梅花。”看取意为看着。晚来风急，恐怕落梅已尽，想赏梅也看不成了。早年青春佳偶，人与梅花相映。中年迭经丧乱，心与梅花共碎。晚年漂泊天涯，不想再看梅花委地飘零。词人南渡后，特别是丈夫去世后更是颠沛流离，沦落漂零。生活的折磨使词人很快变得憔悴苍老，头发稀疏，两鬓花白。词人说：如今虽然赏梅季节又到，可是哪里还有心思去插梅呢？而且看来晚上要刮大风，将难以晴夜赏梅了。而且一夜风霜，明朝梅花就要凋零败落，即使想看也看不成了。\n\n　　最后的“看取晚来风势，故应难看梅花”，可能还寄托着词人对国事的忧怀。古人常用比兴，以自然现象的风雨、风云，比政治形势。这里的“风势”既是自然的“风势”，也是政治的“风势”，即“国势”。稍后于清照的辛弃疾的《摸鱼儿》“更能消几番风雨，匆匆春又归去”，与此寓意相似，都寄寓着为国势衰颓而担忧的情绪。清照所说“风势”，似乎是暗喻当时极不利的民族斗争形势；“梅花”以比美好事物，“难看梅花”，则是指国家的遭难，而且颇有经受不住之势。在这种情况下，她根本没有赏梅的闲情逸致。身世之苦、国家之难糅合在一起，使词的思想境界为之升华。\n\n　　这首词篇幅虽小，却运用了多种艺术手法。从依次描写赏梅的不同感受看，运用的是对比手法。赏梅而醉、对梅落泪和无心赏梅，三个生活阶段，三种不同感受，形成鲜明的对比，在对比中表现词人生活的巨大变化。从上下两阕的安排看，运用的是衬托的手法，上阕写过去，下阕写现在，但又不是今昔并重，而是以昔衬今，表现出当时作者飘零沦落、哀老孤苦的处境和饱经磨难的忧郁心情。以赏梅寄寓自己的今昔之感和国家之忧，但不是如咏物词之以描写物态双关人事，词语平实而感慨自深，较之《永遇乐·落日镕金》一首虽有所不及，亦足动人。\n\n　　这一首小词，把个人身世与梅花紧紧联系在一起，在梅花上寄托了遭际与情思，构思甚巧而寄托甚深。', poem_tags = '宋词三百首,宋词精选,梅花,回忆,感伤' WHERE poem_title = '清平乐·年年雪里' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '东汉末年建安年间，庐江府小吏焦仲卿的妻子刘氏，被仲卿的母亲驱赶回娘家，她发誓不再改嫁。但她娘家的人一直逼着她再嫁，她只好投水自尽。焦仲卿听到妻子的死讯后，也吊死在自己家里庭院的树上。当时的人哀悼他们，便写了这样一首诗。\n\n　　孔雀朝着东南方向飞去，每飞五里便是一阵徘徊。\n\n　　“我十三岁就能织出白色的丝绢，十四岁就学会了裁衣。十五岁学会弹箜篌，十六岁就能诵读诗书。十七岁做了你的妻子，但心中常常感到痛苦伤悲。你既然已经做了府吏，当然会坚守臣节专心不移。只留下我孤身一人待在空房，我们见面的日子常常是日渐疏稀。每天当鸡叫的时候我就进入机房纺织，天天晚上都不能休息。三天就能在机上截下五匹布，但婆婆还故意嫌我缓慢松弛。不是我纺织缓慢行动松弛，而是你家的媳妇难做公婆难服侍。我已经受不了你家这样的驱使，徒然留下来也没有什么用处无法再驱驰。你这就禀告公公婆婆，及时遣返我送我回娘家去。”\n\n　　府吏听到这些话，便走到堂上禀告阿母：“儿已经没有做高官享厚禄的福相，幸而娶得这样一个好媳妇。刚成年时我们便结成同床共枕的恩爱夫妻，并希望同生共死直到黄泉也相伴为伍。我们共同生活才过了两三年，这种甜美的日子只是开头还不算长久。她的行为没有什么不正当，哪里知道竟会招致你的不满得不到慈爱亲厚。”\n\n　　阿母对府吏说：“你怎么这样狭隘固执！这个媳妇不懂得礼节，行动又是那样自专自由。我心中早已怀着愤怒，你哪能自作主张对她迁就。东邻有个贤惠的女子，她本来的名字叫秦罗敷。她可爱的体态没有谁能比得上，我当为你的婚事去恳求。你就应该把兰芝快赶走，把她赶走千万不要让她再停留！”\n\n　　府吏直身长跪作回答，他恭恭敬敬地再向母亲哀求：“现在如果赶走这个媳妇，儿到老也不会再娶别的女子！”\n\n　　阿母听了府吏这些话，便敲着坐床大发脾气：“你这小子胆子太大毫无畏惧，你怎么敢帮着媳妇胡言乱语。我对她已经断绝了情谊，对你的要求决不会依从允许！”\n\n　　府吏默默不说话，再拜之后辞别阿母回到自己的房里。开口向媳妇说话，悲痛气结已是哽咽难语：“我本来不愿赶你走，但阿母逼迫着要我这样做。但你只不过是暂时回到娘家去，现在我也暂且回到县官府。不久我就要从府中回家来，回来之后一定会去迎接你。你就为这事委屈一下吧，千万不要违背我这番话语。”\n\n　　兰芝对府吏坦陈：“不要再这样麻烦反复叮咛！记得那年初阳的时节，我辞别娘家走进你家门。侍奉公婆都顺着他们的心意，一举一动哪里敢自作主张不守本分？日日夜夜勤劳地操作，孤身一人周身缠绕着苦辛。自以为可以说是没有什么罪过，能够终身侍奉公婆报答他们的大恩。但仍然还是要被驱赶，哪里还谈得上再转回你家门。我有一件绣花的短袄，绣着光彩美丽的花纹。还有一床红罗做的双层斗形的小帐，四角都垂挂着香囊。大大小小的箱子有六七十个，都是用碧绿的丝线捆扎紧。里面的东西都各不相同，各种各样的东西都收藏其中。人既然低贱东西自然也卑陋，不值得用它们来迎娶后来的新人。你留着等待以后有机会施舍给别人吧，走到今天这一步今后不可能再相会相亲。希望你时时安慰自己，长久记住我不要忘记我这苦命的人。”\n\n　　当公鸡呜叫窗外天快要放亮，兰芝起身精心地打扮梳妆。她穿上昔日绣花的裌裙，梳妆打扮时每件事都做了四五遍才算妥当。脚下她穿着丝鞋，头上的玳瑁簪闪闪发光。腰间束着流光的白绸带，耳边挂着明月珠装饰的耳珰。十个手指像尖尖的葱根又细又白嫩，嘴唇涂红像含着朱丹一样。她轻轻地小步行走，艳丽美妙真是举世无双。\n\n　　她走上堂去拜别阿母，阿母听任她离去而不挽留阻止。“从前我做女儿的时候，从小就生长在村野乡里。本来就没有受到教管训导，更加惭愧的是又嫁到你家愧对你家的公子。受了阿母许多金钱和财礼，却不能胜任阿母的驱使。今天我就要回到娘家去，还记挂着阿母孤身操劳在家里。”她退下堂来又去向小姑告别，眼泪滚滚落下像一连串的珠子。“我这个新媳妇初嫁过来时，小姑刚学走路始会扶床。今天我被驱赶回娘家，小姑的个子已和我相当。希望你尽心地侍奉我的公婆，好好地扶助他们精心奉养。每当七夕之夜和每月的十九日，玩耍时千万不要把我忘。”她走出家门上车离去，眼泪落下百多行。\n\n　　府吏骑着马走在前头，兰芝坐在车上跟在后面走。车声时而小声隐隐时而大声甸甸，但车和马都一同到达了大道口。府吏下马走进车中，低下头来在兰芝身边低声细语：“我发誓不同你断绝，你暂且回到娘家去，我今日也暂且赶赴官府。不久我一定会回来，我向天发誓永远不会辜负你。”\n\n　　兰芝对府吏说：“感谢你对我的诚心和关怀。既然承蒙你这样的记着我，不久之后我会殷切地盼望着你来。你应当像一块大石，我必定会像一株蒲苇。蒲苇像丝一样柔软但坚韧结实，大石也不会转移。只是我有一个亲哥哥，性情脾气不好常常暴跳如雷。恐怕不能任凭我的心意由我自主，他一定会违背我的心意使我内心饱受熬煎。”两人忧伤不止地举手告别，双方都依依不舍情意绵绵。\n\n　　兰芝回到娘家进了大门走上厅堂，进退为难觉得脸面已失去。母亲十分惊异地拍着手说道：“想不到没有去接你你自己回到家里。十三岁我就教你纺织，十四岁你就会裁衣，十五岁会弹箜篌，十六岁懂得礼仪，十七岁时把你嫁出去，总以为你在夫家不会有什么过失。你现在并没有什么罪过，为什么没有去接你你自己回到家里？”“我十分惭愧面对亲娘，女儿实在没有什么过失。”亲娘听了十分伤悲。\n\n　　回家才过了十多日，县令便派遣了一个媒人来提亲。说县太爷有个排行第三的公子，身材美好举世无双。年龄只有十八九岁，口才很好文才也比别人强。\n\n　　亲娘便对女儿说：“你可以出去答应这门婚事。”\n\n　　兰芝含着眼泪回答说：“兰芝当初返家时，府吏一再嘱咐我，发誓永远不分离。今天如果违背了他的情义，这门婚事就大不吉利。你就可以去回绝媒人，以后再慢慢商议。”\n\n　　亲娘出去告诉媒人：“我们贫贱人家养育了这个女儿，刚出嫁不久便被赶回家里，不配做小吏的妻子，哪里适合再嫁你们公子为妻？希望你多方面打听打听，我不能就这样答应你。”\n\n　　媒人去了几天后，那派去郡里请示太守的县丞刚好回来。他说：“在郡里曾向太守说起一位名叫兰芝的女子，出生于官宦人家。”又说：“太守有个排行第五的儿子，貌美才高还没有娶妻。太守要我做媒人，这番话是由主簿来转达。”县丞来到刘家直接说：“在太守家里，有这样一个美好的郎君，既然想要同你家结亲，所以才派遣我来到贵府做媒人。”\n\n　　兰芝的母亲回绝了媒人：“女儿早先已有誓言不再嫁，我这个做母亲的怎敢再多说？”\n\n　　兰芝的哥哥听到后，心中不痛快十分烦恼，向其妹兰芝开口说道：“作出决定为什么不多想一想！先嫁是嫁给一个小府吏，后嫁却能嫁给太守的贵公子。命运好坏差别就像天和地，改嫁之后足够让你享尽荣华富贵。你不嫁这样好的公子郎君，往后你打算怎么办？”\n\n　　兰芝抬起头来回答说：“道理确实像哥哥所说的一样，离开了家出嫁侍奉丈夫，中途又回到哥哥家里，怎么安排都要顺着哥哥的心意，我哪里能够自作主张？虽然同府吏有过誓约，但同他相会永远没有机缘。立即就答应了吧，就可以结为婚姻。”媒人从坐床走下去，连声说好!好!就这样!就这样!他回到太守府禀告太守：“下官承奉着大人的使命，商议这桩婚事谈得很投机。”太守听了这话以后，心中非常欢喜。他翻开历书反复查看，吉日就在这个月之内，月建和日辰的地支都相合。“成婚吉日就定在三十日，今天已是二十七日，你可立即去办理迎娶的事。”彼此相互传语快快去筹办，来往的人连续不断像天上的浮云。迎亲的船只上画着青雀和白鹄，船的四角还挂着绣着龙的旗子。旗子随风轻轻地飘动，金色的车配着玉饰的轮。驾上那毛色青白相杂的马缓步前进，马鞍两旁结着金线织成的缨子。送了聘金三百万，全部用青丝串联起。各种花色的绸缎三百匹，还派人到交州广州购来海味和山珍。随从人员共有四五百，热热闹闹地齐集太守府前准备去迎亲。\n\n　　亲娘对兰芝说：“刚才得到太守的信，明天就要来迎娶你。你为什么还不做好衣裳？不要让事情办不成!”\n\n　　兰芝默默不说话，用手巾掩口悲声啼，眼泪坠落就像流水往下泻。移动她那镶着琉璃的坐榻，搬出来放到前窗下。左手拿着剪刀和界尺，右手拿着绫罗和绸缎。早上做成绣裌裙，傍晚又做成单罗衫。一片昏暗天时已将晚，她满怀忧愁想到明天要出嫁便伤心哭泣。\n\n　　府吏听到这个意外的变故，便告假请求暂且回家去看看。还未走到刘家大约还有二三里，人很伤心马儿也悲鸣。兰芝熟悉那匹马的鸣声，踏着鞋急忙走出家门去相迎。心中惆怅远远地望过去，知道是从前的夫婿已来临。她举起手来拍拍马鞍，不断叹气让彼此更伤心。“自从你离开我之后，人事变迁真是无法预测和估量。果然不能满足我们从前的心愿，内中的情由又不是你能了解端详。我有亲生的父母，逼迫我的还有我的亲兄长。把我许配了别的人，你还能有什么希望!”\n\n　　府吏对兰芝说：“祝贺你能够高升!大石方正又坚厚，可以千年都不变。蒲苇虽然一时坚韧，但只能坚持很短的时间。你将一天比一天生活安逸地位显贵，只有我独自一人下到黄泉。”\n\n　　兰芝对府吏说：“想不到你会说出这样的话!两人同样是被逼迫，你是这样我也是这样受熬煎。我们在黄泉之下再相见，不要违背今天的誓言!”他们握手告别分道离去，各自都回到自己家里面。活着的人却要做死的离别，心中抱恨哪里能够说得完。他们都想很快地离开人世，无论如何也不愿苟且偷生得保全。\n\n　　府吏回到自己家，上堂拜见阿母说：“今天风大天又寒，寒风摧折了树木，浓霜冻坏了庭院中的兰花。我今天已是日落西山生命将终结，让母亲独留世间以后的日子孤单。我是有意作出这种不好的打算，请不要再怨恨鬼神施责罚!但愿你的生命像南山石一样的久长，身体强健又安康。”\n\n　　阿母听到了这番话，泪水随着语声往下落：“你是大户人家的子弟，一直做官在官府台阁。千万不要为了一个妇人去寻死，贵贱不同你将她遗弃怎能算情薄？东邻有个好女子，苗条美丽全城称第一。做母亲的为你去求婚，答复就在这早晚之间。”\n\n　　府吏再拜之后转身走回去，在空房中长叹不已。他的决心就这样定下了，把头转向屋子里，心中忧愁煎迫一阵更比一阵紧。\n\n　　迎亲的那一天牛马嘶叫，新媳妇兰芝被迎娶进入青色帐篷里。天色昏暗已是黄昏后，静悄悄的四周无声息。“我的生命终结就在今天，只有尸体长久留下我的魂魄将要离去。”她挽起裙子脱下丝鞋，纵身一跳投进了清水池。\n\n　　府吏听到了这件事，心里知道这就是永远的别离，于是来到庭院大树下徘徊了一阵，自己吊死在东南边的树枝。\n\n　　两家要求将他们夫妻二人合葬，结果合葬在华山旁。坟墓东西两边种植着松柏，左右两侧栽种梧桐。各种树枝枝枝相覆盖，各种树叶叶叶相连通。中间又有一对双飞鸟，鸟名本是叫鸳鸯，它们抬起头来相对鸣叫，每晚都要鸣叫一直叫到五更。过路的人都停下脚步仔细听，寡妇惊起更是不安和彷徨。我要郑重地告诉后来的人，以此为鉴戒千万不要把它忘。', poem_notes = '建安中：建安年间（—）。建安，东汉献帝刘协的年号。\n庐江：汉代郡名，郡城在今安徽潜山一带。\n遣：女子出嫁后被夫家休弃回娘家。\n云尔：句末语气词。如此而已。\n徘徊（pái huái）：来回走动。汉代乐府诗常以飞鸟徘徊起兴，以写夫妇离别。\n素：白绢。这句话开始到“及时相遣归”是焦仲卿妻对仲卿说的。\n箜篌（kōnghóu）：古代的一种弦乐器，形如筝瑟。\n诗书：原指《诗经》和《尚书》，这里泛指儒家的经书。\n守节：遵守府里的规则。\n断：（织成一匹）截下来。\n大人故嫌迟：婆婆故意嫌我织得慢。大人，对长辈的尊称，这里指婆婆。\n不堪：不能胜任。\n徒：徒然，白白地。\n施：用。\n白公姥（mǔ）：禀告婆婆。白，告诉，禀告。公姥，公公婆婆，这里是偏义复词，专指婆婆。\n薄禄相：官禄微薄的相貌。\n结发：束发。古时候的人到了一定的年龄（男子岁，女子岁）才把头发结起来，算是到了成年，可以结婚了。\n始尔：刚开始。尔，助词，无义。一说是代词，这样。\n致不厚：招致不喜欢。致，招致。厚，厚待。这里是“喜欢”的意思。\n区区：小，这里指见识短浅。\n自专由：与下句“汝岂得自由”中的“自由”都是自作主张的意思。专，独断专行。由，随意，任意。\n贤：这里指聪明贤惠。\n可怜：可爱。\n伏惟：趴在地上想。古代下级对上级或小辈对长辈说话表示恭敬的习惯用语。\n取：通“娶”，娶妻。\n床：古代的一种坐具。\n会不相从许：当然不能答应你的要求。会，当然，必定。\n举言：发言，开口。\n新妇：媳妇（不是新嫁娘）。“新妇”是汉代末年对已嫁妇女的通称。\n报府：赴府，指回到庐江太守府。\n下心意：低心下意，受些委屈。\n勿复重（chóng）纷纭：不必再添麻烦吧。也就是说，不必再提接她回来的话了。\n初阳岁：农历冬末春初。\n谢：辞别。\n作息：原意是工作和休息，这里是偏义复词，专指工作。\n伶俜（pīng）萦（yíng）苦辛：孤孤单单，受尽辛苦折磨。伶俜，孤单的样子。萦，缠绕。\n谓言：总以为。\n卒：完成，引申为报答。\n绣腰襦（rú）：绣花的齐腰短袄。\n葳蕤（wēi ruí）：草木繁盛的样子，这里形容短袄上刺绣的花叶繁多而美丽。\n箱帘：箱，衣箱。帘，通“奁”，古代妇女梳妆用的镜匣。\n后人：指府吏将来再娶的妻子。\n遗（wèi）施：赠送，施与。\n会因：会面的机会。\n严妆：整妆，郑重地梳妆打扮。\n通：次，遍。\n蹑（niè）：踩，踏，这里指穿鞋。\n玳瑁（dài mào）：一种同龟相似的爬行动物，甲壳可制装饰品。\n珰（dāng）：耳坠。\n昔作女儿时：以下八句是仲卿妻对焦母告别时说的话。\n野里：乡间。\n兼愧：更有愧于……\n却：从堂上退下来。\n扶将：扶持，搀扶。这里是服侍的意思。\n初七及下九：七月七日和每月的十九日。初七，指农历七月七日，旧时妇女在这天晚上在院子里陈设瓜果，向织女星祈祷，祈求提高刺绣缝纫技巧，称为“乞巧”。下九，古人以每月的二十九为上九，初九为中九，十九为下九。在汉朝时候，每月十九日是妇女欢聚的日子。\n隐隐：和下面的“甸甸”都是象声词，指车声。\n誓不相隔卿……誓天不相负：这是府吏对兰芝说的话。\n区区：这里是诚挚的意思，与上面“何乃太区区”中的“区区”意思不同。\n若见录：如此记住我。见录，记着我。见，被。录，记。\n纫：通“韧”，柔韧牢固。亲父兄：即同胞兄。\n逆：逆料，想到将来。\n劳劳：怅惘若失的样子。\n颜仪：脸面，面子。\n拊（fǔ）掌：拍手，这里表示惊异。\n子自归：你自己回来。意思是，没料到女儿竟被驱遣回家。古代女子出嫁以后，一定要娘家得到家的同意，派人迎接，才能回娘家。下文“不迎而自归”，也是按这种规矩说的责备的话。\n无誓违：不会有什么过失。誓，似应作“諐”。諐，古“愆（qiān）”字。愆违，过失。\n悲摧：悲痛，伤心。\n窈窕（yǎo tiǎo）：容貌体态美好的样子。\n便（pián）言多令才：口才很好，又多才能。便言，很会说话。令，美好。\n丁宁：嘱咐我。丁宁，嘱咐，后写作“叮咛”。\n非奇：不宜，不妥。\n断来信：回绝来做媒的人。断，回绝。信，使者，指媒人。\n更谓之：再谈它。之，指再嫁之事。\n适：出嫁。\n不堪：这里是“不能做”的意思。\n媒人去数日……丞籍有宦官：这几句可能有文字脱漏或错误，因此无法解释清楚。这里列出部分字的意义解释：寻，随即，不久。丞，县丞，官名。承籍，承继先人的仕籍。宦官，即“官宦”，指做官的人。\n娇逸：娇美文雅。\n主簿：太守的属官。\n作计：拿主意，打算。\n量（liáng）：考虑。\n否（pǐ）泰：都是《易经》中的卦名。这里指运气的好坏。否，坏运气。泰，好运气。\n义郎：男子的美称，这里指太守的儿子。\n其往欲何云：往后打算怎么办。其往，其后，将来。何云，这里指怎么办。\n处分：处置。\n适：依照。\n要（yāo）：相约。\n渠（qú）会：同他相会。渠，他。一说是那种相会。渠，那。\n登即：立即。\n尔尔：如此如此。等于说“就这样，就这样”。\n府君：对太守的尊称。\n下官：县丞自称。\n缘：缘分。\n视历：翻看历书。\n六合：古时候迷信的人，结婚要选好日子，要年月日的干支（干，天干，甲乙丙丁……支，地支，子丑寅卯……）合起来都相适合，这叫“六合”。\n卿：你，指县丞。\n交语：交相传话。\n舫（fǎng）：船。\n龙子幡（fān）：绣龙的旗帜。\n婀娜（ē nuó）：轻轻飘动的样子。\n踯躅（zhí zhú）：缓慢不进的样子。\n青骢（cōng）马：青白杂毛的马。\n流苏：用五彩羽毛做的下垂的缨子。\n赍（jī）：赠送。\n杂彩：各种颜色的绸缎。\n交广：交州广州，古代郡名，这里泛指今广东广西一带。\n鲑（xié）：这里是鱼类菜肴的总称。\n郁郁：繁盛的样子。\n适：刚才。\n不举：办不成。\n榻（tà）：坐具。\n晻晻（yǎnyǎn）：日色昏暗无光的样子。\n摧藏（zàng）：摧折心肝。藏，脏腑。\n人事不可量：人间的事不能预料。\n父母：这里偏指母。\n弟兄：这里偏指兄。\n日胜贵：一天比一天高贵。\n恨恨：抱恨不已，这里指极度无奈。\n日冥冥：原意是日暮，这里用太阳下山来比喻生命的终结。\n单：孤单。\n故：有意，故意。\n不良计：不好的打算（指自杀）。\n四体：四肢，这里指身体。\n直：意思是腰板硬朗。\n台阁：原指尚书台，这里泛指大的重府。\n情何薄：怎能算是薄情。\n乃尔立：就这样决定。\n青庐：用青布搭成的篷帐，举行婚礼的地方。\n奄奄：通“晻晻”，日色昏暗无光的样子。\n黄昏：古时计算时间按十二地支将一日分为十二个“时辰”。“黄昏”是“戌时”（相当于现代的晚上时至时）。下句的“人定”是“亥时”（相当于现代的晚上时至时）。\n华山：庐江郡内的一座小山。\n交通：交错，这里指挨在一起。\n驻足：停步。\n谢：告诉。', poem_appreciation = '《孔雀东南飞》在艺术上标志着中国古代叙事诗已臻成熟，其主要表现有三：\n\n　　一、成功地塑造了刘兰芝、焦仲卿等艺术形象。刘兰芝不仅敢爱敢恨，敢说敢为，具有强烈的反抗性格，而且在别小姑、别仲卿时，赠物留言、订立蒲石之盟，于悲怆之中充满了温厚的深情。她感情丰富，形象饱满，不同于一般叙事诗中人物性格的单一简略。与兰芝相较，仲卿形象更为复杂。他忍让求母，委曲求全，显得软弱，但这是当时一般人所无法超越的时代局限，何况他身为府吏，更不能不受封建法规的制约。然而他的求，在当时是对母命的公开顶撞，实在是对封建礼教的大不敬。进而又对母命阳奉阴违，表面上驱遣兰芝，私下却密约重娶，表明他倔强不驯，只是绵里藏针、刚强不露而已。至于他告母自裁，幻想以此促使其母同意他与兰芝重新结合，这是他认识上的不足。但论其态度，实已由一般的顶撞发展到了威胁的地步。然而愚昧无知的焦母，虽然爱子，却仍坚持另娶。仲卿则在幻想破灭之后，并不因此屈从其母而终于以死殉情，充分显示了焦仲卿的反叛性格。这是一个既想当孝子，但在与切身利害冲突下又不甘于愚孝的典型。黑暗的环境和现实的矛盾造就了仲卿这种思想性格。作者不仅写出了人物性格中的个性，而且写出了他们性格中所特有的复杂性，有血有肉兼有神，可歌可泣又可信，这决非短小的抒情诗和一般的叙事诗所能达到的境界。诗中的主要人物是如此，对于次要人物，作者同样注意性格描写，因而能写出同类人物的不同特点。如刘母和焦母，同为老寡妇，刘母家境清寒，性格懦弱，虽同情女儿而又不能不听从儿子的安排，反映了封建礼教“夫死从子”的黑暗；焦母则富有高傲，为人凶悍，不仅不从子，而且要儿子从她，表现出封建家长的淫威。她们同为妇女，在同一社会中，却因境遇所造就的性格不同而扮演了不同的角色。这种艺术造诣是当时其他叙事诗中所看不到的。\n\n　　二、故事情节完整，矛盾冲突不断。《孔雀东南飞》以人物为中心铺叙故事，情节曲折，首尾完整。故事带有传奇的色彩：一个被休弃的妇女，竟然受到县令、太守相继登门为子求婚的奇遇，显然这是极其偶然而富有戏剧性的情节。但作者并不单纯地追求离奇的故事，而是借助于情节，描写人与人之间的关系。作者写此奇遇，不仅衬托出兰芝之美，歌颂了兰芝忠贞专一、不为利诱的品格，而且在比较中刻画出她与刘兄、刘母截然不同的性格。再则，叙事长诗易致平直，此诗却写得曲折有致，扣人心弦，因此令人读来不觉其长，不愧为“长篇之圣”。尤其是诗通过刘兰芝和焦母、焦仲卿和母亲、兰芝与刘兄这三对连续不断的矛盾，描叙人物性格之间的冲突，把普遍存在于当时社会中的矛盾现象集中概括，驱遣笔端，从而通过一个家庭，反映一个社会，使这首诗成为复杂社会的写真。这又是当时其他叙事诗所无法企及的。\n\n　　三、语言通俗化、个性化，明白如话而又神情毕肖。这首诗描摹情态，铺叙事物，全都通俗易懂。尤其是人物的对话，真实而又贴切地反映出人物的性格与心理活动。刘兰芝与焦仲卿之间的对话，显现了他们之间的恩爱和为了共同的理想而进行抗争的性格；仲卿母子的对话，既写出了焦母对儿子的爱，又写出了她对新妇的恨；兰芝母女、兄妹的对话，令人看到了母亲对女儿所特有的感情和刘兄的刻薄势利之心。清代陈祚明曰：此诗“佳处在历述十许人口中语，各各肖其声情，神化之笔也”，这的确说出了《孔雀东南飞》的语言艺术所达到的高水平。', poem_tags = '高中文言文,乐府,民谣,写人,爱情' WHERE poem_title = '孔雀东南飞 / 古诗为焦仲卿妻作' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '三国鼎立你建立了盖世功绩，创八阵图你成就了永久声名。\n江水东流推不转你布阵石头，千古遗恨你灭吴失策功未就。', poem_notes = '八阵图：由八种阵势组成的图形，用来操练军队或作战。\n盖：超过。三分国：指三国时魏、蜀、吴三国。\n石不转：指涨水时，八阵图的石块仍然不动。\n失吞吴：是吞吴失策的意思。', poem_appreciation = '“功盖三分国，名成八阵图“两句赞颂诸葛亮的丰功伟绩。第一句是从总的方面写，说诸葛亮在确立魏蜀吴三分天下、鼎足而立局势的过程中，功绩最为卓绝。三国并存局面的形成，固然有许多因素，而诸葛亮辅助刘备从无到有地创建蜀国基业，应该说就是重要原因之一。杜甫这一高度概括的赞语，客观地反映了三国时代的历史真实。第二句是从具体的方面来写，说诸葛亮创制八阵图使他声名更加卓著。对这一点古人曾屡加称颂，如成都武侯祠中的碑刻就写道：“一统经纶志未酬，布阵有图诚妙略。”“江上阵图犹布列，蜀中相业有辉光。”而杜甫的这句诗则是更集中、更凝炼地赞颂了诸葛亮的军事业绩。\n\n　　头两句诗在写法上用的是对仗句，“三分国”对“八阵图”，以全局性的业绩对军事上的贡献，显得精巧工整，自然妥帖。在结构上，前句劈头提起，开门见山；后句点出诗题，进一步赞颂功绩，同时又为下面凭吊遗迹作了铺垫。\n\n　　“江流石不转，遗恨失吞吴。”这两句就“八阵图”的遗址抒发感慨。“八阵图”遗址在夔州西南永安宫前平沙上。据《荆州图副》和刘禹锡《嘉话录》记载，这里的八阵图聚细石成堆，高五尺，六十围，纵横棋布，排列为六十四堆，始终保持原来的样子不变，即使被夏天大水冲击淹没，等到冬季水落平川，万物都失故态，唯独八阵图的石堆却依然如旧，六百年来岿然不动。前一句极精炼地写出了遗迹这一富有神奇色彩的特征。“石不转”，化用了《诗经·国风·邶风·柏舟》中的诗句“我心匪石，不可转也”。在作者看来，这种神奇色彩和诸葛亮的精神心志有内在的联系：他对蜀汉政权和统一大业忠贞不二，矢志不移，如磐石之不可动摇。同时，这散而复聚、长年不变的八阵图石堆的存在，似乎又是诸葛亮对自己赍志以殁表示惋惜、遗憾的象征，所以杜甫紧接着写的最后一句是“遗恨失吞吴”，说刘备吞吴失计，破坏了诸葛亮联吴抗曹的根本策略，以致统一大业中途夭折，而成了千古遗恨。\n\n　　当然，这首诗与其说是在写诸葛亮的“遗恨”，无宁说是杜甫在为诸葛亮惋惜，并在这种惋惜之中渗透了杜甫“伤己垂暮无成”（黄生语）的抑郁情怀。\n\n　　这首怀古绝句，具有融议论入诗的特点。但这种议论并不空洞抽象，而是语言生动形象，抒情色彩浓郁。诗人把怀古和述怀融为一体，浑然不分，给人一种此恨绵绵、余意不尽的感觉。', poem_tags = '唐诗三百首,怀古,写人,哲理' WHERE poem_title = '八阵图' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '长相思呵长相思，我们相思在长安，\n秋天蟋蟀常悲鸣，声声出自金井阑。\n薄霜凄凄送寒气，竹席已觉生凉寒；\n夜里想她魂欲断，孤灯伴我昏暗暗。\n卷起窗帘望明月，对月徒然独长叹；\n如花似玉美人呵，仿佛相隔在云端！\n青青冥冥呵，上是无边无垠的蓝天，\n清水渺渺呵，下是浩浩汤汤的波澜。\n天长长来地迢迢，灵魂飞越多辛苦；\n关山重重相阻隔，梦魂相见也艰难。\n长相思呵长相思，每每相思摧心肝！\n\n注解\n1、长安：今陕西省西安市。\n2、络纬：昆虫名，又名莎鸡，俗称纺织娘。\n3、金井阑：精美的井阑。\n4、簟色寒：指竹席的凉意。簟，凉席。\n5、帷：窗帘。\n6、青冥：青云。\n7、渌水：清水。\n8、关山难：关山难渡。\n9、摧：伤。▲', poem_tags = '唐诗三百首,乐府,思念,伤怀' WHERE poem_title = '长相思·其一' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '杭州地理位置重要，风景优美，是三吴的都会。这里自古以来就十分繁华。如烟的柳树、彩绘的桥梁，挡风的帘子、翠绿的帐幕，楼阁高高低低，大约有十万户人家。高耸入云的大树环绕着钱塘江沙堤，澎湃的潮水卷起霜雪一样白的浪花，宽广的江面一望无涯。市场上陈列着琳琅满目的珠玉珍宝，家家户户都存满了绫罗绸缎，争相比奢华。\n　　里湖、外湖与重重叠叠的山岭非常清秀美丽。秋天桂花飘香，夏季十里荷花。晴天欢快地吹奏羌笛，夜晚划船采菱唱歌，钓鱼的老翁、采莲的姑娘都嬉笑颜开。千名骑兵簇拥着巡察归来的长官。在微醺中听着箫鼓管弦，吟诗作词，赞赏着美丽的水色山光。他日把这美好的景致描绘出来，回京升官时向朝中的人们夸耀。', poem_notes = '三吴：即吴兴（今浙江省湖州市）、吴郡（今江苏省苏州市）、会稽（今浙江省绍兴市）三郡，在这里泛指今江苏南部和浙江的部分地区。\n钱塘：即今浙江杭州，古时候的吴国的一个郡。\n烟柳：雾气笼罩着的柳树。\n画桥：装饰华美的桥。\n风帘：挡风用的帘子。\n翠幕：青绿色的帷幕。\n参差：参音此跟反，差音此衣反。近似；高下不齐貌。\n云树：树木如云，极言其多。\n怒涛卷霜雪：又高又急的潮头冲过来，浪花像霜雪在滚动。\n天堑：天然沟壑，人间险阻。一般指长江，这里借指钱塘江。\n珠玑：珠是珍珠，玑是一种不圆的珠子。这里泛指珍贵的商品。\n重湖：以白堤为界，西湖分为里湖和外湖，所以也叫重湖。巘（yǎn）：大山上之小山。\n叠巘：层层叠叠的山峦。此指西湖周围的山。巘：小山峰。\n清嘉：清秀佳丽。\n三秋：①秋季，亦指秋季第三月，即农历九月。王勃《滕王阁序》有“时维九月，序属三秋”。柳永《望海潮》有“三秋桂子，十里荷花”。②三季，即九月。《诗经·王风·采葛》有“一日不见，如三秋兮！”孔颖达疏“年有四时，时皆三月。三秋谓九月也。设言三春、三夏其义亦同，作者取其韵耳”。亦指三年。李白《江夏行》有“只言期一载，谁谓历三秋！”\n羌管（qiāng）：即羌笛，羌族之簧管乐器。这里泛指乐器。弄：吹奏。\n菱歌泛夜：采菱夜归的船上一片歌声。菱：菱角。泛：漂流。\n高牙：高矗之牙旗。牙旗，将军之旌，竿上以象牙饰之，故云牙旗。这里指高官孙何。\n吟赏烟霞：歌咏和观赏湖光山色。烟霞：此指山水林泉等自然景色。\n异日图将好景：有朝一日把这番景致描绘出来。异日：他日，指日后。图：描绘。\n凤池：全称凤凰池，原指皇宫禁苑中的池沼。此处指朝廷。', poem_appreciation = '《望海潮》这一词牌名是柳永创制的，大概取意于杭州是观潮胜地。\n\n　　钱塘江畔的杭州自古就是著名的大都市，风景秀丽，人文荟萃，经济繁荣，生活富足。在这首词里，柳永以生动的笔墨，把杭州描绘得富丽非凡。\n\n　　“东南形胜，三吴都会”，起笔便大开大阔，直起直落。两个四字对句，气势博大，力量非凡。“东南”，就方向言；“三吴”，就地点言。交代地理位置空间浩瀚、面积广大，给人以开阔之感，引起人的阅读期待：是何处如此占尽天时地利？下句紧接着作了回答：“钱塘自古繁华。”“自古”突出了杭州历史悠久，繁华富庶。\n\n　　接下来，词人如数家珍般一一细数杭州的自然风光、人文景观。以下三句分别就首句中的“都会”、“形胜”、“繁华”，作出形象的说明。“烟柳画桥，风帘翠幕，参差十万人家。”远望去，垂柳含烟，薄雾如纱，虹桥似画，真是画中才有的好景致啊。这一处人烟阜盛，各式建筑，各抱地势，鳞次栉比，檐牙错落；走近了看，微风过处，千门万户帘幕轻摆，显得怡然安详，真是一派“都会”景象。“参差”形容楼阁高下不齐，“十万”指人口众多，未必是确数。“云树绕堤沙，怒涛卷霜雪，天堑无涯。”视线从城内转到钱塘江边，来写“形胜”。高耸入云的古树围绕着江堤，汹涌的江涛象发了怒一样奔腾而来，激起如霜如雪的白色浪花，壮阔的钱塘江就象一道天然的壕沟阻挡着北方敌人的进犯。一“绕”字尽显古树成行，长堤迤逦之态，一“卷”字又状狂涛汹涌，波浪滔滔之势。“市列珠玑，户盈罗绮，竞豪奢。”镜头移近，来街市上走走看看。珠玉宝石遍陈于市，家家户户绫罗盈柜，人们的衣饰更是鲜丽豪华，竞相斗艳。“列”、“盈”、“竞”把经济繁荣、生活富庶奢华落到了实处。\n\n　　杭州之美在西湖，西湖之美在景美，更在人美。“重湖叠巘清嘉，有三秋桂子，十里荷花。”湖外有湖，山外有山，西湖的锦山秀水实在是清丽可嘉；更美的是“三秋桂子，十里荷花”，堪称千古丽句。“三秋”意指桂花花期长，馥郁芬芳，长久不散；“十里”是说湖中广植荷花，逢到花期真可谓“接天莲叶无穷碧，映日荷花别样红”了。一句牵出了诸多意象，湖、山、秋月、桂花、荷花奔赴而来，令人心旷神怡，遐想万千。“三秋桂子”就让人联想起有关西湖的美丽传说。传说西湖灵隐寺和天竺寺，每到中秋，常常有带露的桂子从天飘落，馨香异常，那是从月宫桂树上飘落下来的，是寂寞的嫦娥赠与人间有心人的。因此宋之问《灵隐寺》中写道：“桂子月中落，天香云外飘。”白居易《忆江南》中也有“山寺月中寻桂子”。美丽的传说给秀丽的西湖增添了神秘空灵的色彩。“羌管弄晴，菱歌泛夜”两句为互文，即羌管弄晴、泛夜，菱歌泛夜、弄晴。意谓笛声歌声昼夜不停，在晴空中飘扬，在月夜下荡漾。“弄”使得吹笛人和采菱女的潇洒欢快之情陡增；“泛”说明人们是在湖中吹笛演唱，笛声歌声似乎随着湖水荡漾开来，轻盈愉悦之貌全出。“嬉嬉钓叟莲娃”，湖边钓鱼的老翁怡然自得，湖中采莲的孩童喧闹嬉戏。一句话就给我们展开了一幅太平盛世下的百姓安乐图。\n\n　　“千骑拥高牙，乘醉听箫鼓，吟赏烟霞。”权贵出行气派威风，真有一呼百应之势。闲暇时，品酒赏音，吟诗作画，赏玩山水，何等风流潇洒。“异日图将好景，归去凤池夸。”至此，才彰显了写作目的是拜谒孙何。“异日”“归去凤池”是对孙何宦途前景的美好祝愿，而这“好景”足以向朝廷中人“夸”，又使这祝愿归结到了对壮美秀丽的杭州的赞美上。虽然投赠之词恭维、夸张在所难免，但西湖的山水人家已经为自己作了明证，不信就请到杭州来眼见为实吧！', poem_tags = '宋词三百首,景点,写景,生活' WHERE poem_title = '望海潮·东南形胜' AND poem_author = '柳永';
UPDATE edu_poem SET poem_translation = '憨厚农家小伙子，怀抱布匹来换丝。其实不是真换丝，找个机会谈婚事。送郎送过淇水西，到了顿丘情依依。不是我愿误佳期，你无媒人失礼仪。望郎休要发脾气，秋天到了来迎娶。\n\n爬上那垛破土墙，遥向复关凝神望。复关远在云雾中，不见情郎泪千行。情郎即从复关来，又说又笑喜洋洋。你去卜卦求神仙，没有凶兆心欢畅。赶着你的车子来，为我搬运好嫁妆。\n\n桑树叶子未落时，缀满枝头绿萋萋。嘘嘘那些斑鸠儿，别把桑葚吃嘴里。哎呀年轻姑娘们，别对男人情依依。男人若是恋上你，要丢便丢太容易。女人若是恋男子，要想解脱难挣离。\n\n桑树叶子落下了，枯黄憔悴任飘摇。自从嫁到你家来，三年穷苦受煎熬。淇水茫茫送我归，水溅车帷湿又潮。我做妻子没差错，是你男人太奸刁。反覆无常没准则，变心缺德耍花招。\n\n婚后多年守妇道，繁重家务不辞劳。起早睡晚不嫌苦，忙里忙外非一朝。谁知家业已成后，渐渐对我施凶暴。兄弟不知我处境，个个见我哈哈笑。静下心来细细想，独自伤神泪暗抛。\n\n当年发誓偕白头，如今未老心先忧。淇水滔滔终有岸，沼泽虽宽有尽头。回想少时多欢乐，谈笑之间露温柔。海誓山盟犹在耳，哪料反目竞成仇。莫再回想背盟事，既已终结便罢休！', poem_notes = '氓：《说文》“氓，民也。”本义为外来的百姓，这里指自彼来此之民，男子之代称。蚩（chī）蚩：通“嗤嗤”，笑嘻嘻的样子。一说憨厚、老实的样子。\n贸：交易。抱布贸丝是以物易物。\n“匪来”二句：是说那人并非真来买丝，是找我商量事情来了。所商量的事情就是结婚。匪：通“非”，读为“fěi”。即：走近，靠近。谋：商量。古音咪（mī）。\n淇：卫国河名。今河南淇河。\n顿丘：地名。今河南清丰。丘：古读如“欺”。\n愆（qiān）：过失，过错，这里指延误。这句是说并非我要拖延约定的婚期而不肯嫁，是因为你没有找好媒人。\n将（qiāng）：愿，请。无：通“毋”，不要。\n乘：登上。垝（guǐ）垣（yuán）：倒塌的墙壁。垝，倒塌。垣，墙壁。\n复关：①复，返。关：在往来要道所设的关卡。女望男到期来会。他来时一定要经过关门。一说“复”是关名。 ②复关：卫国地名，指“氓”所居之地。\n涕：眼泪；涟涟：涕泪下流貌。她初时不见彼氓回到关门来，以为他负约不来了，因而伤心泪下。\n载（zaì）：动词词头，无义。\n尔卜尔筮（shì）：烧灼龟甲的裂纹以判吉凶，叫做“卜”。用蓍（shī）草占卦叫做“筮”。体：指龟兆和卦兆，即卜筮的结果。\n咎（jiù）：不吉利，灾祸。无咎言：就是无凶卦。\n贿：财物，指嫁妆，妆奁（lián）。以上四句是说你从卜筮看一看吉凶吧，只要卜筮的结果好，你就打发车子来迎娶，并将嫁妆搬去。\n沃若：犹“沃然”，像水浸润过一样有光泽。以上二句以桑的茂盛时期比自己恋爱满足，生活美好的时期。\n于嗟鸠兮：于：通“吁”（xū）本义为表示惊怪、不然、感慨等，此处与嗟皆表感慨。鸠：斑鸠。传说斑鸠吃桑葚过多会醉。\n耽（dān）：迷恋，沉溺，贪乐太甚。\n说：通“脱”，解脱。\n陨（yǔn）：坠落，掉下。这里用黄叶落下比喻女子年老色衰。黄：变黄。其黄而陨：犹《裳裳者华》篇的“芸其黄矣”，芸也是黄色。\n徂（cú）：往；徂尔：嫁到你家。\n食贫：过贫穷的生活。\n汤（shāng）汤：水势浩大的样子。\n渐（jiān）：浸湿。帷（wéi）裳（cháng）：车旁的布幔。以上两句是说被弃逐后渡淇水而归。\n爽：差错。\n贰：“貣（tè）”的误字。“貣”就是“忒”，和“爽”同义。这里指爱情不专一。以上两句是说女方没有过失而男方行为不对。\n罔：无，没有；极：标准，准则。\n二三其德：在品德上三心二意，言行为前后不一致。\n靡室劳矣：言所有的家庭劳作一身担负无余。室劳：家务劳动。靡：无。\n“夙兴”二句：就是说起早睡迟，朝朝如此，不能计算了。夙：早。兴：起来。\n言既遂矣：“言”字为语助词，无义。既遂：就是《谷风》篇“既生既育”的意思，言愿望既然已经实现。\n咥（xì）：笑的样子。以上两句是说兄弟还不晓得我的遭遇，见面时都讥笑我啊。\n静言思之：静下心来好好地想一想，言：音节助词，无实义。\n躬自悼矣：自身独自伤心。躬，自身；悼，伤心。\n“及尔”二句：当初曾相约和你一同过到老，偕老之说徒然使我怨恨罢了。\n隰（xí）：低湿的地方；当作“湿”，水名，就是漯河，黄河的支流，流经卫国境内。泮（pàn）：通“畔”水边，边岸。以上二句承上文，以水流必有畔岸，喻凡事都有边际，而自己愁思无尽。言外之意，如果和这样的男人偕老，那就苦海无边了。\n总角：古代男女未成年时把头发扎成丫髻，称总角。这里指代少年时代。宴：快乐。\n晏晏（yàn）：欢乐，和悦的样子。\n旦旦：诚恳的样子。\n反：即“返”字。不思其反：不曾想过会违背誓言。\n反是不思：违反这些。是，指示代词，指代誓言。是重复上句的意思，变换句法为的是和下句叶韵。\n已：了结，终止。焉哉（古读如兹zī）：语气词连用，加强语气，表示感叹。末句等于说撇开算了罢！', poem_appreciation = '开头一、二章，《诗集传》云：“赋也。”具体描写男子向女主人公求婚以至结婚的过程。那是在一次集市上，一个男子以买丝为名，向女主人公吐露爱情，一会儿嬉皮笑脸，一会儿又发脾气，可谓软硬兼施。可是这位单纯的女子看不透他的本质，说是必须有人来说媒，最后将婚期订在秋天。从此以后，女子朝思暮想，“乘彼垝垣，以望复关”，望不到男子所住的复关，便泪流不止；既见复关，就像见到所恋之人，不禁眉开眼笑。她还打卦占卜，预测婚事的吉凶。及至男方派车前来迎娶，她就带着全部的财物，嫁了过去。这两章叙事真切，历历可见，而诗人作为一个纯情少女的自我形象，也刻画得栩栩如生。方玉润评这一段云：“不见则忧，既见则喜，夫情之所不容已者，女殆痴于情者耳。”（同上）一个“痴”字。点出了此女钟情之深。\n\n　　《诗集传》谓第三章“比而兴也”，第四章“兴也”，也就是说这两章以抒情为主，诗中皆以桑树起兴，从诗人的年轻貌美写到体衰色减，同时揭示了男子对她从热爱到厌弃的经过。“桑之未落，其叶沃若”，以桑叶之润泽有光，比喻女子的容颜亮丽。“桑之落矣，其黄而陨”，以桑叶的枯黄飘落，比喻女子的憔悴和被弃。“于嗟鸠兮，无食桑葚；于嗟女兮，无与士耽”，则以“戒鸠无食桑葚以兴下句戒女无与士耽也”（《诗集传》）。桑葚是甜的，鸠多食则易致醉；爱情是美好的，人多迷恋则易上当受骗。男人沉溺于爱情犹可解脱。女子一旦堕入爱河，则无法挣离。这是多么沉痛的语言！从桑叶青青到桑叶黄落，不仅显示了女子年龄的由盛到衰，而且暗示了时光的推移。“自我徂尔，三岁食贫”，一般以为女子嫁过去三年，但另有一种解释：“三岁，多年。按‘三’是虚数，言其多，不是实指三年。”（程俊英《诗经译注》）实际上是说女子嫁过去好几年，夫妻关系渐渐不和，终至破裂。女子不得已又坐着车子，渡过淇水，回到娘家。她反覆考虑，自己并无一点差错，而是那个男子“二三其德”。在这里女子以反省的口气回顾了婚后的生活，找寻被遗弃的原因，结果得到了一条教训：在以男子为中心的社会里，只有痴心女子负心汉。\n\n　　诗之五章用赋的手法叙述被弃前后的处境，前六句承上章“自我徂尔，三岁食贫”，补叙多年为妇的苦楚，她起早睡晚，辛勤劳作，一旦日子好过一些，丈夫便变得暴戾残酷。这个“暴”字可使人想像到丈夫的狰狞面目，以及女主人公被虐待的情景。后四句写她回到娘家以后受到兄弟们的冷笑。《诗集传》释此段云：“盖淫奔从人，不为兄弟所齿，故其见弃而归，亦不为兄弟所恤，理固有必然者，亦何所归咎哉，但自痛悼而已。”说女主人公“淫奔”，固不足取；但其他的话可以帮助读者理解她当时所受到的精神压力和由此而产生的内心矛盾。\n\n　　第六章赋兼比兴，在抒情中叙事，当初他们相恋时，有说有笑；男子则“信誓旦旦”，表示白头偕老。可是他还未老时就产生怨恨，而且无法挽回。这里用了两个比喻：浩浩汤汤的淇水，总有堤岸；广阔连绵的沼泽，也有边际。言外之意是：我的痛苦为什么竟没有到头的时候？《诗集传》指出“此则兴也”，其实它是比中有兴。诗人运用这两个比喻，强烈地抒发了一腔怨愤，诉说了弃妇无边无际的痛苦。为了摆脱这些痛苦，她下决心与那男子割断感情上的联系：“反是不思，亦已焉哉！”从此后不再希望他回心转意，算了，算了。然而她果真能做到吗？方玉润认为：“虽然口纵言已，心岂能忘？”（《诗经原始》）是的，从这女子一贯钟情的性格来看，她对男子不可能在感情上一刀两断，这就是今天常说的悲剧性格。', poem_tags = '诗经,叙事,闺怨,民谣,分手' WHERE poem_title = '氓' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '永州的野外出产一种奇特的蛇，（它有着）黑色的底子白色的花纹；如果这种蛇碰到草木,草木全都干枯而死；如果蛇用牙齿咬人，没有能够抵挡（蛇毒）的方法。然而捉到后晾干把它用来作成药饵，可以用来治愈大风、挛踠、瘘、疠，去除死肉，杀死人体内的寄生虫。起初，太医用皇帝的命令征集这种蛇，每年征收这种蛇两次，招募能够捕捉这种蛇的人，充抵他的赋税缴纳。永州的人都争着去做（捕蛇）这件事。\n\n　　有个姓蒋的人家，享有这种（捕蛇而不纳税的）好处已经三代了。我问他，他却说：“我的祖父死在捕蛇这件差事上，我父亲也死在这件事情上。现在我继承祖业干这差事也已十二年了，险些丧命也有好几次了。”他说这番话时，脸上好像很忧伤的样子。\n\n　　我很同情他，并且说：“你怨恨这差事吗？我打算告诉管理政事的地方官，让他更换你的差事，恢复你的赋税，那怎么样？”\n\n　　蒋氏(听了),更加悲伤，满眼含泪地说：“你要哀怜我，使我活下去吗？然而我干这差事的不幸，还比不上恢复我缴纳赋税的不幸那么厉害呀。（假使）从前我不当这个差，那我就早已困苦不堪了。自从我家三代住到这个地方，累计到现在，已经六十年了，可乡邻们的生活一天天地窘迫，把他们土地上生产出来的都拿去，把他们家里的收入也尽数拿去(交租税仍不够)，只得号啕痛哭辗转逃亡，又饥又渴倒在地上，(一路上)顶着狂风暴雨，冒着严寒酷暑，呼吸着带毒的疫气，一个接一个死去,处处死人互相压着。从前和我祖父同住在这里的，现在十户当中剩不下一户了；和我父亲住在一起的人家，现在十户当中只有不到两三户了；和我一起住了十二年的人家，现在十户当中只有不到四五户了。那些人家不是死了就是迁走了。 可是我却凭借捕蛇这个差事才唯独存活了下来。凶暴的官吏来到我乡，到处吵嚷叫嚣，到处骚扰，那种喧闹叫嚷着惊扰乡民的气势，（不要说人）即使鸡狗也不能够安宁啊！我就小心翼翼地起来，看看我的瓦罐，我的蛇还在，就放心地躺下了。我小心地喂养蛇，到规定的日子把它献上去。回家后有滋有味地吃着田地里出产的东西，来度过我的余年。估计一年当中冒死的情况只是两次,其余时间我都可以快快乐乐地过日子。哪像我的乡邻们那样天天都有死亡的威胁呢！现在我即使死在这差事上，与我的乡邻相比，我已经死在（他们）后面了，又怎么敢怨恨（捕蛇这件事）呢？”\n\n　　我听了(蒋氏的诉说)越听越悲伤。孔子说：“苛酷的统治比老虎还要凶暴啊!”我曾经怀疑过这句话，现在根据蒋氏的遭遇来看这句话，还真是可信的。唉！谁知道苛捐杂税的毒害比这种毒蛇的毒害更厉害呢！所以（我）写了这篇“说”,以期待那些朝廷派出的用来考察民情的人得到它。', poem_notes = '之：的。\n野：郊外。\n产：生产。\n异：奇特的。\n章，花纹。\n触：碰。\n尽：全。\n以：假设连词，如果。\n啮：咬。\n御：抵挡。\n之：代词，指被毒蛇咬后的伤毒。\n然得而腊之：然，但。得，抓住。而，表顺接。之，它，代永州的异蛇。\n腊（xī）：干肉，这里作动词用，指把蛇肉晾干。\n以为饵：以，用来。为，作为。饵，糕饼，这里指药饵。即药引子\n可以：可以用来。可，可以。以，用来。\n已：止，治愈。\n去死肌：去除腐肉。去，去除。死肌，死肉，腐肉。\n三虫：泛指人体内的寄生虫。\n其始：其，助词，不译。始：刚开始。\n太医以王命聚之：以，用。命：命令。聚，征集。之：这种蛇，指永州异蛇。\n岁赋其二：岁，每年。赋，征收、敛取。其，这种蛇，指永州异蛇。二，两次\n募：招收。\n者：……的人。\n当其租入：（允许用蛇）抵他的税收。当，抵。\n奔走：指忙着做某件事。\n焉：兼词，于之，在捕蛇这件事上。也可理解为——语气词兼代词。\n专其利：独占这种（捕蛇而不用交税的）好处。\n则：却。\n死于是：死在（捕蛇）这件事上。\n今：现在。\n嗣：继承。\n数：几次\n为之：做捕蛇这件事。\n几(jī):几乎,差点儿.\n几死者：几乎要被蛇咬死的情况。\n数：多次。\n言之：之，音节助词，无实义。\n貌若甚戚者：表情好像非常忧伤的样子。戚，忧伤。\n余悲之：我同情他。\n且：并且。\n若毒之乎：你怨恨（捕蛇）这件事吗。\n将：打算。\n于：向。\n莅事者：管理政事的人，指地方官。莅事：视事 ，处理公务。\n更若役：更换你的差事。役：差事。\n复：恢复。赋：赋税。\n则何如：那么怎么样。\n大：非常。\n汪然：满眼含泪的样子。\n涕：眼泪。\n生：使……活下去。\n斯：此，这。\n若：、比得上。、好像、你\n甚：那么。\n向：从前。\n为：做。\n病：困苦不堪。\n自：自从。\n居：居住。\n积于今：算到现在。积，一年一年累积起来。\n生：生活。\n日：一天天。\n蹙：窘迫。\n徙：迁移。\n殚：尽，竭尽。\n竭：尽。\n庐：简陋的房屋。\n顿踣：（劳累地）跌倒在地上。\n犯：冒。\n疠：这里指疫气。\n曩 ：从前。\n其室：他们的家。\n非…则…：不是…就是…。\n尔：用于句尾，表示限制的语气。\n嚣：叫喊。\n隳突：冲撞毁坏。\n骇：使人害怕。\n虽：即使。\n恂恂：小心谨慎的样子。\n缶：瓦罐。\n弛然：放心的样子。\n之：指代蛇。\n时：到（规定献蛇的）时候。\n退：回来。\n甘：有味地。\n有：生产出来的东西。\n齿：年龄。\n盖：用于句首，带有估计的语气。\n犯：冒着。\n熙熙：快乐的样子。\n旦旦：天天。\n毒：怨恨。\n是：这，指冒死亡的危险。\n苛：苛刻。\n乎：相当“于”，对.\n于：比。\n故：所以。\n以：用来。\n俟：等待，这里有希望的意思。\n大风：麻风病\n人风：即民风。唐代为了避李世民的讳，用“人”字代“民”字。\n汪：汪汪，形容眼泪多。\n貌：脸色。\n质：质地。', poem_appreciation = '《捕蛇者说》主题思想即赋敛之毒有甚于蛇毒\n\n　　柳宗元生活于唐王朝由盛到衰的时代，经过了“安史之乱”，社会各种矛盾异常尖锐复杂。统治者为了筹措军费和满足个人挥霍，加紧了对人民的横征暴敛，增加盐税、间架税（房税）、货物税等。\n\n　　由于税上加税，“故农人日困，末业日增”，“愁怨之声，盈于远近”。大批农民纷纷逃亡，社会生产日益凋蔽。贞元二十一年亦即永贞元年（公元805年），唐顺宗李诵即位，王叔文被重用。\n\n　　柳宗元二十九岁作监察御史在京任职期间，就参加了以王叔文为首的进步知识分子的”政治集团“。王叔文受重用，柳宗元也被提升为礼部员外郎。王叔文，柳宗元等依靠顺宗的支持，着手改革弊政，减轻赋税，禁止宫市，释放宫女，惩办恶吏，选用贤臣。\n\n　　可是因为反对派的强烈反抗，这场革新运动仅进行了一百四十多天就以失败而告终。结果顺宗退位，王叔文被杀，柳宗元被贬为邵州刺史，他又改贬为永州司马。《捕蛇者说》就是柳宗元谪居永州时写的。柳宗元被贬之后，仍然坚持他革新政治的主张，他曾说“虽万受摈弃，不更乎内”，因此仍极不满于唐王朝的重赋繁税，希望减轻人民负担。柳宗元被贬谪后，与下层人民有所接触，对民间疾苦有所了解，且看到“永州之野产异蛇”，听到“有蒋氏者，专其利三世矣”之类的事迹，因此能以进步的政治观点为指导，为实际生活为素材加以构思。\n\n　　柳宗元写《捕蛇者说》，旨在说明“ 赋敛之毒有甚于蛇毒” 。文本借事明道，溶理于事，因事说理，以蛇毒与赋毒相对举而成文。', poem_tags = '古文观止,生活,赋税' WHERE poem_title = '捕蛇者说' AND poem_author = '柳宗元';
UPDATE edu_poem SET poem_translation = '自从河南地区经历战乱，关内一带漕运受阻致使饥荒四起，我们兄弟也因此流离失散，各自在一处。因为看到月亮而有所感触，便随性写成诗一首来记录感想，寄给在浮梁的大哥、在於潜的七哥，在乌江的十五哥和在符离、下邽的弟弟妹妹们看。\n\n家业在灾年中荡然一空，兄弟分散各自你西我东。\n战乱过后田园荒芜寥落，骨肉逃散在异乡道路中。\n吊影伤情好像离群孤雁，漂泊无踪如断根的秋蓬。\n同看明月都该伤心落泪，一夜思乡心情五地相同。', poem_notes = '河南：唐时河南道，辖今河南省大部和山东、江苏、安徽三省的部分地区。\n关内：关内道，辖今陕西大部及甘肃、宁夏、内蒙的部分地区。\n阻饥：遭受饥荒等困难。\n浮梁大兄：白居易的长兄白幼文，贞元十四、五年（798—799年）间任饶州浮梁（今属江西景德镇）主簿。\n於潜七兄：白居易叔父白季康的长子，时为於潜（今浙江临安县）县尉。\n乌江十五兄：白居易的从兄白逸，时任乌江（今安徽和县）主簿。\n符离：在今安徽宿县内。白居易的父亲在彭城（今江苏徐州）作官多年，就把家安置在符离。\n下邽：县名，治所在今陕西省渭南县。白氏祖居曾在此。\n时难年荒：指遭受战乱和灾荒。荒，一作“饥”。\n世业：祖传的产业。唐代初年推行授田制度，所授之田分“口分田”和“世业田”，人死后，子孙可以继承“世业田”。\n羁旅：漂泊流浪。\n寥落：荒芜零落。\n干戈：古代两种兵器，此代指战争。\n吊影：一个人孤身独处，形影相伴，没有伴侣。\n千里雁：比喻兄弟们相隔千里，皆如孤雁离群。\n辞根：草木离开根部，比喻兄弟们各自背井离乡。\n九秋蓬：深秋时节随风飘转的蓬草，古人用来比喻游子在异乡漂泊。九秋，秋天。\n乡心：思亲恋乡之心。\n五处：即诗题所言五处。', poem_appreciation = '这是一首感情浓郁的抒情诗。全诗意在写经乱之后，怀念诸位兄弟姊妹。\n\n　　此诗读来如听诗人倾诉自己身受的离乱之苦。在这战乱饥馑灾难深重的年代里，祖传的家业荡然一空，兄弟姊妹抛家失业，羁旅行役，天各一方。回首兵燹后的故乡田园，一片寥落凄清。破敝的园舍虽在，可是流离失散的同胞骨肉，却各自奔波在异乡的道路之中。诗的前两联就是从“时难年荒”这一时代的灾难起笔，以亲身经历概括出战乱频年、家园荒残、手足离散这一具有典型意义的苦难的现实生活。接着诗人再以“雁”、“蓬”作比：手足离散各在一方，犹如那分飞千里的孤雁，只能吊影自怜；辞别故乡流离四方，又多么像深秋中断根的蓬草，随着萧瑟的西风，飞空而去，飘转无定。“吊影分为千里雁，辞根散作九秋蓬”两句，一向为人们所传诵。诗人不仅以千里孤雁、九秋断蓬作了形象贴切的比拟，而且以吊影分飞与辞根离散这样传神的描述，赋予它们孤苦凄惶的情态，深刻揭示了饱经战乱的零落之苦。孤单的诗人凄惶中夜深难寐，举首遥望孤悬夜空的明月，情不自禁联想到飘散在各地的兄长弟妹们。他想：如果此时大家都在举目遥望这轮勾引无限乡思的明月，也会和自己一样潸潸泪垂吧！恐怕这一夜之中，流散五处深切思念家园的心，也都会是相同的。诗人在这里以绵邈真挚的诗思，构出一幅五地望月共生乡愁的图景，从而收结全诗，创造出浑朴真淳、引人共鸣的艺术境界。\n\n　　全诗以白描的手法，采用平易的家常话语，抒写人们所共有而又不是人人俱能道出的真实情感。清刘熙载在《艺概》中说：“常语易，奇语难，此诗之初关也。奇语易，常语难，此诗之重关也。香山常得奇，此境良非易到。”白居易的这首诗不用典故，不事藻绘，语言浅白平实而又意蕴精深，情韵动人，堪称“用常得奇”的佳作。', poem_tags = '唐诗三百首,初中古诗,望月,抒情,思乡' WHERE poem_title = '望月有感' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '海外来客们谈起瀛洲，烟波渺茫实在难以寻求。\n越中来人说起天姥山，在云雾忽明忽暗间有人可以看见。\n天姥山仿佛连接着天遮断了天空。山势高峻超过五岳，遮掩过赤城山。\n天台山虽高四万八千丈，面对着它好像要向东南倾斜拜倒一样。\n我根据越人说的话梦游到吴越，一天夜晚飞渡过明月映照下的镜湖。\n镜湖上的月光照着我的影子，一直伴随我到了剡溪。\n谢灵运住的地方如今还在，清澈的湖水荡漾，猿猴清啼。\n我脚上穿着谢公当年特制的木鞋，攀登直上云霄的山路。\n上到半山腰就看见了从海上升起的太阳，在半空中传来天鸡报晓的叫声。\n无数山岩重叠，道路盘旋弯曲，方向不定，迷恋着花，依倚着石头，不觉天色已经晚了。\n熊在怒吼，龙在长鸣，岩中的泉水在震响，使森林战栗，使山峰惊颤。\n云层黑沉沉的，像是要下雨，水波动荡生起了烟雾。\n电光闪闪，雷声轰鸣，山峰好像要被崩塌似的。\n仙府的石门，訇的一声从中间打开。\n洞中蔚蓝的天空广阔无际，看不到尽头，日月照耀着金银做的宫阙。\n用彩虹做衣裳，将风作为马来乘，云中的神仙们纷纷下来。\n老虎弹奏着琴瑟，鸾鸟驾着车。仙人们成群结队密密如麻。\n忽然魂魄惊动，我猛然惊醒，不禁长声叹息。\n醒来时只有身边的枕席，刚才梦中所见的烟雾云霞全都消失了。\n人世间的欢乐也是像梦中的幻境这样，自古以来万事都像东流的水一样一去不复返。\n告别诸位朋友远去（东鲁）啊，什么时候才能回来？暂且把白鹿放牧在青崖间，等到要远行时就骑上它访名山。\n岂能卑躬屈膝去侍奉权贵，使我不能有舒心畅意的笑颜！', poem_notes = '天姥山：在浙江新昌东面。传说登山的人能听到仙人天姥唱歌的声音，山因此得名。\n瀛洲：古代传说中的东海三座仙山之一（另两座叫蓬莱和方丈）。烟涛：波涛渺茫，远看像烟雾笼罩的样子。微茫：景象模糊不清。信：确实，实在。\n越人：指浙江一带的人。\n明灭：忽明忽暗。\n向天横：直插天空。横，直插。\n”势拔“句：山势高过五岳，遮掩了赤城。拔，超出。五岳，指东岳泰山、西岳华（huà）山、中岳嵩山、北岳恒山、南岳衡山。赤城，和下文的“天台（tāi）”都是山名，在今浙江天台北部。\n一万八千丈：一作“四万八千丈”。\n”对此“句：对着天姥这座山，天台山就好像要倒向它的东南一样。意思是天台山和天姥山相比，显得低多了。\n因：依据。之：指代前边越人的话。\n镜湖：又名鉴湖，在浙江绍兴南面。\n剡（shàn）溪：水名，在浙江嵊（shèng）州南面。\n谢公：指南朝诗人谢灵运。谢灵运喜欢游山。游天姥山时，他曾在剡溪这个地方住宿。\n渌（lù）：清。\n清：这里是凄清的意思。\n谢公屐（jī）：谢灵运穿的那种木屐。《南史·谢灵运传》记载：谢灵运游山，必到幽深高峻的地方；他备有一种特制的木屐，屐底装有活动的齿，上山时去掉前齿，下山时去掉后齿。木屐，以木板作底，上面有带子，形状像拖鞋。\n青云梯：指直上云霄的山路。\n半壁见海日：上到半山腰就看到从海上升起的太阳。\n天鸡：古代传说，东南有桃都山，山上有棵大树叫桃都，树枝绵延三千里，树上栖有天鸡，每当太阳初升，照到这棵树上，天鸡就叫起来，天下的鸡也都跟着它叫。\n”迷花“句：迷恋着花，依靠着石，不觉天色已经很晚了。暝（míng），日落，天黑。\n”熊咆“句：熊在怒吼，龙在长鸣，岩中的泉水在震响。“殷岩泉”即“岩泉殷”。殷，这里用作动词，震响。\n”栗深林“句：使深林战栗，使层巅震惊。栗、惊，使动用法。\n青青：黑沉沉的。\n澹澹：波浪起伏的样子。\n列缺：指闪电。\n洞天石扉，訇（hōng）然中开：仙府的石门，訇的一声从中间打开。洞天，仙人居住的洞府。扉，门扇。訇然，形容声音很大。\n青冥浩荡：青冥，指天空。浩荡，广阔远大的样子。\n金银台：金银铸成的宫阙，指神仙居住的地方。\n云之君：云里的神仙。\n鸾回车：鸾鸟驾着车。鸾，传说中的如凤凰一类的神鸟。回，旋转，运转。\n恍：恍然，猛然。\n觉时：醒时。\n失向来之烟霞：刚才梦中所见的烟雾云霞消失了。向来，原来。烟霞，指前面所写的仙境。\n东流水：像东流的水一样一去不复返。\n”且放“二句：暂且把白鹿放在青青的山崖间，等到要行走的时候就骑上它去访问名山。白鹿，传说神仙或隐士多骑白鹿。须，等待。\n摧眉折腰：低头弯腰。摧眉，即低眉。', poem_appreciation = '这是一首记梦诗，也是一首游仙诗。意境雄伟，变化惝恍莫测，缤纷多采的艺术形象，新奇的表现手法，向来为人传诵，被视为李白的代表作之一。\n\n　　这首诗的题目一作《别东鲁诸公》。其时李白虽然出翰林已有年月了，而政治上遭受挫折的愤怨仍然郁结于怀，所以在诗的最后发出那样激越的呼声。\n\n　　李白一生徜徉山水之间，热爱山水，达到梦寐以求的境地。此诗所描写的梦游，也许并非完全虚托，但无论是否虚托，梦游就更适于超脱现实，更便于发挥他的想象和夸张的才能了。\n\n　　“海客谈瀛洲，烟涛微茫信难求；越人语天姥，云霓明灭或可睹。”诗一开始先说古代传说中的海外仙境──瀛洲，虚无缥缈，不可寻求；而现实中的天姥山在浮云彩霓中时隐时现，真是胜似仙境。以虚衬实，突出了天姥胜景，暗蕴着诗人对天姥山的向往，写得富有神奇色彩，引人入胜。\n\n　　天姥山临近剡溪，传说登山的人听到过仙人天姥的歌唱，因此得名。天姥山与天台山相对，峰峦峭峙，仰望如在天表，冥茫如堕仙境，容易引起游者想入非非的幻觉。浙东山水是李白青年时代就向往的地方，初出川时曾说“此行不为鲈鱼鲙，自爱名山入剡中”。入翰林前曾不止一次往游，他对这里的山水不但非常热爱，也是非常熟悉的。\n\n　　天姥山号称奇绝，是越东灵秀之地。但比之其他崇山峻岭如我国的五大名山──五岳，在人们心目中的地位仍有小巫见大巫之别。可是李白却在诗中夸说它“势拔五岳掩赤城”，比五岳还更挺拔。有名的天台山则倾斜着如拜倒在天姥的足下一样。这个天姥山，被写得耸立天外，直插云霄，巍巍然非同凡比。这座梦中的天姥山，应该说是李白平生所经历的奇山峻岭的幻影，它是现实中的天姥山在李白笔下夸大了的影子。\n\n　　接着展现出的是一幅一幅瑰丽变幻的奇景：天姥山隐于云霓明灭之中，引起了诗人探求的想望。诗人进入了梦幻之中，仿佛在月夜清光的照射下，他飞渡过明镜一样的镜湖。明月把他的影子映照在镜湖之上，又送他降落在谢灵运当年曾经歇宿过的地方。他穿上谢灵运当年特制的木屐，登上谢公当年曾经攀登过的石径──青去梯。只见：“半壁见海日，空中闻天鸡。千岩万转路不定，迷花倚石忽已暝。熊咆龙吟殷岩泉，栗深林兮惊层巅。云青青兮欲雨，水澹澹兮生烟。”继飞渡而写山中所见，石径盘旋，深山中光线幽暗，看到海日升空，天鸡高唱，这本是一片曙色；却又于山花迷人、倚石暂憩之中，忽觉暮色降临，旦暮之变何其倏忽。暮色中熊咆龙吟，震响于山谷之间，深林为之战栗，层巅为之惊动。不止有生命的熊与龙以吟、咆表示情感，就连层巅、深林也能战栗、惊动，烟、水、青云都满含阴郁，与诗人的情感，协成一体，形成统一的氛围。前面是浪漫主义地描写天姥山，既高且奇；这里又是浪漫主义地抒情，既深且远。这奇异的境界，已经使人够惊骇的了，但诗人并未到此止步，而诗境却由奇异而转入荒唐，全诗也更进入高潮。在令人惊悚不已的幽深暮色之中，霎时间“丘峦崩摧”，一个神仙世界“訇然中开”，“青冥浩荡不见底，日月照耀金银台。霓为衣兮风为马，云之君兮纷纷而来下。”洞天福地，于此出现。“云之君”披彩虹为衣，驱长风为马，虎为之鼓瑟，鸾为之驾车，皆受命于诗人之笔，奔赴仙山的盛会来了。这是多么盛大而热烈的场面。“仙之人兮列如麻”！群仙好象列队迎接诗人的到来。金台、银台与日月交相辉映，景色壮丽，异彩缤纷，何等的惊心眩目，光耀夺人！仙山的盛会正是人世间生活的反映。这里除了有他长期漫游经历过的万壑千山的印象、古代传说、屈原诗歌的启发与影响，也有长安三年宫廷生活的迹印，这一切通过浪漫主义的非凡想象凝聚在一起，才有这般辉煌灿烂、气象万千的描绘。\n\n　　值得注意的是，这首诗写梦游奇境，不同于一般游仙诗，它感慨深沉，抗议激烈，并非真正依托于虚幻之中，而是在神仙世界虚无飘渺的描述中，依然着眼于现实。神游天上仙境，而心觉“世间行乐亦如此”。\n\n　　仙境倏忽消失，梦境旋亦破灭，诗人终于在惊悸中返回现实。梦境破灭后，人，不是随心所欲地轻飘飘地在梦幻中翱翔了，而是沉甸甸地躺在枕席之上。“古来万事东流水”，其中包含着诗人对人生的几多失意和深沉的感慨。此时此刻诗人感到最能抚慰心灵的是“且放白鹿青崖间，须行即骑访名山”。徜徉山水的乐趣，才是最快意的，也就是在《春夜宴从弟桃花园序》中所说：“古人秉烛夜游，良有以也。”本来诗意到此似乎已尽，可是最后却愤愤然加添了两句“安能摧眉折腰事权贵，使我不得开心颜！”一吐长安三年的郁闷之气。天外飞来之笔，点亮了全诗的主题：对于名山仙境的向往，是出之于对权贵的抗争，它唱出封建社会中多少怀才不遇的人的心声。在等级森严的封建社会中，多少人屈身权贵，多少人埋没无闻！唐朝比之其他朝代是比较开明的，较为重视人才，但也只是比较而言。人才在当时仍然摆脱不了“臣妾气态间”的屈辱地位。“折腰”一词出之于东晋的陶渊明，他由于不愿忍辱而赋“归去来”。李白虽然受帝王优宠，也不过是个词臣，在宫廷中所受到的屈辱，大约可以从这两句诗中得到一些消息。封建君主把自己称“天子”，君临天下，把自己升高到至高无上的地位，却抹煞了一切人的尊严。李白在这里所表示的决绝态度，是向封建统治者所投过去的一瞥蔑视。在封建社会，敢于这样想、敢于这样说的人并不多。李白说了，也做了，这是他异乎常人的伟大之处。\n\n　　这首诗的内容丰富、曲折、奇谲、多变，它的形象辉煌流丽，缤纷多彩，构成了全诗的浪漫主义华赡情调。它的主观意图本来在于宣扬“古来万事东流水”这样颇有消极意味的思想，可是它的格调却是昂扬振奋的，潇洒出尘的，有一种不卑不屈的气概流贯其间，并无消沉之感。', poem_tags = '唐诗三百首,高中古诗,古体,记梦' WHERE poem_title = '梦游天姥吟留别 / 梦游天姥山别东鲁诸公' AND poem_author = '李白';
UPDATE edu_poem SET poem_tags = '端午节,感叹,人生' WHERE poem_title = '端午日' AND poem_author = '殷尧藩';
UPDATE edu_poem SET poem_translation = '我年幼时就爱学习。因为家中贫穷，无法得到书来看，常向藏书的人家求借，亲手抄录，约定日期送还。天气酷寒时，砚池中的水冻成了坚冰，手指不能屈伸，我仍不放松读书。抄写完后，赶快送还人家，不敢稍稍超过约定的期限。因此人们大多肯将书借给我，我因而能够看各种各样的书。已经成年之后，更加仰慕圣贤的学说，又苦于不能与学识渊博的老师和名人交往，曾快步走（跑）到百里之外，手拿着经书向同乡前辈求教。前辈德高望重，门人学生挤满了他的房间，他的言辞和态度从未稍有委婉。我站着陪侍在他左右，提出疑难，询问道理，低身侧耳向他请教；有时遭到他的训斥，表情更为恭敬，礼貌更为周到，不敢答复一句话；等到他高兴时，就又向他请教。所以我虽然愚钝，最终还是得到不少教益。\n\n　　当我寻师时，背着书箱，趿拉着鞋子，行走在深山大谷之中，严冬寒风凛冽，大雪深达几尺，脚和皮肤受冻裂开都不知道。到学舍后，四肢僵硬不能动弹，仆人给我灌下热水，用被子围盖身上，过了很久才暖和过来。住在旅馆，我每天吃两顿饭，没有新鲜肥嫩的美味享受。同学舍的求学者都穿着锦绣衣服，戴着有红色帽带、饰有珍宝的帽子，腰间挂着白玉环，左边佩戴着刀，右边备有香囊，光彩鲜明，如同神人；我却穿着旧棉袍、破衣服处于他们之间，毫无羡慕的意思。因为心中有足以使自己高兴的事，并不觉得吃穿的享受不如人家。我的勤劳和艰辛大概就是这样。\n\n　　如今我虽已年老，没有什么成就，但所幸还得以置身于君子的行列中，承受着天子的恩宠荣耀，追随在公卿之后，每天陪侍着皇上，听候询问，天底下也不适当地称颂自己的姓名，更何况才能超过我的人呢？\n\n　　如今的学生们在太学中学习，朝廷每天供给膳食，父母每年都赠给冬天的皮衣和夏天的葛衣，没有冻饿的忧虑了；坐在大厦之下诵读经书，没有奔走的劳苦了；有司业和博士当他们的老师，没有询问而不告诉，求教而无所收获的了；凡是所应该具备的书籍，都集中在这里，不必再像我这样用手抄录，从别人处借来然后才能看到了。他们中如果学业有所不精通，品德有所未养成的，如果不是天赋、资质低下，就是用心不如我这样专一，难道可以说是别人的过错吗！\n\n　　东阳马生君则，在太学中已学习二年了，同辈人很称赞他的德行。我到京师朝见皇帝时，马生以同乡晚辈的身份拜见我，写了一封长信作为礼物，文辞很顺畅通达，同他论辩，言语温和而态度谦恭。他自己说少年时对于学习很用心、刻苦，这可以称作善于学习者吧！他将要回家拜见父母双亲，我特地将自己治学的艰难告诉他。如果说我勉励同乡努力学习，则是我的志意；如果诋毁我夸耀自己遭遇之好而在同乡前骄傲，难道是了解我吗？', poem_notes = '东阳：今浙江东阳县，当时与潜溪同属金华府。马生：姓马的太学生，即文中的马君则。序：文体名，有书序、赠序二种，本篇为赠序。\n致：得到。\n余：我。嗜（shì是）学：爱好读书。\n假借：借。\n弗之怠：即“弗怠之”，不懈怠，不放松读书。弗，不。之，指代抄书。\n走：跑，这里意为“赶快”。\n逾约：超过约定的期限。\n既：已经，到了。加冠：古代男子到二十岁时，举行加冠（束发戴帽）仪式，表示已成年。\n圣贤之道：指孔孟儒家的道统。宋濂是一个主张仁义道德的理学家，所以十分推崇它。\n硕（shuò朔）师：学问渊博的老师。游：交游。\n尝：曾。趋：奔赴。\n乡之先达：当地在道德学问上有名望的前辈。这里指浦江的柳贯、义乌的黄溍等古文家。执经叩问：携带经书去请教。\n稍降辞色：把言辞放委婉些，把脸色放温和些。辞色，言辞和脸色。\n援疑质理：提出疑难，询问道理。\n叱（chì赤）（咄duō夺）：训斥，呵责。\n俟（sì四）：等待。忻（xīn新）：同“欣”。\n卒：终于。\n箧（qiè窃）：箱子。曳（yè夜）屣（xǐ喜）：拖着鞋子。\n穷冬：隆冬。\n皲（jūn军）裂：皮肤因寒冷干燥而开裂。\n僵劲：僵硬。\n媵人：陪嫁的女子。这里指女仆。持汤沃灌：指拿热水喝或拿热水浸洗。汤：热水。沃灌：浇水洗。\n衾（qīn钦）：被子。\n逆旅主人：旅店主人。\n日再食：每日两餐。\n被（pī披）绮绣：穿着华丽的绸缎衣服。被，同“披”。绮，有花纹的丝织品。\n朱缨宝饰：红穗子上穿有珠子等装饰品。\n腰白玉之环：腰间悬着白玉圈。\n容臭：香袋子。臭（xiù）：气味，这里指香气。\n烨（yè页）然：光采照人的样子。\n缊（yùn）袍：粗麻絮制作的袍子。敝衣：破衣。\n耄（mào帽）老：年老。八九十岁的人称耄。宋濂此时已六十九岁。\n幸预：有幸参与。君子指有道德学问的读书人。\n缀：这里意为“跟随”。\n谬称：不恰当地赞许。这是作者的谦词。\n诸生：指太学生。太学：明代中央政府设立的教育士人的学校，称作太学或国子监。\n县官：这里指朝廷。廪（lǐn凛）稍：当时政府免费供给的俸粮称“廪”或“稍”。\n裘（qiú球）：皮衣。葛：夏布衣服。遗（wèi位）：赠，这里指接济。\n司业、博士：分别为太学的次长官和教授。\n非天质之卑：如果不是由于天资太低下。\n流辈：同辈。\n朝：旧时臣下朝见君主。宋濂写此文时，正值他从家乡到京城应天（南京）见朱元璋。\n以乡人子：以同乡之子的身份。谒（yè夜）：拜见。\n撰（zhuàn赚）：同“撰”，写。长书：长信。贽（zhì至）：古时初次拜见时所赠的礼物。\n夷：平易。\n“谓余”二句：认为我是在勉励同乡人努力学习，这是说到了我的本意。\n诋：毁谤。际遇之盛：遭遇的得意，指得到皇帝的赏识重用。骄乡人：对同乡骄傲。\n归见：回家探望。', poem_appreciation = '刘基曾评价宋濂的,送东的前五个自然段，从不同侧面，用多种表述手法，充分叙述和阐明了勤奋好学的重要性，以及应秉持的精神、态度。最后一个自然段，才简要说及题意：因为马生进见，又因为马生年轻善学，所以著文勉励马生。\n\n　　这种别具一格的文章结构布局，可以说是先“宾”后“主”。“宾”，着力叙事说理、笔墨酣畅，因而水到渠成，可以自然过渡到“主”——惜墨如金地点明题意。\n\n　　全文分三大部分，行文紧凑严密，前两部分是从对比中阐发主旨，后一部分扣紧赠序文体，说明写作意图。文章有情有理，不空谈，令人容易接受。第一部分是作者叙述自己的求学时期，如何不辞劳苦，不避艰险，不计客观条件，虚心求学的学生之首”，与高启、刘基并称为“明初诗文三大家”，刘基赞许他“当今文章第一”，四方学者称他为“太史公”。他自幼家境贫寒，但聪敏好学，曾受业于元末古文大家吴莱、柳贯、黄溍等。他一生刻苦学习，“自少至老，未尝一日去书卷，于学无所不通”。元朝末年，元顺帝曾召他为翰林院编修，他以奉养父母为由，辞不应召，修道著书.\n\n　　明初朱元璋称帝，宋濂就任江南儒学提举，为太子讲经。洪武二年（1369），奉命主修《元史》。累官至翰林院学士承旨、知制诰。洪武十年（1377），以年老辞官还乡。后阳马生序》可谓其散文中的佳作，体现了其长者之风、大家之范，其中之美值得细细品味。', poem_tags = '初中文言文,赠言,劝勉,学习,励志,序文' WHERE poem_title = '送东阳马生序' AND poem_author = '宋濂';
UPDATE edu_poem SET poem_translation = '此次离别不知你们心绪何如，停住马饮酒询问被贬的去处。\n巫峡猿猴悲啼令人伤心流泪，衡阳的归雁会为我捎来回书。\n秋日青枫江上孤帆远远飘去，白帝城边黄叶飘零古木稀疏。\n圣明朝代如今定会多施雨露，暂时分手希望你们不要踌躇。', poem_notes = '峡中：此指夔州巫山县（今属重庆）。\n谪居：贬官的地方。\n巫峡：地名，在今重庆市巫山县东。古民谣《巴东三峡歌》：“巴东三峡巫峡长，猿鸣三声泪沾裳。”\n衡阳：地名，今属湖南。相传每年秋天，北方的南飞之雁，至衡阳的回雁峰，便折回北方。这是由长沙想到衡阳，意思要王少府至长沙后多写信来。\n青枫江：地名，在花溪。秋帆：指秋风吹着小舟，送友人远去。', poem_appreciation = '这是一首送别诗，同时也是一首边塞诗，同时送别两人，且两人均为遭贬而迁。\n\n　　首联“嗟君此别意何如，驻马衔杯问谪居。”诗人首先抓住二人都是遭贬，都有满腹愁怨，而眼下又即将分别这一共同点，以深表关切的问句开始，表达了对李、王二少府遭受贬谪的同情，以及对分别的惋惜。“嗟”是叹息之声，置于句首，贬谪分别时的痛苦已不言而喻。“此别”、“谪居”四字，又将题中的“送”和“贬”点出，轻灵自然，不着痕迹。作者在送别之地停下马来，与李、王二少府饮酒饯别，“意何如”、“问谪居”，反复致意，其殷切珍重之情，显而易见，一开篇就以强烈的感情，给读者以深刻的印象。无怪乎方东树在《昭昧詹言》中说：“常侍（即高适）每工于发端。”中间两联针对李、王二少府的现实处境，从二人不同的贬谪之地分别着笔，进一步表达对他们的关心和安慰。\n\n　　“巫峡啼猿数行泪，衡阳归雁几封书？”上句写李少府贬峡中。当时，这里路途遥远，四野荒凉，《巴东三峡歌》曰：“巴东三峡巫峡长，猿鸣三声泪沾裳。”诗人设想李少府来到峡中，在这荒远之地听到凄厉的猿啼，不禁流下感伤的眼泪。下句写王少府贬长沙。衡阳在长沙南面，衡山有回雁峰，传说北雁南飞至此不过，遇春而回。归雁传书是借用苏武雁足系书故事，但长沙路途遥远，归雁也不能传递几封信。\n\n　　“青枫江上秋帆远，白帝城边古木疏。”上句想象长沙的自然风光。青枫江指浏水，在长沙与湘江汇合。这句写李少府到了长沙，在秋高气爽的季节，望着那明净高远、略无纤尘的蓝天，自然会洗尽烦恼。下句想象夔州（即今四川奉节县）的名胜古迹。白帝城为西汉公孙述所筑，在夔州，当三峡之口。这句写王少府到了峡中，可以去古木参天、枝叶扶疏的白帝城凭吊古迹，以求慰藉。\n\n　　这四句情景相融，结合得自然巧妙，读来自有一种苍凉中饱含亲切的情味。所写之境，从巫峡到衡阳，从青枫浦到白帝城，十分开阔，而分写二人，更显出作者的艺术匠心。\n\n　　作者在两联中，一句写李、一句写王，然后一句写王、一句写李，错综交织，而井然不乱，并且采用了“互文”这种修辞手法中的对句互见的方法，在一联中上句隐含着下句，下句隐含着上句，“巫峡”一联上句写贬谪荒远的凄凉，下句说要多通音信，表面看是对李、王分开讲的，实际上是对两人共同而言。同样，“青枫江”一联上句说流连光景，下句说寻访古迹，实际也是对二人共同讲的。这样，在精炼的字句中，包含了丰富的内容，既照顾到了二人不同的地点，又表达了对双方一致的情意，诗人巧妙的处理，使写分送二人的困难迎刃而解，收到了很好的效果。\n\n　　最后一联：“圣代即今多雨露，暂时分手莫踌躇。”诗针对李、王二少府远贬的愁怨和惜别的忧伤，进行了语重心长的劝慰，对前景作了乐观的展望。圣代雨露，是古代文人诗中的惯用之语，这里用来和贬谪相连，也还深藏着婉曲的微讽之意。重点是在后一句“暂时分手莫踌躇”，意思是说：这次外贬，分别只是暂时的，你们不要犹豫不前，将来定有重归之日。全诗在这里结束，不仅与首联照应，而且给读者留下无尽的遐思。\n\n　　叶燮在《原诗》中，曾经指责此诗中间两联连用四个地名太多。其实，高适此诗情真意挚而又气势健拔，虽然连用了四个地名，但对诗意并无影响，反而使意境显得更为开阔。', poem_tags = '唐诗三百首,送别,边塞,贬谪,同情' WHERE poem_title = '送李少府贬峡中王少府贬长沙' AND poem_author = '高适';
UPDATE edu_poem SET poem_translation = '杨柳青青江水宽又平，听见情郎江上踏歌声。\n东边日出西边下起雨，说是无晴但是还有晴。', poem_notes = '竹枝词：乐府近代曲名。又名《竹枝》。原为四川东部一带民歌，唐代诗人刘禹锡根据民歌创作新词，多写男女爱情和三峡的风情，流传甚广。后代诗人多以《竹枝词》为题写爱情和乡土风俗。其形式为七言绝句。\n晴：与“情”谐音。《全唐诗》：也写作“情”。', poem_appreciation = '《竹枝词》是古代四川东部的一种民歌，人民边舞边唱，用鼓和短笛伴奏。赛歌时，谁唱得最多，谁就是优胜者。刘禹锡任夔（kuí）州刺史时，非常喜爱这种民歌，他学习屈原作《九歌》的精神，采用了当地民歌的曲谱，制成新的《竹枝词》，描写当地山水风俗和男女爱情，富于生活气息。体裁和七言绝句一样。但在写作上，多用白描手法，少用典故，语言清新活泼，生动流畅，民歌气息浓厚。刘禹锡创作多首《竹枝词》，这是其中一首。\n\n　　这是一首描写青年男女爱情的诗歌。它描写了一个初恋的少女在杨柳青青、江平如镜的清丽的春日里，听到情郎的歌声所产生的内心活动。\n\n　　首句“杨柳青青江水平”，描写少女眼前所见景物，用的是起兴手法。所谓“兴”，就是触物起情，它与后文要表达的情事。并无直接关系，但在诗中却是不可少的。这一句描写的春江杨柳，最容易引起人的情思，于是很自然地引出了第二句：“闻郎江上唱歌声”。这一句是叙事，写这位少女在听到情郎的歌声时起伏难平的心潮。最后两句：“东边日出西边雨，道是无晴却有晴”，是两个巧妙的隐喻，用的是语意双关的手法。“东边日出”是“有晴”，“西边雨”是“无晴”。“晴”和“情”谐音，“有晴”、“无晴”是“有情”、“无情”的隐语。“东边日出西边雨”，表面是“有晴”、“无晴”的说明，实际上却是“有情”、“无情”的比喻。这使这个少女听了，真是感到难以捉摸，心情忐忑不安。但她是一个聪明的女子，她从最后一句辨清了情郎对她是有情的，因为句中的“有”、“无”两字中，着重的是“有”。因此，她内心又不禁喜悦起来。这句用语意双关的手法，既写了江上阵雨天气，又把这个少女的迷惑、眷恋和希望一系列的心理活动巧妙地描绘出来。\n\n　　此诗以多变的春日天气来造成双关，以“晴”寓“情”，具有含蓄的美，对于表现女子那种含羞不露的内在感情，十分贴切自然。最后两句一直成为后世人们所喜爱和引用的佳句。\n\n　　用谐音双关语来表达思想感情，是我国从古代到现代民歌中常用的一种表现手法。这首诗用这种方法来表达青年男女的爱情，更为贴切自然，既含蓄，又明朗，音节和谐，颇有民歌风情，但写得比一般民歌更细腻，更含蓄。因此，历来为人们所喜爱传诵。', poem_tags = '乐府,民歌,爱情,写景,早教古诗100首' WHERE poem_title = '竹枝词二首·其一' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '北方有位美丽姑娘，独立世俗之外，她对守城的将士瞧一眼，将士弃械，墙垣失守；\n她对君临天下的皇帝瞧一眼，皇帝倾心，国家败亡！美丽的姑娘呀，常常带来“倾城、倾国”的灾难。\n纵然如此，也不能失去获得佳人的好机会。美好姑娘世所难遇、不可再得！', poem_notes = '倾城、倾国：原指因女色而亡国，后多形容妇女容貌极美。陶渊明《闲情赋》：“表倾城之艳色，期有德于传闻。”\n宁不知：怎么不知道。', poem_appreciation = '《李延年歌》有三点特色。\n\n　　其一，出语夸张，欲扬故抑。诗人将所咏美女赞为冠绝当代而独此一人，其美貌的程度竟至看她一眼城邦就会倾覆，再看她一眼国家就会沦亡，“美女亡国”之说最早见于《诗经·大雅·瞻卬》：“哲夫成城，哲妇倾城”，说的是男子有才能立国，女子有才毁社稷，旨在讽刺周幽王宠幸貌美而好迸谗言的褒拟以至亡国之事。此后，“倾城”、“倾国”就成了绝色美女的代名词。在《李延年歌》里，诗人极尽夸张之能事，危言耸听，但绝不是以此来昭示君王，求鉴前史，而是反其意而用之，以其具有倾城倾国的巨大魅力来极言佳人之美，达到引动君王思美之心的目的。\n\n　　其二，情真意切，溢于诗间。《李延年歌》一诗，除了 “其辞脱口而出，无矫揉妆束之态”外，其表达的情感是十分真挚的。李延年歌咏的佳人是自己的胞妹。无论是出于对胞妹的深爱之情而望她有个辉煌的前途，还是出于利己之心而进献胞妹，其诗中表现出的赞美都是热切的。短短几句的小诗，“倾城”、“倾国”的字眼二度出现，推荐美人的主旨非常鲜明。先言有此绝美之人，再言美人的惊人魅力，然后向君王恳切呼告：您难道不知这具有倾城倾国之貌的佳人，一旦错过就再难得到了！拳拳之心意，殷切的情感，在一咏三叹之中挣到了充分的表达，产生了沁人心脾的感染力，拨动了汉武帝的心弦。\n\n　　其三，以简胜繁，以虚生实。中国画以墨为颜色，色彩可谓少矣。但那单一的墨色却可在鉴赏者的脑海中幻化出缤纷的五彩。如同齐白石的画，空白可谓多矣，但那空白处却可使人想象出无限丰美的境界。《李延年歌》只是咏叹了佳人的无双而不作具体描绘，这就势必使佳人的形象成为神秘诱人的空白，从而激发起赏诗者对她的神往、想象和渴念之情。当时在汉武帝的脑海中一定幻化出了世间最为美妙的女子形象。而后世的读诗者，更可以根据自己的审美理想、历史知识及其特有的心理素质，想象出各自心中的绝色佳人来。在歌咏美女的中国古诗中，有不少细描实写的佳句，像“手如柔荑，肤如凝脂”之类。同时也不乏以侧描虚写取胜的佳篇。如《诗经·周南·关雎》，对女子品貌的描写只有一句“窈窕淑女，君子好逑”，而浓墨渲染的是男子对她的苦苦思恋、热烈追求和结合后的欢乐喜悦，以此显示出女子的美丽可爱。《李延年歌》显然也是以这种以虚生实的艺术手法取胜的。', poem_tags = '古诗三百首,乐府,歌咏,美人' WHERE poem_title = '李延年歌' AND poem_author = '李延年';
UPDATE edu_poem SET poem_translation = '我回忆儿童时，可以张开眼睛看着太阳，能看清最细微的东西。我看见细小的东西，一定会去仔细地观察它的纹理，因此常有超出事物本身的乐趣。\n\n　　夏天蚊子发出雷鸣般的声响，我暗自把它们比作群鹤在空中飞舞，心里这么想，那成千成百的蚊子果然都变成仙鹤了；我抬着头看它们，脖颈都为此僵硬了。我又将几只蚊子留在素帐中，用烟慢慢地喷它们，让它们冲着烟雾边飞边叫，我把它当做一幅青云白鹤的景观，果然像仙鹤在青云中鸣叫，我为这景象高兴地拍手叫好。\n\n　　我常在土墙高低不平的地方，在花台杂草丛生的地方，蹲下身子，使自己和花台相平，聚精会神地观察，把草丛当做树林，把虫子、蚂蚁当做野兽，把土块凸出部分当做山丘，凹陷的部分当做山谷，我在其中游玩，觉得非常安闲舒适。\n\n　　有一天，我看见两只小虫在草间相斗，蹲下来观察它们，兴趣正浓厚，忽然有个极大的家伙，掀翻山压倒树而来了，原来是一只癞蛤蟆，舌头一吐，两只虫子全被它吃掉了。我那时年纪很小，正看得出神，不禁‘呀’的一声惊叫起来。待到神情安定下来，捉住癞蛤蟆，鞭打了几十下，把它驱赶到别的院子里去了。', poem_notes = '余：我。\n忆：回忆，回想。\n稚：幼小，形容年龄小。\n张目：张大眼睛。\n对：面向，对着，朝。\n明察秋毫：形容视力好。秋毫，指鸟类到了秋天，重新生出来非常纤细的羽毛。后来用来比喻最细微的事物。\n藐小之物：微小的东西。\n细：仔细。\n纹理：花纹和条理。\n故：所以。\n物外：这里指超出事物本身。\n成：像。\n私拟：我（把蚊子）比作。拟，比。私，私自\n于：在。\n则：那么，就。\n或：有的。\n果：果真。\n项为之强（jiāng）：脖颈为此而变得僵硬了。项，颈，脖颈。为，为此。强，通“僵”，僵硬的意思。\n素帐：未染色的帐子。\n徐喷以烟：慢慢地用烟喷。徐，慢慢地。以，用。\n使：让。\n而：承接关系，这里可解释为“便”“就”。\n作：当做。\n观：景观。\n唳（lì）：鸟鸣。\n为之：因此。\n怡然：安适、愉快的样子。然，……的样子。\n以……为……：把……当作……。\n林：森林。\n砾：土块。\n壑（hè）：山沟。\n怡然自得：安适愉快而又满足的样子。\n兴：兴致。\n庞然大物：体积庞大的东西，极大的东西。\n盖：承接上文，表示原因。这里有“原来是”的意思。\n虾（há）蟆：蟾蜍的通称。虾蟆，现写作“蛤蟆”。\n为：介词，被。\n方出神：正在出神。方，正。\n鞭：名词作动词，鞭打。\n数十：几十。\n驱：驱赶。\n之：代词，它指癞蛤蟆。', poem_tags = '初中文言文,叙事,散文,回忆,童年' WHERE poem_title = '童趣' AND poem_author = '沈复';
UPDATE edu_poem SET poem_translation = '锦官城里的音乐声轻柔悠扬，一半随着江风飘去，一半飘入了云端。\n这样的乐曲只应该天上有，人间里哪能听见几回？', poem_notes = '花卿：成都尹崔光远的部将花敬定。\n锦城：即锦官城，此指成都\n丝管：弦乐器和管乐器，这里泛指音乐。\n纷纷：形容乐曲的轻柔悠扬。\n天上：双关语，虚指天宫，实指皇宫。\n几回闻：本意是听到几回。文中的意思是说人间很少听到。', poem_appreciation = '这首绝句，字面上明白如话，但对它的主旨，历来注家颇多异议。有人认为它只是赞美乐曲，并无弦外之音；有人则认为它表面上看是在赞美乐曲，实际上却含讽刺，劝诫的意味。\n\n　　说是语含讽刺，耐人寻味的是，作者并没有对花卿明言指摘，而是采取了一语双关的巧妙手法。字面上看，这俨然是一首十分出色的乐曲赞美诗。“锦城丝管日纷纷”，锦城，即成都；丝管，指弦乐器和管乐器；纷纷，本意是既多而乱的样子，通常是用来形容那些看得见、摸得着的具体事物的，这里却用来比状看不见、摸不着的抽象的乐曲，这就从人的听觉和视觉的通感上，化无形为有形，极其准确、形象地描绘出弦管那种轻悠、柔靡，杂错而又和谐的音乐效果。“半入江风半入云”也是采用同样的写法：那悠扬动听的乐曲，从花卿家的宴席上飞出，随风荡漾在锦江上，冉冉飘入蓝天白云间。这两句诗，使读者真切地感受到了乐曲的那种“行云流水”般的美妙。两个“半”字空灵活脱，给全诗增添了不少的情趣。\n\n　　乐曲如此之美，作者禁不住慨叹说：“此曲只应天上有，人间能得几回闻。”天上的仙乐，人间当然难得一闻，难得闻而竟闻，愈见其妙得出奇了。\n\n　　全诗四句，前两句对乐曲作具体形象的描绘，是实写；后两句以天上的仙乐相夸，是遐想。因实而虚，虚实相生，将乐曲的美妙赞誉到了极度。\n\n　　然而这仅仅是字面上的意思，其弦外之音是意味深长的。这可以从“天上”和“人间”两词看出端倪。“天上”，实际上指天子所居皇宫；“人间”，指皇宫之外。这是封建社会极常用的双关语。说乐曲属于“天上”，且加“只应”一词限定，既然是“只应天上有”，那么，“人间”当然就不应“得闻”。不应“得闻”而竟然“得闻”，不仅“几回闻”，而且“日纷纷”，于是，作者的讽刺之旨就从这种矛盾的对立中，既含蓄婉转又确切有力地显现出来了。\n\n　　宋人张天觉曾论诗文的讽刺说：“讽刺则不可怒张，怒张则筋骨露矣。”（《诗人玉屑》卷九引）杜甫这首诗柔中有刚，绵里藏针，寓讽于谀，意在言外，忠言而不逆耳，作得恰到好处。', poem_tags = '劝诫,讽刺' WHERE poem_title = '赠花卿' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '不要说从山岭上下来就没有困难，这句话骗得前来爬山的人白白地欢喜一场。\n当你进入到崇山峻岭的圈子里以后，你刚攀过一座山，另一座山立刻将你阻拦。', poem_notes = '松源、漆公店：地名，在今皖南山区。\n莫言：不要说。\n赚得：骗得。\n空喜欢：白白的喜欢。\n拦：阻拦，阻挡。', poem_appreciation = '本诗朴实平易，生动形象，表现力强，一个“空”字突出表现了“行人”被“赚”后的失落神态。“放”、“拦”等词语的运用，赋予“万山”人的思想、人的性格，使万山活了起来。\n\n　　第一句当头喝起，“莫言下岭便无难”，这是一个富于包孕的诗句，它包含了下岭前艰难攀登的整个上山过程，以及对所经历困难的种种感受。正因为上山艰难，人们便往往把下山看得容易和轻松。开头一句，正像是对这种普遍心理所发的棒喝。“莫言”二字，像是自诫，又像是提醒别人，耐人寻味。\n\n　　第二句补足首句，“赚得行人空喜欢”，“赚”字富于幽默风趣。行人心目中下岭的容易，与它实际上的艰难形成鲜明对比，因此说“赚”——行人是被自己对下岭的主观想象骗了。诗人在这里点出而不说破，给读者留下悬念，使下两句的出现更引人注目。\n\n　　三四两句承接“空喜欢”，对第二句留下的悬念进行解释。本来，上山过程中要攀登多少道山岭，下山过程中也会相应遇到多少道山岭。山本无知，“一山放过一山拦”的形容却把山变成了有生命有灵性的东西。它仿佛给行人布置了一个迷魂阵，设置了层层叠叠的圈套。而行人的种种心情——意外、惊诧、厌烦，直至恍然大悟，也都在这一“拦”一“放”的重复中体现出来了。\n\n　　诗人借助景物描写和生动形象的比喻，通过写山区行路的感受，说明一个具有普遍意义的深刻道理：人们无论做什么事，都要对前进道路上的困难作好充分的估计，不要被一时的成功所陶醉。', poem_tags = '初中古诗,写景,行路,哲理' WHERE poem_title = '过松源晨炊漆公店' AND poem_author = '杨万里';
UPDATE edu_poem SET poem_translation = '春天只要播下一粒种子，秋天就可收获很多粮食。\n普天之下，没有荒废不种的田地，劳苦农民，仍然要饿死。\n\n盛夏中午，烈日炎炎，农民还在劳作，汗珠滴入泥土。\n有谁想到，我们碗中的米饭，粒粒饱含着农民的血汗？', poem_notes = '悯：怜悯。这里有同情的意思。诗一作《古风二首》。这两首诗的排序各版本有所不同。\n粟：泛指谷类。\n秋收：一作“秋成”。子：指粮食颗粒。\n四海：指全国。闲田：没有耕种的田。\n犹：仍然。\n禾：谷类植物的统称。\n餐：一作“飧”。熟食的通称。', poem_appreciation = '第一首诗一开头，就以“一粒粟”化为“万颗子”具体而形象地描绘了丰收，用“种”和“收”赞美了农民的劳动。第三句再推而广之，展现出四海之内，荒地变良田，这和前两句联起来，便构成了到处硕果累累，遍地“黄金”的生动景象。“引满”是为了更有力的“发”，这三句诗人用层层递进的笔法，表现出劳动人民的巨大贡献和无穷的创造力，这就使下文的反结变得更为凝重，更为沉痛。“农夫犹饿死”，它不仅使前后的内容连贯起来了，也把问题突出出来了。勤劳的农民以他们的双手获得了丰收，而他们自己还是两手空空，惨遭饿死。诗迫使人们不得不带着沉重的心情去思索“是谁制造了这人间的悲剧”这一问题。诗人把这一切放在幕后，让读者去寻找，去思索。要把这两方综合起来，那就正如马克思所说的：“劳动替富者生产了惊人作品（奇迹），然而，劳动替劳动者生产了赤贫。劳动生产了宫殿，但是替劳动者生产了洞窟。劳动生产了美，但是给劳动者生产了畸形。”\n\n　　第二首诗，一开头就描绘在烈日当空的正午，农民依然在田里劳作，那一滴滴的汗珠，洒在灼热的土地上。这就补叙出由“一粒粟”到“万颗子”，到“四海无闲田”，乃是千千万万个农民用血汗浇灌起来的；这也为下面“粒粒皆辛苦”撷取了最富有典型意义的形象，可谓一以当十。它概括地表现了农民不避严寒酷暑、雨雪风霜，终年辛勤劳动的生活。“谁知盘中餐，粒粒皆辛苦”，不是空洞的说教，不是无病的呻吟；它近似蕴意深远的格言，但又不仅以它的说服力取胜，而且还由于在这一深沉的慨叹之中，凝聚了诗人无限的愤懑和真挚的同情。\n\n　　这两首小诗在百花竞丽的唐代诗苑，同那些名篇相比算不上精品，但它却流传极广，妇孺皆知，不断地被人们所吟诵、品味，其中不是没有原因的。\n\n　　首先，这两首诗所抒写的内容是人们经常接触到的最熟悉的事情。但是，最熟悉不一定真知道，生活中就有许多熟视无睹的情况，如果一旦有人加以点拨，或道明实质，或指出所包含的某种道理，就会觉得很醒目，很清楚，从而加深了认识。这两首小诗所以有生命力，就有这一方面的道理。\n\n　　“春种一粒粟，秋收万颗子”，这个春种秋收的景象大概是人人习见，众人皆知的，然而往往难于像诗人那样去联系社会、阶级而思考一些问题。诗人却想到了，他从“四海无闲田”的大丰收景象里看到“农夫犹饿死”的残酷现实。这一点拨就异常惊人醒目，自然给人留下深刻的印象。再如“盘中餐”，这原是人们天天接触，顿顿必食的，然而并没有谁想到把这粒粒粮食和农民在烈日之下的汗水联系在一起。诗人敏锐地观察到了，并凝聚成“粒粒皆辛苦”的诗句。这就给人们以启迪，引人去思索其中的道理，从而使那些不知珍惜粮食的人受到深刻的教育。\n\n　　其次，诗人在阐明上述的内容时，不是空洞抽象地叙说和议论，而是采用鲜明的形象和深刻的对比来揭露问题和说明道理，这就使人很容易接受和理解。像第一首的前三句，从总体意义来说都是采用了鲜明的形象概括了农民在广大田野里春种秋收等繁重劳动的辛苦。这些辛苦并换来了大量的粮食，该说是可以生活下去的，但最后一句却凌空一转，来了个“农夫犹饿死”的事实。这样，前后的情况形成鲜明的对比，引发读者从对比中去思考问题，得出结论，如此就比作者直接把观点告诉读者要深刻有力得多。再如第二首，作者在前两句并没有说农民种田怎样辛苦，庄稼的长成如何不易，只是把农民在烈日之下锄禾而汗流不止的情节作了一番形象的渲染，就使人把这种辛苦和不易品味得更加具体、深刻且真实。所以诗人最后用反问语气道出“谁知盘中餐，粒粒皆辛苦”的道理就很有说服力。尤其是把粒粒粮食比作滴滴汗水，真是体微察细，形象而贴切。\n\n　　最后，诗的语言通俗、质朴，音节和谐明快，朗朗上口，容易背诵，也是这两首小诗长期在人民中流传的原因。', poem_tags = '忧国忧民,农民,组诗,早教古诗100首' WHERE poem_title = '悯农二首' AND poem_author = '李绅';
UPDATE edu_poem SET poem_translation = '梁惠王说：“我对于国家，总算尽了心啦。河内遇到饥荒，就把那里的老百姓迁移到河东去，把河东的粮食转移到河内；河东遇到饥荒也是这样做。了解一下邻国的政治，没有像我这样用心的。邻国的百姓不见减少，我的百姓不见增多，这是为什么呢？”\n\n　　孟子回答说：“大王喜欢打仗，让我用战争做比喻吧。咚咚地敲响战鼓，两军开始交战，战败的扔掉盔甲拖着武器逃跑。有人逃了一百步然后停下来，有的人逃了五十步然后停下来。凭自己只跑了五十步而耻笑别人跑了一百步，那怎么样呢？”梁惠王说：“不行。只不过没有跑上一百步罢了，那也是逃跑啊。”孟子说：“大王如果懂得这个道理，就不要指望自己的百姓比邻国多了。\n\n　　“不耽误农业生产的季节，粮食就会吃不完。密网不下到池塘里，鱼鳖之类的水产就会吃不完。按一定的季节入山伐木，木材就会用不完。粮食和水产吃不完，木材用不完，这就使百姓对生养死葬没有什么不满了。百姓对生养死葬没有什么不满，这是王道的开端。“五亩大的住宅场地，种上桑树，五十岁的人就可以穿丝织品了。鸡、猪、狗的畜养，不要耽误它们的繁殖时机，七十岁的人就可以吃肉食了。百亩大的田地，不要耽误它的耕作时节，数口之家就可以不受饥饿了。认真地兴办学校教育，把尊敬父母、敬爱兄长的道理反复讲给百姓听，须发花白的老人就不会背负或头顶重物在路上行走了。七十岁的人能够穿上丝织品、吃上肉食，百姓没有挨饿受冻的，做到了这些而不能统一天下称王的还从未有过。“猪狗吃人所吃的食物，不知道制止；道路上有饿死的人，不知道开仓赈济。百姓死了，就说：‘这不是我的过错，是因为年岁不好。’这种说法与拿刀把人杀死后，说‘杀死人的不是我，是兵器’有什么不同？大王不要归罪于年成，那么天下的百姓都会来归顺了。”', poem_notes = '1. 梁惠王： 战国时期魏国的国君，姓魏，名罃。魏国都城在大梁，今河南省开封市西北，所以魏惠王又称梁惠王。\n2. 寡人：寡德之人．是古代国君对自己的谦称。\n3. 焉耳矣：焉、耳、矣都是句末助词，重叠使用，加重语气。\n4. 河内：今河南境内黄河以北的地方。古人以中原地区为中心，所以黄河以北称河内，黄河以南称河外。\n5. 凶：谷物收成不好．荒年。\n6. 河东：黄河以东的地方。在今山西西南部。黄河流经山西省境，自北而南，故称山西境内黄河以东的地区为河东。\n7. 粟：谷子，脱壳后称为小米，也泛指谷类。\n8. 亦然：也是这样。\n9. 无如：没有像……。\n10. 加少：更少。下文“加多”，更多。加，副词，更、再。\n11. 好战：喜欢打仗。战国时期各国诸侯热衷于互相攻打和兼并。\n12. 请以战喻：让我用打仗来做比喻。请，有“请允许我”的意思。\n13. 填：拟声词，模拟鼓声。\n14. 鼓之：敲起鼓来，发动进攻。古人击鼓进攻，鸣锣退兵。鼓，动词。之，没有实在意义的衬字。\n15. 兵刃既接：两军的兵器已经接触，指战斗已开始。兵，兵器、武器。既，已经。接，接触，交锋。\n16. 弃甲曳兵：抛弃铠甲，拖着兵器。曳，yè，拖着。\n17. 走：跑，这里指逃跑。\n18. 或：有的人。\n19. 以：凭着，借口。\n20. 笑：耻笑，讥笑。\n21. 直：只是、不过。\n22. 是：代词，这，指代上文“五十步而后止”。\n23. 无：通“毋”，不要。\n24. 不违农时：指农忙时不要征调百姓服役。违，违背、违反，这里指耽误。\n25. 谷：粮食的统称。\n26. 不可胜食：吃不完。胜，尽。\n27. 数罟不入洿池：这是为了防止破坏鱼的生长和繁殖。数，cù，密。罟，gǔ，网。洿，wū，深。\n28. 鳖：biē，甲鱼或团鱼。\n29. 斤：与斧相似，比斧小而刃横。\n30. 时：时令季节。砍伐树木宜于在草木凋落，生长季节过后的秋冬时节进行。\n31. 养生：供养活着的人。\n32. 丧死：为死了的人办丧事。\n33. 憾：遗憾。\n34. 王道：以仁义治天下，这是儒家的政治主张。与当时诸侯奉行的以武力统一天下的“霸道”相对。\n35. 五亩：先秦时五亩约合21世纪一亩二分多。\n36. 树：种植。\n37. 衣帛：穿上丝织品的衣服。衣，用作动词，穿。\n38. 豚：tún，小猪。\n39. 彘：zhì，猪。\n40. 畜：xù，畜养，饲养。\n41. 无：通“毋”，不要。\n42. 百亩之田：古代实行井田制，一个男劳动力可分得耕田一百亩。\n43. 夺：失，违背。\n44. 谨：谨慎，这里指认真从事。\n45. 庠序：古代的乡学。《礼记?学记》：“古之教者，家有塾，党有庠，术有序，国有学。“家”，这里指“闾”，二十五户人共住一巷称为闾。塾，闾中的学校。党，五百户为党。庠，设在党中的学校。术，同“遂”，一万二千五百家为遂。序，设在遂中的学校。国，京城。学，大学。庠，xiánɡ。\n46. 教：教化。\n47. 申：反复陈述。\n48. 孝悌：敬爱父母和兄长。悌，tì。\n49. 义：道理。\n50. 颁白：头发花白。颁，通“斑”。\n51. 负戴：负，背负着东西。戴，头顶着东西。\n52. 黎民：百姓。\n53. 王：这里用作动词，为王，称王，也就是使天下百姓归顺。\n54. 未之有：未有之。之，指代“七十者衣帛食肉，黎民不饥不寒，然而不王者”。\n55. 食人食：前一个“食”，动词，吃；后一个“食”，名词，指食物。\n56. 检：检点，制止、约束。\n57. 涂：通“途”，道路。\n58. 饿莩：饿死的人。莩，piǎo，同“殍”，饿死的人。\n59. 发：指打开粮仓，赈济百姓。\n60. 岁：年岁、年成。\n61. 罪：归咎，归罪。\n62. 斯：则、那么。', poem_appreciation = '本文写作上体现出的孟子散文的特点\n\n　　谈问题先把主旨藏起来，从侧面、反面、外围人手，逐渐引向本题。如本意要讲实行仁政，却先以战设喻，从反面入手，使梁惠王不知不觉中跟着他走。这样，文章如曲径探幽，引人入胜；文势则波澜起伏，毫无板滞。\n\n　　2. 逻辑严谨，层层深入。\n\n　　表面看来，文章铺张扬厉，散漫无纪，实则逻辑清晰，段落分明，层次井然。如先提出问题，再分析原因，后述措施，王道之始，王道之实，实行仁政，均是层层深入、环环相扣。\n\n　　3. 词丰笔活，理足气盛。\n\n　　善用贴切的比喻、有力的铺排，考究用词，讲求句式。奇句与偶句，单势句与排比句，交错使用，笔势灵活，理直气壮，谈锋犀利，咄咄逼人。文章极富雄辩的气势。', poem_tags = '高中文言文,治国,哲理' WHERE poem_title = '寡人之于国也' AND poem_author = '孟子弟子录';
UPDATE edu_poem SET poem_translation = '梅子黄透了的时候，天天都是晴朗的好天气，乘小舟沿着小溪而行，走到了小溪的尽头，再改走山路继续前行。\n山路上苍翠的树，与来的时候一样浓密，深林丛中传来几声黄鹂的欢鸣声，比来时更增添了些幽趣。', poem_notes = '三衢道中：在去三衢州的道路上。三衢即衢州，今浙江省常山县，因境内有三衢山而得名。\n梅子黄时：指五月，梅子成熟的季节。\n小溪泛尽：乘小船走到小溪的尽头。小溪，小河沟。泛，乘船。尽，尽头。\n却山行：再走山间小路。却，再的意思。\n绿阴：苍绿的树阴。阴，树阴。\n不减：并没有少多少，差不多。\n黄鹂：黄莺。', poem_appreciation = '诗写初夏时宁静的景色和诗人山行时轻松愉快的心情。\n\n　　这是一首纪行诗，全诗明快自然，极富有生活韵味。写诗人行于三衢山道中的见闻感受。首句点明此行的时间，“梅子黄时”正是江南梅雨时节（黄梅天），难得有这样“日日晴”的好天气，因此诗人的心情自然也为之一爽，游兴愈浓。诗人乘轻舟泛溪而行，溪尽而兴不尽，于是舍舟登岸，山路步行。一个“却”字，道出了他高涨的游兴。三四句紧承“山行”，写绿树荫浓，爽静宜人，更有黄鹂啼鸣，幽韵悦耳，渲染出诗人舒畅愉悦的情怀。“来时路”将此行悄然过渡到归程，“添得”二字则暗示出行归而兴致犹浓，故能注意到归途有黄鹂助兴，由此可见出此作构思之机巧、剪裁之精当。\n\n　　作者将一次平平常常的行程，写得错落有致，平中见奇，不仅写出了初夏的宜人风光，而且诗人的愉悦情状也栩栩如生，让人领略到平的意趣。\n\n　　诗还有个特点，就是通过对比融入感情。诗将往年阴雨连绵的黄梅天与眼下的晴朗对比；将来时的绿树及山林的幽静与眼前的绿树与黄莺叫声对比，于是产生了起伏，引出了新意。全诗又全用景语，浑然天成，描绘了浙西山区初夏的秀丽景色；虽然没有铺写自己的感情，却在景物的描绘中锲入了自己愉快欢悦的心情。\n\n　　曾几虽然是江西诗派的一员，但这首绝句写得清新流畅，没有江西诗派生吞活剥、拗折诘屈的弊病。他的学生陆游就专学这种，蔚成大家。', poem_tags = '古诗三百首,纪游,喜悦' WHERE poem_title = '三衢道中' AND poem_author = '曾几';
UPDATE edu_poem SET poem_translation = '昨天夜里北斗星的斗柄转向东方，今天早晨一年又开始了。\n我已经四十岁了，虽然没有官职但仍担心农事。\n靠近在种满桑树的田野里耕作的农夫，扛着锄头和牧童一起劳作。\n农家人推测今年的收成，都说这一年是丰收年。', poem_notes = '元日：农历正月初一。\n斗：指北斗星。回北：指北斗星的斗柄从指向北方转而指向东方。古人认为北斗星斗柄指东，天下皆春；指南，天下皆夏；指西，天下皆秋；指北，天下皆冬。\n起：开始。东：北斗星斗柄朝东。\n强仕：强仕之年，即四十岁。\n无禄：没有官职。禄：官吏的薪俸。尚：还。\n桑野：种满桑树的田野。就：靠近。耕父：农人。\n荷：扛，担。\n占（zhān）：推测占气候：根据自然气候推测一年收成的好坏。', poem_appreciation = '诗的首联写斗转星移，岁月不居，昨晚除夕还是寒冷的隆冬，今朝大年初一起来就已经是和煦的春天。这两句通过斗柄指北向东转动的快速过程显示时间的推移，节序的更替，暗点了题中的“元日”。\n\n　　颔联写诗人已进入四十岁的壮年时期，本应出仕，大有作为，但未曾得到一官半职，虽然如此，他对农事还是非常重视，非常关心。这一联概述了诗人仕途的遭际，表露了他的农本思想，体现了他不以物喜，不以己悲的可贵品质。诗人既初隐于鹿门，不仅结交了大批淳朴善良的农夫野老；同时又直接参与了田事劳作。自然有了对农村的深厚的感情，忧喜以共，苦乐同心。但另方面，作为一个有理想的知识分子，不能叫他完全没有奋飞冲天的幻想，正是这样，在诗句里才有“我年已强仕，无禄尚忧农”的叹息。时代的隐者都有远大的志趣。所以无论他的出山或其后的再次归田，都深刻地表现了诗人对农村乡土真挚的爱恋。\n\n　　颈联展示的是一幅典型的田园牧歌图。白天。在田间，诗人和农父一起扶犁耕作；傍晚，在路上，诗人荷锄伴牧童一道回归村庄。由此，人们仿佛可以看到诗人与农父并肩劳动，促膝休息，“但道桑麻长”的情景；仿佛可以听到诗人与“短笛无腔信口吹”的牧童应和的笛音歌声，从而深深地体味到田园风光的美好，田园生活的快乐。\n\n　　尾联扣题，明确点题，写田家元日之际凭借占卜纷纷预言今年是一个丰收年。显然，这首诗没有状写辞旧迎新的热闹，没有抒发节日思亲的情感，而是将诗人自身恬淡，惬意的情趣水乳般交融于节日气氛之中，令人读来自觉有一种和谐自然之美。\n\n　　诗中首尾两联反映了我国古代农民非常重视观测天象，注意气候、节令与农业生产的关系，其中虽有某种程度的迷信色彩，但更多的是从生产实践中总结出来的经验，有一定的科学价值。中间两联叙写了自已的隐居生活内容，其中隐隐透露了作者不甘隐居躬耕的心情，说明他的鹿门隐居只是为了取得清高的声望，以便得到引荐达到入仕的目的。这首诗既叹自己的不遇，惜壮志之难伸；又复悲天悯人，忧农收之不丰，隐然有一心以天下为己任的怀抱。本来，士各有志，人各有愿；而在总的希望的水中，九派百支，主流总趋于一个定向：愿年年月圆花好，愿岁岁人寿年丰。只不过表现的形式不同而已。\n\n　　这首诗叙写了诗人新年伊始的心绪。前四句写时光匆匆，又一年开始了，自己已届四十，仍未做官，不禁产生淡淡的哀伤。后四句写自己与牧童、农人一起推测气候、年成，不觉又有一丝自适之情。全诗没有明显的起伏，语调平和，而静味深长。尾句“共说此年丰”当有双重含义：一是指农田耕种的丰收，二是企盼即将去长安赴试有一个好的结果。', poem_tags = '春节,农事,抒情' WHERE poem_title = '田家元日' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '青春的日子十分容易逝去，学问却很难获得成功，所以每一寸光阴都要珍惜，不能轻易放过。没等池塘生春草的美梦醒来，台阶前的梧桐树叶就已经在秋风里沙沙作响了。', poem_notes = '池塘春草梦：这是一个典故，源于《南史·谢方明传》，谢方明之子惠连，年十岁能属文，族兄灵运嘉赏之，云：“每有篇章，对惠连辄得佳话。”尝于永嘉西堂四诗，竞日不就，忽梦见惠连，即得“池塘生春草”，大以为工。常云：“此语神功，非吾语也。”“池塘生春草，园柳变鸣禽”是谢灵运《登池上楼》中的诗句，后被赞誉为写春意的千古名句，此处活用其典，意谓美好的青春年华将很快消逝，如同一场春梦。\n秋声：秋时西风作，草木凋零，多肃杀之声。', poem_tags = '励志,惜时,读书' WHERE poem_title = '劝学诗 / 偶成' AND poem_author = '朱熹';
UPDATE edu_poem SET poem_translation = '弯弯的勾月悬挂在疏落的梧桐树上；夜阑人静，漏壶的水早已滴光了。有谁见到幽人独自往来，仿佛天边孤雁般飘渺的身影。\n黑夜中的它突然受到惊吓，骤然飞起，并频频回头，却总是无人理解它内心的无限幽恨。它不断于寒冷的树枝间逡巡，然而不肯栖息于任何一棵树上，最后只能寂寞地降落在清冷的沙洲上。', poem_notes = '漏断：即指深夜。漏，指古人计时用的漏壶；即指深夜。\n原题“黄州定惠寺寓居作”。\n漏：指更漏而言。这里“漏断”不过说夜深罢了。\n幽：《易·履卦》：“幽人贞吉”，其义为幽囚。引申为幽静、优雅。\n孤鸿：张九龄《感遇》十二之四：“孤鸿海上来。”胡仔《苕溪渔隐丛话》前集三十九：“此词本咏夜景，至换头但只说鸿，正如《贺新郎》词“乳燕飞华屋”，至换头但只说榴花。….“按两词均系泛咏，本未尝有”夜景“等题，多说鸿，多说石榴，既无所妨，亦未必因之而奇妙。胡评似未谛。\n省：理解。“无人省“，犹言”无人识“。\n或以为“拣尽寒枝“有语病，亦见注⑷所引同书同条。《稗海》本《野客丛书》：”观隋李元操《鸿雁行》曰：“夕宿寒枝上，朝飞空井旁。“坡语岂无自邪？“此言固是。寒枝意广泛，又说”不肯栖“，本属无碍。此句亦有良禽择木而栖的意思。《左传》哀公十一年：”鸟则择木，木岂能择鸟。“杜甫《遣愁》：”择木知幽鸟。“\n末句一本作“枫落吴江冷“，全用唐人崔信明断句，且上下不接，恐非。', poem_appreciation = '这是苏轼的一首名词《卜算子》。现在通行的各个版本的词选中都有一个小序：“黄州定慧院寓居作。”据史料记载，此词为公元1083年（神宗元丰六年）初作于黄州，定慧院在今天的湖北黄冈县东南，苏轼另有《游定惠院记》一文。由上可知这首词是苏轼初贬黄州寓居定慧院时所作。被贬黄州后，虽然自己的生活都有问题，但苏轼是乐观旷达的，能率领全家通过自身的努力来渡过生活难关。但内心深处的幽独与寂寞是他人无法理解的。在这首词中，作者借月夜孤鸿这一形象托物寓怀，表达了孤高自许、蔑视流俗的心境。　\n\n　　上阕写的正是深夜院中所见的景色。“缺月挂疏桐，漏断人初静。”营造了一个夜深人静、月挂疏桐的孤寂氛围，为\'\'幽人\'\'、\'\'孤鸿\'\'的出场作铺垫。“漏”指古人计时用的漏壶：“漏断”即指深夜。在漏壶水尽，更深人静的时候，苏轼步出庭院，抬头望月，又是一个多么孤寂的夜晚呀！月儿似乎也知趣，从稀疏的桐树间透出清晖，像是挂在枝桠间。这两句出笔不凡，渲染出一种孤高出生的境界。接下来的两句，“时见幽人独往来，缥缈孤鸿影。”周围是那么宁静幽寂，在万物入梦的此刻，又有谁像自己这样在月光下孤寂地徘徊，就像是一只孤单飞过天穹的凄清的大雁呢？先是点出一位独来独往、心事浩茫的“幽人”形象，随即轻灵飞动地由“幽人”而孤鸿，使这两个意象产生对应和契合，让人联想到：“幽人”那孤高的心境，不正像缥缈若仙的孤鸿之影吗？这两句，既是实写，又通过人、鸟形象的对应、嫁接，极富象征意味和诗意之美地强化了“幽人”的超凡脱俗。物我同一，互为补充，使孤独的形象更具体感人。\n\n　　下阕，更是把鸿与人同写，“惊起却回头，有恨无人省。”这是直写自己孤寂的心境。人孤独的时候，总会四顾，回头的寻觅，找到的是更多的孤独，“有恨无人省”，有谁能理解自己孤独的心呢？世无知音，孤苦难耐，情何以堪？“拣尽寒枝不肯栖，寂寞沙洲冷。”写孤鸿遭遇不幸，心怀幽恨，惊恐不已，在寒枝间飞来飞去，拣尽寒枝不肯栖息，只好落宿于寂寞荒冷的沙洲，度过这样寒冷的夜晚。这里，词人以象征手法，匠心独运地通过鸿的孤独缥缈，惊起回头、怀抱幽恨和选求宿处，表达了作者贬谪黄州时期的孤寂处境和高洁自许、不愿随波逐流的心境。作者与孤鸿惺惺相惜，以拟人化的手法表现孤鸿的心理活动，把自己的主观感情加以对象化，显示了高超的艺术技巧。 　\n\n　　这首词的境界，确如黄庭坚所说：“语意高妙，似非吃烟火食人语，非胸中有万卷书，笔下无一点尘俗气，孰能至此！”这种高旷洒脱、绝去尘俗的境界，得益于高妙的艺术技巧。作者“以性灵咏物语”，取神题外，意中设境，托物寓人；对孤鸿和月夜环境背景的描写中，选景叙事均简约凝练，空灵飞动，含蓄蕴藉，生动传神，具有高度的典型性。\n\n　　冷寒的，也不止是沙洲和桐枝。有恨的，究竟是孤鸿还是幽人？静夜如此寂寞，又何须漏壶提醒辰次？月儿依然残缺。不见有清满的佳期！疏淡的笑墨，似写凄淡的夜色；清美的词境，难歇哀愤的心。作为刚到黄州时的词作，可以看出作者心内的紊乱。可正是在黄州，作者完成了自己处世哲学的形成。《赤壁怀古》、《赤壁赋》等篇章，才是作者对人生乐观冷静的态度。而写作此词时，应该还没有完成这种成熟。所以，从词中，读者看到的是一种冷清与寂寞的情怀。即使如此，此词还是很受后人推崇，如《山谷题跋》有云：“语意高妙，似非吃人间烟火语。”而“非胸中有数万卷书，笔下无一点俗气”则不能到。但是，正因为此词的仙骨气质，历来对这首词的主旨说法不一，有人认为是为王姓女子而作，有人认为是为温都监女作，即这是一首爱情词；但也有人认为是作者对现实不满，抒发愤懑之情的，也就是说这是一首影射、刺时之作；还有人认为这首词是写作者的寂寞之情的。有一种说法最为有趣。据《宋六十名家词·东坡词》载，此词还有一序，讲的是一个美丽而凄凉的故事。摘录如下：\n\n　　惠州有温都监女，颇有色。年十六，不肯嫁人。闻坡至，甚喜。每夜闻坡讽咏，则徘徊窗下，坡觉而推窗，则其女逾墙而去。坡从而物色之曰：“当呼王郎，与之子为姻。未几，而坡过海，女遂卒，葬于沙滩侧。坡回惠，为赋此词。\n\n　　前半段写的虚幻迷离，要不是前面有段引言：“惠州有温都监女，颇有色。年十六，不肯嫁人。”颇有点遇仙的感觉。\n\n　　苏轼寓居定惠院，每到他深夜吟诗时，总有一位美女在窗外徘徊。当推窗寻找时，她却已经翻墙而去。此情此景岂非正是苏轼词上阕所写：“ 缺月挂疏桐，漏断人初静。谁见幽人独往来？缥缈孤鸿影。”由此说来，句中的幽人该是指那位神秘美丽的女子，上阕则是记录此事了。\n\n　　当时苏轼六十几岁，张先七十还纳妾，六十岁也不算什么的。有人很愤慨他为什么不纳那个女子为妾，却物色王郎之子与她为姻，最终使她郁郁而亡。\n\n　　这个女子好像是为苏轼而存在，在苏轼离开惠州后，女子就死去了，遗体埋葬在沙洲之畔。当苏轼回到惠州，只见黄土一堆，个中幽愤之情可想而知。于是，就赋了这篇著名的《卜算子》。由此可见，此首词的下阕是为了纪念那女子而写：“惊起却回头，有恨无人省。拣尽寒枝不肯栖，寂寞沙洲冷。”\n\n　　这篇序言，短短的数十个字，就婉娩道出了一个感人肺腑，催人泪下的爱情故事，真是精彩绝伦，令人拍案叫绝。\n\n　　吴曾《能改斋漫录》云：“其属意盖为王氏女子也，读者不能解。张右史文潜继贬黄州，访潘邠老，闻得其祥，题诗以志之云：空江月明鱼龙眠，月中孤鸿影翩翩。有人清吟立江边，葛巾藜杖眼窥天。夜冷月堕幽虫泣，鸿影翘沙衣露湿。仙人采诗作步虚，玉皇饮之碧琳腴。”\n\n　　这个记载好像是为了证明那个序言的真实性而作，甚至还有诗为证。且不论其可信度到底有多高，这个故事在当时深入人心是肯定了的。\n\n　　现今一般以唐圭璋先生的注释为准，他认为此词上片写鸿见人，下片写人见鸿。此词借物比兴。人似飞鸿，飞鸿似人，非鸿非人，亦鸿亦人，人不掩鸿，鸿不掩人，人与鸿凝为一体，托鸿以见人。东坡又有诗云：“人似秋鸿来有信，去如春梦了无痕。”（《正月二十二日与潘郭二生出郊游寻春忽记去年是日同至女王城作诗乃和并韵》）比喻人生来去如鸿雁，代代往复，生生不已。但一个人的经历又像春梦一样，去而无踪，难以追怀。可以作为对照。这首词应该是有政治寄托的，周济论词主“有寄托”与“无寄托”之说，以为“非寄托不入”，而“专寄托则不出”。东坡此词能臻此境，在于“非因寄托而为是词”，乃“触发于弗克自己，流露于不自知”。这正是苏轼的才学，气度，思想的体现。', poem_tags = '宋词三百首,豪放,月夜,写景,抒怀,孤独' WHERE poem_title = '卜算子·黄州定慧院寓居作' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '纵目望去，黄河渐行渐远，好像奔流在缭绕的白云中间，就在黄河上游的万仞高山之中，一座孤城玉门关耸峙在那里，显得孤峭冷寂。\n何必用羌笛吹起那哀怨的杨柳曲去埋怨春光迟迟不来呢，原来玉门关一带春风是吹不到的啊！\n\n突厥首领来到中原求和亲，北望自己的领土，看到了边界以北的拂云堆神祠，回想昔日曾经多次在此杀马登台祭祀，然后兴兵犯唐，颇有几分踌躇满志。\n但现在唐朝天子神武超绝，不肯与突厥和亲，此次中原之行只好无功而返。', poem_notes = '凉州词：又名《出塞》。为当时流行的一首曲子《凉州》配的唱词。郭茂倩《乐府诗集》卷七十九《近代曲词》载有《凉州歌》，并引《乐苑》云：“《凉州》，宫调曲，开元中西凉府都督郭知运进。”凉州，属唐陇右道，治所在姑臧县（今甘肃省武威市凉州区）。\n远上：远远向西望去。黄河远上：远望黄河的源头。“河”一作“沙”，“远”一作“直”。\n孤城：指孤零零的戍边的城堡。仞：古代的长度单位，一仞相当于七尺或八尺（约等于213厘米或264cm厘米）。 \n羌笛：古羌族主要分布在甘、青、川一带。羌笛是羌族乐器，属横吹式管乐。何须：何必。杨柳：《折杨柳》曲。古诗文中常以杨柳喻送别情事。《诗经·小雅·采薇》：“昔我往矣，杨柳依依。”北朝乐府《鼓角横吹曲》有《折杨柳枝》，歌词曰：“上马不捉鞭，反拗杨柳枝。下马吹横笛，愁杀行客儿。” \n度：吹到过。玉门关：汉武帝置，因西域输入玉石取道于此而得名。故址在今甘肃敦煌西北小方盘城，是古代通往西域的要道。六朝时关址东移至今安西双塔堡附近。\n单于：古代对匈奴君长的称呼，此指突厥首领。拂云堆：祠庙名，在今内蒙古五原。\n来：语助词，无义。\n春风：某种温暖关怀或某种人间春意春象', poem_appreciation = '其一 　　据唐人薛用弱《集异记》记载：开元（唐玄宗年号，公元713—741年）间，王之涣与高适、王昌龄到旗亭饮酒，遇梨园伶人唱曲宴乐，三人便私下约定以伶人演唱各人所作诗篇的情形定诗名高下。王昌龄的诗被唱了两首，高适也有一首诗被唱到，王之涣接连落空。轮到诸伶中最美的一位女子演唱了，她所唱则为“黄河远上白云间”。王之涣甚为得意。这就是著名的“旗亭画壁”故事。此事未必实有。但表明王之涣这首诗在当时已成为广为传唱的名篇。\n\n　　诗的前两句描绘了西北边地广漠壮阔的风光。首句抓住自下（游）向上（游）、由近及远眺望黄河的特殊感受，描绘出“黄河远上白云间”的动人画面：汹涌澎湃波浪滔滔的黄河竟象一条丝带迤逦飞上云端。写得真是神思飞跃，气象开阔。诗人的另一名句“黄河入海流”，其观察角度与此正好相反，是自上而下的目送；而李白的“黄河之水天上来”，虽也写观望上游，但视线运动却又由远及近，与此句不同。“黄河入海流”和“黄河之水天上来”，同是着意渲染黄河一泻千里的气派，表现的是动态美。而“黄河远上白云间”，方向与河的流向相反，意在突出其源远流长的闲远仪态，表现的是一种静态美。同时展示了边地广漠壮阔的风光，不愧为千古奇句。\n\n　　次句“一片孤城万仞山”出现了塞上孤城，这是此诗主要意象之一，属于“画卷”的主体部分。“黄河远上白云间”是它远大的背景，“万仞山”是它靠近的背景。在远川高山的反衬下，益见此城地势险要、处境孤危。“一片”是唐诗习用语词，往往与“孤”连文（如“孤帆一片”、“一片孤云”等等），这里相当于“一座”，而在词采上多一层“单薄”的意思。这样一座漠北孤城，当然不是居民点，而是戌边的堡垒，同时暗示读者诗中有征夫在。“孤城”作为古典诗歌语汇，具有特定涵义。它往往与离人愁绪联结在一起，如“夔府孤城落日斜，每依北斗望京华”（杜甫《秋兴》）、“遥知汉使萧关外，愁见孤城落日边”（王维《送韦评事》）等等。第二句“孤城”意象先行引入，为下两句进一步刻划征夫的心理作好了准备。\n\n　　诗起于写山川的雄阔苍凉，承以戌守者处境的孤危。第三句忽而一转，引入羌笛之声。羌笛所奏乃《折杨柳》曲调，这就不能不勾起征夫的离愁了。此句系化用乐府《横吹曲辞·折杨柳歌辞》“上马不捉鞭，反折杨柳枝。蹀座吹长笛，愁杀行客儿”的诗意。折柳赠别的风习在唐时最盛。“杨柳”与离别有更直接的关系。所以，人们不但见了杨柳会引起别愁，连听到《折杨柳》的笛曲也会触动离恨。而“羌笛”句不说“闻折柳”却说“怨杨柳”，造语尤妙。这就避免直接用曲调名，化板为活，且能引发更多的联想，深化诗意。玉门关外，春风不度，杨柳不青，离人想要折一枝杨柳寄情也不能，这就比折柳送别更为难堪。征人怀着这种心情听曲，似乎笛声也在“怨杨柳”，流露的怨情是强烈的，而以“何须怨”的宽解语委婉出之，深沉含蓄，耐人寻味。这第三句以问语转出了如此浓郁的诗意，末句“春风不度玉门关”也就水到渠成。用“玉门关”一语入诗也与征人离思有关。《后汉书·班超传》云：“不敢望到酒泉郡，但愿生入玉门关。”所以末句正写边地苦寒，含蓄着无限的乡思离情。如果把这首《凉州词》与中唐以后的某些边塞诗（如张乔《河湟旧卒》）加以比较，就会发现，此诗虽极写戌边者不得还乡的怨情，但写得悲壮苍凉，没有衰飒颓唐的情调，表现出盛唐诗人广阔的心胸。即使写悲切的怨情，也是悲中有壮，悲凉而慷慨。“何须怨”三字不仅见其艺术手法的委婉蕴藉，也可看到当时边防将士在乡愁难禁时，也意识到卫国戌边责任的重大，方能如此自我宽解。也许正因为《凉州词》情调悲而不失其壮，所以能成为“唐音”的典型代表。\n\n其二 　　这首诗反映了唐朝与北方少数民族政权之间的关系，诗中牵涉到唐玄宗对待突厥问题的一些历史事件。开元（唐玄宗年号，713—741）年间，突厥首领小杀曾乞与玄宗为子，玄宗许之。又欲娶公主，玄宗只厚赐而不许和亲。后小杀问唐使袁振，袁振说：“可汗既与皇帝为子，父子岂合为婚姻？”后小杀遣其大臣颉利发入朝贡献，颉利发与玄宗射猎，时有兔起于御马前，玄宗引弓傍射，一发获之。颉利发下马捧兔蹈舞曰：“圣人神武超绝，人间无也。”后来玄宗为其设宴，厚赐而遣之，最终不许和亲。诗中的后两句通过突厥首领心理活动的微妙变化赞颂了唐玄宗的文治武功，说明其威势足以震慑周边少数民族，对于他们的无理要求坚决按原则办事，决不肯对之妥协以求苟安。\n\n　　这首诗，从侧面赞颂了唐朝在处理少数民族关系上的有理有节，借突厥首领求和亲的失望而回反映了唐朝的强大，充满了民族自豪感。', poem_tags = '边疆,地名,民族,组诗' WHERE poem_title = '凉州词二首' AND poem_author = '王之涣';
UPDATE edu_poem SET poem_tags = '端午节' WHERE poem_title = '端午' AND poem_author = '李隆基';
UPDATE edu_poem SET poem_translation = '先帝考虑到蜀汉和曹贼不能并存，帝王之业不能苟且偷安于一地，所以委任臣下去讨伐曹魏。以先帝那样的明察，估量臣下的才能，本来就知道臣下要去征讨敌人，是能力微弱而敌人强大的。但是，不去讨伐敌人，王业也是要败亡的；是坐而待毙，还是主动去征伐敌人呢？因此委任臣下，一点也不犹疑。\n\n　　臣下接受任命的时候，睡不安稳，食无滋味。想到要去北伐，应该先南征。所以五月里渡过泸水，深入不毛之地，两天才能吃上一餐；臣下不是不爱惜自己呵，而是看到帝王之业不可能局处在蜀地而得以保全，所以冒着危险，来执行先帝的遗愿，可是争议者说这不是上策。而敌人恰好在西面疲于对付边县的叛乱，东面又要竭力去应付孙吴的进攻，兵法要求趁敌方劳困时发动进攻，当前正是赶快进军的时机呵！现在谨将这些事陈述如下：\n\n　　高祖皇帝的明智，可以和日月相比，他的谋臣见识广博，谋略深远，但还是要经历艰险，身受创伤，遭遇危难然后才得安定。现在，陛下比不上高祖皇帝，谋臣也不如张良、陈平，而想用长期相持的战略来取胜，安安稳稳地平定天下，这是臣所不能理解的第一点。\n\n　　刘繇、王朗，各自占据州郡；在议论安守策略时，动辄引用古代圣贤的话，大家疑虑满腹，胸中充斥着惧难；今年不去打仗，明年不去征讨，让孙策安然强大起来，终于并吞了江东，这是臣下所不能理解的第二点。\n\n　　曹操的智能谋略，远远超过别人，他用兵像孙武、吴起那样，但是在南阳受到窘困，在乌巢遇上危险，在祁山遭到厄难，在黎阳被敌困逼，几乎惨败在北山，差一点死在潼关，然后才得僭称国号于一时。何况臣下才能低下，而竟想不冒艰险来平定天下，这是臣下所不能理解的第三点。\n\n　　曹操五次攻打昌霸而攻不下；四次想跨越巢湖而未成功，任用李服，而李服密谋对付他；委用夏侯渊，而夏侯渊却败死了。先帝常常称赞曹操有能耐，可还是有这些挫败，何况臣下才能低劣，怎能保证一定得胜呢？这是臣下所不能理解的第四点。\n\n　　自从臣下进驻汉中，不过一周年而已，期间就丧失了赵云、阳群、马玉、阎芝、丁立、白寿、刘郃、邓铜等将领及部曲将官、屯兵将官七十余人；突将、无前、賨叟、青羌、散骑、武骑等士卒一千余人。这些都是几十年内从各处积集起来的精锐力量，不是一州一郡所能拥有的；如果再过几年，就会损失原有兵力的三分之二，那时拿什么去对付敌人呢？这是臣下所不能理解的第五点。\n\n　　如今百姓贫穷兵士疲乏，但战争不可能停息；战争不能停息，那末耽在那里等待敌人来进攻和出去攻击敌人，其劳力费用正是相等的。不趁此时去出击敌人，却想拿益州一地来和敌人长久相持，这是臣下所不能理解的第六点。\n\n　　最难于判断的，是战事。当初先帝兵败于楚地，这时候曹操拍手称快，以为天下已经平定了。但是，后来先帝东面与孙吴连和，西面取得了巴蜀之地，出兵北伐，夏侯渊掉了脑袋；这是曹操估计错误。看来复兴汉室的大业快要成功了。但是，后来孙吴又违背盟约，关羽战败被杀，先帝又在秭归遭到挫败，而曹丕就此称帝。所有的事都是这样，很难加以预料。臣下只有竭尽全力，到死方休罢了。至于伐魏兴汉究竟是成功是失败，是顺利还是困难，那是臣下的智力所不能预见的。', poem_notes = '汉：指蜀汉。贼：指曹魏。古时往往把敌方称为贼。\n偏安：指王朝局处一地，自以为安。\n孰与：何如，表示抉择，倾向肯定后一种（偏指一方）\n惟：助词。\n入南：指诸葛亮深入南中，平定四郡事。\n并日：两天合作一天。\n顾：这里有“但”的意思。蜀都：此指蜀汉之境。\n议者：指对诸葛亮决意北伐发表不同意见的官吏。\n这两句指建兴六年（228）诸葛亮初出祁山（在今甘肃省礼县东）时，曹魏西部的南安、天水、安定三郡叛变，牵动关中局势：在魏、吴边境附近的夹石（今安徽省桐城县北），东吴大将陆逊击败魏大司马曹休两事。\n进趋：快速前进。\n高帝：刘邦死后的谥号为“高皇帝”。并：平列。\n渊深：指学识广博，计谋高深莫测。\n被创：受创伤。这句说：刘邦在楚汉战争中，屡败于楚军，公元前二○三年，在广武（今河南省荥阳县）被项羽射伤胸部：在汉朝初建时，因镇压各地的叛乱而多次出征，公元前一九五年又曾被淮南王英布的士兵射中；公元前二○○年在白登山还遭到匈奴的围困。被，通假字，同“披”\n良：张良，汉高祖的著名谋士，与萧何、韩信被称为“汉初三杰”。平：陈平，汉高祖的著名谋士。后位至丞相。\n长计：长期相持的打算。\n坐：安安稳稳。\n未解：不能理解。胡三省认为“解”应读作“懈”，未解，即未敢懈怠之意。两说皆可通。\n刘繇（yóu由）：字正礼，东汉末年任扬州刺史，因受淮南大军阀袁术的逼迫，南渡长江，不久被孙策攻破，退保豫章（今江西省南昌市），后为豪强笮融攻杀。《三国志·吴书》有传。王朗：字景兴，东汉末年为会稽（治所在今浙江省绍兴市）太守，孙策势力进入江浙时，兵败投降，后为曹操所征召，仕于曹魏。\n孙策：字伯符，孙权的长兄。父孙坚死后，借用袁术的兵力，兼并江南地区，为孙吴政权的建立打下基础，不久遇刺身死。\n江东：指长江中下游地区。\n殊绝：极度超出的意思。\n孙：指孙武，春秋时人，曾为吴国将领，善用兵，著有兵法十三篇。吴：指吴起，战国时兵家、法家代表人物，先后仕于鲁、魏、楚，著有《吴子兵法》。\n困于南阳：建安二年（197）曹操在宛城（今河南省南阳市，汉时南阳郡的治所）为张绣所败，身中流矢。\n险于乌巢：建安五年（200），曹操与袁绍在官渡相持，因乏粮难支，在荀彧等人的劝说下，坚持不退，后焚烧掉袁绍在乌巢所屯的粮草，才得险胜。\n危于祁连：这里的“祁连”，据胡三省说，可能是指邺（在今河北省磁县东南）附近的祁山，当时（204）曹操围邺，袁绍少子袁尚败守祁山（在邺南面），操再败之，并还围邺城，险被袁将审配的伏兵所射中。\n逼（bì逼）于黎阳：建安七年（202）五月，袁绍死，袁谭、袁尚固守黎阳（今河南浚县东），曹操连战不克。\n几败北山：事不详。可能指建安二十四年（219），曹操率军出斜谷，至阳平北山（今陕西沔县西），与刘备争夺汉中，备据险相拒，曹军心涣，遂撤还长安。\n殆死潼关：建安十六年（211），曹操与马超、韩遂战于潼关，在黄河边与马超军遭遇，曹操避入舟中，马超骑兵沿河追射之。殆，几乎。\n伪定：此言曹氏统一北中国，僭称国号。诸葛亮以蜀汉为正统，因斥曹魏为“伪”。\n昌霸：又称昌豨。建安四年（199），刘备袭取徐州，东海昌霸叛曹，郡县多归附刘备。\n四越巢湖：曹魏以合肥为军事重镇，巢湖在其南面。而孙吴在巢湖以南长江边上的须濡口设防，双方屡次在此一带作战。\n李服：建安四年，车骑将军董承根据汉献帝密诏，联络将军吴子兰、王子服和刘备等谋诛曹操，事泄，董承、吴子兰、王服等被杀。据胡三省云：“李服，盖王服也。”\n夏侯：指夏侯渊。曹操遣夏侯渊镇守汉中。刘备取得益州之后，于建安二十四年出兵汉中，蜀将黄忠于阳平关定军山（今陕西省沔县东南）击杀夏侯渊。\n汉中：郡名，以汉水上流（沔水）流经而得名，治所在南郑（今陕西省汉中县东）。\n期（jì寄）年：一周年。\n赵云为蜀中名将，阳群等人事迹不详。曲长、屯将是部曲中的将领。\n突将、无前：蜀军中的冲锋将士。賨（cóng丛）叟、青羌：蜀军中的少数民族部队。散骑、武骑：都是骑兵的名号。\n图：对付。\n夫：发语词。平：同“评”，评断。\n败军于楚：指建安十三年（208），曹操大军南下，刘备在当阳长坂被击溃事。当阳属古楚地，故云。\n拊手：拍手。\n已定：以定，已，同“以”。\n本句指刘备遣诸葛亮去江东连和，孙刘联军在赤壁大破曹军。\n本句指建安十六年（211）刘备势力进入刘璋占据的益州，后来攻下成都，取得巴蜀地区。\n授首：交出脑袋。\n关羽：字云长，蜀汉大将，刘备入川时，镇守荆州，建安二十四年，他出击曹魏，攻克襄阳，擒于禁，斩庞德，威震中原。孙权趁机用吕蒙计谋偷袭荆州，擒杀关羽父子。\n本句指刘备因孙权背盟，袭取荆州，杀害关羽，就亲自领兵伐吴，在秭zi归（在今湖北省宜昌市北）被吴将陆逊所败。蹉跌cuōdiē，失坠，喻失败。\n曹丕：字子桓，曹操子。在公元220年废汉献帝为山阳公，建立魏国，是为魏文帝。\n逆见：预见，预测。\n鞠躬尽力：指为国事用尽全力。一作“鞠躬尽瘁”。\n利钝：喻顺利或困难。\n睹（dǔ赌）：亦即“逆见”，预料。', poem_appreciation = '伪作论据 　　（一）良史陈寿修《三国志》，编《诸葛亮集》，在材料的取舍上是经过审慎斟酌的，但其均未收录此表 　　（二）此表气绥调低，与《前出师表》辞气迥异，非出自一人之手，盖诸葛亮侄儿东吴大将军诸葛恪伪作，目的在于以”此表为他的伐魏主张制造有力的旁证“，因为诸葛恪在《论征魏》一文中曾说：”每览荆邯说公孙述以进取之图，近见家叔父表陈与贼争竞之计，未尝不喟然叹息也“。而“陈与贼争竞之计”的只能是《后出师表》。（或说是张俨伪作）。 　　（三）表中所列史实有误。《赵云传》载云卒于建兴七年，而六年十一月的《后表》却说云已死。\n\n肯定观点 　　（一） 陈寿《亮集》未载此表，不足为伪作之证。 　　陈氏修史编集对史料取舍，确实是经过审慎斟酌的，但却不是完备详尽的。将《亮传》与《武帝纪》相较，前者显然简略的多，诸如伐吴、南征、八阵、渭南之战等理应明确详述的内容，他都一笔带过，或未作记载。 　　又陈寿编《亮集》，主要依据司马氏从成都接收运回洛阳的蜀汉政府档案，这个档案经公元264年钟会成都兵变后已不完整。又考裴注所引诸葛亮“言教书奏”，有一部分明确谓“《亮集》载“；而有一部分非出自《亮集》，如《绝盟好议》出自《汉晋春秋》，《与陆逊书》出自《江表传》等；还有一部分未注明出处，如《公文上尚书》《与李丰教》等。这些都说明陈寿所编《亮集》并不完备。《后表》或因重在分析形势，关乎军情机密，不宜公开宣示，故流传不广；或因成都之乱散失，陈寿未见到。 　　裴松之就是针对《三国志》这种“失在于略，时有脱漏”的情况注补之，且对本文及注引材料每每刻意惩妄论辩，但对《汉晋春秋》所载《后表》只存录而并无疑义，看来裴氏相信这是诸葛亮所作。 　　（二） 所谓前、后表词气迥异、风格不同字观点也是不能令人信服的。 　　《后表》所谓“才弱敌强”，既是诸葛亮转述当初刘备的看法，也是他把蜀汉的总体人才质量、军事力量跟曹操及其庞大的人才群和军事力量作对比后实事求是的结论，它与《前表》中的“今天下三分，益州疲弊，此诚危急存亡之秋也”语义类似。 　　《后表》所谓“夫难平者，事也”，“至于成败利钝，非臣之明所能逆睹也”等语，是在首次北伐失利后，针对议者非料度“必胜”绝不出兵的观点而讲，是就即将二次北伐的战役而言，并不是对兴复汉室、统一全国的长远目标丧失信心，诸葛亮所列举的曹、刘集团成败浮沉的曲折历史完全证明诸葛亮“凡事如是，难可逆见”乃清醒客观之言。所以《后标》并无“志衰气丧”的情调。 　　再看二表的用辞风格也基本一致：《前表》所谓“今南方已定，兵甲已足，当奖率三军，北定中原”，说的是当前的任务，与《后表》“今贼适疲於西，又务於东，兵法乘劳，此进趋之时也”辞义仿佛，所谓“庶竭驽钝，攘除奸凶”，说的是自己的职责和决心，与《后表》“鞠躬尽力，死而后已”之心志一脉相承；所谓“兴复汉室，还于旧都”，指长远的目标，非认为一举大胜，它与《后表》并不矛盾。 　　《后表》与《前表》及诸葛亮其他文章，都有如下共同的特点：讲究对仗排比、有汉赋骈偶特色；音节铿锵，纵横捭阖，回转层叠，说理透彻；感情真挚，语言酣畅平易。所不同的只是，《前表》偏重叙事抒情，《后表》专注于论述批驳，互为补充映照，合之为一完璧，故当出自一人之手。 　　（三） 诸葛恪不可能伪作。 　　建兴六年冬诸葛亮二次伐魏前曾向其兄吴公安督诸葛瑾致书通报军情，言“与贼争竞之计”的《后表》应是此时传送到诸葛瑾手中，而后其子诸葛恪看到，再有吴大鸿胪张俨撰《默记》时收录。 　　假使诸葛恪伪作，他当会大赞叔父，贬抑曹魏，决不会造“难可逆见”一类有余之辞；假使他做伪作的目的是为自己伐魏的乐观主张做“旁证”，则会转引其辞以说服他人，然诸葛恪“见家叔父表”，只是“喟然叹息”而已；诸葛恪“见家叔父表”，在公元253年，时蜀汉尚在，两国使者频往，知情者均在；又诸葛恪作为吴臣，安肯曰“孙策做大，遂并江东乎？”所以，诸葛恪伪作叔父表章是不可能的。而如系张俨伪作，起码首先骗不了诸葛恪这位知情者。 　　至于张俨将《后表》收入《默记》，一则因为俨是主战派（由裴注引《默记·述佐篇》）可见，二则因为《后表》与《默记·述佐篇》体例相符。张俨曰：“余观彼治国之体，当时既肃整，遗教在后，及其辞意恳切，陈进取之图，忠谋謇謇，义形於主。”显然，其“陈进取之图”的，主要当指《后表》，他之所以主战并对诸葛亮屡以弱攻强的进取方针予以肯定，受《后表》的感染当是一个重要原因。 　　（四） 关于赵云死亡时间，可能是《三国志》有误。今但知建兴六年夏初赵云箕谷失利退回褒谷道，其秋子赤崖屯田，其后活动一概不见史载，即使建兴七年春取武都、阴平二郡之重大战事亦不见有赵云出现。由此窥测，赵云有可能卒于建兴六年冬诸葛亮上《后表》前，灵柩运回大邑县（蜀汉蜀郡江原县境）安葬时至七年春，陈寿或有可能因此误记卒年。', poem_tags = '古文观止' WHERE poem_title = '后出师表' AND poem_author = '诸葛亮';
UPDATE edu_poem SET poem_translation = '京城一年一度又是清明，人们的心里自然就起了忧愁思念。\n马车声在路上繁杂地响着，东城的郊外杨柳一片青翠。\n花开了草都长了出来，鸟儿在飞蝴蝶成双成对在嬉戏。\n自己坐在空空的大堂里回忆往昔，以茶代酒，喝着聊着。', poem_notes = '此诗除《全唐诗》外，诸本皆不载，似非孟浩然所作。\n帝里：京都。\n据此句，知作诗时作者不在帝里。\n茗：茶。按，饮茶之风，似始盛于中唐以后，盛唐时尚不多见。', poem_tags = '清明节,写景,怀人' WHERE poem_title = '清明即事' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '天啊！请问世间的各位，爱情究竟是什么，竟会令这两只飞雁以生死来相对待？\n南飞北归遥远的路程都比翼双飞，任它多少的冬寒夏暑，依旧恩爱相依为命。\n比翼双飞虽然快乐，但离别才真的是楚痛难受。到此刻，方知这痴情的双雁竟比人间痴情儿女更加痴情！\n相依相伴，形影不离的情侣已逝，真情的雁儿心里应该知道，此去万里，形孤影单，前程渺渺路漫漫，每年寒暑，飞万里越千山，晨风暮雪，失去一生的至爱，形单影只，即使苟且活下去又有什么意义呢？\n这汾水一带，当年本是汉武帝巡幸游乐的地方，每当武帝出巡，总是箫鼓喧天，棹歌四起，何等热闹，而今却是冷烟衰草，一派萧条冷落。\n武帝已死，招魂也无济于事。女山神因之枉自悲啼，而死者却不会再归来了！\n双雁生死相许的深情连上天也嫉妒，殉情的大雁决不会和莺儿燕子一般，死后化为一抔尘土。\n将会留得生前身后名，与世长存。狂歌纵酒，寻访雁丘坟故地，来祭奠这一对爱侣的亡灵。', poem_notes = '《摸鱼儿》：一名《摸鱼子》，又名《买陂塘》、《迈陂塘》、《双蕖怨》等。唐教坊曲，后用为词牌。宋词以晁补之《琴趣外篇》所收为最早。双片一百一十六字，前片六仄韵，后片七仄韵。双结倒数第三句第一字皆领格，宜用去声。\n乙丑岁：金章宗泰和五年（公元1205年），以天干地支纪年为乙丑年，当时元好问年仅十六岁。\n赴试并州：《金史·选举志》载：金代选举之制，由乡至府，由府至省及殿试，凡四试。明昌元年罢免乡试。府试试期在秋八月。府试处所承安四年赠太原，共为十处。\n识（zhì）：标志。\n雁丘：嘉庆《大清一统志》：雁丘在阳曲县西汾水旁。金元好问赴府试……累土为丘，作《雁丘词》。\n无宫商：不协音律。\n直教：竟使。许：随从。\n双飞客：大雁双宿双飞，秋去春来，故云。\n“就中”句：这雁群中更有痴迷于爱情的。\n“君应”四句：万里长途，层云迷漫，千山暮景，处境凄凉，形影孤单为谁奔波呢？\n“横汾”三句：这葬雁的汾水，当年汉武帝横渡时何等热闹，如今寂寞凄凉。汉武帝《秋风辞》：“泛楼船兮济汾河，横中流兮扬素波，箫鼓鸣兮发棹歌。”平楚：楚指丛木。远望树梢齐平，故称平楚。\n“招魂”二句：我欲为死雁招魂又有何用，雁魂也在风雨中啼哭。招魂楚些（suò）：《楚辞·招魂》句尾皆有“些”字。何嗟及：悲叹无济于事。山鬼：《楚辞·九歌·山鬼》篇指山神，此指雁魂。\n暗啼：一作“自啼”。\n“天也”二句：不信殉情的雁子与普通莺燕一样都寂灭无闻变为黄土，它将声明远播，使天地忌妒。\n骚人：诗人。', poem_appreciation = '此词作于金宣宗泰和五年（1205）遗山十六岁时，虽晚年曾经改定，然大体则为原作。词的上片在小序已叙事情梗概的基础上追寻殉情成因：前七句以我观物，放眼于巨大的时空中突出其长久厮守，同甘共苦、相依为命的深情厚感；后四句以我度物，模拟死雁之口，说出其殉情的原因。下片写凭吊，前三句渲染雁丘所处环境的冷落寂寞；“招魂”二句叙述为雁招魂及雁魂之凄苦；“天也妒”二句论断为情而死必将流芳千古；末四句点出垒筑雁丘的用意。\n\n　　这首咏物诗通过对雁的生活和心理体贴入微的描写及雁丘凄凉环境的渲染，谱写了一曲凄恻动人的恋情悲歌，歌颂了大雁同生共死的“至情”。拟人手法的运用，打通了人与物的界限，使歌颂的“至情”扩展的世间万物。词以抒情为主，多用议论口吻，景因情设，随意挥洒，将凄伤的爱情悲剧写得跌宕澎湃，慷慨激越，可谓“婀娜中含刚健”。', poem_tags = '咏物,写鸟,抒情,爱情' WHERE poem_title = '摸鱼儿·雁丘词 / 迈陂塘' AND poem_author = '元好问';
UPDATE edu_poem SET poem_translation = '采莲少女的绿罗裙融入到田田荷叶中，仿佛一色，少女的脸庞掩映在盛开的荷花间，相互映照。\n混入莲池中不见了踪影，听到歌声四起才觉察到有人前来。', poem_notes = '罗裙：用细软而有疏孔的丝织品制成的裙子。\n一色裁：像是用同一颜色的衣料剪裁的。\n芙蓉：指荷花。\n乱入：杂入、混入。\n看不见：指分不清哪是芙蓉的绿叶红花，哪是少女的绿裙红颜。\n闻歌：听到歌声。\n始觉：才知道。', poem_appreciation = '“荷叶罗裙一色裁 ，芙蓉向脸两边开”。诗歌在开始就展现出一幅人与环境和谐统一的美丽画面采莲女的罗裙和荷叶的颜色一样青翠欲滴。比喻虽不新奇，但用在此处却产生意想不到的效果，既描绘了田田的荷叶，又写了采莲女美丽的衣裳，两者相互映衬，恍若一体。尤其是“裁”字，用得极其巧妙，罗裙是裁出的，可是此处也用在荷叶上，似从贺知章《咏柳》诗“不知细叶谁裁出？二月春风似剪刀”句中得到了灵感，让人感到荷叶与罗裙不仅颜色相同，似乎也是同一双巧手以同一种材料制成的。由此又让人不禁联想到屈原《离骚》中“制芰荷以为衣兮，集芙蓉以为裳”，感受到这些女子如荷花般的心灵。娇艳的芙蓉花似乎都朝着采莲女美丽的脸庞开放，明写荷花，实则为了衬出人之美，采莲女的美丽，不是闭月羞花式的惊艳，而是如阳光般健康温暖，似乎能催开满池的荷花。这两句诗本自梁元帝《碧玉诗》“莲花乱脸色，荷叶杂衣香”，王昌龄的这篇较之则更胜一筹，意义更为隽永。\n\n　　“乱入池中看不见，闻歌始觉有人来“。诗的第三句“ 乱入池中看不见” 是对前两句的补充和深入。它有两重含义：一是突出荷田的稠密, 使人荷莫辨更真实可信；二是突出了观望者的感受和心理活动。其中“ 乱” 字用得十分微妙。末句“ 闻歌始觉有人来” 除了从另一面说明少女被荷田遮蔽与消融，难以被观望者发现以外，又写出一种声音的美，增添了诗的活泼情趣“。乱”字既指采莲女纷纷入池嬉笑欢闹的场面，也可指人与花同样娇嫩难以辨别，眼前一乱的感觉而“看不见”呼应上文，也更显荷叶罗裙，芙蓉人面之想像了，同时也虚写了荷塘中花叶繁茂，人在其中若隐若现之景，并引出下句：“闻歌始觉有人来。”这一句描写细腻入微，仿佛让读者身临其境地体会到了诗人当时真实的感受。“始觉”与上句“看不见”呼应，共同创造出了一种“莲花过人头”的意境。“闻歌”也与“乱”字呼应，悠扬动听的歌声表现出她们活泼开朗的天性，同时也为整个采莲的场景添上了动人的一笔。\n\n　　这首诗句与句联系紧密，意蕴深远，精雕细琢却给人带来清丽自然之感，可以看出王昌龄炼字炼意的高超技艺，对中晚唐的诗歌有着重要的影响。', poem_tags = '写景,少女' WHERE poem_title = '采莲曲' AND poem_author = '王昌龄';
UPDATE edu_poem SET poem_translation = '击鼓的声音震响（耳旁），兵将奋勇操练。（人们）留在国内筑漕城，只有我向南方行去。\n跟随孙子仲，平定陈、宋（两国）。不允许我回家，（使我）忧心忡忡。\n于是人在哪里？于是马跑失在哪里？到哪里去寻找它？在山间林下。\n生死聚散，我曾经对你说（过）。拉着你的手，和你一起老去。\n唉，太久。让我无法（与你）相会。唉，太遥远，让我的誓言不能履行。', poem_notes = '镗：鼓声。其镗，即“镗镗”。明 陈继儒《大司马节寰袁公（袁可立）家庙记》：“喤喤考钟，坎坎击鼓。” \n踊跃：双声连绵词，犹言鼓舞。兵：武器，刀枪之类。\n土国：在国都服役。漕：地名。\n孙子仲：即公孙文仲，字子仲，邶国将领。\n平：和也，和二国之好。谓救陈以调和陈宋关系。陈、宋：诸侯国名。\n不我以归：即不以我归，有家不让回。\n有忡：忡忡。\n爰（yuán）：本发声词，犹言“于是”。丧：丧失，此处言跑失。爰居爰处？爰丧其马：有不还者，有亡其马者。\n于以：于何。\n契阔：聚散。契，合；阔，离。\n成说：成言也犹言誓约。\n于嗟：即“吁嗟”，犹言今之哎哟。\n活：借为“佸”，相会。\n洵：远。\n信：一说古伸字，志不得伸。一说誓约有信。', poem_appreciation = '这是一篇典型的战争诗。诗人以袒露自身与主流意识的背离，宣泄自己对战争的抵触情绪。作品在对人类战争本相的透视中，呼唤的是对个体生命具体存在的尊重和生活细节幸福的获得。这种来自心灵深处真实而朴素的歌唱，是对人之存在的最具人文关 怀的阐释，是先民们为后世的文学作品树立起的一座人性高标。\n\n　　《毛诗序》云：“《击鼓》，怨州吁也。”郑笺以《左传·隐公四年》州吁伐郑之事实之。姚际恒《诗经通论》以为“与经不合者六”，此实乃《春秋·宣公十二年》“宋师伐陈，卫人救陈”之事，在卫穆公时。今以为姚说较《毛序》为合理，姑从姚氏。\n\n　　第一章总言卫人救陈，平陈宋之难，叙卫人之怨。结云“我独南行”者，诗本以抒写个人愤懑为主，这是全诗的线索。诗的第三句言“土国城漕”者，《鄘风·定之方中》毛诗序云：“卫为狄所灭，东徙渡河，野居漕邑，齐桓公攘夷狄而封之。文公徙居楚丘，始建城市而营宫室。”文公营楚丘，这就是诗所谓“土国”，到了穆公，又为漕邑筑城，故诗又曰“城漕”。“土国城漕”虽然也是劳役，犹在国境以内，南行救陈，其艰苦就更甚了。\n\n　　第二章“从孙子仲，平陈与宋”，承“我独南行”为说。假使南行不久即返，犹之可也。诗之末两句云“不我以归，忧心有忡”，叙事更向前推进，如芭蕉剥心，使人酸鼻。\n\n　　第三章写安家失马，似乎是题外插曲，其实文心最细。《庄子》说：“犹系马而驰也。”好马是不受羁束、爱驰骋的；征人是不愿久役、想归家的。这个细节，真写得映带人情。毛传解释一二句为：“有不还者，有亡其马者。”把“爰”解释为“或”，作为代词，则两句通叙营中他人。其实全诗皆抒诗人一己之情，所以四、五两章文情哀苦，更为动人。\n\n　　第四章“死生契阔”，毛传以“契阔”为“勤苦”是错误的。黄生《义府》以为“契，合也；阔，离也；与死生对言”是正确的。至于如何解释全章诗义。四句为了把叶韵变成从AABB式，次序有颠倒，前人却未尝言及。今按此章的原意，次序应该是：\n\n　　执子之手，与子成说；死生契阔，与子偕老。\n\n　　这样诗的韵脚，就成为ABBA式了。本来“死生契阔，与子偕老”，是“成说”的内容，是分手时的信誓。诗为了以“阔”与“说”叶韵，“手”与“老”叶韵，韵脚更为紧凑，诗情更为激烈，所以作者把语句改为这一次序。\n\n　　第五章“于嗟阔兮”的“阔”，就是上章“契阔”的“阔”。“不我活兮”的“活”，应该是上章“契阔”的“契”。所以“活”是“佸”的假借，“佸，会也。”“于嗟洵兮”的“洵”，应该是“远”的假借，所以指的是“契阔”的“阔”。“不我信兮”的“信”，应该是“信誓旦旦”的“信誓”，承上章“成说”而言的。两章互相紧扣，一丝不漏。\n\n　　“怨”是《击鼓》一诗的总体格调与思想倾向。从正面言，诗人怨战争的降临，怨征役无归期，怨战争中与己息息相关的点滴幸福的缺失，甚至整个生命的丢失。从反面言，诗作在个体心理，行为与集 体要求的不断背离中，在个体生命存在与国家战事的不断抗衡中，在小我的真实幸福对战争的残酷的不断颠覆中，流显出一份从心底而来的厌战情绪。这一腔激烈的厌战之言，要争取的是对个体生命存在的尊重，是生活细节中的切实幸福。', poem_tags = '诗经,抒情,战争' WHERE poem_title = '击鼓' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '微风吹拂着江岸的细草，那立着高高桅杆的小船在夜里孤零地停泊着。\n星星垂在天边，平野显得宽阔；月光随波涌动，大江滚滚东流。\n我难道是因为文章而著名吗？年老病多也应该休官了。\n自己到处漂泊像什么呢？就像天地间的一只孤零零的沙鸥。', poem_notes = '岸：指江岸边。\n危樯（qiáng）：高竖的桅杆。危，高。樯，船上挂风帆的桅杆。\n独夜舟：是说自己孤零零的一个人夜泊江边。\n星垂平野阔：星空低垂，原野显得格外广阔。\n月涌：月亮倒映，随水流涌。大江：指长江。\n名岂：这句连下句，是用“反言以见意”的手法写的。杜甫确实是以文章而著名的，却偏说不是，可见另有抱负，所以这句是自豪语。休官明明是因论事见弃，却说不是，是什么老而且病，所以这句是自解语了。\n官应老病休：官倒是因为年老多病而被罢退。应，认为是、是。\n飘飘：飞翔的样子，这里含月“飘零”、“飘泊”的意思，因为这里是借沙鸥以写人的飘泊。', poem_appreciation = '诗的前半描写“旅夜”的情景。第一、二句写近景：微风吹拂着江岸上的细草，竖着高高桅杆的小船在月夜孤独地停泊着。当时杜甫离成都是迫于无奈。这一年的正月，他辞去节度使参谋职务，四月，在成都赖以存身的好友严武死去。处此凄孤无依之境，便决意离蜀东下。因此，这里不是空泛地写景，而是寓情于景，通过写景展示他的境况和情怀：像江岸细草一样渺小，像江中孤舟一般寂寞。第三、四句写远景：明星低垂，平野广阔；月随波涌，大江东流。这两句写景雄浑阔大，历来为人所称道。在这两个写景句中寄寓着诗人的什么感情呢？有人认为是“开襟旷远”（浦起龙《读杜心解》），有人认为是写出了“喜”的感情（见《唐诗论文集·杜甫五律例解》）。很明显，这首诗是写诗人暮年飘泊的凄苦景况的，而上面的两种解释只强调了诗的字面意思，这就很难令人信服。实际上，诗人写辽阔的平野、浩荡的大江、灿烂的星月，正是为了反衬出他孤苦伶仃的形象和颠连无告的凄怆心情。这种以乐景写哀情的手法，在古典作品中是经常使用的。如《诗经·小雅·采薇》“昔我往矣，杨柳依依”，用春日的美好景物反衬出征士兵的悲苦心情，写得多么动人！\n\n　　诗的后半是“书怀”。第五、六句说，有点名声，哪里是因为我的文章好呢？做官，倒应该因为年老多病而退休。这是反话，立意至为含蓄。诗人素有远大的政治抱负，但长期被压抑而不能施展，因此声名竟因文章而著，这实在不是他的心愿。杜甫此时确实是既老且病，但他的休官，却主要不是因为老和病，而是由于被排挤。这里表现出诗人心中的不平，同时揭示出政治上失意是他飘泊、孤寂的根本原因。关于这一联的含义，黄生说是“无所归咎，抚躬自怪之语”（《杜诗说》），仇兆鳌说是“五属自谦，六乃自解”（《杜少陵集详注》），恐怕不很妥当。最后两句说，飘然一身象个什么呢？不过象广阔的天地间的一只沙鸥罢了。诗人即景自况以抒悲怀。水天空阔，沙鸥飘零；人似沙鸥，转徙江湖。这一联借景抒情，深刻地表现了诗人内心飘泊无依的感伤，真是一字一泪，感人至深。\n\n　　王夫之《姜斋诗话》说：“情景虽有在心在物之分，而景生情，情生景，互藏其宅。”情景互藏其宅，即寓情于景和寓景于情。前者写宜于表达诗人所要抒发的情的景物，使情藏于景中；后者不是抽象地写情，而是在写情中藏有景物。杜甫的这首《旅夜书怀》诗，就是古典诗歌中情景相生、互藏其宅的一个范例。\n\n　　全诗景情交融，景中有情。整首诗意境雄浑，气象万千。用景物之间的对比，烘托出一个独立于天地之间的飘零形象，使全诗弥漫着深沉凝重的孤独感。这正是诗人身世际遇的写照。\n\n　　大历三年（768年），迟暮之年的诗人终于乘舟出了三峡，来到湖北荆门，心境不免孤寂。 此诗开头四句写“旅夜”：岸上有细草微风，江上只有一叶孤舟，依岸而宿，就舟而居，遥望原野，远处天与地似乎相接了，天边的星宿也仿佛下垂得接近地面。大江之中，江水浩浩荡荡东流，一轮明月映照在江水中，随着江水的流动而浮荡着。岸上星垂，舟前月涌，用“星垂”来描写原野的广阔，用“月涌”来形容大江的东流，形象而细致地描绘了江上的夜景。唯有在广阔的原野上才可感到“星垂”；唯其“星垂”，才能见出原野的广阔。而大江中有“月涌”，才能反映出江水的流动；也只因江水的流动，才能感到“月涌”。“星垂”、“月涌”是以细腻称阔大的手法，首四句塑造了一个宏阔非凡宁静孤寂的江边夜境。\n\n　　后四句书“怀”：“名岂文章著”，声名不因政治抱负而显著，反因文章而显著，这本非自己的矢志，故说“岂”，这就流露出因政治理想不得实现的愤慨。说“官应老病休”， 诗人辞去官职，并非因老而多病，什么原因，诗人没有直接说出。说“应”当，本是不应当，正显出老诗人悲愤的心情。面对辽阔寂寥的原野，想起自己的痛苦遭遇，深感自己漂泊无依，在这静夜孤舟的境界中自己恰如是天地间无所依存的一只沙鸥。以沙鸥自况，乃自伤飘泊之意。', poem_tags = '唐诗三百首,写景,抒怀,孤独' WHERE poem_title = '旅夜书怀' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '面对着潇潇暮雨从天空洒落在江面上，经过一番雨洗的秋景，分外寒凉清朗。凄凉的霜风一阵紧似一阵，关山江河一片冷清萧条，落日的余光照耀在高楼上。到处红花凋零翠叶枯落，一切美好的景物渐渐地衰残。只有那滔滔的长江水，不声不响地向东流淌。\n不忍心登高遥看远方，眺望渺茫遥远的故乡，渴求回家的心思难以收拢。叹息这些年来的行踪，为什么苦苦地长期停留在异乡？想起美人，正在华丽的楼上抬头凝望，多少次错把远处驶来的船当作心上人回家的船。她哪会知道我，倚着栏杆，愁思正如此的深重。', poem_notes = '潇潇：风雨之声。\n一番洗清秋：一番风雨，洗出一个凄清的秋天。\n霜风凄紧：秋风凄凉紧迫。霜风，秋风。凄紧，一作“凄惨”。\n是处红衰翠减：到处花草凋零。是处，到处。红，翠，指代花草树木。语出李商隐《赠荷花》诗：“翠减红衰愁杀人。”\n苒（rǎn）苒：渐渐。\n渺邈：遥远。\n淹留：久留。\n颙（yóng）望：抬头远望。\n误几回、天际识归舟：多少次错把远处驶来的船当作心上人回家的船。语出谢朓《之宣城郡出新林浦向板桥》：“ 天际识归舟，云中辩江树。”\n争：怎。\n恁（nèn）：如此。凝愁：忧愁凝结不解。', poem_appreciation = '词中表达了作者常年宦游在外，于清秋薄暑时分，感叹漂泊的生涯和思念情人的心情。这种他乡做客叹老悲秋的主题，在封建时代文人中带有普遍意义。但作者在具体抒情上，具有特色。\n\n　　词的上片写作者登高临远，景物描写中融注着悲凉之感。一开头，总写秋景，雨后江天，澄澈如洗。头两句“对潇潇暮雨洒江天，一番洗清秋。”用“对”字作领字，勾画出词人正面对着一幅暮秋傍晚的秋江雨景。“洗”字生动真切，潜透出一种情心。“潇”和“洒”字，用来形容暮雨，仿佛使人听到了雨声，看到了雨的动态。接着写高处景象，连用三个排句：“渐霜风凄惨，关何冷落，残照妆楼。”进一步烘托凄凉、萧索的气氛，连一向鄙视柳词的苏轼也赞叹“此语于诗句不减唐人高处”（赵令畴《侯鲭录》）。所谓“不减唐人高处”，主要是指景中有情，情景交融，悲壮阔大；凄冷的寒风和着潇潇暮雨紧相吹来，关山江河都冷落了，残日的余辉映照着作者所在的高楼，所写的每一个景色里，都渗透着作者深沉的感情。这三句由“渐”字领起。雨后傍晚的江边，寒风渐冷渐急，身上的感觉如此，眼前看到的也是一片凄凉。“关河”星是冷落的，词人所在地也被残阳笼罩，同样是冷落的，景色苍茫辽阔，境界高远雄浑，勾勒出深秋雨后的一幅悲凉图景，也渗透进了天涯游客的忧郁伤感。 “是处红衰翠减，苒苒物华休。” 这两句写低处所见，到处花落叶败，万物都在凋零，更引起作者不可排解的悲哀。这既是景物描写，也是心情抒发，看到花木都凋零了，自然界的变化不能不引起人的许多感触，何况又是他乡做客之人。作者却没明说人的感触，而只用“长江无语东流”来暗示出来。词人认为“无语”便是无情。“惟有”二字暗示“红衰翠减”的花木不是无语无情的，登高临远的旅人当然更不是无语无情的，只有长江水无语东流，对长江水的指责无理而有情。在无语东流的长江水中，寄托了韶华易逝的感慨。\n\n　　上片以写景为主，但景中有情，从高到低，由远及近，层层铺叙，把大自然的浓郁秋气与内心的悲哀感慨完全融合在一起，淋漓酣畅而又兴象超远。\n\n　　词的下片由景转入情，由写景转入抒情。写对故乡亲人的怀念，换头处即景抒情，表达想念故乡而又不忍心登高，怕引出更多的乡思的矛盾心理。从上片写到的景色看，词人本来是在登高临远，而下片则用“不忍登高临远”一句，“不忍”二字领起，在文章方面是转折翻腾，在感情方面是委婉伸屈。登高临远是为了看看故乡，故乡太远是望而不见，看到的则更是引起相思的凄凉景物，自然使人产生不忍的感情。“望故乡渺邈，归思难收”，实际上这是全词中心。“叹年来踪迹，何事苦淹留。”这两句向自己发问，流露出不得已而淹留他乡的凄苦之情，回顾自己落魄江湖，四处漂泊的经历。扪心问声究竟是为了什么原因。问中带恨，发泄了被人曲意有家难归的深切的悲哀。有问无答，因为诗人不愿说出来，显得很含蕴。一个“叹”字所传出的是千思百回的思绪，和回顾茫然的神态，准确而又传神。“想佳人，妆楼颙望，误几回，天际识归舟？” 又从对方写来，与自己倚楼凝望对照，进一步写出两地想念之苦，并与上片寂寞凄清之景象照应。虽说是自己思乡，这里却设想着故乡家人正盼望自己归来。佳人怀念自己，处于想象。本来是虚写，但词人却用“妆楼颙望，误几回，天际识归舟”这样的细节来表达怀念之情。仿佛实有其事，见人映己，运虚于实，情思更为悱侧动人。结尾再由对方回到自己，说佳人在多少次希望和失望之后，肯定会埋怨自己不想家，却不知道“倚阑”远望之时的愁苦。“倚阑”、“凝愁”本是实情，但却从对方设想用“争知我”领起，化实为虚，显得十分空灵，感情如此曲折，文笔如此变化，实在难得。结尾与开头相呼应，理所当然地让人认为一切景象都是“倚阑”所见，一切归思都由“凝愁”引出，生动地表现了思乡之苦和怀人之情。\n\n　　全词一层深一层，一步接一步，以铺张扬厉的手段，曲折委婉地表现了登楼凭栏，望乡思亲的羁旅之情。通篇结构严密，迭宕开阖，呼应灵活，首尾照应，很能体现柳永词的艺术特色。', poem_tags = '宋词三百首,高中古诗,写景,抒情,哲理,怀人' WHERE poem_title = '八声甘州·对潇潇暮雨洒江天' AND poem_author = '柳永';
UPDATE edu_poem SET poem_translation = '春天还没有过去，微风细细，柳枝斜斜随之起舞。登上超然台远远眺望，护城河只半满的春水微微闪动，城内则是缤纷竞放的春花。更远处，家家瓦房均在雨影之中。\n寒食节过后，酒醒反而因思乡而叹息不已，只得自我安慰：不要在老朋友面前思念故乡了，姑且点上新火来烹煮一杯刚采的新茶，作诗醉酒都要趁年华尚在啊。', poem_notes = '望江南：原唐教坊曲名，后用为词牌名。又名“忆江南”。\n超然台：筑在密州（今山东诸城）北城上，登台可眺望全城。\n壕：护城河。\n寒食：节令。旧时清明前一天（一说二天）为寒食节。\n咨嗟：叹息、慨叹。\n故国：这里指故乡、故园。\n新火：唐宋习俗，清明前二天起，禁火三日。节后另取榆柳之火称“新火”。新茶：指清明前采摘的“雨前茶”。', poem_appreciation = '公元1074年（宋神宗熙宁七年）秋，苏轼由杭州移守密州（今山东诸城）。次年八月，他命人修葺城北旧台，并由其弟苏辙题名“超然”，取《老子》“虽有荣观，燕处超然”之义。公元1076年（熙宁九年）暮春，苏轼登超然台，眺望春色烟雨，触动乡思，写下了此作。这首豪迈与婉约相兼的词，通过春日景象和作者感情、神态的复杂变化，表达了词人豁达超脱的襟怀和“用之则行，舍之则藏”的人生态度。词的上片写登台时所见暮春时节的郊外景色。\n\n　　首以春柳在春风中的姿态——“风细柳斜斜”，点明当时的季节特征：春已暮而未老。“试上”二句，直说登临远眺，而“半壕春水一城花”，在句中设对，以春水、春花，将眼前图景铺排开来。然后，以“烟雨暗千家”作结，居高临下，说烟雨笼罩着千家万户。于是，满城风光，尽收眼底。作者写景，注意色彩上的强烈对比作用，把春日里不同时空的色彩变幻，用明暗相衬的手法传神地传达出来。\n\n　　下片写情，乃触景生情，与上片所写之景，关系紧密。“寒食后，酒醒却咨嗟”，进一步将登临的时间点明。寒食，在清明前二日，相传为纪念介子推，从这一天起，禁火三天；寒食过后，重新点火，称为“新火”。此处点明“寒食后”，一是说，寒食过后，可以另起“新火”，二是说，寒食过后，正是清明节，应当返乡扫墓。但是，此时却欲归而归不得。以上两句，词情荡漾，曲折有致，寄寓了作者对故国、故人不绝如缕的思念之情。“休对故人思故国，且将新火试新茶”写作者为摆脱思乡之苦，借煮茶来作为对故国思念之情的自我排遣，既隐含着词人难以解脱的苦闷，又表达出词人解脱苦闷的自我心理调适。\n\n　　“诗酒趁年华”，进一步申明：必须超然物外，忘却尘世间一切，而抓紧时机，借诗酒以自娱。“年华”，指好时光，与开头所说“春未老”相应合。全词所写，紧紧围绕着“超然”二字，至此，进入了“超然”的最高境界。这一境界，便是苏轼在密州时期心境与词境的具体体现。\n\n　　这首词情由景发，情景交融。词中浑然一体的斜柳、楼台、春水、城花、烟雨等暮春景象，以及烧新火、试新茶的细节，细腻、生动的表现了作者细微而复杂的内心活动，表达了游子炽烈的思乡之情。将写异乡之景与抒思乡之情结合得如此天衣无缝，足见作者艺术功力之深。\n\n　　这首词上片写景，下片抒情，是典型的借景抒情。上片之景，有“以乐景衬哀情”的成分，寄寓作者对有家难回、有志难酬的无奈与怅惘。更重要的是，整首词表达思乡的感情，作者以茶聊以慰藉尤其突出。', poem_tags = '春天,写景,抒情,思乡' WHERE poem_title = '望江南·超然台作' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '白天鹅啊白天鹅，脖颈弯弯，向天欢叫。\n洁白的羽毛，漂浮在碧绿水面；红红的脚掌，拨动着清清水波。', poem_notes = '曲项：弯着脖子。歌：长鸣。\n拨：划动。', poem_appreciation = '诗的第一句连用三个“鹅’字，这种反复咏唱方法的使用，表达了诗人对鹅的热爱，增强了感情上的效果。\n\n　　第二句写鹅鸣叫的神态，给人以声声入耳之感。鹅的声音高亢嘹亮，一个“曲”字，把鹅伸长脖子，而且仰头弯曲着嘎嘎嘎地朝天长鸣的形象写得十分生动。这句先写所见，再写所听，极有层次。\n\n　　以上是写鹅在陆地上行进中的情形，下面两句则写鹅群到水中悠然自得游泳的情形。小诗人用一组对偶句，着重从色彩方面来铺叙鹅群戏水的情况。鹅儿的毛是白的，而江水却是绿的，“白”“绿”对照，鲜明耀眼，这是当句对；同样，鹅掌是红的，而水波是青的，“红”“青”映衬，十分艳丽，这也是当句对。而两句中又“白”“红”相对，“绿”“青”相对，这是上下对。这样，回环往复，都是对仗，其妙无穷。\n\n　　在这组对偶句中，动词的使用也恰到好处。“浮”字说明鹅儿在水中悠然自得，一动不动。“拨”字则说明鹅儿在水中用力划水，以致掀起了水波。这样，动静相生，写出了一种变化美。', poem_tags = '咏物,早教古诗100首' WHERE poem_title = '咏鹅' AND poem_author = '骆宾王';
UPDATE edu_poem SET poem_translation = '我被江边上的春花弄得烦恼不堪，无处讲述这种心倩只好到处乱走。\n来到南邻想寻找酷爱饮酒的伙伴，不料他床已空十天前便外出饮酒。\n\n繁花乱蕊像锦绣一样裹住江边，脚步歪斜走入其间心里着实怕春天。\n不过眼下诗和酒还能听我驱遣，不必为我这白头人有什么心理负担。\n\n深江岸边静竹林中住着两三户人家，撩人的红花映衬着白花。\n我有去处来报答春光的盛意，酒店的琼桨可以送走我的年华。\n\n东望少城那里鲜花如烟，高高的白花酒楼更是解人眼馋。\n谁能携酒召我前往畅饮，唤来美人欢歌笑舞于盛席华筵？\n\n来到黄师塔前江水的东岸，又困又懒沐浴着和煦春风。\n一株无主的桃花开得正盛，我该爱那深红还是爱浅红？\n\n黄四娘家花儿茂盛把小路遮蔽，万千花朵压弯枝条离地低又低。\n眷恋芬芳花间彩蝶时时在飞舞，自由自在娇软黄莺恰恰欢声啼。\n\n并不是说爱花爱得就要死，只因害怕花尽时迁老境逼来。\n花到盛时就容易纷纷飘落，嫩蕊啊请你们商量着慢慢开。', poem_notes = '江：指作者在成都的草堂边的浣花溪。独步：独自散步。\n彻：已，尽。\n颠狂：放荡不羁。颠，即“癫”。\n南邻：指斛斯融。诗原注：“斛斯融，吾酒徒。”\n旬：十日为一旬。\n稠：密。畏（wēi）：通“隈”，山水弯曲处。一作“里”。\n行步：脚步。欹（qī）：歪斜。实：一作“独”。\n在：语助词，相当于“得”。一说“在”相当于“时”。\n料理：安排、帮助。白头人：老人。诗中是作者自指。\n多事：这里有撩人之意。\n送：打发。生涯：生活。\n少城：小城。成都原有大城和少城之分，小城在大城西面。《元和郡县志》载，少城在成都县西南一里。\n可怜：可爱。\n盏：一作“锁”。\n佳人：指官妓。秀筵：丰盛的筵席。\n黄师塔：和尚所葬之塔。陆游《老学庵笔记》：余以事至犀浦，过松林甚茂，问驭卒，此何处？答曰：“师塔也。蜀人呼僧为师，葬所为塔，乃悟少陵“黄师塔前”之句。\n懒困：疲倦困怠。\n无主：自生自灭，无人照管和玩赏。\n爱：一作“映”，一作“与”。\n黄四娘：杜甫住成都草堂时的邻居。蹊（xī）：小路。\n留连：即留恋，舍不得离去。\n娇：可爱的样子。恰恰：象声词，形容鸟叫声音和谐动听。一说“恰恰”为唐时方言，恰好之意。\n爱：一作“看”。肯：犹“拼”。一作“欲”，一作“索”。\n纷纷：多而杂乱。\n嫩蕊：指含苞待放的花。', poem_appreciation = '春暖花开的时节，杜甫本想寻伴同游赏花，未能寻到，只好独自在成都锦江江畔散步，每经历一处，写一处；写一处，又换一意；一连成诗七首，共成一个体系，同时每首诗又自成章法。这组诗，第一首写独步寻花的原因从恼花写起，颇为突兀，见出手不凡。第二首写行至江滨见繁花之多，忽曰怕春，语极奇异，实际上是反语见意。第三首写某些人家的花，红白耀眼，应接不暇。第四首则写遥望少城之花，想象其花之盛与人之乐。第五首写黄师塔前之桃花，第六首写黄四娘家尽是花，第七首总结赏花、爱花、惜花。这组诗脉络清楚，层次井然，是一幅独步寻花图。它表现了杜甫对花的惜爱、在美好生活中的留连和对关好事物常在的希望。\n\n　　这组诗，每首都紧扣着寻花题意来写，每首都有花。第一首起句的“江上被花恼不彻”和末首的“不是看花即欲死”遥相呼应，真如常山蛇，扣首则尾应，扣尾则首应，而其中各首都抓绘着赏花、看花，贯串到底。\n\n　　第一首：“江上被花恼不彻”，花恼人，实际上是花惹人爱。花在江上，花影媚水，水光花色，更是可爱。“颠狂”两字把爱花的情态刻画得淋漓尽致。于是诗人觅伴赏花，“走觅南邻爱酒伴”。可知杜甫是找他的邻居一同赏花的。“经旬出饮独空床”，明写这位爱酒伴是出饮，但他该也是独自赏花去了。这“无处告诉只颠狂”写的是两个人的事——他们都到江畔独步寻花去了。也可能寻花的还有更多的人，谁都爱美。这七首绝句写寻花，贯穿了“颠狂”二字，这第一首诗是解题。\n\n　　第二首：“稠花乱蕊畏江滨”，是承第一首“江上被花恼不彻”而来的。江上的花是纷繁的花和杂乱的蕊左右包围着江的两边，浣花溪一片花海。第一首头一句说“江上被花恼不彻”，而这首第二句则说“行步欹危实怕春”。王嗣奭在《杜臆》把颠狂的形态和心理都讲得比较透辟。花之醉人如此，接着写驱使诗酒，“未须料理自头人”。这是写花之魅力，花添诗情酒意，花使青春长在。这是寓有哲理，也合乎情理的。\n\n　　第三首：“江深竹静两三家，多事红花映白花。”这两句又是承二首句“稠花乱蕊畏江滨”而来，把大的范围缩到小的范围——两三家。范围缩小了，花却繁忙起来了。诗的起句是写静态，红花白花也平常。而加“多事”两字，顿觉热闹非常。“多事”又是从前面花恼人而生发来的，其奇妙处也是前后辉映。末二句抒情，把春光拟人化。“报答春光知有处，应须美酒送生涯。”似乎有所妙悟，也似有所解脱，但其深情，仍该是爱花。\n\n　　第四首：“东望少城花满烟，百花高楼更可怜。”组诗又宕开一层，写洗花溪边的繁花缤纷，这是村居所见之花；作者这时又想象成都少城之花，“百花高楼更可怜”。这句和他后来写的“花近高楼伤客心”，两句前半截极相似，而后三字哀乐迥异。“更可怜”即多可爱的意思。遥看少城之花，本是烟雾迷惘的烟花，但不曰烟花，而曰花满烟，真如《杜臆》所云“化腐为新”了。这样把城中之花再来陪衬江上、江滨村中人家之花，有远望近观之异，而乐事则相同。末二句以发问作结，“谁能载酒开金盏，唤取佳人舞绣筵？”实叹招饮无人，徒留想象，余韵无穷。\n\n　　诗题为独步寻花，组诗的第五首则写到黄师塔前看花。“黄师塔前江水东”，写具体的地点。“春光懒困倚微风”则写自己的倦态，春暖人易懒倦，所以倚风小息。但这为的是更好地看花，看那“桃花一簇开无主，可爱深红爱浅红”。这里叠用爱字，爱深红，爱浅红，爱这爱那，应接不暇，但又是紧跟着“开无主”三字来的。“开无主”就是自由自在地开，尽量地开，大开特开，所以下句承接起来更显出绚烂绮丽，诗也如锦似绣。\n\n　　第六首写寻花到了黄四娘家。这首诗记叙在黄四娘家赏花时的场面和感触，描写草堂周围烂漫的春光，表达了对美好事物的热爱之情和适意之怀。春花之美、人与自然的亲切和谐，都跃然纸上。首句点明寻花的地点，是在“黄四娘家”的小路上。此句以人名入诗，生活情趣较浓，颇有民歌味。次句“千朵万朵”，是上句“满”字的具体化。“压枝低”，描绘繁花沉甸甸地把枝条都压弯了，景色宛如历历在目。“压”、“低”二字用得十分准确、生动。第三句写花枝上彩蝶蹁跹，因恋花而“留连”不去，暗示出花的芬芳鲜妍。花可爱，蝶的舞姿亦可爱，不免使漫步的人也“留连”起来。但他也许并未停步，而是继续前行，因为风光无限，美景尚多。“时时”，则不是偶尔一见，有这二字，就把春意闹的情趣渲染出来。正在赏心悦目之际，恰巧传来一串黄莺动听的歌声，将沉醉花丛的诗人唤醒。这就是末句的意境。“娇”字写出莺声轻软的特点。“自在”不仅是娇莺姿态的客观写照，也传出它给作者心理上的愉快轻松的感觉。诗在莺歌“恰恰”声中结束，饶有余韵。此诗写的是赏景，这类题材，盛唐绝句中屡见不鲜。但像此诗这样刻画十分细微，色彩异常秾丽的，则不多见。如“故人家在桃花岸，直到门前溪水流”（常建《三日寻李九庄》），“昨夜风开露井桃，未央前殿月轮高”（王昌龄《春宫曲》），这些景都显得“清丽”；而杜甫在“花满蹊”后，再加“千朵万朵”，更添蝶舞莺歌，景色就秾丽了。这种写法，可谓前无古人。其次，盛唐人很讲究诗句声调的和谐。他们的绝句往往能被诸管弦，因而很讲协律。杜甫的绝句不为歌唱而作，纯属诵诗，因而常常出现拗句。如此诗“千朵万朵压枝低”句，按律第二字当平而用仄。但这种“拗”决不是对音律的任意破坏，“千朵万朵”的复叠，便具有一种口语美。而“千朵”的“朵”与上句相同位置的“四”字，虽同属仄声，但彼此有上、去声之别，声调上仍具有变化。诗人也并非不重视诗歌的音乐美。这表现在三、四两句双声词、象声词与叠字的运用。“留连”、“自在”均为双声词，如贯珠相联，音调宛转。“时时”、“恰恰”为叠字，即使上下两句形成对仗，使语意更强，更生动，更能表达诗人迷恋在花、蝶之中，忽又被莺声唤醒的刹那间的快意。这两句除却“舞”、“莺”二字，均为舌齿音，这一连串舌齿音的运用造成一种喁喁自语的语感，维妙维肖地状出看花人为美景陶醉、惊喜不已的感受。声音的效用极有助于心情的表达。在句法上，盛唐诗句多天然浑成，杜甫则与之异趣。比如“对结”（后联骈偶）乃初唐绝句格调，盛唐绝句已少见，因为这种结尾很难做到神完气足。杜甫却因难见巧，如此诗后联既对仗工稳，又饶有余韵，用得恰到好处：在赏心悦目之际，听到莺歌“恰恰”，增添不少感染力。此外，这两句按习惯文法应作：戏蝶留连时时舞，娇莺自在恰恰啼。把“留连”、“自在”提到句首，既是出于音韵上的需要，同时又在语意上强调了它们，使含义更易体味出来，句法也显得新颖多变。\n\n　　最后一首：“不是爱花即欲死”。痛快干脆，毫不藏伏。杜甫惯于一拚到底，常用狠语，如“语不惊人死不休”，即是如此。他又写道：“只恐花尽老相催。”怕的是花谢人老。下两句则是写景，写花枝之易落，花蕊的慢开，景中寓借花之深情，以对句出之，更是加倍写法，而又密不透风，情深语细。', poem_tags = '春天,写花,写景,喜悦' WHERE poem_title = '江畔独步寻花七绝句' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '陈元方十一岁时，去拜会袁公。袁公问：“你贤良的父亲在太丘做官，远近的人都称赞他，他到底做了些什么事情？”元方说：“我父亲在太丘，对强者用德行去安抚；对弱者用仁慈去安抚，让人们心安理得地做事，久而久之，大家就对他老人家更加敬重。”袁公说：“我曾经也当过邺县县令，正是做这样的事情。不知是你的父亲学我，还是我学你的父亲？”元方说：“周公、孔子生在不同时代，虽然时间相隔遥远，但他们的行为却是那么一致。周公没有学孔子，孔子也没有学周公。”', poem_notes = '候：拜访，问候。\n履行：实施，实行。\n绥：安，体恤。\n孤：封建时代王侯对自己的谦称。王后、皇后对自己的尊称，还有寡人，孤家等称呼.\n师：学习。\n尝：曾经。\n卿：客气，亲热的称呼\n法：在古汉语字典里有四种解释（1）法令，制度。（2)方法，做法。（3）效法，仿效。（4）标准，法则。这里用（3）效法，仿效。\n称：称赞，赞不绝口\n周公：周武王的弟弟。历史上的第一代周公姓姬名旦（约公元前1100年），亦称叔旦，周文王姬昌第四子。汉族，因封地在周（今陕西省宝鸡市岐山北），故称周公或周公旦。为西周初期杰出的政治家、军事家和思想家，被尊为儒学奠基人。\n周旋动静：这里指思想和行动\n益：更加\n以：用\n恣：放纵、无拘束，这里指顺从', poem_tags = '小学文言文,生活,写人,寓理' WHERE poem_title = '陈元方候袁公' AND poem_author = '刘义庆';
UPDATE edu_poem SET poem_translation = '碧绿的江水把鸟儿的羽毛映衬得更加洁白，山色青翠欲滴，红艳的野花似乎将要燃烧起来。\n今年春天眼看着又要过去了，什么时候才是我返回故乡的日期呢？', poem_notes = '逾（yú）：就是愈，更加的意思。\n欲燃：将要烧起来，这里是形容鲜红的颜色。欲：好像。\n何日：什么时候。\n归年：回去的时候。', poem_tags = '写景,思乡' WHERE poem_title = '绝句二首·其二' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '昨天刚登上龙山宴饮，今天又在这里举起了酒杯。\n菊花为何这样受苦，遭到两个重阳的采折之罪？', poem_notes = '即事：以眼前事物为题材之诗，称即事。\n登高：古时重阳节有登高的习俗。\n更：再。举觞（shāng）：举杯。觞，古代喝酒用的器具。\n遭此两重阳：古时重阳节有采菊宴赏的习俗。重阳后一日宴赏为小重阳。菊花两遇饮宴，两遭采摘，故有遭此两重阳之言。', poem_appreciation = '在唐宋时代，九月十日被称为“小重阳”，诗人从这一角度入手，说菊花在大小重阳两天内连续遇到人们的登高、宴饮，两次遭到采撷，所以有“太苦”的抱怨之言。作者以醉浇愁，朦胧中，仿佛看到菊花也在嘲笑他这个朝廷“逐臣”，他痛苦地发问：菊花为什么要遭到“两重阳”的重创？对于赏菊的人们来说，重阳节的欢乐情绪言犹未尽，所以九月十日还要继续宴饮；但菊花作为一种生命的个体，却要忍受两遭采撷之苦。诗人以其极为敏感、幽微的灵秀之心，站在菊花的立场上，发现了这一诗意的空间。实际上，诗人是借菊花之苦来寄托自己内心的极度苦闷。借叹菊花，而感慨自己被馋离京、流放夜郎的坎坷与不幸，正见其愁怀难以排解。此诗语虽平淡，内涵却十分深沉。主要表现了作者一生屡遭挫败和打击，而在节日里所引发的忧伤情绪。', poem_tags = '重阳节,菊花,抒情' WHERE poem_title = '九月十日即事' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '手拿干戈啊身穿犀皮甲，战车交错啊刀剑相砍杀。\n旗帜蔽日啊敌人如乌云，飞箭交坠啊士卒勇争先。\n犯我阵地啊践踏我队伍，左骖死去啊右骖被刀伤。\n埋住两轮啊绊住四匹马，手拿玉槌啊敲打响战鼓。\n天昏地暗啊威严神灵怒，残酷杀尽啊尸首弃原野。\n出征不回啊往前不复返，平原迷漫啊路途很遥远。\n佩带长剑啊挟着强弓弩，首身分离啊壮心不改变。\n实在勇敢啊富有战斗力，始终刚强啊没人能侵犯。\n身已死亡啊精神永不死，您的魂魄啊为鬼中英雄！', poem_notes = '国殇：指为国捐躯的人。殇：指未成年而死，也指死难的人。戴震《屈原赋注》：“殇之义二：男女未冠（男二十岁）笄（女十五岁）而死者，谓之殇；在外而死者，谓之殇。殇之言伤也。国殇，死国事，则所以别于二者之殇也。”\n操吴戈兮被（pī）犀甲：手里拿着吴国的戈，身上披着犀牛皮制作的甲。吴戈：吴国制造的戈，当时吴国的冶铁技术较先进，吴戈因锋利而闻名。被，通“披”，穿着。犀甲：犀牛皮制作的铠甲，特别坚硬。\n车错毂（gǔ）兮短兵接：敌我双方战车交错，彼此短兵相接。毂：车轮的中心部分，有圆孔，可以插轴，这里泛指战车的轮轴。错：交错。短兵：指刀剑一类的短兵器。\n旌蔽日兮敌若云：旌旗遮蔽的日光，敌兵像云一样涌上来。极言敌军之多。\n矢交坠：两军相射的箭纷纷坠落在阵地上。\n凌：侵犯。躐（liè）：践踏。行：行列。\n左骖（cān）殪（yì）兮右刃伤：左边的骖马倒地而死，右边的骖马被兵刃所伤。殪：死。\n霾（mái）两轮兮絷（zhí）四马：战车的两个车轮陷进泥土被埋住，四匹马也被绊住了。霾：通“埋”。古代作战，在激战将败时，埋轮缚马，表示坚守不退。\n援玉枹（fú）兮击鸣鼓：手持镶嵌着玉的鼓槌，击打着声音响亮的战鼓。先秦作战，主将击鼓督战，以旗鼓指挥进退。枹：鼓槌。鸣鼓：很响亮的鼓。\n天时怼（duì）兮威灵怒：天地一片昏暗，连威严的神灵都发起怒来。天怨神怒。天时：上天际会，这里指上天。天时怼：指上天都怨恨。怼：怨恨。威灵：威严的神灵。\n严杀尽兮弃原野：在严酷的厮杀中战士们全都死去，他们的尸骨都丢弃在旷野上。严杀：严酷的厮杀。一说严壮，指士兵。尽：皆，全都。\n出不入兮往不反：出征以后就不打算生还。反：通“返”。\n忽：渺茫，不分明。超远：遥远无尽头。\n秦弓：指良弓。战国时，秦地木材质地坚实，制造的弓射程远。\n首身离：身首异处。心不惩：壮心不改，勇气不减。惩：悔恨。\n诚：诚然，确实。以：且，连词。武：威武。\n终：始终。凌：侵犯。\n神以灵：指死而有知，英灵不泯。神：指精神。\n鬼雄：战死了，魂魄不死，即使做了死鬼，也要成为鬼中的豪杰。', poem_appreciation = '《九歌》是一组祭歌，共11篇，是屈原据民间祭神乐歌的再创作。《九歌·国殇》取民间“九歌”之祭奠之意，以哀悼死难的爱国将士，追悼和礼赞为国捐躯的楚国将士的亡灵。乐歌分为两节，先是描写在一场短兵相接的战斗中，楚国将士奋死抗敌的壮烈场面，继而颂悼他们为国捐躯的高尚志节。由第一节“旌蔽日兮敌若云”一句可知，这是一场敌众我寡的殊死战斗。当敌人来势汹汹，冲乱楚军的战阵，欲长驱直入时，楚军将士仍个个奋勇争先。但见战阵中有一辆主战车冲出，这辆原有四匹马拉的大车，虽左外侧的骖马已中箭倒毙，右外侧的骖马也被砍伤，但他的主人，楚军统帅仍毫无惧色，他将战车的两个轮子埋进土里，笼住马缰，反而举槌擂响了进军的战鼓。一时战气萧杀，引得苍天也跟着威怒起来。待杀气散尽，战场上只留下一具具尸体，静卧荒野。\n\n　　作者描写场面、渲染气氛的本领是十分高强的。不过十句，已将一场殊死恶战，状写得栩栩如生，极富感染力。底下，则以饱含情感的笔触，讴歌死难将士。有感于他们自披上战甲一日起，便不再想全身而返，此一刻他们紧握兵器，安详地，心无怨悔地躺在那里，他简直不能抑止自己的情绪奔进。他对这些将士满怀敬爱，正如他常用美人香草指代美好的人事一样，在诗篇中，他也同样用一切美好的事物，来修饰笔下的人物。这批神勇的将士，操的是吴地出产的以锋利闻名的戈、秦地出产的以强劲闻名的弓，披的是犀牛皮制的盔甲，拿的是有玉嵌饰的鼓槌，他们生是人杰，死为鬼雄，气贯长虹，英名永存。\n\n　　依现存史料尚不能指实这次战争发生的具体时地，敌对一方为谁。但当日楚国始终面临七国中实力最强的秦国的威胁，自怀王当政以来，楚国与强秦有过数次较大规模的战争，并且大多数是楚国抵御秦军入侵的卫国战争。从这一基本史实出发，说此篇是写楚军抗击强秦入侵，大概没有问题。而在这种抒写中，作者那热爱家国的炽烈情感，表现得淋漓尽致。\n\n　　楚国灭亡后，楚地流传过这样一句话：“楚虽三户，亡秦必楚。”屈原此作在颂悼阵亡将士的同时，也隐隐表达了对洗雪国耻的渴望，对正义事业必胜的信念，从此意义上说，他的思想是与楚国广大人民息息相通的。作为中华民族贡献给人类的第一位伟大诗人，他所写的决不仅仅是个人的些许悲欢，那受诬陷被排挤，乃至流亡沅湘的坎壈遭际；他奉献给人的是那颗热烈得近乎偏执的爱国之心。他是楚国人民的喉管，他所写一系列作品，道出了楚国人民热爱家国的心声。\n\n　　此篇在艺术表现上与作者其他作品有些区别，乃至与《九歌》中其他乐歌也不尽一致。它不是一篇想像奇特、辞采瑰丽的华章，然其“通篇直赋其事”（戴震《屈原赋注》），挟深挚炽烈的情感，以促迫的节奏、开张扬厉的抒写，传达出了与所反映的人事相一致的凛然亢直之美，一种阳刚之美，在楚辞体作品中独树一帜，读罢实在让人有气壮神旺之感。', poem_tags = '悼亡,赞颂,爱国,忧国忧民' WHERE poem_title = '九歌·国殇' AND poem_author = '屈原';
UPDATE edu_poem SET poem_translation = '北海里有一条鱼，它的名字叫鲲。鲲非常巨大，不知道有几千里。鲲变化成为鸟，它的名字就叫做鹏。鹏的脊背，也不知道有几千里长；当它振动翅膀奋起直飞的时候，翅膀就好像挂在天边的云彩。这只鸟，大风吹动海水的时候就要迁徙到南方的大海去了。南方的大海是一个天然的大池子。\n\n　　《齐谐》这本书，是记载一些怪异事情的书。书上记载：“鹏往南方的大海迁徙的时候，翅膀拍打水面，能激起三千里的浪涛，环绕着旋风飞上了九万里的高空，乘着六月的风离开了北海。”像野马奔腾一样的游气，飘飘扬扬的尘埃，活动着的生物都因为风吹而运动。天空苍苍茫茫的，难道就是它本来的颜色吗？它的辽阔高远也是没有尽头的吗？鹏往下看的时候，看见的应该也是这个样子。\n\n　　如果聚集的水不深，那么它就没有负载一艘大船的力量了。在堂前低洼的地方倒上一杯水，一棵小草就能被当作是一艘船，放一个杯子在上面就会被粘住，这是水浅而船却大的原因。如果聚集的风不够强大的话，那么负载一个巨大的翅膀也就没有力量了。因此，鹏在九万里的高空飞行，风就在它的身下了，凭借着风力，背负着青天毫无阻挡，然后才开始朝南飞。\n\n　　蝉和小斑鸠讥笑鹏说：“我们奋力而飞，碰到榆树和檀树就停止，有时飞不上去，落在地上就是了。何必要飞九万里到南海去呢？”到近郊去的人，只带当天吃的三餐粮食，回来肚子还是饱饱的；到百里外的人，要用一整夜时间舂米准备干粮；到千里外的人，要聚积三个月的粮食。蝉和小斑鸠这两只小虫、鸟又知道什么呢。\n\n　　小智比不上大智，短命比不上长寿。怎么知道是这样的呢？朝生暮死的菌草不知道黑夜与黎明。春生夏死、夏生秋死的寒蝉，不知道一年的时光，这就是短命。楚国的南方有一种大树叫做灵龟，它把五百年当作一个春季，五百年当作一个秋季。上古时代有一种树叫做大椿，它把八千年当作一个春季，八千年当作一个秋季，这就是长寿。可是活了七百来岁的彭祖如今还因长寿而特别闻名，众人都想与他相比，岂不可悲！\n\n　　商汤问棘，谈的也是这件事。汤问棘说：“上下四方有极限吗？”棘说：“无极之外，又是无极！在草木不生的极远的北方，有个大海，就是天池。里面有条鱼，它的身子有几千里宽，没有人知道它有多长，它的名字叫做鲲。有一只鸟，它的名字叫做鹏。鹏的背像泰山，翅膀像天边的云；借着旋风盘旋而上九万里，超越云层，背负青天，然后向南飞翔，将要飞到南海去。小泽里的麻雀讥笑鹏说：‘它要飞到哪里去呢？我一跳就飞起来，不过数丈高就落下来，在蓬蒿丛中盘旋，这也是极好的飞行了。而它还要飞到哪里去呢？’”这是大和小的分别。\n\n　　所以，那些才智能胜任一官的职守，行为能够庇护一乡百姓的，德行能投合一个君王的心意的，能力能够取得全国信任的，他们看待自己，也像上面说的那只小鸟一样。而宋荣子对这种人加以嘲笑。宋荣子这个人，世上所有的人都称赞他，他并不因此就特别奋勉，世上所有的人都诽谤他，他也并不因此就感到沮丧。他认定了对自己和对外物的分寸，分辨清楚荣辱的界限，就觉得不过如此罢了。他对待人世间的一切，都没有拼命去追求。即使如此，他还是有未达到的境界。\n\n　　列子乘风而行，飘然自得，驾轻就熟。十五天以后返回；他对于求福的事，没有拼命去追求。这样虽然免了步行，还是有所凭借的。倘若顺应天地万物的本性，驾驭着六气的变化，遨游于无穷的境地，他还要凭借什么呢？所以说：修养最高的人能任顺自然、忘掉自己，修养达到神化不测境界的人无意于求功，有道德学问的圣人无意于求名。', poem_notes = '冥：通假“溟”，指海色深黑。“北冥”，北海。下文“南冥”，指南海。传说北海无边无际，水深而黑。\n鲲（kūn）：传说中的大鱼。 之：主谓之间取消句子独立性。其：表推测。\n鹏：本为古“凤”字，这里指传说中的大鸟。\n怒：奋起的样子，这里指鼓起翅膀。\n垂：同“陲”，边际。\n海运：海动。古有“六月海动”之说。海运之时必有大风，因此大鹏可以乘风南行。徙：迁移。\n天池：天然形成的大海。\n《齐谐》：书名。出于齐国，多载诙谐怪异之事，故名“齐谐”。一说人名。\n志怪：记载怪异的事物。志，记载。\n水击：指鹏鸟的翅膀拍击水面。击：拍打。\n抟（tuán）：回旋而上。一作“搏”（bó），拍。扶摇：一种旋风，又名飙，由地面急剧盘旋而上的暴风。九，表虚数，不是实指。\n去：离，这里指离开北海。“去以六月息者也”指大鹏飞行六个月才止息于南冥。一说息为大风，大鹏乘着六月间的大风飞往南冥。以：凭借。息：风。\n野马：指游动的雾气。古人认为：春天万物生机萌发，大地之上游气奔涌如野马一般。\n尘埃：扬在空中的土叫“尘”，细碎的尘粒叫“埃”。\n生物：概指各种有生命的东西。息：这里指有生命的东西呼吸所产生的气息。 相：互相。吹：吹拂。\n苍苍：深蓝。其正色邪：或许是上天真正的颜色？其，抑，或许。正色，真正的颜色。邪，同“耶”，疑问语气词。极：尽。 下：向下。亦：也。是：这样。已：罢了。\n覆：倾倒。坳（ào）：凹陷不平，“坳堂”指堂中低凹处。\n芥：小草。置杯焉则胶：将杯子放于其中则胶着搁浅。置，放。焉，于此。胶，指着地。\n斯：则，就。\n而后乃今：“今而后乃”的倒文，意为“这样，然后才……”。培：凭。\n莫之夭阏（yāo è）：无所滞碍。夭，挫折。阏，遏制，阻止。“莫之夭阏”即“莫夭阏之”的倒装。 图南：计划向南飞。\n蜩（tiáo）：蝉。学鸠：斑鸠之类的小鸟名。\n决（xuè）：疾速的样子。\n抢（qiāng）：触，碰，着落。“抢”也作“枪”。榆枋：两种树名。榆，榆树。枋，檀木。\n 控：投，落下。\n 奚以：何以。之：去到。为：句末语气词，表反问，相当于“呢”。南：名词作动词，向南（飞行）。“奚以……为”，即“哪里用得着.......呢”。\n 适：去，往。莽苍：色彩朦胧，遥远不可辨析，本指郊野的颜色，这里引申为近郊。\n三餐：指一日。意思是只需一日之粮。反：同“返”，返回。\n犹：还。果然：吃饱的样子。\n宿：这里指一夜。 宿舂粮：即舂宿粮，舂捣一宿的粮食。\n之：此，这。二虫：指蜩与学鸠。虫:有动物之意，可译为小动物\n知（zhì）：通“智”，智慧。\n朝菌：一种大芝，朝生暮死的菌类植物。晦朔：晦，农历每月的最后一天，朔，农历每月的第一天。一说“晦”指月末，“朔”指月初。\n蟪蛄（huì gū）：寒蝉，春生夏死或夏生秋死。\n冥灵：大树名。一说为大龟名。\n根据前后用语结构的特点，此句之下当有“此中年也”一句，但传统本子均无此句。\n 大椿：传说中的大树名。一说为巨大的香椿。\n彭祖：传说中尧的臣子，名铿，封于彭，活了约八百岁。乃今：而今。以，凭。特，独。闻，闻名于世。\n众人：一般人。匹：配，比。\n汤：商汤。棘：汤时的贤大夫，《列子汤问》篇作“夏革（jí）”。已：矣。\n穷发：传说中极荒远的不生草木之地。发，指草木植被。\n修：长。\n泰山：在今山东泰安北。\n羊角：一种旋风，回旋向上如羊角状。\n绝：穿过。\n斥鴳（yàn）：池沼中的小雀。斥，池，小泽。\n仞：古代长度单位，周制为八尺，汉制为七尺；这里应从周制。\n至：极点。\n小大之辩：小和大的区别。辩，同“辨”，分辨，分别。\n效：效力，尽力。官：官职。\n行（xíng）：品行。比：合。\n合：使...满意。而：通“能”，能够。征：征服。\n宋荣子：一名宋钘（jiān），宋国人，战国时期的思想家。犹然：喜笑的样子；犹，通“繇”，喜。\n举：全。劝：勉励。\n非：责难，批评。沮（jǔ）：沮丧。\n定：认清。内外：这里分别指自身和身外之物。在庄子看来，自主的精神是内在的，荣誉和非难都是外在的，而只有自主的精神才是重要的、可贵的。\n境：界。\n数数（shuò）然：汲汲然，指急迫用世、谋求名利、拼命追求的样子。\n列子：郑国人，名叫列御寇，战国时代思想家。御：驾驭。\n泠（líng）然：轻妙飘然的样子。善：美好的。\n旬：十天。有：通“又”，用于连接整数与零数。\n致福：求福。\n虽：虽然。待：凭借，依靠。\n乘：遵循，凭借。天地：这里指万物，指整个自然界。正：本；这里指自然的本性。\n御六气之辩：驾驭六气的变化。御，驾驭、把握。六气：指阴、阳、风、雨、晦、明。辩：通“变”，变化的意思。\n彼：他。且：将要。恶（wū）：何，什么。\n至人：庄子认为修养最高的人。下文“神人”“圣人”义相近。 无己：清除外物与自我的界限，达到忘掉自己的境界。即物我不分。\n神人：这里指精神世界完全能超脱于物外的人。无功：无作为，故无功利。\n圣人：这里指思想修养臻于完美的人。无名：不追求名誉地位，不立名。', poem_appreciation = '“逍遥”也写作“消摇”，意思是优游自得的样子；“逍遥游”就是没有任何束缚地、自由自在地活动。\n\n　　全文可分为三个部分，第一部分至“圣人无名”，是本篇的主体，从对比许多不能“逍遥”的例子说明，要得真正达到自由自在的境界，必须“无己”、“无功”、“无名”。第二部分至“窅然丧其天下焉”，紧承上一部分进一步阐述，说明“无己”是摆脱各种束缚和依凭的唯一途径，只要真正做到忘掉自己、忘掉一切，就能达到逍遥的境界，也只有“无己”的人才是精神境界最高的人。余下为第三部分，论述什么是真正的有用和无用，说明不能为物所滞，要把无用有用，进一步表达了反对积极投身社会活动，志在不受任何拘束，追求优游自得的生活旨趣。\n\n　　本篇是《庄子》的代表篇目之一，也是诸子百家中的名篇，充满奇特的想象和浪漫的色彩，寓说理于寓言和生动的比喻中，形成独特的风格。“逍遥游”也是庄子哲学思想的一个重要方面。全篇一再阐述无所依凭的主张，追求精神世界的绝对自由。在庄子的眼里，客观现实中的一事一物，包括人类本身都是对立而又相互依存的，这就没有绝对的自由，要想无所依凭就得无己。因而他希望一切顺乎自然，超脱于现实，否定人在社会生活中的一切作用，把人类的生活与万物的生存混为一体；提倡不滞于物，追求无条件的精神自由。', poem_tags = '高中文言文,寓言,故事,自由' WHERE poem_title = '逍遥游(节选)' AND poem_author = '庄周';
UPDATE edu_poem SET poem_translation = '非常像花又好像不是花，无人怜惜任凭衰零坠地。把它抛离在家乡路旁，细细思量仿佛又是无情，实际上则饱含深情。受伤柔肠婉曲娇眼迷离，想要开放却又紧紧闭上。蒙混随风把心上人寻觅，却又被黄莺儿无情叫起。\n不恨这种花儿飘飞落尽，只是抱怨愤恨那个西园、满地落红枯萎难再重缀。清晨雨后何处落花遗踪？飘入池中化成一池浮萍。如果把春色姿容分三份，其中的二份化作了尘土，一份坠入流水了无踪影。细看来那全不是杨花啊，是那离人晶莹的眼泪啊。', poem_notes = '水龙吟：词牌名。又名“龙吟曲”“庄椿岁”“小楼连苑”。《清真集》入“越调”。一百二字，前后片各四仄韵。又第九句第一字并是领格，宜用去声。结句宜用上一、下三句法，较二、二句式收得有力。\n次韵：用原作之韵，并按照原作用韵次序进行创作，称为次韵。章质夫：即章楶（jié），建州浦城（今属福建）人。时任荆湖北路提点刑狱，常与苏轼诗词酬唱。\n从教：任凭。\n无情有思：言杨花看似无情，却自有它的愁思。用唐韩愈《晚春》诗：“杨花榆荚无才思，唯解漫天作雪飞。”这里反用其意。思：心绪，情思。\n萦：萦绕、牵念。柔肠：柳枝细长柔软，故以柔肠为喻。用唐白居易《杨柳枝》诗：“人言柳叶似愁眉，更有愁肠如柳枝。”\n困酣：困倦之极。娇眼：美人娇媚的眼睛，比喻柳叶。古人诗赋中常称初生的柳叶为柳眼。\n“梦随”三句：用唐金昌绪《春怨》诗：“打起黄莺儿，莫教枝上啼。啼时惊妾梦，不得到辽西。”\n落红：落花。缀：连结。\n一池萍碎：苏轼自注：“杨花落水为浮萍，验之信然。”\n春色：代指杨花。', poem_tags = '宋词三百首,宋词精选,柳树,婉约' WHERE poem_title = '水龙吟·次韵章质夫杨花词' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '淳熙年丙申月冬至这天，我经过扬州。夜雪初晴，放眼望去，全是荠草和麦子。进入扬州，一片萧条，河水碧绿凄冷，天色渐晚，城中响起凄凉的号角。我内心悲凉，感慨于扬州城今昔的变化，于是自创了这支曲子。千岩老人认为这首词有《黍离》的悲凉意蕴。\n\n扬州自古是淮南东路的名城，这里有著名游览胜地竹西亭，初到扬州我解鞍下马作停留。当年那春风十里繁华街道，如今却是荞麦青青孤单可怜。自从金兵侵犯长江流域以后，连荒废的池苑和古老的大树，都厌恶再提起那场可恶的战争。临近黄昏凄清的号角已吹响，回荡在这座凄凉残破的空城。\n杜牧曾以优美的诗句把你赞赏，今若重来定会为你残破而惊。纵使有豆蔻芳华的精工词采，纵有歌咏青楼一梦绝妙才能，也难抒写此刻深沉悲怆感情。二十四桥依然完好毫无损伤，桥下波心荡漾一弯冷月寂寞。想那桥边红芍年年花叶繁荣，不知年年有谁欣赏为谁而生？', poem_notes = '扬州慢：词牌名，又名《郎州慢》，上下阕，九十八字，平韵。此调为姜夔自度曲，后人多用以抒发怀古之思。\n淳熙丙申：淳熙三年（1176）。至日：冬至。\n维扬：即扬州（今属江苏）。\n荠麦：荠菜和野生的麦。弥望：满眼。\n戍角：军营中发出的号角声。\n千岩老人：南宋诗人萧德藻，字东夫，自号千岩老人。姜夔曾跟他学诗，又是他的侄女婿。黍离：《诗经·王风》篇名。据说周平王东迁后，周大夫经过西周故都，看见宗庙毁坏，尽为禾黍，彷徨不忍离去，就做了此诗。后以“黍离”表示故国之思。\n淮左名都：指扬州。宋朝的行政区设有淮南东路和淮南西路，扬州是淮南东路的首府，故称淮左名都。左，古人方位名，面朝南时，东为左，西为右。名都，著名的都会。\n解（xiè）鞍少驻初程：少驻，稍作停留；初程，初段行程。\n春风十里：杜牧《赠别》诗：“春风十里扬州路，卷上珠帘总不如。”这里用以借指扬州。\n胡马窥江：指金兵侵略长江流域地区，洗劫扬州。这里应指第二次洗劫扬州。\n废池乔木：废毁的池台。乔木：残存的古树。二者都是乱后余物，表明城中荒芜，人烟萧条。\n渐：向，到。清角：凄清的号角声。\n杜郎：即杜牧。唐文宗大和七年到九年，杜牧在扬州任淮南节度使掌书记。俊赏：俊逸清赏。钟嵘《诗品序》：“近彭城刘士章，俊赏才士。”\n豆蔻：形容少女美艳。豆蔻词工：杜牧《赠别》：“娉娉袅袅十三余，豆蔻梢头二月初。”\n青楼：妓院。青楼梦好：杜牧《遣怀》诗：“十年一觉扬州梦，赢得青楼薄幸名。”\n二十四桥：扬州城内古桥，即吴家砖桥，也叫红药桥。\n红药：红芍药花，是扬州繁华时期的名花。', poem_appreciation = '赏析三 　　尽管姜夔一生以游士终老，但白石词并不仅仅是游士生涯的反映，展现在他笔下的是折射出多种光色的情感世界。诚然，由于生活道路和审美情趣的制约，较之辛词，姜词的题材较为狭窄，对现实的反映也略显淡漠。但他并不是一位不问时事的世外野老。姜夔身历高、孝、光、宁四朝，其青壮年正当宋金媾和之际，朝廷内外，文恬武嬉，将恢复大计置于度外。姜夔也曾因此而痛心疾首，深致慨叹。淳熙二年，他客游扬州时便有感于这座历史名城的凋敝和荒凉，而自度此曲，抒写黍离之悲。在作年可考的姜夔词中，这是最早的一首。上片由“名都”、“佳处”起笔，却以“空城”作结，其今昔盛衰之感昭然若揭。“过春风十里，尽荠麦青青”，自虚处传神，城池荒芜、人烟稀少、屋宇倾颓的凄凉情景不言自明，这与杜甫的“城春草木深”（《春望》）用笔相若。“春风十里”，并非实指一路春风拂面，而是化用杜牧诗意，使作者联想当年楼阁参差、珠帘掩映的盛况，反照今日的衰败景象。“胡马窥江”二句写金兵的劫掠虽然早已成为过去，而“废池乔木”犹以谈论战事为厌，可知当年带来的战祸兵燹有多么酷烈！陈廷焯《白雨齐词话》认为：“‘犹厌言兵’四字，包括无限伤乱语，他人累千百言，亦无此韵味。”姜词以韵味胜，其佳处即在于淡语不淡，其中的韵味反倒是某些浓至之语所不及的。“清角”二句，不仅益增寂凄，而且包含几多曲折：下有同仇敌忾之心，而上无抗金北伐之意，这样，清泠的号角声便只能徒然震响在兵燹之余的空城。词的下片，作者进一步 从怀古中展开联想：晚唐诗人杜牧的扬州诗历来脍炙人中，但如果他重临此地，必定再也吟不出深情缱绻的诗句，因为眼下只有一弯冷月、一泓寒水与他倘佯过的二十四桥相伴；桥边的芍药花虽然风姿依旧，却是无主自开，不免落寞。尤其“二十四桥”二句，愈工致，愈惨淡，可谓动魄惊心。萧德藻认为此词“有黍离之悲”，的确深中肯綮。 ▲', poem_tags = '宋词三百首,写景,抒情' WHERE poem_title = '扬州慢·淮左名都' AND poem_author = '姜夔';
UPDATE edu_poem SET poem_translation = '世上万事恍如一场大梦，人生经历了几度新凉的秋天？到了晚上，风吹动树叶发出的声音，响彻回廊里，看看自己，眉头鬓上又多了几根银丝。\n酒并非好酒，却为客少发愁，月亮虽明，却总被云遮住。在这中秋之夜，谁能够和我共同欣赏这美妙的月光？我只能拿起酒杯，凄然望着北方。', poem_notes = '⑴西江月：原为唐教坊曲，后用作词调。《乐章集》《张子野词》并入“中吕宫”。五十字，上下片各两平韵，结句各叶一仄韵。\n⑵世事一场大梦：《庄子·齐物论》：“且有大觉，而后知其大梦也。”李白《春日醉起言志》：“处世若大梦，胡为劳其生。”\n⑶新凉：一作“秋凉”。\n⑷风叶：风吹树叶所发出的声音。鸣廊：在回廊上发出声响。《淮南子·说山训》：“见一叶落而知岁之将暮。”徐寅《人生几何赋》：“落叶辞柯，人生几何”。此由风叶鸣廊联想到人生之短暂。\n⑸眉头鬓上: 指眉头上的愁思鬓上的白发。\n⑹贱：质量低劣。\n⑺妨：遮蔽。\n⑻孤光：指独在中天的月亮。\n⑼琖：同“盏”，酒杯。', poem_appreciation = '上片 　　以词为书信，是宋词传播的一道风景线。此词即是苏轼兄弟的唱和之作，观其词察其人,无论文势文辞,我们都可发现一个视成规为草芥的缚不住的苏东坡。\n\n　　这首词反映了作者谪居后的苦闷心情，词调较为低沉、哀惋，充满了人生空幻的深沉喟叹。具体写作年代，大概是元丰三年（1080）。\n\n　　词的上片写感伤，寓情于景，咏人生之短促，叹壮志之难酬。下片写悲愤，借景抒情，感世道之险恶，悲人生之寥落。苏轼的几首中秋词中，本篇自有其特色 上片的起句“世事一场大梦，人生几度新凉”，感叹人生的虚幻与短促，发端便以悲剧气氛笼罩全词。以梦喻世事，不仅包含了不堪回首的辛酸往事，还概括了对整个人生的纷纷扰扰究竟有何目的和意义这一问题的怀疑、厌倦和企求解脱与舍弃。“人生几度新凉”，有对于逝水年华的无限惋惜和悲叹。“新凉”二字照应中秋，句中数量词兼疑问词“几度”的运用，低回唱叹，更显示出人生的倏忽之感。三、四句“夜来风叶已鸣廊，看取眉头鬓上”，紧承起句，进一步唱出了因时令风物而引起的人生惆怅。作者撷取秋风萧瑟、落叶纷飞这两个典型秋色秋景，借寒暑的易替，叹时光易逝、容颜将老、壮志难酬，以哀惋的笔调道出无法摆脱人生烦忧的怅惘之情。\n\n下片 　　下片写独自一人于异乡把盏赏月的孤寂处境和伤时感事的思绪。“酒贱常愁客少”，委婉地点出作者遭贬斥后势利小人避之如水火的情形；“月明多被云妨”，隐喻奸人当道，排斥善类，忠而被谤，因谗遭贬。以上两句，流露出词人对世态炎凉的感愤，包含的情感非常丰富：有念怀亲人的无限情思，有对国事的忧虑和对群小当道的愤懑，有渴望朝廷理解、重用的深意，也有难耐的孤寂落寞和不被世人理解的苦痛凄凉。这一结拍，是一个天涯沦落人带着血泪的人生呐喊与宣泄。它巨大的悲剧力量，确乎令人荡气回肠。\n\n　　以景寓情，情景交融，是这首中秋词的艺术特色。全词通过对新凉风叶、孤光明月等景物的描写，将吟咏节序与感慨身世、抒发悲情紧密结合起来，由秋思及人生，触景生情，感慨悲歌，情真意切，令人回味无穷。', poem_tags = '宋词三百首,宋词精选,婉约,中秋节,贬谪,感叹,人生' WHERE poem_title = '西江月·世事一场大梦' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '天地之间一片空旷，时光公然地离我而去。\n在人生的末路上因为风雨而受惊，在偏僻的边疆饱经了冰雪寒霜。\n如今生命跟这一年一样快要结束了，我和我一生的经历也会被遗忘。\n以后再也梦不到过新年喝屠苏酒，只能在漫漫长夜里拨动灯火。', poem_notes = '除夜：即除夕，为农历一年中的最后一天。\n乾坤：天地间。乾，卦名，天；坤:卦名，地。\n堂堂：公然。唐·薛能《春日使府寓怀》诗：“青春背我堂堂去，白发欺人故故生。” \n穷：偏僻的。\n屠苏：代指新年，古有农历初一饮屠苏酒的习俗。\n挑灯：拨动灯火（古人多用油灯，需要拨动灯芯），点灯。\n央：尽，完，结束。', poem_appreciation = '此诗作于元朝至元十八年，即公元1281年，是文天祥平生度过的最后一个除夕夜。这一首诗，诗句冲淡、平和，没有“天地有正气”的豪迈，没有“留取丹心照汗青”的慷慨，只表现出大英雄欲与家人共聚一堂欢饮屠苏酒过元旦的愿望，甚至字里行间中透露出一丝寂寞、悲怆的情绪。恰恰是在丹心如铁男儿这一柔情的刹那，反衬出勃勃钢铁意志之下人的肉身的真实性，这种因亲情牵扯萌发的“脆弱”，更让我们深刻体味了伟大的人性和铮铮男儿的不朽人格。\n\n　　《除夜》一诗，没有雕琢之语，没有琐碎之句，更无高昂的口号式咏叹。可是，我们仍旧感到心灵的一种强烈震撼。无论时光怎样改变，无论民族构成如何增容扩大，无论道德是非观念几经嬗变，文天祥，作为我们民族精神的象征，作为忠孝节义人格的伟大图腾，万年不朽，颠扑不灭，仍会是在日后无数个世代激励一辈又一辈人的道德典范。', poem_tags = '节日,春节' WHERE poem_title = '除夜' AND poem_author = '文天祥';
UPDATE edu_poem SET poem_translation = '有一个屠夫，傍晚走在路上，被狼紧紧地追赶着。路旁有个农民留下的田间休息处，他就跑进去躲藏在里面。狼从苫房的草帘中伸进两只爪子。于是屠夫急忙捉住狼爪，不让它离开，但是没有办法可以杀死它。只有一把不满一寸长的小刀，就用它割破爪子下面的狼皮，用吹猪的方法往里吹气。（屠夫）用力吹了一阵儿，觉得狼不怎么动了，才用绳子把狼腿捆起来。出去一看，只见狼浑身膨胀，就像一头牛。四条腿直挺挺地不能弯曲，张着嘴也无法闭上。屠夫就把它背回去了。\n\n　　（如果）不是屠夫，谁有这个办法呢？', poem_notes = '暮：傍晚。\n夜耕：夜晚替人耕田，打短工的\n为（wèi）：被。\n遗（yí）：留下。\n伏（fú）：躲藏（也有人说是埋伏，躲藏更符合当时情景。）\n去：离开。\n盈：超过。\n不盈：不满，不足。\n负：背。\n行室（xíng shì）：指农民在田中所搭的草棚。\n苫（shàn）：用草编的席子。\n去：离开。\n豕（shǐ）：猪。\n方：才。\n则：就。\n股：大腿。\n乌：哪里，怎么。\n顾：但是\n死之：杀死它', poem_appreciation = '本文可分三段：第一段(屠夫遇狼）写两狼追赶屠户，屠户时而迁就退让，继而被迫抵抗自卫。\n\n　　这一段又分为三层，从“一屠晚归”至“缀行甚远”，简洁地叙述了屠户遇狼的时间、地点和情况。一个卖肉晚归的屠户，在“担中肉尽，止有剩骨”，却又行人断绝，孤立无援的情况下，让两只恶狼给盯住了。草草几笔，就勾画出危急的处境，紧张的气氛，实在扣人心弦，为后面描述屠户的斗争策略作了铺垫。\n\n　　（屠夫惧狼）面对意想不到的恶狼，屠夫首先是“惧”。于是采取迁就的策略，“投以骨”。屠夫最初认为，只要满足狼的贪欲，就可脱险。至“一狼得骨止，一狼仍从”，也似乎如他所料，使两狼“缀行甚远”的情况暂时有了改变，文笔十分曲折。可是照样投骨的结果，只不过让后狼暂时停脚，而“前狼又至”；直到骨头投尽了，也没有填饱饿狼的饥肠，而“并驱如故”，因此屠户处境更加危险。这就充分暴露了狼的贪婪本性，证明了屠户退让迁就策略的失败。这是第二层。\n\n　　“屠大窘”，说明在危急的关头，他产生了激烈的思想斗争。他明白自己已面临生死抉择，或者被狼吃掉，或者把狼杀死。怕死是不行的，退让是无用的，唯一的方法是：杀狼。屠户已在事实面前吸取了教训，开始考虑如何改变“前后受敌”的不利条件。他机敏地环顾麦场且速“奔倚”在积薪之下，放下担子，拿起刀，利用麦场的有利地形，改变了途中两狼并驱的局面，避免了前后受敌的处境。“狼不敢前”是屠户敢于斗争的初步效果，并非它们开始退让。“眈眈相向”，说明两狼既凶狠又狡诈，也准备变换策略，寻机残害屠户。这样，双方进入相持阶段。这是第三层。\n\n　　（屠夫御狼）第二段分两层：\n\n　　第一层，从“少时”至“又数刀毙之”。作者在描写两狼对屠户“眈眈相向”之后，又变换笔法，写一只狼竟然自己走开，另一只狼装作驯良的家狗形态蹲着，然后闭着眼睛打盹，样子十分悠闲。这是狼在屠户持刀的情况下耍弄的新花招。文中故意不作说明，而是以细腻的笔触刻画狼的狡诈形象，让人们仔细品味，加深对狼的本性的认识。这时的屠户虽然不能猜透它们诱敌包抄然后夹击的花招，但对于狼的凶狠狡诈有了清醒的认识，所以不受这种假象欺骗，不是释刀自喜，而是趁机“暴起”，猝不及防地以刀劈狼首，结束了它的性命。文中狼的悠闲假象，屠户的暴起动作，相映成趣。\n\n　　（屠夫杀狼）第二层，屠户杀了眼前的狼而准备赶路，又警惕地转视积薪后，发现了另一只正在钻洞的狼。作者借屠户的锐利的眼睛，点出狼“隧入以攻其后”的企图，揭露其“身已半入，止露尻尾”那种弄巧成拙的丑态，次“亦毙之”作了痛快的结束。行文至此，才以画龙点睛之笔点出屠户“乃悟前狼之假寐，盖以诱敌”的道理，与上层紧相呼应。这使屠户也使读者领悟到：只知狼凶狠的特性，不了解狼的欺诈一面，那就要受骗上当；只看到眼前的狼，却不注意暗藏的狼，满足于一时的胜利，到头来还会遭到失败。\n\n　　第三段，是作者诙谐风趣的议论。作者指出狼的狡黠奸诈，而嘲笑其顷刻而毙的结局，也间接赞扬了屠户的勇敢机智，余味无穷。', poem_tags = '初中文言文,写狼,哲理,寓言,故事' WHERE poem_title = '狼三则' AND poem_author = '蒲松龄';
UPDATE edu_poem SET poem_translation = '秋风萧瑟,天气清冷，草木凋落，白露凝霜。\n燕群辞归，天鹅南飞。思念出外远游的良人啊，我肝肠寸断。\n思虑冲冲，怀念故乡。君为何故，淹留他方。\n贱妾孤零零的空守闺房，忧愁的时候思念君子啊，我不能忘怀。不知不觉中珠泪下落，打湿了我的衣裳。\n拿过古琴，拨弄琴弦却发出丝丝哀怨。短歌轻吟，似续还断。\n那皎洁的月光啊照着我的空床，星河沉沉向西流，忧心不寐夜漫长。\n牵牛织女啊远远的互相观望，你们究竟有什么罪过，被天河阻挡。', poem_notes = '本篇属《相和歌辞·平调曲》。燕是北方边地，征戍不绝，所以《燕歌行》多半写离别。\n摇落：凋残。\n鹄：天鹅。\n慊慊(qiàn qiàn ) ：空虚之感。淹留：久留。上句是设想对方必然思归，本句是因其不归而生疑问。\n茕茕(qióngqióng)：孤独无依的样子。出自《楚辞·九章·思美人》：“独茕茕而南行兮，思彭咸之故也。”\n援：执，持。清商：乐名。清商音节短促，所以下句说“短歌微吟不能长”。\n夜未央：夜已深而未尽的时候。古人用观察星象的方法测定时间，这诗所描写的景色是初秋的夜间，牛郎星、织女星在银河两旁， 初秋傍晚时正见于天顶， 这时银河应该西南指，现在说“星汉西流”，就是银河转向西，表示夜已很深了。\n尔：指牵牛、织女。河梁：河上的桥。传说牵牛和织女隔着天河，只能在每年七月七日相见，乌鹊为他们搭桥。', poem_appreciation = '这是曹丕《燕歌行》二首中的第一首。《燕歌行》是一个乐府题目，属于《相和歌》中的《平调曲》，它和《齐讴行》、《吴趋行》相类，都是反映各自地区的生活，具有各自地区音乐特点的曲调。燕（Yān）是西周以至春秋战国时期的诸侯国名，辖地约当今北京市以及河北北部、辽宁西南部等一带地区。这里是汉族和北部少数民族接界的地带，秦汉以来经常发生战争，因此历年统治者都要派重兵到这里戍守，当然那些与此相应的筑城、转输等各种摇役也就特别多了。拿最近的事实说，建安十二年（207）曹操北伐乌桓的战争，就发生在这古燕国的北部今辽宁省兴城一带。反映这个地区战争徭役之苦的作品，早在秦朝就有“生男慎勿举，生女哺用脯。不见长城下，尸骨相撑拄”的民歌，到汉代更有了著名的《饮马长城窟》。曹丕的《燕歌行》从思想内容上说就是对这种文学作品的继承与发展。郭茂倩《乐府诗集》引《乐府解题》说：“魏文帝‘秋风’‘别日’二曲言时序迁换，行役不归，妇人怨旷无所诉也。”又引《乐府广题》说：“燕，地名也。言良人从役于燕，而为此曲。”这样来理解作品的内容是正确的。《燕歌行》不见古辞，这个曲调可能就创始于曹丕。这篇作品反映的是秦汉以来四百年间的历史现象，同时也是他所亲处的建安时期的社会现实，表现了作者对下层人民疾苦的关心与同情。\n\n　　“秋风萧瑟天气凉，草木摇落露为霜，群燕辞归雁南翔。”开头三句写出了一片深秋的肃杀情景，为女主人公的出场作了准备。这里的形象有视觉的，有听觉的，有感觉的，它给人一种空旷、寂寞、衰落的感受。这种景和即将出场的女主人公的内心之情是一致的。这三句虽然还只是写景，还没有正面言情，可是我们已经感觉到情满于纸了。这种借写秋景以抒离别与怀远之情的方法，中国是有传统的。宋玉《九辨》中有：“悲哉，秋之为气也！萧瑟兮，草木摇落而变衰。憭栗兮，若在远行，登高临水兮送将归。”汉武帝的《秋风辞》说：“秋风起兮白云飞，草木黄落兮雁南归。兰有秀兮菊有芳，怀佳人兮不能忘。”从这里我们不仅可以看到《燕歌行》与它们思想感情上的连续性，而且还可以看到其中语言词汇上的直接袭用。但是这些到了曹丕笔下，却一切又都成为具有他个人独特思想面貌，独特艺术风格的东西了。这点我们后面再说。\n\n　　“念君客游思断肠，慊慊思归恋故乡，君何淹留寄他方？”在前面已经描写过的那个肃杀的秋风秋夜的场景上，我们的女主人公登台了：她愁云满面，孤寂而又深情地望着远方自言自语，她说：你离家已经这样久了，我思念你思念得柔肠寸断。我也可以想象得出你每天那种伤心失意的思念故乡的情景，可是究竟是什么原因使你这样长久地留在外面而不回来呢？慊慊（qiānqiān）：失意不平的样子。“慊慊思归恋故乡”是女主人公在想象她的丈夫在外面思念故乡的情景。这种写法是巧妙的，也是具体、细致的。一个人思念另一个人，其思想活动总有具体内容，或者回忆过去在一起的时光，或者憧憬日后见面的欢乐，或者关心牵挂对方目下在外边的生活，想象着他现在正在做什么，如此等等。这种借写被思念人的活动以突出思念者感情急切深沉的方法，早在《诗经》中就有，到了宋人柳永笔下更有所谓“想佳人，妆楼颙望，误几回，天际识归舟”，那就更加精采了。这种写法的好处是翻进一层，使人更加感到曲折、细致、具体。淹留：久留。“君何淹留寄他方？”这里有期待，有疑虑，同时也包含着无限的悬心。是什么原因使你至今还不能回来呢？是因为修筑繁忙？是因为战事紧急？是因为你生病了？受伤了？还是……那简直更不能想了。看，女主人公的心思多么沉重啊！\n\n　　“贱妾茕茕守空房，忧来思君不敢忘，不觉泪下沾衣裳。”茕茕（qióngqióng）：孤单，孤独寂寞的样子。不敢：谨虚客气的说法，实指不能、不会。这三句描写了女主人公在家中的生活情景：她独守空房，整天以思夫为事，常常泪落沾衣。这一方面表现了她生活上的孤苦无依和精神上的寂寞无聊；另一方面又表现了女主人公对她丈夫的无限忠诚与热爱。她的生活尽管这样凄凉孤苦，但是她除了想念丈夫，除了盼望着他的早日回归外，别无任何要求。\n\n　　“援琴鸣弦发清商，短歌微吟不能长。”援：引，拿过来。清商：东汉以来在民间曲调基础上形成的一种新乐调，以悲惋凄清为其特色。短歌：调类名，汉乐府有长歌行、短歌行，是根据“歌声有长短”（《乐府诗集》语）来区分的，大概是长歌多表现慷慨激昂的情怀，短歌多表现低回哀伤的思绪。女主人公在这秋月秋风的夜晚，愁怀难释，她取过瑶琴想弹一支清商曲，以遥寄自己难以言表的衷情，但是口中吟出的都是急促哀怨的短调，总也唱不成一曲柔曼动听的长歌。《礼记·乐记》云：“乐也者，情之不可变者也。”女主人公寂寞忧伤到了极点，即使她想弹别样的曲调，又怎么能弹得成呢？\n\n　　“明月皎皎照我床，星汉西流夜未央。牵牛织女遥相望，尔独何辜限河梁？”女主人公伤心凄苦地怀念远人，她时而临风浩叹，时而抚琴低吟，旁徨徙倚，不知过了多久。月光透过帘栊照在她空荡荡的床上，她抬头仰望碧空，见银河已经西转，她这时才知道夜已经很深了。“夜未央”，在这里有两层含意，一层是说夜正深沉，我们的女主人公何时才能捱过这凄凉的漫漫长夜啊！另一层是象征的，是说战争和徭役无穷无尽，我们女主人公的这种人生苦难，就如同这漫漫黑夜，还长得很，还看不到个尽头呢！面对着这沉沉的夜空，仰望着这耿耿的星河，品味着这苦痛的人生，作为一个弱女子，我们的女主人公她又有什么办法能改变自己的命运呢？这时，她的眼睛忽然落在了银河两侧的那几颗亮星上：啊！牛郎织女，我可怜的苦命的伙伴，你们到底有什么罪过才叫人家把你们这样地隔断在银河两边呢？牵牛、织女分别是天鹰和天琴星座的主星，这两颗星很早以来就被我国古代人民传说成一对受迫害，不能团聚的夫妻，这是家喻户晓，无人不知的事情。女主人公对牵牛织女所说的这两句如愤如怨，如惑如痴的话，既是对天上双星说的，也是对自己说的，同时也是对和自己命运相同的千百万被迫分离、不能团聚的男男女女们说的。这个声音是一种强烈的呼吁，是一种悲凉的控诉，是一种愤怒的抗议，它仿佛是响彻了当时的苍穹，而且在以后近两千年的封建社会里年年月月、时时刻刻都还可以听到它的响亮的回声。这样语涉双关，言有尽而余味无穷，低回而又响亮的结尾，是十分精采的。\n\n　　作品表现的思想并不复杂，题材也不算特别新鲜，但是曹丕作为一个统治阶级的上层人物能关心这样一种涉及千家万户的事情，而在诗中寄予了如此深刻的同情，这是很可贵的。在艺术上他把抒情女主人公的感情、心理描绘得淋漓尽致，她雍容矜重，炽烈而又含蓄，急切而又端庄。作品把写景抒情、写人叙事，以及女主人公的那种自言自语，巧妙地融为一体，构成了一种千回百转、凄凉哀怨的风格。它的辞藻华美，也袭用了许多前人的东西，但这一切又象是完全出之于无心，而不带任何雕琢的痕迹。这是《燕歌行》的特点，也是曹丕诗歌区别于建安其他诗人的典型特征。曹丕是个政治家，但从他的作品中往往看不到其父曹操那种慷慨激扬以天下为己任的气概，也找不到其弟曹植那种积极上进志欲报效国家的思想。在他那里总象是有一种诉说不完的凄苦哀怨之情，而且他的言事抒情又常常爱用妇女的口吻，因此明代锺惺说他的诗“婉娈细秀，有公子气，有文人气”（《古诗归》）。清代陈祚明说他的诗“如西子捧心，俯首不言，而回眸动盻无非可怜之绪”（《采菽堂古诗选》）。《燕歌行》可以说是最能代表曹丕这种思想和艺术风格特征的作品。前人对这两首诗的评价是很高的，清代吴淇说：“风调极其苍凉，百十二字，首尾一笔不断，中间却具千曲百折，真杰构也。”（《六朝选诗定论》）王夫之说：“倾情倾度，倾色倾声，古今无两。”（《姜斋诗话》）\n\n　　《燕歌行》二首在七言诗的发展史上有重要地位，这也是我们应该知道的。《诗经》基本是四言体，偶尔也出个七言句子，但为数甚少。《楚辞》是楚歌体，有七言句，但大多数都带有“兮”字，与七言诗句子的格式韵味不同。汉代乐府中有一部分杂言体，如《战城南》、《东门行》等，其中有一部分七言句，这些对于七言诗的发展显然是有促进的，但七言句在那些作品中还不是主体。两汉四百年间，全篇由七言构成的作品今天被人们提到的有两首，第一首是汉武帝时的君臣联句，即所谓《柏梁台诗》。这首诗出于后代小说，漏洞甚多，原不可信，而且生编硬凑，堆砌敷衍，也完全没有什么诗味。第二首是张衡的《四愁诗》。诗味很浓，但张衡这四首诗每首的第一句还都带着一个“兮”字，还拖着一个楚歌的尾巴。因此，真正摆脱了楚歌形式的羁绊，使七言形式宣告独立的作品就不能不说是曹丕的这两首《燕歌行》了。由此我们可以看到曹丕学习汉代乐府，学习前人诗歌，在形式上勇于探索、勇于创新的精神。《燕歌行》句句压韵，而且都是平声，格调清丽宛转，这是七言古诗发展的一个阶段。晋宋作家模写七言，还照此继续走了相当长的一段路。后来又经过南朝鲍照、萧绎、庾信等人的努力，到唐代卢照邻、骆宾王那种隔句用韵、平仄相押的鸿篇巨制出现的时候，那时七言古诗就又进入一个更新的发展阶段了。可见，曹丕的开创之功是不能掩没的。', poem_tags = '古诗三百首,乐府,秋天,女子,怀人' WHERE poem_title = '燕歌行二首·其一' AND poem_author = '曹丕';
UPDATE edu_poem SET poem_translation = '叶公喜欢龙，衣带钩、酒器上刻着龙，居室里雕镂装饰的也是龙。他这样爱龙，被天上的真龙知道后，便从天上下降到叶公家里，龙头搭在窗台上探望，龙尾伸到了厅堂里。叶公一看是真龙，转身就跑，吓得他像失了魂似的，惊恐万状，不能控制自己 。由此看来，叶公并不是真的喜欢龙，他喜欢的只不过是那些像龙却不是龙的东西罢了。', poem_notes = '叶公：春秋时楚国叶县县令沈诸梁，名子高，封于叶（古邑名，今河南叶县）。\n子高：叶公的字。\n钩：衣服上的带钩。\n写：画。\n凿：通“爵“，古代饮酒的器具。\n屋室雕纹：房屋上雕刻的图案、花纹\n“文”通“纹”。\n以：在\n闻：听说。\n下之：到叶公住所处。\n窥（kuī)：这里是探望、偷看的意思。\n牖（yǒu)：窗户。\n施（yì）：延伸，同“拖”。\n堂：厅堂\n还（xuán）走：转身就跑。还，通“旋”。\n走：逃跑。\n五色无主：脸色一忽儿白，一忽儿黄。五色，这里指脸色。\n是：由此看来。\n好：喜欢。\n夫：这，那。\n是叶公非好龙也：由此看来，叶公并不是真的喜欢龙。', poem_appreciation = '这个故事，用很生动的比喻，辛辣地讽刺了叶公式的人物，深刻地揭露了他们只唱高调、不务实际的坏思想、坏作风。通过这个故事，我们要丢弃“理论脱离实际“的坏思想、坏作风，树立实事求是的好思想、好作风。同时也讽刺了名不副实、表里不一的人。但历史上的叶公却不是这样的人。\n\n　　叶公最著名的功劳是他不以怨报德，果断率兵平定了白公胜的叛乱，从而稳定了楚国政权。之后，为了楚国的长治久安，把职位让给别人，这一让贤之举，被专家们评为不迷权贵、深明大义。\n\n　　叶公沈诸梁，字子高，被楚昭王封为叶邑尹而始姓叶。叶公生于楚国王室之家，其曾祖父是春秋五霸之一的楚庄王。秦国出兵击退吴军后，楚昭王把沈诸梁封到楚国北疆重镇“方城之外”的叶邑为尹。沈诸梁受到了楚国朝野及四境诸侯的敬重，时年24岁。\n\n　　经考古发掘证实，他主持叶政期间，采取养兵息民、发展农业、增强国力的策略，组织民众修筑了中国现存最早的水利工程，使当地数十万亩农田得以灌溉，这比著名的蜀守李冰修的都江堰早200多年，比郑国渠早300多年。至今，叶公修筑的东陂、西陂遗址保存尚好，是叶公治水的历史见证。\n\n　　史学专家安国楼博士称，叶公确实有画龙的爱好，但龙是神化了的动物，不可能下降叶宅，“叶公好龙”折射出叶公所在地和所处时代龙文化的丰厚内涵。专家们还指出，汉代刘向描写的这一寓言故事，反映出汉代儒家思想走向独尊的地位后，对楚道之风等其他学派的贬斥。\n\n　　根据《周礼》规制，叶公去世后，即被立祠享祭。叶公的后裔为纪念祖上之德与祖居之地，部分改沈为叶，是为叶姓之源。因此，叶公沈诸梁又是世界叶姓华人公认的始祖。每年清明前后，澧河之滨的叶公墓前，来自海内外的叶姓子孙纷纷回乡祭祖，已成为中原文化旅游的一大景观。', poem_tags = '小学文言文,寓言,故事,哲理' WHERE poem_title = '叶公好龙' AND poem_author = '刘向';
UPDATE edu_poem SET poem_translation = '公输盘替楚国造云梯这类攻城的器械，造成后，将要用它来攻打宋国。墨子先生听到这个消息后，从鲁国出发，行走了十天十夜，才到达郢都，见到了公输盘。\n\n　　公输盘说：“先生有什么见教呢？”\n\n　　墨子先生说：“北方有一个欺侮我的人，我希望借助您的力量去杀了他。”\n\n　　公输盘很不高兴。\n\n　　墨子先生说：“请让我奉送（给您）十金。”\n\n　　公输盘说：“我坚守道义坚决不杀人。”\n\n　　墨子先生起身，拜了两拜，说：“请（让我）解说这件事。我在北方听说你在制造云梯，将要用它来攻打宋国。宋国有什么罪呢？楚国在土地方面有富余却在人口方面不够，牺牲不足的人口而争夺多余的土地，不能说是明智的；宋国没有罪却攻打它，不能说是仁义的；知道这道理而不对楚王进行劝阻，不能说是忠君的；劝阻却没有成功，这不能称作坚持；你崇尚仁义不肯帮我杀死欺负我的一个人，却要为楚国攻打宋国而杀死很多人，不能叫做明白事理。”\n\n　　公输盘被说服了。\n\n　　墨子先生说：“既然这样，那么为什么不停止计划呢？”\n\n　　公输盘说：“不行，我已经向楚王说了这件事了。”\n\n　　墨子先生说：“为什么不向楚王引见我呢？”\n\n　　公输盘说：“好吧。”\n\n　　墨子先生拜见了楚王，说：“现在这里有一个人，舍弃他自己装饰华美的车，邻居有破车，却想要去偷；舍弃自己华美的衣服，邻居有件粗布衣服，却想要去偷；舍弃自己的好饭好菜，邻居只有粗劣饭食，却想要去偷。——这是怎么样的一个人呢？”\n\n　　楚王回答说：“这个人一定是患有偷盗的毛病了。”\n\n　　墨子先生说：“楚国的土地，方圆大小足有五千里；宋国的土地，方圆大小不过五百里，这好像装饰华美的车子同破车相比。楚国有云梦泽，里面有成群的犀牛麋鹿，长江、汉水里的鱼，鳖，鼋，鳄鱼多得天下无比；宋国却像人们所说的一样，是一个连野鸡、兔子、小鱼都没有的地方，这好像美食佳肴同糠糟相比。荆国有巨松、梓树、黄楩木、楠、樟等名贵木材；宋国是一个连多余的木材都没有的国家，这就像华丽的衣服与粗布短衣相比。我认为大王派官吏进攻宋国，是和这个患偷窃病的人的行为是一样的。”\n\n　　楚王说：“好啊！虽然这样，(但是)公输盘给我造了云梯，一定要攻取宋国。”\n\n　　在这种情况下（楚王）召见公输盘，墨子先生解下衣带，用衣带当作城墙，用木片当作守城器械。公输盘多次用了攻城的巧妙战术，墨子先生多次抵御他。公输盘的攻城的方法用尽了，墨子先生的抵御器械还绰绰有余。\n\n　　公输盘理屈，却说：“我知道用来抵御你的方法，可我不说。”\n\n　　墨子先生说：“我知道你要用来抵御我的方法，我也不说。”\n\n　　楚王问其中的缘故。\n\n　　墨子先生说：“公输先生的意思，不过是要杀掉我。杀了我，宋国没有人能守城，就可以攻取了。可是我的学生禽滑厘等三百多人，已经拿着我的守城器械，在宋国城上等待楚国入侵了。即使杀了我，也不能杀尽（宋国的抵御者）啊。”\n\n　　楚王说：“好，我不攻打宋国了。”\n\n　　墨子从楚国归来，经过宋国，天下着雨，他到闾门去避雨，守闾门的人却不接纳他。所以说：“运用神机的人，众人不知道他的功劳；而于明处争辩不休的人，众人却知道他。”', poem_notes = '公输盘：鲁国人，公输是姓，盘是名，也写做“公输班”。能造奇巧的器械，有人说他就是鲁班。\n云梯：古代战争中攻城用的器械，因其高而称为云梯。\n将以攻宋：准备用来攻打宋国。以，用来。将，准备。\n子墨子：指墨翟（此字念“dí“，；姓中念作“zhái“）。前一个“子”是夫子（即先生、老师）的意思，学生对墨子的尊称。后一个是当时对男子的称呼。\n闻之：闻，听说。之，代指攻宋这件事。\n起于鲁：起，起身，出发。于，从。\n而：表顺承。\n至于郢：至于，到达。郢，春秋战国时楚国国都，在今天的湖北江陵。\n夫子：先生，古代对男子的敬称，这里是公输盘对墨子的尊称。\n何命焉为：有什么见教呢？命，教导，告诫。焉为，两个字都是表达疑问语气的句末助词。\n侮：欺侮。\n臣：墨子的自我谦称（秦汉以前对一般人也可自称“臣”）。\n愿借子杀之：希望借助你的力量去杀了他。愿，希望。借，凭借，依靠。\n说：通“悦”，高兴，愉快。\n请献十金：请允许我奉送（你）十金（作为杀人的酬）。请，和下文“请说之”的“请”，大致相当于现在的“请允许我”。金：量词，先秦以二十两（银子）为一金。\n义：坚守道义。\n固：坚决，从来。\n再拜：先后拜两次，表示郑重的礼节。再：第二次。\n请说之：请允许我解说这件事。说：解说。之：代词，代墨子下面要说的话。\n吾从北方闻子为梯：我在北方听说您制造了云梯。为：做，造。\n何罪之有：即“有何罪”，有什么罪呢？之：提宾标志。\n荆国有余于地而不足于民：荆国有的是土地而没有足够的人民。荆国：楚国的别称。有余于地：在土地方面有多。于：在……方面。\n杀所不足而争所有余：损失不足的而争夺有余的，意思是牺牲百姓的生命去争夺土地。而，表转折，却。\n不可谓智：不可以说是聪明。\n仁：对人亲善，友爱。\n知而不争（zhèng）：知道这道理却不对楚王进行劝谏。\n不得：不能达到目的。\n知类：明白类推的道理。类：对事物作类比进而明白它的事理。\n服：信服。\n然胡不已乎：但是为什么不停止（攻打宋国的计划）呢？ 然：但是。胡：为什么。已：停止。\n胡不见我于王：为什么不向楚王引见我呢？见：引见。于王：状语后置语。王：指楚惠王。\n诺：好，表示同意。\n文轩：装饰华美的车。文：彩饰。轩：有篷的车。\n敝舆：破车。\n褐：粗布衣服。\n粱肉：好饭好菜。\n何若：什么样的。\n犹......之与......也：好像.......同.....相比。固定用法。\n云梦：楚国的大泽，跨长江南北，也包括今天的洞庭湖、洪湖和白鹭湖等湖沼。\n犀：雄性的犀牛。\n兕：雌性的犀牛。\n鼍：鳄鱼。\n鲋鱼：一种像鲫鱼的小鱼。\n文梓：梓树。文理明显细密，所以叫文梓。楩：黄楩木。豫章：樟树。这些都是名贵的木材。\n长木：多余的木材。\n王吏：指楚王所派攻宋的官吏。\n善哉：好呀。\n虽然：虽然如此。\n见：召见。\n牒：木片。\n九：表示次数多，古代“三”、“九”常有这种用法。\n机变：巧妙的方式。\n距：通“拒”，抵御。\n尽：完。\n守圉：守卫。圉：通“御”，抵挡。\n诎：通“屈”，意思是理屈，（办法）穷尽。\n所以：用来……的方法。和现代汉语利用来表示因果关系的连词“所以”不同。\n莫：没有谁。\n禽滑厘：人名，魏国人。墨子学生。\n已：已经。\n寇：入侵。\n虽杀臣，不能绝也：即使杀了我 ，也不能（杀）尽（宋的守御者）。虽：即使。绝：尽。', poem_appreciation = '《公输》（《公输》为后人添加的，取的是文章的前两个字）通过墨子止楚攻宋的故事，生动地叙述了墨子为实现自己的“非攻”主张，所表现出的艰苦实践和顽强斗争的精神，同时也暴露了公输盘和楚王的阴险狡诈，从而说明只有把道义和实力结合起来，才能迫使侵略者收敛其野心。\n\n　　在这篇文章里，墨子对战争的性质看得是比较清楚的。他能明确指出楚攻宋之不义，因而他不辞辛劳，长途跋涉赶到楚国都城，以实际行动去制止战争的发生。正因为墨子站在正义一边，所以自始至终，都以主动进攻的姿态向公输盘及其主子楚王进行了无可调和的斗争，而且理直气壮，义正辞严。要想制止这场战争的发生，是一件极为不易的事。然而墨子终于制止了这场战争。这固然同墨子的机智善辩颇有关系，但更重要的却在于他能够针对敌方的要害展开攻势。首先，他从道义上击败敌人。墨子至楚后，公输盘问他为何而来，他说：“北方有侮臣者，愿借子杀之。”先是使得公输盘“不说（悦）”，继而逼出“吾义固不杀人。”但公输盘只知道杀一人谓之不义，却不知兴师攻宋杀更多的人，是更大的不义。所以墨子接着指出：“义不杀少而杀众，不可谓知类。”把公输盘说得哑口无言。在十分狼狈的情况下，公输盘不得不把责任转嫁到楚王身上。墨子见楚王，同样采取了“以子之矛攻子之盾”的办法，从道义上谴责楚攻宋之不义。他以富人盗窃穷人为喻，问楚王“此为何若人”，使楚王承认此人“必为有窃疾矣”。因此楚以富有之国而攻伐贫穷之宋，正“为与此同类”。在墨子强有力的论据面前，楚王也不得不诺诺称是。公输盘的“义不杀少而杀众”和楚王以富窃贫，在道义上都是站不住的，因而他们理屈词穷，弄得尴尬不堪。从而说明对于强大而又顽固之敌，只是在道义上攻破它还远远不够，与此同时，还必须在实力上同敌人较量，并压倒它，才有可能迫使侵略者放弃勃勃野心。墨子意识到了这一点。因而他“解带为城，以牒为械。公输盘九设攻城之机变。子墨子九距之。公输盘之攻械尽，子墨子之守圉有余”。这虽然只停留于近乎纸上谈兵，却是一次战术上的较量，大大灭了公输盘仗恃云梯之械攻宋的嚣张气焰。公输盘虽被挫败，但侵宋之心仍然不死。直到墨子说出即使杀掉他，“然臣之弟子禽滑厘等三百人，已持臣守圉之器，在宋城上而待楚寇矣”之时，在实力的对抗之下，才使公输盘和楚王死了攻宋之心。\n\n　　阻止这场战争的不是道义，而是墨子的智慧，在绝对失败的情况下，楚王放弃攻打宋国。\n\n　　这表明，面对大国的不义之战，要敢于斗争。一方面要从道义上揭露其不义，使他们在舆论上威风扫地；另一方面，要从实力上作好充分准备，使他们的侵略野心无法得逞。这个道理，不仅在历史上是行之有效的，而且在今天也不无借鉴意义。\n\n　　从写作特点来看，本文通过曲折生动的故事，围绕矛盾冲突来阐明道理，凸显人物性格。当墨子到楚国见到公输盘，经过道义上的一番谴责之后，公输盘“服”了。它似乎意味着矛盾得以解决。其实不然。当墨子指出：你既然“服”了，何以不停止攻宋呢？这么一问，公输盘却把责任转嫁于楚王。这既说明他口是心非，又引出了与楚王的新矛盾。为解决它，墨子去见楚王，从道义上把楚王驳得体无完肤，致使楚王称“善”。看来矛盾该是解决了。其实不然。楚王同公输盘一样，只不过是耍了个花招罢了。他在称“善”之后用“虽然”二字一转，又把责任推到公输盘身上，说什么“公输盘为我为云梯，必取宋”。这样一来，矛盾就更加复杂化了。又是与楚王的矛盾，又是与公输盘的矛盾，二者错综交织在一起。面对这样顽固而又狡诈的敌人，如果还采取先前那种从道义上揭露的办法对付他们，显然是不能奏效的。那么究竟怎样解决这一矛盾，既是摆在墨子面前的一个十分艰巨的课题，也是读者想要急切知道的。出自墨子的机智多谋，来了个以眼还眼，以牙还牙。既然楚王和公输盘都仗恃云梯这一攻城之械来攻宋，就需要把云梯这个迷信予以彻底摧毁。于是墨子便在战术上与公输盘来一次较量。较量的结果，公输盘彻底失败，屈服了。然而，矛盾非但没有解决，且向纵深发展。公输盘在黔驴技穷的情况下，竟想下毒手把墨子这个劲敌杀掉，妄图扫清攻宋道路上的障碍。但是这一阴谋不但未能得逞，反被墨子一眼看穿进而一针见血地当面揭露。墨子还严正告诉他们：“臣之弟子禽滑厘等三百人，已持臣守圉之器，在宋城上而待楚寇矣。虽杀臣，不能绝也。”最后在实力的对比和威慑之下，楚王才被迫说出“善哉！吾请无攻宋矣”的话来。矛盾终于得以解决。试看故事是多么曲折生动！矛盾冲突犹如波浪起伏，滚滚向前推进。\n\n　　再者，作者还善于运用类比说理，进行层层推理。墨子见公输盘和楚王，都不是直陈其事，开宗明义，而是先作比喻，然后进行逻辑推理，使之持之有故，言之成理，这就大大增强了说服力，收到了很好的艺术效果。而尤为突出者，是作者运用比喻之妙。诸如墨子见到公输盘后，公输盘问他有何见教，他并不正面直答来意，而说：“北方有侮臣者，愿借子杀之。”他把问题说得十分严重，意在一下子把对方的注意力引到这件事上，迫使对方对这件事立即表示态度，说出意见，亦即使对方说出自己要他说出的话来。可是公输盘偏偏不说，只是表示不高兴。公输盘不说，当然没有达到预期的目的。于是只好再来个火上加油，“请献十金”。这意味着要拿金钱贿赂收买他，让他去干杀人的勾当。这下子公输盘可沉不住气了，便脱口说出“吾义固不杀人”。墨子之所以使他不高兴，继而又激怒他，无非是让他说出这句话来，然后再予以批驳。墨子见楚王，则是另一番气象。一开头就作比说：“今有人于此”如此这般。他不用“倘若”“假如”等假设字样，好像是讲一件实实在在的事，使对方不致发生错觉，能够听得进去，然后让对方说出自己要他说出的话来。墨子连用了三个比喻，然后问楚王：“此为何若人？”楚王很痛快地回答说：“必为有窃疾矣。”既然回答得痛快，那就毫无必要再用激将的办法进一步逼问了。但读者完全可以想像，假如楚王也像公输盘那样吞吞吐吐的话，墨子将会用别的办法使他说出自己要他说的话的。可见，墨子是根据不同对象的表现，而采用不同的方式方法。总之，要他们说话，要他们说出自己想要他们说的话。不说话，不行；说了话，达不到自己的目的也不作罢。只要他们说了话，事情就好办了，就可以抓其把柄，以子之矛攻子之盾了。墨子就是用这种引鱼上钩、先发制人的办法，进行说理的，自始至终都以主动进攻的姿态出现，使对方完全处于被动挨打的地位。文章之所以富有逻辑性和说服力，是同这种说理方法密不可分的。', poem_tags = '初中文言文,对话,写人,故事' WHERE poem_title = '公输' AND poem_author = '墨子及弟子';
UPDATE edu_poem SET poem_translation = '在深山中送走了好友，夕阳落下把柴门半掩。\n春草到明年催生新绿，朋友啊你能不能回还？', poem_notes = '⑴掩：关闭。柴扉：柴门。\n⑵明年：一作“年年”。\n⑶王孙：贵族的子孙，这里指送别的友人。', poem_appreciation = '这首《山中送别》诗，不写离亭饯别的情景，而是匠心别运，选取了与一般送别诗全然不同的下笔着墨之点。\n\n　　诗的首句“山中相送罢”，在一开头就告诉读者相送已罢，把送行时的话别场面、惜别情怀，用一个看似毫无感情色彩的“罢”字一笔带过。这里，从相送到送罢，跳越了一段时间。而次句从白昼送走行人一下子写到“日暮掩柴扉”，则又跳越了一段更长的时间。诗人在把生活接入诗篇时，剪去了在这段时间内送行者的所感所想，都当作暗场处理了。\n\n　　对离别有体验的人都知道，行人将去的片刻固然令人黯然魂消，但一种寂寞之感、怅惘之情往往在别后当天的日暮时会变得更浓重、更稠密。在这离愁别恨最难排遣的时刻，要写的东西也定必是千头万绪的；可是，诗只写了一个“掩柴扉”的举动。这是山居的人每天到日暮时都要做的极其平常的事情，看似与白昼送别并无关连。而诗人却把这本来互不关连的两件事连在了一起，使这本来天天重复的行动显示出与往日不同的意味，从而寓别情于行间，见离愁于字里。读者自会从其中看到诗中人的寂寞神态、怅惘心情；同时也会想：继日暮而来的是黑夜，在柴门关闭后又将何以打发这漫漫长夜呢？这句外留下的空白，更是使人低回想象于无穷的。\n\n　　诗的三、四两句“春草明年绿，王孙归不归”，从《楚辞·招隐士》“王孙游兮不归，春草生兮萋萋”句化来。但赋是因游子久去而叹其不归，这两句诗则在与行人分手的当天就惟恐其久去不归。唐汝询在《唐诗解》中概括这首诗的内容为：“扉掩于暮，居人之离思方深；草绿有时，行人之归期难必。”而“归期难必”，正是“离思方深”的一个原因。“归不归”，作为一句问话，照说应当在相别之际向行人提出，这里却让它在行人已去、日暮掩扉之时才浮上居人的心头，成了一个并没有问出口的悬念。这样，所写的就不是一句送别时照例要讲的话，而是“相送罢”后内心深情的流露，说明诗中人一直到日暮还为离思所笼罩，虽然刚刚分手，已盼其早日归来，又怕其久不归来了。前面说，从相送到送罢，从“相送罢”到“掩柴扉”，中间跳越了两段时间；这里，在送别当天的日暮时就想到来年的春草绿，而问那时归不归，这又是从当前跳到未来，跳越的时间就更长了。\n\n　　这首送别诗，不写离亭饯别的依依不舍，却更进一层写冀望别后重聚。这是超出一般送别诗的所在。开头隐去送别情景，以“送罢”落笔，继而写别后回家寂寞之情更浓更稠，为望其再来的题意作了铺垫，于是想到春草再绿自有定期，离人回归却难一定。惜别之情，自在话外。意中有意，味外有味，真是匠心别运，高人一筹。\n\n　　王维善于从生活中拾取看似平凡的素材，运用朴素、自然的语言，来显示深厚、真挚的感情，令人神远。这首《山中送别》诗就是这样的。', poem_tags = '唐诗三百首,送别,友情' WHERE poem_title = '送别 / 山中送别' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '逃亡生活是如此紧张，看到有人家就上门投宿，我希望出亡的康有为、梁启超能像张俭一样受到人们的保护。也希望战友们能如杜根一样忍死待机完成变法维新的大业。\n我横刀而出，仰天大笑，因为去者和留者肝胆相照、光明磊落，有如昆仑山一样的雄伟气魄。', poem_notes = '望门投止：望门投宿。张俭：东汉末年高平人，因弹劾宦官侯览，被反诬“结党”，被迫逃亡，在逃亡中凡接纳其投宿的人家，均不畏牵连，乐于接待。事见《后汉书·张俭传》。\n忍死：装死。须臾：不长的时间。杜根：东汉末年定陵人，汉安帝时邓太后摄政、宦官专权，其上书要求太后还政，太后大怒，命人以袋装之而摔死，行刑者慕杜根为人，不用力，欲待其出宫而释之。太后疑，派人查之，见杜根眼中生蛆，乃信其死。杜根终得以脱。事见《后汉书·杜根传》。\n横刀：屠刀，意谓就义。\n两昆仑：有两种说法，其一是指康有为和浏阳侠客大刀王五；其二为“去”指康有为（按：康有为在戊戌政变前潜逃出京，后逃往日本），“留”指自己。', poem_appreciation = '这首诗表达了对避祸出亡的变法领袖的褒扬祝福，对阻挠变法的顽固势力的憎恶蔑视，同时也抒发了诗人愿为自己的理想而献身的壮烈情怀。\n\n　　“望门投止思张俭止”这一句，是身处囹圄的谭嗣同记挂、牵念仓促出逃的康有为等人的安危，借典述怀。私心祈告：他们大概也会像张俭一样，得到拥护变法的人们的接纳和保护。\n\n　　“忍死须臾待杜根”，是用东汉诤臣义士的故事，微言大义。通过运用张俭的典故，以邓太后影射慈禧，事体如出一辙，既有对镇压变法志士残暴行径的痛斥，也有对变法者东山再起的深情希冀。这一句主要是说，戊戌维新运动虽然眼下遭到重创，但作为锐意除旧布新的志士仁人，应该志存高远，忍死求生。等待时机，以期再展宏图。\n\n　　“我自横刀向天笑”是承接上两句而来：如若康、梁诸君能安然脱险，枕戈待旦，那么，我谭某区区一命岂足惜哉，自当从容地面对带血的屠刀，冲天大笑。“让魔鬼的宫殿在笑声中动摇”。对于死，诗人谭嗣同早有准备。当政变发生时，同志们曾再三苦劝他避居日本使馆，他断然拒绝，正是由于他抱定了必死的决心，所以才能处变不惊，视死如归。\n\n　　“去留肝胆两昆仑”，对于去留问题，谭嗣同有自己的定见。在政变的第二天，谭氏待捕不至，遂往日本使馆见梁启超，劝其东游日本。他说：“不有行者，无以图将来；不有死者，无以酬圣主。今南海（康有为）之生死未可卜，程婴、杵臼、月照、西乡，吾与足下分任之。”他出于“道”（变法大业、国家利益），也出于“义”（君臣之义、同志之义），甘愿效法《赵氏孤儿》中的公孙杵臼和日本德川幕府末期月照和尚的好友西乡的行节，以个人的牺牲来成全心目中的神圣事业，以自己的挺身赴难来酬报光绪皇帝的知遇之恩。同时，他也期望自己的一腔热血能够惊觉苟且偷安的芸芸众生，激发起变法图强的革命狂澜。在他看来，这伟大的身后事业，就全靠出奔在逃的康、梁们的推动和领导。基于这种认知，他对分任去留两职的同仁同志，给予了崇高的肯定性评价：去者，留者。路途虽殊，目标则同，价值同高，正像昆仑山的两座奇峰一样，比肩并秀，各领千秋风骚。', poem_tags = '古诗三百首,爱国,悲壮,早教古诗100首,猖狂' WHERE poem_title = '狱中题壁' AND poem_author = '谭嗣同';
UPDATE edu_poem SET poem_translation = '夜深宴饮在东坡的寓室里醒了又醉，回来的时候仿佛已经三更。这时家里的童仆早已睡熟鼾声如雷鸣。轻轻地敲了敲门，里面全不回应，只好独自倚着藜杖倾听江水奔流的吼声。\n　　经常愤恨这个躯体不属于我自己，什么时候能忘却为功名利禄而奔竞钻营！趁着这夜深、风静、江波坦平，驾起小船从此消逝，泛游江河湖海寄托余生。', poem_notes = '东坡：在湖北黄冈县东。苏轼谪贬黄州时，友人马正卿助其垦辟的游息之所，筑雪堂五间。\n听江声：苏轼寓居临皋，在湖北黄 县南长江边，故能听长江涛声。\n营营：周旋、忙碌，内心躁急之状，形容为利禄竟逐钻营。\n夜阑：夜尽。\n縠纹：比喻水波细纹。縠，绉纱。', poem_appreciation = '上片赏析 　　这首词作于神宗元丰五年，即东坡黄州之贬的第三年。全词风格清旷而飘逸，写作者深秋之夜在东坡雪堂开怀畅饮，醉后返归临皋住所的情景，表现了词人退避社会、厌弃世间的人生理想、生活态度和要求彻底解脱的出世意念，展现了作者旷达而又伤感的心境。\n\n　　上片首句“夜饮东坡醒复醉”，一开始就点明了夜饮的地点和醉酒的程度。醉而复醒，醒而复醉，当他回临皋寓所时，自然很晚了。“归来仿佛三更”，“仿佛” 二字，传神地画出了词人醉眼朦胧的情态。这开头两句，先一个“醒复醉”，再一个“仿佛”，就把他纵饮的豪兴淋漓尽致地表现出来了。\n\n　　接着，下面三句，写词人已到寓所、在家门口停留下来的情景：“家童鼻息已雷鸣。敲门都不应，倚杖听江声。”走笔至此，一个风神潇洒的人物形象，一位襟怀旷达、遗世独立的“幽人”跃然纸上，呼之欲出。其间浸润的，是一种达观的人生态度，一种超旷的精神世界，一种独特的个性和真情。\n\n　　上片以动衬静，以有声衬无声，通过写家僮鼻息如雷和作者谛听江声，衬托出夜静人寂的境界，从而烘托出历尽宦海浮沉的词人心事之浩茫和心情之孤寂，使人遐思联翩，从而为下片当中作者的人生反思作好了铺垫。\n\n下片赏析 　　下片一开始，词人便慨然长叹道：“长恨此身非我有，何时忘却营营？”这奇峰突起的深沉喟叹，既直抒胸臆又充满哲理意味，是全词枢纽。\n\n　　以上两句精粹议论，化用庄子“汝身非汝有也”、“全汝形，抱汝生，无使汝思虑营营”之言，以一种透彻了悟的哲理思辨，发出了对整个存在、宇宙、人生、社会的怀疑、厌倦、无所希冀、无所寄托的深沉喟叹。这两句，既饱含哲理又一任情性，表达出一种无法解脱而又要求解脱的人生困惑与感伤，具有震撼人心的力量。\n\n　　词人静夜沉思，豁然有悟，既然自己无法掌握命运，就当全身免祸。顾盼眼前江上景致，是“夜阑风静縠纹平”，心与景会，神与物游，为如此静谧美好的大自然深深陶醉了。于是，他情不自禁地产生脱离现实社会的浪漫主义的遐想，唱道：“小舟从此逝，江海寄余生。”他要趁此良辰美景，驾一叶扁舟，随波流逝，任意东西，他要将自己的有限生命融化在无限的大自然之中。\n\n　　“夜阑风静彀纹平”，表面上看来只是一般写景的句子，其实不是纯粹写景，而是词人主观世界和客观世界相契合的产物。它引发出作者心灵痛苦的解脱和心灵矛盾的超越，象征着词人追求的宁静安谧的理想境界，接以“小舟”两句，自是顺理成章。苏东坡政治上受到沉重打击之后，思想几度变化，由入世转向出世，追求一种精神自由、合乎自然的人生理想。在他复杂的人生观中，由于杂有某些老庄思想，因而在痛苦的逆境中形成了旷达不羁的性格。“小舟从此逝，江海寄余生”，这余韵深长的歇拍，表达出词人潇洒如仙的旷达襟怀，是他不满世俗、向往自由的心声。', poem_tags = '宋词三百首,饮酒,抒怀,旷达' WHERE poem_title = '临江仙·夜饮东坡醒复醉' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '白梅生长在有冰有雪的树林之中，并不与桃花李花混在一起，沦落在世俗的尘埃之中。\n忽然间，这一夜清新的香味散发出来，竟散作了天地间的万里新春。', poem_notes = '著：放进，置入。此身：指白梅。\n混：混杂。芳尘：香尘。\n清香发：指梅花开放，香气传播。 \n乾坤：天地。', poem_appreciation = '“冰雪林中著此身”，就色而言，以“冰雪”形“此身”之“白”也；就品性而言，以“冰雪”形“此身”之坚忍耐寒也，诗人运用拟人手法，将梅树比作自己。已经表现白梅的冰清玉洁，接着就拿桃李作反衬。夭桃秾李，花中之艳，香则香矣，可惜争春太苦，未能一尘不染。“不同桃李混芳尘”的“混芳尘”，是说把芳香与尘垢混同，即“和其光，同其尘”、“和光同尘，不能为皎皎之操。”相形之下，梅花则能迥异流俗，所以“清香”二字，只能属梅，而桃李无份。\n\n　　“忽然一夜清香发，散作乾坤万里春”。也许只是诗人在灯下画了一枝墨梅而已。而诗句却造成这样的意向：忽然在一夜之中，全世界的白梅齐放，清香四溢，玉宇澄清。这首诗给人以品高兼志大，绝俗而又入世的矛盾统一的感觉，这又正是王冕人格的写照。\n\n　　前两句写梅花冰清玉洁，傲霜斗雪，不与众芳争艳的品格。后两句借梅喻人，写自己的志趣、理想与抱负，讴歌了为广大民众造福的英雄行为及牺牲精神。本文通过对梅花的吟咏描写，表达了诗人自己的志趣和品格。', poem_tags = '咏物,梅花,言志' WHERE poem_title = '白梅' AND poem_author = '王冕';
UPDATE edu_poem SET poem_translation = '七夕晚上，望着碧蓝的天空，就好像看见隔着“天河”的牛郎织女在鹊桥上相会。\n家家户户都在一边观赏秋月，一边乞巧（对月穿针），穿过的红线都有几万条了。', poem_notes = '乞巧：古代节日，在农历七月初七日，又名七夕。\n碧霄：指浩瀚无际的青天。\n几万条：比喻多。', poem_appreciation = '《乞巧》是唐代诗人林杰描写民间七夕乞巧盛况的诗。农历七月初七夜晚，俗称“七夕”，又称“女儿节”“少女节”。是传说中隔着“天河”的牛郎和织女在鹊桥上相会的日子。乞巧，就是向织女乞求一双巧手的意思。乞巧最普遍的方式是对月穿针，如果线从针孔穿过，就叫得巧。\n\n　　“七夕今霄看碧霄，牵牛织女渡河桥。”“碧霄”指浩瀚无际的青天。开头两句叙述的就是牛郎织女的民间故事。一年一度的七夕又来到了，家家户户的人们纷纷情不自禁地抬头仰望浩瀚的天空，这是因为这一美丽的传说牵动了一颗颗善良美好的心灵，唤起人们美好的愿望和丰富的想象。\n\n　　“家家乞巧望秋月，穿尽红丝几万条。”后两句将乞巧的事交代得一清二楚，简明扼要，形象生动。诗人在诗中并没有具体写出各种不同的心愿，而是留下了想象的空间，愈加体现了人们过节时的喜悦之情。', poem_tags = '小学古诗,七夕节' WHERE poem_title = '乞巧' AND poem_author = '林杰';
UPDATE edu_poem SET poem_translation = '归乡隐居的志向就算没有那五亩田园也依然如故，读书的本意原在于黎民百姓。\n灯下读书，眼神已大不如从前了。却还是阅读完了两万的蝇头小字。', poem_notes = '归志：返回的念头。\n宁无：难道没有。\n元元：指人民。\n课：诗中作阅读解。\n蝇头：比喻字小的和苍蝇头一样。', poem_appreciation = '陆游的诗歌继承了屈原以来诗人忧国忧民的优良传统，以现实主义风格为主，立足于时代，“归老宁无五亩园，读书本意在元元。”一二句直抒胸臆，说自己读书 是为了人民，前两句不重情节画面，而是把事实压缩在极其精炼的诗句内，着重抒写自己的主观感受，具有高度的概括性和强烈的抒情性。一个“宁无”把诗人内心深处对黎民百姓的牵挂表达的淋漓尽致。也显示诗人不为五斗米折腰的情操。在封建时代，能提出“读书本意在元元”，把读书看做是为百姓而读，展现了诗人的可贵。\n\n　　三四句是写实，具有二个特点：一是细节的真实性，灯下读书，眼神已大不如从前了。写这首诗时，诗人已经是老人了，透过诗句，诗人灯下读书的形象出现在眼前。二是具体描写方式的客观性，一盏青灯为何出现在陆游的诗中，因为是其读书生涯中最为重要的一件物体，故而成了其读书诗中最引人注目的一个意象。作者通过对现实生活的客观，具体的描写，从作品的场面和情节中自然地体现出作者的忠于人民思想倾向和爱憎感情，尽管明白如话，浅显平淡，但却浅中有深，平中有奇。把诗人在孤灯之下，老眼昏花地阅读蝇头小字的场景，维妙维肖地刻划出来。既是对生活描写，更是对后人告诫，寓意深远。\n\n　　陆游是一个善于学习的诗人。他提倡“万卷虽多应具眼”，又强调“诗思出门河处元？”他一生之中写出大量优秀诗篇，是与他的苦学精神分不开的。这首《读书》七绝，如同诗人的学习体会，既反映了诗人在年老时仍坚持苦学的情况，又表明了他学习是为平民百姓而并无他求的可贵精神。诗言志，诗歌是诗人对人生的歌咏，这是中国自古以来关于诗歌内容的基本要求。从这个角度出发，凡是属于人生的各类内容，都可以被纳入诗人取材的范围，不应有什么事先划定的禁区 。对于主要身份是士人的陆游来说，其生活内容有相当大的部分是在书斋里度过的，读书正是他人生经历的重要组成部分。于是当他要想写诗歌咏其生活内容，表示其人生感慨时，读书便理所当然成为不可或缺的题材。\n\n　　《读书》虽以读书为题材，但诗人的眼光早已离开书斋这个狭小的空间，他将目光投向于整个人民，所以他所有的读书诗包括《读书》，仍然充满着对生活的热爱，仍然流露着对生命的感慨，仍然是活色生香，精力充沛，是文学意味十分浓厚的好诗。同时他的读书诗既有现实主义的精神，使他的诗内容充实，热情横溢，显得既沉郁悲壮，又恢宏雄放。从平凡细微当中觅得诗情，写成活泼生动的好诗，一切都取决于诗人是否有灵心慧性。', poem_tags = '读书,忧国忧民' WHERE poem_title = '读书' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '新酿的米酒，色绿香浓；小小红泥炉，烧得殷红。\n天快黑了，大雪将要来。能否共饮一杯？朋友！\n\n意译\n我家新酿的米酒还未过滤，酒面上泛起一层绿泡，香气扑鼻。用红泥烧制成的烫酒用的小火炉也已准备好了。\n天色阴沉，看样子晚上即将要下雪，能否留下与我共饮一杯？', poem_notes = '刘十九：白居易留下的诗作中，提到刘十九的不多，仅两首。但提到刘二十八、二十八使君的，就很多了。刘二十八就是刘禹锡。刘十九乃其堂兄刘禹铜，系洛阳一富商，与白居易常有应酬。\n绿蚁：指浮在新酿的没有过滤的米酒上的绿色泡沫。醅（pēi）：酿造。\n绿蚁新醅酒：酒是新酿的酒。新酿酒未滤清时，酒面浮起酒渣，色微绿，细如蚁，称为“绿蚁”。\n雪：下雪，这里作动词用。\n无：表示疑问的语气词，相当于“么”或“吗”。', poem_appreciation = '刘十九是作者在江州时的朋友，作者另有《刘十九同宿》诗，说他是嵩阳处士。全诗寥寥二十字，没有深远寄托，没有华丽辞藻，字里行间却洋溢着热烈欢快的色调和温馨炽热的情谊，表现了温暖如春的诗情。\n\n　　诗句的巧妙，首先是意象的精心选择和巧妙安排。全诗表情达意主要靠三个意象（新酒、火炉、暮雪）的组合来完成。“绿蚁新醅酒”，开门见山点出新酒，由于酒是新近酿好的，未经过滤，酒面泛起酒渣泡沫，颜色微绿，细小如蚁，故称“绿蚁”。诗歌首句描绘家酒的新熟淡绿和浑浊粗糙，极易引发读者的联想，让读者犹如已经看到了那芳香扑鼻，甘甜可口的米酒。次句“红泥小火炉”，粗拙小巧的火炉朴素温馨，炉火正烧得通红，诗人围炉而坐，熊熊火光照亮了暮色降临的屋子，照亮了浮动着绿色泡沫的家酒。“红泥小火炉”对饮酒环境起到了渲染色彩、烘托气氛的作用。酒已经很诱人了，而炉火又增添了温暖的情调。诗歌一、二两句选用“家酒”和“小火炉”两个极具生发性和暗示性的意象，容易唤起读者对质朴地道的农村生活的情境联想。后面两句：“晚来天欲雪，能饮一杯无？”在这样一个风寒雪飞的冬天里，在这样一个暮色苍茫的空闲时刻，邀请老朋友来饮酒叙旧，更体现出诗人那种浓浓的情谊。“雪”这一意象的安排勾勒出朋友相聚畅饮的阔大背景，寒风瑟瑟，大雪飘飘，让人感到冷彻肌肤的凄寒，越是如此，就越能反衬出火炉的炽热和友情的珍贵。“家酒”、“小火炉”和“暮雪”三个意象分割开来，孤立地看，索然寡味，神韵了无，但是当这三个意象被白居易纳入这首充满诗意情境的整体组织结构中时，读者就会感受到一种不属于单个意象而决定于整体组织的气韵、境界和情味。寒冬腊月，暮色苍茫，风雪大作，家酒新熟、炉火已生，只待朋友早点到来，三个意象连缀起来构成一幅有声有色、有形有态、有情有意的图画，其间流溢出友情的融融暖意和人性的阵阵芳香。\n\n　　其次是色彩的合理搭配。诗画相通贵在情意相契，诗人虽然不能像雕塑家、画家那样直观地再现色彩，但是可以通过富有创意的语言运用，唤起读者相应的联想和情绪体验。这首小诗在色彩的配置上是很有特色的，清新朴实，温热明丽，给读者一种身临其境、悦目怡神之感。诗歌首句“绿蚁”二字绘酒色摹酒状，酒色流香，令人啧啧称美，酒态活现让读者心向“目”往。次句中的“红”字犹如冬天里的一把火，温暖了人的身子，也温热了人的心窝。“火”字表现出炭火熊熊、光影跃动的情境，更是能够给寒冬里的人增加无限的热量。“红”“绿”相映，色味兼香，气氛热烈，情调欢快。第三句中不用摹色词语，但“晚”“雪”两字告诉读者黑色的夜幕已经降落，而纷纷扬扬的白雪即将到来。在风雪黑夜的无边背景下，小屋内的“绿”酒“红”炉和谐配置，异常醒目，也格外温暖。\n\n　　最后是结尾问句的运用。“能饮一杯无”，轻言细语，问寒问暖，贴近心窝，溢满真情。用这样的口语入诗收尾，既增加了全诗的韵味，使其具有空灵摇曳之美，余音袅袅之妙；又创设情境，给读者留下无尽的想象空间。诗人既可能是特意准备新熟家酿来招待朋友的，也可能是偶尔借此驱赶孤居的冷寂凄凉；既可能是在风雪之夜想起了朋友的温暖，也可能是平日里朋友之间的常来常往。而这些，都留给读者去尽情想象了。\n\n　　通览全诗，语浅情深，言短味长。白居易善于在生活中发现诗情，用心去提炼生活中的诗意，用诗歌去反映人性中的春晖，这正是此诗令读者动情之处。\n\n　　《问刘十九》。诗从开门见山地点出酒的同时，就一层层地进行渲染，但并不因为渲染，不再留有余味，相反地仍然极富有包蕴。读了末句“能饮一杯无”，可以想象，刘十九在接到白居易的诗之后，一定会立刻命驾前往。于是，两位朋友围着火炉，“忘形到尔汝”地斟起新酿的酒来。也许室外真的下起雪来，但室内却是那样温暖、明亮。生活在这一刹那间泛起了玫瑰色，发出了甜美和谐的旋律……这些，是诗自然留给人们的联想。由于既有所渲染，又简练含蓄，所以不仅富有诱惑力，而且耐人寻味。它不是使人微醺的薄酒，而是醇醪，可以使人真正身心俱醉的。诗中蕴含生活气息，不加任何雕琢，信手拈来，遂成妙章。\n\n　　作品充满了生活的情调，浅进的语言写出了日常生活中的美和真挚的友谊。', poem_tags = '唐诗三百首,饮酒,生活,友情' WHERE poem_title = '问刘十九' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '新年来临思乡之心更切，独立天边不禁热泪横流。\n到了老年被贬居于人下，春归匆匆走在我的前头。\n山中猿猴和我同度昏晓，江边杨柳与我共分忧愁。\n我已和长太傅一样遭遇，这样日子须到何时才休？', poem_notes = '天畔：天边，指潘州南巴，即今广东茂名。潸（shān）然：流泪的样子。\n居人下：指官人，处于人家下面。客：诗人自指。\n“春归”句：春已归而自己尚未回去。\n岭：指五岭。作者时贬潘州南巴，过此岭。\n长沙傅：指贾谊。曾受谗被贬为长沙王太傅，这里借以自喻。', poem_appreciation = '在唐代，长沙以南地域都很荒凉，潘州一带的艰苦而可想而知，诗人受冤被贬，从鱼肥水美的江南苏州迁至荒僻的潘州，委屈之心不言而喻。诗人满腹冤屈化作一句诗语：“乡心新岁切，天畔独潸然”。新年已至，自己与亲人们相隔千里，思乡之心，自然更切。人欢己悲，伤悲之泪“潸然”而下。其实，伤心泪早就洒于贬途：“裁书欲谁诉，无泪可潸然。”（《毗陵集》）联系仕宦偃蹇，很难自控，而有“新年向国泪”（《酬郭夏人日长沙感怀见赠》）。这与“每逢佳节倍思亲”（王维《九月九日忆山东兄弟》）有异曲同工之处。\n\n　　“老至居人下，春归在客先”，是由薛道衡“人归落雁后，思发在花前”（《人日思归》）化出，在前人单纯的思乡之情中，融入仕宦身世之感，扩大了容量，增强了情感的厚度。两句有感而发，自然浑成，诚为甘苦之言。使笔运意，纯熟圆浑，字凝句炼，素来是诗人的所长，“老至”句承“独潸然”，“春归”句承“新岁切”，脉络细致，情意深沉。诗人有感年华“老至”，反遭贬而“居人下”。新年伊始，天下共春，而仍滞留炎南天畔，升迁无望，故有时不我待、春归我先之感。悲愤郁积，不能自己，因此连续以四句伤情语抒发。\n\n　　“岭猿同旦暮，江柳共风烟”二句描绘天畔荒山水乡节序风光。猿啼积淀着哀伤的诗歌意象。“猿鸣三声泪沾裳”的古谣，引发怨苦，以此属引凄厉之声度入诗中，与北方呜咽陇水同是感伤的声态意象，都令人怀悲而思归。刘长卿的仕历活动主要在南方，其诗中有很多表现猿啼的句子：“梦寐猿啼吟”、“万里猿啼断”、“猿啼万里客”。而这里犹再重之“同旦暮”——早晚、日夜时时在耳，起哀伤，动归思，进而把“乡心切”刻划得淋漓尽致。这新岁元日的惆怅，别有一番滋味在心头。远望，江流岸柳不但没有给诗人带来生机和新意，相反，风烟一空，濛濛笼罩，倒给诗人心头蒙上一层厚厚的愁雾。\n\n　　在抑郁、失落的情绪中诗人发出了长长的慨叹：“已似长沙傅，从今又几年？”这里借用贾谊的典故，洛阳才子贾谊，有济世匡国之志，脱颖初露，而为权贵宿老谗毁，疏放为长沙太傅。诗人这次遭贬，也是以功蒙过，怏怏哀怨，时有流露：“地远明君弃，天高酷吏欺”（《初贬南巴至鄱阳题李嘉祐江亭》）故引贾谊为同调，而有“同是天涯沦落人”的“已似”之感。而自忤权门，担心滞此难返，不免生出“从今又几年”的忧虑。至此诗人引颈遥望长安，归心不已，步履迟迟的徘徊背影已如在眼前；似可听见深深的长吁短叹。\n\n　　诗的情感哀切深至，颔联意绪剀切，首尾感叹往复。唯颈联写景，淡密而不显焕，情致悱恻。全诗结体深沉，有“绪缠绵而不断，味涵咏而愈旨”（卢文昭语）的风致。就其风骨而言，则属大历家数，呈露顿衰之象。', poem_tags = '唐诗三百首,春节,思乡' WHERE poem_title = '新年作' AND poem_author = '刘长卿';
UPDATE edu_poem SET poem_translation = '年轻时就立志北伐中原， 哪想到竟然是如此艰难。我常常北望那中原大地， 热血沸腾啊怨气如山啊。\n记得在瓜州渡痛击金兵， 雪夜里飞奔着楼船战舰。秋风中跨战马纵横驰骋， 收复了大散关捷报频传。\n想当初我自比万里长城， 立壮志为祖国扫除边患。到如今垂垂老鬓发如霜， 盼北伐盼恢复都成空谈。\n不由人缅怀那诸葛孔明， 出师表真可谓名不虚传，有谁像诸葛亮鞠躬尽瘁， 率三军复汉室北定中原！', poem_notes = '书愤：书写自己的愤恨之情。书，写。\n早岁：早年，年轻时。那：即“哪”。世事艰：指抗金大业屡遭破坏。\n“中原”句：北望中原，收复故土的豪迈气概坚定如山。中原北望，“北望中原”的倒文。气，气概。\n楼船，指采石之战中宋军使用的车船，又名明轮船、车轮柯。车船内部安装有以踩踏驱动的机械连接船外的明轮，依靠一组人的脚力踩踏前行。车船在宋代盛极一时。因这种战船高大有楼，故把它称之为楼船。瓜洲：在今江苏邢江南长江边，与镇江隔江相对，是当时的江防要地。\n铁马：披着铁甲的战马。大散关：在今陕西宝鸡西南，是当时宋金的西部边界。\n塞上长城，比喻能守边的将领。《南史·檀道济传》载，宋文帝要杀大将檀道济，檀临刑前怒叱道：“乃坏汝万里长城！”\n衰鬓：年老而疏白的头发。斑：指黑发中夹杂了白发。\n出师一表：蜀汉后主建兴五年（227）三月，诸葛亮出兵伐魏前曾写了一篇《出师表》，表达了自己“奖率三军，北定中原”，“兴复汉室，还于旧都”的坚强决心。名世：名传后世。\n堪：能够。伯仲：原指兄弟间的次第。这里比喻人物不相上下，难分优劣高低。', poem_appreciation = '本诗系宋孝宗淳熙十三年（1186）春陆游居家乡山阴时所作。陆游时年六十有一，这分明是时不待我的年龄。\n\n　　前四句概括了自己青壮年时期的豪情壮志和战斗生活情景，其中颔联撷取了两个最能体现“气如山”的画面来表现，不用一个动词，却境界全出，饱含着浓厚的边地气氛和高昂的战斗情绪。又妙在对仗工整，顿挫铿锵，且一气贯注，组接无痕，以其雄放豪迈的气势成为千古传诵的名联。\n\n　　“早岁那知世事艰，中原北望气如山。”当英雄无用武之地时，他会回到铁马金戈的记忆里去的。想当年，诗人北望中原，收复失地的壮心豪气，有如山涌，何等气魄！诗人何曾想过杀敌报国之路竟会如此艰难？以为我本无私，倾力报国，那么国必成全于我，孰料竟有奸人作梗、破坏以至于屡遭罢黜？诗人开篇一自问，问出多少郁愤？\n\n　　后四句抒发壮心未遂、时光虚掷、功业难成的悲愤之气，但悲愤而不感伤颓废。尾联以诸葛亮自比，不满和悲叹之情交织在—起，展现了诗人复杂的内心世界。\n\n　　再看尾联。亦用典明志。诸葛坚持北伐，虽“出师一表真名世”，但终归名满天宇，“千载谁堪伯仲间”。追慕先贤的业绩，表明自己的爱国热情至老不移，渴望效仿诸葛亮，施展抱负。\n\n　　回看整首诗歌，可见句句是愤，字字是愤。以愤而为诗，诗便尽是愤。', poem_tags = '古诗三百首,爱国,忆旧' WHERE poem_title = '书愤五首·其一' AND poem_author = '陆游';
UPDATE edu_poem SET poem_tags = '寒食节,思乡' WHERE poem_title = '寒食野望吟' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '夜卧枕被如冰，不由让我很惊讶，又看见窗户被白雪泛出的光照亮。\n夜深的时候就知道雪下得很大，是因为不时地能听到雪把竹枝压折的声音。', poem_notes = '讶：惊讶。 衾（qīn）枕：被子和枕头。\n折竹声：指大雪压折竹子的声响。', poem_tags = '冬天,写雪' WHERE poem_title = '夜雪' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '来到树林里，看到画眉鸟在开满红红紫紫山花的枝头自由自在地飞翔，听到它们在高高低低的树梢上随着自己的心意尽情愉快地唱歌，不由得感慨到 ：如果把它们锁起来，即使是锁在金笼里，它们也不会唱出这样美妙的歌声了。因为自由是生活愉快的先决条件。鸟是这样，人不也是这样吗？\n\n译文二\n千百声的鸟的鸣叫声，随着自己的心意任意回荡着，\n(就在那)山花万紫千红绽放在高低有致的林木里。\n这才明白：（以前)听到那锁在金笼内的画眉叫声，\n远比不上悠游林中时的自在啼唱。', poem_notes = '啭：鸟婉转地啼叫\n随意：随着自己（鸟）的心意。\n树高低：树林中的高处或低处。\n金笼：贵重的鸟笼，喻指不愁吃喝、生活条件优越的居所。\n百啭千声：形容画眉叫声婉转，富于变化。\n始知：现在才知道。\n不及：远远比不上。', poem_appreciation = '这首篇借咏画眉以抒发自己的性灵，诗题一作《郡斋闻百舌》。画眉、百舌，都是声音婉转的鸣禽，诗人在《啼鸟》诗中也写过“南窗睡多春正美，百舌未晓催天明。黄鹂颜色已可爱，舌端哑咤如娇婴。”可见他对“林间自在啼”的欣赏，这儿以“锁向金笼”与之对比，更见出诗人挣脱羁绊、向往自由的心理。诗人本在朝为官，后因党争牵连，贬为知州知县，此两句大概有所寄托。\n\n　　欧阳修的《画眉鸟》，前两句写景：画眉鸟千啼百啭，一高一低舞姿翩翩，使得嫣红姹紫的山花更是赏心悦目。后两句抒情：看到那些关在笼里的鸟儿，真羡慕飞啭在林间的画眉鸟，自由自在，无拘无束。这里也要了解的是，作者欧阳修此时因在朝中受到排挤而被贬到滁州，写作此诗的心情也就可知了。\n\n　　写画眉实是写自己，画眉鸟的百啭千声的表达的是归隐山林、不受羁绊的心曲。看山花烂漫、叶木葱笼，管什么金带紫袍；无限的欣喜快慰如山间清流泻出，洗尽俗尘，只余下悦耳的音韵流转。运用了对比手法：前两句（写自由自在，任意翔鸣的画眉）与后两句（写陷入囚笼，失去了自由的画眉）构成对比。\n\n　　这首诗情景结合，寓意深远，反映了作者对自由生活的追求和向往。', poem_tags = '古诗三百首,写鸟,寓人,早教古诗100首' WHERE poem_title = '画眉鸟' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '高山上挺拔耸立的松树，顶着山谷间瑟瑟呼啸的狂风。\n风声是如此的猛烈，而松枝是如此的刚劲！\n任它满天冰霜惨惨凄凄，松树的腰杆终年端端正正。\n难道是松树没有遭遇凝重的寒意？不，是松柏天生有着耐寒的本性！', poem_notes = '亭亭：高耸的样子\n瑟瑟：形容寒风的声音。　\n一何：多么。\n惨凄：凛冽、严酷。　\n罹（ lí ）凝寒：遭受严寒。 罹，遭受。\n“岂不罹凝寒？松柏有本性”二句是说，难道松柏没有遭到严寒的侵凌吗？（但是它依然青翠如故，)这是它的本性决定的。\n从弟：堂弟。', poem_appreciation = '刘桢的诗刚劲挺拔，卓荦不凡。曹丕称“其五言诗之善者，妙绝时人”。《赠从弟》共三首，为其代表作，尤以第二首著称于世。\n\n　　《赠从弟》（其二）貌似咏物，实为言志，借青松之刚劲，明志向之坚贞。全诗由表及里，由此及彼，寓意高远，气壮脱俗。\n\n　　起首二句，即以松的高洁之态动人情思，风的肃杀之声逼人警觉。用“亭亭”标示松的傲岸姿态，用“瑟瑟”摹拟刺骨的风声。绘影绘声，简洁生动。又以“谷中”映衬“山上”，更突出了位居全诗中心的青松的傲骨。\n\n　　起首二句以客观描写为主，三四两句则加强了抒情的氛围。而且在似乎不相关的松和风之间冲突顿起，令听者心惊，观者颜开。两个“一何”强调诗人感受的强烈，一“盛”一“劲”表现冲突的激烈和诗人的感情倾向。第三句诗顺接第二句，第四句呼应首句，章法绵密，展开有序。\n\n　　五六两句，由风势猛烈而发展到酷寒的冰霜，由松枝的刚劲而拓宽为一年四季常端正，越发显出环境的严酷和青松岁寒不凋的特性。诗的意境格外高远，格调更显得悲壮崇高。松树和环境的对比也更分明，而松树品性的价值也更加突现出来。\n\n　　最后两句变换句式，以有力的一问一答作结。诗人由外而内，由表层到深层，把读者眼光从“亭亭”“端正”的外貌透视到松树内在的本性，以此表明松树之所以不畏狂风严寒，是因为有坚贞不屈的高风亮节。\n\n　　全诗以松树为中心，写得集中紧凑。反复咏歌，却不平板单调。用词朴素无华，风骨雄健，气势有力。不重在工笔细描，而以层层深入事物的内核见长。\n\n　　这 首诗名为“赠从弟”，但无一语道及兄弟情谊。我们读来却颇觉情深谊长，而且能同诗人心心相印。这是因为诗人运用了象征手法，用松树象征自己的志趣、情操和 希望。自然之物原本自生自灭，与人无关。但一旦诗人用多情的目光注入山水树木、风霜雷电，与自然界中某些同人类相通的特征一撞击，便会爆发出动人的火花。 这种象征手法的运用，刘桢之前有屈原的桔颂，刘桢之后，则更是屡见不鲜，且形成中国古典诗歌的传统特征之一。\n\n　　刘桢如果直接抒写内心情感，很易直露，便借松树的高洁来暗示情怀，以此自勉，也借以勉励从弟。全诗关于兄弟情谊虽“不着一字”，但味外之旨却更耐人品尝。', poem_tags = '古诗三百首,初中古诗,咏物,松树,言志' WHERE poem_title = '赠从弟' AND poem_author = '刘桢';
UPDATE edu_poem SET poem_translation = '蝉垂下像帽缨一样的触角吸吮着清澈甘甜的露水，声音从挺拔疏朗的梧桐树枝间传出。\n蝉声远传是因为蝉居在高树上，而不是依靠秋风。', poem_notes = '垂緌（ruí）：古人结在颔下的帽缨下垂部分,蝉的头部伸出的触须,形状与其有些相似。\n清露：纯净的露水。古人以为蝉是喝露水生活的，其实是刺吸植物的汁液。\n流响：指连续不断的蝉鸣声。\n疏：开阔、稀疏。\n藉：凭借。', poem_appreciation = '这是初唐名臣虞世南的一首咏物诗，咏物中尤多寄托，具有浓郁的象征性。句句写的是蝉的形体、习性和声音，而句句又暗示着诗人高洁清远的品行志趣，物我互释，咏物的深层意义是咏人。关键要把握住蝉的某些别有意味的具体特征，从中找出艺术上的契合点。垂緌，是古代官帽打结下垂的带子，也指蝉的下巴上与帽带相似的细嘴。蝉用细嘴吮吸清露，由于语义双关，暗示着冠缨高官要戒绝腐败，追求清廉。蝉居住在挺拔疏朗的梧桐上，与那些在腐草烂泥中打滚的虫类自然不同，因此它的声音能够流丽响亮。诗的最后评点道，这完全是由于蝉能够“居高声自远”，而不是由于凭借秋风一类外力所致。这些诗句的弦外之音，它们所隐喻的深层意义无非是说，做官做人应该立身高处，德行高洁，才能说话响亮，声名远播。这种居高致远完全来自人格美的力量，绝非依凭见风使舵，或者什么权势、关节和捧场所能得到的。实际上，咏蝉包含着虞世南的夫子自道。他作为唐贞观年间画像悬挂在凌烟阁的二十四勋臣之一，名声在于博学多能，高洁耿介，与唐太宗谈论历代帝王为政得失，能够直言善谏，为贞观之治作出独特贡献。为此，唐太宗称他有“五绝”（德行、忠直、博学、文辞、书翰），并赞叹：“群臣皆如虞世南，天下何忧不理！”从他不是以鲲鹏鹰虎，而是以一只不甚起眼的蝉来自况，也可见其老成谨慎，以及有自知之明。\n\n　　这首托物寓意的小诗，是唐人咏蝉诗中时代最早的一首，很为后世人称道。 首句“垂緌饮清露”表面上是写蝉的形状与食性，实际上是运用比兴手法，暗示自己的显要身份和清廉的品质。蝉的头部有两根触须，形状似官员系在颈下的帽带；古人认为蝉栖身高树，只喝清洁的露水，因而用“饮清露”象征人的品格高洁。其实蝉是靠吸食植物的液汁生活的，哪里可能只喝露水？ 次句“流响出疏桐”写蝉鸣声。为什么说连续不断的蝉鸣声是从枝叶稀疏的梧桐中传出来的呢？这是因为梧桐在古人的心目中是一种高贵而灵异的树，传说鸾凤一类的鸟非梧桐不栖，“王者任用贤良，则梧桐生于东厢”。诗人以蝉自比，则其鸣声也就不同凡响。“桐”前着一“疏”，既让人感到“流响”的易于流传，又与末句“秋风”相应。 “居高声自远，非是藉秋风”，这是全篇比兴寄托的点睛之笔，是从上面两句引发出来的议论。意思是“蝉儿栖身高处，声音自然会传得很远。这并不是借助秋风的飞传”，沈德潜说：“命意自高，咏蝉者每咏其声，此独尊其品格。” 这一托物寓意的名句，既是写景，也是抒怀，是唐诗中最早咏蝉的，很为后世称道。虞世南原是陈隋旧臣，入唐后以文才和德行受到唐太宗的器重，他生性耿直孤傲，不合于世，显示出一种内向、孤僻、深沉的性格特征，虞世南借蝉咏怀，表明自己立身高洁，不需任何凭藉，自会扬名。情景交融，显得十分和谐自然。这两句用的是比喻，蝉声远传不是借藉于秋风的传送，这里所突出强调的是诗人的人格美，表达了诗人对自己内在品格的热情赞美，表现了一种雍容不迫的风度、气韵。读者可从中想像到人格化了的蝉儿那种清华隽朗的高标逸韵，可谓巧妙至极。正像曹丕在《典论o论文》中所言“不做良臣之辞，不托飞驰之势，而名声自传达于后”。“居高声自远。非是藉秋风”展示了一个清狂自负、踌躇满志的士大夫形象。 施朴华《岘佣说诗》曰：“《三百篇》比兴为多，唐人犹得其意。同一咏蝉，虞世南‘居高声自远，非是籍秋风’，是清华人语；骆宾王‘露重飞难进，风多响易沉’，是患难人语；李商隐‘本以高难饱，徒劳恨费声’，是牢骚人语，比兴不同如此。”同是唐人，又都是托咏蝉以寄意，由于作者的地位、遭际、气质彼此不同，虽同样工于比兴寄托，却呈现出殊异的面貌，形成富有个性特征的艺术形象。', poem_tags = '咏物,寓理' WHERE poem_title = '蝉' AND poem_author = '虞世南';
UPDATE edu_poem SET poem_translation = '我劝你不要顾惜华贵的金缕衣，我劝你一定要珍惜青春少年时。\n花开宜折的时候就要抓紧去折，不要等到花谢时只折了个空枝。\n\n韵译\n不要爱惜荣华富贵，而应爱惜少年时光。\n就像那盛开的鲜花，要及时采摘。如果采摘不及时，等到春残花落之时，就只能折取花枝了。', poem_notes = '⑴金缕衣：缀有金线的衣服，比喻荣华富贵。\n⑵须惜：珍惜。\n⑶堪：可以，能够。\n⑷直须：尽管。直：直接，爽快。\n⑸莫待：不要等到。', poem_appreciation = '此诗含意很单纯，可以用“莫负好时光”一言以蔽之。这原是一种人所共有的思想感情。可是，它使得读者感到其情感虽单纯却强烈，能长久在人心中缭绕，有一种不可思议的魅力。它每个诗句似乎都在重复那单一的意思“莫负好时光！”而每句又都寓有微妙变化，重复而不单调，回环而有缓急，形成优美的旋律，反复咏叹强调爱惜时光，莫要错过青春年华。从字面看，是对青春和爱情的大胆歌唱，是热情奔放的坦诚流露。然而字面背后，仍然是“爱惜时光”的主旨。因此，若作“行乐及时”的宗旨看似乎低了，作“珍惜时光”看，便摇曳多姿，耐人寻味。\n\n　　一、二句式相同，都以“劝君”开始，“惜”字也两次出现，这是二句重复的因素。但第一句说的是“劝君莫惜”，二句说的是“劝君须惜”，“莫”与“须”意正相反，又形成重复中的变化。这两句诗意又是贯通的。“金缕衣”是华丽贵重之物，却“劝君莫惜”，可见还有远比它更为珍贵的东西，这就是“劝君须惜”的“少年时”了。至于其原因，诗句未直说，那本是不言而喻的：“一寸光阴一寸金，寸金难买寸光阴”，贵如黄金也有再得的时候，“千金散尽还复来”；然而青春对任何人也只有一次，它一旦逝去是永不复返的。可是，世人多惑于此，爱金如命、虚掷光阴的真不少呢。一再“劝君”，用对白语气，致意殷勤，有很浓的歌味，和娓娓动人的风韵。两句一否定，一肯定，否定前者乃是为肯定后者，似分实合，构成诗中第一次反复和咏叹，其旋律节奏是纡回徐缓的。\n\n　　三、四句则构成第二次反复和咏叹，单就诗意看，与一、二句差不多，还是“莫负好时光”那个意思。这样，除了句与句之间的反复，又有上联与下联之间的较大的回旋反复。但两联表现手法就不一样，上联直抒胸臆，是赋法；下联却用了譬喻方式，是比义。于是重复中仍有变化。三、四没有一、二那样整饬的句式，但意义上彼此是对称得铢两悉称的。上句说“有花”应怎样，下句说“无花”会怎样；上句说“须”怎样，下句说“莫”怎样，也有肯定否定的对立。二句意义又紧紧关联：“有花堪折直须折”是从正面说“行乐须及春”意，“莫待无花空折枝”是从反面说“行乐须及春”意，似分实合，反复倾诉同一情愫，是“劝君”的继续，但语调节奏由徐缓变得峻急、热烈。“堪折——直须折”这句中节奏短促，力度极强，“直须”比前面的“须”更加强调。这是对青春与欢爱的放胆歌唱。这里的热情奔放，不但真率、大胆，而且形象、优美。“花”字两见，“折”字竟三见；“须——莫”云云与上联“莫——须”云云，又自然构成回文式的复叠美。这一系列天然工妙的字与字的反复、句与句的反复、联与联的反复，使诗句琅琅上口，语语可歌。除了形式美，其情绪由徐缓的回环到热烈的动荡，又构成此诗内在的韵律，诵读起来就更使人感到回肠荡气了。\n\n　　有一种歌词，简单到一句两话，经高明作曲家配上优美的旋律，反复重唱，尚可获得动人的风韵；而《金缕衣》，起诗意单纯而不单调，有往复，有变化，一中有多，多中有一，作为独立的诗篇一摇曳多姿，更何况它在唐代是配乐演唱，因此而被广泛流唱了。\n\n　　此诗另一显著特色在于修辞上的别致新颖。一般情况下 ，旧诗中比兴手法往往合一，用在诗的发端； 而绝句往往先景语后情语。此诗一反惯例，它赋中有兴，先赋后比 ，先情语后景语，殊属别致。“劝君莫惜金缕衣”一句是赋 ，而以物起情，又有兴的作用。 诗的下联是比喻，也是对上句“须惜少年时”诗意的继续生发 。不用“人生几何 ”式直截的感慨，用花来比少年好时光，用折花来比莫负大好青春，既形象又优美，创造出一个意象世界。\n\n　　这就是艺术的表现，形象思维。错过青春便会导致无穷悔恨，这种意思，此诗本来可以用但却没有用“老大徒伤悲”一类成语来表达，而紧紧朝着折花的比喻向前走，继而造出“无花空折枝”这样闻所未闻的奇语。没有沾一个悔字恨字，而“空折枝”三字却耐人寻味，富有艺术感染力。', poem_tags = '唐诗三百首,励志,惜时,早教古诗100首' WHERE poem_title = '金缕衣' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '眉妆漫染，叠盖了部分额黄，鬓边发丝飘过。洁白的香腮似雪，懒得起来，画一画蛾眉，整一整衣裳，梳洗打扮，慢吞吞，意迟迟。\n照一照新插的花朵，对了前镜，又对后镜，红花与容颜，交相辉映，刚穿上的绫罗裙襦，绣着一双双的金鹧鸪。', poem_notes = '小山：眉妆的名目，指小山眉，弯弯的眉毛。另外一种理解为：小山是指屏风上的图案，由于屏风是折叠的，所以说小山重叠。金：指唐时妇女眉际妆饰之“额黄”。明灭：隐现明灭的样子。金明灭：形容阳光照在屏风上金光闪闪的样子。一说描写女子头上插戴的饰金小梳子重叠闪烁的情形，或指女子额上涂成梅花图案的额黄有所脱落而或明或暗。\n鬓云：像云朵似的鬓发。形容发髻蓬松如云。度：覆盖，过掩，形容鬓角延伸向脸颊，逐渐轻淡，像云影轻度。欲度：将掩未掩的样子。香腮雪：香雪腮，雪白的面颊。\n蛾眉：女子的眉毛细长弯曲像蚕蛾的触须，故称蛾眉。一说指元和以后叫浓阔的时新眉式“蛾翅眉”。\n弄妆：梳妆打扮， 修饰仪容。\n罗襦：丝绸短袄。\n鹧鸪：贴绣上去的鹧鸪图，这说的是当时的衣饰，就是用金线绣好花样，再绣贴在衣服上，谓之“贴金”。', poem_appreciation = '这首《菩萨蛮》，为了适应宫廷歌伎的声口，也为了点缀皇宫里的生活情趣，把妇女的容貌写得很美丽，服饰写得很华贵，体态也写得十分娇柔，仿佛描绘了一幅唐代仕女图。\n\n　　词学专家周汝昌先生认为：此篇通体一气。精整无只字杂言，所写只是一件事，若为之拟一题目增入，便是“梳妆”二字。领会此二字，一切迎刃而解。而妆者，以眉为始；梳者，以鬓为主；故首句即写眉，次句即写鬓。\n\n　　小山，眉妆之名目，晚唐五代，此样盛行，见于《海录碎事》，为“十眉”之一式。大约“眉山”一词，亦因此起。眉曰小山，也时时见于当时词中，如五代蜀秘书监毛熙震《女冠子》云：“修蛾慢脸（脸，古义，专指眼部），不语檀心一点（檀心，眉间额妆，双关语），小山妆。”正指小山眉而言。又如同时孙光宪《酒泉子》云：“玉纤（手也）淡拂眉山小，镜中嗔共照。翠连娟，红缥缈，早妆时。”亦正写晨妆对镜画眉之情景。可知小山本谓淡扫蛾眉，实与韦庄《荷叶杯》所谓“一双愁黛远山眉”同义。\n\n　　旧解多以小山为“屏”，其实未允。此由（1）不知全词脉络，误以首句与下无内在联系；（2）不知“小山”为眉样专词，误以为此乃“小山屏”之简化。又不知“叠”乃眉蹙之义，遂将“重叠”解为重重叠叠。然“小山屏”者，译为今言，谓“小小的山样屏风”也，故“山屏”即为“屏山”，为连词，而“小”为状词；“小”可省减而“山屏”不可割裂而止用“山”字。既以“小山”为屏，又以“金明灭”为日光照映不定之状，不但“屏”“日”全无着落，章法脉络亦不可寻矣。\n\n　　重，在诗词韵语中，往往读平声而义为去声，或者反是，全以音律上的得宜为定。此处声平而义去，方为识音。叠，相当于蹙眉之蹙字义，唐诗有“双蛾叠柳”之语，正此之谓。金，指唐时妇女眉际妆饰之“额黄”，故诗又有“八字宫眉捧额黄”之句，其良证也。\n\n　　已将眉喻为山，再将鬓喻为云，再将腮喻为雪，是谓文心脉络。盖晨间闺中待起，其眉蹙锁，而鬓已散乱，其披拂之发缕，掩于面际，故上则微掩眉端额黄，在隐现明灭之间；下则欲度腮香，——度实亦微掩之意。如此，山也，金也，云也，雪也，构为一幅春晓图，十分别致。\n\n　　上来两句所写，待起未起之情景也。故第三句紧接懒起，起字一逗——虽曰懒起，并非不起，是娇懒迟迟而起也。闺中晓起，必先梳妆，故“画蛾眉”三字一点题——正承“小山”而来。“弄妆”再点题，而“梳洗”二字又正承鬓之腮雪而来。其双管并下，脉络最清。然而中间又着一“迟”字，远与“懒”相为呼应，近与“弄”字互为注解。“弄”字最奇，因而是一篇眼目。一“迟”字，多少层次，多少时光，多少心绪，多少神情，俱被此一字包尽矣。\n\n　　梳妆虽迟，终究须有完毕之日，故过片重开，即写梳妆已罢，最后以两镜前后对映而审看梳妆是否合乎标准。其前镜，妆台奁内之座镜也；其后镜，手中所持之柄镜也——俗呼“把儿镜”。所以照者，为看两鬓簪花是否妥恰，而两镜之交，“套景”重叠，花光之与人面，亦交互重叠，至于无数层次！以十个字写此难状之妙景，尽得神理，实为奇绝之笔。\n\n　　词笔至此，写梳妆题目已尽其能事了，后面又忽有两句，又不知为何而设？新贴，新鲜之“花样子”也，剪纸为之，贴于绸帛之上，以为刺绣之“蓝本”者也。盖言梳妆既妥，遂开始一日之女红：刺绣罗襦，而此新样花贴，偏偏是一双一双的的鹧鸪图纹。闺中之人，见此图纹，不禁有所感触。此处之所感所触，乃与开头之山眉深蹙，梦起迟妆者相应。由此一例足见飞卿词极工于组织联络，回互呼应之妙。\n\n　　此词对后世颇有影响。电视连续剧《后宫甄嬛传》剧终曲曾采用此词原文为歌词，由刘欢作曲，姚贝娜演唱。', poem_tags = '宋词三百首,婉约,女子,闺怨' WHERE poem_title = '菩萨蛮·小山重叠金明灭' AND poem_author = '温庭筠';
UPDATE edu_poem SET poem_translation = '秦国的将军王翦攻破赵国，俘虏赵王，大部分占领了赵国的国土，进军向北侵占土地，到达燕国南部的边界。\n　　燕国的太子丹很害怕，就请求荆轲说：“秦军马上就要渡过易水，那么虽然我想长久地侍奉您，又怎么能够做得到呢？”荆轲说：“即使太子不说，我也要请求行动。假如空手而去，没有什么凭信之物，那就无法接近秦王。现在的樊将军，秦王用一千斤金和一万户人口的封地作悬赏来购取他的头颅。果真能够得到樊将军的首级及燕国督亢一带的地图献给秦王，秦王一定高兴地召见我，我就有办法来报答太子了。”太子说：“樊将军因为走投无路，处境困窘而来归附我，我不忍心由于自己个人的私仇而伤害长者的心意，希望您另外考虑对策吧!”\n　　荆轲知道太子不忍心，于是私下里会见樊於期，说：“秦国对待将军，可以说是刻毒透顶了。父亲、母亲和同族的人都被杀死或没收入官为奴。现在听说用一千斤金和一万户人口的封地作悬赏来购买将军的首级，您将怎么办？”樊将军仰天长叹，泪流满面地说：“我每当想起这一点，常常恨入骨髓，只是想不出什么办法罢了。”荆轲说：“现在有一个建议，可以用来解除燕国的忧患，报将军的深仇大恨，怎么样？”樊於期于是上前问道：“怎么办？”荆轲说：“希望得到樊将军的首级来献给秦国，秦王一定高兴而又友好地接见我。我左手抓住他的衣袖，右手（用匕首）刺他的胸膛。这样，将军的仇报了，燕国被欺侮的耻辱也除掉了。将军是否有这个心意呢？”樊於期脱下一只衣袖露出一只胳膊，左手握住右腕，走近一步说：“这是我日日夜夜咬牙切齿、捶胸痛恨的事，今天才得到您的指教!”于是自杀。\n　　太子听说了这件事，赶着马车跑去，伏在樊於期的尸体上大哭，非常悲伤。事已至此，没有办法挽回了，于是就收拾安放樊於期的首级，用匣子装好它。\n　　于是太子预先寻求世上锋利的匕首，得到赵国徐夫人的匕首，用一百金把它买到，叫工匠在淬火时把毒药浸到匕首上。用人来做实验，血沾湿衣褛，没有不立即死亡的。于是整理行装，派遣荆轲上路。\n　　燕国有个勇士秦武阳，十二岁的时候就杀过人，人们不敢同他正眼相看，于是叫秦武阳做助手。\n　　荆轲等待着一个人，想同他一起去。那个人住得很远，没有来，因而停下等候他。\n　　过了一阵还没动身，太子嫌荆轲走晚了，怀疑他有改变初衷和后悔的念头，就又请求他说：“太阳已经完全落下去了，您难道没有动身的意思吗？请允许我先遣发秦武阳!”荆轲发怒，呵斥太子说：“今天去了而不能好好回来复命的，那是没有用的小子!现在光拿着一把匕首进入不可意料的强暴的秦国，我之所以停留下来，是因为等待我的客人好同他一起走。现在太子嫌我走晚了，请允许我告别吧!”于是出发了。\n　　太子和他的宾客中知道这件事的人，都穿着白衣，戴着白帽给他送行。到易水上，祭过路神，就要上路。高渐离敲着筑，荆轲和着节拍唱歌，发出变徵的声音，众宾客都流着眼泪小声地哭。荆轲又上前作歌唱道：“风声萧萧悲鸣啊易水彻骨寒冷，壮士这一离去啊就永远不再回还!”又发出悲壮激昂的羽声。众宾客都睁大了眼睛，头发都向上竖起顶住了帽子。于是荆轲就上车离去，始终不曾回头看一眼。\n　　到达秦国后，拿着价值千金的礼物，优厚地赠送给秦王的宠臣中庶子蒙嘉。\n　　蒙嘉替他事先向秦王进言，说：“燕王确实非常惧怕大王的威势，不敢出兵来抗拒，愿意全国上下都做秦国的臣民，排在诸侯的行列里(意为：燕国愿意同别的诸侯一起尊秦王为天子)像秦国的郡县那样贡纳赋税，俾能守住祖先的宗庙。他们诚惶诚恐，不敢自己来陈述，恭谨地砍下樊於期的头颅和献上燕国督亢一带的地图，用盒子封好，燕王在朝廷上行跪拜大礼送出来，派使者来禀告大王。一切听凭大王吩咐。”\n　　秦王听了蒙嘉的话，非常高兴。于是穿了上朝的礼服，安排下隆重的九宾大礼仪式，在咸阳宫接见燕国的使者。\n　　荆轲捧着装了樊於期头颅的盒子，秦武阳捧着地图匣子，按次序进宫，到达殿前的台阶下，秦武阳脸色都变了，十分害怕，秦国的群臣对此感到奇怪。荆轲回过头来对秦武阳笑了笑，上前替他向秦王谢罪说：“北方蛮夷地区的粗鄙人，没有拜见过天子，所以害怕，希望大王稍微原谅他些，让他在大王的面前完成他的使命。”秦王对荆轲说：“起来，取来武阳所拿的地图!”\n　　荆轲拿了地图捧送给秦王，打开地图，地图全部打开，匕首就露了出来。于是荆轲左手抓住秦王的衣袖，右手拿着匕首刺秦王。还没有刺到秦王的身上，秦王非常惊骇，自己伸直身子站起来，挣断了袖子。秦王拔剑，剑太长，就握住剑鞘。当时秦王心里又怕又急，剑插得很紧，所以不能立即拔出来。\n　　荆轲追逐秦王，秦王绕着柱子跑。秦国的君臣都惊呆了，事情突然发生，意料不到，大家都失去了常态。并且按照秦国的法律，臣子们侍立在殿上的，不能带一点兵器；那些宫廷侍卫握着武器，都排列在宫殿的台阶下面，没有君王的命令不能上殿。当危急的时候，来不及召唤阶下的侍卫，所以荆轲追逐秦王，大家仓猝间惊惶失措，没有武器用来击杀荆轲，仅仅用空手一起同荆轲搏斗。\n　　这时，秦王的随从医官夏无且(jū)用他手里捧着的药袋投击荆轲。秦王还正在绕着柱子跑，仓猝间惊惶失措，不知道怎么办。侍臣们就说：“大王背着剑!大王背着剑！”秦王于是拔出剑用来攻击荆轲，砍断了荆轲的左大腿。荆轲倒下了，就举起他的匕首投击秦王，没有击中，击中了柱子。秦王又砍击荆轲，荆轲被砍伤了八处。\n　　荆轲自己知道事情不能成功了，靠着柱子笑着，像撮箕一样地张开两腿坐在地上，骂道：“事情之所以没有成功，是想活生生地劫持你，一定要得到约契来回报燕太子啊!”\n　　秦王的侍臣上前，斩杀荆轲。事后，秦王还头昏眼花了好长一段时间。', poem_notes = '秦将王翦破赵，虏赵王：这是公元前年的事。荆轲刺秦王是在第二年。\n收：占领。北：向北（名词用作状语）。略：通掠，掠夺，夺取。\n荆卿：燕人称荆轲为荆卿。卿，古代对人的敬称。\n旦暮渡易水：早晚就要渡过易水了。旦暮，早晚，极言时间短暂。易水，在河北省西部，发源于易县，在定兴县汇入南拒马河。\n长侍：长久侍奉。\n微太子言，臣愿得谒之：即使太子不说，我也要请求行动。微，假如没有。谒，拜访。\n今行而无信，则秦未可亲也：当下去却没有什么凭信之物，就无法接近秦王。信：凭信之物。亲：亲近，接近。\n樊将军：即下文的樊於期，秦国将领，因得罪秦王，逃到燕国。\n秦王购之金千斤，邑万家：秦王用一千斤金（当时以铜为金）和一万户人口的封地做赏格，悬赏他的头。购，重金征求。邑，封地。\n督亢：今河北省易县，霸县一带，是燕国土地肥沃的地方。\n说：同“悦”，喜欢，高兴。\n更虑之：再想想别的办法。更，改变。\n遇：对待。深，这里是刻毒的意思。\n戮没：杀戮和没收。重要的人杀掉，其他人等收为奴婢。\n顾计不知所出耳：只是想不出什么办法罢了。顾，不过，只是，表轻微转折。\n善：好好地。\n把：握，抓住。\n揕：刺。\n见陵之耻：被欺侮的耻辱。见，被。陵，侵犯，欺侮。\n偏袒扼腕而进：脱下一只衣袖，握住手腕，走近一步。这里形容激动愤怒的样子。偏袒，袒露一只臂膀。扼：握住。\n拊心：捶胸，这里形容非常心痛。\n盛：装。\n函封之：用匣子封装起来。函，匣子。\n徐夫人：姓徐，名夫人。一个收藏匕首的人。\n工：工匠。以药淬之：在淬火时把毒药浸到匕首上。淬，把烧红的铁器浸入水或者其他液体，急速冷却，使之硬化。\n濡缕：沾湿衣缕。濡，浸湿，沾湿。\n忤视：正眼看。忤，逆。意思是迎着目光看。\n为副：做助手。\n荆轲有所待，欲与俱：荆轲等待一个人，想同他一起去。\n迟之：嫌荆轲动身迟缓。\n往而不反者，竖子也：去了而不能好好回来复命的，那是没用的人。反，通“返”。竖子，对人的蔑称。\n不测：难以预料，表示凶险。\n请辞决矣：我就辞别了。请，请允许我，表示客气。辞决，辞别，告别。\n既祖，取道：祭过路神，就要上路。祖，临行祭路神，引申为践行和送别。\n高渐离：荆轲的朋友。\n为变徵之声：发出变徵的声音。古时音乐分为宫，商，角，徵，羽，变徵，变宫七音，变徵是徵音的变调，声调悲凉。\n慷慨羽声：声调激愤的羽声。\n瞋目：形容发怒时瞪大眼睛的样子。\n终已不顾：始终不曾回头。形容意志坚决。\n持千金之资币物：拿着价值千金的礼物。币，礼品。\n厚遗秦王宠臣中庶子蒙嘉：以厚礼赠送给秦王的宠臣中庶子蒙嘉。遗：赠送。\n诚：确实。振怖：惧怕。振，通“震”。\n比：并，列。\n给贡职如郡县：像秦国的郡县那样贡纳赋税。给，供。\n奉守先王之宗庙：守住祖先的宗庙。意思是保存祖先留下的国土。\n使使：派遣使者。\n唯大王命之：意思是一切听大王的吩咐。唯，希望的意思。\n奉：两手捧着。\n以次进：按先后顺序进来。\n陛：殿前的台阶。\n顾笑武阳：回头冲武阳笑。顾，回头看。\n少假借之：稍微原谅他些。少：通“稍”。假借，宽容，原谅。\n使毕使于前：让他在大王面前完成使命。\n发：打开。\n自引而起，绝袖：自己挣着站起来，袖子断了。引，指身子向上起。绝：挣断。\n操其室：握住剑鞘。室，指剑鞘。\n剑坚：剑插得紧。\n还：通“环”，绕。\n卒起不意，尽失其度：事情突然发生，没意料到，全都失去常态。卒，通“猝”，突然。\n尺兵：尺寸之兵，指各种兵器。\n郎中：宫廷的侍卫。\n提：掷击。\n负剑：负剑于背。\n废：倒下。\n引：举起。\n被八创：荆轲受了八处剑伤。被，受。创，伤。\n箕踞：坐在地上，两脚张开，形状像箕。这是一种轻慢傲视对方的姿态。\n劫：强迫，威逼（其订立盟约）。', poem_appreciation = '本文记述战国时期荆轲剌秦王这—悲壮的历史故事，反映了当时的社会政治情况，表现了荆轲重义轻生、反抗暴秦、勇于牺牲的精神。文章通过一系列情节和人物对话、行动、表情、神态等表现人物性格，塑造了侠义英雄荆轲的形象。\n\n　　秦王嬴政重用尉缭，一心想统一中原，不断向各国进攻。他拆散了燕国和赵国的联盟，使燕国丢了好几座城。燕国的太子丹原来留在秦国当人质，他见秦王嬴政决心兼并列国，又夺去了燕国的土地，就偷偷地逃回燕国。他恨透了秦国，一心要替赵国报仇。但他既不操练兵马，也不打算联络诸侯共同抗秦，却把燕国的命运寄托在刺客身上。他把家产全拿出来，找寻能刺秦王嬴政的人。\n\n　　后来，太子丹物色到了一个很有本领的勇士，名叫荆轲。公元前230年，秦国灭了韩国；过了两年，秦国大将王翦（音jiǎn）占领了赵国都城邯郸，一直向北进军，逼近了燕国。燕太子丹十分焦急，就去找荆轲。要他去刺杀秦王。荆轲说：“行是行，但要挨近秦王身边，必定得先叫他相信我们是向他求和去的。听说秦王早想得到燕国最肥沃的土地督亢（在河北涿县一带）。还有秦国将军樊於期，现在流亡在燕国，秦王正在悬赏通缉他。我要是能拿着樊将军的头和督亢的地图去献给秦王，他一定会接见我。这样，我就可以对付他了。”\n\n　　荆轲知道太子丹心里不忍，就私下去找樊於期（fánwūjī），跟樊於期说：“我有一个主意，能帮助燕国解除祸患，还能替将军报仇，可就是说不出口。” 樊於期连忙说：“什么主意，你快说啊！” 荆轲说：“我决定去行刺，怕的就是见不到秦王的面。现在秦王正在悬赏通缉你，如果我能够带着你的头颅去献给他，他准能接见我。” 樊於期说：“好，你就拿去吧！”说着，就拔出宝剑，抹脖子自杀了。\n\n　　太子丹事前准备了一把锋利的匕首，叫工匠用毒药煮炼过。谁只要被这把匕首刺出一滴血，就会立刻气绝身死。他把这把匕首送给荆轲，作为行刺的武器，又派了个十二岁时便杀过人的勇士秦武阳，做荆轲的副手。\n\n　　公元前227年，荆轲从燕国出发到咸阳去。太子丹和少数宾客穿上白衣白帽，到易水（在今河北易县）边送别。临行的时候，荆轲给大家唱了一首歌：“风萧萧兮易水寒， 壮士一去兮不复还。” 荆轲跳上车，头也不回地走了。\n\n　　荆轲到了咸阳。秦王政一听燕国派使者把樊於期的头颅和督亢的地图都送来了，十分高兴，就立刻穿上上朝的衣服，在咸阳宫接见荆轲。朝见的仪式开始了。荆轲捧着装了樊於期头颅的盒子，秦武阳捧着督亢的地图，一步步走上秦国朝堂的台阶。秦武阳一见秦国朝堂那副威严样子，不由得害怕得发起抖来。当然，《刺客列传》里，谋士田光对燕太子丹说的一段话：“窃观太子客无可用者：夏扶血勇之人，怒而面赤；宋意脉勇之人，怒而面青；舞阳骨勇之人，怒而面白。光所之荆柯，神勇之人，怒而色不变。”秦王政左右的侍卫一见，吆喝了一声，说：“使者怎么变了脸色？” 荆轲回头一瞧，果然见秦武阳的脸又青又白，就赔笑对秦王说：“粗野的人，从来没见过大王的威严，免不了有点害怕，请大王原谅。” 秦王政毕竟有点怀疑，对荆轲说：“叫秦武阳把地图给你，你一个人上来吧。” 荆轲从秦武阳手里接过地图，捧着木匣上去，献给秦王政。秦王政打开木匣，果然是樊於期的头颅。秦王政又叫荆轲拿地图来。荆轲把一卷地图慢慢打开，到地图全都打开时，荆轲预先卷在地图里的一把匕首就露出来了。秦王政一见，惊得跳了起来。荆轲连忙抓起匕首，左手拉住秦王政的袖子，右手把匕首向秦王政胸口直扎过去。秦王政使劲地向后一转身，把那只袖子挣断了。荆轲拿着匕首追了上来，秦王政一见跑不了，就绕着朝堂上的大铜柱子跑。荆轲紧紧地逼着。两个人像走马灯似地直转悠。旁边虽然有许多官员，但是都手无寸铁；台阶下的武士，按秦国的规矩，没有秦王命令是不准上殿的，大家都急得六神无主，也没有人召台下的武士。官员中有个伺候秦王政的医生，叫夏无且，急中生智，拿起手里的药袋对准荆轲扔了过去。荆轲用手一扬，那只药袋就飞到一边去了。这时，左右大臣提醒道：“把剑背在背上，把剑背在背上。”秦王政遂将宝剑背在背上，再往前一步，拔出宝剑，砍断了荆轲的左腿。荆轲站立不住，倒在地上。他拿匕首直向秦王政扔过去。秦王政往右边只一闪，那把匕首就从他耳边飞过去，打在铜柱子上，“嘣”的一声，直迸火星儿。秦王政见荆轲手里没有武器，又上前向荆轲砍了几剑。荆轲身上受了八处剑伤，自己知道已经失败，张开双腿坐在地上，傲慢地说：“我没有早下手，本来是想先逼你退还燕国的土地。” 这时候，侍从的武士已经一起赶上殿来，结果了荆轲的性命。', poem_tags = '高中文言文,历史,故事' WHERE poem_title = '荆轲刺秦王' AND poem_author = '刘向 编';
UPDATE edu_poem SET poem_translation = '昨夜霜降寒风骤起，梧桐叶落纷纷，我无处回避自己衰老的面容。秋风问我为何这样，我没有说话，只是用手在空中书写。人老了，有时沉醉有时沉病有时慵懒。\n早晨来到院子里，感叹时光荏苒，岁月流逝，虽不吭声，似乎有意让我伤心。如今万念俱空，把所有心事，都换作千杯酒来饮。哪管它酒花白、眼花乱、烛花红。', poem_notes = '行香子：词牌名。双调小令，六十六字，有前段八句四平韵、后段八句三平韵，前段八句五平韵、后段八句三平韵，前段八句五平韵、后段八句四平韵三种。\n霜风：刺骨寒风。\n衰容：衰老的面容。\n不语书空：不说话，用手指在空中虚画字形。此处用典表示胸中愤懑。\n慵（yōng）：困倦。\n侬：我，系江浙方言。\n付与千钟：交付酒杯，即以酒浇愁之意。钟，酒器。\n酒花：指斟酒时酒面泛起的珠花。\n眼花：这里指视线。\n烛花：指蜡烛的火焰。', poem_appreciation = '此词上片写景抒情，将秋风拟人与人对话，写词人面对萧瑟秋景，衰容剧增。悲秋是中国古典诗词中历史悠久的传统主题，“霜风”就渲染出秋日的萧瑟氛围，奠定了全词悲凉哀怨的基调；尽管词人不愿意让人看出内心的痛苦，但“衰容”遮掩不住其因政治上的挫折而带来的郁结。接着以问句的形式写出词人有冤无处诉的忧郁愤激，“醉、病、慵”高度概括出了词人生活的无聊和苦闷，显示出对社会和人事的完全绝望。\n\n　　下片叙事议论，写词人早上醒来，来得庭院，感叹时光易逝，来日无多，而当时处境，只能让他将世间万桩事付与千钟美酒，任凭酒花雪白，眼花缭乱，烛花火红。光阴似箭，强烈地表现出词作的感伤之情；酒醉、眼乱、烛红，充分写出了词人狂放不羁的醉态。\n\n　　此词上下片采用对称结构，但时序上却有“昨夜”与“今朝”的先后承递关系。词中描述了两幅衰容，一是霜风昨夜入梧桐、今朝来庭下的萧瑟冷落；一是词人病后意慵懒、酒后眼花乱的潦倒颓放。\n\n　　全词融悲自然之秋、悲生命之秋和悲心境之秋为一体，风格悲凉凄婉，情感沉郁缠绵，富有感染力。它硬语盘空，借秋日病愈，抒发了官场坎坷、世路沧桑的感叹，流露出风烛残年的悲伤。\n\n　　作者一生多舛，几遭贬谪。这时，曾经骄傲的才子，回望一生漂泊，秋风中过往的淡然、坚定、洒脱似一一看穿。这时的他褪去了才子的傲然，伤得真切。全词悲切中又有作者一如既往的旷达，也表达了作者对坎坷一生的无谓态度，在伤感中放任心性的情感，哀而不伤.', poem_tags = '秋天,感叹,生活' WHERE poem_title = '行香子·秋与' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '秦孝公占据着崤山和函谷关的险固地势，拥有雍州的土地，君臣牢固地守卫着来伺机夺取周王室的权力，（秦孝公）有统一天下的雄心。正当这时，商鞅辅佐他，对内建立法规制度，从事耕作纺织，修造防守和进攻的器械；对外实行连衡策略，使诸侯自相争斗。因此，秦人轻而易举地夺取了黄河以西的土地。\n　　秦孝公死了以后，惠文王、武王、昭襄王承继先前的基业，沿袭前代的策略，向南夺取汉中，向西攻取巴、蜀，向东割取肥沃的地区，向北占领非常重要的地区。诸侯恐慌害怕，集会结盟，商议削弱秦国。不吝惜奇珍贵重的器物和肥沃富饶的土地，用来招纳天下的优秀人才，采用合纵的策略缔结盟约，互相援助，成为一体。在这个时候，齐国有孟尝君，赵国有平原君，楚国有春申君，魏国有信陵君。这四位封君，都见识英明有智谋，心地诚而讲信义，待人宽宏厚道而爱惜人民，尊重贤才而重用士人，以合纵之约击破秦的连横之策，联合韩、魏、燕、楚、齐、赵、宋、卫、中山的部队。在这时，六国的士人，有宁越、徐尚、苏秦、杜赫等人为他们出谋划策，齐明、周最、陈轸、召滑、楼缓、翟景、苏厉、乐毅等人沟通他们的意见，吴起、孙膑、带佗、倪良、王廖、田忌、廉颇、赵奢等人统率他们的军队。他们曾经用十倍于秦的土地，上百万的军队，攻打函谷关来攻打秦国。秦人打开函谷关口迎战敌人，九国的军队有所顾虑徘徊不敢入关。秦人没有一兵一卒的耗费，然而天下的诸侯就已窘迫不堪了。因此，纵约失败了，各诸侯国争着割地来贿赂秦国。秦有剩余的力量趁他们困乏而制服他们，追赶逃走的败兵，百万败兵横尸道路，流淌的血液可以漂浮盾牌。秦国凭借这有利的形势，割取天下的土地，重新划分山河的区域。强国主动表示臣服，弱国入秦朝拜。\n　　延续到孝文王、庄襄王，统治的时间不长，秦国并没有什么大事发生。 \n　　到始皇的时候，发展六世遗留下来的功业，以武力来统治各国，将东周，西周和各诸侯国统统消灭，登上皇帝的宝座来统治天下，用严酷的刑罚来奴役天下的百姓，威风震慑四海。秦始皇向南攻取百越的土地，把它划为桂林郡和象郡，百越的君主低着头，颈上捆着绳子（愿意服从投降），把性命交给司法官吏。秦始皇于是又命令蒙恬在北方修筑长城，守卫边境，使匈奴退却七百多里；胡人不敢向下到南边来放牧，勇士不敢拉弓射箭来报仇。秦始皇接着就废除古代帝王的治世之道，焚烧诸子百家的著作，来使百姓愚蠢；毁坏高大的城墙，杀掉英雄豪杰；收缴天下的兵器，集中在咸阳，销毁兵刃和箭头，冶炼它们铸造十二个铜人，以便削弱百姓的反抗力量。然后凭借华山为城墙，依据黄河为城池，凭借着高耸的华山，往下看着深不可测的黄河，认为这是险固的地方。好的将领手执强弩，守卫着要害的地方，可靠的官员和精锐的士卒，拿着锋利的兵器，盘问过往行人。天下已经安定，始皇心里自己认为这关中的险固地势、方圆千里的坚固的城防，是子子孙孙称帝称王直至万代的基业。\n　　始皇去世之后，他的余威（依然）震慑着边远地区。可是，陈涉不过是个破瓮做窗户、草绳做户枢的贫家子弟，是氓、隶一类的人，（后来）做了被迁谪戍边的卒子；才能不如普通人，并没有孔丘、墨翟那样的贤德，也不像陶朱、猗顿那样富有。（他）跻身于戍卒的队伍中，从田野间突然奋起发难，率领着疲惫无力的士兵，指挥着几百人的队伍，掉转头来进攻秦国，砍下树木作武器，举起竹竿当旗帜，天下豪杰像云一样聚集，回声似的应和他，许多人都背着粮食，如影随形地跟着。崤山以东的英雄豪杰于是一齐起事，消灭了秦的家族。\n　　况且那天下并没有缩小削弱，雍州的地势，崤山和函谷关的险固，是保持原来的样子。陈涉的地位，没有比齐、楚、燕、赵、韩、魏、宋、卫、中山的国君更加尊贵；锄头木棍也不比钩戟长矛更锋利；那迁谪戍边的士兵也不能和九国部队抗衡；深谋远虑，行军用兵的方法，也比不上先前九国的武将谋臣。可是条件好者失败而条件差者成功，功业完全相反，为什么呢？假使拿东方诸侯国跟陈涉比一比长短大小，量一量权势力量，就更不能相提并论了。然而秦凭借着它的小小的地方，发展到兵车万乘的国势，管辖全国，使六国诸侯都来朝见，已经一百多年了；这之后把天下作为家业，用崤山、函谷关作为自己的内宫；陈涉一人起义国家就灭亡了，秦王子婴死在别人（项羽）手里，被天下人耻笑，这是为什么呢？就因为不施行仁政而使攻守的形势发生了变化啊。\n\n中篇\n　　秦统一天下，吞并诸侯，临朝称帝，供养四海，天下的士人顺服的慕风向往，为什么会像这样呢？回答是：近古以来没有统一天下的帝王已经很久了。周王室力量微弱，五霸相继死去以后，天子的命令不能通行天下，因此诸侯凭着武力相征伐，强大的侵略弱小的，人多的欺凌人少的，战事不止，军民疲惫。如今秦皇南面称帝统治了天下，这就是在上有了天子啊。这样一来，那些可怜的百姓就都希望能靠他安身活命，没有谁不诚心景仰皇上，在这个时候，应该保住威权，稳定功业，是安定，是危败，关键就在于此了。\n　　秦王怀着贪婪卑鄙之心，只想施展他个人的智慧，不信任功臣，不亲近士民，抛弃仁政王道，树立个人权威，禁除诗书古籍，实行严刑酷法，把诡诈权势放在前头，把仁德信义丢在后头，把残暴苛虐作为治理天下的前提。实行兼并，要重视诡诈和实力；安定国家，要重视顺时权变：这就是说夺天下和保天下不能用同样的方法。秦经历了战国到统一天下，它的路线没有改，他的政令没有变，这是它夺天下和保天下所用的方法没有不同。秦王孤身无辅却拥有天下，所以他的灭亡很快就来到了。假使秦王能够考虑古代的情况，顺着商、周的道路，来制定实行自己的政策，那么后代即使出现骄奢淫逸的君主，也不会有倾覆危亡的祸患。所以夏禹、商汤、周文王和周武王建立了国家，名号卓著，功业长久。\n　　当今秦二世登上王位，普天之下没有人不伸长脖子盼着看一看他的政策。受冻的人穿上粗布短袄就觉得很好，挨饿的人吃上糟糠也觉得香甜。天下苦苦哀叫的百姓，正是新皇帝执政才能的表现。这就是说劳苦人民容易接受仁政。如果二世有一般君主的德行，任用忠贞贤能的人，君臣一心，为天下的苦难而忧心，丧服期间就改正先帝的过失，割地分民，封赏功臣的后代，封国立君，对天下的贤士以礼相待，把牢狱里的犯人放出来，免去刑戮，废除没收犯罪者妻子儿女为官家奴婢之类的杂乱刑罚，让被判刑的人各自返回家乡。打开仓库，散发钱财，以赈济孤独穷困的士人；减轻赋税，减少劳役，帮助百姓解除急困；简化法律，减少刑罚，给犯罪人以把握以后的机会，使天下的人都能自新，改变节操，修养品行，各自谨慎对待自身；满足万民的愿望，以威信仁德对待天下人，天下人就归附了。如果天下到处都欢欢喜喜安居乐业，唯恐发生变乱，那么即使有奸诈不轨的人，而民众没有背叛主上之心，图谋不轨的臣子也就无法掩饰他的奸诈，暴乱的阴谋就可以被阻止了。\n　　二世不实行这种办法，破坏宗庙，残害百姓，比始皇更加暴虐无道，重新修建阿房宫，使刑罚更加繁多，杀戮更加严酷，官吏办事苛刻狠毒，赏罚不得当，赋税搜刮没有限度，国家的事务太多，官吏们都治理不过来；百姓穷困已极，而君主却不加收容救济。于是奸险欺诈之事纷起，上下互相欺骗，蒙受罪罚的人很多，道路上遭到刑戮的人前后相望，连绵不断，天下的人都陷入了苦难。从君卿以下直到平民百姓，人人心中自危，身处穷苦之境，到处都不得安静，所以容易动乱。因此陈涉不凭商汤、周武王那样的贤能，不借公侯那样的尊贵，在大泽乡振臂一呼而天下响应，其原因就在于人民正处于危难之中。\n　　所以古代圣王能洞察开端与结局的变化，知道生存与灭亡的关键，因此统治人民的方法，就是要专心致力于使他们安定罢了。这样，天下即使出现叛逆的臣子，也必然没有人响应，得不到帮助力量了。所谓“处于安定状态的人民可以共同行仁义，处于危难之中的人民容易一起做坏事”，就是说的这种情况。尊贵到做了天子，富足到拥有天下，而自身却不能免于被杀戮，就是由于挽救倾覆局势的方法错了。这就是二世的错误。\n\n下篇\n　　秦朝兼并了诸侯，崤山以东有三十多个郡，修筑渡口关隘，占据着险要地势，修治武器，守护着这些地方。然而陈涉凭着几百名散乱的戌卒，振臂大呼，不用弓箭矛戟等武器，光靠锄把和木棍，虽然没有给养，但只要看到有人家住的房屋就能吃上饭，横行天下。秦朝险阻之地防守不住了，关卡桥梁封锁不住了，长戟刺不了，强弩射不了。楚军很快深入境内，鸿门一战，竟然连篱笆一样的阻拦都没有遇到。于是崤山以东大乱，诸侯纷纷起事，豪杰相继立王。秦王派章邯率兵东征，章邯凭着三军的众多兵力，在外面跟诸侯相约，做交易，图谋他的主上。秦君之间互相不信任，从这件事就可以看出来了。子婴登位，最终也不曾觉悟，假使子婴有一般君主的才能，仅仅得到中等的辅佐之臣，崤山以东地区虽然混乱，秦国的地盘还是可以保全的，宗庙的祭祀也不会断绝。\n　　秦国地势有高山阻隔，有大河环绕，形成坚固防御，是个四面都有险要关塞的国家。从穆公以来，一直到秦始皇，二十多个国君，经常在诸侯中称雄。难道代代贤明吗？这是地位形势造成的呀！再说天下各国曾经同心合力进攻秦国。在这种时候，贤人智士会聚，有良将指挥各国的军队，有贤相沟通彼此的计谋，然而被险阻困住不能前进，秦国就引诱诸侯进入秦国境内作战，为他们打开关塞，结果崤山以东百万军队败逃崩溃。难道是因为勇气、力量和智慧不够吗？是地形不利，地势不便啊。秦国把小邑并为大城，在险要关塞驻军防守，把营垒筑得高高的而不轻易跟敌方作战，紧闭关门据守险塞，肩扛矛戟守卫在那里。诸侯们出身平民，是为了利益联合起来，并没德高望众而位居王位者的德行。他们的交往不亲密，他们的下属不亲附。名义上是说灭亡秦朝，实际上是为自己谋求私利。他们看见秦地险阻难以进犯，就必定退兵。如果他们能安定本土，让人民休养生息，等待秦的衰败，收纳弱小，扶助疲困，来指挥东方诸侯新建的各国的君主，就不用担心在天下实现不了自己的愿望了。可是他们尊贵身为天子，富足拥有天下，自己却遭擒获，这是因为他们在覆亡前夕没有做出挽救的措施。\n　　秦王满足一己之功，不求教于人，一错到底而不改变。二世承袭父过，因循不改，残暴苛虐以致加重了祸患。子婴孤立无亲，自处危境，却又年幼而没有辅佐，三位君主一生昏惑而不觉悟，秦朝灭亡，不也是应该的吗？在这个时候，世上并非没有深谋远虑懂得形势变化的人士，然而他们所以不敢竭诚尽忠，纠正主上之过，就是由于秦朝的风气多有忌讳的禁规，忠言还没说完而自己就被杀戮了。所以使得天下之士只能侧着耳朵听，重叠双脚站立，闭上嘴巴不敢说话。因此，三位君主迷失了路途，而忠臣不敢进谏言，智士不敢出主意，天下已经大乱，皇上还不知道，难道不可悲吗？先王知道壅塞不通就会伤害国家，所以设置公卿、大夫和士，来整治法律设立刑罚，天下因而得到治理。强盛的时候，禁止残暴诛讨叛乱，天下服从；衰弱的时候，五霸为天子征讨，诸侯也顺从；土地被割削的时候，在内能自守备，在外还有亲附，社稷得以保存。所以秦朝强盛的时候，繁法严刑，天下震惊；等到它衰弱的时候，百姓怨恨，天下背叛。周朝的公、侯、伯、子、男五等爵位合乎根本大道，因而传国一千多年不断绝。而秦朝则是本末皆失，所以不能长久。由此看来，安定和危亡的纲纪相距太远了！\n　　俗话说“前事不忘，后事之师”（过去的经验教训不忘记，就是以后做事的借鉴）。因此君子治理国家，考察于上古的历史，验证以当代的情况，还要通过人事加以检验，从而了解兴盛衰亡的规律，详知谋略和形势是否合宜，做到取舍有序，变化适时，所以历时长久，国家安定。▲', poem_appreciation = '《过秦论》共有三篇。其中写得最好、影响最大的是第一篇。它最早附见于《史记·秦始皇本纪》篇末，列为第二篇；后来褚少孙补《史记》，又把它单独附在《陈涉世家》的篇末。《汉书》《文选》也都选录了这一篇。今传贾谊所撰专著《新书》，当由后人搜辑而成，对此文则明确标出它是三篇中的“上篇”。在《史》《汉》《新书》《文选》四部书中，本篇凡五见，文章字句颇有出入。\n\n　　从明、清到当代，几乎所有的古文选本都选了这篇《过秦论》（上），因此前人对它的评语也很多。如清人姚鼐在《古文辞类纂》中评它为“雄骏宏肆”，近人吴闿生在《古文范》的夹批中评它“通篇一气贯注，如一笔书，大开大阖”。归纳大多数评论者的意见，主要说这篇文章气势充沛，一气呵成，是古今第一篇气“盛”的文章。因此吴闿生的意见是比较有代表性的。\n\n　　从语言的角度看，所谓气盛的文章，多用排比句或对偶句，本篇固不例外（如第2段中从“于是六国之士”以下，先用一“有”字领起，贯穿下面三句，罗列了大量人名，就是排比句式；如“蒙故业”以下四句，每两句一对仗，就是对偶句式。也有排比兼对偶的句式，如开头说秦孝公“有席卷天下，包举宇内，囊括四海之意，并吞八荒之心”即是）。但这还只是从表面现象去理解。在古典散文名篇中，用排比句或对偶句的文章并不少，却不一定篇篇气盛。如孔稚圭的《北山移文》，造句或排或偶，比比皆是，然而读起来并不感到气很盛。可见用排比句和对偶句只是使文章气盛增加的因素之一，是属于外在的艺术技巧，而不是主要因素。\n\n　　本篇之所以以气盛为特点而传诵不朽，之所以使人觉得有说服力，有三个原因。第一个是最主要的，即这篇文章虽是说理文，其中却用了十之七八的篇幅来叙事。用叙事来说理，可以说是本篇最大的特点。作者用千把字的篇幅概括了从秦孝公到秦亡国这一百多年来的历史，概括地说明了秦之由盛而衰的全过程和主要现象，同时还贯穿了作者本人的观点来说明其所以兴衰的关键所在。这就帮助我们对这一段历史事实有比较清楚的认识。这个特点为什么就能使文章读起来有气势呢？关键在于：一、作者既能用概括扼要的笔墨来表达丰富的内容，让读者感到短短一篇文章竟然包涵了这许多东西，自然觉得文章饱满充沛，读起来思路自然而然跟着作者的笔锋走，那当然会显得气“盛”了；二、贾谊对秦国由盛而衰、由兴而亡的叙述是很有条理的，上来抓住一条纵的线，即从秦孝公之兴到秦王朝之亡，始终是按照时间的顺序来安排文章的层次先后的；而对某一特定时间内的某一点，又突出地加以铺陈发挥，使人不仅看到“线”，还看到“线”上的一个个用浓墨重彩着重描述的“点”。于是你不由自主地会顺着作者所安排的次序往下推，往下读，他不中断，你就不能中断，他不节外生枝，你就不能旁及其余。因此，这也给人带来了气盛的感觉。\n\n　　第二个使读者感到文章气盛的原因，亦即本篇所具有的另一特点：贾谊在用写赋的手法来写说理散文。写赋是需要铺张和夸大的，贾谊写这篇文章可以说通篇都采用了这种手法。比如第1段“有席卷天下”四句，“席卷”“包举”“囊括”“并吞”等词，基本上都同义；“天下”“宇内”“四海”和“八荒”，也都是同一个意思。同一个意思而一连写上好几句，既有排比又有对仗，这就是写赋的夸张手法。下面第2、第4、第5等段中，都有类似的句子，不胜枚举。所谓“铺张扬厉”，主要就是指的这一类句子。这样，气势自然就充沛了，自然让读者感受到作者的笔锋锐不可当，咄咄逼人，读起来有劲头，有说服力，而且有欲罢不能之感。这是由于作者本人原是一位辞赋作家的缘故。作为作家，贾谊不仅是政治家，也是文学家；作为作品，《过秦论》同样具有文学作品的艺术特色。\n\n　　还有第三个原因，也是这篇文章所具有的第三个特点，即作者用全篇对比到底的手法写出了他的论点。对比手法并没有什么希奇，而本篇精彩处却在于作者用了四个方面的对比：即秦国本身先强后弱、先盛后衰、先兴旺后灭亡的对比；秦与六国的对比；秦与陈涉的对比；陈涉与六国的对比。几种对比交织在一起，结构自然宏伟，气势也自然磅礴，话也显得更有分量了。主客观形势的不同，强弱盛衰难易的不同，都从几方面的对比中显现出来。而文章气盛的道理，也就不难理解了。\n\n　　前三段，主要写三个方面：一、秦国世世代代有野心；二、秦国实力愈来愈强大；三、由于靠实力，秦国统一天下并不很难。第1段着重写有野心，第2段着重写有实力，第3段兼而写之。全篇的铺排和对比都从这三方面入手，把具体事实贯穿进去，用概括的语言勾画出大的轮廓来，使叙述的内容有了倾向性，有了作者自己的观点。如说“秦人拱手而取西河之外”“秦无亡矢遗镞之费”和第3段结束处写“始皇之心，自以为关中之固，金城千里，子孙帝王万世之业也”等等，都是极写秦之野心和实力，极写得天下并不难。与此同时，作者也写了另一方面，如“四君”“九国之师”“六国之士”等等，愈写对方强大也就愈反衬秦之强大，这是烘云托月的手法。但我们却感到：愈写秦之强大，就愈见秦之骄横愚昧；愈写秦之自信太强，就愈见秦之主观片面；愈写秦之野心极大，就愈见秦之眼光短浅。作者虽处处叙而不论，却处处为最后一段的议论在“蓄势”。这样的文章，读起来自然感到饱满酣畅了。\n\n　　第3段开头只说了九个字：“享国之日浅，国家无事”。这当然是事实。但也并非一点可写的事都没有。可是作者不准备在这里多费笔墨，只把那一条贯穿于秦之各个时期的纵线画出来就够了。从行文方面来说，一篇气盛的文章也不能一点不喘息。第3段开头的十几个字，就给全篇形成一个短暂的停顿。明代古文家归有光就说过，这是“如人吐气”（见归有光《评点史记》）。我们固然不能形式主义地看问题，硬要在一气呵成的文章里安插一个“气口”；但文章写到这里，自然有了一个喘息的机会，“如人吐气”，还是必要的，也是学写作的人应予注意的。（或许此文作者的版本 “享国之日浅，国家无事”位于第三段初。）\n\n　　第3段写秦始皇：野心与实力，兼而写之。但第3段与第2段还不一样。第2段是用正反对比手法两面写，第3段却全从正面写，把秦始皇的实力和野心描绘得淋漓尽致，愈写愈足，愈写愈神气。甚至到了第4段开头处，还要找补两句：“始皇既没，余威震于殊俗”。吴闿生夹批：“再加二句，十分酣恣。”这就像给皮球或车轮打气，打到最大限度，再加上两下，自然球胎或轮胎就非爆裂不可了。然后一下子反跌下来，改从陈涉方面写起，却又处处对陈涉寓褒于贬，这就更加写出秦之灭亡实有自取其祸之道了。\n\n　　最末一段是“论”和“断”，仍用对比手法把几个方面综合到一起，然后得出结论，即所谓“断”。为了使结论下得郑重，于是又把秦重新提起总说一遍，才以“仁义不施而攻守之势异也”收尾。文章须能放能收，能开能合，始见本领。贾谊在这篇杰作中完全做到了这一点。\n\n　　金圣叹在《才子古文》（历朝部分）卷二中对本篇加批语说：“《过秦论》者，论秦之过也。秦过只是末句‘仁义不施’一语便断尽，此通篇文字。……至于前半有说六国时，此只是反衬秦；后半有说秦时，此只是反衬陈涉，最是疏奇之笔。”这是说得相当扼要的。\n\n　　这篇文章在当时确实起了好影响。贾谊作为士大夫，固然站在封建统治阶级立场为汉王朝出谋划策；但他却能认识到农民起义的力量，认识到秦王朝灭亡的关键在于失掉民心和过分迷信武力，封建统治者野心大而虐待人民，终于被人民灭亡。有了这个认识，统治阶级才开始考虑如何缓和社会矛盾，以巩固自己的统治政权。这才说明农民起义真正推动了历史前进的车轮。有了贾谊这一番描绘，汉朝的皇帝才能真正总结秦代由盛而衰、由强而弱的经验教训。\n\n　　总结：《过秦论》主旨在于分析“秦之过”，旧分上中下三篇，其实本是一篇，最广为流传的《过秦论》是文章的前三分之一，它通过对秦国兴盛历史的回顾，指出秦国变法图强而得天下，“仁义不施”而不能守天下。而在中篇和下篇，作者则具体地论述了秦统一之后的种种过失。中篇指出秦统一天下，结束了多年的战乱，本来处在很好的形势中，但秦始皇并没有制定出正确的政策，反而焚书坑儒，以暴虐治天下；到了二世时，也不能改正原先的过失，终致国家倾覆。《过秦论》的下篇后部分，作者承接前文，指出在“诸侯并起，豪俊相立”的时候，如果子婴能改变原来错误的政策，“闭关据厄”，“荷戟而守之”，是可以守住三秦之地的，以后“安土息民”，徐图发展，甚至也可以重新恢复国家的统一，但是遗憾的是，秦朝钳口闭言的一贯政策，导致上下“雍闭”，子婴孤立无亲，终于不免灭亡的命运。', poem_tags = '高中文言文,古文观止,议论' WHERE poem_title = '过秦论' AND poem_author = '贾谊';
UPDATE edu_poem SET poem_translation = '深夜梦回楼台朱门紧锁，宿酒醒后帘幕重重低垂。去年的春恨涌上心头时，人在落花纷扬中幽幽独立，燕子在微风细雨中双双翱飞。\n记得与小苹初次相见，她穿着两重心字香熏过的罗衣。琵琶轻弹委委倾诉相思。当时明月如今犹在，曾照着她彩云般的身影回归。', poem_notes = '⑴临江仙：双调小令，唐教坊曲名，后用为词牌。《乐章集》入“仙吕调”，《张子野词》入“高平调”。五十八字，上下片各三平韵。约有三格，第三格增二字。柳永演为慢曲，九十三字，前片五平韵，后片六平韵。\n⑵“梦后”两句：眼前实景，“梦后”“酒醒”互文，犹晏殊《踏莎行·小径红稀》所云“一场秋梦酒醒时”；“楼台高锁”，从外面看，“帘幕低垂”，就里面说，也只是一个地方的互文，表示春来意与非常阑珊。许浑《客有卜居不遂薄游汧陇因题》：“楼台深锁无人到，落尽春风第一花。“\n⑶却来：又来，再来。“去年春恨“是较近的一层回忆，独立花前，闲看燕子，比今年的醉眠愁卧，静掩房栊意兴还稍好一些。郑谷《杏花》：”小桃初谢后，双燕却来时。“”独立“与双燕对照，已暗逗怀人意。《五代诗话》卷七引翁宏《宫词》”落花人独立，微雨燕双飞。“（翁诗全篇见《诗话总龟》前集卷十一。）\n⑷以下直到篇末，是更远的回忆，即此篇的本事。小苹，当时歌女名。汲古阁本《小山词》作者自跋：“始时沈十二廉叔，陈十君宠家，有莲鸿苹云，品清讴娱客。每得一解，即以草授诸儿。“小莲、小苹等名，又见他的《玉楼春》词中。\n⑸心字罗衣：未详。杨慎《词品》卷二：“心字罗衣则谓心字香薰之尔，或谓女人衣曲领如心字。“说亦未必确。疑指衣上的花纹。”心“当是篆体，故可作为图案。”两重心字“，殆含”心心“义。李白《宫中行乐词八首》之一：”山花插鬓髻，石竹绣罗衣“，仅就两句字面，虽似与此句差远，但太白彼诗篇末云：”只愁歌舞散，化作彩云飞“，显然为此词结句所本，则”罗衣“云云盖亦相绾合。前人记诵广博，于创作时，每以联想的关系，错杂融会，成为新篇。此等例子正多，殆有不胜枚举者。\n⑹彩云：比喻美人。江淹《丽色赋》：“其少进也，如彩云出崖。“其比喻美人之取义仍从《高唐赋》”行云“来，屡见李白集中，如《感遇四首》之四”巫山赋彩云“、《凤凰曲》”影灭彩云断“及前引《宫中行乐词》。白居易《简简吟》：”彩云易散琉璃脆。“此篇”当时明月“”曾照彩云“，与诸例均合，寓追怀追昔之意，即作者自跋所云。', poem_appreciation = '这首词抒发作者对歌女小苹怀念之情。比较起来，这首《临江仙·梦后楼台高锁》在作者众多的怀念歌女词中更有其独到之处。全词共四层：\n\n　　“梦后楼台高锁，酒醒帘幕低垂”为第一层。这两句首先给人一种梦幻般的感觉。如不仔细体味，很难领会它的真实含义。其实是词人用两个不同场合中的感受来重复他思念小苹的迷惘之情。由于他用的是一种曲折含蓄，诗意很浓的修词格调。所以并不使人感到啰嗦，却能更好地帮助读者理解作者的深意。如果按常规写法，就必须大力渲染梦境，使读者了解词人与其意中人过去生活情状及深情厚谊。而作者却别开生面，从他笔下迸出来的是“梦后楼台高锁”。即经过甜蜜的梦境之后，含恨望着高楼，门是锁着的，意中人并不真的在楼上轻歌曼舞。作者不写出梦境，让读者去联想。这样就大大地增加了词句的内涵和感染力。至于“梦”和“楼”有什么必然联系，只要细心体味词中的每一句话，就会找到答案。这两句的后面紧接着“去年春恨却来时”。既然词人写的是“春恨”，他做的必然是春梦了。回忆梦境，却怨“楼台高锁”，那就等于告诉读者，他在梦中是和小苹歌舞于高楼之上。请再看晏几道的一首《清平乐·幺弦写意》：“幺弦写意，意密弦声碎。书得凤笺无限事，却恨春心难寄。卧听疏雨梧桐，雨余淡月朦胧，一夜梦魂何处？那回杨叶楼中。”这首词虽然也没有写出梦境，却能使读者联想到，这是非常使人难以忘怀的梦境。以上所谈是词人第一个场合的感受。另一个场合的感受是：“酒醒帘幕低垂”，在不省人事的醉乡中是不会想念小苹的，可是一醒来却见原来居住小苹的楼阁，帘幕低垂，门窗是关着的，人已远去，词人想借酒消愁，但愁不能消。\n\n　　“去年春恨却来时，落花人独立，微雨燕双飞”。三句为第二层。“去年”两字起了承前启后的作用。有了“去年”二字第一层就有了依据。说明两人相恋已久，刻骨铭心。下文的“记得”“当时”“曾照”就有了着落，把这些词句串联起来，整首词就成了一件无缝的天衣。遣词之妙，独具匠心！“却”字和李商隐《夜雨寄北》中“却话巴山夜雨时”中的“却”字一样，当“又”字“再”字解。意思是说：去年的离愁别恨又涌上了心头。紧接着词人借用五代翁宏《春残》“又是春残也，如何出翠帏？落花人独立，微雨燕双飞”的最后两句，但比翁诗用意更深。“落花”示伤春之感，“燕双飞”寓缱绻之情。古人常用“双燕”反衬行文中人物的孤寂之感。如：冯延已《醉桃源·南园春半踏青时》“秋千慵困解罗衣，画梁双燕飞”就是其中一例。晏词一写“人独立”再写“燕双飞”形成了鲜明的对比。此篇盖袭用成语，但翁宏诗作不出名，小晏词句却十分煊赫。这里也有好些原因：（一）乐府向例可引用诗句，所谓”以诗入乐“，如用得浑然天成，恰当好处，评家且认为是一种优点。（二）诗词体性亦不尽同，有用在诗中并不甚好，而在词中却很好的，如晏殊《浣溪沙·一曲新词酒一杯》的”无可奈何“”似曾相识“一联。（三）优劣当以全篇论，不可单凭摘句。\n\n　　“记得小苹初见，两重心字罗衣，琵琶弦上说相思”。为第三层。欧阳修《好女儿令·眼细眉长》：“一身绣出，两重心字，浅浅金黄。”词人有意借用小苹穿的“心字罗衣”来渲染他和小苹之间倾心相爱的情谊，已够使人心醉了。他又信手拈来，写出“琵琶弦上说相思”，使人很自然地联想起白居易《琵琶行》“低眉信手续续弹，说尽心中无限事”的诗句来，给词的意境增添了不少光彩。\n\n　　第四层是最后两句：“当时明月在，曾照彩云归”这两句是化用李白《宫中行乐词》“只愁歌舞散，化作彩云飞”。中国社会科学院文学研究所编的《唐宋词选》把“当时明月在，曾照彩云归”解释为“当初曾经照看小苹归去的明月仍在，眼前而小苹却已不见”，这样解释虽然不错，但似乎比较乏味。如果把这两句解释为“当时皓月当空，风景如画的地方，现在似乎还留下小苹归去时，依依惜别的身影”。这样会增加美的感受，像彩云一样的小苹在读者的头脑里，会更加妩媚多姿了。 把“在”字当作表示处所的方位词用，因为在吴系语中，“在”能表达这种意思。某处可说成“某在”。杨万里《明发南屏》“新晴在在野花香”。“在在”犹“处处”也，可作佐证。这首《临江仙》含蓄真挚，字字关情。词的上阕“去年春恨却来时”可说是词中的一枚时针，它表达了词人处于痛苦和迷惘之中，其原因是由于他和小苹有过一段甜蜜幸福的爱情。时间是这首词的主要线索。其余四句好像是四个相对独立的镜头（即1、梦后，2、酒醒，3、人独立，4、燕双飞），每个镜头都渲染着词人内心的痛苦，句句景中有情。', poem_tags = '宋词三百首,宋词精选,婉约,怀念,歌女' WHERE poem_title = '临江仙·梦后楼台高锁' AND poem_author = '晏几道';
UPDATE edu_poem SET poem_translation = '太阳从东南方升起，照到我们秦家的小楼。秦家有位美丽的少女，自家取名叫罗敷。罗敷善于养蚕采桑，（有一天在）城南边侧采桑。用青丝做篮子上的络绳，用桂树枝做篮子上的提柄。头上梳着堕马髻，耳朵上戴着宝珠做的耳环；浅黄色有花纹的丝绸做成下裙，紫色的绫子做成上身短袄。走路的人看见罗敷，放下担子捋着胡子（注视她）。年轻人看见罗敷，禁不住脱帽重整头巾，希望引起罗敷对自己的注意。耕地的人忘记了自己在犁地，锄地的人忘记了自己在锄地；以致于农活都没有干完，回来后相互埋怨，只是因为仔细看了罗敷的美貌。\n\n　　太守乘车从南边来到这，拉车的五匹马停下来徘徊不前。太守派遣小吏过去，问这是谁家美丽的女子。小吏回答：“是秦家的女儿，自家起名叫做罗敷。”太守又问：“罗敷多少岁了？”小吏回答：“还不到二十岁，但已经过了十五了。”太守请问罗敷：“愿意与我一起乘车吗？”\n\n　　罗敷上前回话：“太守你怎么这样愚蠢！太守你已经有妻子了，罗敷我也已经有丈夫了！（丈夫当官）在东方，随从人马一千多，他排列在最前头。怎么识别我丈夫呢？骑白马后面跟随小黑马的那个大官就是，用青丝拴着马尾，那马头上戴着金黄色的笼头；腰中佩着鹿卢剑，宝剑可以值上千上万钱，十五岁在太守府做小吏，二十岁在朝廷里做大夫，三十岁做皇上的侍中郎，四十岁成为一城之主。他皮肤洁白，有一些胡子；他轻缓地在府中迈方步，从容地出入官府。（太守座中聚会时）在座的有几千人，都说我丈夫出色。”', poem_notes = '⑴陌上桑：陌：田间的路。桑：桑林。\n⑵东南隅：指东方偏南。隅，方位、角落。中国在北半球，夏至以后日渐偏南，所以说日出东南隅。\n⑶喜蚕桑：喜欢采桑。喜，有的本子作“善”（善于、擅长）。\n⑷青丝为笼系：用黑色的丝做篮子上的络绳。笼，篮子。系，络绳（缠绕篮子的绳子）。\n⑸笼钩：一种工具。采桑用来钩桑枝，行时用来挑竹筐。\n⑹倭堕髻：即堕马髻，发髻偏在一边，呈坠落状。倭堕，叠韵字。\n⑺缃绮：有花纹的浅黄色的丝织品。\n⑻帩头：帩头，古代男子束发的头巾。\n⑼少年：古义（10-20岁）男\n⑽但：只是。坐：因为，由于。\n⑾使君：汉代对太守、刺史的通称。\n⑿姝：美丽的女子。\n⒀谢：这里是“请问”的意思。\n⒁不：通假字，通“否”音也为“否”的音。\n⒂居上头：在行列的前端。意思是地位高，受人尊重。\n⒃鹿卢剑：剑把用丝绦缠绕起来，像鹿卢的样子。鹿卢，即辘轳，井上汲水的用具。宝剑，荆轲刺秦王时带的就是鹿卢剑。\n⒄侍中郎：出入宫禁的侍卫官。\n⒅盈盈：仪态端庄美好。\n⒆冉冉：走路缓慢。', poem_appreciation = '全诗共分三解。解为乐歌的段落，本诗的乐歌段落与歌词内容的段落大致相合。第一解从开始至“但坐观罗敷”，主要叙述罗敷的美貌。第二解从“使君从南来”至“罗敷自有夫”，写太守觊觎罗敷容姿，要跟她“共载”而归，遭到罗敷严辞拒绝。第三解从“东方千余骑”至结束，写罗敷在太守面前夸赞自己丈夫，用意在于彻底打消太守的邪念，并让他对自己轻佻的举止感到羞愧。\n\n　　诗人成功地塑造了一个貌美品端、机智活泼、亲切可爱的女性形象。一般来说，人们认识一个人，总是先识其外貌，然后再洞达其心灵。《陌上桑》塑造罗敷的形象也依循人们识辨人物的一般顺序，在写法上表现为由容貌而及品性。罗敷刚出现，还只是笼统地给人一个“好女”的印象，随着叙述的展开，通过她服饰的美丽和路人见到他以后无不倾倒的种种表现，“好女”的形象在读者眼前逐渐变得具体和彰明。第二、三段，诗人的笔墨从摹写容貌转为表现性情，通过罗敷与使君的对话，她抗恶拒诱，刚洁端正的品格得到了充分的展示。从她流利得体，同时又带有一点调皮嘲弄的答语中，还可看出她禀性开朗、活泼、大方，对自己充满自信，并且善于运用智慧保护自己不受侵害。当然这只是大致的概括，事实上，作品在这方面也不乏灵活的安排。如第一解虽然主要写容貌，“罗敷喜蚕桑”则又表现出她热爱劳动的良好品质；第二、三解虽然主要揭示她内心情感，但第二解使君立马踟蹰不前，分明又暗中映显出罗敷美貌丽态的魅力，第三解罗敷夸扬丈夫姿容，与一解总述罗敷美好“遥对”（张玉谷《古诗赏析》卷五），不正可以见到罗敷本人的倩影吗？诗人笔下的罗敷品貌俱美，从而赋予这一艺术形象更高的审美价值。读完全诗，人们对罗敷的喜爱比起诗中那些忘乎所以的观望者的态度来更加深厚真挚，因为他们还仅仅是为罗敷的容貌所吸引，读者却又对罗敷的品格投以敬佩。从这一意义上说，《陌上桑》与《诗经·硕人》在摹绘美人的形象方面，其区别不仅在于具体手法的不同（这一点下面还会谈到），还在于它由比较单纯地刻画人物的容貌之美进而达到表现性情之美，这后面一点显然在文学形象的创造史上具有更重要的意义。\n\n　　《陌上桑》在写作手法方面，最受人们称赞的是侧面映衬和烘托。如第一解写罗敷之美，不用《硕人》直接形容具体对象容貌的常套，而是采用间接的、静动结合的描写来暗示人物形象的美丽。先写罗敷采桑的用具和她装束打扮的鲜艳夺目，渲染服饰之美又是重点。“青丝为笼系，桂枝为笼钩。头上倭堕髻，耳中明月珠。缃绮为下裙，紫绮为上襦。”这些诗句一字不及罗敷的容貌，而人物之美已从衣饰等的铺叙中映现出来。前人评汉乐府《江南》诗句“莲叶何田田”，说：“不说花偏说叶，叶尚可爱，花不待言矣。”张玉谷《古诗赏析》卷五。这话也可以被运用来说明本篇上述诗句的艺术特点。更奇妙的是，诗人通过描摹路旁观者的种种神态动作，使罗敷的美貌得到了强烈而又极为鲜明、生动的烘托。“行者见罗敷，下担捋髭须。少年见罗敷，脱帽著帩头。耕者忘其犁，锄者忘其锄。来归相怨怒，但坐观罗敷。”爱美之心人皆有之，而人类对异性美（尤其是在形貌方面）就更为敏感，同时也会表现出更高的热情。这些男性旁观者为罗敷深深吸引，乃至有意无意地做出一些想取悦罗敷的举止，（“脱帽著帩头”的动作暗示了自己未婚)正说明他们看到罗敷时激动不宁的心情和从她身上获得的审美满足。借助于他们的目光，读者似乎也亲眼饱睹了罗敷的面容体态。这样来塑造人物形象，比借助比喻等手段正面进行摹写显得更加富有情趣；而且由于加入了旁观者的反应，使作品的艺术容量也得到了增加。这是《陌上桑》为描写文学形象提供的新鲜经验。\n\n　　除了从侧面摹写形象外，本篇还善于从侧面表达意图，这主要是指第三解罗敷夸夫的内容。对这段内容，人们有两种理解：一种认为诗中“夫婿”是罗敷实指其夫，另一种意见是罗敷虚设一夫，更有人断定这一段是诗中的糟粕。“夫婿”究竟是实指还是虚设，这是弄不明白的问题，不过这并不重要。重要的倒是应该弄清楚：罗敷当时为何要讲这番话?意图何在?她集中夸赞自己丈夫的尊贵和美好，这显然是有明显的针对性。因为调戏她的是一位怀有特殊优越感的太守，罗敷说自己丈夫尊贵，则使其优越感变得可笑；又因为太守看中她的是美色，罗敷说自己丈夫美好，实际上是说只有丈夫才可以与自己相配。罗敷这段话句句夸夫，而客观上又句句奚落太守，这正是全诗侧面写法的又一次运用。诗歌的喜剧效果主要也是从这里得到体现的。第三解在整篇作品中不是可有可无，更不是什么糟粕，而是诗篇的有机构成。\n\n　　幽默风趣是《陌上桑》明显的风格特点。如写旁观者见到罗敷时不由自主地表现出来的种种神态，十分好笑，而又无不是乡民的真趣流露。又如罗敷讲自己的年龄，“二十尚不足，十五颇有余”，口齿伶俐，而又暗带调皮，“颇”字尤见口角语态之妙。最后一段罗敷盛夸夫婿，使眼前那位听着的太守感到通身不自在，羞愧难状。这一寓严肃的主题于诙谐的风格之中的优秀诗篇，体现了乐观和智慧，它与《孔雀东南飞》《东门行》等体现的悲慨和亢烈相比，代表着汉乐府又一种重要的艺术精神。它和《孔雀东南飞》《东门行》《木兰诗》堪称乐府名著。当中《孔雀东南飞》《木兰诗》又是乐府双壁\n\n　　《陌上桑》的语言带有明显的藻采化倾向，主要是反映在第一和第三节中。这些构成了此篇统一的叙述风格。\n\n　　正是罗敷这种表里如一的“美”，才深深地打动了所有善良的人们，无论是年长的老者（行者），还是翩翩的少年，抑或是耕锄的百姓，都为罗敷的美所倾倒，看见了她以至于忘记了一切。正如诗中所描述的：“行者见罗敷，下担捋髭须。少年见罗敷，脱帽著帩头。耕者忘其犁，锄者忘其锄。”这一段描写既巧妙，又夸张，虽不是精雕细琢，但却是浓墨重彩，罗敷那不能言喻的美尽在这旁观者的“不言”之中。\n\n　　同时罗敷的美是平淡中含着典雅、质朴中透着高贵、清丽中显露豪华，不同身份的人能从不同的角度看到自己所欣赏的不同的“美”，这便是所谓的“雅俗共赏”。', poem_tags = '写人,乐歌' WHERE poem_title = '陌上桑' AND poem_author = '乐府诗集';
UPDATE edu_poem SET poem_translation = '中年以后存有较浓的好道之心，直到晚年才安家于终南山边陲。\n兴趣浓时常常独来独往去游玩，有快乐的事自我欣赏自我陶醉。\n间或走到水的尽头去寻求源流，间或坐看上升的云雾千变万化。\n偶然在林间遇见个把乡村父老，偶与他谈笑聊天每每忘了还家。', poem_notes = '①中岁：中年。好（hào）：喜好。道：这里指佛教。\n②家：安家。南山：即终南山。陲（chuí）：边缘，旁边，边境；南山陲，指辋 川别墅所在地，意思是终南山脚下。\n③胜事：美好的事。\n④值：遇到。叟（sǒu）：老翁。\n⑤无还期：没有回还的准确时间。', poem_appreciation = '全诗的着眼点在于抒发对自得其乐的闲适情趣的向往。开篇二句，由“中岁好道”“晚家南山”点明诗人隐居奉佛的人生归宿和思想皈依。“道”，指佛家道义之精髓，即“万法皆空”思想。“中岁颇好道”，作者强调自中年起，他就已倾心佛法了，随着时间的推移，这种倾向会越来越加剧，反映出他对尘世越来越厌倦，这与其人生际遇密切相关。一个“颇”字，点明其崇佛的虔诚心态。“晚”字，意蕴丰富，既可以指“晚近”，也可以指“晚年”。如果是前者，“晚家南山陲”是对现实隐居生活的描绘；如果是后者，则是对自己晚景的构想。\n\n　　山林的生活自在无比，兴致来临之际，每每独往山中信步闲走，那快意自在的感受只有诗人自己能心领神会。“每”，表明“兴来独往”非常频繁，不是偶然为之。“独”，并非没有同调之人，事实上，诗人隐居之际不乏同调之人与其往来唱和，如张諲、裴迪等，此处当指诗人兴致一来就等不及邀人同往了，一个洒脱的隐者形象便展现到了读者面前。从字面意义上看，隐隐约约带有些落寞，但谁又能说这种情致不是件快乐的事呢？“胜事空自知”，亦然，一个“空”字，也许带有几分无奈与孤独，但诗人是陶醉于这种山林情趣间的。\n\n　　“行到水穷处，坐看云起时”即言“胜事”。在山间信步闲走，不知不觉中，已到了溪水尽头，似乎再无路可走，但诗人却感到眼前一片开阔，于是，索性坐下，看天上的风起云涌。一切是那样的自然，山间流水、白云，无不引发作者无尽的兴致，足见其悠闲自在。清人沈德潜赞曰：“行所无事，一片化机。”（《唐诗别裁集》）“行到水穷处”，让读者体味到了“应尽便须尽”的坦荡；“坐看云起时”，在体味最悠闲、最自在境界的同时，又能领略到妙境无穷的活泼！云，有形无迹，飘忽不定，变化无穷，绵绵不绝，因而给人以无心、自在和闲散的印象，陶潜有诗云“云无心以出岫”（《归去来兮辞》），而在佛家眼里，云又象征着“无常心”“无住心”。因此，“坐看云起时”，还蕴藏着一种“应无所住而生其心”的禅机。简而言之，就是“空”，如果人能够去掉执着，像云般无心，就可以摆脱烦恼，得到解脱，得到自在，诗人在一坐、一看之际已经顿悟。再看这流水、白云，已是无所分别，达到了物我一体的境界。从结构看，“行到水穷处，坐看云起时”二句，对偶工稳，一贯而下，从艺术手法上看，此二句俨然是一幅山水画，是“诗中有画”也。\n\n　　结句写作者在山间偶然碰到了“林叟”，于是无拘无束地跟其尽情谈笑，以致忘了时间，诗人淡逸的天性和超然物外的风采跃然纸上，与前面独赏山水时的洒脱自在浑然一体，使得全诗形成了一个完整的意境。“偶然”二字，贯穿前后，却行迹全无，其实，“兴来独往”“行到水穷处，坐看云起时”等，何尝不是“无心的偶然”呢？然诗人至此方借“值林叟”点出“偶然”二字，可见艺术手段之高超。因为处处“偶然”，更显现出心中的悠闲自在。“谈笑无还期”结句自然，却暗藏哲理，诗人因为体悟到物我两忘、物我一体之境，从而忘记了那流迁无常的世俗世界，这是真正的“空”境。\n\n　　这首诗没有描绘具体的山川景物，而重在表现诗人隐居山间时悠闲自得的心境。诗的前六句自然闲静，诗人的形象如同一位不食人间烟火的世外高人，他不问世事，视山间为乐土。不刻意探幽寻胜，而能随时随处领略到大自然的美好。结尾两句，引入人的活动，带来生活气息，诗人的形象也更为可亲。', poem_tags = '唐诗三百首,田园,写人,抒情' WHERE poem_title = '终南别业' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '巍巍岳阳楼矗立在洞庭湖之东长江之西，夕阳黄昏，没有晚风卷起，楼阁上的招牌静止不动。\n登临当年吴国和蜀国的分界之处（荆州），在湖山黄昏下徘徊。\n行程万里，今日登高远望是什么心绪？为避战乱我奔波三年。\n登楼凭吊古人，我自己已是两鬓如霜，看着远山的古树，青苍中，隐含无限的伤悲。\n\n平湖映着天空的影子，晴空万里，波澜不惊，大雁在空中飞来飞去。\n岳阳楼很多人都在看秋天的景色，看日落君山。\n往北边可以看到白首，往南边可以看到丹枫。\n一路欣赏景色，结果到了巴陵还没有写出来诗。', poem_notes = '⑴帘旌（jīng）：酒店或茶馆的招子。夕阳迟：夕阳缓慢地下沉。迟，缓慢。\n⑵吴蜀横分地：三国时吴国和蜀国争夺荆州，吴将鲁肃曾率兵万人驻扎在岳阳。横分，这里指瓜分。\n⑶徙（xǐ）倚（yǐ）：徘徊。\n⑷三年多难：公元1126年（宋钦宗靖康元年）春天北宋灭亡，到写此诗时已有三年。凭危：指登楼。凭，靠着。危，指高处。\n⑸吊古：哀吊，凭吊。\n⑹晴不风：晴空万里，波澜不惊。\n⑺杪（miǎo）秋：晚秋。\n⑻君山：全称君山岛，位于湖南岳阳东部的洞庭湖中。\n⑼白首：白发。这里指为枯萎而不凋谢的白色草。\n⑽丹枫：经霜泛红的枫叶。', poem_appreciation = '其一\n\n　　《登岳阳楼》二首都是七言律诗。其中第一首是诗人写岳阳楼的开篇之作，所以精心打造，郑重其事。首联写岳阳楼的地理位置，先从大处着墨，以洞庭湖和长江为背景，在一个宏观视野中隆重推出岳阳楼。“洞庭之东江水西”，诗人在一句七字之中，巧妙地运用了“东”“西”两个方位词，并以湖、江系之，则岳阳楼之所在，如或可见。而后再写举目所见，为“帘旌不动夕阳迟”。这一句是全诗写景浓墨重彩的一笔，看似平常，实则细腻。“帘旌”为近景，“夕阳”为远景，近景远景合而为一，诗人的视线由近及远地扫描，逐渐放开，融入那苍茫的暮色中。不动的帘旌，表明湖面风平浪静；迟落的夕阳，提示着傍晚的安详。这样富有诗情画意的情境，不禁引起诗人丰富的遐想。\n\n　　诗的颔联从静态舒缓的景物描写中振起，转而为强烈的抒情。仿佛是音乐的变奏，这两句诗似乎是在重复上面的主题，风格却又迥然不同了。“登临吴蜀横分地”，也是在说登临的地理位置，却加入了厚重的历史感；“徙倚湖山欲暮时”，也是在写黄昏时分登楼观景，却融入了些许怅惘之情。这样的渐变，是一种烘托，是一种过渡，是一种物我兼融的摹状。在这里，诗人的主体形象不经意地、自然而然地出现在诗中，他在思索，在徘徊，在融情入景，在借景抒怀。\n\n　　经过前面的蓄势，诗人终于在颈联以近于直呼的方式，发出了最高亢最强烈的呐喊：“万里来游还望远，三年多难更凭危。”这两句诗，道出了一个亡国之臣心中的愤懑。“万里”与“三年”对举，分别从空间、时间的跨度上来叙述其事，收到了双重叠加的艺术效果，读之让人感慨万分。诗人的“万里来游”不过是万里逃难的高雅说法，但是又无可奈何。心中的苦闷，只好在“远望”中消解。“三年多难”，本来已经不胜觳觫，却还要在这里登高临危，让人不堪忍受。诗意至此，已经一波三折，千回百转，把感情推向了极致。\n\n　　诗的最后一联，顾影自怜，以无限悲凉的身世之慨收束全篇。此时，诗人已届四十，到了不惑之年，所以言“白头”；不说伤今，而言“吊古”，含蓄蕴藉，意味深长；“风霜”明指自然事物，实喻社会现实，语意双关；而“老木沧波”更是包裹诗人形象的一件外衣，无限悲恨。这一联似乎是诗人自语，未老先衰头已白，为国事，为家事，为自己，为那些与自己一样国破家亡的同乡们焦虑、忧愁，吊古伤今，感怀伤时，在秋霜的季节里，更觉时世如风霜相逼，冷峭之极。那衰老的枯木、那苍凉的湖面，就像是作者自己。沦落天涯无尽的凄凉，国破家亡的无限悲痛，一切尽在不言中。\n\n　　其二\n\n　　第一首写登楼，而第二首转写景和归途。诗人登上岳阳楼，看到的是“天入平湖晴不风，夕帆和雁正浮空。”这就描绘了多种景物：天空、湖水、倒影、夕日、大雁，构成了洞庭湖独有的美景。表面上“晴不风”三字略显俗套，但这正和“大漠孤烟直，长河落日圆”有相同韵味，不加修饰，只是写的是湖水之壮美，这更显手法独特。第二联写人亦写景，而且再次点明时间是傍晚时分。第三联起，开始写诗人的归途了，而且又再一次将诗句引向了景物，向北看，见白草稀稀，向南望则见枫叶红红，这一联的描写将整首诗推向高潮，对仗工整，别有韵味。最后两句就是写诗人只顾观景，写着的诗到了江陵还未完，这就从侧面衬托了长江洞庭之间风光之好。整首诗的感情同第一首一样，是“忧”的，因为两首诗记述的为同一系列的事，其感情也是相同的，只是被隐藏了，这首诗实际上表达了北宋国亡后，作者只能观景排忧之情。', poem_tags = '登楼,写景,抒怀,感慨' WHERE poem_title = '登岳阳楼二首' AND poem_author = '陈与义';
UPDATE edu_poem SET poem_translation = '清晨，连绵起伏的鲁山，千峰竞秀，忽高忽低，蔚为壮观，正好迎合了我爱好自然景色的情趣。\n一路上，奇峰峻岭在眼前不断地变换，沉醉于一人在蜿蜒幽深的小路上游览的野趣，竟忘了走到了什么地方。\n太阳高升，霜雪融落，山林显得愈加寂静空荡，笨熊正在缓慢地爬着大树，鹿儿正在悠闲地喝着小溪的潺潺流水。\n看不到房舍，也望不见炊烟，我心中不禁疑问，山里是否也有人家居住？就在这时，忽听得远处云雾缭绕的山间传来一声鸡鸣。', poem_notes = '⑴鲁山：一名露山，在河南鲁山县东北，接近襄城县境。\n⑵适：恰好。野情：喜爱山野之情。惬（qiè）：心满意足。\n⑶随处改：（山峰）随观看的角度的变化而变化。\n⑷幽径：小路。\n⑸熊升树：熊爬上树。一作大熊星座升上树梢。\n⑹何许：何处，哪里。\n⑺云外：形容遥远。一声鸡：暗示有人家。', poem_appreciation = '这首诗运用丰富的意象，动静结合，描绘了一幅斑斓多姿的山景图：深秋时节，霜降临空，诗人在鲁山中旅行。山路上没有其他人，诗人兴致勃勃，一边赶路一边欣赏着千姿百态的山峰和山间的种种景象。仿佛从云外传来的一声鸡鸣，告诉诗人有人家的地方还很远很远。\n\n　　这是一首五律，但不为格律所缚，写得新颖自然，曲尽山行情景。\n\n　　山路崎呕，对于贪图安逸，怯于攀登的人来说，“山行”不可能有什么乐趣。山野荒寂，对于酷爱繁华，留恋都市的人来说，“山行”也不会有什么美感和诗意。此诗一开头就将这一类情况一扫而空，兴致勃勃地说：“适与野情惬”——恰恰跟作者爱好山野风光的情趣相合。下句对此作了说明：“千山高复低。”按时间顺序，两句为倒装。一倒装，既突出了爱山的情趣，又显得跌宕有致。“千山高复低”，这当然是“山行”所见。看见了山野非常喜爱，心中很满足，群山连绵起伏的，时高时低，一个“惬”字，足以体会出当时作者心满意足的心情。“适与野情惬”，则是 “山行”所感。首联只点“山”而“行”在其中。\n\n　　颔联进一步写“山行”。“好峰”之“峰”即是“千山高复低”；“好峰”之“好”则包含了诗人的美感，又与“适与野情惬”契合。说“好峰随处改”，见得人在“千山”中继续行走，也继续看山，眼中的“好峰”也自然移步换形，不断变换美好的姿态。第四句才出“行”字，但不单是点题。“径”而曰“幽”，“行”而曰“独”，正合了诗人的“野情”。着一“迷”字，不仅传“幽”、“独”之神，而且以小景见大景，进一步展示了“千山高复低”的境界。山径幽深，容易“迷”；独行无伴，容易“迷”；“千山高复低”，更容易“迷”。著此“迷”字，更见野景之幽与野情之浓。\n\n　　颈联“霜落熊升树，林空鹿饮溪”，互文见意，写“山行”所见的动景。“霜落”则“林空”，既点时，又写景。霜未落而林未空，林中之“熊”也会“升树”，林中之“鹿”也要“饮溪”；但树叶茂密，遮断视线，“山行”者很难看见“熊升树”与“鹿饮溪”的野景，作者特意写出“霜落”、“林空”与“熊升树”、“鹿饮溪”之间的因果关系，正是为了表现出那是“山行”者眼中的野景。惟其是“山行”者眼中的野景，所以饱含着“山行”者的“野情”。“霜落”而“熊升树”，“林空”而“鹿饮溪”，很是闲适，野趣盎然。\n\n　　苏轼《高邮陈直躬处士画雁》诗云：“野雁见人时，未起意先改。君从何处看，得此无人态？无乃枯木形，人禽两自在！······”梅尧臣从林外“幽径”看林中，见“熊升树”、“鹿饮溪”，那正是苏轼所说的“无人态”，因而就显得“自在”。熊“自在”，鹿“自在”，看“熊升树”、“鹿饮溪”的人也“自在”。\n\n　　欧阳修《六一诗话》云：“圣俞尝语余曰：‘诗家虽主意，而造语亦难。若意新语工，得前人所未道者，斯为善也。必能状难状之景如在目前，含不尽之意见于言外，然后为至矣。’”此联就可以说是“状难状之景如在目前”。而且还“含不尽之意见于言外”。“熊升树”、“鹿饮溪”而未受到任何惊扰，见得除“幽径”的“独行”者而外，四野无人，一片幽寂；而“独行”者看了。“熊升树”，又看“鹿饮溪”，其心情之闲静愉悦，也见于言外。从章法上看，这一联不仅紧承上句的“幽”、“独”而来，而且对首句“适与野情惬”作了更充分的表现。\n\n　　全诗以“人家在何许？云外一声鸡”收尾，余味无穷。杜牧的“白云生处有人家”，是看见了人家。王维的“欲投人处宿，隔水问樵夫”，是看不见人家，才询问樵夫。这里又是另一番情景：望近处，只见“熊升树”、“鹿饮溪”，没有人家；望远方，只见白云浮动，也不见人家；于是自己问自己：“人家在何许”呢？恰在这时，云外传来一声鸡叫，仿佛是有意回答诗人的提问：“这里有人家哩，快来休息吧！”两句诗，写“山行”者望云闻鸡的神态及其喜悦心情，都跃然可见、宛然可想。', poem_tags = '古诗三百首,初中古诗,登山,写景,抒怀' WHERE poem_title = '鲁山山行' AND poem_author = '梅尧臣';
UPDATE edu_poem SET poem_translation = '一篇谏书早晨上奏给皇帝，晚上就被贬官到路途遥远的潮阳去。\n想替皇上除去有害的事，哪能因衰老就吝惜残余的生命。\n云彩横出于南山，我的家在哪里？在白雪厚积的蓝田关外，马也停住脚步。\n知道你远道而来定会有所打算，正好在瘴江边收殓我的尸骨。', poem_notes = '⑴左迁：降职，贬官，指作者被贬到潮州。蓝关：在蓝田县南。《地理志》：“京兆府蓝田县有蓝田关。”湘：韩愈的侄孙韩湘，字北渚，韩愈之侄，韩老成的长子，长庆三年（823年）进士，任大理丞。韩湘此时27岁，尚未登科第，远道赶来从韩愈南迁。\n⑵一封：指一封奏章，即《论佛骨表》。朝（zhāo）奏：早晨送呈奏章。九重（chóng）天：古称天有九层，第九层最高，此指朝廷、皇帝。\n⑶路八千：泛指路途遥远。八千，不是确数。\n⑷“欲为”二句：想替皇帝除去有害的事，哪能因衰老就吝惜残余的生命。弊事：政治上的弊端，指迎佛骨事。肯：岂肯。衰朽（xiǔ）：衰弱多病。惜残年：顾惜晚年的生命。圣明，指皇帝。\n⑸秦岭：在蓝田县内东南。\n⑹“雪拥”句：立马蓝关，大雪阻拦，前路艰危，心中感慨万分。拥：阻塞。蓝关：蓝田关，今在陕西省蓝田县东南。马不前：古乐府《饮马长城窟行》：“驱马涉阴山，山高马不前。”\n⑺汝（rǔ）：你，指韩湘。应有意：应知道我此去凶多吉少。\n⑻“好收”句：意思是自己必死于潮州，向韩湘交待后事。瘴（zhàng）江：指岭南瘴气弥漫的江流。瘴江边：指贬所潮州。\n⑼潮阳：今广东潮州潮安区。', poem_appreciation = '韩愈《论佛骨表》是一篇正气凛然的名文。文中说：“今闻陛下令群僧迎佛骨于凤翔，御褛以观，升入大内，又令诸寺递迎供养。——百姓何人，岂合更惜身命？焚香烧指，百十为群，解衣散钱，自朝至暮，转相仿效，惟恐后时。老少奔波，弃其业次。若不即加禁遏，更历诸寺，必有断骨脔身，以为供养者。伤风败俗，传笑四方，非细事也。——佛如有灵，能作祸祟，凡有殃咎，宜加臣身，上天鉴临，巨不怨悔。”这首诗和这篇文珠联璧合，相得益彰，具有深刻的社会意义。\n\n　　前两联写“左遣”，一气贯注，浑灏流转。“贬”的原因是“奏”，“奏”的本意是为国“除弊”，可见“贬”非其罪。然而“朝奏”而“夕贬”，处罚何其迅急！一贬就贬到“八千”里以外，处罚又何其严厉！那么“九重天”虽高而不明，也就意在言外了。第三句理直气壮地声言“欲为圣明除弊事”，表明并未因受严谴而有丝毫心，其刚正不屈的风骨宛然如见。“朝奏”与“夕贬”、“九重天”与“路八千”、“圣明”与“衰朽”、“欲……除弊事”与“肯……惜残年”，强烈对比，高度概括，扩大和加深了诗的内涵。', poem_tags = '初中古诗,叙事,写景,抒情' WHERE poem_title = '左迁至蓝关示侄孙湘' AND poem_author = '韩愈';
UPDATE edu_poem SET poem_translation = '见云之灿烂想其衣裳之华艳，见花之艳丽想人之容貌照人。\n若不是在群玉山头见到了她，就是在瑶池的月光下来相逢。', poem_notes = '清平调：一种歌的曲调，“平调、清调、瑟调”皆周房中之遗声。\n“云想”句：见云之灿烂想其衣之华艳，见花之艳丽想美人之容貌照人。实际上是以云喻衣，以花喻人。\n槛：栏杆；露华浓：牡丹花沾着晶莹的露珠更显得颜色艳丽。\n“若非……会向……”：相当于“不是……就是……”的意思。群玉：山名，传说中西王母所住之地。全句形容贵妃貌美惊人，怀疑她不是群玉山头所见的飘飘仙子，就是瑶台殿前月光照耀下的神女。', poem_appreciation = '第一首，一起七字：“云想衣裳花想容，”把杨妃的衣服，写成真如霓裳羽衣一般，簇拥着她那丰满的玉容。“想”字有正反两面的理解，可以说是见云而想到衣裳，见花而想到容貌，也可以说把衣裳想象为云，把容貌想象为花，这样交互参差，七字之中就给人以花团锦簇之感。接下去“春风拂槛露华浓”，进一步以“露华浓”来点染花容，美丽的牡丹花在晶莹的露水中显得更加艳冶，这就使上句更为酣满，同时也以风露暗喻君王的恩泽，使花容人面倍见精神。下面，诗人的想象忽又升腾到天堂西王母所居的群玉山、瑶台。“若非”、“会向”，诗人故作选择，意实肯定：这样超绝人寰的花容，恐怕只有在上天仙境才能见到。玉山、瑶台、月色，一色素淡的字眼，映衬花容人面，使人自然联想到白玉般的人儿，又像一朵温馨的白牡丹花。与此同时，诗人又不露痕迹，把杨妃比作天女下凡，真是精妙至极。', poem_tags = '唐诗三百首,乐府,赞美,女子' WHERE poem_title = '清平调·其一' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '生下来以后还不会相思，才刚刚懂了什么是相思，却深受着相思之苦。\n身像飘浮的云，心像纷飞的柳絮，气像一缕缕游丝。\n空剩下一丝余香留在此，心上人却已不知道在哪里去留？\n相思病症候的到来，最猛烈的时候是什么时候？是灯光半昏半暗时，是月亮半明半亮的时候。', poem_notes = '①身似浮云：形容身体虚弱，走路晕晕乎乎，摇摇晃晃，像飘浮的云一样。\n②余香：指情人留下的定情物。\n③盼千金游子何之：殷勤盼望的情侣到哪里去了。何之，往哪里去了。千金：喻珍贵。千金游子：远去的情人是富家子弟。\n④证候：即症候，疾病，此处指相思的痛苦。', poem_tags = '少女,相思,爱情' WHERE poem_title = '折桂令·春情' AND poem_author = '徐再思';
UPDATE edu_poem SET poem_translation = '苍松下，我询问了年少的学童；他说，师傅已经采药去了山中。\n他还对我说，就在这座大山里，可山中云雾缭绕，不知他行踪。', poem_notes = '⑴寻：寻访。隐者：隐士，隐居在山林中的人。古代指不肯做官而隐居在山野之间的人。一般指的是贤士。不遇：没有遇到，没有见到。\n⑵童子：没有成年的人，小孩。在这里是指“隐者”的弟子、学生。\n⑶言：回答，说。\n⑷云深：指山上的云雾。处：行踪，所在。', poem_appreciation = '贾岛是以“推敲”两字出名的苦吟诗人。一般认为他只是在用字方面下功夫，其实他的“推敲”不仅着眼于锤字炼句，在谋篇构思方面也是同样煞费苦心的。此诗就是一个例证。\n\n　　全诗只有二十字，作为抒情诗，却有环境，有人物，有情节，内容极丰富，其奥秘在于独出心裁地运用了问答体。不是一问一答，而是几问几答，并且寓问于答。 第一句省略了主语“我”。“我”来到“松下”问“童子”， 见得“松下”是“隐者”的住处，而“隐者”外出。“寻隐者不遇”的题目已经交待清楚。“隐者” 外出而问其“童子”，必有所问，而这里把问话省略了，而写出“童子”的答语：“师采药去。”从这四个字而可想见当时松下所问是“师往何处去”。“我” 专程来“寻隐者”，“隐者”“采药去”了，自然很想把他找回来。因而又问童子：“采药在何处？”这一问诗人也没有明写，而以“只在此山中”的童子答辞，把问句隐括在内。最后一句“云深不知处”，又是童子答复对方采药究竟在山前、山后、山顶、山脚的问题。明明三番问答，至少须六句方能表达的，贾岛采用了以答句包赅问句的手法，精简为二十字。这种“推敲”就不在一字一句间了。\n\n　　然而，这首诗的成功，不仅在于简炼；单言繁简，还不足以说明它的妙处。诗贵善于抒情。这首诗的抒情特色是在平淡中见深沉。一般访友，问知他出，也就自然扫兴而返了。但这首诗中，一问之后并不罢休，又继之以二问三问，其言甚繁，而其笔则简，以简笔写繁情，益见其情深与情切。而且这三番答问，逐层深入，表达感情有起有伏。“松下问童子”时，心情轻快，满怀希望；“言师采药去”，答非所想，一坠而为失望；“只在此山中”，在失望中又萌生了一线希望；及至最后一答：“云深不知处”，就惘然若失，无可奈何了。\n\n　　然而诗的抒情要凭借艺术形象，要讲究色调。从表面看，这首诗似乎不着一色，白描无华，是淡妆而非浓抹。其实它的造型自然，色彩鲜明，浓淡相宜。郁郁青松，悠悠白云，这青与白，这松与云，它的形象与色调恰和云山深处的隐者身份相符。而且未见隐者先见其画，青翠挺立中隐含无限生机；而后却见茫茫白云，深邃杳霭，捉摸无从，令人起秋水伊人无处可寻的浮想。从造型的递变，色调的先后中也映衬出作者感情的与物转移。\n\n　　诗中隐者采药为生，济世活人，是一个真隐士。所以贾岛对他有高山仰止的钦慕之情。诗中白云显其高洁，苍松赞其风骨，写景中也含有比兴之义。惟其如此，钦慕而不遇，就更突出其怅惘之情了。另外，作者作为一个封建社会的知识分子，离开繁华的都市，跑到这超尘绝俗的青松白云之间来“寻隐者”，其原因也是耐人寻味，引人遐想的。', poem_tags = '唐诗三百首,寻访,写人' WHERE poem_title = '寻隐者不遇 / 孙革访羊尊师诗' AND poem_author = '贾岛';
UPDATE edu_poem SET poem_tags = '爱国,忧国忧民' WHERE poem_title = '临江仙·樱桃落尽春归去' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '离别以来，春天已经过去一半，映入目中的景色掠起柔肠寸断。阶下落梅就像飘飞的白雪一样零乱，把它拂去了又飘洒得一身满满。\n鸿雁已经飞回而音信毫无依凭，路途遥远，要回去的梦也难形成。离别的愁恨正像春天的野草，越行越远它越是繁生。', poem_notes = '春半：即半春，春天的一半。别来春半：意思是，自分别以来，春天已过去一半，说明时光过得很快。\n柔肠：原指温柔的心肠，此指绵软情怀。\n砌（qì）下：台阶下。砌，台阶。落梅：指白梅花，开放较晚。全句意思是，台阶下飘落的白梅花犹如雪片纷飞。\n拂了一身还满：指把满身的落梅拂去了又落了满身。\n雁来音信无凭：这句话是说鸿雁虽然来了，却没将书信传来。古代有凭借雁足传递书信的故事。无凭：没有凭证，指没有书信。\n遥：远。归梦难成：指有家难回。\n恰如：《全唐诗》、《古今词统》、《古今诗余醉》等本中均作“却如”；毛本《尊前集》中作“怯如”。\n更行更远还生：更行更远，指行程越远。更，越。还生，还是生得很多。还，仍然，还是。', poem_appreciation = '这首《清平乐》，表现了作者在恼人的春色中，触景生情，思念离家在外的亲人的情景。\n\n　　词的上片，开篇即直抒胸臆、毫无遮拦地道出郁抑于心的离愁别恨。一个“别”字，是起意，也是点题，单刀直入，紧扣人心。李煜前期作品中因各种原因，这种开篇直抒胸臆的不多，但中、后期作品中不少，想必是生活际遇之大变，作者的感情已如洪水注池、不泄不行罢。“春半”有人释为春已过半，有理，但如释为相别半春，亦有据，两义并取也无不可。接下二句承“触目”来，“砌下落梅如雪乱”突出一个“乱”字，既写出了主人公独立无语却又心乱如麻，也写出了触景伤情景如人意的独特感受，用生动的比喻把愁情说得明白如见。“拂了一身还满”，前有“拂”字，显见有主人公克制定念的想法，但一个“满”字，却把主人公那种无奈之苦、企盼之情、思念之深刻画得至真至实。上片的画面是情景交融、虚实相生而又动静结合的，直抒胸臆中见委婉含蓄，活泼喻象中透深沉凝重。\n\n　　他之所以久久地站在花下，是因为在思念远方的亲人。“雁来”两句把思念具体化。写出作者盼信，并希望能在梦中见到亲人。古代有大雁传书的故事。西汉时，苏武出使北方，被匈奴扣留多年。但他坚贞不屈。汉昭帝派使臣要匈奴释放苏武，匈奴谎说苏武已死。使臣知苏武未死，假称皇帝曾射下大雁，雁足上系有苏武的书信说他正在匈奴的某地。匈奴听了，只得将苏武放回。所以作者说，他看到大雁横空飞过，为它没有给自己带来书信而感到失望。他又设想，和亲人在梦中相会，但“路遥归梦难成”，距离实在是太遥远了，恐怕他的亲人在梦中也难以回来。古人认为人们在梦境中往往是相通的。对方作不成“归梦”，自己也就梦不到对方了。梦中一见都不可能，思念万分之情溢于言表，从而更强烈地表现了作者的思念之切。他怀着这种心情，向远处望去，望着那遍地滋生的春草，突然发现，“离恨却如春草，更行更远还生”。“更行更远”是说无论走得多么远，自己心中的“离恨”就像那无边无际、滋生不已的春草。无论人走到哪里，它们都在眼前，使人无法摆脱。这个结句，比喻浅显生动，而且通过形象给人以离恨无穷无尽、有增无已的感觉，使这首词读起来显得意味深长。\n\n　　全词以离愁别恨为中心，线索明晰而内蕴，上下两片浑成一体而又层层递进，感情的抒发和情绪的渲染都十分到位。作者手法自然，笔力透彻，尤其在喻象上独到而别致，使这首词具备了不同凡品的艺术魅力。', poem_tags = '宋词三百首,春天,写景,思乡' WHERE poem_title = '清平乐·别来春半' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '玉箫的声音悲凉呜咽，秦娥从梦中惊醒时，秦家的楼上正挂着一弦明月。秦家楼上的下弦月，每一年桥边青青的柳色，都印染着灞陵桥上的凄怆离别。\n遥望乐游原上冷落凄凉的秋日佳节，通往咸阳的古路上音信早已断绝。西风轻拂着夕阳的光照，眼前只是汉朝留下的坟墓和宫阙。', poem_notes = '⑴此词上片伤别，下片伤逝。两宋之交邵博《邵氏闻见后录》始称之为李白之作。南宋黄升《唐宋诸贤绝妙词选》亦录于李白名下。明代以来屡有质疑者。\n⑵箫：一种竹制的管乐器。咽：呜咽，形容箫管吹出的曲调低沉而悲凉，呜呜咽咽如泣如诉。\n⑶梦断：梦被打断，即梦醒。\n⑷灞陵：在今陕西省西安市东，是汉文帝的陵墓所在地。当地有一座桥，为通往华北、东北和东南各地必经之处。《三辅黄图》卷六：“文帝灞陵，在长安城东七十里。……跨水作桥。汉人送客至此桥，折柳送别。”伤别：为别离而伤心。\n⑸乐游原：又叫“乐游园”，在长安东南郊，是汉宣帝乐游苑的故址，其地势较高，可俯视长安城，在唐代是游览之地。清秋节：指农历九月九日的重阳节，是当时人们重阳登高的节日。\n⑹咸阳古道：咸阳，秦都，在长安西北数百里，是汉唐时期由京城往西北从军、经商的要道。古咸阳在今陕西省咸阳市东二十里。唐人常以咸阳代指长安，“咸阳古道”就是长安道。音尘：一般指消息，这里是指车行走时发出的声音和扬起的尘士。\n⑺残照：指落日的光辉。\n⑻汉家：汉朝。陵阙：皇帝的坟墓和宫殿。', poem_appreciation = '此词描绘了一个女子思念爱人的痛苦心情，读来凄婉动人。古人对它评价很高，把它与《菩萨蛮·平林漠漠烟如织》一起誉为“百代词曲之祖”。\n\n　　王国维在《人间词话》称此词“以气象胜”。这首词中的气象，与人们常所说的开元（唐玄宗年号，公元713—741年）时代的“盛唐气象”已有很大不同，但它又确实是盛唐气象之一种。它博大深厚、意境开阔、气韵沉雄，又带有悲凉之气。这种“气象”在天宝（唐玄宗年号，公元742—756年）后期李白的作品《古风·一百四十年》《远别离》《夕霁杜陵登楼寄韦繇》等诗都可以看到。《夕霁杜陵登楼寄韦繇》中写道：“浮阳灭霁景，万物生秋容。登楼送远目，伏槛观群峰。原野旷超缅，关河纷错重。”与这首《忆秦娥》格调气象十分近似。杜甫天宝后期的《同诸公登慈恩寺塔》也有相类之处。胡应麟说这首词“气亦衰飒”，反映了晚唐王朝衰变的气运。其实此词似是反映了天宝后期表面上依然歌舞升平、内部危机重重的盛唐之衰。因此，这首词可能作于天宝后期。词人以比拟的手法，托秦娥抒情怀，把直观的感情与意象浑融在一起，上片由个人的忧愁写开，下片过渡到历史忧愁。\n\n　　这首词不像《菩萨蛮·平林漠漠烟如织》那样由客观景物的渲染过渡到人物内心感受的描摹。它一开始就写出人物内心的情态：呜咽的箫声把秦娥从梦中惊醒，此时，一钩残月斜映在窗前。梦虽断了，她却还似乎沉浸在梦境之中，与情人欢会，可是眼前只有这冰冷的残月陪伴看她。多少个这样的月夜，叫她黯然消魂、顾影自怜。因此，下面自然转入对“灞陵伤别”的回忆。《雍录》载：“汉世凡东出涵、潼，必自灞陵始，故赠行者于此折柳相送。”可是，柳色绿了，一年又一年，而伊人依然远隔一方，只有那鸣咽的箫声和着低声的啜泣，冰冷的残月陪伴着消瘦的倩影，葱绿的柳色句起往事的回忆。实际上这是作者以秦娥对情人的思念来表达内心对某种事物的苦思与追求，这种苦思与追求是执着的，然而又是没有结果的。\n\n　　词的上片始终纠葛在个人的悲欢离合之中，下片则出现了较大的跌宕。似乎比拟手法已不能满足感情的表达了，词人要撇开先前的主体，直接把自己融入画面之中。换头处突兀以“乐游原上清秋节”起，画面是清秋节佳侣如云的狂欢时景，可是主人公茕茕孑立在西风残照之中，“此身饮罢无归处，独立苍茫自咏诗”（杜甫《乐游园歌》）。此时，个人的忧愁完全被抛开了，或者说融入了历史的忧愁之中，词人通过对秦、汉那样赫赫王朝的遗迹——咸阳古道、汉代陵墓的掇取，从而进入了历史的反思。古道悠悠，音尘杳然，繁华、奢侈、纵欲，一切都被埋葬了，只剩下陵墓相伴着萧瑟的西风，如血的残阳，百年、千年地存在下去。作者不是在凭吊秦皇汉武，他是在反思历史和现实。这里交杂着盛与衰、古与今、悲与欢的反思。词人固然没有正面写唐王朝的苟且繁华，但“乐游原上清秋节”这就足够了，这使人自然想象到天宝后期那种古罗马式的穷奢极欲和狂欢极乐。可没有人能从中去体会那潜在的破碎感。秦代、汉代过去了，只剩下悠悠的古道和孤独的陵墓，面对着西风残照。这固然是过去的遗迹，然而它又是实实在在的实景，同时，这“西风残照、汉家陵阙”的实景又必然使人联系到王朝的未来。于是，过去、现在、未来的界限被取消了，浑融在一起，历史的时序给人们留下的只是一种表象——“西风残照，汉家陵阙”。造成一种悲壮的历史消亡感，或者说是毁灭感，填塞在人们心头，这就是历史反思的结果。因而上片的个人忧愁只能被取代，作为下片的陪衬。\n\n　　此词意境博大开阔，风格宏妙浑厚。读者从敦煌曲子词中也可以看到类似格调，而不类中晚唐的清婉绮丽。陆游说：“唐自大中以后，诗家日趋浅薄，其间不复有前辈宏妙浑厚之作。”（《花间集跋》）。诗风与词风自身存在着交错否定之趋势。\n\n　　此词句句自然，而字字锤炼，沉声切响，掷地真作金石声。而抑扬顿挫，法度森然，无字荒率空泛，无一处逞才使气。以此而言，设为李太白之色，毋宁认是杜少陵之笔。其风格诚在五代花间未见，亦非歌席诸曲之所能拟望，已开宋代词之格调。', poem_tags = '宋词三百首,豪放,女子,思念,忧愁' WHERE poem_title = '忆秦娥·箫声咽' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '说它是花不是花，说它是雾吗不是雾。\n半夜时到来，天明时离去。\n来时仿佛短暂而美好的春梦？\n离去时又像清晨的云彩无处寻觅。', poem_notes = '花非花：《花非花》之成为词牌始于此诗。\n来如：来时。\n几多时：短暂美好的。\n去似：去了以后，如早晨飘散的云彩，无处寻觅。\n朝（zhāo）云：此借用楚襄王梦巫山神女之典故。', poem_appreciation = '白居易诗不仅以语言浅近著称，其意境亦多显露。这首“花非花”却颇有些“朦胧”味儿，在白诗中确乎是一个特例。\n\n　　诗取前三字为题，近乎“无题“。首二句应读作“花——非花，雾——非雾”，先就给人一种捉摸不定的感觉。“非花”、“非雾”均系否定，却包含一个不言而喻的前提：似花、似雾。因此可以说，这是两个灵巧的比喻。苏东坡似从这里获得一丝灵感，写出了“似花还似非花，也无人惜从教坠”（《水龙吟》）的名句。苏词所咏为杨花柳絮，而白诗所咏何物未尝显言。但是，从“夜半来，天明去”的叙写，可知这里取喻于花与雾，在于比方所咏之物的短暂易逝，难持长久。\n\n　　单看“夜半来，天明去”，颇使读者疑心是在说梦。但从下句“来如春梦”四字，可见又不然了。“梦”原来也是一比。这里“来”、“去”二字，在音情上有承上启下作用，由此生发出两个新鲜比喻。“夜半来”者春梦也，春梦虽美却短暂，于是引出一问：“来如春梦几多时？”“天明”见者朝霞也，云霞虽美却易幻灭，于是引出一叹：“去似朝云无觅处”。\n\n　　诗由一连串比喻构成，这叫博喻。它们环环紧扣，如云行水流，自然成文。反复以鲜明的形象突出一个未曾说明的喻意。诗词中善用博喻者不乏其例，如《古诗十九首》（明月皎夜光）之“南箕北有斗，牵牛不负轭”，贺铸《青玉案》的“一川烟草，满城风絮，梅子黄时雨”。但这些博喻都不过是诗词中一个组成部分，象此诗通篇用博喻构成则甚罕见。再者，前一例用南箕、北斗、牵牛等星象作比，喻在“嘘名复何益”；后一例用烟草、风絮、梅雨等景象作比，喻在“借问闲悉都几许”，其喻本（被喻之物）都是明确的。而此诗只见喻体（用作比喻之物）而不知喻本，就象一个耐人寻思的谜。从而诗的意境也就蒙上一层“朦胧“的色彩了。\n\n　　虽说如此，但此诗诗意却并不完全隐晦到不可捉摸。它被作者编在集中“感伤“之部，同部还有情调接近的作品。一是《真娘墓》，诗中写道：“霜摧桃李风折莲，真娘死时犹少年。脂肤荑手不坚固，世间尤物难留连。难留连，易销歇，塞北花，江南雪。”另一是《简简吟》，诗中写到：“二月繁霜杀桃花，明年欲嫁今年死”，“大都好物不坚牢，彩云易散琉璃碎”，二诗均为悼亡之作，它们末句的比喻，尤其是那“易销歇”的“塞北花”和“易散”的“彩云”，与此诗末二句的比喻几乎一模一样，连音情都逼肖的，它们都同样表现出一种对于生活中存在过、而又消逝了的美好的人与物的追念、惋惜之情。而《花非花》一诗在集中紧编在《简简吟》之后，更告诉读者关于此诗归趣的一个消息。此诗大约与《简简吟》同时为同一目的所作吧。\n\n　　此诗运用三字句与七字句轮换的形式（这是当时民间歌谣三三七句式的活用），兼有节律整饬与错综之美，极似后来的小令。所以后人竟采此诗句法为词调，而以“花非花”为调名。词对五七言诗在内容上的一大转关，就在于更倾向于人的内在心境的表现。在这点上，此诗也与词相近。这种“诗似小词”的现象，出现在唐代较早从事词体创作的诗人白居易笔下，原是很自然的。', poem_tags = '宋词三百首,人生,感悟' WHERE poem_title = '花非花' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '今夜鄜州月亮，一定同样清圆，遥想闺中妻子，只能独自观赏。\n可怜幼小的儿女，怎懂思念的心酸？\n蒙蒙雾气，或许沾湿了妻子的鬓发；冷冷月光，该是映寒了妻子的玉臂。\n何时才能团圆相见，倚靠薄帷共赏明月。那时一定月色依旧，就让月光默默照干我们的泪痕。', poem_notes = '鄜（fū）州：今陕西省富县。当时杜甫的家属在鄜州的羌村，杜甫在长安。\n闺中：内室。看，读平声kān。\n怜：想。\n未解：尚不懂得。\n香雾云鬟（huán）湿，清辉玉臂寒：写想象中妻独自久立，望月怀人的形象。香雾：雾本来没有香气，因为香气从涂有膏沐的云鬟中散发出来，所以说“香雾”。望月已久，雾深露重，故云鬟沾湿，玉臂生寒。云鬟：古代妇女的环形发饰。\n清辉：阮籍诗《咏怀》其十四：“明月耀清晖。”\n虚幌：透明的窗帷。幌，帷幔。\n双照：与上面的“独看“对应，表示对未来团聚的期望。泪痕：隋宫诗《叹疆场》“泪痕犹尚在。”', poem_appreciation = '这首诗借看月而抒离情，但抒发的不是一般情况下的夫妇离别之情。字里行间，表现出时代的特征，离乱之痛和内心之忧熔于一炉，对月惆怅，忧叹愁思，而希望则寄托于不知“何时”的未来。\n\n　　在一二两联中，“怜”字，“忆”字，都不宜轻易滑过。而这又应该和“今夜”、“独看”联系起来加以吟味。明月当空，月月都能看到。特指“今夜”的“独看”，则心目中自然有往日的“同看”和未来的“同看”。未来的“同看”，留待结句点明。往日的“同看”，则暗含于一二两联之中。“今夜鄜州月，闺中只独看。遥怜小儿女，未解忆长安。” 这透露出他和妻子有过“同看”鄜州月而共“忆长安”的往事。安史之乱以前，作者困处长安达十年之久，其中有一段时间，是与妻子在一起度过的。和妻子一同忍饥受寒，也一同观赏长安的明月，这自然就留下了深刻的记忆。当长安沦陷，一家人逃难到了羌村的时候，与妻子“同看”鄜州之月而共“忆长安”，已不胜其辛酸。如今自己身陷乱军之中，妻子“独看”鄜州之月而“忆长安”，那“忆”就不仅充满了辛酸，而且交织着忧虑与惊恐。这个“忆”字，是含意深广，耐人寻思的。往日与妻子同看鄜州之月而“忆长安”，虽然百感交集，但尚有自己为妻子分忧；如今呢，妻子“独看”鄜州之月而“忆长安”，“遥怜”小儿女们天真幼稚，只能增加她的负担，不能为她分忧。这个“怜”字，也是饱含深情，感人肺腑的。孩子还小，并不懂得想念，但杜甫不能不念。从小孩的“不念”更能体现出大人的“念”之深切。\n\n　　第三联通过妻子独自看月的形象描写，进一步表现“忆长安”。雾湿云鬟，月寒玉臂。望月愈久而忆念愈深，这完全是作者想象中的情景。当想到妻子忧心忡忡，夜深不寐的时候，自己也不免伤心落泪。两地看月而各有泪痕，这就激起了作者结束这种痛苦生活的希望；于是以表现希望的诗句作结：“何时倚虚幌，双照泪痕干？”“双照”而泪痕始干，则“独看”而泪痕不干，也就意在言外了。\n\n　　题为“月夜”，字字都从月色中照出，而以“独看”、“双照”为一诗之眼。“独看”是现实，却从对面着想，只写妻子“独看”鄜州之月而“忆长安”，而自己的“独看”长安之月而忆鄜州，已包含其中。“双照”兼包回忆与希望：感伤“今夜”的“独看”，回忆往日的同看，而把并倚“虚幌”（薄帷）、对月抒愁的希望寄托于不知“何时”的未来。采用这种从对方设想的方式，妙在从对方那里生发出自己的感情，这种方法尤被后人当作法度。全词词旨婉切，章法紧密，明白如话，感情真挚，没有被律诗束缚的痕迹。', poem_tags = '唐诗三百首,高中古诗,月亮,思念,女子' WHERE poem_title = '月夜' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '明明是一生一世，天作之合，却偏偏不能在一起，两地分隔。\n整日里，相思相望，而又不得相亲，枉教得凄凉憔悴，黯然销魂。\n不知道上苍究竟为谁，造就这美丽青春。一为裴航，乞浆蓝桥，而得妻云英；一为嫦娥，窃不死药，而飞奔月宫。\n如果能够像牛郎织女一样，于天河相见，即使抛却荣华富贵也心甘。', poem_notes = '争教：怎教。销魂，形容极度悲伤、愁苦或极度欢乐。\n蓝桥：地名。在陕西蓝田县东南蓝溪上，传说此处有仙窟，为裴航遇仙女云英处。此处用这一典故是表明自己的“蓝桥之遇”曾经有过，且不为难得。\n药成句：这里借用此典说，纵有不死之灵药，但却难像嫦娥那样飞入月宫去。意思是纵有深情却难以相见。\n饮牛津：这里是借指与恋人相会的地方。', poem_appreciation = '上片化用成句，说相亲相爱的“一双人”无端被拆散。不曾交代相关故事，也没有具体情节。下片以“故事”说故事，借古老传说，为透露消息。\n\n　　劈头便是“一生一代一双人，争教两处销魂”，明白如话，更无丝毫的妆点；素面朝天，为有天姿的底蕴。这样的句子，并不曾经过眉间心上的构思、语为惊人的推敲、诗囊行吟的揣摩，不过是脱口而出，再无其他道理。\n\n　　下片转折，接连用典。小令一般以频繁用典为大忌，此为通例，而才子手笔，再多的禁忌也要退避三舍。\n\n　　用典很讲究，也很完美。连用典而显不生涩，丝毫没有堆砌的感觉。这两个典故又是截然相反的意思，用在一起不冲突，还有互相推动的感觉，丰富了词义，这是难得的。我一向主张，诗词要么就少用典，没那功力别急着显摆，要用就用到大音若稀，大象无形的境界，干干脆脆融汇贯通。\n\n　　结句则采用了中国诗词用典时暗示的力量。容若有意让词意由“饮牛津“过渡到“牛衣对泣“容若乃权相之子，本不贫，现在用“相对忘贫“之语，无非说如果我能同她相见，一个像牛郎，一个像织女，便也可以相对忘言了。如若能结合，便是做睡在牛衣中的贫贱夫妇，我们也满足。', poem_tags = '典故,伤怀,相思' WHERE poem_title = '画堂春·一生一代一双人' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '中秋的月光照射在庭院中，地上好像铺上了一层霜雪那样白，树上的鸦雀停止了聒噪，进入了梦乡。\n夜深了，清冷的秋露悄悄地打湿庭中的桂花。今夜，明月当空，人们都在赏月，不知那茫茫的秋思落在谁家？', poem_notes = '⑴十五夜：指农历八月十五的晚上，即中秋夜。杜郎中，名杜元颖。\n⑵中庭：即庭中，庭院中。\n⑶地白：指月光照在庭院的样子。\n⑷鸦：鸦雀。\n⑸冷露：秋天的露水。\n⑹尽：都。\n⑺秋思：秋天的情思，这里指怀人的思绪。\n⑻落：在，到。', poem_appreciation = '这是一首中秋之夜望月思远的七言绝句。在民俗中，中秋节的形成历史悠久。诗人望月兴叹，但写法与其他中秋咏月诗完全不同，很有创造性，甚至更耐人回味。\n\n　　“中庭地白树栖鸦”，明写赏月环境，暗写人物情态，精炼而含蓄。这句如同马致远的《天净沙·秋思》首句一样，借助特有的景物一下子就将萧瑟苍凉之景推到读者眼前，予人以难忘的印象。诗人写中庭月色，只用“地白”二字，却给人以积水空明、澄静素洁、清冷之感，联想到李白的名句“床前明月光，疑是地上霜”，沉浸在清美的意境之中。“树栖鸦”，应该是听出来的，而不是看到的。因为即使在明月之夜，人们也不大可能看到鸦鹊的栖宿；而鸦鹊在月光树荫中从开始的惊惶喧闹到最后的安定入睡，却完全可能凭听觉感受出来。（周邦彦《蝶恋花·早行》词有“月皎惊乌栖不定”句，就是写这种意境。）“树栖鸦”这三个字，朴实、简洁、凝炼，既写了鸦鹊栖树的情状，又烘托了月夜的寂静。全句无一字提到人，而又使人处处想到清宵的望月者。\n\n　　“冷露无声湿桂花”，紧承上句，借助感受进一步渲染中秋之夜。这句诗因桂香袭人而发。在桂花诸品中，秋桂香最浓。在皎洁的月亮上某些环形火山的阴影曾使富于幻想的人赋予它美好的形象，说它是月宫里的桂树，有的传说还说人间的桂树是天上落下来的种子生成的（宋之问《灵隐寺》“桂子月中落，天香云外飘”）。这句诗描写了冷气袭人，桂花怡人的情景。如果进一步揣摩，更会联想到这桂花可能是指月中的桂树。这是暗写诗人望月，正是全篇点题之笔。诗人在万籁俱寂的深夜，仰望明月，凝想入神，丝丝寒意，轻轻袭来，不觉浮想联翩：那广寒宫中，清冷的露珠一定也沾湿了桂花树。这样，“冷露无声湿桂花”的意境，就显得更悠远，更耐人寻思。诗人选取“无声”二字，细致地表现出冷露的轻盈无迹，又渲染了桂花的浸润之久。而且不只是桂花，那树下的玉兔，那挥斧的吴刚，那“碧海青天夜夜心”的嫦娥，也是如此。古人以为霜露之类似雨雪都从天而降，因而诗人探桂时奇怪冰凉的露水把花枝沁得这么湿却没听到一点声音。如此落笔，既写出了一个具体可感的中秋之夕，又表现了夜之深和静，似乎桂香与寒气袭人而来了，带给人以美的联想。\n\n　　“今夜月明人尽望，不知秋思落谁家。”这两句采取了忽然宕开的写法，从作者的一群人的望月联想到天下人的望月，又由赏月的活动升华到思人怀远，意境阔大，含蓄不露。普天之下又有多少人在望月思亲：在家乡的人思念远离的亲人，离乡之人遥望家乡亲人。于是，水到渠成，吟出了这两句。前两句写景，不带一个“月”字；第三句才点明望月，而且推己及人，扩大了望月者的范围。但是，同是望月，那感秋之意，怀人之情，却是人各不同的。诗人怅然于家人离散，因而由月宫的凄清，引出了入骨的相思。他的“秋思”必然是最浓挚的。然而，在表现的时候，诗人却并不采用正面抒情的方式，直接倾诉自己的思念之切；而是用了一种委婉的疑问语气：不知那茫茫的秋思会落在谁的一边。天下离人千千万万，怀人愁绪如绵绵秋草，逐处丛生；诗人在思谁是确定的，说“不知秋思落谁家”并非真不知，而是极写秋思的浩茫浑涵，似虚而实，深得诗歌含蓄之美。明明是自己在怀人，偏偏说“秋思落谁家”，这就将诗人对月怀远的情思，表现得蕴藉深沉。似乎秋思唯诗人独有，别人尽管也在望月，却并无秋思可言。这真是无理之极，然而愈显出诗人痴情，手法高妙。在炼字上，“落”字新颖妥贴，不同凡响，它给人以生动形象的感觉，仿佛那秋思随着银月的清辉，一齐洒落人间。\n\n　　这首诗意境很美，首先予人的印象是情景如画，用苏轼的话来说就是“诗中有画”。明《唐诗画谱》中就有以这首诗为题材的版画，但这幅版画仅是画家别出心裁构想出的意境，和王建原作并不一一吻合，而且它对全诗点睛之笔——秋思未作充分表达。在这一点上，诗歌语言艺术显示了它的不可代替性。诗人运用形象的语言，丰美的想象，渲染了中秋望月的特定的环境气氛，把读者带进一个月明人远、思深情长的意境，加上一个唱叹有神、悠然不尽的结尾，将别离思聚的情意，表现得委婉动人。', poem_tags = '中秋节,月亮,思乡' WHERE poem_title = '十五夜望月寄杜郎中' AND poem_author = '王建';
UPDATE edu_poem SET poem_translation = '春风吹回来了，庭院里的杂草变绿了，柳树也生出了嫩叶，一年又一年的春天继续来到人间。独自依靠着栏杆半天没有话说，那吹箫之声和刚刚升起的月亮和往年差不多。\n乐曲演奏未完，酒宴未散，仍在继续，池水冰面初开。夜深之时，华丽而精美的君室也变得幽深。我已年老，忧思难以承受啊。', poem_notes = '⑴虞美人：词牌名。原为唐教坊曲，初咏项羽宠姬虞美人，因以为名。又名《一江春水》、《玉壶水》、《巫山十二峰》等。双调，五十六字，上下片各四句，皆为两仄韵转两平韵。\n⑵风：指春风。庭芜：庭院里的草。芜，丛生的杂草。\n⑶柳眼：早春时柳树初生的嫩叶，好像人的睡眼初展，故称柳眼。李商隐《二月二日》诗中有“花须柳眼多无赖，紫蝶黄蜂俱有情”之句。春相续：一年又一年的春天继续来到人间。\n⑷凭阑：靠着栏杆。\n⑸竹声：竹制管乐器发出的声音。竹，古乐八晋之一，指竹制管乐器，箫、管、笙、笛之类。一说“竹声”为风吹竹叶之声。\n⑹笙歌：泛指奏乐唱歌，这里指乐曲。尊罍（léi）在：意谓酒席未散，还在继续。尊罍，一作“尊前”。尊，酒杯，罍，一种酒器，小口大肚，有盖，上部有一对环耳，下部有一鼻可系。\n⑺池面冰初解：池水冰面初开，指时已初春。\n⑻烛明香暗：是指夜深之时。香，熏香。画堂：一作“画歌”，一作“画楼”；一作“画阑”。指华丽而精美的君室。深：一作“声”，指幽深。\n⑼清霜残雪：形容鬓发苍白，如同霜雪，谓年已衰老。思难任（rèn）：忧思令人难以承受，即指极度忧伤。思，忧思。难任，难以承受。任：一作“禁”。', poem_appreciation = '开头称春风又回到小院里来，院子里的草又绿了。院子里的柳条上新生柳叶，细长如人睡眼初展，这样的柳叶在春天到来时，连续着生出来。这里写出小院中春天的信息，可以从庭草的绿色里，从柳叶的舒展和相续生出中看出来。“柳眼春相续”，写得很细，是诗人的观察。这里也透露出他的寂寞之感来。他在《玉楼春》里写在金陵时的春天景象：“晚妆初了明肌雪，春殿嫔娥鱼贯列。凤箫吹断水云闲，重按霓裳歌遍彻。”是盛极一时，跟被拘留中的寂寞正好构成对照。想起当日的情况，靠着栏杆半天没有一句话，透露他对故国之思的痛苦心情。这时想替自己排解，说风吹竹子的声音和新月的照耀还象当年。想来小院中还有竹子，春风吹来，还有竹声。不过跟《玉楼春》写的“醉拍阑干情味切”相比，这时的“半日独无言”又构成鲜明的对照了。\n\n　　下半片写他在赐第里还有故妓，还可以奏乐。笙歌未散，酒杯还在，还可以喝酒。春天到来，池面冰开始融化了。就他的处境来说，也许也像东风解冻。“烛明香暗画堂深，满鬓清霜残雪思难任。”用“烛明香暗”来陪衬“画堂深”，用“满鬓清霜残雪”的霜雪来反衬东风解冻的“冰初解”。“画堂深”是深沉，看来故妓的奏乐也是寂寞中的聊以自慰，不能跟“凤箫吹断水云闲，重按霓裳歌遍彻”相比，所以无法解除寂寞，因此有画堂深沉的感觉。东风解冻透露春天的气息，但对他说来，春天永远过去了，这表现在四十岁光景的人已经是满鬓霜雪了，这里含有对故国的怀念、亡国的痛苦难以负担。这首词，结合被俘后的生活来反映故国之思，写春天的到来，东风的解冻，都无法减轻他的痛苦。', poem_tags = '宋词三百首,春天,写景,怀旧' WHERE poem_title = '虞美人·风回小院庭芜绿' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '采呀采呀采卷耳，半天不满一小筐。我啊想念心上人，菜筐弃在大路旁。\n攀那高高土石山，马儿足疲神颓丧。且先斟满金壶酒，慰我离思与忧伤。\n登上高高山脊梁，马儿腿软已迷茫。且先斟满大杯酒，免我心中长悲伤。\n艰难攀登乱石冈，马儿累坏倒一旁，仆人精疲力又竭，无奈愁思聚心上！', poem_notes = '⑴采采：采了又采。卷耳：苍耳，石竹科一年生草本植物，嫩苗可食，子可入药。\n⑵盈：满。顷筐：斜口筐子，后高前低。一说斜口筐。这句说采了又采都采不满浅筐子，心思不在这上头。\n⑶嗟：语助词，或谓叹息声。怀：怀想。\n⑷寘（zhì）：同“置”，放，搁置。周行（háng）：环绕的道路，特指大道。索性把筐子放在大路上，于是眼前出现了她丈夫在外的情景。\n⑸陟：升；登。彼：指示代名词。崔嵬（wéi）：山高不平。\n⑹我：想象中丈夫的自称。虺隤（huī tuí）：疲极而病。\n⑺姑：姑且。酌：斟酒。金罍（léi）：金罍，青铜做的罍。罍，器名，青铜制，用以盛酒和水。\n⑻维：发语词，无实义。永怀：长久思念。\n⑼玄黄：黑色毛与黄色毛相掺杂的颜色。朱熹说“玄马而黄，病极而变色也”，就是本是黑马，病久而出现黄斑。\n⑽兕觥（sì gōng）：一说野牛角制的酒杯，一说“觥”是青铜做的牛形酒器。\n⑾永伤：长久思念。\n⑿砠（jū）：有土的石山，或谓山中险阻之地。\n⒀瘏（tú）：因劳致病，马疲病不能前行。\n⒁痡（pū）：因劳致病，人过劳不能走路。\n⒂云：语助词，无实义。云何：奈何，奈之何。吁（xū）：忧伤而叹。', poem_appreciation = '《卷耳》是一篇抒写怀人情感的名作。其佳妙处尤其表现在它匠心独运的篇章结构上。旧说如“后妃怀文王”“文王怀贤”“妻子怀念征夫”“征夫怀念妻子”诸说，都把诗中的怀人情感解释为单向的；另外，日本的青木正儿和中国的《诗经》专家孙作云还提出过《卷耳》是由两首残简的诗合为一诗的看法。这些看法反映出对《卷耳》篇章佳妙布局认识不足的缺陷。\n\n　　《卷耳》四章，第一章是以思念征夫的妇女的口吻来写的；后三章则是以思家念归的备受旅途辛劳的男子的口吻来写的。犹如一场表演着的戏剧，男女主人公各自的内心独白在同一场景同一时段中展开。诗人坚决地隐去了“女曰”“士曰”一类的提示词，让戏剧冲突表现得更为强烈，让男女主人公“思怀”的内心感受交融合一。首章女子的独白呼唤着远行的男子，“不盈顷筐”的卷耳被弃在“周行”——通向远方的大路的一旁。顺着女子的呼唤，备受辛苦的男子满怀愁思地出现；对应着“周行”，他正行进在崔嵬的山间。一、二两章的句式结构也因此呈现着明显的对比和反差。第三章是对第二章的复沓，带有变化的复沓是《诗经》中最常见的章法结构特征，这种复沓可以想象为是一种合唱或重唱，它强有力地增加了抒情的效果，开拓补充了意境，稳定地再现了音乐的主题旋律。第四章从内容分析仍是男子口吻，但与二、三章相差很大。这类《诗经》中经常用的手法称为单行章断，比如《召南·采蘩》《召南·行露》《周南·葛覃》《周南·汉广》《周南·汝坟》等诗中都有此类手法。这类手法是合唱形式的遗存，可以想像这是幕后回荡的男声合唱。其作用是渲染烘托诗篇的气氛，增强表演的效果。\n\n　　《卷耳》的语言是优美自然的。诗人能够熟练地运用当时的民谣套语。《周易·归妹三·上六》：“女承筐，无实；士刲羊，无血。”“女承筐，无实”正与《卷耳》首句“采采卷耳，不盈顷筐”对应。把民谣用作套语，像一个套子一样放在诗章句首，为诗奠定韵脚、句式的基础和情感思绪的习惯性暗示，这是《诗经》的起兴手法的一例。诗人善于用实境描画来衬托情感。旅途的艰难是通过对山的险阻的描摹直接反映出来的：诗人用了“崔嵬”“高冈”“砠”等词语。而旅途的痛苦则是通过对马的神情的刻画间接表现出来的：诗人用了“虺隤”“玄黄”“瘏矣”等词语。而描摹山、刻画马都意在衬托出行者怀人思归的惆怅。“我姑酌彼金罍”“我姑酌彼兕觥”，以酒浇愁，便是正面对这种悲愁的心态提示。全诗的最后是以一种已类化的自问自答体收场的：“云何？吁矣！”它既是对前两章“不永怀”“不永伤”的承接，也是以“吁”一字对全诗进行的总结，点名“愁”的主题，堪称诗眼。\n\n　　怀人是世间永恒的情感主题，这一主题跨越了具体的人和事，它本身成了历代诗人吟咏的好题目。《卷耳》为中国诗歌长河中蔚为壮观的一支——怀人诗开了一个好头。其深远影响光泽后世。徐陵《关山月》、张仲素《春归思》、杜甫《月夜》、王维《九月九日忆山东兄弟》、元好问《客意》等抒写离愁别绪、怀人思乡的诗歌名篇，多多少少体现了与《卷耳》一脉相承的意味。', poem_tags = '诗经,怀人' WHERE poem_title = '卷耳' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '依旧是秦汉时期的明月和边关，守边御敌鏖战万里征人未回还。\n倘若攻袭龙城的卫青和飞将军李广而今健在，绝不许匈奴南下牧马度过阴山。\n\n将军刚跨上配了白玉鞍的宝马出战，战斗结束后战场上只剩下凄凉的月色。\n城头上的战鼓还在旷野里震荡回响，将军刀匣里的宝刀上的血迹仍然没干。', poem_notes = '1.但使：只要。\n2.龙城飞将：《汉书·卫青霍去病传》载，元光六年（前129年），卫青为车骑将军，出上谷，至笼城，斩首虏数百。笼城，颜师古注曰：“笼”与“龙”同。龙城飞将指的是卫青奇袭龙城的事情。其中，有人认为龙城飞将中飞将指的是汉飞将军李广，龙城是唐代的卢龙城（卢龙城就是汉代的李广练兵之地，在今河北省喜峰口附近一带，为汉代右北平郡所在地），纵观李广一生主要的时间都在抗击匈奴，防止匈奴掠边，其中每次匈奴重点进攻的汉地天子几乎都是派遣李广为太守，所以这种说法也不无道理。\n3.不教：不叫，不让。教，让。\n4.胡马：指侵扰内地的外族骑兵。\n5.度：越过。在漫长的边防线上，战争一直没有停止过，去边防线打仗的战士也还没有回来。要是攻袭龙城的大将军卫青和飞将军李广今天还依然健在，绝不会让敌人的军队翻过阴山。\n6.阴山：昆仑山的北支，起自河套西北，横贯绥远、察哈尔及热河北部，是中国北方的屏障。\n7.骝马：黑鬣黑尾巴的红马，骏马的一种。新：刚刚。\n8.沙场：指战场。\n9.震：响。', poem_appreciation = '其一\n\n　　这是一首慨叹边战不断，国无良将的边塞。\n\n　　诗从写景入手。首句“秦时明月汉时关”七个字，即展现出一幅壮阔的图画：一轮明月，照耀着边疆关塞。诗人只用大笔勾勒，不作细致描绘，却恰好显示了边疆的寥廓和景物的萧条，渲染出孤寂、苍凉的气氛。尤为奇妙的是，诗人在“月”和“关”的前面，用“秦汉时”三字加以修饰，使这幅月临关塞图，变成了时间中的图画，给万里边关赋予了悠久的历史感。这是诗人对长期的边塞战争作了深刻思考而产生的“神来之笔”。\n\n　　面对这样的景象，边人触景生情，自然联想起秦汉以来无数献身边疆、至死未归的人们。“万里长征人未还”，又从空间角度点明边塞的遥远。这里的“人”，既是指已经战死的士卒，也指还在戍守不能回归的士卒。“人未还”，一是说明边防不巩固，二是对士卒表示同情。这本是一个问题的两个方面，前者是因，后者是果。这是从秦到汉乃至于唐代，都没有解决的大问题。于是在第三、四两句，诗人给出了回答。\n\n　　“但使龙城飞将在，不教胡马度阴山”两句，融抒情与议论为一体，直接杆发戍边战士巩固边防的愿望和保卫国家的壮志，洋溢着爱国激情和民族自豪感。写得气势豪迈，铿锵有力。同时，这两句又语带讽刺，表现了诗人对朝廷用人不当和将帅腐败无能的不满。有弦外之音，使人寻味无穷。\n\n　　这首诗虽然只有短短四行，但是通过对边疆景物和征人心理的描绘，表现的内容是复杂的。既有对久戍士卒的浓厚同情和结束这种边防不顾局面的愿望；又流露了对朝廷不能选贤任能的不满，同时又以大局为重，认识到战争的正义性，因而个人利益服从国家安全的需要，发出了“不教胡马度阴山”的誓言，洋溢着爱国激情。\n\n　　诗人并没有对边塞风光进行细致的描绘，他只是选取了征戍生活中的一个典型画面来揭示士卒的内心世界。景物描写只是用来刻划人物思想感情的一种手段，汉关秦月，无不是融情入景，浸透了人物的感情色彩。把复杂的内容熔铸在四行诗里，深沉含蓄，耐人寻味。\n\n其二\n\n　　这首诗描写了一惊心动魄的战斗刚刚结束的情景。枣红马刚刚装上白玉装饰的马鞍，战士就骑着它出发了。战斗结束的时候天已经很晚，战场上只留下寒冷的月光。城头上催战的鼓声仍在旷野上回荡，刀鞘里的钢刀血迹未干。诗人用寥寥数笔，就把将士们的英武气概，胜利者的神态生动地描绘出来。\n\n　　骅骝骏马，是再好不过的马了，还要给它配上再美不过的白玉鞍桥，可以想见这马上骑手的威风。这英武的骑士是手持“金刀”（即金错刀）奋战沙场的。这骑士披一身月色，顶凛冽寒风，鏖战而归。但他全副精神仍沉浸在烟尘滚滚的沙场，那咚咚的进击鼓声还响彻耳畔。这风度轩昂、勇武不凡、充满自信的骑士，就是诗人心目中唐军将官的形象，也是诗人矢志抗敌、无时无刻不意欲拼搏战场的心灵写照。“城头铁鼓声犹震，匣里金刀血未干。”这实在是一个坚定的爱国者从耿耿赤心发出的雄壮的呐喊，也分明寄寓着诗人的殷切希望。\n\n　　这首诗抒写自信、进取、开拓为特征的传统尚武精神，风格刚健、清新。诗人描写战争的胜利，不在于字面，而在于构成一种气氛。诗歌选取战斗生活的一个片段，以“骝马”“沙场”“铁鼓”“金刀”等战争意象串成一系列战斗生活的画面，战斗的激烈与战场的肃杀尽在其中。诗头“新跨”一词将战士风风火火、迎接战斗的激情表达得淋漓尽致，而诗尾以“血未干”这样一幅看似血腥的场景描写战士的内心——热血并未因为战斗的结束而冷却。这种激烈肃杀的气氛，生动地表现出战士的飒爽英姿和激昂振奋的风貌。\n\n　　作者在这首诗中抓住战斗刚刚结束的场面加以描写，塑造了一个英姿飒爽、勇猛善战的将军形象，热情地歌颂了将士们为国杀敌立功的勇敢精神。\n\n　　诗人描写胜利，不在于字面，而在于构成一种气氛。把战士的飒爽英姿，激昂振奋的风貌写了出来。', poem_tags = '边塞,写景,叙事,战争,抒情,组诗' WHERE poem_title = '出塞二首' AND poem_author = '王昌龄';
UPDATE edu_poem SET poem_translation = '南唐开国已有四十年历史，幅员辽阔。宫殿高大雄伟，可与天际相接，宫苑内珍贵的草木茂盛，就像罩在烟雾里的女萝。在这种奢侈的生活里，我哪里知道有战争这回事呢？\n自从做了俘虏，我因为在忧虑伤痛的折磨中过日子而腰肢减瘦、鬓发斑白。最使我记得的是慌张地辞别宗庙的时候，宫廷里的音乐机关/教坊的乐工们还奏起别离的歌曲，这种生离死别的情形，令我悲伤欲绝，只能面对宫女们垂泪而已。', poem_notes = '破阵子：词牌名。\n四十年：南唐自建国至李煜作此词，为三十八年。此处四十年为概数。\n凤阁：别作“凤阙”。凤阁龙楼指帝王能够居所。霄汉：天河。\n玉树琼枝：别作“琼枝玉树”，形容树的美好。烟萝：形容树枝叶繁茂，如同笼罩着雾气。\n识干戈：经历战争。识，别作“惯”。干戈：武器，此处指代战争。\n沈腰潘鬓：沈指沈约。后用沈腰指代人日渐消瘦。潘：指潘岳。后以潘鬓指代中年白发。\n辞庙：辞，离开。庙，宗庙，古代帝王供奉祖先牌位的地方。\n犹奏：别作“独奏”。\n垂泪：别作“挥泪”。', poem_appreciation = '此词上片写南唐曾有的繁华，建国四十余年，国土三千里地，居住的楼阁高耸入云霄，庭内花繁树茂。这片繁荣的土地，几曾经历过战乱的侵扰。几句话，看似只是平平无奇的写实，但却饱含了多少对故国的自豪与留恋。“几曾识干戈”，更抒发了多少自责与悔恨。下片写国破。“一旦”二字承上片“几曾”之句意，笔锋一叠，而悔恨之意更甚。终有一天国破家亡，人不由得消瘦苍老，尤其是拜别祖先的那天，匆忙之中，偏偏又听到教坊里演奏别离的曲子，又增伤感，不禁面对宫女恸哭垂泪。\n\n　　“沈腰”暗喻自己像沈约一样，腰瘦得使皮革腰带常常移孔，而“潘鬓”则暗喻词人自己像潘岳一样，年纪不到四十就出现了鬓边的白发。连着这两个典故，描写词人内心的愁苦凄楚，人憔悴消瘦，鬓边也开始变白，从外貌变化写出了内心的极度痛苦。古人说忧能伤人，亡国之痛，臣虏之辱，使得这个本来工愁善感的国君身心俱敝。李煜被俘之后，日夕以眼泪洗面，过着含悲饮恨的生活。这两个典故即是他被虏到汴京后的辛酸写照。\n\n　　此词上片写繁华，下片写亡国，由建国写到亡国，极盛转而极衰，极喜而后极悲。中间用“几曾”“一旦”二词贯穿转折，转得不露痕迹，却有千钧之力，悔恨之情溢于言表。作者以阶下囚的身份对亡国往事作痛定思痛之想，自然不胜感慨系之。此词回顾事国时的繁华逸乐：那四十年来的家国基业；三千里地的辽阔疆域，竟都沉浸在一片享乐安逸之中。“几曾识干戈”既是其不知珍惜的结果，同时也是沦为臣虏的原因。记叙离别故国时哭辞宗庙的情景，写来尤为沉痛惨怛。其事虽见载于《东坡志林》但出自后主之手，更觉凄惨苦涩，不失为一个丧国之君内心的痛苦自白。', poem_tags = '宋词三百首,豪放,典故,留恋,感伤' WHERE poem_title = '破阵子·四十年来家国' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '近年来做官的兴味淡淡的像一层薄纱，谁又让我乘马来到京都作客沾染繁华？\n住在小楼听尽了一夜的春雨淅沥滴答，清早会听到小巷深处在一声声叫卖杏花。\n铺开小纸从容地斜写行行草草，字字有章法，晴日窗前细细地煮水、沏茶、撇沫，试着品名茶。\n呵，不要叹息那京都的尘土会弄脏洁白的衣衫，清明时节还来得及回到镜湖边的山阴故家。', poem_notes = '霁（jì）：雨后或雪后转晴。\n世味：人世滋味；社会人情。\n客：客居。\n京华：京城之美称。因京城是文物、人才汇集之地，故称。\n深巷：很长的巷道。\n明朝（zhāo）：明日早晨。\n矮纸：短纸、小纸。\n斜行：倾斜的行列。\n草：指草书。\n晴窗：明亮的窗户。\n细乳：沏茶时水面呈白色的小泡沫。\n分茶：宋元时煎茶之法。注汤后用箸搅茶乳，使汤水波纹幻变成种种形状。\n素衣：原指白色的衣服，这里用作代称。是诗人对自己的谦称（类似于“素士”）。\n风尘叹：因风尘而叹息。暗指不必担心京城的不良风气会污染自己的品质。', poem_appreciation = '如果掩去作者的名字，读这首《临安春雨初霁》，也许会以为它并不是出自“铁马金戈”、“气吞残虏”的陆放翁之手。诗中虽然有杏花般的春色，却更隐含着“世味薄似纱”的感伤之情和“闲作草”“戏分茶”的无聊之绪。这是与高唱着“为国戍轮台”而“一身报国”的陆游的雄奇悲壮的风格特征很不一致的。\n\n　　自淳熙五年孝宗召见了陆游以来，他并未得到重用，只是在福建、江西做了两任提举常平茶盐公事；家后五年，更是远离政界，但对于政治舞台上的倾轧变幻，对于世态炎凉，他是体会得更深了。所以诗的开头就用了一个独具易动的巧譬，感叹世态人情薄得就象半透明的纱。于是首联开口就言“世味”之“薄”，并惊问“谁令骑马客京华”。陆游时年已六十二岁，不仅长期宦海沉浮，而且壮志未酬，又兼个人生活的种种不幸，这位命途坎坷的老人发出悲叹，说出对世态炎凉的内心感受。这种悲叹也许在别人身上是无可疑问的，而对于“僵卧孤村不自哀，尚思为国戍轮台”的陆游来说，却显得不尽合乎情理。此奉诏入京，被任命为严州知州。对于一生奋斗不息、始终矢志不渝地实现自己的报国理想的陆游来说，授之以权，使之报国有门，竟会引起他“谁”的疑问。\n\n　　颔联点出“诗眼”，也是陆游的名句，语言清新隽永。诗人只身住在小楼上，彻夜听着春雨的淅沥；次日清晨，深幽的小巷中传来了叫卖杏花的声音，告诉人们春已深了。绵绵的春雨，由诗人的听觉中写出；而淡荡的春光，则在卖花声里透出。写得形象而有深致。传说这两句诗后来传入宫中，深为孝宗所称赏，可见一时传诵之广。历来评此诗的人都以为这两句细致贴切，描绘了一幅明艳生动的春光图，但没有注意到它在全诗中的作用不仅在于刻划春光，而是与前后诗意浑然一体的。其实，“小楼一夜听春雨”，正是说绵绵春雨如愁人的思绪。在读这一句诗时，对“一夜”两字不可轻轻放过，它正暗示了诗人一夜未曾入睡，国事家愁，伴着这雨声而涌上了眉间心头。李商隐的“秋阴不散霜飞晚，留得枯荷听雨声”，是以枯荷听雨暗寓怀友之相思。陆游这里写得更为含蓄深蕴，他虽然用了比较明快的字眼，但用意还是要表达自己的郁闷与惆怅，而且正是用明媚的春光作为背景，才与自己落寞情怀构成了鲜明的对照。\n\n　　接下去的颈联就道出了他的这种心情。在这明艳的春光中，诗人只能做的是“矮纸斜行闲作草”，陆游擅长行草，从现存的陆游手迹看，他的行草疏朗有致，风韵潇洒。这一句实是暗用了张芝的典故。据说张芝擅草书，但平时都写楷字，人问其故，回答说，“匆匆不暇草书”，意即写草书太花时间，所以没功夫写。陆游客居京华，闲极无聊，所以以草书消遣。因为是小雨初霁，所以说“晴窗”，“细乳戏分茶”这里就是品茶、玩茶道。无事而作草书，晴窗下品着清茗，表面上看，是极闲适恬静的境界，然而在这背后，正藏着诗人无限的感慨与牢骚。陆游素来有为国家作一番轰轰烈烈事业的宏愿，而严州知府的职位本与他的素志不合，何况觐见一次皇帝，不知要在客舍中等待多久！国家正是多事之秋，而诗人却在以作书品茶消磨时光，真是无聊而可悲！于是再也捺不住心头的怨愤，写下了结尾两句。\n\n　　尾联虽不像古人抱怨“素衣化为缁”（晋陆机作《为顾彦先赠好》：“京洛多风尘，素衣化为缁”），但这联不仅道出了羁旅风霜之苦，又寓有京中恶浊，久居为其所化的意思。诗人声称清明不远，应早日回家，而不愿在所谓“人间天堂”的江南临安久留。诗人应召入京，却只匆匆一过，便拂袖而去。陆游这里反用其意，其实是自我解嘲。\n\n　　在陆游的众多著名诗篇中，有壮怀激烈的爱国忧民之作，如《关山月》、《秋夜将晓出篱门迎凉有感》；有寄梦抒怀、悲愤凄切之作，如《十一月四日风雨大作》，这些诗不是直抒胸臆，痛切陈词，就是笔墨纵横，抚古思今，都是雄壮的大气磅礴之作；作者也有优美淳朴的乡村生活描写，如《游山西村》；也有缅怀爱情、追思往日幸福的伤感之作，如《沈园》。等等这些，都与《临安春雨初霁》极不相似。《临安春雨初霁》没有豪唱，也没有悲鸣，没有愤愤之诗，也没有盈盈酸泪，有的只是结肠难解的郁闷和淡淡然的一声轻叹，“别是一番滋味在心头”。\n\n　　严酷的现实，使他不得不对朝廷对皇帝，对人生对社会作出一些阴暗的结论。与他的许多寄梦诗不一样，在深夜，万籁俱寂时，作者眼前没有现实生活的情景搅扰，可以对着旷远的星空和雨夜任意地幻想，说任何放言达词。而身在繁荣帝都，作者却身不由己。临安城虽然春色明媚，但官僚们偏安一隅，忘报国仇，粉饰太平。作者是时刻清醒的，他在表面的升平气象和繁荣面貌中看到了世人的麻木、朝廷的昏聩，想到了自己未酬的壮志。但他既不能高唱，又无法托情梦，只好借春色说愁绪，把春天写成了无情之物。\n\n　　可以说《临安春雨初霁》反映了作者内心世界的另一方面，作者除了在战场上、幕帐中和夜空下高唱报国之外，偶尔也有惆怅徘徊的时候。在几乎同时所作的《书愤》中，作者就截然不同地表现了一贯的豪情。《书愤》在一定意义上是作者对自己悲壮一生的总结。“早岁那知世事艰”，却终有胆量说“千载谁堪伯仲间”，把一生留给历史公断。《临安春雨初霁》、《书愤》的比较可以显现出诗人感情思想的一个短时期的反复。陆游毕竟是陆游，他不会永久地停留在“闲”“戏”之上的。不久后他在严州任上，仍坚持抗金，并且付诸行动，表达于诗文，终于又被以“嘲咏风月”的罪名罢官。他的绵绵“杏花春雨”，在《十一月四日风雨大作》中，发展成了“铁马冰河入梦来”的疾风暴雨。\n\n　　一个诗人的性格是复杂的，一个始终刚强不屈、矢志不渝的烈士，也难免间或惆怅抑郁。这种抑郁惆怅与其雄奇悲壮并不矛盾。唯其抑郁惆怅得苦不堪言，才有更强烈的情怀的喷发。诗中一开头就道“世味薄似纱”，正是作者对现实的否定，也体现出作者的刚直气节。诗末拂袖而去，也是诗人对浮华帝都的不屑。因此，透过原诗的表面，依稀仍可看见一个威武不屈的形象，这个形象才是作者真正的一贯的自己。', poem_tags = '古诗三百首,春天,写雨,忧愁' WHERE poem_title = '临安春雨初霁' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '狂风声里，角弓鸣响，将军狩猎渭城郊外。\n秋草枯黄，鹰眼更加锐利；冰雪消融，马蹄格外轻快。\n转眼已过新丰市，不久又回细柳营。\n回头远眺射雕荒野，千里暮云平展到天边。', poem_notes = '诗题一作《猎骑》。宋人郭茂倩摘前四句编入《乐府诗集·近代曲辞》，题作《戎浑》。按：唐人姚合《玄极集》及韦庄《又玄集》均以此诗为王维作。猎，狩猎。\n劲：强劲。\n角弓：用兽角装饰的硬弓，使用动物的角、筋等材料制作的传统复合弓。\n渭（wèi）城：秦时咸阳城，汉改称渭城，在今西安市西北，渭水北岸。\n鹰：指猎鹰。\n眼疾：目光敏锐。\n新丰市：故址在今陕西省临潼县东北，是古代盛产美酒的地方。\n细柳营：在今陕西省长安县，是汉代名将周亚夫屯军之地。借此指打猎将军所居军营。\n射雕处：借射雕处表达对将军的赞美。雕：猛禽，飞得快，难以射中；射雕：北齐斛律光精通武艺，曾射中一雕，人称“射雕都督”，此引用其事以赞美将军。\n暮云平：傍晚的云层与大地连成一片。', poem_appreciation = '诗的内容不过是一次普通的狩猎活动，却写得激情洋溢，豪放有力。全诗共分两部分。前四句为第一部分，写射猎的过程；后四句写将军傍晚收猎回营的情景。\n\n　　首联起句先写角弓鸣响，箭飞劲疾，然后才点出是将军冬猎。在强劲的北风中，传来了开弓放箭的声音，一开头便渲染出紧张肃杀的气氛，然后点明猎者和猎所，确是下笔不凡。\n\n　　“风劲角弓鸣”，未及写人，先全力写其影响：风呼，弦鸣。风声与角弓（用角装饰的硬弓）声彼此相应：风之劲由弦的震响听出；弦鸣声则因风而益振。“角弓鸣”三字已带出“猎”意，能使人去想象那“马作的卢飞快，弓如霹雳弦惊”的射猎场面。劲风中射猎，待声势俱足，才推出射猎主角来：“将军猎渭城”。这发端的一笔，胜人处全在突兀，能先声夺人。\n\n　　领联具体描写纵鹰击捕，怒马追逐，进一步渲染了打猎的气氛，细致地刻画出打猎的场面，成为千古传诵的名句。诗人用“疾”字刻画鹰眼锐利，以“轻”字形容马蹄迅捷，细腻传神。\n\n　　渭城为秦时咸阳故城，在长安西北，渭水北岸，其时平原草枯，积雪已消，冬末的萧条中略带一丝儿春意。“草枯”“雪尽”四字如素描一般简洁、形象，颇具画意。“鹰眼”因“草枯”而特别锐利，“马蹄”因“雪尽”而绝无滞碍，颔联体物极为精细。“草枯鹰眼疾”不言鹰眼“锐”而言眼“疾”，意味猎物很快被发现，紧接以“马蹄轻”三字则见猎骑迅速追踪而至。“疾”“轻”下字俱妙。三四句初读似各表一意，对仗铢两悉称；细绎方觉意脉相承，实属“流水对”。如此精妙的对句，实不多见。\n\n　　以上写出猎，只就“角弓鸣”、“鹰眼疾”、“马蹄轻”三个细节点染，不写猎获的场面。一则由于猎获之意见于言外；二则射猎之乐趣，远非实际功利所可计量，只就猎骑英姿与影响写来自佳。\n\n　　颈联紧接“马蹄轻”而来，意思却转到罢猎还归。虽转折而与上文意脉不断，自然流走。言“忽过”，言“还归”，则见返营驰骋之疾速，真有瞬息“千里”之感。这两句连上两句，既生动地描写了猎骑情景又真切地表现了主人公的轻快感受和喜悦心情。\n\n　　“新丰市”（今陕西临潼县）、“细柳营”（今陕西长安县），两地相隔七十余里。这两个地名皆可参考见《汉书》，诗人兴会所至，一时汇集，典雅有味。“细柳营”本是汉代周亚夫屯军之地，用来就多一重意味，似谓诗中狩猎的主人公亦具名将之风度，与其前面射猎时意气风发、飒爽英姿，形象正相吻合。这两句连上两句，既生动描写了猎骑情景，又真切表现了主人公的轻快感觉和喜悦心情。\n\n　　尾联更以写景作结，但它所写非营地景色，而是遥遥“回看”行猎处之远景，已是“千里暮云平”，此景遥接篇首，首尾不但彼此呼应，而且适成对照：当初风起云涌，与出猎约紧张气氛相应；此时风平云定，与猎归后从容自如的心境相称。\n\n　　首尾不但彼此呼应，而且适成对照：当初是风起云涌，与出猎紧张气氛相应；此时是风定云平，与猎归后踌躇容与的心境相称。写景俱是表情，于景的变化中见情的消长，堪称妙笔。七句语有出典，语出《北史·斛律光传》载：北齐斛律光精通武艺，曾射中一雕，人称“射雕都督”。此言“射雕处”，借射雕处赞美将军的膂力强、箭法高。诗的这一结尾遥曳生姿，饶有余味。\n\n　　总的来说，王维的诗，或以悠闲古淡见长，或以豪迈精工著称。此诗气概豪迈，造句精工，章法严整，诗味浓郁。此诗运用先声夺人、侧面烘托和活用典故等艺术手段来刻画人物，从而使诗的形象鲜明生动、意境恢宏而含蓄。诗写的虽是日常的狩猎活动，但却栩栩如生地刻画出将军的骁勇英姿、感染力，表达出诗人渴望效命疆场，期盼建功立业。', poem_tags = '冬天,狩猎' WHERE poem_title = '观猎' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '荡罢秋千起身，懒得揉搓细嫩的手。在她身旁，瘦瘦的花枝上挂着晶莹的露珠，她身上的涔涔香汗渗透着薄薄的罗衣。\n突然进来一位客人，她慌得顾不上穿鞋，只穿着袜子抽身就走，连头上的金钗也滑落下来。她含羞跑开，倚靠门回头看，又闻了一阵青梅的花香。', poem_notes = '点绛唇：词牌名。\n蹴：踏。此处指打秋千。\n慵：懒，倦怠的样子。\n袜刬：这里指跑掉鞋子以袜着地。金钗溜：意谓快跑时首饰从头上掉下来。\n倚门回首：这里只是靠着门回头看的意思。', poem_appreciation = '靖康之乱前，词人李清照的生活是幸福美满的。她这时期的词，主要是抒写对爱情的强烈追求，对自由的渴望。风格基本上是明快的。《点绛唇》（“蹴罢秋千”）很可能就是这一时期中的早期作品。\n\n　　这首词的上片用“慵整纤纤手”、“露浓花瘦，薄汗轻衣透”，给读者描绘出一个身躯娇小、额间鬓角挂着汗珠、轻衣透出香汗刚下秋千的如花少女天真活泼、憨态可掬的娇美形象。紧接着，词人转过笔锋，使静谧的词境风吹浪起，写少女忽然发现有人来了，她自然而然地、匆匆忙忙地连鞋子也顾不上穿，光着袜子，害羞地朝屋里就跑，头上的金钗也滑落了。这把封建社会深闺少女的另一种心理和行动，也就是在封建礼教束缚下的遵守所谓“礼”的心理和行动，逼真地摹写出来了。但是，她害羞地跑到门边，却没有照常理立刻躲进屋里去，而是“倚门回首，却把青梅嗅”。\n\n　　李清照这两个短句和李煜《一斛珠》中的“烂嚼红茸，笑向檀郎唾”一样，成功地写出了少女的情态。同时，李清照这两个短句还生动地表露了少女的内心世界。她嗅青梅，不是真的嗅，而是用以表现其若无其事来遮掩她的紧张。这和欧阳炯《贺明朝》中的：“石榴裙带，故将纤纤玉指，偷捻双凤金线。”晃冲之《传言玉女·上元》中的“娇波溜人，手捻玉梅低说”，都有类似之处。这和今天现实生活中，年轻的姑娘以摆弄辫梢、手绢等，来掩饰她的害羞、紧张也是类似的。至于“回首”，那也和欧阳炯《南乡子》中“水上游人沙上女，回顾，笑指芭蕉林里住”的“回顾”，李珣《南乡子》中“玉纤遥指花深处，争回顾，孔雀双双迎日舞”的“回顾”一样，虽然它们所表现的内容、表达的感情，并不完全相同，但它们都是以简单的回头看的动作，表现比较复杂的内心活动的。李清照这两个短句中的“回首”是少女对来人打搅了她自由玩乐的不愉快，她要看看打搅她的来人是谁，她要看看把他弄得那么狼狈的是谁，是什么样的人。这表现了她的天真、勇敢，表现了她对封建礼教束缚轻视的一面。这种思想感情，就其内容来说，远远超过了这一生活侧面的描写。\n\n　　在李清照之前，虽然绝大多数词都是写妇女，但是，能够描绘出妇女的形象，并写出妇女的内心世界，而且有一定意义的却不多。李清照这首《点绛唇》语言质朴，形象生动逼真，不但有心理描写，而且有一定的深意，的确是一首写封建社会的少女（词人的自我写照）的好作品。它和李清照的著名词作《一剪梅》（“红藕香残玉簟秋”）、《醉花阴》（“薄雾浓云愁永昼”）、《武陵春》（“风住尘香花已尽”）、《声声慢》（“寻寻觅觅”）等完全可以媲美。', poem_tags = '宋词三百首,宋词精选,少女' WHERE poem_title = '点绛唇·蹴罢秋千' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '以往八月十五的夜晚，“我”站在曲江的池畔杏园旁边。\n今年八月十五的夜晚，“我”又在湓浦沙头水馆前。\n向着西北怎么才能看到故乡在哪里，向着东南方向看见月亮又圆了好几次。\n昨天的风吹过没有人理会，今晚清美的风彩就好像以往的那些年。', poem_notes = '昔年：去年、以往。', poem_appreciation = '歌题目的中心语“望月”，是叙述也是行为，其修饰语时间“八月十五日夜”和地点“湓亭”，它限定了望月的特定环境时，还突出“望”的动作，又强化“望”之月的圆盘貌。显然是这个“望”月引发了诗人情怀。\n\n　　其实，诗人就是在特定空间面对这个特定时间的月亮引发的人生感慨，诗歌首颔联正是诗人关照月亮的思考。从逻辑上应该“明、曲江池畔、朝廷盛会欢饮图。诗歌起笔不同反响，召唤其昔日的觥筹交颔联的今年贬谪的“湓浦沙头水馆前”的失落。繁华的过去越明朗，对照今日的凄冷就越有感觉，以此造成的昔今悬殊反差，犹如从天堂掉入地狱的悲苦感。可是两联二十八言中，诗人不烦厌地重复“八月十五夜”，显然它带给诗人的心灵是震撼的，也是惨痛的。让诗人不堪回首昨日的欢乐，独自苦品着眼前的寂寞和凄苦。诗句一望而知地运用了昔今对比手法，其实每一联都交代了时间地点和场景，对比的不仅是时间，更是情景意境的对比，今晚观赏的心情，是一种过去到现在的物是人非的感伤情怀。\n\n　　月亮在古典诗歌里，更多承载了怀乡思亲。“举头望明月，低头思故乡”“我寄愁心与明月，随君直到夜郎西”“明月照高楼，含君千里光”，这些月亮内涵是因空间距离产生而寄寓感情的。不过月亮也会出现时间概念，它却成穷已，江月年年望相似。不知江月待何人，但见长江送流水（张若虚《春江花月夜》）”“ 淮水东边旧时月，夜深还过女墙来（刘禹锡《石头城》）”“春江秋月何时了，往事知多少（李煜《虞美人》）”，这些诗句里的月亮意象无不指向时间概念，突出物是人非之感留给个体生命的怅惘痛苦。\n\n　　昔今这种对比古诗里还是常见的，“昔闻洞庭水，今上岳阳楼”（杜甫《登岳阳楼》），过去听闻就该登楼观望洞庭水，可是不知为何直至今朝才有机缘登临，道出诗人生活无尽的无奈和生活的凄楚遭遇。其实白居易在对比中也在暗示自己无法主宰命运的无奈和感伤之情。\n\n　　诗歌的首颔联多层面的表现诗人的痛苦感，其实这还是生活横截面的对比，那诗歌又是如何完成内容的转折呢？从内容上颈联涉及望乡和圆月，表面上像在思乡，但是“望乡“行为反映的心理，却浸透着诗人的孤寂和凄苦，而这种心理再次强化了内在的主体孤苦体验。“见月”就是观赏中秋明月月，那是一轮圆月，但行为发问的竟为“几回圆人极度孤寂产生的心理结果。“西北望四方眺望故乡和四野观望明月，能想象出一个人观望的心神不定和急切之情，希望能望到家乡带给自己温暖，能看到心中一轮明月留给自己关怀，却出现相反结果，徒添了诗人不尽的凄苦感。\n\n　　诗歌是如此极尽曲折的突出诗人贬谪的孤寂之情，尾联诗人细节化的再现秋风月光。“秋风秋雨愁煞人”，过去的日子出现的“昨风一吹无人会”，没有人领会这凄厉秋风的凉意。能忽略这凄冷秋风的肌肤感，一定是人们沉浸在无情的喜悦里，已然忘记了秋风的凄冷，这里突出诗人过去日子的欢快感。“今夜清光似往年”，一是说今夜的月和往年是相似的，光是借代用法，突出的月亮还是昔日的月亮，暗含了人已不是昔日的意气之人了，照应诗歌前文对比的物是人非的无奈悲苦；二是言今夜的月亮似往年，但这样的月光照在身上，却令人清冷至极，置身“湓浦沙头水馆前”环境里，心内却是清冷感，诗歌在这进一步强化了诗人贬谪后面对十五惊叹诗人诗歌技巧的娴熟，尺幅之间尽情描摹无形的心里悲苦！', poem_tags = '中秋节,贬谪,孤独,思乡' WHERE poem_title = '八月十五日夜湓亭望月' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '玉漏和银壶你们暂且停下不要催了，宫禁的城门和上面的金锁直到天亮也开着。\n谁家看到明月还能坐着什么都不做呢？哪里的人听说有花灯会不过来看呢？', poem_notes = '①上元：节日名，即农历正月十五元宵节。\n②玉漏、银壶、铁关、金锁：都是美称，并非真正全由玉、银、铁、金做成，应理解为“像……一样的……”\n③漏，壶：古代计时的器具，古人向铜壶里灌水，壶底打通一小孔，壶中立刻度箭，壶中的水逐渐减少，箭上的度数就依次显露出来，然后根据刻度计时，是为漏刻之法。\n④铁关：宫禁的城门，唐朝宫禁森严，平时入夜即管关，天亮开放。\n⑤彻：通，直到。', poem_appreciation = '上元夜，指旧历正月十五夜，又称元宵节。我国素有元宵赏灯的风俗。崔液组诗《上元夜》七绝，共六首。描写当时京城长安元宵赏灯的繁华景象。据刘肃《大唐新语》记载：“神龙（唐中宗年号，公元705—707年）之际，京城正月望日（即十五），盛饰灯影之会，金吾弛禁，特许夜行。贵族戚属及下隶工贾，无不夜游。车马喧阗，人不得顾。王、主之家，马上作乐，以相竞夸。文士皆赋诗一章，以记其事。作者数百人，唯中书侍郎苏味道、吏部员外郎郭利贞（苏、郭之作皆五律）、殿中侍御史崔液为绝唱。”这是崔液所作赏灯诗六首中的第一首。\n\n　　“玉漏银壶且莫催，铁关金锁彻明开。”“玉漏银壶”，计时的器具，古代以漏刻之法计时，具体方法是用铜壶盛水，壶底打通一小孔，壶中立刻度箭，壶中的水逐渐减少，箭上的度数就依次显露，就可按度计时，击鼓报更。元宵夜尽管解除了宵禁，但长安城的钟鼓楼上，仍旧按时报更；人们听了，都嫌时间过得太快，怕不能玩得尽兴，于是说：滴漏箭壶，你不要这样一声比一声紧地催促呀，也不要过得那么快，今夜的城门要一直开到天亮呢！上句写出了人们“欢娱苦日短”的感慨，下句是说在此太平盛世，应该通宵尽兴。吃过晚饭，打扮一新的人们，按捺不住心中的喜悦，迫不及待地早早走出家门，三五成群相邀着、呼唤着、嬉笑着，涌出巷口，融入大街，汇进似潮喧闹欢腾的人流。人们兴高采烈地燃放烟花爆竹，挥舞狮子龙灯，观赏绚丽多彩的灯火，评论着、嬉戏着、赞叹着。越看越高兴，越玩越兴奋，“莫相催”衬托出气氛之热烈，景色之迷人、“彻明开”既写出了元宵节通宵达旦闹花灯时间和程度，又写出了人们高涨而持续的勃勃兴致。\n\n　　后面接着连用两个问句：“谁家见月能闲坐？何处闻灯不看来？”“谁家”、“何处”，实际是指家家、人人说明万巷皆空的盛况。这包括了上至王侯将相，下至平民百姓形形色色的各类人。因而，“谁家”“何处”这四字包涵的内容实在太多，它把人声鼎沸、车如流水马如龙，灯火闪烁，繁华似锦的京城元宵夜景一语道尽。连用两个诘句，不仅将盛景迷人，令人不得不往的意思表达得灵活传神，而且给人以无限回味的余地，言有尽而意无穷。', poem_tags = '节日,元宵节' WHERE poem_title = '上元夜六首·其一' AND poem_author = '崔液';
UPDATE edu_poem SET poem_translation = '山上寺院的高楼真高啊，好像有一百尺的样子，人在楼上好像一伸手就可以摘下天上的星星。\n站在这里，我不敢大声说话，唯恐（害怕）惊动天上的神仙。', poem_notes = '宿：住，过夜。\n危楼：高楼，这里指山顶的寺庙。危：高。百尺：虚指，不是实数，这里形容楼很高。\n星辰：天上的星星统称。\n语：说话。\n恐：唯恐，害怕。惊：惊动。', poem_appreciation = '诗人夜宿深山里面的一个寺庙，发现寺院后面有一座很高的藏经楼，于是他登了上去。凭栏远眺，星光闪烁，李白诗性大发，写下了这一首纪游写景的短诗。\n\n　　首句正面描绘寺楼的峻峭挺拔、高耸入云。发端一个“ 危 ”字，倍显突兀醒目，与“高”字在同句中的巧妙组合，就确切、生动、形象地将山寺屹立山巅、雄视寰宇的非凡气势淋漓尽致地描摹了出来。\n\n　　次句以极其夸张的技法来烘托山寺之高耸云霄。字字将读者的审美视线引向星汉灿烂的夜空，非但没有“高处不胜寒”的感慨，反给人旷阔感，以星夜的美丽引起人们对高耸入云的“危楼”的向往。\n\n　　三、四两句，“不敢”写出了作者夜临“危楼”时的心理状态，从诗人“不敢”与深“怕”的心理中，读者完全可以想象到“山寺”与“天上人”的相距之近，这样，山寺之高也就不言自明了。\n\n　　诗人用夸张的艺术手法，描绘了山寺的高耸，给人以丰富的联想。山上的这座楼好像有一百尺高，诗人站在楼顶就可以用手摘下天上的星星。在这儿都不敢大声说话，唯恐惊动了天上的仙人。\n\n　　此诗语言自然朴素，却形象逼真。全诗无一生僻字，却字字惊人，堪称“平字见奇”的绝世佳作。诗人借助大胆想象，渲染山寺之奇高，把山寺的高耸和夜晚的恐惧写的很逼真，从而将一座几乎不可想象的宏伟建筑展现在读者面前，给人身临其境的感觉。摘星辰、惊天人，这些仿佛是童稚的想法，被诗人信手拈来，用入诗中，让人顿感情趣盎然，有返璞归真之妙。\n\n　　李白的诗风豪放雄健，想象极其丰富，语言自然婉转，音律富于变化而又和谐统一，具有浓郁的浪漫主义色彩。此诗寥寥数笔，就酣畅淋漓地表现出了人在高处的愉悦、豪放、可爱、率直。', poem_tags = '纪游,写景,早教古诗100首' WHERE poem_title = '夜宿山寺' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '繁花靠近高楼，远离家乡的我触目伤心，在这全国各地多灾多难的时刻，我登楼观览。\n锦江两岸蓬蓬勃勃的春色铺天盖地涌来，玉垒山上的浮云，古往今来，千形万象，变幻不定。\n朝廷如同北极星一样最终都不会改换，西山的寇盗吐蕃不要来侵扰。\n可叹蜀后主刘禅那样的昏君，仍然在祠庙中享受祭祀，黄昏的时候我也姑且吟诵那《梁甫吟》。\n\n韵译\n登楼望春近看繁花游子越发伤心；万方多难愁思满腹我来此外登临。\n锦江的春色从天地边际迎面扑来；从古到今玉垒山的浮云变幻莫测。\n大唐的朝廷真像北极星不可动摇；吐蕃夷狄莫再前来骚扰徒劳入侵。\n可叹刘后主那么昏庸还立庙祠祀；日暮时分我要学孔明聊作梁父吟。', poem_notes = '客心：客居者之心。\n锦江：即濯锦江，流经成都的岷江支流。成都出锦，锦在江中漂洗，色泽更加鲜明，因此命名濯锦江。\n来天地：与天地俱来。　\n玉垒浮云变古今：是说多变的政局和多难的人生，捉摸不定，有如山上浮云，古往今来一向如此。\n玉垒：山名，在四川灌县西、成都西北。\n变古今：与古今俱变。\n北极：星名，北极星，古人常用以指代朝廷。\n终不改：终究不能改，终于没有改。\n西山：指今四川省西部当时和吐蕃交界地区的雪山。\n寇盗：指入侵的吐蕃集团。\n后主：刘备的儿子刘禅，三国时蜀国之后主。曹魏灭蜀，他辞庙北上，成亡国之君。\n还祠庙：意思是，诗人感叹连刘禅这样的人竟然还有祠庙。这事借眼前古迹慨叹刘禅荣幸佞臣而亡国，暗讽唐代宗信用宦官招致祸患。\n还：仍然。\n聊为：不甘心这样做而姑且这样做。\n梁父吟：古乐府中一首葬歌。。“父”通“甫”读三声fǔ 传说诸葛亮曾经写过一首《梁父吟》的歌词', poem_appreciation = '首联提挈全篇，“万方多难”，是全诗写景抒情的出发点。在这样一个万方多难的时候，流离他乡的诗人愁思满腹，登上此楼，虽然繁花触目，诗人却为国家的灾难重重而忧愁，伤感，更加黯然心伤。花伤客心，以乐景写哀情，和“感时花溅泪”（《春望》）一样，同是反衬手法。在行文上，先写诗人见花伤心的反常现象，再说是由于万方多难的缘故，因果倒装，起势突兀；“登临”二字，则以高屋建瓴之势，领起下面的种种观感。\n\n　　颔联从诗人登楼所见的自然山水描述山河壮观，“锦江”、“玉垒”是登楼所见。诗人凭楼远望，锦江流水挟着蓬勃的春色从天地的边际汹涌而来，玉垒山上的浮云飘忽起灭，正像古今世势的风云变幻，诗人联想到国家动荡不安的局势。上句向空间开拓视野，下句就时间驰骋遐思，天高地迥，古往今来，形成一个阔大悠远、囊括宇宙的境界，饱含着诗人对祖国山河的赞美和对民族历史的追怀；而且，登高临远，视通八方，独向西北前线游目骋怀，也透露诗人忧国忧民的无限心事。\n\n　　颈联议论天下大势，“朝廷”、“寇盗”，是诗人登楼所想。北极，星名，居北天正中，这里象征大唐政权。上句“终不改”，反承第四句的“变古今”，是从前一年吐蕃攻陷京城、代宗不久复辟一事而来，意思是说大唐帝国气运久远；下句“寇盗”“相侵”，进一步说明第二句的“万方多难”，针对吐蕃的觊觎寄语相告：“莫再徒劳无益地前来侵扰！”词严义正，浩气凛然，在如焚的焦虑之中透着坚定的信念。\n\n　　尾联咏怀古迹，讽喻当朝昏君，寄托诗人的个人怀抱。后主，指蜀汉刘禅，宠信宦官，终于亡国；先主庙在成都锦官门外，西有武侯祠，东有后主祠；《梁甫吟》是诸葛亮遇刘备前喜欢诵读的乐府诗篇，用来比喻这首《登楼》，含有对诸葛武侯的仰慕之意。诗人伫立楼头，徘徊沉吟，很快日已西落，在苍茫的暮色中，城南先主庙、后主祠依稀可见。想到后主刘禅，诗人不禁喟然而叹：“可怜那亡国昏君，竟也配和诸葛武侯一样，专居祠庙，歆享后人香火！”这是以刘禅比喻唐代宗李豫。李豫重用宦官程元振、鱼朝恩，造成国事维艰、吐蕃入侵的局面，同刘禅信任黄皓而亡国极其相似。所不同的是，诗人生活的时代只有刘后主那样的昏君，却没有诸葛亮那样的贤相。而诗人自己，空怀济世之心，苦无献身之路，万里他乡，高楼落日，忧虑满怀，却只能靠吟诗来聊以自遣。\n\n　　全诗即景抒怀，写山川联系着古往今来社会的变化，谈人事又借助自然界的景物，互相渗透，互相包容；融自然景象、国家灾难、个人情思为一体，语壮境阔，寄意深远，体现了诗人沉郁顿挫的艺术风格。\n\n　　这首七律，格律严谨。中间两联，对仗工稳，颈联为流水对，有一种飞动流走的快感。在语言上，特别工于各句（末句例外）第五字的锤炼。首句的“伤”，为全诗点染一种悲怆气氛，而且突如其来，造成强烈的悬念。次句的“此”，兼有“此时”、“此地”、“此人”、“此行”等多重含义，也包含着“只能如此而已”的感慨。三句的“来”，烘托锦江春色逐人、气势浩大，令人有荡胸扑面的感受。四句的“变”，浮云如白云变苍狗，世事如沧海变桑田，一字双关，引发读者作联翩无穷的想象。五句的“终”，是“终于”，是“始终”，也是“终久”；有庆幸，有祝愿，也有信心，从而使六句的“莫”字充满令寇盗闻而却步的威力。七句的“还”，是“不当如此而居然如此”的语气，表示对古今误国昏君的极大轻蔑。只有末句，炼字的重点放在第三字上，“聊”是“不甘如此却只能如此”的意思，抒写诗人无可奈何的伤感，与第二句的“此”字遥相呼应。\n\n　　尤其值得读者注意的是，首句的“近”字和末句的“暮”字在诗的构思方面起着突出的作用。全诗写登楼观感，俯仰瞻眺，山川古迹，都是从空间着眼；“日暮”，点明诗人徜徉时间已久。这样就兼顾了空间和时间，增强了意境的立体感。单就空间而论，无论西北的锦江、玉垒，或者城南的后主祠庙，都是远处的景物；开端的“花近高楼”却近在咫尺之间。远景近景互相配合，便使诗的境界阔大雄浑而无豁落空洞的遗憾。\n\n　　历代诗家对于此诗评价极高。清人浦起龙评论说：“声宏势阔，自然杰作。”（《读杜心解》卷四）沈德潜更为推崇说：“气象雄伟，笼盖宇宙，此杜诗之最上者。”（《唐诗别裁》卷十三）', poem_tags = '唐诗三百首,初中古诗,高中古诗,写景,怀古,感时,忧国忧民' WHERE poem_title = '登楼' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '一袭深红色的长裙日子久了便蒙上了淡黄色，自古以来旧的东西就比不得新的东西讨人喜欢。\n你我原本应该像合欢核桃一样坚贞不移，哪里想到你的心里原来已经有了别人，让我对你终究有了恨意。（其一）\n\n深夜里点亮烛火深深的嘱咐你，此去路途遥远不要忘了归期。\n小巧精致的骰子上嵌入那意喻相思的红豆，相思入骨你是否知道？', poem_notes = '一尺深红：即一块深红色丝绸布。古代妇人之饰；或即女子结婚时盖头的红巾，称“盖头”。曲尘：酒曲上所生菌，因色微黄如尘，亦用以指淡黄色。此处意谓，红绸布蒙上了尘土，呈现出酒曲那样的暗黄色。\n合欢桃核：是夫妇好合恩爱的象征物。桃核，桃为心形，核同合音，可以像喻两心永远相合。\n里许：里面，里头。许，语助词。元来：即“原来”。人：取“仁”的谐音。\n深烛：音谐深嘱，此处用的是谐音双关的修辞手法，写女子“深嘱”情郎。伊：人称代词，“你”。\n长行：长行局，古代的一种博戏，盛行于唐。这里用此博戏的名称双关长途旅行。围棋：中国传统棋种。变化极复杂，棋理极深奥；高手对弈，一局棋常需数个时辰，甚至数日方可分出胜负。此处用“围棋”与“违期”的谐音，劝“郎”莫要误了归期。\n玲珑：精巧貌。骰（tóu）子：博具，相传为三国曹植创制，初为玉制，后演变为骨制，因其点着色，又称色子；为小立方体块状，六个面上分别刻有从一到六不同数目的圆点，其中一、四点数着红色，其余点数皆着黑色。这骰子上的红点，即被喻为相思的红豆。\n“入骨”句：用骨制的骰子上的红点深入骨内，来隐喻入骨的相思。“入骨”是双关隐语。', poem_appreciation = '其一\n\n　　“一尺深红蒙曲尘，天生旧物不如新。”首二句，感物起兴。眼见一块原来是极鲜亮的红丝绸，却因蒙上了灰尘，颜色变得暗淡了，旧如“曲尘”，而这“一尺深红”的丝绸，好像不是一般的妇人之饰，很可能它就是女子新婚时用过的方幅红绸“盖头”。这“一尺深红”，应是女子眼中的不寻常之物，她一直把那约一尺宽的红绸作为自己婚姻的象征，看到红绸，就引起对幸福的憧憬。可如今，眼前的红绸却已经蒙上尘土，还有了不少“曲尘”似的霉斑。睹物思人，不由感慨万端。唉，还是俗话说得对，物品天生的都是旧不如新。然而，就爱情而言，则不能“喜新厌旧”，而应是“日久长新”才好，否则情不专而怨恨必生。窦玄妻《古怨歌》云：“衣不如新，人不如故。”诗人这里正是以“衣不如新”反衬“人不如故”。看来是丈夫又有了新欢，才引起女主人公幽怨的情思。这二句运用了比喻，虽然手法委宛，语言却很直白，就意蕴而论，显然缺乏含蓄之美感。\n\n　　“合欢桃核终堪恨，里许元来别有人。”这二句，仍然运用了比喻，抒发被弃女子的“恨”意。“合欢桃核”，本来那是夫妇好合恩爱的象征物，旧日婚俗在“新人”家中，也常常摆放枣、栗子、桂枝、桃核等果物，预示喜兆。想当初，女主人公在与丈夫两情欢娱的时候，她是那样相信她们用桃核来表示的永远好合的誓言，现在明白，原来那“合欢桃核”里面，已经有了另外一个“人”了。“人”是“仁”的谐音，说“合欢桃核”另有“人”，就是说她的丈夫内心里另有新欢的“人”了。所以，这是借鉴了民歌中常用的谐音双关的手法写桃核内有“仁”以隐喻合欢之人心中原来别有“人”，富有民间的生活气息。既然对方心中已有他人，故第二句曰“旧物不如新”；虽前有“合欢桃核”之约，然“终堪恨”也。这就既巧妙地讽刺了爱情上的喜新厌旧者，又曲折地表达了抒情主人公对所爱者的执着追求，那“恨”字流露出一种难言的幽恨之情。面对负心人，诗人委婉地提出自己的劝戒，言有尽而意无穷，反映了甜蜜爱情生活中的另一个侧面。\n\n　　这首词，在艺术方面，采用比兴、暗示、谐音双关的手法，加强了抒情效果。但从词的整体意境看，仍然是“意伤于太尽”（张戒《岁寒堂诗话》），缺乏余韵远致。像“天生旧物不如新”、 “里许元来别有人”这样的内心触悟，也过于直浅了些。\n\n其二\n\n　　此篇是以女子口吻，抒写她对情郎的眷恋。首起二句，是叮嘱之辞。“井底点灯深烛伊”，这“井底点灯”四字，谓在井底点上灯。何以偏在井底点灯呢？原来这井底之灯，必是深处之烛。而“深烛”，隐喻“深嘱”。“伊”是人称代词，在此代“你”。 “深烛伊”也就是“非常诚恳地嘱咐你。”显然，是作者刻意运用谐音双关的手法叙事。因而使词意隐晦了。\n\n　　既云“深嘱”，嘱咐些什么呢？即次句“共郎长行莫围棋”。共，介词，犹同；跟。 “共郎”二字，明示女主人公正与郎相聚。而紧跟“长行”二字，又暗示着这是离别的时刻。所以她才对他叮嘱再三、情意绵绵。此“长行”与“围棋”，又作谐音双关。长行，是一种博戏的名称。据唐人笔记记载，用掷骰子来博“长行局”，因简单易行，唐人“颇或耽玩，至有废庆吊、忘寝休、辍饮食者”（《唐国史补》卷下），是一种低俗的赌博。而“围棋”，是中国传统的棋艺，棋理高深，可谓文人雅士的游戏。可她为什么“深嘱”将要出门的丈夫，让他记住：我可以与你玩长行，但不同你下围棋呢？原来，她的这番叮嘱中另有深意。她是用“长行”这种博戏的名称来双关“长途旅行”，又用“围棋”来双关“违误归期”。她这是告诉丈夫“远行一定不要误了归期”！在生活中，人们要把某件事情告诉对方，却又不便于明白说出，往往会用这种谐音双关的方式来暗示。这里的“长行”、“围棋”，也是女主人公将她深隐的心曲，婉转托出；虽然可见女子的柔情蜜意，但由于其中的隐语，过于隐晦。\n\n　　“玲珑骰子安红豆，入骨相思知不知？”这后两句从“长行”引出“骰子”，说那种制造精巧的骰子上的颗颗红点，有如最为相思的红豆，而且深入骨中，表达着我对你深入骨髓的相思，你知道吗？这样一来，自然又深化了第二句深嘱“长行莫围棋”的用意，原来她“共郎长行”，也是有意要用“长行”这种博戏所用的“骰子”来提醒丈夫：当你玩“长行”使用骰子时，知不知道，那骰子上的红点，颗颗都是入骨的红豆，代表着我对你的入骨相思？所以，你千万不要违误了归期。这一句，非常准确地表现出她对丈夫的惦念，对丈夫的那种难舍难离的强烈的爱！“入骨相思”，一语双关，其中缠绵之意，教人不由魂销。在章法上，则是对前二句“深嘱”早归“莫违期”的对应。诗中，女子“共郎长行”时“深嘱”于前，客子“违期”未归时又“入骨相思”于后，最后以“知不知”设问寄意的口吻轻轻将全诗兜住，然后再表现出这位多情的闺中人亟盼游子早归的焦虑心情。“知不知”三字，把女子离别之久、会合之难、相思之深之苦，乃至欲说无人都淋漓尽致地表现了出来，可谓收得自然，余味不尽。而读者所感受到的正是女主人公内心深处诚挚而火热的爱情。有女钟情如此，令人读来倍觉感人。“入骨相思知不知”七个字，乃是全篇的点睛之笔！\n\n　　这首词最精粹之笔，在于后二句以相思子（红豆）为喻，寄托女子的挚爱深情。全词采用谐音双关的手法，虽有助于词境的深婉含蓄；但由于刻意为之，便又流人“谜而不诗”（王夫之《古诗评选》）之地，缺乏“自然天成”之妙。\n\n　　此二诗写“合欢桃核终堪恨，里许元来别有人”，以讽喜新厌旧；写“玲珑骰子安红豆，入骨相思知不知”，以骰子喻己相思之情，就既未见浓艳的辞藻，又未闻有些许脂粉气。其设想新奇，别开生面，在许多的爱情诗中，使人顿觉耳目一新。大量使用谐音双关修辞法，更使诗作独标一格，别有情致。人们表达爱的情感，力避直率明白，本尚朦胧含蓄（当然不是晦涩费解），而双关隐语的运用，却能使人透过字面的意思，通过那些音同或音近的“别字”，去细细品味那双关语中底层的无尽的意蕴。这些谐音词的寓意颇深，不可囫囵读之。它蕴含着诗人人为的特定含义和感情色彩，能使语言在表达上更含蓄、婉转和饶有风趣。用于表达爱情，则言浅意深，更富有感染力。', poem_tags = '思念,爱情' WHERE poem_title = '南歌子词二首 / 新添声杨柳枝词' AND poem_author = '温庭筠';
UPDATE edu_poem SET poem_translation = '白天在田里锄草，夜晚在家中搓麻线，村中男男女女各有各的家务劳动。\n小孩子虽然不会耕田织布，也在那桑树阴下学着种瓜。', poem_notes = '耘田：除草。绩麻：把麻搓成线。各当家：每人担任一定的工作。未解：不懂。供：从事，参加。傍：靠近。', poem_appreciation = '这首诗描写农村夏日生活中的一个场景。 　\n\n　　首句“昼出耘田夜绩麻”是说：白天下田去除草，晚上搓麻线。“耘田”即除草。初夏，水稻田里秧苗需要除草了。这是男人们干的活。“绩麻”是指妇女们在白天干完别的活后，晚上就搓麻线，再织成布。这句直接写劳动场面。次句“村庄儿女各当家”，“儿女”即男女，全诗用老农的口气，“儿女”也就是指年轻人。“当家”指男女都不得闲，各司其事，各管一行。第三句“童孙未解供耕织”，“童孙”指那些孩子们，他们不会耕也不会织，却也不闲着。他们从小耳濡目染，喜爱劳动，于是“也傍桑阴学种瓜”，也就在茂盛成阴的桑树底下学种瓜。这是农村中常见的现象，却颇有特色。结句表现了农村儿童的天真情趣。\n\n　　诗人用清新的笔调，对农村初夏时的紧张劳动气氛，作了较为细腻的描写，读来意趣横生。', poem_tags = '古诗三百首,小学古诗,农村,夏天,生活' WHERE poem_title = '夏日田园杂兴·其七' AND poem_author = '范成大';
UPDATE edu_poem SET poem_translation = '我在年少时离开家乡，到了迟暮之年才回来。我的乡音虽未改变，但鬓角的毛发却已经疏落。\n儿童们看见我，没有一个认识的。他们笑着询问：这客人是从哪里来的呀？\n\n我离别家乡的时间已经很长了，回家后才感觉到家乡的人事变迁实在是太大了。\n只有门前那镜湖的碧水，在春风吹拂下泛起一圈一圈的涟漪，还和五十多年前一模一样。', poem_notes = '偶书：随便写的诗。偶：说明诗写作得很偶然，是随时有所见、有所感就写下来的。\n少小离家：贺知章三十七岁中进士，在此以前就离开家乡。老大：年纪大了。贺知章回乡时已年逾八十。\n乡音：家乡的口音。无改：没什么变化。一作“难改”。鬓毛：额角边靠近耳朵的头发。一作“面毛”。衰：减少，疏落。鬓毛衰：指鬓毛减少，疏落。\n相见：即看见我；相：带有指代性的副词。不相识：即不认识我。\n笑问：一本作“却问”，一本作“借问”。\n消磨：逐渐消失、消除。\n镜湖：在浙江绍兴会稽山的北麓，方圆三百余里。贺知章的故乡就在镜湖边上。', poem_appreciation = '第一首是久客异乡、缅怀故里的感怀诗。写于初来乍到之时，抒写久客伤老之情。在第一、二句中，诗人置身于故乡熟悉而又陌生的环境之中，一路迤逦行来，心情颇不平静：当年离家，风华正茂；今日返归，鬓毛疏落，不禁感慨系之。首句用“少小离家”与“老大回”的句中自对，概括写出数十年久客他乡的事实，暗寓自伤“老大”之情。次句以“鬓毛衰”顶承上句，具体写出自己的“老大”之态，并以不变的“乡音”映衬变化了的“鬓毛”，言下大有“我不忘故乡，故乡可还认得我吗”之意，从而为唤起下两句儿童不相识而发问作好铺垫。\n\n　　三四句从充满感慨的一幅自画像，转而为富于戏剧性的儿童笑问的场面。“笑问客从何处来”，在儿童，这只是淡淡的一问，言尽而意止；在诗人，却成了重重的一击，引出了他的无穷感慨，自己的老迈衰颓与反主为宾的悲哀，尽都包含在这看似平淡的一问中了。全诗就在这有问无答处悄然作结，而弦外之音却如空谷传响，哀婉备至，久久不绝。\n\n　　就全诗来看，一二句尚属平平，三四句却似峰回路转，别有境界。后两句的妙处在于背面敷粉，了无痕迹：虽写哀情，却借欢乐场面表现；虽为写己，却从儿童一面翻出。而所写儿童问话的场面又极富于生活的情趣，即使读者不为诗人久客伤老之情所感染，也不能不被这一饶有趣味的生活场景所打动。\n\n　　杨衡《对床夜语》诗云：“正是忆山时，复送归山客。”张籍云：“长因送人处，忆得别家时。”卢象《还家诗》云：“小弟更孩幼，归来不相识。”贺知章云：“儿童相见不相识，笑问客从何处来。”语益换而益佳，善脱胎者宜参之。\n\n　　第二首可看作是第一首的续篇。诗人到家以后，通过与亲朋的交谈得知家乡人事的种种变化，在叹息久客伤老之余，又不免发出人事无常的慨叹来。“离别家乡岁月多”，相当于上一首的“少小离家老大回”。诗人之不厌其烦重复这同一意思，无非是因为一切感慨莫不是由于数十年背井离乡引起。所以下一句即顺势转出有关人事的议论。“近来人事半消磨”一句，看似抽象、客观，实则包含了许多深深触动诗人感情的具体内容，“访旧半为鬼”时发出的阵阵惊呼，因亲朋沉沦而引出的种种嗟叹，无不包孕其中。唯其不胜枚举，也就只好笼而统之地一笔带过了。\n\n　　三四句笔墨荡开，诗人的目光从人事变化转到了对自然景物的描写上。镜湖，在今浙江绍兴会稽山的北麓，周围三百余里。贺知章的故居即在镜湖之旁。虽然阔别镜湖已有数十个年头，而在四围春色中镜湖的水波却一如既往。诗人独立镜湖之旁，一种“物是人非”的感触自然涌上了他的心头，于是又写下了“惟有门前镜湖水，春风不改旧时波”的诗句。诗人以“不改”反衬“半消磨”，以“惟有”进一步发挥“半消磨”之意，强调除湖波以外，昔日的人事几乎已经变化净尽了。从直抒的一二句转到写景兼议论的三四句，仿佛闲闲道来，不着边际，实则这是妙用反衬，正好从反面加强了所要抒写的感情，在湖波不改的衬映下，人事日非的感慨显得愈益深沉了。\n\n　　还需注意的是诗中的“岁月多”、“近来”、“旧时”等表示时间的词语贯穿而下，使全诗笼罩在一种低回沉思、若不胜情的气氛之中。与第一首相比较，如果说诗人初进家门见到儿童时也曾感到过一丝置身于亲人之中的欣慰的话，那么，到他听了亲朋介绍以后，独立于波光粼粼的镜湖之旁时，无疑已变得愈来愈感伤了。\n\n　　陆游说过：“文章本天成，妙手偶得之。”《回乡偶书二首》之成功，归根结底在于诗作展现的是一片化境。诗的感情自然、逼真，语言声韵仿佛自肺腑自然流出，朴实无华，毫不雕琢，读者在不知不觉之中被引入了诗的意境。像这样源于生活、发于心底的好诗，是十分难得的。', poem_tags = '生活,家乡,思念,岁月,伤感' WHERE poem_title = '回乡偶书二首' AND poem_author = '贺知章';
UPDATE edu_poem SET poem_translation = '流放岭南与亲人断绝了音信，熬过了冬天又经历一个新春。\n越走近故乡心里就越是胆怯，不敢打听从家那边过来的人。', poem_notes = '汉江：汉水。长江最大支流，源出陕西，经湖北流入长江。\n岭外：五岭以南的广东省广大地区，通常称岭南。唐代常作罪臣的流放地。书：信。\n来人：渡汉江时遇到的从家乡来的人。', poem_appreciation = '宋之问从泷州贬所逃回家乡，经过汉江(也就是汉水)时，写了这首诗。宋之问的家在巩县，汉水离巩县，虽然还有不少路，但较之岭外的泷州，毕竟要近得多，所以诗里说“近乡“。诗的语言，极为浅近通俗，但乍一读，仍不免会有疑惑。一个离开家乡已逾半年的游子，能踏上归途，自当心情欢悦，而且这种欣喜之情，也会随着家乡的越来越近而越来越强烈。宋之问却偏说“近乡情更怯“，乃至不敢向碰到的人询问家人的消息，这岂非有点不合情理?\n\n　　要解开这一疑团，必须重视诗的前两句，它们提供了必要的线索。诗人在到达贬所后，即与家人断绝了联系，且已持续了半年以上。在这种情况下，诗人的心境如何呢?诗中似未明言，其实不然。“近乡情更怯“，说明诗人早巳“情怯“。对家中情况的一无所知，使诗人的思虑中，增加了不安和疑惧:亲人们是否遭遇到什么不幸呢?空间的阻隔，时间的推移，使这种不安和疑惧，日趋沉重地郁结在诗人的心头。渡过汉水，离乡日近，但心中的恐惧也越来越沉重，因为不祥的猜测，有可能即将被证实。“不敢问“，不是“不想问“，诗人也想能尽早知道家人的消息。不过，假如能听到好消息，固然会无限欣喜，但万一相反呢?那么，期待着与家人团聚的喜悦，岂不将被这无情的消息一下子所粉碎?与其如此，不如听任这模糊不明再持续下去，因为毕竟还存在着一切皆好的希望啊。这种想问而又不敢问的矛盾心理，反映了诗人焦虑痛苦的心情。大诗人杜甫在战乱中与亲人分离，又音信不通，在《述怀》一诗中，写了这样几句;“自寄一封书，今已十月后。反畏消息来，寸心亦何有!“尽管诗人的身份不同，造成音书惭绝的原因不同，但矛盾痛苦的心情却完全相同。当然，这种独特的生活体验，不会人人都有;但这种特殊微妙的心理状态。却是大家都能理解，真实可信的。看似不合情理，其实只是情况特殊而已。\n\n　　以上这一思索，理解的过程，可以使我们对这首诗巧妙的抒情艺术，有更深刻的体会。诗人在用逐层递进的追述，交代了背景之后，立即直抒胸臆，不加保留地倾诉出矛盾心理和痛苦心情。但是，读者却必需经过一番认真的咀嚼，才能感受到这种特殊的心理状态，达到与作者的心灵沟通。这种高度简洁的抒情手法，使作品用最省略的语言，获取了极为深远的艺术效果。', poem_tags = '唐诗三百首,渡江,思乡' WHERE poem_title = '渡汉江' AND poem_author = '宋之问';
UPDATE edu_poem SET poem_translation = '孟子的母亲，世人称她孟母。过去孟子小时候，居住的地方离墓地很近，孟子学了些祭拜之类的事。他的母亲说：“这个地方不适合孩子居住。”于是将家搬到集市旁，孟子学了些做买卖和屠杀的东西。母亲又想：“这个地方还是不适合孩子居住。”又将家搬到学宫旁边。孟子学习会了在朝廷上鞠躬行礼及进退的礼节。孟母说：“这才是孩子居住的地方。”就在这里定居下来了。', poem_notes = '舍：家。\n墓间之事：指埋葬、祭扫死人一类的事。\n处子：安顿儿子。\n乃：于是，就。\n嬉：游戏，玩耍。\n贾（gǔ）人：商贩。\n炫卖：同“炫”，沿街叫卖，夸耀。\n徙：迁移。\n俎豆：古代祭祀用的两种盛器，此指祭礼仪式。\n徙居：搬家。\n及：等到。\n大儒：圣贤。\n揖让进退：即打拱作揖、进退朝堂等古代宾主相见的礼仪。\n揖：作揖。\n遂：最后。\n市：集市。\n居：家。\n卒：最终，终于。', poem_appreciation = '孟母教子的影响特别深远，早在西汉时期韩婴的《韩诗外传》中，就用有关孟母的故事来解释诗义，刘向的《列女传》中，首次出现了“孟母”这个专用名词。 东汉女史学家班昭曾作《孟母颂》，西晋女文学家左芬也作《孟母赞》。\n\n　　南宋时的启蒙课本《三字经》引证的第一个典故就是“昔孟母，择邻处，子不学，断机杼”，这一普及于封建社会后期的启蒙读物，虽经明、清学者陆续修订补充，而孟母三迁、断机教子的故事始终冠于篇首。\n\n　　山东监察御使钟化民《祭孟母文》赞扬道：“子之圣即母之圣”、“人生教子，志在青紫。夫人教子，志在孔子。古今以来，一人而已。”\n\n　　随着孟母故事的广泛流传，封建统治者也竭力将其塑造成符合其需要的偶像，封建皇帝对其屡加封谥，直到乾隆二年（1737年）加封孟母为“邾国端范宣献夫人”。', poem_tags = '小学文言文,教育,故事,寓理' WHERE poem_title = '孟母三迁' AND poem_author = '刘向';
UPDATE edu_poem SET poem_translation = '青苍的竹林寺，近晚时传来深远的钟声。\n背着斗笠披着斜阳，独回青山渐行渐远。', poem_notes = '灵澈上人：唐代著名僧人，本姓杨，字源澄，会稽（今浙江绍兴）人，后为云门寺僧。上人，对僧人的敬称。\n苍苍：深青色。竹林寺：在现在江苏丹徒南。\n杳（yǎo）杳：深远的样子。\n荷（hè）笠：背着斗笠。荷，背着。', poem_appreciation = '这首小诗记叙诗人在傍晚送灵澈返竹林寺时的心情，它即景抒情，构思精致，语言精炼，素朴秀美，是唐代山水诗的名篇。\n\n　　前二句想望苍苍山林中的灵澈归宿处，远远传来寺院报时的钟响，点明时已黄昏，仿佛催促灵澈归山。诗人出以想象之笔，创造了一个清远幽渺的境界。此二句重在写景，景中也寓之以情。后二句即写灵澈辞别归去情景。灵澈戴着斗笠，披带夕阳余晖，独自向青山走去，越来越远。“青山”即应首句“苍苍竹林寺”，点出寺在山林。“独归远”显出诗人伫立目送，依依不舍，结出别意。只写行者，未写送者，而诗人久久伫立，目送友人远去的形象仍显得非常生动。全诗表达了诗人对灵澈的深挚的情谊，也表现出灵澈归山的清寂的风度。送别多半黯然情伤，这首送别诗却有一种闲淡的意境，和作者的寂寞心情。\n\n　　刘长卿和灵澈相遇又离别于润州，大约在公元769—770年（唐代宗大历四、五年）间。刘长卿于公元761年（唐肃宗上元二年）从贬谪南巴（今广东茂名南）归来，一直失意待官，心情郁闷。灵澈此时诗名未著，云游江南，心情也不大得意，在润州逗留后，将返回浙江。一个宦途失意客，一个方外归山僧，在出世入世的问题上，可以殊途同归，同有不遇的体验，共怀淡泊的胸襟。这首小诗表现的就是这样一种境界。\n\n　　精美如画，是这首诗的明显特点。但这帧画不仅以画面上的山水、人物动人，而且以画外的诗人自我形象，令人回味不尽。那寺院传来的声声暮钟，触动诗人的思绪；这青山独归的灵澈背影，勾惹诗人的归意。耳闻而目送，心思而神往，正是隐藏在画外的诗人形象。他深情，但不为离别感伤，而由于同怀淡泊；他沉思，也不为僧儒殊途，而由于趋归意同。这就是说，这首送别诗的主旨在于寄托着、也表露出诗人不遇而闲适、失意而淡泊的情怀，因而构成一种闲淡的意境。十八世纪法国狄德罗评画时说过：“凡是富于表情的作品可以同时富于景色，只要它具有尽可能具有的表情，它也就会有足够的景色。”（《绘画论》）此诗如画，其成功的原因亦如绘画，景色的优美正由于抒情的精湛。', poem_tags = '唐诗三百首,初中古诗,送别,即景抒情,山水' WHERE poem_title = '送灵澈上人' AND poem_author = '刘长卿';
UPDATE edu_poem SET poem_translation = '有个担忧他的禾苗长不高而把禾苗往上拔的春秋宋国人，一天下来十分疲劳地回到家，对他的家人说：“今天累坏了，我帮助禾苗长高了！”他儿子小步奔去看那禾苗的情况，禾苗却都枯萎了。天下不希望自己禾苗长得快一些的人很少啊！以为禾苗长大没有用处而放弃的人，就像是不给禾苗锄草的懒汉。妄自帮助它生长的人，就像这个拔苗助长的人，不但没有好处，反而害了它。', poem_notes = '闵（mǐn）：同“悯”，担心，忧虑。\n长（zhǎng）：生长，成长。\n揠（yà）：拔。\n茫茫然：疲惫不堪的样子。\n谓：对,告诉。\n其人：他家里的人。\n病：疲劳，困苦，精疲力尽，文中是引申义\n予（余）：我，第一人称代词。\n趋：快步走。\n往：去，到..去。\n槁（gǎo）：草木干枯，枯萎。\n之：放在主谓之间，取消句子独立性，无实义，不译。\n寡：少。\n耘苗：给苗锄草。\n非徒：非但。徒，只是。\n益：好处。\n孟子：战国思想家、政治家、教育家。有“亚圣”之称。', poem_tags = '小学文言文,寓言,故事,哲理' WHERE poem_title = '揠苗助长' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '等到秋天九月重阳节来临的时候，菊花盛开以后别的花就凋零了。\n盛开的菊花璀璨夺目，阵阵香气弥漫长安，满城均沐浴在芳香的菊意中，遍地都是金黄如铠甲般的菊花。', poem_notes = '不第：科举落第。\n九月八：九月九日为重阳节，有登高赏菊的风俗，说“九月八”是为了押韵。\n杀：草木枯萎。《吕氏春秋·应同》：“及禹之时，天先见草木秋冬不杀。”\n黄金甲：指金黄色铠甲般的菊花。', poem_appreciation = '黄巢流传下来的三首诗中，有两首是以菊花为题材的咏物诗。其中，《题菊花》写道：“飒飒西风满院栽，蕊寒香冷蝶难来。他年我若为青帝，报与桃花一处开。”表现了他顽强的斗争精神和必胜信念。这首《不第后赋菊》的境界比《题菊花》更雄伟、豪迈。在这首诗中，诗人运用比喻的手法，赋予菊花以农民起义军的英雄风貌与高洁品格。\n\n　　首句“待到秋来九月八”，意思是重阳佳节未到，而诗人即赋诗遥庆之。“待到”二字迸发突兀，“骤响如爆竹”，具有凌厉、激越的韵致和可望在即的肯定意味。“九月八”在重阳节的前一天，从诗情奔腾的湍流来考察，诗人不写“九月九”而写“九月八”，并不仅仅是为了押韵，而且还透露出一种迫不及待，呼唤革命暴风雨早日来到的情绪。\n\n　　次句“我花开后百花杀”，一方面向读者展示了一种不可抗御的自然规律，用金菊傲霜盛开与百花遇霜而凋所造成的强烈对比，显示出菊花生机盎然的顽强生命力，一方面暗示了农民革命风暴一旦来临，腐败的唐王朝立刻就会像“百花”遇霜一样，变成枯枝败叶。\n\n　　第三、四句“冲天香阵透长安，满城尽带黄金甲”，则是对菊花胜利远景的预见和憧憬。第三句写味，“冲天香阵透长安”，这香，不是幽香，不是清香，而是“冲天香阵”。“冲天”二字，写出了菊花香气浓郁、直冲云天的非凡气势；“香阵”二字说明金菊胜利时决非一枝独放，而是群体皆荣，包含了朴素而深刻的天下太平观念；一个“透”字，又显示了菊花香气沁人心脾、芳贯广宇、无所不至的进取精神。\n\n　　第四句“满城尽带黄金甲”，“满城”是说菊花无处不有，遍满京都；“尽带”是说这遍满长安的菊花，无一例外地全都披上了黄金甲。“满”、“尽”二字，则状摹出菊花夺魁天下时的奇观——重阳佳节，菊花盛开，整个长安成了菊花的世界，这就充分展示出农民革命风暴摧旧更新、主宰一切的胜利前景。\n\n　　菊花，历来被视为华夏的国花，咏菊花而写不出国魂者，皆下品。黄巢的这首诗托物言志，借咏菊以抒抱负，境界瑰丽，气魄恢宏，笔势刚劲，格调雄迈，成功地塑造了抒情主人公那身披甲胄，手擎长剑，气冲霄汉的英雄形象，诸如“我花开后百花杀”、“满城尽带黄金甲”等句，语调斩截，气势凌厉，对后世许多有志之士的思想产生了积极影响。', poem_tags = '咏物,菊花,品格,抱负' WHERE poem_title = '不第后赋菊' AND poem_author = '黄巢';
UPDATE edu_poem SET poem_translation = '袅袅的东风吹动了淡淡的云彩，露出了月亮，月光也是淡淡的。花朵的香气融在朦胧的雾里，而月亮已经移过了院中的回廊。\n由于只是害怕在这深夜时分，花儿就会睡去，因此燃着高高的蜡烛，不肯错过欣赏这海棠盛开的时机。', poem_notes = '东风：春风。袅袅：微风轻轻吹拂的样子。一作“渺渺”。泛：摇动。崇光：高贵华美的光泽，指正在增长的春光。\n空蒙：一作“霏霏”。\n夜深花睡去：暗引唐玄宗赞杨贵妃“海棠睡未足耳”的典故。史载，昔明皇召贵妃同宴，而妃宿酒未醒，帝曰：“海棠睡未足也。”\n故：于是。红妆：用美女比海棠。故烧高烛照红妆：一作“高烧银烛照红妆”。', poem_appreciation = '此诗开头两句，并不拘限于正面描写。首句“东风袅袅”形容春风的吹拂之态，化用了《楚辞·九歌·湘夫人》中的“袅袅兮秋风”之句。着一“泛”字，活写出春意的暖融，这为海棠的盛开造势。次句侧写海棠，“香雾空蒙”写海棠阵阵幽香在氤氲的雾气中弥漫开来，沁人心脾。“月转廊”，月亮已转过回廊那边去了，照不到这海棠花；暗示夜已深，人无寐，从中还可读出一层隐喻：处江湖之僻远，不遇君王恩宠。这两句把读者带入一个空濛迷幻的境界，十分艳丽，然而略显幽寂。\n\n　　后两句，作者由花及人，生发奇想，深切巧妙地表达了爱花惜花之情。“只恐夜深花睡去”，这一句写得痴绝，是全诗的关键句。此句转折一笔，写赏花者的心态。当月华再也照不到海棠的芳容时，诗人顿生满心怜意：海棠如此芳华灿烂，不忍心让她独自栖身于昏昧幽暗之中。一个“恐”写出了作者不堪孤独寂寞的煎熬而生出的担忧、惊怯之情，也暗藏了作者欲与花共度良宵的执著。一个“只”字极化了爱花人的痴情，此刻他满心里只有这花儿璀璨的笑靥，其余的种种不快都可暂且一笔勾销了：这是一种“忘我”、“无我”的超然境界。\n\n　　末句更进一层，将爱花的感情提升到一个极点。“故”照应上文的“只恐”二字，含有特意而为的意思，表现了诗人对海棠的情有独钟。宋释惠洪《冷斋夜话》记载：唐明皇登香亭，召太真妃，于时卯醉未醒，命高力士使待儿扶掖而至。妃子醉颜残妆，鬓乱钗横，不能再拜。明皇笑日：“岂妃子醉，直海棠睡未足耳！”此句运用唐玄宗以杨贵妃醉貌为“海棠睡未足”的典故，转而以花喻人，点化入咏，浑然无迹。\n\n　　“烧高烛”遥承上文的“月转廊”，这是一处精彩的对比，月光似乎也太嫉妒于这怒放的海棠的明艳了，那般刻薄寡恩，竟然不肯给她一方展现姿色的舞台。于是作者用高烧的红烛，为她驱除这长夜的黑暗。此处隐约可见诗人的侠义与厚道。“照红妆”呼应前句的“花睡去”三字，极写海棠的娇艳妩媚。“烧”“照”两字表面上都写作者对花的喜爱与呵护，其实也不禁流露出些许贬居生活的郁郁寡欢。他想在“玩物”（赏花）中获得对痛苦的超脱，哪怕这只是片刻的超脱也好。虽然花儿盛开了，就向衰败迈进了一步，尽管高蹈的精神之花毕竟远离了现实的土壤，但他想过这种我行我素、自得其乐的生活的积极心态，没有谁可以阻挠。\n\n　　全诗语言浅近而情意深永。写此诗时，诗人虽已过不惑之年，但此诗却没有给人以颓唐、萎靡之气，从“东风”“崇光”“香雾”“高烛”“红妆”这些明丽的意象中分明可以感触到诗人的达观、潇洒的胸襟。', poem_tags = '古诗三百首,初中古诗,赏花' WHERE poem_title = '海棠' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '你走啊走啊老是不停的走，就这样活生生分开了你我。\n从此你我之间相距千万里，我在天这头你就在天那头。\n路途那样艰险又那样遥远，要见面可知道是什么时候？\n北马南来仍然依恋着北风，南鸟北飞筑巢还在南枝头。\n彼此分离的时间越长越久，衣服越发宽大人越发消瘦。\n飘荡游云遮住了太阳，他乡的游子不想回还。\n只因为想你使我都变老了，又是一年很快地到了年关。\n还有许多心里话都不说了，只愿你多保重切莫受饥寒。', poem_notes = '重（chóng崇）：又。这句是说行而不止。\n生别离：是“生离死别”的意思。屈原《九歌·少司命》：“悲莫悲兮生别离。”\n相去：相距，相离。\n涯：方。\n阻：艰险。\n胡马：北方所产的马。\n越鸟：南方所产的鸟。“胡马倚北风，越鸟朝南枝”，是当时习用的比喻，借喻眷恋故乡的意思。\n已：同“以”。\n远：久。\n缓：宽松。这句意思是说，人因相思而躯体一天天消瘦。\n顾返：还返，回家。顾，返也。\n“老”，并非实指年龄，而指消瘦的体貌和忧伤的心情，是说心身憔悴，有似衰老而已。\n“晚”，指行人未归，岁月已晚，表明春秋忽代谢，相思又一年，暗喻青春易逝\n弃捐：抛弃。\n这两句的意思是说这些都丢开不必再说了，只希望你在外保重；一说是指这些都丢开不必再说，自己要努力保重自己，以待后日相会。', poem_appreciation = '这是一首在东汉末年动荡岁月中的相思乱离之歌。尽管在流传过程中失去了作者的名字，但“情真、景真、事真、意真”（陈绎《诗谱》），读之使人悲感无端，反复低徊，为女主人公真挚痛苦的爱情呼唤所感动。\n\n　　首句五字，连叠四个“行”字，仅以一“重”字绾结。“行行”言其远，“重行行”极言其远，兼有久远之意，翻进一层，不仅指空间，也指时间。于是，复沓的声调，迟缓的节奏，疲惫的步伐，给人以沉重的压抑感，痛苦伤感的氛围，立即笼罩全诗。“与君生别离”，这是思妇“送君南浦，伤如之何”的回忆，更是相思之情再也压抑不住发出的直白的呼喊。诗中的“君”，当指女主人公的丈夫，即远行未归的游子。\n\n　　与君一别，音讯茫然：“相去万余里”。相隔万里，思妇以君行处为天涯；游子离家万里，以故乡与思妇为天涯，所谓“各在天一涯”也。“道路阻且长”承上句而来，“阻”承“天一涯”，指路途坎坷曲折；“长”承“万余里”，指路途遥远，关山迢递。因此，“会面安可知”！当时战争频仍，社会动乱，加上交通不便，生离犹如死别，当然也就相见无期。\n\n　　然而，别离愈久，会面愈难。诗人在极度思念中展开了丰富的联想：凡物都有眷恋乡土的本性：“胡马依北风，越鸟巢南枝。”飞禽走兽尚且如此，何况人。这两句用比兴手法，突如其来，效果远比直说更强烈感人。表面上喻远行君子，说明物尚有情，人岂无思的道理，同时兼暗喻思妇对远行君子深婉的恋情和热烈的相思：胡马在北风中嘶鸣了，越鸟在朝南的枝头上筑巢了，游子啊，你还不归来啊！“相去日已远，衣带日已缓”，思妇说：自别后，我容颜憔悴，首如飞蓬，自别后，我日渐消瘦，衣带宽松，游子啊，你还不归来啊！正是这种心灵上无声的呼唤，才越过千百年，赢得了人们的旷世同情和深深的惋叹。\n\n　　如果稍稍留意，至此，诗中已出现了两次“相去”。第一次与“万余里”组合，指两地相距之远；第二次与“日已远”组合，指夫妻别离时间之长。相隔万里，日复一日，是忘记了当初旦旦誓约，还是为他乡女子所迷惑，正如浮云遮住了白日，使明净的心灵蒙上了一片云翳。“浮云蔽白日，游子不顾反”，这使女主人公忽然陷入深深的苦痛和彷惶之中。诗人通过由思念引起的猜测疑虑心理“反言之”，思妇的相思之情才愈显刻骨，愈显深婉、含蓄，意味不尽。\n\n　　猜测、怀疑，当然毫无结果；极度相思，只能使形容枯槁。这就是“思君令人老，岁月忽已晚。”“老”，并非实指年龄，而指消瘦的体貌和忧伤的心情，是说心身憔悴，有似衰老而已。“晚”，指行人未归，岁月已晚，表明春秋忽代谢，相思又一年，暗喻女主人公青春易逝，坐愁红颜老的迟暮之感。\n\n　　坐愁相思了无益,与其憔悴自弃，不如努力加餐，保重身体，留得青春容光，以待来日相会。故诗最后说：“弃捐勿复道，努力加餐饭。至此，诗人以期待和聊以自慰的口吻，结束了她相思离乱的歌唱。\n\n　　诗中淳朴清新的民歌风格，内在节奏上重叠反复的形式，同一相思别离用或显、或寓、或直、或曲、或托物比兴的方法层层深入，“若秀才对朋友说家常话”式单纯优美的语言，正是这首诗具有永恒艺术魅力的所在。而首叙初别之情——次叙路远会难——再叙相思之苦——末以宽慰期待作结。离合奇正，现转换变化之妙。不迫不露、句意平远的艺术风格，表现出东方女性热恋相思的心理特点。', poem_tags = '古诗三百首,古诗十九首,女子,离别,相思' WHERE poem_title = '行行重行行' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '您难道不曾看见吗？那辽阔的走马川紧靠着雪海边缘，茫茫无边的黄沙连接云天。\n轮台九月整夜里狂风怒号，到处的碎石块块大如斗，狂风吹得斗大乱石满地走。\n这时匈奴牧草繁茂军马肥，侵入金山西面烟尘滚滚飞，汉家的大将率兵开始征西。\n将军身著铠甲夜里也不脱，半夜行军戈矛彼此相碰撞，凛冽寒风吹到脸上如刀割。\n马毛挂着雪花还汗气蒸腾，五花马的身上转眼结成冰，营幕中写檄文砚墨也冻凝。\n敌军听到大军出征应胆惊，料他不敢与我们短兵相接，我就在车师西门等待报捷。', poem_notes = '马川：即车尔成河，又名左未河，在今新疆境内。行：诗歌的一种体裁。封大夫（dà fū）：即封常清，唐朝将领，蒲州猗氏人，以军功擢安西副大都护、安西四镇节度副大使、知节度事，后又升任北庭都护，持节安西节度使。西征：一般认为是出征播仙。\n走马川行雪海边：一作“走马沧海边”。雪海：在天山主峰与伊塞克湖之间。\n轮台：地名，在今新疆米泉境内。封常清军府驻在这里。\n匈奴：借指达奚部族。\n金山：指天山主峰。\n汉家：唐代诗人多以汉代唐。汉家大将：指封常清，当时任安西节度使兼北庭都护，岑参在他的幕府任职。\n戈相拨：兵器互相撞击。\n五花：即五花马。连钱：一种宝马名。五花连钱：指马斑驳的毛色。\n草檄（xí）：起草讨伐敌军的文告。\n短兵：指刀剑一类武器。\n车师：为唐北庭都护府治所庭州，今新疆乌鲁木齐东北。蘅塘退士本作“军师”。伫：久立，此处作等待解。献捷：献上贺捷诗章。', poem_appreciation = '岑参诗的特点是意奇语奇，尤其是边塞之作，奇气益著。《白雪歌送武判官归京》是奇而婉，侧重在表现边塞绮丽瑰异的风光，给人以清新俊逸之感；这首诗则是奇而壮，风沙的猛烈、人物的豪迈，都给人以雄浑壮美之感。诗人在任安西北庭节度判官时，封常清出兵去征播仙，他便写了这首诗为封送行。\n\n　　为了表现边防将士高昂的爱国精神，诗人用了反衬手法，抓住有边地特征的景物来状写环境的艰险，极力渲染、夸张环境的恶劣，来突出人物不畏艰险的精神。诗中运用了比喻、夸张等艺术手法，写得惊心动魄，绘声绘色，热情奔放，气势昂扬。\n\n　　首先围绕“风”字落笔，描写出征的自然环境。这次出征将经过走马川、雪海边，穿进戈壁沙漠。“平沙莽莽黄入天”，这是典型的绝域风沙景色，狂风怒卷，黄沙飞扬，遮天蔽日，迷迷蒙蒙，一派混沌的景象。开头三句无一“风”字，但捕捉住了风“色”，把风的猛烈写得历历在目。这是白天的景象。\n\n　　“轮台九月风夜吼，一川碎石大如斗，随风满地石乱走。”对风由暗写转入明写，行军由白日而入黑夜，风“色”是看不见了，便转到写风声。狂风像发疯的野兽，在怒吼，在咆哮，“吼”字形象地显示了风猛风大。接着又通过写石头来写风。斗大的石头，居然被风吹得满地滚动，再著一“乱”字，就更表现出风的狂暴。“平沙莽莽”句写天，“石乱走”句写地，三言两语就把环境的险恶生动地勾勒出来了。\n\n　　下面写匈奴利用草黄马肥的时机发动了进攻，“金山西见烟尘飞”中“烟尘飞”三字，形容报警的烽烟同匈奴铁骑卷起的尘土一起飞扬，既表现了匈奴军旅的气势，也说明了唐军早有戒备。下面，诗由造境转而写人，诗歌的主人公——顶风冒寒前进着的唐军将士出现了。诗人很善于抓住典型的环境和细节来描写唐军将士勇武无敌的飒爽英姿。如环境是夜间，“将军金甲夜不脱”，以夜不脱甲，写将军重任在肩，以身作则。“半夜军行戈相拨”写半夜行军，从“戈相拨”的细节可以想见夜晚一片漆黑，和大军衔枚疾走、军容整肃严明的情景。写边地的严寒，不写千丈之坚冰，而是通过几个细节来描写来表现的。“风头如刀面如割”，呼应前面风的描写；同时也是大漠行军最真切的感受。\n\n　　“马毛带雪汗气蒸，五花连钱旋作冰。”战马在寒风中奔驰，那蒸腾的汗水，立刻在马毛上凝结成冰。诗人抓住了马身上那凝而又化、化而又凝的汗水进行细致的刻画，以少胜多，充分渲染了天气的严寒，环境的艰苦和临战的紧张气氛。“幕中草檄砚水凝”，军幕中起草檄文时，发现连砚水也冻结了。诗人巧妙地抓住了这个细节，笔墨酣畅地表现出将士们斗风傲雪的战斗豪情。这样的军队必然无人能敌。这就引出了最后三句，料想敌军闻风丧胆，预祝凯旋而归，行文就象水到渠成一样自然。\n\n　　全篇奇句豪气，风发泉涌，由于诗人有边疆生活的亲身体验，因而此诗能“奇而入理”，“奇而实确”，真实动人。\n\n　　全诗句句用韵，除开头两句外，三句一转韵，这在七言古诗中是不多见的。全诗韵位密集，换韵频数，节奏急促有力，情韵灵活流宕，声调激越豪壮，有如音乐中的进行曲。', poem_tags = '唐诗三百首,初中古诗,边塞,送别,写风,写马,赞美,将士' WHERE poem_title = '走马川行奉送出师西征 / 走马川行奉送封大夫出师西征' AND poem_author = '岑参';
UPDATE edu_poem SET poem_translation = '昨夜，寒秋蟋蟀不住哀鸣，梦回故乡，千里燃战火，被惊醒，已三更。站起身，独绕台阶踽踽行。四周静悄悄，帘外，一轮淡月正朦胧。\n为国建功留青史，未老满头霜星星。家山松竹苍然老，无奈议和声起、阻断了归程。想把满腹心事，付与瑶琴弹一曲。可可高山流水知音稀，纵然弦弹断，又有谁来听？', poem_notes = '小重山：词牌名。一名《小冲山》、《柳色新》、《小重山令》。唐人常用此调写宫女幽怨。《词谱》以薛昭蕴词为正体。五十八字。上下片各四句，四平韵。换头句较上片起句少二字，其余各句上下片均同。另有五十七字、六十字两体，是变格。\n寒蛩（qióng）：秋天的蟋蟀。\n千里梦：指赴千里外杀敌报国的梦。\n三更：指半夜十一时至翌晨一时。\n月胧明：月光不明。胧，朦胧。\n功名：此指为驱逐金兵的入侵，收复失地而建功立业。\n旧山：家乡的山。\n付：付与。\n瑶（yáo）琴：饰以美玉的琴。\n知音：比喻知己，同志。', poem_appreciation = '这首《小重山》虽然没有《满江红》家喻户晓，但是通过不同的风格特点和艺术手法表达了作者隐忧时事的爱国情怀。\n\n　　上片着重写景。“昨夜寒蛩不住鸣。惊回千里梦，已三更”，昨天夜里蟋蟀一直鸣叫不停，使作者从金戈铁马对抗金兵的梦中惊醒了，而此时已经是深夜的三更天了。“寒蛩”点明了季节是深秋。山河飘摇，国家残破，作者夙夜忧患，而昨夜深秋的蟋蟀却小停地呜叫，催逼着词人心中的隐忧和悲愤，使克复中原的责任更加沉重，“惊”字充分表达了在秋夜蟋蟀的凄清呜叫中作者终夜难眠的情景。“千里”暗示梦回到包括家乡在内的中原地区，说明了词人在睡梦之中也不忘收复中原的爱国之情。这一句通过叙写被梦惊醒来表现作者日夜牵挂的都是国家的战事和兴衰。“起来独自绕阶行。人悄悄，帘外月胧明”，被梦惊醒后，因梦见战场战事而忧国忧民再无睡意，独自在台阶前徘徊。周围静悄悄的，人们都在熟睡，只有天上的明月散下淡淡的冷光。深秋的月夜，凄清冷淡，表达了作者“众人皆醉我独醒，举世皆浊我独清”的孤独与凄凉心境。“独自”写出词人的孤独寂寞，心事无法向人诉说，可见苦闷之深。结拍“人悄悄，帘外月胧明”以景收束上片，映衬词人不能成眠，更见孤独之感。上阕用简洁的语言和平淡的叙述质朴地展现出作者所面临的困境，其简沽有力、朴素真切的文风，确实展现出一代英雄的真性情和其所面对的历史情景的复杂性。\n\n　　词的下片重在抒情。“白首为功名”写词人终其一生渴望为国建功立业，痴心不改。“旧山松竹老”用松竹喻中原父老，他们在金人的统治之下，顽强挺立，渴望早日复国，可如今他们都已老了，暗示了南渡时间之长。“阻归程”写投降派的求和主张阻挡了收复中原，回归故乡的进程，隐含了词人的痛心。如今头发已经白了，几十年的求索，都是为了驱逐金人，收复河山。作者竭尽心力，几操心成白发，都只是为了矢志北伐，匡扶宋室，收复河山，成千古功名，成一代情怀。然而，十多年的等待、十多年的期盼、十多年的转战努力，便是为了某一天的“归程”。可是英雄的壮志难酬，想到了故乡，家乡的树木已经变得老了，而到头来却得到一个宋金和议的结局。作者多年矢志北伐的壮志难酬，忧愤难平。宋朝皇帝赵构与秦桧力图议和偏安，不迎回徽、钦二帝，国家也遭受未有之变局。既然不能建功立业，收复河山，回家度过余生也好。可是故乡已经落到敌人的手里，有家难归。“欲将心事付瑶琴。知音少，弦断有谁听”，这里化用善于操琴的俞伯牙和知音钟子期的典故寄托作者的一腔愤懑和无处言说的沉痛，来表达苦闷的心情，将自己的心事寄托于琴弦，可是却没有知音，就是把琴弦弹断了也没有人来听。当时作者主张抗金，收复失地，但是朝野上下一片议和声，使作者陷入孤掌难鸣的处境，不禁担忧起国家的未来和命运，心情沉重。\n\n　　上片是即景抒情，寓情于景，忧国忧民使他愁怀难遣，在凄清的月色下独自徘徊。下片写他收复失地受阻，要抗金却是“知音少”，内心郁闷焦急，用了比兴手法。作者隐忧时事，吞吐曲折，委婉含蓄，流露出悲凉悱恻之思。全词所展现的沉郁悲怆情怀，节制而深层，忧思而压抑。至其《小重山》词，则真有寄托之作也。故国怕回首，而托诸惊梦；所愿不得偿，则托诸空阶明月；咎忠贞不见谅于当轴，致坐失机宜，而托诸瑶琴独奏，赏音无人。盖托体比兴也”，如此评断，亦可谓知套岳帅之良苦用心也。\n\n　　从写作手法说，《满江红·怒发冲冠》多用赋体，直陈其事，慷慨激昂，凝聚着岳飞忠贞报国的豪迈精神和战斗雄姿。这首《小重山》则多用比喻，曲折地道出心事，含蓄委婉，抑扬顿挫，情景交融，艺术手法是很高超的。这首词虽然短小。但含蓄隽永，明丽婉转，寓情于景，深切地表达了作者壮志难酬和忧国忧民的悲苦心境。\n\n　　另外，虽然这首《小重山》写得比较含蓄委婉，与同为岳飞所作的《满江红·怒发冲冠》格调有所不同，但在思想内容方面仍有其内在的统一性。后两首表现的是抗击金兵，收复中原；这首表现的则是不满“和议”，反对投降。这两方面的主题是完全统一的，统一的基础就是岳飞反对民族压迫、反对投降主义的坚定立场，热爱国家、热爱民族的深厚感情。由于写作的时间和历史背景不同，因而在情调和风格上产生了差异，这也是可以理解的。', poem_tags = '宋词三百首,宋词精选,豪放,壮志难酬' WHERE poem_title = '小重山·昨夜寒蛩不住鸣' AND poem_author = '岳飞';
UPDATE edu_poem SET poem_translation = '褒禅山也称为华山。唐代和尚慧褒当初在这里筑室居住，死后又葬在那里；因为这个缘故，后人就称此山为褒禅山。如今人们所说的慧空禅院，就是慧褒和尚的墓舍。距离那禅院东边五里，是人们所说的华山洞，因为它在华山南面而这样命名。距离山洞一百多步，有一座石碑倒在路旁，上面的文字已被剥蚀、损坏近乎磨灭，只有从勉强能认得出的地方还可以辨识出“花山”的字样。如今将“华”读为“华实”的“华”，是（因字同而产生的）读音上的错误。\n\n　　由此向下的那个山洞平坦而空阔，有一股山泉从旁边涌出，在这里游览、题记的人很多，（这就）叫做“前洞”。经由山路向上五六里，有个洞穴，一派幽深的样子，进去便（感到）寒气逼人，打问它的深度，就是那些喜欢游险的人也未能走到尽头——这是人们所说的“后洞”。我与四个人打着火把走进去，进去越深，前进越困难，而所见到的景象越奇妙。有个懈怠而想退出的伙伴说：“再不出去，火把就要熄灭了。”于是，只好都跟他退出来。我们走进去的深度，比起那些喜欢游险的人来，大概还不足十分之一，然而看看左右的石壁，来此而题记的人已经很少了。洞内更深的地方，大概来到的游人就更少了。当决定从洞内退出时，我的体力还足够前进，火把还能够继续照明。我们出洞以后，就有人埋怨那主张退出的人，我也后悔跟他出来，而未能极尽游洞的乐趣。\n\n　　对于这件事我有所感慨。古人观察天地、山川、草木、虫鱼、鸟兽，往往有所得益，是因为他们探究、思考深邃而且广泛。平坦而又近的地方，前来游览的人便多；危险而又远的地方，前来游览的人便少。但是世上奇妙雄伟、珍异奇特、非同寻常的景观，常常在那险阻、僻远，少有人至的地方，所以，不是有意志的人是不能到达的。（虽然）有了志气，也不盲从别人而停止，但是体力不足的，也不能到达。有了志气与体力，也不盲从别人、有所懈怠，但到了那幽深昏暗而使人感到模糊迷惑的地方却没有必要的物件来支持，也不能到达。可是，力量足以达到目的（而未能达到），在别人（看来）是可以讥笑的，在自己来说也是有所悔恨的；尽了自己的主观努力而未能达到，便可以无所悔恨，这难道谁还能讥笑吗？这就是我这次游山的收获。\n\n　　我对于那座倒地的石碑，又感叹古代刻写的文献未能存留，后世讹传而无人弄清其真相的事，哪能说得完呢？这就是学者不可不深入思考而谨慎地援用资料的缘故。\n\n　　同游的四个人是：庐陵人萧君圭，字君玉；长乐人王回，字深甫；我的弟弟王安国，字平甫；王安上，字纯甫。至和元年七月，临川人王安石记。', poem_notes = '浮图：梵（fàn）语（古印度语）音译词，也写作“浮屠”或“佛图”，本意是佛或佛教徒，这里指和尚。慧褒：唐代高僧。舍：名词活用作动词，建舍定居。址：地基，基部，基址，这里指山脚。\n而：连词，并且。卒：最终。之：指褒禅山麓。\n以故：因为（这个）缘故，译为“因此”。名：命名，动词。禅：梵语译音“禅那”的简称，意思是“静思”，指佛家追求的一种境界。后来泛指有关佛教的人和事物，如禅师、禅子、坐禅、禅房、禅宗、禅林、禅杖等。褒禅，慧褒禅师。\n慧空禅院：寺院名。庐冢（zhǒng）：古时为了表示孝敬父母或尊敬师长，在他们死后的服丧期间，为守护坟墓而盖的屋舍，也称“庐墓”。这里指慧褒弟子在慧褒墓旁盖的屋舍。庐：屋舍。（一说指慧褒生前的屋舍。)冢：坟墓。禅院：佛寺。\n华山洞：南宋王象生《舆地纪胜》写作“华阳洞”，看正文下出应写作“华阳洞”。以：因为。乃：表示判断，有“为”、“是”的意思。阳：山的南面。古代称山的南面、水的北面为“阳”，山的背面、水的南面为“阴”。名：命名，动词。\n仆道：“仆（于）道”的省略，倒在路旁。\n文：碑文，与下文“独其为文（碑上残存的文字）”的“文”不同。漫灭：指因风化剥落而模糊不清。\n独：唯独，只有。其：指代石碑。文：文字，这里指的是碑上残存的文字。犹：还，仍。\n今言“华”(huā)如“华(huá)实”之“华(huá)”者，盖音谬也：汉字最初只有“华(huā)”字，没有“花”字，后来有了“花”字，“华”“花”分家，“华”才读为huá。（王安石认为碑文上的“花”是按照“华”的古音而写的今字，仍应读huā，而不应读“华(huá奢侈、虚浮)实”的huá。按，这里说的不是五岳中的“华(huà)山”）。言：说。盖：承接上文，解释原因，有“大概因为”的意思。谬：错误。\n侧出：从旁边涌出，记游：指在洞壁上题诗文留念。\n上：名词活用作动词，向上走。窈（yǎo）然：深远幽暗的样子。\n问：探究，追究。深，形容词活用作名词，深度。则：副词，用于判断句表示肯定,相当于“就”。穷：穷尽。\n拥火：拿着火把。拥，持，拿。以：连词，连接状语与中心词。\n见：动词活用作名词，见到的景象。\n怠：懈怠。且：副词，将，将要。\n盖：表猜测的发语词，大概。尚：还。不能十一：不及十分之一。不能：不及，不到。\n而：表递进的连词，并且，而且。\n则：表假设的连词，那么。至：动词活用作名词，到达的人。加：更，更加。\n方是时：正当这个时候。方：当，正在。是时：指决定从洞中退出的时候。\n以：相当于“而”，连词，连接状语与中心词。明：形容词或用作动词，照明。\n既：已经，……以后。其：助词。\n则：副词，就，便，表示前后两事紧密相承或时间相距很近。或：有人。咎（jiù）：责怪。其：那，那些。\n其：第一人称代词，指自己。而：连词，表结果，以致，以至于。不得：不能，极：尽，这里有尽情享受的意思，形容词活用作动词。夫：这，那，指示代词。\n于是：对于这种情况，因此。焉：句末语气词。\n之：用于主谓之间，取消句子的独立性，可不译。得：心得，收获。\n以：因为。求思：探求、思索。而：连词，表递进，而且。无不在：无所不在，没有不探索、思考的，指思考问题广泛全面。\n夫：表议论的发语词。夷：平坦。以：连词，表并列，而且，并且。则：表假设的连词，那么。\n而：可是。观：景象，景观。险远，形容词活用作名词，险远的地方。\n而：因而。焉：兼词，相当于“于此”。\n随：跟随（别人），“随”字后面省略“之”。以：连词，表结果，以致，以至于。\n至于：这里是抵达、到达的意思，不同于现代汉语用在下文开头，表示提出另一话题。幽暗昏惑：幽深昏暗，叫人迷乱（的地方）。昏惑：迷乱。以：连词，表目的。相（xiàng）：帮助，辅助。\n以：相当于“而”，连词，连接状语与中心词。焉：兼词，相当于“于此”。这一句在“焉”后面省略了“而不至”。\n于人：在别人（看来）。为：是。\n其：加强反问语气的副词，难道。孰：谁。\n得：心得，收获。\n谬其传：把那些（有关的）传说弄错。谬，使……谬误，把……弄错。莫能名：不能说出真相（一说真名）。\n何可胜道：怎么能说得完。胜，尽。\n所以：表示“……的原因”。慎取：谨慎取舍。\n以：以（之），因此。悲：叹息\n庐陵：今江西吉安。萧君圭，字君玉。\n长乐：今福建长乐。王回，字深父。父：通“甫”，下文的“平父”“纯父”的“父”同。\n安国平父、安上纯父：王安国，字平父。王安上，字纯父。\n至和元年：公元年。至和：宋仁宗的年号。临川：今江西临川。王某：王安石。古人作文起稿，写到自己的名字，往往只作“某”，或者在“某”上冠姓，以后在誊写时才把姓名写出。根据书稿编的文集，也常常保留“某”的字样。', poem_appreciation = '该文写于宋仁宗至和元年（1054）七月某日，是作者与他的两位朋友和两个胞弟同游褒禅山后所写。这是一篇记述与议论相结合的散文，与一般游记不同，独具特色。全文按照记叙和议论的层次，可分五段。\n\n　　从篇首至“盖音谬也”。记述褒禅山命名的由来。文章开头紧扣题目，开门见山地先说明褒禅山又叫华山之后，接着追述之所以命名为褒禅山，是因为唐朝有一个名叫慧褒的和尚，一开始住在华山之下，死后又葬在华山之下，所以叫做褒禅。作者由远及近，当追溯了褒禅山命名的由来之后，就把笔墨转向眼前所见的慧空禅院上来。说明如今看到的慧空禅院，就是当年慧褒禅师居住的房舍和坟墓之所在。因为这毕竟是一篇游记，所以当写到慧空禅院之后，便以它为基点，重点突出地来记叙褒禅山的名胜华山洞。“距其院东五里，所谓华山洞者，以其乃华山之阳名之也”。这三句，说明华山洞的方位及其命名的由来。接着又写距华山洞百余步倒在路旁的石碑，以及碑文的情况。“其文漫灭”一句，从字面上来看，是说由于年代久远，字迹已经模糊不清。其实，也是为了突出其中尚可辨识的“花山”二字。之所以要突出“花山”二字，在于纠正今人把“花山”之“花”误读为“华实”之“华”的错误。之所以要纠正今人读音的错误，又旨在为下文发表感想和议论设下张本。\n\n　　从“其下平旷，有泉侧出”至“而不得极夫游之乐也”。记叙游览褒禅山后洞的情形。这段承接第1段华山洞的方位和命名，进一步分别就华山洞的前洞和后洞加以叙写。前洞，“其下平旷，有泉侧出”，虽有美景而不险绝，“而记游者甚众”，不足以游，所以一笔带过。而后洞与前洞相比，则迥然不同，它不像前洞那样平坦广阔，游人举足可到，而在“由山以上五六里”的幽深之处，需要花费气力才能到达，而且“入之甚寒”，所以即使喜欢游览的人，也不能穷尽它的尽头。然而惟其险绝，才有奇观。因而便引起了作者与同游者的极大兴趣。于是他们拿着火把走了进去，走得越深，行进越艰难，而所看到的景物也就越加美妙。可是行进的艰难与景物的美妙形成了矛盾，所以同游者之中有倦怠而想出来的人说：“不出去，火把就要烧光了。”这么一说，大家就随着他一起走了出来。一旦走出洞后，作者却深有感慨，慨叹自己所到达的地方比起喜欢游览的人，还不到十分之一，然而在洞的左右壁上，题字留念的人已经很少了。如果再往深处走，到达的人就更少了。这说明没有大志而畏于艰险的人，是不能够深入险境而窥视到异观的。因而又回顾自己在洞里还没有出来的时候，“余之力尚足以入，火尚足以明”，是可以继续前进的，只是听了倦怠者的话，随着走出洞来，而不能极尽游览之乐。目的不达，满腹憾恨之情溢于言表，由此可见作者不畏艰险的积极进取精神。\n\n　　从“于是余有叹焉”至“此余之所得也”。写未能深入华山后洞所产生的感想和体会。这段开头“于是余有叹焉”一句，奠定了全段的基调，为展开议论作了带有浓厚感情色彩的转折。行文先从古人的行事说起，而后又回到游览风物上来，加以发挥议论。就古人来说，他们观察天地、山川、草木、虫鱼、鸟兽，往往都有所得，这是因为他们对事物观察思索得深切，而没有探索不到的地方。作者称引古人，是为了借古鉴今。不言而喻，今人行事，要想有所收益，也必须具有古人那种探索的精神。但事实上，并不是人人都具有这种精神的。就以游览风物来说，“夫夷以近，则游者众；险以远，则至者少”。这种现象，就正是缺乏探索精神的表现。而天下的奇异雄伟、异乎寻常的景物，又常常在险远之处，人们却又很少能够到达，那也就不可能看到奇景异观了。那么怎样才能看到奇景异观呢？作者进而又从三个方面加以论说。一是“非有志者不能至也”。这里强调了一个“志”字。只有胸怀大志，才有可能到达理想的境地。二是有了大志，不随随便便地止足不前，“然力不足者，亦不能至也”。这里又强调了一个“力”字。这个“力”，是指气力。如果气力不足，像“有怠而欲出者”那样，也是不能到达理想境地的。三是有了大志和气力，而又不轻易地倦怠，“至于幽暗昏惑而无物以相之，亦不能至也”。这里又强调了一个“物”字。这里所说的“物”，是指火把之类的借助之物。当游览者走进昏暗之处的时候，如果不借助火把之类的物来照亮前进的道路，也是不能到达理想境地的。总之，只有具备志、力与相助之物这三个条件，才能到达理想的境地。这是就正面来说。反过来说，气力可以达到而又未能达到，这对别人来说是非常可笑的，对自己来说是很可悔恨的。如果竭尽了自己的志气，也仍然达不到，也就没有什么可悔恨的了。这样，谁还能讥笑他呢？作者从正反两方面把道理说得清清楚楚。这就是作者游览华山后洞之后的心得和体会。这个心得和体会，是十分深刻的，它的客观意义却远远超过了游览，而可以用之于从事一切事情。\n\n　　从“余于仆碑”至“此所以学者不可以不深思而慎取之也”。写由于仆碑而引起的联想。作者从仆碑上尚可辨识的“花山”之“花”字，今人误读为“华实”之“华”，从而联想到古籍，“又以悲夫古书之不存，后世之谬其传而莫能名者，何可胜道也哉！”从山名的以讹传讹，联想到古籍的以讹传讹，使作者触目伤怀，慨叹不已。因而又进一步提出“此所以学者不可以不深思而慎取之也”。对待传闻要“深思”而“慎取”这个提法，也很精辟。它对学者整理和研究古籍，鉴别其真伪，恢复其本来面目，不仅是必要的，而且也是有指导意义的。\n\n　　从“四人者”至篇末。记同游者姓名和写作时间。\n\n　　从以上五段简略地叙述和分析里不难看出，本文虽以游记命题，但所写重点却不在于记游，而在于写作者在游览中的心得和体会，并着重写了两点：一是写华山山名的本末；一是写游览华山后洞的经过。\n\n　　写华山山名的本末时，从今人对“花山”读音之误，联想到对古籍的以讹传讹，从而指出对古籍要持“深思而慎取”的态度。这既是对当时学者的劝勉，同时也是作者自己治学态度的写照。王安石在治学方面，就颇多创见，不为前人之见所束缚。比如他与门人一起修撰《诗》《书》《周礼》三书的经义和《老子注》等书的注疏，以代替汉儒以来的章句之学，就是突出一例。再如他写的咏史和怀古诗，也多半一反常人之见。在《商鞅》诗里写道：“今人未可非商鞅，商鞅能令政必行。”在《贾生》诗里写道：“一时谋议略施行，谁道君王薄贾生。”这些都反映出他的新见解。这些见解，又都是为他打击旧党，推行变法革新服务的。因而也可以说他变法革新的理论和实践，就正是他认真总结历史的经验教训，得出“深思而慎取”的结果。\n\n　　写游览华山后洞的经过时，从“入之愈深，其进愈难，而其见愈奇”，而游者也随之越来越少的情况，进而论述了“世之奇伟、瑰怪、非常之观，常在险远”，要想看到“奇伟、瑰怪、非常之观”，就必须有一个不畏艰险，一往直前的坚强意志，同时还要具备足够的实力和可资凭借的外界条件。他这种力图精进，永攀高峰的精神，同他后来在变法革新中所表现的不怕围攻、百折不回的精神也是完全一致的。这种积极进取精神，同他的变法革新，虽有其不可避免的历史的和阶级的局限，然而却也能给人以有益启示和鼓舞。\n\n　　本文的写作技巧也是比较高明的。既然本文的重点不在记游，而在写游览中的心得体会，所以在材料的取舍上，行文的组织安排上，是颇费一番切磋琢磨之功的。作者在记游中，处处为写心得体会搭桥铺路，使记游与心得体会十分和谐自然地结合起来。\n\n　　文章开头“褒禅山亦谓之华山”一句，看来只是叙说褒禅山的原委，平平淡淡，并不新奇。但细加玩味，却不寻常。它不仅为下文考究褒禅命名的由来起着开拓的作用，而且也把有关全局的“华山”二字突现出来。作者突现出“华山”，对全文的记游和议论是有着重要作用的。可以设想，倘若读者不了解褒禅山就是“华山”，那么文章题为《游禅山褒记》，而下面所记的，也就是与“华山”不可分割的华山前洞、华山后洞，便失去了根基，而令人不可思议。随之游览华山后洞，从而发表议论也将成为不可能。所以首句把“华山”突现出来，是十分重要的，不可缺少的，它对全文来说，起着先引和铺垫的作用。然而作者又不特意去就“华山”而论“华山”，却以考究褒禅山命名由来的方式来突现它，这就更显得自然入妙了。从考究褒禅山命名的由来来看，文从字顺，无懈可击；从记游角度来看，又顺理成章，起到了它应有的作用。\n\n　　该文是以记游为辅，以议论为主的特点，所以作者在记游中写什么，不写什么，以及怎样写，也是经过周密考虑，严加取舍的。文中所写华山、慧空禅院、仆碑和华山前洞，由于都不是所写重点，所以都一笔带过。而它们的出现，又都是为写华山后洞，特别是写游华山后洞作铺垫过渡的。详其所详，略其所略，对所写重点游华山后洞，则刻意作了较为细致地记叙。作者先写华山后洞幽深昏暗，寒气袭人，虽好游者不能穷；次写入之愈深，进之愈难，见之愈奇；次写怠而欲出者声张出洞，同游者遂与之俱出；次写入之愈深，记游者愈少；次写既出之后，有人责备怠而欲出者；次写作者悔恨随怠者而出，不能极尽游览之余，层层深入地写出了游览华山后洞的全过程。这之中有环境气氛的渲染，有游人的活动，有意志不坚强者的退缩，有责怨之辞，有悔恨之语。记游详尽曲折，思想斗争波澜起伏，这就为下文抒写心得体会，发表议论，作了自然而然地铺垫过渡，使记游与议论紧密地融合起来。\n\n　　再如作者写仆道之碑，叙写“其文漫灭，独其为文犹可识，曰‘花山’”，并从而考究今人读音之谬，也是有意安排。它对下面针对后人对古籍以讹传讹的现象发表议论，同样起着铺垫的作用，使之前呼后应，结为一体。总观全文，记游为议论提供了条件，而议论则是记游的必然发展。为突出所写重点，作者严于取舍，精于剪裁，善于铺垫过渡的写作技巧，是值得借鉴的。正如《古文观止》的编者所说:“一路俱是记游,按之却俱是论学.古人诣力到时,头头是道.川上山梁,同一趣也.“作者最后又感慨倒在路边的碑，与篇首相呼应,结构严丝合缝，脉络清晰。', poem_tags = '高中文言文,古文观止,纪游,写景,感悟' WHERE poem_title = '游褒禅山记' AND poem_author = '王安石';
UPDATE edu_poem SET poem_translation = '树叶飘落大雁飞向南方，北风萧瑟江上分外寒冷。\n我家在曲曲弯弯襄水边，远隔楚天云海迷迷茫茫。\n思乡的眼泪在旅途流尽，看归来的帆在天边徜徉。\n风烟迷离渡口可在何处，茫茫江水在夕阳下荡漾。', poem_notes = '木落：树木的叶子落下来。雁南度：大雁南飞。南：一作“初”。\n首二句从鲍照《登黄鹤矶》“木落江渡寒，雁还风送秋”句脱化而来。\n襄（xiāng）水曲（qū）：在汉水的转弯处。襄水，汉水流经襄阳（今属湖北）境内的一段。曲，江水曲折转弯处，即河湾。襄：一作“湘”，又作“江”。曲：一作“上”。\n楚云端：长江中游一带云的尽头。云：一作“山”。\n乡泪客中尽：思乡眼泪已流尽，客旅生活无比辛酸。\n孤：一作“归”。天际：天边。一作“天外”。\n迷津：迷失道路。津，渡口。\n平海：宽广平静的江水。漫漫：水广大貌。', poem_appreciation = '这是一首怀乡思归的抒情诗。全诗情感是复杂的。诗人既羡慕田园生活，有意归隐，但又想求官做事，以展鸿图。这种矛盾，就构成了诗的内容。\n\n　　“木落雁南度，北风江上寒”，这两句是写景。作者捕捉了当时带有典型性的事物，点明季节。木叶渐脱，北雁南飞，这是最具代表性的秋季景象。但是单说秋，还不能表现出“寒”，作者又以“北风”呼啸来渲染，使人觉得寒冷，这就点出了题目中的“早寒”。\n\n　　落木萧萧，鸿雁南翔，北风呼啸，天气寒冷，作者活画出一幅深秋景象。处身于这种环境中，很容易引起悲哀的情绪，所谓“悲落叶于劲秋”（陆机《文赋》），是有一定道理的。远离故土，思想处于矛盾之中的作者就更是如此了。\n\n　　这是一种“兴”起的手法，诗很自然地进入第二联。作者面对眼前景物，思乡之情，不免油然而生。“襄水”，亦即“襄河”。汉水在襄阳一带水流曲折，所以作者以“曲”概括之。“遥隔”两字，不仅表明了远，而且表明了两地隔绝，不能归去。这个“隔”字，已透露出思乡之情。作者家住襄阳，古属楚国，故诗中称“楚云端”，既能表现出地势之高（与长江下游相比），又能表现出仰望之情，可望而不可即，也能透露出思乡的情绪。“我家襄水曲，遥隔楚云端”，看来句意平淡，但细细咀嚼，是很能体味到作者炼句之妙、造意之苦的。\n\n　　如果说第二联只是透露一些思乡的消息，带有含蓄的意味，而又未点明；那么第三联的“乡泪客中尽”，不仅点明了乡思，而且把这种感情一泄无余了。不仅他自己这样思乡，而且家人也在想望着他自己的归去，遥望着“天际”的“孤帆”。家人的想望，是假托之词，然而使思乡的感情，抒发得更为强烈了。“迷津欲有问”，是用《论语·微子》孔子使子路问津的典故。长沮、桀溺是隐者，而孔子则是积极想从政的人。长沮、桀溺不说津（渡口）的所在，反而嘲讽孔子栖栖遑遑、奔走四方，以求见用，引出了孔子的一番慨叹。双方是隐居与从政的冲突。而孟浩然本为襄阳隐士，如今却奔走于东南各地（最后还到长安应进士举），却是把隐居与从政的矛盾集于一身，而这种矛盾又无法解决，故以“平海夕漫漫”作结。滔滔江水，与海相平，漫漫无边，加以天色阴暗，已至黄昏。这种景色，完全烘托出作者迷茫的心情。\n\n　　这首诗二、三两联都是自然成对，毫无斧凿痕迹。第二联两句都是指襄阳的地位，信手拈来，就地成对，极为自然。第三联“乡泪”是情，“归帆”是景，以情对景，扣合自然，充分表达了作者的感情。最后又以景作结，把思归的哀情和前路茫茫的愁绪都寄寓在这迷茫的黄昏江景中了。', poem_tags = '唐诗三百首,初中古诗,思乡,思归' WHERE poem_title = '早寒江上有怀 / 早寒有怀' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '注释 千门，形容宫毁群建筑宏伟，众多，千门万户。如杜甫《哀江头》：“江头宫殿锁于门”。 内人，宫中歌午艺妓，入宜春院，称“内人”。 著，同着，犹“有”。此句形容歌声高唱入云，又兼喻歌乐声悦耳动听，宛若仙乐下凡。', poem_appreciation = '本诗描写 家家出门、万人空巷、尽情而来、尽兴方归闹上元夜的情景，使上元灯节成为了最有诗意，最为消魂的时刻。\n\n　　唐宫内万灯齐明，舞衲联翩，歌声入云，有鸟瞰式全景、有特写武近景，场面壮观，气象恢宏。\n\n　　千门开锁万灯明:“千门开锁”就是指很多门的锁都打开了，“千门”泛指很多门，门锁都打开了即人都出门了。\n\n　　“万灯明”万灯，泛指很多灯，明则是亮起来了。正月中旬动帝京：“正月中旬”正月的中旬就是指正月十五。“动”震动。形容热闹。“帝京”是指京城、国都百内人连袖舞：“三百内人”应该是指很多的宫女。“三百”也是形容人数众多的，非实指。“连袖舞”是指一时天上著词声跳舞。“一时”是说当时，“天上著词声”是指人间的歌舞乐声直冲云霄，传到天上。也是极言歌舞的热闹和盛大，以及街上人数的众多，声可直传天上。', poem_tags = '节日,元宵节,古诗里的十二个月' WHERE poem_title = '正月十五夜灯' AND poem_author = '张祜';
UPDATE edu_poem SET poem_translation = '人生旅途常有别离不易相见，就像参星商星实在难得相遇。\n今夜又是一个什么吉日良辰，让我们共同在这烛光下叙谈。\n青春壮健年少岁月能有多少，转瞬间你我都已经两鬓如霜。\n昔日往来的朋友一半已去世，我内心激荡不得不连声哀叹。\n没想到我们已分别廿个春秋，今天还能亲临你家里的厅堂。\n相分别是你还没有结婚成家，倏忽间你的子女已成帮成行。\n他们彬彬有礼笑迎父亲老友，亲切地询问我来自什么地方？\n还来不及讲述完所有的往事，你就催促儿女快把酒菜摆上。\n冒着夜雨剪来了青鲜的韭菜，呈上新煮的黄米饭让我品尝。\n主人感慨见面的机会太难得，开怀畅饮一连喝干了十几杯。\n一连喝干十几杯还没有醉意，令我感动你对老友情深意长。\n明日分别后又相隔千山万水，茫茫的世事真令人愁绪难断。', poem_notes = '卫八处士，名字和生平事迹已不可考。处士，指隐居不仕的人；八，是处士的排行。\n动如，是说动不动就像。参（shēn）商，二星名。典故出自《左传·昭公元年》：“昔高辛氏有二子，伯曰阏伯，季曰实沉。居於旷林，不相能也。日寻干戈，以相征讨。后帝不臧，迁阏伯於商丘，主辰，商人是因，故辰为商星。迁实沉於大夏，主参，唐人是因，以服事夏商。”商星居于东方卯位（上午五点到七点），参星居于西方酉位（下午五点到七点），一出一没，永不相见，故以为比。\n苍，灰白色。\n“访旧”句，意谓彼此打听故旧亲友，竟已死亡一半。访旧，一作“访问”。\n“惊呼”句：有两种理解，一为：见到故友的惊呼，使人内心感到热乎乎的；二为：意外的死亡，使人惊呼怪叫以至心中感到火辣辣的难受。惊呼，一作“呜呼”。\n成行（háng），儿女众多。\n“父执”：词出《礼记·曲礼》：“见父之执。”意即父亲的执友。执是接的借字，接友，即常相接近之友。\n乃未已，还未等说完。\n“儿女”一作“驱儿”。罗，罗列酒菜。\n“夜雨”句：与郭林宗冒雨剪韭招待好友范逵的故事有关。林宗自种畦圃，友人范逵夜至，自冒雨剪韭，作汤饼以供之。《琼林》：冒雨剪韭，林宗款友情殷；踏雪寻梅，孟浩然自娱兴雅。\n“间”：读去声，搀和的意思。黄粱，即黄米。新炊是刚煮的新鲜饭。\n主，主人，即卫八。称就是说。曹植诗：“主称千金寿。”\n累，接连。\n故意长，老朋友的情谊深长。\n山岳，指西岳华山。这句是说明天便要分手。\n世事，包括社会和个人。两茫茫，是说明天分手后，命运如何，便彼此都不相知了。极言会面之难，正见令夕相会之乐。这时大乱还未定，故杜甫有此感觉。根据末两句，这首诗乃是饮酒的当晚写成的。', poem_appreciation = '这首诗写久别的老友重逢话旧，家常情境，家常话语，娓娓写来，表现了乱离时代一般人所共有的“沧海桑田”和“别易会难”之感，同时又写得非常生动自然，所以向来为人们所爱读。　\n\n　　开头四句说：人生动辄如参、商二星，此出彼没，不得相见；今夕又是何夕，咱们一同在这灯烛光下叙谈。这几句从离别说到聚首，亦悲亦喜，悲喜交集，把强烈的人生感慨带入了诗篇。诗人与卫八重逢时，安史之乱已延续了三年多，虽然两京已经收复，但叛军仍很猖獗，局势动荡不安。诗人的慨叹，正暗隐着对这个乱离时代的感受。　\n\n　　久别重逢，彼此容颜的变化，自然最容易引起注意。别离时两人都还年轻，而此时俱已鬓发斑白了。“少壮能几时，鬓发各已苍”两句，由“能几时”引出，对于世事、人生的迅速变化，表现出一片惋惜、惊悸的心情。接着互相询问亲朋故旧的下落，竟有一半已不在人间了，彼此都不禁失声惊呼，心里火辣辣地难受。按说，杜甫这一年才四十八岁，亲故已经死亡半数很不正常。如果说开头的“人生不相见”已经隐隐透露了一点时代气氛，那么这种亲故半数死亡，则更强烈地暗示着一场大的干戈乱离。“焉知”二句承接上文“今夕复何夕，共此灯烛光”，诗人故意用反问句式，含有意想不到彼此竟能活到今天的心情。其中既不无幸存的欣慰，又带着深深的痛伤。\n\n　　前十句主要是抒情。接下去，则转为叙事，而无处不关人世感慨。随着二十年岁月的过去，此番重来，眼前出现了儿女成行的景象。这里面当然有倏忽之间迟暮已至的喟叹。“怡然”以下四句，写出卫八的儿女彬彬有礼、亲切可爱的情态。诗人款款写来，毫端始终流露出一种真挚感人的情意。这里“问我来何方”一句后，本可以写些路途颠簸的情景，然而诗人只用“问答乃未已”一笔轻轻带过，可见其裁剪净炼之妙。接着又写处士的热情款待：菜是冒着夜雨剪来的春韭，饭是新煮的掺有黄米的香喷喷的二米饭。这自然是随其所有而具办的家常饭菜，体现出老朋友间不拘形迹的淳朴友情。“主称”以下四句，叙主客畅饮的情形。故人重逢话旧，不是细斟慢酌，而是一连就进了十大杯酒，这是主人内心不平静的表现。主人尚且如此，杜甫心情的激动，当然更不待言。“感子故意长”，概括地点出了今昔感受，总束上文。这样，对“今夕”的眷恋，自然要引起对明日离别的慨叹。末二句回应开头的“人生不相见，动如参与商”，暗示着明日之别，悲于昔日之别：昔日之别，今幸复会；明日之别，后会何年？低回深婉，耐人玩味。\n\n　　诗人是在动乱的年代、动荡的旅途中，寻访故人的；是在长别二十年，经历了沧桑巨变的情况下与老朋友见面的，这就使短暂的一夕相会，特别不寻常。于是，那眼前灯光所照，就成了乱离环境中幸存的美好的一角；那一夜时光，就成了烽火乱世中带着和平宁静气氛的仅有的一瞬；而荡漾于其中的人情之美，相对于纷纷扰扰的杀伐争夺，更显出光彩。“今夕复何夕，共此灯烛光”，被战乱推得遥远的、恍如隔世的和平生活，似乎一下子又来到眼前。可以想象，那烛光融融、散发着黄粱与春韭香味、与故人相伴话旧的一夜，对于饱经离乱的诗人，是多么值得眷恋和珍重啊。诗人对这一夕情事的描写，正是流露出对生活美和人情美的珍视，它使读者感到结束这种战乱，是多么符合人们的感情与愿望。\n\n　　这首诗平易真切，层次井然。诗人只是随其所感，顺手写来，便有一种浓厚的气氛。它与杜甫以沉郁顿挫为显著特征的大多数古体诗有别，而更近于浑朴的汉魏古诗和陶渊明的创作；但它的感情内涵毕竟比汉魏古诗丰富复杂，有杜诗所独具的感情波澜，如层漪迭浪，展开于作品内部，是一种内在的沉郁顿挫。诗写朋友相会，却由“人生不相见”的慨叹发端，因而转入“今夕复何夕，共此灯烛光”时，便格外见出内心的激动。但下面并不因为相会便抒写喜悦之情，而是接以“少壮能几时”至“惊呼热中肠”四句，感情又趋向沉郁。诗的中间部分，酒宴的款待，冲淡了世事茫茫的凄惋，带给诗人幸福的微醺，但劝酒的语辞却是“主称会面难”，又带来离乱的感慨。诗以“人生不相见”开篇，以“世事两茫茫”结尾，前后一片苍茫，把一夕的温馨之感，置于苍凉的感情基调上。这些，正是诗的内在沉郁的表现。如果把这首诗和孟浩然的《过故人庄》对照，就可以发现，二者同样表现故人淳朴而深厚的友情，但由于不同的时代气氛，诗人的感受和文字风格都很不相同，孟浩然心情平静而愉悦，连文字风格都是淡淡的。而杜甫则是悲喜交集，内心蕴积着深深的感情波澜，因之，反映在文字上尽管自然浑朴，而仍极顿挫之致。', poem_tags = '唐诗三百首,人生,友情,时光' WHERE poem_title = '赠卫八处士' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '康肃公陈尧咨善于射箭，世上没有第二个人能跟他相媲美，他也就凭着这种本领而自夸。曾经（有一次），（他）在家里（射箭的）场地射箭，有个卖油的老翁放下担子，站在那里斜着眼睛看着他，很久都没有离开。卖油的老头看他射十箭中了八九成，但只是微微点点头。\n\n　　陈尧咨问卖油翁：”你也懂得射箭吗？我的箭法不是很高明吗？”卖油的老翁说：“没有别的（奥妙），不过是手法熟练罢了。”陈尧咨（听后）气愤地说：“你怎么敢轻视我射箭（的本领）！”老翁说：“凭我倒油的经验就可以懂得这个道理。”于是拿出一个葫芦放在地上，把一枚铜钱盖在葫芦口上，慢慢地用油杓舀油注入葫芦里，油从钱孔注入而钱却没有湿。于是说：“我也没有别的（奥妙），只不过是手熟练罢了。”陈尧咨笑着将他送走了。\n\n　　这与庄子所讲的庖丁解牛、轮扁斫轮的故事有什么区别呢？', poem_notes = '⑴本文选自《归田录》卷一（中华书局1981年版），有删节。\n⑵〔陈康肃公〕陈尧咨，谥号康肃，北宋人。公，旧时对男子的尊称。\n⑶〔善射〕擅长射箭。\n⑷〔自矜（jīn）〕自夸。\n⑸〔家圃（pǔ）〕家里（射箭的）场地。圃，园子，这里指场地。\n⑹〔释担〕放下担子。释，放。\n⑺〔睨（nì）〕斜着眼看，形容不在意的样子。\n⑻〔但微颔（hàn）之〕只是微微对此点头，意思是略微表示赞许。但，只、不过。颔之，就是”对之颔”。颔，点头。之，指陈尧咨射箭十中八九这一情况。\n⑼〔无他〕没有别的（奥妙）。\n⑽〔但手熟尔〕不过手熟罢了。熟，熟练。尔，同“耳”，相当于”罢了。\n⑾〔忿（fèn）然〕气愤愤地。然，作形容词或者副词的词尾，相当于”的”或”地”。\n⑿〔安〕怎么。\n⒀〔轻吾射〕看轻我射箭（的本领）。轻，作动词用。\n⒁〔以我酌（zhuó）油知之〕凭我倒油（的经验）知道这个（道理）。以，凭、靠。酌，斟酒，这里指倒油。之，指射箭也是凭手熟的道理。\n⒂〔覆〕盖。\n⒃〔徐〕慢慢地。\n⒄〔沥之〕注入葫芦。沥，注。之，指葫芦。\n⒅〔遣之〕让他走，打发。\n(19)〔惟〕只，不过。', poem_appreciation = '本文是一篇富含哲理与情趣的小品文章，通俗易懂，意味深长，非常具有教育意义，因此多年来为中学课本必选篇目。这篇文章的成功之处在于将熟能生巧这个大道理。用一个生动的小故事加以阐释，达到了发人深省、心领神会的目的。\n\n　　第一段：写陈尧咨善射，卖油翁略表赞许。 文章开头就对陈尧咨作概括介绍，他”善射”，”当世无双”并”以此自矜”。射技高超，以常理而论，定然是人人赞赏，射者自命不凡也是常情。这就为下文做了伏笔。但是，卖油老头对其”发矢十中八九”，却只”但微颔之”。这里以极其精练的笔墨提出了矛盾，在读者心中产生了悬念，就自然地引出了下文。\n\n　　第二段：说明熟能生巧的道理。 康肃公一贯”自矜”，对卖油老头对其箭术所表示的不以为然的态度，是不会轻易放过的，自然要追问：”汝亦知射乎？吾射不亦精乎？”卖油老头回答：”无他，但手熟尔。”这一问一答，说明了一个深刻的道理，就是”熟能生巧”。康肃公一时还不明白其中的道理，反认为是”轻吾射”，至此矛盾更加激化，卖油老头只好现身说法”以我酌油知之”。又用具体事实证明”熟能生巧”，”乃取一葫芦置于地，以钱覆其口，徐以杓酌油沥之，自钱孔入而钱不湿”。作了这一番表演之后，卖油老头为解除康肃公的疑虑，说道：”我亦无他，惟手熟尔。”这个回答很重要，既回答了并非”轻吾射”，又再次说明道理。康肃公心中豁然开朗了，由”忿然”到”笑而遣之”结束了全文。 本文以卖油翁自钱孔沥油而钱不湿的这件小事，说明了”熟能生巧”这个普通的道理。 一般说理文章，常常要发议论，说为什么应该这样，为什么不应该那样。而这篇文章并没有高谈阔论，只是记叙卖油翁与陈尧咨对答和卖油翁酌油的经过，来说明道理。本文着重写的是射箭和酌油都可以由于手熟达到高超的技艺，而不是写陈尧咨的射箭。所以写陈尧咨的射箭只用了”矢十中八九”五个字，写得十分简略。这样繁简得当，突出文章的重点。\n\n　　陈尧咨学问不小，官职做得也很大，而且是文武双全，不愿屈居人下，可是却不得不在卖油翁面前认输，因为卖油翁指出的道理辩驳不倒，只得”笑而遣之”，没有责备”犯上”的小百姓，对于”用刑惨急，数有杖死”的陈尧咨确实不大容易。”笑”，既是有所领悟，也是自我解嘲，自是”传神之笔”。', poem_tags = '初中文言文,哲理,寓言,故事' WHERE poem_title = '卖油翁' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '伯牙擅长弹琴，钟子期擅长倾听琴声。伯牙弹琴的时候，心里想到巍峨的泰山，钟子期听了赞叹道：“太好了！就像巍峨的泰山屹立在我的面前！”伯牙弹琴时，心里想到宽广的江河，钟子期赞叹道：“好啊，宛如一望无际的江河在我面前流动！” 无论伯牙弹琴的时候心里想到什么，钟子期都会清楚地道出他的心声。钟子期去世后，伯牙就此认为世界上再也没有他的知音了。于是，他坚决地把自己心爱的琴摔破了，挑断了琴弦，终生不再弹琴，以便绝了自己对钟子期的思念。', poem_notes = '善 ：擅长，善于。 \n鼓：弹奏。\n听：倾听。\n绝 ：断绝。\n志在高山 :心中想到高山。\n曰：说。\n善哉 :赞美之词，有夸奖的意思。即“好啊“ 、“妙啊”或“太棒了”。善，好；哉，语气词,表示感叹。\n峨峨 :高\n兮 :语气词，相当于“啊”。\n若 ：像……一样。\n洋洋：广大。\n念 ：心里所想的。\n必 ：一定，必定。\n之：他。\n谓 ：认为，以为。\n知音 ：理解自己心意，有共同语言的人。\n乃 ：就。\n复：再,又。\n弦：在这里读作xián的音。\n志在流水：心里想到河流。\n阴：山北或水南为阴。反之，山南水北为阳。', poem_appreciation = '春秋时期，有一个人名叫伯牙，随成连先生学古琴。他掌握了各种演奏技巧，但是老师感到他演奏时，常常是理解不深，单纯地把音符奏出来而已，少了点神韵，不能引起欣赏者的共鸣。老师想把他培养成一位真正的艺术家，有一天，成连先生对伯牙说：“我的老师方子春，居住在东海，他能传授培养人情趣的方法。我带你前去，让他给你讲讲，能够大大提高你的艺术水平。”于是师徒两人备了干粮，驾船出发。到了东海蓬莱山后，成连先生对伯牙说：“你留在这里练琴，我去寻师父。”说罢，就摇船渐渐远离。\n\n　　过了十天，成连先生还没回来。伯牙在岛上等得心焦，每天调琴之余，举目四眺。他面对浩瀚的大海，倾听澎湃的涛声。远望山林，郁郁葱葱，深远莫测，不时传来群鸟啁啾飞扑的声响。这些各有妙趣、音响奇特不一的景象，使他不觉心旷神怡，浮想翩翩，感到自己的情趣高尚了许多。伯牙产生了创作激情，要把自己的感受谱成音乐，于是他架起琴，把满腔激情倾注到琴弦上，一气呵成，谱写了一曲《高山流水》。\n\n　　没多久，成连先生摇船而返，听了他感情真切的演奏，高兴地说：“现在你已经是天下最出色的琴师了，你回去吧！”伯牙恍然大悟，原来这涛声鸟语就是最好的老师。此后，伯牙不断积累生活和艺术体会，终于成了天下操琴的高手。', poem_tags = '小学文言文,音乐,知音,故事' WHERE poem_title = '伯牙绝弦' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '娴静姑娘真可爱，约我城角楼上来。故意躲藏让我找，急得抓耳又挠腮。\n娴静姑娘好容颜，送我一枝红彤管。鲜红彤管有光彩，爱它颜色真鲜艳。\n郊野采荑送给我，荑草美好又珍异。不是荑草长得美，美人相赠厚情意。', poem_notes = '静女：贞静娴雅之女。马瑞辰《毛诗传笺通释》：“静当读靖，谓善女，犹云淑女、硕女也。”姝（shū）：美好。\n俟（sì）：等待，此处指约好地方等待。城隅：城角隐蔽处。一说城上角楼。\n爱：“薆”的假借字。隐蔽，躲藏。\n踟（chí）躇（chú）：徘徊不定。\n娈（luán）：面目姣好。\n贻（yí）：赠。彤管：不详何物。一说红管的笔，一说和荑应是一物。有的植物初生时或者才发芽不久时呈红色，不仅颜色鲜亮，有的还可吃。如是此意，就与下文的“荑”同类。但是也可能是指涂了红颜色的管状乐器等。\n有：形容词词头。炜（wěi）：盛明貌。\n说（yuè）怿（yì）：喜悦。女（rǔ）：汝，你，指彤管。\n牧：野外。归：借作“馈”，赠。荑（tí）：白茅，茅之始生也。象征婚媾。\n洵美且异：确实美得特别。洵：实在，诚然。异：特殊。\n匪：非。\n贻：赠与。', poem_appreciation = '《静女》一诗，向来为选家所注目。现代学者一般都认为此诗写的是男女青年的幽期密约，也就是说，它是一首爱情诗。而旧时的各家之说，则多有曲解，未得其真旨。最早《毛诗序》云：“《静女》，刺时也。卫君无道，夫人无德。”郑笺释云：“以君及夫人无道德，故陈静女遗我以彤管之法。德如是，可以易之，为人君之配。”而《易林》有“季姬踟蹰，结衿待时；终日至暮，百两不来”、“季姬踟蹰，望我城隅；终日至暮，不见齐侯，居室无忧”、“踯躅踟蹰，抚心搔首；五昼四夜，睹我齐侯”之句，则反映齐诗之说，王先谦《诗三家义集疏》遂谓“此媵俟迎而嫡作诗也”。所说拘牵于礼教，皆不免附会。宋人解诗，能破除旧说，欧阳修《诗本义》以为“此乃述卫风俗男女淫奔之诗”，朱熹《诗集传》也以为“此淫奔期会之诗”，他们的说法已经接近本义，但指男女正常的爱情活动为“淫奔”，仍是头巾气十足，与汉儒解诗言及妇女便标榜“后妃之德”同一弊端。\n\n　　诗是从男子一方来写的，但通过他对恋人外貌的赞美，对她待自己情义之深的宣扬，也可见出未直接在诗中出现的那位女子的人物形象，甚至不妨说她的形象在男子的第一人称叙述中显得更为鲜明。而这又反过来使读者对小伙子的痴情加深了印象。\n\n　　诗的第一章是即时的场景：有一位闲雅而又美丽的姑娘，与小伙子约好在城墙角落会面，他早早赶到约会地点，急不可耐地张望着，却被树木房舍之类东西挡住了视线，于是只能抓耳挠腮，一筹莫展，徘徊原地。“爱而不见，搔首踟蹰”虽描写的是人物外在的动作，却极具特征性，很好地刻划了人物的内在心理，栩栩如生地塑造出一位恋慕至深、如痴如醉的有情人形象。\n\n　　第二、第三两章，从辞意的递进来看，应当是那位痴情的小伙子在城隅等候他的心上人时的回忆，也就是说，“贻我彤管”、“自牧归荑”之事是倒叙的。在章与章的联系上，第二章首句“静女其娈”与第一章首句“静女其姝”仅一字不同，次句头两字“贻我”与“俟我”结构也相似，因此两章多少有一种重章叠句的趋向，有一定的匀称感，但由于这两章的后两句语言结构与意义均无相近之处，且第一章还有五字句，这种重章叠句的趋向便被扼制，使之成为一种佯似。这样的结构代表了《诗经》中一种介于整齐的重章叠句体与互无重复的分章体之间的特殊类型，似乎反映出合乐歌词由简单到复杂的过渡历程。\n\n　　读诗的第二、第三两章，读者会发出会心的微笑，对诗人的“写形写神之妙”（陈震《读诗识小录》）有进一步的感受。照理说，彤管比荑草要贵重，但男主人公对受赠的彤管只是说了句“彤管有炜”，欣赏的是它鲜艳的色泽，而对受赠的普通荑草却由衷地大赞“洵美且异”，欣赏的不是其外观而别有所感。原来，荑草是她跋涉远处郊野亲手采来的，物微而意深，一如后世南朝宋陆凯《赠范晔》诗之“江南无所有，聊赠一枝春”，重的是情感的寄托、表达，不妨说已成为一个具有能指优势的特殊符号。接受彤管，想到的是恋人红润的面容，那种“说（悦）怿”只是对外在美的欣赏；而接受荑草，感受到普通的小草也“洵美且异”，则是对她所传送的那种有着特定内容的异乎寻常的真情的深切体验，那已经超越了对外表的迷恋而进入了追求内心世界的谐合的高层次的爱情境界。而初生的柔荑将会长成茂盛的草丛，也含有爱情将更加发展的象征意义。\n\n　　第三章结尾“匪女之为美，美人之贻”两句对恋人赠物的“爱屋及乌”式的反应，可视为一种内心独白，既是第二章诗义的递进，也与第一章以“爱而不见，搔首踟蹰”的典型动作刻划人物的恋爱心理可以首尾呼应，别具真率纯朴之美。读完此诗，对那位痴心小伙子的一腔真情，读者必然深受感动。', poem_tags = '诗经,爱情,民谣' WHERE poem_title = '静女' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '站在骊山上我四处张望，（雄伟瑰丽的）阿房宫已被付之一炬，当年奢侈的场面现在到哪里去了呢？只见衰草萧疏，水波旋绕。到现在那些遗恨已消失在烟雾弥漫的树林中了。（想想）自周、齐、秦、汉、楚等国至今。那些战胜了的国家，都化作为了土；（那些）战败了的国家，（也）都化作为了土。', poem_notes = '山坡羊：词牌名。\n骊山：在今陕西临潼县东南。\n阿房：阿房宫，秦宫殿名，故址在今陕西西安市西南阿房村。\n一炬：指公元前206年12月，项羽引兵屠咸阳，“烧秦宫室，火三月不灭”（见《史记·项羽本纪》。故杜牧有“楚人一炬，可怜焦土。”（《阿房宫赋》）之叹息。\n萦纡：形容水流回旋迂曲的样子。\n列国：各国，即周、齐、秦、汉、楚。', poem_appreciation = '骊山（今西安市的东边），阿房宫当初的宫殿台基残存。杜牧在《阿房宫赋》中说：“骊山北构而西折，直走咸阳”，阿房宫从骊山建起，再向西直达咸阳，规模极其宏大，设施极其奢华。公元前206年秦朝灭亡，项羽攻入咸阳后阿房宫焚毁。张养浩途经骊山有所感而创作了这首“骊山怀古”小令。开头三句“骊山四顾，阿房一炬，当时奢侈今何处？”回顾骊山的历史，曾是秦朝宫殿的所在，被大火焚烧之后，当时的歌台舞榭、金块珠砾都已不复存在，诗人用“今何处”一个问句，强调了对从古到今历史所发生的巨大变化的感慨，并自然而然地引出了下文“只见草萧疏，水萦纡。”再不见昔日豪华的宫殿，只有野草稀疏地铺在地上，河水在那里迂回的流淌。草的萧索，水的萦纡更加重了作者怀古伤今的情感分量。\n\n　　第六七句说：“至今遗恨迷烟树。 列国周齐秦汉楚。”到如今，秦王朝因奢侈、残暴而亡国的遗恨已消失在烟树之间了。而这种亡国的遗恨不只有秦朝才有，周朝、战国列强直到汉楚之争，哪个不抱有败亡的遗恨呢？实际上作者在这里寄托了一种讽刺，是说后人都已遗忘了前朝败亡的教训！元朝统治者在夺得政权之后更奢侈挥霍无度，全然不顾国库空虚社会经济急待调整。\n\n　　张养浩对当时的状况心怀不满，但想到列国的历史，又觉得从夺得政权，到奢侈暴戾，到最终败亡，乃是历代封建王朝的共同结局。杜牧说阿旁宫“楚人一炬，可怜焦土”，作者正是由此引申开来写道：“赢， 都 变 做 了 土；输，都变做了土。”这句结尾句式相同的两句是说无论输赢，奢侈的宫殿最后都会归于死亡，“都变做了土”，我们可以看作这是对封建王朝的一种诅咒，更是对封建王朝社会历史的规律性的概括。张养浩在另一首《山坡羊·潼关怀古》的结尾说：“兴，百姓苦；亡，百姓苦。”这是从百姓的角度看封建王朝的更迭，带给人民的全是苦难。而这首小令则是从王朝的统治者的角度来谈的，封建统治者无论输赢成败最终都逃脱不了灭亡的命运。它虽不及“潼关怀古”思想深刻，但也提示出了一种历史的必然，还是比较有意义的。', poem_tags = '初中古诗,写景,怀古' WHERE poem_title = '山坡羊·骊山怀古' AND poem_author = '张养浩';
UPDATE edu_poem SET poem_translation = '与姐妹们分手时，惜别的泪水打湿了衣衫，洇湿了双腮，送别的《阳关曲》唱了一遍又一遍，纵有千言万语，也难尽别情。而今身在异乡，望莱州山长水远。寄宿馆所，秋雨潇潇，不禁感到无限凄清。\n　　被离情别绪搅得心乱如麻，竟不知在饯行时姐妹们送别酒是如何喝下去的，那杯中酒是深是浅，都全不知道了。最后嘱咐姐妹，你们要将音讯让过往的大雁捎来，以慰我心，东莱毕竟不像蓬莱那样遥远。', poem_notes = '蝶恋花：词牌名。\n昌乐馆：昌乐县驿馆，故址在今山东昌乐西北十里。\n泪湿罗衣脂粉满：四印斋本自注云：“别作‘泪搵征衣脂粉暖’。”满：同“漫”。\n阳关：这里指王维的《渭城曲》（送元二使安西）：“渭城朝雨浥轻尘，客舍青青柳色新。劝君更进一杯酒，西出阳关无故人。”后人乐，曰《阳关曲》，亦称《阳关》。苏轼论《阳关三迭》唱法云：“余在密州，文勋长官以事至密，自云得古本《阳关》，每句皆再唱，而第一句不叠。乃知古本三叠盖如此”。《四叠阳关》盖按苏轼之言推之，或者第一句也叠，故称四叠。究竟如何叠法，说法不一。宋刘仙伦《一剪梅》：“唱到阳关第四声，香带轻分。”\n萧萧：一作“潇潇”。孤馆：孤独寂寞的旅馆。\n方寸：即“方寸地”，指人的心。\n把：四印斋本自注：“别作有。”\n东莱：即莱州，时为明城为官之地，今山东莱州市，曾名掖县。蓬莱：传说中的海上仙山名。', poem_appreciation = '此词一开头就写她想念家中姊妹想得厉害，以至珠泪涟涟，浸湿身上罗衣，并且连脸上的脂粉也冲落下来沾满了罗衣；这时，她不由得想起了家中姊妹送她出行时，一遍遍吟唱《阳关曲》时的情景。《阳关曲》，又名《渭城曲》。唐代著名诗人兼音乐家王维《送元二使安西》诗：“渭城朝雨　轻尘，西出阳关无故人。”后歌入乐府，以为送别之曲。至“阳关”句，反复歌之，所以李清照称“四叠阳关”。如今，这长长的山路已将亲人隔于两地了，她孤身一人在这异地的旅馆中，听着这凄苦的萧萧雨声，心里无比忧伤，竟使自己的心绪全乱了，乱得忘记了姊妹们送她时，饯行宴上酒杯斟得是浅还是满。不管多么想念，亲人已经别于两地了，只好靠鸿雁来传递音信吧。好在东莱是个实实在在的地方，不像蓬莱仙山那样遥远飘渺，可望而不可即。“蓬莱”，指蓬莱山，也称医壶，古人传说与方丈、瀛洲并为海上三神山，都在渤海中，世人不能登及，所以说它“远”。\n\n　　这是一首开阖纵横的小令，王维的“劝君更尽一杯酒，西出阳关无故人”，到了她的笑下变成“四叠阳关，唱到千千遍”的激情，极夸张，却又极亲切、真挚。通首写惜别心情一层比一层深入，但煞拍“好把音书凭过雁，东莱不似蓬莱远”，出人意料地作宽解语，能放能收，小令词能用这种变化莫测的手法是很不容易的，这就是所谓善方情者不尽情。', poem_tags = '婉约,离别,亲情' WHERE poem_title = '蝶恋花·泪湿罗衣脂粉满' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '有一树梅花凌寒早开，枝条洁白如玉条。它远离人来车往的村路，临近溪水桥边。\n人们不知寒梅靠近溪水提早开放，以为那是经冬而未消融的白雪。', poem_notes = '迥（jiǒng）：远。\n傍：靠近。\n发(fā)：开放。\n经冬：经过冬天。\n销：通“消”，融化。这里指冰雪融化。', poem_appreciation = '这首诗立意咏赞早梅的高洁，但作者并没有发一句议论和赞语，却将早梅的高洁品格和诗人的赞美之情清晰地刻划出来。\n\n　　“一树寒梅白玉条”描写早梅花开的娇美姿色。“一树”实为满树，形容花开之密集而缤纷；“寒梅”指花开之早，还在冬末春初的寒冷季节，紧扣“早”字；“白玉条”生动地写出梅花洁白娇美的姿韵，像一块块白玉似的晶莹醒目。这是对梅花外貌的描写，有形有神，令人陶醉。\n\n　　“迥临村路傍谿桥”，从生长环境中表现早梅的高洁品格。花草本无知，不会选择生长环境，但这里诗人在真实的景物中，融入人的思想意念，仿佛寒梅是有意远离村路，而到偏僻的傍溪近水的小桥边，独自悄悄地开放。这就赋予早梅以不竞逐尘世、无哗众取宠之心的高尚品格。这样就使诗的意境显得开阔，进一步突出了早梅的高洁。最后两句，抒发诗人初见桥边早梅的感受。“不知近水花先发”是承上两句对早梅的铺写之后的转折，用惊叹的口吻表达了对近水梅花早开的惊喜之情。“疑是经冬雪未销”写出“不知”的缘由，用一“疑”字，更为传神，它将诗人那时的惊喜之情渲染得淋漓尽致，似乎诗人并不敢相信自己的眼睛所看到的是梅花，而怀疑是不是未融化的冬雪重压枝头。这就与首句的“白玉条”紧密呼应，喻比出梅花的洁白和凛然不屈的形象和品格，从而含蓄婉转地把诗意落到实处，使诗的主题得到进一步深化，加强了人们对早梅的倾慕之情。\n\n　　一首绝句，仅二十八个字，就能将梅花写得如此之美，除立意新颖之外，还在于诗人从现实生活的观察中，能捕捉住早梅的颜色（洁白）、地点（偏僻）、季节（早春）、气质（耐寒）、姿态（俏丽）等特征，加以艺术的提炼和概括，并借助像“白玉条”“冬雪压枝”等生动、形象的比喻，鲜明、传神地塑造出早梅的品貌和气质，使人生发出美不胜叹的感觉。梅与雪常常在诗人笔下结成不解之缘，如许浑《早梅》诗云：“素艳雪凝树”，这是形容梅花似雪，而这首诗则是疑梅为雪，着意点是不同的。对寒梅花发，形色的似玉如雪，不少诗人也都产生过类似的疑真的错觉。\n\n　　宋代王安石有诗云：“遥知不是雪，为有暗香来”（《梅花》），也是先疑为雪，只因暗香袭来，才知是梅而非雪，和这首《早梅》意境可谓异曲同工。', poem_tags = '咏物,梅花' WHERE poem_title = '早梅' AND poem_author = '张谓';
UPDATE edu_poem SET poem_translation = '端起酒杯向东方祈祷，请你再留些时日不要一去匆匆。洛阳城东垂柳婆娑的郊野小道，就是我们去年携手同游的地方，我们游遍了姹紫嫣红的花丛。\n欢聚和离散都是这样匆促，心中的遗恨却无尽无穷。今年的花红胜过去年，明年的花儿将更美好，可惜不知那时将和谁相从？', poem_notes = '把酒：端着酒杯。\n从容：留恋，不舍。\n紫陌：紫路。洛阳曾是东周、东汉的都城，据说当时曾用紫色土铺路，故名。此指洛阳的道路。洛城：指洛阳。\n总是：大多是，都是。\n匆匆：形容时间匆促。\n“可惜”两句：杜甫《九日蓝田崔氏庄》诗：“明年此会知谁健，醉把茱萸仔细看。”', poem_appreciation = '欧阳修入仕初期三年西京留守推官的生涯，不仅使他文名鹊起，而且与梅尧臣、尹洙等结下了深厚的友情，而洛阳东郊的旖旎芳景便是他们友谊的见证。公元1032年（明道元年）春，梅尧臣由河阳（今河南省孟县）入洛，与欧阳修把酒言欢，重游故地，曾写下《再至洛中寒食》和《依韵和欧阳永叔同游近郊》等诗，纪其游历之盛。欧阳修的这首《浪淘沙》或作于同一时期，词中同游之人则很可能就是梅尧臣。这是一首惜春忆春、伤时惜别的小词，抒发了人生聚散无常的感叹。\n\n　　此词在时间上跨了前后三年。上片由现境而忆已过之境，即由眼前美景而思“去年”同游之乐。下片再由现境而思未来之境，含遗憾之情于其中，尤表现出对友谊的珍惜。首二句语本于司空图《酒泉子》“黄昏把酒祝东风，且从容”，而添一“共”字，便有了新意。“共从容”是兼风与人而言。对东风言，不仅是爱惜好风，且有留住光景，以便游赏之意；对人而言，希望人们慢慢游赏，尽兴方归。“洛城东”揭出地点。洛阳公私园囿甚多，宋人李格非著有《洛阳名园记》专记之。京城郊外的道路叫“紫陌”。“垂杨”同“东风”合言，可想见其暖风吹拂，翠柳飞舞，天气宜人，景色迷人，正是游赏的好时候、好处所。末两句说，都是过去携手同游过的地方，今天仍要全都重游一遍。“当时”即下片的“去年”。“芳丛”说明此游主要是赏花。\n\n　　下片头两句深深地感叹：“聚散苦匆匆”，是说本来就很难聚会，而刚刚会面，又要匆匆作别，这怎能不给人带来无穷的怅恨。“此恨无穷”并不仅仅指作者本人而言，也就是说，在亲人朋友之间聚散匆匆这种怅恨，从古到今，以至今后，永远都没有穷尽，都给人带来莫大的痛苦。“黯然销魂者唯别而已矣！”（南朝梁江淹《别赋》）好友相逢，不能长聚，心情自然是非常难受的。这感叹，就是对友人深情厚谊的表现。下面三句是从眼前所见之景来抒写别情，也可以说是对上面的感叹的具体说明。“今年花胜去年红”有两层意思。一是说“今年”的花比“去年”开得更加繁盛，看去更加鲜艳，当然希望同友人尽情观赏。说“花胜去年红”，足见“去年”作者曾同友人来观赏过此花，此与上片“当时”呼应，这里包含着对过去的美好回忆；也说明此别已经一年，这次是久别重逢。聚会这么不易，花又开得这么美好，本来应该多多观赏，然而友人就要离去，怎能不使人痛惜？这句写的是鲜艳繁盛的景色，表现的却是感伤的心情，正是“以乐景写哀”。末两句意为：明年这花还将比今年开得更加繁盛，可惜的是，自己和友人分居两地，天各一方，明年此时，不知同谁再来共赏此花啊！再进一步说，“明年”自己也可能已离开此地，更不知是谁来赏此花了。把别情熔铸于赏花中，将三年的花加以比较，层层推进，以惜花写惜别，构思新颖，富有诗意，是篇中的绝妙之笔。而别情之重，亦即说明同友人的情谊之深。黄蓼园《蓼园词选》说此词“大有理趣”，或许是着眼于其对人生飘泊无定、聚散匆匆的大笔概括。其实由笃于友谊的深情而咏叹出人生长恨的苦调，才是这首词更为动人之处。\n\n　　此词笔致疏放，婉丽隽永，近人俞陛云称它“因惜花而怀友，前欢寂寂，后会悠悠，至情语以一气挥写，可谓深情如水，行气如虹矣。”指出了欧阳修此词笃于友情、风格疏隽的特点。', poem_tags = '宋词三百首,惜春,友情,感叹,人生' WHERE poem_title = '浪淘沙·把酒祝东风' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '樽前拟把归期说定，一杯心切情切，欲说时佳人无语滴泪，如春风妩媚的娇容，先自凄哀低咽。啊，人生自是有情，情到深处痴绝，这凄凄别恨不关涉——楼头的清风，中天的明月。\n饯别的酒宴前，莫再演唱新的一阕，清歌一曲，已让人愁肠寸寸郁结。啊，此时只需要把满城牡丹看尽，你与我同游相携，这样才会——少些滞重的伤感，淡然无憾地与归去的春风辞别。', poem_notes = '尊前：即樽前，饯行的酒席前。\n春容：如春风妩媚的颜容。此指别离的佳人。\n离歌：指饯别宴前唱的流行的送别曲。\n翻新阕：按旧曲填新词。白居易《杨柳枝》：“古歌旧曲君莫听，听取新翻杨柳枝。”阙，乐曲终止。\n洛阳花：洛阳盛产牡丹，欧阳修有《洛阳牡丹记》。', poem_appreciation = '此词咏叹离别，于伤别中蕴含平易而深刻的人生体验。上片，尊前伤别，芳容惨咽，而转入人生的沉思：“人生自是有情痴，此恨不关风与月。”中天明月、楼台清风原本无情，与人事了无关涉，只因情痴人眼中观之，遂皆成伤心断肠之物，所谓“情之所钟，正在我辈”。下片，离歌一曲，愁肠寸结，离别的忧伤极哀极沉，却于结处扬起：“直须看尽洛城花，始共春风容易别。”只有饱尝爱恋的欢娱，分别才没有遗憾，正如同赏看尽洛阳牡丹，才容易送别春风归去，将人生别离的深情痴推宕放怀遣性的疏放。当然，这豪宕放纵仍难托尽悲沉，花毕竟有“尽”，人终是要“别”，词人只是以遣玩的意兴暂时挣脱伤别的沉重罢了。此词上、下两收拍皆为传诵的名句。\n\n　　这首词开端的“尊（同“樽”）前拟把归期说，欲语春容先惨咽”两句，是对眼前情事的直接叙写，同时其遣辞造句的选择与结构之间，词中又显示出了一种独具的意境。“尊前”，原该是何等欢乐的场合，“春容”又该是何等美丽的人物，而“尊前”所要述说的却是指向离别的“归期”，于是“尊前”的欢乐与“春容”的美丽，乃一变而为伤心的“惨咽”了。这种转变与对比之中，隐然见出欧公对美好事物之爱赏与对人世无常之悲慨二种情绪以及两相对比之中所形成的一种张力。\n\n　　“归期说”之前，所用的乃是“拟把”两个字；而“春容”、“惨咽”之前，所用的则是“欲语”两个字。此词表面虽似乎是重复，然而其间却实含有两个不同的层次，“拟把”仍只是心中之想，而“欲语”则已是张口欲言之际。二句连言，反而更可见出对于指向离别的“归期”，有多少不忍念及和不忍道出的宛转的深情。\n\n　　至于下面二句“人生自是有情痴，此恨不关风与月”，是对眼前情事的一种理念上的反省和思考，而如此也就把对于眼前一件情事的感受，推广到了对于整个人世的认知。所谓“人生自是有情痴”者，古人有云“太上忘情，其下不及情，情之所钟，正我辈”。所以况周颐其《蕙风词话》中就曾说过“吾观风雨，吾览江山，常觉风雨江山之外，别有动吾心者”。这正是人生之自有情痴，原不关于风月，所以说“人生自是有情痴，此恨不关风与月”。此二句虽是理念上的思索和反省，但事实上却是透过了理念才更见出深情之难解。而此种情痴则又正与首二句所写的“樽前”“欲语”的使人悲惨呜咽之离情暗相呼应。所以下片开端乃曰“离歌且莫翻新阕，一曲能教肠寸结”，再由理念中的情痴重新返回到上片的樽前话别的情事。“离歌”自当指樽前所演唱的离别的歌曲，所谓“翻新阕”者，殆如白居易《杨柳枝》所云“古歌旧曲君休听，听取新翻杨柳枝”，与刘禹锡同题和白氏诗所云“请君莫奏前朝曲，听唱新翻杨柳枝”。欧阳修《采桑子》组词前之《西湖念语》，亦云“因翻旧阕之词，写以新声之调”。盖如《阳关》旧曲，已不堪听，离歌新阕，亦“一曲能教肠寸结”也。前句“且莫”二字的劝阻之辞写得如此叮咛恳切，正足以反衬后句“肠寸结”的哀痛伤心。\n\n　　末二句却突然扬起，写出了“直须看尽洛城花，始共春风容易别”的遣玩的豪兴。欧阳修这一首《玉楼春》词，明明蕴含有很深重的离别的哀伤与春归的惆怅，然而他却偏偏结尾写出了如此豪宕的句子。这二句中，他不仅要把“洛城花”完全“看尽”，表现了一种遣玩的意兴，而且他所用的“直须”和“始共”等口吻也极为豪宕有力。然而“洛城花”却毕竟有“尽”，“春风”也毕竟要“别”，因此豪宕之中又实隐含了沉重的悲慨。所以王国维《人间词话》中论及欧词此数句时，乃谓其“于豪放之中有沉着之致，所以尤高”。', poem_tags = '宋词精选,离别,惜别,友情' WHERE poem_title = '玉楼春·尊前拟把归期说' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '在重阳节这天登高回望故乡，身处他乡，设席送朋友离开，举杯之际，分外愁。\n心中已经厌倦了南方客居的各种愁苦，我想北归不得，鸿雁为何还要从北方来。', poem_notes = '九月九日：指重阳节。\n望乡台：古代出征或流落在外乡的人，往往登高或登土台，眺望家乡，这种台称为望乡台。\n他席：别人的酒席。这里指为友人送行的酒席。\n他乡：异乡。\n南中：南方，这里指四川一带。\n那：为何。\n北地：北方。', poem_tags = '重阳节,思乡' WHERE poem_title = '蜀中九日 / 九日登高' AND poem_author = '王勃';
UPDATE edu_poem SET poem_translation = '百花凋零，独有梅花迎着寒风昂然盛开，那明媚艳丽的景色把小园的风光占尽。\n稀疏的影儿，横斜在清浅的水中，清幽的芬芳浮动在黄昏的月光之下。\n寒雀想飞落下来时，先偷看梅花一眼；蝴蝶如果知道梅花的妍美，定会消魂失魄。\n幸喜我能低声吟诵，和梅花亲近，不用敲着檀板唱歌，执着金杯饮酒来欣赏它了。\n\n像剪碎的丝绸点缀着酥酪般的枝干，要画出那姿态和布局确实为难。\n尽情享受着日落春晚，影单应当怯怕霜重夜寒。\n澄洁鲜艳只与相邻的高僧共惜，冷落孤傲犹嫌被俗人一看。\n想起旧时在江南的旅途上，香魂飘落于酒旗下行吟的马鞍。', poem_notes = '暄（xuān）妍：景物明媚鲜丽，这里是形容梅花。\n疏影横斜：梅花疏疏落落，斜横枝干投在水中的影子。疏影，指梅枝的形态。\n暗香浮动：梅花散发的清幽香味在飘动。黄昏：指月色朦胧，与上句“清浅”相对应，有双关义。\n霜禽：羽毛白色的禽鸟。根据林通“梅妻鹤子”的趣称，理解为“白鹤”更佳。偷眼：偷偷地窥看。\n合：应该。断魂：形容神往，犹指销魂。\n狎（xiá）：玩赏，亲近。\n檀（tán）板：檀木制成的拍板，歌唱或演奏音乐时用以打拍子。这里泛指乐器。金樽（zūn）：豪华的酒杯，此处指饮酒。\n绡（xiāo）：生丝绸。酥：酥酪一般的。乾（gān）：枝干。\n向背：面向和背对的姿态。稀稠：疏疏密密的布局。\n日薄：日落。从：任从。甘：甘心。\n澄鲜：清新。\n吟鞍：指吟诗者所骑的马鞍。', poem_appreciation = '林逋种梅养鹤成癖，终身不娶，世称“梅妻鹤子”，所以他眼中的梅含波带情，笔下的梅更是引人入胜。\n\n　　第一首诗一开端就突写作者对梅花的喜爱与赞颂之情：“众芳摇落独暄妍，占尽风情向小园”，它是在百花凋零的严冬迎着寒风昂然盛开，那明丽动人的景色把小园的风光占尽了。一个“独”字、一个“尽”字，充分表现了梅花独特的生活环境、不同凡响的性格和那引人入胜的风韵。作者虽是咏梅，实则是他“弗趋荣利”、“趣向博远”思想性格的真实写照。苏轼曾在《书林逋诗后》说；“先生可是绝伦人，神清骨冷无尘俗。”其诗正是作者人格的化身。\n\n　　颔联是最为世人称道的，它为人们送上了一幅优美的山园小梅图。这一联简直把梅花的气质风姿写尽绝了，它神清骨秀，高洁端庄，幽独超逸。上句轻笔勾勒出梅之骨，下句浓墨描摹出梅之韵，“疏影”、“暗香”二词用得极好，它既写出了梅花不同于牡丹、芍药的独特形成；又写出了它异于桃李浓郁的独有芬芳。极真实地表现诗人在朦胧月色下对梅花清幽香气的感受，更何况是在黄昏月下的清澈水边漫步，那静谧的意境，疏淡的梅影，缕缕的清香，使之陶醉。“横斜”传其妩媚，迎风而歌；“浮动”言其款款而来，飘然而逝，颇有仙风道骨。“水清浅”显其澄澈，灵动温润。“暗香”写其无形而香，随风而至，如同捉迷藏一样富有情趣；“月黄昏”采其美妙背景，从时间上把人们带到一个“月上柳梢头，人约黄昏后”的动人时刻，从空间上把人们引进一个“落霞与孤鹜齐飞，秋水共长天一色”似的迷人意境。首联极目聘怀，颔联凝眉结思。林逋这两句诗也并非是臆想出来的，他除了有生活实感外，还借鉴了前人的诗句。\n\n　　林逋这两句诗也并非是臆想出来的，他除了有生活实感外，还借鉴了前人的诗句。五代南唐江为有残句：“竹影横斜水清浅，桂香浮动月黄昏。”这两句既写竹，又写桂。不但未写出竹影的特点，且未道出桂花的清香。因无题，又没有完整的诗篇，未能构成了一个统一和谐的主题、意境，感触不到主人公的激情，故缺乏感人力量。而林逋只改了两字，将“竹”改成“疏”，将“桂”改成“暗”，这“点睛”之笔，使梅花形神活现，可见林逋点化诗句的才华。\n\n　　上二联皆实写，下二联虚写。\n\n　　作者写尽梅花姿质后，掉转笔头，从客观上着意泻染：“霜禽欲下先偷眼，粉蝶如知合断魂。”前句极写白鹤爱梅之甚，它还未来得及飞下来赏梅，就迫不及待地先偷看梅花几眼。“先偷眼”三字写得很是传神，作者对现实事物的观察是非常细致的。后句则变换手法，用设想之词，来写假托之物，意味深邃。而“合断魂”一词更是下得凄苦凝重，因爱梅而至销魂，这就把蝴蝶对梅的喜爱夸张到了顶端。通过颈联的拟人化手法，从而更进一步衬托出作者对梅花的喜爱之情和幽居之乐。联中那不为人经意的“霜”、“粉”二字，也实是经诗人精心择取，用来表现他高洁情操和淡远的趣味。\n\n　　以上三联，作者是把梅当作主体，诗人的感情是通过议论、叙述、拟人等手法隐曲地体现在咏梅之中。至尾联主体的梅花转化为客体，成为被欣赏的对象。而作者则从客体变为主体，他的感情由隐至显，从借物抒怀变为直抒胸臆：“幸有微吟可相狎，不须檀板共金尊。”尾联“微吟”实讲“口中梅”也，“微”言其淡泊雅致，如此咀嚼，虽不果腹，然可暖心、洁品、动情、铸魂，表达出诗人愿与梅化而为一的生活旨趣和精神追求，至此诗人对梅的观赏进入了冯友兰所说的“天地境界”，人们看到的则是和“霜禽”“粉蝶”一样迫不及待和如痴如醉的诗人——一个梅化的诗人。在赏梅中低声吟诗，使幽居生活平添几分雅兴，在恬静的山林里自得其乐，真是别具风情，根本不须音乐、饮宴那些热闹的俗情来凑趣。这就把诗人的理想、情操、趣味全盘托出，使咏物与抒情达到水乳交融的进步。\n\n　　全诗之妙在于脱略花之形迹，着意写意传神，因而用侧面烘托的笔法，从各个角度渲染梅花清绝高洁的风骨，这种神韵其实就是诗人幽独清高、自甘淡泊的人格写照。\n\n　　第二首诗开头两句是说梅花像是剪碎了的丝织品，上面涂了油酥，正反面有深有浅，多么自然，画是画不出来的。这里用精细轻薄的丝织品绢和油酥制品来比喻悔花的滋润柔美，十分传神。这在宋代诗词作品中一不乏其例，如苏轼《腊梅》诗中就有“天工点酥作梅花”的句子。“向背”、“稀稠‘’描绘了在白天丽日高照下的梅花风姿。接下去说梅花在整个白天直到日薄西山这段时间里，可以尽情地享受春天的温暖，但到夜幕降临的时候，在严霜的侵袭下，梅花可能要受不了吧。梅花本来是以其经霜耐寒的品格受到人们称赞的，“霜深应怯”的顾虑似乎大可不必，但正是这不必要顾虑的顾虑，才能表达出诗人对梅花的无比深情。\n\n　　五、六两句是赞美梅花孤高绝俗的品性：清新鲜艳的梅花只能让隔壁的僧人爱惜，尽管它很冷落，但是还不愿让城里的俗人来观赏。把“邻僧”和“俗客”对举，是因为佛门弟子信奉清净无为的教义，往往和隐逸之士的思想非常合拍，这在历史上是屡见不鲜的。唐代著名诗人王维，在政治上遭到挫折后，就以“诗佛”自居，“晚年唯好静，万事不关心。”（《酬张少府》），看破红尘，成为佛门信徒。二十年足迹不进城市的林逋也是如此。末尾两句是说：回忆过去在梅花盛开、洒旗飘拂的江南路上，微风吹过，梅花簌簌地坠到马鞍上，叫人情不自禁地吟起诗来。以此作结，饶有情趣。\n\n　　从意象构造的角度言，这组诗单言山园小梅，实非易事，但诗人借物来衬，借景来托，使其成为一幅画面中的中心意象，此一绝也。\n\n　　诗人具体写梅画梅时，虚实结合，对比呈现，使得全诗节奏起伏跌宕，色彩时浓时淡，环境动静相宜，观景如梦如幻，充分体现了“山园”的绝妙之处，这一点也是为许多赏家所忽视的，正是通过这一点，作者淋漓尽致地表达出“弗趋荣利”、“趣向博远”精神品格。此二绝也。\n\n　　作者以梅自况，虽展现了中国传统文人的一贯追求，然而也颇具特色。单就“疏影”一联而言，欧阳修说：“前世咏梅者多矣，未有此句也。”陈与义说：“自读西湖处士诗，年年临水看幽姿。晴窗画出横斜影，绝胜前村夜雪时。”（《和张矩臣水墨梅》）他认为林逋的咏梅诗已压倒了唐齐已《早梅》诗中的名句“前村深雪里，昨夜一枝开”。王士朋对其评价更高，誉之为千古绝唱：“暗香和月人佳句，压尽千古无诗才。”辛弃疾在《念奴娇》中奉劝骚人墨客不要草草赋梅：“未须草草赋梅花，多少骚人词客。总被西湖林处士，不肯分留风月。”因为这联特别出名，所以“疏影”、“暗香”二词，就成了后人填写梅词的调名，如姜夔有两首咏梅词即题为《暗香》、《疏影》，此后即成为咏梅的专有名词，可见林逋的咏梅诗对后世文人影响之大。这只说到了其一，更为重要的是梅在林逋的笔下，不再是浑身冷香了，而是充满了一种“丰满的美丽”，很有精神，很有力度，也很温度，很有未来。正因为如此，该诗才有着强烈的现实感，让人感到很真实，回到它的起始状态，作为“梅妻鹤子”的林逋，写出此种具有理想主义倾向的诗句来，是一种富有力量的心灵审美。此三绝也。\n\n　　作者写出此种妙句，亦非唾手可得。宋初另有相当多的诗人，偏重以苦吟的写作方法在狭小的格局中描绘清新小巧的自然景象，表达或是失意怅惘、或是闲适旷达的士大夫情趣，这主要是继承了唐代贾岛、姚合一派的风格，林逋就是这些诗人之一。另外，这组诗格局未免太小，后面自命清高的标榜，也实在有唯恐不为人知的味道。', poem_tags = '古诗三百首,咏物,梅花,寓人,品质' WHERE poem_title = '山园小梅二首' AND poem_author = '林逋';
UPDATE edu_poem SET poem_translation = '奂山的山市,是（淄川）县有名的八景之一，但好几年也难得见到一次。有位名叫孙禹年的公子，同几位志同道合朋友（在）楼上饮酒，忽然看见（奂山）山头有一座孤零零塔耸立起来，高高地插入青天。（大家）面面相觑，惊疑不定，心想附近并没有这么个禅院。没过多久，又出现了几十座高大的宫殿，碧绿色的琉璃瓦，飞翘的殿檐，(人们)这才明白是（出现）山市。不到一会儿，只见一座高高低低的城墙,连绵不断有六七里长，竟然像一座城市。其中(景物）有像楼一样的，有像厅堂一样的，有像街巷一样的，（一个个）清晰地出现在眼前，（多得）可以用亿万来计算。忽然，一阵大风刮起，空气中的尘土之大，城市变得隐隐约约。接着，风停了，天空又变得晴朗起来，刚才的一切都消失了，只有一座高楼，直插云霄，这座楼每层有五间，门窗全都是大开着的；每一行有五处明亮的地方，(透露出)那是楼那边的天空。\n一层层地指着数，楼越高亮点越小，数到第八层，亮点才如星星一般大了；又往上数，就昏暗得看不分明，没法计算层次了。楼上的人往来匆匆，有靠着的，有站立的，形态各不一样。过了一会，楼渐渐低矮下来，可以看见楼顶了，慢慢地又像平常的高楼一样了，又渐渐地像座高房子，突然间又只像拳头那么大，像豆粒那么小，接着就什么也看不见了。\n又听说有起早赶路的人，看见山上有店铺集市（人来人往），和人世间没有两样，所以又叫“鬼市”。', poem_notes = '山市：山市蜃景，与“海市蜃楼”相似。\n奂山 ：山名。旧淄川县有涣山，也写作焕山。\n邑：县。这里指清代淄川县，今属淄博市。\n孙公子禹年 ：对孙禹年的尊称。公子，旧时用来称呼豪门贵族子弟。\n然数年恒不一见 ：经常是多年看不见一次。然，但是。 数年，许多年。恒，经常。\n同人：共事的人或志同道合的友人\n饮：喝酒。 \n青冥 ：青天，天空。青，形容天空的颜色。冥，形容天高远无穷的样子。\n相顾 ：你看看我，我看看你。\n念：想。\n禅院 ：佛寺。禅，佛教用语，表示与佛教有关的事物。\n无何 ：不久，不一会儿。\n碧瓦飞甍：青色的瓦和翘起的屋檐。飞甍：两端翘起的房脊。甍，房脊。\n始悟 ：才明白。始：才，悟：明白\n未几 ：不久，不一会儿。与前边的“无何”含义相同。\n高垣睥睨 ：高高低低的城墙。高垣，高墙。睥睨，又写做“埤堄”。指女墙，即城墙上呈凹凸形的矮墙。\n连亘 ：连绵不断。\n居然城郭 ：竟然变成一座城郭了。居然，竟然。城郭，城市。\n中有楼若者 ：其中有的像楼。\n堂若者 ：有的像厅堂。堂，厅堂。\n坊若者 ：有的像牌坊。坊，街巷、店铺。\n历历在目 ：清晰地出现在眼前。\n以：用。\n莽莽然 ：一片迷茫的样子。莽莽，一片迷茫。\n依稀 ：隐隐约约。\n既而：不久。\n一切乌有：这个词用来形容什么都没有，或者也可以用来形容漏得或者消磨、消耗得所剩无几。现指，所有的（景象）都没有了。乌有，虚幻，不存在。乌，同“无”。\n危楼 ：高楼。危，高。\n直接：连接。\n霄汉 ：云霄与天河。\n窗扉 ：窗户。\n皆：都。\n洞开 ：敞开\n裁如星点 ：才像星星那么小。裁，通“才”，仅仅。\n黯然缥缈 ：黯淡下来，隐隐约约，若有若无。黯然，昏暗的样子缥缈，隐隐约约，若有若无，又作“飘渺”。\n而：然后。\n往来屑屑 ：形容来往匆匆。屑屑，忙碌的样子。\n或：有的人。\n凭 ：靠着。\n不一状 ：形态不一。\n逾时 ：过了一会儿。\n倏忽 ：突然。\n遂 ：终于。\n人烟市肆 ：人家和集市。市肆，集市。肆，店铺。\n孤 ：孤零零。\n耸 ：耸立。\n惊疑 ：惊奇，疑惑。\n碧 ：青绿色。\n同人：同业朋友。\n然：但是。\n数：几。\n明（出自文中“则明渐少”）：光亮。\n行（出自文中“又闻有早行者”）：赶路（另一说行也为走的意思）\n与世无别：跟尘世上的情形没有什么区别。\n孙公子禹年：对孙禹年的尊称。\n风定天清：大风停止，天空晴朗。\n孤塔耸起：意思是孤零零的一座塔耸立起来。\n\n通假字\n裁如星点：裁通“才”，仅仅，只有,刚刚。\n乌:乌通“无”，没有。\n\n词类活用\n故又名“鬼市”云 （名：叫，称。名词用作动词）。\n窗扉皆洞开（洞：像洞一样，名词作状语）。\n中有楼若者，堂若者，坊若者（名词作状语。依次译为：城市中有像楼台的，有像厅堂的，有像牌坊的）。\n楼渐低(低：降低。形容词作动词）\n\n古今异义\n恒：\n古义：常常，经常。\n今义：持久，普通。\n顾：\n古义：看。\n今义：注意。\n念：\n古义：1.思考、思虑 2.惦念、怀思 3. 诵读\n今义：1.想念 2.读.\n悟：\n古义：明白。\n今义：了解。\n始：\n今义：开始。\n危楼:\n古义：高楼。危，高耸。\n今义：危险的楼。\n直接:\n古义：一直连接到。\n今义：不经过中间的事物。\n黯然：\n古义：1.黑色的样子 2.暗淡无光的样子 3.神情沮丧的样子 4.和谐顺利的意思。\n今义：1.阴暗的样子 2.心里不舒服，情绪低落。\n层次：\n古义:层数 。\n今义:说话、作文的次序。\n睥睨：\n古义：城墙上面呈凹凸形的短墙，亦称女墙。\n今义：眼睛斜着向旁边看，形容傲慢的样子。\n居然：\n古义：竟然。\n今义：表示出乎意料,在自己意料之外\n（原文：然数年恒不一见）连词，但是，然而（表转折）。\n(原文：尘气莽莽然）助词，……的样子。\n（原文：居然城郭矣）尾词，副词后缀。\n数:\n（原文：见宫殿数十所）量词，几，几个。\n（原文：数至八层，裁如星点）动词，计数。（原文：然数年恒不一见）多。\n(原文：中有楼若者，堂若者,坊若者）有想楼台的，有想厅堂的，有像牌坊的。\n无何：\n古义：不久，一会儿。\n今义：没有什么。\n以：\n（原文：以亿万计）用，(形容很多)。', poem_tags = '初中文言文,叙事,写景' WHERE poem_title = '山市' AND poem_author = '蒲松龄';
UPDATE edu_poem SET poem_translation = '唱完了《阳关》曲泪却未干，视功名为馀事（志不在功名）而劝加餐。水天相连，好像将两岸的树木送向无穷的远方，乌云挟带着雨水，把重重的高山掩埋了一半。\n古往今来使人愤恨的事情，何止千件万般，难道只有离别使人悲伤，聚会才使人欢颜？江头风高浪急，还不是十分险恶，而人间行路却是更艰难。', poem_notes = '唱彻《阳关》：唱完送别的歌曲。 彻，完；《阳关》，琴歌《阳关三叠》。\n馀，多余；加餐，多吃饭。\n无穷：无尽，无边。\n今古，古往今来；般，种。\n只应，只以为，此处意为“岂只”。\n未是：还不是。\n别有：更有。', poem_tags = '宋词精选,送别,感伤' WHERE poem_title = '鹧鸪天·送人' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '自从我们在京城分别一晃又三年，远涉天涯你奔走辗转在人间。相逢一笑时依然像春天般的温暖。你心如古井水不起波澜，高风亮节象秋天的竹竿。\n我心惆怅因你要连夜分别扬孤帆，送行之时云色微茫月儿淡淡。陪酒的歌妓不用冲着酒杯太凄婉。人生就是一趟艰难的旅程，你我都是那匆匆过客，就如在不同的客栈停了又走，走了又停。', poem_notes = '临江仙：唐教坊曲，用作词调。又名《谢新恩》、《雁后归》、《画屏春》、《庭院深深》、《采莲回》、《想娉婷》、《瑞鹤仙令》、《鸳鸯梦》、《玉连环》。敦煌曲两首，任二北《敦煌曲校录》定名\n《临江仙》。此词双调六十字，平韵格。\n钱穆：名勰，又称钱四。元佑三年，因坐奏开封府狱空不实，出知越州（今浙江绍兴）。元佑五年，又徙知瀛洲（治所在今河北河间）。元佑六年春，钱穆父赴任途中经过杭州，苏轼作此词以送。\n父：是对有才德的男子的美称。\n都门：是指都城的城门。\n改火：古代钻木取火，四季换用不同木材，称为“改火”，这里指年度的更替。\n春温：是指春天的温暖。\n古井：枯井。比喻内心恬静，情感不为外界事物所动。\n筠：竹。\n翠眉：古代妇女的一种眉饰，即画绿眉，也专指女子的眉毛。\n颦：皱眉头。\n逆旅：旅店。', poem_appreciation = '这首词是公元1091年（宋哲宗元祐六年）春苏轼知杭州时，为送别自越州（今浙江绍兴）北徙途经杭州的老友钱穆父（名勰）而作。全词一改以往送别诗词缠绵感伤、哀怨愁苦或慷慨悲凉的格调，创新意于法度之中，寄妙理于豪放之外，议论风生，直抒性情，写得既有情韵，又富理趣，充分体现了作者旷达洒脱的个性风貌。词人对老友的眷眷惜别之情，写得深沉细腻，婉转回互，一波三折，动人心弦。\n\n　　词的上片写与友人久别重逢。元祐初年，苏轼朝为起居舍人，钱穆父为中书舍人，气类相善，友谊甚笃。元祐三年穆父出知越州，都门帐饮时，苏轼曾赋诗赠别。岁月如流，此次杭州重聚，已是别后的第三个年头了。三年来，穆父奔走于京城、吴越之间，此次又远赴瀛州，真可谓“天涯踏尽红尘”。分别虽久，可情谊弥坚，相见欢笑，犹如春日之和煦。更为可喜的是友人与自己都能以道自守，保持耿介风节，借用白居易《赠元稹》诗句来说，即“无波古井水，有节秋竹竿”。作者认为，穆父出守越州，同自己一样，是由于朝好议论政事，为言官所攻。\n\n　　以上数句，先从时间着笔，回忆前番离别，再就空间落墨，概述仕宦生涯，接下来抒发作者对仕宦失意、久处逆境所持的达观态度，并用对偶连喻的句式，通过对友人纯一道心、保持名节的赞颂，表明了自己淡泊的心境和坚贞的操守。词的上片既是对友人辅君治国、坚持操守的安慰和支持，也是词人半生经历、松柏节操的自我写照，是词人的自勉自励，寓有强烈的身世之感。明写主，暗寓客；以主慰客，客与主同，表现出作者与友人肝胆相照，志同道合。\n\n　　词的下片切入正题，写月夜送别友人。“惆怅孤帆连夜发，送行淡月微云”一句，描绘出一种凄清幽冷的氛围，渲染了作者与友人分别时抑郁无欢的心情。\n\n　　“樽前不用翠眉颦”一句，由哀愁转为旷达、豪迈，说离宴中歌舞相伴的歌妓用不着为离愁别恨而哀怨。这一句，其用意一是不要增加行者与送者临歧的悲感，二是世间离别本也是常事，则亦不用哀愁。这二者似乎有矛盾，实则可以统一强抑悲怀、勉为达观这一点上，这符合苏轼宦途多故之后锻炼出来的思想性格。词末二句言何必为暂时离别伤情，其实人生如寄，李白《春夜宴从弟桃花园序》云：“夫天地者，万物之逆旅也，光阴者，百代之过客也。”既然人人都是天地间的过客，又何必计较眼前聚散和江南江北呢？词的结尾，以对友人的慰勉和开释胸怀总收全词，既动之以情，又揭示出得失两忘、万物齐一的人生态度。\n\n　　苏轼一生虽积极入世，具有鲜明的政治理想和政治主张，但另一方面又受老庄及佛家思想影响颇深，每当官场失意、处境艰难时，他总能“游于物之外”，“无所往而不乐”，以一种恬淡自安、闲雅自适的态度来应对外界的纷纷扰扰，表现出超然物外、随遇而安的旷达、洒脱情怀。这首送别词中的“一笑作春温”、“樽前不用翠眉颦。人生如逆旅，我亦是行人”等句，是苏轼这种豪放性格、达观态度的集中体现。然而在这些旷达之语的背后，仍能体察出词人对仕宦浮沉的淡淡惆怅，以及对身世飘零的深沉慨叹。', poem_tags = '豪放,送别,友情,慰勉' WHERE poem_title = '临江仙·送钱穆父' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_tags = '端午节,风俗,怀古' WHERE poem_title = '屈原塔' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '金杯中的美酒一斗价十千，玉盘里的菜肴珍贵值万钱。\n但心情愁烦使得我放下杯筷，不愿进餐。拔出宝剑环顾四周，心里一片茫然。\n想渡过黄河，坚冰堵塞大川；想登太行山，大雪遍布高山。\n遥想当年，姜太公溪垂钓，得遇重才的文王，伊尹乘舟梦日，受聘在商汤身边。\n人生的道路何等艰难，何等艰难，歧路纷杂，真正的大道究竟在哪边？\n坚信乘风破浪的时机定会到来，到那时，将扬起征帆远渡碧海青天。\n\n大道虽宽广如青天，唯独没有我的出路。\n我不愿意追随长安城中的富家子弟，去搞斗鸡走狗一类的赌博游戏。\n像冯谖那样弹剑作歌发牢骚，在权贵之门卑躬屈节，那不合我心意。\n韩信发迹之前被淮阴市井之徒讥笑，贾谊才能超群遭汉朝公卿妒忌。\n君不见古时燕昭王重用郭隗，拥篲折节、谦恭下士，毫不嫌疑猜忌。\n剧辛和乐毅感激知遇的恩情，竭忠尽智，以自己的才能为君主效力。\n而今燕昭王之白骨已隐于荒草之中，还有谁能像他那样重用贤士呢？\n世路艰难，我只得归去啦！\n\n不要学许由用颍水洗耳，不要学伯夷和叔齐隐居收养采薇而食。\n在世上活着贵在韬光养晦，为什么要隐居清高自比云月?\n我看自古以来的贤达之人，功绩告成之后不自行隐退都死于非命。\n伍子胥被吴王弃于吴江之上，屈原最终抱石自沉汨罗江中。\n陆机如此雄才大略也无法自保，李斯以自己悲惨的结局为苦。\n陆机是否还能听见华亭别墅间的鹤唳？李斯是否还能在上蔡东门牵鹰打猎？\n你不知道吴中的张翰是个旷达之人，因见秋风起而想起江东故都。\n生时有一杯酒就应尽情欢乐，何须在意身后千年的虚名？', poem_notes = '樽（zūn）：古代盛酒的器具，以金为饰。清酒：清醇的美酒。斗十千：一斗值十千钱（即万钱），形容酒美价高。\n珍羞：珍贵的菜肴。羞：同“馐”，美味的食物。直：通“值”，价值。\n箸（zhù）：筷子。\n闲来垂钓碧溪上，忽复乘舟梦日边：这两句暗用典故：姜太公吕尚曾在渭水的磻溪上钓鱼，得遇周文王，助周灭商；伊尹曾梦见自己乘船从日月旁边经过，后被商汤聘请，助商灭夏。这两句表示诗人自己对从政仍有所期待。碧：一作“坐”。\n多岐路，今安在：岔道这么多，如今身在何处？岐：一作“歧”。安：哪里。\n长风破浪：比喻实现政治理想。据《宋书·宗悫传》载：宗悫少年时，叔父宗炳问他的志向，他说：“愿乘长风破万里浪”\n云帆：高高的船帆。船在海里航行，因天水相连，船帆好像出没在云雾之中。\n社：古二十五家为一社。白狗：一作“白雉”。\n弹剑：战国时齐公子孟尝君门下食客冯谖曾屡次弹剑作歌怨己不如意。\n贾生：洛阳贾谊，曾上书汉文帝，劝其改制兴礼，受时大臣反对。\n拥篲：燕昭王亲自扫路，恐灰尘飞扬，用衣袖挡帚以礼迎贤士邹衍。折节：一作“折腰”。\n归去来：指隐居。语出东晋陶渊明《归去来辞》。\n首阳蕨：《史记·伯夷列传》：“武王已平殷乱，天下宗周，而伯夷、叔齐耻之，义不食周粟，隐于首阳山，采薇而食之……遂饿死于首阳山。”《索引》：“薇，蕨也。”按薇、蕨本二草，前人误以为一。\n含光混世贵无名：此句言不露锋芒，随世俯仰之意。《高士传》：巢父谓许由曰：“何不隐汝形，藏汝光？”\n自古贤达人：鲍照《拟行路难》：“自古圣贤尽贫贱”。《史记·蔡泽列传》：“四时之序，成功者去。……商君为秦孝公明法令，……功已成矣，而遂以车裂。……白起……功已成矣，而遂赐剑死于杜邮。吴起……功已成矣，而卒枝解。大夫种为越王深谋远计……令越成霸，功已彰而信矣，勾践终负而杀之。此四子者，功成不去，祸至于身？”\n子胥：伍子胥，春秋末期吴国大夫。《吴越春秋》卷五《夫差内传》：“吴王闻子胥之怨恨也，乃使人赐属镂之剑，子胥……遂伏剑而死。吴王乃取子胥尸，盛以鸱夷之器，投之于江中。”又见《国语·吴语》。\n陆机雄才岂自保：《晋书·陆机传》载：陆机因宦人诬陷而被杀害于军中，临终叹曰：“华亭鹤唳，岂可复闻乎？”\n李斯税驾苦不早：李斯，秦国统一六国的大功臣，任秦朝丞相，后被杀。《史记·李斯列传》载：李斯喟然叹曰：“……斯乃上蔡布衣……今人臣之位，无居臣上者，可谓富贵极矣。物极则衰，吾未知所税驾？”《索引》：“税驾，犹解驾，言休息也。”\n华亭鹤唳讵可闻？上蔡苍鹰何足道：这两句还是写李斯。《史记·李斯列传》：“二世二年七月，具斯五刑，论腰斩咸阳市。斯出狱，与其中子俱执，顾谓其中子曰：‘吾欲与若复牵黄犬俱出上蔡东门逐狡兔，岂可得乎！’”《太平御览》卷九二六：《史记》曰：“李斯临刑，思牵黄犬、臂苍鹰，出上蔡门，不可得矣。”\n秋风忽忆江东行：这句写张翰。《晋书·张翰传》：“张翰，字季鹰，吴郡吴人也。……为大司马东曹掾。……因见秋风起，乃思吴中菰菜、莼羹、鲈鱼脍，曰：‘人生贵得适志，何能羁官数千里，以要名爵乎？’遂命驾而归。……或谓之曰：‘卿乃纵适一时，独不为身后名邪？’答曰：‘使我有身后名，不如即时一杯酒。’时人贵其旷达。”', poem_appreciation = '“行路难”多写世道艰难，表达离情别意。李白《行路难》共三首，蘅塘退士辑选其一。诗以“行路难”比喻世道险阻，抒写了诗人在政治道路上遭遇艰难时，产生的不可抑制的激愤情绪；但他并未因此而放弃远大的政治理想，仍盼着总有一天会施展自己的抱负，表现了他对人生前途乐观豪迈的气概，充满了积极浪漫主义的情调。\n\n　　诗开头写“金樽清酒”、“玉盘珍馐”，描绘了一个豪华盛大的饯行宴饮场面。接着写“停杯投箸”、“拔剑四顾”，又向读者展现了作者感情波涛的冲击。中间四句，既感叹“冰塞川”、“雪满山”、又恍然神游千载之上，看到了吕尚、伊尹忽然得到重用。“行路难”四个短句，又表现了进退两难和继续追求的心理。最后两句，表达了尽管理想与现实有着巨大的距离，尽管诗人内心痛苦，但还是在沉郁中振起，坚定了信心，重新鼓起了沧海扬帆的勇气。\n\n　　全诗在高度彷徨与大量感叹之后，以“长风破浪会有时”忽开异境，并且坚信美好前景，终会到来，因而“直挂云帆济沧海”，激流勇进。蕴意波澜起伏，跌宕多姿。', poem_tags = '怀才不遇,励志,组诗' WHERE poem_title = '行路难三首' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '人人都说江南好，游人应该在江南待到老去。春天的江水清澈碧绿比天空还青，游人可以在有彩绘的船上听着雨声入眠。\n江南酒家卖酒的女子长得很美，卖酒撩袖时露出的双臂洁白如雪。年华未衰之时不要回乡，回到家乡后必定悲痛到极点。', poem_notes = '游人只合江南老：这里指飘泊江南的人，即作者自谓。只合：只应。江南好：白居易《忆江南》词首句为“江南好”。碧于天：一片碧绿，胜过天色。\n垆边：指酒家。垆，旧时酒店用土砌成酒瓮卖酒的地方。《史记·司马相如列传》记载，司马相如妻卓文君长得很美，曾当垆卖酒：“买一酒舍沽就，而令文君当垆。”\n皓腕凝霜雪：形容双臂洁白如雪。凝霜雪，像霜雪凝聚那样洁白。\n未老莫还乡，还乡须断肠：年尚未老，且在江南行乐。如还乡离开江南，当使人悲痛不已。须：必定，肯定。', poem_appreciation = '这首诗是《菩萨蛮五首》中的第二首，对第一首的回应。难道主人公不愿意回到家中吗？可是自己求取功名不得，又怎能轻言回去呢？“人人尽说江南好。游人只合江南老。”写得多美！但这种美，不是靠意象的美而烘托，却是靠浓挚的情感，而且是经过理性的浸润后的浓挚的情感动人。江南之美，甲于天下，但寓居在此，逃避战乱的人，又怎么会有归属感？故这两句是沉郁的。“春水碧于天。画船听雨眠。”说的是碧绿的春水，比天空还要明净，躺在游船画舫之中，和着雨声入睡，又是何等之美，何等之空灵。前二句的沉郁，与后二句的空灵，就形成了难以言喻的艺术张力。\n\n　　过片暗用卓文君之典。汉时蜀人司马相如，与巨富卓王孙之女卓文君私奔，因卓王孙宣布与文君断绝关系，司马相如就令文君当垆，自己穿着短裤，在大街上洗涤酒器。所以“炉边人似月。皓腕凝双雪”，炉就是酒垆，炉边人指的就是自己的妻子，也就是上一首中“绿窗人”。主人公何尝不思念这位面如皎月、肤色赛霜雪的妻子？但是“未老莫还乡。还乡须断肠”，古人云富贵而不还乡，就像衣锦而夜行，而一事无成的人，回到家乡，心情却只有更加抑郁哀凉。这两句没有任何艺术技巧可言，纯粹靠人生阅历和情感动人，成为千古名句。清末大词人王鹏运提出，写词要符合“重、大、拙”三字诀，这两句就是“拙”的审美境界。', poem_tags = '宋词三百首,婉约,江南,思乡' WHERE poem_title = '菩萨蛮·人人尽说江南好' AND poem_author = '韦庄';
UPDATE edu_poem SET poem_translation = '我对书籍的感情就像是多年的朋友，无论清晨还是傍晚忧愁还是快乐总有它的陪伴。\n眼前浏览过无数的文字后，胸中再无半点尘世间世俗的杂念。\n新鲜的想法源源不断的涌来用之不竭，像东风里花柳争换得形色簇新。\n漫跨着金鞍，权贵们犹叹芳踪难寻，谅也不信这书斋里别有春景。', poem_notes = '故人：老朋友。此用拟人手法，将书卷比拟作“故人”。\n“相亲”句：晨昏：即早晚，一天到晚．晨：早上。昏：黄昏。忧：愁。每：时常。亲：近。\n三千字。此为泛指，并非确数。此句说明作者读书多且快，同时也写出他那种如饥似渴的情态。\n胸次：胸中，心里。尘：杂念。这句说作者专心读书，胸无杂念，\n“活水”句：化用朱熹《观书有感》（其一）诗中：“问渠那得清如许，谓有源头活水来。”\n逐：挨着次序。\n金鞍：饰金的马鞍。玉勒：饰玉的马笼头。此泛指马鞍、笼头的贵美。\n庐：本指乡村一户人家所占的房地，引申为村房或小屋的通称。这里指书房。', poem_appreciation = '该诗盛赞书之好处，讲开卷有益之理，极写读书之趣，作者于谦，是明代著名民族英雄、诗人。他生性刚直，博学多闻。他的勤学苦练精神与他的高风亮节一样名传后世。这首诗写诗人自我亲身体会，抒发喜爱读书之情，意趣高雅，风格率直，说理形象，颇有感染力。\n\n　　“书卷多情是故人，晨昏忧乐每相亲。”书本好似感情真挚的老友，每日从早到晚和自己形影相随、愁苦与共，形象地表明诗人读书不倦、乐在其中。本诗开篇，即以个人读书的独特体会，谈出自己和书本的亲密关系。中间两联，集中写己读书之乐。\n\n　　“眼前直下三千字，胸次全无一点尘。”眼前的书，一读即是无数字，读书之多之快，表现诗人读书如饥似渴的心情，胸中顿觉爽快，全无一点杂念。“直下三千字”，写为书所吸引；“全无一点尘”，写书本知识荡涤心胸，心无杂念。这两句诗使诗人专心致志，读书入迷的情态跃然纸上，也道出了一种读书方法。\n\n　　“活水随流随处满，东风花柳逐时新。”活水句，化用朱熹《观书有感》“问渠那得清如许，谓有源头活水来”句，是说坚持经常读书，就象池塘不断有活水注入，不断得到新的营养，永远清澈。“东风”句是说勤奋攻读，不断增长新知，就象东风催开百花，染绿柳枝一样，依次而来，其乐趣令人心旷神怡 。\n\n　　“金鞍玉勒寻芳客，未信我庐别有春。”结尾一联，以“金鞍玉勒寻芳客”为陪衬，写出书斋之乐。“勒”为马笼头。“金鞍玉勒”者是富贵公子，再缀以“寻芳客”三字，直是富家浪子。这些人日以寻花问柳为能是，他们和作者是两个不同世界之人，故而他们自然不会相信书斋之中别有一个烂漫的春天。以贵公子反衬，显示读书人书房四季如春的胜景。读书可以明理，可以赏景，可以观史，可以鉴人，可谓是思接千载，视通万里，这美好之情之境，不是玩物丧志的游手好闲者流所能领略的。', poem_tags = '赞美,读书' WHERE poem_title = '观书' AND poem_author = '于谦';
UPDATE edu_poem SET poem_translation = '在金字题名的榜上，我只不过是偶然失去取得状元的机会。即使在政治清明的时代，君王也会一时错失贤能之才，我今后该怎么办呢？既然没有得到好的机遇，为什么不随心所欲地游乐呢！何必为功名患得患失？做一个风流才子为歌姬谱写词章，即使身着白衣，也不亚于公卿将相。\n在歌姬居住的街巷里，有摆放着丹青画屏的绣房。幸运的是那里住着我的意中人，值得我细细地追求寻访。与她们依偎，享受这风流的生活，才是我平生最大的欢乐。青春不过是片刻时间，我宁愿把功名，换成手中浅浅的一杯酒和耳畔低徊婉转的歌唱。', poem_notes = '鹤冲天：词牌名。柳永大作，调见柳永《乐章集》。双调八十四字，仄韵格。另有词牌《喜迁莺》、《风光好》的别名也叫鹤冲天，“黄金榜上”词注“正宫”。\n黄金榜：指录取进士的金字题名榜。\n龙头：旧时称状元为龙头。\n明代：圣明的时代。一作“千古”。遗贤：抛弃了贤能之士，指自己为仕途所弃。\n如何向：向何处。\n风云：际会风云，指得到好的遭遇。\n争不：怎不。恣：放纵，随心所欲。\n得丧：得失。\n白衣卿相：指自己才华出众，虽不入仕途，也有卿相一般尊贵。白衣：古代未仕之士著白衣。\n烟花：指妓女。巷陌：指街巷。\n丹青屏障：彩绘的屏风。丹青：绘画的颜料，这里借指画。\n堪：能，可以。\n恁：如此。偎红倚翠：指狎妓。宋陶谷《清异录·释族》载，南唐后主李煜微行娼家，自题为“浅斟低唱，偎红倚翠大师，鸳鸯寺主”。\n平生：一生。\n饷：片刻，极言青年时期的短暂。\n忍：忍心，狠心。浮名：指功名。', poem_appreciation = '这首词反映了柳永的反叛性格，也带来了他人生路上一大波折。据传说，柳永善作俗词，而宋仁宗颇好雅词。有一次，宋仁宗临轩放榜时想起柳永这首词中那句“忍把浮名，换了浅斟低唱”，就说道：“且去浅斟低唱，何要浮名”，就这样黜落了他。从此，柳永便自称“奉旨填词柳三变”而长期地流连于坊曲之间、花柳丛中寻找生活的方向、精神的寄托。\n\n　　“黄金榜上，偶失龙头望”，考科举求功名，他并不满足于登进士第，而是把夺取殿试头名状元作为目标。落榜只认为“偶然”，“见遗”只说是“暂”，由此可见柳永狂傲自负的性格。他自称“明代遗贤”是讽刺仁宗朝号称清明盛世，却不能做到“野无遗贤”。但既然已落第，下一步该怎么办呢？“风云际会”，施展抱负是封建时代士子的奋斗目标，既然“未遂风云便”，理想落空了，于是他就转向了另一个极端，“争不恣狂荡”，表示要无拘无束地过那种为一般封建士人所不齿的流连坊曲的狂荡生活。“偎红倚翠”、“浅斟低唱”，是对“狂荡”的具体说明。柳永这样写，是恃才负气的表现，也是表示抗争的一种方式。科举落第，使他产生了一种逆反心理，只有以极端对极端才能求得平衡。所以，他故意要造成惊世骇俗的效果以保持自己心理上的优势。柳永的“狂荡”之中仍然有着严肃的一面，狂荡以傲世，严肃以自律，这才是“才子词人”、“白衣卿相”的真面目。柳永把他内心深处的矛盾想法抒写出来，说明落第这件事情给他带来了多么深重的苦恼和多么烦杂的困扰，也说明他为了摆脱这种苦恼和困扰曾经进行了多么痛苦的挣扎。写到最后，柳永得出结论：“青春都一饷。忍把浮名，换了浅斟低唱！”谓青春短暂，怎忍虚掷，为“浮名”而牺牲赏心乐事。所以，只要快乐就行，“浮名”算不了什么。\n\n　　这首词是柳永进士科考落第之后的一纸“牢骚言”，在宋元时代有着重大的意义和反响。它正面鼓吹文人士者与统治者分离，而与歌妓等下层人民接近，有一定的思想进步性。', poem_tags = '宋词三百首,考试,抒怀,豪迈' WHERE poem_title = '鹤冲天·黄金榜上' AND poem_author = '柳永';
UPDATE edu_poem SET poem_translation = '天地是万物的客舍，百代是古往今来时间的过客，死生的差异，就好像梦与醒的不同，纷纭变换，不可究诘，得到的欢乐，又能有多少呢！古人夜间执着火炬游玩实在是有道理啊，况且春天用艳丽景色召唤我，大自然把各种美好的形象赐予我，相聚在桃花飘香的花园中，畅叙兄弟间快乐的往事。弟弟们英俊优秀，个个都有谢惠连那样的才情，而我作诗吟咏，却惭愧不如谢灵运。清雅的赏玩兴致正雅，高谈阔论又转向清言雅语。摆开筵席来坐赏名花，快速地传递着酒杯醉倒在月光中，没有好诗，怎能抒发高雅的情怀?倘若有人作诗不成，就要按照当年石崇在金谷园宴客赋诗的先例，谁咏不出诗来，罚酒三杯。', poem_notes = '桃花园，疑在安陆兆山桃花岩。从：cóng（旧读zòng），堂房亲属。从弟：堂弟。\n逆旅：客舍。 逆：迎接。 旅：客。 迎 客止歇，所以客舍称逆旅。\n过客：过往的客人。李白《拟古十二首》其九：“生者为过客。”\n浮生若梦：意思是，死生之差异，就好像梦与醒之不同，纷纭变化，不可究诘。\n秉烛夜游：谓及时行乐。秉：执。《古诗十九首》其十五：“昼短苦夜长，何不秉烛游。“曹丕《与吴质书》：“少壮真当努力，年一过往，何可攀援！古人思秉烛夜游，良有以也。有以：有原因。这里是说人生有限，应夜以继日的游乐。秉，执。以，因由，道理。\n阳春：和煦的春光。召：召唤，引申为吸引。烟景：春天气候温润，景色似含烟雾。\n大块：大地。大自然。假：借，这里是提供、赐予的意思。文章：这里指绚丽的文采。古代以青与赤相配合为文，赤与白相配合为章。\n序：通“叙”，叙说。天伦：指父子、兄弟等亲属关系。这里专指兄弟。\n群季：诸弟。兄弟长幼之序，曰伯(孟）、仲、叔、季，故以季代称弟。季：年少者的称呼。古以伯（孟）、仲、叔、季排行，季指同辈排行中最小的。这里泛指弟弟。\n惠连：谢惠连，南朝诗人，早慧。这里以惠连来称赞诸弟的文才。\n咏歌：吟诗。\n康乐：南朝刘宋时山水诗人谢灵运，袭封康乐公，世称谢康乐。\n“幽赏”二句：谓一边欣赏着幽静的美景，一边谈论着清雅的话题。\n琼筵（yán）：华美的宴席。坐花：坐在花丛中。\n羽觞（shāng）：古代一种酒器，作鸟雀状，有头尾羽翼。醉月：醉倒在月光下。\n金谷酒数：金谷，园名，晋石崇于金谷涧(在今河南洛阳西北)中所筑，他常在这里宴请宾客。其《金谷诗序》：“遂各赋诗，以叙中怀，或不能者，罚酒三斗。“后泛指宴会上罚酒三杯的常例。', poem_appreciation = '这篇文章主要在说李白和其诸弟相聚一同歌唱一同饮酒的情景，深刻的表现出天伦之乐和兄弟之情，虽然文章篇幅不长，但却能令人有回味无穷之感，现时现况下，能拥有如些深厚的兄弟之情真的是不多见了，但却往往看到新闻报告：兄弟隙墙、反目成仇诸如些类的天伦悲剧，唉！这怎能叫人不心寒呢? 相形之下，我们的手足之情该算什麼呢?\n\n　　兄弟就是「手足」，为什么叫「手足」呢? 就是因为手与脚是不能分开的，只要手脚合作那就没有不能完成的事，同样的，只要兄弟同心，其力是可以断金的，这就和一根筷子折的断，但十根筷子要一次折断就不容易了哦！！所以我们更加要珍惜手足之情，将它扩大之朋友之情，如此一来，社会哪有不进步、国家哪有不强之理呢?\n\n　　本文以清新俊逸的风格，转折自如的笔调，记叙了作者与诸位堂在桃花园聚会赋诗畅叙天伦一事，慷慨激昂地表达了李白热爱生活、热爱生命的人生追求和积极乐观的人生态度。', poem_tags = '古文观止,宴饮,抒怀,序文' WHERE poem_title = '春夜宴桃李园序 / 春夜宴从弟桃花园序' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '青山隐隐约约绿水千里迢迢，秋时已尽江南草木还未枯凋。\n二十四桥明月映照幽幽清夜，你这美人现在何处教人吹箫？', poem_notes = '韩绰：事不详，杜牧另有《哭韩绰》诗。判官：观察使、节度使的属官。时韩绰似任淮南节度使判官。\n迢迢：指江水悠长遥远。一作“遥遥”。\n草未凋（diāo）：一作“草木凋”。凋：凋谢。\n二十四桥：一说为二十四座桥。北宋沈括《梦溪笔谈·补笔谈》卷三中对每座桥的方位和名称一一做了记载。一说有一座桥名叫二十四桥，清李斗《扬州画舫录》卷十五：“廿四桥即吴家砖桥，一名红药桥，在熙春台后，……扬州鼓吹词序云，是桥因古二十四美人吹箫于此，故名。”\n玉人：貌美之人。这里是杜牧对韩绰的戏称。一说指扬州歌妓。教：使，令。', poem_appreciation = '扬州之盛，唐世艳称，历代诗人为它留下了多少脍炙人口的诗篇。这首诗风调悠扬，意境优美，千百年来为人们传诵不衰。韩绰不知何人，杜牧集中赠他的诗共有两首，另一首是《哭韩绰》，看来两人友情甚笃。\n\n　　首句从大处落墨，化出远景：青山逶迤，隐于天际，绿水如带，迢递不断。“隐隐”和“迢迢”这一对叠字，不但画出了山清水秀、绰约多姿的江南风貌，而且隐约暗示着诗人与友人之间山遥水长的空间距离，那抑扬的声调中仿佛还荡漾着诗人思念江南的似水柔情。欧阳修的《踏莎行》：“离愁渐远渐无穷，迢迢不断如春水”、“平芜尽处是青山，行人更在青山外”，正道出了杜牧这句诗的言外之意。此时虽然时令已过了深秋，江南的草木却还未凋落，风光依旧旖旎秀媚。正由于诗人不堪晚秋的萧条冷落，因而格外眷恋江南的青山绿水，越发怀念远在热闹繁花之乡的故人了。\n\n　　江南佳景无数，诗人记忆中最美的印象则是在扬州“月明桥上看神仙”（张祜《纵游淮南》）的景致。岂不闻“天下三分明月夜，二分无赖是扬州”（徐凝《忆扬州》），更何况当地名胜二十四桥上还有神仙般的美人可看呢？二十四桥，一说扬州城里原有二十四座桥，一说即吴家砖桥，因古时有二十四位美人吹箫于桥上而得名。“玉人”，既可借以形容美丽洁白的女子，又可比喻风流俊美的才郎。从寄赠诗的作法及末句中的“教”字看来，此处玉人当指韩绰。元稹《莺莺传》“疑是玉人来”句可证中晚唐有以玉人喻才子的用法。诗人本是问候友人近况，却故意用玩笑的口吻与韩绰调侃，问他当此秋尽之时，每夜在何处教妓女歌吹取乐。这样，不但韩绰风流倜傥的才貌依稀可见，两人亲昵深厚的友情得以重温，而且调笑之中还微微流露了诗人对自己“十年一觉扬州梦，赢得青楼薄幸名”的感喟，从而使此诗平添了许多风韵。杜牧又长于将这类调笑寄寓在风调悠扬、清丽俊爽的画面之中，所以虽写艳情却并不流于轻薄。这首诗巧妙地把二十四美人吹箫于桥上的美丽传说与“月明桥上看神仙”的现实生活融合在一起，因而在客观上造成了“玉人”又是指歌妓舞女的恍惚印象，读之令人如见月光笼罩的二十四桥上，吹箫的美人披着银辉，宛若洁白光润的玉人，仿佛听到呜咽悠扬的箫声飘散在已凉未寒的江南秋夜，回荡在青山绿水之间。这样优美的境界早已远远超出了与朋友调笑的本意，它所唤起的联想不是风流才子的放荡生活，而是对江南风光的无限向往：秋尽之后尚且如此美丽，当其春意方浓之时又将如何迷人？这种内蕴的情趣，微妙的思绪，“可言不可言之间”的寄托，“可解不可解之会”的指归（见叶燮《原诗》），正是这首诗成功的奥秘。', poem_tags = '唐诗三百首,调笑,写景,友情,怀念' WHERE poem_title = '寄扬州韩绰判官' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '云儿淡，风儿轻，时近春日中午，傍着花，随着柳，我向河岸漫步。\n这惬意的春游呀，人们并不了解，将会说我忙里偷闲，强学少年童。\n\n散译\n淡淡的云在天上飘，风儿吹拂着我的脸庞，此时此刻已近正午，我穿行于花丛之中，沿着绿柳，不知不觉间来到了前面的河边。\n当时的人不理解我此时此刻我内心的快乐，还以为我在学年轻人的模样，趁着大好时光忙里偷闲呢。', poem_notes = '偶成：偶然写成。\n云淡：云层淡薄，指晴朗的天气。 午天：指中午的太阳。\n傍花随柳：傍随于花柳之间。傍，靠近，依靠。随，沿着。 川：瀑布或河畔。\n时人：一作“旁人”。 余心：我的心。余：一作“予”，我。\n将谓：就以为。将：乃，于是，就。 偷闲：忙中抽出空闲的时间。', poem_appreciation = '这是一首即景诗，描写春天郊游的心情以及春天的景象，也是一首写理趣的诗，作者用朴素的手法把柔和明丽的春光同作者自得其乐的心情融为一体。\n\n　　诗的前二句“云淡风轻近午天，傍花随柳过前川”，看似十分平淡，但如细细品味，却有几层意思在其中。其一，写自己春游所见、所感。云淡风轻，傍花随柳，寥寥数笔，不仅出色地勾画出了春景，而且强调了动感—和煦的春风吹拂大地，自己信步漫游，到处是艳美的鲜花，到处是袅娜多姿的绿柳，可谓“人在图画中”。其二，着重写自己留连忘返的心情。这种心情主要是通过‘近午天”、“过前川”六字自然而然地传达出来的。所谓“近午天”，并不是说自己时至中午才出来游春，而是用“近”来强调自己只顾春游忘了时间，用自已的突然发现来表现自己沉醉于大自然的心情。同样，“过前川”也并不仅仅是简单地描写自己向河岸漫步的情况，而是用“过”来强调自己在春花绿柳的伴随下“过”了前面的河流才发现自己只顾游春，不知不觉已经走了很远很远。这样，这两句诗尽管描写的只是云风花柳等自然景观和作者喜爱它们的心情，但其中更隐括着一种作者要忘世脱俗的高稚情调，正是这种情调，才使他几乎忘记了时间，忘记了疲劳，达到了如醉如痴的境界。\n\n　　假如说，诗的前两句主要是写情写景的话，那么，“时人不识余心乐，将谓偷闲学少年”，则主要是诗人自己内心世界的直接抒发。本来，在云淡风轻的大好春色中漫游，在春花绿柳的簇拥中陶冶自己的情性，这应该是十分自然的事，但是，在扼杀人们性灵的封建时代，这似乎只应该是有些“狂”劲儿的少年人才能千，而须眉长者只应该端然危坐，摆出一副冷冰冰的面孔才行。然而，尽管程颢是一位著名的理学家，尽管他写这首诗时很可能已经是一位蔼然长者，可他仍然无法抗拒大自然对他的吸引，做出一些为“时人”所不能理解的举动。这其中包括了他对自然真性的追求和理解，同时也包括了他对一般“时人”的嘲笑与讽刺，既表现了他对子人生价值的另一种认识，也表现出了他乐在其中，孤芳自赏的高雅。至此，一向被人们认为是道貌岸然的理学家也有意无意地披露了他性格的另一个侧面：他不仅生活在令人窒息的“理”的世界中，还是一个对大自然充满感情的活生生的人，只不过他的感情经常被“理”压抑和扭曲罢了。', poem_tags = '古诗三百首,春天,哲理,思乡' WHERE poem_title = '春日偶成' AND poem_author = '程颢';
UPDATE edu_poem SET poem_translation = '谁说我们没衣穿？与你同穿那长袍。君王发兵去交战，修整我那戈与矛，杀敌与你同目标。\n谁说我们没衣穿？与你同穿那内衣。君王发兵去交战，修整我那矛与戟，出发与你在一起。\n谁说我们没衣穿？与你同穿那战裙。君王发兵去交战，修整甲胄与刀兵，杀敌与你共前进。', poem_notes = '袍：长袍，即今之斗篷。\n王：此指秦君。一说指周天子。于：语助词。兴师：起兵。\n同仇：共同对敌。\n泽：通“襗”，内衣，如今之汗衫。\n作：起。\n裳：下衣，此指战裙。\n甲兵：铠甲与兵器。\n行：往。', poem_appreciation = '这首诗充满了激昂慷慨、同仇敌忾的气氛。按其内容，当是一首战歌。全诗表现了秦国军民团结互助、共御外侮的高昂士气和乐观精神，其独具矫健而爽朗的风格正是秦人爱国主义精神的反映。\n\n　　当时的秦国位于今甘肃东部及陕西一带。那里木深土厚，民性厚重质直。班固在《汉书·赵充国辛庆忌传赞》中说秦地“民俗修习战备，高上勇力，鞍马骑射。故秦诗曰：‘王于兴诗，修我甲兵，与子偕行。’其风声气俗自古而然，今之歌谣慷慨风流犹存焉。”朱熹《诗集传》也说：“秦人之俗，大抵尚气概，先勇力，忘生轻死，故其见于诗如此。”这首诗意气风发，豪情满怀，确实反映了秦地人民的尚武精神。在大敌当前、兵临城下之际，他们以大局为重，与周王室保持一致，一听“王于兴师”，他们就一呼百诺，紧跟出发，团结友爱，协同作战，表现出崇高无私的品质和英雄气概。\n\n　　由于此诗旨在歌颂，也就是说以“美”为主，所以对秦军来说有巨大的鼓舞力量。据《左传》记载，鲁定公四年（公元前506年），吴国军队攻陷楚国的首府郢都，楚臣申包胥到秦国求援，“立依于庭墙而哭，日夜不绝声，勺饮不入口，七日，秦哀公为之赋《无衣》，九顿首而坐，秦师乃出”。于是一举击退了吴兵。可以想像，在秦王誓师的时候，此诗犹如一首誓词；对士兵们来说，则又似一首动员令。\n\n　　如前所述，秦人尚武好勇，反映在这首诗中则以气概胜。诵读此诗，不禁为诗中火一般燃烧的激情所感染，那种慷慨激昂的英雄主义气概令人心驰神往。之所以造成这样的艺术效果，第一是每章开头都采用了问答式的句法。一句“岂曰无衣”，似自责，似反问，洋溢着不可遏止的愤怒与愤慨，仿佛在人们复仇的心灵上点上一把火，于是无数战士同声响应：“与子同袍！”“与子同泽！”“与子同裳！”第二是语言富有强烈的动作性：“修我戈矛！”“修我矛戟！”“修我甲兵！”使人想像到战士们在磨刀擦枪、舞戈挥戟的热烈场面。这样的诗句，可以歌，可以舞，堪称激动人心的活剧。\n\n　　诗共三章，采用了重叠复沓的形式。每一章句数、字数相等，但结构的相同并不意味简单的、机械的重复，而是不断递进，有所发展的。如首章结句“与子同仇”，是情绪方面的，说的是他们有共同的敌人。二章结句“与子偕作”，作是起的意思，这才是行动的开始。三章结句“与子偕行”，行训往，表明诗中的战士们将奔赴前线共同杀敌了。这种重叠复沓的形式固然受到乐曲的限制，但与舞蹈的节奏起落与回环往复也是紧密结合的，而构成诗中主旋律的则是一股战斗的激情，激情的起伏跌宕自然形成乐曲的节奏与舞蹈动作，正所谓“长言之不足，故嗟叹之。嗟叹之不足，故不知手之舞之足之蹈之也。”（《礼记·乐记》）', poem_tags = '诗经,赞美,爱国' WHERE poem_title = '秦风·无衣' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '菩提原本就没有树， 明亮的镜子也并不是台。\n佛性就是一直清澈干净，哪里会有什么尘埃？\n\n众生的身体就是一棵觉悟的智慧树， 众生的心灵就象一座明亮的台镜。\n明亮的镜子本来就很干净，哪里会染上什么尘埃？\n\n菩提原本就没有树， 明亮的镜子也并不是台。\n本来就是虚无没有一物， 哪里会染上什么尘埃?\n\n菩提只是向着内心寻找，何必劳累向外界求取玄妙的佛家思想？\n以此进行修行自身，极乐世界也就在眼前！', poem_notes = '菩提偈：“菩提”，梵文的音译，意译为“觉”或“智”，旧译也作“道”。指对佛教教义的理解，或是通向佛教理想的道路。偈，和尚唱颂的歌诗称为偈。菩提偈，即诠释佛教教义的歌偈。\n树：这里指菩提树，意译为“觉树”或“道树”。相传佛教始祖释迦牟尼在此树下证得菩提，觉悟成道，故称此树为菩提树。但这种树的本名是什么，有多种不同的说法。据说南朝梁时僧人智药曾把这种树自天竺移植中国。《雷州府志》记载：“菩提果色白者，味甜，五月熟。海南琼山县则把这种树所结的果子称为金刚子。这种果子可作念珠。佛教徒常焚香散花，绕树行礼。今广东省曲江县南华寺藏经阁旁左右两侧，各有一棵菩提树。” \n明镜：据《资持记》下二之三：“坐禅之处，多悬明镜，以助心行。”通常用以比喻佛与众生感应的中介。台：指安置明镜的地方，可以借代为客观存在。\n佛性：是梵汉并译名词，意译为“觉性”、“如来性”，有时被称为“涅”，或叫“真如”，也是“如来藏”的异名。原指佛陀本性，发展为成佛的可能性，是佛教徒所追求的修行目标和理想境界。这个问题，小乘和大乘的观点不一致，提出种种不同的见解，引起长期争论。中国南北朝时盛谈佛性，隋唐各宗也重视佛性说。天台宗提出五种佛性，法相宗归结为两种佛性，华严宗更把“有情”众生的佛性与“非情”之物的法性区别开来。清净：佛教术语，远恶行，离惑垢，称为清净。\n尘埃：佛教术语，指人间的一切世俗事务。按出家人的观点，世务不净，故称尘务。\n玄：佛教术语，这里是指玄妙的佛教理想。《信心铭》：“不识玄者，徒劳念佛。”对于佛教徒来说，通晓玄机，是至关重要的。\n西方：佛教术语，指净土所在的极乐世界。过去，佛教徒认为：东方日出，是万物滋生之地；西方日落，才是万物终归之处。因此，传统的教义都认定佛教徒要以西方（或称西天）为其归宿。惠能的这个观点，实是对西方“净土”的否定，为“顿悟”成佛提供了理论根据。', poem_appreciation = '第一首偈，见于敦煌写本《坛经》。关于这首诗的来历，《坛经》第四节至第八节，有明白的记载：五祖弘忍“一日唤门人尽来”，要大家“各作一偈”。并说“若悟大意者”，即“付汝衣法，禀为六代”。弘忍的上首弟子神秀在门前写了一偈道：“身是菩提树，心如明镜台。时时勤拂拭，莫使有尘埃。”弘忍知道后，“遂唤神秀上座于堂内”，说是“汝作此偈，见即未到”，“若觅无上菩提，即未可得”，因而要他“更作一偈”。而“秀上座去数日，作不得”。惠能的偈语，即针对神秀的《无相偈》而发。据《坛经》所载，惠能本不识字，他先“请人一读”神秀的偈语，然后作此歌偈，“请得一解书人于西间壁上题着”。\n\n　　这首偈，同神秀的那一首，在修行方法上具有原则的区别。神秀的那首“无相偈”，使他失去作为弘忍继承人的资格，却成了北宗一派的开山祖。由于神秀强调“时时勤拂拭”，后人以其主张“拂尘看净”，称之为“渐修派”。而惠能的这一首，是对神秀偈的彻底否定，也即主观唯心主义对客观唯心主义的彻底否定，直接把握住“见性成佛”的关键，被称为“顿悟派”。\n\n　　在《坛经》第二十节，惠能指出：“世人性本自净，万法在自性。思量一切恶事，即行于恶；思量一切善事，使修于善行。”这是惠能“顿悟说”的基础。在他看来，“愚人”与“智人”，“善人”与“恶人”，他们和“佛”之间，没有不可逾越的鸿沟。从“迷”到“悟”，仅在一念之间。这种“放下屠刀，立地成佛”的思想，不仅对我国佛教的演变产生了巨大的作用，对于后来的中国哲学理论也有重大的影响。\n\n　　第二首偈，也是惠能针对神秀的《无相偈》所作的。旨在说明“明镜”的清净，也即“自性”的清净，这是佛教徒坚信能到达理想境界人人所共有的主观条件。该偈亦见于敦煌写本《坛经》，但据郭朋《坛经校释》考证，这一首当属衍文。特别是前两句，虽调换了“身”、“心”二字的位置，实际也是重复神秀的话，不应视为惠能的思想。\n\n　　第三首偈，见于《六祖法宝·坛经》，流传甚广，为《全唐诗外编》所补录。据郭朋《坛经校释》考证，这一首是由《菩提偈》第一首演化而成，关键在第三句，由惠昕本带头，契嵩本、宗宝本因之，把“佛性常清净”改成“本来无一物”。这是一种误解，早在宋代即有人提出非议。郭朋认为：“《坛经》的首窜者，不仅不了解‘佛性’论，而且也不了解‘性空’说。”其实，大乘佛教的所谓“空”、“无”，是就“妄心”、“妄境”而言；若就“真心”、“真境”而论，则决非“绝无”。在《坛经》第十五节，惠能有言：“有灯即有光，无灯即无光。灯是光之体，光是灯之用。”在《坛经》第二十四节，惠能又说：“虚空能含日月星辰、大地山河，一切草木、恶人善人、恶法善法、天堂地狱，尽在空中；世人性空，亦复如是。”这些都足以证明惠能的思想体系，同“一切万法，自性本空”的理论完全不同。不过在这句话之前，惠能先说：“心量广大，犹如虚空。”他把一切归结于“心”，也即“自性”。这是典型的主观唯心主义观点。但无论如何，把“佛性常清净”和“本来无一物”等同起来，是不适当的。\n\n　　第四首偈，见于《大正藏·坛经》，着重讲修行方法。《坛经》第三十五节，惠能引佛言：“随其心净，则佛土净。”接着说：“心但无不净，西方去此不远；心起不净之心，念佛往生难到。” 《坛经》第三十六节说：“若见真道，行正即是道；自若无正心，暗行不见道。自若无佛心，向何处求佛！”《坛经》第五十二节说：“我心自有佛，自佛是真佛；自若无佛心，向何处求佛！”《坛经》第五十三节又说：“若能心中自有真，有真即是成佛因；自不求真外觅佛，去觅总是大痴人。”反复申明向人的自我求真，自我求佛，这是惠能教导其弟子立地成佛的唯一途径。在他看来，求佛的人只图自悟，不假外示，心注一境，化难为易，自能达到目的。论根据。', poem_tags = '修行,哲理' WHERE poem_title = '菩提偈' AND poem_author = '惠能';
UPDATE edu_poem SET poem_tags = '春节,思念' WHERE poem_title = '除夜太原寒甚' AND poem_author = '于谦';
UPDATE edu_poem SET poem_translation = '船在吴江上飘摇，我满怀羁旅的春愁，看到岸上酒帘子在飘摇，招揽客人，便产生了借酒消愁的愿望。船只经过令文人骚客遐想不尽的胜景秋娘渡与泰娘桥，也没有好心情欣赏，眼前是“风又飘飘，雨又潇潇”，实在令人烦恼。\n哪一天能回家洗客袍，结束客游劳顿的生活呢？哪一天能和家人团聚在一起，调弄镶有银字的笙，点燃熏炉里心字形的盘香？春光容易流逝，使人追赶不上，樱桃才红熟，芭蕉又绿了，春去夏又到。', poem_notes = '吴江：今江苏县名。在苏州南。\n浇：浸灌，消除。\n帘招：指酒旗。\n秋娘渡：指吴江渡。秋娘：唐代歌伎常用名，或有用以通称善歌貌美之歌伎者。又称杜仲阳，为唐德宗时镇海军节度史李侍女。渡：一本作“度”。\n桥：一本作“娇”。\n萧萧：象声，雨声。\n银字笙：管乐器的一种。调笙，调弄有银字的笙。\n心字香，点熏炉里心字形的香。', poem_appreciation = '这是一首写在离乱颠簸的流亡途中的心歌。明艳的春光与凄楚的神魂在强烈地对照着，春深似海，愁深胜似海，在时光的流逝中，“春愁”却无法排遣。于是从看似浏亮的声韵中读者听到了夹杂着风声雨声的心底的呜咽声。\n\n　　词大致作在南宋亡后蒋捷飘零于姑苏一带太湖之滨的阶段。这里原是个山柔水软的江南秀丽地。一个彷徨四顾，前程茫茫，时光空抛，有家难归的游子置身在此境地里，怎能不惆怅莫名呢？词的上片初一看无非写春愁难解，借酒浇愁而已。略加细察，可以看出此中有大起伏，情思在跌宕中激越波荡。词人的一腔“春愁”待酒以浇的渴望，在“江上舟摇”的飘流中是得到瞬间的满足的。“楼上帘招”这江村小酒店的或许写有“太白一醉”字样的青布帘招知词人，可来醉乡小憩。在这一“摇”一“招”之间，情绪是由愁而略见开颜了的。可是当江上小舟载着这薄醉之人继续行去，醉眼惺忪地在眼帘上映入“秋娘渡与泰娘桥”的景色时，风吹酒醒，雨滴心帘，只觉风入骨，雨寒心。转而“秋愁”复涨，而且愈涨愈高了。情绪的起伏就是如此激转湍漩。“秋娘渡”、“泰娘桥”指的是吴江一带地名。蒋捷的《行香子·舟宿间湾》词就有“过窈娘堤，秋娘渡，泰娘桥”之句。词人在此处以“秋娘渡”与“泰娘桥”指代苏州吴江一带景物之美——秀婉妩媚令人愉悦的美。正是这美景愈触发其愁思，思念起了在家的“笑涡红透”、“软语灯前”的妻室。\n\n　　“风又飘飘，雨又萧萧”的句式正是一种暗示法的句式，是某种特定心态借助意象的表现方法。它让人可以产生听觉上的风声雨声，视觉上的潇潇绵绵、飘飘扬扬，触觉上的寒意、潮意、湿润意，一直到心态上的感知：酸辛感、苦涩感。这手法在下片中也出现的：“流光容易把人抛，红了樱桃，绿了芭蕉。”一“红”一“绿”，将春光渐渐消逝于初夏的来临中这个过程充分表现了出来。这是时序的暗示。但细加辨味，芭蕉叶绿，樱桃果红，花落花开，回黄转绿，大自然一切可以年年如此，衰而盛，盛而衰，可是人呢？绿肥红瘦对人来说意味着青春不再，盛世难逢。再进一步推去，家国呢？一旦破败，还能重见么？“流光容易把人抛”的全过程，怎样抛的，本极抽象，现今以“红了樱桃，绿了芭蕉”明示出来。所以，如果说，暗示具体时序由春而夏，那是“实”的表现，那么将抽象的流光抛人揭示开来就是“虚”的具体化。这八个字真是妙极了的。至于色彩的自然绚丽，语言的准确性那是可以不言而喻的。\n\n　　明白了这些，“何日归家洗客袍”之问就显得不只是一般的游子之家情了。从词的脉络说，这一句暗接上片的因风雨之声而强化了的触景生情，即使内心的愈发高涨的“春愁”由心底浮出来，具体化，外现。但从内在情思看，这“洗客袍”即结束飘流的不安定生活，重新过着由佳人相伴，素手调笙，烧起心字形清香的宁静怡乐的生活——可能吗？“何日归家”正是无望之叹！莫说有家难归，即使归家了，“客袍”洗涴得了么？国已破，家难在！对一个忠贞之士来说，从此将是无尽的流亡生涯，往昔温馨雅事都已在“何日”之问中一去不复返。失落了这样的心境，也就结束了这样的情事，这是肯定的，所以“何日”之间，其实他已是自答了的。由此而读下去，“流光容易把人抛”已如前面分析，在这看似明畅的词句中包裹的是怎样一颗紧缩的心，岂非一目了然。\n\n　　这里有意把下片诸句倒过顺序来谈，又将“何日归家洗客袍”置于上下片的关联点上去理解，是想从具体的句式和情思上说明这首短词形似明快，实则苦涩，在艺术上具有似“流”实“留”的特点，情韵在回环周转地流荡，呈一种漩涡状。这种艺术手段最能将“剪不断，理还乱”的情意充分表达出。“流”，是流畅少停蓄，而“留”则有顿挫，有吞吐，有抑扬之势。蒋捷确有一些词写得稍嫌“流”，但这首《一剪梅》却不属此类作品，不可匆匆浏览，不细辨味。\n\n　　《一剪梅》词牌的特点是在舒徐（七字句）与急促（四字叠句）的节奏较整齐的交替中显现动人的音乐性的。自周邦彦以来，有不少名句，如李清照“才下眉头，又上心头”等。后又经辛弃疾的创作，使四字叠句完全由散而整，构成排句重叠的规定性，音乐性更强了。而且往往突出画面的重叠或心境的重叠。到蒋捷手里，特别是这首《一剪梅·舟过吴江》传世，《一剪梅》的表现手法更为丰富，四组四字相叠的排句也往往写得灵动流丽，名篇更多了。', poem_tags = '宋词三百首,婉约,伤春,思归' WHERE poem_title = '一剪梅·舟过吴江' AND poem_author = '蒋捷';
UPDATE edu_poem SET poem_translation = '秋风刮起，白云飞。草木枯黄雁南归。\n秀美的是兰花呀，芳香的是菊花。思念美人难忘怀。\n乘坐着楼船行驶在汾河上，划动船桨扬起白色的波浪。\n吹起箫来打起鼓，欢乐过头哀伤多。\n年轻的日子早过去，渐渐衰老没奈何。', poem_notes = '辞：韵文的一种。\n黄落：变黄而枯落。\n秀：此草本植物开花叫“秀”。这里比佳人颜色。芳：香气，比佳人香气。兰、菊：这里比拟佳人。“兰有秀”与“菊有芳”，互文见义，意为兰和菊均有秀、有芳。\n佳人：这里指想求得的贤才。\n泛：浮。楼船：上面建造楼的大船。泛楼船，即“乘楼船”的意思。汾河：起源于山西宁武，西南流至河津西南入黄河。\n中流：中央。扬素波：激起白色波浪。\n鸣：发声，响。发：引发，即“唱”。棹（zhào）：船桨。这里代指船。棹歌：船工行船时所唱的歌。\n极：尽。\n奈老阿：对老怎么办呢？', poem_appreciation = '诗开篇写道：“秋风起兮白云飞，草木黄落兮雁南归。”阵阵秋风卸白云而飞，岸边的树木已不复葱郁，然而纷纷飘坠的金色的落叶，为秋日渲染了一副斑斓的背景。大雁苍鸣，缓缓掠过樯桅……短短两句，清远流丽。\n\n　　胡应麟《诗薮·内编》卷三：“秋风百代情至之宗。”秋日乃惹人思情，虽有幽兰含芳，秋菊斗艳，然凋零的草木，归雁声声，勾起汉武帝对“佳人”不尽的思念之情：“兰有秀兮菊有芳，怀佳人兮不能忘。”此句写的缠绵流丽乃一诗之精华，正如张玉谷《古诗赏析》卷三：“此辞有感秋摇落系念仙意。怀佳人句，一篇之骨……”\n\n　　“泛楼船兮济汾河，横中流兮扬素波。萧鼓鸣兮发棹歌”三句，竭力描写汉武帝泛舟中流、君臣欢宴景致。当楼船在汾河中流疾驶，潺缓的碧水，顿时扬起一片白色的波浪。在酒酣耳热之际，不禁随着棹橹之声叩舷而歌。\n\n　　紧接着却出现了“欢乐极兮哀情多”。君临天下，当藐视一世，俯视天地之间，应慨然得意忘形尔。何来如此幽情哀音？王尧衢《古诗合解》卷一一语道破：“乐极悲来，乃人情之常也。愁乐事可复而盛年难在。武帝求长生而慕神仙，正为此一段苦处难谴耳。念及此而歌啸中流，顿觉兴尽，然自是绝妙好辞”原来，即便是君王也免不了生老病死，眼前的尊贵荣华终有尽时，人生老之将至，所有一切也会随着死亡不复存在，所以又怎能不因为“少壮几时兮奈老何”而忧伤呢？', poem_tags = '古诗三百首,秋天,写风,乐府,人生,岁月' WHERE poem_title = '秋风辞' AND poem_author = '刘彻';
UPDATE edu_poem SET poem_translation = '江南的风景多么美好，风景久已熟悉。春天到来时，太阳从江面升起，把江边的鲜花照得比火红，碧绿的江水绿得胜过蓝草。怎能叫人不怀念江南？\n\n江南的回忆，最能唤起追思的是杭州：游玩天竺寺寻找中秋的桂子，登上郡亭，枕卧其上，欣赏钱塘江大潮。什么时候能够再次去游玩？\n\n江南的回忆，再来就是回忆苏州的吴宫，喝一喝吴宫的美酒春竹叶，看一看吴宫的歌女双双起舞像朵朵迷人的芙蓉。清晨夜晚总要再次相逢。', poem_notes = '忆江南：唐教坊曲名。作者题下自注说：“此曲亦名‘谢秋娘’，每首五句。”按《乐府诗集》：“‘忆江南’一名‘望江南’，因白氏词，后遂改名‘江南好’。”至晚唐、五代成为词牌名。这里所指的江南主要是长江下游的江浙一带。\n谙（ān）：熟悉。作者年轻时曾三次到过江南。\n江花：江边的花朵。一说指江中的浪花。红胜火：颜色鲜红胜过火焰。\n绿如蓝：绿得比蓝还要绿。如，用法犹“于”，有胜过的意思。蓝，蓝草，其叶可制青绿染料。\n“山寺”句：作者《东城桂》诗自注说：“旧说杭州天竺寺每岁中秋有月桂子堕。”桂子，桂花。宋柳永《望海潮·东南形胜》词：“有三秋桂子，十里荷花。”\n郡亭：疑指杭州城东楼。看潮头：钱塘江入海处，有二山南北对峙如门，水被夹束，势极凶猛，为天下名胜。\n吴宫：指吴王夫差为西施所建的馆娃宫，在苏州西南灵岩山上。\n竹叶：酒名。即竹叶青。亦泛指美酒。《文选·张协〈七命〉》：“乃有荆南乌程，豫北竹叶，浮蚁星沸，飞华蓱接。”\n吴娃：原为吴地美女名。《文选·枚乘〈七发〉》：“使先施、徵舒、阳文、段干、吴娃、闾娵、傅予之徒……嬿服而御。”此词泛指吴地美女。醉芙蓉：形容舞伎之美。\n早晚：犹言何日，几时。北齐颜之推《颜氏家训·风操》：“尝有甲设宴席，请乙为宾；而旦于公庭见乙之子，问之曰：‘尊侯早晚顾宅？’”', poem_appreciation = '诗人早年因避乱来到江南，曾经旅居苏、杭二州。晚年又担任杭、苏刺史多年。江南的山山水水、一草一木给他留下了极深的印象。他也与那里的人民结下了深挚的友谊，直到晚年回到北方以后，仍然恋恋不已。三首《忆江南》词就是这种心情下的产物。作品表达了诗人对祖国大好河山的热爱，对以后文人词的发展，也产生了积极的作用。\n\n　　《忆江南·江南忆》的前一首是突出描绘杭州这个被人喻为可同天堂媲美的地方来验证“江南好”。古神话中有月中桂树的传说。《南部新书》载：“杭州灵隐寺多桂，寺僧曰：‘此月中种也。’至今中秋望夜，往往子堕，寺僧亦尝拾得。”可见这寺中月桂的说法不过是寺僧自神其说而已。但是，生活真实不等于艺术真实，作品运用这一传说，意在表达杭州的非同凡俗。同时“山寺月中寻桂子”也表现了诗人浪漫的想像，读者眼前仿佛现出怒放的丹桂，闻到桂子浓郁的芳香。次句“郡亭枕上看潮头”则描绘了杭州浙江入海的奇观。诗人通过对当年山寺寻桂和钱塘观潮两个代表性的生活画面的描写，仅用两句话就足以使人想见杭州之多彩多姿。\n\n　　后一首词是描绘苏州之美。苏州有当年吴王夫差为美人西施修建的馆娃宫等风景名胜古迹，有名叫“竹叶春”的美酒佳酿，苏州的女子也更美丽多姿，能歌善舞，她们的舞姿，令人联想到那在风中沉醉的荷花。诗人以美妙的诗笔，简洁地勾勒出苏州的旖旎风情，令人无比神往。\n\n　　两首《忆江南·江南忆》各自独立而又互为补充，分别描绘杭州与苏州的景色美，风物美和女性之美，每首都以“江南忆”开篇，而以直接深情之句作结，艺术概括力强，意境奇妙，使人读其词而直欲奔向江南实地观览一番。这两首词与《忆江南·江南好》既是各自独立成篇又是互为联系的整体。', poem_tags = '宋词三百首,怀念,江南,地名' WHERE poem_title = '忆江南三首' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '你将木瓜投赠我，我拿琼琚作回报。不是为了答谢你，珍重情意永相好。\n\n你将木桃投赠我，我拿琼瑶作回报。不是为了答谢你，珍重情意永相好。\n\n你将木李投赠我，我拿琼玖作回报。不是为了答谢你，珍重情意永相好。', poem_notes = '木瓜：一种落叶灌木（或小乔木），蔷薇科，果实长椭圆形，色黄而香，蒸煮或蜜渍后供食用。按：今粤桂闽台等地出产的木瓜，全称为番木瓜，供生食，与此处的木瓜非一物。\n琼琚（jū）：美玉，下“琼玖”“琼瑶”同。\n匪：非。\n木桃：果名，即楂子，比木瓜小。\n木李：果名，即榠楂，又名木梨。', poem_appreciation = '《诗经·大雅·抑》有“投我以桃，报之以李”之句，后世“投桃报李”便成了，成语，比喻相互赠答，礼尚往来。比较起来，《卫风·木瓜》这一篇虽然也有从“投之以木瓜（桃、李），报之以琼琚（瑶、玖）”生发出的成语“投木报琼”（如托名宋尤袤《全唐诗话》就有“投木报琼，义将安在”的记载），但“投木报琼”的使用频率却根本没法与“投桃报李”相提并论。可是论传诵程度还是《木瓜》更高，它是现今传诵最广的《诗经》名篇之一。\n\n　　对于这么一首知名度很高而语句并不复杂的先秦古诗，古往今来解析其主旨的说法居然也有七种之多（据张树波《国风集说》统计）。按，成于汉代的《毛诗序》云：“《木瓜》，美齐桓公也。卫国有狄人之败，出处于漕，齐桓公救而封之，遗之车马器物焉。卫人思之，欲厚报之，而作是诗也。”这一说法在宋代有严粲（《诗缉》）等人支持，在清代有魏源（《诗古微》）等人支持。与毛说大致同时的三家诗，据陈乔枞《鲁诗遗说考》考证，鲁诗“以此篇为臣下思报礼而作”，王先谦《诗三家义集疏》意见与之相同。从宋代朱熹起，“男女相互赠答说”开始流行，《诗集传》云：“言人有赠我以微物，我当报之以重宝，而犹未足以为报也，但欲其长以为好而不忘耳。疑亦男女相赠答之词，如《静女》之类。”这体现了宋代《诗》学废序派的革新疑古精神。但这一说法受到清代《诗》学独立思考派的重要代表之一姚际恒的批驳，《诗经通论》云：“以（之）为朋友相赠答亦奚不可，何必定是男女耶！”现代学者一般从朱熹之说，而且更明确指出此诗是爱情诗。因此诗主旨说法多不同，而“木瓜”作为文学意象也就被赋予了多种不同的象征意义。其中“臣子思报忠于君主”“爱人定情坚于金玉”“友人馈赠礼轻情重”三种意象逐渐成为“木瓜”意象的主流内涵。\n\n　　《木瓜》一诗，从章句结构上看，很有特色。首先，其中没有《诗经》中最典型的句式——四字句。这不是没法用四字句（如用四字句，变成“投我木瓜（桃，李），报以琼琚（瑶、玖）；匪以为报，永以为好”，一样可以），而是作者有意无意地用这种句式造成一种跌宕有致的韵味，在歌唱时易于取得声情并茂的效果。其次，语句具有极高的重叠复沓程度。不要说每章的后两句一模一样，就是前两句也仅一字之差，并且“琼琚”“琼瑶”“琼玖”语虽略异义实全同，而“木瓜”“木桃”“木李”据李时珍《本草纲目》考证也是同一属的植物．其间的差异大致也就像橘、柑、橙之间的差异那样并不大。这样，三章基本重复，而如此高的重复程度在整部《诗经》中也并不很多，格式看起来就像唐代据王维诗谱写的《阳关三叠》乐歌似的，——自然这是《诗经》的音乐与文学双重性决定的。\n\n　　“你赠给我果子，我回赠你美玉”，与“投桃报李”不同，回报的东西价值要比受赠的东西大得多，这体现了一种人类的高尚情感（包括爱情，也包括友情）。这种情感重的是心心相印，是精神上的契合，因而回赠的东西及其价值的高低在此实际上也只具有象征性的意义，表现的是对他人对自己的情意的珍视，所以说“匪报也”。“投我以木瓜（桃、李），报之以琼琚（瑶、玖）”，其深层语义当是：虽汝投我之物为木瓜（桃、李），而汝之情实贵逾琼琚（瑶、玖）；我以琼琚（瑶、玖）相报，亦难尽我心中对汝之感激。清牛运震《诗志》评此数语云：“惠有大于木瓜者，却以木瓜为言，是降一格衬托法；琼瑶足以报矣，却说匪报，是进一层翻剥法。”他的话并非没有道理，但将木瓜、琼瑶之类已基本抽象化的物品看得太实，其他解此诗者似也有此病。实际上，作者胸襟之高朗开阔，已无衡量厚薄轻重之心横亘其间，他想要表达的就是：珍重、理解他人的情意便是最高尚的情意。从这一点上说，后来汉代张衡《四愁诗》“美人赠我金错刀，何以报之英琼瑶”，尽管说的是“投金报玉”。其意义实也与“投木报琼”无异。', poem_tags = '古诗三百首,诗经,感激' WHERE poem_title = '木瓜' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '淡黄色的桂花，并不鲜艳，但体态轻盈。于幽静之处，不惹人注意，只留给人香味。不需要具有名花的红碧颜色。桂花色淡香浓，应属最好的。\n　　（和桂花相比）梅花一定妒嫉，菊花自当羞惭。桂花是秋天里百花之首，天经地义。可憾屈原对桂花不太了解，太没有情意了。不然，他在《离骚》中赞美那么多花，为什么没有提到桂花呢？', poem_notes = '鹧鸪天：词牌名。\n“画阑”句：化用李贺《金铜仙人辞汉歌》的“画栏桂树悬秋香”之句意，谓桂花为中秋时节首屈一指的花木。\n“骚人”二句：取意于陈与义《清平乐·木犀》的“楚人未识孤妍，《离骚》遗恨千年”之句意。“骚人”、“楚人”均指屈原。可煞：疑问词，犹可是。情思：情意。何事：为何。此二句意谓《离骚》多载花木名称而未及桂花。', poem_appreciation = '这首《鹧鸪天》词是一篇盛赞桂花的作品。在李清照词中，咏花之作很多，但推崇某花为第一流者还仅此一篇。它与《摊破浣溪沙》同为作者与丈夫居住青州时的作品。\n\n　　作为供观赏的花卉，艳丽的色彩是惹人喜爱的一个重要原因。此篇的上片正是抓住桂花“色”的特点来写的。“暗淡轻黄体性柔”，“暗”“淡”“轻”三字是形容桂花的色是暗黄、淡黄、轻黄。“体性柔”说这种花的花身和性质。\n\n　　“情疏迹远只香留。”这种树多生于深山中，宋之问诗：“为问山东桂，无人何自芳。”李白诗：“安知南山桂，绿叶垂芳根。”所以对人来说是迹远而情疏的，可是它的香却不因此而有所减少。\n\n　　“何须浅碧深红色，自是花中第一流。”作者以为，浅碧、深红在诸颜色中堪称美妙，然而，这些美妙的颜色，对于桂花来说，却是无须添加的。因为它浓郁的香气，温雅的体性已足使她成为第一流的名花，颜色淡一点又有什么要紧呢？\n\n　　上片围绕“色”与“香”的矛盾展开形象化的议论，生动地表现了作者的美学观点。对于“花”这个具体的审美对象来说，“色”属于外在美的范畴，“味”属于内在美的范畴，作者以为色淡味香的桂花“自是花中第一流”，足见作者对于内在美是很推崇的。\n\n　　下片的“梅定妒，菊应羞，画栏开处冠中秋”，是紧承上一片的意思写的。梅花，虽然开在早春，开在百花之前，而且姿容秀丽，仪态万千。但是，面对着“暗淡轻黄体性柔”的桂花，她却不能不生嫉妒之意；菊花，虽然开在深秋，独放百花之后，而且清雅秀美，幽香袭人，但面对着“情疏迹远只香留”的桂花，她也不能不掩饰羞愧之容。于是，正值中秋八月开放的桂花便理所当然地成为花中之冠了。\n\n　　“骚人可煞无情思，何事当年不见收。”“骚人”指的是屈原。屈原的《离骚》上多载草木名称，独独不见桂花。宋代的陈与义在《清平乐·咏桂》中说：“楚人未识孤妍，《离骚》遗恨千年。”意思和此词大体上是一致的，皆以屈原的不收桂花入《离骚》为憾事，以为这是屈原情思不足的缘故。\n\n　　就全篇来说，这首词的笔法是很巧妙的。全词自始至终都象是为桂花鸣不平，实际上是在抒发自己的幽怨之情。\n\n　　词中正面描写桂花的，只有开头两句。仅此两句便把桂花的颜色、光泽、性格、韵味都写尽了，为后面替桂花“鸣冤”、“正名”做好了铺垫。\n\n　　作者之所以推崇桂花为第一流的花朵，是因为她十分注重桂花的内在美，十分欣赏桂花的色淡味香，体性温雅。所谓“何须浅碧深红色”，言外之意是，只要味香性柔，无须浅碧深红；如果徒有“浅碧深红”便不能列为花中第一流。为了推崇桂花，作者甚至让梅花生妒，使菊花含羞。其实，作者的咏梅、咏菊之作是不少的，这两种花，论颜色，论风韵，确实不在桂花之下，她们的“妒”和“羞”恐怕还是因为她们没有桂花那样浓郁的芳香吧？最后，作者更直接谈及咏桂与情思的关系，她以非凡的艺术家的胆量和勇气指责屈原的当年不收桂花入《离骚》是“情思”不够的缘故。至此，作者既为桂花“正”了“名”，又抒发了自己的一怀幽情。实际上，那“暗淡轻黄体性柔，情疏迹远只香留”的桂花，正是作者傲视尘俗，乱世挺拔的正直性格的写照。', poem_tags = '宋词精选,咏物,写花,抒怀,猖狂' WHERE poem_title = '鹧鸪天·桂花' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '当年首次相逢你酥手捧杯殷勤劝酒频举玉盅，是那么地温柔美丽和多情，我开怀畅饮喝得酒醉脸通红。翩翩起舞从月上柳梢的傍晚时分开始，直到楼顶月坠楼外树梢的深夜，我们尽情地跳舞歌唱，筋疲力尽累到无力再把桃花扇摇动。\n自从那次离别后，我总是怀念那美好的相逢，多少回梦里与你相拥。今夜里我举起银灯把你细看，还怕这次相逢又是在梦中。', poem_notes = '鹧鸪天：词牌名，又名“思佳客”，五十五字。 此词黄升《花庵词选》题作《佳会》。\n彩袖：代指穿彩衣的歌女。\n玉钟：古时指珍贵的酒杯，是对酒杯的美称。\n拚（pàn）却：甘愿，不顾惜。却：语气助词。\n“舞低”二句：歌女舞姿曼妙，直舞到挂在杨柳树梢照到楼心的一轮明月低沉下去；歌女清歌婉转，直唱到扇底儿风消歇（累了停下来），极言歌舞时间之久。桃花扇，歌舞时用作道具的扇子，绘有桃花。歌扇风尽，形容不停地挥舞歌扇。这两句是《小山词》中的名句。“低”字为使动用法，使······低。\n同：聚在一起。.\n剩把：剩：通“尽（jǐn）”，只管。把：持，握。\n银釭（gāng）：银质的灯台，代指灯。', poem_tags = '宋词三百首,爱情,婉约' WHERE poem_title = '鹧鸪天·彩袖殷勤捧玉钟' AND poem_author = '晏几道';
UPDATE edu_poem SET poem_translation = '夸父与太阳赛跑，一直追赶到太阳落下的地方；他感到口渴，想要喝水，就到黄河、渭水喝水。黄河、渭水的水不够，往北去大湖喝水。还没到大湖，在半路因口渴而死。丢弃他的手杖，（手杖）化成桃林。', poem_notes = '1、逐走：竞跑，赛跑。\n2、逐：竞争。走：跑。\n3、入日：追赶到太阳落下的地方。\n4、欲得饮：想要喝水解渴。\n5、河、渭：即黄河，渭水。\n6、北饮大泽：大湖。传说纵横千里，在雁门山北。北：方位名词用作状语，向北方，向北面。\n7、道渴而死：半路上因口渴而死。\n8、邓林：地名，今在大别山附近河南、湖北、安徽三省交界处。邓林即“桃林”。\n9、未至：没有赶到。\n10、渴：感到口渴。\n11、弃：遗弃。\n12、为：成为。\n13、逐日：追逐太阳。\n14、于：到。（饮于河、渭中的于，应译为到，介词）\n15、大泽：大湖。\n16、足：够。（因为足的意思等同于够，所以 足够：同义复合词）\n\n词语活用 \n北饮大泽\n北：名词作状语，向北。\n道渴而死\n道：名词作状语，在半路上。\n\n古今异义\n①夸父与日逐走\n走：古义：跑。今义：行走。\n②饮于河渭\n河：古义：指黄河。 今义：泛指所有河流。\n\n一词多义\n饮：\n①欲得饮 饮：名词，饮食，食物和水。\n②饮于河、渭饮： 动词，喝。', poem_tags = '初中文言文,神话,故事' WHERE poem_title = '夸父逐日' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '夜静月黑雁群飞得很高，单于趁黑夜悄悄地逃窜。\n正要带领轻骑兵去追赶，大雪纷飞落满了身上的弓刀。', poem_notes = '塞下曲：古时边塞的一种军歌。\n月黑：没有月光。\n单于（chán yú ）：匈奴的首领。这里指入侵者的最高统帅。\n遁：逃走。\n将：率领。\n轻骑：轻装快速的骑兵。\n逐：追赶。\n满：沾满。', poem_appreciation = '这首诗只有短短20个字，却饱含了大量的信息，激发读者产生无穷的想象。作者并没有直接描写战斗的场面，但通过读诗，完全可以通过领悟诗意和丰富想象，绘出一幅金戈铁马的战争画图来。\n\n　　诗由写景开始：“月黑雁飞高”。这样的景是难于刻画的：“月黑”，则茫无所见；“雁飞高”，则无迹可寻。雁飞而且高。是由声音觉察到的。这样的景，并非眼中之景，而是意中之景。雪夜月黑，本不是雁飞的正常时刻。而宿雁惊飞，正透露出敌人正在行动。寥寥五字，既交待了时间，又烘托了战斗前的紧张气氛，直接逼出下句“单于夜遁逃”来。单于本是古匈奴的君主，这里借指敌军统帅。敌军在夜间行动，应当有各种可能。然而诗人但谓“单于夜遁逃”。读诗至此，顿觉一股豪迈之情扑面而来。敌人夜间行动，并非率兵来袭，而是借夜色的掩护仓惶逃遁。诗句语气肯定，判断明确，充满了对敌人的蔑视和我军必胜的信念，足令读者为之振奋，于上句造成的神秘气氛中，发一惊采。敌酋遁去，我军纵兵追擒，这是自然的发展。“欲将轻骑逐”，是追兵将发而未发。不用大军而仅派“轻骑”，绝不仅仅因为快捷，同时也还显示厂一种高度的自信。仿佛敌人已是瓮中之鳖，只须少量“轻骑”追剿。便可手到擒来。当勇士们列队准备出发时。虽然站立不过片刻．而大雪竟落满弓刀。“大雪满弓刀”一句，又发惊采，将全诗意境推向高潮。在茫茫的夜色中，在洁白的雪地上，一支轻骑兵正在集结，雪花顷刻便落满了他们全身，遮掩了他们武器的寒光。他们就象一支支即将离弦的箭。虽然尚未出发，却早就满怀着必胜的信心。这是一幅非常动人的画图：在静谴中蕴藏着呐喊，在昏暗中酝酿着闪电。虽然是在漆黑的夜间，勇士们被白雪勾画出的英姿仍然是“焕尔触目”。“离首即尾、离尾即首”虽然是绝句的难点，但诗人倘能大胆剪裁，巧妙构思，抓住典型环境与典型场景，完全能够写出精采的佳作。', poem_tags = '唐诗三百首,边塞,冬天,战争,赞美,将军' WHERE poem_title = '和张仆射塞下曲·其三' AND poem_author = '卢纶';
UPDATE edu_poem SET poem_translation = '明灯错落，园林深处映射出璀璨的光芒，有如娇艳的花朵一般；由于四处都可通行，所以城门的铁锁也打开了。\n人潮汹涌，马蹄下尘土飞扬；月光洒遍每个角落，人们在何处都能看到明月当头。\n月光灯影下的歌妓们花枝招展、浓妆艳抹，一面走，一面高唱《梅花落》。\n京城取消了夜禁，计时的玉漏你也不要着忙，莫让这一年只有一次的元宵之夜匆匆过去。', poem_notes = '火树银花：比喻灿烂绚丽的灯光和焰火。特指上元节的灯景。此句对后世影响甚大，如宋辛弃疾《青玉案·元夕》词有：“东风夜放花千树……蓦然回首，那人却在灯火阑珊处。”《红楼梦》十八回：“只见庭燎绕空，香雪布地，火树琪花，金窗玉槛”\n星桥：星津桥，天津三桥之一，“洛水贯都，以像星汉”此处或以星津桥指代天津三桥。”东都洛阳，洛水从西面流经上阳宫南，流到皇城端门外，分为三道，上各架桥，南为星津桥，中为天津桥，北为黄道桥 。开元年间，改修天津桥，星津桥毁，二桥合而为一。 \n 铁锁开：比喻京城开禁。唐朝都城都有宵禁，但在正月十五这天取消宵禁，连接洛水南岸的里坊区与洛北禁苑的天津桥、星津桥、黄道桥上的铁锁打开，任平民百姓通行。\n暗尘：暗中飞扬的尘土。\n逐人来：追随人流而来。\n游伎：歌女、舞女。一作“游骑（jì）”\n秾李：此处指观灯歌伎打扮得艳若桃李。《诗经·召南·何彼秾矣》：“何彼秾矣，华如桃李。”\n落梅：曲调名。\n金吾：原指仪仗队或武器，此处指金吾卫，掌管京城戒备，禁人夜行的官名，汉代置。《唐两京新记》云：”正月十五日夜，敕金吾弛禁，前后各一日以看灯，光若昼日。”\n不禁夜：指取消宵禁。唐时，京城每天晚上都要戒严，对私自夜行者处以重罚。一年只有三天例外，即正月十四、十五、十六。\n玉漏：古代用玉做的计时器皿，即滴漏。', poem_appreciation = '这首诗是描写长安城里元宵之夜的景色。据《大唐新语》和《唐两京新记》记载：每年这天晚上，长安城里都要大放花灯；前后三天，夜间照例不戒严，看灯的真是人山人海。豪门贵族的车马喧阗，市民们的歌声笑语，汇成一片，通宵都在热闹的气氛中度过。\n\n　　春天刚刚才透露一点消息，还不是万紫千红的世界，可是明灯错落，在大路两旁、园林深处映射出灿烂的辉光，简直象明艳的花朵一样。从“火树银花”的形容，我们不难想象，这是多么奇丽的夜景！说“火树银花合”，因为四望如一的缘故。王维《终南山》“白云回望合”，孟浩然《过故人庄》“绿树村边合”的“合”，用意相同，措语之妙，可能是从这里得到启发的。由于到处任人通行，所以城门也开了铁锁。崔液《上元夜》诗有句云：“玉漏铜壶且莫催，铁关金锁彻明开。”可与此相印证。城关外面是城河，这里的桥，即指城河上的桥。这桥平日是黑沈沈的，今天换上了节日的新装，点缀着无数的明灯。灯影照耀，城河望去有如天上的星河，所以也就把桥说成“星桥”了。“火树”“银花”“星桥”都写灯光，诗人的鸟瞰，首先从这儿着笔，总摄全篇；同时，在“星桥铁锁开”这句话里说出游人之盛，这样，下面就很自然地过渡到节日风光的具体描绘。\n\n　　人潮一阵阵地涌着，马蹄下飞扬的尘土也看不清；月光照到人们活动的每一个角落，哪儿都能看到明月当头。原来这灯火辉煌的佳节，正是风清月白的良宵。在灯影月光的映照下，花枝招展的歌妓们打扮得分外美丽，她们一面走，一面唱着《梅花落》的曲调。长安城里的元宵，真是观赏不尽的。所谓“欢娱苦日短”，不知不觉便到了深更时分，然而人们却仍然怀着无限留恋的心情，希望这一年一度的元宵之夜不要匆匆地过去。“金吾不禁”二句，用一种带有普遍性的心理描绘，来结束全篇，言尽而意不尽，读之使人有余音绕梁，三日不绝之感。这诗于镂金错采之中，显得韵致流溢，也在于此。', poem_tags = '节日,元宵节' WHERE poem_title = '正月十五夜' AND poem_author = '苏味道';
UPDATE edu_poem SET poem_translation = '五月五日是端午节，你赠与我了一枝艾草。死者却看不见，新结交的知己却在万里之外。\n往日能够为国尽忠的人，现在已经白发苍苍。我想要从屈原那里得到希望，三湘相隔的比较远。', poem_notes = '即事：就眼前之事歌咏。\n故人：古人，死者。\n新知：新结交的知己。\n丹心：指赤红炽热的心，一般以“碧血丹心”来形容为国尽忠的人。\n夙昔：指昔时，往日。\n灵均：形容土地美好而平坦，含有“屈”字的意思。在这里指屈原。\n三湘：指沅湘、潇湘、资湘（或蒸湘），合称“三湘”。也可以指湖南一带。\n隔：间隔，距离。\n辽海：泛指辽河流域以东至海地区。', poem_tags = '端午节,无奈,壮志' WHERE poem_title = '端午即事' AND poem_author = '文天祥';
UPDATE edu_poem SET poem_translation = '炉火照彻天地，紫烟中红星乱闪。\n炼铜工人在明月之夜，一边唱歌一边劳动，他们的歌声响彻了寒峭的山谷。', poem_notes = '秋浦：县名，唐时先属宣州，后属池州，在今安徽省贵池县西。秋浦因流经县城之西的秋浦河得名。\n炉火：唐代，秋浦乃产铜之地。此指炼铜之炉火\n赧郎：红脸汉。此指炼铜工人。赧：原指因羞愧而脸红，此指脸被炉火所映红。', poem_tags = '秋夜,赞美,工人,劳动,早教古诗100首' WHERE poem_title = '秋浦歌十七首·其十四' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '平沙万里，在月光下像铺上一层白皑皑的霜雪。连绵的燕山山岭上，一弯明月当空，如弯钩一般。\n何时才能受到皇帝赏识，给我这匹骏马佩戴上黄金打造的辔头，让我在秋天的战场上驰骋，立下功劳呢？', poem_notes = '燕山：山名，在现河北省的北部。\n钩：弯刀，是古代的一种兵器，形似月牙。\n金络脑：用黄金装饰的马笼头，说明马具的华贵。', poem_appreciation = '一、二句展现出一片富于特色的边疆战场景色，乍看是运用赋法：连绵的燕山山岭上，一弯明月当空；平沙万里，在月光下象铺上一层白皑皑的霜雪。这幅战场景色，一般人也许只觉悲凉肃杀，但对于志在报国之士却有异乎寻常的吸引力。“燕山月似钩”与“晓月当帘挂玉弓”（《南园》其六）匠心正同，“钩”是一种弯刀，与“玉弓”均属武器，从明晃晃的月牙联想到武器的形象，也就含有思战斗之意。作者所处的贞元、元和之际，正是藩镇极为跋扈的时代，而“燕山”暗示的幽州蓟门一带又是藩镇肆虐为时最久、为祸最烈的地带，所以诗意是颇有现实感慨的。思战之意也有针对性。平沙如雪的疆场寒气凛凛，但它是英雄用武之地。所以这两句写景实启后两句的抒情，又具兴义。\n\n　　三、四句借马以抒情：什么时候才能披上威武的鞍具，在秋高气爽的疆场上驰骋，建树功勋呢？《马诗》其一云：“龙背铁连钱，银蹄白踏烟。无人织锦襜，谁为铸金鞭？”“无人织锦襜”二句的慨叹与“何当金络脑”表达的是同一个意思，就是企盼把良马当作良马对待，以效大用。“金络脑”、“锦襜”、“金鞭”统属贵重鞍具，都是象征马受重用。显然，这是作者热望建功立业而又不被赏识所发出的嘶鸣。\n\n　　此诗与《南园（男儿何不带吴钩）》都是写同一种投笔从戎、削平藩镇、为国建功的热切愿望。但《南园》是直抒胸臆，此诗则属寓言体或比体。直抒胸臆，较为痛快淋漓；而用比体，则觉婉曲耐味。而诗的一、二句中，以雪喻沙，以钩喻月，也是比；从一个富有特征性的景色写起以引出抒情，又是兴。短短二十字中，比中见兴，兴中有比，大大丰富了诗的表现力。从句法上看，后二句一气呵成，以“何当”领起作设问，强烈传出无限企盼意，且有唱叹味；而“踏清秋”三字，声调铿锵，词语搭配新奇，盖“清秋”草黄马肥，正好驰驱，冠以“快走”二字，形象暗示出骏马轻捷矫健的风姿，恰是“所向无空阔，真堪托死生。骁腾有如此，万里可横行”（杜甫《房兵曹胡马》）。所以字句的锻炼，也是此诗艺术表现上不可忽略的成功因素。', poem_tags = '边塞,写景,咏物,写马,战争,早教古诗100首' WHERE poem_title = '马诗二十三首·其五' AND poem_author = '李贺';
UPDATE edu_poem SET poem_translation = '春风中一株株杨柳树，沿着御河两岸呈现出一片绿色。\n最近攀折起来不是那么方便，应该是因为离别人儿太多。', poem_notes = '东门：即长安青门，唐朝时出京城多东行者，多用于送别。有的版本作东风。\n青青：指杨柳的颜色。\n御河：指京城护城河。\n攀折：古代折柳送别的习俗。\n苦：辛苦，这里指折柳不方便。\n别离：离别，分别。', poem_tags = '离别,送别,柳树' WHERE poem_title = '送别' AND poem_author = '王之涣';
UPDATE edu_poem SET poem_translation = '信步东城感到春光越来越好，皱纱般的水波上船儿慢摇。条条绿柳在霞光晨雾中轻摆曼舞，粉红的杏花开满枝头春意妖娆。\n总是抱怨人生短暂欢娱太少，怎肯为吝惜千金而轻视欢笑？让我为你举起酒杯奉劝斜阳，请留下来把晚花照耀。', poem_notes = '木兰花：原唐教坊曲名，后用为词牌名，调同“玉楼春”。\n縠（hú）皱波纹：形容波纹细如皱纱。縠皱：即皱纱，有皱褶的纱。棹（zhào）：船桨，此指船。\n春意：春天的气象。闹：浓盛。\n浮生：指飘浮无定的短暂人生。\n肯爱：岂肯吝惜，即不吝惜。一笑：特指美人之笑。\n持酒：端起酒杯。\n晚照：夕阳的余晖。', poem_appreciation = '此词上片从游湖写起，讴歌春色，描绘出一幅生机勃勃、色彩鲜明的早春图；下片则一反上片的明艳色彩、健朗意境，言人生如梦，虚无缥缈，匆匆即逝，因而应及时行乐，反映出“浮生若梦，为欢几何”的寻欢作乐思想。作者宋祁因词中“红杏枝头春意闹”一句而名扬词坛，被世人称作红杏尚书。\n\n　　起首一句泛写春光明媚。第二句以拟人化手法，将水波写得生动、亲切而又富于灵性。“绿杨”句写远处杨柳如烟，一片嫩绿，虽是清晨，寒气却很轻微。“红杏”句专写杏花，以杏花的盛开衬托春意之浓。词人以拟人手法，着一“闹”字，将烂漫的大好春光描绘得活灵活现，呼之欲出。\n\n　　过片两句，意谓浮生若梦，苦多乐少，不能吝惜金钱而轻易放弃这欢乐的瞬间。此处化用“一笑倾人城”的典故，抒写词人携妓游春时的心绪。结拍两句，写词人为使这次春游得以尽兴，要为同时冶游的朋友举杯挽留夕阳，请它在花丛间多陪伴些时候。这里，词人对于美好春光的留恋之情，溢于言表，跃然纸上。\n\n　　这首词章法井然，开阖自如，言情虽缠绵而不轻薄，措词虽华美而不浮艳，将执著人生、惜时自贵、流连春光的情怀抒写得淋漓尽致，具有不朽的艺术价值。\n\n　　本词歌咏春天，洋溢着珍惜青春和热爱生活的情感。上阙写初春的风景。起句“东城渐觉风光好”，以叙述的语气缓缓写来，表面上似不经意，但“好”字已压抑不住对春天的赞美之情。\n\n　　以下三句就是“风光好”的具体发挥与形象写照。首先是“縠皱波纹迎客棹”，把人们的注意力引向盈盈春水，那一条条漾动着水的波纹，仿佛是在向客人招手表示欢迎。然后又要人们随着他去观赏“绿杨”，“绿杨”句点出“客棹”来临的时光与特色。“晓寒轻”写的是春意，也是作者心头的情意。“波纹”、“绿杨”都象征着春天。但是，更能象征春天的却是春花，在此前提下，上片最后一句终于咏出了“红杏枝头春意闹”这一绝唱。如果说这一句是画面上的点睛之笔，还不如说是词人心中绽开的感情花朵。“闹”字不仅形容出红杏的众多和纷繁，而且，它把生机勃勃的大好春光全都点染出来了。“闹”字不仅有色，而且似乎有声，王国维在《人间词话》中说：“着一‘闹’字而境界全出。”\n\n　　下阙再从词人主观情感上对春光美好做进一步的烘托。“浮生长恨欢娱少，肯爱千金轻一笑”二句，是从功名利禄这两个方面来衬托春天的可爱与可贵。词人身居要职，官务缠身，很少有时间或机会从春天里寻取人生的乐趣，故引以为“浮生”之“长恨”。于是，就有了宁弃“千金”而不愿放过从春光中获取短暂“一笑”的感慨。既然春天如此可贵可爱，词人禁不住“为君持酒劝斜阳”，明确提出“且向花间留晚照”的强烈主观要求。这要求是“无理”的，因此也是不可能的，却能够充分地表现出词人对春天的珍视，对光阴的爱惜。', poem_tags = '宋词三百首,宋词精选,婉约,春游,写景,惜春' WHERE poem_title = '玉楼春·春景' AND poem_author = '宋祁';
UPDATE edu_poem SET poem_translation = '在烽火台的西边高高地耸着一座戍楼，黄昏时分，独坐在戍楼上任凭从湖面吹来的秋风撩起自己的战袍。此时又传来一阵幽怨的羌笛声，吹奏的是《关山月》的调子，无奈着笛声更增添了对万里之外的妻子的相思之情。\n\n　　军中起舞，伴奏的琵琶翻出新声，不管怎样翻新，每每听到《关山月》的曲调时，总会激起边关将士久别怀乡的忧伤之情。纷杂的乐舞与思乡的愁绪交织在一起，欲理还乱，无尽无休。此时秋天的月亮高高地照着长城。\n\n　　边城榆树的叶子早已稀疏飘落，颜色发黄了，傍晚时分，一场战斗刚刚结束，环视战场，只见暮云低合，荒丘起伏。将军向皇帝上表，奏请班师，以便能把战死沙场的将士们的尸骨运回故土安葬，不能让士兵们为他乡埋葬自己的战友而伤感痛哭。\n\n　　青海湖上蒸腾而起的漫漫云雾，遮暗了整个祁连山，远远地可以望见玉门关那座孤城。黄沙万里，频繁的战斗磨穿了战士们身上的铠甲，不将敌人打败绝不回还。\n\n　　塞北沙漠中大风狂起，尘土飞扬，天色为之昏暗，前线军情十分紧急，接到战报后迅速出击。先头部队已经于昨天夜间在洮河的北岸和敌人展开了激战，刚刚听说与敌人交火，现在就传来了已获得大捷的消息。\n\n　　将军臂膊上绑缚着胡瓶，骑着紫薄汗马，英姿飒爽；碎叶城西的天空中一轮秋月高高悬挂。边境传来紧急军情，皇上派使者星夜传诏将军，并赐予尚方宝剑令其即刻领兵奔赴前线杀敌；将军拜诏辞京，奔赴战场，将士用命，一鼓作气，很快就攻破了敌人的老巢。\n\n　　玉门关周围山峦层层叠叠，像重重屏障护卫着王朝的西北边防；烽火台遍布各个山头。人们戍边要依靠烽火来传递消息；那里山深林密，马儿跑过一会儿就看不见踪影了。', poem_notes = '从军行：乐府旧题，属相和歌辞平调曲。多是反映军旅辛苦生活的。\n羌笛：羌族竹制乐器。关山月，乐府曲名，属横吹曲。多为伤离别之辞。\n独上：一作“独坐”。\n无那：无奈，指无法消除思亲之愁。一作“谁解”。\n新声：新的歌曲。\n关山：边塞。旧别：一作“离别”。\n撩乱：心里烦乱。边愁：久住边疆的愁苦。听不尽：一作“弹不尽”。\n关城：指边关的守城。\n云沙：像云一样的风沙。\n表：上表，上书。掩尘骨：指尸骨安葬。掩，埋。\n龙荒：荒原。\n青海：指青海湖，在今青海省。\n玉门关：汉置边关名，在今甘肃敦煌县西。一作“雁门关”。\n楼兰：汉西域国名，在今新疆蜡羌县及罗布泊一带，此地代指唐西边境少数民族政权。终不还：一作“竟不还”。\n辕门：指军营的大门。\n吐谷浑：中国古代少数民族名称，晋时鲜卑慕容氏的后裔。\n胡瓶：唐代西域地区制作的一种工艺品，可用来储水。\n敕：专指皇帝的诏书。星驰：像流星一样迅疾奔驰，也可解释为星夜奔驰。\n嶂：指直立像屏障一样的山峰。\n烽：指烽火台。', poem_appreciation = '组诗《从军行七首》是王昌龄采用乐府旧题写的边塞诗，载于《全唐诗》卷一百四十三。\n\n　　【其一】\n\n　　这首小诗，笔法简洁而富蕴意，写法上很有特色。诗人巧妙地处理了叙事与抒情的关系。前三句叙事，描写环境，采用了层层深入、反复渲染的手法，创造气氛，为第四句抒情做铺垫，突出了抒情句的地位，使抒情句显得格外警拔有力。“烽火城西”，一下子就点明了这是在青海烽火城西的瞭望台上。荒寂的原野，四顾苍茫，只有这座百尺高楼，这种环境很容易引起人的寂寞之感。时令正值秋季，凉气侵人，正是游子思亲、思妇念远的季节。时间又逢黄昏，“鸡栖于埘，日之夕矣，羊牛下来。君子于役，如之何勿思！”（《诗经·王风·君子于役》）这样的时间常常触发人们思念于役在外的亲人。而此时此刻，久戍不归的征人恰恰“独坐”在孤零零的戍楼上。天地悠悠，牢落无偶，思亲之情正随着青海湖方向吹来的阵阵秋风任意翻腾。上面所描写的，都是通过视觉所看到的环境，没有声音，还缺乏立体感。接着诗人写道：“更吹羌笛关山月”。在寂寥的环境中，传来了阵阵呜呜咽咽的笛声，就象亲人在呼唤，又象是游子的叹息。这缕缕笛声，恰似一根导火线，使边塞征人积郁在心中的思亲感情，再也控制不住，终于来了个大爆发，引出了诗的最后一句。这一缕笛声，对于“独坐”在孤楼之上的闻笛人来说是景，但这景又饱含着吹笛人所抒发的情，使环境更具体、内容更丰富了。诗人用这亦情亦景的句子，不露痕迹，完成了由景入情的转折过渡，何等巧妙、何等自然！\n\n　　在表现征人思想活动方面，诗人运笔也十分委婉曲折。环境氛围已经造成，为抒情铺平垫稳，然后水到渠成，直接描写边人的心理——“无那金闺万里愁”。作者所要表现的是征人思念亲人、怀恋乡土的感情，但不直接写，偏从深闺妻子的万里愁怀反映出来。而实际情形也是如此：妻子无法消除的思念，正是征人思归又不得归的结果。这一曲笔，把征人和思妇的感情完全交融在一起了。就全篇而言，这一句如画龙点睛，立刻使全诗神韵飞腾，而更具动人的力量了。\n\n　　【其二】\n\n　　此诗截取了边塞军旅生活的一个片断，通过写军中宴乐表现征戍者深沉、复杂的感情。\n\n　　“琵琶起舞换新声”。随舞蹈的变换，琵琶又翻出新的曲调，诗境就在一片乐声中展开。琵琶是富于边地风味的乐器，而军中置酒作乐，常常少不了“胡琴琵琶与羌笛。”这些器乐，对征戍者来说，带着异或情调，容易唤起强烈感触。既然是“换新声”，总能给人以一些新的情趣、新的感受吧？不，“总是关山旧别情”。边地音乐主要内容，可以一言以蔽之，“旧别情”而已。因为艺术反映实际生活，征戍者谁个不是离乡背井乃至别妇抛雏？“别情”实在是最普遍、最深厚的感情和创作素材。所以，琵琶尽可换新曲调，却换不了歌词包含的情感内容。《乐府古题要解》云：“《关山月》，伤离也。”句中“关山”在字面的意义外，双关《关山月》曲调，含意更深。\n\n　　此句的“旧”对应上句的“新”，成为诗意的一次波折，造成抗坠扬抑的音情，特别是以“总是”作有力转接，效果尤显。次句既然强调别情之“旧”，那么，这乐曲是否太乏味呢？不，“撩乱边愁听不尽”，那曲调无论什么时候，总能扰得人心烦乱不宁。所以那奏不完、“听不尽”的曲调，实叫人又怕听，又爱听，永远动情。这是诗中又一次波折，又一次音情的抑扬。“听不尽”三字，是怨？是叹？是赞？意味深长。作“奏不完”解，自然是偏于怨叹。然作“听不够”讲，则又含有赞美了。所以这句提到的“边愁”既是久戍思归的苦情，又未尝没有更多的意味。当时北方边患未除，尚不能尽息甲兵，言念及此，征戍者也会心不宁意不平的。前人多只看到它“意调酸楚”的一面，未必十分全面。\n\n　　诗前三句均就乐声抒情，说到“边愁”用了“听不尽”三字，那末结句如何以有限的七字尽此“不尽”就最见功力。诗人这里轻轻宕开一笔，以景结情。仿佛在军中置酒饮乐的场面之后，忽然出现一个月照长城的莽莽苍苍的景象：古老雄伟的长城绵亘起伏，秋月高照，景象壮阔而悲凉。对此，你会生出什么感想？是无限的乡愁？是立功边塞的雄心和对于现实的忧怨？也许，还应加上对于祖国山川风物的深沉的爱，等等。\n\n　　读者也许会感到，在前三句中的感情细流一波三折地发展（换新声——旧别情——听不尽）后，到此却汇成一汪深沉的湖水，荡漾回旋。“高高秋月照长城”，这里离情入景，使诗情得到升华。正因为情不可尽，诗人“以不尽尽之”，“思入微茫，似脱实粘”，才使人感到那样丰富深刻的思想感情，征戍者的内心世界表达得入木三分。此诗之臻于七绝上乘之境，除了音情曲折外，这绝处生姿的一笔也是不容轻忽的。\n\n　　【其三】\n\n　　这首诗通过描写古战场的荒凉景象，无数的将士们死在边关，而没有办法好好安葬，反映了当时战争的惨烈，也表现了诗人对将士们深切的同情之心。\n\n　　诗的开头点明地点和时令，形象地描绘出边地的荒凉景象，次句暗示有不少战士在这场战斗中为国捐躯。后两句写将军上表请求把战死的将士们尸骨运回安葬，表明了将帅对士卒的爱护之情，\n\n　　此诗以旷远苍茫的荒野战场作为背景，“黄叶”“暮云”等边塞景象更进一步烘托出边塞的荒凉，给人以满目萧然、凄凉悲怆之感。最后两句感情真挚，造句沉痛，更增悲怆之气。全诗读来颇令人感到那种震撼人心的力量，一支部队有这样体恤、爱护士卒的统帅，士卒没有不卖命的道路，由此亦可以想象这支部队战斗力量的强大。\n\n　　【其四】\n\n　　唐代边塞诗的读者，往往因为诗中所涉及的地名古今杂举、空间悬隔而感到困惑。怀疑作者不谙地理，因而不求甚解者有之，曲为之解者亦有之。这首诗就有这种情形。\n\n　　前两句提到三个地名。雪山即河西走廊南面横亘廷伸的祁连山脉。青海与玉门关东西相距数千里，却同在一幅画面上出现，于是对这两句就有种种不同的解说。有的说，上句是向前极目，下句是回望故乡。这很奇怪。青海、雪山在前，玉门关在后，则抒情主人公回望的故乡该是玉门关西的西域，那不是汉兵，倒成胡兵了。另一说，次句即“孤城玉门关遥望”之倒文，而遥望的对象则是“青海长云暗雪山”，这里存在两种误解：一是把“遥望”解为“遥看”，二是把对西北边陲地区的概括描写误解为抒情主人公望中所见，而前一种误解即因后一种误解而生。\n\n　　一、二两句，不妨设想成次第展现的广阔地域的画面：青海湖上空，长云弥温；湖的北面，横亘着绵廷千里的隐隐的雪山；越过雪山，是矗立在河西走廊荒漠中的一座孤城；再往西，就是和孤城遥遥相对的军事要塞——玉门关。这幅集中了东西数千里广阔地域的长卷，就是当时西北边戍边将士生活、战斗的典型环境。它是对整个西北边陲的一个鸟瞰，一个概括。为什么特别提及青海与玉关呢？这跟当时民族之间战争的态势有关。唐代西、北方的强敌，一是吐蕃，一是突厥。河西节度使的任务是隔断吐蕃与突厥的交通，一镇兼顾西方、北方两个强敌，主要是防御吐蕃，守护河西走廊。“青海”地区，正是吐蕃与唐军多次作战的场所；而“玉门关”外，则是突厥的势力范围。所以这两句不仅描绘了整个西北边陲的景象，而且点出了“孤城”西拒吐蕃，北防突厥的极其重要的地理形势。这两个方向的强敌，正是戍守“孤城”的将士心之所系，宜乎在画面上出现青海与玉关。与其说，这是将士望中所见，不如说这是将士脑海中浮现出来的画面。这两句在写景的同时渗透丰富复杂的感情：戍边将士对边防形势的关注，对自己所担负的任务的自豪感、责任感，以及戍边生活的孤寂、艰苦之感，都融合在悲壮、开阔而又迷蒙暗淡的景色里。\n\n　　三、四两句由情景交融的环境描写转为直接抒情。“黄沙百战穿金甲”，是概括力极强的诗句。戍边时间之漫长，战事之频繁，战斗之艰苦，敌军之强悍，边地之荒凉，都于此七字中概括无遗。“百战”是比较抽象的，冠以“黄沙”二字，就突出了西北战场的特征，令人宛见“日暮云沙古战场”的景象；“百战”而至“穿金甲”，更可想见战斗之艰苦激烈，也可想见这漫长的时间中有一系列“白骨掩蓬蒿”式的壮烈牺牲。但是，金甲尽管磨穿，将士的报国壮志却并没有销磨，而是在大漠风沙的磨炼中变得更加坚定。“不破楼兰终不还”，就是身经百战的将士豪壮的誓言。上一句把战斗之艰苦，战事之频繁越写得突出，这一句便越显得铿锵有力，掷地有声。一二两句，境界阔大，感情悲壮，含蕴丰富；三四两句之间，显然有转折，二句形成鲜明对照。“黄沙”句尽管写出了战争的艰苦，但整个形象给人的实际感受是雄壮有力，而不是低沉伤感的。因此末句并非嗟叹归家无日，而是在深深意识到战争的艰苦、长期的基础上所发出的更坚定、深沉的誓言，盛唐优秀边塞诗的一个重要的思想特色，就是在抒写戍边将士的豪情壮志的同时，并不回避战争的艰苦，本篇就是一个显例。可以说，三四两句这种不是空洞肤浅的抒情，正需要有一二两句那种含蕴丰富的大处落墨的环境描写。典型环境与人物感情高度统一，是王昌龄绝句的一个突出优点，这在本篇中也有明显的体现。\n\n　　【其五】\n\n　　读过《三国演义》的人，可能对第五回“关云长温酒斩华雄”有深刻印象。这对塑造关羽英雄形象是很精彩的一节。但书中并没有正面描写单刀匹马的关羽与领兵五万的华雄如何正面交手，而是用了这样一段文字：（关羽）出帐提刀，飞身上马。众诸侯听得关外鼓声大振，喊声大举，如天摧地塌，岳撼山崩，众皆失惊。正欲探听，鸾铃响处，马到中军，云长提华雄之头，掷于地上，其酒尚温。\n\n　　这段文字，笔墨非常简炼，从当时的气氛和诸侯的反应中，写出了关羽的神威。论其客观艺术效果，比写挥刀大战数十回合，更加引人入胜。罗贯中的这段文字，当然有他匠心独运之处，但如果就避开正面铺叙，通过气氛渲染和侧面描写，去让人想象战争场面这一点来看，却不是他的首创，像王昌龄的这首《从军行》，应该说已早著先鞭，并且是以诗歌形式取得成功的。\n\n　　“大漠风尘日色昏”，由于我国西北部的阿尔泰山、天山、昆仑山均呈自西向东或向东南走向，在河西走廊和青海东部形成一个大喇叭口，风力极大，狂风起时，飞沙走石。因此，“日色昏”接在“大漠风尘”后面，并不是指天色已晚，而是指风沙遮天蔽日。但这不光表现气候的暴烈，它作为一种背景出现，还自然对军事形势起着烘托、暗示的作用。在这种情势下，唐军采取什么行动呢？不是辕门紧闭，被动防守，而是主动出征。为了减少风的强大阻力，加快行军速度，战士们半卷着红旗，向前挺进。这两句于“大漠风尘”之中，渲染红旗指引的一支劲旅，好像不是自然界在逞威，而是这支军队卷尘挟风，如一柄利剑，直指敌营。这就把读者的心弦扣得紧紧的，让人感到一场恶战已迫在眉睫。这支横行大漠的健儿，将要演出怎样一种惊心动魄的场面呢？在这种悬想之下，再读后两句：“前军夜战洮河北，已报生擒吐谷浑。”这可以说是一落一起。读者的悬想是紧跟着刚才那支军队展开的，可是在沙场上大显身手的机会却并没有轮到他们。就在中途，捷报传来，前锋部队已在夜战中大获全胜，连敌酋也被生擒。情节发展得既快又不免有点出人意料，但却完全合乎情理，因为前两句所写的那种大军出征时迅猛、凌厉的声势，已经充分暗示了唐军的士气和威力。这支强大剽悍的增援部队，既衬托出前锋的胜利并非偶然，又能见出唐军兵力绰绰有余，胜券在握。\n\n　　从描写看，诗人所选取的对象是未和敌军直接交手的后续部队，而对战果辉煌的“前军夜战”只从侧面带出。这是打破常套的构思。如果改成从正面对夜战进行铺叙，就不免会显得平板，并且在短小的绝句中无法完成。现在避开对战争过程的正面描写，从侧面进行烘托，就把绝句的短处变成了长处。它让读者从“大漠风尘日色昏”和“夜战洮河北”去想象前锋的仗打得多么艰苦，多么出色。从“已报生擒吐谷浑”去体味这次出征多么富有戏剧性。一场激战，不是写得声嘶力竭，而是出以轻快跳脱之笔，通过侧面的烘托、点染，让读者去体味、遐想。这一切，在短短的四句诗里表现出来，在构思和驱遣语言上的难度，应该说是超过“温酒斩华雄”那样一类小说故事的。\n\n　　【其六】\n\n　　第六首诗描写的是一位将军欲奔赴边关杀敌立功的急切心情。\n\n　　诗的首句写这位将军的战时装束和勇武雄姿，次句转写边塞之景，意在营造和烘托气氛，暗示将军之心时时想着边塞的安危，时时准备奔赴边塞，保境安民。这两句着力铺陈将军的装束和边地景色，既衬托出将军的神武之姿，又意在蓄势，在如水秋月的广阔清寒背景下，一身戎装的将军的剪影，威风凛凛，一位勇武的将军形象就被传神地勾勒了出来。诗的后两句，豪气生发，尤显英雄本色，既写出了部队攻城拔寨的神速，同时也反映出作者对唐朝强大国势和军力的一种自信和自豪心理。\n\n　　【其七】\n\n　　第七首诗主要描写的是山峦叠嶂，烽火遍布的边塞景观。用笔隐曲，语浅意深，余味不尽。\n\n　　诗的前三句写山多、烽火台多，以及边塞将士对烽火的依赖，均属静态描述，突出了唐军在玉门关一带边防设施的完善和布防的到位。至第四句笔锋一转，引入的动态画面，视野之中闯入了一匹马儿，但转瞬又消失在深山密林里。动静结合，形成叙述力度上的张弛美感。而“不见踪”则又将马行之疾，山林之深准确地刻画了出来。虽然已经看不见马了，但仍然能使人产生不尽的联想，让读者隐约地感到边防健儿身手的敏捷。这种结尾，颇为耐人寻味，正如诗人在《诗格》中谈到结尾一句如何处理时所写的那样：“每至落句，常须含蓄，不令语尽思穷。”全诗起笔突兀，收笔婉转，而又似乎绵里藏针，读来颇感意味深长，值得玩味。', poem_tags = '边塞,叙事,抒情,思念,早教古诗100首' WHERE poem_title = '从军行七首' AND poem_author = '王昌龄';
UPDATE edu_poem SET poem_translation = '邦驻军霸上，还没有能和项羽相见，刘邦的左司马曹无伤派人对项羽说：“刘邦想要在关中称王，让子婴（ying）做丞相，珍宝全都被刘邦占有。”项羽大怒，说：“明天犒（kao）劳士兵，给我打败刘邦的军队！”这时候，项羽的军队40万，驻扎在新丰鸿门；刘邦的军队10万，驻在霸上。范增劝告项羽说：“沛公在崤山的东边的时候，对钱财货物贪恋，喜爱美女。现在进了关，不掠取财物，不迷恋女色，这说明他的志向不在小处。我叫人观望他那里的气运，都是龙虎的形状，呈现五彩的颜色，这是天子的气运呀!赶快攻打，不要失去机会。”\n\n　　楚国的左尹项伯，是项羽的叔父，一向同留侯张良交好。张良这时正跟随着刘邦。项伯就连夜骑马跑到刘邦的军营，私下会见张良，把事情详细地告诉了他，想叫张良和他一起离开，说：“不要和（刘邦）他们一起死了。”张良说：“我是韩王派给沛公的人，现在沛公遇到危急的事，逃走是不守信义的，不能不告诉他。”于是张良进去，详细地告诉了刘邦。刘邦大惊，说：“这件事怎么办？”张良说：“是谁给大王出这条计策的？”刘邦说：“一个见识短浅的小子劝我说：‘守住函谷关，不要放诸侯进来，秦国的土地可以全部占领而称王。’所以就听了他的话。”张良说：“估计大王的军队足够用来抵挡项王吗?”刘邦沉默了一会儿，说：“当然不如啊。这又将怎么办呢？”张良说：“请您亲自告诉项伯，说刘邦不敢背叛项王。”刘邦说：“你怎么和项伯有交情？”张良说：“秦朝时，他和我交往，项伯杀了人，我使他活了下来；现在事情危急，幸亏他来告诉我。”刘邦说：“他和你年龄谁大谁小？”张良说：“比我大。”刘邦说：“你替我请他进来，我要像对待兄长一样对待他。”张良出去，邀请项伯。项伯就进去见刘邦。刘邦捧上一杯酒向项伯祝酒，和项伯约定结为儿女亲家，说：“我进入关中，一点东西都不敢据为己有，登记了官吏、百姓，封闭了仓库，等待将军到来。派遣将领把守函谷关的原因，是为了防备其他盗贼进来和意外的变故。我日夜盼望将军到来，怎么敢反叛呢？希望您全部告诉项王我不敢背叛项王的恩德。”项伯答应了，告诉刘邦说：“明天早晨不能不早些亲自来向项王道歉。”刘邦说：“好。”于是项伯又连夜离去，回到军营里，把刘邦的话报告了项羽，趁机说：“沛公不先攻破关中，你怎么敢进关来呢？现在人家有了大功，却要攻打他，这是不讲信义。不如趁此好好对待他。”项王答应了。\n\n　　刘邦第二天早晨带着一百多人马来见项王，到了鸿门，向项王解释说：“我和将军合力攻打秦国，将军在黄河以北作战，我在黄河以南作战，但是我自己没有料到能先进入关中，灭掉秦朝，能够在这里又见到将军。现在有小人的谣言，使您和我发生误会。”项王说：“这是沛公的左司马曹无伤说的，如果不是这样，我怎么会这么生气？”项王当天就留下刘邦，和他饮酒。项王、项伯朝东坐，亚父朝南坐。亚父就是范增。刘邦朝北坐，张良朝西陪侍。范增多次向项王使眼色，再三举起他佩戴的玉玦暗示项王，项王沉默着没有反应。范增起身，出去召来项庄，说：“君王为人心地不狠。你进去上前为他敬酒，敬酒完毕，请求舞剑，趁机把沛公杀死在座位上。否则，你们都将被他俘虏！”项庄就进去敬酒。敬完酒，说：“君王和沛公饮酒，军营里没有什么可以用来作为娱乐的，请让我舞剑。”项王说：“好。”项庄拔剑起舞，项伯也拔剑起舞，常常张开双臂像鸟儿张开翅膀那样用身体掩护刘邦，项庄无法刺杀。\n\n　　于是张良到军营门口找樊哙。樊哙问：“今天的事情怎么样？”张良说：“很危急！现在项庄拔剑起舞，他的意图常在沛公身上啊！”樊哙说：“这太危急了，请让我进去，跟他同生死。”于是樊哙拿着剑，持着盾牌，冲入军门。持戟交叉守卫军门的卫士想阻止他进去，樊哙侧着盾牌撞去，卫士跌倒在地上，樊哙就进去了，掀开帷帐朝西站着，瞪着眼睛看着项王，头发直竖起来，眼角都裂开了。项王握着剑挺起身问：“客人是干什么的？”张良说：“是沛公的参乘樊哙。”项王说：“壮士！赏他一杯酒。”左右就递给他一大杯酒，樊哙拜谢后，起身，站着把酒喝了。项王又说：“赏他一条猪的前腿。”左右就给了他一条未煮熟的猪的前腿。樊哙把他的盾牌扣在地上，把猪腿放（在盾）上，拔出剑来切着吃。项王说：“壮士！还能喝酒吗？”樊哙说：“我死都不怕，一杯酒有什么可推辞的？秦王有虎狼一样的心肠，杀人惟恐不能杀尽，惩罚人惟恐不能用尽酷刑，所以天下人都背叛他。怀王曾和诸将约定：‘先打败秦军进入咸阳的人封作王。’现在沛公先打败秦军进了咸阳，一点儿东西都不敢动用，封闭了宫室，军队退回到霸上，等待大王到来。特意派遣将领把守函谷关的原因，是为了防备其他盗贼的进入和意外的变故。这样劳苦功高，没有得到封侯的赏赐，反而听信小人的谗言，想杀有功的人，这只是灭亡了的秦朝的继续罢了。我以为大王不应该采取这种做法。”项王没有话回答，说：“坐。”樊哙挨着张良坐下。坐了一会儿，刘邦起身上厕所，趁机把樊哙叫了出来。\n\n　　刘邦出去后，项王派都尉陈平去叫刘邦。刘邦说：“现在出来，还没有告辞，这该怎么办？”樊哙说：“做大事不必顾及小节，讲大礼不必计较小的谦让。现在人家正好比是菜刀和砧板，我们则好比是鱼和肉，告辞干什么呢？”于是就决定离去。刘邦就让张良留下来道歉。张良问：“大王来时带了什么东西？”刘邦说：“我带了一对玉璧，想献给项王；一双玉斗，想送给亚父。正碰上他们发怒，不敢奉献。你替我把它们献上吧。”张良说：“好。”这时候，项王的军队驻在鸿门，刘邦的军队驻在霸上，相距四十里。刘邦就留下车辆和随从人马，独自骑马脱身，和樊哙、夏侯婴、靳强、纪信四人拿着剑和盾牌徒步逃跑，从郦山脚下，取道芷阳，抄小路走。刘邦对张良说：“从这条路到我们军营，不过二十里罢了，估计我回到军营里，你才进去。”\n\n　　刘邦离去后，从小路回到军营里。张良进去道歉，说：“刘邦禁受不起酒力，不能当面告辞。让我奉上白璧一双，拜两拜敬献给大王；玉斗一双，拜两拜献给大将军。”项王说：“沛公在哪里？”张良说：“听说大王有意要责备他，脱身独自离开，已经回到军营了。”项王就接受了玉璧，把它放在座位上。亚父接过玉斗，放在地上，拔出剑来敲碎了它，说：“唉！这小子不值得和他共谋大事！夺项王天下的人一定是刘邦。我们都要被他俘虏了！”\n\n　　刘邦回到军中，立刻杀掉了曹无伤。 ▲', poem_appreciation = '《鸿门宴》一文，既为我们再现了历史真实；它也为我们提供了高度的文学技巧典范。它的艺术特点，可以分为以下四点来观察。\n\n　　第一点，它善于在矛盾开展中描绘人物。通过重要历史事件的描写以突现人，使之为形象塑造服务。人物形象获得高度的鲜明与统一，因之具备典型性。\n\n　　在本文中，作者善善、恶恶、贤贤、黜不肖的态度是十分鲜明的。司马迁以极其深微而又明显的爱憎笔触，刻画了两种不同类型的统治人物。刘邦是一个卑鄙狡诈而又极其机变的所谓成功人物；项羽则是一个粗豪自恃、浅听轻信的所谓失败英雄。作者把刘邦、项羽放在鸿门一会的具体历史事件具体矛盾开展当中，进行描绘。最后达到人物形象的高度鲜明与统一，完成传记文学人物的典型性质。所以刘邦、项羽，尽管是历史上的真实人物，所描绘的的也完全符合历史的真实；然而后世却常用来概括两种不同类型的人。作者在描绘这两种人物性格时，爱憎倾向是十分明确的。对项羽主要的是同情和赞颂；对刘邦主要的是鄙夷和贬斥。这就深刻地影响着千百年后读者群众情感的向背，使人们同情的都归于项羽一面。本文在描绘张良、项伯、樊哙、范增的形象上，也极为成功。假如说本文写的是“子房如龙，樊哙如虎”，那么写刘邦就真该是“如狐如鼠”了。\n\n　　第二点，本文善于把巨大的历史事件与丰富的细节描写相结合，善于把生动的场面叙写与细节描绘相结合。在对尖锐的矛盾斗争的叙写当中，完成其惊奇的富于戏剧性的故事情节。\n\n　　这样就能以在尖锐的矛盾斗争的展现当中，完成其惊奇的富于戏剧性的故事情节。使人们在千百年后，一提起鸿门宴故事来，许多人物的活跃形象，都如近在眼前。《鸿门宴》一文，在这一点上，可以说是极其成功的范例。\n\n　　第三点，本文具有周密严谨的组织安排。在材料处理上，也能前后相生，具有缜密的逻辑联系。它密切依照历史发展，把许多材料，加以精心地抉择，并进行了细密的安排组织。使矛盾一环衔着一环，使情节一波推动一波。他以曹无伤密告起，以曹无伤被诛结。以范增说项羽始，以范增怒项羽终。在处理材料上，作者运用了繁（如闯宴）、简（如诛曹）、省（如张良“具告沛公”）、复（如樊哙说项）各种不同笔法，使其相辅相成，以构成全篇严密无间的逻辑结构。帮助了主题内容的显现。这些是本文鲜明特点之一。\n\n　　第四点，是本文在语言运用上达到了一个新的高度。由于作者在传记文学著作上，具有独创精神叛逆情感，所以他能自觉地靠拢人民向民间语言学习；受有明显的影响。许多民间传说与歌谣谚语，都成为作者创作思想与创作语言的重要来源，构成作品的新鲜血液。使它的语言艺术，推进到中古时期散文文学的一个新的高峰：浅切、明白、活泼、朴实。\n\n　　在本文中，如“大行不顾细谨，大礼不辞小让。”“人为刀俎，我为鱼肉。”都是当时流行的成语；而“唉！竖子不足与谋！”则是当时的生动具体的口头语言。\n\n　　从全文语言风格来看，也完全可以说明司马迁的操纵运用语言的能力，远远跨过秦及汉初散文语言的既有水平，达到了一个新的高度。\n\n　　此外，司马迁在善于活用虚词上，也极其出色。他往往凭借表情作用很强的虚词运用，表现人物情态。如本文中，“沛公默然曰：‘固不如也，且为之奈何？’”“项王曰：‘此沛公左司马曹无伤言之，不然，籍何以至此？’”“樊哙曰：‘臣死且不避，酒安足辞！’”等。都是运用虚字进行表情的极其传神处所。《鸿门宴》一文的文学技巧，在整个《史记》当中，是具有代表性的。郭嵩焘说它“自是史公《项羽本纪》中聚精会神，极得意文字。”自非过誉。它不只是达到了“叙事真而描写切”、“语调整齐，字句锤炼”的境地；它也达到了神采辞章双跻峰顶（“理既切至，词亦通畅。”——《文心雕龙·启奏篇》）的新高度。有人也用思想清新、文字精美、内容充实、组织周密四点，对整个《史记》的艺术特点作通俗的概括。这种通俗的概括评价，同样也适用于本文。五　最后，需要说明的是，过去有些论述《鸿门宴》的文章，在作思想内容与艺术特点分析时，往往有一种脱离本段文字而从《项羽本纪》与《高祖本纪》全部着眼进行论列的不当倾向；在作刘、项评价时也有这样毛病。我认为我们分析《鸿门宴》时，还是应该抓紧本文。虽然也应当联系照顾到刘项《本纪》全篇，但却不应喧宾夺主，或者把延伸的意义，说成本篇的思想内容。', poem_tags = '高中文言文,历史,故事' WHERE poem_title = '鸿门宴' AND poem_author = '司马迁';
UPDATE edu_poem SET poem_translation = '一只猴子死后见到了阎王，（向阎王）要求投胎做人。阎王说：“既然你想做人，就需要将毛全部拔掉。”于是（阎王）就叫夜叉给猴子拔毛。刚刚才拔下了一根，猴子就忍不住痛得叫了起来。阎王笑道：“看你，连一根毛都舍不得拔，怎么做人呢？”', poem_notes = '既：既然\n之：代指猴毛\n方：才\n胜：能忍受', poem_appreciation = '故事 　　古代有个富翁，大家都叫他六叔，他十分吝啬。由于他整天盘剥穷人，累得病倒了，差一点昏死过去。三天后，他稍稍清醒了一下，看见屋里挤满了送终的亲友，想要表示什么。他的大侄说：“六叔，是不是还有两个亲人没见面？”他摇摇头。二侄问：“是不是有笔银子放在哪里，不曾交代？”还是他妻子明白，看见两根灯芯同时燃点，就挑掉一根。这时六叔才微微舒了一口气。突然，快断气的六叔流着泪，凑近妻子的耳朵，想跟她说话。他说： “我死后，可把我留下的两张便纸分给前来吊孝的亲戚。” “我死后，别用棺材来盛我，挖个坑，把我埋了就成。” “我死后，不要请和尚念经，我在黄泉下自己会念经的。” “我死后，把我的皮剥下来，卖给皮匠；把我的毛拔下来卖给做刷子的人，一根别丢了……” “一毛不拔”就是一根毛也舍不得拔掉丢失，形容极端自私。 ▲', poem_tags = '小学文言文,寓言,故事,哲理' WHERE poem_title = '一毛不拔' AND poem_author = '邯郸淳';
UPDATE edu_poem SET poem_translation = '黔地（这里的黔不指贵州）这个地方本来没有驴，有一个喜欢多事的人用船运来（一头驴）进入这个地方。运到后却没有什么用处，就把它放置在山脚下。老虎看到它是个庞然大物，把它作为神（来对待），躲藏在树林里偷偷看它。（老虎）渐渐小心地出来接近它，不知道它是什么东西。\n　　有一天，驴叫了一声，老虎十分害怕，远远地逃走，认为（驴）要咬自己，非常害怕。但是（老虎）来来回回地观察它，觉得它并没有什么特殊的本领。（老虎）渐渐地熟悉了驴的叫声，又前前后后地靠近它，但始终不与它搏斗。（老虎）渐渐地靠近驴子，态度更加亲切而不庄重，碰倚靠撞冒犯它。驴非常生气，用蹄子踢老虎。老虎因此而很高兴，盘算这件事说：“驴的技艺仅仅只是这样罢了！”于是跳起来大吼了一声，咬断了驴的喉咙，吃光了它的肉，才离开。\n　　唉！外形庞大好像有德行，声音洪亮好像有能耐，(老虎）当初（如果说）看不出驴的本领，老虎即使凶猛，（但）多疑、畏惧，终究不敢猎取驴子 。如今像这样的下场，可悲啊！', poem_notes = '好事者：喜欢多事的人。\n船载以入：用船载运（驴）进黔。船，这里指用船的意思。以，连词，相当于“而”，表修饰。\n至：到。\n则：表转折，却。\n之：代词，代驴。\n庞然大物：（虎觉得驴是）巨大的动物。庞然，巨大的样子。然，......的样子。\n以为：把……当作。\n蔽：躲避，躲藏。\n窥：偷看。\n稍：逐渐地，渐渐地。\n近：形容词作动词，靠近。\n慭慭（yìnyìn）然：小心谨慎的样子。\n莫相知：不知道它是什么东西。相：一方对另一方，偏指另一方。\n他日：之后的一天。\n大骇：非常害怕。大：很，非常。骇，害怕。\n远遁：跑得远远的。遁：跑，逃跑。\n以为：认为\n且：将要。噬：咬。\n甚：很，非常。\n恐：害怕。\n然：表转折，然而，但是。\n视：观察。\n觉无异能：（虎）觉得（驴）没有特别的本领。异：特别的，与众不同的。能：本领，能力。\n者：语气词，文中表示揣度语气，似的。\n益：渐渐地。\n习：熟悉。\n终：始终。\n搏：搏击，搏斗。\n稍：渐渐地。\n近：靠近。\n益：更加。\n狎：态度亲近而不庄重。\n荡倚冲冒：形容虎对驴轻侮戏弄的样子。荡，碰撞。倚，倚靠。冲，冲撞。冒，冒犯。\n不胜（shēng）怒：非常愤怒。\n蹄：名词作动词，踢。\n因：因此。\n计之：盘算这件事。计，盘算。\n技止此耳：（驴）的本领只不过这样罢了。技，本领。止，同“只”，只不过，仅仅。此，这样。耳，罢了。\n因：于是，就。\n跳踉（tiàoliáng）：跳跃。\n㘎（hǎn）：吼叫。\n尽：（吃）完。\n乃：才。', poem_appreciation = '《黔之驴》是我国一篇著名的古典寓言。开头是这样写的：“黔无驴，有好事者船载以入。至则无可用，放之山下。”\n\n　　作者首先从故事发生的地区环境写起。“黔”，是唐代当时一个行政区的名称，又叫黔中道，包括今天湖南西部、四川东南部、湖北西南部和贵州北部一带。这一带有什么特点呢？“无驴”，从来没有过驴子。这一特点很重要，因为如果没有这一特点，就不会出现后面老虎被驴一时迷惑的情节，因此也就不会发生后面这样的故事。“有好事者船载以入”，有一个没事找事的人用船运去了一头驴。这一句紧紧承接着“黔无驴”三个字而来，交代了寓言中的主要角色驴的来历——原来它是一个外来户。“至则无可用，放之山下”，运到以后，派不上什么用场，就把它放养到山脚下。这两句不仅解释了为什么说运驴的人是一个“好事者”，而且也很巧妙地把这个“好事者”一笔撇开——因为他同后面的情节没有关系——从而为下文集中描写寓言中的主要角色准备了方便条件。\n\n　　随着驴被“放山下”，到了一个具体的地方，寓言中的另一角色虎的出场就很自然了：\n\n　　虎见之，庞然大物也，以为神，蔽林间窥之。稍出近之，慭慭然，莫相知。他日，驴一鸣，虎大骇，远遁，以为且噬己也，甚恐。\n\n　　这一段主要写虎见到驴以后的心理状态。“虎见之，庞然大物也，以为神”，老虎看到这个又高又大的家伙，以为是什么神物。这是虎对驴的最初印象和认识。由于寓言一开头就交代了“黔无驴”，谁也没有见过，因此老虎少见多怪，产生这样的错觉是很自然的。于是，“蔽林间窥之”，它就躲藏到树林里，偷偷地盯着驴子。这里，一个“蔽”字，充分写出了老虎在“以为神”的认识基础上所产生的害怕心理；而一个“窥”字，又说明了作为兽中之王的老虎虽怕但并不甘心、亟想摸清对方底细的心理活动，从而孕育了后面情节的必然发展。“稍出近之”，后来老虎又慢慢走出来向驴靠近些。这是对老虎并不甘心、打算摸底的心理的进一步揭示。“蔽林间窥之，稍出近之”两句，不仅写出了老虎行动的连续和发展——由迅速离开驴子的“蔽”，到立定脚跟的“窥”，再到走出树林、走向驴子的“近”——而且初步地揭示了老虎一心要认识这个“庞然大物”的决心。不过这里的“近”，并不是说同驴已经靠得很近了，只是指略微缩短了一点同驴的距离罢了；因为这时老虎对驴还是“慭慭然莫相知”，小心谨慎，不知道它是个什么怪物。“慭慭然”，谨慎害怕的样子。由于“莫相知”，自然“慭慭然”；而由于“慭慭然”，当然也就只能“稍出近之”了。这里“莫相知”三字，既有承上的作用，说明老虎产生“慭慭然”不安心理和采取“稍出近之”谨慎行动的原因；又有启下的作用，交代了后面情节演进的根据。“他日”，有一天。这是寄全于一的笔法，说明老虎为了改变自己“莫相知”的状况，对驴观察已经不止一天了。由此也可见其决心。然而认识并未取得进展，仍然停留在“以为神”的阶段。所以“驴一鸣”，驴子吼叫一声，“虎大骇，远遁”，老虎大吃一惊，逃得远远的。为什么要“远遁”呢？“以为且噬己也”，因为老虎认为驴子要吃掉自己，所以“甚恐”，非常恐惧。“以为且噬己也”，点明了“甚恐”的实质；而“甚恐”，又为老虎后来识破驴子的真面目得出“不过如此”的结论进行了铺垫。\n\n　　这一节写老虎的心理活动虽然只是一个“怕”字，但时起时伏，非常生动。“虎见之，庞然大物也，以为神”，畏惧之心突然而起；“蔽林间”，可见害怕得还很厉害，纵是兽中之王，也不敢露面；“窥之”，虽害怕得很，但惊魂初定；“稍出近之”，说明畏惧心理已经明显减少，尽管仍然小心翼翼；“驴一鸣，虎大骇，远遁”，“甚恐”，畏惧之心又一下子达到了高潮。而所有这些变化又无不围绕着“以为神”的思想认识。\n\n　　然而老虎“远遁”，会不会一走了之呢？如果这样，情节又将如何发展呢？我们不用担心，因为从虎一开始所表现出来的虽怕驴但并不甘心的心理活动来看，它是不会一走了之的。事实正是这样，虎不但没有逃之夭夭，而且很快就看穿了驴子的假象；不仅逐渐消除了畏驴之心，甚至慢慢产生了吃驴之意：\n\n　　然往来视之，觉无异能者。益习其声，又近出前后，终不敢搏。\n\n　　这一节主要写虎对驴认识的深入。“然往来视之，觉无异能者。”然而通过来回观察，觉得驴并没有什么特殊的本领。这是虎对驴“神”的形象怀疑的开始。这里的一个“然”字，非常有力，具有特殊的作用，不仅是语气的转折，而且也是虎由怕驴到逐渐认清驴的本质并最后把驴吃掉的整个情节的转折。“往来”，说明老虎的观察是多么细心和频繁。因而“觉无异能者”，并进而“益习其声”，对驴的吼叫声也逐渐习惯了。心理上的这一变化，必然导致行动上的更加大胆，于是，“又近出前后”，进一步到驴子的身前身后转来转去。注意，这里的“近”，比“稍出近之”的“近”，又进了一步，是逼近的意思，充分反映了老虎“觉无异能者”的心理。那么，既然认为驴子没有什么了不起，又为什么“终不敢搏”，始终不敢扑上去抓取它呢？这是因为老虎对驴的底细尚未彻底摸清的缘故。——虽然“觉无异能者”，但驴子的“无异能”，只不过是自己的主观感觉罢了，实际情况如何，谁又知道！一个“终”字，把老虎慎重对敌、不敢贸然行事的思想揭示得淋漓尽致；而一个“搏”字，又把老虎围绕驴子煞费苦心的全部目的披露无遗，从而为后面的吃驴情节作了伏笔。\n\n　　这一节写虎“觉无异能者”的心理活动，尽管归结为“终不敢搏”，仍有怕的意味，但与开始的怕不仅有着程度上的不同，而且有着性质上的区别：以前的怕，是担心自己被对手吃掉的恐惧；怕，只不过是担心自己不能顺利吃掉对方的顾虑而已。所以，“终不敢搏”，既说明了老虎对驴的认识由“以为神”到“觉无异能者”的巨大进步，同时也说明了它对驴的彻底认识还有待于进一步深入。\n\n　　那么后来，虎是怎样取得了对驴的彻底认识并终于消除了顾虑的呢？\n\n　　稍近益狎，荡倚冲冒。驴不胜怒，蹄之。虎因喜，计之曰：“技止此耳！”\n\n　　这一节写虎对驴认识的最后完成。为了彻底摸清驴的底细，改变自己“终不敢搏”的心理，虎进行了一系列的试探活动。首先，“稍近”，慢慢靠拢驴子。注意，这里的“近”，比“近出前后”的“近”，又进了一步，说明虎已经非常贴近驴子了。“稍近”之后，“益狎”，越来越轻佻起来——这是对驴进行戏弄；进而又“荡倚冲冒”，摇摇它，靠着它，撞击它，甚至扒着它的脊背(“冒”，古代同衣帽的“帽”，覆盖的意思)——这是对驴进行挑逗。这里，我们不仅看到了虎一系列的挑衅性的行动，而且通过它得寸进尺、逐步发展的行动，还可以察知它大胆而谨慎、既藐视对方又重视敌手的思想。由“近出前后”的观察到“稍近”的试探，已经大胆了，但这毕竟只是距离的逼近；见对方没有反应，才进而由“稍近”的试探到“益狎”的戏弄，但这毕竟只是态度上的不恭；见对方仍然没有反应，最后才由态度上的“益狎”到动作上的“荡倚冲冒”。看到虎越来越无理和放肆，“驴不胜怒，蹄之”，驴再也压抑不住愤怒了，就踢了虎。这一下驴在虎的面前终于暴露了自己的全部秘密。所以，“虎因喜”，老虎因而非常高兴。显然，它是在为自己终于摸清了对手的老底——最大能耐不过一“蹄”而已——而在窃窃自喜。然而尽管如此，虎在下最后结论之前，还得要“计之”，在心里掂掇掂掇。掂掇什么呢？是不是对方还有更厉害的招儿没有使出来呢？想了想，不可能；因为自己对它“荡倚冲冒”，已经使它到了“不胜怒”的程度了，盛怒之下，不顾一切，哪里还能保留一手呢？一个“计”字，又一次有力地说明了虎对陌生之敌的格外重视。经过审慎地“计之”以后，才“曰：‘技止此耳’”，说：它的本领也不过这么一点点罢了。\n\n　　到这里，虎已经把驴的本质彻底揭穿了。随着它对驴的认识的最后完成，“终不敢搏”的心理自然也就不复存在了：\n\n　　因跳踉大阚，断其喉，尽其肉，乃去。\n\n　　于是虎大吼一声，腾空扑去，咬断了驴的喉咙，吃光了它的肉，心满意足而去。这一小节写驴终于葬身虎腹的下场，尽管情节非常简单，只有“吃驴”两字，但作者写起来并没有简单化。吃驴之前，先写虎“跳踉大”，大发威风，用足令百兽魂飞魄散的一吼一纵震摄住对方，让它乖乖就范；吃驴时，也不是一下子就“尽其肉”，而是先“断其喉”，击其要害，使其毙命，然后大嚼大吃，一啖而光。这样描写，既生动而具体，又说明了慎重对敌的老虎是多么机警和精明。\n\n　　以上，是寓言的故事情节。介绍到这里，你有什么感想呢？你是否觉得黔驴可悲呢？然而它又可悲在什么地方呢？人们从这里应该获得什么教训呢？这些问题，也许你还未来得及考虑。那么，我们还是先来看看作者的议论和感叹吧：\n\n　　噫！形之庞也类有德，声之宏也类有能。向不出其技，虎虽猛，疑畏，卒不敢取。今若是焉，悲夫！\n\n　　这一节正面写作者对这一事件的看法。“噫！形之庞也类有德，声之宏也类有能。”唉！形体庞大好像很有风度和德性，声音洪亮好像很有本事和能耐。这里，言外之意是说，形虽庞而无德，声虽宏而无能，徒有其表，名不副实，这是第一可悲之处。“向不出其技，虎虽猛，疑畏，卒不敢取。”当初如果不拿出那么一点可怜的本领，虎虽然凶猛，但因疑虑、畏惧，始终不敢吃掉它。这里，言外之意是说，驴既不知自己无能，更不知敌手强大，轻举妄动，终于落了个被“断喉”“尽肉”的下场，这是第二可悲之处。以上，作者用言外之意的议论指出黔驴的可悲，虽然辛辣但还比较委婉；篇末用感叹指出它的可悲，就直截了当了：“今若是焉，悲夫！”如今是这样，真可悲！显然，“今若是焉”，正是指前面言外之意的两层议论，既包括“类有德”而没有德、“类有能”而没有能的意思，更包括“今出其技”、自取灭亡的意思。所以，作者发出“悲夫”的深沉长叹。\n\n　　这篇寓言的题目叫“黔之驴”，然而通篇写驴的笔墨却很少，只有“庞然大物”“一鸣”“不胜怒，蹄之”等十多个字；相反，写虎的笔墨却非常之多，从开始的畏驴，到中间的察驴，再到最后的吃驴都写了。既有不断发展的行动的生动描写，更有不断变化的心理的细致刻画。因此，也许有的人要问：这是否有点“文不对题”呢？既然重点写虎，为什么不命题叫“黔之虎”呢？要回答这个问题，必须弄清这篇寓言的主题是什么，作者创作这篇寓言的意图是什么。我们知道，《黔之驴》是柳宗元在“永贞革新”失败后，他因参加这一进步改革而被贬作永州司马时写的《三戒》中的一篇。所谓“三戒”，就是应该引起世人警戒的三件事。《黔之驴》就是以黔驴的可悲下场，警戒那些“不知推己之本”、毫无自知之明而必将自招祸患的人。联系作者的政治遭遇，讽刺当时无德无能而官高位显、仗势欺人而外强中干的统治集团中的某些上层人物，指出他们必然覆灭的下场，也就不能不是他的写作动机了。这一点，从寓言末尾作者的议论、感叹和《三戒》文前的小序当中都可以得到说明。显然，要想表现这样的主题思想，关键在于充分揭示黔驴的可悲下场；而黔驴覆灭的可信与否，关键又在于是否能够把虎写活。——这，也许就是作者为什么命题为“驴”而着意写虎的原因了。当然，如果把主题理解为对于任何事物，不应被表面现象迷惑，只要弄清其本质，认真对付，就一定能战而胜之，那么寓言自然就“文不对题”而应易之为“虎”了。应该说，这样理解，也未尝不可。但是必须明白，这是对寓言本意的引申和发挥，不是原作的本来意思。\n\n　　然而，尽管用于驴的笔墨甚少，但是驴的形象依然极其鲜明。这当然一方面是由于借助虎的形象的有力衬托。因为虎的一切心理和行动都是围绕驴而产生和展开的，所以明写了虎的深谋谙练、谨慎精明，也就暗写了驴的麻木不仁、愚不可及，这样，驴的形象便在不写之中被写出来了。另一方面，这是由于描写驴的笔墨虽少却精、以寡胜多的缘故。“庞然大物”一语，由于作者没有把它处理成自己笔下的客观描写，而是作为老虎心目中的主观反映，这就很富讽刺意味，不仅明写了驴的外在形体，而且暗示了它的内在无能。“不胜怒，蹄之”五字，通过对驴的心理和行动的极其简略的交代，就把它在别人暗算面前的麻木和乖乖进入圈套的愚蠢揭示无遗。如果说在虎“荡倚冲冒”的时候，作者只用“蹄之”两字就写出了驴的愚蠢上当；那么，在虎“慭慭然，莫相知”的时候，作者只用“一鸣”两字就似乎写出了驴的虚荣和卖弄了。因为当时虎对驴并无任何妨害，所以驴让虎“大骇”“远遁”“甚恐”的“一鸣”之举，不是自我炫耀、借以吓人又是什么呢？人们都把驴作为愚蠢的代名词，看来同它在这篇寓言里的鲜明形象是不无关系的。\n\n　　总之，柳宗元的《黔之驴》这篇寓言，笔法老到，造诣精深；既揭示了深刻的哲理，又塑造了生动的形象；不仅给人们以思想上的启示和教育，而且给人们以艺术上的享受和满足，难怪它千古传诵成为我国文苑里一朵永不凋谢的奇花。', poem_tags = '初中文言文,寓言,故事' WHERE poem_title = '黔之驴' AND poem_author = '柳宗元';
UPDATE edu_poem SET poem_translation = '细焚沉香，来消除夏天闷热潮湿的暑气。鸟雀鸣叫呼唤着晴天（旧有鸟鸣可占雨之说），拂晓时分我偷偷听它们在屋檐下的“言语”。荷叶上初出的阳光晒干了昨夜的雨，水面上的荷花清润圆正，荷叶迎着晨风，每一片荷叶都挺出水面。\n（看到这风景）我想到遥远的故乡，何日才能回去啊？我家本在吴越一带，长久地客居长安。五月，我故乡的小时候的伙伴是否在想我，划着一叶扁舟，在我的梦中来到了过去的荷花塘（词中指杭州西湖）。', poem_notes = '燎（liáo）：烧。\n沉香：木名，其芯材可作熏香料。沈，现写作沉。沈（沉）香，一种名贵香料，置水中则下沉，故又名沉水香，其香味可辟恶气。\n溽(rù)暑：潮湿的暑气。沈约《休沐寄怀》诗：“临池清溽暑，开幌望高秋。”溽，湿润潮湿。\n呼晴：唤晴。旧有鸟鸣可占晴雨之说。\n侵晓：快天亮的时候。侵，渐近。\n宿雨：昨夜下的雨。\n清圆：清润圆正。\n风荷举：意味荷叶迎着晨风，每一片荷叶都挺出水面。举，擎起。司空图《王官二首》诗：“风荷似醉和花舞，沙鸟无情伴客闲。”\n吴门：古吴县城亦称吴门，即今之江苏苏州，此处以吴门泛指江南一带。作者乃江南钱塘人。\n长安：原指今西安，唐以前此地久作都城，故后世每借指京都。词中借指汴京，今河南开封。\n旅：客居。\n楫（jí）：划船用具，短桨。\n芙蓉浦：有荷花的水边。有溪涧可通的荷花塘。词中指杭州西湖。唐张宗昌《太平公主山亭侍宴》诗：“折桂芙蓉浦，吹萧明月湾。” 浦，水湾、河流。芙蓉，又叫“芙蕖”，荷花的别称。', poem_appreciation = '读书求仕，是古代文人普遍的人生选择，一旦踏入仕途，便游宦四方，长期远离家乡，难免不思念故乡的亲人与风物，因此，思乡成为古代诗词中的永恒主题，最能引发天涯游子的共鸣。思乡的情怀往往借助作家记忆中印象最深刻的故乡景物来表达，周邦彦的这首《苏幕遮》正如此，它以荷为媒介，表达对故乡杭州的深深眷念。\n\n　　此词上片描写盛夏早晨的风景：词人一早醒来，便嗅到昨夜点燃的沉香依旧弥漫在空气中，令人烦闷的暑热也已退去。窗外传来鸟儿叽叽喳喳的欢叫声，据说鸟鸣声能预测晴雨，莫非天已放晴？词人抬头朝窗外望去，只见天色才微微放亮，鸟雀在屋檐上跳来跳去，晃动着头脑争噪不停，似乎也在为雨后新晴而喜悦。盛夏酷暑时节，难得有这样一个清爽的早晨，词人漫步荷塘边，只见荷叶上的雨珠在朝阳下渐渐变干，看上去更加碧绿净洁，一张张圆圆的荷叶铺满水面。一株株荷花亭亭玉立在荷叶间，微风吹过，微微颤动着更显丰姿绰约。“叶上初阳干宿雨，水面清圆，一一风荷举”被誉为写荷名句，王国维在《人间词话》中称赞此语“真能得荷之神理”，寥寥几笔，将荷的摇曳多姿、神清骨秀写尽，营造出一种清新恬静的境界，\n\n　　下片转入思乡的愁怀与回忆。眼前的荷塘，勾起了词人的乡愁：故乡遥遥，就在那莲叶田田的江南，羁旅京师已经很久，何时才能归去？汴京（今河南开封）的荷塘唤起了词人的思乡浓情，思绪飞回故乡，不知儿时的玩伴是否还记得五月同游西湖的情景？多少次梦回故乡，依然是划着轻巧的小船驶向荷塘。杭州西湖上的“十里荷花”闻名天下，杨万里曾写道：“接天莲叶无穷碧，映日荷花别样红”。词人生长于斯，他对荷花的记忆是与童年的水乡生活联系在一起的。京城夏日雨后荷塘的景致牵动了词人对故乡最亲切的回忆，荷花成了词人思乡的媒介，同时将这首词的上下片联成一气，成为一篇写荷绝唱。\n\n　　这首词天然真美，不事雕饰，它以质朴无华的语言，准确而又生动地表现出荷花的风神与词人的乡愁，有一种从容雅淡、自然清新的风韵，这在周邦彦以雕饰取胜的词作中当为别具一格之作，陈延焯称赞此词“风致绝佳，亦见先生胸襟恬淡。”词人这份恬淡的胸襟不正是故乡“天然去雕饰”的荷花所赋予的吗？', poem_tags = '宋词三百首,高中古诗,婉约,荷花,思乡' WHERE poem_title = '苏幕遮·燎沉香' AND poem_author = '周邦彦';
UPDATE edu_poem SET poem_translation = '从前有个愚蠢的人，到朋友家，主人给他食物。食物嫌淡而无味。主人知道之后，于是添加盐。吃的，很美，于是自言自语说：“之所以味道鲜美，是有了盐的缘故。很少就如此，何况又多了？”这个愚蠢的人没有智慧，就只吃盐。味觉败坏，反而成为他的祸患。天下的事情都是这样，经过则不但没有好处，反而是有害的。', poem_notes = '食：食物。\n闻已：听罢。\n更：再次。\n益：增加。\n既：已经。\n空：空口。\n口爽：口味败坏。\n所以：……的原因。\n复：再。\n爽：差、败坏。\n智：智慧。\n故：缘故。\n反：反而。\n患：祸患。', poem_appreciation = '从前有一个愚笨的人，有一天到一个很远的朋友家里去。主人便很殷勤地招待。并煮了好几道好菜招待这位客人，可是忘了放盐，所以每道菜都淡而无味。这位客人对主人说：“你今天烧的菜都很名贵，可是淡了一点，所以不太好吃。”主人说：“啊！我忘了放一样东西！”于是到厨房拿了些盐，放进每一道菜，搅拌了一会儿再请客人尝尝，这回每道菜都很美味可口。问主人说：“你放了些什么，菜就那么好吃？”\n\n　　主人说：“放盐呀！之所以每样菜都好吃，是因为有盐，盐是百味之源。”傻人以为盐既然那么好吃，回去每餐都买盐来吃好了，省得煮那么多菜。于是到了街上买了一大包的盐，回到家里急忙打开，抓了一把放进嘴里，苦涩不堪，以为是被那位亲戚骗了。\n\n　　各位大众，世间各人有各人的智识，知识也有高高低低的差别。知识是改造自己和利益他人的武器。若是智识用之不当！也可能毁灭自己、和违害社会。更是要用得不偏不倚，才能发挥效用。\n\n　　比喻贪吃好玩，与断食偏食都不适中。过分的享乐与吃苦主义都有偏。世间万事必须适中，过与不及都可能坏事。又比喻有些人做事不负责任，可能一生一世都一事无成，过分的热衷名利，也会造成争夺计较而造恶业，或劳碌一生，与烦恼纠缠不休，乃至生生世世都轮回不息。\n\n　　世间万事做得适中，即成功立业。物用之得适即物物皆良，人用之得适即人尽其才。时、地、人、都恰到好处，即事事皆通，否则事事都障碍。世间事事物物皆须靠我\n\n　　禅宗的祖师，往往一言半句即开启人的智慧—开悟。有人一生埋在禅堂里，埋在经典里参研，都不能开悟何故？机缘也、善根也、智慧也、对机对法，遇缘即应。否则多费工夫也没有受用，所以佛法一点点都很能受用，无善根无缘分的人再多亦没有用。\n\n　　有些不法的人说：‘德行一斤值多少钱？’他们视道德良善一文不值！可是对于修行的人来说，德行乃是无上的至宝。一样一种东西，有的人如宝贝一样，有的人视如粪土，这就得看人的用途了。就好像有某些信仰佛教的人说：我没有空念佛，也没有空用功修行，待儿女长大以后，才来好好用功。\n\n　　我们一天二十四小时，真的一点空都没有吗？我想不是的，都是名和利填藏满了脑子里，那里有空呢？有信心的人把佛法当做至宝，没有信心的人把佛法当做闲时的消遣品！能不能受用佛法就是在这里。能受用的人，就是一点一滴也当作宝贝，而受持奉行。不能受用的人，就是听多了，返而变成‘。本则故事意义就在这里。', poem_tags = '小学文言文,写人,哲理,故事' WHERE poem_title = '愚人食盐' AND poem_author = '僧伽斯那';
UPDATE edu_poem SET poem_translation = '车辆隆隆响，战马萧萧鸣，出征士兵弓箭各自佩在腰。爹娘妻子儿女奔跑来相送，行军时扬起的尘土遮天蔽日以致看不见咸阳桥。拦在路上牵着士兵衣服顿脚哭，哭声直上天空冲入云霄。\n路旁经过的人问出征士兵怎么样，出征士兵只是说按名册征兵很频繁。有的人十五岁到黄河以北去戍守，纵然到了四十岁还要到西部边疆去屯田。到里长那里用头巾把头发束起来，他们回时已经白头还要去守边疆。边疆无数士兵流血形成了海水，武皇开拓边疆的念头还没停止。您没听说汉家华山以东两百州，百千村落长满了草木。即使有健壮的妇女手拿锄犁耕种，田土里的庄稼也长得没有东西行列。更何况秦地的士兵又能够苦战，被驱使去作战与鸡狗没有分别。\n尽管长辈有疑问，服役的人们怎敢申诉怨恨？就像今年冬天，还没有停止征调函谷关以西的士兵。县官紧急地催逼百姓交租税，租税从哪里出？如果确实知道生男孩是坏事情，反而不如生女孩好。生下女孩还能够嫁给近邻，生下男孩死于沙场埋没在荒草间。您没有看见，青海的边上，自古以来战死士兵的白骨没人掩埋。新鬼烦恼地怨恨旧鬼哭泣，天阴雨湿时众鬼凄厉地发出啾啾的哭叫声。', poem_notes = '兵车行：选自《杜诗详注》。这首诗大约作于天宝中后期。当时唐王朝对西南的少数民族不断用兵。天宝八年（749），哥舒翰奉命进攻吐蕃，石堡城（在今\n西安北部）一役，死数万人。十年（751），剑南节度使鲜于仲通率兵八万进攻南诏（辖境主要在今云南），军大败，死六万人。为补充兵力，杨国忠遣御史分道捕人，连枷送往军所，送行者哭声震野。这首诗就是据上述情况写的。这是一首乐府诗。题目是诗人自拟的。\n辚（lín）辚：车轮声。《诗经·秦风·车辚》：“有车辚辚”。\n萧萧：马嘶叫声。《诗经·小雅·车攻》：“萧萧马鸣”。\n行(xíng)人：指被征出发的士兵。\n耶：通假字，同“爷”，父亲。\n走：奔跑。\n咸阳桥：指便桥，汉武帝所建，故址在今陕西咸阳市西南，唐代称咸阳桥，唐时为长安通往西北的必经之路。\n干(gān)：冲。\n过者：过路的人，这里是杜甫自称。\n但云：只说\n点行（ xíng ）频：频繁地点名征调壮丁。\n或：不定指代词，有的、有的人。\n防河：当时常与吐蕃发生战争，曾征召陇右、关中、朔方诸军集结河西一带防御。因其地在长安以北，所以说“北防河“。\n西营田：古时实行屯田制，军队无战事即种田，有战事即作战。“西营田“也是防备吐蕃的。\n里正：唐制，每百户设一里正，负责管理户口。检查民事、催促赋役等。\n裹头：男子成丁，就裹头巾，犹古之加冠。古时以皂罗（黑绸）三尺裹头，曰头巾。新兵因为年纪小，所以需要里正给他裹头。\n还（huán）\n边庭：边疆。\n武皇：汉武帝刘彻。唐诗中常有以汉指唐的委婉避讳方式。这里借武皇代指唐玄宗。唐人诗歌中好以“汉”代“唐”，下文“汉家”也是指唐王朝。\n开边：用武力开拓边疆。\n汉家: 汉朝。这里借指唐。\n山东：崤山或华山以东。古代秦居西方，秦地以外，统称山东。\n荆杞(qǐ )：荆棘与杞柳，都是野生灌木。\n陇(lǒng)亩：田地。\n陇，通“垄”，在耕地上培成一行的土埂，田埂，中间种植农作物。\n无东西：不分东西，意思是行列不整齐。\n况复：更何况。\n秦兵：指关中一带的士兵。耐苦战--能顽强苦战。这句说关中的士兵能顽强苦战，像鸡狗一样被赶上战场卖命。\n长者：即上文的“道旁过者“，也指有名望的人，即杜甫。征人敬称他为“长者“。“役夫敢申恨“：征人自言不敢诉说心中的冤屈愤恨。这是反诘语气，表现士卒敢怒而不敢言的情态。\n役夫：行役的人。\n敢：岂敢，怎么敢。\n且如：就如。\n关西：当时指函谷关以西的地方。这两句说，因为对吐蕃的战争还未结束，所以关西的士兵都未能罢遣还家。\n县官：官府。\n比邻：近邻。\n青海头：即青海边。这里是自汉代以来，汉族经常与西北少数民族发生战争的地方。唐初也曾在这一带与突厥、吐蕃发生大规模的战争。\n烦冤：愁烦冤屈。\n啾啾：象声词，形容凄厉的哭叫声。', poem_appreciation = '1．章法严密 　　先说形式。这首诗的结构方式古称“一头两脚体”。全诗共三段：第一段（即“头”）共6句（按乐句计算，下同），一韵到底；第二、三段（即“两脚”）各14句，并四次换韵。从整体看，节奏整齐而又略有变化；且各段皆自有起结，析之则三，合则为一。\n\n　　再说内容。其特点有二：一是前后呼应，例如第一段以“牵衣顿足拦道哭”写战士家属，颇有生离死别之意，下面就用“边庭流血成海水”“生男埋没随百草”来证明“行人”此去决难生还；又如第二段以“千村万落生荆杞”“禾生陇亩无东西”写农村生产凋敝，第三段再说“县官急索租，租税从何出”也就显得顺理成章了。二是层层递进，这在“行人”答话里表现极为鲜明。这篇答话由“点行频”三字领出，接着用“十五北防河”“四十西营田”为例加以证明，又以“武皇开边意未已”说明频繁征兵的原因，揭示了事情的本质，使意境加深一层。循此继进，先以“君不闻”翻出一层新意，揭露“开边”战争给农业生产造成极大危害，土地无人耕种，荆杞遍野；后说本地区人民无以为生而朝廷依旧催索租税，意境又深。再顺势说到战争怎样改变了传统的社会心理，以半宽慰半哀叹的方式将怨愤之情暂时隐藏起来。经过如此层层蓄势，最后更以“君不见”翻出又一层新意，描绘了古战场的阴森景象，将满腔的怨愤一齐宣泄出来，也表达了人民强烈的反战愿望。\n\n　　2．生动的场景描写 　　诗的开头写士兵家属前来送别的场面。前两句为“宾”，写出征士兵。“辚辚”“萧萧”是听觉形象，令人有人马杂沓之感，可以想见出征士兵之多；“弓箭各在腰”是视觉形象，表明一切准备就绪，只待一声令下就要出发。后四句为“主”，写士兵家属，突出地描写了他们的动作细节。“走”，表明这些人闻讯后立即跑了来，心情万分急切。他们料定，很可能这是生离死别，所以一见面就“牵衣”而泣，“顿足”而呼；待到队伍出发了，他们拦在道上，不让自己的子弟离去，而且哭得更厉害了，千万人的哭声汇成了震天巨响，仿佛吞没了一切……诗人用这些细节给这个场面渲染了极其凄惨的气氛，借此表达了人民对无休止的“开边”战争的怨愤，使这首诗具有明显的倾向性。\n\n　　结尾写青海战场的景象，好像是用摄影机拍下的一个全景镜头：漫山遍野，白骨纵横，在阴沉的天色和蒙蒙细雨中，不时地闪出磷火，传来凄厉的鬼哭声。如此阴森的景象，真叫人不寒而栗!诗人这样来描绘古战场，其意仍在讽今──揭露“开边”政策的罪恶，颇能发人深思。\n\n　　3．名句赏析 　　（1）“去时里正与裹头，归来头白还戍边。”\n\n　　这是对前两句“或从十五北防河，便至四十西营田”所作的形象说明，读罢使人心酸不已。古代孩子留长发，15岁开始用头巾束发。如今，一个刚到束发年龄还不怎么会束发的孩子就被征入伍，而且要到远离父母的北方去“防河”，这是何等可怜啊!所以，连里正也动了心，替他束发。人过40，头发渐白，又刚从前线回来，理当休息了，不料又被派到前线去。从这两件事可以看出统治者的残酷简直到了无以复加的地步。\n\n　　（2）“生女犹得嫁比邻，生男埋没随百草。”\n\n　　这两句写社会心理的变化。在封建社会里，人们重男轻女，生男则喜，生女则悲；可是现在不同了，反以生男为“恶”，生女为“好”。这种变化是由繁重的兵役负担和士兵大量死亡的事实造成的，反映了人们心灵受伤害之深。这两句主宾分明：上句是自我宽慰之辞，为“宾”；下句是哀叹之辞，为“主”。以自我宽慰烘托哀叹，更显出哀叹之深。这样的心理变化也是对统治者穷兵黩武政策的有力控诉。\n\n　　场景、内容解读\n\n　　一、场景：\n\n　　1、送别场面—诀别 　　诗歌以重墨铺染的雄浑笔法，在读者眼前突兀展现出一幅扣人心弦的巨幅送别图：兵车隆隆，战马嘶鸣，一队队被抓来的穷苦百姓，换上了戎装，佩上了弓箭，在官吏的押送下，正开往前线。征夫的爷娘妻子乱纷纷地在队伍中寻找、呼喊自己的亲人，扯着亲人的衣衫，捶胸顿足，边叮咛边呼号。车马扬起的灰尘，遮天蔽日，连咸阳西北横跨渭水的大桥都被遮没了。千万人的哭声汇成震天的巨响在云际回荡。“耶娘妻子走相送”，一个家庭支柱、主要劳动力被抓走了，剩下来的尽是些老弱妇幼，对一个家庭来说不啻是一个塌天大祸，怎么不扶老携幼，奔走相送呢?一个普通的“走”字，寄寓了诗人多么浓厚的感情色彩!亲人被突然抓兵，又急促押送出征，眷属们追奔呼号，去作那一刹那的生死离别，是何等仓促，何等悲愤!“牵衣顿足拦道哭”，一句之中连续四个动作，又把送行者那种眷恋、悲怆、愤恨、绝望的动作神态，表现得细腻入微。诗人笔下，灰尘弥漫，车马人流，令人目眩；哭声遍野，直冲云天，震耳欲聋!这样的描写，给读者以听觉视觉上的强烈感受，集中展现了成千上万家庭妻离子散的悲剧，令人触目惊心!\n\n　　2、征夫诉苦—抓兵 　　接着，从“道旁过者问行人”开始，诗人通过设问的方法，让当事者，即被征发的士卒作了直接倾诉。\n\n　　“道旁过者”即过路人，也就是杜甫自己。上面的凄惨场面，是诗人亲眼所见；下面的悲切言辞，又是诗人亲耳所闻。这就增强了诗的真实感。“点行频”，意思是频繁地征兵，是全篇的“诗眼”。它一针见血地点出了造成百姓妻离子散，万民无辜牺牲，全国田亩荒芜的根源。接着以一个15岁出征，40岁还在戍边的“行人”作例，具体陈述“点行频”，以示情况的真实可靠。\n\n　　“边庭流血成海水，武皇开边意未已。”“武皇”，是以汉喻唐，实指唐玄宗。杜甫如此大胆地把矛头直接指向了最高统治者，这是从心底迸发出来的激烈抗议，充分表达了诗人怒不可遏的悲愤之情。\n\n　　诗人写到这里，笔锋陡转，开拓出另一个惊心动魄的境界。诗人用“君不闻”三字领起，以谈话的口气提醒读者，把视线从流血成海的边庭转移到广阔的内地。诗中的“汉家”，也是影射唐朝。华山以东的原田沃野千村万落，变得人烟萧条，田园荒废，荆棘横生，满目凋残。诗人驰骋想像，从眼前的闻见，联想到全国的景象，从一点推及到普遍，两相辉映，不仅扩大了诗的表现容量，也加深了诗的表现深度。\n\n　　3、征夫诉苦—逼租 　　从“长者虽有问”起，诗人又推进一层。“长者”，是征夫对诗人的尊称。“役夫”是士卒自称。“县官”指唐王朝。“长者”二句透露出统治者加给他们的精神桎梏，但是压是压不住的，下句就终究引发出诉苦之词。敢怒而不敢言，而后又终于说出来，这样一阖一开，把征夫的苦衷和恐惧心理，表现得极为细腻逼真。\n\n　　这几句写的是眼前时事。因为“未休关西卒”，大量的壮丁才被征发。而“未休关西卒”的原因，正是由于“武皇开边意未已”所造成。“租税从何出?”又与前面的“千村万落生荆杞”相呼应。这样前后照应，层层推进，对社会现实的揭示越来越深刻。这里忽然连用了几个短促的五言句，不仅表达了戍卒们沉痛哀怨的心情，也表现出那种倾吐苦衷的急切情态。这样通过当事人的口述，又从抓兵、逼租两个方面，揭露了统治者的穷兵黩武加给人民的双重灾难。\n\n　　二、人民苦难及其根源 　　诗人接着感慨道：如今是生男不如生女好，女孩子还能嫁给近邻，男孩子只能丧命沙场。这是发自肺腑的血泪控诉。重男轻女，是封建社会制度下普遍存在的社会心理。但是由于连年战争，男子的大量死亡，在这一残酷的社会条件下，人们却一反常态，改变了这一社会心理。这个改变，反映出人们心灵上受到多么严重的摧残啊!\n\n　　最后，诗人用哀痛的笔调，描述了长期以来存在的悲惨现实：青海边的古战场上，平沙茫茫，白骨露野，阴风惨惨，鬼哭凄凄。寂冷阴森的情景，令人不寒而栗。这里，凄凉低沉的色调和开头那种人声鼎沸的气氛，悲惨哀怨的鬼泣和开头那种惊天动地的人哭，形成了强烈的对照。这些都是“开边未已”所导致的恶果。至此，诗人那饱满酣畅的激情得到了充分的发挥，唐王朝穷兵黩武的罪恶也揭露得淋漓尽致。\n\n　　三、思想内容 　　诗人把这个历史镜头捕捉到自己的诗中来，不过是拿它作为一出社会悲剧的序幕，而他的主要意图是揭露统治阶级对人民的残酷压迫。因此，紧接着这个序幕，就通过“行人”答问逐层深入地展示这出悲剧的内容：“去时里正与裹头，归来头白还戍边”——这是说丁壮们无限期地超期服役；“边庭流血成海水”——这是千百万战士战死沙场；“汉家山东二百州，千村万落生荆杞”——这是说全国农村生产凋敝；“县官急索租，租税从何出”——这是说人民连生计都无法维持，而朝廷依旧逼索租税。可见，这种艺术概括方式的基本点是，由点到面、由现象到本质地勾画出安史之乱前的一个历史时期里社会的真实状况。读完这首诗，我们不仅可以看到整整一代人的深重苦难，而且能触摸到诗人那颗同情人民的火热的心。\n\n　　这首诗的意义还不止于此，更为重要的是，它表现了诗人反对“开边”战争的坚定立场。“边庭流血成海水，武皇开边意未已”，说明他认识到这种不义的战争是一切苦难的根源；他敢于把战争的责任加在最高统治者身上，这样的勇气是当时众多的诗人所不具有的。诗人的这种立场是一贯的，在《前出塞》中他曾写道：“君已富土境，开边一何多”“杀人亦有限，立国自有疆”。这正是杜诗人民性之所在。\n\n　　四、结尾写古战场的含义 　　诗人描写青海古战场的阴森景象，不是为了宣扬战争的恐怖，而是为说明必须停止对边疆少数民族的战争，即“列国自有疆”(《前出塞》)之意。关于“新鬼旧鬼”的描写，则是当时常用的一种表现手段，跟杜甫同期的散文家李华在《吊古战场文》中也有类似的写法，如“此古战场也，常覆三军，往往鬼哭，天阴则闻”“魂魄结兮天沉沉，鬼神聚兮云”“天地为愁，草木凄悲，吊祭不至，精魂何依”等。', poem_tags = '唐诗三百首,叙事,战争,忧国忧民' WHERE poem_title = '兵车行' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '这一年十月十五日，我从雪堂出发，准备回临皋亭。有两位客人跟随着我，一起走过黄泥坂。这时霜露已经降下，叶全都脱落。我们的身影倒映在地上，抬头望见明月高悬。四下里瞧瞧，心里十分快乐；于是一面走一面吟诗，相互酬答。\n\n　　过了一会儿，我叹惜地说：“有客人却没有酒，有酒却没有菜。月色皎洁，清风吹拂，这样美好的夜晚，我们怎么度过呢？”一位客人说：“今天傍晚，我撒网捕到了鱼，大嘴巴，细鳞片，形状就像吴淞江的鲈鱼。不过，到哪里去弄到酒呢？”我回家和妻子商量，妻子说：“我有一斗酒，保藏了很久，为了应付您突然的需要。”\n\n　　就这样，我们携带着酒和鱼，再次到赤壁的下面游览。长江的流水发出声响，陡峭的江岸高峻直耸；山峦很高，月亮显得小了，水位降低，礁石露了出来。才相隔多少日子，上次游览所见的江景山色再也认不出来了！我就撩起衣襟上岸，踏着险峻的山岩，拨开纷乱的野草；蹲在虎豹形状的怪石上，又不时拉住形如虬龙的树枝，攀上猛禽做窝的悬崖，下望水神冯夷的深宫。两位客人都不能跟着我到这个极高处。我大声地长啸，草木被震动，高山与我共鸣，深谷响起了回声，大风刮起，波浪汹涌。我也觉得忧愁悲哀，感到恐惧而静默屏息，觉得这里令人畏惧，不可久留。回到船上，把船划到江心，任凭它漂流到哪里就在那里停泊。这时快到半夜，望望四周，觉得冷清寂寞得很。正好有一只鹤，横穿江面从东边飞来，翅膀像车轮一样大小，尾部的黑羽如同黑裙子，身上的白羽如同洁白的衣衫，它戛戛地拉长声音叫着，擦过我们的船向西飞去。\n\n　　过了会儿，客人离开了，我也回家睡觉。梦见一位道士，穿着羽毛编织成的衣裳，轻快地走来，走过临皋亭的下面，向我拱手作揖说：“赤壁的游览快乐吗？”我问他的姓名，他低头不回答。“噢！哎呀！我知道你的底细了。昨天夜晚，边飞边叫着从我这里经过的人，不是你吗？”道士回头笑了起来，我也忽然惊醒。开门一看，却看不到他在什么地方。', poem_notes = '步自雪堂：从雪堂步行出发。雪堂，苏轼在黄州所建的新居，离他在临皋的住处不远，在黄冈东面。堂在大雪时建成，画雪景于四壁，故名“雪堂”。\n临皋（gāo）：亭名，在黄冈南长江边上。苏轼初到黄州时住在定惠院，不久就迁至临皋亭。\n黄泥之坂（bǎn）：黄冈东面东坡附近的山坡叫“黄泥坂”。坂，斜坡，山坡。文言文为调整音节，有时在一个名词中增“之”字，如欧阳修的《昼锦堂记》：“乃作昼锦之堂于后圃。”\n木叶：树叶。木，本来是木本植物的总名，“乔木”“灌木”的“木”都是用的这个意思。后来多用“木”称“木材”，而用本义是“树立”的“树”作木本植物的总名。\n行歌相答：边行边吟诗，互相唱和；且走且唱，互相酬答。\n已而：过了一会儿。\n如此良夜何：怎样度过这个美好的夜晚呢？如……何，怎样对待…… “如何”跟“奈何”差不多，都有“对待”“对付”的意思。\n今者薄暮：方才傍晚的时候。薄暮，太阳将落天快黑的时候。薄，迫，逼近。\n淞江之鲈（lú）：鲈鱼是松江（现在属上海）的名产，体扁，嘴大，鳞细，味鲜美，松小所产的鲈鱼。这是有名的美味。\n顾安所得酒乎：但是从哪儿能弄到酒呢？顾，但是，可是。安所，何所，哪里。\n谋诸妇：谋之于妻，找妻子想办法。诸，相当于“之于”。\n斗：古代盛酒的器具。\n不时之须：随时的需要。“须”通“需”。\n复游于赤壁之下：这是泛舟而游。下文“摄衣而上”是舍舟登陆，“反而登舟”是回到船上。\n断岸千尺：江岸上山壁峭立，高达千尺。断，阻断，有“齐”的意思，这里形容山壁峭立的样子。\n曾日月之几何，而江山不可复识矣：才过了几天啊，（眼前的江山明知是先前的江山，）而先前的景象再不能辨认了。这话是联系前次赤壁之游说的。前次游赤壁在“七月既望”，距离这次仅仅三个月，时间很短，所以说“曾日月之几何”。前次所见的是“水光接天”，“万顷茫然”，这次所见的是“断岸千尺”“水落石出”，所以说“江山不可复识”。曾，才，刚刚。这样用的“曾”常放在疑问句的句首。“曾日月之几何”，也就是“曾几何时”。\n摄衣：提起衣襟.摄，牵曳。\n履巉（chán）岩：登上险峻的山崖。履，践，踏。巉岩，险峻的山石。\n披蒙茸：分开乱草。蒙茸，杂乱的丛草。\n踞：蹲或坐。虎豹，指形似虎豹的山石。\n虬龙：指枝柯弯曲形似虬龙的树木。虬，龙的一种。登虬龙是说游于树林之间。\n栖鹘（hú）：睡在树上的鹘。栖，鸟宿。鹘，意为隼，鹰的一种。\n俯冯（píng）夷之幽宫：低头看水神冯夷的深宫。冯夷，水神。幽，深。“攀栖鹘之危巢，俯冯夷之幽宫”，这只是说，上登山的极高处，下临江的极深处。\n划然长啸：高声长啸。划有“裂”的意思，这里形容长啸的声音。啸，蹙口作声。\n亦：这个“亦”字是承接上文“二客不能从”说的。上文说，游到奇险处二客不能从；这里说，及至自己发声长啸，也感到悲恐，再不能停留在山上了。\n悄然：静默的样子。\n肃然：因恐惧而收敛的样子。\n留：停留。\n反：同“返”。返回。\n放：纵，遣。这里有任船飘荡的意思。\n听其所止而休焉：任凭那船停止在什么地方就在什么地方休息。\n四顾寂寥：向四外望去，寂寞空虚。\n横江东来：横穿大江上空从东飞来。\n玄裳缟衣：下服是黑的，上衣是白的。玄，黑。裳，下服。缟，白。衣，上衣。仙鹤身上的羽毛是白的，尾巴是黑的，所以这样说。\n戛然：形容鹤雕一类的鸟高声叫唤的声音。如白居易《画雕赞》“轩然将飞，戛然欲鸣。”\n掠：擦过。\n须臾客去，予亦就睡：这时的作者与客已经舍舟登岸，客去而作者就寝于室内，看下文的“开户”便明。\n羽衣翩仙：穿着羽衣（道士穿的用鸟羽制成的衣服），轻快地走着。翩仙，一作“蹁跹”。\n揖予：向我拱手施礼。\n俛：同“俯”，低头。\n呜呼噫嘻：这四个字都是叹词，也可以呜呼，噫，嘻分开用，或者呜呼，噫嘻分开用。\n畴昔之夜：昨天晚上。此语出于《礼记·檀弓》上篇“予畴昔之夜”。畴，语首助词，没有实在的意思。昔，昨。\n过我：从我这里经过。\n非子也耶：不是你吗？“也”在这里不表示意义，只起辅助语气的作用。\n顾：回头看。\n寤：觉，醒。', poem_appreciation = '前虽都以秋江夜月为景，以客为陪衬，但后赤壁赋重在游、状景，而前赤壁赋意在借景抒怀，阐发哲理。本文第一段，作者在月明风清之夜，与客行歌相答。先有“有客无酒”、“有酒无肴”之憾，后有“携酒与鱼”而游之乐。行文在平缓舒展中有曲折起伏。第二段，从“江流有声，断岸千尺”的江岸夜景，写到“履巉岩，披蒙茸……”的山崖险情；从“曾日月之几何而江水不可复识”的感叹，到“悄然而悲，肃然而恐”的心情变化，极腾挪跌宕之姿。第三段，借孤鹤道士的梦幻之境，表现旷然豁达的胸怀和慕仙出世的思想。\n\n　　《赤壁赋》分前后两篇，珠联璧合，浑然一体。文章通过同—地点(赤壁)，同一方式(月夜泛舟饮酒)，同—题材(大江高山清风明月)，反映了不同的时令季节，描绘了不同的大自然景色，抒发了不同的情趣，表达了不同的主题。字字如画，句句似诗，诗画合一，情景交融，真是同工异曲，各有千秋。\n\n　　《后赤壁赋》是《前赤壁赋》的续篇，也可以说是姐妹篇。前赋主要是谈玄说理，后赋却是以叙事写景为主；前赋描写的是初秋的江上夜景，后赋则主要写江岸上的活动，时间也移至孟冬；两篇文章均以“赋“这种文体写记游散文，一样的赤壁景色，境界却不相同，然而又都具诗情画意。前赋是“清风徐来，水波不兴“、“白露横江，水光接天 “，后赋则是“江流有声，断岸千尺，山高月小，水落石出“。不同季节的山水特征，在苏轼笔下都得到了生动、逼真的反映，都给人以壮阔而自然的美的享受。\n\n　　全文分为三个层次，第一层次写泛游之前的活动，包括交待泛游时间、行程、同行者以及为泛游所作的准备。写初冬月夜之景与踏月之乐，既隐伏着游兴，又很自然地引出了主客对话。面对着“月白风清“的“如此良夜“，又有良朋、佳肴与美酒，再游赤壁已势在必行，不多的几行文字，又写了景，又叙了事，又抒了情，三者融为一体，至此已可转入正文，可东坡却“节外生枝“地又插进“归而谋诸妇“几句，不仅给文章增添生活气息，而且使整段“铺垫“文字更呈异采。\n\n　　第二层次乃是全文重心，纯粹写景的文字只有“江流有声“四句，却写出赤壁的崖峭山高而空清月小、水溅流缓而石出有声的初冬独特夜景，从而诱发了主客弃舟登岸攀崖游山的雅兴，这里，作者不吝笔墨地写出了赤壁夜游的意境，安谧清幽、山川寒寂、“履巉岩，披蒙茸，踞虎豹，登虬龙；攀西鹊之危巢，俯冯夷之幽宫“，奇异惊险的景物更令人心胸开阔、境界高远。可是，当苏轼独自一人临绝顶时，那“划然长啸，草木震动，山鸣谷应，风起水涌“的场景又不能不使他产生凄清之情、忧惧之心，不得不返回舟中。文章写到这里，又突起神来之笔，写了一只孤鹤的“横江东来“\'、“戛然长鸣“后擦舟西去，于是，已经孤寂的作者更添悲悯，文章再起跌宕生姿的波澜，还为下文写梦埋下了伏笔。\n\n　　最后，在结束全文的第三层，写了游后入睡的苏子在梦乡中见到了曾经化作孤鹤的道士，在“揖予 “、“不答“、“顾笑“的神秘幻觉中，表露了作者本人出世入世思想矛盾所带来的内心苦闷。政治上屡屡失意的苏轼很想从山水之乐中寻求超脱，结果非但无济于事，反而给他心灵深处的创伤又添上新的哀痛。南柯一梦后又回到了令人压抑的现实。结尾八个字“开户视之，不见其处“相当迷茫，但还有双关的含义，表面上像是梦中的道士倏然不见了，更深的内涵却是“苏子的前途、理想、追求、抱负又在哪里呢?\n\n　　文中写苏子独自登山的情景，真是“句句如画、字字似诗“，通过夸张与渲染，使人有身临其境之感。文中描写江山胜景，色泽鲜明，带有作者个人真挚的感情。巧用排比与对仗，又增添了文字的音乐感。读起来更增一分情趣。但总的来说，后赋无论在思想上和艺术上都不及前赋。神秘色彩，消沉情绪与“赋“味较淡、“文“气稍浓恐怕是逊色于前篇的主要原因。\n\n　　《后赤壁赋》作于苏轼因“乌台诗案“而被贬至黄州之时，贬谪生涯使苏轼更深刻地理解了社会和人生，也使他的创作更深刻地表现出内心的情感波澜。《后赤壁赋》沿用了赋体主客问答、抑客伸主的传统格局，抒发了自己的人生哲学，同时也描写了长江月夜的优美景色。全文骈散并用，情景兼备，堪称优美的散文诗。不仅让我们感到了作者高超的表达能力和语言技巧，文中的孤鹤形象更能够让我们感到超然物外的人生哲理。孤独、寂寞、高贵、幽雅、超凡脱俗的孤鹤历来便是道家的神物。乘鹤是道化升仙的标 志，苏轼不仅借孤鹤以表达自己那种高贵幽雅、超凡脱俗、自由自在的心境，更表现了那种超越现实的痛苦遗世的精神。那我们就看看他在《后赤壁赋》中是如何将孤鹤的孤独、寂寞、高贵、幽雅、超凡脱俗展现得淋漓尽致的。山石高峻怪异，既是对立、压迫着他的自然力量，又象征了他积郁难消的苦闷之情。鹤则是这一苦闷孤独情感的意象。歇于松柏，不作稻粮谋的孤鹤在苏轼心中，就像在其他隐逸 者的意中一样，本是高蹈于世外的象征。苏轼曾作《放鹤亭记》，以放鹤招鹤、与鹤共处来渲染内心弃世的幽情，孤鹤的形象尤其为他所钟爱。此际在苏轼最感孤独时，忽然有一东来的孤鹤振翅横江而掠过小舟西去。这只在暗夜独飞，独鸣的鹤是孤独的，它可以蔚藉同样感受状态中的苏子之心。因此与客不交一言的苏子对它注意极深。而且它不仅是苏子此际情怀的象征，也是七月之夜的道士形象新化。苏轼以“畴昔之夜，飞鸣而过我者，非子也耶”的觉悟，联想前来入梦的道士，表明作者在这只孤鹤身上寄予了自己怀念故友之情。而道士的思想，原是苏子思想中的一个侧面，苏子--孤鹤--道士的联结，暗示着苏轼在精神上已归向高蹈于世外的隐逸者。“开户视之，不见其处”结尾处写自己梦醒后开门寻找，夜色茫茫，不见孤鹤，也并无道士。一笔双关，余味深长。将苦闷与希望糅合在诗化境界中。山形与鹤形，使苏轼因自然的变化和人事的不谙的精神不适感，和在孤独中向往自由的念头找到了对应。通观全文，在我们的眼前自然就展现出了好一幅“水月禅境、山鹤幽鸣”的美景图！', poem_tags = '古文观止,纪游,山水,写景,抒情,人生,哲理' WHERE poem_title = '后赤壁赋' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '汴水长流，泗水长流，流到长江古老的渡口，遥望去，江南的群山在默默点头，频频含羞，凝聚着无限哀愁。\n思念呀，怨恨呀，哪儿是尽头，伊人呀，除非你归来才会罢休。一轮皓月当空照，让我俩紧紧偎傍，倚楼望月。', poem_notes = '汴水：源于河南，东南流入安徽宿县、泗县，与泗水合流，入淮河。\n泗水：源于山东曲阜，经徐州后，与汴水合流入淮河。\n瓜州：在今江苏省扬州市南面。\n吴山：泛指江南群山。\n悠悠：深长的意思。', poem_appreciation = '这首词是抒发“闺怨”的名篇，构思比较新颖奇巧。它写一个闺中少妇，月夜倚楼眺望，思念久别未归的丈夫，充满无限深情。词作采用画龙点睛之笔，最后才点出主人公的身份，突出作品的主题思想，因而给读者留下强烈的悬念。\n\n　　上片全是写景，暗寓恋情。前三句以流水比人，写少妇丈夫外出，随着汴水、泗水向东南行，到了遥远的地方；同时也暗喻少妇的心亦随着流水而追随丈夫的行踪飘然远去。第四句“吴山点点愁”才用拟人化的手法，婉转地表现少妇思念丈夫的愁苦。前三句是陈述句，写得比较隐晦，含而不露如若不细细体会，只能看到汴水、泗水远远流去的表面意思，而看不到更深的诗意，这就辜负了作者的苦心。汴水发源于河南，古汴水一支自开封东流至今徐州，汇入泗水，与运河相通，经江苏扬州南面的瓜州渡口而流入长江，向更远的地方流去。这三首是借景抒情，寓有情于无情之中，使用的是暗喻和象征的手法。“吴山点点愁”一句，承“瓜洲古渡”而入吴地，而及吴山，写得清雅而沉重，是上片中的佳句。“吴山点点”是写景，在这里，作者只轻轻一带，着力于頙的“愁”字。著此“愁”字，就陡然使意发生了巨大的变化：吴山之秀色不复存在，只见人之愁如山之多且重，这是一；山亦因人之愁而愁，这是二；山是愁山，则上文之水也是恨水了，这是三。一个字点醒全片，是其笔力堪称强劲。\n\n　　下片直抒胸臆，表达少妇对丈夫长期不归的怨恨。前三句写她思随流水，身在妆楼，念远人而不得见，思无穷，恨亦无穷。“悠悠”二字，意接流水，笔入人情。“恨到归时方始休”一句，与《长恨歌》之“天长地久有时尽，此恨绵绵无绝期”，各擅胜场。《长恨歌》写死别，故恨无绝期；此词写生离，故归即无恨。“恨到归时方始休”，句意拙直，不假藻饰，然而深刻有味，情真意真。末句“月明人倚楼”，是画景也是情语。五字包拢全词，从而知道以上的想水想山，含思含恨，都是人于明月下、倚楼时的心事；剪影式的画幅，又见出她茫茫然远望驰思，人仍未归，恨亦难休，几乎要化为山头望夫石也。', poem_tags = '宋词三百首,婉约,山水,女子,相思' WHERE poem_title = '长相思·汴水流' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '夜间在亭台上踱着步子，不知道为何清明刚过，便已经感觉到了春天逝去的气息。夜里飘来零零落落的几点雨滴，月亮在云朵的环绕下，散发着朦胧的光泽。\n桃花、杏花在暗夜的空气中散发着幽香，不知道在园内荡着秋千，轻声说笑的女子是谁？对她千万般思念，在辽阔的天地里，竟无一处可以安排“我”的相思愁绪。', poem_notes = '蝶恋花，词牌名，分上下两阕，共六十个字，一般用来填写多愁善感和缠绵悱恻的内容。此词于《唐宋诸贤绝妙词选》、《类编草堂诗余》、《词的》、《古今诗余醉》等本中均有题作“春暮”。\n遥夜：长夜。亭皋：水边的平地。《汉书·司马相如传上》：“亭皋千里，靡不被筑。”闲：吴本《二主词》误作“闭”。信：吴讷本、吕远本、侯文灿本《南唐二主词》作“倒”。王仲闻《南唐二主词校订》云：“倒步不可解，必信步之误。”刘继增《南唐二主词笺》云：“旧钞本作信。”\n风约住：下了几点雨又停住，就象雨被风管束住似的。\n杏：《尊前集》、《唐宋诸贤绝妙词选》、《类编草堂诗余》、《词的》、《古今词统》作“杏”。《欧阳文忠近体乐府》注：“一作杏。”依依：《欧阳文忠公近体乐府》、《醉翁琴趣外篇》、《乐府雅词》、《花庵词选》、《类编草堂诗余》、《唐宋诸贤绝妙词选》、毛订《草堂诗余》、《词的》、《古今词统》均作“依稀”。《欧阳文忠近体乐府》罗泌校语云：“一作无言。”暗度：不知不觉中过去。春暗度：《尊前集》作“风暗度”。《欧阳文忠近体乐府》、《花庵词选》、《醉翁琴趣外篇》、《乐府雅词》、《唐宋诸贤绝妙词选》、《类编草堂诗余》、《词的》、《古今词统》、《古今诗余醉》、《历代诗余》、《全唐诗》作“香暗度”。\n谁：《乐府雅词》作“谁”。《欧阳文忠公近体乐府》罗泌校语云：“谁，一作人。”在：《欧阳文忠公近体乐府》、《醉翁琴趣外篇》、《乐府雅词》作“上”。《欧阳文忠公近体乐府》注：“一作在。”\n一寸：指心，喻其小。绪：连绵不断的情丝。“千万绪”有千丝万缕的意思。\n安排：安置，安放。', poem_tags = '婉约,闺怨,思念' WHERE poem_title = '蝶恋花·春暮' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '清明节夜晚时，清风习习，月夜朦胧，用碧玉做成的栏杆和用红色的砖砌成的墙是刺史的府宅。\n独自步行在回旋的走廊中唱歌，远远的听到弦声，默默的欣赏花。', poem_notes = '清明夜：清明节的夜晚。清明，二十四节气之一，在阳历四月五日前后。旧俗当天有扫墓、踏青、插柳等活动。\n砌（qì）：台阶。\n独：独自。\n回廊：回旋的走廊。\n遥：遥远，远远。\n看花：赏花。', poem_tags = '清明节,踏青' WHERE poem_title = '清明夜' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '汉文帝求贤，宣示召见被贬臣子。贾谊才能，确实高明无人能及。\n只是空谈半夜，令人扼腕叹息。文帝尽问鬼神之事，只字不提国事民生。', poem_notes = '贾生：指贾谊（前200—前168），西汉著名的政论家、文学家，力主改革弊政，提出了许多重要政治主张，但却遭谗被贬，一生抑郁不得志。\n宣室：汉代长安城中未央宫前殿的正室。逐臣：被放逐之臣，指贾谊曾被贬谪。\n才调：才华气质。\n可怜：可惜，可叹。虚：徒然，空自。前席：在坐席上移膝靠近对方。\n苍生：百姓。问鬼神：事见《史记·屈原贾生列传》。汉文帝接见贾谊，“问鬼神之本。贾生因具道所以然之状。至夜半，文帝前席。”', poem_appreciation = '这是一首托古讽时诗，意在借贾谊的遭遇，抒写诗人怀才不遇的感慨。诗选取汉文帝宣室召见贾谊，夜半倾谈的情节，写文帝不能识贤，任贤；“不问苍生问鬼神”却揭露了晚唐皇帝服药求仙，荒于政事，不能任贤，不顾民生的昏庸特性。诗寓慨于讽，讽刺效果颇好。\n\n　　此诗是首咏叹贾生故事的短诗，其着眼点，不在个人的穷通得失，而在于指出封建统治者不能真正重视人才，使其在政治上发挥作用。\n\n　　贾谊贬长沙，久已成为诗人们抒写不遇之感的熟滥题材。作者独辟蹊径，特意选取贾谊自长沙召回，宣室夜对的情节作为诗材。《史记。屈贾列传》载：贾生征见。孝文帝方受厘（刚举行过祭祀，接受神的福佑），坐宣室（未央宫前殿正室）。上因感鬼神事，而问鬼神之本。贾生因具道所以然之状。至夜半，文帝前席（在坐席上移膝靠近对方）。既罢，曰：“吾久不见贾生，自以为过之，今不及也。”\n\n　　在一般封建文人心目中，这大概是值得大加渲染的君臣遇合盛事。但诗人却独具只眼，抓住不为人们所注意的“问鬼神”之事，翻出了一段新警透辟、发人深省的诗的议论。\n\n　　“宣室求贤访逐臣，贾生才调更无伦。”前幅纯从正面着笔，丝毫不露贬意。首句特标“求”、“访”（咨询），仿佛热烈颂扬文帝求贤意愿之切、之殷，待贤态度之诚、之谦，所谓求贤若渴，虚怀若谷。“求贤”而至“访逐臣”，更可见其网罗贤才已达到“野无遗贤”的程度。次句隐括文帝对贾谊的推服赞叹之词。“才调”，兼包才能风调，与“更无伦”的赞叹配合，令人宛见贾生少年才俊、议论风发、华采照人的精神风貌，诗的形象感和咏叹的情调也就自然地显示出来。这两句，由“求”而“访”而赞，层层递进，表现了文帝对贾生的推服器重。如果不看下文，几乎会误认为这是一篇圣主求贤颂。其实，这正是作者故弄狡狯之处。\n\n　　第三句承、转交错，是全诗枢纽。承，即所谓“夜半前席”，把文帝当时那种虚心垂询、凝神倾听、以至于“不自知膝之前于席”的情状描绘得维妙维肖，使历史陈迹变成了充满生活气息、鲜明可触的画面。这种善于选取典型细节，善于“从小物寄慨”的艺术手段，正是李商隐咏史诗的绝招。通过这个生动的细节的渲染，才把由“求”而“访”而赞的那架“重贤”的云梯升到了最高处；而“转”，也就在这戏剧高潮中同时开始。不过，它并不露筋突骨，硬转逆折，而是用咏叹之笔轻轻拨转——在“夜半虚前席”前加上可怜两字。可怜，即可惜。不用感情色彩强烈的“可悲”、“可叹”一类词语，只说“可怜”，一方面是为末句——一篇之警策预留地步；另一方面也是因为在这里貌似轻描淡写的“可怜”，比剑拔弩张的“可悲”、“可叹”更为含蕴，更耐人寻味。仿佛给文帝留有余地，其实却隐含着冷隽的嘲讽，可谓似轻而实重。“虚”者，空自、徒然之谓。虽只轻轻一点，却使读者对文帝“夜半前席”的重贤姿态从根本上产生了怀疑，可谓举重而若轻。如此推重贤者，何以竟然成“虚”？诗人引而不发，给读者留下了悬念，诗也就显出跌宕波折的情致，而不是一泻无余。这一句承转交错的艺术处理，精炼，自然，和谐，浑然无迹。\n\n　　末句方引满而发，紧承“可怜”与“虚”，射出直中鹄的的一箭——不问苍生问鬼神。郑重求贤，虚心垂询，推重叹服，乃至“夜半前席”，不是为了询求治国安民之道，却是为了“问鬼神”的本原问题！这究竟是什么样的求贤，对贤者又究竟意味着什么啊！诗人仍只点破而不说尽——通过“问”与“不问”的对照，让读者自己对此得出应有的结论。辞锋极犀利，讽刺极辛辣，感概极深沉，却又极抑扬吞吐之妙。由于前几句围绕“重贤”逐步升级，节节上扬，第三句又盘马弯弓，引而不发，末句由强烈对照而形成的贬抑便显得特别有力。这正是通常所谓的“抬得高，摔得重”（也就是反跌手法）。整首诗在正反、扬抑、轻重、隐显、承转等方面的艺术处理上，都蕴含着艺术的辩证法，而其新警含蕴、唱叹有情的艺术风格也就通过这一系列成功的艺术处理，逐步显示出来。\n\n　　点破而不说尽，有论而无断，并非由于内容贫弱而故弄玄虚，而是由于含蕴丰富，片言不足以尽意。诗有讽有慨，寓慨于讽，旨意并不单纯。从讽的方面看，表面上似刺文帝，实际上诗人的主要用意并不在此。晚唐许多皇帝，大都崇佛媚道，服药求仙，不顾民生，不任贤才，诗人矛头所指，显然是当时现实中那些“不问苍生问鬼神”的封建统治者。在寓讽时主的同时，诗中又寓有诗人自己怀才不遇的深沉感慨。诗人夙怀“欲回天地”的壮志，但偏遭衰世，沉沦下僚，诗中每发“贾生年少虚垂涕”、“贾生兼事鬼”之慨。这首诗中的贾谊，正有诗人自己的影子。概而言之，讽汉文实刺唐帝，怜贾生实亦自悯。', poem_tags = '唐诗三百首,托古讽今,怀才不遇' WHERE poem_title = '贾生' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '世上人们对花和叶的说法不同，把花栽在美观的金盆中，却不管花叶让它落在土里变为尘土。\n只有荷花是红花绿叶相配，荷叶有卷有舒，荷花有开有合，衬托得那样完美自然。\n荷花与荷叶长期互相交映，当荷叶掉落，荷花凋谢之时，是多么令人惋惜啊。', poem_notes = '不相伦：不相比较。意谓世人皆重花而轻叶。伦：同等，同类。\n金盆：铜制的盆。供注水盥洗之用。\n绿荷红菡萏（hàn dàn）：绿荷是指碧绿的荷叶。菡萏是指未开的荷花。《诗经·山有扶苏》之“隰有荷华”，刘桢《公宴》诗：“芙蓉散其华，菡萏溢金塘。”\n卷舒：形容荷叶的姿态。卷，卷缩。舒，伸展。开合：形容荷花的姿态。开，开放。合，合拢。\n天真：天然本性、不加雕饰的本来样子。冯延巳《忆江南》词之一：“玉人贪睡坠钗云，粉消妆薄见天真。”\n翠减红衰：翠者为叶，红者为花，翠减红衰言花叶凋零。翠：指荷叶。红：指荷花。\n愁杀（shà）人：令人愁苦至极。', poem_appreciation = '诗一开头，并没有直接从荷花本身着笔，而是先从其他花卉的花与叶的关系写起：“世间花叶不相伦，花入金盆叶作尘。”“伦”，比并之意，世上的人对待花和叶是不一样的，二者不能相提并论。人们对花特别偏爱，把它栽在金盆中以供观赏，又倍加爱护，而花叶则听任它“零落成泥碾作尘”（陆游《卜算子·咏梅》）。同时，其他花卉的花与叶的关系也并不密切。如杏即先花而后叶，花开而叶未放，叶生而花凋落。桃花那么鲜艳，但其叶也不与之般配，须得绿柳相映才更显其美，故有“桃红柳绿”之称。“红花虽好，还须绿叶扶持”。这种花叶相映之关是其他花卉不易具备的，只有荷花以此见长，所以诗人接下去便写道：“惟有绿荷红菡萏，卷舒开合任天真。”《尔雅·释草》： “荷，芙蕖，其叶葭，其华菡萏， 《毛诗笺》云： ‘芙蕖之茎曰荷。”’《说文解字》；“荷未发为菡萏，已发为夫容（芙蓉）。”“惟有”，只有。这是诗人特别强调之语。“卷舒”指荷叶，“开合”指荷花，“任天真”即自然天成。在诗人眼中，只有荷花红苞绿叶相配，完美无缺。荷叶之卷舒，荷花之开合，相互映衬，自然而然，美丽无比。\n\n　　开头这四句，诗人是别具匠心的：他写的不仅仅是花与叶的关系问题，而是有深意的。字面上这是一种对比，即拿荷花与其他花卉对比，突出荷花花叶相配、交相辉映的特殊美，更深一层的意思则是在表明他自己与女方是天造地设的一对，有如荷花的花与叶，可堪匹配，是天赐良缘。这样，在诗人的笔下，他自己与对方的情事便被描绘、渲染得十分美妙，又如此自然、和谐。 诗的最后两句，既写出了诗人的期望，也写出了诗人的隐忧：“此荷此叶常相映，翠减红衰愁杀人。”首句是希望，明里是说但愿这美丽的荷花与那碧绿的荷叶长久共存、相互映衬、形影不离，实际的意思是期望女方同自己长相厮守，永不分离，白头到老。后句是忧虑，字面上是忧虑荷叶减翠，红花衰落，那时看起来太让人伤感了。而实际上的意思则是一方面担心时不我与。双方年老色衰。但愿青春常驻；但更深一层，则是担心两人的感情“变色”，出现意外的变故，如果出现那种情况，实在是不堪忍受的，简直是愁死人了。所以，这是诗人在向情人表白心志，希望两人都珍视爱情，永不变心。\n\n　　这首诗明里句句都是写花。但实际上句句都是写人。借荷花表明自己的心曲。既说明自己与女方可堪匹配。是天生的一对儿；又表明了两人相配之美满；又表明了自己的心愿与忧虑。委婉含蓄，耐人寻味，在众多的咏物诗中实属上乘之作。', poem_tags = '赞美,荷花' WHERE poem_title = '赠荷花' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '三年为抗清兵东走西飘荡，今天兵败被俘作囚入牢房。\n无限美好河山失陷伤痛泪，谁还敢说天庭宽阔地又广。\n已经知道黄泉之路相逼近，想到永别故乡实在心犯难。\n鬼雄魂魄等到归来那一日，灵旗下面要将故乡河山看。', poem_notes = '1.云间：上海松江区古称云间，是作者家乡。1647年（永历元年/顺治四年），他在这里被逮捕。\n2.三年：作者自1645年（弘光元年/顺治二年）起，参加抗清斗争，出入于太湖及其周围地区，至1647年（顺治四年），共三年。\n3.羁旅：寄居他乡，生活飘泊不定。羁：音（jī），停留。\n4.南冠（guān），被囚禁的人。语出《左传》。楚人钟仪被俘，晋侯见他戴着楚国的帽子，问左右的人：“南冠而絷（zhi，拴、捆）者，谁也？”后世以“南冠”代被俘。\n5.泉路：黄泉路，死路。泉，黄泉，置人死后埋葬的地穴。\n6.毅魄，坚强不屈的魂魄，语出屈原《九歌.国殇》：“身即死兮神以灵，魂魄毅兮为鬼雄。”。\n7.灵旗，又叫魂幡，古代招引亡魂的旗子。这里指后继者的队伍。', poem_appreciation = '这首诀别故乡之作，表达的不是对生命苦短的感慨，而是对山河沦丧的极度悲愤，对家乡亲人的无限依恋和对抗清斗争的坚定信念。\n\n　　诗作首联叙事。其中“羁旅”一词将诗人从父允彝、师陈子龙起兵抗清到身落敌手这三年辗转飘零、艰苦卓绝的抗清斗争生活作了高度简洁的概括。诗人起笔自叙抗清斗争经历，似乎平静出之，然细细咀嚼，自可读出诗人激越翻滚的情感波澜，自可读出平静的叙事之中深含着诗人满腔辛酸与无限沉痛。\n\n　　颔联抒写诗人按捺不住的满腔悲愤。身落敌手被囚禁的结局，使诗人恢复壮志难酬，复国理想终成泡影，于是诗人悲愤了：“无限河山泪，谁言天地宽？”大明江山支离破碎，满目疮痍，衰颓破败，面对这一切，诗人禁不住“立尽黄昏泪几行”，流不尽“无限河山泪”。诗人一直冀盼明王朝东山再起，可最终时运不济，命途多舛，恢复故土、重整河山的爱国宏愿一次次落空，他禁不住深深地失望与哀恸，忍不住向上苍发出“谁言天地宽”的质问与诘责。\n\n　　颈联坦露对故乡、亲人的依恋不舍之情。无论怎样失望、悲愤与哀恸，诗人终究对自己的人生结局非常清醒：“已知泉路近”。生命行将终结，诗人该会想些什么呢？“欲别故乡难”，诗人缘何难别故乡呢？原来，涌上他心头的不仅有国恨，更兼有家仇。父起义兵败，为国捐躯了。而自己是家中唯一的男孩，此次身落敌手，自是凶多吉少，难免一死，这样，家运不幸，恐无后嗣。念及自己长年奔波在外，未能尽孝于母，致使嫡母“托迹于空门”，生母“寄生于别姓”，自己一家“生不得相依，死不得相问”，念及让新婚妻子在家孤守两年，自己未能尽为夫之责任与义务，妻子是否已有身孕尚不得而知。想起这一切的一切，诗人内心自然涌起对家人深深的愧疚与无限依恋。\n\n　　尾联盟恢复之志。尽管故乡牵魂难别，但诗人终将恢复大志放在儿女私情之上，不以家运后嗣为念，最终表明心迹：“毅魄归来日，灵旗空际看。”正如诗人在《狱中上母书》中所表示的“二十年后，淳且与先文忠为北塞之举矣”。“已知泉路近”的诗人坦然作出“毅魄归来日”的打算，抱定誓死不屈、坚决复明的决心，生前未能完成大业，死后也要亲自看到后继者率部起义，恢复大明江山。诗作以落地有声的铮铮誓言作结，鲜明地昭示出诗人坚贞不屈的战斗精神、精忠报国的赤子情怀，给后继者以深情的勉励，给读者树立起一座国家与民族利益高于一切的不朽丰碑。\n\n　　全诗思路流畅清晰，感情跌宕豪壮。起笔叙艰苦卓绝的飘零生涯，承笔发故土沦丧、山河破碎之悲愤慨叹，转笔抒眷念故土、怀恋亲人之深情，结笔盟誓志恢复之决心。诗作格调慷慨豪壮，令人读来荡气回肠，禁不住对这位富有强烈民族意识的少年英雄充满深深的敬意。\n\n　　这首诀别故乡之作，表达的不是对生命苦短的感慨，而是对山河沦丧的极度悲愤，对家乡亲人的无限依恋和对抗清斗争的坚定信念。', poem_tags = '古诗三百首,初中古诗,离别,悲愤,爱国' WHERE poem_title = '别云间' AND poem_author = '夏完淳';
UPDATE edu_poem SET poem_tags = '边塞,饮酒,思乡' WHERE poem_title = '凉州词二首' AND poem_author = '王翰';
UPDATE edu_poem SET poem_translation = '以往在生活上的困顿与思想上的局促不安再不值得一提了，今朝金榜题名，郁结的闷气已如风吹云散，心上真有说不尽的畅快，真想拥抱一下这大自然。策马奔驰于春花烂漫的长安道上，今日的马蹄格外轻盈，不知不觉中早已把长安的繁荣花朵看完了。', poem_notes = '龌龊：指处境不如意和思想上的拘谨局促。\n放荡：自由自在，无所拘束。', poem_tags = '喜悦,早教古诗100首' WHERE poem_title = '登科后' AND poem_author = '孟郊';
UPDATE edu_poem SET poem_translation = '人生在世没有根蒂，飘泊如路上的尘土。\n生命随风飘转，此身历尽了艰难，已经不是原来的样子了。\n世人都应当视同兄弟，何必亲生的同胞弟兄才能相亲呢？\n遇到高兴的事就应当作乐，有酒就要邀请近邻共饮。\n青春一旦过去便不可能重来，一天之中永远看不到第二次日出。\n应当趁年富力强之时勉励自己，光阴流逝，并不等待人。', poem_notes = '蒂（dì）：瓜当、果鼻、花与枝茎相连处都叫蒂。陌：东西的路，这里泛指路。\n此：指此身。非常身：不是经久不变的身，即不再是盛年壮年之身。\n落地：刚生下来。\n斗：酒器。比邻：近邻。\n盛年：壮年。　\n及时：趁盛年之时。', poem_appreciation = '陶渊明《杂诗》共有十二首，此为第一首。王瑶先生认为前八首“辞气一贯”，当作于同一年内。据其六“奈何五十年，忽已亲此事”句意，证知作于公元414年（晋安帝义熙十年），时陶渊明五十岁，距其辞官归田已有八年。\n\n　　这组《杂诗》，实即“不拘流例，遇物即言”（《文选》李善注）的杂感诗。正如明黄文焕《陶诗析义》卷四所云：“十二首中愁叹万端，第八首专叹贫困，余则慨叹老大，屡复不休，悲愤等于《楚辞》。”可以说，慨叹人生之无常，感喟生命之短暂，是这组《杂诗》的基调。\n\n　　这种关于“人生无常”“生命短暂”的叹喟，是在《诗经》《楚辞》中即已能听到的，但只是到了汉末魏晋时代，这种悲伤才在更深更广的程度上扩展开来，从《古诗十九首》到“三曹”，从“竹林七贤”到“二陆”，从刘琨到陶渊明，这种叹喟变得越发凄凉悲怆，越发深厚沉重，以至成为整个时代的典型音调。这种音调，在今天看来不无消极悲观的意味，但在当时特定的社会条件下，却反映了人的觉醒，是时代的进步。\n\n　　“人生无根蒂”四句意本《古诗十九首》之“人生寄一世，奄忽若飘尘”，感叹人生之无常。蒂，即花果与枝茎相连接的部分。人生在世即如无根之木、无蒂之花，没有着落，没有根柢，又好比是大路上随风飘转的尘土。由于命运变幻莫测，人生飘泊不定，种种遭遇和变故不断地改变着人，每一个人都已不再是最初的自我了。这四句诗，语虽寻常，却寓奇崛，将人生比作无根之木、无蒂之花，是为一喻，再比作陌上尘，又是一喻，比中之比，象外之象，直把诗人深刻的人生体验写了出来，透露出至为沉痛的悲怆。陶渊明虽然“少无适俗韵”，怀有“猛志逸四海，骞翮思远翥”的宏大抱负，但他生值晋宋易代前后，政治黑暗，战乱频仍，国无宁日，民不聊生。迫于生计，他几度出仕，几度退隐，生活在矛盾痛苦之中，终于在四十一岁时辞职归田，不再出仕。如此世态，如此经历，使他对人生感到渺茫，不可把握。虽然在他的隐逸诗文中，读者可以感受到他的旷达超然之志，平和冲淡之情，但在他的内心深处，蕴藏着的是一种理想破灭的失落，一种人生如幻的绝望。\n\n　　“落地为兄弟，何必骨肉亲。”承前而来，既然每个人都已不是最初的自我，那又何必在乎骨肉之亲、血缘之情呢。来到这个世界上的都应该成为兄弟。这一层意思出自《论语》：“子夏曰：‘君子敬而无失，与人恭而有礼。四海之内，皆兄弟也。君子何患乎无兄弟也？”这也是陶渊明在战乱年代对和平、泛爱的一种理想渴求。“得欢当作乐，斗酒聚比邻。”阅历的丰富往往使人对人生的悲剧性有更深刻的认识，年龄的增长常常使人更难以寻得生活中的欢乐和激动，处于政治黑暗时期的陶渊明更是如此，这在他的诗中表露得非常明确：“荏苒岁月颓，此心稍已去。值欢无复娱，每每多忧虑。”（《杂诗》其五）但他毕竟没有完全放弃美好的人生理想，他转向官场宦海之外的自然去寻求美，转向仕途荣利之外的村居生活去寻求精神上的欢乐，这种欢乐平淡冲和、明净淳朴。“斗酒聚比邻”正是这种陶渊明式的欢乐的写照，在陶渊明的诗中时有这种场景的描述，如：“过门更相呼，有酒斟酌之。”（《移居》）“日入相与归，壶浆劳近邻。”（《癸卯岁始春怀古田舍》）这是陶渊明式的及时行乐，与“昼短苦夜长，何不秉烛游”；“不如饮美酒，被服纨与素”；“何不策高足，先据要路津”（《古诗十九首》）有着明显的差异，体现了更高的精神境界。\n\n　　“盛年不重来”四句常被人们引用来勉励年轻人要抓紧时机，珍惜光阴，努力学习，奋发上进。在今天，一般读者若对此四句诗作此理解，也未尝不可。但陶渊明的本意却与此大相径庭，是鼓励人们要及时行乐。既然生命是这么短促，人生是这么不可把握，社会是这么黑暗，欢乐是这么不易寻得，那么，对生活中偶尔还能寻得的一点点欢乐，不要错过，要及时抓住它，尽情享受。这种及时行乐的思想，必须放在当时特定的历史条件下加以考察，“它实质上标志着一种人的觉醒，即在怀疑和否定旧有传统标准和信仰价值的条件下，人对自己生命、意义、命运的重新发现、思索、把握和追求。陶渊明在自然中发现了纯净的美，在村居生活中找到了质朴的人际关系，在田园劳动中得到了自我价值的实现。\n\n　　这首诗起笔即命运之不可把握发出慨叹，读来使人感到迷惘、沉痛。继而稍稍振起，诗人执著地在生活中寻找着友爱，寻找着欢乐，给人一线希望。终篇慷慨激越，使人为之感奋。全诗用语朴实无华，取譬平常，质如璞玉，然而内蕴却极丰富，波澜跌宕，发人深省。', poem_tags = '古诗三百首,感叹,人生,惜时' WHERE poem_title = '杂诗' AND poem_author = '陶渊明';
UPDATE edu_poem SET poem_translation = '燕地小草像碧丝般青绿，秦地的桑树已叶翠枝绿。\n当你怀念家园盼归之日，早就思念你而愁肠百结。\n春风啊你与我素不相识，为何吹进罗帐激我愁思？', poem_notes = '燕草：指燕地的草。燕，河北省北部一带，此泛指北部边地，征夫所在之处。\n秦桑：秦地的桑树。秦，指陕西省一带，此指思妇所在之地。燕地寒冷，草木迟生于较暖的秦地。\n君：指征夫。怀归：想家。\n妾：古代妇女自称。此处为思妇自指。\n罗帏：丝织的帘帐。', poem_appreciation = '李白有很多描写思妇心理的诗篇，《春思》是其中之一。中国古典诗歌中的“春”字通常语意双关：既指春天，又可以用来比喻男女之爱。此诗《春思》中的“春”就包含有这两方面的意思。此诗以相隔遥远的燕秦两地春天景物起兴，别具一格。思妇触景生情，想起了远方的丈夫，颇为伤怀。她申斥春风，正是明志自警，恰到好处。\n\n　　开头两句：“燕草如碧丝，秦桑低绿枝”，可以视作“兴”。诗中的兴句一般是就眼前所见，信手拈起，这两句却以相隔遥远的燕、秦两地的春天景物起兴，颇为别致。“燕草如碧丝”，当是出于思妇的悬想；“秦桑低绿枝”，才是思妇所目睹。把目力达不到的远景和眼前近景配置在一幅画面上，并且都从思妇一边写出，从逻辑上说，似乎有点乖碍，但从“写情”的角度来看，却是可通的。试想：仲春时节，桑叶繁茂，独处秦地的思妇触景生情，终日盼望在燕地行役屯戍的丈夫早日归来；她根据自己平素与丈夫的恩爱相处和对丈夫的深切了解，料想远在燕地的丈夫此刻见到碧丝般的春草，也必然会萌生思归的念头。见春草而思归，语出《楚辞·招隐士》：“王孙游兮不归，春草生兮萋萋！”首句化用《楚辞》语，浑成自然，不着痕迹。诗人巧妙地把握了思妇复杂的感情活动，用两处春光，兴两地相思，把想象与怀忆同眼前真景融合起来，据实构虚，造成诗的妙境。所以不仅起到了一般兴句所能起的烘托感情气氛的作用，而且还把思妇对于丈夫的真挚感情和他们夫妻之间心心相印的亲密关系传写出来了，这是一般的兴句所不易做到的。另外，这两句还运用了谐声双关。“丝”谐“思”，“枝”谐“知”，这恰和下文思归与“断肠”相关合，增强了诗句的音乐美与含蓄美。\n\n　　三四两句直承兴句的理路而来，故仍从两地着笔：“当君怀归日，是妾断肠时。”丈夫及春怀归，足慰离人愁肠。按理说，诗中的女主人公应该感到欣喜才是，而下句竟以“断肠”承之，这又似乎违背了一般人的心理，但如果联系上面的兴句细细体会，就会发现，这样写对表现思妇的感情又进了一层。元代萧士赟对此诗评述揭示了兴句与所咏之词之间的微妙的关系。诗中看似于理不合之处，正是感情最为浓密所在。\n\n　　旧时俗话说：“见多情易厌，见少情易变。”这首诗中的女主人公的可贵之处在于阔别而情愈深，迹疏而心不移。诗的最后两句是：“春风不相识，何事入罗帏？”诗人捕捉了思妇在春风吹入闺房，掀动罗帐的一霎那的心理活动，表现了她忠于所爱、坚贞不二的高尚情操。从艺术上说，这两句让多情的思妇对着无情的春风发话，又仿佛是无理的，但用来表现独守春闺的特定环境中的思妇的情态，又令人感到真实可信。春风撩人，春思缠绵，申斥春风，正所以明志自警。以此作结，恰到好处。\n\n　　无理而妙是古典诗歌中一个常见的艺术特征。从李白的这首诗中不难看出，所谓无理而妙，就是指在看似违背常理、常情的描写中，反而更深刻地表现了各种复杂的感情。', poem_tags = '唐诗三百首,春天,妇女,坚贞,思念' WHERE poem_title = '春思' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '庄子和惠子一起在濠水的桥上游玩。庄子说：“鯈鱼在河水中游得多么悠闲自得，这是鱼的快乐啊。”惠子说：“你又不是鱼，哪里知道鱼是快乐的呢？”庄子说：“你又不是我，怎么知道我不知道鱼儿是快乐的呢？”惠子说：“我不是你，固然就不知道你（的想法）；你本来就不是鱼，你不知道鱼的快乐，这是可以完全确定的。”庄子说：“让我们回到最初的话题，你开始问我‘你哪里知道鱼儿的快乐’的话，就说明你很清楚我知道，所以才来问我是从哪里知道的。现在我告诉你，我是在濠水的桥上知道的。”', poem_notes = '濠梁：濠水的桥上。濠,水名，在现在安徽凤阳。\n从容：悠闲自得。\n鯈（tiáo）鱼：一种淡水鱼中的银白色小鱼，喜欢在水层下面游动，长约16厘米，又名白鲦。\n是：这。\n固：固然（固不知子矣）；本来（子固非鱼也）。\n全：完全，确定是。\n循其本：从最初的话题说起。循：顺着。其，话题。本：最初。\n子曰‘汝安知鱼乐’云者：你说“汝安知鱼乐”等等。汝安知鱼乐：你怎么（哪里）知道鱼是快乐的呢。云者：如此如此。安，怎么；哪里。\n安;疑问代词.怎么,哪里', poem_appreciation = '该文节选自《秋水》。\n\n　　《秋水》是《庄子》中的又一长篇，用篇首的两个字作为篇名，中心是讨论人应怎样去认识外物。全篇由两大部分组成。前一部分写北海海神跟河神的谈话，一问一答一气呵成，构成本篇的主体。后一部分分别写了六个寓言故事，每个寓言故事自成一体，各不关联，跟前一部分海神与河神的对话也没有任何结构关系上的联系，对全篇主题的表达帮助也不甚大，似有游离之嫌。\n\n　　《庄子与惠子游于濠梁》轻松闲适，诗意盎然。一力辩，一巧辩；一求真，一尚美；一拘泥，一超然；让人读后会心一笑而沉思良久。\n\n　　惠子好辩，重分析。对于事物有一种寻根究底的认知态度，重在知识的探讨；庄子智辩，重观赏。对外界的认识带有欣赏的态度，将主观的情意发挥到外物上而产生移情同感的作用。如果说惠子带有逻辑家的个性，那么庄子则具有艺术家的风貌。', poem_tags = '初中文言文,认知' WHERE poem_title = '庄子与惠子游于濠梁' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '回乐峰前的沙地白得像雪，受降城外的月色有如秋霜。\n不知何处吹起凄凉的芦管，一夜间征人个个眺望故乡。', poem_notes = '受降城：唐初名将张仁愿为了防御突厥，在黄河以北筑受降城，分东、中、西三城，都在今内蒙古自治区境内。另有一种说法是：公元646年（贞观二十年），唐太宗亲临灵州接受突厥一部的投降,“受降城”之名即由此而来。\n回乐峰：唐代有回乐县，灵州治所，在今宁夏回族自治区灵武县西南。回乐峰即当地山峰。一作“回乐烽”：指回乐县附近的烽火台。\n城下：一作“城上”，一作“城外”。\n芦管：笛子。一作“芦笛”。\n征人：戍边的将士。尽：全。', poem_appreciation = '这是一首抒写戍边将士乡情的诗作，从多角度描绘了戍边将士（包括吹笛人）浓烈的乡思和满心的哀愁之情。\n\n　　诗歌的前两句描写了一幅边塞月夜的独特景色.举目远眺，蜿蜒数十里的丘陵上耸立着座座高大的烽火台，烽火台下是一片无垠的沙漠，在月光的映照下如同积雪的荒原。近看，高城之外月光皎洁，如同深秋的寒霜。沙漠并非雪原，诗人偏说它“似雪”，月光并非秋霜，诗人偏说它“如霜”。诗人如此运笔，是为了借这寒气袭人的景物来渲染心境的愁惨凄凉。正是这似雪的沙漠和如霜的月光使受降城之夜显得格外空寂惨淡。也使诗人格外强烈地感受到置身边塞绝域的孤独，而生发出思乡情愫。\n\n　　如果说前两句写景，景中寓情，蓄而未发；那么后两句则正面写情。在万籁俱寂中，夜风送来呜呜咽咽的芦笛声。这笛声使诗人想到：是哪座烽火台上的戍卒在借芦笛声倾诉那无尽的边愁？那幽怨的笛声又触动了多少征人的思乡愁？在这漫长的边塞之夜，他们一个个披衣而起，忧郁的目光掠过似雪的沙漠，如霜的月地，久久凝视着远方······“不知何处”，写出了诗人月夜闻笛时的迷惘心情，映衬出夜景的空寥寂寞。“一夜”和“尽望”又道出征人望乡之情的深重和急切。\n\n　　从全诗来看，前两句写的是色，第三句写的是声；末句抒心中所感，写的是情。前三句都是为末句直接抒情作烘托、铺垫。开头由视觉形象引动绵绵乡情，进而由听觉形象把乡思的暗流引向滔滔的感情的洪波。前三句已经蓄势有余，末句一般就用直抒写出。李益却蹊径独辟，让满孕之情在结尾处打个回旋，用拟想中的征人望乡的镜头加以表现，使人感到句绝而意不绝，在戛然而止处仍然漾开一个又一个涟漪。这首诗艺术上的成功，就在于把诗中的景色、声音、感情三者融合为一体，将诗情、画意与音乐美熔于一炉，组成了一个完整的艺术整体，意境浑成，简洁空灵，而又具有含蕴不尽的特点。\n\n　　这首诗语言优美，节奏平缓，寓情于景，以景写情，写出了征人眼前之景，心中之情，感人肺腑。诗意婉曲深远，让人回味无穷。刘禹锡《和令孤相公言怀寄河中杨少尹》中提到李益，有“边月空悲芦管秋”句，即指此诗。可见此诗在当时已传诵很广。《唐诗纪事》说这首诗在当时便被度曲入画。仔细体味全诗意境，的确也是谱歌作画的佳品。因而被谱入弦管，天下传唱，成为中唐绝句中出色的名篇之一。', poem_tags = '唐诗三百首,冬天,月亮,边塞,思念,战争' WHERE poem_title = '夜上受降城闻笛' AND poem_author = '李益';
UPDATE edu_poem SET poem_translation = '因为要去河梁谋生，所以把帷帐撩起，依依不舍要向年迈的母亲辞别，看到白发苍苍的老母不由泪下不停，眼泪也流干了。\n在这风雪之夜，不能在母亲身边尽孝却要掩柴门凄惨地远去，不禁令人兴叹：养子又有何用呢？倒不如没有啊。', poem_notes = '搴（qiān）帷（wéi）：掀起门帘，出门。\n河梁：桥，替代送别地。\n枯（kū）：干涸。\n惨惨：幽暗无光。\n柴门：树枝编的门，替代贫苦人家。', poem_tags = '古诗三百首,母亲' WHERE poem_title = '别老母' AND poem_author = '黄景仁';
UPDATE edu_poem SET poem_translation = '五月的天山仍是满山飘雪，只有凛冽的寒气，根本看不见花草。\n只有在笛声《折杨柳》曲中才能想象到春光，而现实中从来就没有见过春天。\n战士们白天在金鼓声中与敌人进行殊死的战斗，晚上却是抱着马鞍睡觉。\n但愿腰间悬挂的宝剑，能够早日平定边疆，为国立功。', poem_notes = '天山：指祁连山。\n折柳：即《折杨柳》，古乐曲名。\n金鼓：指锣，进军时击鼓，退军时鸣金。', poem_appreciation = '首句言“五月天山雪”，已经扣紧题目。五月，在内地正值盛夏。韩愈说“五月榴花照眼明，枝间时见子初成”，赵嘏说“和如春色净如秋，五月商山是胜游”。但是，李白所写五月却在塞下，在天山，自然，所见所感也就迥然有别。天山孤拔，常年被积雪覆盖。这种内地与塞下在同一季节的景物上的巨大反差，被诗人敏锐地捕捉，然而，他没有具体细致地进行客观描写，而以轻淡之笔徐徐道出自己内心的感受：“无花只有寒”。“寒”字，隐约透露出诗人心绪的波动，何况寒风之中又传来《折杨柳》的凄凉曲调呢！春天在边疆是看不到的，人们只能从笛曲之中去领受，去回味。《折杨柳》为乐府横吹曲，多写行客的愁苦。在这里，诗人写“闻折柳”，当亦包含着一层苍凉寒苦的情调。他是借听笛来渲染烘托这种气氛的。诗为五律，依惯例当于第二联作意思上的承转，但是李白却就首联顺势而下，不肯把苍凉情绪稍作收敛，这就突破了格律诗的羁绊，以气脉直行，豪纵不拘，语淡而雄浑为其特色了。\n\n　　“晓战随金鼓，宵眠抱玉鞍。”古代出征要敲击钲、鼓，用来节制士卒进退，五、六两句，写的正是这种情况。语意转折，已由苍凉变为雄壮。诗人设想：自己来到边塞，就在天山脚下，整日过着紧张的战斗生活。白天在钲、鼓声中行军作战，晚上就抱着马鞍子打盹儿。这里，“晓战”与“宵眠”相对应，当是作者有意在概括军中一日的生活，其军情之紧张急迫，跃然纸上。“随”字，摹状士卒的令行禁止。“抱”字，描绘士卒夜间警备的情况。二句写的是士卒的生活场景，而他们守边备战，人人奋勇，争为功先的心态则亦尽情流露出来。\n\n　　“愿将腰下剑，直为斩楼兰。”斩楼兰：据《汉书·傅介子传》：“汉代地处西域的楼兰国经常杀死汉朝使节，傅介子出使西域，楼兰王贪他所献金帛，被他诱至帐中杀死，遂持王首而还”。这里是借用傅介子慷慨复仇的故事，表现诗人甘愿赴身疆场，为国杀敌的雄心壮志。“直”与“愿”字呼应，语气斩截强烈，一派心声，喷涌而出，自有夺人心魄的艺术感召力。', poem_tags = '边塞,写雪,军旅,生活' WHERE poem_title = '塞下曲六首·其一' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '柳絮杨花随风飘到哪里去了呢？原来是被厚厚的冰雪摧残了。五更时分夜阑风寒，这株柳树也显得凄冷萧疏。皎洁的明月无私普照，不论柳树是繁茂还是萧疏，都一般关怀。\n最是在繁茂的柳丝摇落的时候，我更免不了回忆起当年的那个女子。梦里又见当年和她幽会的情景，但是好梦易断，断梦难续。遂将愁思寄给西风，可是，再强劲的西风也吹不散我眉间紧锁的不尽忧愁。', poem_notes = '临江仙：双调小令，唐教坊曲。《乐章集》入“仙吕调”，《张子野词》入“高平调”。\n层冰：厚厚之冰。\n憔悴：瘦弱无力脸色难看的样子：颜色憔悴，形容枯槁。\n关：这里是关切、关怀之意。\n最是：特别是。\n繁丝：指柳丝的繁茂。这两句里的“柳丝”和“春山”，都暗喻女子的眉毛。\n春山：春日之山。又，春山山色如黛，故借喻女子之眉毛，或代指女子。这里指代亡妻。\n湔（jiān）裙梦断：意思是涉水相会的梦断了。湔裙，溅湿了衣裙。\n西风：从西方吹来的风。', poem_appreciation = '这是一首咏物词，咏的是寒柳。\n\n　　“飞絮飞花何处是”，咏柳咏柳，开门见山：柳絮呀，随风飘到哪里去了呢？花儿呀，随风飘到哪里去了呢？——咦，说柳絮自然应该，毕竟是咏柳，可这个”花儿”是从哪里出来的呢？谁见过柳树开花呢？\n\n　　明明是咏柳，怎么突然出来个扬花呢？正确的答案是：杨花和柳絮其实都是一回事，都是柳树上飘飞的那种一团一团的白色绒毛，现在还是很常见的。\n\n　　柳絮为什么又叫杨花呢？这是子从父姓，因为柳树有个别名叫“杨柳”。\n\n　　“飞絮飞花何处是”，其实就是“飞絮何处是”，但这里特别用了“飞花”的意象，除了造成叠音的声音效果之外，还因为杨花作为诗词当中的一个意象符号，独有一些复杂的含义。\n\n　　杨花是一个飘零无助的意象。传说，杨花如果飘落到水中，就会化为浮萍。这个传说细想一下是非常凄凉的，因为杨花本身就是飘零无根之物，好容易在水里落了脚，却又化为浮萍，依然是个飘零无根之物。“飘零无根”至此便有了一种宿命的悲剧感。\n\n　　看，柳絮（杨花），其命运即便终于能摆脱飘泊无根，也只是沦落泥泞而已，益发可悲。——当然，这都只是附着在柳絮（杨花）之上的文学意象，如果从科学角度说，柳絮其实是柳树的种子，被绒毛包裹着随风飘飞，找地方去生根发芽、孕育新生去了。\n\n　　“飞絮飞花何处是，层冰积雪摧残”，容若发问柳絮飘飞生涯的命运归属，自问自答说“层冰积雪摧残”，意思是和“已作沾泥絮”差不多的，只是，“层冰积雪”也是个由来有自的文学符号，在字面意思之外还有其特定的所指。\n\n　　“层冰积雪”，语出《楚辞·招魂》：“层冰峨峨，积雪千里”，如果联系一下《招魂》的上下文，意义就更加明确了：\n\n　　魂兮归来，北方不可以止些。\n\n　　层冰峨峨，积雪千里些。\n\n　　归来归来，不可以久兮。\n\n　　魂兮归来，君无上天些。\n\n　　那么，如果把“飞絮飞花何处是”与“层冰积雪摧残”在《招魂》上下文的背景里联系起来，就会读出新的一层意思：柳絮离开了柳树的怀抱，如同魂魄一般散漫地飞向极北极北的天堂，可那里太寒太冷了呀，为什么你不回来呢？——这时候再来联系一下词题的“寒柳”，咏的是“柳”，为的是“留”。这首词的主题至此而明朗，两个字悼亡。\n\n　　“疏疏一树五更寒”，“疏疏一树”正是寒柳的意象，而“五更寒”原本仅仅是一个时间的意象，此时交迭在一起，却把夜阑、更残、轻寒这些意象付诸于柳树身上，使柳树获得了人格化的色彩，使柳树更加顺理成章地成为词人的情感投射的客体。\n\n　　“爱他明月好，憔悴也相关”，递进一层，似在说明月无私，不论柳树是繁茂还是萧疏，都一般照耀，一般关怀。貌似在写明月，实则是容若自况：柳树就算“疏疏”，就算“憔悴”，也减不了自己一分一毫的喜爱；伊人就算永诀，也淡不去自己一分一毫的思念。\n\n　　“最是繁丝摇落后，转教人忆春山”，下片转折，由柳树而及女子，由当下而及回忆，是说：最是在柳丝摇落的时候，我更免不了去想起当年的那个女子。\n\n　　春山，作为诗词中一个常见的意象，既可以实指春色中的山峦，也可以比喻为女子的眉毛。宋词有“眉扫春山淡淡，眼裁秋水盈盈”，便是以春山喻眉，以秋水喻眼，而一“扫”一“裁”，是形容女子描眉画眼的可爱的梳妆动作。春山既然可以比喻为女子的蛾眉，便也可以用作女子的代称，容若这里便是此意。由柳叶的形态联想到蛾眉的妙曼，联想到心爱的女子，曾经的故事……\n\n　　接下来仍是追忆那位女子，即“湔裙梦断续应难”。\n\n　　湔jian，这里是洗的意思。旧日风俗，三月三日上巳节，女人们相约一同到水边洗衣，以为这样可以除掉晦气。上巳节和清明节隔得不远，所以穆修有诗说“改火清明度，湔衫上巳连”。这种户外聚众的日子往往提供给了男男女女们以堂而皇之地偷偷约会的机会。\n\n　　这首词，曾被那位对纳兰词评价不高的陈廷焯赞为纳兰词中的压卷之作，不知道容若听到了会不会高兴一些呢？无论如何，“爱他明月好，憔悴也相关”，”西风多少恨，吹不散眉弯”，都是性灵之句，非挚情挚性之奇男子无以得之。\n\n　　纳兰何以有此“憔悴也相关”，“西风多少恨”的伤感情调？清朝气数正旺盛，却有此醒人气的词人和词作，真是可悲可叹可钦啊！\n\n　　这首作品是纳兰集中得后人推誉最力的佳作之一，不但多种选集阑入，陈廷焯甚至作出“言之有物，几令人感激涕零”之“压卷之作”的崇高评价。“压卷”与否姑且不置论，“言之有物”则可以作点简单分析。\n\n　　咏物为古典诗词之大宗，而原其宗旨，“物”本是外壳，是媒介，抒情才是本质，是核心。所以咏物之作要求摹写神理而不能徒赋形体，同时还要不粘不离，保持一个恰好的分寸。以此绳衡这首小词，在“层冰积雪摧残”、“爱他明月好，憔悴也相关”等句刻画出那婀娜杨柳的“寒意”之外，词人更着重“摧残”、“憔悴”、“梦断”、“西风多少恨，吹不散眉弯”的情感的抒写，亦将他复杂凄咽的内心感受特别深曲又特别准确地传递出来。写寒柳而字里含情，弦外有音，此之谓“言之有物”。\n\n　　还要深思一层，“言之有物”之“物”究竟能否落实呢？有文章指出这首词借咏柳而寄寓对亡妻的哀思，实亦即悼亡之作。作为一种猜测容或可以，但作为学术研究，在本篇不能肯定作年在其妻逝世之后的情况下，则不可以武断地这样定论。如果说里面寄托有纳兰一贯婉转哀凉的身世之感，那也就足够了。', poem_tags = '婉约,咏物,柳树,抒情' WHERE poem_title = '临江仙·寒柳' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '辽阔的草原像被铺在地上一样，四处都是草地。晚风中隐约传来牧童断断续续悠扬的笛声。\n牧童放牧归来，在吃饱晚饭后的晚霞时分。他连蓑衣都没脱，就躺在草地上看天空中的圆月。', poem_notes = '牧童：放牛放羊的孩子。\n铺：铺开。\n横野：辽阔的原野。\n弄：逗弄，玩弄。\n饱饭：吃饱了饭。\n蓑衣：用草或棕毛编织成的，披在身上的防雨用具，用来遮风挡雨。\n卧月明：躺着观看明亮的月亮。', poem_appreciation = '首句“草铺横野六七里“描述了视觉上的感受，放眼望去，原野上草色葱茏。一个“铺”字，表现出草的茂盛和草原给人的那种平缓舒服的感觉。草场的宽阔无垠为牧童的出场铺垫了一个场景。\n\n　　第二句“笛弄晚风三四声。”描述了听觉上的感受，侧耳倾听，晚风中牧笛声声。一“弄”字，更显出了一种情趣，把风中笛声的时断时续、悠扬飘逸和牧童吹笛嬉戏的意味，传达出来了。笛声的悠扬悦耳，反映出晚归牧童劳作一天后的轻松闲适的心境。未见牧童，先闻其声，具有无限美好的想象空间。这里的“六七里”和“三四声”不是确指的数字，只是为了突出原野的宽阔和乡村傍晚的静寂。 　　第三句“归来饱饭黄昏后”，诗人笔锋一转，开始直接描写牧童，牧童吃饱了饭，已经是黄昏之后了。\n\n　　末句“不脱蓑衣卧月明”描写牧童休息的情景。把以地为床，以天为帐，饥来即食，困来即眠，无牵无挂，自由自在的牧童形象刻画得活灵活现。诗人没有描写牧童躺下做什么，牧童可能是想舒展下身子，也可能是欣赏月色。诗人似乎只把他之所见如实地写了下来，却有无限的想象空间。\n\n　　全诗展示了一幅鲜活的牧童晚归休憩图：原野、绿草、笛声、牧童、蓑衣和明月。诗中有景、有情，有人物、有声音，这生动的一幕，是由远及近出现在诗人的视野里的；写出了农家田园生活的恬静，也体现了牧童放牧生活的辛劳，是一首赞美劳动的短曲。草场、笛声、月夜、牧童，像一幅恬淡的水墨画，使读者的心灵感到安宁。\n\n　　《牧童》一诗，不仅让读者感到了“日出而作，日落而息”的生活的安然与恬静，也让读者感受到了牧童心灵的无羁无绊，自然放松。该诗反映了诗人心灵世界的一种追求，对远离喧嚣、安然自乐的生活状态的一种向往。诗中尽道牧童生活的闲逸与舒适。此诗委婉劝说钟傅趁早离开那尔虞我诈、角名竞利的官场，回归田园，过牧童那样无欲无求的生活。在此诗中，牧童即是以智者的化身出现为迷失在宦途中的钟傅指路，而其人未必真是牧童。本诗语言朴直清新，明白如话，表现出一种“由工入微，不犯痕迹”的精湛功夫。', poem_tags = '小学古诗,儿童' WHERE poem_title = '牧童' AND poem_author = '吕岩';
UPDATE edu_poem SET poem_translation = '春天的夜晚，即便是极短的时间也十分珍贵。花儿散发着丝丝缕缕的清香，月光在花下投射出朦胧的阴影。\n楼台深处，富贵人家还在轻歌曼舞，那轻轻的歌声和管乐声还不时地弥散于醉人的夜色中。夜已经很深了，挂着秋千的庭院已是一片寂静。', poem_notes = '春宵：春夜。\n一刻：刻，计时单位，古代用漏壶记时，一昼夜共分为一百刻。一刻，比喻时间短暂。\n花有清香：意思是花朵散发出清香。\n月有阴：指月光在花下投射出朦胧的阴影。\n歌管：歌声和管乐声。', poem_tags = '古诗三百首,写景,哲理,惜时' WHERE poem_title = '春宵' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '自古以来，骚人墨客都悲叹秋天萧条、凄凉、空旷。我却说秋天远远胜过春天。\n秋日天高气爽，晴空万里。一只仙鹤直冲云霄推开层云，也激发我的诗情飞向万里晴空。\n\n秋天了，山明水净，夜晚已经有霜；树叶由绿转为浇黄色，其中却有几棵树叶成红色，在浅黄色中格外显眼；\n登上高楼，四望清秋入骨；才不会象春色那样使人发狂。', poem_notes = '悲寂寥：悲叹萧条空寂。宋玉《九辩》有“悲哉，秋之为气也”、“寂寥兮，收潦而水清”等句。\n春朝：春初朝，朝，有早晨的意思，这里指的是刚开始。\n晴：一作“横”。排云：推开白云。排：推开，有冲破的意思。\n诗情：作诗的情绪、兴致。碧霄：青天。\n深红：指红叶。浅黄：指枯叶。\n入骨：犹刺骨。\n嗾：使唤狗。这里是“使”的意思。', poem_appreciation = '其一\n\n　　“自古逢秋悲寂寥”，诗人开篇，即以议论起笔，断然否定了前人悲秋的观念，表现出一种激越向上的诗情。首句即明确指出自古以来，人们每逢到了秋天就感叹秋天的寂寞萧索。“自古”和“逢”，极言悲秋的传统看法的时代久远和思路模式的顽固。接着一句用“我言”直抒胸臆，态度鲜明，说出的是诗人的自信，这种自信，尽管染上的，是一种不幸的色彩，然而，诗人阔大的胸襟却非凡地溶解了这种不幸。“秋日胜春朝”，用对比手法，热情赞美秋天，说秋天比那万物萌生，欣欣向荣的春天更胜过一筹，这是对自古以来那种悲秋的论调的有力否定。\n\n　　第三句选择了典型事物具体生动地勾勒了一幅壮美的画面。诗人抓住秋天“一鹤凌云”，这一别致的景观的描绘，展现的是秋高气爽，万里晴空，白云漂浮的开阔景象。那凌云的鹤，也载着诗人的诗情，一同遨游到了云霄。虽然，这鹤是孤独的，然而它所呈现出来的气势，却是非凡的。一个“排”字，所蕴涵的深意，尽在不言中了。也许，诗人是以“鹤”自喻，也许是诗人视“鹤”为不屈的化身。这里，有哲理的意蕴，也有艺术的魅力，发人深思，耐人吟咏。这幅画面是对“秋日胜春朝”的生动注脚。第四句紧接上句直接抒写自己的感受，看到这一壮美的情境作者心中那激荡澎湃的诗情勃发出来，也像白鹤凌空一样，直冲云霄了。字里行间作者那乐观的情怀，昂扬的斗志国安呼之欲出。如果说，上句侧重写秋的“形美”，那么这句则突出秋的“神韵”，使“秋日胜春朝”的观点表现得更鲜明，更有力度。\n\n　　“晴空一鹤排云上，便引诗情到碧霄”展现的，不仅仅是秋天的生机和素色，更多的是一种高扬的气概和高尚的情操。这样的诗，没有什么悲凉的气息，诗人随着自己的“诗情”，和想象驰骋于碧空之上。于是，鹤飞之冲霄，诗情之旷远，“实”和“虚”便融合在了一起，所获得的全然是一种励志冶情的美的感受。全诗气势雄浑，意境壮丽，融情、景、理于一炉，不仅仅表现出是秋天的生机和素色，更多的是一种高扬精神和开阔胸襟，唱出的那曲非同凡响的秋歌，留下的是一份难能可贵的精神财富。\n\n　　其二\n\n　　这两首《秋词》主题相同，但各写一面，既可独立成章，又是互为补充。其一赞秋气，其二咏秋色。气以励志，色以冶情。所以赞秋气以美志向高尚，咏秋色以颂情操清白。景随人移，色由情化。景色如容妆，见性情，显品德。春色以艳丽取悦，秋景以风骨见长。第二首的前二句写秋天景色，诗人只是如实地勾勒其本色，显示其特色，明净清白，有红有黄，略有色彩，流露出高雅闲淡的情韵，泠然如文质彬彬的君子风度，令人敬肃。谓予不信，试上高楼一望，便使人感到清澈入骨，思想澄净，心情肃然深沉，不会像那繁华浓艳的春色，教人轻浮若狂。末句用“春色嗾人狂”反比衬托出诗旨，点出全诗暗用拟人手法，生动形象，运用巧妙。\n\n　　总结\n\n　　这是两首抒发议论的即兴诗。诗人通过鲜明的艺术形象表达深刻的思想，既有哲理意蕴，也有艺术魅力，发人思索，耐人吟咏。刘禹锡这两首《秋词》所展现的不只是秋天的生气和素色，更有为理想而奋斗的英雄气概和高尚情操，获得深刻的美感和乐趣。', poem_tags = '秋天' WHERE poem_title = '秋词二首' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '龙舟竞赛为的是深切悲念屈原的千古奇冤，忠烈之魂一去千载哪里还能回还啊？\n国破身死现在还能有什么呢？唉！只留下千古绝唱之离骚在人世间了！', poem_notes = '竞渡：赛龙舟。\n讵（jù）：岂，表示反问。\n殒（yǔn ）：死亡。\n离骚：战国时楚人屈原的作品。关于篇名，司马迁在《史记·屈原列传》中解释为“离忧”；王逸在《楚辞章句》中解释为“别愁”；近人或解释为“牢骚”，或解释为“楚国曲名‘劳商’的异写”。关于写作年代，有人认为写于楚怀王当朝，诗人被疏远以后；也有人认为作于顷襄王当朝，诗人再放江南时。迄无定论。《离骚》是中国古代诗歌史上最长的一首浪漫主义的政治抒情诗。诗人从自叙身世、品德、理想写起，抒发了自己遭谗被害的苦闷与矛盾，斥责了楚王昏庸、群小猖獗与朝政日非，表现了诗人坚持“美政”理想，抨击黑暗现实，不与邪恶势力同流合污的斗争精神和至死不渝的爱国热情。诗中大量运用了古代神话传说，以想象和联想的方式构成了瑰丽奇特的幻想世界，又以神游幻想世界的方式表现了诗人对理想的热烈追求。诗中大量地运用了“香草美人”的比兴手法，将深刻的内容借助具体生动的艺术形象表现出来，极富艺术魅力。《离骚》具有深刻现实性的积极浪漫主义精神，对后世产生了深远的影响。', poem_tags = '端午节,竞渡,怀人,爱国' WHERE poem_title = '和端午' AND poem_author = '张耒';
UPDATE edu_poem SET poem_translation = '楚国有个渡江的人，他的剑从船中掉到水里。他急忙在船边上用剑在掉下剑的地方做了记号，说：“这是我的剑掉下去的地方。”船到目的地后停了下来，这个楚国人从他刻记号的地方跳到水里寻找剑。 船已经航行了，但是剑没有行进，像这样寻找剑，不是很糊涂吗！', poem_notes = '涉：过，渡。\n者：……的人，定语后置的标志。 \n其：他的，代词。\n自：从。\n坠：落。\n于：在，到。\n遽：急忙，立刻。\n契：用刀雕刻，刻。\n是：指示代词，这，这个，这儿，这样。\n吾：我的。\n之：主谓之间取消句子独立性。\n所从坠：从剑落下的地方。坠：落下\n其：他，代词。\n求：找，寻找。\n之：剑，代词。 \n矣：了。\n而：然而，表转折。\n若：像。\n此：这样。\n不亦惑乎：不是很糊涂吗？惑，愚蠢，糊涂。“不亦......乎”是一种委婉的反问句式。\n止：停止，指船停了下来。', poem_appreciation = '战国时，楚国有个人坐船渡江。船到江心，他一不小心，把随身携带的一把宝剑掉落江中。船上的人对此感到非常惋惜，但那楚国人似乎胸有成竹，马上掏出一把小刀，在船舷上刻上一个记号，并向大家说：“这是我宝剑落水的地方，所以我要刻上一个记号。”\n\n　　大家虽然都不理解他为什么这样做，但也不再去问他。\n\n　　船靠岸后那楚国人立即在船上刻记号的地方下水，去捞取掉落的宝剑。捞了半天，不见宝剑的影子。他觉得很奇怪，自言自语说：“我的宝剑不就是在这里掉下去吗？我还在这里刻了记号呢，怎么会找不到的呢？”\n\n　　至此，船上的人纷纷大笑起来，说：“船一直在行进，而你的宝剑却沉入了水底不动，你怎么找得到你的剑呢？”\n\n　　其实，剑掉落在江中后，船继续行驶，而宝剑却不会再移动。像他这样去找剑，真是太愚蠢可笑了。', poem_tags = '小学文言文,寓言,故事,哲理' WHERE poem_title = '刻舟求剑 / 楚人涉江' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '雨中传来鸡鸣，山村里依稀一两户人家。村路竹溪之上，一条板桥斜横。\n婆媳相唤，一起去选蚕种。只有那栀子花开，独自摇曳庭院中。', poem_notes = '竹溪：小溪旁长着翠竹。\n妇姑：嫂嫂和小姑。\n相唤：互相呼唤。\n浴蚕：古时候将蚕种浸在盐水中，用来选出优良的蚕种，成为浴蚕。\n闲着：农人忙着干活，没有人欣赏盛开的栀子花。\n中庭：庭院中间。\n栀子：常绿灌木，春夏开白花，很香。', poem_appreciation = '第一句中，“雨里鸡鸣一两家”。诗的开头就大有山村风味。这首先与“鸡鸣”有关，“鸡鸣桑树颠”乃村居特征之一。在雨天，晦明交替似的天色，会诱得“鸡鸣不已”。但倘若是平原大坝，村落一般不会很小，一鸡打鸣会引来群鸡合唱。山村就不同了，地形使得居民点分散，即使成村，人户也不会多。“鸡鸣一两家”，恰好写出山村的特殊风味。\n\n　　第二句中，“竹溪村路板桥斜”。如果说首句已显出山村之“幽”，那么，次句就由曲径通幽的过程描写，显出山居的“深”来，并让读者随诗句的向导，体验了山行的趣味。在霏霏小雨中沿着斗折蛇行的小路一边走，一边听那萧萧竹韵，潺潺溪声，该有多称心。不觉来到一座小桥跟前。这是木板搭成的“板桥”。山民尚简，溪沟不大，原不必张扬，而从美的角度看，这一座板桥设在竹溪村路间，这竹溪村路配上一座板桥，却是天然和谐的景致。\n\n　　第三句中，“雨过山村”四字，至此全都有了。诗人转而写到农事：“妇姑相唤浴蚕去”。“浴蚕”，指古时用盐水选蚕种。据《周礼》“禁原蚕”注引《蚕书》：“蚕为龙精，月值大火（二月）则浴其种。”于此可见这是在仲春时分。在这淳朴的山村里，妇姑相唤而行，显得多么亲切，作为同一家庭的成员，关系多么和睦，她们彼此招呼，似乎不肯落在他家之后。“相唤浴蚕”的时节，也必有“相唤牛耕”之事，只举一端，不难概见其余。那优美的雨景中添一对“妇姑”，似比着一双兄弟更有诗意。\n\n　　第四句中，田家少闲月，冒雨浴蚕，就把倍忙时节的农家气氛表现得更加够味。但诗人存心要锦上添花，挥洒妙笔写下最后一句：“闲着中庭栀子花”。事实上就是没有一个人“闲着”，但他偏不正面说，却要从背面、侧面落笔。用“闲”衬忙，通过栀子花之“闲”衬托人们都十分忙碌的情景.，兴味尤饶。同时诗人做入“栀子花”，又丰富饱满了诗意。雨浥栀子冉冉香，意象够美的。此外，须知此花一名“同心花”，诗中向来用作爱之象征，故少女少妇很喜采撷这种素色的花朵。此诗写栀子花无人采，主要在于表明春深农忙，似无关“同心”之意。但这恰从另一面说明，农忙时节没有谈情说爱的“闲”功夫，所以那花的这层意义便给忘记了。这含蓄不发的结尾，实在妙机横溢，摇曳生姿。前人曾这样来评论这首诗的末句：“心思之巧，词句之秀，最易启人聪颖”。\n\n　　全诗处处扣住山村景象，从景写到人，从人写到境；农事的繁忙，山村的神韵，皆蕴于一个“闲”字之中。它是全篇之“眼”，着此一字而境界全出。作者写雨过山村所见情景，富有诗情画意，又充满劳动生活的气息,同时也表达了一种对乡村生活的喜爱之情。', poem_tags = '山水,田园,写雨,生活' WHERE poem_title = '雨过山村' AND poem_author = '王建';
UPDATE edu_poem SET poem_translation = '在色彩华丽的灯光里，夫妻举办芳宴玩乐庆祝，精致的灯具下，年轻人显得更加光鲜艳丽。\n灯光绚丽的色彩遥遥看来好像分开了大地，繁多的灯火远远的点缀着天际。\n连接天河的灯光烟火好像是星星坠落下来，靠着高楼的灯似乎月亮悬挂空中。\n还有美丽女子的美好笑容映照在九枝的火光下。', poem_notes = '锦：色彩华丽，这里指色彩华丽的花灯，正月十五有放花灯的习俗。\n开芳宴：始于唐代的一种习俗，由夫妇中的男方主办，活动内容一般为夫妻对坐进行宴饮或赏乐观戏。宋罗烨《醉翁谈录》“常开芳宴，表夫妻相爱耳。”开，举行。\n兰缸：也作“兰釭”，是燃烧兰膏的灯具，也常用来表示精致的灯具。\n早年：年轻的时候，这里指年轻人。\n缛彩：也作“縟采”，绚丽的色彩。\n汉：天河，银河。《迢迢牵牛星》中有“皎皎河汉女”，即为银河中的织女星。\n依：靠着，依靠。《说文》依，倚也。\n千金笑：指美丽女子的笑。\n九枝：一干九枝的灯具，枝上放置蜡烛或加灯油，也泛指一干多枝的灯。', poem_tags = '节日,元宵节' WHERE poem_title = '十五夜观灯' AND poem_author = '卢照邻';
UPDATE edu_poem SET poem_translation = '远处舒展的树林烟雾漾潆，好像纺织物一般，秋寒的山色宛如衣带，触目伤心的碧绿。暮色进了高高的闺楼，有人正在楼上独自忧愁。\n玉石的台阶上，徒然侍立盼望。那回巢的鸟儿，在归心催促下急急飞翔。哪里是我返回的路程？过了长亭接着短亭。', poem_notes = '菩萨蛮，唐教坊曲名。又名《菩萨篁》、《重叠金》、《花间意》、《梅花句》等。《杜阳杂编》说：“大中初，女蛮国入贡，危髻金冠，璎珞被体，号为菩萨蛮，当时倡优遂制《菩萨蛮曲》，文士亦往往声其 词。”后来，《菩萨蛮》便成了词人用以填词的词牌。但据《教坊记》 载开元年间已有此曲名。到底孰是，今不可考。\n平林：平原上的林木。《诗·小雅·车舝》：“依彼平林，有集维鷮。” 毛 传：“平林，林木之在平地者也。”\n漠漠：迷蒙貌。烟如织：暮烟浓密。\n伤心：极甚之辞。愁苦、欢快均可言伤心。此处极言暮山之青。\n暝色：夜色。\n玉阶：玉砌的台阶。这里泛指华美洁净的台阶。\n伫（zhù）立：长时间地站着等候。谢眺《秋夜》诗：“夜夜空伫立。”\n归：一作“回”。\n长亭更短亭：古代设在路边供行人休歇的亭舍。庾信《哀江南赋》云：“十里五里，长亭短亭。”说明当时每隔十里设一长亭，五里设一短亭。亭，《释名》卷五：亭，停也，人所停集也。“更”一作“连”。', poem_appreciation = '这首词上下两片采用了不同的手法，上片偏于客观景物的渲染，下片着重主观心理的描绘。然而景物的渲染中却带有浓厚的主观色彩，主观心理的描绘又糅合在客观景物之中。因而从整体上来说，情与景、主观与客观，又融成一片。\n\n　　这首词选择的时间是一个暮色苍茫、烟云暖暧的黄昏，季节是秋冬之交。开头两句为远景，“平林漠漠烟如织”便传达出一种空寞惆怅的情绪，它起到笼罩全篇的作用。如烟如织，扯也扯不开，割也割不断。就连那远处碧绿的山色也使人着恼，叫人伤感。这似乎是静态的写生，是一种冷色的画面，但静态之中又夹杂着主观的感受，给人一种潜在的骚动感，撩人意绪。接着，这种骚动感由潜在到表面化了。“暝色”句为近景，用一“入”字由远而近，从全景式的平林远山拉到楼头思妇的特写镜头，突出了“有人楼上愁”的人物主体，层次井然，一个“入”字使整个画面波动起来，由远及近、由潜在到表面化。看起来是客观景物感染了其人，实际上是此人内心感受在不断深化。至“有人楼上愁”句，这个由客观到主观、由物到人的过渡完成了。这个“愁”字把整个上片惆怅空寞的情绪全部绾结在一起，同时又自然地过渡到下片。承上启下，臻于绝妙。\n\n　　下片立足于主观的感受上。在暮霭沉沉之中，主人公久久地站立在石阶前，感到的只是一片空茫。“空”也是上片所勾画的景物感染下的必然结果。主观情绪并不是孤立存在着的，它立刻又融入了景物之中——“宿鸟归飞急”。这一句插得很巧妙。作者用急飞的宿鸟与久立之人形成强烈的对照。一方面，南宿鸟急归反衬出人的落拓无依；另一方面，宿鸟急归无疑地使抒情主人公的内心骚动更加剧烈。于是，整个情绪波动起来。如果说上片的“愁”字还只是处于一种泛泛的心理感受状态，那么，现在那种朦胧泛泛的意识逐渐明朗化了。它是由宿鸟急归导发的。所以下面就自然道出了：“何处是归程?”主人公此刻也急于寻求自己的归宿，来挣脱无限的愁绪。可是归程在何处呢?只不过是“长亭连短亭”，并没有一个实在的答案。有的仍然是连绵不断的落拓、惆怅和空寞，在那十里五里、长亭短亭之间。征途上无数长亭短亭，不但说明归程遥远，同时也说明归期无望，以与过片“空伫立”之“空”字相应。如此日日空候，思妇的离愁也就永无穷尽了。结句不怨行人忘返，却愁道路几千，归程迢递，不露哀怨，语甚酝藉。韩元吉《念奴娇》词云，“尊前谁唱新词，平林真有恨，寒烟如织。”短短的一首词中，掇取了密集的景物：平林、烟霭、寒山、暝色、高楼、宿鸟、长亭、短亭，借此移情、寓情、传情，手法极为娴熟，展现了丰富而复杂的内心世界活动，反映了词人在客观现实中找不到人生归宿的无限落拓惆怅的愁绪。\n\n　　历来解说此词，虽然有不少论者认为它是眺远怀人之作，但更多的人却说它是羁旅行役者的思归之辞。后一种理解，大概是受了宋代文莹《湘山野录》所云“此词不知何人写在鼎州沧水驿楼”一语的影响。以为既然题于驿楼，自然是旅人在抒思归之情。其实，古代的驿站邮亭等公共场所以及庙宇名胜的墙壁上，有些诗词不一定是即景题咏，也不一定是写者自己的作品。细玩这首词，也不是第一称谓，而是第三称谓。有如电影，从“平林”、“寒山”的远镜头，拉到“高楼”的近景，复以“暝色”做特写镜头造成气氛，最终突出“有人楼上愁”的半身镜头。分明是第三者所控制、所描撰的场景变换。下片的歇拍两句，才以代言的方法，模拟出画中人的心境。而且词中的“高楼”、“玉阶”，也不是驿舍应有之景。驿舍邮亭，是不大会有高楼的，它的阶除也决不会“雕栏玉砌”，正如村舍茅店不能以“画栋雕梁”形容一样。同时，长亭、短亭，也不是望中之景；即使是“十里一长亭，五里一短亭”中的最近一座，也不是暮色苍茫中视野所能及。何况“长亭更短亭”，不知凡几，当然只能意想于心头，不能呈现于楼头人的眼底。', poem_tags = '宋词三百首,豪放,秋天,写景,怀人' WHERE poem_title = '菩萨蛮·平林漠漠烟如织' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '花草树木知道春天即将归去，都想留住春天的脚步，纷纷争奇斗艳。就连那没有美丽颜色的杨花和榆钱也不甘寂寞，随风起舞，化作漫天飞雪。', poem_notes = '不久归：将结束。\n杨花：指柳絮\n榆荚：亦称榆钱。榆未生叶时，先在枝间生荚，荚小，形如钱，荚花呈白色，随风飘落。\n才思：才华和能力。\n解（jie）：知道。', poem_appreciation = '这里，似乎只是用拟人化的手法描绘了晚春的繁丽景色，其实，它还寄寓着人们应该乘时而进，抓紧时机去创造有价值的东西这一层意思。但这里值得一提的是，榆荚杨花虽缺乏草木的“才思”，但不因此藏拙，而为晚春增添一景，虽然不美，但尽了努力，这种精神是值得赞扬了。\n\n　　这是一首描绘暮春景色的七绝。乍看来，只是写百卉千花争奇斗艳的常景，但进一步品味便不难发现，诗写得工巧奇特，别开生面。诗人不写百花稀落、暮春凋零，却写草木留春而呈万紫千红的动人情景：花草树木探得春将归去的消息，便各自施展出浑身解数，吐艳争芳，色彩缤纷，繁花似锦，就连那本来乏色少香的杨花、榆荚也不甘示弱，而化作雪花随风飞舞，加入了留春的行列。诗人体物入微，发前人未得之秘，反一般诗人晚春迟暮之感，摹花草灿烂之情状，展晚春满目之风采。寥寥几笔，便给人以满眼风光、耳目一新的印象。\n\n　　说这首诗平中翻新，颇富奇趣，还在于诗中拟人化手法的奇妙运用，糅人与花于一体。“草木”本属无情物，竟然能“知”能“解”还能“斗”，而且还有“才思”高下有无之分。想象之奇，实为诗中所罕见。末二句尤其耐人咀嚼，读者大可根据自己的生活体验进行毫无羁绊的大胆想象，使人思之无穷，味之不尽。\n\n　　再细加揣摩，此诗熔景与理于一炉。可以透过景物描写领悟出其中的人生哲理：诗人通过“草木”有“知”、惜春争艳的场景描写，反映的其实是自己对春天大好风光的珍惜之情。面对晚春景象，诗人一反常见的惜春伤感之情，变被动感受为主观参与，情绪乐观向上，很有新意。你看，“杨花榆荚”不因“无才思”而藏拙，不畏“班门弄斧”之讥，为“晚春”添色。这就给人以启示：一个人“无才思”并不可怕，要紧的是珍惜光阴，不失时机，“春光”是不负“杨花榆荚”这样的有心人的。\n\n　　钱钟联《集释》系此诗于元和十一年。注引朱彝尊《批韩诗》云：“此意作何解？然情景却是如此。“的确，仅就描写暮春景色而言，此诗可谓有情有趣，亦不落俗套。诗题又作《游城南晚春》，可知所写乃春游郊外所见。诗人全用拟人手法，不说人之惜春，而说草树亦知春将不久，因而百花争艳，各呈芳菲。凑热闹的还有朴素无华的杨花榆荚，像飞雪一般漫天遍野地飘舞。人言草木无情，诗偏说它们有知，或“斗“或“解“，活泼有趣。这是此诗明白有趣之处。\n\n　　然而“无才思“三字颇怪异，遂引起后人诸多猜测。或谓劝人勤学，不要像杨花那样白首无成；或谓隐喻人之无才，作不出好文章；或言有所讽喻；或言赞赏杨花虽无芳华，却有情趣和勇气。细审诗意，诗人当是赞赏杨花的。“无才思“应是故作顿挫的谐谑之笔。\n\n　　此诗之寓意，见仁见智，不同的人生阅历和心绪会有不同的领悟。', poem_tags = '春天,哲理' WHERE poem_title = '晚春二首·其一' AND poem_author = '韩愈';
UPDATE edu_poem SET poem_translation = '沧州的南面有一座寺庙靠近河岸，庙门倒塌在了河里，两只石兽一起沉没于此。经过十多年，僧人们募集金钱重修（寺庙），便在河中寻找石兽，最后也没找到。僧人们认为石兽顺着水流流到下游了。于是划着几只小船，拖着铁钯，（向下游）寻找了十多里，没有找到石兽的踪迹。\n\n　　一位讲学家在寺庙中教书，听说了这件事笑着说：“你们这些人不能推究事物的道理。这（石兽）不是木片，怎么能被暴涨的洪水带走呢?石头的性质坚硬沉重，泥沙的性质松软浮动，石兽埋没在沙上，越沉越深罢了。顺着河流寻找石兽，不是（显得）疯狂了吗?”大家信服地认为（这话）是精当确切的言论。\n\n　　一位老河兵听说了讲学家的观点，又笑着说：“凡是落入河中的石头，都应当在河的上游寻找它。正因为石头的性质坚硬沉重，沙的性质松软轻浮，水流不能冲走石头，水流反冲的力量，一定在石头下面迎水的地方侵蚀沙子形成坑洞。越激越深，当坑洞延伸到石头底部的一半时，石头必定倾倒在坑洞中。像这样再冲刷，石头又会再次转动，像这样不停地转动，于是反而逆流朝相反方向到上游去了。到河的下游寻找石兽，本来就（显得）很疯狂;在石兽沉没的地方寻找它们，不是（显得）更疯狂了吗?”结果依照他的话去（寻找），果然在上游的几里外寻到了石兽。\n\n　　既然这样，那么天下的事，只知道表面现象，不知道根本道理的情况有很多，难道可以根据某个道理就主观判断吗?', poem_notes = '沧州：地名，今河北省沧州市。\n临：靠近。也有“面对”之意。\n河干：河边。（河：指黄河，历史上黄河曾流经沧州。）干，水边，河岸。\n山门：寺庙的大门。\n圮：倒塌。\n并：一起。\n沉焉：沉没在这条河里。焉，兼词，于此，在那里。\n阅：过了，经过。\n十余岁：十多年。岁：年。\n棹：名词作动词，划船。\n求石兽于水中：在河中寻找石兽。求，寻找。\n竟：终于，到底。\n曳：拖着,牵引。\n铁钯：农具，用于除草平土。 钯，通“耙”。\n设帐：讲学，教书。\n尔辈不能究物理：你们这些人不能推究事物的道理。尔辈，你们。究，推究。物理，事物的道理规律。\n是非木杮：这不是木片。是，这。杮，削下的木片。\n岂能：怎么能。\n为：被。\n暴涨：洪水。暴，突然（急大）。\n湮：埋没。\n颠：通“癫”，疯狂。\n众服为确论：大家信服地认为（这话）是精当确切的言论。为：（认为）是。\n河兵：指镇守河防的兵。清代设河道总督，辖有专门治河的兵营。\n盖：因为。\n啮：本意是“咬”，这里是侵蚀冲刷的意思。\n坎穴：坑洞。\n不已：不停止。已：停止。\n倒掷：倾倒。\n如是：像这样。\n遂：于是。\n溯（sù）流：逆流。\n固：固然。\n如：依照，按照。\n然则：既然这样，那么。\n但：只，仅仅。\n据理臆断：根据某个道理就主观判断。臆断，主观地判断。\n欤：表反问的句末语气词。\n耳：罢了。\n其一：表面现象。\n其二：根本道理。', poem_appreciation = '古今异义 1.干：古义：岸边。今义：做。 2.耳：古义：罢了。今义：五官之一，用来听声音。 3.物理：古义：事物的道理，规律。今义：一种学科。 4.并：古义：一起 。今义：并列。 5.阅：古义：经历。 今义：阅读。 6.是：代词 ，此，这。今义：表示判断（多指正确，但并不完全是）。 7.但：古义：但，只。 今义：表示转折 但是，却。 8.求：古义：寻找。今义：请求、要求、追求。 9.已：古义：停止。今义：已经。 10.如：古义：像这样。今义：如果 11.盖：古义：大概。今义：有遮蔽作用的东西;由上往下覆。\n\n一词多义 1.为： 岂能为暴涨携之去 （为：介词“被”） 必与石下迎水处啮沙为坎穴 （为：动词“成为”） 众服为确论 （为：动词“认为是”或“是”） 2.重： 僧募金重修 （重：读chóng，重新） 乃石性坚重 重：（读zhòng，分量较大，与“轻”相对）', poem_tags = '文言文,理论,哲理' WHERE poem_title = '河中石兽' AND poem_author = '纪昀';
UPDATE edu_poem SET poem_translation = '花没有雪花的话，看起来没有什么精神气质。如果下雪了却没有诗文相合，也会非常的俗气。\n当在冬天傍晚夕阳西下写好了诗，刚好天空又下起了雪。再看梅花雪花争相绽放，像春天一样艳丽多姿，生气蓬勃。', poem_appreciation = '赏析 　　古今不少诗人往往把雪、梅并写。雪因梅，透露出春的信息，梅因雪更显出高尚的品格。如毛泽东《卜算子·咏梅》中就曾写道：“风雨送春归，飞雪迎春到。已是悬崖百丈冰，犹有花枝俏。俏也不争春，只把春来报。待到山花烂漫时，她在丛中笑。”雪、梅都成了报春的使者、冬去春来的象征。但在诗人卢梅坡的笔下，二者却为争春发生了“摩擦”，都认为各自占尽了春色，装点了春光，而且谁也不肯相让。这种写法，实在是新颖别致，出人意料，难怪诗人无法判个高低。诗的后两句巧妙地托出二者的长处与不足：梅不如雪白，雪没有梅香，回答了“骚人阁笔费评章”的原因，也道出了雪、梅各执一端的根据。读完全诗，我们似乎可以看出作者写这首诗是意在言外的：借雪梅的争春，告诫我们人各有所长，也各有所短，要有自知之明。取人之长，补己之短，才是真理。这首诗既有情趣，也有理趣，值得咏思。 ▲', poem_tags = '冬天,写雪,梅花' WHERE poem_title = '雪梅·其二' AND poem_author = '卢梅坡';
UPDATE edu_poem SET poem_translation = '江水倒映秋影大雁刚刚南飞， 约朋友携酒壶共登峰峦翠微。\n尘世烦扰平生难逢开口一笑， 菊花盛开之时要插满头而归。\n只应纵情痛饮酬答重阳佳节， 不必怀忧登临叹恨落日余晖。\n人生短暂古往今来终归如此， 何必像齐景公对着牛山流泪。', poem_notes = '九日：旧历九月九日重阳节，旧浴登高饮菊花酒。齐安：今湖北省麻城一带。\n翠微：这里代指山。\n酩酊（mǐngdǐng）：醉得稀里糊涂。这句暗用晋朝陶渊明典故。登临：登山临水或登高临下，泛指游览山水。\n牛山：山名。在今山东省淄博市。春秋时齐景公泣牛山，即其地。', poem_appreciation = '首联用白描的手法写雁过江上南飞，与客提壶上青山的一副美景。仅用七字，把江南的秋色描写的淋漓尽致。诗人用“涵”来形容江水仿佛把秋景包容在自己的怀抱里，“江涵秋影”四字精妙的传达出江水之清，“秋影”包容甚广，不独指雁影。“与客携壶”是置酒会友，兼之有山有水，是人生乐事，“翠微”来代替秋山，都流露出对于眼前景物的愉悦感受。\n\n　　颔联为唐诗名句，夹叙夹议，写出了诗人矛盾的心情。“难逢”、“须插”的言外之意是应把握当前及时行乐，不要无益地痛惜流光，表现了一种通达的生活态度。“菊花”是扣合重阳节的习俗。\n\n　　颈联与颔联手法相同，都采用了夹叙夹议的手法，表达了诗人想只管用酩酊大醉来酬答这良辰佳节，无须在节日登临时为夕阳西下、为人生迟暮而感慨、怨恨，同时也表达了及时行乐之意。“酩酊”也是扣合了重阳节的习俗。颔联和颈联都用了对比，一是尘世不乐与佳节尽情快乐的对比，一是大醉无忧与怨恨忧愁的对比。两联也多次提到重阳。节日的一个重要功能，就是使人们暂时摆脱日常生活的束缚、抛开日常生活的烦恼，让自己的心情放松片刻。杜牧在这里所表现的正是趁着重阳节抛开世事、尽情放纵快乐的思想。\n\n　　尾联承上“登临恨落晖”意，诗人用齐景公牛山泣涕之事进一步安慰自己。诗人由眼前所登池州的齐山，联想到齐景公的牛山坠泪，认为像“登临恨落晖”所感受到的那种人生无常，是古往今来尽皆如此的。既然并非今世才有此恨，就不必像齐景公那样独自伤感流泪。以齐景公的反例作结，表现了这种旷怀中包含着一种苦涩。\n\n　　此诗通过记叙重阳登山远眺一事，表达了诗人人生多忧、生死无常的悲哀。以看破一切的旷达乃至颓废，表现了封建知识分子的人生观的落后、消极一面。', poem_tags = '节日,重阳节' WHERE poem_title = '九日齐山登高 / 九日齐安登高' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '白酒刚刚酿熟时我从山中归来，黄鸡在啄着谷粒秋天长得正肥。\n喊着童仆给我炖黄鸡斟上白酒，孩子们嬉笑吵闹牵扯我的布衣。\n放晴高歌求醉想以此自我安慰，醉而起舞与秋日夕阳争夺光辉。\n游说万乘之君已苦于时间不早，快马加鞭奋起直追开始奔远道。\n会稽愚妇看不起贫穷的朱买臣，如今我也辞家去长安而西入秦。\n仰面朝天纵声大笑着走出门去，我怎么会是长期身处草野之人？', poem_notes = '南陵：一说在东鲁，曲阜县南有陵城村，人称南陵；一说在今安徽省南陵县。\n白酒：古代酒分清酒、白酒两种。见《礼记·内则》。《太平御览》卷八四四引三国魏鱼豢《魏略》：“太祖时禁酒，而人窃饮之。故难言酒，以白酒为贤人，清酒为圣人。”\n嬉笑：欢笑；戏乐。\n起舞落日争光辉：指人逢喜事光彩焕发，与日光相辉映。\n游说（shuì）：战国时，有才之人以口辩舌战打动诸侯，获取官位，称为游说。万乘（shèng）：君主。周朝制度，天子地方千里，车万乘。后来称皇帝为万乘。苦不早：意思是恨不能早些年头见到皇帝。\n会稽愚妇轻买臣：用朱买臣典故。买臣：即朱买臣，西汉会稽郡吴（今江苏省苏州市境内）人。\n西入秦：即从南陵动身西行到长安去。秦：指唐时首都长安，春秋战国时为秦地。\n蓬蒿人：草野之人，也就是没有当官的人。蓬、蒿：都是草本植物，这里借指草野民间。', poem_appreciation = '此诗一开始就描绘出一派丰收的景象：“白酒新熟山中归，黄鸡啄黍秋正肥。”这不仅点明了从山中归家的时间是秋熟季节，而且，白酒新熟，黄鸡啄黍，显示出一种欢快的气氛，衬托出诗人兴高采烈的情绪，为下面的描写作了铺垫。\n\n　　接着，诗人摄取了几个似乎是特写的“镜头”，进一步渲染欢愉之情。李白素爱饮酒，这时更是酒兴勃然，一进家门就“呼童烹鸡酌白酒”，神情飞扬，颇有欢庆奉诏之意。诗人的情绪感染了家人，“儿女嬉笑牵人衣”，此情此态真切动人。饮酒似还不足以表现兴奋之情，继而又“高歌取醉欲自慰，起舞落日争光辉”，一边痛饮，一边高歌，表达快慰之情。酒酣兴浓，起身舞剑，剑光闪闪与落日争辉。这样，通过儿女嬉笑，开怀痛饮，高歌起舞几个典型场景，把诗人喜悦的心情表现得活灵活现。在此基础上，又进一步描写自己的内心世界。\n\n　　“游说万乘苦不早，著鞭跨马涉远道”。这里诗人用了跌宕的表现手法，用“苦不早”反衬诗人的欢乐心情，同时，在喜悦之时，又有“苦不早”之感，正是诗人曲折复杂的心情的真实反映。正因为恨不在更早的时候见到皇帝，表达自己的政治主张，所以跨马扬鞭巴不得一下跑完遥远的路程。“苦不早”和“著鞭跨马”表现出诗人的满怀希望和急切之情。\n\n　　“会稽愚妇轻买臣，余亦辞家西入秦”。诗从“苦不早”又很自然地联想到晚年得志的朱买臣。据《汉书·朱买臣传》记载：朱买臣，会稽人，早年家贫，以卖柴为生，常常担柴走路时还念书。他的妻子嫌他贫贱，离开了他。后来朱买臣得到汉武帝的赏识，做了会稽太守。诗中的“会稽愚妇”，就是指朱买臣的妻子。李白把那些目光短浅轻视自己的世俗小人比作“会稽愚妇”，而自比朱买臣，以为像朱买臣一样，西去长安就可青云直上了。其得意之态溢于言表。诗题只说“别儿童”，这里用“会稽愚妇”之典故，是有所指责。詹锳认为此诗是“把刘氏比作‘会稽愚妇’”\n\n　　诗情经过一层层推演，至此，感情的波澜涌向高潮。“仰天大笑出门去，我辈岂是蓬蒿人。”“仰天大笑”，可以想见其得意的神态；“岂是蓬蒿人”，显示了无比自负的心理。这两句把诗人踌躇满志的形象表现得淋漓尽致。\n\n　　这首诗因为描述了李白生活中的一件大事，对了解李白的生活经历和思想感情具有特殊的意义，而在艺术表现上也有其特色。诗善于在叙事中抒情。诗人描写从归家到离家，有头有尾，全篇用的是直陈其事的赋体，而又兼采比兴，既有正面的描写，而又间之以烘托。诗人匠心独运，不是一条大道直通到底，而是由表及里，有曲折，有起伏，一层层把感情推向顶点。犹如波澜起伏，一波未平，又生一波，使感情酝蓄得更为强烈，最后喷发而出。全诗跌宕多姿，把感情表现得真挚而又鲜明。', poem_tags = '生活,喜悦,壮志,猖狂' WHERE poem_title = '南陵别儿童入京' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '天上浮云日日飘来飘去，远游的故人却久去不归。\n夜晚我屡屡梦中见到你，可知你对我的深情厚意。\n分别是你总是神色匆匆，总说能来相见多么不易。\n江湖上航行多险风恶浪，担心你的船被掀翻沉没。\n出门时搔着满头的白发，悔恨辜负自己平生之志。\n高车丽服显贵塞满京城，才华盖世你却容颜憔悴。\n谁能说天理公道无欺人，迟暮之年却无辜受牵累。\n即使有流芳千秋的美名，难以补偿遭受的冷落悲戚。', poem_notes = '浮云：喻游子飘游不定。游子：此指李白。\n这两句说：李白一连三夜入我梦中，足见对我情亲意厚。这也是从对方设想的写法。\n告归：辞别。局促：不安、不舍的样子。\n这两句是述李白告归时所说的话。\n这两句写李白告归时的神态。搔首：大概是李白不如意时的习惯举动。\n冠：官帽。盖：车上的篷盖。冠盖：指代达官。斯人：此人，指李白。\n孰云：谁说。网恢恢：《老子》有“天网恢恢，疏而不漏”的话。此处指法网恢恢。这句意思是：谁说天网宽疏，对你却过于严酷了。\n这两句说：他活着的时候虽然寂寞困苦，但必将获得千秋万岁的声名。', poem_appreciation = '这两首记梦诗，分别按梦前、梦中、梦后叙写，依清人仇兆鳌说，两篇都以四、六、六行分层，所谓“一头两脚体”。（见《杜少陵集详注》卷七）上篇写初次梦见李白时的心理，表现对故人吉凶生死的关切；下篇写梦中所见李白的形象，抒写对故人悲惨遭遇的同情。\n\n　　“死别已吞声，生别常恻恻。”诗要写梦，先言别；未言别，先说死，以死别衬托生别，极写李白流放绝域、久无音讯在诗人心中造成的苦痛。开头便如阴风骤起，吹来一片弥漫全诗的悲怆气氛。\n\n　　“故人入我梦，明我长相忆。”不说梦见故人，而说故人入梦；而故人所以入梦，又是有感于诗人的长久思念，写出李白幻影在梦中倏忽而现的情景，也表现了诗人乍见故人的喜悦和欣慰。但这欣喜只不过一刹那，转念之间便觉不对了：“君今在罗网，何以有羽翼？”你既累系于江南瘴疠之乡，怎么就能插翅飞出罗网，千里迢迢来到我身边呢？联想世间关于李白下落的种种不祥的传闻，诗人不禁暗暗思忖：莫非他真的死了？眼前的他是生魂还是死魂？路远难测啊！乍见而喜，转念而疑，继而生出深深的忧虑和恐惧，诗人对自己梦幻心理的刻画，是十分细腻逼真的。\n\n　　“魂来枫林青，魂返关塞黑。”梦归魂去，诗人依然思量不已：故人魂魄，星夜从江南而来，又星夜自秦州而返，来时要飞越南方青郁郁的千里枫林，归去要渡过秦陇黑沉沉的万丈关塞，多么遥远，多么艰辛，而且是孤零零的一个。“落月满屋梁，犹疑照颜色。”在满屋明晃晃的月光里面，诗人忽又觉得李白那憔悴的容颜依稀尚在，凝神细辨，才知是一种朦胧的错觉。相到故人魂魄一路归去，夜又深，路又远，江湖之间，风涛险恶，诗人内心祝告着、叮咛着：“水深波浪阔，无使蛟龙得。”这惊骇可怖的景象，正好是李白险恶处境的象征，这惴惴不安的祈祷，体现着诗人对故人命运的殷忧。这里，用了两处有关屈原的典故。“魂来枫林青”，出自《楚辞·招魂》：“湛湛江水兮上有枫，目极千里兮伤春心，魂兮归来哀江南！”旧说系宋玉为招屈原之魂而作。“蛟龙”一语见于梁吴均《续齐谐记》：东汉初年，有人在长沙见到一个自称屈原的人，听他说：“吾尝见祭甚盛，然为蛟龙所苦。”通过用典将李白与屈原联系起来，不但突出了李白命运的悲剧色彩，而且表示着杜甫对李白的称许和崇敬。\n\n　　上篇所写是诗人初次梦见李白的情景，此后数夜，又连续出现类似的梦境，于是诗人又有下篇的咏叹。\n\n　　“浮云终日行，游子久不至。”见浮云而念游子，是诗家比兴常例，李白也有“浮云游子意，落日故人情”（《送友人》）的诗句。天上浮云终日飘去飘来，天涯故人却久望不至；所幸李白一往情深，魂魄频频前来探访，使诗人得以聊释愁怀。“三夜频梦君，情亲见君意”，与上篇“故人入我梦，明我长相忆”互相照应，体现着两人形离神合、肝胆相照的情谊。其实，我见君意也好，君明我忆也好，都是诗人推己及人，抒写自己对故人的一片衷情。\n\n　　“告归”以下六句选取梦中魂返前的片刻，描述李白的幻影：每当分手的时候，李白总是匆促不安地苦苦诉说：“来一趟好不容易啊，江湖上风波迭起，我真怕会沉船呢！”看他走出门去用手搔着头上白发的背影，分明是在为自己壮志不遂而怅恨。“告归常局促，苦道来不易”写神态；“江湖多风波，舟楫恐失坠”是独白；“出门搔白首，若负平生志”，通过动作、外貌揭示心理。寥寥三十字，从各个侧面刻画李白形象，其形可见，其声可闻，其情可感，枯槁惨淡之状，如在目前。“江湖”二句，意同上篇“水深波浪阔，无使蛟龙得”，双关着李白魂魄来去的艰险和他现实处境的恶劣；“出门”二句则抒发了诗人“惺惺惜惺惺”的感慨。\n\n　　梦中李白的幻影，给诗人的触动太强太深了，每次醒来，总是愈思愈愤懑，愈想愈不平，终于发为如下的浩叹：“冠盖满京华，斯人独憔悴！孰云网恢恢？将老身反累！”高冠华盖的权贵充斥长安，唯独这样一个了不起的人物，献身无路，困顿不堪，临近晚年更被囚系放逐，连自由也失掉了，还有什么“天网恢恢”之可言！生前遭遇如此，纵使身后名垂万古，人已寂寞无知，夫复何用！“千秋万岁名，寂寞身后事。”在这沉重的嗟叹之中，寄托着对李白的崇高评价和深厚同情，也包含着诗人自己的无限心事。\n\n　　《梦李白二首》，上篇以“死别”发端，下篇以“身后”作结，形成一个首尾完整的结构；两篇之间，又处处关联呼应，“逐客无消息”与“游子久不至”，“明我长相忆”与“情亲见君意”，“君今在罗网”与“孰云网恢恢”，“水深波浪阔，无使蛟龙得”与“江湖多风波，舟楫恐失坠”等等，都是维系其间的纽带。但两首诗的内容和意境却颇不相同：从写“梦”来说，上篇初梦，下篇频梦；上篇写疑幻疑真的心理，下篇写清晰真切的形象。从李白来说，上篇写对他当前处境的关注，下篇写对他生平遭际的同情；上篇的忧惧之情专为李白而发，下篇的不平之气兼含着诗人自身的感慨。总之，两首记梦诗是分工而又合作，相关而不雷同，全为至诚至真之文字。', poem_tags = '唐诗三百首,记梦,同情,友人' WHERE poem_title = '梦李白二首·其二' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '巍峨高耸的滕王阁俯临着江心的沙洲，\n佩玉、鸾铃鸣响的华丽歌舞早已停止。\n早晨，画栋飞上了南浦的云；\n傍晚，珠帘卷入了西山的雨。\n悠闲的彩云影子倒映在江水中，整天悠悠然地漂浮着\n时光易逝，人事变迁，不知已经度过几个春秋。\n昔日游赏于高阁中的滕王如今无处可觅，\n只有那栏杆外的滔滔江水空自向远方奔流。', poem_notes = '滕王阁：故址在今江西南昌赣江滨，江南三大名楼之一。\n江：指赣江。渚：江中小洲。\n佩玉鸣鸾：身上佩戴的玉饰、响铃。\n南浦：地名，在南昌市西南。浦：水边或河流入海的地方（多用于地名）。\n西山：南昌名胜，一名南昌山、厌原山、洪崖山。\n日悠悠：每日无拘无束地游荡。\n物换星移：形容时代的变迁、万物的更替。物：四季的景物。\n帝子：指滕王李元婴。\n槛：栏杆。', poem_appreciation = '此诗第一句开门见山，用质朴苍老的笔法，点出了滕王阁的形势。滕王阁是高祖李渊之子滕王李元婴任洪州都督时所建。故址在今江西新建西章江门上，下临赣江，可以远望，可以俯视，下文的“南浦”、“西山”、“闲云”、“潭影”和“槛外长江”都从第一句“高阁临江渚”生发出来。滕王阁的形势是这样的好，但是如今阁中有谁来游赏呢？想当年建阁的滕王已经死去，坐着鸾铃马车，挂着琳琅玉佩，来到阁上，举行宴会，那种豪华的场面，已经一去不复返了。第一句写空间，第二句写时间，第一句兴致勃勃，第二句意兴阑珊，两两对照。诗人运用“随立随扫”的方法，使读者自然产生盛衰无常的感觉。寥寥两句已把全诗主题包括无余。\n\n　　三四两句紧承第二句，更加发挥。阁既无人游赏，阁内画栋珠帘当然冷落可怜，只有南浦的云，西山的雨，暮暮朝朝，与它为伴。这两句不但写出滕王阁的寂寞，而且画栋飞上了南浦的云，写出了滕王阁的居高，珠帘卷入了西山的雨，写出了滕王阁的临远，情景交融，寄慨遥深。\n\n　　至此，诗人的作意已全部包含，但表达方法上，还是比较隐藏而没有点醒写透，所以在前四句用“渚”“舞”“雨”三个比较沉着的韵脚之后，立即转为“悠”“秋”“流”三个漫长柔和的韵脚，利用章节和意义上的配合，在时间方面特别强调，加以发挥，与上半首的偏重空间，有所变化。“闲云”二字有意无意地与上文的“南浦云”衔接，“潭影”二字故意避开了“江”字，而把“江”深化为“潭”。云在天上，潭在地下，一俯一仰，还是在写空间，但接下来用“日悠悠”三字，就立即把空间转入时间，点出了时日的漫长，不是一天两天，而是经年累月，很自然地生出了风物更换季节，星座转移方位的感慨，也很自然地想起了建阁的人而今安在。这里一“几”一“何”，连续发问，表达了紧凑的情绪。最后又从时间转入空间，指出物要换，星要移，帝子要死去，而槛外的长江，却是永恒地东流无尽。“槛”字“江”字回应第一句的高阁临江，神完气足。\n\n　　这首诗一共只有五十六个字，其中属于空间的有阁、江、栋、帘、云、雨、山、浦、潭影；属于时间的有日悠悠、物换、星移、几度秋、今何在，这些词融混在一起，毫无叠床架屋的感觉。主要的原因，是它们都环绕着一个中心──滕王阁，而各自发挥其众星拱月的作用。\n\n　　唐诗多用实字（即名词），这与喜欢多用虚字（尤其是转折词）的宋诗有着明显的区别。例如，三四两句中，除了“飞”字和“卷”字是动词以外，其余十二个字都是实字，但两个虚字就把十二个实字一齐带动带活了，唐人的善用实字，实而不实，于此可见。\n\n　　另外，诗的结尾用对偶句法作结，很有特色。一般说来，对偶句多用来放在中段，起铺排的作用。这里用来作结束，而且不象两扇门一样地并列（术语称为扇对），而是一开一合，采取“侧势”，读者只觉其流动，而不觉其为对偶，显出了王勃过人的才力。后来杜甫的七言律诗，甚至七言绝句，也时常采用这种手法，如“即从巴峡穿巫峡，便下襄阳向洛阳”，“口脂面药随恩泽，翠管银罂下九霄”，“流连戏蝶时时舞，自在娇莺恰恰啼”等。可见王勃对唐诗发展的影响。', poem_tags = '写景,怀古' WHERE poem_title = '滕王阁诗' AND poem_author = '王勃';
UPDATE edu_poem SET poem_translation = '回忆起那个晴朗的中秋，我置身在芳香的丹桂丛。花影映照在酒杯中，月波荡漾在酒杯中。今晚同样在楼上举杯待月光，可是乌云浸湿了纱窗，雨水打湿了纱窗。\n我直想乘风上天去质问天公，可是这天路没法打通，想送个信吧信也难通。满堂只有蜡烛高烧光闪闪，照耀得酒宴上红彤彤。让我们慢慢把酒喝几盅，让我们慢慢把曲唱到终。', poem_notes = '尊：同“樽”，酒杯。\n浑欲：简直想。化工：指自然的造化者。\n从容：悠闲舒缓，不慌不忙。', poem_appreciation = '这是一首描写中秋赏月未得的词。上片运用对比手法，写出今宵中秋无月的遗憾。“忆对”三句是回忆以前那个花好月圆的中秋节情景：天晴风静，皓月当空，桂花飘香，饮酒乐甚，心情非常舒畅。尤其是花映在杯中，月也在映在酒杯中的描写，生动形象，富于情趣。“今宵”三句，写今夜无月的情景，但词人并未直接写出，而是说今晚饮酒还是和以前一样的，但云雨却打湿了纱窗，言外之意就是雨夜没有月亮，纱窗外显得格外孤寂，显得含蓄蕴藉，耐人寻味。\n\n　　词的下片写赏月不得的愁绪。“浑欲”三句说词人因不见明月而忧愁，真想乘风上天去问个究竟，为什么中秋之夜没有月亮呢，但“路也难通，信也难通”，想问也问不成。“满堂”三句写出中秋无月的寂寞，只好以饮酒和歌舞来弥补这些遗憾了。', poem_tags = '中秋节,月夜,抒怀,壮志难酬,怀才不遇,愤懑' WHERE poem_title = '一剪梅·中秋元月' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '在深秋的夜晚，弹奏起吴丝蜀桐制成精美的箜篌。听到美妙的乐声，天空的白云凝聚起来不再飘游。\n湘娥把泪珠洒满斑竹，九天素女也牵动满腔忧愁。出现这种情况，是由于乐工李凭在京城弹奏箜篌。\n乐声清脆动听得就像昆仑山美玉击碎，凤凰鸣叫；时而使芙蓉在露水中饮泣，时而使香兰开怀欢笑。\n清脆的乐声，融和了长安城十二门前的清冷光气。二十三根弦丝高弹轻拨，打动了高高在上的天帝。\n高亢的乐声直冲云霄，冲上女娲炼石补过的天际。好似补天的五彩石被击破，逗落了漫天绵绵秋雨。\n幻觉中仿佛乐工进入了神山，把技艺向女仙传授；老鱼兴奋得在波中跳跃，瘦蛟也翩翩起舞乐悠悠。\n月宫中吴刚被乐声吸引，彻夜不眠在桂树下逗留。桂树下的兔子也伫立聆听，不顾露珠斜飞寒飕飕！', poem_notes = '李凭：当时的梨园艺人，善弹奏箜篌。杨巨源《听李凭弹箜篌》诗曰：“听奏繁弦玉殿清，风传曲度禁林明。君王听乐梨园暖，翻到《云门》第几声？”“花咽娇莺玉嗽泉，名高半在玉筵前。汉王欲助人间乐，从遣新声坠九天。”箜篌引：乐府旧题，属《相和歌·瑟调曲》。箜篌：古代弦乐器。又名空侯、坎侯。形状有多种。据诗中“二十三丝”，可知李凭弹的是竖箜篌。引：一种古代诗歌体裁，篇幅较长，音节、格律一般比较自由，形式有五言、七言、杂言。\n吴丝蜀桐：吴地之丝，蜀地之桐。此指制作箜篌的材料。张：调好弦，准备调奏。高秋：指弹奏时间。这句说在深秋天气弹奏起箜篌。\n空白：一作“空山”。《列子·汤问》：“秦青抚节悲歌，响遏行云”。此句言山中的行云因听到李凭弹奏的箜篌声而凝定不动了。\n江娥：一作“湘娥”。李衎《竹谱详录》卷六：“泪竹生全湘九疑山中……《述异记》云：‘舜南巡，葬于苍梧，尧二女娥皇、女英泪下沾竹，文悉为之斑。’一名湘妃竹。”素女：传说中的神女。《汉书·郊祀志上》：“秦帝使素女鼓五十弦瑟，帝禁不止，故破其瑟为二十五弦。”这句说乐声使江娥、素女都感动了。\n中国：即国之中央，意谓在京城。\n昆山玉碎凤凰叫：昆仑玉碎，形容乐音清脆。昆山，即昆仑山。凤凰叫，形容乐音和缓。\n芙蓉泣露、香兰笑：形容乐声时而低回，时而轻快。\n十二门：长安城东西南北每一面各三门，共十二门，故言。这句是说清冷的乐声使人觉得长安城沉浸在寒光之中。\n二十三丝：《通典》卷一百四十四：“竖箜篌，胡乐也，汉灵帝好之，体曲而长，二十三弦。竖抱于怀中，用两手齐奏，俗谓之擘箜篌。”“紫皇”：道教称天上最尊的神为“紫皇”。这里用来指皇帝。\n女娲：中华上古之神，人首蛇身，为伏羲之妹，风姓。《淮南子·览冥训》和《列子·汤问》载有女娲炼五色石补天故事。\n石破天惊逗秋雨：补天的五色石（被乐音）震破，引来了一场秋雨。逗，引。\n坤山：一作“神山”。神妪（yù）：《搜神记》卷四：“永嘉中，有神现兖州，自称樊道基。有妪号成夫人。夫人好音乐，能弹箜篌，闻人弦歌，辄便起舞。”所谓“神妪”，疑用此典。从这句以下写李凭在梦中将他的绝艺教给神仙，惊动了仙界。\n老鱼跳波：鱼随着乐声跳跃。源自《列子·汤问》：“瓠巴鼓琴而鸟舞鱼跃。”\n吴质：即吴刚。《酉阳杂俎》卷一：“旧言月中有桂，有蟾蜍。故异书言月桂高五百丈，下有一人常斫之，树创随合。人姓吴名刚，西河人，学仙有过，谪令伐树。”\n露脚：露珠下滴的形象说法。寒兔：指秋月，传说月中有玉兔，故称。', poem_appreciation = '李凭是梨园弟子，因善弹箜篌，名噪一时。“天子一日一回见，王侯将相立马迎”，身价之高，似乎远远超过盛唐时期的著名歌手李龟年。他的精湛技艺，受到诗人们的热情赞赏。李贺此篇想象丰富，设色瑰丽，艺术感染力很强。清人方扶南把它与白居易的《琵琶行》、韩愈的《听颖师弹琴》相提并论，推许为“摹写声音至文”。\n\n　　诗的起句开门见山，“吴丝蜀桐”写箜篌构造精良，借以衬托演奏者技艺的高超，写物亦即写人，收到一箭双雕的功效。“高秋”一语，除了表明时间是九月深秋，还含有“秋高气爽”的意思，与“深秋”、“暮秋”之类相比，更富含蕴。二、三两句写乐声。诗人故意避开无形无色、难以捉摸的主体（箜篌声），从客体（“空山凝云”之类）落笔，以实写虚，亦真亦幻，极富表现力。\n\n　　优美悦耳的弦歌声一经传出，空旷山野上的浮云便颓然为之凝滞，仿佛在俯首谛听；善于鼓瑟的湘娥与素女，也被这乐声触动了愁怀，潸然泪下。“空山”句移情于物，把云写成具有人的听觉功能和思想感情，似乎比“天若有情天亦老”（《金铜仙人辞汉歌》）更进一层。它和下面的“江娥”句互相配合，互相补充，极力烘托箜篌声神奇美妙，具有“惊天地，泣鬼神”的魅力。第四句“李凭中国弹箜篌”，用“赋”笔点出演奏者的名姓，并且交代了演奏的地点。前四句，诗人故意突破按顺序交待人物、时间、地点的一般写法，另作精心安排，先写琴，写声，然后写人，时间和地点一前一后，穿插其中。这样，突出了乐声，有着先声夺人的艺术力量。\n\n　　五、六两句正面写乐声，而又各具特色。“昆山”句是以声写声，着重表现乐声的起伏多变；“芙蓉”句则是以形写声，刻意渲染乐声的优美动听。“昆山玉碎凤凰叫”，那箜篌，时而众弦齐鸣，嘈嘈杂杂，仿佛玉碎山崩，令人不遑分辨；时而又一弦独响，宛如凤凰鸣叫，声振林木，响遏行云。“芙蓉泣露香兰笑”，构思奇特。带露的芙蓉（即荷花）是屡见不鲜的，盛开的兰花也确实给人以张口欲笑的印象。它们都是美的化身。诗人用“芙蓉泣露”摹写琴声的悲抑，而以“香兰笑”显示琴声的欢快，不仅可以耳闻，而且可以目睹。这种表现方法，真有形神兼备之妙。\n\n　　从第七句起到篇终，都是写音响效果。先写近处，长安十二道城门前的冷气寒光，全被箜篌声所消融。其实，冷气寒光是无法消融的，因为李凭箜篌弹得特别好，人们陶醉在他那美妙的弦歌声中，以致连深秋时节的风寒露冷也感觉不到了。虽然用语浪漫夸张，表达的却是一种真情实感。“紫皇”是双关语，兼指天帝和当时的皇帝。诗人不用“君王”而用“紫皇”，不单是遣词造句上追求新奇，而且是一种巧妙的过渡手法，承上启下，比较自然地把诗歌的意境由人寰扩大到仙府。以下六句，诗人凭借想象的翅膀，飞向天庭，飞上神山，把读者带进更为辽阔深广、神奇瑰丽的境界。“女娲炼石补天处，石破天惊逗秋雨”，乐声传到天上，正在补天的女娲听得入了迷，竟然忘记了自己的职守，结果石破天惊，秋雨倾泻。这种想象是何等大胆超奇，出人意料，而又感人肺腑。一个“逗”字，把音乐的强大魅力和上述奇瑰的景象紧紧联系起来了。而且，石破天惊、秋雨霶霈的景象，也可视作音乐形象的示现。\n\n　　第五联，诗人又从天庭描写到神山。那美妙绝伦的乐声传入神山，教令神妪也为之感动不已；乐声感物至深，致使“老鱼跳波瘦蛟舞”。诗人用“老”和“瘦”这两个似平干枯的字眼修饰鱼龙，却有着完全相反的艺术效果，使音乐形象更加丰满。老鱼和瘦蛟本来羸弱乏力，行动艰难，竟然伴随着音乐的旋律腾跃起舞，这种出奇不意的形象描写，使那无形美妙的箜篌声浮雕般地呈现在读者的眼前了。\n\n　　以上八句以形写声，摄取的多是运动着的物象，它们联翩而至，新奇瑰丽，令人目不暇接。结末两句改用静物，作进一步烘托：成天伐桂、劳累不堪的吴刚倚着桂树，久久地立在那儿，竟忘了睡眠；玉兔蹲伏一旁，任凭深夜的露水不停在洒落在身上，把毛衣浸湿，也不肯离去。这些饱含思想感情的优美形象，深深印在读者心中，就像皎洁的月亮投影于水，显得幽深渺远，逗人情思，发人联想。\n\n　　诗的最大特点是想象奇特，形象鲜明，充满浪漫主义色彩。诗人致力于把自己对于箜篌声的抽象感觉、感情与思想借助联想转化成具体的物象，使之可见可感。诗歌没有对李凭的技艺作直接的评判，也没有直接描述诗人的自我感受，有的只是对于乐声及其效果的摹绘。然而纵观全篇，又无处不寄托着诗人的情思，曲折而又明朗地表达了他对乐曲的感受和评价。这就使外在的物象和内在的情思融为一体，构成可以悦目赏心的艺术境界。', poem_tags = '音乐,想象' WHERE poem_title = '李凭箜篌引' AND poem_author = '李贺';
UPDATE edu_poem SET poem_tags = '豪放,登楼,抒怀' WHERE poem_title = '满江红·登黄鹤楼有感' AND poem_author = '岳飞';
UPDATE edu_poem SET poem_translation = '聚首如胶似漆作别却象无情；\n只觉得酒筵上要笑笑不出声。\n案头蜡烛有心它还依依惜别；\n你看它替我们流泪流到天明。', poem_notes = '多情句：意谓多情者满腔情绪，一时无法表达，只能无言相对，倒象彼此无情。\n樽：酒杯。', poem_appreciation = '这一首着重写惜别，描绘与她的筵席上难分难舍的情怀。首名写离筵之上压抑无语，似乎冷淡无情；次句以“笑不成”点明原非无情，而是郁悒感伤，实乃多情，回应首句。\n\n　　齐、梁之间的江淹曾经把离别的感情概括为“黯然销魂”四字。但这种感情的表现，却因人因事的不同而千差万别，这种感情本身，也不是“悲”、“愁”二字所能了得。杜牧此诗不用“悲”、“愁”等字，却写得坦率、真挚，道出了离别时的真情实感。\n\n　　诗人同所爱不忍分别，又不得不分别，感情是千头万绪的。“多情却似总无情”，明明多情，偏从“无情”着笔，著一“总”字，又加强了语气，带有浓厚的感情色彩。诗人爱得太深、太多情，以至使他觉得，无论用怎样的方法，都不足以表现出内心的多情。别筵上，凄然相对，象是彼此无情似的。越是多情，越显得无情，这种情人离别时最真切的感受，诗人把它写出来了。“唯觉樽前笑不成”，要写离别的悲苦，他又从“笑”字入手。一个“唯”字表明，诗人是多么想面对情人，举樽道别，强颜欢笑，使所爱欢欣！但因为感伤离别，却挤不出一丝笑容来。想笑是由于“多情”，“笑不成”是由于太多情，不忍离别而事与愿违。这种看似矛盾的情态描写，把诗人内心的真实感受，说得委婉尽致，极有情味。\n\n　　题为“赠别”，当然是要表现人的惜别之情。然而诗人又撇开自己，去写告别宴上那燃烧的蜡烛，借物抒情。诗人带着极度感伤的心情去看周围的世界，于是眼中的一切也就都带上了感伤色彩。这就是刘勰所说的：“属采附声，亦与心而徘徊”（《文心雕龙·物色》）。“蜡烛”本是有烛芯的，所以说“蜡烛有心”；而在诗人的眼里烛芯却变成了“惜别”之心，把蜡烛拟人化了。在诗人的眼里，它那彻夜流溢的烛泪，就是在为男女主人的离别而伤心了。“替人垂泪到天明”，“替人”二字，使意思更深一层。“到天明”又点出了告别宴饮时间之长，这也是诗人不忍分离的一种表现。\n\n　　诗人用精炼流畅、清爽俊逸的语言，表达了悱恻缠绵的情思，风流蕴藉，意境深远，余韵不尽。就诗而论，表现的感情还是很深沉、很真挚的。杜牧为人刚直有节，敢论列大事，却也不拘小节，好歌舞，风情颇张，本诗亦可见此意。', poem_tags = '唐诗三百首,离别,惜别' WHERE poem_title = '赠别' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '一个面容姣好的少女，她的笑容像荷花盛开，斜坠的云鬓，双手衬着雪白的香腮。她的眼波灵活可动就像能说话一样。\n一脸的温情饱含着深韵，笔下的纸笺写了一半上面全是寄托自己娇嗔和思念的话语。月上阑干，花的影子不断移动，正是情人约会重聚的好时光。', poem_notes = '①《浣溪沙》：词牌名。本为唐玄宗时教坊曲名，后用为词牌，亦作《浣溪纱》。分平仄两体，字数以四十二字居多，还有四十四字和四十六字两种。全词分两片，上片三句全用韵，下片末二句用韵。曲调轻松明快，是宋词中使用频率较高的词牌名。\n②绣面：形容面容姣美。芙蓉：荷花，此处指面容好看像荷花盛开了。\n③飞：《历代诗余》作“偎”。宝鸭：鸭形发式，或指钗头形状为鸭形的宝钗。香腮：唐代温庭筠有“鬓云欲度香腮雪。”\n④一面：整个脸上。风情：男女爱慕之情。韵：味道。\n⑤笺：纸，指信笺、诗笺。半笺娇恨：半纸怨艾之辞。\n⑥月移花影：唐代元稹《莺莺传》：“待月西厢下，迎风户半开。拂墙花影动，疑是玉人来。”', poem_appreciation = '这首言情小调通过对一个女子的情态的几个侧面摹写，不仅生动地勾勒出她美丽动人的外貌，而且也展现出人物大胆天真的性格，以及蕴藏在心底的细腻幽深的感情。\n\n　　上片三句中前两句“绣面芙蓉一笑开，斜飞宝鸭衬香腮”，是一副似对非对的偶句。“绣面芙蓉”形容这个女子姣美的面庞宛如出水荷花，光艳明丽；“斜飞宝鸭”是说她把用宝石镶嵌的飞鸭状头饰斜插鬓边，对自己作了精心地修饰妆点；正如古人所说的“粉黛所以饰容，而顾盼生于淑质”，这两句表示词中女主角天生俏丽，再加以入时的华饰，就必然产生不同一般的效果。句中的“一笑开”三字之妙，妙在它以动态描写打破了静物写生，起到了能将词中的女子从字面上呼出的奇效；而其中“开”字在这里用得尤为精巧。诗词之妙，在于炼字炼句，使一词一句的含义达到极大的丰富；即如这个“开”字，无疑是指芙蓉花开，但其深层意思未尝不可以表示词中女主人公心底被禁锢的爱之苞蕾正在展放。接下来的“眼波才动被人猜”这句神来之笔，便为此提出了很好的印证。常言道“眼睛是心灵的窗户”，这个女子美目流盼，宛如一弯流动明澈的秋水，其中映照着她内心的喜悦与怕人发现自己秘密的悸栗。越怕人猜，偏会被猜，这便是生活的真实；作者捕捉到这一真实，用朴实无华的文字恰当地表现出来，更添了几分韵味。\n\n　　下片进一步刻划人物的内心世界，前两句“一面风情深有韵，半笺娇恨寄幽怀”是一副较为工巧的对偶句，摹写出这样的情景：幽居深闺的怀春女子，完全被“爱而不见”的愁苦与期盼的喜悦所左右，这混杂的感情化为风情万点，都从她一颦一笑的的面部流露无遗；终于她大胆地展开半张素笺，舞动一只彤管，把满怀思念、娇嗔与幽怨倾泻给自己深深系恋着的人。结句“月移花影约重来”写的是实况？是希冀？还是幻影？无从考定。但这确是一幅绝美的流动着的画面：月光里，花影下，玉人双双，倾诉着生死相依的情话……\n\n　　这首反映爱情的小令，词语鲜明生动而不失其朴直。只要把它放在被封建礼教重重包裹的那个时代，只要不带任何世俗偏见，便会发现易安笔下的这个秀外慧中的少女多么可爱，她对幸福、自由的追求又是多么真挚、炽烈、大胆；从而也会惊叹这首词多么质朴深刻、生气盎然。', poem_tags = '宋词精选,女子,追求,爱情' WHERE poem_title = '浣溪沙·闺情' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '冷雨洒满江天的夜晚我来到吴地，天明送走好友只留下楚山的孤影。\n到了洛阳，如果有亲友向您打听我的情况，就请转告他们，我的心依然像玉壶里的冰一样纯洁，未受功名利禄等世情的玷污。\n\n往丹阳城南望去，只见秋海阴雨茫茫；向丹阳城北望去，只见楚天层云深深。\n高楼送客，与友人依依惜别，心情悲愁，喝酒也不能尽兴。四周一片寂静，对着寒冷江天，只有高悬的明月照我心。', poem_notes = '芙蓉楼：原名西北楼，登临可以俯瞰长江，遥望江北，在润州（今江苏省镇江市）西北。据《元和郡县志》卷二十六《江南道·润州》丹阳：“晋王恭为刺史，改创西南楼名万岁楼，西北楼名芙蓉楼。”辛渐：诗人的一位朋友。\n寒雨：秋冬时节的冷雨。连江：雨水与江面连成一片，形容雨很大。吴：古代国名，这里泛指江苏南部、浙江北部一带。江苏镇江一带为三国时吴国所属。\n平明：天亮的时候。客：指作者的好友辛渐。楚山：楚山：楚地的山。这里的楚也指镇江市一带，因为古代吴、楚先后统治过这里，所以吴、楚可以通称。孤：独自，孤单一人。\n洛阳：现位于河南省西部、黄河南岸。\n冰心，比喻纯洁的心。玉壶，道教概念妙真道教义，专指自然无为虚无之心。陆机《汉高祖功臣颂》有“心若怀冰”句，比喻心地纯洁。鲍照《白头吟》：“直如朱丝绳，清如玉壶冰。”也是以“玉壶冰”比喻清白的操守。唐人有时也以此比喻为官廉洁，如姚崇《冰壶诫》序云“夫洞澈无瑕，澄空见底，当官明白者，有类是乎？故内怀冰清，外涵玉润，此君子冰壶之德也”。\n丹阳：在今江苏省西南部，东北滨长江，大运河斜贯，属镇江市。\n高楼：指芙蓉楼。', poem_appreciation = '这两首诗所记送别的时间和情景是“倒叙”。第一首写的是第二天早晨在江边送别友人的情景；第二首写第一天晚上在芙蓉楼为友人饯行之事。\n\n　　第一首写平明送客，临别托意。”寒雨连江夜入吴”，迷蒙的烟雨笼罩着吴地江天（江宁一带，此地是三国孙吴故地），织成了一张无边无际的愁网。夜雨增添了萧瑟的秋意，也渲染出了离别的黯淡气氛。那寒意不仅弥漫在满江烟雨之中，更沁透在两个离别友人的心头上。”连”字和”入”字写出雨势的平稳连绵，江雨悄然而来的动态能为人分明地感知，则诗人因离情萦怀而一夜未眠的情景也自可想见。 但是，这一幅水天相连、浩渺迷茫的吴江夜雨图，正好展现了一种极其高远壮阔的境界。中晚唐诗和婉约派宋词往往将雨声写在窗下梧桐、檐前铁马、池中残荷等等琐物上，而王昌龄却并不实写如何感知秋雨来临的细节，他只是将听觉、视觉和想象概括成连江入吴的雨势，以大片淡墨染出满纸烟雨，这就用浩大的气魄烘托了”平明送客楚山孤”的开阔意境。清晨，天色已明，辛渐即将登舟北归。诗人遥望江北的远山，想到友人不久便将隐没在楚山之外，孤寂之感油然而生。在辽阔的江面上，进入诗人视野的当然不止是孤峙的楚山，浩荡的江水本来是最易引起别情似水的联想的，唐人由此而得到的名句也多得不可胜数。 然而王昌龄没有将别愁寄予随友人远去的江水，却将离情凝注在矗立于苍莽平野的楚山之上。因为友人回到洛阳，即可与亲友相聚，而留在吴地的诗人，却只能像这孤零零的楚山一样，伫立在江畔空望着流水逝去。一个”孤”字如同感情的引线，自然而然牵出了后两句临别叮咛之辞：”洛阳亲友如相问，一片冰心在玉壶。”诗人从清澈无瑕、澄空见底的玉壶中捧出一颗晶亮纯洁的冰心以告慰友人，这就比任何相思的言辞都更能表达他对洛阳亲友的深情。\n\n　　早在六朝刘宋时期，诗人鲍照就用”清如玉壶冰”《代白头吟》来比喻高洁清白的品格。自从开元宰相姚崇作《冰壶诫》以来，盛唐诗人如王维、崔颢、李白等都曾以冰壶自励，推崇光明磊落、表里澄澈的品格。王昌龄托辛渐给洛阳亲友带去的口信不是通常的平安竹报，而是传达自己依然冰清玉洁、坚持操守的信念，是大有深意的。\n\n　　诗人在这以晶莹透明的冰心玉壶自喻，正是基于他与洛阳诗友亲朋之间的真正了解和信任，这决不是洗刷谗名的表白，而是蔑视谤议的自誉。因此诗人从清澈无瑕、澄空见底的玉壶中捧出一颗晶亮纯洁的冰心以告慰友人，这就比任何相思的言辞都更能表达他对洛阳亲友的深情。\n\n　　即景生情，情蕴景中，本是盛唐诗的共同特点，而深厚有余、优柔舒缓。“尽谢炉锤之迹”（胡应麟《诗薮》）又是王诗的独特风格。此诗那苍茫的江雨和孤峙的楚山，不仅烘托出诗人送别时的凄寒孤寂之情，更展现了诗人开朗的胸怀和坚强的性格。屹立在江天之中的孤山与冰心置于玉壶的比象之间又形成一种有意无意的照应，令人自然联想到诗人孤介傲岸、冰清玉洁的形象，使精巧的构思和深婉的用意融化在一片清空明澈的意境之中，所以天然浑成，不着痕迹，含蓄蕴藉，余韵无穷。\n\n　　第二首说的是头天晚上诗人在芙蓉楼为辛渐饯别时的情景。先从“秋海阴”、“楚雪深”写起，以景起兴。第三句是点题：高楼送客，依依惜别，心情悲愁，酒不尽兴。末句以景结情：寒江寂寂，惆怅如不尽之江水；明月高照，友情像明月一样地纯真。全诗融情入景，以景结情，主要还是抒情，堪称一绝。', poem_tags = '组诗,送别,友情,写景,抒情' WHERE poem_title = '芙蓉楼送辛渐二首' AND poem_author = '王昌龄';
UPDATE edu_poem SET poem_translation = '我送给你一种解决疑问的办法，这个办法不需龟甲，蓍草茎来占卜吉凶。\n检验玉真假还需要烧满三天，辨别木材还要等七年以后。\n周公害怕流言蜚语的日子，王莽篡位之前毕恭毕敬。\n假使这人当初就死去了，一生的真假又有谁知道呢？', poem_notes = '（1）放言：言论放肆，不受拘束的意思。\n（2）君：您，这里指作者的好友元稹。\n（3）法：办法，方法。\n（4）决：决定，解决，判定。\n（5）狐疑：狐性多疑，故用狐疑指犹豫不定。\n（6）钻龟、祝蓍（shī）：古人因迷信而占卜的方法，钻龟壳后看其裂纹占卜吉凶，或拿蓍草的茎占卜吉凶。这里是指求签问卜。蓍，多年生草本植物，全草可入药，茎、叶可制香料。\n（7）试：试验，检验。\n（8）辨：辨别，鉴别。\n（9）材：木材，这里指枕木和樟木。\n（10）期：期限。\n（11）篡（cuàn）：篡位，臣子夺取君主的权位。\n（12）向使：假如，如果，假使。\n（13）便：就。\n（14）复：又。\n（15）周公：姬旦，周武王弟，成王的叔父。典故：成王年幼为王，周公摄政，管叔等人散布流言，说周公要害成王，于是周公躲避了起来。后来成王发现流言是假的，便迎接周公回来，平定了管叔等人的叛乱。\n（16）王莽（mǎng）：汉元帝皇后侄。典故：王莽在篡夺政权之前，为了收揽人心，常以谦恭退让示人，后来终于篡汉自立，改国号为“新”。', poem_appreciation = '这是一首富有理趣的好诗。它以极通俗的语言说出了一个道理：对人、对事要得到全面的认识，都要经过时间的考验，从整个历史去衡量、去判断，而不能只根据一时一事的现象下结论，否则就会把周公当成篡权者，把王莽当成谦恭的君子了。诗人表示像他自己以及友人元稹这样受诬陷的人，是经得起时间考验的，因而应当多加保重，等待“试玉”、“辨材”期满，自然会澄清事实，辨明事伪。这是用诗的形式对他自身遭遇进行的总结。\n\n　　在表现手法上，虽以议论为主，但行文却极为曲折，富有情味。“赠君一法决狐疑”，诗一开头就说要告诉人一个决狐疑的方法，而且很郑重，用了一个“赠”字，强调这个方法的宝贵，说明是经验之谈。这就紧紧抓住了读者。因在生活中不能做出判断的事是很多的，大家当然希望知道是怎样的一种方法。“不用钻龟与祝蓍”。先说不用什么，而该用什么，却不径直说出。这就使诗歌有曲折、有波澜，对读者也更有吸引力。诗的第二、三句才把这个方法委婉地介绍出来：“试玉要烧三日满，辨材须待七年期。”很简单，要知道事物的真伪优劣只有让时间去考验。经过一定时间的观察比较，事物的本来面目终会呈现出来的。\n\n　　以上是从正面说明这个方法的正确性，然后掉转笔锋，再从反面说明：“周公恐惧流言日，王莽谦恭未篡时。”如果不用这种方法去识别事物，就往往不能做出准确的判断。对周公和王莽的评价，就是例子。周公在铺佐成王的时期，某些人曾经怀疑他有篡权的野心，但历史证明他对成王一片赤诚，他忠心耿耿是真，说他篡权则是假。王莽在未取代汉朝政权时，假装谦恭，曾经迷惑了一些人；《汉书》说他“爵位愈尊，节操愈谦”。但历史证明他的“谦恭”是伪，代汉自立才是他的真面目。“向使当初身便死，一生真伪复谁知？”这是全篇的关键句。“决狐疑”的目的是分辨真伪。真伪分清了，狐疑自然就没有了。如果过早地下结论，不用时间来考验，就容易为一时表面现象所蒙蔽，不辨真伪，冤屈好人。\n\n　　诗的意思极为明确，出语却曲折委婉。从正面、反面叙说“决狐疑”之“法”，都没有径直点破。前者举出“试玉”、“辨材”两个例子，后者举出周公、王莽两个例子，让读者思而得之。这些例子，既是论点，又是论据。寓哲理于形象之中，以具体事物表现普遍规律，小中见大，耐人寻思。其以七言律诗的形式，表达一种深刻的哲理，令读者思之有理，读之有味。', poem_tags = '哲理' WHERE poem_title = '放言五首·其三' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '在绿阴丛中，一座别致、幽静的小楼悄然独立，曲曲折折的栏杆紧紧依偎着碧树，两者相映成趣。春风和煦轻柔，鹅黄嫩绿、如丝如缕的杨柳在风中款款摆动腰肢，摇曳多姿。\n春光明媚，晴空万里，游丝袅袅，柳絮翻飞，这已是暮春景象了，正当杏花盛开，娇艳无比之际，却下起了一阵小雨。在如此深重的幽情之中，她不由沉沉睡去，正在睡酣梦甜之际，却被窗外清脆的莺啼声惊起，而美梦也再也无寻处了。', poem_notes = '偎：紧靠着。\n黄金缕：形容嫩黄的柳条，如同丝丝金线一般。\n钿筝：用金翠宝石装饰的筝，玉柱：筝上定弦用的玉制码子。\n海燕：传说燕子来自海上，故称“海燕”。双飞，一作“晾飞”。以上两句是写有人弹起筝来，双燕由帘内惊起飞走。\n游丝：指在空中飞扬的虫丝。落絮：指飘落的柳絮。\n一霎（sha）：一阵子。唐孟郊《春后雨》诗：“昨夜一霎雨，天意苏群物。”\n觉来：醒来。莺乱语，一作“慵不语”。', poem_appreciation = '这首词是拟写闺情之作，全篇以写景始而以情终，景中含情，情又衬景，因而被评为“金碧山水，一片空蒙。”（谭献《谭评词辨》）\n\n　　上阕从春光写起。“六曲阑干”三句极力描写庭院的春日明媚风景。曲曲红阑，被绿茵扶疏的碧树所环绕；院中的杨柳随风摇摆，如丝如缕的柔条在夕阳的晚照中轻盈飞舞，好一派静谧、优美的景色。一个“偎”字，写出自然景物与人工景物的和谐、亲昵，一个“展”字，写尽了柳条的媚态，词的意境，就在这柔和、清雅的景物中被烘托出。而突如其来的琮琮筝声，打破了这安静的氛围，也惊起了双燕，穿帘而去。由燕子的安居，可知闺中的冷清；由筝声的惊燕，可知声音之激越，弹筝者心情之郁闷也可见一斑。尽管全部是写景，但闺中人独处的难堪之情已经隐约可见。上阕中词人分别从听觉和视觉两个角度进行描写，先写筝鸣声之凄婉，再写成双的海燕穿帘而去，所见所闻，勾起词人隐隐的孤独与惆怅之感，为下文进一步抒情做铺垫。\n\n　　下片抒伤春之情。首三句写词人所见：游丝、落絮、红杏花，这些景物的描写，暗示春之将逝。依旧由景开始，但是“满眼”一词已经凸现了人的出现，是从闺中人的视线和心情来看景了。“游丝”和“落絮”都是经典的春愁缭乱、幽思绵绵的意象，“满”和“兼”字更说明了一种无聊、无奈的心情。这是突然降下的一阵清明雨，打得院中杏花零落。最后一句由春光缭绕归结到春闺的愁思，一个“乱”字说明了心绪之乱，“无寻处”则点出了好梦被惊醒后的烦恼与忧愁。经过这两句一点化，前面的景语全都变成了情语，令人回味不已。\n\n　　整首词诗人由写景始，由写人终。写景抓住春天的特指，但有富于变化，在变化中蕴含了作者的情感，写人先写人物的行动，把细筝移玉柱，但穿帘双燕却勾起了主人公无限的伤感，成为全词感情转折的基点。再写人物的心理，“惊残好梦无寻处”，直接抒发主人公内心的伤感。整首词写景与写人相互交融，通过穿帘的双燕，乱语的“黄莺”、“游丝”、“落絮”“清明雨”，使人物的心理活动步步呈现，达到了情与景的高度统一，但又含而不露，堪称“金碧山水，一片空蒙。”全词在艺术风格上语言明丽，用意婉曲。', poem_tags = '清明节,写景,回忆,伤怀' WHERE poem_title = '鹊踏枝·六曲阑干偎碧树' AND poem_author = '冯延巳';
UPDATE edu_poem SET poem_translation = '胜败乃是兵家常事，难以事前预料。能够忍辱负重，才是真正男儿。\n西楚霸王啊，江东子弟人才济济，若能重整旗鼓卷土杀回，楚汉相争，谁输谁赢还很难说。', poem_notes = '乌江亭：在今安徽和县东北的乌江浦，相传为西楚霸王项羽自刎之处。《史记·项羽本纪》：“于是项王乃欲东渡乌江。乌江亭长檥船待，谓项王曰：‘江东虽小，地方千里，众数十万人，亦足王也。愿大王急渡。今独臣有船，汉军至，无以渡。’项王笑曰：‘天之亡我，我何渡为！且籍与江东子弟八千人渡江而西，今无一人还，纵江东父兄怜而王我，我何面目见之？纵彼不言，籍独不愧于心乎？’······乃自刎而死。”\n兵家：一作“由来”。事不期：一作“不可期”。不期，难以预料。\n包羞忍耻：意谓大丈夫能屈能伸，应有忍受屈耻的胸襟气度。\n江东：自汉至隋唐称自安徽芜湖以下的长江南岸地区为江东。才俊：才能出众的人。才，一作“豪”。\n卷土重来：指失败以后，整顿以求再起。', poem_appreciation = '诗作首句直截了当地指出胜败乃兵家之常这一普通常识，并暗示关键在于如何对待的问题，为以下作好铺垫。“事不期”，是说胜败的事，不能预料。次句强调指出只有“包羞忍耻”，才是“男儿”。项羽遭到挫折便灰心丧气，含羞自刎，怎么算得上真下的“男子汉”呢？“男子汉”三字，令人联想到自诩为力超过山河，气可盖世的西楚霸王，直到临死，还未找到自己失败的原因，只是归咎于“时不利”而羞愤自杀，有愧于他的“英雄”称号。\n\n　　第三句“江东子弟多才俊”，是对亭长建议“江东虽小，地方千里，众数十万人，亦足王也”的艺术概括。人们历来欣赏项羽“无面见江东父兄”一语，认为表现了他的气节。其实这恰好反映了他的刚愎自用，听不进亭长忠言。他错过了韩信，气死了范增，确是愚蠢得可笑。然而在这最后关头，如果他能面对现实，“包羞忍耻”，采纳忠言，重返江东，再整旗鼓，则胜负之数，或未易量。这就又落脚到了末句。\n\n　　“卷土重来未可知”，是全诗最得力的句子，其意盖谓如能做到这样，还是大有可为的；可惜的是项羽却不肯放下架子而自刎了。这样就为上面一、二两句提供了有力的依据，而这样急转直下，一气呵成，令人想见“江东子弟”“卷土重来”的情状，是颇有气势的。同时，在惋惜、批判、讽刺之余，又表明了“败不馁”的道理，也是颇有积极意义的。\n\n　　此诗与《赤壁》诗一样，议论战争成败之理，提出自己对历史上已有结局的战争的假设性推想。首句言胜败乃兵家常事。次句批评项羽胸襟不够宽广，缺乏大将气度。三四句设想项羽假如回江东重整旗鼓，说不定就可以卷土重来。这句有对项羽负气自刎的惋惜，但主要的意思却是批评他不善于把握机遇，不善于听取别人的建议，不善于得人、用人。司马迁曾以史家眼光批评项羽“天亡我，非战之罪”的执迷不悟。杜牧则以兵家的眼光论成败由人之理。二人都注重人事，但司马迁是总结已然之教训，强调其必败之原因；杜牧则是假想未然之机会，强调兵家须有远见卓识和不屈不挠的意志。\n\n　　议论不落传统说法的窠臼，是杜牧咏史诗的特色。诸如“东风不与周郎便，铜雀春深锁二乔”（《赤壁》），“南军不袒左边袖，四老安刘是灭刘”（《题商山四皓庙》），都是反说其事，笔调都与这首诗类似。这首诗借题发挥，宣扬百折不挠的精神，是可取的。', poem_tags = '咏史怀古,励志' WHERE poem_title = '题乌江亭' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '一层雪压在松枝上，仔细看一看，这青松又高又直。\n要想知道这青松有多么纯洁多么高大，那就要等到树上那层厚厚的雪化了之后才能看到。', poem_appreciation = '《青松》一题，是《冬夜杂咏》中的首篇。《冬夜杂咏》这一组诗最初发表于《诗刊》1962年第一期上。共12题19首，这里选其中一首。发表时有小序云：一九六〇年冬夜大雪，长夜不寐。起坐写小诗若干段，寄兴无端，几乎零乱。迄今事满一年，不复诠次。（诠次，选择、归类及排列的意思。）送登《诗刊》，以博读者一粲。（粲，形容笑的样子。）一九六一年十二月一日仲弘记。（仲弘，是陈毅的字。）作者借物咏怀，表面写松，其实写人。写人坚忍不拔、宁折不弯的刚直与豪迈，写那个特定时代不畏艰难、雄气勃发、愈挫弥坚的精神。作者写松是把它放在一个严酷的环境中，一个近乎剑拔弩张的气氛中，我们看到了雪的暴虐，感受到松的抗争。我们似乎像松一样承受压迫，又像松一样挺直起来。那冷峻峭拔的松的形象，因为充溢其中的豪气激荡其中的力量而挺直起来。在压与挺的抗争中，我们似乎同时经历了一场灵魂的涤荡，因为在这种抗争中，展现了那个时代飞扬凌厉的热情，展现了作者那令人起敬的人格力量。 　\n\n　　读这首诗，总让人想起陈总的形象。想起那刚毅的面孔。勃发的神采，光明磊落的胸襟，刚直不阿、任何时候也不肯向恶势力低头的人格。真是文若其人。如果说：“问苍茫大地，谁主沉浮”的诗句充溢着一种帝王之气，那么“大雪压青松，青松挺且直”的诗句也只有刚傲沉毅、满怀将帅气度的陈毅能够写出来！也许作者在这里的主要目的不是抒写个人。冬夜大雪，作者辗转难眠。1960年那是全国人民都在经受考验的时期。特大的自然灾害，党的工作失误，赫鲁晓夫修正主义集团背信弃义，帝修联合反华，正使中国内外交困。正是黑云压城城欲摧的时候，作者作为国内领导人，胸怀的是祖国的命运，承受的是民族的困厄，他考虑的是决不能丧失民族气节，不能丧失原则和立场，向各种反华势力妥协。而这时，全国人民正紧密地团结在党中央周围，以大无畏的革命英雄主义精神迎接困难，战胜困难，顶住了世界性的修正主义的逆流。“大雪压青松，青松挺且直”正是对我们的党和人民，对雄气勃发的时代精神的盛赞。也许正是作者人格和时代精神相互融合，内外互动，共同投射在青松这个特定的象喻上，才使这首诗有一股凛然大气，读来令人感动。', poem_tags = '冬天,咏物,松树' WHERE poem_title = '青松' AND poem_author = '陈毅';
UPDATE edu_poem SET poem_translation = '一座高桥隔着云烟出现，在岩石的西畔询问渔船。\n桃花整天随着流水流淌，桃源洞口在清溪的哪边？', poem_notes = '桃花溪：水名，在湖南省桃源县桃源山下。\n飞桥：高桥。\n石矶：水中积石或水边突出的岩石、石堆。渔船：源自陶渊明《桃花源记》中语句。\n尽日：整天，整日。\n洞：指《桃花源记》中武陵渔人找到的洞口。', poem_appreciation = '这首诗通过描写桃花溪幽美的景色和作者对渔人的询问，抒写一种向往世外桃源，追求美好生活的心情。\n\n　　桃花溪两岸多桃林，暮春时节，落英缤纷，溪水流霞。相传东晋陶渊明的《桃花源记》就是以这里为背景的。张旭描写的桃花溪，虽然不一定是指这里，但却暗用其意境。此诗构思婉曲，情趣深远，画意甚浓。\n\n　　“隐隐飞桥隔野烟”，起笔写远景：深山野谷，云烟缭绕；透过云烟望去，那横跨山溪之上的长桥，忽隐忽现，似有似无，恍若在虚空里飞腾。这境界多么幽深、神秘，令人朦朦胧胧，如入仙境。在这里，静止的桥和浮动的野烟相映成趣：野烟使桥化静为动，虚无缥缈，临空而飞；桥使野烟化动为静，宛如垂挂一道轻纱帏幔。隔着这帏幔看桥，使人格外感到一种朦胧美。“隔”字，使这两种景物交相映衬，溶成一个艺术整体；“隔”字还暗示出诗人是在远观，若是站在桥边，就不会有“隔”的感觉了。\n\n　　下面画近景。近处，水中露出嶙峋岩石，如岛如屿（石矶）；那飘流着片片落花的溪上，有渔船在轻摇，景色清幽明丽。“石矶西畔问渔船”，一个“问”字，诗人也自入画图之中了，使读者从这幅山水画中，既见山水之容光，又见人物之情态。诗人伫立在古老的石矶旁，望着溪上飘流不尽的桃花瓣和渔船出神，恍惚间，他似乎把眼前的渔人当作当年曾经进入桃花源中的武陵渔人。那“问”字便脱口而出。\n\n　　“问渔船”三字，逼真地表现出这种心驰神往的情态。三、四句，是问讯渔人的话：但见一片片桃花瓣随着清澈的溪水不断漂出，却不知那理想的世外桃源洞在清溪的什么地方呢？这里，桃源洞的美妙景色，是从问话中虚写的，诗人急切向往而又感到渺茫难求的心情，也是从问话中委婉含蓄地透露出来的。\n\n　　七言绝句篇幅短小，要做到情韵悠长，意境深邃，除了讲究炼字琢句外，更要求构思的巧妙。张旭作为盛唐的一位七绝名家，是很善于构思的。这首诗从远到近，正面写来，然后用问讯的方式运实入虚，构思布局相当新颖巧妙。作者的笔触又轻快洒脱，对景物不作繁琐的描写，不敷设明艳鲜丽的色彩，对《桃花源记》的意境也运用得空灵自然、蕴藉不觉，从而创造了一个饶有画意、充满情趣的幽深境界。', poem_tags = '唐诗三百首,写水,写景,抒情' WHERE poem_title = '桃花溪' AND poem_author = '张旭';
UPDATE edu_poem SET poem_tags = '爱情,组诗' WHERE poem_title = '无题二首' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '夜已经深了，香炉里的香早已经燃尽，漏壶里的水也快漏完了。后半夜的春风给人带来阵阵的寒意。\n然而春天的景色却使人心烦意乱，只看见随着月亮的移动，花木的影子悄悄地爬上了栏杆。', poem_notes = '漏：古代计时用的漏壶。\n翦翦：形容初春的寒风削面，尖刻刺骨。', poem_tags = '古诗三百首,春天,写景,抒情,思念' WHERE poem_title = '春夜' AND poem_author = '王安石';
UPDATE edu_poem SET poem_translation = '雾迷蒙，楼台依稀难辨，月色朦胧，渡口也隐匿不见。望尽天涯，理想中的桃花源，无处觅寻。怎能忍受得了独居在孤寂的客馆，春寒料峭，斜阳西下，杜鹃声声哀鸣！\n远方的友人的音信，寄来了温暖的关心和嘱咐，却平添了我深深的别恨离愁。郴江啊，你就绕着你的郴山流得了，为什么偏偏要流到潇湘去呢？', poem_notes = '踏莎行：词牌名。\n郴（chēn）州：今属湖南。\n雾失楼台：暮霭沉沉，楼台消失在浓雾中。\n月迷津渡：月色朦胧，渡口迷失不见。\n桃源望断无寻处：拼命寻找也看不见理想的桃花源。桃源：语出晋陶渊明《桃花源记》，指生活安乐、合乎理想的地方。无寻处：找不到。\n可堪：怎堪，哪堪，受不住。\n杜鹃：鸟名，相传其鸣叫声像人言“不如归去”，容易勾起人的思乡之情。\n驿寄梅花：陆凯在《赠范晔诗》：“折梅逢驿使，寄与陇头人。江南无所有，聊寄一枝春。”这里作者是将自己比作范晔，表示收到了来自远方的问候。\n鱼传尺素：东汉蔡邕的《饮马长城窟行》中有“客从远方来，遗我双鲤鱼。呼儿烹鲤鱼，中有尺素书。” 另外，古时舟车劳顿，信件很容易损坏，古人便将信件放入匣子中，再将信匣刻成鱼形，美观而又方便携带。“鱼传尺素”成了传递书信的又一个代名词。这里也表示接到朋友问候的意思。\n砌：堆积。无重数：数不尽。\n郴江：清顾祖禹《读史方舆纪要·湖广》载：郴水在“州东一里，一名郴江，源发黄岑山，北流经此……下流会来水及自豹水入湘江。”幸自：本自，本来是。\n为谁流下潇湘去：为什么要流到潇湘去呢？意思是连郴江都耐不住寂寞何况人呢？为谁：为什么。潇湘，潇水和湘水，是湖南境内的两条河流，合流后称湘江，又称潇湘。', poem_appreciation = '“雾失楼台，月迷津渡，桃源望断无寻处”，写夜雾笼罩一切的凄凄迷迷的世界：楼台茫茫大雾中消失；渡口被朦胧的月色所隐没；那当年陶渊明笔下的桃花源更是云遮雾障，无处可寻了。当然，这是作者意想中的景象，因为紧接着的两句是“可堪孤馆闭春寒，杜鹃声里斜阳暮”。词人闭居孤馆，只有想象中才能看得到“津渡”。\n\n　　而从时间上来看，上句写的是雾蒙蒙的月夜，下句时间又倒退到残阳如血的黄昏时刻。由此可见，这两句是实写诗人不堪客馆寂寞，而头三句则是虚构之景了。这里词人运用因情造景的手法，景为情而设，意味深长。“楼台”，令人联想到的是一种巍峨美好的形象，而如今被漫天的雾吞噬了：“津渡”，可以使人产生指引道路、走出困境的联想，而如今朦胧夜色中迷失不见了开头三句，分别下了“失”、“迷”、“无”三个否定词，接连写出三种曾经存过或人们的想象中存过的事物的消失，表现了一个屡遭贬谪的失意者的怅惘之情和对前途的渺茫之感。\n\n　　而“可堪孤馆闭春寒，杜鹃声里斜阳暮。”两句则开始正面实写词人羁旅郴州客馆不胜其悲的现实生活。一个“馆”字，已暗示羁旅之愁。说“孤馆”则进一步点明客舍的寂寞和客子的孤单。而这座“孤馆”又紧紧封闭于春寒之中，置身其间的词人其心情之凄苦就可想而知了。此时此刻，又传来杜鹃的阵阵悲鸣；那惨淡的夕阳正徐徐西下，这景象益发逗引起词人无穷的愁绪。杜鹃鸣声，是古典诗词中常用的表游子归思的意象。以少游一个羁旅之身，所居住的是寂寞孤馆，所感受的是料峭春寒，所听到的是杜鹃啼血，所见到的是日暮斜阳，此情此境，只能以“可堪”道之。\n\n　　“可堪”者，岂堪也，词人这重重凄厉的气围中，又怎能忍受得了呢？过片“驿寄梅花，鱼传尺素，砌成此恨无重数。”连用两则友人投寄书信的典故，极写思乡怀旧之情。“驿寄梅花”，见于《荆州记》记载：“鱼传尺素”，是用古乐府《饮马长城窟》诗意，意指书信往来。少游是贬谪之人，北归无望，亲友们的来书和馈赠，实际上并不能给他带来丝毫慰藉，而只能徒然增加他别恨离愁而已。\n\n　　因此，书信和馈赠越多，离恨也积得越多，无数“梅花”和“尺素”，仿佛堆砌成了“无重数”的恨。词人这种感受是很深切的，而这种感受又很难表现，故词人手法创新，只说“砌成此恨无重数”。有这一“砌”字，那一封封书信，一束束梅花，便仿佛成了一块块砖石，层层垒起，以至于达到“无重数”的极限。这种写法，不仅把抽象的微妙的感情形象化，而且也可使人想象词人心中的积恨也如砖石垒成，沉重坚实而又无法消解。\n\n　　如此深重难排的苦恨中，迸发出最后二句：“郴江幸自绕郴山，为谁流下潇湘去？”从表面上看，这两句似乎是即景抒情，写词人纵目郴江，抒发远望怀乡之思。郴江出山后，向北流入耒水，又北经耒阳县，至衡阳而东流入潇水湘江。但实际上，一经词人点化，那山山水水都仿佛活了，具有了人的思想感情。这两句由于分别加入了“幸自”和“为谁”两个字，无情的山水似乎也能听懂人语，词人痴痴问询郴江：你本来生活自己的故土，和郴山欢聚一起，究竟为了谁而竟自离乡背井，“流下潇湘去”呢？', poem_tags = '宋词三百首,高中古诗,婉约,孤独,思念' WHERE poem_title = '踏莎行·郴州旅舍' AND poem_author = '秦观';
UPDATE edu_poem SET poem_translation = '男子汉大丈夫为什么不腰带武器去收取关山五十州呢？\n请你且登上那画有开国功臣的凌烟阁去看，又有哪一个书生曾被封为食邑万户的列侯？', poem_notes = '吴钩：吴地出产的弯形的刀，此处指宝刀。\n凌烟阁：唐太宗为表彰功臣而建的殿阁，上有秦琼等二十四人的像。', poem_appreciation = '这首诗由两个设问句组成，顿挫激越，而又直抒胸臆，把家国之痛和身世之悲都淋漓酣畅地表达出来了。\n\n　　第一个设问是泛问，也是自问，含有“国家兴亡，匹夫有责”的豪情。“男儿何不带吴钩”，起句峻急，紧连次句“收取关山五十州”，犹如悬流飞瀑，从高处跌落而下，显得气势磅礴。“带吴钩”指从军的行动，身佩军刀，奔赴疆场，那气概多么豪迈！“收复关山”是从军的目的，山河破碎，民不聊生，诗人怎甘蛰居乡间，无所作为呢？因而他向往建功立业，报效国家。一、二两句，十四字一气呵成，节奏明快，与诗人那昂扬的意绪和紧迫的心情十分契合。首句“何不”二字极富表现力，它不只构成了特定句式（疑问），而且强调了反诘的语气，增强了诗句传情达意的力量。诗人面对烽火连天、战乱不已的局面，焦急万分，恨不得立即身佩宝刀，奔赴沙场，保卫家邦。“何不”云云，反躬自问，有势在必行之意，又暗示出危急的军情和诗人自己焦虑不安的心境。此外，它还使人感受到诗人那郁积已久的愤懑情怀。李贺是个书生，早就诗名远扬，本可以才学入仕，但这条进身之路被“避父讳”这一封建礼教无情地堵死了，使他没有机会施展自己的才能。“何不”一语，表示实在出于无奈。次句一个“取”字，举重若轻，有破竹之势，生动地表达了诗人急切的救国心愿。然而“收取关山五十州”谈何容易？书生意气，自然成就不了收复关山的大业，而要想摆脱眼前悲凉的处境，又非经历戎马生涯，杀敌建功不可。这一矛盾，突出表现了诗人愤激不平之情。\n\n　　“请君暂上凌烟阁，若个书生万户侯？”诗人问道：封侯拜相，绘像凌烟阁的，哪有一个是书生出身？这里诗人又不用陈述句而用设问句，牢骚的意味显得更加浓郁。看起来，诗人是从反面衬托投笔从戎的必要性，实际上是进一步抒发了怀才不遇的愤激情怀。由昂扬激越转入沉郁哀怨，既见出反衬的笔法，又见出起伏的节奏，峻急中作回荡之姿。就这样，诗人把自己复杂的思想感情表现 在诗歌的节奏里，使读者从节奏的感染中加深对主题的理解、感受。\n\n　　李贺《南园》组诗，多就园内外景物讽咏，以写其生活与感情。但此首不借所见发端，却凭空寄慨，于豪情中见愤然之意。盖只是同时所作，拉杂汇编，不能以题目限的。（朱世英）', poem_tags = '地名,爱国,励志' WHERE poem_title = '南园十三首·其五' AND poem_author = '李贺';
UPDATE edu_poem SET poem_translation = '我常常想起钱塘江观潮的情景，满城的人争着向江上望去。潮水涌来时，仿佛大海都空了，潮声像一万面鼓齐发，声势震人。\n踏潮献技的人站在波涛上表演，他们手里拿着的红旗丝毫没被水打湿。此后几次梦到观潮的情景，梦醒时依然感觉心惊胆战。', poem_notes = '酒泉子：原为唐教坊曲，以酒泉郡地名作曲名，后用为词牌名。《金奁集》入“高平调”。有两体，一为温庭筠体，为词牌正格；二为潘阆体，又名《忆余杭》。\n长：通假字，通“常”，常常、经常。\n郭：外城，这里指外城以内的范围。\n万面鼓声中：将潮来时，潮声像万面金鼓，一时齐发，声势震人。\n弄潮儿：指朝夕与潮水周旋的水手或在潮中戏水的少年人。喻有勇敢进取精神的人。\n向：朝着，面对\n红旗：红色的旗帜。\n觉：睡醒。\n尚：还（hái），仍然。\n心寒：心里感觉很惊心动魄。', poem_appreciation = '词的上片描写观潮盛况，表现大自然的壮观、奇伟；起首两句，写杭州人倾城而出，拥挤钱塘江边，万头攒动，争看江面潮水上涨。为下面潮水的涌现制造了气氛，作好了铺垫。上片结尾两句，运用比喻、夸张等手法，把钱江潮涌的排山倒海、声容俱壮，渲染得有声有色、惊险生动。\n\n　　下片描写弄潮情景，表现弄潮健儿与大自然奋力搏斗的大无畏精神，抒发出人定胜天的豪迈气概。过片转而描写弄潮儿的英勇无畏、搏击风浪、身手不凡和履险如夷。这两句纯用白描手法，写得有声有色，富于动感，眩目惊心。结拍由回忆转为现实，写词人虽离杭已久，但那壮观的钱江涌潮仍频频入梦，以至梦醒后尚感惊心动魄。\n\n　　此词对于钱塘江涌潮的描绘，可谓匠心独远，别具神韵。词中“来疑沧海尽成空”一句采用夸张手法，浓墨重彩，大开大阖，感染力甚强。上片第二句的“争”、“望”二字，生动地表现了人们盼潮到来的殷切心情，从空间广阔的角度进行烘托与大潮的壮观结合得甚为密切。结拍言梦醒后尚心有余悸，更深化了潮水的雄壮意象。前后的烘托与中间重点描写当中的夸张手法配合紧密，使全词的结构浑然一体。', poem_tags = '宋词三百首,豪放,景点' WHERE poem_title = '酒泉子·长忆观潮' AND poem_author = '潘阆';
UPDATE edu_poem SET poem_translation = '当年在曲折的回廊深处，我再一次与你相逢。我怜惜地将你轻轻拥人怀中。两人深隋相偎，低语呢喃，互述久别后的相思情意。在我的怀里，你的身体微微颤动，轻轻擦拭着滴落的晶莹泪水，让人无限地怜惜。而今，记忆中的美妙已成别后的凄凉。\n分别后只觉得半生孤苦，枕上早已是泪痕点点。最是凄凉清冷，在寂静月明时分；最是害怕忆起，那时与你一起泼墨画罗裙。', poem_notes = '虞美人：词牌名。此调原为唐教坊曲，初咏项羽宠姬虞美人，因以为名。又名《一江春水》、《玉壶水》、《巫山十二峰》等。双调，五十六字，上下片各四句，皆为两仄韵转两平韵。\n匀泪：拭泪。全句指在情人的怀中颤抖着搽拭眼泪。\n不胜清怨：指难以忍受的凄清幽怨。唐钱起《归雁》：“二十五弦弹夜月，不胜清怨却飞来。”不胜：承受不了。清怨：凄清幽怨。\n分（fèn）：料想。\n山枕：枕头。两端凸起中间低凹的山形枕头。\n檀痕，浅红色的泪痕。是说沾上胭脂的泪痕。\n涴（wò）：浸渍、染上。枕头上浸渍了粉红色的泪痕。\n销魂：极度的愁苦或欢乐。\n折枝，中国花卉画技法，即不画全株，只画连枝折下的部分。宋仲仁《华光梅谱·取象》：“……其法有僵仰枝、覆枝、从枝、分枝、折枝。”\n花样：供仿制的式样。罗裙：丝罗织成的裙子，多泛指妇女衣裙。', poem_appreciation = '这首词以白描的手法再现情人重聚时的情景，字句间一片春光凄凉。\n\n　　从词意上看，大约是写昔日的情人，通篇皆作追忆的口吻。“曲阑深处重相见，匀泪偎人颤。”开篇两句化用了李煜《菩萨蛮》中的“画堂南畔见，一向偎人颤”，生动传神。别后的凄凉，最难以忍受的是月明之夜的清冷相思。读来令人摇心动魄。\n\n　　“凄凉别后两应同，最是不胜清怨月明中”。词意陡转，道破这原是记忆中的美妙而已，现在已是别后凄凉。凄清幽怨到让人不堪承受。\n\n　　“半生已分孤眠过”，紧承词意，将失意一倾到底，用词精美婉约，凄怆词意并未因而消减，依然辛酸入骨。\n\n　　结句处的“折枝花样画罗裙”，借物映人，含蓄委婉。整首词从头到尾都是写实，写对方的情态状貌，中间数句皆是情语，有情有景，有尽而不尽之意，通体灵活隽美。', poem_tags = '离别,相思' WHERE poem_title = '虞美人·曲阑深处重相见' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '听说山上的梅花已经迎着晨风绽开，四周大山的山坡上一树树梅花似雪洁白。\n有什么办法可以把我的身子也化为几千几亿个？让每一棵梅花树前都有一个陆游常在。', poem_notes = '闻道：听说。坼（chè）：裂开。这里是绽开的意思。\n雪堆:指梅花盛开像雪堆似的。\n何方：有什么办法。千亿：指能变成千万个放翁(陆游号放翁，字务观)。\n梅花：一作梅前。\n坼晓风：（梅花)在晨风中开放。', poem_tags = '古诗三百首,咏物,梅花,抒怀' WHERE poem_title = '梅花绝句·其一' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '楚国有个祭祀的官员，给手下办事的人一壶酒和酒具。门客们互相商量说：“几个人喝这壶酒不够，一个人喝这壶酒才有剩余。请大家在地上画蛇，先画成的人喝酒。”\n一个人先把蛇画好了。他拿起酒壶准备饮酒，就左手拿着酒壶，右手画蛇，说：“我能够给蛇添上脚！”没等他画完，另一个人的蛇画成了，夺过他的酒说：“蛇本来没有脚，你怎么能给它添上脚呢？”于是就把壶中的酒喝了下去。\n那个给蛇画脚的人最终失掉了那壶酒。', poem_notes = '祠（cí）：祭祀。周代贵族一年四季都要祭祀祖宗，每个季度祭祀都有专门的称呼，春天祭祀叫“祠”。祠者：主管祭祀的官员。\n舍人：门客，手下办事的人。\n卮（zhī）：古代的一种盛酒器，类似壶。\n相谓：互相商议。\n请画地为蛇：要求大家在地上画蛇。画地：在地面上画（画的过程）。为蛇：画蛇。\n引酒且饮之：拿起酒壶准备饮酒。引：拿，举。且:将要\n蛇固无足：蛇本来就没有脚。固：本来，原来。\n子：对人的尊称，您；你。\n安能：怎能；哪能。\n为：给；替。\n遂：于是；就。\n赐：赏给，古代上给下，长辈给晚辈送东西叫赐。\n为之足：给它画上脚。足：画脚。\n终：最终、最后。\n引：拿起。\n成：完成。\n余：剩余。\n足：（画）脚。\n亡：丢失，失去。\n为：给，替。\n乃左手持卮：然后\n夺其卮曰：他的，指代先成蛇者\n遂饮其酒：他的，指示代词\n终亡其酒：那，指示代词\n谓:对......说。\n祠：祭祀。周代贵族一年四季都要祭祀祖宗，每个季度祭祀都有专门的称呼，春天祭祀叫“祠”。\n终亡其酒：失去', poem_appreciation = '这个故事告诉人们，蛇本来没有脚，先画成蛇的人，却将蛇添了脚，结果不成为蛇。后遂用画蛇添足，比喻节外生枝，告诉人们做任何事都要实事求是，不卖弄聪明，否则非但不能把事情做好，反而会把事情弄砸。名著《三国演义》第一百一十回：“张翼谏曰：“将军战绩已成，威声大震，可以止矣，今若前进，倘不如意，正如画蛇添足也。”告诉人们做任何事都要实事求是，不卖弄聪明，否则非但不能把事情做好，反而会把事情弄砸。\n\n　　不论对国家、人民或自己，都具有安全性。这个故事的意义是肤浅的，“画蛇添足”的教训，值得我们记取。不要因为一个小小的错误而丧失了自己本该有的东西。“ 为蛇足者，终亡其酒。“，真是可惜！', poem_tags = '小学文言文,寓言,故事,哲理' WHERE poem_title = '画蛇添足' AND poem_author = '刘向';
UPDATE edu_poem SET poem_translation = '大自然虽然默默无言，但却有情，寒尽而带来春天，悄悄地安排好万紫千红的百花含苞待放\n大自然早已安排好了万紫千红，只等春雷一响，百花就将竞相开放。', poem_notes = '新雷：春天的第一个雷声，象征春天的莅临。古人认为雷是动生万物的\n造物：指天。古人认为天是创造万物的\n每于：常常在。', poem_appreciation = '这首诗平顺自然，没有难词拗句，比较容易领会。在艺术构思上，诗人却匠心独运，使诗歌的表达手段有了新意。\n\n　　首先，诗人的移情手法，赋予自然界具有人的情感活动和思维能力。“造物无言却有情”，作为造物者的天，即自然界，本来并不具有人类的情感和思维。诗人笔下，自然界不但能思维，而且在不言不语之中，饱含着对人类的感情。这表现在害怕寒冷的人类，在最难熬的时刻，自然界会冬去春来，带来温暖。不仅如此，还刻意安排了万紫千红的百花，来愉悦人类、安慰人类。这一切，只等一声春雷炸响之后，就出现了。自然四时运行，本来是自然界的规律，无情绪可言。诗人有意识地把人类的情绪活动外射到自然界中，使自然界具有与诗人共鸣的思想感情活动。因此，诗人笔下的自然，实际上是诗人思绪改造过了的自然。在这个自然画面上，寄托了诗人对于一种新的社会环境，新的生活气氛的追求和仰慕，也启示了读者对更新更高尚美好生活的渴望。\n\n　　其次，诗人在处理全诗情绪的转换时，巧妙地利用最富于孕育性的时刻这一美学手段。诗人不写新雷之后满目欢愉的情形，而集中写新雷炸响前夕，万物俱备而万物俱待这一关键时刻，使画面更富悬念，更具戏剧色彩。因为造物有情，寒尽春生，千红万紫的百花正含苞待放，自然界一时间仿佛处于静止的等待之中。这是巨大变化前夕的平静，是第一声春雷炸响前的寂静。所以，平静、寂静之中，蕴藏着即将爆发的巨变。在人们的情绪上，只有这样的时刻，最令人紧张，也最富于想象力。诗人抓住了第一声春雷炸响前夕这个富于孕育性的时刻，更能表达他对春天的渴望，对新的生活环境的渴望。\n\n　　因为诗人巧妙运用了移情手法和富于孕育性的时刻，来描写冬尽春来一时间情绪的波澜，诗歌虽然短小，却隽永清新，为人传唱。', poem_tags = '赞颂,大自然,春天' WHERE poem_title = '新雷' AND poem_author = '张维屏';
UPDATE edu_poem SET poem_translation = '大田鼠呀大田鼠，不许吃我种的黍！多年辛勤伺候你，你却对我不照顾。发誓定要摆脱你，去那乐土有幸福。那乐土啊那乐土，才是我的好去处！\n　　大田鼠呀大田鼠，不许吃我种的麦！多年辛勤伺候你，你却对我不优待。发誓定要摆脱你，去那乐国有仁爱。那乐国啊那乐国，才是我的好所在！\n　　大田鼠呀大田鼠，不许吃我种的苗！多年辛勤伺候你，你却对我不慰劳！发誓定要摆脱你，去那乐郊有欢笑。那乐郊啊那乐郊，谁还悲叹长呼号！', poem_notes = '硕鼠：大老鼠。一说田鼠。\n无：毋，不要。黍：黍子，也叫黄米，谷类，是重要粮食作物之一。\n三岁：多年。三，非实数。贯：借作“宦”，侍奉。\n逝：通“誓”。去：离开。女：同“汝”。\n爰：于是，在此。所：处所。\n德：恩惠。\n国：域，即地方。\n直：王引之《经义述闻》说：“当读为职，职亦所也。”一说同值。\n劳：慰劳。\n之：其，表示诘问语气。号：呼喊。', poem_appreciation = '《硕鼠》全诗三章，意思相同。三章都以“硕鼠硕鼠”开头，直呼奴隶主剥削阶级为贪婪可憎的大老鼠、肥老鼠，并以命令的语气发出警告：“无食我黍（麦、苗）！”老鼠形象丑陋又狡黠，性喜窃食，借来比拟贪婪的剥削者十分恰当，也表现诗人对其愤恨之情。三四句进一步揭露剥削者贪得无厌而寡恩：“三岁贯女，莫我肯顾（德、劳）。”诗中以“汝”、“我”对照：“我”多年养活“汝”，“汝”却不肯给“我”照顾，给予恩惠，甚至连一点安慰也没有，从中揭示了“汝”、“我”关系的对立。这里所说的“汝”、“我”，都不是单个的人，应扩大为“你们”、“我们”，所代表的是一个群体或一个阶层，提出的是谁养活谁的大问题。后四句更以雷霆万钧之力喊出了他们的心声：“逝将去女，适彼乐土；乐土乐土，爰得我所！”诗人既认识到“汝我”关系的对立，便公开宣布“逝将去女”，决计采取反抗，不再养活“汝”。一个“逝”字表现了诗人决断的态度和坚定决心。尽管他们要寻找的安居乐业、不受剥削的人间乐土，只是一种幻想，现实社会中是不存在的，但却代表着他们美好的生活憧憬，也是他们在长期生活和斗争中所产生的社会理想，更标志着他们新的觉醒。正是这一美好的生活理想，启发和鼓舞着后世劳动人民为挣脱压迫和剥削不断斗争。\n\n　　这首诗纯用比体，《诗经》中此类诗连同此篇只有三首，另外两首是《周南·螽斯》、《豳风·鸱鸮》。这三首的共同特点就是以物拟人，但此篇稍有不同。另两篇可以看作寓言诗，通篇比喻，寓意全在咏物中。此篇以硕鼠喻剥削者虽与以鸱鸮喻恶人相同，但《鸱鸮》中后半仍以鸟控诉鸱鸮展开，寓意包含在整体形象中，理解易生分歧；而此篇后半则是人控诉鼠，寓意较直，喻体与喻指基本是一对一的对应关系，《诗序》认为老鼠“贪而畏人”，重敛者“蚕食于民……若大鼠也”，对寓意的理解与两千年后的今人非常相近，其理就在此。', poem_tags = '古诗三百首,诗经,寓理' WHERE poem_title = '国风·魏风·硕鼠' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '南方地区有很多生长茂盛的树木，这些树木中有下垂的树枝，葛藟爬上这根树枝，并在这根树枝上快乐的生长蔓延。一位快乐的君子，他能够用善心或善行去安抚人或使人安定。\n\n南方地区有很多生长茂盛的树木，这些树木中有下垂的树枝，葛藟爬上这根树枝，在这根树枝上快乐的生长蔓延，并且这根樛木都被葛藟覆盖了。一位快乐的君子，能够用善心或善行去扶助他人\n\n南方地区有很多生长茂盛的树木，这些树木中有下垂的树枝，好几根葛藟爬上这根树枝，缠绕在这根树枝上快乐的生长蔓延。一位快乐的君子，能够用善心或善行去成就他人。', poem_notes = '这是一首祝贺新婚的民歌。诗人先以葛藟缠绕樛木，比喻女子嫁给丈夫。然后为新郎祝福，希望他能有幸福、美满的生活。诗凡三章，每章只改易二字，句式整饬，以群歌叠唱的形式表达出喜庆祝颂之情。\n樛（jiū）：下曲而高的树。\n葛（gé）藟（lěi）：多年生草本植物，花紫红色，茎可做绳，纤维可织葛布。藟似葛，野葡萄之类。\n累：攀缘，缠绕。此处又作纍。\n只：语气助词。\n君子：此处指结婚的新郎。\n福履：福禄，幸福。后妃能逮下而无嫉妒之心，故众妾乐其德而称愿之曰：南有樛木，则葛藟累之矣，乐只君子，则福履绥之矣。\n绥：安定，安抚人心的意思。\n荒：覆盖。\n将：扶助；或释为“大”。朱熹：《诗经集注》将，犹扶助也。\n萦（yíng 营）：回旋缠绕。《康熙字典》：玉篇萦，旋也。广韵 绕也。\n成：就；到来。', poem_appreciation = '从“祝贺新婚”方面的鉴赏\n\n　　《诗经》中的“兴”语往往兼有“比”义，《樛木》就是如此。“兴”者起也，“先咏他物以引起所咏之词也”（朱熹《诗集传》）。从这一解说看，“乐只君子，福履绥之”二句，乃是首章所咏之本体；“南有樛木，葛藟累之”二句，则是引起所咏之词的“兴”体。后二章每章只改动二字，大体意思与首章相近，运用的是“国风”常用的“叠章”形式。以反覆咏唱逐层推进，在回环往复中造成浓浓的感情。故从“兴”之引起的“所咏之词”看，这乃是一首为“君子”祝“福”的歌，当无可疑。\n\n　　而这三章中的“兴”语，同时又带有“比”义。“比者，以彼物比此物也”。诗中的“彼物”即“樛木”和“葛藟”，“此物”则是“君子”和“福”——以樛木的得到葛藟缠绕，比君子的常得福禄相随，也实在非常形象。故从各章之“比”义看，这也是一首形象动人的祝福歌。\n\n　　所以透过诗经比兴的手法，从中可以还原在三千多年前一场婚礼宴席上：秋日的黄昏宾客毕集，辘辘的车音自远而近。性急的孩童早从村口奔来，嚷叫着：“接新娘的车子到啦！”欢乐的鼓吹由此压过喜悦的喧声齐鸣。当幸福的“君子”搀扶新娘下车的时候，迎接他们的，便是青年男女们一遍又一遍的热烈歌唱：“南有樛木，葛藟累之。乐只君子，福履绥之……”\n\n　　于是，用“南有樛木，葛藟累之（荒之、萦之）”来比拟、形容新郎新娘的喜悦和美满以及当时的情景，是十分贴切的，也体现了《诗经》表达感情克制而平和的优雅。数次的叠唱将在众宾客心间的祝福之情宣泄的兴奋和浓烈，而《樛木》，正以如此兴奋和浓烈的激情，表现了我们民族淳朴、古老的婚礼祝福习俗。\n\n　　乐只君子，福履绥之，此处的“福”究竟在赞颂什么，诗中的比兴之物给了我们判断的方向。“国风”比兴，常以花草、藤蔓、雌鸟、牝兽喻女子，而以高木、日月、雄狐之类喻男子。其中尤以树木喻男、花草喻女更为常见。如《邶风·简兮》的“山有榛，隰有苓。云谁之思？西方美人”；又如《郑风·山有扶苏》的“山有扶苏，隰有荷华。不见子都，乃见狂且”，都是如比。至于《唐风·葛生》叙妻子对亡夫的哀恋，更有“葛生蒙楚（荆树），蔹蔓于野。予美亡此，谁与独处”之语，以葛藤与荆木的相互依存，抒写了女主人公失去夫君的凄伤之情。通过对这一特点的掌握，则《樛木》进一层的比兴之义亦可迎刃而解：倘若此诗中的“樛木”，喻的是青年男子的话，那么缠绕樛木的翠绿“葛藟”，即比喻着他的美丽新娘。故《毛诗序》旧说：以为此乃歌咏“后妃”“能逮下而无嫉妒之心焉”之作，为对诗歌原意的误读；而方玉润《诗经原始》、王先谦《诗三家义集疏》推测此诗“似于夫妇为近”、“喻妇人之托夫家也”，才真正猜着了这首祝福诗的旨意。\n\n其他方面的鉴赏\n\n　　有的学者认为这首诗讲了一位君子在没有嫉妒心之后的所作所为，也就是看到别人有优点的时候，真心的为别人高兴，看到别人有困难或不足的时候，无私的给予帮助和补充，“君子成人之美“。诗描绘了三幅画面：\n\n　　“南有樛木，葛藟纍之。乐只君子，福履绥之。”你是南山一棵弯弯木，由我葛藤来牵附。快乐着的君子呀，一定能安享大福禄。（葛藤是樛木的保护伞）\n\n　　朱熹曰：“兴者，先言他物以引起所咏之词也“ 。本诗还是以“ 樛木“ 及”葛藟“起兴，然后再讲到君子所应该具备的品行。我们看，下垂的树枝（樛木）让葛藟爬上来快乐的生长和蔓延。以之教化人，君子也以帮助别人而快乐。而君子能够这样帮助别人，是因为他没有嫉妒心。\n\n　　“南有樛木，葛藟荒之。乐只君子，福履将之。”南山有棵弯弯木，全靠葛藤来掩护。快乐着的君子呀，福禄离不开葛藤来扶助。（实现福禄靠葛藤）\n\n　　樛木是指下垂的树枝，并不特定指是什么树上的一根下垂的树枝。也许这棵树，它本身的树叶或花朵并没有多少，可是却有好几根葛藟爬到树上，茂盛的生长并开出美丽的花朵，把整根树枝都覆盖了。\n\n　　“南有樛木，葛藟萦之。乐只君子，福履成之。”南山有棵弯弯木，葛藤萦绕作庇护。快乐着的君子呀，一定能实现大福禄。\n\n　　《樛木》这首祝颂君子安享福禄的叙事诗，蕴藏着人际关系的哲理，而这个人际关系的哲理，是借用“葛藟”的特性来完成的，这就是诗中的比兴。从《樛木》这首诗，我们可以看到保护与被保护的作用。尽管你是一棵弯弯木，不能成其大材，但只要有像葛藤一样组成支持你，牵附你的人际网，也能获得福禄。因为葛藤有错综复杂的网状关系，可以逢凶化吉，遇难呈祥。这就是人际关系的作用。因此，“葛藤萦之”是人生通达的途径，不遵循这条途径，就会陷入举步维艰，孤立无援。这里体现了群体的力量，不可忽视。\n\n　　结语：《樛木》这首诗讲了一位君子在没有嫉妒心之后的所作所为，也就是看到别人有优点的时候，真心的为别人高兴，看到别人有困难或不足的时候，无私的给予帮助和补充，孔子曰：“君子成人之美”。', poem_tags = '诗经,祝福' WHERE poem_title = '樛木' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '我踏过江水去采荷花，生有兰草的水泽中长满了香草。\n可是我采了荷花要送给谁呢?我想要送给远方的爱人。\n回头看那一起生活过的故乡，路途显得那么无边无际。\n两心相爱却不能在一起。于是我们要各在一方，愁苦忧伤以至终老异乡。', poem_notes = '芙蓉：荷花的别名。\n兰泽：生有兰草的沼泽地。\n遗（wèi）：赠。\n远道：犹言“远方”。\n还顾：回顾，回头看。\n旧乡：故乡。\n漫浩浩：犹“漫漫浩浩”，形容路途的遥远无尽头。形容无边无际。\n同心：古代习用的成语，多用于男女之间的爱情或夫妇感情融洽指感情深厚。\n终老：度过晚年直至去世。', poem_appreciation = '《涉江采芙蓉》初读时十分单纯，而这”单纯“其实寓于颇微妙的婉曲表现中。初看起来，似乎无须多加解说，即可明白它的旨意，乃在表现远方游子的思乡之情。诗中的“还顾望旧乡，长路漫浩浩”，正把游子对“旧乡”的望而难归之思，抒写得极为凄惋。那么，开篇之“涉江采芙蓉”者，也当是离乡游子了。不过，游子之求宦京师，是在洛阳一带，是不可能去“涉”南方之“江”采摘芙蓉的，而且按江南民歌所常用的谐音双关手法，“芙蓉”（荷花）往往以暗关着“夫容”，明是女子思夫口吻，当不可径指其为“游子”。连主人公的身分都在两可之间，可见此诗并不单纯。不妨先从女子口吻，体味一下它的妙处。\n\n　　夏秋之交，正是荷花盛开的美好季节。在风和日丽中，荡一叶小舟，穿行在“莲叶何田田”、“莲花过人头”的湖泽之上，开始一年一度的采莲活动，可是江南农家女子的乐事。采莲之际，摘几枝红莹可爱的莲花，归去送给各自的心上人，难说就不是妻子、姑娘们真挚情意的表露。何况在湖岸泽畔，还有着数不清的兰、蕙芳草，一并摘置袖中、插上发际、幽香袭人，更教人心醉。——这就是“涉江采芙蓉，兰泽多芳草”两句吟叹，所展示的如画之境。倘若倾耳细听，读者想必还能听到湖面上、“兰泽”间传来的阵阵戏谑、欢笑之声。\n\n　　但这美好欢乐的情景，刹那间被充斥于诗行间的叹息之声改变了。镜头迅速摇近，人们才发现，这叹息来自一位怅立船头的女子。与众多姑娘的嬉笑打诨不同，她却注视着手中的芙蓉默然无语。此刻，“芙蓉”在她眼中幻出了一张亲切微笑的面容——他就是这位女子苦苦思念的丈夫。“采之欲遗谁？所思在远道！”长长的吁叹，点明了这女子全部忧思之所由来：当姑娘们竞采摘着荷花，声言要拣最好的一朵送给“心上人”时，女主人公思念的丈夫，却正远在天涯！她徒然采摘了象征美好的芙蓉，却难以遗送给心上人。人们总以为，倘要表现人物的寂寞、凄凉，最好是将他（她）放在孤身独处的清秋，因为那最能烘托人物的凄清心境。但是否想到，有时将人物置于美好、欢乐的采莲背景上，抒写女主人公独自思夫的忧伤，更具有以“乐”衬“哀”的强烈效果。\n\n　　接着两句空间突然转换，出现在画面上的，似乎已不是拈花沉思的女主人公，而是那身在“远道”的丈夫了：“还顾望旧乡，长路漫浩浩。”是女主人公在想丈夫在干什么，这是古体诗长用手法。而且仿佛是心灵感应似的，正当女主人公独自思夫的时候，她远方的丈夫，此刻也正带着无限忧愁，回望着妻子所在的故乡。他当然不能望见故乡的山水、那在江对岸湖泽中采莲的妻子。此刻展现在他眼间的，无非是漫漫长路，和那阻山隔水的浩浩烟云。许多读者以为，这两句写的是还望“旧乡’的实境，从而产生了诗之主人公乃离乡游子的错觉。实际上，这两句的“视点”仍在江南，表现的依然是那位采莲女子的痛苦思情。不过在写法上，采用了“从对面曲揣彼意，言亦必望乡而叹长途”（张玉谷《古诗赏析》）的“悬想”方式，从面造出了“诗从对面飞来”的绝妙虚境。\n\n　　这种“从对面曲揣彼意”的表现方式，与《诗经》“卷耳”、“陟岵”的主人公，在悬想中显现丈夫骑马登山望乡，父母在云际呼唤儿子的幻境，正有着异曲同工之妙——所以，诗中的境界应该不是空间的转换和女主人公的隐去，而是画面的分隔和同时显现：一边是痛苦的妻子，正手拈芙蓉、仰望远天，身后的密密荷叶、红丽荷花，衬着她飘拂的衣裙，显得那样孤独而凄清；一边则是云烟缥缈的远空，隐隐约约摇晃着返身回望的丈夫的身影，那一闪而隐的面容，竟那般愁苦！两者之间，则是层叠的山峦和浩荡的江河。双方都茫然相望，当然谁也看不见对方。正是在这样的静寂中，天地间幽幽响起了一声凄伤的浩汉：“同心而离居，忧伤以终老！”这浩叹无疑发自女主人公心胸，但因为是在“对面”悬想的境界中发出，读者所感受到的，就不是一个声音：它仿佛来自万里相隔的天南地北，是一对同心离居的夫妇那痛苦叹息的交鸣！这就是诗之结句所传达的意韵。当你读到这结句时，或许能感觉到：此诗抒写的思夫之情虽然那样“单纯”，但由于采取了如此婉曲的表现方式，便如山泉之曲折奔流，最后终于汇成了飞凌山岩的急瀑，震荡起撼人心魄的巨声。\n\n　　上文已经说到，此诗的主人公应该是位女子，全诗所抒写的，乃是故乡妻子思念丈夫的深切忧伤。但倘若把此诗的作者，也认定是这位女子，那就错了。马茂元先生说得好：“文人诗与民歌不同，其中思妇词也出于游子的虚拟。”因此，《涉江采芙蓉》最终仍是游子思乡之作，只是在表现游子的苦闷、忧伤时，采用了“思妇词”的“虚拟”方式：“在穷愁潦倒的客愁中，通过自身的感受，设想到家室的离思，因而把一性质的苦闷，从两种不同角度表现出来”（马茂元《论〈古诗十九首〉》）。从这一点看，《涉江采芙蓉》为表现游子思乡的苦闷，不仅虚拟了全篇的“思妇”之词，而且在虚拟中又借思妇口吻，“悬想”出游子“还顾望旧乡”的情景。', poem_tags = '古诗三百首,古诗十九首,女子,思念' WHERE poem_title = '涉江采芙蓉' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '轻移莲步不再越过横塘路，只有用目力相送，她像芳尘一样飘去。正是青春年华时候，可什么人能与她一起欢度？是月台，是花榭，是雕饰的窗，是紧闭的朱户，这只有春天才会知道她的居处。\n飘飞的云彩舒卷自如，芳草岸旁的日色将暮，挥起彩笔刚刚写下断肠的诗句。若问闲情愁绪有几许？好像一江的烟草，满城随风飘落的花絮，梅子刚刚黄熟时的霖雨。\n\n注解\n凌波：形容女子步态轻盈。\n芳尘去：指美人已去。\n锦瑟华年：指美好的青春时期。　锦瑟：饰有彩纹的瑟。\n月台：赏月的平台。　花榭：花木环绕的房子。\n琐窗：雕绘连琐花纹的窗子。　朱户：朱红的大门。\n蘅皋（héng gāo,横高）：长着香草的沼泽中的高地。\n彩笔：比喻有写作的才华。事见南朝江淹故事。\n试问闲愁都几许：都几许，有多少。试问，一说“若问”。闲愁，一说“闲情”。\n一川：遍地。▲', poem_appreciation = '这首词通过对暮春景色的描写，抒发作者所感到的“闲愁”。上片写路遇佳人而不知所往的怅惘情景，也含蓄地流露其沉沦下僚、怀才不遇的感慨。下片写因思慕而引起的无限愁思。全词虚写相思之情，实抒悒悒不得志的“闲愁”。立意新奇，能兴起人们无限想象，为当时传诵的名篇。\n\n　　贺铸的美称“贺梅子”就是由这首词的末句引来的。据周紫芝《竹坡诗话》载：“贺方回尝作《青玉案》词，有‘梅子黄时雨’之句，人皆服其工，士大夫谓之贺梅子。”可见这首词影响之大。\n\n　　“凌波不过横塘路，但目送，芳尘去。”横塘，在苏州城外。龚明之《中吴纪闻》载：“铸有小筑在姑苏盘门外十余里，地名横塘。方回往来于其间。”是作者隐居之所。凌波，出自曹植《洛神赋》：“凌波微步，罗袜生尘。”这里是说美人的脚步在横塘前匆匆走过，作者只有遥遥地目送她的倩影渐行渐远。基于这种可望而不可即的遗憾，作者展开丰富的想象，推测那位美妙的佳人是怎样生活的。“锦瑟年华谁与度？”用李商隐“锦瑟无端五十弦，一弦一柱思华年”诗意。下句自问自答，用无限婉惜的笔调写出陪伴美人度过如锦韶华的，除了没有知觉的华丽住所，就是一年一度的春天了。这种跨越时空的想像，既属虚构，又合实情。\n\n　　上片以偶遇美人而不得见发端，下片则承上片词意，遥想美人独处幽闺的怅惘情怀。“碧云”一句，是说美人伫立良久，直到暮色的四合，笼罩了周围的景物，才蓦然醒觉。不由悲从中来，提笔写下柔肠寸断的诗句。蘅皋，生长着香草的水边高地，这里代指美人的住处。“彩笔”，据《南史·江淹传》：“……（淹）尝宿于冶亭，梦一丈夫自称郭璞，谓淹曰：‘吾有笔在卿处多年，可以见还。’淹乃探怀中得五色笔一以授之。”这里用彩笔代指美人才情高妙。那么，美人何以题写“断肠句”？于是有下一句“试问闲愁都几许？”刘熙载云：“贺方回《青玉案》词收四句云：‘试问闲愁都几许？一川烟草，满城风絮，梅子黄时雨。’其未句好处全在‘试问’句呼起，及与上‘一川’二句并用耳。”笔者认为，“试问”一句的好处还在一个“闲”字。“闲愁”，即不是离愁，不是穷愁。也正因为“闲”，所以才漫无目的，漫无边际，飘飘渺渺，捉摸不定，却又无处不在，无时不有。这种若有若无，似真还幻的形象，只有那“一川烟草，满城风絮，梅子黄时雨”差堪比拟。作者妙笔一点，用博喻的修辞手法将无形变有形，将抽象变形象，变无可捉摸为有形有质，显示了超人的艺术才华和高超的艺术表现力。宋·罗大经云：“以三者比愁之多，尤为新奇，兼兴中有比，意味更长。”清·王闿运说：“一句一月，非一时也。”都是赞叹末句之妙。\n\n　　贺铸一生沉抑下僚，怀才不遇，只做过些右班殿臣、监军器库门、临城酒税之类的小官，最后以承仪郎致仕。将政治上的不得志隐曲地表达在诗文里，是封建文人的惯用手法。因此，结合贺铸的生平来看，这首诗也可能有所寄托。贺铸为人耿直，不媚权贵，“美人”、“香草”历来又是高洁之士的象征，因此，作者很可能以此自比。居住在香草泽畔的美人清冷孤寂，不正是作者怀才不遇的形象写照吗？从这个意义上讲，这首词之所以受到历代文人的盛赞，“同病相怜”恐怕也是一个重要原因吧！当然，径直把它看作一首情词，抒写的是对美好情感的追求和可望而不可即的怅惘，亦无不可。无论从哪个角度来理解，这首词所表现的思想感情对于封建时代的人们来说，都是“与我心有戚戚焉”。这一点正是这首词具有强大生命力的关键所在。', poem_tags = '宋词三百首,婉约,春天,写景,爱情,相思' WHERE poem_title = '青玉案·凌波不过横塘路' AND poem_author = '贺铸';
UPDATE edu_poem SET poem_translation = '关东的仗义之士都起兵讨伐那些凶残的人。\n最初约会各路将领订盟，同心讨伐长安董卓。\n讨伐董卓的各路军队汇合以后，因为各有自己的打算，力不齐一，互相观望，谁也不肯率先前进。\n势利二字引起了诸路军的争夺，随后各路军队之间就自相残杀起来。\n袁绍的堂弟袁术在淮南称帝号，袁绍谋立傀儡皇帝在北方刻了皇帝印玺。\n由于战争连续不断，士兵长期脱不下战衣，铠甲上生满了虮虱，众多的百姓也因连年战乱而大批死亡。\n尸骨曝露于野地里无人收埋，千里之间没有人烟，听不到鸡鸣。\n一百个老百姓当中只不过剩下一个还活着，想到这里令人极度哀伤。', poem_notes = '关东：函谷关（今河南灵宝西南）以东。义士：指起兵讨伐董卓的诸州郡将领。\n讨群凶：指讨伐董卓及其党羽。\n初期：本来期望。盟津：即孟津（今河南孟县南）。相传周武王伐纣时曾在此大会八百诸侯，此处借指本来期望关东诸将也能像武王伐纣会合的八百诸侯那样同心协力。\n乃心：其心，指上文“义士”之心。咸阳：秦时的都城，此借指长安，当时献帝被挟持到长安。\n力不齐：指讨伐董卓的诸州郡将领各有打算，力量不集中。齐：一致。\n踌躇：犹豫不前。雁行（háng）：飞雁的行列，形容诸军列阵后观望不前的样子。此句倒装，正常语序当为“雁行而踌躇”。\n嗣：后来。还：同“旋”，不久。自相戕（qiāng）：自相残杀。当时盟军中的袁绍、公孙瓒等发生了内部的攻杀。\n淮南句：指袁绍的异母弟袁术于公元197年（建安二年）在淮南寿春（今安徽寿县）自立为帝。\n刻玺句：指公元191年（初平二年）袁绍谋废献帝，想立幽州牧刘虞为皇帝，并刻制印玺。玺，印，秦以后专指皇帝用的印章。\n铠甲句：由于长年战争，战士们不脱战服，铠甲上都生了虱子。铠甲，古代的护身战服。铠，就是甲。虮，虱卵。\n万姓：百姓。以：因此。\n生民：百姓。遗：剩下。', poem_appreciation = '这首《蒿里行》可以说是《薤露行》的姐妹篇，清人方东树的《昭昧詹言》中说：“此用乐府题，叙汉末时事。所以然者，以所咏丧亡之哀，足当哀歌也。《薤露》哀君，《蒿里》哀臣，亦有次第。”就说明了此诗与《薤露行》既有联系，又各有侧重不同。《蒿里》也属乐府《相和歌·相和曲》，崔豹《古今注》中就说过：“《薤露》送王公贵人，《蒿里》送士大夫庶人，使挽柩者歌之，世呼为挽歌。”因此，如果说《薤露行》主要是写汉朝王室的倾覆，那么，《蒿里行》则主要是写诸军阀之间的争权夺利，酿成丧乱的历史事实。\n\n　　此诗前十句勾勒了这样的历史画卷：关东各郡的将领，公推势大兵强的渤海太守袁绍为盟主，准备兴兵讨伐焚宫、毁庙、挟持献帝、迁都长安、荒淫兀耻、祸国殃民的董卓。当时各郡虽然大军云集，但却互相观望，裹足不前，甚至各怀鬼胎，为了争夺霸权，图谋私利，竟至互相残杀起来。诫之不成便加之笔伐，诗人对袁绍兄弟阴谋称帝、铸印刻玺、借讨董卓匡扶汉室之名，行争霸天下称孤道寡之实给予了无情的揭露，并对因此造成的战乱感到悲愤。诗中用极凝练的语言将关东之师从聚合到离散的过程原原本本地说出来，成为历史的真实记录。然而，曹操此诗的成功与价值还不仅在此，自“铠甲生虮虱”以下，诗人将笔墨从记录军阀纷争的事实转向描写战争带给人民的灾难，在揭露军阀祸国殃民的同时，表现出对人民的无限同情和对国事的关注和担忧，这就令诗意超越了一般的记事，而反映了诗人的忧国忧民之心。\n\n　　连年的征战，使得将士长期不得解甲，身上长满了虮子、虱子，而无辜的百姓却受兵燹之害而大批死亡，满山遍野堆满了白骨，千里之地寂无人烟，连鸡鸣之声也听不到了，正是满目疮痍，一片荒凉凄惨的景象，令人目不忍睹。最后诗人感叹道：在战乱中幸存的人百不馀一，自己想到这些惨痛的事实，简直肝肠欲裂，悲痛万分。诗人的感情达到高潮，全诗便在悲怆愤懑的情调中戛然而止。\n\n　　此诗比《薤露行》更深刻地揭露了造成社会灾难的原因，更坦率地表现了自己对现实的不满和对人民的同情。曹操本人真正在政治舞台上崭露头角还是从他随袁绍讨伐董卓始，故此诗中所写的事实都是他本人的亲身经历，较之《薤露行》中所述诸事，诗人更多直接感性的认识，故诗中反映的现实更为真切，感情更为强烈。如最后两句完全是诗人目睹兵连祸结之下民不聊生，哀鸿遍野的真实情境而产生的感时悯世之叹。刘勰评曹氏父子的诗曾说：“志不出于滔荡，辞不离于哀思。”（《文心雕龙·乐府》）锺嵘评曹操的诗也说：“曹公古直，甚有悲凉之句。”（《诗品·下》）都指出了曹操的诗歌感情沉郁悲怆的特点。惟其有情，故曹操的诗读来有感人的力量；惟其悲怆，故造成了其诗沉郁顿挫、格高调响的悲壮气势。这首《蒿里行》即是极为典型的例子。故陈祚明说：“孟德所传诸篇，虽并属拟古，然皆以写己怀来，始而忧贫，继而悯乱，慨地势之须择，思解脱而未能，亹亹之词，数者而已。”（《采菽堂古诗选》）可见曹操诗歌抒忧写愤的特征已为前人所注重。\n\n　　正因为此诗实录当时事实并由诗人直抒胸臆，故全诗用了简洁明了的白描手法，无意于词句的雕凿粉饰，而以明快有力的语言出之，如“关东有义士，兴兵讨群凶。初期会孟津，乃心在咸阳”四句，明白如话，一气直下，将关东之师初起时的声势与正义刻画殆尽，自己的爱憎也于此鲜明地表现出来。又如“军合力不齐，踌躇而雁行”等语描写联军将领的各怀私心，逡巡不前，可谓入木三分。对于袁绍等军阀的讥刺与抨击是随着事态的发展而逐步表现的，起先称之为“义士”，并指出“乃心在咸阳”，意在恢复汉祚，然自“踌躇而雁行”已逗出其军心不齐和怯懦畏战的弊端。然后写其各为势利而争、发展到自相残杀,最后点明其称帝野心，可谓如层层剥笋，步步深入。但都以直接明白的语言写来，令人感到诗人抑捺不住的真实感情，而军阀懦弱而丑恶的嘴脸已跃然纸上。至于诗人感情的强烈，也完全由明畅的语言冲口而出，如写白骨蔽野，千里无人，都以直陈其事的方式说出，最后说“生民百遗一，念之断人肠”，直出胸臆，无一丝造作之意，可视为诗人心声的自然表露。', poem_tags = '古诗三百首,乐府,战争,忧国忧民' WHERE poem_title = '蒿里行' AND poem_author = '曹操';
UPDATE edu_poem SET poem_translation = '菱叶在水面飘荡，荷叶在风中摇曳荷花深处，采莲的小船轻快飞梭。\n采莲姑娘碰见自己的心上人，想跟他打招呼又怕人笑话。便低头羞涩微笑，一不留神，头上的玉簪掉落水中。', poem_notes = '萦（yíng）：萦回，旋转，缭绕；\n飐（zhǎn）：摇曳；\n小船通：两只小船相遇；\n搔头：簪之别名；碧玉搔头：即碧玉簪，简称玉搔头。', poem_appreciation = '《采莲曲》，乐府旧题，为《江南弄》七曲之一。内容多描写江南一带水国风光，采莲女子劳动生活情态，以及她们对纯洁爱情的追求等。描写采莲生活的诗歌很早就出现了，汉乐府中就有《采莲曲》《江南可采莲》“江\n\n　　南可采莲，莲叶何田田！鱼戏莲叶间：鱼戏莲叶东，鱼戏莲叶西，鱼戏莲叶南，鱼戏莲叶北。”南北朝出现了不少写采莲生活的名作，如《西洲曲》“采莲南唐秋，莲花过人。低头弄莲子，莲子清如水头。”到了唐代，写采莲更是成为一种时尚，很多名家如李白、白居易、王昌龄、戎昱、崔国辅、皇甫松等都写过这类诗歌。白居易的《采莲曲》写得尤为细腻动人。\n\n　　白居易这首诗描写的是一位采莲姑娘腼腆的情态和羞涩的心理。前两句写风中婀娜舞动的荷叶荷花，从荷花的深处有小船悠然划出，画面充满了动感。“菱叶萦波荷飐风”，在碧水荡漾一望无际的水面上，菱叶荷叶一片碧绿，阵阵清风吹来，水波浮动，绿叶随风摇摆，菱叶在绿波荡漾的湖面上飘飘荡荡，荷花在风中摇曳生姿。正因为绿叶的摇动，才让人们看到了“荷叶深处小船通”。荷花深处，暗示了荷花的茂盛、广阔，而“小船通”，则告诉读者有人有活动。这就像一组电影长镜头，先见一片风光，然后将人物活动呈现在其中，给人以真切感。\n\n　　然后诗人用了一个日常习见、颇具情趣的细节：“逢郎欲语低头笑，碧玉搔头落水中。”采莲少女看见了自己的情郎，正想说话却又突然止住，羞涩得在那里低头微笑，不想一不小心，头上的碧玉簪儿落入了水中。“欲语低头笑”既表现了少女的无限喜悦，又表现了少女初恋时的羞涩难为情。“碧玉搔头落水中”又进一步暗示了少女“低头笑”的激动神态。后两句描写细致，生动逼真。诗人抓住人物的神情和细节精心刻画，一个欲语还休、含羞带笑的姑娘宛然出现在读者眼前。\n\n　　《采莲曲》为民歌体裁，同类的作品历来很多。但白居易没有落入俗套，在短短的四句二十八个字中，既写景，又写人，生动形象，富有情趣，层层深入，活灵活现。此诗用乐府旧题写男女恋情，少女欲语低头的羞涩神态，以及搔头落水的细节描写，都自然逼真，意味无穷。犹如一卷望不尽的画面，使人百读不厌。', poem_tags = '荷花,女子,爱情' WHERE poem_title = '采莲曲' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '拉弓要拉最坚硬的，射箭要射最长的。射人先要射马，擒贼先要擒住他们的首领。\n杀人要有限制，各个国家都有边界。只要能够制止敌人的侵犯就可以了，难道打仗就是为了多杀人吗？', poem_notes = '挽：拉。\n当：应当。\n长：指长箭。\n擒：捉拿。\n前四句极像谣谚，可能是当时军中流行的作战歌诀。马目标大易射，马倒则人非死即伤，故先射马，蛇无头而不行，王擒则贼自溃散，故先擒王。擒王句乃主意所在，下四句便是引伸这一句的。\n亦有限：是说也有个限度，有个主从。正承上句意。沈德潜《杜诗偶评》：“诸本杀人亦有限，惟文待诏（文徵明）作杀人亦无限，以开合语出之，较有味。”不确。\n列国：各国。\n疆：边界。\n自有疆，是说总归有个疆界，饶你再开边。和前出塞诗第一首中的“开边一何多”照应。\n苟能：如果能。\n侵陵：侵犯。\n岂：难道。\n最后两句是说如果能抵制外来侵略的话，那末只要擒其渠魁就行了，又哪在多杀人呢？张远《杜诗会粹》：“大经济语，借戍卒口中说出。”在这里我们相当明显的看到杜甫的政治观点。', poem_appreciation = '鉴赏 　　作者是唐代诗人杜甫，诗人先写《出塞》九首，后又写《出塞》五首；加“前”、“后”以示区别。《前出塞》是写天宝末年哥舒翰征伐吐蕃的时事，意在讽刺唐玄宗的开边黩武，本篇原列第六首，是其中较有名的一篇。 诗的前四句，很象是当时军中流行的作战歌诀，颇富韵致，饶有理趣，深得议论要领。所以黄生说它“似谣似谚，最是乐府妙境”。两个“当”，两个“先”，妙语连珠，开人胸臆，提出了作战步骤的关键所在，强调部伍要强悍，士气要高昂，对敌有方略，智勇须并用。四句以排句出之，如数家珍，宛若总结战斗经验。然而从整篇看，它还不是作品的主旨所在，而只是下文的衬笔。后四句才道出赴边作战应有的终极目的。“杀人亦有限，列国自有疆。苟能制侵陵，岂在多杀伤？”诗人慷慨陈词，直抒胸臆，发出振聋发聩的呼声。他认为，拥强兵只为守边，赴边不为杀伐。不论是为制敌而“射马”，不论是不得已而“杀伤”，不论是拥强兵而“擒王”，都应以“制侵陵”为限度，不能乱动干戈，更不应以黩武为能事，侵犯异邦。这种以战去战，以强兵制止侵略的思想，是恢宏正论，安边良策；它反映了国家的利益，人民的愿望。所以，张会在《杜诗府粹》里说，这几句“大经济语，借戍卒口说出”。从艺术构思说，作者采用了先扬后抑的手法：前四句以通俗而富哲理的谣谚体开势，讲如何练兵用武，怎样克敌制胜；后四句却写如何节制武功，力避杀伐，逼出“止戈为武”本旨。先行辅笔，后行主笔；辅笔与主笔之间，看似掠转，实是顺接，看似矛盾，实为辩证。因为如无可靠的武备，就不能制止外来侵略；但自恃强大武装而穷兵黩武，也是不可取的。所以诗人主张既拥强兵，又以“制侵陵”为限，才符合最广大人民的利益。浦起龙在《读杜心解》中很有体会地说：“上四（句）如此飞腾，下四（句）忽然掠转，兔起鹘落，如是！如是！”这里说的“飞腾”和“掠转”，就是指作品中的奔腾气势和波澜；这里说的“兔起鹘落”就是指在奔腾的气势中自然地逼出“拥强兵而反黩武”的深邃题旨。在唐人的篇什中，以议论取胜的作品较少，而本诗却以此见称；它以立意高、正气宏、富哲理、有气势而博得好评。 ▲', poem_tags = '议论,战争,哲理' WHERE poem_title = '前出塞九首·其六' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '梅子味道很酸，吃过之后，余酸还残留在牙齿之间；芭蕉初长，而绿阴映衬到纱窗上。春去夏来，日长人倦，午睡后起来，情绪无聊，闲着无事观看儿童戏捉空中飘飞的柳絮。', poem_notes = '梅子：一种味道极酸的果实。软齿牙：一作溅齿牙，指梅子的酸味渗透牙齿。\n芭蕉分绿：芭蕉的绿色映照在纱窗上。与窗纱：《四部备要》本《诚斋集》作“上窗纱”，此据《杨万里选集》。与，给予的意思。\n无情思：没有情绪，指无所适从，不知做什么好。思，意，情绪。\n捉柳花：戏捉空中飞舞的柳絮。柳花，即柳絮。', poem_tags = '夏天,儿童' WHERE poem_title = '闲居初夏午睡起·其一' AND poem_author = '杨万里';
UPDATE edu_poem SET poem_translation = '魏文侯同掌管山泽的官约定去打猎。这天，魏文侯与百官饮酒非常的高兴，天下起雨来。文侯要出去赴约，随从的侍臣说：“今天饮酒这么快乐，天又下雨了，您要去哪里呢？”魏文侯说：“我与别人约好了去打猎，虽然在这里很快乐,但是怎么能不去赴约呢？”于是自己前往约定地点，亲自取消了打酒宴。魏国从此变得强大。', poem_notes = '文侯：战国时期魏国国君，在诸侯中有美誉。\n虞人：管理山泽的官。\n期猎：约定打猎时间。\n焉：哪里。\n是： 这\n罢：停止，取消。\n之：到，往。\n强：强大。\n期：约定\n雨：下雨\n岂：怎么\n可：能\n乃：于是就', poem_tags = '小学文言文,故事,哲理,诚信' WHERE poem_title = '文侯与虞人期猎' AND poem_author = '刘向';
UPDATE edu_poem SET poem_translation = '常常羡慕这世间如玉雕琢般丰神俊朗的男子，就连上天也怜惜他，赠予他柔美聪慧的佳人与之相伴。人人称道那女子歌声轻妙，笑容柔美，风起时，那歌声如雪片飞过炎热的夏日使世界变得清凉。\n你从遥远的地方归来却看起来更加年轻了，笑容依旧，笑颜里好像还带着岭南梅花的清香；我问你：“岭南的风土应该不是很好吧？”你却坦然答道：“心安定的地方，便是我的故乡。”', poem_notes = '定风波：词牌名。一作“定风波令”，又名“卷春空”、“醉琼枝”。双调六十二字，上片五句三平韵，二仄韵，下片六句四仄韵，二平韵。\n王定国：王巩，作者友人。寓娘：王巩的歌妓。\n柔奴：即寓娘。\n玉郎：是女子对丈夫或情人的爱称，泛指男子青年。\n点酥娘：谓肤如凝脂般光洁细腻的美女。\n皓齿：雪白的牙齿。\n炎海：喻酷热。\n岭：指大庾岭，沟通岭南岭北咽喉要道。\n试问：试着提出问题，试探性地问。\n此心安处是吾乡：这个心安定的地方，便是我的故乡。', poem_appreciation = '这首词中以明洁流畅的语言，简练而又传神地刻画了柔奴外表与内心相统一的美好品性，通过歌颂柔奴身处逆境而安之若素的可贵品格，抒发了作者在政治逆境中随遇而安、无往不快的旷达襟怀。\n\n　　上片总写柔奴的外在美，开篇“常羡人间琢玉郎，天教分付点酥娘”，描绘柔奴的天生丽质、晶莹俊秀，使读者对她的外貌有了一个比较完整、真切而又寓于质感的印象。第三句“自作清歌传皓齿，风起，雪飞炎海变清凉。”这句的意思是：柔奴能自作歌曲，清亮悦耳的歌声从她芳洁的口中传出，令人感到如同风起雪飞，使炎暑之地一变而为清凉之乡，使政治上失意的主人变忧郁苦闷、浮躁不宁而为超然旷放、恬静安详。苏词横放杰出，往往驰骋想象，构成奇美的境界，这里对“清歌”的夸张描写，表现了柔奴歌声独特的艺术效果。“诗言志，歌咏言”，“哀乐之心感，而歌咏之声发”（班固《汉书·艺文志》），美好超旷的歌声发自于美好超旷的心灵。这是赞其高超的歌技，更是颂其广博的胸襟，笔调空灵蕴藉，给人一种旷远清丽的美感。\n\n　　下片通过写柔奴的北归，刻画其内在美。换头承上启下，先勾勒她的神态容貌：“万里归来年愈少。”岭南艰苦的生活她甘之如饴，心情舒畅，归来后容光焕发，更显年轻。“年愈少”多少带有夸张的成分，洋溢着词人赞美历险若夷的女性的热情。“微笑”二字，写出了柔奴在归来后的欢欣中透露出的度过艰难岁月的自豪感。“笑时犹带岭梅香”，表现出浓郁的诗情，既写出了她北归时经过大庾岭的情况，又以斗霜傲雪的岭梅喻人，赞美柔奴克服困难的坚强意志，为下边她的答话作了铺垫。最后写到词人和她的问答。先以否定语气提问：“试问岭南应不好？”“却道”陡转，使答语“此心安处是吾乡”更显铿锵有力，警策隽永。白居易《初出城留别》中有“我生本无乡，心安是归处”，《种桃杏》中有“无论海角与天涯，大抵心安即是家”等语，苏轼的这句词，受白诗的启发，但又明显地带有王巩和柔奴遭遇的烙印，有着词人的个性特征，完全是苏东坡式的警语。它歌颂柔奴随缘自适的旷达与乐观，同时也寄寓着作者自己的人生态度和处世哲学。\n\n　　这首词不仅刻画了歌女柔奴的姿容和才艺，而且着重歌颂了她的美好情操和高洁人品。柔中带刚，情理交融，空灵清旷，细腻柔婉，是这首词的风格所在。', poem_tags = '宋词三百首,赞颂,歌女' WHERE poem_title = '定风波·南海归赠王定国侍人寓娘' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '当年谢安隐居在东海，出仕做官鬓发已霜秋，中年难与亲友别，唯有丝竹缓离愁。一旦功成名就，准备返归东海，谁料抱病入西州。做官困扰了隐居的雅志，遗恨寄托于田园山丘。\n既已年高衰朽，便当及早划筹，要做百姓穿粗裘。返回故乡遵迢千里，选取佳地长住久留。酒醉放歌君相和，醉倒在地君扶我，只有醉时忘忧愁。任凭刘备笑我无大志，我却甘愿身居平地，仰看他高卧百尺楼。', poem_notes = '水调歌头：词牌名，又名“元会曲”“台城游”“凯歌”“江南好”“花犯念奴”等。双调，九十五字，平韵。\n东武：指密州。\n子由：苏轼之弟文学家苏辙字。\n彭门：指徐州。\n此曲：指苏辙《水调歌头·徐州中秋》词。\n安石：谢安，字安石，阳夏（今河南太康）人。东晋名臣，以功封建昌县公，死后赠太傅。东海：谢安早年隐居会稽（今浙江绍兴），东面濒临大海，故称东海。\n“从事”句：意为谢安出仕时鬓发已开始变白。谢安少有重名，屡征不起，直到四十多岁才出仕从政。\n“中年”两句：《晋书·王羲之传》：“谢安尝谓羲之曰：‘中年以来，伤于哀乐，与亲友别，辄作数日恶。’羲之曰：‘年在桑榆，自然至此。顷正赖丝竹陶写，恒恐儿辈觉，损其欢乐之趣。”’丝竹，泛指管弦乐器。\n“一旦”三句：意思是说谢安功成名就之后，一定准备归隐会稽，不料后来抱病回京了。西州，代指东晋都城建康（今江苏南京市）。\n雅志：指退隐东山的高雅的志趣。轩冕（xuān miǎn）：古代官员的车服。借指做官。\n沧洲：水滨，古代多用以指隐士的住处。\n岁云暮：即岁暮。云，语助词。\n要褐裘（qiú）：指换上粗布袍，意为辞官归乡，作普通百姓。\n迟留：逗留，停留。\n“惟酒”句：语本《晋书·顾荣传》：“恒纵酒酣畅，谓友人张翰曰：‘惟酒可以忘忧，但无如作病何耳。”’\n“一任”二句：意思是说，任凭有雄心大志的入瞧不起我们，也不去管它了。刘玄德，刘备。', poem_appreciation = '上阕咏史，写东晋谢安的经历，意在“以不早退为戒”。发端明点“安石”，领起上半阕。词人的写作角度比较独特，既不写他经天纬地的才能，也不写他建功立业的辉煌，而是写他人生的另一侧面。劈头就写谢安中年出仕的尴尬：他本来隐居会稽，踏上仕途时鬓发已开始染上秋霜，令人吃惊。再写人情的难堪：人到中年，与亲友相别时觉得难舍难分，于是借音乐来抒写离愁。而后突出他一向抱有的功成身退的心愿： “一旦功成名遂，准拟东还海道”。语气多么肯定，多么坚决，确实是对史书中所谓“安虽受朝寄，然东山之志始末不渝，每形于言色”（《晋书》）数语准确的表述。而结果却是“扶病人西州”，这就反跌出困於轩冕不遂雅志的“遗恨”。这种“遗恨”，便是作者引出的鉴戒——“不早退”。词中的“困轩冕”只是一个文雅的或婉转的说法，实际上（至少在某种程度上）与贪恋功名富贵是联系在一起的。\n\n　　下阕述怀，设想早日“退而相从之乐”。换头“岁云暮”三字承上转下，“岁暮”当指年华老大，“早计”是对“遗恨”而言，其内容便是“要褐裘”，亦即辞官归隐，过平民生活。以下七句是由此产生的设想：在归乡的千里长途中，每逢山水名胜或有贤主、良朋接待之类好的去处，可以随意逗留，尽情游乐，不必如官场中人因王命在身而行道局促，一层：我带着醉意唱歌时你跟着唱和，我因醉酒倒下时你要搀扶我，——只有酒是可以使人忘怀得失的，二层：这样，有雄心大志的人会瞧不起我们，那就悉听尊便好了，我们只管走自己的路，三层：这种种设想，情辞恳切，言由中发，有如骏马驻坡，不可遏止，充分表现出词人对辞官归隐而享弟兄“相从之乐”的夙愿。“我醉歌时君和，醉倒须君扶我”，极写想象中“退而相从之乐”的情态，简直是对二人的“合影”。篇末“一任刘玄德，相对卧高楼”两句，反用典故，并非真要趋同胸无大志的庸人，而只是强调素愿的坚定不移，这体现了用典的灵活性。\n\n　　同《南乡子》（东武望余杭）、《醉落魄》（分携如昨）、《减字木兰花》（贤哉令尹）等词作一样，这首词着重表现了苏轼前期思想的另一面，虽然“功成名遂”尚未实现，出仕思想仍占上风，但在某种程度上徘徊于出处之间，却是可以肯定的。早在嘉祐五年（1060）苏氏弟兄寓居怀远驿时，即有“夜雨对床”，“为闲居之乐”（苏辙《逍遥堂会宿二首》引、《再祭亡兄端明文》等）的口头约定，这一回正是对前约的重申，当然在很大程度上也是出于对其弟的安慰，词中流露出深厚的兄弟之情。不过，他在诗词中不断表达的这种归卧故山的雅志，最终还是没有实现。苏辙词中的“但恐同王粲，相对永登楼”，倒成了他们此后生活的写照。', poem_tags = '故事,抒情' WHERE poem_title = '水调歌头·安石在东海' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '有个人憎恨老鼠，倾尽所有的家财讨得一只好猫。用鱼肉喂养，用棉垫、毯子给猫睡。猫已经吃得饱饱的并且过得安安稳稳，大都不捕鼠了，有时猫甚至与老鼠一块嬉戏，老鼠因此更加凶暴。这人十分生气，把它赶走，于是再也不在家里养猫了，认为这个世界上没有好猫。', poem_notes = '某：某个人；有一个人。\n恶：讨厌；厌恶。\n破家：拿出所有的家财。破：倾尽\n厌：满足。\n以：用。\n腥膏：鱼和肥肉。腥：代指鲜鱼。膏：肥肉。\n罽：（jì）（罽蒘）古书上说的一种植物，似芹，可食，子大如麦粒。俗称“鬼麦”。毡罽：毡子和毯子。\n且：并且。\n率：大都。\n故：缘故。\n益：更加。\n暴：凶暴。横行不法。\n遂：于是；就。\n逐：驱逐，赶走。\n蓄：养。\n以为：认为。', poem_tags = '小学文言文,寓理,故事' WHERE poem_title = '世无良猫' AND poem_author = '乐钧';
UPDATE edu_poem SET poem_translation = '回想当初出征时，杨柳依依随风吹；\n如今回来路途中，大雪纷纷满天飞。\n道路泥泞难行走，又渴又饥真劳累。\n满心伤感满腔悲。我的哀痛谁体会。', poem_notes = '思：语气助词。\n矣：语气助词。\n依依：形容树枝柔弱，随风摇摆的样子。\n霏霏：雪花飞舞的样子。\n昔：从前。', poem_appreciation = '赏析 　　《采薇》是《诗经·小雅》中的一篇。历代注者关于它的写作年代说法不一。但据它的内容和其它历史记载的考订大约是周宣王时代的作品的可能性大些。周代北方的猃狁（即后来的匈奴）已十分强悍，经常入侵中原，给当时北方人民生活带来不少灾难。历史上有不少周天子派兵戍守边外和命将士出兵打败猃狁的记载。从《采薇》的内容看，当是将士戍役劳还时之作。诗中唱出从军将士的艰辛生活和思归的情怀。 全诗分六章，前三章叠出，以采薇起兴写薇由作而柔而刚，而戍役军士远别家乡，历久不归，思乡之情，忧心不已！作者写道：山薇啊，你发芽了，出生了，我们总该回家了吧！但转眼又是一年，我们都顾不上家室，这却是为何呢？为了猃狁入侵之故，我们连好好坐上一会儿也来不及，也是为了猃狁之故。我们需要攻战！又到了采薇的时候，薇叶长大了，枝叶柔嫩，这下总该回家了吧！心里的忧伤如此炽烈，为战事奔波，我们戍期未定，谁难替我们带回家信！山薇长得粗壮刚健了，这下该回家了吧！已是阳春十月了！可是王事没完，还没法闲暇，忧伤的心情好不痛苦，却无人相慰劳！四、五两章是写边关战事繁忙、紧张：那盛开的花是什么？是棠棣之花。用花之盛起兴，喻出征军伍车马服饰之盛：那好大好大的是什么？那是将士的军车，兵车既已驾起，战马高大雄健，战事频繁，军队又要迁徙，岂敢定居？驾着四匹昂首高大的公马，军将们坐在战车上，步兵们蔽依车后，战马威武雄健，兵士手中的象骨的弓和鱼皮箭袋时时佩在身边，猃狁的侵战如此强大猖狂，马能不日日加强戒备？这两章写的是猃狁的匈悍而周家军队盛大的军威，纪律严正，卒伍精强。但是戍役的生活也是艰辛而紧张的，这些都是作者用写实的笔法来写的。第六章则笔锋一转，写出征人在还乡路上饱受饥寒，痛定思痛的哀伤心情：想起出征之时，那依依杨柳，枝茂叶盛，而此时风雪归程，路远，天寒，又饥，又渴，可谓十分狼狈而又凄苦。晋人谢玄把“昔我往矣”四句论为三百篇中最好的诗句。在文学史上影响极大。常为后世文人反复吟唱、仿效。由于《诗经》素以浑厚、质朴著称，这类如此凄婉动人的作品确属不多。因而它便成了《诗经》抒情作品的一个典范而为历代文学家所称颂。 这首诗的主题是严肃的。猃狁的凶悍，周家军士严阵以待，作者以戍役军士的身份描述了以天子之命命将帅、遣戊役，守卫中国，军旅的严肃威武，生活的紧张艰辛。作者的爱国情怀是通过对猃狁的仇恨来表现的。更是通过对他们忠于职守的叙述——“不遑启居”、“不遑启处”、“岂敢定居”、“岂不日戒”和他们内心极度思乡的强烈对比来表现的。全诗再衬以动人的自然景物的描写：薇之生，薇之柔，薇之刚，棠棣花开，依依杨柳，霏霏雨雪，都烘托了军士们“日戒”的生活，心里却是思归的情愫，这里写的都是将士们真真实实的思想，忧伤的情调并不降低本篇作为爱国诗篇的价值，恰恰相反是表现了人们的纯真朴实，合情合理的思想内容和情感，也正是这种纯正的真实性，赋予了这首诗强盛的生命力和感染力。 从写作上看，它和诗经的许多作品一样用以薇起兴的手法，加上章法、词法上重沓叠奏，使内容和情趣都得以层层铺出，渐渐深化，也增强了作品的音乐美和节奏感。全诗有记叙，有议论，有景物，有抒情，有心理描写，搭配错落有致，又十分妥贴，因此《采薇》（节选）一篇确是《诗经》中最好的篇章之一。 ▲', poem_tags = '小学古诗,回忆,感伤' WHERE poem_title = '采薇(节选)' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '轻雷响过，春雨淅沥而下。雨后初晴，阳光好像在刚刚被雨洗过的碧瓦间浮动。春雨过后，芍药含泪，情意脉脉；蔷薇横卧，娇态可掬，惹人怜爱。', poem_notes = '选自《淮海集》。 秦观（1049~1100），宋代文学家，号淮海居士，高邮（今属江苏）人 \n丝:喻雨。 \n浮瓦:晴光照在瓦上。 \n霁(jì)光：雨天之后明媚的阳光。霁：雨后放晴。 \n参差：高低错落的样子。 \n芍药：一种草本植物，这里指芍药花。 \n春泪:雨点。', poem_appreciation = '这首诗写雨后春景。瞧，雨后庭院，晨雾薄笼，碧瓦晶莹，春光明媚；芍药带雨含泪，脉脉含情，蔷薇静卧枝蔓，娇艳妩媚。这里有近景有远景，有动有静，有情有姿，随意点染，参差错落。全诗运思绵密，描摹传神，自具一种清新、婉丽的韵味，十分惹人喜爱　诗人捕捉到春雨“万丝”的特征，把镜头的焦点对准了庭院一角，摄下了一幅雷雨后晴春晓日的精巧画面。通过对偶形式，拟人手法，衬托庭院的华丽，描绘了芍药和蔷薇百媚千娇的情态。芍药亭亭玉立、蔷薇攀枝蔓延，故各有“含春泪”之态、“无力卧”之状。因其体物入微，情致蕴藉，通篇自具一种清新婉丽的韵味，展示了诗人对自然界景物、现象敏锐的观察力、感受力和摄取力、表现力。在意境上以“春愁”统摄全篇，虽不露一“愁”字，但可从芍药、蔷薇的情态中领悟，又曲折体现了诗人由于宦途艰险而形成的多愁善感的性格。\n\n　　“好雨知时节”，在一夕隐隐春雷的召唤下，它“随风潜入夜”，它“润物细无声”。雷是“轻”的，雨如“丝”般，春雨的特色诗人只用两个字就揭示出来了。\n\n　　那碧绿的琉璃瓦，被一夜春雨洗得干干净净，晶莹剔透，犹如翡翠，瓦上还沾有水珠，在晨曦的辉映下，浮光闪闪，鲜艳夺目，令人心旷神怡——这是第二句所写的美\n\n　　最妙的是后两句，诗人采用以美人喻花的手法，又加上对仗，确实是美不胜收。\n\n　　李白笔下“一枝红艳露凝香”，白居易笔下刚出浴的“侍儿扶起娇无力”的杨妃，和第三句有着惊人的相似之处。雨后的牡丹，犹如多情的少女，泪光闪闪，含情脉脉。\n\n　　最后一句令人想起《红楼梦·史湘云醉眠芍药铟》那段描写：湘云“业经香梦沈酣，四面芍药花飞了一身，满头脸衣襟上皆是红香散乱。”这醉卧中浑身洒满落花的史湘云，情思绵绵，百媚千娇，多像“无力蔷薇卧晓枝”。', poem_tags = '古诗三百首,写雨,写景' WHERE poem_title = '春日' AND poem_author = '秦观';
UPDATE edu_poem SET poem_translation = '一旦成为贬谪之人，就像贾谊到了长沙，日日西望，望不见长安，也望不见家。\n黄鹤楼上传来了一声声《梅花落》的笛声，使这五月的江城又见到纷落的梅花。', poem_notes = '郎中：官名，为朝廷各部所属的高级部员。钦：当是史郎中名。一作“饮”。王琦《李太白全集》注本谓史钦，其生平不详。黄鹤楼：古迹在今湖北武汉，今已在其址重建。\n迁客：被贬谪之人。去长沙：用汉代贾谊事。贾谊因受权臣谗毁，被贬为长沙王太傅，曾写《吊屈原赋》以自伤。\n江城：指江夏（今湖北武昌），因在长江、汉水滨，故称江城。落梅花：即《梅花落》，古代笛曲名。', poem_appreciation = '西汉的贾谊，因指责时政，受到权臣的谗毁，贬官长沙。而李白也因永王李璘事件受到牵连，被加之以“附逆”的罪名流放夜郎。所以诗人引贾谊为同调。“一为迁客去长沙”，就是用贾谊的不幸来比喻自身的遭遇，流露了无辜受害的愤懑，也含有他的自我辩白之意。但政治上的打击，并没有使诗人忘怀国事。在流放途中，他不禁“西望长安”，这里有对往事的回忆，有对国运的关切和对朝廷的眷恋。然而，长安万里迢迢，对迁谪之人来说十分遥远，充满了隔膜。望而不见，诗人不免感到惆怅。听到黄鹤楼上吹奏《梅花落》的笛声，他感到格外凄凉，仿佛五月的江城落满了梅花。\n\n　　诗人巧借笛声来渲染愁情。王琦注引郭茂倩《乐府诗集》对此调的题解说：“《梅花落》本笛中曲也。”江城五月，正当初夏，当然是没有梅花的，但由于《梅花落》笛曲吹得非常动听，使诗人仿佛看到了梅花满天飘落的景象。梅花是寒冬开放的，景象虽美，却不免给人以凛然生寒的感觉，这正是诗人冷落心情的写照。同时使诗人联想到邹衍下狱、六月飞霜的历史传说。由乐声联想到音乐形象的表现手法，就是诗论家所说的“通感”。诗人由笛声想到梅花，由听觉诉诸视觉，通感交织，描绘出与冷落的心境相吻合的苍凉景色，从而有力地烘托了去国怀乡的悲愁情绪。所以《唐诗直解》评此诗“无限羁情笛里吹来”，是很有见解的。清代的沈德潜说：“七言绝句以语近情遥、含吐不露为贵，只眼前景，口头语，而有弦外音，使人神远，太白有焉。”（《唐诗别裁》卷二十）这首七言绝句，正是以“语近情遥、含吐不露”见长，使读者从“吹玉笛”、“落梅花”这些眼前景、口头语，听到了诗人的弦外之音。\n\n　　此外，这首诗还好在其独特的艺术结构。诗写听笛之感，却并没按闻笛生情的顺序去写，而是先有情而后闻笛。前半捕捉了“西望”的典型动作加以描写，传神地表达了怀念帝都之情和“望”而“不见”的愁苦。后半部分才点出闻笛，从笛声化出“江城五月落梅花”的苍凉景象，借景抒情，使前后情景相生，妙合无垠。', poem_tags = '贬谪,抒情,思乡,忧国忧民' WHERE poem_title = '与史郎中钦听黄鹤楼上吹笛 / 题北榭碑' AND poem_author = '李白';
UPDATE edu_poem SET poem_tags = '古诗三百首,纪行,写云' WHERE poem_title = '襄邑道中' AND poem_author = '陈与义';
UPDATE edu_poem SET poem_translation = '秋风不知从哪里吹来，萧萧地送来了大雁一群群。\n清早秋风来到庭中的树木上，孤独的旅人最先听到秋风的声音。', poem_notes = '引：一种文学或乐曲体裁之一，有序奏之意，即引子，开头。\n至：到。\n萧萧：形容风吹树木的声音。雁群：大雁的群体。\n朝：凌晨。庭树：庭园的树木。\n孤客：单身旅居外地的人。这里指诗人自己。闻：听到。', poem_appreciation = '诗以“秋风”为题；首句“何处秋风至”，就题发问，摇曳生姿，而通过这一起势突兀、下笔飘忽的问句，也显示了秋风的不知其来、忽然而至的特征。进一步推寻思索还暗含怨秋的意思，与李白《春思》诗“春风不相识，何事入罗帏”句有异曲同工之处。秋风之来，既无影无迹，又无所不在，它从何处来、来到何处，本是无可究诘的。这里虽以问语出之，而诗人的真意原不在追根究底，接下来就宕开诗笔。\n\n　　“萧萧送雁群”一句写耳所闻的风来萧萧之声和目所见的随风而来的雁群。化无形之风为可闻可见的景象，从而把不知何处至的秋风绘声绘影地写入诗篇。结合前两句诗，脱胎于屈原《九歌》“风飒飒兮木萧萧”和汉武帝《秋风辞》“秋风起兮白云飞，草木黄落兮雁南归”。而可以与这两句诗合参的有韦应物的《闻雁》诗：“故园渺何处？归思方悠哉。淮南秋雨夜，高斋闻雁来。”但韦诗是以我感物，以情会景，先写“归思”，后写“闻雁”。沈德潜在《唐诗别裁集》中指出，这样写，“其情自深”，如果“倒转说”，就成了一般人都写得出的普通作品了。这首《秋风引》前两句所写的秋风始至、鸿雁南来，正是韦诗后两句的内容，恰恰是把韦诗倒转过来说的。它是远处落想，空际运笔，从闻雁思归之人的对面写起，就秋风送雁构思造境。至于韦诗前两句的内容，是留到篇末再写的。\n\n　　“朝来入庭树，孤客最先闻”，把笔触从秋空中的“雁群”移向地面上的“庭树”，再集中到独在异乡、“归思方悠哉”的“楚客”，由远而近，步步换景。“朝来”句既承接首句的“秋风至”，又承接次句的“萧萧”声，不是回答又似回答了篇端的发问。它说明秋风的来去虽然无处可寻，却又附着它物而随处存在，此刻风动庭树，木叶萧萧，则无形的秋风分明已经近在庭院、来到耳边了。\n\n　　“孤客最先闻”诗写到这里，写足了作为诗题的“秋风”，诗中之人还没有露面，景中之情还没有点出。“孤客最先闻。”才画龙点睛，说秋风已为“孤客”所“闻”。这里，如果联系作者的另一首《始闻秋风》诗，其中“五夜飕飗枕前觉，一年颜状镜中来”两句，倒可以作“闻”的补充说明。当然，作为“孤客”，他不仅会因颜状改变而为岁月流逝兴悲，其羁旅之情和思归之心更是可想而知的。\n\n　　这首诗主要要表达的，其实正是这羁旅之情和思归之心，但妙在不从正面着笔，始终只就秋风做文章，在篇末虽然推出了“孤客”，也只写到他“闻”秋风而止。至于他的旅情归思是以“最先”两字来暗示的。如照说，秋风吹到庭树，每个人都可以同时听到，不应当有先后之分。而惟独孤客“最先”听到，可以想见，他对时序、物候有特殊的敏感。而他如此敏感的原因。这就是对“最先闻”的解释。这些评语都称赞这一结句曲折见意，含蓄不尽，为读者留有可寻味的深度。从全诗看来，却必须说“不可闻”，才与它的苍凉慷慨的意境、高亢劲健的风格相融浃。两个结句，内容相似，一用曲笔，一用直笔，却各尽其妙。对照之下，可悟诗法。\n\n　　这首诗借景抒情，主要表达的其实是这羁旅之情和思归之心，它说明秋风的来去虽然无处可寻，却又附着它物随处存在，风吹树动，萧萧木叶，那无形的秋风分明已经近在庭院、来到耳边了。', poem_tags = '秋天,写风,思乡' WHERE poem_title = '秋风引' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '看那黍子一行行，高粱苗儿也在长。走上旧地脚步缓，心里只有忧和伤。能够理解我的人，说我是心中忧愁。不能理解我的人，问我把什么寻求。高高在上苍天啊，何人害我离家走？\n看那黍子一行行，高粱穗儿也在长。走上旧地脚步缓，如同喝醉酒一样。能够理解我的人，说我是心中忧愁。不能理解我的人，问我把什么寻求。高高在上苍天啊，何人害我离家走？\n看那黍子一行行，高粱穗儿红彤彤。走上旧地脚步缓，心中如噎一般痛。能够理解我的人，说我是心中忧愁。不能理解我的人，问我把什么寻求。高高在上苍天啊，何人害我离家走？', poem_notes = '黍（shǔ）：北方的一种农作物，形似小米，有黏性。离离：行列貌。\n稷（jì）：古代一种粮食作物，指粟或黍属。\n行迈：行走。靡（mǐ）靡：行步迟缓貌。\n中心：心中。摇摇：心神不定的样子。\n悠悠：遥远的样子。\n噎（yē）：堵塞。此处以食物卡在食管比喻忧深气逆难以呼吸。', poem_appreciation = '关于《黍离》一诗的主旨，虽然《诗序》说得明白：“黍离，闵宗周也。周大夫行役，至于宗周，过故宗庙宫室，尽为禾黍。闵周室之颠覆，彷徨不忍去，而作是诗也。”而且从此诗序于王风之首，确见其为编诗者之意旨。但历来争讼颇多，三家诗中韩、鲁遗说与毛序异，宋儒程颐更有臆说以为“彼稷之苗”是彼后稷之苗。近人读诗，新说迭出，比较有代表性的有郭沫若在《中国古代社会研究》中将其定为旧家贵族悲伤自己的破产而作，余冠英则在《诗经选》中认为当是流浪者诉述他的忧思。还有蓝菊荪的爱国志士忧国怨战说（《诗经国风今译》），程俊英的难舍家园说（《诗经译注》）等。说法虽多，诗中所蕴含的那份因时世变迁所引起的忧思是无可争辩的，虽然从诗文中无法确见其具体背景，但其显示的沧桑感带给读者的心灵震撼是值得细加体味的。另一方面，从诗教角度视之，正因其为大夫闵宗周之作，故得列于《王风》之首，此为诗说正统，不可不及，以下从两方面细析之。\n\n　　闵宗周之诗何以列于《王风》之首，先得弄清何为《王风》，郑笺云：“宗周，镐京也，谓之西周。周，王城也，谓之东周。幽王之乱而宗周灭，平王东迁，政遂微弱，下列于诸侯，其诗不能复《雅》，而同于《国风》焉。”可见《王风》兼有地理与政治两方面的含义，从地理上说是王城之歌，从政治上说，已无《雅》诗之正，故为《王风》。此诗若如《诗序》所言，其典型情境应该是：平王东迁不久，朝中一位大夫行役至西周都城镐京，即所谓宗周，满目所见，已没有了昔日的城阙宫殿，也没有了都市的繁盛荣华，只有一片郁茂的黍苗尽情地生长，也许偶尔还传来一两声野雉的哀鸣，此情此景，令诗作者不禁悲从中来，涕泪满衫。这样的情和这样的景化而为诗是可以有多种作法的，诗人选取的是一种物象浓缩化而情感递进式发展的路子，于是这首诗具有了更为宽泛和长久的激荡心灵的力量。\n\n　　全诗共三章，每章十句。三章间结构相同，取同一物象不同时间的表现形式完成时间流逝、情景转换、心绪压抑三个方面的发展，在迂回往复之间表现出主人公不胜忧郁之状，“三章只换六字，而一往情深，低回无限”（方玉润《诗经原始》）。\n\n　　诗首章写诗人行役至宗周，过访故宗庙宫室时，所见一片葱绿，当年的繁盛不见了，昔日的奢华也不见了，就连刚刚经历的战火也难觅印痕了，看哪，那绿油油的一片是黍在盛长，还有那稷苗凄凄。“一切景语皆情语也”（王国维《人间词话》），黍稷之苗本无情意，但在诗人眼中，却是勾起无限愁思的引子，于是他缓步行走在荒凉的小路上，不禁心旌摇摇，充满怅惘。怅惘尚能承受，令人不堪者是这种忧思不能被理解，“知我者谓我心忧，不知我者谓我何求”。这是众人皆醉我独醒的尴尬，这是心智高于常人者的悲哀。这种大悲哀诉诸人间是难得回应的，只能质之于天：“悠悠苍天，此何人哉？”苍天自然也无回应，此时诗人郁懑和忧思便又加深一层。\n\n　　第二章和第三章，基本场景未变，但“稷苗”已成“稷穗”和“稷实”。稷黍成长的过程颇有象征意味，与此相随的是诗人从“中心摇摇”到“如醉”、“如噎”的深化。而每章后半部分的感叹和呼号虽然在形式上完全一样，但在一次次反覆中加深了沉郁之气，这是歌唱，更是痛定思痛之后的长歌当哭。难怪此后历次朝代更迭过程中都有人吟唱着《黍离》诗而泪水涟涟：从曹植唱《情诗》到向秀赋《思旧》，从刘禹锡的《乌衣巷》到姜夔的《扬州慢》，无不体现这种兴象风神。\n\n　　其实，诗中除了黍和稷是具体物象之外，都是空灵抽象的情境，抒情主体“我”具有很强的不确定性，基于这一点，欣赏者可根据自己不同的遭际从中寻找到与心灵相契的情感共鸣点。诸如物是人非之感，知音难觅之憾，世事沧桑之叹，无不可借此宣泄。更进一层，透过诗文所提供的具象，读者可以看到一个孤独的思想者，面对虽无灵性却充满生机的大自然，对自命不凡却无法把握自己命运的人类的前途的无限忧思，这种忧思只有“知我者”才会理解，可这“知我者”是何等样的人：“悠悠苍天，此何人哉？”充满失望的呼号中读者看到了另一个诗人的影子。“前不见古人，后不见来者，念天地之悠悠，独怆然而涕下”！吟出《登幽州台歌》的陈子昂心中所怀的正是这种难以被世人所理解的对人类命运的忧思。读此诗者当三思之。', poem_tags = '诗经,咏史怀古' WHERE poem_title = '黍离' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '项脊轩，是过去的南阁楼。屋里只有一丈见方，可以容纳一个人居住。这座百年老屋，（屋顶墙上的）泥土从上边漏下来，积聚的流水一直往下流淌；我每次动书桌，环视四周没有可以安置桌案的地方。屋子又朝北，不能被阳光照到，白天过了中午（屋内）就已昏暗。我稍稍修理了一下，使它不从上面漏土漏雨。在前面开了四扇窗子，在院子四周砌上围墙，用来挡住南面射来的日光，日光反射照耀，室内才明亮起来。我在庭院里随意地种上兰花、桂树、竹子等草木，往日的栏杆，也增加了新的光彩。家中的（这里不翻译成”借来的”）书摆满了书架，我仰头高声吟诵诗歌，有时又静静地独自端坐，自然界的万物皆有声音；庭院、台阶前静悄悄的，小鸟不时飞下来啄食，人走到它跟前也不离开。农历十五的夜晚，明月高悬，照亮半截墙壁，桂树的影子交杂错落，微风吹过影子摇动，可爱极了。\n　　然而我住在这里，有许多值得高兴的事，也有许多值得悲伤的事。在这以前，庭院南北相通成为一体。等到伯父叔父们分了家，在室内外设置了许多小门，墙壁到处都是。分家后，狗把原住同一庭院的人当作陌生人，客人得越过厨房去吃饭，鸡在厅堂里栖息。庭院中开始是篱笆隔开，然后又砌成了墙，一共变了两次。家中有个老婆婆，曾经在这里居住过。这个老婆婆，是我死去的祖母的婢女，给两代人喂过奶，先母对她很好。房子的西边和内室相连，先母曾经常来。老婆婆常常对我说：”这个地方，你母亲曾经站在这儿。”老婆婆又说：”你姐姐在我怀中，呱呱地哭泣；你母亲用手指敲着房门说：‘孩子是冷呢，还是想吃东西呢？’我隔着门一一回答……”话还没有说完，我就哭起来，老婆婆也流下了眼泪。我从十五岁起就在轩内读书，有一天，祖母来看我，说：”我的孩子，好久没有见到你的身影了，为什么整天默默地呆在这里，真像个女孩子呀？”等到离开时，用手关上门，自言自语地说：”我们家读书人很久没有得到功名了，（我）孩子的成功，就指日可待了啊！”不一会，拿着一个象笏过来，说：”这是我祖父太常公宣德年间拿着去朝见皇帝用的，以后你一定会用到它！”瞻仰回顾旧日遗物，就像在昨天一样，真让人忍不住放声大哭。\n　　项脊轩的东边曾经是厨房，人们到那里去，必须从轩前经过。我关着窗子住在里面，时间长了，能够根据脚步声辨别是谁。项脊轩一共遭过四次火灾，能够不被焚毁，大概是有神灵在保护着吧。\n　　项脊生说：巴蜀地方有个名叫清的寡妇，她继承了丈夫留下的朱砂矿，采矿获利为天下第一，后来秦始皇筑”女怀清台”纪念她。刘备与曹操争夺天下，诸葛亮出身陇中由务农出而建立勋业。当这两个人还待在不为人所知的偏僻角落时，世人又怎么能知道他们呢？我今天居住在这破旧的小屋里，却自得其乐，以为有奇景异致。如果有知道我这种境遇的人，恐怕会把我看作目光短浅的井底之蛙吧！\n　　我作了这篇文章之后，过了五年，我的妻子嫁到我家来，她时常来到轩中，向我问一些旧时的事情，有时伏在桌旁学写字。我妻子回娘家探亲，回来转述她的小妹妹们的话说：”听说姐姐家有个小阁楼，那么，什么叫小阁楼呢？”这以后六年，我的妻子去世，项脊轩破败没有整修。又过了两年，我很长时间生病卧床没有什么（精神上的）寄托，就派人再次修缮南阁子，格局跟过去稍有不同。然而这之后我多在外边，不常住在这里。\n　　庭院中有一株枇杷树，是我妻子去世那年她亲手种植的，如今已经高高挺立着，枝叶繁茂像伞一样了。', poem_notes = '项脊轩，归有光家的一间小屋。轩：小的房室。\n旧：旧日的，原来的。\n方丈：一丈见方。\n尘泥渗（shèn）漉（lù）：（屋顶墙头上的）泥土漏下。渗，透过。漉，漏下。渗漉：从小孔慢慢漏下。\n雨泽下注：雨水往下倾泻。下，往下。雨泽：雨水。\n案：几案，桌子。\n顾视：环看四周。顾，环视也。（许慎《说文解字》）\n不能得日：得日，照到阳光。\n日过午已昏：昏，光线不明。\n为（wéi）修葺（qì）。修葺：修缮、修理，修补。\n辟：开。\n垣墙周庭：庭院四周砌上围墙。垣，在这里名词作动词，指砌矮墙。垣墙：砌上围墙。周庭，（于）庭子周围。\n当：挡住\n洞然：明亮的样子。\n栏楯（shǔn）：栏杆。纵的叫栏，横的叫楯。\n增胜：增添了光彩。胜：美景。\n偃仰：偃，伏下。仰，仰起。偃仰，安居。\n啸歌：长啸或吟唱。这里指吟咏诗文，显示豪放自若。啸，口里发出长而清越的声音。\n冥然兀坐：静静地独自端坐着。兀坐，端坐。\n万籁有声：自然界的一切声音都能听到。万籁，指自然界的一切声响。籁，孔穴里发出的声音，也指一般的声响。\n三五之夜：农历每月十五的夜晚。\n珊珊：衣裾玉佩的声音，通”姗”，引申为美好的样子。\n迨（dài）诸父异爨（cuàn）：等到伯、叔们分了家。迨，及，等到。诸父，伯父、叔父的统称。异爨，分灶做饭，意思是分了家。\n往往：指到处，处处。而：修饰关系连词。是：这（样）。\n东犬西吠：东边的狗对着西边叫。意思是分家后，狗把原住同一庭院的人当作陌生人。\n逾（yú）庖（páo）而宴：越过厨房而去吃饭。庖，厨房\n已：已而，随后不久。\n凡再变矣：凡，总共。再，两次。\n相为应答：一一回答。相：偏义复词，指她（先母）。\n束发：古代男孩成年时束发为髻，15岁前指儿童时代。\n竟日：一天到晚。竟，从头到尾。\n阖（hé）：通‘合’。合上。\n瞻顾遗迹：回忆旧日事物。瞻：向前看。顾：向后看。瞻顾：泛指看，有瞻仰、回忆的意思。\n扃（jiōng）牖（yǒu）：关着窗户。扃，（从内）关闭。牖，窗户。\n殆：恐怕，大概，表示揣测的语气。\n来归：嫁到我家来。归，古代女子出嫁。\n凭几学书：伏在几案上学写字。几，小或矮的桌子。书：写字。\n归宁：出嫁的女儿回娘家省亲。\n制：指建造的格式和样子。\n手植：亲手种植。手：亲手。\n亭亭如盖：高高挺立，树冠像伞盖一样。亭亭，直立的样子。盖，古称伞。', poem_appreciation = '作者善于抓住富有特征性的细节，来描写一个封建大家庭的四分五裂之状，反映归家家庭的败落。归家原本庭院南北相通，是一个整体。自从”诸父异爨”后，设置了许多小门，墙壁到处都是（四分五裂之状）。先用篱笆相隔，后来更用一堵堵墙壁阻断往来（”始为篱，已为墙”）。尤其是”东犬西吠，客逾庖而宴，鸡栖于厅”，寥寥几笔，将一个封建大家庭分家后所产生的颓败、衰落、混乱不堪的情状表现得淋漓尽致。另外，写祖母到项脊轩来，鼓励作者读书求仕，光宗耀祖这件事，同样可透析出归家家道衰落的状况。归有光祖母的祖父曾在宣德年间担任朝廷官员（太常寺卿），而如今，”吾家读书久不效”，儿辈们科举无望，反以分家为能事，闹得个钟鸣鼎食之家四分五裂，乌烟瘴气，只有把希望寄托在孙儿归有光的身上了。\n\n　　作者善于抓住具有特征的语言、行动和生活细节来表现人物，从不同的角度把人物写得栩栩如生，情态各别。对母亲，写她听到女儿呱呱而泣时以指叩扉的动作和”儿寒乎？欲食乎？”的问话，突现了慈母对儿女衣食的无微不至的关怀。对祖母，写她的”吾儿，久不见若影……”的爱怜的言辞和离去时的喃喃自语和”以手阖扉”的动作等，惟妙惟肖地表现出了老祖母对孙儿的疼爱和期待。对妻子，写她的”时至轩中，从余问古事，或凭几学书”，简洁地表现了少年夫妇相依相爱的情状；写她归宁回来时转述小妹们的充满稚气的问话，不但传神地表现了小妹们的娇憨之态，而且生动地再现了夫妻依依情话的场面。总之，作者对于各个人物，都能分别抓住他们的特征，用寥寥几笔描绘出他们的音容笑貌和真挚的感情，富于生活情趣，并从中表达出自己对亲人一往情深的怀念。\n\n　　结构”关”情：文章先写轩的狭小、破漏与昏暗，继而写经过修葺之后的优美、宁静与恬适。轩内积书，轩外花木；白日小鸟，月夜挂影；构成了一种和谐清雅的小天地氛围。而居于这小天地中心的，正是作者自己。他的清贫的生活，高洁的志趣，怡悦的心境，于不知不觉中自然而然的显露出来。”多可喜，亦多可悲”几个字，承上启下，思路陡转。”喜”字应上文，”悲”从以下几个方面而来，一是大家庭的分崩离析，表现了作者对家庭衰败的哀痛。二是母亲对子女无微不至的关怀，表现了作者对母亲的怀念。三是祖母对作者的牵挂、赞许和期盼，含蓄地表达了怀才不遇、功名未成、辜负了亲人的抚育和期望的无限沉痛的心情。最后两节，补记亡妻在轩中的生活片断和轩在以后的变迁，抒发了作者怀念妻子的真挚情意。平淡的文字，唱出了深沉的人生哀歌。\n\n　　细节”撩”情：善于从日常生活中选取那些感受最深的细节和场面，表现人物的风貌，寄托内心的感情，是归文的一大特色。如写修葺后的南阁子，图书满架，小鸟时来，明月半墙，桂影斑驳，把作者的偃仰啸歌、怡然自得的情绪充分表现了出来。环境固然清幽、谧静，充满诗意，然而作者更为怀念的是自己的亲人。作者写祖母、写母亲、写妻子，只是通过一两件和她们有关联的事来叙述。笔墨不多，事情不大，只留下人物的一些身影，但人物的音容笑貌跃然纸上。\n\n　　如写母亲听到大姐”呱呱而泣”时，用手指轻轻叩打南阁子的门扉说：”儿寒乎？欲食乎？”极普通的动作描写，极平常的生活话语，生动地描写了母亲对孩子的慈爱之情，读来如见其人，如闻其声，倍感真切。”语未毕，余泣，妪亦泣”，悲戚的感情是很自然的生发的。林纾曾说：”震川之述老妪语，至琐细，至无关紧要，然自少失母之儿读之，匪不流涕矣。”（《古文辞类纂选本、〈项脊轩志〉评语》）。\n\n　　再如写祖母的一段文字，简洁细腻，绘声传神，”大类女郎”，”儿之成，则可待乎”一两句话；”比去，以手阖门”，”顷之，持一象笏至”一两个动作，把老年人对孙子的牵挂、赞许、鞭策的复杂感情，描绘的惟妙惟肖。写亡妻，只说：”时至轩中，从余问古事，或凭几学书。”寥寥数笔，绘出了夫妻之间的一片深情。末尾，作者把极深的悲痛寄寓一棵枇杷树。”庭有枇杷树，吾妻死之年所手植也，今已亭亭如盖矣。”枇杷树本来是无思想感情的静物，但把它的种植时间与妻子逝世之年联系起来，移情于物；在”亭亭如盖”四个字的前面加上”今已”这个时间词，表明时光在推移，静物也显示着动态。树长，人亡！物是，人非！光阴易逝，情意难忘。由于想念人而触及与人有一定关系的物，便更添了对人的思念；再由对物的联想，又引发对往事的伤怀。于是托物寄情，物我交融，进一步把思念之情深化了。只说树在生长，不说人在思念，它所产生的艺术效果则是：不言情而情无限，言有尽而意无穷。\n\n　　质朴”增”情：文章动情的另一个原因是语言质朴，不加藻饰。作者不大张声势，不故作惊人之笔，甚至也不采用色彩强烈的词藻来作恣意的渲染，而只是运用明净、流畅的语言，平平常常地叙事，老老实实地回忆。但通俗自然之中蕴含着丰富的表现力，浅显明白的文字却能使景物如画，人物毕肖。如写老妪叙述母亲之事，寥寥数语，老妪的神情、母亲的慈爱无不尽现纸上。祖母爱怜的言辞、离去时的喃喃自语、以手阖扉以及持象笏的动作等，也都是通过通俗平淡的语言变现出来的，但平淡的文字，道出了人间的亲情。此外，妻婚后来轩的往事，从娘家回来后转述的诸小妹语，亭亭如盖的枇杷树等细节，无一不是平时如话中露真情。正所谓”所为抒写怀抱之文，温润典丽，如清庙之瑟，一唱三叹。无意于感人，而欢愉惨恻之思，溢于言语之外”（王锡爵《归公墓志铭》）含而不露，以情动人，不去刻意追求强烈的效果，却取得了很好的效果，这确实是归有光散文的一个显著特色。\n\n　　叠字”助”情：和一般叠词一样，文章的叠词也是为了增加形象性和音乐美。如用”寂寂”来烘托环境之清静，用”往往”来渲染门墙之杂乱，用”呱呱”来描摹小儿的哭声，用”默默”来状写作者攻读之刻苦。又如写月下之树随风摇曳，用”姗姗”；写枇杷树高高耸立，用”亭亭”。用叠词，摹声更为真切，状物更为细致，写景更为生动。而且读起来，音节和谐，更富美感。\n\n　　一篇散文，作者六用叠词，单纯是为了状物、写景、绘情的说法，难于令人信服。”随物以宛转”，”与心而徘徊”，刘勰老先生一语中的。写物关情，情景交融，是文章多处用叠词的真实用意。如”寂寂”一词，既强调环境的清幽、静谧，又充满了对”项脊轩”的生活的怀念；”往往”一词既强调门墙到处都是，语言中又流露出作者对分家后出现的杂乱现象的不满和对家族衰败的哀痛。再如”亭亭”一词，既使人想到树木高高耸立，又使人想到人之亭亭玉立，在这一笔中间，寄寓了作者对亡人的感慨和惆怅，读来富有余味。', poem_tags = '高中文言文,叙事,抒情,生活' WHERE poem_title = '项脊轩志' AND poem_author = '归有光';
UPDATE edu_poem SET poem_translation = '范氏逃亡的时候，有个人趁机偷了一口钟，想要背着它逃跑。但是，这口钟太大了，不好背，他就打算用锤子砸碎以后再背。谁知，刚砸了一下，那口钟就“咣”地发出了很大的响声。他生怕别人听到钟声，来把钟夺走了，就急忙把自己的两只耳朵紧紧捂住继续敲。害怕别人听到钟的声音，这是可以理解的；但捂住自己的耳朵就以为别人也听不到了，这就太荒谬了。', poem_notes = '范氏之亡也：范氏是春秋末期晋国的贵族，被其他四家贵族联合打败后，逃在齐国。\n亡，逃亡。\n钟：古代的打击乐器。 \n则：但是 \n负：用背驮东西。 \n锤（chuí）：槌子或棒子。 \n况（huàng）然：形容钟声。 \n遽（jù）：立刻。 \n悖（bèi）：荒谬。 (8)恶(e):害怕。', poem_tags = '小学文言文,哲理,寓言,故事' WHERE poem_title = '掩耳盗铃' AND poem_author = '吕不韦 撰';
UPDATE edu_poem SET poem_translation = '空旷冷落的古旧行宫，只有宫花寂寞地艳红。\n几个满头白发的宫女，闲坐无事谈论唐玄宗。', poem_notes = '寥（liáo）落：寂寞冷落。\n行宫：皇帝在京城之外的宫殿。这里指当时东都洛阳的皇帝行宫上阳宫。\n宫花：行宫里的花。\n白头宫女：据白居易《上阳白发人》，一些宫女天宝末年被“潜配”到上阳宫，在这冷宫里一闭四十多年，成了白发宫人。\n说：谈论。\n玄宗：指唐玄宗。', poem_appreciation = '元稹的这首《行宫》是一首抒发盛衰之感的诗，这首短小精悍的五绝具有深邃的意境，富有隽永的诗味，倾诉了宫女无穷的哀怨之情，寄托了诗人深沉的盛衰之感。\n\n　　从诗的内容上看，理解这首诗的关键在末尾一句“闲坐说玄宗”。说者前句已经点明是“白头宫女”，时间地点则是在荒凉冷寞的古行宫，红花盛开，正是一年春好处之时。从天宝至贞元，过了半个世纪左右，漫长的岁月，风雨的侵蚀，古行宫早变得荒败不堪了，而当年入宫的红颜少女，也在寂寞孤独中苦熬了几十个春秋，如今早已是白发苍颜了。她们的青春在此葬送，她们悲怨的泪水在此流淌，她们面对着怒放的红花在感叹嘘唏。透过纯朴的字面，我们分明听到了她们痛苦的心音。白居易《上阳白发人》写道：“上阳人，红颜暗老白发新。绿衣监使守宫门，一闭上阳多少春。玄宗末岁初选入，入时十六今六十。同时采择百余人，零落年深残此身。”白诗直截了当地道出了年老宫女的幽怨，元诗则点染寥落的环境，以红色宫花和白头宫女相互衬托的笔法，通过形象对比来揭示宫女的悲惨生活和心理活动。二诗相比，一具体，一概括，一以感情的热烈淋漓见长，一以境界的深沉隽永取胜。\n\n　　这里，寥落古行宫中的白头宫女，还是唐玄宗时代历史的见证人。唐玄宗在其继位后期，宠幸杨贵妃，终日沉溺在淫乐酒色之中，把政务全部委给奸相李林甫和杨国忠，朝纲紊乱，谄佞当道，终于酿成安史之乱。乱后，玄宗被迫退位，赫赫不可一世的大唐王朝亦从此一蹶不振，日益走向下坡路。白居易在《长恨歌》里曾深致感慨说：“缓歌慢舞凝丝竹，尽日君王看不足。渔阳鼙鼓动地来，惊破霓裳羽衣曲。”四句诗，已形象地概括出玄宗昏愦好色与亡国致乱的历史因由，其讽刺与揭露是十分深刻的。元稹这首短诗当然不可能象白诗那样铺张扬厉，极尽渲染之能事，他只能采取对照、暗示点染等方法，把这一段轰轰烈烈的历史高度浓缩，加以典型化的处理，从而让人回味咀嚼。寥落的古行宫，那在寂寞之中随岁月更替而自生自落的宫花，那红颜少女的变为白发老人，都深深地带有时代盛衰迁移的痕迹。白头宫女亲历开元、天宝之世，本身就是历史的见证人，“闲坐说玄宗”的由治而乱。这本是诗篇主旨所在，也是诗人认为应引以为戒的地方，却以貌似悠闲实则深沉的笔调加以表现，语少意多，有无穷之味。\n\n　　从表现手法上来看，诗人塑造意境，艺术上主要运用了两种表现手法。一是以少总多。这首诗具有举一而反三，字少而意多的特点。四句诗，首句指明地点，是一座空虚冷落的古行宫；次句暗示环境和时间，宫中红花盛开，正当春天季节；三句交代人物，几个白头宫女，与末句联系起来推想，可知是玄宗天宝末年进宫而幸存下来的老宫人；末句描写动作，宫女们正闲坐回忆、谈论天宝遗事。二十个字，地点、时间、人物、动作，全都表现出来了，构成了一幅非常生动的画面。这个画面触发读者联翩的浮想：宫女们年轻时都是月貌花容，娇姿艳质，这些美丽的宫女被禁闭在这冷落的古行宫之中，成日价寂寞无聊，看着宫花，花开花落，年复一年，青春消逝，红颜憔悴，白发频添，如此被摧残，往事不堪重省。然而，她们被禁闭冷宫，与世隔绝，别无话题，却只能回顾天宝时代玄宗遗事，此景此情，令人凄绝。“寥落”、“寂寞”、“闲坐”，既描绘当时的情景，也反映诗人的倾向。凄凉的身世，哀怨的情怀，盛衰的感慨，二十个字描绘出生动的画面，表现出深刻的意思。\n\n　　另一个表现手法是以乐景写哀情。我国古典诗歌，其所写景物，有时从对立面的角度反衬心理，利用忧思愁苦的心情同良辰美景气氛之间的矛盾，以乐景写哀情，却能收到很好的艺术效果。这首诗也运用了这一手法。诗所要表现的是凄凉哀怨的心境，但却着意描绘红艳的宫花。红花一般是表现热闹场面，烘托欢乐情绪的，但在这里却起了很重要的反衬作用：盛开的红花和寥落的行宫相映衬，加强了时移世迁的盛衰之感；春天的红花和宫女的白发相映衬，表现了红颜易老的人生感慨；红花美景与凄寂心境相映衬，突出了宫女被禁闭的哀怨情绪。红花，在这里起了很大的作用。这都是利用好景致与恶心情的矛盾，来突出中心思想，即王夫之《姜斋诗话》所谓“以乐景写哀”，一倍增其哀。白居易《上阳白发人》“宫莺百啭愁厌闻，梁燕双栖老休妒”，也可以说是以乐写哀。不过白居易的写法直接揭示了乐景写哀情的矛盾，而元稹《行宫》则是以乐景作比较含蓄的反衬，显得更有余味。\n\n　　这首绝句语言平实，但很有概括力，精警动人，也很含蓄，给人以想象的天地，历史沧桑之感尽在不言之中，寓意深刻，自来评价很高。王建的《宫词》，白居易的《长恨歌》，元稹的《连昌宫词》，都是长达千字左右的宏篇巨制，详尽地描述了唐玄宗时代治乱兴衰的历史过程，感叹兴亡。总结教训，内容广博而深刻。元稹这首小诗总共不过二十个字，能入选《唐诗三百首》，与这些长篇巨作比美，可谓短小精悍，字字珠玑。', poem_tags = '唐诗三百首,怀古,宫怨' WHERE poem_title = '行宫' AND poem_author = '元稹';
UPDATE edu_poem SET poem_translation = '从古至今江山兴亡都无定数，眼前仿佛战角吹响烽烟滚滚战马驰骋来来去去，黄沙遮日满目荒凉谁可同语？只有萧瑟的西凤吹拂着枯老鲜红的枫树。\n从前愁苦凄滚的往事无穷无尽，铁马金戈南征北战，最终只剩日落黄昏青草掩藏着坟墓。满腹幽情情深几许，夕阳照射深山飘洒着潇潇秋雨。', poem_notes = '无定据：没有一定。宋代毛开《渔家傲·次丹阳忆故人》词：“可忍归期无定据，天涯已听边鸿度。”\n画角：古管乐器，传自西羌。因表面有彩绘，故称。发声哀厉高亢，形如竹筒，本细末大，以竹木或皮革等制成，古时军中多用以警昏晓，振士气，肃军容。帝王出巡，亦用以报警戒严。\n牧马：指古代作战用的战马．\n谁可语：有谁来和我一起谈谈。\n从前幽怨：过去各民族、各部族间的战事。\n铁马金戈：形容威武雄壮的士兵和战马。代指战事．兵事。\n青冢：长遍荒草的坟墓。这里指指王昭君墓，相传冢上草色常青，故名。杜甫《咏怀古迹》诗：“一去紫台连朔漠，独留青冢向黄昏。”\n一往情深深几许：化用欧阳修《蝶恋花》：“庭院深深深几许”句意。几许：多少。', poem_tags = '咏史怀古,豪放,边塞,写景,述志' WHERE poem_title = '蝶恋花·出塞' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '十年辛苦劳作，磨出一把利剑，剑刃寒光闪烁，只是未试锋芒。\n如今取出，给您一看，谁有不平之事，不妨如实告我。', poem_notes = '剑客：行侠仗义的人。\n霜刃：形容剑锋寒光闪闪，十分锋利。\n把示君：拿给您看。', poem_appreciation = '十年磨一剑，霜刃未曾试\n\n　　“良工锻炼凡几年，铸得宝剑名龙泉。”而此剑是“十年磨一剑”，可见其制作精良足可与传说中的龙泉宝剑比肩。开篇先侧写一笔，已显示出此剑非同一般。接着，正面一点：“霜刃未曾试。”写出此剑颜色如霜雪，闪烁着寒光，是一把锋利无比却还没有试过锋芒的宝剑。虽说“未曾试”，而跃跃欲试之意已流于言外。此剑一出，定会使人“咨嗟叹奇绝”的，这里同时表现了作者的充分自信。这位剑客经过潜心修养，苦练多年，身怀绝技却还没有机会一显身手，便不禁跃跃欲试，期盼能有表现自己才能的机会。这两句咏物而兼自喻，意在以宝剑未试来比喻自己抱负和才华不得施展。诗人未写自己十年寒窗刻苦读书的生涯，也未正面写自己出众的才能和宏大的理想，然而通过托物言志，已可洞悉诗人的心理。这种寓政治抱负于鲜明形象之中的表现手法，确是很高明的。\n\n　　今日把示君，谁有不平事\n\n　　为何铸剑十年却从未露过锋芒呢？只是因为能识此宝之人尚未出现。高山流水，知音难觅。怀才不遇者正如抱玉的卞和，如果赏识自己的人始终不出现，岂不是要活活哭死。幸运的是，韬光十载，而如今终于得遇知贤善任的知音——“君”，那还有什么好犹豫的呢？于是今日剑客便毫不犹豫地亮出了宝剑，充满自信地说：“今日把示君，谁有不平事？”今天将这把利剑拿出来给你看看，告诉我，天下谁有冤屈不平的事？此句将剑客的豪侠之风表现得痛快淋漓，仿佛剑鸣于匣，呼之欲出，读之使人顿感血脉偾张，怒发冲冠，一种急欲施展才能，干一番事业的壮志豪情，跃然纸上。\n\n　　同样以咏宝剑言志的诗还有唐代郭震的《古剑篇》，此诗化用古代著名的龙泉宝剑的传说。诗中有“虽复沉埋无所用，渊能夜夜气冲天”的句子，与贾岛的这首《剑客》一样，在借咏剑以寄托自己的理想和抱负，抒发不遇感慨的同时，表现了一种虽然身处困顿之中，却相信“天生我材必有用”，自己终究不会被埋没，终将破壁飞腾而去的强烈自信。\n\n　　这首诗思想性与艺术性结合得自然而巧妙。由于这首诗是借咏剑以寄托理想，因而求鲜明，任奔放，不求技巧，不受拘束。诗人所注重的是比喻贴切，意思显豁，主题明确。其艺术上的突出特点在于语言平易，诗思明快，诗句短小精练，更有一种干练豪爽的侠客之风，显示了贾岛诗风的另外一种特色。全诗感情奔放，气势充沛，读来剑中见人，达到人剑合一的艺术效果。实际上，这首诗在艺术上的成就，主要不在形式技巧，而在丰满地表现出诗人的形象，体现为一种典型，一种精神。诗人以剑客的口吻，着力刻画“剑”和“剑客”的形象，托物言志，抒发了兴利除弊、实现政治抱负的豪情壮志。', poem_tags = '豪情,抱负' WHERE poem_title = '剑客 / 述剑' AND poem_author = '贾岛';
UPDATE edu_poem SET poem_translation = '花丛中摆下一壶好酒，无相知作陪独自酌饮。\n举杯邀请明月来共饮，加自己身影正好三人。\n月亮本来就不懂饮酒，影子徒然在身前身后。\n暂且以明月影子相伴，趁此春宵要及时行乐。\n我唱歌月亮徘徊不定，我起舞影子飘前飘后。\n清醒时我们共同欢乐，酒醉以后各奔东西。\n但愿能永远尽情漫游，在茫茫的天河中相见。\n\n天如果不爱酒，酒星就不能罗列在天。\n地如果不爱酒，就不应该地名有酒泉。\n天地既然都喜爱酒，那我爱酒就无愧于天。\n我先是听说酒清比作圣，又听说酒浊比作贤。\n既然圣贤都饮酒，又何必再去求神仙？三\n杯酒可通儒家的大道，一斗酒正合道家的自然。\n我只管得到醉中的趣味，这趣味不能向醒者相传！\n\n三月里的长安城，春光明媚，春花似锦。\n谁能如我春来独愁，到此美景只知一味狂饮？\n富贫与长寿，本来就造化不同，各有天分。\n酒杯之中自然死生没有差别，何况世上的万事根本没有是非定论。\n醉后失去了天和地，一头扎向了孤枕。\n沉醉之中不知还有自己，这种快乐何处能寻？\n\n无穷的忧愁有千头万绪，我有美酒三百杯多。\n即使酒少愁多，美酒一倾愁不再回。\n因此我才了解酒中圣贤，酒酣心自开朗。\n辞粟只能隐居首阳山，没有酒食颜回也受饥。\n当代不乐于饮酒，虚名有什么用呢？\n蟹螯就是仙药金液，糟丘就是仙山蓬莱。\n姑且先饮一番美酒，乘着月色在高台上大醉一回。', poem_notes = '酌：饮酒。独酌：一个人饮酒。\n间：一作“下”， 一作“前”。\n无相亲：没有亲近的人。\n“举杯”二句：我举起酒杯招引明月共饮，明月和我以及我的影子恰恰合成三人。一说月下人影、酒中人影和我为三人。\n既：已经。不解：不懂，不理解。三国魏嵇康《琴赋》：“推其所由，似元不解音声。”\n徒：徒然，白白的。徒：空。\n将：和，共。\n及春：趁着春光明媚之时。\n月徘徊：明月随我来回移动。\n影零乱：因起舞而身影纷乱。\n同交欢：一起欢乐。一作“相交欢”。\n无情游：月、影没有知觉，不懂感情，李白与之结交，故称“无情游”。\n相期邈（miǎo）云汉：约定在天上相见。期：约会。邈：遥远。云汉：银河。这里指遥天仙境。“邈云汉”一作“碧岩畔”。\n酒星：古星名。也称酒旗星。《晋书·天文志》云：“轩辕右角南三星曰酒旗，酒官之旗也，主享宴酒食。”汉孔融《与曹操论酒禁书》：“天垂酒星之耀，地列酒泉之郡，人著旨酒之德。”\n酒泉：酒泉郡，汉置。传说郡中有泉，其味如酒，故名酒泉。在今甘肃省酒泉市。\n大道：指自然法则。《庄子·天下》：“天能覆之而不能载之，地能载之而不能覆之，大道能包之而不能辩之，知万物皆有所可，有所不可。”\n酒中趣：饮酒的乐趣。晋陶潜《晋故征西大将军长史孟府君传》：“温（桓温）尝问君：‘酒有何好，而卿嗜之？’君笑而答曰：‘明公但不得酒中趣尔。’”\n“三月”二句：一作“好鸟吟清风，落花散如锦”；一作“园鸟语成歌，庭花笑如锦”。咸阳城：此指长安城。“城”一作“时”。\n径须：直须。李白《将进酒》诗：“主人何为言少钱，径须沽取对君酌。”\n穷通：困厄与显达。《庄子·让王》：“古之得道者，穷亦乐，通亦乐，所乐非穷通也；道德于此，则穷通为寒暑风雨之序矣。”修短：长短。指人的寿命。《汉书·谷永传》：“加以功德有厚薄，期质有修短，时世有中季，天道有盛衰。”\n造化：自然界的创造者。亦指自然。《庄子·大宗师》：“今一以天地为大炉，以造化为大冶，恶乎往而不可哉？”\n齐死生：生与死没有差别。\n兀然：昏然无知的样子。孤枕：独枕。借指独宿、独眠。唐李商隐《戏赠张书记》诗：“别馆君孤枕，空庭我闭关。”\n穷愁：穷困愁苦。《史记·平原君虞卿列传论》：“然虞卿非穷愁，亦不能著书以自见于后世云。”千万端：一作“有千端”。\n三百杯：一作“唯数杯”。\n酒圣：谓豪饮的人。宋曾巩《招泽甫竹亭闲话》诗：“诗豪已分材难强，酒圣还谙量未宽。”\n卧首阳：一作“饿伯夷”。首阳，山名。一称雷首山，相传为伯夷、叔齐采薇隐居处。\n屡空：经常贫困。谓贫穷无财。《论语·先进》：“回也其庶乎！屡空。”何晏集解：“言回庶几圣道，虽数空匮而乐在其中。”颜回：春秋末期鲁国人，孔子的得意门生。\n乐饮：畅饮。《史记·高祖本纪》：“沛父兄诸母故人日乐饮极驩，道旧故为笑乐。”\n安用：有什么作用。安，什么。\n蟹螯（áo）：螃蟹变形的第一对脚。状似钳，用以取食或自卫。《晋书·毕卓传》：“右手持酒杯，左手持蟹螯，拍浮酒船中，便足了一生矣。”金液：喻美酒。唐白居易《游宝称寺》诗：“酒懒倾金液，茶新碾玉尘。”\n糟丘：积糟成丘。极言酿酒之多，沉湎之甚。《尸子》卷下：“六马登糟丘，方舟泛酒池。”蓬莱：古代传说中的神山名。此处泛指仙境。\n乘月：趁着月光。《乐府诗集·清商曲辞一·子夜四时歌夏歌一》：“乘月采芙蓉，夜夜得莲子。”', poem_appreciation = '这组诗共四首，以第一首流传最广。第一首诗写诗人由政治失意而产生的一种孤寂忧愁的情怀。诗中把寂寞的环境渲染得十分热闹，不仅笔墨传神，更重要的是表达了诗人善自排遣寂寞的旷达不羁的个性和情感。此诗背景是花间，道具是一壶酒，登场角色只是他自己一个人，动作是独酌，加上“无相亲”三个字，场面单调得很。于是诗人忽发奇想，把天边的明月，和月光下自己的影子，拉了过来，连自己在内，化成了三个人，举杯共酌，冷清清的场面，顿觉热闹起来。然而月不解饮，影徒随身，仍归孤独。因而自第五句至第八句，从月影上发议论，点出“行乐及春”的题意。最后六句为第三段，写诗人执意与月光和身影永结无情之游，并相约在邈远的天上仙境重见。诗人运用丰富的想象，表现出一种由独而不独，由不独而独，再由独而不独的复杂情感。全诗以独白的形式，自立自破，自破自立，诗情波澜起伏而又纯乎天籁，因此一直为后人传诵。\n\n　　第二首诗通篇议论，堪称是一篇“爱酒辩”。开头从天地“爱酒”说起。以天上酒星、地上酒泉，说明天地也爱酒，再得出“天地既爱酒，爱酒不愧天”的结论。接着论人。人中有圣贤，圣贤也爱酒，则常人之爱酒自不在话下。这是李白为自己爱酒寻找借口，诗中说：“贤圣既已饮，何必求神仙。”又以贬低神仙来突出饮酒。从圣贤到神仙，结论是爱酒不但有理，而且有益。最后将饮酒提高到最高境界：通于大道，合乎自然，并且酒中之趣的不可言传的。此诗通篇说理，其实其宗旨不在明理，而在抒情，即以说理的方式抒情。这不合逻辑的议论，恰恰十分有趣而深刻地抒发了诗人的情怀，诗人的爱酒，只是对政治上失意的自我排遣。他的“酒中趣”，正是这种难以言传的情怀。\n\n　　第三首诗开头写诗人因忧愁不能乐游，所以说“谁能春独愁，对此径须饮”，诗人希望从酒中得到宽慰。接着诗人从人生观的角度加以解释，在精神上寻求慰藉，并得出“此乐最为甚”的结论。诗中说的基本是旷达乐观的话，但“谁能春独愁”一语，便流露出诗人内心的失意悲观情绪。旷达乐观的话，都只是强自宽慰。不止不行，不塞不流。强自宽慰的结果往往是如塞川流，其流弥激。当一个人在痛苦至极的时候发出一声狂笑，人们可以从中体会到其内心的极度痛苦；而李白在失意愁寂难以排遣的时候，发出醉言“不知有吾身，此乐最为甚”时，读者同样可以从这个“乐”字感受到诗人内心的痛苦。以旷达写牢骚，以欢乐写愁苦，是此诗艺术表现的主要特色，也是艺术上的成功之处。\n\n　　第四首诗借用典故来写饮酒的好处。开头写诗人借酒浇愁，希望能用酒镇住忧愁，并以推理的口气说：“所以知酒圣，酒酣心自开。”接着就把饮酒行乐说成是人世生活中最为实用最有意思的事情。诗人故意贬抑了伯夷、叔齐和颜回等人，表达虚名不如饮酒的观点。诗人对伯夷、叔齐和颜回等人未必持否定态度，这样写是为了表示对及时饮酒行乐的肯定。然后，诗人又拿神仙与饮酒相比较，表明饮酒之乐胜于神仙。李白借用蟹螯、糟丘的典故，并不是真的要学毕卓以饮酒了结一生，更不是肯定纣王在酒池肉林中过糜烂生活，只是想说明必须乐饮于当代。最后的结论就是：“且须饮美酒，乘月醉高台。”话虽这样说，但只要细细品味诗意，便可以感觉到，诗人从酒中领略到的不是快乐，而是愁苦。', poem_tags = '月亮,怀才不遇,孤独,饮酒,组诗' WHERE poem_title = '月下独酌四首' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '廉颇是赵国优秀的将领。赵惠文王十六年，时为赵国将军的廉颇率领赵军征讨齐国，大败齐军，夺取了阳晋，晋升为上卿，从此他以英勇善战闻名于诸侯各国。蔺相如，赵国人，他是赵国的宦官首领缪贤家的门客。\n\n　　赵惠文王的时候，得到了楚人的和氏璧。秦昭王听说了这件事，就派人给赵王送来一封书信，表示愿意用十五座城池交换和氏璧。赵王同大将军廉颇以及诸大臣们商量：如果把宝玉给了秦国，秦国的城邑恐怕不可能得到，白白地受到欺骗；如果不给他，又恐怕秦国来攻打。尚未找到合适的解决办法，寻找一个能到秦国去回复的使者，也未能找到。宦官令缪贤说：“我的门客蔺相如可以出使。”赵王问：“你是怎么知道他可以出使的？”缪贤回答说：“微臣曾犯过罪，私下打算逃亡到燕国去，我的门客相如劝阻我不要去，问我说：‘您怎么会了解燕王呢？’我对他说：‘我曾随从大王在国境上与燕王会见，燕王私下握住我的手，说“情愿跟您交个朋友”。因此了解他，所以打算投奔燕王。’相如对我说：‘赵国强，燕国弱，而您受宠于赵王，所以燕王想要和您结交。现在您是从赵国逃亡到燕国去，燕国惧怕赵国，这种形势下燕王必定不敢收留您，而且还会把您捆绑起来送回赵国。您不如脱掉上衣，露出肩背，伏在斧刃之下请求治罪，这样也许侥幸被赦免。’臣听从了他的意见，大王也开恩赦免了为臣。为臣私下认为这人是个勇士，有智谋，应该可以出使。”于是赵王立即召见，问蔺相如：“秦王用十五座城池请求交换我的和氏璧，能不能给他？”相如说：“秦国强，赵国弱，不能不答应它。”赵王说：“得了我的宝璧，不给我城邑，怎么办？”相如说：“秦国请求用城换璧，赵国如不答应，赵国理亏；赵国给了璧而秦国不给赵国城邑，秦国理亏。衡量一下两种对策，宁可答应它，使秦国来承担理亏的责任。”赵王说：“谁可以前往？”相如说：“大王如果无人可派，臣愿捧护宝璧前往出使。城邑归属赵国了，就把宝璧留给秦国；城邑不能归赵国，我一定把和氏璧完好地带回赵国。”赵王于是就派遣蔺相如带好和氏璧，西行入秦。\n\n　　秦王坐在章台上接见蔺相如，相如捧璧呈献给秦王。秦王非常高兴，把宝璧传着给妻妾和左右侍从看，左右都高呼万岁。相如看出秦王没有用城邑抵偿赵国的意思，便走上前去说：“璧上有个小斑点，让我指给大王看。”秦王把璧交给他，相如于是手持璧玉退后几步靠在柱子上，怒发冲冠，对秦王说：“大王想得到宝璧，派人送信给赵王，赵王召集全体大臣商议，大家都说：‘秦国贪得无厌，倚仗它的强大，想用空话得到宝璧，说给我们城邑恐怕不可能。’商议的结果是不想把宝璧给秦国。但是我认为平民百姓之间的交往尚且互相不欺骗，更何况是大国之间呢！况且为了一块璧玉的缘故就使强大的秦国不高兴，也是不应该的。于是赵王斋戒了五天，派我捧着宝璧，在殿堂上恭敬地拜送国书。为什么要这样呢？是尊重大国的威望以表示敬意呀。如今我来到贵国，大王却在一般的台观上接见我，礼节十分傲慢；得到宝璧后，传给姬妾们观看，这样来戏弄我。我观察大王没有给赵王十五城的诚意，所以我又取回宝璧。大王如果一定要逼我，我的头今天就同宝璧一起在柱子上撞碎！”相如手持宝璧，斜视庭柱，就要向庭柱上撞去。秦王怕他把宝璧撞碎，便向他道歉，坚决请求他不要如此，并召来有司查看地图，指明从某地到某地的十五座城邑都给赵国。相如估计秦王只不过用欺诈手段假装给赵国城邑，实际上赵国根本不可能得到，于是就对秦王说：“和氏璧是天下公认的宝物，赵王惧怕贵国，不敢不奉献出来。赵王送璧之前，斋戒了五天，如今大王也应斋戒五天，在殿堂上安排九宾大典，我才敢献上宝璧。”秦王估量，毕竟不可能强力夺取，于是就答应斋戒五天，把相如安置在广成宾馆。相如估计秦王虽然答应斋戒，也必定背约不给城邑，便派他的随从穿上粗麻布衣服，怀中藏好宝璧，从小路逃出，把宝璧送回赵国。\n\n　　秦王斋戒五天后，就在殿堂上安排了九宾的大典礼，宴请赵国使者蔺相如。相如来到后，对秦王说：“秦国从穆公以来的二十余位君主，从没有一个是能切实遵守信约的。我实在是害怕被大王欺骗而对不起赵王，所以派人带着宝璧回去，已从小路回到赵国了。况且秦国强大赵国弱小，大王派遣一位使臣到赵国，赵国立即就会把璧送来。如今凭着秦国的强大，先把十五座城邑割让给赵国，赵国哪里敢留下宝璧而得罪大王呢？我知道欺骗大王是应该被诛杀的，我愿意接受汤镬之刑，只希望大王和各位大臣从长计议此事！”秦王和群臣面面相觑，发出苦笑之声。侍从有人要拉相如去受刑，秦王趁机说：“如今杀了相如，终归还是得不到宝璧，反而破坏了秦赵两国的交情，不如趁此好好款待他，放他回到赵国，赵王难道会为了一块璧玉的缘故而欺骗秦国吗！”最终还是在殿堂上隆重地接见了相如，大礼完后让他回了国。\n\n　　相如回国后，赵王认为他是一位有德行、有才能的贤大夫，出使诸侯国，能做到不辱使命，于是封相如为上大夫。此后秦国并没有把城邑给赵国，赵国也始终不给秦国宝璧。\n\n　　此后秦国攻打赵国，夺取了石城。第二年，秦国再次攻打赵国，杀死两万人。\n\n　　秦王派使者告诉赵王，想在西河外的渑池与赵王进行一次友好会见。赵王害怕秦国，打算不去。廉颇、蔺相如商量道：“大王如果不去，就显得赵国既软弱又胆小。”赵王于是前去赴会，蔺相如随行。廉颇送到边境，和赵王诀别说：“大王此行，估计路程和会谈结束，再加上返回的时间，不会超过三十天。如果三十天还没回来，就请您允许我们立太子为王，以断绝秦国要挟的妄想。”赵王答应了，便去渑池与秦王会见。秦王饮到酒兴正浓时，说：“我私下里听说赵王爱好音乐，请您奏瑟一曲！”赵王就弹起瑟来。秦国的史官上前来写道：“某年某月某日，秦王与赵王一起饮酒，令赵王弹瑟。”蔺相如上前说：“赵王私下里听说秦王擅长秦地土乐，请让我给秦王捧上盆，来相互为乐。”秦王发怒，不答应。这时蔺相如向前进献瓦缻，并跪下请秦王演奏。秦王不肯击缻，蔺相如说：“在这五步之内，如果我自杀，脖颈里的血可以溅在大王身上了！”秦王的侍从们想要杀蔺相如，蔺相如睁圆双眼大声斥骂他们，侍从们都吓得倒退。因此秦王很不高兴，也只好敲了一下缻。相如回头来招呼赵国史官写道：“某年某月某日，秦王为赵王击缻。”秦国的大臣们说：“请你们用赵国的十五座城池向秦王献礼。”蔺相如也说：“请你们用秦国的咸阳向赵王献礼。”直到酒宴结束，秦王始终也未能压倒赵王。赵国也部署了大批军队来防备秦国，因而秦国也不敢轻举妄动。\n\n　　渑池会结束以后回到赵国，由于蔺相如功劳大，被封为上卿，官位在廉颇之上。廉颇说：“作为赵国的将军，我有攻战城池作战旷野的大功劳，而蔺相如只不过靠能说会道立了点功，可是他的地位却在我之上，况且蔺相如本来就出身卑贱，我感到羞耻，无法容忍在他的下面。”并且扬言说：“我遇见蔺相如，一定要羞辱他一番。”蔺相如听到这话后，不愿意和廉颇相会。每到上朝时，蔺相如常常声称有病，不愿和廉颇去争位次的先后。没过多久，蔺相如外出，远远看到廉颇，蔺相如就掉转车子回避。于是蔺相如的门客就一起来向蔺相如抗议说：“我们之所以离开亲人来侍奉您，是仰慕您高尚的节义呀。如今您与廉颇官位相同，廉颇传出坏话，而您却害怕躲避着他，胆怯得也太过分了，一般人尚且感到羞耻，更何况是身为将相的人呢！我们这些人没有出息，请让我们辞去吧！”蔺相如坚决地挽留他们，说：“诸位认为廉将军和秦王相比谁更厉害？”众人都说：“廉将军比不上秦王。”蔺相如说：“以秦王的威势，而我尚敢在朝廷上呵斥他，羞辱他的群臣，我蔺相如虽然无能，难道会害怕廉将军吗！但是我想到，强大的秦国之所以不敢对赵国用兵，就是因为有我们两人在呀。如今我们俩相斗，就如同两猛虎争斗一般，势必不能同时生存。我所以这样忍让，就是将国家的危难放在前面，而将个人的私怨搁在后面罢了！”廉颇听说了这些话，就脱去上衣，露出上身，背着荆鞭，由宾客引领，来到蔺相如的门前请罪，他说：“我这个粗野卑贱的人，想不到将军的胸怀如此宽大啊！”二人终于相互交欢和好，成了生死与共的好友。', poem_notes = '1.赵惠文王十六年：公元前283年。赵惠文王，赵国君主，名何。\n2.阳晋：齐国城邑，在今山东菏泽西北。\n3.上卿：战国时期诸侯国大臣中最高的官位。\n4.宦者令：宦官的首领。\n5.舍人：有职务的门客。\n6.和氏璧：战国时著名的玉璧，是楚人卞和发现的，故名。事见《韩非子·何氏》。\n7.秦昭王：即秦昭襄王，名则。\n8.遗（wèi）：送。\n9.徒见欺：白白地被欺骗。\n10.亡走燕：逃到燕国去。\n11.何以知燕王：根据什么知道燕王（会收留你）。\n12.境上：指燕赵两国的边境。\n13.幸于赵王：被赵王宠爱。幸，宠幸。\n14.乃：却，竟然。\n15.束君归赵：把您捆绑起来送还赵国。\n16.肉袒伏斧质：解衣露体，伏在斧质上。袒，脱衣露体。质，同“锧”，承斧的砧板。\n17.宜可使：可供差遣。宜，适宜。\n18.不：同“否”。\n19.曲：理屈，理亏。\n20.均之二策：衡量这两个计策。均，衡量。之，这。\n21.宁许以负秦曲：宁可答应，而让秦国承担理亏的责任。\n22.奉：捧着。\n23.完璧归赵：让璧完整无损地归还赵国。\n24.章台：秦离宫中的台观名。\n25.奏：进献。\n26.美人：指秦王的姬妾。\n27.偿赵城：把十五城补偿给赵国。\n28.瑕：玉上的斑点或裂痕。\n29.却立：倒退几步立定。\n30.怒发上冲冠：愤怒得头发直竖，顶起了冠。形容极其愤怒。\n31.负：倚仗。\n32.布衣之交：平民间的交往。古代平民只穿麻衣、葛布，故称布衣。\n33.逆：拂逆，触犯。\n34.斋戒：古人祭祀之前，一定要沐浴更衣，节制饮食，表示虔诚，叫做斋戒。\n35.书：指赵王的复信。\n36.庭：同“廷”，朝堂。\n37.严：尊重，敬畏。\n38.修敬：致敬。\n39.列观（guàn）：一般的台观，指章台。不在朝堂接见，说明秦对赵使的不尊重。\n40.急：逼迫。\n41.睨（nì）：斜视。\n42.辞谢：婉言道歉。\n43.固请：坚决请求（相如不要把璧撞破）。\n44.有司：职有专司的官吏。\n45.案图：查明地图。案，同“按”。\n46.都：城邑。\n47.特：只，只是。\n48.详为：假装做。详，同“佯”，假装。\n49.共传：等于说公认。\n50.设九宾：一种外交上最隆重的仪式。有傧相九人依次传呼接引宾客上殿。宾，同“傧”。\n51.舍：安置。\n52.广成传（zhuàn）：广成，宾馆名。传，传舍，宾馆。\n53.衣（yì）褐：穿着粗麻布短衣，指化装成平民百姓。\n54.径道：小路。\n55.缪公：即秦穆公。缪，同“穆”。\n56.坚明约束：坚决明确地遵守信约。约束，信约。\n57.间（jiàn）：抄小路，与上文“从径道亡”相应。\n58.立：立刻。\n59.就汤镬（huò）：指接收烹刑。汤，沸水。镬，大锅。\n60.孰：同“熟”，仔细。\n61.嘻：苦笑声。\n62.因而厚遇之：趁此优厚地款待他。\n63.卒廷见相如：终于在朝堂上接见蔺相如。\n64.毕礼而归之：举行完廷见的外交大礼然后送他回国。\n65.拔石城：攻取石城。石城，故址在今河南林州西南。\n66.为好：修好。\n67.西河外渑（miǎn）池：西河，黄河西边。渑池，今河南渑池。\n68.欲毋行：想不去。\n69.诀：告别。\n70.度道里会遇之礼毕：估算前往渑池的路程和会谈完毕的时间。道里，路程。\n71.绝秦望：断绝秦国要挟胁迫的念头。\n72.好音：喜欢音乐。\n73.瑟：古代乐器，形似琴而较长大。通常配有二十五根弦。\n74.御史：官名。战国时御史专管图籍，记载国家大事。\n75.秦声：秦国的音乐。\n76.盆缻（fǒu）：均为瓦器。缻，同“缶”。秦人敲打盆缶作为唱歌时的节拍。\n77.刃：刀锋。这里是杀的意思。\n78.叱：喝骂。\n79.靡：倒下，这里指后退。\n80.怿（yì）：愉快。\n81.为秦王寿：祝秦王长寿，指向秦王献礼。\n82.竟酒：直到酒宴完毕。\n83.盛设兵：多布置军队。\n84.右：上。古人以右为尊。\n85.相如素贱人：指蔺相如这个人做过太监的家臣，向来微贱。素，素来，向来。\n86.争列：争位次的高下。\n87.引车避匿：将车子调转躲避。\n88.舍人：指蔺相如的门客。\n89.相与：一起，共同。\n90.孰与秦王：与秦王相比怎么样？孰与，与……相比。孰，谁，哪一个。\n91.驽：愚笨，拙劣。\n92.负荆：背着荆条，表示愿受鞭打。\n93.因：通过。\n94.将军：当时的上卿兼职将相，所以廉颇这样称呼蔺相如。\n95.刎（wěn）颈之交：指能够共患难、同生死的朋友。刎颈，杀头。刎，割。', poem_appreciation = '《廉颇蔺相如列传》生动刻画了廉颇、蔺相如、赵奢、李牧、赵惠文王等一批性格各异的人物形象，他们或耿直或忠厚，或鲁莽或机智，形象鲜明生动，令人叹服。\n\n　　抓住人物特征，人物形象凸现纸上。司马迁善于抓住人物主要特征进行极力渲染。如在对事迹颇丰的蔺相如这一形象进行处理时，便抓住“智勇”这一特征为核心展开描述。正如他在本传传末所论赞的：“太史公曰：知死必勇，非死者难也，处死者难也。方蔺相如引璧睨柱，及叱秦王左右，势不过诛，然士或怯懦而不敢发。相如一奋其气，威信敌国；退而让颇，名重泰山。其处智勇，可谓兼之矣！”在对完璧归赵、渑池之会等事件进行描述时更是紧紧扣住蔺相如的机智勇敢这一特征，给读者留下深刻的印象。\n\n　　层层衬染，极力蓄势，造成人物形象的张势。司马迁在文中极尽渲染之能事，层层蓄势，有如大江截流。如他在文中五次渲染相如操天下大势为己用之睿智：为国纾难，利用国际舆论，借使秦负曲之势，奉璧至秦；秦王得璧不偿城，相如以“璧有瑕，请指示王”诓得玉璧后，抓住秦王贪婪的弱点，欲以璧击柱，借“秦恐璧破”之势威胁秦王；抓住秦国二十余君“不坚明约束”之过，借理在我方之势，使人怀璧归赵；渑池之会，借“五步之内以颈血溅大王”之势，逼秦王就范，为一击缶；借“赵亦盛设兵以待秦”之势，迫使秦不敢动武。相如勇智，已是光彩照人。行文至此，司马迁笔势陡转：多谋善断、意气风发的蔺相如竟对无理取闹的廉颇一再退忍避让，连门客都感到羞愧。当门客要离开他时，才袒露他“先国家之急而后私仇也”的胸怀。相如的绝顶智慧和贤相风采凸现在读者的眼前。', poem_tags = '高中文言文,传记,赞美,写人' WHERE poem_title = '廉颇蔺相如列传(节选)' AND poem_author = '司马迁';
UPDATE edu_poem SET poem_translation = '病体虚弱消瘦，以致头上的纱帽也显得宽大了，孤单一人客居在万里之外的成都江边。\n虽然职位低微却从未敢忘记忧虑国事，但若想实现统一理想，只有死后才能盖棺定论。\n希望天地神灵保佑国家社稷，北方百姓都在日夜企盼着君主御驾亲征收复失落的河山。\n诸葛孔明的传世之作《出师表》忠义之气万古流芳，深夜难眠，还是挑灯细细品读吧。', poem_notes = '病起：病愈。\n病骨：指多病瘦损的身躯。支离：憔悴；衰疲。\n孤臣：孤立无助或不受重用的远臣。江干：江边；江岸。\n忘忧：忘却忧虑。\n阖（hé ）棺：指死亡，诗中意指：盖棺定论。\n庙社：宗庙和社稷，以喻国家。\n京华：京城之美称。因京城是文物、人才汇集之地，故称。 和銮（luán）：同“ 和鸾 ”。古代车上的铃铛。挂在车前横木上称“和”，挂在轭首或车架上称“銮”。诗中代指“君主御驾亲征，收复祖国河山”的美好景象。\n出师一表：指三国时期诸葛亮所作《出师表》。\n挑灯：拨动灯火，点灯。亦指在灯下。', poem_appreciation = '《病起书怀》载于《剑南诗稿》，此诗贯穿了诗人忧国忧民的爱国情怀，表现了中华子民热爱祖国的伟大精神，揭示了百姓与国家的血肉关系。“位卑未敢忘忧国”这一传世警句，是诗人内心的真实写照，也是历代爱国志士爱国之心的真实写照，这也是它能历尽沧桑，历久常新的原因所在。诗人想到自己一生屡遭挫折，壮志难酬，而年已老大，自然有着深深的慨叹和感伤；但他在诗中说一个人盖棺方能论定，表明诗人对前途仍然充满着希望。\n\n　　首联“病骨支离纱帽宽，孤臣万里客江干”。叙事、点题，是诗人诗文自身的写照“纱帽宽”，一语双关，既言其病后瘦损，故感帽沿宽松。也暗含被贬官之意，写出了现实，纵使有满腔报国之志，也只能身处江湖之远，客居江边，无力回天，心中的痛苦与烦恼可见一斑。\n\n　　颔联“位卑未敢忘忧国，事定犹须待阖棺”。为全篇的主旨所在，其中“位卑未敢忘忧国”同顾炎武的“天下兴亡，匹夫有责“意思相近，它的主旨就是热爱祖国。这两句使我们看到诗人高尚的人格和一颗忠心爱国的赤子之心。正因为诗人光明磊落、心地坦荡，所以他对暂时遭遇的挫折并不介意。他坚信历史是公正的，是一定会对一个人做出恰如其分的评价的。但是诗人并没有局限于抒写自己的情怀，而是以国家的大事为己任。\n\n　　颈联“天地神灵扶庙社，京华父老望和銮”。宕开一笔，抒写了对国家政局的忧虑同时呼吁朝廷北伐，重返故都，以慰京华父老之望。在这里诗人寄托了殷切的期望：但愿天地神灵扶持国家，使过大民众脱离战火，安乐昌盛。\n\n　　尾联“出师一表通今古，夜半挑灯更细看”。采用典故抒发了诗人的爱国情怀，可收复河山对于诗人来说毫无办法。只能独自一人挑灯细看诸葛亮的传世之作，希望皇帝能早日悟出“出师一表通古今”的道理。', poem_tags = '古诗三百首,爱国,励志,忧国忧民,壮志难酬' WHERE poem_title = '病起书怀' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '在一片被寒霜打过的灰白色秋草中，小虫在窃窃私语着，山村周围行人绝迹。\n我独自来到前门眺望田野，只见皎洁的月光照着一望无际的荞麦田，满地的荞麦花简直就像一片耀眼的白雪。', poem_notes = '霜草：被秋霜打过的草。\n苍苍：灰白色。\n切切：虫叫声。\n绝：绝迹。\n独：单独，一个人。\n野田：田野。\n荞麦：一年生草本植物，子实黑色有棱，磨成面粉可食用。', poem_tags = '乡村,写景' WHERE poem_title = '村夜' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '飒飒秋风卷地而来，满园菊花瑟瑟飘摇。花蕊花香充满寒意，蝴蝶蜜蜂难以到来。\n有朝一日，我要当了春神，我将安排菊花和桃花同在春天盛开。', poem_notes = '飒飒：形容风声。\n蕊：花心儿。\n青帝：司春之神。古代传说中的五天帝之一，住在东方，主行春天时令。\n报：告诉，告知，这里有命令的意思。', poem_appreciation = '唐末诗人林宽有这样两句诗：“莫言马上得天下，自古英雄皆解诗。”古往今来，确有不少能“解诗”的英雄，唐末农民起义领袖黄巢就是其中突出的一个。自从陶渊明“采菊东篱下，悠然见南山”的名句一出，菊花就和孤标傲世的高士、隐者结下了不解之缘，几乎成了封建文人孤高绝俗精神的一种象征。黄巢的菊花诗，却完全脱出了同类作品的窠臼，表现出全新的思想境界和艺术风格。\n\n　　第一句写满院菊花在飒飒秋风中开放。“西风”点明节令，逗起下句；“满院”极言其多。说“栽”而不说“开”，是避免与末句重韵，同时“栽”字本身也给人一种挺立劲拔之感。写菊花迎风霜开放，以显示其劲节，这在文人的咏菊诗中也不难见到；但“满院栽”却不同于文人诗中菊花的形象。无论是表现“孤标傲世”之情，“孤高绝俗”之态或“孤孑无伴”之感，往往脱离不了一个“孤”字。黄巢的诗独说“满院栽”，是因为在他心目中，这菊花是劳苦大众的象征，与“孤”字无缘。\n\n　　菊花迎风霜开放，固然显出它的劲节，但时值寒秋，“蕊寒香冷蝶难来”，却是极大的憾事。在飒飒秋风中，菊花似乎带着寒意，散发着幽冷细微的芳香，不象在风和日丽的春天开放的百花，浓香竞发，因此蝴蝶也就难得飞来采掇菊花的幽芳了。在旧文人的笔下，这个事实通常总是引起两种感情：孤芳自赏与孤孑不偶。作者的感情有别于此。在他看来，“蕊寒香冷”是因为菊花开放在寒冷的季节，他自不免为菊花的开不逢时而惋惜、而不平。\n\n　　第三、四两句正是上述感情的自然发展，揭示环境的寒冷和菊花命运的不公平。作者想象有朝一日自己作了“青帝”（司春之神），就要让菊花和桃花一起在春天开放。这一充满强烈浪漫主义激情的想象，集中地表达了作者的宏伟抱负。统观全诗，寓意是比较明显的。诗中的菊花，是当时社会上千千万万处于底层的人民的化身。作者既赞赏他们迎风霜而开放的顽强生命力，又深深为他们所处的环境、所遭的命运而愤激不平，立志要彻底加以改变。所谓“为青帝”，不妨看作建立农民革命政权的形象化表述。作者想象，到了那一天，广大劳苦大众就都能生活在温暖的春天里。值得注意的是，这里还体现了农民朴素的平等观念。因为在作者看来，菊花和桃花同为百花之一，理应享受同样的待遇，菊花独处寒秋，蕊寒香冷，实在是天公极大的不公。因此他决心要让菊花同桃花一样享受春天的温暖。不妨认为，这是诗化了的农民平等思想。\n\n　　这里还有一个靠谁来改变命运的问题。是祈求天公的同情与怜悯，还是“我为青帝”，取而代之，其间存在着做命运的奴隶和做命运的主人的区别。诗的作者说：“我为青帝”，这豪迈的语言，正体现了农民阶级领袖人物推翻旧政权的决心和信心。而这一点，也正是一切封建文人所不能超越的铁门槛。\n\n　　这首诗所抒写的思想感情是非常豪壮的，它使生活在封建社会中的文人学士表达自己胸襟抱负的各种豪言壮语都相形失色。但它并不流于粗豪，仍不失含蕴。这是因为诗中成功地运用了比兴手法，而比兴本身又融合着作者对生活的独特感受与理解的缘故。', poem_tags = '咏物,菊花,抒怀,豪壮,猖狂' WHERE poem_title = '题菊花' AND poem_author = '黄巢';
UPDATE edu_poem SET poem_translation = '明月照在高楼之上，洒下的光芒在楼上游移不定。\n楼上有一位哀愁的妇人，正在悲哀的叹息。\n请问楼上唉声叹气的是谁？回答说是异地客旅者的妻子。\n丈夫离开超过了十年，妾身常常一个人。\n夫君像是路上的轻尘般飘忽，妾身像是污浊的水中的淤泥。\n浮尘和沉泥各自相异，什么时候才能相互汇合相互和谐？\n可以的话，我愿意化作西南风，在人间消失而进入夫君的怀抱中！\n夫君的胸怀早已不向我开放了，我还有什么可依靠的呢？', poem_notes = '七哀：该篇是闺怨诗，也可能借此“讽君”。七哀作为一种乐府新题，起于汉末。\n流光：洒下的月光。\n余哀：不尽的忧伤。\n宕（dàng）子：荡子。指离乡外游，久而不归之人。\n逾：超过。\n独栖（qī）：孤独一个人居住。\n清：形容路上尘。浊（zhuó）：形容水中泥。“清”、“浊”二者本是一物。\n浮：就清了。沉：就浊了。比喻夫妇（或兄弟骨肉）本是一体，如今地位（势）不同了。\n逝：往。\n君怀：指宕子的心。良：很久，早已。', poem_appreciation = '诗人自比“宕子妻”，以思妇被遗弃的不幸遭遇来比喻自己在政治上被排挤的境况，以思妇与丈夫的离异来比喻他和身为皇帝的曹丕之间的生疏“甚于路人”、“殊于胡越”。诗人有感于兄弟之间“浮沉异势，不相亲与”，进一步以“清路尘”与“浊水泥”来比喻二人境况悬殊。“愿为西南风，长逝人君怀”，暗吐出思君报国的衷肠；而“君怀良不开，贱妾当何依”，则对曹丕的绝情寡义表示愤慨，流露出无限凄惶之感。全诗处处从思妇的哀怨着笔，句句暗寓诗人的遭际，诗情与寓意浑然无间，意旨含蓄，笔致深婉，确有“情兼雅怨”的特点。\n\n　　这首诗的起句既写实景，又渲染出凄清冷寂的气氛，笼罩全诗。“明月照高楼，流光正徘徊”运用了“兴”的手法带出女主角的背景：明月高照，思妇独倚高楼，对影自怜，思念远方的夫君。月照高楼之时，正是相思最切之际，那徘徊徜徉的月光勾起思妇的缕缕哀思——曹植所创造的“明月”、“高楼”、“思妇”这一组意象，被后代诗人反复运用来表达闺怨。明月在中国诗歌传统里，起着触发怀想相思的作用，比如李白的“举头望明月，低头思故乡”。月光月夜，会撩起诗人绵绵不尽的思绪，勾起心中思念怪挂怀的人或事。\n\n　　次两句“上有愁思妇，悲叹有余哀”运用了“赋”的表达方法，承接上两句直接点出该诗的主角——愁思妇的情怀——悲叹和哀伤。当皎洁的明月照着高楼，清澄的月光如徘徊不止的流水轻轻晃动著，伫立在高楼上登高望远的思妇，在月光的沐浴下伤叹着无尽哀愁。因为思念良人而不得见，甚至音讯亦不能通。这是典型的白描手法，即“赋”的表达方法。\n\n　　第五、六句“借问叹者谁，言是客子妻”也是以“赋”的方法来表达的，但是以问答的方式来达到“赋”的表达效果的：“请问楼上唉声叹气的是谁？回答说是异地客旅者的妻子。”直截了当，干脆利落，明白如话。曹植接着采用自问自答的形式，牵引出怨妇幽幽地叙述悲苦的身世，这同时也是曹植牵动了对自己崎岖境遇的感慨。从明月撩动心事到引述内心苦闷，曹植写得流畅自然，不著痕迹，成为“建安绝唱”。\n\n　　第七、八句“君行逾十年，孤妾常独栖”承接上文，继续以“赋”的手法表达。思妇诉说她的孤独和寂寞：“夫君已远行在外超过十年了，我只好孤清地独自栖居。”透过思妇的诉说进一步描述思妇的哀叹，非常直接。\n\n　　第九、十句“君若清路尘，妾若浊水泥”运用了“比”的手法进一步表达思妇的哀怨情怀。将夫君比喻为路中的清尘，将自己比喻为污浊的水和泥，喻意两人相差太远，难以融合在一起，也比喻夫君高高在上，对己不屑一顾，自己卑微在下，不能攀附，非常悲哀。曹植于此自比“浊水泥”的弃妇，“清路尘”指的是曹丕曹睿。曹丕继位后不再顾念手足之情，疏远甚至防范著自己的亲弟。曹睿称王时，曹植多次上表上书自试，终究无法获得任用。所以曹植用了浊泥和清尘的远离相互映照，衬托出和兄长侄子形势两异的遥远距离。\n\n　　第十一、十二句“浮沉各异势，会合何时谐”承接上文，同时以“比”和“赋”的手法表达思妇的哀怨情怀。清尘是浮的，水泥是沉的，浮沉所处的位置是不同的，因而和合在一起的机会是渺茫的。浮沉是比喻，点描出不能谐和的悲哀。\n\n　　第十三、十四句“愿为西南风，长逝入君怀”是运用了“比”的手法表达思妇的心志。思妇见弃，不单不以怨报之，反而愿意牺牲自己：“可以的话，我愿意化作西南风，在人间消失而进入夫君的怀抱中！”思妇对夫君何等的忠诚和忠贞！为了得见夫君，不惜将自己比喻为西南风，化入君怀！曹植盼望着骨肉相谐和好，期盼能在曹丕曹睿身旁效力献功。所以他说但愿能化作一阵西南风，随风重投丈夫，也就是兄长侄子的怀抱。\n\n　　第十五、十六句“君怀良不开，贱妾当何依”运用了“赋”的方法表达思妇被冷待的遭遇和情怀，思妇的思念就象那缕飘逝的轻风，结尾的这缕轻风与开首的那道月光共同构成了一种幽寂清冷的境界。思妇很了解夫君的性情，超过十年了，音讯全无，“夫君的胸怀早已不向我开放了，我还有什么可依靠的呢？”哀怨之情，直透长空。这两句的表达非常直接，正是“赋”的典型手法。曹丕曹睿始终防备怀疑曹植，曹植“戮力上国，流惠下民，建永世之业，流金石之功”的抱负就不能实现。\n\n　　该诗通篇表面上描写思妇诉说被夫君遗弃的哀怨情怀，实际上暗喻自己被长兄疏远排斥的苦闷和郁抑，这是另一种意义上运用了“比”的表达方法，这是诗人更深层的自况自喻。\n\n　　“愿为西南风，长逝入君怀”是三国魏曹植《七哀诗》里的名句，这是坚决而执著的持守誓言。独守十年，没有沉沦和颓废，思妇依旧祈愿自己化作长风，随风而去，与君相依，这是思妇此生唯一的期待。子建也是如此。他在认清无常荒诞的命运之后，并没有放弃初衷，而是“长怀永慕，忧心如酲”（《应诏》）。\n\n　　曹植以弃妇自比是其后期诗歌的特色之一。除了这首，其他如《浮萍篇》、《杂诗》等诗里皆有怨妇形象的运用。曹植这首里的弃妇，就是用作象喻的。曹植具有致君为国的理想，不仅是曹植个人的志向，同时也是当时整个时代的风气反映。可是抱著成就功名期盼的臣子，如果不能获得君主的赏识任用，那便全无施展才能抱负之机，没有办法实现自我的价值。这样的君臣关系，就彷佛那个时代全心托靠男性的女子，一朝被夫君离弃，那就是没了依傍的怨妇，失去生存的价值以及生命的重心。', poem_tags = '弃妇,思念' WHERE poem_title = '七哀诗' AND poem_author = '曹植';
UPDATE edu_poem SET poem_translation = '惠施在梁国做国相，庄子去看望他。有人告诉惠施说：“庄子（到梁国）来，是想取代你做宰相。”于是惠施非常害怕，在国都搜捕三天三夜。庄子前去见他，说：“南方有一种鸟，它的名字叫鹓鶵，你知道它吗？那鹓鶵从南海起飞飞到北海去，不是梧桐树不栖息，不是竹子的果实不吃，不是甜美的泉水不喝。在此时猫头鹰拾到(一只)腐臭的老鼠，鹓鶵从它面前飞过，(猫头鹰)仰头看着，发出‘喝！’的怒斥声。现在你也想用你的梁国来吓我吗？”', poem_notes = '惠子：即惠施，战国时宋国人，哲学家，庄子好友。\n相梁：在梁国当宰相。梁：魏国的都城，战国时期魏国迁都大梁。（今河南开封）后的别称。根据史实魏国都城叫大梁，所以魏也叫梁。相：辅助君主的人，相当于后代的宰相。这里用作动词，做宰相的意思。\n或：有人。\n于是：与现代意思相同，可直接翻译为“于是”。\n恐：害怕。\n国：国都。\n往：前往。\n鹓鶵（yuānchú）：鶵，古同“雏”。鹓鶵为古代传说中像凤凰一类的鸟，习性高洁。\n止：栖息。\n练实：竹实，即竹子所结的子，因为色白如洁白的绢，故称。\n醴（lǐ）泉：甘泉，甜美的泉水。醴：甘甜。\n于是：在这时。\n鸱（chī）：人教版语文书中解释为猫头鹰。\n吓（hè）：模仿鹞鹰发怒的声音。下文的“吓”用作动词。\n夫（fú）：句首语气词，可以不译，也可以译作那 那鹓鶵。\n三：虚指，多次。\n发于南海：于，从。\n飞于北海：于，到。\n子：你，指代惠子。', poem_appreciation = '《惠子相梁》这则故事，辛辣地讥讽了醉心于功名富贵者的嘴脸，表现了庄子对功名利禄的态度。故事发展出人意料，人物形成鲜明对照，比喻巧妙贴切，收到言简义丰的效果。\n\n　　巧妙地采用了寓言的形式。庄子往见惠子，表明自己的清高，无意功名利禄，指责惠子为保住官位而偏狭猜忌的心态，但这些并没有直接道出，而是寓于一个虚构的故事中，使人感到意味隽永，具有更强的讽刺性。\n\n　　善于运用比喻。其中的“鹓鶵”“鸱”和“腐鼠”都具有明显的比喻义，且比喻自然生动形象，特别是把鸱吓鹓鶵的情景刻画地惟妙惟肖，活画出了惠子因怕丢掉相国的官职而偏狭猜忌的丑态。按：庄子和惠子本是朋友，惠子先于庄子而逝，在《庄子·徐无鬼》中表现了庄子对墓中的惠子的怀念。\n\n　　本篇表现了庄子无意于功名利禄的清高的品质。比起《逍遥游》中表现的虚无主义和追求绝对自由的人生观来，还是值得肯定的。', poem_tags = '初中文言文,讽刺,哲理,寓言' WHERE poem_title = '惠子相梁' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '六国的灭亡，不是（因为他们的）武器不锋利，仗打得不好，弊端在于用土地来贿赂秦国。拿土地贿赂秦国亏损了自己的力量，（这就）是灭亡的原因。有人问：“六国一个接一个的灭亡，难道全部是因为贿赂秦国吗？”（回答）说：“不贿赂秦国的国家因为有贿赂秦国的国家而灭亡。原因是不贿赂秦国的国家失掉了强有力的外援，不能独自保全。所以说：弊病在于贿赂秦国。”\n　　秦国除了用战争夺取土地以外，（还受到诸侯的贿赂），小的就获得邑镇，大的就获得城池。比较秦国受贿赂所得到的土地与战胜别国所得到的土地，(前者)实际多百倍。六国诸侯（贿赂秦国）所丧失的土地与战败所丧失的土地相比，实际也要多百倍。那么秦国最想要的，与六国诸侯最担心的，本来就不在于战争。想到他们的祖辈和父辈，冒着寒霜雨露，披荆斩棘，才有了很少的一点土地。子孙对那些土地却不很爱惜，全都拿来送给别人，就像扔掉小草一样不珍惜。今天割掉五座城，明天割掉十座城，这才能睡一夜安稳觉。明天起床一看四周边境，秦国的军队又来了。既然这样，那么诸侯的土地有限，强暴的秦国的欲望永远不会满足，（诸侯）送给他的越多，他侵犯得就越急迫。所以用不着战争，谁强谁弱，谁胜谁负就已经决定了。到了覆灭的地步,道理本来就是这样子的。古人说：“用土地侍奉秦国，就好像抱柴救火，柴不烧完，火就不会灭。”这话说的很正确。\n　　齐国不曾贿赂秦国，（可是）最终也随着五国灭亡了，为什么呢？（是因为齐国）跟秦国交好而不帮助其他五国。五国已经灭亡了，齐国也就没法幸免了。燕国和赵国的国君，起初有长远的谋略，能够守住他们的国土，坚持正义，不贿赂秦国。因此燕虽然是个小国，却后来才灭亡，这就是用兵抗秦的效果。等到后来燕太子丹用派遣荆轲刺杀秦王作对付秦国的计策，这才招致了（灭亡的）祸患。赵国曾经与秦国交战五次，打了两次败仗，三次胜仗。后来秦国两次攻打赵国。（赵国大将）李牧接连打退秦国的进攻。等到李牧因受诬陷而被杀死，（赵国都城）邯郸变成（秦国的一个）郡，可惜赵国用武力抗秦而没能坚持到底。而且燕赵两国正处在秦国把其他国家快要消灭干净的时候，可以说是智谋穷竭，国势孤立危急，战败了而亡国，确实是不得已的事。假使韩、魏、楚三国都爱惜他们的国土，齐国不依附秦国。（燕国的）刺客不去（刺秦王）（赵国的）良将李牧还活着，那么胜败的命运，存亡的理数，倘若与秦国相比较，也许还不容易衡量（出高低来）呢。\n　　唉！（如果六国诸侯）用贿赂秦国的土地来封给天下的谋臣，用侍奉秦国的心来礼遇天下的奇才，齐心合力地向西（对付秦国），那么，我恐怕秦国人饭也不能咽下去。真可悲啊！有这样的有利形势，却被秦国积久的威势所胁迫，天天割地，月月割地，以至于走向灭亡。治理国家的人不要被积久的威势所胁迫啊！\n　　六国和秦国都是诸侯之国，他们的势力比秦国弱，却还有可以不贿赂秦国而战胜它的优势。如果凭借偌大国家，却追随六国灭亡的前例，这就比不上六国了。', poem_notes = '1.兵：兵器\n2.善：好。\n3.弊在赂秦：弊病在于贿赂秦国。赂，贿赂。这里指向秦割地求和。\n4.或曰：有人说。这是设问。下句的“曰”是对该设问的回答。\n5.率：都，皆。\n6.盖：承接上文，表示原因，有“因为”的意思。\n7.完：保全。\n8.攻取：用攻战（的办法）而夺取。\n9.小：形容词作名词，小的地方。\n10.其实：它的实际数目。\n11.所大欲：所最想要的（东西），大，最。\n12厥先祖父：泛指他们的先人祖辈，指列国的先公先王。厥，其。先，对去世的尊长的敬称。祖父，祖辈与父辈.\n13.暴霜露：暴露在霜露之中。意思是冒着霜露。和下文的斩荆棘，已有尺寸之地，都是形容创业的艰苦。\n14.视：对待\n15.举以予人：拿它（土地）来送给别人。实际是举之以予人，省略了之，代土地。\n16.然则：既然这样，那么。\n17.厌：同“餍”，满足。\n18.奉之弥繁，侵之愈急：（诸侯）送给秦的土地越多，（秦国）侵略诸侯也越急。奉：奉送。弥、愈：都是“更加”的意思。繁：多。\n19.判：决定。\n20.至于：以至于。\n21.颠覆：灭亡。\n22.理固宜然：（按照）道理本来就应该这样。\n23.事：侍奉。“以地事秦……火不灭”：语见《史记魏世家》和《战国策魏策》。\n24.此言得之：这话对了。得之，得其理。之，指上面说的道理。\n25.终：最后。\n26.继：跟着。\n27.迁灭：灭亡。古代灭人国家，同时迁其国宝、重器，故说“迁灭”。\n28．与嬴：亲附秦国。与，亲附。嬴，秦王族的姓，此借指秦国。\n29．既：已经。\n30．免：幸免。\n31.始有远略：起初有长远的谋略。\n32．义：名词作动词，坚持正义。\n33.斯：这\n34.始：才\n35.速：招致。\n36．再：两次。\n37．连却之：使...退却（动词的使动用法）\n38．洎：及，等到。\n39.以：因为\n39．谗：小人的坏话。\n40.邯郸为郡：秦灭赵之后，把赵国改为秦国的邯郸郡。邯郸，赵国的都城。\n41.且燕、赵处秦革灭殆尽之际：燕赵两国正处在秦国把其他国家快要消灭干净的时候。革,改变，除去。殆，几乎，将要。\n42．智力：智谋和力量（国力）。\n43．向使：以前假如。\n44．胜负之数，存亡之理：胜负存亡的命运。数，天数。理，理数。皆指命运。\n45.当：同“倘”，如果。\n46.易量：容易判断。\n47．以赂秦之地封天下之谋臣：以，用。\n48．礼：礼待。名作动。\n49.食之不得下咽也：指寝食不安，内心惶恐。下：向下。名作动。咽：吞咽。\n50．势：优势。\n51.而为秦人积威之所劫：而，却。积威：积久而成的威势。劫，胁迫，劫持。\n52．日削月割，以趋于亡：日，每天，名作状。月，每月，名作状。以，而。\n53．为国者无使为积威之所劫哉：治理国家的人不要被积久的威势胁迫啊！\n54．势弱于秦。于：比。\n55．而犹有可以不赂而胜之之势。可以：可以凭借。\n56．苟以天下之大苟，如果。以，凭着。\n57.下：指在六国之后\n58.从：跟随。\n59．故事：旧事，先例。', poem_tags = '古文观止,高中文言文,议论,历史,借古讽今' WHERE poem_title = '六国论' AND poem_author = '苏洵';
UPDATE edu_poem SET poem_translation = '一群鹿儿呦呦叫，在那原野吃艾蒿。我有一批好宾客,弹琴吹笙奏乐调。一吹笙管振簧片，捧筐献礼礼周到。人们待我真友善，指示大道乐遵照。\n\n一群鹿儿呦呦叫，在那原野吃蒿草。我有一批好宾客，品德高尚又显耀。示人榜样不轻浮，君子贤人纷纷来仿效。我有美酒香而醇，宴请嘉宾嬉娱任逍遥。\n\n一群鹿儿呦呦叫，在那原野吃芩草。我有一批好宾客，弹瑟弹琴奏乐调。弹瑟弹琴奏乐调，快活尽兴同欢笑。我有美酒香而醇，宴请嘉宾心中乐陶陶。', poem_notes = '呦（yōu）呦：鹿的叫声。朱熹《诗集传》：“呦呦，声之和也。”\n苹：藾蒿。陆玑《毛诗草木鸟兽虫鱼疏》：“藾蒿，叶青色，茎似箸而轻脆，始生香，可生食。”\n簧：笙上的簧片。笙是用几根有簧片的竹管、一根吹气管装在斗子上做成的。\n承筐：指奉上礼品。毛传：“筐，篚属，所以行币帛也。”将：送，献。\n周行（háng）：大道，引申为大道理。\n蒿：又叫青蒿、香蒿，菊科植物。\n德音：美好的品德声誉。孔：很。\n视：同“示”。恌：同“佻”。\n则：法则，楷模，此作动词。\n旨：甘美。\n式：语助词。燕：同“宴”。敖：同“遨”，嬉游。\n芩（qín）：草名，蒿类植物。\n湛（dān）：深厚。《毛传》：“湛，乐之久。”', poem_appreciation = '《小雅·鹿鸣》是《诗经》的“四始”诗之一，是古人在宴会上所唱的歌。据朱熹《诗集传》的说法，此诗原是君王宴请群臣时所唱，后来逐渐推广到民间，在乡人的宴会上也可唱。朱熹这一推测该是符合事实的，直到东汉末年曹操作《短歌行》，还引用了此诗首章前四句，表示了渴求贤才的愿望，说明千余年后此诗还有一定的影响。\n\n　　诗共三章，每章八句，开头皆以鹿鸣起兴。在空旷的原野上，一群糜鹿悠闲地吃着野草，不时发出呦呦的鸣声，此起彼应，十分和谐悦耳。诗以此起兴，便营造了一个热烈而又和谐的氛围，如果是君臣之间的宴会，那种本已存在的拘谨和紧张的关系，马上就会宽松下来。故《诗集传》云：“盖君臣之分，以严为主；朝廷之礼，以敬为主。然一于严敬，则情或不通，而无以尽其忠告之益，故先王因其饮食聚会，而制为燕飨之礼，以通上下之情；而其乐歌，又以鹿鸣起兴。”也就是说君臣之间限于一定的礼数，等级森严，形成思想上的隔阂。通过宴会，可以沟通感情，使君王能够听到群臣的心里话。而以鹿鸣起兴，则一开始便奠定了和谐愉悦的基调，给与会嘉宾以强烈的感染。\n\n　　此诗自始至终洋溢着欢快的气氛，它把读者从“呦呦鹿鸣”的意境带进“鼓瑟吹笙”的音乐伴奏声中。《诗集传》云：“瑟笙，燕礼所用之乐也。”按照当时的礼仪，整个宴会上必须奏乐。《礼记·乡饮酒义》云：“工入升歌三终，主人献之。笙入三终，主人献之。间歌三终，合乐三终，工告乐备，遂出。……知其能和乐而不流也。”据陈澔注，乐工升堂，“歌《鹿鸣》、《四牡》、《皇皇者华》，每一篇而一终。三篇终，则主人酌以献工焉。”由此可知，整个宴会上是歌唱以上三首诗，而歌唱《鹿鸣》时又以笙乐相配，故诗云“鼓瑟吹笙”。乐谱虽早已失传，但从诗的语言看，此诗三章全是欢快的节奏，和悦的旋律，同曹操《短歌行》相比，曹诗开头有“人生苦短”之叹，后段有“忧从中来，不可断绝”之悲，唯有中间所引“鹿鸣”四句显得欢乐舒畅，可见《诗经》的作者对人生的领悟还没有曹操那么深刻。也许因为这是一首宴飨之乐，不容许杂以一点哀音吧。\n\n　　诗之首章写热烈欢快的音乐声中有人“承筐是将”，献上竹筐所盛的礼物。献礼的人，在乡间宴会上是主人自己，说见上文所引《礼记》；在朝廷宴会上则为宰夫，《礼记·燕义》云：“设宾主饮酒之礼也，使宰夫为献。”足可为证。酒宴上献礼馈赠的古风，即使到了今天，在大宾馆的宴会上仍可见到。然后主人又向嘉宾致辞：“人之好我，示我周行。”也就是“承蒙诸位光临，示我以大道”一类的客气话。主人若是君王的话，那这两句的意思则是表示愿意听取群臣的忠告。诗之二章，则由主人（主要是君王）进一步表示祝辞，其大意则如《诗集传》所云：“言嘉宾之德音甚明，足以示民使不偷薄，而君子所当则效。”祝酒之际要说出这样的话的原因，分明是君主要求臣下做一个清正廉明的好官，以矫正偷薄的民风。如此看来，这样的宴会不徒为乐而已，它也带有一定的政治色彩。三章大部与首章重复，唯最后几句将欢乐气氛推向高潮。末句“燕乐嘉宾之心”，则是卒章见志，将诗之主题深化。也就是说这次宴会，“非止养其体、娱其外而已”，它不是一般的吃吃喝喝，满足口腹的需要，而是为了“安乐其心”，使得参与宴会的群臣心悦诚服，自觉地为君王的统治服务。', poem_tags = '诗经,宴会' WHERE poem_title = '小雅·鹿鸣' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '现在才知道那时我错了，心中凄凉迷乱，眼泪默默落下，满眼看到的都是春风，事物却非于从前。\n后来知道这是没有办法的，勉强说后会有期，像这样别离，梨花落完了 ，月亮已经在天的西方。', poem_notes = '才道：才知道。语本晏几道《醉落魄》词：“心心口口长恨昨，分飞容易当时错。”又宋刘克庄：《忆秦娥》：“古来成败难描模，而近却悔当时错。”\n凄迷：凄凉迷乱。\n红泪，形容女子的眼泪。当初，魏文帝曹丕迎娶美女薛灵芸，薛姑娘不忍远离父母，伤心欲绝，等到登车启程以后，薛灵芸仍然止不住哭泣，眼泪流在玉唾壶里，染得那晶莹剔透的玉唾壶渐渐变成了红色。待车队到了京城，壶中已经泪凝如血。\n满眼春风百事非：句出于李贺《三月》诗“东方风来满眼春，花城柳暗愁杀人。”又宋赵彦端《减字木兰花》词：“满眼春风，不觉黄梅细雨中。”\n无计：无法。“欢期”：佳期，指二人重会相守之期。\n落尽梨花月又西：唐郑谷《下第退居二首》之一，“落尽梨花春又了，破篱残雨晚莺啼。”又宋梅尧臣《苏幕遮》词：“落尽梨花春又了，满地残阳，翠色和烟老。”容若此句撇开前人，用“月字”独创出凄迷冷艳的意境。梨花同月若梅花惹雪，别是一种肌骨。', poem_appreciation = '《采桑子》率直平白，把词人的一片深情以及被迫分离永难相见的痛苦与思念表达得淋漓尽致。\n\n　　“而今才道当时错，心绪凄迷。”有一种美，就在于语言的歧义，“心绪凄迷”是本篇抒情的重心。这里的“心绪凄迷”，正是由上面的“错”而引发出来，但而今才明白的“当时错”，究竟是当初不应相识，还是当初不该从相识而走得更近，或是当时应该牢牢把握住机会、不放你离去，作者所谓的“错”是什么词中并未交待清楚，也不需要交待清楚，这个空间是留给读者自己想像的，读者不应该侵占、剥夺，也不能够侵占、剥夺。\n\n　　“红泪偷垂，满眼春风百事非。”设想那个女子正在偷偷垂泪，这里似乎是一个错位的修辞，要说“百事非”，应该搭配“满眼秋风”才是，但春风满眼，春愁宛转，由生之美丽而感受死之凄凉，在繁花似锦的喜景里独会百事皆非的悲怀，尤为痛楚。此刻的春风和多年前的春风并没什么两样，而此刻的心情却早已步入秋天。\n\n　　“情知此后来无计，强说欢期。”“欢期”是相见、欢聚的意思，而“强说”一词让这份期待中的欢期变得难以预见，明明知道再也不会有见面的机会了，但还是强自编织着谎言，约定将来的会面。那一别真成永诀，此时此刻，欲哭无泪，欲诉无言。\n\n　　“一别如斯，落尽梨花月又西”。风动梨花、淡烟软月中，翩翩归来的，是佳人的一点幽香，化作梨花落入手心。情语写到尽处，以景语来作结：以景语的“客观风月”来昭示情语的“主观风月”，这既是词人的修辞，也是情人的无奈。正是那无限愁怀说不得，却道天凉好个秋。', poem_tags = '写景,落花,悼亡,爱情' WHERE poem_title = '采桑子·当时错' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '大鹏一日从风而起，扶摇直上九万里之高。\n如果在风歇时停下来，其力量之大犹能将沧海之水簸干。\n时人见我好发奇谈怪论，听了我的大言皆冷笑不已。\n孔圣人还说后生可畏，大丈夫可不能轻视年轻人啊！', poem_notes = '上：呈上。李邕（678—747）：字泰和，广陵江都（今江苏江都县）人，唐代书法家、文学家。\n摇：由下而上的大旋风。\n假令：假使，即使。\n簸却：激起。\n沧溟：大海。恒：常常。殊调：不同流俗的言行。\n余：我。大言：言谈自命不凡。\n宣父：即孔子，唐太宗贞观十一年（637年）诏尊孔子为宣父。见《新唐书·礼乐志》。宋本“宣父”作“宣公”。\n丈夫：古代男子的通称，此指李邕。', poem_appreciation = '大鹏是李白诗赋中常常借以自况的意象，它既是自由的象征，又是惊世骇俗的理想和志趣的象征。开元十三年（725年），青年李白出蜀漫游，在江陵遇见名道士司马承祯，司马称李白“有仙风道骨焉，可与神游八极之表”，李白当即作《大鹏遇希有鸟赋并序》（后改为《大鹏赋》），自比为庄子《逍遥游》中的大鹏鸟。李白诗中还有一首《临路歌》：“大鹏飞兮振八裔，中天摧兮力不济。余风激兮万世，游扶桑兮挂石袂。后人得之传此，仲尼亡兮谁为出涕？”据唐李华《故翰林学士李君墓志铭序》云，李白“赋《临终歌》而卒”。后人认为可能就是这首《临路歌》，“路”或为“终”之误写。可见李白终生引大鹏自喻之意。按此诗语气直率不谦，故前人有疑非李白之作者，亦有信为李白之作而辨之者。参詹锳主编《李白全集校注汇释集评》此诗题解。\n\n　　前四句中李白以大鹏自比。大鹏是《庄子·逍遥游》中的神鸟，传说这只神鸟其大“不知其几千里也 ”，“其翼若垂天之云”，翅膀拍下水就是三千里，扶摇直上，可高达九万里。大鹏鸟是庄子哲学中自由的象征，理想的图腾。李白年轻时胸怀大志，非常自负，又深受道家哲学的影响，心中充满了浪漫的幻想和宏伟的抱负。这只大鹏即使不借助风的力量，以它的翅膀一搧，也能将沧溟之水一簸而干，这里极力夸张大鹏的神力。在这前四句诗中，诗人寥寥数笔，就勾划出一个力簸沧海的大鹏形象——也是年轻诗人自己的形象。\n\n　　诗的后四句，是对李邕怠慢态度的回答：“世人”指当时的凡夫俗子，显然也包括李邕在内，因为此诗是直接给李邕的，所以措词较为婉转，表面上只是指斥“世人”。“殊调”指不同凡响的言论。李白的宏大抱负，常常不被世人所理解，被当做“大言”来耻笑。李白显然没有料到，李邕这样的名人竟与凡夫俗子一般见识，于是，就抬出圣人识拔后生的故事反唇相讥。《论语·子罕》中说：“子曰：“后生可畏。焉知来者之不如今也？”这两句意为孔老夫子尚且觉得后生可畏，你李邕难道比圣人还要高明？男子汉大丈夫千万不可轻视年轻人呀！后两句对李邕既是揄揶，又是讽刺，也是对李邕轻慢态度的回敬，态度相当桀骜，显示出少年锐气。\n\n　　李邕在开元初年是一位名闻海内的大名士，史载李邕“素负美名，……人间素有声称，后进不识，京洛阡陌聚观，以为古人。或传眉目有异，衣冠望风，寻访门巷。”对于这样一位名士，李白竟敢指名直斥与之抗礼，足见青年李白的气识和胆量。“不屈己、不干人”笑傲权贵，平交王侯，正是李太白的真正本色。', poem_tags = '赠别,讽刺' WHERE poem_title = '上李邕' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '、几番风雨。匆匆春又归去。\n　　晚春时节，百花凋零，风雨常至，难免令人伤春。词人对这一切更是敏感。他牵挂着那美丽的春花，还能经受得起几番风雨？他心绪不宁，为春的匆匆离去惋惜，却又无可奈何。\n\n惜春长恨花开早，何况落红无数。\n　　花是春天的象征。花开得早，自然落得早，春就去得早。词人对春天是这般珍惜，连花儿开早了都会感到遗憾，又怎能忍受落花无数呢。\n\n春且住。见说道、天涯芳草迷归路。\n　　花儿既然无法迟开晚放，那么就留住春天离去的脚步吧。“春天啊，听说海角天涯并没有你的归处，你就留在这里吧！”情至深处，词人仿佛一个天真任性的孩子。\n\n怨春不语。算只有殷勤，画檐蛛网，尽日惹飞絮。\n　　春天没有理会词人的挽留，她依旧悄然离去。词人只能轻轻埋怨春的无言自去，只能四处寻找一些春的痕迹，给自己一丝慰藉。\n\n　　他找了又找，最终发现，只有屋檐上的蛛网，沾满了飘飞的柳絮，还留有少许春色。\n\n　　五彩缤纷的春过后，是绿意盎然的夏。按说生性豪放的词人应该看到这一点。然而，他深深地陷在春逝的伤感中，难以自拔。这是因为触景伤情，落红无数的暗淡让情绪低落的他更加黯然伤神。\n\n长门事，准拟佳期又误。蛾眉曾有人妒。千金纵买相如赋，脉脉此情谁诉。　\n　　“蛾眉”，形容女子眉如飞蛾触须，代指美人。\n\n　　据《文选·长门赋序》，汉武帝的皇后陈阿娇先得宠幸，后来失宠被废，贬居长门宫。陈氏听说司马相如的文章天下最工，便送去百斤黄金，求得一篇《长门赋》。后来汉武帝看到此赋，有所感悟，陈皇后再度承宠。事实上，《长门赋》并非司马相如所作，史书上也没有陈皇后被废后复得宠幸的记载。\n\n　　正如《长门赋序》的作者敢于不拘泥故事真伪一样，辛弃疾此处也来了个大胆生发。他说，被冷落的陈皇后本已有了与汉武帝重聚的希望，但是由于遭到武帝身边其他女子的妒恨，致使佳期无望。这时候，纵使陈皇后千金买得相如的生花妙笔，脉脉真情又能向谁倾诉呢？\n\n　　词人似为陈皇后而伤感，其实是为自己伤感。\n\n　　南宋国势日衰，政权腐朽，收复中原的希望渺茫。辛弃疾热爱自己的祖国，却又不免对它痛惜、失望。在词的上片，春的离去，实际上喻指国家的败落。他期望春天长驻久留，但国势却如残春，风雨飘摇。他不愿面对这个现实，然而他又怎能回避得了？他的济世之志、救国理想都寄托在南宋王朝的复兴上，可是事与愿违，眼见这些都落了空，他的心中异常苦痛、矛盾。\n\n　　爱而不成，则生恨心。他痛恨权奸当道，蒙蔽君主、陷害忠良，痛恨朝廷不思恢复失地，反而排挤抗金志士。所以，他以长门陈皇后自比，哀叹自己遭受小人妒忌，无法大展宏图的悲惨命运。\n\n君莫舞。君不见、玉环飞燕皆尘土。\n　　杨玉环、赵飞燕都是古代著名的美女。一个是唐玄宗的贵妃，“三千宠爱在一身”，后来安史乱中被缢死马嵬坡下；一个是汉成帝宠极一时的皇后，结局是被废为庶人后自杀。\n\n　　词人对妒恨陈皇后的女子说，你们不要高兴得跳起舞来，须知玉环、飞燕也难免归于尘土，一切成空。实际上，他是在申饬、诅咒那些打击陷害忠良的权贵奸小：你们休要得意忘形，你们难道不知道，玉环、飞燕那样的命运，最终也会降临到你们头上吗？\n\n闲愁最苦。休去倚危楼，斜阳正在，烟柳断肠处。\n　　词人此刻正与同事一道饮酒话别。在这闲暇之时，他的愁，依然是家国之愁、命运之愁。惟其如此，才令他感到“闲愁最苦”，才说道，不要去倚靠高楼，否则会看见斜阳坠落烟柳中，令人伤心断肠。\n\n　　“梳洗罢，独倚望江楼。过尽千帆皆不是，斜晖脉脉水悠悠，肠断白苹洲”（唐温庭筠《望江南》）；“伫倚危楼风细细，望极春愁，黯黯生天际”（北宋柳永《蝶恋花》）……从这些词中，读者可以想见：靠着高楼，会看见一点点下坠的残阳、苍茫迷蒙的江水、轻烟笼罩的垂柳。这些都会令人伤悲。所以，辛弃疾说“休去倚危楼”，他害怕看到那落日残阳的光景，害怕由此想到江河日下的国家。他的哀愁，本就已经太多太多了。 ▲', poem_appreciation = '此词作于淳熙六年（1179）。作者在此借春意阑珊和美人遭妒来暗喻自己政治上的不得意。词里面的玉环、飞燕，似是用来指朝中当权的主和派。辛弃疾在淳熙己亥前之两三年内，转徙频繁，均未能久于其任。他曾在《论盗贼札子》里说：“生平刚拙自信，年来不为众人所容，恐言未脱口而祸不旋踵。”这与“蛾眉曾有人妒”语意正同。作者本来是要积极建功立业的，被调到湖北去管钱粮，已不合他的要求；再调到湖南，还是管钱粮，当然更是失望。他心里明白朝廷的这种调动就是不让恢复派抬头。一想到国家前途的暗淡，自不免要发出“烟柳断肠”的哀叹。表面看来，词人是在伤春吊古，实际上他将自己的哀时怨世、忧国之情隐藏在了春残花落、蛾眉遭妒的描写中。词里所流露的哀怨确有对朝廷表示不满的情绪。《鹤林玉露》云此词：“词意殊怨。斜阳烟柳之句，其‘未须愁日暮，天际乍轻阴’者异矣。便在汉唐时，宁不贾种豆种桃之祸哉。愚闻寿皇见此词颇不悦。”当年宋孝宗读到这首词心中非常不快，大概他是读懂了其真意。\n\n　　此词的写作手法颇似屈原《离骚》，同样是以香草美人为比兴，来抒写自己的政治情怀。风格上，一变辛词常见的豪放，偏向柔美一路，委婉含蓄，却又与一般写儿女柔情和风月闲愁的婉约词大有不同。今人夏承焘评之曰：“肝肠似火，色貌如花。”', poem_tags = '宋词三百首,婉约,惜春,爱国,壮志,苦闷' WHERE poem_title = '摸鱼儿·更能消几番风雨' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '只有击打石头，才会有火花；如果不击打，连一点儿烟也不冒出。\n人也是这样，只有通过学习，才能掌握知识；如果不学习，知识不会从天上掉下来。\n任何事情必须自己去实践，别人得到的知识不能代替自己的才能。\n青春年少时期就应趁早努力，一个人难道能够永远都是“少年”吗？', poem_notes = '乃：才。\n元：原本、本来。\n始：方才。\n道：事物的法则、规律。这里指各种知识。\n非：不是。\n自然：天然。\n运：运用。\n贤：才能。\n青春：指人的青年时期。\n岂：难道。\n长：长期。', poem_tags = '读书,励志,哲理' WHERE poem_title = '劝学' AND poem_author = '孟郊';
UPDATE edu_poem SET poem_translation = '只要是读书，就要每个字都读得很大声，不可以读错一个字，不可以少读一个字，不可以多读一个字，不可以读颠倒一个字，不可以勉强硬记，只要多读几遍，自然而然就顺口而出，即使时间久了也不会忘记。古人说过：“读书百遍，其义自见。”就是说书读得熟了，那么不依靠别人解释说明，自然就会明白它的道理了。我曾经说过：读书有三到，谓心到、眼到、口到。心思不在书本上，那么眼睛就不会仔细看，心和眼既然不专心致志，却只是随随便便地读，就一定不能记住，即使记住了也不能长久。三到之中，心到最重要 。心既然已经到了，眼和口难道会不到吗？', poem_notes = '误：错。\n倒：颠倒。\n牵强暗记：勉强默背大意。\n见：同“现”,表露出来。\n晓：知道。\n漫浪：随随便便，漫不经心。\n急：重要，要紧。\n矣：相当于\'\'了“\n岂：时常,习\n乎：吗,语气词\n余尝谓：我曾经说过。谓，说', poem_tags = '小学文言文,寓言,故事,学习,哲理' WHERE poem_title = '读书要三到' AND poem_author = '朱熹';
UPDATE edu_poem SET poem_translation = '再向北走二百里，有座山叫发鸠山，山上长了很多柘树。树林里有一种鸟，它的形状像乌鸦，头上羽毛有花纹，白色的嘴，红色的脚，名叫精卫，它的叫声像在呼唤自己的名字。这其实是炎帝的小女儿，名叫女娃。有一次，女娃去东海游玩，溺水身亡，再也没有回来，所以化为精卫鸟。经常叼着西山上的树枝和石块，用来填塞东海。浊漳河就发源于发鸠山，向东流去，注入黄河。', poem_notes = '曰：叫作 \n发鸠之山：古代传说中的山名 \n拓木：拓树，桑树的一种 \n状：形状 \n乌：乌鸦 \n文首：头上有花纹。文，同“纹”，花纹　 \n其鸣自詨：它的叫声是在呼唤自己的名字 \n是：这 \n炎帝之少女：炎帝的小女儿 \n故：所以 \n湮：填塞', poem_appreciation = '太阳神炎帝有一个小女儿，名叫女娃，是他最钟爱的女儿．有一天，女娃驾着小船，到东海去游玩，不幸海上起了风浪，象山一样的海浪把小船打翻，女娃就淹死在海里，永远不回来了。炎帝固然挂念他的女儿。但都不能用他的光和热来使她死而复生，只好独自悲伤罢了。\n\n　　女娃不甘心她的死，她的魂灵变化做了一只小鸟，名叫“精卫”。精卫长着花脑袋、白嘴壳、红脚爪，大小有点象乌鸦，住在北方的发鸠山。她恨无情的大海夺去了她年轻的生命，因此她常常飞到西山去衔一粒小石子，或是一段小树枝；展翅高飞，一直飞到东海。她在波涛汹涌的海面上回翔着，把石子或树枝投下去，要想把大海填平。\n\n　　大海奔腾着，咆哮着，露出雪亮亮的牙齿。凶恶地嘲笑着：“小鸟儿，算了罢，你这工作就算干上一百万年，也休想把大海填平呢。”\n\n　　精卫在高空答复大海：“哪怕是干上一千万年，一万万年，干到宇宙的终尽，世界的末日，我也要把你填平！”\n\n　　“你为什么衔恨我这样深呢?”\n\n　　“因为你呀——夺取了我年轻的生命，将来还会有许多年轻无辜的生命要被你无情地夺去。”\n\n　　“傻鸟儿．那么你就干吧——干吧！”大海哈哈地大笑了。\n\n　　精卫在高空悲啸着：“我要干的！我要干的！我要永无休止地干下去的!这叫人悲恨的大海啊，总有一天我会把你填成平地！”\n\n　　她飞翔着，啸叫着．离开大海，又飞回西山去；把西山上的石子和树枝衔来投进大海。她就这样往复飞翔，从不休息，直到今天地还在做着这种工作。\n\n　　原文：又北二百里，曰发鸠之山，其上多柘木，有鸟焉，其状如乌，纹首，白喙，赤足，名曰“精卫”，其鸣自詨。是炎帝之少女，名曰女娃。女娃游于东海，溺而不返，故为精卫，常衔西山之木石，以堙于东海。漳水出焉，东流注于河。', poem_tags = '小学文言文,神话,故事' WHERE poem_title = '精卫填海' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '落日里寒鸦归巢勾起我一片思愁。只有池塘柳树发出嫩绿的新芽显出温柔。如果不是眼下亲自遭遇离愁别恨的折磨，根本不会相信这世上真会有人伤心白头。\n离肠寸断，泪流难收。怀着相思之情，又一次登上了小红楼。明明知道乱山无数，遮断了远方的天空，可还是不由自主地靠在栏杆上，一直凝望而不能罢休。', poem_notes = '鹧鸪天：小令词调，双片五十五字，上片四句三平韵，下片五句三平韵。唐人郑嵎诗“春游鸡鹿塞，家在鹧鸪天”，调名取于此。又名“思佳客”“思越人”“剪朝霞”“骊歌一叠。\n晚日：夕阳。唐刘长卿《行营酬吕侍御》诗：“晚日归千骑，秋风合五兵。”\n新绿：初春草木显现的嫩绿色。唐白居易《长安早春旅怀》诗：“风吹新绿草牙拆，雨洒轻黄柳条湿。”\n教：使，令。眼底：眼中，眼睛跟前。五代齐己《寄双泉大师兄》诗：“清泉流眼底，白道倚岩棱。”\n白头：犹白发。形容年老。《战国策·韩策三》：“中国白头游敖之士，皆积智欲离 秦韩之交。”\n深知；明知。唐骆宾王《艳情代郭氏答卢照邻》诗：“情知唾井终无理，情知覆水也难收，不复下山能借问，更向卢家字莫愁。”\n阑干：栏杆。阑。同“栏”。', poem_appreciation = '“晚日寒鸦”，这是送人归来后的眼中景。“晚日”的余辉染红天际，也染红长亭古道和目之所极的一切，这是空间。夕阳愈来愈淡，夜幕即将降落，这是时间。而她送走的那位意中人，就在这空间、这时间中愈走愈远了\n\n　　“柳塘”之后缀以“新绿”，便立刻为我们唤来了春天：塘周柳丝摇金，塘中春波涨绿，已够赏心悦目了；那料到在此基础上，又加上“温柔”一词。相对于严冬而言，初春的水显得“温”，所谓“春江水暖鸭先知”。但说它“温柔”，这就不仅表现了抒情主人公的感觉，而且表现了她的感情。这感情异常微妙，耐人寻味。凭借我们的经验：那一塘春水，既倒映着天光云影和四周的垂柳，又浮游着对对鸳鸯或其他水禽。抒情主人公看到这一切，就自然感到“温柔”，从而也联想到她与意中人欢聚之时是何等的“温柔”了。\n\n　　“柳塘新绿”，春光明丽，倘能与意中人象鸳鸯那样双双戏水，永不分离，便青春永驻，不会白头。\n\n　　“若教眼底无离恨，不信人间有白头。”心绪何等低回宛转，笔致何等摇曳生姿！“无离恨”是假设，不“白头”是假设变成事实之后希望出现的结果。可如今呢？假设未能成立，“白头”已是必然，于是下片紧承“离恨”、“白头”，以“肠已断，泪难收”开头，尽情吐露，略无含蓄。当感情如洪水暴发，冲决一切堤防的时候，是不可能含蓄、因为也用不着含蓄的。\n\n　　“相思重上小红楼”一句，妙在一个“重”字。女主人公送走意中人之后，一次又一次地爬上小楼遥望。开始是望得见的，后来就只见“晚日寒鸦”，望不见人影了。由于十分相思的缘故，望不见人影，还要望，因而“重上小红楼”。晚日寒鸦一片愁，柳塘新绿却温柔。若教眼底无离恨，不信人间有白头。\n\n　　肠已断，泪难收，相思重上小红楼。情知已被山遮断，频倚栏干不自由。', poem_tags = '离恨,相思' WHERE poem_title = '鹧鸪天·代人赋' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '群峰陡峭上摩碧天，逍遥世外不用记年。\n拨开浓云寻找古老的山间古道，奇树听那涂涂的流泉。\n温暖的花丛中卧着青牛，高高的松枝上有白鹤在眠。\n与雍尊师交谈起来一直到江水已笼罩在暮色里，我只好独自走下烟云弥漫的寒山。', poem_notes = '雍尊师：姓雍的道师，名字、生平不详。尊师是对道士的尊称。\n群峭：连绵陡峭的山峰。\n”花暖“二句：都是指道行高深之意。《列仙传》：老子乘青牛车去，入大秦。《玉策记》：千岁之鹤，随时而鸣，能登于木。其未千岁者，终不集于树上也。色纯白，而脑尽成丹。杨齐贤曰：青牛，花叶上青虫也。有两角，如蜗牛，故云。琦按：“青牛”、“白鹤”，不过用道家事耳，不必别作创解。', poem_appreciation = '此诗写作时间难以确定，可能是李白青年时期的作品，作于蜀中。\n\n　　此诗首联“群峭碧摩天”，逍遥不记年从大处落笔，起势不凡。“峭”壮群峰之势，“碧”绘其色，补以“摩天”二字，壮观的景象全出。这是些雍尊师隐居所在。下句“逍遥”二字赞美雍尊师超尘拔俗的人生态度；“不记年”则为补足“逍遥”之意，远离尘嚣，连岁月的流逝都不屑去计算了。上句写景，下句写人，写景也为写人，人景浑然一体，显得崇高、挺拔、永恒。\n\n　　颔联“拨云寻古道，倚石听流泉”紧扣诗题，着意写“寻”。“拨”与“寻”二字绝妙，生动地再现了寻者攀登的举止和情态。诗人穿过雾隐云横的丹岩翠壁奋力攀登之后，斜靠在长藤古树之上，一览众山景色，倾听流泉欢歌。上句从视觉着笔，写行寻的艰难和乐趣；下句则从听觉落墨，流泉叮咚，沁心悦耳。\n\n　　颈联“花暖青牛卧，松高白鹤眠”以五彩交辉的浓笔，静中有动，动中有静地描绘了雍尊师居所优美、静谧、仙境般的环境。用青牛、白鹤来点缀隐居处，又用花和松做烘托，“卧”与“眠”清幽、安谧、静美的境界活脱而出。\n\n　　尾联“语来江色暮，独自下寒烟”以素冷的色调，泼墨挥洒出一幅清幽隽永的画面。上句“语来”二字，省去了诗人与雍尊师的高谈阔论的细节，但可以想象他们感情之融洽，谈吐之投机。开怀畅饮，不觉已是黄昏，只好分手。诗人独自从寒烟笼罩的摩天碧峰上走下来。“下”字不仅与首句呼应，还别有情趣，与“暮”“独”“寒”三字在一联中连用，使人顿生寒气扑面而至之感。', poem_tags = '赞颂,老师,典故' WHERE poem_title = '寻雍尊师隐居' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '遇见北去的驿使就去折梅花，托他带给远在陇山的友人。\n江南别没有更好的礼品相送，姑且把一枝梅花送去报春。', poem_notes = '《荆州记》：“陆凯与范晔交善，自江南寄梅花一枝，诣长安与晔，兼赠诗。”唐汝谔《古诗解》则云：“晔为江南人，陆凯代北人，当是范寄陆耳。”这里用《赠范晔》题，乃暂从旧说。范晔：字蔚宗，顺阳山阴（今河南省淅川县东）人，南朝宋史学家、散文家。\n驿使：古代递送官府文书的人。\n陇头人：即陇山人，在北方的朋友，指范晔。陇山，在今陕西陇县西北。\n“聊赠”句：赠：一作“寄”。一枝春：指梅花，人们常常把梅花作为春天的象征。', poem_appreciation = '古今吟咏岭梅诗词不下千章，最早的是晋代陆凯《赠范哗》“折梅逢驿使，寄与陇头人．江南无所有，聊赠一枝春。”《直隶南雄州志》载，南雄城南有寄梅驿，即取折梅逢驿使诗语。该驿曾经宋绍兴知州李岐重修。清道光知州戴锡纶有《寄梅驿》诗云：“一枝春可当人情，投赠南州艳此清。妙是不登供帐例，香风千古被征行。”\n\n　　陆凯是三国时人。《三国志．陆凯传》载：“陆凯，字敬风，吴郡吴人也。丞相逊族子也。黄武初为永兴诸暨长，所在有治迹，拜建武都尉。领兵虽统军众，手不释书。……赤乌中除儋耳太守，讨珠崖，斩获有功，迁为建武校尉。”又《三国志.孙权传》载：“赤乌四年秋七月，遣将军聂友、校尉陆凯以兵三万讨珠崖儋耳。”\n\n　　这首诗当是陆凯率兵南征度梅岭时所作。他在戎马倥偬中登上梅岭，正值岭梅怒放，立马于梅花丛中，回首北望，想起了陇头好友范哗，又正好碰上北去的驿使，就出现了折梅赋诗赠友人的一幕。他那“虽统军众，手不释书”的儒将风度跃然出现在读者眼前。\n\n　　《赠范哗》寥寥2 0字，简朴中道出了真挚的友情，平淡中显出了高雅的意境。“一枝春”作为梅花的象征，向人们预示着美好的春天即将来临，祝愿人们的美好祈望定能实现。\n\n　　范晔是谁?南北朝刘宋时有个编写《后汉书》的范晔，但他距三国近200年，肯定不是这个范晔，而是三国另一个范晔。有的人则认为范哗是刘宋时的范哗，而陆凯不是三国吴的陆凯，而是刘宋时的另一个陆凯。熟是熟非，有待考证。\n\n　　陆凯这首诗不过二十个字，却包含无限的诗趣和感情。当陆凯怀念范晔的时候，为了表达高洁与纯挚的感情，特地折取一枝梅花，托传递书物的信使带给范晔，所谓陇头人，因为范晔时在陕西长安，陇山在陕西陇县，所以用陇头人以代。不言而喻，陆凯折花遥赠之地是江南，江南的梅花是驰名于世的。隐居西湖的林逋有咏梅诗：“疏影横斜水清浅，暗香浮动月黄昏。”正是江南梅花神韵的写照。江南是文物之邦，物丰文萃，但陆凯认为别的礼物不足以表达他对范晔的情感，所以说江南没有什么可贵的东西堪以相赠，唯有先春而至为报春讯的梅花是最适当的，因而遥遥千里，以寄思慕之情，而梅花也象征他们之间的崇高友谊。大概人陆凯赠诗开始，“一枝春”就成为梅花及赠别的代称了。可见影响的深远。唐宋以下历代诗人都有类似的吟咏，刘克庄写道：“轻烟小雪孤行路，折滕梅花寄一枝”，是袭取了陆凯的意境；高启写道：“无限春愁在一枝”，是套用了陆凯诗以寄托感情。后来连唱曲的词牌也取了《一枝春》的曲名。《武林旧事》就曾记有一段故事：“除夕，小儿女终夕嬉戏不寐，谓之守岁，守岁之词虽多，极难其选，独杨守齐《一枝春》最为近世所称。”可见一首小诗也有传世的艺术魅力。它的艺术美在于朴素、自然而又借物寄喻，在特定的季节，特定的环境，把怀友的感情，通过一种为世公认具有高洁情操的梅花表达出来，把抽象的感情与形象的梅花结为一体了。（曾敏之）', poem_tags = '古诗三百首,梅花,友情' WHERE poem_title = '赠范晔诗' AND poem_author = '陆凯';
UPDATE edu_poem SET poem_tags = '闺怨,伤春,怀人' WHERE poem_title = '浣溪沙·小院闲窗春色深' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '桃李花得日而开，花朵缤纷，装点新春。\n东风已经复苏万物，草木皆似欣欣欲语。\n枯枝上发出了美丽的新叶，涸流中也清泉汩汩，一片生机。\n造化运转着天地，太阳乘着日车不停地飞奔。\n如果不早立功名，史籍怎能写上您的名字？\n桃李须待春天，但谁能使春日永驻不逝？\n时不我待，富贵与神仙两者皆会错肩而过。\n金石之坚尚会销蚀殆尽，风霜日月之下，没有长存不逝的东西。\n我深深地畏俱日月如梭而逝，因此才欢歌纵酒，强以为欢。\n就像是秋天寒霜下的蒲柳，倏忽之间，老之将至，身已衰矣！', poem_notes = '长歌行：乐府旧题。《乐府诗集》卷三十列于《相和歌辞·平调曲》，属乐府相和歌平调七曲之一。题解云：《乐府解题》曰：“古辞云‘青青园中葵，朝露待日晞’，言芳华不久，当努力为乐，无至老大乃伤悲也。”魏改奏文帝所赋曲“西山一何高”，言仙道茫茫不可识，如王乔、赤松，皆空言虚词，迂怪难言，当观圣道而已。若陆机“逝矣经天日，悲哉带地川”，则复言人运短促，当乘间长歌，与古文合也。《长歌行》古曲今不传，惟留歌辞近十首，李白这首为其中之一。\n待：一作“得”。\n荣华：草木茂盛、开花。《荀子·王制》：“草木荣华滋硕之时，则斧斤不入山林。”\n东风：春风。李白《春日独酌》诗之一：“东风扇淑气，水木荣春晖。”百物：犹万物。《礼记·祭法》：“黄帝正名百物，以明民共财，颛顼能脩之。”\n“枯枝”句：谓枯枝生新叶，皆可爱也。\n羲（xī）和：古代神话传说中的人物。驾御日车的神。《楚辞·离骚》：“吾令羲和弭节兮，望崦嵫而勿迫。”王逸注：“羲和，日御也。”\n竹帛（bó）：竹简和白绢，古代初无纸，用竹帛书写文字。引申指书籍、史乘。《史记·孝文本纪》：“然后祖宗之功德著于竹帛，施于万世，永永无穷，朕甚嘉之。”\n务：需要。青春：指春天。春季草木茂盛，其色青绿，故称。《楚辞·大招》：“青春受谢，白日昭只。”王逸注：“青，东方春位，其色青也。”\n贳（shì）：出借，赊欠。\n蹉（cuō）跎（tuó）：失意；虚度光阴。南朝齐谢朓《和王长史卧病》：“日与岁眇邈，归恨积蹉跎。”\n销铄（shuò）：熔化，消磨。汉枚乘《七发》：“虽有金石之坚，犹将销铄而挺解也。”\n欢：一作“饮”。\n倏（shū）忽：迅疾貌，形容出乎意外之快。《吕氏春秋·决胜》：“倏忽往来，而莫知其方。”蒲柳：即水杨，一种入秋就凋零的树木。蒲与柳都早落叶，这里用来比喻人的早衰。南朝宋刘义庆《世说新语·言语篇》：“蒲柳之姿，望秋而落，松柏之姿，经霜弥茂。”', poem_appreciation = '李白这首《长歌行》深受同题古辞的影响。长歌行古辞或写及时建功立业，不要老大伤悲；或写游仙服药，延年长寿；或写游子思乡，感伤人命短促。陆机《长歌行》恨功名薄，竹帛无宣；谢灵运《长歌行》感时光流速，壮志消磨；梁元帝《长歌行》写及时行乐；沈约《长歌行》写羁旅行后倦恋金华殿，功名未著，竹帛难宣。总之李白之前运用长歌行古题者，均触景感时，抒写悲伤之情，寄寓着他们对美好人生的追求，以及追求不得的怅惘感伤的心灵。李白由此感悟人生，联想反思自己功业无成，游仙不果，重蹈古人的覆辙，陷入痛苦之中，不抒不快。于是尽情倾吞，激昂文字，悲歌式的心灵，融汇着千古人所共有的情愫，感发着人意，体验着人生的苦乐。\n\n　　此诗前十句为第一段。开端两句，总述桃李迎春得朝阳而鲜花怒放，争芳吐艳，然而它也只是荣华当年。一年一度春芳桃李，这是自然规律，因而桃李花开是春天的象征，是美好的象征。经过幽闭冬藏的寒日笼照之后，转而接受春日温暖的朝阳抚摸，使大地万物顿感复苏，呈现了活跃的旺盛的生命力，作为万物之灵的人，精神倍增，昂扬奋进，这是物之常理与人之常情。故人们把人生美好时刻称之为青春。可是作者认知不限于此，而更深入探索桃李迎春吐艳，其条件是须春阳细腻的化育，苦心无私地用功，生存发展离不开春日阳光。由此作者更悟出君臣关系的相互依存的道理，预伏后面“功名不早著”之因。日这个描写意象在古诗中曾有象征君王之意。桃李遇春阳而开，贤相逢明君而荣，自然常律与人事常理，有其相似之点，明写桃李，暗喻君臣事理。这可能是用“得日开”的甘苦用心吧!美好意象的描写，深含着美好感情与对美好事物的追求。美虽美；但尤感不足之处，只是荣华当年，因而更值得珍惜。接着作者连用四句诗赞美春光之妙用，“东风动百物，草木尽欲言。枯枝无丑叶，涸水吐清芬。”东风送暖，遍吹大地万物，阳气萌发，万物从蛰伏中苏醒，争现新姿，构成了一个生命律动的美的境界。因而草木尽欲显露英姿，冬日的枯枝丑叶败落净尽。“无丑叶”的对应之意是“竟美叶”。已经乾涸的水泉，也喷吐着清香的水柱。这四句从开端的桃李花开一点，铺叙春回大地的全景。桃李艳美又衬托东风不停地化育万物，草木换新颜，涸泉复吐清芬，尽现出春之美，写出春之境界。总上六句诗正是诗人触景所生之美感，又以平淡自然的文字与诗句，绘成春光美的形象与意境，诗人入于境中，而又出于境外，妙笔生花，与境冥合。于平淡的描写中凝聚着深蕴美与哲理性认知，然而它绝不同于自然教科书的说理。这一段后四句则由上面春光境界的描写而转入讨论，发抒感慨，寻求造成这一美景的力量来源。“大力运天地，羲和无停鞭。功名不早著，竹帛将何宣。”作者依据中国古代哲学家见解，也认为这是自然界的神力，运转天地，故而有春、夏、秋、冬四季，因而也就生成了宇宙中万物的自然生存、发展、死亡的各自规律，形成了不同季节的不同景象。不过人们总是偏爱春日，而厌恶冬日，不过这是当时人们无法改变这一阴阳变化的规律。当然他们也从天地运行不止，时光流速，永无停止中，观察万物的生衰，包括人的生老病死，悟出了一个人生道理，人亦应如春日桃李花一样，要在青春的美好时刻，展示怀抱，建立丰功伟业。生时为人们仰慕赞美，死后美名留青史，千古流芳。可是在现实中的李白，虽有美好的理想和作人的价值观，以及奋进不止的精神，但由于得不到“日”（皇帝）的温暖抚育，年华老大，驾着六龙的日神车，驭手羲和又催赶不停，如不能在青春时早立功名，就更不能留名于竹帛的史书之中。默默无闻地离开人世，故深为痛恨。外在的无形压力与内在愤激之情的积郁，终于迸发出忧患不平的心声。从过去的借鉴，目前的现状，到未来的预测，拓展时空，言浅而意深，雅正而浑厚，发展了五言古诗的传统特点。诗写到这里诗情与意旨都该停顿，但留给人们的是为何功名不早立，结局又是如何的悬念。\n\n　　诗的后十句为第二段。头两句照应开端，深化诗意。桃李既然是专在追求青春，应青春而显美容。那么有人能赊取太阳，使其不动，青春不是永在吗？“谁”字有疑问之情，本是不能之事，设想其能，从幻想中慰勉自己，从幻境中享受快感，从而减轻了心里压力，从困境得到解脱。然而幻想是暂时的，当其转化为现实之时，也就从狂热转化为冷静，用理智滤取生活的轨迹，明确是非与得失，于是铸成“富贵与神仙，蹉跎两相失”的痛定思痛的诗句。对于自己的言行作出了新的判断，知昨日之非。追求富贵功名，神仙长生，这是统治阶级的享乐意识和人生价值观。当了官是实现人生价值的标志，自然富而且贵。于此又滋生长生不死的幻想和妄求，目的永远保持自己的权贵地位与富裕的生活条件，名与利两收。求官不得则游仙，表示超然物外，清高自恃，平等官吏，也能获得美名。可在唐代它又是作官的终南捷径，初盛唐的封建士人多通此径。李白亦不例外，拜谒官吏，寻访名山高僧仙师，获取功名富贵。于今两相失败，一事无成，虚度年华，悔恨不及，再次跌入痛苦的深渊之中。进而想到古人曾说的“人生非金石，”“寿无金石固，岂能长寿考”，于是发展成为“金石犹销铄，风霜无久质”。就算人生如金石之固，可金石在长久的风霜侵袭与磨蚀之下，也会使完整之体粉碎为沙砾，更不用说人又不是金石。春之桃李、草木、清泉等也自然难以保持它们春日美姿了。言外之意，人不能长生，其功名富贵就要及早得到，否则就有得不到危险；既或得到了也难以长存。所以古人求仕的经验，“早据要路津”，实现竹帛留名的人生价值。表面上看这两句与前两句无关，然而它是似断实连，是对游仙长生的否定。诗意的发展，感情跳荡，思潮起伏的写照，因而表现为诗句的跳跃性，留给人们以悬念，追求究竟，诱人深入，弄得水落石出。当其悔恨昨非之时，必然改弦更张，作出新的抉择，“畏落日月后，强欢歌与酒。”及时行乐，纵情歌唱，酣饮消忧。否则就要落在时间的后面，衰朽之躯，想行乐也不可能了，空空地走向死亡世界，白活了一生。一个“强欢”，透露出其内心曲隐之愁情，是不情愿地造作欢情，是无欢心地造作欢情，是借歌与酒消解胸中愁情，是一时的麻醉。这种有意识麻醉自己是心灵更痛苦的表现，这是李白艺术上超常的表现，发人人所感而尚未意识到的内心深曲。这是大家路数，而非小家捉襟见肘的手法。然而，就是这一点强作排解的自我克制的希望，也难以达到与满足，痛心地写下了结尾诗句：“秋霜不惜人，倏忽侵蒲柳。”严酷的秋霜从无仁爱之心，萧杀万物，于人也无所惜，突然间降临，侵害蒲柳之姿。蒲柳为草木之名，体柔弱而经不起风霜，经霜而枯枝败叶，苦无生机。这里是用典，《世说新语》记载，顾悦与梁简文帝同岁，而顾发早白。简文帝问顾“卿何以先白？”顾答：“蒲柳之姿，望秋而落；松柏之姿，经霜弥茂。”蒲柳之姿是顾自指，松柏之姿喻简文帝。李白用此典切合自己身份，微贱之躯，经不得风霜摧残。秋霜这里既是自然的威力，同时又是象征邪恶的政治势力的残酷打击。以不可抗御的力量打击毫无准备的柔弱微贱之躯，其结果不言自明。结句不仅含蕴丰厚，而感情也至痛。令人不平，催人泪下。真是可以称作长歌当哭之作。\n\n　　李白这篇乐府诗综合前人同题之作的长处，而自成一格，以气为主，以自然为宗，清新俊逸，奇伟特出，是大家手笔。诗以比兴诗句开其端，触景生情，但它并非泛咏桃李荣谢，人生无常，及时行乐之作，而是表现出用常得奇，抒写出超出常人的胸怀壮思，生命的价值。绝非庸庸碌碌的小人私欲，它是盛唐时代精神的高扬。它描写出一代人的精英的爱国衷肠，对美好的自然春景的赞颂，对爱美与追求美好理想的倾诉，对自己事业无成的愤懑及自我解脱不成的痛苦，敞开心扉，让人们尽情了解他的内心衷曲。一颗跳荡的心，激荡的变化，万端的感情，牵动着优美的自然画面，透视出社会的不公正。美好理想总是难以兑现，为此而忧患着，抗争着，终不免遭受秋霜的厄运。美好的人性遭受摧残，不是一个时代的现象，而是阶级社会中共有的现象。盛唐社会尤其如此，令人深思。\n\n　　李白成功地塑造这天才者遭受厄运的心象，还借助于他熔铸古诗的叙事、抒情、议论手法于一炉，运用得出神入化，挥洒自如，成为一个完整艺术表现体系，只见诗境美，而不见技法。这正是李白所追求的清真美。', poem_tags = '乐府,建功立业,理想' WHERE poem_title = '长歌行' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '新婚三天来到厨房，洗手亲自来作羹汤。\n不知婆婆什么口味，做好先让小姑品尝。', poem_notes = '三日：古代风俗，新媳妇婚后三日须下厨房做饭菜。\n羹：泛指做成浓的菜肴。\n“未谙”句：意思是还不熟悉婆婆的口味。谙：熟悉。姑食性：婆婆的口味。\n遣：让。小姑：一作“小娘”。丈夫的妹妹。也称小姑子。', poem_appreciation = '这组诗共三首，其中第三首（“三日入厨下”）最受推崇。下面是中国唐代文学学会常务理事、中国韵文学会常务理事兼诗学分会会长、安徽师范大学中国古代文学专业博士生导师余恕诚教授对此诗的赏析。\n\n　　“新媳妇难当”——在旧社会人们普遍有这种看法。但也有些新媳妇在令人作难的处境中找到了办法，应付了难局，使得事情的发展带有戏剧性，甚至富有诗趣，像王建的这首诗所写的，即属于此类。这也是唐代社会封建礼教控制相对放松，妇女们的巧思慧心多少能够得以表现出来的一种反映。\n\n　　“三日入厨下，洗手作羹汤。”古代女子嫁后的第三天，俗称“过三朝”，依照习俗要下厨房做菜。“三日”，正见其为“新嫁娘”。“洗手作羹汤”，“洗手”标志着第一次用自己的双手在婆家开始她的劳动，表现新媳妇郑重其事，力求做得洁净爽利。\n\n　　但是，婆婆喜爱什么样的饭菜，对她来说尚属未知数。粗心的媳妇也许凭自己的口味，自以为做了一手好菜，实际上公婆吃起来却为之皱眉呢。因此，细心、聪慧的媳妇，考虑就深入了一步，她想事先掌握婆婆的口味，要让第一回上桌的菜，就能使婆婆满意。\n\n　　“未谙姑食性，先遣小姑尝。”这是多么聪明、细心，甚至带有点狡黠的新嫁娘！她想出了很妙的一招——让小姑先尝尝羹汤。为什么要让小姑先尝，而不像朱庆馀《闺意献张水部》那样问她的丈夫呢？朱诗云“画眉深浅入时无”，之所以要问丈夫，因为深夜洞房里只有丈夫可问。而厨房则是小姑经常出入之所，羹汤做好之后，要想得到能够代表婆婆的人亲口尝一尝，则非小姑不可。所以，从“三日入厨”，到“洗手”，到“先遣小姑尝”，不仅和人物身份，而且和具体的环境、场所，一一紧紧相扣。语虽浅白。却颇为得体，合情合理。新娘的机灵聪敏，心计巧思，跃然纸上。“先遣小姑尝”，真是于细微处见精神。沈德潜评论说：“诗到真处，一字不可易。”\n\n　　《新嫁娘词》所具有的典型意义，固然可以使人联想到这些，但是要直接就写这些入诗，则不免带有庸俗气。而在这首诗中，因为它和新嫁娘的灵机慧心，和小姑的天真，以及婆婆反将入于新嫁娘彀中等情事联系在一起，才显得富有诗意和耐人寻味。\n\n　　像这样的诗，在如何从生活中发现和把握有诗意的题材方面，似乎能够给读者一些启示。\n\n　　读这首诗，人们对新嫁娘的聪明和心计无疑是欣赏的，诗味也正在这里。新嫁娘所循的，实际上是这样一个推理过程：一、前提：长期共同生活，会有相近的食性；二、小姑是婆婆抚养大的，食性当与婆婆一致；三、所以由小姑的食性可以推知婆婆的食性。但这样一类推理过程，并不是在任何场合下都能和诗相结合。像有人在笺注此诗时所讲的：“我们初入社会，一切情形不大熟悉，也非得先就教于老练的人不可。”（喻守真《唐诗三百首详析》）', poem_tags = '唐诗三百首,女子,新婚,生活,早教古诗100首' WHERE poem_title = '新嫁娘词' AND poem_author = '王建';
UPDATE edu_poem SET poem_translation = '不吝惜很多钱去买一把好刀，用貂皮大衣换酒也算得上豪迈，\n革命者要充分爱惜自己的生命，抛洒鲜血做出惊天动地的事业。', poem_notes = '（1）对酒：指此诗为对酒痛饮时所作。\n（2）宝刀：吴芝瑛 《记秋女侠遗事》提到，秋瑾在日本留学时曾购一宝刀。\n（3）貂裘换酒：以貂皮制成的衣裘换酒喝。多用来形容名士或富贵者的风流放诞和豪爽。\n（4）勤，常常，多。 珍重：珍惜重视。\n（5）碧涛：血的波涛。用《庄子·外物》典：“苌弘死于蜀，藏其血，三年而化为碧。”苌弘是周朝的大夫，忠于祖国，遭奸臣陷害，自杀于蜀，当时的人把他的血用石匣藏起来，三年后化为碧玉。后世多以碧血指烈士流的鲜血。 涛：在此处意即掀起革命的风暴。', poem_appreciation = '第一句以不吝惜千两黄金去购买锋利的宝刀起兴，“千金”本是珍贵的钱财器物，而诗人却毫不可惜地用来换取别人看来价值根本不足相当的东西。表现了诗人意欲投身反帝反封建的斗争，甚至不惜流血牺牲，表现出诗人的性格的豪爽。\n\n　　第二句与首句呼应，诗人愿意用名贵的貂裘去换酒喝，这些贵重的东西都毫不犹豫地舍弃，诗人以一女子而作如此语，显示出诗人仗义疏财，不计较个人得失的豪爽性格。\n\n　　诗的后两句，借用周朝的忠臣苌弘鲜血化碧的典故阐明：人的生命是非常宝贵的，蛮强的热血也不能白白的流淌，应当为了崇高的革命事业抛头颅，洒热血，只有这样这辈子算是没有白活。同时抒发诗人随时准备为国捐躯的豪迈情感。\n\n　　全诗句句铿锵有力，字字掷地有声，借对酒所感抒发革命豪情，表达了诗人决心为革命奉献一切的豪情壮志，充分表现了诗人的英雄气概。', poem_tags = '古诗三百首,爱国,壮志' WHERE poem_title = '对酒' AND poem_author = '秋瑾';
UPDATE edu_poem SET poem_translation = '（一）\n　　晏子出使到楚国。楚人因为晏子身材矮小，在大门的旁边开一个小门请晏子进去。晏子不进去，说：“出使到狗国的人从狗门进去，今天我出使到楚国来，不应该从这个狗门进去。”迎接宾客的人带晏子改从大门进去。（晏子）拜见楚王。楚王说：“齐国没有人可派吗？竟派您做使臣。”晏子回答说：“齐国的都城临淄有七千五百户人家，人们一起张开袖子，就能遮天；挥洒汗水，就是下雨；街上行人肩膀靠着肩膀，脚尖碰脚后跟，怎么能说齐国没有人呢？”楚王说：“既然这样，那么为什么会打发你来呢？”晏子回答说：“齐国派遣使臣，各有不同的规矩，那些有德有才的人被派遣出使到有德有才的君主所在的国家，没有德没有才的人被派遣出使到没有德没有才的国王所在的国家。我晏婴是最不贤，没有德才的人，所以只好出使到楚国来了。”\n（二）\n　　晏子将要出使楚国。楚王听到这个消息，对身边的大臣说：“晏婴是齐国的一个能言善辩的人，现在 他正要来，我想要羞辱他，用什么办法呢？”侍臣回答说：“在他来的时候，大王请允许我们绑着一个人从大王面前走过。大王（就）问：‘（他）是做什么的？’（我则） 回答说：‘（他）是齐国人。’大王（接着再）问：‘（他）犯了什 么罪？’（我就）回答：‘（他）犯了偷窃罪。’“\n（三）\n　　晏子来到了楚国，楚王请晏子喝酒，喝酒喝得正高兴的时候，两名小官员绑着一个人到楚王面前来。楚王问道：“绑着的人是做什么的人？’（公差）回答 说：“（他）是齐国人，犯了偷窃罪。”楚王看着晏子问道：“齐国人本来就善于偷东西的吗？”晏子离开座位回答道：“我听说（这样一件事）：橘树生长在淮河以南的地方就是橘树，生长在淮河以北的地方就是枳树，只是叶子相像罢了，他们的果实味道却不同。这是什么原因呢？（是因为）水土地方不相同啊。老百姓生长在齐国不偷东西，到了楚国就偷东西，莫非楚国的水土使百姓善于偷东西吗？”楚王笑着说：“圣人不是能同他开玩笑的，我反而自讨没趣了。', poem_notes = '（一）\n使：出使，被派遣前往别国。后面的两个使字，一个作名词即使者，一个作动词即委派。\n以：因为。\n短：长短，这里是人的身材矮小的意思。\n袂：衣袖\n命：命令，这里是委任、派遣的意思。\n主：主张，这里是规矩、章程的意思。后面的主字，是指主人、国君。\n不肖：不贤，这里指没有德才的人。\n宜：应该\n（二）\n将：将要\n使：出使\n闻：听说\n之： 之 这个消息，代“晏子将使楚”这件事。\n左右：身边的人\n谓……曰：对……说\n习辞者：善于辞令（很会说话）的人。 习，熟练、善于；辞，辞令；者：......的人。\n方：将要\n吾：我\n欲：想\n辱：侮辱\n之：代词，代晏子\n何以也：用什么办法呢？何以，即以何。\n对：回答\n为：这里相当于“于”。\n缚：捆绑\n而:表顺承\n何：什么\n坐：犯罪\n（三）\n赐：赏赐，给予。\n酒酣：酒喝得正畅快的时候。酣，喝得正畅快的时候。\n诣：到........去（指到尊长那里去）。\n曷：同“何”，什么。\n为：相当于“于”，当。\n固：本来。\n善：擅长\n避席：离开座位，表示郑重和严肃的意思古代把席子铺在地上坐，所以座位叫“席”。避，离开。席，座具\n闻：听说\n之：代下面晏子说的“橘生淮南则为橘，生于淮北则为枳”。\n生：生长\n则：就是。\n则为：就变为。为：变为。\n枳：一种灌木类植物，果实小而苦。也叫【枸橘】，果实酸苦。\n徒：只是，仅仅。\n其实：它们的果实。\n味：味道\n不同：不一样\n所以然者何：这样的原因是什么呢？然，这样。所以：……原因\n对曰：回答道\n得无：莫非。\n耶：语气助词，“吗”？\n圣人：才德极高的人\n熙：同“嬉”，开玩笑。\n反取病焉：反而自讨没趣了。病，辱。', poem_appreciation = '景公意识到单凭齐国的力量是无法与强晋抗衡的，于是他将目光放到了南方的楚国，决意与楚修好，共抗晋国。在这种情况下，晏子作为使者访问了楚国。 此时楚国由楚灵王执政，他目空天下，狂妄自傲，因此打算羞辱一下齐国的使节，于是便有了“晏子使楚”这个故事。\n\n　　这则故事通过晏子出使楚国，挫败楚王诬蔑齐人入楚为盗阴谋的故事，表现了晏子机智善辩的才能和政治家.外交家的风度。说明了侮辱别人的人到头来必然受辱于人。\n\n　　外交无小事，尤其在牵涉到国格的时候，更是丝毫不可侵犯。晏子以“针尖对麦芒“的方式，维持了国格，也维护了个人尊严。晏婴是聪明机智，能言善辩，勇敢大胆、不畏强权的人。\n\n　　晏子能赢得这场外交的胜利的原因：不仅是因为晏子的话不卑不亢，有礼有节，用语委婉，头脑清晰，还是因为晏子的背后有一个强大的国家支撑着他。', poem_tags = '小学文言文,历史,故事,外交,哲理' WHERE poem_title = '晏子使楚' AND poem_author = '刘向';
UPDATE edu_poem SET poem_translation = '轻幽的芳香朗绕在弯曲的池岸，圆实的花叶覆盖着美丽的水池。\n常常担心萧瑟的秋风来得太早，使你来不及饱赏荷花就调落了。', poem_notes = '浮香：荷花的香气。曲岸：曲折的堤岸。\n圆影：指圆圆的荷叶。华池：美丽的池子。\n飘零：坠落，飘落。', poem_appreciation = '“浮香绕曲岸”，未见其形，先闻其香。曲折的池岸泛着阵阵清香，说明荷花盛开，正值夏季。“圆影覆华池”，写月光笼罩着荷池。月影是圆的，花与影，影影绰绰，莫能分解。写荷的诗作不在少数。而这首诗采取侧面写法，以香夺人，不着意描绘其优美的形态和动人的纯洁，却传出了夜荷的神韵。“常恐秋风早，飘零君不知”，是沿用屈原《离骚》“惟草木之零落兮，恐美人之迟暮”的句意，但又有所变化，含蓄地抒发了自己怀才不遇、早年零落的感慨。\n\n　　卢照邻在去世前不久写的《释疾文》中说道：“春秋冬夏兮四序，寒暑荣悴兮万端。春也万物熙熙焉感其生而悼死，夏也百草榛榛焉见其盛而知其阑，秋也严霜降兮殷忧者为之不乐，冬也阴气积兮愁颜者为之解欢。圣人知性情之纷纠。”这不免也有诗人自己的性格原因。由于他被病痛所折磨，对事物变化的反映特别敏感。如《释疾文》中所说：“神翳翳兮似灰，命绵绵兮若缕。一伸一屈兮，比艰难若尺蠼，九生九死兮。同变化乎盘古。万物繁茂兮此时，余独何为兮肠邅回而屡腐？”“草木扶疏兮如此，余独兰騨兮不自胜。”万物越是繁茂越是生机勃勃，他就越发感觉到自己的形象枯槁。同时他对繁荣的万物是“感其生而悼死”，“见其盛而知其阑”也有对自己和他人盛时的回忆与感慨。他的这种思想突出表现在他晚期的诗歌里。\n\n　　《曲池荷》的前两句写的是花好月圆，而后两句突然转写花之自悼。这花之自悼实为人之自悼。咏物诗，“因物以见我”，乃见其佳处。除余山《竹林问答》中说：“咏物诗寓兴为上，传神次之。寓兴者，取照在流连感慨之中，《三百篇》之比兴也。传神者，相赏在牝牡骊黄之外，《三百篇》之赋也。若模形范质，藻绘丹青，直死物耳，斯为下矣。”如此看来，可见卢照邻咏物诗之造诣。\n\n　　这首诗托物言志 ，为中国咏物诗之正宗手法，自不待言。其略可称道者大致有两点：一是咏花诗最易落入精雕细刻、镂金错彩的细微描写套路，这首诗写曲池荷，虽略带六朝余韵，然能于大处落墨，气象较为阔大。二是切物抒情，较为真切自然，婉转写来，并无造作，笔未离题而深沉之意尽蕴其中。', poem_tags = '咏物,荷花,抒情' WHERE poem_title = '曲池荷' AND poem_author = '卢照邻';
UPDATE edu_poem SET poem_translation = '秋浦水像秋一样的长，景色萧条令我心愁。\n客愁像秋浦水一样不可量度，我乐行至大楼山以散心忧。站\n在山顶西望伏安，直见长江之水正滚滚东流。\n我问江水：你还记得我李白吗？\n请你将我一掬泪水，遥寄给扬州的朋友去吧！\n\n夜猿在秋浦水上哀鸣，连附近的小黄山也愁白了头。\n青溪虽非是陇水。但也发出像陇水一样的悲胭之声。\n我想离开这里，但却因故而去不得；本来打算暂游此地，但却滞留此地而成了久游。\n何年何月才能回家乡啊，想至此不觉在孤舟上潜然泪流。\n\n秋浦产一种霹驼鸟，其羽毛之美，为人间天上所少有。\n以美丽著称的山鸡，见了它也羞得不敢走近水边映照自己的华美的羽毛。\n\n入了秋浦之境，一个早晨就愁白了我的双鬓。\n那凄切的猿声，叫得将我满头的白发郡成了纷乱的素丝。\n\n秋涌河畔的树丛中多产白猿，其跳跃飞腾如一团白雪。\n它们在树枝上牵引着儿女，在玩水中厉月的游戏。\n\n愁作秋浦之客，强看秋浦之花。\n秋浦的山川就如剡县一样优美，而其风光却像长沙一带的潇湘之景。\n\n我像晋朝的山简一样大醉骑马而归；我像春秋时的宁戚一样倚牛角而歌。\n空吟着《牛歌》而无人知遇，便只有像苏秦那样泪落黑罗裘了。\n\n在秋浦的干重山岭中，唯有水车岭的风景最为奇特\n。天空好像要随着大石一道倾倒下来，山石上的松萝兔丝在顺水飘拂。\n\n巨石江祖耸立在清溪河畔，就像是直扫青天的一幅天然画屏。\n上面古人的题诗千年犹在，其在绿字之上长满了美丽的苔藓。\n\n秋浦河岸的两旁，长着千千万万棵石楠树和女贞林。\n各个山头上都落满了白鬓，各个山涧里都有白猿在哀吟。\n劝君千万莫要去游秋浦，那悲哀的猿声会搅碎你这位他乡游子的客心。\n\n逻人石之高踱，上只有飞鸟才能飞过。江祖石上有渔人筑起了捕鱼的小堤坝。\n急流使得客舟飞快地行驶，山花挨着人面，散着阵阵香气。\n\n水如一匹静静的白练，此地之水即与天平。\n何不乘此舟直升云天去一览明月，一边看赏两岸的鲜花，一边在舱中饮酒呢？\n\n透明的绿水中映着一轮素净的明月，一行白鹭在日光下飞行。\n种田郎荷锄听采菱女唱歌，并一道唱和着山歌踏月而归。\n\n炉火隔彻天地，柴烟中红星乱闪。\n炼铜工人在明月之夜，一边唱歌一边劳动，他们的歌声响彻了寒峭的山谷。\n\n白发长达三千丈，是因为愁才长得这样长。\n不知在明镜之中，是何处的秋霜落在了我的头上？\n\n秋浦的田舍老翁，为捕鱼而睡在水上的船中。\n他的妻子在竹林深处张结鸟网，捕捉林中的白鹇。\n\n桃波离这里只有一步地之遥，那里的人说话这里都听得清清楚楚。\n我在这里暗与山僧告别，遥向白云作揖而去。', poem_notes = '秋浦：唐时属池州郡。故址在今安徽省贵池县西。\n山公：指山简。\n宁戚：春秋时卫国人。\n白石烂：宁戚《放牛歌》中有“南山矸，白石烂，生不逢尧与舜禅”之句。\n黑貂裘：《战国策·秦策》载，苏秦“说秦王，书十上而说不行，黑貂之裘敝”。\n水车岭：《贵池志》载，贵池西南七十余里有水车岭。\n寄生：一种植物，其根部不扎在土里而依附在松树、杨树等枝杈上，靠吸取这些树的养分而存活。\n江祖一片石：《一统志》载，江祖山，在贵池西南二十五里处，一石突出水际，高数丈，名曰江祖石。\n逻人：今称逻人矶，乃江边一巨石。人：一作“叉”。\n鱼梁：地名，在逻人矶附近。\n舟：一作“行”\n平天：湖名，旧址在贵池西南的齐山脚下。\n赧（nǎn）：原指因害羞而脸红。这里是指炉火映红人脸。\n个：如此，这般。\n秋霜：形容头发白如秋霜。\n白鹇（xián）：大型鸟类，也叫“白雉“。\n罝（jū）：捕捉兔子的网，泛指捕鸟兽的网。\n波：一作“陂”。', poem_appreciation = '第一首诗是这组诗中最长的一首。开头说“秋浦长似秋”：秋浦老是像秋天的样子。这是因地名而产生的诙谐，也是为引出下句“萧条使人愁”而设。秋——萧条——愁，顺理成章，并且十分和谐，读之顿生冷落寂寥之感。三四句承上写愁：“客愁不可度，行上东大楼。”“正西望长安，下见江水流。”一个“望”字，凝聚着深沉的忧愤。“望长安”正是诗眼所在。后面四句是对江水说的话。“遥传一掬泪，为我达扬州。”扬州是北上长安的必经之处，诗人要把忧国之泪寄往扬州，实为寄往长安。泪虽一掬，却极有分量。\n\n　　第二首诗与前一首一样，也是抒发客愁和对长安的思念，思归益切，愁绪愈来浓。“秋浦猿夜愁，黄山堪白头。清溪非陇水，翻作断肠流。”前四句写别愁，比较婉曲；“欲去不得去，薄游成久游。何年是归日，雨泪下孤舟。”后四句进一步言归思，直抒胸臆，一气呵成。\n\n　　第三首诗是一首具有寓意的咏物诗。此诗正面赞美秋浦的锦驼鸟，而以山鸡作为陪衬，但对后者并无贬意。从诗意看，诗人对山鸡所倾注的同情似乎还更多一些。\n\n　　第四首诗是李白的自画像。全诗描绘的诗人形象是满腹忧郁，形容枯槁，白发苍苍的孤苦老人。盛年不再的李白，是怀着失意的心情来到秋浦的，虽然是刚过“知天命”的年纪，可是好像一下子白发就全白了。在此诗的开头，他说自己是“两鬓入秋浦，一朝飒已衰”。听起来似乎觉得原来还李白一直是两鬓青丝，但到了秋浦之后，没有想到竟然会在一天早上起来之后，发现两鬓已经白发苍苍了！“一朝”极言头发白得之快，简直出乎意料之外，言下之意，还真有点当年伍子胥过不去昭关，一夜之间，就把头发愁白了的味道，但是伍子胥是心急火燎，李白却并不着急赶到哪里去，而且，也不像伍子胥那样过不了昭关就有性命之忧，但是又为什么白了头发呢？李白在惊异之余，给自己找了一个看上去说得过去的原因：“猿声催白发，长短尽成丝。”中国古代的文人一听到猿声，马上就会愁肠百结的，这其中的例外恐怕还只有李白一人，不过那也是他晚年在长流夜郎的途中，在三峡中得到大赦，乘舟东归的时候，曾经欢快地写到“两岸猿声啼不住，轻舟已过万重山”。可是在眼下，他可没有这么好的心情，猿声一“催”，他满头的青丝，不管是长是短，统统白了，这个“催”字可谓是用得惊心动魄，本来头发就在一夜之间白了，那里还禁得住猿声的催促！这首诗由于用了“一朝”和“催”这两个词来着重强调自己头发白得异乎寻常地快，不由得让人想到他在《将进酒》中的名句：“君不见高堂明镜悲白发，朝如青丝暮成雪！”\n\n　　这首诗的表层意义是诗人对进入暮年的喟叹，深层意义是抒发一种匡时济世之大志而又无门可报，欲罢而又不能的矛盾情怀。\n\n　　第五首诗前两句“秋浦多白猿，超腾若飞雪”说明了地点和描写的对象，并塑造出白猿欢乐嬉戏的群像；后两句“牵引条上儿，饮弄水中月”，则是对白猿母子戏月的特写，把白猿的动态写得活灵活现。\n\n　　第六首诗开篇以“愁”字领起，展现出诗人面对残酷现实和即将爆发的战乱一筹莫展的苦闷心情和深广忧愤。”愁作秋浦客，强看秋浦花“，连观赏秋色也要强打精神，与杜甫”感时花溅泪，恨别鸟惊心“的感受相似，可见情绪是比较低落的。\n\n　　第七首诗可以说是这十七首诗的纲领，它真挚深切地抒发了诗人畅游秋浦时的心境。诗中以山简、宁戚、苏秦自况，抒发了自己抱负、境遇和不平。从”白石烂“和”黑貂裘“这两个典故上，读者不难明白，在长安时失意于最高统治者其实一直是李白心中抹不去的隐痛。”白石烂“是宁戚在不得志时，抓住齐桓公出行的机会，牵牛叩角而歌时唱的歌词，”南山灿，白石烂，……生不逢尧与舜禅，长夜漫漫何时旦！“从而引起了齐桓公的注意而最终得到了重用；”黑貂裘“则是说的战国时期最成功的策士苏秦在一开好游说秦惠王失败后，穷困潦倒的处境，”说秦王，书十上而说不行，黑貂之裘敝，黄金百斤尽。“（《战国策·苏秦始以连横说秦》）李白觉得自己的处境就好比那失意东归的苏秦，而再也不会像宁戚那样得到君王的赏识了。\n\n　　第八首和第九首，诗人描绘了秋浦的奇特景观：水车岭和江祖石。在艺术处理上，两首也很相似。第八首除一句”天倾欲堕石“略带夸张外，其余都是如实描绘；第九首也是除”青天扫画屏“一句用比外，纯用白描手法，不以词语惊人而以意境取胜。\n\n　　第十首诗，李白以轻快的笔调描写山乡的自然风光：嘉木成林，满山葱翠，白鹭横飞，白猿长鸣。但末二句笔锋陡转，劝诫人们不可去观赏这里的山光水色，因为那凄厉的猿声使人愁肠寸断。\n\n　　第十一首诗，诗人选择了两块不寻常的岩石，描写它们雄奇峻峭的姿态，绘制了一幅十分壮观的画面，倾诉了诗人对秋浦山水的爱慕之情。\n\n　　第十二首诗，写的是平天湖的夜景和诗人观赏夜景时的感受。前两句写景，后两句抒情。想象丰富，韵味无穷。\n\n　　第十三首诗，写江南水乡之景和民间采菱男女之情，也是先写景，后写情，而景和情又是相互关联、渗透、交融的，充满了乡土气息和生活气息，语近情逸，令人神远。\n\n　　第十四首诗，是一首正面描写和歌颂冶炼工人的诗歌，在中国浩如烟海的古典诗歌中较为罕见，因而极为可贵。“炉火照天地，红星乱紫烟”，诗一开头，便呈现出一幅色调明亮、气氛热烈的冶炼场景：炉火熊熊燃烧，红星四溅，紫烟蒸腾，广袤的天地被红彤彤的炉火照得通明。诗人用了“照”、“乱”两个看似平常的字眼，但一经炼入诗句，便使冶炼的场面卓然生辉。透过这生动景象，不难感受到诗人那种新奇、兴奋、惊叹之情。接着两句“赧郎明月夜，歌曲动寒川”，转入对冶炼工人形象的描绘。诗人以粗犷的线条，略加勾勒，冶炼工人雄伟健壮的形象便跃然纸上。“赧郎”二字用词新颖，颇耐寻味。从“赧郎”二字，可以联想到他们健美强壮的体魄和勤劳、朴实、热情、豪爽、乐观的性格。结句“歌曲动寒川”，关合了上句对人物形象的塑造。冶炼工人一边劳动，一边歌唱，那嘹亮的歌声使寒冷的河水都荡漾起来了。他们唱的什么歌，诗人未加明点，读者可以作出各式各样的补充和联想。歌声把寒川激荡了，当然不会，这只是诗人的独特感受，是夸张之笔，却极为传神。如果说，“赧郎”句只是描绘了明月、炉火交映下冶炼工人的面部肖像，那么，这一句则揭示出他们的内心世界，他们丰富的情感和优美的情操，字里行间饱含着诗人的赞美歌颂之情。\n\n　　这是一幅瑰玮壮观的秋夜冶炼图。在诗人神奇的画笔下，光、热、声、色交织辉映，明与暗、冷与热、动与静烘托映衬，鲜明、生动地表现了火热的劳动场景，酣畅淋漓地塑造了古代冶炼工人的形象，确是古代诗歌宝库中放射异彩的艺术珍品。\n\n　　第十五首诗，是组诗中流传最广的一首。“白发三千丈，缘愁似个长？”劈空而来，似大潮奔涌，似火山爆发，骇人心目。单看“白发三千丈”一句，真叫人无法理解：白发怎么能有“三千丈”呢？读到下句“缘愁似个长”，豁然明白，原来“三千丈”的白发是因愁而生，因愁而长。愁生白发，人所共晓，而长达三千丈，该有多少深重的愁思。十个字的千钧重量落在一个“愁”字上。以此写愁，匪夷所思。奇想出奇句，不能不使人惊叹诗人的气魄和笔力。古典诗歌里写愁的取譬很多。宋人罗大经《鹤林玉露》说：“诗家有以山喻愁者，杜少陵云：‘忧端如山来（按：当作“齐终南”），澒洞不可掇’；有以水喻愁者，李颀云：‘请量东海水，看取浅深愁’。”李白独辟蹊径，以“白发三千丈”之长喻愁之深之重。人们不但不会因“三千丈”的无理而见怪诗人，相反会由衷赞赏这出乎常情而又入于人心的奇句，而且感到诗人的长叹疾呼实堪同情。\n\n　　人看到自己头上生了白发以及白发的长短，是因为照镜而知。首二句暗藏照镜，三四句就明白写出：“不知明镜里，何处得秋霜！”秋霜色白，以代指白发，似重复又非重复，它并具忧伤憔悴的感情色彩，不是白发的“白”字所能兼带。上句的“不知”，不是真不知，不是因“不知”而发出“何处”之问。这两句不是问语，而是愤激语，痛切语。诗眼就在下句的一个“得”字上。如此浓愁，从何而“得”？“得”字直贯到诗人半生中所受到的排挤压抑；所志不遂，因此而愁生白发，鬓染秋霜，亲历亲感，何由不知！李白有“奋其志能，愿为辅弼”的雄心，有使“寰区大定，海县清一”的理想（均见《代寿山答孟少府移文书》），尽管屡遭挫折，未能实现，但他的志向绐终不泯。写这首诗时，他已经五十多岁了，壮志未酬，人已衰老，不能不倍加痛苦。所以揽镜自照，触目惊心，发生“白发三千丈”的孤吟，使天下后世识其悲愤，并以此奇想奇句流传千古，可谓善作不平鸣者了。\n\n　　第十六首诗，李白用一种极为欣赏的眼光，再现了秋浦人家的生活情调：渔家在夜以继日地打鱼，而他的妻子也不肯闲着，在竹林深处，张网捕鸟。一家人都在为着生活而忙碌，但是心态却是非常平和的，这首被人赞为颇有王维《辋川诗》格调的诗作，显然是在一种轻松自在的心境下创作出来的。正是这种不断地自我更新，不断地接受新事物的健康心理，才使得李白不论身处何地，都能写出脍炙人口的华彩辞章来的重要主观因素。\n\n　　第十七首诗，也是最后一首，以黯然离别秋浦作结，传达了一种伤感的情调。', poem_tags = '游历,山水,抒情,组诗' WHERE poem_title = '秋浦歌十七首' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '新丰美酒一斗价值十千钱，出没五陵的游侠多是少年。\n相逢时意气投合为君痛饮，骏马就拴在酒楼下垂柳边。\n\n才从军便作汉朝的羽林郎，一开始就随将军鏖战渔阳。\n谁知道不能去边关的痛苦，纵然战死还留下侠骨芬芳。\n\n一个人就能拉开两张雕弓，敌骑千重全都不放在眼中。\n偏坐金鞍上从容调好羽箭，不停地射去敌酋无法逃生。\n\n朝廷君臣庆功大宴方告终，高高坐在云台上谈论战功。\n天子亲临殿栏赐予列侯印，将军佩着印绶走出明光宫。', poem_notes = '新丰：在今陕西省临潼县东北，盛产美酒。斗十千：指美酒名贵，价值万贯。\n咸阳：本指战国时秦国的都城咸阳，当时著名的勇士盖勒、荆轲、秦舞阳都到过咸阳，这里用来代指唐朝都城长安。\n羽林郎：汉代禁卫军官名，无定员，掌宿卫侍从，常以六郡世家大族子弟充任。后来一直沿用到隋唐时期。\n骠骑：指霍去病，曾任骠骑将军。渔阳：古幽州，今河北蓟县一带，汉时与匈奴经常接战的地方。\n苦：一作“死”。\n擘：张，分开。一作“臂”。雕弧：饰有雕画的良弓。\n重：一作“群”。\n白羽：指箭，尾部饰有白色羽翎。\n五单于：原指汉宣帝时匈奴内乱争立的五个首领。汉宣帝时，匈奴内乱，自相残杀，诸王自立分而为五。这里比喻骚扰边境的少数民族诸王。\n欢宴：指庆功大宴。\n云台：东汉洛阳宫中的座台，明帝时，曾将邓禹等二十八个开国功臣的像画在台上，史称“云台二十八将”。\n轩：殿前滥槛。\n明光宫：汉宫名，公元前101年（汉武帝太初四年）秋建。', poem_appreciation = '这组诗的第一首，写侠少的欢聚痛饮。诗开头便以“美酒”领起，因为豪饮酣醉自来被认为是英雄本色，所谓“三杯吐然诺，五岳倒为轻。眼花耳热后，意气素霓生。”（李白《少年行》）饮酒在当时因能激发意气而被视作胜事。“斗十千”语出曹植《名都篇》：“归来宴平乐，美酒斗十千”，按李白也有《将进酒》诗云：“昔时陈王宴平乐，斗酒十千恣欢谑”，此诗意近李诗，不仅极言酒之珍美，而且还借前人的用语写出慷慨好客、纵情欢乐的盛况。盖游侠之饮原非独酌遣闷，其倜傥意气正在大会宾客之际才得以充分的表现。第二句言“咸阳游侠”，乃以京都侠少为其代表。游侠人物大多出身于都市的闾里市井之中，故司马迁在《史记·游侠列传》里径直称之为“闾里之侠”，咸阳为秦的国都，则京邑为游侠的渊薮也不言自明，这里不过是举其佼佼者以概全体。诗的前两句以“新丰美酒”烘染在前，“咸阳游侠”出场在后，而“多少年”则为全篇之纲。诗的后二句更进一层，写出侠少重友情厚交谊的作风。即便是邂逅相逢的陌路人，杯酒之间便能成为意气相倾的知己，所谓“论交从优孟，买醉入新丰”（李白《结客少年场行》）、“一生大笑能几回，斗酒相逢须醉倒”（岑参《凉州馆中与诸判官夜集》），正表现了他们同声相应的热情。因此，在他们开怀畅饮的豪爽风度中，还渗透着为朋友倾情倒意，肝胆相照的人情美。酒如一面镜子，映照出他们率真坦荡的人生态度。诗为人物写照，最后却宕开去以景语收束。诗人撇开楼里的场面，转而从楼外的景象落笔，其实写外景还是为内景服务的。末句中的“高楼”不仅和首句呼应，暗示了人物的豪纵气派，而且以其卓然挺立的雄姿一扫鄙陋猥琐之态；“系马垂柳”则以骏马和杨柳的意象，衬托出少年游侠富有青春气息的俊爽风致。有此一笔，使情景历历如绘，遂在表现人物豪宕气概的同时，又显得蕴藉有致。全诗用笔的跳荡灵动，也是和少年奔放不羁的性格神采相吻合的。\n\n　　第二首，写游侠的出征边塞。这首诗里所说的“仕汉”“骠骑”，以及下面两首诗里出现的“五单于”“汉家君臣”等，都是借汉事喻唐，这在唐诗中几乎是习闻熟见的惯例。这里说少年委身事君，入仕之初便担任了羽林郎的职务。由于羽林郎宿仗卫内、亲近帷幄，地位十分重要，故非一般等闲之辈可以入选。《后汉书·地理志》云：“汉兴，六郡良家子选给羽林。”由此即可见一斑。骠骑指武帝时的名将霍去病，曾多次统率大军反击匈奴侵扰，战功显赫。少年报国心切，一心想效功当世，一旦国家有事，便毫不犹豫地随军出征。边关是遥远荒寒的，沙场的搏杀更是出生入死，而主人公“明知山有虎，偏向虎山行”，这种为国献身的精神，和曹植的《白马篇》里“捐躯赴国难，视死忽如归”的少年英雄是一脉相承的。所不同的是，曹诗通篇是用第三人称的视角来加以客观的描述和赞颂，这里却借少年自己的口吻直抒胸臆：第三句以自诘的口气反挑，使文势陡起波澜，末句则以斩截之语收束，而“孰”“不”“纵”“犹”等虚词的连用，又在接二连三的转折中不断加强语气，活脱地传达出少年从容朱毅的神情和义无返顾的决心。这种借顿挫的用笔展示人物内心世界的手法，不仅很有力度，而且进一步深化了游侠“意气”的内涵。\n\n　　第三首，写少年的勇武杀敌。诗人将主人公置于孤危险恶的战争情势之中。“虏骑千重”指敌人大军压境，形成包围之势；“众敌酋倾巢出动，来势汹汹，企图以优势兵力取胜。而少年以“一身”对“千重”之敌，竟能左右驰突于敌阵之中，如入无人之境，且能擒贼先擒王，将凶蛮剽悍的敌酋“纷纷射杀”，其过人的胆略和武艺已分明可见。这里把少年写成孤胆英雄，意在突出他的勇冠三军、战功卓著。诗的一、三两句，以特写镜头为少年英武矫健的身姿写照：“擘两雕弧”言其多力善射，能左右开弓；“偏坐金鞍”言其鞍马功夫娴熟，能在疾驰的马背上自如地变换各种姿势；“调白羽”则是善于在运动中瞄准目标，箭无虚发。二、四两句，从对方着笔来反衬少年的艺高胆大。敌我双方的力量愈是悬殊，也就愈能表现主人公无所畏惧的英雄气概，而这种气概，又正来自于其置生死于度外的献身精神。这样，这首诗就和上一首彼此呼应，并为下一首写功高不赏张本。诗中所出现的雕弧、金鞍和白羽，均是以着色之笔略加点染，本来是爱其人而及其物，这里的物又为人增色，人与物原不妨是互相辉映、相得益彰的。盛唐诗人每喜表现尚武精神，如李白自称“弯弓绿弦开，满月不惮坚。闲骑骏马猎，一射两虎穿。”（《赠宣城宇文太守兼呈崔侍御》）杜甫自述“射飞曾纵鞚，引臂落鹙鸧。”（《壮游》）王维则称赞他的一位族弟说：“读书复骑射，带剑游淮阴……席帆聊问罪，卉服尽成擒。”（《送从弟蕃游淮南》）等等。这些都可看作是诗中理想形象的现实依据。\n\n　　第四首，写游侠的功成无赏。上一首诗既已写到少年游侠的勇却群敌，那么这一首写朝廷论功行赏，他也理应是受奖的主角了。诗的前三句，极写庆功仪式的隆重和气氛的热烈：君臣欢宴、云台论功、天子临轩、封侯赐爵，正当期待中的主角出场时，领赏者却突然变成了“将军”。这里的“将军”和第二首“初随骠骑战渔阳”里的“骠骑”当是一人，指军中的主帅。“将军讽出明光宫”，也即李白《塞下曲》其三所云：“功成画麟阁，独有霍嫖姚。”意谓受皇帝宠信的权贵坐享其成而血战的勇士反遭冷落。诗以烘云托月的手法反复渲染，到头来却翻作他人；而活跃在前三首诗里的主角被悄无声息地推到了局外。这种欲抑故扬的艺术处理，使诗中的不平之鸣得以强有力的表现，这里再加申说反而是多余的了。\n\n　　王维的《少年行四首》，以浪漫的笔调讴歌了豪荡使气、舍身报国、崇尚事功和功成不居的任侠精神，表现出强烈的英雄主义色彩。他笔下的少年游侠形象，和盛唐其他诗人创造的形象一样，实际上是时代理想的人格化写照。这四首绝句独自成篇，各有侧重，但又蝉联而下，互相补充和照应。用笔或实或虚，或显或隐，舒卷自如，不拘一格，成功地谱写了一支朝气蓬勃、富有青春旋律的进行曲。', poem_tags = '乐府,励志,少年,喝酒,边塞,战争' WHERE poem_title = '少年行四首' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '都说作诗是为了赠汨罗江，作为当今的快乐又奈何。我曾经听说对木雕神像祈求幸福，试着向艾人祝福啊！\n明明是忠言，却不被楚王采纳，最后落得个沉江而死的下场，但是留下的文章却像星星一样永垂不朽。再倒一杯昌歜酒?为屈原而击节歌唱吧！\n每年端午节都会下雨刮风，像是为屈原喊冤陈情。我想要找人谈谈这些心事，去玩只有屋舍南北的鹁鸠。', poem_notes = '谩说：犹休说。 \n木居士：木雕神像的戏称。\n艾人：端午节，有的用艾束为人形，称为“艾人”。\n沉死：沉江而死。\n星斗罗：星星一样永垂不朽。\n风兼雨：下雨刮风。\n陈昔冤：喊冤陈情。\n舍：房屋。', poem_tags = '端午节,怀人,组诗' WHERE poem_title = '端午三首' AND poem_author = '赵蕃';
UPDATE edu_poem SET poem_translation = '请你下马来喝一杯酒，敢问朋友你要去何方？\n你说因为生活不得意，回乡隐居在终南山旁。\n只管去吧我何须再问，看那白云正无边飘荡。', poem_notes = '饮君酒：劝君饮酒。饮，使……喝。\n何所之：去哪里。之，往。\n归卧：隐居。南山：终南山，即秦岭，在今陕西省西安市西南。陲：边缘。\n但，只。', poem_appreciation = '这首诗写送友人归隐。全诗六句，仅第一句叙事，五个字就叙写出自己骑马并辔送了友人一段路程，然后才下马设酒，饯别友人。下马之处也就是饯饮之地，大概在进入终南山的山口。这样就把题旨点足。以下五句，是同友人的问答对话。第二句设问，问友人向哪里去，以设问自然地引出下面的答话，并过渡到归隐，表露出对友人的关切。三、四句是友人的回答。看似语句平淡无奇，细细读来，却是词浅情深，含着悠然不尽的意味。王维笔下是一个隐士，有自己的影子，至于为什么不得意，放在杜甫等人那里一定有许多牢骚，可在这里只是一语带过，更见人物的飘逸性情，对俗世的厌弃以及对隐居生活的向往。\n\n　　“不得意”三字，指出了友人归隐的原因，道出了友人心中郁抑不平。至于友人不得意的内容，当然主要是指政治上、功业上的怀才不遇。诗人没有明确写出，也不必写出，留以想象空间。五、六句，是他在得知友人“不得意”后，对友人的劝慰。他劝友人只管到山中去，不必再为尘世间得意失意的事情苦恼，只有山中的白云才是无穷无尽的。这里明说山中白云无尽，而尘世的功名利禄的“有尽”，无常，已含蕴其中。这两句意蕴非常复杂、丰富，诗的韵味很浓。句中有诗人对友人的同情、安慰，也有自己对现实的愤懑，有对人世荣华富贵的否定，也有对隐居山林的向往。似乎是旷达超脱，又带着点无可奈何的情绪。从全篇看，诗人以问答的方式，既使送者和行人双方的思想感情得以交流，又能省略不少交代性的文字，还使得诗意空灵跳脱，语调亲切。\n\n　　王维这首《送别》，用了禅法入诗，富于禅家的机锋。禅宗师弟子间斗机锋，常常不说话，而做出一些奇怪的动作，以求“心心相印”。即使要传达禅意，也往往是妙喻取譬，将深邃意蕴藏在自然物象之中，让弟子自己去参悟。王维在诗歌创作中吸收了这种通过直觉、暗示、比喻、象征来寄寓深层意蕴的方法。他在这首诗中，就将自己内心世界的复杂感受凝缩融汇在“白云无尽时”这一幅自然画面之中，从而达到了“拈花一笑，不言而喻”，寻味无穷的艺术效果。', poem_tags = '唐诗三百首,友情,送别,写景,抒情' WHERE poem_title = '送别' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '我驾着小舟在若耶溪上悠闲地游玩，天空倒映在水中，水天相和，一起荡悠。\n晚霞从远处背阳的山头升起，阳光照耀着蜿蜒曲折的水流。\n蝉声高唱，树林却显得格外宁静；鸟鸣声声，深山里倒比往常更清幽。\n这地方让我生了归隐之心，我因多年来厌倦仕途却没有归隐而悲伤起来。', poem_notes = '若耶溪：在绍兴市东南，发源于离城区44里的若耶山（今称化山），沿途纳三十六溪溪水，北入鉴湖。早年，上游流经群山，下游两岸竹木丰茂，是一处非常幽雅的旅游胜地。\n艅（yú）艎（huáng）：舟名。大船。\n泛泛：船行无阻。\n空：指天空。\n水：指若耶溪\n阴霞：山北面的云霞。若耶溪流向自南而北，诗人溯流而上，故曰“阴霞”。\n远岫（xiù）：远处的峰峦，这里指若耶山、云门山、何山、陶晏岭、日铸山等隐现的高山。\n阳景：指太阳在水中的影子；“景”是“影”的本字。\n回流：船向上游行进时岸边倒流的水。\n噪：许多鸟或虫子乱叫。\n逾：同“愈”，更加。\n幽：宁静、幽静\n归念：归隐的念头。\n长年悲倦游：诗人多年以来就厌倦仕途，却没有归隐，以此而悲伤。倦游：厌倦仕途而思退休。', poem_appreciation = '《梁书·文学传》有这么一段记载：“籍除轻车湘东王谘议参军，随府会稽。郡境有云门天柱山，籍尝游之，或累月不反。至若耶溪，赋诗云：‘蝉噪林逾静，鸟鸣山更幽。’当时以为文外独绝。”\n\n　　上面提到的“籍”，即王籍。诗的开头两句就缴足题面。诗人乘坐一条大船，驶向若耶溪上游，这就是题中的“入”。船不是快速行进，而是任意漂荡，可见诗人此行在于游赏自然。“泛泛”两字，除了写出水域宽阔，还表达了诗人的游兴。一个“何”字，入若耶溪的喜悦之情略略透出。一入若耶溪，马上发现这里的水特别清澈，抬头望天，天空高朗，白云悠悠；低头看水，水映朗空，也是一派悠悠；于是着一“共”字，将本来了然无涉的朗空和清水置于自然的和谐之中。\n\n　　前两句叙写中带有交代性质，接下去四句便具体描写若耶溪的美景了。“阴霞”、“远岫”、“阳景”“回流”，诗人观察很细，落笔非常客观。船是向上游行进的，溪是由南而北流向的，因此，除了题目中用“入”表明外，诗中还用“阴霞”、“回流”作照应。远处写山，近处写水，山水相映，境界奇美。但诗人不满足于此，他以云霞衬群山，以日影照清水，使境界富有了层次感和色彩感。不仅如此，诗人又将静景化动景，一个“生”字，不仅突出云霞的动态美，而且赋予云霞以情趣；一个“逐”字，人的行为赋予日影，仿佛日影像诗人一样正在追逐着回流，想跟艅艎一起行进，到上游去探个美的究竟。如果说“阴霞生远岫，阳景逐回流”从视角落笔，那么“蝉噪林逾静，鸟鸣山更幽”便是从听觉落笔了。这两句被称为“文外独绝”。它的“独绝”可从下列五个方面来阐明：\n\n　　第一，前面写到岫，是远景，写到影，是近景，这里再补写山林，如此写若耶溪，就不是纵向的，而照顾到两旁，就是说，不只是线，还考虑到面。\n\n　　第二，诗人写山林，在于写出若耶溪的幽静。这样幽静的环境，与“阴霞生远岫，阳景逐回流”和谐统一，是开头“泛泛”、“悠悠”情趣的写实。它们共同组成一个境界，为最后两句的抒情张本。\n\n　　第三，写山林的幽静，不是以静写静，而是以动写静。有了知了的鸣叫，山鸟的啼鸣，诗人才感到更加幽静，诚如钱钟书先生在《管锥编》中指出的“寂静之幽深者，每以得声音衬托而愈觉其深”。\n\n　　第四，诗人的情趣在幽静，因此，笔下不是死寂、沉寂、寂静，而是处于清静的状态，并且给人以幽雅的感觉，这是依然充满生命活力的所在。写蝉，写鸟，而且蝉在噪，鸟在鸣，目的就在于此。后来王安石在《钟山绝句》之一中作了另一番描写：“涧水无声绕竹流，竹西花草弄春柔。茅檐相对坐终日，一鸟不鸣山更幽。”就没有幽静的感觉，不能说不是模仿的失败。\n\n　　第五，这两句出以工整的对句形式，读起来有一种整齐美。\n\n　　最后两句抒情。诗人说，若耶溪这样幽静的境界，激起我回乡隐居的情思，使我为长期在外做官感到伤悲。“此地”一顿，将上述描写和感情作一汇总，转入对今后生活的打算，自然贴切，“动”字下得传神，这是其一。景色宜人，却使诗人引出悲绪，实际上这是从反面着笔，说明若耶溪美景给人以喜情，只是没有点明“喜”字罢了，这是其二。诗人游若耶溪的目的在赏心悦目，孰料游完却激起归隐若耶溪的念头，说明诗人长年在外做官并不得意，故“游”前着一“倦”字，这是其三。这样的收结，也明白地告诉读者，王籍是会稽郡人。\n\n　　此诗之后，描写若耶溪的诗作不断涌现，而且或多或少受了它的影响。如崔颢《入若耶溪》：“轻舟去何疾，已到云林境。起坐鱼鸟间，动摇山水影。岩中响自答，溪里言弥静。事事令人幽，停挠向馀景。”孟浩然《耶溪泛舟》：“落景余清辉，轻挠弄溪渚。澄明爱水物，临泛何容与。白首垂钓翁，新妆浣纱女。相看似相识，脉脉不得语。”', poem_tags = '古诗三百首,写景,思归' WHERE poem_title = '入若耶溪' AND poem_author = '王籍';
UPDATE edu_poem SET poem_tags = '春节' WHERE poem_title = '元日' AND poem_author = '李世民';
UPDATE edu_poem SET poem_translation = '唐军将士誓死横扫匈奴奋不顾身，\n五千身穿锦袍的精兵战死在胡尘。\n真可怜呵那无定河边成堆的白骨，\n还是少妇们梦中相依相伴的丈夫。', poem_notes = '貂锦：这里指战士，指装备精良的精锐之师。\n无定河：在陕西北部。\n春闺：这里指战死者的妻子。\n匈奴：指西北边境部族。', poem_appreciation = '《陇西行》是乐府《相和歌·瑟调曲》旧题，内容写边塞战争。陇西，即今甘肃宁夏陇山以西的地方。这首《陇西行》诗反映了唐代长期的边塞战争给人民带来的痛苦和灾难。虚实相对，宛若电影中的蒙太奇，用意工妙。诗情凄楚，吟来潸然泪下\n\n　　首二句以精炼概括的语言，叙述了一个慷慨悲壮的激战场面。唐军誓死杀敌，奋不顾身，但结果五千将士全部丧身“胡尘”。“誓扫”、“不顾”，表现了唐军将士忠勇敢战的气概和献身精神。汉代羽林军穿锦衣貂裘，这里借指精锐部队。部队如此精良，战死者达五千之众，足见战斗之激烈和伤亡之惨重。\n\n　　接着，笔锋一转，逼出正意：“可怜无定河边骨，犹是春闺梦里人。”这里没有直写战争带来的悲惨景象，也没有渲染家人的悲伤情绪，而是匠心独运，把“河边骨”和“春闺梦”联系起来，写闺中妻子不知征人战死，仍然在梦中想见已成白骨的丈夫，使全诗产生震撼心灵的悲剧力量。知道亲人死去，固然会引起悲伤，但确知亲人的下落，毕竟是一种告慰。而这里，长年音讯杳然，人早已变成无定河边的枯骨，妻子却还在梦境之中盼他早日归来团聚。灾难和不幸降临到身上，不但毫不觉察，反而满怀着热切美好的希望，这才是真正的悲剧。\n\n　　明代杨慎《升庵诗话》认为，此诗化用了汉代贾捐之《议罢珠崖疏》“父战死于前，子斗伤于后，女子乘亭鄣，孤儿号于道，老母、寡妻饮泣巷哭，遥设虚祭，想魂乎万里之外”的文意，称它“一变而妙，真夺胎换骨矣”。贾文着力渲染孤儿寡母遥祭追魂，痛哭于道的悲哀气氛，写得沉痛而富有情致。文中写家人“设祭”、“想魂”，已知征人战死。而陈陶诗中的少妇则深信丈夫还活着，丝毫不疑其已经死去，几番梦中相逢。诗意更深挚，情景更凄惨，因而也更能使人一洒同情之泪。\n\n　　这诗的跌宕处全在三、四两句。“可怜”句紧承前句，为题中之义；“犹是”句荡开一笔，另辟新境。“无定河边骨”和“春闺梦里人”，一边是现实，一边是梦境；一边是悲哀凄凉的枯骨，一边是年轻英俊的战士，虚实相对，荣枯迥异，造成强烈的艺术效果。一个“可怜”，一个“犹是”，包含着多么深沉的感慨，凝聚了诗人对战死者及其家人的无限同情。\n\n　　明王世贞《艺苑卮言》赞赏此诗后二句“用意工妙”，但指责前二句“筋骨毕露”，后二句为其所累。其实，首句写唐军将士奋不顾身“誓扫匈奴”，给人留下了深刻的印象。而次句写五千精良之兵，一旦之间丧身于“胡尘”，确实令人痛惜。征人战死得悲壮，少妇的命运就更值得同情。所以这些描写正是为后二句表现少妇思念征人张本。可以说，若无前二句明白畅达的叙述描写作铺垫，想亦难见后二句“用意”之“工妙”。', poem_tags = '唐诗三百首,边塞,战争,妇女,思念' WHERE poem_title = '陇西行四首·其二' AND poem_author = '陈陶';
UPDATE edu_poem SET poem_translation = '注释 一剪梅：此词牌以周邦彦所作起句有“一剪梅花万样娇”句，故取为调名。又名“玉簟秋”、“腊梅香”。重头六十字，平韵。 “雨打梨花”句：用宋人李重元《忆王孙·春词》结末成句。 销魂：黯然神伤。 颦：皱眉。“愁聚”句意为整日眉头皱蹙如黛峰耸起。 “晓看”句：两个“看”字实系无意义举止，乃特定心态的外现行为。', poem_appreciation = '《一剪梅·雨打梨花深闭门》是明代词人、一代文豪唐寅，即唐伯虎的作品。这首词的佳处不只在于词句之清圆流转，其于自然明畅的吟哦中所表现的空间阻隔灼痛着痴恋女子的幽婉心态更是动人。唐寅轻捷地抒述了一种被时空折磨的痛苦，上下片交叉互补、回环往复，将一个泪痕难拭的痴心女形象灵动地显现于笔端。\n\n　　唐寅这阕《一剪梅》的佳处不只在于词句之清圆流转，其于自然明畅的吟哦中所表现的空间阻隔灼痛着痴恋女子的幽婉心态更是动人。空间，既无情地拉开着恋者的距离，而空间的阻隔又必然在一次次“雨打梨花”、春来春去中加重其往昔曾经有过的“赏心乐事”的失落感；至若青春年华也就无可挽回地在花前月下神伤徘徊之间被残酷地空耗去。时间在空间中流逝，空间的凝滞、间距的未能缩却，尤加速着时光的消失。上片的“花下销魂，月下销魂”，是无处不令 “我” 回思往时的温馨；下片的“行也思君，坐也思君”则写尽朝暮之间无时不在翘首企盼所恋者的归来，重续欢情。唐寅轻捷地抒述了一种被时空折磨的痛苦，上下片交叉互补、回环往复，将一个泪痕难拭的痴心女形象灵动地显现于笔端，诚无愧其“才子”之誉称。', poem_tags = '闺怨,女子,思念' WHERE poem_title = '一剪梅·雨打梨花深闭门' AND poem_author = '唐寅';
UPDATE edu_poem SET poem_translation = '草堂的南北涨满了春水，只见鸥群日日结队飞来。老夫不曾为客扫过花径，今天才为您扫，这柴门不曾为客开过，今天为您打开。离市太远盘中没好菜肴，家底太薄只有陈酒招待。若肯邀请隔壁的老翁一同对饮，隔着篱笆唤来喝尽余杯！', poem_notes = '客至：客指崔明府，杜甫在题后自注：“喜 崔明府相过”，明府，县令的美称。 \n舍：指家。但见：只见。此句意为平时交游很少，只有鸥鸟不嫌弃能与之相亲。\n蓬门：用蓬草编成的门户，以示房子的简陋。\n市远：离市集远。兼味：多种美味佳肴。无兼味，谦言菜少。樽：酒器。旧醅：隔年的陈酒。樽酒句：古人好饮新酒，杜甫以家贫无新酒感到歉意。\n肯：能否允许，这是向客人征询。余杯：余下来的酒。\n花径：长满花草的小路 \n呼取：叫，招呼', poem_appreciation = '这是一首工整而流畅的七律。前两联写客至，有空谷足音之喜，后两联写待客，见村家真率之情。篇首以“群鸥”引兴，篇尾以“邻翁”陪结。在结构上，作者兼顾空间顺序和时间顺序。从空间上看，从外到内，由大到小；从时间上看，则写了迎客、待客的全过程。衔接自然，浑然一体。但前两句先写日常生活的孤独，从而与接待客人的欢乐情景形成对比。这两句又有“兴”的意味：用“春水”、“群鸥”意象，渲染出一种充满情趣的生活氛围，流露出主人公因客至而欢欣的心情。\n\n　　刘克庄《后村诗话》说：“此篇若戏效元白体者。”杜甫自不可能飞跃时空去戏效他后代的元白体，那么从什么角度什么意义上讲，《客至》“戏效元白体”呢？简而言之，元白体就是指浅切平易的诗歌风格。综观全诗，语势流畅，除“盘飧”、“兼味”、“樽酒”之外，其馀语句都没有太大的障碍，尤其是尾联虚字（“肯与”）和俗语（“呼取”）的运用，足当“戏效元白体”之评。另外，诗用第一人称，表达质朴流畅，自然亲切，与内容非常协调，形成一种欢快淡雅的情调，与杜甫其他律诗字斟句酌的风格确实不大一样，难怪刘克庄说它是戏效元白体。', poem_tags = '唐诗三百首,待客,友情,喜悦,写景' WHERE poem_title = '客至' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '白话译文\n江上来来往往的人只喜爱鲈鱼的味道鲜美。\n看看那些可怜的打鱼人吧，正驾着小船在大风大浪里上下颠簸，飘摇不定。\n\n英文译文\nTHE FISHERMAN ON THE STREAM\nYou go up and down stream;\nYou love to eat the bream.\nLo! The fishing boat braves\nPerilous wind and waves.', poem_notes = '①渔者：捕鱼的人。\n②但：只\n江上渔者\n江上渔者\n③爱：喜欢\n④鲈鱼：一种头大口大、体扁鳞细、背青腹白、 味道鲜美的鱼。 生长快，体大味美。\n⑤君：你。\n⑥一叶舟：像漂浮在水上的一片树叶似的小船。\n⑦出没：若隐若现。指一会儿看得见，一会儿看不见。\n⑧风波：波浪。', poem_appreciation = '这首语言朴实、形象生动、对比强烈、耐人寻味的小诗，反映了渔民劳作的艰辛，唤起人们对民生疾苦的注意。\n\n　　首句写江岸上人来人往，十分热闹。次句写岸上人的心态，揭示“往来’的原因。后二句牵过的视线，指示出风浪中忽隐忽现的捕鱼小船，注意捕鱼的情景。鲈鱼虽味美，捕捉却艰辛表达出诗人对渔人疾苦的同情，深含对“但爱鲈鱼美”的岸上人的规劝。“江上”和“风波”两种环境，“往来人”和“一叶舟”两种情态、“往来”和“出没”两种动态强烈对比，显示出全诗旨在所在。\n\n　　表现手法上，该诗无华丽词藻，无艰字僻典，无斧迹凿痕，以平常的语言，平常的人物、事物，表达不平常的思想、情感，产生不平常的艺术效果。', poem_tags = '渔人,生活,抒怀,同情' WHERE poem_title = '江上渔者' AND poem_author = '范仲淹';
UPDATE edu_poem SET poem_tags = '春天,写水,写景,抒情' WHERE poem_title = '南湖早春' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '有个想要买鞋子的郑国人，先测量好自己脚的尺码，把尺码放在他的座位上，等到前往集市，却忘了带量好的尺码。已经拿到鞋子，却说：“我忘记带量好的尺码了。”就返回家去取量好的尺码。等到他返回集市的时候，集市已经散了，最后郑国人没能买到鞋子。\n　　有人问他说：“为什么你不用自己的脚去试一试呢?”\n　　他说：“我宁可相信量好的尺码，也不相信自己的脚。”', poem_notes = '选自《韩非子·外储说左上》。郑：春秋时代郑国，在现今河南省的新郑县。\n欲：将要，想要。\n者：（怎么样）的人。（定语后置）\n先：首先，事先。\n度（duó）：衡量。用尺子度量的意思（动词）\n而：顺承连词 意为然后\n置： 放，搁在。（动词）\n之：代词，它，此处指量好的尺码。\n其：他的，指郑人的。（代词）\n坐：通“座”，座位。\n至：等到。\n之：到……去，前往。（动词）\n操：拿、携带。（动词）\n已：已经。（时间副词）\n得：得到；拿到。\n履：鞋子，革履。（名词）\n乃：于是（就）\n持：拿，在本文中同“操”。（动词）\n度（dù)：量好的尺码，这里作动词用，即计算、测量的意思。（名词） \n之：文言代名词，这里指量好的尺码。\n操：操持，带上拿着的意思\n及：等到。\n反：通“返”，返回。\n罢：引申为散了，完结的意思，这里指集市已经解散。\n遂：于是。\n曰：说。\n宁（nìng）：副词。宁可，宁愿。\n无：虚无，没有，这里是不能、不可的意思。\n自信：相信自己。\n以：用。\n吾：我。\n市罢：集市散了\n至之市：等到前往集市。', poem_tags = '小学文言文,寓理,故事,讽刺' WHERE poem_title = '郑人买履' AND poem_author = '韩非';
UPDATE edu_poem SET poem_translation = '八岁小姑娘喜欢偷偷地照镜子，已能把自己的眉毛画成长眉了。\n十岁到野外踏青，想象着荷花做自己的衣裙。\n十二岁开始学弹筝，套在手指上的银甲一直没脱下来。\n十四岁时，要避免见到男性，连最亲的人也不能见，这时她可能在猜想何时出嫁吧。\n十五岁时，她背对着秋千，在春风中哭泣，怕春天的消逝。', poem_notes = '偷：指羞涩，怕人看见。\n长眉：古以纤长之眉为美，《古今注》：“魏宫人好画长眉。”\n踏青：《月令粹编》引《秦中岁时记》：“上巳赐宴曲江，都人士于江头禊饮，践踏青草，谓之踏青履。”\n芙蓉：荷花。《离骚》：“集芙蓉以为裳。”裙衩：下端开口的衣裙。\n筝（zhēng）：乐器，十三弦。\n银甲：银制假指甲，弹筝用具。\n六亲：本指最亲密的亲属，这里指男性亲属。\n悬知：猜想。\n泣春风：在春风中哭泣，怕春天的消逝。\n背面：背着女伴。秋千下：女伴在高兴地打秋千。\n招邀：邀请。\n裛（yì）：沾湿。\n风蝶：风中之蝶。娇饶：柔美妩媚。\n不自聊：不能自行排遣，烦闷无聊。', poem_appreciation = '这首诗以少女怀春之幽怨苦闷，喻少年才士渴求仕进遇合之心情。这位少女八岁犹存爱美之心。古以长眉为美，所谓“青黛点眉眉细长”，犹为唐人入时装扮。十岁时就有了高洁的情操，郊外春游，知道缝缀荷花制成下裳。作者化用了屈原《离骚》语句：“制芰荷以为衣兮，集芙蓉以为裳。不吾知其亦已兮，苟余情其信芳。”即是说，裁剪荷叶制成绿色的上衣，缝缀荷花再把它制成下裳。没有人了解我也毫不在乎，只要我内心情感确实芬芳。十二岁学艺刻苦，学弹秦筝，所用的银爪从不曾取下。十四岁怀春羞涩，藏于深阁，回避关系最亲的男性戚属，“悬知”，表现了女子半是希望半是担忧的待嫁心理。十五岁无处说相思，古时女子十五岁许嫁，诗中女主人公前途未卜，忧伤烦闷，又无处说相思，更无心为秋千之戏，这还不够，作者善作情语，让少女独自对面春风而泣，何等情思。\n\n　　从此诗的描述看，这位诗中的姑娘也许是诗人初恋对象，因为只有青梅竹马的异性，才可能有如此近距离的观察，才写得出如此动人心弦的诗。可惜父母未能如其愿，姑娘在“泣春风”，也是诗人在叹息。“十五泣春风”正是写出了诗人与姑娘的这段恋爱，没有结果，从此要劳燕分飞，天各一方了。\n\n　　有专家研究此诗是自喻少负才华、渴望参与社会政治生活而又忧虑前途，证据是诗人在《樊南甲集序》中曾自称：“樊南生十六能著《才论》、《圣论》，以古文出诸公间。”近人韦然超认为，这是诗人在十六岁时因初恋对象之父母未能同意他们这段婚姻，而写下的这首诗，不能明题，故称“无题”。而且在其后的众多“无题”诗中有相当数量还是在写他的这段无果初恋。可见这位姑娘在诗人心中的地位，尽管此后诗人结婚生子，与夫人感情深笃，但这段初恋却深深地埋藏心底，时时以“无题”作诗念之。', poem_tags = '写人,少女,爱情' WHERE poem_title = '无题·八岁偷照镜' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '我听说想要树木生长，一定要稳固它的根；想要泉水流得远，一定要疏通它的源泉；想要国家安定，一定要厚积道德仁义。源泉不深却希望泉水流得远，根系不牢固却想要树木生长。道德不深厚却想要国家安定，我虽然地位低见识浅，（也）知道这是不可能的，更何况（您这）聪明睿智（的人）呢！国君处于皇帝的重要位置，在天地间尊大，就要推崇皇权的高峻，永远保持政权的和平美好。如果不在安逸的环境中想着危难，戒奢侈，行节俭，道德不能保持宽厚，性情不能克服欲望，这也（如同）挖断树根来求得树木茂盛，堵塞源泉而想要泉水流得远啊。\n\n　　（古代）所有的帝王，承受了上天赋予的重大使命，他们没有一个不为国家深切地忧虑而且治理成效显著的，但大功告成之后国君的品德就开始衰微了。国君开头做得好的确实很多，能够坚持到底的大概不多，难道是取得天下容易守住天下困难吗？过去夺取天下时力量有余，现在守卫天下却力量不足，这是为什么呢？通常处在深重的忧虑之中一定能竭尽诚心来对待臣民，已经成功，就放纵自己的性情来傲视别人。竭尽诚心，虽然一在北方，一在南方，也能结成一家，傲视别人，就会使亲人成为陌路之人。即使用严酷的刑罚来督责（人们），用威风怒气来吓唬（人们），（臣民）只求苟且免于刑罚而不怀念感激国君的仁德，表面上恭敬而在内心里却不服气。（臣民）对国君的怨恨不在大小，可怕的只是百姓；（他们像水一样）能够负载船只，也能颠覆船只，这是应当深切谨慎的。疾驰的马车却用腐烂的绳索驾驭，怎么可以疏忽大意呢？\n\n　　做国君的人，如果真的能够做到一见到能引起（自己）喜好的东西就要想到用知足来自我克制，将要兴建什么就要想到适可而止来使百姓安定，想到帝位高高在上就想到要谦虚并加强自我约束，害怕骄傲自满就想到要像江海那样能够（处于）众多河流的下游，喜爱狩猎就想到网三面留一面，担心意志松懈就想到（做事）要慎始慎终，担心（言路）不通受蒙蔽就想到虚心采纳臣下的意见，考虑到（朝中可能会出现）谗佞奸邪就想到使自身端正（才能）罢黜奸邪，施加恩泽就要考虑到不要因为一时高兴而奖赏不当，动用刑罚就要想到不要因为一时发怒而滥用刑罚。全面做到这十件应该深思的事，弘扬这九种美德，选拔有才能的人而任用他，挑选好的意见而听从它。那么有智慧的人就能充分献出他的谋略，勇敢的人就能完全使出他的力量，仁爱的人就能散播他的恩惠，诚信的人就能献出他的忠诚。文臣武将争先恐后前来效力，国君和大臣没有大事烦扰，可以尽情享受出游的快乐，可以颐养得像赤松子与王子乔那样长寿，皇上弹着琴垂衣拱手就能治理好天下，不用再说什么，天下人就已经都有教化了。为什么一定要（自己）劳神费思，代替臣下管理职事，役使自己灵敏、明亮的耳、眼，减损顺其自然就能治理好天下的大道理呢！', poem_notes = '1.长（zhǎng）：生长。\n2.固其根本：使它的根本牢固。本，树根。\n3.浚（jùn）：疏通，挖深。\n4.在下愚：处于地位低见识浅的人。\n5.明哲：聪明睿智（的人）。\n6.当神器之重：处于皇帝的重要位置。神器，指帝位。古时认为“君权神授”，所以称帝位为“神器”。\n7.域中：指天地之间。\n8.休：美。这里指政权的平和美好。\n9.凡百元首：所有的元首，泛指古代的帝王。\n10.承天景命：承受了上天赋予的重大使命。景，大。\n11.殷忧：深忧。\n12.实：的确。\n13.克终者盖寡：能够坚持到底的大概不多。克，能。盖，表推测语气。\n14.傲物：傲视别人。物，这里指人。\n15.吴越为一体：（只要彼此竭诚相待）虽然一在北方，一在南方，也能结成一家。胡，指北方；越，指南方。\n16.骨肉为行路：亲骨肉之间也会变得像陌生人一样。骨肉，有血缘关系的人。行路，路人，比喻毫无关系的人。\n17.董：督责。\n18.振：通“震”，震慑。\n19.苟免而不怀仁：（臣民）只求苟且免于刑罚而不怀念感激国君的仁德。\n20.怨不在大：（臣民）对国君的怨恨不在大小。\n21.可畏唯人：可怕的只是百姓。人，本应写作“民”，因避皇上李世民之名讳而写作“人”。\n22.载舟覆舟：这里比喻百姓能拥戴皇帝，也能推翻他的统治。出自《荀子·王制》：“君者，舟也；庶人者，水也。水则载舟，水则覆舟。”\n23.见可欲：见到能引起（自己）喜好的东西。出自《老子》第三章“不见可欲，使民心不乱”。下文的“知足”、“知止”（知道适可而止），出自《老子》第四十四章“知足不辱”，“知止不殆”。\n24.将有所作：将要兴建某建筑物。作，兴作，建筑。\n25.安人：安民，使百姓安宁。\n26.念高危：想到帝位高高在上。危，高。\n27.则思谦冲而自牧：就想到要谦虚并加强自我修养。冲，虚。牧，约束。\n28.江海下而百川：江海处于众多河流的下游。下，居……之下。\n29.盘游：打猎取乐。\n30.三驱：据说古代圣贤之君在打猎布网时只拦住三面而有意网开一面，从而体现圣人的“好生之仁”。另一种解释为田猎活动以一年三次为度。\n31.敬终：谨慎地把事情做完。\n32.虑壅（yōng）蔽：担心（言路）不通受蒙蔽。壅，堵塞。\n33.想谗邪：考虑到（朝中可能会出现）谗佞奸邪。谗，说人坏话，造谣中伤。邪，不正派。\n34.正身以黜（chù）恶：使自身端正（才能）罢黜奸邪。黜，排斥，罢免。\n35.宏兹九德：弘扬这九种美德。九德，指忠、信、敬、刚、柔、和、固、贞、顺。\n36.简：选拔。\n37.效：献出。\n38.松乔：赤松子和王子乔，古代传说中的仙人。\n39.垂拱：垂衣拱手。比喻很轻易的天下就实现大治了。\n40.无为：道家主张清静虚无，顺其自然。', poem_tags = '古文观止,高中文言文,劝谏,寓理' WHERE poem_title = '谏太宗十思疏' AND poem_author = '魏征';
UPDATE edu_poem SET poem_translation = '房兵曹的这一匹马是产自大宛国的名马，它那精瘦的筋骨像刀锋一样突出分明。\n它的两耳如斜削的竹片一样尖锐，跑起来四蹄生风，好像蹄不践地一样。\n这马奔驰起来，从不以道路的空阔辽远为难，骑着它完全可以放心大胆地驰骋沙场，甚至可托生死。\n拥有如此奔腾快捷、堪托死生的良马，真可以横行万里之外，为国立功了。', poem_notes = '兵曹：兵曹参军的省称，是唐代州府中掌官军防、驿传等事的小官。房兵曹，不详为何人。胡：此指西域。\n大宛（yuān）：汉代西域国名，其地在今乌兹别克斯坦境内，盛产良马。大宛名：著名的大宛马。\n锋棱：锋利的棱角。形容马的神骏健悍之状。\n竹批：形容马耳尖如竹尖。峻：尖锐。“双耳峻”是良马的特征之一。\n堪：可以，能够。托死生：马值得信赖，对人的生命有保障。\n骁（xiāo）腾：健步奔驰。', poem_appreciation = '这是一首咏物言志诗。杜甫本来善于骑马，也很爱马，写过不少咏马诗。此诗的风格超迈遒劲，凛凛有生气，反映了青年杜甫锐于进取的精神。\n\n　　诗分前后两部分。前面四句正面写马，是实写。诗人恰似一位丹青妙手，用传神之笔为我们描画了一匹神清骨峻的“胡马”。它来自大宛（汉代西域的国名，素以产“汗血马”著称），自然非凡马可比。接着，对马作了形象的刻画。南齐谢赫的《古画品录》提出“六法”，第一为“气韵生动”，第二即是“骨法用笔”，这是作为气韵生动的首要条件提出来的。所谓“骨法”，就是要写出对象的风度、气格。杜甫写马的骨相：嶙峋耸峙，状如锋棱，勾勒出神峻的轮廓。接着写马耳如刀削斧劈一般锐利劲挺，这也是良马的一个特征。至此，骏马的昂藏不凡已跃然纸上了，我们似见其咴咴喷气、跃跃欲试的情状，下面顺势写其四蹄腾空、凌厉奔驰的雄姿就十分自然。“批”和“入”两个动词极其传神。前者写双耳直竖，有一种挺拔的力度；后者不写四蹄生风，而写风入四蹄，别具神韵。从骑者的感受说，当其风驰电掣之时，好像马是不动的，两旁的景物飞速后闪，风也向蹄间呼啸而入。诗人刻画细致，唯妙逼真。颔联两句以“二二一”的节奏，突出每句的最后一字：“峻”写马的气概，“轻”写它的疾驰，都显示出诗人的匠心。这一部分写马的风骨，用的是大笔勾勒的方法，不必要的细节一概略去，只写其骨相、双耳和奔驰之态，因为这三者最能体现马的特色。正如张彦远评画所云：“笔才一二，象已应焉，离披点画，时见缺落，此虽笔不周而意周也。”《历代名画记》这就是所谓“写意传神”。\n\n　　诗的前四句写马的外形动态，后四句转写马的品格，用虚写手法，由咏物转入了抒情。颈联承上奔马而来，写它纵横驰骋，历块过都，有着无穷广阔的活动天地；它能逾越一切险阻的能力就足以使人信赖。这里看似写马，实是写人，这其实就是一个忠实的朋友、勇敢的将士、侠义的豪杰的形象。尾联先用“骁腾有如此”总挽上文，对马作概括，最后宕开一句：“万里可横行”，包含着无尽的期望和抱负，将意境开拓得非常深远。这一联收得拢，也放得开，它既是写马驰骋万里，也是期望房兵曹为国立功，更是诗人自己志向的写照。盛唐时代国力的强盛，疆土的开拓，激发了民众的豪情，书生寒士都渴望建功立业，封侯万里。这种蓬勃向上的精神用骏马来表现确是最合适不过了。这和后期杜甫通过对病马的悲悯来表现忧国之情，真不可同日而语。\n\n　　南朝宋人宗炳的《画山水序》认为通过写形传神而达于“畅神”的道理。如果一个艺术形象不能“畅神”，即传达作者的情志，那么再酷肖也是无生命的。杜甫此诗将状物和抒情结合得自然无间。在写马中也写人，写人又离不开写马，这样一方面赋予马以活的灵魂，用人的精神进一步将马写活；另一方面写人有马的品格，人的情志也有了形象的表现。前人讲“咏物诗最难工，太切题则粘皮带骨，不切题则捕风捉影，须在不即不离之间”钱泳《履园谈诗》，这个要求杜甫是做到了。', poem_tags = '咏物,言志' WHERE poem_title = '房兵曹胡马诗' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '渔翁晚上靠着西山歇宿，早上汲取清澈的湘水，以楚竹为柴做饭。\n太阳出来云雾散尽不见人影，摇橹的声音从碧绿的山水中传出。\n回头望去渔舟已在天边向下漂流，山上的白云正在随意飘浮，相互追逐。', poem_notes = '傍：靠近。西岩：当指永州境内的西山，可参作者《始得西山宴游记》。\n汲（jí）：取水。湘：湘江之水。楚：西山古属楚地。\n销：消散。亦可作“消”。\n欸（ǎi）乃：象声词，一说指桨声，一说是人长呼之声。唐时湘中棹歌有《欸乃曲》（见元结《欸乃曲序》）。\n下中流：由中流而下。\n无心：陶渊明《归去来兮辞》：“云无心而出岫。”一般是表示庄子所说的那种物我两忘的心灵境界。苏轼《书柳子厚〈渔翁〉诗》云：“诗以奇趣为宗，反常合道为趣。熟味此诗有奇趣。然其尾两句，虽不必亦可。”严羽《沧浪诗话》从此说，曰：“东坡删去后二句，使子厚复生，亦必心服。”然刘辰翁认为：“此诗气泽不类晚唐，下正在后两句。”此后，关于此诗后两句当去当存，一直有两种意见。', poem_appreciation = '这首小诗情趣盎然，诗人以淡逸清和的笔墨构画出一幅令人迷醉的山水晨景，并从中透露了他深沉热烈的内心世界。\n\n　　这首诗取题渔翁，渔翁是贯串全诗首尾的核心形象。但是，诗人并非孤立地为渔翁画像，作品的意趣也不唯落在渔翁的形象之上。完整地看，构成诗篇全境的，除了辛劳不息的渔翁以外，还有渔翁置身于其中的山水天地，这两者在诗中留下了按各自的规律特点而发展变幻的形迹。但同时，诗人又把两者浑然融化，渔翁和自然景象结成不可分割的一体，共同显示着生活的节奏和内在的机趣。由夜而晨，是人类活动最丰富的时刻，是万物复苏、生机勃勃的时刻，本诗即以此为景色发展的线索。因此，渔翁不断变换的举止行动和自然景色的无穷变幻便有了共同的时间依据，取得极为和谐的统一。\n\n　　全诗共六句，按时间顺序，分三个层次。“渔翁夜傍西岩宿，晓汲清湘燃楚竹。”这是从夜到拂晓的景象。渔翁是这两句中最引人注目的形象，他夜宿山边，晨起汲水燃竹，以忙碌的身影形象地显示着时间的流转。伴随着渔翁的活动，诗人的笔触又自然而然地延及西岩、清湘、楚竹，西岩即永州西山，柳宗元在《始得西山宴游记》一文中曾极言探得西山的欢悦，并描述了西山的高峻：居于西山之巅，“则凡数州之土壤，皆在衽席之下”；而流经山下的湘水“至清，虽深五六丈，见底”（《湘中记》，见《太平御览》卷六十五）。诗中的“清”字正显示了湘水的这一特点。再加以永州一带（今湖南零陵等地）盛产湘竹，于是，山、水、竹这些仿佛不经意地出现在诗句中的零星物象，却分明在读者脑海中构成了清新而完整的画面：轻纱般的薄雾笼罩着高山、流水、湘竹……司空图在《诗品》中有言：“是有真迹，如不可知，意象欲出，造化已奇”，正可概括此诗首二句的艺术表现特点。这两句既设制了一个秀丽悦目的空间画面，又以夜幕初启、晨曦微露这样流动的时间感引出了下面对日出的描述，可以说在时空两方面奠定了全诗活跃而又清逸的基调。\n\n　　“烟销日出不见人，欸乃一声山水绿。”这是最见诗人功力的妙句，也是全诗的精华所在，若从内容上给予整理，这两句描写的是以下情景：一方面是自然景色：烟销日出，山水顿绿；一方面是渔翁的行踪：渔船离岸而行，空间传来一声橹响。然而，诗人没有遵循这样的生活逻辑来组织诗句，却从自我感受出发，交错展现两种景象，更清晰地表现了发生于自然界的微妙变异。前一句中“烟销日出”和“不见人”，一是清晨常见之景，一是不知渔船何时悄然离去的突发意识，两者本无必然的联系，但如今同集一句，却唤起了人们的想象力：仿佛在日出的一刹那，天色暗而忽明，万物从朦胧中忽而显豁，这才使人猛然发觉渔船已无踪影。“不见人”这一骤生的感受成为一个标志，划开了日出前后的界限，真实生活中的日出过程得到艺术的强化，以一种夸张的节奏出现在读者眼前。紧接着的“欸乃一声”和“山水绿”更使耳中所闻之声与目中所见之景发生了奇特的依存关系。清晨，山水随着天色的变化，色彩由黯而明，这是一个渐变的过程，但在诗中，随着划破静空的一下声响，万象皆绿，这一“绿”字不仅呈现出色彩的功能，而且给人一种动态感。这不禁使人想起王安石的著名诗句：“春风又绿江南岸”，王安石借春风的飘拂赋“绿”字以动态，而柳宗元则借声响的骤起，不仅赋之以动态，而且赋以顷刻转换的疾速感，生动地显现了日出的景象，令人更觉神奇。德国启蒙运动时期的文艺理论家莱辛在指出诗与画的区别时曾说：“一切物体不仅在空间中存在，而且也在时间中存在。物体也持续，在它的持续期内的每一顷刻都可以现出不同的样子，并且和其它事物发生不同的关系。……诗在它的持续性的摹仿里，也只能运用物体的某一个属性，而所选择的就应该是，从诗要运用它那个观点去看，能够引起该物体的最生动的感性形象的那个属性。”（《拉奥孔》）柳宗元没有静止地去表现日出的壮丽辉煌，或去描摹日出后的光明世界，他正是充分发挥语言艺术的特长，抓住最有活力，最富生气的日出瞬间，把生活中常见的自然景象表现得比真实更为美好，给人以强大的感染力。苏东坡论此诗道：“诗以奇趣为宗，反常合道为趣，熟味此诗，有奇趣。”（《冷斋诗话》）这是恰如其分的评语。\n\n　　“回看天际下中流，岩上无心云相逐。”日出以后，画面更为开阔。此时渔船已进入中流，而回首骋目，只见山巅上正浮动着片片白云，好似无心无虑地前后相逐，诗境极是悠逸恬淡。对这一结尾苏东坡认为“虽不必亦可”，因而还引起一场争论，一时间，宋严羽、刘辰翁，明胡应麟、王世贞，清王士禛、沈德潜等人各呈己见，众说纷纭，但是他们的争论都局限在艺术趣味上，却没有深入体会柳宗元作此诗的处境和心情。柳宗元在诗文中，曾多次言及他被贬后沉重压抑的心绪，在《与杨诲之第二书》中，他写道：“至永州七年矣，蚤夜惶惶”，理想抱负和冷酷的现实产生了尖锐的矛盾，在极度悲愤的情况下，他“但当把锄荷锸，决溪泉为圃以给茹，其隟则浚沟池，艺树木，行歌坐钓，望青天白云，以此为适。”在《始得西山宴游记》中，柳宗元表露得更明白：“自余为僇人，居是州，恒惴栗，其隟也，则施施而行，漫漫而游”，可见他并非以一颗平静恬淡的心徜徉于山水之间，而是强求宽解，以图寻得慰藉。但是，正如他在《游朝阳岩遂登西亭二十韵》中所叹的那样：“谪弃非隐沧，登陟非远郊”，事实上，他并没有获得真正的解脱，有时候，他因一山一水的遭遇而想及自己的不幸，于是不胜怅惘感慨，有时候他在登陟跋涉中意有所感，情不自禁地显露出不平和抗争，正因为如此，他更强烈地希求摆脱这种精神的压抑。所以，与其说《渔翁》以充满奇趣的景色表现出淡逸的情调，不如说更袒露了隐于其后的一颗火热不安的心。这是热烈的向往，是急切的追求，诗中显示的自由安适的生活情趣对于处在禁锢状态的诗人来说，实在是太珍贵太美好了。于是，在写下日出奇句之后，诗人不欲甘休，以更显露地一吐自己的心愿为快，化用陶渊明《归去来兮辞》中“云无心以出岫”的句子，宕开诗境，作了这样的收尾。只有真正体会柳宗元的现实处境，才能理解他结句的用心。诗人自始至终表现渔翁和大自然的相契之情，不仅出于艺术表现的需要，同样体现着他对自由人生的渴求。这也说明，要深入领会一篇作品的艺术风格，常常离不开对作者思想感情的准确把握。', poem_tags = '唐诗三百首,山水,写人' WHERE poem_title = '渔翁' AND poem_author = '柳宗元';
UPDATE edu_poem SET poem_translation = '亭台上的花影一层又一层，几次叫童儿去打扫，可是花影怎么扫走呢？傍晚太阳下山时，花影刚刚隐退，可是月亮又升起来了，花影又重重叠叠出现了。', poem_notes = '重重迭迭：形容地上的花影一层又一层，很浓厚。 \n瑶台：华贵的亭台。 \n几度：几次。\n童：男仆。这两句说，亭台上的花影太厚了，几次叫仆人扫都扫不掉。 \n收拾去：指日落时花影消失，好像被太阳收拾走了。 \n教：让。\n送将来：指花影重新在月光下出现，好像是月亮送来的。将，语气助词，用于动词之后。这两句说，太阳落了，花影刚刚消失，明月升起，它又随着月光出现了。', poem_appreciation = '赏析一 　　这首饶有趣味的小诗，作者也有争议。起因是这样的:有人查遍了《东坡七集》并未发现此作，而在谢枋得的《叠山集》中却发现了此诗，于是便欲“正名”为谢枋得所作，我觉得这有些过于唐突。　无论是《东坡七集》或者《叠山集》都经过后人辗转抄录编纂，遗漏诗作和窜入他人诗作的情况并不罕见，谢枋得是个十分崇敬苏轼的人，他的外号“叠山”，就是从苏轼的一首七律诗中的首句“溪上青山三百叠”而来，相传《千家诗》曾经过谢枋得的编订，喜欢苏轼诗作的他，极有可能特地将这首诗推荐在《千家诗》的选本中。　还有一个感觉就是，这首诗太像苏轼的风格了，我们可以拣出苏轼另一首家喻户晓的诗来比较一下：“若言琴上有琴声，放在匣中何不鸣？若言声在指头上，何不于君指上听？”和这首诗中呼童扫花影的“天真”举动如出一辙，同样也是在貌似无理、貌似调侃的语气中隐喻了发人深思的道理。　苏轼的诗有诙谐、灵动的特点，有时充满童趣，语言也颇有几分“打油诗”的特色。他曾说：“吾虽不善书，晓书莫如我。苟能通其意，常谓不学可。”对自己刚出生的儿子说：“人皆养子望聪明，我被聪明误一生。惟愿孩儿愚且鲁，无灾无难到公卿。”　苏轼这个人才华横溢，他的诗风格往往出奇出新，并非用“豪放”两字就能一概而论。他自己曾说过这样两句话：“出新意于法度之中，寄妙理于豪放之外。”（《书吴道子画后》）虽然这两句原本不是说他自己，但这里“请君入瓮”，将此语拿来形容东坡先生的诗，也十分恰当。　单说这首诗：有人说诗中的“花影”，是形容朝廷中当政的小人，难以驱去，赶不尽，除不绝。这样解诗不免呆板无味。如果真是形容小人，那苏轼的水平也太差劲了，“明月花影”，这是何等雅致的景物，用来形容小人，一点攻击力也没有。大家见骂人时，谁把对方骂成“花影”？像刘禹锡《聚蚊谣》，把小人形容为蚊子，罗隐把尸位素餐的昏官形容为木偶，这才叫讽刺。　那么此诗中的喻义又是什么呢？我觉得，此诗喻义深远，其中有着一种非常复杂的感情。常言道：“如影随形。”有形就有影，有因就有果，世间的种种琐事，正像花影一样萦绕在花前，挥不尽，抛不去，只要有日月轮回，只要还停留在这世上，你就躲不开、赶不走这永远跟着你的影子，不管你喜不喜欢它。　东坡喜欢禅，我觉得这首诗中颇有禅意。 ▲', poem_tags = '咏物,抒怀,失意,无奈' WHERE poem_title = '花影' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '青天上明月高悬起于何时？我现在停下酒杯且一问之。\n人追攀明月永远不能做到，月亮行走却与人紧紧相随。\n皎洁得如镜飞升照临宫阙，绿烟散尽发出清冷的光辉。\n只能看见每晚从海上升起，谁能知道早晨在云间隐没。\n月亮里白兔捣药自秋而春，嫦娥孤单地住着与谁为邻？\n现在的人见不到古时之月，现在的月却曾经照过古人。\n古人与今人如流水般流逝，共同看到的月亮都是如此。\n只希望对着酒杯放歌之时，月光能长久地照在金杯里。', poem_notes = '题下作者自注：故人贾淳令予问之。\n丹阙：朱红色的宫殿。绿烟：指遮蔽月光的浓重的云雾。\n但见：只看到。宁知：怎知。没（mò）：隐没。\n白兔捣药：神话传说月中有白兔捣仙药。西晋傅玄《拟天问》：“月中何有，白兔捣药”。嫦娥：神话中的月中女神。传说她原是后羿的妻子，偷吃了羿的仙药，成为仙人，奔入月中。见《淮南子·览冥训》。\n当歌对酒时：在唱歌饮酒的时候。曹操《短歌行》：“对酒当歌，人生几何？”金樽：精美的酒具。', poem_appreciation = '“把酒问月”这诗题就是作者绝妙的自我造象，那飘逸浪漫的风神唯谪仙人方能有之。题下原注：“故人贾淳令予问之。”彼不自问而令予问之，一种风流自赏之意溢于言表。\n\n　　悠悠万世，明月的存在对于人间是一个魅人的宇宙之谜。“青天有月来几时”的劈头一问，对那无限时空里的奇迹，大有神往与迷惑交驰之感。问句先出，继而具体写其人神往的情态。这情态从把酒“停杯”的动作见出。它使人感到那突如其来的一问分明带有几分醉意，从而倍有诗味。二句语序倒装，以一问摄起全篇，极富气势感。开篇从手持杯酒仰天问月写起，以下大抵两句换境换意，尽情咏月抒怀。 紧接二句“人攀明月不可得，月行却与人相随”意谓：明月高悬，欲攀不能，使人感到可望难即，莫测高远；可是不管夜间人们走到哪里，随时都得到月光的照拂，相与同行，如在身边，于是距离顿消。两句一冷一热，亦远亦近，若离若即，道是无情却有情。写出明月于人既可亲又神秘的奇妙感，人格化手法的运用维妙维肖。回文式句法颇具唱叹之致。再接下二句对月色作描绘：皎皎月轮如明镜飞升，下照宫阙，云翳（“绿烟”）散尽，清光焕发。以“飞镜”作譬，以“丹阙”陪衬俱好，而“绿烟灭尽”四字尤有点染之功。此处写出了一轮圆月初为云遮，然后揭开纱罩般露出娇面，那种光彩照人的美丽。月色之美被形容得如可揽接。不意下文又以一问将月的形象推远：“但见宵从海上来，宁知晓向云间没？”月出东海而消逝于西天，踪迹实难测知，偏能月月循环不已。“但见”“宁知”的呼应足传诗人的惊奇，他从而浮想联翩，究及那难以稽考的有关月亮的神话传说：月中白兔年复一年不辞辛劳地捣药，为的是什么？碧海青天夜夜独处的嫦娥，该是多么寂寞？语中对神物、仙女深怀同情，其间流露出诗人自己孤苦的情怀。这面对宇宙的遐想又引起一番人生哲理探求，从而感慨系之。今月古月实为一个，而今人古人则不断更迭。说“今人不见古时月”，亦意味“古人不见今时月”；说“今月曾经照古人”，亦意味“古月依然照今人”。故二句造语备极重复、错综、回环之美，且有互文之妙。古人今人何止恒河沙数，只如逝水，然而他们见到的明月则亘古如斯。后二句在前二句基础上进一步把明月长在而人生短暂之意渲染得淋漓尽致。前二句分说，后二句总括，诗情哲理并茂，读来意味深长，回肠荡气。最后二句则结穴到及时行乐的主意上来。曹操诗云：“对酒当歌，人生几何？”此处略用其字面，流露出同一种人生感喟。末句“月光长照金樽里”，形象鲜明独特。从无常求”常“，意味隽永。至此，诗情海阔天空地驰骋一番后，又回到诗人手持的酒杯上来，完成了一个美的巡礼，使读者从这一形象回旋中获得极深的诗意感受。\n\n　　全诗感情饱满奔放，语言流畅自然，极富回环错综之美。诗人由酒写到月，又从月归到酒，用行云流水般的抒情方式，将明月与人生反复对照，在时间和空间的主观感受中，表达了对宇宙和人生哲理的深层思索。其立意上承屈原的《天问》，下启苏轼的《水调歌头·明月几时有》。情理并茂，富有很强的艺术感染力。', poem_tags = '咏物,月亮,抒怀,哲理' WHERE poem_title = '把酒问月·故人贾淳令予问之' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '遥望终南，北山秀丽，皑皑白雪，若浮云间。\n雪后初晴，林梢之间闪烁着夕阳余晖，晚时分，长安城内又添了几分积寒。', poem_notes = '终南：山名，在唐京城长安（今陕西西安）南面六十里处。余雪：指未融化之雪。《全唐诗》此诗题下有小字注：“有司试此题，咏赋四句即纳，或诘之，曰‘意尽’。”\n阴岭：北面的山岭，背向太阳，故曰阴。\n林表：林外，林梢。霁（jì）：雨、雪后天气转晴。', poem_appreciation = '此诗载于《全唐诗》卷一百三十一。下面是中国古典文学专家、陕西师范大学文学研究所所长霍松林先生对此诗的赏析。\n\n　　据《唐诗纪事》卷二十记载，这首诗是祖咏在长安应试时作的。按照规定，应该作成一首六韵十二句的五言排律，但他只写了这四句就交卷。有人问他为什么，他说：“意思已经完满了。”这真是无话即短，不必画蛇添足。\n\n　　题意是望终南余雪。从长安城中遥望终南山，所见的自然是它的“阴岭”（山北叫做“阴”）；而且，惟其“阴”，才有“馀雪”。“阴”字下得很确切。“秀”是望中所得的印象，既赞颂了终南山，又引出下句。“积雪浮云端”，就是“终南阴岭秀”的具体内容。这个“浮”字下得十分生动。自然，积雪不可能浮在云端。这是说：终南山的阴岭高出云端，积雪未化。云，总是流动的；而高出云端的积雪又在阳光照耀下寒光闪闪，正给人以“浮”的感觉。或许有的读者要说：“这里并没有提到阳光呀！”这里是没有提，但下句却作了补充。“林表明霁色”中的“霁色”，指的就是雨雪初晴时的阳光给“林表”涂上的色彩。同时，“积雪浮云端”一句写出了终南山高耸入云，表达了作者的凌云壮志。\n\n　　“明”字当然下得好，但“霁”字更重要。作者写的是从长安遥望终南余雪的情景。终南山距长安城南约六十华里，从长安城中遥望终南山，阴天固然看不清，就是在大晴天，一般看到的也是笼罩终南山的蒙蒙雾霭；只有在雨雪初晴之时，才能看清它的真面目。贾岛的《望山》诗里是这样写终南山的：“日日雨不断，愁杀望山人。天事不可长，劲风来如奔。阴霾一似扫，浩翠泻国门。长安百万家，家家张屏新。”久雨新晴，终南山翠色欲流，长安百万家，家家门前张开一面新崭崭的屏风，非常好看。唐时如此，现在仍如此，久住西安的人，都有这样的经验。所以，如果写从长安城中望终南馀雪而不用一个“霁”字，却说望见终南阴岭的馀雪如何如何，那就不是客观真实了。\n\n　　祖咏不仅用了“霁”，而且选择的是夕阳西下之时的“霁”。他说“林表明霁色”，而不说山脚、山腰或林下“明霁色”，这是很费推敲的。“林表”承“终南阴岭”而来，自然在终南高处。只有终南高处的林表才明霁色，表明西山已衔半边日，落日的余光平射过来，染红了林表，不用说也照亮了浮在云端的积雪。而结句的“暮”字，也已经呼之欲出了。\n\n　　前三句，写“望”中所见；末一句，写“望”中所感。俗谚有云：“下雪不冷消雪冷。”又云：“日暮天寒。”一场雪后，只有终南阴岭尚余积雪，其他地方的雪正在消融，吸收了大量的热，自然要寒一些；日暮之时，又比白天寒；望终南余雪，寒光闪耀，就令人更增寒意。做望终南余雪的题目，写到因望余雪而增加了寒冷的感觉，意思的确完满了，就不必死守清规戎律，再凑几句了。\n\n　　王士禛在《渔洋诗话》卷上里，把这首诗和陶潜的“倾耳无希声，在目皓已洁”、王维的“洒空深巷静，积素广庭宽”等并列，称为咏雪的“最佳”之作。诗中的霁色、阴岭等词烘托出了诗题中余字的精神。', poem_tags = '唐诗三百首,冬天,写景,写雪' WHERE poem_title = '终南望余雪' AND poem_author = '祖咏';
UPDATE edu_poem SET poem_translation = '山上有茂盛的扶苏，池里有美艳的荷花。没见到子都美男子啊，偏遇见你这个小狂徒。\n山上有挺拔的青松，池里有丛生的水荭。没见到子充好男儿啊，偏遇见你这个小狡童。', poem_notes = '扶苏：树木名。一说桑树。\n隰（xí席）：洼地。华：同“花”。\n子都：古代美男子。\n狂：狂妄的人。且（jū居）：助词。一说拙、钝也。\n桥：通“乔”，高大。\n游龙：水草名。即荭草、水荭、红蓼。\n子充：古代良人名。\n狡童：姣美的少年。', poem_appreciation = '全诗共二章，均借草木以起兴。“山有扶苏， 隰有荷华“；”山有乔松，隰有游龙“，描写的尽是山中的树，低谷的花，并未见一人。其实这并不是情侣约会的地点和景色的描写，因为在《诗经》中，“山有…...，隰有......”是常用的起兴句式，如《邶风·简兮》‘中有：“山有榛，隰有苓”，《唐风·山有枢》中有“山有枢，隰有榆”，“山有漆，隰有栗”等。这里就是一个典型的起兴，清代方玉润在《诗经原始》中说：“诗非兴会不能作，或因物以起兴，或因时而感兴，皆兴也”，即这里的兴只从语势或韵脚上引出下文，使诗篇的开头委婉含蓄，与后文的故事并不相关。\n\n　　“不见子都，乃见狂且”，这两句是赋，为女子的调笑之辞。“至于子都，天下莫不知其姣也”（《孟子·告子上》）。“子都”，似为传说中古代美男子名，这里泛指俊美的男子。有论者认为“都“姝”古本双声，都”为“姝”的假借。《说文解字》云：“姝，美也”，故子都就是子美。女子称所爱为“狂且”，与美男子“子都”对举，明明是双方相约而来，偏说对方非己所爱，心爱叫冤家，可见其性格的爽朗善谑。\n\n　　第二章是叠章，开头两句仍以草木起兴引起下文。“不见子充，乃见狡童”反复调侃，加强语势，感情也层层递进。“子充”泛指美男子。论者认为“充”，古韵在东部，姝”，古韵在区部，区东可以对转，“充”即“姝”的对转，故子充与子都实为同指。始为“子都”，此为“子充”，重章叠句，整饬中有变化，更显得错落有致。\n\n　　少女对心上人主动发起调笑戏谑，可以想象，被调侃的男子绝不会甘拜下风，当有回敬。妙语如珠，往来应答，场面应十分热烈，气氛也极为活跃，少男少女率真爽朗的性格及欢快健康的戏剧性场面，在这里得到了淋漓尽致的表现。', poem_tags = '诗经,爱情' WHERE poem_title = '国风·郑风·山有扶苏' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '美人儿卷起珠帘一直等待，一直坐着把双眉紧紧锁闭。\n只看见她泪痕湿满了两腮，不知道她是恨人还是恨己。', poem_notes = '“深坐”句：写失望时的表情。深坐，久久呆坐。蹙蛾眉：皱眉。', poem_appreciation = '语言平浅简易，情态缠绵凄凉，含蓄蕴藉，言短意长。“含蓄有古意”、“直接国风之遗”，在理解李白诗歌的时候应该注意这些。古代的“美人”不是一个普通的词，与现代的“美女”很不一样。《离骚》里的“香草美人”指贤臣明君；《诗经》中的美人指容德俱美的年轻女子，“有美一人，清扬婉兮”。“美人卷珠帘”是指品性容貌都美好的闺中女子，李白诗歌的“含蓄蕴藉”是指诗歌中主人公情韵的婉转，而非指寄托兴寓，所以说它“直接国风之遗”。\n\n　　“深坐颦蛾眉”，“深”的意思是有多层的。“庭院深深深几许，杨柳堆烟，幕帘无重数。”（欧阳修《蝶恋花》）女子所住的闺房在“幕帘无重数”的深院里，十分幽深，十分寂寞，这是第一层；“深”还有深情的意思，所谓“美人卷珠帘”，古人思念亲人，总要登高望远，那是男子的做法，女子“养在深闺人未识”，不能抛头露面，于是只好“卷珠帘”望着离人去的方向以寄托思念之情，期待离人回来，这是第二层；“深”的第三层意思便是“久”，指坐的时间很长了。颦是皱的意思，吴宫里的西施“颦”起来的样子比平日更加美丽，更加楚楚可怜，才有了东施的效颦。“颦蛾眉”更显出了“美人”之美。\n\n　　“但见泪痕湿”，因为思念太深了，情太深了，所以不知不觉就流下相思泪。“湿”字说明是暗暗地流泪，情不自禁地流泪。联系到第二句的“颦蛾眉”，比“才下眉头，又上心头”的怨情更重。\n\n　　“不知心恨谁”，明明是思念，是爱一个人，却偏偏用“恨”。女主人公的心底是有点抱怨，离人去外地太久了，害她一个人在这深院里忍受着孤单寂寞，离人却还不回来。但这种恨，其实就是一种爱。爱一个人，总是恨对方不能陪伴在身边。\n\n　　诗的前三句用赋，末尾用问句归结“怨情”。这里的赋是个动态的过程，首先是“卷珠帘”，然后“深坐”，再“颦蛾眉”，最后“泪痕湿”，行动可见，情态逼人。李白的这首诗写的就是一个意境，一个孤独的女子的思念之情。这样一个很平凡的情景，作者捕捉到了几个点，由这几个点勾出一幅简单的画面，同时又留下无限的遐想。随意的一个小细节，就可以泄露整个主题，可见诗人的洞察力。', poem_tags = '唐诗三百首,女子' WHERE poem_title = '怨情' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '庭院中有许许多多的杂树，却偏偏对梅花赞许感叹，请问你为何会如此？是因为它能在寒霜中开花，在寒露中结果实。那些只会在春风中摇荡，在春日里妩媚的，你一定会飘零在寒风中追逐，因为你徒有在寒霜中开花却没有耐寒的本质。', poem_notes = '中庭：庭院中。\n咨嗟：赞叹声。\n君：指“偏为梅咨嗟”的诗人。这句是假托杂树的问话：你为什么单单赞赏梅花？\n其：指梅。作花：开花。作实：结实。以下是诗人的回答。这二句是说梅花能在霜中开花，露中结实，不畏严寒。\n尔：指杂树。霜华：霜中的花。华，同“花”。这三句是说杂树只能在春风中摇曳，在春日下盛开，有的虽然也能在霜中开花，却又随寒风零落而没有耐寒的品质。', poem_tags = '古诗三百首,梅花,抒怀' WHERE poem_title = '梅花落' AND poem_author = '鲍照';
UPDATE edu_poem SET poem_translation = '秋风起，树叶飞，吴江的鲈鱼鲜又肥。离家三千里，想回未能回。\n思念家乡的愁和恨，怎么也压抑不住，只能向天悲叹！', poem_notes = '木叶：树叶。\n鲈鱼：即桂花鱼，古名银鲈、玉花鲈。体侧扁，巨口细鳞，身有桂花色纹，肉肥嫩鲜美。', poem_appreciation = '读唐宋诗词，常常会遇到“秋风鲈脍”、“莼羹鲈脍”（莼（纯）羹：即莼菜汤。莼，一种水生植物，叶椭圆，柔滑味美。鲈鱼脍（快）：即鲈鱼片）的典故，这典故就是出自张翰。张翰，字季鹰，西晋吴郡吴人，家住吴江（即吴淞江）、太湖间。其为人纵任不拘，时人比为阮籍，称之为“江东步兵”。他本无意于功名，竟也鬼使神差到洛阳做了几年官，自然觉着很不适应。其时“八王之乱”初起，齐王对他有笼络之意，他就更感到不可久留了，“见秋风起，乃思吴中菰菜、莼羹、鲈鱼脍，曰：‘人生贵得适志，何能羁宦数千里以要名爵乎！’遂命驾而归。”（《晋书》本传）这首诗当是思归时即兴吟成（此诗各本文字有异，此从最早著录本《岁华纪丽》）。\n\n　　“秋风起兮木叶飞”，出句即见其思情的发动。悲凉的秋风最易触动人们的节序之感和念远之情。从时间上说，秋往往意味着岁暮的到来，使人觉着时光的流逝、流年的虚度。从空间看，秋高气清，万木萧萧，视野一下空阔起来，不自觉中自有人在何方、家在何方之叹。《楚辞·湘夫人》有“袅袅兮秋风，洞庭波兮木叶下”的句子，自是此句之本；不过，作为张翰来说，也不一定是有意地仿效，实在是一种语言定势、心理定势。秋风一吹，使作者感到在洛阳羁留时间太久了；秋风一吹，又使作者想起往昔的乡居生活、家乡风物，第二句就自然接上了：“吴江水兮鲈正肥”。鲈鱼，是作者家乡的特产，味极鲜美，秋天又正是鱼肥的季节。“鲈正肥”着一“正”字，便与“秋风起”连上了，同时还流露了一种“正”当其时、迫不及待的心情。下两句就直抒其情了。“三千里兮家未归，恨难禁兮仰天悲。”《晋书》本传谓“数千里”，此言“三千里”，自是文句与诗句修辞的不同。“三”比“数”来得明确、爽口，同时它既可表确数，又可表虚数，而且往往指向多的方面，这“三千里”比“数千里”更能给人以距离遥远之感。下句的“恨”是思归不得之恨，这种恨想压也压不住，于是仰天悲叹。这里把他的思归之情表现得异常强烈。\n\n　　由前述背景可知，张翰的归乡既有放达情性的一面，又有惧祸避乱的一面，他“恨难禁兮仰天悲”，恐怕更多的还是出于后一方面考虑，时人谓其“知几”，到宋初王贽过吴江还写诗道：“吴江秋水灌平湖，水阔烟深恨有余。因想季鹰当日事，归来未必为莼鲈。”（《中吴纪闻》）但是，唐代以后更多的人还是从敝屣功名的角度来理解、赞扬张翰的行为，“秋风鲈脍”成了厌弃仕途、向往家园、向往自由自在生活的代名词，正如近人王文濡所言：“季鹰吴江鲈莼与渊明故园松菊，同斯意致。”（《古诗评注读本》）宋代在张翰家乡吴江垂虹桥旁还建有“三高祠”（纪念范蠡、张翰、陆龟蒙这三位“高人”）、鲈乡亭，往来题咏甚多，张翰的《思吴江歌》也广为人们传诵。古代知识分子中不得意者总是居多，其中不乏洁身自好、不愿蝇营狗苟之士，张翰其事、其诗正好表达了他们的心声。\n\n　　这首短歌似是最早的七言四句押同部平声韵的作品，虽然句句用韵，句句有“兮”，未脱楚歌格调，但毕竟是向后来的七绝体式前进了一步。', poem_tags = '古诗三百首,秋天,思归' WHERE poem_title = '思吴江歌' AND poem_author = '张翰';
UPDATE edu_poem SET poem_translation = '万里桥西边就是我的破草房，没几个人来访，百花潭与我相伴，随遇而安，这就是沧浪。和风轻轻拥着翠绿的竹子，秀美光洁，飘雨慢慢洗着粉红的荷花，阵阵清香。当了大官的朋友人一阔就变脸，早与我断的来往，长久饥饿的小儿子，小脸凄凉，让我愧疚而感伤。我这老骨头快要扔进沟里了，无官无钱只剩个狂放，自己大笑啊，当年的狂夫老了却更狂！我就这么狂！', poem_notes = '万里桥：在成都南门外，是当年诸葛亮送费祎出使东吴的地方。杜甫的草堂就在万里桥的西面。\n百花潭：即浣花溪，杜甫草堂在其北。沧浪：指汉水支流沧浪江，古代以水清澈闻名。《孟子·离娄上》：“沧浪之水清兮，可以濯我缨。”有随遇而安之意。\n筱（xiǎo）：细小的竹子。娟娟净：秀美光洁之态。\n裛（yì）：滋润。红蕖：粉红色的荷花。冉冉香：阵阵清香。\n厚禄故人：指做大官在朋友。书断绝：断了书信来往。\n恒饥：长时间挨饿。\n填沟壑（hè）：把尸体扔到山沟里去。这里指穷困潦倒而死。疏放：疏远仕途，狂放不羁。', poem_tags = '写人,写景,抒情' WHERE poem_title = '狂夫' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_tags = '古诗三百首,边塞,思念' WHERE poem_title = '关山月' AND poem_author = '徐陵';
UPDATE edu_poem SET poem_translation = '译文 梅梅花初放，花萼中还含着白雪；梅花美丽孤傲，即使要入画，都会担心难画的传神。 花香中别有韵致，清雅的都不知道冬的寒冷。 梅花的枝干横斜错落，似愁似病， 北风如果能够理解梅花的心意，就请不要再摧残她了。 在孤寒中的梅花，坚韧顽强，傲然独立，潇洒的北风啊，请你放慢脚步，精心的呵护她吧！你忍心在如此严寒之中再摧残她吗？', poem_appreciation = '这首诗前四句描写了几枝一海花初绽乍放，洁白如雪。虽有孤高绝俗的神韵，但却不能淋漓尽致的表现于画中。她素雅高洁，不畏寒箱，淡淡的香气中蕴含着铮铮气韵。后四句重在抒情。笛声是最易引起人之愁思的.古人所谓‘’愁人不愿听，自到枕边来”，何况笛声中更有《梅花落》之曲，因而这横玉声中很容.易引’起人借花惆怅之情。诗人病躯独倚，在一片寒香混着笛声的景象中，诗人隐隐动了徘恻之心:北风如果理解我怜悔之意干万不要轻易予以摧残，让她多开些时间吧。“容易”这里作轻.易讲。“朔风”即北风，阮籍有诗云:“朔风厉严寒.阴气下微霜”。\n\n　　雪梅 诗人对北风的嘱托即是诗人爱花借花，恐其早谢心情的泄露。也许诗人带病观梅，笛声更易拨动他惜花的心弦吧。寒梅初开即恐其落.这里应隐含着诗人对人生的伤叹。', poem_tags = '咏物,梅花,抒怀' WHERE poem_title = '梅花' AND poem_author = '崔道融';
UPDATE edu_poem SET poem_translation = '墙：李商隐《代应》：“本来银汉是红墙，隔得卢家白玉堂。”\n星辰：李商隐《无题》“昨夜星辰昨夜风，画楼西畔桂堂东。”风露：高启《芦雁图》“沙阔水寒鱼不见，满身风露立多时。”\n思，丝。心，芯。皆双关语。李商隐《无题》“春蚕到死丝方尽，蜡炬成灰泪始干。”', poem_appreciation = '“绮”本意为“有 花纹的丝织品”，后来引申为“美丽”，“绮怀”自是一种美丽的情怀，对清代诗人黄景仁来说，这种美丽来自一种爱情失落无处寻觅的绝望，因而更加凄婉动人。\n\n　　黄景仁年轻时曾同 自己的表妹两情相悦，但故事却仅有一个温馨的开始和无言的结局。正因如此，在《绮怀》之中，笼罩着隐隐约约的感伤。这种感伤，被那种无法排解的甜蜜回忆和苦涩的现实纠缠着，使得诗人一步步地陷入绝望中。\n\n　　首联“几回花下坐 吹箫，银汉红墙入望遥”。明月相伴，花下吹箫，美好的相遇。但是这只是一个开始。那伊人所在的红墙虽然近在咫尺，却如天上的银汉一般遥遥而不可及。\n\n　　第二联“似此星辰 非昨夜，为谁风露立中宵”。这是最让人称道的一联，是的，今夜已非昨夜，昨夜的星辰，是记录着花下吹箫的浪漫故事，而今夜的星辰，却只有陪伴自已这个伤心之人。诗人是清醒的，他知道往事不可能重现，而正是因为这种清醒，才使他陷入了更深的绝望。\n\n　　在黄景仁的诗中， 所有虚幻的安慰全消失了，只有一个孤独的人依旧保持着一种望月的姿势，思念的姿势。试想，诗人独立中庭，久久望月，一任夜晚的冷露打湿了自已的衣裳，打湿了自已的心灵。而这种等待的尽头却只能是一片虚无，这种思念的幻灭以及明明知道思念幻灭却仍然不能不思念的心态，正是最为绝望的一种心态。　第三联“缠绵思尽 抽残茧，宛转心伤剥后蕉”。这句可以和李商隐的《无题》诗“春蚕到死丝方尽，蜡炬成灰泪始干”相媲美。春蚕吐丝，将自已重重包裹，正如诗人自己，用重重思念将自己重重包围。春蚕吐丝尽头是茧，是死，红烛流泪的尽头是灰，是死。而死，自然是人世间最为绝望的结局了。“芭蕉”也是幽怨的意象，李商隐《代赠》诗有“芭蕉不展丁香结，同向春风各自愁”句。\n\n　　尾联“三五年时三 五月，可怜杯酒不曾消”。尾联同首联呼应，三五年时三五之月，自然是“几回花下坐吹箫”的往昔，而那时的美酒在今夜早已被酿成苦涩的酒。而这种苦涩是永远也无法消除的。因为，诗人无法不想念，也就无法同往昔和现实的夹缝之中突围出来。法国著名诗人缪塞说：“最美丽的诗歌也是最绝望的诗歌，有些不朽的篇章是纯粹的眼泪。”黄景仁的七言律诗《绮怀十六首之十五》，也正是因为这种绝望而更有了魅力。', poem_tags = '爱情,孤独,思念' WHERE poem_title = '绮怀' AND poem_author = '黄景仁';
UPDATE edu_poem SET poem_translation = '昨天的夜晚，风雨交加， 遮窗的帐子被秋风吹出飒飒的声响，窗户外传来了令人心烦的风声雨声，整整响了一夜。蜡烛燃烧的所剩无几，壶中水已漏尽，我不停的多次起来斜靠在枕头上。 躺下坐起来思绪都不能够平稳。\n人世间的事情，如同流水东逝，说过去就过去了，想一想我这一生，就像做了一场大梦，以前的荣华富贵生活已一去不复返了。醉乡道路平坦，也无忧愁，可常去，别的地方不能去。', poem_notes = '兼：同有，还有。\n帘帏（wéi）：帘子和帐子。帘，用布、竹、苇等做的遮蔽门窗的东西。帏，同帷，帐子，幔幕，一般用纱、布制成。\n飒飒（sà）：象声词，这里形容风吹帘帏发出的声音。\n烛残：蜡烛燃烧将尽。残，尽，竭。\n漏断：漏壶中的水已经滴尽，表示时间已经很晚。漏，漏壶，为古代计时的器具，用铜制成。壶上下分好几层，上层底有小孔，可以滴水，层层下注，以底层蓄水多少计算时问。\n频：时常，频繁。\n欹（qī）枕：通彀，斜，倾斜。欹枕，头斜靠在枕头上。\n平：指内心平静。\n世事：指人世间的各种各样的事情。\n漫：枉然，徒然。\n浮生：指人生短促，世事虚浮不定。浮，这里为短暂、空虚之意。\n醉乡：指人醉酒时神志不清的状态。\n稳：平稳，稳当。宜，应当。\n不堪行：不能行。堪，能够。', poem_appreciation = '词的上片，主要写作者的凄苦境遇和无奈情态。“昨夜风兼雨”，不从日而偏从夜写起，是写作者悲怀愁思的夜不能寐，“风兼雨”与“飒飒秋声”相对应，是渲染环境、气氛。在这种凄凉寒苦的景色中，作者的心境是可想而知的。之所以说“昨夜”，当还有一种不堪回首的感触在其中罢。这里虽然客观的写景，但主人公的形象，尤其是他的彷徨、郁闷的心情却已隐然可见。接下来二句就是直写了。李煜在《喜迁莺·晓月坠》中曾有“无语枕频欹”之句，与此句“烛残漏断频欹枕”用意相同，但所思不同。以前是怀想佳人，君存情爱在先，如今却是是国破家亡成阶下之囚，境遇不同，感触自是相异，于是看“烛残”、听“漏断”，虽然仍是“无语”，但却已是“起坐不能平”了。“不能平”的不是身体，而是心境，这一次是连梦都没有了。上片虽似写景为主，描摹情状，但事实上作者那种愁思如潮、郁抑满怀的心情却已淋漓尽致地表现出来，深沉而又挚切。\n\n　　词的下片以抒情为主，抒发作者的切肤之痛和人生感慨。这既是“起坐不能平”的原因，也是“起坐不能平”中思前想后的结论。“世事漫随流水，算来梦里浮生”，昨日一国之君，今日阶下之囚；昨夜欢歌笑语，今夜“烛残漏断”，明日明夜呢？作者的苦痛遭遇，不能不使他有人生如梦的感慨和浩叹。一个“漫”字，极空虚，极幻妄，准确地传达了作者的万千思绪。一个“算来”，既说明作者是总结回顾了自己的过去得出的结论，但同时也传达出作者的那种十分迷惘、无奈的心情，同“漫”字一样地生动、传神。作者的这种慨叹是沉痛的，但同时也是消极的，于是作者宁愿醉去不醒，宁愿迷迷糊糊，“醉乡路稳宜频到”，原来作者指望的是一个“稳”字，一语道破天机，作者处境的危险困苦不言自明。所以我们并不能从这个角度太过严厉地去批评李煜的颓废消极思想，环境使然，差可理解。更何况即便如此，李煜也仍是难逃恶运，不久于世。\n\n　　全词比较鲜明地体现了李煜后期作品的特色：情感真实，清新自然。尤其是这首词，作者对自己的苦痛毫不掩饰，把自己的人生感慨明白写出，不假饰，不矫情，简洁质朴，有现实感，虽然思想情调不高，但艺术价值不低。', poem_tags = '宋词三百首,写风,写雨,抒情,人生' WHERE poem_title = '乌夜啼·昨夜风兼雨' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '春风吹起柳絮，酒店满屋飘香，侍女捧出美酒，劝我细细品尝。\n金陵年轻朋友，纷纷赶来相送。欲走还留之间，各自畅饮悲欢。\n请你问问东流江水，别情与流水，哪个更为长远？', poem_notes = '金陵：今江苏省南京市。酒肆：酒店。留别：临别留诗给送行者。\n风吹：一作“白门”。\n吴姬：吴地的青年女子，这里指酒店中的侍女。压酒：压糟取酒。古时新酒酿熟，临饮时方压糟取用。唤：一作“劝”，一作“使”。\n子弟：指李白的朋友。\n欲行：将要走的人，指诗人自己。不行：不走的人，即送行的人，指金陵子弟。尽觞（shāng）：喝尽杯中的酒。觞，酒杯。\n试问：一作“问取”', poem_appreciation = '柳絮飘飞的时节，江南水村山郭的一家小酒店里，即将离开金陵的诗人，满怀别绪。骀荡的春风，卷起了垂垂欲下的杨花，轻飞乱舞，扑满店中；当垆的姑娘，捧出新压榨出来的美酒，劝客品尝。这里，柳絮濛濛，酒香郁郁，扑鼻而来，也不知是酒香，还是花香。这么一幅令人陶醉的春光春色的画面，该用许多笔墨来表现。此诗只“风吹柳花满店香”七字，就将风光的骀荡，柳絮的精神，以及酒客沉醉东风的情调，生动自然地浮现在纸面之上；而且又极洒脱超逸，不费半分气力，脱口而出，纯任直观，于此，充分显示了李白的才华。\n\n　　“风吹柳花满店香，吴姬压酒劝客尝。”\n\n　　和风吹着柳絮，酒店里溢满芳香；吴姬捧出新压的美酒，劝客品尝。“金陵”，点明地属江南，“柳花”，说明时当暮春。这是柳烟迷蒙、春风沉醉的江南三月，诗人一走进店里，沁人心脾的香气就扑面而来。这一“香”字，把店内店外连成一片。金陵古属吴地，遂称当地女子为“吴姬”，这里指酒家女。她满面春风，一边压酒（即压酒糟取酒汁），一边笑语殷勤地招呼客人。置身其间，真是如沐春风，令人陶醉，让人迷恋。\n\n　　这两句写出了浓浓的江南味道，虽然未明写店外，而店外“杂花生树，群莺乱飞”，杨柳含烟的芳菲世界，已依稀可见。此时，无论是诗人还是读者，视觉、嗅觉、听觉全都调动起来了。\n\n　　“柳花”，即柳絮，本来无所谓香，但一些诗人却闻到了，如传奇“莫唱踏阳春，令人离肠结。郎行久不归，柳自飘香雪。”“香”字的使用，一则表明任何草木都有它微妙的香味，二则这个“香”字代表了春之气息，这不但活画出一种诗歌意境，而且为下文的酒香埋下伏笔。其实，对“满店香”的理解完全不必拘泥于“其柳花之香”，那当是春风吹来的花香，是泥土草木的清香，是美酒飘香，大概还有“心香”，所谓心清闻妙香。这里的“店”，初看不知何店，凭仗下句始明了是指酒店。实在也唯有酒店中的柳花才会香，不然即使是最雅致的古玩书肆，在情景的协调上，恐怕也还当不起“风吹柳花满店香”这七个字。所以这个“香”字初看似觉突兀，细味却又感到是那么妥贴。\n\n　　“金陵子弟来相送，欲行不行各尽觞。”\n\n　　金陵的一群年轻人来到这里，为诗人送行。饯行的酒啊，你斟我敬，将要走的和不走的，个个干杯畅饮。也有人认为，这是说相送者殷勤劝酒，不忍遽别；告别者要走又不想走，无限留恋，故“欲行不行”。\n\n　　李白此行是去扬州。他后来在《上安州裴长史书》说：“曩昔东游维扬，不逾一年，散金三十余万，有落魄公子，悉皆济之。此则白之轻财好施也。”李白性格豪爽，喜好交游，当时既年轻富有，又仗义疏财，朋友自是不少。在金陵时也当如此。一帮朋友喝酒，话别，少年刚肠，兴致盎然，没有伤别之意，这也很符合年轻人的特点。“尽觞”，意思是喝干杯中酒。“觞”，酒器。\n\n　　“请君试问东流水，别意与之谁短长？”\n\n　　金陵一行，诗人是快乐的。在这样一个美好的时节，一个让人留恋的地方，诗人却要走了。面对美丽的江南风物和朋友们的盛情挽留，诗人依依不舍，他在想：怎样才能表达自己的无限惜别之情呢？也许饯别的酒店正面对大江，诗人顺手一指，以水为喻：“请你们问问那东流的江水，离情别意与它相比究竟谁短谁长？”\n\n　　情感是抽象的，即使再深再浓，也看不见摸不着；而江水是形象的，给人的印象是绵绵不绝。但诗人不是简单的相喻，而是设问比较，迷迷茫茫地，似收而未收住，言有尽而意无穷，给人以想象的空间。采用这种表现手法，李白可能受到前人的启发，如谢朓就写过“大江流日夜，客心悲未央”，但李白写得更加生动自然。与“桃花潭水深千尺，不及汪伦送我情”有异曲同工之妙。\n\n　　此诗构思巧妙。首句”风吹柳花满店香“，是阒无一人的境界，第二句”吴姬压酒劝客尝“，当垆红粉遇到了酒客，场面上就出现人了，等到“金陵子弟”这批少年一涌而至时，酒店中就更热闹了。别离之际，本来未必有心饮酒，而吴姬一劝，何等有情，加上“金陵子弟”的前来，更觉情长，谁也不愿舍此而去。可是偏偏要去，“来相送”三字一折，直是在上面热闹场面上泼了一盆冷水，点出了从来热闹繁华就是冷寂寥落的前奏。李白要离开金陵了。但是，如此热辣辣的诀舍，总不能跨开大步就走吧。于是又转为“欲行不行各尽觞”，欲行的诗人固陶然欲醉，而不行的相送者也各尽觞，情意如此之长，于是落出了“请君试问东流水，别意与之谁短长”的结句，以含蓄的笔法，悠然无尽地结束了这一首抒情的短歌。\n\n　　很多人写离别，大多少不了言愁，所谓“离愁别绪”。然而，李白这首诗中连一点愁的影子都不见，只有别意。诗人正值青春华茂，他留别的不是一两个知己，而是一群青年朋友。这种惜别之情在他写来，饱满酣畅，悠扬跌宕，唱叹而不哀伤，富于青春豪迈、风流潇洒的情怀。', poem_tags = '唐诗三百首,离别,饮酒' WHERE poem_title = '金陵酒肆留别' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '青色的烟云，遮住了月影，从碧海般的晴空里飞出一轮金灿灿的明镜。长夜的空阶上卧着挂树的斜影。夜露渐凉之时，多少秋蝉零乱地嗓鸣。思念京都路远，论路近唯有月宫仙境。\n高卷水晶帘儿，展开云母屏风，美人的淡淡脂粉浸润了夜月的清冷。待我许多月色澄辉，倾入金樽，直到拂晓连同流霞全都倾尽。再携带一张胡床登上南楼，看白玉铺成的人间，领略素白澄洁的千顷清秋。', poem_notes = '泗州：今安徽省泗县。\n幂（mì）：烟雾弥漫貌。\n永：长，兼指时间或空间。\n寒螀（jiāng）：即寒蝉，体小，秋出而鸣。\n神京：指北宋京城汴梁。\n蓝桥：谓秀才裴航于蓝桥会仙女云英事。唐裴铏《传奇·裴航》云：长庆中，有秀才裴航，行于湘汉。同行樊夫人，国色天姿，航欲求之，夫人与诗曰：“一饮琼浆百感生，玄霜捣尽见云英。蓝桥便是神仙宫，何必崎岖上玉清。”后经蓝桥驿侧近，因渴甚，遂下道求浆而饮，会云英，以玉杵臼为礼，结为连理。方知云英为仙女、樊夫人则云英之姐也。蓝桥，今陕西省蓝田县西南蓝溪之上，故名。\n云母屏：云母为花岗岩主要成分，可作屏风，艳丽光泽。\n佳人：这里指席间的女性。\n流霞：本天上云霞，语意双关，借指美酒。《太平广记》引《抱朴子·须曼卿》曰：蒲坂有须曼卿者曰：“在山中三年精思，有仙人来迎我，乘龙升天。龙行甚疾，头昂尾低，令人在上危怖。及到天上，先过紫府，金床玉几，晃晃昱昱，真贵处也。仙人以流霞一杯饮我，辄不饥渴。忽然思家，天帝前谒拜失仪，见斥来还。令更自修责，乃可更往。昔淮南王刘安，升天见上帝，而箕坐大言，自称寡人，遂见谪，守天厕三年。吾何人哉？”河东因号曼卿为“斥仙人”。\n胡床：古代一种轻便坐具，可以折叠。', poem_appreciation = '此词通篇都写赏月。上片开头写词人仰望浩月初升情景。首二句化用李白诗中“皎如飞镜临丹阙，绿烟灭尽清辉发”句意，“青烟”指遮蔽月光的云影。夜空像茫茫碧海，无边无际；一轮明月穿过云层，像一面金镜飞上碧空，金色的光辉照亮了天上人间。“飞”字写乍见月之突然升起，使人感到似是何处飞来，充满惊异欣喜之情。“永夜”三句，通过永夜、闲阶、凉露、寒蝉等物象，极写月夜的静寂清冷，描绘出一幅充满凉意的，悠长寂寞的中秋月夜图，烘托出词人的孤寂心境和万千感慨，流露出词人对美好月色的珍惜眷恋。\n\n　　以下两句，写因望月而生的身世感慨。词中引用，以蓝桥神仙窟代指蟾宫月窟。这两句意思是说，京城邈远难至，倒是这一轮明月，与人为伴，对人更加亲近。作者为苏门四学士之一，曾三次任京官，后面两次都是因牵连党争而去职，被贬外郡；作此词前不久词人虽得脱出党籍，起任泗州知州，但朝中已无知音。“神京远”的“远”，主要是从政治的含意说的。\n\n　　上面这几句赞美眷恋中透出了几分凄清。这时作者已五十八岁，前次去官回家，就已修葺归来园隐居，自号“归来子”，忘情仕进，此词对仕途坎坷，也仅微露怅恨而已，全词的主调，仍然是旷达豪放的。两句明白点出孤寂心情，意脉紧接上文，而扬景则由环境景物转到望月抒怀。\n\n　　下片转写室内宴饮赏月。卷帘、开屏，都是为使月光遍满，为下文“付与金尊”预作地步，表现了对明月的极端爱悦。“淡指粉”的“淡”字也与月光极协调。水晶做成的帘子高高卷起，云母屏风已经打开，明月的冷光照入室内，宛如浸润着佳人的淡淡脂粉。筵上的人频频举怀，饮酒赏月，似乎要把明月的清辉全部纳入金尊之中，待天晓时同着流霞，一道饮尽。\n\n　　这里把月下筵面的高雅素美，赏月兴致的无比浓厚，都写到极致。月光本来无形。作者却赋予它形体，要把它“付与金尊”，真奇思妙想也。天晓时分，月尚未落，朝霞已生；将二者同时倾尽，意思是说赏月饮酒，打算直到月落霞消方罢。\n\n　　结尾写登楼赏月，由室内转到室外。夜更深，月更明，虽然夜深露冷，作者赏月的兴致不但没有衰减，反而更加豪壮。这时他想起《世说新语·容止》记载的一个故事：晋庾亮武昌，尝秋夜与诸佐吏殷浩之徒南楼赏月，据胡床咏谑。作者觉得庭中赏月不能尽兴，所以要象庾亮那样登上南楼，去观赏那月光下如白玉做成的人无际素白澄澈的清秋气象。古代五行说以秋配金，其色白，故称秋天为素秋。用“玉做人间”比喻月光普照大地，可谓奇想自外飞来。它既写月色，也暗含希望人间消除黑暗和污浊，像如玉的明月一般美好之意。“看玉做人间，素秋千顷”作豪放之语，两句包举八荒，丽而且壮，使通篇为之增色。\n\n　　全词从天上到人间，又从人间到天上，天上人间浑然一体，境界阔大，想象丰富，词气雄放，与东坡词颇有相似之处。全词以月起，以月结，首尾呼应，浑然天成。篇中明写、暗写相结合，将月之色、光、形、神，人对月之怜爱迷恋，写得极为生动入微。', poem_tags = '中秋节,豪放,赏月,抒怀' WHERE poem_title = '洞仙歌·泗州中秋作' AND poem_author = '晁补之';
UPDATE edu_poem SET poem_translation = '译文 　　青春的日子容易逝去，学问却很难成功，所以每一寸光阴都要珍惜，不能轻易放过。还没从美丽的春色中一梦醒来，台阶前的梧桐树叶就已经在秋风里沙沙作响了。', poem_tags = '秋天,写景,感叹,惜时,早教古诗100首' WHERE poem_title = '偶成' AND poem_author = '朱熹';
UPDATE edu_poem SET poem_translation = '骚：指在文学上有成就的“才人”的崇高地位和深远的影响。\n\n　　在中国文学史上，“风骚”是代表《诗经》的《国风》和代表楚辞的《离骚》的并称。而“风骚”传统则是在《诗经》和《楚辞》的影响下发展形成的我国古代诗歌的两种优良传统，即代表《诗经》的《国风》所形成的“风”诗传统和代表《楚辞》的《离骚》所形成的“骚”诗传统。\n\n　　所谓的“风”诗传统，就是世代相传的现实主义的精神。现实主义的基本原则是按照生活的实际样式再现生活，并通过对生活真实的、具体的、形象的描写，表达作者的思想情感，反映社会生活的本质或本质的某些方面。《国风》中的民歌和二雅中的卿士大夫政治讽喻诗就集中体现了这种现实主义的精神。在内容上，它们正视现实、描写现实、揭露现实、批判现实；在艺术表现手法上，它们善于用朴素的文风、简洁的语言、巧妙的比兴，塑造出真实、自然而生动的形象，描绘出亲切感人的生活画面，来抒发情怀，反映现实。而这也就是“风”诗传统，即现实主义诗歌传统的主要特征。后世文学中继承发展了“风”诗传统的现实主义精神的主要有：两汉乐府民歌、建安曹魏时代的文人诗歌、北朝民歌、唐代杜甫的“诗史”作品、中唐白居易倡导的“新乐府运动”、宋代以王禹偁作品为代表的“白居易体”诗歌、金元之际元好问的诗歌等。元代关汉卿的杂剧、清代曹雪芹的小说《红楼梦》虽然不是诗歌，但是也继承了现实主义文学的优良传统。\n\n　　所谓的“骚”诗传统则是充满激情和幻想的积极浪漫主义的创作方法。积极浪漫主义的原则是“力图加强人的生活意志，在他的心中唤起他对现实和现实的一切压迫的反抗”。诗人屈原的长篇政治抒情诗《离骚》集中地体现了这种积极浪漫主义的创作精神。这表现在《离骚》的思想内容和艺术手法两方面。在内容上，《离骚》表现了屈原的进步理想以及他对进步理想九死不悔的孜孜追求。这是积极浪漫主义的本质。在艺术手法上，屈原一方面采用丰富的神话素材，通过自由的幻想，来构成一个奇特的神话世界，借此表现诗人内心的矛盾冲突和上天入地地求索以及始终不渝的爱国之情；另一方面还礼利用发展了民歌的比兴手法创作了一个“香草美人”的世界以此来象征他与楚国腐朽黑暗势力的斗争是真善美与假恶丑之间的斗争。《离骚》这种在现实生活的基础上，以丰富的幻想和热情，表现作者对进步理想的执着追求的特征，也就是“骚”诗传统，即积极浪漫主义的文学传统的主要特征。这种积极浪漫主义的文学传统也在后世薪火相传，汉代的辞赋家贾谊、建安时代的曹植、正始时期的阮籍、两晋六朝时的左思、鲍照、盛唐的李白、中唐的李贺以至宋代以苏轼、辛弃疾为代表的豪放词派、明清的小说家吴承恩、蒲松龄，都在一定程度上继承发展了这一优良传统。\n\n　　这里指在文学上有成就的“才人”的崇高地位和深远的影响。▲', poem_tags = '古诗三百首,初中古诗,励志,哲理,写人' WHERE poem_title = '论诗五首·其二' AND poem_author = '赵翼';
UPDATE edu_poem SET poem_translation = '虽说是百花凋落，暮春时节的西湖依然是美的，残花轻盈飘落，点点残红在纷杂的枝叶间分外醒目；柳絮时而飘浮，时而飞旋，舞弄得迷迷蒙蒙；杨柳向下垂落，纵横交错，在和风中随风飘荡，摇曳多姿，在和煦的春风中，怡然自得，整日轻拂着湖水。\n游人尽兴散去，笙箫歌声也渐渐静息，才开始觉得一片空寂，又仿佛正需要这份安谧。回到居室，拉起窗帘，等待着燕子的来临，只见双燕从蒙蒙细雨中归来，这才拉起了帘子。', poem_notes = '群芳过后：百花凋零之后。群芳，百花。西湖：指颍州西湖，在今安徽阜阳西北，颖水和诸水汇流处，风景佳胜。\n狼籍残红：残花纵横散乱的样子。残红，落花。狼籍，同“狼藉”，散乱的样子。\n濛濛：今写作“蒙蒙”。细雨迷蒙的样子，以此形容飞扬的柳絮。\n阑干：横斜，纵横交错。\n笙歌：笙管伴奏的歌筵。散：消失，此指曲乐声停止。去：离开，离去。\n帘栊：窗帘和窗棂，泛指门窗的帘子。', poem_appreciation = '这首词，上片描绘载酒游湖时船中丝竹齐奏、酒杯频传的热闹气氛。下片写酒后醉眠船上，俯视湖中，但见行云在船下浮动，使人疑惑湖中别有天地。整首词寓情于景，写出了作者与友人的洒脱情怀。下片写醉后俯视湖水，只见白云朵朵，飘于船下。船在移动，云也在移动，似乎人和船在天上飘飞。“空水澄鲜”一句，本于谢灵运《登江中孤屿》诗“云日相晖映，空水共澄鲜”，言天空与湖水同是澄清明净。这一句是下片的关键。兼写“空”、 “ 水”，绾合上句的“云”与“舟”。下两句的 “俯”与“仰”、“湖”与“天”，四照玲珑，笔意俱妙，虽借用成句，而恰切现景，妥贴自然，如同己出。“俯仰留连”四字，又是承上启下过渡之笔。从水中看到蓝天白云的倒影，他一会儿举头望天，一会儿俯首看水，被这空阔奇妙的景象所陶醉，于是怀疑湖中别有一个天宇在，而自己行舟在两层天空之间。 “疑是湖中别有天”，用“疑是”语，是就其形貌来说。说“疑”者非真，说“是”者诚是，“湖中别有天”的体会，自出心裁，给人以活泼清新之感。\n\n　　“残霞夕照”是天将晚而未晚、日已落而尚未落尽的时候。“夕阳无限好”，古往今来不知有多少诗人歌咏过这一转瞬即逝的黄金时刻。欧阳修没有直写景物的美，而是说“霞”已“残”，可见已没有“熔金”、“合璧”那样绚丽的色彩了。但这时的西湖，作者却觉得“好”。好就好在“花坞苹汀”。在残霞夕照下所看到的是种在花池里的花，长在水边或小洲上的苹草，无一字道及情，但情却寓于景中了。“十顷波平 ”，正是欧阳修在另一首《 采桑子》里写的“无风水面琉璃滑”。波平如镜，而且这“镜面”浩渺无边。“野岸无人舟自横”，这句出自韦应物《滁州西涧 》诗“ 野渡无人舟自横”。作者改“渡”为“岸”，说明“舟自横”是由于当日的游湖活动结束了，因此这“无人”而“自横”的“舟”，就更衬托出了此刻“野岸”的幽静沉寂。\n\n　　“西南月上”，残霞夕照已经消失。月自西南方现出，因为不是满月，所以虽在“浮云散”之后，这月色也不会十分皎洁。这种色调与前面的淡素画图和谐融洽，见出作者用笔之细。“轩槛凉生”，这是人的感觉。直到这时才隐隐映现出人物来。至此可知，上片种种景物，都是在这“轩槛”中人的目之所见，显然他在这里已经有好长一段时间了。这里，作者以动写静，一切都是静悄悄的，一点声音也没有，使人们仿佛置身红尘之外。\n\n　　“莲芰香清，水面风来酒面醒。”“水面风来”，既送来莲香 ，也吹醒了人的醉意。原来他喝醉了酒，就这么长时间地悄无声息地沉浸在“西湖好”的美景中。这位颍州西湖的“旧主人”怀着无限深情，谱出了一曲清歌。\n\n　　欧公在此词中借啸傲湖山而试图忘记仕途的坎坷不平，表达了视富贵如浮云的情趣。词中用语平实却极有表现力。', poem_tags = '婉约,写景,写水,西湖,抒情,旷达' WHERE poem_title = '采桑子·群芳过后西湖好' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '落日中卷起绣帘眺望，亭下江水与碧空相接，远处的夕阳与亭台相映，空阔无际。为了我的来到，你特意在窗户上涂上了清油的朱漆，色彩犹新。这让我想起当年在平山堂的时候，靠着枕席，欣赏江南的烟雨，遥望远方天际孤鸿出没的情景。今天看到眼前的景象，我方体会到欧阳醉翁词句中所描绘的，山色若隐若现的景致。\n广阔的水面十分明净，山峰翠绿的影子倒映其中。忽然江面波涛汹涌，一个渔翁驾着小舟在风浪中掀舞。见此不由得想起了宋玉的《风赋》，像宋玉这样可笑的人，是不可能理解庄子的风是天籁之说的，硬说什么风有雄雌。其实，一个人只要具备至大至刚的浩然之气，就能在任何境遇中都处之泰然，享受到无穷快意的千里雄风。', poem_notes = '水调歌头：词牌名，又名“元会曲”“台城游”“凯歌”“江南好”“花犯念奴”等。双调，九十五字，平韵（宋代也有用仄声韵和平仄混用的）。相传隋炀帝开汴河自制《水调歌》，唐人演为大曲， “歌头”就是大曲中的开头部分。快哉亭：苏辙《黄州快哉亭记》：“清河张君梦得，谪居齐安，即其庐之西南为亭，以览观江流之胜，而余兄子瞻名之曰‘快哉’。”\n湿青红：谓漆色鲜润。\n平山堂：宋仁宗庆历八年（1048年）欧阳修在扬州所建。\n欹枕：谓卧着可以看望。\n醉翁：欧阳修别号。\n“山色”句：出自欧阳修《朝中措·平山栏槛倚晴空》。\n倒碧峰：碧峰倒影水中。\n一叶：指小舟。白头翁：指老船夫。\n庄生：战国时道家学者庄周。天籁：是发于自然的音响，即指风吹声。\n刚道：“硬说”的意思。\n一点”两句：谓胸中有“浩然之气”，就会感受“快哉此风”。', poem_appreciation = '这首词又名《快哉亭作》，是苏轼豪放词的代表作之一。全词通过描绘快哉亭周围壮阔的山光水色，抒发了作者旷达豪迈的处世精神。\n\n　　此词描写的对象，主要是“快哉亭”周围的广阔景象。开头四句，先用实笔，描绘亭下江水与碧空相接、远处夕阳与亭台相映的优美图景，展现出一片空阔无际的境界，充满了苍茫阔远的情致。“知君为我新作”两句，交待新亭的创建，点明亭主和自己的密切关系，反客为主、诙谐风趣地把张偓佺所建的快哉亭说成特意为自己而造，又写亭台窗户涂抹上青红两色油漆，色彩犹新。“湿”字形容油漆未干，颇为传神。\n\n　　“长记平山堂上”五句，是记忆中情景，又是对眼前景象的一种以虚托实的想象式侧面描写。作者用“长记”二字，唤起他曾在扬州平山堂所领略的“江南烟雨”“杳杳没孤鸿”那种若隐若现、若有若无、高远空蒙的江南山色的美好回忆。他又以此比拟他在“快哉亭”上所目睹的景致，将“快哉亭”与“平山堂”融为一体，构成一种优美独特的意境。这种以忆景写景的笔法，不但平添了曲折蕴藉的情致，而且加强了词境的空灵飞动。以上五句新颖别致，引人入胜，通过作者昔日的淋漓兴致，传达出当日快哉亭前览胜的欣喜之情。\n\n　　上片是用虚实结合的笔法，描写快哉亭下及其远处的胜景。下片换头以下五句，又用高超的艺术手法展现亭前广阔江面倏忽变化、涛澜汹涌、风云开阖、动心骇目的壮观场面。词人并由此生发开来，抒发其江湖豪兴和人生追求。“一千顷，都镜净，倒碧峰”三句，写眼前广阔明净的江面，清澈见底，碧绿的山峰，倒映江水中，形成了一幅优美动人的平静的山水画卷，这是对水色山光的静态描写。“忽然”两句，写一阵巨风，江面倏忽变化，涛澜汹涌，风云开阖，一个渔翁驾着一叶小舟，在狂风巨浪中掀舞。至此，作者的描写奇峰突起，由静境忽变动境，从而自自然然地过渡到全词着意表现的着重点——一位奋力搏击风涛的白发老翁。这位白头翁的形象，其实是东坡自身人格风貌的一种象征。以下几句，作者由风波浪尖上弄舟的老人，自然引出他对战国时楚国兰台令宋玉所作《风赋》的议论。作者看来，宋玉将风分为“大王之雄风”和“庶人之雌风”是十分可笑的，是未解自然之理的生硬说教，白头翁搏击风浪的壮伟风神即是明证。其实，庄子所言天籁本身绝无贵贱之分，关键于人的精神境界的高下。他以“一点浩然气，千里快哉风”这一豪气干云的惊世骇俗之语昭告世人：一个人只要具备了至大至刚的浩然之气，就能超凡脱俗，刚直不阿，坦然自适，任何境遇中，都能处之泰然，享受使人感到无穷快意的千里雄风。苏轼这种逆境中仍保持浩然之气的坦荡的人生态度，显然具有积极的社会意义。\n\n　　这首词在艺术构思和结构上，具有波澜起伏、跌宕多姿、大开大合、大起大落的特点。下片的描写和议论，豪纵酣畅，气势磅礴，词中出没风涛的白头翁形象，犹如百川汇海，含蓄地点明全篇主旨，有强烈的震撼力。全词熔写景、抒情、议论于一炉，既描写了浩阔雄壮、水天一色的自然风光，又其中灌注了一种坦荡旷达的浩然之气，展现出词人身处逆境却泰然处之、大气凛然的精神风貌，充分体现了苏词雄奇奔放的特色。', poem_tags = '豪放,山水,写景,抒情,议论' WHERE poem_title = '水调歌头·黄州快哉亭赠张偓佺' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '思念梅花很想去西洲，去折下梅花寄去长江北岸。\n（她那）单薄的衣衫像杏子那样红，头发如小乌鸦那样黑。\n西洲到底在哪里？摇着小船的两支桨就可到西洲桥头的渡口。\n天色晚了伯劳鸟飞走了，晚风吹拂着乌桕树。\n树下就是她的家，门里露出她翠绿的钗钿。\n她打开家门没有看到心上人，便出门去采红莲。\n秋天的南塘里她摘着莲子，莲花长得高过了人头。\n低下头拨弄着水中的莲子，莲子就像湖水一样青。\n把莲子藏在袖子里，那莲心红得通透底里。\n思念郎君郎君却还没来，她抬头望向天上的鸿雁。\n西洲的天上飞满了雁儿，她走上高高的楼台遥望郎君。\n楼台虽高却看望不到郎君，她整天倚在栏杆上。\n栏杆曲曲折折弯向远处，她垂下的双手明润如玉。\n卷起的帘子外天是那样高，如海水般荡漾着一片空空泛泛的深绿。\n如海水像梦一般悠悠然然，伊人你忧愁我也忧愁啊。\n南风若知道我的情意，请把我的梦吹到西洲（与她相聚）。', poem_notes = '《西洲曲》：选自《乐府诗集·杂曲歌辞》。这首诗是南朝民歌。西洲曲，乐府曲调名。\n忆梅下西洲，折梅寄江北：意思是说，女子见到梅花又开了，回忆起以前曾和情人在梅下相会的情景，因而想到西洲去折一枝梅花寄给在江北的情人。下，往。西洲，当是在女子住处附近。江北，当指男子所在的地方。\n鸦雏色：像小乌鸦一样的颜色。形容女子的头发乌黑发亮。\n两桨桥头渡：从桥头划船过去，划两桨就到了。\n伯劳：鸟名，仲夏始鸣，喜欢单栖。这里一方面用来表示季节，一方面暗喻女子孤单的处境。\n乌臼：现在写作“乌桕”。\n翠钿：用翠玉做成或镶嵌的首饰。\n莲子：和“怜子”谐音双关。\n青如水：和“清如水”谐音，隐喻爱情的纯洁。\n莲心：和“怜心”谐音，即爱情之心。\n望飞鸿：这里暗含有望书信的意思。因为古代有鸿雁传书的传说。\n青楼：油漆成青色的楼。唐朝以前的诗中一般用来指女子的住处。\n尽日：整天。\n卷帘天自高，海水摇空绿：意思是说，卷帘眺望，只看见高高的天空和不断荡漾着的碧波的江水。海水，这里指浩荡的江水。\n海水梦悠悠：梦境像海水一样悠长。', poem_appreciation = '这首《西洲曲》，郭茂倩编的《乐府诗集》收入“杂曲歌辞”类，认为是“古辞”。《玉台新咏》作江淹诗，但宋本不载。明清人编的古诗选本，或作“晋辞”，或以为是梁武帝萧衍所作。这个问题，很难成定论。但从内容和风格看，它当是经文人润色改定的一首南朝民歌，十分精致流丽，广为后人传诵。\n\n　　此诗以四句为一节，基本上也是四句一换韵，节与节之间用民歌惯用的“接字”法相勾联，读来音调和美，声情摇曳。沈德潜在《古诗源》中说它“续续相生，连跗接萼，摇曳无穷，情味愈出”，确实道出了它在艺术上的特色。然而，如何正确理解这首诗的内容，却是学术界争议已久的问题，直到目前为止，也未能统一认识。\n\n　　这首诗主要是写一个少女，刻划她思念情侣的炽热而微妙的心情。然而，它既不是以少女自述的第一人称口吻来写，也不作诗人第三人称的客观描述，而是让这位少女的情侣用“忆”的方式来抒写，所以全诗都作男子诉说的口气。后来杜甫的《月夜》，写诗人对月怀念妻子，却设想妻子对月怀念自己，正是使用同样的手法。通过她的种种情况的描写，生动地塑造了一位美丽轻灵、纯洁多情的少女形象。这是全诗在艺术构思上的总的设想；若不这样理解，那将是越理越乱，最终变成一团乱麻，使人读来神秘恍惚，造成似懂非懂的印象。\n\n　　《西洲曲》是南朝乐府民歌中最长的抒情诗篇。诗中描写了一位少女从初春到深秋，从现实到梦境，对钟爱之人的苦苦思念，洋溢着浓厚的生活气息和鲜明的感情色彩。表现出鲜明的民族特色和纯熟的表现技巧。\n\n　　全诗三十二句，四句一解，用蝉联而下的接字法，顶真勾连。全诗技法之“巧”，真令人拍案叫绝。\n\n　　最早著录于徐陵所编《玉台新咏》的《西洲曲》，历来被视为南朝乐府民歌的代表作。沈德潜称其“续续相生，连跗接萼，摇曳无穷，情味愈出”(《古诗源》卷十二)，陈祚明则谓之“言情之绝唱”(《采菽堂古诗选》)，其艺术魅力自不容置疑。但与一般南朝乐府民歌不同的是，《西洲曲》极为难解，研究者甚至称之为南朝文学研究的“歌德巴赫猜想”(见《汉魏六朝诗歌鉴赏集》陈志明文)。《西洲曲》的语言一如民歌的清新质朴而少用事典，所以其难解并不在字词的生僻、晦涩，而是整首诗的诗意难以得到一个贯通全篇的畅达的解释。之所以如此，乃是因为诗歌所涉时间、地点、人物、情节等，都有幽暗不明之处，难以得到一个一致的解释。也许正因如此，“有人说这诗是若干短章的拼合，内容未必是完整统一的”(余冠英《谈西洲曲》)。但诚如余先生所言：“这话我却不敢信，因为诗的起讫都提到‘西洲’，中间也一再提到‘西洲’，分明首尾可以贯串，全篇必然是一个整体，且必然道着一个与西洲有关的故事。”(同上)可以说，如果《西洲曲》不是一个整体，那么所谓“《西洲曲》标志着南朝民歌在艺术发展上的最高成就”(游国恩等主编《中国文学史》)，便无从谈起。因此，求得《西洲曲》诗意的完整而畅达的解释，便直接关乎其文学史地位的评价。也正是在这个问题上，对《西洲曲》这篇名作的“猜想”远未完成，而不仅仅是一个“诗无达诂”的问题。\n\n　　余冠英先生在《西洲曲》的注释中说：这首诗写一个女子对所欢的思和忆。开头说她忆起梅落西洲那可纪念的情景，便寄一枝梅花给在江北的所欢，来唤起他相同的记忆，以下便写她从春到秋，从早到晚的相思。诗中有许多辞句表明季节，如“折梅”表早春，“单衫”表春夏之交，“采红莲”应在六月，“南塘秋”该是早秋(因为还有“莲花过人头”)，“弄莲子”已到八月，“鸿飞满西洲”便是深秋景象。(《汉魏六朝诗选》第三卷)\n\n　　这一具有经典性的解释，至少意在解决这样三个问题：第一，这首诗是一个多情女子对自己情郎的思念之歌。游国恩先生曾以为《西洲曲》从开头到“海水摇空绿”句皆为男子口气，只有末四句为女子自道心事；叶玉华先生则认为全诗部是女子的口吻(参见余冠英《古代文学杂论·谈西洲曲》)。余冠英先生确定“这首诗写一个女子对所欢的思和忆”，而以为“篇末四句当然是女子的口气，这四句以上却不妨都作为第三者的叙述”(同上)，可以说已经解决了这个问题，研究者已无疑义。第二，诗中女子居于江南，而其情郎住于江北，西洲则是二人共同纪念的地方。余先生说：“西洲固然不是诗中女子现在居住之地，也不是男子现在居住之地，它是另一个地方。……它何妨是一个名副其实的江中的洲呢?”(同上)第三，这首诗写的是“四季相思”。\n\n　　显然，上述三个问题正是理解《西洲曲》的关键。如果说，第一个问题已不成问题，研究者早已取得共识；那么，后两个问题虽很少有人再有疑问，但笔者感到，要想贯通全诗，其中仍有阻隔。首先，女子居于江南，其情郎居于江北，这是没有问题的；但西洲与江南、江北的关系是什么呢?一般据诗中“西洲在何处，两桨桥头渡”二句，认为西洲距女子居处不远，或谓即在江南，或谓距江南岸不远而两桨可渡。那么，其与江北便相距甚遥。但是，诗末却说：“南风知我意，吹梦到西洲。”这两句千古传颂，正因其涉想新奇，情思无限；它寄托的显然是这位女子对情郎的思念之情，如果西洲离女子居处不远，“吹梦”又有何必要?其次，正如余冠英先生所说：“这首诗表面看来像是若干首绝句联接而成，其实是两句一截。”(同上)所谓“两句一截”，正是从诗意着眼的；所谓“续续相生，连跗接萼”，正说明整首诗诗意的完整、统一而浑然一体。以“两句一截”的形式而写“四季相思”，不仅少见，而且很可能会破坏诗意的完整、统一。诗歌所写，乃一位女子的所思所想所作所为，尤其是她的一连串的动作；这一连串的动作怎么会分到四季写呢?比如，从开门盼郎至出门采莲．从采莲南塘至低首弄莲，这显然是这位女子的一系列连贯的动作，怎么可以分散到几个月去写呢?现代影视艺术有所谓“蒙太奇”的艺术手法，通过镜头的剪接、组合，可以有较长时间的跨越、衔接而产生连贯的效果。但省略的时间亦必须有结果体现出来，连贯只是效果的连贯，决不可一个连续的动作跨越很长时间。因此，如果说《西洲曲》写的是“四季相思”，即在现代艺术也是颇难理解的，更何况它是千余年前的作品呢?不过最后一句说“南风知我意，吹梦到西洲”，我想也可以理解为本诗描写的是一个人的梦境，这样诗中四季更迭的纷乱意象就不难理解了。\n\n　　以上两个问题是密切相关的。诗歌所涉地点不确或理解有误，便难以真正弄清其所涉时间。这两个问题的幽暗不明，便使得整首诗诗意难以连贯，许多解释也就龃龉难合。其实，诗歌的末四句为女子自道向无异议，而“南风知我意，吹梦到西洲”，则明确地显示出西洲即是这位女子的情郎所居之地，它正在江北。只有如此理解，才能真正确切把握“南风吹梦”的诗意。范云《闺思》诗有“几回明月夜，飞梦到郎边”句，李白《闻王昌龄左迁龙标遥有此寄》诗有“我寄愁心与明月，随风直到夜郎西”句，皆从《西洲曲》化出；他们对“南风吹梦”诗意的理解，正说明西洲只能是情郎所居之地。温庭筠《西洲曲》谓“西洲风色好，遥见武昌楼”。武昌在长江南岸，既云“遥见”则西洲可能正在江北。而据“出门采红莲。采莲南塘秋”之句，可知诗中女子距南塘之地不远。《新唐书·地理志》说：“钟陵，贞元中又更名，县南有东湖。元和三年，刺史韦丹开南塘斗门以节江水，开陂塘以溉田。”耿湋《春日洪州即事》亦云：“钟陵春日好，春水满南塘。”可见南塘在钟陵附近，即在今江西南昌附近。因此，诗中女子乃居于南昌附近，其与西洲相去远矣；所谓“南风”、“吹梦”，正以此也。借用余冠英先生的话说：“‘江北’可不见得近啊！要是近，就不会有这许多梦，许多愁，也就没有这首诗了。”(《谈西洲曲》)笔者以为，西洲正在江北，《西洲曲》所谓“江北”亦正指西洲。\n\n　　确定了诗歌所涉地点，则诗意的贯通便较为容易了。首二句“忆梅下西洲，折梅寄江北”，并非写梅落西洲、女子折梅。“下”者，到也。温庭筠《西洲曲》谓：“悠悠复悠悠，昨日下西洲。”“下”正是“到”的意思。南朝民歌《那呵滩》亦有：“闻欢下扬州，相送江津湾。”其意甚明。但“忆梅下西洲”也并非这位女子要到西洲去折梅花，而是说这位女子想到自己所寄梅花可能早已到了西洲，到了情郎的手中。“折梅寄江北”是对“忆梅下西洲”的补充说明，或谓首二句就是一个倒装句。“折梅”是过去所为，“忆梅“才是此时所思。只有如此理解，方与下文所写季节相合。如上所述，谓此诗为“四季相思”实难讲通，这不仅因为诗意难贯，而且通常所谓诗中表明季节的辞句，其实不然。如谓“单衫”句表春夏之交或春天，“单衫”岂止春天可穿?“杏子红(黄)”与“鸦雏色”相对而言，所指为“单衫”色彩，亦不表明季节。又如谓“日暮伯劳飞”表夏天，更属望文生解。《礼记·月令》诚有“仲夏鵙始鸣”之载，《诗·豳风·七月》亦有“七月鸣鵙”之句，“鵙”即为伯劳；但伯劳“始鸣”与“伯劳飞”井非一回事是显然可见的。因此，《西洲曲》所涉时节决不用“猜”，“采莲南塘秋”已作了明确说明；至于采莲时节又有“莲花过人头”亦并不奇怪，故亦不必再分初秋、中秋和深秋。所以，秋天便是《西洲曲》的季节背景。“秋露如珠，秋月如圭，明月白露，光阴往来；与子之别，思心徘徊”(江淹《别赋》)，正是在秋日怀人时节，这位女子想起自己曾寄梅花一事，从而有所盼望。先说“忆梅下西洲”，而后补充自己曾经“折梅寄江北”，正表明心情的迫切和思念之深重，极为切合此时女子的心态。实际上，忆及折梅、寄梅之事，只是一个“引子”，是绵绵之思的开始。\n\n　　诗篇在写了女子想到西洲以后，插叙了一下女子的打扮及其美丽的容貌，即“单衫杏子红(黄)，双鬓鸦雏色”，这可以说是一种体察入微的心理描绘或烘托。本来，“西洲在何处”的交代紧承“折梅寄江北”正合乎逻辑；然而女主人公既想起了情郎，想起了自己曾折梅寄往江北，因而她多少抱有情郎可能归来的希望，下文所谓“开门郎不至”正说明了这一希望的存在。正因有这个希望，她才在想到了情郎之后，立即注意到自己的装束和姿容，所谓“女为悦己者容”，要是情郎已站在门外了呢?所以这两句正绝妙地刻画出女主入公此时的心理活动，而不只是对其装束的简单交代。“西洲在何处?两桨桥头渡”二句，既交代了西洲之位置，亦表现出此女子对其挂怀之情；之所以值得如此魂牵梦绕，正因其为情郎所在地。所谓“两桨桥头渡”，一般释为划两下桨就到了，所距很近。其实这是误解。南朝民歌的《西曲歌》中有《莫愁乐》二首，其一云：“莫愁在何处?莫愁石城西。艇子打两桨，催送莫愁来。”所谓“两桨”，指的就是船的两个桨；在《西洲曲》中，借以指船。其意是说，要到西洲去，需要乘船过江，此亦正说明西洲在江北。以上六句所描绘的乃是一个静坐相思的女子的形象，而非正乘船到西洲采梅的女子形象。如此理解，则与下文正好贯通。\n\n　　“日暮伯劳飞，风吹乌臼树”，是对女主人公居住环境的描写。《古微书》说：“博劳好单栖。”所以，这里的环境描写也是一种象征，显示了这位女子的孤独和凄清。“树下即门前，门中露翠钿”，则静坐相思的女子形象方直接呈现出来。如上所说，盼望郎归已在情理之中，而归来又并不是现实；“开门郎不至”就既写了现实的严酷，又暗含了女主人公的希望。静坐相思无望，便“出门采红莲”，以遣不尽的相思之情。然而，既然带着思念的心情“出门”，则相思之情注定非但难以去除，反而因采莲而加重。以下对采莲情节的细致描绘，正体现了这种情形。研究者早已指出，“莲”与“怜”谐音双关，则“青如水”的“莲子”正是女主人公纯洁爱情的象征，也就难怪其如此爱怜，以至于“置莲怀袖中”了；“莲心彻底红”，可以说是他们之间爱情的象征。在此情形之下，这位女子盼郎归的心情也就更加迫切，以至于“忆郎郎不至，仰首望飞鸿”了。诗歌对女主人公翘首以望飞鸿的描绘可谓生动传神，韵味悠长。“望飞鸿”既是一种无可奈何的自然动作，又是一种有目的的盼望——盼郎不至而盼有信来，所谓“鸿雁传书”。然而信也没有。以下所谓“鸿飞满西洲”，并非女主人公看到了大雁飞满西洲，而是一种猜度之词。其意是说，时值秋日，“鸿飞应满西洲”，而人皆谓“鸿雁传书”，为何你竟无音信?正是带着这种疑惑的心情，这位女子“望郎上青楼”了。“青楼”，漆成青色的楼，在南朝所指不一。曹植《美女篇》云；“青楼临大路，高门结重关。”则“青楼”指显贵家之闺阁。《南齐书·东昏侯纪》谓：“世祖兴光楼上施青漆，世谓之青楼。”则“青楼”指帝王所居。梁诗人刘邈《万山见采桑人诗》有：“倡妾不胜愁，结束下青楼。”“青楼”便指妓院了。“望郎上青楼”句显示了《西洲曲》带有文人诗的色彩。青楼虽高却仍然望不见，望不见又并不甘心，便有了“尽日栏杆头”的执着。所谓“尽日”，乃夸饰之词，是说凝望有时，而非终日伫立。较长时间的扶栏眺望，自然会注意到平常所不注意的事情；所谓“栏杆十二曲，垂手明如玉”，正写出女主人公此时百无聊赖的心境，与上文“单衫”两句恰成鲜明的对照。“双鬓鸦雏色”还显示着自信和希望，而“垂手明如玉”则表现出愁怅和怨恨，因为此时是空有“垂手明如玉”，尽日望郎郎不归！这种心理活动的描绘是白描式的，甚至“不着一字”，然而又是细致入微的，可谓“尽得风流”，体现出中国古代诗歌的独特风韵。“栏杆”二句写女主人公对近景的仔细而又是漫不经心的注意，“卷帘天自高，海水摇空绿”二句则 　　是对眼前远景的观察。余冠英先生说：“以上二句似倒装。秋夜的一片蓝天像大海。风吹帘动，隔帘见天便觉似海水滉漾。一说内地人有呼江为海者，‘海水’即指江水。”(《汉魏六朝诗选》第三卷)鲁迅先生在小说《白光》中有这样的描绘：“空中青碧倒如一片海……”其境正似“秋夜的一片蓝天像大海”的“海水摇空绿”。不过．从下文“海水梦悠悠”句看，“海水”似有实指，而不仅仅是一个比喻。与其说“海水”即指江水，勿宁说它指的是湖水。这不仅因为内地许多湖即名为海，而且上文所引《新唐书·地理志》正指出南塘附近有一“东湖”。\n\n　　诗歌至此，女主人公盼君君不归，等书书不到，心情陷入无端的愁怅。“海水梦悠悠，君愁我亦愁”，她不仅自己愁思绵绵，而且也想到了情郎同样会愁绪满怀；他们的愁思像蓝天、湖水，无边无际，缠绵不绝。此时，便只有在梦中相见的希望了。“南风知我意，吹梦到西洲”，这是想像，更是希望；这一想像和希望既合情合理，是情之所至、不得不然，又新奇鲜美、生动感人。它是情之所至，那是因为女主人公自“日暮”盼郎，经历了南塘采莲、望郎登楼等一系列活动，至此天色已晚，她必须就寝休息了，盼望梦中相见是所剩惟一的希望；它涉想新奇，乃是因为她并非如一般所谓自己多么希望能梦见情郎，而是把自己的心事诉诸南风，请南风把自己的梦吹往西洲，带到情郎的身旁。这种含蓄、细腻、婉转的表情方式，集中而典型地体现出南方民歌的艺术特色及其独特的艺术风格。\n\n　　综上可见，《西洲曲》乃心系西洲、怀念郎君之作。其所涉地点只有两处，一是郎君所在地西洲，一是女子所在地南塘附近；一在江北，一在江南，且相距甚遥。其中人物，出场的是女子，幕后的是情郎；全诗既可以看成以第三人称而写女子，亦可视为女子自道，或者其中既有女子自道，亦有以第三人称而作的叙述，但其中没有男子的声音或描写，则是显然的。本诗的时间，不是写四季，也不是写春夏秋三季或夏秋两季，而就是写秋天；而且其中所写，只是秋日某天下午至天黑这段时间里，女主人公的所思所想所作所为。所有这些，实际上又可归结为一点，那就是这位女子的相思之情。《西洲曲》可谓中国诗歌史上的“言情之绝唱”。', poem_tags = '乐府,民歌,梅花,女子,思念' WHERE poem_title = '西洲曲' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '城墙上的画角声仿佛也在哀痛，沈园已经不是原来的池阁亭台。\n令人伤心的桥下春水依然碧绿，在此曾见她的倩影如惊鸿飘来。\n\n离她香消玉殒已过去四十多年，沈园柳树也老得不能吐絮吹绵。\n自身即将化为会稽山一抔泥土，仍然来此凭吊遗踪而泪落潸然。', poem_notes = '沈园：即沈氏园，故址在今浙江绍兴禹迹寺南。\n斜阳：偏西的太阳。画角：涂有色彩的军乐器，发声凄厉哀怨。\n惊鸿：语出三国魏曹植《洛神赋》句“翩若惊鸿”，以喻美人体态之轻盈。这里指唐琬。\n“梦断”句：作者在禹迹寺遇到唐琬是在高宗绍兴二十五年（1155年），其后不久，唐琬郁郁而死。作此诗时距那次会面四十四年，这里的“四十”是举其成数。香消，指唐琬亡故。\n不吹绵：柳絮不飞。\n行：即将。稽（jī）山：即会稽山，在今浙江绍兴东南。\n吊：凭吊。泫（xuàn）然：流泪貌。', poem_appreciation = '《沈园二首》乃陆游触景生情之作，此时距沈园邂逅唐氏已四十余年，但缱绻之情丝毫未减，反而随岁月之增而加深。\n\n　　第一首诗回忆沈园相逢之事，悲伤之情充溢楮墨之间。\n\n　　“城上斜阳”，不仅点明傍晚的时间，而且渲染出一种悲凉氛围，作为全诗的背景。斜阳惨淡，给沈园也涂抹上一层悲凉的感情色彩。于此视觉形象之外，又配以“画角哀”的听觉形象，更增悲哀之感。“画角”是一种彩绘的管乐器，古时军中用以警昏晓，其声高亢凄厉。此“哀”字更是诗人悲哀之情外射所致，是当时心境的反映。这一句造成了有声有色的悲境，作为沈园的陪衬。\n\n　　次句即引出处于悲哀氛围中的“沈园”。诗人于光宗绍熙三年（1192年）六十八岁时所写的《禹迹寺南有沈氏小园序》曰：“禹迹寺南有沈氏小园，四十年前（按：实为三十八年）尝题小词壁间，偶复一到，园已三易主，读之怅然。”诗中并有“坏壁醉题尘漠漠”之句。那时沈园已有很大变化；而现在又过七年，更是面目全非，不仅“三易主”，且池台景物也不复可认。诗人对沈园具有特殊的感情，这是他与唐氏离异后唯一相见之处，也是永诀之所。这里留下了他刹那间的毛喜与永久的悲，《钗头凤·红酥手》这首摧人肝肺之词也题于此。他多么渴望旧事重现，尽管那是悲剧，但毕竟可一睹唐氏芳姿。这当然是幻想，不得已而求其次，他又希望沈园此时的一池一台仍保持当年与唐氏相遇时的情景，以便旧梦重温，借以自慰。但现实太残酷了，今日不仅心上人早已作古，连景物也非复旧观。诗人此刻心境之寥落，可以想见。\n\n　　但是诗人并不就此作罢，他仍竭力寻找可以引起回忆的景物，于是看到了“桥下春波绿”一如往日，感到似见故人。只是此景引起的不是喜悦而是“伤心”的回忆：“曾是惊鸿照影来”。四十四年前，唐氏恰如曹植《洛神赋》中所描写的“翩若惊鸿”的仙子，飘然降临于春波之上。她是那么婉娈温柔，又是那么凄楚欲绝。离异之后的不期而遇所引起的只是无限“伤心”。诗人赋《钗头凤》，抒写出“东风恶，欢情薄”的愤懑，“泪痕红浥鲛绡透”的悲哀，“错！错！错！”的悔恨。唐氏和词亦发出“世情薄，人情恶”的控诉，“今非昨，病魂常恨千秋索”的哀怨。虽然已过了四十余春秋，而诗人“一怀愁绪”，绵绵不绝，但“玉骨久成泉下土”（《十二月二日夜梦游沈氏园亭》），一切早已无可挽回，那照影惊鸿已一去不复返了。然而只要此心不死，此“影”将永在心中。\n\n　　第二首诗写诗人对爱情的坚贞不渝。\n\n　　首句感叹唐氏溘然长逝已四十年了。古来往往以“香销玉殒”喻女子之亡，“梦断香消”即指唐氏之死。陆游于八十四岁即临终前一年所作悼念唐氏的《春游》亦云：“也信美人终作土，不堪幽梦太匆匆。”唐氏实际已死四十四年，此“四十年”取其整数。这一句充满了刻骨铭心之真情。\n\n　　次句既是写沈园即日之景：柳树已老，不再飞绵；也是一种借以自喻的比兴：诗人六十八岁时来沈园已自称“河阳愁鬓怯新霜”（《禹迹寺南有沈氏小园四十年前尝题小阕壁间偶复一到而园已易主刻小阕于石读之怅然》），此时年逾古稀，正如园中老树，已无所作为，对个人生活更无追求。“此身行作稽山土”，则是对“柳老”内涵的进一步说明。“美人终作土”，自己亦将埋葬于会稽山下而化为黄土。此句目的是反衬出尾句“犹吊遗踪一泫然”，即对唐氏坚贞不渝之情。一个“犹”字，使诗意得到升华：尽管自己将不久于人世，但对唐氏眷念之情永不泯灭；尽管个人生活上已无所追求，但对唐氏之爱历久弥新。所以对沈园遗踪还要凭吊一番而泫然涕下。“泫然”二字，饱含无比复杂的感情：其中有爱，有恨，有悔，诗人不点破，足供读者体味。\n\n　　这两首诗与陆游慷慨激昂的诗篇风格迥异：感情性质既别，艺术表现自然不同。写得深沉哀婉，含蓄蕴藉，但仍保持其语言朴素自然的一贯特色。', poem_tags = '悼亡,回忆,组诗' WHERE poem_title = '沈园二首' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '桃花坞里有桃花庵，桃花庵下有桃花仙。\n桃花仙人种了桃树，又折下桃花枝去抵酒钱。\n酒醒了也只是坐在桃花前，喝醉了就要在桃花下睡觉。\n日复一日的在桃花旁，年复一年的酒醉又酒醒。\n不愿意在华贵的车马前弯腰屈从，只希望在赏花饮酒中度日死去。\n车马奔波是富贵人的乐趣所在，而无财的人追寻的是酒盏和花枝。\n如果将富贵和贫贱相比，那是天壤之别。\n如果将清贫的生活与车马劳顿的生活相比，他们得到的是奔波之苦，我得到的是闲适之乐。\n世间的人笑我太疯癫了，我笑他们都太肤浅。\n还记得五陵豪杰的墓前没有花也没有酒，如今都被锄作了田地。\n弘治乙丑年三月桃花庵的主人唐寅作。', poem_notes = '庵：屋舍也。\n桃花坞：坞为四面高，中间低的地方，今江苏省苏州市有地名“桃花坞”。\n鞠躬：恭敬谨慎的样子，表示屈从，屈服。\n忒（tuī）：太。\n五陵豪杰墓：汉代五个皇帝的陵墓，即长陵，安陵，阳陵，茂陵，平陵，都在长安附近，后人也用“五陵”指富贵人家聚居长安的地方。\n无花无酒：指没有人前来祭祀，摆花祭酒是祭祀的礼俗。', poem_appreciation = '全诗画面艳丽清雅，风格秀逸清俊，音律回风舞雪，意蕴醇厚深远。虽然满眼都是花、桃、酒、醉等香艳字眼，却毫无低俗之气，反而笔力直透纸背，让人猛然一醒。唐寅诗画得力处正在于此，这首诗也正是唐寅的代表作。\n\n　　全诗描绘了两幅画面，一幅是汉朝大官和富人的生活场景，一幅是明朝唐寅自己的生活场景。只用了“鞠躬车马前”、“车尘马足”、“碌碌”等十几个字，就把明朝大官和富人的生活场景传神地勾勒了出来。唐寅自己的生活场景描写得比较详细，“种桃树”、“摘桃花换酒钱”、　“酒醒只在花前坐，酒醉还来花下眠”、“ 半醉半醒日复日”、“但愿老死花酒间，不愿鞠躬车马前”、“酒盏花枝隐士缘”。两幅画面孰优孰劣由读者自己体会和评定。\n\n　　“桃花坞里桃花庵，桃花庵下桃花仙。桃花仙人种桃树，又摘桃花换酒钱。”起首四行，有如一个长长的“推”的镜头，由远及近，将一个画里神仙陡然呈现在读者面前。短短四行，重复用了六个“桃花”，循环复沓，前后钩连，浓墨重彩，迅速堆积出一个花的世界，使人一下子落入其所设定的情境之中。不紧不慢的语调和语速，又加重了读者的亲切感和好奇心：这桃花仙人究竟过得是怎样的神仙生活？接下来的四行便展开一幅“醉卧花间”的美图：“酒醒只在花前坐，酒醉还来花下眠。半醒半醉日复日，花落花开年复年。”看这桃花仙人何等逍遥，何等快活，竟年复一年、日复一日地醉酒赏花。这里，花与酒，已不完全是诗人藉以谴怀的外物，简直是诗人生命的一部分，或者说也成了独立的生命个体，花、酒与人，融为一个和谐的整体。以上几句，可谓作者自况，意象生动、鲜明而有深义。那个曾经幻想“朝为田舍郎，暮登天子堂”的学子唐寅不见了，那个烟花柳巷醉生梦死的风流才子不见了，痛也痛过，乐也乐过，在经历了几年放浪生活之后，唐寅终于还是选择逃离闹市，为自己选定这一处世外桃源，和继娶沈氏，开始了相对平静的隐居生活。虽仕进无门，毕竟身有所托，又值壮年，美景逸思，一咏成诗。\n\n　　“但愿老死花酒间，不愿鞠躬车马前。”此一句承上启下，道出了诗人的志趣所在：与其为了荣华富贵奔波劳碌屈己下人，何如在花酒间快活逍遥：“车尘马足贵者趣，酒盏花枝贫者缘。若将富贵比贫者，一在平地一在天。”“车尘马足”只是富贵者的趣味，而花和酒注定与贫者结缘。如果用金钱和物质来衡量，这两种人两种生活自然有着天壤之别，但换个角度去理解，那些富贵者须得时刻绷紧神经，小心翼翼如履薄冰地过活，而所谓贫者，却能多几分闲情，多几分逸趣，反而活得更加自然、真实，更加轻松和快乐。以上六行全用对比描写，感情在激烈的碰撞中展开，每一句中，因用韵的关系，前紧后舒，充分表现出诗人傲世不俗的个性，和居处生活的的超脱与释然。\n\n　　注：“车尘马足显者势，酒盏花枝隐士缘。 若将显者比隐士，一在平地一在天。 若将花酒比车马，彼何碌碌我何闲。”综合全文意境，显者与隐士的对比，较富者与贫者的对比更贴合，作此诗时，唐寅已经经历过了出仕不利，已经绝了“朝为田舍郎，暮登天子堂”的进取之意，是隐居在此。\n\n　　然而此中真义并非人人悟得，君不见“别人笑我忒疯癫”？而“我”，却不以为然：“我笑他人看不穿。”难道你们没有看到，昔日叱咤风云富贵至极的君王将相，如今又如何呢？不但身已没，势已落，连花和酒这些在他们生前不屑一顾的东西都无法奢望了，甚至连坟茔都不保。如果他们在天有知，也只能无奈地看着农夫在自己葬身的土地上耕作了。 “不见五陵豪杰墓，无花无酒锄作田！” 一句收束，戛然而止，余味绵绵。\n\n　　通观全诗，层次清晰，语言浅近，回旋委婉，近乎民谣式的自言自语，然而就是这样的自言自语，却蕴涵的无限的艺术张力，给人以绵延的审美享受和强烈的认同感，不愧是唐寅诗中之最上乘者。这也正合了韩愈“和平之音淡薄，而愁思之音要妙；欢愉之辞难工，而穷苦之言易好”（《荆潭唱和诗序》）的著名论断。\n\n　　这首诗中最突出，给人印象最深的两个意象是“花”和“酒”。桃花，最早见诸文学作品，当于《诗经·周南》之《桃夭》篇，本意表达一种自由奔放的情感。而至晋陶渊明《桃花源记》一出，桃花便更多地被用来表达隐逸情怀了。古代，桃还有驱鬼辟邪的意思，而“桃”与“逃” 谐音，因有避世之意。在唐寅的诗中，“桃花”这一意象频频出现。试举几例：\n\n　　我也不登天子船，我也不上长安眠。姑苏城外一茅屋，万树桃花月满天。 （《把酒对月歌》）\n\n　　桑出罗兮柘出绫，绫罗妆束出娉婷。娉婷红粉歌金缕，歌与桃花柳絮听。 （《桑图》）\n\n　　野店桃花万树低，春光多在画桥西。幽人自得寻芳兴，马背诗成路欲迷。 （《题画四首其一》）\n\n　　花开烂漫满村坞，风烟酷似桃源古。千林映日莺乱啼，万树围春燕双舞。 （《桃花坞》）\n\n　　草屋柴门无点尘，门前溪水绿粼粼。中间有甚堪图画，满坞桃花一醉人。 （《题画廿四首其十五》）\n\n　　不难看出，例中桃花意象都是用来表达闲居和隐逸生活的。\n\n　　“酒”，在中国古代文化和古代士人中也有着重要的地位。它不仅可以用来表达悲壮慷慨情怀，更与世事苍凉、傲岸不羁、独行特立结缘。晋有刘伶、嵇康，唐有“饮中八仙”，宋有东坡“把酒问青天”，而到了明代，又有了唐寅醉酒花下眠。\n\n　　唐寅在世时声名已著，除在绘画史上拥有突出地位外，在诗词上亦有独创的成就。其诗真切平易，不拘成法，大量采用口语，意境警拔清新，在当时独树一帜，并以其独特超凡的个性和艺术气质，从一个侧面，给那个自由、开放近乎荒唐、混沌的时代做出典型、生动的诠释。', poem_tags = '桃花,生活,猖狂' WHERE poem_title = '桃花庵歌' AND poem_author = '唐寅';
UPDATE edu_poem SET poem_translation = '喝醉了酒后恣意欢笑，我哪里有那闲工夫发愁呢。\n最近才明白古书上的话，的的确确是没有半点可信的！\n昨儿晚上我在松边喝醉了，醉眼迷蒙，把松树看成了人，就问他：“我醉得怎么样啊？”\n恍惚中看见松树活动起来，疑是要来扶我，于是我用手不耐烦的推推松树说：“走开走开！”。', poem_notes = '用《孟子·尽心下》“尽信书则不如无书“意。\n《汉书·龚胜传》“胜以手推常（夏侯常）曰‘去’。“见黄季刚师《读汉书后汉书札记》说辛词此句。', poem_appreciation = '欣赏这首词，我们似乎可以这样说：品读辛弃疾的词，可从词中品出更有韵味的戏剧来，虽然在写词中，恰如其分地引入戏剧性场景并非辛弃疾发明，但是在他手上得到了发扬光大，在他的词中，这种情况十分常见。这是值得肯定的。\n\n　　“醉里且贪欢笑，要愁那得工夫。”通篇“醉”字出现了三次。难道词人真成了沉湎醉乡的“高阳酒徒”么？否。盖因其力主抗金而不为南宋统治者所用，只好借酒消愁，免得老是犯愁。说没工夫发愁，是反话，骨子里是说愁太多了，要愁也愁不完。\n\n　　“近来始觉古人书，信着全无是处。”才叙饮酒，又说读书，并非醉后说话无条理。这两句是“醉话”。“醉话”不等于胡言乱语。它是词人的愤激之言。《孟子·尽心下》：“尽信书，则不如无书。”本意是说古书上的话难免有与事实不符的地方，未可全信。辛弃疾翻用此语，话中含有另一层意思：古书上尽管有许多“至理名言”，现在却行不通，因此信它不如不信。\n\n　　以上种种，如直说出来，则不过慨叹“世道日非”而已。但词人曲笔达意，正话反说，便有咀嚼不尽之味。\n\n　　下片写出了一个戏剧性的场面。词人“昨夜松边醉倒”，居然跟松树说起话来。他问松树：“我醉得怎样了？”看见松枝摇动，只当是松树要扶他起来，便用手推开松树，并厉声喝道：“去！”醉憨神态，活灵活现。词人性格之倔强，亦表露无遗。在当时的现实生活里，醉昏了头的不是词人，而是南宋小朝廷中那些纸醉金迷的昏君佞臣。哪怕词人真醉倒了，也仍然挣扎着自己站起来，相比之下，小朝廷的那些软骨头们是多么的渺小和卑劣。\n\n　　辛弃疾的这首小词，粗看，正如标题所示，是一时即兴之作。但如果再往里仔细一看，那么会发现作者是在借诙谐幽默之笔达发泄内心的不平。如再深入研究，我们还可洞察到作者是由于社会现实的黑暗而忧心忡忡，满腹牢骚和委屈，不便明说而又不能不说，所以，只好借用这种方式，来畅快淋漓地宣泄他的真情实感。', poem_tags = '宋词三百首,豪放,怀才不遇,壮志难酬' WHERE poem_title = '西江月·遣兴' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '茂盛的松树生长在山涧底,风中低垂摇摆着的小苗生长在山头上.\n(由于生长的地势高低不同,)凭它径寸之苗,却能遮盖百尺之松.\n贵族世家的子弟能登上高位获得权势,有才能的人却埋没在低级职位中.\n这是所处的地位不同使他们这样的,这种情况由来已久 并非一朝一夕造成的.\n汉代金日磾和张安世二家就是依靠了祖上的遗业,子孙七代做了高官.(珥汉貂:珥,插.汉代侍中官员的帽子上插貂鼠尾作装饰.)\n汉文帝时的冯唐难道还不算是个奇伟的人才吗?可就因为出身微寒,白头发了仍不被重用。', poem_notes = '郁郁：严密浓绿的样子。涧：两山之间。涧底松：比喻才高位卑的寒士。　\n离离：下垂的样子。苗：初生的草木。山上苗：山上小树。　\n彼：指山上苗。径：直径。径寸：直径一寸。径寸茎：即一寸粗的茎。　\n荫：遮蔽。此：指涧底松。条：树枝，这里指树木。　\n胄：长子。世胄：世家子弟。蹑（niè聂）：履、登。　\n下僚：下级官员，即属员。沉下僚：沉没于下级的官职。　\n“地势”两句是说这种情况恰如涧底松和山上苗一样，是地势造成的，其所从来久矣。　\n金：指汉金日磾（jin mi di)，他家自汉武帝到汉平帝，七代为内侍。（见《汉书·金日传》）张：指汉张汤，他家自汉宣帝以后，有十余人为侍中、中常侍。《汉书·张汤传赞》云：“功臣之世，唯有金氏、张氏亲近贵宠，比于外戚。”七叶：七代。珥（ěr耳）：插。珥汉貂：汉代侍中、中常侍的帽子上，皆插貂尾。这两句是说金张两家的子弟凭借祖先的世业，七代做汉朝的贵官。　\n冯公：指汉冯唐，他曾指责汉文帝不会用人，年老了还做中郎署长的小官。伟：奇。招：招见。不见招：不被进用。这两句是说冯唐难道不奇伟，年老了还不被重用。以上四句引证史实说明“世胄蹑高位，英俊沉下僚”的情况，是由来已久。', poem_tags = '古诗三百首,咏史,抒怀' WHERE poem_title = '咏史·郁郁涧底松' AND poem_author = '左思';
UPDATE edu_poem SET poem_translation = '闺中少妇未曾有过相思离别之愁，在明媚的春日，她精心妆饰，登上高楼。忽然看到路边的杨柳春色，惆怅之情涌上心头。她后悔当初不该让丈夫从军边塞，建功封侯。\n\n译文二\n闺阁中的少妇，从来不知忧愁；\n春来细心打扮，独自登上翠楼。\n忽见陌头杨柳新绿，心里难受；\n呵，悔不该叫夫君去觅取封侯。', poem_notes = '闺怨：少妇的幽怨。闺，女子卧室，借指女子。一般指少女或少妇。古人“闺怨“之作，一般是写少女的青春寂寞，或少妇的离别相思之情。以此题材写的诗称“闺怨诗”。\n“不知愁“一作“不曾愁“，则诗意大减。\n凝妆：盛妆。\n陌头：路边。\n觅封侯：为求得封侯而从军。觅，寻求。\n悔教：后悔让', poem_appreciation = '王昌龄的一系列宫闺怨诗中《闺怨》尤为突出。诗题为《闺怨》，起笔却写道：“闺中少妇不知愁”，紧接着第二句又写出这位不知愁的少妇，如何在春光明媚的日子里“凝妆”登楼远眺的情景。于是，一个有些天真和娇憨之气的少妇形象跃然纸上。闺中少妇果真不知愁吗？当然不是。读过全诗之后我们知道，这是一位丈夫远征他乡，自己独守空房的少妇，即使在唐朝封建礼教尚不严格束缚妇女的时代，她平日里也是不能随便出门的。\n\n　　第三句是全诗的关键，称为“诗眼”。这位少妇所见，不过寻常之杨柳，作者何以称之为“忽见”？其实，诗句的关键是见到杨柳后忽然触发的联想和心理变化。杨柳在古代人的心目中，不仅仅是“春色”的代替物，同时，它又是友人别离时相赠的礼物，古人很早便有折柳相赠的习俗。因为那迷茫和朦胧的杨花柳絮和人的离愁别绪有着某种内在的相似。\n\n　　故少妇见到春风拂动下的杨柳，一定会联想很多。她会想到平日里的夫妻恩爱，想到与丈夫惜别时的深情，想到自己的美好年华在孤寂中一年年消逝，而眼前这大好春光却无人与她共赏……或许她还会联想到，丈夫戍守的边关，不知是黄沙漫漫，还是和家乡一样杨柳青青呢？\n\n　　在这一瞬间的联想之后，少妇心中那沉积已久的幽怨、离愁和遗憾便一下子强烈起来，变得一发而不可收。“悔教夫婿觅封侯”便成为自然流淌出的情感。说到“忽见”，杨柳色显然只是触发少妇情感变化的一个媒介，一个外因。如果没有她平时感情的积蓄，她的希冀与无奈，她的哀怨与幽愁，杨柳是不会如此强烈地触动她“悔”的情感的。故曰少妇的情感变化看似突然，实则并不突然，而在情理之中。', poem_tags = '唐诗三百首,春天,妇女,闺怨' WHERE poem_title = '闺怨' AND poem_author = '王昌龄';
UPDATE edu_poem SET poem_translation = '在一个长满青草的池塘里，池水灌得满满的，山衔住落日淹没了水波。放牛的孩子横坐在牛背上，随意地用短笛吹奏着不成调的的乐曲。', poem_notes = '陂（bēi）：池塘。\n衔：口里含着。本文指落日西沉，半挂在山腰，像被山咬住了。\n浸：淹没。\n寒漪（yī）：水上波纹。\n横牛背：横坐在牛背上。\n腔：曲调。\n信口：随口。\n归去：回去。\n池塘：堤岸。', poem_appreciation = '这首诗展示的是一幅牧童骑牛晚归图，真正达到了“诗中有画”的境界。这是一首描写农村晚景的诗：在四周长满青草的池塘里，池中的水灌得满满的，太阳正要落山，红红的火球好像被山吃掉一样（是落山后），倒映在冰凉的池水波纹中。放牛回家的孩子横坐在牛背，他拿着短笛随意的吹奏。诗人即景而写，构成了一幅饶有生活情趣的农村晚景图。\n\n　　诗前两句写背景。首句“草满池塘”是说节令已在春末，池塘里的青草已经长满，借鉴谢灵运《登池上楼》名句“池塘生春草”，但以“满”字易“生”字，显出节令的不同。“水满陂”，是说正逢多雨季节，因此水涨得很高。次句写远山落日。用一个“衔”字，形象地现出落日挂在山头上的情况，与杜甫“四更山吐月”的“吐”字同见炼字之工。又用一个“浸”字，写落日青山倒映水中，与王安石“北山输绿涨横陂”句情景非常相似。诗围绕池塘为中心，以池塘中的绿草与澄净的池水，带出青山与落日，中间以一“浸”字作维系，使池塘显得很热闹，色彩也十分绚丽。\n\n　　在这样宁静优美的背景中，主人公——牧童登场了。他骑着牛儿，走向村庄，手中拿着支短笛，随意吹着。与上两句的恬静相比，这两句描绘得非常生动活泼。牧童骑着牛，不是规规矩矩地骑，而是横坐着；他吹笛也不是认真地吹，而是“无腔信口吹”。于是，牧童调皮天真的神态，活生生地呈现在读者面前，使人为之耳目一新。\n\n　　诗摄取的画面不大，写景则集中在池塘上，写人则集中在牧童上，又都紧紧围绕着“村晚”二字落笔，把人引入了江南优美的田园之中，使人对悠然恬静的乡村生活充满着向往。在此之前，张舜民《村居》诗有“夕阳牛背无人卧，带得寒鸦两两归”句，与这首诗比，画面中少了个天真烂漫的牧童，代之以牛背的乌鸦，以显出村晚的萧瑟。同样的农村景色，因诗人的心情不同，摄取的画面便不同，一是充满情趣，一是惆怅落寞，因此诗家有“一切景语皆情语”的说法。', poem_tags = '农村,写景,儿童' WHERE poem_title = '村晚' AND poem_author = '雷震';
UPDATE edu_poem SET poem_translation = '我敬重孟先生的庄重潇洒，\n他为人高尚风流倜傥闻名天下。\n少年时鄙视功名不爱官冕车马，\n高龄白首又归隐山林摒弃尘杂。\n明月夜常常饮酒醉得非凡高雅，\n他不事君王迷恋花草胸怀豁达。\n高山似的品格怎么能仰望着他？\n只在此揖敬他芬芳的道德光华！', poem_notes = '孟夫子：指孟浩然。夫子，一般的尊称。\n风流：古人以风流赞美文人，主要是指有文采，善词章，风度潇洒，不钻营苟且等。王士源《孟浩然集序》说孟“骨貌淑清，风神散朗，救患释纷，以立义表。灌蔬艺竹，以全高尚。”\n红颜句：意谓从青年时代起就对轩冕荣华（仕宦）不感兴趣。\n白首：白头，指老年。\n醉月句：月下醉饮。中圣：“中圣人”的简称，即醉酒。曹魏时徐邈喜欢喝酒，称酒清者为圣人，酒浊者为贤人。中：读去声，动词，“中暑”、“中毒”之“中”，此为饮清酒而醉，故曰中圣。\n迷花：迷恋花草，此指陶醉于自然美景。事君：侍奉皇帝。\n高山：言孟品格高尚，令人敬仰。\n徒此揖清芬：只有在此向您清高的人品致敬了。', poem_appreciation = '李白的律诗，不屑为格律所拘束，而是追求古体的自然流走之势，直抒胸臆，透出一股飘逸之气。李白与孟浩然的友谊是诗坛上的一段佳话。二人彼此结识，固然不乏饮酒唱和、携手邀游的乐趣，但是至为重要的，则是在追求情感的和谐一致，寻求灵性飘逸的同伴和知音。史载孟浩然曾隐鹿门山，年四十余客游京师，终以“当路无人”，还归故园。而李白竟亦有类似的经历。他少隐岷山，又隐徂徕山.后被玄宗召至京师，供奉翰林。终因小人谗毁，被赐金放还。的确，笑傲王侯，宏放飘然，邈然有超世之心，这便是两位著名诗人成为知交的根本原因。这首诗就是二人友谊的见证。\n\n　　首先看其章法结构。首联即点题，揭出“吾爱”二字，亲切挚恳，言由心出，一片真情掩蔽全篇，抒发了对孟浩然的钦敬爱慕之情。“孟夫子”，点出所爱之人，扣紧题目。孟浩然比李白长十二岁，年岁既长，襟怀磊落，生性潇洒，诗才又特出，自然令李白仰慕钦敬，所以才以“夫子”相称。“夫子”非章句腐儒，那是作者鄙夷不耻的。这是对孟浩然倜傥旷放生涯的赞誉，果然，下面使补充道：“风流天下闻”。一个“爱”字是贯串全诗的抒情线索。“风流”指浩然潇洒清远的风度人品和超然不凡的文学才华。这一联提纲挈领，总摄全诗。到底如何风流，就要看中间二联的笔墨了。\n\n　　中二联好似一幅高人隐逸图，勾勒出一个高卧林泉、风流自赏的诗人形象。作者集中笔墨刻画这位儒雅悠闲的“孟夫子”形象：“红颜弃轩冕，白首卧松云”。“红颜”对“白首”，当是概括了孟浩然漫长的人生旅程，“轩冕”对“松云”，则象征着仕途与隐遁,象征着富贵与淡泊.前者是多少人梦寐以求的。一边是达官贵人的车马冠服，一边是高人隐士的松风白云，浩然宁弃仕途而取隐遁，通过这一弃一取的对比，突出了他的高风亮节。“白首”句着一“卧”字，活画出人物风神散朗、寄情山水的高致。如果说颔联是从纵的方面写浩然的生平，那么颈联则是在横的方面写他的隐居生活。在皓月当空的清宵，他把酒临风，往往至于沉醉，有时则于繁花丛中，流连忘返。颔联采取由反而正的写法，即由弃而取，颈联则自正及反，由隐居写到不事君。纵横正反，笔姿灵活。\n\n　　中二联是在形象描写中蕴含敬爱之情，尾联则又回到了直接抒情，感情进一步升华。浩然不慕荣利、自甘淡泊的品格已写得如此充分，在此基础上将抒情加深加浓，推向高潮，就十分自然，如水到渠成。仰望高山的形象使敬慕之情具体化了，但这座山太巍峨了，因而有“安可仰”之叹，只能在此向他纯洁芳馨的品格拜揖。这样写比一般地写仰望又翻进了一层，是更高意义上的崇仰，诗就在这样的赞语中结束。\n\n　　其次诗在语言上也有自然古朴的特色。首联看似平常，但格调高古，萧散简远。它以一种舒展的唱叹语调来表达诗人的敬慕之情，自有一种风神飘逸之致，疏朗古朴之风。尾联也具有同样风调。中二联不斤斤于对偶声律，对偶自然流走，全无板滞之病。谢榛《四溟诗话》曾谓，“红颜”句与“迷花”句，“两联意颇相似”，其中运用“互体”，耐人寻味：“弃轩冕”、“卧松云”是一个事情的两个方面。这样写，在自然流走之中又增加了摇曳错落之美。诗中用典，融化自然，不见斧凿痕迹。如“中圣”用曹魏时徐邈的故事，他喜欢喝酒，将清酒叫作圣人，浊酒叫作贤人，“中圣”就是喝醉酒之意，与“事君”构成巧妙的对偶。“高山”一句用了《诗经·小雅·车舝》中“高山仰止，景行行止”的典故，后来司马迁又在《孔子世家》中用来赞美孔子。这里既是用典，又是形象描写，即使不知其出处，也仍能欣赏其形象与诗情之美。而整个诗的结构采用抒情——描写——抒情的方式。开头提出“吾爱”之意，自然地过渡到描写，揭出“可爱”之处，最后归结到“敬爱”。依感情的自然流淌结撰成篇，所以像行云流水般舒卷自如，表现出诗人率真自然的感情。', poem_tags = '唐诗三百首,赠别,敬爱' WHERE poem_title = '赠孟浩然' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '有个出生在北方不认识菱角的人，在南方做官，（一次）他在酒席上吃菱角，（那个人）连角壳一起放进嘴里吃。有人对他说：“吃菱角必须去掉壳再吃。”那人为了掩饰自己的缺点，（护住自己的无知），说：“我并不是不知道，连壳一起吃进去的原因，是想要清热解毒。”问的人说：“北方也有这种东西吗？”他回答说：“前面的山后面的山，哪块地没有呢？”\n\n　　菱角生长在水中,（他）却说是在土里生长的，这是因为他为了装作有学问，硬要把不知道的说成知道的。', poem_notes = '北人：北方人。\n识：知道。\n菱：俗称菱角，形状像牛头，紫红色，水生植物，果实可以煮着吃。性喜温暖和充足阳光，盛产于我国 中部和南部。果实有硬壳。\n仕于：（仕途）在……做官。于， 在。\n席：酒席。\n啖：吃。\n并壳：连同皮壳。\n或：有人。\n曰：说。\n食：食用，在这里可以指吃。\n去：去除，去掉。\n护：掩饰。\n短：缺点，短处,不足之处。\n并：一起。\n欲：想要。\n以：用来。\n答：回答。\n何：哪里。\n而：表示转折，此指却\n坐：因为，由于。\n强（qiǎng)：本文中指“勉强”。', poem_tags = '小学文言文,哲理,故事,讽刺,写人' WHERE poem_title = '北人食菱' AND poem_author = '江盈科';
UPDATE edu_poem SET poem_translation = '译文 　　船儿前行，河水溅起，参差的绿荷在荡漾，倚在船边的栏杆旁，风一阵阵的吹来，摇动着一柄柄荷叶，送来缕缕清香。要多多感谢那些浣纱的女子，她们没来采摘荷叶，这样，在雨中荷叶还可以遮盖戏水的鸳鸯。', poem_tags = '咏物,荷叶' WHERE poem_title = '莲叶' AND poem_author = '郑谷';
UPDATE edu_poem SET poem_translation = '片刻的时光，有限的生命，宛若江水东流，一去不返，深感悲伤。于是，频繁的聚会，借酒消愁，对酒当歌，及时行乐，聊慰此有限之身。\n若是登临之际，放眼辽阔河山，突然怀思远别的亲友；就算是独处家中，看到风雨吹落了繁花，更令人感伤春光易逝。不如在酒宴上，好好爱怜眼前的人。\n\n英译\nWhat can a short-lived man do with the fleeting year and soul-consuming separations from his dear? Refuse not banquet when fair singing girls appear!\nWith hills and rills in sight, I miss the far-off in vain. How can I bear the fallen blooms in wind and rain! Why not enjoy the fleeting pleasure now again?', poem_notes = '一向：一晌，片刻，一会儿。年光：时光。有限身：有限的生命。\n等闲：平常，随便，无端。\n销魂：极度悲伤，极度快乐。\n莫辞频：频，频繁。不要因为次数多而推辞。\n怜取眼前人：元稹《会真记》载崔莺莺诗：“还将旧来意，怜取眼前人。”怜：珍惜，怜爱。取：语助词。', poem_appreciation = '该词是宴会上即兴之作。下片首两句虽然仍是念远伤春，但气度较大，从放眼河山到风雨惜别，引出眼前人，并与上片别宴离歌前后呼应。\n\n　　词中所写的并非一时所感，也非一事，而是反映了作者人生观的一个侧面：悲年光之有限，感世事之无常；慨叹空间和时间的距离难以逾越，慨叹对已逝美好事物的追寻总是徒劳，在山河风雨中寄寓着对人生哲理的探索。词人幡然感悟，认识到要立足现实，牢牢地抓住眼前的一切。\n\n　　“ 一向年光有限身。”，劈空而来，语甚警炼。惜春光之易逝，感盛年之不再，有撼人心魄的效果。紧接“等闲”句，加厚一笔。词中所写的，不是生离，更不是死别，而只不过是寻常的离别而已。“等闲”二字，殊不等闲，具见词人之深于情。在短暂的人生中，别离是不只一次会遇到的，而每一回离别，都占去有限年光的一部分，词人唯有强自宽解：“ 酒筵歌席莫辞频”。痛苦是无益的，不如对酒当歌， 自遣情怀吧。这句写及时行乐，聊慰此有限之身。\n\n　　上片起调不做任何铺垫，直言年华有限，稍纵即逝，以精炼的语言表达富有深度的哲理，让人不觉为之一振。紧接着，词人将离别看成是平常事，可见人的一生离别之多，因而“易销魂”，但词人转而又写“酒筵歌席莫辞频”，表达人生短暂，莫为离别伤神，应当及时行乐的思想。\n\n　　过片二语，气象宏阔，意境莽苍，以健笔写闲情，兼有刚柔之美。两句是设想之辞。若是登临之际，放眼辽阔的河山，徒然地怀思远别的亲友；就算是独处家中，看到风雨摧落了繁花，更令人感伤春光易逝。语本李峤《汾阴行》：“山川满目泪沾衣，富贵荣华能几时？”作者不欲刻意去伤春伤别，故要想办法从痛苦中解脱出来。\n\n　　“不如怜取眼前人。”意谓去参加酒筵歌席，好好爱怜眼前的歌女。作为富贵宰相的晏殊，他不会让痛苦的怀思去折磨自己，也不会沉湎于歌酒之中而不能自拔，他要“怜取眼前人”，也只是为了眼前的欢娱而已，这是作者对待生活的一贯态度。\n\n　　下片抒情。起首两句为空想之辞：到了登临之时，放眼望去尽是大好河山，不禁徒然思念起远方的友人；等到风雨吹落繁华之际，才发现春天易逝，不禁更生伤春愁情。这两句词意境开阔、辽远，表现出词人对时空不可逾越，消逝的事物不可复得的感慨。结句中，词人以“不如”一词转折，再次表达了自己及时享乐的思想：与其徒劳地思念远方的亲友，因风雨摇落的花朵而伤怀，不如实际一些，珍惜眼前朋友的情谊。这也是词人对待生活的一种态度。\n\n　　这首词又是《珠玉词》中的别调。大晏的词作，用语明净，下字修洁，表现出闲雅蕴藉的风格；而在本词中，作者却一变故常，取景甚大，笔力极重，格调遒上。抒写伤春念远的情怀，深刻沉着，高健明快，而又能保持一种温婉的气象，使词意不显得凄厉哀伤。', poem_tags = '宋词三百首,婉约,感叹,离别' WHERE poem_title = '浣溪沙·一向年光有限身' AND poem_author = '晏殊';
UPDATE edu_poem SET poem_translation = '成群的鸡正在乱叫，客人来时，鸡又争又斗。\n把鸡赶上了树端，这才听到有人在敲柴门。\n四五位村中的年长者，来慰问我由远地归来。\n手里都带着礼物，从榼里往外倒酒，酒有的清，有的浊。\n一再解释说：“酒味之所以淡薄，是由于田地没人去耕耘。\n战争尚未停息，年轻人全都东征去了。”\n请让我为父老歌唱，在艰难的日子里， 感谢父老携酒慰问的深情。\n吟唱完毕，我不禁仰天长叹，在座的客人也都热泪纵横不绝，悲伤之至。', poem_notes = '正，一作“忽”。斗争，争斗；搏斗。一作“正生”。\n柴荆，犹柴门，也有用荆柴、荆扉的。最初的叩门声为鸡声所掩，这时才听见，所以说“始闻”。按养鸡之法，今古不同，南北亦异。《诗经》说“鸡栖于埘”，汉乐府却说“鸡鸣高树颠”，又似栖于树。石声汉《齐民要术今释》谓“黄河流域养鸡，到唐代还一直有让它们栖息在树上的，所以杜甫诗中还有‘驱鸡上树木’的句子”。按杜甫《湖城东遇孟云卿复归刘颢宅宿宴饮散因为醉歌》末云“庭树鸡鸣泪如线”。湖城在潼关附近，属黄河流域，诗作于将晓时，而云“庭树鸡鸣”，尤足为证。驱鸡上树，等于赶鸡回窝，自然就安静下来。\n问，问遗，即带着礼物去慰问人，以物遥赠也叫做“问”。父老们带着酒来看杜甫，所以说“问我”。\n榼（kē），酒器。浊清，指酒的颜色。\n苦辞酒味薄，是说苦苦地以酒味劣薄为辞。苦辞，就是再三地说，觉得很抱歉似的，写出父老们的淳厚。下面并说出酒味薄的缘故。苦辞、苦忆、苦爱等也都是唐人习惯语，刘叉《答孟东野》诗：“酸寒孟夫子，苦爱老叉诗。”都不含痛苦或伤心的意思。苦，一作“莫”。黍（shǔ），黍子。\n兵革，一作“兵戈”，指战争。童，一作“郎”。\n请为父老歌，一来表示感谢，二来宽解父老。但因为是强为欢笑，所以“歌”也就变成了“哭”。“艰难”句就是歌词。“艰难”二字紧对父老所说的苦况。来处不易，故曰艰难。惟其出于艰难，故见得情深，不独令人感，而且令人愧。从这里可以看到人民的品质对诗人的感化力量。\n杜甫是一个“自比稷与契”、“穷年忧黎元”的诗人，这时又正作左拾遗，面对着这灾难深重的“黎元”，而且自己还喝着他们的酒，不得不叹，不得不仰天而叹以至泪流满面。', poem_tags = '初中古诗,生活,感激' WHERE poem_title = '羌村三首·其三' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '酒杯用的是琉璃钟，酒是琥珀色的，还有珠红的。经过烹、炮的马肉（龙）和雄雉（凤）拿到口中吃的时候，还能听到油脂被烧烤时的油爆声，像是在哭泣。用绫罗锦绣做的帷幕中充满了香气。罗帏之中，除了食品与酒的香气外，还有白齿的歌伎的吟唱和细腰的舞女和着龙笛的吹奏、鼍鼓的敲击在舞蹈。宴饮的时间是一个春天的黄昏，他们已欢乐终日了，他们饮掉了青春，玩去了如花的大好时光。桃花被鼓声震散了，被舞袖拂乱了，落如红雨，他们把如花的青春白白地浪费了。我奉劝你们要像他们那样，终日喝个酩酊大醉吧，由于酒已被你们喝光，酒鬼刘伶坟上已经无酒可洒了！', poem_notes = '琉璃钟：形容酒杯之名贵。\n琥珀：琥珀是数千万年前的树脂被埋藏于地下，经过一定的化学变化后形成的一种树脂化石，是一种有机的似矿物。琥珀的形状多种多样，表面常保留着当初树脂流动时产生的纹路，内部经常可见气泡及古老昆虫或植物碎屑。颜色一般为黄红色，透明到半透明。这里借喻酒色透明香醇。\n真珠红：真珠即珍珠，这里借喻酒色。\n烹龙炮凤：指厨肴珍异。', poem_appreciation = '这首诗将一个宴饮歌舞的场面写的缤纷绚烂，有声有色，形神兼备，兴会淋漓，并且以精湛的艺术技巧表现了诗人对人生的深切体验。\n\n　　这首诗的前五句描写一幅奇丽熏人的酒宴图，场面绚丽斑斓，有声有色，给读者极强烈的感官刺激。作者似乎不遗余力地搬出华艳词藻、精美名物，目不暇接：“琉璃钟”、“琥珀浓”、“真珠红”、“烹龙炮风”、“罗帏绣幕”，作者用这样密集的华丽字眼描绘了一场华贵丰盛的筵宴。其物象之华美，色泽之瑰丽，简直无以复加。\n\n　　诸物象之间没有动词连接，就像一组蒙太奇镜头，将画面与画面按照内在逻辑顺序一一呈现出来。杯、酒、滴酒的槽床……这些具体意象的相继出现，给读者酒宴进行着的意念。这种省略叙写语言的手法，不但大大增加了形象的密度，同时也能启迪读者活跃的联想，使之主动地去填补、丰富那物象之间的空白。\n\n　　“吹龙笛，击鼍鼓，皓齿歌，细腰舞。”四句写宴乐的鼓点愈来愈急，连串三字句法衬得歌繁舞急，仅十二字，就将音乐歌舞之美妙写得尽态极妍。不仅让读者目不暇视，甚至耳不暇接。这似乎已不是普通宴饮，而是抵死的狂欢。下面的诗句作者开始解释这炊金馔玉，浩歌狂舞的原因。\n\n　　“况是青春日将暮，桃花乱落如红雨。”春光正美，太阳却冷酷地移向地平线；青春正美，白发却已在悄悄滋长。曾在繁茂的桃花园中，看花瓣随风如雨而落，那真是令人目眩神迷的美。但每一秒的美丽，都是以死亡为代价的。何等奢侈的美丽。人们伸出手想挽留残春，但最终留下的，只是那空荡荡的枝头和指间的几片残红。在这凄艳的花雨中，在这渐渐拉长的日影下，愈转愈急的歌弦舞步是想追上时间的脚步，在时间鼓点均匀而无情的敲击声中，入唇的玉液琼浆己变得苦涩。\n\n　　“劝君终日酩酊醉，酒不到刘伶坟上土！”诗的前一部分是大段关于人间乐事瑰丽夸张的描写：美酒佳肴，欢歌曼舞，人生之乐似乎莫过于此。但结尾笔锋倏转，出人意料地出现了死的意念和“坟上土”的惨淡形象，透露出一片苦涩幽怨的意绪。时光难逗留，诗人遂道，罢了，对酒当歌，人生几何，既是壶中日月长，就多喝几杯，终日酩酊吧，无知无觉也就没有困扰了。何况哪怕好酒如刘伶，死后想喝酒亦不可得。可酒并不是真的就能令人忘忧。刘伶“一醉一石，五斗解醒”也未必真的逃避了痛苦。狂呼痛饮，及时行乐固然痛快，但是，即使秉烛夜游，人生又有几何，再回首已百年身，酒闲人寂之后，留下的只有深沉的孤独和空虚之感。况且生时的辉煌更加衬托出死后的悲凉，正是前后这种极度的反差和不协调给读者带来极大的震撼。人间乐事极力地反衬出死的可悲，终日醉酒和暮春之愁思又回过来表露出生的无聊，这就是诗人内心深处所隐藏的死既可悲而生亦无聊的最大的矛盾和苦闷。人生总难免面对差别，在差别面前，庄子喜欢否定它，以求心灵的宽慰和淡泊；作者李贺则喜欢确认它、甚至放大它，以强化主体对生命、生活的敏感和执著。他为此宁愿悲愤伤感，宁愿陷入感性的深渊而不愿自拔。\n\n　　这首诗以幽遽朦胧、瑰艳凄冷的意境，生动灵澈、神奇超常的意象，构设意与境浑的美学特质，充分表达诗人身处病态社会的烦闷、压抑、凄凉与愤激心绪，给读者以深刻的精神启示和审美感受。', poem_tags = '乐府,宴饮,讽喻,人生' WHERE poem_title = '将进酒' AND poem_author = '李贺';
UPDATE edu_poem SET poem_translation = '南山乔木大又高，树下不可歇阴凉。\n汉江之上有游女，想去追求不可能。\n汉江滔滔宽又广，想要渡过不可能。\n江水悠悠长又长，乘筏渡过不可能。\n\n柴草丛丛错杂生，用刀割取那荆条。\n姑娘就要出嫁了，赶快喂饱她的马。\n汉江滔滔宽又广，想要渡过不可能。\n江水悠悠长又长，乘筏渡过不可能。\n\n柴草丛丛错杂生，用刀割取那蒌蒿。\n姑娘就要出嫁了，赶快喂饱小马驹。\n汉江滔滔宽又广，想要渡过不可能。\n江水悠悠长又长，乘筏渡过不可能。', poem_notes = '休思：休思。休：止息也；思：语气助词，没有实义。\n汉：指汉水。游女：在汉水岸上出游的女子。\n江：指长江。永：水流很长。\n方：渡河的木排。这里指乘筏渡河。\n翘翘：众也，秀起之貌。错薪：杂乱的柴草。\n楚：杂薪之中尤翘翘者\n秣(mò)：喂马。\n蒌(lóu)：草名，即蒌蒿', poem_appreciation = '从结构形式上分析，《汉广》全篇三章，前一章独立，后二章叠咏，同《诗经》中其他重章叠句的民歌，似无差异。但从艺术意境看，三章层层相联，自有其诗意的内在逻辑。可析而为二。\n\n　　首先，全诗三章的起兴之句，传神地暗示了作为抒情主人公的青年樵夫，伐木刈薪的劳动过程。方氏由此把《汉广》诗旨概括为“江干樵唱”，否定其恋情诗的实质，仍不免迂阔；但见出起兴之句暗示了采樵过程，既有文本依据，也是符合劳动经验的。\n\n　　其次，从结构形式看，首章似独立于二、三两章；而从情感表现看，前后部分紧密相联，细腻地传达了抒情主人公由希望到失望、由幻想到幻灭，这一曲折复杂的情感历程。有希望有追求，才有失望有失落；但诗篇于此未作明言，对这位青年当年追求思恋的一往深情，让读者得之言外。诗篇从失望和无望写起，首章八句，四曰“不可”，把追求的无望表达得淋漓尽致，不可逆转。一般把首句视为起兴；如果换一种读法，把“汉有游女，不可求思”置于首位，那么，“南有乔木，不可休思”便可视为比喻，连同“汉之广矣，不可泳思”、“江之永矣，不可方思”，构成一组气势如潮的博喻；瞻望难及的无限怅惘之情，也表现得更为强烈。当年苦恋追求，今日瞻望难及。但心不甘、情难拔，于是由现实境界转入幻想境界。三、三两章一再地描绘了痴情的幻境：有朝“游女”来嫁我，先把马儿喂喂饱；“游女”有朝来嫁我，喂饱驹儿把车拉。但幻境毕竟是幻境，一旦睁开现实的眼睛，便更深地跌落幻灭的深渊。他依然痴情而执着，但二、三两章对“汉广”、“江永”的复唱，已是幻境破灭后的长歌当哭，比之首唱，真有男儿伤心不忍听之感。总之，诗章前后相对独立，情感线索却历历可辨。抒情主人公是位青年樵夫。他钟情一位美丽的姑娘，却始终难遂心愿。情思缠绕，无以解脱，面对浩渺的江水，他唱出了这首动人的诗歌，倾吐了满怀惆怅的愁绪。\n\n　　陈启源《毛诗稽古编》把《汉广》的诗境概括为“可见而不可求”。这也就是西方浪漫主义所谓的“企慕情境”，即表现所渴望所追求的对象在远方、在对岸，可以眼望心至却不可以手触身接，是永远可以向往但永远不能到达的境界。《秦风·蒹葭》也是刻划“企慕情境”的佳作，与《汉广》比较，则显得一空灵象征，一具体写实。《蒹葭》全篇没有具体的事件、场景，连主人是男是女都难以确指，诗人着意渲染一种追求向往而渺茫难即的意绪。《汉广》则相对要具体写实得多，有具体的人物形象：樵夫与游女；有细徽的情感历程：希望、失望到幻想、幻灭；就连“之子于归”的主观幻境和“汉广江永”的自然景物的描写都是具体的。不为无见。当然，空灵象征能提供广阔的想像空间，而具体写实却不易作审美的超越。钱锺书《管锥编》论“企慕情境”这一原型意境，在《诗经》中以《秦风·蒹葭》为主，而以《周南·汉广》为辅，其原因或许就在于此。', poem_tags = '诗经,爱情' WHERE poem_title = '汉广' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '春天回到了哪里？找不到它的脚印，四处一片沉寂，如果有人知道春天的消息，喊它回来同我们住在一起。\n谁也不知道春天的踪迹，要想知道，只有问一问黄鹂。那黄鹂千百遍地宛转啼叫，又有谁能懂得它的意思？看吧，黄鹂鸟趁着风势，飞过了盛开的蔷薇。', poem_notes = '寂寞：清静，寂静。\n无行路：没有留下春去的行踪。行路，指春天来去的踪迹。\n唤取：换来。\n谁知：有谁知道春的踪迹。\n问取：呼唤，询问。取，语助词。\n黄鹂（lí）：黄鹂：又叫黄莺、黄鸟。身体黄色自眼部至头后部黑色，嘴淡红色，啼声非常悦耳，食森林中的害虫。益鸟。\n百啭：形容黄鹂宛转的鸣声。啭，鸟鸣。\n解：懂得，理解。\n因风：顺着风势。\n蔷薇（qiáng wēi）：花木名。品类甚多，花色不一，有单瓣重瓣，开时连春接夏，有芳香，果实入药。', poem_appreciation = '这是一首惜春词，表现作者惜春的心情。上片惜春在不知不觉中过去；下片惜春之无踪影可以追寻。用笔委婉曲折，层层加深惜春之情。直至最后，仍不一语道破，结语轻柔，余音袅袅，言虽尽而意未尽。作者以拟人的手法，构思巧妙，设想新奇。创造出优美的意境。\n\n　　上片开首两句“春归何处？寂寞无行路。”以疑问句，对春的归去提出责疑，春天回到哪里去了，为什么连个踪影也没有，一个“归”字，一个“无行路”，就把春天拟人化了。“若有人知春去处，唤取归来同住？”两句，转而询问有谁知道春天的去处，要让他把“春天”给叫喊回来。这是一种设想，是有意用曲笔来渲染惜春的程度。使词情跌宕起伏，变化多端。\n\n　　下片过头两句，把思路引到物象上，“春无踪迹谁知，除非问取黄鹂。”既然无人能知道春天的去处，看来只好去问黄鹂了，因为黄鹂是在春去夏来时出现，它应该知道春天的消息。这种想象也极为奇特，极富情趣。后两句“百啭无人能解，因风飞过蔷薇”，这是对现实的描述。上面想象春天踪迹，也许黄鹂可以知道，然而嘤嘤鸟语，谁人能解?它不过也是自然中的一小生物而已，仅看一阵风起，它便随风飞过蔷薇花那边去了。于是春之踪迹，终于无法找寻，而心头的寂寞也就更加重了。\n\n　　词中以以清新细腻的语言，表现了词人对美好春光的珍惜与热爱，抒写了作者对美好事物的执着和追求。全词构思新颖委婉，思路回环反复；笔情跳脱，风格清奇；语言轻巧，淡雅饶味；有峰回路转之妙，有超轶绝尘之感。', poem_tags = '宋词三百首,婉约,惜春' WHERE poem_title = '清平乐·春归何处' AND poem_author = '黄庭坚';
UPDATE edu_poem SET poem_translation = '置身高楼，凭高看去，中秋的月夜，长空万里无云，显得更为辽阔无边。月亮的光辉从天上照射下来，使秋天的碧空沉浸在一片清冷之中。在月宫的琼楼玉宇上，仙女们乘鸾凤自由自在地来来往往，我向往月宫中的清净自由，秀丽的江山像图画般的美丽，看过去在朦胧的月色里，树影婆娑。\n现在我把天上的明月和身边自己的影子当成知心朋友和他一起起舞，希望愉快地度过如此良宵，邀月赏心，用酒浇愁，但悲愁还在。不要辜负了这良辰美景，此时此刻，唯有月亮才是我的知音，渴望乘风归去，在明净的月宫里，把横笛吹得响彻云霄，唤起人们对美好境界的追求和向往。', poem_notes = '元丰五年八月十五日在黄州作。念奴娇：南北曲均有。属大石调。字句格律与词牌前半阕同。南曲用作引子，北曲用于套曲中。另北曲大石调有《百字令》，别名《念奴娇》，与词牌全阕同，用为小令。\n桂魄：月亮的别称。古人称月体为魄，又传月中有桂树，故称月亮为“桂魄”。\n“冷浸”句：秋天的碧空浸透着清冷的月光。\n玉宇琼楼：传说中月宫里神仙居住的楼宇。形容月中宫殿的精美。\n乘鸾：《异闻录》：“开元中，明皇与申天师游月中，见素娥十余人，皓衣乘白鸾， 笑舞于广庭大桂树下。”\n清凉国：唐陆龟蒙诗残句：“溪山自是清凉国。”\n烟树：烟雾笼罩的树木。历历：清楚可数。\n翻然：回飞的样子。\n鹏翼：大鹏之翅。', poem_appreciation = '古往今来，中秋之月激发过文人多少丰富的情感和无穷的想象，苏东坡在熙宁九年（1076）写过的脍炙人口的《水调歌头》（明月几时有），尽情驰骋对月宫的幻想，表达超脱尘俗和依恋现实的矛盾，倾吐对情同手足的胞弟的思念。\n\n　　词的开头“凭高眺远，见长空万里，云无留迹。”是写万里无云的中秋夜月。本来在中秋月夜，长空万里无云，是人们常见的，没有什么稀奇。但这里作者加上“凭高眺远”四字，就使得境界全然不同。作者置身高楼，凭高望远，所以视野开阔，而使得长空显得更为辽阔无边，毫无尽处，引人入胜。\n\n　　“桂魄飞来，光射处，冷浸一天秋碧。”由晴空写到明月。古时称月为魄，传说月中有桂树，故称月亮为“桂魄”。意思是说，月儿的光辉从天上飞来，它所照射的地方，整个秋天的碧空都沉浸在清冷之中。这两句描绘了一个月光照耀的清辉夜色，给人以清凉的感觉。这竟引起了作者无限的幻想，以寄托着他的精神世界：”玉宇琼楼，乘鸾来去，人在清凉国。“作者让他的想象翅膀飞翔，幻想出月宫中有琼楼玉宇，仙女们乘飞鸾自由来往，那里是一个清凉的境地。据《异闻录》记载，唐玄宗一次游月宫，”见素娥十余人，皓衣，乘白鸾，笑舞于广庭大桂树下。“所以用”飞鸾而去“，想象月宫中仙人乘鸾自由来往。作者这样想象，究竟有什么意义？从他当时所处的黑暗现实、不得自由的环境来看，不能说和现实无关。应该说，正是由于他处在那样一个不得自由的闲官职位上，才有向往月宫清静自由的幻想。\n\n　　”江山如画，望中烟树历历。“他想象着从月宫往下界眺望：秀丽的江山像图画那样的美，清晰可辨的烟火，历历在望。人间的江山越美，就越反衬出现实社会越丑，就越能见出作者内心世界的苦闷。\n\n　　然而，作者毕竟是一个处于逆境而善于而善于自我解脱的人。所以，下片笔锋一转写道：“我醉拍手狂歌，举杯邀月，对影成三客。”这三句化用李白“举杯邀明月，对影成三人”的诗句。作者通过高超的想象，把天上的明月和身边的影子当做知心朋友，一起欢乐。这样写，既使词染上了浓厚的浪漫色彩，给人有一种奇异之感；又真实地展现出他孤单、凄凉的影子。作者之所有“举杯邀月”，正是意味着他对当时社会的憎恶，意味着他对权贵们的讨厌。\n\n　　苏轼尽管邀月赏心，把酒浇愁，但悲愁仍在，这就使他不能不起舞了：“起舞徘徊风露下，今夕不知何夕？”希望愉快地度此中秋良夜，不要辜负这良辰美景。“今夕”句化用《诗经》“今夕何夕，见此良人”，表示这是一个良宵。作者之所以月下起舞，并非愉快而歌，得意而舞，恰恰是为了消除这股愁闷与抑郁不平之气。正如“长言之不足，故嗟叹之。嗟叹知不足，故不知手之舞之足之蹈之也。”因此，这里似乎使人听到他强颜为笑之声，但又使人深深地感到他觉得月亮才是他的知音。唯其如此，所以，他便幻想起遨游月宫来了：“便欲乘风，翻然归去，何用骑鹏翼！水晶宫里，一声吹断横笛。”他渴望乘风归去，在明净的月宫里，把横笛吹得响彻云霄，唤起人么对美好境界的追求与向往。豪情溢于纸背，令人读之神思飘渺。当然这种追求是虚幻的，在现实中不可能实现，但作者这样写，正是人在苦闷时寻求解脱、自我安慰的无可奈何的举动；它表现出作者对自由生活、美好现实的追求。\n\n　　总的来说，这是一篇狂放不羁。洒脱飘逸的作品。当时，苏轼居住黄州，政治处境仍然没有得到改善。为了排遣个人政治上的失意的苦闷，为了摆脱庸俗污浊的现实，于是他越发热烈追求那超凡的清空境界。虽然是带有消极成分，不值得称颂，但它之所以产生，正是由于黑暗现实所促成。它是深深滴植根于社会土壤之中的，我们不能忽视这一点。', poem_tags = '中秋节,月亮,想象,向往' WHERE poem_title = '念奴娇·中秋' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '齐宣王让人吹竽，一定要三百人的合奏。南郭处士请求给齐宣王吹竽，宣王对此感到很高兴，拿数百人的粮食供养他。齐宣王去世了，齐湣王继承王位，他喜欢听一个一个的演奏，南郭处士听后便逃走了。', poem_notes = '节选自《韩非子·内储说上》。这则寓言讽刺了无德无才、招摇撞骗的骗子，提醒人们只要严格把关，骗子就难行骗。告诉人们要有真才实学。滥：失实的，假的。竽：一种古代乐器，即大笙。“滥竽”即不会吹竽。充数：凑数。\n齐宣王：战国时期齐国的国君。姓田，名辟疆。\n使：让。\n必：一定，必须，总是。\n南郭：复姓。\n处士：古代称有学问、有品德而没有做官的人为处士，相当于“先生”\n请：请求，要求。\n为：给，替。\n说：通“悦”，对......感到高兴。\n廪食（lǐn sì）以数百人：拿数百人的粮食供养他。廪：粮食。食：供养。\n以：用，拿。\n湣王：齐国国君，宣王的儿子，在宣王死后继位。姓田，名地或遂。\n好∶喜欢，喜悦，此处是喜欢。\n逃：逃跑。\n立：继承王位。\n竽：古代的一种乐器，像如今的笙。', poem_tags = '小学文言文,寓理,故事' WHERE poem_title = '滥竽充数' AND poem_author = '韩非';
UPDATE edu_poem SET poem_translation = '注释 兰舟：用木兰做的船。木兰树质坚硬耐腐蚀，宜于做船。马戴《楚江怀古》：“猿啼洞庭树，人在木兰舟。” 簟（dian）：竹席。披襟散发：敞开衣襟，散开头发。', poem_tags = '夏天,荷花' WHERE poem_title = '得胜乐·夏' AND poem_author = '白朴';
UPDATE edu_poem SET poem_translation = '清晨，满脸稚气的小孩，将夜间冻结在盘中的冰块脱下，提在手中。\n轻轻敲打，冰块发出穿林而过的响声，当欣赏者正醉心于那穿林而过的响声时，忽然却听到了另一种声音--冰块落地，发出了如玻璃破碎的声音。', poem_notes = '稚子：指幼稚、天真的孩子。\n脱晓冰：在这里指儿童晨起，从结成坚冰的铜盆里剜冰。\n铮：指古代的一种像锣的乐器。\n磬（qìng）：四声 古代打击乐器，形状像曲尺，用玉、石制成，可以悬挂在墙上。\n玻璃：指古时候的一种天然玉石，也叫水玉，并不是现在的玻璃。', poem_appreciation = '全诗摄取瞬间快景避开直接描写，用生动形象的“穿林”响声和贴切的比喻，用老者的眼光开掘稚子的情趣。\n\n　　诗中孩子弄冰的场景，充满了乐趣：心态上，寒天“弄冰”，童心炽热；色泽上，“金”盘“彩”丝串“银”冰；形态上，是用“金盘”脱出的‘‘银铮”，圆形；声音上，有 “玉罄穿林响”的高亢，忽又转 作“玻璃碎地声”的清脆。全诗形色兼具以感目，声意俱美以悦耳赏心，绘声绘色地表现出儿童以冰为钲、自得其乐的盎然意趣。\n\n　　全诗突出一个“稚”字。稚气和乐趣能使儿童忘却严冬的寒冷，保持他一如既往的活力和快乐。孩童与老人在心理特征上有诸多的相通之处，唯其如此，孩童的“脱冰作戏”的场景在老人的眼里才有依依情趣。\n\n　　正是以这种老少相通的心理特征为审美基点，杨万里通过“以稚为老”的手法使童趣化为诗趣，一方面从稚子的心理出发，描写“脱冰”的动作细节；另一方面基于世人的心理去感受，欣赏其行为细节，这样孩童的稚气与老人的“天真”相映成趣，融为形之于笔端的盎然诗意。诗人发自内心地尊重儿童的天真，才能把孩子玩冰的情趣描绘得如此真切酣畅。', poem_tags = '冬天,儿童,生活' WHERE poem_title = '稚子弄冰' AND poem_author = '杨万里';
UPDATE edu_poem SET poem_translation = '注释 端午：端午节，农历五月初五日。自：自从。 屈原（前340—前278）：中国最早的浪漫主义诗人、战国时代楚国政治家。名平，字原。因贵妃郑袖、令尹子兰、大夫靳尚等诋毁排挤，被贬黜流放。楚败于秦，郢都失陷后，自沉汨罗江。相传端午节习俗就是源自对屈原的纪念。 楚江：楚国境内的江河，此处指汨罗江。 直臣：正直之臣，此处指屈原。', poem_tags = '端午节,抒怀' WHERE poem_title = '端午' AND poem_author = '文秀';
UPDATE edu_poem SET poem_translation = '扬子江头杨柳青青春色惹人心，杨花似雪漫天飞舞愁杀渡江人。\n微风轻拂笛声幽咽离亭染暮色，你就要南下潇湘我却奔向西秦。', poem_notes = '淮（huái）上：扬州。淮：淮水。\n扬子江：长江在江苏镇江、扬州一带的干流，古称扬子江。杨柳：“柳”与“留”谐音，表示挽留之意。\n杨花：柳絮。愁杀：愁绪满怀。杀，形容愁的程度之深。\n风笛：风中传来的笛声。离亭：驿亭。亭是古代路旁供人休息的地方，人们常在此送别，所以称为“离亭”。\n潇湘（xiāo xiāng）：指今湖南一带。秦：指当时的都城长安。在今陕西境内。', poem_appreciation = '晚唐绝句自杜牧、李商隐以后，单纯议论之风渐炽，抒情性、形象性和音乐性都大为减弱。而郑谷的这首七绝则仍然保持了长于抒情、富于风韵的特点。\n\n　　“扬子江头杨柳春，杨花愁杀渡江人。”一、二两句即景抒情，点醒别离，写得潇洒不着力，读来别具一种天然的风韵。画面很疏朗，淡淡几笔，像一幅清新秀雅的水墨画。景中寓情，富于含蕴。依依袅袅的柳丝，牵曳着彼此依依惜别的深情，唤起一种“柳丝长，玉骢难系”的伤离意绪；蒙蒙飘荡的杨花，惹动着双方缭乱不宁的离绪，勾起天涯羁旅的漂泊之感。美好的江头柳色，宜人春光，在这里恰恰成了离情别绪的触媒，所以说“愁杀渡江人”。诗人用淡墨点染景色，用重笔抒写愁绪，初看似不甚协调，细味方感到二者的和谐统一。两句中“扬子江头”、“杨柳春”、“杨花”等同音字的有意重复，构成了一种既轻爽流利，又回环往复，富于情韵美的风调，使人读来既感到感情的深永，又不显得过于沉重与伤感。次句虽单提“渡江人”，但彼此羁旅漂泊，南北乖离，君愁吾亦愁，原是不言自明的。\n\n　　“数声风笛离亭晚，君向潇湘我向秦。”三、四两句，从江头景色收转到离亭别宴，正面抒写握别时情景。驿亭宴别，酒酣情浓，席间吹奏起了凄清怨慕的笛曲。即景抒情，所奏的也许正是象征着别离的《折杨柳》。这笛声正倾诉出彼此的离衷，使两位即将分手的友人耳接神驰，默默相对，思绪萦绕，随风远扬。离笛声中，天色仿佛不知不觉地暗了下来，握别的时间到了。两位朋友在沉沉暮霭中互道珍重，各奔前程——“君向潇湘我向秦”。诗到这里，突然停止，富有韵味。\n\n　　这首诗有一个别开生面和富于情韵的结尾，使得它受到较高的评价。表面上看，末句只是交待各自行程的叙述语，既乏寓情于景的描写，也无一唱三叹的抒情，实际上诗的深长韵味恰恰就蕴含在这貌似朴直的不结之结当中。由于前面已通过江头春色、杨花柳丝、离亭宴饯、风笛暮霭等一系列物象情景对离情进行反复渲染，结句的截然而止，在反激与对照中愈益显出其内涵的丰富。临歧握别的黯然伤魂，各向天涯的无限愁绪，南北异途的深长思念，乃至漫长旅程中的无边寂寞，都在这不言中得到充分的表达。“君”“我”对举，“向”字重叠，更使得这句诗增添了咏叹的情味。', poem_tags = '柳树,离别' WHERE poem_title = '淮上与友人别' AND poem_author = '郑谷';
UPDATE edu_poem SET poem_translation = '东武和余杭两地相望，但见远隔天涯云海茫茫。不知什么时候才能功成名就，衣锦还乡，到那时我与你同笑长醉三万场。\n不用像世俗的样子用酒来诉说离情别绪，痛快的饮宴从来都另有缘由。今夜拿着残灯送你归去，走过河塘，恍惚间见落泪如羊祜的却是你杨元素啊。', poem_notes = '南乡子：词牌名，唐教坊曲。《金奁集》入“黄钟宫”。唐教坊曲，原为单调，有二十七字、二十八字、三十字各体，平仄换韵。单调始自后蜀欧阳炯。南唐冯延巳始增为双调。冯词平韵五十六字，十句，上下片各四句用韵。另有五十八字体。双调五十六字，前后阕各四平韵，一韵到底。\n杨元素：即杨绘，公元1074年（熙宁七年）七月接替陈襄为杭州知州，九月，苏轼由杭州通判调为密州知府，杨再为饯别于西湖上，唱和此词。\n东武：密州治所，今山东诸城。余杭：杭州。\n“醉笑”句：唐李白《襄阳歌》：“百年三万六千日，一日须倾三百杯。”此化用其意。\n河塘：指沙河塘，在杭州城南五里，宋时为繁荣之区。\n“堕泪”句：《晋书·羊祜传》：羊祜为荆州督。其后襄阳百姓于祜在岘山游息之处建庙立碑，岁时享祭，望其碑者，莫不流涕。杜预因名之为“堕泪碑”。这里以杨绘比羊祜，“羊”、“杨”音近。', poem_tags = '地名,思念,友情' WHERE poem_title = '南乡子·和杨元素时移守密州' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '一弯蛾眉月挂在柳湾的上空，月光清朗，凉爽宜人。越中山色倒映在水平如镜的溪面上，煞是好看。淅淅沥沥的春雨，下了三天，溪水猛涨，鱼群争抢新水，夜半人静之时纷纷涌上溪头浅滩。', poem_notes = '兰溪：兰溪江，也称兰江，浙江富春江上游一支流，在今浙江省兰溪市西南。棹（zhào）歌：船家摇橹时唱的歌。\n凉月：新月。\n越：古代东南沿海一带称为越，今浙江省中部。\n桃花雨：江南春天桃花盛开时下的雨。\n棹歌：渔民的船歌。\n三日：三天。', poem_appreciation = '这是一首富于民歌风味的船歌。全诗以清新灵妙的笔触写出了兰溪的山水之美及渔家的欢乐之情。\n\n　　歌唱当地风光的民歌，除有特殊背景外（如刘禹锡《踏歌词》）取景多在日间。因为在丽日艳阳照映下，一切景物都显得生气蓬勃、鲜妍明媚，得以充分展示出它们的美。此篇却独出心裁，选取夜间作背景，歌咏江南山水胜地另一种人们不大注意的美。这是它在取材、构思上的一个显著特点。\n\n　　“凉月如眉挂柳湾”，首句写舟行所见岸边景色：一弯如眉的新月，映射着清冷的黑暗，正低挂在水湾的柳梢上。雨后的春夜，月色显得更加清澄；时值三月（从下文“桃花雨”可知），柳条已经垂缕披拂。眉月新柳，相映成趣，富于清新之感。\n\n　　“越中山色镜中看”，此句转写水色山影。浙江一带古为越国之地，故称“越中”。“山色镜中看”，描绘出越中一带水清如镜，两岸秀色尽映水底的美丽图景。句内“中”字复迭，既增添了民歌的咏叹风味啊，又传递出夜间行舟时于水中一边观赏景色，一边即景歌唱的怡然自得的情趣。\n\n　　“兰溪三日桃花雨，半夜鲤鱼来上滩。”船继续前行，不觉意间已从平缓如镜的水面驶到滩头。听到滩声哗哗，诗人才联想到连日春雨，兰溪水涨，滩声听起来也变得更加急骤了。在滩声中，似乎时不时听到鱼儿逆水而行时发出的泼刺声，诗人又不禁想到，这该是撒欢的鲤鱼趁着春江涨水，在奔滩而上了。南方二三月间桃花开时，每有绵绵春雨。这种持续不断的细雨，能使江水上涨，却不会使水色变浑，所以次句有水清如镜的描写，如果是北方的桃花汛，则自无“山色镜中看”的清澈之景。由此可见诗人观察事物描写景物的真切。因是夜中行舟，夜色本来比较黯淡朦胧，这里特意选用“桃花雨”的字面，感觉印象中便增添了黑暗的冬天色彩；夜间本来比较宁静，这里特意写到鲤鱼上滩的声响，遂使静夜增添了活泼的生命跃动气息。实际上，这里所写的“三月桃花雨”与“鲤鱼来上滩”都不是目接之景，前者因滩声喧哗而有此联想，后者因游鱼泼刺而有此猜测。两者都是诗人的想象之景。正因为多了这一层想像的因素，诗情便显得更为浓郁。\n\n　　通观全诗，可以发现，这首船歌虽然以兰溪之夜作为背景，但它着重表现的并非夜的静谧朦胧，而是兰溪夜景的清新澄澈，生趣盎然。而这，正体现出这首诗独特的民歌气韵，渔家的欢乐之情。', poem_tags = '春天,写景,山水,地名,民歌' WHERE poem_title = '兰溪棹歌' AND poem_author = '戴叔伦';
UPDATE edu_poem SET poem_translation = '长夜里，虽然放下了帘幕，小楼上依旧寒气逼人。可恨那萧萧飒飒的无情风雨，在夜里摧残着如玉的白菊。 看那白菊，不似杨贵妃的微红醉脸，也不似孙寿的娇柔愁眉。韩令偷香，徐娘傅粉，他们的行径都不能拿来与白菊相比。细细看着，屈原和陶令，孤傲高洁的品性正与白菊相宜。微风吹起，白菊的清香蕴藉，丝毫不亚于淡雅的荼蘼。\n秋天将尽，白菊愈发显得雪清玉瘦，似向人流露出它无限依恋的惜别情怀。你看它似忧愁凝聚，在汉皋解佩；似泪洒于纨扇题诗。有时是明月清风，有时是浓雾秋雨，老天让白菊在日益憔悴中度尽芳姿。我纵然爱惜，但不知从此还能将它留下多少时候。唉！世人如果都晓得爱护、欣赏，又何须再去追忆、强调屈原和陶渊明的爱菊呢？', poem_notes = '多丽：词牌名，一名“鸭头绿”，一名“陇头泉”，139字。此词是《漱玉词》中最长的一首。\n潇潇：疾厉的风雨声。一作“萧萧”。\n琼肌：指花瓣像玉一般的白菊。\n贵妃醉脸：此句意谓：杨贵妃醉酒以后的脸蛋儿，就像李正封诗中的牡丹花那样娇艳动人。\n韩令偷香：韩令，指韩寿。徐娘傅粉：徐娘，指梁元帝的妃子徐昭佩。\n看取：看着。取，语助词。\n屈平陶令：屈平是屈原的名，字原，又自名正则，字灵均。陶令：指陶渊明，一名潜，字元亮，曾任彭泽令。\n蕴藉（yùn jiè）：宽和有涵容。\n酴醾（tú mí）：即荼蘼，花名，初夏开白色花。\n秋阑：秋深。\n瘦：一作“度”。\n汉皋（gāo）解佩：汉皋，山名，在今湖北襄阳西北。佩：古人衣带上的玉饰。此处当指男子有外遇。\n纨（wán）扇题诗：纨扇，细绢制成的团扇。\n泽畔东篱：指代屈原、陶潜二位爱菊的诗人。', poem_appreciation = '在李清照的词中，“花”是出现得最多的意象。她笔下的花，不仅有人的情志，如“宠柳娇花”（《念奴娇·萧条庭院》），“梅心惊破”（《孤雁儿·藤床纸帐朝眠起》）；而且有眉、腮，如“柳眼梅腮”（《蝶恋花·暖雨晴风初破冻》）；有肌骨，如“玉骨冰肌”（《瑞鹧鸪·双银杏》）；因而也有肥瘦，如“绿肥红瘦”（《如梦令·昨夜雨疏风骤》）。菊花纤细，这里就用“揉损琼肌”来描写菊花的纤纤玉骨。然后进一步用四个历史人物来作类比反衬。贵妃醉脸，是对牡丹的比喻。李正封《咏牡丹》有“国色朝酣酒，天香夜染衣”，唐玄宗认为可比杨妃醉酒（见《松窗杂录》）。作者通过铺陈贵妃、孙寿、韩令、徐娘等典故，来说明白菊既不似杨妃之富贵丰腴，更不似孙寿之妖娆作态。其香幽远，不似韩寿之香异味袭人；其色莹白，不似徐娘之白，傅粉争妍。她是屈子所餐，陶潜所采。屈原《离骚》有“朝饮木兰之坠露兮，夕餐秋菊之落英”；陶渊明《饮酒》之五有“采菊东篱下，悠然见南山”。细赏此花，如对直臣高士，香淡风微，清芬酝藉，不减于酴釄。酴釄，即荼蘼花，花黄如酒，开于春末。\n\n　　下片续写，用一“渐”字表示时间推移，秋阑菊悴。“雪清玉瘦”呼应“揉损琼肌”，紧扣白菊在风雨中挣扎自立从开到谢的神态。这里不说人对残菊的依恋，反说菊愁凝泪洒，依依惜别。用班婕妤“汉皋解佩”的典故，以“秋扇见捐”自喻。这两个典说的都是得而复失、爱而遭弃的失落、捐弃的悲哀。怅惘之情，融入朗月清风，浓烟暗雨之中，又通过这既清朗、又迷离的境界具象化。同时，它又暗示了，菊既不同流俗，就只能在此清幽高洁，又迷蒙暗淡之境中任芳姿憔悴。\n\n　　词人不胜惜花、自惜之情，倒折出纵使怜爱之极，亦不能留花片时。情不能堪处，忽宕开作旷达语：只要人情自适其适，应时菊赏，且休忆他屈子忠贞，行吟泽畔；陶潜放逸，采菊东篱。', poem_tags = '咏物,白菊,惜花' WHERE poem_title = '多丽·咏白菊' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '地上长满了如丝的绿草，树上开满了烂漫的红花，已是暮春时节了。\n莫说你不回来，即使回来，春天也过去了。', poem_notes = '蔓：蔓延。　\n英：花。　\n无论：莫说。　\n歇：尽。', poem_tags = '古诗三百首,乐府,春天,写景,惜时' WHERE poem_title = '王孙游' AND poem_author = '谢朓';
UPDATE edu_poem SET poem_translation = '江边的城池好像在画中一样美丽，山色渐晚，我登上谢朓楼远眺晴空。两条江之间，一潭湖水像一面明亮的镜子；江上两座桥仿佛天上落下的彩虹。橘林柚林掩映在令人感到寒意的炊烟之中；秋色苍茫，梧桐也已经显得衰老。除了我还有谁会想着到谢朓北楼来，迎着萧飒的秋风，怀念谢先生呢？', poem_notes = '谢朓北楼：即谢朓楼，为南朝齐诗人谢朓任宣城太守时所建，故址在陵阳山顶，是宣城的登览胜地。谢朓是李白很佩服的诗人。\n江城：泛指水边的城，这里指宣城。唐代江南地区的方言，无论大水小水都称之为“江”。\n两水：指宛溪、句溪。宛溪上有凤凰桥，句溪上有济川桥。明镜：指拱桥桥洞和它在水中的倒影合成的圆形，像明亮的镜子一样。\n双桥：指凤凰桥和济川桥，隋开皇（隋文帝年号，公元581～600年）年间所建。彩虹：指水中的桥影。\n人烟：人家里的炊烟。\n北楼：即谢朓楼。\n谢公：谢朓。', poem_appreciation = '谢朓北楼是南齐诗人谢朓任宣城太守时所建，又名谢公楼，唐代改名叠嶂楼，是宣城的登览胜地。宣城处于山环水抱之中，陵阳山冈峦盘屈，三峰挺秀；句溪和宛溪的溪水，萦回映带着整个城郊，“鸟去鸟来山色里，人歌人哭水声中”（杜牧《题宣州开元寺水阁阁下宛溪夹溪居人》）。\n\n　　一个晴朗的秋天的傍晚，诗人独自登上了谢公楼。岚光山影，景色十分明净。诗人凭高俯瞰，“江城”犹如在图画中一样。开头两句，诗人把他登览时所见景色概括地写了出来，总摄全篇，一下子就把读者深深吸引住，一同进入诗的意境中去了。严羽《沧浪诗话》说：“太白发句，谓之开门见山。”指的就是这种表现手法。\n\n　　中间四句是具体的描写。这四句诗里所塑造的艺术形象，都是从上面的一个“望”字生发出来的。从结构的关系来说，上两句写“江城如画”，下两句写“山晚晴空”；四句是一个完整的统一体，而又是有层次的。“两水”指句溪和宛溪。宛溪源出峄山，在宣城的东北与句溪相会，绕城合流，所以说“夹”。因为是秋天，溪水更加澄清，它平静地流着，波面上泛出晶莹的光。用“明镜”来形容，用语十分恰当。“双桥”指横跨溪水的上、下两桥。上桥叫做凤凰桥，在城的东南泰和门外；下桥叫做济川桥，在城东阳德门外，都是隋文帝开皇年间（581～600年）的建筑。这两条长长的大桥架在溪上，倒影水中，诗人从高楼上远远望去，缥青的溪水，鲜红的夕阳，在明灭照射之中，桥影幻映出无限奇异的璀璨色彩。这更像是天上的两道彩虹，而这“彩虹”的影子落入“明镜”之中去了。这两句与诗人的另一名作《望庐山瀑布水》中的“飞流直下三千尺，疑是银河落九天”相似。两者同样是用比拟的手法来塑造形象，同样用一个“落”字把地下和天上联系起来；然而同中有异，异曲同工：一个是以银河比拟瀑布的飞流，一个是用彩虹写夕阳明灭的波光中双桥的倒影；一个着重在描绘其奔腾直下的气势，一个着重在显示其瑰丽变幻的色彩，两者所给予读者的美感也不一样，而诗人想象的丰富奇妙，笔致的活泼空灵，则同样十分高明。\n\n　　秋天的傍晚，原野是静寂的，山冈一带的丛林里冒出人家一缕缕的炊烟，橘柚的深碧，梧桐的微黄，呈现出一片苍寒景色，使诗人感到是秋光渐老的时候了。当时诗人的心情是完全沉浸在他的视野里，他的观察是深刻的，细致的；而他的描写又是毫不粘滞的。他站得高，望得远，抓住了一刹那间的感受，用极端凝炼的形象语言，在随意点染中勾勒出一个深秋的轮廓，深深地透漏出季节和环境的气氛。他不仅写出秋景，而且写出了秋意。他在高度概括之中，用笔丝丝入扣。\n\n　　结尾两句，从表面看来很简单，只不过和开头二句一呼一应，点明登览的地点是在“北楼上”；这北楼是谢朓所建的，从登临到怀古，似乎是照例的公式，因而李白就不免顺便说一句怀念古人的话罢了。这里值得注意是“谁念”两个字。“怀谢公”的“怀”，是李白自指，“谁念”的“念”，是指别人。两句的意思，是慨叹诗人“临风怀谢公”的心情没有谁能够理解。这就不是一般的怀古了。\n\n　　客中的抑郁和感伤，特别当摇落秋风的时节，诗人那寂寞的心情，读者是可以想象的。宣城是他旧游之地，此时他又重来这里。一到宣城，他就会怀念到谢朓，这不仅因为谢朓在宣城遗留下了像叠嶂楼这样的名胜古迹，更重要的是因为谢朓对宣城有着和诗人相同的情感。当李白独自在谢朓楼上临风眺望的时候，面对着谢朓所吟赏的山川，缅怀他平素所仰慕的这位前代诗人，虽然古今世隔，然而他们的精神却是遥遥相接的。这种渺茫的心情，反映了他政治上苦闷彷徨的孤独之感；正因为政治上受到压抑，找不到出路，所以只得寄情山水，尚友古人；他当时复杂的情怀，很难有人能理解。', poem_tags = '秋天,咏史怀古,景点' WHERE poem_title = '秋登宣城谢脁北楼' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '有个人丢了一把斧子，他怀疑是他的邻居家的儿子偷去了，他看到那人走路的样子，像是偷斧子的；看那人脸上的神色，像是偷斧子的；听他的言谈话语，像是偷斧子的；一举一动,没有一样不像是偷斧子的人。不久，他挖掘山沟时却找到了自己的斧子。之后有一天又看见他邻居的儿子，就觉得他的行为、表情、动作，都不像偷斧子的人。', poem_notes = '者：有个丢掉斧子的人。\n亡：丢掉，丢失。\n意：同“臆“，估计，怀疑，猜想。\n谷：山谷，地窑。\n其：指代邻人之子。\n窃：偷盗。\n无为而不窃斧也：没有一样不像偷斧子的人。\n他日：另一天。\n复：再,又。\n无似窃斧者：没有一点像偷斧子的样子。\n俄而掘其沟而得其斧：不久，（他）挖掘那山谷却找到了自己的斧子。\n俄：一会儿，不久。\n视：看。\n皆：都。\n行动：走路的姿势。\n颜色：表情。', poem_appreciation = '《人有亡斧者》讲述的 从前有个人丢了一把斧子，他怀疑是邻居家的儿子偷去了，他看到那人走路的样子，是偷斧子的；看那人脸上的神色，是偷斧子的；听他的言谈话语，是偷斧子的；一举一动，没有一样不像偷斧子的人。不久，他挖掘那山谷（土地时）却找到了自己的斧子。第二天又看见他邻居的儿子，就觉得他行为、表情、动作，都不像偷斧子的人。\n\n　　这则寓言说明，主观成见，是认识客观真理的障碍。当人以成见去观察世界时，必然歪曲原来客观事物的原貌。准确的判断来源于对客观事实的调查，而不是主观的猜想。\n\n　　不要多疑，重要的是要从实际出发，摆正自己的心态。\n\n　　不要随便猜疑别人。', poem_tags = '小学文言文,寓理,故事' WHERE poem_title = '人有亡斧者' AND poem_author = '吕不韦 撰';
UPDATE edu_poem SET poem_tags = '小学文言文,哲理,故事' WHERE poem_title = '父善游' AND poem_author = '吕不韦 撰';
UPDATE edu_poem SET poem_translation = '齐国有个富人，家里有很多钱，但是他的两个儿子很笨，儿子的父亲又不教他。一天，艾子对富人说：“您的儿子虽然很好，但（您的儿子）不通事务，他日后怎么能够持家呢？”富人大怒道：“我的儿子，聪明并且具有各种本领，怎么会不了解世间的各种事务呢？”艾子说：“不如试一试他,只要问你的儿子，米是从哪里来的，如果知道，我承担造谣的罪名。”父亲就叫他的儿子来问他，儿子笑嘻嘻地说：“我怎么会不知道呢？米是从布袋里取来的。”富人神情变得严肃，改变面容说：“儿子（你）太笨了，难道不知道米是从田中来的吗？”艾子说：“不是他的父亲不生他的儿子（有这样的父亲，儿子怎么会不笨呢）。”', poem_notes = '累：积攒、拥有\n克：胜任。\n敏：灵敏，聪明。\n多能：多种本领。\n妄言：乱说，造谣。\n愀然改容：神色变得严肃。改容，改变面色。\n恃：依靠，指具有。\n当：担当，承担。\n曷﹕何，怎能。\n愀然改容：神色变得严肃。改容，改变面色。\n甚：十分，很。\n以：从。', poem_tags = '小学文言文,寓言,故事,哲理' WHERE poem_title = '富人之子' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '洞庭湖边静立着的纤草，在这个中秋将至的时候，没有一丝风过的痕迹。是玉的世界，还是琼的原野？三万倾明镜般的湖水，载着我一叶细小的扁舟。皎洁的明月和灿烂的银河，在这浩瀚的玉镜中映出她们的芳姿，水面上下一片明亮澄澈。体会着万物的空明，却不知如何道出，与君分享。\n感怀这一轮孤光自照的明月啊，多少年徘徊于岭海之间，胸襟仍象冰雪一样透明。而此刻的我，正披着萧瑟幽冷的须发和衣袂，平静的泛舟在这广阔浩淼的苍溟之中。让我捧尽西江清澈的江水，细细的斟在北斗星做成的酒勺中，请天地万象统统来做我的宾客，我尽情的拍打着我的船舷，独自的放声高歌啊，怎能记得此时是何年！', poem_notes = '张孝祥：字安国，号于湖居士，南宋著名爱国词人。\n洞庭：湖名，在湖南岳阳西南。\n风色：风势。\n琼：美玉。\n着：附着。扁舟：小船。\n素月：洁白的月亮。\n明河：天河。明河一作“银河”。\n表里：里里外外。此处指天上月亮和银河的光辉映入湖中，上下一片澄明。\n岭表：岭外，即五岭以南的两广地区，作者此前为官广西。岭表一作“岭海”。\n孤光：指月光。\n肝胆：一作“肝肺”。冰雪：比喻心地光明磊落像冰雪般纯洁。\n萧骚：稀疏。萧骚一作“萧疏”。襟袖冷：形容衣衫单薄。\n沧浪：青苍色的水。沧浪一作“沧溟”。\n挹：舀。挹一作“吸”。西江：长江连通洞庭湖，中上游在洞庭以西，故称西江。\n北斗：星座名。由七颗星排成像舀酒的斗的形状。\n万象：万物。\n扣：敲击。扣一作“叩”。啸：撮口作声。啸一作“笑”。\n不知句，赞叹夜色美好，使人沉醉，竟忘掉一切（包括时间）。', poem_appreciation = '这首中秋词是作者泛舟洞庭湖时即景抒怀之作。开篇直说地点与时间，然后写湖面、小舟、月亮、银河。此时作者想起岭南一年的官宦生涯，感到自己无所作为而有所愧疚。而且想到人生苦短不免心酸，不过由于自己坚持正道，又使他稍感安慰。他要用北斗做酒勺，舀尽长江做酒浆痛饮。全词格调昂奋，一波三折。\n\n　　“洞庭春草”指的是洞庭湖加上与之相连的春草湖，点出地点，题目是《过洞庭》，词一开头就紧扣题目。“近中秋”点出时间，秋天天高气爽，“月到中秋分外明”，秋月对于生活在农业社会与大自然息息相关的古代文人来说，当是别有意味。“风色”二字值得注意，风有风向、强弱，从来没有听说过风有色彩，其实张孝祥用“风色”是有所本的，李白《庐山谣》“登高壮观天地间，大江茫茫去不还。黄云万里动风色，白波九道流雪山。”说的是黄云万里改变了风的色彩；张孝祥的“更无一点风色”说的是洞庭青草湖上，万里无云，水波不兴，不仅没有风，而且连风的影子都没有，这种表达方式富有新意，增添了一分诗意。“玉界琼田”形容的是秋月下浩浩汤汤、一碧万顷的湖水。“界”又作“鉴”，玉界也好，玉鉴也好，美玉般的琼田也好，都是以玉比喻湖水清澈透明之美，“万顷”则极言湖面之广，如此良辰美景，驾一叶扁舟游其中，该是多么惬意，这是一；点出了过洞庭的方式，进一层紧扣题目，这是二。\n\n　　紧承“更无一点风色”，从秋月写到秋水。素月分辉是说皎洁的月亮把自己的光辉分给了湖水。水里的银河是天上银河的倒影，它们有着同辉的形象。“素月”、“明河”两个意象点出了天空的特征，“分辉”、“共影”则写出了秋水长天一色的美景，尽管只有八个字，却具体而生动的显示了诗人的才华。“表里俱澄澈”是这首词主旨所在，它包含了两层意思，一层是写秋月秋水之美，美在哪里，美在澄澈。澄是水清，澈也是水清，上上下下，里里外外，没有一丝一毫浑浊，没有一丝一毫污染，这样的清澈明亮，有如非人间的琉璃世界；另一层是说三万顷湖上扁舟上的我，也有如秋月，有如秋水，我就是一个光明磊落，坦坦荡荡，言行一致，表里如一的男子汉、大丈夫。所以表里俱澄澈不仅是写景，而且也是写人，写自己品格之美。杜甫诗有“心迹喜双清”，行迹是表、心灵是里，“心迹喜双清”是杜甫的夫子自道；“表里俱澄澈”则是张孝祥的夫子自道。中国文史馆馆长袁行霈认为，“表里俱澄澈”“心迹喜双清”可以集成一副对联，而且给人提供了一个为人处世的准则，此言良是。\n\n　　屈原《离骚》“纷吾既有此内美兮，又重之以修能；扈江离与辟芷兮，纫秋兰以为佩”写出了屈子自己内美与外美的统一。张孝祥则进一步写外在世界与内在世界澄澈的相会与相合。则是一种天人合一的会合，这一会合的美妙只可意会不可言传，是人生最高、最美、最富有诗意的高峰体验，因此诗人用“怡然心会，妙处难于君说”作为上片的结语、同时巧妙的引出了下阕。上阕写景，下阕则从回顾岭表一年写起，抒发感情。\n\n　　岭表指五岭之外，即今之广西一带。《宋史》本传载张孝祥于宋孝宗乾道元年（1165年）知静江府兼广南西路经略安抚使，次年因谗落职，由桂林北归，途径岳阳，故有《过洞庭》之作。“应”，因也，杜甫诗“名岂文章著，官应老病休。”是说名难道以文章而著，官因老病而休。此处的“应”语气相当肯定。诗人由洞庭湖的澄澈，想起自己在岭表一年因被谗而免职的经历，感慨系之矣。苏轼《西江月》：“中秋谁与共孤光，把盏凄然北望”，张孝祥用了“孤光”这一典故源于此。“孤光自照”，一方面指月亮在天宇中，只能自我孤独地照耀着；另一方面想起自己的岭表一年，不被人所理解，同时诗人也无需别人理解，只能与孤月作伴，引清冷的月光相照。冰雪的特点是洁白晶莹，南朝诗人江总有“净心抱冰雪”之句，所以“肝胆皆冰雪”之句，唐王昌龄有“一片冰心在玉壶”之句，所以“肝胆皆冰雪”，实际上是说，尽管自己被免职，但自己是光明磊落、心地纯洁、肝胆照人的；另一层意思是说，我问心无愧，话语中有愤慨、有失望、有自我安慰，但主要还夹杂着自豪、感情真挚而又复杂。\n\n　　“短发萧骚襟袖冷，稳泛沧溟空阔。”这是从岭表经年回复到当下，“襟袖”则是以部分代全体，月夜清冷，衣服单薄，凉意顿生，更重要的是官场人情冷暖，不免有萧条冷落之感。尽管如此，自己是拿得起放得下的人，任凭风浪起，稳坐钓鱼船，如今我正泛舟于横无际涯的洞庭湖上，不就是证明凡此种种，体现了诗人的鲜明个性。\n\n　　“尽挹西江，细斟北斗，万象为宾客。”这是全词的高潮所在，也是诗人感情的高潮所在。《景德传灯录》卷八记马祖语曰：“侍女一口挹尽西江水”，此处界禅宗话语，表明自己的心胸开阔。北斗星是由七颗星组成的星座，像舀酒的长把勺，《诗经·小雅·大东》：“维北有斗，不可挹酒浆”，而屈原《九歌·东君》则反其意而用之，“援北斗兮酌桂浆”。诗人作主人，请万象（天地万物）作客人，舀尽西去长江的水，用北斗七星作酒器，低斟浅酌的招待天地万物，这是何等气势，一个被谗免官的人，如此自信，如此心胸，真有李白当年“青天有月来几时，我今停杯一向之”，或“相看两不厌，唯有敬亭山”大无畏的浪漫主义精神。\n\n　　“扣舷独啸，不知今夕何夕。”苏轼《前赤壁赋》有“扣舷而歌之”之语，张孝祥则是敲击船沿、仰天长啸，抒发出自己的满腔豪情。受苏轼《念奴娇·中秋》：“我醉拍手狂歌，举杯邀月，对影成三客。起舞徘徊风露下，今夕不知何夕”影像，张孝祥以“不知今夕何夕”作结，从秋月秋水回归自我，扣舷是动作，独啸是声音，从空间上说是由洞庭之大到一己之小；从时间上说是由今夕之初泛到稳泛；从心理上说是由知到不知，通过对照，说明诗人已忘情这月白无风之夜，忘情于与大自然交融之中。\n\n　　此词意象鲜明，意境深邃，结构严谨，想象瑰丽，真正做到了“宠辱不惊，闲看庭前花开花落，去留无意，漫观天外云舒云卷”，是首表现浩然正气的绝妙好词。', poem_tags = '宋词三百首,豪放,写景,写水,月夜,抒怀' WHERE poem_title = '念奴娇·过洞庭' AND poem_author = '张孝祥';
UPDATE edu_poem SET poem_translation = '滞留在远离家乡的地方，依依不舍地向往着春天的景物。\n寒梅最能惹起人们怨恨，因为老是被当作去年开的花。', poem_notes = '定定：唐时俗语，类今之“牢牢”。\n天涯：此指远离家乡的地方，即梓州。\n物华：万物升华，指春天的景物。\n寒梅：早梅，多于严冬开放。\n恨：怅恨，遗憾。\n去年花：指早梅。因为梅花在严冬开放，春天的时候梅花已经凋谢，所以称为“去年花”。', poem_appreciation = '此诗是李商隐所作的一首咏物诗。\n\n　　首先是一句“定定住天涯”，可看得出一开始诗人的思绪并不在梅花上面，而是因为滞留异乡而苦。梓州（今四川三台）离长安一千八百余里，以唐代疆域之辽阔而竟称“天涯”，与其说是地理上的，不如说是心理上的。李商隐是在仕途抑塞、妻子去世的情况下应柳仲郢之辟，来到梓州的。独居异乡，寄迹幕府，已自感到孤孑苦闷，想不到竟一住数年，意绪之无聊郁闷更可想而知。这句就是这个痛苦灵魂的心声。定定即是“死死地”、“牢牢地”，诗人感到自己竟象是永远地被钉死在这异乡的土地上了。这里，有强烈的苦闷，有难以名状的厌烦，也有无可奈何的悲哀。屈复评此句说：“‘定定’字俚语入诗却雅。”这个“雅”，似乎可以理解为富于艺术表现力。\n\n　　为思乡之情、留滞之悲所苦的诗人，精神上不能不寻找慰藉，于是转出第二句：“依依向物华。”诗人在百花争艳的春色面前似乎暂时得到了安慰，从内心深处升起一种对美好事物无限依恋的柔情。一、二两句，感情似乎截然相反，实际上“依依向物华”之情即因“定定住天涯”而生，两种相反的感情却是相通的。\n\n　　“寒梅最堪恨，长作去年花。”三、四两句，诗境又出现更大的转折。面对姹紫嫣红的“物华”，诗人不禁想到了梅花。它先春而开，到百花盛开时，却早花凋香尽，诗人遗憾之余，便不免对它怨恨起来了。由“向物华”而忆梅，这是一层曲折；由忆梅而恨梅，这又是一层曲折。“恨”正是“忆”的发展与深化，正像深切期待的失望会转化为怨恨一样。\n\n　　但这只是一般人的心理。对于李商隐来说，却有更内在的原因。“寒梅”先春而开、望春而凋的特点，使诗人很自然地联想到自己：少年早慧，文名早著，科第早登，但依旧怀才不遇，紧接着的便是一系列不幸和打击，到入川以后，已经是“克意事佛，方愿打钟扫地，为清凉山行者”（《樊南乙集序》），意绪颇为颓唐了。这早秀先凋，不能与百花共享春天温暖的“寒梅”，正是诗人自己的写照。诗人在《十一月中旬扶风界风梅花》诗中，也曾发出同样的感叹：“为谁成早秀？不待作年芳。”非时而早秀，“不待作年芳”的早梅，和“长作去年花”的“寒梅”，都是诗人不幸身世的象征。正因为看到或想到它，就会触动早秀先凋的身世之悲，诗人自然不免要发出“寒梅最堪恨”的怨嗟了。诗写到这里，黯然而收，透出一种不言而神伤的情调。\n\n　　全诗看来，这首五言绝句，贵在天然浑成，一意贯串，并无刻意雕镂，枝蔓曲折。这首《忆梅》，意极曲折，却并不给人以散漫破碎、雕琢伤真之感，关键在于层层转折都离不开诗人沉沦羁泊的身世。这样一来，便显得此诗潜气内转，在曲折中见浑成，在繁多中见统一，达到有神无迹的境界。', poem_tags = '咏物,梅花,抒情' WHERE poem_title = '忆梅' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_tags = '初中文言文,赞颂,女子,传记' WHERE poem_title = '乐羊子妻' AND poem_author = '范晔';
UPDATE edu_poem SET poem_translation = '有人疑惑不解地问我，为何幽居碧山？我只笑而不答，心里却一片轻松坦然。\n桃花飘落溪水，随之远远流去。此处别有天地，真如仙境一般。', poem_notes = '余：我，诗人自指。何意：一作“何事”。栖：居住。碧山：山名，在湖北省安陆市内，山下桃花洞是李白读书处。一说碧山指山色的青翠苍绿。\n自闲：悠闲自得。闲：安然，泰然。\n“桃花”句：晋陶渊明《桃花源记》载，东晋时，武陵有一渔人在溪中捕鱼。忽进桃花林，林尽处有山。山有小口。从山口进去，遇一与外界隔绝的桃花源，里边的人过着安居乐业的生活。此句暗用其事。窅（yǎo）然：指幽深遥远的样子。\n别有天地：另有一种境界。别：另外。非人间：不是人间，这里指诗人的隐居生活。', poem_appreciation = '这是一首诗意淡远的七言绝句，以问答形式并暗用典故抒发了作者隐居生活的自在天然的情趣，也体现了作者的矛盾心理。\n\n　　第一联：“问余何意栖碧山，笑而不答心自闲。”前句起得突兀，后句接得迷离。这首诗的诗题一作《山中答俗人》，那么“问”的主语即所谓“俗人”。诗以提问的形式领起，突出题旨，以唤起读者的注意。当人们正要倾听答案时，诗人笔锋却故意一晃，“笑而不答”。“笑”字值得玩味，它不仅表现出诗人喜悦而矜持的神态，造成了轻松愉快的气氛；而且这“笑而不答”，还带有几分神秘的色彩，造成悬念，以诱发读者思索的兴味。“心自闲”三个字，既是山居心境的写照，更表明这“何意栖碧山”的问题，对于诗人来说，既不觉得新鲜，也不感到困惑，只不过是“悠然心会，妙处难与君说”（张孝祥《念奴娇·过洞庭》）罢了。第二句接得迷离，妙在不答，使诗增添了变幻曲折，有摇曳生姿、引人入胜的魅力。\n\n　　第二联：“桃花流水窅然去，别有天地非人间。”这是写“碧山”之景，其实也就是“何意栖碧山”的答案。这种“不答”而答、似断实连的结构，加深了诗的韵味。诗虽写花随溪水，窅然远逝的景色，却无一点“流水落花春去也”的衰飒情调，而是把它当作令人神往的美来渲染、来赞叹。因为上面写的“笑而不答”的神态，以及末句的议论都流露出这种感情。“山花如绣颊”（李白《夜下征虏亭》）固然是美的，桃花随流水也是美的，它们都是依照自然的法则，在荣盛和消逝之中显示出不同的美，这不同的美却具有一个共同点——即“天然”二字。这种美学观点反映了诗人酷爱自由、天真开朗的性格。“碧山”之中这种没有名利，又不冷落荒凉的环境，充满着天然、宁静之美的“天地”，不是“人间”所能比。而“人间”究竟怎样，诗人没有明说。只要读者了解当时黑暗的现实和李白的不幸遭遇，诗人“栖碧山”、爱“碧山”便不难理解了。这“别有天地非人间”，隐含了诗人心中许许多多的伤和恨。所以，这首诗并不完全是抒写李白超脱现实的闲适心情。诗中用一“闲”字，就是要暗示出“碧山”之“美”，并以此与“人间”形成鲜明的对比。因而诗在风格上有一种“寓庄于谐”的味道，不过这并非“超脱”。愤世嫉俗与乐观浪漫往往能奇妙地统一在他的作品之中，体现出矛盾的对立统一。\n\n　　全诗虽然只有四句二十八字，但是有问、有答，有叙述、有描绘、有议论，其间转接轻灵，活泼流利。诗境似近而实远，诗情似淡而实浓。用笔有虚有实，实处的描写形象可感，虚处的用笔一触即止，虚实对比，蕴意幽邃。诗押平声韵，采用不拘格律的古绝形式，显得质朴自然，悠然舒缓，有助于传达出诗的情韵。', poem_tags = '典故,隐居,生活' WHERE poem_title = '山中问答 / 山中答俗人问' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '其次诎体受辱。诎，通“屈”，弯曲。\n其次剔毛发。剔，通“剃”，动词。\n其次关木索，被箠楚受辱。关，同“贯”，套上。 箠，同“棰”，杖。\n见狱吏则头枪地。枪，通“抢”，撞击。\n及以至是。以，通“已”\n及罪至罔加。罔，通“网”，法网。\n大底圣贤发愤之所为作也。底，通“抵” ，大抵，大都。\n8思垂空文以自见。见，通“现”，表现。\n9网罗天下放失旧闻。失，通“佚”\n放失旧闻。失，通“佚”，散乱的文献。\n则仆偿前辱之责。责，通“债”，债务。\n古者富贵而名摩灭。摩，通“磨”。\n权倾五伯。伯， 通“霸”。\n具于五刑。具，通“俱”。\n曷足贵乎。曷，通“何”。\n幽于圜墙之中。圜，通“圆”。\n稽其成败兴坏之纪。纪，通“记”，历史记录。\n\n词类活用\n孙子膑脚：名词作动词，古代剔去膝盖骨的酷刑\n以污辱先人：形容词作使动用法，使……受辱\n倡优所畜：名词作状语， 像乐师、优伶一样\n仆之先人非有剖符丹书之功：名词作状语， 用朱砂\n故述往事，思来者：动词作使动用法，使.……思考\n请略陈固陋：形容词作名词，固执鄙陋的意见\n衣赭衣：名词作动词，穿上\n流俗之所轻也：形容词作动词，轻视\n幸勿为过：名词作动词，责怪，责备\n太史公牛马走司马迁言：名词作状语，像牛马一样\n曩者辱赐书：使动用法，使……蒙受耻辱\n百兽震恐：使动用法，使……害怕\n\n特殊句式\n被动句\n（1）幽于粪土之中而不辞者。\n（2）其次诎体受辱。\n省略句、判断句\n（1）《诗》三百篇，大底圣贤发愤之所为作也。\n（2）且西伯，伯也。\n（3）倡优所畜，流俗之所轻也。\n（五）状语后置句\n（1）鄙陋没世而文采不表于后世也。\n（2）权倾五伯，囚于请室。\n（3）幽于圜墙之中\n宾语前置句\n（1）若望仆不相师\n重点翻译句\n《诗》三百篇，大氐圣贤发愤之所为作也。\n《诗经》共三百篇，大都是圣人贤士为抒发愤懑之情而写作的。\n2．亦欲以究天人之际，通古今之变，成一家之言。\n也就是想要探究自然和人间的关系，弄通由古至今的变化规律，自成一家之见解。\n3．虽万被戮，岂有悔哉！\n即使被千刀万剐，我难道会后悔吗?\n4．假令仆伏法受诛，若九牛亡一毛，与蝼蚁何异?\n假如我受到法律的制裁被杀，就像在九头牛身上去掉一根牛毛，与杀死一只蝼蚁有什么区别呢?\n5．故士有画地为牢，士不可入；削木为吏，议不可对，定计于鲜也。\n所以，在地上划圈为牢，气节之士势必不肯进去；用木头削成狱吏，气节之士也认为不可受它审讯，拿定主意在受辱之前自杀。\n6．仆虽怯懦，欲苟活，亦颇识去就之分矣，何至自沉溺缧绁之辱哉！\n我虽然怯弱，想苟活偷生，但也知道舍生就死，怎么会自甘沉溺于牢狱的侮辱之中呢?\n7．今虽欲自雕琢，曼辞以自饰，无益于俗，不信，祗取辱耳。\n时至今日，我即使想要修饰打扮，用美好的言辞为自己解脱也无济于事，一般人不会相信，只不过自取侮辱罢了。\n\n一词多义\n1.胜\n（1）胜任。能够承担或承受。\n（2）不可胜记。尽。\n（3）百战百胜。胜利。\n（4）引人入胜。优美的。\n2.再\n（1）太史公牛马走司马迁再拜言。两次。\n（2）青春不再。再继续，再出现。\n3.厥\n（1）思厥先祖父。他的。\n（2）大放厥词。别的。\n（3）厥有《国语》。于是，就，才。\n4.焉\n（1）不入虎穴，焉得虎子。疑问代词，怎么。\n（2）唯倜傥非常之人称焉。语气词。\n（3）积土成山，风雨兴焉。兼词，在那里。\n5.非\n（1）死日然后是非乃定。错误，不对。\n（2）无可厚非。反对，责备。\n6.就\n（1）亦颇识去就之分矣。 赴死。\n（2）草创未就。 完成。\n（3）是以就极刑而无愠色。靠近，引申为承受。\n7.望\n（1)若望仆不相师。 怨恨。\n（2）日夜望将军至。期望。\n（3）七月既望。农历每月十五日。\n（4）吾尝跂而望矣。向远处看。\n（5）以绝秦望。 念头.\n（6）名门望族。有声望的。\n\n古今异义\n太史公牛马走司马迁再拜言。\n再：古义：两次 今义：第二次\n古义：谦词，像牛马一样供人驱使的人。\n今义：牛马走路。\n意气勤勤恳恳。\n古义：情意诚挚恳切。\n今义：勤劳而踏实。\n夫人情莫不贪生恶死。\n古义：两个词，夫为语气词。\n今义：对已婚女人的称呼。\n念父母，顾妻子。\n古义：妻子和儿女。\n今义：配偶。\n唯倜傥非常之人称焉。\n古义：形容词，不同寻常。\n今义：表程度的副词，相当于“很”、“非常”。\n下流多谤议。\n古义：处于卑贱的地位。\n今义：1.下游\n2.行为不符合道德准则\n意气勤勤恳恳。\n古义：心意，情意。\n今义：意志和气概：志趣和性格。\n至激于义理者不然。\n古义：正义和真理\n今义：言论或文章的内容和道理\n恨私心有所不尽\n恨：古义：遗憾\n今义：怨，仇视\n私心：古义：自己的志愿\n今义：为自己打算的念头\n大底圣贤发愤之所为作也\n古义：抒发愤懑\n今义：决心努力\n仆以口语遇遭此祸\n古义：言论\n今义：与“书面语”相对\n素所自树立使然也\n古义：立身于世\n今义：1.建立 2.直立，竖立\n何至自沉溺缧绁之辱哉\n古义：陷身\n今义：陷入不良境地\n\n虚词\n以\n（1）及以至是(通“已”）\n（2）仆以口语遇遭此祸（介词，因为）\n（3）退论书策以舒其愤（连词，来）\n（4）重为乡党所戮笑，以污辱先人（连词，以致）\n（5）今少卿乃教以推贤进士（介词，用）\n（6）夫人不能早自裁绳墨之外，以稍陵迟（连词，因而）\n为\n（1）为十表，本纪十二（动词，写成）\n（2）季布为朱家钳奴（动词，做了）\n（3）削木为吏，议不可对（动词，当作）\n（4）然此可为智者道（介词，给，替）\n（5）古人所以重施刑于大夫者，殆为此也（介词，因为）\n（6）重为乡党所笑（介词，被）\n且\n（1）且勇者不必死节（连词，况且）\n（2）且从俗浮沉，与时俯仰（副词，暂且，姑且）\n（3）且西伯，伯也（连词，再说）\n于\n（1）人固有一死，或重于泰山（介词，比)\n（2）幽于圜墙之中（介词，在）\n（3）至激于义理者不然（介词，被）\n（4）少卿视仆于妻子何如哉（介词，对）\n（5）无益于俗（介词，对）\n乃\n（1）今少卿乃教以推贤进士（副词，却，竟然）\n（2）乃欲引节，斯不亦远乎（副词，才）\n（3）然后是非乃定（副词，才）\n（4）至激于义理者不然，乃有所不得已也（动词，是）\n然\n（1）至激于义理者不然（代词，这样）\n（2）然此可为智者道（连词，表示转折）\n（3）阙然久不报（形容词词尾，……的样子）▲', poem_appreciation = '《报任安书》是一篇激切感人的至情散文，是对封建专制的血泪控诉。司马迁用千回百转之笔，表达了自己的光明磊落之志、愤激不平之气和曲肠九回之情。辞气沉雄，情怀慷慨。\n\n　　全文融议论、抒情、叙事于一体，文情并茂。叙事简括，都为议论铺垫，议论之中感情自现。“若九牛亡一毛，与蝼蚁何以异！”，抒发了对社会不公的愤慨；“仆虽怯懦欲苟活，亦颇识去就之分矣，何至自沉溺缧绁之辱哉！”，悲切郁闷，溢于言表；“肠一日而九回，居则忽忽若有所亡，出则不知其所往。每念斯耻，汗未尝不发背沾衣也！”，如泣如诉，悲痛欲绝……富于抒情性的语言，将作者内心久积的痛苦与怨愤表现得淋漓尽致，如火山爆发，如江涛滚滚。\n\n　　大量的铺排，增强了感情抒发的磅礴气势。如叙述腐刑的极辱，从“太上不辱先”以下，十个排比句，竟连用了八个“其次”，层层深入，一气贯下，最后逼出“最下腐刑极矣”。这类语句，有如一道道闸门，将司马迁心中深沉的悲愤越蓄越高，越蓄越急，最后喷涌而出，一泻千里，如排山倒海，撼天动地。\n\n　　典故的运用，使感情更加慷慨激昂，深沉壮烈。第二段用西伯、李斯、韩信等王侯将相受辱而不自杀的典故，直接引出“古今一体”的结论，愤激地控诉了包括汉王朝在内的封建专制下的酷吏政治；第五段用周文王、孔子、屈原等古圣先贤愤而著书的典故，表现了自己隐忍的苦衷、坚强的意志和奋斗的决心。这些典故，援古证今，明理达情，让我们更深刻的感受到了作者伟岸的人格和沉郁的感情。\n\n　　修辞手法的多样，丰富了感情表达的内涵。如“盖文王拘而演《周易》”以下八个迭句，实际隐含着八组对比，同时又两两对偶，与排比相结合，既表明了对历史上杰出人物历经磨难而奋发有为的现象的认识，又表明了以他们为榜样，矢志进取、成就伟业的坚强意志，气势雄浑，令人欲悲欲叹。又如“猛虎在山，百兽震恐……”一句，运用比喻，沉痛控诉了人间暴政对人性的扼杀和扭曲，形象地说明了“士节”不可以稍加受辱的道理，真是痛彻心脾。其他像引用、夸张、讳饰等修辞手法的运用，都真切的表达出作者跌宕起伏的情感，有时奔放激荡，不可遏止；有时隐晦曲折，欲言又止，让我们似乎触摸到了作者内心极其复杂的矛盾与痛苦。\n\n　　总之，在《报任安书》中，司马迁通过富有特色的语言，真切地表达了激扬喷薄的愤激感情，表现出峻洁的人品和伟大的精神，可谓字字血泪，声声衷肠，气贯长虹，催人泪下。前人的评价，“感慨啸歌有燕赵烈士之风，忧愁幽思则又直与《离骚》对垒”，实在精辟。', poem_tags = '古文观止,叙事,议论,抒怀' WHERE poem_title = '报任少卿书 / 报任安书' AND poem_author = '司马迁';
UPDATE edu_poem SET poem_translation = '漆黑之夜不见月亮，只见那渔船上的灯光，孤独的灯光在茫茫的夜色中，象萤火虫一样发出一点微亮。\n微风阵阵，河水泛起层层波浪，渔灯微光在水面上散开，河面好象撤落无数的星星。', poem_notes = '孤光：孤零零的灯光。\n簇：拥起。', poem_appreciation = '这首诗好似一幅速写，作者抓住了那倒映在水中的渔火化作满天星星的片刻，几笔勾勒，立即捕捉住了这转瞬即逝的景物。这首诗又好似一幅木刻，在漆黑的背景之上，亮出一点渔火，黑白对比，反差特别鲜明。\n\n　　前两句是静态描写，把暗色和亮色联系在一起，显得形象鲜明。\n\n　　第一句“月黑见渔灯”，“月黑”两字很有特色。这是一个有月亮的夜晚，月亮却没有光，人们见到的只是月亮的轮廓和黑影。“见渔灯”的这个“见”，是不见中的“见”，写的是视像，有突然发现的意思。因为月黑无光，河面也黑沉沉的，突然见到河中的一盏渔灯，格外引人注目。\n\n　　第二句“孤光一点萤”，写如豆灯光像江岸边一点萤火，是意中之象，描写渔灯的形象。河面幽黑，只有孤零零的一点灯光闪烁着，仿佛是一只萤火虫在原野里发出微弱的光。“孤”表现了环境的寂寞、单调，寄寓着一定的感情色彩。一种茫然无奈的情感袭上诗人的心头。\n\n　　后两句为动态描写。不难想象，当诗人见到微风腾起细浪，灯影由一点散作千万这动人一幕的时候，心情是何等地兴奋。\n\n　　第三句“微微风簇浪”抛开了灯光，一转而写夜风。微风从河面阵阵吹来，河水哗哗作响，轻轻的掀起浪花。这句写听觉为下句张目。“微微”二字又体现了风是如此的小，“簇”说明了就算是微风也能掀起一簇簇的浪花。渲染了一种宁静舒适的气氛。\n\n　　第四句“散作满河星”犹如天外奇峰，劈空而来。那如萤的孤光，刹那间似乎变成万船灯火，点缀河中，又如风吹云散，满天明星，倒映水中，使这静谧的黑夜，单调的河面出现了意想不到的壮观。风吹浪起，簇起的每朵浪花，都把那如萤般的灯光摄进水中，有多少浪花，就有多少灯光。同时此句的描写为诗词增添了画面感，使枯燥无趣的文字能幻化出美丽浪漫带有一丝丝的安逸宁静的景象，使诗人流连其中。', poem_tags = '古诗三百首,写景' WHERE poem_title = '舟夜书所见' AND poem_author = '查慎行';
UPDATE edu_poem SET poem_translation = '重重帷幕深垂，我孤居莫愁堂；\n独卧不眠，更觉静夜漫漫长长。\n巫山神女艳遇楚王，原是梦幻；\n青溪小姑住所，本就独处无郎。\n我是柔弱菱枝，偏遭风波摧残；\n我是铃芳桂叶，却无月露香。\n虽然深知沉溺相思，无益健康；\n我却痴情到底，落个终身清狂。\n\n注解\n神女：即宋玉《神女赋》中的巫山神女。\n小姑句：古乐府《青溪小姑曲》：“小姑所居，独处无郎。”\n风波句：意谓菱枝虽是弱质，却不相信会任凭风波欺负。\n直道两句：意谓即使相思全无好处，但这种惆怅之心，也好算是痴情了。直道：即使，就说。了：完全。清狂：旧注谓不狂之狂，犹今所谓痴情。按：如作狂放解本也通，但既把诗中人作为女子解，那么，还是作痴情解较切。▲', poem_appreciation = '李商隐的七律无题，艺术上最成熟，最能代表其无题诗的独特艺术风貌。这首七律无题，内容是抒写青年女子爱情失意的幽怨，相思无望的苦闷，又采取女主人公深夜追思往事的方式，因此，女主人公的心理独白就构成了诗的主体。她的身世遭遇和爱情生活中某些具体情事就是通过追思回忆或隐或显地表现出来的。\n\n　　这首诗侧重于抒写女主人公的身世遭遇之感，写法非常概括。一开头就撇开具体情事，从女主人公所处的环境氛围写起。层帷深垂，幽邃的居室笼罩着一片深夜的静寂。独处幽室的女主人公自思身世，辗转不眠，倍感静夜的漫长。这里尽管没有一笔正面抒写女主人公的心理状态，但透过这静寂孤清的环境气氛，读者几乎可以触摸到女主人公的内心世界，感觉到那帷幕深垂的居室中弥漫着一层无名的幽怨。\n\n　　颔联进而写女主人公对自己爱情遇合的回顾。上句用巫山神女梦遇楚王事，下句用乐府《神弦歌·清溪小姑曲》：“小姑所居，独处无郎。”意思是说，追思往事，在爱情上尽管也象巫山神女那样，有过自己的幻想与追求，但到头来不过是做了一场幻梦而已；直到现在，还正像清溪小姑那样，独处无郎，终身无托。这一联虽然用了两个典故，却几乎让人感觉不到有用典的痕迹，真正达到了驱使故典如同己出的程度。特别是它虽然写得非常概括，却并不抽象，因为这两个典故各自所包含的神话传说本身就能引起读者的丰富想象与联想。两句中的“原”字、“本”字，颇见用意。前者暗示她在爱情上不仅有过追求，而且也曾有过短暂的遇合，但终究成了一场幻梦，所以说“原是梦”；后者则似乎暗示：尽管迄今仍然独居无郎，无所依托，但人们则对她颇有议论，所以说“本无郎”，其中似含有某种自我辩解的意味。不过，上面所说的这两层意思，都写得隐约不露，不细心揣摩体味是不容易发现的。\n\n　　颈联从不幸的爱情经历转到不幸的身世遭遇。这一联用了两个比喻：说自己就象柔弱的菱枝，却偏遭风波的摧折；又象具有芬芳美质的桂叶，却无月露滋润使之飘香。这一联含意比较隐晦，似乎是暗示女主人公在生活中一方面受到恶势力的摧残，另一方面又得不到应有的同情与帮助。“不信”，是明知菱枝为弱质而偏加摧折，见“风波”之横暴；“谁教”，是本可滋润桂叶而竟不如此，见“月露”之无情。措辞婉转，而意极沉痛。\n\n　　爱情遇合既同梦幻，身世遭逢又如此不幸，但女主人公并没有放弃爱情上的追求──“直道相思了无益，未妨惆怅是清狂。”即便相思全然无益，也不妨抱痴情而惆怅终身。在近乎幻灭的情况下仍然坚持不渝的追求，“相思”的铭心刻骨更是可想而知了。\n\n　　中唐以来，以爱情、艳情为题材的诗歌逐渐增多。这类作品在共同特点是叙事的成份比较多，情节性比较强，人物、场景的描绘相当细致。李商隐的爱情诗却以抒情为主体，着力抒写主人公的主观感觉、心理活动，表现她（他）们丰富复杂的内心世界。而为了加强抒情的形象性、生动性，又往往要在诗中织入某些情节的片断，在抒情中融入一定的叙事成分。这就使诗的内容密度大大增加，形成短小的体制与丰富的内容之间的矛盾。为了克服这一矛盾，他不得不大大加强诗句之间的跳跃性，并且借助比喻、象征、联想等多种手法来加强诗的暗示性。这是他的爱情诗意脉不很明显、比较难读的一个重要原因。但也正因为这样，他的爱情诗往往具有蕴藉含蓄、意境深远、写情细腻的特点和优点，经得起反复咀嚼与玩索。\n\n　　无题诗究竟有没有寄托，是一个复杂的问题。离开诗歌艺术形象的整体，抓住其中的片言只语，附会现实生活的某些具体人事，进行索隐猜谜式的解释，是完全违反艺术创作规律的。像冯浩那样，将《无题·凤尾香罗薄几重》中的“垂杨岸”解为“寓柳姓”（指诗人的幕主柳仲郢），将“西南”解为“蜀地”，从而把这首诗和《无题·凤尾香罗薄几重》说成是诗人“将赴东川，往别令狐，留宿，而有悲歌之作”，就是穿凿附会的典型。但这并不妨碍读者从诗歌形象的整体出发，联系诗人的身世遭遇和其他作品，区别不同情况，对其中的某些无题诗作这方面的探讨。这首着重写女主人公如梦似幻，无所依托，横遭摧折的凄苦身世，笔意空灵概括，意在言外，其中就可能寓含或渗透作者自己的身世之感。熟悉作者身世的读者不难从“神女”一联中体味出诗人在回顾往事时深慨辗转相依、终归空无的无限怅惘。“风波”一联，如单纯写女子遭际，显得不着边际；而从比兴寄托角度理解，反而易于意会。作者地位寒微，“内无强近，外乏因依”（《祭徐氏姊文》），仕途上不仅未遇有力援助，反遭朋党势力摧抑，故借菱枝遭风波摧折，桂叶无月露滋润致慨。他在一首托宫怨以寄慨的《深宫》诗中说：“狂飚不惜萝阴薄，清露偏知桂叶浓”，取譬与“风波”二句相似（不过“清露”句与“月露”句托意正相反而已），也可证“风波”二句确有寄托。何焯说这首无题“直露（自伤不遇）本意”，是比较符合实际的。不论这首无题诗有无寄托，它首先是成功的爱情诗。即使读者完全把它作为爱情诗来读，也并不减低其艺术价值。', poem_tags = '唐诗三百首,思念,爱情,抒情' WHERE poem_title = '无题·重帏深下莫愁堂' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '我们离别的太久了，已经是七次中秋。去年的今天在东武之地，我望着明月，愁绪万千。没想到在彭城山下，一起泛舟古汴河上，同去凉州。有鼓吹助兴，惊起汀上的鸿雁。\n坐中的客人，穿着华丽。月亮无情，不肯为人留下而西沉。今天晚上有酒待客，明晚又要孤独的的住在船上，离愁依旧。就怕像王粲那样，不得返乡，只能登楼相望。', poem_notes = '水调歌头：词牌名。唐朝大曲有《水调歌》，据《隋唐嘉话》，为隋炀帝凿汴河时所作。宋乐入“中吕调”，见《碧鸡漫志》卷四。凡大曲有“歌头”，此殆裁截其首段为之。九十五字，前后片各四平韵。亦有前后片两六言句夹叶仄韵者，有平仄互叶几于句句用韵者。\n离别：比较长久地跟人或地方分开。\n七度：七次。\n今夕：今天。\n不胜：无法承担；承受不了。\n彭城：彭城，鼓声之城，即今江苏徐州，是黄帝最初的都城。\n古汴（biàn）：古汴河。\n凉州：曲名，唐开元中西凉州所献。\n鼓吹：鼓吹乐。\n鸿雁：俗称大雁。\n汀（tīng）州：水中小洲。\n翠羽帔（pèi），紫绮（qǐ）裘（qiú）：指豪华衣饰。\n素娥：即嫦娥，此处指月亮。\n无赖：无所倚靠；无可奈何。\n曾不：不曾。\n清尊：酒器。\n水驿：水路驿站。\n依旧：照旧。\n但恐：但害怕。\n王粲（càn）：王粲（177年—217年2月17日），字仲宣。山阳郡高平县（今山东微山两城镇）人。\n相对：相望。', poem_appreciation = '下片则直接展现诗人内心世界。前三句，只是从宴饮中主人、客人的穿戴里，聊表人们的欢愉心情，可下面却写出了急转之下诗人的内心感受。“素娥无赖西去，曾不为人留”，明月无情，不会为人而滞留。“今夜清尊对客，明夜孤帆水驿，依旧照离忧”，直写情事，明日即将分别；即便明月当头，也是分明地倾泻出两地别愁，“依旧”二字非常好。最后两句，用典却直抒胸臆，“但恐同王粲，相对永登楼”，王粲滞留荆州十二年，不得施展才华，郁闷中他登楼远眺，北望家乡，胸中翻滚着无限乡思乡愁，写出了《登楼赋》。后以“王粲登楼”作为怀念故国乡土的典故。这里，词人以此句做结，倾诉出未来的日月：宦游茫茫，前途未卜；亲人相隔，幽幽愁绪的别样的深沉。本来是百日逍遥堂欢乐的手足相聚，到头来却是迎来生离别的无奈，也许这就是人生的必然。', poem_tags = '中秋节,咏物,月亮,抒怀' WHERE poem_title = '水调歌头·徐州中秋' AND poem_author = '苏辙';
UPDATE edu_poem SET poem_translation = '在绿杨垂柳、芳草萋萋的长亭古道上，他好像情侣轻易地抛下我就登程远去。楼头的钟声惊醒了五更的残梦，心头的离愁就像洒在花底的三月春雨。\n无情人哪里懂得多情的人的苦恼，一寸相思愁绪竟化作了万缕千丝。天涯地角再远也有穷尽终了那一天，只有怀人的愁思却是无限绵长、没有尽期啊。', poem_notes = '玉楼春：词牌名。又名“木兰花”。\n长亭路：送别的路。长亭：古代驿路上建有供行人休息的亭子。《白帖》：“十里一长亭，五里一短亭。”\n年少抛人：人被年少所抛弃，言人由年少变为年老。\n残梦：未做完的梦。\n五更钟、三月雨：都是指思念人的时候。\n一寸：指愁肠。还：已经。千万缕：千丝万缕。比喻离恨无穷。', poem_appreciation = '此词抒写人生离别相思之苦，寄托了作者从有感于人生短促、聚散无常以及盛筵之后的落寞等心情生发出来的感慨。整首词感情真挚，情调凄切，抒情析理，绰约多姿，有着迷人的艺术魅力。作者抒发人生感慨时成功地使用了夸张手法，更增添了词的艺术感染力。\n\n　　上片首句写景，时间是绿柳依依的春天，地点古道长亭，这是旅客小休之所，也是两人分别之处。\n\n　　“年少”句叙述临行之际，闺女空自泪眼相看，无语凝咽，而“年少”的他却轻易地弃之而去。年少，是指思妇的“所欢”，也即“恋人”，据赵与时《宾退录》记载，“晏叔原见蒲传正曰：‘先君平日小词虽多，未尝作妇人语也。’传正曰：‘绿杨芳草长亭路，年少抛人容易去，岂非妇人语乎？’叔原曰：‘公谓年少为所欢乎，因公言，遂解得乐天诗两句：欲留所欢待富贵，富贵不来所欢去。’传正笔而悟。余按全篇云云，盖真谓所欢者，与乐天‘欲留年少待富贵，富贵不来年少去’之句不同，叔原之言失之。”这是晏几道为其父此词“年少”语所作的无谓辩解。实际上，此词写思妇闺怨，用的的确是“妇人语”。\n\n　　“楼头”两句，把思妇的思念之意生动地描绘出来，从相反方面说明“抛人去”者的薄情。白昼逝去，黑夜降临，她转辗反侧，很久之后才悠悠进入睡乡，但很快就被五更钟声惊破了残梦，使她重又陷入无边的失望；窗外，飘洒着春雨，那些花瓣像是承受不住，带着离愁纷纷落下。“残梦”和“落花”这里都是用来曲折地抒发怀人之情，语言工致匀称。陈廷焯《白雨斋词话》称其“婉转缠绵，深情一往，丽而有则，耐人寻味”。\n\n　　下片用反语，先以无情与多情作对比，继而以具体比喻从反面来说明。“无情”两句，用反语以加强语意。先说无情则无烦恼，因此多情还不如无情，从而反托出“多情自古伤离别”的深衷：“一寸”指心，柳丝缕缕，拂水飘绵，最识离怀别苦。两句意思是说，无情怎似多情之苦，那一寸芳心，化成了千丝万缕，蕴含着千愁万恨。词意来自李煜“一片芳心千万绪，人间没个安排处”（《蝶恋花》）。\n\n　　末两句含意深婉。天涯地角，是天地之尽头，故云“有穷时”。然而，别离之后的相思之情，却是无穷无尽的，正所谓“只有相思无尽处”。这里通过比较来体现出因“多情”而受到的精神折磨，感情真切而含蓄，对于那个薄幸年少，却毫无埋怨之语。此词写闺怨，颇具婉转流利之致，词中不事藻饰，没有典故，除首两句为叙述，其余几句不论是用比喻，还是用反语，用夸张，都是通过白描手段反映思妇的心理活动，亦即难以言宣的相思之情，收到了很好的艺术效果。', poem_tags = '春天,思念,爱情,感叹,人生' WHERE poem_title = '玉楼春·春恨' AND poem_author = '晏殊';
UPDATE edu_poem SET poem_translation = '贺知章酒后骑马，晃晃悠悠，如在乘船。他眼睛昏花坠入井中，竟在井底睡着了。\n汝阳王李琎饮酒三斗以后才去觐见天子。路上碰到装载酒曲的车，酒味引得口水直流，为自己没能封在水味如酒的酒泉郡而遗憾。\n左相李适为每日之兴起不惜花费万钱，饮酒如长鲸吞吸百川之水。自称举杯豪饮是为了脱略政事，以便让贤。\n崔宗之是一个潇洒的美少年，举杯饮酒时，常常傲视青天，俊美之姿有如玉树临风。\n苏晋虽在佛前斋戒吃素，饮起酒来常把佛门戒律忘得干干净净。\n李白饮酒一斗，立可赋诗百篇，他去长安街酒肆饮酒，常常醉眠于酒家。天子在湖池游宴，召他为诗作序，他因酒醉不肯上船，自称是酒中之仙。\n张旭饮酒三杯，即挥毫作书，时人称为草圣。他常不拘小节，在王公贵戚面前脱帽露顶，挥笔疾书，若得神助，其书如云烟之泻于纸张。\n焦遂五杯酒下肚，才得精神振奋。在酒席上高谈阔论，常常语惊四座。', poem_notes = '知章：即贺知章，越州永兴（今浙江萧山）人，官至秘书监。性旷放纵诞，自号“四明狂客”，又称“秘书外监”。他在长安一见李白，便称他为“谪仙人”，解所佩金龟换酒痛饮。这两句写贺知章醉后骑马，摇摇晃晃，像乘船一样。醉眼昏花，跌落井中淹死。\n汝阳：汝阳王李琎，唐玄宗的侄子。朝天：朝见天子。此谓李痛饮后才入朝。麴车．酒车。移封：改换封地。酒泉：郡名，在今甘肃酒泉县。传说郡城下有泉，味如酒。故名酒泉。\n左相：指左丞相李适之，天宝元年（742年）八月为左丞相，天宝五年（746年）四月，为李林甫排挤罢相。长鲸：鲸鱼。古人以为鲸鱼能吸百川之水，故用来形容李适之的酒量之大。衔杯：贪酒。圣：酒的代称。\n宗之：崔宗之，吏部尚书崔日用之子，袭父封为齐国公，官至侍御史，也是李白的朋友。觞：大酒杯。白眼：晋阮籍能作青白眼，青眼看朋友，白眼视俗人。玉树临风：崔宗之风姿秀美，故以玉树为喻。\n苏晋：开元进士，曾为户部和吏部侍郎，长斋：长期斋戒。绣佛：画的佛像。逃禅：这里指不守佛门戒律。佛教戒饮酒。苏晋长斋信佛，却嗜酒，故曰“逃禅”。\n李白：以豪饮闻名，而且文思敏捷，常以酒助诗兴。\n张旭：吴人，唐代著名书法家，善草书，时人称为“草圣”。脱帽露顶：写张旭狂放不羁的醉态。据说张旭每当大醉，常呼叫奔走，索笔挥洒，甚至以头濡墨而书。醒后自视手迹，以为神异，不可复得。世称“张颠”。\n焦遂：布衣之士，平民，以嗜酒闻名，事迹不详。卓然：神采焕发的样子。', poem_appreciation = '《饮中八仙歌》是一首别具一格，富有特色的“肖像诗”。八个酒仙是同时代的人，又都在长安生活过，在嗜酒、豪放、旷达这些方面彼此相似。诗人以洗炼的语言，人物速写的笔法，将他们写进一首诗里，构成一幅栩栩如生的群像图。\n\n　　八仙中首先出现的是贺知章。他是其中资格最老、年事最高的一个。在长安，他曾“解金龟换酒为乐”（李白《对酒忆贺监序》）。诗中说他喝醉酒后，骑马的姿态就象乘船那样摇来晃去，醉眼朦胧，眼花缭乱，跌进井里竟会在井里熟睡不醒。相传“阮咸尝醉，骑马倾欹”，人曰：“箇老子如乘船游波浪中”（明王嗣？;《杜臆》卷一）。杜甫活用这一典故，用夸张手法描摹贺知章酒后骑马的醉态与醉意，弥漫着一种谐谑滑稽与欢快的情调，惟妙惟肖地表现了他旷达纵逸的性格特征。\n\n　　其次出现的人物是汝阳王李琎。他是唐玄宗的侄子，宠极一时，所谓“主恩视遇频”，“倍比骨肉亲”（杜甫《赠太子太师汝阳郡王琎》），因此，他敢于饮酒三斗才上朝拜见天子。他的嗜酒心理也与众不同，路上看到麴车（即酒车）竟然流起口水来，恨不得要把自己的封地迁到酒泉（今属甘肃）去。相传那里“城下有金泉，泉味如酒，故名酒泉”（见《三秦记》）。唐代，皇亲国戚，贵族勋臣有资格袭领封地，因此，八人中只有李琎才会勾起“移封”的念头，其他人是不会这样想入非非的。诗人就抓着李琎出身皇族这一特点，细腻地描摹他的享乐心理与醉态，下笔真实而有分寸。\n\n　　接着出现的是李适之。他于742年（天宝元年），代牛仙客为左丞相，雅好宾客，夜则燕赏，饮酒日费万钱，豪饮的酒量有如鲸鱼吞吐百川之水，一语点出他的豪华奢侈。然而好景不长，开宝五载适之为李林甫排挤，罢相后，在家与亲友会饮，虽酒兴未减，却不免牢骚满腹，赋诗道：“避贤初罢相，乐圣且衔杯，为问门前客，今朝几个来？”（《旧唐书。李适之传》）“衔杯乐圣称避贤”即化用李适之诗句。“乐圣”即喜喝清酒，“避贤”，即不喝浊酒。结合他罢相的事实看，“避贤”语意双关，有讽刺李林甫的意味。这里抓住权位的得失这一个重要方面刻画人物性格，精心描绘李适之的肖像，含有深刻的政治内容，很耐人寻味。\n\n　　三个显贵人物展现后，跟着出现的是两个潇洒的名士崔宗之和苏晋。崔宗之，是一个倜傥洒脱，少年英俊的风流人物。他豪饮时，高举酒杯，用白眼仰望青天，睥睨一切，旁若无人。喝醉后，宛如玉树迎风摇曳，不能自持。杜甫用“玉树临风”形容宗之的俊美丰姿和潇洒醉态，很有韵味。接着写苏晋。司马迁写《史记》擅长以矛盾冲突的情节来表现人物的思想性格。杜甫也善于抓住矛盾的行为描写人物的性格特征。苏晋一面耽禅，长期斋戒，一面又嗜饮，经常醉酒，处于“斋”与“醉”的矛盾斗争中，但结果往往是“酒”战胜“佛”，所以他就只好“醉中爱逃禅”了。短短两句诗，幽默地表现了苏晋嗜酒而得意忘形，放纵而无所顾忌的性格特点。\n\n　　以上五个次要人物展现后，中心人物隆重出场了。\n\n　　诗酒同李白结了不解之缘，李白自己也说过“百年三万六千日，一日须倾三百杯”（《襄阳歌》），“兴酣落笔摇五岳”（《江上吟》）。杜甫描写李白的几句诗，浮雕般地突出了李白的嗜好和诗才。李白嗜酒，醉中往往在“长安市上酒家眠”，习以为常，不足为奇。“天子呼来不上船”这一句，顿时使李白的形象变得高大奇伟了。李白醉后，更加豪气纵横，狂放不羁，即使天子召见，也不是那么毕恭毕敬，诚惶诚恐，而是自豪地大声呼喊：“臣是酒中仙！”强烈地表现出李白不畏权贵的性格。“天子呼来不上船”，虽未必是事实，却非常符合李白的思想性格，因而具有高度的艺术真实性和强烈的艺术感染力。杜甫是李白的挚友，他把握李白思想性格的本质方面并加以浪漫主义的夸张，将李白塑造成这样一个桀骜不驯，豪放纵逸，傲视封建王侯的艺术形象。这肖像，神采奕奕，形神兼备，焕发着美的理想光辉，令人难忘。这正是千百年来人民所喜爱的富有浪漫色彩的李白形象。\n\n　　另一个和李白比肩出现的重要人物是张旭。他“善草书，好酒，每醉后，号呼狂走，索笔挥洒，变化无穷，若有神助”（《杜臆》卷一）。当时人称“草圣”。张旭三杯酒醉后，豪情奔放，绝妙的草书就会从他笔下流出。他无视权贵的威严，在显赫的王公大人面前，脱下帽子，露出头顶，奋笔疾书，自由挥洒，笔走龙蛇，字迹如云烟般舒卷自如。“脱帽露顶王公前”，这是何等的倨傲不恭，不拘礼仪！它酣畅地表现了张旭狂放不羁，傲世独立的性格特征。\n\n　　歌中殿后的人物是焦遂。袁郊在《甘泽谣》中称焦遂为布衣，可见他是个平民。焦遂喝酒五斗后方有醉意，那时他更显得神情卓异，高谈阔论，滔滔不绝，惊动了席间在座的人。诗里刻画焦遂的性格特征，集中在渲染他的卓越见识和论辩口才，用笔精确、谨严。\n\n　　《八仙歌》的情调幽默谐谑，色彩明丽，旋律轻快。在音韵上，一韵到底，一气呵成，是一首严密完整的歌行。在结构上，每个人物自成一章，八个人物主次分明，每个人物的性格特点，彼此衬托映照，有如一座群体圆雕，艺术上确有独创性。正如王嗣奭所说：“此创格，前无所因。”它在古典诗歌中的确是别开生面之作。', poem_tags = '肖像,写人,喝酒,猖狂' WHERE poem_title = '饮中八仙歌' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '百尺长的柳条轻拂过闪耀着银光的水塘，柳色尚且还不是深青的，只是浅浅的黄。 \n未必柳条能蘸到水，那是因为水中的柳影将它拉长了。', poem_notes = '银塘：指清澈明净的池塘。\n且：尚，还。', poem_tags = '柳树' WHERE poem_title = '新柳' AND poem_author = '杨万里';
UPDATE edu_poem SET poem_translation = '纱窗外的阳光淡去，黄昏渐渐降临；\n锁闭华屋，无人看见我悲哀的泪痕。\n庭院空旷寂寞，春天景色行将逝尽；\n梨花飘落满地，无情无绪把门关紧。', poem_notes = '金屋：原指汉武帝少时欲金屋藏阿娇事。这里指妃嫔所住的华丽宫室。', poem_appreciation = '这是一首宫怨诗。点破主题的是诗的第二句“金屋无人见泪痕”。句中的“金屋”，用汉武帝幼小时愿以金屋藏阿娇（陈皇后小名）的典故，表明所写之地是与人世隔绝的深宫，所写之人是幽闭在宫内的少女。下面“无人见泪痕”五字，可能有两重含意：一是其人因孤处一室、无人作伴而不禁下泪；二是其人身在极端孤寂的环境之中，纵然落泪也无人得见，无人同情。这正是宫人命运之最可悲处。句中的“泪痕”两字，也大可玩味。泪而留痕，可见其垂泪已有多时。这里，总共只用了七个字，就把诗中人的身份、处境和怨情都写出了。这一句是全诗的中心句，其他三句则都是环绕这一句、烘托这一句的。\n\n　　起句“纱窗日落渐黄昏”，是使无人的“金屋”显得更加凄凉。屋内环顾无人，固然已经很凄凉，但在阳光照射下，也许还可以减少几分凄凉。现在，屋内的光线随着纱窗日落、黄昏降临而越来越昏暗，如李清照《声声慢》词中所说，“守着窗儿，独自怎生得黑”，其凄凉况味就更可想而知了。\n\n　　第三句“寂寞空庭春欲晚”，是为无人的“金屋”增添孤寂的感觉。屋内无人，固然使人感到孤寂，假如屋外人声喧闹，春色浓艳，呈现一片生机盎然的景象，或者也可以减少几分孤寂。现在，院中竟也寂无一人，而又是花事已了的晚春时节，正如欧阳修《蝶恋花》词所说的“门掩黄昏，无计留春住”，也如李雯《虞美人》词所说的“生怕落花时候近黄昏”，这就使“金屋”中人更感到孤寂难堪了。\n\n　　末句“梨花满地不开门”，它既直承上句，是“春欲晚”的补充和引伸；也遥应第二句，对诗中之人起陪衬作用。王夫之在《夕堂永日绪论》中指出“诗文俱有主宾”，要“立一主以待宾”。这首诗中所立之主是第二句所写之人，所待之宾就是这句所写之花。这里，以宾陪主，使人泣与花落两相衬映。李清照《声声慢》词中以“满地黄花堆积”，来陪衬“寻寻觅觅，冷冷清清，凄凄惨惨戚戚”的词中人，所采用的手法与这首诗是相同的。\n\n　　从时间布局看，诗的第一句是写时间之晚，第三句是写季节之晚。从第一句纱窗日暮，引出第二句窗内独处之人；从第三句空庭春晚，引出第四句庭中飘落之花。再从空间布局看，前两句是写屋内，后两句是写院中。写法是由内及外，由近及远，从屋内的黄昏渐临写屋外的春晚花落，从近处的杳无一人写到远处的庭空门掩。一位少女置身于这样凄凉孤寂的环境之中，当然注定要以泪洗面了。更从色彩的点染看，这首诗一开头就使所写的景物笼罩在暮色之中，为诗篇涂上了一层暗淡的底色，并在这暗淡的底色上衬映以洁白耀目的满地梨花，从而烘托出了那样一个特定的环境气氛和主人公的伤春情绪，诗篇的色调与情调是一致的。\n\n　　为了增强画面效果，深化诗篇意境，诗人还采取了重叠渲染、反复勾勒的手法。诗中，写了日落，又写黄昏，使暮色加倍昏暗；写了春晚，又写落花满地，使春色扫地无余；写了金屋无人，又写庭院空寂，更写重门深掩，把诗中人无依无伴、与世隔绝的悲惨处境写到无以复加的地步。这些都是加重分量的写法，使为托出宫人的怨情而着意刻画的那样一个凄凉寂寞的境界得到最充分的表现。\n\n　　此外，这首诗在层层烘托诗中人怨情的同时，还以象征手法点出了美人迟暮之感，从而进一步显示出诗中人身世的可悲、青春的暗逝。曰“日落”，曰“黄昏”，曰“春欲晚”，曰“梨花满地”，都是象征诗中人的命运，作为诗中人的影子来写的。这使诗篇更深曲委婉，味外有味。', poem_tags = '唐诗三百首,宫怨,孤独' WHERE poem_title = '春怨' AND poem_author = '刘方平';
UPDATE edu_poem SET poem_translation = '小小星辰光朦胧，三个五个闪天东。天还未亮就出征，从早到晚都为公。彼此命运真不同。\n小小星辰光幽幽，原来那是参和柳。天还未亮就出征，抛撇香衾与暖裯。命不如人莫怨尤。', poem_notes = '嘒（huì慧）：微光闪烁。\n三五：一说参三星，昴五星，指参昴。一说举天上星的数。\n肃肃：疾行的样子。宵：指下文夙夜，天未亮以前。征：行。\n夙（sù素）：早。\n寔：“实”的异体字。是，此。或谓即“是”。\n维：是也。参（shēn申）：星名，二十八宿之一。昴（mǎo卯）：星名，二十八宿之一，即柳星。\n抱：古“抛”字。衾（qīn钦）：被子。裯（chóu绸）：被单。\n犹：若，如，同。', poem_appreciation = '《毛诗序》云：“《小星》，惠及下也。夫人无妬忌之行，惠及贱妾，进御于君，知其命有贵贱，能尽其心矣。”韩诗说与毛异，《韩诗外传》卷一引“曾子仕于莒”以说诗，谓“家贫亲老，不择官而仕”，引诗曰：“夙夜在公，实命不同。”《容斋随笔》以为此诗是“咏使者远适，夙夜征行，不敢慢君命”之意，用韩说也。《白帖》引“肃肃宵征，夙夜在公”入“奉使类”。姚际恒《诗经通论》云：“章俊卿以为‘小臣行役之作’，是也。”并驳毛传郑笺，以为诗中情景，于毛传不类者三，于郑笺不通者三。魏源《诗古微·召南答问·小星》总结各家，更加详说。郑笺孔疏附会毛传者非，不如申韩各家之说。\n\n　　申韩各家中引诗《北山》：“或燕燕居息，或尽瘁事国；或息偃在床，或不已于行。”解释《小星》之“寔命不同”，更合诗义。但谓“抱衾与裯”一句，指行人所携之“襆被”，或役夫所携之“行帐”，则似是而实非。他们注意了句中“衾裯”两字，在“衾裯”两字上做文章，不知道“抱”即古“抛”字。钱大昕《声类》：“抱，古抛字。《史记·三代世表》：‘抱之山中，山者养之。’《集解》：‘抱音普茅反’。”（详见《声类疏证》，上海古籍出版社出版）。诗言“抱衾与裯”者，说征人役夫“肃肃宵征”，抛却室家之乐，夫妻之爱也。唐人李商隐诗云：“为有云屏无限娇，风城寒尽怕春宵。无端嫁得金龟婿，孤负香衾事早朝”。说李诗是从《齐风·鸡鸣》“虫飞薨薨，甘与子同梦”，蜕化而来，可。说李诗从《小星》“抱衾与裯，寔命不犹”发展而来，亦可。因居者言之，则妻子怨早朝之孤负香衾；因行者言之，则自伤其“抛却衾裯”也。\n\n　　第一章之前两句云：“嚖彼小星，三五在东。”姚际恒所谓：“山川原隰之间，仰头见星，东西历历可指，所谓戴星而行也。”\n\n　　征人奔走，为赶行程，凌晨上道。忽见小星，三五在天，睡眼惺忪，初亦不知其星何名也。言在东者，东字与公、同趁韵，不必定指东方。第二章云：“嚖彼小星，维参与昴。”征人睡梦才醒，故初见晨星，不知何名。继而察以时日，然后知其为参星与柳星。第一章只言小星，三五在东，不言星名；第二章既说小星，又说乃参乃柳，这就是诗分章次的道理。诗虽写景，而情亦隐见其中。\n\n　　诗之每章后三句主要言情者，第一章云：“肃肃宵征，夙夜在公。寔命不同。”“夙夜”旧释“早夜”，“日未出，夜未尽，曰早夜”。夙夜或早夜都不是两字平列，而是上字形容下字的偏正结构。征人天不明即行，可见其不暇启处，忙于王事。《北山》诗云：“或燕燕居息，或尽瘁事国；或息偃在床，或不已于行；或不知叫号，或惨惨劬劳；或栖迟偃仰，或王事鞅掌；……”可见同为“王臣”，同为“职司”，工作并不相等，遭遇并不相同。第二章后三句云：“肃肃宵征，抱衾与裯，寔命不犹。”改第一章的“夙夜在公”为“抱衾与裯”。又改“同”为“犹”。改“同”为“犹”者换字叶韵。改言“抱衾与裯”者，则由于上章之“夙夜在公”，凌晨上道，弃室家之好，“抛衾与裯”也。“夙夜在公”是“抛衾与裯”之因，“抛衾与裯”是“夙夜在公”之果。文心极细，章序分明。征人之“不已于行”，较之“息偃在床”者，是“寔命不犹”。写役夫之悲，真是词情并茂。', poem_tags = '诗经,写人' WHERE poem_title = '小星' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '我并非大器，只会敷衍官事，忙碌了一天了，趁着傍晚雨后初晴，登上快阁来放松一下心情。\n举目远望，时至初冬，万木萧条，天地更显得阔大。而在朗朗明月下澄江如练分明地向远处流去。\n友人远离，早已没有弄弦吹箫的兴致了，只有见到美酒，眼中才流露出喜色。\n想想人生羁绊、为官蹭蹬，还真不如找只船坐上去吹着笛子，漂流到家乡去，在那里与白鸥做伴逍遥自在岂不是更好的归宿。', poem_notes = '快阁：在吉州泰和县(今属江西)东澄江（赣江）之上，以江山广远、景物清华著称。此诗作于元丰五年(1082)作者任泰和令时。\n痴儿了却公家事：意思是说，自己并非大器，只会敷衍官事。痴儿，作者自指。了却：完成。\n东西：东边和西边 。指在阁中四处周览。\n倚：倚靠 \n落木：落叶\n澄江：指赣江。澄，澄澈，清澈。\n朱弦：这里指琴。佳人：美人，引申为知己、知音。 \n青眼：黑色的眼珠在眼眶中间,青眼看人则是表示对人的喜爱或重视、尊重，指正眼看人 。 白眼指露出眼白，表示轻蔑。 聊：姑且。\n弄：演奏\n与白鸥盟：这里是指无利禄之心，借指归隐。', poem_appreciation = '这是黄庭坚在太和知县任上登快阁时所作的抒情小诗。\n\n　　一般说来，文章或诗歌开头往往较难，以致有的文学家常将其开头处砍去，这是因为开头处，作者还没有和作品的情境融为一体，因而容易作态。黄山谷此诗起首，用通俗口语娓娓道来，但又能构思奇妙，引人入境。诗人说，我这个呆子办完公事，登上了快阁，在这晚晴余辉里，倚栏远眺。这二句，看似通俗浅近，却包涵着极为丰富的内容：前句是用《晋书·傅咸传》所载夏侯济之语，“生子痴，了官事，官事未易了也。了事正坐痴，复为快耳！“后句用杜甫“注目寒江倚山阁“及李商隐“万古贞魂倚暮霞“之典，还多有翻新出奇之妙。“痴儿“二字翻前人之意，直认自己是“痴儿“，此为谐趣之一；“了却“二字，渲染出了诗人如释重负的欢快心情，与“快阁“之“快“暗相呼应，从而增加了一气呵成之感此为妙用二；“倚晚晴“三字，更是超脱了前人的窠臼。杜诗之“倚“，倚于山阁，乃实境平叙；李诗之“倚“，主语为“万古贞魂“，乃虚境幻生而成；黄诗之“倚“，可谓虚实相兼；诗人之“倚“，乃是实景，但却倚在无际无垠的暮色晴空。读此三家，宛如一幅艺术摄影，在晚霞的逆光里，诗人与亭阁的背影......\n\n　　不仅如此，“倚晚晴“三字，还为下句的描写，作了铺垫渲染，使诗人顺势迸出了“落木千山天远大，澄江一道月分明“的绝唱。远望无数秋山，山上的落叶飘零了，浩渺的天空此时显得更加辽远阔大，澄净如玉的澄江在快阁亭下淙淙流过，一弯新月，映照在江水中，显得更加空明澄澈。这是诗人初登快阁亭时所览胜景的描绘，也是诗人胸襟怀抱的写照。读这样的诗句，不禁使人想起杜甫“无边落木萧萧下，不尽长江滚滚来“和谢眺“余霞散成绮，澄江净如练“的名句。但黄山谷之句，既汲取了前辈的养料加以锻炼熔造，又是新的境界再现。所以前人曾评此二句道：“其意境天开，则实能劈古今未泄之奥妙。“（张宗泰《鲁斋所学集》）\n\n　　五、六二句，是诗人巧用典故的中句。前句用伯牙捧琴谢知音的故事。《吕氏春秋·本味篇》载：“钟子期死，伯牙破琴绝弦，终身不复鼓琴，以为世无足复为鼓琴者。“后句用阮籍青白眼事。史载阮籍善为青白眼，“见礼俗之士，以白眼对之“，见所悦之人，“乃见青眼“（《晋书·阮籍传》）。诗人这二句大意是说，因为知音不在，我弄断了琴上的朱弦，不再弹奏，于是只好清樽美酒，聊以解忧了。此处“横“字用得很生动，把诗人无可奈何、孤独无聊的形象神情托了出来。\n\n　　结句诗人说自己希望能坐上归船，吹弄着悠扬的长笛，回到那遥远的故乡——我的这颗心呵，早已和白鸥订好盟约了。从全诗的结构看，这个结尾是相当精彩的：起首处诗人从“痴儿了却官家事“说起，透露了对官场生涯的厌倦和对登快阁亭欣赏自然景色的渴望；然后，渐入佳境，诗人陶醉在落木千山，澄江月明的美景之中，与起首处对“公家事“之“了却“形成鲜明对照；五、六句诗人作一迭宕：在良辰美景中，诗人心内的忧烦无端而来，诗人感受到自己的抱负无法实现、自己的胸怀无人理解的痛苦。那么，解脱的出路何在呢？这就很自然地引出了诗人的“归船“、“白鸥“之想。这一结尾，不但呼应了起首，顺势作结，给人以“一气盘旋而下之感“（潘伯鹰评语）。而且意味隽永，让人想象无穷。\n\n　　全诗明白如话，因景抒情寄慨，字字紧扣，层层关联，用典贴切，无一字无来处，体现了江西诗派用字新奇、笔力雄健的特点。\n\n　　此诗极受后人称赏。姚鼐称此诗“豪而有韵，此移太白歌行于七律内者“；方东树评析说：“起四句且叙且写，一往浩然，五、六句对意流行。收尤豪放。此所谓寓单行之气于排偶之中者。“这些评析都是十分切中肯綮的。翁方纲评黄山谷诗云：“坡公之外又出此一种绝高之风骨，绝大之境界，造化元气发泄透矣。“细吟此诗，当知无愧。\n\n　　黄庭坚作诗以学杜甫为宗旨，专意学其“拗句”；又提倡“无一字无来处”而“点铁成金”、“夺胎换骨”，从而形成独具风格的“山谷体”。体现其特征的作品如：\n\n　　石吾甚爱之，勿遣牛砺角。牛砺角尚可，牛斗残我竹。(《题竹石牧牛》)\n\n　　对“落木千山天远大，澄江一道月分明”的赏析\n\n　　“远望群山，落木萧萧。天空开阔明朗，眺望江水，澄净江面上的月色皎洁明净。\n\n　　这种景表现了诗人对官场生活厌倦和投身自然的愉悦。', poem_tags = '古诗三百首,高中古诗,登楼,写景,抒情' WHERE poem_title = '登快阁' AND poem_author = '黄庭坚';
UPDATE edu_poem SET poem_translation = '江面上吹过一阵秋风，江岸上的落花在夕照中纷纷飘落。\n离别之情让远去的笛声吹送，并随秋风吹到乱山的东面。', poem_notes = '漾：吹过。\n脱：脱下。\n被：让。\n横笛：横吹的笛子，这里指笛声。', poem_appreciation = '这首诗非常注意抓住江上特有的景物，从视觉和听觉两个角度，扣住“秋天”这特定的节令特点，描绘江上的秋色，给人留下极深的印象。江水浩淼无边，江畔红花朵朵，而到了秋季，西风劲吹，水面则起波浪，荡漾连绵，江花也渐次凋谢，脱下了红妆，那岸边或水上的小舟传来横笛声，也就使景色带上了浓浓的秋意，勾起作者的思绪。江水江花、西风横笛，这些特有时令的特定景物，就构成了一幅色彩浓烈的“江上秋意图”，具有鲜明的特色。\n\n　　此诗一、二句两写景，其目的并不在要再现什么秋声秋色，而是旨在以比兴手法，用景衬情：猎猎的西风带来秋的消息，令人心生愁绪，绵绵的江水长流不息，让人顿时产生感触，晚开的花儿飘落，正所谓落红无数，也让人郁郁寡欢。这些景物，都带上了浓浓的感情色彩，使人愁肠百结。而三、四两句，则题旨非常鲜明地凸现出来：“离情被横笛，吹过乱山东。”特定的季节、特定的景物，触动了诗人的离情别绪：是自己远离故乡、孤身在外，涌起了桑梓之思，或者是亲人在外飘泊、时世动乱，勾起了眷怀之恋。整首诗，景为情出，情因景生，情景交融，寄寓深沉，深隽的诗韵诗味。\n\n　　对于离情让横笛吹送的问题，古文学者刘逸生先生有这样详尽的解释：诗人刚和亲人分手，坐上向远方而去的船，看着江上的风光，秋意甚浓，也使满怀离情的诗人更添伤感，忽地不知何处传来笛声，呜呜咽咽的，听的更是心情沉重，而笛声一直没停，让诗人更感折磨，不过，蓦然抬头，原来船已转到乱山的东边，适才与亲人分别的渡口，都已望不到了。这是一种奇特的化虚为实的手法。\n\n　　诗到宋代，很讲究炼字炼句。王安石的“春风又绿江南岸”（《泊船瓜洲》）是个著名的例子。从这首诗看，也是如此。因笛声而引起离情，李白就写过他的《春夜洛城闻笛》说：“谁家玉笛暗飞声，散入春风满洛城。此夜曲中闻折柳，何人不起故园情？”仿佛是随口而成，自然明畅；但王安石就不愿追随这种风格，他一定要把“离情”写成是一种“异化之物”，是能够让风吹着走的。这正是注意了锻炼，让句子显出不寻常的曲拆。', poem_tags = '秋天,写景,感伤,离别' WHERE poem_title = '江上' AND poem_author = '王安石';
UPDATE edu_poem SET poem_translation = '天上宫阙，白玉京城，有十二楼阁，五座城池。\n仙人为我抚顶，结受长生命符。\n突然想来人间一游，误逐世间的环乐，以尽前缘。\n人间从开始到现在已经有九十六圣君，空名挂于浮云端。\n以天地为赌注，一掷决定命运，一直战争不停。\n我曾经学习霸王战略，希望能功成名就，锦衣返乡。\n可是时运不佳，长期漂泊五湖四海。\n曾经去山东学剑，没有什么结果，会写点文章，可那有什么用呢？\n剑术并非万人之敌，防防身的技术，文章倒是四海闻名，罕有人匹敌。\n这些都是些儿戏，微不足道，所以我象梁鸿一样看破了世界，唱着五噫歌离开西京长安。\n不过在临去之时，我还是流下了慷慨激扬的泪水，打湿了我的帽上红缨。\n叹君也是个倜傥之才，气质品格冠群英。\n道旁设帐为我饯行，慰籍我此次远征的艰辛。\n鞍马生涯如浮云，送我送在骠骑亭。\n歌声钟鼓声表达不尽你的情意，白日马上就要落在昆明池中。\n我曾经在某年十月到达幽州，看见安禄山的军阵兵甲灿烂如群星。\n君王唐玄宗放弃东北河北，整个地区都由安禄山横行无忌，犹如长鲸在海洋横行。\n呼吸之间就走遍百川，燕然山也仿佛可被他摧毁。\n我心知我在皇上那里不得意，说也无用，只好躲入桃花源，独善一身。\n想弯弧射天狼，挟着弓却不敢张开，怕祸及自己。\n我曾经在北京黄金台揽涕痛哭，呼天喊地：燕昭王啊你在那里啊，怎么没有人识用人才？\n无人珍贵骏马之骨，天马空自腾骧，不得大用。\n即使乐毅再生，到如今这样的形势，也只有逃命的份儿。\n岁月蹉跎，不得人意，驱骑马儿来到贵乡。\n正逢你在悠闲地欣赏弦歌，肃穆地坐在华美的厅堂。\n你如远古的百里之王候，陶然而卧如羲皇伏羲氏一般。\n行乐在昌乐馆，大开酒筵，罗列壶觞。\n青娥美女夹坐在贤豪之间，对着烛光俨然成双成行。\n醉舞纷纷散满绮席，清歌袅袅绕飞尘梁。\n欢娱完毕，你秩满（丧礼守孝期满）以后就要回归咸阳。\n饮宴送行的有万人之多，帐蓬遥遥相望。\n这一别，我俩各隔千里，荣枯不用，炎凉各自。\n炎凉几度变化，九州几乎崩溃。\n唐军抗战叛军，沙尘使云海昏暗无光。\n连草木都摇着杀气，星辰更是无光。\n白骨堆成丘山，苍生竟有何罪，遭此劫难。\n潼关函谷关捍卫皇帝宫殿，国命悬于哥舒翰一身。\n不料长戟三十万的大军，竟然开关门投降元凶。\n公卿官僚犹如犬羊，忠诚正直的人变为肉酱。\n二圣逃离京城，两座京城变为废墟。\n帝子永王受皇上诏命，军事管制楚地。\n永王节制并非是想做春秋五霸中齐桓公与晋文公，永王的军师却拥有勇猛的将士。\n人心失去体统，贼势腾起风雨。\n唯有你固守房陵郡，忠诚高节勇冠终古。\n我那时云卧庐山香炉峰顶，学仙人餐霞漱瑶泉。\n草堂门开九江流转，枕头下面五湖相连。\n半夜永王的水军来浔阳，城里城外遍插旌旃。\n我被空名自误，永王派兵迫胁我上了他的楼船。\n他曾经赐与我五百两黄金，我把黄金视为浮烟。\n我辞去永王的官却不受赏，反而远谪到夜郎那样的穷山恶水的地方。\n夜郎离这里万里之遥道，西去令人衰老。\n海内六合，扫荡清静，我却像负霜之草。\n日月普照，并无私心，有什么办法可以诉冤给苍天听听。\n你是神明的太守，深知仁心爱民。\n惭愧作你的青云客，三次登上黄鹤楼。\n惭愧不是祢衡处士，虚对鹦鹉洲。\n樊山霸气已尽，天地一派寥落秋色。\n长江漂流着峨眉山的雪水和三峡的急流。\n万舸千舟江上往来，连帆一片过扬州。\n登高极目，万里悠悠，旷然散我忧愁。\n纱窗倚天而开，水树翠绿如少女青发。\n看太阳，怕它马上落山，举起酒杯喜得明月。\n吴越美女艳如花，窈窕婀娜，浓装艳抹。\n呼来款款轻上云梯，含笑羞羞步出帘栊。\n对着客人清唱小垂手，罗衣飘摇舞春风。\n跪请宾客休息，主人情还未了。\n浏览你在荆山的大作，堪与江淹鲍照的文笔媲美。\n宛如出清水的芙蓉，有大自然天然去雕饰。\n逸兴满溢平素的襟怀，无时不想到你的招寻约请。\n朱门拥立虎士，兵戟罗列森森。\n剪竹凿石，溪流清深宛然而去。\n登高楼坐水阁，吐论滔滔不绝，声音清朗。\n言辞贵于白璧，一诺重于黄金。\n称我不愧于你，宛如青鸟有丹心。\n云间五色的喜鹊，飞鸣着从天上飞来。\n传闻是大赦的文书到了，却被流放夜郎去。\n顿时就如没有暖气的寒谷，没有炎烟的死灰，没有希望了。\n贤君你马上要登朝廷的凤凰池去了，别忘记了我这个被遗弃的贾谊，有机会推荐一下。\n桀犬吠尧，古来之理，别让匈奴千秋笑话我们。\n我常常在中夜失眠，唉声叹气，为这大国忧愁啊。\n旌旆飘飘夹两岸之山，黄河当中奔流。\n群雄相互牵掣，不能一致行动，面对战场犹豫不决。\n如何才有善射的后羿那样的良将，一箭射落敌军的元凶。', poem_notes = '题下原注：“江夏，岳阳。”韦太守良宰：即江夏郡太守（鄂州刺史）韦良宰。《元和姓纂》卷二韦氏彭城公房：“庆祚生行祥、行诚、行佺。……行佺，尚书右丞，生亮宰、利见。”此诗之韦良宰当即其人，即韦行佺之子，韦利见之兄。\n天上二句：道教认为天上有白玉京，昆仑山上有五城十二楼。\n结发句：指年轻时接受道教长生不老之术。\n穷理乱：研究治乱。因避唐高宗李治讳，改“治”为“理”。\n九十六圣君：指自秦始皇至唐玄宗共九十六代皇帝。\n天地二句：谓这些帝王像赌博投掷一样，通过战争来争夺天下。\n霸王略：称霸成王的策略。\n轩冕：华美的车乘和高级官员所戴礼帽，代指高官显宦。\n时命句：谓自己命运不好。\n学剑四句：《史记·项羽本纪》：“项籍（项籍字羽）少时，学书不成，去学剑，又不成。项梁怒之。籍曰:‘书，足以记名姓而已。剑，一人敌，不足学，学万人敌。’”于是项梁又教项藉兵法。自哂：自我微笑。此为李白感叹自己学武不成，转而以诗文扬名四海。\n五噫句：《后汉书·梁鸿传》：“因东出关，过京师，作《五噫》之歌曰：‘陟彼北芒兮，噫！顾瞻帝京兮，噫！宫阙崔嵬兮，噫！民之劬劳兮，噫！辽辽未央兮，噫！’肃宗闻而非之，求鸿不得。乃异姓运期。名燿，字侯光，与妻子居齐鲁之间。”此处喻指自己离京而隐居。西京，即长安。\n倜傥才：卓异的才能。\n标举：高超。\n祖帐：在郊外设帐摆宴饯别。\n骠骑亭：地址不详。王琦谓玩诗意当在长安。\n昆明：池名，故址在今陕西西安市西南丰水和潏水之间。公元前年（汉武帝元狩三年）为准备和昆明国作战训练水军以及为解决长安水源不足而开凿。\n幽州：在今北京市及河北北部。公元年（天宝元年）改为范阳郡，公元年（乾元元年）复改幽州。李白于公元年（天宝十载）北上，年（天宝十一载）十月抵达范阳郡治所（今北京市）。时安禄山为范阳节度使。\n戈鋋句：鋋，短矛。此处以“戈鋋”泛指兵器。罗星，罗列如星，形容众多。此以兵器之多说明军队严阵备战，预示安禄山即将叛乱。\n君王二句：谓唐玄宗将北方大片土地交给安禄山。公元年（天宝元年），玄宗任安禄山为平卢节度使。年（天宝三载），代裴宽为范阳节度使，仍领平卢军。经略威武、清夷等十一军，及榆关守捉、安东都护府兵三十万余，皆归其所统。幽、蓟、妫、檀、易、恒、定、莫、沧、营、平十一州之地皆归其所治。公元年（天宝十载），又兼河东节度使。二句即指此。\n呼吸二句：形容安禄山气焰嚣张，如长鲸呼吸可使百川奔腾，燕然山倒塌。燕然，山名，现名杭爱山，在今蒙古人民共和国境内。\n蓬灜：即蓬莱、瀛洲，传说大海中的仙山。\n天狼：星名。《史记·天官书》：“其东有大星曰狼。”张守节正义：“狼为野将，主侵略。”此指安禄山。\n黄金台：相传为战国时燕昭王所筑，因曾置千金延请天下之士，故名。今北京市和徐水、满城、定县等县皆有黄金台，多系后世慕名赴会。\n骏骨：千里马之骨。典出《战国策·燕策一》：燕昭王预招天下贤士，报齐破燕之仇。郭隗对燕昭王云：古代一君主用千金求千里马，三年不能得。有侍臣用五百金买一千里马尸骨，君王怒曰死马何用。侍臣说，买死马尚肯用五百金，天下人必信君王诚心求马。千里马将不求自至。不久，果然来了三匹千里马。今君王诚心招贤，先从我郭隗开始，必有贤于郭隗者为大王用。\n騄駬句：騄駬，骏马名，周穆王“八骏”之一。腾骧，奔跃。此句比喻贤人无法施展才能。\n乐毅二句：《史记·乐毅列传》载：乐毅至燕，为燕昭王重用，攻下齐国七十余城，立下大功。但昭王死后，齐国用离间计使燕惠王疑忌乐毅，燕惠王就派骑劫代乐毅为将，乐毅被迫奔赵。\n贵乡：唐县名，在今河北大名县东北。\n弦歌：用孔子弟子子游弦歌而治武城之典，喻指韦良宰当时为贵乡县令。\n百里二句：《三国志·蜀志·庞统传》：“统以从事守耒阳令，在县不治免官。吴将鲁肃遗先主书曰：‘庞士元非百里才也。’”后因以百里才指治理一县的人才。太古，远古。陶然，和乐安闲的样子。羲皇，指伏羲氏。古人想像伏羲氏时代的人无忧无虑，生活安闲。此处赞颂贵乡县在韦良宰治理下民风淳朴，社会安定，像远古伏羲氏时代一样。\n昌乐：县名，今河南南乐县。\n贤豪：贤能勇壮之士。\n俨：恭敬的样子。\n清歌句：用《列子·汤问》故事。战国时代，韩娥到齐国去，途中缺粮，在雍门唱歌乞食，歌声余音绕梁，三日不绝。比喻歌舞音乐美妙。\n未终朝：极言时间之短。\n秩满：指韦良宰为贵乡县令的任期已满，回长安等候调遣。\n祖道：践行。\n供帐：践行所用之帐幕。\n荣枯句：谓季节变换，草木开花衰萎，暑寒更迭，相别多年。\n九土句：指安禄山叛乱。九土，犹九州，全国。横溃，以水喻乱。\n汉甲句：指唐军与叛军接战。\n函关句：谓函谷关形势险要，使长安显得雄壮。函谷关，古关在今河南灵宝东北，战国时秦置。因关在谷中，深险如函而名。其东自崤山，西至潼津，通名函谷，号称天险。乃古时由东方入秦的重要关口。公元前年（汉武帝元鼎三年），徙关至今河南新安县东，离故关三百里，称新函谷关。\n哥舒：指哥舒翰。《旧唐书·哥舒翰传》：“及安禄山反，上以封常清、高仙芝丧败，召翰入，拜为皇太子先锋兵马元帅。……据贼于潼关。”\n长戟二句：长戟，兵器名，此代指士卒。凶渠，指叛军将领。《旧唐书·哥舒翰传》：“引师出关，……军既败，翰与数百骑驰而西归，未火拔归仁执降于贼。”二句即指哥舒翰投降安禄山之事。\n奴犬羊：为犬羊（指安史叛军）所奴役。\n忠谠句：谓忠诚敢言之士惨遭杀害。醢与菹，即菹醢，肉酱。此处用作动词，即被杀戮。\n二圣句：指唐玄宗与肃宗逃亡在外。游豫，游乐，逃亡的讳辞。\n二京：指长安与洛阳。\n帝子句：帝子，指永王李璘，玄宗之子。专征，皇帝给予统兵征讨的权力。\n秉旄句：秉旄，掌握军队。旄，古时旗杆上用旄牛尾做的装饰。《书·牧誓》：“右秉白旄以麾。”强楚，指强盛富庶的南方。\n节制二句：《荀子·议兵》：“秦之锐士，不可以当桓、文之节制。”此处反用其意，谓永王军队非春秋时齐桓公、晋文公约束有方之师。熊虎，喻勇猛的士兵。《书·牧誓》：“尚桓桓，如虎如貔，如熊如罴。”此句谓统帅无方，徒有强壮之兵。\n固房陵：坚守房陵。房陵，即房州，公元年（天宝元年）改为房陵郡，公元年（乾元元年）复为房州。郡治在今湖北房县。\n诚节句：谓韦良宰忠诚的节操超过古人，坚守岗位，不为永王所迫。\n香炉顶：香炉峰。庐山北部的著名山峰。因水气郁结峰顶，云雾弥漫如香烟缭绕，故名。\n九江：古代传说，长江流至浔阳分为九道，故浔阳亦名九江，即今江西九江市，此处指长江。\n五湖：此处指庐山下的湖泊。其时李白隐居庐山屏风叠，故云。\n满旌旃：形容军中旌旗之多。\n翻谪：反而被贬谪流放。\n六合：古人以天地、四方为六合。\n良牧：贤明的地方长官。指韦良宰。\n恤交道：顾念好友。\n一忝句：忝，谦词，辱，有愧于。辱为青云之客，乃李白为韦太守贵宾的客套话。\n黄鹤楼：故址在今湖北武汉市蛇山黄河矶上。相传始建于公元年（三国吴黄武二年），历代屡毁屡建。传说费祎登仙，每乘黄河于此憩驾，故号为黄鹤楼。\n祢处士：东汉末名士祢衡。《文选》卷十三祢衡《鹦鹉赋序》述祢衡为黄祖太子射作《鹦鹉赋》事。\n樊山：在今湖北鄂城县西，三国时孙权曾在此建立霸业。樊，原作“焚”，注云：“一作樊”。今按作“焚”误。\n横穿：一作“川横”。\n舸：大船。\n吴娃二句：吴娃、越艳，指吴越美女。窈窕，娇美的样子。铅红，铅粉和胭脂。\n帘栊：本指竹帘和窗棂，此处为偏义复词，指帘子。\n小垂手：古代舞蹈中的一种垂手身段。有大垂手、小垂手之分。《乐府诗集》卷七六引《乐府解题》曰：“《大垂手》、《小垂手》，皆言舞而垂其手也。”\n览君二句：荆山，在今湖北武当山东南、汉水西岸，漳水发源于此。江、鲍，指六朝诗人江淹和鲍照。二句谓江淹、鲍照如看到韦太守荆山之作，亦必能为之动情于色。\n清水二句：钟嵘《诗品》：“谢诗如芙蓉出水。”此处用以赞美韦良宰的作品清新自然，不假雕饰。\n逸兴句：谓韦良宰平素胸襟豁达，具有超逸豪放的意兴。\n朱门二句：形容郡守衙门的威势。虎士，勇猛的卫士。戟，古兵器名。按唐代制度，州府以上衙门前列戟。《新唐书·百官志》卫尉寺武器署：“凡戟，……三品及上都督、中都督、上都护、上州之门十二，下都护、中州、下州之门各十。”森森，威严的样子。\n剪凿二句：写水阁景色优美，剪竹凿石，清流萦绕。\n英音：英明卓越的见解。\n片辞二句：谓韦良宰重义尚信，片言只语比白璧、黄金还要贵重。诺，允诺。《史记·季布列传》载，汉初季布最守信用，答应别人的事一定办到。楚人谚曰：“得黄金百斤，不如得季布一诺。”\n青鸟四句：阮籍《咏怀诗》：“谁言不可见，青鸟明我心。”此处即用其意。\n五色四句：唐张鷟《朝野佥载》卷四：“唐贞观末，南康黎景逸居于空青山，常有鹊巢其侧，每饭食以喂之。后邻近失布者诬景逸盗之，系南康狱，月余劾不承。欲讯之，其鹊止以狱楼，向景逸欢喜，似传语之状。其日传有赦，官司诘其来，云路逢玄衣素衿人所说。三日而赦至。景逸还山，乃知玄衣素衿者，鹊之所传也。”四句即用此事。\n暖气二句：以寒谷变暖、死灰复燃喻己流放遇赦。\n凤池：凤凰池。《通典·职官志三》：“魏晋以来，中书监令掌赞诏命，记会时事，典作文书，以其地在枢近，多成宠任，是以人固其位，谓之凤凰池焉。”此处泛指朝廷要职。\n贾生；即汉代文人贾谊，此处为诗人自比。\n桀犬句：桀，夏朝末代君主，此处以桀犬喻叛将余兵，以尧喻唐朝皇帝。按其时安禄山已死，其部史思明、史朝义仍在作乱。\n匈奴句：《汉书·车千秋传》：“千秋无他材能学术，又无伐阅功劳，特以一言悟主，旬月取宰相封侯，世未尝有也。后汉使者至匈奴，单于问曰：‘闻汉新拜丞相，何用得之？’使者曰：‘以上书言事故。’单于曰：‘苟如是，汉置丞相非用贤也，妄用一男子上书记得之矣。’”此处喻指当时宰相苗晋卿、王玙等皆庸碌无能之辈。\n旌旆二句：谓黄河西岸战争仍未平息。两山，指黄河两岸的太华、首阳二山。\n连鸡：缚在一起的鸡，喻互相牵制，行动不能一致。《战国策·秦策一》：“诸侯不可一，尤连鸡之不能俱止于栖亦明矣。”\n夷犹：犹豫不进。\n羿：又称后羿，传说中夏代东夷族领袖，原为有穷氏部落首领，善于射箭。\n旄头：又作“髦头”，星宿名，即昴宿。古人认为昴宿是胡星，旄头星特别亮时，预示有胡兵入侵。此处指安史叛军。', poem_appreciation = '此诗是李白公元760年（唐肃宗上元元年）滞留江夏时所作的一首自传体长诗（按此诗作年，王谱、詹谱、王增谱、安谱、郁本、安本作公元759年，黄谱、裴谱作公元760年）。诗人因受永王之败的牵连，被流放至夜郎，中途获上赦宥。此诗是在他被赦免后所作。在这个时候与韦良宰这样一个老朋友相见，李白的感慨当然是很深的。其中最强烈的莫过于他已由旧日的御前歌手沦为一个流犯，而对方已由一介平凡的知县成为名镇一方的主座了。其中一个首要缘由就是韦良宰在骚动变乱中作出了与李白不同的选择。面对老友，李白除了叙及他们的交往始末，着意向他诉说了本身的不幸与委屈，还告诉老朋友骚动变乱前自己北上幽州就是为了探察安禄山的虚实。这如同下面诠释入永王幕的缘故一样，也是为了消除老朋友的误会，表明自身在政治态度上的清白。\n\n　　这是诗人写的最长一首抒情诗，诗人以自己的人生经历和同韦良宰的交往为中心，尽情抒发了自己的政治感慨。其中如“十月到幽州”之句所产生的岐义，作为一个大诗人，他不可能感觉不到这一点。对于此只能作一种解释，这是诗人在事后有意造出的一种恍惚语境。他知道这首诗不只是写给这一个老朋友看的，他是有意向世人明示自己在乱世中的态度与先见之明。\n\n　　此诗流传最广的是“清水出芙蓉，天然去雕饰”两句。其意思是，像那刚出清水的芙蓉花，质朴明媚，毫无雕琢装饰，喻指文学作品要像芙蓉出水那样自然清新。雕饰：指文章雕琢。这两句诗赞美韦太守的文章自然清新，也表示了李白自己对诗歌的见解，主张纯美自然——这是李白推崇追求的文章风格，反对装饰雕琢。李白自己的作品也正是如此，后人经常引用这两句评价李白的作品。', poem_tags = '赠别,忧愤,自传,长诗' WHERE poem_title = '经乱离后天恩流夜郎忆旧游书怀赠江夏韦太守良宰' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '一\n　　吉祥的日子，良好的时光，恭恭敬敬娱乐天神东皇。\n　　手抚着镶玉的长剑剑柄，身上的佩玉和鸣响叮当。\n　　精美的瑶席玉瑱压四方，摆设好祭品鲜花散芳香。\n　　蕙草包祭肉兰叶做衬垫，献上桂椒酿制的美酒浆。\n　　举鼓槌敲得鼓声咚咚响，疏节奏缓拍节声调安详，又吹竽又鼓瑟放声歌唱。\n　　巫女舞姿美服装更漂亮，芬芳的香气溢满大厅堂。\n　　宫商角徵羽五音齐合奏，衷心祝神君快乐又健康。\n\n云中君\n　　我沐浴兰汤满身飘香，穿上彩衣像鲜花一样。\n　　看云神宛曲停留云端，神光灿烂气宇轩昂。\n　　你安居在云间殿堂，功德广大与日月齐光。\n　　你驾龙车穿五彩衣裳，翱翔空中游览四方。\n　　神光闪闪你从天而降，又疾速高飞重返天上。\n　　高瞻远瞩超越九州，恩被四海功德无量。\n　　思念神君长长叹息，忧心忡忡黯然神伤。\n\n湘君\n　　你犹豫不决迟迟不来，为谁停留在水中沙洲？\n　　我天生丽质又修饰打扮，急流中驾起芳香的桂舟。\n　　令沅水湘水风平浪静，让长江安安静静地流。\n　　盼望你啊你却不来，吹排箫啊我在思念谁？\n　　我驾起龙舟向北航行，掉转船头抵达洞庭。\n　　用薜荔做帘蕙草做帐，拿香荪饰桨香兰饰旌。\n　　极目骋怀遥望涔阳，扬起风帆横渡大江。\n　　一路飞舟不见你的踪影，侍女啊也为我叹息悲伤。\n　　热泪纵横不住流淌，思念你啊痛断肝肠。\n　　荡起双桨把稳船舵，飞舟破浪卷起千堆雪。\n　　薜荔长在陆上啊偏要水中采，荷花开在水中啊却上树梢折。\n　　二人不同心媒人也徒劳，恩爱不深厚轻易抛弃我。\n　　石滩上的水啊浅又浅，龙舟轻又快啊飞向前。\n　　相爱不忠诚招人长怨恨，约会不守信却说没空闲。\n　　早晨在江边急速奔走，傍晚泊舟在北洲停留。\n　　孤独的鸟儿在屋上栖息，弯弯的江水在堂前缓流。\n　　把玉块抛向滚滚江流。\n　　把玉佩丢在澧水之滨。\n　　在芳洲上采摘杜若，赠给下女聊表寸心。\n　　时光匆匆不会再来，放宽心怀静候佳音。\n\n湘夫人\n　　夫人降临在江北小洲，我望眼欲穿心中哀愁。\n　　秋风袅袅万木飘落叶，波涌浪翻千里洞庭秋。\n　　登上白薠岗举目远望，与佳人约会相见黄昏后。\n　　鸟儿为啥聚集水草里，鱼网为啥挂在树枝头？\n　　沅水有白芷，澧水有香兰，心中思念你，口中未敢言。\n　　恍恍惚惚向远方张望，但见湘江北去流水潺潺。\n　　驼鹿为啥觅食在庭院，蛟龙为啥回游在水边？\n　　早晨在江边跃马飞驰，傍晚渡过江到了西岸。\n　　听到夫人的亲切召唤，驾起快车一同归乐园。\n　　宫室豪华筑在水中央，荷叶圆圆盖在屋顶上。\n　　香荪饰墙紫贝铺庭院，花椒香味浓郁充满厅堂。\n　　桂木做正梁，木兰做椽子，辛夷做门楣，白芷饰卧房。\n　　湘夫人编织薜荔巧手做帷帐，剖开蕙草放在帐顶上。\n　　白玉为镇压住坐席，摆上石兰满室芬芳。\n　　荷叶屋顶再加放白芷，杜衡缠绕让满院飘香。\n　　聚集百草布满庭院，香花摆在门旁走廊。\n　　九疑众神前来迎接，群神云集纷纷扬扬。\n　　把香囊抛向滚滚江流，把禅衣扔在澧水之滨。\n　　在沙洲上拔取杜若，赠寄远方人聊表寸心。\n　　好时光不能骤然得到，且逍遥等待吉日良辰。\n\n大司命\n　　敞开了天国的大门，我乘上浓密的乌云。\n　　命令旋风为我开道，叫那暴雨洗洒路尘。\n　　神君盘旋从空中下降，我紧跟着你越过空桑。\n　　九州上芸芸众生闹嚷嚷，谁生谁死都握在我手上。\n　　高空里我安详地飞翔，乘天地正气驾驭阴阳。\n　　我虔诚恭敬紧跟着你，把上帝权威带到九州上。\n　　神衣飘动啊长又长，玉佩闪烁啊放光芒。\n　　一阴一阳啊变幻莫测，我做的事啊众人怎知详。\n　　折一枝神麻的玉色花朵，送给你这将离去的神灵。\n　　衰老已经渐渐地到来，不亲近就更要疏远感情。\n　　我乘着龙车车声辚辚，高飞冲天啊直入重云。\n　　手持一束桂枝久久伫立，愈是想念啊愈是伤心。\n　　伤心哀愁又有什么用，但愿像现在康健无损。\n　　人的寿命本来有定分，死生离合啊怎能由人？\n\n少司命\n　　芬芳的秋兰，洁白的麋芜，并列生长在堂下漫布。\n　　绿色的叶子，白色的花朵，香气浓郁沁入我的肺腑。\n　　人们自有娇美的小儿女，你为何还要替他们愁苦？\n　　秋天的兰花真茂盛，绿叶紫茎郁郁葱葱。\n　　满堂的人儿都倾慕你，只对我传情把秋波送。\n　　来时默默走时无言语，乘风驾云飘然离我去。\n　　悲哀莫过于有情人离别，欢乐莫过于知心人团聚。\n　　荷叶做衣蕙草做腰带，匆匆而来忽然飘天外。\n　　傍晚时你投宿在帝郊，云端里你又把谁等待？\n　　想与你一同沐浴在咸池，想与你同晒头发在山窝。\n　　盼望美人啊美人不来，心神恍惚啊当风高歌。\n　　孔雀车盖翡翠旗旌，飞上九天扫除彗星。\n　　一手举长剑一手抱幼童，保护老百姓神中你最行。\n\n东君\n　　一轮红日将出现在东方，照耀我的栏杆神木扶桑。\n　　抚拍我的宝马安步缓行，夜色渐渐消失露出曙光。\n　　驾着龙车车声如雷响，遍插云旗旗帜随风扬。\n　　长叹一声将要升天去，低头徘徊又把故乡望。\n　　车声旗色娱乐人心醉，观者着迷竟把归家忘。\n　　绷紧琴弦鼓声相对响，敲击大钟钟架摇晃晃。\n　　吹奏横笛竽笛声相和，思恋灵巫贤惠又漂亮。\n　　舞姿翩翩像翠鸟轻飞，载歌载舞齐声诵诗章。\n　　按照音律唱踏着节拍舞，群神来迎接多得遮太阳。\n　　青云做衣白霓做裙裳，高举长箭射杀贼天狼。\n　　操持天弓向西方沉落，拿起北斗舀取桂酒浆。\n　　抓住马缰绳高高飞驰，幽幽黑暗中急奔东方。\n\n河伯\n　　河神啊，与你一起游九河，急风冲起河水泛洪波。\n　　乘坐水车荷叶做车盖，双龙驾辕双螭来拉车。\n　　登上昆仑纵目望四方，心意飞扬胸怀多宽畅。\n　　日暮美景流连竟忘归，突然警醒更怀念水乡。\n　　鱼鳞做屋瓦厅堂画蛟龙，紫贝饰门阙珍珠饰玉宫，河伯啊，为何久住水中？\n　　乘上白鼋文鱼伴，同游沙洲永相随，绵绵情深如流水。\n　　与你携手向东行，送你同到河南岸。\n　　滔滔河水来欢迎，鱼儿列队来陪伴。\n\n山鬼\n　　好像有个人儿在山坳，身披薜荔女萝束细腰。\n　　含情脉脉开口微微笑，你爱我啊美丽又窈窕。\n　　赤豹前拉车，后跟大花狸，辛夷木做车桂枝做旌旗。\n　　石兰做车盖杜衡做飘带，折下香花送给意中的你。\n　　我身居竹林深处暗不见天日，通路艰难险阻使我来迟。\n　　我孤独地站在高山顶端，云海茫茫在我脚下翻卷。\n　　昏昏暗暗白昼如夜晚，东风阵阵飘洒着细雨。\n　　痴心等待你不思回返，红颜已凋谢谁来顾盼？\n　　采灵芝仙草在那巫山间，山石嶙峋葛藤蔓蔓。\n　　怨恨你失约惆怅我忘返，你也思念我只是不得闲。\n　　山中人儿纯真像杜若，啜饮石泉伫立松柏下。\n　　你想我谁知是真是假。\n　　雷声隆隆细雨飘扬，长猿夜啼声声断人肠。\n　　秋风飒飒黄叶飘零，痴情思公子徒自哀伤。\n\n国殇\n　　手持吴戈身披犀牛甲，车轮交错短兵相厮杀。\n　　旌旗蔽日阵前敌人多如云，勇士争先哪怕乱箭交坠下。\n　　强敌冲我阵，队列遭践踏，左骖倒地死，右服被刀扎。\n　　车轮深陷四匹战马被拴住，挥动鼓槌猛敲响鼓勇拼杀。\n　　苍天哀怨神灵怒气迸发，将士阵亡尸横荒野山下。\n　　勇夫出征一去不复返，荒原渺茫道路多遥远。\n　　佩带长剑秦弓拿在手，身首分离雄心永不变。\n　　真是既勇敢啊又有武艺，始终刚强啊不可侵凌。\n　　身虽死啊精神不死显威灵，就是做鬼啊也是鬼中雄。\n\n礼魂\n　　祭礼完成一齐击鸣鼓，传递鲜花轮番来跳舞，美女高唱歌声多安舒。\n　　春兰秋菊常供奉，祭礼不绝传千古。▲', poem_appreciation = '关于“九歌”名称的来历，王逸认为是屈原仿南楚的民间祭歌创作的。朱熹认为是屈原对南楚祭歌修改加工，“更定其词”（《楚辞集注》）。胡适则认为《九歌》乃古代“湘江民族的宗教歌舞”，“与屈原传说绝无关系”（《读楚辞》）。今人多取朱说。\n\n　　《九歌》由于以民间祭歌为基础，所以具有楚国民间祭神巫歌的许多特色，《汉书·地理志》说：“（楚地）信巫鬼，重淫祀。”《吕氏春秋·侈乐》也说：“楚之衰也，作为巫音。”所谓“巫音”，即巫觋祭神的乐歌，这是《九歌》与屈原其他诗篇的不同之处。但是，作品中如“载云旗兮委迤”、“九嶷缤兮并迎”、“吾道兮洞庭”等诗句，“老冉冉”、“纷总总”等习用语，又与屈原其他诗作一脉相通。因此，它应当是屈原诗歌艺术整体中的有机构成部分。\n\n　　“九歌”名称，来源甚古。除《尚书》、《左传》、《山海经》所称引者外，《离骚》中有“启九辩与九歌兮，夏康娱以自纵”，“奏九歌而舞韶兮，聊假日以乐”，《天问》中有“启棘宾商,九辩九歌”诸语。各书所说到的“九歌”内容虽有种种演化，但可证“九歌”乃是传说中很古的乐章。至于屈原用它作为篇名，似乎不会跟远古“九歌”的章数有关，也不一定跟古代“九歌”的曲调相同。可能是取其“娱神”这一点，再结合《离骚》所说的“康娱”、“乐”的意思，基本上属于新歌袭旧名的类型。\n\n　　传说中九歌本是天乐。赵简子梦中升天所听到的“广乐九奏万舞”，即《九歌》与配合著《九歌》的韶舞。（《离骚》“奏九歌而舞韶兮”。）《九歌》自被夏后启偷到人间来，一场欢宴，竟惹出五子之乱而终于使夏人亡国。这神话的历史背景大概如下。《九歌》韶舞是夏人的盛乐，或许只郊祭上帝时方能使用。启曾奏此乐以享上帝，即所谓钧台之享。正如一般原始社会的音乐，这乐舞的内容颇为猥亵。只因原始生活中，宗教与性爱颇不易分，所以虽猥亵而仍不妨为享神的乐。也许就在那次郊天的大宴享中，启与太康父子之间，为著有仍二女（即“五子之母”）起了冲突。事态扩大到一种程度，太康竟领着弟弟们造起反来，结果敌人——夷羿乘虚而入，把有夏灭了。（关于此事，另有考证。）启享天神，本是启请客。传说把启请客弄成启被请，于是乃有启上天作客的故事。这大概是因为所谓“启宾天”的“宾”字，（《天问》“启棘宾商”即宾天，《大荒西经》“开上三嫔于天”，嫔宾同。）本有“请客”与“作客”二义，而造成的结果。请客既变成作客，享天所用的乐便变为天上的乐，而奏乐享客也就变为作客偷乐了。传说的错乱大概只在这一点上，其余部分说启因《九歌》而亡国，却颇合事实。这里特别提出这几点，是要指明《九歌》最古的作用及其带猥亵性的内容，因为这对于解释《楚辞·九歌》是颇有帮助的。少司命一说是主宰人祸福的神。', poem_tags = '楚辞,祭祀' WHERE poem_title = '九歌' AND poem_author = '屈原';
UPDATE edu_poem SET poem_translation = '专心读书，不知不觉春天过完了，\n每一寸时间就像一寸黄金珍贵。\n并不是道人过来嘲笑，\n周公的精义孔子的思想教导投入钻研中。', poem_notes = '白鹿洞：在今江西省境内庐山五老峰南麓的后屏山之南。这里青山环抱，碧树成荫，十分幽静。名为“白鹿洞”，实际并不是洞，而是山谷间的一个坪地。\n春深：春末，晚春。\n一寸光阴一寸金：以金子比光阴，谓时间极为宝贵，应该珍惜。寸阴：极短的时间。\n道人：指白鹿洞的道人。\n引笑：逗笑，开玩笑。\n周情孔思：指周公孔子的精义、教导。\n追寻：深入钻研。', poem_appreciation = '赏析 　　首句叙事。“读书不觉已春深”，言自己专心读书，不知不觉中春天又快过完了。“春深”犹言春末、晚春。从这句诗中可以看出，诗人读书入神，每天都过得紧张而充实，全然忘记了时间。春天快过完了，是诗人不经意中猛然发现的。这一发现令诗人甚感意外，颇多感慨。他觉得光阴过得太快了，许多知识要学，时间总不够用似的。次句写诗人的感悟。“一寸光阴一寸金”，寸阴，指极短的时间，这里以金子喻光阴，谓时间宝贵，应该珍惜。这是诗人由第一句叙事自然引发出来的感悟，也是诗人给后人留下的不朽格言，千百年来一直勉励人们、特别是读书人珍惜时间、注重知识积累，不断充实和丰富自己。三、四句叙事，补叙自己发觉“春深”，是因为“道人来引笑”。“道人”指白鹿洞的道人。“引笑”指逗笑，开玩笑。道人修禅养性是耐得住寂寞、静得下心的了，而诗人需要道人来“引笑”，才肯放松一下，休息片刻，可见诗人读书之专心致志，非同寻常。这不，道人到来之时，诗人正在深入钻研周公孔子的精义、教导呢。“周情孔思”，当指古代读书人所读的儒家典籍。从诗人的读书生活看，诗人是惜时如金、潜心求知的人。我们应当从中受到启发和教育，知识是靠时间积累起来的，为充实和丰富自己，应十分珍惜时间才是。 ▲', poem_tags = '励志,惜时,读书' WHERE poem_title = '白鹿洞二首·其一' AND poem_author = '王贞白';
UPDATE edu_poem SET poem_translation = '枫树在深秋露水的侵蚀下逐渐凋零、残伤，巫山和巫峡也笼罩在萧瑟阴森的迷雾中。\n巫峡里面波浪滔天，上空的乌云则像是要压到地面上来似的，天地一片阴沉。\n花开花落已两载，看着盛开的花，想到两年未曾回家，就不免伤心落泪。小船还系在岸边，虽然我不能东归，飘零在外的我，心却长系故园。\n又在赶制冬天御寒的衣服了，白帝城上捣制寒衣的砧声一阵紧似一阵。看来又一年过去了，我对故乡的思念也愈加凝重，愈加深沉。', poem_notes = '玉露：秋天的霜露，因其白，故以玉喻之。凋伤：使草木凋落衰败。\n巫山巫峡：即指夔州（今奉节）一带的长江和峡谷。萧森：萧瑟阴森。\n兼天涌：波浪滔天。\n塞上：指巫山。接地阴：风云盖地。“接地”又作“匝地”。\n丛菊两开：杜甫此前一年秋天在云安，此年秋天在夔州，从离开成都算起，已历两秋，故云“两开”。“开”字双关，一谓菊花开，又言泪眼开。他日：往日，指多年来的艰难岁月。\n故园：此处当指长安。', poem_appreciation = '秋兴者，遇秋而遣兴也，感秋生情之意。《秋兴八首》是杜甫晚年为逃避战乱而寄居夔州时的代表作品，作于大历元年（公元766年），时诗人56岁。全诗八首蝉联，前呼后应，脉络贯通，组织严密，既是一组完美的组诗，而又各篇各有所侧重。每篇都是可以独立的七言律诗。王船山在《唐诗评选·卷四》中说：“八首如正变七音，旋相为宫而自成一章，或为割裂，则神态尽失矣。”\n\n　　八首之中，第一首总起，统帅后面七篇。前三首写夔州秋景，感慨不得志的平生，第四首为前后过渡之枢纽，后四首写所思之长安，抒发“处江湖远则忧其君”的情愫。声身居巫峡而心系长安就是这组诗的主要内容和线索。\n\n　　全诗以“秋”作为统帅，写暮年飘泊、老病交加、羁旅江湖，面对满目萧瑟的秋景而引起的国家兴衰、身世蹉跎的感慨；写长安盛世的回忆，今昔对比所引起的哀伤；写关注国家的命运、目睹国家残破而不能有所为、只能遥忆京华的忧愁抑郁。\n\n　　全诗于凄清哀怨中，具沉雄博丽的意境。格律精工，词彩华茂，沉郁顿挫，悲壮凄凉意境深宏，读来令人荡气回肠，最典型地表现了杜律的特有风格，有很高的艺术成就。\n\n　　首章对秋而伤羁旅，是全诗的序曲，总写巫山巫峡的秋声秋色。用阴沉萧瑟、动荡不安的景物环境衬托诗人焦虑抑郁、伤国伤时的心情。亮出了“身在夔州，心系长安”的主题。\n\n　　起笔开门见山叙写景物之中点明地点时间。“玉露”即白露，秋天，草木摇落，白露为霜。“巫山巫峡”，诗人所在。二句下字密重，用“凋伤”、“萧森”给意境笼罩着败落景象，气氛阴沉，定下全诗感情基调。\n\n　　接着用对偶句展开“气萧森”的悲壮景象。“江间”承“巫峡”，“塞上”承“巫山”，波浪在地而兼天涌，风云在天而接地阴，可见整个天地之间风云波浪，极言阴晦萧森之状。万里长江滚滚而来，波涛汹涌，天翻地覆，是眼前的实景；“塞上风云”既写景物也寓时事。当时土蕃入侵，边关吃紧，处处是阴暗的战云，虚实兼之。此联景物描绘之中，形象地表达了诗人和时局那种动荡不安、前途未卜的处境和作者胸中翻腾起伏的忧思与郁勃不平之气。把峡谷深秋、个人身世、国家沦丧囊括其中，波澜壮阔，哀感深沉。\n\n　　颈联由继续描写景物转入直接抒情，即由秋天景物触动羁旅情思。与上二句交叉承接，“丛菊”承“塞上”句，“孤舟”承“江间”句。“他日”即往日，去年秋天在云安，今年此日在夔州，均对丛菊，故云“两开”，“丛菊两开他日泪”，表明去年对丛菊掉泪，今年又对丛菊掉泪；两开而字，实乃双关，既指菊开两度，又指泪流两回，见丛菊而流泪，去年如此，今年又如此，足见羁留夔州心情的凄伤。“故园心”，实即思念长安之心。“系”字亦双关词语：孤舟停泊，舟系于岸；心念长安，系于故园。从云安到夔州苦苦挣扎了两年，孤舟不发，见丛菊再开，不禁再度流泪，心总牵挂着故园。诗人《客社》一诗亦云：“南菊再逢人病卧”，《九日》又云：“系舟身万里”，均可参读。此处写得深沉含蓄，耐人寻味。身在夔州，心系故园，为下七首张目。\n\n　　尾联在时序推移中叙写秋声。西风凛冽，傍晚时分天气更是萧瑟寒冷，意味冬日即将来临，人们在加紧赶制寒衣，白帝城高高的城楼上，晚风中传来急促的砧声。白帝城在东，夔州府在西，诗人身在夔州，听到白帝城传来的砧杵之声。砧杵声是妇女制裁棉衣时，槌捣衣服的声音。砧即捣衣之石。此诗末二句，关合全诗，回到景物，时序由白天推到日暮，客子羁旅之情更见艰难，故能结上生下，下面接着写夔州孤城，一气蝉联。钱注杜诗称：“以节则杪秋，以地则高城，以时则薄暮，刀尺苦寒，急砧促别，末句标举兴会，略有五重，所谓嵯峨萧瑟，真不可言。”', poem_tags = '秋天,写景,思念' WHERE poem_title = '秋兴八首·其一' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '蝈蝈张翅膀，群集低飞翔啊。你的子孙多又多，家族正兴旺啊。\n蝈蝈张翅膀，群飞嗡嗡响啊。你的子孙多又多，世代绵延长啊。\n蝈蝈张翅膀，群聚挤满堂啊。你的子孙多又多，和睦好欢畅啊。', poem_notes = '螽（zhōng终）斯：或名斯螽，一种直翅目昆虫，常称为“蝈蝈”。一说“斯”为语词。\n诜（shēn 身）诜：同莘莘，众多貌。\n振振（zhēn真 古音）：茂盛的样子。\n薨（hōng轰）薨：很多虫飞的声音。或曰形容螽斯的齐鸣。\n绳绳（mǐn）：延绵不绝的样子。\n揖揖（yī）：会聚的样子。揖为集之假借。\n蛰（zhé哲）蛰：多，聚集。', poem_appreciation = '全诗三章，每章四句，前两句描写，后两句颂祝。而叠词叠句的叠唱形式。是这首诗艺术表现上最鲜明的特色。如果说，“宜尔子孙”的三致其辞，使诗旨显豁明朗；那么，六组叠词的巧妙运用，则使全篇韵味无穷。《诗经》运用叠词颇为寻常，而《螽斯》的独特魅力在于：六组叠词，锤炼整齐，隔句联用，音韵铿锵，造成了节短韵长的审美效果。同时，诗章结构并列，六词意有差别，又形成了诗意的层递：首章侧重多子兴旺；次章侧重世代昌盛；末章侧重聚集欢乐。由此看来，方氏的评语似可改为：诗虽平说，平中暗含波折；六字炼得甚新，诗意表达圆足。另外，在朱熹《诗集传》中，《螽斯》是比体首篇，故用以释比。其实，通篇围绕“螽斯”着笔，却一语双关，即物即情，物情两忘，浑然一体。因此，“螽斯”不只是比喻性意象，也可以说是《诗经》中不多见的象征性意象。\n\n　　关于诗旨，《毛诗序》云：“《螽斯》，后妃子孙众多也，言若螽斯。不妒忌，则子孙众多也。”点出了诗的主旨，但拖了一个经学的尾巴。朱熹《诗集传》承毛氏之说。还作了“故众妾以螽斯之群处和集而子孙众多比之”的发挥，没有贯彻其“《诗》作诗读”的主张。对此，姚际恒一并认为“附会无理”（《诗经通论》）；方玉润进而指出：诗人措词“仅借螽斯为比，未尝显颂君妃，亦不可泥而求之也。读者细咏诗词，当能得诸言外”（《诗经原始》）。确实不可泥求经传，而应就诗论诗。\n\n　　体会意象，细味诗语，先民颂祝多子多孙的诗旨，显豁而明朗。就意象而言，飞蝗产卵孵化的若虫极多，年生两代或三代，真可谓是宜子的动物。诗篇正以此作比，寄兴于物，即物寓情；“子孙众多，言若螽斯”，即此之谓。就诗语而言，“宜尔子孙”的“宜”，有“多”的含义；而六组叠词，除“薨薨”外，均有形容群聚众多之意。易辞复唱，用墨如泼，正因心愿强烈。“子孙”，是生命的延续，晚年的慰藉，家族的希望。华夏先民多子多福的观念，在尧舜之世已深入民心。《庄子·天地》篇有“华封人三祝”的记载：尧去华地巡视，守疆人对这位“圣人”充满敬意，衷心地祝愿他“寿、富、多男子”。而再三颂祝“宜尔子孙”的《螽斯》，正是先民这一观念诗意地热烈抒发。\n\n　　就诗篇编排而言，前篇《国风·周南·樛木》祝贺新婚幸福，此篇继而祈颂多生贵子，不仅顺理成章，或恐正是编者苦心所系。', poem_tags = '诗经,写鸟,祝福' WHERE poem_title = '螽斯' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '暖暖的雨，暖暖的风，送走了些许冬天的寒意。柳叶长出了，梅花怒放了，春天已经来了。端庄的少妇，也被这春意撩拨起了愁怀。爱侣不在身边，又能和谁把酒论诗呢？少妇的泪水流下脸颊，弄残了搽在她脸上的香粉。\n　　少妇试穿金丝缝成的夹衫，但心思全不在衣服上面。她无情无绪的斜靠在枕头上，把她头上的钗儿压坏了，她也茫然不顾。她孤单的愁思太浓，又怎能做得好梦？惟有在深夜里呵，手弄着灯花，心里想着爱侣。', poem_notes = '初破冻：刚刚解冻。\n柳眼：初生柳叶，细长如眼，故谓“柳眼”。梅腮：梅花瓣儿，似美女香腮，故称“梅腮”。\n花钿（diàn）：用金翠珠宝等制成花朵的首饰。\n乍：起初，刚刚开始。金缕缝：用金钱缝成的农服。\n山枕：即檀枕。因其形如“凹”，故称“山枕”。欹（qī）：靠着。\n钗头凤：即头钗，古代妇女的首饰。因其形如凤，故名。\n夜阑：夜深。灯花：灯蕊燃烧耐结成的花形。', poem_appreciation = '此词《唐宋诸贤绝妙词选》、《草堂诗余别集》、《古今词综》等都题作“离情”，而《草堂诗余别集》还注云：“一作春怀”。由此看来，这些恐均非原题，是后人据词作内容添加的；此外，“春怀”与“离情”确也概括了词作的主要内容。从词作的内容与风格来看，这首词当写于词人婚后不久，夫妻小别，李清照独居时。\n\n　　“暖日晴风初破冻，柳眼梅腮，已觉春心动”。开首三句，词人放眼室外，由春景落笔。但见初春时节，春风化雨，和暖怡人，大地复苏，嫩柳初长，如媚眼微开，艳梅盛开，似香腮红透，到处是一派春日融融的景象。词人前期生活虽然没有大的波折，但以其独具的才情、细腻的情感，以及对外部世界敏锐的感悟、强烈的关注，常有出人意表之想。表现在词作里，就是经常慧心独照，发人所未发，见人所未见。“暖日晴风”似还不足以表达春天到来的特征，而紧接以“柳眼梅腮”（此句历来被称为“易安奇句”），则使到来的春天更直接、更形象。李商隐在《二月二日》一诗中有“花须柳眼各无赖，紫蝶黄蜂俱有情”，苏轼在《水龙吟》词中描绘柳叶情状是“萦损柔肠，困酣娇眼，欲开还闭”。看来女词人受此启发，抓住两个极具特点的事物，写出春天的生机。第三句的“已觉春心动”，从语意上看，是对春天来临总的概括，实亦是自己怀春之情已动之流露。词人游春、赏春，目睹良辰美景，必有所思，这句也暗启后二句词人所抒发的情思：“酒意诗情谁与共？泪融残粉花钿重。”女词人的细腻、敏感的思绪与感悟进一步强化，面对如此大好春光，自然便联想到自己独处深闺，孤栖寂寞，这与往日和丈夫赵明诚一齐把玩金石，烹茗煮酒，赏析诗文的温馨气氛形成强烈反差。一个“谁与共”，道出此刻词人内心的苦涩。紧接着词人用一个细节来进一步形容自己内心的苦涩，泪水流淌，脸庞上的香粉为之消融，心情沉重以致觉得头上戴的花钿也是沉甸甸的。\n\n　　词作的下片，词人以细微的笔触，紧承上片末句，着重刻画自己具体的闺中寂寞生活。“乍试夹衫金缕缝，山枕斜欹，枕损钗头凤。”春暖天晴，春装初试，然而词人却足不出户，去观赏那美好的春景，却斜倚在山枕上，以致把精美的钗头凤给压坏了。“山枕”，即檀枕，因其如“凹”形，故称山枕。词人不出户观赏春景，是因怕良辰美景触引伤感之情，二是表明其心境郁闷，慵懒至极。一个“损”字，也暗示词人慵懒、无精打彩。末二句：“独抱浓愁无好梦，夜阑犹剪灯花弄。”愁本无形，却言“抱”，可见此愁对其来说有多“浓”，多重，更何况是“独抱”，此情更是难堪。“无好梦”，是说现实很寂寞无聊，想在梦中去寻求慰藉，但却始终无法进入梦乡，直至夜阑人静之时，仍剪弄灯花，以排遣愁怀。“犹”字写活了词人百无聊赖的情态。此外，剪弄灯火，古时妇女常藉以卜数夫君之归期。这两句写得极为细致、生动，看似毫不经意，如叙写生活本身，实是几经苦炼，没有生活经历和深厚的艺术功力是无法写就的。清词论家贺裳评这两句为“入神之句”（《皱水轩词筌》）。', poem_tags = '宋词三百首,宋词精选,春天,离别' WHERE poem_title = '蝶恋花·暖雨晴风初破冻' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '风凄凄呀雨凄凄，窗外鸡鸣声声急。风雨之时见到你，怎不心旷又神怡。\n风潇潇呀雨潇潇，窗外鸡鸣声声绕。风雨之时见到你，心病怎会不全消。\n风雨交加昏天地，窗外鸡鸣声不息。风雨之时见到你，心里怎能不欢喜。', poem_notes = '喈（jiē 皆）喈：鸡鸣声。\n云：语助词。胡：何。夷：平，指心中平静。\n胶胶：或作“嘐嘐”，鸡鸣声。\n瘳（chōu 抽）：病愈，此指愁思萦怀的心病消除。\n晦：黑夜。', poem_appreciation = '蕴涵性的顷刻，包前启后。在情境的选择上，诗篇不写未见之前绵绵无尽的相思之苦，也不写相见之后载笑载言的欢聚之乐，而是重章渲染“既见”之时的喜出望外之情。而这一顷刻，正是最富于蕴涵性的顷刻。读者透过这位女子难以形容的望外之喜，既能想见她在“既见”之前，白日的“愿言思伯，甘心首疾”、和夜间的“耿耿不寐，如有隐忧”之情；也能想见在“既见”之后，夫妇间的“既见复关，载笑载言”和“维士与女，伊其相谑”的融融之乐。以少许胜多许，以顷刻蕴过程，这是构思的巧妙。\n\n　　哀景写乐，倍增其情。每章首二句，都以风雨、鸡鸣起兴，这些兼有赋景意味的兴句，重笔描绘出一幅寒冷阴暗、鸡声四起的背景。当此之时，最易勾起离情别绪。赋景之句，也确成写情之语。风雨交加和夜不能寐之无聊；群鸡阵啼和怀人动荡之思；鸡守时而鸣与所期之人盼而不至，可谓契合无间，层层映衬。然而，正在这几乎绝望的凄风苦雨之时，怀人的女子竟意外地“既见”了久别的情郎；骤见之喜，欢欣之情，自可想见。而此时凄风苦雨中的群鸡乱鸣，也似成了煦风春雨时的群鸡欢唱了。这种情景反衬之法，恰如王夫之所说，“以乐景写哀，以哀景写乐，一倍增其哀乐”（《董斋诗话》）。这一手法，确实不唯见诸《小雅·采薇》，而是《诗经》中诗人的常用之法。\n\n　　炼词申意，循序有进。诗篇的结构是单纯的，三章叠咏；诗人的易词写景却是讲究的，它细腻地表现出了人的不同感受。凄凄，是女子对风雨寒凉的感觉；潇潇，则从听觉见出夜雨骤急；如夜的晦冥，又从视觉展现眼前景象。易词写景的这种微妙性，姚际恒《诗经通论》曾有精到的分析：“‘如晦’正写其明也。惟其明，故曰‘如晦’。惟其如晦，‘凄凄’、‘潇潇’时尚晦可知。”诗篇在易词申意的同时，对时态的运动和情态的发展，又有循序渐进的微妙表现。关于时态的渐进，姚氏说，“‘喈喈’为众声和，初鸣声尚微，但觉其众和耳。‘胶胶’，同声高大也。三号以后，天将晓，相续不已矣。”民间尚有“鸡鸣三遍天将明”之说；《风雨》的三章相叠，或许正是以此习惯规律为基础的。随着时态的发展，怀人女子“既见君子”时的心态也渐次有进。“云胡不夷”，以反诘句式，语气热烈，言其心情大悦；“云胡不瘳”，言积思之病，至此而愈，语气至深；末章“云胡不喜”，则喜悦之情，难以掩饰，以至大声疾呼了。天气由夜晦而至晨晦，鸡鸣由声微而至声高，情感的变化则由乍见惊疑而至确信高呼。方玉润说：“此诗人善于言情，又善于即景以抒怀，故为千秋绝调。”（《诗经原始》）实当此之谓。\n\n　　象征意象，一诗多解。《风雨》的诗旨，今人或主“夫妻重逢”，或主“喜见情人”；联系诗境，前说更合情理。然而，汉代经生的“乱世思君”说，却在后世产生了积极的影响。《毛诗序》曰：“《风雨》，思君子也。乱世则思君子不改其度焉。”郑笺申发之曰：“兴者，喻君子虽居乱世，不变改其节度。……鸡不为如晦而止不鸣。”这样，“风雨”便象征乱世，“鸡鸣”便象征君子不改其度，“君子”则由“夫君”之君变成为德高节贞之君子了。这虽属附会，却也有其文本依据。因为，“君子”，在《诗经》时代，可施诸可敬、可爱、可亲之人，含义不定。因此，把赋体的白描意象理解为比体的象征意象，就可能生发“乱世思君”的联想；而把“风雨如晦”的自然之景，理解为险恶的人生处境或动荡的社会环境，也符合审美规律。故后世许多士人君子，常以虽处“风雨如晦”之境，仍要“鸡鸣不已”自励。南朝梁简文帝《幽絷题壁自序》云：“梁正士兰陵萧纲，立身行己，终始如一。风雨如晦，鸡鸣不已。”郭沫若创作于五四运动退潮期的《星空·归来》中也写道：“游子归来了，在这风雨如晦之晨，游子归来了！”从现代接受美学看，这种立足文本的审美再创造是无可非议的；而《毛序》的这一“附会”，也可以说是一种“创造性的误读”。', poem_tags = '诗经,写雨,怀人,民谣' WHERE poem_title = '诗经·国风·郑风' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '最辛苦和最让人怜爱的是天上的明月，它在一月之中只有一夜是像玉环一样的满月，其它时候都像是不完整的玉玦。如果能像月轮那样终身皎洁，我会放弃自身像冰雪般的清凉为你发热。无奈的是人的尘缘容易结束，燕子还是那样，轻盈的踏上帘钩。我在秋日，面对你的坟茔，高歌一曲，然而愁绪丝毫没有削减。我是多么希望能和你像春天里双飞双宿的蝴蝶那样在草丛里嬉戏啊。', poem_notes = '一昔句：昔，同“夕”，见《左传·哀公四年》：“为一昔之期。”玦（jué）玉玦，半环形之玉，借喻不满的月亮。这句是说，一月之中，天上的月亮只有一夜是圆满的，其他的夜晚就都是有亏缺的。 \n不辞句：引用一则典故。荀粲之妻冬天高烧病重，全身发热难受。荀粲为了给妻子降温，脱光衣服站在大雪中，等身体冰冷时回屋给妻子降温。卿，“你”的爱称。《世说新语?惑溺》谓：“荀奉倩（粲）与妇至笃，冬月妇病热，乃出中庭，自取冷还，以身熨之。” \n无那：无奈，无可奈何。 \n软踏句：意思是说燕子依然轻轻地踏在帘钩上，呢喃絮语。 \n唱罢句：唐李贺《秋来》：“秋坟鬼唱鲍家诗，恨血千年土中碧。”这里借用此典表示总是哀悼过了亡灵，但是满怀愁情仍不能消解。 \n春丛句：认取，注视着。取，语助词。此句意思是说，花丛中的蝴蝶可以成双成对，人却生死分离，不能团聚，故愿自己死后同亡妻一起化作双飞双宿的蝴蝶。李商隐《偶题二首》：“春丛定是双栖夜，饮罢莫持红烛行。”', poem_appreciation = '这是一首悼亡词。作者在《沁园春》一词的小序中曾写道：“丁巳重阳前三日，梦亡妇澹妆素服，执手哽咽，语多不复能记，但临别有云：\'衔恨愿为天上月，年年犹得向郎圆。\'此词即先从“天上月“写起。上片三句借月亮为喻，写爱情的欢乐转瞬即逝，恨多乐少。后两句，写假如爱情能象月亮那样皎洁圆满，付出再大的代价都愿意。　“一昔如环，昔昔长如玦“，包蕴了无限的哀伤与怀念，表达了对亡妻的真挚爱恋。下片写伤逝中的悲痛，用燕子在帘间呢喃，反衬人去楼空，未亡人的孤寂。结语化用“双栖蝶“的典故，表达了他与亡妻的爱情生死不渝，抒发了无穷尽的哀悼，把永恒的爱寄托在化蝶的理想中。\n\n　　容若这阕《蝶恋花》凄美，却不减清灵。“辛苦最怜天上月，一夕如环，夕夕都成玦。““环“和“玦“皆为美玉制成的饰物，古人佩在身上。“环“似满月，“玦“似缺月。物理相通，容若以寻常佩物解自然之物，可见其格物，常怀世事难圆的隐恨，此句比之苏子的“人有悲欢离合,月有阴晴圆缺,此事古难全。“深情胜之，豁达减之，各得其所。\n\n　　谓辛苦最怜，算是天上月。一轮端正，悬挂天中。一昔如环，曾有最光辉的时刻，那么圆满皎洁。但一朝别去，永远留下遗憾。如果能够像天上的圆月，长盈不亏，那么，我作为冰雪，将不惜为你融化。这是上片，以月喻人，亦以人喻月，为布景。下片说情，谓十分无奈，尘世因缘竟然那么容易断绝。但是，帘幕间的燕子就不一样，年复一年，辛苦奔波，不是和往常一样，仍旧踏在帘钩上，轻轻地呢喃。鬼唱秋坟，纵使能够另恨血化碧，只是挽歌（鲍诗）唱罢，心上的愁和恨，仍旧不能消解。而今，算是已经认定，死后化作花丛双蝶，生生世世，永不分离。这是下片，用另外两个物象作比，燕子和双栖蝶，以表达愿望。', poem_tags = '婉约,悼亡,爱情' WHERE poem_title = '蝶恋花·辛苦最怜天上月' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '绿野堂建成之后占尽了万物的精华，路人指着宅子说这是裴令公的家啊。\n裴令公的桃李学生遍布天下，哪里用得着再在门前屋后种花呢？', poem_notes = '奉和：做诗词和别人相应和，达到一唱一和的效果。\n令公：即指裴度，令公是唐朝对中书令的尊称，裴度（765年至839年）唐代文学家、政治家，字中立，河东闻喜(今山西闻喜)人。因为拥立文宗有功，进位至中书令。又绿野堂为裴度之宅，所以这里的令公是指裴度。\n绿野堂：唐代裴度的住宅名，故址在今天的河南省洛阳市南。《旧唐书 裴度列传》又于午桥创别墅，花木万株，中起凉台暑馆，名曰绿野堂。\n开：创立，建设。\n物华：万物的精华。\n桃李：代指学生。', poem_tags = '赞美,老师' WHERE poem_title = '奉和令公绿野堂种花' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '白天登山观察报警的烽火台，黄昏时牵马饮水靠近交河边。\n昏暗的风沙传来阵阵刁斗声，如同汉代公主琵琶充满幽怨。\n旷野云雾茫茫万里不见城郭，雨雪纷纷笼罩着无边的沙漠。\n哀鸣的胡雁夜夜从空中飞过，胡人士兵个个眼泪双双滴落。\n听说玉门关已被挡住了归路，战士只有追随将军拼命奔波。\n年年战死的尸骨埋葬于荒野，换来的只是西域葡萄送汉家。', poem_notes = '烽火：古代一种警报。\n饮（yìn）马：给马喂水。傍：顺着。交河：古县名，故城在今新疆吐鲁番西面。\n行人：出征战士。刁斗：古代军中铜制炊具，容量一斗。白天用以煮饭，晚上敲击代替更柝。\n公主琵琶：汉武帝时以江都王刘建女细君嫁乌孙国王昆莫，恐其途中烦闷，故弹琵琶以娱之。\n“闻道”两句：汉武帝曾命李广利攻大宛，欲至贰师城取良马，战不利，广利上书请罢兵回国，武帝大怒，发使至玉门关，曰：“军有敢入，斩之！”两句意谓边战还在进行，只得随着将军去拼命。\n蒲桃：今作“葡萄”。', poem_appreciation = '“从军行”是乐府古题。此诗借汉皇开边，讽玄宗用兵。实写当代之事，由于怕触犯忌讳，所以题目加上一个“古”字。它对当代帝王的好大喜功，穷兵黩武，视人民生命如草芥的行径，加以讽刺，悲多于壮。全诗记叙从军之苦，充满非战思想。万千尸骨埋于荒野，仅换得葡萄归种中原，显然得不偿失。\n\n　　诗开首先写紧张的从军生活。白天爬上山去观望四方有无举烽火的边警；黄昏时候又到交河边上让马饮水（交河在今新疆吐鲁番西面，这里借指边疆上的河流）。三、四句的“公主琵琶”是指汉朝细君公主远嫁乌孙国时所弹的琵琶曲调，当然，这不会是欢乐之声，而只是哀怨之调。一、二句写“白日”、“黄昏”的情况，三、四句接着描绘夜晚的情况：风沙弥漫，一片漆黑，只听得见军营中巡夜的打更声和那如泣如诉的幽怨的琵琶声。景象非常肃穆而凄凉。“行人”，是指出征将士，这样就与下一句的公主出塞之声，引起共鸣了。\n\n　　接着，诗人又着意渲染边陲的环境。军营所在，四顾荒野，无城郭可依，“万里”极言其辽阔；雨雪纷纷，以至与大漠相连，其凄冷酷寒的情状亦可想见。以上六句，写尽了从军生活的艰苦。接下来，似乎应该正面点出“行人”的哀怨之感了。可是诗人却别具机杼，背面傅粉，写出了“胡雁哀鸣夜夜飞，胡儿眼泪双双落”两句。胡雁胡儿都是土生土长的，尚且哀啼落泪，更不必说远戍到此的“行人”了。两个“胡”字，有意重复，“夜夜”、“双双”又有意用叠字，有着烘云托月的艺术力量。\n\n　　面对这样恶劣的环境，没有人不想班师复员。可是办不到。“闻道玉门犹被遮”一句，笔一折，似当头一棒，打断了“行人”思归之念。据《史记·大宛列传》记载，汉武帝太初元年，汉军攻大宛，攻战不利，请求罢兵。汉武帝闻之大怒，派人遮断玉门关，下令：“军有敢入者辄斩之。”这里暗刺当朝皇帝一意孤行，穷兵黩武。随后，诗人又压一句，罢兵不能，“应将性命逐轻车”，只有跟着本部的将领“轻车将军”去与敌军拼命，这一句其份量压倒了上面八句。下面一句，再接再厉。拼命死战的结果无外乎“战骨埋荒外”。诗人用“年年”两字，指出了这种情况的经常性。全诗一步紧一步，由军中平时生活，到战时紧急情况，最后说到死，为的是什么？这十一句的压力，逼出了最后一句的答案：“空见蒲桃入汉家。”\n\n　　“蒲桃”就是葡萄。汉武帝时为了求天马（即阿拉伯马），开通西域，便乱启战端。当时随天马入中国的还有蒲桃和苜蓿的种子，汉武帝把它们种在离宫别馆之旁，弥望皆是。这里“空见蒲桃入汉家”一句，用此典故，讥讽好大喜功的帝王，牺牲了无数人的性命，换到的只有区区的蒲桃而已。言外之意，可见帝王是怎样的草菅人命了。\n\n　　此诗全篇一句紧一句，句句蓄意，步步逼紧，直到最后一句，才画龙点睛，着落主题，显出此诗巨大的讽谕力。诗巧妙地运用音节来表情达意。第一句开头两字“白日”都是入声，具有开场鼓板的意味。三、四两句中的“刁斗”和“琵琶”，运用双声，以增强音节美。中段转入声韵，“双双落”是江阳韵与入声的配合，犹如云锣与鼓板合奏，一广一窄，一放一收，音节最美。中段入声韵后，末段却又选用了张口最大的六麻韵。以五音而论，首段是羽音，中段是角音，末段是商音，音节错落，各极其致。全诗先后用“纷纷”、“夜夜”、“双双”、“年年”等叠字，不但强调了语意，而且叠字叠韵，在音节上生色不少。', poem_tags = '唐诗三百首,乐府,冬天,边塞,生活' WHERE poem_title = '古从军行' AND poem_author = '李颀';
UPDATE edu_poem SET poem_translation = '新长的竹子要比旧竹子高，它们的生长全凭老的枝干扶持。下年又有新长出来的，会长得更高。', poem_notes = '龙孙：竹笋的别称。\n凤池：凤凰池，古时指宰相衙门所在地，这里指周围生长竹子的池塘。', poem_tags = '咏物,竹子,寓人,老师' WHERE poem_title = '新竹' AND poem_author = '郑燮';
UPDATE edu_poem SET poem_translation = '你明知我已经有了丈夫，还偏要送给我一对明珠。\n我心中感激你情意缠绵，把明珠系在我红罗短衫。\n我家的高楼就连着皇家的花园，我丈夫拿着长戟在皇宫里值班。\n虽然知道你是真心朗朗无遮掩，但我已发誓与丈夫生死共患难。\n归还你的双明珠我两眼泪涟涟，遗憾没有遇到你在我未嫁之前。', poem_notes = '节妇：能守住节操的妇女，特别是对丈夫忠贞的妻子。吟：一种诗体的名称。李司空师道：李师道，时任平卢淄青节度使。\n妾：古代妇女对自己的谦称，这里是诗人的自喻。\n缠绵：情意深厚。\n罗：一类丝织品，质薄、手感滑爽而透气。襦：短衣、短袄。\n高楼连苑起：耸立的高楼连接着园林。苑：帝王及贵族游玩和打猎的风景园林。起：矗立着。\n良人：旧时女人对丈夫的称呼。执戟：指守卫宫殿的门户。戟：一种古代的兵器。明光：本汉代宫殿名，这里指皇帝的宫殿。\n用心：动机目的。如日月：光明磊落的意思。\n事：服事、侍奉。拟：打算。\n何不：一作“恨不”。', poem_appreciation = '《节妇吟寄东平李司空师道》载于《全唐诗》卷三八二。下面是国学大师、全国首批博士生导师钱仲联先生与苏州大学文学院徐永端教授对此诗的赏析。\n\n　　此诗通篇运用比兴手法，委婉地表明自己的态度。单看表面完全是一首抒发男女情事之言情诗，骨子里却是一首政治抒情诗，题为《节妇吟》，即用以明志。\n\n　　此诗似从汉乐府《陌上桑》、《羽林郎》脱胎而来，但较之前者更委婉含蓄。\n\n　　首二句说：这位既明知我是有夫之妇，还要对我用情，此君非守礼法之士甚明，语气中带微辞，含有谴责之意。这里的“君”，喻指藩镇李师道，“妾”是自比，十字突然而来，直接指出师道的别有用心。\n\n　　接下去诗句一转，说道：我虽知君不守礼法，然而又为你情意所感，忍不住亲自把君所赠之明珠系在红罗襦上。表面看，是感师道的知己；如果深一层看，话中有文章。\n\n　　继而又一转，说自己家的富贵气象，良人是执戟明光殿的卫士，身属中央。古典诗词，传统的以夫妇比喻君臣，这两句意谓自己是唐王朝的士大夫。\n\n　　紧接两句作波澜开合，感情上很矛盾，思想斗争激烈：前一句感谢对方，安慰对方；后一句斩钉截铁地申明己志，“我与丈夫誓同生死”。\n\n　　最后以深情语作结，一边流泪，一边还珠，言词委婉，而意志坚决。\n\n　　诗中所说“双明珠”是李师道用来拉拢、引诱作者为其助势的代价，也就是常人求之不得的声名地位、富贵荣华一类的东西。作者慎重考虑后委婉的拒绝了对方的要求，做到了“富贵不能淫”，像一个节妇守住了贞操一样的守住了自己的严正立场。但当时李师道是个炙手可热的藩镇高官，作者并不想得罪他、让他难堪，因此写了这首非常巧妙的双层面的诗去回拒他。\n\n　　此诗富有民歌风味，它的一些描写，在心理刻画中显示，写得如此细腻，熨贴，入情入理，短幅中有无限曲折，真所谓“一波三折”。\n\n　　此诗词浅意深，言在意外，含蓄地表达了诗人的政治立场。全诗情理真挚，心理描写细致入微，委婉曲折而动人。除了它所表现的是君子坦荡胸怀这一因素外，其在艺术上的高妙也是促使它成为名作的重要原因。据说由于这首诗情词恳切，连李师道本人也深受感动，不再勉强。', poem_tags = '乐府,女子,坚贞,分手' WHERE poem_title = '节妇吟·寄东平李司空师道' AND poem_author = '张籍';
UPDATE edu_poem SET poem_translation = '细雨斜风天气微寒。淡淡的烟雾，滩边稀疏的柳树似乎在向刚放晴后的沙滩献媚。眼前入淮清洛，亦仿佛渐流渐见广远无际。\n乳色鲜白的好茶伴着新鲜的野菜。人间真正有味道的还是清淡的欢愉。', poem_notes = '浣溪沙：本唐教坊曲名，后用作词牌。一作《浣溪纱》，又名《浣沙溪》、《小庭花》等。双调四十二字，平韵。南唐李煜有仄韵之作。此调音节明快，句式整齐，易于上口。为婉约、豪放两派词人所常用。\n刘倩叔：名士彦，泗州人，生平不详。\n南山：在泗州东南，景色清旷，宋米芾称为淮北第一山。\n媚：美好。此处是使动用法。滩：十里滩，在南山附近。\n洛：洛河，源出安徽定远西北，北至怀远入淮河。\n漫漫：水势浩大。\n“雪沫”句：谓午间喝茶。雪沫乳花：形容煎茶时上浮的白泡。午盏：午茶。\n蓼（liǎo）茸：蓼菜嫩芽。\n春盘：旧俗，立春时用蔬菜水果、糕饼等装盘馈赠亲友。', poem_appreciation = '词的上片写早春景象，下片写作者与同游者游山时以清茶野餐的风味。作品充满春天的气息，洋溢着生命的活力，反映了作者对现实生活的热爱和健胜进取的精神。\n\n　　词的上片写沿途景观。第一句写清晨，风斜雨细，瑟瑟寒侵，这残冬腊月是很难耐的，可是东坡却只以“作晓寒”三字出之，表现了一种不大在乎的态度。\n\n　　第二句写向午的景物：雨脚渐收，烟云淡荡，河滩疏柳，尽沐晴晖。一个“媚”字，极富动感地传出作者喜悦的心声。作者从曳于淡云晴日中的疏柳，觉察到萌发中的春潮。于残冬岁暮之中把握住物象的新机，这正是东坡逸怀浩气的表现，是他精神境界上度越恒流之处。“入淮”句寄兴遥深，一结甚远。句中的“清洛”，即“洛涧”，发源于合肥，北流至怀远合于淮水，地距泗州（宋治临淮）不近，非目力能及。词中提到清洛，是以虚摹的笔法，眼前的淮水联想到上游的清碧的洛涧，当它汇入浊淮以后，就变得浑浑沌沌一片浩茫了。\n\n　　下片转写作者游览时的清茶野餐及欢快心情。一起两句，作者抓住了两件有特征性的事物来描写：乳白色的香茶一盏和翡翠般的春蔬一盘。两相映托，便有浓郁的节日气氛和诱人的力量。“雪沫”乳花，状煎茶时上浮的白泡。以雪、乳形容茶色之白，既是比喻，又是夸张，形象鲜明。午盏，指午茶。此句可说是对宋人茶道的形象描绘。“蓼茸蒿笋”，即蓼芽与蒿茎，这是立春的应时节物。旧俗立春时馈送亲友以鲜嫩春菜和水果、饼铒等，称“春盘”。\n\n　　此二句绘声绘色、活灵活现地写出了茶叶和鲜菜的鲜美色泽，使读者从中体味到词人品茗尝鲜时的喜悦和畅适。这种将生活形象铸成艺术形象的手法，显示出词人高雅的审美意趣和旷达的人生态度。“人间有味是清欢”，这是一个具有哲理性的命题，用词的结尾，却自然浑成，有照彻全篇之妙趣，为全篇增添了欢乐情调和诗味、理趣。\n\n　　这首词，色彩清丽而境界开阔的生动画面中，寄寓着作者清旷、闲雅的审美趣味和生活态度，给人以美的享受和无尽的遐思。', poem_tags = '婉约,纪游,写景' WHERE poem_title = '浣溪沙·细雨斜风作晓寒' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '登上高楼万里乡愁油然而生，眼中水草杨柳就像江南汀洲。\n溪云突起红日落在寺阁之外，山雨未到狂风已吹满咸阳楼。\n黄昏杂草丛生的园中鸟照飞，深秋枯叶满枝的树上蝉啾啾。\n来往的过客不要问从前的事，只有渭水一如既往地向东流。', poem_notes = '咸阳：秦都城，唐代咸阳城与新都长安隔河相望。今属陕西。\n蒹葭：芦苇一类的水草。汀洲：水边平坦的沙洲。\n“溪云”句：此句下作者自注：“南近磻溪，西对慈福寺阁。”\n“鸟下”二句：夕照下，飞鸟下落至长着绿草的秦苑中，秋蝉也在挂着黄叶的汉宫中鸣叫着。\n当年：一作“前朝”。\n“故国东来渭水流”：一作“渭水寒声昼夜流”，“声”一作“光”。', poem_appreciation = '诗人首联扣题，抒情写景：“高楼”，指咸阳城西楼，咸阳旧城在西安市西北，汉时称长安，秦汉两朝在此建都。隋朝时向东南移二十城建新城，即唐京师长安。咸阳旧城隔渭水与长安相望；“蒹葭”，即芦荻（蒹，荻；葭，芦），暗用《诗经·国风·秦风·蒹葭》的诗意，表思念心绪；“汀洲”，水边之地为汀、水中之地为洲，这里指代诗人在江南的故乡。诗人一登上咸阳高高的城楼，向南望去，远处烟笼蒹葭，雾罩杨柳，很像长江中的汀洲。诗人游宦长安，远离家乡，一旦登临，思乡之情涌上心头。蒹葭杨柳，居然略类江南。万里之愁，正以乡思为始：“一上”表明触发诗人情感时间之短瞬，“万里”则极言愁思空间之迢遥广大，一个“愁”字，奠定了全诗的基调。笔触低沉，景致凄迷，触景生情，苍凉伤感的情怀落笔即出，意远而势雄。\n\n　　颔联写晚眺远景，寓意深远：“溪”指磻溪，“阁”指慈福寺，诗人有自注：“南近磻溪，西对慈福寺阁。” 诗人傍晚登上城楼，只见磻溪罩云，暮色苍茫，一轮红日渐薄远山，夕阳与慈福寺阁姿影相叠，仿佛靠近寺阁而落。就在这夕照图初展丽景之际，蓦然凉风突起，咸阳西楼顿时沐浴在凄风之中，一场山雨眼看就要到了。这是对自然景物的临摹，也是对唐王朝日薄西山，危机四伏的没落局势的形象化勾画，它淋漓尽致而又形象入神地传出了诗人“万里愁”的真实原因。云起日沉，雨来风满，动感分明；“风为雨头”，含蕴深刻。此联常用来比喻重大事件发生前的紧张气氛，是千古传咏的名句。\n\n　　颈联写晚眺近景，虚实结合：山雨将到，鸟雀仓惶逃入遍地绿芜、秋蝉悲鸣躲在黄叶高林，这些是诗人眼前的实景。但早已荡然无存的“秦苑”“汉宫”又给人无尽的联想——禁苑深宫，而今绿芜遍地，黄叶满林；唯有鸟雀和虫鸣，不识兴亡，依然如故。历史的演进，王朝的更替，世事的变化沧桑，把诗人的愁怨从“万里”推向“千古”，以实景叠合虚景，吊古之情油然而生。\n\n　　尾联作结，融情于景：“行人”，过客。泛指古往今来征人游子，也包括作者在内；“故国”，指秦汉故都咸阳；“东来”，指诗人（不是渭水）自东边而来。诗人最后感慨道：羁旅过客还是不要索问当年秦汉兴亡之事吧！我这次来故国咸阳，连遗址都寻不着，只有渭水还像昔日一样长流不止而已。“莫问”二字，并非劝诫之辞 ，实乃令人思索之语，它让读者从悲凉颓败的自然景物中钩沉历史的教训；一个“流”字，则暗示出颓势难救的痛惜之情。渭水无语东流的景象中，融铸着诗人相思的忧愁和感古伤今的悲凉，委婉含蓄，令人伤感。\n\n　　全诗情景交融，景中寓情，诗人通过对景物的描写，赋予抽象的感情以形体，在呈现自然之景的同时又体现丰富的生活经验，以及对历史和现实的深刻思考。景别致而凄美，情愁苦而悲怆，意蕴藉而苍凉，境雄阔而高远，神完气足，堪称晚唐登临之作的翘楚。', poem_tags = '写景,吊古伤今' WHERE poem_title = '咸阳城东楼 / 咸阳城西楼晚眺' AND poem_author = '许浑';
UPDATE edu_poem SET poem_translation = '东风吹拂，微微春雨洒过青山；登高远望，长安城中房舍叠嶂，草色闲闲。\n故园就在梦中，可是何时才能归还；冬去春来，江上舟来舟往，又有几人得以还家。\n长安城外，河流原野，纵横交错，一直延伸到天边浮云之外，长安城中，宫阙参差错落，笼罩在一片残阳之中。\n又有谁理解我这位读书人，生逢乱世，孤身一人，满头白发，形容憔悴，漂泊流荡在荒远的秦关。', poem_notes = '“东风”句：语从陶渊明《读山海经》“微雨从东来，好风与之俱”化出。\n草色：一作“柳色”。\n春生：一作“春归”，一作“春来”。\n川原：即郊外的河流原野，这里指家乡。\n逢世难：一作“多失意”，意即遭逢乱世。\n秦关：秦地关中，即长安所在地。', poem_tags = '登高,写景,思乡' WHERE poem_title = '长安春望' AND poem_author = '卢纶';
UPDATE edu_poem SET poem_translation = '其一\n像吴国美女越国娇娘楚王妃嫔一样美丽的采莲女们，竞相划动采莲船，湖水打湿了衣衫。来的时候莲花把她们迎进河口，采完之后明月把她们送回江边。\n\n其二\n采莲女的罗裙绿得像荷叶一样，出水的荷花正朝着采莲女的脸庞开放。碧罗裙芙蓉面混杂在荷花池中难以辨认，听到歌声才发觉池中有人来采莲。', poem_notes = '采莲曲：古曲名。内容多描写江南一带水国风光，采莲女劳动生活情态。\n“吴姬”句：古时吴、越、楚三国（今长江中下游及浙江北部）盛尚采莲之戏，故此句谓采莲女皆美丽动人，如吴越国色，似楚王妃嫔。\n浦（pǔ）口：江湖会合处。浦，水滨。\n罗裙：用细软而有疏孔的丝织品制成的裙子。一色裁：像是用同一颜色的衣料剪裁的。\n芙蓉：指荷花。\n看不见：指分不清哪是芙蓉的绿叶红花，哪是少女的绿裙红颜。', poem_appreciation = '第一首诗写水乡姑娘的采莲活动。\n\n　　吴姬、越艳、楚王妃三个词连用，铺写出莲娃们争芳斗妍，美色纷呈的景象。第二句正写采莲活动，从“争弄莲舟”来看，似乎是一种采莲的竞赛游戏。唐汝询说：“采莲之戏盛于三国，故并举之。”（《唐诗解》）因为要划船竟采，顾不得水湿衣衫。采莲姑娘那好胜、活泼、开朗的情态就通过“水湿衣”这个细节表现出来。\n\n　　她们划着采莲船来到一个花的世界，而最后两句点出她们直到月上江头才回去。诗人不急着写回程，而是插叙采莲女来的情境，她们来时被花儿所迎接，可见花儿是很乐意为她们所造访，而隐着一层写她们对采莲这一活动是非常喜爱，近乎于享受。当她们回去时，那月儿实际上也就是花儿，便依依不舍地送她们了。“花迎人”和“月送归”运用了拟人手法，把整个采莲活动的现场给写活了，极富诗意，写荷花迎接采莲女和月亮送别采莲女，实际上还是为了表现采莲女之可爱。\n\n　　这首诗通过几个动词淋漓尽致地将采莲女应有的性格——活泼开朗表现出来，并以花、月、舟、水来衬托女子的容貌，可以说这就是一部小电影，对刻画人物形象非常生动形象而别有韵味。\n\n　　第二首诗可以说是一幅《采莲图》，画面的中心自然是采莲少女们。但作者却自始至终不让她们在这幅活动的画面上明显地出现，而是让她们夹杂在田田荷叶、艳艳荷花丛中，若隐若现，若有若无，使采莲少女与美丽的大自然融为一体，使全诗别具一种引人遐想的优美意境。这样的艺术构思，是独具匠心的。\n\n　　一开头就巧妙地把采莲少女和周围的自然环境组成一个和谐统一的整体──“荷叶罗裙一色裁，芙蓉向脸两边开。”说女子的罗裙绿得象荷叶一样，不过是个普通的比喻；而这里写的是采莲少女，置身莲池，说荷叶与罗裙一色，那便是“本地风光”，是“赋”而不是“比”了，显得生动喜人，兼有素朴和美艳的风致。次句的芙蓉即荷花。说少女的脸庞红润艳丽如同出水的荷花，这样的比喻也不算新鲜。但“芙蓉向脸两边开”却又不单是比喻，而是描绘出一幅美丽的图景：采莲少女的脸庞正掩映在盛开的荷花中间，看上去好象鲜艳的荷花正朝着少女的脸庞开放。把这两句联成一体，读者仿佛看到，在那一片绿荷红莲丛中，采莲少女的绿罗裙已经融入田田荷叶之中，几乎分不清孰为荷叶，孰为罗裙；而少女的脸庞则与鲜艳的荷花相互照映，人花难辨。让人感到，这些采莲女子简直就是美丽的大自然的一部分，或者说竟是荷花的精灵。这描写既具有真切的生活实感，又带有浓郁的童话色彩。\n\n　　第三句“乱入池中看不见”，紧承前两句而来。乱入，即杂入、混入之意。荷叶罗裙，芙蓉人面，本就恍若一体，难以分辨，只有在定晴细察时才勉强可辨；所以稍一错神，采莲少女又与绿荷红莲浑然为一，忽然不见踪影了。这一句所写的正是伫立凝望者在刹那间所产生的一种人花莫辨，是耶非耶的感觉，一种变幻莫测的惊奇与怅惘。这是通常所说“看花了眼”时常有的情形。然而，正当踟蹰怅惘、望而不见之际，莲塘中歌声四起，忽又恍然大悟，“看不见”的采莲女子仍在这田田荷叶、艳艳荷花之中。“始觉有人来”要和“闻歌”联在一起体味。本已“不见”，忽而“闻歌”，方知“有人”；但人却又仍然掩映于荷叶荷花之中，故虽闻歌而不见她们的身姿面影。这真是所谓“菱歌唱不彻，知在此塘中”（崔国辅《小长干曲》）了。这一描写，更增加了画面的生动意趣和诗境的含蕴，令人宛见十亩莲塘，荷花盛开，菱歌四起的情景，和观望者闻歌神驰、伫立凝望的情状，而采莲少女们充满青春活力的欢乐情绪也洋溢在这闻歌而不见人的荷塘之中。直到最后，作者仍不让画的主角明显出现在画面上，那目的，除了把她们作为美丽的大自然的化身之外，还因为这样描写，才能留下悠然不尽的情味。', poem_tags = '荷花,女子,组诗' WHERE poem_title = '采莲曲二首' AND poem_author = '王昌龄';
UPDATE edu_poem SET poem_translation = '早春的清新景色，正是诗人的最爱。绿柳枝头嫩叶初萌，鹅黄之色尚未均匀。\n若是到了京城花开之际，那将满城便是赏花之人。', poem_notes = '城：指唐代京城长安。\n诗家：诗人的统称，并不仅指作者自己。清景：清秀美丽的景色。清：一作“新”。新春：即早春。\n才黄：刚刚露出嫩黄的柳眼。匀：均匀，匀称。\n上林：上林苑，故址在今陕西西安市西，建于秦代，汉武帝时加以扩充，为汉宫苑。诗中用来代指唐朝京城长安。锦：五色织成的绸绫。\n俱：全，都。看花人：此处双关进士及第者。唐时举进士及第者有在长安城中看花的风俗。', poem_tags = '春天,写景,哲理' WHERE poem_title = '城东早春' AND poem_author = '杨巨源';
UPDATE edu_poem SET poem_translation = '广大辽阔的无边无际的旷野啊，极目远望看不到人影。河水弯曲得像带子一般，远处无数的山峰交错在一起。一片阴暗凄凉的景象：寒风悲啸，日色昏黄，飞蓬折断，野草枯萎，寒气凛冽犹如降霜的冬晨。鸟儿飞过也不肯落下，离群的野兽奔窜而过。亭长告诉我说：“这儿就是古代的战场，曾经全军覆没。每逢阴天就会听到有鬼哭的声音。真令人伤心啊！这是秦朝、汉朝，还是近代的事情呢？\n　　我听说战国时期，齐魏征集壮丁服役，楚韩募集兵员备战。士兵们奔走万里边疆，年复一年暴露在外，早晨寻找沙漠中的水草放牧，夜晚穿涉结冰的河流。地远天长，不知道哪里是归家的道路。性命寄托于刀枪之间，苦闷的心情向谁倾诉？自从秦汉以来，四方边境上战争频繁，中原地区的损耗破坏，也无时不有。古时称说，外夷中夏，都不和帝王的军队为敌；后来不再宣扬礼乐教化，武将们就使用奇兵诡计。奇兵不符合仁义道德，王道被认为迂腐不切实际，谁也不去实行。\n　　唉哟哟！我想像北风摇撼着沙漠，胡兵乘机来袭。主将骄傲轻敌，敌兵已到营门才仓卒接战。原野上竖起各种战旗，河谷地奔驰着全副武装的士兵。严峻的军法使人心惊胆战，当官的威权重大，士兵的性命微贱。锋利的箭镞穿透骨头，飞扬的沙粒直扑人面。敌我两军激烈搏斗，山川也被震得头昏眼花。声势之大，足以使江河分裂，雷电奔掣。\n　　何况正值极冬，空气凝结，天地闭塞，寒气凛冽的翰海边上，积雪陷没小腿，坚冰冻住胡须。凶猛的鸷鸟躲在巢里休息，惯战的军马也徘徊不前。绵衣毫无暖气，人冻得手指掉落，肌肤开裂。在这苦寒之际，老天假借强大的胡兵之手，凭仗寒冬肃杀之气，来斩伐屠戮我们的士兵，半途中截取军用物资，拦腰冲断士兵队伍。都尉刚刚投降，将军又复战死。尸体僵仆在大港沿岸，鲜血淌满了长城下的窟穴。无论高贵或是卑贱，同样成为枯骨。说不完的凄惨哟！鼓声微弱啊，战士已经精疲力竭；箭已射尽啊，弓弦也断绝。白刃相交肉搏啊，宝刀已折断；两军迫近啊，以生死相决。投降吧？终身将沦于异族；战斗吧？尸骨将暴露于沙砾！鸟儿无声啊群山沉寂，漫漫长夜啊悲风淅淅，阴魂凝结啊天色昏暗，鬼神聚集啊阴云厚积。日光惨淡啊映照着短草，月色凄苦啊笼罩着白霜。人间还有像这样令人伤心惨目的景况吗？\n　　我听说过，李牧统率赵国的士兵，大破林胡的入侵，开辟疆土千里，匈奴望风远逃。而汉朝倾全国之力和匈奴作战，反而民穷财尽，国力削弱。关键是任人得当，哪在于兵多呢！周朝驱逐猃狁，一直追到太原，在北方筑城防御，尔后全军凯旋回京，在宗庙举行祭祀和饮宴，记功授爵，大家和睦愉快而又安适。君臣之间，端庄和蔼，恭敬有礼。而秦朝修筑长城，直到海边都建起关塞，残害了无数的人民，鲜血把万里大地染成了赤黑；汉朝出兵攻击匈奴，虽然占领了阴山，但阵亡将士骸骨遍野，互相枕藉，实在是得不偿失。苍天所生众多的人民，谁没有父母？从小拉扯带领，抱着背着，唯恐他们夭折。谁没有亲如手足的兄弟？谁没有相敬如宾友的妻子？他们活着受过什么恩惠？又犯了什么罪过而遭杀害？他们的生死存亡，家中无从知道；即使听到有人传讯，也是疑信参半。整日忧愁郁闷，夜间音容入梦。不得已只好陈列祭品，酹酒祭奠，望远痛哭。天地为之忧愁，草木也含悲伤。这样不明不白的吊祭，不能为死者在天之灵所感知，他们的精魂也无所归依。何况战争之后，一定会出现灾荒，人民难免流离失所。唉唉！这是时势造成，还是命运招致呢？从古以来就是如此！怎样才能避免战争呢？惟有宣扬教化，施行仁义，才能使四方民族为天子守卫疆土啊。', poem_notes = '[1]浩浩：辽阔的样子。垠（yín银）：边际。\n[2]夐（xiòng）：远。\n[3]纠纷：重叠交错的样子。\n[4]黯：昏黑。\n[5]曛：赤黄色，形容日色昏暗。\n[6]蓬：草名，即蓬蒿。秋枯根拔，随风飘转。\n[7]挺：通“铤”（tǐng），疾走的样子。\n[8]亭长：秦汉时每十里为一亭，设亭长一人，掌管治安、诉讼等事。唐代在尚书省各部衙门设置亭长，负责省门开关和通报传达事务，是流外（不入九品职级）吏职。此借指地方小吏。\n[9]三军：周制：天子置六军，诸侯大国可置三军，每军一万二千五百人。此处泛指军队。\n[10]齐魏、荆韩：战国七雄中的四个国家。荆，即楚国。这里泛指战国时代。召募：以钱物招募兵员。徭役和召募，是封建时代的义务兵和雇佣兵。\n[11]腷（bì必）臆：心情苦闷。愬，即“诉”。\n[12]四夷：四方边境的少数民族。夷，古时对异族的贬称。\n[13]耗斁（dù妒）：损耗败坏。\n[14]戎：西方少数民族。此泛指少数民族。夏：华夏，汉族。\n[15]王师：帝王的军队。古称帝王之师是应天顺人、吊民伐罪的仁义之师。\n[16]文教：指礼乐法度，文章教化。\n[17]用奇：使用阴谋诡计。\n[18]奇兵：乘敌不备进行突然袭击的部队。\n[19]王道：指礼乐仁义等治理天下的准则。迂阔：迂腐空疏。\n[20]期门：军营的大门。\n[21]旌旗：旗帜的统称。旌，用旄牛尾和彩色鸟羽作竿饰的旗。\n[22]组练：即“组甲被练”，战士的衣甲服装。此代指战士。\n[23]析：分离，劈开。原作“折”，据《唐文粹》及《文集》改。\n[24]穷阴：犹穷冬，极寒之时。\n[25]海隅：西北极远之地。海，瀚海，在蒙古高原东北；一说指今内蒙古自治区之呼伦贝尔湖。\n[26]缯纩（zēng增kuàng旷）：缯，丝织品的总称。纩，丝绵。古代尚无棉花，絮衣都用丝棉。\n[27]凭陵：凭借，倚仗。\n[28]辎（zī资）重：军用物资的总称。\n[29]都尉：官名，此指职位低于将军的武官。\n[30]踣（bó博）：僵仆。\n[31]胜（shēng生）：尽。\n[32]蹙（cù促）：迫近，接近。\n[33]幂（mì密）幂：深浓阴暗。\n[34]牧：李牧，战国末赵国良将，守雁门（今山西北部），大破匈奴的入侵，击败东胡，降服林胡（均为匈奴所属的部族）。其后十余年，匈奴不敢靠近赵国边境。见《史记·廉颇蔺相如列传》。\n[35]殚（dān丹）：尽。痡（pū铺）：劳倦，病苦。汉武帝时，多次大举征伐匈奴及大宛、西羌、南越，以至“赋税既竭，犹不足以奉战士”、“天下虚耗”，甚至“人复相食”。见《史记·平准书》、《汉书·食货志》。\n[36]猃狁（xiǎn险yǔn允）：也作“猃狁”、“荤粥”、“獯鬻”、“薰育”、“荤允”等，古代北方的少数民族，即匈奴的前身。周宣王时，狁南侵，宣王命尹吉甫统军抗击，逐至太原（今宁夏固原县北），不再穷追。二句出自《诗经·小雅·六月》：“薄伐狁，至于太原”。\n[37]城：筑城。朔方：北方。一说即今宁夏灵武县一带。句出《诗经·小雅·出车》：“天子命我，城彼朔方。”\n[38]饮至：古代盟会、征伐归来后，告祭于宗庙，举行宴饮，称为“饮至”。策勋，把功勋记载在简策上。句出《左传》桓公二年：“凡公行，告于宗庙；反行，饮至，舍爵策勋焉，礼也。”\n[39]穆穆：端庄盛美，恭敬谨肃的样子，多用以形容天子的仪表，如《礼记·曲礼下》：“天子穆穆”。棣（dì弟）棣，文雅安和的样子。\n[40]荼（tú涂）毒：残害。\n[41]殷（yān烟）：赤黑色。《左传》成公二年杜注：“血色久则殷。”\n[42]阴山：在今内蒙古中部，西起河套，东接内兴安岭，原为匈奴南部屏障，匈奴常由此以侵汉。汉武帝时，为卫青、霍去病统军夺取，汉军损失亦惨重。\n[43]苍苍：指天。蒸，通“烝”，众，多。\n[44]悁（yuān冤）悁：忧愁郁闷的样子。\n[45]寤寐：梦寐。\n[46]布奠倾觞：把酒倒在地上以祭奠死者。布，陈列。奠，设酒食以祭祀。\n[47]不至：不能达于死者。精魂：精气灵魂。古时认为人死后，其精气灵魂能够离开身体而存在。\n[48]凶年：荒年。语出《老子道德经》第三十章：“大军之后，必有凶年”。大举兴兵造成大量农业劳动力的征调伤亡，再加上双方军队的蹂躏掠夺以及军费的负担，必然影响农业生产的种植和收成。故此处不仅指自然灾荒。\n[49]守在四夷：语出《左传》昭公二十三年：“古者天子，守在四夷。”', poem_tags = '古文观止,战争,吊古伤今,忧国忧民' WHERE poem_title = '吊古战场文' AND poem_author = '李华';
UPDATE edu_poem SET poem_tags = '爱情,思念' WHERE poem_title = '诉衷情·夜来沉醉卸妆迟' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '数声杜鹃的鸣啼，又报告烂漫春光将要凋谢。惜春人更想将那残花折。怎奈何雨虽轻柔风却猛烈，正赶上这梅子发青的暮春时节。看那永丰坊的柳树，在无人的园中整日撒飞絮如飘雪。\n切莫把琵琶的细弦拨动，我深深的哀怨细弦也难倾泻。天如有情不会老，真情永不会灭绝。多情的心就像那双丝网，中间有千千万万个结。中夜已经过去了，东方未白，尚留一弯残月。', poem_notes = '千秋岁：词牌名。\n鶗鴂（tíjué）：即子规、杜鹃。《离骚》：“恐鶗鴂之未先鸣兮，使夫百草为之不劳。”\n芳菲：花草，亦指春时光景。\n永丰柳：唐时洛阳永丰坊西南角荒园中有垂柳一株被冷落，白居易赋《杨柳枝词》“永丰东角荒园里，尽日无人属阿谁。“以喻家妓小蛮。后传入乐府，因以“永丰柳”泛指园柳，喻孤寂无靠的女子。\n花飞雪：指柳絮。\n把：持，握。幺弦：琵琶的第四弦，各弦中最细，故称。亦泛指短弦、小弦。\n凝残月：一作“孤灯灭”。', poem_appreciation = '这首词是写爱情横遭阻抑的幽怨情怀和坚决不移的信念，声调激越，极尽曲折幽怨之能事。\n\n　　作者张先以“不如桃杏，犹解嫁东风”及“云破月来花弄影”诸名句蜚声北宋词坛。在现存一百八十二首词中，内容涉及爱情、友谊、风土等多方面。尤其擅长写悲欢离合之情，能曲尽其妙。此词就是其中之一。词调“千秋岁”声情激越，宜于抒发抑郁的情怀。秦观的一首（水边沙外）也是如此。\n\n　　此篇上片沉痛地回顾爱情遭到破坏，但无一语明说。完全运用描写景物来烘托，暗示，让读者自己去寻绎、领会。一起就把鸣声悲切的鶗鴂提出来，说它向人们报道美好的春光又过去了。语源于《离骚》“恐鶗鴂之先鸣兮，使夫百草为之不芳。”此与辛弃疾的“绿树听鶗鴂，......啼到春归无寻处，苦恨芳菲都歇”（《贺新郎·别茂嘉十二弟》）词句很相似，而子野写得更为简练。从“又”字看，他们间融融泄泄的爱情已不止一年了。可是由于遭到阻力，正和春天一样，来也匆匆，去出匆匆。春去，人们都会惋惜，但惋惜的想法做法却各有不同。有人“惜春常怕花开早”（辛弃疾《摸鱼儿》），子野笔下这位多情者却是“惜春更把残红折”。所谓残红，可发说是受破坏而又坚持的爱情。一个折字更能表达出对于经过风雨摧残的爱情多么珍惜。紧接着写出“雨轻风色暴，梅子青时节”。这是上片最为重要而又精彩的两句。表面是写时令，写景物，但细心的读者会理解语意的双关，说的是爱情遭受破坏。“梅子黄时雨”（贺铸《青玉案》），这是正常的。不料梅子青时，便被无情的风暴突袭。青春初恋经过这场灾难，美好的春光便双在鶗鴂的声中归去。白居易有咏杨柳句说：“永丰西角荒园里，尽日无人属阿诠？”被冷落的受害者这时也就和永丰坊的柳树一样，爱情却如柳絮，“似花还似非花，也无人惜，从教坠”（苏轼《水龙吟》）。\n\n　　一首词的上下片间，意脉是相通的。此词如仅从上片看，未尝不可理解为“刻意伤春复伤别”（李商隐《杜司勋》）。读到下片则全词写的什么就很清楚了。换头说：“莫把幺弦拨，怨极弦能说。”这两句来得很突然。在换头处发起新意，向来认为只有高手能之。幺弦，琵琶第四弦。弦幺怨极，就必然发出倾诉不平的最强音。在这“铁骑突出刀枪鸣”（白居易《琵琶行》）的气势下，受害者接着表示其反抗的决心，“天不老，情难绝”。化用李贺“天若有情天亦老”而含意却不完全一样。这里肯定地说天是不会老的，那么爱情也就永无断绝的时候。这比作者常说的“无物似情浓”（《一丛花》），“人生无物比多情，江水不深山不重”（《木兰花》）等等，更为深刻有力。“心似双丝网，中有千千结。”“丝”谐“思”。在这个情网里，他们是通过千万个结，把彼此牢牢实实地系住，谁想破坏都是徒劳的。这是全词表达思想感情的高峰，也就是《文赋》所谓“立片言而居要，乃一篇之警策”。情思未了，不觉春宵已经过去，这时东窗未白，残月犹明。如此作结，可谓恰到好处。\n\n　　上阕用景物烘托、暗示爱情被破坏，无一语明说内情，要读者细心品味。“数声，叉报芳菲歇”，首二句化用《离骚》中语，由的悲呜声中，宣布繁花簇锦的春天已经过去，一个“又”字，说明美好时光逝去已非年半载。来时匆匆，去时匆匆，故是春之常志，惜春之情，因人而异，“惜春更选残红折，雨轻风色暴，梅子青时节”，“选残红”说明爱情虽遭摧残，但自己仍然珍惜，接下二句，既写时令，又写爱情被破坏之事，一语双关，极为精彩。遭受如此打击，何人能堪，末二句化白居易之事，诉出心中苦楚，别自凄惋动人。\n\n　　下阕将此中真意挑明，但是换头二句来得极为突兀，幺弦能诉极其强烈的怨恨，而说“莫把幺弦拨”，可知此情是多么凄苦，语虽奇，意则与上文一脉相承。“天不老，情难绝”，爱情虽被摧残，只要天不老去，情是难以断绝的，悲苦中作刚强语，钟情之心，耿耿不泯。“心似双丝网，中有千千结”，两情相悦，彼此知心，虽遭破坏，终是徒劳。行文至此，情感的抒发也到了高潮。但情丝未了，春夜已尽，东方未白，孤灯先灭，如此作结，恰到好处。\n\n　　前人评子野词，最早有晁无咎。他说：“子野韵高，是耆卿所乏处。近世以来，作者皆不及。”（《能改斋漫录》十六引）清陈廷焯说子野词里“有含蓄处，亦有发越处；但含蓄不似温韦，发越亦不似豪苏腻柳”（《白雨斋词话》）。这些评论都很中肯。“含蓄”和“发越”，此词可以说兼而有之。至于韵高之说，亦可通过此词体味，略见一斑。', poem_tags = '宋词三百首,宋词精选,婉约,写景,抒情,爱情' WHERE poem_title = '千秋岁·数声鶗鴂' AND poem_author = '张先';
UPDATE edu_poem SET poem_tags = '宋词三百首,春天,清明节,写景' WHERE poem_title = '三台·清明应制' AND poem_author = '万俟咏';
UPDATE edu_poem SET poem_translation = '落下一片花瓣让人感到春色已减。如今风把成千上万的花打落在地，怎不令人发愁？\n且看将尽的落花从眼前飞过，也不再厌烦过多的酒入口。\n翡翠鸟在曲江上的楼堂上作巢，原来雄踞的石麒麟现今倒卧在地上。\n仔细推究事物盛衰变化的道理，那就是应该及时行乐，何必让虚浮的荣誉束缚自身呢？\n\n上朝回来，天天去典当春天穿的衣服，换得的钱每天到江头买酒喝，直到喝醉了才肯回来。\n到处都欠着酒债，那是寻常小事，人能够活到七十岁，古来也是很少的了。\n但见蝴蝶在花丛深处穿梭往来，蜻蜓在水面款款而飞，时不时点一下水。\n传话给春光，让我与春光一起逗留吧，虽是暂时相赏，也不要违背啊！', poem_notes = '曲江：河名，在陕西西安市东南郊，唐朝时候是游赏的好地方。\n减却春：减掉春色。\n万点：形容落花之多。\n且：暂且。经眼：从眼前经过。\n伤：伤感，忧伤。江上小堂巢翡翠 巢翡翠：翡翠鸟筑巢。\n苑边高冢卧麒麟苑：指曲江胜境之一芙蓉花。冢：坟墓。\n推：推究。物理：事物的道理。\n浮：虚名。\n朝回：上朝回来。典：押当。\n债：欠人的钱。行处：到处。\n深深：在花丛深处；又可解释为“浓密的样子”。见：现。\n款款：形容徐缓的样子。传语：传话给。\n风光：春光。共流转：在一起逗留的盘桓。\n违：违背，错过。', poem_appreciation = '曲江又名曲江池，故址在今西安城南五公里处，原为汉武帝所造。唐玄宗开元年间大加整修，池水澄明，花卉环列。其南有紫云楼、芙蓉苑；西有杏园、慈恩寺。是著名游览胜地。\n\n　　第一首写他在曲江看花吃酒，布局出神入化，抒情感慨淋漓。\n\n　　在曲江看花吃酒，正遇“良辰美景”，可称“赏心乐事”了，但作者却别有怀抱，一上来就表现出无可奈何的惜春情绪，产生出惊心动魄的艺术效果。他一没有写已经来到曲江，二没有写来到曲江时的节令，三没有写曲江周围花木繁饶，而只用“风飘万点”四字，就概括了这一切。“风飘万点”，不止是客观地写景，缀上“正愁人”三字，重点就落在见景生情、托物言志上了。“风飘万点”，这对于春风得意的人来说，会煞是好看，该不会又“正愁人”。但是作者面对的是“风飘万点”，那“愁”却早已萌生于前此的“一片花飞”，因而用跌笔开头：“一片花飞减却春！”历尽漫长的严冬，好容易盼到春天来了，花儿开了。这春天，这花儿，是很值得人们珍惜的。然而“一片花飞”，又透露了春天消逝的消息。敏感的、特别珍惜春天的诗人就不能不“愁”。“一片”，是指一朵花儿上的一个花瓣。因一瓣花儿被风吹落就感到春色已减，暗暗发愁，可如今，面对着的分明是“风飘万点”的严酷现实啊！因此“正愁人”三字，非但没有概念化的毛病，简直力透纸背。\n\n　　“风飘万点”已成现实，那尚未被风飘走的花儿就更值得爱惜。然而那风还在吹。剩下的，又一片、一片地飘走，眼看即将飘尽了。第三句就写这番情景：“且看欲尽花经眼。”“经眼”之花“欲尽”，只能“且看”。“且”，是暂且、姑且之意。而当眼睁睁地看着枝头残花一片、一片地被风飘走，加入那“万点”的行列，心中滋味就不怎么样了。于是来了第四句：“莫厌伤多酒入唇。”吃酒为了消愁。一片花飞已愁；风飘万点更愁；枝上残花继续飘落，即将告尽，愁上添愁。因而“酒”已“伤多”，却禁不住继续“入唇”啊！\n\n　　蒋弱六云：“只一落花，连写三句，极反复层折之妙。接入第四句，魂消欲绝。”这是颇有见地的。然而作者没有说明要如此“反复层折”地写落花，以致魂消欲绝的原因，究竟是仅仅叹春光易逝，还是有慨于难于直陈的人事问题。\n\n　　第三联“江上小堂巢翡翠，苑边高冢卧麒麟。”这一联并非人们所认为的只是叙述凄凉的景象，而是对尾联哲学的阐述。如果想要理解这其中的意思那么就要对古代文人道家归隐思想有所了解了。江上小堂巢翡翠，是指快乐自由的豪放之士。苑边高冢卧麒麟，则是指人生易老，都会走向衰亡的，哪怕是高高在上的王公贵族也不可避免。由苑边高冢即足以见得。结合此联总体，就是说人生苦短，而面对这些则需像翡翠一样好好快乐一番，即说了前边愁思在徘徊于不徘徊之间的纠结情绪，又为下文做了很好的铺垫，可看出杜甫的手笔已经十分成熟。\n\n　　“细推物理须行乐，何用浮荣绊此身？”\n\n　　这两句意思是：在这个世界上乐是一个人毕生所追求的，那为什么不去痛快的了一次呢。\n\n　　大家可以去参考“自是不归归便得，五湖烟景有谁争”去理解诗中行乐的含义，这是一种极为无奈而发出的一句感叹而已。\n\n　　联系全篇来看，所谓“行乐”，绊此身的浮荣指的就是“左拾遗”那个从八品上的谏官。因为疏救房琯，触怒了肃宗，从此，为肃宗疏远。作为谏官，他的意见却不被采纳，还蕴含着招灾惹祸的危机。这首诗就是公元758年（乾元元年）暮春任“左拾遗”时写的。到了这年六月，果然受到处罚，被贬为华州司功参军。从写此诗到被贬，不过两个多月的时间。明乎此，就会对这首诗有比较确切的理解。\n\n　　这是“联章诗”，上、下两首之间有内在的联系。下一首，即紧承“何用浮荣绊此身”而来。\n\n　　前四句一气旋转，而又细针密线。仇兆鳌注：“酒债多有，故至典衣；七十者稀，故须尽醉。二句分应。”就章法而言，大致是不错的。但把“尽醉”归因于“七十者稀”，对诗意的理解就表面化了。时当暮春，长安天气，春衣才派用场；即使穷到要典当衣服的程度，也应该先典冬衣。如今竟然典起春衣来，可见冬衣已经典光。这是透过一层的写法。而且不是偶而典，而是日日典。这是更透过一层的写法。“日日典春衣”，读者准以为不是等米下锅，就是另有燃眉之急；然而读到第二句，才知道那不过是为了“每日江头尽醉归”，真有点出人意外。出人意外，就不能不引人深思：为什么要日日尽醉呢？\n\n　　诗人还不肯回答读者的疑问，又逼进一层：“酒债寻常行处有。”“寻常行处”，包括了曲江，又不限于曲江。行到曲江，就在曲江尽醉；行到别的地方，就在别的地方尽醉。因而只靠典春衣买酒，无异于杯水车薪，于是乎由买到赊，以至“寻常行处”，都欠有“酒债”。付出这样高的代价就是为了换得个醉醺醺。　诗人对这这究竟是为什么终于作了回答：“人生七十古来稀。”意谓人生能活多久，既然不得行其志，就“莫思身外无穷事，且尽生前有限杯”吧！这是愤激之言，联系诗的全篇和杜甫的全人，是不难了解言外之意的。\n\n　　“穿花”一联写江头景。在杜诗中也是别具一格的名句，叶梦得曾指出：“诗语固忌用巧太过，然缘情体物，自有天然工妙，虽巧而不见刻削之痕。老杜……‘穿花蛱蝶深深见，点水蜻蜓款款飞’：‘深深’字若无‘穿’字，‘款款’字若无‘点’字，皆无以见其精微如此。然读之浑然，全似未尝用力，此所以不碍其气格超胜。使晚唐诸子为之，便当如‘鱼跃练波抛玉尺，莺穿丝柳织金梭’体矣。”（《石林诗话》卷下）这一联“体物”有天然之妙，但不仅妙在“体物”，还妙在“缘情”。“七十古来稀”，人生如此短促，而“一片花飞减却春，风飘万点正愁人”，大好春光，又即将消逝，非常值得珍惜。诗人正是满怀惜春之情观赏江头景物的。“穿花蛱蝶深深见，点水蜻蜓款款飞”，这是无比恬静、无比自由、无比美好的境界。可是这样恬静、这样自由、这样美好的境界，存在不了多久了。于是诗人“且尽芳樽恋物华”，写出了这样的结句：\n\n　　“传语风光共流转，暂时相赏莫相违。”\n\n　　“传语”犹言“寄语”，对象就是“风光”。这里的“风光”，就是明媚的春光。“穿光”一联体物之妙，不仅在于写小景如画，而且在于以小景见大景。读这一联，就能唤起春光明媚的美感。蛱蝶、蜻蜓，正是在明媚的春光里自由自在地穿花、点水；深深见（现）、款款飞的。失掉明媚的春光，这样恬静、这样自由、这样美好的境界也就不复存在了。诗人以情观物，物皆有情，因而“传语风光”说：“可爱的风光呀，你就同穿花的蛱蝶、点水的蜻蜓一起流转，让我欣赏吧，那怕是暂时的；可别连这点心愿也违背了啊！”\n\n　　仇注引张綖语云：“二诗以仕不得志，有感于暮春而作。”言简意赅，深得诗人用心。因“有感于暮春而作”，故暮春之景与惜春、留春之情融合无间。因“仕不得志”而有感，故惜春、留春之情饱含深广的社会内容，耐人寻味。\n\n　　这两首诗总的特点，用我国传统的美学术语说，就是“含蓄”，就是有“神韵”。所谓“含蓄”，所谓“神韵”，就是留有余地。抒情、写景，力避倾囷倒廪，而要抒写最典型最有特征性的东西，从而使读者通过已抒之情和已写之景去玩味未抒之情，想象未写之景。“一片花飞”、“风飘万点”，写景并不工细。然而“一片花飞”，最足以表现春减；“风飘万点”，也最足以表现春暮。一切与春减、春暮有关的景色，都可以从“一片花飞”、“风飘万点”中去冥观默想。比如说，从花落可以想到鸟飞，从红瘦可以想到绿肥……“穿花”一联，写景可谓工细；但工而不见刻削之痕，细也并非详尽无遗。例如只说“穿花”，不复具体地描写花，只说“点水”，不复具体地描写水，而花容、水态以及与此相关的一切景物，都宛然可想。\n\n　　就抒情方面说，“何用浮荣绊此身”，“朝回日日典春衣，……”，其“仕不得志”是依稀可见的。但如何不得志，为何不得志，却秘而不宣，只是通过描写暮春之景抒发惜春、留春之情；而惜春、留春的表现方式，也只是吃酒，只是赏花玩景，只是及时行乐。诗中的抒情主人公“日日江头尽醉归”，从“一片花飞”到“风飘万点”，已经目睹了、感受了春减、春暮的全过程，还“传语风光共流转，暂时相赏莫相违”，真可谓乐此不疲了！然而仔细探索，就发现言外有意，味外有味，弦外有音，景外有景，情外有情，“测之而益深，究之而益来”，真正体现了“神余象外”的艺术特点。', poem_tags = '暮春,写景,景点,哀思,组诗,早教古诗100首' WHERE poem_title = '曲江二首' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '洛阳城东的桃花李花随风飘转，飞来飞去，不知落入了谁家？\n洛阳女子有着娇艳的容颜，独坐院中，看着零落的桃李花而长声叹息。\n今年我在这里看着桃花李花因凋零而颜色衰减，明年花开时节不知又有谁还能看见那繁花似锦的胜况？\n已经看见了俊秀挺拔的松柏被摧残砍伐作为柴薪，又听说那桑田变成了汪洋大海。\n故人现在已经不再悲叹洛阳城东凋零的桃李花了，而今人却依旧对着随风飘零的落花而伤怀。\n年年岁岁繁花依旧，岁岁年年看花之人却不相同。\n转告那些正值青春年华的红颜少年，应该怜悯这位已是半死之人的白头老翁。\n如今他白发苍苍，真是可怜，然而他从前亦是一位风流倜傥的红颜美少年。\n这白头老翁当年曾与公子王孙寻欢作乐于芳树之下，吟赏清歌妙舞于落花之前。\n亦曾像东汉光禄勋马防那样以锦绣装饰池台，又如贵戚梁冀在府第楼阁中到处涂画云气神仙。\n白头老翁如今一朝卧病在床，便无人理睬，往昔的三春行乐、清歌妙舞如今又到哪里去了呢？\n而美人的青春娇颜同样又能保持几时？须臾之间，已是鹤发蓬乱，雪白如丝了。\n只见那古往今来的歌舞之地，剩下的只有黄昏的鸟雀在空自悲啼。', poem_notes = '代：拟。白头翁：白发老人。这首诗的题目，各个选本都有不同。《唐音》《唐诗归》《唐诗品汇》《全唐诗》，均作“代悲白头翁”。《全唐诗》又作“代白头吟”。《文苑英华》《乐府诗集》《韵语阳秋》作“白头吟”。尤袤《全唐诗话》作“白头翁咏”。\n坐见：一作“行逢”。\n松柏摧为薪：松柏被砍伐作柴薪。《古诗十九首》：“古墓犁为田，松柏摧为薪。”\n桑田变成海：《神仙传》：“麻姑谓王方平曰：‘接待以来，已见东海三为桑田’”。\n“公子”两句：白头翁年轻时曾和公子王孙在树下花前共赏清歌妙舞。\n光禄：光禄勋。用东汉马援之子马防的典故。《后汉书·马援传》（附马防传）载：马防在汉章帝时拜光禄勋，生活很奢侈。文锦绣：指以锦绣装饰池台中物。文，又作“开”、或“丈”，皆误。\n将军：指东汉贵戚梁冀，他曾为大将军。《后汉书·梁冀传》载：梁冀大兴土木，建造府宅。\n宛转蛾眉：本为年轻女子的面部画妆，此代指青春年华。\n须臾：一会儿。鹤发：白发。\n古：一作“旧”。', poem_appreciation = '这是一首拟古乐府诗。《白头吟》是汉乐府相和歌楚调曲旧题，古辞写一个女子向遗弃她的情人表示决绝。刘希夷这首诗则从女子写到老翁，咏叹青春易逝、富贵无常。构思独创，抒情宛转，语言优美，音韵和谐，艺术性较高，在初唐即受推崇，历来传为名篇。\n\n　　诗的前半写洛阳女子感伤落花，抒发人生短促、红颜易老的感慨；后半写白头老翁遭遇沦落，抒发世事变迁、富贵无常的感慨，以“但看古来歌舞地，惟有黄昏鸟雀悲”总结全篇意旨。在前后的过渡，以“寄言全盛红颜子，应怜半死白头翁”二句，点出红颜女子的未来不免是白头老翁的今日，白头老翁的往昔实即是红颜女子的今日。诗人把红颜女子和白头老翁的具体命运加以典型化，表现出这是一大群处于封建社会下层的男女老少的共同命运，因而提出应该同病相怜，具有“醒世”的作用。\n\n　　“洛阳城东桃李花，飞来飞去落谁家”，诗的开头两句，描绘洛阳城东暮春景色。洛阳是唐代的东都，十分繁华；繁华的都市盛开着艳丽的鲜花，满城春色，生气勃勃，令人心醉神往。然而时光易逝，此时的洛阳已是落花季节，桃李纷飞，不知飘向何处。这两句是诗的起兴。下文表达的对大好春光、妙龄红颜的憧憬和留恋，对桃李花落、青春易逝的感伤和惋惜，都是由此生发开来的。\n\n　　“洛阳女儿好颜色”以下十句，写年轻的洛阳女儿面对漫天飞舞的落花生出无限感慨。洛阳女儿所感伤的，实际上是由大自然的变化而联想到美的短暂和人的生命的有限。“今年花落颜色改，明年花开复谁在？”表现的是因为春光的流逝而感叹红颜易老、生命无常的心理。“松柏摧为薪”句，出自《古诗十九首·去者日以疏》：“古墓犁为田，松柏摧为薪。”“桑田变成海”，指陆地变成海洋，典出《神仙传·麻姑》：“麻姑自说云，接待以来，已见东海三为桑田。”这两句运用比喻，形象地表现世事变化很大。“古人无复洛城东，今人还对落花风”则揭示人生易逝、宇宙永恒的客观规律。“年年岁岁花相似，岁岁年年人不同”两句，以优美、流畅、工整的对句集中地表现青春易老世事无常的感叹，富于诗的意境，且具有哲理性，历来广为传诵。\n\n　　“寄言全盛红颜子”以下十句，概括叙述白头翁一生的经历。白头老翁曾是一个美貌少年，从前他也常和公子王孙一起，在树下花前歌舞游乐。“光禄池台文锦绣”两句，以历史上权臣贵戚的豪华奢侈，表现白头翁曾经历过的一段富贵生活。然而，一旦生病衰老，就无人理睬，三春行乐只好让给别人了。这一段通过描写白头翁从红颜到老病、从游乐到孤苦的生活，不仅表示了诗人对青春红颜、清歌妙舞的眷恋、向往，对垂老白头翁的怜悯、同情，同时进一步抒发了对美的短暂和生命的有限的感慨，从而增强了诗歌的艺术感染力和哲理性。\n\n　　结尾四句点明主旨，收束全诗。“宛转蛾眉能几时？须臾鹤发乱如丝”两句感叹美貌的少女转眼之间将化作白发的老妇，惋惜青春难驻。“但看古来歌舞地，唯有黄昏鸟雀悲”两句，一切都如同过眼云烟，迅速消失了！往日繁华热闹的游乐场所，如今只有几只离群的鸟雀在清冷的暮蔼中发出几声凄苦的悲鸣。末句的最后一个“悲”字，是此诗的基调。\n\n　　诗的前半首化自东汉宋子侯的乐府歌辞《董娇娆》，但经过刘希夷的再创作，更为概括典型。作为前半的结语，“年年岁岁”二句是精警的名句，它比喻精当，语言精粹，令人警省。“年年岁岁”“岁岁年年”的颠倒重复，不仅排沓回荡，音韵优美，更在于强调了时光流逝的无情事实和听天由命的无奈情绪，真实动情。“花相似”、“人不同”的形象比喻，突出了花卉盛衰有时而人生青春不再的对比，耐人寻味。结合后半写白头老翁的遭遇，可以体会到，诗人不用“女子”和“春花”对比，而用泛指名词“人”和“花”对比，不仅是由于七言诗字数的限制，更由于要包括所有不能掌握自己命运的可怜人，其中也包括了诗人自己。也许，因此产生了不少关于这诗的附会传说。如《大唐新语》《本事诗》所云：诗人自己也觉得这两句诗是一种不祥的预兆，即所谓“诗谶”，一年后，诗人果然被害，应了所谓“诗谶”的说法。这类无稽之谈的产生与流传，既反映人们爱惜诗人的才华，同情他的不幸，也表明这诗情调也过于伤感了。\n\n　　此诗融会汉魏歌行、南朝近体及梁、陈宫体的艺术经验，而自成一种清丽婉转的风格。它还汲取乐府诗的叙事间发议论、古诗的以叙事方式抒情的手法，又能巧妙交织运用各种对比，发挥对偶、用典的长处，是这诗艺术上的突出成就。刘希夷生前似未成名，而在死后，孙季良编选《正声集》，“以刘希夷诗为集中之最，由是大为时人所称”（《大唐新语》）。可见他一生遭遇压抑，是他产生消极感伤情绪的思想根源。这诗浓厚的感伤情绪，反映了封建制度束缚戕害人才的事实。', poem_tags = '写花,感伤,青春' WHERE poem_title = '代悲白头翁' AND poem_author = '刘希夷';
UPDATE edu_poem SET poem_translation = '我有多少的恨，昨夜梦中的景象，还像以前我还是故国君主时，常在上苑游玩，车子如流水穿过，马队像长龙一样川流不息。正是景色优美的春天，还吹着融融的春风。', poem_notes = '望江南：《全唐诗》、《词谱》等均作《忆江南》。\n梦魂：古人认为在睡梦中人的灵魂会离开肉体，故称“梦魂”。\n还似：一作“还是”。上苑：封建时代供帝王玩赏、打猎的园林。\n车如流水马如龙：意思是车子接连不断像流水一样驰过，马匹络绎不绝像一条龙一样走动。形容车马络绎不绝，十分繁华热闹。花月：花和月，泛指美好的景色。花月正春风，意思是形容春天鲜花怒放，春夜月光明朗，春风微拂的情景，描绘春光的明媚。', poem_tags = '婉约,记梦,思国' WHERE poem_title = '忆江南·多少恨' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '我住在北方海滨，而你住在南方海滨，欲托鸿雁传书，它却飞不过衡阳。\n当年春风下观赏桃李共饮美酒，江湖落魄，一别已是十年，常对着孤灯听着秋雨思念着你。\n你支撑生计也只有四堵空墙，艰难至此。古人三折肱后便成良医，我却但愿你不要如此。\n想你清贫自守发奋读书，如今头发已白了罢，隔着充满瘴气的山溪，猿猴哀鸣攀援深林里的青藤。', poem_notes = '此诗作于神宗元丰八年（1085），其时诗人监德州（今属山东）德平镇。\n黄几复：名介，南昌人，是黄庭坚少年时的好友，时为广州四会（今广东四会县）县令。\n“我居”句：《左传·僖公四年》：“君处北海，寡人处南海，惟是风马牛不相及也。”作者在“跋”中说：“几复在广州四会，予在德州德平镇，皆海滨也。”\n寄雁”句：传说雁南飞时不过衡阳回雁峰，更不用说岭南了。\n四立壁：《史记·司马相如传》：“文君夜奔相如，相如驰归成都，家徒四壁立。”\n蕲：祈求。肱：上臂,手臂由肘到肩的部分，古代有三折肱而为良医的说法。\n瘴溪：旧传岭南边远之地多瘴气。', poem_appreciation = '“我居北海君南海”，起势突兀。写彼此所居之地一“北”一“南”，已露怀念友人、望而不见之意；各缀一“海”字，更显得相隔辽远，海天茫茫。作者跋此诗云：“几复在广州四会，予在德州德平镇，皆海滨也。”\n\n　　“寄雁传书谢不能”，这一句从第一句中自然涌出，在人意中；但又有出人意外的地方。两位朋友一在北海，一在南海，相思不相见，自然就想到寄信；“寄雁传书”的典故也就信手拈来。李白长流夜郎，杜甫在秦州作的《天末怀李白》诗里说：“凉风起天末，君子意如何？鸿雁几时到，江湖秋水多！”强调音书难达，说“鸿雁几时到”就行了。黄庭坚却用了与众不同的说法：“寄雁传书——谢不能。”意谓：我托雁儿捎一封信去，雁儿却谢绝了。“寄雁传书”，这典故太熟了，但继之以“谢不能”，立刻变陈熟为生新。黄庭坚是讲究“点铁成金”之法的，王若虚批评说：“鲁直论诗，有‘夺胎换骨’、‘点铁成金’之喻，世以为名言。以予观之，特剽窃之黠者耳。”（《滹南诗话》卷下）类似“剽窃”的情况当然是有的，但也不能一概而论。上面所讲的诗句，可算成功的例子。\n\n　　“寄雁传书”，作典故用，不过表示传递书信罢了。但相传大雁南飞，至衡阳而止。王勃《秋日登洪府滕王阁饯别序》云：“雁阵惊寒，声断衡阳之浦。”秦观《阮郎归》云：“衡阳犹有雁传书，郴阳和雁无。”黄庭坚的诗句，亦同此意；但把雁儿拟人化，写得更有情趣。\n\n　　第二联在当时就很有名。这两句诗所用的词都是常见的，甚至可说是“陈言”，谈不上“奇”。张耒称为“奇语”，当然是就其整体说的；可惜的是何以“奇”，“奇”在何处，他没有讲。其实，正是黄庭坚这样遣词入诗，才创造出如此清新隽永的意境，给人以强烈的艺术感染。\n\n　　任渊说这“两句皆记忆往时游居之乐”，看来是弄错了。据《黄几复墓志铭》所载，黄几复于熙宁九年（1076年）“同学究出身，调程乡尉”；距作此诗刚好十年。结合诗意来看，黄几复“同学究出身”之时，是与作者在京城里相聚过的，紧接着就分别了，一别十年。这两句诗，上句追忆京城相聚之乐，下句抒写别后相思之深。诗人摆脱常境，不用“我们两人当年相会”之类的一般说法，却拈出“一杯酒”三字。“一杯酒”，这太常见了，但惟其常见，正可给人以丰富的暗示。沈约《别范安成》云：“勿言一樽酒，明日难重持。”王维《送元二使安西》云：“劝君更进一杯酒，西出阳关无故人。”杜甫《春日忆李白》云：“何时一樽酒，重与细论文？”故人相见，或谈心，或论文，总是要吃酒的。仅用“一杯酒”，就写出了两人相会的情景。诗人还选了“桃李”、“春风”两个词。这两个词，也很陈熟，但正因为熟，能够把阳春烟景一下子唤到读者面前，用这两个词给“一杯酒”以良辰美景的烘托，就把朋友相会之乐表现出来了。\n\n　　其实要用七个字写出两人离别和别后思念之殷，也不那么容易。诗人却选了“江湖”、“夜雨”、“十年灯”，作了动人的抒写。“江湖”一词，能使人想到流转和飘泊，杜甫《梦李白》云：“江湖多风波，舟楫恐失坠。”“夜雨”，能引起怀人之情，李商隐《夜雨寄北》云：“君问归期未有期，巴山夜雨涨秋池。”在“江湖”而听“夜雨”，就更增加萧索之感。“夜雨”之时，需要点灯，所以接着选了“灯”字。“灯”，这是一个常用词，而“十年灯”，则是作者的首创，用以和“江湖夜雨”相联缀，就能激发读者的一连串想象：两个朋友，各自飘泊江湖，每逢夜雨，独对孤灯，互相思念，深宵不寐。而这般情景，已延续了十年。\n\n　　晚唐温庭筠不用动词，只选择若干名词加以适当的配合，写出了“鸡声茅店月，人迹板桥霜”两句诗，真切地表现了“商山早行”的情景，颇为后人所称道。欧阳修有意学习，在《送张至秘校归庄》诗里写了“鸟声梅店雨，柳色野桥春”一联，终觉其在范围之内，他自己也不满意（参看《诗话总龟》、《存余堂诗话》）。黄庭坚的这一联诗，吸取了温诗的句法，却创造了独特的意境。“桃李”、“春风”、“一杯酒”，“江湖”、“夜雨”、“十年灯”，这都是些名词或名词性词组，其中的每一个词或词组，都能使人想象出特定的景象、特定的情境，展现了耐人寻味的艺术天地。\n\n　　同时这两句诗，还是相互对照的。两句诗除各自表现的情景之外，还从相互对照中显示出许多东西。第一、下句所写，分明是别后十年来的情景，包括眼前的情景；那么，上句所写，自然是十年前的情景。因此，上句无须说“我们当年相会”，而这层意思，已从与下句的对照中表现出来。第二、“江湖”除了前面所讲的意义之外，还有与京城相对的意义，所谓“身在江湖，心存魏阙”，就是明显的例证。“春风”一词，也另有含意。孟郊《登科后》诗云：“昔日龌龊不足夸，今朝放荡思无涯。春风得意马蹄疾，一日看尽长安花。”和下句对照，上句所写，时、地、景、事、情，都依稀可见：时，十年前的春季；地，北宋王朝的京城开封；景，春风吹拂、桃李盛开；事，友人“同学究出身”，把酒欢会；情，则洋溢于良辰美景、赏心乐事之中。\n\n　　“桃李春风”与“江湖夜雨”，这是“乐”与“哀”的对照；“一杯酒”与“十年灯”，这是“一”与“多”的对照。“桃李春风”而共饮“一杯酒”，欢会极其短促。“江湖夜雨”而各对“十年灯”，飘泊极其漫长。快意与失望，暂聚与久别，往日的交情与当前的思念，都从时、地、景、事、情的强烈对照中表现出来，令人寻味无穷。张耒评为“奇语”，并非偶然。\n\n　　后四句，从“持家”、“治病”、“读书”三个方面表现黄几复的为人和处境。\n\n　　“持家，——但有四立壁”，“治病，——不蕲三折肱”。这两句，也是相互对照的。作为一个县的长官，家里只有立在那儿的四堵墙壁，这既说明他清正廉洁，又说明他把全部精力和心思用于“治病”和“读书”，无心、也无暇经营个人的安乐窝。“治病”句化用《左传·定公十三年》记载的一句古代成语：“三折肱，知为良医。”意思是：一个人如果三次跌断胳膊，就可以断定他是个好医生，因为他必然积累了治疗和护理的丰富经验。在这里，当然不是说黄几复会“治病”，而是说他善“治国”，《国语·晋语》里就有“上医医国，其次救人”的说法。黄庭坚在《送范德孺知庆州》诗里也说范仲淹“平生端有活国计，百不一试埋九京”。作者称黄几复善“治病”、但并不需要“三折肱”，言外之意是：他已经有政绩，显露了治国救民的才干，为什么还不重用，老要他在下面跌撞呢？\n\n　　尾联以“想见”领起，与首句“我居北海君南海”相照应。在作者的想象里，十年前在京城的“桃里春风”中把酒畅谈理想的朋友，如今已白发萧萧，却仍然像从前那样好学不倦。他“读书头已白”，还只在海滨作一个县令。其读书声是否还像从前那样欢快悦耳，没有明写，而以“隔溪猿哭瘴溪藤”作映衬，就给整个图景带来凄凉的氛围；不平之鸣，怜才之意，也都蕴含其中。\n\n　　黄庭坚推崇杜甫，以杜甫为学习榜样，七律尤其如此。但比较而言，他的学习偏重形式技巧方面。他说：“老杜作诗，退之作文，无一字无来处，盖后人读书少，故谓韩、杜自作此语耳。古之能为文章者，真能陶冶万物，虽取古人之陈言入于翰墨，如灵丹一粒，点铁成金也。”（《答洪驹父书》）而杜甫的杰出之处主要表现在以“穷年忧黎元”的激情，艺术地反映了安史之乱前后的广阔现实。诗的语言，也丰富多彩，元稹就赞赏“怜渠直道当时语，不着心源傍古人”的一面。当然，杜甫的不少律诗，也是讲究用典的；黄庭坚把这一点推到极端，追求“无一字无来处”，其流弊是生硬晦涩，妨碍了真情实感的生动表达。但这也不能一概而论。例如这首《寄黄几复》，就可以说是“无一字无来处”。但并不觉晦涩；有的地方，还由于活用典故而丰富了诗句的内涵；而取《左传》《史记》《汉书》中的散文语言入诗，又给近体诗带来苍劲古朴的风味。\n\n　　黄庭坚主张“宁律不谐而不使句弱”。他的不谐律是有讲究的，方东树就说他“于音节尤别创一种兀傲奇崛之响，其神气即随此以见”。在这一点上，他也学习杜甫。杜甫首创拗律，如“落花游丝白日静，鸣鸠乳燕青春深”，“有时自发钟磐响，落日更见渔樵人”等句，从拗折之中，见波峭之致。黄庭坚推而广之，于当用平字处往往易以仄字，如“只今满坐且尊酒，后夜此堂空月明”，“黄流不解涴明月，碧树为我生凉秋”，“清谈落笔一万字，白眼举觞三百杯”等都句法拗峭而音响新异，具有特殊的韵味。这首《寄黄几复》亦然。“持家”句两平五仄，“治病”句也顺中带拗，其兀傲的句法与奇峭的音响，正有助于表现黄几复廉洁干练，刚正不阿的性格。', poem_tags = '思念,友情' WHERE poem_title = '寄黄几复' AND poem_author = '黄庭坚';
UPDATE edu_poem SET poem_translation = '客舍前的梅花已经凋残，溪桥旁新生细柳轻垂，春风踏芳草远行人跃马扬鞭。走得越远离愁越没有穷尽，像那迢迢不断的春江之水。\n寸寸柔肠痛断，行行盈淌粉泪，不要登高楼望远把栏杆凭倚。平坦的草地尽头就是重重春山，行人还在那重重春山之外。', poem_notes = '候馆：迎宾候客之馆舍。\n草薰：小草散发的清香。薰，香气侵袭。征辔（pèi）：行人坐骑的缰绳。辔，缰绳。\n迢迢：形容遥远的样子。\n寸寸柔肠：柔肠寸断，形容愁苦到极点。\n盈盈：泪水充溢眼眶之状。粉泪：泪水流到脸上，与粉妆和在一起。\n危阑：也作“危栏”，高楼上的栏杆。\n平芜：平坦地向前延伸的草地。芜，草地。', poem_tags = '宋词三百首,婉约,写景,离别,相思' WHERE poem_title = '踏莎行·候馆梅残' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '铺满大地的白雪映照着山城。冰天雪地里，楼上吹笛的，连玉指都感到寒冷吧？你吹奏出的一声声羌笛音里，饱含着离别的哀怨，飘荡在空间。江南的梅花开了又落，落了又开，不知开落了几次了？我在天涯漂泊，两鬓已如此斑白了。\n面对天上点点闪亮的星星，朗朗普照的圆月，我独自一人痛饮不休。喝着，喝着，好像觉得天上的银河倒流入了我的杯中。我这翰林学士为我这种相思写了三千首诗词，想寄给你这南方的恋人，让你去忍着眼泪慢慢细读啊！', poem_notes = '玉指：比喻女子洁白如玉的纤指。\n羌管：即羌笛，出自古代西部羌族的一种管乐器，其声凄切、哀伤。又名玉笛、短笛、芦笛等。范仲淹《渔家傲·塞下秋来风景异》：“羌管悠悠霜满地”。\n楼间：一作“楼闲”，空楼的意思。\n团团：形容月圆。\n河汉：指银河。翰林：指李白。刘著曾入翰林，故此处以李白自比。风月：原指诗句中的骚情雅意，此处代指表达爱情相思的诗篇。三千首：极言作诗之多。这里词人说自己作诗非常多，有如翰林李白。\n吴姬：吴地（即江南）一带的美女。此借指曾经相好的女子。\n忍泪：强忍眼泪。', poem_appreciation = '上片状别离滋味，下片抒思念情怀。写得情真意挚，清丽绵密而又自然健朗，笔墨别具一格。“雪照山城玉指寒，一声羌管怨楼间”起拍，追怀往日那次难忘的离别场面。山城雪照，一个严寒的冬日。山城指南方某地，词人与所爱者分携之处。悲莫悲兮生别离，离筵充满了悲凉的气氛。玉指寒，既点冬令，又兼示离人心上的凄清寒意。吹梅笛怨，也许是她在小楼上奏起的一曲《梅花落》吧。“南楼不恨吹横笛，恨晓风、千里关山。”羌管悠悠，离愁满目。这两句自“细雨梦回鸡塞远，小楼吹彻玉笙寒”化出，而景情切合，缠绵哀感，深得脱胎换骨之妙。这一别，黯然销魂，情难自禁，从此后相思两地，再见何年。下面的“江南几度梅花发”，接得如行云流水，自然无迹。由笛怨声声到梅花几度，暗示着江南的梅花开了又落，落了又开，情天恨海，逝者如斯。无情的岁月早经染白了主人公的青青双鬓。追忆别时，恍如昨日。整个上片，读来已觉回肠荡气。\n\n　　下片，由当年写到此夕，感情进一步深化。天涯霜月又今宵，茫茫百感，袭上心头，除了诗和酒，世上没有什么能寄托自己的思恋，消遣自己的愁怀。换头先说饮酒。一片深愁待酒浇。苍茫无际的天野，有星光作伴，月色相陪，还是开怀痛饮，不管一切吧。这几句大有“尽挹西江，细斟北斗，万象为宾客”的气势，“倒流河汉”，等于说吸尽银河，更巧妙的是暗中融化了李贺“酒酣喝月使倒行”（《秦王饮酒》）的意境，痛饮淋漓，忘乎所以，恨不得令银河倒流，让辰光倒转，把自己的一腔郁闷，驱除个干净。兴会不可谓不酣畅了。然而，酒入愁肠，化作的毕竟是相思泪。紧接着，一气呵成的，就是放笔疾书，不可遏止地倾转，无所顾忌地抒怀，要将那无穷的往事、别后的相思；要将那尘满面、鬓如霜的感慨；要将那但愿人长久、千里共婵娟的祝愿，一齐泻向笔端。可这些，是有限的篇章、区区的言语不能表达的，他只好借助于欧阳修《赠王安石》的成句，动用一下“翰林风月三千首”了。而竟夕呜咽、愁情满纸的诗篇，寄与伊人，将会带给她新的悲哀。作者仿佛已感到了她的心弦颤动，看到了她的泪眼模糊。设身处地，体贴入微，心息之相通，一至于此。魂逐飞蓬。心灵感荡，“非陈诗何以展其义，非长歌何以骋其情”。而在一首短章小令之中，用词代简，以歌当哭，包含了如许丰富的感情容量，传达了如许深微的心理活动，长短句的语言艺术功能也可算得发挥尽致了。\n\n　　全词以流转自然的音节，迂回曲折的笔势，既缠绵悱侧，又激宕疏爽，以词代简，短篇中含丰富的感情内容，传达出微妙而细致的内心活动，把一种无力排遣的悲凉愁绪发挥得淋漓尽致。', poem_tags = '婉约,离别,思念' WHERE poem_title = '鹧鸪天·雪照山城玉指寒' AND poem_author = '刘著';
UPDATE edu_poem SET poem_translation = '前几日伴狂风自去北海漂游，费尽千辛万苦回到扬子江头。\n我的心就像那一根磁针，不永远指向南方誓不罢休。', poem_notes = '扬子江：长江在南京一带称扬子江。\n北海：这里指北方。\n回从：曲意顺从。\n磁针石：即指南针。\n南方：这里指南宋王朝。', poem_appreciation = '《尧典》中说： “诗言志，歌咏言。”诗，一向是表达人的思想感情和志向的。诗人运用比兴手法，触景生情，抒写了自己心向南宋，不到南方誓不罢休的坚强信念，真实地反映了作者对祖国的坚贞和热爱。\n\n　　诗的首二句纪行，叙述他自镇江逃脱，绕道北行，在海上漂流数日后，又回到长江口的艰险经历。首句的“北海游”。指绕道长江口以北的海域。次句“回从扬子大江头”，指从长江口南归，引起三、四两句。\n\n　　末二句抒情，以“磁针石”比喻忠于宋朝的一片丹心，表明自己一定要战胜重重困难，回到南方，再兴义师，重整山河的决心。“臣心一片磁针石，不指南方不肯休”，表现了他不辞千难万险，赶到南方去保卫南宋政权的决心。忠肝义胆，昭若日月。\n\n　　全诗语言浅近，比喻贴切，字里行间表现出坚定不移的爱国主义精神。', poem_tags = '爱国,励志' WHERE poem_title = '扬子江' AND poem_author = '文天祥';
UPDATE edu_poem SET poem_translation = '你看这黄鼠还有皮，人咋会不要脸面。人若不要脸面，还不如死了算啦。\n你看这黄鼠还有牙齿，人却不顾德行。人要没有德行，不去死还等什么。\n你看这黄鼠还有肢体，人却不知礼义。人要不知礼义，还不如快快死去。', poem_notes = '相：视也。\n仪：威仪，指人的举止作风大方正派而言，具有尊严的行为外表。一说为“礼仪”。\n何为：为何，为什么。\n止：假借为“耻”，郑笺释为“容止”，也可通。\n俟：等。“不死何俟”为“俟何”宾语前置。\n体：肢体。\n礼：礼仪，指知礼仪，或指有教养。\n胡：何，为何，为什么，怎么。遄（chuán）：快，速速，赶快。', poem_appreciation = '《相鼠》大约是《诗经》里骂人最露骨、最直接、最解恨的一首。汉儒们“嫌于虐且俚矣！”意思是最粗鄙的语言暴力，是《诗》“三百篇所仅有”。但对此诗咒骂的对象，说法不一。前人对这个问题大致上有二说：《毛诗序》以为是刺在位者无礼仪，郑笺从之；《鲁诗》则认为是妻谏夫，班固承此说。后一说虽然有何楷、魏源、陈延杰诸家的阐发，但究竟由于所申述的内容与此诗所显露的深恶痛绝的情感不吻合，故为大多数说诗者所不取，而从毛序郑笺之说。\n\n　　《诗经》中写到“鼠”的有五首（《雨无正》“鼠思泣血”之鼠通癙，未计），除此诗外，其他四首都是直接把鼠作为痛斥或驱赶的对象，确实“老鼠过街，人人喊打”，自古而然。而此诗却有所不同，偏偏选中丑陋、狡黠、偷窃成性的老鼠与卫国“在位者”作对比，公然判定那些长着人形而寡廉鲜耻的在位者连老鼠也不如，诗人不仅痛斥，而且还要他们早早死去，以免玷污“人”这个崇高的字眼。至于所刺的“在位者”是谁，所刺何事，虽曾有过多种说法，但已无法考实，翻开卫国的史册，在位者卑鄙龌龊的勾当太多，如州吁弑兄桓公自立为卫君；宣公强娶太子伋未婚妻为妇；宣公与宣姜合谋杀太子伋；惠公与兄黔牟为争位而开战；懿公好鹤淫乐奢侈；昭伯与后母宣姜乱伦；等等。父子反目，兄弟争立，父淫子妻，子奸父妾，没有一件不是丑恶之极、无耻之尤。这些在位者确实禽兽不如，禽兽尚且恋群，而他们却是骨肉相残。此篇诗人咬牙切齿，是有感而发。\n\n　　此篇三章重叠，以鼠起兴，反覆类比，意思并列，但各有侧重，第一章“无仪”，指外表；第二章“无止（耻）”，指内心；第三章“无礼”，指行为。三章诗重章互足，合起来才是一个完整的意思，这是《诗经》重章的一种类型。此诗尽情怒斥，通篇感情强烈，语言尖刻；每章四句皆押韵，并且二、三句重复，末句又反诘进逼，既一气贯注，又回流激荡，增强了讽刺的力量与风趣。', poem_tags = '古诗三百首,诗经,讽刺' WHERE poem_title = '国风·鄘风·相鼠' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '传说在北国寒门这个地方，住着一条烛龙，它以目光为日月，张目就是白昼而闭目就是黑夜。\n这里连日月之光都照不到啊！只有漫天遍野的北风怒号而来。\n燕山的雪花其大如席，一片一片地飘落在轩辕台上。\n在这冰天雪地的十二月里，幽州的一个思妇在家中不歌不笑，愁眉紧锁。\n她倚着大门，凝望着来往的行人，盼望着她丈夫的到来。她的夫君到长城打仗去了，至今未回。长城那个地方可是一个苦寒要命的地方，夫君你可要保重啊。\n丈夫临别时手提宝剑，救边而去，在家中仅留下了一个虎皮金柄的箭袋。\n里面装着一双白羽箭，一直挂在堵上。上面结满了蜘蛛网，沾满了尘埃。\n如今其箭虽在，可是人却永远回不来了他已战死在边城了啊！\n人之不存，我何忍见此旧物乎？于是将其焚之为灰矣。\n黄河虽深，尚捧土可塞，唯有此生离死别之恨，如同这漫漫的北风雨雪一样铺天盖地，无边无垠。', poem_notes = '北风行：乐府“时景曲”调名，内容多写北风雨雪、行人不归的伤感之情。\n烛龙：中国古代神话传说中的龙。人面龙身而无足，居住在不见太阳的极北的寒门，睁眼为昼，闭眼为夜。\n此：指幽州，治所在今北京大兴县。这里指当时安禄山统治北方，一片黑暗。\n燕山：山名，在河北平原的北侧。轩辕台，纪念黄帝的建筑物，故址在今河北怀来县乔山上。这两句用夸张的语气描写北方大雪纷飞、气候严寒的景象。\n双蛾：女子的双眉。双蛾摧，双眉紧锁，形容悲伤、愁闷的样子。\n长城：古诗中常借以泛指北方前线。良，实在。\n鞞靫（bǐngchá）：当作鞴靫。虎文鞞靫，绘有虎纹图案的箭袋。\n“焚之”句：语出古乐府《有所思》：“摧烧之，当风扬其灰。”\n“黄河”句：《后汉书·朱冯虞郑周列传》：“此犹河滨之人，捧土以塞孟津，多见其不知量也。”此反其意而用之。\n北风雨雪：这是化用《诗经·国风·邶风·北风》中的“北风其凉，雨雪其雾”句意，原意是指国家的危机将至而气象愁惨，这里借以衬托思妇悲惨的遭遇和凄凉的心情。裁，消除。', poem_tags = '冬天,写雪,写风,借景抒情,女子,思念' WHERE poem_title = '北风行' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '现在正是农历十二月的末尾，气候温和舒畅，旧居蓝田山很可以一游。您正在温习经书，仓猝中不敢打扰，就自行到山中，在感配寺休息，跟寺中主持一起吃完饭，便离开了。\n\n　　我向北渡过深青色的灞水，月色清朗，映照着城郭。夜色中登上华子冈，见辋水泛起涟漪，水波或上或下，水中 的月影也随同上下。那寒山中远远的灯火，火光忽明忽暗在林外看得很清楚。深巷中狗叫，叫声像豹叫一样。村子里传来舂米声，又与稀疏的钟声相互交错。这时， 我独坐在那里，跟来的僮仆已入睡，多想从前你我于搀着手吟诵诗歌，在狭窄的小路上漫步，临近那清澈流水的情景。\n\n　　等到了春天，草木蔓延生长，春天的山景更可观赏，轻捷的鲦鱼跃出水面，白色的鸥鸟张开翅膀，晨露打湿了青 草地，麦田里雉鸟在清晨呜叫，这些景色离现在不远了，（您）能和我一起游玩吗?如果你天性不是与众不同的话，难道我能把邀请你当作闲事吗？而这当中有很深 的旨趣啊！不要忽略。因为有载运黄檗的人出山，托他带给你这封信，不一一详述了。', poem_notes = '秀才：唐代对参加进士科考试的人的称呼。\n腊月：农历十二月。古代在农历十二月举行“腊祭”，所以称十二月为腊月。\n景气：景色，气候。\n故山殊可过：旧居蓝田山很可以一游。故山，旧居的山，指王维的“辋川别业”所在地的蓝田山。殊，很。过，过访、游览。\n足下：您，表示对人的尊称。\n方温经：正在温习经书。方，正。\n猥：鄙贱。自谦之词。\n烦：打扰。\n辄便：就。\n憩感配寺：在感配寺休息。感配寺，王维集中有游感化寺的诗，《旧唐书·神秀传》中说，蓝田有化感寺。感配寺可能是化感寺之误。\n饭讫（qì）：吃完饭。讫，完。饭，名词作动词，吃饭。\n北涉玄灞：近来渡过灞水。涉，渡。玄，黑色，指水深绿发黑。\n华子冈：王维辋川别业中的一处胜景。\n辋水：车轮状的湖水。\n村墟：村庄。\n夜舂：晚上用臼杵捣谷（的声音）。舂，这里指捣米，即把谷物放在石臼里捣去外壳。\n疏：稀疏的。\n静默：指已入睡。\n曩：从前。\n仄迳：迳同径，狭窄的小路。\n当待：等到。\n蔓发：蔓延生长。\n轻鯈（tiáo）：即白，鱼名。身体狭长，游动轻捷。\n矫翼：张开翅膀。矫，举。\n青皋：青草地。皋，水边高地。\n麦陇：麦田里。\n朝雊（gòu）：早晨野鸡鸣叫。雊，野鸡鸣叫。\n斯之不远〕这不太远了。斯，代词，这，指春天的景色。\n傥：同“倘”，假使，如果。\n天机清妙：性情高远。天机，天性。清妙，指超尘拔俗，与众不同。\n不急之务：闲事，这里指游山玩水。\n是中：这中间。\n无忽：不可疏忽错过。\n因驮黄檗（bò）人往：借驮黄檗的人前往之便（带这封信）。因，趁。黄檗，一种落叶乔木，果实和茎内皮可入药。茎内皮为黄色，也可做染料。\n不一：古人书信结尾常用的套语，不一一详述之意。\n山中人：王维晚年信佛，过着半隐的生活，故自称。', poem_tags = '高中文言文,书信,写景,邀请,友人' WHERE poem_title = '山中与裴秀才迪书' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '千山万岭好像波涛奔赴荆门，王昭君生长的乡村至今留存。\n从紫台一去直通向塞外沙漠，荒郊上独留的青坟对着黄昏。\n只依凭画图识别昭君的容颜，月夜里环佩叮当是昭君归魂。\n千载琵琶一直弹奏胡地音调，曲中抒发的分明的昭君怨恨。', poem_notes = '荆门：山名，在今湖北宜都西北。\n明妃：指王昭君。\n去：离开。\n紫台：汉宫，紫宫，宫廷。\n朔漠：北方的沙漠。\n青冢：指王昭君的坟墓。\n省识：略识。\n春风面：形容王昭君的美貌。', poem_appreciation = '这是组诗《咏怀古迹五首》其中的第三首，诗人借咏昭君村、怀念王昭君来抒写自己的怀抱。诗人有感于王昭君的遭遇。寄予了自己深切的同情，同时表现了昭君对故国的思念与怨恨，并赞美了昭君虽死，魂魄还要归来的精神，从中寄托了诗人自己身世及爱国之情。全诗叙事明确，形象突出，寓意深刻。\n\n　　“群山万壑赴荆门，生长明妃尚有村”。诗的发端两句，首先点出昭君村所在的地方。据《一统志》说：“昭君村，在荆州府归州东北四十里。”其地址，即在今湖北秭归县的香溪。杜甫写这首诗的时候，正住在夔州白帝城。这是三峡西头，地势较高。他站在白帝城高处，东望三峡东口外的荆门山及其附近的昭君村。远隔数百里，本来是望不到的，但他发挥想象力，由近及远，构想出群山万壑随着险急的江流，奔赴荆门山的雄奇壮丽的图景。他就以这个图景作为这首诗的首句，起势很不平凡。杜甫写三峡江流有“众水会涪万，瞿塘争一门”（《长江二首》）的警句，用一个“争”字，突出了三峡水势之惊险。这里则用一个“赴”字突出了三峡山势的雄奇生动。这是一个有趣的对照。但是，诗的下一句，却落到一个小小的昭君村上，颇有点出人意外，因而引起评论家一些不同的议论。明人胡震亨评注的《杜诗通》就说：“群山万壑赴荆门，当似生长英雄起句，此未为合作。”意思是这样气象雄伟的起句，只有用在生长英雄的地方才适当，用在昭君村上是不适合，不协调的。清人吴瞻泰的《杜诗提要》则又是另一种看法。他说：“发端突兀，是七律中第一等起句，谓山水逶迤，钟灵毓秀，始产一明妃。说得窈窕红颜，惊天动地。”意思是说，杜甫正是为了抬高昭君这个“窈窕红颜”，要把她写得“惊天动地”，所以才借高山大川的雄伟气象来烘托她。杨伦《杜诗镜铨》说：“从地灵说入，多少郑重。”也与这个意思相接近。\n\n　　“一去紫台连朔漠，独留青冢向黄昏。”前两句写昭君村，这两句才写到昭君本人。诗人只用这样简短而雄浑有力的两句诗，就写尽了昭君一生的悲剧。从这两句诗的构思和词语说，杜甫大概是借用了南朝江淹《恨赋》里的话：“明妃去时，仰天太息。紫台稍远，关山无极。望君王兮何期，终芜绝兮异域。”但是，仔细地对照，杜甫这两句诗所概括的思想内容的丰富和深刻，大大超过了江淹。清人朱瀚《杜诗解意》说：“‘连’字写出塞之景，‘向’字写思汉之心，笔下有神。”说得很对。但是，有神的并不止这两个字。读者只看上句的紫台和朔漠，自然就会想到离别汉宫、远嫁匈奴的昭君在万里之外，在异国殊俗的环境中，一辈子所过的生活。而下句写昭君死葬塞外，诗人用青冢、黄昏这两个最简单而现成的词汇，尤其具有大巧若拙的艺术匠心。在日常的语言里，黄昏两字都是指时间，而在这里，它似乎更主要是指空间了，它指的是那和无边的大漠连在一起的、笼罩四野的黄昏的天幕，它是那样地大，仿佛能够吞食一切，消化一切，但是，独有一个墓草长青的青冢，它吞食不下，消化不了。这句诗就给人一种天地无情、青冢有恨的无比广大而沉重之感。\n\n　　“画图省识春风面，环佩空归月夜魂。”这是紧接着前两句，更进一步写昭君的身世家国之情。画图句承前第三句，环佩句承前第四句。画图句是说，由于汉元帝的昏庸，对后妃宫人们，只看图画不看人，把她们的命运完全交给画工们来摆布。省识，是略识之意。说元帝从图画里略识昭君，实际上就是根本不识昭君，所以就造成了昭君葬身塞外的悲剧。环佩句是写她怀念故国之心，永远不变，虽骨留青冢，魂灵还会在月夜回到生长她的父母之邦。南宋词人姜夔在他的咏梅名作《疏影》里曾经把杜甫这句诗从形象上进一步丰富提高：“昭君不惯胡沙远，但暗忆江南江北。想佩环月夜归来，化作此花幽独。”这里写昭君想念的是江南江北，而不是长安的汉宫，特别动人。月夜归来的昭君幽灵，经过提炼，化身成为芬芳缟素的梅花，想象更是幽美。\n\n　　“千载琵琶作胡语，分明怨恨曲中论。”这是此诗的结尾，借千载作胡音的琵琶曲调，点明全诗写昭君“怨恨”的主题。据汉代刘熙的《释名》说：“琵琶，本出于胡中马上所鼓也。推手前曰琵，引手却曰琶。”晋代石崇《明君词序》说：“昔公主嫁乌孙，令琵琶马上作乐，以慰其道路之思。其送明君亦必尔也。”琵琶本是从胡人传入中国的乐器，经常弹奏的是胡音胡调的塞外之曲，后来许多人同情昭君，又写了《昭君怨》、《王明君》等琵琶乐曲，于是琵琶和昭君在诗歌里就密切难分了。\n\n　　前面已经反复说明，昭君的“怨恨”尽管也包含着“恨帝始不见遇”的“怨思”，但更主要的，还是一个远嫁异域的女子永远怀念乡土，怀念故土的怨恨忧思，它是千百年中世代积累和巩固起来的对乡土和祖国的最深厚的共同的感情。前面提到，这首诗的开头两句，胡震亨说“群山万壑赴荆门”的诗句只能用于“生长英雄”的地方，用在“生长明妃”的小村子就不适当，正是因为他只从哀叹红颜薄命之类的狭隘感情来理解昭君，没有体会昭君怨恨之情的分量。吴瞻泰意识到杜甫要把昭君写得“惊天动地”，杨伦体会到杜甫下笔“郑重”的态度，但也未把昭君何以能“惊天动地”，何以值得“郑重”的道理说透。昭君虽然是一个女子，但她身行万里，青冢留千秋，心与祖国同在，名随诗乐长存，诗人就是要用“群山万壑赴荆门”这样壮丽的诗句来郑重地写她。\n\n　　杜甫的诗题叫《咏怀古迹》，他在写昭君的怨恨之情时，是寄托了他的身世家国之情的。杜甫当时正“飘泊西南天地间”，远离故乡，处境和昭君相似。虽然他在夔州，距故乡洛阳偃师一带不像昭君出塞那样远隔万里，但是“书信中原阔，干戈北斗深”，洛阳对他来说，仍然是可望不可即的地方。他寓居在昭君的故乡，正好借昭君当年想念故土、夜月魂归的形象，寄托他自己想念故乡的心情。\n\n　　清人李子德说：“只叙明妃，始终无一语涉议论，而意无不包。后来诸家，总不能及。”这个评语说出了这首诗最重要的艺术特色，它自始至终，全从形象落笔，不着半句抽象的议论，而“独留青冢向黄昏”、“环佩空归月夜魂”的昭君的悲剧形象，却在读者的心上留下了难以磨灭的深刻印象。', poem_tags = '唐诗三百首,怀古,思乡' WHERE poem_title = '咏怀古迹五首·其三' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '唐玄宗开元二十六年，有个随从主帅出塞回来的人，写了《燕歌行》诗一首给我看。我感慨于边疆战守的事，因而写了这首《燕歌行》应和他。\n\n唐朝边境举烟火狼烟东北起尘土，唐朝将军辞家去欲破残忍之边贼。\n战士们本来在战场上就所向无敌，皇帝又特别给予他们丰厚的赏赐。\n锣声响彻重鼓棰声威齐出山海关，旌旗迎风又逶迤猎猎碣石之山间。\n校尉紧急传羽书飞奔浩瀚之沙海，匈奴单于举猎火光照已到我狼山。\n山河荒芜多萧条满目凄凉到边土，胡人骑兵仗威力兵器声里夹风雨。\n战士拼斗军阵前半数死去半生还，美人却在营帐中还是歌来还是舞！\n时值深秋大沙漠塞外百草尽凋枯，孤城一片映落日战卒越斗越稀少。\n身受皇家深恩义常思报国轻寇敌，边塞之地尽力量尚未破除匈奴围。\n身穿铁甲守边远疆场辛勤已长久，珠泪纷落挂双目丈夫远去独啼哭。\n少妇孤单住城南泪下凄伤欲断肠，远征军人驻蓟北依空仰望频回头。\n边境飘渺多遥远怎可轻易来奔赴，绝远之地尽苍茫更是人烟何所有。\n杀气春夏秋三季腾起阵前似乌云，一夜寒风声声里如泣更声惊耳鼓。\n互看白刃乱飞舞夹杂鲜血纷飞，从来死节为报国难道还求著功勋？\n你没看见拼杀在沙场战斗多惨苦，现在还在思念有勇有谋的李将军。', poem_notes = '燕歌行：乐府旧题。诗前有作者原序：“开元二十六年，客有从御史大夫张公出塞而还者，作《燕歌行》以示适。感征戍之事，因而和焉。”张公，指幽州节度使张守珪，曾拜辅国大将军、右羽林大将军，兼御史大夫。一般以为本诗所讽刺的是开元二十六年，张守珪部将赵堪等矫命，逼平卢军使击契丹余部，先胜后败，守珪隐败状而妄奏功。这种看法并不很准确。\n汉家：汉朝，唐人诗中经常借汉说唐。\n烟尘：代指战争。\n横行：任意驰走，无所阻挡。\n元戎：军事元帅。\n非常赐颜色：超过平常的厚赐礼遇。\n摐：撞击。\n金：指钲一类铜制打击乐器。\n伐：敲击。\n榆关：山海关，通往东北的要隘。\n旌旆：旌是竿头饰羽的旗。旆是末端状如燕尾的旗。这里都是泛指各种旗帜。\n逶迤：蜿蜒不绝的样子。\n碣石；山名。\n校尉；次于将军的武官。\n羽书；（插有鸟羽的，军用的）紧急文书。\n瀚海；沙漠。这里指内蒙古东北西拉木伦河上游一带的沙漠。\n单于；匈奴首领称号，也泛指北方少数民族首领。\n猎火：打猎时点燃的火光。古代游牧民族出征前，常举行大规模校猎，作为军事性的演习。\n狼山：又称狼居胥山，在今内蒙古自治区克什克腾旗西北。一说狼山又名郎山，在今河北易县境内。此处“瀚海”、“狼山”等地名，未必是实指。\n极：穷尽。\n凭陵：仗势侵凌。\n杂风雨：形容敌人来势凶猛，如风雨交加。一说，敌人乘风雨交加时冲过来。\n半生死：意思是半生半死，伤亡惨重。\n腓（一作衰）：指枯萎。隋虞世基《陇头吟》：“穷求塞草腓，塞外胡尘飞”\n斗兵稀：作战的士兵越打越少了。\n身当恩遇：指主将受朝廷的恩宠厚遇。\n玉箸：白色的筷子（玉筷），比喻思妇的泪水如注。\n城南：京城长安的住宅区在城南。\n蓟北：唐蓟州在今天津市以北一带，此处当泛指唐朝东北边地。\n边庭飘摇：形容边塞战场动荡不安。庭，一作“风”。飘摇，一作“飘飘”，随风飘荡的样子。\n度：越过相隔的路程，回归。\n绝域：更遥远的边陲。\n更何有：更加荒凉不毛。\n三时：指晨、午、晚，即从早到夜（历时很久。三，不表确数。）。\n刁斗：军中夜里巡更敲击报时用的、煮饭时用的，两用铜器。\n阵云：战场上象征杀气的云，即战云。\n一夜：即整夜，彻夜。\n血：一作“雪”\n死节：指为国捐躯。节，气节。\n岂顾勋：难道还顾及自己的功勋。\n李将军：指汉朝李广，他能捍御强敌，爱抚士卒，匈奴称他为汉之飞将军。', poem_appreciation = '《燕歌行》是高适的代表作，不仅是高适的“第一大篇”（近人赵熙评语），而且是整个唐代边塞诗中的杰作，千古传诵，良非偶然。\n\n　　诗意在慨叹征战之苦，谴责将领骄傲轻敌，荒淫失职，造成战争失利，使战士受到极大痛苦和牺牲，反映了士兵与将领之间苦乐不同，庄严与荒淫迥异的现实。诗虽叙写边战，但重点不在民族矛盾，而是讽刺和愤恨不恤战士的将领。同时，也写出了为国御敌之辛勤。主题仍是雄健激越，慷慨悲壮。\n\n　　全诗以非常浓缩的笔墨，写了一个战役的全过程：第一段八句写出师，第二段八句写战败，第三段八句写被围，第四段四句写死斗的结局。各段之间，脉理绵密。\n\n　　诗的发端两句便指明了战争的方位和性质，见得是指陈时事，有感而发。“男儿本自重横行，天子非常赐颜色”，貌似揄扬汉将去国时的威武荣耀，实则已隐含讥讽，预伏下文。樊哙在吕后面前说：“臣愿得十万众，横行匈奴中”，季布便斥责他当面欺君该斩。（见《史记·季布传》）所以，这“横行”的由来，就意味着恃勇轻敌。紧接着描写行军：“摐金伐鼓下榆关，旌旆逶迤碣石间。”透过这金鼓震天、大摇大摆前进的场面，可以揣知将军临战前不可一世的骄态，也为下文反衬。战端一启，“校尉羽书飞瀚海”，一个“飞”字警告了军情危急：“单于猎火照狼山”，犹如“看明王宵猎，骑火一川明，笳鼓悲鸣，遣人惊！”（张孝祥《六州歌头》）不意“残贼”乃有如此威势。从辞家去国到榆关、碣石，更到瀚海、狼山，八句诗概括了出征的历程，逐步推进，气氛也从宽缓渐入紧张。\n\n　　第二段写战斗危急而失利。落笔便是“山川萧条极边土”，展现开阔而无险可凭的地带，带出一片肃杀的气氛。“胡骑”迅急剽悍，象狂风暴雨，卷地而来。汉军奋力迎敌，杀得昏天黑地，不辨死生。然而，就在此时此刻，那些将军们却远离阵地寻欢作乐：“美人帐下犹歌舞！”这样严酷的事实对比，有力地揭露了汉军中将军和兵士的矛盾，暗示了必败的原因。所以紧接着就写力竭兵稀，重围难解，孤城落日，衰草连天，有着鲜明的边塞特点的阴惨景色，烘托出残兵败卒心境的凄凉。“身当恩遇恒轻敌，力尽关山未解围”。回应上文，汉将“横行”的豪气业已灰飞烟灭，他的罪责也确定无疑了。\n\n　　第三段写士兵的痛苦，实是对汉将更深的谴责。应该看到，这里并不是游离战争进程的泛写，而是处在被围困的险境中的士兵心情的写照。“铁衣远戍辛勤久”以下三联，一句征夫，一句征夫悬念中的思妇，错综相对，离别之苦，逐步加深。城南少妇，日夜悲愁，但是“边庭飘飖那可度？”蓟北征人，徒然回首，毕竟“绝域苍茫更何有！”相去万里，永无见期，“人生到此，天道宁论！”更那堪白天所见，只是“杀气三时作阵云”；晚上所闻，惟有“寒声一夜传刁斗”，如此危急的绝境，真是死在眉睫之间，不由人不想到把他们推到这绝境的究竟是谁呢？这是深化主题的不可缺少的一段。\n\n　　最后四句总束全篇，淋漓悲壮，感慨无穷。“相看白刃血纷纷，死节从来岂顾勋”，最后士兵们与敌人短兵相接，浴血奋战，那种视死如归的精神，岂是为了取得个人的功勋！他们是何等质朴、善良，何等勇敢，然而又是何等可悲呵！\n\n　　诗人的感情包含着悲悯和礼赞，而“岂顾勋”则是有力地讥刺了轻开边衅，冒进贪功的汉将。最末二句，诗人深为感慨道：“君不见沙场征战苦，至今犹忆李将军！”八九百年前威镇北边的飞将军李广，处处爱护士卒，使士卒“咸乐为之死”。这与那些骄横的将军形成多么鲜明的对比。诗人提出李将军，意义尤为深广。从汉到唐，悠悠千载，边塞战争何计其数，驱士兵如鸡犬的将帅数不胜数，备历艰苦而埋尸异域的士兵，更何止千千万万！可是，千百年来只有一个李广，不能不教人苦苦地追念他。杜甫赞美高适、岑参的诗：“意惬关飞动，篇终接混茫。”（《寄高使君岑长史三十韵》）此诗以李广终篇，意境更为雄浑而深远。\n\n　　全诗气势畅达，笔力矫健，经过惨淡经营而至于浑化无迹。气氛悲壮淋漓，主意深刻含蓄。“山川萧条极边土，胡骑凭陵杂风雨”，“大漠穷秋塞草腓，孤城落日斗兵稀”，诗人着意暗示和渲染悲剧的场面，以凄凉的惨状，揭露好大喜功的将军们的罪责。尤可注意的是，诗人在激烈的战争进程中，描写了士兵们复杂变化的内心活动，凄恻动人，深化了主题。全诗处处隐伏着鲜明的对比。从贯串全篇的描写来看，士兵的效命死节与汉将的怙宠贪功，士兵辛苦久战、室家分离与汉将临战失职，纵情声色，都是鲜明的对比。而结尾提出李广，则又是古今对比。全篇“战士军前半死生，美人帐下犹歌舞”，“二句最为沈至”（《唐宋诗举要》引吴汝纶评语），这种对比，矛头所指十分明显，因而大大加强了讽刺的力量。\n\n　　《燕歌行》是唐人七言歌行中运用律句很典型的一篇。全诗用韵依次为入声“职”部、平声“删”部、上声“麌”部、平声“微”部、上声“有”部、平声“文”部，恰好是平仄相间，抑扬有节。除结尾两句外，押平韵的句子，对偶句自不待言，非对偶句也符合律句的平仄，如“摐金伐鼓下榆关，旌旆逶迤碍石间”；押仄韵的句子，对偶的上下句平仄相对也是很严整的，如“杀气三时作阵云，寒声一夜传刁斗。”这样的音调之美，正是“金戈铁马之声，有玉磐鸣球之节”（《唐风定》卷九邢昉评语）。', poem_tags = '唐诗三百首,边塞,将士,战争,生活' WHERE poem_title = '燕歌行' AND poem_author = '高适';
UPDATE edu_poem SET poem_translation = '跋涉在道路崎岖又遥远的三巴路上，客居在万里之外的危险地方。四面群山下，残雪映寒夜，对烛夜坐，我这他乡之客。因离亲人越来越远，反而与书童和仆人渐渐亲近。真难以忍受在漂泊中度过除夕夜，到明天岁月更新就是新的一年。', poem_notes = '迢递：遥远貌。三巴：指巴郡、巴东、巴西，在今四川东部。\n羁危：在艰险中羁旅漂泊。\n“烛”：一作“独”。人：一作“春”。\n转于：反与。僮仆：随行小奴。\n飘：一作“漂”。\n明日：指新年。岁华：岁月，年华。', poem_appreciation = '这首诗是诗人客居他地、除夕怀乡之作。诗人身在异乡，深感羁旅艰危。三、四两句写凄清的除夕夜景，渲染诗人落寞情怀。五、六两句写远离亲人，连僮仆也感到亲切，更表达出思乡之切。最后两句寄希望于新年，飘泊之感更烈，自然真切。全诗用语朴实，抒情细腻。离愁乡思，发泄无余。其中“渐与骨肉远，转于僮仆亲”一句，从王维《宿郑州》“他乡绝俦侣，孤案亲僮仆”化出。本诗作为“万里身”、“异乡人”的深绘，更加悲恻感人。　\n\n　　崔《除夜有感》：“迢递三巴路，羁危万里身。乱山残雪夜，孤烛异乡春。渐与骨肉远，转于僮仆亲。那堪正漂泊，明日岁华新？”读之如凉雨凄风飒然而至，此所谓真诗，正不得以晚唐概薄之。按崔此诗尚胜戴叔伦作。戴之“一年将尽夜，万里未归人。寥落悲前事，支离笑此身，”已自惨然，此尤觉刻肌砭骨。崔长短律皆以一气斡旋，有若口谈，真得张水部之深者。如“并闻寒雨多因夜，不得乡书又到秋”、“正逢摇落仍须别，不待登临已合悲”，皆本色语佳者。至《春夕》一篇，又不待言。', poem_tags = '唐诗三百首,春节,羁旅,思乡' WHERE poem_title = '除夜 / 巴山道中除夜书怀' AND poem_author = '崔涂';
UPDATE edu_poem SET poem_translation = '玉石砌的台阶上生起了露水，深夜独立很久，露水浸湿了罗袜。回房放下水晶帘，仍然隔着帘子望着玲珑的秋月。', poem_notes = '罗袜：丝织的袜子。 　　\n却下：放下。', poem_appreciation = '李白的这首宫怨诗，虽曲名标有“怨”字，诗作中却只是背面敷粉，全不见“怨”字。无言独立阶砌，以致冰凉的露水浸湿罗袜；以见夜色之浓，伫待之久，怨情之深。“罗袜”，表现出人的仪态、身份，有人有神。夜凉露重，罗袜知寒，不说人而已见人的幽怨如诉。二字似写实，实用曹植“凌波微步，罗袜生尘”意境。\n\n　　怨深，夜深，主人公不禁幽独之苦，由帘外到帘内，拉下帘幕之后，反又不忍使明月孤寂。似月怜人，似人怜月；而如果人不伴月，则又没有什么事物可以伴人。月无言，人也无言。但读者却深知人有无限言语，月也解此无限言语，而写来却只是一味望月。这正是“不怨之怨”，所以才显得愁怨之深。\n\n　　“却下”二字，以虚字传神，最为诗家秘传。此处一转折，似断实连；好像要一笔荡开，推却愁怨，实际上则是经此一转，字少情多，直入幽微。“却下”一词，看似无意下帘，而其中却有无限幽怨。本来主人公由于夜深、怨深，无可奈何而回到室内。入室之后，却又怕隔窗的明月照此室内幽独，因而拉下帘幕。帘幕放下来了，却更难消受这个凄苦无眠之夜，在更加无可奈何之中，却更要去隔帘望月。此时主人公的忧思不断在徘徊，直如李清照“寻寻觅觅、冷冷清清、凄凄惨惨戚戚”的那种纷至沓来，这样的情思，作者用“却下”二字表达出来。“却”字直贯下句，“却下水晶帘”，“却去望秋月”，在这两个动作之间，有许多愁思转折反复，诗句字少情多，以虚字传神。中国古代诗艺中有“空谷传音”的手法，这是如此。“玲珑”二字，看似不经意的笔调，实际上极见功力。以月的玲珑，衬托人的幽怨，从反处着笔，全胜正面涂抹。\n\n　　诗中不见人物姿容与心理状态，而作者似也无动于衷，只以人物行动来表达含义，引读者步入诗情的最幽微之处，所以能不落言筌，为读者保留想象的余地，使诗情无限辽远，无限幽深。所以，这首诗体现出了诗家“不著一字，尽得风流”的真意。以叙人事的笔调来抒情，这很常见，也很容易；以抒情的笔调来写人，这很少见，也很难。\n\n　　契诃夫有“矜持”说，写诗的人也常有所谓“距离”说，两者非常近似，应合为一种说法。作者应与所写对象保持一定距离，并保持一定的“矜持”与冷静。这样一来，作品才没有声嘶力竭之弊，而有幽邃深远之美，写难状之情与难言之隐，使漫天的诗思充满全诗，却又在字句间捉摸不到。这首《玉阶怨》含思婉转，余韵如缕，正是这样的佳作。', poem_tags = '唐诗三百首,宫怨,孤独' WHERE poem_title = '玉阶怨' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '虽然住的屋子简陋但知识却没有变少，我还是与往常一样，尽管外面已经战乱纷纷。\n故乡虽然在打仗，可是弟侄还在接受儒家思想的教化。\n窗外竹子的影子还在书桌上摇摆，砚台中的墨汁好像发出了野外泉水的叮咚声。\n年轻时候的努力是有益终身的大事，对着匆匆逝去的光阴，不要丝毫放松自己的努力。', poem_notes = '何事：为什么。\n居穷道不穷：处于穷困之境仍要注重修养。\n乱时：战乱时期。静时：和平时期。\n家山：家乡的山，这里代指故乡。\n干戈：干和戈本是古代打仗时常用的两种武器，这里代指战争。\n礼乐（yuè）：这里指儒家思想。礼，泛指奴隶社会或封建社会贵族等级制的社会规范和道德体系。乐，音乐。儒家很重视音乐的教化作用。\n案：几案。\n惰：懈怠。', poem_tags = '惜时,勉励,哲理' WHERE poem_title = '题弟侄书堂' AND poem_author = '杜荀鹤';
UPDATE edu_poem SET poem_translation = '登上高楼凭栏极目，金陵的景象正是一派晚秋，天气刚刚开始索肃。千里奔流的长江澄沏得好像一条白练，青翠的山峰俊伟峭拔犹如一束束的箭簇。江上的小船张满了帆迅疾驶向夕阳里，岸旁迎着西风飘/拂的是抖擞的酒旗斜出直矗。彩色缤纷的画船出没在云烟稀淡，江中洲上的白鹭时而停歇时而飞起，这清丽的景色就是用最美的图画也难把它画足。\n回想往昔，奢华淫逸的生活无休止地互相竞逐，感叹“门外韩擒虎，楼头张丽华”的亡国悲恨接连相续。千古以来凭栏遥望，映入眼帘的景色就是如此，可不要感慨历史上的得失荣辱。六朝的风云变化全都消逝随着流水，只有那郊外的寒冷烟雾和衰萎的野草还凝聚着一片苍绿。直到如今的商女，还不知亡国的悲恨，时时放声歌唱《后庭》遗曲。', poem_notes = '登临送目：登山临水，举目望远。\n故国：旧时的都城，指金陵。\n千里澄江似练：形容长江像一匹长长的白绢。语出谢眺《晚登三山还望京邑》：“余霞散成绮，澄江静如练。”澄江，清澈的长江。练，白色的绢。\n如簇：这里指群峰好像丛聚在一起。簇，丛聚。\n去棹（zhào）：往来的船只。棹，划船的一种工具，形似桨，也可引申为船。\n星河鹭（lù）起：白鹭从水中沙洲上飞起。长江中有白鹭洲（在今南京水西门外）。星河，银河，这里指长江。\n画图难足：用图画也难以完美地表现它。\n豪华竞逐：（六朝的达官贵人）争着过豪华的生活。竞逐：竞相仿效追逐。\n门外楼头：指南朝陈亡国惨剧。语出杜牧《台城曲》：“门外韩擒虎，楼头张丽华。”韩擒虎是隋朝开国大将，他已带兵来到金陵朱雀门（南门）外，陈后主尚与他的宠妃张丽华于结绮阁上寻欢作乐。\n悲恨相续：指亡国悲剧连续发生。\n凭高：登高。这是说作者登上高处远望。\n漫嗟荣辱：空叹什么荣耀耻辱。这是作者的感叹。\n六朝：指三国吴、东晋、南朝宋、齐、梁、陈六个朝代。它们都建都金陵。\n商女：歌女。\n《后庭》遗曲：指歌曲《玉树后庭花》，传为陈后主所作。杜牧《泊秦淮》：“商女不知亡国恨，隔江犹唱《后庭花》”，后人认为是亡国之音。', poem_appreciation = '这是一首金陵怀古之词。上片写金陵之景，下片写怀古之情。一开头，用“登临送目”四字领起，表明以下所写为登高所见。映入眼帘的是晚秋季节特有的白练般清澈的江水和连锦不断翠绿的山峰。船帆飘动，酒旗迎风，云掩彩舟，白鹭腾空。这图画难述其美的江天景色使诗人极为赞赏也极为陶醉，同时也引起他深深的思考。换头之后写怀古：在金陵建都的六朝帝王，争奇斗胜地穷奢极欲，演出一幕幕触目惊心的亡国悲剧。千百年来，人们只是枉自嗟叹六朝的兴亡故事。但空叹兴亡，又有何益？诗人在这里表现了政治家深邃的思想和雄伟的气概。不仅批判了六朝亡国之君的荒淫误国，也批判了吊古者的空叹兴亡。六朝的往事都随水逝去，空余寒烟芳草。可悲的是，有些人如商女一般，不顾国家兴亡，还沉溺于享乐，吟唱着《后庭花》这样的亡国之曲。作为政治家的王安石反对“谩嗟”六朝兴废，在北宋这积贫积弱的现实面前，要汲取历史教训，从政治上进行改革，免致奢华靡费导致国力衰竭，重蹈六朝覆辙。\n\n　　本词以壮丽的山河为背景，历述古今盛衰之感，立意高远，笔力峭劲，体气刚健，豪气逼人。多处化用前人诗句，不着痕迹，显示了作者深厚的功底。\n\n　　此词抒发金陵怀古人之情，为作者别创一格、非同凡响的杰作，大约写于作者再次罢相、出知江宁府之时。词中流露出王安石失意无聊之时移情自然风光的情怀。\n\n　　全词开门见山，写作者南朝古都金陵胜地，于一个深秋的傍晚，临江揽胜，凭高吊古。他虽以登高望远为主题，却是以故国晚秋为眼目。“正”、“初”、“肃”三个字逐步将其主旨点醒。\n\n　　以下两句，借六朝谢家名句“解道‘澄江净如练’，令人长忆谢玄晖”之意，点化如同已出。即一个“似练”，一个“如簇”，形胜已赫然而出。然后专写江色，纵目一望，只见斜阳映照之下，数不清的帆风樯影，交错于闪闪江波之上。细看凝眸处，却又见西风紧处，那酒肆青旗高高挑起，因风飘拂。帆樯为广景，酒旗为细景，而词人之意以风物为导引，而以人事为着落。一个“背”字，一个“矗”字，用得极妙，把个江边景致写得栩栩如生，似有生命其中。\n\n　　写景至此，全是白描，下面有所变化。“彩舟”、“星河”两句一联，顿增明丽之色。然而词拍已到上片歇处，故而笔亦就此敛住，以“画图难足”一句，抒赞美嗟赏之怀，颇有大家风范。“彩舟云淡”，写日落之江天：“星河鹭起”，状夕夜之洲渚。\n\n　　下片另换一幅笔墨，感叹六朝皆以荒淫而相继亡覆的史实。写的是悲恨荣辱，空贻后人凭吊之资；往事无痕，唯见秋草凄碧，触目惊心而已。“门外楼头”，用杜牧《台城曲》句加以点染，亦简净有力。\n\n　　词至结语，更为奇妙，词人写道：时至今日，六朝已远，但其遗曲，往往犹似可闻。此处用典。“商女不知亡国恨，隔江犹唱《后庭花》！”此唐贤小杜于“烟笼寒水月笼沙，夜泊秦淮近酒家”时所吟之名句，词人复加运用，便觉尺幅千里，饶有有余不尽之情致，而嗟叹之意，千古弥永。', poem_tags = '宋词三百首,登高,写景,咏史怀古' WHERE poem_title = '桂枝香·金陵怀古' AND poem_author = '王安石';
UPDATE edu_poem SET poem_translation = '人生在世，到这里、又到那里，偶然留下一些痕迹，你觉得像是什么？我看真像随处乱飞的鸿鹄，偶然在某处的雪地上落一落脚一样。\n它在这块雪地上留下一些爪印，正是偶然的事，因为鸿鹄的飞东飞西根本就没有一定。\n老和尚奉闲已经去世，他留下的只有一座藏骨灰的新塔，我们也没有机会再到那儿去看看当年题过字的破壁了。老和尚的骨灰塔和我们的题壁，是不是同飞鸿在雪地上偶然留下的爪印差不多呢！\n你还记得当时往渑池的崎岖旅程吗？路又远，人又疲劳，驴子也累得直叫。', poem_notes = '此诗作于苏轼经渑池（今属河南），忆及苏辙曾有《怀渑池寄子瞻兄》一诗，从而和之。子由：苏轼弟苏辙字子由。渑（miǎn）池：今河南渑池县。这首诗是和苏辙《怀渑池寄子瞻兄》而作。\n“人生”句：此是和作，苏轼依苏辙原作中提到的雪泥引发出人生之感。查慎行、冯应榴以为用禅语，王文诰已驳其非，实为精警的譬喻，故钱钟书《宋诗选注》指出：“雪泥鸿爪”，“后来变为成语”。\n老僧：即指奉闲。\n坏壁：指奉闲僧舍。嘉祐元年（1056年），苏轼与苏辙赴京应举途中曾寄宿奉贤僧舍并题诗僧壁。\n蹇（jiǎn）驴：腿脚不灵便的驴子。蹇，跛脚。', poem_appreciation = '苏辙原诗的基调是怀旧，因为他十九岁时曾被任命为渑池县的主簿(由于考中进士，未到任)，嘉祐元年和兄轼随父同往京城应试，又经过这里，有访僧留题之事。所以在诗里写道：“曾为县吏民知否？旧宿僧房壁共题。”他觉得，这些经历真是充满了偶然。如果说与渑池没有缘份，为何总是与它发生关联？如果说与渑池有缘份，为何又无法驻足时间稍长些？这就是苏辙诗中的感慨。而由这些感慨，苏轼更进一步对人生发表了一段议论。这就是诗的前四句。在苏轼看来，不仅具体的生活行无定踪，整个人生也充满了不可知，就像鸿雁在飞行过程中，偶一驻足雪上，留下印迹，而鸿飞雪化，一切又都不复存在。那么，在冥冥中到底有没有一种力量在支配着这种行为呢？如果说，人生是由无数个坐标点所组成的，那么，这些坐标点有没有规律可循？青年苏轼对人生发出了这样的疑问和感喟。但是，人生有着不可知性，并不意味着人生是盲目的；过去的东西虽已消逝，但并不意味着它不曾存在。就拿崤山道上，骑着蹇驴，在艰难崎岖的山路上颠簸的经历来说，岂不就是一种历练，一种经验，一种人生的财富？所以，人生虽然无常，但不应该放弃努力；事物虽多具有偶然性，但不应该放弃对必然性的寻求。事实上，若不经过一番艰难困苦，又怎能考取进士，实现抱负呢？这就是苏轼：既深究人生底蕴，又充满乐观向上，他的整个人生观在此得到了缩微的展示。\n\n　　这首诗的理趣主要体现在前四句上，“雪泥鸿爪”也作为一个成语被后世广泛传诵。但从写作手法上来看，也颇有特色。纪昀曾评道：“前四句单行入律，唐人旧格；而意境恣逸，则东坡之本色。”所谓“唐人旧格”，大致上指崔颢《黄鹤楼》：“昔人已乘黄鹤去，此地空余黄鹤楼。黄鹤一去不复返，白云千载空悠悠。……”作为七律，三、四两句本该对仗，此却一意直下，不作讲求。苏轼的“泥上”二句，也可算是对仗，但其文意承上直说，本身也带有承接关系，所以是“单行入律”。“意境恣逸”的意思，就是不仅字面上飘逸，行文中有气势，而且内涵丰富，耐人寻味，不求工而自工。这正是苏轼的“本色”。', poem_tags = '古诗三百首,人生,感伤' WHERE poem_title = '和子由渑池怀旧' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '一轮缓缓移动的秋月洒下万里金波，就像那刚磨亮的铜镜又飞上了天廓。我举起酒杯问那月中的嫦娥：怎么办呢？白发日增，好像故意欺负我。\n我要乘风飞上万里长空，俯视祖国的大好山河。还要砍去月中摇曳的桂树枝柯，人们说，这将使月亮洒下人间的光辉更多。', poem_notes = '太常引：词牌名。\n吕叔潜：名大虬，生平事迹不详，似为作者声气相应的朋友。\n金波：形容月光浮动，因亦指月光。《汉书》卷二十二《礼乐志》：“月穆穆以金波”。颜师古注：“言月光穆穆，若金之波流也”。苏轼《洞仙歌》词：“金波淡，玉绳低转”。\n飞镜：飞天之明镜，指月亮。甘子布《光赋》：“银河波曀，金颸送清，孤圆上魄，飞镜流明”。李白《把酒问月》诗：“皎如飞镜临丹阙，绿烟灭尽清辉发。”\n姮娥：即嫦娥，传说中的月中仙女。《淮南子·览冥训》：“羿请不死之药于西王母，姮娥窃以奔月”。高诱注说，她后来“得仙，奔入月中为月精”。\n被白发欺人奈何：化用薛能《春日使府寓怀》“青春背我堂堂去，白发欺人故故生”诗意。\n“斫去”三句：化用杜甫《一百五十日夜对月》诗中“斫却月中桂，清光应更多”句意。斫：砍。桂：桂树。婆娑：树影摇曳的样子。《酉阳杂俎》载：“月桂高五百丈，下有一人常斫之，树创遂合，人姓吴、名刚，西河人，学仙有过，谪令伐树。”', poem_appreciation = '众所周知，辛弃疾是宋代豪放派词作家的杰出代表。他的这首《太常引》，运用浪漫主义的艺术手法，通过古代的神话传说，强烈地表达了自己反对妥协投降、立志收复中原失土的政治理想。从这首词的内容看，此词可能是公元1174年（宋孝宗淳熙元年），作者在建康（今江苏南京）任江东安扶司参议官任上所作。这时作者南归已整整十二年了。为了收复中原，作者曾多次上书，力主抗金，收复中原。但他的建议根本不被人理睬，在阴暗的政治环境中，词人只能以诗词来抒发自己的心愿。\n\n　　这首词的上片，词人巧妙地运用神话传说构成一种超现实的艺术境界，以寄托自己的理想与情怀。“一轮秋影转金波。飞镜又重磨。把酒问姮娥：被白发欺人奈何？”作者在中秋之夜，对月抒怀，很自然地想到与月有关的神话传说：吃了不死之药飞入月宫的嫦娥，以及月中高五百丈的桂树。词人运用这两则有关月亮的神话传说，借以表达自己的政治理想和阴暗的政治现实的矛盾。辛弃疾一生以恢复中原为己任，但残酷的现实使他的理想不能实现。想到功业无成、白发已多，作者怎能不对着皎洁的月光，迸发出摧心裂肝的一问：“被白发欺人奈何？”这一句有力地展示了英雄怀才不遇的内心矛盾。\n\n　　词的下片，作者又运用想象的翅膀，直入月宫，并幻想砍去遮住月光的桂树。想象更加离奇，更加远离尘世，但却更直接、强烈地表现了词人的现实理想与为实现理想的坚强意志，更鲜明地揭示了词的主旨。\n\n　　作者这里所说的挡住月光的“桂婆娑”，实际是指带给人民黑暗的婆娑桂影，它不仅包括南宋朝廷内外的投降势力，也包括了金人的势力。因为由被金人统治下的北方南归的辛弃疾，不可能不深切地怀想被金人统治、压迫的家乡人民。进一步说，这首词还可以理想为一种更广泛的象征意义，即扫荡黑暗，把光明带给人间。这一巨大的意义，是词人利用神话材料，借助于想象和逻辑推断所塑造的形象来实现的。\n\n　　总之，辛弃疾的这首词，无论是从它的艺术境界，还是从它的气象和风格看，他都与运用神话传说的浪漫主义手法有着密切的联系。作者通过超现实的艺术境界，来解决现实的苦闷与实现理想的浪漫主义手法的特点，是一首富于浓厚浪漫主义色彩的优秀词章。', poem_tags = '宋词三百首,中秋节,神话,咏物,月亮,抒怀' WHERE poem_title = '太常引·建康中秋夜为吕叔潜赋' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '从前，郑武公在申国娶了一妻子，叫武姜，她生下庄公和共叔段。庄公出生时脚先出来，武姜受到惊吓，因此给他取名叫“寤生”，所以很厌恶他。武姜偏爱共叔段，想立共叔段为世子，多次向武公请求，武公都不答应。\n\n　　到庄公即位的时候，武姜就替共叔段请求分封到制邑去。庄公说：“制邑是个险要的地方，从前虢叔就死在那里，若是封给其它城邑，我都可以照吩咐办。”武姜便请求封给太叔京邑，庄公答应了，让他住在那里，称他为京城太叔。大夫祭仲说：“分封的都城如果城墙超过三百方丈长，那就会成为国家的祸害。先王的制度规定，国内最大的城邑不能超过国都的三分之一，中等的不得超过它的五分之一，小的不能超过它的九分之一。京邑的城墙不合法度，非法制所许，恐怕对您有所不利。”庄公说：“姜氏想要这样，我怎能躲开这种祸害呢？”祭仲回答说：“姜氏哪有满足的时候！不如及早处置，别让祸根滋长蔓延，一滋长蔓延就难办了。蔓延开来的野草还不能铲除干净，何况是您受宠爱的弟弟呢？”庄公说：“多做不义的事情，必定会自己垮台，你姑且等着瞧吧。\n\n　　过了不久，太叔段使原来属于郑国的西边和北边的边邑也背叛归为自己。公子吕说：“国家不能有两个国君，现在您打算怎么办？您如果打算把郑国交给太叔，那么我就去服待他；如果不给，那么就请除掉他，不要使百姓们产生疑虑。”庄公说：“不用除掉他，他自己将要遭到灾祸的。”太叔又把两属的边邑改为自己统辖的地方，一直扩展到廪延。公子吕说：“可以行动了！土地扩大了，他将得到老百姓的拥护。”庄公说：“对君主不义，对兄长不亲，土地虽然扩大了，他也会垮台的。”\n\n　　太叔修治城廓，聚集百姓，修整盔甲武器，准备好兵马战车，将要偷袭郑国。武姜打算开城门作内应。庄公打听到公叔段偷袭的时候，说：“可以出击了！”命令子封率领车二百乘，去讨伐京邑。京邑的人民背叛共叔段，共叔段于是逃到鄢城。庄公又追到鄢城讨伐他。五月二十三日，太叔段逃到共国。\n\n　　《春秋》记载道：“郑伯克段于鄢。”意思是说共叔段不遵守做弟弟的本分，所以不说他是庄公的弟弟；兄弟俩如同两个国君一样争斗，所以用“克”字；称庄公为“郑伯”，是讥讽他对弟弟失教；赶走共叔段是出于郑庄公的本意，不写共叔段自动出奔，是史官下笔有为难之处。\n\n　　庄公就把武姜安置在城颍，并且发誓说：“不到黄泉（不到死后埋在地下），不再见面！”过了些时候，庄公又后悔了。有个叫颍考叔的，是颍谷管理疆界的官吏，听到这件事，就把贡品献给郑庄公。庄公赐给他饭食。颍考叔在吃饭的时候，把肉留着。庄公问他为什么这样。颍考叔答道：“小人有个老娘，我吃的东西她都尝过，只是从未尝过君王的肉羹，请让我带回去送给她吃。”庄公说：“你有个老娘可以孝敬，唉，唯独我就没有！”颍考叔说：“请问您这是什么意思？”庄公把原因告诉了他，还告诉他后悔的心情。颍考叔答道：“您有什么担心的！只要挖一条地道，挖出了泉水，从地道中相见，谁还说您违背了誓言呢？”庄公依了他的话。庄公走进地道去见武姜，赋诗道：“大隧之中相见啊，多么和乐相得啊！”武姜走出地道，赋诗道：“大隧之外相见啊，多么舒畅快乐啊！”从此，他们恢复了从前的母子关系。\n\n　　君子说：“颍考叔是位真正的孝子，他不仅孝顺自己的母亲，而且把这种孝心推广到郑伯身上。《诗经·大雅·既醉》篇说：‘孝子不断地推行孝道，永远能感化你的同类。’大概就是对颍考叔这类纯孝而说的吧？”', poem_notes = '初：当初，这是回述往事时的说法。\n郑武公：名掘突，郑桓公的儿子，郑国第二代君主。\n娶于申：从申国娶妻。申，春秋时国名，姜姓，河南省南阳市北。\n曰武姜：叫武姜。武姜，郑武公之妻，“姜”是她娘家的姓，“武”是她丈夫武公的谥号。\n共（gōng）叔段：郑庄公的弟弟，名段。他在兄弟之中年岁小，因此称“叔段”。\n寤（wù）生：难产的一种，胎儿的脚先生出来。寤，通“啎”，逆，倒着。\n惊：使动用法，使姜氏惊。\n遂恶（wù）之：因此厌恶他。遂，连词，因而。恶，厌恶。\n爱：喜欢，喜爱。\n亟（qì）请于武公：屡次向武公请求。亟，屡次。于，介词，向。\n公弗许：武公不答应她。弗，不。\n及庄公即位：到了庄公做国君的时候。及，介词，到。即位，君主登上君位。\n制：地名，即虎牢，河南省荥（xíng）阳县西北。\n岩邑：险要的城镇。岩，险要。邑，人所聚居的地方。\n虢（guó）叔死焉：东虢国的国君死在那里。虢，指东虢，古国名，为郑国所灭。焉，介词兼指示代词相当于“于是”“于此”。\n佗邑唯命：别的地方，听从您的吩咐。佗，同“他”，指示代词，别的，另外的。唯命，只听从您的命令。\n京：地名，河南省荥阳县东南。\n谓之京城大（tài）叔：京地百姓称共叔段为京城太叔。大，同“太”。王力、朱骏声作古今字。《说文》段注：“太从大声，后世凡言大，而以为形容未尽则作太，如大宰，俗作太宰，大子，俗作太子，周大王俗作太王是也。\n祭（zhài）仲：郑国的大夫。祭：特殊读音。\n都城过百雉（zhì）：都邑的城墙超过了300丈。都：《左传·庄公二十八年》“凡邑有宗庙先君之主曰都”。指次于国都而高于一般邑等级的城市。 雉：古代城墙长一丈，宽一丈，高一丈为一堵，三堵为一雉，即长三丈。\n国之害也：国家的祸害。\n先王：前代君王。郭锡良《古代汉语讲授纲要》注为周开国君主文、武王。\n大都不过参（sān）国之一：大城市的城墙不超过国都城墙的三分之一，参，同“三”。\n中五之一：中等城市城墙不超过国都城墙的五分之一。“五分国之一”的省略。\n小九之一：小城市的城墙不超过国都城墙的九分之一。“九分国之一”的省略。\n不度：不合法度。\n非制也：不是先王定下的制度。\n不堪：受不了，控制不住的意思。\n焉辟害：哪里能逃避祸害。辟，“避”的古字。\n何厌（厌）之有：有何厌。有什么满足。宾语前置 何：疑问代词作宾语定语。之：代词，复指前置宾语。\n为之所：给他安排个地方，双宾语，即重新安排。\n无使滋蔓（zī màn）：不要让他滋长蔓延，“无”通“毋”（wú）。\n图：除掉。\n犹：尚且。\n况：何况。\n多行不义，必自毙：多做不义的事，必定自己垮台。毙，本义倒下去、垮台。汉以后才有“死”义。\n姑：姑且，暂且。\n既而：固定词组，不久。\n命西鄙北鄙（bǐ）贰于已：命令原属庄公的西部和北部的边境城邑同时也臣属于自己。 鄙：边 邑也，从邑，啚声，边境上的城邑。贰：两属。\n公子吕：郑国大夫。\n堪：承受。\n若之何：固定结构，对它怎么办？之，指“大叔命西鄙北鄙贰于己”这件事。\n欲与大（tài）叔：如果想把国家交给共叔段。与，给予。\n臣请事之：那么我请求去事奉他。事，动词，事奉。\n生民心：使动，使民生二心。\n无庸：不用。“庸”、“用”通用，一般出现于否定式。\n将自及：将自己赶上灾难，杜预注：“及之难也。及：本义追赶上。\n收贰以为己：把两属的地方收为自己的领邑。贰，指原来贰属的西鄙北鄙。 以为，“以之为”的省略。\n廪（lǐn）延：地名，河南省延津县北。\n厚将得众：势力雄厚，就能得到更多的百姓。众，指百姓。\n不义，不暱（nì），厚将崩：共叔段对君不义，百姓就对他不亲，势力再雄厚，将要崩溃。 暱：同昵（异体），亲近。\n完聚：修治（城郭），聚集（百姓）。完，修葺（qì）。\n缮甲兵：修整作战用的甲衣和兵器。缮，修理。甲，铠甲。兵，兵器。\n具卒乘（shènɡ）：准备步兵和兵车。具，准备。卒，步兵。乘，四匹马拉的战车。\n袭：偷袭。行军不用钟鼓。杜预注：“轻行掩其不备曰袭”。本是贬义，后逐渐转为中性词。\n夫人将启之：武姜将要为共叔段作内应。夫人，指武姜。启之，给段开城门，即作内应。启，为动用法。\n公闻其期：庄公听说了偷袭的日期。\n帅车二百乘 ：率领二百辆战车。帅，率领。古代每辆战车配备甲士三人，步卒七十二人。二百乘，共甲士六百人，步卒一万四千四百人。\n叛：背叛。\n入：逃入。\n公伐诸鄢：庄公攻打共叔段在鄢邑。诸：之于，合音词 。\n辛丑：干支纪日。天干：甲乙丙丁戊己庚辛壬癸。　地支：子丑寅卯辰巳（sì）午未申酉戌(xū)亥。二者相配，用以纪日，汉以后亦用以纪年。即二十三日。\n出奔共：出逃到共国(避难)。奔，逃亡。\n不弟：不守为弟之道。与“父不父，子不子用法相同。”《春秋》记载道：“郑伯克段于鄢。”意思是说共叔段不遵守做弟弟的本分。\n如二君，故曰克：兄弟俩如同两个国君一样争斗，所以用“克”字；克，战胜。\n称郑伯，讽失教也：称庄公为“郑伯”，是讥讽他对弟弟失教。讥，讽剌。失教，庄公本有教弟之责而未教。\n谓之郑志：赶走共叔段是出于郑庄公的本意。志，意愿。\n不言出奔，难之也：不写共叔段自动出奔，是史官下笔有为难之处。\n寘：“置”的通用字。放置，放逐。\n誓之：为动，对她发誓。\n黄泉：地下的泉水，喻墓穴，指死后。\n悔之：为动，对这事后悔 。\n颍考叔：郑国大夫，执掌颍谷（今河南登封西）。\n封人：管理边界的地方长官。 封：聚土培植树木。古代国境以树（沟）为界，故为边界标志。\n有献：有进献的东西。献作宾语，名词。\n赐之食：赏给他吃的。双宾语。\n食舍肉：吃的时候把肉放置一边不吃。 舍，舍的古字。\n尝：吃过。\n羹：带汁的肉。《尔雅·释器》：“肉谓之羹。”\n遗（wèi）之：赠送给她。\n繄（yī）我独无：我却单单没有啊！ 繄：句首语气助词，不译 。\n敢问何谓也：冒昧地问问你说的是什么意思呢？ 敢：表敬副词，冒昧。\n故：原故，原因和对姜氏的誓言。\n悔：后悔的心情。\n何患焉：您在这件事上忧虑什么呢？焉：于是。\n阙：通“掘”，挖。\n隧而相见：挖个地道，在那里见面。隧，隧道，这里用作动词，指挖隧道。\n其谁曰不然：那谁能说不是这样(不是跟誓词相合)呢?其，语气助词，加强反问的语气。然，代词，代庄公对姜氏发的誓言。\n赋：赋诗，孔颖达疏：“谓自作诗也。”\n大隧之中，其乐也融融：走进隧道里，欢乐真无比。\n大隧之外，其乐也洩洩（yì）：走出隧道外，心情多欢快。 中、融：上古冬韵，今押韵。 外，洩：上古月韵，今不押韵。\n遂为母子如初：从此作为母亲和儿子象当初一样。\n君子：道德高尚的人。\n施及庄公：施，延及。延及庄公。\n孝子不匮，永锡尔类：匮，尽。锡，通赐，给与。\n其是之谓乎：其，表推测语气，之，结构助词，助词宾语前置。', poem_appreciation = '这是一个流传甚广、十分典型的兄弟相争的故事。\n\n　　人们常用“亲如兄弟”来形容亲情的深厚，也用“亲兄弟，明算帐”来说明亲情和利益冲突之间的关系。我们凭自己的生活体验深知，亲情在很多时候是脆弱的，在利益的驱使之下，亲情远远不足以化解由利益导致的矛盾冲突。\n\n　　当然，兄弟相争，并非完全没有是非曲直，并非完全没有正 义、真理的存在。比如，郑庄公与共叔段的权位之争，按传统观 念，长子是王位天然的继承者，是“天理”，不容有违背。这样， 郑庄公就代表了合理的、正当的一方，而共叔段夺取王位的图谋， 便是不合理的、不正当的。\n\n　　代表合理的、正义的一方，往往充满“正气”，可以慷慨陈辞。 鸣鼓攻之，可以稳坐如山，居高临下，所以郑庄公才可以自豪地、 以先知的口吻说：“多行不义，必自毙。”\n\n　　抛开这个故事不论，‘多行不义，必自毙”也算是一条普遍真 理，正如“得道多助，失道寡助”一样。几乎可以说，古往今来，凡是作恶的人，搞阴谋诡计的人，违法乱纪的人，都没有好下场， 最终会搬起石头砸自己的脚。\n\n　　但是，如果坐着等待结果的到来，等待作恶者“自毙”，显然是愚蠢的，无异于自己坐以待毙，很可能让作恶者占尽了风光好处。我们要相信毛主席说过的：“凡是反动的东西，你不打，他就不倒。扫帚不到，灰尘照例不会自己跑掉。”所以，与其坐以待毙， 不如起而对抗，以其人之道，还治其人之身。\n\n　　这么说来，以恶抗恶，以暴力抗恶，以阴谋诡计对阴谋诡计， 在一定范围内便是合理的事。真理、道义总得以某种方式来加以捍卫，对真理、道义的信念，总不能替代实际有效的行动，就好 比强盗闯进我们家里，是不可能凭借善良的愿望和对正义的信念 来阻止强盗的抢劫的。唯有拿起武器，同强盗搏斗，把强盗赶出家门去，才是用行动来维护自己的信念，因而真理、正义才可能 得到证明，得到捍卫。\n\n　　儒家传统一直是主张知行合一、言行一致的。在内心承认的真理，在思想和言论中确信原则，必须用实际行动来加以体现，让真理、原则变成行动 的指南。如果能做到这样，不溢、恶行、阴谋等等，就既不是可怕的猛兽，也不是不可战胜和征服的。关键不在对方，而在自己是否能挺身而出，以及如何挺身而出，从而让东风压倒西风。', poem_tags = '古文观止,叙事,写人,历史,故事' WHERE poem_title = '郑伯克段于鄢' AND poem_author = '左丘明';
UPDATE edu_poem SET poem_translation = '绿衣裳啊绿衣裳，绿色面子黄里子。心忧伤啊心忧伤，什么时候才能止！\n绿衣裳啊绿衣裳，绿色上衣黄下裳。心忧伤啊心忧伤，什么时候才能忘！\n绿丝线啊绿丝线，是你亲手来缝制。我思亡故的贤妻，使我平时少过失。\n细葛布啊粗葛布，穿上冷风钻衣襟。我思亡故的贤妻，实在体贴我的心。', poem_notes = '里：衣服的衬里。\n曷（hé）：何，怎么。维：语气助同，没有实义。已：止息，停止。\n裳（cháng）：下衣，形状像现在的裙子。\n亡：用作“忘”，忘记。\n女（rǔ）：同“汝”，你。治：纺织。\n古人：故人，古通“故”，这里指作者亡故的妻子。\n俾（bǐ）：使。訧（yóu）：古同“尤”，过失，罪过。\n絺（chī）：细葛布。绤（xì）：粗葛布。\n凄：凉而有寒意。凄其：同“凄凄”。以：因。一说通“似”，像。\n获：得。', poem_appreciation = '此诗表达丈夫悼念亡妻的深长感情。由衣而联想到治丝，惋惜亡妻治家的能干。想到亡妻的贤德，“我思古人，俾无訧兮，”正是俗话所言，家有贤妻，夫无横祸。描写细腻，情感丰富。构思巧妙，由外入里，层层生发。衣裳多色见于外，衣裳之丝见于内。再由“治”丝条理，联想办事的条理，才使“无訧”，讲而深入到身心内部，体肤由而凉爽，再到“实获我心”的情感深处，若断若续，含蓄委婉，缠绵悱恻。\n\n　　这首诗有四章，也采用了重章叠句的手法。鉴赏之时，要四章结合起来看，才能体味到包含在诗中的深厚感情，及诗人创作此诗时的情况。\n\n　　第一章说：“绿兮衣兮，绿衣黄里。”表明诗人把故妻所作的衣服拿起来翻里翻面地看，诗人的心情是十分忧伤的。\n\n　　第二章“绿衣黄裳”与“绿衣黄里”相对为文，是说诗人把衣和裳都翻里翻面细心看。妻子活着时的一些情景是他所永远不能忘记的，所以他的忧愁也是永远摆不脱的。\n\n　　第三章写诗人细心看着衣服上的一针一线（丝线与衣料同色）。他感到，每一针都反映着妻子对他的深切的关心和爱。由此，他想到妻子平时对他在一些事情上的规劝，使他避免了不少过失。这当中包含着非常深厚的感情。第四章说到天气寒冷之时，还穿着夏天的衣服。妻子活着的时候，四季换衣都是妻子为他操心，衣来伸手，饭来张口。妻子去世后，自己还没有养成自己关心自己的习惯。到实在忍受不住萧瑟秋风的侵袭，才自己寻找衣服，便勾起他失去贤妻的无限悲恸。“绿衣黄里”是说的夹衣，为秋天所穿；“絺兮绤兮”则是指夏衣而言。这首诗应作于秋季。诗中写诗人反覆看的，是才取出的秋天的夹衣。人已逝而为他缝制的衣服尚在。衣服的合身，针线的细密，使他深深觉得妻子事事合于自己的心意，这是其他任何人也代替不了的。所以，他对妻子的思念，他失去妻子的悲伤，都将是无穷尽的。“天长地久有尽时，此恨绵绵无绝期”（白居易《长恨歌》），诗是写得十分感人的。', poem_tags = '诗经,悼亡' WHERE poem_title = '国风·邶风·绿衣' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '磨针溪是坐落在眉州的象耳山下。传说李白在山中读书的时候，没有完成好自己的学业，就放弃学习离开了。他路过一条小溪，遇见一位老妇人在磨铁棒，问她在干什么，老妇人说：“我想把它磨成针。”李白被她的精神感动，就回去完成学业。那老妇人自称姓武。现在那溪边还有一块武氏岩。', poem_notes = '眉州：地名，今四川省眉山一带。\n世传：世世代代相传。\n成：完成。\n去：离开。\n逢：碰上。\n媪：妇女的统称。\n方：正在。\n铁杵；铁棍,铁棒.杵,压米或捶衣用的棒,一头粗一头细的圆棒.\n欲：想要.\n感：被......感动.\n还：回去.\n之：代词，指代老妇人在做的事。\n卒业：完成学业。\n今：现在\n氏：姓…的人。', poem_appreciation = '唐朝著名大诗人李白小时候不喜欢念书，常常逃学，到街上去闲逛。\n\n　　一天，李白又没有去上学，在街上东溜溜、西看看，不知不觉到了城外。暖和的阳光、欢快的小鸟、随风摇摆的花草使李白感叹不已，“这么好的天气，如果整天在屋里读书多没意思？”\n\n　　走着走着，在一个破茅屋门口，坐着一个满头白发的老婆婆，正在磨一根棍子般粗的铁杵。李白走过去， “老婆婆，您在做什么？”\n\n　　“我要把这根铁杵磨成一个绣花针。”老婆婆抬起头，对李白笑了笑，接着又低下头继续磨着。\n\n　　“绣花针？”李白又问：“是缝衣服用的绣花针吗？”\n\n　　“当然！”\n\n　　“可是，铁杵这么粗，什么时候能磨成细细的绣花针呢？”\n\n　　老婆婆反问李白：“滴水可以穿石，愚公可以移山，铁杵为什么不能磨成绣花针呢？”\n\n　　“可是，您的年纪这么大了？”\n\n　　“只要我下的功夫比别人深，没有做不到的事情。”\n\n　　老婆婆的一番话，令李白很惭愧，于是回去之后，再没有逃过学。每天的学习也特别用功，终于成了名垂千古的诗仙。', poem_tags = '小学文言文,寓言,故事,励志,哲理' WHERE poem_title = '铁杵磨针' AND poem_author = '郑之珍';
UPDATE edu_poem SET poem_translation = '余漫步在秋天的夜色中低声吟唱，总觉得心里空虚郁闷、心里惴惴不安。\n今天晚上如果再没有圆满的月亮，今年的秋天就算是虚度光阴了。', poem_tags = '秋天,中秋节' WHERE poem_title = '中秋' AND poem_author = '司空图';
UPDATE edu_poem SET poem_translation = '扁鹊进见蔡桓公，（在蔡桓公面前）站了一会儿，扁鹊说：“您在肌肤纹理间有些小病，不医治恐怕会加重。”蔡桓公说：“我没有病。”扁鹊离开后，蔡桓公说：“医生喜欢/习惯给没病的人治病来当作自己医术的功效。”过了十天，扁鹊再次进见蔡桓公，说：“您的病在肌肉里，不及时医治将会更加严重。”蔡桓公不理睬。扁鹊离开后，蔡桓公又不高兴。\n\n　　（又）过了十天，扁鹊再一次进见蔡桓公，说：“您的病在肠胃里了，不及时治疗将要更加严重。”蔡桓公又没有理睬。扁鹊离开后，蔡桓公又不高兴。\n\n　　（又）过了十天，扁鹊（远远地）看见桓侯，掉头就跑。蔡桓公于是/特意派人问他。扁鹊说：“小病在皮肤纹理（之间），汤熨（的力量）所能达到的；病在肌肉和皮肤里面，用针灸可以治好；病在肠胃里，用火剂汤可以治好；病在骨髓里，那是司命神管辖的事情了，（医生）是没有办法（医治）的。现在（病）在骨髓（里面），我因此不再请求（为他治病）了。”\n\n　　过了五天，蔡桓公身体疼痛，派人寻找扁鹊，（扁鹊）已经逃到秦国了。蔡桓公于是病死了。\n\n释义\n扁鹊（què）：战国时医学家。姓秦，名越人，鄚（mò）（今河北任丘）人，他是扁鹊学派的传人，医术高明，所以人们就沿用他师傅的名字来称呼他，以此表达对他的尊敬。扁鹊学派的最后传人是宋代的窦材，著有《扁鹊心书》，他曾说，历史上有三个扁鹊，“上古扁鹊者，扁鹊也；中古扁鹊者，秦越人也；当世扁鹊者，大宋窦材是也。”\n蔡桓公：蔡国（今河南上蔡一带）国君，下文称“桓侯”。\n立：站立。\n有间（jiān）：一会儿。\n疾：古时‘疾’与‘病’的意思有区别。疾，小病、轻病；病，重病。\n腠（còu）理：中医学名词，指人体肌肤之间的空隙和肌肉、皮肤纹理。\n恐：恐怕，担心。\n寡人：古代君主对自己的谦称。这个词的用法比“孤”复杂些。君王自称。春秋战国时，诸侯王称寡人。在文中译为“我”。\n医之好治不病以为功：医生喜欢治疗没有发作的疾病来当作自己医术的功效。好（hào），喜欢。（另解：好（hào），习惯。医生习惯治疗没有发作的疾病来当作自己医术的功效。读法：医之好治不病以为功。医，医生。之，用于主谓之间，取消句子独立性，不译。好（hào），习惯。治，医治。不病，没有发作的疾病。（自古上工治未病。）以，以之，用以。为，作为。功，功绩，成绩。）\n肌肤：肌肉。\n将：要。\n应：答应，理睬。\n居：用于表时间的词语前，表示已经经过的时间。\n居十日：待了十天。居：用在表示时间的词语前面，表示经过的时间；停留，经历。在文中译“过了”。\n益：更，更加。\n望桓侯而还（xuán）走：远远地看见桓侯，掉头就跑。还，回转，调转。走，小步快跑。\n故：特意。（另解：于是。）\n汤熨：汤熨（的力量）所能达到的。汤熨，中医治病的方法之一。汤，用热水或药水敷治。这个意义后写作“烫”。熨，用粗盐或艾草等东西外用热敷。\n及：达到。\n针石：古代针灸用的金属针和用砭石制成的石针，这里指用针刺治病。\n火齐（jì）：火剂汤，一种清火、治肠胃病的汤药。齐，调配，调剂。这个意义后写作“剂”。22.司命之所属：司命神所掌管的事。司命，传说中掌管生命的神。属，隶属，管辖。23.无奈何也：没有办法了。奈何，怎么办，怎么样。\n臣是以无请也：我就不再请求给他治病了，意思是不再说话。无请，不再请求。是以：以是，因此。（另解：请，询问。）\n使：指使，派人。\n索：寻找。\n遂（suì）：于是，就。▲', poem_appreciation = '这篇故事选自《韩非子·喻老》，题目是后人加的。内容带有劝喻型性。文章以时间为序，以蔡桓公（桓侯）的病情的发展为线索，通过扁鹊“四见”的局势，通过记叙蔡桓公因讳疾忌医最终致死的故事，阐明一个道理：不能盲目相信自己，不能讳疾忌医。同时给人们以启迪：对待自己的缺点、错误，也像对待疾病一样，决不能讳疾忌医，而应当虚心接受批评，防患于未然。告诫人们要正视自己的缺点和错误，虚心接受别人的意见。\n\n　　全文叙述生动，条理清晰。刻画的两个人物形象简洁、传神。\n\n　　以时间为序，写扁鹊与蔡桓公的四次见面，又传神地再现两人见面时不同的神态、语言和性格，突出扁鹊慧眼识病，尽职尽责，敢于直言，机智避祸，和桓公的骄横自负、讳疾忌医。结尾，扁鹊不得不逃亡，暗示了专制君主统治下的残暴。文中深刻揭示了及时医过，防微杜渐的道理，颇能引人深思。', poem_tags = '初中文言文,寓理,故事' WHERE poem_title = '扁鹊见蔡桓公' AND poem_author = '韩非';
UPDATE edu_poem SET poem_translation = '灞原上的秋风细雨初定，傍晚看见雁群南去不停。\n面对他乡树木落叶纷纷，寒夜的孤灯独照我一人。\n空园里白露频频地下滴，单门独户只与野僧为邻。\n寄卧荒凉郊居为时已久，何时才能为国致力献身？', poem_notes = '⑴灞（bà）上：又作“霸上”，古代地名，位于今陕西西安东，因地处灞陵高原而得名，为作者来京城后的寄居之所。\n⑵郊扉：郊居。\n⑶致此身：意即以此身为国君报效尽力。', poem_appreciation = '此诗纯写闭门寥落之感。整首诗篇好似一幅形象鲜明、艺术精湛的画卷。读者把它慢慢地打开，首先映入眼帘的是灞原上空萧森的秋气：撩人愁思的秋风秋雨直到傍晚才停歇下来，在暮霭沉沉的天际，接连不断的雁群自北向南急急飞过。连番的风雨，雁儿们已经耽误了不少行程，好不容易风停雨歇，得赶在天黑之前找到一个宿处。这里用一个“频”字，既表明了雁群之多，又使人联想起雁儿们急于投宿的惶急之状。古人每见雁回，易惹乡思。读者继续打开画卷，景象则由寥廓的天际渐渐地转到地面，转到诗中的主人。只见风雨中片片黄叶从树上飘落下来，而寄居在孤寺中的一个旅客正独对孤灯，默默地出神。“落叶他乡树”这句，很值得玩味。中国有句老话叫做“树高千丈，叶落归根”，诗人在他乡看到落叶的情景，不能不有所感触。自己羁留异地，不知何时才能回到故乡东海（今江苏连云港市西南）。其心情之酸楚，完全渗透在这句诗的字里行间。“寒灯独夜人”，一个“寒”字，一个“独”字，写尽客中凄凉孤独的况味。不难想象：一灯如豆，伴着一个孤寂的身影。夜已深了，寒意重重，在寒气包围中，灯光更显得黯淡无力，而诗人孤独凄苦的心情也随之更进了一层。“寒”与“独”起着相互映衬的作用：由寒灯而显出夜长难捱，因孤独而更感到寒气逼人。\n\n　　五、六两句让画卷再向下推移，它不仅显示了更大的空间，更细的景物，而且出神入化，展现了诗人的心境。这时夜阑人静，连秋虫都已停止了歌唱，只有露珠滴落在枯叶上的响声，一滴接着一滴，虽很微弱，却很清晰。这句“空园白露滴”用的是以“动”烘托“静”的手法，比写无声的静更能表现环境的寂静，露滴的声音不但没有划破长夜的寂静，反而更使人感到静得可怕。连露滴的声音都可听到，就没有什么比这更寂静的了。下一句“孤壁野僧邻”同样是用烘托的手法。明明要说的是自己孑然一身，孤单无依，却偏说出还有一个邻居，而这个邻居竟是一个绝迹尘世、犹如闲云野鹤的僧人。与这样的野僧为邻，诗人的处境的孤独就显得更加突出了。这两句在写景的同时进一步写出了诗人的心境：秋夜孤房连露滴的声音都可听到，正说明他思潮起伏，长夜无眠；而所与为邻的只有一个野僧，表明他正想到自己已经被抛出世外，不知何日才能结束这种生涯。正是因为这样，所以诗的最后两句也就与前面的描写自然衔接起来，不显得突兀。\n\n　　最后两句直接说出诗人的感慨：“寄卧郊扉久，何年致此身？”诗人为了求取官职来到长安，在灞上（又作“霸上”，长安东）已寄居多时，一直没有找到进身之阶，因而这里率直道出了怀才不遇的苦境和进身希望的渺茫。\n\n　　这首诗写景，都是眼前所见，不假浮词雕饰；写情，重在真情实感，不作无病呻吟。因此，尽管题材并不新鲜，却仍有相当强的艺术感染力。', poem_tags = '唐诗三百首,秋天,孤独,怀才不遇' WHERE poem_title = '灞上秋居' AND poem_author = '马戴';
UPDATE edu_poem SET poem_translation = '好个修美的女郎，麻纱罩衫锦绣裳。她是齐侯的爱女，她是卫侯的新娘，她是太子的胞妹，她是邢侯的小姨，谭公又是她姊丈。\n手像春荑好柔嫩，肤如凝脂多白润，颈似蝤蛴真优美，齿若瓠子最齐整。额角丰满眉细长，嫣然一笑动人心，秋波一转摄人魂。\n好个高挑的女郎，车歇郊野农田旁。看那四马多雄健，红绸系在马嚼上，华车徐驶往朝堂。诸位大夫早退朝，今朝莫太劳君王。\n黄河之水白茫茫，北流入海浩荡荡。下水鱼网哗哗动，戏水鱼儿刷刷响，两岸芦苇长又长。陪嫁姑娘身材高，随从男士貌堂堂！', poem_notes = '硕人：高大白胖的人，美人。当时以身材高大为美。此指卫庄公夫人庄姜。颀（qí）：修长貌。\n衣锦：穿着锦衣，翟衣。“衣”为动词。褧（jiǒng）：妇女出嫁时御风尘用的麻布罩衣，即披风。\n齐侯：指齐庄公。子：这里指女儿。\n卫侯：指卫庄公。\n东宫：太子居处，这里指齐太子得臣。\n邢：春秋国名，在今河北邢台。姨：这里指妻子的姐妹。\n谭公维私：意谓谭公是庄姜的姐夫。谭，春秋国名，在今山东历城。维，其。私，女子称其姊妹之夫。\n荑（tí）：白茅之芽。\n领：颈。蝤蛴（qiúqí）：天牛的幼虫，色白身长。\n瓠犀（hùxī户西）：瓠瓜子儿，色白，排列整齐。\n螓（qín）：似蝉而小，头宽广方正。螓首，形容前额丰满开阔。蛾眉：蚕蛾触角，细长而曲。这里形容眉毛细长弯曲。\n倩：嘴角间好看的样子。\n盼：眼珠转动，一说眼儿黑白分明。\n敖敖：修长高大貌。\n说（shuì）：通“税”，停车。农郊：近郊。一说东郊。\n四牡：驾车的四匹雄马。有骄：骄骄，强壮的样子。“有”是虚字，无义。\n朱幩（fén）：用红绸布缠饰的马嚼子。镳镳（biāo）：盛美的样子。\n翟茀（dífú）：以雉羽为饰的车围子。翟，山鸡。茀，车篷。\n夙退：早早退朝。\n河水：特指黄河。洋洋：水流浩荡的样子。\n北流：指黄河在齐、卫间北流入海。活活（guō）：水流声。\n施：张，设。罛（gū）：大的鱼网。濊濊（huò）：撒网入水声。\n鱣（zhān）：鳇鱼。一说赤鲤。鲔（wěi）：鲟鱼。一说鲤属。发发（bō）：鱼尾击水之声。一说盛貌。\n葭（jiā）：初生的芦苇。菼（tǎn）：初生的荻。揭揭：长貌。\n庶姜：指随嫁的姜姓众女。孽孽：高大的样子，或曰盛饰貌。\n士：从嫁的媵臣。有朅（qiè）：朅朅，勇武貌。', poem_appreciation = '《硕人》是《诗经·卫风》中的一首，是赞美是齐庄公的女儿、卫庄公的夫人庄姜的诗。其中“巧笑倩兮，美目盼兮”二句对庄姜之美的精彩刻画，永恒地定格了中国古典美人的曼妙姿容，历来备受推崇。\n\n　　《卫风·硕人》通篇用了铺张手法，不厌其烦地吟唱了有关“硕人”的方方面面，如第一章主要说她的出身——她的三亲六戚，父兄夫婿，皆是当时各诸侯国有权有势的头面人物，她是一位门第高华的贵夫人。第三、四章主要写婚礼的隆重和盛大，特别是第四章，七句之中，竟连续六句用了叠字。那洋洋洒洒的黄河之水，浩浩荡荡北流入海；那撒网入水的哗哗声，那鱼尾击水的唰唰声，以及河岸绵绵密密、茂茂盛盛的芦苇荻草，这些壮美鲜丽的自然景象，都意在引出“庶姜孽孽，庶士有朅”——那人数众多声势浩大的陪嫁队伍，那些男傧女侣，他们像庄姜本人一样，皆清一色地修长俊美。上述所有这一切，从华贵的身世到隆重的仪仗，从人事场面到自然景观，无不或明或暗、或隐或显、或直接或间接地衬托着庄姜的天生丽质。而直接描写她的美貌者，除开头“硕人其颀，衣锦褧衣”的扫描外，主要是在第二章。这里也用了铺叙手法，以七个生动形象的比喻，犹如电影的特写镜头，犹如纤微毕至的工笔画，细致地刻画了她艳丽绝伦的肖像——柔软的纤手，鲜洁的肤色，修美的脖颈，匀整洁白的牙齿，直到丰满的额角和修宛的眉毛，真是毫发无缺憾的人间尤物。但这些工细的描绘，其艺术效果，都不及“巧笑倩兮，美目盼兮”八字。\n\n　　此诗开启了后世博喻写美人的先河，历来备受人们的推崇和青睐。孙联奎《诗品臆说》拈出“巧笑倩兮，美目盼兮”二语，并揭示出其所以写得好的奥窍。在他看来，“手如柔荑”等等的比拟譬况，诗人尽管使出了混身解数，却只是刻画出美人之“形”，而“巧笑”“美目”寥寥八字，却传达出美人之“神”。还可以补充说，“手如柔荑”等句是静态，“巧笑”二句则是动态。在审美艺术鉴赏中，“神”高于“形”，“动”优于“静”。形的描写、静态的描写当然也必不可少，它们是神之美、动态之美的基础。如果没有这些基础，那么其搔首弄姿也许会成为令人生厌的东施效颦。但更重要的毕竟还是富有生命力的神之美、动态之美。形美悦人目，神美动人心。一味静止地写形很可能流为刻板、呆板、死板，犹如纸花，了无生气，动态地写神则可以使人物鲜活起来，气韵生动，性灵毕现，似乎从纸面上走出来，走进读者的心灵，摇动读者的心旌。在生活中，一位体态、五官都无可挑剔的丽人固然会给人留下较深的印象，但那似乎漫不经心的嫣然一笑、含情一瞥却更能使人久久难忘。假如是一位多情的年青人，这一笑一盼甚至会进入他的梦乡，惹起他纯真无邪的爱的幻梦。在此诗中，“巧笑”“美目”二句确是“一篇之警策”，“倩”“盼”二字尤富表现力。古人释“倩”为“好口辅”，释“盼”为“动目也”。“口辅”指嘴角两边，“动目”指眼珠的流转。可以想象那楚楚动人的笑靥和顾盼生辉的秋波，是怎样的千娇百媚，令人销魂摄魄。几千年过去了，诗中所炫夸的高贵门第已成为既陈刍狗，“柔荑”“凝脂”等比喻也不再动人，“活活”“濊濊”等形容词更不复运用，而“巧笑倩兮，美目盼兮”却仍然亮丽生动，光景常新，仍然能够激活人们美的联想和想像。\n\n　　“传神写照，正在阿堵”，这原是六朝画家所总结出的创作经验，它也适用于其他艺术创造活动。此“阿堵”即眼睛。眼睛是心灵的窗户，表现人物莫过于表现眼睛。不过“眼睛”应作宽泛的理解，它可以泛指一切与人的内心世界、人的灵性精神息息相关的东西，比如此诗中倩丽的“巧笑”。达·芬奇的名画《蒙娜丽莎》，也是以“永恒的微笑”获得永恒的魅力。总之，任何艺术创作都要善于捕捉与表现关键所在。一个“关键”胜过一打非“关键”。', poem_tags = '诗经,女子' WHERE poem_title = '硕人' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '王濬的战船从益州出发，东吴的王气便黯然消逝。\n千丈长的铁链沉入江底，一片降旗挂在石头城头。\n人生中多少次伤怀往事，山形依然不变靠着寒流。\n从今以后天下归为一同，芦荻在旧垒上萧萧飘摇。', poem_notes = '西塞山：位于今湖北省黄石市，又名道士洑，山体突出到长江中，因而形成长江弯道，站在山顶犹如身临江中。\n王濬：晋益州刺史。一作“西晋”。益州：晋时郡治在今成都。晋武帝谋伐吴，派王濬造大船，出巴蜀，船上以木为城，起楼，每船可容二千余人。\n金陵：今南京，当时是吴国的都城。王气：帝王之气。黯然：一作“漠然”。\n千寻铁锁沉江底：东吴末帝孙皓命人在江中轩铁锥，又用大铁索横于江面，拦截晋船，终失败。寻：长度单位。\n一片降幡（fān）出石头：王濬率船队从武昌顺流而下，直到金陵，攻破石头城，吴主孙皓到营门投降。\n人世几回伤往事：一作“荒苑至今生茂草”。\n枕寒流：一作“枕江流”。\n今逢：一作“从今”。\n“四海为家”两句：如今国家统一，旧时的壁垒早已荒芜。', poem_appreciation = '西塞山，在今湖北省黄石市东面的长江边上。岚横秋塞，山锁洪流，形势险峻。是六朝有名的军事要塞。公元280年（西晋太康元年），晋武帝司马炎命王濬率领以高大的战船“楼船”组成的西晋水军，顺江而下，讨伐东吴。诗人便以这件史事为题，开头写“楼船下益州”，“金陵王气”便黯然消失。益州金陵，相距遥遥，一“下”即“收”，表明速度之快。两字对举就渲染出一方是势如破竹，一方则是闻风丧胆，强弱悬殊，高下立判。第二联便顺势而下，直写战事及其结果。东吴的亡国之君孙皓，凭借长江天险，并在江中暗置铁锥，再加以千寻铁链横锁江面，自以为是万全之计，谁知王濬用大筏数十，冲走铁锥，以火炬烧毁铁链，结果顺流鼓棹，径造三山，直取金陵。“皓乃备亡国之礼，……造于垒门”（《晋书·王濬传》）。第二联就是形象地概括了这一段历史。\n\n　　诗的前四句，洗炼、紧凑，在对比之中写出了双方的强弱，进攻的路线，攻守的方式，战争的结局。它只用第一句诗写西晋水军出发，下面就单写东吴：在战争开始的反映，苦心经营的工事被毁，直到举旗投降，步步紧逼，一气直下。人们不仅看到了失败者的形象，也看到了胜利者的那种摧枯拉朽的气势。可谓虚实相间，胜败相形，巧于安排。\n\n　　诗人在剪裁上颇具功力。他从众多的史事中单选西晋灭吴一事，这是耐人寻味的，因为东吴是六朝的头，它又有颇为“新颖”的防御工事，竟然覆灭了。照理后人应引以为鉴，其实不然。所以写吴的灭亡，不仅揭示了当时吴王的昏聩无能，更表现了那些后来者的愚蠢，也反映了国家的统一是历史的必然。其次，诗人写晋吴之战，重点是写吴，而写吴又着重点出那种虚妄的精神支柱“王气”、天然的地形、千寻的铁链，皆不足恃。这就从反面阐发了一个深刻的思想，那就是“兴废由人事，山川空地形”（刘禹锡《金陵怀古》）。可见如此剪裁，就在于它能完满地表现其主题思想。\n\n　　清代屈复认为此诗第五句甚妙。不过应该指出，若是没有前四句丰富的内容和深刻的思想，第五句是难以收到如此言简意赅的效果。第六句“山形依旧枕寒流”，山形，指西塞山；寒流，指长江，“寒”字和结句的“秋”字相照应。诗到这里才点到西塞山，但是前面所写并没有离题。因为西塞山之所以成为有名的军事要塞，之所以在它的身边演出过那些有声有色载入史册的“活剧”，就是以南北分裂、南朝政权存在为条件的。因此前面放眼六朝的兴亡，正是为了从一个广阔的历史背景中引出西塞山，从而大大开拓了诗的境界。诗人不去描绘眼前西塞山如何奇伟竦峭，而是突出“依旧”二字，亦是颇有讲究的。山川“依旧”，就更显得人事之变化，六朝之短促，不仅如此，它还表现出一个“江山不管兴亡恨，一任斜阳伴客愁”（包佶《再过金陵》）的意境。这些又从另一个角度对上一句的“伤”字作了补充。\n\n　　第七句宕开一笔，直写“今逢”之世，第八句说往日的军事堡垒，如今已荒废在一片秋风芦荻之中。这残破荒凉的遗迹，便是六朝覆灭的见证，便是分裂失败的象征，也是“今逢四海为家日”、江山一统的结果。怀古慨今，收束了全诗。全诗借古讽今，沉郁感伤，但繁简得当，直点现实。\n\n　　刘禹锡的这首诗，寓深刻的思想于纵横开阖、酣畅流利的风调之中，诗人好像是在客观地叙述往事，描绘古迹，其实并非如此，刘禹锡在这首诗中，把嘲弄的锋芒指向在历史上曾经占据一方、但终于覆灭的统治者，这正是对重新抬头的割据势力的迎头一击。当然，“万户千门成野草，只缘一曲《后庭花》”（刘禹锡《金陵五题·台城》），这个六朝覆灭的教训，对于当时骄侈腐败的唐王朝来说，也是一面很好的镜子。', poem_tags = '唐诗三百首,咏史怀古' WHERE poem_title = '西塞山怀古' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '齐景公喜欢捕鸟。有一次，他捕到了一只漂亮的鸟，就命令烛邹管理鸟。不久，鸟逃跑了。齐景公气坏了，决定亲手杀掉他。晏子说：“烛邹有三条罪状，请让我列数他的罪状然后杀掉他。”于是召见烛邹，在齐景公面前列数他的罪行，说：“烛邹！你是我们君王的养鸟人，却让鸟逃跑了，这是第一条罪行；让我们君王为了一只鸟就要杀人，这是第二条罪行；让诸侯听到这件事，认为我们的君王看重鸟而轻视手下的人，这是第三条罪行。烛邹的罪已经列举结束，请杀死烛邹。”景公说：“不用处死了.我明白你的指教了。”', poem_notes = '弋：（yì）带有绳子的箭，用来射鸟；系着绳的箭，此处名词作动词，指用弋射；此处指捕鸟\n使（使烛邹主鸟）：命令，派遣（上级对下级）。\n使（使吾君、使诸侯）：致使，让。\n是：这。\n故：原因，缘故。\n景公：姜姓，吕氏，名杵臼。春秋后期齐国国君，齐灵公之子，齐庄公之弟。\n好：爱好，喜爱。\n烛邹：齐景公的一个臣仆。\n主：掌管，主管，负责管理；也可翻译成“养”。\n诏：诏书，皇上的命令或文告。这里指下令。\n数（shǔ）：历数；列举\n重：重视，以……为重。\n轻：轻视，以……为轻。\n闻命：接受教导。命：命令，这里指教导。\n亡：丢失，逃跑，让……逃跑了，这里指让鸟逃走了。\n以（以吾君重鸟）：认为。\n以（以其罪而杀之）：按照。\n以（以鸟之故）：因为。\n士：商、西周、春秋时最低级的贵族阶层；读书人。\n前：前面。\n毕：结束。\n而：连词表承接；连词表并列　。\n汝：你。\n谏：规劝\n罪三：三条罪状。古代汉语中数词作定语常常放在中心词后。下文的“罪一”“罪二”用法相同。\n是：这。\n欲(召吏欲杀之):想\n寡人：古代君主自称。', poem_tags = '小学文言文,故事,赞美,写人' WHERE poem_title = '晏子谏杀烛邹' AND poem_author = '刘向 编';
UPDATE edu_poem SET poem_tags = '抒怀,感慨' WHERE poem_title = '游子吟' AND poem_author = '李益';
UPDATE edu_poem SET poem_translation = '用黄金镀饰、白玉镶嵌的宝刀，到夜间，它耀眼的光芒，穿透窗户，直冲云霄。\n大丈夫已到了五十岁，可建功立业的希望渺茫，只能独自提刀徘徊，环顾着四面八方，祈求能一展抱负，小试牛刀。\n我在京城里结交的都是些豪杰义士，彼此意气相投，相约为国战斗，同生共死。\n不能在流传千年的史册上留名，我感到羞耻；但一颗丹心始终想消灭胡虏，报效天子。\n近来，我来到汉水边从军，每天早晨都对着参差耸立的终南山，遥望着布满晶莹似玉般积雪的峰峦。\n啊，楚国虽然被秦国蚕食，但即使剩下三户人家，也一定能消灭秦国，难道我堂堂中华大国，竟会没有一个能人，把金虏赶出边关？', poem_notes = '金错刀：用黄金装饰的刀。\n白玉：白色的玉。亦指白璧。\n八荒：指四面八方边远地区。\n京华：京城之美称。因京城是文物、人才汇集之地，故称。这里指南宋京城临安（今杭州市）。\n奇士：非常之士。德行或才智出众的人\n意气：豪情气概。\n相期：期待；相约。这里指互相希望和勉励。\n史策：即史册、史书。\n丹心：赤诚的心。\n尔来：近来。\n天汉滨：汉水边。这里指汉中一带。\n南山：终南山，一名秦岭，在陕西省南部。嶙峋：山石参差重叠的样子。\n “楚虽三户”句：战国时，秦攻楚，占领了楚国不少地方。楚人激愤，有楚南公云：“楚虽三户，亡秦必楚。”意思说：楚国即使只剩下三户人家，最后也一定能报仇灭秦。三户，指屈、景、昭三家。', poem_tags = '古诗三百首,爱国,壮志' WHERE poem_title = '金错刀行' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '松树小的时候长在很深很深的草中，埋没看不出来，\n到现在才发现已经比那些野草（蓬蒿）高出了许多。\n那些人当时不识得可以高耸入云的树木，\n直到它高耸入云，人们才说它高。', poem_notes = '刺头：指长满松针的小松树。\n蓬蒿（pénghāo）：两种野草。\n直待：直等到。\n凌云：高耸入云。\n始道：才说。', poem_appreciation = '《小松》借松写人，托物讽喻，寓意深长。\n\n　　松，树木中的英雄、勇士。数九寒天，百草枯萎，万木凋零，而它却苍翠凌云，顶风抗雪，泰然自若。然而凌云巨松是由刚出土的小松成长起来的。小松虽小，即已显露出必将“凌云”的苗头。《小松》前两句，生动地刻画出这一特点。\n\n　　“自小刺头深草里”——小松刚出土，的确小得可怜，路边野草都比它高，以至被掩没在“深草里”。但它虽小而并不弱，在“深草”的包围中，它不低头，而是“刺头”——那长满松针的头，又直又硬，一个劲地向上冲刺，锐不可当。那些弱不禁风的小草是不能和它相匹敌的。“刺头”的“刺”，一字千钧，不但准确地勾勒出小松外形的特点，而且把小松坚强不屈的性格、勇敢战斗的精神，活脱脱地勾画出来了。一个“刺”字，显示出小松具有强大的生命力；它的“小”，只是暂时的，相对的，随着时间的推进，它必然由小转大。不是么？——\n\n　　“而今渐觉出蓬蒿。”蓬蒿，即蓬草、蒿草，草类中长得较高者。小松原先被百草踩在脚底下，可现在它已超出蓬蒿的高度；其他的草当然更不在话下。这个“出”字用得精当，不仅显示了小松由小转大、发展变化的情景，而且在结构上也起了承前启后的作用：“出”是“刺”的必然结果，也是未来“凌云”的先兆。事物发展总是循序渐进，不可能一步登天，故小松从“刺头深草里”到“出蓬蒿”，只能“渐觉”。“渐觉”说得既有分寸，又很含蓄。是谁“渐觉”的呢？只有关心、爱护小松的人，时时观察、比较，才能“渐觉”；至于那些不关心小松成长的人，视而不见，哪能谈得上“渐觉”呢？故作者笔锋一转，发出深深的慨叹：\n\n　　“时人不识凌云木，直待凌云始道高。” 这里连说两个“凌云”，前一个指小松，后一个指大松。大松“凌云”，已成事实，称赞它高，并不说明有眼力，也无多大意义。小松尚幼小，和小草一样貌不惊人，如能识别出它就是“凌云木”，而加以爱护、培养，那才是有识见，才有意义。然而时俗之人所缺少的正是这个“识”字，故诗人感叹道：眼光短浅的“时人”，是不会把小松看成是栋梁之材的，有多少小松，由于“时人不识”，而被摧残、被砍杀啊！这些小松，和韩愈笔下“骈死于槽枥之间”的千里马，不是遭到同样悲惨的命运吗？\n\n　　杜荀鹤出身寒微，虽然年青时就才华毕露，但由于“帝里无相识”（《辞九江李郎中入关》），以至屡试不中，报国无门，一生潦倒。埋没深草里的“小松”，不也正是诗人的自我写照？', poem_tags = '咏物,讽喻,励志,哲理' WHERE poem_title = '小松' AND poem_author = '杜荀鹤';
UPDATE edu_poem SET poem_translation = '离别跟这样的情景最为相同，二水分流，一个向西，一个朝东，但最终还能再度相逢。即使情感浅薄，好象是飘飘不定，白云行空，但仍可相逢在梦中。\n　　可惜的是人的情意比行云流水还要浅薄而无定性，佳期密约，难以使人信从。认真回想，从前的种种。虽然多次令人肠断，但都与这次，截然不同！', poem_notes = '解：懂得，知道。\n行云：喻自己所思念的女子，用巫山神女朝云暮雨的故事。\n可怜：可惜。\n佳会：美好的聚会。\n难重（chóng）：难以再来。', poem_tags = '抒情,离别' WHERE poem_title = '少年游·离多最是' AND poem_author = '晏几道';
UPDATE edu_poem SET poem_translation = '柏木船儿荡悠悠，河中水波漫漫流。圆睁双眼难入睡，深深忧愁在心头。不是想喝没好酒，姑且散心去邀游。\n我心并非青铜镜，不能一照都留影。也有长兄与小弟，不料兄弟难依凭。前去诉苦求安慰，竟遇发怒坏性情。\n我心并非卵石圆，不能随便来滚转；我心并非草席软，不能任意来翻卷。雍容娴雅有威仪，不能荏弱被欺瞒。\n忧愁重重难排除，小人恨我真可恶。碰到患难已很多，遭受凌辱更无数。静下心来仔细想，抚心拍胸猛醒悟。\n白昼有日夜有月，为何明暗相交迭？不尽忧愁在心中，好似脏衣未洗洁。静下心来仔细想，不能奋起高飞越。', poem_notes = '泛：浮行，漂流，随水冲走。\n流：中流，水中间。\n耿耿：鲁诗作“炯炯”，指眼睛明亮；一说形容心中不安。\n隐忧：深忧。隐：痛\n微：非，不是。\n鉴：铜镜。\n茹（rú如）：猜想。\n据：依靠。\n薄言：语助词。愬（sù诉）：同“诉”，告诉。\n棣棣：雍容娴雅貌；一说丰富盛多的样子。\n选：假借为“柬”。挑选,选择。\n悄悄：忧貌。\n愠（yùn运）：恼怒，怨恨。\n觏（gòu够）：同“遘”，遭逢。闵（mǐn敏）：痛，指患难。\n寤：交互。辟（pì屁）：通“擗”，捶胸。摽（biào鳔）：捶，打。\n居、诸：语助词。\n迭：更动。微：指隐微无光。\n澣（huàn浣）：洗涤。', poem_appreciation = '此诗到底为何人何事而作，历来争论颇多，迄今尚无定论。简略言之，汉代时不仅今古文有争议，而且今文三家也有不同意见。《鲁诗》主张此诗为“卫宣夫人”之作，后为刘向《列女传》之所本，《韩诗》亦同《鲁诗》说（见宋王应麟《诗考》）。《诗序》说：“《柏舟》言仁而不遇也卫顷公之时，仁人不遇，小人在侧。”这是以此诗为男子不遇于君而作，为古今文家言。今文三家，《齐诗》之说，与《诗序》同。\n\n　　自东汉郑玄笺《毛诗》以后，学者多信从《毛诗》说，及至南宋，朱熹大反《诗序》，作《诗序辩说》，又作《诗集传》，力主《柏舟》为妇人之诗，形成汉、宋学之争论。元、明以降，朱熹《诗集传》列为科举功名，影响颇大，学者又多信朱说，但持怀疑态度的亦复不少，明何楷、清陈启源、姚际恒、方玉润等皆有驳议，争论不休。\n\n　　至今尚未形成一致的意见，今人之《诗经》选注本、译注本各有所本，或主男著，或主女作。高亨《诗经今注》、陈子展《诗经直解》均以为男子作，而袁梅《诗经译注》、程俊英《诗经译注》又皆以为女子作。\n\n　　细究诗义，当以卫臣不遇于君之作为是，陈子展先生说得很准确：“今按《柏舟》，盖卫同姓之臣，仁人不遇之诗。诗义自明，《序》不为误。”此诗人的身份为男子 --- 而且是大臣，绝非平常男子（下文尚有论述），这从诗中“无酒”、“遨游”、“威仪”、“群小”、“奋飞”等词语即可看出。况且，主此诗为女子之作者的理由实不充分。刘向、朱熹之说均自相矛盾：刘向《列女传》虽以《柏舟》属之卫夫人，但是他在上封事，论群小倾陷正人时，两引此诗仍用《毛诗》义（《汉书·楚元王传·刘向传》，又在《说苑·立节》中引用此诗时，也用《毛诗》义，说“此士君子之所以越众也”‘朱熹先从刘向之“卫宣夫人”说，后又疑其为“庄姜”（《诗集传》），切在《孟子·尽心下》：“‘忧心悄悄，愠于群小’孔子也。”注曰：“《诗·邶风·柏舟》....本言卫之仁人见怒于群小。孟子以为孔之事可以当之。”是不能自圆其说的，也都是自语相违。\n\n　　另外，需要说明的是，此诗既属《邶风》，为何却咏卫国之事？原来“邶”、“鄘”、“卫”连地，原为殷周之旧都，武王灭殷后，占领殷都朝歌一带地方，三分其地。邶在朝歌之北，鄘。卫都朝歌，为成王封康叔之地，“邶、鄘始封，及后何时并入于卫，诸家均未详。....惟邶、鄘既入卫，诗多卫风，而犹系其故国之名。”（方玉润《诗经原始》）所以邶诗咏卫事也是可以理解的。另外，方玉润认为此诗可能即为邶诗，“安知非即邶诗乎?邶既为卫所并，其未亡也，国事必孱。......当此之时，必有贤人君子，......故作为是诗，以其一腔忠愤，不忍弃君，不能远祸之心。”也有一定的参考价值。\n\n　　这首诗凡五章。第一章写作者夜不能寐，原因是怀有深忧，无法排遣。首二句，“泛彼柏舟，亦泛其流”，以自喻，虽以喻国，以舟自喻，喻忧心之沉重而飘忽，以“舟喻国，泛泛然于水中流，其势靡所底止，为此而有隐忧，乃见仁人用心所在”（《诗经原始》）。诗一开始就写出了抒情主人公沉郁的心情。接着点明夜不成眠的原因是由于痛苦忧伤一齐涌积心头，这里既有国家式微之痛，又有个人不遇于君、无法施展抱负之苦。“隐忧”是诗眼，贯穿全篇。末二句写出了作者的忧国之心和伤己之情，即使美酒、遨游也不能排除自己的痛苦忧伤。何楷《诗经世本古义》云：“饮酒遨游，岂是妇人之事？”以驳朱熹之说，自有相当理由。第二章表明自己不能容让的态度和兄弟不可靠。“我心匪鉴，不可以茹”二句，表白不能逆来顺受之意，辞意坚决、果断，以镜作喻，说明自己不可能像镜子那样不分善恶美丑，将一切都加以容纳而照进去。“亦有兄弟，不可以据。”写兄弟之不可依靠。《孔疏》云：“此责君而言兄弟者，此仁人与君同姓，故以兄弟之道责之；言兄弟这正谓君与己为兄弟也。”虽过于落实，但从后两句“薄言往恕，逢彼之怒”看来，却与《离骚》中“茎不察余之中情兮”两句的意思相近，说它是借喻君主，未必不符合原意。第三章“我心匪石，不可转也！我心匪席，不可卷也！”表明自己坚定不移的刚强意志。这四句以“石”、“席”为喻，表明自己意志的坚定，语句凝重，刚直不阿，哪里有丝毫的“卑顺柔弱”之处（况且即使“辞气卑顺柔弱”也并不能作为妇人之诗之证）。“威仪棣棣，不可选也”二句，更是正气凛然，不可侵犯。尤其是“威仪”一词，决不可能是妇人的语气，特别是在古代男尊女卑的社会环境里。“威仪”从字面上讲，是庄严的仪容之意，《左传·襄公三十一年》记载北宫文子曾对卫侯论及“威仪”说：“有威而可畏谓之威，有仪而可象谓之仪。”并引“威仪棣棣，不可选也”为证，这还不能说明问题吗？另外全章六句，每二句的下句均用“不可”一词，形成否定排比句，铿锵有力，气势极其雄健。第四章写茕独无助，捶胸自伤，原因是被群小侵侮，一再遭祸受辱。“群小”一次对说明作者的身份很有用处，陈启源在《毛诗稽古编》中说：“朱子至谓群小为众妾，尤无典据。呼妾为小，古人安得有此称谓乎？”那么，“群小”“指虐待她的兄弟等人”行不行呢？回答也是否定的，因为果然如此，她就不可能“薄言往怒”了！所以“群小”，只能释为“一群小人”，犹《离骚》中之“党人”一样。第五章写含垢忍辱，不能摆脱困境，奋起高飞，由 　　此感叹统治者昏聩。首二句：“日居月诸，胡迭而微”，以日月蚀喻指蛛蛛昏聩不明。姚际恒曰：“喻卫之君臣昏暗而不明之意。”（《诗经通论》）中二句“心之忧矣，如匪纺衣”，喻写忧心之深，难以摆脱。严桀云：“我心之忧，如不纺濯其衣，言处在乱君之朝，与小人同列，其忍垢含辱如此。”（《诗缉。）末二句“静言思之，不能奋飞。”，写无法摆脱困境之愤懑。“奋飞”一词语意双关，既感愤个人处境困顿，无法展翅高飞，不能施展抱负，又慨叹国家式微振兴无望。我们不能想象，在那礼制重重，连许穆夫人家国破灭归唁卫侯都横遭阻拦的春秋时代，一个贵族妇人（或普通妇女）能高唱“奋飞”，有“想突破生活的樊笼，争取自由幸福”的思想。黄元吉云：“妇人从一而终，岂可奋飞？”（〈传说汇篆〉）比之将古代妇女思想现代话的倾向，还是基本无误的，虽然它也脱离了时代实际。\n\n　　这是一篇直诉胸臆，径陈感受，风格质朴的显示注意作品，“隐忧”为诗眼、主线，逐层深入地抒写爱国忧己之情，倾诉个人受群小倾陷，而主上不明，无法施展抱负的忧愤。首章便提出“忧”字，接着写不得“兄弟”的同情，深忧在胸，屋脊排遣；然后再写自己坚持节操，不随人转移；后边又写群小倾陷，而主上不明，只得捶胸自伤；最后抒发无法摆脱困境之愤懑，向最高统治者发出呼喊，从而将爱国感情表达得十分强烈。\n\n　　此诗最突出的艺术特色是善用比喻，而富于变化：首章“泛此彼舟，亦泛其流”，末章“日居月诸，胡迭而微”是隐喻，前者既喻国事飘摇不定，而不直所从，又喻己之忧心沉重而飘忽，后者喻主上为群小所谗蔽,忠奸不明。“心之忧矣，如匪纺衣”，为明喻，喻忧之缠身而难去。二章之“我心匪鉴”、三章之“我心匪石”，则均用反喻以表达自己坚定不移的节操。至于姚际恒在〈诗经通论〉中所说的“三‘匪’字前后错综则是指诗在句法上的表化，“我心匪席”连用排比句，而“我心匪鉴”句为单句。\n\n　　另外，诗的语言亦复凝重而委婉，激亢而幽抑，侃侃申诉，娓娓动听在〈诗经〉中别具一格。', poem_tags = '诗经,爱国' WHERE poem_title = '国风·邶风·柏舟' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '精美的红格信笺写满密密小字，说的都是我平生对你的爱慕之情。鸿雁飞翔云端且鱼儿游戏水里，这番满腹惆怅的情意难以传寄。在斜阳里我独自一人倚着西楼，遥远的群山恰好正对窗上帘钩。桃花般的人面不知到何处去了，唯有碧波绿水依旧向东方流去。', poem_notes = '红笺（从竹,戋( jiān)声）：红色的质地很好纸片或者条。供题诗、写信等用的(质量较高的)小幅纸张。\n平生意：这里是写的平生相慕相爱之意\n鸿雁：在古代，传说中的一种鸭科鸟（鸿雁）可以传递书信。也作书信的代称。“鸿雁传书”是中国古老的民间传说，因为鸿雁属定期迁徙的候鸟，信守时间，成群聚集，组织性强。古人当时的通信手段较落后，渴望能够通过这种“仁义礼智信”俱备的候鸟传递书信，沟通信息。\n斜阳：傍晚西斜的太阳。\n惆怅：失意，伤感。惆怅就是因为心中郁闷而不知道该干什么，忧伤和悲哀是表示的一种心理状态，而惆怅是强调一种迷茫，不知所措的感觉。', poem_appreciation = '此为怀人之作。词中寓情于景，以淡景写浓愁，言青山长在，绿水长流，而自己爱恋着的人却不知去向；虽有天上的鸿雁和水中的游鱼，它们却不能为自己传递书信，因而惆怅万端。\n\n　　词的上片抒情。起句“红笺小字，说尽平生意”语似平淡，实包蕴无数情事，无限情思。红笺是一种精美的小幅红纸，可用来题诗、写信。词里的主人公便用这种纸，写上密密麻麻的小字，说尽了平生相慕相爱之意。显然，对方不是普通的友人，而是倾心相爱的知音。\n\n　　三、四两句抒发信写成后无从传递的苦闷。古人有“雁足传书”和“鱼传尺素”的说法，前者见于《汉书·苏武传》，后者见于古诗《饮马长城窟行》（客从远方来），是诗文中常用的典故。作者以“鸿雁在云鱼在水”的构思，表明无法驱遣它们去传书递简，因此“惆怅此情难寄”。运典出新，比起“断鸿难倩”等语又增加了许多风致。\n\n　　过片由抒情过渡到写景。“斜阳”句点明时间、地点和人物活动，红日偏西，斜晖照着正在楼头眺望的孤独人影，景象已十分凄清，而远处的山峰又遮蔽着愁人的视线，隔断了离人的音信，更加令人惆怅难遣。“远山恰对帘钩”句，从象征意义上看，又有两情相对而遥相阻隔的意味。倚楼远眺本是为了抒忧，如今反倒平添一段愁思，从抒情手法来看，又多了一层转折。\n\n　　结尾两句化用崔护《题都城南庄》诗句：“人面不知何处去，桃花依旧笑东风”之意，略加变化，给人以有余不尽之感。绿水，或曾映照过如花的人面，如今，流水依然在眼，而人面不知何处，唯有相思之情，跟随流水，悠悠东去而已。\n\n　　此词以斜阳、遥山、人面、绿水、红笺、帘钩等物象，营造出一个充满离愁别恨的意境，将词人心中蕴藏的情感波澜表现得婉曲细腻，感人肺腑。全词语淡情深，闲雅从容，充分体现了词人独特的艺术风格。', poem_tags = '宋词三百首,爱情,怀人' WHERE poem_title = '清平乐·红笺小字' AND poem_author = '晏殊';
UPDATE edu_poem SET poem_translation = '爱在早晨的镜子里欣赏残妆，钗环插满在发丝丛中。\n不一会儿初升的太阳照在抹了胭脂的脸颊上，仿佛一朵红花苏醒绽放又仿佛要化开了一般。\n\n山泉绕着街道缓缓流去，万树桃花掩映着小楼。\n我（在楼上）悠闲地翻看道教书籍慵懒着没有起身，隔着水晶帘看（你在妆台前）梳头。\n\n著压（一种织布工艺）的红罗总是追逐时髦新颖的花样，绣着秦吉了（一种类似鹦鹉的鸟）花纹的纱布染着酒曲一样的嫩色。\n（你说）不要首先嫌布料的材质太薄弱，稍微有些经纬稀疏的帛才是最宜人的。\n\n曾经领略过苍茫的大海，就觉得别处的水相形见绌；曾经领略过巫山的云霭，就觉得别处的云黯然失色。\n即使身处万花丛中，我也懒于回头一望，这也许是因为修道，也许是因为你的缘故吧。\n\n当时百花齐放，我却偏偏摘了朵白色的梨花送给你这个皮肤洁白如玉的女子。\n如今我就像那两三棵树一样静静地站在江边，可怜只有一树绿叶和我一起度过残春。', poem_notes = '篸（zān）：古同“簪”。\n须臾（yú）：片刻，很短的时间。\n散漫：慢慢的。\n慵（yōng）：懒惰，懒散。\n水晶帘：石英做的帘子；一指透明的帘子。\n吉了（liǎo）：又称秦吉了，八哥。\n嫩麴（qū）：酒曲一样的嫩色。\n纰（pī）缦（màn）：指经纬稀疏的披帛。\n曾经沧海难为水：此句由孟子“观于海者难为水”（《孟子·尽心篇》）脱化而来，意思是已经观看过茫茫大海的水势，那江河之水流就算不上是水了。\n除却巫山不是云：此句化用宋玉《高唐赋》里“巫山云雨”的典故，意思是除了巫山上的彩云．其他所有的云彩都称不上彩云。\n取次：随便，草率地。\n缘：因为，为了。\n发：开放。\n白人：皮肤洁白的人。诗中指亡妻。', poem_appreciation = '其一\n\n　　其一是回忆情人晓镜中残妆慵懒的可人情态。诗人同韦丛结婚，二人恩爱无比，这首诗是“思”情人一夜恩爱晓起后残妆慵懒的动人情态。诗人不直接去抒写，而是“自爱残妆晓镜中”的情人，残妆晓镜中的她，钗环参差不齐，绿色丝缕丛杂不整。很快日出东方映照面颊红如一朵胭脂，脸庞肌肤红润柔腻好像要立即融化消溶一样，给读者展示了一幅明丽动人娇媚的风姿。\n\n　　其二\n\n　　元稹这首诗的一、二句，也给人以超凡绝尘之感。碧山清泉漫流，万树桃花掩映，已非崔护《题城南庄》“人面桃花”小家碧玉，楼中丽人定是美艳绝伦的仙姝无疑。置景由远及近，敷色自浅人深，焦点渐次凸现，为人物登场设置了悬念及具体环境氛围。诗是有声的画，画是无声的诗。如果两者与规定戏剧情景浑融，就会产生意想不到的绝佳艺术效果。\n\n　　三、四两句推出人物，工笔细描闺中“画眉”故事，对照着笔，角度则从一方眼中写出，此亦有助于丰富潜在的戏剧因素与人物心理层次。“闲读道书慵未起”，“道书”不管是致用明道的儒家经籍，或是羽客仙心的方外秘篆，“闲”字传神地刻画了心不在焉的可笑情态，是一层深曲对比；“慵”既描述一方眼中的楚楚可怜，又流露无限呵护挚爱深情，是二层深曲对比；风光旖旎的闺房之乐出以如此潇洒高雅笔致，是三层深曲对比。“水晶帘下看梳头”也有许多曲折：水晶帘与美人妆，一层；情人眼里看与被看，又一层；好景不长，水月镜花，则更深一层。苏轼《江城子》词云：“夜来幽梦忽还乡，小轩窗，正梳妆。”同样以“乐境写悲哀”，同样表现对亡妻死生不渝的深长思念，同样打破并浓缩了时空界限。所不同的是，苏词托之以梦，入而即出，“相顾无言，惟有泪千行”；元诗则沉浸一往情深的回忆，仿佛在银幕“定格”，痴看而竟不知所以了。水晶帘下看梳头”感性的神往，都能引导读者走向真善美诗境，从而具有普遍的道德价值与美学意义。 　　　　 　　其三\n\n　　这首诗运用了暗喻的手法，首二句写著压的红罗总是追逐新颖的花样，就好像别的女子总是一个比一个动人。绣着秦吉了花纹的轻纱染上了迷人的酒曲一样的嫩色，你不要说纱太薄，因为只有这样的纱才是最好的。正是因为亡妻韦丛典雅淡泊，贤惠端庄，诗人才把她比作经纬稀疏的纱布才是最好的，这固然是元稹对妻子的偏爱之词。却也只有深情者才能才能表现出这种天长地久的真挚。\n\n　　其四\n\n　　这首诗最突出的特色，就是采用巧比曲喻的手法，淋漓尽致地表达了主人公对已经失去的心上人的深深恋情。它接连用水、用云、用花比人，写得曲折委婉，含而不露，意境深远，耐人寻味。\n\n　　首二句“曾经沧海难为水，除却巫山不是云”，沧海无比深广，因而使别处的水相形见绌。巫山有朝云峰，下临长江，云蒸霞蔚。据宋玉《高唐赋序》说，其云为神女所化，上属于天，下入于渊，茂如松榯，美若娇姬。因而，相形之下，别处的云就黯然失色了。“沧海”、“巫山”，是世间至大至美的形象，诗人引以为喻，从字面上看是说经历过“沧海”、“巫山”，对别处的水和云就难以看上眼了，实则是用来隐喻他们夫妻之间的感情有如沧海之水和巫山之云，其深广和美好是世间无与伦比的，因而除爱妻之外，再没有能使自己动情的女子了。\n\n　　“难为水”、“不是云”，这固然是元稹对妻子的偏爱之词，但像他们那样的夫妻感情，也确乎是很少有的。元稹在《遣悲怀》诗中有生动描述。因而第三句说自己信步经过“花丛”，懒于顾视，表示他对女色绝无眷恋之心了。\n\n　　第四句即承上说明“懒回顾”的原因。元稹生平“身委《逍遥篇》，心付《头陀经》”（白居易《和答诗十首》赞元稹语），是尊佛奉道的。另外，这里的“修道”，也可以理解为专心于品德学问的修养。然而，尊佛奉道也好，修身治学也好，对元稹来说，都不过是心失所爱、悲伤无法解脱的一种感情上的寄托。“半缘修道”和“半缘君”所表达的忧思之情是一致的，而且，说“半缘修道”更觉含意深沉。\n\n　　其五\n\n　　“寻常百种花齐发，偏摘梨花与白人”，春天里百花齐放，诗人偏偏摘了朵白色的梨花送与自己的妻子，那个皮肤洁白如玉的女子。春天百花争奇斗艳，诗人摘了梨花，不就是因为自己的妻子不像其她女色，不仅贤惠端庄、通晓诗文，更重要的是出身富贵，却不好富贵，不慕虚荣，就好像那洁白的梨花，静静地在枝头绽放。可是，妻子已经过世，满树的梨花凋谢了，只剩下绿叶，孤零零地度过残春。诗人把运用比喻的手法，把梨花比作妻子，自己比作绿叶，抒发了对亡妻的无尽怀念。', poem_tags = '爱情,思念,组诗' WHERE poem_title = '离思五首' AND poem_author = '元稹';
UPDATE edu_poem SET poem_translation = '李白的诗作无人能敌，他那高超的才思也远远地超出一般人。\n李白的诗作既有庾信诗作的清新之气，也有鲍照作品那种俊逸之风。\n如今，我在渭北独对着春日的树木，而你在江东远望那日暮薄云，天各一方，只能遥相思念。\n我们什么时候才能同桌饮酒，再次仔细探讨我们的诗作呢？', poem_notes = '不群：不平凡，高出于同辈。这句说明上句，思不群故诗无敌。\n庾开府：指庾信。在北周官至骠骑大将军、开府仪同三司（司马、司徒、司空），世称庾开府。\n俊逸：一作“豪迈”。鲍参军：指鲍照。南朝宋时任荆州前军参军，世称鲍参军。\n渭北：渭水北岸，借指长安（今陕西西安）一带，当时杜甫在此地。\n江东：指今江苏省南部和浙江省北部一带，当时李白在此地。\n论文：即论诗。六朝以来，通称诗为文。细论文：一作“话斯文”。', poem_appreciation = '杜甫同李白的友谊，首先是从诗歌上结成的。这首怀念李白的五律，主要就是从这方面来落笔的。开头四句，一气贯注，都是对李白诗的热烈赞美。首句称赞他的诗冠绝当代。第二句是对上句的说明，是说他之所以“诗无敌”，就在于他思想情趣，卓异不凡，因而写出的诗，出尘拔俗，无人可比。接着赞美李白的诗像庾信那样清新，像鲍照那样俊逸。庾信、鲍照都是南北朝时的著名诗人。这四句，笔力峻拔，热情洋溢，首联的“也”、“然”两个语助词，既加强了赞美的语气，又加重了“诗无敌”、“思不群”的分量。\n\n　　对李白奇伟瑰丽的诗篇，杜甫在题赠或怀念李白的诗中，总是赞扬备至。从此诗坦荡真率的赞语中，也可以见出杜甫对李白的诗作十分钦仰。这不仅表达了他对李白诗的无比喜爱，也体现了他们的诚挚友谊。这四句是因忆其人而忆及其诗，赞诗亦即忆人。但作者并不明说此意，而是通过第三联写离情，自然地加以补明。这样处理，不但简洁，还可避免平铺直叙，而使诗意前后勾联，曲折变化。\n\n　　表面看来，第三联两句只是写了作者和李白各自所在之景。“渭北”指杜甫所在的长安一带；“江东”指李白正在漫游的江浙一带地方。“春天树”和“日暮云”都只是平实叙出，未作任何修饰描绘。分开来看，两句都很一般，并没什么奇特之处。然而作者把它们组织在一联之中，却有了一种奇妙的紧密的联系。也就是说，当作者在渭北思念江东的李白之时，也正是李白在江东思念渭北的作者之时；而作者遥望南天，惟见天边的云彩，李白翘首北国，惟见远处的树色，又见出两人的离别之恨，好像“春树”、“暮云”，也带着深重的离情。两句诗，牵连着双方同样的无限情思。回忆在一起时的种种美好时光，悬揣二人分别后的情形和此时的种种情状，这当中有十分丰富的内容。这两句，看似平淡，实则每个字都千锤百炼；语言非常朴素，含蕴却极丰富，是历来传颂的名句。《杜臆》引王慎中语誉为“淡中之工”，极为赞赏。\n\n　　上面将离情写得极深极浓，这就引出了末联的热切希望：“什么时候才能再次欢聚，像过去那样，把酒论诗啊！”把酒论诗，这是作者最难忘怀、最为向往的事，以此作结，正与诗的开头呼应。说“重与”，是说过去曾经如此，这就使眼前不得重晤的怅恨更为悠远，加深了对友人的怀念。用“何时”作诘问语气，把希望早日重聚的愿望表达得更加强烈，使结尾余意不尽，回荡着作者的无限思情。\n\n　　清代浦起龙说：“此篇纯于诗学结契上立意。”（《读杜心解》）道出了这首诗在内容和结构上的特点。全诗以赞诗起，以“论文”结，由诗转到人，由人又回到诗，转折过接，极其自然，通篇始终贯穿着一个“忆”字，把对人和对诗的倾慕怀念，结合得水乳交融。以景寓情的手法，更是出神入化，把作者的思念之情，写得深厚无比，情韵绵绵。', poem_tags = '怀念,赞美,写人' WHERE poem_title = '春日忆李白' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '欧阳先生（欧阳修自称）夜里正在读书，（忽然）听到有声音从西南方向传来，心里不禁悚然。他一听，惊道：“奇怪啊！”这声音初听时像淅淅沥沥的雨声，其中还夹杂着萧萧飒飒的风吹树木声，然后忽然变得汹涌澎湃起来，像是江河夜间波涛突起、风雨骤然而至。碰到物体上发出铿锵之声，又好像金属撞击的声音，再（仔细）听，又像衔枚奔走去袭击敌人的军队，听不到任何号令声，只听见有人马行进的声音。（于是）我对童子说：“这是什么声音？你出去看看。”童子回答说：“月色皎皎、星光灿烂、浩瀚银河、高悬中天，四下里没有人的声音，那声音是从树林间传来的。”\n\n　　我叹道：“唉，可悲啊！这就是秋声呀，它为何而来呢（它怎么突然就来了呢）？大概是那秋天的样子，它的色调暗淡、烟飞云收；它的形貌清新明净、天空高远、日色明亮；它的气候寒冷、刺人肌骨；它的意境寂寞冷落，没有生气、川流寂静、山林空旷。所以它发出的声音时而凄凄切切，呼号发生迅猛，不可遏止。绿草浓密丰美，争相繁茂，树木青翠茂盛而使人快乐。然而，一旦秋风吹起，拂过草地，草就要变色；掠过森林，树就要落叶。它能折断枝叶、凋落花草，使树木凋零的原因，便是一种构成天地万物的混然之气（秋气）的余威。秋天是刑官执法的季节，它在季节上说属于阴；秋天又是兵器和用兵的象征，在五行上属于金。这就是常说的天地之严凝之气，它常常以肃杀为意志。自然对于万物，是要它们在春天生长，在秋天结实。所以，秋天在音乐的五声中又属商声。商声是西方之声，夷则是七月的曲律之名。商，也就是‘伤’的意思，万物衰老了，都会悲伤。夷，是杀戮的意思，草木过了繁盛期就应该衰亡。”\n\n　　“唉！草木是无情之物，尚有衰败零落之时。人为动物，在万物中又最有灵性，无穷无尽的忧虑煎熬他的心绪，无数琐碎烦恼的事来劳累他的身体。只要内心被外物触动，就一定会动摇他的精神。更何况常常思考自己的力量所做不到的事情，忧虑自己的智慧所不能解决的问题？自然会使他红润的面色变得苍老枯槁，乌黑的头发（壮年）变得鬓发花白（年老）。（既然这样，）为什么却要以并非金石的肌体，去像草木那样争一时的荣盛呢？（人）应当仔细考虑究竟是谁给自己带来了这么多残害，又何必去怨恨这秋声呢？”\n\n　　书童没有应答，低头沉沉睡去。只听得四壁虫鸣唧唧，像在附和我的叹息。', poem_notes = '欧阳子：作者自称。\n方：正在。\n悚（sǒng）然：惊惧的样子。\n初淅沥以萧飒：起初是淅淅沥沥的细雨带着萧飒的风声。淅沥，形容轻微的声音如风声、雨声、落叶声等。以，表并列，而。萧飒，形容风吹树木的声音。\n砰湃：同“澎湃”，波涛汹涌的声音。\n鏦鏦（cōng）铮铮：金属相击的声音。\n衔枚：古时行军或袭击敌军时，让士兵衔枚以防出声。枚，形似竹筷，衔于口中，两端有带，系于脖上。\n明河：天河。\n秋之为状：秋天所表现出来的意气容貌。状，情状，指下文所说的“其色”、“其容”、“其气”、“其意”。\n惨淡：黯然无色。\n烟霏：烟气浓重。霏，散扬。\n云敛：云雾密聚。敛，收，聚。\n日晶：日光明亮。晶，亮。\n栗冽：寒冷。\n砭（biān）：古代用来治病的石针，这里引用为刺的意思。\n绿缛：碧绿繁茂。\n一气：指构成天地万物的混然之气。天地万物的变化都是“一气”运行的结果。\n余烈：余威。\n刑官：执掌刑狱的官。《周礼》把官职与天、地、春、夏、秋、冬相配，称为六官。秋天肃杀万物，所以司寇为秋官，执掌刑法，称刑官。\n有时：有固定时限。\n渥：红润的脸色。\n黟（yī）：黑。\n星星：鬓发花白的样子。', poem_appreciation = '本文是作者晚年所作。虽仕途已入顺境，但长期的政治斗争也使他看到了世事的复杂，逐渐淡于名利。秋在古代也是肃杀的象征，一切生命都在秋天终止。作者的心情也因为屡次遭贬而郁闷，但他也借秋声告诫世人：不必悲秋、恨秋，怨天尤地，而应自我反省。这一立意，抒发了作者难有所为的郁闷心情，以及自我超脱的愿望。\n\n　　这篇赋以“有声之秋”与“无声之秋”的对比作为基本结构框架，精心布局，文势一气贯串而又曲折变化，作者从凄切悲凉的秋声起笔，为下文铺写“有声之秋”蓄势；然后由草木经秋而摧败零落，写到因人事忧劳而使身心受到戕残，由自然界转到社会人生，这是“无声之秋”；最后归结出全篇主旨：“念谁为之戕贼，亦何恨乎秋声！”\n\n　　文章用第一人称的笔法来写。一开始作者就为我们描绘了一个从静到动，令人悚惊的秋夜奇声，营造了一种悲凉气氛。“欧阳子方夜读书，闻有声自西南来者，悚然而听之。”作者正在秋夜专心致志地读书，忽听一种奇特的声音从西南方传来。作者惊讶于这样的声音，细听，起初似雨声淅淅沥沥，又似风声潇潇飒飒，忽然又如波涛奔腾翻涌，又似狂风暴雨骤然而至。它接触到物体上，又发出如金铁相撞的鏦鏦铮铮的声音，又好像奔赴敌阵的军队，衔枚迅跑，听不到号令，只听到人马行进之声。\n\n　　作者用风声，波涛，金铁，行军四个比喻，从多方面和不同角度，由小到大，由远及近地形象地描绘了秋声状态。用形象化的比喻，生动鲜明地写出了作者听觉中的秋声的个性特点，融入了作者主观情感。\n\n　　接着作者引出与童子对话，从浮想联翩，又回到现实，增强了艺术真实感。作者对童子说：“此何声也？汝出视之。”童子回答：“星月皎洁，明河在天，四无人声，声在树间。”童子的回答，质朴简明，意境优美、含蓄。这里，作者的“悚然”与童子的若无其事，作者的悲凉之感与童子的朴拙稚幼形成鲜明对比，对秋声的两种不同的感受相映成趣，富于意味。作者在第一段通过悬念式的对声音的生动描绘，点明了文章主题即秋声。文章起始，就写得脉络清晰，波澜起伏，摇曳多姿，读者有一种身临其境之感。\n\n　　作者接着寻根溯源，探究秋声所以形成的缘由？“予曰：‘噫嘻悲哉！此秋声也，胡为而来哉？’”，自答曰：“盖夫秋之为状也，其色惨淡，烟霏云敛；其容清明，天高日晶；其气栗冽，砭人肌骨；其意萧条，山川寂寥。……”秋声，是秋天的声音，作者从秋之色，容，气，意四个方面把秋天的到来之后万物所呈现的风貌和秋之内在“气质”描绘得具体可感，其色颜容貌似乎呈现眼前，其栗冽之气似乎穿透衣服直刺肌肤，其萧条之意似已围裹全身。这种秋气，是一种肃杀之气，是让人速生冷颤之气。它只要施展它的一点余威，就会使繁茂蓊郁的绿色变色，葱茏的佳木凋零。这样，通过秋声的描绘和感受把“秋”之威力作了形象化的描绘。“秋”何以有这样的威力和会使人产生如此的感受呢？\n\n　　接着，作者又从社会和自然两个方面，对秋声进行了剖析和议论。“夫秋，刑官也，于时为阴；又兵象也，于行用金；是谓天地之义气，常以肃杀而为心。天之于物，春生秋实。故其在乐也，商声主西方之音；夷则为七月之律。商，伤也，物即老而悲伤；夷，戮也，物过盛而当杀。”古代用天地、四时之名命官，如天官冢宰、地官司徒、春官宗伯、夏官司马、秋官司寇、冬官司空，这是六官。司寇掌刑法。故秋天是古代刑官行刑的季节。在四季中又属阴冷的季节；春夏为阳，秋冬为阴。从五行来分，秋属金，由古代多以秋天治兵，“沙场秋点兵”，所以秋又有战争的象征；这样，秋天对人来说，意味着有悲凉肃杀死亡之气。从自然界来看，天地万物，春天生长，秋天结实，意味着自然界中生命由盛转衰的过程，人与此同，故有对生命将息的悲叹与伤感。又以音乐为喻，古人将五声（宫、商、角、徵、羽）和四时相配，秋属商，又将五行和东、南、中、西、北五个方位相配，秋主西方，秋属于商声，商，伤也，悲伤之意。夷则，是七月的音律，古音分十二律，夷则为十二律之一。将乐律和历法联系起来，，十二律与十二月相配，夷则配七月。《礼记?月令》：“孟秋之月，律中夷则。”夷，是删刈，杀戮之意。万物由繁荣到衰败，则为自然之规律。作者从自然与社会两方面进行了论述，人是自然的一部分，又是社会的产物，人与自然、社会形成一个相互联系的有机整体。人从个人出发体验感悟自然和社会。这体现了中国“天人合一”的思想。\n\n　　接着作者仍然抓住秋声的主题，通过无情的草木与万物中最有感情，最有灵性的人的对比，抒发议论。作者认为，百般的忧虑和万事的操劳必然损伤着人的身心，内心受到刺激和痛苦，必然损耗精力，更何况是“思其力之所不及，忧其智之所不能”呢！这样就容易朱颜易老，乌发变白，“奈何以非金石之质，欲与草木而争荣？”这是你自己无穷无尽的忧劳伤害了自己，又何必去怨恨秋声的悲凉呢？这就说明了作者之所以感到秋声之悲凉，其根源不在秋声，主要是当时作者面对国家和自己的处境而产生的忧思所致。当时作者被朝廷重用，但想起曾经在政治上屡不得志，怀才不遇，报国无门，心情郁闷。这样的情绪和秋季气息正相统一，触物伤情，有感而发。\n\n　　作者蓄积已久的深沉苦闷和悲凉没有人能理解。“童子莫对，垂头而睡。”唯有四壁的虫鸣，与“我”一同叹息。此情此景是何等悲凉：秋风呼号，秋声凄切，长夜漫漫，虫声唧唧，悲愤郁结，无可奈何，只能徒然叹息。\n\n　　此文，把写景、抒情、记事、议论熔为一炉，浑然天成。作者叙事简括有法，而议论迂徐有致；章法曲折变化；而语句圆融轻快；情感节制内敛；语气轻重和谐；节奏有张有弛；语言清丽而富于韵律。在这个秋气正浓的季节，不妨打开《秋声赋》，一方面欣赏作者优美的文字所带给你的艺术美感，另一方细细品味秋之色、之容、之气、之意，体验自然和人生。\n\n　　作者把无形的秋声写得可见可闻。文章开头便用形象的比喻描写秋夜西风渐起，触物有声，再用星月皎洁、四无人声加以烘托，一萧瑟幽森的画面便呈现在读者面前；最后以“四壁虫声唧唧”收尾，也紧扣住季节的特色。中间两大段用赋体的传统铺陈手法，渲染秋天的肃杀和万物的凋零，抒写对人事忧劳的悲感，最后“念谁为之戕贼，亦何恨乎秋声”，又转喻祸根在人，发挥了清心寡欲的老庄哲学，反映了作者对人生的感悟。写景、抒情、议论有机地融为一体，显示出文赋自由挥洒的韵致。\n\n　　《秋声赋》作于嘉祐四年（1059），欧阳修时年53岁，这是他继《醉翁亭记》后的又一名篇。它骈散结合，铺陈渲染，词采讲究，是宋代文赋的典范。\n\n　　文章第一段写作者夜读时听到秋声，从而展开了对秋声的描绘。文章开头，作者简捷直人地描画了一幅生动的图景：欧阳修晚上正在读书，被一种奇特的声音所搅动。这简捷的开头，实际上并不简单，灯下夜读，是一幅静态的图画，也可以说，作者正处于一处凝神的状态中。声音的出现是以动破静，引起了作者的注意，不禁去倾听它，同时，也就惹动了文思。这样由伏到起，在动静的对比中，文势便蓄成了，有了这种文势，下面的文章便仿佛是泉水涌出，自然流泻。接下来，是作者对秋声一连串的比喻，把难以捉摸的东西变得具体可感。作者通过由“初”到“忽”，再到“触于物”，写出了由远而近、由小到大、凭虚而来的撞击物体的秋声夜至的动态过程，突出了秋声变化的急剧和来势的猛烈。这也就回答了作者闻声惊惧和感叹的原因。\n\n　　第二段是对秋声的描绘和对秋气的议论。首先，作者概括了平日观察所得，运用骈偶句式和铺张渲染的赋的传统手法，抓住烟云、天日、寒气、山川等景物，分别就秋的色、容、气、意，描绘出了秋状的四幅具有不同特征的鲜明图画。而对秋状的描绘，正是为了烘托秋声的“凄凄切切，呼号愤发”。然后，是对秋气的议论。“丰草”四句，作者把草木在夏天和秋季作对比，通过对比，指出草木之所以摧败零落，是秋气施加强大威力的结果。在此基础上，议论又进一步展开。“夫秋，刑官也”到这一段结束，作者吸收前人种种说法，又运用骈偶句把秋与官制、阴阳、五行、音律等配属起来，甚至用“伤”解释“商”，用“戮”解释“夷”，极力铺张，突出秋对万物的强大摧残力量，说明万物盛衰的自然之理。这是宇宙生成的哲学思考，写出了秋声中永恒的悲伤，为下文进入本文主题起了铺垫作用。\n\n　　第三段是全文的题旨所在，作者由感慨自然而叹人生，百感交集，黯然神伤。这一段，作者在极力渲染秋气对自然界植物摧残的基础上，着力指出，对于人来说，人事忧劳的伤害，比秋气对植物的摧残更为严重。\n\n　　第四段是全篇的结束，作者从这些沉思冥想中清醒过来，重新面对静夜，只有秋虫和呜，衬托着作者悲凉的心境。结尾处秋虫的和鸣，更衬出作者的感慨与孤独。戛然而止的结尾，给文章增添了不少的感染力，在秋虫唧唧中，读者似乎也要同声一叹。\n\n　　欧阳修在宋仁宗嘉佑占四年(1059)春天辞去开封府尹的职务，专心著述。这时的欧阳修，在政治上早已经历了多次贬官，对政治和社会时局心情郁结，对人生短暂、大化无情感伤于怀，正处于不知如何作为的苦闷时期。在《秋声赋》中，作者以“无形”的秋声作为描写和议论的对象，采用赋的形式抒写秋感，极尽渲染铺陈之能事，实际上融入了作者对宦海沉浮、人生苦短深沉的感慨。\n\n　　《秋声赋》写秋以立意新颖著称，从题材上讲，悲秋是中国古典文学的永恒题材，但欧阳修选择了新的角度人手，虽然承袭了写秋天肃杀萧条的传统，但却烘托出人事忧劳更甚于秋的肃杀这一主题，这就使文章在立意上有所创新。\n\n　　更应该提到的，应是《秋声赋》在文体上的贡献。注重骈偶铺排以及声律的赋到了宋代以后，由于内容的空乏和形式上的矫揉造作，已经走向没落。欧阳修深明其中之弊，当他的散文革新取得了成功之后，回过头来又为“赋’’体打开了一条新的出路，即赋的散文化，使赋的形式活泼起来，既部分保留了骈赋、律赋的铺陈排比、骈词俪句及设为问答的形式特征，又呈现出活泼流动的散体倾向，且增加了赋体的抒情意味。这些特点也使《秋声赋》在散文发展史上占有了一席很重要的地位。\n\n　　还有一点必须指出的是，在赏析该文时，应取其精华，去其糟粕。不应该受古人消极情绪的影响。 “悲秋”是历代文人骚客写作的主题，他们借对秋的悲，抒发对时政不满而产生的郁闷心情；感叹自己怀才不遇，宦海沉浮，人生艰难的不幸遭遇。 欧阳先生的《秋声赋》在立意方面，虽然通过感伤秋之肃杀而烘托出感伤世事之肃杀，但仍然难免有很浓的悲伤情调。\n\n　　文章第三段开头“嗟乎”二字多么淋漓尽致地表达了悲伤的情感；而此段的最后“奈何”、“念谁”两句更体现了作者凄苦愁闷的心情。\n\n　　古代的封建文人墨客，因为受时代的局限和传统人生观、世界观的束缚，因秋而生悲的伤感情绪是必然的。我们不能苛求古人而指责他们的消极情绪。建议大家在欣赏《秋声赋》这篇脍炙人口的文章时有必要读读毛泽东主席的《浪淘沙·北戴河》和现代作家俊青的散文《秋色赋》。', poem_tags = '辞赋精选,古文观止,秋天,悲秋' WHERE poem_title = '秋声赋' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '交了不好的运气我又能怎么办呢？想摆脱却被碰得头破血流。\n破帽遮脸穿过热闹的集市，像用漏船载酒驶于水中一样危险。\n横眉怒对那些丧尽天良、千夫所指的人，俯下身子甘愿为老百姓做孺子牛。\n坚守自己的志向和立场永不改变，不管外面的环境发生怎样的变化。', poem_notes = '华盖：星座名，共十六星，在五帝座上，今属仙后座。旧时迷信，以为人的命运中犯了华盖星，运气就不好。\n破帽：原作“旧帽”。\n漏船载酒：用《晋书·毕卓传》中的典故：“得酒满数百斛（hú）……浮酒船中，便足了一生矣。”漏船：原作破船”。“中流：河中。\n横眉：怒目而视的样子，表示愤恨和轻蔑。\n孺子牛：春秋时齐景公跟儿子嬉戏，装牛趴在地上，让儿子骑在背上。这里比喻为人民大众服务，更指小孩子，意思是说鲁迅把希望寄托在小孩子身上，就是未来的希望。\n成一统：意思是说，我躲进小楼，有个一统的小天下。\n管他冬夏与春秋：即不管外在的气候、环境有怎样的变化。', poem_appreciation = '“运交华盖欲何求，未敢翻身已碰头。”其中“运交华盖”是说生逢豺狼当道的黑暗社会，交了倒霉的坏运。“欲何求”、“未敢”都带有反语的意味，是极大的愤激之词，反衬出当时国民党统治者的残暴，形象地描画和揭示了一个禁锢得像密封罐头那样的黑暗社会，概括了作者同当时国民党的尖锐的矛盾冲突。表明他对当时国民党统治者不抱任何幻想，对当时的政治环境极端蔑视和无比的憎恨。由此衬托无产阶级战士不畏强暴，碰壁不回的革命精神。\n\n　　“破帽遮颜过闹市，漏船载酒泛中流。”其中“闹市”喻指敌人猖獗跋扈、横行霸道的地方。“中流”指水深急处。这联用象征的手法，讲形势非常险恶。作者在“破帽“与“闹市”， “漏船”与“中流”这两不相应且对立的事物中，巧妙地运用了一个“过”和一个“泛”，再一次形象地表现出作者临危不惧、激流勇进的战斗精神，衬托出革命战士在险恶环境中是何等的英勇顽强、机智灵活。这两句诗流露出诙谐、乐观的情趣，表现出寓庄于谐的特色。\n\n　　“横眉冷对千夫指，俯首甘为孺子牛。”是全诗的核心和精髓，集中地体现出作者无产阶级的世界观。前四句叙写处境和战斗行动，这两句揭示内心深处的感情，把全诗的思想境界推到了高峰。这两句诗，表达作者对人民的强烈的爱和对敌人的强烈的憎，表现了作者在敌人面前毫不妥协，为人民大众鞠躬尽瘁的崇高品德。这句是全诗主题的集中体现，也是作者感情表达的最高潮。\n\n　　“躲进个楼成一统，管他冬夏与春秋。”其中“小搂”是作者居住的地方。“躲进”有暂时隐避下来的意思。 “躲“字，融合着巧与敢的双重意味。前一句十分风趣地道出了作者当时战斗环境的特点和善于斗争的艺术，反映出作者自信、乐观的心境和神情。后一句写无所畏惧、韧战到底的决心。这就把前一句的战斗内容揭示得更加鲜明，使寓庄于谐的特色表现得更加突出。既表明作者不管形势怎样变幻，前途如何艰险，决心为革命坚持不懈地斗争，又是对当时国民党统治者出卖民族利益的罪行的辛辣讽刺。这一语双关的结尾，增强了本诗的主题。\n\n　　这首诗是一首抒情诗，是作者鲁迅从自己深受迫害，四处碰壁中迸发出的愤懑之情，有力地揭露和抨击了当时国民党的血腥统治，形象地展现了作者的硬骨头性格和勇敢坚毅的战斗精神。', poem_tags = '励志' WHERE poem_title = '自嘲' AND poem_author = '鲁迅';
UPDATE edu_poem SET poem_translation = '天下的事情有困难和容易的区别吗？只要肯做，那么困难的事情也变得容易了；如果不做，那么容易的事情也变得困难了。人们做学问有困难和容易的区别吗？只要肯学，那么困难的学问也变得容易了；如果不学，那么容易的学问也变得困难了。\n　　我天资愚笨，赶不上别人；我才能平庸，赶不上别人。我每天持之以恒地提高自己，等到学成了，也就不知道自己愚笨与平庸了。我天资聪明，超过别人；能力也超过别人，却不努力去发挥，即与普通人无异。孔子的学问最终是靠不怎么聪明的曾参传下来的。如此看来聪明愚笨，难道是一成不变的吗？\n　　四川边境有两个和尚，其中一个贫穷，其中一个富裕。穷和尚对有钱的和尚说：“我想要到南海去，你看怎么样？”富和尚说：“您凭借着什么去呢？”穷和尚说：“我只需要一个盛水的水瓶一个盛饭的饭碗就足够了。”富和尚说：“我几年来想要雇船沿着长江下游而（去南海），尚且没有成功。你凭借着什么去！”到了第二年，穷和尚从南海回来了，把到过南海的这件事告诉富和尚。富和尚的脸上露出了惭愧的神情。\n　　四川距离南海，不知道有几千里路，富和尚不能到达可是穷和尚到达了。一个人立志求学，难道还不如四川边境的那个穷和尚吗？因此，聪明与敏捷，可以依靠但也不可以依靠；自己依靠着聪明与敏捷而不努力学习的人，是自己毁了自己。愚笨和平庸，可以限制又不可以限制；不被自己的愚笨平庸所局限而努力不倦地学习的人，是靠自己努力学成的。', poem_notes = '1、资：天资，天分。之：助词。\n2、倍人：“倍于人”的省略。\n3、屏：同“摒”，除去、排除。\n4、圣人：指孔子。卒：终于。鲁：迟钝、不聪明。\n5、鄙：边远的地方。\n6、南海：指佛教圣地普陀山。\n7、何恃：“恃何”的倒装。恃，凭借、依靠。\n8、钵：和尚用的饭碗。\n9、买舟：租船。买，租、雇的意思。\n10、顾不如：难道还不如。顾，难道。\n11、自败者也：判断句，表示肯定，靠自己努力学成的。', poem_tags = '初中文言文,学习,哲理,故事' WHERE poem_title = '为学一首示子侄' AND poem_author = '彭端淑';
UPDATE edu_poem SET poem_translation = '一个住在乡下以养蚕为生的妇女，昨天到城市里去赶集并且出售蚕丝。回来的时候，她却是泪流不断，伤心的泪水甚至把手巾都浸湿了。\n因为她在都市中看到，全身穿着美丽的丝绸衣服的人，根本不是像她这样辛苦劳动的养蚕人！', poem_notes = '蚕妇：养蚕的妇女。蚕，一种昆虫，吐出的丝是重要的纺织原料，主要用来纺织绸缎。\n市：做买卖或买卖货物地方。这里是指卖出蚕丝。\n巾：手巾或者其他的用来擦抹的小块布。\n遍身：全身上下。罗绮：丝织品的统称。罗，素淡颜色或者质地较稀的丝织品。绮，有花纹或者图案的丝织品。在诗中，指丝绸做的衣服。', poem_appreciation = '诗首两句写蚕妇的伤感。妇人昨天进城里去卖丝，回来的时候却是痛哭流泪。“泪满巾”可以看出蚕妇感情刺激之深。诗人用朴素的语言无声地揭示了社会的极端不公。通过对一个蚕妇经历与感受的叙写，表达了对下层劳动人民处境的深刻同情。诗中不着一字议论，却无声地控诉了以养蚕为生、深居僻乡的劳动妇女这一形象。蚕妇初次进城，竟发现了自己贫困终生的根源，难怪她要悲伤，要痛哭流泪了。那位蚕妇的神态、见闻、感受都写得绘声绘色、有血有肉，就以这么一个生活细节，来深刻揭露封建社会制度的极端不合理，立意深刻，构思巧妙，显示了诗人对生活的敏锐洞察力和高度概括力。\n\n　　后两句揭示蚕妇是因为有感于获而不劳、劳而不获的不合理社会现实而伤感。蚕妇之所以会痛哭流泪，是因为她看到，城里身穿丝绸服装的人，都是有权有势的富人。像她一样的劳动人民，即使养一辈子蚕，也是没有能力穿上美丽的丝绸衣服的。诗人用明显对比的手法概括封建社会阶级对立的现实，揭露统治者不劳而获的不合理现实，极有说服力。\n\n　　这是一首言简意赅的讽喻诗，诗人借养蚕妇女的所见所感，把养蚕人衣不蔽体，不养蚕人却穿着满身绸缎加以对比，深刻地揭露了封建社会劳动人民的劳动成果遭到剥削掠夺的不合理现象。诗中反映了劳动人民生活的悲苦，表达了诗人对养蚕农妇的同情，对不劳而获的剥削阶级的愤恨，以及对整个封建社会的控诉和鞭挞。', poem_tags = '古诗三百首,妇女,感伤,同情,早教古诗100首' WHERE poem_title = '蚕妇' AND poem_author = '张俞';
UPDATE edu_poem SET poem_translation = '生活当中身上包裹着粗衣劣布，胸中有学问气质自然光彩夺人。\n不喜欢陪伴着老儒一块清谈过“烹瓠叶”那样的苦日子，决定随从举子们参加科举考试。\n口袋里没有钱不置办那“看花”的马，但会看取令人眼花缭乱的“择婿车”。\n考试得中仍然可以向世俗的人们夸耀，诏书上如鸦的黑字新写着俺的名字。', poem_notes = '董传：字至和，洛阳（今属河南）人。曾在凤翔与苏轼交游。宋神宗熙宁二年（1069）卒。\n麤（cū）缯：粗制的丝织品。麤：同“粗”。大布：古指麻制粗布。《左传·闵公二年》：“卫文公大布之衣，大帛之冠。”杜预注：“大布，粗布。”裹：经历。生涯：人生的境遇过程。语本《庄子·养生主》：“吾生也有涯，而知也无涯。”\n腹有：胸有，比喻学业有成。诗书：原指《诗经》和《尚书》。此泛指书籍。气：表于外的精神气色。华：丰盈而实美。\n老儒：旧谓年老的学人。唐牟融《寄周韶州》诗：“十年学道困穷庐，空有长才重老儒。”瓠叶：《诗经·小雅》的篇名。共四章。根据诗序：瓠叶，大夫刺幽王也。或以为燕饮之诗。首章二句为：幡幡瓠叶，采之亨之。\n举子：指被推荐参加考试的读书人。槐花：豆科植物槐的干燥花及花蕾。夏季花开放或花蕾形成时采收，及时干燥，除去枝、梗及杂质。前者习称“槐花”，后者习称“槐米”。踏槐花：唐代有“槐花黄，举子忙”俗语，槐花落时，也就是举子应试的时间了，后因称参加科举考试为“踏槐花”。\n囊空不办：引自《南史‧虞玩之传》：“玩之为少府，犹蹑屐造席。高帝取屐亲视之，讹黑斜锐，瓒断以芒接之。问曰：‘卿此屐已几载？’玩之曰：‘初释褐拜征北行佐买之，著已三十年，贫士竟不办易。’”引用孟郊诗而不直接引用其诗语，只将“春风得意马蹄疾，一日看尽长安花。”之诗意转化为“寻春马”；引用虞玩之因贫困而旧屐著三十年不办易的事典，而转化为“囊空不办”，引用二个典故融合为一句，语多转折。囊空：口袋里空空的，比喻没有钱。唐杜甫《空囊》诗：“囊空恐羞涩，留得一钱看。”寻春马：引用孟郊《登科后》诗：“昔日龌龊不足夸，今朝放荡思无涯。春风得意马蹄疾，一日看尽长安花。”\n择婿车：此指官贾家之千金美女所座之马车，游街以示择佳婿。唐代进士放榜，例于曲江亭设宴。其日，公卿家倾城纵观，高车宝马，于此选取佳婿。见五代王定保《唐摭言·慈恩寺题名游赏赋咏杂纪》。\n得意：即“春风得意”，意谓黄榜得中。唐赵氏《闻夫杜羔登第》诗：“良人得意正年少，今夜醉眠何处楼。”世俗：社会上流传的风俗习惯。《文子·道原》：“矜伪以惑世，畸行以迷众，圣人不以为世俗。”\n诏黄：即诏书，诏书用黄纸书写，故称。《南史·王韶之传》：“恭帝即位，迁黄门侍郎，领著作，西省如故。凡诸诏黄皆其辞也。”字如鸦：诏书写的黑字。语出唐人卢仝《示添丁》“忽来案上翻墨汁，涂抹诗书如老鸦”。', poem_appreciation = '“厌伴老儒烹瓠叶，强随举子踏槐花。”这两句是说董传的志向，不甘心过贫苦的日子，希望通过科举出人头地。老儒是指年老的学人。“烹瓠叶”是用典。《诗经·小雅·瓠叶》，首章二句为“幡幡瓠叶，采之亨之”。瓠叶味苦，诗中以瓠叶言其宴席上菜肴的粗陋和简约，但主人并没有以其微薄而废礼，而是情真意挚地“采之亨之”（“亨”同“烹”）。\n\n　　“囊空不办寻春马，眼乱行看择婿车。”“寻春马”是暗用孟郊《登科后》的典故。这里苏轼是说董传即便登科也没钱置办马匹，像孟郊那样“一日看尽长安花”。“择婿车”是用王定保《唐摭言·慈恩寺题名游赏赋咏杂纪》所载唐进士放榜日公卿家倾城选取佳婿，“钿车珠鞍，栉比而至”的典故。苏轼的意思是说，董传虽不能像孟郊那样骑马看花，但却有机会被那“选婿车”包围，让自己眼花缭乱。这两句诗是苏轼鼓励董传的话，有钱没钱不是问题，考中才是硬道理，那时什么都会有。\n\n　　“得意犹堪夸世俗，诏黄新湿字如鸦。”这两句诗是承接上两句，继续对董传给予鼓励，希冀董传能够有朝一日，可以金榜题名，扬眉吐气，以夸世俗。苏轼写到这里，似乎完全忘记了此诗开头的“腹有诗书气自华”，剩下的就只有对一个不得意书生的一点祝福了。\n\n　　这首诗的特点是巧于用典，蕴藉含蓄。其中“腹有诗书气自华”，是至今让人传诵于口的名句。“诗书”在这里泛指书籍；“气”是指气质风度；“华”指有光彩，与众不同。脱开诗中赞扬董传的语境，单独来看，“腹有诗书气自华”的意思就是：那些勤于读书的人身上总会一种儒雅之气自然地流露出来，使他们看起来与众不同。正因为它概括出了读书人当中普遍存在的一种现象，所以才成为了有关读书学习方面的诗词名句，被广泛引用。', poem_tags = '送别,议论,读书,写人,修养' WHERE poem_title = '和董传留别' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '野草蔓蔓连成片，草上露珠亮闪闪。有位美女路上走，眉清目秀美又艳。不期而遇真正巧，正好适合我心愿。\n野草蔓蔓连成片，草上露珠大又圆。有位美女路上走，眉清目秀美容颜。不期而遇真正巧，与她幽会两心欢。', poem_notes = '蔓（màn）草：蔓延生长的草。蔓：蔓延。一说茂盛。\n零：降落。漙（tuán）：形容露水多。\n清扬：目以清明为美，扬亦明也，形容眉目漂亮传神。婉：美好。\n邂（xiè）逅（hòu）：不期而遇。\n适：适合。\n瀼（ráng）：形容露水浓，多。\n偕臧（cáng）：一同藏匿，指消失这草木丛中。臧，同“藏”。', poem_appreciation = '这首诗写的是非常浪漫而自由的爱情：良辰美景，邂逅丽人，一见钟情，便携手藏入芳林深处，恰如一对自由而欢乐的小鸟，一待关关相和，便双双比翼而飞。\n\n　　率真的爱情，形诸牧歌的笔调，字字珠玉，如歌如画。诗分二章，重复叠咏。每章六句，两句一层，分写景、写人、抒情三个层次，而典型环境、典型人物与典型感情齐备，可谓出之无心而天然合作。\n\n　　美好的环境和有着美丽眉目的姑娘，从小伙子的视角见出，楚楚有致，格外动人。“野有蔓草，零露漙兮”两句是兼赋的兴句，勾勒出一派春草青青、露水晶莹的良辰美景。春晨的郊野，春草葳蕤，枝叶蔓延，绿成一片；嫩绿的春草，缀满露珠，在初日的照耀下，明澈晶莹。在这清丽、幽静的春晨郊野，“有美一人，清扬婉兮”，意思是说，一位美丽的姑娘含情不语，飘然而至，那露水般晶莹的美目，秋波一转，顾盼流转，妩媚动人。这四句诗俨然是一幅春日丽人图，先写景，后写人，堪称是“诗中有画”（苏轼语），画中有人。而在修长的蔓草、晶莹的露珠与少女的形象之间，有着微妙的隐喻，能引发丰富的联想。“清扬婉兮”的点睛之笔，表现了姑娘惊人的美丽。小伙子见到这一切，爱悦之情怎能不喷涌而出。“邂逅相遇，适我愿兮。”这里，有对姑娘的惊叹，有对不期而遇的惊喜，更有对爱神突然降临的幸福感和满足感。\n\n　　第一章与第二章之间的空白，可理解为姑娘小伙相对凝视之时，此时无声胜有声的静场；次章前五句的重叠复唱，可理解为小伙子心情略为平静后，向姑娘倾诉的爱慕之意和殷殷之情。然而，在这人性纯朴的时代，又值仲春欢会之时，无需絮絮长谈，更不必繁文缛节。“邂逅相遇，与子偕臧。”只要两情相愿，便结百年之好；毋须父母之命、媒妁之言，自可永结同心。\n\n　　德国美学家黑格尔说：“灵魂集中在眼睛里，灵魂不仅要通过眼睛去看事物，而且也要通过眼睛才被人看见”（《美学》第一卷）。其实，艺术描写的这一美学原则，二千多年前中国的民间诗人已心领神会，运用娴熟。从《卫风·硕人》的“巧笑倩兮”“美目盼兮”，到《郑风·野有蔓草》的“清扬婉兮”“婉如清扬”，都是通过流盼婉美的眼睛，写姑娘的美丽。在短小的抒情篇章中，只有通过传神的“点睛”之笔，才可能写活人物；而在陌生男女邂逅相遇之时，四目注视，相对而望，也是最自然的表情。因而，这里的“点睛”之笔，可以说虽着力而极自然。', poem_tags = '诗经,爱情' WHERE poem_title = '国风·郑风·野有蔓草' AND poem_author = '佚名';
UPDATE edu_poem SET poem_tags = '元宵节,杂剧,表演' WHERE poem_title = '汴京元夕' AND poem_author = '李梦阳';
UPDATE edu_poem SET poem_tags = '初中文言文,神话,故事' WHERE poem_title = '共工怒触不周山' AND poem_author = '佚名';
UPDATE edu_poem SET poem_appreciation = '黄孝迈的词流传很少，但他的词的确写得“风度婉秀，真佳词也。”（万树《词律》）\n\n　　“清歌”与“黄昏”所含的情绪本是相反的，前者引人愉悦，后者使人忧伤，相反相成，其结果是益增忧伤之感，故此二句表现为极其沉痛的感叹口吻。接下来，作者进一步采用了拟人手法，将具有感知的品格赋予了柳花，想对它低声倾诉自己的心事，转而又：“怕柳花轻薄，不解伤春”。可见作者忧思之深重。“伤春”二字，点出了作品主旨之所在。再下面，是作者自己感叹当时旅行在湘水之滨，独自投宿在旅舍时的孤寂心情。明明要写冷落，却偏用“温存”的字眼，再用“谁与”来作反诘，这种写法突现了一种炽烈追求的意愿。写到此处，已近过片，须得由伤春向恨别过渡，故而“柔情别绪”四字的安排也就是相当巧妙而颇具匠心的了。\n\n　　这首词的下片更为精采。前几句，作者紧紧抓住“湘春夜月”的景色特点，将深沉的离愁别恨熔铸进去，造成了动人的艺术效果：“空樽夜泣，青山不语，残照当门。翠玉楼前，惟是有、一波湘水，摇荡湘云。”这个境界是由众多形象构筑起来的一个整体，七宝楼台固不应拆碎，然而，倘求观察得细致，却无妨从局部着眼。“空樽夜泣”，表示心情的极度忧伤，是一个凝炼警策的句子，其造语则显得老辣，与姜夔《暗香》词里的“翠樽易泣”相同。“青山不语”，山峰不会说话，而作者却好像认为它原是会说话的，只是此时此刻无话可说罢了，以这种方式描摹环境的幽静，其艺术效果则更为强烈。“残照当门”，意谓残月照在门前，门外唯见残月。残月象征离别，正是由于它的情调凄恻。“今宵酒醒何处？杨柳岸，晓风残月”（柳永《雨霖铃》）等常见的例子，已经足以说明用残月抒写离别之情的艺术表现力了。“翠玉楼”，即前文“楚乡旅宿”，“惟是有”，同义重叠，起着强调下文的作用，而它以“平去上”的声韵作为引出下文的铺垫，从而使“一波湘水，摇荡湘云”一句更富有诗意，显得更加突出。从“翠玉楼”望去，月色下的湘江，一片朦胧迷茫，水面上只看到隐隐的波光，天空飘动着朵朵浮云，阵阵微风吹来，又将水天“摇荡”在一起了。然而这轻微的摇荡却不能打破“青山不语，残月当门”的静寂，正像“蝉噪林逾静”那样，反倒更增强了这种静寂之感；同时，在静寂之中，“湘春夜月”的景色更显得空灵深邃，它启迪着人们对生活的沉思。\n\n　　下片的后几句，像上片点出“伤春”一样，又将“恨别”的题旨点明了。“天长梦短，问甚时、重见桃根？”“天”是宇宙，“梦”是人生，“天长梦短”与吴文英在的“春宽梦窄”（《莺啼序》）构思相同，富有哲学意味。如梦的人生既然短暂，离别的愁苦就更使人难耐，于是又自然地产生了一种急切的希望尽快地“重见桃根”。桃根，出于东晋的《桃叶歌》：“桃叶复桃叶，桃叶连桃根。相怜两乐事，独使我殷勤。”相传为王献之所作，桃叶是他的妾名。后人经常用桃叶、桃根指代意中人。结句的“这次第”虽只是一个“点”，分量却是相当沉重的。愁绪扰人，自然产生剪除的意愿，这也是人们的共同心理。然而这首词中，合理的意愿却是用否定方式、喟叹的口吻表达出来的，因为“算人间没个并刀，剪断心上愁痕”，遍寻人间也找不到能够剪断这种愁绪的剪刀。', poem_tags = '宋词三百首,宋词精选,婉约,伤春,恨别' WHERE poem_title = '湘春夜月·近清明' AND poem_author = '黄孝迈';
UPDATE edu_poem SET poem_translation = '湘君降落在北洲之上，极目远眺啊使我惆怅。\n树木轻摇啊秋风初凉，洞庭起波啊树叶落降。\n踩着白薠啊纵目四望，与佳人相约啊在今天晚上。\n鸟儿为什么聚集在水草之处？鱼网为什么挂结在树梢之上？\n沅水芷草绿啊澧水兰花香，思念湘夫人啊却不敢明讲。\n神思恍惚啊望着远方，只见江水啊缓缓流淌。\n麋鹿为什么在庭院里觅食？蛟龙为什么在水边游荡？\n清晨我打马在江畔奔驰，傍晚我渡到江水西旁。\n我听说湘夫人啊在召唤着我，我将驾车啊与她同往。\n我要把房屋啊建筑在水中央，还要把荷叶啊盖在屋顶上。\n荪草装点墙壁啊紫贝铺砌庭坛。四壁撒满香椒啊用来装饰厅堂。\n桂木作栋梁啊木兰为桁椽，辛夷装门楣啊白芷饰卧房。\n编织薜荔啊做成帷幕，析开蕙草做的幔帐也已支张。\n用白玉啊做成镇席，各处陈设石兰啊一片芳香。\n在荷屋上覆盖芷草，用杜衡缠绕四方。\n汇集各种花草啊布满庭院，建造芬芳馥郁的门廊。\n九嶷山的众神都来欢迎湘夫人，他们簇簇拥拥的像云一样。\n我把那衣袖抛到江中去，我把那单衣扔到澧水旁。\n我在小洲上啊采摘着杜若，将用来馈赠给远方的姑娘。\n美好的时光啊不可多得，我姑且悠闲自得地徘徊游逛。', poem_notes = '九歌：屈原十一篇作品的总称。“九”是泛指，非实数，《九歌》本是古乐章名。王逸《楚辞章句》认为：“昔楚国南郢之邑，沅湘之间，其俗信鬼而好祠。其祠必作歌乐鼓舞以乐诸神。屈原放逐，窜伏其域，杯忧苦毒，愁思沸郁，出见俗人祭祀之札，歌舞之乐，其辞鄙陋，因作《九歌》之曲，上陈事神之敬，下见已之冤结，托之以风谏。”也有人认为是屈原在民间祭歌的基础上加工而成。关于湘夫人和湘君为谁，多有争论。二人为湘水之神，则无疑。\n帝子：指湘夫人。舜妃为帝尧之女，故称帝子。\n眇眇（miǎo）：望而不见的徉子。愁予：使我忧愁。\n袅袅（niǎo）：绵长不绝的样子。\n波：生波。下：落。\n薠（fán）：一种近水生的秋草。骋望：纵目而望。\n佳：佳人，指湘夫人。期：期约。张：陈设。\n萃：集。鸟本当集在木上，反说在水草中。\n罾（zēng）：捕鱼的网。罾原当在水中，反说在木上，比喻所愿不得，失其应处之所。\n沅：即沅水，在今湖南省。澧（lǐ）：即澧水，在今湖南省，流入洞庭湖。芷（zhǐ）：即白芷，一种香草。\n公子：指湘夫人。古代贵族称公族，贵族子女不分性别，都可称“公子”。\n荒忽：不分明的样子。\n潺湲：水流的样子。\n麋：兽名，似鹿。\n水裔：水边。此名意谓蛟本当在深渊而在水边。比喻所处失常。\n皋：水边高地。\n澨（shì）：水边。\n腾驾：驾着马车奔腾飞驰。偕逝：同往。\n葺：编草盖房子。盖：指屋顶。\n荪壁：用荪草饰壁。荪（sūn）：一种香草。紫：紫贝。坛：中庭。\n椒：一种科香木。\n栋：屋栋，屋脊柱。橑（lǎo）：屋椽（chuán）。\n辛夷：木名，初春升花。楣：门上横梁。药：白芷。\n罔：通“网”，作结解。薜荔；一种香草，缘木而生。帷：帷帐。\n擗（pǐ）：掰开。蕙：一种香草。櫋（mián）：隔扇。\n镇：镇压坐席之物。\n疏：分疏，分陈。石兰：一种香草。\n缭：缠绕。杜衡：一种香草。\n合：合聚。百草：指众芳草。实：充实。\n馨：能够远闻的香。庑（wǔ）：走廊。\n九嶷（yí）：山名，传说中舜的葬地，在湘水南。这里指九嶷山神。缤：盛多的样子。\n灵：神。如云：形容众多。\n袂（mèi）：衣袖。\n褋（dié）：《方言》：禅衣，江淮南楚之间谓之“褋”。禅衣即女子内衣，是湘夫人送给湘君的信物。这时古时女子爱情生活的习惯。\n汀：水中或水边的平地。杜若：一种香草。\n远者：指湘夫人。\n骤得：数得，屡得。\n逍遥：游玩。容与：悠闲的样子。', poem_appreciation = '《九歌·湘夫人》是《楚辞·九歌》组诗十一首之一，是祭湘水女神的诗歌，和《九歌·湘君》是姊妹篇。\n\n　　诗题虽为《湘夫人》，但诗中的主人公却是湘君。这首诗的主题主要是描写相恋者生死契阔、会合无缘。作品始终以候人不来为线索，在怅惘中向对方表示深长的怨望，但彼此之间的爱情始终不渝则是一致的。全诗由男神的扮演者演唱，表达了赴约的湘君来到约会地北渚，却不见湘夫人的惆怅和迷惘。\n\n　　如果把这两首祭神曲联系起来看，那么这首《湘夫人》所写的情事，正发生在湘夫人久等湘君不至而北出湘浦、转道洞庭之时。因此当晚到的湘君抵达约会地北渚时，自然难以见到他的心上人了。作品即由此落笔，与《湘君》的情节紧密配合。\n\n　　首句“帝子降兮北渚”较为费解。“帝子”历来解作天帝之女，后又附会作尧之二女，但毫无疑问是指湘水女神。一般都把这句说成是帝子已降临北渚，即由《湘君》中的“夕弭节兮北渚”而来；但这样便与整篇所写湘君盼她前来而不见的内容扞格难合。于是有人把这句解释成湘君的邀请语（见詹安泰《屈原》），这样文意就比较顺畅了。\n\n　　歌辞的第一段写湘君带着虔诚的期盼，久久徘徊在洞庭湖的山岸，渴望湘夫人的到来。这是一个环境气氛都十分耐人寻味的画面：凉爽的秋风不断吹来，洞庭湖中水波泛起，岸上树叶飘落。望断秋水、不见伊人的湘君搔首蹰躇，一会儿登临送目，一会儿张罗陈设，可是事与愿违，直到黄昏时分仍不见湘夫人前来。这种情形经以“鸟何萃兮苹中，罾何为兮木上”的反常现象作比兴，就更突出了充溢于人物内心的失望和困惑，大有所求不得、徒劳无益的意味。而其中“嫋嫋兮秋风，洞庭波兮木叶下”更是写景的名句，对渲染气氛和心境都极有效果，因而深得后代诗人的赏识。\n\n　　第二段在此基础上，进一步深化湘君的渴望之情。以水边泽畔的香草兴起对伊人的默默思念，又以流水的缓缓而流暗示远望中时光的流逝，是先秦诗歌典型的艺术手法，其好处在于人物相感、情景合一，具有很强的感染力。以下麋食中庭和蛟滞水边又是两个反常现象，与前文对鸟和网的描写同样属于带有隐喻性的比兴，再次强调爱而不见的事愿相违。接着与湘夫人一样。他在久等不至的焦虑中，也从早到晚骑马去寻找，其结果则与湘夫人稍有不同：他在急切的求觅中，忽然产生了听到佳人召唤、并与她一起乘车而去的幻觉。于是作品有了以下最富想像力和浪漫色彩的一笔。\n\n　　第三段纯粹是湘君幻想中与湘夫人如愿相会的情景。这是一个令人目不暇接、眼花缭乱的神奇世界：建在水中央的庭堂都用奇花异草香木构筑修饰。其色彩之缤纷、香味之浓烈，堪称无与伦比。作品在这里一口气罗列了荷、荪、椒、桂、兰、辛夷、药、薜荔、蕙、石兰、芷、杜衡等十多种植物，来极力表现相会处的华美艳丽。其目的，则全在于以流光溢彩的外部环境来烘托和反映充溢于人物内心的欢乐和幸福。因此当九嶷山的众神来把湘君的恋人接走时，他才恍然大悟，从这如梦幻般的美境中惊醒，重新陷入相思的痛苦之中。\n\n　　最后一段与《湘君》结尾不仅句数相同，而且句式也完全一样。湘君在绝望之余，也像湘夫人那样情绪激动，向江中和岸边抛弃了对方的赠礼，但表面的决绝却无法抑制内心的相恋。他最终同样恢复了平静，打算在耐心的等待和期盼中，走完相恋相思这段好事多磨的心理历程。他在汀洲上采来芳香的杜若，准备把它赠送给远来的湘夫人。\n\n　　从情感的结构角度看，这首诗是以“召唤方式”呼应“期待视野”。《湘夫人》既然是迎神曲，必然是以召唤的方式祈求神灵降临。全诗以召唤湘夫人到来作为出发点，以期待的心理贯穿其中。诗的前半段主要写湘君思念湘夫人时那种望而不见、遇而无缘的期待心情。中间经历了忧伤、懊丧、追悔、恍惚等情感波动。这些都是因期待而落空所产生的情绪波动。诗的后半段是写湘君得知湘夫人应约即将到来的消息后，喜出望外，在有缘相见而又未相见的期待心情中忙碌着新婚前的准备事宜。诗的末尾，湘夫人才出现，召唤的目的达到，使前面一系列的期待性的描写与此呼应。实际上，后半段的描写不过是湘君的幻想境界。出现这种幻象境界，也是由于期待心切的缘故。整首诗对期待过程的描写，有开端，有矛盾，有发展，有高潮，有低潮，有平息。意识线路清晰可见。\n\n　　这首诗还有着明暗对应的双层结构方式。主人公情感的表现，有明有暗，明暗结合。抒情对象既可实指，又有象征性。在描写实境时，主人公的情感是表层性的，意旨明朗，指事明确，语言明快，情感色泽清晰，高低起伏，强弱大小，都呈透明状态。如诗的后半段写筑室建堂、美饰洞房、装饰门面、迎接宾客的场面，就属于表层性的，即明写。从“筑室兮水中”至“疏石兮为芳”，是从外到里、由大到小；从“芷葺兮荷屋”至“建芳馨兮庑门”，又由里到外。线路清楚，事实明白，情感的宣泄是外露的，是直露胸臆的方式，淋漓酣畅，无拘无束，少含蓄，情感的流动与外在形式同步。\n\n　　从深层结构看，这首诗又有着寓情于景的表情法。景物不是原来的样子，如“鸟何”、“罾何”、“麋何”、“蛟何”等句；或是带上感情色彩的景物，如秋风、秋水、秋叶的描写。情感的流动较蕴藉、含蓄、深沉，如海底暗流，不易发觉。因此需要通过表层意象加以领会。\n\n　　这种双层结构，明暗对应，相辅相成，构成一种情景交融的境界。这种结构的优点是：可以增大情感的容量，使情感的表现呈立体状。\n\n　　另外，全诗所描写的对象和运用的语言，都是楚化了的，具有鲜明的楚国地方特色。诸如沅水、湘水、澧水、洞庭湖、白芷、白薠、薜荔、杜蘅、辛夷、桂、蕙、荷、麋、鸟、白玉等自然界的山水、动物、植物和矿物，更有那楚地的民情风俗、神话传说、特有的浪漫色彩、宗教气氛等，无不具有楚地的鲜明特色。诗中所构想的房屋建筑、陈设布置，极富特色，都是立足于楚地的天然环境、社会风尚和文化心理结构这个土壤上的，否则是不可能作此构想的。语言上也有楚化的特点。楚辞中使用了大量的方言俗语，《湘夫人》也不例外，如“搴”（动词）、“袂”、“褋”（名词）等。最突出的是“兮”字的大量运用——全诗每句都有一个“兮”字。这个语气词相当于今天所说的“啊”字。它的作用就在于调整音节，加大语意、语气的转折、跳跃，增强语言的表现力。《湘夫人》以方言为主，兼有五七言。句式变化灵活。这种“骚体”诗，是继《诗经》后新出现的自由诗，在我国古代诗歌发展史上是一次了不起的创新。\n\n　　综上所述，《湘君》和《湘夫人》是由一次约会在时间上的误差而引出的两个悲剧，但合起来又是一幕两情相悦、忠贞不渝的喜剧。说它们是悲剧，是因为赴约的双方都错过了相会的时间，彼此都因相思不见而难以自拔，心灵和感情遭受了长时间痛苦的煎熬；说它们是喜剧，是由于男女双方的相恋真诚深挚，尽管稍有挫折，但都没有放弃追求和期盼，所以圆满结局的出现只是时间问题。当他们在耐心平静的相互等待之后终于相见时，这场因先来后到而产生的误会和烦恼必然会在顷刻间烟消云散，迎接他们的将是湘君在幻觉中所感受的那种欢乐和幸福。\n\n　　这两篇作品一写女子的爱慕，一写男子的相思，所取角度不同，所抒情意却同样缠绵悱恻；加之作品对民间情歌直白的抒情方式的吸取和对传统比兴手法的运用，更加强了它们的艺术感染力。因此尽管这种热烈大胆、真诚执着的爱情被包裹在宗教仪式的外壳中，但它本身所具有强大的生命内核，却经久不息地释放出无限的能量，让历代的读者和作者都能从中不断获取不畏艰难、不息地追求理想和爱情的巨大动力。这可以从无数篇后代作品都深受其影响的历史中，得到最好的印证。', poem_tags = '思念,爱情,写人' WHERE poem_title = '九歌·湘夫人' AND poem_author = '屈原';
UPDATE edu_poem SET poem_translation = '这两句诗我琢磨三年才写出，一读起来禁不住两行热泪流出来。\n了解我思想情感的好朋友如果不欣赏这两句诗，我只好回到以前住过的故乡（山中），在瑟瑟秋风中安稳地睡了。', poem_notes = '吟：读，诵。\n知音：指了解自己思想情感的好朋友。\n赏：欣赏。\n得：此处指想出来。', poem_tags = '题诗,早教古诗100首' WHERE poem_title = '题诗后' AND poem_author = '贾岛';
UPDATE edu_poem SET poem_translation = '范增因为项羽不杀刘邦怒而撞碎玉斗，范蠡助越灭吴之后带着西施泛舟五湖。谓英雄之所以能够美名流传，就在于立功万里，为国家和君王效命。\n\n燕雀怎么能知道鸿鹄的志向？公侯将相原本出身于普通士卒。可笑泸溪地小如斗，不知道您肯不肯在那里小试牛刀？赠送给您两只玉瓯作为寿礼。', poem_notes = '范南伯：范如山，字南伯，是辛弃疾的内兄。张南轩：张 ，安敬夫，自号南轩，张浚之子，时任荆湖北路转运副使。辟：征召。　宰：县令。\n\n掷地刘郎玉斗：《史记·项羽本纪》载，鸿门宴上，项羽不听范增劝告，放走刘邦。范增十分气愤，将刘邦送给自己的一双玉斗掷于地，用剑击碎而去。\n\n挂帆西子扁舟：用吴越时期越国大臣范蠡在破吴后与西施泛舟五湖的典故。\n\n兜鍪：战盔，貂蝉为侍从贵臣所着冠上的饰物。\n\n牛刀：这里牛刀是大材，孔子曾以“割鸡焉用牛刀”比喻大材小用。玉瓯：玉制酒杯。', poem_appreciation = '范南伯，名如山，是辛弃疾的内兄。让他担任泸溪县令（即所谓“辟宰泸溪”）,范如山并不相信朝廷真能有所作为，故“迟迟未行”。辛弃疾便写《破阵子》既为祝寿又为规劝，营意用典之妙，用梁启超的话说是“可为三叹！” 全词62字，用了范增、范蠡、陈涉、周盘龙、宗悫、子游六典，除周盘龙一典稍为冷僻外，均为熟典，为全词的生动内容的一部分，非耀学无生硬，得蕴藉隽永之妙，远胜于直接议论。 第一句典出刘邦送玉斗给项羽谋士范增，范掷玉斗于地，拔剑碎之，可谓以碎玉开始；而结句是辛弃疾献玉碗以祝寿，则为完玉终，其间，捕捉心态，造语灵动，以万里功名上对千古风流，下启君王三百州，而大宋三百州此时已剩下不及一半了，完玉之业吾辈岂能以一己之得失而置之度外乎？\n\n　　这首词作于宋淳熙五年（1178）。词中作者借为范如山祝寿的机会，劝说他不要仿效范增和范蠡，鼓励他应该去泸溪，施展自己的才干，锻练自己的能力，准备为收复祖国失地建功立业。范南伯，名如山，是辛弃疾的内兄。范氏一家都是很有民族气节的人，他父亲范邦彦曾仕金为蔡州新息县令，后率豪杰开城迎宋军，举家归宋。他很钦佩辛弃疾的忠心赤胆而把女儿嫁给了辛。辛跟范如山“皆中州之豪，相得甚”。范如山是个有才干的政治家，刘宰《故公安范大夫行述》说他“治官如家，抚民若子”，极受百姓拥护。他颇有忧世之心，常思恢复北土，但感于政治腐败，当道非人，又很想学陶渊明“躬耕南亩”，隐居不仕。淳熙五年（1178年）六月，南宋主战派名相张浚的儿子张拭（自号南轩），任荆湖北路安抚使，颇想干一番事业，因范如山从金人占领区来，“知其豪杰，熟其形势”，便请他担任泸溪县令（即所谓“辟宰泸溪”）。范如山并不相信朝廷真能有所作为，故“迟迟未行”。辛弃疾当时正任湖北漕运副使，很希望范能出仕荆湖，“因作此词勉之”。词的主题就是劝他以国事为重，“万里功名莫放休”，时时挂念“君王三百州”，努力做出力所能及的贡献。\n\n　　一开篇作者用了两个典故。一个是，“掷地刘郎玉斗”。鸿门宴上刘邦令张良献玉斗给亚父范增，范增痛感项羽不听劝告放走刘邦，贻下后患，而将玉斗置于地，拔剑撞而破之。另一个是，“挂帆西子扁舟。”春秋吴越之争时，范蠡献西施于吴王，以瓦解吴王斗志；灭吴后，不受越封，复取西施乘舟游五湖而不返。写法都是似明而暗，一看便知是用典，但真正的用意却没有直接说出来，甚至连范增、范蠡的名字都没有出现。作者用这两个典的意思，主要因范增、范蠡都与范如山同姓，又都是才智出众，有胆有识的谋士，因而即以二范比如山，希望他成为二范那样的人物，能竭诚尽智为自己的君国作出应有的贡献。这个看来隐晦的开端，不但艺术上很有特色（隐含范如山姓氏，却不出一范字），从词的主旨说也是很好的开端，有了这个开端垫底，下面几句正面劝勉的话就显得很有力量，很动感情了。“千古风流”应在我辈身上，不要轻抛建功立业（“万里功名”）的时机，要时时想到大宋的万里江山（“三百州”）呵！\n\n　　下片，针对范如山“迟迟未行”的思想活动，进行劝勉。一方面称赞了范的大才宏志，预言他定能有所成就，一方面劝告他不要嫌泸溪令职位低小难以发挥作用。而应当以之作为搞大事业的起点。为了同时表达这两方面的意思，作者选用了四个典故。一是：“燕雀岂知鸿鹄”。陈涉辍耕垄上，慨叹“燕雀安知鸿鹄之志哉”的故事，借此表明自己理解范的志向，他的不愿就任是想有更大的作为。二是：“貂蝉元出兜鍪”。用的南齐将军周盘龙的故事。周年老不能守边，还朝为散骑常侍（皇帝侍从，能预闻要政），世祖戏问他：“你戴貂蝉（近侍贵臣冠饰）冠比起戴兜鍪（战盔）来如何？”周答：“此貂蝉从兜鍪中出耳。”意思是说我成为近臣是在战场上拚杀得来的，不是靠了恩宠。这里表示自己理解范有更大的才能，想得到更能发挥作用的位置，但是想得到更大的尊荣，要想得到参预朝政的要位，必须在实际工作中多作表现，积累“战功”。三是：南朝宋大将军宗悫的故事。宗晚年为豫州刺史，典签多所违执，宗怒叹“得一州如斗大，竟遭到典签的慢待！”辛借此表示自己体会到范的心情──以大才而屈居小小泸溪，且行动不能自主，难有作为。但也是劝他：宗悫都难免屈居下位，受小人之气，何况你我。典签，本为地方文书小吏，但南朝时，多由帝王亲信担任，以监视地方大员，号为“签师”，颇有实权。四是《论语·阳货篇》：孔子至武城，闻弦歌之声，认为割鸡无需用牛刀的故事。作者反其意而用之，鼓励范南伯不妨以牛刀杀鸡，一试身手，把泸溪治理好，以显示自己的才能。', poem_tags = '祝寿,典故,劝勉' WHERE poem_title = '破阵子·掷地刘郎玉斗' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '头上的红色冠子不用特别剪裁，雄鸡身披雪白的羽毛雄纠纠地走来。\n它平生不敢轻易鸣叫，它叫的时候，千家万户的门都打开。', poem_notes = '裁：裁剪，这里是制作的意思。\n将：助词，用在动词和来、去等表示趋向的补语之间。\n平生：平素，平常。\n轻：随便，轻易。\n言语：这里指啼鸣，喻指说话，发表意见。\n一：一旦。\n千门万户：指众多的人家。', poem_appreciation = '《画鸡》是一首题画诗，描绘了雄鸡的优美高洁的形象，赞颂了轻易不鸣，鸣则动人的品格，也表现了诗人的精神面貌和思想情怀。\n\n　　“头上红冠不用裁，满身雪白走将来”，这是写公鸡的动作、神态。头戴无须剪裁的天然红冠，一身雪白，兴致冲冲地迎面走来。诗人运用了描写和色彩的对比，勾画了一只冠红羽白、威风凛凛，相貌堂堂的大公鸡。起句的“头上红冠”，从局部描写公鸡头上的大红冠，在这第一句里，诗人更着重的是雄鸡那不用装饰而自然形成的自然美本身，所以诗人称颂这种美为“不用裁”。承句“满身雪白”又从全身描写公鸡浑身的雪白羽毛。状物明确，从局部到全面；用大面积的白色（公鸡）与公鸡头上的大红冠相比，色彩对比强烈，描绘了雄鸡优美高洁的形象。\n\n　　“平生不敢轻言语，一叫千门万户开”。这是写公鸡的心理和声音。诗人拟鸡为人揭开了它一生中不敢轻易说话的心理状态，它一声呜叫，便意味着黎明的到来。它一声呜叫，千家万户都要打开门，迎接新的一天的到来。“平身不敢轻言语”，诗人的诗路急转，说公鸡一生不敢随便啼叫，此句的气色收敛，还很低调，尤其“不敢”一词，用的很贴切，为第四句的结句做了铺垫，并对下句有反衬效果。后两句用拟人法写出了雄鸡在清晨报晓的情景，动静结合，运用了诗歌的艺术手法，使两句产生了强烈的对比树立了雄鸡高伟的形象，表现了公鸡具备的美德和权威。\n\n　　这首诗，诗人表达含蓄又不失些许豪放之情，借助诗中的雪白大公鸡表达了自己渴望成为时代先驱者的远大志向。', poem_tags = '豪放,哲理' WHERE poem_title = '画鸡' AND poem_author = '唐寅';
UPDATE edu_poem SET poem_translation = '我已经很衰老了。平生曾经一同出游的朋友零落四方，如今还剩下多少？真令人惆怅。这么多年只是白白老去而已，功名未竟，对世间万事也慢慢淡泊了。还有什么能真正让我感到快乐？我看那青山潇洒多姿，想必青山看我也是一样。不论情怀还是外貌，都非常相似。\n把酒一尊，在窗前吟诗，怡然自得。想来当年陶渊明写成《停云》之时也是这样的感觉吧。江南那些醉中都渴求功名的人，又怎能体会到饮酒的真谛？在酒酣之际，回头朗吟长啸，云气会翻飞，狂风会骤起。不恨我不能见到疏狂的前人，只恨前人不能见到我的疏狂而已。了解我的，还是那几个朋友。', poem_notes = '贺新郎：后人创调，又名《金缕曲》、《乳燕飞》、《貂裘换酒》。传作以《东坡乐府》所收为最早，惟句豆平仄，与诸家颇多不合。因以《稼轩长短句》为准。一百十六字，前后片各六仄韵。大抵用入声部韵者较激壮，用上、去声部韵者较凄郁，贵能各适物宜耳。\n邑：指铅山县。辛弃疾在江西铅山期思渡建有别墅，带湖居所失火后举家迁之。\n仆：自称。\n停云：停云堂，在瓢泉别墅。\n甚矣吾衰矣：这是孔丘慨叹自己“道不行”的话（梦见周公，欲行其道）。作者借此感叹自己的壮志难酬。\n问何物、能令公喜：还有什么东西能让我感到快乐。\n妩媚：潇洒多姿。\n搔首东窗：借指陶潜《停云》诗就，自得之意。\n江左：原指江苏南部一带，此指南朝之东晋。\n浊醪（láo）：浊酒。\n知我者，二三子：引《论语》的典故：“二三子以我为隐乎”。', poem_appreciation = '正如此词自注所述，辛弃疾的这首《贺新郎》词，乃是仿陶渊明《停云》“思亲友”之意而作，抒写了作者罢职闲居时的寂寞与苦闷的心情。据邓广铭《稼轩词编年笺注》考证，此词约作于宋宁宗庆元四年（1198）左右。此时辛弃疾被投闲置散又已四年。他在信州铅山（今属江西）东期思渡瓢泉旁筑了新居，其中有“停云堂”，即取陶渊明《停云》诗意。\n\n　　辛弃疾的词，爱用典故，在宋词中别具一格。这首词的上片一开头“甚矣吾衰矣。怅平生交游零落，只今馀几！”即引用了《论语》中的典故。《论语·述而篇》记孔子说：“甚矣吾衰也，久矣吾不复梦见周公。”如果说，孔子慨叹的是其道不行；那么辛弃疾引用它，就有慨叹政治理想无法实现之意。辛弃疾写此词时已五十九岁，又谪居多年，故交零落，因此发出这样的慨叹也是很自然的。这里“只今馀几”与结句“知我者，二三子”首尾衔接，用以强调“零落”二字。接着“白发空垂三千丈，一笑人间万事。问何物能令公喜？”数语，又连用李白《秋浦歌》“白发三千丈”和《世说新语·宠礼篇》记郗超、王恂“能令公（指晋大司马桓温）喜”等典故，叙自己徒伤老大而一事无成，又找不到称心朋友，写出了世态关系与自己此时的落寞。“我见青山多妩媚，料青山见我应如是”两句，是全篇警策。词人因无物（实指无人）可喜，只好将深情倾注于自然，不仅觉得青山“妩媚”，而且觉得似乎青山也以词人为“妩媚”了。这与李白《敬亭独坐》“相看两不厌”是同一艺术手法。这种手法，先把审美主体的感情楔入客体，然后借染有主体感情色彩的客体形象来揭示审美主体的内在感情。这样，便大大加强了作品里的主体意识，易于感染读者。以下“情与貌，略相似。”两句，情，指词人之情；貌，指青山之貌。二者有许多相似之处，如崇高、安宁和富有青春活力等。作者在这里将自己的情与青山相比，委婉地表达了自己宁愿落寞，决不与奸人同流合污的高洁之志。\n\n　　词的下片作者又连用典故。“一尊搔首东窗里，想渊明《停云》诗就，此时风味。”陶渊明《停云》中有“良朋悠邈，搔首延伫”和“有酒有酒，闲饮东窗”等诗句，辛弃疾把它浓缩在一个句子里，用以想像陶渊明当年诗成时的风味。这里作者又提陶渊明，意在以陶自况。“江左沉酣求名者，岂识浊醪妙理？”两句，表面似申斥南朝那些“醉中亦求名”（苏轼《和陶饮酒二十首》之三）的名士派人物；实际是讽刺南宋已无陶渊明式的饮酒高士，而只有一些醉生梦死的统治者。以下“不恨古人吾不见，恨古人不见吾狂耳”两句，句法与上片“我见青山”一联相似，表现出了作者傲视古今的英雄气概。这里所说的“古人”，不是一般的古人，而是指像陶渊明一类的人。据岳珂《桯史·卷三》记：“辛弃疾每逢宴客，必命侍姬歌其所作。特好歌《贺新郎》一词，自诵其警句曰：‘我见青山多妩媚，料青山见我应如是。’又曰：‘不恨古人吾不见，恨古人不见吾狂耳。’每至此，辄拊髀自笑，顾问坐客何如。”足见辛弃疾对自己这二联是很自负的。\n\n　　结句“知我者，二三子。”这“二三子”为谁没有人进行专门的考证，有人认为是当时人陈亮。但读者不妨视野扩大些，将古人陶渊明、屈原乃至于孔子等，都算在内。辛弃疾慨叹当时志同道合的朋友不多，实与屈原慨叹“众人皆醉我独醒”的心情类似，同出于为国家和民族的危亡忧虑。而他的闲居铅山，与陶渊明居“南山”之情境也多少有点类似。', poem_tags = '宋词三百首,典故,言志,猖狂' WHERE poem_title = '贺新郎·甚矣吾衰矣' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '精卫含着微小的木块，要用它填平沧海。刑天挥舞着盾斧，刚毅的斗志始终存在。同样是生灵不存余哀，化成了异物并无悔改。如果没有这样的意志品格，美好的时光又怎么会到来呢？', poem_notes = '精卫：古代神话中鸟名。据《山海经·北山经》及《述异记》卷上记载，古代炎帝之女精卫，因游东海淹死，灵魂化为鸟，经常衔木石去填东海。衔：用嘴含。微木：细木。 \n刑天：神话人物，因和天帝争权，失败后被砍去了头，埋在常羊山，但他不甘屈服，以两乳为目，以肚脐当嘴，仍然挥舞着盾牌和板斧。（《山海经·海外西经》） \n同物：精卫既然淹死而化为鸟，就和其它的的相同，即使再死也不过从鸟化为另一种物，所以没有什么忧虑。 \n化去：刑天已被杀死，化为异物，但他对以往和天帝争神之事并不悔恨。 \n徒：徒然、白白地。在昔心：过去的壮志雄心。 \n良辰：实现壮志的好日子。讵：岂。这两句是说精卫和刑天徒然存在昔日的猛志，但实现他们理想的好日子岂是能等待得到！ \n猛志：勇猛的斗志。 \n在昔心：过去的壮志雄心。 \n讵：表示反问，岂。', poem_appreciation = '关于“同物”的理解 　　关于“同物既无虑，化去不复悔”一句，有的认为，上句言生时，下句言死后，“同物”言同为有生命之物，指精卫、刑天之原形，“化去”言物化，指精卫、刑天死而化为异物。然而这样理解，未必符合作者的原意。《说文解字》云：“物，万物也。牛为大物，天地之数起于牵牛，故从牛。”可见物为天地万物之意，而精卫化去为鸟，刑天化去为“以乳为目，以脐为口，操干戚以舞”，二者虽则化为了异物，但实际上与生前并没有区别，都有着自己的意志，都是天地所生的有灵之物，都同归于自然大道。所谓的生死、化与不化，都不能改变“同物”的本质。因而，既然同样是“物”，只不过形态有所不同，那么便没有什么可以忧虑的，那么化去也就没有任何的悔恨了。“物”不仅仅是指精卫与刑天本来的形态而言的，“同物既无虑”与“化去不复悔”两句是因果的关系。作这样的理解，诗文更能表达出一种道生万物而万物一同的意义，更能理解“化去不复悔”的原因，可能更符合作者的原意。▲', poem_tags = '古诗三百首,赞美,写人,神话' WHERE poem_title = '读山海经·其十' AND poem_author = '陶渊明';
UPDATE edu_poem SET poem_translation = '战场上哭泣的大多是新死去兵士的鬼魂，只有老人一个人忧愁地吟诗。\n乱云低低的在黄昏的地方，急下的雪花在风中飘舞回旋。\n葫芦丢弃了，酒器中没有酒，火炉中的余火，好似照得眼前一片通红。\n前线战况和妻子弟妹的消息都无从获悉，忧愁坐着用手在空中划着字。', poem_notes = '战哭：指在战场上哭泣的士兵。新鬼：新死去士兵的鬼魂。《左传·文公二年》：“吾见新鬼大故鬼小。”\n愁吟：哀吟。唐薛能《西县作》诗：“从此渐知光景异，锦都回首尽愁吟。”\n旋风。《楚辞·九章·悲回风》：“悲回风之摇蕙兮，心冤结而内伤。”\n瓢：葫芦，古人诗文中习称为瓢，通常拿来盛茶酒的。弃：一作“弄”。樽：又作“尊”，似壶而口大，盛酒器。句中以酒的绿色代替酒字。\n愁坐：含忧默坐。唐李白《酬崔五郎中》诗：“奈何怀良图，郁悒独愁坐。”书空：是晋人殷浩的典故，意思是忧愁无聊，用手在空中划着字。唐李公佐《谢小娥传》：“余遂请齐公书于纸。乃凭槛书空，凝思默虑。”', poem_appreciation = '此诗一二句中“战哭多新鬼”，正暗点了这个使人伤痛的事实。房琯既败，收复长安暂时没有希望，不能不给诗人平添一层愁苦，又不能随便向人倾诉。所以上句用一“多”字，以见心情的沉重；下句“愁吟独老翁”，就用一“独”字，以见环境的险恶。\n\n　　三、四句中“乱云低薄暮，急雪舞回风”，正面写出题目。先写黄昏时的乱云，次写旋风中乱转的急雪。这样就分出层次，显出题中那个“对”字，暗示诗人独坐斗室，反复愁吟，从乱云欲雪一直呆到急雪回风，满怀愁绪，仿佛和严寒的天气交织融化在一起了。\n\n　　五、六句中接着写诗人贫寒交困的景况。“瓢弃樽无绿”，写出了诗人困居长安，生活非常艰苦。在苦寒中找不到一滴酒。葫芦早就扔掉，樽里空空如也。“炉存火似红”，也没有多少柴火，剩下来的是勉强照红的余火。这里，诗人不说炉中火已然燃尽，而偏偏要说有“火”，而且还下一“红”字，写得好象炉火熊熊，满室生辉，然后用一“似”字点出幻境。明明是冷不可耐，明明只剩下的是炉中只存余热的灰烬，由于对温暖的渴求，诗人眼前却出现了幻象：炉中燃起了熊熊的火，照得眼前一片通红。这样的以幻作真的描写，非常深刻地挖出了诗人此时内心世界的隐秘。这是在一种渴求满足的心理驱使下出现的幻象。这样来刻画严寒难忍，比之“炉冷如冰”之类，有着不可以拟的深度。因为它不仅没有局限于对客观事物的如实描写，而且融进了诗人本身的主观情感，恰当地把诗人所要表现的思想感情表现出来，做到了既有现实感，又有浪漫感。\n\n　　七、八句中，诗人再归结到对于时局的忧念。至德元载（756年）至二载（757年），唐王朝和安禄山、史思明等的战争，在黄河中游一带地区进行，整个形势对唐军仍然不利。诗人陷身长安，前线战况和妻子弟妹的消息都无从获悉，所以说“数州消息断”，而以“愁坐正书空”结束全诗。这首诗表现了杜甫对国家和亲人的命运深切关怀而又无从着力的苦恼心情。', poem_tags = '冬天,写雪' WHERE poem_title = '对雪' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '在长安回头远望骊山宛如一堆堆锦绣，山顶上华清宫千重门依次打开。\n一骑驰来烟尘滚滚妃子欢心一笑，无人知道是南方送了荔枝鲜果来。\n\n绿树环绕的新丰一带不时可见黄尘四起，那是前往渔阳的探使返回。\n他们谎报军情，唐玄宗和杨贵妃仍旧沉溺于歌舞，直至安禄山起兵，中原残破。\n\n全国上下沉浸在一片歌舞升平之中，骊山上宫殿楼阁在月光下显得格外分明。\n安禄山拖着肥胖的身体翩翩作胡旋舞，引发了杨贵妃的笑声随风飘扬越过层层山峰。', poem_notes = '华清宫：《元和郡县志》：“华清宫在骊山上，开元十一年初置温泉宫。天宝六年改为华清宫。又造长生殿，名为集灵台，以祀神也。”\n绣成堆：骊山右侧有东绣岭，左侧有西绣岭。唐玄宗在岭上广种林木花卉，郁郁葱葱。\n千门：形容山顶宫殿壮丽，门户众多。次第：依次。\n红尘：这里指飞扬的尘土。妃子：指杨贵妃。乐史《杨太真外传》：上曰：“赏名花，对妃子，焉用旧乐词！”《新唐书·李贵妃传》：“妃嗜荔枝，必欲生致之，乃置骑传送，走数千里，味未变已至京师。”《唐国史补》：“杨贵妃生于蜀，好食荔枝，南海所生，尤胜蜀者，故每岁飞驰以进。然方暑而熟，经宿则败，后人皆不知之。”按：此诗或为写意之作，意在讽刺玄宗宠妃之事，不可一一求诸史实。在唐代，岭南荔枝无法运到长安一带，故自苏轼即言“此时荔枝自涪州致之，非岭南也”（《通鉴唐纪》注）。而荔枝成熟的季节，玄宗和贵妃必不在骊山。玄宗每年冬十月进驻华清宫，次年春即回长安。《程氏考古编》亦辨其谬，近人陈寅恪亦复考证之。\n知是：一作“知道”。\n新丰：唐设新丰县，在陕西临潼县东北，离华清宫不远。黄埃：马队奔驰踏起的尘土。\n渔阳探使：《全唐诗》此句下注：“帝使中使辅璆琳探禄山反否，璆琳受禄山金，言禄山不反。”\n霓裳（nícháng）：《霓裳羽衣曲》，当时的宫廷舞曲，是唐玄宗根据西凉节度使杨敬述进献的印度《婆罗门》舞曲十二遍亲自改编而成的。千峰：指骊山的众多山峰。\n舞破中原：指唐玄宗耽于享乐而误国，导致安史之乱。\n万国：指全国。\n倚天：形容骊山宫殿的雄伟壮观。\n云中两句：《旧唐书·安禄山传》载：禄山体肥，重三百三十斤，但却能在唐玄宗面前表演胡旋舞，其疾如风。旁边的宫人拍掌击节，因为舞得太快，节拍都乱了。', poem_appreciation = '其一\n\n　　此诗通过送荔枝这一典型事件，鞭挞了玄宗与杨贵妃骄奢淫逸的生活，有着以微见著的艺术效果，精妙绝伦，脍炙人口。\n\n　　起句描写华清宫所在地骊山的景色。诗人从长安“回望”的角度来写，犹如电影摄影师，在观众面前先展现一个广阔深远的骊山全景：林木葱茏，花草繁茂，宫殿楼阁耸立其间，宛如团团锦绣。“绣成堆”，既指骊山两旁的东绣岭、西绣岭，又是形容骊山的美不胜收，语意双关。\n\n　　接着，场景向前推进，展现出山顶上那座雄伟壮观的行宫。平日紧闭的宫门忽然一道接着一道缓缓地打开了。接下来，又是两个特写镜头：宫外，一名专使骑着驿马风驰电掣般疾奔而来，身后扬起一团团红尘；宫内，妃子嫣然而笑了。几个镜头貌似互不相关，却都包蕴着诗人精心安排的悬念：“千门”因何而开？“一骑”为何而来？“妃子”又因何而笑？诗人故意不忙说出，直至紧张而神秘的气氛憋得读者非想知道不可时，才含蓄委婉地揭示谜底：“无人知是荔枝来。”“荔枝”两字，透出事情的原委。《新唐书·杨贵妃传》：“妃嗜荔枝，必欲生致之，乃置骑传送，走数千里，味未变，已至京师。”明于此，那么前面的悬念顿然而释，那几个镜头便自然而然地联成一体了。\n\n　　吴乔《围炉诗话》说：“诗贵有含蓄不尽之意，尤以不著意见声色故事议论者为最上。”杜牧这首诗的艺术魅力就在于含蓄、精深，诗不明白说出玄宗的荒淫好色，贵妃的恃宠而骄，而形象地用“一骑红尘”与“妃子笑”构成鲜明的对比，就收到了比直抒己见强烈得多的艺术效果。“妃子笑”三字颇有深意。春秋时周幽王为博妃子一笑，点燃烽火，导致国破身亡。读到这里时，读者是很容易联想到这个尽人皆知的故事。“无人知”三字也发人深思。其实“荔枝来”并非绝无人知，至少“妃子”知，“一骑”知，还有一个诗中没有点出的皇帝更是知道的。这样写，意在说明此事重大紧急，外人无由得知，这就不仅揭露了皇帝为讨宠妃欢心无所不为的荒唐，也与前面渲染的不寻常的气氛相呼应。全诗不用难字，不使典故，不事雕琢，朴素自然，寓意精深，含蓄有力，是唐人咏史绝句中的佳作。\n\n其二\n\n　　唐玄宗时，安禄山兼任平卢、范阳、河东三镇节度使后伺机谋反，玄宗却对他十分宠信。皇太子和宰相杨国忠屡屡启奏，方派中使辅璆琳以赐柑为名去探听虚实。璆琳受安禄山厚赂，回来后盛赞他的忠心。玄宗轻信谎言，自此更加高枕无忧，恣情享乐了。“新丰绿树起黄埃，数骑渔阳探使回”，正是描写探使从渔阳经由新丰飞马转回长安的情景。这探使身后扬起的滚滚黄尘，是迷人眼目的的烟幕，又象征着叛乱即将爆发的战争风云。\n\n　　诗人从“安史之乱”的纷繁复杂的史事中，只摄取了“渔阳探使回”的一个场景，是颇具匠心的。它既揭露了安禄山的狡黠，又暴露了玄宗的糊涂，有“一石二鸟”的妙用。\n\n　　如果说诗的前两句是表现了空间的转换，那么后两句“霓裳一曲千峰上，舞破中原始下来”，则表现了时间的变化。前后四句所表现的内容本来是互相独立的，但经过诗人巧妙的剪接便使之具有互为因果的关系，暗示了两件事之间的内在联系。而从全篇来看，从“渔阳探使回”到“霓裳千峰上”，是以华清宫来联结，衔接得很自然。这样写，不仅以极俭省的笔墨概括了一场重大的历史事变，更重要的是揭示出事变发生的原因，诗人的构思是很精巧的。\n\n　　将强烈的讽刺意义以含蓄出之，尤其是“霓裳一曲千峰上，舞破中原始下来”两句，不着一字议论，便将玄宗的耽于享乐、执迷不悟刻画得淋漓尽致。说一曲霓裳可达“千峰”之上，而且竟能“舞破中原”，显然这是极度的夸张，是不可能的事，但这样写却并非不合情理。因为轻歌曼舞纵不能直接“破中原”，中原之破却实实在在是由统治者无尽无休的沉醉于歌舞造成。而且，非这样写不足以形容歌舞之盛，非如此夸张不能表现统治者醉生梦死的程度以及由此产生的国破家亡的严重后果。此外，这两句诗中“千峰上”同“下来”所构成的鲜明对照，力重千钧的“始”字的运用，都无不显示出诗人在遣词造句方面的深厚功力，有力地烘托了主题。正是深刻的思想内容与完美的表现手法，使之成为脍炙人口的名句。全诗到此戛然而止，更显得余味无穷。\n\n其三\n\n　　这是三绝句中的最后一首，也是一首讽喻诗。\n\n　　“万国笙歌醉太平”，此言唐玄宗整日与杨贵妃在骊山游乐，不理朝政，举国上下也沉浸在一片歌舞升平之中。“倚天楼殿月分明”，此言骊山上宫殿楼阁高耸挺拔，在月光下显得格外分明。“云中乱拍禄山舞”，此句语带讥刺地说：想当年安禄山在骊山上觐见唐玄宗和杨贵妃时，在大殿中拖着肥胖的身体翩翩作胡旋舞，竟引发了杨贵妃爽朗的笑声。“风过重峦下笑声”，此言那笑声随风飘扬越过层层峰峦，在山间久久回荡。\n\n　　据载：杨贵妃见安禄山作胡旋舞，心花怒放，竟收安禄山做自己的干儿子，唐玄宗也非常高兴，对安禄山分外器重，委任他为三镇节度使。但恰恰是他们的这位干儿子对他们举起了反叛的大旗。大唐帝国也从此滑向衰亡的深渊。\n\n　　此诗含蓄委婉，笔调看似轻快，实则对亡国之君的荒淫误国给予了辛辣无情的嘲讽。', poem_tags = '咏史怀古,讽刺,组诗,早教古诗100首' WHERE poem_title = '过华清宫绝句三首' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '夜里做梦与你携手共同游玩，早晨醒来泪水流满巾也不擦拭。\n在漳浦我三次生病，长安城草生草长已经八个年头。\n想你逝去九泉尸骨已经化成泥沙，我还暂时寄住人间白发满头。\n阿卫韩郎已经先后去世，黄泉渺茫昏暗能够知晓吗？', poem_notes = '微之：唐朝诗人元稹（779－831），字微之，与白居易同科及第，并结为终生诗友。\n漳浦：地名，在今福建漳州南部。\n宿草：指墓地上隔年的草，用为悼念亡友之辞朋友之墓，有宿草而不哭焉。\n君埋泉下：指微之去世。\n阿卫：微之的小儿子。\n韩郎：微之的爱婿。\n夜台：指坟墓，因为闭于坟墓，不见光明，所以称为夜台，后来也用来指代阴间。\n茫昧：模糊不清。', poem_appreciation = '这首《梦微之》是白居易在元稹离世九年后所做的一首七言律诗。其中颈联“君埋泉下泥销骨，我寄人间雪满头”，古往今来更不知有多少人为它而伤怀！\n\n　　公元 801年，30岁的白居易在长安结识了 23岁的元稹，他们为对方的文采精华而深深折服，政治上又都反对宦官专权、提倡轻徭薄赋。真是相见恨晚！为了实现古代仕人怀有的那份安邦定国的宏伟抱负，二人同时参加了吏部的制科考试，并且同时当上校书郎。虽是个闲官，倒也可自得其乐。饮酒赋诗赏花听书，好个诗酒风流！直到元稹因敷水驿事件得罪宦官、被贬下放，白居易以死上书无效。公元815年，元稹被贬为通州司马，同年白居易被贬为江州司马，同是天涯沦落人！此后，二人只能互通书信、倾诉衷肠！公元831年，60岁的白居易正赋闲于东都洛阳，惊闻元稹病逝于武昌，悲痛不已！当元稹的灵柩运回老家陕西咸阳时，途径洛阳，白挥泪写下祭文。\n\n　　“夜来携手梦同游，晨起盈巾泪莫收”。梦中乐天与微之重逢，二人携手同游，他们可能意气风发地畅谈天下大事、黎明苍生；可能痛斥那宦海风波、官场污浊；可能耻笑那魑魅小人、假义君子……可是梦总有醒来的时候！泪水打湿了乐天的绢帕，老泪纵横也无心擦拭了。时年，乐天已经是一位风烛残年的老人。他想起了元稹当年还和过他的一首诗，诗中有这么两句：“我今因病魂颠倒，惟梦闲人不梦君”。确实，生时不能相见，梦见还可以慰藉相思，梦不见是悲痛的！可是，死后故人梦更是痛彻心扉！明知此生不能再见，却又一遍遍回忆着逝去的时光，每每回忆一次，都是一遍强于一遍的无奈忧伤！死亡，切断了所有一切可能的念想！\n\n　　“漳浦老身三度病，咸阳草树八回秋”。乐天说他自己在漳浦这个地方已经生了几次病了，长安城草生草长不知不觉已有八个年头。时间蹉跎了芳华，元稹死后，乐天的一把老骨头也不得安生，只是淡漠地看着长安城的草生草长。如果人的生命也能够像草生草长一样该多好，就像乐天 17岁时写下的《赋得古原草送别》一样：“野火烧不尽，春风吹又生”。乐天与元稹一别已是九年，而且还会有好几个九年，直到乐天也身赴黄泉。乐天的生老病死，已经没有了元稹的参与！\n\n　　“君埋泉下泥销骨，我寄人间雪满头”。元稹埋在黄泉之下，泥土侵蚀着他的身体，也许早已和泥化作尘土，乐天也只是顶着满头白发暂时居住在人间。乐天是一位“深入浅出”型的沉思者：孤高、正直、磊落、坦荡。这句话正是白诗在字面、形式上看似浅显，而情意、内涵甚深的表现。我想起了祖父，我那逝世不久的祖父。很多时候，在我们的亲人活着时，我们是羞赧于将悄悄写下的那些关于他们的赞美文字与人分享的，尤其是不愿让他们本人看到。而今，祖父魂归大地、深埋黄土，他在人间的最后一席之地只是水泥石碑下一方小小的骨灰盒，家人把祖父与已逝世 13年的祖母合埋了。写着这些文字时，我想起祖父总是在清明前后轻轻擦拭着太祖父、太祖母及祖母的祭框，擦着擦着就出神地望着。可是如今，他深埋地下，谁又来擦拭他崭新的祭框呢？有关祖父的一切，我再也不会知晓了。他早年因公致残的左腿，还会风湿发作吗？黄泉该是个湿冷的地方吧？想到这些，我已经受不住了。有句话是残忍的：“我们将会死去很久”。乐天写下这首诗时，身边不是缺乏朋友，亦不是敌人泛滥。拉法特曾说：“没有朋友也没有敌人的人，就是凡夫俗子”。乐天恰好不是个凡夫俗子，他一生的朋友是很多的，比如李商隐就是他的忘年交。也正因为如此，在时隔九年后，乐天的这份思友之情才愈显得弥足珍贵！\n\n　　“阿卫韩郎相次去，夜台茫昧得知不”。阿卫是元稹的小儿子，韩郎是元稹的女婿。他们都先后死去了，黄泉渺茫昏暗能够知道这些吗？高寿的乐天目睹了后辈们的离去。一方面，活着的人想要知道死去的人的情况，另一方面，活着的人总是念念不忘地将人世间的新鲜事儿祷告给死者，纵然知道是徒劳，还是怀着这份希望。《古诗十九首》中有言：“去者日以疏,来者日以亲”。当乐天看着去者已去经年，而来者亦已成去者，这是多么大的内心荒凉！\n\n　　人生得一知己足矣，斯世当以同怀视之！浅品《梦微之》，我品味到了这世间有一种真情———相濡以沫！', poem_tags = '悼亡,怀念' WHERE poem_title = '梦微之' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '庭院中的芍药花艳丽虽艳丽，但格调不高；池面上的荷花明净倒是明净，却缺少热情；\n只有牡丹花才是真正的国色，是最美的花，当它开花的时候，其盛况轰动了整个京城。', poem_notes = '⑴牡丹：著名的观赏植物。古无牡丹之名，统称芍药，后以木芍药称牡丹。一般谓牡丹之称在唐以后，但在唐前，已见于记载。\n⑵庭前芍药：喻指宦官、权贵。芍药：多年生草本植物，属毛茛科，初夏开花，形状与牡丹相似。妖无格：妖娆美丽，但缺乏标格。妖：艳丽、妩媚。格：骨格。无格指格调不高。郑虔《胡本草》：“芍药，一名没骨花。”牡丹别名“木芍药”，芍药为草本，又称“没骨牡丹”，故作者称其“无格”。\n⑶芙蕖（qú）：荷花的别名。《尔雅·释草》：“荷，芙渠。其茎茄，其叶蕸，其本蔤，其华菡萏，其实莲，其根藕，其中菂，菂中薏。”郭璞注：“（芙渠）别名芙蓉，江东呼荷。”\n⑷国色：倾国之色。原意为一国中姿容最美的女子，此指牡丹花色卓绝，艳丽高贵。李濬《松窗杂录》：“上颇好诗，因问脩己曰：‘今京邑传唱牡丹花诗，谁为首出？’ 脩己对曰：‘臣尝闻公卿间多吟赏中书舍人李正封诗曰：“天香夜染衣，国色朝酣酒。”’上闻之，嗟赏移时。”吴钢、张天池《刘禹锡诗文选注》认为此为作者用来喻指革新人士。\n⑸“花开”句：说明唐代观赏牡丹风气极盛。李肇《唐国史补》卷中：“京城贵游尚牡丹，三十余年矣。每春暮，车马若狂，以不耽玩为耻。执金吾铺官围外，寺观种以求利，一本有直数万者。元和末，韩令始至长安，居第有之，遽命劚去，曰：‘吾岂效儿女子耶！’”白居易《买花》：“帝城春欲暮，喧喧车马度。共道牡丹时，相随买花去。贵贱无常价，酬直看花数：灼灼百朵红，戋戋五束素。上张幄幕庇，旁织巴篱护。水洒复泥封，移来色如故。家家习为俗，人人迷不悟。”京城：一般认为是指长安，但刘锬编的《咏花古诗欣赏》、鲍思陶等编的《中国名胜诗联精鉴》以及谢明等编的《历代咏物诗选读》认为此诗中的京城是指洛阳。', poem_appreciation = '此诗乃赞颂牡丹之作，其赞颂之手法，乃用抑彼扬此的反衬之法。诗人没有从正面描写牡丹的姿色，而是从侧面来写牡丹。诗一开始先评赏芍药和芙蕖。芍药与芙蕖本是为人所喜爱的花卉，然而诗人赞颂牡丹，乃用“芍药妖无格”和“芙蕖净少情”以衬托牡丹之高标格和富于情韵之美。“芍药”，本来同样是一种具有观赏价值的花卉，但据说到了唐代武则天以后，“牡丹始盛而芍药之艳衰” （王禹傅《芍药诗序》）。以至有人将牡丹比为“花王”，把芍药比作“近侍”。此处，刘禹锡也怀着主观感情，把芍药说成虽妖娆但格调不高。“芙蕖”，是在诗文中常以清高洁净的面目出现的花卉，但刘禹锡大概因为她亭亭玉立于池面之中，令人只可远观而不可近玩的缘故，说她纯洁而寡情。这里暗示了牡丹兼具妖、净、格、情四种资质，可谓花中之最美者。\n\n　　前两句用的是抑彼扬此的手法，为牡丹的出现作铺垫，而第三句笔锋一转，从正面赞颂牡丹。“唯有”一词，突出强调了只有牡丹才配称“真国色”，表明了诗人对牡丹的偏爱。“国色天香”则成了当时对牡丹的定评，也为后人所乐于接受和沿用。牡丹是花中之王，“百般颜色百般香”（邵雍《牡丹吟》）。但此诗却只字未提牡丹的色香，仅说“花开时节动京城”。这句表现了人们倾城而出观赏牡丹的热闹景象，以此赞颂牡丹为人赏爱的倾国之色。牡丹在诗人眼里，她姿色超群，是国中最佳“美人”。由于牡丹具有无与伦比的姿色，竞使得花开时节京城轰动，人们竞相品赏，生动地描述了当时的时尚，说出了多数人的心声。这里“动”字用得极妙，仿佛使人看到了当时人们为了观赏牡丹而万人空巷、人头攒动的生动场面。\n\n　　这短短四句诗，写了三种名花，而其中又深含了诗人丰富的审美思想。诗人没有忘记对芍药与荷花美好一面的赞誉，却又突出了牡丹的姿色，令人玩味无穷。作为花木，本来无所谓格调高下和感情的多寡，但诗人用拟人化和烘托的手法，巧妙生动地把自然美变成了艺术美，给人留下了难忘的印象。', poem_tags = '牡丹' WHERE poem_title = '赏牡丹' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '寒山转变得格外郁郁苍苍，秋水日日舒缓地流向远方。\n我柱杖伫立在茅舍的门外，迎风细听着那暮蝉的吟唱。\n渡头那边太阳快要落山了，村子里的炊烟一缕缕飘散。\n又碰到裴迪这个接舆酒醉，在恰如陶潜的我面前讴狂。', poem_notes = '辋川：水名，在今陕西省蓝田县南终南山下。山麓有宋之问的别墅，后归王维。王维在那里住了三十多年，直至晚年。裴迪：诗人，王维的好友，与王维唱和较多。\n转苍翠：一作“积苍翠”。转：转为，变为。苍翠：青绿色，苍为灰白色，翠为墨绿色。\n潺湲（chán yuán ）：水流声。这里指水流缓慢的样子，当作为“缓慢地流淌”解。\n听暮蝉：聆听秋后的蝉儿的鸣叫。暮蝉：秋后的蝉，这里是指蝉的叫声。\n渡头：渡口。余：又作“馀”。\n墟里：村落。孤烟：直升的炊烟，可以是倚门看到的第一缕村烟。\n值：遇到。接舆：陆通先生的字。接舆是春秋时楚国人，好养性，假装疯狂，不出去做官。在这里以接舆比裴迪。\n五柳：陶渊明。这里诗人以“五柳先生”自比。这两句诗的意思是说，又碰到狂放的裴迪喝醉了酒，在我面前唱歌。', poem_appreciation = '此诗所要极力表现的是辋川的秋景。一联和三联写山水原野的深秋晚景，诗人选择富有季节和时间特征的景物：苍翠的寒山、缓缓的秋水、渡口的夕阳，墟里的炊烟，有声有色，动静结合，勾勒出一幅和谐幽静而又富有生机的田园山水画。诗的二联和四联写诗人与裴迪的闲居之乐。倚杖柴门，临风听蝉，把诗人安逸的神态，超然物外的情致，写得栩栩如生；醉酒狂歌，则把裴迪的狂士风度表现得淋漓尽致。全诗物我一体，情景交融，诗中有画，画中有诗。\n\n　　此诗、画、音乐完美结合的五律。首联和颈联写景，描绘辋川附近山水田园的深秋暮色；颔联和尾联写人，刻画诗人和裴迪两个隐士的形象。风光人物，交替行文，相映成趣，形成物我一体、情景交融的艺术境界，抒写诗人的闲居之乐和对友人的真切情谊。\n\n　　“寒山转苍翠，秋水日潺湲。”首联写山中秋景。时在水落石出的寒秋，山间泉水不停歇地潺潺作响；随着天色向晚，山色也变得更加苍翠。不待颔联说出“暮”字，已给人以时近黄昏的印象。“转”和“日”用得巧妙。转苍翠，表示山色愈来愈深，愈来愈浓；山是静止的，这一“转”字，便凭借颜色的渐变而写出它的动态。日潺湲，就是日日潺湲，每日每时都在喧响；水是流动的，用一“日”字，却令人感觉它始终如一的守恒。寥寥十字，勾勒出一幅有色彩，有音响，动静结合的画面。\n\n　　“渡头余落日，墟里上孤烟。”颈联写原野暮色。夕阳欲落，炊烟初升，是田野黄昏的典型景象。渡头在水，墟里在陆；落日属自然，炊烟属人事：景物的选取是很见匠心的。“墟里上孤烟”，显系从陶潜“暧暧远人村，依依墟里烟”（《归田园居之一》）点化而来。但陶句是拟人化的表现远处村落上方炊烟萦绕、不忍离去的情味，王句却是用白描手法表现黄昏第一缕炊烟袅袅升到半空的景象，各有各的形象，各有各的意境。这一联是王维修辞的名句，历来被人称道。“渡头余落日”，精确地剪取落日行将与水面相切的一瞬间，富有包孕地显示了落日的动态和趋向，在时间和空间上都为读者留下想象的余地。“墟里上孤烟”，写的也是富有包孕的片刻。“上”字，不仅写出炊烟悠然上升的动态，而且显示已经升到相当的高度。\n\n　　首、颈两联，以寒山、秋水、落日、孤烟等富有季节和时间特征的景物，构成一幅和谐静谧的山水田园风景画。但这风景并非单纯的孤立的客观存在，而是画在人眼里，人在画图中，一景一物都经过诗人主观的过滤而带上了感情色彩。颔联：“倚杖柴门外，临风听暮蝉。”这就是诗人的形象。柴门，表现隐居生活和田园风味；倚杖，表现年事已高和意态安闲。柴门之外，倚杖临风，听晚树鸣蝉、寒山泉水，看渡头落日、墟里孤烟，那安逸的神态，潇洒的闲情，和“策扶老以流憩，时矫首而遐观”（《归去来辞》）的陶渊明有几分相似。事实上，王维对那位“古今隐逸诗人之宗”，也是十分仰慕的，就在这首诗中，不仅仿效了陶的诗句，而且在尾联引用了陶的典故：“复值接舆醉，狂歌五柳前。”陶文《五柳先生传》的主人公，是一位忘怀得失、诗酒自娱的隐者，“宅边有五柳树，因以为号焉。”实则，生正是陶潜的自我写照；而王维自称五柳，就是以陶潜自况的。接舆，是春秋时代“凤歌笑孔丘”的楚国狂士，诗人把沉醉狂歌的裴迪与楚狂接舆相比，乃是对这位年轻朋友的赞许。陶潜与接舆──王维与裴迪，个性虽大不一样，但那超然物外的心迹却是相近相亲的。所以，“复值接舆醉”的复字，不表示又一次遇见裴迪，而是表示诗人情感的加倍和进层：既赏佳景，更遇良朋，辋川闲居之乐，至于此极啊！末联生动地刻画了裴迪的狂士形象，表明了诗人对他的由衷的好感和欢迎，诗题中的赠字，也便有了着落。\n\n　　颔联和尾联，对两个人物形象的刻画，也不是孤立进行，而是和景物描写密切结合的。柴门、暮蝉、晚风、五柳，有形无形，有声无声，都是写景。五柳，虽是典故，但对王维说来，模仿陶渊明笔下的人物，植五柳于柴门之外，这是自然而然的。', poem_tags = '唐诗三百首,秋天,写景,抒情' WHERE poem_title = '辋川闲居赠裴秀才迪' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '我居住在邯郸客栈的时候正好是冬至佳节。晚上，我抱着双膝坐在灯前，只有影子与我相伴。\n我相信，家中的亲人今天会相聚到深夜，还应该谈论着我这个远行人。', poem_notes = '邯郸（Hándān）：地名，今河北省邯郸市。冬至：农历二十四节气之一。在十二月下旬，这天白天最短，夜晚最长。古代冬至有全家团聚的习俗。\n驿：驿站，古代的传递公文，转运官物或出差官员途中的歇息的地方。\n抱膝：以手抱膝而坐，有所思貌。影伴身：影子与其相伴。\n夜深：犹深夜。\n远行人：离家在外的人，这里指作者自己。', poem_appreciation = '《邯郸冬至夜思家》没有精工华美的辞藻，没有奇特新颖的想象，只是用叙述的语气来描绘远客的怀亲之情。其佳处，一是以直率质朴的语言，道出了人们常有的一种生活体验，感情真挚动人。二是构思精巧别致：首先，诗中无一“思”字，只平平叙来，却处处含着“思”情；其次，写自己思家，却从对面着笔。\n\n　　前两句纪实，侧面写“思家”。第一句叙客中度节，已植“思家”之根。在唐代，冬至这个日子，人们本应在家中和亲人一起欢度。但是如今作者在邯郸客店里碰上这个节日，不知如何是好。第二句，就写作者在邯郸客栈里过节的情景。“抱膝”二字，活画出枯坐的神态。“灯前”二字，既烘染环境，又点出“夜”，托出“影”。一个“伴”字，把“身”与“影”联系起来，并赋予“影”以人的感情。只有抱膝枯坐的影子陪伴着抱膝枯坐的身子，作者的孤寂之感，思家之情，已溢于言表。\n\n　　后两句运用想象，正面写“思家”。后两句笔锋一转，来个曲笔，不直接写自己如何思家，而是想象家人冬至夜深时分，家人还围坐在灯前，谈论着自己这个远行之人，以此来表现“思家”，使这种思乡之情扩大化，真实感人。其感人之处是：他在思家之时想象出来的那幅情景，却是家里人如何想念自己。这个冬至佳节，由于自己离家远行，所以家里人一定也过得很不愉快。当自己抱膝灯前，想念家人，直想到深夜的时候，家里人大约同样还没有睡，坐在灯前，“说着远行人”。具体“说”了什么，作者并没有指明，这就给读者留下了驰骋想象的广阔天地。每一个享过天伦之乐的人，有过类似经历的人，都可以根据自己的生活体验，想得很多。作者没用华丽的词句，没有玩弄过多的艺术技巧，而用平实质朴的语言，却把思乡之情表现的淋漓尽致。\n\n　　白居易的诗常以语言浅近、平实质朴著称，其意境也多显露。这首诗平实质朴，构思精巧别致，字里行间流露着淡淡的思乡之愁以及浓浓的怀亲之意。', poem_tags = '冬天,地名,思乡' WHERE poem_title = '邯郸冬至夜思家' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '夜雨一点点淋在梧桐树叶上，秋声难禁，打在芭蕉上，惹人愁思不断。半夜时分梦里回到了故乡。醒来只见灯花垂落，一盘残棋还未收拾，可叹啊，我孤单地留滞在新丰的旅馆里。靠在枕边，十年的经历，远在江南的双亲，都浮上心头。', poem_notes = '水仙子：曲牌名，又名凌波仙、凌波曲、湘妃怨等。句式为七七、七五七、三三四。八句四韵。 \n“一声梧叶一声秋”二句：梧桐叶的落下，预示了秋天的到来，雨打在芭蕉上的声音更使人增添了一份愁闷。一点芭蕉：是指雨点打在芭蕉叶上。 \n三更归梦三更后：夜半三更梦见回到了故乡，醒来时三更已过。归梦：梦归故乡。 \n灯花：油灯结成花形的余烬。 \n叹新丰孤馆人留：用唐代初期大臣马周的故事。新丰：在陕西新丰镇一带。马周年轻时，生活潦倒，外出时曾宿新丰旅舍，店主人见他贫穷，供应其他客商饭食，独不招待他，马周命酒一斗八升，悠然独酌。 \n枕上十年事：借唐人李泌所作传奇《枕中记》故事，抒发作者的辛酸遭遇。 \n二老：指年老的双亲。', poem_appreciation = '这是一首写羁旅愁思的小令。曲作一开始就用鼎足对形式：“一声梧叶一声秋。一点芭蕉一点愁。三更归梦三更后。”既点明了时间、环境、又照应了题目，更交待了此曲的感情基调。梧桐叶落，飒飒声响，表明是深秋时节；以雨打芭蕉叙出气候，芭蕉叶大而较硬，声音清晰而杂乱，与寂寥的旅人的愁绪自然和谐地共鸣起来，仿佛打在心上，千愁万苦，如雨点密集而下，创造了无限凄凉的环境。作者以《夜雨》为题，通篇却不着一个“雨”字，而是从听觉人手，给秋以声，给芭蕉以愁，借“雨”写“愁”；“一声”声，“一点”点，既形象地写出了秋雨连绵不断的特点，也暗示了主人公的缕缕愁思如同这秋雨一样无法断绝，从而深化了曲子的意境。接着连用两个“三更”，以点出“归梦”之难成：由于万千愁绪，以致夜不能寐。归乡之梦又为作者平添了一份乡愁，故“归梦”两字承上启下，既补叙了愁因，又为下文梦醒的描写作了必要的铺垫。梧桐滴雨，雨打芭蕉，古代的文人骚客常以此描写人生的愁苦，加之深秋夜雨，孤身一人，客居他乡，半夜“归梦”，引起人无限的愁思和惘怅。因此，作者以一个“愁”字，点出全曲的感情基调。\n\n　　“落灯花棋未收”，雨夜下棋，本为排遣愁闷，然而棋后懒于收捡，可见是越下越愁闷，正像李白所言“抽刀断水水更流，举杯消愁愁更愁”。此句从视觉角度渲染乡愁，化用宋代诗人赵师秀《约客》诗：“有约不来过夜半，闲敲棋子落灯花。”的诗意，写雨夜客居时的孤寂。而残灯照空局的景象，则进一步表现了深秋雨夜的凄凉和愁苦。因此，“落灯花棋未收”是由景向情过渡句，接“三更”时分，引出更深喟叹。\n\n　　“叹新丰逆旅淹留。”此句借用唐代名臣马周之典，唐人马周未登第时，曾旅宿新丰，受店主冷遇，后世借指旅愁。《坚瓠集》载徐再思“旅寄江湖十年不归”，曾滞留北方十多年，然而仕途多艰，仅做过下等的小官。这里以马周自况，羁旅他乡，饱受寂寥愁苦，然而仕进无门，一事无成，穷途潦倒，仿佛马周当年为新丰客般备受冷落。而马周穷途尚有常何引荐，自己怀才不遇，久困异乡，前途渺茫。而且客居地“新丰”之得名本就与乡愁有关，加之前句“归梦”的导诱，联想到自己与马周境遇迥异，是愁上添愁。一个“叹”字，把自己羁旅异乡的孤寂，怀才不遇的愁闷，尽收其中。\n\n　　“枕上十年事，江南二老忧，都到心头。”作者躺在床上，回想起十年来孤身一人漂泊在外的种种往事，年迈的父母远在江南，自己不但未尽孝，反倒让二老担忧，如今功名也未成。孤寂、怨恨、自责、思亲等种种愁苦，都凝结为“都到心头”四字，道出了深秋夜雨时心头愁苦的具体内容。\n\n　　此曲采用作者惯用的重词叠字手法，善用数词人曲，如“一声”、“一点”、“三更”、“十”、“二”等，给人以回环复沓，一咏三叹之感。全曲情景交融，用典用对，贴切自然，不愧为“情中紧语”。', poem_tags = '羁旅,孤独,写雨,感伤' WHERE poem_title = '水仙子·夜雨' AND poem_author = '徐再思';
UPDATE edu_poem SET poem_translation = '我自己并不是生性喜好风尘生活，之所以沦落风尘，是为前生的因缘（即所谓宿命）所致花落花开自有一定的时候，可这一切都只能依靠司其之神东君来作主。\n该离终须要离开，离开这里又如何能待下去。若能将山花插满头，不需要问我归向何处。', poem_notes = '风尘：古代称妓女为堕落风尘。\n前缘：前世的因缘。\n东君：司春之神，借指主管妓女的地方官吏。\n奴：古代妇女对自己的卑称\n终须：终究。', poem_appreciation = '那一年，时任台州的太守唐与正（字仲友），相召严蕊前来作陪酒局。眼前是红红白白的桃花，千枝万朵，盛开如海。有蜂儿追，蝶儿舞，燕子帘前轻声语。\n\n　　美人与桃花，相映成趣。\n\n　　趁着酒兴，唐与正命严蕊以身边的红白桃花为题，赋词一首。于是，就有这么一首关于桃花的《如梦令》。当时，唐仲友还赏了她两匹缣帛。\n\n　　这首小令的大意是：\n\n　　假如你说它是梨花，答案当然错了。倘若你再猜它是杏花，也不对。\n\n　　你瞧它那种洁白与粉红相间的颜色，实在是春风里的另一番风景和情趣。\n\n　　曾经记得，曾经还记得。\n\n　　当年有人在武陵源看到此花的时候，被它的娇艳之美，所深深沉醉过。\n\n　　整首词，像是猜一条谜语。词是谜面，谜底是桃花。\n\n　　词作简练传神，既有脱俗的清新，也有几分俏皮之感。读来具体可感，含蓄有味。清人冯金伯的《词苑萃编》和叶申芗的《本事词》书中，皆记载了这首词。\n\n　　词人借以梨花的白，杏花的红，故意卖关子不提及“桃花”的花名，却在结句写“人在武陵微醉”，让人很快能想到了陶渊明那篇著名的散文《桃花源记》。\n\n　　这时，我们方才顿悟，原来是桃花。\n\n　　在南宋，另外一位词人郑域，其实也写过此类风格的一首《昭君怨》：\n\n　　道是花来春未，道是雪来香异。竹外一枝斜，野人家。\n\n　　冷落竹篱茅舍，富贵玉堂琼榭。两地不同栽，一般开。\n\n　　花开的时候，春天未至。它犹似香雪，一些竹子旁边，能见到它一支横斜的疏影。\n\n　　各位再猜猜，这又是描写的啥花呢？\n\n　　同样，全篇构思也很巧妙，不着一“梅”字，却几乎都是对梅花真实的写照。\n\n　　作品暗示出了作者本人，虽然目前尚处于倍受冷落的阶段，但他仍坚持着自己人生的理想和追求。\n\n　　王国维先生在《人间词话》中说：“因大诗人所造之境，必合乎自然，所写之境，亦必邻于理想故也。”长久的歌妓生涯，使得她早已厌倦。故向往男耕女织的世外桃源，正是符合她理想中的生活。\n\n　　《宋词鉴赏辞典》中点评此词：“绝不同于一般滞于物象的咏物词，它纯然从空际著笔，空灵荡漾，不即不离，写出红白桃花之高标逸韵，境界愈推愈高远，令人玩味无极而神为之一旺。就艺术而言，可以说是词中之逸品。”\n\n　　因这首桃花词，她本人也被后人称之为了“桃花仙子”。\n\n　　如今，桃花依旧笑春风，而美人已不在。', poem_tags = '宋词三百首,宋词精选,婉约,女子,自白,无奈' WHERE poem_title = '卜算子·不是爱风尘' AND poem_author = '严蕊';
UPDATE edu_poem SET poem_translation = '深秋季节西墙外寒蝉不停地鸣唱，蝉声把我这囚徒的愁绪带到远方。\n怎堪忍受正当玄鬓盛年的好时光，独自吟诵白头吟这么哀怨的诗行。\n露重翅薄欲飞不能世态多么炎凉，风多风大声响易沉难保自身芬芳。\n无人知道我像秋蝉般的清廉高洁，有谁能为我表白冰晶玉洁的心肠？', poem_notes = '西陆：指秋天。\n南冠：楚冠，这里是囚徒的意思。用深：一作“侵”。\n玄鬓：指蝉的黑色翅膀，这里比喻自己正当盛年。那堪：一作“不堪”。\n白头吟：乐府曲名。\n露重：秋露浓重。飞难进：是说蝉难以高飞。\n响：指蝉声。沉：沉没，掩盖。\n高洁：清高洁白。古人认为蝉栖高饮露，是高洁之物。作者因以自喻。\n予心：我的心。', poem_appreciation = '小序鉴赏\n\n　　这首诗前有一段序，而一些唐诗选本往往只录诗，对序则弃而不录。其实这段序文与诗是一有机整体，诗中比兴寓意，亦即自然之物与人格化身的契合，是以序文的铺叙直言为前提的。欲解二者契合之妙，不可不读这首诗的序。\n\n　　可以说这是一篇简短而精美的骈文，是一篇很有情致的抒情小说。诗人在这段序文中叙说了自己作诗的缘起，叙说了蝉的形态、习性及美德，抒发了自己“失路艰虞，遭时徽纆”的哀怨之情。诗人首先从禁所的古槐写起，运用晋代殷仲文仕途失意及西周时召公明察狱讼的典故，表达了自己身陷囹圄的痛苦和乞盼有司明察的心愿。然后，写闻蝉鸣生悲感，“岂人心异于曩时，将虫响悲乎前听”，以反问的语句把蝉与己、心与物联系在一起。以拟人的笔法铺叙蝉的美德、从蝉的形态习性写起，写蝉适应季节的变化，随季节、气候的变化而出现；写蝉翼甚薄，蝉目常开，“不以道昏而昧其视，不以俗厚而易其真”。诗人谓之具有“君子达人之高行”。因为蝉有这样的美德，所以诗人才引蝉自喻，以蝉为自己的人格化身。刘勰《文心雕龙·物色》云：“情以物迁，辞以情发。一叶且或迎意，虫声有足引心。”骆宾王以蝉喻己，顾影自怜，正是感物联类，情以物迁。从骆宾王作于同时期的《萤火赋序》中也可印证此论断：“物有感而情动，迹或均而心异。响必应之于同声，道固从之于同类。”诗人的体验说明了感物生情的道理，人的审美心理结构与自然之物的某种同构对应。诗人咏蝉之妙，不仅在于符合同构对应的原理，而且还在于蝉意象所包涵的丰富的文化内蕴。\n\n　　诗歌鉴赏\n\n　　此诗起二句在句法上用对偶句，在作法上则用起兴的手法，以蝉声来逗起客思，诗一开始即点出秋蝉高唱，触耳惊心。接下来就点出诗人在狱中深深怀想家园。三、四两句，一句说蝉，一句说自己，用“那堪”和“来对”构成流水对，把物我联系在一起。诗人几次讽谏武则天，以至下狱。大好的青春，经历了政治上的种种折磨已经消逝，头上增添了星星白发。在狱中看到这高唱的秋蝉，还是两鬓乌玄，两两对照，不禁自伤老大，同时更因此回想到自己少年时代，也何尝不如秋蝉的高唱，而今一事无成，甚至入狱。就在这十个字中，诗人动作比兴的方法，把这分凄恻的感情，委婉曲折地表达了出来。同时，白头吟又是乐府曲名。相传西汉时司马相如对卓文君爱情不专后，卓文君作《白头吟》以自伤。其诗云：“凄凄重凄凄，嫁娶不须啼，愿得一心人，白头不相离。”（见《西京杂记》）这里，诗人巧妙地运用了这一典故，进一步比喻执政者辜负了诗人对国家一片忠有之忱。“白头吟”三字于此起了双关的作用，比原意更深入一层。十字之中，什么悲呀愁呀这一类明点的字眼一个不用，意在言外，充分显示了诗的含蓄之美。\n\n　　接下来五六两句，纯用“比”体。两句中无一字不在说蝉，也无一字不在说自己。“露重”“风多”比喻环境的压力，“飞难进”比喻政治上的不得意，“响易沉”比喻言论上的受压制。蝉如此，诗人也如此，物我在这里打成一片，融混而不可分了。咏物诗写到如此境界，才算是“寄托遥深”。\n\n　　诗人在写这首诗时，由于感情充沛，功力深至，故虽在将近结束之时，还是力有余劲。第七句再接再厉，仍用比体。秋蝉高居树上，餐风饮露，没有人相信它不食人间烟火。这句诗人喻高洁的品性，不为时人所了解，相反地还被诬陷入狱，“无人信高洁”之语，也是对坐赃的辩白。然而正如战国时楚屈原《离骚》中所说：“世混浊而不分兮，好蔽美而嫉妒”。在这样的情况下，没有一个人来替诗人雪冤。“卿须怜我我怜卿”，意谓：只有蝉能为我而高唱，也只有我能为蝉而长吟。末句用问句的方式，蝉与诗人又浑然一体了。\n\n　　好诗，不但要有诗眼，以放“灵光”，而且有时须作“龙吟”，以发“仙声”。对照杨炯的《从军行》与杜甫《蜀相》，两诗若无“宁为百夫长，胜作一书生”，“出师未捷身先死，长使英雄泪满襟”这样的“龙吟”句殿后，直抒胸臆，剖献“诗心”，则全篇就木然无光了。此诗亦然，尾联诗人愤情冲天，勃发“龙吟”，喷出蕴蓄许久的真情：“无人信高洁，谁为表予心”，遂脱去了前三联罩裹诗句的“蝉身”，使人看到了作者洁纯无瑕的报国诚心，这颗诚心恰如其《序》所说，乃“有目斯开、不以道昏而昧其视，有翼自薄，不以俗厚而易其真。吟乔树之微风，韵姿天纵；饮高秋之坠露，清畏人知。”不以世俗更易秉性，宁饮坠露也要保持“韵姿”。正是这裂帛一问，才使《在狱咏蝉》成为唐诗的卓荦名篇，超然于初唐诸宫体艳诗之上。\n\n　　这首诗作于患难之中，感情充沛，取譬明切，用典自然，语多双关，于咏物中寄情寓兴，由物到人，由人及物，达到了物我一体的境界，是咏物诗中的名作。', poem_tags = '唐诗三百首,咏物' WHERE poem_title = '咏蝉 / 在狱咏蝉' AND poem_author = '骆宾王';
UPDATE edu_poem SET poem_tags = '诗经,民歌,劳动' WHERE poem_title = '国风·周南·芣苢' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '杭州有个卖水果的人，擅长贮藏柑橘，经历一整年也不溃烂，拿出它们的时候还是光彩鲜明的样子，玉石一样的质地，金灿灿的颜色。放到市场上，卖（比别人的高出）十倍的价钱。人们争相购买他的柑橘。\n\n　　我买到了其中的一个，切开它，像有股烟直扑口鼻，看它的里面，干枯得像破败的棉絮。我对此感到奇怪，问他说：“你卖给别人的柑橘，是打算用来装满在盛祭品的容器中，祭祀祖先、招待宾客的吗？还是要炫耀它的外表用来欺骗傻子和瞎子的吗？这样欺骗人的行为实在是太过分了。”\n\n　　卖柑橘的人笑着说：“我从事这个行业已有好多年了。我依赖这个用来养活自己。我卖它，别人买它，不曾有人说过什么的，却唯独不能满足您吗？世上做欺骗的事的人不少，难道仅仅只有我一个吗？你还没有好好考虑这个问题。\n\n　　那些佩戴虎形兵符、坐在虎皮上的人，威武的样子，好像是捍卫国家的将才，他们果真能拥有孙武、吴起的谋略吗？那些戴着高帽子，拖着长长带子的人，气宇轩昂的坐在朝堂之上，他们果真能够建立伊尹、皋陶的业绩吗？盗贼四起却不懂得抵御，百姓困苦却不懂得救助，官吏狡诈却不懂得禁止，法度败坏却不懂得治理，奢靡的浪费粮食却不懂得羞耻。看看那些坐在高堂上，骑着大马，喝着美酒，吃着美食的人，哪一个不是威风凛凛、令人敬畏、显赫的值得人们效仿？可是无论到哪里，又有谁不是外表如金似玉、内心破败得像破棉絮呢？你看不到这些现象，却只看到我的柑橘！”\n\n　　我默默地没有话用来回答。回来思考这卖柑人的话，觉得他像是像东方朔那样诙谐多讽、机智善辩的人。难道他是对世间邪恶现象激愤痛恨之人吗？因而假托柑橘用来讽刺吗？', poem_notes = '涉：经过，经历。\n溃：腐烂，腐败。\n烨（yè）然：光彩鲜明的样子。\n玉：像玉石一样。\n贾（jià)：同“价”，价格。\n鬻（yù）：这里是买的意思。\n贸：买卖，这里是买的意思。\n若：像，好像。\n败絮：破败的棉絮。\n若：代词，你，你们。\n实：填满，装满。\n笾（biān）豆：古代祭祀时盛祭品用的两种器具。笾，竹制的食器。豆，木制、陶制或铜制的食器。\n炫：同“炫”，炫耀，夸耀。\n惑：迷惑，欺骗。\n愚瞽（gǔ）：愚蠢的人和瞎子。瞽，瞎子。\n为：做。\n欺：欺骗人的事。\n业：以······为职业。\n赖：依赖，依靠。\n食（sì）：同“饲”，这里有供养、养活的意思。\n夫：发语词。\n虎符：虎形的兵符，古代调兵用的凭证。\n皋（gāo）比（pí）：虎皮，指将军的坐席。比，通“皮”，毛皮。\n洸（guāng）洸：威武的样子。\n干城之具：捍卫国家的将才。干，盾牌，文中意为捍卫。干和城都用以防御。具，将才。\n孙、吴：指古代著名军事家孙武和吴起。\n略：谋略。\n峨：高高地，指高戴。\n拖长绅：拖着长长的腰带。绅，古代士大夫束在外衣上的带子。\n昂昂：气宇轩昂的样子。\n庙堂：指朝廷。\n器：才能，本领，这里指“有才能的人”。\n伊、皋（gāo）：指古代著名政治家伊尹和皋陶。\n业：功业。\n起：兴起。\n御：抵御。\n斁（dù）：败坏。\n坐：坐在高位的意思，指那些在高位上却不干正事。\n糜：通“靡”，浪费。\n廪（lǐn）粟：国家发的俸米。\n醉：醉饮。\n饫（yù）：饱食。\n巍巍：高大的样子。\n赫赫：显赫的样子。\n象：模仿。\n金玉其外、败絮其中：比喻虚有其表，及外表好而实质坏的人\n类：像。\n东方生：指东方朔。汉武帝时曾任太中大夫，性格诙谐，善于讽谏。\n滑稽（古书中读作gǔ jī）之流：指诙谐多讽、机智善辩的人。\n疾：愤恨。\n愤世疾邪：激愤、痛恨世间邪恶的现象。\n托：假托。', poem_appreciation = '这是一篇著名的寓言体讽刺散文，全文可分为三个部分。第一部分以洗炼的笔墨记述了故事的经过，可说是全文的引子，作者先写柑子外表具有金玉之美，其中却如败絮之劣，在一优一劣而形成的鲜明对比之中，自然而然地引起发问，“将炫外以惑愚瞽也？”也自然而然地引出指责，“甚矣哉，为欺也！”作者在此突出一个“欺”字，这是全文的核心，也是贯串始终的主线，看似不经意地提出，实则是精心设计的。正是这个文眼，才引起卖柑者大段的深刻的议论。\n\n　　第二部分是全文的重点，通过卖柑人之口，揭露那些达官绅士欺世盗名的真相。文章的构思非常巧妙，“卖者笑曰”一个“笑”字用得很好，首先表现在后面的大段议论只是由一个小商贩在谈笑诙谐中说出，这就亲切又可信；其次表现了一个普通人对那些不可一世的人的鄙视。小商贩的回答也是巧妙之极，用一句反问“而独不足子所乎？”它揭示面对“欺”道横行的社会，人们已经麻木。紧接着再用一个反问“而独我也乎？”这个反问比前一个反问更有份量，它既突出了言者对“欺”道横行社会的强烈憎恨，又使愤懑之词如流涌出。为证实自己的论点，卖柑者以排比句式，历数了行“大欺”的人。先用两个长排比句描写武将“洸洸乎干城之具”、文官“昂昂乎庙堂之器”，以之与柑子“烨然”外表相对照；接着又连用五个短排比句揭露其实质，原来是文不能治国、武不能治军之众。为了更琳漓尽致地宣泄自己愤世嫉邪之情感，文章又用两个反问句进行反复揭露。反复揭露使卖柑者“今子是之不察，而以察吾柑”一句指责得有理，批评得有力。\n\n　　第三部分是文章的结尾，作者没有写自己如何慷慨激昂地响应卖柑者之言，却是“退而思其言”，这样既使文章形成一种跌宕美，也表明作者在深思熟虑之中品味其言的真谛所在，承认其言的真实性和合理性。\n\n　　这篇文章由买卖一个坏了的柑橘的小事引起议论，假托卖柑者的一席话，以形象、贴切的比喻，揭示了当时盗贼蜂起，官吏贪污，法制败坏，民不聊生的社会现实，有力地讽刺了那些冠冕堂皇、声威显赫的达官贵人们本质上都是“金玉其外，败絮其中”的欺世盗名的人物，从而有利抨击了元末统治者及统治集团的腐朽无能还有社会当下的黑暗，抒发了作者愤世嫉俗的情感。', poem_tags = '古文观止,寓言,故事,抒怀' WHERE poem_title = '卖柑者言' AND poem_author = '刘基';
UPDATE edu_poem SET poem_translation = '东风飒飒，阵阵细雨随风飘散纷飞，\n荷花塘外的那边，传来了声声轻雷。\n有锁纽的金蟾香炉，香烟缭绕飘逸，\n状似玉虎的辘轳，牵引绳索汲井水。\n贾女隔帘窥韩寿，是爱他年轻貌美，\n魏王梦见甄氏留枕，赋诗比作宓妃。\n呵，我这颗心不再与春花一同萌发；\n免得使我寸寸相思，都化成了烟灰。', poem_notes = '金蟾句：意谓虽有金蟾啮锁，香烟犹得进入。金蟾：旧注说是“蟾善闭气，古人用以饰锁”。啮：咬。\n玉虎句：意谓井水虽深，玉虎犹得牵丝汲之。玉虎：井上的辘轳。丝：井索。汲：引。\n贾氏句：晋韩寿貌美，司空南充招为掾，贾女于窗格中见韩寿而悦之，遂通情。贾女又以晋帝赐贾充之西域异香赠寿。韩掾少：为了韩寿的年轻俊美。掾：僚属。少：年轻。\n宓妃句：魏曹植曾作《洛神赋》，赋中叙述他和洛河女神宓妃相遇事。宓妃：指洛神，传说为伏（宓）羲之女。留枕：这里指幽会。魏王：曹植封东阿王，后改陈王。', poem_appreciation = '这首无题诗写一位深锁幽闺的女子追求爱情而幻灭的绝望之情。\n\n　　首联“飒飒东风细雨来，芙蓉塘外有轻雷。”描绘环境气氛：飒飒东风，飘来蒙蒙细雨；芙蓉塘外，传来阵阵轻雷。既隐隐传达了生命萌动的春天气息，又带有一些凄迷黯淡的色调，烘托出女主人公春心萌动和难以名状的迷惘苦闷。东风细雨，容易令人联想起“梦雨”的典故；芙蓉塘即莲塘，在南朝乐府和唐人诗作中，常常代指男女相悦传情之地；“轻雷”则又暗用司马相如《长门赋》：“雷殷殷而响起兮，声象君之车音。”这一系列与爱情密切相关的词语，所给予读者的暗示和联想是很丰富的。纪昀说：“起二句妙有远神，可以意会。”所谓“远神，是指这种富于暗示性的诗歌语言所构筑的渺远的艺术意境，一种难以言传的朦胧美。\n\n　　颔联“金蟾啮锁烧香入，玉虎牵丝汲井回。”写女子居处的幽寂。金蟾是一种蟾状香炉；“锁”指香炉的鼻钮，可以开启放入香料；玉虎，是用玉石装饰的虎状辘轳，“丝”指井索。室内户外，所见者惟闭锁的香炉，汲井的辘轳，它们衬托出女子幽处孤寂的情景和长日无聊、深锁春光的惆怅。香炉和辘轳，在诗词中也常和男女欢爱联系在一起，它们同时又是牵动女主人公相思之情的东西，这从两句分别用“香”、“丝”谐音“相”、“思”可以见出。总之，这一联兼用赋、比，既表现女主人公深闭幽闺的孤寞，又暗示她内心时时被牵动的情丝。\n\n　　颈联出句“贾氏窥帘韩掾少”使用贾充女与韩寿的爱情故事。见《世说新语》载：晋韩寿貌美，大臣贾充辟他为掾（僚属）。一次充女在帘后窥见韩寿，私相慕悦，遂私通。女以皇帝赐充之西域异香赠寿。被充所发觉，遂以女妻寿。对句“宓妃留枕魏王才”使用甄后与曹植的爱情故事。见《文选·洛神赋》李善注说：魏东阿王曹植曾求娶甄氏为妃，曹操却将她许给曹丕。甄后被谗死后，曹丕将她的遗物玉带金镂枕送给曹植。曹植离京归国途经洛水，梦见甄后对他说：“我本托心君王，其心不遂。此枕是我在家时从嫁，前与五官中郎将（曹丕），今与君王。”曹植感其事作《感甄赋》，后明帝改名《洛神赋》（句中“宓妃”即洛神，代指甄后）。由上联的“烧香”引出贾氏窥帘，赠香韩掾；由“牵丝（思）”引出甄后留枕，情思不断，藕断丝连。这两个爱情故事，尽管结局有幸有不幸，但在女主人公的意念中，无论是贾氏窥帘，爱韩寿之少俊，还是甄后情深，慕曹植之才华，都反映出青年女子追求爱情的愿望之强烈，奔放。末联“春心莫共花争发，一寸相思一寸灰！”突然转折，向往美好爱情的心愿切莫和春花争荣竞发，因为寸寸相思都化成了灰烬。这是深锁幽闺、渴望爱情的女主人公相思无望的痛苦呼喊。热情转化成幻灭的悲哀和强烈的激愤。以“春心”喻爱情的向往，是平常的比喻；但把“春心”与“花争发”联系起来，不仅赋予“春心”以美好的形象，而且显示了它的自然合理性。“相思”本是抽象的概念，诗人由香销成灰联想出“一寸相思一寸灰”的奇句，化抽象为具象，用强烈对照的方式显示了美好事物之毁灭，使这首诗具有一种动人心弦的悲剧美。\n\n　　李商隐写得最好的爱情诗，几乎全是写失意的爱情。而这种失意的爱情中又常常融入自己的某些身世之感。在相思成灰的爱情感慨中也可窥见他仕途失意的不幸遭际。', poem_tags = '唐诗三百首,女子,相思,爱情' WHERE poem_title = '无题·飒飒东风细雨来' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '姿态美好举止轻盈正是十三年华，活象二月初含苞待放一朵豆蔻花。\n看遍扬州城十里长街的青春佳丽，卷起珠帘卖俏粉黛没有比得上她。\n\n聚首如胶似漆作别却象无情；只觉得酒筵上要笑笑不出声。\n案头蜡烛有心它还依依惜别；你看它替我们流泪流到天明。', poem_notes = '娉娉袅袅：形容女子体态轻盈美好。十三余：言其年龄。\n豆蔻：据《本草》载，豆蔻花生于叶间，南人取其未大开者，谓之含胎花，常以比喻处女。\n“春风二句”：说繁华的扬州城中，十里长街上有多少歌楼舞榭，珠帘翠幕中有多少佳人姝丽，但都不如这位少女美丽动人。\n“多情”一句：意谓多情者满腔情绪，一时无法表达，只能无言相对，倒象彼此无情。\n樽：古代盛酒的器具。', poem_appreciation = '第一首诗是诗人赠别一位相好的歌妓的，从同题另一首（“多情却似总无情”）看，彼此感情相当深挚。不过那一首诗重在“惜别”，这一首却重在赞颂对方的美丽，引起惜别之意。第一句就形容了一番：“娉娉袅袅”是身姿轻盈美好的样子，“十三余”则是女子的芳龄。七个字中既无一个人称，也不沾一个名词，却能给读者完整、鲜明生动的印象，使人如目睹那美丽的倩影。其效果不下于“翩若惊鸿，宛若游龙；荣耀秋菊，华茂春松”（曹植《洛神赋》）那样具体的描写。全诗正面描述女子美丽的只这一句。就这一句还避实就虚，其造句真算得空灵入妙。第二句不再写女子，转而写春花，是将花比女子。“豆蔻”产于南方，其花成穗时，嫩叶卷之而生，穗头深红，叶渐展开，花渐放出，颜色稍淡。南方人摘其含苞待放者，美其名曰“含胎花”，常用来比喻处女。而“二月初”的豆蔻花正是这种“含胎花”，用来比喻“十三余”的小歌女，是形象优美而又贴切的。而花在枝“梢头”，随风颤袅者，当尤为可爱。所以“豆蔻梢头”又暗自照应了“娉娉袅袅”四字。这里的比喻不仅语新，而且十分精妙，又似信手拈来，写出人似花美，花因人艳，说它新颖独到是不过分的。一切“如花似玉”、“倾国倾城”之类比喻形容，在这样的诗句面前都会黯然失色。而杜牧写到这里，似乎还是一个开始，他的才情尚未发挥尽致。\n\n　　当时诗人正要离开扬州，“赠别”的对象就是他在幕僚失意生活中结识的一位扬州的歌妓。所以第三句写到“扬州路”。唐代的扬州经济文化繁荣，时有“扬一益（成都）二”之称。“春风”句意兴酣畅，渲染出大都会富丽豪华气派，使人如睹十里长街，车水马龙，花枝招展。这里歌台舞榭密集，美女如云。“珠帘”是歌楼房栊设置，“卷上珠帘”则看得见“高楼红袖”。而扬州路上不知有多少珠帘，所有帘下不知有多少红衣翠袖的美人，但“卷上珠帘总不如”。不如谁，谁不如，诗中都未明说，含吐不露。这里“卷上珠帘”四字用得很不平常，它不但使“总不如”的结论更形象，更有说服力；而且将扬州珠光宝气的繁华气象一并传出。诗用压低扬州所有美人来突出一人之美，有众星拱月的效果。《升庵诗话》云：“书生作文，务强此而弱彼，谓之‘尊题’。”杜牧此处的修辞就是“尊题格”。但由于前两句美妙的比喻，这里“强此弱彼”的写法显得自然入妙。\n\n　　杜牧此诗，从意中人写到花，从花写到春城闹市，从闹市写到美人，最后又烘托出意中人。二十八字挥洒自如，游刃有余，真俊爽轻利之至。别情人不用一个“你（君、卿）”字；赞美人不用一个“女”字；甚至没有一个“花”字、“美”字，“不著一字”而能“尽得风流”。语言空灵清妙，贵有个性。\n\n　　第二首抒写诗人对妙龄歌女留恋惜别的心情。\n\n　　齐、梁之际的江淹曾经把离别的感情概括为“黯然销魂”四字。但这种感情的表现，却因人因事的不同而千差万别，这种感情本身，也不是“悲”、“愁”二字所能了得。杜牧此诗不用“悲”、“愁”等字，却写得坦率、真挚，道出了离别时的真情实感。\n\n　　诗人同所爱不忍分别，又不得不分别，感情是千头万绪的。“多情却似总无情”，明明多情，偏从“无情”着笔，著一“总”字，又加强了语气，带有浓厚的感情色彩。诗人爱得太深、太多情，以至使他觉得，无论用怎样的方法，都不足以表现出内心的多情。别筵上，凄然相对，象是彼此无情似的。越是多情，越显得无情，这种情人离别时最真切的感受，诗人把它写出来了。“唯觉樽前笑不成”，要写离别的悲苦，他又从“笑”字入手。一个“唯”字表明，诗人是多么想面对情人，举樽道别，强颜欢笑，使所爱欢欣。但因为感伤离别，却挤不出一丝笑容来。想笑是由于“多情”，“笑不成”是由于太多情，不忍离别而事与愿违。这种看似矛盾的情态描写，把诗人内心的真实感受，说得委婉尽致，极有情味。\n\n　　题为“赠别”，当然是要表现人的惜别之情。然而诗人又撇开自己，去写告别宴上那燃烧的蜡烛，借物抒情。诗人带着极度感伤的心情去看周围的世界，于是眼中的一切也就都带上了感伤色彩。这就是刘勰所说的：“属采附声，亦与心而徘徊”（《文心雕龙·物色》）。“蜡烛”本是有烛芯的，所以说“蜡烛有心”；而在诗人的眼里烛芯却变成了“惜别”之心，把蜡烛拟人化了。在诗人的眼里，它那彻夜流溢的烛泪，就是在为男女主人的离别而伤心了。“替人垂泪到天明”，“替人”二字，使意思更深一层。“到天明”又点出了告别宴饮时间之长，这也是诗人不忍分离的一种表现。\n\n　　诗人用精炼流畅、清爽俊逸的语言，表达了悱恻缠绵的情思，风流蕴藉，意境深远，余韵不尽。就诗而论，表现的感情还是很深沉、很真挚的。杜牧为人刚直有节，敢论列大事，却也不拘小节，好歌舞，风情颇张，此诗亦可见此意。', poem_tags = '唐诗三百首,离别,女子' WHERE poem_title = '赠别二首' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '天黑了，天黑了，为什么还不回家？如果不是为君主，何以还在露水中！\n天黑了，天黑了，为什么还不回家？如果不是为君主，何以还在泥浆中！', poem_notes = '式：作语助词。微：（日光）衰微，黄昏或曰天黑。\n微：非。微君：要不是君主。\n中露：露中。倒文以协韵。\n躬：身体。', poem_appreciation = '全诗只有短短二章，都以“式微，式微，胡不归”起调：天黑了，天黑了，为什么还不回家？诗人紧接着便交待了原因：“微君之故，胡为乎中露”；“微君之躬，胡为乎泥中”。意思是说，为了君主的事情，为了养活他们的贵体，才不得不终年累月、昼夜不辍地在露水和泥浆中奔波劳作。然而，《式微》诗上下二章只变换了两处文字， 但就在这巧妙的变换中， 体现出了作者用词的独具匠心。\n\n　　其一， 一章“微君之故”和二章“微君之躬”。上下章只变换“故”“躬”两字， 却使诗歌语义饱满、押韵和谐。“微君之故”， 朱熹《诗集传》释为： “我若非以君之故”； “微君之躬”， “躬”是“躳”的异体， 《尔雅·释言》： “躬， 身也。”躬、身二字互训， 故“躬”即自身也， 也即“君”。“微君之躬”即“我若无君”。上章言“我若非以君之故”， 下章言“我若无君”。上下章表达相同的意思却运用不同的字眼， 把作者委婉含蓄的感情表达得淋漓尽致。其二， 一章“胡为乎中露”和二章“胡为乎泥中”。“露”为“路”的假借字。《尔雅·释名》： “路， 露也。言人所践蹈而露见也。”方玉润《诗经原始》： “‘泥中’犹言泥涂也。”按： “中露”也即今俗语所谓心里沉沉的， 像被什么东西堵得慌； “泥中”犹今所谓陷入泥中而不能自拔。因此“中露”、“泥中”是虚写而非实写， 上下章可互相补充理解。\n\n　　同时，作者字数的变换中， 始终不忘记押韵的和谐。一章“故”、“露”为阴声“鱼”韵和入声“铎”韵同用； 二章“躬”、“中”押阴声“侵”部韵。此两句在表达作者思想感情的同时， 又能押韵和谐字数整齐， 有一箭双雕之功效。短短二章，寥寥几句，受奴役者的非人处境以及他们对统治者的满腔愤懑，给读者留下极其深刻的印象。\n\n　　由是，重章换字， 押韵和谐。体现了一唱三叹、余味无穷的特色。体现了《诗经》精巧凝练的语言，兼有长短的句式， 节奏感强。《式微》诗短短32个字， 就包含了三言、四言和五言等多种变化， 工整与灵活相整合， 参差错落， 能极力地表达女主人公思想感情的起伏。而其句式的选择又是随着诗的内容和思想感情而灵活变化的， 增强了诗的节奏感。总之， 《式微》运用语言的艺术， 非但韵律和谐优美， 而且用词精巧。\n\n　　在艺术上，这首诗以设问强化语言效果。从全诗看，“式微，式微，胡不归”，并不是有疑而问，而是胸中早有定见的故意设问。诗人遭受统治者的压迫，夜以继日地在野外干活，有家不能回，苦不堪言，自然要倾吐心中的牢骚不平，但如果是正言直述，则易于穷尽，采用这种虽无疑而故作有疑的设问形式，使诗篇显得宛转而有情致，同时也引人注意，启人以思，所谓不言怨而怨自深矣。正是因为这些修辞手法的巧妙使用， 才使《式微》一诗“境界具于词语之外， 愈反复看去，愈觉其含义无穷。”', poem_tags = '诗经' WHERE poem_title = '国风·邶风·式微' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '漫漫长夜你撇下我远走到哪里？没有一点音讯。香阁门儿关上，眉儿紧紧皱起，月亮就要西沉。\n怎么忍心不把你追寻？怨恨这孤眠独寝。只有换我的心，变作你的心，你才会知道这相思有多么深。', poem_notes = '诉衷情：唐教坊曲名。因毛文锡词句有“桃花流水漾纵横”，又名《桃花水》；因顾夐本词，又名《怨孤衾》。\n永夜：长夜。\n眉敛：指皱眉愁苦之状。\n争忍：怎忍。\n孤衾：喻独宿。', poem_appreciation = '《诉衷情·永夜抛人何处去》是情人怨恋相思之词。此词运用白描手法，写一位独守空闺的少妇的情态与景物，表现并反衬出她在漫漫长夜中的孤寂与怨恨，既有文人词的细腻华美，又带有民歌风味，是写闺情的别开生面之作。\n\n　　“永夜抛人何处去？绝来音。”“永夜”，即漫漫长夜；一个“抛”字暗示出女子对自己命运的担心。起句劈面一问，不仅揭示了女子愁怨的根由，还写出了她因久盼不归而产生的焦灼、苦闷、不安和疑虑。下接“绝来音”，表明所爱深夜不归，并不是不得已的行为，而是故意给她的冷遇，一则写夜阑人静、悄无声息，烘托出女子的孤寂无伴；同时透露出在漫漫长夜、寂寂空闺中她一直在侧耳凝神聆听户外声息的不安心情，门外的每一点哪怕是极轻微的声音都会唤起她的希望，使她激动和喜悦。\n\n　　“香阁掩，眉敛，月将沉。”当希望之火一次次在心头燃起旋又熄灭以后，她终于明白今宵是无望的了，“香阁掩”三字表明了她内心的绝望。一个“掩”字，显示了她的情感所系，她并不想把那个无情的人拒于门外，依然为他留着门，闷坐空闺，独对孤灯，痴痴等待着他。“眉敛”，正是她内心深处压抑不住的怨情的不自禁的流露。然而直到月将西沉时分，他也没有给她消息，或者回来陪伴她。“月将沉”一句不仅点明天将破晓，它既暗示了清幽的月光没有给人以任何安慰，徒然增加了女子的愁思，也透露出女子为怨思所苦而一夜无眠，在辗转反侧之际，往日恩爱厮守、形影相随的情景尽在眼前，在独卧孤寝的凄清中更添加了几分寂寞和冷清。\n\n　　“争忍不相寻？怨孤衾。”她的语气里有埋怨，有委屈，“争忍”二字反问，表明她怨中有爱，情丝难解，既有不忍苛贵之意，也有不免怨怪之情，仔细体味，竟似有要对方发慈悲的意思。忍或不忍，不是因为情感的自然生发，不是因为情不自禁，而是来自慈悲的意念。然而稍加推究，闺门紧闭，室内一目了然，并无可寻。“寻”这一动作，正好显示她已陷于迷离恍惚的精神状态。等到她头脑稍为清醒，又得面对令人心碎的现实——孤衾独处。“怨孤衾”一句，短而有力，长夜难眠的孤独，自身情感依依而不获对应的痛苦，终于直接以一个“怨”字透出。“怨”，是因爱所生的恨，是不敢决裂而去的恨。\n\n　　“换我心，为你心，始知相忆深。”情之所钟，忽发痴语，这是女子发自内心深处的表白和对负心人的恳切呼唤。换心者，移心之谓也，主人公希望把自己的一颗心移置在对方的心腔里，以取得对方对自己思念之深的理解。如果对方已经彻底绝情，任是怎样他也不会回心转意了。虽是如此，但词这样写，却愈见感情激愤而又无可奈何，沉哀深痛，入木三分。这里既有对男子的嗔怨，更透出女子的一片深情，令人低徊不尽。\n\n　　词写痴情女子对负心情郎的期待、爱恋与幽怨。心不可换，情痴故欲换之，换之而不可得，益增其怨忧。写闺怨情至于此，形象鲜明生动，无以复加。', poem_tags = '宋词三百首,婉约,爱情,女子,思念' WHERE poem_title = '诉衷情·永夜抛人何处去' AND poem_author = '顾夐';
UPDATE edu_poem SET poem_tags = '古文观止,读书,感想' WHERE poem_title = '读孟尝君传' AND poem_author = '王安石';
UPDATE edu_poem SET poem_translation = '乡居少与世俗交游，僻巷少有车马来往。\n白天依旧柴门紧闭，心地纯净断绝俗想。\n经常涉足偏僻村落，拨开草丛相互来往。\n相见不谈世俗之事，只说田园桑麻生长。\n我田桑麻日渐长高，我垦土地日渐增广。\n经常担心霜雪突降，庄稼凋零如同草莽。', poem_notes = '野外：郊野。罕：少。人事：指和俗人结交往来的事。陶渊明诗里的“人事”、“人境”都有贬义，“人事”即“俗事”，“人境”即“尘世”。这句是说住在田野很少和世俗交往。\n穷巷：偏僻的里巷。鞅（ yāng）：马驾车时套在颈上的皮带。轮鞅：指车马。这句是说处于陋巷，车马稀少。\n白日：白天。荆扉：柴门。尘想：世俗的观念。这两句是说白天柴门紧闭，在幽静的屋子里屏绝一切尘俗的观念。\n时复：有时又。曲：隐僻的地方。墟曲：乡野。披：拨开。\n杂言：尘杂之言，指仕宦求禄等言论。但道：只说。\n这两句是说桑麻一天天在生长，我开垦的土地一天天广大。\n霰（xiàn现）：小雪粒。莽：草。', poem_tags = '田园,乡村,生活' WHERE poem_title = '归园田居·其二' AND poem_author = '陶渊明';
UPDATE edu_poem SET poem_translation = '鹧鸪在温暖的烟色荒地上面嬉戏，只见他们五彩斑斓的羽毛那么整齐；\n看它们的行动举止，类别与平日活泼的山鸡相象。\n天空阴沉雨水淋漓的时候，从巴丘湖，洞庭湖东南湖边的青草地上经过；\n黄陵庙花瓣飘落，只听鹧鸪的啼叫声音。\n身在异乡的客人刚一听到鸣叫，就不由自主抬起手臂，听任泪水沾湿衣袖；\n美丽的女子刚一听到鸣叫，开口唱和一曲充满相思情意的《山鹧鸪》，青黑色的眉毛黯然低垂。\n宽阔的湘江上鹧鸪叫声此起彼伏，同是不幸境遇的人们的情怀水乳交融；\n茂密的竹林丛中深处鹧鸪寻找温暖的巢穴，夕阳就要落山，带来悲凉的苦意。', poem_notes = '戏：嬉戏。\n烟芜：烟雾弥漫的荒地。\n锦翼齐：彩色的羽毛整齐。\n品流：等级，类别。\n雨昏：下雨天空阴沉。\n青草湖：又名巴丘湖，在洞庭湖东南。\n黄陵庙：祭祀娥皇、女英的庙。传说帝舜南巡，死于苍梧。二妃从征，溺于湘江，后人遂立祠于水侧，是为黄陵庙。\n游子：离家在外或久居外乡的人。\n乍（zhà）闻：刚听到。\n征袖：指游子的衣袖。征，远行。\n翠眉：古时女子用螺黛（一种青黑色矿物颜料）画的眉。\n湘江阔：宽阔的湘江。湘江：长江支流，在今湖南省。\n苦竹：竹的一种，笋味苦。\n日向：一作“春日”。', poem_tags = '写鸟,思乡' WHERE poem_title = '鹧鸪' AND poem_author = '郑谷';
UPDATE edu_poem SET poem_translation = '靖安宅里，天天面对着窗前的碧柳，凝眸念远；望驿台前，春意阑珊，花儿纷纷飘落到地面。\n两处美好的春光，在同一天消尽；此时，家里人思念着出门在外的亲人，出门在外的人一样也思念着家中的亲人。', poem_notes = '望驿台：在今四川广元。驿：旧时供传递公文的人中途休息、换马的地方。\n当窗柳：意即怀人。唐人风俗，爱折柳以赠行人，因柳而思游子。\n扑地：遍地。\n春光：一作“春风”。\n居人：家中的人。诗中指元稹的妻子。客：出门在外的人。指元稹。', poem_tags = '和诗,思念' WHERE poem_title = '望驿台' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '利欲驱使人东奔西走，如同万头火牛奔突一样，倒不如做个江湖上人，浪迹天涯，像沙鸥鸟那样自由自在。\n一日长似一年，闲暇无所事事的时候才感觉如此，即使是天大的事，喝醉了也就无事了。\n在捣衣棒的敲击声中，深巷里的明月渐渐西沉，井边的梧桐树忽然摇动叶落，方知故乡也是秋天了。\n想极目远眺，苦于没有登高的地方，哪能像陈登站在百尺楼上，高论天下大事呢。', poem_notes = '欲：欲望。 驱：赶逐。\n浪迹：到处漫游，行踪不定。\n休：此处作“忘了”解。\n井梧：水井边的梧桐树。\n元龙：陈元龙，即陈登，三国时人，素有扶世救民的志向。', poem_tags = '秋天,向往' WHERE poem_title = '秋思' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '我本是像那个接舆楚狂人，\n高声唱着凤歌去嘲笑孔丘。\n手里拿一根镶绿玉的棍杖，\n大清早辞别著名的黄鹤楼。\n攀登五岳寻仙道不畏路远，\n这一生就喜欢踏上名山游。\n秀美的庐山挺拔在南斗旁，\n九叠云屏像锦绣云霞铺张，\n湖光山影相互映照泛青光。\n金阙岩前双峰矗立入云端，\n三叠泉如银河倒挂三石梁。\n香炉峰瀑布与它遥遥相望，\n重崖叠嶂耸云霄莽莽苍苍。\n翠云红霞与朝阳相互辉映，\n鸟儿也飞不过吴天广又长。\n登高远望天地间壮观景象，\n大江悠悠东流去永不回还。\n天上万里黄云变动着风色，\n江流波涛九道如雪山奔淌。\n我喜欢为雄伟的庐山歌唱，\n这兴致因庐山风光而滋长。\n闲时观看石镜使心神清净，\n谢灵运足迹早被青苔掩藏。\n我要早服仙丹去掉尘世情，\n修炼三丹和积学道已初成。\n远远望见仙人正在彩云里，\n手里捧着芙蓉花朝拜玉京。\n早已约好神仙在九天会面，\n希望迎接你一同邀游太清。', poem_notes = '谣：不合乐的歌，一种诗体。卢侍御虚舟：卢虚舟，字幼真，范阳（今北京大兴县）人，唐肃宗时曾任殿中侍御史，相传“操持有清廉之誉”（见清王琦注引李华《三贤论》），曾与李白同游庐山。\n楚狂人：春秋时楚人陆通，字接舆，因不满楚昭王的政治，佯狂不仕，时人谓之“楚狂”。\n凤歌笑孔丘：孔子适楚，陆通游其门而歌：“凤兮凤兮，何德之衰……”劝孔不要做官，以免惹祸。这里，李白以陆通自比，表现对政治的不满，而要像楚狂那样游览名山过隐居的生活。\n绿玉杖：镶有绿玉的杖，传为仙人所用。\n五岳：即东岳泰山，西岳华山，南岳衡山，北岳恒山，中岳嵩山。此处泛指中国名山。\n南斗：星宿名，二十八宿中的斗宿。古天文学家认为浔阳属南斗分野（古时以地上某些地区与天某些星宿相应叫分野）。这里指秀丽的庐山之高，突兀而出。\n屏风九叠：指庐山五老峰东的九叠屏，因山丸叠如屏而得名。\n影落：指庐山倒映在明澈的鄱阳湖中。青黛（dài代）：青黑色。\n金阙（què确）：阙为皇宫门外的左右望楼，金阙指黄金的门楼，这里借指庐山的石门——庐山西南有铁船峰和天池山，二山对峙，形如石门。\n银河：指瀑布。三石梁：一说在五老峰西，一说在简寂观侧，一说在开先寺（秀峰寺）旁，一说在紫霄峰上。近有人考证，五老峰西之说不谬。\n香炉：南香炉峰。瀑布：黄岩瀑布。\n迥崖沓（tà踏）嶂：曲折的山崖，重叠的山峰。凌：高出。苍苍：青色的天空。\n吴天：九江春秋时属吴国。整句诗的意思：连鸟也难以飞越高峻的庐山和它辽阔的天空。\n大江：长江。\n黄云：昏暗的云色。\n白波九道：九道河流。古书多说长江至九江附近分为九道。李白在此沿用旧说，并非实见九道河流。雪山：白色的浪花。\n石镜：古代关于石镜有多种说法，诗中的石镜应指庐山东面的“石镜”——圆石，平滑如镜，可见人影。清我心：清涤心中的污浊。\n谢公：谢灵运。\n服：服食。还丹：道家炼丹，将丹烧成水银，积久又还成丹，故谓“还丹”。\n琴心三叠：道家修炼术语，一种心神宁静的境界。\n玉京：道教称元始天尊在天中心之上，名玉京山。\n先期：预先约好。汗漫:仙人名，一云造物者。九垓（gāī该）：九天之外。\n卢敖：战国时燕国人，周游至蒙谷山，见一古怪之士迎风而舞。卢敖邀他同游，那人笑着说：“吾与汗漫期于九垓之外，不可久留。”遂纵身跳入云中。太清：太空。', poem_appreciation = '此诗为写景名篇。诗人以大手笔描绘了庐山雄奇壮丽的风光，可谓描写庐山的千古绝唱。同时，此诗也表现了诗人的豪迈气概，抒发了诗人寄情山水、纵情遨游、狂放不羁的情怀，表达了诗人想在名山胜景中得到寄托，在神仙境界中逍遥的愿望，流露了诗人因政治失意而避世求仙的愤世之情。　\n\n　　“我本楚狂人，凤歌笑孔丘。”起句即用典，开宗明义表达胸襟：我本来就象楚狂接舆，高唱凤歌嘲笑孔丘。孔子曾去楚国，游说楚王。接舆在他车旁唱道：“凤兮凤兮，何德之衰？往者不可谏，来者犹可追！已而！已而！今之从政者殆而！”（《论语·微子》）嘲笑孔子迷于做官。李白以楚狂自比，表示了对政治前途的失望，暗示出要象楚狂那样游诸名山去过隐居生活。“凤歌”一典，用语精警，内容深刻，饱含身世之感。接着诗人写他离开武昌到庐山：“手持绿玉杖，朝别黄鹤楼。五岳寻仙不辞远，一生好入名山游”。诗人以充满神话传说的色彩表述他的行程：拿着仙人所用的嵌有绿玉的手杖，于晨曦中离开黄鹤楼。为什么到庐山来呢？是因为“好入名山游。”后两句诗，既可说是李白一生游踪的形象写照，同时也透露出诗人寻仙访道的隐逸之心。\n\n　　以上是第一段，可谓序曲。然后转入第二段，诗人以浓墨重彩，正面描绘庐山和长江的雄奇风光。先写山景鸟瞰：“庐山秀出南斗旁，屏风九叠云锦张，影落明湖青黛光。”古人认为天上星宿指配地上州域，庐山一带正是南斗的分野。屏风九叠，指庐山五老峰东北的九叠云屏。三句意谓：庐山秀丽挺拔，高耸入云；树木青翠，山花烂熳，九叠云屏像锦绣云霞般展开；湖光山影，相互映照，烘托得分外明媚绮丽。以上是粗绘，写出庐山的雄奇瑰丽；下面，则是细描：“金阙前开二峰长，银河倒挂三石梁。香炉瀑布遥相望，回崖沓嶂凌苍苍。”金阙、三石梁、香炉、瀑布，都是庐山绝景。这四句是从仰视的角度来描写：金阙岩前矗立着两座高峰，三石梁瀑布有如银河倒挂，飞泻而下，和香炉峰瀑布遥遥相对，那里峻崖环绕，峰峦重叠，上凌苍天。接着，笔姿忽又宕起，总摄全景：“翠影红霞映朝日，鸟飞不到吴天长。”旭日初升，满天红霞与苍翠山色相辉映；山势峻高，连鸟也飞不到；站在峰顶东望吴天，真是寥廓无际。诗人用笔错综变化，迂回别致，层层写来，把山的瑰玮和秀丽，写得淋漓尽致，引人入胜。\n\n　　然后，诗人登高远眺，以如椽大笔，彩绘长江雄伟气势：“登高壮观天地间，大江茫茫去不还。黄云万里动风色，白波九道流雪山。”九道，古谓长江流至浔阳分为九条支流。雪山，形容白波汹涌，堆叠如山。这几句意谓：登临庐山高峰，放眼纵观，只见长江浩浩荡荡，直泻东海，一去不返；万里黄云飘浮，天色瞬息变幻；茫茫九派，白波汹涌奔流，浪高如雪山。诗人豪情满怀，笔墨酣畅，将长江景色写得境界高远，气象万千。何等雄伟，何等壮美！大自然之美激发了大诗人的无限诗情：“好为庐山谣，兴因庐山发。闲窥石镜清我心，谢公行外苍苔没。”石镜，传说在庐山东面有一圆石悬岩，明净能照人形。谢公，南朝宋谢灵运，尝入彭蠡湖口，登庐山，有“攀崖照石镜”诗句（《谢康乐集·入彭蠡湖口》）。李白经过永王璘事件的挫折后，重登庐山，不禁感慨万千。这四句意思是：爱作庐山歌谣，诗兴因庐山而激发。从容自得地照照石镜，心情为之清爽，谢灵运走过的地方，如今已为青苔所覆盖。人生无常，盛事难再。李白不禁油然产生寻仙访道思想，希望超脱现实，以求解决内心的矛盾。\n\n　　“早服还丹无世情，琴心三叠道初成。”还丹，道家所谓服后能“白日升天”的仙丹。琴心三叠，指道家修炼的功夫很深，达到心和神悦的境界。这两句表明诗人想象着自己有一天能早服仙丹，修炼升仙，以摆脱世俗之情，到那虚幻的神仙世界：“遥见仙人彩云里，手把芙蓉朝玉京。”玉京，道教谓元始天尊居处。诗人仿佛远远望见神仙在彩云里，手拿着莲花飞向玉京。诗人多么向往这样自由自在的世界：“先期汗漫九垓上，愿接卢敖游太清。”《淮南子·道应训》载，卢敖游北海，遇见一怪仙，想同他做朋友而同游，怪仙笑道：“吾与汗漫期于九垓之外，吾不可以久驻。”“遂入云中。”汗漫，意谓不可知，这里比喻神。九垓，九天。太清，最高的天空。李白在这诗里反用其意，以怪仙自比，卢敖借指卢虚舟，邀卢共作神仙之游。两句意谓：我李白已预先和不可知之神在九天之外约会，并愿接待卢敖共游仙境。诗人浮想联翩，仿佛随仙人飘飘然凌空而去。全诗戛然而止，余韵悠然。\n\n　　此诗思想内容比较复杂，既有对儒家孔子的嘲弄，也有对道家的崇信；一面希望摆脱世情，追求神仙生活，一面又留恋现实，热爱人间风物。诗的感情豪迈开朗，磅礴着一种震撼山岳的气概。想象丰富，境界开阔，给人以雄奇的美感享受。诗的韵律随诗情变化而显得跌宕多姿。开头一段抒怀述志，用尤侯韵，自由舒展，音调平稳徐缓。第二段描写庐山风景，转唐阳韵，音韵较前提高，昂扬而圆润。写长江壮景则又换删山韵，音响慷慨高亢。随后，调子陡然降低，变为入声月没韵，表达归隐求仙的闲情逸致，声音柔弱急促，和前面的高昂调子恰好构成鲜明的对比，极富抑扬顿挫之妙。最后一段表现美丽的神仙世界，转换庚清韵，音调又升高，悠长而舒畅，余音袅袅，令人神往。', poem_tags = '唐诗三百首,写景,山水,归隐,猖狂' WHERE poem_title = '庐山谣寄卢侍御虚舟' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '庞葱要陪太子到邯郸去做人质，庞葱对魏王说：“现在，如果有一个人说大街上有老虎，您相信吗”“魏王说：“不相信。”庞葱说：“如果是两个人说呢？”魏王说：“那我就要疑惑了。”庞葱又说：“如果增加到三个人呢，大王相信吗？”魏王说：“我相信了。”庞葱说：“大街上不会有老虎那是很清楚的，但是三个人说有老虎，就像真有老虎了。如今邯郸离大梁，比我们到街市远得多，而毁谤我的人超过了三个。希望您能明察秋毫。”魏王说：“我知道该怎么办。”于是庞葱告辞而去，而毁谤他的话很快传到魏王那里。后来太子结束了人质的生活，庞葱果真不能再见魏王了。', poem_notes = '庞恭：魏国大臣。\n质：人质，这里用作动词，指作人质。谓将人作为抵押品，这是战国时代国与国之间的外交惯例。\n邯郸：赵国的都城，在今河北省邯郸县西南十里。\n市：集市\n之：代词，这里指“市有虎”这件事。\n信：相信。\n夫：语气词，用于句首，表示下文要发表议论，现代汉语没有与此相应的词语。\n明：明白，清楚。\n然：可是。\n去：距离。\n议臣者：议论我的人。议：议论。这里是非议，说人坏话。臣：庞葱（恭）自称。者：……的人。\n愿：希望。\n察：观察，仔细看，明察。\n反：通“返”，返回。\n得：能够（得到）。\n见：拜见、谒见。这里指召见。\n竟：最终\n\n通假字\n原句：庞恭从邯郸反\n“反”通“返” 意思为返回', poem_appreciation = '战国时代，互相攻伐，为了使大家真正能遵守信约，国与国之间通常都将太子交给对方作为人质。“战国策“：“魏策“有这样一段记载：\n\n　　魏国大臣庞恭，将要陪魏太子到赵国去作人质，临行前对魏王说：“现在有一个人来说街市上出现了老虎，大王相信吗？“\n\n　　魏王道：“我不相信。“\n\n　　庞恭说：“如果有第二个人说街市上出现了老虎，大王相信吗？“\n\n　　魏王道：“我开始质疑。“\n\n　　庞恭又说：“如果有第三个人说街市上出现了老虎，大王相信吗？“\n\n　　魏王道：“我当然会相信。“\n\n　　庞恭就说：“街市上不会有老虎，这是很明显的事，可是经过三个人一说，好像真的有了老虎了。现在赵国国都邯郸离魏国国都大梁，比这里的街市远了许多，议论我的人又不止三个。希望大王明察才好。“\n\n　　魏王道：“一切我自己知道。“\n\n　　太子结束了做人质，庞恭再也没有见到魏王。\n\n　　街市是人口集中的地方，当然不会有老虎。说街市上有虎，显然是造谣、欺骗，但许多人这样说了，如果不是从事物真相上看问题，也往往会信以为真的。\n\n　　这故事本来是讽刺魏惠王无知的，但后世人引申这故事成为“三人成虎“这句成语，乃是借来比喻有时谣言可以掩盖真相的意思。例如：判断一件事情的真伪，必须经过细心考察和思考，不能道听途说。否则“三人成虎“，有时会误把谣言当成真实的。', poem_tags = '小学文言文,寓言,故事,哲理' WHERE poem_title = '三人成虎' AND poem_author = '刘向';
UPDATE edu_poem SET poem_translation = '谁说闲情逸致被忘记了太久？每到新春来到，我的惆怅心绪一如故旧。为了消除这种闲愁，我天天在花前痛饮，让自己放任大醉，不惜身体消瘦，对着镜子自己容颜已改。\n河边上芳草萋萋，河岸上柳树成荫。见到如此美景，我忧伤地暗自思量，为何年年都会新添忧愁？我独立在小桥的桥头，清风吹拂着衣袖。只有远处那一排排树木在暗淡的月光下影影绰绰，与我相伴。', poem_notes = '清王鹏运《半塘丁稿·鹜翁集》云：“冯正中《鹤踏枝》十四首，郁伊倘况，义兼比兴。”调名即《蝶恋花》。\n谁道句：近人梁启超云：“稼轩《摸鱼儿》起处从此脱胎。文前有文，如黄河液流，莫穷其源。”（《阳春集笺》引）。闲情：即闲愁、春愁。\n病酒：饮酒过量引起身体不适。\n敢辞：不避、不怕。朱颜，青春红润的面色。\n朱颜：这里指红润的脸色。\n青芜：青草。\n平林：平原上的树林。李白《菩萨蛮》：“平林澳漠烟如织。”\n新月：阴历每月初出的弯形月亮。', poem_appreciation = '这是一首表达孤寂惆怅的言情词。全词所写的乃是心中一种常存永在的惆怅、忧愁，而且充满了独自一人承担的孤寂、凄冷之感，不仅传达了一种感情的意境，而且表现出强烈而鲜明的个性，意蕴深远，感发幽微。\n\n　　上阕开门见山，首句用反问的句式把这种既欲抛弃却又不得忘记的“闲情”提了出来，整个上片始终紧扣首句提出的复杂矛盾的心情回环反复，表现了作者内心感情的痛苦撕咬。\n\n　　“谁道闲情抛掷久。”虽然仅只七个字，然而却写得千回百转，表现了在感情方面欲抛不得的一种盘旋郁结的挣扎的痛苦。而对此种感情之所由来，却又并没有明白指说，而只用了“闲情”两个字。这种莫知其所自来的“闲情”才是最苦的，而这种无端的“闲情”对于某些多情善感的诗人而言，却正是如同山之有崖、木之有枝一样的与生俱来而无法摆脱的。词人在此一句词的开端先用了“谁道”两个字，“谁道”者，原以为可以做到，谁知竟未能做到，故以反问之语气出之，有此二字，于是下面的“闲情抛弃久”五字所表现的挣扎努力就全属于徒然落空了。\n\n　　“每到春来，惆怅还依旧。”上面着一“每”字，下面着一“还”，字，再加上后面的“依旧”两个字，已足可见此“惆怅”之永在长存。而“每到春来”者，春季乃万物萌生之时，正是生命与感情觉醒的季节，词人于春心觉醒之时，所写的却并非如一般人之属于现实的相思离别之情，而只是含蓄地用了“惆怅”二字。“惆怅”者，是内心恍如有所失落又恍如有所追寻的一种迷惘的情意，不像相思离别之拘于某人某事，而是较之相思离别更为寂寞、更为无奈的一种情绪。\n\n　　“日日花前常病酒，敢辞镜里朱颜瘦。”既然有此无奈的惆怅，而且经过抛弃的挣扎努力之后而依然永在长存，于是下面两句冯氏遂径以殉身无悔的口气，说出了“日日花前常病酒，不辞镜里朱颜瘦”两句决心一意承担负荷的话来。上面更着以“日日”两字，更可见出此一份惆怅之情之对花难遣，故唯有“日日”饮酒而已。曰“日日”，盖弥见其除饮酒外之无以度日也。至于下句之“镜里朱颜瘦”，则正是“日日病酒”之生活的必然结果。曰“镜里”，自有一份反省惊心之意，而上面却依然用了“不辞”二字，昔《离骚》有句云“虽九死其犹未悔”，“不辞”二字所表现的，就正是一种虽殉身而无悔的情意。\n\n　　下阕进一步抒发这种与时常新的闲情愁绪。词人把这种迷惘与困惑又直接以疑问的形式再次鲜明突出地揭诸笔端，可谓真率之极；而在“河畔青芜堤上柳”的意象之中，隐含着绵远纤柔、无穷无尽的情意与思绪，又可谓幽微之至。\n\n　　“河畔青芜堤上柳。”下半阕承以“河畔青芜堤上柳”一句为开端，在这首词中实在只有这七个字是完全写景的句子，但此七字却又并不是真正只写景物的句子，不过只是以景物为感情之衬托而已。所以虽写春来之景色，却并不写繁枝嫩蕊的万紫千红，只说“青芜”，只说“柳”。“芜”者，丛茂之草也，“芜”的青青草色既然遍接天涯，“柳”的缕缕柔条，更是万丝飘拂。簇这种绿遍天涯的无穷草色，这种’随风飘拂的无尽柔条，它们所唤起的，或者所象喻的，该是一种何等绵远纤柔的情意。而这种草色又不自今日方始，年年河畔草青，年年堤边柳绿，则此一份绵远纤柔的情意，也就年年与之无尽无穷。\n\n　　“为问新愁，何事年年有。”所以下面接下去就说了“为问新愁，何事年年有”二句，正式从年年的芜青柳绿，写到“年年有”的“新愁”。虽是“年年有”的“愁”，却又说是“新”，一则此词开端已曾说过“闲情抛弃久”的话，经过一段“抛弃”的挣扎，而重新又复苏起来的“愁”，所以说“新”；再则此愁虽一宋词鉴赏辞典一旧，而其令人惆怅的感受，则敏锐深切岁岁常新，故曰“新”。上面用了“为问”二字，下面又用了“何事”二字，造成了一种强烈的疑问语气，从其尝试抛弃之徒劳的挣扎，到问其新愁之何以年年常有，有如此之挣扎与反省而依然不能自解。在此强烈的追问之后，词人却忽然荡开笔墨，更不作任何回答，而只写下了“独立小桥风满袖，平林新月人归后”两句身外的景物情事，仔细玩味，这十四个字却实在是把惆怅之情写得极深。\n\n　　“独立小桥风满袖，平林新月人归后。”试观其“独立”二字，已是寂寞可想，再观其“风满袖”三字，更是凄寒可知，又用了“小桥”二字，则其立身之地的孤伶无所荫蔽亦复如在眼前，而且“风满袖”一句之“满”字，写风寒袭人，也写得极饱满有力。在如此寂寞孤伶无所荫蔽的凄寒之侵袭下，其心情之寂寞凄苦已可想见，何况又加上了下面的“平林新月人归后”七个字。“平林新月”，则林梢月上，夜色渐起，“人归后”，则路断行人，已是寂寥人定之后了。从前面所写的“河畔青芜”之颜色鲜明来看，应该乃是白日之景象，而此一句则直写到月升人定，则诗人承受着满袖风寒在小桥上独立的时间之长久也可以想见了。如果不是内心中有一份难以排解的情绪，有谁会在寒风冷露的小桥上直立到中宵呢？', poem_tags = '宋词三百首,婉约,春愁,感叹,人生' WHERE poem_title = '鹊踏枝·谁道闲情抛掷久' AND poem_author = '冯延巳';
UPDATE edu_poem SET poem_tags = '赏花,抒怀' WHERE poem_title = '海棠春·已未清明对海棠有赋' AND poem_author = '吴潜';
UPDATE edu_poem SET poem_translation = '往昔曾经戏言我们身后的安排，如今都按你所说的展现在眼前。\n你穿过的衣裳已经快施舍完了，你的针线盒我珍存着不忍打开。\n因怀念你我对婢仆也格外恋爱，多次梦到你我便为你焚纸烧钱。\n谁不知夫妻永诀人人都会伤怀，想起许多往事令人极度地伤悲。', poem_notes = '戏言：开玩笑的话。身后意：关于死后的设想。\n行看尽：眼看快要完了。\n怜：怜爱，痛惜。\n诚知：确实知道。', poem_appreciation = '赏析 　　这首诗主要写妻子死后的“百事哀”。诗人写了在日常生活中引起哀思的几件事。人已仙逝，而遗物犹在。为了避免见物思人，便将妻子穿过的衣裳施舍出去；将妻子做过的针线活仍然原封不动地保存起来，不忍打开。诗人想用这种消极的办法封存起对往事的记忆，而这种做法本身恰好证明他无法摆脱对妻子的思念。还有，每当看到妻子身边的婢仆，也引起自己的哀思，因而对婢仆也平添一种哀怜的感情。白天事事触景伤情，夜晚梦魂飞越冥界相寻。梦中送钱，似乎荒唐，却是一片感人的痴情。苦了一辈子的妻子去世了，如今生活在富贵中的丈夫不忘旧日恩爱，除了“营奠复营斋”以外，已经不能为妻子做些什么了。于是积想成梦，出现送钱给妻子的梦境。末两句，从“诚知此恨人人有”的泛说，落到“贫贱夫妻百事哀”的特指上。夫妻死别，固然是人所不免的，但对于同贫贱共患难的夫妻来说，一旦永诀，是更为悲哀的。末句从上一句泛说推进一层，着力写出自身丧偶不同于一般的悲痛感情。 ▲', poem_tags = '唐诗三百首,悼亡,追忆,思念' WHERE poem_title = '遣悲怀三首·其二' AND poem_author = '元稹';
UPDATE edu_poem SET poem_translation = '的妆容！却不得人欣赏，竟然和画像争论！这幅仪态妆容！在后宫中又能排到第几名 ！\n忧愁的看着水中自己纤瘦的身影，你应该怜惜我对于你的爱。', poem_tags = '女子,闺怨' WHERE poem_title = '怨' AND poem_author = '冯小青';
UPDATE edu_poem SET poem_translation = '富饶的水域江山都已绘入战图，百姓想要打柴割草度日而不得。\n请你别再提什么封侯的事情了，一将功成要牺牲多少士卒生命！\n\n传说一旦开战连众神灵都发愁，两岸军队连年混战一直不停休。\n谁还说沧江总是太平没有祸事，近来江水混着鲜血争先向东流。', poem_notes = '己亥：为唐僖宗乾符六年（879年）的干支。\n泽国：泛指江南各地，因湖泽星罗棋布，故称。\n樵苏：一作“樵渔”。\n传闻：一作“波间”。', poem_appreciation = '这组诗载于《全唐诗》卷七百一十七。下面是四川大学文学与新闻学院教授、四川诗词学会理事周啸天先生对组诗第一首的赏析。\n\n　　“己亥岁”这个醒目的诗题，就点明了诗中所写的是活生生的社会政治现实。\n\n　　安史之乱后，战争先在河北，后来蔓延入中原。到唐末又发生大规模农民起义，唐王朝进行穷凶极恶的镇压，大江以南也都成了战场。这就是所谓“泽国江山入战图”。诗句不直说战乱殃及江汉流域（泽国），而只说这一片河山都已绘入战图，表达委婉曲折，让读者通过一幅“战图”，想象到兵荒马乱、铁和血的现实，这是诗人运用形象思维的一个成功例子。\n\n　　随战乱而来的是生灵涂炭。打柴为“樵”，割草为“苏”。樵苏生计本来艰辛，无乐可言。然而，“宁为太平犬，勿为乱世民”，在流离失所、挣扎于生死线上的“生民”心目中，能平平安安打柴割草以度日，也就快乐了。只可惜这种樵苏之乐，此时亦不可复得。用“乐”字反衬“生民”的不堪其苦，耐人寻味。\n\n　　古代战争以取首级之数计功，战争造成了残酷的杀戮，人民的大量死亡。这是血淋淋的现实。诗的前两句虽然笔调轻描淡写，字里行间却有斑斑血泪。这就自然逼出后两句沉痛的呼告。\n\n　　“凭君莫话封侯事，一将功成万骨枯。”这里“封侯”之事，是有现实针对性的：公元879年（乾符六年，即“己亥岁”）镇海节度使高骈就以在淮南镇压黄巢起义军的“功绩”，受到封赏，无非“功在杀人多”而已。令人闻之发指，言之齿冷。无怪诗人闭目摇手道“凭君莫话封侯事”了。一个“凭”字，意在“请”与“求”之间，语调比言“请”更软，意谓：行行好吧，可别提封侯的话啦。词苦声酸，全由此一字推敲得来。\n\n　　“一将功成万骨枯”，更是一篇之警策。它词约而义丰。与“可怜白骨攒孤冢，尽为将军觅战功”（张蠙《吊万人冢》）之句相比，字数减半而意味倍添。它不仅同样含有“将军夸宝剑，功在杀人多”（刘商《行营即事》）的现实内容；还更多一层“士卒涂草莽，将军空尔为”（李白《战城南》）的意味，即言将军封侯是用士卒牺牲的高昂代价换取的。其次，一句之中运用了强烈对比手法：“一”与“万”、“荣”与“枯”的对照，令人触目惊心。“骨”字极形象骇目。这里的对比手法和“骨”字的运用，都很接近“朱门酒肉臭，路有冻死骨”的惊人之句。它们从不同侧面揭示了封建社会历史的本质，具有很强的典型性。前三句只用意三分，词气委婉，而此句十分刻意，掷地有声，相形之下更觉字字千钧。', poem_tags = '边塞,战争,忧国忧民,组诗' WHERE poem_title = '己亥岁二首·僖宗广明元年' AND poem_author = '曹松';
UPDATE edu_poem SET poem_translation = '恨意千万如丝如缕，飘散到了遥远的天边。山间的明月不知道我的心事。绿水清风中，鲜花独自摇落。花儿零落中，不知不觉的明月早已经斜入碧云外。', poem_notes = '①恨：离恨。\n②天涯： 天边。指思念的人在遥远的地方。\n③摇曳：犹言摇荡、动荡。', poem_appreciation = '这首词以意境取胜，通过描写思妇在孤单的月光下独自思念的情景，表现了其内心的悲戚和哀伤。\n\n　　“千万恨，恨极在天涯。”首句直出“恨”字，“千万”直贯下句“极”字，并点出原因在于所恨之人远“在天涯”，满腔怨恨喷薄而出。说“恨”而有“千万”，足见恨之多与无穷，而且显得反复、零乱，大有不胜枚举之概。虽有千头万绪之恨，但恨到极点的事只有一桩，即远在天涯的那个人久不归来。这是对全词的主旨作正面描写。\n\n　　“山月不知心里事，水风空落眼前花。”三、四两句，初读起来很是平淡，仔细玩味却觉得是妙手天成。这两句是从侧面阐述其“恨”之深。女主人既有千万恨，其“心里”有“事”是理所当然的了，更使她难过的却在于“有恨无人知”。“恨”是一种无形的心理情绪，是难以把握和捉摸的，而词人却善于借景将它烘托出来：像风掠过水面时荡起的阵阵涟漪，像花儿随风落去时的缤纷缭乱，像悠悠白云在天空摇曳时的飘忽迷离，这样一来，抽象的“恨”就变得形象、可感了，使人们能够清晰地体验到它的纷乱、动荡的状态，也增强了词的审美价值。\n\n　　“摇曳碧云斜。”夜对山月，昼惜落花，在昼夜交替的黄昏，摇曳是程度不怎么明显的动荡，是轻轻移斜了角度的晃动。此句看似单纯写景，却状出了凝望暮色与碧云的女主人的百无聊赖之态，说明一天的光阴又在不知不觉中消逝了，不着“恨”字而“恨极”之意已和盘托出。', poem_tags = '婉约,写景,妇女,怀人' WHERE poem_title = '梦江南·千万恨' AND poem_author = '温庭筠';
UPDATE edu_poem SET poem_translation = '七弦琴奏出清凉的曲调悠扬起伏，细细倾听就像那滚滚的松涛声。\n我虽然很喜爱这首古时的曲调，但在今天人们大多已不去弹奏了。', poem_notes = '泠（líng）泠：形容清凉、清淡，也形容声音清越。丝：一作“弦”。\n松风：以风入松林暗示琴声凄凉。琴曲中有《风入松》的调名。\n古调：古时的曲调。', poem_appreciation = '此诗题一作“弹琴”，《刘随州集》与《全唐诗》均为“听弹琴”。从诗中“静听”二字细味，题目以有“听”字为妥。\n\n　　琴是中国古代传统民族乐器，由七条弦组成，所以首句以“七弦”作琴的代称，意象也更具体。“泠泠”形容琴声的清越，逗起“松风寒”三字。“松风寒”以风入松林暗示琴声的凄清，极为形象，引导读者进入音乐的境界。“静听”二字描摹出听琴者入神的情态，可见琴声的超妙。高雅平和的琴声，常能唤起听者水流石上、风来松下的幽清肃穆之感。而琴曲中又有《风入松》的调名，一语双关，用意甚妙。\n\n　　如果说前两句是描写音乐的境界，后两句则是议论性抒情，牵涉到当时音乐变革的背景。汉魏六朝南方清乐尚用琴瑟。而到唐代，音乐发生变革，“燕乐”成为一代新声，乐器则以西域传入的琵琶为主。“琵琶起舞换新声”的同时，公众的欣赏趣味也变了。受人欢迎的是能表达世俗欢快心声的新乐。穆如松风的琴声虽美，毕竟成了“古调”，已经没有几个人能怀着高雅情致来欣赏，言下便流露出曲高和寡的孤独感。“虽”字转折，从对琴声的赞美进入对时尚的感慨。“今人多不弹”的“多”字，更反衬出琴客知音者的稀少。有人以此二句谓今人好趋时尚不弹古调，意在表现作者的不合时宜，是很对的。刘长卿清才冠世，一生两遭迁斥，有一肚皮不合时宜和一种与流俗落落寡合的情调。他的集中有《幽琴》（《杂咏八首上礼部李侍郎》之一）诗曰：“月色满轩白，琴声宜夜阑。飗飗青丝上，静听松风寒。古调虽自爱，今人多不弹。向君投此曲，所贵知音难。”其中四句就是这首听琴绝句。“所贵知音难”也正是诗的题旨之所在。“作诗必此诗，定知非诗人”，诗咏听琴，只不过借此寄托一种孤芳自赏的情操罢了。', poem_tags = '唐诗三百首,音乐,抒情' WHERE poem_title = '听弹琴' AND poem_author = '刘长卿';
UPDATE edu_poem SET poem_translation = '雨前初次见到新开花朵的花蕊，雨后连叶子底下也不见一朵花。\n蜜蜂和蝴蝶纷纷地飞过了墙去，让人怀疑迷人的春色尽在邻家。', poem_notes = '蕊（ruǐ）：花朵开放后中间露出的柱头花丝等，分雌蕊、雄蕊。\n叶底：绿叶中间。底，底部。\n蜂蝶：蜜蜂和蝴蝶。纷纷：接连不断。\n疑：怀疑。春色：春天的景色。邻家：邻居的家。', poem_appreciation = '这是一首即兴诗，写雨后漫步花园所见的衰败景象。诗中摄取的景物很简单，也很平常，但平中见奇，饶有诗趣。\n\n　　“雨前初见花间蕊，雨后全无叶底花。”诗的前两句扣住象征春色的“花”字来写春景，以“雨前”所见和“雨后”情景相对比、映衬，表现了作者面对满园落红残春油然而生的叹惜之情。“初见”“全无”是精准的概括，令人感受到雨前、雨后截然不同的两种景致。雨前，春天刚刚降临，花才吐出骨朵儿，尚未开放；而雨后，花事已了，落红满径，枝条是上只剩下满树绿叶了，说明这场雨下得很大很久。好端端的百花争艳的美好春色，却被这一场春雨给闹杀了。诗人望着花落春残的小园之景，是非常扫兴而生感触的。\n\n　　扫兴的不光是诗人，还有那蜜蜂和蝴蝶。诗的下两句由花写到蜂蝶。“蜂蝶纷纷过墙去，却疑春色在邻家。”被苦雨久困的蜂蝶，好不容易盼到大好的春晴佳期，它们怀着和诗人同样高兴的心情，翩翩飞到小园中来，满以为可以在花丛中饱餐春色，不料扑了空，小园无花空有叶；它们也像诗人一样大失所望，懊丧地离开，纷纷飞过院墙。花落了，蜂蝶也纷纷离开了，小园显得更加冷清寥落，诗人的心也就更是悲苦怅惘。望着“纷纷过墙去”的蜂蝶，满怀着惜春之情的诗人，刹那间产生出一种大胆而奇妙的联想：“却疑春色在邻家”。院墙那边是邻家，诗人想得似乎真实有据；但一墙之隔的邻家小园，自然不会得天独厚，独享春色，诗人想得却是天真烂漫；毕竟墙高遮住视线，不能十分肯定，故诗人只说“疑”。“疑”字极有分寸，体现了一个度，格外增加了真实感。这两句诗，作者把原无理性的蜂蝶赋予“人”的智慧，不仅把蜂蝶追逐春色的神态、心理写得活灵活现，妙趣横生，而且描写似乎“阳春”真的“有脚”，她不住自家小园，偏偏跑到邻家，她是十分调皮、非常会捉弄人的，这就更把“春色”写活了。同时，作者的“惜春之情”也被表现得淋漓尽致，透露出诗人希望春色没有远去的心情。作者内心伤春惜春的心情和眼前自然景象巧妙接合，既赋予蜜蜂蝴蝶以人格精神，又暗暗流露作者的内心感触，两者神态、心理写得活灵活现。其中，“却疑春色在邻家”，可谓神来之笔，造语奇峰突起，而又浑然天成，令人顿时耳目一新。这一句是全篇精髓，起了点铁成金、化腐朽为神奇的作用，经它点化，小园、蜂蝶、春色，一齐焕发出异样神采，妙趣横生。古人谓“诗贵活句”（吴乔《围炉诗话》），就是指这种最能表达诗人独特感受的新鲜生动的诗句。\n\n　　这首七言绝句，精巧地选择雨晴后的景物，来进行生动的描绘，表达了作者的惜春之情。', poem_tags = '惜春,春天,写雨,写景' WHERE poem_title = '雨晴' AND poem_author = '王驾';
UPDATE edu_poem SET poem_tags = '春天,写景,抒情' WHERE poem_title = '早春呈水部张十八员外二首' AND poem_author = '韩愈';
UPDATE edu_poem SET poem_translation = '在花园里是容易看出时节的变化的，其中最使人惊异、最能标志时节变化的就是梅花。\n梅花不怕霜雪、不畏风寒，在零霜下雪的时候，它就在路边开放了。\n梅花的枝叶和花朵开遍扬州。\n梅花盛开的时候可以使被遗弃者见之有感而落泪，也可以使钟情的人触景兴怀而勃发。\n梅花大概也知道自己飘落得早，所以赶在正月就开起花来了。', poem_notes = '兔园：本是汉梁孝王的园名，这里借指扬州的林园。\n标：标志。\n物序：时序，时节变换。\n拟：比，对着。\n却月观：扬州的台观名。\n凌风台：扬州的台观名。\n长门：汉宫名。汉武帝曾遗弃陈皇后于长门宫，司马相如为她写过一篇《长门赋》。\n临邛：汉县名，司马相如曾在临邛饮酒，结识了卓文君。\n上春：即孟春正月。', poem_tags = '古诗三百首,咏物,梅花,言志' WHERE poem_title = '咏早梅 / 扬州法曹梅花盛开' AND poem_author = '何逊';
UPDATE edu_poem SET poem_translation = '手执酒杯细听那《水调歌》声声，午间醉酒虽醒愁还没有醒。送走了春天，春天何时再回来？临近傍晚照镜，感伤逝去的年景，如烟往事在日后空自让人沉吟。\n鸳鸯于黄昏后在池边并眠，花枝在月光下舞弄自己的倩影。一重重帘幕密密地遮住灯光，风儿还没有停，人声已安静，明日落花定然铺满园中小径。', poem_notes = '天仙子，唐教坊舞曲，后用为词牌。段安节《乐府杂录》：“龟兹部，《万斯年》曲，是朱崖李太尉（德裕）进。此曲名即《天仙子》是也。”《金奁集》入“歇指调”，所收为韦庄作五首，皆平韵或仄韵转平韵体。《花间集》收皇甫松二首，皆仄韵单调小令，三十四字，五仄韵。《张子野词》兼入“中吕”、“仙吕”两调，并重叠一片为之。\n嘉乐小倅：嘉乐，秀州别称，治所在今浙江省嘉兴市。倅，副职，时张先任秀州通判。不赴府会：未去官府上班。\n水调：曲调名。唐杜牧《扬州》诗之一：“谁家唱《水调》，明月满扬州。”自注：“炀帝凿汴渠成，自造《水调》。”\n流景：像水一样的年华，逝去的光阴。景，日光。唐武平一《妾薄命》诗：“流景一何速，年华不可追。”\n后期：以后的约会。记省：记志省识。记：思念。省（xǐng）：省悟。\n并禽：成对的鸟儿。这里指鸳鸯。瞑：天黑，暮色笼罩。\n弄影：谓物动使影子也随着摇晃或移动。弄，摆弄。\n落红：落花。唐戴叔伦《相思曲》：“落红乱逐东流水，一点芳心为君死。”', poem_appreciation = '这是北宋词中名篇之一，也是张先享誉之作。而其所以得名，则由于词中有“云破月来花弄影”之句。据陈师道《后山诗话》及胡仔《苕溪渔隐丛话》所引各家评论，都说张先所创的词中以三句带有“影”字的佳句为世所称，人们誉之为“张三影”。\n\n　　这首词下有注云：“时为嘉禾小倅，以病眠，不赴府会。”说明词人感到疲怠，百无聊赖，对酣歌妙舞的府会不敢兴趣，这首词写的就是这种心情。\n\n　　作者未尝不想借听歌饮酒来解愁。但在这首词里，作者却写他在家里品着酒听了几句曲子之后，不仅没有遣愁，反而心里更烦了。于是在吃了几杯闷酒之后便昏昏睡去。一觉醒来，日已过午，醉意虽消，愁却未曾稍减。冯延巳《鹊踏枝》：“昨夜笙歌容易散，酒醒添得愁无限。”这同样是写“欢乐极兮哀情多，少壮几时兮奈老何？”的闲愁。只不过冯是在酒阑人散，舞休歌罢之后写第二天的萧索情怀，而张先则一想到笙歌散尽之后可能愁绪更多，所以根本连宴会也不去参加了。这就逼出了下一句“送春春去几时回”的感叹来。这首词乃是临老伤春之作，但伤春的内容却依然是年轻时风流缱绻之事。理由是：一、从“往事后期空记省”一句微逗出个中消息；二、下片特意点明“沙上并禽池上暝”，意思说鸳鸯一类水鸟，天一黑就双栖并宿，燕婉亲昵，如有情人之终成眷属。而自己则是形影相吊，索居块处。因此，“送春春去几时回”的上下两个“春”字，也就有了不尽相同的涵义。上一个“春”指季节，指大好春光；而下面的“春去”，不仅指年华的易逝，还蕴涵着对青春时期风流韵事的追忆和惋惜。这就与下文“往事后期空记省”一句紧密联系起来。作者所“记省”的“往事”并非一般的嗟叹流光的易逝，或伤人事之无凭，而是有其具体内容的。只是作者说得十分含蓄，在意境上留下很多余地让读者凭想象去补充。\n\n　　“临晚镜，伤流景”。杜牧《代吴兴妓春初寄薛军事》诗有句云：“自悲临晓镜，谁与惜流年？”张反用小杜诗句，以“晚”对“晓”，主要在于写实。小杜是写女子晨起梳妆，感叹年华易逝，用“晓”字；而张先词则于午醉之后，又倦卧半晌，此时已近黄昏，总躺在那儿仍不能消解忧愁，便起来“临晚镜”了。这个“晚”既是天晚之晚，当然也隐指晚年之晚，这同上文两个“春”字各具不同涵义是一样的，只是此处仅用了一个“晚”字，而把“晚年”的一层意思通过“伤流景”三字给补充出来了。\n\n　　“往事后期空记省”句中的“后期”一本作“悠悠”。从词意含蓄看，“悠悠”空灵而“后期”质实，前者自有其传神入妙之处。但“后期”二字虽嫌朴拙，却与上文“愁”、“伤”等词语绾合得更紧密些。“后期”有两层意思。一层说往事过了时，这就不得不感慨系之，故用了个“空”字；另一层意思则是指失去了机会或错过了机缘。所谓“往事”，可以是甜蜜幸福的，也可以是辛酸哀怨的。前者在多年以后会引起人无限怅惘之情，后者则使人一想起来就加重思想负担。这件“往事”，明明是可以成为好事的，却由于自己错过机缘，把一个预先定妥的期约给耽误了（即所谓后期），这就使自己追悔莫及，正如李商隐说的“此情可待成追忆，只是当时已惘然”。随着时光的流逝，往事的印象并未因之淡忘，只能向自己的“记省”中去寻求。但寻求到了，也并不能得到安慰，反而更增添了烦恼。这就是自己为什么连把酒听歌也不能消愁，从而嗟老伤春，即使府中有盛大的宴会也不想去参加的原因了。可是作者却偏把这个原因放在上片的末尾用反缴的手法写出，乍看起来竟像是事情的结果，这就把一腔自怨自艾、自甘孤寂的心情写得格外惆怅动人，表面上却又似含而不露，真是极尽婉约之能事了。\n\n　　上片写作者的思想活动，是静态；下片写词人即景生情，是动态。静态得平淡之趣，而动态有空灵之美。作者未参加府会，便在暮色中将临时到小园中闲步，借以排遣从午前一直滞留在心头的愁闷。天很快就暗下来了，水禽已并眠在池边沙岸上，夜幕逐渐笼罩着大地。这个晚上原应有月的，作者的初衷未尝不想趁月色以赏夜景，才步入园中的。不料云满夜空，并无月色，既然天已昏黑那就回去吧。恰在这时，意外的景色变化在眼前出现了。风起了，霎那间吹开了云层，月光透露出来了，而花被风所吹动，也竟自在月光临照下婆娑弄影。这就给作者孤寂的情怀注入了暂时的欣慰。此句之所以传诵千古，不仅在于修辞炼句的功夫，主要还在于词人把经过整天的忧伤苦闷之后，在一天将尽品尝到即将流逝的盎然春意这一曲折复杂的心情，通过生动妩媚的形象给曲曲传绘出来，让读者从而也分享到一点欣悦和无限美感。\n\n　　王国维《人间词话》则就遣词造句评论说：“‘红杏枝头春意闹’，着一“闹”字而境界全出；‘云破月来花弄影’着一‘弄’字而境界全出矣。”这已是权威性的评语。沈祖棻说：“其好处在于‘破’、‘弄’二字，下得极其生动细致。天上，云在流，地下，花影在动：都暗示有风，为以下‘遮灯’、‘满径’埋下伏线。”拈出“破”、“弄”两字而不只谈一“弄”字，确有过人之处，然还要注意到一句诗或词中的某一个字与整个意境的联系。即如王国维所举宋祁的‘红杏枝头春意闹’，如果没有“红”、“春”二词规定了当时当地情景，单凭一个“闹”字是不足以见其“境界全出”的。张先的这句词，没有上面的“云破月来”（特别是“破”与“来”这两个动词），这个“弄”字就肯定不这么突出了。“弄”之主语为“花”，宾语为“影”，特别是那个“影”字，也是不容任意更改的。其关键所在，除沈祖棻谈到的起了风这一层意思外，还有好几方面需要补充说明的。第一，当时所以无月，乃云层厚暗所致。而风之初起，自不可能顿扫沉霾而骤然出现晴空万里，只能把厚暗的云层吹破了一部分，在这罅隙处露出了碧天。但云破出未必正巧是月光所在，而是在过了一会儿之后月光才移到了云开之处。这样，“破”与“来”这两个字就不宜用别的字来代替了。在有月而多云到暮春之夜的特定情境下，由于白天作者并未出而赏花，后来虽到园中，又由于阴云笼罩，暮色迷茫，花的风姿神采也未必能尽情地表现出来。及至天色已暝，群动渐息，作者也意兴阑珊，准备回到室内去了，忽然出人意表，云开天际，大地上顿时呈现皎洁的月光，再加上风的助力，使花在月下一扫不久前的暗淡而使其娇艳丽质一下子摇曳生姿，这自然给作者带来了意外的欣慰。\n\n　　接下去词人写他进入室中，外面的风也更加紧了，大了。作者先写“重重帘幕密遮灯”而后写“风不定”，不是迁就词谱的规定，而是说明作者体验事物十分细致，外面有风而帘幕不施，灯自然就会被吹灭，所以作者进了屋子就赶快拉上帘幕，严密地遮住灯焰。但下文紧接着说“风不定”，是表示风更大了，纵使帘幕密遮而灯焰仍在摇摆，这个“不定”是包括灯焰“不定”的情景在内的。“人初静”一句，也有三层意思。一是说由于夜深人静，愈加显得春夜的风势迅猛；二则联系到题目的“不赴府会”，这里的“人静”很可能是指府中的歌舞场面这时也已经散场了吧；三则结合末句，见出作者惜花（亦即惜春；忆往，甚且包括了怀人）的一片深情。好景无常，刚才还在月下弄影的姹紫嫣红，经过这场无情的春风，恐怕要片片飞落在园中的小径上了。作者这末一句所蕴涵的心情是复杂的：首先是“林花谢了春红，太匆匆”，春天毕竟过去了；复次，自嗟迟暮的愁绪也更为浓烈了；然而，幸好今天没有去赴府会，居然在园中还欣赏了片刻春光，否则错过时机，在想见到“云破月来花弄影”的动人景象就不可能了。这正是用这末一句衬出了作者在流连光景不胜情的淡淡哀愁中所闪现出的一星晶莹艳丽的火花——“云破月来花弄影”。', poem_tags = '宋词三百首,婉约,伤春' WHERE poem_title = '天仙子·水调数声持酒听' AND poem_author = '张先';
UPDATE edu_poem SET poem_translation = '成的紫檀金屑文，可以做成琵琶其声音洪亮直上云霄。\n遥远的胡地三万里，即使是送与王明君马上作乐的琵琶声又哪能穿越。\n身处异地即便是欢乐也让人觉得悲凉，这羌笛胡笳也不用再吹。\n坐在边塞看着今晚的月亮，心里想的是杀光边关的敌人。', poem_tags = '边塞,战争' WHERE poem_title = '凉州词' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '连日雨后，树木稀疏的村落里炊烟冉冉升起。烧好的粗茶淡饭是送给村东耕耘的人。\n广阔平坦的水田上一行白鹭掠空而飞；田野边繁茂的树林中传来黄鹂宛转的啼声。\n我在山中修身养性，观赏朝槿晨开晚谢；在松下吃着素食，和露折葵不沾荤腥。\n我已经是一个从追名逐利的官场中退出来的人，而鸥鸟为什么还要猜疑我呢？\n\n韵译\n空林积雨，薪火难以点燃。午饭做完，马上送向田间。\n漠漠水田，飞起几只白鹭；阴阴夏树，传来婉转鸟鸣。\n惯于山间安静，早起遍地看花。松下长吃素食，采摘露葵佐餐。\n我与野老已融洽无间，海鸥为何还要猜疑？', poem_notes = '积雨：久雨。辋（wǎng）川庄：即王维在辋川的宅第，在今陕西蓝田终南山中，是王维隐居之地。\n空林：疏林。唐孟浩然《题大禹寺义公禅房》诗：“义公习禅处，结宇依空林。”烟火迟：因久雨林野润湿，故烟火缓升。\n藜（lí）：一年生草本植物，嫩叶可食。黍（shǔ）：谷物名，古时为主食。饷东菑（zī）：给在东边田里干活的人送饭。饷：送饭食到田头。菑：已经开垦了一年的田地，此泛指农田。\n漠漠：形容广阔无际。唐罗隐《省试秋风生桂枝》诗：“漠漠看无际，萧萧别有声。”\n阴阴：幽暗的样子。唐李端《送马尊师》诗：“南入商山松路深，石床溪水昼阴阴。”夏木：高大的树木，犹乔木。夏：大。啭（zhuàn）：小鸟婉转的鸣叫。鸟的宛转啼声。黄鹂：黄莺。\n“山中”句：意谓深居山中，望着槿花的开落以修养宁静之性。习静：谓习养静寂的心性。亦指过幽静生活。南朝梁何逊《苦热》诗：“习静閟衣巾，读书烦几案。”槿（jǐn）：植物名。落叶灌木，其花朝开夕谢。古人常以此物悟人生枯荣无常之理。其花早开晚谢。故以此悟人生荣枯无常之理。\n清斋：谓素食，长斋。晋支遁《五月长斋》诗：“令月肇清斋，德泽润无疆。”露葵：经霜的葵菜。葵为古代重要蔬菜，有“百菜之主”之称。\n野老：村野老人，此指作者自己。争席罢：指自己要隐退山林，与世无争。争席：典出《庄子·杂篇·寓言》：杨朱去从老子学道，路上旅舍主人欢迎他，客人都给他让座；学成归来，旅客们却不再让座，而与他“争席”，说明杨朱已得自然之道，与人们没有隔膜了。\n“海鸥”句：典出《列子·黄帝篇》：海上有人与鸥鸟相亲近，互不猜疑。一天，父亲要他把海鸥捉回家来，他又到海滨时，海鸥便飞得远远的，心术不正破坏了他和海鸥的亲密关系。这里借海鸥喻人事。何事：一作“何处”。', poem_appreciation = '“积雨空林烟火迟，蒸藜炊黍饷东菑。”首联写田家生活，是诗人山上静观所见。诗人视野所及，先写空林烟火，一个“迟”字，不仅把阴雨天的炊烟写得十分真切传神，而且透露了诗人闲散安逸的心境；再写农家早炊、饷田以至田头野餐，展现一系列人物的活动画面，秩序井然而富有生活气息，使人想见农妇田夫那怡然自乐的心情。\n\n　　颔联写自然景色，同样是诗人静观所得：“漠漠水田飞白鹭，阴阴夏木啭黄鹂。”辋川之夏，百鸟飞鸣，诗人只选了形态和习性迥然不同的黄鹂、白鹭，联系着它们各自的背景加以描绘：雪白的白鹭，金黄的黄鹂，在视觉上自有色彩浓淡的差异；白鹭飞行，黄鹂鸣啭，一则取动态，一则取声音；漠漠，形容水田广布，视野苍茫；阴阴，描状夏木茂密，境界幽深。两种景象互相映衬，互相配合，把积雨天气的辋川山野写得画意盎然。所谓“诗中有画”，这便是很好的例证。\n\n　　唐人李肇因见李嘉祐集中有“水田飞白鹭，夏木啭黄鹂”的诗句，便讥笑王维“好取人文章嘉句”（《国史补》卷上）；明人胡应麟力辟其说：“摩诘盛唐，嘉祐中唐，安得前人预偷来者？此正嘉祐用摩诘诗。”（《诗薮·内编》卷五）按，嘉祐与摩诘同时而稍晚，谁袭用谁的诗句，这很难说；然而，从艺术上看，两人诗句还是有高下的。宋人叶梦得认为王维添加的两个叠词使诗句更加精彩。“漠漠”有广阔意，“阴阴”有幽深意，“漠漠水田”“阴阴夏木”比之“水田”和“夏木”，画面就显得开阔而深邃，富有境界感，渲染了积雨天气空蒙迷茫的色调和气氛。\n\n　　如果说，首联所写农家无忧无虑的劳动生活已引起诗人的浓厚兴趣和欣羡之情，那么，面对这黄鹂、白鹭的自由自在的飞鸣，诗人自会更加陶醉不已。而且这两联中，人物活动也好，自然景色也好，并不是客观事物的简单摹拟，而是经过诗人心灵的感应和过滤，染上了鲜明的主观色彩，体现了诗人的个性。对于“晚年惟好静，万事不关心”的王维来说，置身于这世外桃源般的辋川山庄，真可谓得其所哉了，这不能不使他感到无穷的乐趣。下面两联就是抒写诗人隐居山林的禅寂生活之乐的。\n\n　　“山中习静观朝槿，松下清斋折露葵。”诗人独处空山之中，幽栖松林之下，参木槿而悟人生短暂，采露葵以供清斋素食。这情调，在一般世人看来，未免过分孤寂寡淡了。然而早已厌倦尘世喧嚣的诗人，却从中领略到极大的兴味，比起那纷纷扰扰、尔虞我诈的名利场，不啻天壤云泥。\n\n　　“野老与人争席罢，海鸥何事更相疑？”诗人在这里借用了《庄子·寓言》和《列子·黄帝》中的两个典故，快慰地宣称自己早已去心机绝俗念，随缘任遇，与世无争，再也不被人猜忌，足可以免除尘世烦恼，悠悠然耽于山林之乐了。这两个充满老庄色彩的典故，一正用，一反用，两相结合，十分恰切地表现了作者远离尘嚣、澹泊自然的心境，而这种心境，正是上联所写“清斋”“习静”的结果。\n\n　　这首七律，形象鲜明，兴味深远，表现了诗人隐居山林、脱离尘俗的闲情逸致，流露出诗人对淳朴田园生活的深深眷爱，是王维田园诗的一首代表作。从前有人把它推为全唐七律的压卷，说成“空古准今”的极至，固然是出于封建士大夫的偏嗜；而有人认为“淡雅幽寂，莫过右丞《积雨》”，赞赏这首诗的深邃意境和超迈风格，艺术见解还是不错的。（参看赵殿成笺注《王右丞集》卷十）', poem_tags = '唐诗三百首,田园' WHERE poem_title = '积雨辋川庄作 / 秋归辋川庄作' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '离别之后痛苦的相思如沧海一样深而无际，让自己备受煎熬，美好的往事就像天上的云一样，远不可即。想把握住这将别的时刻，流尽了千千万万行的眼泪，也留不住远行的恋人，让我愁肠寸断。\n我想与恋人相见却又无法相见，想要结束这段爱情却终究舍弃不了。你我如果是前生没有缘分，那么就等待来生，再结为夫妻。', poem_notes = '卜算子：词牌名，又名《百尺楼》、《眉峰碧》、《楚天遥》等。\n答施：指答复姓施的情人。\n旧事：往事。\n如：如同。\n泪滴：流眼泪。\n因：作“由”的意思。\n拚（pàn）：割舍。\n了（liǎo）：结束，断绝。\n若是：如果是。\n重（chóng）：重新。', poem_appreciation = '乐婉此词直抒胸臆，明白如话。上片中，“相思似海深，旧事如天远。”临别之前，却从别后的情况说起，起句便奇。“泪滴千千万万行，更使人、愁肠断。”上一句势若江河，一泻而下，下一句一断一续，正如哽咽。诀别的时刻最终还是来临了。女诗人既道尽别后的痛苦，又诉尽临别的伤心，似乎已无可再言。\n\n　　而下片更是奇外出奇，奇人之又奇。“要见无因见，拼了终难拼。”表现出诗人内心那种要重见，却无法重见，要死心，却又死不了心的纠结心理。而“若是前生未有缘，待重结、来生愿。”表现的是诗人在绝望之中，发一愿，又生出一线希望。而此一线希望，到底是希望还是绝望，令人难以分辨。唯此一大愿，意长留天地。\n\n　　上下片两结句（赠词下结除外），较通常句式增加了一个字，化五言为六言句，于第三字顿，遂使这个词调一气流转的声情，增添了顿宕波峭之致。全词犹如长江之水，一流而去永不回头，但其意蕴仍觉有馀。以一位风尘女子，而能够得到此段奇情异彩，历来受到人们的喜爱，其奥秘正在于词中道出了古往今来的爱情真谛：生死不渝。这是词中的最高境界。\n\n　　全词篇幅虽短，但是，一位感情真挚，思想果断的女性形象，活脱脱的跃然于纸上。以泪滴千千万万行之人，以绝不可能断了之情，直道出作者的真挚情感，为之一拼，转念便直说出终是难舍，如此种种念头，皆在情理之中。但在别人则未必能够直接道出自己的感情，而她却能直言不讳，这正是由于作者的性格豪爽果决。至于思旧事如天远，要重见而无因见，待重结、来生愿，若不是感情真挚的人，那是说不出的。\n\n　　中国古代的仁人志士，小而对于个人爱情，大而对于民族传统，皆抱有一种忠实的态度，即使当其不幸而处于绝望关头，生死难关之时，也能体现出一种生死不渝的精神。唯其此种精神，小而至于个人爱情，才能够心心相印，肝胆相照；大而至于民族文化，才能够绵延不绝，生生不已。两者表面上有大小之别，实际上则具共通之义。乐婉此词虽为言情小令，但其比喻的宗旨则并非一首言情小令所能代替的。', poem_tags = '爱情,离别,相思' WHERE poem_title = '卜算子·答施' AND poem_author = '乐婉';
UPDATE edu_poem SET poem_translation = '暮春时节，深闺里无边的寂寞如潮水般涌来，这一寸的柔肠却要容下千丝万缕的愁绪。越是珍惜春天，春天却越容易流逝，淅淅沥沥的雨声催着落红，也催着春天归去的脚步。\n在这寂寞暮春里，倚遍了每一寸相思阑干，纵是春天千般好，怎奈也是无情绪。轻问一声：“良人呵，你在何处？”眼前只有那一眼望不到边的连绵衰草，蔓延着良人必经的道路。', poem_notes = '点绛唇：词牌名。\n“寂寞”二句：此系对韦庄调寄《应天长》二词中有关语句的隐括和新变。\n人何处：所思念的人在哪里？此处的“人”，当与《凤凰台上忆吹箫·香冷金猊》的“武陵人”及《满庭芳·小阁藏春》的“无人到”中的二“人”字同意，皆喻指作者的丈夫赵明诚。\n“连天”二句：化用《楚辞·招隐士》“王孙游兮不归，春草生兮萋萋”之句意，以表达亟待良人归来之望。', poem_tags = '宋词精选,闺怨,伤春,伤别' WHERE poem_title = '点绛唇·闺思' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '回忆当年在午桥畅饮，在座的都是英雄豪杰。月光映在河面，随水悄悄流逝，在杏花的淡淡影子里，吹起竹笛直到天明。\n二十多年的岁月仿佛一场春梦，我虽身在，回首往昔却胆战心惊。百无聊赖中登上小阁楼观看新雨初睛的景致。古往今来多少历史事迹，都让渔人在半夜里当歌来唱。', poem_notes = '临江仙：词牌名，又称《鸳鸯梦》、《雁后归》、《庭院深深》。双调，上片五句，押三平韵，三十字；下片同，共六十字。\n午桥：在洛阳南面。坐中：在一起喝酒的人。\n豪英：出色的人物。这两句说：想从前在午桥桥头饮宴，在一起喝酒的都是英雄好汉。\n长沟流月：月光随着流水悄悄地消逝。去无声：表示月亮西沉，夜深了。\n疏影：稀疏的影子。这两句说，在杏花稀疏的影子里吹起短笛，一直欢乐到天明。\n二十余年：二十多年来的经历（包括北宋亡国的大变乱）。堪惊：总是心战胆跳。\n新晴：新雨初晴。晴，这里指晴夜。渔唱：打鱼人编的歌儿。\n三更：古代漏记时，自黄昏至指晓分为五刻，即五更，三更正是午夜。', poem_appreciation = '这首《临江仙》词大概是在公元1135年（宋高宗绍兴五年）或1136年（绍兴六年）陈与义退居青墩镇僧舍时所作，当时作者四十六或四十七岁。陈与义是洛阳人，他追忆起二十多年前的洛阳中旧游，那时是徽宗政和年间，当时天下太平无事，可以有游赏之乐。其后金兵南下，北宋灭亡，陈与义流离逃难，备尝艰苦，而南宋朝廷在南迁之后，仅能自立，回忆二十多年的往事，真是百感交集。但是当他作词以抒发此种悲慨之时，并不直抒胸臆，而且用委婉的笔调唱叹而出（这正是作词的要诀）。上片是追忆洛中旧游。午桥在洛阳南，唐朝裴度有别墅在此。“杏花疏影里，吹笛到天明”二句，的确是造语“奇丽”（胡仔评语，见《苕溪渔隐丛话后集》卷三十四），一种良辰美景，赏心乐事，宛然出现词人心目中。但是这并非当前实境，而是二十多年前浩如烟海的往事再现而已。刘熙载说得好，“陈去非……《临江仙》：‘杏花疏影里，吹笛到天明’，此因仰承‘忆首’，府注‘一梦’，故此二句不觉豪酣转成怅悒，所谓好在句外者也。”（《艺概》卷四）下片起句“二十馀年如一梦，此身虽在堪凉。”一下子说到当前，两句中包含了二十多年无限国事沧桑、知交零落之感，内容极充实，运笔也极空灵。“闲登小阁”三句，不再接上文之意进一步抒发悲叹，而是直接去写，作者想到国家的兴衰自己的流离失所，于是看新晴，听渔唱，将沉重悲愤的情感转化为旷达之情。\n\n　　这首词节奏明快，浑成自然，如水到渠成，不见矫揉造作之迹。张炎称此词“真是自然而然”（《词源》卷下）。然“自然”并不等于粗露浅显，这就要求作者有更高的文学素养。彭孙遹说得好，“词以自然为宗，但自然不从追琢中来，亦率易无味。如所云绚烂之极仍归于平淡。……若《无住词》之‘杏花疏影里，吹笛到天明’，自然而然者也”（《金粟词话》）。\n\n　　陈与义词作虽少，但却受后世推重，而且认为其特点很像苏东坡。南宋黄升说，陈与义“词虽不多，语意超绝，识者谓其可摩坡仙之垒也。”（《中兴以来绝妙词选》卷一）清陈廷焯也说，陈词如《临江仙》，“笔意超旷，逼近大苏。”（《白雨斋词话》卷一）陈与义填词时是否有意模仿苏东坡呢？从他的为人，诗作可以看出，他并不是有意模仿，而是感情的自然抒发。陈与义作诗，近法黄（庭坚）、陈（师道），远宗杜甫，不受苏诗影响。至于填词，乃是他晚岁退居时的遣兴之作，他以前既非专业作词，所以很不留心当时的词坛风气，可见并未受其影响。譬如，自从柳永、周邦彦以来，慢词盛行，而陈与义却未作过一首慢词；词至北宋末年，专门雕饰，有矫揉造作之感，周邦彦是以“富艳精工”见称，贺铸亦复如是，而陈与义的词独是疏快自然，不假雕饰；可见陈与义填词是独往独来，自行其是，自然也不会有意学苏（东坡）的。\n\n　　不过，他既然擅长作诗，晚岁填词，运以诗法，自然也就会不谋而合，与苏相近了。以诗法入词，固然可以开拓内容，独创新意，但是仍必须保持词体本质之美，而不可以流露出直粗疏，失去词意。苏东坡是最先“以诗为词”的，但是苏词的佳作，如《卜算子》（缺月挂疏桐）、《水调歌头》（明月几时有）、《永遇乐》（明月如霜）、《洞仙歌》（冰肌玉骨）、《八声甘州》（有情风万里卷潮来）、《虞美人》（乳燕飞华屋）诸作，都是“如春花散空，不著迹象，使柳枝歌之，正如天风海涛之曲，中多幽咽怨断之音”（夏敬观手批《东坡词》，转引自龙榆生《唐宋名家词选》）。评词者不可不知此意也。', poem_tags = '宋词三百首,豪放,回忆,感伤' WHERE poem_title = '临江仙·夜登小阁忆洛中旧游' AND poem_author = '陈与义';
UPDATE edu_poem SET poem_translation = '我在长满芳草花卉的原野尽情地游玩，目睹春色已到远山，四周一片碧绿。乘着兴致追逐随风飘飞的红色花瓣，穿过柳丝飘摇的小巷；感到困倦时，对着溪边流水，坐在长满青苔的石头上休息。休要推辞这杯酒，辜负十分诚挚劝酒的心意，只是怕风吹花落，一片片飞散了。况且今日是清明佳节，又遇着晴朗的好天气，极宜游乐，但不可乐而忘返。', poem_notes = '恣行：尽情游赏。\n遥山：远山。\n兴：乘兴，随兴。\n乱红：指落花。\n游衍：是游玩溢出范围的意思。', poem_tags = '清明节,春游,感叹,人生,珍惜' WHERE poem_title = '郊行即事' AND poem_author = '程颢';
UPDATE edu_poem SET poem_tags = '初中文言文,寓理,故事' WHERE poem_title = '宋定伯捉鬼' AND poem_author = '干宝';
UPDATE edu_poem SET poem_translation = '在山边的幽谷里和水边的村庄中，疏疏落落的梅花让过客魂断不舍。\n一直遗憾的是东风没有情趣，越发地吹拂着烟雾似的朦胧细雨使黄昏更加暗淡。', poem_notes = '嵲（niè）\n幽谷：幽静深邃的山谷。\n犹：仍然，还。\n恨：悔恨，遗憾。\n无意思：没有风情，情趣。\n烟雨：像烟雾一样的朦胧细雨。', poem_tags = '咏物,梅花,抒怀' WHERE poem_title = '墨梅' AND poem_author = '张嵲';
UPDATE edu_poem SET poem_translation = '蒹葭面对摧残不能够保全自我，又被瑟瑟秋风吹着该怎么办。\n只是在极短的时间里盛开花朵，很快叶子就会沉入水中。\n在形体柔弱的时候春风拂过都嫌来得早，在生长成密丛时夜里的寒露又多了。\n即使衰败后花叶摇落，还担心岁月虚度。', poem_notes = '蒹葭：植物名，即芦荻，芦苇。蒹，没有长穗的芦苇。葭，初生的芦苇。一般生长于沼泽、河沿、海滩等湿地。\n摧折：摧残折断。\n自守：保卫自己，坚守自我。\n若何：怎么办。《新唐书》有“诏不许，若何？”\n花戴雪：暗指花开。芦苇花为灰白之色，花开如同顶着白雪。\n蹉跎：失意，虚度光阴。\n江湖后摇落：此处江湖引申为退隐。贾岛《过唐校书书斋》诗“江湖心自切，未可挂头巾。”', poem_tags = '感慨,时间,岁月' WHERE poem_title = '蒹葭' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_tags = '古诗三百首,游子,惭愧' WHERE poem_title = '岁暮到家 / 岁末到家' AND poem_author = '蒋士铨';
UPDATE edu_poem SET poem_translation = '巍巍的太乙山临近长安城，山连着山一直蜿蜒到海边。\n白云缭绕回望中合成一片，青霭迷茫进入山中都不见。\n中央主峰把终南东西隔开，各山间山谷迥异阴晴多变。\n想在山中找个人家去投宿，隔水询问那樵夫可否方便？', poem_notes = '终南山，在长安南五十里，秦岭主峰之一。古人又称秦岭山脉为终南山。秦岭绵延八百余里，是渭水和汉水的分水岭。\n太乙：又名太一，秦岭之一峰。唐人每称终南山一名太一，如《元和郡县志》：“终南山在县（京兆万年县）南五十里。按经传所说，终南山一名太一，亦名中南“。\n天都：天帝所居，这里指帝都长安。\n青霭：山中的岚气。霭：云气。\n海隅：海边。终南山并不到海，此为夸张之词。\n分野：古天文学名词。古人以天上的二十八个星宿的位置来区分中国境内的地域，被称为分野。地上的每一个区域都对应星空的某一处分野。\n壑：山谷。“分野中峰变，阴晴众壑殊”这两句诗是说终南山连绵延伸，占地极广，中峰两侧的分野都变了，众山谷的天气也阴晴变化，各自不同。\n人处：有人烟处。', poem_appreciation = '艺术创作，贵在以个别显示一般，以不全求全，刘勰所谓“以少总多”，古代画论家所谓“意余于 象”，都是这个意思。作为诗人兼画家的王维，很懂得此中奥秘，因而能用只有四十个字的一首五言律诗，为偌大一座终南山传神写照。\n\n　　首联“太乙近天都，连山接海隅”，先用夸张手法勾画了终南山的总轮廓。这个总轮廓，只能得之于遥眺，而不能得之于逼视。所以，这一联显然是写远景。\n\n　　“太乙”是终南山的别称。终南虽高，去天甚遥，说它“近天都”，当然是艺术夸张。但这是写远景，从平地遥望终南，其顶峰的确与天连接，因而说它“近天都”，正是以夸张写真实。“连山接海隅”也是这样。终南山西起甘肃天水，东止河南陕县，远远未到海隅。说它“接海隅”，固然不合事实，说它“与他山连接不断，直到海隅”，又何尝符合事实？然而这是写远景，从长安遥望终南，西边望不到头，东边望不到尾。用“连山接海隅”写终南远景，虽夸张而愈见真实。\n\n　　次联写近景，“白云回望合”一句，“回望”既与下句“入看”对偶，则其意为“回头望”，王维写的是入终南山而“回望”，望的是刚走过的路。诗人身在终南山中，朝前看，白云弥漫，看不见路，也看不见其他景物，仿佛再走几步，就可以浮游于白云的海洋；然而继续前进，白云却继续分向两边，可望而不可即；回头看，分向两边的白云又合拢来，汇成茫茫云海。这种奇妙的境界，凡有游山经验的人都并不陌生，而王维却能够只用五个字就表现得如此真切。\n\n　　“青霭入看无”一句，与上句“白云回望合”是“互文”，它们交错为用，相互补充。诗人走出茫茫云海，前面又是蒙蒙青霭，仿佛继续前进，就可以摸着那青霭了；然而走了进去，却不但摸不着，而且看不见；回过头去，那青霭又合拢来，蒙蒙漫漫，可望而不可即。\n\n　　这一联诗，写烟云变灭，移步换形，极富含蕴。即如终南山中千岩万壑，苍松古柏，怪石清泉，奇花异草，值得观赏的景物还多，一切都笼罩于茫茫“白云”、蒙蒙“青霭”之中，看不见，看不真切。唯其如此，才更令人神往，更急于进一步“入看”。另一方面，已经看见的美景仍然使人留恋，不能不“回望”，“回望”而“白云”、“青霭”俱“合”，则刚才呈现于眉睫之前的景物或笼以青纱，或裹以冰绡，由清晰而朦胧，由朦胧而隐没，更令人回味无穷。这一切，诗人都没有明说，但他却在已经勾画出来的“象”里为我们留下了驰聘想象的广阔天地。\n\n　　第三联高度概括，尺幅万里。首联写出了终南山的高和从西到东的远，这是从山北遥望所见的景象。至于终南从北到南的阔，则是用“分野中峰变”一句来表现。游山而有“分野中峰变”的认识，则诗人立足“中峰”，纵目四望之状已依稀可见。终南山东西之绵远如彼，南北之辽阔如此，只有立足于“近天都”的“中峰”，才能收全景于眼底；而“阴晴众壑殊”，就是尽收眼底的全景。所谓“阴晴众壑殊”，当然不是指“东边日出西边雨”，而是以阳光的或浓或淡、或有或无来表现千岩万壑千形万态。\n\n　　对于尾联，历来有不同的理解、不同的评价。有些人认为它与前三联不统一、不相称，从而持否定态度。王夫之辩解说：“‘欲投人处宿，隔水问樵夫’，则山之辽廓荒远可知，与上六句初无异致，且得宾主分明，非独头意识悬相描摹也。”（《姜斋诗话》卷二）沈德潜也说：“或谓末二句与通体不配。今玩其语意，见山远而人寡也，非寻常写景可比。”（《唐诗别裁》卷九）\n\n　　这些意见都不错，然而“玩其语意”，似乎还可以领会到更多的东西。第一，欲投人处宿”这个句子分明有个省略了的主语“我”，因而有此一句，便见得“我”在游山，句句有“我”，处处有“我”，以“我”观物，因景抒情。第二，“欲投人处宿”而要“隔水问樵夫”，则“我”还要留宿山中，明日再游，而山景之赏心悦目，诗人之避喧好静，也不难于言外得之。第三，诗人既到“中峰”，则“隔水问樵夫”的“水”实际上是深沟大涧；那么，他怎么会发现那个“樵夫”呢？“樵夫”必砍樵，就必然有树林，有音响。诗人寻声辨向，从“隔水”的树林里欣然发现樵夫的情景，不难想见。既有“樵夫”，则知不太遥远的地方必然有“人处”，因而问何处可以投宿，“樵夫”口答手指、诗人侧首遥望的情景，也不难想见。\n\n　　诗旨在咏叹终南山的宏伟壮大。首联写远景，以艺术的夸张，极言山之高远。颔联写近景，身在山中之所见，铺叙云气变幻，移步变形，极富含蕴。颈联进一步写山之南北辽阔和千岩万壑的千形万态。末联写为了入山穷胜，想投宿山中人家。“隔水”二字点出了作者“远望”的位置。全诗写景、写人、写物，动如脱兔，静若淑女，有声有色，意境清新、宛若一幅山水画。\n\n　　总起来看，这首诗的主要特点和优点是善于“以不全求全”，从而收到了“以少总多”、“意余于象”的艺术效果。', poem_tags = '唐诗三百首,高中古诗,写山' WHERE poem_title = '终南山' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '中午，天气炎热，想不到夜晚还是那么热。打开门，到月光下去站一会儿吧。 \n这时，远处的竹林和树丛里，传来一声声虫子的鸣叫,一阵阵清凉的感觉也迎面飘来。可是，这并不是风，或许就是大自然宁静的凉意吧？', poem_appreciation = '“追凉”，即觅凉、取凉。较之“觅”和“取”，“追”更能表现对“凉”的渴求，杜甫“忆昔好追凉，故绕池边树”(《羌村三首》其二)诗意可见。但这首诗在艺术处理上却有其独到之处：它撇开了暑热难耐的感受，而仅就“追凉”着墨，以淡淡的几笔，勾勒出一幅夏夜追凉图，其中有皎洁的月光，有浓密的树荫，有婆娑的竹林，有悦耳的虫吟，以及作者悄然伫立的身影。\n\n　　首句貌似平直，其实也有一层曲折：中午时分，烈日暴晒，是一天中最为酷热的时刻，而今，“夜热”竟然与“午热”相仿佛，则“夜热”之甚，可想而知。唯其如此，才引出次句诗人月下独立的形象。“开门”，点出作者原在室内。或许他本已就寝，而因夜里天热的缘故，辗转反侧难以入梦，迫于无奈才出门纳凉。而“明月”，则点出正值“月华皎洁”的三五之夜。这样，作者“独立”的目的，应该说是“追凉”与“赏月”兼而有之，追凉可得体肤之适，赏月则可得精神之快，难怪他要独立不移、执着若此了。\n\n　　第三句是对周围环境的点染：竹林深深，树荫密密，虫鸣唧唧。“竹深树密”，见其清幽；“虫鸣”，则见其静谧——唯其静谧，“虫鸣”之声才能清晰入耳。诗人置身其间，凉意顿生，于是又引出结句“时有微凉不是风”，这一真切、细微的体验。“不是风”，点明所谓凉意，不过是夜深气清，静中生凉而已，并非夜风送爽。范成大《六月七日夜起坐殿取凉》诗亦云：“风从何处来?殿阁微凉生。桂旗俨不动，藻井森上征。”虽设问风从何来，但既然桂旗不动，可见非真有风，殿阁之“微凉”不过因静而生。人们通常说“心静自凉”，其理相若。因此，范诗实可与这首诗参读。\n\n　　显然静中生凉正是作者所要表现的意趣，但这一意趣并未直接点明。如果没有“不是风”三字，读者很可能将“凉”与“风”联系在一起。陈衍《石遗室诗话》早就指出：“若将末三字掩了，必猜是说甚么风矣，岂知其不是哉。”然而，这首诗的妙处恰恰也就在这里。作者故意直到最后，才将微露其本意的线索交给读者——既然明言“不是风”，善于神会的读者自当想到静与凉之间的因果关系；随即又当想到，前面出现的月光、竹林、树荫、虫鸣，都只是为揭示静中生凉之理所作的铺垫。这样，自然要比直截了当地道出本意更有诗味。大概这就是《石遗室诗话》所称道的“浅意深一层说，直意曲一层说”的旨趣。', poem_tags = '夏天' WHERE poem_title = '夏夜追凉' AND poem_author = '杨万里';
UPDATE edu_poem SET poem_translation = '杂乱的柳枝条还没有变黄，在东风的吹动下狂扭乱舞。\n把它的飞絮想蒙住日月，但不知天地之间还有秋霜', poem_notes = '倚--仗恃，依靠。狂--猖狂。这两句形容柳树在春天绿得很快：柳条似乎还没有发黄，但趁着东风吹暖，一下子便飞快地变绿了。\n解把--解得，懂得。飞花--柳絮。', poem_tags = '古诗三百首,春天,咏物,柳树,讽刺' WHERE poem_title = '咏柳' AND poem_author = '曾巩';
UPDATE edu_poem SET poem_translation = '杨柳青青，枝叶垂到了地上。杨花漫漫，在空中纷乱地飞舞。\n送别的时候眼里的柳条折尽，杨花飞绝。请问远行的人什么时候回来呢？', poem_notes = '著地：碰到地。\n漫漫：遍布貌。\n搅：《说文》：乱也。\n借问：敬词，请问。', poem_tags = '送别,柳树' WHERE poem_title = '送别诗' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '如雪般的梨花淡淡的白，柳条透露出浓郁的春色，飘飘洒洒的柳絮夹带着如雪的梨花，布满了全城。\n我心绪惆怅，恰如东栏那一株白如雪的梨花，居俗世而自清，将这纷杂的世俗人生，看得多么透彻与清明。', poem_notes = '东栏：指诗人当时庭院门口的栏杆。\n柳深青：意味着春意浓。\n柳絮：柳树的种子。有白色绒毛，随风飞散如飘絮，因以为称。\n雪：这里喻指梨花。\n清明：清澈明朗。', poem_appreciation = '《东栏梨花》是一首感伤的诗，诗人因为梨花盛开而感叹时光的流逝。这首诗抒发了诗人感叹春光易逝、人生短促的哀愁，也抒发了诗人淡看人生、从失意中得到解脱的思想，寄予了作者自己清正坦荡的风骨。\n\n　　首句以“淡白”状梨花，以深青状柳叶，以柳青衬梨白，可谓是一青二白。梨花的淡白，柳的深青，这一对比，景色立刻就鲜活了，再加上第二句的动态描写：满城飞舞的柳絮，真是“春风不解禁杨花，蒙蒙乱扑行人面”，同时柳絮写出梨花盛开的季节，春意之浓，春愁之深，更加烘托出来。\n\n　　前两句以一青二白，突出了梨花的特点。它不妖艳，也不轻狂的神态，又在第三句“一株雪”里再次赋予梨花以神韵，并把咏梨花与自咏结合了起来。其实，这“一株雪”正是诗人自己的化身。因为苏轼一生正道直行，清廉洁白，坦荡如砥。 在咏梨花时，苏轼用了“柳絮飞时花满城”来加以衬托，梨花既不像“颠狂柳絮随风去”，也不像“轻薄桃花逐水流”，其品格是何其高尚的。诗人还用了“人生看得几清明”来加以侧面烘托梨花之“清明”。“一株雪”和“几清明”是对偶的写法，一不是指有一株梨树，而是指一株梨树一个作者自己，后两句意境如下：作者惆怅的站在东栏旁，梨树上满是白色的梨花，同时柳絮在飘，落在作者身上，作者也变成了“一株雪”，写的是凄清惆怅的意境，最后一句，人生看得几清明，人生能有几次清明，这是补足前句“惆怅”的内容，更增添悲凉的气氛。苏轼的诗，一向以豪放著称，像这样悲凉的很是少见。\n\n　　《东栏梨花》的最后两句化用了唐代诗人杜牧的《初冬夜饮》“砌下梨花一堆雪，明年谁此凭栏杆”。杜牧的诗说的是物是人非的感慨，而苏东坡的诗感慨的是人生的短促。', poem_tags = '感伤,人生,时光' WHERE poem_title = '东栏梨花' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '你为我热情拿过酒杯添满酒同饮共醉，我们一起拿筷子击打盘儿吟唱诗歌。\n虽然你诗才一流堪称国手也只是如此，但命中注定你不能出人头地也没有办法。\n抬眼看到的人都荣耀体面而你却长守寂寞，满朝官员都有了自己满意的位置而你却虚渡光阴。\n也知道你应该被才高名显所累，但这二十三年的损失也太多了。', poem_notes = '刘二十八使君：即刘禹锡。\n引：本意为用力拉开弓。这里形容诗人用力拿过朋友的酒杯，不容拒绝。说明诗人的热情、真诚和豪爽。\n箸（zhù）：筷子。\n举：抬。\n蹉跎（cuō tuó）：不顺利，虚渡光阴。\n合被：应该被。合，应该。是与命中注定相符合的应该。例：《说唐全传》：合当归位。\n才名：才气与名望。\n二十三年：刘禹锡于公元805年（唐顺宗永贞元年）旧历九月被贬连州刺史，赴任途中再贬朗州司马。十年后，奉诏入京，又复贬任连州刺史，转夔、和二州刺史。直至公元827年（唐文宗大和元年），方得回京，预计回到京城时，已达二十三年之久。', poem_appreciation = '表达诗人对刘禹锡的深深理解和真诚劝慰，同时也对其遭遇深表同情和不平。\n\n　　这首诗，对刘禹锡二十三年的坎坷遭遇，表示了无限感慨和不平。诗人说：你远在边远之地，过着寂寞的生活，满朝那么多官员，唯独你多次被贬外任；我深知你才高名重，却偏偏遭逢不公的对待，这二十三年，你失去的太多了。怨愤与对友人的同情溢于言表，见其直率与坦诚，亦见其与刘禹锡友情之深厚。为此，刘禹锡作了一首酬答诗，即著名的《酬乐天扬州初逢席上见赠》。\n\n　　“诗称国手徒为尔，命压人头不奈何。“这句是抱怨刘禹锡的怀才不遇。虽然写诗才华横溢，但命运始终让人无可奈何。表达的应该是乐天对刘禹锡悲惨遭遇的同情和愤恨。虽然说命运不可逆转，但实际上是把矛头指向满朝的官吏和当权者的，抱怨他们不珍惜人才。', poem_tags = '友情,劝慰' WHERE poem_title = '醉赠刘二十八使君' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '看那淇水弯弯岸，碧绿竹林片片连。高雅先生是君子，学问切磋更精湛，品德琢磨更良善。神态庄重胸怀广，地位显赫很威严。高雅先生真君子，一见难忘记心田。\n看那淇水弯弯岸，绿竹袅娜连一片。高雅先生真君子，美丽良玉垂耳边，宝石镶帽如星闪。神态庄重胸怀广，地位显赫更威严。高雅先生真君子，一见难忘记心田。\n看那淇水弯弯岸，绿竹葱茏连一片。高雅先生真君子，青铜器般见精坚，玉礼器般见庄严。宽宏大量真旷达，倚靠车耳驰向前。谈吐幽默真风趣，开个玩笑人不怨。', poem_notes = '淇：淇水，源出河南林县，东经淇县流入卫河。奥（yù）：水边弯曲的地方。\n绿竹：一说绿为王刍，竹为扁蓄。猗（ē）猗：长而美貌。猗，通“阿”。\n匪：通“斐”，有文采貌。\n切、磋、琢、磨：治骨曰切，象曰磋，玉曰琢，石曰磨。均指文采好，有修养。切磋，本义是加工玉石骨器，引申为讨论研究学问；琢磨，本义是玉石骨器的精细加工，引申为学问道德上钻研深究。\n瑟：仪容庄重。僩（xiàn）：神态威严。\n赫：显赫。咺（xuān）：有威仪貌。\n谖（xuān）：忘记。\n充耳：挂在冠冕两旁的饰物，下垂至耳，一般用玉石制成。琇（xiù）莹：似玉的美石，宝石。\n会弁（guì biàn）：鹿皮帽。会，鹿皮会合处，缀宝石如星。\n箦（zé）：积的假借，堆积。\n金、锡：黄金和锡，一说铜和锡。闻一多《风诗类钞》主张为铜和锡，还说：“古人铸器的青铜，便是铜与锡的合金，所以二者极被他们重视，而且每每连称。”\n圭璧：圭，玉制礼器，上尖下方，在举行隆重仪式时使用；璧，玉制礼器，正圆形，中有小孔，也是贵族朝会或祭祀时使用。圭与璧制作精细，显示佩带者身份、品德高雅。\n绰：旷达。一说柔和貌。\n猗（yǐ）：通“倚”。较：古时车厢两旁作扶手的曲木或铜钩。重（chóng）较，车厢上有两重横木的车子。为古代卿士所乘。\n戏谑：开玩笑。\n虐：粗暴。', poem_appreciation = '《诗经》中有许多人物的赞歌，称赞的对象也很广泛。其中重要一类被称颂的对象，是各地的良臣名将。《淇奥》就是一曲形象的赞歌，而时间、地点、人物的指涉性不强，因此可以说，诗中形象并非实指，而是周王朝时代一个品德高尚的士大夫，具有泛指意蕴。全诗分三章，反覆吟咏。但在内容上，并不按诗章分派，而是融汇赞美内容于三章之中。这是因为诗歌本身比较短小，不能长篇铺叙，无法按称颂对象的各个方面一一分述，只能混涵概括，点到为止。同时，三章内容基本一致，就起了反复歌颂的作用，使听者印象更加深刻。\n\n　　《淇奥》反复吟颂了士大夫几个方面的优秀之处：首先是外貌。这位官员相貌堂堂，仪表庄重，身材高大，衣服也整齐华美。“充耳琇莹”、“会弁如星”，连冠服上的装饰品也是精美的。外貌的描写，对于塑造一个高雅君子形象，是很重要的。这是给读者的第一印象。其次是才能。“如切如磋，如琢如磨”，文章学问很好。实际上，这是赞美这位君子的行政处事的能力。因为卿大夫从政，公文的起草制定，是主要工作内容。至于“猗重较兮”、“善戏谑兮”，突出君子的外事交际能力。春秋时诸侯国很多，能对应诸侯，不失国体，对每个士大夫都是个考验。看来，诗歌从撰写文章与交际谈吐两方面，表达了这君子处理内政和处理外事的杰出能力，突出了良臣的形象。最后，也是最重要的方面，是歌颂了这位君子的品德高尚。“如圭如璧，宽兮绰兮”，意志坚定，忠贞纯厚，心胸宽广，平易近人，的确是一位贤人。正因为他是个贤人，从政就是个良臣，再加上外貌装饰的庄重华贵，更加使人尊敬了。所以，第一、第二两章结束两句，都是直接的歌颂：“有匪君子，终不可谖兮！”从内心世界到外貌装饰，从内政公文到外事交涉，这位士大夫都是当时典型的贤人良臣，获得人们的称颂，是必然的了。此诗就是这样从三个方面，从外到内，突出了君子的形象。诗中一些句子，如“如切如磋，如琢如磨”、“善戏谑兮，不为虐兮”成为日后人们称许某种品德或性格的词语，可见《淇奥》一诗影响之深远了。', poem_tags = '诗经,赞美' WHERE poem_title = '国风·卫风·淇奥' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '一个人深居简出过着清幽的日子，俯瞰夹城，春天已去，夏季清朗。\n小草饱受雨水的浸淹，终于得到上天的怜爱，雨过天晴了。\n登上高阁，凭栏远眺，天高地迥，夕阳冉冉的余晖透过窗棂。\n越鸟的窝巢已被晒干，它们的体态也恢复轻盈了。', poem_notes = '夹城：城门外的曲城。\n幽草：幽暗地方的小草。\n并：更。高阁：指诗人居处的楼阁。迥：高远。\n微注：因是晚景斜晖，光线显得微弱和柔和，故说“微注”。\n越鸟：南方的鸟。', poem_appreciation = '首联说自己居处幽僻，俯临夹城，时令正值清和的初夏。乍读似不涉题，上下两句也不相属，其实“俯夹城”的“深居”即是览眺晚晴的立足点，而清和的初夏又进而点明了晚晴的特定时令，不妨说是从时、地两方面把诗题一体化了——初夏凭高览眺所见的晚晴。\n\n　　初夏多雨，岭南尤然。久雨转晴，傍晚云开日霁，万物顿觉增彩生辉，人的精神也为之一爽。这种景象与感受，本为一般人所习见、所共有。诗人的独特处，在于既不泛泛写晚晴景象，也不作琐细刻画，而是独取生长在幽暗处不被人注意的小草，虚处用笔，暗寓晚晴，并进而写出他对晚晴别有会心的感受。久遭雨潦之苦的幽草，忽遇晚晴，得以沾沐余辉而平添生意，诗人触景兴感，忽生“天意怜幽草”的奇想。这就使作为自然物的“幽草”无形中人格化了，给人以丰富的联想。诗人自己就有着类似的命运，故而很自然地从幽草身上发现自己。这里托寓着诗人的身世之感。他在为目前的幸遇欣慰的同时不期然地流露出对往昔厄运的伤感，或者说正由于有已往的厄运而倍感目前幸遇的可慰。这就自然引出“人间重晚晴”，而且赋予“晚晴”以特殊的人生含义。晚晴美丽，然而短暂，人们常在赞赏流连的同时对它的匆匆即逝感到惋惜与怅惘。然而诗人并不顾它的短暂，而只强调“重晚晴”。从这里，可以体味到一种分外珍重美好而短暂的事物的感情，一种积极、乐观的人生态度。\n\n　　颔联写得浑融概括，深有托寓，颈联则转而对晚晴作工致的描画。这样虚实疏密相间，诗便显得弛张有致，不平板，不单调。雨后晚晴，云收雾散，凭高览眺，视线更为遥远，所以说“并添高阁迥”（这高阁即诗人居处的楼阁）。这一句从侧面写晚晴，写景角度由内及外，下句从正面写，角度由外及内。夕阳的余晖流注在小窗上，带来了一线光明。因为是晚景斜晖，光线显得微弱而柔和，故说“微注”。尽管如此，这一脉斜晖还是给人带来喜悦和安慰。这一联通过对晚景的具体描绘，写出了一片明朗欣喜的心境，把“重”字具体化了。\n\n　　尾联写飞鸟归巢，体态轻捷，仍是登高览眺所见。“巢乾”、“体轻”切“晴”，“归飞”切“晚”。宿鸟归飞，通常是触动旅人羁愁的，这里却成为喜晴情绪的烘托。古诗有“越鸟巢南枝”之句，这里写越鸟归巢，带有自况意味。如果说“幽草”是诗人“沦贱艰虞”身世的象征，那么，“越鸟”似乎是眼前托身有所、精神振作的诗人的化身。\n\n　　作为一首有寓托的诗，《晚晴》的写法更接近于“在有意无意之间”的“兴”。诗人也许本无托物喻志的明确意图，只是在登高览眺之际，适与物接而触发联想，情与境谐，从而将一刹那间别有会心的感受融化在对晚晴景物的描写之中，所以显得特别自然浑成，不着痕迹。', poem_tags = '夏天,登高,写景,抒情' WHERE poem_title = '晚晴' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '不见南方的军队去北伐已经很久，金人就胡说中原的人才已一扫而空。当场伸出手来力挽狂澜，终究还要归还我的气压万夫的英雄。自笑身为堂堂的大汉民族的使节，居然像河水一般，向东而流（比喻对金人的朝拜）。暂且再向敌人的帐篷（穹庐）走一遭，将来定要征服他们，下次与金主再见就要在我大宋的属国使节馆了。\n是唐尧建立的城都，是虞舜开辟的土壤，是夏禹对疆域的分封。在这当中应有一个半个知耻的臣子站出来保卫国家。万里河山充斥着金人游牧民族的腥膻之气，千古以来的爱国志士的英灵安在，浩大的抗金正气什么时候才能伸张畅通？金人的命运用不着多问，祖国将像光辉灿烂的太阳照耀在空中。', poem_notes = '送章德茂大卿使虏：陈亮的友人章森，字德茂，当时是大理少卿，试户部尚书，奉命使金，贺金主完颜雍生辰（万春节），陈亮便写了本词赠别。\n北群空：语出韩愈《送温处士赴河阳军序》“伯乐一过冀北之野而马群遂空”，指没有良马，借喻没有良才。\n只手：独立支撑的意思。\n穹庐：北方少数民族居住的圆顶毡房。\n藁街：在长安城内，外国使臣居住的地方。《汉书·陈汤传》曾载陈汤斩匈奴郅支单于后奏请“悬头藁街”，以示万里明犯强汉者，虽远必诛”。\n腥膻：代指金人。因金人膻肉酪浆，以充饥渴。', poem_tags = '宋词三百首,议论,豪放,爱国,壮志' WHERE poem_title = '水调歌头·送章德茂大卿使虏' AND poem_author = '陈亮';
UPDATE edu_poem SET poem_translation = '会稽山上，云朵淡淡的像是水墨画中轻抹上去的一半；越州城外，衰草连天，无穷无际。城门楼上的号角声，时断时续。在北归的客船上，与歌妓举杯共饮，聊以话别。回首多少男女间情事，此刻已化作缕缕烟云散失而去。眼前夕阳西下，万点寒鸦点缀着天空，一弯流水围绕着孤村。\n悲伤之际又有柔情蜜意，心神恍惚下，解开腰间的系带，取下香囊。徒然赢得青楼中薄情的名声罢了。此一去，不知何时重逢？离别的泪水沾湿了衣襟与袖口。正是伤心悲情的时候，城已不见，万家灯火已起，天色已入黄昏。', poem_notes = '满庭芳：词牌名。双调九十五字，前片四平韵，后片五平韵。\n连：一作“黏”。\n谯门：城门。\n引：举。尊：酒杯。\n蓬莱旧事：男女爱情的往事。\n烟霭（ǎi）：指云雾。\n消魂：形容因悲伤或快乐到极点而心神恍惚不知所以的样子。\n谩（màn）：徒然。薄幸：薄情。', poem_appreciation = '有不少词调，开头两句八个字，便是一副工致美妙的对联。宋代名家，大抵皆向此等处见工夫，逞文采。诸如“作冷欺花，将烟困柳”。“叠鼓夜寒，垂灯春浅”……一时也举他不尽。这好比名角出台，绣帘揭处，一个亮相，丰采精神，能把全场“笼罩”住。试看那“欺”字“困”字，“叠”字“垂”字……词人的慧性灵心、情肠意匠，早已颖秀葩呈，动人心目。\n\n　　然而，要论个中高手，我意终推秦郎。比如他的笔下“碧水惊秋，黄云凝暮”，何等神笔!至于这首<满庭芳)的起拍开端：“山抹微云，天连衰草”，更是雅俗共赏，只此一个出场，便博得满堂碰头彩，掌声雷动——真好看煞人!\n\n　　这两句端的好在何处?\n\n　　大家先就看上了那“抹”字。好一个“山抹微云”!“抹”得奇，新鲜，别有意趣!\n\n　　“抹”又为何便如此新奇别致，博得喝采呢?\n\n　　须看他字用得妙，有人说是文也而通画理。\n\n　　抹者何也?就是用别一个颜色，掩去了原来的底色之谓。所以，唐德宗在贞元时阅考卷，遇有词理不通的，他便“浓笔抹之至尾”(煞是痛快)!至于古代女流，则时时要“涂脂抹粉”，罗虬写的“一抹浓红傍脸斜”，老杜说的“晓妆随手抹”，都是佳例，其实亦即用脂红别色以掩素面本容之义。\n\n　　如此说来，秦郎所指，原即山掩微云，应无误会。\n\n　　但是如果他写下酌真是“山掩微云”四个大字，那就风流顿减，而意致无多了。学词者宜向此处细心体味，同是这位词人，他在一首诗中却说：“林梢一抹青如画，知是淮流转处山。”同样成为名句。看来，他确实是有意地运用绘画的笔法而将它写入了诗词，人说他“通画理”，可增一层印证。他善用“抹”字。一写林外之山痕，一写山间之云迹，手法俱是诗中之画，画中之诗，其致一也。只单看此词开头四个字，宛然一幅“横云断岭”图。\n\n　　出句如彼，且看他对句用何字相敌?他道是：“天连衰草。”\n\n　　于此，便有人嫌这“连”字太平易了，觉得还要“特殊”一点才好。想来想去，想出一个“黏”字来。想起“黏”字来的人，起码是南宋人了，他自以为这样才“炼字”警策。大家见他如此写天际四垂，远与地平相“接”，好像“黏合”了一样，用心选辞，都不同俗常，果然也是值得击节赞赏!\n\n　　我却不敢苟同这个对字法。\n\n　　何以不取“黏”字呢?盖少游时当北宋，那期间，词的风格还是大方家数一派路子，尚五十分刁钻古怪的炼字法。再者，上文已然着重说明：秦郎所以选用“抹”并且用得好，全在用画人词，看似精巧，实亦信手拈来，自然成趣。他断不肯为了“敌”那个“抹”字，苦思焦虑，最后认上一个“黏”，以为“独得之秘”——那就是自从南宋才有的词风，时代特征是不能错乱的。“黏”字之病在于：太雕琢，——也就显得太穿凿；太用力，——也就显得太吃力。艺术是不以此等为最高境界的。况且，“黏”也与我们的民族画理不相贴切，我们的诗人赋手，可以写出“野旷天低”，“水天相接”。这自然也符合西洋透视学；但他们还不致也不肯用一个天和地像是黏合在一起这样的“修辞格”，因为画里没有这样的概念。这其间的分际，是需要仔细审辨体会的：大抵在选字工夫上，北宋词人宁肯失之“出”，而南宋词人则有意失之“人”。后者的末流，就陷入尖新、小巧一路，专门在一二字眼上做扭捏的工夫；如果以这种眼光去认看秦郎，那就南其辕而北其辙了。', poem_tags = '宋词三百首,宋词精选,婉约,惜别,写景' WHERE poem_title = '满庭芳·山抹微云' AND poem_author = '秦观';
UPDATE edu_poem SET poem_translation = '汉江流经楚塞又折入三湘，西起荆门往东与九江相通。\n远望江水好像流到天地外，近看山色缥缈若有若无中。\n岸边都城仿佛在水面浮动，水天相接波涛滚滚荡云空。\n襄阳的风光的确令人陶醉，我愿在此地酣饮陪伴山翁。', poem_notes = '汉江：即汉水，流经陕西汉中、安康，湖北十堰、襄阳、荆门、潜江、仙桃、孝感，到汉口流入长江。诗题在元代方回的《瀛奎律髓》中题名为“汉江临眺”，临眺，登高远望。汉江从襄阳城中流过，把襄阳与樊城一分为二（合称“襄樊”），以及襄樊周围大大小小的无数城郭（包括襄阳城门外的许多“瓮城”），一个个都像在眼前的水道两旁漂浮。临泛江上，随着小舟在波澜中摇晃，感觉远处的天空都在摇动，非常恰当地扣题，写出“临泛”的独特观感。假如是“汉江临眺”，就不会有这样的感觉。所以此诗还是应题为《汉江临泛》为是。\n楚塞：楚国边境地带，这里指汉水流域，此地古为楚国辖区。三湘：湖南有湘潭、湘阴、湘乡，合称三湘。一说是漓湘、蒸湘、潇湘总称三湘。\n荆门：山名，荆门山，在今湖北宜都县西北的长江南岸，战国时为楚之西塞。九派：九条支流，长江至浔阳分为九支。这里指江西九江。\n郡邑：指汉水两岸的城镇。浦：水边。\n好风日：一作“风日好”，风景天气好。\n山翁：一作“山公”，指山简，晋代竹林七贤之一山涛的幼子，西晋将领，镇守襄阳，有政绩，好酒，每饮必醉。这里借指襄阳地方官。', poem_appreciation = '此诗可谓王维融画法入诗的力作。\n\n　　“楚塞三湘接，荆门九派通”，语工形肖，一笔勾勒出汉江雄浑壮阔的景色，作为画幅的背景。春秋战国时期，湖北、湖南等地都属于楚国，而襄阳位于楚之北境，所以这里称“楚塞”。“三湘”，一说湘水合漓水为漓湘，合蒸水为蒸湘，合潇水为潇湘，合称三湘；一说为湖南的湘潭、湘阴、湘乡。古诗文中，三湘一般泛称今洞庭湖南北、湘江一带。“荆门”，山名，在今湖北宜都县西北。“九派”，指长江的九条支流，相传大禹治水，开凿江流，使九派相通。诗人泛舟江上，纵目远望，只见莽莽古楚之地和从湖南方面奔涌而来的“三湘”之水相连接，汹涌汉江入荆江而与长江九派汇聚合流。诗虽未点明汉江，但足已使人想象到汉江横卧楚塞而接“三湘”、通“九派”的浩渺水势。诗人将不可目击之景，予以概写总述，收漠漠平野于纸端，纳浩浩江流于画边，为整个画面渲染了气氛。\n\n　　“江流天地外，山色有无中”，以山光水色作为画幅的远景。汉江滔滔远去，好像一直涌流到天地之外去了，两岸重重青山，迷迷蒙蒙，时隐时现，若有若无。前句写出江水的流长邈远，后句又以苍茫山色烘托出江势的浩瀚空阔。诗人着墨极淡，却给人以伟丽新奇之感，其效果远胜于重彩浓抹的油画和色调浓丽的水彩。而其“胜”，就在于画面的气韵生动。王世贞说：“江流天地外，山色有无中，是诗家俊语，却入画三昧。”说得很中肯。而“天地外”、“有无中”，又为诗歌平添了一种迷茫、玄远、无可穷尽的意境，所谓“含不尽之意见于言外”。首联写众水交流，密不间发，此联开阔空白，疏可走马，画面上疏密相间，错综有致。\n\n　　接着，诗人的笔墨从“天地外”收拢，写出眼前波澜壮阔之景：“郡邑浮前浦，波澜动远空。”正当诗人极目远望，突然间风起浪涌，所乘之舟上下波动，眼前的襄阳城郭也随着波浪在江水中浮浮沉沉。风越来越大，波涛越来越汹涌，浪拍云天，船身颠簸，仿佛天空也为之摇荡起来。风浪之前，船儿是平缓地在江面行驶，城郭是静止地立于岸边，远空是不动地悬于天际；风浪忽至，一切都动了起来。这里，诗人笔法飘逸流动。明明是所乘之舟上下波动，却说是前面的城郭在水面上浮动；明明是波涛汹涌，浪拍云天，却说成天空也为之摇荡起来。诗人故意用这种动与静的错觉，进一步渲染了磅礴水势。“浮”、“动”两个动词用得极妙，使诗人笔下之景活起来了，诗也随之飘逸起来了，同时，诗人的一种泛舟江上的怡然自得的心态也从中表现了出来，江水磅礴的气也表现了出来。诗人描绘的景象是泛舟所见，舟中人产生了一种动荡的错觉，这种错觉也正好符合诗句中的汉水的描写，所以这两个词用得极其恰当。\n\n　　“襄阳好风日，留醉与山翁。”山翁，即山简，晋人。《晋书·山简传》说他曾任征南将军，镇守襄阳。当地习氏的园林，风景很好，山简常到习家池上大醉而归。诗人要与山简共谋一醉，流露出对襄阳风物的热爱之情。此情也融合在前面的景色描绘之中，充满了积极乐观的情绪。尾联诗人直抒胸臆，表达了留恋山水的志趣。\n\n　　这首诗给读者展现了一幅色彩素雅、格调清新、意境优美的水墨山水画。画面布局，远近相映，疏密相间，加之以简驭繁，以形写意，轻笔淡墨，又融情于景，情绪乐观，这就给人以美的享受。王维同时代的殷璠在《河岳英灵集》中说：“维诗词秀调雅，意新理惬，在泉为珠，着壁成绘。”此诗很能体现这一特色。同时，也\n\n　　表达了诗人追求美好境界、希望寄情山水的思想感情。', poem_tags = '唐诗三百首,山水,抒情' WHERE poem_title = '汉江临泛 / 汉江临眺' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '春天，山上的野桃花红艳艳的开的正旺，蜀江的江水拍着旁边的悬崖峭壁。\n一位姑娘看见了，认为丈夫的喜爱如同这桃花转瞬即逝，而无限的忧愁就如这源源不断的江水。', poem_notes = '山桃：野桃。\n上头：山头，山顶上。', poem_appreciation = '头两句写眼前景色：“山桃红花满上头，蜀江春水拍山流。”上句写满山桃花红艳艳，下句写江水拍山而流，描写了水恋山的情景，这样的情景原是很美的，但对诗中的女子来讲，如此美景恰恰勾起了她的无限痛苦：“花红易衰似郎意，水流无限似侬愁。”这两句是对景抒情，用的是两个比喻：花红易衰，正像郎君的爱情虽甜，但不久便衰落；而流水滔滔不绝，正好像自己的无尽愁苦。这两句形象地描绘出了了这个失恋女子的内心痛苦。比喻贴切、动人，使人读了，不禁为这个女子在爱情上的不幸遭遇而深受感动。南唐后主李煜的《虞美人》词：“问君能有几多愁，恰是一江春水向东流。”用江水比拟亡国之痛的深沉悠长，历来被人们称为写愁的名句，其实这正是从“水流无限似侬愁”一句脱胎而来的。\n\n　　这首诗和前首诗一样，用的也是民歌常用的比兴手法，先写眼前水恋山的景象，然后再用它来作比喻，抒写愁绪，从而形象地描绘出人物的内心情感。全诗比喻新颖别致，形象感强。', poem_tags = '宋词三百首,写景,桃花,爱情' WHERE poem_title = '竹枝词·山桃红花满上头' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '红花满树，青山隐隐，日已偏西。广漠的郊野，草色青绿，看不见边际。\n游春的人们，兴趣正浓，哪管春天将去。丰乐亭前，人来人往，落花遍地。', poem_notes = '红树：开红花的树，或落日反照的树，非指秋天的红叶。\n长郊：广阔的郊野。无涯：无边际。\n老：逝去。一作“尽”。春将老：春天将要过去。', poem_tags = '古诗三百首,写景,惜春' WHERE poem_title = '丰乐亭游春·其三' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '庭院一层层的有好多层，云簇阁楼的窗户，淡淡的雾气弥漫在四周，春天却迟迟不来。思念让容色憔悴，只有在夜晚的梦中才能相聚，向阳的梅枝也到了发芽的时节。\n梅花风姿清瘦，南楼的羌笛不要吹奏哀怨的曲调。散发着浓浓的香味的梅花不知道被吹落多少？春日的暖风，别一下就让时间来到杏花盛开的时节了。', poem_notes = '《临江仙·梅》：此首或为李清照效法欧阳修《蝶恋花》所作的数阕《临江仙》之一。\n南枝：向南，亦即朝阳的梅枝。\n玉瘦檀轻：谓梅花姿态清瘦，颜色浅红。檀：原为木名，此处指浅绛色。\n羌管休吹：意谓不要吹奏音调哀怨的笛曲《梅花落》。\n暖风迟日：语出孙光宪《浣溪沙》词：“兰沐初休曲槛前，暖风迟日洗头天。”迟日：春日，语出杜审言《渡湘江》诗：“迟日园林悲昔游，今春花鸟作边愁。”\n肥：这里指盛开。', poem_appreciation = '这首词以咏梅为题，用梅花暗喻词人自己，把闺人幽独的离思与韶华易逝的帐悯，极其高华而深至地表现了出来。\n\n　　“庭院深深深几许”起句袭用欧词，一字不改，而又融化不涩，别具意境。这种问鼎名篇的作法，表现了漱玉词人的魄力与艺术上的自信。以设问的口气一连迭用三个“深”字，能在读者心中唤起了一种院宇深邃，气象雍容的声情效果。迭字用得好，却能形容尽妙，动人于不自觉之中……李清照这首《临江仙》一、二两句用得浑成而富有变化。因而避免了袭用成句容易造成的雷同之感。“庭院”句言其深，“云窗”句状其高。一纵一横，交相映衬，便将一座贵家池馆的富丽与清幽的气象勾画出来了。云簇疏棂，雾迷高阁，这是何其缥缈清幽、高出尘寰的所在呵。“春迟”二字语义双关，包蕴甚深，不可草草读过。乍看起来，仿佛是主人公慨叹春光的姗姗来迟。然而这仅是表面的理解。其实，阳春有一序，天地无私，烂漫的春光是不会遗弃这锦屏府第的，这个“迟”字所反映的意蕴中不只是客观的景物，而且是一种主观的感情。作者是借春光不到的艺术构思来表现春闺思妇的凄黯心绪。它同“羌笛何须怨杨柳，春风不度玉门关。”“玉颜不及寒鸦色，犹带昭阳日影来。”等等，可说是同其委婉的手法。“为谁憔悴损芳姿？”更设一问，以跌宕的笔触，补足上文。指出了原来使闺中人赏春无绪、芳姿悴损的，不正是对远人的思念和被爱情的折磨吗？几经铺垫，到此才将一篇题旨揭出来。“夜来清梦好，应是发南枝”，歇拍处点出梅花，承上巨启下之笔，高华中带有一些凄丽的意味。“清梦”乃是结想而成的南柯相会。远人纵未得归，这梦里的欢娱便也是一分消受了。\n\n　　以清词写苦思，倍增凄苦……她不是以梅花直接比人，而是把梅花同清梦联系起来，因好梦而溯及梅花，又以“应是”云云推测之词，加以摇曳，愈觉意折层探，令人回味不尽。漱玉词富于形象之美，尤长于活用比况类形容词。如“绿肥红瘦”与此处之“别到杏花肥”等，皆能别出巧思，一新耳目。“杏花肥”犹言杏花盛开也。然而不用常语而换一“肥”字，把形容词活用作谓语，就大增其直观的美感。巧而不尖，新而不怪，真能超越凡庸，别开生面。此处着一“肥”字，上与“瘦”字关合，以梅花之玉瘦，衬红杏之憨肥，益觉鲜明生动。同时两相映带，还点明了时间的跨度。从早梅绽蕊直盼到杏花开遍，二十四番花信风，已吹过十一番了。春光半过，伊人未归，花落花开，只成孤赏。难怪园中的春色，尽作愁痕了。末尾以景结情，骚情雅韵，令人凄然无尽，洵为小令中精品。', poem_tags = '咏物,梅花,言志' WHERE poem_title = '临江仙·梅' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '在采石江边，无边的野草围绕坟地，远接白云。\n可悲的是这荒坟深穴中的枯骨，曾经写过惊天动地的诗文。\n只要是诗人，大都命运不好，而诗人穷困失意，谁也没有超过李君。', poem_notes = '李白墓：唐代大诗人李白死于当涂（今属安徽），初葬龙山，元和十二年（817年）正月迁葬青山。今安徽马鞍山南采石山下采石镇犹存墓址。过往诗人到此多有吟咏。\n采石：即采石矶，原名牛渚矶，在安徽省马鞍山市长江东岸，为牛渚山北部突出江中而成，江面较狭，形势险要，自古为大江南北重要津渡，也是江防重镇。相传为李白醉酒捉月溺死之处。有太白楼、捉月亭等古迹。\n田：指墓地。\n可怜：可叹，可悲。荒垄：荒芜的坟墓。穷泉：泉下，指埋葬人的地下，墓中。\n惊天动地：形容发生的事情极不寻常，令人震惊。这是对李白诗文的高度评价，认为可以感动天地。\n但是：但凡是，只是。薄命：命运不好，福分差。\n就中：其中。沦落：落魄，穷困失意。君：指李白。', poem_tags = '写人,悼亡' WHERE poem_title = '李白墓' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '在一个细雨初晴的春日，杨柳的颜色已经由初春的鹅黄嫩绿变得苍翠浓郁，经过细雨的洗浴后，柳色变得更加深暗，枝头的残花也在雨中全都落尽，露出了在枝头啼鸣的流莺。\n昨天晚上一夜春风吹起了我的甜蜜的思乡梦，在梦中我追逐着春风飞回了我的家乡。', poem_notes = '春兴：春游的兴致。唐皇甫冉《奉和对山僧》：“远心驰北阙，春兴寄东山。”\n阴阴：形容杨柳幽暗茂盛。\n流莺：即莺。流，谓其鸣声婉转。南朝梁沈约 《八咏诗·会圃临东风》：“舞春雪，杂流莺。”\n乡梦：美梦；甜蜜的梦境。乡：一作“香”。\n梦：一作“又”。洛城：洛阳，诗人家乡缑氏在洛阳附近。', poem_tags = '春天,思乡' WHERE poem_title = '春兴' AND poem_author = '武元衡';
UPDATE edu_poem SET poem_translation = '落日金光灿灿，像熔化的金水一般，暮云色彩波蓝，仿佛碧玉一样晶莹鲜艳。景致如此美好，可我如今又置身于何地哪边？新生的柳叶如绿烟点染，《梅花落》的笛曲中传出声声幽怨。春天的气息已露倪端。但在这元宵佳节融和的天气，又怎能知道不会有风雨出现？那些酒朋诗友驾着华丽的车马前来相召，我只能报以婉言，因为我心中愁闷焦烦。\n记得汴京繁盛的岁月，闺中有许多闲暇，特别看重这正月十五。帽子镶嵌着翡翠宝珠，身上带着金捻成的雪柳，个个打扮得俊丽翘楚。如今容颜憔悴，头发蓬松也无心梳理，更怕在夜间出去。不如从帘儿的底下，听一听别人的欢声笑语。', poem_notes = '吹梅笛怨：梅，指乐曲《梅花落》，用笛子吹奏此曲，其声哀怨。\n次第：这里是转眼的意思。\n香车宝马：这里指贵族妇女所乘坐的、雕镂工致装饰华美的车驾。\n中州：即中土、中原。这里指北宋的都城汴京，今河南开封。\n三五：十五日。此处指元宵节。\n铺翠冠儿：以翠羽装饰的帽子。雪柳：以素绢和银纸做成的头饰(详见《岁时广记》卷十一)。此二句所列举约均为北宋元宵节妇女时髦的妆饰品。\n簇带：簇，聚集之意。带即戴，加在头上谓之戴。济楚：整齐、漂亮。簇带、济楚均为宋时方言，意谓头上所插戴的各种饰物。', poem_appreciation = '这首词是李清照晚年避难江南时的作品，写她在一次元宵节时的感受。\n\n　　词的上片写元宵佳节寓居异乡的悲凉心情，着重对比客观现实的欢快和她主观心情的凄凉。起始二句“落日熔金，暮云合璧”，写晚晴，正是度节日的好天气，意境开阔，色彩绚丽。紧接“人在何处”四字，点出自己的处境：飘泊异乡，无家可归，同吉日良辰形成鲜明对照。（这里的“人”，有的评论者认为指李清照所怀念的亲人，从文意上看，似不如指作者自己为好。）前三句写当时的天气，次三句写当时的季节，“染柳烟浓，吹梅笛怨”，点出时令是初春。上句从视觉着眼，写早春时节初生细柳被淡烟笼罩。下句从听觉落笔，通过笛声传来的哀怨曲调，联想到“砌下落梅如雪乱”的初春景色。四处充满春意，景色宜人，但在词人看来，毕竟“春意知几许”，还远不是很浓郁的。虽是“元宵佳节”，“融和天气”，可是这些年来国事的变化，身世的坎坷，使得女词人产生了“物是人非”、“好景不常”之感。所以在“融和天气”之后，立即指出“次第岂无风雨”的可能，在淡淡的春意中又掺进了浓浓的隐忧。以上三小节结构相类，都是两个四字句，是实写，写客观景色的宜人，紧接着一个问句，反衬出主观的不同感受。归结到本篇的主题：身逢佳节，天气虽好，却无心赏玩。因此，虽然有“酒朋诗侣”用“香车宝马”来邀请她去观灯赏月，也只好婉言辞谢了。表面上的理由是怕碰上“风雨”，实际是国难当前，早已失去了赏灯玩月的心情。如果是在太平盛世的当年，情况就大不相同了。这样，诗人很自然地转到当年汴京欢度节日的回忆上来。\n\n　　词的下片着重用作者南渡前在汴京过元宵佳节的欢乐心情，来同当前的凄凉景象作对比。“中州”指北宋都城汴京，即今河南省开封市；“三五”，指正月十五日，即元宵节。当时宋王朝为了点缀太平，在元宵节极尽铺张之能事。据《大宋宣和遗事》记载，“从腊月初一直点灯到正月十六日”，真是“家家灯火，处处管弦”。其中提到宣和六年正月十四日夜的景象：“京师民有似云浪，尽头上带着玉梅、雪柳、闹蛾儿，直到鳌山看灯。”孟元老《东京梦华录》“正月十六日”条也有类似的记载。这首词里的“铺翠冠儿，捻金雪柳，簇带争济楚”，写的正是作者当年同“闺门”女伴，心情愉快，盛装出游的情景。全是写实，并非虚构。可是，好景不常，金兵入侵，自己只落得飘流异地。如今人老了，憔悴了，白发蓬乱，虽又值佳节，又哪还有心思出外游赏呢？“不如向，帘儿底下，听人笑语”，更反衬出词人伤感孤凄的心境。\n\n　　这首词不仅情感真切动人，语言也很质朴自然。作者在这首词的下片中，无论是用当年在汴京赏灯过节来作今昔对比也好，还是用今天的游人的欢乐来反衬自己的处境也好，都能更好地刻划出诗人当前的凄凉心情。真是语似平淡而实沉痛已极。更多李清照宋词赏析请关注诗词库的李清照专栏。\n\n　　这首词运用今昔对照与丽景哀情相映的手法，还有意识地将浅显平易而富表现力的口语与锤炼工致的书面语交错融合，以极富表现力的语言写出了浓厚的今昔盛衰之感和个人身世之悲。这首词的艺术感染力如此之强，以至于南宋著名词人刘辰翁会每诵此词必“为之涕下”。', poem_tags = '古诗三百首,宋词精选,伤今追昔,元宵节' WHERE poem_title = '永遇乐·落日熔金' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '楼阁倚在经霜的树林外，天空如明镜无纤云一毫。\n峻拔的南山与清爽秋色，气势互不相让两两争高？', poem_notes = '秋望：在秋天远望。\n倚：靠着，倚立。霜树：指深秋时节的树。外：之外。指楼比“霜树”高。\n镜天：像镜子一样明亮、洁净的天空。无一毫：没有一丝云彩。\n南山：指终南山，在今陕西西安南。秋色：晴高气爽的天空。\n气势：气概。喻终南山有与天宇比高低的气概。', poem_appreciation = '这是一曲高秋的赞歌。题为“长安秋望”，重点却并不在最后的那个“望”字，而是赞美远望中的长安秋色。“秋”的风貌才是诗人要表现的直接对象。\n\n　　首句点出“望”的立足点。“楼倚霜树外”的“倚”，是倚立的意思，重在强调自己所登的高楼巍然屹立的姿态；“外”，是“上”的意思。秋天经霜后的树，多半木叶黄落，越发显出它的高耸挺拔，而楼又高出霜树之上，在这样一个立足点上，方能纵览长安高秋景物的全局，充分领略它的高远澄洁之美。所以这一句实际上是全诗的出发点和基础，没有它，也就没有“望”中所见的一切。\n\n　　次句写望中所见的天宇。“镜天无一毫”，是说天空明净澄洁得象一面纤尘不染的镜子，没有一丝阴翳云彩。这正是秋日天宇的典型特征。这种澄洁明净到近乎虚空的天色，又进一步表现了秋空的高远寥廓，同时也写出了诗人当时那种心旷神怡的感受和高远澄净的心境。\n\n　　“南山与秋色，气势两相高。”第三句转笔写到远望中的终南山。将它和“秋色”相比，说远望中的南山，它那峻拔入云的气势，象是要和高远无际的秋色一赛高低。\n\n　　南山是具体有形的个别事物，而“秋色”却是抽象虚泛的，是许多带有秋天景物特点的具体事物的集合与概括，二者似乎不好比拟。而此诗却别出心裁地用南山衬托秋色。秋色是很难描写的，它存在于秋天的所有景物里，而且不同的作者对秋色有不同的观赏角度和感受，有的取其凄清萧瑟，有的取其明净澄洁，有的取其高远寥廓。这首诗的作者显然偏于欣赏秋色之高远无极，这是从前两句的描写中可以明显看出的。但秋之“高”却很难形容尽致（在这一点上，和写秋之“凄”、之“清”很不相同），特别是它那种高远无极的气势更是只可意会，难以言传。在这种情况下，以实托虚便成为有效的艺术手段。具体有形的南山，衬托出了抽象虚泛的秋色，诗人通过“南山与秋色，气势两相高”的诗句，不但能具体地表现出“秋色”之“高”，而且写出了它的气势、精神和性格。\n\n　　这首诗的好处，还在于它在写出长安高秋景色的同时写出了诗人的精神性格。它更接近于写意画。高远、寥廓、明净的秋色，实际上也正是诗人胸怀的象征与外化。特别是诗的末句，赋予南山与秋色一种峻拔向上的动态，这就更鲜明地表现出了诗人的性格气质，也使全诗在跃动的气势中结束，留下了充分的想象余地。\n\n　　晚唐诗往往流于柔媚绮艳，缺乏清刚遒健的骨格。这首五言短章却写得意境高远，气势健举，和盛唐诗人王之涣的《登鹳雀楼》有神合之处，尽管在雄浑壮丽、自然和谐方面还不免略逊一筹。', poem_tags = '秋天,地名' WHERE poem_title = '长安秋望' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '喜鹊筑成巢，鳲鸠来住它。这人要出嫁，车队来迎她。\n\n喜鹊筑成巢，鳲鸠占有它。这人要出嫁，车队送走她。\n\n喜鹊筑成巢，鳲鸠住满它。这人要出嫁．车队成全她。', poem_notes = '维：发语词。鹊：喜鹊。有巢：比兴男子已造家室。\n鸠：一说鳲鸠（布谷鸟），自己不筑巢，居鹊的巢。贵州民间传说斑鸠不筑巢，居其他鸟类筑的巢。居：侵占。\n归：嫁。\n百：虚数，指数量多。两：同辆。御（yà）：同“迓”，迎接。\n方：并，比，此指占居。\n将（jiāng）：送。\n盈：满。此指陪嫁的人很多。\n成：迎送成礼，此指结婚礼成。', poem_appreciation = '这是一首描写婚礼的诗。《毛诗序》以此诗为国君之婚礼。朱熹《诗集传》以此诗为诸侯之婚礼。从诗中描写的送迎车辆之盛可以知道，应为贵族的婚礼，而不是一般民间的婚礼。\n\n　　关于此诗诗旨历来争议较大，归纳起来大致有三种观点：\n\n　　一、鹊喻新郎，鸠喻新娘。这个观点又分两种意见：（一）这首诗是诗人代新郎言说，表达了诗人对男子的同情。喜鹊搭好了窝，鸠来居住。新郎准备好了房子，新娘来居住。以鸠居鹊巢比喻女居男室。此说以姚际恒为代表。姚际恒《诗经通论》言：“按此诗之意，其言鹊鸠者，以鸟之异类况人之异类也。其言巢与居者，以鸠之居鹊巢，况女之居男室也。”姚氏之说，尊者甚众。但是清代另一位善说《诗》者方玉润却有着不同的看法。方玉润《诗经原始》辨驳说：“自《序》《传》来，说《诗》者无不以鹊巢鸠居况女居男室矣，夫男女同类也，鹊鸠异物也，而何以为配乎？”意思是说：用鸠居鹊巢比喻女居男室，就像是说鸠婚配给了鹊犹如女嫁给了男。但是男女同类可以婚配，鸠鹊异类又怎么能相配昵？方玉润又说：“姚氏际恒最攻《序》《传》，乃其自解诗意，又以为‘言鹊鸠者，以鸟之异类况人之异类也，其言巢居者，况女之居男室也\'则与旧说何异？且谓\'以鸟之异类况人之异类’，男女纵不同体，而谓之异类可乎哉？此不通之论也。”（二）这首诗是新娘家人在唱赞歌，是一首新婚礼赞诗。如果以鹊喻新郎，以鸠（布谷）喻新娘，则此诗为新婿礼赞诗。朱熹将《鹊巢》的诗旨强解为以鸠比喻文王之化，行后妃之德盛而赞颂之。此一说出现最早，流传最久，影响也最大，而批评者亦最多。这种赞颂文王之化，后妃之德的说法，虽然历来因为牵强附会而被指责为完全是一种背离诗义的经学化理学化的臆断，但是他将这首诗解释为是一首新娘家人赞美婚礼的诗，是值得肯定的。\n\n　　二、鹊喻弃妇，鸠喻新妇，这是一首弃妇诗。如果以鹊喻弃妇，以鸠（布谷）喻新妇，则此诗的作者是代弃妇立言或作者本人就是弃妇，那么这是一首深切沉痛的弃妇诗。弃妇的丈夫遗弃了同他一起艰苦经营，创立家室的结发妻子，却用百辆盛车的热闹场面迎娶新妇，致使新妇占了旧妇之位，恰如”鸠占鹊巢“一般。弃妇心生嫉恨，因作此诗，以责备丈夫另娶新妇，新妇占据其家：我辛辛苦苦终于经营了一个家，现 在丈夫却将我抛弃，用盛大的车队去接新人了，而有个新妇要霸占我的家了。表达了一个为家操劳，却遭丈夫遗弃的妇女内心无比哀怨的心情。《诗经》中这类妇女很多，如《国风·邶风·谷风》。《召南·鹊巢》中这位妇女的遭遇已经成为了一种社会现象，这首诗就是古代毫无话语权的妇女对喜新厌旧的丈夫的指责和对自己悲惨命运的无奈叙述。这实际上也是对男权社会里痴心女子负心汉婚姻现象的一种沉痛控诉，获得了强烈的社会意义。高亨在其《诗经今注》对此表示了相同的看法：”诗以鸠侵占鹊巢比喻新夫人夺去原配夫人的宫室。“同时高亨说：”（这是）召南的一个国君废了原配夫人，另娶一个新夫人，作者写这首诗叙其事，有讽刺的意味。“将这首诗的当事人具体地指为：召南的一个国君和他的两个夫人。\n\n　　三、鹊与鸠并无明确所指，只是自然界的两种鸟，且此诗的叙述者是与婚礼无关的他者。这首诗也可能只是一个与婚礼毫无关系的路人所作，诗人无意中看到一场婚礼，于是有所联想有所感触，便作了此诗。\n\n　　全诗三章，都以鸠居鹊巢起兴。喜鹊筑好巢，鳲鸠住了进去，这是二鸟的天性。《齐诗》曰：“鹊以夏至之月始作室家，鳲鸠因成事，天性然也。”诗中还点明成婚的季节，郑笺云：“鹊之作巢，冬至架之，至春乃成。”这也是当时婚嫁的季节。各章二句写鳲住鹊巢分别用了“居”“方”“盈”三字，有一种数量上的递进的关系。“方”，是比并而住；“盈”，是住满为止。因此诗三章不是简单的重章叠唱。\n\n　　一章“百两御之”，是写成婚过程的第一环，新郎来迎亲。迎亲车辆之多，是说明新郎的富有，也衬托出新娘的高贵。二、三章继续写成婚过程第二、三环：迎回与礼成。“百两将之”是写男方已接亲在返回路上，“百两成之”是迎回家而成婚了。“御”“将”“成”三字就概述了成婚的整个过程。“子之于归”，点明其女子出嫁的主题。因此，三章是选取了三个典型的场面加以概括，真实地传达出新婚喜庆的热闹。仅使用车辆之多就可以渲染出婚事的隆重。\n\n　　这首诗以平浅的语言写成婚的过程，没有如《周南·桃夭》里以桃花来衬托新娘的艳丽，更没有直接去描写新娘的容貌。如果说“之子于归”一句还点出新娘这一主角，让人在迎亲的车队之中找出新娘来，那么，另一位主角新郎则完全隐在诗中场景的幕后，他是否来迎亲，就留给读者去想像了。细味诗中所写，往返的迎亲车队给画面以较强的时空感，短短三章，却回味悠长。', poem_tags = '诗经' WHERE poem_title = '国风·召南·鹊巢' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '清明时节，春光满地，熏风洋洋。 玉炉中的残烟依旧飘送出醉人的清香。 午睡醒来，头戴的花钿落在枕边床上。\n海外的燕子还未归来，邻家儿女们在玩斗草游戏。 江边的梅子已落了，绵绵的柳絮随风荡漾。\n零星的雨点打湿了院子里的秋千，更增添了黄昏的清凉。', poem_notes = '淡荡：和舒的样子。多用以形容春天的景物。\n寒食：节令名。在清明前一二日。相传春秋时，介子推辅佐晋文公回国后，隐于山中，晋文公烧山逼他出来，子推抱树焚死。为悼念他，遂定于是日禁火寒食。\n玉炉：香炉之美称。\n沉水：沉香。\n山枕：两端隆起如山形的凹枕。\n花钿（diàn）：用金片镶嵌成花形的首饰。\n斗草：一种竞采百草、比赛优胜的游戏。\n江梅：梅的一种优良品种，非专指生于江边或水边之梅。\n柳绵：即柳絮。柳树的种子带有白色绒毛，故称。\n秋千：相传春秋时齐桓公由北方山戎引入。一说秋千起于汉武帝时，武帝愿千秋万寿，宫中因作千秋之戏，后倒读为秋千。', poem_tags = '宋词精选,婉约,寒食节,写景,惜春' WHERE poem_title = '浣溪沙·淡荡春光寒食天' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '在这个地方荆轲告别燕太子丹，壮士悲歌壮气，怒发冲冠。\n那时的人已经都不在了，今天的易水还是那样的寒冷。', poem_notes = '易水：也称易河，河流名，位于河北省西部的易县境内，分南易水、中易水、北易水，为战国时燕国的南界。燕太子丹送别荆轲的地点。《战国策·燕策三》：“风萧萧兮易水寒，壮士一去兮不复还。”\n此地：原意为这里，这个地方。这里指易水岸边。\n别燕丹：指的是荆轲作别燕太子丹。\n壮士：意气豪壮而勇敢的人；勇士。这里指荆轲，战国卫人，刺客。\n发冲冠：形容人极端愤怒，因而头发直立，把帽子都冲起来了。冠：帽子。《史记·廉颇蔺相如列传》：“ 相如 因持璧却立，倚柱，怒发上冲冠。”\n昔时：往日；从前。《东观汉记·东平王苍传》：“骨肉天性，诚不以远近亲疏，然数见颜色，情重昔时。”\n人：一种说法为单指荆轲，另一种说法为当时在场的人。\n没：死，即“殁”字。\n水：指易水之水。\n犹：仍然。', poem_appreciation = '该诗描述作者在易水送别友人时的感受，并借咏史以喻今。整首诗寓意深远，笔调苍凉。\n\n　　第一联“此地别燕丹，壮士发冲冠”，道出诗人送别友人的地点。“壮士发冲冠”用来概括那个悲壮的送别场面和人物激昂慷慨的心情，表达了诗人对荆轲的深深崇敬之意。此时在易水边送别友人，想起了荆轲的故事，这是很自然的。但是，诗的这种写法却又给人一种突兀之感，它舍弃了那些朋友交往、别情依依、别后思念等等一般送别诗的常见的内容，而是芟夷枝蔓，直入史事。这种破空而来的笔法，反映了诗人心中蕴蓄着一股难以遏止的愤激之情，借怀古以慨今，把昔日之易水壮别和此刻之易水送人融为一体。从而为下面的抒情准备了条件，酝酿了气氛。\n\n　　第二联“昔时人已没，今日水犹寒”，是怀古伤今之辞，抒发了诗人的感慨。这首诗的中心在第四句，尤其是诗尾的“寒”字，更是画龙点睛之笔，寓意丰富，深刻表达了诗人对历史和现实的感受。“寒”字，寓情于景，以景结情，因意构象，用象显意。景和象，是对客观事物的具体描绘；情和意，是诗人对客观对象在审美上的认识和感受。诗人在自然对象当中，读者在艺术对象当中，发现了美的客观存在，发现了生命和人格的伟大表现，从而把这种主观的情和意，转移到客观的景和象上，给自然和艺术以生命，给客观事物赋予主观的灵魂，这就是诗歌创作和欣赏当中的“移情作用”。“寒”字正是这种移情作用的物质符号，这是此诗创作最为成功之处。诗人于易水岸边送别友人，不仅感到水冷气寒，而且更加觉得意冷心寒。诗人在“前不见古人，后不见来者”的伟大孤独中，只好向知心好友倾诉难酬的抱负和无尽的愤懑。诗人感怀荆轲之事，既是对自己的一种慰藉，也是将别时对友人的一种激励。这首诗题为送别，可又没有交待所别之人和所别之事，但“慷慨倚长剑，高歌一送君”的壮别场景如在眼前。所咏的历史本身就是壮别，这同诗人送友在事件上是相同的。而古今送别均为易水河岸，在地点上也是相同的。这两句诗是用对句的形式，一古一今，一轻一重，一缓一急，一明一暗，两条线索，同时交待，易水跨越古今，诗歌超越了时空，最后统一在“今日水犹寒”的“寒”字上，全诗融为一体。既是咏史又是抒怀，充分肯定了古代英雄荆轲的人生价值，同时也倾诉了诗人的抱负和苦闷，表达了对友人的希望。诗的构思是极为巧妙的。\n\n　　从诗题上看这是一首送别诗，从诗的内容上看这又是一首咏史诗。这首诗题目虽为“送人”，但它并没有叙述一点朋友别离的情景，也没有告诉读者送的是何许人。然而那所送之人，定是肝胆相照的至友。因为只有这样，诗人才愿意、才能够在分别之时不可抑制地一吐心中的块垒，而略去一切送别的常言套语。骆宾王长期怀才不遇，佗傺失志，身受迫害，爱国之志无从施展。他在送别友人之际，通过咏怀古事，表达对古代英雄的仰慕，也寄托自己对现实的深刻感慨，倾吐了自己满腔热血无处可洒的极大苦闷。全诗以强烈深沉的感情，含蓄精炼的手法，摆脱了初唐委靡纤弱的诗风影响，标志着唐代五言绝句的成熟，为唐诗的健康发展开拓了道路。', poem_tags = '咏史怀古,送别,地点' WHERE poem_title = '于易水送人 / 于易水送别' AND poem_author = '骆宾王';
UPDATE edu_poem SET poem_translation = '月光照在波光粼粼的河面上，天空中有几丝淡淡的云彩。白色的马儿此时尚气宇昂扬，我却不胜酒力，在河边下马，等不及解下马鞍，就想倒在这芳草中睡一觉。\n这小河中的清风明月多么可爱，马儿啊可千万不要踏碎那水中的月亮。我解下马鞍作枕头，斜卧在绿杨桥上进入了梦乡，听见杜鹃叫时，天已明了。', poem_notes = '西江月：词牌名。\n蕲水：水名，流经湖北蕲春县境，在黄州附近。\n弥弥：水波翻动的样子。\n层霄：弥漫的云气。\n障泥：马鞯，垂于马两旁以挡泥土。玉骢：良马。骄：壮健的样子。\n可惜：可爱。\n琼瑶：美玉。这里形容月亮在水中的倒影。\n杜宇：杜鹃鸟。', poem_appreciation = '这是一首寄情山水的词。作者在词中描绘出一个物我两忘、超然物外的境界，把自然风光和自己的感受融为一体，在诗情画意中表现自己心境的淡泊、快适，抒发了他乐观、豁达、以顺处逆的襟怀。\n\n　　小序叙事简洁，描写生动，短短五十四字，即写出地点、时间、景物以及词人的感受。它充满了诗情画意，是一篇写得很优美的散文，可与其《记承天寺夜游》媲美。\n\n　　上片头两句写归途所见：“照野弥弥浅浪，横空隐隐层霄。”弥弥，是水盛的样子；层霄，即层云。春夜，词人在蕲水边骑马而行，经过酒家饮酒，醉后乘着月色归去，经过一座溪桥。由于明月当空，所以才能看见清溪在辽阔的旷野流过。”先说“照野”，突出地点明了月色之佳。用“弥弥”形容“浅浪”，就把春水涨满、溪流汩汩的景象表现出来了。广阔的天空还有淡淡的云层。“横空”，写出了天宇之广。说云层隐隐约约在若有若无之间，更映衬了月色的皎洁。野外是广袤的，天宇是寥廓的，溪水是清澈的。在明月朗照之下的人间仙境中，诗人忘却了世俗的荣辱得失和纷纷扰扰，把自己的身心完全融化到大自然中。此两句暗写月光。\n\n　　“障泥未解玉骢骄”，是说那白色的骏马忽然活跃起来，提醒他的主人：要渡水了！障泥，是用锦或布制作的马荐，垫在马鞍之下，一直垂到马腹两边，以遮尘土。《晋书·王济传》：“济善解马性，尝乘一马，著连乾障泥，前有水，终不肯渡。济曰：‘此必是惜障泥。’使人解去，便渡。”词人在这里只是写了坐骑的神态，便衬托出濒临溪流的情景。把典故融化于景物描写之中，这是很成功的一个例子。此时，词人不胜酒力，从马上下来，等不及卸下马鞍鞯，即欲眠于芳草。“我欲醉眠芳草”，既写出了浓郁的醉态，又写了月下芳草之美以及词人因热爱这幽美的景色而产生的喜悦心情，可以说收到了一石三鸟的效果。\n\n　　过片二句，明写月色，描绘从近处观赏到的月照溪水图，更进一步抒发迷恋、珍惜月色之佳的心情：“可惜一溪风月，莫教踏碎琼瑶”。“溪”作一个量词，巧妙又无痕地把风，月与溪融为一体，并洗去了风尘世俗之感。琼瑶，是美玉，这里比做皎洁的水上月色。可惜，是可爱的意思。微风轻轻吹拂，溪中波光粼粼，水月交辉，真像缀了一溪晶莹剔透的珠玉。这里用的修辞手法是“借喻”，径以月色为“琼瑶”。由于感情的挚浓，使比喻的客体升到了突出的地位，因而它的形象显得更鲜明，更生动。这种表现手法是从生活中来的，不背理，更不违情。月色皎洁，加之以醉人痴语，怪不得异想天开，这是“理”；十分珍惜美好的月色，这是“情”。“情理交至”，这就更巧妙地揭开了词人所追求的精神世界的帷幕。这个境界是极为幽美、静谧、纯洁的，如果有一丁点儿外物羼入，就会被损害，被践踏。此句以独特感受和精切的比喻，传神地写出水之清、月之明、夜之静、人之喜悦赞美。\n\n　　“解鞍欹枕绿杨桥”，写词人用马鞍作枕，倚靠着它斜卧在绿杨桥上“少休”。这一觉当然睡得很香，及至醒来，“杜宇一声春晓”，春天的黎明又是一番景色了。这个结尾如空谷传声，余音不绝。妙在又将展现一幅清新明丽的画卷，却留下空白，让读者自己用丰富的联想去感受它。作者在词中不去写“乱山攒拥，流水锵然”的景致，而是通过描写杜鹃在黎明的一声啼叫，把野外春晨的景色作了画龙点睛的提示。这是因为他是从杜鹃啼叫声中醒过来的，由杜鹃之啼才首先感到这空山月明、万籁俱寂的春晨之美。词人真实地记录了他第一次难忘的感受，因而也就给读者留下了第一次动人的印象。\n\n　　此词所描绘的富有诗情画意的美景中，处处有“我”之色彩，景物成为塑造“我”的典型性格的凭据。词人不论是醉还是醒，是月夜还是春晨，都能“无入不自得”，随意而成趣，逐步展示词的意境。作者善于把意和境浑然凝结为一个不可分割的整体，他把自己的身心完全融化到大自然中，忘却了世俗的荣辱得失和纷纷扰扰，表现了自己与造化神游的畅适愉悦，读来回味无穷，令人神往。', poem_tags = '宋词三百首,豪放,山水,月色,喜悦,散文' WHERE poem_title = '西江月·顷在黄州' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '秋风劲吹，洞庭湖水似乎衰老了许多，一夜愁思，湘君也应多了白发。\n醉后忘却了水中的星辰只是倒影，清朗的梦中，我卧在天河上。', poem_notes = '龙阳县：即今湖南汉寿。\n青草湖：位于洞庭湖的东南部，因湖的南面有青草山而得名。“青草湖”与洞庭湖一脉相连，所以，诗中又写成了“洞庭湖”。\n湘君：尧的女儿，舜的妃子，死后化为湘水女神。\n天在水：天上的银河映在水中。', poem_appreciation = '一、二两句，诗人由对眼前自然景色的深广感受而引起对神话中人的向往，借以对神话的幻想，反映出是时境界的逐渐深入。“西风吹老洞庭波，一夜湘君白发多。”诗中境界由一“老”字带起。秋风飒飒，洞庭湖水渺渺茫茫。那景象，与春日轻漾宁静的碧水相较，是和乐世间另一面的深邃的人生。诗人所思所忆渐渐入深。所思所悟如何细言，唯有诉付对白发湘君的神往，那江山与人生的化境，即是这般深沉了！传说湘君闻帝舜死于苍梧之野，追随不及，啼竹成斑，那宿命却如何可及呢？此夜洞庭可老，湘君如约此等情境，复能何言？这等思悟境界深广，洞庭深广的秋色可谓遇到了知音。思绪沉沉，竟至幻象，昼晓和乐尘世，此夜却换了人间。以神抒情，寄思于景，至幻乃深。\n\n　　“醉后不知天在水，满船清梦压星河。”秋风已久，赏景渐忘景，不分是天上星、水中星？夜深思量长，怎知何时已醉？昔杜甫心怀长安，所目疮痍，“春水船如天上坐”，但悲其生不能已，故无缘这般深然长醉、安然入梦。泊舟、泊梦，天河或曰星河，景中或曰境中，所思或曰所忘。诗人的梦境，满船清梦，是诗人思量着的人生。然而，秋湖相往来，物我无碍，陶然自在，正是快哉。一二句亦真亦幻，愈是明了，愈是痴然；三四句境中心中，却深沉了，方潇洒了。所以，境界深了，夜即梦了，此真人生佳境也。', poem_tags = '写景,叙梦,纪游' WHERE poem_title = '题龙阳县青草湖' AND poem_author = '唐珙';
UPDATE edu_poem SET poem_translation = '砍伐檀树声坎坎啊，棵棵放倒堆河边啊，河水清清微波转哟。不播种来不收割，为何三百捆禾往家搬啊？不冬狩来不夜猎，为何见你庭院猪獾悬啊？那些老爷君子啊，不会白吃闲饭啊！\n砍下檀树做车辐啊，放在河边堆一处啊。河水清清直流注哟。不播种来不收割，为何三百捆禾要独取啊？不冬狩来不夜猎，为何见你庭院兽悬柱啊？那些老爷君子啊，不会白吃饱腹啊！\n砍下檀树做车轮啊，棵棵放倒河边屯啊。河水清清起波纹啊。不播种来不收割，为何三百捆禾要独吞啊？不冬狩来不夜猎，为何见你庭院挂鹌鹑啊？那些老爷君子啊，可不白吃腥荤啊！', poem_notes = '坎坎：象声词，伐木声。\n寘：同“置”，放置。\n干：水边。\n涟：即澜。\n猗（yī）：义同“兮”，语气助词。\n稼（jià）：播种。\n穑（sè）：收获。\n胡：为什么。\n禾：谷物。\n三百：意为很多，并非实数。\n廛（chán）：通“缠”，古代的度量单位，三百廛就是三百束。\n狩：冬猎。猎，夜猎。此诗中皆泛指打猎。\n县（xuán）：通“悬”，悬挂。\n貆（huán）：猪獾。也有说是幼小的貉。\n君子：此系反话，指有地位有权势者。\n素餐：白吃饭，不劳而获。\n辐：车轮上的辐条。\n直：水流的直波。\n亿：通“束”。\n瞻：向前或向上看。\n特：三岁大兽。\n漘（chún）：水边。\n沦：小波纹。\n囷（qūn）：束。一说圆形的谷仓。\n飧（sūn）：熟食，此泛指吃饭。', poem_appreciation = '全诗充满了劳动者对统治者的讽刺和对社会现实不公的斥责。三章诗重叠，意思相同，按照诗人情感发展的脉络可分为三层：\n\n　　第一层写伐檀造车的艰苦劳动。头两句直叙其事，第三句转到描写抒情，这在《诗经》中是少见的。当伐木者把亲手砍下的檀树运到河边的时候，面对微波荡漾的清澈水流，不由得赞叹不已，大自然的美令人赏心悦目，也给这些伐木者带来了暂时的轻松与欢愉，然而这只是刹那间的感受而已。由于他们身负沉重压迫与剥削的枷锁，又很自然地从河水自由自在地流动，联想到自己成天从事繁重的劳动，没有一点自由，从而激起了他们心中的不平。\n\n　　因此接着第二层便从眼下伐木造车想到还要替剥削者种庄稼和打猎，而这些收获物却全被占去，自己一无所有，愈想愈愤怒，愈无法压抑，忍不住提出了严厉责问：“不稼不穑，胡取禾三百廛兮？不狩不猎，胡瞻尔庭有县貆兮？”\n\n　　第三层承此，进一步揭露剥削者不劳而获的寄生本质，巧妙地运用反语作结：“彼君子兮，不素餐兮！”，对剥削者冷嘲热讽，点明了主题，抒发了蕴藏在胸中的反抗怒火。\n\n　　此篇三章复沓，采用换韵反复咏叹的方式，不但有利地表达伐木者的反抗情绪，还在内容上起到补充的作用，如第二、三章“伐辐”“伐轮”部分，在点明了伐檀是为造车之用的同时，也暗示他们的劳动是无休止的。另外各章猎物名称的变换，也说明剥削者对猎取之物无论是兽是禽、是大是小，一概毫不客气地据为己有，表现了他们的贪婪本性。全诗直抒胸臆，叙事中饱含愤怒情感，不加任何渲染，增加了真实感与揭露的力量。另外诗的句式灵活多变，从四言、五言、六言、七言乃至八言都有，纵横错落，或直陈，或反讽，也使感情得到了自由而充分的抒发，称得上是最早的杂言诗的典型。', poem_tags = '古诗三百首,诗经,抒情' WHERE poem_title = '伐檀' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '邴原从小就失去父亲，几岁时，从书塾经过就哭起来了，书塾的老师问他说：“孩子，你为什么哭泣？”邴原答道：“孤儿容易悲哀，穷人容易感伤。凡是能够学习的人，都是些有父母的孩子。我一来羡慕他们有父亲，二来羡慕他们能够上学。内心感到悲伤，所以就哭了。”老师为他感到悲伤，说：“你想要读书吗？”邴原说：“我没有钱支付学费。”老师说：“孩子你如果有志向，我传授你知识，不收学费。”于是邴原就开始读书。只过了一个冬天，就已能背诵《孝经》《论语》。\n\n译文二\n邴（bǐng）原是三国魏国人。小时候，他经过学堂，听到清脆响亮的读书声，于是忍不住哭泣。老师说：“小孩子你因为什么哭啊？”他说：“凡是能入学堂学习的人，都有父母。”老师询问他的缘故，邴原说：“我小时候就失去了父母。一是羡慕他们不是孤儿，二是羡慕他们能够学习，我心中十分悲伤，所以才哭泣。”老师哀伤了很久，说：“如果你想要学习，不需要付学费。”邴原于是进入学堂学习，最终成为了国家杰出的人才。\n\n译文三\n邴原小的时候就失去父亲，几岁时，从书塾经过就开始哭，书塾的老师问他说：“孩子，你为了什么哭？”邴原回答说：“凡是能够读书的人，都是一些有父母的孩子。我第一羡慕他们有父母亲，第二羡慕他们能够上学。内心感到十分悲伤，所以就哭了。”老师哀怜地说:“孩子如果你想学（我传授你知识）不收学费。”', poem_notes = '书舍：书塾。\n中心：内心里。\n恻然：怜悯，同情。\n国士：国家杰出的人才。\n就学：开始学习。\n何以：为什么。\n少孤：年少失去父亲。\n就书：上书塾（读书）。\n孤：幼年丧失父母。\n过：经过。\n泣：小声哭。\n恻：心中悲伤。\n亲：父母。\n羡：羡慕。\n其：他们，指代书舍里的学生。\n得：能够。\n中心：内心里\n感：伤感。\n伤：悲哀。\n苟：如果，要是。\n愿：仰慕。\n书：学习。\n徒：白白的，此处指不收费。\n资：费用。\n遂：就。\n卒：终于是。\n诵：背诵。\n就：靠近，此处指就书，即上学。\n凡：凡是。\n以：用。\n故：原因；缘由。', poem_tags = '小学文言文,寓言,故事,学习,哲理' WHERE poem_title = '邴原泣学' AND poem_author = '礼赞';
UPDATE edu_poem SET poem_translation = '兔网结得紧又密，布网打桩声声碎。武士气概雄赳赳，是那公侯好护卫。\n\n兔网结得紧又密，布网就在叉路口。武士气概雄赳赳，是那公侯好帮手！\n\n兔网结得紧又密，布网就在林深处。武士气概雄赳赳。是那公侯好心腹！', poem_notes = '肃肃(suō)：整饬貌，密密。罝（jū 居）：捕兽的网。\n椓（zhuó 浊）：打击。丁丁（zhēnɡ 争）：击打声。布网捕兽，必先在地上打桩。\n赳赳：威武雄健的样子。\n公侯：周封列国爵位（公、侯、伯、子、男）之尊者，泛指统制者。干：盾牌。城：城池。干城，比喻捍卫者。\n逵（kuí 魁）：九达之道曰“逵”。中逵，即四通八达的路叉口。\n仇（qiú 求）：通“逑”。\n林：牧外谓之野，野外谓之林。中林，林中。\n腹心：比喻最可信赖而不可缺少之人。', poem_appreciation = '从首章的“肃肃兔罝，椓之丁丁”，到二章、三章的“施于中逵”、“施于中林”，虽皆为“兴语”，其实亦兼有直赋其事的描摹之意，一场紧张的狩猎就将开始。“兔”解为“兔子”自无不可，但指为“老虎”似更恰当。“周南”江汉之间，本就有呼虎为“於菟”的习惯。那么，这场狩猎所要猎获的对象。就该是啸声震谷的斑斓猛虎了！正因为如此，猎手们所布的“兔罝”，结扎得格外紧密，埋下的网桩，也敲打得愈加牢固。“肃肃”，既有形容布网紧密之义，但从出没“中逵”、“中林”的众多狩猎战士说，同时也表现着这支队伍的“军容整肃”之貌。“丁丁”摹写敲击网“椓”的音响，从路口、从密林四处交汇，令人感觉到它们是那样恢宏，有力。而在这恢宏有力的敲击声中，又同时展示着狩猎者振臂举锤的孔武身影。\n\n　　从诗中所咏看，狩猎战士围驱虎豹的关键场景还没有展开，就突然跳向了对“赳赳武夫”的热烈赞美。但被跳过的狩猎场景，其实是可由读者的丰富想像来补足的。《郑风·大叔于田》就曾描摹过“火烈具举，襢裼暴虎（袒胸手搏猛虎）”的惊险场面，以及“叔善射忌，又良御（车）忌，抑磬控忌（忽而勒马），抑纵送忌（忽而纵驰）”的追猎猛兽情景。这些，都可在此诗兴语的中断处，或热烈赞语的字行间想见。而且由猎手跳向“武夫”，由“兔罝”跳向“干城”，又同时在狩猎虎豹和沙场杀敌之间，实现了刹那间的时空大转换：这些在平时狩猎中搏虎驱豹的健儿，一旦出现在捍卫国家的疆场之上，将在车毂交错、箭矢纷坠之际，挥戈击退来犯强敌，而巍然难摧如横耸的城墙。于是一股由衷的赞美之情，便突然充溢于诗人胸际，甚至冲口而出，连连呼曰“赳赳武夫，公侯干城（好仇、腹心）”了。\n\n　　诗写得很自豪。在三章相叠的咏唱之中，这种自豪也因了“干城”、“好仇”以至“腹心”的层层推进，而增添了一种神采飞扬的夸耀意味。这对那些“公侯”来说，有这么一些孔武有力之士为其卖命，当然是值得自矜的。但在另外一个方面，对于“春秋无义战”的那个时代来说，甘将一身武艺，售予公侯之家，而以充当他们的“腹心”为荣，就很难说是一件幸事了。《诗经》“国风”中另一些为离乡背井、久役不归或丧身异域，而咽泣、哀号和歌哭的诗作，也许更能透露：在这种夸耀背后，还掩盖着怎样一种广大无际的悲哀。', poem_tags = '诗经' WHERE poem_title = '国风·周南·兔罝' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '行遍天涯，看尽人情。想不到重回故地时，故人已如花飘零。忆当时与她花下别离，相对无言，只有离愁别绪噎胸间，现在只剩绿窗青天如故，却已非当时风景了。\n想在这萤萤孤灯下细诉相思，新人如玉好，旧人无奈向谁边？早知道这世间美丽的东西都不长久，都难长留，明镜空在，何处得照玉颜，恰似花儿飘落，只余空枝残干，显我孤清。', poem_notes = '阅：经历。\n不道：不料。\n如许：像这样。\n绿窗：绿色的纱窗，指女子居所。韦庄《菩萨蛮》：“劝我早归家，绿窗人似花。”\n朱颜：青春年少的容颜。李煜《虞美人》：“雕栏玉砌应犹在，只是朱颜改。”辞镜花辞树。', poem_appreciation = '“阅尽”三句：我早已历尽天涯离别的痛苦，想不到归来时，却看到百花如此零落的情景。三句甚好。天涯离别之苦，不抵时光流逝之悲。加倍写来，意尤深厚。\n\n　　“花底”二句：我跟她，在花底黯然相看，都无一语。绿窗下的芳春，也与天时同样地迟暮了。“无一语”，益觉悲凉。春暮，日暮，象征着情人们年华迟暮。\n\n　　“待把”三句：本来准备在夜阑灯下，细诉别后的相思。可是，一点点新的欢娱，又勾起了无穷的旧恨。三句更着力写迟暮的悲感。当日的别离，辜负了大好芳春，这千丝万缕的怨恨是无法消除的。\n\n　　最 是”二句：在人世间最留不住的是：那在镜中一去不复返的青春和离树飘零的落花。“辞镜”二字新，有点铁成金之妙。两“辞”字重用亦佳。', poem_tags = '写景,离别,相思' WHERE poem_title = '蝶恋花·阅尽天涯离别苦' AND poem_author = '王国维';
UPDATE edu_poem SET poem_translation = '我离家外出去远行，无论到哪里，都会敞开宽阔的胸怀。我们要乐观旷达，心里不要难受悲哀。\n世上的大事、国家的大事，是很难从没有过错中成功的，就连高官达贵也不是天生得来。\n回想广东那轰轰烈烈的禁烟抗英，我蔑视英国侵略者。从今以后，我将游历祖国大地，观察形势，数历山川。\n不要理会那般人幸灾乐祸、冷嘲热讽，鄙弃那些“赵老送灯台”之类的混话。\n\n我能力低微而肩负重任，早已感到精疲力尽。一再担当重任，以我衰老之躯，平庸之才，是定然不能支撑了。\n如果对国家有利，我将不顾生死。难道能因为有祸就躲避、有福就上前迎受吗？\n我被流放伊犁，正是君恩高厚。我还是退隐不仕，当一名成卒适宜。\n我开着玩笑，同老妻谈起《东坡志林》所记宋真宗召对杨朴和苏东坡赴诏狱的故事，说你不妨吟诵一下“这回断送老头皮”那首诗来为我送行。', poem_notes = '立：成。\n三岛：指英伦三岛，即英国的英格兰、苏格兰、爱尔兰。此旬回顾抗英经历，足见英国无人。\n九垓（gāi）。九州，天下，这句可能是用古神话中竖亥自东极步行至西极的故事（见《山海经·海外东经》），表示自己将风尘仆仆地走遍各地观察形势。\n儿童：指幼稚无知的人，代指对林则徐被贬幸灾乐祸的人。\n赵老送灯台：即上句的轻薄语。\n衰庸：意近“衰朽”，衰老而无能，这里是自谦之词。\n以：用，去做。\n谪居：因有罪被遣戍远方。\n养拙：犹言藏拙，有守本分、不显露自己的意思。刚：正好。戍卒宜：做一名戍卒为适当。这句诗谦恭中含有愤激与不平。\n山妻：对自己妻子的谦称。故事：旧事，典故。', poem_tags = '爱国,励志' WHERE poem_title = '赴戍登程口占示家人二首' AND poem_author = '林则徐';
UPDATE edu_poem SET poem_translation = '枝条最顶端的木芙蓉花，在山中绽放鲜红的花萼。\n涧口一片寂静杳无人迹，纷纷扬扬独自开了又落。', poem_notes = '辛夷坞（wù）：辋川地名，因盛产辛夷花而得名，今陕西省蓝田县内。坞：周围高而中央低的谷地。\n木末芙蓉花：即指辛夷。辛夷，落叶乔木。其花初出时尖如笔椎，故又称木笔，因其初春开花，又名应春花。花有紫白二色，大如莲花。白色者名玉兰。紫者六瓣，瓣短阔，其色与形似莲花，莲花亦称芙蓉。辛夷花开在枝头，故以“木末芙蓉花”借指。木末：树梢，枝头。芙蓉花：此指辛夷花，因芙蓉花与辛夷花形相似，花色相近。\n萼（è）：花萼，花的组成部分之，由若干片状物组成，包在花瓣外面，花开时托着花瓣。\n涧（jiàn）户：一说指涧边人家；一说山涧两崖相向，状如门户。\n且：又。', poem_appreciation = '辛夷坞，蓝田辋川(今陕西省蓝田县内)风景胜地，王维辋川别业(别墅)附近。坞，四面高、中部低的小块地方。\n\n　　这首《辛夷坞》是王维《辋川集》诗二十首之第十八首。这组诗全是五绝，犹如一幅幅精美的绘画小品，从多方面描绘了辋川一带的风物。作者很善于从平凡的事物中发现美，不仅以细致的笔墨写出景物的鲜明形象，而且往往从景物中写出一种环境气氛和精神气质。\n\n　　“木末芙蓉花，山中发红萼。”木末，指树杪。辛夷花不同于梅花、桃花之类。它的花苞打在每一根枝条的最末端上，形如毛笔，所以用“木末”二字是很准确的。“芙蓉花”，即指辛夷，辛夷含苞待放时，很象荷花箭，花瓣的颜色也近似荷花。裴迪《辋川集》和诗有“况有辛夷花，色与芙蓉乱”的句子，可用来作为注脚。诗的前两句着重写花的“发”。当春天来到人间，辛夷在生命力的催动下，欣欣然地绽开神秘的蓓蕾，是那样灿烂，好似云蒸霞蔚，显示着一派春光。诗的后两句写花的“落”。这山中的红萼，点缀着寂寞的涧户，随着时间的推移，最后纷纷扬扬地向人间洒下片片落英，了结了它一年的花期。短短四句诗，在描绘了辛夷花的美好形象的同时，又写出了一种落寞的景况和环境。\n\n　　王维写辋川诗时是在晚年，即安史之乱以前。自唐玄宗开元二十四年(736)张九龄罢知政事，李林甫一派反动势力上台，朝政黑暗，社会矛盾日趋尖锐。王维虽然在朝，他倾向于张九龄的开明政治，对现实十分不满而又无能为力，内心矛盾，产生退隐归田的思想而又恋于禄位。他于是先后在长安附近的终南山和辋川建立别墅，过着亦仕亦隐的生活。\n\n　　辋川诗以田园山水为题材，描绘自然优美的景色，表现幽静的境界，但其中也有一些寄慨，透露了作者内心的苦闷。如：“来者复为谁，空悲昔人有”(《孟城坳》)，“上下华子冈，惆怅情何极”(《华子冈》)。特别是紧接《辛夷坞》之后的《漆园》的“偶寄一微官，婆娑数株树”就更为感伤了。《世说新语》第二十八：“桓玄败后，殷仲文还为大司马咨议，意似二三，非复往日。大司马府听(厅)前，有一老槐，甚扶疏。殷因月朔，与众在听（厅），视槐良久，叹曰：‘槐树婆娑，复无生意’”。王维暗用此事，表达其政治上的苦闷和内心的矛盾。这首《辛夷坞》与《漆园》诗意互有联系，它是以花在无人的山涧自开自落的可悲命运，寄托自己才能被压抑埋没的感伤情绪，有一定现实意义。全诗用比的手法，有优美生动的形象和乐府民歌的韵味，诗意极其含蓄。宋人方回认为此诗是辋川诗中的佳篇，“有一唱三叹不可穷之妙”(《瀛奎律髓》)。我想，其妙不在“幽极”，应在它的精巧寓意。', poem_tags = '田园,写花' WHERE poem_title = '辛夷坞' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '九月九日重阳佳节，我勉强登上高处远眺，然而在这战乱的行军途中，没有谁能送酒来。我心情沉重地遥望我的故乡长安，那菊花大概傍在这战场零星的开放了。', poem_notes = '九日：指九月九日重阳节。\n强：勉强。\n登高：重阳节有登高赏菊饮酒以避灾祸的风俗。\n怜：可怜。\n傍：靠近、接近。', poem_appreciation = '重阳节登高是古已有之的风俗。王维说“独在异乡为异客，每逢佳节倍思亲“。因登高而引发出深沉的乡思，写得诚挚感人，但这单纯的思亲情绪毕竟围绕一己的身世，境界算不得宽阔。岑参这首诗则不然。首句便说“强欲登高去“，“登高去“，还见出逢场作戏的味道，而前面冠以“强欲“二字，其含意便深刻得多了。两个字表现出强烈的无可奈何的情绪。强，是勉强，是不愿为之而又不得不为之的心态体现。“强欲登高“，结合题目“思长安故园“来看，是流露出浓郁的思乡情绪，但“长安“不仅是故园，更是诗人生活了多年的帝都。而它，竟被安、史乱军所占领。在这种特定情境之下，诗人又怎能有心思去过重阳节，去登高胜赏呢?这首诗原有小注说:“时未收长安“。长安被安、史攻陷，在天宝十五年(756)六月，其收复在肃宗至德二年(757)九月。诗题言“行军九日“，当是指他在至德元年(756)随军扈从肃宗自灵武至彭原的行军途中过重阳节。典型的环境，使诗人登高时的心情愈趋复杂，既思故园，更思帝都，既伤心，更感慨，两种感情交汇撞击着他的心房。\n\n　　既是“登高“，诗人自然联想到饮酒、赏菊。据说陶渊明“尝九月九日无酒，出宅边菊丛中坐。久之，逢弘(指江州刺史王弘)送酒至，即便就酌，醉而后归“。陶潜居宅，有人送酒。诗人行军在外，自然没有这个福分。所以，“无人送酒来“句，实际上是在写旅况的凄凉萧瑟，无酒可饮，更无菊可赏。他想到故园今日黄花堆积的情景，只能遥遥寄去一片深沉的乡情。“遥“字，渲染出诗人与长安的相距之远。“怜“字，不仅写出诗人对故乡之菊的眷恋，更写出诗人对故园之菊开在战场上的长长叹息，百般怜惜。“应傍战场开“，沈德潜说“可悲在战场二字“。残垣断壁，战血涂地，黄花开在被乱军糟踏得不成样子的帝都长安岂不可悲可叹!结句把惜花、思乡、感时伤乱的情绪包容在一起加以抒发，所以最为“可悲“。\n\n　　这首诗由欲登高而引出无人送酒的联想，又由无人送酒遥想故园之菊，复由故园之菊而慨叹故园为战场，蝉联而下，犹如弹丸脱手，圆美流转。', poem_tags = '重阳节,登高,思乡,菊花' WHERE poem_title = '行军九日思长安故园' AND poem_author = '岑参';
UPDATE edu_poem SET poem_translation = '漫长的夜啊，故人何在？碧波夜月之下行船。\n天地空旷而茫茫，思乡之情，切切难忘。\n身外的景物没有人的忧愁，清澈的河水也自在流动。\n念及乡愁，离家已是林叶换了多个春秋了，拥着乡愁坐在寂静的夜里，任凭寒露渐生，打湿了衣袖。\n而在此时，还有那江中沙洲上的白鹤，在这暗夜与黎明的分际，乍然长鸣，让人暗暗心惊。', poem_notes = '遥：远。这里指时间漫长。\n天宇：天空。\n露华：露水。', poem_tags = '思念' WHERE poem_title = '西江夜行' AND poem_author = '张九龄';
UPDATE edu_poem SET poem_translation = '从西山路口一直向北走，越过黄茅岭往下走，有两条路：一条向西走，沿着它走过去什么也得不到；另一条稍微偏北而后向东，走了不到四十丈，路就被一条河流截断了，有积石横挡在这条路的尽头。石山顶部天然生成矮墙和栋梁的形状，旁边又凸出一块好像堡垒，有一个像门的洞。从洞往里探望一片漆黑，丢一块小石子进去，咚地一下有水响声，那声音很洪亮，好久才消失。石山可以盘绕着登到山顶，站在上面望得很远。山上没有泥土却长着很好的树木和竹子，而且更显得形状奇特质地坚硬。竹木分布疏密有致、高低参差，好像是有智慧的人特意布置的。\n\n　　唉！我怀疑造物者的有无已很久了，到了这儿更以为造物者确实是有的。但又奇怪他不把这小石城山安放到人烟辐辏的中原地区去，却把它摆在这荒僻遥远的蛮夷之地，即使经过千百年也没有一次可以显示自己奇异景色的机会，这简直是白耗力气而毫无用处，神灵的造物者似乎不会这样做的。那么造物者果真没有的吧？有人说：“造物者之所以这样安排是用这佳胜景色来安慰那些被贬逐在此地的贤人的。”也有人说：“这地方山川钟灵之气不孕育伟人，而唯独凝聚成这奇山胜景，所以楚地的南部少出人才而多产奇峰怪石。”这二种说法，我都不信。', poem_notes = '径北：一直往北。\n逾：越过。\n黄茅岭：在今湖南省零陵县城西面。\n西出：路向西伸去。\n少（shāo）北而东：稍向北又向东去。少，通“稍”。\n土断而川分：土路中断，出现分流的河水。\n横当其垠（yín）：横着挡在路的尽头。\n睥睨（pìnì）：城墙上如齿状的矮墙。\n梁欐（lì）：栋梁，这里指架支着的梁栋。欐，栋，正梁。\n堡坞（wù）：小城堡，此处是指由山石天然形成的。因此作者称其“小石城山”。\n窥：注意，留心。\n洞然：深深的样子。\n激越：声音高亢清远。\n已：停止。\n环：绕道而行。\n望甚远：“望之甚远”的意思。\n箭：指竹子。\n益：特别。\n“其疏数”二句：意思是，那些嘉树美箭，疏密相宜，起伏有致，好像是聪明人精心设置的。数（cù），密。堰（yàn），倒伏。类：好像。\n造物者：指创世上帝。\n愈：更是。\n诚：确实是，的确是。\n“又怪其”四句：意思是说，又奇怪“造物者”不把小石城山安排在中原，反而陈设在这偏僻的蛮夷地区，经历千百年也不能够一展，它的风采，这当然是徒劳而无功用的。中州，中原地区。更，gēng音。售其伎，贡献其技艺，其技艺得到赏识。伎，通“技”。售，出售，这里是显露的意思。\n“神者”二句：意思是，神奇性倘若不该这样，造物者就真的不存在了吧？神者，指神奇性，《易·系辞上》：“阴阳不测之谓神。”傥（tǎng），通“倘”。倘若，或者。不宜，不合适。如是，如此，指“不为之中州，而列是夷狄”的现象。果，真的。\n以慰夫贤而辱于此者：意思是，小石城山是用来慰藉那些贤明却被贬谪到这里的人们的。此句是指有人辩“无用”为“有用”的说法。\n“其气”四句：意思是，那天地间的灵气，在这一带，不造就伟大的人物，却仅仅造就小石城山这样的景物，所以“楚之南”这地方缺少人才而多有石岩。此句是指有人辩“徒劳”为“功劳”的说法。其气之灵，这里指天地的灵气。楚，今湖南、湖北等地，春秋战国时属楚国。少人而多石，指少出贤人而多出奇石。', poem_appreciation = '这篇游记以作者的游踪为线索，记叙了亲身经历的旅途见闻和山川景物，几乎用了一半的篇幅抒发了他贬逐永州后游历自然时触景生情的感慨，这自然构成了文章的写景和议论两段。\n\n　　上段写景。可分两层，先是指明小石城山的方位：“自西山道口径北，逾黄茅岭而下，有二道：其一西出，寻之无所得；其一少北而东，不过四十丈，土断而川分，有积石横当其垠。”反映了作者在永州借游赏自然寻幽探奇。“无所不到”以排遣悠闲时光和怀才不遇的烦忧的精神状态，继而描述小石城山的奇貌；无论是方位的指点还是景观的描绘，都是在循序渐进中进行的，自然景致随着观赏者的游历渐次展现，这样的笔法使本文的景物描写达到了紧凑而自然流畅的效果。同时，也给小石城山的发现笼罩上一层神奇的色彩，增强了文章的吸引力与感染力。随着横亘路头的积石的出现，紧接着以简洁形象的笔墨勾勒了积石二仁呈现的房屋形状及四围像小城的外貌，于是与“石城”之称吻合。此后写石上如门的洞穴，其深邃且有水，可感其幽静；“环之可上，望甚远”，则见其高旷；石上没有土壤，却疏密相间、高昂低伏地生一长着秀美的树木竹子，又显其奇丽。这一段绘声绘色的描述，把石城写得不仅奇美异常，而且生机盎然。柳宗元曾说过：“游之适夕大率有二：旷如也，奥如也。”（《永州龙兴寺东丘记》）登其高，有旷达之感；探其奥，有幽奇之得。小石城山的天然造化、鬼斧神工，实为作者眼中适游的奇妙之地，从而顺理成章地发出了“类智者所施设也”的慨叹。以本句承上启下，第二段对造物者的疑问就不感突兀了。\n\n　　第二段是作者由自然景观带来的联想和思索。作者在这一段里，本意是通过像小石城山这样美好的自然景观却埋没于荒僻之乡，引发对美的事物被压抑、遭遗弃的郁愤之情，并借以抒发贤才遭贬逐的天涯沦落之感，然而却不直抒胸臆。首句由怀疑造物者的有无到“愈以为诚有”，乃是作者的着意之笔，思索由此伸展。文章波澜层出，避免了平铺呆板之病。美好的景观“不为之中州”，反长期沉埋在人迹罕至的僻野，不为人知，不为人用，暗扣柳宗元自己的身世遭际，把自己怀才不遇的感情寄托到被弃置的美丽自然之上，用曲笔表达了身遭贬逐的不平之鸣。至此，由上段的纯景物描写达到了与主观感受的和谐交融。在感慨能向人们呈伎献巧的石头和在艰苦的条件下“益奇而坚”的嘉树秀竹“劳而无用”之后，作者又以推想神者大概不会这么作而提出了造物者“其果无乎”的反问，文章再起波澜。因反问而设答，不说自己借奇石以自慰，却说奇石是造物者安排在这里以安慰那些谪贬到此的贤人；不说自己贬到这荒僻之地的孤单寂寥，唯以自然之石为伍遣怀，却说造物者灵气独钟于石，所以湖南、湖北一带少伟大人物而多奇石。所透出的天涯沦落、同病相怜、孤芳独赏的痛楚愤懑之情就更深一层。最后用“余未信之”作结，既可看作对造物者的否定，更流露了柳宗元渴求摆脱现状以施展才能的希望。最后这一段议论，从字面上看，是由小石城山的景物所发，实际上它抒发了作者被贬永州后内心深处的真实想法。把它们放在永州八记的最后一篇结尾，是作者的精心安排。它表明柳宗元在永州虽然似乎整天游山玩水，饮酒寻乐，实际上内心却充满了矛盾和痛苦；他寄情山水之间，仍在探求真理和正义，这议论是“永州八记”的主旨之所在。', poem_tags = '古文观止,山水,游记,咏物,抒怀' WHERE poem_title = '小石城山记' AND poem_author = '柳宗元';
UPDATE edu_poem SET poem_translation = '驰聘疆场、转战南北是为了报答皇上对我的信任，南北江畔和北方边关的花草都笑我一生忙忙碌碌。一年三百六十日，我都是带着兵器骑着战马在疆场上度过的。', poem_notes = '南北驱驰：戚继光曾在东南沿海一带抗击倭宼的侵扰，又曾镇守北方边关。\n主：指明朝皇帝。\n边月：边塞的月亮。这里的边塞指山东沿海登州卫等地。\n江花边草：南方江边和北方边塞的花草树木。\n横戈：手里握着兵器。', poem_appreciation = '“南北驱驰报主情，江花边草笑平生。”从福建、广东到蓟州，可说一在天南，一在地北。“南北驱驰”四字，概尽戚继光一生大节。“报主情”，并非不喜欢安定的生活，只是心怀天下，为了国家的安宁，不惜万里奔波。全句表现出一种崇高的襟怀。而次句一“笑”字更是意极浑含，写尽了抗倭名将的豪迈气概。为了抗倭事业，一生中到过山清水秀的南方，也到过波涛汹涌的山东海防，行色匆匆间，总无暇顾及周围美好的景色。作者说：江畔紫嫣红的鲜花和江防皎洁明朗的月亮恐怕要笑我不懂得欣赏了吧。\n\n　　“一年三百六十日，都是横戈马上行。”这两句是“平生”、“南北驱驰”的更具体的说明。一个保家卫国的英雄形像跃然纸上，他是紧紧与战马与横戈联在一起，不能须臾分离的。“一年三百六十日”初读似乎是一个凑句，其实很有妙用。它出现在“都是横戈马上行”的点睛之笔的前面，起到了必要的渲染作用，使读者感到，一日横戈马上英勇奋战并不难，难的是三百六十天如一日，更难的是年年如此，“平生”如此。\n\n　　这首诗平易自然，琅琅上口。而作者忠于祖国，热爱人民的高尚品质更让人钦佩。', poem_tags = '古诗三百首,战争,英雄' WHERE poem_title = '马上作' AND poem_author = '戚继光';
UPDATE edu_poem SET poem_translation = '人生道路如此宽广，唯独我没有出路。\n我不愿意追随长安城中的富家子弟，去搞斗鸡走狗一类的赌博游戏。\n像冯谖那样弹剑作歌发牢骚，在权贵之门卑躬屈节是不合我心意的。\n当年淮阴市人讥笑韩信怯懦无能，汉朝公卿大臣嫉妒贾谊才能超群。\n你看，古时燕昭王重用郭隗，拥篲折节、谦恭下士，毫不嫌疑猜忌。\n剧辛和乐毅感激知遇的恩情，竭忠尽智，以自己的才能来报效君主。\n然而燕昭王早就死了，还有谁能像他那样重用贤士呢？\n世路艰难，我只得归去啦！', poem_notes = '羞逐长安社中儿，赤鸡白雉赌梨栗：字面上是说自己耻于像长安的市井小人一般凭着斗鸡小技赌胜微不足道的彩头暗讽唐玄宗在宫内设置斗鸡坊，斗鸡小儿因此而谋得功名富贵。据陈鸿《东城父老传》记载，唐玄宗宠爱一个叫贾昌的斗鸡小孩，给了他极其珍贵的待遇，而且恩宠他达几十年之久。\n弹剑作歌奏苦声：战国时代，冯谖投齐国贵族孟尝君门下为门客，但不受孟尝君的重视，便三番弹剑作歌，抱怨自己得到的待遇太低。曳裾王门：语出《汉书·邹阳传》中的“饰固陋。', poem_appreciation = '“大道如青天，我独不得出。”这个开头与《行路难》的第一首不同。第一首用赋的手法，从筵席上的美酒佳肴写起，起得比较平。这一首，一开头就陡起壁立，让久久郁积在内心里的感受，一下子喷发出来。亦赋亦比，使读者感到它的思想感情内容十分深广。后来孟郊写了“出门如有碍，谁谓天地宽”的诗句，可能受了此诗的启发，但气局比李白差多了。能够和它相比的，还是李白自己的诗，“蜀道之难，难于上青天”这类诗句，大概只有李白那种胸襟才能写得出。不过，《蜀道难》用徒步上青天来比喻蜀道的艰难，使人直接想到那一带山川的艰险，却并不感到文意上有过多的埋伏。而这一首，用青天来形容大道的宽阔，照说这样的大道是易于行路的，但紧接着却是“我独不得出”，就让人感到这里面有许多潜台词。这样，这个警句的开头就引起了人们对下文的注意。\n\n　　“羞逐”以下六句，是两句一组。“羞逐”两句是写诗人的不愿意。唐代上层社会喜欢拿斗鸡进行游戏或赌博。唐玄宗曾在宫内造鸡坊，斗鸡的小儿因而得宠。当时有“生儿不用识文字，斗鸡走狗胜读书”的民谣。如果要去学斗鸡，是可以结交一些纨袴子弟，在仕途上打开一点后门的。但李白对此嗤之以鼻。所以他声明自己羞于去追随长安里社中的小儿。这两句和他在《答王十二寒夜独酌有怀》中所说的“君不能狸膏金距学斗鸡，坐令鼻息干虹霓”是一个意思。都是说他不屑与“长安社中儿”为伍。至于去和那些达官贵人交往，“曳裾王门不称情，弹剑作歌奏苦声。”“曳裾王门”，即拉起衣服前襟，出入权贵之门。“弹剑作歌”，用的是冯谖的典故。冯谖在孟尝君门下作客，觉得孟尝君对他不够礼遇，开始时经常弹剑而歌，表示要回去。李白是希望“平交王侯”的，而现在在长安，权贵们并不把他当一回事，因而使他像冯谖一样感到不能忍受。这两句是写他的不称意。“淮阴市井笑韩信，汉朝公卿忌贾生。”韩信未得志时，在淮阴曾受到一些市井无赖们的嘲笑和侮辱。贾谊年轻有才，汉文帝本打算重用，但由于受到大臣灌婴、冯敬等的忌妒、反对，后来竟遭贬逐。李白借用了韩信、贾谊的典故，写出在长安时一般社会上的人对他嘲笑、轻视，而当权者则加以忌妒和打击。这两句是写他的不得志。\n\n　　“君不见”以下六句，深情歌唱当初燕国君臣互相尊重和信任，流露他对建功立业的渴望，表现了他对理想的君臣关系的追求。战国时燕昭王为了使国家富强，尊郭隗为师，于易水边筑台置黄金其上，以招揽贤士。于是乐毅、邹衍、剧辛纷纷来归，为燕所用。燕昭王对于他们不仅言听计从，而且屈己下士，折节相待。当邹衍到燕时，昭王“拥篲先驱”，亲自扫除道路迎接，恐怕灰尘飞扬，用衣袖挡住扫帚，以示恭敬。李白始终希望君臣之间能够有一种比较推心置腹的关系。他常以伊尹、姜尚、张良、诸葛亮自比，原因之一，也正因为他们和君主之间的关系，比较符合他的理想。但这种关系在现实中却是不存在的。唐玄宗这时已经腐化而且昏庸，根本没有真正的求贤、重贤之心，下诏召李白进京，也只不过是装出一副爱才的姿态，并要他写一点歌功颂德的文字而已。“昭王白骨萦蔓草，谁人更扫黄金台？”慨叹昭王已死，没有人再洒扫黄金台，实际上是表明他对唐玄宗的失望。诗人的感慨是很深的，也是很沉痛的。\n\n　　以上十二句，都是承接“大道如青天，我独不得出”，对“行路难”作具体描写的。既然朝廷上下都不是看重他，而是排斥他，那就只有拂袖而去了。“行路难，归去来！”在当时的情况下，他只有此路可走。这两句既是沉重的叹息，也是愤怒的抗议。\n\n　　篇末的“行路难，归去来”，只是一种愤激之词，只是比较具体地指要离开长安，而不等于要消极避世，并且也不排斥在此同时他还抱有他日东山再起，“直挂云帆济沧海”的幻想。之心，则何王之门不可曳长裾乎”，指游食于王侯之门。不称（chèn）情：不如意', poem_tags = '唐诗三百首,乐府,失意,叹息' WHERE poem_title = '行路难·其二' AND poem_author = '李白';
UPDATE edu_poem SET poem_appreciation = '《从军行》属乐府《相和歌辞·平调曲》。\n\n　　在历代众多《从军行》诗作中，卢思道的这首是传播得较为广泛的。据《古今诗话》载：唐玄宗自巴蜀回，夜登勤政楼就吟咏了本诗中的“庭前奇树已堪攀，塞外征人殊未还”句，可见在唐代这首诗就很受欣赏。\n\n　　古乐府《从军行》大多写军旅生活的艰苦和征人思妇两地相思的痛苦，本篇也是如此。\n\n　　这首诗的前半部是写征战将士英勇奋战，长戍不归的戎马生活。“朔方烽火照甘泉，长安飞将出祁连”，诗篇一开头，便渲染了强烈的战争气氛：北方的烽火接连不断地传来战争的消息，军情紧急，令人担忧。甘泉是西汉的皇宫名，“照甘泉”在这里代指向朝廷报警。“飞将”即西汉著名将领李广。接着，诗中便描绘了这位“长安飞将”的英姿。“犀渠玉剑良家子，白马金羁侠少年”，据《史记·李将军列传》载：“孝文帝十四年，匈奴大入箫关，而广以良家子从军击胡……”“犀渠”是盾的一种。“平明偃月屯右地，薄暮鱼丽逐左贤”，这两句中“右地”指右北平，左贤代指匈奴的重要首领。“平明”和“薄暮”写出了将士们在边塞度过了数不清的日日夜夜。“偃月”和“鱼丽”是古代的两种战阵的名称。这里诗人用了极简炼的文字，生动地写出了将士们紧张的征战生活。“屯右地”“逐左贤”都是李广所为。接下来“谷中石虎经衔箭，山上金人曾祭天”用了两个典故。《史记·李将军列传》中记道：“广出猎，见草中石，以为虎而射之，中石没镞，视之石也。因复更射之，终不能复入石矣。”“山上金人曾祭天”也用的是汉代典故，汉大将霍去病出征西域，获胜，“收休屠祭天金人”。诗人通过这两个典故进一步表现出征匈奴的将士的神威，也正因为有了这些英勇的将士，才取得了战争的胜利。\n\n　　诗的前半部着重塑造了飞将军李广的形象，以李广来代指当时的征战将士，采取了虚中有实，实中有虚的写法，既是赞扬汉代名将李广的业绩，又是当时征战将士生活的写照。把历史和现实揉合在一起。\n\n　　自“天涯一去无穷已”开始，写将士和他们妻子的两地相思。诗从两处落笔，感情转为忧怨。“无穷已”原指路途遥远，这里写出了将士们遥无归期的征战生活。“蓟门”“马岭”“龙城”均为北方的地名，在这里都是虚指。连年的战争使将士家中的亲人，对着遥远的塞北望眼欲穿，但是“庭中奇树已堪攀，塞外征人殊未还”，诗人用衬托的手法写出了战争的长期和残酷。“白雪初下天山外，浮云直上五原间”，五原在今内蒙古包头西北，这里写了亲人们在极寒冷的塞外，远隔千里，因此人们只能发出“关山万里不可越，谁能坐对芳菲月”的叹息。《乐府诗集·横吹曲辞》中有《关山月》曲，《乐府题解》说：“关山月，伤离别也”在写征夫思妇的诗中，常用到关山和月。人们想着万里之外的亲人，谁能独自欣赏那美丽动人的月亮呢?“流水本自断人肠，坚冰旧来伤马骨”既写出了边地将上的生活苦寒，又写出了他们悲切的怨情。“伤马骨”出自陈琳的“饮马长城窟，水寒伤马骨”，冬去春来，在远离故土的异地他乡，将士们度过了多少日日夜夜，“长风萧萧渡水来，归雁连连映天没”雁归而人未归，萧萧长风，行行归雁，蕴含着征夫思妇无限的思乡离情。\n\n　　“从军行，军行万里出龙庭”可说是全诗的总结，龙庭是匈奴祭祀的地方，“出龙庭”在诗中指出征之远。“单于渭桥今已拜，将军何处觅功名。“意思是说匈奴已投降了，将军再到哪里去建功立业呢?言外之意是：边塞的将士总该回来了吧!\n\n　　《诗薮》说“六朝歌行可入初唐者，卢思道《从军行》，薛道衡《豫章行》，音响格调咸自停匀，气体丰神，尤为焕发。”可以说《从军行》影响了唐以来的七言歌行。\n\n　　隋朝统一了分裂三百来年的中国，结束了东晋以来南北对峙的局面。作为隋代的诗人卢思道，在他的诗中，也融会了南朝和北朝的风格，在《从军行》中，既写将士的英勇出征，又写了思妇闺怨，既有“长安飞将出祁连”“白马金羁侠少年”的奔放、雄健，又有“谁能坐对芳菲月”“流水本自断人肠”的清丽、哀怨，南北的风格在卢思道的《从军行》里得到了较和谐的统一。', poem_tags = '乐府,边塞,军旅,生活,相思' WHERE poem_title = '从军行' AND poem_author = '卢思道';
UPDATE edu_poem SET poem_appreciation = '《短歌行》是乐府相和歌平调七曲之一。古乐府中有《长歌行》与《短歌行》之分，关于二者的命意，《乐府解题》有两种说法：一是“言人寿命长短，有定分，不可妄求”；一是“歌声之长短耳，非言寿命也”。在李白之前，以此题为诗者，多为慨叹人生短暂，主张及时行乐。李白的这首诗，却以乐观浪漫、昂扬奋发的精神，在喟叹生命短促的同时，表达了对人生的珍惜，对建功立业的渴望。\n\n　　“白日何短短，百年苦易满。”时间本是个抽象的概念，用“白日”来指代，便成为具体可感的形象了。“短短”两个叠字，强调它稍纵即逝。由时光的流逝，自然联想到人生易老，年华难驻。这样，诗意自然而然地转到对光阴的珍惜。起首两句，貌似平平，实则恰到好处。既开门见山点明题意，又为诗意的拓展预留地步，而且格调质补，语势流走，转承自然。\n\n　　时间永恒，无始无终，漫漫无垠；生命短暂，代谢荣衰，转瞬即逝。诗人正是抓住了这一强烈的反差，进一步驰骋瑰丽神奇的想象。“苍穹浩茫茫，万劫太极长”。上句从“空间”角度极言天宇浩瀚无垠；下句则从“时间”角度感叹光阴的永恒漫长。“万劫太极”，何其久远！在这漫长的岁月里，那曾经见过东海三次变为桑田的麻姑仙女，如今也已两鬓斑白了。这种浪漫的夸张只能出自李白的笔下。据传为汉代东方朔所作的《神异经》里有这么一个故事：东王公常和玉女用箭作投壶游戏，每次要投一千二百支，若未投中，天便开口大笑，这就是下界所见到的电光。如今这种电闪雷鸣已历成千上亿次了。诗人巧妙地把这两个故事融入诗篇，将人们带进奇伟的神仙世界。这里有苍茫的穹宇，人世的兴替，麻姑仙女蝉鬓染霜，天公玉女嬉戏作乐，倏忽又是雷鸣电闪，风雨将至……，多么光怪陆离，神奇而诡谲!这些奇异的境界，极其有力地渲染铺排了“万劫太极长”的内涵。至此，空间的浩渺、时间的无垠，通过诗人大胆而奇特的想象，表达得淋漓尽致。继而，诗人笔锋一转，拓出另一番意境。\n\n　　“吾欲揽六龙，回车挂扶桑。北斗酌美酒，劝龙各一觞。”诗人要揽住为太阳驾车的六条神龙，把太阳所乘之车挂在东方“日出之所”的扶桑树上，用北斗作酒勺盛满美酒，请六龙各饮一杯。这样便会使时光停歇下来，人生似乎便能得以长久。结尾二句道出诗人的意愿：“富贵非吾愿，为人驻颓光。”自古帝王们，即使秦皇、汉武一代雄主，也无不遣人访神仙，求长生，无非为了富贵永久。诗人要揽六龙、回朝日，“使之朝不得回，夜不得伏”，绝非为个人富贵。对他人，为的是“老者不死，少者不哭”（李贺《苦昼短》）；对诗人自己，坚信“天生我材必有用”的李白，他渴望着有朝一日能“申管晏之谈，谋帝王之术”，“使寰区大定，海县清一。”（《代寿山答孟少府移文书》）他要拯物济世，干一番轰轰烈烈的事业，像大鹏一样要“扶摇直上九万里”，即使暂时受挫，也要“犹能簸却沧溟水”（《上李邕》）。这也许就是诗人的弦外之音，味外之旨吧。唐司空图说：“辨于味而后可以言诗”（《与李生论诗书》）。对诗人的意蕴似乎应作如是观。\n\n　　纵观全诗，诗人在驰骋丰富的想象时，把美丽的神话传说融入瑰丽奇伟的艺术境界，塑造出瑰奇壮观，多姿多彩的艺术形象，洋溢着浓郁而热烈的浪漫主义色彩。文辞如行云流水，极富表现力，体现了诗人雄奇奔放，清新飘逸的风格。他以吞吐千古，囊括六合的胸襟和气魄，天马行空般地驰骋想象，从思想到艺术都表现出极大的创造性，在继承借鉴前人的同时作了重大的突破，比如，“北斗酌美酒”就是反用《诗·小雅·大东》“唯北有斗，不可以挹酒浆”的典故。前人的《短歌行》在慨叹人生短促时，往往流露出一种及时行乐，纵情声色的颓废情绪。同样的歌题，在李白的笔下，虽也同样发出“百年苦易满”的叹喟，然而，全诗贯穿的却是乐观浪漫、昂扬奋发的基调。这是诗人的个性及盛唐时代的精神风貌使然。再如，屈原在《离骚》中唱道：“吾令曦和弭节兮，望崦嵫而勿迫”、“折若木以拂日兮，聊逍遥以徜徉”。李白显然对此是有所借鉴的。但同样的素材到他手里，便刻意铺排为新颖、诡谲的艺术境界、包蕴着更为深广的内涵。“真正的创造就是艺术想象力的活动。”（黑格尔语）李白的创作实践证实了这一论断。正如皮日休对他的评价：“言出天地外，思出鬼神表，读之则神驰八极，测之则心怀四溟，磊磊落落，真非世间语者”。李白是当之无愧的。', poem_tags = '人生,时间,惜时' WHERE poem_title = '短歌行' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '入春已经七天了，离开家已经有两年了。\n回家的日子要落在春回大地北飞的雁群之后了，但是想回家的念头却在春花开放以前就有了。', poem_notes = '人日：古代相传农历正月初一为鸡日，初二为狗日，初三为猪日，初四\n为羊日，初五为牛日，初六为马日，初七为人日。\n入春才七日：即人日。把春节当成春天开始，故言“入春”。\n落：居，落在.....后。\n思：思归。传说鸿雁正月从南方返回北方。', poem_appreciation = '这是一首思乡诗。诗的一开头,即以工整的对仗交代了时令及离家的时日。开头二句，诗人淡淡地说出一个事实：“入春才七日，离家已二年”。笔调平淡，似乎不带什么感情，然而低吟之际，就会感觉到一股苦涩的思乡之情弥漫在字里行间。“入春才七日”好像诗人在核对一个事实：今天是正月初七，是新年的第七天。然而一个“才”字，则透露出诗人的满腹心事。诗人正在屈指计日，在作者的主观感受中新年已过去很久了，但是仔细一算，诗人只能不禁失望地说：原来入春才七天呀！——表现出作者对时间缓慢的感慨。“离家已两年”一句也说得平平淡淡，好像不带什么感情，但是将“入春才七日”与“离家已两年”连在一起吟诵细品，可以感觉到一股无可奈何的帐惘之情弥漫在字里行间。诗人在客居生活中过了“春节”，进入了第二年。到了“人日”，入春不过才七天，不能算长。但从旧年到新春，已经跨了两个年头，因而可以说“离家已二年”。“二年”既是客观事实，又是主管感受。将“才七日”和“已二年”作了一个对比，短短的七日已让人难以忍受，离乡两年的岁月又是怎么样熬过去的呢！这两句平淡质朴的诗句中表现出诗人度日如年的心情。\n\n　　后二句说春花未萌发之时，思归之念已经发动。传说鸿雁在正月里从南方飞回北方，因此在后两句中作者借这个传说来抒写自己思归急切的心情。在这个春天到来之前，他就盘算着回乡了，即“思发在花前”；可是现在新的一个春天已到来，眼看着春草将绿，春花将开，成队的鸿雁从头顶掠过，飞回北方，诗人却无法归去，所以说“人归落雁后”。这两句运用了对比手法，以归落在雁后、思生于花前对比。诗人清醒地估计到，不可能很快回去，但只愿落在春来即行北归的大雁之后，不肯把时间设想得再晚一些了，由此可见思归之心切。这两句写得极妙。借用春雁北归之说，抒发极想回归之情，自是联想自然贴切；早已计算归期的思想活动，也极为生动感人。寥寥十字，仿佛能使我们看到诗人翘首北望归雁、屈指计算归期的生动形象；使我们感到他不能与雁同归的遗憾，及极欲早归的焦急心情。一片深沉的乡思之情，就这样形象而委婉地表达出来了。\n\n　　这首五言小诗写出了远在他乡的游子在新春佳节时刻渴望回家与亲人团聚的普遍心理，诗人即景生情，以平实自然、精巧委婉的语言，表达出他深刻细腻的情感体验，把思归盼归之情融入到九曲柔肠之中，景中寓情，情中带景，情景交融。并运用了对比映衬手法，叙述中有对比，含蓄宛转地表达了作者急切的思归之情，而且作者将“归”与“思”分别放在两个相对照的句子中，与题目遥相呼应，别具特色。', poem_tags = '古诗三百首,思乡' WHERE poem_title = '人日思归' AND poem_author = '薛道衡';
UPDATE edu_poem SET poem_translation = '我问这江潮和海水，哪里像郎君的深情和女子的心意。\n男女互相埋怨的时候认为对方不如潮水守时有信，互相思念的时候才发觉海并不算深。', poem_notes = '妾：古时女子的谦称。\n恨：埋怨，不满的情绪。《说文》恨，怨也。', poem_appreciation = '这首词形式与七言绝句相同，本来是白居易的自度曲，“相恨不如潮有信”句诗人化用了李益《江南曲》诗意：“嫁得瞿塘贾，朝朝误妾期。早知潮有信，嫁与弄潮儿。”在中唐当时，官府重商弃农，盐商和珠宝大贾成为一个特殊阶层，“姓名不在县籍中”，“不属州县属天子”，他们牟取暴利，生活豪奢，“商人重利轻离别”、“日日逐利西复东”，故商人妇便更要常受“来去江口守空船”之苦。这首词通过自问自答的形式来写闺情。词人通过对一位复杂微妙的闺中女子内心矛盾的刻画，真实地表现出她对爱情的忠贞和被人抛弃的悲惨境遇。\n\n　　“借问江潮与海水，何似君情与妾心”首二句劈空发问，以水喻情。“江潮”常汹涌而来，倏忽而去，与薄幸人起初热烈却又转瞬即逝的爱情极为相似。大海既深且广，有如思妇对情人的思念。但词中思妇却并不这么看，她认为江和海水不能与自己的情意相比。“相恨不如潮有信，相思始觉海非深”，上二句设问，这两句予以回答。“江潮”纵然倏忽而逝，但它有日日夜夜有来有往，而那负心郎呢？他走后却再没有音信。海水纵然很深，却不及自己对“君”的情意深厚。真是“君心不如潮，妾心深过海”。词以“君心”比“江潮”，以“妾心”比“海水”，十分贴切自然，读之叫人拍手称妙。这首词虽写闺情，却是以欢情来显现，形式清新活泼。', poem_tags = '宋词三百首,妇女,思念,爱情,忠贞' WHERE poem_title = '浪淘沙·借问江潮与海水' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '暮春三月花败又花开，矮矮屋檐下燕子飞走又回来。\n只那眷恋春光的杜鹃鸟仍在夜半悲啼，不相信春风唤不回。', poem_notes = '更：再，重。\n檐：屋檐。\n子规：杜鹃鸟。\n啼血：形容鸟类啼叫的悲苦，一般指杜鹃鸟的啼叫。\n不信：虽则不信，然春去依旧', poem_appreciation = '这是一首写景的七言诗，表现了暮春时节的景象和诗人的感受。诗的前两句写景为主，后两句由景生情，抒发了自己的生活态度和追求。\n\n　　花落了虽又重开，燕子离去了还会回来，然而那眷恋春光的杜鹃，却半夜三更还在悲啼，不相信东风是唤不回来的。\n\n　　诗中的“落更开”描述了三月的花谢了又开，表现了春光未逝；“燕飞来”描述了低矮的屋檐下有燕子飞来飞去，表现了春光生机犹在写出了暮春景象：春光未逝，生机犹存的特点。\n\n　　后两句以拟人的手法来写了杜鹃鸟，塑造了一个执着的形象，借此表现自己留恋春天的情怀，字里行间充满凄凉的美感。\n\n　　东风就是指春风，子规，杜鹃鸟经常在暮春啼叫。\n\n　　诗人用子规夜半犹啼血，不信东风唤不回来表达竭尽全力留住美好时光的意思，既表达珍惜的心情，又显示了自信和努力的态度。表现了自己顽强进取，执着追求美好未来的坚定的信念和乐观的精神。这首诗的子规（杜鹃）与以往大部分诗里借喻哀伤，凄切的含义较不相同，带有比较积极的意义.', poem_tags = '古诗三百首,春天,写景,惜春' WHERE poem_title = '送春 / 春晚' AND poem_author = '王令';
UPDATE edu_poem SET poem_translation = '我年轻的时候带着一万多的士兵、精锐的骑兵们渡过长江时。金人的士兵晚上在准备着箭袋，而我们汉人的军队一大早向敌人射去名叫金仆姑的箭。\n追忆着往事，感叹如今的自己，春风也不能把我的白胡子染成黑色了。我看都把那长达几万字能平定金人的策略，拿去跟东边的人家换换种树的书吧。', poem_notes = '鹧鸪天：词牌名。双调五十五字，押平声韵。\n少年时事：年轻时期的事情。\n壮岁旌旗拥万夫：指作者领导起义军抗金事，当时正二十岁出头。他在《进美芹十论子》里说：“臣尝鸠众二千，隶耿京，为掌书记，与图恢复，共藉兵二十五万，纳款于朝。”壮岁：少壮之时。\n锦襜（chān）突骑渡江初：指作者南归前统帅部队和敌人战斗之事。锦襜突骑：穿锦绣短衣的快速骑兵。襜：战袍。衣蔽前曰“襜”。\n“燕兵”句：意谓金兵在夜晚枕着箭袋小心防备。燕兵：此处指金兵。娖（chuò）：整理的意思。银胡觮（原字为“革”旁加“录”，音lù）：银色或镶银的箭袋。一说娖为谨慎貌，胡觮是一种用皮制成的测听器，军士枕着它，可以测听三十里内外的人马声响，见《通典》。\n“汉箭”句：意谓清晨宋军便万箭齐发，向金兵发起进攻。汉：代指宋。金仆姑：箭名，见《左传·庄公十一年》。\n髭（zī）须：胡子。唇上曰髭，唇下为须。\n平戎策：平定当时入侵者的策略。此指作者南归后向朝廷提出的《美芹十论》《九议》等在政治上、军事上都很有价值的抗金意见书。\n东家：东邻。种树书：表示退休归耕农田。', poem_appreciation = '这首词的上片写的是作者青年时期那段传奇般的出色经历。“壮岁旌旗拥万夫，锦襜突骑渡江初。”上句写作者年青时参加领导抗金义军，曾率领过上万人的队伍；下句写自己率领精锐锦衣骑兵渡江南来。“锦襜突骑”，即穿锦绣短衣的快速骑兵。“燕兵夜娖银胡簶，汉箭朝飞金仆姑。”具体描写南奔时突破金兵防线，和金兵战斗的场面：金兵晚上准备箭筒，修筑工事，而宋兵拂晓便发起了进攻。燕兵，指金兵。“夜娖银胡觮”，夜里整理兵器（准备天明的战斗），侧面说明义军进兵神速，出其不意。娖，通“捉”；胡觮，箭袋。一说，枕着银胡觮而细听之意。娖，谨慎貌；胡觮是一种用皮制成的测听器，军士枕着它，可以测听三十里内外的人马声响，见《通典》。两说皆可通，今取前说。“汉箭”句，指义军用箭攻击金人。金仆姑，箭名，见《左传·庄公十一年》。四句写义军军容之盛和南奔时的紧急战斗情况，用“拥”字、“飞”字表动作，从旌旗、军装、兵器上加以烘托，写得如火如荼，有声有色，极为饱满有力富有感染力。\n\n　　作者回忆青年时代自己杀敌的壮举和抗敌的战斗，豪情壮志溢于笔端，他怀着一片报国之心南渡归宋，满怀希望地打算为宋杀敌建功，但却不被高宗重用，亦不采纳他的平戎之策，长期被闲置不用，使他壮志沉埋，无法一展怀抱。因此在转入下片后，追怀往事，不免深深地叹息：“追往事，叹今吾，春风不染白髭须。”上二句今昔对照，一“追”一“叹”，包含多少岁月，多少挫折；又灵活地从上片的忆旧引出下片的叙今。第三句申明“叹今吾”的主要内容。草木经春风的吹拂能重新变绿，人的须发在春风中却不能由白变黑。感叹青春不再，韶华易逝的可惜，这是一层；白髭须和上片的壮岁对照，和句中的春风对照，又各为一层；不甘心年老，言外有壮志未能彻底湮灭之意，又自为一层。一句中有多层含意，感慨极为深沉。“却将万字平戎策，换得东家种树书”，以最鲜明、最典形最生动的形象，突出作者的理想与现实的尖锐矛盾，突出他一生的政治悲剧，把上一句的感慨引向更为深化、极端沉痛的地步。平戎策，指作者南归后向朝廷提出的《美芹十论》《九议》等在政治上、军事上都很有价值的抗金意见书。上万字的平戎策毫无用处，倒不如向人换来种树书，还有一些生产上的实用价值。这是一种政治现实，对于作者是一种什么样的生活感受，不言而喻。陆游《小园》诗：“骏马宝刀俱一梦，夕阳闲和饭牛歌。”刘克庄《满江红·夜雨凉甚忽动从戎之兴》词中的“生怕客谈榆塞事，且教儿诵《花间集》”和这两句意境相近，也写得很凄凉；但联系作者生平的文韬武略、英雄事迹来看，这两句的悲慨程度还更使人扼腕不已。\n\n　　这首词以短短的五十五个字，深刻地概括了一个抗金名将的悲惨遭遇。上片气势恢宏，下片悲凉如冰，心伤透骨。悲壮对照，悲壮结合，真如彭孙遹《金粟词话》评辛词所说的：“激昂排宕，不可一世”，是作者最出色、最有分量的小令词。', poem_tags = '宋词三百首,豪放,回忆,战争,壮志难酬' WHERE poem_title = '鹧鸪天·有客慨然谈功名因追念少年时事戏作' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '这位老人家七十岁了仍然在卖酒，将上千个酒壶和酒瓮摆放在在花门楼口。\n道路旁的榆荚看起来也很像一串串铜钱，我摘下来用它买酒您可卖否？', poem_notes = '沽：买或卖。首句的“沽”是卖的意思，末句的“沽”是买的意思。\n花门：即花门楼，凉州（今甘肃武威）馆舍名。花门口：指花门楼口。\n榆荚：榆树的果实。春天榆树枝条间生榆荚，形状似钱而小，色白成串，俗称榆钱。', poem_tags = '抒情,生活' WHERE poem_title = '戏问花门酒家翁' AND poem_author = '岑参';
UPDATE edu_poem SET poem_translation = '与金人议和的诏书已经下了十五年，将军不作战白白地来到边疆。\n深广、壮丽的贵族府里按着节拍演歌舞，马棚里的肥马默默死去、弓弦朽断。\n守望岗楼上报更的刁斗催月落，三十岁参军到如今已经白了发。\n从笛声里谁人知道壮士的心思。月亮白白地照射着出征将士的骨头。\n中原一带的战争古代也听说有，但哪有异族统治者能在中原传子传孙？\n沦陷的人民忍痛生存盼复国，今天晚上有多少地方的民众在流泪！', poem_notes = '关山月：乐府旧题，《乐府解题》云“《关山月》，伤离别也”。\n和戎：原意是与少数民族和睦相处，实指宋朝向金人屈膝求安。宋孝宗隆兴元年（1163年）下诏与金人第二次议和，至作者作此诗时，历时为十五年。\n边：边防，边境。\n“朱门”句：红漆大门，借指豪门贵族。沉沉：形容门房庭院深邃。按：击节拍。\n“厩（iù）”句：马棚。肥死：马棚里的马不用，渐渐死去。弓断弦：弓很久不用，绷的弦都断了。\n“戍楼”句：边界上用以守望的岗楼。刁斗：军用铜锅，可以做饭，也可用来打更。\n笛里：指以笛吹奏的曲调声。\n沙头：边塞沙漠之地。征人：出征戍守边塞的战士。\n逆胡传子孙：指金人长期占领中原。金自太宗完颜晟进占中原，至此时已有四世，故云传子孙。又可理解为南宋当今君臣不思恢复。将它留给后代去处理。\n“遗民”句：指金国占领下的中原百姓。恢复：恢复中原故土。', poem_appreciation = '艺术特色 　　《关山月》诗不仅有着深刻的思想，而且有充沛的感情，丰满的形象，生动的描写。具体说来，概括性强，抒情性强，语言精练自然，圆转流畅，是这首诗的特点。同时也可以说是陆游在艺术上的共同特点。这首《关山月》诗的风格是沉郁、苍茫、悲凉、激越的。陆游创造性运用了《关山月》这种古乐府的旧题， “关山月”原来以边塞为题材，抒发从军战士怀人思乡的内心感情。而陆游从和戎下诏的统治集团写到边塞戍楼的战士又写到中原忍死的遗民，诗的内容丰富了，境界扩展了，思想意义也更深刻了。它的风格也不再是一味的低回哀怨而是沉郁苍茫、悲凉激越的了。陆游还相当巧妙地紧扣着关、山、月三个字，去组织材料表现主题，具有高度的概括性和很强的抒情性。关山原是代表边塞的地理特征，防守时总是在山势险峻之处设置关塞。而陆游却突破这一限制，把关山扩大开去，从关山以内写到关山以外。关山以内是后方，那里朱门之内的尽兴的浅斟低唱，无休止地轻歌漫舞。关山本身是前方战士的戍楼，那里有楼内生者的苍苍白发，楼外死者的累累白骨。关山以外，是沦陷区，那里有残暴敌人的干戈屠杀，无辜百姓的血泪酸辛。诗人由近及远，把几方面不同的事物排列在一起，深刻而生动地表现了诗人爱憎的感情、是非观念，形象而具体地揭示出爱国和卖国两条政治路线的尖锐对立，具有高度的概括性和浓郁的抒情性。同时诗人还紧扣“月”字，利用月亮的连续变化，周而复始，来表示时间的推移、季节的转换，这是从纵的方面贯穿和戎诏下十五年的历史。而且月在我们民族的传统中象征着美好的团圆，因此守边的战士见了它抒发怀乡之情；亡国的遗民见了它，牵动故国之思。可是在南宋统治集团看来，这正是烹歌煮酒的良辰美景。同是明月，在不同的政治立场、不同生活处境人们的心目当中，感受不同，反映不同；同是明月照射着朱门的歌舞，照射着前方战士的白发、尸骨，照射着沦陷区遗民的泪痕，而且在十五年来就这么一直照射着。歌舞沉迷，白发益多，尸骨未收，泪痕依旧。借着月光的照射，诗人从历史到现实，把长期和戎不战的政治局面，作了鲜明真切的艺术概括，沉痛悲愤之情充溢于字里行间。诗的语言也晓畅平易，精练自然，没有剑拔弩张惊人的句子，但在客观事实的描述中，却更显出一种摧人泪下、惊心动魄的力量。由此可见，说《关山月》思想性、艺术性达到了高度完美的结合，能代表陆游诗歌的思想艺术特点，是一点也不夸张的。 ▲', poem_tags = '爱国,壮志未酬,悲愤' WHERE poem_title = '关山月' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '江面烟雨迷濛，江边绿草如茵。六朝先后衰亡，宛如南柯一梦。江鸟哀婉啼叫，听来悲悲切切。\n只有台城柳树最是无情，依旧灯笼十里长堤。', poem_notes = '台城：也称苑城，在今南京市鸡鸣山南，原是三国时代吴国的后苑城，东晋成帝时改建。从东晋到南朝结束，这里一直是朝廷台省（中央政府）和皇宫所在地，既是政治中枢，又是帝王荒淫享乐的场所。\n霏霏：细雨纷纷状。\n六朝：指吴、东晋、宋、齐、梁、陈。\n烟：指柳树绿阴阴的，像清淡的烟雾一样。', poem_appreciation = '这是一首凭吊六朝古迹的诗。中唐时期，昔日繁华的台城已是“万户千门成野草”；到了唐末，这里就更荒废不堪了。\n\n　　吊古诗多触景生情，借景寄慨，写得比较虚。这首诗则比同类作品更空灵蕴藉。它从头到尾采取侧面烘托的手法，着意造成一种梦幻式的情调气氛，让读者透过这层隐约的感情帷幕去体味作者的感慨。这是一个值得注意的特点。\n\n　　起句不正面描绘台城，而是着意渲染氛围。金陵滨江，故说“江雨”、“江草”。江南的春雨，密而且细，在霏霏雨丝中，四望迷蒙，如烟笼雾罩，给人以如梦似幻之感。暮春三月，江南草长，碧绿如茵，又显出自然界的生机。这景色即具有江南风物特有的轻柔婉丽，又容易勾起人们的迷惘惆伥。这就为下一句抒情作了准备。\n\n　　“六朝如梦鸟空啼”。从首句描绘江南烟雨到次句的六朝如梦，跳跃很大，乍读似不相属。其实不仅“江雨霏霏”的氛围已暗逗“梦”字，而且在霏霏江雨、如茵碧草之间就隐藏着一座已经荒凉破败的台城。鸟啼草绿，春色常在，而曾经在台城追欢逐乐的六朝统治者却早已成为历史上来去匆匆的过客，豪华壮丽的台城也成了供人凭吊的历史遗迹。从东吴到陈，三百多年间，六个短促的王朝一个接一个地衰败覆亡，变幻之速，本来就给人以如梦之感；再加上自然与人事的对照，更加深了“六朝如梦”的感慨。“台城六代竞豪华”，但眼前这一切已荡然无存，只有不解人世沧桑、历史兴衰的鸟儿在发出欢快的啼鸣它从人们对鸟啼的特殊感受中进一步烘托出“梦”字，寓慨很深。\n\n　　“无情最是台城柳，依旧烟笼十里堤。”杨柳是春天的标志。在春风中摇荡的杨柳，总是给人以欣欣向荣之感，让人想起繁荣兴茂的局面。当年十里长堤，杨柳堆烟，曾经是台城繁华景象的点缀；如今，台城已经是“万户千门成野草”，而台城柳色，却“依旧烟笼十里堤。”这繁荣茂盛的自然景色和荒凉破败的历史遗迹，终古如斯的长堤烟柳和转瞬即逝的六代豪华的鲜明对比，对于一个身处末世、怀着亡国之忧的诗人来说，该是多么令人触目惊心！而台城堤柳，却既不管人间兴亡，也不管面对它的诗人会引起多少今昔盛衰之感，所以说它“无情”。说柳“无情”，正透露出人的无限伤痛。“依旧”二字，深寓历史沧桑之慨。它暗示了一个腐败的时代的消逝，也预示历史的重演。堤柳堆烟，本来就易触发往事如烟的感慨，加以它在诗歌中又常常被用作抒写兴亡之感的凭藉，所以诗人因堤柳引起的感慨也就特别强烈。“无情”、“依旧”，通贯全篇写景，兼包江雨、江草、啼鸟与堤柳；“最是”二字，则突出强调了堤柳的“无情”和诗人的感伤怅惘。\n\n　　诗人凭吊台城古迹，回顾六朝旧事，免不了有今之视昔，亦犹后之视今之感。亡国的不祥预感，在写这首诗时是萦绕在诗人心头的。如果说李益的《汴河曲》在“行人莫上长堤望，风起杨花愁杀人”的强烈感喟中还蕴含着避免重演亡隋故事的愿望，那么本篇则在如梦似幻的气氛中流露了浓重的伤感情绪，这正是唐王朝覆亡之势已成，重演六朝悲剧已不可免的现实在吊古诗中的一种折光反映。\n\n　　这首诗以自然景物的“依旧”暗示人世的沧桑，以物的“无情”反托人的伤痛，而在历史感慨之中即暗寓伤今之意。思想情绪虽不免有些消极，但这种虚处传神的艺术表现手法，仍可以借鉴。', poem_tags = '咏史怀古,写景,抒情' WHERE poem_title = '台城' AND poem_author = '韦庄';
UPDATE edu_poem SET poem_translation = '魏明帝青龙元年八月，诏宫官牵车西取汉孝武捧露盘仙人，欲立置前殿。宫官既拆盘，仙人临载，乃潸然泪下。唐诸王孙李长吉遂作《金铜仙人辞汉歌》。\n\n茂陵里埋葬的刘郎，好像秋风过客匆匆而逝。\n夜里曾听到他的神马嘶鸣，天亮却杳无踪迹。\n画栏旁边棵棵桂树，依然散发着深秋的香气。\n长安城的三十六宫，如今却是一片苔藓碧绿。\n魏国官员驱车载运铜人，直向千里外的异地。\n刚刚走出长安东门，寒风直射铜人的眼珠里。\n只有那朝夕相处的汉月，伴随铜人走出官邸。\n怀念起往日的君主，铜人流下如铅水的泪滴。\n枯衰的兰草为远客送别，在通向咸阳的古道。\n上天如果有感情，也会因为悲伤而变得衰老。\n独出长安的盘儿，在荒凉的月色下孤独影渺。\n眼看着长安渐渐远去，渭水波声也越来越小。', poem_notes = '魏明帝：名曹叡，曹操之孙。青龙元年：旧本又作九年，然魏青龙无九年，显误。元年亦与史不符，据《三国志·魏书·明帝纪》，公元237年（魏青龙五年）旧历三月改元为景初元年，徙长安铜人承露盘即在这一年。\n宫官：指宦官。牵车：一作“舝车”。舝，同“辖”，车轴头。这里是驾驶的意思。捧露盘仙人：王琦注引《三辅黄图》：“神明台，武帝造，上有承露盘，有铜仙人舒掌捧铜盘玉杯以承云表之露，以露和玉屑服之，以求仙道。”\n潸然泪下：《三国志·魏书·明帝纪》裴注引《汉晋春秋》：“帝徙盘，盘拆，声闻数十里，金狄（铜人）或泣，因留于霸城。”\n唐诸王孙：李贺是唐宗室之后，故称“唐诸王孙”。\n茂陵：汉武帝刘彻的陵墓，在今陕西省兴平县东北。刘郎：指汉武帝。秋风客：犹言悲秋之人。汉武帝曾作《秋风辞》，有句云：“欢乐极兮哀情多，少壮几时兮奈老何？”\n“夜闻”句：传说汉武帝的魂魄出入汉宫，有人曾在夜中听到他坐骑的嘶鸣。\n桂树悬秋香：八月景象。秋香：指桂花的芳香。\n三十六宫：张衡《西京赋》：“离宫别馆三十六所。”土花：苔藓。\n舝：一作“牵”。千里：言长安汉宫到洛阳魏宫路途之远。\n东关：车出长安东门，故云东关。酸风：令人心酸落泪之风。\n将：与，伴随。汉月：汉朝时的明月。\n君：指汉家君主，特指汉武帝刘彻。铅水：比喻铜人所落的眼泪，含有心情沉重的意思。\n衰兰送客：秋兰已老，故称衰兰。客指铜人。咸阳：秦都城名，汉改为渭城县，离长安不远。咸阳道：此指长安城外的道路。\n“天若”句：意谓面对如此兴亡盛衰的变化，天若有情，也会因常常伤感而衰老。\n独出：一说应作“独去”。\n渭城：秦都咸阳，汉改为渭城县，此代指长安。波声：指渭水的波涛声。渭城在渭水北岸。', poem_appreciation = '《金铜仙人辞汉歌》诗中的金铜仙人临去时“潸然泪下”表达的主要是亡国之恸。此诗所抒发的是一种交织着家国之痛和身世之悲的凝重感情。\n\n　　诗共十二句，大体可分成三个部分。前四句慨叹韶华易逝，人生难久。汉武帝当日炼丹求仙，梦想长生不老。结果，还是像秋风中的落叶一般，倏然离去，留下的不过是茂陵荒冢而已。尽管他在世时威风无比，称得上是一代天骄，可是，“夜闻马嘶晓天迹”，在无穷无尽的历史长河里，他不过是偶然一现的泡影而已。诗中直呼汉武帝为“刘郎”，表现了李贺傲兀不羁的性格和不受封建等级观念束缚的可贵精神。\n\n　　全诗可分为三个层次。首四句是第一个层次，借金铜仙人的“观感”慨叹韶华易逝，人生短暂。世事无常。诗中直呼汉武帝为“刘郎”为“客”，表现了李贺不羁的性格和不受封建等级观念束缚的精神。中四句为第二个层次，用拟人化手法写金铜仙人初离汉宫的酸苦惨凄情态，亡国之痛和移徙之悲跃然纸上。特别是“酸”、“射”两字，把主观的情和客观的物完全揉和在一起，含义极为丰富。末四句为第三个层次，写出城后途中的情景。“衰兰”一语，写形兼写情，而以写情为主（因愁苦而“衰”）；“天若”一语，设想奇伟，意境辽远，感情深沉，司马光称为“奇绝无双”;末联进一步描述了金铜仙人恨别伤离，不忍离去，而又不能不离去的情怀，感人至深。\n\n　　“夜闻”句承上启下，用夸张的手法显示生命短暂，世事无常。它是上句的补充，使“秋风客”的形象更加鲜明、丰满，也为下句展示悲凉幽冷的环境气氛作了必要的铺垫。汉武帝在世时，宫殿内外，车马喧阗。此时物是人非，画栏内高大的桂树依旧花繁叶茂，香气飘逸，三十六宫却早空空如也，惨绿色的苔藓布满各处，荒凉冷落的面貌令人目不忍睹。\n\n　　以上所写是金铜仙人的“观感”。金铜仙人是汉武帝建造的，矗立在神明台上，“高二十丈，大十围”（《三辅故事》），异常雄伟。公元233年（魏明帝景初元年），它被拆离汉宫，运往洛阳，后因“重不可致”，而被留在霸城。习凿齿《汉晋春秋》说：“帝徙盘，盘拆，声闻数十里，金狄（即铜人）或泣，因留霸城。”李贺故意去掉史书上“铜人重不可致，留于霸城”（《三国志》注引《魏略》）的情节，而将“金狄或泣”的神奇传说加以发挥，并在金铜仙人身上注入自己的思想感情。这样，物和人、历史和现实便融为一体，从而幻化出美丽动人的艺术境界来。\n\n　　中间四句用拟人法写金铜仙人初离汉宫时的凄婉情态。金铜仙人是刘汉王朝由昌盛到衰亡的“见证人”，眼前发生的沧桑巨变早已使他感慨万端，神惨色凄。而自己又被魏官强行拆离汉宫，此时此刻，兴亡的感触和离别的情怀一齐涌上心头。“魏官”二句，从客观上烘托金铜人依依不忍离去的心情。“指千里”言道路遥远。从长安迁往洛阳，千里迢迢，远行之苦加上远离之悲，实在教人不堪忍受。“东关”句言气候恶劣。此时关东霜风凄紧，直射眸子，不仅眼为之“酸”，亦且心为之“酸”。它含有“马后桃花马前雪，出关争得不回头”的意味，表现出对汉宫、对长安的深切依恋之情。句中“酸”、“射”二字，新奇巧妙而又浑厚凝重。特别是“酸”字，通过金铜仙人的主观感受，把彼时彼地风的尖利、寒冷、惨烈等情形，生动地显现出来。这里，主观的情和客观的物已完全揉合在一起，含义极为丰富。\n\n　　诗人时而正面摹写铜人的神态，时而又从侧面落笔，描绘铜人四周的景物，给它们涂上一层忧伤的色调。两种手法交互运用，使诗意开阖动荡，变幻多姿，而又始终围绕着一个“愁”字，于参差中见整饬，色调统一，题旨鲜明。“魏官”二句，侧重描写客体，“空将”二句则改写主体，用第一人称，直接抒发金铜仙人当时的思想感情：在魏官的驱使下离别汉宫，作千里之行。伴随着“我”的唯有天上旧时的明月而已。事情发生在三国时期而称月为“汉月”，它抒发的是一种怀旧的感情，正如王琦《李长吉歌诗汇解》所诠释的：“因革之间，万象为之一变，而月体始终不变，仍似旧时，故称‘汉月’。”金铜仙人亲身感受过武帝的爱抚，亲眼看到过当日繁荣昌盛的景象。对于故主，他十分怀念，对于故宫，也有着深厚的感情。而此刻坐在魏官牵引的车子上，渐行渐远，眼前熟悉而又荒凉的宫殿即将隐匿不见，抚今忆昔，不禁潸然泪下。“忆君”句中“泪如铅水”，比喻奇妙非凡，绘声绘色地写出了金铜仙人当时悲痛的形容——泪水涔涔，落地有声。这种感怀旧事、恨别伤离的神情与人无异，是“人性”的表现，而“铅水”一词又与铜人的身份相适应，婉曲地显示了他的“物性”。这些巧妙的表现手法，成功地塑造出金铜仙人这样一个物而人、物而神，独一无二，奇特而又生动的艺术形象来。\n\n　　末四句写出城后途中的情景。此番离去，正值月冷风凄，城外的“咸阳道”和城内的“三十六宫”一样，呈现出一派萧瑟悲凉的景象。这时送客的唯有路边的“衰兰”，而同行的旧时相识也只有手中的承露盘而已。“衰兰”一语写形兼写情，而以写情为主。兰花之所以衰枯，不只因为秋风肃杀，对它无情摧残，更是愁苦的情怀直接造成。这里用衰兰的愁映衬金铜仙人的愁，亦即作者本人的愁，它比《开愁歌》中的“我生二十不得意，一心愁谢如枯兰”，更加婉曲，也更为新奇。\n\n　　兰花的衰枯是情使之然。凡是有情之物都会衰老枯谢。别看苍天日出月没，光景常新，终古不变。假若它有情的话，也照样会衰老。“天若有情天亦老”这一句设想奇伟，司马光称为“奇绝无对”。它有力地烘托了金铜仙人（实即作者自己）艰难的处境和凄苦的情怀，意境辽阔高远，感情执着深沉，真是千古名句。\n\n　　尾联进一步描述金铜仙人恨别伤离的情绪。他不忍离去，却又不得不离去，而且随着时间的推移，离开故都越来越远。这时，望着天空中荒凉的月色，听着那越来越小的渭水流淌声，心里有种说不出来的滋味。“渭城”句从对面落笔，用“波声小”反衬出铜人渐渐远去的身影。一方面波声渺远，另一方面，道阻且长。它借助于事物的声音和形态，委婉而深沉地表现出金铜仙人“思悠悠，恨悠悠”的离别情怀，而这正是当日诗人在仕进无望、被迫离开长安时的心境。\n\n　　这首诗是李贺的代表作品之一。它设想奇创，而又深沉感人；形象鲜明而又变幻多姿。怨愤之情溢于言外，却并无怒目圆睁、气峻难平的表现。遣词造句奇峭而又妥帖，刚柔相济，恨爱互生，参差错落而又整饬绵密。这确是一首既有独特风格，而又诸美同臻的诗作，在李贺的集子里，也找不出几首类似的作品来。', poem_tags = '离别,怀古,感伤' WHERE poem_title = '金铜仙人辞汉歌' AND poem_author = '李贺';
UPDATE edu_poem SET poem_translation = '城里有夕阳而城外却下雪，相距十里天气竟不一样。\n可知道造物主是何心意？莫非人心中的苦难还没有磨平。\n御史府的楼台倒影在水中，茅屋松竹流泻出寒冷的信息。\n有布被不要担心睡觉冻僵，多一点耐心总会等到天明。', poem_notes = '也知：有谁知道。\n底事：此事。底，作疑问代词，相当于此、这。\n布衾：棉被。如杜甫诗《茅屋为秋风所破歌》：“布衾多年冷似铁。”', poem_tags = '春节,写景,抒怀,愿望' WHERE poem_title = '次韵陆佥宪元日春晴' AND poem_author = '王守仁';
UPDATE edu_poem SET poem_translation = '西城的杨柳逗留着春天的柔情，使我想起离别时的忧伤，眼泪很难收回。还记得当年你为我拴着归来的小舟。绿色的原野，红色的桥，是我们当时离别的情形。而如今你不在，只有水孤独地流着。\n美好的青春不为少年时停留，离别的苦恨，何时才到头？飘飞的柳絮，落花满地的时候我登上楼台。即使江水都化作泪水，也流不尽，依然有愁苦在心头。', poem_notes = '江城子：词牌名，又名“江神子”“村意远”。唐词单调，始见《花间集》韦庄词。宋人改为双调，七十字，上下片都是七句五平韵。\n弄春：谓在春日弄姿。明徐渭《赋得万绿枝头红一点》诗：“名园树树老啼莺，叶底孤花巧弄春。”\n离忧：离别的忧思；离人的忧伤。唐杜甫《长沙送李十一》诗：“李杜齐名真忝窃，朔云寒菊倍离忧。”\n多情：指钟情的人。宋张先《南乡子·京口》词：“春水一篙残照阔，遥遥，有个多情立画桥。”\n归舟：返航的船。南朝宋谢灵运《酬从弟惠连》诗：“梦寐伫归舟，释我吝与劳。”\n韶华：美好的时光。常指春光。唐戴叔伦《暮春感怀》诗：“东皇去后韶华尽，老圃寒香别有秋。”\n飞絮：飘飞的柳絮。北周庾信《杨柳歌》：“独忆飞絮鹅毛下，非复青丝马尾垂。”\n春江：春天的江。唐张若虚《春江花月夜》诗：“滟滟随波千万里，何处春江无月明。”', poem_appreciation = '这首愁情词由春愁离愁写起，再写失恋之愁和叹老嗟卑之愁，省略或者说是虚化了具体时空背景，仿佛将词人一生所经历之愁都凝聚浓缩在一首词中了，很富表现力和艺术感染力。\n\n　　上片前三句写初春的离别，并未出现告别的对象而悲泪滂沱，已寓无限隐情。“犹记”两句转为忆旧，“多情”指恋人，“系归舟”指飘泊重逢的激动。“碧野朱桥”是当日系舟处所，又是今日处境。“当日事”唯存记忆，而眼前是“人不见，水空流”。即谓再度离别，再度“归来”时，已无人“系舟”，只见水流了！几个波折，诉尽赴约而不遇的绝望哀情。\n\n　　换头“韶华”句为议论，道破人生真理，此理虽为常理常情，但由词人体味人生后道出则有极哀切的意蕴。这青春不再，年华易衰，才是“恨悠悠”的终极原因，何况春天又一次完结了哩！此悠悠长恨，当然将词人仕途不遇、理想落空的伤感融注其间了。最后，将愁恨之泪化作春江，极尽夸饰之能事，却仍“流不尽，许多愁”！妙在“流不尽”！此喻，在李后主“问君能有几多愁，恰似一江春水向东流”的比喻基础上，又翻出一层新意，乃脱胎换骨，点铁成金之法。\n\n　　此词结构布局极缜密。下片“飞絮落花”印上片“杨柳弄春柔”；“登楼”印“离忧”；“春江都是泪”印“泪难收”；“韶华不为少年留”总提全词命意，天然浑成，意态兼善，神韵悠长。', poem_tags = '宋词三百首,宋词精选,婉约,爱情,怀人,感伤' WHERE poem_title = '江城子·西城杨柳弄春柔' AND poem_author = '秦观';
UPDATE edu_poem SET poem_translation = '今天云彩飘飘，景色迥然，流水更绿，青山更明亮。\n我手携一壶流霞酒，采撷一朵黄菊花，欣赏这菊花凌霜不凋的品行。\n这里山石偏僻，松树古远，快乐的管弦乐随风飘洒。\n酒杯当明镜照耀我欢乐容颜，独自一个人喝酒，自得其乐。\n望着山月独自起舞高歌，任帽儿被舞风吹落，却不知道让我怀念的朋友都在哪里。', poem_notes = '九日：农历九月九日，俗称重九，古人认为九是阳数，所以这天又叫重阳节。\n云景好：景物好。\n流霞：美酒名。\n搴（qiān）菊：采取菊花。\n寒荣：寒冷天气开放的菊花，指菊花。\n觞（shāng）：古时的酒杯。\n落帽：典出《晋书》，据载：大司马桓温曾和他的参军孟嘉登高于龙山，孟嘉醉后，风吹落帽，自己却没有发觉，此举在讲究风度的魏晋时期，有伤大雅，孙盛作文嘲笑，孟嘉即兴作答：“醉看风落帽，舞爱月留人。”文辞优美，语惊四座。后人以此典比喻文人不拘小节，风度潇洒之态。\n空：徒然。\n友生：朋友。', poem_tags = '重阳节,登高,饮酒,典故' WHERE poem_title = '九日' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '花儿已经枯萎凋残，风儿吹得它漫天旋转。退尽了鲜红颜色，消失了芳香，有谁对它同情哀怜？\n柔软的蛛丝儿似断似连，飘荡在春天的树间。漫天飘散的柳絮随风扑来，沾满了绣花的门帘。\n闺房中的少女，面对着残春的景色多么惋惜。满怀忧郁惆怅，没有地方寄托愁绪。\n手拿着锄花的铁锄，挑开门帘走到园里。园里花儿飘了一地，我怎忍心踏着花儿走来走去？\n轻佻的柳絮，浅薄的榆钱，只知道显耀自己的芳菲。不顾桃花飘零，也不管李花纷飞。\n待到来年大地春回，桃树李树又含苞吐蕊。可来年的闺房啊，还能剩下谁？\n新春三月燕子噙来百花，散着花香的巢儿刚刚垒成。梁间的燕子啊，糟蹋了多少鲜花多么无情！\n明年百花盛开时节，你还能叼衔花草。你怎能料到房主人早已死去，旧巢也已倾落，只有房梁空空。\n一年三百六十天啊，过的是什么日子！刀一样的寒风，利剑般的严霜，无情地摧残着花枝。\n明媚的春光，艳丽的花朵，能够支撑几时。一朝被狂风吹去，再也无处寻觅。\n花开时节容易看到，一旦飘落难以找寻。站在阶前愁思满怀，愁坏了我这葬花的人。\n手里紧握着花锄，我默默地抛洒泪珠。泪珠儿洒满了空枝，空枝上浸染着斑斑血痕。\n杜鹃泣尽了血泪默默无语，愁惨的黄昏正在降临。我扛着花锄忍痛归去，紧紧地关上重重闺门；\n青冷的灯光照射着四壁，人们刚刚进入梦境。轻寒的春雨敲打着窗棂，床上的被褥还是冷冷冰冰。\n人们奇怪是什么事情，使我今天这样格外伤心？一半是对美好春光的爱惜，一半是恼恨春天的逝去。\n我高兴春天突然来临，又为它匆匆归去感到抑郁。春天悄然无语地降临人间，又一声不响地离去。\n昨晚不知院外什么地方，传来一阵阵悲凉的歌声。不知道是花儿的灵魂，还是那鸟儿的精灵？\n不管是花儿的灵魂，还是鸟儿的精灵，都一样地难以挽留。问那鸟儿，鸟儿默默无语，问那花儿，花儿低头含羞。\n我衷心地希望啊，如今能够生出一双翅膀。尾随那飞去的花儿，飞向那天地的尽头。\n纵使飞到天地的尽头，那里又有埋葬香花的魂丘？\n不如用这锦绣的香袋，收敛你那娇艳的尸骨。再堆起一堆洁净的泥土，埋葬你这绝代风流。\n愿你那高贵的身体，洁净的生来，洁净的死去。不让它沾染上一丝儿污秽，被抛弃在那肮脏的河沟。\n花儿啊，你今天死去，我来把你收葬。谁知道我这薄命的人啊，什么时候忽然命丧？\n我今天把花儿埋葬，人们都笑我痴情。等到我死去的时候，有谁把我掩埋？\n不信请看那凋残的春色，花儿正在渐渐飘落。那也就是闺中的少女，衰老死亡的时刻。\n一旦春天消逝，少女也便白发如丝。花儿凋零人死去，花儿人儿两不知！', poem_notes = '榭（xiè）：建在高土台或水面（或临水）上的的建筑，是一种借助于周围景色而见长的园林或景区休憩建筑。\n香丘：是根据佛教名词“香山”新造的词，意思是香气缭绕的小山丘，比喻有一小方受佛教庇护，可以安居乐业的土地。不奢求香气缭绕的蓬莱仙境。\n一抔（póu）：意思是一捧之土。典出《史记·张释之冯唐传》：“假令愚民取长陵一抔土，陛下何以加其法乎？”净土：佛教专用名词，原意指完全被佛教度化的土地，净土上除了佛教之外没有任何其它外道。与“一抔”联用后成为双关语，也指只有汉文化，不被佛教文化沾染的土地。\n帘中女儿惜春莫：“帘中”与上句为顶针续麻格。“莫”，“暮”的古字。\n洒上花枝见血痕：此句与两个传说有关：①娥皇、女英在湘江哭舜，泣血染竹枝成斑。所以黛玉号“潇湘妃子”。②蜀帝杜宇魂化杜鹃鸟，啼血染花枝，花即杜鹃花。所以下句接言“杜鹃”。案：周汝昌言：（花枝）谓花即泪染，非“空枝”之义。\n他年葬奴知是谁：这一句中在周汇本中出现了矛盾。在《葬花吟》中打出的是“奴”，而在下一章节中宝玉感慨句写出的是“我”，而周先生在注释中特意说明用“奴”“我”字样可体现小女随口吟成，改成“侬”尽显文人酸气。', poem_appreciation = '《葬花吟》是曹雪芹创作的章回小说《红楼梦》女主人公林黛玉所吟诵的一首诗。这首诗在风格上仿效初唐体的歌行体，名为咏花，实则写人。全诗血泪怨怒凝聚，通过丰富而奇特的想象，暗淡而凄清的画面，浓烈而忧伤的情调，展现了黛玉多愁善感的性格、内心的矛盾与痛苦、细微而复杂的心理活动，表达了其在生与死、爱与恨等复杂的斗争过程中所产生的一种对自身存在焦虑不安的体验和对生命迷茫的情感。将花拟人，以花喻人，把花的命运与人的命运紧相联系，有力地控诉了那些摧残花的自然界和扼杀人的黑暗社会恶势力。明写花，实写人，将人物的遭遇、命运、思想、感情融汇于景与物的描绘之中，创造出内涵丰富、形象鲜明生动的意境，具有强烈的艺术感染力。整首诗是林黛玉生命理念和人生价值的真实写照。全诗抒情淋漓尽致，语言如泣如诉，声声悲音，字字血泪，满篇无一字不是发自肺腑、无一字不是血泪凝成，把林黛玉对身世的遭遇和感叹表现得入木三分。《葬花吟》写出主人公在幻想自由幸福而不可得时，所表现出来的那种不愿受辱被污、不甘低头屈服的孤傲不阿的性格。是为其思想价值。\n\n　　此诗另一价值在于它为后人提供了探索曹雪芹笔下的宝黛悲剧的重要线索。甲戌本上脂砚斋的批语指出：没有看过“宝玉之后文”是无从对此诗加批的；批书人“停笔以待”的也正是与此诗有关的“后文”。所谓“后文”当然是指后半部佚稿冲写黛玉之死的文字。如果这首诗中仅仅一般地以落花象征红颜薄命，那也用不着非待后文不可；只有诗中所写非泛泛之言，而大都与后来黛玉之死情节声切相关时，才有必要强调指出，在看过后面文字以后，应回头来再重新加深对此诗的理解。由此可见，《葬花吟》实际上就是林黛玉自作的“诗谶”。\n\n　　为落花缝锦囊，为落花埋香冢；还要悲哭，还要作诗。这种前无古人，后无来者的“荒唐”举动，唯有痴情如宝黛者方能理解，也唯有发生在宝黛身上方能为世人所理解。和曹雪芹同时期的富察·明义《题红楼梦》绝句说：“伤心一首葬花词，似谶成真自不如。安得返魂香一缕，起卿沉痼续红丝？”“似谶成真”，这是只有知道了作者所写黛玉之死的情节的人才能说出来的话。以前红学研究者还以为明义未必能如脂砚那样看到小说全书，从此绝句中可以看出，他读到过后半部部分稿子的可能性极大，或者至少也听作者交往的圈子里的人比较详尽地说起过后半部的主要情节。如果说，明义绝句中提到后来的事像“聚如春梦散如烟”、“石归山下无灵气”之类，还可由推测而知的话；那么，写宝玉贫穷的“王孙瘦损骨嶙峋”，和写他因获罪致使他心中的人为他的不幸忧忿而死的“惭愧当年石季伦”等诗句，是再也无从凭想象而得的。\n\n　　上面所引之诗中的后两句也是如此：明义说，他真希望有起死回生的返魂香，能救活黛玉，让宝、黛两个有情人成为眷属，把已断绝的月下老人所牵的红丝绳再接续起来。可想而知，只要“沉痼”能起，“红丝”也就能续，这与后来续书者想象宝、黛悲剧的原因在于婚姻不自主极为不同。倘若一切都如程伟元、高鹗整理的续书中所写的那样，则贾宝玉已有他属。起黛玉“沉痼”毫无作用。“续红丝”当然不是为了要她做宝二姨娘。\n\n　　《葬花吟》“侬今葬花人笑痴，他年葬侬知是谁？”等末了数句，书中几次重复，特意强调，甚至通过写鹦鹉学吟诗也提到。可知红颜老死之日，确在春残花落之时，并非虚词作比。同时，这里说“他年葬侬知是谁”，前面又说“红消香断有谁怜”、“一朝飘泊难寻觅”等等，则黛玉亦如晴雯那样死于十分凄惨寂寞的境况之中可以。那时，并非大家都忙着为宝玉办喜事，因而无暇顾及，恰恰相反，宝玉、凤姐都因避祸流落在外，那正是“家亡莫论亲”、“各自须寻各自门”的日子，诗中“柳丝榆荚自芳菲，不管桃飘与李飞”或含此意。\n\n　　“三月香巢初垒成，梁间燕子太无情。明年花发虽可啄，却不道人去梁空巢也倾”几句，原在可解不可解之间，怜落花而怨及燕子归去，用意甚难把握贯通。倘作谶语看，就比较明确了。大概春天里宝黛的婚事已基本说定了，即所谓“香巢初垒成”，可是，到了秋天，发生了变故，就像梁间燕子无情地飞去那样，宝玉被迫离家出走了。因而，她悲叹“花魂鸟魂总难留”，幻想着自己能“胁下生双翼”也随之而去。她日夜悲啼，终至于“泪尽证前缘”了。\n\n　　这样，“花落人亡两不知”，若以“花落”比黛玉，“人亡”（流亡也）说宝玉，正是完全切合的。贾宝玉凡遭所谓“丑祸”，总有别人要随之而倒霉的。先有金钏，后有晴雯，终于轮到了黛玉，所以诗中又有“质本洁来还洁去，强于污淖陷渠沟”的双关语可用来剖白和显示气节。“一别秋风又一年”，宝玉在次年秋天回到贾府，但所见怡红院已“红瘦绿稀”（脂评），潇湘馆更是一片“落叶萧萧，寒姻漠漠”（脂评）的凄凉景象，黛玉的闺房和宝玉的绛芸轩一样，只见“蛛丝儿结满雕梁”（脂评谓指宝黛住处），虽然还有薛宝钗在，而且以后还成其“金玉姻缘”，但这不能弥补他“对境悼颦儿”时所产生的巨大精神创痛。“明年花发虽可啄，却不道人去梁空巢也倾！”就是这个意思。这些只是从脂评所提及的线索中可以得到印证的一些细节，所述未必都那么妥当。但此诗与宝黛悲剧情节必定有照应这一点，应不是主观臆断；其实，“似谶成真”的诗还不止于此，黛玉的《代别离·秋窗风雨夕》和《桃花行》也有这种性质。前者仿佛不幸地言中了她后来离别宝玉的情景，后者则又像是她对自己“泪尽夭亡”（脂评）结局的预先写照。\n\n　　有人说《葬花吟》是从唐寅的两首诗中“脱胎”的（《红楼梦辨》）。诗歌当然是有所继承借鉴的，但不应把文艺创作的“源”和“流”的关系弄颠倒了。说到《葬花吟》在某些遣词造句、意境格调上利用前人之作，实不必到明人的集子中去找。唐初刘希夷《代悲白头翁》中“今年花落颜色改，明年花开复谁在”、“年年岁岁花相似，岁岁年年人不同”之类为人熟知的诗句也足以借取利用。即如葬花情节，也未必径取唐寅将牡丹花“盛以锦囊，葬于药栏东畔”事，作者的祖父曹寅的《楝亭诗钞》中也就有“百年孤冢葬桃花”的诗句，也不足以启发他的构思。但这些都是“流”，都仅仅是利用，既不表现诗的主要精神，也决不能代替作者源于现实生活的创造。何况，如前所述，此诗中，作者运笔鬼斧神工之处，完全不在于表面上那些伤春惜花词句的悱恻缠绵。\n\n　　“伤心一首葬花词，似谶成真不自知。”黛玉这首抒情诗，实际上也是隐示其命运的谶语。她如一朵馨香娇嫩的花朵，悄悄地开放，又在狂风骤雨中被折磨得枝枯叶败，从世界上悄悄消逝。说这首诗是谶语，是就其整体的思想而言，并不是说每字每句都隐示着黛玉的具体遭遇。\n\n　　《葬花吟》中消极颓伤的情绪也是极其浓重且不容忽视的。它曾对缺乏分析思考能力的读者起过不良的影响。这种情绪虽然在艺术上完全符合林黛玉这个人物所处的环境地位所形成的思想性格，但毕竟因作者在某种程度上有意识借所倾心的人物之口来抒发自己的身世之感，而显露了他本身思想的弱点。\n\n　　其实《葬花吟》不仅仅是黛玉一个人的诗谶，同时也是大观园群芳共同的诗谶。她们尽管未来的具体遭遇各不相同但在“有命无运”这一点上却没有两样，都是在“薄命司”注册的人物。随着贾家的败落，所有的大观园内的女孩儿都要陷于污淖、沟渠之中，都没有好命运。', poem_tags = '写花,寓人,抒情' WHERE poem_title = '葬花吟' AND poem_author = '曹雪芹';
UPDATE edu_poem SET poem_appreciation = '此词只冷雪盦本《漱玉词》收入，他本皆未收，故属存疑之作。\n\n　　李清照婚后，丈夫名城曾离家远行，她以《醉花阴.·重阳》寄给赵明诚，抒写重阳佳节对丈夫的深切思念之情。南渡后，赵明诚病故，她避乱漂泊，在一个 近重阳的时节，写了这首《行香子》，表象他对逝去丈夫的缅怀及悲凉的心情。前者写的是生离，后者写的是死别。故 后者悲苦过之。 从艺术技巧之精湛上说，虽然不像《醉花阴·重阳》那样引人注目，但它的确是一颗明珠瑰宝，在艺海的深处熠熠发光，丝毫没能降低它的艺术价值。 　　 　　“天与秋光，转转情伤，探金英知近重阳。” 宇宙 造化 自然 ，使人间世界有四季的区别，给人们以秋日的光景。随着节气及阴雨风寒的往复变化，秋天变得天高气清，烟消云敛，西风飒飒，草木衰微，落叶萧萧，山川寂寥，景象凄肃。《文心雕龙》云“物色之动，心亦摇焉” 景物的变化，使人的思想感情也波动起来。本来易安因国破、家亡、夫丧，又颠沛流离而心境凄悲，看见眼前衰退的景象，怎能不黯然情伤？“转转” 指天气的反复变化。她年轻时看到秋天的景象是无比欣悦的，赞道“水光山色与人亲，说不尽、无穷好”。然而现在她已遭受种种苦难的摧残，心境情怀产生巨大的变化，“览物之情 得无异乎？”这更使他情伤的原因。\n\n　　“探金英知近重阳” 探 ，仔细察看。金英，黄色菊花。重阳，农历九月九日为重阳节。女主人仔细观察一下黄色菊花就知道重阳佳节临近了。按照古老的习俗，人们要在重阳节这一天，团聚、赏菊、饮菊花酒、插茱萸等。孟浩然《过故人庄》“故人具鸡黍，邀我至田家，绿树村边合，青山郭外斜，开轩面场圃，把酒话桑麻，待到重阳日，还来就菊花”王维《九月九日忆山东兄弟》“独在异乡为异客，每逢佳节倍思亲，遥知兄弟登高处，遍插茱萸少一人”。从这两首诗可以看出古时重阳节人们的活动。年轻时她曾写《醉花阴·重阳》“莫道不销魂，帘卷西风，人比黄花瘦”。与丈夫赵明诚仅仅是暂别就使她的感情禁受不住，她比菊花还要消瘦了；而今 国破家亡，明诚逝世，她转徙江浙，“独在异乡为异客” “近重阳”抚今追昔，又何等的“情伤”\n\n　　“薄衣初试，绿蚁新尝” ，薄衣，粗糙的衣服。《梁书·武帝记·入屯阅武堂下令》“菲饮薄衣，请自孤始” ......绿蚁，一种新酿成的酒，上浮绿色泡沫。这种泡沫后来成为酒的代称，也叫浮蚁、碧蚁。白居易《问刘十九》“绿蚁新醅酒，红泥小火炉”李珣《渔歌子》“孤素琴，倾绿蚁，扁舟自得逍遥志”，其绿蚁就是这种酒。意思是，刚刚试穿了一件粗糙的衣服品尝了新酿成的绿蚁酒。因为时近重阳，衣服要加厚；因为情伤，需要用酒来浇愁。“每逢佳节倍思亲”“独在异乡为异客”思今虑昔，情怀酸楚。词句承前。\n\n　　“渐一番风，一番雨，一番凉” 此句回应首句的’“转转” 渐，渐次。意思是，在阴雨风凉的反复变化中，每刮一次风，下一次雨，天气便渐次转凉。此句有三个结构相同、两个字相同的词组组成。此类结句，使词自然流动，增加词的音律美和修辞美。\n\n　　上阕 写近重阳，天气逐渐转凉，女主人百感交集，格外情伤。\n\n　　“黄昏院落，凄凄惶惶，酒醒时往事愁肠” 上片，秋光 ，近重阳，点明节序。此处的“黄昏”点明时间。落日的余晖已渲染在茫茫的天边，庭院里也变得昏黄、暗淡。一阵秋风吹来，又有庭树的叶子飘落，发出飒飒的声响，冷冷清清，凄凄惨惨，一个人在院子里感到惊恐害怕，凄凉的景象恰似她如水的情怀。白天 绿蚁曾使她醉倒，当夜幕要降临的时候，她酒劲过了，麻醉了的神经刚刚恢复正常，种种往事又涌上心头。真是“抽刀断水水更流，举杯消愁愁更愁” 北国沦丧，至今不的收复；家藏的大量的金石书画，荡然无存；相依为命的丈夫，在兵荒马乱中逝去\'自己避乱江浙，飘泊无依，抚今追昔真是“旧恨春江流不尽，新恨云山千叠”，愁肠寸断。范仲淹《御街行》“愁肠已断无由醉，酒未到，先成泪” 。愁肠，极言愁事熬心。\n\n　　“那堪永夜，明月空床” 永夜，漫漫长夜。易安《蝶恋花》“永夜恹恹欢意少”郎士元《宿杜判官江楼》“故人江楼月，永夜千里心”几个“永夜”都是同意。明月，是美丽的，有给黑夜以光明，故引起人们无穷的遐思，奇妙的幻想。古今的骚人墨客，在他们的诗文中未曾涉及过明月的，几乎没有。骚人有的望月思乡，李白《静夜思》\'床前明月光 疑是地上霜，举头望明月 低头思故乡”白居易“共看明月应垂泪，一夜乡心五处同”是例也。有的望月怀人，如杜甫月下思念妻子儿女 《月夜》“今夜鄜州月，闺中只独看，遥怜小儿女，未解忆长安”有如苏东坡，《水调歌头》“但愿人长久 千里共婵娟”这是念手足兄弟的；有的望月怀念故国，如李后主《虞美人》“小楼昨夜又东风 故国不堪回首明月中”就是如此。李清照望着明月，思念逝去的丈夫。美好的明月，它的光辉照耀在词人身边的空床上。过去一起望月，同床共枕的爱人已经不在人世，旧恨新仇，又那忍受得了这般孤单无告的凄凉情景？《古诗·明月何皎皎》“明月皎皎照我床，星汉西流夜未央”，都是写女子思念丈夫的著名诗句。易安“明月空床”由此点化而成，将诗句浓缩简化，利用明月与空床的美感差异，乐景写哀，其哀倍增。\n\n　　“闻砧声捣 蛩声细 漏声长”砧，古代捣衣用的石头。古时妇女多在秋季拆洗缝制衣服，忙到深夜。《子夜歌》”长安一片月 万户捣衣声 秋风吹不尽 总是玉关情 何日平胡虏 良人罢远征” 这是妇女在明月之夜听捣衣的声音，怀念远征丈夫的诗。秦观《满庭芳》“有时近重阳也，几处处、砧杵声催“其时节与此词时节是相同的。李煜《捣练子》“深院静 ，小庭空，断续寒砧断续风。无奈夜长人不寐，数声和月到帘栊” 这与易安词意境基本相同。都是表现 听砧人对亲人的怀念。易安在“往事愁肠”的情况下，写出对逝去丈夫的无比怀念，悲苦甚之。\n\n　　“蛩声细”蛩，蟋蟀。人长夜不寐，听到蟋蟀细微的叫声，倍觉情怀凄切。唐人白居易《闻蛩》“闻蛩唧唧夜绵绵，况是秋阴欲雨天，犹恐愁人暂得睡，声声移近卧床边”。杜甫《促织》“促织甚细微，哀音何动人。草根吟不稳，床下夜相亲。久客得无泪，故妻难及晨。悲诗与急管，感激异天真”。可见古人常用蟋蟀的哀吟衬托愁人的悲哀心境。促织，即蟋蟀。\n\n　　“漏声长” 。漏，古代一种滴水计时用的器具。毛熙震《更漏子》“更漏咽，蛩鸣切，满院霜华如雪”。古诗词调名与词的内容是一致的。《更漏子》作为常用词调，及其产生的本身，就说明更漏是诗人常写的素材。“长” 说明主人公久久不能入睡。\n\n　　易安在近重阳之际追念丈夫，饮酒也无法排遣，酒醒时种种往事时他悲伤。明月照耀，她孤苦伶仃，夜阑不寐。沉重的捣衣声，细微的蛩鸣声，迢递的滴漏声，组成一个哀怨、凄凉、婉转的交响乐曲，它与李清照的心曲在节奏、旋律、情调上似乎是合拍的。\n\n　　下片 。写黄昏时她情怀悒郁，往事愁肠及永夜对丈夫的深切思念。\n\n　　作者通过典型环境的描写完美的表达了对逝去的丈夫的怀念这一题旨。之一艺术手段，在此词创作上的体现是昭著卓绝的。她首先选取的是四季风光中的秋光。秋光 是令人情伤的。从这一点说是典型的；写此季节的环境抓住“渐一番风 一番雨 一番凉”，这一秋天气候变化的典型特征来写；进而撷取秋光中“近重阳”这一时节，典型意义在于它是令人“倍思亲”的时节；写此时节的景物抓住了“金英”，因为菊花独放百花杀之一时期的独特特点；进而选取重阳时节中最易使人缅怀往事亲人的“黄昏”“永夜”；写这一时刻的环境时抓住“黄昏院落”“明月空床”“砧声”\'蛩声”“漏声”这些使人愁发郁勃的典型景物和声音。作者写节序时所摄取的景物都是颇具典型的，通过综合、融化儿塑造出来典型的环境。这表现作者艺术技巧的高超和善于继承优良文学传统，同时也表现作者对生活体察的深微，感受的强烈。\n\n　　易安此词前结：“渐一番风一番雨一番凉”，后结 “ 闻砧声捣蛩声细漏声长”与她的另一首《行香子》“甚霎儿晴 霎儿雨 霎儿风”都是有三个结构相同、个别一二个字相同的词组组成，前人把它叫做“重笔”此类结句盖祖于温庭筠 《更漏子》结句“一叶叶，一声声，空阶滴到明”前人评此句说“此种句法极锻炼，也及自然，故能令人掩卷后作三日之想”，余韵无穷。温词结句是由两个结构相同、一个结构不同的词组组成。是“二重笔”到了苏轼，行香子》“但远山长，云山乱，晓山青”，用了“三重笔”，其中有一个重字“山”。易安两首《行香子》结句用的是“三重笔”二重字，向前发展了。辛弃疾有《三山作》“放霎时阴，霎时雨，霎时晴”《问蘧庐随笔》认为此句“胎易安语也”。明人 高启《行香子》“正一番风，一番雨 ，一番凉”更明显看出是从易安句化出。\n\n　　此词运用“转转”“凄凄惶惶’六个叠字。古诗词常用叠字，《诗经》中“关关雎鸠”“桃之夭夭”“杨柳依依”《古诗十九首》“行行重行行”“青青河畔草” 乔吉《天净沙》’莺莺燕燕春春”，易安“凄凄惨惨戚戚”不胜枚举。此词六个叠字加浓了词的凄凉气氛，把词悲凉的心境表达得更为深切，增强了诗词的音律美。\n\n　　此词声声凄切，字字血泪。她的哀愁与“为赋新诗强说愁”不同，与浮薄的“闲愁”不同，又与一般的离愁别苦不同，这是在异族残酷进犯，南宋统治集团采取屈辱投降政策之下，一个难民的痛苦呻吟，虽然写的是个人遭逢的凄悲，但却有代表性。国破家亡，夫死妇丧，妻离子散，背井离乡，颠沛流离，这是整个时代的苦难。', poem_tags = '重阳节,思念' WHERE poem_title = '行香子·天与秋光' AND poem_author = '李清照';
UPDATE edu_poem SET poem_appreciation = '本文是为五位普通的平民百姓树碑立传的文字，探讨了生死价值这样重大的问题。全文以“义“为核心，成功地运用了记叙、议论、抒情三结合的表达方式。作者首先肯定五人之死是“激于义”，开篇抓住一个“义”字。五人是为义而生，为义而争，最后为义而献身。这就使读者联想起孟子的名言──“生，亦我所欲也；义，亦我所欲也：二者不可得兼，舍生而取义者也。”可以说，本文是对孟子名言的生动诠释。\n\n　　明代大奸臣、大宦官魏忠贤无恶不作，杀害了许多正直之士。东林党人与之进行了坚决的斗争。这是一场正义与邪恶的较量。苏州市民旗帜鲜明地站在东林党人一边，用鲜血和生命捍卫正义。五人是苏州市民的优秀代表。作者用饱蘸感情的笔墨，叙述了五人的动人事迹，歌颂了平民英雄的高尚品质。\n\n　　“然五人之当刑也，意气扬扬，呼中丞之名而詈之，谈笑以死。断头置城上，颜色不少变。”大义凛然，惊天地，泣鬼神!语言简练生动，铿锵有力。\n\n　　作者为了突出五人的英雄行为，运用对比的手法加以表现。“大阉之乱，缙绅而能不易其志者，四海之大有几人欤？”在阉党横行天下，炙手可热之时，多数人采取了苟且偷安的做法，甚至助纣为虐，为虎作伥。而五人面对阉党的淫威，无所畏惧，视死如归。应该说，一般的老百姓对阉党的倒行逆施可以不管，因为他们不在其位。但五人以“天下兴亡，匹夫有责”的大境界投入到对阉党的斗争中去，并且慷慨赴死，义无反顾。这不能不说是一种高尚的精神。而那些身在政位，吃民膏、喝民血的“缙绅”，却在阉党的淫威下屈服了，变节了。作者问道：“而五人生于编伍之间，素不闻诗书之训，激昂大义，蹈死不顾，亦曷故哉?”这一问，多少缙绅无地自容?“十年浩劫”期间，林彪、“四人帮”专横跋扈，“缙绅而能不易其志者，四海之大有几人欤?”张志新，一个普通女干部，坚持真理，宁死不屈，表现了一个共产党人的铮铮铁骨。也有许多人投靠“四人帮”，出卖良心，出卖人格。历史是如此惊人地相似。\n\n　　张溥认为：“大阉逡巡畏义，非常之谋难于猝发，待圣人之出而投缳道路，不可谓非五人之力也。”作者认识到了平民百姓的作用，这是非常可贵的。读此段，读者可能会联想到鲁迅先生在《记念刘和珍君》中所写的句子：“我目睹中国女子的办事，是始于去年的，虽然是少数，但看那干练坚决，百折不回的气概，曾经屡次为之感叹。至于这一回在弹雨中互相救助，虽殒身不恤的事实，则更足为中国女子的勇毅，虽遭阴谋秘计，压抑至数千年，而终于没有消亡的明证了。倘要寻求这一次死伤者对于将来的意义，意义就在此罢。”这样的文章都是用心，不，是用生命写成的。张溥若知三百年后有一鲁迅君执匕首般的笔尖写慷慨之情，不知作何感想？\n\n　　第五段是本文最精彩的一段。本段夹叙夹议，反复对比，将文章的中心升华到一个理性的高度。作者将“高爵显位”的辱人贱行，与五人的嘉节懿行比照论述，从而提出“轻重固何如哉”的问题让读者思考。接着，作者把五人的英勇就义与假设五人寿终正寝作对比，从而揭示出“亦以明死生之大，匹夫之有重于社稷也”这一富有进步性的观点。读者至此，是否联想到司马迁在《报任安书》中的那句名言──“人固有一死，或重于泰山，或轻于鸿毛。”五人之死，重于泰山，与日月同辉，与山河共存。\n\n　　第六段也用对比手法，但以“由是观之”领头，表明它与第五段不是机械的并列关系，而是由此及彼、层层深入的关系。“是”是一个指代词，指代第五段所论述的事实。从第五段所论述的事实看来，仗义而死与苟且偷生，其社会意义判若霄壤。作者以饱含讽刺的笔墨，揭露了“今之高爵显位”为了苟全性命而表现出来的种种“辱人贱行”，提出了一个问题：这种种“辱人贱行”，和“五人之死”相比，“轻重固何如哉”?苟且偷生，轻如鸿毛；仗义而死，重于泰山。这自然是作者希望得到的回答。\n\n　　在作了如上对比之后，作者又从正反两方面论述了“五人”之死所产生的另一种社会效果。从正面说，由于“五人”“发愤一击”、“蹈死不顾”而挫败了浊乱天下的邪恶势力，因而“得以加其土封，列其姓名于大堤之上。凡四方之士，无有不过而拜且泣者，斯固百世之遇也”。从反面说，“五人者保其首领以老于户牖之下，则尽其天年，人皆得以隶使之，安能屈豪杰之流，扼腕墓道，发其志士之悲哉?”应该指出：这不仅是就“五人”死后所得的光荣方面说的，而且是就“五人”之死在“四方之士”“豪杰之流”的精神上所产生的积极影响方面说的。“四方之士”“过而拜且泣”，“豪杰之流，扼腕墓道，发其志士之悲”，不正表现了对“五人”同情、仰慕乃至向他们学习的崇高感情吗?而号召人们向“五人”学习，继续跟阉党余孽作斗争，正是作者写这篇文章的目的。\n\n　　这篇文章题为《五人墓碑记》，歌颂“五人”当然是它的主要内容。但社会是复杂的，事物是互相联系的，要孤立地歌颂“五人”，就很难着笔。张溥在这篇文章中，与“五人”相对比，不仅指斥了阉党，还暴露批判了“富贵之子，慷慨得志之徒”和“缙绅”“高爵显位”等等；与“五人”相映衬，不仅赞美了周顺昌，还肯定了“郡之贤士大夫”。正是由于有了这一系列的对比和映衬，才充实了歌颂“五人”的思想内容，加强了歌颂“五人”的艺术力量。', poem_tags = '古文观止,高中文言文,赞颂,写人,碑记' WHERE poem_title = '五人墓碑记' AND poem_author = '张溥';
UPDATE edu_poem SET poem_translation = '风中的柳絮残飞到水面化作浮萍，河泥中的莲花虽然刚劲果断，但是它的茎却依然会丝丝萦绕不断。别离时拈一花瓣赠与对方，记念以前的事情。\n人们常说人多情了他的感情就不会很深，现在真的后悔以前的多情，回到以前伤心离别的地方，泪水禁不住悄悄流下来。', poem_notes = '泥莲句：泥莲，指荷塘中的莲花。倩，请、恳请。此处谓莲花被藕丝缠绕。\n别拈香一瓣：谓分别之时手中握着一瓣芳香的花。', poem_appreciation = '《山花子》这首词从“记前生”句可以看出，是写怀念亡妻的。这是残荷引发的怀人之作。\n\n　　上片前两句是荷塘败落的实写，以“飘残”而感知了季节之悲，同时也是人生之秋的写照。而泥莲被藕丝萦绕，既是实景，又是不绝的情思。后两句“珍重别拈香一瓣，记前生”，追忆当初，因景诱情，前生珍重，后世亦珍情。情重更见心苦。\n\n　　下片承上抒情，前两句化用杜牧诗句《赠别》“多情却似总无情”句意，“人到情多情转薄，而今真个悔多情”,作者后悔妻子在世的时候，没有对她深情相待，自觉对她薄情。因作者与妻卢氏结婚时，他心中还惦念着姓谢的表妹。自己因为对表妹谢氏的多情，而对卢氏薄情。如今想来人在的时候没有好好珍惜，而今人不在了，只有偷偷流泪的份了。“悔”字为反语，不悔之意。这是对于“情”的一种特殊感受，是更深沉得情的告白。后两句是真情的率性表露，“断肠”和“泪”恰是因多情而伤痛彻骨，凄苦惆怅。', poem_tags = '悼亡,写景,怀念' WHERE poem_title = '山花子·风絮飘残已化萍' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '桑乾河北边一场夜战，秦地士兵一半未能归营。\n早晨后方送来一位士兵的家信，告诉他寒衣已经寄来。', poem_notes = '桑乾（gān）北：桑乾河北岸。桑乾河，永定河的上游，发源于山西，流经华北平原。\n秦兵：唐都在关中，是秦朝旧地，所以称唐军为“秦兵”。半不归：一半回不来，指战死。\n乡信：家乡来信。\n犹自：仍然。寒衣：御寒的衣服。', poem_tags = '边塞,战争,同情' WHERE poem_title = '塞下曲' AND poem_author = '许浑';
UPDATE edu_poem SET poem_translation = '饥饿的老鼠绕着床窜来窜去，蝙蝠围着昏黑的油灯上下翻舞。狂风夹带着松涛，犹如汹涌波涛般放声呼啸；大雨瓢泼而下，急促地敲打着屋顶；糊窗纸被风撕裂，发出呼啦啦的声音，仿佛在自言自语。\n从塞北辗转江南，如今归隐山林，已是容颜苍老，满头白发。一阵凄冷的秋风吹透了单薄的布被，突然惊醒，眼前依稀还是梦中的万里江山。', poem_notes = '博山，在江西永丰境内（今江西省广丰县），古名通元峰，由于其形状像庐山香炉峰，所以改称博山。庵：圆形草屋。\n翻灯舞：绕着灯来回飞。\n“破纸”句：窗间破纸瑟瑟作响，好像自言自语。\n塞北：泛指中原地区。据《美芹十论》，词人自谓南归前曾受祖父派遣两次去燕京观察形势。归来：指淳熙八年（1181年）冬被劾落职归隐。华：花白，华发苍颜：头发苍白，面容苍老。\n“布被”两句：谓秋夜梦醒，眼前依稀犹是梦中的万里江山。', poem_tags = '宋词三百首,壮志难酬' WHERE poem_title = '清平乐·独宿博山王氏庵' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '我悄悄地倚栏凝望，雨已停歇，云已散去，目送着秋色消逝于天边。秋天的傍晚，景色萧瑟凄凉，真让人兴发宋玉悲秋之叹。轻风拂过水面，白蘋花渐渐衰残，凉月使露水凝住，梧桐树也禁不住月夜寒露的侵袭，叶子已片片枯黄。此情此景，不由人寂寞感伤。我的故朋旧友，不知你们都在何方？眼前所见只有一望无际的秋水，烟雾迷茫。\n文人的雅集，纵情的欢宴，如今仍历历在目，令人难忘。离别后辜负了多少风月时光，斗转星移，都只为你我相距遥远，天各一方。海是如此之遥，山是如此之遥，相逢相会不知何处何年？让人感到凄苦彷徨。想那双双飞去的燕子，难以靠它给故友传音送信；企盼故友归来，遥指天际苍茫，辨识归来航船，谁知过尽千帆皆不是，也是枉自空等企望。我默默伫立，黯然相望，只见斜阳已尽，孤雁哀鸣声仍在天际飘荡。', poem_notes = '玉蝴蝶，词牌名。此调有小令及长调两体，小令为唐温庭筠所创，双调，上片四句，押三平韵，二十一字；下片四句，押三平韵，二十字，共四十一字。长调始于宋人柳永，又称为“玉蝴蝶慢”，双调，九十九字，平韵。亦有九十八字体。\n雨收云断：雨停云散。\n萧疏：清冷疏散，稀稀落落。堪：可以。\n宋玉悲凉：指宋玉《九辩》，引申为悲秋。宋玉《九辩》有“悲哉！秋之为气也，萧瑟兮草木摇落而变衰！”\n蘋花：一种夏秋间开小白花的浮萍。\n遣情伤：令人伤感。遣：使得。\n文期酒会：文人们相约饮酒赋诗的聚会。期：约。\n几孤风月：辜负了多少美好的风光景色。几：多少回。孤：通“辜”，辜负。风月：美好的风光景色。\n屡变星霜：经过了好几年。星霜：星一年一周天，霜每年而降，因称一年为一星霜，亦以之喻年月也。\n潇湘：湘江的别称。这里指所思念的人居住的地方。\n暮天：傍晚时分。\n空：白白地。归航：返航的船。\n立尽斜阳：在傍晚西斜的太阳下立了很久，直到太阳落山。', poem_tags = '宋词精选,婉约,写景,怀人' WHERE poem_title = '玉蝴蝶·望处雨收云断' AND poem_author = '柳永';
UPDATE edu_poem SET poem_translation = '海棠枝间新长出的绿叶层层叠叠的，小花蕾隐匿其间微微泛出些许的红色。\n一定要爱惜自己那芳香的心，不要轻易地盛开，姑且让桃花李花在春风中尽情绽放吧！', poem_notes = '赋：吟咏。\n同儿辈赋句：和儿女们一起做关于还没开放的海棠花的诗。 \n一重重：一层又一层。形容新生的绿叶茂盛繁密。 \n小蕾：指海棠花的花蕾。 \n芳心：原指年轻女子的心。这里一语双关，一指海棠的花芯，二指儿辈们的心。 \n轻吐：轻易、随便地开放。 \n且教：还是让。 \n闹春风：在春天里争妍斗艳。', poem_appreciation = '诗句写了深藏于重重新绿之中的、尚未开放而仅仅是“数点红”的海棠蓓蕾。诗人忠告它“爱惜芳心”，不要轻易地吐蕾。那么，诗人为什么要如此深情地忠告？也许，诗人想到了，如果一旦开放，几场风雨之后，花就会很快坠落、凋零，“林花谢了太匆匆”，为了它的不至于很快谢落，为了它的长久，诗人宁愿红蕾深藏。也许，诗人想得更深，认为真正的“芳心”是不应该轻易吐露的，像桃李那样在春风中追逐、嬉闹，只是一种炫耀，一种浅薄的表现。诗人不希望像“桃李卖阳艳”，希望“慎勿作桃李”（李白《赠韦侍御黄裳》）。总之，诗句虽然用语平易，却意味醇厚，耐人咀嚼，留给我们很多的思考。诗人曾经说过：“动可以周万物而济天下，静可以崇高节而抗浮云。”（《新斋赋》）诗人作此诗时已入暮年，时金已灭亡，他回到了自己的故乡，抱定了“今是中原一布衣”（《为邓人作诗》）、“衰年那与世相关”（《已卯端阳日感怀》）的态度，过着遗民生活，他自觉已无能周济天下，于是只能坚守自己节操，独善其身。诗人也许从一个侧面，借告诫未开之海棠，不要轻易吐露花蕊，寄托了自己的这种心态。\n\n　　海棠花比桃花、李花开得晚，而且花朵儿红白相间，色彩淡雅，深藏在浓密的绿叶之中，并不起眼，不像桃花、李花那样，在春天争相开放，吸引人们的眼球。诗人通过对海棠的描述，赞美海棠洁身自爱，甘于清静的品性。\n\n　　它的清新，它的传神，它的志趣，无一不感动着我。公历四月上、中旬，正是百花盛开的时候。当然，最早开放的是桃杏了。故有“占断春风是此花”（唐·白敏中）和“红杏枝头春意闹”（宋·宋祁）的歌咏。海棠，开放略晚，先叶后花。当那嫩绿的叶片重重叠起的时候，它的花蕾也才刚刚绽裂花萼，露出花瓣的点点鲜红。作者所赋的就是这时的海棠。我特别赞叹作者抓取的时机是那么的准确，观察的是如此细致！然而作者的本意却在后面两句，赞扬海棠的矜持高洁，不趋时，不与群芳争艳。这正是作者自己精神的写照。\n\n　　作者以一首海棠诗暗示、告诫自己的儿女们要稳重行事，要像海棠一样不轻易显露自己的芳心，保持自己内心的纯洁。\n\n　　“芳心”是一个双关词语，一层意思是海棠花的花心。另一层是儿女的爱慕之心。', poem_tags = '古诗三百首,咏物,写花,寓人,劝诫' WHERE poem_title = '同儿辈赋未开海棠' AND poem_author = '元好问';
UPDATE edu_poem SET poem_tags = '抒情,思乡,孤寂' WHERE poem_title = '风入松·危楼古镜影犹寒' AND poem_author = '张炎';
UPDATE edu_poem SET poem_translation = '万壑古树高耸云天，千山深处杜鹃啼啭。\n山中春雨一夜未停，树丛梢头流淌百泉。\n汉女辛劳织布纳税，巴人地少诉讼争田。\n望你发扬文翁政绩，奋发有为不负先贤。', poem_notes = '梓州：《唐诗正音》作“东川”。梓州是隋唐州名，治所在今四川三台。李使君：李叔明，先任东川节度使、遂州刺史，后移镇梓州。\n壑（hè）：山谷。\n杜鹃：鸟名，一名杜宇，又名子规。\n一夜雨：一作“一半雨”。\n树杪（miǎo）：树梢。\n汉女：汉水的妇女。橦（tóng）布：橦木花织成的布，为梓州特产。\n巴：古国名，故都在今四川重庆。芋田：蜀中产芋，当时为主粮之一。这句指巴人常为农田事发生讼案。\n文翁：汉景时为郡太守，政尚宽宏，见蜀地僻陋，乃建造学宫，诱育人才，使巴蜀日渐开化。翻：翻然改变，通“反”。\n先贤：已经去世的有才德的人。这里指汉景帝时蜀郡守。', poem_appreciation = '赠别之作，多从眼前景物写起，即景生情，抒发惜别之意。王维此诗，立意则不在惜别，而在劝勉，因而一上来就从悬想着笔，遥写李使君赴任之地梓州的自然风光，形象逼真，气韵生动，令人神往。\n\n　　开头两句互文见义，起得极有气势：万壑千山，到处是参天的大树，到处是杜鹃的啼声。既有视觉形象，又有听觉感受，读来使人恍如置身其间，大有耳目应接不暇之感。这两句气象阔大，神韵俊迈，被后世诗评家引为律诗工于发端的范例。“万壑树参天，千山响杜鹃”，以如椽大笔，淋漓泼墨，勾勒出巴蜀层峦叠嶂的群山、无数险峻深邃的岩壑、高耸云天的林木，同时还有一片杜鹃热闹如沸的啼鸣，使万壑千岩为之振响。如同展开一卷气势磅礴的山水画，令人为之一振。紧接着的“山中一半雨，树杪百重泉”，更扣紧蜀地山高林密、雨水充沛的特点，先描绘深山冥晦，千岩万壑中晴雨参半的奇景，再绘出雨中山间道道飞泉，悬空而下。诗人远远望去，泉瀑就如同从树梢上倾泻下来似的。这里生动地表现出远处景物互相重叠的错觉。诗人以画家的眼睛观察景物，运用绘法入诗，将三维空间的景物叠合于平面画幅的二维空间，若将最远处、高处的泉瀑画在稍近、稍低的树梢上。\n\n　　由此，就表现出山中景物的层次、纵深、高远，使画面富于立体感，把人带入一个雄奇、壮阔而又幽深、秀丽的境界。这一联的“山中”承首联的“山”，“树杪”承应首联的“树”，连接紧凑，天然工巧。无怪乎清代诗人王士禛击节称赞这四句诗，“兴来神来，天然入妙，不可凑泊”（《带经堂诗话》卷十八）。\n\n　　作者以欣羡的笔调描绘蜀地山水景物之后，诗的后半首转写蜀中民情和使君政事。梓州是少数民族聚居之地，那里的妇女，按时向官府交纳用橦木花织成的布匹；蜀地产芋，那里的人们又常常会为芋田发生诉讼。“汉女”“巴人”“橦布”“芋田”，处处紧扣蜀地特点，而征收赋税，处理讼案，又都是李使君就任梓州刺史以后所掌管的职事，写在诗里，非常贴切。最后两句，运用有关治蜀的典故。“文翁”是汉景帝时的蜀郡太守，他曾兴办学校，教育人才，使蜀郡“由是大化”（《汉书·循吏传》。王维以此勉励李使君，希望他效法文翁，翻新教化，而不要倚仗文翁等先贤原有的政绩，泰然无为。联系上文来看，既然蜀地环境如此之美，民情风土又如此之淳，到那里去当刺史，自然更应当克尽职事，有所作为。寓劝勉于用典之中，寄厚望于送别之时，委婉而得体。\n\n　　《送梓州李使君》作为一首送别诗来看，它的艺术构思新颖奇特。诗中没有一句涉及送别之时、之地、之情、之事，全篇都是描绘巴蜀的山水、风情和民事。然而读后深思，就会发觉此诗紧紧围绕李氏即将赴任的梓州步步展开，层层深入，全诗融注着诗人对李氏欣羡、期望、劝勉的一腔真情，前后融会贯通，结构谨严缜密。前两联描绘巴蜀雄秀山川风光，景因情生，流露出诗人对梓州风光的热烈向往，对李氏即将前往赴任的无限欣羡。第三联有极强的概括力，既表现了蜀地的物产、民风，也说明蜀地僻远经济落后，人民穷困而且缺乏教化，这就含蓄地提醒李使君，治蜀并非易事，而是任重道远。这一联还为尾联埋下伏笔，使诗人劝勉李使君的话更显得切实而不空洞。尾联则顺势而下，勉励李使君以汉代蜀郡太守文翁为榜样，在梓州重施教化，翻新吏治，大展宏图。诗人以文翁来比李使君，用典贴切，切人，切事，切地，又能借以传达出自己真诚、殷切的期望之意，可谓用典妙笔。\n\n　　诗写送别，不写离愁别恨，不作浮泛客套之语，却有对于国家大事、民生疾苦、友人前途的深切关心。格调高远，爽利明快，在唐人送别诗中，堪称是一首构思别开生面、思想境界高远、读后令人振奋的佳作。', poem_tags = '唐诗三百首,友情,送别' WHERE poem_title = '送梓州李使君' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '从前吴起外出遇到了老朋友，就留他吃饭。老朋友说：“好啊，等我回来就（到你家）吃饭。”吴起说：“我（在家里）等待您一起进餐。”（可是）老朋友到了傍晚还没有来，吴起不吃饭而等候他。第二天早晨，（吴起）派人去找老朋友，老朋友来了，才同他一起进餐。吴起不吃饭而等候老朋友的原因是怕自己说了话不算数。他坚守信用到如此程度，这是能使军队信服的缘由吧！要想使军队信服，（作为将领）不守信用是不行的。', poem_notes = '昔：从前\n令：派；使；让\n方：才\n之：代词，指“老朋友”\n俟（sì）：等待\n恐：恐怕；担心\n可：行；可以\n信：信用\n故：先前的；原来的\n食：吃\n信：诚信\n止：留住\n求：寻找\n服：使……信服（意动用法）\n非信不可也：不守信用是不行的。 信，守信，讲信用\n吴起：战国初期著名的政治改革家，卓越的军事家、统帅、政治家、改革家。\n欤：语气词，吧\n其：他，指吴起\n宜：应该\n为：坚守\n明日：明天\n者：.....的原因', poem_tags = '小学文言文,诚信,故事' WHERE poem_title = '吴起守信' AND poem_author = '宋濂';
UPDATE edu_poem SET poem_translation = '雨后的晴天，风和日丽，雨水蒸发得无影无踪。小溪的河槽水流上涨，岸边丛生绿油油的野草，盛开着绚丽的野花。\n一个牧童躺在柳荫下，睡梦正甜。而那头牛只管埋头吃草，越走越远，直吃到柳林西面。', poem_notes = '桑茶坑：地名，在安徽泾县。\n草满花堤（dī）：此处倒装，即花草满堤。\n童子：儿童；未成年的男子。柳阴：柳下的阴影。诗文中多以柳阴为游憩佳处。', poem_appreciation = '此诗写的是桑茶道中所见的儿童牧牛情景，展现了夏日江南田野水边的景色。此诗诗中有画，意韵悠长。诗人撷取春末夏初田园憩息的小景，以作画法表现人与自然的和谐。每一句都是一幅画面，画面之间又是相互联系着。远景写意，着色粗放淋漓；近景写人，工笔勾勒，细致入微。\n\n　　此诗语言浅显易懂。首句写得平易，“晴明风日雨干时”，点明一个大晴天，雨后初晴之日，阳光透亮，风儿流畅，地面的积水正被阳光蒸发，被风儿吹干。一雨一晴，风调雨顺，又是农业生产的好时光。全句展示出的大自然不是死寂的，而是流动的。“草满花堤水满溪”，在这样好的气候条件下，小溪被雨水充盈了，水面和堤齐平，这种情景用“满”字是合适的，常见的；而以“满”字写堤上花儿草儿繁盛之状，原也不足为奇，但“满”在这里作为动词，仿佛青草有意识地去装点堤岸一般，这就生动有趣了。这样的“花堤”，正是放牛的好去处啊。于是，诗人的眼睛发现了“童子柳阴眠正着”，童子在柳树的浓荫下酣睡。在诗的节奏上，第三句是个顿挫。前两句写的是自然界景物，都充满生气和动态，到了最有生命力的人（又是活泼可爱的孩子），却呼呼大睡，一动不动。轻快的诗歌节奏在这里仿佛停了下来，放慢了速度。然而，情绪上的顿挫，是为了推出第四句“一牛吃过柳阴西。”童子的牛在哪儿呢？牛儿吃着吃着，已经挪到了柳阴的西边去了。因为牧童的安然静止睡眠，使牛儿得以自由自在地吃草，悠然地动着。画面因牛的活动，又活动起来。这样一静一动，和谐自然。这里把牧牛童子和牛的神态写活了，富有生活气息。\n\n　　这首诗前两句写出了由雨而晴，由湿而干，溪水由浅而满，花草于风中摇曳，大自然充满了生机的律“动”；第三句写出了牧童柳荫下酣睡的自然悠闲的“静”，加上第四句“一牛吃过柳阴西”的时动时静，形成了这首诗独特的生活情趣和原始朴素的美感。', poem_tags = '春天,写景,儿童,生活' WHERE poem_title = '桑茶坑道中' AND poem_author = '杨万里';
UPDATE edu_poem SET poem_tags = '儿童,讽刺' WHERE poem_title = '牧童词' AND poem_author = '李涉';
UPDATE edu_poem SET poem_tags = '小学文言文,写人,寓理,故事' WHERE poem_title = '截竿入城' AND poem_author = '邯郸淳 撰';
UPDATE edu_poem SET poem_translation = '傍山的日影忽然西落了，池塘上的月亮从东面慢慢升起。\n披散着头发在夜晚乘凉，打开窗户躺卧在幽静宽敞的地方。\n一阵阵的晚风送来荷花的香气，露水从竹叶上滴下发出清脆的响声。\n正想拿琴来弹奏，可惜没有知音来欣赏。\n感慨良宵，怀念起老朋友来，整夜在梦中也苦苦地想念。\n\n韵译\n夕阳忽然间落下了西山，东边池角明月渐渐东上。\n披散头发今夕恰好乘凉，开窗闲卧多么清静舒畅。\n清风徐徐送来荷花幽香，竹叶轻轻滴下露珠清响。\n心想取来鸣琴轻弹一曲，只恨眼前没有知音欣赏。\n感此良宵不免怀念故友，只能在夜半里梦想一场。', poem_notes = '山光：傍山的日影。\n池月：池边的月色。\n东上：从东面升起\n开轩：开窗。\n卧闲敞：躺在幽静宽敞的地方。\n恨：遗憾。\n感此：有感于此。\n中宵：整夜。\n劳：苦于。\n梦想：想念。', poem_appreciation = '此诗载于《全唐诗》卷一百五十九。下面是四川诗词学会理事、四川大学文学与新闻学院教授周啸天对此诗的赏析。\n\n　　孟浩然诗的特色是“遇景入咏，不拘奇抉异”（皮日休），虽只就闲情逸致作清描淡写，往往能引人渐入佳境。《夏日南亭怀辛大》就是有代表性的名篇。\n\n　　诗的内容可分两部分，既写夏夜水亭纳凉的清爽闲适，同时又表达对友人的怀念。“山光忽西落，池月渐东上”，开篇就是遇景入咏，细味却不止是简单写景，同时写出诗人的主观感受。“忽”、“渐”二字运用之妙，在于它们不但传达出夕阳西下与素月东升给人实际的感觉（一快一慢）；而且，“夏日”可畏而“忽”落，明月可爱而“渐”起，只表现出一种心理的快感。“池”字表明“南亭”傍水，亦非虚设。\n\n　　近水亭台，不仅“先得月”，而且是先退凉的。诗人沐浴之后，洞开亭户，“散发”不梳，靠窗而卧，使人想起陶潜的一段名言：“五六月中北窗下卧，遇凉风暂至，自谓是羲皇上人。”（《与子俨等疏》）三四句不但写出一种闲情，同时也写出一种适意——来自身心两方面的快感。\n\n　　进而，诗人从嗅觉、听觉两方面继续写这种快感：“荷风送香气，竹露滴清响。”荷花的香气清淡细微，所以“风送”时闻；竹露滴在池面其声清脆，所以是“清响”。滴水可闻，细香可嗅，使人感到此外更无声息。诗句表达的境界宜乎“一时叹为清绝”（沈德潜《唐诗别裁》）。写荷以“气”，写竹以“响”，而不及视觉形象，恰是夏夜给人的真切感受。\n\n　　“竹露滴清响”，那样悦耳清心。这天籁似对诗人有所触动，使他想到音乐，“欲取鸣琴弹”了。琴，这古雅平和的乐器，只宜在恬淡闲适的心境中弹奏。据说古人弹琴，先得沐浴焚香，屏去杂念。而南亭纳凉的诗人此刻，已自然进入这种心境，正宜操琴。“欲取”而未取，舒适而不拟动弹，但想想也自有一番乐趣。不料却由“鸣琴”之想牵惹起一层淡淡的怅惘。象平静的井水起了一阵微澜。相传楚人钟子期通晓音律。伯牙鼓琴，志在高山，子期品道：“峨峨兮若泰山”；志在流水，子期品道：“洋洋兮若流水。”子期死而伯牙绝弦，不复演奏。（见《吕氏春秋·本味》）这就是“知音”的出典。由境界的清幽绝俗而想到弹琴，由弹琴想到“知音”，而生出“恨无知音赏”的缺憾，这就自然而然地由水亭纳凉过渡到怀人上来。\n\n　　此时，诗人是多么希望有朋友在身边，闲话清谈，共度良宵。可人期不来，自然会生出惆怅。“怀故人”的情绪一直带到睡下以后，进入梦乡，居然会见了亲爱的朋友。诗以有情的梦境结束，极有余味。\n\n　　孟浩然善于捕捉生活中的诗意感受。此诗不过写一种闲适自得的情趣，兼带点无知音的感慨，并无十分厚重的思想内容；然而写各种感觉细腻入微，诗味盎然。文字如行云流水，层递自然，由境及意而达于浑然一体，极富于韵味。诗的写法上又吸收了近体的音律、形式的长处，中六句似对非对，具有素朴的形式美；而诵读起来谐于唇吻，又“有金石宫商之声”（严羽《沧浪诗话》）。', poem_tags = '唐诗三百首,夏天,怀人,友情' WHERE poem_title = '夏日南亭怀辛大' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '中秋的时候，捣衣声混杂着风声，蟠蟀好像在思索高爽的秋天。我面对着这样的景象，是不会学宋玉去纾解悲愁的。把凄凉的心意收拾起来，给每个酒樽里都倒上美酒，内心更加觉得抵不过这样的幽静。明月挂在南楼正是我觉得充满情趣的地方所在。\n怅惘这样的胸怀，于是拿起笛子吹奏，笛声的韵律悠悠扬扬。在这清平之时，良美之夜，就把这块地方借给我让我痛饮。看着这一天可爱的风景，我倚着曲曲折折的栏杆，宇宙在我眼里也只是小小的浮萍。喝醉困乏了就靠着枕头临江而睡，不知道什么时候会醒来。', poem_notes = '砧声：也作“碪声”，捣衣声。元好问《短日》：短日碪声急，重云雁影深。\n蟠蟀：蟋蟀的一种，宋代顾逢曾作《观鬭蟠蟀有感》。\n高秋：天高气爽的秋天。\n宋玉解悲秋：宋玉《九辨》：悲哉秋之为气也，萧瑟兮草木摇落而变衰。\n兴况：情趣，意趣。\n分付：分别付予，这里指给酒樽分别倒酒。\n醽醁（líng lù）：古代的一种美酒。\n清时：清平之时，也指太平盛世。\n金瓯（ōu）：酒杯的美称。瓯，杯子。\n阑干十二：曲曲折折的栏杆。阑干，即栏杆。十二，形容曲折之多。\n欹（qī）:斜倚着，斜靠。', poem_tags = '中秋节,饮酒,抒情' WHERE poem_title = '水调歌头·中秋' AND poem_author = '米芾';
UPDATE edu_poem SET poem_translation = '年年岁岁戍守金河保卫玉关，日日夜夜挥舞马鞭手握刀环。\n时届暮春白雪飘飞归来塞外，万里奔波渡过黄河绕过黑山。', poem_notes = '岁岁：年复一年，年年月月。金河：即黑河，在今呼和浩特市城南。玉关：即甘肃玉门关。\n朝（zhāo）朝：每天，日日夜夜。马策：马鞭。刀环：刀柄上的铜环，喻征战事。\n三春：春季的三个月或暮春，此处指暮春。青冢（zhǒng）：西汉时王昭君的坟墓，在今内蒙古呼和浩特之南，当时被认为是远离中原的一处极僻远荒凉的地方。传说塞外草白，惟独昭君墓上草色发青，故称青冢。\n黑山：一名杀虎山，在今内蒙古呼和浩特市东南。', poem_appreciation = '这是一首传诵极广的边塞诗。诗中写到的金河、青冢、黑山，都在今内蒙古自治区境内，唐时属单于都护府。由此可以推断，这首诗写的是一个隶属于单于都护府的征人的怨情。全诗四句，一句一景，表面上似乎不相连属，实际上却统一于“征人”的形象，都围绕着一个“怨”字铺开。\n\n　　前两句就时记事，说的是：年复一年，东西奔波，往来边城；日复一日，跃马横刀，征战不休。金河在东而玉门关在西，相距很远，但都是边陲前线。马策、刀环虽小而微，然而对于表现军中生活来说却有典型性，足以引起对征戍之事的一系列的联想。这两句“岁岁”“朝朝”相对，“金河”“玉关”，“马策”“刀环”并举，又加以“复”字、“与” 字，给人以单调困苦、不尽无穷之感，怨情自然透出。\n\n　　前两句从“岁岁”说到“朝朝”，似乎已经把话说尽。然而对于满怀怨情的征人来说，这只是说着了一面。他不仅从那无休止的时间中感到怨苦之无时不在，而且还从即目所见的景象中感到怨苦之无处不有，于是又有三、四句之作。\n\n　　“青冢”是王昭君的坟墓，在今呼和浩特市境内，当时被认为是远离中原的一处极僻远荒凉的地方。传说塞外草白，惟独昭君墓上草色发青，故称青冢。时届暮春，在苦寒的塞外却 “春色未曾看”，所见者唯有白雪落向青冢而已。萧杀如此，令人凄绝。末句写边塞的山川形势：滔滔黄河，绕过沉沉黑山，复又奔腾向前。黄河和黑山相隔甚远，这里不可坐实理解。上句说青冢，这里自然想起青冢附近的黑山，并用一个“绕”字牵合，寄寓绵绵怨情。这两句写景，似与诗题无关，其实都是征人常见之景，常履之地，因而从白雪青冢与黄河黑山这两幅图画里，读者不仅看到征戍之地的寒苦与荒凉，也可以感受到征人转战跋涉的苦辛。诗虽不直接发为怨语，而蕴蓄于其中的怨恨之情足以使人回肠荡气。\n\n　　此诗通篇不着一个“怨”字，却又处处弥漫着怨情。诗人抓住产生怨情的缘由，从时间与空间两方面落笔，让“岁岁”“朝朝”的戎马生涯以及“三春白雪”与“黄河”“黑山”的自然景象去现身说法，收到了“不着一字，尽得风流”（司空图《二十四诗品》）的艺术效果。而这首诗的谨严工整也历来为人称道。诗不仅每句自对（如首句中的“金河” 对“玉关”），又两联各自成对。后一联的对仗尤其讲究：数字对（“三”“万”）与颜色对（“白”“青”“黄”“黑”）同时出现在一联之中；颜色对中，四种色彩交相辉映，使诗歌形象富于色泽之美；动词“归”“绕”对举，略带拟人色彩，显得别具情韵。这样精工的绝句，确是不多见的。', poem_tags = '唐诗三百首,黄河,边塞' WHERE poem_title = '征人怨 / 征怨' AND poem_author = '柳中庸';
UPDATE edu_poem SET poem_translation = '华山的上面只有青天，世上更是找不到和它齐平的山。\n在山顶抬头就能看到红色的太阳有多近，回头看甚至觉得白云都很低。', poem_notes = '与齐：与之齐的省略，即没有山和华山齐平。\n举头：抬起头。李白《静夜思》举头望明月，低头思故乡。\n回首：这里作低头，与“举头”相对应。', poem_appreciation = '《咏华山》是宋朝宰相寇准七岁时咏诵的一首诗。诗的大意是：除了蓝天，远远近近的山都在华山脚下。太阳显得那么近，山腰间飘着朵朵白云。\n\n　　寇准是北宋时期稀世神童，聪慧过人。他咏的这首诗，缘境构诗，诗与境谐。孩子的诗是即景即情之作，与先前的爬山描写投榫合缝，都突出了华山的高峻陡峭，气势不凡，显得贴合山势，准确传神，应该说是难能可贵了。\n\n　　据记载，寇准小时候，其父大宴宾客，饮酒正酣，客人请小寇准以附近华山为题，作《咏华山》诗，寇准在客人面前踱步思索，一步、二步，到第三步便随口吟出一首五言绝句：“只有天在上，更无山与齐。举头红日近，回首白云低。”比世人皆知的曹植七步成诗还要快出许多，真是才思敏捷，出口成章。', poem_tags = '咏物,写山' WHERE poem_title = '咏华山' AND poem_author = '寇准';
UPDATE edu_poem SET poem_translation = '月亮出来多明亮，美人仪容真漂亮。身姿窈窕步轻盈，让我思念心烦忧。\n月亮出来多洁白，美人仪容真姣好。身姿窈窕步舒缓，让我思念心忧愁。\n月亮出来光普照，美人仪容真美好。身姿窈窕步优美，让我思念心烦躁。', poem_notes = '皎：毛传：“皎，月光也。”谓月光洁白明亮。\n佼（jiǎo）：同“姣”，美好。“佼人”即美人。\n僚：同“嫽”，娇美。\n舒：舒徐，舒缓，指从容娴雅。\n窈纠：形容女子行走时体态的曲线美。\n劳心：忧心。\n悄：忧愁状。\n懰（liǔ）：音柳，妩媚。《埤苍》作“嬼”，妖冶。\n慅（cǎo）：忧愁，心神不安。\n燎：明也。一说姣美。\n夭绍：形容女子风姿绰绝。汉赋里往往写作“要绍”，曲貌。“窈纠”、“忧受”、“夭绍”都是形容女子行动时的曲线美，就是曹植《洛神赋》所谓“婉若游龙”。\n惨（zào）：当为“懆（cǎo）”，焦躁貌。《集传》：“惨当作懆，忧也。”', poem_appreciation = '关于诗的主题，《毛诗序》认为是讽刺陈国统治者“好色”，朱熹《诗集传》谓“此亦男女相悦而相念之辞”。高亨《诗经今注》认为描绘“陈国统治者，杀害了一位英俊人物”。多认为是月下相思的爱情诗。\n\n　　诗从望月联想到意中女子的美丽，想起她的面容，想起她的身姿，想起她的体态，越思越忧，越忧越思……深沉的相思，美人的绰绝，月夜的优美，构成了动人情景，又别是一番诗情画意了。\n\n　　“月出皎兮”，天上一轮圆月洒着皎洁的银辉，这夜色显得格外的美丽。这是写景，也是写情。这句交待了诗人活动的背景是在一个月光明丽的夜晚，这本身就富有很大的魅力和诱惑力，容易使人对景生情，发出许多美好的联想。同时，结合下句，这句又有着比兴的作用，以月光的美来比喻所爱人的美，是很恰贴的。“佼人僚兮”反映出这时在诗人的眼前，出现了一个娇美的女子，引起他无限的爱慕和情思。天上有着皎洁的月光，地上有着娇美的女子，此时此刻，此情此景，花好月圆，天惬人意。“舒窈纠兮”一句写诗人仔细端详女子时的感觉。在月光下，她不但显得容貌皎好，而且身材那么苗条、秀美，真让人神颠魄荡；而更吸引人的，是她还有一种气质美，她举止舒缓，雍容大方，性情安静，而这气比外表更富有魅力。“劳心悄兮”，此句是诗人自言其心情的烦闷。月光美，人更美，那窈窕的身姿象那雍容的举止，使得诗人一见钟情，而又无从表白，因而生发出无限的忧愁和感慨。\n\n　　这首诗的景色描写很有特色，“月出皎兮”，“月出皓兮”，“月出照兮”，柔美的月光本身就有无限的情意，而让它作为背景来衬托，则女子的倩影愈发显得秀美。同时，月光朦胧下，一个线条优美的女子在缓缓起步，更增添了几分神秘的色彩，有一种朦胧美的韵味。所以，这一景色很富有画意，而画意又渗透了无限的诗情。\n\n　　《月出》的意境是迷离的。诗人思念他的情人，是从看到冉冉升起的皎月开始的。也许因为月儿总是孤独地悬在无垠的夜空，也许因为它普照一切，笼盖一切，所谓“隔千里兮共明月”（谢庄《月赋》），月下怀人的作品总给人以旷远的感觉。作者的心上人，此刻也许就近在咫尺，但在这朦胧的月光下，又似乎离得很远很远，真是“美人如花隔云端”（李白《长相思》）。诗人“虚想”着她此刻姣好的容颜，她月下踟躅的婀娜倩影，时而分明，时而迷茫，如梦似幻。\n\n　　《月出》的情调是惆怅的。全诗三章中，如果说各章前三句都是从对方设想，末后一句的“劳心悄兮”、“劳心慅兮”、“劳心惨兮”，则是直抒其情。这忧思，这愁肠，这纷乱如麻的方寸，都是在前三句的基础上产生，都由“佼人”月下的倩影诱发，充满可思而不可见的怅恨。其实这怅恨也已蕴含在前三句中：在这静谧的永夜，“佼人”月下独自地长久地徘徊，一任夜风拂面，一任夕露沾衣，她也是在苦苦地思念着自己。这真是“此时相望不相闻，愿逐月华流照君”（张若虚《春江花月夜》）。\n\n　　与迷茫的意境和惆怅的情调相适应。《月出》的语言是柔婉缠绵的。通篇各句皆以感叹词“兮”收尾，这在《诗经》中并不多见。“兮”的声调柔婉、平和，连续运用，正与无边的月色、无尽的愁思相协调，使人觉得一唱三叹，余味无穷。另外，形容月色的“皎”、“皓”、“照”，形容容貌的“僚”、“懰”、“燎”，形容体态的“窈纠”、“懮受”、“夭绍”，形容心情的“悄”、“慅”、“惨”，可谓一韵到底，犹如通篇的月色一样和谐。其中“窈纠”、“懮受”、“夭绍”俱为叠韵词，尤显缠绵婉约。\n\n　　望月怀人的迷离意境和伤感情调一经《月出》开端，后世的同类之作便源源不断，李白《送祝八》“若见天涯思故人，浣溪石上窥明月”，杜甫《梦太白》“落月满屋梁，犹疑见颜色”，常建《宿王昌龄隐处》“松际露微月，清光犹为君”，王昌龄《送冯六元二》“山月出华阴，开此河渚雾，清光比故人，豁然展心悟”，此类甚多，大抵出自《陈风》。不管它们如何变换着视角，变换着形式，变换着语言，但似乎都只是一种意境，一种情调，即迷离的意境，怅惘的情调。这种意境与情调，最早也可以追溯到《月出》。这些滥觞于《月出》的望月怀人诗赋作品，总能使人受到感动与共鸣，这也正如月亮本身，终古常见，而光景常新。', poem_tags = '诗经,月亮,怀人,民谣' WHERE poem_title = '诗经·陈风·月出' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '沿着汝河大堤走，采伐山楸那枝条。还没见到我夫君，忧如忍饥在清早。\n沿着汝河大堤走，采伐山楸那余枝。终于见到我夫君，请莫再将我远弃。\n鳊鱼尾巴色赤红，王室事务急如火。虽然有事急如火，父母穷困谁养活！', poem_notes = '遵：循，沿。汝：汝河，源出河南省。坟（fén）：水涯，大堤。\n条枚：山楸树。一说树干（枝曰条，干曰枚）。\n君子：此指在外服役或为官的丈夫。\n惄（nì）：饥，一说忧愁。调（zhōu）：又作“輖”，“朝”（鲁诗此处作“朝”字），早晨。调饥：早上挨饿，以喻男女欢情未得满足。\n肄（yì）：树砍后再生的小枝。\n遐（xiá）：远。\n鲂（fánɡ）鱼：鳊鱼。赬（chēng成）：浅红色。\n毁（huǐ）：火，齐人谓火为毁。如火焚一样。\n孔：甚。　迩（ěr）：近，此指迫近饥寒之境。', poem_appreciation = '这在诗之首章，“遵彼汝坟，伐其条枚”——在高高的汝河大堤上，有一位凄苦的妇女，正手执斧子砍伐山楸的树枝。其实已透露了消息，采樵伐薪，本该是男人担负的劳作，现 在却由织作在室的妻子承担了。读者不禁要问：她的丈夫究竟到哪里去了？竟就如此忍心让妻子执斧劳瘁！“未见君子，惄如调饥”二句的跳出，即隐隐回答了此中缘由：原来，她的丈夫久已行役外出，这维持生计的重担，若非妻子没有人能来肩负。“惄”者忧也，“调饥”者朝食未进也。满腹的忧愁用朝“饥”作比，自然只有饱受饥饿折磨的人们，方有的真切感受。那么，这倚徙“汝坟”的妻子，想必又是忍着饥饿来此伐薪的了，此为文面之意。“朝饥”还有一层意思，它在先秦时代往又被用来作男欢女爱的隐语。而今丈夫常年行役，他那可怜的妻子，享受不到丝毫的眷顾和关爱。这便是首章展示的女主人公境况：她孤苦无依、忍饥挨饿，大清早便强撑衰弱之身采樵伐薪。当凄凉的秋风吹得她衣衫飘飘，大堤上传送来一声声“未见君子，惄如调饥”的怆然叹息时，令人闻之而酸鼻。\n\n　　第二章诗情发生了意外的转折。“遵彼汝坟，伐其条肄”二句，不宜视为简单的重复：“肄”指树木砍伐后新长的枝条，它点示了女主人公的劳瘁和等待，秋往春来又捱过了一年。忧愁悲苦在岁月漫漫中延续，期待也许早已化作绝望，此刻却意外发现了“君子”归来的身影。于是“既见君子，不我遐弃”二句，便带着女主人公突发的欢呼涌出诗行。不过它们所包含的情感，似乎又远比“欢呼”要丰富和复杂：久役的丈夫终于归来，他毕竟思我、爱我而未将我远弃，这正是悲伤中汹涌升腾的欣慰和喜悦；但归来的丈夫还会不会外出，他是否还会将我抛在家中远去？这疑虑和猜思，难免又会在喜悦之余萌生；然而此次是再不能让丈夫外出的了，他不能将可怜的妻子再次远弃。这又是喜悦、疑虑中发出的深情叮咛了。如此种种，实难以一语写尽，却又全为“不我遐弃”四字所涵容——《国风》对复杂情感的抒写，正是如此淳朴而又婉曲。\n\n　　女主人公的疑虑并非多余。第三章开首两句，即以踌躇难决的丈夫口吻，无情地宣告了他还得弃家远役：正如劳瘁的鳊鱼曳着赤尾而游，在王朝多难、事急如火之秋，他丈夫不可能耽搁、恋家。形象的比喻，将丈夫远役的事势渲染得如此窘急，可怜的妻子欣喜之余，又很快跌落到绝望之中。当然，绝望中的妻子也未放弃最后的挣扎：“虽则如毁，父母孔迩！”这便是她万般无奈中向丈夫发出的凄凄质问：家庭的夫妇之爱，纵然已被无情的徭役毁灭；但是濒临饥饿绝境的父母呢，他们的死活不能不顾。\n\n　　全诗在凄凄的质问中戛然收结，征夫对此质问又能作怎样的回答。这质问其实贯串了亘古以来的整整一部历史：当惨苛的政令和繁重的徭役，危及每一个家庭的生存，将支撑“天下”的民众逼到“如毁”、“如汤”的绝境时，历史便往往充满了这样的质问。《周南·汝坟》在几经忧喜和绝望后发出的质问，虽然化作了结句中征夫的不尽沉默。但是读者却分明听到了此后不久历史所发出的巨大回音：那便是西周王朝的轰然崩塌。', poem_tags = '诗经,思念' WHERE poem_title = '国风·周南·汝坟' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '两朵芙蓉渐渐地红起，像美人半红的脸一样。恋恋不舍地特地为开一次。假说徐守没有这种感受，为什么这两朵芙蓉花不对别人开放？\n看见芙蓉在濛濛细雨中摇摆不止，劝徐守停止说喝满杯酒的话了。进一步问酒席前的东坡醉官，明年，芙蓉花开时，我们再为谁来敬一杯？', poem_notes = '孟亨之：孟震，东平人，曾中进土。\n拒霜：即木芙蓉。\n君猷：徐君猷，字大受，东海人，当时知黄州，苏轼贬黄州，君猷待之甚厚。\n两两轻红半晕腮：形容两朵芙蓉呈粉红色，像美人晕红的脸腮。晕腮，红脸。\n独：唯一，特地。回：量词。\n双花：两朵芙蓉花。\n低昂：前栽后仰。十分杯：满杯酒。\n尊前：酒席前。狂副使：东坡自称狂醉团练副使，无事可做的酒官。\n来岁：明年。', poem_appreciation = '上片，以拟人的手法，烘托徐守的美好人格和丰厚政绩。“两两轻红半晕腮，依依独为使君回”，推出一个动感镜头：如美人晕腮般的千瓣半白、半桃红的芙蓉花，特地甜甜地为徐守开放。作者总是以灵敏的眼光，丰富的感情，微妙的想象来观察、来体验客观世界，认为自然界的万事万物都有灵性，于是写进作品里，就能深深打动读者的心。作者用美丽、名贵的芙蓉花来敬赠一位“非使君莫可当此花”者，足见东坡对这位贤明的地方官的仰慕深情。“坐客喜笑”，人花通情。拟人之法，高超绝妙。“若道使君无此意，何为，双花不向别人开？”以设问的句式，更深透一层地把这种花如人意、花超人意的敬仰之情升华起来。“双花不向别人开？”这一过片问话结句，收而难止，留有余味，为下片的深化题旨作了铺垫。\n\n　　下片，“但看低昂烟雨里，不已，劝君休诉十分杯”，承上问话，由写芙蓉花的动人美貌、诱人感情到写芙蓉花感人精神、令人忘返：使君呀，好好地看看濛濛细雨中的芙蓉花，它在为你动情而翩翩起舞！劝君多喝几杯满杯酒表示谢意。“但”字一用，上下意蕴，一脉相通。“更向尊前狂副使，来岁，花开时节与谁来？”自问无答的三句话令人回味。东坡问：明年，芙蓉花开时节，我们与谁喝酒而来？芙蓉花与谁“依依”而开，答案便是余下的想象空间了。\n\n　　全词，采用拟人、设问的手法，强化了词的主观感情色彩。“双拒霜独向君猷而开”，景语含蓄，比直说更有意味。芙蓉花是那样的真情痴情，谁不为之动心。“来岁，花开时节为谁来？”用笔越曲，含情越深，留下了长久的回味。', poem_tags = '人格' WHERE poem_title = '定风波·两两轻红半晕腮' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '屈原遭到了放逐,在沅江边上游荡。他沿着江边走边唱，面容憔悴,模样枯瘦。渔父见了向他问道:“您不是三闾大夫么，为什么落到这步田地?“屈原说:“天下都是浑浊不堪只有我清澈透明（不同流合污）,世人都迷醉了唯独我清醒,因此被放逐。“\n　　渔父说:“圣人不死板地对待事物,而能随着世道一起变化。世上的人都肮脏,何不搅浑泥水扬起浊波，大家都迷醉了,何不既吃酒糟又大喝其酒?为什么想得过深又自命清高,以至让自己落了个放逐的下场?“\n　　屈原说:“我听说:刚洗过头一定要弹弹帽子,刚洗过澡一定要抖抖衣服。怎能让清白的身体去接触世俗尘埃的污染呢?我宁愿跳到湘江里,葬身在江鱼腹中。怎么能让晶莹剔透的纯洁,蒙上世俗的尘埃呢?“\n　　渔父听了,微微一笑,摇起船桨动身离去。唱道:“沧浪之水清又清啊,可以用来洗我的帽缨;沧浪之水浊又浊啊,可以用来洗我的脚。“便远去了,不再同屈原说话。', poem_notes = '既：已经，引申为“（在）……之后”。\n颜色:脸色。形容:形体容貌。\n三闾（lǘ)大夫:掌管楚国王族屈、景、昭三姓事务的官。屈原曾任此职。\n是以见放，是:这。以:因为。见：被。\n淈(gǔ):搅浑。\n餔：吃。糟:酒糟。歠(chuò):饮。醨(lí):薄酒。 成语：哺糟歠醨\n高举:高出世俗的行为。在文中与“深思“都是渔父对屈原的批评,有贬意,故译为(在行为上)自命清高。举,举动。\n沐：洗头。\n浴：洗身，洗澡。\n察察:皎洁的样子。\n汶(mén)汶:污浊。\n皓皓：洁白的或高洁的样子。\n莞尔：微笑的样子。\n鼓枻：摇摆着船桨。.鼓：拍打。枻(yì):船桨。\n沧浪：水名,汉水的支流,在湖北境内。或谓沧浪为水清澈的样子。“沧浪之水清兮“四句：这首《沧浪歌》也见于《孟子·离娄上》,二“吾“字皆作“我“字。\n濯：洗。\n缨：系帽的带子，在颔下打结。\n遂去，遂:于是。去:离开。\n不复与言，复:再。', poem_appreciation = '关于《渔父》的作者，历来说法不一。最早认定为屈原作的，是东汉王逸的《楚辞章句》。《楚辞章旬》是在西汉末年刘向编的《楚辞》的基础上作注。在《楚辞》中，《渔父》已作为屈原的二十五篇作品之一收入。据此，则认定屈原作《渔父》，又可上推至刘向时。后世认同屈原作《渔父》，影响较大的有南朝梁代萧统编的《昭明文选》和南宋朱熹的《楚辞集注》。但此说漏洞颇多。从外证来说，司马迁在《史记·屈贾列传》中引述《渔父》文字时，只是作为行文的一部分，而并非作为屈原的原作转引。王逸《楚辞章句》在明确指出“《渔父》者，屈原之所作也”之后，又说“楚人思念屈原，因叙其辞以相传焉”，则作者又非屈原而成了“楚人”。从内证来说，《渔父》中的屈原表示“宁赴湘流，葬于江鱼之腹中”，以下当是赴湘自沉的一幕，似不可能再有心绪用轻松的笔调续写“莞尔而笑”的渔父。何况全文采用第三人称，亦与屈原作为此文作者的身份不合。故近人一般都认为此文并非屈原所作。郭沫若说：“《渔父》可能是深知屈原生活和思想的楚人的作品。”(《屈原赋今译》)按之作品的实际，这一推断还是比较可信的。\n\n　　在第一部分中，屈原开始露面。文章交待了故事发生的背景、环境以及主人公的特定情况。时间是在“既放”之后，即屈原因坚持爱国的政治主张遭到楚顷襄王的放逐之后；地点是在“江潭”、“泽畔”，从下文“宁赴湘流”四字看来，当是在接近湘江的沅江或沅湘间的某一江边、泽畔；其时屈原的情况是正心事重重，一边走一边口中念念有词。文中以“颜色憔悴，形容枯槁”八字活画出屈原英雄末路、心力交瘁、形销骨立的外在形象。\n\n　　第二部分是文章的主体。在这部分中，渔父上场，并开始了与屈原的问答。对渔父不作外形的描述，而是直接写出他心中的两个疑问。一问屈原的身份：“子非三闾大夫与?”屈原曾任楚国的三闾大夫(官名)，显然渔父认出了屈原，便用反问以认定身份。第二问才是问话的重点所在：“何故至于斯?”落魄到这地步，当是渔父所没有料想到的。由此一问，引出屈原的答话，并进而展开彼此间的思想交锋。屈原说明自己被流放的原因是“举世皆浊我独清，众人皆醉我独醒”，即自己与众不同，独来独往，不苟合，不妥协。由此引出渔父的进一步的议论。针对屈原的自是、自信，渔父提出，应该学习“圣人不凝滞于物，而能与世推移”的榜样，并以三个反问句启发屈原“淈泥扬波”、“哺糟歠酾”，走一条与世浮沉、远害全身的自我保护的道路。他认为屈原不必要“深思高举”，从思想到行为无不高标独立，以致为自己招来流放之祸。渔父是一位隐者，是道家思想的忠实信徒。老子说：“和其光，同其尘。”(《老子》)庄子说：“虚而委蛇。”(《庄子·应帝王》，后世成语作“虚与委蛇”)渔父所取的人生哲学、处世态度，正是从老庄那里继承过来的。他所标举的“圣人”，指的正是老、庄一类人物。儒家的大圣人则说：“道不同，不相为谋。”(《论语·卫灵公》)坚持“苏世独立，横而不流”(《九歌·橘颂》)的高尚人格的屈原，对于渔父的“忠告”当然是格格不入的。他义正辞严地进一步表明了自己的思想、主张。他以“新沐者必弹冠，新浴者必振衣”的两个浅近、形象的比喻，说明自己洁身自好、决不同流合污的态度。又以不能以自己的清白之身受到玷污的两个反问句，表明了自己“宁赴湘流”，不惜牺牲性命也要坚持自己的理想。屈原在《离骚》中就曾旗帜鲜明地表示过：“亦余心之所善兮，虽九死其犹未悔!”“既莫足与为美政兮，吾将从彭咸之所居!”《渔父》中的屈原，正是这样一个始终不渝地坚持理想、不惜舍生取义的生活中的强者。司马迁将《渔父》的文字作为史料载入屈原的传记中，当也是有见于所写内容的真实性，至少是符合屈原一以贯之的思想性格的。\n\n　　全文的最后一部分，笔墨集中在渔父一人身上。听了屈原的再次回答，渔父“莞尔而笑”，不再答理屈原，兀自唱起“沧浪之水清兮”的歌，“鼓枻而去”。这部分对渔父的描写十分传神。屈原不听他的忠告，他不愠不怒，不强人所难，以隐者的超然姿态心平气和地与屈原分道扬镳。他唱的歌，后人称之为《渔父歌》(宋人郭茂倩《乐府诗集》第八十三卷将此歌作为《渔父歌》的“古辞”收入)，也《沧浪歌》或《孺子歌》。歌词以“水清”与“水浊”比喻世道的清明与黑暗。所谓水清可以洗帽缨、水浊可以洗脚，大意仍然是上文“圣人不凝滞于物，而能与世推移”的意思，这是渔父和光同尘的处世哲学的一种较为形象化的说法。\n\n　　最后这一部分，不见于《史记》屈原本传中。从全篇结构来说，这一部分却是不可或缺的：它进一步渲染了渔父的形象；渔父无言而别、唱歌远去的结尾，也使全文获得了悠远的情韵。不少研究者认为《渔父》这篇作品是歌颂屈原的。但从全文的描写、尤其是从这一结尾中，似乎很难看出作者有专门褒美屈原、贬抑渔父的意思。《渔父》的价值在于相当准确地写出了屈原的思想性格，而与此同时，还成功地塑造了一位高蹈遁世的隐者形象。后世众多诗赋词曲作品中吟啸烟霞的渔钓隐者形象，从文学上溯源，都不能不使我们联想到楚辞中的这篇《渔父》。如果一定要辨清此文对屈原与渔父的感情倾向孰轻孰重，倒不妨认为他比较倾向于作为隐者典型的渔父。\n\n　　《渔父》是一篇可读性很强的优美的散文。开头写屈原，结尾写渔父，都着墨不多而十分传神；中间采用对话体，多用比喻、反问，生动、形象而又富于哲理性。从文体的角度看，在楚辞中，唯有此文、《卜居》以及宋玉的部分作品采用问答体，与后来的汉赋的写法已比较接近。前人说汉赋“受命于诗人，拓宇于楚辞”(刘勰《文心雕龙·诠赋》)，在文体演变史上，《渔父》无疑是有着不可忽视的重要地位的。', poem_tags = '楚辞,哲理,散文,故事' WHERE poem_title = '渔父' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '风和日丽的春天，摆起丰盛的酒宴。一杯美酒一曲歌呵，拜了又拜许三愿：一愿郎君你长寿千岁，二愿我身体永远康健，三愿我俩如同梁上燕呀，双双对对，幸福无边。', poem_notes = '长命女：唐教坊曲名用作词调名。全词39字，上片三句三仄韵，下片四句仄韵。\n绿酒：古时米酒酿成未滤时，面浮米渣，呈淡绿色，故名。\n妾身：古时女子队自己的谦称。\n岁岁：年年，即每年。', poem_appreciation = '这首词实际是祝酒词，描写春日开宴时，夫妇双方祝酒陈愿。前两愿分别祝郎君与自己长寿健康，第一愿以梁燕双柄喻夫妻团圆，天长地久。冯词三愿对于人问恩爱夫妇而苦则相当典型，主人公不求富贵．惟愿夫妇相守长久，意愿虽强而所求不奢，表现了古代女子对美满生活的追求。\n\n　　在具体描写上。本词不但通过人物的语言来抒情，而且通过相应的具体环境描写来烘托人物的思想感情。春日、绿酒、情歌、呢喃燕语，构成了极美的意境，对于爱情的抒写是极有力的烘托。\n\n　　整首词采用妇人口吻，语言清新明丽，语浅情深，可谓做到单纯与丰富富、平易与雅致高度统一，深得民歌精髓，化平凡为神奇，艺术效果奇妙。', poem_tags = '宋词三百首,婉约,夫妻,饮酒,祝愿' WHERE poem_title = '长命女·春日宴' AND poem_author = '冯延巳';
UPDATE edu_poem SET poem_translation = '残灯已没有火焰，周围留下模糊不清的影子，这时听说你被贬官九江。\n在垂死的重病中，我被这个消息震惊得忽的坐了起来。\n暗夜的风雨吹进我窗户，感觉分外寒冷。', poem_notes = '授：授职，任命。江州：即九江郡，治所在今江西省九江市。司马：官名。唐代以司马为州刺史的辅佐之官，协助处理州务。\n残灯：快要熄灭的灯。焰：火苗。幢（chuáng）幢：灯影昏暗摇曳之状。\n夕：夜。谪：古代官吏因罪被降职或流放。\n垂死：病危。', poem_appreciation = '此诗的中间两句是叙事言情，表现了作者在乍一听到这个不幸消息时的陡然一惊，语言朴实而感情强烈。诗的首尾两句是写景，形象地描绘了周围景物的暗淡凄凉，感情浓郁而深厚。\n\n　　元稹贬谪他乡，又身患重病，心境本来就不佳。此时忽然听到挚友也蒙冤被贬，内心更是极度震惊，万般怨苦，满腹愁思一齐涌上心头。以这种悲凉的心境观景，一切景物也都变得阴沉昏暗了。于是，看到“灯”，觉得是失去光焰的“残灯”；连灯的阴影，也变成了“幢幢”——昏暗的摇曳不定的样子。“风”，本来是无所谓明暗的，而今却成了“暗风”。“窗”，本来无所谓寒热的，而今也成了“寒窗”。只因有了情的移入，情的照射，情的渗透，连风、雨、灯、窗都变得又“残”又“暗”又“寒”了。“残灯无焰影幢幢”、“暗风吹雨入寒窗”两句，既是景语，又是情语，是以哀景抒哀情，情与景融会一体、“妙合无垠”。\n\n　　诗中“垂死病中惊坐起”一语，是传神之笔。白居易曾写有两句诗：“枕上忽惊起，颠倒着衣裳”，这是白居易在元稹初遭贬谪、前往江陵上任时写的，表现了他听到送信人敲门，迫不及待地想看到元稹来信的情状，十分传神。元稹此句也是如此。其中的“惊”，写出了“情”──当时震惊的感情；其中的“坐起”，则写出了“状”──当时震惊的模样。如果只写“情”不写“状”，不是“惊坐起”而是“吃一惊”，那恐怕就神气索然了。而“惊坐起”三字，正是惟妙惟肖地摹写出作者当时陡然一惊的神态。再加上“垂死病中”，进一步加强了感情的深度，使诗句也更加传神。既曰“垂死病中”，那么，“坐起”自然是很困难的。然而，作者却惊得“坐起”了，这样表明：震惊之巨，无异针刺；休戚相关，感同身受。元、白二人友谊之深，于此清晰可见。\n\n　　按照常规，在“垂死病中惊坐起”这句诗后，大概要来一句实写，表现“惊”的具体内涵。然而作者却偏偏来了个写景的诗句：“暗风吹雨入寒窗”。这样，“惊”的具体内涵就蕴含于景语之中，成为深藏不露、含蓄不尽的了。作者对白氏被贬一事究竟是惋惜，是愤懑，还是悲痛，全都没有说破，全都留给读者去领悟、想象和玩味了。\n\n　　元稹这首诗所写的，只是听说好友被贬而陡然一惊的片刻，这无疑是一个“有包孕的片刻”，也就是说，是有千言万语和多种情绪涌上心头的片刻，是有巨大的蓄积和容量的片刻。作者写了这个“惊”的片刻而又对“惊”的内蕴不予点破，这就使全诗含蓄蕴藉，情深意浓，诗味隽永，耐人咀嚼。\n\n　　元稹把他这首诗寄到江州以后，白居易读了非常感动。后来他在《与元微之书》中说 ：“此句他人尚不可闻，况仆心哉！至今每吟，犹恻恻耳。”像这样一首情景交融、形神俱肖、含蓄不尽、富有包孕的好诗，它是有很强的艺术魅力的。别人读了尚且会受到艺术感染，何况当事人白居易。', poem_tags = '友情,贬谪' WHERE poem_title = '闻乐天授江州司马' AND poem_author = '元稹';
UPDATE edu_poem SET poem_translation = '年、某月、某日，叔父韩愈在听说你去世后的第七天，才得以含着哀痛向你表达诚意，并派建中在远方备办了应时的鲜美食品作为祭品，告慰你十二郎的灵位：\n\n　　唉，我自幼丧父，等到大了，不知道父亲是什么模样，只有依靠兄嫂抚养。哥哥正当中年时就因与犯罪的宰相关系密切而受牵连被贬为韶州刺史，次年死于贬所 。我和你都还小，跟随嫂嫂把灵柩送回河阳老家安葬。随后又和你到江南谋生，孤苦伶丁，也未曾一天分开过。我上面本来有三个哥哥，都不幸早死。继承先父的后代，在孙子辈里只有你，在儿子辈里只有我。韩家子孙两代各剩一人，孤孤单单。嫂子曾经抚摸着你的头对我说：“韩氏两代，就只有你们两个了！”那时你比我更小，当然记不得了；我当时虽然能够记事，但也还不能体会她话中的悲凉啊！\n\n　　我十九岁时，初次来到京城参加考试。四年以后，才回去看你。又过了四年，我去河阳凭吊祖先的坟墓，碰上你护送嫂嫂的灵柩来安葬。又过了两年，我在汴州辅佐董丞相，你来探望我，留下住了一年，你请求回去接妻子儿女。第二年，董丞相去世，我离开汴州，你没能来成。这一年，我在徐州辅佐军务，派去接你的人刚动身，我就被免职，你又没来成。我想，你跟我在东边的汴州、徐州，也是客居，不可能久住；从长远考虑，还不如我回到家乡，等在那里安下家再接你来。唉！谁能料到你竟突然离我而死呢?当初，我和你都年轻，总以为虽然暂时分别，终究会长久在一起的。因此我离开你而旅居长安，以寻求微薄的俸禄。假如真的知道会这样，即使让我做高官厚禄的公卿宰相，我也不愿因此离开你一天而去赴任啊！\n\n　　去年，孟东野到你那里去时，我写给你的信中说：“我年纪还不到四十岁，但视力模糊，头发花白，牙齿松动。想起各位父兄，都在健康强壮的盛年早早去世，像我这样衰弱的人，难道还能长活在世上吗?我不能离开（职守），你又不肯来，恐怕我早晚一死，你就会有无穷无尽的忧伤。”谁能料到年轻的却先死了，而年老的反而还活着，强壮的早早死去，而衰弱的反而还活在人间呢?\n\n　　唉！是真的这样呢?还是在做梦呢?还是这传来的消息不可靠呢?如果是真的，那么我哥哥有（那么）美好的品德反而早早地绝后了呢?你（那么）纯正聪明反而不能承受他的恩泽呢?难道年轻强壮的反而要早早死去，年老衰弱的却应活在世上吗?实在不敢把它当作真的啊！如果是梦，传来的噩耗不是真的，可是东野的来信，耿兰的报丧，却又为什么在我身边呢?啊！大概是真的了！我哥哥有美好的品德竟然早早地失去后代，你纯正聪明，本来是应该继承家业的，现在却不能承受你父亲的恩泽了。这正是所谓苍天确实难以揣测，而神意实在难以知道了！也就是所谓天理不可推求，而寿命的长短无法预知啊！\n\n　　虽然这样，我从今年以来，花白的头发，全要变白了，松动的牙齿，也像要脱落了，身体越来越衰弱，精神也越来越差了，过不了多久就要随你死去了。如果死后有知，那么我们又能分离多久呢?如果我死后无知，那么我也不能悲痛多少时间了，而（死后）不悲痛的时间却是无穷无尽的。\n\n　　你的儿子才十岁，我的儿子才五岁，年轻强壮的尚不能保全，像这么大的孩子，又怎么能希望他们成人立业呢?啊，悲痛啊，真是悲痛！\n\n　　你去年来信说：“近来得了软脚病，时常（发作）疼得厉害。”我说：“这种病，江南人常常得。”没有当作值得忧虑的事。唉，（谁知道）竟然会因此而丧了命呢?还是由于别的病而导致这样的不幸呢?\n\n　　你的信是六月十七日写的。东野说你是六月二日死的，耿兰报丧时没有说日期。大概是东野的使者不知道向你的家人问明日期，而耿兰报丧竟不知道应该告诉日期?还是东野给我写信时，才去问使者，使者胡乱说个日期应付呢?是这样呢?还是不是这样呢?\n\n　　现在我派建中来祭奠你，安慰你的孩子和你的乳母。他们有粮食能够守丧到丧期终了，就等到丧期结束后再把他们接来；如果不能守到丧期终了，我就马上接来。剩下的奴婢，叫他们一起守丧。如果我有能力迁葬，最后一定把你安葬在祖坟旁，这样以后，才算了却我的心愿。\n\n　　唉，你患病我不知道时间，你去世我不知道日子，活着的时候不能住在一起互相照顾，死的时候没有抚尸痛哭，入殓时没在棺前守灵，下棺入葬时又没有亲临你的墓穴。我的行为辜负了神明，才使你这么早死去，我对上不孝，对下不慈，既不能与你相互照顾着生活，又不能和你一块死去。一个在天涯，一个在地角。你活着的时候不能和我形影相依，死后魂灵也不在我的梦中显现，这都是我造成的灾难，又能抱怨谁呢?天哪，（我的悲痛）哪里有尽头呢?从今以后，我已经没有心思奔忙在世上了！还是回到老家去置办几顷地，度过我的余年。教养我的儿子和你的儿子，希望他们成才；抚养我的女儿和你的女儿，等到她们出嫁，（我的心愿）如此而已。\n\n　　唉！话有说完的时候，而哀痛之情却不能终止，你知道呢?还是不知道呢?悲哀啊！希望享用祭品吧！\n\n　　（转自人民教育出版社）▲', poem_appreciation = '全篇三大段之间，不但自有有机联系，而且一段之中，又分若干小段，小段之中，又有若干层次，层次当中，还有不少转折。以第二大段的前半段为例。一开始，作者先不直接写十二郎，而是先写自己。“吾年未四十”四句，是衰象，后来被传颂为写未老先衰的名句，这是一层。“念诸父与诸兄，皆康强而早世”，是长辈的例子，又是一层。以下四句，一句写一层意思，说明自己将死，要十二郎早来相会。这是第一小段。下面“孰谓”两句一转，便过到十二郎之死。这种写法，是上文为下文蓄势，也就是用自己之将死而竟不死，反衬出十二郎之不应死而竟死的特别可哀。“少者殁而长者存，强者夭而病者全”，这不合情理，太使人悲哀，在这个巨大的打击下，作者神志恍惚，不相信这是事实，所以下面紧接着一转，发出三个疑问，“其信然邪?其梦邪?其传之非其真邪?”然后从信说到疑，一层；从疑又说到信，又一层；最后把十二郎之死归咎于天，归咎于神，归咎于理，得出“寿者不可知”的结论。这是第二小段。从文意讲，十二郎之死，于此已经写完，此段已可结束，但“虽然”两字一转，又上承开头“而发苍苍”一段而翻进一层，写自己的衰象更加严重，又回到自己之将死。“几何不从汝而死也”，是说自己不久也要跟在十二郎的后面死去，讲的本来是一件不幸的事，可是下面突然一转，又变成了幸事──“死而有知，其几何离?其无知，悲不几时，而不悲者无穷期矣。”作者已经痛不欲生，所以视死为幸了。这是第三小段。文章至此，已将作者和十二郎两个方面讲尽，但作者还不结束，又上承第二小段写二人之子之难保。这是第四小段。以上可以看出，短短一段当中，层次转换，变化无穷，有如万水回环，千峰合抱。而这一切在作者说来，不过是将情将事如实叙写，并未有意去精心结撰，过接转换，显得非常自然，看不出丝毫造作之迹。这种不刻意追求结构而结构自妙，在古今都是不可多得的。\n\n　　除了结构方面有韩文的共同特点之外，此文还有它独具的显著特色。\n\n　　读完这篇祭文，我们最突出的一个感觉，就是全篇自始至终，贯注着一个“情”字。“言有穷而情不可终”，作者在此文结尾的这句话，表明它是因情而写，所写皆情，整篇祭文都是作者用感情所写成的。\n\n　　韩愈三岁丧父母，由兄嫂（也就是十二郎的父母）抚养成人，他和十二郎，虽为叔侄，实同兄弟，从小生活在一起，“零丁孤苦，未尝一日相离”，感情特别深厚。十二郎的死，使他悲痛欲绝，也勾起他的辛酸回忆。身世的不幸，家世的凄凉，父母的早逝，兄嫂的抚养，从前同十二郎一起生活的种种情景，都一齐涌上心头；自己的衰病，子孙辈的幼小，这是眼前必须正视的现实。所有这一切，汇成一股感情的激流，作者悲感万端，百思萦集，情不能已，因而写成此文。这里有怀念，有感激，有悔恨，有哀愤，有内咎，有期望，全篇每句每字，都可看到作者感情的奔流。\n\n　　此文不但全篇写情，而且写得非常真，非常深，历来被称为“至情”之文。作者从自己的不幸身世，说到同十二郎的情谊，说到十二郎之死和善后事宜，不加修饰，不作渲染，完全从肺腑中流出，全都是骨肉至情的真实流露。开头的“少孤”“兄殁”“吾与汝俱幼”，看去似乎很平淡，却饱含着作者的无限辛酸和眼泪，写得很沉痛。嫂嫂的惨不忍闻的话和“抚汝指吾”的慈爱而又凄楚的神情，对自己离家谋生的深沉悔恨，得知十二郎死讯后的悲痛心情，也无不情真语真，悲酸无限。我们还可看到，作者抒写时非常坦率，想到什么就写什么，心里怎么想，笔下就怎么写，没有丝毫隐避，一任感情自然倾泻。例如写自己离家的目的，明白地说是以“求斗升之禄”，要是别人，恐怕就不会这样直截了当，很可能不是闭口不说，就是另外安上一个什么冠冕堂皇的名目。想到二人之子，说：“少而强者不可保，如此孩提者，又可冀其成立耶?”按照旧时的忌讳，这样的话是不吉利的，由此正可看出作者此时悲痛至极，因而什么也不顾忌了。末尾将十二郎之死完全归罪于自己，说自己“行负神明”“不孝不慈”，更是披肝沥胆的恸哭长号。清代叶燮论诗文，有重“胆”之说：“无胆则笔墨畏缩”，“欲言而不能言，或能言而不敢言”（《原诗》）。韩愈此文，正称得上有胆，他既敢打破祭文的传统形式，又敢无话不说，所以才写出这篇千古传颂之作。\n\n　　不仅如此，我们细读全文，还可看到作者感情的起伏变化。篇中用“呜呼”“呜呼哀哉”这两个悲叹词，来表现这种变化情态，凡是用这种词的地方，都表示感情变得更加强烈。从第一个“呜呼”开始，可以看到，作者由含着眼泪的深沉倾诉，进而呜咽抽泣，进而泪流满面，至“汝之子始十岁”一段之末，连用两个“呜呼哀哉”，已经是号啕痛哭，感情发展到一个高潮。从“呜呼！汝病吾不知时”至“‘彼苍者天’，‘曷其有极’”，这个长句，声调急促，一气贯注，一句紧接一句，一字紧接一字，中间不能断开，简直就是顿足捶胸，呼天抢地，悲痛之情发展到最高点。值得注意的是，这种发展，并不是直线的，在一度激烈之后，又伴随着一段虽然悲切但却较为平静的倾诉，这样或高或低，或疾或徐，就像生活中的真实情况一样。结尾“言有穷而情不可终”，使人感到祭文已完，作者仍然悲哭不已。《古文观止》的编选者说道：“情之至者，自然流为至文。读此等文，须想其一面哭，一面写，字字是血，字字是泪。”这话是很有见地的。确实，读这篇祭文，我们不但可以看到作者眼泪纵横的模样，还可听到作者痛哭的声音。正因为如此，千百年来，不知有多少读者被它所打动。宋代大作家苏轼曾说，“读韩退之《祭十二郎文》而不堕泪者，其人必不友”，可见它感人之深。\n\n　　正是为了抒情，此文在写法上也有着与一般祭文显著不同的一个特色：通篇以汝吾（你我）相称，好像同亡者家常对语一样，读来特别真切感人。开篇“告汝十二郎之灵”，作者不像一般祭文用“祭”字，而特别用一“告”字，意思是说：我在对你说话，你听着啊。这就使读者先留下一个印象：下面的话都是作者向十二郎的倾诉。\n\n　　把此文同韩愈以前和以后其他许多祭文比照读读，就会产生这样一个感觉：其他那些祭文，祭的是“死人”，文中内容大多是赞颂死者的功业或德行，俨如对死者一生的评论，祭的是死者，实际上是讲给其他活着的人听。旧时祭文的写法大多如此公式化，所以为人传颂的不多。此文则不然。它写的全是作者同十二郎之间的个人家常琐事，通篇没有一句专门赞颂的话（只在行文中顺带提到伯兄的“盛德”和十二郎的“纯明”），每字每句，都是讲给死者听的，而死者也好像并没有死，正在听作者讲话。篇中叙十二郎生前种种家庭琐事的段落，就像久别重逢的亲人在一起回忆往事。即使是讲十二郎之死的地方，也好像死者就在旁边倾听，例如讲死期死因一段，就像二人在一起核实情况一样。同时，文中不时插入一些问话，“其竟以此而殒其生乎?抑别有疾而至斯乎?”“其然乎?其不然乎?”“汝其知也耶?其不知也耶?”像是作者当着十二郎的面在问他，更增强了当面对语的意味。因为是讲给死者听的，所以文中不发半句议论，朴素如口语，全文反复曲折，好像絮絮叨叨，实则不觉其烦，而且越读越打动人。\n\n　　也是为了抒情，此文还特别注意文言虚词，特别是语气词的运用，从而增强了行文的感染力。不论在古文或白话文中，虚词都是不可缺少的一个部分。有的古代散文，往往由于虚词运用的巧妙，使文章别具风采。宋代欧阳修的《醉翁亭记》，全文除一句之外，其他每句之末，都用一个语气词“也”字，因而使文章格外生色，是大家熟知的例子。在《祭十二郎文》的第二大段中，这一点也很突出。这段开头，“吾年未四十，而视茫茫，而发苍苍，而齿牙动摇”，连用三个并列的转折连词“而”字。从“呜呼！其信然邪?其梦邪?其传之非其真邪?”以下，先是连用三个“邪”字，紧接着又接连不断地连用三个“乎”字，三个“也”（同“邪”，作疑问语气词）字，五个“矣”字。这样连用连词和语气词，第一是可以加重语气，使表达的感情更加强烈；第二是可以押韵和增强文章的节奏，从而增强作品的感人力量。由于连用“邪”“乎”“也”“矣”等语气词，就使这篇祭文在散体之中又含有韵味，节奏也更加顿挫有力，更能打动读者的心。\n\n　　（选自《古典散文名作赏析》，山西人民出版社1985年版，有删节）', poem_tags = '古文观止,高中文言文,祭文,悼亡' WHERE poem_title = '祭十二郎文' AND poem_author = '韩愈';
UPDATE edu_poem SET poem_translation = '人间的事情都有更替变化，来来往往的时日形成古今。\n江山各处保留的名胜古迹，而今我们又可以登攀亲临。\n鱼梁洲因水落而露出江面，云梦泽由天寒而迷濛幽深。\n羊祜碑如今依然巍峨矗立，读罢碑文泪水沾湿了衣襟。', poem_notes = '岘山：一名岘首山，在今湖北襄阳城以南。诸子：指诗人的几个朋友。\n代谢：交替变化。\n往来：旧的去，新的来。\n复登临：对羊祜曾登岘山而言。登临：登山观看。\n鱼梁：沙洲名，在襄阳鹿门山的沔水中。\n梦泽：云梦泽，古大泽，即今江汉平原。\n字：一作“尚”。\n羊公碑：后人为纪念西晋名将羊祜而建。羊祜镇守襄阳时，常与友人到岘山饮酒诗赋，有过江山依旧人事短暂的感伤。', poem_tags = '唐诗三百首,吊古伤今' WHERE poem_title = '与诸子登岘山' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '注释 ⑴梅子：梅树的果实，夏季成熟，可以吃。肥：指果肉肥厚。麦花：荞麦花。菜花：油菜花。篱落：中午篱笆的影子。惟有：只有。蛱（jiá）蝶：菜粉蝶。 ⑵科斗：即蝌蚪。 ⑶秋：收成。一作“收”。 ⑷缲：同“缫”，抽茧出丝。 ⑸耘田：除草。绩麻：把麻搓成线。各当家：每人担任一定的工作。未解：不懂。供：从事，参加。傍：靠近。 ⑹浆：古代一种带酸味的饮料，这里比喻汗水浑浊。少住：稍稍停一会儿。侬：我。漱井香：用香甜的井水漱漱口。借与：让给。亭午：正午。 ⑺芙蕖：荷花。 ⑻蜩螗：蝉。', poem_tags = '田园,写景,劳动,生活,组诗' WHERE poem_title = '夏日田园杂兴' AND poem_author = '范成大';
UPDATE edu_poem SET poem_translation = '昨天夜晚江边的春水大涨，那艘庞大的战船就像一根羽毛一样轻。\n以往花费许多力量也不能推动它，今天在水中间却能自在地移动。', poem_notes = '渠：它，第三人称代词，这里指方塘之水。\n那得：怎么会。\n那：通“哪”，怎么的意思。\n清如许：这样清澈。\n如：如此，这样。\n清：清澈。\n为：因为。\n源头活水：比喻知识是不断更新和发展的，从而不断积累，只有在人生的学习中不断地学习、运用和探索，才能使自己永保先进和活力，就像水源头一样。\n“艨艟”:古代攻击性很强的战舰名，这里指大船。一毛轻：像一片羽毛一般轻盈。\n向来：原先，指春水上涨之前。推移力：指浅水时行船困难，需人推挽而行。\n中流：河流的中心。', poem_tags = '写水,读书,哲理' WHERE poem_title = '活水亭观书有感二首·其二' AND poem_author = '朱熹';
UPDATE edu_poem SET poem_translation = '出征的战士应当高唱军歌胜利日来。\n决心把满族统治者赶出山海关。\n战士只知道在战场上，要为国捐躯。\n何必考虑把尸体运回家乡。', poem_notes = '环：与“还”同音，古人常用作还乡的隐语。\n胡奴：指清王朝封建统治者。玉关：即甘肃玉门关，汉时为出塞要道。\n沙场：本指平沙旷野，后多指战场。\n马革裹尸：英勇作战，战死于战场。', poem_appreciation = '“拼将热血洒疆场 ”，这是一首边塞诗，写于1906年。当时作者从日本回国，曾北上游历，在吉林、辽宁一带察看形势，一路走来，有许多感想，于是就留下了这首七言诗。\n\n　　启首两句就写得颇具气势，“军歌应唱大刀环，誓灭胡奴出玉关。”出征的战士应高唱着战歌，挥举大刀，要一直把清朝统治者杀到关外。玉关，本指玉门关，这里代指山海关。清政府是在关外发迹的，因此要杀到关外，把他们彻底消灭。这里用一个“环”字，预示着反清斗争一定会取得胜利，战士们会踏着歌声，凯旋而回。后两句写得极其悲壮，抒发了作者的情感，“只解沙场为国死，何须马革裹尸还。”作为一名战士，想到的只是为国捐躯，根本不去考虑身后事，为国捐躯，死得其所，又何必用“马革裹尸还”呢？\n\n　　这首诗抒发了作者义无反顾的革命激情和牺牲精神，充满了英雄主义气概，把一腔报效祖国、战死疆场的热忱发挥得淋漓尽致。在写下了这首诗的一年以后，作者在安庆起义，失败被捕，清政府要他写口供，他挥笔直书：“尔等杀我好了，将我心剖了，两手两足断了，全身碎了，均可，不可冤杀学生。”尔后，慷慨就义，他用生命实现了自己的理想。这首诗感情豪放激扬，语气慷慨悲壮，英气逼人，最后一句“何须马革裹尸还”，写出了他壮怀激烈、视死如归的英雄气概。总之，这是近代边塞诗中难得的一首好诗。', poem_tags = '边塞,励志,赞美,将士,爱国' WHERE poem_title = '出塞' AND poem_author = '徐锡麟';
UPDATE edu_poem SET poem_translation = '境界有“有我之境”和“无我之境”。“泪眼问花花不语，乱红飞过秋千去。”“可堪孤馆闭春寒，杜鹃声里斜阳暮。”这是有我之境。“采菊东篱下，悠然见南山。”“寒波澹澹起，白鸟悠悠下。”这是无我之境。有我之境，是用自己的眼光来看事物，所以物我都带有我自己的主观色彩。无我之境，是忘记了自我，用物去看待物，所以不知道自身是什么也不知道外物是什么。古人作词，大部分写的都是有我之境，杰出的人士却能独树一帜写出无我之境。\n\n　　境界不仅仅是指景色和事物。喜怒哀乐每一项都是人心中的一种境界。所以能写出真景物，真感情的人，那他才是有境界的。否则就是无境界。\n\n　　境界有大也有小，不能以大小为标准来评判孰优孰劣。“细雨鱼儿出，微风燕子斜”哪里比不上“落日照大旗，马鸣风萧萧”。“宝帘闲挂小银钩”哪里比不上“雾失楼台，月迷津渡”了。\n\n　　词到了李煜那里眼界才开始变阔大，感慨逐渐加深，慢慢地由乐师戏子的词变成士大夫的词。周介存把他的词列在温庭筠和韦应物的下面，真是颠倒了黑白。“自是人生长恨水长东”、“流水落花春去也，天上人间”，《金荃》《浣花》，能有这样的气象？\n\n　　从古至今，那些做成大事业，大学问的人，没有不经历三种境界的：“昨夜西风凋碧树。独上高楼，望尽天涯路。”这是第一境界。“衣带渐宽终不悔，为伊消得人憔悴。”这是第二境界。“众里寻他千百度，蓦然回首，那人却在，灯火阑珊处。”这是第三境界。这些话都是大词人才能作出来。但是根据这个意思解释诗词，恐怕晏同叔和欧阳修等人是不会赞同的。\n\n　　大作家的作品，表述情绪会让人感觉内心清新爽朗，写景也一定会让人开拓视听。他们的话语脱口而出，没有刻意的揉捏装扮。这是因为他们能看到事物怎正的状态，能了解到事物的深处。诗词都是这样。用这个方法来衡量古今的作者，不会有大的错误。\n\n　　诗人面对宇宙人生，应该进入其中，又应该游离其外。进入其中，所以能描写它。游离其外，所以能观察它。进入其中，所以有生气。游离其外，所以有高雅的情致。周邦彦能进却不能出来。自姜夔以来，这两种状态在梦里也没有见过啊。', poem_notes = '①泪眼问花花不语，乱红飞过秋千去：出自欧阳修的《蝶恋花》。\n②可堪孤馆闭春寒，杜鹃声里斜阳暮：出自秦观的《踏莎行·雾失楼台》。\n③采菊东篱下，悠然见南山：出自陶渊明的《饮酒·其五》。\n④寒波澹澹起，白鸟悠悠下：出自元好问的《颖亭留别》。\n⑤细雨鱼儿出，微风燕子斜》、：出自杜甫的《水槛遣心·其一》。\n⑥落日照大旗，马鸣风萧萧：出自杜甫的《后出塞·其二》。\n⑦宝帘闲挂小银钩 ：出自秦观的《浣溪沙》。\n⑧雾失楼台，月迷津渡：出自秦观的《踏莎行》。\n⑨李后主：即李煜。\n⑩伶工：古时指乐师或演员。\n⑪周介存：即周济，字介存，清词论家，词人。\n⑫自是人生长恨水长东：出自李煜的《乌夜啼》。\n⑬流水落花春去也，天上人间：出自李煜的《浪淘沙》。\n⑭罔（wǎng）：没有。\n⑮昨夜西风凋碧树。独上高楼，望尽天涯路：出自晏殊的《蝶恋花·槛菊愁烟兰泣露》。\n⑯衣带渐宽终不悔，为伊消得人憔悴：出自柳永的《蝶恋花》，也有人认为是欧阳修所作。\n⑰众里寻他千百度，蓦然回首，那人却在，灯火阑珊处：出自辛弃疾的《青玉案》。\n⑱晏欧：晏同叔和欧阳修。\n⑲美成：即周邦彦。\n⑳白石以降：自从姜夔以后。白石，即姜夔，号白石道人。', poem_tags = '文学,批评' WHERE poem_title = '人间词话七则' AND poem_author = '王国维';
UPDATE edu_poem SET poem_tags = '音乐' WHERE poem_title = '琵琶行' AND poem_author = '牛殳';
UPDATE edu_poem SET poem_translation = '一轮明月高高地挂在天空，月光映上露珠晶莹剔透，好像被露水打湿了一样。在如此美丽的月光下，寒鹊不知道该到哪里栖息。而萤火虫也不敢和月光争一点光亮。随着卷起的门帘飞进了房间。\n院子里只剩枝丫的槐树落在月光下的影子，稀疏凄凉。而这个时候从邻居那边传来的杵声在寂静的秋夜里显得那么清晰急促。相隔遥远。如何去约定相聚的日子，只能惆怅地望着同样遥远的月亮，什么事也做不了，就那样傻站着。', poem_notes = '沾：润湿。\n栖：栖息。\n帘：即竹帘，可以卷起，故称卷帘。\n 杵（chǔ）：春米、捣衣用的棒槌。此用作动词，指捣衣。\n佳期：原指与佳人相约会，后泛指欢聚之日。\n望望：望了又望。\n伫立：久久站立。', poem_appreciation = '第一，二句“秋空明月悬，光彩露沾湿”，极为平淡的文笔勾勒出一幅孤清明月图，此时的明月很是寂静，甘心悬于秋空，也不霸道，只是将光彩照到晶莹的露水上，这不是一种炫耀，而是一种淡如水的关怀，就如诗人与明月有着一层微妙的关系。\n\n　　第三，四句“惊鹊栖未定，飞萤卷帘飞”，这是极好的动态描写，惶诚惶恐的鹊仍没有找到自己的住处，而飞萤早巳随灯光飞人寻找它的寄托。这是对比的描写，在此写法之下，真切地感受到惊鹊的彷徨与恐惧，诗人正也如它，在众人欢聚的夜晚却不知何去何从，又得流连徘徊。\n\n　　而第五，六句“庭槐寒影疏，邻杵夜声急”更是加深了这一孤清的意境，在庭院中稀疏的树影中，在邻家急急的夜杵声中，他更显得形单影只，骨子深处的孤独更是无处逃逸，全部涌上心头，强烈而含蓄。\n\n　　于是诗人再也抑制不住，发出了第七句的“佳期旷何许”的感叹，以后便是最后一句的“望望空伫立”。冷清凄凉的庭院里，唯有他一人久久伫立、沉默，不愿离去。描绘了一幅凄凉幽冷的环境下，一人孤单只影远望的画面。\n\n　　通读整篇，发现并无任何用词新奇之处，但妙就妙在这意境的成功营造。诗人以流水般流畅的文笔，以“明月”“惊鹊”“寒影”等一组意象画出了一幅别样的孤清月夜图。徜徉其中，能清楚地看见他的思痕，触摸到他跳跃的文思，听到他的叹息。', poem_tags = '中秋节,月亮,借景抒情' WHERE poem_title = '秋宵月下有怀' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '杨朱的弟弟叫杨布，他穿着件白色的衣服出门去了。天上下起了雨，杨布便脱下白衣，换了黑色的衣服回家。他家的狗没认出来是杨布，就迎上前冲他叫。杨布十分生气，正准备打狗。在这时，杨朱说：“你不要打狗，如果换做是你,你也会是像它这样做的。假如刚才你的狗离开前是白色的而回来变成了黑色的，你怎么能不感到奇怪呢?”', poem_notes = '杨朱，先秦哲学家，战国时期魏国人，字子居\n曰：名叫。\n衣：穿。\n素：白色的。\n雨：下雨。\n衣：上衣，这里指衣服。\n缁（zī）：黑色。\n反：同“返“返回，回家。\n知：了解，知道。\n而：连词，表示顺承。\n吠：（狗）大叫。\n怒：生气，愤怒。\n将：打算。\n扑：打、敲。\n子无扑之，子 ：你\n犹是：像这样。\n向者：刚才。向，从前，往昔。\n使：假使，假若。\n岂：怎么。\n无：同“毋”，不，不要。\n怪：对……感到奇怪。\n衣素衣：穿着白衣服。', poem_appreciation = '从前，在一个不太出名的小山村，住着一户姓杨的人家，靠在村旁种一片山地过日子。这户人家有两个儿子，大儿子叫杨朱，小儿子叫杨布，两兄弟一边在家帮父母耕地、担水，一边勤读诗书。这兄弟两人都写得一手好字，交了一批诗文朋友。\n\n　　有一天，弟弟杨布穿着一身白色干净的衣服兴致勃勃地出门访友。在快到朋友家的路上，不料天空突然下起雨来了，雨越下越大，杨布正走在前不着村、后不落店的山间小道上，只好硬着头皮顶着大雨，被淋得落汤鸡似地跑到了朋友家。他们是经常在一起讨论诗词、评议字画的好朋友，杨布在朋友家脱掉了被雨水淋湿了的白色外衣，穿上了朋友的一身黑色外套。朋友家里招待杨布吃过饭，两人又谈论了一会儿诗词，评议了一会儿前人的字画。他们越谈越投机，越玩越开心，不觉天快黑下来了，杨布就把自已被雨水淋湿了的白色外衣晾在朋友家里，而自己就穿着朋友的一身黑色衣服告辞朋友回家。\n\n　　雨后的山间小道虽然是湿的，但由于路面上小石子铺得多，没有淤积的烂泥。天色渐渐地暗下来了，弯弯曲曲的山路还是明晰可辨。晚风轻轻吹着，从山间送来一阵阵新枝嫩叶的清香。要不是天愈来愈黑下来了，杨布还真有点儿雨后漫游山岗的雅兴哩！他走着、走着，走到自家门口了，还沉浸在白天与朋友畅谈的兴致里。这时，杨布家的狗却不知道是自家主人回来了，从黑地里猛冲出来对他汪汪直叫。须臾，那狗又突然后腿站起、前腿向上，似乎要朝杨布扑过来。杨布被自家的狗这突如其来的狂吠声和它快要扑过来的动作吓了一跳，十分恼火，他马上停住脚向旁边闪了一下，愤怒地向狗大声吼道：“瞎了眼，连我都不认识了！”于是顺手在门边抄起一根木棒要打那条狗。这时，哥哥杨朱听到了声音，立即从屋里出来，一边阻止杨布用木棒打狗，一边唤住了正在狂叫的狗，并且说：“你不要打它啊！应该想想看，你白天穿着一身白色衣服出去，这么晚了，又换了一身黑色衣服回家，假若是你自己，一下子能辨得清吗？这能怪狗吗？”\n\n　　杨布不说什么了，冷静地思考了一会儿，觉得哥哥杨朱讲的也是有道理的。狗也不汪汪地叫了，一家人重新又恢复了原先的快乐。', poem_tags = '哲理,故事' WHERE poem_title = '杨布打狗' AND poem_author = '列御寇';
UPDATE edu_poem SET poem_translation = '春风乍起，吹皱了一池碧水。（我）闲来无事，在花间小径里逗引池中的鸳鸯，随手折下杏花蕊把它轻轻揉碎。\n独自倚靠在池边的栏杆上观看斗鸭，头上的碧玉簪斜垂下来。（我）整日思念心上人，但心上人始终不见回来，（正在愁闷时），忽然听到喜鹊的叫声。', poem_notes = '谒金门：词牌名。\n乍：忽然。\n闲引：无聊地逗引着玩。\n挼：揉搓。\n斗鸭：以鸭相斗为欢乐。斗鸭阑和斗鸡台，都是官僚显贵取乐的场所。独：一作“遍”\n碧玉搔头：一种碧玉做的簪子。《西京杂记》载：“（汉）武帝过李夫人，就取玉簪搔头；自此后，宫人搔头皆用玉。”', poem_appreciation = '冯延巳擅长以景托情，因物起兴的手法，蕴藏个人的哀怨。写得清丽、细密、委婉、含蓄。这首脍炙人口的怀春小词，在当时就很为人称道。尤其“风乍起，吹绉一池春水”，是传诵古今的名句。词的上片，以写景为主，点明时令、环境及人物活动。下片以抒情为主，并点明所以烦愁的原因。\n\n　　春风乍起，吹皱了一池碧水，这本是春日平常得很的景象。可是有谁知道，这一圈圈的涟漪，却搅动了一位女性的感情波澜。别看她貌似悠闲，时而逗引鸳鸯，时而揉扯花蕊，过一会儿又倚身在池栏上观看斗鸭，但只需要从她懒洋洋的神态上，我们就知她的心思其实全不在此。随着几声喜鹊的欢叫，她的面庞儿顿时就涌上了一阵红晕----盼念已久的丈夫终于回家了，这怎能不令她的心像小鹿儿那样乱撞乱跳？', poem_tags = '宋词三百首,婉约,写景,惜别,留恋' WHERE poem_title = '谒金门·风乍起' AND poem_author = '冯延巳';
UPDATE edu_poem SET poem_translation = '病牛耕耘千亩，换来了劳动成果装满千座粮仓的结果，但它自身却精神极为疲惫，力气全部耗尽，然而，又有谁来怜惜它力耕负重的劳苦呢？\n但为了众生都能够饱，即使拖垮了病倒卧在残阳之下，也在所不辞。', poem_notes = '实千箱：极言生产的粮食多。实：充实，满。 箱：装粮的容器。一说同“厢”，指官府的仓房。\n复：又，再。伤：哀怜，同情。\n但得：只要能让。\n众生：大众百姓。\n不辞：不推辞。\n羸（léi）病：瘦弱有病。残阳：夕阳，即快要下山的太阳。此处既烘托凄凉气氛，又喻指作者晚年。', poem_appreciation = '诗首句言牛终生辛劳，硕果累累，不言牛“病”，又字字含“病”意，年复一年，力耕千亩，获实千箱，必然气力衰竭，病由此生。次句言牛虽功绩至伟，却没有人对它同情哀怜，责问语气，有强烈的感情色彩。三四句以牛的口气作答，将牛人格化，揭示牛为百姓甘于自我牺牲的可贵品格。\n\n　　此诗中的牛，亦是诗人自喻。李纲官至宰相，他为官清正，反对媾和，力主抗金，并亲自率兵收复失地，但为投降派奸佞排挤，为相七十天即“谪居武昌”，次年又“移澧浦”，内心极为愤抑不平。因此，作《病牛》诗以自慰、自白。\n\n　　这首诗运用比喻和拟人手法，形象生动，立意高远，既是成功的咏物诗，更是杰出的言志诗，为后世传诵。\n\n　　在中国诗歌史上，自第一部诗歌总集《诗经》里吟咏鸱鸮的诗作之后，吟咏日月星辰、山川草木、花鸟鱼虫的咏物诗可谓层出不穷。在浩如烟海的咏物诗中有不少格调颇高、艺术精湛、韵味无穷的佳作。李纲的这首《病牛》便是其中之一。这里，我们不谈此诗所具有的高度概括力，也不说此诗质朴无华的语言美，只是想欣赏一下其“离形得似”、“托物言志”的艺术。司空图《诗品·形容》认为，诗人“形容”（指描摹客观事物）能不拘形似而求得神似，才是精于“形容”者：“离形得似，庶几斯人”。李纲正是精于“形容”者，其《病牛》诗达到了“离形得似”，也即不拘于描写对象的外形外貌相似，而求得描写对象精神相似的境界。作者吟咏病牛，笔墨重点不在绘其形，而在传其神。\n\n　　诗的前两句“耕犁千亩实千箱，力尽筋疲谁复伤”，写病牛耕耘千亩，换来了劳动成果装满千座粮仓的结果，但它自身却精神极为疲惫，力气全部耗尽，然而，又有谁来怜惜它力耕负重的劳苦呢？这里，作者从揭示病牛“耕犁千亩”与“实千箱”之间的因果关系上落笔，将病牛“力尽筋疲”与“谁复伤”加以对照，集中描写了病牛劳苦功高、筋疲力尽及其不为人所同情的境遇。首句中的两个“千字”，分别修饰“亩”与“箱”（通“厢”，指粮仓），并非实指，而是极言病牛“耕犁”数量之大、劳动收获之多，同时，也暗示这头牛由年少至年老、由体壮及体衰的历程。次句反诘语气强烈，增添了诗情的凝重感。\n\n　　诗的后两句笔锋陡地一转，转为述其志：“但得众生皆得饱，不辞羸病卧残阳。”病牛劳苦功高，筋疲力尽，却无人怜惜，但它没有怨天尤人，更未消极沉沦。因为它具有心甘情愿为众生的温饱而“羸病卧残阳”之志。这两句诗将病牛与“众生”联系起来写，以“但得”与“不辞”对举，强烈地抒发了病牛不辞羸病，一心向着众生的志向。结句中的“残阳”是双关语，既指夕阳，又象征病牛的晚年，它与“卧”等词语相结合，有助于表现老牛身体病弱却力耕负重、死而后已的精神。\n\n　　这首诗惟妙惟肖地刻画了一个病牛的形象，既绘出其身体病弱之形，更传出了其不辞羸病、志在众生之神。如此咏牛，颇为切合牛任劳任怨、唯有奉献、别无他求的性格特点。不过，此诗并非为咏牛而咏牛，而是“托物言志”，借咏牛来为作者言情述志。我们只要能像前人所说的那样“知人论世”，便不难看出这一点。\n\n　　赞颂了牛不辞羸病、任劳任怨、志在众生、唯有奉献、别无他求的性格特点。—— “托物言志”，借咏牛来为作者言情述志。\n\n　　诗人疲惫不堪，却耿耿不忘抗金报国，想着社稷，念着众生，因此其笔下力尽筋疲、无人怜惜而不辞羸病、志在众生的老牛即诗人形象的化身。\n\n　　作者正是这样怀着强烈的爱国热忱来吟咏病牛，托物言志的。因而，此诗中的病牛，也即作者自身的形象活了，动了，能在读者心中引起共鸣，产生美感。', poem_tags = '古诗三百首,咏物,动物,言志,爱国' WHERE poem_title = '病牛' AND poem_author = '李纲';
UPDATE edu_poem SET poem_translation = '富家的子弟不会饿死，清寒的读书人大多贻误自身。\n韦大人你可以静静地细听，我把自己的往事向你直陈。\n我在少年时候，早就充当参观王都的来宾。\n先后读熟万卷书籍，写起文章，下笔敏捷好像有神。\n我的辞赋能与扬雄匹敌，我的诗篇可跟曹植相近。\n李邕寻求机会要和我见面，王翰愿意与我结为近邻。\n自以为是一个超异突出的人，一定很快地身居要津。\n辅助君王使他在尧舜之上，要使社会风尚变得敦厚朴淳。\n平生的抱负全部落空，忧愁歌吟，决不是想优游退隐。\n骑驴行走了十三年，寄食长安度过不少的新春。\n早上敲过豪富的门，晚上追随肥马沾满灰尘。\n吃过别人的残汤剩饭，处处使人暗中感到艰辛。\n不久被皇帝征召，忽然感到大志可得到展伸。\n但自己像飞鸟折翅天空坠落，又像鲤鱼不能跃过龙门。\n我很惭愧，你对我情意宽厚，我深知你待我一片情真。\n把我的诗篇举荐给百官们，朗诵着佳句，夸奖格调清新。\n想效法贡禹让别人提拔自己，却又难忍受像原宪一样的清贫。\n我怎能这样使内心烦闷忧愤，老是且进且退地厮混。\n我要向东奔入大海，即将离开古老的西秦。\n我留恋巍峨的终南山，还要回首仰望清澈的渭水之滨。\n想报答你的“一饭之恩”，想辞别关心我的许多大臣。\n让我像白鸥出现在浩荡的烟波间，飘浮万里有谁能把我纵擒？', poem_notes = '纨绔：指富贵子弟。不饿死：不学无术却无饥饿之忧。儒冠多误身：满腹经纶的儒生却穷困潦倒。这句是全诗的纲要。《潜溪诗眼》云：“此一篇立意也。”\n丈人：对长辈的尊称。这里指韦济。贱子：年少位卑者自谓。这里是杜甫自称。请，意谓请允许我。具陈：细说。\n破万卷：形容书读得多。如有神：形容才思敏捷，写作如有神助。\n扬雄：字子云，西汉辞赋家。料：差不多。敌：匹敌。子建：曹植的字，曹操之子，建安时期著名文学家。看：比拟。亲：接近。\n李邕：唐代文豪、书法家，曾任北海郡太守。杜甫少年在洛阳时，李邕奇其才，曾主动去结识他。王翰：当时著名诗人，《凉州词》的作者。\n挺出：杰出。立登要路津：很快就要得到重要的职位。\n尧舜：传说中上古的圣君。\n骑驴：与乘马的达官贵人对比。十三载：从公元735年（开元二十三年）杜甫参加进士考试，到公元747年（天宝六载），恰好十三载。旅食：寄食。京华：京师，指长安。\n主上：指唐玄宗。顷：不久前。见征：被征召。歘然：忽然。欲求伸：希望表现自己的才能，实现致君尧舜的志愿。\n青冥却垂翅：飞鸟折翅从天空坠落。蹭蹬：行进困难的样子。无纵鳞：本指鱼不能纵身远游。\n贡公：西汉人贡禹。他与王吉为友，闻吉显贵，高兴得弹冠相庆，因为知道自己也将出头。杜甫说自己也曾自比贡禹，并期待韦济能荐拔自己。难甘：难以甘心忍受。原宪；孔子的学生，以贫穷出名。\n怏怏：气愤不平。踆踆：且进且退的样子。\n东入海：指避世隐居。孔子曾言：“道不行，乘桴浮于海。”（《论语》）去秦：离开长安。\n报一饭：报答一饭之恩。辞大臣：指辞别韦济。这两句说明赠诗之故。\n白鸥：诗人自比。没浩荡：投身于浩荡的烟波之间。谁能驯：谁还能拘束我呢？', poem_appreciation = '在杜甫困守长安十年时期所写下的求人援引的诗篇中，要数这一首是最好的了。这类社交性的诗，带有明显的急功求利的企图。常人写来，不是曲意讨好对方，就是有意贬低自己，容易露出阿谀奉承、俯首乞怜的寒酸相。杜甫在这首诗中却能做到不卑不亢，直抒胸臆，吐出长期郁积下来的对封建统治者压制人材的悲愤不平。这是他超出常人之处。\n\n　　诗人主要运用了对比和顿挫曲折的表现手法，将胸中郁结的情思，抒写得如泣如诉，真切动人。这首诗应该说是体现杜诗“沉郁顿挫”风格的最早的一篇。\n\n　　诗中对比有两种情况，一是以他人和自己对比；一是以自己的今昔对比。先说以他人和自己对比。开端的“纨袴不饿死，儒冠多误身”，把诗人强烈的不平之鸣，像江河决口那样突然喷发出来，真有劈空而起，锐不可当之势。在诗人所处的时代，那些纨袴子弟，不学无术，一个个过着脑满肠肥、趾高气扬的生活；他们精神空虚，本是世上多余的人，偏又不会饿死。而像杜甫那样正直的读书人，却大多空怀壮志，一直挣扎在饿死的边缘，眼看误尽了事业和前程。这两句诗，开门见山，鲜明揭示了全篇的主旨，有力地概括了封建社会贤愚倒置的黑暗现实。\n\n　　从全诗描述的重点来看，写“纨袴”的“不饿死”，主要是为了对比突出“儒冠”的“多误身”，轻写别人是为了重写自己。所以接下去诗人对韦济坦露胸怀时，便撇开“纨袴”，紧紧抓住自己在追求“儒冠”事业中今昔截然不同的苦乐变化，再一次运用对比，以浓彩重墨抒写了自己少年得意蒙荣、眼下误身受辱的无穷感慨。这第二个对比，诗人足足用了二十四句，真是大起大落，淋漓尽致。从“甫昔少年日”到“再使风俗淳”十二句，是写得意蒙荣。诗人用铺叙追忆的手法，介绍了自己早年出众的才学和远大的抱负。少年杜甫很早就在洛阳一带见过大世面。他博学精深，下笔有神。作赋自认可与扬雄匹敌，咏诗眼看就与曹植相亲。头角乍露，就博得当代文坛领袖李邕、诗人王翰的赏识。凭着这样卓越挺秀的才华，他天真地认为求个功名，登上仕途，还不是易如反掌。到那时就可实现梦寐以求的“致君尧舜上，再使风俗淳”的政治理想了。诗人信笔写来，高视阔步，意气风发，大有踌躇满志、睥睨一切的气概。写这一些，当然也是为了让韦济了解自己的为人，但更重要的还是要突出自己眼下的误身受辱。从“此意竟萧条”到“蹭蹬无纵鳞”，又用十二句写误身受辱，与前面的十二句形成强烈的对比。现实是残酷的，“要路津”早已被“纨袴”占尽，主观愿望和客观实际的矛盾无情地嘲弄着诗人。诗中写了诗人在繁华京城的旅客生涯：多少年来，诗人经常骑着一条瘦驴，奔波颠踬在闹市的大街小巷。早上敲打豪富人家的大门，受尽纨袴子弟的白眼；晚上尾随着贵人肥马扬起的尘土郁郁归来。成年累月就在权贵们的残杯冷炙中讨生活。不久前诗人又参加了朝廷主持的一次特试，谁料这场考试竟是奸相李林甫策划的一个忌才的大骗局，在“野无遗贤”的遁辞下，诗人和其他应试的士子全都落选了。这对诗人是一个沉重的打击，就像刚飞向蓝天的大鹏又垂下了双翅，也像遨游于远洋的鲸鲵一下子又失去了自由。诗人的误身受辱、痛苦不幸也就达到了顶点。\n\n　　这一大段的对比描写，迤逦展开，犹如一个人步步登高，开始确是满目春光，心花怒放，那曾想会从顶峰失足，如高山坠石，一落千丈，从而使后半篇完全笼罩在一片悲愤怅惘的氛围中。诗人越是把自己的少年得意写得红火热闹，越能衬托出眼前儒冠误身的悲凉凄惨，这大概是诗人要着力运用对比的苦心所在。\n\n　　从“甚愧丈人厚”到诗的终篇，写诗人对韦济的感激、期望落空、决心离去而又恋恋不舍的矛盾复杂心情。这样丰富错杂的思想内容，必然要求诗人另外采用顿挫曲折的笔法来表现，才能收到“其入人也深”的艺术效果。在坎坷的人生道路上，诗人再也不能忍受像孔子学生原宪那样的贫困了。他为韦济当上了尚书左丞而暗自高兴，就像汉代贡禹听到好友王吉升了官而弹冠相庆。诗人十分希望韦济能对自己有更实际的帮助，但现实已经证明这样的希望是不可能实现了。诗人只能强制自己不要那样愤愤不平，快要离去了却仍不免在那里顾瞻俳徊。辞阙远游，退隐江海之上，这在诗人是不甘心的，也是不得已的。他对自己曾寄以希望的帝京，对曾有“一饭之恩”的韦济，是那样恋恋不舍，难以忘怀。但是，又没有办法。最后只能毅然引退，像白鸥那样飘飘远逝在万里波涛之间。这一段，诗人写自己由盼转愤、欲去不忍、一步三回头的矛盾心理，真是曲折尽情，丝丝入扣，和前面动人的对比相结合，充分体现出杜诗“思深意曲，极鸣悲慨”（方东树《昭昧詹言》）的艺术特色。\n\n　　“白鸥没浩荡，万里谁能驯！”从结构安排上看，这个结尾是从百转千回中逼出来的，宛若奇峰突起，末势愈壮。它将诗人高洁的情操、宽广的胸怀、刚强的性格，表现得辞气喷薄，跃然纸上。正如浦起龙指出的“一结高绝”（见《读杜心解》）。董养性也说：“篇中……词气磊落，傲睨宇宙，可见公虽困踬之中，英锋俊彩，未尝少挫也。”（转引自仇兆鳌《杜诗详注》）吟咏这样的曲终高奏，诗人青年时期的英气豪情，会重新在读者心头激荡。诗人经受着尘世的磨炼，没有向封建社会严酷的不合理现实屈服，显示出一种碧海展翅的冲击力，从而把全诗的思想性升华到一个新的高度。\n\n　　此诗通篇直抒胸臆，语句颇多排比，语意纵横转折，感愤悲壮之气溢于字里行间。全诗不仅成功地运用了对比和顿挫曲折的笔法，而且语言质朴中见锤炼，含蕴深广。如“残杯与冷炙，到处潜悲辛”，道尽了世态炎凉和诗人精神上的创伤。一个“潜”字，表现悲辛的无所不在，可谓悲沁骨髓，比用一个寻常的“是”或“有”字，就精细生动得多倍。句式上的特点是骈散结合，以散为主，因此既有整齐对衬之美，又有纵横飞动之妙。所以这一切，都足证诗人功力的深厚，也预示着诗人更趋成熟的长篇巨制，随着时代的剧变和生活的充实，必将辉耀于中古的诗坛。', poem_tags = '社交,读书,壮志' WHERE poem_title = '奉赠韦左丞丈二十二韵' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '隐隐的犬吠声夹杂在淙淙的流水声中，\n桃花带着几点露珠。\n树林深处，常见到麋鹿出没。\n正午时来到溪边却听不见山寺的钟声。\n绿色的野竹划破了青色的云气，\n白色的瀑布高挂在碧绿的山峰。\n没有人知道道士的去向，\n我不由自主地靠着几株古松犯愁。', poem_notes = '戴天山：在四川昌隆县北五十里，青年时期的李白曾经在此山中的大明寺读书。不遇：没有遇到\n吠：狗叫。\n带露浓：挂满了露珠。\n树深：树丛深处。\n青霭：青色的云气。\n倚：靠。', poem_appreciation = '这首诗是李白早年的作品。李白早年在戴天山大明寺读书。后来，李白因坐永王李璘事入狱，流放夜郎，遇赦，漂泊浔阳、金陵、宣城、历阳等地。杜甫在成都于肃宗上元二年(761)，因“近无李白消息“，写了一首《不见》诗怀念李白，担心他在外会闯祸，盼他早日归还“匡山“故乡。诗曰:“不见李生久，佯狂真可哀。世人皆欲杀，吾意独怜才。敏捷诗千首，飘零酒一杯。匡山读书处，头白好归来。“次年，李白便死于安徽当涂。\n\n　　李白早年即富有才华，他在大匡山读书时，就描绘了这样一幅色彩鲜明的访问道士不遇图。道士姓名，不得而知。通篇着意于写景，真实自然，并生动形象地再现了道士世外桃源的优美生活境界。\n\n　　全诗分为三个层次，前四句为一个层次，五、六两句为二个层次，最后两句为一个层次。前四句是写诗人拜访道士途中听耳闻目睹。诗人沿着小溪而行，沿路两旁。桃花盛开，花瓣上挂满露珠。这说明诗人一大早，就出门而行。小溪流水淙淙，与狗吠之声，响成一片，形成了一种别有情趣的乐章。道士的处所，路程还不近呢。诗人从早走到中午时分，尚且没有听见道士敲钟的声音，只见树丛的深处，不时有麋鹿出没。这两句的妙处，暗示道士不在道院，为最后两句设下伏笔。以上四句。把道士远离人间闹市的那种清新幽静的环境，逼真地摹写出来。前两句写狗吠声声，溪水淙淙，桃花含露，是诗人早上的所见听闻。“树深时见鹿，溪午不闻钟“两句，是写中午时分的耳闻目睹。时间不同，地点各异，诗人所描写的见闻，也各不相同。在这里，时间和空间感。异常清晰。\n\n　　“野竹分青霭，飞泉挂碧峰“两句，是写道士处所的近景，野竹参天，与青气融为一体，从碧绿的山峰间飞流直下的瀑布，形成了一种优美壮观的奇境。飞、挂二字，是写瀑布飞流直下的动的画面。“野竹分青霭“的“分“字，表面是写野竹参天，把空中的青色云气隔开，实则是说翠竹参天，与青色的云气相接，浑为一体。形成天竹一色的奇景。竹前冠一“野“字，是说翠竹是自然长成，并非人工培植，因而更觉可喜可爱。“霭“前冠一“青“字，与竹色协调，融为一色。“飞泉挂碧峰“，颇有“飞流直下三千尺，疑是银河落九天“的壮观，具有引入入胜，令人留连忘返的艺术魅力。\n\n　　最后两句，方才点明“访戴天山道士不遇“的诗题。人们都会有这样的常识:大凡去访亲探友，不能相遇，就会令人焦躁不安。李白去拜访道士，道士不在道院，又无人知道去向、怎能不使他十分着急呢?尽管道士不在，诗人并没有立即返回，他远道而来，总想能见到道士，同他畅谈一番。“愁倚两三松“，写得极其生动形象，写诗人等待道士回来，倚靠遍了道士门前的两三棵松树，而道士仍然未回。“愁“字，颇能传神，把诗人着急的神态。刻画得清晰可见，历历在目。“无人知所去“，是一般的陈述句。只是说明道士不知所去。是为“愁倚两三松“句，所作的铺垫。\n\n　　此作的构思并不复杂，它写诗人的所闻所见，都是为了突出访道士不遇的主题。所以，吴大受说:“无一字说道士，无一字说不遇，却句句是不遇，句句是访道士不遇。“(《诗筏》)当然，并不是说李白这首诗已经写得尽善尽美了，李白是伟大的浪漫主义诗人，他后期比较成熟的诗作，都写得十分洒脱、酣畅、飘逸、雄浑，字里行间，充满着一股豪气。而他这首诗，在这方面的特点还不够明显，还不够浓郁。这说明此作还带有他早期作品的痕迹。', poem_tags = '拜访,写景,抒情,写狗古诗18首' WHERE poem_title = '访戴天山道士不遇' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '老旧园子里的小路旁已经长出了幽幽的花丛，一夜之间清露从天空坠下落在花上。\n有多少远在他方为客的未归人啊，只能借着篱笆看看秋天的景色。', poem_notes = '故园：古旧的林苑，也借指故乡。\n三径：借指归隐者的家园。\n幽丛：幽幽的花丛，这里指菊花。\n玄露：清露。\n篱落：即篱笆。柳宗元《田家》篱落隔烟火，农谈四邻夕。', poem_appreciation = '赏析 　　这是一首托物寄兴的诗，没有什么艰涩的意象，很清新淡雅，并且浅近直白。诗人借菊花以自比，在诗词中属于香草美人笔法。首联诗人先描写故园中的菊花淡放的情形，开得并不张扬，而是淡淡的幽然的开放，而且开得那么突然，所以颔联写它就好像是一夜的霜降后从天空坠落一般。写出了菊花高傲的品质，不铺排张扬，但是却内涵丰沛，在单淡然中凸现其品质。后两句是诗人的托物起行，以菊花自比。颈联写到多少沦落天涯的文人骚客，估计诗人自己也在内吧，尾联写尽借篱落看秋风，篱落是指篱笆，记的范成大在他的一首诗中提到篱落，“日长篱落无人问”。沦落天涯的文人骚客从这篱笆里面的开放的秋菊中看尽了浓浓衰飒的秋意，看到了自己的影子。自陶渊明以来，菊花就是隐士、高洁的象征，诗人就是借菊花表现自己的高洁品格。 ▲', poem_tags = '咏物,菊花,品格,寓人' WHERE poem_title = '菊花' AND poem_author = '唐寅';
UPDATE edu_poem SET poem_translation = '如果说琴声发自琴，那把它放进盒子里为什么不响呢？\n如果说琴声发自手，为何你的手上听不到声音？', poem_notes = '若:如果。\n何:为何。', poem_appreciation = '唐朝的韦应物写了一首《听嘉陵江水声寄深上人》：“凿岩泄奔湍，称古神禹迹。夜喧山门店，独宿不安席。水性自云静，石中本无声。如何两相激，雷转空山惊？贻之道门旧，了此物我情。”这位作家对水石之间关系的疑惑与领悟，亦同于苏轼之于琴指。这其实是个高深的哲学问题，因为在佛教看来，一切都是因缘和合而成，事物与事物之间只是由于发生了联系，才得以存在。即如所谓“四大”，《金光明最胜王经》卷五说：“譬如机关由业转，地火水风共成身。随彼因缘招异果，一在一处相违害，如四毒蛇具一箧。”《圆觉经》说：“恒在此念，我今此身，四大和合。”《楞严经》曾对什么是“浊”有一段阐发：“譬如清水，清洁本然，即彼尘土灰沙之伦，本质留碍，二体法尔，性不相循。有世间人取彼土尘，投于净水，土失留碍，水亡清洁，容貌汩然，名之为浊。”也就是说，“浊”是尘土和清水发生了作用而形成的。另一段论述说得更为明确：“譬如琴瑟、箜篌、琵琶，虽有妙音，若无妙指，终不能发。”——苏轼的诗简直就是这段话的形象化。\n\n　　从字面上看是说，如果说琴可以自己发声，那么为什么把它放在盒子里就没了乐声？如果说声音是由手指头发出的，那么为什么不能凑过耳朵靠近指头直接听到乐声呢？\n\n　　苏轼在这首诗中思考是：琴是如何发出声音的？根据科学依据可知，其实，琴能演奏出优美的音乐，这不光需要靠琴，还要靠人的指头弹动、敲击钢丝 ,产生振动发出，人的手指和琴同时存在是发出琴音的物质基础，只有两者相辅相成，才能奏出优美的音乐。\n\n　　由于钢丝的粗细不同，所以按不同的键，木槌就会敲击相应的钢， 发出不同的声音。\n\n　　该诗哲理性很强，富有禅机。佛教视有为无，视生为灭，追求无声无形不生不减，音乐的真实即虚无，所以音乐无所谓真实与否，要以“谐无声之乐，以自得为和”、“反闻闻自性，性成无上道”，通过内心的感受而自得、反悟禅道。《题沈君琴》否定了琴、指两者和音乐之声的关系，其思想和《楞言经》“声无既无灭，声有亦非生，生灭两圆离，是则常真实”相通。', poem_tags = '美学,哲理' WHERE poem_title = '琴诗' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '昏暗的树林中，草突然被风吹得摇摆不定，飒飒作响，将军以为野兽来了，连忙开弓射箭。\n天亮去寻找那只箭，已经深深地陷入石棱中。', poem_notes = '塞下曲：古代歌曲名。这类作品多是描写边境风光和战争生活的。\n惊风：突然被风吹动。\n引弓：拉弓，开弓，这里包含下一步的射箭。\n平明：天刚亮的时候。\n白羽：箭杆后部的白色羽毛，这里指箭。\n没：陷入，这里是钻进的意思。\n石棱：石头的边角。\n将军——指的是西汉的飞将军李广。', poem_appreciation = '卢纶《塞下曲》共六首一组，分别写发号施令、射猎破敌、奏凯庆功等等军营生活。语多赞美之意。此为第二首，描写将军夜里巡逻时景况。\n\n　　首句写将军夜猎场所是幽暗的深林；当时天色已晚，一阵阵疾风刮来，草木为之纷披。这不但交代了具体的时间、地点，而且制造了一种气氛。右北平是多虎地区，深山密林是百兽之王的猛虎藏身之所，而虎又多在黄昏夜分出山，“林暗草惊风”，着一“惊”字，就不仅令人自然联想到其中有虎，呼之欲出，渲染出一片紧张异常的气氛，而且也暗示将军是何等警惕，为下文“引弓”作了铺垫。\n\n　　次句即续写射。但不言“射”而言“引弓”，这不仅是因为诗要押韵的缘故，而且因为“引”是“发”的准备动作，这样写能启示读者从中想象、体味将军临险是何等镇定自若，从容不迫。在一“惊”之后，将军随即搭箭开弓，动作敏捷有力而不仓皇，既具气势，而形象也益鲜明。\n\n　　后二句写“没石饮羽”的奇迹，把时间推迟到翌日清晨，将军搜寻猎物，发现中箭者并非猛虎，而是蹲石，令人读之，始而惊异，既而嗟叹，原来箭杆尾部装置着白色羽毛的箭，竟“没在石棱中”，入石三分。这样写不仅更为曲折，有时间、场景变化，而且富于戏剧性。“石棱”为石的突起部分，箭头要钻入殊不可想象。神话般的夸张，为诗歌形象涂上一层浪漫色彩，读来特别尽情够味，只觉其妙，不以为非。\n\n　　这首边塞小诗，写一位将军猎虎的故事，取材于西汉只学家司马迁记载当时名将李广事迹的《李将军列传》。原文是：“广出猎，见草中石，以为虎而射之中，中（zhòng）石没镞（箭头），视之，石也。”\n\n　　诗的前两句写事件的发生：深夜，山林里一片昏暗，突然狂风大作，草丛被乔得刷啦啦起伏抖动；蛙人起落处津津乐道恍恍惚惚有一头白虎扑来。恰好这时，将军正从林边驰马而过，他眼疾手快，拉满弓一箭射出… …\n\n　　后两句写事件的结果是：第二天清晨，将军记起昨晚林间的事，顺原路来到现场，他不禁大吃一惊：明亮的晨光中，分明看见被他射中的原来不是老虎，而是一座巨石。恐惧感默然蹲在那里，那枝白羽箭竟深深钻进石棱里去了！请注意箭射入的部位，不是石孔，不是石缝，也不是石面，而是窄细的尖突的石棱――这需要多大的臂力，多高的武艺啊！\n\n　　有人要问，将军射老虎，干吗不当时就看结果，还要等第二天早晨？原来的故事并没说第二天才知道射中的是石头呀！这，就是诗人的艺术处理了。第一，这样可以表现将军的自信，从来是百发百中，这一次还怕它死不了跑掉吗？第二，可以增加形象的直观性，让人看得更清楚些，如果是当夜就看，固然也能发现是一场误会，但很难取得现在这样的画面一般的鲜明效果。\n\n　　诗，最注重含蓄，最讲究意在言外。看到诗中箭入石的描写，我们会油然联想：如果射中的真是老虎将会射成什么样子？如果在战场上射击敌军兵马呢？于是，一位武艺高强、英勇善战的将军形象，便盘马弯弓、巍然屹立在我们眼前了。', poem_tags = '唐诗三百首,边塞,狩猎,赞美,将军' WHERE poem_title = '和张仆射塞下曲·其二' AND poem_author = '卢纶';
UPDATE edu_poem SET poem_translation = '自从分别之后，不知你已经到了何方？眼里心中都是凄凉与愁闷，生出不尽的忧愁！你越走越远，最后竟断了音信；江水是何等的宽阔，鱼儿深深地游在水底，我又能向何处去打听你的消息？ \n昨夜里大风吹得竹林处处作响，传递着深秋的韵律，每一片叶子的声响都似乎在诉说着怨恼。我有心斜倚着单枕，希望梦中能与你相遇，可惜梦做不成，无奈灯芯，又在秋风中燃成烬。', poem_notes = '鱼沉：古人有鱼雁传书之说，鱼沉，谓无人传言。 \n秋韵：即秋声。此谓风吹竹声。\n攲（qī）：倚、依。\n烬（jìn）：火烧剩余之物，此指灯花。', poem_appreciation = '这首词是作者的早期作品。词是写闺中思妇深沉凄绝的离愁别恨。发端句“别后不知君远近”是恨的缘由。因不知亲人行踪，故触景皆生出凄凉、郁闷，亦即无时无处不如此。“多少”，不知多少之意，以模糊语言极状其多。三四两句再进一层，抒写了远别的情状与愁绪。“渐行渐远渐无书”，一句之内重复了三个“渐”字，将思妇的想象意念从近处逐渐推向远处，仿佛去追寻爱人的足迹，然而雁绝鱼沉，天崖无处觅寻踪影。“无书”应首句的“不知”，且欲知无由，她只有沉浸在“水阔鱼沉何处问”的无穷哀怨之中了。“水阔”是“远”的象征，“鱼沉”是“无书”的象征。“何处问”三字，将思妇欲求无路、欲诉无门的那种不可名状的愁苦，抒写得极为痛切。在她与亲人相阻绝的浩浩水域与茫茫空间，似乎都充塞了触目凄凉的离别苦况。词的笔触既深沉又婉曲。\n\n　　词篇从过片以下，深入细腻地刻画了思妇的内心世界，着力渲染了她秋夜不寐的愁苦之情。“自古伤心唯远别，登山临水迟留。暮尘衰草一番秋。寻常景物，到此尽成愁。”（张先《临江仙·自古伤心惟远别》）风竹秋韵，原是“寻常景物”，但在与亲人远别，空床独宿的思妇听来，万叶千声都是离恨悲鸣，一叶叶一声声都牵动着她无限愁苦之情。“故欹单枕梦中寻，梦又不成灯又烬”。思妇为了摆脱苦状的现实，急于入睡成梦，故特意斜靠着孤枕，幻想在梦中能寻觅到在现实中寻觅不到的亲人，可是“千山万水不曾行，魂梦欲教何处觅？”（韦庄《木兰花·独上小楼春欲暮》）连仅有的一点小小希望也成了泡影，不单是“愁极梦难成”（薛昭蕴《小重山·春到长门春草青》），最后连那一盏作伴的残灯也熄灭了。“灯又烬”一语双关，闺房里的灯花燃成了灰烬，自己与亲人的相会也不可能实现，思妇的命运变得和灯花一样凄迷、黯淡。词到结句，哀婉幽怨之情韵袅袅不断，给人以深沉的艺术感染。\n\n　　前于欧阳修的花间派词人，往往喜欢对女性的外在体态服饰进行精心刻画，而对人物内心的思想感情则很少揭示。欧阳修显然比他们进了一大步，在这首词中，他没在使用一个字去描绘思妇的外貌形象，而是着力揭示思妇内心的思想感情，字字沉着，句句推进，如剥笋抽茧，逐层深入，由分别－－远别－－无音信－－夜闻风竹－－寻梦不成－－灯又烬，将一层、一层、又一层的愁恨写得越来越深刻、凄绝。全词写愁恨由远到近，自外及内，从现实到幻想，又从幻想回到现实。且抒情写景两得，写景句寓含着婉曲之情，言情句挟带着凄凉之景，表现出特有的深曲婉丽的艺术风格。', poem_tags = '宋词精选,秋天,闺怨' WHERE poem_title = '玉楼春·别后不知君远近' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '太阳啊月亮，你们的光芒照耀着大地。我嫁的这个人啊，却不再像过去那样对待我了。事情怎么变得这样了呢？一点也不顾念我呀。 \n太阳啊月亮，大地披上了你们的光芒。我嫁的这个人啊，却不再像过去那样恩爱我了。事情怎么变成这样了呢？一点也不念夫妻之情呀。 \n太阳呀月亮，你们每天都从东方升起。我嫁的这个人啊，却不再以好言好语安慰我了。事情怎么变成这样了呢？把那些无良之行都忘了吧。 \n太阳呀月亮，你们每天都从东方升起。我尊君如父，亲君如母，君却不以善终报我。事情怎么变成这样了呢，你自己也没有得到善终啊！', poem_notes = '居、诸：语尾助词。\n乃：可是。之人：这个人，指她的丈夫。\n逝：助词。无实义,起调整音节的作用。古处：一说旧处，和原来一样相处；一说姑处。\n胡：何，怎么。定：止。指心定、心安。\n宁：一说乃，曾；一说岂，竟然，难道。我顾：顾我。顾，念。\n.冒：覆盖，照临。\n相好：相爱。\n德音：好名誉。\n畜我不卒：即好我不终。畜，同“慉”，喜爱。不卒，不到最后。\n不述：不循义理。', poem_appreciation = '这是一首弃妇申诉怨愤的诗。《毛诗序》说：“《日月》，卫庄姜伤己也。遭州吁之难，伤己不见答于先君，以至困穷之诗也。”朱熹《诗集传》说：“庄姜不见答于庄公，故呼日月而诉之。言日月之照临下土久矣，今乃有如是之人，而不以古道相处，是其心志回惑，亦何能有定哉？”都说此诗作于卫庄姜被庄公遗弃后，以此诗作者为卫庄姜，所指责的男子为卫庄公。而鲁诗则认为是卫宣公夫人宣姜为让自己的儿子寿继位而欲杀太子伋，寿为救伋，亦死，后人伤之，为作此诗。今人一般认为这是弃妇怨丈夫变心的诗。\n\n　　诗的第一章把读者带入这样的境界：在太阳或月亮的光辉照耀下，一位妇人在她的屋旁呼日月而申诉：日月能如常地照耀大地，为何我的丈夫不能如以往一样顾念我！以后各章的第一句“日居月诸”作为起兴，还有一种陪衬的作用。日月出自东方、照临大地，是有定所，而结为夫妇的“之人”竟心志回惑，“胡能有定”。作者之所以反覆吟咏日月，正是为了陪衬其反覆强调的“胡能有定”的。\n\n　　第二第三章承第一章的反覆咏叹，真是“一诉不已，乃再诉之，再诉不已，更三诉之”（方玉润《诗经原始》）。第四章沉痛已极，无可奈何，只有自呼父母而叹其生之不辰了，前面感情的回旋，到此突然一纵，扣人心弦，“埋怨父母极无理，却有至情”（牛运震《诗志》）。\n\n　　诗中没有具体去描写弃妇的内心痛苦，而是着重于弃妇的心理刻画。女主人公的内心世界是很复杂的，有种被遗弃后的幽愤，指责丈夫无定止。同时她又很怀念她的丈夫，仍希望丈夫能回心转意，能够“顾”（想念）她，“报”（答理）她。理智上，她清醒地认识到丈夫“德音无良”；但情感上，她仍希望丈夫“畜我”以“卒”。朱熹《诗集传》说：“见弃如此，而犹有望之之意焉。此诗之所为厚也。”这种见弃与有望之间的矛盾，又恰恰是弃妇真实感情的流露。因此，《日月》能强烈震撼读者的心灵。延伸解析古代学者以为这是首弃妇声诉幽怨的愤诗，且很多人认定是“卫庄姜”（卫庄公夫人）感喟“州吁之难”（卫庄公庶子“公子州吁” 弑杀庄姜养子、卫桓公“姬完”的宫廷政变）的穷困诗。这种观点看似成立的理由是比较充分的，日月比喻国君与夫人，未亡人庄姜目睹宫廷剧变（卫公子州吁首开弑杀犯上之风，挑衅姬周宗法制度，被时人认为大逆不道），所以作诗追念先君亡夫，痛惜枉死的嗣君养子，哀叹自己的不良遭际但是仔细研究诗中细节，弃妇之说则疑窦颇多。尤其是抱怨父母一节，既不合于周人礼法（强调“孝悌”），也语意突兀：常人以给父母养老送终为俗，怎可颠倒要求父母终养自己？实际上结合周初历史和邶人的渊源，综合看待《国风.邶风》的低闷、忧郁风格，将这首诗同样视为殷遗怀旧的歌谣可能才更靠谱。熟悉中国上古史的研究者都知道：周朝推翻商朝后，最初的政策对亡国民众比较友好，武王君臣采取了各种措施极力安抚；后来因殷顽叛乱、周公旦才在镇压平叛后对其施以重大惩罚。如果扩大思路，将周人、商人这段恩怨变化的背景套入到《邶风.日月》篇中，则很多细节就更容易对号入座、解释通畅。日月起兴，是因为天道有恒，衬托人世容易变幻，暗喻商族亡国亡族（没有灭族，大贵族微子、萁子和其他小贵族保留了商族血脉，但纣王和武庚禄父这条主根化为浮云了）的沧海桑田悲剧。两厢难处，是当年周、商两族复杂关系的真实写照。处境飘摇窘困，是因为大叛乱后惩罚加身。作为曾经显赫、现在弱势的“殷顽”，自然会抱怨周朝，很容易将所有灾难都委过周室而不愿意深刻自省。所以诗中屡屡出现“逝不古处”、 “宁不我顾”……、 “德音无良”的抱怨，希冀处境得到改善，如此才“俾也可忘”。抱怨父母其实完全是比喻。犹如说：我们商人的祖先是天下共主，轮到我们这代人却不仅失去霸权，还因两次战败（前为武王克商的“牧野之战”，后为周公东征的二次征服），宗族亲人被离析打散、族群主体被监视居住。“胡能有定？报我不述。”也可以顺理成章解释。中国上古传统，灭人国而不绝其祀，夏、商、周三代均遵循这条重要国际规则。传说夏后（夏朝君主的称号）册封上古著名氏族为诸侯（实际上是认可）；汤王灭桀，也专门册封禹王的后人，承认各地氏族部落首领的诸侯地位（夏商封建都不是严格意义的封建制度，所谓封国其实是氏族部落或更大型的联盟而非地域国家，周朝的封建制才是真正意义的叠层封建联盟体制，周朝封国很多都是打破了血缘关系的地域型国家）；武王遵守传统，册封周人认定的上迄黄帝、炎帝、下止夏禹、商汤的后裔为诸侯。只是由于武庚组织叛乱，周公才粉碎了武庚的政权，重新安排处置“殷顽民”。诗中的“报我不述”应该是指武庚政权被粉碎的事情，作者认为周朝这样处置不合古礼和惯例。对这首诗的新解属于个人的一家之说，可以存疑，也欢迎有兴趣的朋友深度研究和发掘，权当是对继承发扬我国古老的国学文化略效绵薄之力。如果新说被证明成立，那么《邶风.日月》的创作时间就不是春秋，而是远为久远的周初。这首诗文辞古朴、风格与《邶风.柏舟》雷同也就相当自然，前面仔细分析过“柏舟”、可以更肯定的说和周初的大叛乱关系密切。', poem_tags = '诗经,闺怨' WHERE poem_title = '国风·邶风·日月' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '独自怅然拄杖还家，道路不平荆榛遍地。\n山涧流水清澈见底，途中歇息把足来洗。\n滤好家中新酿美酒，烹鸡一只款待邻里。\n太阳落山室内昏暗，点燃荆柴把烛代替。\n兴致正高怨恨夜短，东方渐白又露晨曦。', poem_notes = '怅恨：失意的样子。策：指策杖、扶杖。还：指耕作完毕回家。曲：隐僻的道路。这两句是说怀着失意的心情独自扶杖经过草木丛生的崎岖隐僻的山路回家了。　\n濯：洗。濯足：指去尘世的污垢。　\n漉：滤、渗。新熟酒：新酿的酒。近局：近邻、邻居。这两句是说漉酒杀鸡，招呼近邻同饮。　\n暗：昏暗。这句和下句是说日落屋里即昏暗，点一把荆柴代替蜡烛。　\n天旭：天明。这句和上句是说欢娱之间天又亮了，深感夜晚时间之短促。', poem_appreciation = '这首诗是陶渊明组诗《归园田居》五首的最后一首。对此诗的首句“怅恨独策还”，有两种解说：一说认为这首诗是紧承第四首《归园田居·久去山泽游》而作，例如方东树说，“怅恨”二字，承上昔人死无余意来”（《昭昧詹言》卷四），黄文焕也说，“昔人多不存，独策所以生恨也”（《陶诗析义》卷二）；另一说认为这一句所写的“还”，是“耕种而还”（邱嘉穗《东山草堂陶诗笺》中语）。这两说都嫌依据不足。如果作者所写是还自“荒墟”的心情，则组诗第四首《归园田居·久去山泽游》之“披榛步荒墟”为“携子侄辈”同往，应该不会“独策还”。如果作者是耕种归来，则所携应为农具，应如这组诗的第三首《归园田居·种豆南山下》所写，“荷锄”而归，似不应策杖而还。联系下三句看，此句所写，似不如视作“性本爱丘山”的作者在一次独游的归途中生发的“怅恨”。其“怅恨”，可以与此句中的“还”字有关，是因游兴未尽而日色将暮，不得不还；也可以与此句中的“独”字有关，是因独游而产生的孤寂之感。这种孤寂感，既是这次游而无伴的孤寂感，也是作者隐藏于内心的“举世皆浊我独清”（《楚辞·渔父》）的时代孤寂感。次句“崎岖历榛曲”，写的应是真景实事，但倘若驰骋联想，从象喻意义去理解，则当时的世途确是布满荆榛，而作者的生活道路也是崎岖不平的。联系其在《感士不遇赋序》中所说的“夷皓有安归之叹，三闾发已矣之哀”，不妨设想：其在独游之际，所感原非一事，怅恨决非一端。\n\n　　此诗的三、四两句“山涧清且浅，可以濯吾足”，则化用《孟子·离娄》“沧浪之水清兮，可以濯我缨；沧浪之永浊兮，可以濯我足”句意，显示了作者的生活情趣和委身自然、与自然相得相洽的质性。人多称渊明冲淡静穆，但他的心中并非一潭止水，更非思想单纯、无忧无虑。生活、世事的忧虑固经常往来于其胸中，只是他能随时从对人生的领悟、与自然的契合中使烦恼得到解脱、苦乐得到平衡，从而使心灵归于和谐。合一、二两句来看这首诗的前四句，正是作者的内心由怅恨而归于和谐的如实表述。\n\n　　这首诗写的是两段时间、两个空间。前四句，时间是日暮之前，空间是山路之上；后六句，则在时间上从日暮写到“天旭”，在空间上从“近局”写到“室中”。如果就作者的心情而言，则前四句以“怅恨”发端，而后六句以“欢来”收结。作者尝自称“质性自然，非矫厉所得”（《归去来兮辞序》），其“归田园居”的主要原因，如这组诗的首篇《归园田居·少无适俗韵》所说，为的是“复得返自然”，以求得本性的回归，保全心灵的真淳。这首诗所写的始则“怅恨”，终则“欢来”，当忧则忧，可乐则乐，正是其脱离尘网后一任自然的真情流露。\n\n　　后六句的“漉我新熟酒，只鸡招近局，日入室中暗，荆薪代明烛”四句，写作者还家后的实事实景，如其《杂诗十二首》之一所说，“得欢当作乐，斗酒聚比邻”。从这四句诗可以想见：酒为新熟，菜仅只鸡，草屋昏暗，以薪代烛，宛然一幅田家作乐图。这样的饮酒场面，其实很寒酸，但作者写来丝毫不觉其寒酸，令人读者看来也不会嫌其寒酸，而只会欣赏其景真情真，趣味盎然。篇末“欢来苦夕短，已复至天旭”二句，即张华《情诗》“居欢惜夜促”意，也寓有《古辞·西门行》“人生不满百，常怀千岁忧，昼短而夜长，何不秉烛游”几句中所抒发的人生短促、光阴易逝的感慨。而为了进一步理解、领会这两句诗的内涵，还可以参读作者的另一些诗句，如《游斜川》诗所说的“中觞纵遥情，忘彼千载忧，且极今朝乐，明日非所求”，又如《己酉岁九月九日》诗所说的“从古皆有没，念之中心焦，何以称我情，浊酒且自陶，千载非所知，聊以永今朝。”从这些诗来看作者的这次欢饮，有聊以忘忧的成分，在“欢”的背后其实闪现着“忧”的影子。同时，作者之饮酒也是他的逃世的手段，是为了坚定其归田的决心，如其《饮酒二十首》诗所说，“泛此忘忧物，远我遗世情”（《饮酒·秋菊有佳色》），“纡辔诚可学，违己讵非迷，且共欢此饮，吾驾不可回”（《饮酒·清晨闻扣门》）。当然，他的饮酒更是与其旷达的心性相表里的；这就是他在《饮酒》诗的首章所说的“寒暑有代谢，人道每如兹，达人解其会，逝将不复疑，忽与一觞酒，日夕欢相持。”\n\n　　朱光潜在《论诗》第十三章《陶渊明》中谈到渊明的情感生活时指出，他“并不是一个很简单的人。他和一般人一样，有许多矛盾和冲突；和一切伟大诗人一样，他终于达到调和静穆。”对于这首诗所写的“怅恨”、“欢来”以及“苦”时间之短促，是应从多方面去理解、领会的。', poem_tags = '田园,生活,孤独,感慨,人生' WHERE poem_title = '归园田居·其五' AND poem_author = '陶渊明';
UPDATE edu_poem SET poem_translation = '乐声初发，仿佛静夜微弱的灯光下，一对青年男女在亲昵地切切私语。弹奏开始，音调既轻柔、细碎而又哀怨、低抑。曲调由低抑到高昂，犹如气宇轩昂的勇士，在镇然骤响的鼓声中，跃马驰骋，不可阻挡。乐曲就如远天的暮云，高空的飞絮一般，极尽缥缈幽远之致。\n百鸟争喧，明媚的春色中振颤着宛转错杂的啁哳之声，唯独彩凤不鸣。瞬息间高音突起，好像走进悬崖峭璧之中，寸步难行。这时音声陡然下降，宛如突然坠入深渊，一落千丈，之后弦音戛然而止。弹者好像能兴风作雨，让人肠中忽而高寒、忽而酷热，坐立不宁。弹者把琵琶一推放下，散去的听众无不为之流泪，君章质夫无不为之倾心同感。', poem_notes = '水调歌头：词牌名，又名《元会曲》、《凯歌》、《台城游》等。双调，九十五字，平韵（宋代也有押仄韵的）。相传隋炀帝开汴河自制《水调歌》，唐人演为大曲，《歌头》即大典开始的第一章。\n隐括：原义是矫正曲木的工具。词的檃括是将其他诗文剪裁改写为词的形式，宋人常有此类作品。\n昵昵：音逆，古音尼。象声词，形容言辞亲切。\n尔汝：表亲昵。\n填然：状声响之巨。\n青冥：①形容青苍幽远。指青天。②形容青苍幽远。指山岭。③指海水。\n跻攀：登攀。跻音机。\n寻：长度单位。《史记·张仪传》有“蹄间三寻”。索隐云“七尺曰寻。”亦有云八尺为寻者。如寻常，八尺为寻，倍寻为常，皆惯见之长度也。', poem_appreciation = '苏轼通过联想，在上阙运用以形象描写不同风格的音乐，从开始的轻柔旖旎，瞬间变为雄壮高扬，然后归于悠扬致远；在下阙则对比音乐本身，一是同一时间内，繁音细响与清越之声之对比，二是不同时间内，音乐之抑扬起伏的对比，添之以自己的感慨，使整首诗具备与原作不同的艺术韵味。\n\n　　词先写乐声初发，仿佛一对青年男女在静夜微弱的灯光下，亲昵地私语 ，谈受说恨，卿卿我我，往复不已。“弹指泪和声”倒点一句，见出弹奏开始，音调轻柔而又哀怨。“忽变”三句，写曲调由低抑到高昂，犹如战士在鼓声下驰骋沙场，无人可挡。结尾的“回首”两句，以景物形容声情，把音乐形象化给人缥渺幽远之感，。“回首暮云远“，让人联想起王维“回看射雕处，千里暮云平“之将士，也与上文中“轩昂勇士”相联系，将独立的音乐片段串起来。白云浮动，柳絮漂浮，若有若无，忽远忽近，难以捉摸，却逗人情思。\n\n　　接着是百鸟争喧，明媚的春色与啁哳之声相伴，唯独彩凤不鸣。这里写以凤凰不鸣，起到“留白“的特殊效果，也点出了深刻哲理：真正内涵的，从不在言语上夺人眼球。之后琴声在瞬息间高音突起，曲折而上，曲调转向艰涩，好象走进悬崖峭璧之中，脚登手攀，前行一寸，也要花费很大气力。正在步履维艰之际，音声陡然下降，恍如一落千丈，飘然坠入深渊，弦音戛然而止。至此，词人确乎借助于语言，把这位乐师的高妙弹技逼真地再现出来了。最后五句，则是从听者心情的激动，反映出成功的弹奏所产生的感人的艺术效果。“指间风雨”，写弹者技艺之高，能兴风作雨；“肠中冰炭”，写听者感受之深，肠中忽而高寒、忽而酷热；并以“烦子”、“置我”等语，把双方紧密关联起来。音响之撼人，不仅使人坐立不宁 ，而且简直难以禁受，由于连连泣下，再没有泪水可以倾洒了。“推手从归去”描写的是琴师奏完将琴推开的动作，也在其中暗示这诗人心中归隐的情怀。“无泪与君倾”，表现出诗人此时肠中之郁结，比起原诗中“湿衣泪滂滂”更为不堪较之，更为含蓄，也更为深沉，虽然无落泪，但是更加表现出心情的郁结。\n\n　　诉诸听觉的音乐美，缺乏空间形象的鲜明性和确定性，是很难捕捉和形容的。但词人巧于取譬，他运用男女谈情说爱、勇士大呼猛进、飘荡的晚云飞絮、百鸟和鸣、攀高步险等等自然和生活现象，极力摹写音声节奏的抑扬起伏和变化，借以传达乐曲的感情色调和内容。这一系列含义丰富的比喻，变抽象为具体，把诉诸听觉的音节组合，转化为诉诸视觉的生动形象，这就不难唤起一种类比的联想，从而产生动人心弦的感染力。末后再从音乐效果，进一步刻画弹技之高，笔墨精微神妙，可说与韩诗同一机杼，同入化境。\n\n　　苏轼这首词的“隐括”，即把韩愈的诗文《听颖师弹琴》剪裁改曲词，虽保留了韩诗的总体构思和一些精彩的描绘，但又在内容、形式以及两者的结合上，显示了自己的创造性，从而使此词获得了新的艺术生命和独特的审美价值。', poem_tags = '咏物,音乐' WHERE poem_title = '水调歌头·昵昵儿女语' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '暗淡的紫色，鲜艳的黄色。\n它们既有陶渊明篱边菊花的色彩，又有罗含宅中的香味。\n菊花不怕露水的沾湿，可是害怕夕阳的来临。\n愿意留在水边畅饮的人的鹦鹉杯中，希望来到富贵人家丰盛的酒席上。', poem_notes = '融融：光润的样子。\n冶冶：艳丽的样子。\n陶令：指陶渊明，因其主彭泽县做过县令，故称陶令。\n罗含：（公元293年一公元369年）字君长，号富和，东晋桂阳郡耒阳（今湖南未阳市）人。博学能文，不慕荣利，编苇作席，布衣蔬食，安然自得。被江夏太守谢尚赞为“湘中之琳琅”。桓温称之为“江左之秀”。官至散骑廷尉。年老辞官归里，比及还家，阶庭忽兰菊丛生，时人以为德行之感。\n禁：禁受，承当。\n重露：指寒凉的秋露。\n怯：胆怯、担心。\n残：一作“斜”。\n金鹦鹉：金制的状如鹦鹉螺的酒杯。泛：指以菊花浸酒。\n白玉堂：指豪华的厅堂，喻朝廷。升：摆进。', poem_tags = '菊花' WHERE poem_title = '菊花' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '难道说我没衣服穿？我的衣服有七件。但都不如你亲手做的，既舒适又美观。\n难道说我没衣服穿？我的衣服有六件。但都不如你亲手做的，既舒适又温暖。', poem_notes = '七：虚数，言衣之多；一说七章之衣，诸侯的服饰。\n子：第二人称的尊称、敬称，此指制衣的人。\n安：舒适。吉：美，善。\n六：一说音路，六节衣。\n燠（yù 玉）：暖热。', poem_appreciation = '此诗与《秦风·无衣》题目及首句皆相同，然思想内容与艺术风格却完全两样。从字面上看，似觉并无深意，但前人往往曲为之说，《毛诗序》云：“《无衣》，美晋武公也。武公始并晋国，其大夫为之请命乎天子之使，而作是诗也。”朱熹《诗集传》云：“曲沃桓叔之孙武公伐晋，灭之，尽以其宝器赂周釐王。王以武公为晋君，列于诸侯。此诗盖述其请命之意”，“釐王果贪其宝玩，而不思天理民彝之不可废，是以诛讨不加，而爵命行焉。”（同上）这一说法今人多表示怀疑，如程俊英《诗经译注》就认为“恐皆附会”。\n\n　　从诗意来看，此篇似为览衣感旧或伤逝之作。诗人可能是一个民间歌手，他本来有一位心灵手巧的妻子，家庭生活十分美满温馨。不幸妻子早亡，一日他拿起衣裳欲穿，不禁睹物思人，悲从中来。诗句朴实无华，皆从肺腑中流出：“难道说我没有衣裳穿？我的衣裳有七件，可是拣了一件又一件，没有一件抵得上你亲手缝制的衣裳，那样舒坦，那样美观。”“难道说我没有衣裳穿？我的衣裳有六件。可是挑了一件又一件，没有一件抵得上你亲手缝制的衣裳，那样合身，那样温暖。”语言自然流畅，酷肖人物声口。感情真挚，读之令人凄然伤怀。\n\n　　对于诗中的句读，旧说两段的起句都作六字句，然今人徐培均认为应标点为：“岂曰无衣？七兮。”前四字为一句，用以自问，后二字为一句，用以自答，诗人正是在这种自问自答中，抒写了一腔哀思。另外在一些字、词的解释上也颇多歧见。如“七”字、“子”字、“六”字，朱熹《诗集传》以为“侯伯七命，其车旗衣服，皆以七为节。子，天子也”。又云：“天子之卿六命，变‘七’言‘六’者，谦也，不敢以当侯伯之命，得受六命之服，比于天子之卿亦幸矣。”朱熹的解释，完全服从于他对于这首诗主题的理解。这首诗既然是述晋武公向周釐王请求封爵之意，那末他就必然把“七”解释为“诸侯七命”，把“六”解释为“天子之卿六命”，而把“子”解释为“天子”。前二者与晋武公的诸侯身份相当，后者则与周釐王的天子地位相称。其说固然言之成理，不失为一家之见，然与诗的本意可能相去甚远。\n\n　　从对此诗主题的理解出发，“七”和“六”俱为数词，也可以看作虚数，极言衣裳之多。而“子”则为第二人称的“你”，也即缝制衣裳的妻子。这样的理解，应该是符合诗的本意的。\n\n　　全诗分为两章，字句大体相同，唯两起变动一个字：“七”易为“六”；两结也变动一字：“吉”易为“燠”。这主要为的是适应押韵的需要。从全篇来说，相同的句式重复一遍，有回环往复、一唱三叹、回肠荡气之妙，读者在吟诵中自然能体会其中的情韵。', poem_tags = '古诗三百首,诗经,咏物,怀人' WHERE poem_title = '无衣' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '听那蝈蝈蠷蠷叫，看那蚱蜢蹦蹦跳。没有见到那君子，我心忧愁又焦躁。如果我已见着他，如果我已偎着他，我的心中愁全消。\n登上高高南山头，采摘鲜嫩蕨菜叶。没有见到那君子，我心忧思真凄切。如果我已见着他，如果我已偎着他，我的心中多喜悦。\n登上高高南山顶，采摘鲜嫩薇菜苗。没有见到那君子，我很悲伤真烦恼。如果我已见着他，如果我已偎着他，我的心中块垒消。', poem_notes = '草虫：一种能叫的蝗虫，蝈蝈儿。\n喓（yāo）喓：虫鸣声。\n趯（tì）趯：昆虫跳跃之状。阜（fù）螽（zhōng）：即蚱蜢，一种蝗虫。\n忡（chōng）忡：犹冲冲，形容心绪不安。\n亦：如，若。既：已经。止：之、他，一说语助词。\n觏（gòu）：遇见。\n降（xiáng）：悦服，平静。\n陟（zhì）：升；登。登山盖托以望君子。\n蕨：野菜名，初生无叶时可食。\n惙（chuò）惙：忧，愁苦的样子。\n说（yuè）：通“悦”，高兴。\n薇：草本植物，又名巢菜，或野豌豆，似蕨，而味苦，山间之人食之，谓之迷蕨。\n夷：平，此指心情平静。', poem_appreciation = '这是一首妻子思念丈夫的诗歌，和《周南·卷耳》一样，也有想象的意境。全诗三章，每章七句。第一章写思妇秋天怀人的情景，第二、三章分别叙写来年春天、夏天怀人的情景。全诗表现了跨度很长的相思苦。\n\n　　首章将思妇置于秋天的背景下，头两句以草虫鸣叫、阜螽相随蹦跳起兴，这是她耳闻目睹的，说是赋亦无不可。画面之内如此，画面之外可以猜想，她此时也许还感受到秋风的凉意，见到衰败的秋草，枯黄的树叶，大自然所呈露的无不是秋天的氛围。“悲哉秋之为气也”，秋景最易勾起离情别绪，怎奈得还有那秋虫和鸣相随的撩拨，诗人埋在心底的相思之情一下子被触动了，激起了心中无限的愁思：“未见君子，忧心忡忡。”此诗构思的巧妙，就在于以下并没有循着“忧心忡忡”写去，而是打破了常规，完全撇开离情别绪，诸如自己孤处的凄凉、强烈的思念，竟不着一字，而却改用拟想，假设所思者突然出现在自己面前将会是如何的情景。诗云，“亦既见之，亦既觏之，我心则降。”见，说的是会面；觏，《易》曰：“男女觏精，万物化生。”故郑笺谓“既觏”是已婚的意思，可见“觏”当指男女情事而言。降，下的意思，指精神得到安慰，一切愁苦不安皆已消失。古人质直，即使是女诗人也不作掩饰。这里以“既见”、“既觏”与“未见”相对照，情感变化鲜明，欢愉之情可掬。运用以虚衬实，较之直说如何如何痛苦，既新颖、具体，又情味更浓。方玉润说：“本说‘未见’，却想及既见情景，此透过一层法。”（《诗经原始》）所谓“透过一层法”，指的就是虚实相衬法。\n\n　　第二、三章虽是重叠，与第一章相比，不仅转换了时空，拓宽了内容，情感也有发展。登高才能望远，诗人“陟彼南山”，为的是赡望“君子”。然而从山颠望去，所见最显眼的就是蕨和薇的嫩苗，诗人无聊之极，随手无心采着。采蕨、采薇暗示经秋冬而今已是来年的春夏之交，换句话说，诗人“未见君子”不觉又多了一年，其相思之情自然也是与时俱增，“惙惙”表明心情凝重，几至气促；“伤悲”更是悲痛无语，无以复加。与此相应的，则是与君子“见”、“觏”的渴求也更为迫切，她的整个精神依托、全部生活欲望、唯一欢乐所在，几乎全系于此：“我心则说（悦）”、“我心则夷”，多么大胆而率真的感情，感人至深。\n\n　　此诗虽是重章结构，押韵却有变化，首章一、二、四、七句用韵；而二、三章则是二、四、七用韵。另外王力《诗经韵读》认为各章第三句“子”与第五、六句“止”亦是韵脚。', poem_tags = '诗经,抒情,思念' WHERE poem_title = '国风·召南·草虫' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '曾子的妻子到集市上去，她的儿子跟随着她在她后面边走边哭。曾子的妻子对儿子说：“你先回去，等我回来后杀猪给你吃。”妻子从集市上回来，曾子就想抓只猪准备杀了它。他的妻子马上阻止他说：“我只不过是跟儿子开了个玩笑罢了。”曾子说：“不可以与儿子开玩笑。儿子什么都不懂，他只学习父母的，听从父母的教导。现在你欺骗了他，这就是在教育他欺骗人。母亲欺骗儿子，儿子就不会再相信他的母亲了，这不是正确教育孩子的方法啊。” 于是曾子就煮猪给孩子吃了。', poem_notes = '曾子（前505～前432）：曾参，春秋末年鲁国人，孔子的弟子，字子舆，被尊称为曾子。性情沉静，举止稳重，为人谨慎，待人谦恭，以孝著称。曾提出“慎终追远，民德归厚”的主张和“吾日三省吾身”的修养方法。据传以修身为主要内容的《大学》是他的作品。 \n彘（zhì）：猪。\n适：往、回去。适市回：去集市上回来。\n戏：开玩笑。\n非与戏：不可同……开玩笑。\n待：依赖。\n子：这里是第二人称尊称“您”的意思。`\n而：则，就。\n非所以成教也：这样做就不能把孩子教育好。\n之：到\n烹（pēng）： 烹饪，煮。\n是：这\n反：同“返”，返回\n顾反：等到回来。\n特：只、仅、独、不过。\n女：同“汝”，你的意思\n杀：宰\n曾子之妻之市:曾子的妻子到集市去.之,前一个作助词“的“,后一个作动词“去“.市,集市.\n欲：想要\n止：阻止\n遂：于是，就', poem_tags = '小学文言文,教育,寓理,故事' WHERE poem_title = '曾子杀彘 / 曾子烹彘' AND poem_author = '韩非';
UPDATE edu_poem SET poem_translation = '宋国（今商丘）有一个养猕猴的老人，他很喜欢猕猴，养的猕猴成群，他能懂得猕猴们的心意，猕猴们懂得那个人的心意。那位老人因此减少了他全家的口粮，来满足猕猴们的欲望。但是不久，家里缺乏食物了，他将要限制猕猴们的食物，但又怕猕猴们生气不听从自己，就先骗猕猴们：“我给你们的橡树果实，早上三颗，晚上四颗，这样够吗？”众多猕猴一听很生气，都跳了起来。过了一会儿，他又说：“我给你们的橡树果实，早上四颗，晚上三颗，这样足够吗？”猕猴们听后都很开心地趴下，都很高兴对那老人服服帖帖的了。', poem_notes = '狙（jū）公：养猴子的老头。\n解：了解，理解，懂得。\n狙：猴子。\n意：心意。\n得：懂得。\n得公之心：了解养猴老人的心思。\n损：减。\n口：口粮。\n充：满足。\n欲：欲望，要求。\n俄而：一会儿，不久。\n匮：缺乏。\n限：限制。\n恐：恐怕。\n驯（xùn）：驯服，顺从，听从。引申为服服帖帖。\n诳（kuáng）：欺骗。\n之：代词，它，代指猴子们。\n与：给。\n若：文言文中的人称代词，代“你”、“你们”，文中指猴子们。\n芧（xù）：橡树的果实，俗称“橡实”。\n朝：早上。\n足：够，足够。\n众：所有的。\n皆：都。\n起怒：一齐生气起来。怒：恼怒，生气。\n伏而喜：都很高兴地趴在地上（一般是动物感到满足时的动作）。', poem_appreciation = '寓意 　　这个故事原来的意义，是阐述一个哲学道理，是《庄子·齐物论》中一则重要的寓言故事，无论朝三暮四还是朝四暮三，其实众猴子所得到的并没有增加或减少，猴子们喜怒为用就显得很可笑。狙公好比是载众生的“大块”而猴子就像是纷乱红尘中的众生。那些追求名和实的理论家，总是试图区分事物的不同性质，而不知道事物本身们就有同一性。最后不免像猴子一样，被朝三暮四和朝四暮三所蒙蔽。告诫人们要放开计较得失的凡心，因为人的一生一死、一得一失都是一时的，到最后我们将会发现我们并没有失去什么，也没有得到什么。因为无论形式有多少种，本质只有一种。宋《二程全书·遗书·十八·伊川先生语》：“若曰圣人不使人知，岂圣人之心是后世朝三暮四之术也？”遗憾的是，后来应用这个成语的人，并不十分清楚朝三暮四的出处，把它和“朝秦暮楚”混淆了。而后者指的是战国时期，秦、楚两大强国对立，有些弱小国家一会儿倒向秦国，一会儿倒向楚国。就像在美苏争霸时期，有些非洲国家时而倒向美国，时而倒向苏联。朝三暮四本来与此无关，但以讹传讹，天长日久，大家也就习惯把“朝三暮四”理解为没有原则，反复无常了。 ▲', poem_tags = '小学文言文,寓言,故事,哲理' WHERE poem_title = '朝三暮四' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '我的生命是有限的，而知识是无限的。以有限的生命去追求无限的知识，真是危险啊！已经有了危险，还要执著地去追求知识，那么除了危险以外就什么都已经没有了。做好事不要求名，做坏事不要受刑罚，以遵循虚无的自然之道为宗旨，便可以保护生命，可以保全天性，可以养护新生之机，可以享尽天年。\n　　庖丁给梁惠王宰牛。手接触的地方，肩膀倚靠的地方，脚踩的地方，膝盖顶的地方，哗哗作响，进刀时豁豁地，没有不合音律的：合乎（汤时）《桑林》舞乐的节拍，又合乎（尧时）《经首》乐曲的节奏。\n　　梁惠王说：“嘻，好啊！（你解牛的）技术怎么竟会高超到这种程度啊？”\n　　庖丁放下刀回答说：“我追求的，是道（本为虚词，无特定之意，可解成自然的规律），已经超过一般的技术了。起初我宰牛的时候，眼里看到的是一只完整的牛；三年以后，再未见过完整的牛了（意思是：只看见一个虚线的牛，就是只看见怎么样去解）。现在，我凭精神和牛接触，而不用眼睛去看，感官停止了而精神在活动。依照牛的生理上的天然结构，砍入牛体筋骨相接的缝隙，顺着骨节间的空处进刀，依照牛体本来的构造，筋脉经络相连的地方和筋骨结合的地方，尚且不曾拿刀碰到过，更何况大骨呢！技术好的厨师每年更换一把刀，是用刀割断筋肉割坏的（就像我们用刀割绳子一样）；技术一般的厨师每月就得更换一把刀，是砍断骨头而将刀砍坏的（因为不知道怎么砍，所以砍到骨头的时候就容易坏）。如今，我的刀用了十九年，所宰的牛有几千头了，但刀刃锋利得就像刚在磨刀石上磨好的一样。那牛的骨节有间隙，而刀刃很薄；用很薄的刀刃插入有空隙的骨节，宽宽绰绰地，那么刀刃的运转必然是有余地的啊！因此，十九年来，刀刃还像刚从磨刀石上磨出来的一样。虽然是这样，每当碰到筋骨交错聚结的地方，我看到那里很难下刀，就小心翼翼地提高警惕，视力集中到一点，动作缓慢下来，动起刀来非常轻，豁啦一声，牛的骨和肉一下子就解开了，就像泥土散落在地上一样。我提着刀站立起来，为此举目四望，为此悠然自得，心满意足，然后把刀擦抹干净，收藏起来。”\n　　梁惠王说：“好啊！我听了庖丁的这番话，懂得了养生的道理了。”', poem_notes = '（1） 庖（páo）丁：名丁的厨工。先秦古书往往以职业放在人名前。文惠君：即梁惠王，也称魏惠王。解牛：宰牛，这里指把整个牛体开剥分剖。\n（2） 踦（yǐ）：支撑，接触。这里指用一条腿的膝盖顶牛。\n（3）砉（huā）然：砉，又读xū，象声词。砉然，皮骨相离的声音。向，通”响“。\n（4）騞（huō）然：象声词，形容比砉然更大的进刀解牛声。\n（5）桑林：传说中商汤时的乐曲名。\n（6）经首：传说中尧乐曲《咸池》中的一章。会：指节奏。以上两句互文，即“乃合于桑林、经首之舞之会”之意。\n（7）嘻：赞叹声。\n（8）盖：通“盍（hé）”，何，怎样。\n（9）进：超过。\n（10）官知：这里指视觉。神欲：指精神活动。\n（11）天理：指牛的生理上的天然结构。\n（12）批大郤：击入大的缝隙。批：击。郤：空隙。\n（13）导大窾（kuǎn）：顺着（骨节间的）空处进刀。\n（14）因：依。固然：指牛体本来的结构。\n（15）技经：犹言经络。技，据清俞樾考证，当是“枝”字之误，指支脉。经，经脉。肯：紧附在骨上的肉。綮（qìng）：筋肉聚结处。技经肯綮之未尝，即“未尝技经肯綮”的宾语前置。\n（16）軱（gū）：股部的大骨。\n（17）割：这里指生割硬砍。\n（18）族：众，指一般的。\n（19）折：用刀折骨。\n（20）发：出。硎（xíng）：磨刀石。\n（21）节：骨节。间：间隙。\n（22）恢恢乎：宽绰的样子。\n（23）族：指筋骨交错聚结处。\n（24）怵（chù）然：警惧的样子。\n（25）謋（huò）：象声词。骨肉离开的声音。\n（26）委地：散落在地上。\n（27）善：通”缮“，修治。这里是拭擦的意思。\n（28）养生：指养生之道。', poem_appreciation = '牛无疑是很复杂的，庖丁解牛，为什么能一刀下去，刀刀到位，轻松简单，原因是什么？是因为掌握了它的肌理。牛与牛当然各不相同，但不管是什么牛，它们的肌理都是一致的；每个人的生活也各有各的面貌，其基本原理也是近似的。庖丁因为熟悉了牛的肌理，自然懂得何处下刀。生活也一样，如果能透解了、领悟了生活的道理，摸准了其中的规律，就能和庖丁一样，做到目中有牛又无牛，就能化繁为简，真正获得轻松。\n\n　　做事应处处小心，还要保持着一种谨慎小心的态度，收敛锋芒，并且在懂得利用规律的同时，更要去反复实践，像庖丁“所解数千牛矣”一样，不停地重复，终究会悟出事物的真理所在。\n\n　　人类社会充满着错综复杂的矛盾，人处世间，只有像庖丁解牛那样避开矛盾，做到顺应自然，才能保身、全生、养心、尽年。', poem_tags = '哲理,故事' WHERE poem_title = '庖丁解牛' AND poem_author = '庄周';
UPDATE edu_poem SET poem_translation = '正午的柳荫直直地落下，雾霭中，丝丝柳枝随风摆动。在古老的隋堤上，曾经多少次看见柳絮飞舞，把匆匆离去的人相送。每次都登上高台向故乡瞭望，杭州远隔山水一重又一重。旅居京城使我厌倦，可有谁知道我心中的隐痛？在这十里长亭的路上，我折下的柳条有上千枝，可总是年复一年地把他人相送。\n我趁着闲暇到了郊外，本来是为了寻找旧日的行踪，不料又逢上筵席给朋友饯行。华灯照耀，我举起了酒杯，哀怨的音乐在空中飘动。驿站旁的梨花已经盛开，提醒我寒食节就要到了，人们将把榆柳的薪火取用。我满怀愁绪看着船像箭一样离开，梢公的竹篙插进温暖的水波，频频地朝前撑动。等船上的客人回头相看，驿站远远地抛在后面，端的离开了让人愁烦的京城。他想要再看一眼天北的我哟，却发现已经是一片蒙胧。\n我孤零零地十分凄惨，堆积的愁恨有千万重。送别的河岸迂回曲折，渡口的土堡一片寂静。春色一天天浓了，斜阳挂在半空。我不禁想起那次携手，在水榭游玩，月光溶溶。我们一起在露珠盈盈的桥头，听人吹笛到曲终……唉，回忆往事，如同是一场大梦。我暗中不断垂泪。', poem_notes = '兰陵王：词牌名，首见于周邦彦词。一百三十字，分三段。\n柳阴直：长堤之柳，排列整齐，其阴影连缀成直线。\n烟：薄雾。丝丝弄碧：细长轻柔的柳条随风飞舞，舞弄其嫩绿的姿色。弄：飘拂。\n隋堤：汴京附近汴河之堤，隋炀帝时所建，故称。是北宋是来往京城的必经之路。\n拂水飘绵：柳枝轻拂水面，柳絮在空中飞扬。行色：行人出发前的景象、情状。\n故国：指故乡。\n京华倦客：作者自谓。京华，指京城，作者久客京师，有厌倦之感，故云。\n长亭：古时驿路上十里一长亭，五里一短亭，供人休息，又是送别的地主。\n“应折”句：古人有折柳送别之习。柔条：柳枝。过千尺：极言折柳之多。\n旧踪迹：指过去登堤饯别的地方。\n又：又逢。酒趁哀弦：饮酒时奏着离别的乐曲。趁：逐，追随。哀弦：哀怨的乐声。\n离席：饯别的宴会。\n“梨花”句：饯别时正值梨花盛开的寒食时节。唐宋时期朝廷在清明日取榆柳之火以赐百官，故有“榆火”之说。寒食：清明前一天为寒食。 \n一箭风快：指正当顺风，船驶如箭。\n半篙波暖：指撑船的竹篙没入水中，时令已近暮春，故曰波暖。\n迢递：遥远。驿：驿站。\n“望人”句：因被送者离汴京南去，回望送行人，故曰天北。望人：送行人。\n凄恻：悲伤。\n渐：正当。别浦：送行的水边。萦回：水波回旋。\n恨：这里是遗憾的意思。\n津堠：渡口附近供瞭望歇宿的守望所。津：渡口。堠：哨所。岑寂：冷清寂寞。\n冉冉：慢慢移动的样子。春无极：春色一望无边。\n念：想到。月榭：月光下的亭榭。榭，建在高台上的敞屋。\n露桥：布满露珠的桥梁。', poem_appreciation = '这首词的题目是“柳”，内容却不是咏柳，而是伤别。古代有折柳送别的习俗，所以诗词里常用柳来渲染别情。隋无名氏的《送别》：“杨柳青青著地垂，杨花漫漫搅天飞。柳条折尽花飞尽，借问行人归不归。”便是人们熟悉的一个例子。周邦彦这首词也是这样，它一上来就写柳阴、写柳丝、写柳絮、写柳条，先将离愁别绪借着柳树渲染了一番。\n\n　　“柳阴直，烟里丝丝弄碧。”这个“直”字不妨从两方面体会。时当正午，日悬中天，柳树的阴影不偏不倚直铺在地上，此其一。长堤之上，柳树成行，柳阴沿长堤伸展开来，划出一道直线，此其二。“柳阴直”三字有一种类似绘画中透视的效果。“烟里丝丝弄碧”转而写柳丝。新生的柳枝细长柔嫩，像丝一样。它们仿佛也知道自己碧色可人，就故意飘拂着以显示自己的美。柳丝的碧色透过春天的烟霭看去，更有一种朦胧的美。\n\n　　以上写的是自己这次离开京华时在隋堤上所见的柳色。但这样的柳色已不止见了一次，那是为别人送行时看到的：“隋堤上，曾见几番，拂水飘绵送行色。”“拂水飘绵”这四个字锤炼得十分精工，生动地摹画出柳树依依惜别的情态。那时词人登上高堤眺望故乡，别人的回归触动了自己的乡情。这个厌倦了京华生活的客子的怅惘与忧愁有谁能理解呢：“登临望故国，谁识京华倦客？”隋堤柳只管向行人拂水飘绵表示惜别之情，并没有顾到送行的京华倦客。其实，那欲归不得的倦客，他的心情才更悲凄。\n\n　　接着，词人撇开自己，将思绪又引回到柳树上面：“长亭路，年去岁来，应折柔条过千尺。”古时驿路上十里一长亭，五里一短亭。亭是供人休息的地方，也是送别的地方。词人设想，在长亭路上，年复一年，送别时折断的柳条恐怕要超过千尺了。这几句表面看来是爱惜柳树，而深层的涵义却是感叹人间离别的频繁。情深意挚，耐人寻味。\n\n　　上片借隋堤柳烘托了离别的气氛，中片便抒写自己的别情。“闲寻旧踪迹”这一句读时容易忽略。那“寻”字，并不是在隋堤上走来走去地寻找。“踪迹”，也不是自己到过的地方。“寻”是寻思、追忆、回想的意思。“踪迹”指往事而言。“闲寻旧踪迹”，就是追忆往事的意思。当船将开未开之际，词人忙着和人告别，不得闲静；这时船已启程，周围静了下来，自己的心也闲下来了，就很自然地要回忆京华的往事。这就是“闲寻”二字的意味。现代人也会有类似的经验，亲友到月台上送别，火车开动之前免不了有一番激动和热闹。等车开动以后，坐在车上静下心来，便去回想亲友的音容乃至别前的一些生活细节。这就是“闲寻旧踪迹”。此时周邦彦想起了：“又酒趁哀弦，灯照离席。梨花榆火催寒食。”有的注释说这是写眼前的送别，恐不妥。眼前如是“灯照离席”，已到夜晚，后面又说“斜阳冉冉”，时间就接不上。所以这应是船开以后寻思旧事。在寒食节前的一个晚上，情人为他送别。在送别的宴席上灯烛闪烁，伴着哀伤的乐曲饮酒。此情此景难以忘怀。这里的“又”字说明，从那次的离别宴会以后词人已不止一次地回忆，如今坐在船上又一次回想起那番情景。“梨花榆火催寒食”写明那次饯别的时间，寒食节在清明前一天，旧时风俗，寒食这天禁火，节后另取新火。唐制，清明取榆、柳之火以赐近臣。“催寒食”的“催”字有岁月匆匆之感。岁月匆匆，别期已至了。\n\n　　“愁一箭风快，半篙波暖，回头迢递便数驿，望人在天北。”周济《宋四家词选》曰：“一愁字代行者设想。”他认定作者是送行的人，所以只好作这样曲折的解释。其实这四句很有实感，不像设想之辞，应当是作者自己从船上回望岸边的所见所感。“愁一箭风快，半篙波暖，回头迢递便数驿”，风顺船疾，行人本应高兴，词里却用一“愁”字，这是因为有人让他留恋着。回头望去，那人已若远在天边，只见一个难辨的身影。“望人在天北”五字，包含着无限的怅惘与凄惋。\n\n　　中片写乍别之际，下片写渐远以后。这两片的时间是连续的，感情却又有波澜。“凄恻，恨堆积！”船行愈远，遗憾愈重，一层一层堆积在心上难以排遣，也不想排遣。“渐别浦萦回，津堠岑寂。斜阳冉冉春无极”。从词开头的“柳阴直”看来，启程在中午，而这时已到傍晚。“渐”字也表明已经过了一段时间，不是刚刚分别时的情形了。这时望中之人早已不见，所见只有沿途风光。大水有小口旁通叫浦，别浦也就是水流分支的地方，那里水波回旋。因为已是傍晚，所以渡口冷冷清清的，只有守望所孤零零地立在那里。景物与词人的心情正相吻合。再加上斜阳冉冉西下，春色一望无边，空阔的背景越发衬出自身的孤单。他不禁又想起往事：“念月榭携手，露桥闻笛。沉思前事，似梦里，泪暗滴。”月榭之中，露桥之上，度过的那些夜晚，都留下了难忘的印象，宛如梦境似的，一一浮现在眼前。想到这里，不知不觉滴下了泪水。“暗滴”是背着人独自滴泪，自己的心事和感情无法使旁人理解，也不愿让旁人知道，只好暗息悲伤。\n\n　　统观全词，萦回曲折，似浅实深，有吐不尽的心事流荡其中。无论景语、情语，都很耐人寻味。', poem_tags = '宋词三百首,宋词精选,婉约,柳树,送别' WHERE poem_title = '兰陵王·柳' AND poem_author = '周邦彦';
UPDATE edu_poem SET poem_translation = '秋天离别时两相顾盼，像飞蓬一样到处飘荡。没有去求仙，真愧对西晋那位炼丹的葛洪。每天痛快地饮酒狂歌白白消磨日子。像您这样意气豪迈的人，如此逞雄究竟是为了谁？', poem_notes = '飘蓬：常用来比喻人的行踪飘忽不定。\n未就：没有成功。丹砂：即朱砂。道教认为炼砂成药，服之可以延年益寿。飞扬跋扈：不守常规，狂放不羁。此处作褒义词用。', poem_appreciation = '杜甫作七绝《赠李白》的当年秋天，李白也写下了《鲁郡东石门送杜二甫》诗。诗云：“飞蓬各自远，且尽手中杯。”从中流露出诗人依依惜别的深情。这与杜诗中的“秋来相顾尚飘蓬”句，可以参照。李白被赐金放还，与杜甫幸会于山东之时，由于有相同的坎坷遭遇，因而情志相投。\n\n　　此诗表面看来，似乎杜甫在规劝李白：要像道家葛洪那样潜心于炼丹求仙，不要痛饮狂歌、虚度时日，何必飞扬跋扈、人前称雄。实际上，杜诗有言外之意：李白藐视权贵，拂袖而去，沦落飘泊，虽尽日痛饮狂歌，然终不为统治者赏识；虽心雄万夫，而难以称雄，虽有济世之才，然不能施展。杜甫在赞叹之余，感慨万千，扼腕之情，油然而生。遂将自己的愤懑之情，诉之笔端，乃至于运用反诘的语气，发出似在埋怨、实则不平的询问。他的感慨既是为李白而发，也是为自己而发的。\n\n　　此诗突现了一个狂字，显示出一个傲字。傲骨嶙峋，狂荡不羁，这就是杜甫对于李白的写照。在这首《赠李白》中，正突现出狂与傲的风采、骨力、气度，显示出李白安能摧眉折腰事权贵的精神，这正是此诗的诗眼和精髓。它不仅同杜甫歌咏李白的其他诗篇是一脉相承的，而且也形象地揭示了李白的性格和气质特征。\n\n　　这首七绝，沉郁有致，抑扬顿挫，跌宕起伏。末句用反诘口吻，把全诗推向了最高潮。清初钱谦益在评注此诗时，独注“飞扬跋扈”句，其余一概略而不论，可谓独具慧眼，也表明它在全诗中的重要价值：“按太白性倜傥，好纵横术。少任侠，手刃数人，故公以飞扬跋扈目之。犹云平生飞动意也。旧注俱大谬。”（《钱注杜诗》卷九）是说从新的角度和侧面颂扬了李白的豪侠精神，并突出“飞扬跋扈”的飞动性。仇兆鳌注云：“飞扬，浮动之貌。跋扈，强梁之意。考《说文》：扈，尾也。跋扈，犹大鱼之跳跋其尾也。”（《杜诗详注》卷之一）此虽就字注字，就词注词，但在《赠李白》中，却是用来象征李白豪放不羁的精神。\n\n　　此诗言简意赅，韵味无穷。为了强化全诗流转的节奏、气势，则以“痛饮”对“狂歌”，“飞扬”对“跋扈”；且“痛饮狂歌”与“飞扬跋扈”，“空度日”与“为谁雄”又两两相对。这就形成了一个飞动的氛围，进一步突现了李白的傲岸与狂放。', poem_tags = '离别,写人,生活' WHERE poem_title = '赠李白' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '庭院前落尽了梧桐的叶子，水中的荷花也早失去当日的风姿。\n仿佛是通晓诗人我的心思。\n一片经霜的红叶离开树枝，飞近身来让我题诗。', poem_notes = '芙蓉：指荷花。\n辞柯：离开枝干。\n题红：在红叶上题诗。唐僖宗时，有一名宫女在红叶上写了一首诗：“流水何太急，深宫尽日闲。愍憨谢红叶，好去到人间。”树叶顺着御沟水流出宫墙。书生于祐拾到后添写道：“曾闻叶上题红怨，叶上题诗寄阿谁？”置于流水上游又流入宫中。后两人终成良缘。', poem_appreciation = '起首两句的对仗，概括了诗人在园林中所望见的秋景。“庭前”和“水边”是两处代表性的地点，暗示出诗人在四处徘徊，也在百般寻觅。但秋天对于诗人实在是太无情了，这两句中的“尽”和“彻”就不留一点余地。这两个字也正是景句之眼。既然是“落尽梧桐”，诗人的判断显然是基于未尽之时绿叶繁茂的秋前情形；同样，“开彻芙蓉”，首先浮现在他脑海中的也必然是旧时荷花盛开的热闹景象。枝上萧索，水面凋敝，这现实与记忆之间的巨大反差，自然会勾惹起悲秋的心情。可明明是作者因红衰翠减而伤感，第三句却偏偏说成是红翠善解人意，因迎合人的心绪而自甘衰残。诗人的这种自我怨艾，一来反衬出心中无可奈何的悲感的沉重，二来也表现了他对园林中美好事物的一往情深。\n\n　　正因为诗人将所见的秋景与自己系结在一起，才会有四、五两句的神来之笔，而在心情上发生一个完全的转折。\n\n　　我们在秋天常会遇到这样的情形：秋风卷着落叶扑面飞来，碰到身上有时就像粘住似的，好一会儿才飘落地面。诗人此时，就有一片“辞柯霜叶”缠上了他。何以见得？因为在上文的气氛中，飞舞在空中的霜叶只会加深“落尽”的印象，唯有停落在身上的片时的流连，才有可能启发诗人新的思考。霜叶“辞柯”而依人，这本身就沟通了“意同”的两者间的联系。“辞柯霜叶，飞来就我题红”，在多情善感的诗人眼中，其“飞来”完全是主动的、有目的的及含情脉脉的行为；而“题红”在其“红叶题诗”典故的原始意义上，则饱含着真、善、美的生活激情。秋天固然有萧瑟的一面，但对热爱生活的诗人来说，却同时意味着希望和奋起。这一“辞”一“就”，尽翻前案，将初时悲秋消沉的气氛一扫而空，无异化衰朽为神奇。小令别出机杼的结尾，令人拍案叫绝。', poem_tags = '秋天,写景,悲秋' WHERE poem_title = '天净沙·秋' AND poem_author = '朱庭玉';
UPDATE edu_poem SET poem_translation = '溪水无情却似对我脉脉有情，进山三天得以有它伴我同行。\n登山岭头就是我俩分手之处，潺湲流淌与我惜别一夜有声。', poem_notes = '分水岭：一般指两个流域分界的山。这里是指今陕西省略阳县东南的嶓冢山，它是汉水和嘉陵江的分水岭。\n岭头：山头。分头：分别；分手。《文苑英华》作“分流”。\n潺湲（chán yuán）：河水缓缓流动的样子。这里是指溪水流动的声音。', poem_appreciation = '化无情之物为有情，往往是使平凡事物富于诗意美的一种艺术手段。温庭筠这首短诗，很能说明这一点。\n\n　　诗中所写的分水岭，是秦蜀或秦梁间往来必经之地，在唐代是著名的交通要道，故一般径称分水岭而不必冠以所在地。题称“过分水岭”，实际上写的是在过分水岭的行程中与溪水的一段因缘，以及由此引起的诗意感受。\n\n　　首句就从溪水写起。溪水是没有感情的自然物，但眼前这条溪水，却又似乎有情。在这里，“无情”是用来引出“有情”、突出“有情”的。“有情”二字，是一篇眼目，下面三句都是围绕着它来具体描写的。“似”字用得恰到好处，它暗透出这只是诗人时或浮现的一种主观感觉。换成“却”字，便觉过于强调、坐实，可是能够肯定并强调溪水的有情，赋予溪水一种动人的人情美；改成“亦”字，又不免掩盖主次，使“无情”与“有情”平分秋色。只有这个“似”字，语意灵动轻妙，且与全诗平淡中见深情的风格相统一。这一句在点出“有情”的同时，也就设置了悬念，具有引导读者去注意下面的解答的效果。\n\n　　次句叙事，暗点感到溪水“似有情”的原因。嶓冢山是汉水与嘉陵江的分水岭，因为山深，所以“入山三日”方能到达岭头。山路蜿蜒曲折，缘溪而行，故而行旅者感到这溪水一直在自己侧畔同行。其实，入山是向上行，而水流总是向下，溪流的方向和行人的方向并不相同，但溪水虽不断向相反方向流逝，而其潺湲声却一路伴随。因为深山空寂无人，旅途孤孑无伴，这一路和旅人相伴的溪水便变得特别亲切，仿佛是有意不离左右，以它的清澈面影、流动身姿和清脆声韵来慰藉旅人的寂寞。“得同行”的“得”字，充分显示了诗人在寂寞旅途中邂逅良伴的欣喜；而感于溪水的“有情”，也可以从“得”字中见出。\n\n　　“岭头便是分头处，惜别潺湲一夜声。”在“入山三日”，相伴相依的旅程中，“溪水有情”之感不免与日俱增，因此当登上岭头，就要和溪水分头而行的时候，心中便不由自主地涌起依依惜别之情。但却不从自己方面来写，而是从溪水方面来写，以它的“惜别”进一步写它的“有情”。岭头处是旅途中的一个站头，诗人这一晚就在岭头住宿。在寂静的深山之夜，耳畔只听到岭头流水，仍是潺湲作响，彻夜不停，仿佛是在和自己这个同行三日的友伴殷勤话别。这“潺湲一夜声”五字，暗补“三日同行”时日夕所闻。溪声仍是此声，而当将别之际，却极其自然地感觉这溪水的“潺湲一夜声”如同是它的深情的惜别之声。在这里，诗人巧妙地利用了分水岭的自然特点，由“岭头”引出旅人与溪水的“分头”，又由“分头”引出“惜别”，因惜别而如此体会溪声。联想的丰富曲折和表达的自然平易，达到了和谐的统一。写到这里，溪水的“有情”已经臻于极致，诗人对溪水的深情也自在不言中了。\n\n　　分水岭下的流水，潺湲流淌，千古如斯。由于温庭筠对羁旅行役生活深有体验，对朋友间的情谊分外珍重，他才能发现溪水这样的伴侣，并赋予它一种动人的人情美。与其说是客观事物的诗意美触发了诗人的感情，不如说是诗人把自己美好的感情移注到了客观事物身上。', poem_tags = '写水,抒情' WHERE poem_title = '过分水岭' AND poem_author = '温庭筠';
UPDATE edu_poem SET poem_translation = '初夏四月，天气清明和暖，下过一场雨天刚放晴，雨后的山色更加青翠怡人，正对门的南山变得更加明净了。\n眼前没有随风飘扬的柳絮，只有葵花朝向着太阳开放。', poem_notes = '客中：旅居他乡作客。\n清和：天气清明而和暖。\n南山当户：正对门的南山。\n惟有：仅有，只有。', poem_appreciation = '首联，描述了四月初夏天和暖的天气，恰又是雨过天晴的时候。通过描浅白的语言，在春尽夏初之际，一幅雨后乍晴清明和暖的秀丽画面跃入读者的视野。\n\n　　颔联，描述了下过雨后，正对门的南山变得更加明净，青翠怡人了。诗人调动读者熟悉的景物布置了一个清明和暖的气氛，使整首诗充满了雨和夏的味道。\n\n　　颈联，通过描述眼前没有随风飘荡的柳絮这一情景。这句是有寄托的，寄托出诗人不是因风起舞的柳絮，意即决不在政治上投机取巧，随便附和。\n\n　　尾联，指出了向日葵向着太阳开放这一景象，也是有寄托的。看看那些像柳絮般随风转舵的小人，唯有那向阳怒放的葵花才值得尊敬。\n\n　　整首诗描述了变化的画面，诗人不喜雨丝蒙蒙的南山，也不赞随风飞舞的柳絮，而把独钟给了葵花，不难发现诗人非独爱葵花，而是言在此而意在彼。诗人久在官场，自是看够了人云亦云的柳絮，不愿诗人本人“摧眉折腰“随风飘摆，终而选择了葵花，且懂得珍惜阳光，这也许才是葵花的可爱之处。诗人托物言志，意即对皇帝忠贞不贰，会永远像葵一样忠心于国家。', poem_tags = '夏天,写景,咏物,写花,言志' WHERE poem_title = '客中初夏' AND poem_author = '司马光';
UPDATE edu_poem SET poem_tags = '春天,写景,抒情,时间' WHERE poem_title = '浣溪沙·雪颔霜髯不自惊' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '注释 百年：指人寿百岁。 强半：大半；过半。 须：必得，应当。 催：使事物的产生、发展变化加快。 无：没有，与“有”相对；不。', poem_tags = '母亲,惜时' WHERE poem_title = '短歌行' AND poem_author = '王建';
UPDATE edu_poem SET poem_translation = '金陵城曾在日暮的景色伴着浮动的云，也在秋声里陪着落日。\n这世上有无数的丹青圣手，可都画不出内心的伤感。', poem_notes = '金陵：今南京。\n晚翠：日暮时苍翠的景色。\n秋声：秋天自然界的声音，如鸟虫叫声，风声。欧阳修有《秋声赋》，以各种比喻描摹秋天的声响。\n丹青手：画师，画工。丹青，图画。', poem_tags = '秋天,感伤,爱国' WHERE poem_title = '金陵晚望' AND poem_author = '高蟾';
UPDATE edu_poem SET poem_appreciation = '这首词初看起来，是一首伤春念远的词。上阕写春光烂漫，又作转折，说春色如此美妙，却无人欣赏。下阕开头既已点明全词的“念远”主旨，接下通过回忆，写昔日邂逅的情境与别后的“幽怨”，后又回到眼前，烟月迷离，子规声咽，一片凄清景致，更增几多离愁。陈亮乃南宋气节之士，其创作绝少儿女情长。故有人认为此作寄托了恢复之志。　\n\n　　起首用“闹”字烘托花的精神情态，同时总揽春的景象，与宋祁《玉楼春》“红杏枝头春意闹”句相比，毫不逊色，加上东风软（和煦），更烘托出春光明媚，春色宜人。翠陌，翠绿的田野；平莎茸嫩，平铺的嫩草，用茸嫩形容初春的草，贴切恰当；垂杨金浅，浅黄色的垂柳。迟日催花，春日渐长，催动百花竞放；淡云阁雨，云层淡薄，促使微雨暂收；轻寒轻暖，不寒不暖，气候最佳。这些都是春归大地后带来的春景、春色。荟萃如此多样的美好景色，本可引人入胜，使人目不暇接而留连忘返。可是歇拍四句却指出：在今朝，游人未曾赏玩这芳菲世界，只能被啼莺语燕所赏玩。莺燕是“能赏而不知者”（《草堂诗余正集》沈际飞语），游人则为“欲赏而不得者”（同上）。\n\n　　鉴于人情世故都是这样，尚有何心踏青拾翠！过片两句，因寂寞而凭高念远，向南楼问一声归雁。从上片看，姹紫嫣红，百花竞放，世界是一片喧闹的，可是这样喧闹的芳菲世界而懒得去游赏，足见主人公的处境是孤立无助的，心情是压抑的。雁足能传书信（见《汉书·苏武传》），于是鸿雁充当了信使，因为征人未回，向南楼探问归雁消息。金钗三句，谓昔年赏心乐事，而此时已如风消云散。金钗斗草，拔金钗作斗草游戏。宗懔《荆楚岁时记》：“竞采百药，谓百草以蠲除毒气，故世有斗草之戏。”青丝勒马，用青丝绳做马络头。古乐府《陌上桑》：“青丝系马尾，黄金络马头。”罗绶三句，谓难忘别时的恋情，难禁别后的粉泪，难遣别久的幽怨。罗绶分香，临别以香罗带贻赠留念。秦观《满庭芳》“罗带轻分”，亦此意。翠绡封泪，翠巾裹着眼泪寄与对方，典出《丽情集》记灼灼事。几多幽怨，数不清的牢愁暗恨。正销魂三句，有两种断法，一断在“魂”字后，另一断在“又是”后，两者都可，而后者较恰当。因为一结要突出“又是”之意，用“又是”领下面两句，由于又看到了与昔年离别之时一般的疏烟淡月、子规声断，触发她的愁绪而黯然销魂。子规，一名杜鹃，相传古代蜀君望帝之魂所化。（《华阳国志·蜀志》）子规鸣声凄厉，最容易勾动人们别恨乡愁。　\n\n　　这首词上片，作者几乎倾全力烘托春景的无比美好，而歇拍三句，却来一个大转折，指出人们以不能游赏美好的春景为憾事，以如此芳菲世界被莺燕所占有为惋惜，才领会前面之所以倾全力描绘春景者，是为了给后面的春恨增添气势。盖春景愈美好，愈令人惆怅，添人愁绪，也就是春恨愈加强烈。杜甫所谓“花近高楼伤客心”（《登楼》），“感时花溅泪”（《春望》），即为此种思想感情的反映。下片似另出机杼，独立成篇，其实不然，它是全词的一个有机组成部分，上下片有岭断云连之妙。上片因春景美好反而引起春恨，这是客观景物与内心世界的矛盾，而所以铸成此种矛盾的，伤离念远是一个主要因素，下片就是抒写离愁别恨的，因而实与上片契合无间。从赏心乐事的一去不返，别后别久的十分怀念，别时景色的触目销魂，都在刻画主人公的感情深挚。可是作者是一位“推倒一世之智勇，开拓万古之心胸”（黄宗羲《宋元学案·龙川学案》）的铁铮铮汉子，他写作态度严谨，目的性明确，每一首词写成后，“辄自叹曰，平生经济之怀略已陈矣”（叶适引陈亮语）。所以很难想象他会写出脂粉气息浓郁的艳词。据此，才知下片的闺怨是假托的，使用这类表现手法在诗词中并不鲜见，大率以柔婉的笔调，抒愤激或怨悱的感情。此种愤激之情是作者平素郁积的，而且与反偏安、复故土的抗金思想相表里，芳菲世界都付莺燕，实际的意思则是大好河山尽沦于敌手。为此，清季词论家刘熙载评这几句词：“言近旨远，直有宗留守（宗泽）大呼渡河之意。”（《艺概》）以小词比壮语，不觉突兀，是因其精神贴近之故。\n\n　　陈亮传世的词七十多首，风格大致是豪放的，所以明代毛晋说：“《龙川词》一卷，读至卷终，不作一妖语、媚语，殆所称不受人怜者欤！”（《龙川词跋》）后来他看到此篇及其他六首婉丽之词，修正自己的论点，曰：“偶阅《中兴词选》，得《水龙吟》以后七阕，亦未能超然。”（《龙川词补跋》）其实毛晋本来的论点还是对的，无须修正。作家的作品，风格、境界可以多样。陈亮词的基调是豪放的，但也出现一些婉约的作品，毫不足怪。苏轼《水龙吟·和章质夫杨花》、辛弃疾《摸鱼儿·暮春》，情调岂不缠绵凄婉，但毕竟与周（邦彦）、秦（观）不同，苏、辛和陈亮的词，和婉中仍含刚劲之气，所谓骨子里还是刚的，关于这一点，明眼人一眼就能看的出。', poem_tags = '宋词三百首,婉约,伤春,怀远' WHERE poem_title = '水龙吟·春恨' AND poem_author = '陈亮';
UPDATE edu_poem SET poem_translation = '一只离群孤雁，不想饮水，不肯进食，只是低飞哀叫，思念追寻它的同伴。\n雁群消失在云海之间，谁来怜惜着天际孤雁?\n放眼望尽天涯，好像看到同伴身影；哀鸣响震山谷，好像听到同伴的声音。\n野鸦不解孤雁心情，只顾自己鸣噪不停。', poem_notes = '①饮啄：鸟类饮水啄食。\n②万重云：指天高路远，云海弥漫。\n③望尽：望尽天际。\n④意绪：心绪，念头。\n⑤鸣噪：野鸦啼叫。自：自己。一作“亦”。', poem_appreciation = '首联“孤雁不饮啄，飞鸣声念群”唤出“孤雁”，“不饮啄”。写得孤雁有品骨。孤雁非常想念它的同伴。不单是想念，而且还拼命追寻，是一只情感热烈而执着的“孤雁”。“不饮啄”体现出孤雁的执着，不达目的绝不放弃的决心。寄寓诗人当时渴望与亲人朋友团聚的心情。\n\n　　颔联“谁怜一片影，相失万重云？”境界忽然开阔。高远浩茫的天空中，这小小的孤雁仅是“一片影”，它与雁群相失在“万重云”间，此时此际显得惶急、焦虑和迷茫。“一片”、“万重”对比，构成极大的反差，极言其“孤”。“谁怜”二字直抒胸臆，凝聚了诗人对孤雁的怜悯之情。形象地写出了路远雁孤、同伴难寻的凄苦之情。这一联以“谁怜”二字设问诗人与雁，“物我交融”，浑然一体了。诗人所思念的不单是兄弟，还包括他的亲密的朋友。经历了安史之乱，在那动荡不安的年月里，诗人流落他乡，亲朋离散，天各一方，可他无时不渴望骨肉团聚，无日不梦想知友重逢，这孤零零的雁儿，寄寓了诗人自己的影子。\n\n　　颈联“望尽似犹见，哀多如更闻。”联紧承上联，从心理方面刻画孤雁的鲜明个性。“似”、“如”二字表现了未见而似见，未闻而犹闻的幻觉。颈联通过对孤雁飞着叫着寻找同伴的描写，将孤雁的渴望、煎熬表现得淋漓尽致。它被思念缠绕着，被痛苦煎熬着，迫使它不停地飞鸣。它望尽天际，不停地望，仿佛那失去的雁群老在它眼前晃。它哀唤声声，不停地唤，似乎那侣伴的鸣声老在它耳畔响。所以，它更要不停地追飞，不停地呼唤了。这两句血泪文字，情深意切，哀痛欲绝。从中体现出诗人流离失所，生活困苦，又没有亲人和朋友可以依靠的状态。“犹”和“更”道出了诗人心中的沉重的悲哀与伤痛。\n\n　　尾联“野鸦无意绪，鸣噪自纷纷。”用了陪衬的笔法，表达了诗人的爱憎感情。用野鸦的无忧无虑、热闹非常来反衬孤雁的寂寞、愁苦，尾联进一步表现了孤雁渴望团聚的哀愁与奋力寻找的坚持不懈。孤雁念群之情那么迫切，它那么痛苦、劳累；而野鸦们是全然不懂的，它们纷纷然鸣噪不停，自得其乐。“无意绪”是孤雁对着野鸦时的心情，也是杜甫既不能与知己亲朋相见，却面对着一些俗客庸夫时厌恶无聊的心绪。\n\n　　这是一篇念群之雁的赞歌，它表现的情感是浓挚的，悲中有壮的。孤雁那样孤单、困苦，同时却还要不断地呼号、追求，它那念友之情在胸中炽烈地燃烧，它甚至连吃喝都可抛弃，更不顾处境的安危；虽然命薄但是心高，宁愿飞翔在万重云里，未曾留意暮雨寒塘，诗情激切高昂，思想境界很高。就艺术技巧而论，全篇咏物传神，是大匠运斤，自然浑成，全无斧凿之痕。中间两联有情有景，一气呵成，而且景中有声有色，甚至还有光和影，能给读者以“立体感”。\n\n　　全诗以孤雁象征自己。诗写的是孤雁，无一字涉及诗人自己。但通过这只不饮不啄、穿飞哀鸣、思寻伙伴的失群的孤雁间接暗示了诗人在战乱中只身颠沛流离、怀念亲朋的情怀。', poem_tags = '咏物,写鸟,孤独,哀伤' WHERE poem_title = '孤雁 / 后飞雁' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '竹丛里船坞深静无尘，临水的亭榭分外幽清。相思之情啊飞向远方，可却隔着重重的高城。\n秋空上阴云连日不散，霜飞的时节也来迟了。留得满地枯残的荷叶，好听深夜萧瑟的雨声。', poem_notes = '崔雍、崔衮：崔戎的儿子，李商隐的从表兄弟。\n竹坞（wù）：丛竹掩映的池边高地。水槛（jiàn）：指临水有栏杆的亭榭。此指骆氏亭。\n迢递：遥远的样子。重城：一道道城关。\n秋阴不散霜飞晚：秋日阴云连日不散，霜期来得晚。\n枯荷听雨声：雨滴枯荷，大约只有彻夜辗转难眠的人才能听到。', poem_appreciation = '此诗首句写骆氏亭，翠竹、清水把这座亭轩映衬得格外清幽雅洁，诗人置身其间，颇有远离尘嚣之感。\n\n　　接着写诗人对友人的思念，诗人眼下所宿的骆氏亭和崔氏兄弟所在的长安，中间隔着重重的城池，路途迢迢，诗人的思念之情宛如随风飘荡的游丝，悠悠然飘向友人所在的长安。诗人因境界的清幽而倍感孤寂，因无好友共赏幽胜而微感惆怅。\n\n　　“秋阴不散霜飞晚”，又回到眼前景物，渲染气氛，烘托情绪。时令已届深秋，但连日天气阴霾，孕育着雨意，所以霜也下得晚了。天色一片迷蒙，本来就因相思而耿耿不寐的诗人，心情不免更加黯淡，而这种心情又反过来更增加了相思的程度。\n\n　　诗人是在旅途中暂宿骆氏亭，此地近一段时期的天气，包括霜期之晚，自然是出之揣测，这揣测的根据就是“秋阴不散”与“留得枯荷”。这句一方面是为末句作铺垫（由于“秋阴不散”故有“雨”；由于“霜飞晚”故“留得残荷”），另一方面又兼有渲染气氛、烘托情绪的作用。\n\n　　末句是全篇的点睛之笔，写诗人聆听雨打枯荷的声音和诗人的心情变化过程。诗人原来是一直在那里思念着远隔重城的朋友的，由于神驰天外竟没有留意天气的变化。不知不觉间，下起了淅沥的小雨，雨点点点滴滴地洒落在枯荷上，发出一阵错落有致的声响。诗人这才意外地发现，这萧瑟的秋雨敲打残荷的声韵竟别有一种美的情趣。枯荷给人一种残败衰飒之感，本无可“留”的价值；但自己这样一个旅宿思友整夜不眠的人，却因聆听枯荷秋雨的清韵而略慰相思，稍解寂寞，所以反而深幸枯荷之“留”了。“留”蕴涵有一种不期而遇的喜悦。而诗人“听”到的，也不止是那凄楚的雨声。枯荷秋雨的清韵，常人难解其中滋味。这单调而凄清的声音却又更增加了环境的寂寥，从而更加深了对朋友的思念。\n\n　　沈义父《乐府指迷》云：“结句须要放开，含有余不尽之意，以景结情最好。”此诗之结语：“秋阴不散霜飞晚，留得枯荷听雨声。”正是以景结情，不仅景中含情，且有声有情、声情并茂，声、景、情谐和合一而收余音缭绕之致，使诗歌境象迷茫，旨义含隐深曲。\n\n　　这首诗虽然写了秋亭夜雨的景色，写得历历如画，但它并不是一首写景诗，而是一首抒情诗。“宿骆氏亭”所见所闻是“寄怀”的凭借，“相思”二字微露端倪，后两句暗藏彻夜不眠之意，诗人的思友之情暗寓其中，可以说是以景寄情、寓情于景的。诗的意境清秀疏朗，而蕴涵其中的心境又是极为深远的。', poem_tags = '写景,写雨,怀人' WHERE poem_title = '宿骆氏亭寄怀崔雍崔衮' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '傍晚从终南山上走下来，山月好像随着行人而归。\n回望来时走的山间小路，山林苍苍茫茫一片青翠。\n遇斛斯山人相携到他家，孩童出来急忙打开柴门。\n走进竹林穿过幽静小路，青萝枝叶拂着行人衣裳。\n欢言笑谈得到放松休息，畅饮美酒宾主频频举杯。\n放声高歌风入松的曲调，歌罢银河星星已经很稀。\n我喝醉酒主人非常高兴，欢乐忘了世俗奸诈心机。', poem_notes = '终南山：即秦岭，在今西安市南，唐时士子多隐居于此山。过：拜访。斛（hú）斯山人：复姓斛斯的一位隐士。\n碧山：指终南山。下：下山。\n却顾：回头望。所来径：下山的小路。\n苍苍：一说是指灰白色，但这里不宜作此解，而应解释苍为苍翠、苍茫，苍苍叠用是强调群山在暮色中的那种苍茫貌。翠微：青翠的山坡，此处指终南山。\n相携：下山时路遇斛斯山人，携手同去其家。及：到。田家：田野山村人家，此指斛斯山人家。\n荆扉：荆条编扎的柴门。\n青萝：攀缠在树枝上下垂的藤蔓。行衣：行人的衣服。\n挥：举杯。\n松风：古乐府琴曲名，即《风入松曲》，此处也有歌声随风而入松林的意思。\n河星稀：银河中的星光稀微，意谓夜已深了。河星：一作“星河”。\n陶然：欢乐的样子。忘机：忘记世俗的机心，不谋虚名蝇利。机：世俗的心机。', poem_appreciation = '中国的田园诗以晋末陶潜为开山祖，他的诗，对后代影响很大。李白这首田园诗，似也有陶诗那种描写琐事人情，平淡爽直的风格。\n\n　　全诗以赋体——叙述题写成。诗以“暮”开首，为“宿”开拓。相携欢言，置酒共挥，长歌风松，赏心乐事，自然陶醉忘机。这些都是作者真情实感的流溢。\n\n　　此诗以田家、饮酒为题材，很受陶潜田园诗的影响。然陶诗显得平淡恬静，既不首意染色，口气也极和缓。如“暧暧远人村，依依墟里烟”、“采菊东篱下，悠然见南山”等等。而李诗却着意渲染。细吟“绿竹入幽径，青萝拂行衣。欢言得所憩，美酒聊共挥”，就会觉得色彩鲜明，神情飞扬。可见陶李两者风格迥异。\n\n　　从诗的内容看，诗人是在月夜到长安南面的终南山去造访一位姓斛斯的隐士。首句“暮从碧山下”，“暮”字挑起了第二句的“山月”和第四句的“苍苍”，“下”字挑起了第二句的“随人归”和第三句的“却顾”，“碧”字又逗出第四句的“翠微”。平平常常五个字，却无一字虚设。“山月随人归”，把月写得如此脉脉有情。月尚如此，人则可知。第三句“却顾所来径”，写出诗人对终南山的余情。这里虽未正面写山林暮景，却是情中有景。正是旖旎山色，使诗人迷恋不已。第四句又是正面描写。“翠微”指青翠掩映的山林幽深处。“苍苍”两字起加倍渲染的作用。“横”有笼罩意。此句描绘出暮色苍苍中的山林美景。这四句，用笔简炼而神色俱佳。诗人漫步山径，大概遇到了斛斯山人，于是“相携及田家”，“相携”，显出情谊的密切。“童稚开荆扉”，连孩子们也开柴门来迎客了。进门后，“绿竹入幽径，青萝拂行衣”，写出了田家庭园的恬静，流露出诗人的称羡之情。“欢言得所憩，美酒聊共挥”，“得所憩”不仅是赞美山人的庭园居室，也为遇知己而高兴。因而欢言笑谈，美酒共挥。一个“挥”字写出了李白畅怀豪饮的神情。酒醉情浓，放声长歌，直唱到天河群星疏落，籁寂更深。“长歌吟松风，曲尽河星稀”句中青松与青天，仍处处绾带上文的一片苍翠。至于河星既稀，月色自淡，这就不在话下了。最后，从美酒共挥，转到“我醉君复乐，陶然共忘机”，写出酒后的风味，陶陶然把人世的机巧之心，一扫而空，显得淡泊而恬远。\n\n　　这首诗以田家、饮酒为题材，是受陶潜诗的影响，然而两者诗风又有不同之处。陶潜的写景，虽未曾无情，却显得平淡恬静，如“暧暧远人村，依依墟里烟”、“道狭草木长，夕露沾我衣”、“采菊东篱下，悠然见南山”、“微雨从东来，好风与之俱”之类，既不染色，而口气又那么温缓舒徐。而李白就着意渲染，“却顾所来径，苍苍横翠微”、“绿竹入幽径，青萝拂行衣。欢言得所憩，美酒聊共挥”，不仅色彩鲜明，而且神情飞扬，口气中也带有清俊之味。在李白的一些饮酒诗中，豪情狂气喷薄涌泄，溢于纸上，而此诗似已大为掩抑收敛了。“长歌吟松风，曲尽河星稀。我醉君复乐，陶然共忘机。”可是一比起陶诗，意味还是有差别的。陶潜的“或有数斗酒，闲饮自欢然”、“过门辄相呼，有酒斟酌之”、“何以称我情，浊酒且自陶”、“一觞虽自进，杯尽壶自倾”之类，称心而出，信口而道，淡淡然无可无不可的那种意味，就使人觉得李白挥酒长歌仍有一股英气，与陶潜异趣。因而，从李白此诗既可以看到陶诗的影响，又可以看到两位诗人风格的不同。', poem_tags = '唐诗三百首,田园,饮酒,写景' WHERE poem_title = '下终南山过斛斯山人宿置酒' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '白鸥栖落水滨，默然地望着我，好似在问：夜泊溪畔是被风雪所阻，不得以停泊；还是无所去处，情愿留下？如若是自愿，又为了何事眉头紧锁？夜风袭来，掀起舱帘，吹得舱内灯火闪烁。孤处江舟，只有身影为伴，对着孤影，不禁怀念起与旧友欢聚和悠游的情景。\n昔日一同悠游的旧友，今日在哪里？回想当时，楼外一片盎然春色，相携漫步锦簇的花丛中。湖中绿波荡漾，系舟在堤边的柳树下。梦啊，梦啊，让我在梦中重温一下旧游。可是在梦中却难寻旧游，只有眼前的寒水空自流。舱外飞雪漫天，凝望浓密的阴云，任凭飞雪落在身上，浸透了棉衣。都说没有人的忧愁，有我这般深沉，今夜，雪中的梅花，一身素白，忧愁似我。\n这首词在清冷的画面中，将深深的忧愁与热烈的回忆交织在一起，如随想曲一样自由潇洒。', poem_notes = '身留：被雪所阻，被迫不能动身而羁留下来。\n心留：自己心里情愿留下。\n旧游：指昔日漫游的伴友与游时的情景。\n漠漠：浓密。\n黄云：指昏黄的天色。高适曾有诗“千里黄云白日曛，北风吹雁雪纷纷。”\n木棉裘：棉衣。', poem_tags = '孤独,怀念,友人' WHERE poem_title = '梅花引·荆溪阻雪' AND poem_author = '蒋捷';
UPDATE edu_poem SET poem_translation = '燕国太子喜欢收养门客，目的是对秦国报仇雪恨。 \n他到处招集有本领的人，这一年年底募得了荆卿。 \n君子重义气为知己而死，荆轲仗剑就要辞别燕京。 \n白色骏马在大路上鸣叫，众人意气激昂为他送行。 \n个个同仇敌忾怒发冲冠，勇猛之气似要冲断帽缨。 \n易水边摆下盛大的别宴，在座的都是人中的精英。 \n渐离击筑筑声慷慨悲壮，宋意唱歌歌声响遏行云。 \n座席中吹过萧萧的哀风，水面上漾起淡淡的波纹。 \n唱到商音听者无不流泪，奏到羽音荆轲格外惊心。 \n他明知这一去不再回返，留下的姓名将万古长存。 \n登车而去何曾有所眷顾，飞车直驰那秦国的官廷。 \n勇往直前行程超过万里，曲折行进所经何止千城。 \n翻完地图忽地现出匕首，秦王一见不由胆颤心惊。 \n可惜呀！只可惜剑术欠佳，奇功伟绩终于未能完成。 \n荆轲其人虽然早已死去，他的精神永远激励后人。', poem_notes = '荆轲：战国时卫国人，为燕太子丹报仇，以送地图为名，藏匕首刺秦王，不成被杀。\n燕丹：战国时燕王喜的太子，名丹。\n强嬴：秦国。\n荆卿：指荆轲。\n渐离：高渐离，战国时燕国人，与荆轲友善，善击筑(古时的一种乐器）。\n宋意：燕国的勇士。\n商音、羽奏：商声和羽声。商声凄凉，羽声较激昂。', poem_appreciation = '关于荆轲之事，《战国策·燕策》与《史记·刺客列传》都有记载，其基本情节是相似的。陶渊明的这首诗显然是取材于上述史料，但并不是简单地用诗的形式复述这一历史故事。\n\n　　诗的头四句，从燕太子丹养士报秦(报，报复、报仇之意)，引出荆轲。不仅概括了荆轲入燕，燕丹谋于太傅鞫武，鞫武荐田光，田光荐荆轲，燕丹得识荆轲，奉为“上卿”等等经过，而且，一开始便将人物(荆轲)置于秦、燕矛盾之中，又因为这个人物是最出众、最雄俊的勇士(百夫良，超越百人的勇士)，于是乎他自然成了矛盾一方(燕)的希望之所托。那么，故事的背景，人物的位置，及其肩负之重任，大体都已亮出，所以说这四句是“已将后事全摄”。正因为如此，矛盾的发展，人物的命运等等悬念，也就同时紧紧地系在读者的心上。下面接着就写荆轲出燕，在临行前，史书中有荆轲等待与其同行的助手，而“太子迟之，疑其改悔”，引起荆轲怒叱太子，且在一怒之下，带着并不中用的秦舞阳同行的记载。诗人略去这一重要情节，而代之以“君子死知己，提剑出燕京”。这后一句逗出下文，而前一句显然是回护了燕丹的过失，但这样写却与首句的“善养士”相呼应。既使得内容和谐统一，一气贯注，也使得笔墨集中，结构浑成。易水饯行，《战国策》与《史记》是这么写的：“遂发，太子及宾客知其事者，皆白衣冠以送之……”，由平缓而渐趋激昂。诗人则不然，他首先插入：“素骥鸣广陌，慷慨送我行”。素骥，白马。马犹如此，人就自不待言了，诗的情绪一下子就激发起来了。因而“雄发”二句的刻画——头发直竖，指向高高的帽子；雄猛之气，冲动了系冠的丝绳——虽不无夸张，但却由于情真意足而显得极其自然。易水饯别，也正是在这种气氛中酝酿和展开的激昂悲壮的一幕。高渐离、宋意……一时燕国的豪杰，都列坐在饯席之上。寒水哀风，击筑高歌，声色俱现，情景相生，送者、行者，无不热血沸腾，慷慨流涕。“心知去不归，且有后世名”。又一笔折到行者，道出了行者的决心，写出了行者的气概，而这也就是这幕戏的意图与效果之所在。“登车”六句写荆轲义无反顾，飞车入秦。使上述的决死之心与一往无前的气概，从行动上再加以具体的表现。其中“凌厉”二句亦属诗人的想像，它好似一连串快速闪过的镜头，使人物迅逼秦廷，把情节推向高潮，扣人心弦。诗中以大量笔墨写出燕入秦，铺叙得排荡淋漓，而写到行刺失败的正面，却是惜墨如金，只用了两句话——“图穷事自至，豪主正怔营”。前一句洗练地交代了荆轲与燕丹在地图中藏着利刃以要劫、刺杀秦王的计谋，同时也宣布了高潮的到来，后一句只写秦王慌张惊恐，从对面突出荆轲的果敢与威慑，而对荆轲被秦王左右击杀等等，则只字不提，其倾向之鲜明，爱憎之强烈，自在不言之中。作者以有限的篇幅，再现了雄姿勃勃的荆轲形象，也表现了作者剪裁的功夫与创造的才能。诗的最后四句，便是直截的抒情和评述，诗人一面惋惜其“奇功”不成，一面肯定其精神犹在，在惋惜和赞叹之中，使这个勇于牺牲、不畏强暴的形象，获得了不灭的光辉、不朽的生命。可以看得出诗人是以饱蘸感情的笔触，写下了这个精采而又有分量的结尾。正如张玉谷说的：“既惜之，复慕之，结得抟捖有力，遂使通首皆振得起”(《古诗赏析》)。\n\n　　发思古之幽情，是为了现实。不过这“现实”亦不宜说得过窄过死(如一些论者所言，这首诗是诗人出于“忠晋报宋”而作)，为什么呢？首先，因为陶渊明反复地说过：“少时壮且厉，抚剑独行游。谁言行游近，张掖至幽州”(《拟古》之八)；“忆我少壮时，无乐自欣豫。猛志逸四海，骞翮思远翥”(《杂诗》之五)。这使我们看到在作者的生活、志趣和性格中，也早已具有着豪放、侠义的色彩。其次，诗人也曾出仕于晋，不过他说这是“误落尘网中，一去十三年”(《归田园居五首》)，悔恨之情溢于言表，足见“晋”也并不是他的理想王国，当然“宋”亦如此。这些都是我们不必将《咏荆轲》的作意胶柱于“忠晋报宋”的理由。诗人一生“猛志”不衰，疾恶除暴、舍身济世之心常在，诗中的荆轲也正是这种精神和理想的艺术折光。说得简单一点，便是借历史之旧事，抒自己之爱憎，这样看是比较接近诗人心迹的吧。是的，这首诗的影响也正在此，此亦有诗为证：“陶潜诗喜说荆轲，想见《停云》发浩歌。吟到恩仇心事涌，江湖侠骨恐无多。”(龚自珍《己亥杂诗》)　(赵其钧)', poem_tags = '古诗三百首,咏史怀古' WHERE poem_title = '咏荆轲' AND poem_author = '陶渊明';
UPDATE edu_poem SET poem_translation = '燕子飞翔天上，参差舒展翅膀。妹子今日远嫁，相送郊野路旁。瞻望不见人影，泪流纷如雨降。\n燕子飞翔天上，身姿忽下忽上。妹子今日远嫁，相送不嫌路长。瞻望不见人影，伫立满面泪淌。\n燕子飞翔天上，鸣音呢喃低昂。妹子今日远嫁，相送远去南方。瞻望不见人影，实在痛心悲伤。\n二妹诚信稳当，思虑切实深长。温和而又恭顺，为人谨慎善良。常常想着父王，叮咛响我耳旁。', poem_notes = '燕燕：即燕子。\n差（cī）池（chí）其羽：义同“参差”，形容燕子张舒其尾翼。\n瞻：往前看；弗：不能。\n颉（xié）：上飞。颃（háng）：下飞。\n将（jiāng）：送。\n伫：久立等待。\n仲：兄弟或姐妹中排行第二者。指二妹。任：信任。氏：姓氏。只：语助词。\n塞（sè）：诚实。渊：深厚。\n 终…且…：既…又… ；惠：和顺。\n淑：善良。慎：谨慎。\n先君：已故的国君。\n勖（xù）：勉励。寡人：寡德之人，国君对自己的谦称。', poem_appreciation = '《燕燕》全诗四章，前三章重章渲染惜别情境，后一章深情回忆被送者的美德。抒情深婉而语意沉痛，写人传神而敬意顿生。\n\n　　前三章开首以飞燕起兴：“燕燕于飞，差池其羽”，“颉之颃之”，“下上其音”。《朱子语类》赞曰：“譬如画工一般，直是写得他精神出。”阳春三月，群燕飞翔，蹁跹上下，呢喃鸣唱。然而，诗人用意不只是描绘一幅“春燕试飞图”。而是以燕燕双飞的自由欢畅，来反衬同胞别离的愁苦哀伤。此所谓“譬如画工”又“写出精神”。接着点明事由：“之子于归，远送于野。”父亲已去世，妹妹又要远嫁，同胞手足今日分离，此情此境，依依难别。“远于将之”、“远送于南”，相送一程又一程，更见离情别绪之黯然。然而，千里相送，总有一别。远嫁的妹妹终于遽然而去，深情的兄长仍依依难舍。这里诗歌运用艺术手法表现出感人的情境：“瞻望弗及，泣涕如雨”，“伫立以泣”、“实劳我心”。先是登高瞻望，虽车马不见，却行尘时起；后是瞻望弗及，唯伫立以泣，伤心思念。真是兄妹情深，依依惜别，缠绵悱恻，鬼神可泣。这三章重章复唱，既易辞申意，又循序渐进，且乐景与哀情相反衬；从而把送别情境和惜别气氛，表现得深婉沉痛，不忍卒读。\n\n　　四章由虚而实，转写被送者。原来二妹非同一般，她思虑切实而深长，性情温和而恭顺，为人谨慎又善良，正是自己治国安邦的好帮手。她执手临别，还不忘赠言勉励：莫忘先王的嘱托，成为百姓的好国君。这一章写人，体现了上古先民对女性美德的极高评价。在写法上，先概括描述，再写人物语言；静中有动，形象鲜活。而四章在全篇的结构上也有讲究，前三章虚笔渲染惜别气氛，后一章实笔刻画被送对象，采用了同《召南·采苹》相似的倒装之法。\n\n　　《燕燕》之后，“瞻望弗及”和“伫立以泣”成了表现惜别情境的原型意象，反复出现在历代送别诗中。“伫立以泣”的“泪”，成为别离主题赖以生发的艺术意象之一。', poem_tags = '诗经,送别,抒情' WHERE poem_title = '国风·邶风·燕燕' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '在长安回头远望骊山宛如一堆堆锦绣，山顶上华清宫千重门依次打开。\n一骑驰来烟尘滚滚妃子欢心一笑，无人知道是南方送了荔枝鲜果来。', poem_notes = '华清宫：《元和郡县志》：“华清宫在骊山上，开元十一年初置温泉宫。天宝六年改为华清宫。又造长生殿，名为集灵台，以祀神也。”\n绣成堆：骊山右侧有东绣岭，左侧有西绣岭。唐玄宗在岭上广种林木花卉，郁郁葱葱。\n千门：形容山顶宫殿壮丽，门户众多。次第：依次。\n红尘：这里指飞扬的尘土。妃子：指杨贵妃。乐史《杨太真外传》：上曰：“赏名花，对妃子，焉用旧乐词！”《新唐书·李贵妃传》：“妃嗜荔枝，必欲生致之，乃置骑传送，走数千里，味未变已至京师。”《唐国史补》：“杨贵妃生于蜀，好食荔枝，南海所生，尤胜蜀者，故每岁飞驰以进。然方暑而熟，经宿则败，后人皆不知之。”按：此诗或为写意之作，意在讽刺玄宗宠妃之事，不可一一求诸史实。在唐代，岭南荔枝无法运到长安一带，故自苏轼即言“此时荔枝自涪州致之，非岭南也”（《通鉴唐纪》注）。而荔枝成熟的季节，玄宗和贵妃必不在骊山。玄宗每年冬十月进驻华清宫，次年春即回长安。《程氏考古编》亦辨其谬，近人陈寅恪亦复考证之。\n知是：一作“知道”。', poem_appreciation = '此诗通过送荔枝这一典型事件，鞭挞了玄宗与杨贵妃骄奢淫逸的生活，有着以微见著的艺术效果，精妙绝伦，脍炙人口。\n\n　　起句描写华清宫所在地骊山的景色。诗人从长安“回望”的角度来写，犹如电影摄影师，在观众面前先展现一个广阔深远的骊山全景：林木葱茏，花草繁茂，宫殿楼阁耸立其间，宛如团团锦绣。“绣成堆”，既指骊山两旁的东绣岭、西绣岭，又是形容骊山的美不胜收，语意双关。\n\n　　接着，场景向前推进，展现出山顶上那座雄伟壮观的行宫。平日紧闭的宫门忽然一道接着一道缓缓地打开了。接下来，又是两个特写镜头：宫外，一名专使骑着驿马风驰电掣般疾奔而来，身后扬起一团团红尘；宫内，妃子嫣然而笑了。几个镜头貌似互不相关，却都包蕴着诗人精心安排的悬念：“千门”因何而开？“一骑”为何而来？“妃子”又因何而笑？诗人故意不忙说出，直至紧张而神秘的气氛憋得读者非想知道不可时，才含蓄委婉地揭示谜底：“无人知是荔枝来。”“荔枝”两字，透出事情的原委。《新唐书·杨贵妃传》：“妃嗜荔枝，必欲生致之，乃置骑传送，走数千里，味未变，已至京师。”明于此，那么前面的悬念顿然而释，那几个镜头便自然而然地联成一体了。\n\n　　吴乔《围炉诗话》说：“诗贵有含蓄不尽之意，尤以不著意见声色故事议论者为最上。”杜牧这首诗的艺术魅力就在于含蓄、精深，诗不明白说出玄宗的荒淫好色，贵妃的恃宠而骄，而形象地用“一骑红尘”与“妃子笑”构成鲜明的对比，就收到了比直抒己见强烈得多的艺术效果。“妃子笑”三字颇有深意。春秋时周幽王为博妃子一笑，点燃烽火，导致国破身亡。读到这里时，读者是很容易联想到这个尽人皆知的故事。“无人知”三字也发人深思。其实“荔枝来”并非绝无人知，至少“妃子”知，“一骑”知，还有一个诗中没有点出的皇帝更是知道的。这样写，意在说明此事重大紧急，外人无由得知，这就不仅揭露了皇帝为讨宠妃欢心无所不为的荒唐，也与前面渲染的不寻常的气氛相呼应。全诗不用难字，不使典故，不事雕琢，朴素自然，寓意精深，含蓄有力，是唐人咏史绝句中的佳作。', poem_tags = '高中古诗,地名,咏史' WHERE poem_title = '过华清宫绝句三首·其一' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '人们说，那太阳落山的地方就是天涯，我竭力朝天涯眺望，也没法看到我的家。\n正在恼恨眼前的青山遮断了我的视线，重重暮云，又把青山密遮。', poem_notes = '落日：太阳落山之地。\n望极：望极：望尽，极目远望。\n碧山：这里指青山。', poem_appreciation = '独自在外，自然充满了对家人的怀念。古诗中表现乡思，除了听风听雨外，最多的是通过登临送目，寄托悲伤。如唐韦应物的《西楼》云：“高阁一怅望，故园何日归？”白居易《江南送北客因凭寄徐州兄弟书》云：“故园望断欲何如？楚水吴山万里余。”李觏这首绝句，也是通过远望，抒发自己思归的牢愁。\n\n　　诗前两句写望，但从望的感受上落笔，不具体写望见些什么。诗人远望时正当黄昏，夕阳西坠，他遥望故乡，故乡不见，远在天涯。这时候，他看到了落日，又想到落日之处就是天涯，然而明明白白地看得见落日，却仍然望不到故乡。这两句，把思家的愁苦表现得很深刻。诗先以落日处即天涯作衬，使后句望不见故乡的失望更重更深，在表现时却不直说，而是通过两个“天涯”的反复吟咏比较，让人从中体会出来。以落日喻天涯，是从《世说新语·夙惠》中得到启发。《世说新语》载：晋元帝曾问明帝：“长安与太阳谁远。”明帝起先回答太阳远，因为没见过有人从太阳那儿来。后来又改口说太阳近，因为“举目见日，不见长安”。后来人们常用这典故，以天涯太阳比喻远。如唐岑参《忆长安曲》云：“东望望长安，正值日初出。长安不可见，喜见长安日。”就是在所忆之处与太阳上做文章。\n\n　　落日终于西沉了，暮色从天际酒来，把诗人的视野压迫到近前碧山。三四句即从近处着墨，写诗人凝视碧山的所见所感。“已恨”句转折巧妙，既承接上句，补充说明“不见家”之由，又“暗度陈仓”，由前二句着眼于空间的距离转到着眼于空间的阻隔。故乡不可见，不仅因为距离遥远，还因为路途阻隔，所以通出一个“恨”字来。第三句用“已恨”二字领起，无限感慨已在其中。第四句再递进一层，故乡为碧山阻隔，已令人恨恨不已，何况眼下碧山又被暮云遮掩。诗用“还被”二字唤起，障碍重重，恨重重。再说，山本可用青、绿形容，用青更符合诗的平仄要求，可是诗人却用碧字，大约是因为青、绿较为轻、明，碧较为重、暗，不仅更符合等色苍茫中山的色彩，而且能唤起凝童情绪。而当苍茫的暮色遮掩住碧山，凝重压抑感也就更加强烈。诗至结尾，随着时间的冉冉推移，诗人的视野由远而近、由大而小的逐步收缩，色调的由明而暗的变化，结构上的层层递进，那乡思也就愈来愈浓郁，以致浓得化不开。\n\n　　全诗四句，分四层意思，层层深入，不断推进，把思想感情发挥到极致。中国古代诗词作法，有透过一层、加一倍写法。这种写法，有用在一联中的，如杜甫《夜闻觱篥》云：“君知天地干戈满，不见江湖行路难。”本意写行路难，再加写遍地战争，行路就更难了。又如李商隐《无题》：“刘郎已恨蓬山远，更隔蓬山一万重。”也是如此。更多的是用若干句透过一层，如宋徽宗《宴山亭·北行见杏花》词：“天遥地远，万水千山，知他故宫何处。怎不思量，除梦里有时曾去。无据，和梦也新来不做。”写思念故宫，故宫不见，转而梦见，最后连梦中也见不到，把感情的波浪重重推向高涨。李觏的这首诗，也是采用了这一手法。', poem_tags = '古诗三百首,思乡' WHERE poem_title = '乡思' AND poem_author = '李觏';
UPDATE edu_poem SET poem_translation = '蟋蟀在草丛中幽凄地鸣叫着，梢头的梧桐叶子似被这蛩鸣之声所惊而飘摇落下，由眼前之景，联想到人间天上的愁浓时节。在云阶月地的星空中，牛郎和织女被千重关锁所阻隔，无由相会。牛郎和织女一年只有一度的短暂相会之期，其余时光则有如浩渺星河中的浮槎，游来荡去，终不得相会聚首。\n鹊桥或许还未搭就，牵牛织女或许还是在离别之中未能相聚吧，猜想此时乌鹊已将星桥搭起，可牛郎、织女莫不是仍未相聚，再看天气阴晴不定，忽风忽雨，该不是牛郎、织女的相会又受到阻碍了吧！', poem_notes = '蛩（qióng）：蟋蟀。\n云阶月地：指天宫。\n浮槎：指往来于海上和天河之间的木筏。\n星桥鹊驾：传说七夕牛郎织女在天河相会时，喜鹊为之搭桥，故称鹊桥。\n牵牛织女：二星宿名。 \n甚霎（shà）儿：“甚”是领字，此处含有“正”的意思。霎儿：一会儿。', poem_appreciation = '这首词具体创作年代不详，大约是词人同丈夫婚后又离居的时期。主要借牛郎织女的神话传说，写人间的离愁别恨，凄恻动人。\n\n　　“七夕”是中国传统节日之一，每年七月七日夜里，人们遥望天上的织女星和牵牛星，想起关于他们的美丽传说，无不感叹。这样的日子里，正受别离之苦的词人，感触更深。“草际鸣蛩，惊恐梧桐”。写的是凄清之景：夜是那么静，草丛中蟋蟀的叫声是那么清晰，连梧桐的叶子掉地上也能听到。这两句从听觉入手，不仅增强了下句的感伤情调，而且给全词笼罩上一层凄凉的气氛。“正人间天上愁浓”是作者仰望牵牛、织女发出的悲叹。“天上”暗点出牵牛、织女。七夕虽为牛、女相会之期，然而相会之时即为离别之日，倾诉一年来的别离之苦，想到今夜之后又要分别一年，心情更痛苦。“人间”包括作者和一切别离中的男女。想到牛、女今夜尚能相见，自己却无此机会，内心的悲愁，可见一斑。“愁浓”二字，写尽辛酸。\n\n　　“云阶目地，关锁千重。纵浮槎来，浮槎去，不相逢。”句意思：望着银河，望着云、月，幻觉中进入了想象中的天上世界。“槎”是用竹木编成的筏子，可以渡水。据说乘着它从海上出发，航行十余天，到了天上，可以见有城郭房舍，非常壮丽，望见织女宫中织布，牵牛天河岸边饮牛。天宫以月为地，以云为阶，重重关锁，即使她象昔人那样乘槎去到天上，又乘槎回来，也不能同织女、牵牛相逢。这几句字面虽写天上，用意则人间。“关锁千重”，极言阻隔之深，致使有情男女不得会合团聚，其中寄托词人个人的别恨。\n\n　　下片仍是作者仰望银河双星时浮现出来的想象世界。传说夏历七月七日夜群鹊银河衔接为桥渡牛、女相会，称为“鹊桥”，也称“星桥”。分别一年，只得一夕相会，离情别恨，自然年年月月永无穷尽。“想”意“讨想”、“想像”等包含着对牛、女的痛惜、体贴和慰藉意，还有启下的作用。正当人们悲慨牛、女常年别离时，刚刚相会的他们，又要别离了。“莫是离中”的“莫”为猜疑之词，即大概，大约之意。结尾三字用一“甚”字总领，与上片末三句句式相同，为此词定格。“甚”这里是时间副词，作“正当”“正值”的“正”解释。“霎儿”是口语，指短暂的时间，意思是一会儿。天这么一会儿晴，一会儿雨，一会儿又刮风，大约织女、牵年已分离了吧？叠用三个“霎儿”，逼肖烦闷难耐声口，写得幽怨不尽。牵牛、织女正是人间别离男女的化身，对他们不幸遭遇的叹恨，正是对人间离愁别情的叹恨。这几句语意双关，构思新颖，用天气的阴晴喻人间的悲喜，贴切生动。\n\n　　这首词由人间写起，先言个人所见所感，再据而继之天上神话世界。通篇以牛女传说为寄托，境界奇丽，曲径通幽，写透了青年男女的离愁别恨。', poem_tags = '宋词精选,七夕节,孤独' WHERE poem_title = '行香子·七夕' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '最使人心神沮丧、失魂落魄的，莫过于别离啊。何况秦国吴国啊是相去极远的国家，更有燕国宋国啊相隔千里。有时春天的苔痕啊刚刚滋生，蓦然间秋风啊萧瑟初起。因此游子离肠寸断，各种感触凄凉悱恻。风萧萧发出与往常不同的声音，云漫漫而呈现出奇异的颜色。船在水边滞留着不动，车在山道旁徘徊而不前，船桨迟缓怎能向前划动，马儿凄凉地嘶鸣不息。盖住金杯吧谁有心思喝酒，搁置琴瑟啊泪水沾湿车前轼木。居留家中的人怀着愁思而卧，恍然若有所失。映在墙上的阳光渐渐地消失，月亮升起清辉洒满了长廊。看到红兰缀含着秋露，又见青楸蒙上了飞霜。巡行旧屋空掩起房门，抚弄锦帐枉生清冷悲凉。想必游子别离后梦中也徘徊不前，猜想别后的魂魄正飞荡飘扬。\n\n　　所以离别虽给人同一种意绪，但具体情况却不相同：\n\n　　至于像高头骏马配着镶银的雕鞍，漆成朱红的车驾饰有采绘的轮轴，在东都门外搭起蓬帐饯行，送别故旧于金谷名园。琴弦发出羽声啊箫鼓杂陈，燕赵的悲歌啊令美人哀伤；明珠和美玉啊艳丽于晚秋，绫罗和纨绮啊娇媚于初春。歌声使驷马惊呆地仰头咀嚼，深渊的鱼也跃出水面聆听。等到分手之时噙着泪水，深感孤单寂寞而黯然伤神。\n\n　　又有自惭未报主人恩遇的剑客，和志在报恩的少年侠士，如聂政击杀韩相侠累、豫让欲刺赵襄子于宫厕，专诸杀吴王、荆轲行刺秦王，他们舍弃慈母娇妻的温情，离开自己的邦国乡里，哭泣流泪地与家人诀别，甚至擦拭泪血互相凝视。骑上征马就不再回头，只见路上的尘土不断扬起。这正是怀着感恩之情以一剑相报，并非为换取声价于黄泉地底。钟磬震响吓得儒夫脸色陡变，亲人悲恸得尽哀而死。\n\n　　有时候边境发生了战争，挟带弓箭毅然去从军。辽河水一望无际，雁门山高耸入云。闺房里风晴日暖，野外道路上绿草芬芳。旭日升临天际灿烂光明，露珠在地上闪耀绚丽的色彩，透过红色的雾霭阳光分外绚烂，映入春天草木的雾气烟霞弥漫。手攀着桃李枝条啊不忍诀别，为心爱的丈夫送行啊泪水沾湿了衣裙。\n\n　　至于一旦到达绝远的国度，哪里还有相见的日期。望着高大的树木啊记下这故乡旧里，在北面的桥梁上啊诀别告辞。送行的左右仆从啊魂魄牵动，亲戚宾客啊落泪伤心。可以铺设树枝而坐啊把怨情倾诉，只有凭借杯酒啊叙述心中的伤悲。正当秋天的大雁啊南飞之日，正是白色的霜露啊欲下之时，哀怨又惆怅啊在那远山的弯曲处，越走越远啊在那长长的河流边。\n\n　　又如郎君住在淄水西面，妾家住在黄河北岸。曾佩带琼玉一起浴沐着晨光，晚上一起坐在香烟袅袅的金炉旁。郎君结绶做官啊一去千里，可惜妾如仙山琼草徒然芬芳。惭对深闺中的琴瑟无心弹奏，重帷深掩遮暗了高阁上的流黄。春天楼宇外关闭了青翠的苔色，秋天帷帐里笼罩着洁白的月光；夏天的竹席清凉啊白日迟迟未暮，冬天的灯光昏暗啊黑夜那么漫长！为织锦中曲啊已流尽了泪水，组成回文诗啊独自顾影悲伤。\n\n　　或有华山石室中修行的道士，服用丹药以求成仙。术已很高妙而仍在修炼，道已至“寂”但尚未得到真情。一心守炼丹灶不问世事，炼丹于金鼎而意志正坚。想骑着黄鹤直上霄汉，欲乘上鸾鸟飞升青天。一刹那可游行可万，天上小别人间已是千年。唯有世间啊看重别离，虽已成仙与世人告别啊仍依依不舍。\n\n　　下界有男女咏“芍药”情诗，唱“佳人”恋歌。卫国桑中多情的少女，陈国上宫美貌的春娥。春草染成青翠的颜色，春水泛起碧绿的微波，送郎君送到南浦，令人如此哀愁情多！至于深秋的霜露像珍珠，秋夜的明月似玉珪，皎洁的月光珍珠般的霜露，时光逝去又复来，与您分别，使我相思徘徊。\n\n　　所以尽管别离的双方并无一定，别离也有种种不同的原因，但有别离必有哀怨，有哀怨必然充塞于心，使人意志丧失神魂滞沮，心理、精神上受到巨大的创痛和震惊。虽有王褒、扬雄绝妙的辞赋，严安、徐乐精深的撰述，金马门前大批俊彦之士，兰台上许多文才杰出的人，辞赋如司马相如有“凌云之气”的美称，文章像驺奭有“雕镂龙文”的名声，然而有谁能描摹出分离时瞬间的情状，抒写出永诀时难舍难分之情呢！', poem_notes = '黯然：心神沮丧，形容惨戚之状。销魂，即丧魂落魄。\n秦吴：古国名。秦国在今陕西一带，吴国在今江苏、浙江一带。\n绝国：相隔极远的邦国。\n燕宋：古国名。燕国在今河北一带，宋国在今河南一带。\n蹔：同“暂”。\n逶迟：徘徊不行的样子。\n櫂（zhào）：船桨，这里指代船。\n容与：缓慢荡漾不前的样子。\n讵前：滞留不前。此处化用屈原《九章·涉江》中“船容与而不进兮，淹回水而疑滞”的句意。\n掩：覆盖。\n觞（shāng）：酒杯。\n御：进用。\n横：横持；阁置。\n玉柱：琴瑟上的系弦之木，这里指琴。\n沾：同“沾”。\n轼：成前的横木。\n怳（huǎng）：丧神失意的样子。\n沈彩：日光西沉。沈，同“沉”。\n楸（qiū）：落叶乔木。枝干端直，高达三十米，古人多植于道旁。\n离：即“罹”，遭受。\n曾楹（yíng）：高高的楼房。曾，同“层”。楹，屋前的柱子，此指房屋。\n揜（yǎn）：同“掩”。\n锦幕：锦织的帐幕。二句写行子一去，居人徘徊旧屋的感受。\n踯躅（zhízhú）：徘徊不前的样子。\n意：同“臆”，料想。\n飞扬：心神不安。\n万族：不同的种类。\n龙马：据《周礼·夏官·廋人》载，马八尺以上称“龙马”。\n朱轩：贵者所乘之车。\n绣轴：绘有彩饰的车轴。此指车驾之华贵。\n帐饮：古人设帷帐于郊外以饯行。\n东都：指东都门，长安城门名。\n金谷：晋代石崇在洛阳西北金谷所造金谷园。史载石崇拜太仆，出为征虏将军，送者倾都，曾帐饮于金谷园。\n羽：五音之一，声最细切，宜于表现悲戚之情。琴羽，指琴中弹奏出羽声。\n张：调弦。\n燕赵：《古诗》有“燕赵多佳人，美者额如玉”句。后因以美人多出燕赵。\n上春：即初春。\n驷马：古时四匹马拉的车驾称驷，马称驷马。\n仰秣（mò）：抬起头吃草。原形容琴声美妙动听，此处反其意。\n耸：因惊动而跃起。\n鳞：指渊中之鱼。\n造：等到。\n衔涕：含泪。\n寂漠：即“寂寞”。\n惭恩：自惭于未报主人知遇之恩。\n报士：心怀报恩之念的侠士。\n韩国：指战国时侠士聂政为韩国严仲子报仇，刺杀韩相侠累一事。\n赵厕：指战国初期，豫让因自己的主人智氏为赵襄子所灭，乃变姓名为刑人，入宫涂厕，挟匕首欲刺死赵襄子一事。\n吴宫：指春秋时专诸置匕首于鱼腹，在宴席间为吴国公子光刺杀吴王一事。\n燕市：指荆轲与朋友高渐离等饮于燕国街市，因感燕太子恩遇，藏匕首于地图中，至秦献图刺秦王未成，被杀。高渐离为了替荆轲报仇，又一次入秦谋杀秦王事。\n沥泣：洒泪哭泣。\n抆（wěn）：擦拭。抆血，指眼泪流尽后又继续流血。\n衔感：怀恩感遇。衔，怀。\n买价：指以生命换取金钱。\n泉里：黄泉。\n金石震：钟、磬等乐器齐鸣。\n骨肉：指死者亲人。\n负羽：挟带弓箭。\n辽水：辽河。在今辽宁省西部，流经营口入海。\n雁山：雁门山。在今山西原平县西北。\n耀景：闪射光芒。\n腾文：指露水在阳光下反射出绚烂的色彩。\n镜：照耀。\n朱尘：红色的尘霭。\n照，日光。烂，光彩明亮而绚丽。\n袭：扑入。\n青气：春天草木上腾起的烟霭。\n烟煴（yīnyūn）：同“氤氲”。云气笼罩弥漫的样子。\n爱子：爱人，指征夫。\n讵：岂有。\n乔木：高大的树木。\n“决北”句：语出《楚辞·九怀》。\n班：铺设。\n荆：树枝条。人们以“班荆道故”来比喻亲旧惜别的悲痛。\n尊：同“樽”，酒器。\n湄：水边。\n淄右：淄水西面。在今山东境内。\n河阳：黄河北岸。\n琼佩：琼玉之类的佩饰。\n二句回忆昔日朝夕共处的爱情生活。\n绶：系官印的丝带。结绶，指出仕做官。\n瑶草：仙山中的芳草。这里比喻闺中少妇。\n徒芳：比喻虚度青春。\n晦：昏暗不明。\n流黄：黄色丝绢，这里指黄绢做成的帷幕。这一句指为免伤情，不敢卷起帷幕远望。\n春宫：指闺房。\n閟（bì）：关闭。\n簟（diàn）：竹席。\n釭（gāng）：灯。以上四句写居人春、夏、秋、冬四季相思之苦。傥（tǎng）：同“倘”。\n华阴：即华山，在今陕西渭南县南。\n上士：道士；求仙的人。\n\n服食：道家以为服食丹药可以长生不老。\n还山：即成仙。一作“还仙”。\n寂：进入微妙之境。\n传：至，最高境界。\n丹灶：炼丹炉。\n不顾：指不顾问尘俗之事。\n炼金鼎：在金鼎里炼丹。\n骖（cān）：三匹马驾车称“骖”。\n鸾：古代神话传说中凤凰一类的鸟。\n少别：小别。\n谢：告辞，告别。以上写学道炼丹者的离别。\n下：下土。与“上士”相对。\n桑中：卫国地名。\n上宫：陈国地名。\n卫女、陈娥：均指恋爱中的少女。\n渌（lù）波：清澈的水波。\n南浦：泛指送别之地。珪（guī）：一种洁白晶莹的圆形美玉。\n别方：别离的双方。\n名：种类。\n盈：充盈。\n折、惊：均言创痛之深。\n渊：即王褒，字子渊。\n云：即扬雄，字子云。二人都是汉代著名的辞赋家。\n严：严安。\n乐：徐乐。二人为汉代著名文学家。\n金闺：原指汉代长安金马门。后来为汉代官署名。是聚集才识之士以备汉武帝诏询的地方。\n彦：有学识才干的人。\n兰台：汉代朝廷中藏书和讨论学术的地方。', poem_appreciation = '离别是人生总要遭遇的内容，伤离伤别也是人们的普遍情感。江淹的《别赋》择取离别的七种类型摹写离愁别绪，有代表性，并曲折地映射出南北朝时战乱频繁、聚散不定的社会状况。其题材和主旨在六朝抒情小赋中堪称新颖别致。\n\n　　文章眉目清晰，次序井然。其结构类似议论文，开宗明义，点出题目，列出论点：“黯然销魂者，唯别而已矣。”首段总起，泛写人生离别之悲，”黯然销魂“四字为全文抒情定下基调。中间七段分别描摹富贵之别、侠客之别、从军之别、绝国之别、夫妻之别、方外之别、情侣之别，以“别虽一绪，事乃万族”铺陈各种别离的情状，写特定人物同中有异的别离之情。末段则以”别方不定，别理千名，有别必怨，有怨必盈“的打破时空的方法进行概括总结，在以悲为美的艺术境界中，概括出人类别离的共有感情。其结构又似乐曲中的ABA形式，首尾呼应，以突出主旨。\n\n　　《别赋》最突出的成就，在于借环境描写和气氛渲染以刻画人的心理感受。作者善于对生活进行观察、概括，提炼，择取不同的场所、时序、景物来烘托、刻画人的情感活动，铺张而不厌其详，夸饰而不失其真，酣畅淋漓，信然能引发共鸣，而领悟”悲“之所以为美。作者对各类特殊的离别情境，根据其各自特点，突出描写某一侧面，表现富有特征的离情。作者力求写出不同离怨的不同特征，不仅事不同，而且情不同，境不同，因而读来不雷同，不重复，各有一种滋味，也有不同启迪。\n\n　　善于抓住特征，善于选择素材，还必须有相应的语言技巧，方可描写出色。《别赋》的文饰骈俪整饬，但却未流入宫体赋之靡丽，亦不同于汉大赋的堆砌，清新流丽，充满诗情画意。尤其是”春草碧色，春水渌波，送君南浦，伤如之何“等名句，如溪流山中，着落预判，千古传诵。', poem_tags = '辞赋精选,离别' WHERE poem_title = '别赋' AND poem_author = '江淹';
UPDATE edu_poem SET poem_translation = '河边春草青青，连绵不绝伸向远方，令我思念远行在外的丈夫。远在外乡的丈夫不能终日思念，但在梦里很快就能见到他。\n梦里见他在我的身旁，一觉醒来发觉他仍在他乡。他乡各有不同的地区，丈夫在他乡漂泊不能见到。\n桑树枯萎知道天风已到，海水也知道天寒的滋味。同乡的游子各自回家亲爱，有谁肯向我告诉我丈夫的讯息？\n有位客人从远方来到，送给我装有绢帛书信的鲤鱼形状的木盒。呼唤童仆打开木盒，其中有尺把长的用素帛写的信。\n恭恭敬敬地拜读丈夫用素帛写的信，信中究竟说了些什么？书信的前一部分是说要增加饭量保重身体，书信的后一部分是说经常想念。', poem_notes = '绵绵：这里义含双关，由看到连绵不断的青青春草，而引起对征人的缠绵不断的情思。\n远道：远行。\n宿昔：指昨夜。\n觉：睡醒。\n展转：亦作“辗转”，不定。这里是说在他乡作客的人行踪无定。“展转”又是形容不能安眠之词。如将这一句解释指思妇而言，也可以通，就是说她醒后翻来覆去不能再入梦。\n枯桑：落了叶的桑树。这两句是说枯桑虽然没有叶，仍然感到风吹，海水虽然不结冰，仍然感到天冷。比喻那远方的人纵然感情淡薄也应该知道我的孤凄、我的想念。\n入门，指各回自己家里。\n媚：爱。言：问讯。以上二句是把远人没有音信归咎于别人不肯代为传送。\n双鲤鱼：指藏书信的函，就是刻成鲤鱼形的两块木板，一底一盖，把书信夹在里面。一说将上面写着书信的绢结成鱼形。\n烹：煮。假鱼本不能煮，诗人为了造语生动故意将打开书函说成烹鱼。\n尺素书：古人写文章或书信用长一尺左右的绢帛，称为“尺素”。素，生绢。书，信。\n长跪：伸直了腰跪着，古人席地而坐，坐时两膝着地，臀部压在脚后根上。跪时将腰伸直，上身就显得长些，所以称为“长跪”。\n下：末二句“上”、“下”指书信的前部与后部。', poem_appreciation = '这是一首汉乐府民歌，抒写怀人情愫。诗歌的笔法委曲多致，完全随着抒情主人公飘忽不定的思绪而曲折回旋。比如诗的开头，由青青绵绵而“思远道”之人；紧接着却说“远道不可思”，要在梦中相见更为真切；“梦见在身边”，却又忽然感到梦境是虚的，于是又回到相思难见上。八句之中，几个转折，情思恍惚，意象迷离，亦喜亦悲，变化难测，充分写出了她怀人之情的缠绵殷切。诗中所写思妇种种意想，似梦非梦，似真非真。象诗中所写他家有人归来和自己接到“双鲤鱼”“中有尺素书”的情节，可能是真的，也可能是一种极度思念时产生的臆象。剖鱼见书，有着浓厚的传奇色彩，而游子投书，又是极合情理的事。作者把二者糅合在一起，以虚写实，虚实难辨，更富神韵。最令人感动的是结尾。好不容易收到来信，“上言加餐食，下言长相忆”，却偏偏没有一个字提到归期。归家无期，信中的语气又近于永诀，蕴含深意。这大概是寄信人不忍明言，读信人也不敢揣想的。如此作结，余味无尽。\n\n　　这首诗以思妇第一人称自叙的口吻写出，多处采用比兴的手法，语言清新通俗，语句上递下接，气势连贯，很有特色。 全诗语言简短质朴，通俗易懂，但具有强烈的艺术感染力。\n\n　　诗起头的“青青河畔草，绵绵思远道。”是作者借著景色的铺陈，引发妇人触景生情，对远离家乡的丈夫的思念。“绵绵”两字传达了两层的意义：妇人“思绪的绵绵”是由“草的绵延不绝”引起的。由于路途的遥远，思念也是突然的，只好在梦中求得相会，然而才在梦中实现的愿望，醒过来后又是遥远的空间隔绝，依旧是“他乡各异县”，彼此无法相见。这一段可以说是故事的前提，在修辞技巧上，“绵绵思远道，远道不可思，”中的“远道”，“宿昔梦见之。梦见在我旁，”中的“梦见”，以及“忽觉在他乡；他乡各异县，”中的“他乡”，都是修辞技巧中的“顶针”句法。这样的连缀句子的方式，使得全段读起来有一种流畅的音乐性。\n\n　　第二层只有两句，“枯桑知天风，海水知天寒。”暗示远方的人也能了解，而邻居却只顾沉浸在家庭的欢乐中，不肯为她捎个信。在这一层中，运用了起兴和对比的手法，写女子寒门独居，表现其孤独和凄凉的感情。\n\n　　最后一段，情节发生了转折。忽然有客从远方带来丈夫木质双鲤鱼夹封的信函，呼儿差封解除了她的思念之苦，而在书中也获得了远方传来的，对她坚定不移的情意。者样的故事，主要在描述中国传统妇女“闺中思人”的感情起伏，文字质朴自然，情感真切悠远。\n\n　　《饮马长城窟行》这首诗是写思妇怀念在远方行役的丈夫的。《盐铁论》中说:“今天下一统， 而方内不安。徭役远，内外烦。古者，过年无徭，逾时无役。今近者数千里，远者 过万里，历二期而长子不还，父子忧愁，妻子咏叹,愤懑之情发于心，慕思之积痛 骨髓。”这首诗就是汉代这类社会现实的反映。正如汉乐府诗的其他优秀作品一 样，它“感于哀乐，缘事而发”，继承和发扬《诗经·国风》的优良传统，善于选择典 型事件，揭示社会现实。', poem_tags = '乐府,妇女,怀人' WHERE poem_title = '饮马长城窟行' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '读书人黄允修来（向我）借书。我把书交授给他并且告诉他说：\n\n　　书不是借来的就不能（认认真真地）去读。你没听说过那些藏书的人（是怎样读书）吗？《七略》（我国最早的图书目录分类著作，分为辑略、六艺略、诸子略、诗赋略、兵书略、术数略、方技略七部）、《四库》（唐朝京师长安和东都洛阳的藏书，有《经》、《史》、《子》、《集》四库。这里《七略》、《四库》都指内府藏书），是天子的藏书，然而天子中读书的人有几个呢？那些搬运起来使牛累得流汗，放在家里塞满了屋子的，是富贵人家的书，然而富贵人中读书的有几个呢？其余那些祖辈和父辈收藏（的书籍），子辈孙辈随便丢弃的就不用说了。不只读书是这样，天下的事物（也）都是这样。不是那人自己的东西却勉强向别人借来，（他）一定担心别人催着要还，因而就显出忧惧的样子，抚摸玩赏那东西久久不能停止，心想：“今天存放（在我这里），明天（就要给人）拿回去，我不能再看到它了。”如果（这东西）已经被我所拥有，（我）一定会（把它）捆扎好放在高处，保存起来，说一声“姑且等到另外的日子再看吧。”\n\n　　我小时候爱好读书，但是家里贫穷，很难得到书读。有个姓张的人藏书很多。（我）到他家去借，（他）不借给我，回来以后我在梦中还出现向他借书的情形。我那种迫切（求书的心情就）像这样。所以（只要）有看过的书就记在心里。（我）做了官以后，薪俸花出去了，书籍买来了，屋里到处都堆放满了，蠹虫丝迹时常覆盖书册。这样以后我（才）感慨借书读的人是（那么）用心专一，而自己少年时候的时光是（多么）值得珍惜的啊!\n\n　　如今姓黄的年轻人像我（从前一样）贫穷，他借书（苦读）也像我（从前一样）；只不过我把书公开，慷慨出借和姓张的吝惜书籍，（不肯出借，）似乎并不相同。这样看来，那么是我本来不幸遇到了姓张的，而姓黄的年轻人本来幸运遇到我吧？（黄生）懂得了（借到书的）幸运和（借不到书的）不幸运，那么他读书一定会专心，而且他还书也一定会很快。\n\n　　（我）写下这篇说，让（它）和书一起（交给黄生）。', poem_notes = '选自《小仓山房文集》。\n生：古时对读书人的通称。\n授：交给，交付。\n子：对人的尊称，相当于现代汉语的“您”。\n七略四库，天子之书：七略四库是天子的书。西汉末学者刘向整理校订内府藏书。刘向的儿子刘歆（xīn）继续做这个工作，写成《七略》。唐朝，京师长安和东都洛阳的藏书，有经、史、子、集四库。这里七略四库都指内府藏书。\n汗牛塞屋，富贵家之书：那汗牛塞屋的是富贵人家的藏书。这里说富贵人家藏书很多，搬运起来就累得牛马流汗，放置在家里就塞满屋子。汗，动词，使……流汗。\n祖父：祖父和父亲。“祖父”相对“子孙”说。\n弃者：丢弃的情况。\n无论：不用说，不必说。\n然：这样。\n夫（fú）人：那人。指向别人借书的人。\n强（qiǎng）：勉强。\n惴惴（zhuì）：忧惧的样子。\n摩玩：摩挲（suō）玩弄，抚弄。\n业：业已、已经。\n高束：捆扎起来放在高处。束，捆，扎。\n庋（guǐ）：放置、保存。\n姑：姑且，且。\n俟（sì）：等待。\n异日：另外的。\n尔：语气词，罢了。\n难致：难以得到。\n与：给。\n形诸梦：形之于梦。在梦中现出那种情形。形，动词，现出。诸，等于“之于”。\n切：迫切。\n如是：这样。\n故有所览辄省（xǐng）记：（因为迫切地要读书，又得不到书。）所以看过的就记在心里。省，记。\n通籍：出仕，做官。做了官，名字就不属于“民籍”，取得了官的身份，所以说“通籍”。这是封建士大夫的常用语。籍，民籍。通，动词，表示从民籍到仕宦的提升。\n俸：俸禄，官吏的薪水。\n落落：堆积的样子。\n素蟫（yín）：指书里蠹虫。\n灰丝：指虫丝。\n卷（juàn）轴：书册。古代还没有线装书的时期，书的形式是横幅长卷，有轴以便卷起来。后世沿用“卷轴”称书册。\n少时：年轻时。\n岁月：指时间。\n类：似、像。\n公：动词，同别人共用。\n吝：吝啬。\n归：还。\n为一说，使与书俱：作一篇说，让（它）同书一起（交给黄生）。', poem_tags = '议论,抒情' WHERE poem_title = '黄生借书说' AND poem_author = '袁枚';
UPDATE edu_poem SET poem_translation = '纷纷杂杂的树叶飘落在透着清香的石阶上，当次夜深人静之时，那悉悉索索的落叶声更增添了秋天的凉意。卷起珍珠串成的锦帘，华丽的楼阁上空空荡荡，只见到高天淡淡，银河的尽头像垂到大地。年年今天的夜里，都能见到那素绡般的皎月，而年年今天的夜里，心上人都远在千里之外。\n愁肠已经寸断，想要借酒浇愁，也难以使自己沉醉。酒还没有入口，却先化作了辛酸的眼泪。夜已深，灯已残，灯火明灭之间，只好斜靠枕头，聊作睡去，这无休无止的孤栖，真让人尝尽了孤独相似的滋味。算来这苦苦的等待尚遥遥无期，虽说是终日眉头紧锁，心绪万千，也没有一点办法可以解脱回避。', poem_notes = '香砌：有落花的台阶。\n寒声碎：寒风吹动落叶发出的轻微细碎的声音。\n真珠：珍珠。\n天淡：天空清澈无云。\n月华：月光。\n练：白色的丝绸。\n无由：无法。\n明灭：忽明忽暗。\n欹（qī）：倾斜，斜靠。\n谙（ān）尽：尝尽。\n都来：算来。', poem_appreciation = '词的上片以写景为主，景中含情。“一叶落而知秋”，词人先从落叶写起。枯黄的落叶轻盈落在地上，声音轻而细碎，然而词人仅凭耳朵就能听到这些轻细的声音，说明词人的内心极度孤寂，也反衬了夜的岑静。“寒声碎”一句，词人意在告诉读者这细碎的声响不仅带着寒冷的秋意，更传达着他落寞的心境。因此，词人通过开头对秋声、秋色的描绘，渲染出秋夜寒寂的景象，为全词奠定了悲凉的基调。词人卷起珠帘，观看夜色，只见天色清淡如洗，星河如瀑，飞泻远方。词人本是一个“不以物喜，不以己悲”的刚毅男子，然而，在这空寂的天宇下，皎皎的明月中，便能触发他内心世界的幽邈情思。因此，接下来就抒写了词人的落寞之情：年年到了今夜，月光皎洁如练，可惜意中人远在千里之外，不能陪伴自己共赏良辰美景，实在令人惆怅不已。此时感情的激流汹涌澎湃，以景寓情的手法已不能淋漓尽致地抒发内心的情感。于是，词人在下片中，采用了直接抒情的手法倾吐愁思。\n\n　　词的下片抒写词人长夜不寐，无法排遣幽愁别恨的情景和心态。因见不到思念的人儿，词人只好借酒浇愁，可愁到深处，已是肠断，酒也无法来麻醉，酒尚未饮下，已先化作了眼泪。比起入肠化泪，更进一层，足见词人愁思之厚重，情意之凄切。浓浓的愁苦本已侵扰着离人，可一盏如豆的青灯忽明忽暗，与室外月明如昼两相映衬，自然更添凄凉，倍加酸楚，使人无法入睡。因而只能斜靠枕头，寂然凝思，黯然神伤。“谙尽孤眠滋味”中的“谙尽”与上片的“年年”遥相呼应，再次说明愁绪由来已久。词的下片由景入情，情景交融，层层递进，反复咏叹，语直情真，悲凉凄切。\n\n　　自《诗经·关雎》“悠哉悠哉，辗转反侧”出，古诗词便多以卧不安席来表现愁态。范仲淹这里说“残灯明灭枕头欹”，室外月明如昼，室内昏灯如灭，两相映照，自有一种凄然的气氛。枕头欹斜，写出了愁人倚枕对灯寂然凝思神态，这神态比起辗转反侧，更加形象，更加生动。“谙尽孤眠滋味。”由于有前句铺垫，这句独白也十分入情，很富于感人力量。“都来此事”，算来这怀旧之事，是无法回避的，不是心头萦绕，就是眉头攒聚。愁，内为愁肠愁心，外为愁眉愁脸。古人写愁情，设想愁象人体中的“气”，气能行于体内体外，故或写愁由心间转移到眉上，或写由眉间转移到心上。范仲淹这首词则说“眉间心上，无计相回避。”两者兼而有之，比较全面，不失为入情入理的佳句。\n\n　　这首词上片写景为主，景中寓情，以寒夜秋声衬托主人公所处环境的冷寂，突出人去楼空的落寞感，并抒发了良辰美景无人与共的愁情。下片抒情为主，通过写作者长期客居他乡，不免被如素练般的月光感发出阵阵思愁，将怀人相思之情表达得淋漓尽致。末尾以“都来此事，眉间心上，无计相回避。”作结，把思妇对丈夫的思念推向高峰。全词虽然没有出现一个“思”字，但字字句句都是“思”，历来的评词者均认为此词情景两到。另外，词中比喻、通感、白描等手法的运用也极大地增强了艺术表达效果，是一首情景俱佳的名篇。', poem_tags = '宋词精选,婉约,秋天,写景,怀人' WHERE poem_title = '御街行·秋日怀旧' AND poem_author = '范仲淹';
UPDATE edu_poem SET poem_translation = '译文 傍晚的秋露洗净了花枝，烂漫的花朵占尽了天时； 春风桃李繁华早就不再，艳阳伴我从暮春到秋日。', poem_tags = '咏物,写花' WHERE poem_title = '紫薇花' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '译文 香甜的桂花馅料里裹着核桃仁， 用井水来淘洗像珍珠一样的江米， 听说马思远家的滴粉汤圆做得好， 趁着试灯的光亮在风里卖元宵。', poem_tags = '元宵节,食物,汤圆' WHERE poem_title = '上元竹枝词' AND poem_author = '符曾';
UPDATE edu_poem SET poem_translation = '荀巨伯到远方看望生病的朋友，正好遇上胡人来攻城。朋友对荀巨伯说：“我如今是快死的人了，你赶快离开吧！”荀巨伯说：“我远道而来看望你，你却要我离开；败坏道义来求生，怎么是我的行为呢？” 等到贼兵来了，问荀巨伯说：“大军一到，全城的人都逃走了，你是什么人，竟敢独自停留在这里？”荀巨伯回答说：“朋友有疾病，(我)不忍心抛下他，宁愿用我的性命来换取朋友的生命。”贼兵听后相互说道：“我们这些无义的人，却要攻入这个讲究道义的地方！”于是调动整个军队回去了，全城因而得以保留。', poem_notes = '语：对…说\n子：尊称，相当于“您”\n去：离开\n败义：毁坏道义\n岂：难道\n既：已经\n一：整个\n止：停留\n委：丢下；舍弃\n遂：于是\n班军：调回军队，班：撤回\n还：回去\n并：都', poem_appreciation = '荀巨伯冒着生命危险也要保护他的病友，是因为他们的友谊建立在道义基础上，这样的友谊，才是君子之交。义气，不会因富贵贫贱或生死祸福而改变立场与做法，义气是为了正当的事情，而主动愿意替别人承担危险，甚至不惜舍弃自我，成全他人的气度，这也是“真”、“诚”的一种体现。一桩舍生取义的义举，不仅救了朋友的性命，更让敌军自惭而退，可见“义”以及道德的强大感化力量。 这则故事除了让我们见证到患难见真情的可贵外，荀巨伯在生死关头还能不忘圣贤书所言，而表现出大义凛然的行为，更让我们学习到读书人笃行真理的精神。\n\n　　从中揭示了一个道理：做人应该讲情意,舍生取义的义举不仅救了他人性命,更是拯救了一座城,乃至一个国家! 坚守信义、大义凛然、对友忠诚、舍生取义、重情义、把情意看得比生命还重要。这样的人是我们去尊敬的，也是我们要好好学习的。\'\'我辈无义之人，而入有义之国。“是文章的点睛之笔.', poem_tags = '小学文言文,故事,哲理,友情' WHERE poem_title = '荀巨伯探病友 / 荀巨伯探友' AND poem_author = '刘义庆';
UPDATE edu_poem SET poem_translation = '清晨起来刚一开门，看到山头已被一场大雪覆盖。此时，天 空已放晴，初升太阳的光芒，透过淡淡的白云，也变得寒冷了。\n房檐的积雪尚未开始融化，院落的梅花枝条仍被冰雪凝冻。这样一种清冷、孤寂的气氛，是多么不寻常啊！', poem_notes = '这是一首寓托身世的诗\n这句是说，屋上积雪未化，庭中亦因寒而未开放。\n清孤：凄清孤独\n等闲：寻常、一般。', poem_appreciation = '《山中雪后》描绘了一幅冬日山居雪景图。清晨，诗人推开门，外面天寒地冻、银装素裹，刚刚升起的太阳也显得没有活力。院子里，屋檐下长长的冰溜子没有融化的迹象，墙角的梅花也好像被冻住了，迟迟没有开放的意思。\n\n　　诗歌前两句描绘了一幅清晨，雪后大地银装素裹，旭日东升，云彩淡淡（描图景）；雪后初晴、天寒地冻的景象（点氛围）的画面。“檐流未滴梅花冻，一种清孤不等闲”运用了衬托的手法（明手法）“檐流未滴”“梅花冻”突出了天气的寒冷，“清孤不等闲”则是突出了梅花坚强不屈的性格（绘图景），作者托物言志，含蓄地表现了作者清高坚韧的性格和洁身自好的品质（析情感）。\n\n　　在这首诗歌中，郑板桥由大雪之后的寒冷，写到自己内心深处的凄凉，看似写景状物，实则见景生情，将景和物交融一起，对历经苦难的身世发出深深的感叹。', poem_tags = '古诗三百首,冬天,写雪,咏物,梅花,言志' WHERE poem_title = '山中雪后' AND poem_author = '郑燮';
UPDATE edu_poem SET poem_translation = '春天里的幽兰翠叶纷披，秋天里的桂花皎洁清新。\n世间的草木勃勃的生机，自然顺应了美好的季节。\n谁想到山林隐逸的高人，闻到芬芳因而满怀喜悦。\n草木散发香气源于天性，怎么会求观赏者攀折呢！', poem_notes = '兰：此指兰草。 葳蕤：枝叶茂盛而纷披\n桂华：桂花，“华”同“花”。\n生意：生机勃勃\n自尔：自然地 。佳节：美好的季节\n林栖者：山中隐士\n 坐：因而\n本心：天性\n美人：指林栖者山林高士、隐士\n闻风：闻到芳香。\n坐：因为。\n葳（wei）蕤(rui)：枝叶茂盛而纷披。', poem_appreciation = '此诗系张九龄遭谗被贬为荆州长史时所作，开元末期，唐玄宗沉溺声色，怠慢政事，宠仁口蜜腹剑的李林甫和专事逢迎的牛仙客。牛、李结党，把持朝政，排除异己，朝政更加腐败。张九龄对此十分不满，于是采用传统的比兴手法，托物寓意，作《感遇十二首》。诗人托物言志，以春兰和秋桂的芳洁品质，来比喻自己守正不阿的高尚节操；以春兰和秋桂不因无人采折而失去芬芳美质，来比喻自己的志洁行芳，不求人知的高雅情怀。\n\n　　诗一开始用整齐的偶句，以春兰秋桂对举，点出无限生机和清雅高洁之特征。三、四句，写兰桂充满活力却荣而不媚，不求人知之品质。上半首写兰桂，不写人。五、六句以“谁知“急转引出与兰桂同调的山中隐者来。末两句点出无心与物相竞的情怀。\n\n　　全诗一面表达了恬淡从容超脱的襟怀，另一面忧谗惧祸的心情也隐然可见。诗以草木照应，旨诣深刻，于咏物背后，寄寓着生活哲理。', poem_tags = '唐诗三百首,植物,抒志,生活,哲理' WHERE poem_title = '感遇十二首·其一' AND poem_author = '张九龄';
UPDATE edu_poem SET poem_tags = '写景,回忆,思念' WHERE poem_title = '杂诗七首·其一' AND poem_author = '曹植';
UPDATE edu_poem SET poem_tags = '冬天,写景,人民,生活,古诗里的十二个月' WHERE poem_title = '冬十月' AND poem_author = '曹操';
UPDATE edu_poem SET poem_translation = '荷叶初生时，春恨已生。\n荷叶枯时，秋恨又成。\n深深知道，只要身在人世，情意地久天长永存。\n多少惆怅，只有那流不尽的江水声。', poem_notes = '曲江：即曲江池。在今陕西省西安市东南。唐高适《同薛司直诸公秋霁曲江俯见南山作》诗：“南山郁初霁，曲江湛不流。”\n春恨：犹春愁，春怨。唐杨炯《梅花落》诗：“行人断消息，春恨几徘徊。”生：一作“起”。\n深知：十分了解。汉扬雄《法言·问道》：“深知器械舟车宫室之为，则礼由己。”\n怅望：惆怅地看望或想望。唐杜甫《咏怀古迹五首》之二：“怅望千秋一洒泪，萧条异代不同时。”', poem_appreciation = '刘熙载《艺概·诗概》独推李商隐诗“深情绵邈”，这首悼念所爱者的小诗便是一篇很有代表性的佳作。\n\n　　这首七绝虽都是律句，但句与句之间不尽符合粘对规则。作者故意让一二句之间不对，二三句之间不粘，并采用其独擅的字句重用的手法来叙事抒情。冯浩赞此“调古情深”，正说出了这首以律句所写的古绝，声调感怆悲凉，情思缠绵哀痛的特点。\n\n　　“荷叶生时春恨生，荷叶枯时秋恨成”，诗一开头就用缓慢沉重的语气喃喃诉说起作者内心的憾恨。上、下句七字中有四字重复，类似的字句重用令人想起其七绝名篇《夜雨寄北》中关于“巴山夜雨”的吟咏，读来自有回环往复、似直而纡的情韵。这两句赋中寓比，把无情的曲江荷叶化为有情之物，仿佛荷叶的春生、秋枯都与诗人的哀思有关。句中春生、秋枯，恨生、恨成映衬对比，更丰富了诗的内涵。这样，诗的前半从语气、字句、修辞、写法诸方面无不恰到好处地表达出悼亡的沉痛感情。类斯情事在义山的悼亡诗中颇有可印证者，取以参读有助于对此诗内容旨意的理解。《房中曲》云：“忆得前年春，未语含悲辛。”大中三年（849）春，王氏已患病。时义山因府主郑亚被贬，罢桂管幕职落魄返京。夫妻久别重逢，无语凝噎。了解义山长年飘泊，依人作游的经历，自会对其诗中“春恨生”的含意有较具体切实的理解。第二年，诗人为生计所迫，又不得不奔波千里，到徐州卢弘止幕府。《房中曲》又云：“归来已不见，锦瑟长于人。”大中五年（851）春，义山徐幕罢归，补太学博士，在京与爱妻一起度过最后几个月的光阴。不幸王氏于秋天病殁。“柿叶翻时独悼亡”、“秋霖腹疾俱难遣，万里西风夜正长”这些悼亡诗名句，正可说明其“秋恨成”所指为何。“人世死前惟有别”，义山伉俪情深，却为着仕途生计夫妻常常在分离中，王氏遽尔病逝，这给诗人留下多大的憾恨。只有知人论世，才能比较确切地把握其中叙事抒情的内容。\n\n　　“深知身在情长在”一句无限凄惋，将前两句所蕴含的绵绵深情推向无以复加的诗境。如此一往情深的悼亡语，正如其作于东川的《属疾》诗所云：“多情真命薄，容易即回肠。”他也只不过暂存人世，最为伤心的是常常触绪成悲，哀思难禁。不过，这一句显得更为沉痛哀绝，唯《无题》诗中“春蚕到死丝方尽，蜡炬成灰泪始干”的至情之语可以仿佛。诗情亦由此臻于极至的境界。\n\n　　前三句是至情语，结句则新境再展，转用婉曲语作收。又值幕秋之时，衰病垂幕的李商隐独游曲江，闻声起哀，触景伤情。“怅望江头江水声”，他似乎在怅望水声，而不是在听水声。表面的视、听错乱，深刻地反映了他内心的怅恨茫然。通感所谓声入心通，这里正说明其听觉、视觉、感觉的交融沟通。诗人所视、所听并不真切，唯是思潮翻腾，哀痛难忍。曲江流水引起他前尘如梦的回忆，往事难追的怅恨，逝者如斯的叹息。诗戛然而止，却如曲江流水有悠悠不尽之势。', poem_tags = '爱情,思念' WHERE poem_title = '暮秋独游曲江' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '镜湖之大有三百余里，到处都开满了欲放的苛花。\n西施五月曾在此采莲，引得来观看的人挤满了若耶溪。\n西施回家不到一个月，便被选进了宫中。', poem_notes = '子夜吴歌：六朝乐府吴声歌曲。《唐书·乐志》：“《子夜吴歌》者，晋曲也。晋有女子名子夜，造此声，声过哀苦。”《乐府解题》：“后人更为四时行乐之词，谓之《子夜四时歌》。”李白的《子夜吴歌》也是分咏四季，这是第三首《秋歌》。并由原来的五言四句扩展为五言六句。\n镜湖：一名鉴湖，在今浙江绍兴县东南。\n菡（hàn）萏（dàn）：荷花的别称。古人称未开的荷花为“菡萏”，即花苞。\n若耶：若耶溪，在今浙江绍兴境内。溪旁旧有浣纱石古迹，相传西施浣纱于此，故又名“浣纱溪”。\n回舟不待月：指西施离去之速，就在回舟的时候，月亮尚未出来，就被带邀而去了。这是夸饰的修辞手法。', poem_appreciation = '这首诗以写景起端：“镜湖三百里，菡萏发荷花。”广阔三百里的镜湖，在含着花苞的荷花吐发的时候，西施泛舟出现了，成为采莲人，但是她的艳丽和美名引起了轰动，“人看隘若耶”，人人争餐秀色，使宽阔的若耶溪变得狭隘了，这一“隘”字传神，那种人潮汹涌、人舟填溪满岸的热闹场面，犹如呈现在读者眼前，将王维的“艳色天下重”的虚写，变成了轰动当地的如实描绘。这里又戛然而止，不再在西施身上着墨，而留下了很大的想象空间，让读者以合理的想象来补足：勾践早已确定使用美人计来对付吴国，而西施的美艳倾倒众生，轰动当地，那么越国的君臣也不用去费力探访了，有了这位不二的美女人选之后，才“回舟不待月，归去越王家”。较之王维的“朝为越溪女，暮作吴宫妃”，语异而意同，王维的诗多了一重曲折，略去了勾践君臣实施美人计的过程；李白的诗实施了“截割”，割去了选作吴宫妃子的结果，同样地表现了“艳色天下重”的意义。这种截割，多了一些含蓄和暗示：既然是“归向越王家”，勾践同样也能留下这个美人，但他在“报吴”、“复仇”的目标下克制住了；而西施的入吴，却成为亡吴的原因之一。这等于是提醒读者：“到底是因为吴王夫差好色之过，还是由于西施成了亡吴的关键？如果西施是灭亡吴国的关键，那么越国在后来的灭亡又是因为什么？”李白没有对后续的发展着墨，并不是他写不出，而是他有意不写。这样做，同样给读者留下了想象的余地。\n\n　　西施采莲，在若耶溪里，不但有传说，而且合情理；至于泛舟三百镜湖之中，则是作者的想象了。但这一想象却有更改事实之嫌，因为如果是借镜湖湖水的清澈来表现西施“自鉴其美”，或者是借三百里的水程来表现拜倒西施的人的众多，那么下句“人看隘若耶”就显得多余了，这可能是李白百密一疏的笔误。', poem_tags = '唐诗三百首,乐府,夏天,荷花,写人,哲理' WHERE poem_title = '子夜吴歌·夏歌' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '姻：指宝玉与宝钗的婚姻。金玉：语意双关，既有贵重的意思，同时指代宝钗和宝玉。木石，语意双关，和“金玉”相对，指代黛玉和宝玉。\n木石前盟：“金玉良姻”的对立面，指贾宝玉和林黛玉因前世之盟而产生的爱情。\n雪：“薛”的谐音，指薛宝钗，兼喻其冷。高士：文雅有涵养的人，指宝钗。作者以“山中高士”比宝钗，表明了宝钗品性的高洁。\n姝：美女。林：指林黛玉。\n齐眉举案：这里指宝玉与宝钗维持着夫妻相敬如宾的表面虚礼。虽然宝钗对宝玉很好，但宝玉却始终放不下黛玉，所以说“到底意难平”。案：有足的小食盘。', poem_appreciation = '这首曲子出自《红楼梦》，象征着封建婚姻的“金玉良姻”和象征着自由恋爱的“木石前盟”，在小说中都被画上了癞僧的神符，载入了警幻的仙册。这样，贾宝玉和林黛玉的悲剧，贾宝玉和薛宝钗的结合，便都成了早已注定了的命运。这一方面固然有作者悲观的宿命论思想的流露，另一方面也曲折地反映了这样的事实：在封建宗法社会中，要违背封建秩序、封建礼教和封建家族的利益，去寻求一种建立在共同理想、志趣基础上的自由爱情，是极其困难的。因此，眼泪还债的悲剧也像金玉相配的“喜事”那样有它的必然性。\n\n　　然而，封建压迫可以强制人处于他本来不愿意处的地位，可以使软弱的抗争归于失败，但不可能消除已经觉悟到现实环境不合理的人的更加强烈的反叛。没有爱情的“金玉良姻”，无法消除贾宝玉心灵上的巨大创痛、使他忘却精神上的真正伴侣，也无法调和他与薛宝钗之间两种思想性格的本质冲突。“纵然是齐眉举案，到底意难平。”结果终至于贾宝玉万念俱灰，弃家为僧；薛宝钗空闺独守，抱恨终身。所谓“金玉良姻”，实际是“金玉成空”！作品中表现了曹雪芹的思想倾向和他对封建传统观念大胆的、深刻的批判精神。\n\n　　这首曲唱的是宝玉、宝钗、黛玉三个人。\n\n　　本来曲牌名都是固定的，如《山坡羊》、《寄生草》之类，按其格式往里填词。《红楼梦曲》的这些曲名全是作者临时撰杜的，既像曲牌，又是对内容的概括或提示。像这首《终身误》的曲牌名，就是对宝、黛爱情悲剧的感慨，可作标题看。\n\n　　曲中的“俺”，当然是宝玉。薛家到了荣国府后，就有一种舆论说，宝钗带的金锁是个和尚给的，“等日后有玉的方可结为婚姻”。宝钗具备封建阶级女性的一切“美德”，她比黛玉更符合荣府少奶奶的标准，不管她自己是否有意去争取，她都是胜利者。\n\n　　然而宝玉一心只在从小一起长大的林妹妹身上。第三十六回，宝玉睡中觉时连喊带骂地说出这样的话：“和尚道士的话如何信得?什么是金玉良缘?我偏说木石姻缘!”宝、黛志向一致，趣味相投，在大观园长期生活中建立起死生不渝的爱情。\n\n　　有情的不能成为眷属，无情的反倒硬被拉在一起，这是封建时代常见的婚姻悲剧，贵族社会也不例外。黛玉在那个“花柳繁华地、温柔富贵乡”里淌着眼泪度过了短暂的一生死了。宝玉同冷美人宝姐姐结了婚。没有爱情的婚姻能有什么幸福?他对黛玉刻骨铭心的爱情一刻不停地折磨着他，加上家业破败，他亲爱的姐妹们或死或散，全部被抛入黑暗的深渊。\n\n　　他对这个世界彻底幻灭了，最后毅然“悬崖撒手”，当了和尚，一定了之。宝钗要孤独凄凉地去熬未来的岁月，其实也是个失败者。宝、钗、黛三人的爱情悲剧，实质是社会悲剧。\n\n　　整部《红楼梦》像一个巨大的生活长流，各种矛盾自然地交织在一起，自然地演进，自然地激化，自然地结束。作者很少安排巧合的情节。高鹗的续书把黛死钗嫁扭在一起，“林黛玉焚稿断痴情，薛宝钗出闺成大礼”，一边极喜，一边极悲，很富戏剧色彩，但这未必符合曹雪芹原意。曹雪芹究竟怎样安排、处理宝、钗、黛三者结局的具体情节，已不易推知了。\n\n　　曹雪芹把《终身误》放在十二首曲子的第一位，表明了宝玉对宝钗和黛玉两人截然不同的感情和心意，抒发了宝玉对误他终身的“金玉良缘”的愤恨。曲子以宝玉的口吻写就，说明宝玉婚后尽管终日面对的是宝钗，心中仍然念念不忘死去的黛玉。同时又表达了对薛宝钗在得到了婚姻的同时，也葬送了自己的青春和终身幸福的深深同情。“晶莹雪”看似形容宝钗的高洁，实际上是说宝钗内心的冰冷无情。在没有心灵共鸣的情况下，纵然宝钗恪守封建妇德，和宝玉相敬如宾，也抚不平宝玉内心深处的伤口。', poem_tags = '婚姻,爱情' WHERE poem_title = '终身误' AND poem_author = '曹雪芹';
UPDATE edu_poem SET poem_translation = '风吹荡汀洲远远望去像天空席卷着如玉雕的浪花，白茫茫一片，水天一线，何等壮阔。\n渔翁感到寒冷想要回家去，去发现不记得归路。此时渔翁洒脱的躺在船上，放任船漂流，让它带着自己回去，在有浓厚云层的江面上只隐隐看见一艘小小的渔船。', poem_notes = '“钓鱼人”句：柳宗元《江雪》：“孤舟蓑笠翁，独钓寒江雪。”张志和《渔父》：“青箬笠，绿蓑衣，斜风细雨不须归。”本句综合上述二句诗意而成。', poem_tags = '写雪,渔人,生活' WHERE poem_title = '寿阳曲·江天暮雪' AND poem_author = '马致远';
UPDATE edu_poem SET poem_translation = '一对对燕子，你们什么时候飞回来的？小河两岸的桃树枝条浸在水里，鲜红的桃花已经开放。\n下了几天雨，河水涨起来淹没了小桥，人不能过河，正在这时候，一叶小舟从柳阴下缓缓驶出。', poem_notes = '湖：指杭州西湖\n夹岸：两岸。\n蘸（zhàn）水：贴着水面开放。湖中水满，岸边桃树枝条弯下来碰到水面，桃花好像是蘸着水开放。\n断桥：指湖水漫过桥面。\n度：与“渡”通用，走过。\n撑：撑船篙，就是用船篙推船前进。', poem_appreciation = '燕子来了，象征着春天的来临。诗人遇上了燕子，马上产生了春天到来的喜悦，不禁突然一问：“双飞的燕子啊，你们是几时回来的？”这一问问得很好，从疑问的语气中表达了当时惊讶和喜悦的心情。再放开眼界一看，果然春天来了，湖边的桃花盛开，鲜红似锦。蘸是沾着水面。但桃花不同于柳树，它的枝叶不是丝丝下垂的，是不能蘸水的。因为春天多雨，湖水上升，距花枝更近了。桃花倒影映在水中，波光荡漾，岸上水中的花枝连成一片，远处望见，仿佛蘸水而开，这景色美极了。诗人在漫长的湖堤上游春，许许多多动人的景色迎面而来，诗人只选一处：就在春雨把桥面淹没了的地方。一条小溪上面，平常架着小木桥。雨后水涨，小桥被淹没，走到这里， 就过不去了。对称心快意的春游来说，是一个莫大的挫折。可是凑巧得很，柳荫深处，悠悠撑出一只小船来，这就可以租船摆渡，继续游赏了。经过断桥的阻碍，这次春游更富有情趣了。\n\n　　诗人善于抓住事物的本质来加以表现，通过燕子归来，桃花盛开．描绘出春日湖光美景，通过春雨断桥，小舟摆渡来突出湖水上涨的特点。\n\n　　这首诗后两句尤为著名。由桥断而见水涨，由舟小而见湖宽。充分体现了中国诗歌艺术的两个重要审美特点：一是写景在秀丽之外须有幽淡之致。桃花开、燕双飞，固然明媚，但无断桥，便少了逸趣；二是以实写虚，虚实相生。小舟撑出柳阴，满湖春色已全然托出。', poem_tags = '古诗三百首,春游,写景,写雨' WHERE poem_title = '春游湖' AND poem_author = '徐俯';
UPDATE edu_poem SET poem_translation = '我本来已老大无成，不该再说什么了，可是，如今碰到了你这个如同陈登、陈遵般有着湖海侠气的臭味相投者，便忍不住“老夫聊发少年狂”了。我正生着病，你来了，我高兴得陪你高歌痛饮，欢喜和友谊驱散了楼头上飞雪 的寒意。可笑那些功名富贵，别人将其看得如同千钧般重，我们却把它看得如同毫毛一般轻。可是我们当时所谈 论和阐发的那些事关国家兴亡的真知灼见又有谁听见了呢？只有那个照人间沧桑、不关时局安危的西窗明月。我们谈得如此投机，一次又一次地斟着酒， 更换着琴瑟音乐。\n国家大事依然如故，可是人心却大为消沉，不同于过去了。请问你们，神州大 地，究竟还要被金人割裂主宰多久呢？汗血良马拖着笨重的盐车无人顾惜，当政者却要到千里之外用重金收买骏马的骸骨。极目远眺，关塞河防道路阻塞，不能通行。我最尊敬你那闻鸡起舞的壮烈情怀，你曾说过：男子汉大丈夫，抗金北伐的决心至死也会像铁一般坚定。我等待着你大显身手，为恢复中原作出重大的贡献。', poem_notes = '贺新郎：词牌名，又名《金缕曲》《贺新凉》。\n老大：年纪大。那堪：“那”通“哪”；堪：能，可。堪当重任。\n元龙臭味：陈登，字元龙。\n孟公瓜葛：陈遵，字孟公。\n瓜葛：指关系、交情。\n楼头：楼上。\n钧：古代重量单位，合三十斤；发：头发，指像头发一样轻。\n硬语盘空：形容文章的气势雄伟，矫健有力。\n西窗：思念。\n进酒：斟酒劝饮；敬酒。\n鸣瑟：即瑟。\n渠侬：对他人的称呼，指南宋当权者。渠︰他；侬︰你，均系吴语方言。\n神州：中原。\n离合：分裂和统一。此为偏义复词，谓分裂。\n汗血盐车：汗血，汗血马。骏马拉运盐的车子。后以之比喻人才埋没受屈。\n骏骨：喻招揽人才。\n目断：纵目远眺；关河：即边塞、边防，指边疆。\n怜：爱惜，尊敬；中宵：半夜。\n试手：大显身手。\n补天裂：女娲氏补天。', poem_tags = '豪放,叙事,抒情,壮志' WHERE poem_title = '贺新郎·同父见和再用韵答之' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '世事短暂，如春梦一般转眼即逝。人情淡薄，就如秋天朗空上的薄云。不要计较自己的辛勤劳苦，万事本来已经在命中注定的。\n今天幸好遇到三杯好酒，又看见一朵新开的鲜花。短暂的欢乐相聚是如此的亲切，至于明天会怎么样谁也不知道了。', poem_notes = '西江月：原为唐教坊曲，后用作词调。《乐章集》《张子野词》并入“中吕宫”。五十字，上下片各两平韵，结句各叶一仄韵。\n计较：算计。\n且：姑且，聊且。\n相亲：互相亲爱。', poem_appreciation = '这首小词从慨叹人生短暂入笔，表现了词人暮年对世情的一种“彻悟”。\n\n　　回首平生，少年的欢情，壮年的襟抱早已成为遥远的过去，飞逝的岁月在这位年迈的词人心中留下的只有世态炎凉命途多舛的凄黯记忆。所以词的起首二句“世事短如春梦，人情薄似秋云”，是饱含辛酸的笔触。这两句属对工畅，集中地、形象地表达了作者对人生的认识。“短如春梦”、“薄似秋云”的比喻熨帖而自然。接下来，笔锋一转，把世事人情的种种变化与表现归结为“命”（命运）的力量。“原来”二字，透露出一种无可如何的神情，又隐含几分激愤。在强大的命运之神面前他感到无能为力，于是消极地放弃了抗争:“不须计较苦劳心”，语气间含有对自己早年追求的悔意和自嘲。这两句倒装，不只是为了照顾押韵，也有把意思的重点落在下句的因素。情调由沉重到轻松，也反映了他从顿悟中得到解脱的心情。\n\n　　似乎是从宿命的解释中真的得到了解脱，词人转而及时行乐，沉迷于美酒鲜花之中。“幸遇三杯酒好，况逢一朵花新”，“幸遇”、“况逢”等字带来一种亲切感“酒好”、“花新”则是愉悦之情的写照。“三杯”、“一朵”对举，给人以鲜明的印象。\n\n　　上下文都是议论，使得这属对工巧的两句尤其显得清新有趣。着墨不多，主人公那种得乐且乐的生活情态活脱脱地展现出来。结语两句，虽以“片时欢笑且相亲”自安自慰，然而至于“明日阴晴未定”，则又是天道无常，陷入更深的叹息中了。“且”是“姑且”、“聊且”的意思。“阴晴未定是感叹世事的翻覆无定，或许还有政治上的寓意。下片末句与上片“万事原来有命”呼应，又回到“命”上去了。作者的生活态度是强作达观而实则颓唐。\n\n　　词人笔下是清雅隽朗的，是以流露出一种闲旷的风致。自然流转，若不经意，全词如骏马注坡，一气直下。通体使用散文化语句，也是比较特别的。', poem_tags = '人生,哲理,抒怀' WHERE poem_title = '西江月·世事短如春梦' AND poem_author = '朱敦儒';
UPDATE edu_poem SET poem_translation = '我是天宫里掌管山水的郎官，天帝赋予我狂放不羁的性格。曾多次批过支配风雨的手令，也多次上奏留住彩云，借走月亮。\n我自由自在，吟诗万首不为过，喝酒千杯不会醉，王侯将相，哪儿能放在我的眼里？就算是在华丽的天宫里做官，我也懒得去，只想插枝梅花，醉倒在花都洛阳城中。', poem_notes = '清都山水郎：在天上掌管山水的官员。清都，指与红尘相对的仙境。\n疏狂：狂放，不受礼法约束。\n支风券：支配风雨的手令。\n章：写给帝王的奏章\n觞（shāng）：酒器\n玉楼金阙慵（yōng）归去：不愿到那琼楼玉宇之中，表示作者不愿到朝廷里做官。', poem_appreciation = '上片主要写作者在洛阳时纵情于山水，豪放不羁的生活。首句以“山水郎”自居，写自己热爱山水乃出于天性。直抒自己的生活理想，他不喜尘世，流连山水。接下来“天教分付与疏狂”则声称自己懒散的生活方式和狂放的性格特征亦属天赋，因而无法改变。这两句充分表现出了词人的性格特征，坦荡直爽，豪气四溢。 “曾批给雨”二句以天意抒怀抱，透露出作者远避俗世，怡然自得的心理。这二句充满了浪漫的精神，富于神奇的幻想，不仅对首句进行了绝妙而风趣的解释，而且透露了他对大自然的由衷热爱和对世俗发自内心的鄙弃。\n\n　　下片用巧妙的方法表现作者赛神仙的淡泊胸怀。“诗万首，酒千觞。几曾著眼看侯王”写作者诗思的丰富，酒量的很大，隐逸生活的全部内容都表现为对诗与酒的钟情。面对“侯王”几曾看过，凸显词人对功名富贵的鄙夷，面对王侯的傲骨铮铮。 “玉楼金阙慵归去，且插梅花醉洛阳”这二句表现出作者不愿意返回京城官场，只想纵诗饮酒，与山水为伴，隐逸归老。玉楼金阙，本是人人羡慕向往的荣华富贵，但词人用一“慵”字，十分准确地表现了自己鄙薄名利的态度，相反对于“插梅花醉洛阳”的生活却十分欣赏留恋，体现名士的清高、名士的风流，“梅花”是高洁的象征，这里意在言词人的品性高洁。将高洁与疏狂的品性有机地统一起来，表现出不愿与污浊的社会同流合污的狂放。\n\n　　全词清隽婉丽，自然流畅，前后呼应，章法谨严，充分体现了作者蔑视权贵、傲视王侯、潇洒狂放的性格特征。', poem_tags = '宋词三百首,豪放,言志' WHERE poem_title = '鹧鸪天·西都作' AND poem_author = '朱敦儒';
UPDATE edu_poem SET poem_tags = '写山,思念' WHERE poem_title = '与浩初上人同看山寄京华亲故' AND poem_author = '柳宗元';
UPDATE edu_poem SET poem_translation = '素雅之花常常要被艳花欺，白莲花总应生长在瑶池里。\n月儿明风儿清花儿要凋谢，只有恨却无情谁人了解你？', poem_notes = '蘤（huā）：“花”的古体字。\n此花：指白莲。端合：真应该。端，一作“真”。瑶池：传说中的仙境，相传为西王母所居，《穆天子传》有“觞西王母于瑶池之上”的话。\n欲堕时：指白莲将要凋谢的时候。', poem_tags = '咏物,荷花,抒怀' WHERE poem_title = '白莲' AND poem_author = '陆龟蒙';
UPDATE edu_poem SET poem_translation = '早起匆匆赶路，天气晴朗春色正好，可以清晰的看到那小舟荡漾在湖水之上。\n飞鸟在天上自在飞翔，少年无忧无虑的嬉戏打闹，只是这般天真无虑的时光却是与我无缘了。\n少数名族儿童的独特的服饰已经很少看到了，楚地的女孩腰肢纤细，惹人怜惜。\n昔日辉煌的定王府已无踪迹，想象着贾谊府中的古井仍是当年模样。\n虽是只需禁火三日，无奈没有食物烹煮实在辜负了周举的好意了，一直四处奔波，生计却仍无着落。\n富足奢侈的生活还是山林平淡生活都是天意，有浊酒、粗茶淡饭颐养天年也已足够了。\n\n一生都在外颠簸漂泊，右臂已渐渐枯瘦无力一边的耳朵也已听不清。\n想到这病弱的身体，无依无靠，不禁悲从中来，泪湿衣襟。\n流浪漂泊，离都城已越来越远，时光匆匆已过十年，现唯有清明的风俗还与之相同。\n雁阵穿云北去，赶赴北国家园；其他人家也纷纷钻青枫取火，一片清明风光。\n长安的城楼掩映在一片轻烟花语中，那万里山河也是一片锦绣吧。\n春水滔滔不绝的汇向洞庭湖中，阻断了我回去的道路，目之所及茫茫一片白萍，心中更是凄苦愁闷。', poem_notes = '绣羽：鸟。\n衔花：少年。\n胡：泛指少数民族。\n童：儿童。\n结束：服饰装束。\n定王：汉景帝第十子刘发，唐姬所生，微无宠，故封王于卑湿贫国长沙，卒谥定。定王城又名定王台、定王庙等，在长沙县东一里，庙连岗，高七丈，故又谓之定王冈，相传乃定王为望其母唐姬墓所建。\n长怀：遐想，悠思。\n贾傅：即贾谊。\n沾：润泽。\n严君：即严君平，汉蜀郡人。卜筮于成都，日得百钱足以自养，则闭肆下帘读老庄，扬雄曾从其游。\n天性：犹天命，指上天的意旨或上天安排的命运。\n浊醪：浊酒。\n白苹：亦作“白萍”。水中浮草。', poem_tags = '清明节,写景,抒情,爱国,组诗' WHERE poem_title = '清明二首' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '《水经》说：“鄱阳湖的湖口有一座石钟山在那里。”郦道元认为石钟山下面靠近深潭，微风振动波浪，水和石头互相拍打，发出的声音好像大钟一般。这个说法，人们常常怀疑它。如果把钟磬放在水中，即使大风大浪也不能使它发出声响，何况是石头呢！到了唐代李渤才访求石钟山的旧址。在深潭边找到两块山石，敲击它们，聆听它们的声音，南边那座山石的声音重浊而模糊，北边那座山石的声音清脆而响亮，鼓槌停止了敲击，声音还在传播，余音慢慢地消失。他自己认为找到了这个石钟山命名的原因。但是这个说法，我更加怀疑。敲击后能发出声响的石头，到处都这样，可唯独这座山用钟来命名，这是为什么呢？\n\n　　元丰七年六月初九,我从齐安坐船到临汝去，大儿子苏迈将要去就任饶州的德兴县的县尉，我送他到湖口，因而能够看到所说的石钟山。庙里的和尚让小童拿着斧头，在乱石中间选一两处敲打它，硿硿地发出声响，我当然觉得很好笑并不相信。到了晚上月光明亮，特地和苏迈坐着小船到断壁下面。巨大的山石倾斜地立着，有千尺之高，好像凶猛的野兽和奇异的鬼怪，阴森森地想要攻击人；山上宿巢的老鹰，听到人声也受惊飞起来，在云霄间发出磔磔声响；又有像老人在山谷中咳嗽并且大笑的声音，有人说这是鹳鹤。我正心惊想要回去，忽然巨大的声音从水上发出，声音洪亮像不断地敲钟击鼓。船夫很惊恐。我慢慢地观察，山下都是石穴和缝隙，不知它们有多深，细微的水波涌进那里面，水波激荡因而发出这种声音。船回到两山之间，将要进入港口，有块大石头正对着水的中央，上面可坐百来个人，中间是空的，而且有许多窟窿，把清风水波吞进去又吐出来，发出窾坎镗鞳的声音，同先前噌吰的声音相互应和，好像音乐演奏。于是我笑着对苏迈说：“你知道那些典故吗？那噌吰的响声，是周景王无射钟的声音，窾坎镗鞳的响声，是魏庄子歌钟的声音。古人没有欺骗我啊！”\n\n　　任何的事情不用眼睛看不用耳朵听，只凭主观臆断去猜测它的有或没有，可以吗？郦道元所看到的、所听到的，大概和我一样，但是描述它不详细；士大夫终究不愿用小船在夜里在悬崖绝壁的下面停泊，所以没有谁能知道；渔人和船夫，虽然知道石钟山命名的真相却不能用文字记载。这就是世上没有流传下来石钟山得名由来的原因。然而浅陋的人竟然用斧头敲打石头来寻求石钟山得名的原因，自以为得到了石钟山命名的真相。我因此记下以上的经过，叹惜郦道元的简略，嘲笑李渤的浅陋。', poem_notes = '石钟山，在江西湖口鄱阳湖东岸，有南、北二山，在县城南边的叫上钟山，在县城北边的叫下钟山。明清时有人认为苏轼关于石钟山得名由来的说法也是错误的，正确的说法是：“盖全山皆空，如钟覆地，故得钟名。”今人经过考察，认为石钟山之所以得名，是因为它具有钟之“声”，又具有钟之“形”。\n彭蠡：鄱阳湖的又一名称。\n郦元：即郦道元，《水经注》的作者。\n鼓：振动。\n搏：击，拍。\n洪钟：大钟。\n是说：这个说法。\n磬（qìng）：古代打击乐器，形状像曲尺，用玉或石制成。\n李渤：唐朝洛阳人，写过一篇《辨石钟山记》。\n遗踪：旧址，陈迹。这里指所在地。\n南声函胡：南边（那座山石）的声音重浊而模糊。函胡，通“含糊”。\n北音清越：北边（那座山石）的声音清脆而响亮。越，高扬。\n桴（fú）止响腾：鼓槌停止了（敲击），声音还在传播。腾，传播。\n余韵徐歇：余音慢慢消失。韵，这里指声音。徐，慢。\n得之：找到了这个（原因）。之，指石钟山命名的原因。\n尤：更加。\n铿（kēng）然：敲击金石所发出的响亮的声音。\n所在皆是：到处都（是）这样。是，这样。\n元丰：宋神宗的年号。\n六月丁丑：农历六月初九。\n齐安：在今湖北黄州。\n临汝：即汝州（今河南临汝）。\n赴：这里是赴任、就职的意思。\n湖口：今江西湖口。\n硿（kōng）硿焉：硿硿地（发出响声）。焉，相当于“然”。\n莫（mù）夜：晚上。莫，通“暮”。\n森然：形容繁密直立。\n搏人：捉人，打人。\n栖鹘（hú）：宿巢的老鹰。鹘，鹰的一种。\n磔（zhé）磔：鸟鸣声。\n鹳鹤：水鸟名，似鹤而顶不红，颈和嘴都比鹤长。\n心动：这里是心惊的意思。\n噌吰（chēnghóng）：这里形容钟声洪亮。\n舟人：船夫。\n罅（xià）：裂缝。\n涵澹澎湃：波浪激荡。涵澹，水波动荡。澎湃，波浪相激。\n为此：形成这种声音。\n中流：水流的中心。\n空中：中间是空的。\n窍：窟窿。\n窾（kuǎn）坎镗（táng）鞳（tà）：窾坎，击物声。镗鞳，钟鼓声。\n汝识（zhì）之乎：你知道那些（典故）吗？识，知道。\n周景王之无射（yì）：《国语》记载，周景王二十三年（前522）铸成“无射”钟。\n魏庄子之歌钟：《左传》记载，鲁襄公十一年（前561）郑人以歌钟和其他乐器献给晋侯，晋侯分一半赐给晋大夫魏绛。庄子，魏绛的谥号。歌钟，古乐器。\n古之人不余欺也：古人（称这山为“石钟山”）没有欺骗我啊！不余欺，就是“不欺余”。\n臆断：根据主观猜测来判断。臆，胸。\n殆：大概。\n终：终究。\n渔工水师：渔人（和）船工。\n言：指用文字表述、记载。\n此世所以不传也：这（就是）世上没有流传下来（石钟山得名由来）的缘故。\n陋者：浅陋的人。\n以斧斤考击而求之：用斧头敲打石头的办法来寻求（石钟山得名的）原因。考，敲击。\n实：指事情的真相。', poem_appreciation = '结构独特。《石钟山记》的结构不同于一般的记游性散文那样，先记游，然后议论，而是先议论，由议论带出记叙，最后又以议论作结。作者以“疑──察──结论”三个步骤展开全文。全文首尾呼应，逻辑严密，浑然一体。本文第一句就提郦道元的说法，提出别人对此说的怀疑，这种怀疑也不是没有根据，而是用钟磬作的实验为依据。这就为文章的第二段中作者所见的两处声源──石穴罅和大石当中流──作铺垫，从而发出“古之人不余欺也”的慨叹。在文章最后又一次慨叹郦元所说虽对，但太简单了，让世人不能真正明白。而对李渤扣石聆之以此推石钟山得名原因的作法，作者在第一段就表示“余尤疑之”，第二段中寺僧使小童持斧，扣石，作者对此种验证方法仍是“笑而不信”。待实地考察，得出真相之后，在第三段中，作者又回扣前文“笑李渤之陋”。全文由思而行，由感而发，夹叙、夹议，记叙、描写、议论、抒情环环相扣，浑然一体，是为因事说理的千古名篇。\n\n　　行文曲折。行文富于曲折变化，是此文的一个突出特色。例如引述郦道元和李渤的说法，本来是枯燥的内容，作者加上两个辨驳，即顿见精彩。文中写对旧说之疑共有三次，不仅每次写法不同，即便在同一次中，文笔也有曲折。对郦道元，是以人之疑引出己之疑，而己之疑又是以比喻来表达；李渤本来是在纠正郦道元的说法，作者引述时，特别加一句“自以为得之矣”，紧接着陡然一转——“然是说也，余尤疑之”，着一“‘尤”字，说它较郦道元的说法更不可信；对寺僧使小童持斧敲击所谓“石钟”，仅以“余固笑而不信也”一句表示不屑一驳，矛头直指到三百年前得双石“扣而聆之”的李渤，驳李渤全用议论，一针见血，也不同于对郦道元的说法用比喻。而且，此节插在游山之前，也使文章平添波澜。总之，此文所记之事、所讨论的问题虽平常，但通篇几句一折，有些地方一句一转，极起伏变化之致，使议论内容富有可读性。\n\n　　修饰巧妙。文章以生动的比喻（明喻如“声如洪钟”“如猛兽奇鬼”“若老人咳且笑于山谷中者”“如钟鼓不绝”“如乐作焉”，暗喻如“噌者，周景王之无射也，窾坎镗者，魏庄子之歌钟也”），形象的拟人（“森然欲搏人”），贴切的拟声词（“铿然”“焉”“磔磔”“噌”“窾坎镗”），对所见所闻作了绘声绘形的描写，创造出独特的意境。此文的景物描写也因其巧妙的修饰而形象生动见胜。\n\n　　语言灵活。文章语言灵活畅达，变化多姿，很有特色。对两处鸟叫和两处水声的描写完全不同：写栖鹘是先点鸟名（“山上栖鹘”），再写惊飞（“闻人声亦惊起”），最后才写其叫声（“磔磔云霄间”）；写鹳鹤是先写声音（“又有若老人咳且笑于山谷中者”），然后交代是鹳鹤在叫（“或曰此鹳鹤也”）。前者用拟声词“磔磔”形容其惊叫，后者用比喻“若老人咳且笑”形容其怪叫。两处水声的描写也完全不同：前面的水声是“微波”与山下的“石穴罅”相击而发出的，后面的水声是“风水”与中流大石的窍穴相吞吐而发出的，这是声源不同；前面的“噌如钟鼓不绝”是一种洪大响亮的声音，后面的“窾坎镗······如乐作焉”是一种比较低而悠扬的声音，这是音调和音量的不同；前面是先闻声，后发现山下“石穴罅”，后面是先看见“大石当中流”，“空中而多窍”，然后再写“有窾坎镗之声”，写的顺序也不同。', poem_tags = '古文观止,纪游,写景,写山' WHERE poem_title = '石钟山记' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '同一帮友人在安远楼聚会，酒席上一位姓黄的歌女请我作一首词，我便当场创作此篇。时为八月五日。\n\n芦苇的枯叶落满沙洲，浅浅的寒水在沙滩上无声无息地流过。二十年光阴似箭，如今我又重新登上这旧地南楼。柳树下的小舟尚未系稳，我就匆匆忙忙重回故地。因为过不了几日就是中秋。\n早已破烂不堪的黄鹤矶头，我的老朋友有没有来过？我眼前满目是苍凉的旧江山，又平添了无尽的绵绵新愁。想要买上桂花，带着美酒一同去水上泛舟逍遥一番。但却没有了少年时那种豪迈的意气。', poem_notes = '唐多令，词牌名，也写作《糖多令》，又名《南楼令》，双调，六十字，上下片各四平韵，亦有前片第三句加一衬字者。\n安远楼：在今武昌黄鹄山上，又称南楼。姜夔《翠楼吟》词序云：“淳熙十三年（1186）冬，武昌安远楼成。”当时武昌是南宋和金人交战的前方。\n小集：此指小宴。\n侑（yòu）觞歌板：指酒宴上劝饮执板的歌女。侑觞，劝酒。歌板，执板奏歌。\n龙洲道人：刘过自号。\n汀洲：水中小洲。\n二十年句：南楼初建时期，刘过曾漫游武昌，过了一段“黄鹤楼前识楚卿，彩云重叠拥娉婷”（《浣溪沙》）的豪纵生活。南楼，指安远楼。\n黄鹤断矶：黄鹤矶，在武昌城西，上有黄鹤楼。断矶，形容矶头荒凉。\n浑是：全是。', poem_appreciation = '这是一首名作，后人誉为“小令中之工品。”工在哪里？此写秋日重登二十年前旧游地武昌南楼，所见所思，缠绵凄怆。在表层山水风光乐酒留连的安适下面，可以感到作者心情沉重的失落，令人酸辛。畅达流利而熟练的文辞描写，和谐工整而圆滑的韵律，都好似在这酒酣耳热纵情声色的场面中不得不挂在脸上的笑容，──有些板滞不太自然的笑容。　　这淡淡而深深的哀愁，如满汀洲的芦叶，如带浅流的寒沙，不可胜数莫可排遣。面对大江东去黄鹄断矶竟无豪情可抒！表中郎谓，“大抵物真则贵，真则我面不能同君面，而况古人之面貌乎？”读此《唐多令》应该补充一句：“真则我面不能同我面”，初读谁相信这是大声镗鞳的豪放词人刘过之作？王国维《人间词话》说，“能写真景物、真感情者，谓之有境界。”《唐多令》情真、景真、事真、意真地写出又一个具有个性独创性的刘改之，此小令之“工”，首在这新境界的创造上。\n\n　　论者多说此词暗寓家国之愁，确。怎么见得？请看此词从头到尾在描写缺憾和不满足：“白云千载空悠悠”的黄鹤山头，所见只是芦叶汀洲、寒沙浅流，滔滔大江不是未见，无奈与心境不合；柳下系舟未稳，中秋将到未到；黄鹤矶断，故人不见；江山未改，尽是新愁；欲纵情声色诗酒，已无少年豪兴……。恢复无望，国家将亡的巨大哀感遍布华林，不祥的浓云压城城欲摧。这一灰冷色调的武昌蛇山巅野望抒怀，真使人肝肠寸断，不寒而栗。\n\n　　韩昌黎云，“欢愉之词难工，穷苦之音易好。”其实，忧郁之情，达之深而近真亦属不易。如果过于外露倾泻，泪竭声嘶，反属不美，故词写悲剧亦不可无含蓄，一发不可收形成惨局。此《唐多令》，于含蓄中有深致，于虚处见真事、真意、真景、真情。情之深犹水之深，长江大河，水深难测，万里奔流，转无声息。吾知此词何以不刻画眼前之大江矣？愁境入情，江流心底。“问君能有几多愁？恰似一江春水向东流。”\n\n　　武昌为当时抗金前线，了解这，对词中外松内紧和异常沉郁的气氛当更有所体会。', poem_tags = '宋词三百首,婉约,写景,抒怀,爱国' WHERE poem_title = '唐多令·芦叶满汀洲' AND poem_author = '刘过';
UPDATE edu_poem SET poem_translation = '可恨你不像江边楼上高悬的明月，不管人们南北东西四处漂泊，明月都与人相伴不分离。\n可恨你就像江边楼上高悬的明月，刚刚圆满就又缺了，等到明月再圆不知还要等到何时。', poem_notes = '采桑子：词牌名。又名“丑奴儿令”、“罗敷艳歌”、“罗敷媚”。\n君：这里指词人的妻子。一说此词为妻子思念丈夫。江楼：靠在江边的楼阁。\n暂满还亏：指月亮短暂的圆满之后又会有缺失。满，此指月圆；亏，此指月缺。', poem_appreciation = '此词中表面上说“恨君”，实际上是思君。表面上说只有月亮相随无离别，实际上是说跟君经常别离。下片借月的暂满还亏，比喻他跟君的暂聚又别。这首词的特色富有民歌风味。民歌是感情自然流露，不用典故，是白描。\n\n　　这首词正是真情的自然流露，也是白描。民歌往往采用重复歌唱的形式，这首词也一样。不仅由于《采桑子》这个词调的特点，像“南北东西”，“暂满还亏”两句是反复的；就是上下两片，也有加以变化的重复，如“恨君不似江楼月”与“恨君却似江楼月”只有一字之差，像民歌中的重叠一样。还有，民歌也往往用比喻，这首词的“江楼月”，正是比喻。\n\n　　词中“江楼月”的比喻，很具有艺术特色。钱钟书曾讲过“喻之二柄”、“喻之多边”。钱钟书所谓二柄：“同此事物，援为比喻，或以褒，或以贬，或示喜，或示恶，词气迥异；修词之学，亟宜指示。”例如“韦处厚《大义禅师碑铭》：”佛犹水中月，可见不可取‘，超妙而不可炔，犹云’高山仰止，虽不能至，心向往之‘，是为心服之赞词。黄庭坚《沁园春》：’镜里拈花，水中捉月，觑着无由得近伊‘，犹云’甜糖抹鼻子上，只教他舐不着‘，是为心痒之恨词。“同样这首词用水中之月作比喻，一个表达敬仰之意，一个表示不满之情，然而感情不同，称为比喻的二柄。镜喻于月，如庾信《咏镜》：“月生无有桂‘，取明之相似，而亦可兼取圆之相似王禹偁《龙凤茶》：”圆似三秋皓月轮’，仅取圆之相似，不及于明，‘月眼’、‘月面’均为常言，而眼取月之明，面取月之圆，各傍月性之一边也。“（节引自《管锥篇·周易正义·归妹》如例子中所讲同用月做比喻，可以比圆，又可比明亮，这是比喻的多边。\n\n　　这首词用“江楼月”作比，词人上片里赞美“江楼月”，南北东西，只有相随无别离“，说的是人虽到处漂泊，而明月随人，永不分离，是赞词。下片里也用”江楼月“作比，”暂满还亏，待得团圆是几时“，说的是月圆时少，缺时多，难得团圆，是恨词。\n\n　　同样用“江楼月”作比，一赞一恨，是一篇中用同一事物作比喻而表达不同感情，从而具有二柄。还有，上片的“江楼月”，比喻“只有相随无别离”；下片的“江楼月”，比喻“待得团圆是几时”。一首词里，同用一个比喻，所比不同，构成多边。象这样，同一个比喻，一首词里，既有二柄，又有多边，这是很难找的。因此，这首词里用的比喻，修辞学上是非常突出的。而且这样的比喻，是感情自然流露，不是有意造作，被词人用得非常贴切，这是此首词更为难能可贵的特点。\n\n　　这词的想象跟后汉徐淑《答夫秦嘉书》的想象颇有相似之妙处。徐淑说：“身非形影，何能动而辄俱；体非比目，何能同而不离。”徐淑虽用了两个不同的比喻，“何能动而辄俱”，“何能同而不离”，但与该词想象一致，所以这两人也可以说千载同心了。', poem_tags = '宋词三百首,宋词精选,民歌,婉约,月亮,感叹,离别' WHERE poem_title = '采桑子·恨君不似江楼月' AND poem_author = '吕本中';
UPDATE edu_poem SET poem_translation = '少年时一股侠气，结交各大都市的豪雄之士。待人真诚，肝胆照人，遇到不平之事，便会怒发冲冠，具有强烈的正义感。站立而谈，生死与共。我们推崇的是出众的勇敢，狂放不羁傲视他人。轻车簇拥联镳驰逐，出游京郊。在酒店里豪饮，酒坛浮现出诱人的春色，我们像长鲸和垂虹那样饮酒，顷刻即干。间或带着鹰犬去打猎，霎那间便荡平了狡兔的巢穴。虽然欢快，可惜时间太过短促。\n就像卢生的黄粱一梦，很快就离开京城。驾孤舟飘流于水中，唯有明月相伴。散职侍从官品位卑微，事多繁忙，情怀愁苦。陷入了污浊的官场仕途，担任了繁重的文书事物工作。像我这样成千上万的武官，都被支派到地方上去打杂，劳碌于文书案牍，不能杀敌疆场、建功立业。笳鼓敲响了，渔阳之兵乱起来了，战争爆发了，想我这悲愤的老兵啊，却无路请缨，不能为国御敌，生擒西夏酋帅，就连随身的宝剑也在秋风中发出愤怒的吼声。怅恨自己极不得志，只能满怀惆怅游山临水，抚瑟寄情，目送归鸿。', poem_notes = '六州歌头：词牌名。\n少年侠气，交结五都雄：化用李白“结发未识事，所交尽豪雄”及李益“侠气五都少”诗句。五都：泛指北宋的各大城市。\n一诺千金：喻一言既出，驷马难追，诺言极为可靠。语出《史记·季布列传》引楚人谚曰：“得黄金百斤，不如得季布一诺。”\n盖：车盖，代指车。\n飞：飞驰的马。鞚（kòng）：有嚼口的马络头。\n斗（dǒu）城：汉长安故城，这里借指汴京。\n嗾（sǒu）：指使犬的声音。\n冗（rǒng）从：散职侍从官。\n倥（kǒng）偬（zǒng）：事多、繁忙。\n鹖（hé）弁（biàn）：本义指武将的官帽，指武官。\n笳鼓：都是军乐器。\n渔阳：安禄山起兵叛乱之地。此指侵扰北宋的少数民族发动了战争。\n七弦桐：即七弦琴。桐木是制琴的最佳材料，故以“桐”代“琴”。', poem_tags = '宋词三百首,豪放,壮志,忧国忧民' WHERE poem_title = '六州歌头·少年侠气' AND poem_author = '贺铸';
UPDATE edu_poem SET poem_translation = '看着花儿像你一样，柳枝像你一样；花儿柳枝已青的春天，人却要别离，低下头不禁流下两行清泪。\n长江的东边，还有那长江的西边，两岸的鸳鸯在东西两处飞舞着，（我们）什么时候才能再次相逢呢？', poem_notes = '长相思：词牌名。唐教坊曲。《古诗十九首》有“客从远方来 遗我一书札。上言长相思，下言久离别。”（作者未知）得名。又名《双红豆》、《忆多娇》。\n花柳：花和柳。《楚辞·九歌·少司命》：“悲奠悲兮生别离，乐莫乐兮新相知。”唐，杜甫《遭田父泥饮美严中丞》：“步展随春风，村村白花柳。唐，聂夷中《劝酒》诗之二：“人间荣乐少，四海别离多。”\n鸳鸯（yuān yāng）：本鸟名，此比喻恩爱夫妻。汉·司马相如《琴歌》之一：“室迩人遐独我肠，何缘交颈为鸳鸯。”唐，温庭筠《南歌子》：“不如从嫁与，作鸳鸯。”\n几时：什么时候。唐·杜甫《天末怀李白》：“鸿雁几时到，江湖秋水多。”宋·苏轼《儋州》诗之二：“荔枝几时熟，花头今已繁。”', poem_tags = '宋词精选,怀人' WHERE poem_title = '长相思·花似伊' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '二月的江南花开满枝头，在他乡过寒食节足够悲哀了。\n贫困的生活平常也是不生火做饭的，不仅仅是明天才吃子推这样的冷食。', poem_notes = '寒食：寒食节，在清明前一日或两日，这一天禁火冷食。\n子推：寒食节前一天所作的枣糕名为子推。', poem_tags = '寒食节,思乡' WHERE poem_title = '寒食' AND poem_author = '孟云卿';
UPDATE edu_poem SET poem_translation = '麟的脚趾呵，仁厚的公子呵。哎哟麟呵！\n麟的额头呵，仁厚的公姓呵。哎哟麟呵！\n麟的尖角呵，仁厚的公族呵。哎哟麟呵！', poem_notes = '麟：麒麟，传说动物。它有蹄不踏，有额不抵，有角不触，被古人看作至高至美的野兽，因而把它比作公子、公姓、公族的所谓仁厚、诚实。趾：足，指麒麟的蹄。\n振振（zhēn真）：诚实仁厚的样子。公子：与公姓、公族皆指贵族子孙。\n于（xū虚）：通吁，叹词。　于嗟：叹美声。\n定：通“顁”，额。\n公姓：诸侯之子为公子，公子之孙为公姓。或曰公姓犹言公子，变文以协韵。\n公族：与公姓义同。', poem_appreciation = '这是一首赞美诸侯公子的诗。但这公子究竟是作为商纣“西伯”的文王之子，还是爵封“鲁公”的周公旦之子，抑或是一般的贵族公子，就不得而知了。按朱熹《诗集传》“文王后妃德修于身，而子孙宗族皆化于善，故诗人以‘麟之趾’兴公之子”的解说看，似指周文王的“子孙”而言；但《毛诗序》则有“《关雎》之化行则天下无犯非礼，虽衰世之公子，皆信厚如麟趾之时也”之说。既为“衰世”，就非必定为文王或周公之子了。\n\n　　赞美贵族公子，而以“麟”起兴，这在今天的读者，或许会感到奇怪，但在古代却是一桩异常庄重和动情的事。所谓“麟”，其实就是糜，鹿之一种而已。不过古代传说中的“麟”，却非同寻常：据汉刘向《说苑》称，“麒麟，麕身牛尾，圜头一角，含信怀义，音中律吕，步中规矩，择土而践，彬彬然动则有容仪”；《春秋感应符》更发挥“一角”之义曰：“麟一角，明海内共一主也。”《荀子》亦云：“古之王者，其政好生恶杀，麟在郊野。”大抵是一种兆示“天下太平”的仁义之兽。所以后儒赞先王之圣明，则眉飞色舞于“麒麟在圃，鸾凤来仪”；孔子生春秋乱世，则为鲁哀公之“获麟”而泣，以为麟出非时也。\n\n　　明白了“麟”在古人心目中的尊崇地位，即可把握此诗所传达的热烈赞美之情了。首章以“麟之趾”引出“振振公子”，正如两幅美好画面的化出和叠印：眼间刚出现那“不践生草、不履生虫”的仁兽麒麟，悠闲地行走在绿野翠林，却又恍然流动，化作了一位仁厚（“振振”）公子，在麒麟的幻影中微笑走来。仁兽麒麟与仁厚公子，由此交相辉映，令人油然升起一股不可按抑的赞叹之情。于是“于嗟麟兮”的赞语，便带着全部热情冲口而出，刹那间振响了短短的诗行。二、三两章各改动二字，其含义并没有多大变化：由“麟”之趾，赞到“之定”、“之角”，是对仁兽麒麟赞美的复沓；至于“公子”、“公姓”、“公族”的变化，则正如马瑞辰《毛诗传笺通释》所说，“此诗公姓犹言公子，特变文以协韵耳。公族与公姓亦同义”。如此三章回旋往复，眼前是麒麟、公子形象的不断交替闪现，耳际是“于嗟麟兮”赞美之声的不断激扬回荡。视觉意象和听觉效果的交汇，经了叠章的反覆唱叹，所造出的正是这样一种兴奋、热烈的画意和诗情。\n\n　　前文说到这是一首赞美贵族公子的诗，似乎已没有异议。但它究竟歌唱于何种场合，实在又很难判明。方玉润以为此乃“美公族龙种尽非常人也”（《诗经原始》），大抵为庆贺贵族生子的赞美诗，似乎较近原意。古代的王公贵族，总要自夸其身世尊崇不同凡俗，所以他们的后代，也定是“龙种”、“麟子”。这首诗用于恭贺贵族得子的场合，大约正能满足那些王公大人的虚荣、自尊之心。然而，自从卑贱如陈胜、吴广这样的氓隶之徒，曾喊着“王侯将相宁有种乎”的不平之语揭竿而起以后，凡俗之家便也有了愿得“麟子”的希冀。在这样的背景上反观“麟之趾”，则能与仁兽麒麟媲美，而可热情赞美的，就决非只有“公族”、“公姓”了——既然有不少贵族“龙种”，最终被历史证明只是王冠落地的不肖“跳蚤”；那么凡俗之家，就也能崛起叱咤风云的一代“麟子”。', poem_tags = '诗经,赞美' WHERE poem_title = '国风·周南·麟之趾' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '衣服上沾满了旅途上的灰尘和杂乱的酒的痕迹。出门在外去很远的地方宦游，所到之地没有一处是不让人心神暗淡和感伤的。\n我这一辈子就应该做一个诗人吗？为什么骑上瘦驴在细雨中到剑门关去？', poem_notes = '剑门：在今四川省剑阁县北。据《大清一统志》：“四川保宁府：大剑山在剑州北二十五里。其山削壁中断，两崖相嵌，如门之辟，如剑之植，故又名剑门山。”\n征尘：旅途中衣服所蒙的灰尘。\n销魂：心怀沮丧得好像丢了魂似的，神情恍惚。形容非常悲伤或愁苦。\n合：应该。未：表示发问。\n最后二句：典出南宋尤袤《全唐诗话》：“（唐昭宗时）相国郑綮，善诗。或曰：‘相国近为新诗否？’对曰：‘诗思在灞桥风雪中驴子上，此何以得之？”', poem_appreciation = '这是一首广泛传颂的名作，诗情画意，十分动人。然而，也不是人人都懂其深意，特别是第四句写得太美，容易使读者“释句忘篇”。如果不联系作者平生思想、当时境遇，不通观全诗并结合作者其他作品来看，便易误解。作者先写“衣上征尘杂酒痕，远游无处不销魂”。陆游晚年说过：“三十年间行万里，不论南北怯登楼”（《秋晚思梁益旧游》）。梁即南郑，益即成都。实际上以前的奔走，也在“万里”“远游”之内。这样长期奔走，自然衣上沾满尘土；而“国仇未报”，壮志难酬，“兴来买尽市桥酒……如钜野受黄河顿”（《长歌行》），故“衣上征尘”之外，又杂有“酒痕”。“征尘杂酒痕”是壮志未酬，处处伤心（“无处不销魂”）的结果，也是“志士凄凉闲处老”（《病起》）的写照。\n\n　　“远游无处不销魂”的“无处不”（即“处处”），既包括过去所历各地，也包括写这首诗时所过的剑门，甚至更侧重于剑门。这就是说：他“远游”而“过剑门”时，“衣上征尘杂酒痕”，心中又一次黯然“销魂”。\n\n　　引起“销魂”的，还是由于秋冬之际，“细雨”蒙蒙，不是“铁马渡河”（《雪中忽起从戎之兴戏作》），而是骑驴回蜀。就“亘古男儿一放翁”（梁启超《读陆放翁集》）来说，他不能不感到伤心。当然，骑驴本是诗人的雅兴。李贺骑驴带小童出外寻诗，就是一个佳话。李白、杜甫、贾岛、郑棨都有“骑驴”的诗句或故事，而李白是蜀人，杜甫、高适、岑参、韦庄都曾入蜀，晚唐诗僧贯休从杭州骑驴入蜀，写下了“千水千山得得来”的名句，更为人们所熟知。所以骑驴与入蜀，自然容易想到“诗人”。于是，作者自问：“我难道只该（合）是一个诗人吗？为什么在微雨中骑着驴子走入剑门关，而不是过那‘铁马秋风大散关’的战地生活呢？”不图个人的安逸，不恋都市的繁华，他只是“百无聊赖以诗鸣”（梁启超语），自不甘心以诗人终老，这才是陆游之所以为陆游。这首诗只能这样进行解释；也只有这样解释，才合于陆游的思想实际，才能讲清这首诗的深刻内涵。\n\n　　这就是说，作者因“无处不销魂”而黯然神伤，是和他一贯的追求和当时的处境有关。他生于金兵入侵的南宋初年，自幼志在恢复中原，写诗只是他抒写怀抱的一种方式。然而报国无门，年近半百才得以奔赴陕西前线，过上一段“铁马秋风”的军旅生活，旋即又要去后方充任闲职，重做纸上谈兵的诗人了。这使作者很难甘心。所以，“此身合是诗人未”，并非这位爱国志士的欣然自得，而是他无可奈何的自嘲、自叹。如果不是故作诙谐，他也不会把骑驴饮酒认真看作诗人的标志。作者怀才不遇，报国无门，衷情难诉，壮志难酬，因此在抑郁中自嘲，在沉痛中调侃自己。\n\n　　一般地说，这首诗的诗句顺序应该是：“细雨”一句为第一句，接以“衣上”句，但这样一来，便平弱而无味了。诗人把“衣上”句写在开头，突出了人物形象，接以第二句，把数十年间、千万里路的遭遇与心情，概括于七字之中，而且毫不费力地写了出来。再接以“此身合是诗人未”，既自问，也引起读者思索，再结以充满诗情画意的“细雨骑驴入剑门”，形象逼真，耐人寻味，正如前人所言，“状难写之景如在目前，含不尽之意见于言外。”但真正的“功夫”仍在“诗外”（《示子遹》）。', poem_tags = '古诗三百首,写雨,抒怀' WHERE poem_title = '剑门道中遇微雨' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '一有机会便唱否则即罢休，愁恨全然不理照样乐悠悠。\n今天有酒就喝个酩酊大醉，明日有忧虑就等明天再愁。', poem_notes = '得：指得到高歌机会。失：指失去这个机会。\n悠悠：悠闲自在的样子。\n今朝：今日。', poem_appreciation = '该诗成功地塑造一个活脱脱的呼之欲出的纵酒高歌的旷士形象。这个形象虽有政治上失意后颓唐的一面，而其中愤世嫉俗的品格颇得人们赞叹。他除了反映旧时代知识分子一种变态的心理外，而通过人物的形象也状写出了晚唐社会的黑暗现实。\n\n　　这首诗先表现在诗歌形象性的追求上。乍看来此诗无一景语而全属率直的抒情。但诗中所有情语都不是抽象的抒情，而能够给人一个具体完整的印象。如首句说不必患得患失，倘若直说便抽象化、概念化。而写成“得即高歌失即休”那种半是自白、半是劝世的口吻，尤其是仰面“高歌”的情态，则给人以一种生动形象的感受。情而有“态”，便形象化。次句不说“多愁多恨”太无聊，而说“亦悠悠”。也就收到具体生动之效，不特是趁韵而已。同样，不说得过且过而说“今朝有酒今朝醉，明日愁来明日愁”，更将“得即高歌失即休”一语具体化，一个放歌纵酒的旷士形象呼之欲出。\n\n　　先看第三句，“今朝有酒今朝醉”，此句是脍炙人口的名句，诗人在此告诉世人：失意无法排解时，可以以醉解愁。其实以酒消愁古已有之，曹操便有“何以解忧，唯有杜康”之句。但这样的话从诗人的口中说出来就别有一番滋味了：如果真的时时刻刻有酒解愁，一辈子沉醉不醒也未尝不可。可诗人是一位穷愁潦倒的文人，他不能天天有酒，两个“今朝”的重复，道出了所谓的解忧，也只是暂时的排解而已。看来面对人世间纷至沓来的忧患与失意，诗人也没有毕其功一役的解决办法。“明日愁来明日愁”，此句明显地流露出了穷愁潦倒的诗人的无奈与伤心，正因为“醉”的时间是有限的，酒醒之后又如何，尚未排遣的旧愁加上明日的新愁，那是更愁了。由此可见，正在劝解世人凡事看开些的诗人其实自己也没有解决“失即休”这个难题，虽然他对明日之愁采取的是一种不屑一顾的态度，但这恰恰体现了他以酒浇愁，得过且过、无可奈何的凄酸、潦倒。古之文人，生活在那争名夺利的官场社会之中，没有几个能达到如此境界。这，也就是此诗造成的总的形象了。仅指出这一点还不够，还要看到这一形象具有独特个性。只要将此诗与同含“及时行乐”意蕴的杜秋娘所歌《金缕衣》相比较，便不难看到。那里说的是花儿与少年，所以“莫待无花空折枝”，颇有不负青春、及时努力的意味；而这里取象于放歌纵酒，更带迟暮的颓丧，“今朝有酒今朝醉”总使人感到一种内在的凄凉、愤嫉之情。二诗彼此并不雷同。此诗的情感既有普遍性，其形象又个性化，所以具有典型意义。\n\n　　此诗艺术表现上更其成功之处，则在于重叠中求变化，从而形成绝妙的咏叹调。一是情感上的重叠变化。首句先括尽题意，说得时诚可高兴失时亦不必悲伤；次句则是首句的补充，从反面说同一意思：倘不这样，“多愁多恨”，是有害无益的；三、四句则又回到正面立意上来，分别推进了首句的意思：“今朝有酒今朝醉”就是“得即高歌”的反复与推进，“明日愁来明日愁”则是“失即休”的进一步阐发。总之，从头至尾，诗情有一个回旋和升腾。二是音响即字词上的重叠变化。首句前四字与后三字意义相对，而二、六字（“即”）重叠；次句是紧缩式，意思是多愁悠悠，多恨亦悠悠，形成同意反复。三、四句句式相同，但三句中“今朝”两字重叠，四句中“明日愁”竟然三字重叠，但前“愁”字属名词，后“愁”字乃动词，词性亦有变化。可以说，每一句都是重叠与变化手牵手走，而每一句具体表现又各各不同。把重叠与变化统一的手法运用得尽情尽致，在小诗中似乎是最突出的。\n\n　　由于上述两个方面的独到，宜乎千年以来一些穷愁潦倒的人沉饮“自遣”，陶冶情操时，于古人偌多解愁诗句中，惟独最容易记起“今朝有酒今朝醉”来。\n\n　　诗名《自遣》，是自行排遣宽慰的意思。解读此诗，关键全在于诗人将“愁’和“恨”排遣掉了没有。而诗人之“愁”和“恨”是社会之愁，家国之愁，这种愁是诗人自己难以解决的。上书，皇帝不听；劝说，皇帝不理；讽谏，皇帝会恼怒。那诗人怎样排遣，是采取了不理、不采、不合作、不发言的态度。这种玩世不恭的态度虽带有一定的消积成分，然而大多的知识分子都不发言，都不合作，那“此时无声胜有声”拥有很大的力量。', poem_tags = '知识,人生' WHERE poem_title = '自遣' AND poem_author = '罗隐';
UPDATE edu_poem SET poem_translation = '窗户之间的梅子熟了之后落了下来，墙下的竹笋长成了竹林。\n雨不断地下，晴下来的时候甚至不知道春天已经过去，夏天都很晚了。', poem_notes = '连雨：连续下雨。', poem_tags = '夏天' WHERE poem_title = '喜晴' AND poem_author = '范成大';
UPDATE edu_poem SET poem_translation = '清澈的江水曲折地绕村流过，长长的夏日里，村中的一切都显得幽雅。\n梁上的燕子自由自在地飞来飞去，水中的白鸥相亲相近，相伴相随。\n老妻正在用纸画一张棋盘，小儿子敲打着针作一只鱼钩。\n只要有老朋友给予一些钱米，我还有什么奢求呢？', poem_notes = '江村：江畔村庄。\n清江：清澈的江水。江：指锦江，岷江的支流，在成都西郊的一段称浣花溪。曲：曲折。抱：怀拥，环绕。\n长夏：长长的夏日。幽：宁静，安闲。\n自去自来：来去自由，无拘无束。\n相亲相近：相互亲近。\n画纸为棋局：在纸上画棋盘。\n稚子：年幼的儿子。\n禄米：古代官吏的俸给，这里指钱米。”但有“句，一说为”多病所须惟药物“。\n微躯：微贱的身躯，是作者自谦之词。', poem_appreciation = '这首诗写于唐肃宗上元元年（760）。在几个月之前，诗人经过四年的流亡生活，从同州经由绵州，来到了这不曾遭到战乱骚扰的、暂时还保持安静的西南富庶之乡成都郊外浣花溪畔。他依靠亲友故旧的资助而辛苦经营的草堂已经初具规模；饱经离乡背井的苦楚、备尝颠沛流离的艰虞的诗人，终于获得了一个暂时安居的栖身之所。时值初夏，浣花溪畔，江流曲折，水木清华，一派恬静幽雅的田园景象。诗人拈来《江村》诗题，放笔咏怀，愉悦之情是可以想见的。\n\n　　本诗首联第二句“事事幽”三字，是全诗关紧的话，提挈一篇旨意。中间四句，紧紧贴住“事事幽”，一路叙下。梁间燕子，时来时去，自由而自在；江上白鸥，忽远忽近，相伴而相随。从诗人眼里看来，燕子也罢，鸥鸟也罢，都有一种忘机不疑、乐群适性的意趣。物情如此幽静，人事的幽趣尤其使诗人惬心快意：老妻画纸为棋局的痴情憨态，望而可亲；稚子敲针做钓钩的天真无邪，弥觉可爱。棋局最宜消夏，清江正好垂钓，村居乐事，件件如意。经历长期离乱之后，重新获得家室儿女之乐，诗人怎么不感到欣喜和满足呢？结句“但有故人供禄米，微躯此外更何求”，虽然表面上是喜幸之词，而骨子里正包藏着不少悲苦之情。曰“但有”，就不能保证必有；曰“更何求”，正说明已有所求。杜甫确实没有忘记，自己眼前优游闲适的生活，是建筑在“故人供禄米”的基础之上的。这是一个十分敏感的压痛点。一旦分禄赐米发生了问题，一切就都谈不到了。所以，我们无妨说，这结末两句，与其说是幸词，倒毋宁说是苦情。艰窭贫困、依人为活的一代诗宗，在暂得栖息，杜甫能安居的同时，便吐露这样悲酸的话语，实在是对封建统治阶级摧残人才的强烈控诉。\n\n　　中联四句，从物态人情方面，写足了江村幽事，然后，在结句上，用“此外更何求”一句，关合“事事幽”，收足了一篇主题，最为简净，最为稳当。\n\n　　《江村》一诗，在艺术处理上，也有独特之处：\n\n　　一，是复字不犯复。此诗首联的两句中，“江”字、“村”字皆两见。照一般做律诗的规矩，颔、颈两联同一联中忌有复字，首尾两联散行的句子，要求虽不那么严格，但也应该尽可能避复字。现在用一对复字，就有一种轻快俊逸的感觉，并不觉得是犯复了。这情况，很象律句中的拗救，拗句就要用拗句来救正，复字也要用复字来弥补。况且，第二句又安下了另外两个叠字“事事”，这样一来，头两句诗在读起来的时候，就完全没有枝撑之感了。\n\n　　二，是全诗前后啮合，照应紧凑。“梁上燕”属“村”，“水中鸥”属“江”：“棋局”正顶“长夏”，“钓钩”又暗寓“清江”。颔联“自去自来梁上燕，相亲相近水中鸥”，两“自”字，两“相”字，当句自对：“去”“来”与“亲”“近”又上下句为对。自对而又互对，读起来轻快流荡。颈联的“画”字、“敲”字，字皆现成。且两句皆用朴直的语气，最能表达夫妻投老，相敬弥笃，稚子痴顽，不隔贤愚的意境。\n\n　　三，是结句，忽转凄婉，很有杜甫咏怀诗的特色。杜甫有两句诗自道其做诗的甘苦，说是“愁极本凭诗遣兴，诗成吟咏转凄凉”（《至后》）。此诗本是写闲适心境，但他写着写着，最后结末的地方，也不免吐露落寞不欢之情，使人有怅怅之感。杜甫很多登临即兴感怀的诗篇，几乎都是如此。前人谓杜诗“沉郁”，其契机恐怕就在此处。', poem_tags = '愉悦,夏天,田园' WHERE poem_title = '江村' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '注释 古代“榆关”是范围广泛的军事防区概念，南至海、北至山，东至山海关，西北抵青龙都山。隋唐时期，榆关作为中原汉王朝防御辽东高句丽入侵的重要的军事重地，设关扎营，屯集大批兵马。本诗作者是唐人，所用地名也是唐代的。 漠北历史上是匈奴、突厥等北方游牧民族的势力范围。把榆关搬到漠北的发明家是现代某粉。', poem_appreciation = '这首诗描写了汉武帝时，大将军卫青在漠北以武钢车合围单于，从此漠南无王庭的一战。\n\n　　结合史记的一段记载：“而适值大将军军出塞千余里，见单于兵陈而待，于是大将军令武刚车自环为营，而纵五千骑往当匈奴。匈奴亦纵可万骑。会日且入，大风起，沙砾击面，两军不相见，汉益纵左右翼绕单于。单于视汉兵多，而士马尚强，战而匈奴不利，薄莫，单于遂乘壮骑可数百，直冒汉围西北驰去。”（《卫将军骠骑列传》 ）\n\n　　事件：“大将军出战” 漠北决战，大将军卫青率五万骑兵于定襄出塞千余里，深入漠北。\n\n　　环境：“白日暗榆关” 会日且入，大风起，沙砾击面，两军不相见。\n\n　　战法：“三面黄金甲” 大将军令武刚车自环为营合围单于，趁风起时反击。\n\n　　战果：“单于破胆还” 单于遂乘壮骑可数百，直冒汉围西北逃跑而去。', poem_tags = '边塞,战争,组诗' WHERE poem_title = '从军行二首·其一' AND poem_author = '王昌龄';
UPDATE edu_poem SET poem_translation = '谁说黄河宽又广？一片苇筏就能航。谁说宋国很遥远？踮起脚尖就能望见。\n谁说黄河广又宽？难以容纳小木船。谁说宋国很遥远？一个早晨就能到达。', poem_notes = '河：黄河。\n苇：用芦苇编的筏子。杭：通“航”。\n跂（qǐ）：古通“企”，踮起脚尖。予：而。一说我。\n曾：乃，竟。刀：通“舠（dāo）”，小船。曾不容刀，意为黄河窄，竟容不下一条小船。\n崇朝（zhāo）：终朝，自旦至食时。形容时间之短。', poem_appreciation = '这首诗应该是客居卫国的宋人表达自己还乡心情急迫的思乡诗作。\n\n　　诗文内容简单，诗义明显，需要解释的地方并不多。\n\n　　大家在欣赏这首诗时一定注意到了它的夸张修辞手法，这是中国文学的一种传统。“朝辞白帝彩云间，千里江陵一日还。”、“官仓老鼠大如斗”、还有“壮志饥餐胡虏肉，笑谈渴饮匈奴血！”，这些都是中国人耳熟能详的著名诗句。\n\n　　作为文艺创作，为增强感染力、引起读者强烈的感情共鸣，运用适当的艺术夸大手法和比喻是可行的。但是超越蔓延到其它领域就是可笑又荒唐的，就将沦为说大话、吹牛皮这些现代文明人非常反感和鄙视的陋习。\n\n　　中国式文人多有这种坏毛病，分不清楚文艺和现实的界限，在日常工作生活甚至严肃的科技领域也保留了严重的联想、夸张、模糊的思维特点，这是我们这个民族必须克服的。从某种意义上讲，这也是落后的农业社会的文化特点，在今天这个现代工商文明方兴未艾的时代，这种过时的思维习惯和表达模式是非常不可取的。', poem_tags = '古诗三百首,诗经,思乡,黄河' WHERE poem_title = '国风·卫风·河广' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '誓和君子到白首，玉簪首饰插满头。举止雍容又自得，稳重如山深似河，穿上礼服很适合。谁知德行太秽恶，对她真是无奈何！\n\n服饰鲜明又绚丽，画羽礼服绣山鸡。黑亮头发似云霞，那用装饰假头发。美玉耳饰摇又摆，象牙发钗头上戴，额角白净溢光彩。仿佛尘世降天仙！恍如帝女到人间！\n\n服饰鲜明又绚丽，软软轻纱做外衣。罩上绉纱细葛衫，凉爽内衣夏日宜。明眸善昧眉秀长，容貌艳丽额宽广。仪容妖冶又妩媚，倾城倾国姿色美！', poem_notes = '君子：指卫宣公。　偕老：夫妻相亲相爱、白头到老。　副：妇人的一种首饰。　笄（音jī）：簪。　六珈：笄饰，用玉做成，垂珠有六颗。\n委委佗佗（音yí），如山如河：一说举止雍容华贵、落落大方，象山一样稳重、似河一样深沉。一说体态轻盈、步履袅娜，如山一般蜿蜒，同河一般曲折。佗同“蛇”、“迤”，或音tuó。　象服：是镶有珠宝绘有花纹的礼服。　宜：合身。\n子：指宣姜。　淑：善。　云：句首发语词。　如之何：奈之何。\n玼（音此）：花纹绚烂。　翟（dí）：绣着山鸡彩羽的象服。\n鬒（音诊）：黑发。　髢（音敌）：假发。\n瑱（音tiàn）：冠冕上垂在两耳旁的玉。　象：象牙。　挮（音替）：剃发针，发钗一类的首饰。一说可用于搔头。　扬：额。　且：助词，无实义。　皙（音xī）：白净。\n胡：何，怎么。　然：这样。　而：如、象。\n瑳（音搓）：玉色鲜明洁白。展：古代后妃或命妇的一种礼服，或曰古代夏天穿的一种纱衣。\n絺（音吃）：细葛布。　绁袢（xiè pàn）：夏天穿的亵衣、内衣，白色。\n清：指眼神清秀。　扬：指眉宇宽广。　颜：额。引申为面容、脸色。\n展：诚，的确。　媛：美女。', poem_appreciation = '《毛诗序》云：“《君子偕老》，刺卫夫人也。夫人淫乱，失事君子之道，故陈人君之德，服饰之盛，宜与君子偕老也。”孔疏云：“毛以为由夫人失事君子之道，故陈别有小君内有贞顺之德，外有服饰之盛，德称其服宜与君子偕老者，刺今夫人有淫泆之行，不能与君子偕老。”他们认为此诗所写的服饰仪容之美属于理想的“小君”（国君之妻）。而朱熹《诗集传》则说：“言夫人当与君子偕老，故其服饰之盛如此，而雍容自得，安重宽广，又有以宜其象服。今宣姜之不善乃如此，虽有是服，亦将如之何哉！言不称也。”他以为服饰仪容之美乃是反衬宣姜人品行为之丑。在这点上今之学者又多从朱熹之说。\n\n　　全诗三章，首章七句，次章九句，末章八句，错落有致。首章揭出通篇纲领，章法巧妙。宣姜本是卫宣公之子伋的未婚妻，不幸被宣公霸占，后来又与庶子顽私通，劣迹斑斑。“君子偕老”一句基此而来，起调突兀如当头棒喝，寓意深婉，褒贬自明。“副笄六珈；委委佗佗，如山如河，象服是宜”四句造语奇特，叙服饰与叙仪容相交叉，辞藻工美，极力渲染宣姜来嫁时服饰的鲜艳绚丽，仪容的雍容华贵。末二句“子之不淑，云如之何”，逗露讥刺，全诗惟此二句是刺意，其他均是赞叹称美之辞，但此二句与“君子偕老”一句遥相呼应，暗自缀合，含蓄蕴藉，藏而不露。\n\n　　次章与末章用赋法反覆咏叹宣姜服饰、容貌之美。次章起始“玼兮玼兮”六句与末章起始“瑳兮瑳兮”四句复说服饰之盛，次章“扬且之皙也”三句与末章“子之清扬”四句是复说容貌之美。“胡然而天也！胡然而帝也！”二句神光离合，仿佛天仙帝女降临尘寰，无怪乎姚际恒《诗经通论》称此诗为宋玉《神女赋》、曹植《洛神赋》之滥觞，并谓“‘山河’、‘天帝’，广揽遐观，惊心动魄，有非言辞可释之妙”。“展如之人兮，邦之媛也！”二句巧于措辞，深意愈出，余音袅袅，意味无穷。这两章造句齐整，意象迷离，所以陈继揆《读风臆补》说：“后两章逸艳绝伦，若除去‘也’字，都作七字读，即为七言之祖。”\n\n　　全诗反覆铺陈咏叹宣姜服饰容貌之盛美，是为了反衬其内心世界的丑恶与行为的污秽，铺陈处用力多，反衬处立意妙，对比鲜明，辛辣幽默，具有强烈的讽刺效果。', poem_tags = '诗经,写人' WHERE poem_title = '国风·鄘风·君子偕老' AND poem_author = '佚名';
UPDATE edu_poem SET poem_tags = '节日,新年,抒情' WHERE poem_title = '新年' AND poem_author = '无可';
UPDATE edu_poem SET poem_translation = '丈夫服役去远方，服役长短难估量，不知到了啥地方？鸡儿已经进了窝，太阳也向西边落，牛羊成群下山坡。丈夫服役在远方，教我怎不把他想？\n丈夫服役去远方，每日每月恨日长，不知何时聚一堂？鸡儿纷纷上了架，太阳渐渐也西下，牛羊下坡回到家。丈夫服役在远方，但愿不会饿肚肠！', poem_notes = '于：往。役：服劳役。于役，到外面服役。\n期：指服役的期限。\n曷（hé）：何时。至：归家。\n埘（shí ）：鸡舍。墙壁上挖洞做成。\n如之何勿思：如何不思。如之：犹说“对此”。\n不日不月：没法用日月来计算时间。\n有（yòu）佸（huó）：相会，来到。\n桀：鸡栖木。一说指用木头搭成的鸡窝。\n括：来到。音、义同“佸”。\n苟：诚，犹如实。', poem_appreciation = '这是一首很朴素的诗。两章相重，只有很少的变化。每章开头，是女主人公用简单的语言说出的内心独白。稍可注意的是“不知其期”这一句（第二章的“不日不月”也是同样意思，有不少人将它解释为时间漫长，是不确切的）。等待亲人归来，最令人心烦的就是这种归期不定的情形，好像每天都有希望，结果每天都是失望。如果只是外出时间长但归期是确定的，反而不是这样烦人。正是在这样的心理中，女主人公带着叹息地问出了“曷至哉”：到底什么时候才能回来呢？\n\n　　这下面的一节有一种天然的妙趣。诗中不再正面写妻子思念丈夫的哀愁乃至愤怨，而是淡淡地描绘出一幅乡村晚景的画面：在夕阳余晖下，鸡儿归了窠，牛羊从村落外的山坡上缓缓地走下来。这里的笔触好像完全是不用力的，甚至连一个形容词都没有，不像后代的文人辞章总是想刻画得深入、警醒，恐怕读者不注意。然而这画面却很感动人，因为它是有情绪的。读者好像能看到那凝视着鸡儿、牛儿、羊儿，凝视着村落外蜿蜒沿伸、通向远方的道路的妇人，是她在感动读者。这之后再接上“君子于役，如之何勿思”，读者分明地感受到女主人公的愁思浓重了许多。倘试把中间“鸡栖于埘，日之夕矣，羊牛下来”三句抽掉，将最后两句直接接继在“曷至哉”之后，感觉会完全不同。这里有抒情表达的节奏问题——节奏太快，没有起伏，抒情效果出不来；同时，这画面本身有其特别的情味。\n\n　　熟悉农村生活的人经常看到这样的晚景。农作的日子是辛劳的，但到了黄昏来临之际，一切即归于平和、安谧和恬美。牛羊家禽回到圈栏，炊烟袅袅地升起，灯火温暖地跳动起来，农人和他的妻儿们聊着闲散的话题。黄昏，在大地上出现白天未有的温顺，农人以生命珍爱着的东西向他们身边归聚，这便是古老的农耕社会中最平常也是最富于生活情趣的时刻。可是在这诗里，那位妻子的丈夫却犹在远方，她的生活的缺损在这一刻也就显得最为强烈了，所以她如此怅惘地期待着。\n\n　　这诗的两章几乎完全是重复的，这是歌谣最常用的手段——以重叠的章句来推进抒情的感动。但第二章的末句也是全诗的末句，却是完全变化了的。它把妻子的盼待转变为对丈夫的牵挂和祝愿：不归来也就罢了，但愿他在外不要忍饥受渴吧。这也是最平常的话，但其中包含的感情却又是那样善良和深挚。\n\n　　这是古老的歌谣，它以不加修饰的语言直接地触动了人心中最易感的地方。它的天然之妙，在后世已是难以重复的了。', poem_tags = '诗经,闺怨,战争,民谣' WHERE poem_title = '君子于役' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '白雪皑皑，满眼银色世界。就在这银色的世界里，一树寒梅点缀其间。那覆雪悬冰的梅枝，晶莹剔透，别在枝头的梅花，丰润姣洁。就是从这傲雪而放的梅花，人们才知道了春天就要到来的消息。梅花含苞初绽，娇美可怜，芳气袭人，就像庭院里刚刚出浴，换了新妆的美人。\n大自然可能也有偏爱，她怜爱这娇艳的梅花，作为陪衬，才让月光这样皎洁清澈，玲珑剔透，洒满大地。让我们举杯开怀畅饮吧，值此花好月圆雪白的良宵，品酒赏梅，一醉方休。要知道，群花竞艳，谁也逊色于梅花呀。', poem_notes = '渔家傲：词牌名。《词谱》卷十四云：“此调始自晏殊，因词有‘神仙一曲渔家傲’句，取以为名。”双调六十二字。\n春信：春天的消息。琼枝：此指覆雪悬冰的梅枝。梅枝著雪，白如玉枝，故称。\n点缀：稍加装饰衬托，使事物更加美好。琼枝：像美玉制成的枝条。腻：这里形容清瘦的梅枝着雪后变得粗肥光洁。\n香脸：指女人敷着胭脂散发香味的面颊。此处用以比拟半开着的散发芳香的梅花。旖旎（yǐ nǐ）：柔美貌。\n玉人：美人。此处用以比梅花。\n造化：天地，大自然。\n玲珑：明亮貌。\n金尊：珍贵的酒杯。尊：同“樽”。沈：同“沉”。绿蚁：本来指古代酿酒时上面浮的碎的屑沫子，也叫浮蚁，后来衍为酒的代称。', poem_appreciation = '这是一首咏梅词。上片写寒梅初放。何逊《扬州早梅》：“兔园标物序，惊时最是梅。衔霜当露发，映雪凝寒开。”梅花，她开于冬春之交，最能惊醒人们的时间意识，使人们萌生新的希望。所以被认为是报春之花。因为梅花斗雪迎寒而开，诗人咏梅，又总以冰雪作为空间背景。庾信《咏梅花》诗：“常年腊月半，已觉梅花阑。不信今春晚，俱来雪里看。树动悬冰落，枝高出手寒……”这里，“琼枝”就指覆雪悬冰的梅枝。半放的寒梅点缀着它，愈显得光明润泽。词人接着用“犹抱琵琶半遮面”的美女形容将开未开之梅的轻盈娇美，用玉人浴出形容梅的玉洁冰清，明艳出群：即物即人，梅已和人融成了一片。\n\n　　下片转用侧面烘托。梅花偏宜月下观赏，造物有意，故教月色玲珑透剔，使暗香浮动，疏影横斜。值此良宵，且备金樽、绿蚁，花前共一醉。绿蚁，酒面的浮沫。白居易《问刘十九》：“绿蚁新醅酒，红泥小火炉。”《历代诗话》引《古隽考略》：“绿蚁，酒之美者，泛泛有浮花，其色绿。”\n\n　　这首词，银色的月光，金色的酒樽，淡绿的酒，晶莹的梅织成了一幅画，写得如梦如幻，空灵优美。与前人的咏梅诗词相比，此词艺术上有所创新。词人抓住寒梅主要特征，用比喻、拟人、想象等多种手法，从正面刻画梅花形象。在对寒梅作了总体勾勒之后，又以生花妙笔点染其形象美和神态美。同时，此时做到了移情于物，以景传情，意中有景，景中寄意，体现了李词的特色。', poem_tags = '咏物,梅花' WHERE poem_title = '渔家傲·雪里已知春信至' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '母别子，子别母，白天的阳光似乎都因为悲伤而失去了光彩，哭声中无限凄苦。\n一家人住在关西长安，丈夫身居大将军的高位，去年立了战功，又被加封了爵土。\n还得到了赏赐的金钱二百万，于是便在洛阳娶了如花似玉的新妇。\n新妇来了不满足，就要丈夫抛旧妇；她是他掌上的莲花，我却是他们眼中的钉子。\n喜新厌旧是俗世的常情，这本来也不足为悲，我就要收拾行装，无奈地离开。但悲伤的是，留在丈夫家的，还有两个亲生的小孩。\n一个才刚刚会扶着床沿走路，一个才刚刚能够坐起来。坐着的孩子啼哭，会走路的孩子牵着我的衣服。\n你们夫妇新欢燕尔，却让我们母子生离死别，从此不得相见。\n此时此刻，我的心有诉不出的悲苦，人的薄情啊，还不如林中的乌鹊，母鸟不离开小雏，雄鸟总在它们身旁呵护。\n此情此景，倒象是后园的桃树，曾经遮蔽着花房的花瓣已经随风落去，幼小的果实还将挂在梢头经历霜雪雨露。\n新人新人你听我说，洛阳有无数的红楼美女。 \n但愿将军将来又立了什么功勋，再娶一个比你更娇艳的新妇吧。', poem_notes = '①乌与鹊：林中自由自在的鸟儿。\n②雏：小鸟。', poem_tags = '母亲,离别' WHERE poem_title = '母别子' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '秋菊花盛正鲜艳，含露润泽采花英。\n菊泡酒中味更美，避俗之情更深浓。\n一挥而尽杯中酒，再执酒壶注杯中。\n日落众生皆息止，归鸟向林欢快鸣。\n纵情欢歌东窗下，姑且逍遥度此生。', poem_notes = '这首诗主要写赏菊与饮酒，诗人完全沉醉其中，忘却了尘世，摆脱了忧愁，逍遥闲适，自得其乐。\n裛（yì意）：通“浥”，沾湿。掇（duo多）：采摘。英：花。\n泛：浮。意即以菊花泡酒中。此：指菊花。忘忧物：指酒。远：这里作动词，使远。遗世情：遗弃世俗的情怀，即隐居。\n壶自倾：谓由酒壶中再往杯中注酒。\n群动：各类活动的生物。息：歇息，止息。趋：归向。\n啸傲：谓言动自在，无拘无束。轩：窗。得此生：指得到人生之真意，即悠闲适意的生活。', poem_appreciation = '此诗写对菊饮酒的悠然自得，实际蕴藏着深沉的感伤。\n\n　　秋天是菊花的季节。在百花早已凋谢的秋日，惟独菊花不畏严霜，粲然独放，表现出坚贞高洁的品格。惟其如此，作者非常爱菊，诗中屡次写到，而且常常把它同松联系在一起，如《和郭主簿》：“芳菊开林耀，青松冠岩列。怀此贞秀姿，卓为霜下杰。”《归去来辞》：“三径就荒，松菊犹存。”此诗首句“秋菊有佳色”，亦是对菊的倾心赞美。“有佳色”三字极朴素，“佳”字还暗点出众芳凋零，惟菊有傲霜之色，如果换成其他秾丽字眼，比如“丽”、“粲”、“绚”之类，反倒恶俗不堪。前人称此句“洗尽古今尘俗气”（宋李公焕《笺注陶渊明集》引艮斋语），并非虚誉“裛露掇其英”，带露摘花，色香俱佳。采菊是为了服食，菊可延年益寿。作者《九日闲居》就有“酒能祛百虑，菊解制颓龄”之旬。曹丕《与钟繇九日送菊书》云：“辅体延年，莫斯（指菊）之贵。谨奉一束，以助彭祖之术。”可见服食菊花，是六朝的风气。屈原《离骚》说：“朝饮木兰之坠露兮，夕餐秋菊之落英。”故服食菊花不仅在强身，还有志趣高洁的喻意，而通篇之高远寓意，亦皆由菊引发。\n\n　　秋菊佳色，助人酒兴，作者不觉一杯接着一杯，独自饮起酒来。《诗经·邶风·柏舟》“微我无酒，以遨以游”，毛《传》：“非我无酒可以遨游忘忧也。”又曹操《短歌行》：“何以解忧，惟有杜康。”（相传杜康是开始造酒的人，这里用作酒的代称。）如果心中无忧，就不会想到“忘忧”，这里透出了作者胸中的郁愤之情。“遗世”，遗弃、超脱俗世，主要是指不去做官。明黄文焕《陶诗析义》说：“遗世之情，我原自远，对酒对菊，又加远一倍矣。”分析甚确。不过，结合“忘忧”看，这里的“遗世”，也含有愤激的成分。因为渊明本来很想做一番“大济于苍生”（《感士不遇赋》）的事业，只是后来在官场中亲眼看到当时政治黑暗，这才决计归隐的。\n\n　　后面六句具体叙写饮酒的乐趣和感想，描绘出一个宁静美好的境界，是对“遗世情”的形象写照。这里写的是独醉。他既没有孔融“坐上客常满，尊中酒不空”（《后汉书·郑孔荀列传》载孔融语）那样的豪华气派，也不像竹林名士那样“纵酒昏酣”，而是一个人对菊自酌。独饮本来容易使人感到寂寞，但五、六两句各着一“虽”字、“自”字，就洗去孤寂冷落之感，“自”字显得那壶儿似也颇解人意，为诗人手中的酒杯殷勤地添注不已。“倾”字不仅指向杯中斟酒，还有酒壶倾尽之意，见出他自酌的时间之长，兴致之高，饮酒之多。所以从这两句到“日入”两句，不仅描写的方面不同，还包含着时间的推移。随着饮酒增多，作者的感触也多了起来。\n\n　　再下二句，“日入群动息”是总论，“归鸟趋林鸣”是于群动中特取一物以证之；也可以说，因见归鸟趋林，所以悟出日入之时正是群动止息之际。“趋”是动态，“鸣”是声音，但惟有在特别空旷静寂的环境中，才能更加显出飞鸟趋林，更加清晰地听到鸟儿的声音，这是以动写静、以声写寂的表现手法。而环境的宁静优美，又衬托出作者的闲适心情。这二句是写景，同时也是渊明此时志趣的寄托。渊明诗中写到鸟的很多，尤其归隐以后，常常借归鸟寓意。除此诗外，他如“翼翼归鸟，相林徘徊。岂思天路，欣及归栖”（《归鸟》），“翼翼归鸟，戢羽寒条。……矰缴奚施，已卷（倦）安劳”（《归鸟》），“羁鸟恋旧林，池鱼思故渊”（《归园田居》），还有“云无心而出蚰，鸟倦飞而知还”（《归去来辞》），“山气日夕佳，飞鸟相与还”（《饮酒·结庐在人境》），“众鸟欣有托，吾亦爱吾庐”（《读山海经》），等等。这些诗中的归鸟，都是作者的艺术化身。趋林之鸟本来是无意中所见，但它却唤起了作者的感慨深思：“群动”皆有止息之时，飞鸟日落犹知还巢，人生何独不然？鸟儿始飞终归的过程，正好像是作者由出仕到归隐的生活历程。这里既是兴，也是比，又是即目写景，三者浑然一体，使人不觉，表现手法非常高妙。\n\n　　末尾写所以归隐之故，表达了隐居终身的决心。“啸”是撮口发出长而清越的声音，是古人抒发感情的一种方式。“啸傲”谓歌咏自得，无拘无束。《饮酒》第五首《饮酒·结庐在人境》有“采菊东篱下，悠然见南山”，知东轩即在此东篱内，东篱之下种有菊花。对菊饮酒，啸歌采菊，自是人生之至乐。“得此生”是说不为外物所役使，按着自己的心意自由地生活，也就是苏东坡所说的“靖节以无事自适为得此生，则凡役于物者，非失此生耶？”（《东坡题跋·题渊明诗》）“得此生”和“失此生”实指归隐和做官。啸傲东轩，是隐居悠闲之乐的形象描绘，它是赞美，是庆幸，也是意愿。然而，“聊复”（姑且算是）一词，又给这一切罩上了一层无可奈何的色彩，它上承“忘忧”、“遗世”，仍然表现出壮志难酬的憾恨，并非一味悠然陶然。', poem_tags = '赏花,菊花,饮酒,感伤' WHERE poem_title = '饮酒·其四' AND poem_author = '陶渊明';
UPDATE edu_poem SET poem_translation = '刚满十五岁的少年就出去打仗，到了八十岁才回来。\n路遇一个乡下的邻居，问：“我家里还有什么人？”\n“你家那个地方现在已是松树柏树林中的一片坟墓。”\n走到家门前看见野兔从狗洞里进出，野鸡在屋脊上飞来飞去，\n院子里长着野生的谷子，野生的葵菜环绕着井台。\n用捣掉壳的野谷来做饭，摘下葵叶来煮汤。\n汤和饭一会儿都做好了，却不知送给谁吃。\n走出大门向着东方张望，老泪纵横，洒落在征衣上。', poem_notes = '始：才；归：回家。\n道逢：在路上遇到；道：路途上。\n阿（ē）：语气词，没有实在意义。\n君：你，表示尊敬的称呼；遥看：远远地望去。\n松柏（bǎi）：松树、柏树。\n冢累累：坟墓一个连着一个。冢（zhǒng），坟墓、高坟。累累（léiléi），与“垒垒”通，连续不断的样子。\n狗窦：给狗出入的墙洞。窦（dòu），洞穴。\n雉（zhì）：野鸡。\n中庭：屋前的院子。\n旅：旅生，植物未经播种而野生；\n旅葵（kuí）：葵菜，嫩叶可以吃。\n舂（chōng）：把东西放在石臼或乳钵里捣掉谷子的皮壳或捣碎。\n羹（gēng）：用菜叶做的汤。\n一时：一会儿就。\n贻（yí）：送，赠送。\n看：一说为“望”。\n沾：渗入。', poem_tags = '乐府,民歌,战争,苦难' WHERE poem_title = '十五从军行 / 十五从军征' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '在那开满了红花的树上，欢跃的群莺在不停的鸣叫，西湖岸边已长满了青草，成群白鹭在平静的湖面上翻飞。\n暖风晴和的天气，人的心情也很好，趁着夕阳余晖，伴着阵阵的鼓声箫韵，人们划着一只只船儿尽兴而归。', poem_notes = '湖：指杭州西湖。\n红树：指开满红花的树。\n乱莺啼：指到处都是黄莺的啼叫。\n长：茂盛。\n人意：游人的心情。\n箫鼓：吹箫击鼓，指游船上奏着音乐。\n几船归：意为有许多船归去。', poem_tags = '古诗三百首,春游,西湖,写景' WHERE poem_title = '湖上' AND poem_author = '徐元杰';
UPDATE edu_poem SET poem_translation = '微微小汗湿透了碧色的细绢，明日端午节用芳兰草沐浴。流香酒般的浴水、油腻布满大晴的江面。\n五彩花线轻轻地缠在红玉色手臂上，小小的符篆（或赤灵符）斜挂在耳下的黑色发髻上。与朝云同过端午节，天长地久，白头偕老。', poem_notes = '浣溪沙：唐教坊曲，后用为词牌名。分平仄两体，字数以四十二字居多，还有四十四字和四十六字两种。\n端午：民间节日，在旧历五月初五。\n碧纨（wàn）：绿色薄绸。\n芳兰：芳香的兰花。端午节有浴兰汤的风俗。\n流香涨腻：指女子梳洗时，用剩下的香粉胭脂随水流入河中。杜牧《阿房宫赋》：“弃脂水也”。\n“小符”句：这句指妇女们在发髻上挂着祛邪驱鬼、保佑平安的符录。云鬟（huán）：女子的发髻。', poem_appreciation = '上片，预示端午节日，将开展浴兰活动，气氛十分浓郁。端午，处于初夏季节。穿着自然华丽，以衬托参与者的身份。于朝云来说，最好是绿色细绢——“碧纨”，正好与她的雅静性格相符。天气稍热，易出“轻汗”，“微透”着“碧纨”。“透”字用得贴切，将半明半暗的肤体朦胧美衬托出来了。“明朝端午浴芳兰”，显得有愉悦的审美性。它不仅体现了朝云由芳体而及兰心的纯洁高贵的情操美，而且反映了浴兰令节俗的淳朴纯真美。朝云浴处，余香犹存。沐芳浴兰，遍及社会。参与者人山人海，气氛热烈，正如词人词中所写：“流香涨腻满晴川”。这正是古老节日文化发扬光大的表现。\n\n　　下片，写词人偕朝云参与具体的端午节俗活动。词人着重写了两项端午节俗健身活动。其一，“彩线轻缠红玉臂”，“以五彩丝系臂”。它辟邪驱鬼，使朝云“玉臂”“红”而长命。与用五色花线缠粽子投江以吊屈原之魂有同等意义。其二，“小符斜挂绿云鬟”，以“赤灵符著心前”。它能通神明，使朝云“云鬟”“绿”而身健。与小孩穿老虎腰肚，门上挂蒲剑以辟邪护身有同等意义。词人着重描写缠线、挂符活动，且用对偶句式，为的是“佳人相见一千年”，愿灵验得到应证。真是一语中的，画龙点睛。\n\n　　全词是篇民俗诗，充满了浓郁的古老民俗气息，是研究端午民俗最形象而珍贵的资料。', poem_tags = '端午节,风俗' WHERE poem_title = '浣溪沙·端午' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '浅画黛眉，轻抹胭脂，轻拂过那紫色首饰锦盒又回想起那往日时光回想往日，那戴在发间的牡丹花重的快要把发髻压偏。捻梅浅尝，与你肩并肩同行。\n大病初愈心情总是郁闷难解，身体疲乏无力，精神困顿无法出门。只能移步在小窗下慢慢的做着针线。', poem_notes = '香膏：芳香的脂膏。\n翠云：形容妇女头髮乌黑浓密。\n挼：同“挪”揉搓。\n病起：病愈。\n不禁：抑制不住，不由自主。\n旋移：缓缓。', poem_tags = '抒情,女子,怀人' WHERE poem_title = '浣溪沙·浅画香膏拂紫绵' AND poem_author = '陈克';
UPDATE edu_poem SET poem_translation = '春日踏青郊游，风吹杏花满头。田间路上是谁家少年，青春如花真风流。\n我想以身相许嫁给他，一生一世就此休。纵使他薄情无义抛弃我，也不后悔也不害羞。', poem_notes = '题解：《思帝乡》又名《万斯年曲》，本是唐玄宗时教坊曲名，后用作词牌。单调三十三至三十六字，平韵。此调金奁集载温庭筠韦庄词，注越调（无射商）。该篇押用同一部平韵，韵脚分别是“游”、“头”、“流”、“休”、“羞”。\n陌（mò）：田间东西方向的道路，这里泛指道路，野外的道路。陌上，道路之上。年少：即“少年”，小伙子，青年人。\n足：程度副词，很，非常。风流：风度潇洒，举止飘逸，洒脱放逸，风雅潇洒。足风流，犹云十分风流，够气派、潇洒，够俊俏、多情的。\n妾：古代女子对自己的谦称。拟：是定、准、必的意思，与“打算”的用法不尽相同，打算，想要。与：给，这个介词后面省略了宾语。将身嫁与，把自己嫁给他。\n休：此处指心愿得遂后的罢休，喜悦，欢乐。一生休，一辈子就这样罢了，意思是一生就满足了，这一辈子也就算了，意谓一生有了依托，一生满足。\n纵：纵然，即便。弃：抛弃，弃置。不能羞：意谓不会感到害羞后悔，即也不在乎。“纵被”二句，即使被他无情无义地休弃了，也不后悔 。', poem_appreciation = '这首词不掩饰地流露了女子青春的热情，迫切要求恋爱自由。词意质朴大胆，很近民歌。\n\n　　此词开端之“春日游”三字，表面看来原只是极为简单直接的一句叙述而已，然而却已经为后文所写的感情之秾挚做了很好的准备和渲染。试想“春日”是何等美好的季节，草木之萌发，昆虫之起蛰，一切都表现了一种生命之觉醒与跃动。而“春日“之后更加一游”字”，则此“春游”之人的春心之欲，随春物以共同萌发及跃动从而可知。而春游所见之万紫千红莺飞蝶舞之景象也就从而可想了。其后再加以“杏花吹满头”一句，则外在之春物遂与游春之人更加了一层直接的关系，其感染触发之密切乃竟有及身满头之情势矣。\n\n　　“吹”字虽有花片被风吹落的意思，然而在此一句中却并没有花落春归的哀感，而却表现出一种当繁花开到极盛时，也同时伴随有花片之飞舞的一种更为缤纷盛美的景象。首二句已经为以后的感情之引发，培养和渲染了足够的气势，于是下面才一泻而出毫无假借地写了“陌上谁家年少、足风流”一个上六下三的九字长句，读起来笔力异常饱满。\n\n　　韦庄这首小词虽不必有儒家之修养与楚骚之忠爱的用心，然而其所写的用情之态度与殉身之精神，却确实可以引发读者一种深层的感动与丰美的联想。', poem_tags = '宋词三百首,婉约,春游,写景' WHERE poem_title = '思帝乡·春日游' AND poem_author = '韦庄';
UPDATE edu_poem SET poem_translation = '别梦中隐约来到了谢家，徘徊在小回廊栏杆底下。\n只有天上春月最是多情，还为离人照着庭院落花。', poem_notes = '谢家：泛指闺中女子。晋谢奕之女谢道韫、唐李德裕之妾谢秋娘等皆有盛名，故后人多以“谢家”代闺中女子。\n“小廊”句：指梦中所见景物。回合：回环、回绕。阑：栏杆。\n“多情”句：指梦后所见。\n离人：这里指寻梦人。', poem_appreciation = '以诗代柬，来表达自己心里要说的话，这是古代常有的事。这首题为《寄人》的诗，就是用来代替一封信的。\n\n　　诗的首句写诗人与情人梦中重聚，难舍难离；第二句写依旧是当年环境，往日欢情，表明自己思念之深。第三句写明月有情；第四句写落花有恨。寄希望于对方，含蓄深厚，曲折委婉，情真意真。前两句写入梦的原因与梦中所见的景物，是向对方表明自己思忆之深；后两句写出多情的明月依旧照人，那就更是对这位女子的埋怨之情了。\n\n　　诗是从叙述一个梦境开始的。“谢家”，代指女子的家，盖以东晋才女谢道韫借称其人。大概诗人曾经在女子家里待过，或者在她家里和她见过面。曲径回廊，本来都是当年旧游或定情的地方。因此，诗人在进入梦境以后，就觉得自己飘飘荡荡地进到了她的家里。这里的环境是这样熟悉：院子里四面走廊，那是两人曾经谈过心的地方；曲折的阑干，也像往常一样，似乎还留着自己抚摸过的手迹，可是，眼前廊阑依旧，独不见所思之人。他的梦魂绕遍回廊，倚尽阑干，他失望地徘徊着，追忆着，直到连自己也不知道怎样脱出这种难堪的梦境。崔护《题都城南庄》诗：“人面不知何处去，桃花依旧笑春风。”周邦彦《玉楼春》词：“当时相候赤阑桥，今日独寻黄叶路。”一种物是人非的依恋心情，写得同样动人。然而，“别梦”两句却以梦境出之，则前此旧游，往日欢情，别后相思，都在不言之中，而在梦里也难寻觅所爱之人，那惆怅的情怀就加倍使人难堪了。\n\n　　人是再也找不到了，作者问：那么，还剩下些什么呢？这时候，一轮皎月，正好把它幽冷的清光洒在园子里，地上的片片落花，反射出惨淡的颜色。花是落了，然而曾经映照过枝上芳菲的明月，依然如此多情地临照着，似乎还没有忘记一对爱侣在这里结下的一段恋情呢。这后两句诗就是诗人要告诉她的话。\n\n　　正因为这首诗是“寄人”的。前两句写入梦之由与梦中所见之景，是向对方表明自己思忆之深；后两句写出多情的明月依旧照人，那就更是对这位女子的鱼沉雁杳，有点埋怨了。“花”固然已经落了，然而，春庭的明月还是多情的，诗人言外之意，还是希望彼此一通音问的。\n\n　　这首诗创造的艺术形象，鲜明准确，而又含蓄深厚。诗人善于通过富有典型意义的景物描写，来表达自己深沉曲折的思相感情，运用得十分成功。他只写小廊曲阑、庭前花月，不需要更多语言，却比作者自己直接诉说心头的千言万语更有动人心弦的力量。', poem_tags = '唐诗三百首,月亮,爱情,思念' WHERE poem_title = '寄人' AND poem_author = '张泌';
UPDATE edu_poem SET poem_translation = '花是无知的，月是无聊的，酒也是无法消愁解恨的。把茂盛的桃树砍断，减损他的风景，把吟风咏月诗人讴歌的鹦哥煮熟，做下酒菜。焚烧砚台书籍，捶坏琴撕毁画，销毁所有的文章抹去所有的功名。我荥阳郑家原本就有慕歌家世，乞食风情，只靠教歌度曲，乞食与人，也能自自在在地活下来。\n自己天生的单寒骨相没法改变，头戴席帽身着青衫的瘦弱寒酸相为人所笑。长期居住于破巷之中，住处蓬门秋草，窗户不严挡不住风雨，夜夜伴随孤灯度过。难道老天爷还要封住词人之口，连叹气都不允许吗？疯狂至极，于是取出乌丝栏百幅，细细写出心中凄清之恨。', poem_notes = '沁（qìn）园春：词牌名，又名“寿星明”“洞庭春色”等。双调一百一十四字，平韵。\n夭桃：茂盛的桃树。\n斫（zhuó）：砍。\n煞（shā）：同“杀”，减损。\n佐（zuǒ）：辅助。\n椎（chuí）：捶。\n荥（xing）阳郑：郑板桥的自称，以表对封建礼法的蔑视。“荥阳郑”指郑元和的故事。荥阳郑生本宦家之子，与妓女李娃恋爱，金钱被老鸨设计掏空，靠帮人唱丧歌糊口。后来又沦为乞丐。李娃于心不忍，不忘旧情，予以搭救，帮助他考上功名。唐白行简《李娃传》即叙其事。郑板桥对这个风流韵事，然而近于子虚乌有的元祖十分敬佩，在作品中曾三次提到他。\n风情：旧指男女相爱的情怀。\n骨相：指人的骨骼相貌，旧谓骨相好坏，注定人一生的命运。\n席帽青衫：明清科举时儒生或秀才的服装。\n太瘦生：即太瘦。生，语助词。\n蓬门、破巷：贫者所居。\n箝（qián）：通“钳”，钳制。\n乌丝：全称乌丝栏，一种专供书写用，带黑格的绢素或纸张。', poem_tags = '豪放,抒怀,愤恨' WHERE poem_title = '沁园春·恨' AND poem_author = '郑燮';
UPDATE edu_poem SET poem_translation = '在长安古道上骑着瘦马缓缓行走，高高的柳树秋蝉乱嘶啼。夕阳照射下，秋风在原野上劲吹，我举目远望，看见天幕从四方垂下。\n　　归去的云一去杳无踪迹，往日的期待在哪里？冶游饮宴的兴致已衰减，过去的酒友也都寥落无几，现在的我已不像以前年轻的时候了。', poem_notes = '马迟迟：马行缓慢的样子。\n乱蝉嘶：一作“乱蝉栖”。\n鸟：又作“岛”，指河流中的洲岛。\n原上：乐游原上，在长安西南。\n目断：极目望到尽头。四天垂：天的四周夜幕降临。\n归云：飘逝的云彩。这里比喻往昔经历而现在不可复返的一切。此句一作“归去一云无踪迹”。\n前期：以前的期约。既可指往日的志愿心期又可指旧日的欢乐约期。\n狎兴：游乐的兴致。狎：亲昵而轻佻。\n酒徒：酒友。萧索：零散，稀少，冷落，寂寞。\n少年时：又作“去年时”。', poem_appreciation = '一般人论及柳永词者，往往多着重于他在长调慢词方面的拓展，其实他在小令方面的成就，也是极可注意的。叶嘉莹在《论柳永词》一文中，曾经谈到柳词在意境方面的拓展，以为唐五代小令中所叙写的“大多不过是闺阁园亭伤离怨别的一种‘春女善怀’的情意”，而柳词中一些“自抒情意的佳作”，则写出了“一种‘秋士易感’的哀伤”。这种特色，在他的一些长调的佳作，如《八声甘州》《曲玉管》《雪梅香》诸词中，都曾经有很明白的表现。然而柳词之拓展，却实在不仅限于其长调慢词而已，就是他的短小的令词，在内容意境方面也同样有一些可注意的开拓。就如这一首《少年游》小词，就是柳永将其“秋士易感”的失志之悲，写入了令词的一篇代表作。\n\n　　柳永之所以往往怀有一种“失志”的悲哀，盖由于其一方面既因家世之影响，而曾经怀有用世之志意，而另一方面则又因天性之禀赋而爱好浪漫的生活。当他早年落第之时，虽然还可以藉着“浅斟低唱”来加以排遣，而当他年华老去之后，则对于冶游之事既已失去了当年的意兴，于是遂在志意的落空之后，又增加了一种感情也失去了寄托之所的悲慨。而最能传达出他的双重悲慨的便是这首《少年游》小词。\n\n　　这首小词，与柳永的一些慢词一样，所写的也是秋天的景色，然而在情调与声音方面，却有着很大的不同。在这首小词中，柳永既失去了那一份高远飞扬的意兴，也消逝了那一份迷恋眷念的感情，全词所弥漫的只是一片低沉萧瑟的色调和声音。从这种表现来判断，这首词很可能是柳永的晚期之作。开端的“长安”可以有写实与托喻两重含义。先就写实而言，则柳永确曾到过陕西的长安，他曾写有另一首《少年游》，有“参差烟树灞陵桥”之句，足可为证。再就托喻言，“长安”原为中国历史上著名古都，前代诗人往往以“长安”借指为首都所在之地，而长安道上来往的车马，便也往往被借指为对于名利禄位的争逐。不过柳永此词在“马”字之下接上“迟迟”两字，这便与前面的“长安道”所可能引起的争逐的联想，形成了一种强烈的反衬。至于在“道”字上著以一“古”字，则又可以使人联想及在此长安道上的车马之奔驰，原是自古而然，因而遂又可产生无限沧桑之感。总之，“长安古道马迟迟”一句意蕴深远，既表现了词人对争逐之事早已灰心淡薄，也表现了一种对今古沧桑的若有深慨的思致。\n\n　　下面的“高柳乱蝉嘶”一句，有的本子或作“乱蝉栖”，但蝉之为体甚小，蝉之栖树决不同于鸦之栖树之明显可见，而蝉之特色则在于善于嘶鸣，故私意以为当作“乱蝉嘶”为是。而且秋蝉之嘶鸣更独具一种凄凉之致。《古诗十九首》云“秋蝉鸣树间”，曹植《赠白马王彪》去“寒蝉鸣我侧”，便都表现有一种时节变易、萧瑟惊秋的哀感。柳永则更在蝉嘶之上，还加上了一个“乱”字，如此便不仅表现了蝉声的缭乱众多，也表现了被蝉嘶而引起哀感的词人心情的缭乱纷纭。至于“高柳”二字，则一则表示了蝉嘶所在之地，再则又以“高”字表现了“柳”之零落萧疏，是其低垂的浓枝密叶已凋零，所以乃弥见其树之“高”也。\n\n　　下面的“夕阳鸟外，秋风原上，目断四天垂”三句，写词人在秋日郊野所见之萧瑟凄凉的景象，“夕阳鸟外”一句，也有的本子作“岛外”，非是。长安道上不可能有“岛”。至于作“鸟外”，则足可以表现郊原之寥阔无垠。昔杜牧有诗云“长空澹澹孤鸟没”，飞鸟之隐没在长空之外，而夕阳之隐没更在飞鸟之外，故曰“夕阳鸟外”也。值此日暮之时，郊原上寒风四起，故又曰“秋风原上”，此景此情，读之如在眼前。然则在此情景之中，此一失志落拓之词人，难有所归往之处。故继之乃曰“目断四天垂”，则天之苍苍，野之茫茫，词人乃双目望断而终无一可供投止之所矣。以上前半阕是词人自写其当时之飘零落拓，望断念绝，全自外界之景象着笔，而感慨极深。\n\n　　下阕，开始写对于过去的追思，则一切希望与欢乐也已经不可复得。首先“归云一去无踪迹”一句，便已经是对一切消逝不可复返之事物的一种象喻。盖天下之事物其变化无常一逝不返者，实以“云”之形象最为明显。故陶渊明《咏贫士》第一首便曾以“云”为象喻，而有“暖暖空中灭，何时见余晖”之言，白居易《花非花》词，亦有“去似朝云无觅处”之语，而柳永此句“归云一去无踪迹”七字，所表现的长逝不返的形象，也有同样的效果。不过其所托喻的主旨则各有不同。关于陶渊明与白居易的象喻，此处不暇详论。至于柳永词此句之喻托，则其口气实与下句之“何处是前期”直接贯注。所谓“前期”者，可以有两种提示：一则是指旧日之志意心期，一则可以指旧日的欢爱约期。总之”期”字乃是一种愿望和期待，对于柳永而言，他可以说正是一个在两种期待和愿望上，都已经同样落空了的不幸人物。\n\n　　于是下面三句乃直写自己当时的寂寥落寞，曰“狎兴生疏，酒徒萧索，不似少年时”。早年失意之时的“幸有意中人，堪寻访”的狎玩之意兴，既已经冷落荒疏，而当日与他在一起歌酒流连的“狂朋怪侣”也都已老大凋零。志意无成，年华一往，于是便只剩下了“不似少年时”的悲哀与叹息。这一句的“少年时”三字，很多本子都作“去年时”。本来“去年时’三字也未尝不好，盖人当老去之时，其意兴与健康之衰损，往往会不免有一年不乃一年之感。故此句如作“去年时”，其悲慨亦复极深。不过，如果就此词前面之“归云一去无踪迹，何处是前期”诸句来看，则其所追怀眷念的，似乎原当是多年以前的往事，如此则承以“不似少年时”，便似乎更为气脉贯注，也更富于伤今感昔的慨叹。\n\n　　柳永这首《少年游》词，前阕全从景象写起，而悲慨尽在言外；后阕则以“归云”为喻象，写一切期望之落空，最后三句以悲叹自己之落拓无成作结。全词情景相生，虚实互应，是一首极能表现柳永一生之悲剧而艺术造诣又极高的好词。总之，柳永以一个禀赋有浪漫之天性及谱写俗曲之才能的青年人，而生活于当日之士族的家庭环境及社会传统中，本来就已经注定了是一个充满矛盾不被接纳的悲剧人物，而他自己由后天所养成的用世之意，与他自己先天所禀赋的浪漫的性格和才能，也彼此互相冲突。他的早年时，虽然还可以将失意之悲，借歌酒风流以自遣，但是歌酒风流却毕竟只是一种麻醉，而并非可以长久依恃之物，于是年龄老大之后，遂终于落得了志意与感情全部落空的下场。昔叶梦得《避署录话》卷记下柳永以谱写歌词而终生不遇之故事，曾慨然论之曰：“永亦善他文辞，而偶先以是得名，始悔为己累，……而终不能救。择术不可不慎。”柳永的悲剧是值得后人同情，也值得后人反省的。', poem_tags = '秋天,写景,人生,伤今感昔' WHERE poem_title = '少年游·长安古道马迟迟' AND poem_author = '柳永';
UPDATE edu_poem SET poem_translation = '藓自是低级植物，多寄生于阴暗潮湿之处，可它也有自己的生命本能和生活意向，并不会因为环境恶劣而丧失生发的勇气，诗人能看到这一点并歌而颂之，很有眼光！\n\n　　「白日不到处」，是如此一个不宜生命成长的地方，可是苔藓却长出绿意来，展现出自己的青春，而这青春从何而来？「恰自来」，嗯，并不从何处来，而是生命力旺盛的苔藓自己创造出来的！它就是凭着坚强的活力，突破环境的重重窒碍，焕发青春的光采。\n\n　　苔也会开花的，当然，怪可怜的，花如米粒般细小，但难道小的就不是花吗？只要能够开放，结出种子，繁衍后代，便是生命的胜利。所以，「也学牡丹开」，既是谦虚，也是骄傲！对的，苔花', poem_appreciation = '苔藓自是低级植物，多寄生于阴暗潮湿之处，可它也有自己的生命本能和生活意向，并不会因为环境恶劣而丧失生发的勇气，诗人能看到这一点并歌而颂之，很有眼光！\n\n　　「白日不到处」，是如此一个不宜生命成长的地方，可是苔藓却长出绿意来，展现出自己的青春，而这青春从何而来？「恰自来」，嗯，并不从何处来，而是生命力旺盛的苔藓自己创造出来的！它就是凭着坚强的活力，突破环境的重重窒碍，焕发青春的光采。\n\n　　苔也会开花的，当然，怪可怜的，花如米粒般细小，但难道小的就不是花吗？只要能够开放，结出种子，繁衍后代，便是生命的胜利。所以，「也学牡丹开」，既是谦虚，也是骄傲！对的，苔花如此细小低微，自不能跟国色天香的牡丹相比，可是牡丹是受人玩赏而受悉心栽培的，而苔花却是靠自己生命的力量自强，争得和花一样开放的权利——这世道并非仅为少数天才和英雄而存在的！', poem_tags = '咏物,植物,励志' WHERE poem_title = '苔' AND poem_author = '袁枚';
UPDATE edu_poem SET poem_tags = '写景,友情' WHERE poem_title = '满江红·翠幕深庭' AND poem_author = '吴文英';
UPDATE edu_poem SET poem_translation = '古时候被人称作豪杰的志士，一定具有胜人的节操，（有）一般人的常情所无法忍受的度量。有勇无谋的人被侮辱，一定会拔起剑，挺身上前搏斗，这不足够被称为勇士。天下真正具有豪杰气概的人，遇到突发的情形毫不惊慌，当无原因受到别人侮辱时，也不愤怒。这是因为他们胸怀极大的抱负，志向非常高远。\n\n　　张良被桥上老人授给兵书这件事，确实很古怪。但是，又怎么知道那不是秦代的一位隐居君子出来考验张良呢？看那老人用以微微显露出自己用意的方式，都具有圣贤相互提醒告诫的意义。一般人不明白，把那老人当作神仙，也太荒谬了。再说，桥上老人的真正用意并不在于授给张良兵书（而在于使张良能有所忍，以就大事）。在韩国已灭亡时，秦国正很强盛，秦王嬴政用刀锯、油锅对付天下的志士，那种住在家里平白无故被抓去杀头灭族的人，数也数不清。就是有孟贲、夏育那样的勇士，没有再施展本领的机会了。凡是执法过分严厉的君王，他的刀锋是不好硬碰的，而他的气势是不可以凭借的。张良压不住他对秦王愤怒的情感，以他个人的力量，在一次狙击中求得一时的痛快，在那时他没有被捕被杀，那间隙连一根头发也容纳不下，也太危险了！富贵人家的子弟，是不肯死在盗贼手里的。为什么呢？因为他们的生命宝贵，死在盗贼手里太不值得。张良有超过世上一切人的才能，不去作伊尹、姜尚那样深谋远虑之事，反而只学荆轲、聂政行刺的下策，侥幸所以没有死掉，这必定是桥上老人为他深深感到惋惜的地方。所以那老人故意态度傲慢无理、言语粗恶的深深羞辱他，他如果能忍受得住，方才可以凭借这点而成就大功业，所以到最后，老人说：“这个年幼的人可以教育了。”\n\n　　楚庄王攻打郑国，郑襄公脱去上衣裸露身体、牵了羊来迎接。庄王说：“国君能够对人谦让，委屈自己，一定能得到自己老百姓的信任和效力。”就此放弃对郑国的进攻。越王勾践在会稽陷於困境，他到吴国去做奴仆，好几年都不懈怠。再说，有向人报仇的心愿，却不能做人下人的，这是普通人的刚强而已。那老人，认为张良才智有余，而担心他的度量不够，因此深深挫折他年轻人刚强锐利的脾气，使他能忍得住小怨愤去成就远大的谋略。为什么这样说呢？老人和张良并没有平生的老交情，突然在郊野之间相遇，却拿奴仆的低贱之事来让张良做，张良很自然而不觉得怪异，这本是秦始皇所不能惊惧他和项羽所不能激怒他的原因。\n\n　　看那汉高祖之所以成功，项羽之所以失败，原因就在于一个能忍耐、一个不能忍耐罢了。项羽不能忍耐，因此战争中是百战百胜，但是随随便便使用他的刀锋（不懂得珍惜和保存自己的实力）。汉高祖能忍耐，保持自己完整的锋锐的战斗力，等到对方疲敝。这是张良教他的。当淮阴侯韩信攻破齐国要自立为王，高祖为此发怒了，语气脸色都显露出来，从此可看出，他还有刚强不能忍耐的气度，不是张良，谁能成全他？司马迁本来猜想张良的形貌一定是魁梧奇伟的，谁料到他的长相竟然像妇人女子，与他的志气和度量不相称。啊！外柔内刚，这就是张良之所以成为张良吧！', poem_notes = '节：节操。 \n匹夫：普通人。\n见辱：受到侮辱。\n卒然：突然。卒，通“猝”。\n所挟持者甚大：谓胸怀广阔，志意高远。挟持，指抱负。\n子房：张良，字子房。因佐刘邦建立汉朝有功，封留侯。\n受书：接受兵书。书，指《太公兵法》。圯上：桥上。老人：指黄石公。《史记·留侯世家》：“良尝闲从容步游下邳圯上，有一老父，衣褐，至良所，直堕其履圯下。顾谓良曰：‘孺子，下取履！’良愕然，欲殴之；为其老，强忍，下取履。父曰：‘履我！’良业为取履，因长跪履之。父以足受，笑而去。”后老父约见张良于桥上，张良两次迟到，受到老父的责备。第三次张良“夜未半”即往，老父喜，送他一部书，说：“读此则为王者师矣。后十年兴，十三年孺子见我济北谷城，山下黄石即我矣。”语毕，老父即离去。次日张良“视其书”，才知道是《太公兵法》。\n隐君子：隐居的高士。\n观其：瞧他。其，指黄石公。\n微：略微，隐约。\n见：同“现”。\n以为鬼物：因黄石公的事迹较为离奇，语或涉荒诞，故有人认为他是鬼神之类，王充《论衡·自然》：“或曰······张良游泗水之上，遇黄石公，授公书。盖天佐汉诛秦，故命令神石为鬼书授人。”\n以刀锯鼎镬待天下之士：谓秦王残杀成性，以刀锯杀人，以鼎镬烹人。\n夷灭：灭族。\n贲、育：孟贲、夏育，古代著名勇士。\n无所复施：无法施展本领。\n其势未可乘：谓形势有利于秦，还没有可乘之机。\n而逞于一击之间：《史记·留侯世家》载“秦灭韩”，张良“悉以家财求客刺秦王，为韩报仇······得力士，为铁椎重百二十斤。秦皇帝东游，良与客狙击秦皇帝博浪沙中，误中副车。秦皇帝大怒，大索天下，求贼甚急，为张良故也。”其间不能容发：当中差不了一根毛发。比喻情势危急。\n千金之子：富贵人家的子弟。\n不死于盗贼：不会死在和贼的拼搏上。\n不足以死：不值得因之而死。\n伊尹太公之谋：谓安邦定国之谋。伊尹辅佐汤建立商朝。吕尚（即太公望）是周武王的开国大臣。\n荆柯聂政之计：谓行刺之下策。荆柯刺秦王与燕政刺杀韩相侠累两事，俱见《史记·刺客列传》。\n鲜腆：无礼，厚颇。\n孺子可教也：谓张良可以教诲。\n“楚庄王伐郑”六句：楚庄王攻克郑国后，郑伯肉祖牵羊以迎，表示屈服。楚庄王认为他能取信于民，便释放了他，并退兵，与郑议和。事见《左传》宜公十二年。肉祖，袒衣阵体。\n“勾践之困于会稽”三句：《左传》哀公元年：“吴王夫差败越于夫椒，报槜李（越军曾击败吴军于此）也。遂入越。越王（勾践）以甲循五千，保于会稽（山），使大夫种因昊大宰萦以行成。······越及吴平。《国语·越语下》载勾践“令大夫种守于国，与范蠡入宦于吴：三年而吴人遣之。”归臣妾于吴，谓投降吴国为其臣妾。\n报人：向人报仇。\n非有生平之素：犹言素昧平生（向来不熟悉）。\n仆妾之役：指“取履”事。\n油然：盛兴貌。此谓悦敬之心油然而生。\n轻用其锋：轻率地消耗自己的兵力。\n弊：疲困，衰败。\n“当淮阴破齐”三句：《史记·淮阴侯列传》：汉四年，韩信破齐，向刘邦请封“假王”，“当是时，楚方急围汉王于荣阳，韩信使者至，发书，汉王大怒，骂日：‘吾困于此，旦暮望若来佐我，乃欲自立为王！’”张良赶紧提醒他不能得罪韩信。刘邦醒悟，便封韩信为齐王以笼络他。韩信后降封为淮阴侯，故称为淮阴。\n非子房其谁全之：不是张良，谁又能来保全他呢？\n“太史公疑子房以为魁梧奇伟”二句：《史记·留侯世家》：“太史公日：‘余以为其人计魁梧奇伟，至见其图，状貌如妇人好女。’”不称，不相称。', poem_appreciation = '《留侯论》并不全面评论张良的生平和功业，而只论述他之所以取得成功的主观方面的根本原因——“能忍”的过人之节。这个问题过去未有人道及，是作者的创见。\n\n　　开头一段是立论，提出能忍、不能忍这个命题。“古之所谓豪杰之士者，必有过人之节”，是泛言，举凡忠勇、坚毅等等超乎常人的节操，全都包括在内。以下则扣住《留侯论》本题，加以申说，将“过人之节”具体到“忍”字。说“忍”，又是从“‘勇”字来说，提出匹夫之勇不算勇，只有“人情有所不能忍者”，“卒然临之而不惊，无故加之而不怒”，也就是说，能忍，才是大勇；而其所以能忍，又是因为抱负甚大，志向甚远的缘故。表面看来，勇和忍似乎是对立的，作者却指出了它们的统一性，充满辩证法，非常精警深刻。这是作者的基本论点，也是全篇的主意。虽然这里并未指名，实际是对张良而言。以下全是对张良的具体论证。\n\n　　文中举了张良狙击秦王、进履受书、劝说刘邦封韩信为齐王三件事。这三件事表面看来似无关连，但作者却敏锐地看到了它们之间的联系，由此提出了他的独创见解。\n\n　　第二段先从前两件事说。人们孤立地看圯上老人赠书事，因而把一些神怪传闻当作真实。作者把这件事同张良狙击秦王联系起来，把他为韩报仇不能忍小忿，逞匹夫之勇，与成大事所需要的大忍耐联系起来，指出这是秦时的隐士对张良忍耐心的考验观察，其用意并不在书的授受。指出老人的行动所暗示的，都是圣贤间互相警示劝戒的道理。这几层意思紧密钩连，互为论证，结构非常严密。拂去老人赠书的神奇色彩，关系到基本立论，因为如果这真是神怪的行为而非人事，就无法按常理论之。老人赠书的用意，则是从张良和老人的行动本身这两个方面来论证。从张良讲，他狙击秦王的行动，是“不忍忿忿之心”的表现，这种荆轲、聂政式的刺杀行为，在当秦势方盛时无异于白白送死。老人因为痛惜其才，才“出而试之”，故意用傲慢无礼的举动“无故加之”，极力摧折侮辱他，以磨炼他的性格，“深折其少年刚锐之气”，使其“能有所忍”。从老人说，他对张良的一系列折辱举动，显然不是出于无心。当老人故意走到张良跟前堕履又命他取履时，张良“欲殴之”，仍有不能忍之心；因念其年老而下桥取履是“强忍”着，老人岂有不知，故又提出更带侮辱性的要求：替我穿履！张良想，既已为老人取履了，就再替他穿上吧。这“能忍”的程度又进了一步，但老人还要再看看。他以足受履，笑而去，行了里许路，见张良只是目送着他，并无异常的表现，这才再走回来，对张良说：“孺子可教矣！”这就自己道出了有意试察的用心。太史公的笔墨也很传神：写张良“欲殴之”，“强忍”，“业为取履，因履之”，“殊大惊，因目之”，一连串带动作的心理描写把个“忍”字的深化过程刻画得丝丝人扣。随后因“平明”、“鸡鸣”赴约仍然迟到而一再受到怒责，终于以“夜未半”即往，得到老人的首肯，完成了“忍”’的磨练。这给作者取为立论主题提供了材料。如果老人的用意是在赠书，只须将书授与即可；之所以“深折之”，正说明“意不在书”。“且其意不在书”，而在使张良能忍，二者实为一个意思。\n\n　　为了加强说服力，第三段又引史为证，再次申说上段之意。文中先引郑伯能忍而不战退敌，勾践能忍而终灭吴国，以见忍的极端重要性，说明圯上老人何以要“出而试之”。又概述老人“深折”张良的情景，证明他的举动确实是对张良的考察试验。前者是从动机讲，后者是从事实讲，行动的目的则是“使之忍小忿而就大谋”（化用《论语·卫灵公》“小不忍则乱大谋”语意，即上文所谓“圣贤相与警戒之义”），后来的结果则是使张良达到了“秦皇帝之所不能惊，而项籍之所不能怒”的境界。\n\n　　以上都是就张良早年的两件事而言，第四段又举他后来在刘邦项籍斗争中的一个例证以实之。没有这个例证，张良在坦上的表现，可以视为偶然；有了这个例证，上面的论证才开花结果，落到实处。这段的精妙之处在于，作者不是孤立地讲张良，而是联系到刘、项两家的斗争来举例。文中把刘邦之所以胜和项籍之所以败，归结为能忍和不能忍，而以韩信求假封为齐王的事例，把刘邦之能忍归结为系由张良成全，不仅说明了能忍对于张良、对于刘、项的事业的重大意义，还说明了纪上老人的启导所起的巨大作用，大大增强了通篇议论的说服力。末尾以揣度作结，谓子房的状貌也表现出能忍的特征，思致新颖，风调翩翩，余味不尽。', poem_tags = '古文观止,议论,写人,散文' WHERE poem_title = '留侯论' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '黄莺用嘴衔过的花更加红润，燕子用尾点扫的水波泛起绿色的涟漪。天寒手冷，玉笙冰凉，但吹笙的人却亢奋地吹起《小梅花》曲子，声音宏亮悠扬， 响彻天空，听者都感到激越、雄浑，春意盎然。人们都说，照这样吹，这样吹吠下去，一定会让人和绿杨都会变得潇洒清秀。', poem_notes = '玉笙：珍贵的管乐器。\n《小梅》：乐曲名。唐《大角曲》里有《大梅花》、《小梅花》等曲。', poem_tags = '婉约,春天,写景,伤春,怀人' WHERE poem_title = '如梦令·春景' AND poem_author = '秦观';
UPDATE edu_poem SET poem_translation = '西山终年积雪，三城都有重兵驻防；南郊外的万里桥，跨过泱泱的锦江。\n海内连年战乱，几个兄弟音讯阻隔；彼此天涯海角，只我一人好不凄怆？\n惟将迟暮的年光，交与多病的身躯；至今无点滴功德，报答贤明的圣皇。\n我独自地骑马郊游，常常极目远望，世事一天天萧条，真叫人不堪想象。', poem_notes = '西山：在成都西，主峰雪岭终年积雪。三城：指松（今四川松潘县）、维（故城在今四川理县西）、保（故城在理县新保关西北）三州。城，一作“年”，一作“奇”。戍：防守。三城为蜀边要镇，吐蕃时相侵犯，故驻军守之。\n南浦：南郊外水边地。清江：指锦江。万里桥：在成都城南。蜀汉费祎访问吴国，临行时曾对诸葛亮说：“万里之行，始于此桥。”这两句写望。\n风尘：指安史之乱导致的连年战火。诸弟：杜甫四弟：颖、观、丰、占。只杜占随他入蜀，其他三弟都散居各地。\n迟暮：这时杜甫年五十。供多病：交给多病之身了。供，付托。\n涓埃：滴水、微尘，指毫末之微。\n日：一作“自”。', poem_appreciation = '诗以“野望”为题 ，是诗人跃马出郊时感伤时局、怀念诸弟的自我写照。\n\n　　首两句写野望时所见西山和锦江。西山主峰终年积雪，因此以“白雪”形容。三城，在当时驻军严防吐蕃入侵，是蜀地要镇。\n\n　　中间四句是野望时触发的有关国家和个人的感怀。三四句由战乱推出怀念诸弟，自伤流落的情思。海内外处处烽火，诸弟流散，此时“一身遥”客西蜀，如在天之一涯。诗人怀念家国，不禁“涕泪”横流。真情实感尽皆吐露不由人不感动。\n\n　　五六句又由“ 天涯”“一身”引出残年“多病”，“未”贡微力，无补“圣朝”的内愧。杜甫时年五十，因此说已入“迟暮”之年。他叹息说：我只有将暮年付诸给“多病”之身，但“未有”丝毫贡献，报答“圣朝”，是很感惭愧的。\n\n　　杜甫虽流落西蜀，而报效李唐王朝之心，却始终未改，足见他的爱国意识是很强烈的。中间四句，由于连用对偶尔将诗人的家国之忧，身世之感，特别是报效李唐王朝之心，艺术地得到有效概括。\n\n　　七八句最后点出“野望”的方式和深沉的忧虑。“人事”，人世间的事。由于当时西山三城列兵防戍，蜀地百姓赋役负担沉重，杜甫深为民不堪命而对世事产生“日” 转“萧条”的隐忧。这是结句用意所在。诗人从草堂“跨马”，走“出”南“郊”，纵目四“望”。“ 南浦清江万里桥”是近望之景。“西山白雪三城戍 ”，是远望之景。他由“三城戍”引出成乱的感叹，由“万里桥”兴起出蜀之意。这是中间四句有关家国和个人忧念产生的原因。\n\n　　杜甫“跨马出郊 ”，“极目”四“望”，原本为了排遣郁闷 。但爱国爱民的感情，却驱迫他由“望 ”到的自然景观引出对国家大事、弟兄离别和个人经历的种种反思。一时间，报效国家、怀念骨肉和伤感疾病等等思想感情，集结心头。尤其为“迟暮”“多病”发愁，为“涓埃”未“答”抱愧。\n\n　　此诗前三联写野望时思想感情的变化过程，即由向外观察转为向内审视。尾联才指出由外向到内向的原因。在艺术结构上，颇有控纵自如之妙。', poem_tags = '唐诗三百首,写景,抒情' WHERE poem_title = '野望' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '贵妃真是一枝带露牡丹，艳丽凝香，楚王神女巫山相会，枉然悲伤断肠。请问汉宫得宠妃嫔，谁能和她相像？可爱无比的赵飞燕，还得依仗新妆！', poem_notes = '飞燕：赵飞燕，西汉皇后\n妆：修饰打扮', poem_tags = '唐诗三百首,乐府,女子' WHERE poem_title = '清平调·其二' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '汉武帝曾经十分宠爱阿娇，为她筑造金屋让她居住。武帝对她娇宠万分，即使她的唾沫落下，也会被看做像珠玉那样珍贵。娇宠到极点，恩爱也就停歇了，武帝对她的情意渐渐停歇淡薄。阿娇被贬长门后，即使与武帝的寝宫相距很近，武帝也不肯回车，在阿娇那里暂时停留。雨落之后再不会飞上天空，覆水也难再收回。武帝与阿娇的情意，各自东西。往日美丽的芙蓉花，今日成为凄凉的断根之草。如果凭借姿色侍奉他人，相好的日子是十分短暂的。', poem_notes = '“汉帝”两句：汉武帝曾有语：“若得阿娇作妇，必作金屋贮之。”\n“咳唾”两句：这里化用的是《庄子》里的故事。《庄子·秋水》中有：“子不见夫唾者乎？喷则大者如珠，小者如雾，杂而下者不可胜数也。”\n水覆难再收：传说姜太公的妻子马氏，不堪太公的贫困而离开了他。到太公富贵的时候，她又回来找太公请求和好。太公取了一盆水泼在地上，令其收之，不得，太公就对她说：“若言离更合，覆水定难收。”\n君：指汉武帝。\n妾：指阿娇。\n芙蓉花：指荷花。断根草：比喻失宠。', poem_appreciation = '这首五言古诗《妾薄命》是唐代大诗人李白的作品。此诗“依题立义”，通过叙述陈皇后阿娇由得宠到失宠之事，揭示了封建社会中妇女以色事人，色衰而爱弛的悲剧命运。\n\n　　这首五言古诗《妾薄命》属乐府杂曲歌辞。李白的这首《妾薄命》通过对汉武帝皇后陈阿娇逃脱不了色衰而爱驰的悲惨终局的描写，表达了一种悲悯，悲悯当中又有一种启示。\n\n　　全诗十六句，每四句基本为一个层次。诗的前四句，先写阿娇的受宠，而从“金屋藏娇”写起，欲抑先扬，以反衬失宠后的冷落。据《汉武故事》记载：汉武帝刘彻数岁时，他的姑母长公主问他：“儿欲得妇否？”指左右长御百余人，皆曰：“不用。”最后指其女阿娇问：“阿娇好否？”刘彻笑曰：“好！若得阿娇作妇，当作金屋贮之。”刘彻即位后，阿娇做了皇后，也曾宠极一时。诗中用“咳唾落九天，随风生珠玉”两句夸张的诗句，形象地描绘出阿娇受宠时的气焰之盛，真是炙手可热，不可一世。但是，好景不长。从“宠极爱还歇”以下四句，笔锋一转，描写阿娇的失宠，俯仰之间，笔底翻出波澜。娇妒的陈皇后，为了“夺宠”，曾做了种种努力，她重金聘请司马相如写《长门赋》，“但愿君恩顾妾深，岂惜黄金买词赋”李白《白头吟》；又曾用女巫楚服的法术，“令上意回”。前者没有收到多大的效果，后者反因此得罪，后来成了“废皇后”，幽居于长门宫内，虽与皇帝相隔一步之远，但咫尺天涯，宫车不肯暂回。“雨落不上天”以下四句，用形象的比喻，极言“令上意回”之不可能，与《白头吟》所谓“东流不作西归水”、“覆水再收岂满杯”词旨相同。最后四句交代其中原因。\n\n　　诗人用比兴的手法，形象地揭示出这样一条规律：“昔日芙蓉花，今成断根草。以色事他人，能得几时好？”这发人深省的诗句，是一篇之警策，它对以色取人者进行了讽刺，同时对“以色事人”而暂时得宠者，也是一个警告。诗人用比喻来说理，用比兴来议论，充分发挥形象思维的特点和比兴的作用，不去说理，胜似说理，不去议论，而又高于议论，颇得理趣。由此可知靠美色取悦与皇上不能得到多少好处。爱是应该有距离的，不能距离为零，否则物极必反。\n\n　　这首诗语言质朴自然，气韵天成，比喻贴切，对比鲜明，得宠与失宠相比，“芙蓉花”与“断根草”相比，比中见义。全诗半是比拟，从比中得出结论：“以色事他人，能得几时好”，显得自然而又奇警，自然得如水到渠成，瓜熟蒂落，奇警处，读之让人惊心动魄。', poem_tags = '乐府,哲理' WHERE poem_title = '妾薄命' AND poem_author = '李白';
UPDATE edu_poem SET poem_tags = '写景,抒情' WHERE poem_title = '浣溪沙·残雪凝辉冷画屏' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '一个人应该树立远大的理想，追慕先贤，节制情欲，去掉郁结在胸中的俗念，使几乎接近圣贤的那种高尚志向，在你身上明白地体现出来，使你内心震动、心领神会。要能够适应顺利、曲折等不同境遇的考验，摆脱琐碎事务和感情的纠缠，广泛地向人请教，根除自己怨天尤人的情绪。做到这些以后，虽然也有可能在事业上暂时停步不前，但哪会损毁自己高尚的情趣，又何必担心事业会不成功呢！如果志向不坚毅，思想境界不开阔，沉溺于世俗私情，碌碌无为，永远混杂在平庸的人群之后，就会难免沦落到下流社会，成为没有教养，没有出息的人。', poem_notes = '存，怀有，怀着\n凝滞，心思局限于某个范围;拘泥\n庶几之志，接近或近似于先贤的志向\n揭然，高举的样子\n恻然，恳切的样子\n细碎，琐碎的杂念\n嫌吝，怨恨耻辱\n淹留，德才不显于世\n济，成功，实现\n强毅，坚强果断\n窜伏，逃避，藏匿\n下流，比喻低下的地位', poem_tags = '书信' WHERE poem_title = '诫外甥书' AND poem_author = '诸葛亮';
UPDATE edu_poem SET poem_translation = '清明这一天，南山北山到处都是忙于上坟祭扫的人群。焚烧的纸灰像白色的蝴蝶到处飞舞，凄惨地哭泣，如同杜鹃鸟哀啼时要吐出血来一般。黄昏时，静寂的坟场一片荒凉，独有狐狸躺在坟上睡觉，夜晚，上坟归来的儿女们在灯前欢声笑语。因此，人活着时有酒就应当饮，有福就应该享。人死之后，儿女们到坟前祭祀的酒哪有一滴流到过阴间呢？', poem_notes = '纷然：众多繁忙的意思。\n九泉：指人死后埋葬的地方，迷信人指阴间。', poem_appreciation = '诗歌首联两句是远景，一句写物景，一句写人景。据此，我们不妨这样想，诗人在清明节这一天来祭扫，未到坟茔聚集之地，即以目睹此景，因墓地往往在深处，怕妨路径，故一眼必是望到远景。那么这是一种什么样的场景呢？“南北山头多墓田”，“南北”当是虚指，意即四面八方。是不是就可以解成“四面八方的山头上有很多墓田”了呢？难道我们竟没有体会出诗人说这句话时无限悲凉的口吻吗：“（你看啊！）四面八方的山头上竟然有这么多的墓田，（那些可都是死去的人啊！）”这样解就丰满得多了。下面人景也就很是顺理成章了，墓地多，自然来祭扫的人也就多了：“清明祭扫各纷然”。可是这里面有一个问题，“各”指每家祭扫每家的毫不相干，“纷然”则指人数众多。那么既然人数众多，何以“各人自扫门前雪”呢？难道不会出现相互帮助、相互劝慰的场景吗？须知道，人们一般只有在什么情况下才会互不搭腔，就是已经痛苦难过到了极致，以致习惯成自然，各自心知肚明，无需多言。\n\n　　颔联两句，诗人走上前去，镜头拉近，细节刻画物景与人景：“纸灰飞作白蝴蝶，泪血染成红杜鹃。”字面上很好说，就是说冥纸成灰，灰飞漫天，好似白色的蝴蝶；相思成泪，泪滴成血，仿佛红色的杜鹃。可为什么要以纸灰作蝴蝶，泪血作杜鹃，而不是旁的什么？我们都知道中国古代美丽的神话中有庄周化蝶、杜鹃啼血的范式。那么就清楚了：原来蝴蝶是沟通阴阳二界的使者啊，冥纸当然就是起到这样的作用；同样的，相思要怎么样来表达才最恳切，总不至于老是“思君如流水，何有穷已时”一类的吧，这样就浅薄了。“我”要告诉阴间的人，“我们”想你想得都把眼泪哭干了，现在啼出来的是血啊！这种震撼力，实在是难以言表的。\n\n　　颈联承接上句，依照时间发展续写诗人的所见所想：“日落狐狸眠冢上，夜归儿女笑灯前。”出句当然是虚景，哪里会有这么巧让诗人碰到狐狸在冢穴里面睡觉呢！不过是说，一天的祭扫结束了，日薄西山，人人各自归家，但“我”知道，只有一种动物是不会离开的，那便是狐狸。你凭什么这么说？虽然“我”没有看见，但“我”竟连“狐死必首丘”的道理也不懂吗？你们这些人，祭扫之时哭哭啼啼，平日里哪里见到你们有丝毫的伤心难过？狐狸却不同，它们始终对同伴、对“家庭”忠诚无二，即使死了，也要将头对准丘穴的方向！真是“狐犹如此，人何以堪”啊！这一层强烈的反差不经仔细的推敲是得不到的。可是哪里知道反差更强烈的还在后头：晚上回到家来，看到孩子们在灯前玩闹嬉戏，他们怎么会知道“我”的心酸，怎么会知道生离死别的痛苦？这于我们来说，又是一个极大的冲击。可是还不止如此，我们再挖掘下去就发现：这些孩子都还那样弱小，是那么天真无邪，可是终归要长大，终归要衰老，终归也要死去，这是天命所在，是多么得令人遗憾，令人神伤。你看，这里正好与首联我们提到的诗人厌倦死亡的思想相照应了。是不是吃了一惊，短短十四个字，居然内涵多至如斯境地，且皆为感人心魄，发人深省之语。\n\n　　尾联诗人要总结了，也算是表达自己的态度：“人生有酒须当醉，一滴何曾到九泉。”应当说这是比较易见的文人士大夫的心理常态，就是及时行乐。我们读到这里，定会不由自主地联想到《古诗十九首》里那么成系统地高唱“人生不满百，常怀千岁忧。昼短苦夜长，何不秉烛游？”或者会更直接想到“今朝有酒今朝醉，明日愁来明日愁”。但果真如此简单吗？我认为关于这一点我们存在一种认识上的误区：即并未区分与判断抒发及时行乐思想究竟是已臻化境，心本开阔，还是无奈愁极，故作旷达，这一点是极重要的问题，是可以作为专题来研究的。就高翥这首诗而言，显然是故作旷达无疑。你看，诗人尚在阳间，就已经想到死后别人祭祀他的酒他一滴也尝不到了，可见他对这个世界是何其留恋！老子说：“五色令人目盲，五音令人耳聋，五味令人口爽，驰骋畋猎令人心发狂”，由此可见欲望能使人丧失本我，渐成依赖。\n\n　　原本下面该是艺术手法的分析，因又要涉及理论，与我想要表达鉴赏的最初的心理流变旨趣不合，故略去。高翥是南宋后期江湖诗派的重要作家，且为宁波人，可以说，无论从时间上还是空间上，都与我近来研究的楼钥有偶合之处。', poem_tags = '清明节,感伤,相思' WHERE poem_title = '清明日对酒' AND poem_author = '高翥';
UPDATE edu_poem SET poem_translation = '故乡和亲人远在千里之外，我已被幽闭在这深宫里二十年了，听一声曲子《何满子》，忍不住掉下眼泪。', poem_notes = '故国：故乡。\n何满子：唐玄宗时著名歌手，据说她因故得罪了皇帝，被推出就刑。就刑前她张口高歌，曲调悲愤，使“苍天白日黯然失色”。结果皇帝闻之，终因惜其技艺难得而降旨缓刑。因为何满子出色的技艺，大诗人元稹、白居易、杜牧等都相继为之赋诗，其中以张祜的《何满子》宫词：“故国三千里，深宫二十年。一声何满子，双泪落君前”最为感人。这首宫词后来流传甚广，其唱来异常悲怨。据说唐武宗时，有一孟才人，因有感于武宗让其殉情之意，为奄奄一息的武宗唱了一曲《何满子》，唱毕，竟气绝身亡。一作“河满子”，舞曲名。题又作“宫词”。白居易《何满子》诗：“世传满子是人名，临就弄时曲始成。一曲四词歌八叠，从头便是断肠声。”“何满子”声调哀婉。《乐府集》引白居易《何满子》诗的自注说：“何满子，开元中沧州歌者，临弄进此曲以赎死，竟不得免。”\n君：指皇帝。这里是指唐武宗。据《唐诗纪事》，张祜《宫词》：“传入宫禁，武宗疾笃，目孟才人曰：‘吾即不讯，尔何为哉？’指笙囊泣曰：‘请以此就缢。’上悯然。复曰：‘妾尝艺歌，请对上歌一曲，以泄其愤。’上许。乃歌一声《何满子》，气亟立殒。上令候之，曰：‘脉尚温而肠已绝。’”后来张祜别有咏《孟才人叹》一绝，词云：“偶因歌态咏娇嚬，传唱宫中十二春。却为一声何满子，下泉须吊旧才人。”', poem_appreciation = '一般以绝句体裁写的篇幅短小的宫怨诗，总是只揭开生活画图的一角，让读者从一个片断场景看到宫人悲惨的一生；同时往往写得委婉含蓄，一些内容留待读者自己去想象，去玩味。这首诗却与众不同。它展示的是一幅生活全图，而且是直叙其事，直写其情。　\n\n　　诗总共只有二十个字。作者在前半首里，以举重若轻、驭繁如简的笔力，把一个宫人远离故乡、幽闭深宫的整个遭遇浓缩在短短十个字中。首句“故国三千里”，是从空间着眼，写去家之远；次句“深宫二十年”，是从时间下笔，写入宫之久。这两句诗，不仅有高度的概括性，而且有强烈的感染力；不仅把诗中女主角的千愁万恨一下子集中地显示了出来，而且是加一倍、进一层地表达了她的愁恨。一个少女不幸被选入宫，与家人分离，与外界隔绝，失去幸福，失去自由，本来已经够悲惨了，何况家乡又在三千里之外，岁月已有二十年之长，这就使读者感到其命运更加悲惨，其身世更可同情。与这两句诗相似的有柳宗元《别舍弟宗一》诗中“一身去国六千里，万死投荒十二年”一联，也是以距离的遥远、时间的久长来表明去国投荒的分外可悲。这都是以加一倍、进一层的写法来增加诗句的重量和深度。　\n\n　　后半首诗转入写怨情，以一声悲歌、双泪齐落的事实，直截了当地写出了诗中人埋藏极深、蓄积已久的怨情。这后两句诗也以强烈取胜，不以含蓄见长。过去一些诗论家有诗贵含蓄、忌直贵曲的说法，其实并不是绝对的。应当说，一首诗或曲或直，或含蓄或强烈，要服从它的内容。这首诗的前半首已经把诗中人的处境之悲惨写到了极点，为逼出怨情蓄足了力量，因而在下半首中就势必让诗中人的怨情喷薄而出、一泻为快了。这样才能使整首诗显得强烈有力，更能收到打动读者的艺术效果。这里，特别值得拈出的一点是：有些宫怨诗把宫人产生怨情的原因写成是由于见不到皇帝或失宠于皇帝，那是不可取的；这首诗反其道而行之，它所写的怨情是在“君前”、在诗中人的歌舞受到皇帝赏识的时候迸发出来的。这个怨情，联系前两句看，决不是由于不得进见或失宠，而是对被夺去了幸福和自由的抗议，正是刘皂在一首《长门怨》中所说，“不是思君是恨君”。　\n\n　　这首诗还有两个特点。一是：四句诗中，前三句都是没有谓语的名词句。谢榛在《四溟诗话》中曾指出，诗句中“实字多，则意简而句健”，而他所举的“皆用实字”的例句，就是名词句。这首诗之所以特别简括凝炼、强烈有力，与运用这种特殊的诗句结构有关。另一特点是：四句诗中，以“三千里”表明距离，以“二十年”表明时间，以“一声”写歌唱，以“双泪”写泣下，句句都用了数目字。而数字在诗歌中往往有其特殊作用，它能把一件事情、一个问题表达得更清晰，更准确，给读者以更深刻的印象，也使诗句特别精炼有力。这首诗的这两个艺术形式上的特点，与它的内容互为表里，相得益彰。\n\n　　与张祜同时的诗人杜牧非常欣赏这首诗，在一首酬张祜的诗中有“可怜故国三千里，虚唱歌词满六宫”句。这说明，张祜的这首诗道出了宫人的辛酸，讲出了宫人要讲的话，当时传入宫中，曾为宫人广泛歌唱。', poem_tags = '唐诗三百首,宫怨' WHERE poem_title = '宫词·故国三千里' AND poem_author = '张祜';
UPDATE edu_poem SET poem_tags = '咏物,梅花,言志' WHERE poem_title = '早梅' AND poem_author = '齐己';
UPDATE edu_poem SET poem_translation = '太平山上的白云泉清澈可人，白云自在舒卷，泉水从容奔流。\n白云泉啊，你又何必冲下山去，给原本多事的人间在添波澜。', poem_notes = '白云泉：天平山山腰的清泉。\n天平山：在今江苏省苏州市西。\n无心：舒卷自如。\n闲：从容自得。\n何必：为何。\n奔：奔跑。\n波浪：水中浪花，这里喻指令人困扰的事情。', poem_appreciation = '这首七绝犹如一幅线条明快简洁的淡墨山水图。诗人并不注重用浓墨重彩描绘天平山上的风光，而是着意摹画白云与泉水的神态，将它人格化，使它充满生机、活力，点染着诗人自己闲逸的感情，给人一种饶有风趣的清新感。诗人采取象征手法，写景寓志，以云水的逍遥自由比喻恬淡的胸怀与闲适的心情；用泉水激起的自然波浪象征社会风浪，“兴发于此而义归于彼”，言浅旨远，意在象外，寄托深厚，理趣盎然。诗的风格平淡浑朴，清代田雯谓“乐天诗极清浅可爱，往往以眼前事为见得语，皆他人所未发。”（《古欢堂集》）这一评语正好道出了这首七绝的艺术特色。\n\n　　“天平山上白云泉”，起句即点出吴中的奇山丽水、风景形胜的精华所在。天平山在苏州市西二十里。“此山在吴中最为崷崪高耸，一峰端正特立”，“巍然特出，群峰拱揖”，岩石峻峭。山上青松郁郁葱葱。山腰依崖建有亭，“亭侧清泉，泠泠不竭，所谓白云泉也”，号称“吴中第一水”，泉水清洌而晶莹，“自白乐天题以绝句”，“名遂显于世”。\n\n　　然而，这一名山胜水的优美景色在诗人眼帘中却呈现为：“云自无心水自闲”。白云随风飘荡，舒卷自如，无牵无挂；泉水淙淙潺流，自由奔泻，从容自得。诗人无意描绘天平山的巍峨高耸和吴中第一水的清澄透澈，却着意描写“云无心以出岫”的境界，表现白云坦荡淡泊的胸怀和泉水闲静雅致的神态。句中连用两个“自”字，特别强调云水的自由自在，自得自乐，逍遥而惬意。这里移情注景，景中寓情，“云自无心水自闲”，恰好是诗人思想感情的自我写照。', poem_tags = '山水,写景,寓志' WHERE poem_title = '白云泉' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '江山沐浴着春光，多么秀丽，春风送来花草的芳香。\n燕子衔着湿泥忙筑巢，暖和的沙子上睡着成双成对的鸳鸯。', poem_notes = '迟日：春天日渐长，所以说迟日。 \n泥融：这里指泥土滋润、湿润。\n鸳鸯：一种水鸟，雄鸟与雌鸟常常双双出没。', poem_appreciation = '明人王嗣爽在其《杜臆》中予以反驳说：“余曰：上二句两间（指天地间）莫非生意，下二句见万物莫不适性。岂不足以感发吾心之真乐乎？”王氏的意见是对的。此诗抓住景物特点写春色，画面优美，格调柔和，很能引发读者的喜春之情。\n\n　　“迟日”，出自《诗经·七月》：“春日迟迟。”春天光照时间渐长，天气趋暖，正所谓“天初暖，日初长”（欧阳炯《春光好》）。诗人以“迟日”领起全篇，突出了春天日光和煦、万物欣欣向荣的特点，并使诗中描写的物象有机的组合为一体，构成一幅明丽和谐的春色图。你看：阳光普照，水碧山青，草木复苏，万象更新。清风拂面，送来百花的芳香，带来春草的清馨。河滩上，溪岸边，冰雪融尽，泥土潮湿而松软，燕子轻盈地飞来飞去，衔泥筑巢，呢呢喃喃。水暖沙温，美丽多情的鸳鸯相依相偎，恬然静睡，十分娇慷可爱。燕子是侯鸟，诗人描写它是有意突出春天的特征。前二句的“迟日”、“江山”、“春风”、“花草”组成一幅粗线勾勒的大场景，并在句尾以“丽”、“香”突出诗人强烈的感觉；后二句则是工笔细描的特定画面，既有燕子翩飞的动态描绘，又有鸳鸯慵睡的静态写照。飞燕的繁忙蕴含着春天的勃勃生机，鸳鸯的闲适则透出温柔的春意，一动一静，相映成趣。而这一切全沐浴在煦暖的阳光下，和谐而优美，确实给人以春光旖旎之感。\n\n　　清人陶虞开称杜甫笔法高妙，能“以诗为画”（《说杜》），此诗可为印证。但这首五绝之妙并不止于“以诗为画”，诗人着意传达的还是他感受到的柔和春意。如果说春日迟迟、江山秀丽、清风徐徐、花草芬芳以及燕子、鸳鸯，都是诗人的视觉、触觉（风）、嗅觉所感，那么泥土之“融”、沙砾之“暖”，便不是五官的直接感觉了。只因为对春天的阳光明丽、惠风和畅、鸟语花香感受至深，诗人无须触摸就能想象出泥土的松湿和沙砾的温暖；而泥之融、沙之暖的体会又加深了对飞燕的轻盈、鸳鸯娇慵的视觉印象，从而使诗人的整个身心都沉浸于柔美和谐和春意之中。', poem_tags = '春天,写景,早教古诗100首' WHERE poem_title = '绝句' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '听着绿树荫里鹈鴂叫得凄恶，更令人悲伤不已。鹧鸪鸟“行不得也哥哥”的啼叫刚住，杜鹃又发出“不如归去”悲切的号呼。一直啼到春天归去再无寻觅处，芬芳的百花都枯萎，实在令人愁恨、痛苦。算起来这桩桩件件也抵不上人间生离死的痛楚。汉代王昭君骑在马上弹着琵琶，奔向黑沉沉的关塞荒野，更有陈皇后阿娇退居长门别馆，坐着翠碧的宫辇辞别皇宫金阙。春秋时卫国庄姜望着燕燕双飞，远送休弃去国的归老。\n汉代名将李陵身经百战，兵败归降匈奴而身败名裂。到河边轿头送别苏武，回头遥望故国远隔万里，与故友永远诀别。还有荆轲冒着萧瑟秋风，慷慨悲歌无尽无歇。啼鸟若知人间有如此多的悲恨痛切，料想它不再悲啼清泪，而总是悲啼着鲜血。如今茂嘉弟远别，还有谁与我饮酒共醉赏明月？', poem_notes = '题下自注：“鹈鴂、杜鹃实两种，见《离骚补注》”。鹈鴂，指伯劳。\n鹧鸪：鸣声凄切，如说“行不得也哥哥”。\n杜鹃：其声哀婉，如说“不如归去”。\n未抵：比不上。\n马上琵琶：用王昭君出塞事。\n“更长门”句：用陈皇后失宠事。\n将军：引用汉武帝时李陵。\n“向河梁”句：引用李陵别苏武事。\n“易水”句：引用《史记·刺客列传》中荆轲刺秦王事。\n如许恨：像上面的许多恨。', poem_appreciation = '这首词的内容和作法与一般的词不同，其内容方面几乎完全与对茂嘉的送行无关，而专门罗列古代的“别恨”事例。形式方面，它又打破上下片分层的常规，事例连贯上下片，不在分片处分层。之所以如此，乃是因作者平时胸中郁积事多，有触而发，非特定题目所能限制，故同类事件纷至涌集，而不为普通的诗文格式所束缚。\n\n　　词的开头几句：“绿树听鹈鴂，更那堪、鹧鸪声住，杜鹃声切。啼到春归无寻处，苦恨芳菲都歇。”采用了兴与赋相结合的创作手法。实中有虚，虚中有实。说它是“赋”，因为它写送别茂嘉，是在春去夏来的时候，可以同时听到三种鸟声，是写实。鹈鴂，一说是杜鹃，一说是伯劳，辛弃疾取伯劳之说；说它是“兴”，因为它借闻鸟声以兴起良时丧失、美人迟暮之感。伯劳在夏至前后出鸣，故暗用《离骚》“恐鹈鴂之先鸣兮，使夫百草为之不芳”意，以兴下文“苦恨”句。鹧鸪鸣声像“行不得也哥哥”；杜鹃传说为蜀王望帝失国后魂魄所化，常悲鸣出血，声像“不如归去”。词同时用这三种悲鸣的鸟声起兴，形成强烈的悲感气氛，并寄托了自己的悲痛心情。接着“算未抵、人间离别”一句，是上下文转接的关键。\n\n　　它把“离别”和啼鸟的悲鸣作一比较，以抑扬的手法承上启下，为下文出的“别恨”作了铺垫。“马上琵琶关塞黑，更长门翠辇辞金阙”两句，有人认为写的是两事：其一指汉元帝宫女王昭君出嫁匈奴呼韩邪单于离开汉宫的事；其二指汉武帝的陈皇后失宠时辞别“汉阙”，幽闭长门宫。也有认为只写一事的，谓王昭君自冷宫出而辞别汉阙。今从多数注释本作两件事看，“看燕燕，送归妾”，写的是春秋时卫庄公之妻庄姜，“美而无子”，庄公妾戴妫生子完，庄公死后，完继立为君。州吁作乱，完被杀，戴妫离开卫国。《诗经·邶风》的《燕燕》诗，相传即为庄姜送别戴妫而作。“将军百战身名裂。向河梁、回头万里，故人长绝”，引用了汉代另一个典故。汉李陵抗击匈奴，力战援绝，势穷投降，败其家声；他的友人苏武出使匈奴，被留十九年，守节不屈。后来苏武得到归汉机会，李陵送他有“异域之人，一别长绝”之语；又世传李陵《与苏武诗》，有“携手上河梁”、“长当从此别”等句。“易水萧萧西风冷，满座衣冠似雪。正壮士、悲歌未彻”，写战国时燕太子丹在易水边送荆轲入秦行刺秦王政故事。相传送行者都穿戴白衣冠，荆轲临行歌唱：“风萧萧兮易水寒，壮士一去兮不复还。”以上这些事都和远适异国、不得生还，以及身受幽禁或国破家亡之事有关，都是极悲痛的“别恨”。这些故事，写在与堂弟的一首送别词中，强烈地表达了作者当时沉重、悲壮之情。\n\n　　“啼鸟还知如许恨，料不啼清泪长啼血。”这又是承上启下的两句。句中说啼鸟只解春归之恨，如果也能了解人间的这些恨事，它的悲痛一定更深，随啼声眼中滴出的不是泪而是血了。为下句转入送别正题作了省力的铺垫。“谁共我，醉明月？”承上面两句转接机势，迅速地归结到送别茂嘉的事，点破题目，结束全词，把上面大片凌空驰骋的想象和描写，一下子收拢到题中来，有此两句，词便没有脱离本题，只是显得善于大处落墨、别开生面而已。由此可以看出，辛弃疾不愧为宋代一代文豪！\n\n　　辛弃疾的这首词，之所以感人，除了其感情、气氛强烈外，还得力于它的音节。它押入声的曷、黠、屑、叶等韵，在“切响”与“促节”中有很强的摩擦力量，声如裂帛，声情并至。古人对此词推崇备至。', poem_tags = '宋词三百首,宋词精选,豪放,送别,写鸟,抒情' WHERE poem_title = '贺新郎·别茂嘉十二弟' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '译文一\n群山依旧，环绕着废弃的故都，潮水如昔，拍打着寂寞的空城。\n淮水东边，古老而清冷的圆月，夜半时分，窥视这昔日的皇宫。\n\n译文二\n城的东、南、西三面，依旧绵亘着高低起伏的群山，它那虎踞龙盘的姿态并未改变；北面的江潮，依旧拍打着城根，而后带着寂寞的心情退回。那声音仿佛在叹惜，昔日的繁华已经化为乌有。\n从秦淮河东边升起的，还是过去那轮月亮。见证历史过后，在夜深人静之际，又心恋恋地爬过凹凸的城墙，小心翼翼来窥探着什么。', poem_notes = '石头城：位于今南京市西清凉山上，三国时孙吴就石壁筑城戍守，称石头城。后人也每以石头城指建业。曾为吴、东晋、宋、齐、梁、陈六朝都城，至唐废弃。今为南京市。\n故国：即旧都。石头城在六朝时代一直是国都。\n周遭：环绕。\n淮水：指贯穿石头城的秦淮河。\n旧时：指汉魏六朝时。\n女墙：指石头城上的矮城。', poem_appreciation = '李白《苏台览古》有句云：“只今惟有西江月，曾照吴王宫里人。”\n\n　　谓苏台已废，繁华已歇，惟有江月不改。其得力处在“只今惟有”四字。刘禹锡此诗也写江月，却并无“只今惟有”的限制词的强调，也无对怀古内容的明点。一切都被包含在“旧时月”、“还过”的含蓄语言之中，溶铸在具体意象之中。而诗境更浑厚、深远。\n\n　　诗人把石头城放到沉寂的群山中写，放在带凉意的潮声中写，放到朦胧的月夜中写，这样尤能显示出故国的没落荒凉。只写山水明月，而六代繁荣富贵，俱归乌有。诗中句句是景，然而无景不融合着诗人故国萧条、人生凄凉的深沉感伤。\n\n　　寄托诗人昔日繁华无处寻觅的感慨，江城涛声依旧在，繁华世事不复再。诗人怀古抒情，希望君主能以前车之覆为鉴。\n\n　　白居易读了《石头城》一诗，赞美道：“我知后之诗人无复措词矣。”后来有些金陵怀古诗词受它的影响，化用它的意境词语，恰也成为名篇。如元萨都剌的《念奴娇》中“指点六朝形胜地，惟有青山如壁”、“伤心千古，秦淮一片明月”就是著例；而北宋周邦彦的《西河》词，更是以通篇化用《石头城》、《乌衣巷》诗意为能事了。', poem_tags = '咏物,地名,咏史怀古' WHERE poem_title = '金陵五题·石头城' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '被你抛弃而被迫出走，犹如那孤苦的白兔，往东去却又往西顾。\n旧的衣服不如新的好，人还是旧人更胜新人。', poem_notes = '茕茕（qióng qióng）：孤独无依的样子。', poem_appreciation = '这篇最初见于《太平御览》卷六百八十九，题为《古艳歌》，无作者名氏。明、清人选本往往作窦玄妻《古怨歌》。《艺文类聚》卷三十记窦玄妻事云：“后汉窦玄形貌绝异，天子以公主妻之。旧妻与玄书别曰：‘弃妻斥女敬白窦生：卑贱鄙陋，不如贵人。妾日已远，彼日已亲。何所告诉，仰呼苍天。悲哉窦生！衣不厌新，人不厌故。悲不可忍，怨不自去。彼独何人，而居是处。’”并不曾提到窦玄妻作这首歌。今仍从《太平御览》。这首诗是弃妇诗，上二句比喻自己被出而终恋故人，下二句是说服故人也应该念旧。\n\n　　乐府《古艳歌》：“茕茕（孤独，无依靠）白兔，东走西顾。衣不如新，人不如故。”这首诗的前两句即以动物起兴，兴中兼含比喻。写弃妇被迫出走，犹如孤苦的白兔，往东去却又往西顾，虽走而仍恋故人。后两句是规劝故人应当念旧。', poem_tags = '弃妇,念旧' WHERE poem_title = '古艳歌' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '小院幽深寂静，我躺在竹席上，浑身清凉；窗外的石榴花盛开，透过垂挂的竹帘，映红了虚堂。\n浓密的树阴隔断了暑气，正是中午时分，我一觉醒来，耳边传来黄莺儿断续的啼唱。', poem_notes = '别院：正院旁侧的小院。夏簟（diàn）：夏天的竹席。清：清凉。\n透帘：穿透帘子。\n觉（jué）：睡醒。', poem_appreciation = '苏舜钦这首《夏意》诗，能于盛夏炎热之时写出一种清幽之境，悠旷之情。\n\n　　“别院深深夏席清”：“夏”字点明节令，而“别院”、“深深”、“清”三词却层层深入，一开始即构成清幽的气氛。别院即正院旁侧的小院。深深，言此小院在宅庭幽深处，小院深深，曲径通幽，在这极清极静的环境中有小轩一座，竹席一领。韩愈《郑群赠簟》诗曾以“卷送八尺含风漪”、“肃肃疑有清飚吹”形容竹席。“夏席清”，正同此意，谓虽当盛夏，而小院深处，竹席清凉。深深是叠词，深深与清，韵母又相近，音质均清亮平远。这样不仅从文字形象上，更从音乐形象上给人以凉爽幽深之感。\n\n　　“石榴开遍透帘明”：“帘”字点明夏席铺展在轩屋之中。诗人欹卧于席上，闲望户外，只见榴花盛开，透过帘栊，展现着明艳的风姿。韩愈曾有句云“五月榴花照眼明”(《榴花》)，第二句化用其意，却又加上了一重帷帘。隔帘而望榴花，虽花红如火，却无刺目之感。\n\n　　陶渊明有句云：“蔼蔼堂前林，中夏贮清阴”(《和郭主簿》)。此诗第三句正由陶诗化出，谓虽当中夏亭午，而小院中仍清阴遍地，一片凉意。此句与上句设色相映，从“树阴满地”可想见绿树成林，不写树，而写阴，更显得小院之清凉宁谧。\n\n　　在这清幽的环境中诗人又在干什么呢?“梦觉流莺时一声”，原来他已为小院清景所抚慰，虽然烈日当午，却已酣然入睡，待到“梦觉”，只听得园林深处不时传来一两声流莺鸣啼的清韵。写莺声而不写黄莺本身，既见得树荫之茂密深邃，又以阒静之中时歇时现的呖呖之声，反衬出这小院的幽深宁谧。南朝王籍诗云：“鸟鸣山更幽”(《入若耶溪》)，王维《辛夷坞》：“月出惊山鸟，时鸣春涧中”。末句意境正与二诗相类。', poem_tags = '古诗三百首,夏天' WHERE poem_title = '夏意' AND poem_author = '苏舜钦';
UPDATE edu_poem SET poem_translation = '有位举世无双的美人，隐居在空旷的山谷中。\n她说自己是高门府第的女子，飘零沦落到与草木相依。\n过去关中一带遭遇战乱，家里的兄弟全被乱军杀戮。\n官居高位又有什么用？自己兄弟的尸骨都无法收埋。\n世俗人情都厌恶衰败的人家，万事就像随风而转的烛火。\n丈夫是个轻薄子弟，抛弃了我又娶了个美丽如玉的新人。\n合欢花尚且知道朝开夜合，鸳鸯鸟成双成对从不独宿。\n丈夫只看见新人欢笑，哪里听得到旧人哭泣？\n泉水在山里是清澈的，出了山就浑浊了。\n让侍女典卖珠宝维持生计，牵把青萝修补茅屋。\n摘下来的花不愿插在头上，喜欢采折满把的柏枝。\n天气寒冷，衣衫显得分外单薄，黄昏时分，独自倚在修长的竹子上。\n\n韵译\n有一个美艳绝代的佳人，隐居在僻静的深山野谷。\n她说：“我是良家的女子，零落漂泊才与草木依附。\n想当年长安丧乱的时候，兄弟遭到了残酷的杀戮。\n官高显赫又有什么用呢，不得收养我这至亲骨肉。\n世情本来就是厌恶衰落，万事象随风抖动的蜡烛。\n没想到夫婿是个轻薄儿，又娶了美颜如玉的新妇。\n合欢花朝舒昏合有时节，鸳鸯鸟雌雄交颈不独宿。\n朝朝暮暮只与新人调笑，那管我这个旧人悲哭？！”\n在山的泉水清澈又透明，出山的泉水就要浑浊浊。\n变卖首饰的侍女刚回来，牵拉萝藤修补着破茅屋。\n摘来野花不爱插头打扮，采来的柏子满满一大掬。\n天气寒冷美人衣衫单薄，夕阳下她倚着长长青竹。', poem_notes = '绝代：冠绝当代，举世无双。佳人：貌美的女子。\n幽居：静处闺室，恬淡自守。\n零落：飘零沦落。依草木：住在山林中。\n丧乱：死亡和祸乱，指遭逢安史之乱。\n官高：指娘家官阶高。\n骨肉：指遭难的兄弟。\n转烛：烛火随风转动，比喻世事变化无常。\n夫婿：丈夫。\n新人：指丈夫新娶的妻子。\n合昏：夜合花，叶子朝开夜合。\n鸳鸯：水鸟，雌雄成对，日夜形影不离。\n旧人：佳人自称。\n卖珠：因生活穷困而卖珠宝。\n牵萝：拾取树藤类枝条。也是写佳人的清贫。\n采柏：采摘柏树叶。动：往往。\n修竹：高高的竹子。比喻佳人高尚的节操。', poem_tags = '唐诗三百首,赞美,闺怨,女子' WHERE poem_title = '佳人' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '自从金人的铁蹄踏碎了祖国的河山，十年了，回望故乡洛阳，路是那么的漫长。岁月使我变得衰老不堪，今天，我独自一个，流落在青墩溪畔，在煦煦春风中，欣赏着盛开的牡丹。', poem_notes = '一自：自从。\n胡尘：指金兵。入汉关：指入侵中原。\n十年：从靖康二年（1126）金兵攻陷汴京到诗人作此诗时整整十年。\n伊洛：河南的伊水和洛水。《国语·周语》云：“昔伊洛竭而复之。”因此，“伊洛”既指诗人的故乡洛阳，又暗寓他亡国的悲痛。\n青墩：在今浙江桐乡，当时诗人所居处。\n龙钟：年老体衰，行动不便的样子，诗人自指。 时诗人四十七岁，却有老态之感。', poem_appreciation = '情感手法 　　诗人的家乡洛阳是有名的牡丹之乡。从金兵入侵中原，诗人避乱南奔，有十年之久，忽然在异乡见到了故乡的名花。诗人感慨万千，国家局势的动态和个人身世的飘零使诗人以牡丹为题，抒发了自己真挚强烈的伤时忧国之情。诗作苍凉悲感，言短意深，对故乡的怀念，对金兵的仇恨，成为强烈的弦外之音。全诗自然流畅，“用诗深隐处，读者抚卷茫然、不暇究索”（楼钥《简斋诗笺叙》）。葛胜仲所谓陈与义晚年“赋咏尤工”（《陈去非诗集序》），确非虚语。除《牡丹》诗外，陈与义还有另外一首咏物名诗《春寒》：“二月巴陵日日风，春寒未了怯园公。海棠不惜胭脂色，独立蒙蒙细雨中。”两首诗所咏之花虽异，而情怀、笔法皆同，都是写“名花苦幽独”的伤感，表现一种怀才不遇的孤独感和失意之情。 ▲', poem_tags = '古诗三百首,咏物,牡丹,思乡,爱国' WHERE poem_title = '咏牡丹' AND poem_author = '陈与义';
UPDATE edu_poem SET poem_translation = '冬天的夜晚，来了客人，用茶当酒，吩咐小童煮茗，火炉中的火苗开始红了起来了，水在壶里沸腾着，屋子里暖烘烘的。\n月光照射在窗前，与平时并没有什么两样，只是窗前有几枝梅花在月光下幽幽地开着，芳香袭人。这使得今日的月色显得与往日格外地不同了。', poem_notes = '竹炉：指用竹篾做成的套子套着的火炉。 　\n汤沸：热水沸腾。\n元朝揭傒斯《寒夜》：\n疏星冻霜空，流月湿林薄。\n虚馆人不眠，时闻一叶落。\n当代阿袁（即陈忠远）《寒夜》：\n“大国何人怜，纷纷为小我。寒夜风雨声，广厦万间破。“', poem_appreciation = '这首诗因为被《千家诗》选入，所以流传很广，几乎稍读过些古诗的人都能背诵，“寒夜客来茶当酒”，几被当作口头话来运用。常在口头的话，说的时候往往用不着思考，脱口而出，可是细细品味，总是有多层转折，“寒夜客来茶当酒”一句，就可以让人产生很多联想。首先，客人来了，主人不去备酒，这客人必是熟客，是常客，可以“倚杖无时夜敲门”，主人不必专门备酒，也不必因为没有酒而觉得怠慢客人。其次，在寒冷的夜晚，有兴趣出门访客的，一定不是俗人，他与主人定有共同的语言，共同的雅兴，情谊很深，所以能与主人寒夜煮茗，围炉清谈，不在乎有酒没酒。\n\n　　前两句，诗人与客人夜间在火炉前，火炉炭火刚红，壶中热水滚滚，主客以茶代酒，一起喝着芳香的浓茶，向火深谈；而屋外是寒气逼人，屋内是温暖如春，诗人的心情也与屋外的境地迥别。三、四句便换个角度，以写景融入说理。夜深了，明月照在窗前，窗外透进了阵阵寒梅的清香。这两句写主客在窗前交谈得很投机，却有意无意地牵入梅花，于是心里觉得这见惯了的月色也较平常不一样了。诗人写梅，固然有赞叹梅花高洁的意思在内，更多的是在暗赞来客。寻常一样窗前月，来了志同道合的朋友，在月光下啜茗清谈，这气氛可就与平常大不一样了。\n\n　　诗看似随笔挥洒，但很形象地反映了诗人喜悦的心情，耐人寻味。宋黄昇《玉林清话》对三、四句很赞赏，并指出苏泂《金陵》诗“人家一样垂杨柳，种在宫墙自不同”与杜耒诗意思相同，都意有旁指，可说真正读出了诗外之味。', poem_tags = '古诗三百首,访友,写花,梅花,月色' WHERE poem_title = '寒夜' AND poem_author = '杜耒';
UPDATE edu_poem SET poem_translation = '往平地上倒水，水会向不同方向流散一样，人生贵贱穷达是不一致的。\n人生是既定的，怎么能成天自怨自哀。\n喝点酒来宽慰自己，歌唱《行路难》，歌唱声因举杯饮酒而中断。\n人心又不是草木，怎么会没有感情？欲说还休，欲行又止，不再多说什么。', poem_notes = '“泻水”二句：往平地上倒水，水流方向不一喻人生贵贱穷达是不一致的。 泻，倾,倒。\n“举杯”句：这句是说《行路难》的歌唱因饮酒而中断。\n吞声：声将发又止。从“吞声”、“踯躅”、“不敢”见出所忧不是细致的事。\n踯躅（zhí zhú）：徘徊不前。\n举杯断绝歌路难：因要饮酒而中断了《行路难》的歌唱。断绝：停止。\n断绝：停止', poem_appreciation = '这首“泻水置平地”是鲍照《拟行路难》中的第四篇，抒写诗人在门阀制度重压下，深感世路艰难激发起的愤慨不平之情，其思想内容与原题妙合无垠。\n\n　　诗歌起笔陡然，入手便写水泻地面，四方流淌的现象。既没有波涛万顷的壮阔场面，也不见澄静如练的幽美意境。然而，就在这既不神奇又不玄妙的普通自然现象里，诗人却顿悟出了与之相似相通的某种人生哲理。作者运用的是以“水”喻人的比兴手法，那流向“东西南北”不同方位的“水”，恰好比喻了社会生活中高低贵贱不同处境的人。“水”的流向，是地势造成的；人的处境，是门第决定的。因此说，起首两句，通过对泻水的寻常现象的描写，形象地揭示出了现实社会里门阀制度的不合理性。诗人借水“泻”和“流”的动态描绘，造成了一种令读者惊疑的气势。正如清代沈德潜所说：“起手万端下，如黄河落天走东海也。”这种笔法，正好曲折地表达了诗人由于激愤不平而一泻无余的悲愤抑郁心情。\n\n　　接下四句，诗人转向自己的心态剖白。他并没有直面人间的不平去歌呼呐喊，而是首先以“人生亦有命”的宿命论观点，来解释社会与人生的错位现象，并渴望借此从“行叹复坐愁”的苦闷之中求得解脱。继而又以“酌酒以自宽”来慰藉心态失去的平衡。然而，举杯消愁愁更愁，就连借以倾吐心中悲愤的《行路难》歌声，也因“举杯”如鲠在喉而“断绝”了。这里诗人有意回避了正面诉说自己的悲哀和苦闷，胸中郁积的块垒，已无法借酒浇除，他便着笔于如何从怅惘中求得解脱，在烦忧中获得宽慰。这种口吻和这笔调，愈加透露出作者深沉浓重的愁苦悲愤的情感，造成了一种含蓄不露，蕴藉深厚的艺术效果。\n\n　　诗的结尾，作者才吐出真情。“心非木石岂无感”，人心不是草木，不可能没有感情，诗人面对社会的黑暗，遭遇人间的不平，不可能无动于衷，无所感慨。写到这里，诗人心中的愤懑，已郁积到最大的密度，达到了随时都可能喷涌的程度。不尽情宣泄，不放声歌唱，已不足以倾吐满怀的愁苦了。然而出人意料的是，下面出现的却是一声低沉的哀叹：“吞声踯躅不敢言！”到了嘴边的呼喊，却突然“吞声”强忍，“踯躅”克制住了。社会政治的黑暗，残酷无情的统治，窒息着人们的灵魂。社会现实对于寒微士人的压抑，已经到了让诗人敢怒而不敢言、徘徊难进的地步了。有许许多多像诗人一样出身寒微的人，也只能像他那样忍气吞声，默默地把愤怒和痛苦强咽到肚里，这正是人间极大的不幸。而这种不幸的根源，已经是尽在言外，表现得很清楚了。所以，前文中“人生亦有命”的话题，也只是诗人在忍气吞声和无可奈何之下所倾吐的愤激之词。\n\n　　这首诗托物寓意，比兴遥深，而又明白晓畅，达到了启人思索、耐人品味的艺术境界。从作者的表达情感方式来说，全篇构思迂曲婉转，蕴藉深厚。明代王夫之评论此诗说：“先破除，后申理，一俯一仰，神情无限。”清代沈德潜评价说：“妙在不曾说破。”准确地指明了这首诗的艺术特点。伴随感情曲折婉转的流露，五言、七言诗句错落有致地相互搭配，韵脚由“流”、“愁”到“难”、“言”的灵活变换，这一切，便自然形成了全诗起伏跌宕的气势格调。\n\n　　沈得潜说，此诗“妙在不曾说破，读之自然生愁。”', poem_tags = '古诗三百首,托物抒怀,哲理' WHERE poem_title = '拟行路难·其四' AND poem_author = '鲍照';
UPDATE edu_poem SET poem_translation = '怀念你竟在这深秋的夜晚，散步咏叹多么寒凉的霜天。\n想此刻空山中正掉落松子，幽居的友人一定还未安眠。', poem_notes = '丘二十二员外：名丹，苏州人，曾拜尚书郎，后隐居平山上。一作“邱二十二员外”。\n属：正值，适逢，恰好。\n幽人：幽居隐逸的人，悠闲的人，此处指丘员外。', poem_appreciation = '韦应物的五言绝句，一向为诗论家所推崇。胡应麟在《诗薮》中说：“中唐五言绝，苏州最古，可继王、孟。”沈德潜在《说诗晬语》中说：“五言绝句，右丞之自然、太白之高妙、苏州之古淡，并入化境。”上面这首诗是他的五绝代表作之一。它给予读者的艺术享受，首先就是这一古雅闲淡的风格美。施补华在《岘佣说诗》中曾称赞这首诗“清幽不减摩诘，皆五绝中之正法眼藏也”。它不以强烈的语言打动读者，只是从容下笔，淡淡着墨，而语浅情深，言简意长，使人感到韵味悠永，玩绎不尽。\n\n　　如果就构思和写法而言，这首诗还另有其值得拈出之处。它是一首怀人诗。前半部分写诗人自己，即怀念友人之人；后半部分写正在临平山学道的丘丹，即诗人所怀念之人。首句“怀君属秋夜”，点明季节是秋天，时间是夜晚，而这“秋夜”之景与“怀君”之情，正是彼此衬映的。次句“散步咏凉天”，承接自然，全不着力，而紧扣上句。“散步”是与“怀君”相照应的：“凉天”是与“秋夜”相绾合的。这两句都是写实，写出了作者因怀人而在凉秋之夜徘徊沉吟的情景。接下来，作者不顺情抒写，就景描述，而把诗思飞驰到了远方，在三、四两句中，想象所怀念之人在此时、彼地的状况。而这三、四两句又是紧扣一、二两句的。第三句“山空松子落”，遥承“秋夜”、“凉天”，是从眼前的凉秋之夜，推想临平山中今夜的秋色。第四句“幽人应未眠”，则遥承“怀君”、“散步”，是从自己正在怀念远人、徘徊不寐，推想对方应也未眠。这两句出于想象，既是从前两句生发，而又是前两句诗情的深化。从整首诗看，作者运用写实与虚构相结合的手法，使眼前景与意中景同时并列，使怀人之人与所怀之人两地相连，进而表达了异地相思的深情。\n\n　　陆机在《文赋》中指出，作者在构思时，可以“观古今于须臾，抚四海于一瞬”。刘勰在《文心雕龙·神思篇》中也说：“文之思也，其神远矣。故寂然凝虑，思接千载；悄焉动容，视通万里。”这些话说明文思是最活跃的，是不受时空限制的。因此，在诗人笔下，同一空间里，可以呈现不同的时间；同一时间里，也可以呈现不同的空间。像王播的《题木兰院》：“三十年前此院游，木兰花发院新修；如今再到经行处，树老无花僧白头”，就属于前者。而这首韦应物的怀人诗，则属于后者。现代的电影艺术，有时采用叠影手法来处理回忆与遥想的镜头，有时使银幕上映出两上或两个以上的画面，使观众同时看到在两个或两个以上的空间或时间里出现的不同场景。这首诗运用的手法正与此相同。它使读者在一首诗中看到两个空间，既看到怀人之人，也看到被怀之人，既看到作者身边之景，也看到作者遥想之景，从而把异地相隔的人和景并列和相连在一起，说明千里神交，有如晤对，故人虽远在天涯，而想思却近在咫尺。', poem_tags = '唐诗三百首,秋天,怀人' WHERE poem_title = '秋夜寄邱员外 / 秋夜寄丘二十二员外' AND poem_author = '韦应物';
UPDATE edu_poem SET poem_translation = '我的头发刚刚盖过额头，便同你一起在门前做折花的游戏。\n你骑着竹马过来，我们一起绕着井栏，互掷青梅为戏。\n我们同在长干里居住，两个人从小都没什么猜忌。\n十四岁时嫁给你作妻子，害羞得没有露出过笑脸。\n低着头对着墙壁的暗处，一再呼唤也不敢回头。\n十五岁才舒展眉头，愿意永远和你在一起。\n常抱着至死不渝的信念，怎么能想到会走上望夫台？\n十六岁时你离家远行，要去瞿塘峡滟滪堆。\n五月水涨时，滟滪堆不可相触，两岸猿猴的啼叫声传到天上。\n门前是你离家时徘徊的足迹，渐渐地长满了绿苔。绿苔太厚，不好清扫，树叶飘落，秋天早早来到。\n八月里，黄色的蝴碟飞舞，双双飞到西园草地上。\n看到这种情景我很伤心，因而忧愁容颜衰老。\n无论什么时候你想下三巴回家，请预先把家书捎给我。\n迎接你不怕道路遥远，一直走到长风沙。', poem_notes = '长干行：属乐府《杂曲歌辞》调名。下篇一作张潮。黄庭坚作李益诗。\n床：井栏，后院水井的围栏。\n长干里：在今南京市，当年系船民集居之地，故《长干曲》多抒发船家女子的感情。\n抱柱信：典出《庄子·盗跖篇》，写尾生与一女子相约于桥下，女子未到而突然涨水，尾生守信而不肯离去，抱着柱子被水淹死。\n滟滪堆：三峡之一瞿塘峡峡口的一块大礁石，农历五月涨水没礁，船只易触礁翻沉。\n天上哀：哀一作“鸣”。\n迟行迹：迟一作“旧”。\n生绿苔：绿一作“苍”。\n蝴蝶来：一作“蝴蝶黄”。清王琦《李太白文集注》云：“杨升庵谓蝴蝶或白或黑，或五彩皆具，唯黄色一种至秋乃多，盖感金气也，引太白‘八月蝴蝶黄’一句，以为深中物理，而评今本‘来’字为浅。琦谓以文义论字，终以‘来’字为长。”作‘黄’字亦有道理。\n早晚：多早晚，犹何时。三巴：地名。即巴郡、巴东、巴西。在今四川东部地区。\n长风沙：地名，在今安徽省安庆市的长江边上，距南京约700里。', poem_tags = '唐诗三百首,妇女,生活,怀远' WHERE poem_title = '长干行·其一' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '满载着一船的秋色，行驶在广阔平展的江面上。行船被风浪所阻，微风吹起鳞鳞波浪，泛起波光。明日风向转为顺风更加好，那么今夜露宿又有什么关系呢？水中的宫殿像是在演奏霓裳羽衣曲，当到达岳阳时，准定在岳阳楼上观赏湖光山色。', poem_notes = '山峰：指黄陵山。（黄陵山在湖南湘阴县北洞庭湖边。湘水由此入湖。相传山上有舜之二妃娥皇、女英的庙，世称黄陵庙。词题一作“黄陵庙”。词句也稍有差异）\n鳞鳞：形容波纹细微如鱼鳞。\n风回：指风向转为顺风。\n水晶宫：古代传说水中的宫殿。\n霓裳：即《霓裳羽衣曲》，唐代著名乐舞名。', poem_appreciation = '《西江月·阻风山峰下》上片写行船遇风受阻，泊舟山下的所见与感受。\n\n　　“满载一船秋色，平铺十里湖光。”开头两句，写风尚未起时的风光。“一船秋色”由作者的感受着笔，勾勒出时令特征，引人遐想，可以想见，此时周围的山色浓郁苍翠，万物生机勃勃，开花的花朵艳丽，结果的果实累累；“十里湖光”写出湖面宽广坦荡。这两个对偶句用“满载”和“平铺”相对，将湖光和山色一并画出，前句说美丽的秋景尽收眼底；后句说无风时湖水平稳，远远望去，就象“平铺”在那儿。水光山色，交相辉映，船上人心旷神怡，其乐无穷。此二句纯属写景，而作者张孝祥欣悦之情尽在其中，即所谓景中有情。\n\n　　“波神”二句说，水神有意留住我观看夕阳西下的美丽景色，放起鱼鳞般的波纹。这是写的天气咋变，微风初起时的湖上景色，也是变天的前兆。有经验的船工势必要抛锚停舟，采取应急措施，因为这霞光辉映，“鳞鳞细浪”过后，将是范仲淹在《岳阳楼记》中描写的“浊浪排空”、“樯倾楫摧”的恶劣天气。这两句以幽默的手法写航船遇风受阻被迫停泊的情景，反衬出作者此时的心境十分安闲自在。用“斜阳”点明时间是傍晚，以“细浪”说明天气变化，要起风，皆是妙笔。\n\n　　《西江月·阻风山峰下》下片写停船后作者的心里活动。“明日风回更好”，写他期待风向回转，天气变好，及时登程的心情。“今宵露宿何妨？”“何妨”，犹言“有什么关系呢”，实际上是无可奈何的话，但也表现了他在迫不得已的情况下“露宿”时的旷达胸襟。“水晶宫里奏霓裳”，“水晶宫”，俗谓“龙宫”；“霓裳”，即《霓裳羽衣曲》，一支大型歌舞曲的名字。作者听到阵阵波涛声，奇特的想象油然而生，把水声比喻作龙宫的音乐。龙宫既然奏欢庆之乐，明日准是好天气，航船正常前进，“准拟岳阳楼上”，尾句设想，明天准能在岳阳楼上欣赏洞庭湖的美景胜状。\n\n　　《西江月·阻风山峰下》写航船遇风受阻的情景，写景、抒情，乃至对“明日”的设想，着笔轻松，无半点沮丧之处。\n\n　　《西江月·阻风山峰下》全词语言浅易而意境幽雅，读来只觉作者张孝祥对山水无限热爱，却不见船遇逆风受阻的懊恼，这是此词的特色，作者张孝祥构思独到之处。', poem_tags = '宋词三百首,山水,写风' WHERE poem_title = '西江月·阻风山峰下' AND poem_author = '张孝祥';
UPDATE edu_poem SET poem_translation = '铸有狻猊提钮的铜炉里，熏香已经冷透，红色的锦被乱堆床头，如同波浪一般，我也无心去收。早晨起来，懒洋洋不想梳头。任凭华贵的梳妆匣落满灰尘，任凭朝阳的日光照上帘钩。我生怕想起离别的痛苦，有多少话要向他倾诉，可刚要说又不忍开口。新近渐渐消瘦起来，不是因为喝多了酒，也不是因为秋天的影响。算了罢，算了罢，这次他必须要走，即使唱上一万遍《阳关》离别曲，也无法将他挽留。想到心上人就要远去，剩下我独守空楼了，只有那楼前的流水，应顾念着我，映照着我整天注目凝眸。就在凝眸远眺的时候，从今而后，又平添一段日日盼归的新愁。', poem_notes = '金猊(ni泥)：狮形铜香炉。\n红浪：红色被铺乱摊在床上，有如波浪。\n宝奁(lian连)：华贵的梳妆镜匣。\n者：通这。\n阳关：语出《阳关三叠》，是唐宋时的送别曲。此处泛指离歌。\n武陵人远：此处借指爱人去的远方。烟锁秦楼：总谓独居妆楼。\n秦楼：即凤台，相传春秋时秦穆公女弄玉与其夫箫史乘风飞升之前的住所。\n眸（móu）：指瞳神。指眼珠。', poem_appreciation = '这首词是李清照抒写离愁的名篇之一。下面是中华诗词学会理事徐培均先生对此词的赏析要点。\n\n　　词写离情，却略去了别时，只是截取了别前和别后两个横断面，加以深入地开掘。开头一个对句“香冷金猊，被翻红浪”，便给人冷漠凄清的感觉。金猊，指狻猊（狮子）形铜香炉。“被翻红浪”，语本柳永《凤栖梧》：“鸳鸯绣被翻红浪。”说的是锦被胡乱地摊在床上，在晨曦的映照下，波纹起伏，恍似卷起层层红色的波浪。金炉香冷，反映了词人在特定心情下的感受；锦被乱陈，是她无心折叠所致。“起来慵自梳头”，则全写人物的情绪和神态。这三句工炼沉稳，在舒徐的音节中寄寓着作者低沉掩抑的情绪。到了“任宝奁尘满，日上帘钩”，则又微微振起，恰到好处地反映了词人情绪流程中的波澜。然而她内心深处的离愁还未显露，给人的印象只是慵怠或娇慵。慵者，懒也。炉中香消烟冷，无心再焚，一慵也；床上锦被乱陈，无心折叠，二慵也；髻鬟蓬松，无心梳理，三慵也；宝镜尘满，无心拂拭，四慵也；而日上三竿，犹然未觉光阴催人，五慵也。慵而一“任”，则其慵态已达极点。词人为何大写“慵”字，目的仍在写愁。这个“慵”字是“词眼”，使读者从人物的慵态中感到她内心深处有个愁在。\n\n　　“生怕离怀别苦”，开始切题，可是紧接着，作者又一笔宕开，“多少事，欲说还休”，万种愁情，一腔哀怨，本待在丈夫面前尽情倾吐，可是话到嘴边，又吞咽下去。词情又多了一层波折，愁苦又加重了一层。\n\n　　“新来瘦，非干病酒，不是悲秋。”她先从人生的广义概括致瘦的原因：有人是因“日日花前常病酒”（冯延巳《鹊踏枝》），有人是因“万里悲秋常作客”（杜甫《登高》），而自己却是因为伤离惜别这种不足与旁人道的缘由。\n\n　　从“悲秋”到“休休”，是大幅度的跳跃。词人一下子从别前跳到别后，略去话别的缠绵和饯行的伤感，笔法极为精炼。“休休！这回去也，千万遍《阳关》，也则难留。”《阳关》，即《阳关曲》。离歌唱了千千遍，终是难留，惜别之情，跃然纸上。“念武陵人远，烟锁秦楼”，把双方别后相思的感情作了极其精确的概括。武陵人，用刘晨、阮肇典故，借指心爱之人。秦楼，一称凤楼、凤台。相传春秋时有个萧史，善吹箫，作凤鸣，秦穆公以女弄玉妻之，筑凤台以居，一夕吹箫引凤，夫妇乘凤而去。李清照化此典，既写她对丈夫赵明诚的思念，也写赵明诚对其妆楼的凝望，丰富而又深刻。同时后一个典故，还暗合调名，照应题意。\n\n　　下片后半段用顶真格，使各句之间衔接紧凑，而语言节奏也相应地加快，感情的激烈程度也随之增强，使词中所写的“离怀别苦”达到了高潮。“惟有楼前流水”句中的“楼前”，是衔接上句的“秦楼”，“凝眸处”是紧接上句的“凝眸”。把它们连起来吟诵，便有一种自然的旋律推动吟诵的速度，而哀音促节便在不知不觉中搏动人们的心弦。古代写倚楼怀人的不乏佳作，却没有如李清照写得这样痴情的。她心中的“武陵人”越去越远了，人影消失在迷蒙的雾霭之中，她一个人被留在“秦楼”，呆呆地倚楼凝望。她那盼望的心情，无可与语；她那凝望的眼神，无人理解。唯有楼前流水，映出她终日倚楼的身影，印下她钟情凝望的眼神。词笔至此，主题似已完成了，而结尾三句又使情思荡漾无边，留有不尽意味。自从得知赵明诚出游的消息，她就产生了“新愁”，此为一段；明诚走后，洞房空设，佳人独坐，此又是“新愁”一段。从今而后，山高路远，枉自凝眸，其愁将与日俱增，愈发无从排遣了。\n\n　　这首词写离愁，步步深人，层次井然。前片用“慵”来点染，用“瘦”来形容；后片用“念”来深化，用“痴”来烘托，由物到人，由表及里，层层开掘，揭示到人物灵魂的深处。而后片的“新愁”与前片的“新瘦”遥相激射，也十分准确地表现了“离怀别苦”的有增无已。在结构上，特别要注意“任宝帘尘满”中的“任”字，“念武陵人远”中的“念”字。这是两个去声领格字，承上启下，在词中起着关键性的转捩作用。从语言上看，除了后片用了两个典故外，基本上是从生活语言中提炼出来的，自然中节，一片宫商，富有凄婉哀怨的音乐色彩。前人所谓“以浅俗之语，发清新之思”（邹袛谟《远志斋词衷》），信不虚也！', poem_tags = '宋词三百首,宋词精选,婉约,女子,离别,思念' WHERE poem_title = '凤凰台上忆吹箫·香冷金猊' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '王杨卢骆开创了一代诗词的风格和体裁，浅薄的评论者对此讥笑是无止无休的。待你辈的一切都化为灰土之后，也丝毫无伤于滔滔江河的万古奔流。', poem_notes = '戏为：戏作。其实杜甫写这六首诗态度是很严肃的，议论也是可取的。六绝句：六首绝句。\n王杨卢骆：王勃、杨炯、卢照邻、骆宾王。这四人擅长诗文，对初唐的文学革新有过贡献，被称为 “初唐四杰”。\n体：这里指诗文的风格而言。当时体：那个时代的风格体裁。\n哂：讥笑。\n尔曹：彼辈，指那些轻薄之徒。', poem_tags = '励志,文学,观点' WHERE poem_title = '戏为六绝句·其二' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '徒然听到传说，海外还有九州，来生未可预知，今生就此罢休。\n空听到禁卫军，夜间击打刀斗，不再有宫中鸡人，报晓敲击更筹。\n六军已经约定，全都驻马不前，遥想当年七夕，我们还嗤笑织女耕牛。\n如何历经四纪，身份贵为天子，却不及卢家夫婿，朝朝夕夕陪伴莫愁。', poem_notes = '战国时齐国的邹衍曾宣扬“大九州”之说，声言除中国的九州外，海外还有九个同样的“九州”。\n杨贵妃死后，有术士说在海外的仙山找到了她，并带回金钗之类的装饰物给唐玄宗看。这句有讽刺唐玄宗\n痴心空想的意思。徒闻，空闻，指没有根据的传闻。\n传说唐玄宗和杨贵妃曾誓约“世世为夫妻”。这句是说，不管来生怎样，今生的夫妻缘分已经断了。\n虎旅，指跟随唐玄宗赴蜀的禁卫军。宵柝，夜间巡逻时用的梆子。\n鸡人：皇宫中报时的卫士。汉代制度，宫中不得畜鸡，卫士候于朱雀门外，传鸡唱。筹：计时的用具。\n天宝十五年（756）六月十四日，随唐玄宗西行的军队在马嵬驿哗变，杀死杨国忠，并要求杀死杨贵妃。\n当年李、杨在长生殿盟誓恩爱，朝朝暮暮，还笑话天上的牛郎织女一年只能相会一个夜晚。\n四十八年。古人以木星绕日一周（十二年）为一纪。玄宗实际在位四十五年。\n南朝乐府歌辞《河东之水歌》：“莫愁十三能织绮，十四采桑南陌头，十五嫁为卢家妇，十六生儿字阿\n侯。“此以平民女子莫愁婚嫁生活的幸福与帝、妃的爱情悲剧对比。', poem_appreciation = '这是一首政治讽刺诗，锋芒指向了李唐前朝皇帝唐玄宗。\n\n　　一开头夹叙夹议，先用“海外”“更九州”的故事概括方士在海外寻见杨妃的传说，而用“徒闻”加以否定。“徒闻”者，徒然听说也。意思是：玄宗听方士说杨妃在仙山上还记着“愿世世为夫妇”的誓言，“十分震悼”，但这有什么用？“他生”为夫妇的事渺茫“未卜”；“此生”的夫妇关系却已分明结束了。怎么结束的，自然引起下文。\n\n　　次联用宫廷中的“鸡人报晓筹”反衬马嵬驿的“虎旅传宵柝”，昔乐今苦、昔安今危的不同处境和心情已跃然纸上。“虎旅传宵柝”的逃难生活很不安适，这是一层意思。和“鸡人报晓筹”相映衬，暗示主人公渴望重享昔日的安乐，这又是一层意思。再用“空闻”和“无复”相呼应，表现那希望已幻灭，为尾联蓄势，这是第三层意思。“虎旅传宵柝”本来是为了巡逻和警卫，而冠以“空闻”，意义就适得其反。从章法上看，“空闻”上承“此生休”，下启“六军同驻马”。意思是：“虎旅”虽“传宵柝”，却不是为了保卫皇帝和贵妃的安全，而是要发动兵变了。正因为如此，才“无复鸡人报晓筹”，李、杨再不可能享受安适的宫廷生活了。\n\n　　第三联的：“此日”指杨妃的死日。“六军同驻马”与白居易《长恨歌》“六军不发无奈何”同意，但《长恨歌》紧接着写了“宛转蛾眉马前死”，而“此日”即倒转笔锋追述“当时”。“当时”与“此日”对照、补充，不仅其意自明，而且笔致跳脱，蕴含丰富，这叫“逆挽法”。玄宗“当时”七夕与杨妃“密相誓心”，讥笑牵牛、织女一年只能相见一次，而他们两人则要“世世为夫妇”，永远不分离，可在遇上“六军不发”的时候，结果又如何？两相映衬，杨妃赐死的结局就不难于言外得之，而玄宗虚伪、自私的精神面貌也暴露无遗。同时，“七夕笑牵牛”是对玄宗迷恋女色、荒废政事的典型概括，用来对照“六军同驻马”，就表现出二者的因果关系。没有“当时”的荒淫，哪有“此日”的离散？而玄宗沉溺声色之“当时”，又何曾虑及“赐死”宠妃之“此日“！行文至此，尾联的一句已如箭在弦。\n\n　　尾联也包含强烈的对比。一方面是当了四十多年皇帝的唐玄宗保不住宠妃，另一方面是作为普通百姓的卢家能保住既“织绮”、又能“采桑”的妻子莫愁。诗人由此发出冷峻的诘问：为什么当了四十多年的皇帝唐玄宗还不如普通百姓能保住自己的妻子呢？前六句诗，其批判的锋芒都是指向唐玄宗的。用需要作许多探索才能作出全面回答的一问作结，更丰富了批判的内容。', poem_tags = '爱情,讽刺' WHERE poem_title = '马嵬·其二' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '雨后初晴，傍晚淡烟弥漫，碧绿的春水涨满新池。双燕飞回柳树低垂的庭院，小小的阁楼里画帘高高卷起。\n黄昏时独自倚着朱栏，西南天空挂着一弯如眉的新月。台阶上的落花随风飞舞，罗衣显得格外寒冷。', poem_notes = '砌：台阶。\n特地：特别。\n砌：台阶。\n朱阑：一作“朱栏”，红色的栏杆。', poem_appreciation = '这是一首抒写闺情的词作，写的是一个少妇在暮春时节的一个黄昏，思念亲人并等待他归来的情景。\n\n　　词的上片写明节候、环境以及这位少妇所见的景物特色。\n\n　　“雨晴烟晚，绿水新池满”一个“晚”字点名时间；“绿水”二字交待气候-----此时正值春天。这两句乃是写寻常春景：雨后放晴，夕阳残照，烟霭空濛一片，暮色中但见新池绿水盈盈，这景色春意盎然。这是女主人公乍一放眼就看到的自然美，与一般人的赏春并没有什么不同，还未充分显现出她观景的独特感受。\n\n　　“双燕飞来垂柳院，小阁画帘高卷”作者在写景中表现主人公观景有一个心理过程。她乍一看春色挺美，但继而看到暮色中归来的双燕在种着垂柳的庭院中翻飞盘旋，她的心弦就被触动了，与前面两句不自觉地感到春景之美就有些不同。燕子尚能在傍晚双双归巢，那么人呢，作者没有明说，只是写这位少妇把阁中画帘高高卷起。她的卷帘，既是为了更清楚地看双飞燕，也是为了使燕子进入画梁栖宿。这一无言的卷帘动作，蕴含着她的独特而微妙的心情，既有对成双晚归的燕子的羡慕，也有只见归燕而不见归人的怨怅。双燕在这里有鲜明的映衬作用，微露了她的复杂心境。在词中，用双飞燕、双鹧鸪、双飞蝶、双鸳鸯等形象来衬托女子的孤独感，是常见的，这里也是如此。至此读者看到春色虽美，但在女主人公眼中却有一个转折，从一般的观赏到融入自己的生活体验，赏景中那种希望成双团聚的潜意识觉醒了。\n\n　　词的下片以女主人为中心，描绘她孤独凄冷的处境。\n\n　　“黄昏独倚朱阑，西南新月眉弯。”上片之景原来都为女主人公独倚栏所见，“黄昏”对应上片的“晚”，“独倚”与上片“双飞”对举，点明她的孤单处境。那么，她黄昏倚栏是为了眺望远景吗？自然不是黄昏时分，大地一片模糊，还能看见什么呢，她是在盼望远人归来。“西南新月眉弯，”月出于东而落于西，她自黄昏独倚，直到月色偏西，可见其倚栏之久，盼望之切。\n\n　　“砌下落花风起，罗衣特地春寒。”从卷帘望飞燕到倚阑盼归人而望月，地点是不断移动的。此刻人依然未归，她又来到了阶砌再伫立等待。她真是心绪不宁，在住所凡是可看到归人的地方多次徘徊。直到夜风卷起阶前的落花，拂动她的罗衣时，她才感到春寒袭人。“落花风起”再次点明了暮春的季节特征，兼有春思撩人的象征意味。“特地”可解作“特意”或“特别”，在这里作“特别”解为宜。春夜的风使她感到特别塞冷，不仅仅由于她只穿了件薄薄的罗衣，更主要是因为她的独处而不能在心头激荡着暖流，这“寒”即是天寒，更指心寒，它以全篇之力为全篇做了一个收束。\n\n　　这是一首闺情词词中表露的是女主人公那种淡淡的哀怨与怅恨，于微婉的格调中流动着丝丝思情。此类写女子独居伤怀、望夫归来的题材，在《花间集》词作中常见。作者大多善于摄取微细的生活镜头，融入特定的自然景象，来表现女主人公的感受。这首词也体现了花间派的这种创作特色。', poem_tags = '宋词三百首,婉约,写景,妇女,孤独,思念' WHERE poem_title = '清平乐·雨晴烟晚' AND poem_author = '冯延巳';
UPDATE edu_poem SET poem_translation = '爱妻从远方的来信很久都没有收到了，我得不到家人音讯，只有在睡梦里才能回到家乡以解乡愁。可是中宵醒后，恍然发觉离别已是悠悠数年，顾望四周，只有空荡荡的床榻和寂寥凄寒的秋夜相对，不由得心生凄凉。\n寂居异乡，平日少有人来往，阶前长满了青苔，那一片绿意和秋天的红叶在迷蒙雨色、朦胧夜月的笼罩下变得黯淡模糊，雨夜的凄寒、月色的冷清，又哪里比得上乡愁的磨人呢?', poem_notes = '端居：闲居。\n素秋：秋天的代称。', poem_appreciation = '这是作者滞留异乡、思念妻子之作。题目“端居”，即闲居之意。\n\n　　诗人远别家乡和亲人，时间已经很久。妻子从远方的来信，是客居异乡寂寞生活的慰藉，但已很久没有见到它的踪影了。在这寂寥的清秋之夜，得不到家人音书的空廓虚无之感变得如此强烈，为寂寞所咬啮的灵魂便自然而然地想从“归梦”中寻求慰藉。即使是短暂的梦中相聚，也总可稍慰相思。但“路迢归梦难成”（李煜《清平乐》），一觉醒来，竟是悠悠相别经年，魂魄未曾入梦。“远书归梦两悠悠”，正是诗人在盼远书而不至、觅归梦而不成的情况下，从心灵深处发出的一声长长的叹息。“悠悠”二字，既形象地显示出远书、归梦的杳邈难期，也传神地表现出希望两皆落空时怅然若失的意态。而双方山川阻隔、别后经年的时间、空间远隔，也隐见于言外。\n\n　　次句写中宵醒后寂寥凄寒的感受。“敌“字不仅突出“空床“与素秋“默默相对的寂寥清冷的氛围,而且表现出空床独寝的人无法承受“素秋“的清冷凄凉的情状,抒发了难以言状的凄怆之情。素秋，是秋天的代称。但它的暗示色彩却相当丰富。它使人联想起洁白清冷的秋霜、皎洁凄寒的秋月、明澈寒冽的秋水，联想起一切散发着萧瑟清寒气息的秋天景物。对于一个寂处异乡、“远书归梦两悠悠”的客子来说，这凄寒的“素秋”便不仅仅是引动愁绪的一种触媒，而且是对毫无慰藉的心灵一种不堪忍受的重压。然而，诗人可以用来和它对“敌”的却“只有空床”而已。清代冯浩《玉溪生诗笺注》引杨守智说：“‘敌’字险而稳。”这评语很精到。这里本可用一个比较平稳而浑成的“对”字。但“对”只表现“空床”与“素秋”默默相对的寂寥清冷之状，偏于客观描绘。而“敌”则除了含有“对”的意思之外，还兼传出空床独寝的人无法承受“素秋”的清寥凄寒意境，而又不得不承受的那种难以言状的心灵深处的凄怆，那种凄神寒骨的感受，更偏于主观精神状态的刻画。试比较李煜“罗衾不耐五更寒”（《浪淘沙》），便可发现这里的“敌”字虽然下得较硬较险，初读似感刻露，但细味则感到它在抒写客观环境所给予人的主观感受方面，比“不耐”要深细、隽永得多，而且它本身又是准确而妥帖的。这就和离开整体意境专以雕琢字句为能事者有别。\n\n　　三、四两句从室内的“空床”移向室外的“青苔”、“红树”。但并不是客观地描绘，而是移情入景，使客观景物对象化，带上浓厚的主观色彩。寂居异乡，平日很少有人来往，阶前长满了青苔，更显出寓所的冷寂。红树，则正是暮秋特有的景象。青苔、红树，色调本来是比较明丽的，但由于是在夜间，在迷蒙雨色、朦胧夜月的笼罩下，色调便不免显得黯淡模糊。在满怀愁绪的诗人眼里，这“阶下青苔与红树”似乎也在默默相对中呈现出一种无言的愁绪和清冷寥落的意态。这两句中“青苔”与“红树”，“雨中”与“月中”，“寥落”与“愁”，都是互文错举。“雨中”与“月中”，似乎不大可能是同一夜间出现的景象。但当诗人面对其中的一幅图景时（假定是月夕），自不妨同时在心中浮现先前经历过的另一幅图景（雨夕）。这样把眼前的实景和记忆中的景色交织在一起，无形中将时间的内涵扩展延伸了，暗示出像这样地中宵不寐，思念远人已非一夕。同时，这三组词两两互文错举，后两组又句中自对，又使诗句具有一种回环流动的美。如果联系一开头的“远书”、“归梦”来体味，那么这“雨中寥落月中愁”的青苔、红树，似乎还可以让读者联想起相互远隔的双方“各在天一涯”默默相思的情景。风雨之夕，月明之夜，胸怀愁绪而寥落之情难以排遣，不禁令人满腹怅然，亦生怜惜之心。', poem_tags = '思乡' WHERE poem_title = '端居' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '我听说官吏在商议驱逐客卿这件事，私下里认为是错误的。\n　　从前秦穆公寻求贤士，西边从西戎取得由余，东边从宛地得到百里奚，又从宋国迎来蹇叔，还从晋国招来丕豹、公孙支。这五位贤人，不生在秦国，而秦穆公重用他们，吞并国家二十多个，于是称霸西戎。秦孝公采用商鞅的新法，移风易俗，人民因此殷实，国家因此富强，百姓乐意为国效力，诸侯亲附归服，战胜楚国、魏国的军队，攻取土地上千里，至今政治安定，国力强盛。秦惠王采纳张仪的计策，攻下三川地区，西进兼并巴、蜀两国，北上收得上郡，南下攻取汉中，席卷九夷各部，控制鄢、郢之地，东面占据成皋天险，割取肥田沃土，于是拆散六国的合纵同盟，使他们朝西侍奉秦国，功烈延续到今天。昭王得到范雎，废黜穰侯，驱逐华阳君，加强·巩固了王室的权力，堵塞了权贵垄断政治的局面，蚕食诸侯领土，使秦国成就帝王大业。这四位君主，都依靠了客卿的功劳。由此看来，客卿哪有什么对不住秦国的地方呢！倘若四位君主拒绝远客而不予接纳，疏远贤士而不加任用，这就会使国家没有丰厚的实力，而让秦国没有强大的名声了。\n　　陛下罗致昆山的美玉，宫中有随侯之珠，和氏之璧，衣饰上缀着光如明月的宝珠，身上佩带着太阿宝剑，乘坐的是名贵的纤离马，树立的是以翠凤羽毛为饰的旗子，陈设的是蒙着灵鼍之皮的好鼓。这些宝贵之物，没有一种是秦国产的，而陛下却很喜欢它们，这是为什么呢？如果一定要是秦国出产的才许可采用，那么这种夜光宝玉，决不会成为秦廷的装饰；犀角、象牙雕成的器物，也不会成为陛下的玩好之物；郑、卫二地能歌善舞的女子，也不会填满陛下的后宫；北方的名骥良马，决不会充实到陛下的马房；江南的金锡不会为陛下所用，西蜀的丹青也不会作为彩饰。用以装饰后宫、广充侍妾、爽心快意、悦入耳目的所有这些都要是秦国生长、生产的然后才可用的话，那么点缀有珠宝的簪子，耳上的玉坠，丝织的衣服，锦绣的装饰，就都不会进献到陛下面前；那些闲雅变化而能随俗推移的妖冶美好的佳丽，也不会立于陛下的身旁。那敲击瓦器，拍髀弹筝，乌乌呀呀地歌唱，能快人耳目的，确真是秦国的地道音乐了；那郑、卫桑间的歌声，《韶虞》《武象》等乐曲，可算是外国的音乐了。如今陛下却抛弃了秦国地道的敲击瓦器的音乐，而取用郑、卫淫靡悦耳之音，不要秦筝而要《韶虞》，这是为什么呢？难道不是因为外国音乐可以快意，可以满足耳目官能的需要么？可陛下对用人却不是这样，不问是否可用，不管是非曲直，凡不是秦国的就要离开，凡是客卿都要驱逐。这样做就说明，陛下所看重的，只在珠玉声色方面；而所轻视的，却是人民士众。这不是能用来驾驭天下，制服诸侯的方法啊！\n　　我听说田地广就粮食多，国家大就人口众，武器精良将士就骁勇。因此，泰山不拒绝泥土，所以能成就它的高大；江河湖海不舍弃细流，所以能成就它的深邃；有志建立王业的人不嫌弃民众，所以能彰明他的德行。因此，土地不分东西南北，百姓不论异国它邦，那样便会一年四季富裕美好，天地鬼神降赐福运，这就是五帝、三王无可匹敌的缘故。抛弃百姓使之去帮助敌国，拒绝宾客使之去事奉诸侯，使天下的贤士退却而不敢西进，裹足止步不入秦国，这就叫做“借武器给敌寇，送粮食给盗贼”啊。\n　　物品中不出产在秦国，而宝贵的却很多；贤士中不出生于秦，愿意效忠的很多。如今驱逐宾客来资助敌国，减损百姓来充实对手，内部自己造成空虚而外部在诸侯中构筑怨恨，那要谋求国家没有危难，是不可能的啊。', poem_notes = '（1）“由余”，亦作“繇余”，戎王的臣子，是晋人的后裔。穆公屡次使人设法招致他归秦，以客礼待之。入秦后，受到秦穆公重用，帮助秦国攻灭西戎众多小国，称霸西戎。“戎”，古代中原人多称西方少数部族为戎。此指秦国西北部的西戎，活动范围约在今陕西西南、甘肃东部、宁夏南部一带。\n（2）“百里奚”，原为虞国大夫。晋灭虞被俘，后作为秦穆公夫人的陪嫁臣妾之一送往秦国。逃亡到宛，被楚人所执。秦穆公用五张黑公羊皮赎出，用上大夫，故称“五羖大夫”。是辅佐秦穆公称霸的重臣。“宛”（yuān），楚国邑名，在今河南南阳市。\n（3）“蹇（jiǎn）叔”，百里奚的好友，经百里奚推荐，秦穆公把他从宋国请来，委任为上大夫。百里奚对穆公说：“臣不及臣友蹇叔，蹇叔贤而世莫知”。“宋”，国名，或称“商”、“殷”，子姓，始封君为商纣王庶兄微子启，西周初周公平定武庚叛乱后将商旧都周围地区封给微子启，都于商丘（今河南商丘县南），约有今河南东南部及所邻山东、江苏、安徽接界之地。公元前三世纪中叶，大臣剔成肸（即司城子罕）逐杀宋桓侯，戴氏代宋。公元前286年被齐国所灭。\n（4）“邳豹”，晋国大夫邳郑之子，邳郑被晋惠公杀死后，邳豹投奔秦国，秦穆公任为大夫。“公孙支”，“支”或作“枝”，字子桑，秦人，曾游晋，后返秦任大夫。“晋”，国名，姬姓，始封君为周成王之弟叔虞，建都于唐（今陕西翼城县西），约有今山西西南部之地。春秋时，晋献公迁都于绛，亦称“翼”（今山西翼城县东南），陆续攻灭周围小国；晋文公成为继齐桓公之后的霸主；晋景公迁都新田（今山西侯马市西），亦称“新绛”，兼并赤狄，疆域扩展到今山西大部、河北西南部、河南北部和陕西一角。春秋后期，公室衰微，六卿强大。战国初，被执政的韩、赵、魏三家所瓜分。公元前369年，最后一位国君晋桓公被废为庶人，国灭祀绝。\n（5）“产”，生，出生。“并”，吞并。\n（6）“并国二十，遂霸西戎”，《秦本纪》云秦缪公”益国十二，开地千里，遂霸西戎”。这里的“二十”当是约数。\n（7）“孝公”，即秦孝公。“商鞅”，卫国公族，氏公孙，亦称公孙鞅，初为魏相公叔座家臣，公叔座死后入秦，受到秦孝公重用，任左庶长、大良造，因功封于商（今山西商县东南）十五邑，号称商君。于公元前356年和前350年两次实行变法，奠定秦国富强的基础。公元前338年，秦孝公去世，被车裂身死。\n（8）“殷”，多，众多。“殷盛”，指百姓众多而且富裕。\n（9）“魏”，国名，始封君魏文侯，系晋国大夫毕万后裔，于公元前403年与韩景侯、赵烈侯联合瓜分晋国，被周威烈王封为诸侯，建都安邑（今山西夏县西北）。魏文侯任用李悝改革内政，成为强国。梁惠王时迁都大梁（今河南开封市），因亦称”梁”。后国势衰败，公元前225年被秦国所灭。“获楚、魏之师”，指战胜楚国、魏国的军队。公元前340年，商鞅设计诱杀魏军主将公子昂，大败魏军。同年又与楚战，战况不详，据此，当也是秦军获胜。\n（10）“惠王”，即秦惠王，名驷，秦孝公之子，公元前337年至前311年在位。于公元前325年称王。“张仪”，魏人，秦惠王时数次任秦相，鼓吹“连横”，游说各国诸侯事奉秦国，辅佐秦惠文君称王，封武信君。秦武王即位，入魏为相。于公元前310年去世。此句以下诸事，并非都是张仪之计，因为张仪曾经作为宰相，就把功劳归功到他身上了。\n（11）“三川之地”，指黄河、雒水、伊水三川之地，在今河南西北部黄河以南的洛水、伊水流域。韩宣王在此设三川郡。公元前308年秦武王派兵攻取三川大县宜阳（今河南宜阳县西）。公元前249年秦灭东周，取得韩三川全郡，重设三川郡。\n（12）“巴”，国名，周武王灭商后被封为子国，称巴子国，在今四川东部、湖北西部一带。战国中期建都于巴（今四川重庆节）。公元前316年秦惠王派张仪、司马错等领兵攻灭巴国，在其地设置巴郡。“蜀”，国名，周武王时曾参加灭商的盟会，有今四川中部偏西地区。战国中期建都于成都（今四川成都市）。公元前316年秦惠文王派张仪、司马错等领兵灭蜀，在其地设置蜀郡。\n（13）“上郡”，郡名，本来是楚地，在现在的陕西的榆林。魏文侯时置，辖境有今陕西洛河以东，黄梁河以北，东北到子长县、延安市一带。公元前328年魏割上郡十五县给秦，前312年又将整个上郡献秦。秦国于公元前304年于此设置上郡。\n（14）“汉中”，郡名，在现在的陕西汉中。楚怀王时置，辖境有陕西东南和湖北西北的汉水流域。公元前312年，被秦将魏章领兵攻取，秦于此重置汉中郡。\n（15）“包”，这里有并吞的意思。“九夷”，此指楚国境内西北部的少数部族，在今陕西、湖北、四川三省交界地区。\n（16）“鄢”，音yān，楚国别都，在今湖北宜城县东南。春秋时楚惠王曾都于此。“郢”（yǐng），楚国都城，在今湖北江陵市西北纪南城。公元前279年秦将白起攻取鄢，翌年又攻取郢。\n（17）“成皋”，邑名，在今河南荥阳县汜水镇，地势险要，是著名的军事重地。春秋时属郑国称虎牢，公元前375年韩国灭郑属韩，公元前249年被秦军攻取。\n（18）“六国”，韩、魏、燕、赵、齐、楚。“施”，音yì，蔓延，延续。\n（19）“昭王”，即秦昭王，名稷，一作侧或则，秦惠王之子，秦武王异母弟，公元前306年至前251年在位。“范雎jū”，一作“范且”，亦称范叔，魏人，入秦后改名张禄，受到秦昭王信任，为秦相，对内力主废除外戚专权，对外采取远交近攻策略，封于应（今河南宝丰县西南），亦称应侯，死于公元前255年。\n（20）“穰”，音ráng。“穰侯”，即魏冉，楚人后裔，秦昭王母宣太后之异父弟，秦武王去世，拥立秦昭王，任将军，多次为相，受封于穰（今河南邓县），故称穰侯，后又加封陶（今山东定陶县西北）。因秦昭王听用范雎之言，被免去相职，终老于陶。\n（21）“华阳”，即华阳君芈戎，楚昭王母宣太后之同父弟，曾任将军等职，与魏冉同掌国政，先受封于华阳（今河南新郑县北），故称华阳君，后封于新城（今河南密县东南），故又称新城君。公元前266年，与魏冉同被免职遣归封地。\n（22）“蚕食”，比喻像蚕吃桑叶那样逐渐吞食侵占。\n（23）“向使”，假使，倘若。“内”，同“纳”，接纳。\n（24）“陛下”，对帝王的尊称，“致”，求得，收罗。“昆山”，即昆仑山。\n（25）“随、和之宝”，即所谓“随侯珠”和“和氏璧”，传说中春秋时随侯所得的夜明珠和楚人卞和来得的美玉。\n（26）“明月”，宝珠名。\n（27）“太阿（ē）”，亦称“泰阿”，宝剑名，相传为春秋著名工匠欧冶子、干将所铸。\n（28）“纤离”，骏马名。\n（29）“翠凤之旗”，用翠凤羽毛作为装饰的旗帜。\n（30）“鼍”（tuó）亦称扬子鳄，俗称猪婆龙，皮可蒙鼓。\n（31）“说”，通“悦”，喜悦，喜爱。\n（32）“犀象之器”，指用犀牛角和象牙制成的器具。\n（33）“郑”，国名，姬姓，始封君为周宣王弟友，公元前806年分封于郑（今陕西华县东）。春秋时建都新郑（今河南新郑县），有今河南中部之地，公元的375年被韩国所灭。“卫”，国名，姬姓，始封君为周武王弟康叔，初都朝歌（今河南淇县），后迁都楚丘（今河南滑县）、帝丘（今河南濮阳县），有今河南北部、山东西部之地。公元前254年被魏国所灭。“郑、卫之女”，此时郑、卫已亡，当指郑、卫故地的女子。“后宫”，嫔妃所居的宫室，也可用作嫔妃的代称。\n（34）“駃騠”，音jué tí，骏马名。“外厩（jiù）”，宫外的马圈。\n（35）“江南”，长江以南地区。此指长江以南的楚地，素以出产金、锡著名。\n（36）“丹”，丹砂，可以制成红色颜料。“青”，青，可以制成青黑色颜料。“西蜀丹青”，蜀地素以出产丹青矿石出名。“采”，彩色，彩绘。\n（37）“下陈”，殿堂下陈放礼器、站立傧从的地方。“充下陈”，此泛指将财物、美女充买府库后宫。\n（38）“宛”，宛转，缠绕。”宛珠之簪”，缀绕珍珠的发簪。或以“宛”为地名，指用宛（今河南南阳市）地出产的珍珠所作装饰的发簪。\n（39）“傅”，附着，镶嵌。“玑”，不圆的珠子。此泛指珠子。“珥”，音er，耳饰。\n（40）“阿”，细缯，一种轻细的丝织物。或以“阿”为地名，指齐国东阿（今山东东阿县）。\n（41）“缟”，音gǎo，未经染色的绢。\n（42）“随俗雅化”，随合时俗而雅致不凡。“佳”，美好，美丽。“冶”，妖冶，艳丽。“窈窕”，音yǎo tiǎo，美好的样子。“赵”，国名，始封君赵烈侯，系晋国大夫赵衰后裔，于公元前403年与魏文侯、韩景侯联合瓜分晋国，被周威烈王封为诸侯，建都晋阳（今山西太原市东南），有今山西中部、陕西东北角、河北西南部。公元前三八六年迁都邯郸（今河北邯郸市）。公元前二二二年被秦国所灭。古人多以燕、赵为出美女之地。\n（43）“瓮”，音wèng，陶制的容器，古人用米打水。“缶”，音fǒu，一种口小腹大的陶器。秦人将瓮、缶作为打击乐器。“搏”，击打，拍打。“髀”，音bì，大腿。“搏髀”，拍打大腿，以此掌握音乐唱歌的节奏。\n（44）“《郑》”，指郑国故地的音乐。“《卫》”，指卫国故地的音乐。“《桑间》”，桑间为卫国濮水边上地名，在今河南濮阳县南，有男女聚会唱歌的风俗。此指桑间的音乐，即本书《乐书》的“桑间濮上之音”。“《昭》”，通“韶”，《史记集解》引徐广曰：“昭，一作‘韶’。”歌颂虞舜的舞乐。”《虞》”，按《史记会注考证校补》引南化本、枫山本、三条本等作“护”，当为歌颂商汤的舞乐。“《武》”，歌颂周武王的舞乐。“《象》”，歌颂周文王的舞乐。\n（45）“太山”，即泰山。“让”，辞让，拒绝。\n（46）“择”，舍弃，抛弃。细流，小水。\n（47）“却”，推却，拒绝。\n（48）“五帝”，指黄帝、颛顼、帝喾、尧、舜。“三王”，指夏、商、周三代开国君主，即夏禹、商汤、周文王和周武王。\n（49）“黔首”，无爵平民不能服冠，只能以黑巾裹头，故称黔首。此泛指百姓。秦始皇统一六国后正式称百姓为黔首。《史记·秦始皇本纪》载：二十六年，“更名民曰黔首”。“资”，资助，供给。\n（50）“业”，从业，从事，事奉。\n（51）“赍”（jī）送，送给。这句是说，把武器粮食供给寇盗。\n（52）“益”，增益，增多。“雠”，通“仇”，仇敌。减少该国的人口而增加敌国的人力。\n（53）“外树怨于诸侯”，指宾客被驱逐出外必投奔其它诸侯，从而构树新怨。', poem_appreciation = '《谏逐客书》是李斯给秦王的一个奏章。这件事是在秦王赢政十年。秦国宗室贵族借韩国派水工修灌溉渠，阴谋消耗秦的国力，谏秦皇下令驱逐一切客卿。秦王读了李斯这一奏章，取消了逐客令。可见本文说服力之强。 　　作者先谈历史，以穆公、孝公、惠王、昭王四位国君召士纳贤为例，强调重用客卿之重要。接着再谈现实，作者列举秦王的爱好，诸如昆山之玉，随和之宝，明月之珠，以及所佩太阿剑，所乘之纤离之马等等，都是来自诸侯各国。\n\n实效性 　　首先是《谏逐客书》具有明显的实效性。实效，就是要讲求实用，注重效果，这就涉及到公文的目的及功能。公文不像艺文那样，优游浸渍，潜移默化，以美感人，公文乃是“政事之先务”，它的目的是为了完成特定的公务，它的功能是可以解决实际的问题。从本质上说公文是一种实用性程式性的文书，以此区别于一般的文章或文学作品。公文所产生的客观效果是衡量公文实用性大小的一个重要尺度。所以公文撰制时必须事先预计效果，办理时讲究效率，客观上注重功效。徐望之《公牍通论》指出：“事前体察周详，令出务求实效。”这说的是下行公文。上行公文也要做到“下情不壅于上闻，谋事惟期其必达”。一篇公文，如果实用性不大，效果不显著，就很难说是上乘之作。因此，实效性显著，应是好公文的重要条件。以此看来《，谏逐客书》正是具有实效性显著的特点。这篇公文最成功之处就在于，该文一上秦王，就达到预期的目的，收到满意的效果。司马迁在《李斯列传》中曾这样叙述过李斯上书的前因后果：“秦王拜斯为客卿。会韩人郑国来间秦，以作注溉渠，已而觉。秦宗室大臣皆言秦王曰：‘诸侯人来事秦者，大抵为其主游间于秦耳。请一切逐客。’李斯议亦在逐中。斯乃上书曰：“秦王乃除逐客之令，复李斯官，卒用其计谋。”当时秦王的逐客令已下，李斯也在被逐之列，而凭此上书,竟能使秦王收回成命，由逐客变为留客、用客、重客，这就不能不承认《谏逐客书》发挥了巨大的作用，公文的实效性在这里得到了最充分的体现。\n\n论断典范 　　其次，《谏逐客书》在“对事的论断”方面堪称典范。笔者以为“对事的论断”应视为公文的一个重要特征。事是公文的内容，论断是对公文内容的表达方式。“对事的论断”体现了公文的内容与形式的统一。显然，公文须有事，刘勰所说“言事于主”、“指事造实”，徐望之所说“谋事惟期其必达”、“尚实事不尚虚文”，都指出公文的内容就是事，因为公文就是办实事的。但是公文在表达事时，不必对其来龙去脉进行具体的叙述，往往是高度概括，或者点到为止。公文对于事，主要是用“论断”的方法。正如《公牍通论》所述，“陈言论事”、“公文本质，重论断”。论断是个合成词，包含论和断两个方面。断，判断、决断之谓，对事的是非、得失、功过等表示肯定或否定的态度，对事的实施提出一定的办法。论是论事理，要受文者承办事务，必须把事理论说明白。简言之，断就是要办什么事，论就是办这事的理由。论是断的前提，如果不把事理论清说透，断就会成为无源之水，无本之木，缺乏说服力。在古代公文中，由于文种不同，对事论断的情况也有差别，如下行的君命文种，比较偏重于断,凡戒敕、废立、告谕、政令等，都显示独断的至高权威，而上行文种的章、奏、表、议等则较侧重于论（当然也应有断），凡谏说、劝请、陈乞、弹劾、执异等，本身就需要有充分的理由，不论说何以达其目的。况且上奏文种面对的是国君这个特殊对象，更要情至理足。《谏逐客书》在这一点上，具有非常鲜明的特色。全文的断就是开头一句话：“臣闻吏议逐客，窃以为过矣。”希望通过这一判断成立，使秦王接受，并收回成命，不要逐。为此在下文展开了有力的论说。开头这一断语的 　　特点是，在客卿已被逐的紧急情势下（《史记集解·新序》：“斯在逐中，道上上谏书。”），用非常警醒而委婉的言辞开宗明义，起句发意振聋发聩。本文尤具特色的更在其论的部分，对事理的论说充分深刻，令人信服。这里有必要指出两点，其一是用重笔浓墨，铺张排比，列举事例。如文中铺排了四君用客的大量事实，铺陈了秦王所喜爱的大量生活享用，由于事例充实，铺垫充足，加强了与下文的对比，因而得出的结论极其有力。而这些事例都有所依傍，且经过精心选择，因而显得可靠典型。从铺排的技巧来说，排比句接踵联翩，文意饱满，文气流畅，文势充沛,极有感染力。其二，在论证上的特点是正反并反复对比，层层深化。如在论证的首层，四君用客（实笔） 与“却客不内”（虚笔） 的对比，首层四君用客与次层秦王轻客的对比，次层重物与轻人的对比，处处在对比之中显示逐客之谬误。全文在逻辑关系上是步步推进，层层深化。时间上由远到近，推移有序：先言古代，次论现实，再次言及未来。在言及逐客的危害时，程度上由轻到重，步步升级：先说如果没有客卿，秦国就不会“富利”和“强大”；接着说“非秦者去，为客者逐”，“此非所以跨海内、制诸侯之术”，直接落到统一天下这个关键问题，比上层更切近要害；再说弃 　　黔首、却宾客，是所谓“藉寇兵而赍盗粮”，资助了敌人削弱了自己，对秦国的不利更严重些；最后指出“今逐客以资敌国、损民以益仇，内自虚而外树怨于诸侯，求国无危，不可得也。”不仅不能统一天下，而且有亡国的危险，把逐客的危害引申到极点。这种由轻到重、步步推进的说理过程，避免一开始就突兀冲撞，造成相反结果，它符合人的心理接受规律。\n\n针对性 　　再者《，谏逐客书》具有很强的针对性。公文的针对性一方面是指每件公文都是针对某一具体的事务而发，另方面也指公文具有比较具体的的受文对象，受文者具有确定性。周知性的公文读者面较宽,但也有一定的范围；下行文受文的面相对说要窄一些，在现代的公文中有的还规定了阅读传达范围；上行文一般是给一个上级机关，受文对象很具体。古代的上奏文种是专门给君主的，对象最明确。公文写作时都视受文者的不同情况进行斟酌，有的放矢。《谏逐客书》的针对性，从内容上来说，是对着逐客这事而发，全文紧紧扣住逐客以论说其错误。文章这样处理很高明，因这逐客的起因是韩国人郑国劝秦王修筑一条灌溉渠，其目的是企图以浩大的工程耗费秦国的财力，使之不能对外用兵，如果就此事进行辩解，显然是没有道理的。李斯避开这个起因不谈，只抓住逐客对秦不利来论说，完全从秦国的利益着眼，这就容易使秦王接受。另外，李斯当时也无辜受牵连，但他在上书中片言不涉及自己，这样完全符合公文的本质要求，徐望之说：“公文本质之可贵，贵在一字一句皆从民生国计上着想。”针对逐客对秦不利来论说，正是从国计民生着想的体现。 　　《谏逐客书》的针对性，还表现在针对特定的受文者来采取谏说的策略。李斯上书是给秦王政这个具体的人看的，如果不熟悉这个人，不揣摩这个人的愿望、想法，不去迎合他的心理需求，那就很容易碰壁。对这个问题，刘勰有中肯的评价：“烦（顺） 情入机动言中务，虽批逆鳞而功成计合，此上出之喜说者也。”顺着秦王的感情、心理，引到统一六国的关键问题，符合主要任务的需要。当时秦王的最大欲望是兼并天下,凡是违反这一欲望，就难以立足，凡是利于达到这一欲望，就容易被接受。李斯紧紧抓住秦王的这一心理，把秦国的霸业作为整篇谏书的灵魂，贯串始终。在论说的首层以秦王政的祖先重用客卿造成“霸西戎”、“治强”、“散六国之从”、“蚕食诸侯”、“使秦成帝业”等成就去耸动秦王；在论说的次层则把用客卿提到“跨海内，制诸侯之术”的高度；再接着以古代五帝三王“不却众庶”无敌天下去打动秦王。总之，每个层次都反复论述这样一个根本的利害关系：纳客就能统一天下，逐客就有亡国危险。以利劝之，以害怵之，这就紧紧抓住了秦王的心，深深击中其要害，使秦王顺理成章地接纳其意见，并收回逐客令，达到了上书的目的。 　　以上论述了《谏逐客书》是如何有针对性地、成功地对逐客之事加以论断，使该公文收到了显著的实效。实效性、针对性、对事加以论断，这三个特征在文中体现最为突出。当然，该文还有个别其他的公文特征，像当时李斯已在被逐之中，写这篇上书必须十分注意时效，除了“道上上谏书”急就此文之外，在写法上开头单刀直入，指出逐客之错，使秦王为之震动。可见首句发意、开门见山，既为当时紧急情势决定，也是公文时效性的要求。', poem_tags = '古文观止,公文' WHERE poem_title = '谏逐客书' AND poem_author = '李斯';
UPDATE edu_poem SET poem_translation = '二月的巴陵，几乎天天都刮风下雨。料峭的春寒还未结束，给园林的花木带来了灾难，叫人担心害怕！\n娇嫩的海棠，毫不吝惜鲜红的花朵，挺身独立在寒风冷雨中开放着。', poem_notes = '选自《简斋集》。陈与义（1090-1138），号简斋。宋代诗人。此诗写于高宗建炎三年（1129）二月。\n巴陵：古郡名，今湖南岳阳市。\n园公：诗人自注：“借居小园，遂自号园公。”\n胭脂：一种红色颜料。也泛指红色。', poem_appreciation = '赏析 　　这首绝句与其说是写春寒，不如说是咏海棠。说到咏海棠，自然忘不了苏轼的《海棠》诗：“东风袅袅泛崇光，香雾空蒙月转廊。只恐夜深花睡去，故烧高烛照红妆。”其实，这两首海棠诗都是借海棠写自己。苏轼笔下的海棠圣洁、幽寂，是他贬官黄州时的写照；陈与义笔下的海棠雅致孤高，是他流亡时的写照。 因此，头两句的“风”“寒”就不仅仅是自然界的风寒，更主要的是社会的风寒——金兵南侵，南宋小朝廷“山河破碎风飘絮”，诗人则“身世浮沉雨打萍”，怎不感到“怯”？后两句诗人用类似于刻划松、梅、菊、竹的手法来写海棠，说它傲然“独立”于风雨中，哪怕有损于自己美丽的“胭脂色”。海棠的风骨和雅致得到充分的表现。诗人点化杜甫的“林花着雨胭脂湿”，别创意境，不但更具风致，而且更具品格。诗人将自己的风骨、品格、雅致融入对海棠的描写中，使这首诗成为咏物上乘之作，这就是咏物诗创作的诀窍。 ▲', poem_tags = '咏物,海棠,抒怀,品格' WHERE poem_title = '春寒' AND poem_author = '陈与义';
UPDATE edu_poem SET poem_translation = '白发将军虎老雄心犹在，收复西京捷报昨夜传来。\n胡贼说梦妄想永占中原，岂知上天桔我大宋兴泰。\n列圣仁泽深如雨露普降，大赦诏令快似疾风迅雷。\n料想明朝寒食祭扫陵墓。一路春风处处梨花盛开。', poem_notes = '武均州：即武巨。当时武巨任果州团练使，知均州，兼管内安抚使，节度忠义军。古人常以任官所在地名代称其人名字，均州故址在今湖北省光化县。\n白发将军：指武巨。\n捷书：捷报。\n胡儿：指金人。\n天意：指冥冥中上天的意向。 回：回心转意。指上天叉决定祜助赵宋王朝。\n列圣。宋王朝已故列代皇帝。\n中兴：国家由衰转盛。赦令：大赦天下的诏令。 疾风雷：指诏令传布快如风雷。\n悬知，预测，推想。 寒食：指清明明前三日，民俗不举火，以纪念被烧死的介子推。古人多在这几日扫墓。朝陵使：朝祭陵墓的使者。北宋诸代皇帝的陵墓皆在西京。收复西京后即可派朝陵使前往祭扫。\n驿路：旅途。驿：古时旅行时换马宿夜的地方。', poem_tags = '战争,抒怀,喜悦' WHERE poem_title = '闻武均州报已复西京' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '你近来平安吗？即便你回来，回首以前令人悲债的事，你又怎能够承受！昔日朋友形同陌生的路人，又有谁安慰你？你母老家贫子幼，早记不起杯酒相娱的时侯。魑魅搏人的事应该司空见惯，正直人却总是输在覆雨翻云的小人之手。我们与寒冷的冰雪，打交道已经很久很久。\n劝你不要让泪水把牛衣滴透。请你数一数天下的戌边人，仍旧和家人团聚二堂的，又有几家？比起早已冤死的红颜薄命人，更不如你如今生命还有。只是在那极远的边塞，四季冰雪的苦寒难受。你在边塞已经二十年，·我要像申包胥那样实现诺言，像燕丹盼归使乌头白马生角样，一定把你营救。我就以这首词代替书信，请你妥善保存不要忧愁。\n\n我也漂泊他乡很久。自中举十年来，我辜负了你的深厚恩情，未报答你这位生死之交的师友。从前你我齐名并非名不副实，试看曾为怀念李白而瘦的杜甫，忧闷不下于流放夜郎的李白。我的夫人已经去世，又与知己的你分别，试问人生在世，到这步田地凄凉不？我将千种怨、万种恨，向你细细倾吐。\n你生于辛未年我生于丁丑，都受了一些时间的冰雪摧残，已经成了早衰的蒲柳。劝你从今要少作词赋，多多保重与我长相守。但愿黄河变清人长寿。你归来定会急忙翻阅戌边时的诗稿，把它们整理出来传给后世，但也只是忧患在前空名在后。满心的话语说不尽，我在此向你行礼磕头。', poem_notes = '吴汉槎（chá）：名兆骞，江苏吴江人。顺治举人，工诗文，以科场事为人所陷，于顺治十六年谪戍宁古塔（今松江省宁安县）。\n书：书信。\n丙辰：清康熙十五年（1676年）\n季子：指春秋时吴王寿梦的儿子季札，号延陵季子，素有贤名。后常称姓吴的人为“季子”。这里代指吴兆骞。\n行路：过路人。\n悠悠：关系很远，不相关。\n慰藉：安慰之意。\n杯酒：即杯酒言欢的缩语。\n魑（chī）魅搏人：魑魅，传说里的山林妖怪。搏人，打人，抓人。据吴兆骞子吴振臣在《秋笳集》的跋中说，吴兆骞“为仇家所中，遂遣戍宁古。”\n覆雨翻云手：指翻手为云，覆手为雨，陷害好人的阴毒小人。\n牛衣：乱麻编制的给牛保暖的披盖物。据《汉书·王章传》载，王章贫困的时侯，曾与妻子卧于牛衣上对泣。\n数天涯，依然骨肉：吴兆骞被遣戍肩，其妻至戍所相陪十余年，生有一子四女。\n绝塞：极远的边塞。苦寒难受：吴兆骞《秋笳集》卷八《与计甫草书》中有：“塞外苦寒，四时冰雪。”\n廿（niàn）载包胥承一诺：廿载，二十年。从1657年吴兆骞被遣戍宁古塔，到作者1676年写这首词，正好二十年。包胥承一诺，据《史记·伍子胥列传》载，春秋时，楚国大失包胥立誓要保全楚国，后果然如愿。\n盼乌头马角终相救：《史记·刺客列传》索引：“丹求归，秦王曰，‘乌头白，马生角，乃许耳。’”燕太子丹仰天长叹，上感于天，果然乌头变白，马也生角。\n札：信札，书信。\n我亦飘零久：飘零，漂泊。作者康熙五年（1666年）中举，掌国史馆典籍，五年后因父病告归，康熙十五年（1676年）又入京在纳兰性德家教书，两度客居京师，故有飘零异乡之感。\n十年来：从康熙五年（1666年）作者中举，到1676年写这首词，正好十年。\n“宿昔”四句：宿昔，过去。非忝窃，不是名不副实。《感引集》卷十六引顾震沧的话说：“贞观幼有异才，能诗，尤工乐府。少与吴江吴兆骞齐名。”杜陵消瘦，杜甫在《丽人行》中自称“杜陵野老”、“杜陵布衣”，李白戏杜甫诗中有：“借问别采太瘦生，总为从前作诗苦。”夜郎僝僽，李白曾被流夜郎（今贵州省西部），受到摧残。这里以杜甫和李白比喻作者和吴兆骞。\n薄命长辞知己别：指作者夫人去世和与昊兆骞分别。\n兄生辛未吾丁丑：吴兆骞生于辛未年，即明崇祯四年（1631）。作者生于丁丑年，即明崇祯十年（1637年）。\n早衰蒲柳：蒲柳，即水杨，是凋零最早的树木。《世说新语》载：“顾悦与简文同年，而发早白。简文曰：‘卿何以先白？’对曰：‘蒲柳之姿，望秋而落。松柏之质，经霜犹茂。’”\n“诗赋”二句：古人认为创作诗文损伤人的心魂。桓谭在《新论》里说，他和扬雄都因作赋，“用精思大剧而得病”。作者和吴兆骞创作都很勤奋，尤其是吴兆骞，儿童时就作胆赋，“累千余言”。（见《国朝先正事略》）\n但愿得，河清人寿：河，指黄河。黄河水浊，古时认为黄河清就天下太平。古人云：“俟河之清，人寿几何。”认为黄河千年一清，而人寿有限。这里是希望一切好转，吴兆骞能归来的意思。\n行戍稿：在戍边时所写的稿子。', poem_appreciation = '二作系以书信格式入词，十分别致。“季子平安否？”写信先须问对方安好，这首句正是问安口气。不过用“季子”二字却有深意。这里用“季子”二字既切合吴兆骞的姓氏，又使入联想其才德，而且还表明吴地人。（一说，吴兆骞有二兄，季子言其排行。）拿吴季子比吴兆骞，其人才德令人钦佩，而却受了这种冤枉，就更令人同情。所以五个字看似寻常，实则有力地领起全篇。“便归来，平生万事，那堪回首？”这是用假设语句极力同情吴兆骞的痛苦经历。即使现在就能回到家乡，这段经历中的千难万苦，又那堪回想。何况现在没有归来，还在经受着这些不堪回首的痛苦。“行路悠悠准慰藉，母老家贫子幼。”这是就不堪回首的痛苦中特别提出充军关外的遭遇，没有谁能加以安慰，家庭又是如此困难——母老家贫子幼。过去的一切欢乐都无影无踪，“记不起、从前杯酒”。朋友的文酒之会，杯酒相欢，不要说现在没有了，就连过去的记忆也消失了，令人伤心。“魑魅搏人应见惯，总输他，覆雨翻云手。”“搏人”，这是含蓄地为吴兆骞鸣不平。“魑魅搏人”，比喻坏人以卑劣的手段陷害人。桂甫诗：“纷纷轻薄何足数，翻手为云覆手雨。”这里用杜意，就是说，君子总要吃小人的亏。应该提出的是清代文字狱频繁，士人往住转喉触讳。吴兆骞是朝廷谪戍的，既要同情兆骞，又要回避触犯朝廷，只能笼统地这样解说，这在当时已经算是大胆的了。“冰与雪，周旋久。”这是切题中宁古塔的特点。塞外苦寒，作者此时在京师风雪之中，想象好友塞外，只能与冰雪周旋，而一过就是多年，定令人难受。这上片痛快淋漓地为吴兆骞的痛苦倾诉，下片一转变成多方安慰开脱，希望他不要为痛苦所摧垮。\n\n　　汉时王章夫妻牛衣对泣的事，作者反用为“泪哀莫滴牛衣透”，劝也不要过分伤心，原因何在，“数天涯，依然骨肉，几家能够？比似红颜多命薄，更不如今还有？”没有几家能够骨肉团聚，吴兆骞虽远在关外，却还能牛农对泣，骨肉一处，这是骨肉分散的还好些。再说红颜命薄，古今一辙，有才往往命途多舛。这样退一步想，也就得些宽慰。但劝慰要有分寸，只能说到这地步，笔锋一转又为他难受：“只绝塞、苦寒难受。”这和上片结尾“冰与雪，周旋久”相呼应。“廿载包胥承一诺，盼乌头马角终相救”，化用春秋后期申包胥立誓救楚和燕太子丹质于秦而后得归的典故，作者把它们巧妙地组织在一起，表示不管多大困准，一定要像申包胥那样尽力救他回来。沉痛感人。“置此札，君怀袖”：这封信请你保存。就是凭证。这几句表现死生不愉的友情，感人肺腑，催入泪下。\n\n　　第一首从吴兆骞写，第二首换个角度从自己发感慨：“我亦飘零久。十年来，深恩负尽，死生师友！”说得沉痛，“亦”字勾留上首，不是泛泛。“宿昔齐名非泰窃，试看杜陵消瘦。曾不减、夜郎僝僽。”从自己又说到两人。杜甫《长沙送李十一衔》：“李杜齐名真悉窃，朔云寒菊倍离忧。”杜甫是客气话。历史上李杜齐名有好多个，东汉的李固杜乔、李膺杜密等等，唐朝诗人李白杜甫，这儿反用杜诗说“非忝窃”，以杜甫自比。“试看杜陵消瘦。”以李白比吴兆骞，李白曾被长流夜邹（中道放归），比吴兆骞之滴戍宁古塔，“僝僽”，指受折磨和愁苦烦恼。自己虽然没有谪戍，却和吴兆骞一样痛苦，备受析磨。“薄命长辞知己别，问人生、到此凄凉否？”红颜薄命，长辞指死亡。顾贞观曾有悼亡之戚，薄命长辞，知已远别，人生逢此，是妻凉。人生之中没有多少人曾到这样凄凉境地。“问人生”这一反问句就包含上两层意思。“千万恨，为兄剖，自然收束半片。\n\n　　换头处，从年龄诉说，“兄生辛未吾丁丑”。辛未、丁丑到作此词时，两人都过了四十，“四十曰强，仕。”但“共些时，冰霜摧折，早衰蒲柳”，身体都受到摧残而早衰了。蒲柳是用《世说新语》顾悦与晋简文帝同岁而先老的典故，而“蒲柳”就变成自指身体的谦词了。这里用个“共”字，表示两人都一样，这是回应上文“试看杜陵消瘦，曾不减、夜郎僝僽。” 既然年过四十，身体早衰，就应注意保养：“词赋从今须少作，留取心魂相守。”两句语重心长。既然可以“相守”，表明前途仍有希望。“但愿得、河清人寿。”（“俟河之情，人寿几何？”“黄河清，出圣人。”）这句祝愿，字面用前一句，意思在后一句。希望圣主施恩，远人归老家园。政治清明，相应地人民应该生活安定，终其天年，所以说“河倩清人寿”。“归日急翻行戍稿，把空名料理传身后。”，吴兆骞的诗必传于后是作者的预言，也是完全符合实际的。吴兆骞流放以后，诗歌增加了悲壮苍凉的气氛，为人传诵，在清代前期也算重要作家。这表现作者对吴兆骞的信任和安慰。不说“声名”而说“空名”，这个“空”字把上文一系列苦痛都括在其中，大名没有使吴兆骞免除生前的苦难，所以说“空名”，这个“空”字可以算一字千金。“言又尽，观顿首”，仍然是书信格式。', poem_tags = '友情' WHERE poem_title = '金缕曲二首' AND poem_author = '顾贞观';
UPDATE edu_poem SET poem_tags = '写水,西湖,荷花,抒情' WHERE poem_title = '采桑子·荷花开后西湖好' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '你近来平安吗？即便你回来，回首以前令人悲债的事，你又怎能够承受！昔日朋友形同陌生的路人，又有谁安慰你？你母老家贫子幼，早记不起杯酒相娱的时侯。魑魅搏人的事应该司空见惯，正直人却总是输在覆雨翻云的小人之手。我们与寒冷的冰雪，打交道已经很久很久。\n劝你不要让泪水把牛衣滴透。请你数一数天下的戌边人，仍旧和家人团聚二堂的，又有几家？比起早已冤死的红颜薄命人，更不如你如今生命还有。只是在那极远的边塞，四季冰雪的苦寒难受。你在边塞已经二十年，·我要像申包胥那样实现诺言，像燕丹盼归使乌头白马生角样，一定把你营救。我就以这首词代替书信，请你妥善保存不要忧愁。\n\n我也漂泊他乡很久。自中举十年来，我辜负了你的深厚恩情，未报答你这位生死之交的师友。从前你我齐名并非名不副实，试看曾为怀念李白而瘦的杜甫，忧闷不下于流放夜郎的李白。我的夫人已经去世，又与知己的你分别，试问人生在世，到这步田地凄凉不？我将千种怨、万种恨，向你细细倾吐。\n你生于辛未年我生于丁丑，都受了一些时间的冰雪摧残，已经成了早衰的蒲柳。劝你从今要少作词赋，多多保重与我长相守。但愿黄河变清人长寿。你归来定会急忙翻阅戌边时的诗稿，把它们整理出来传给后世，但也只是忧患在前空名在后。满心的话语说不尽，我在此向你行礼磕头。', poem_notes = '吴汉槎（chá）：名兆骞，江苏吴江人。顺治举人，工诗文，以科场事为人所陷，于顺治十六年谪戍宁古塔（今松江省宁安县）。\n书：书信。\n丙辰：清康熙十五年（1676年）\n季子：指春秋时吴王寿梦的儿子季札，号延陵季子，素有贤名。后常称姓吴的人为“季子”。这里代指吴兆骞。\n行路：过路人。\n悠悠：关系很远，不相关。\n慰藉：安慰之意。\n杯酒：即杯酒言欢的缩语。\n魑（chī）魅搏人：魑魅，传说里的山林妖怪。搏人，打人，抓人。据吴兆骞子吴振臣在《秋笳集》的跋中说，吴兆骞“为仇家所中，遂遣戍宁古。”\n覆雨翻云手：指翻手为云，覆手为雨，陷害好人的阴毒小人。\n牛衣：乱麻编制的给牛保暖的披盖物。据《汉书·王章传》载，王章贫困的时侯，曾与妻子卧于牛衣上对泣。\n数天涯，依然骨肉：吴兆骞被遣戍肩，其妻至戍所相陪十余年，生有一子四女。\n绝塞：极远的边塞。苦寒难受：吴兆骞《秋笳集》卷八《与计甫草书》中有：“塞外苦寒，四时冰雪。”\n廿（niàn）载包胥承一诺：廿载，二十年。从1657年吴兆骞被遣戍宁古塔，到作者1676年写这首词，正好二十年。包胥承一诺，据《史记·伍子胥列传》载，春秋时，楚国大失包胥立誓要保全楚国，后果然如愿。\n盼乌头马角终相救：《史记·刺客列传》索引：“丹求归，秦王曰，‘乌头白，马生角，乃许耳。’”燕太子丹仰天长叹，上感于天，果然乌头变白，马也生角。\n札：信札，书信。\n我亦飘零久：飘零，漂泊。作者康熙五年（1666年）中举，掌国史馆典籍，五年后因父病告归，康熙十五年（1676年）又入京在纳兰性德家教书，两度客居京师，故有飘零异乡之感。\n十年来：从康熙五年（1666年）作者中举，到1676年写这首词，正好十年。\n“宿昔”四句：宿昔，过去。非忝窃，不是名不副实。《感引集》卷十六引顾震沧的话说：“贞观幼有异才，能诗，尤工乐府。少与吴江吴兆骞齐名。”杜陵消瘦，杜甫在《丽人行》中自称“杜陵野老”、“杜陵布衣”，李白戏杜甫诗中有：“借问别采太瘦生，总为从前作诗苦。”夜郎僝僽，李白曾被流夜郎（今贵州省西部），受到摧残。这里以杜甫和李白比喻作者和吴兆骞。\n薄命长辞知己别：指作者夫人去世和与昊兆骞分别。\n兄生辛未吾丁丑：吴兆骞生于辛未年，即明崇祯四年（1631）。作者生于丁丑年，即明崇祯十年（1637年）。\n早衰蒲柳：蒲柳，即水杨，是凋零最早的树木。《世说新语》载：“顾悦与简文同年，而发早白。简文曰：‘卿何以先白？’对曰：‘蒲柳之姿，望秋而落。松柏之质，经霜犹茂。’”\n“诗赋”二句：古人认为创作诗文损伤人的心魂。桓谭在《新论》里说，他和扬雄都因作赋，“用精思大剧而得病”。作者和吴兆骞创作都很勤奋，尤其是吴兆骞，儿童时就作胆赋，“累千余言”。（见《国朝先正事略》）\n但愿得，河清人寿：河，指黄河。黄河水浊，古时认为黄河清就天下太平。古人云：“俟河之清，人寿几何。”认为黄河千年一清，而人寿有限。这里是希望一切好转，吴兆骞能归来的意思。\n行戍稿：在戍边时所写的稿子。', poem_appreciation = '二作系以书信格式入词，十分别致。“季子平安否？”写信先须问对方安好，这首句正是问安口气。不过用“季子”二字却有深意。这里用“季子”二字既切合吴兆骞的姓氏，又使入联想其才德，而且还表明吴地人。（一说，吴兆骞有二兄，季子言其排行。）拿吴季子比吴兆骞，其人才德令人钦佩，而却受了这种冤枉，就更令人同情。所以五个字看似寻常，实则有力地领起全篇。“便归来，平生万事，那堪回首？”这是用假设语句极力同情吴兆骞的痛苦经历。即使现在就能回到家乡，这段经历中的千难万苦，又那堪回想。何况现在没有归来，还在经受着这些不堪回首的痛苦。“行路悠悠准慰藉，母老家贫子幼。”这是就不堪回首的痛苦中特别提出充军关外的遭遇，没有谁能加以安慰，家庭又是如此困难——母老家贫子幼。过去的一切欢乐都无影无踪，“记不起、从前杯酒”。朋友的文酒之会，杯酒相欢，不要说现在没有了，就连过去的记忆也消失了，令人伤心。“魑魅搏人应见惯，总输他，覆雨翻云手。”“搏人”，这是含蓄地为吴兆骞鸣不平。“魑魅搏人”，比喻坏人以卑劣的手段陷害人。桂甫诗：“纷纷轻薄何足数，翻手为云覆手雨。”这里用杜意，就是说，君子总要吃小人的亏。应该提出的是清代文字狱频繁，士人往住转喉触讳。吴兆骞是朝廷谪戍的，既要同情兆骞，又要回避触犯朝廷，只能笼统地这样解说，这在当时已经算是大胆的了。“冰与雪，周旋久。”这是切题中宁古塔的特点。塞外苦寒，作者此时在京师风雪之中，想象好友塞外，只能与冰雪周旋，而一过就是多年，定令人难受。这上片痛快淋漓地为吴兆骞的痛苦倾诉，下片一转变成多方安慰开脱，希望他不要为痛苦所摧垮。\n\n　　汉时王章夫妻牛衣对泣的事，作者反用为“泪哀莫滴牛衣透”，劝也不要过分伤心，原因何在，“数天涯，依然骨肉，几家能够？比似红颜多命薄，更不如今还有？”没有几家能够骨肉团聚，吴兆骞虽远在关外，却还能牛农对泣，骨肉一处，这是骨肉分散的还好些。再说红颜命薄，古今一辙，有才往往命途多舛。这样退一步想，也就得些宽慰。但劝慰要有分寸，只能说到这地步，笔锋一转又为他难受：“只绝塞、苦寒难受。”这和上片结尾“冰与雪，周旋久”相呼应。“廿载包胥承一诺，盼乌头马角终相救”，化用春秋后期申包胥立誓救楚和燕太子丹质于秦而后得归的典故，作者把它们巧妙地组织在一起，表示不管多大困准，一定要像申包胥那样尽力救他回来。沉痛感人。“置此札，君怀袖”：这封信请你保存。就是凭证。这几句表现死生不愉的友情，感人肺腑，催入泪下。\n\n　　第一首从吴兆骞写，第二首换个角度从自己发感慨：“我亦飘零久。十年来，深恩负尽，死生师友！”说得沉痛，“亦”字勾留上首，不是泛泛。“宿昔齐名非泰窃，试看杜陵消瘦。曾不减、夜郎僝僽。”从自己又说到两人。杜甫《长沙送李十一衔》：“李杜齐名真悉窃，朔云寒菊倍离忧。”杜甫是客气话。历史上李杜齐名有好多个，东汉的李固杜乔、李膺杜密等等，唐朝诗人李白杜甫，这儿反用杜诗说“非忝窃”，以杜甫自比。“试看杜陵消瘦。”以李白比吴兆骞，李白曾被长流夜邹（中道放归），比吴兆骞之滴戍宁古塔，“僝僽”，指受折磨和愁苦烦恼。自己虽然没有谪戍，却和吴兆骞一样痛苦，备受析磨。“薄命长辞知己别，问人生、到此凄凉否？”红颜薄命，长辞指死亡。顾贞观曾有悼亡之戚，薄命长辞，知已远别，人生逢此，是妻凉。人生之中没有多少人曾到这样凄凉境地。“问人生”这一反问句就包含上两层意思。“千万恨，为兄剖，自然收束半片。\n\n　　换头处，从年龄诉说，“兄生辛未吾丁丑”。辛未、丁丑到作此词时，两人都过了四十，“四十曰强，仕。”但“共些时，冰霜摧折，早衰蒲柳”，身体都受到摧残而早衰了。蒲柳是用《世说新语》顾悦与晋简文帝同岁而先老的典故，而“蒲柳”就变成自指身体的谦词了。这里用个“共”字，表示两人都一样，这是回应上文“试看杜陵消瘦，曾不减、夜郎僝僽。” 既然年过四十，身体早衰，就应注意保养：“词赋从今须少作，留取心魂相守。”两句语重心长。既然可以“相守”，表明前途仍有希望。“但愿得、河清人寿。”（“俟河之情，人寿几何？”“黄河清，出圣人。”）这句祝愿，字面用前一句，意思在后一句。希望圣主施恩，远人归老家园。政治清明，相应地人民应该生活安定，终其天年，所以说“河倩清人寿”。“归日急翻行戍稿，把空名料理传身后。”，吴兆骞的诗必传于后是作者的预言，也是完全符合实际的。吴兆骞流放以后，诗歌增加了悲壮苍凉的气氛，为人传诵，在清代前期也算重要作家。这表现作者对吴兆骞的信任和安慰。不说“声名”而说“空名”，这个“空”字把上文一系列苦痛都括在其中，大名没有使吴兆骞免除生前的苦难，所以说“空名”，这个“空”字可以算一字千金。“言又尽，观顿首”，仍然是书信格式。', poem_tags = '友情' WHERE poem_title = '金缕曲二首' AND poem_author = '顾贞观';
UPDATE edu_poem SET poem_tags = '春天,抒情,怀人' WHERE poem_title = '江城子' AND poem_author = '秦观';
UPDATE edu_poem SET poem_translation = '译文 灿灿的萱草花，生在北堂之下。 南风吹着萱草，摇摆着是为了谁吐露着芬芳？ 慈祥的母亲倚着门盼望着孩子，远行的游子是那样的苦啊！ 对双亲的奉养每天都在疏远，孩子的音讯每天都不能传到。 抬头看着一片云林，听到慧鸟的叫声思念起来至此很是惭愧。', poem_tags = '母亲,思念,游子' WHERE poem_title = '墨萱图·其一' AND poem_author = '王冕';
UPDATE edu_poem SET poem_translation = '和你结发成为夫妻，就从没怀疑与你恩爱到老。\n和你相爱缠绵陶醉在今夜幸福的时刻，多么美好的时光呀!\n可是明天我就要为国远行，不得不起来看看天亮没亮是什么时候了。\n当星辰隐没在天边时，我就不得不与你辞别了，\n因为要到战场上这一走不知道什么时候才能与你团聚。\n与你依依不舍长时间的握着手也是幸福的，相互不由自主的流泪是因为这可能是你我今生的最后一面。\n我倍加珍惜现在幸福的每分每秒，我永远也不会忘了和你相爱，这么幸福欢乐的时光。\n如果我有幸能活着，一定会回到你身边。如果我不幸死了，也会永远想你……', poem_notes = '结发：束发，借指男女始成年时。古时男年二十、女年十五束发，以示成年。　\n嬿婉：欢好貌。　\n怀往路：想着出行的事。“往路”一作“远路”。　\n夜何其：语出《诗经·庭燎》：“夜如何其？”是说“夜晚何时？”其，语尾助词。　\n参（shēn申）、辰：二星名，代指所有星宿。这句是说星星都已隐没，天将放晓了。　\n行役：赴役远行。　\n生别：生离死别。一作“别生”。滋：多。　\n春华：春光，借喻少壮时期。', poem_tags = '新婚,离别,思念' WHERE poem_title = '留别妻' AND poem_author = '苏武';
UPDATE edu_poem SET poem_translation = '年复一年，我驰骋疆场，战袍上洒满了灰尘；今天，在“得得”的马蹄声中，缓缓登上齐山，浏览翠微亭的美景。\n好山好水，我怎么也看不够，可已是明月当空，马蹄声又催着我踏上了归程。', poem_notes = '池州：今安徽贵池。\n翠微亭：在贵池南齐山顶上。\n经年：常年。\n征衣：离家远行的人的衣服。这里指从军的衣服。\n特特：特地、专门。亦可解作马蹄声，二义皆通。\n寻芳：游春看花。\n翠微：指翠微亭。\n看不足：看不够。', poem_appreciation = '“池州”，是宋代江南东路的一个州，州府设在当时的秋浦，就是现在的安徽省池州市贵池区。这里作者以州名代指州府名。“翠微亭”，在今安徽贵池南边的齐山上，是唐代大诗人杜牧在武宗会昌年间任池州刺史时建造的。\n\n　　这是一首记游诗，主要记述登临池州翠微亭观览胜景的心理状态和出游情形，表现了作者对祖国山河的无限热爱之情。前两句写出游的愉悦。起句“经年尘土满征衣”写长期紧张的军旅生活。诗人从军后，一直过着紧张的军事生活，特别是在抗金斗争中，为了保卫南宋残存的半壁河山，进而恢复中原，他披甲执锐，率领军队，冲锋陷阵，转战南北，长期奔波，把全部精力都投入到保卫国家的伟大事业之中。诗的开头一句正是对这种紧张军旅生活的生动朴实的高度概括。“经年”，这里指很长时间以来。“征衣”，这里是指长期在外作战所穿的衣服。既然长年累月地率领部队转战南北，生活十分紧张，那就根本没有时间、没有心思去悠闲地游览和欣赏祖国的大好河山。愈是这样，愈盼望有朝一日能够有这样的一个机会。这样，起笔一句就为下面内容的引出作了充分的渲染和铺垫，看似与记游无关，而作用却在于突出、强调和反衬了这次出游的难得与可贵，故对句以“特特寻芳上翠微”接住。现在，诗人竟然有了这样的机会，到齐山观览，而且登上了著名诗人杜牧在这里建造的翠微亭，心里一定愉快、兴奋。“特特”，在这里有两层意思，一是当特别、特地讲，起了强调、突出的作用，以承接首句意脉，一是指马蹄声，交待了这次出游是骑马去的，成为诗歌结尾一句的伏笔。“寻芳”，探赏美好的景色。“翠微”，是诗人到达的地方。这样，对句实际上写了出游的方式（骑马）和到达的地点（翠微亭），从而起到了点题、破题的作用。诗的开头两句，首句起笔突兀，如高山坠石，不知其来，似与题目无关，而实为次句铺垫；次句陡转笔锋扣题，承接自然，成为首句的照应；两句相互配合，表现出作者大起大落、大开大阖的高度艺术腕力和高屋建瓴的雄伟气魄。两句形成了波澜和对比，从而突出了这次出游的欣喜。\n\n　　“好水好山看不足，马蹄催趁月明归。”诗的三四两句并没有象一般的记游诗那样，对看到的景色作具体细致的描述，而是着眼于主观感觉，用“好水好山”概括地写出了这次“寻芳”的感受，将秀丽的山水和优美的景色用最普通、最朴实、最通俗的“好”字来表达，既有主观的感受，又有高度的赞美。同时，又用“看不足”传达自己对“好水好山”的喜爱、依恋和欣赏。结尾一句则写了诗人为祖国壮丽的山河所陶醉，乐而忘返，直到夜幕降临，才在月光下骑马返回。“马蹄”，照应了上面的“特特”。“催”字则写出了马蹄声响使诗人从陶醉中清醒过来的情态，确切而传神。“月明归”，说明回返时间之晚，它同上句的“看不足”一起，充分写出了诗人对山水景色的无限热爱、无限留恋。岳飞之所以成为民族英雄，之所以为自己的国家英勇战斗，同他如此热恋祖国的大好河山是密不可分的。诗的结尾两句正表现了作者对祖国山河特有的深厚感情。\n\n　　这首诗通过记游，抒发了作者对祖国山河无限深厚的热爱之情。在艺术上运思巧妙，不落俗套，虽是记游，而不具体描述景物，重在抒写个人感受。其结构方式除以时间为序外，又把情感的变化作为全诗的线索，突出了这次出游登临的喜悦。语言通俗自然，明白如话。', poem_tags = '古诗三百首,纪游,写景,热爱' WHERE poem_title = '池州翠微亭' AND poem_author = '岳飞';
UPDATE edu_poem SET poem_translation = '远处郁郁葱葱的树林尽头，有耸立的高山。近处竹林围绕的屋舍边，有长满衰草的小池塘，蝉鸣缭乱。空中不时有白色的小鸟飞过，塘中红色的荷花散发幽香。\n　　在乡村的野外，古城墙的近旁，我手拄藜杖慢步徘徊，转瞬已是夕阳。昨夜天公殷殷勤勤地降下一场微雨，今天又能使漂泊不定的人享受一日的爽心清凉。', poem_notes = '鹧鸪天：词牌名。\n林断山明：树林断绝处，山峰显现出来。\n翻空：飞翔在空中。\n红蕖（qú）：荷花。\n古城：当指黄州古城。\n杖藜 ：拄着藜杖。杜甫《漫兴九首》其五：“杖藜徐步立芳洲。”藜：一种草本植物，这里指藜木拐杖。\n殷勤：劳驾，有劳。\n浮生：意为世事不定，人生短促。李涉《题鹤林寺僧舍》：“偶经竹院逢僧话，又得浮生半日闲。”', poem_appreciation = '此词上片写景，下片刻画人物形象，描写人物的心理状态。开头两句，作者以推移镜头，由远而近，描绘自己所处的特殊环境：远处有郁郁葱葱的树林，树林尽头，有座高山清晰可见；近处，丛生的翠竹，象绿色的屏障，围护在一所墙院周围。这所墙院正是词人的居所。靠近院落，有一池塘，池边大约由于天旱缺水，满地长着枯萎的衰草。蝉声四起，叫声乱成一团，令人烦躁不安。在这两句词中，竟然描写出林、山、竹、墙、蝉、草、池塘七种景色，容量如此之大，在古典诗词里也是不多见的。这里呈现的景象，跟词人熙宁十年（1077）任徐州知州时所描写的景象迥然不同。那时作者写下的词句是：“麻叶层层檾叶光，谁家煮茧一村香。”“软草平莎过雨新，轻沙走马路无尘。”（《浣溪沙·徐门石潭谢雨道上作五首》）那是一种奔腾奋发、蒸蒸日上的景象。而“林断山明竹隐墙，乱蝉衰草小池塘”，则完全是一种杂乱、衰萎的景象，显得苍白无力，缺乏生机。词人为何会描写出此等景象呢？原来，词人在徐州任知州时，政绩卓著，深得民心，所以他当时写的词作，充满着积极奋发的精神。后来，他受到打击，被贬到黄州，充任团练副使，处境十分艰难，才能无从施展，被迫过着隐退生活，所以心情苦闷，精神不振。这就无怪乎他的词章变得这样凄清苍凉了。\n\n　　三、四两句，含义更深邃。从词句上看，这两句描写得比较优美：在广阔的天空，不时看到白鸟上下翻飞、自由翱翔，满池荷花，映照绿水，散发出柔和的芳香。意境如此清新淡雅，颇有些诗情画意。“红蕖”，是荷花的别名。“细细香”，是说荷花散发出的香味不是扑鼻的浓烈香气，而是宜人的淡淡芳香。如果不是别的原因，这样的境界的确是修身养性的乐土。然而，对于词人来说，他并非安于现状，有心流连这里的景致。他虽然描绘出白鸟翻空，红荷照水的画面，但这和他倾心欣赏杭州西湖那种“淡妆浓抹总相宜”的美丽景色，是不能相提并论的。透过这样一幅画面，读者能够隐隐约约看到词人那种百无聊赖、自寻安慰、无可奈何的心境。词的下片，作者又用自我形象的描绘，作了生动的说明。\n\n　　下片前三句，是写太阳在即将落山的时候，词人拄着藜杖在村边小道上徐徐漫步。这是词人自我形象的写照。但他表现的究竟是怎样的形象呢？是老态龙钟，还是病后的神态？是表现自得其乐的隐者生活，还是百无聊赖、消磨时光的失意情绪？读者仔细玩味，自然会得出正确的答案。\n\n　　最后两句，是画龙点睛之笔。词句的表面是说：天公想得挺周到，昨天夜里三更时分，下了一场好雨，又使得词人度过了一天凉爽的日子。“殷勤”二字，犹言“多承”。细细品评，在这两个字里，还含有某些意外之意，即是说：有谁还能想到几经贬谪的词人呢？大概世人早已把我忘却了，唯有天公还想到我，为我降下“三更雨”。所以，在“殷勤”两字中还隐藏着词人的无限感慨。“又得浮生一日凉”，是词中最显露的一句。“浮生”，是说人生飘忽不定，是一种消极的人生哲学。《庄子·刻意》篇说：“其生若浮，其死若休。”苏轼的这种消极思想，就是受庄子思想的影响。“又得浮生一日凉”中的“又”字，分量很重，对揭示主题，起着重要的作用，它表现词人得过且过、日复一日地消磨岁月的消极情绪。\n\n　　总观全词，从词作对特定环境的描写和作者形象的刻画，就可以看到一个抑郁不得志的隐者形象。', poem_tags = '写景,写人,隐居,生活,抒怀' WHERE poem_title = '鹧鸪天·林断山明竹隐墙' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '忽然之间，已经是细雨飘飞的春天了，怎堪芳草青青。\n宫中把新火赐给大臣，大臣们无事，以蹴鞠为戏。\n路上骏马乱叫，绿杨丛里，秋千上下飞舞。\n游人还记得以前太平时候的盛事，这和昔年相似的风光，引起心头的隐隐快乐。', poem_notes = '蚤：“蚤”通“早”。\n梦雨：春天如丝的细雨。\n可堪：意思是不可堪，不能忍受。\n芊（qiān）芊：草木茂盛的样子。\n内官：国君左右的亲近臣僚。又指宦官太监。\n初赐清明火：一种古代风俗，寒食禁火，把冬季保留下来的火种熄灭了。到了清明，又要重新钻木取火。唐代的皇帝于此日要举行隆重的“清明赐火”典礼，把新的火种赐给群臣，以表示对臣民的宠爱。\n上相：泛指大臣。\n白打钱：玩蹴鞠游戏，优胜者受赐金钱，种“白打钱”，一说白打钱指斗鸡。\n紫陌：大路。“陌”本是指田间的小路，这里借指道路：“紫”是指道路两旁草木的颜色。\n红叱（chì）拨：唐天宝中从西域进汗血马六匹分别以红、紫、青、黄、丁香、桃花叱拨为名，这里泛指骏马。\n画秋千：装饰美丽的秋千。\n承平：太平。', poem_appreciation = '这首诗语言清新，诗人通过写清明节时的人事和景物，来透露出诗人对盛世的怀念与对现实朝野状况的失望。\n\n　　首联描写自己独伤春，朝与野之人游春、赏春。开头诗人便暗用了杜甫《登楼》“花近高楼伤客心，万方多难此登临”的诗意，抒发别有怀抱的诗人的伤春愁绪。诗人在春雨霏霏的阴沉灭气中，内心郁苦愁闷，更由芊芊芳草增添凄迷冷落之情。“蚤是”、“可堪”这两个虚词，构成语意表达的递进关系，将诗人内心的凄楚表现得深长而急切。但是，后面所描写的并不是诗人自己的情态举止，而是朝廷内外游人的赏春之乐。\n\n　　颔联描写宫中清明节的风俗和游乐。韩翃《寒食》诗有云：“春城无处不飞花，寒食东风稠柳斜。日暮汉宫传蜡烛，轻烟散人五侯家。”此诗“内官初赐清明火”句，即描写皇宫内清明节取榆柳火赏赐近臣的节俗。一个“初”字，暗示了此时动乱刚定，朝廷复行旧日礼制。“上相闲分白打钱”一句描写宫中蹴鞠游戏之乐，一个“闲”字，则交代了贵为朝廷宰相却无所作为的状态。\n\n　　颈联描写宫外游春繁盛的景象。在京师郊野的道路上，红色的骏马嘶鸣不已，游春的男子络绎不绝；在绿杨掩映的庭院中，女子们正在欢快地荡着秋千。这里的色彩鲜艳夺目，所见所闻热闹非凡，一“乱”字、一“高”字，都尽显出晚唐时代人们沉湎在纵恣冶游的“世纪末”的狂欢之中。\n\n　　尾联展现身处其间的游人的欣慰。他们觉得如今的热闹喧闹，就像是昔年的升平风光，又可以忘却动乱的痛苦记忆，无所顾忌地享受眼前的快乐。然而，所谓的“升平”却是表象，诗人正是透过这虚假的繁荣，感受到了国势岌岌可危的形势，深藏着浓重的现实忧愁。\n\n　　诗人用冷峻的目光，看似闲淡地刻画长安城清明时分热闹如昔、游人如织的欢快场面，实则暗含着深沉的讽刺、斥责之意，以“游人”之喜乐，愈加反衬出诗人“伤时伤世复伤心”的悲郁之情。', poem_tags = '清明节,怀念' WHERE poem_title = '长安清明' AND poem_author = '韦庄';
UPDATE edu_poem SET poem_appreciation = '在历代的诗词中，有不少咏梅之作。早在南朝诗人何逊的《扬州法曹梅花盛开》诗中，就写下“衔霜当路发，映雪拟寒开“的名句。鲍照的《梅花落》则以庭院中的杂树为反衬，赞叹梅花“念其霜中能作花，露中能作实”。体物写志，借事明情，在诗人们笔底下的梅花，常常被引为傲视霜雪，坚贞不屈的高洁品质的象征。柳宗元的《早梅》诗同样如此。诗人以早梅迎风斗寒，昂首开放的英姿，委婉地表达了自己正直无私的胸怀，显示出对理想执着追求的意志，表现了自己孤傲高洁的品格和不屈不挠的斗争精神。这首诗用简朴、疏淡的文辞刻画早梅傲立风霜昂首开放的形象，抒写诗人的情志，状难写之物如在眼前，含不尽之意见于言外，梅的风骨与作者的人格融为一体，含蓄蕴藉，感情深挚委曲，给人以很强的感染力。\n\n　　“早梅发高树”，起句直写梅花，笔姿飞扬，醒人耳目。一个“发”字极富于神韵，不仅写出梅花绽开的形象，而且予人一种“能开天地春”（清人沈钦圻咏梅诗句）的生机蓬勃的感受，把早梅昂首怒放、生机盎然的形象逼真地展现在读者的眼前。其背景高远广阔的碧蓝的天空，不仅映衬着梅花的色泽，更突出了它的雅洁，不同凡俗。高树，既是实写，又是诗人心中意象的再现，自喻行高于时人，并与下旬“迥映楚天碧“紧相粘连，构成一幅情景融和的意境。避望楚天，辽阔无际，明净的碧空映照着早梅发出的光泽，使人感到梅花分外娴静高洁。这两句诗，言辞简洁，而情波荡漾，深寓着诗人对早梅的赞叹之意。诚如王国维所说， “以我观物，故物皆着我之色彩。”\n\n　　第一、二两句是描写梅花的外在之形，“朔吹飘夜香，繁霜滋晓白。”两句进一层刻画早梅内在的气质。尽管北风吹打，严霜相逼，而梅花仍然在寒风中散发着缕缕芬芳，在浓霜中增添着洁白的光泽。这两句诗一写“香”，一写“色”，集中地写出早梅傲视风霜，力斡春回的风格。“飘”字寓有四散的意思，王冕《墨梅》诗有“只留清气满乾坤”，用的也是这个意思。诗人咏梅，目的是为了抒怀，是为了言志。诗中梅花的品格也是诗人心灵的一种物化。\n\n　　诗的下面四句，由咏物而转入抒怀，进而推出新意。当诗人看到早梅绽放的时侯，不禁怀念起远方的友人来，于是借物抒怀：“欲为万里赠，杳杳山水隔。寒英坐销落，何用慰远客？”往事如潮，涌上心头。他极想攀折一枝寒梅，赠与友人聊以表达慰勉的情意。可是转念一想，千里迢迢，山水阻隔，这是无法如愿的。柳宗元被贬永州后，“罪谤交织，群疑当道”， “故旧大臣”已不敢和他通音讯，在寂寞和孤独中艰难度日的柳宗元是多么思念亲友们啊！于是想到折梅相送，可亲友们远在万里之外，是根本无法送到的。这里除了地理上的原因外，还有政治上的原因，他作为一个“羁囚”不能连累了亲友。透过字里行间，人们不难体会到诗人那种伥惘、不平之情。这两句诗，原是化用北朝陆凯《赠范晔》“折花逢驿使，寄与陇头人；江南无所有，聊赠一枝春”的诗意。都是叙写对故人的思念，但是两诗的情趣迥然不同，陆诗洒脱，柳诗沉郁。正是因为他们写诗时的处境和心情并不相同，情趣也就各异了。\n\n　　“寒英坐销落，何用慰远客？”两句诗是紧承上两句发展出来的，含有更深一层的意义。诗人意识到，由于关山阻隔，时日过久，梅花势将枯萎凋零，于是喟叹“我将用什么去慰问远方的友人呢？”。柳宗元从梅的早开早落联想到自己的身世，自己的境遇，不禁忧从中来。正因为忧其早开早落，所以柳宗元也是在自我勉励，自我鞭策。\n\n　　这首《早梅》语言平实质直，不事藻饰，意脉若隐若现，艺术美和人格美的融和合一，形式的质朴，感情的其淳，流露出来的诗人的高洁、孤傲的情志。', poem_tags = '咏物,梅花,抒怀' WHERE poem_title = '早梅' AND poem_author = '柳宗元';
UPDATE edu_poem SET poem_translation = '译文 　　二月里的湖水呀是那么清澈，家家户户春意盎然，鸟儿快乐地鸣叫。树林里的花儿开了又谢，扫也扫不完；小径上翠绿的青草呀，充满了勃勃生机，踏上去之后，很快就又可以生长起来。我的酒友又来喊我去喝酒了，我们拿出酒杯啊，打开酒瓮。酒杯握在手中啊，歌妓们在眼前唱歌跳舞。歌舞是那么的优美动人啊，千万不要停下来啊！', poem_tags = '春天' WHERE poem_title = '春中喜王九相寻 / 晚春' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '桃李不要嫉妒我红梅，红梅和桃李开花的样子原来就不同，\n红梅经历了风雪，身上还有雪的痕迹。它却还是不承认自己的色彩很红艳。', poem_notes = '莫：不要。\n元：通“原” ， 原本。', poem_tags = '咏物,梅花,品格' WHERE poem_title = '红梅' AND poem_author = '王十朋';
UPDATE edu_poem SET poem_translation = '春雨迅猛，池塘水满，遥望群山，高低不齐，东边西侧，山路崎岖。热热闹闹地开了一阵的桃花和李花，此刻已开过时了，只见眼前春草萋萋，碧绿一片。', poem_notes = '路东西:分东西两路奔流而去\n横塘：古塘名，在今南京城南秦淮河南岸\n乱山高下：群山高低起伏', poem_tags = '古诗三百首,写花,写草,哲理' WHERE poem_title = '城南' AND poem_author = '曾巩';
UPDATE edu_poem SET poem_translation = '深秋时分，在这遥远的边塞，有谁能记得我？树叶发出萧萧的声响。返乡之路千里迢迢。家和梦一样遥不可及。重阳佳节，故园风光正好，离愁倍增。不愿登高远望。只觉心中悲伤不已。当鸿雁南归之际，将更加冷落凄凉。', poem_notes = '九日。即农历九月九日，是为重阳节。逢此日，古人要登高饮菊花酒，插茱萸，与亲人团聚。\n绝塞：极遥远之边塞。\n木叶：木叶即为树叶，在古典诗歌中特指落叶。\n萧：风声；草木摇落声。\n迢迢（tiáo）：形容遥远。\n六曲句：六曲屏山，曲折之屏风。因屏风曲折若重山叠嶂，或谓屏风上绘有山水图画等，故称“屏山”。此处代指家园。这句是说，故乡那么遥远，只有在梦中才能见到她。\n登高：重阳有登高之俗。\n魂销：极度悲伤。', poem_appreciation = '纳兰容若一向柔情细腻，这阙《采桑子》却写得十分简练壮阔，将边塞秋景和旅人的秋思完美地结合起来。仅用聊聊数十字写透了天涯羁客的悲苦，十分利落。上阙写秋光秋色，落笔壮阔，“六曲屏山和梦遥”点出边塞山势回环，路途漫长难行，遥应了“绝塞”一词，亦将眼前山色和梦联系起来，相思变得流水一样生动婉转，意境深广。下阙更翻王维诗意，道出了不为登高。只觉魂销这样仿佛雨打残荷般清凉警心的句子，轻描淡写地将王维诗意化解为词意，似有若无，如此恰到好处。结句亦如南雁远飞般空旷，余意不尽。大雁有自由飞回家乡，人却在这深秋绝塞路上渐行渐远。愁情沁体，心思深处，魂不堪重负，久久不消散。\n\n　　“不为登高。只觉魂销“一句，词中有诗的意境。也非是用词这种格式流水潺潺地表达，换另一种都不会如此完美。“青山隐隐水迢迢，秋尽江南草木凋“是杜牧诗中意境；“遥知兄弟登高处，遍插茱萸少一人。“是王维诗中景象。而今，这一切尽归容若。容若此词，看似平淡，其实抬手间已化尽前人血骨。', poem_tags = '重阳节,边塞,写景,相思' WHERE poem_title = '采桑子·九日' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '叹息着这年老的身体怎么能像年一样循环更新呢。\n在石门旁思索了很久要不要隐退，看见铜镜里年老的容貌忍不住再三窥视。\n花又开了，路旁移来了新的树，我心里知道这是故国的春天来了。\n谁能来扫平心中的不满呢？反正不是佛教的。', poem_notes = '嗟：叹息。\n龙钟身：年老的身体。龙钟，年迈。\n谁能……北宗人：当时国家正遭受战火，此句表现自己身为佛教中人对战争的无能为力。\n北宗：佛教禅宗的一派，以神秀为代表。', poem_tags = '节日,新年,抒怀,忧国忧民' WHERE poem_title = '新年' AND poem_author = '贾岛';
UPDATE edu_poem SET poem_translation = '郭橐驼，不知道他起初叫什么名字。他患了脊背弯曲的病，脊背突起而弯腰行走，就像骆驼一样，所以乡里人称呼他叫“橐驼”。橐驼听说后，说：“这个名字很好啊，这样称呼我确实恰当。”于是他舍弃了他原来的名字，也自称起“橐驼”来。\n\n　　他的家乡叫丰乐乡，在长安城西边。郭橐驼以种树为职业，凡是长安城里经营园林游览和做水果买卖的豪富人，都争着把他接到家里奉养。观察橐驼种的树，有的是移植来的，也没有不成活的；而且长得高大茂盛，结果实早而且多。其他种树的人即使暗中观察、羡慕效仿，也没有谁能比得上。\n\n　　有人问他种树种得好的原因，他回答说：“我郭橐驼不是能够使树木活得长久而且长得很快，只不过能够顺应树木的天性，来实现其自身的习性罢了。但凡种树的方法，它的树根要舒展，它的培土要平均，它根下的土要用原来培育树苗的土，它捣土要结实。已经这样做了，就不要再动，不要再忧虑它，离开它不再回顾。栽种时要像对待子女一样细心，栽好后要像丢弃它一样放在一边，那么树木的天性就得以保全，它的习性就得以实现。所以我只不过不妨碍它的生长罢了，并不是有能使它长得高大茂盛的办法；只不过不抑制、减少它的结果罢了，也并不是有能使它果实结得早又多的办法。别的种树人却不是这样，树根拳曲又换了生土；他培土的时候，不是过紧就是太松。如果有能够和这种做法相反的人，就又太过于吝惜它们了，担心它太过分了，在早晨去看了，在晚上又去摸摸，已经离开了，又回头去看看。更严重的，甚至掐破树皮来观察它是死是活着，摇晃树根来看它是否栽结实了，这样树木的天性就一天天远去了。虽然说是喜爱它，这实际上是害了它，虽说是担心它，这实际上是仇视它。所以他们都不如我。我又能做什么呢？”\n\n　　问的人说：“把你种树的方法，转用到做官治民上，可行吗？”橐驼说：“我只知道种树罢了，做官治民,不是我的职业。但是我住在乡里，看见那些官吏喜欢不断地发号施令，好像是很怜爱(百姓)啊，但百姓最终反因此受到祸害。在早上在晚上那些小吏跑来大喊：‘长官命令：催促你们耕地，勉励你们种植，督促你们收获，早些煮茧抽丝，早些织你们的布，养育你们的小孩，喂大你们的鸡和猪。’一会儿打鼓招聚大家，一会儿鼓梆召集大家，我们这些小百姓停止吃早、晚饭去慰劳那些小吏尚且不得空暇，又怎能使我们繁衍生息，使我们民心安定呢？所以我们既困苦又疲乏,像这样（治民反而扰民），它与我种树的行当大概也有相似的地方吧？”\n\n　　问的人说：“不也是很好吗！我问种树的方法，得到了治民的方法。”我为这件事作传把它作为官吏们的鉴戒。', poem_notes = '橐（tuó）驼：骆驼。这里指驼背。\n始：最初。\n病瘘（lǘ）：患了脊背弯曲的病。\n隆然：脊背突起而弯腰行走。\n有类：有些像。\n号之：给他起个外号叫。号，起外号。\n之：代词，指起外号事。\n名我固当：这样称呼我确实恰当。名，称呼，名词作动词，意动用法。固：确实。当：恰当。\n因：于是，就，副词。舍：舍弃。其名：他原来的名字。\n谓：称为。云：句末语气词，此处可译“了”。\n长安：今西安市，唐王朝首都。\n业：以……为业，名词作动词。\n为观游：经营园林游览。为，从事，经营。\n争迎取养：争着迎接雇用（郭橐驼），取养：雇用。\n或：或者。移徙：指移植。徙，迁移。\n硕茂：高大茂盛。\n早实：早结果实。实，结果实，名词做动词。以：而且，连词，作用同“而”。蕃：多。\n他植者：其他种树的人。窥伺：偷偷地察看。效慕：仿效，慕也是“效“的意思。窥伺效慕：暗中观察，羡慕效仿。\n莫：没有谁，代词。如：比得上，动词。\n有问之：有人问他（种树的经验）。\n木：树。橐驼：古人最郑重最恭敬的自称法，是自称其名，可译“我”。寿且孳（zī）：活得长久而且繁殖茂盛。孳，繁殖。\n天：指自然生长规律。致其性：使它按照自己的本性成长。致，使达到。焉尔：罢了，句末语气词连用。\n凡：凡是，所有，表示概括，副词。植木之性：按树木的本性种植。性，指树木固有的特点。\n本：树根。欲：要。舒：舒展。培：培土。\n故：旧。\n筑：捣土。密：结实。\n既然：已经这样。已：（做）完了。勿动：不要再动它。\n勿虑：不要再担心它。\n去：离开。顾：回头看。其：如果，连词。\n莳（shì）：栽种。若子：像对待子女一样精心。\n置：放在一边。若弃：像丢弃了一样不管。\n则其天者全而其性得矣：那么树木的生长规律可以保全而它的本性得到了。则：那么，连词。者：助词，无义。\n不害其长：不妨碍它的生长。而已：罢了，句末语气词连用。\n硕茂：使动用法，使高大茂盛。\n不抑耗其实：不抑制、损耗它的果实（的成熟过程）。\n早而蕃：使动用法，使……（结实）早而且多。\n根拳：树根拳曲。土易：更换新土。\n若不过焉则不及：如果不是过多就是不够。若……则……，如果……那么（就），连接假设复句的固定结构。焉：句中语气词，无义。\n苟：如果，连词。反是者：与此相反的人。\n爱之太恩：爱它太情深。恩，有情义。这里可引申为”深“的意思。\n忧之太勤：担心它太过分。\n甚者：更严重的。甚，严重。\n爪其肤：掐破树皮。爪，掐，作动词用。以：表目的，连词，用来。验：检验，观察。生枯：活着还是枯死。\n疏密：指土的松与紧。\n日以离：一天天地失去。以，连词，连接状语和动词，不译。\n不我若：不若我，比不上我。否定句中代词作宾语时一般要置于动词前。若，及，赶得上，动词。\n之：助词，的。道：指种树的经验。\n之：代词，指种树之“道”。官理：为官治民。理，治理，唐人避高宗李治名讳，改“治”为“理”。\n而已：罢了。\n理：治理百姓。\n长（zhǎng）人者：为人之长者，指当官治民的地方官。大县的长官称“令”，小县的长官称“长”。烦其令：不断发号施令。烦，使繁多。\n若甚怜：好像很爱（百姓）。焉：代词，同“之”。\n而：但，连词。卒以祸：以祸卒，以祸（民）结束。卒，结束。\n官命：官府的命令。促尔耕：催促你们耕田。\n勖（xù）：勉励。植：栽种。\n督：督促。获：收割。\n缫（sāo）：煮茧抽丝。而：通“尔”，你们。绪：丝头。早缫而绪：早点缫好你们的丝。\n早织而缕：早点纺好你们的线。缕，线。\n字：养育。\n遂而鸡豚（tún）：喂养好你们的鸡和猪。遂，顺利地成长。豚，猪。\n聚之：召集百姓。聚：使聚集。\n木：这里指木梆。\n吾小人：我们小百姓。辍飧（sūn）饔（yōng）：不吃饭。辍，停止。飧，晚饭。饔，早饭。以：来，连词。劳吏者：慰劳当差的。且：尚且。暇：空暇。\n何以：以何，靠什么。蕃吾生：繁衍我们的生命，即使我们的人口兴旺。安吾性：安定我们的生活。性，生命。\n病：困苦。怠：疲倦。病且怠：困苦又疲劳。\n若是：像这样。\n与吾业者：与我同行业的人，指“他植者”。其：大概，语气词。类：相似。\n嘻：感叹词，表示高兴。\n不亦善夫：不是很好吗？夫，句末语气词。\n养人：养民，唐人避唐太宗李世民名讳，改“民”为“人”。\n传：作传。以为：以（之）为，把它作为。戒：鉴戒。', poem_appreciation = '种树人有“勤虑害树”的错误，做官者也有“烦令扰民”之过。\n\n　　本文是带有寓言和政论色彩的人物传记文。名“传”，实际上是一个讽喻性极强的寓言故事。是柳宗元早年在长安任职时期的作品。郭橐驼种树的本事已不可考，后世学者多认为这是设事明理之作。本文是针对当时官吏繁政扰民的现象而言的。这是一篇兼具寓言和政论色彩的传记散文。柳宗元在参加“永贞革新”前两年，即贞元十九年至二十一年(803—805)，曾任监察御史里行，是御史的见习官，可以和御史一样“分察百僚，巡按郡县，纠视刑狱，肃整朝仪”，可以到各地检查工作，民事、军事、财政都可以过问，品秩不高而权限较广。这篇文章，可能就是在此期间写的，是针对当时地方官吏扰民、伤民的现象而作的。这篇文章可以看成是柳宗元参加“永贞革新”的先声。', poem_tags = '古文观止,高中文言文,叙事,写人,传记' WHERE poem_title = '种树郭橐驼传' AND poem_author = '柳宗元';
UPDATE edu_poem SET poem_translation = '冬天到了，白天的时间就越来越短；\n漫天的雪在这个寒冷的夜晚停住了。\n天未明时，当地的驻军已开始活动起来，号角声起伏悲壮；\n倒映在三峡水中的星影摇曳不定。\n战乱的消息传来，千家万户哭声响彻四野；\n渔人、樵夫们在好几个地方唱起了民歌。\n（像）诸葛亮和公孙述这样的历史人物，（无论是贤还是愚）都终归黄土；\n我眼前的这点寂寥（指郊游和亲人间的慰藉）又算得了什么呢。', poem_notes = '阴阳：指日月。短景：指冬季日短。景：通“影”，日光。\n霁（jì）： 雪停。\n五更鼓角：天未明时，当地的驻军已开始活动起来。\n三峡：指瞿塘峡、巫峡、西陵峡。星河：银河，这里泛指天上的群星。\n野哭：战乱的消息传来，千家万户的哭声响彻四野。战伐：崔旰（gàn）之乱。\n夷歌：指四川境内少数民族的歌谣。夷，指当地少数民族。\n卧龙：指诸葛亮。《蜀书·诸葛亮传》：“徐庶……谓先主曰：‘诸葛孔明者，卧龙也。’”。跃马：指公孙述。字子阳，扶风人。西汉末年，天下大乱，他凭蜀地险要，自立为天子，号“白帝”。这里用晋代左思《蜀都赋》中“公孙跃马而称帝”之意。诸葛亮和公孙述在夔州都有祠庙，故诗中提到。这句是贤人和愚人终成黄土之意。\n人事：指交游。音书：指亲朋间的慰藉。漫：徒然、白白的。', poem_appreciation = '全诗写冬夜景色，有伤乱思乡之意。首联点明冬夜寒怆；颔联写夜中所闻所见；颈联写拂晓所闻；末联写极目武侯、白帝两庙而引出的感慨。\n\n　　开首二句点明时间。岁暮，指冬季；阴阳，指日月；短景，指冬天日短。一“催”字，形象地说明夜长昼短，使人觉得光阴荏苒，岁月逼人。次句天涯，指夔州，又有沦落天涯之意。在霜雪刚停的寒冬夜晚，雪光明朗如昼，诗人对着凄凉寒怆的夜景，不由感慨万千。\n\n　　“五更”二句，承次句“寒宵”，写出了夜中所闻所见。上句鼓角，指古代军中用以报时和发号施令的鼓声、号角声。晴朗的夜空，鼓角声分外响亮，正是五更天快亮的时候，诗人忧愁难眠，那声音更显得悲壮感人。这就从侧面烘托出夔州一带也不太平，黎明前军队已在加紧活动。诗人用“鼓角”二字点示，再和“五更”、“声悲壮”等词语结合，兵革未息、战争频仍的气氛就自然地传达出来了。下句说雨后天空无尘，天上银河显得格外澄澈，群星参差，映照峡江，星影在湍急的江流中摇曳不定。景色是够美的。前人赞扬此联写得“伟丽”。它的妙处在于：通过对句，诗人把他对时局的深切关怀和三峡夜深美景的欣赏，有声有色地表现出来，诗句气势苍凉恢廓，音调铿锵悦耳，辞采清丽夺目，“伟丽”中深蕴着诗人悲壮深沉的情怀。\n\n　　“野哭”二句，写拂晓前所闻。一闻战伐之事，就立即引起千家的恸哭，哭声传彻四野，景象凄惨。夷歌，指四川境内少数民族的歌谣。夔州是民族杂居之地。杜甫客居此地，渔夫樵子不时在深夜传来“夷歌”之声。“数处”指不只一处。这两句把偏远的夔州的典型环境刻画得很真实：“野哭”、“夷歌”，一个富有时代感，一个具有地方性。对这位忧国忧民的伟大诗人来说，这两种声音都使他倍感悲伤。\n\n　　“卧龙”二句，诗人极目远望夔州西郊的武侯庙和东南的白帝庙，而引出无限感慨。卧龙，指诸葛亮。跃马，化用左思《蜀都赋》“公孙跃马而称帝”句，意指公孙述在西汉末乘乱据蜀称帝。杜甫曾屡次咏到他：“公孙初据险，跃马意何长？”（《白帝城》）“勇略今何在？当年亦壮哉！”（《上白帝城二首》）。一世之雄，都成了黄土中的枯骨。末尾一句说，人事与音书，如今都只好任其寂寞了。结尾二句，流露出诗人极为忧愤感伤的情绪。清代沈德潜说：“结言贤愚同尽，则目前人事，远地音书，亦付之寂寥而已。”（《唐诗别裁》）像诸葛亮、公孙述这样的历史人物，不论是贤是愚，都同归于尽了。现实生活中，征戍、诛掠更造成广大人民天天都有死亡，作者眼前这点寂寥孤独，根本算不了什么。这话看似自遣之词，实际上却充分反映出诗人感情上的矛盾与苦恼。“志士幽人莫怨嗟，古来材大难为用！”（《古柏行》）“英雄余事业，衰迈久风尘。”（《上白帝城二首》）这些诗句正好传达出诗中某些未尽之意。前人认为此诗“意中言外，怆然有无穷之思”，是颇有见地的。\n\n　　此诗向来被誉为杜甫律诗中的典范性作品。诗人围绕题目，从几个重要侧面抒写夜宿西阁的所见所闻所感，从寒宵雪霁写到五更鼓角，从天空星河写到江上洪波，从山川形胜写到战乱人事，从当前现实写到千年往迹。气象雄阔，有上天下地、俯仰古今之概。明代胡应麟称赞此诗：“气象雄盖宇宙，法律细入毫芒”，并说它是七言律诗的“千秋鼻祖”，是很有道理的。', poem_tags = '唐诗三百首,冬天,战争,思乡' WHERE poem_title = '阁夜' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '十月天气很好，冬天的景色像春天一样可爱。\n寒霜未冻死小草，太阳晒干了大地。\n老柘树虽然叶子黄了，但仍然像初生的一样。\n这个时候的我只羡慕喝酒人的那份清闲，不知不觉走入酒家。', poem_tags = '冬天' WHERE poem_title = '早冬' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '屈原（被）流放了，三年不再能见（到国王）。（他）竭尽智慧用尽忠心，却被谗言遮挡和阻隔。（他）心情烦闷思想混乱，不知道何去何从。就前往拜见太卜郑詹尹说：“我有所疑惑，希望由先生您来决定。”詹尹就摆正蓍草拂净龟壳说：“您有什么赐教的啊？”\n　　屈原说：“我是宁愿忠实诚恳，朴实地忠诚呢，还是迎来送往，而使自己不会穷困呢？\n　　“是宁愿凭力气除草耕作呢，还是游说于达官贵人之中来成就名声呢？是宁愿直言不讳来使自身危殆呢，还是跟从习俗和富贵者来偷生呢？是宁愿超然脱俗来保全（自己的）纯真呢，还是阿谀逢迎战战兢兢，咿咿喔喔（语无伦次地谄言献媚）来巴结妇人呢？是宁愿廉洁正直来使自己清白呢，还是圆滑求全，像脂肪（一样滑）如熟皮（一样软），来谄媚阿谀呢？\n　　“是宁愿昂然（自傲）如同（一匹）千里马呢，还是如同（一只）普普通通的鸭子随波逐流，偷生来保全自己的身躯呢？\n　　“是宁愿和良马一起呢，还是跟随驽马的足迹呢？是宁愿与天鹅比翼齐飞呢，还是跟鸡鸭一起争食呢？\n　　“这些选择哪是吉哪是凶？应该何去何从？\n　　“（现实）世界浑浊不清：蝉翼被认为重，千钧被认为轻；黄钟被毁坏丢弃，瓦锅被认为可以发出雷鸣（般的声音）；谗言献媚的人位高名显，贤能的人士默默无闻。可叹啊沉默吧，谁知道我是廉洁忠贞的呢？”\n　　詹尹便放下蓍草辞谢道：“所谓尺有它不足的地方，寸有它的长处；物有它不足的地方，智慧有它不能明白的问题；卦有它算不到的事，神有它显不了灵的地方。您（还是）按照您自己的心，决定您自己的行为（吧）。龟壳蓍草实在无法知道这些事啊！”\n\n译文二\n　　屈原被流放后，三年没能再见楚怀王。他竭尽智慧效忠国家，却被谗言谤语把他和君王遮蔽阻隔。他心烦意乱，不知如何是好。于是去见太卜郑詹尹问卜说：“我对有些事疑惑不解，希望通过您的占卜帮助我分析判断。”郑詹尹就摆正蓍草、拂去龟甲上的灰尘，问道：“先生有何见教?”\n　　屈原说：“我宁可诚恳朴实、忠心耿耿呢，还是迎来送往、巧于逢迎而摆脱困境?宁可垦荒锄草勤劳耕作呢，还是交游权贵而沽名钓誉?宁可毫无隐讳地直言为自己招祸呢，还是顺从世俗贪图富贵而苟且偷生?宁可鹤立鸡群而保持正直操守呢，还是阿谀逢迎、强颜欢笑以侍奉那位妇人?宁可廉洁正直以保持自己的清白呢，还是圆滑诡诈、油滑适俗、趋炎附势?宁可像志行高远的千里驹呢，还是像浮游的野鸭随波逐流而保全自身?宁可与骐骥并驾齐驱呢，还是追随那劣马的足迹?宁可与天鹅比翼高飞呢，还是同鸡鸭在地上争食?上述种种，哪个是吉哪个是凶，哪个该舍弃哪个该遵从?现在的世道混浊不清：认为蝉翼是重的，千钧是轻的；黄钟大吕竟遭毁弃，瓦釜陶罐却响如雷鸣；谗佞小人嚣张跋扈，贤明之士则默默无闻。唉，沉默吧，谁人能知我廉洁忠贞的心哪!”\n　　郑詹尹于是放下蓍草抱歉地说：“尺比寸长但也有短处，寸比尺短却也有它的长处；世间万物都有不完善的地方，人的智慧也有不明了的时候；术数有占卜不到的事情，天神也有难解之理。请您花心思实行您的主张吧，龟甲和蓍草实在不知如何破解您的疑惑!”', poem_notes = '放:放逐。\n复见:指再见到楚王。\n蔽障:遮蔽、阻挠。\n太卜:掌管卜筮的官。\n因:凭借。\n端策:数计蓍草;端,数也。拂龟:拂去龟壳上的灰尘。\n悃(kǔn)悃款款:诚实勤恳的样子。\n送往劳来:送往迎来。劳(láo),慰劳。\n大人:指达官贵人。\n偷生:贪生。\n超然:高超的样子。高举:远走高飞。保真:保全真实的本性。\n哫訾(zú zī):以言献媚。栗斯:阿谀奉承状。栗：恭谨，恭敬。斯：语助词。喔咿儒儿(ní):强颜欢笑的样子。妇人:指楚怀王的宠姬郑袖，她与朝中重臣上官大夫等人联合排挤馋毁屈原。\n突梯:圆滑的样子。滑稽(gǔ jī):一种能转注吐酒、终日不竭的酒器,后借以指应付无穷、善于迎合别人。如脂如韦:谓像油脂一样光滑,像熟牛皮一样柔软,善于应付环境。洁楹:度量屋柱,顺圆而转,形容处世的圆滑随俗。洁,借为“絜(xié)“,《楚辞补注》引《文选》亦作“絜“。\n昂昂:昂首挺胸、堂堂正正的样子。\n泛泛:漂浮不定的样子。凫(fú):水鸟,即野鸭。此字下原有一“乎“字,据《楚辞补注》引一本删。\n亢轭(kàng\'è):并驾而行。亢,同“伉“,并也;轭,车辕前端的横木。\n驽(nú)马:劣马。\n宁与黄鹄比翼乎：黄鹄(hú):天鹅；比：旧读bì。\n鹜:鸭子。\n溷(hùn混)浊:肮脏、污浊。\n千钧:代表最重的东西。古制三十斤为一钧。\n黄钟:古乐中十二律之一,是最响最宏大的声调。这里指声调合于黄钟律的大钟。\n瓦釜:陶制的锅。这里代表鄙俗音乐。\n高张:指坏人气焰嚣张,趾高气扬。\n谢:辞谢,拒绝。\n数:卦数。逮:及。', poem_appreciation = '这篇文章记述了屈原的一件逸事，屈原被放逐三年之后，往见太卜郑詹尹问卜。无论它的作者是谁，这篇文章都是很有艺术价值与历史价值的。在先秦的典籍里，没有关于屈原的资料，最早为他立传的是西汉司马迁《史记·屈原列传》。也许因为搜集资料的困难，《屈原列传》的史料并不丰赡，倒是太史公与屈原的遭遇颇多相似，故借屈原的遭遇抒发自己的忧愤与怨怒，因此抒情胜于记事。屈原问卜未必实有其事，但屈原对自己的人生遭遇与做人处事的原则的反思却是非常真实的。屈原连设八问，以“宁”“将”两疑方式问卜，给人以不知所从的印象。其实，诗人的设问，与其说是他对人生道路和处世原则的困惑，倒不如说是他对黑白颠倒、清浊混淆的现实的震惊和愤慨。在你死我活的尖锐对立中，愈显出屈原廉洁正直、心性高洁的品格与坚持操守、绝不妥协的斗争精神。对屈原的研究，此文至少可供参考。\n\n　　全文以屈原问卜开篇，以詹尹“释策而谢”的答语收结，中间以连珠式的对立设问的语句贯穿，文采斐然，往复盘旋，八对设问，一一贯之。虽铺陈夸饰，句式整齐，却不板不散，亦无重复之嫌。气势充沛，感情强烈，体现了大诗人特有的气质。而且，这种体式，对汉赋“设为问答，以显己意”，颇具启发意义，或谓之汉赋之先声亦无不可。', poem_tags = '古文观止,楚辞,写人,品格,励志' WHERE poem_title = '卜居' AND poem_author = '屈原';
UPDATE edu_poem SET poem_translation = '在衙门里休息的时候，听见竹叶萧萧作响，仿佛听见了百姓啼饥号寒的怨声。\n我们虽然只是州县里的小官吏，但百姓的每一件小事都在牵动着我们的感情。', poem_notes = '署：衙门。\n年伯：古称同榜考取的人为同年，称“同年”的父辈为年伯。\n中丞：清代将巡抚称为中丞。\n衙斋：官衙中供官员居住和休息之所。\n萧萧：拟声词，形容草木摇动声。\n些小：很小，这里指官职卑微。\n吾曹：我们。\n关情：牵动情怀。', poem_tags = '题画,忧国忧民' WHERE poem_title = '潍县署中画竹呈年伯包大丞括 / 墨竹图题诗' AND poem_author = '郑燮';
UPDATE edu_poem SET poem_translation = '金粟轴的古筝发出优美的声音，那素手拨筝的美人坐在玉房前。\n想尽了办法为博取周郎的青睐，你看她故意地时时拨错了琴弦。', poem_notes = '听筝：弹奏筝曲。\n金粟：古也称桂为金粟，这里当是指弦轴之细而精美。\n柱：定弦调音的短轴。\n素手：指弹筝女子纤细洁白的手。\n玉房：指玉制的筝枕。房，筝上架弦的枕。\n周郎：指三国时吴将周瑜。他二十四岁为大将，时人称其为“周郎”。他精通音乐，听人奏错曲时，即使喝得半醉，也会转过头看一下奏者。当时人称：“曲有误，周郎顾。”\n拂弦：拨动琴弦。', poem_appreciation = '这首小诗轻捷洒脱，寥寥数语，就在读者面前展示了一幅线条流畅，动态鲜明的舞台人物速写图。\n\n　　“鸣筝金粟柱，素手玉房前。”诗的一二句写弹筝的女子纤手拨筝，正处于弹奏状态。筝是一种弦乐器。从唐诗中所描写的筝来看，筝是十三根弦，如：“花脸云鬟坐玉楼，十三弦里一时愁”（白居易《听崔七妓人筝》）。“大艑高船一百尺，清声促柱十三弦”（刘禹锡《夜闻商人船中筝》）。此诗是速写，当然必须抓住最能突出主题的部分。最引人注目的，首先便是弹筝者手中正在拨弄的乐器，特别是那绚丽华美，闪烁着点点金色光斑的弦柱。接着，诗人的目光又自然而然地落到那双正在琴弦上跳动的洁白如玉的纤手上，以及弹奏的环境。精洁雅致的琴房，自然别有一番情味。从画面上看，“金粟”、“素手”、“玉房”交相对比，色彩明丽而华贵，虽然是速写，却又施重彩，给人以极为强烈的印象。绘画毕竟是视觉的艺术，而鸣筝所成的乐曲则是作用于听觉的艺术。一、二两句诗所绘出的画面是绝妙的，读者从中瞥见了闪光的琴柱、白嫩的巧手、素雅的琴房，但却没有听到琴声。也许是精湛的工艺、绰约的风姿、高洁的环境使诗人过于全神贯注了。\n\n　　“欲得周郎顾，时时误拂弦。”诗人终于注意到弹奏出的乐曲本身。诗的前两句写女子正在弹筝，按此写法，接下去似乎应该描写女了的弹奏技艺，或者表现秦筝极富感染力的音乐形象，但出人意料的是，三、四句并不沿袭通常的写法，而是描写女子为了引起知音者的注意，故意错拨筝弦。相传三国时代的周瑜，别人奏曲有误，他就回头一看，此诗显然受到了这个故事的启发。“时时”说明这并非偶尔失手，也并非技艺低下，因为这失误明显地属于有意为之。有人将她的有意错弹理解为“妇人卖弄身份，巧于撩拨”（清·徐增《而庵说唐诗》），似乎弹筝女子的微妙心理，仅仅是一种邀宠之情；其实这种故意的失误是出于寻觅知音的苦心。她大约也是沦落风尘之人，对一般浪荡子弟，她的故意错弹饱含着对这班人的嘲弄和蔑视，但总会有一天，真正的知音——她的“周郎”会听出那曲中的深意，从而向她投去会心的一“顾”的。此处的“周郎”喻指听者，“欲得”就意味着当时坐在一旁的“周郎”没有看她。为什么不看她呢？大概听者已经完全陶醉在那美妙的筝声中了。本来这应该是演奏者最祈盼的效果，最欣慰的时刻，然而，这情景却不是这位女子此时最渴望的效果，因为她心中另有所思，思不在听者赏音，而在于一“顾”，怎么办呢？她灵机一动，故意不时地错拨一两个音，于是充满戏剧性的场景出现了：那不谐和的旋律，突然惊动了沉醉在音乐境界中的“周郎”，他下意识地眉头一皱，朝她一看，只见她非但没有丝毫“误拂”的遗憾和歉意，两眼反而闪烁出得意的眼神——原来是误非真误。为了所爱慕的人顾盼自己，便故意将弦拨错，弹筝女的可爱形象跃然纸上。这两句正面写出了弹者藏巧于拙，背面又暗示了听者以假当真，而这种巧与拙、假与真，又在那无言的一顾之中获得了奇妙的统一。它不仅说明弹者是高手，听者是知音，而且传神地表现出两者的心理神态，其意趣韵味无穷。', poem_tags = '唐诗三百首,音乐' WHERE poem_title = '听筝' AND poem_author = '李端';
UPDATE edu_poem SET poem_translation = '我自从成为有罪的人，住在这个州里，就常常恐惧不安。如有空闲时间，就慢慢地行走，无拘束地游玩。每日和那些同伴，上高山，入深林，走到曲折溪流的尽头。幽僻的泉水，奇异的山石，没有一处僻远的地方不曾到过。到了目的地就分开草而坐下，倒尽壶中酒，一醉方休。醉了就互相枕着睡觉，睡觉了就做梦。心里有向往的好境界，梦里也就有（在这种境界中获得的）相同的乐趣。睡醒了就起来，起来了就回家。我以为凡是这个州的山有奇特形状的，我都游过了；可是我还未曾知道西山的奇异特别。\n　　今年九月二十八日，我因坐在法华寺西亭，眺望西山，才指点着觉得它奇特。于是命令仆人渡过湘江，沿着染溪，砍伐荆棘，焚烧乱草，一直到山顶才停下。（我们随后）攀援登上山顶，随意坐下观赏，附近几个州的土地，就全在我们的坐席之下了。这几州的地势高低不平，高处是深山，低处是洼地，像蚁封，像洞穴，（看上去）只有尺寸之远，实际上有千里之遥。（这为千里之内的景物）聚集、紧缩、累积在眼下，没有什么能够隐藏。青山萦回，白水缭绕，外与天边相接。向四面望去都是一样的景象。（登上山顶）然后才知这座山的特别突出，与小土丘不一样。辽阔浩渺啊与天地间的大气合一而不能得到它的边际，悠然自得啊和大自然交游而不知它的尽期。（于是我们）拿起酒杯斟满酒，喝得东倒西歪地进入醉态，不知太阳下了山。灰暗的暮色，由远而至，直到看不见什么了还不想返回。（我只觉得）思想停止了，形体消散了，与自然界万物不知不觉地融为一体了。（游过西山）然后才知我以前不曾真正游赏过，真正的游赏是从这里开始的。所以我把这次西山之游写成文章以记载下来。这一年是元和四年。', poem_notes = '僇人：同“戮人”，受过刑辱的人，罪人。作者因永贞革新失败，被贬为永州司马，故自称僇人。僇，通“戮”，耻辱。\n是州：这个州，指永州。\n恒：常常。\n惴栗：恐惧不安。惴，恐惧。栗，发抖。此意为害怕政敌落井下石。\n其：如果，连词。\n隟：指空闲时间。\n施施而行：慢慢地行走。施施，慢步缓行的样子。\n漫漫而游：无拘无束地游。漫漫，不受拘束的样子。\n日：每日，时间名词作状语。\n其徒：那些同伴。徒，同一类的人，指爱好游览的人。\n穷：走到尽头。\n回溪：曲折溪流。\n幽泉：深僻的泉水。\n无远不到：没有一处僻远的地方不曾到过。\n披草：分开草。披，用手分开。\n倾壶：倒尽壶里的酒。倾，倒出来。\n更相：互相。\n意有所极，梦亦同趣：心里有向往的好境界，梦里也就有相同的乐趣。所极，所向往的境界。极，至，向往。\n觉：睡醒。\n以为：认为。\n异态：奇特的形状。\n未始：未曾。\n怪特：奇异特别。\n今年：指元和四年（809年）。\n法华：指法华寺，在原零陵县城东山之上。\n西亭：在法华寺内，为柳宗元所建，他经常在这里游赏山景，饮酒赋诗。\n始：才。\n指异之：指着它觉得它奇特。指，指点。异，觉得······奇特。\n湘江：应为潇水。潇水流经永州城西，至萍州才与湘江汇合。\n缘：沿着。\n染溪：又作“冉溪”，柳宗元又称为“愚溪”，是潇水的一条小支流。\n斫：砍伐。\n榛莽：指杂乱丛生的荆棘灌木。\n茅茷：指长得繁密杂乱的野草。茷，草叶茂盛。\n穷山之高而止：一直砍除、焚烧到山的最高处才停止。穷，尽，指把榛莽、茅茷砍除、焚烧尽。\n箕踞：像簸箕一样地蹲坐着。指坐时随意伸开两腿，像个簸箕，是一种不拘礼节的坐法。正规坐法，屁股要压在脚后跟上，两腿不能伸直。箕，簸箕。踞，蹲坐。\n遨：游赏。\n土壤：土地，指地域。\n衽席：坐垫、席子。\n其：代词，指上句“数州之土壤”。\n岈然：高山深邃的样子。岈，《广韵》：“岈，蛤岈，山深之状。”\n洼然：深谷低洼的样子。“岈然”承“高”，“洼然“承“下”。\n垤：蚁封，即蚂蚁洞边的小土堆。“若垤”承“岈然”，“若穴”承“洼然”。\n尺寸千里：（从西山顶上望去）只有尺寸之远，实际上有千里之遥。\n攒：聚集在一起。\n蹙：紧缩在一起。\n累积：堆积。\n莫得：没有什么能够。莫，没有什么，代词。得，能。\n遁隐：隐藏。\n萦青缭白：青山萦回，白水缭绕。作者为了突出“萦”“缭”景象，有意把主谓式变成动宾式。白，指山顶所见潇、湘二水。\n际：接近。\n四望如一：向四面望去都像一样的。\n是山：这座山，指西山。\n特立：特别突出。\n培塿：小土堆。\n悠悠乎：辽阔浩渺啊。\n灏气：同“浩气”，指天地间的大气。\n俱：在一起。\n涯：边际。\n洋洋乎：悠然自得啊。\n造物者：创造万物的天地，指大自然。\n引觞：拿起酒杯。\n满酌：斟满酒。\n颓然：东倒西歪地。颓，跌倒。\n就：接近，进入。\n苍然：灰暗的样子，这里是形容傍晚的天色。\n犹：还，仍然。\n心凝：思想停止了（不再想任何事情）。\n形释：形体消散了（忘掉了自己的存在）。\n万化：万物变化，指自然界万物。\n冥合：不知不觉地融合为一体。\n向：以前。\n未始游：不曾（真正）游赏过。\n于是：从这里。\n为之文：把这次西山之游写成文章。之，代指西山之游，是动词“为”的间接宾语。\n志：记载下来。\n是岁：这一年。\n元和：唐宪宗李纯年号。', poem_tags = '初中文言文,游记,写景,抒怀,怀才不遇' WHERE poem_title = '始得西山宴游记' AND poem_author = '柳宗元';
UPDATE edu_poem SET poem_translation = '古时候天上有十日同时出现，晒得庄稼枯死，民不聊生，一个名叫后羿的英雄，力大无穷，他同情受苦的百姓，拉开神弓，一气射下九个多太阳，并严令最后一个太阳按时起落，为民造福。后羿妻子名叫嫦娥。后羿除传艺狩猎外，终日和妻子在一起。不少志士慕名前来投师学艺，心术不正的蓬蒙也混了进来。\n\n　　一天，后羿到昆仑山访友求道，向王母求得一包不死药。据说，服下此药，能即刻升天成仙。然而，后羿舍不得撇下妻子，暂时把不死药交给嫦娥珍藏。嫦娥将药藏进梳妆台的百宝匣。三天后，后羿率众徒外出狩猎，心怀鬼胎的蓬蒙假装生病，没有外出。待后羿率众人走后不久，蓬蒙持剑闯入内宅后院，威逼嫦娥交出不死药。嫦娥知道自己不是蓬蒙的对手，危急之时她转身打开百宝匣，拿出不死药一口吞了下去。嫦娥吞下药，身子立时飘离地面、冲出窗口，向天上飞去。由于嫦娥牵挂着丈夫，便飞落到离人间最近的月亮上成了仙。\n\n　　傍晚，后羿回到家，侍女们哭诉了白天发生的事。后羿既惊又怒，抽剑去杀恶徒，蓬蒙早已逃走，后羿气得捶胸顿足，悲痛欲绝，仰望着夜空呼唤嫦娥，这时他发现，今天的月亮格外皎洁明亮，而且有个晃动的身影酷似嫦娥。后羿思念妻子，便派人到嫦娥喜爱的后花园里，摆上香案，放上嫦娥平时爱吃的蜜食鲜果，遥祭在月宫里的嫦娥。百姓们闻知嫦娥奔月成仙的消息后，纷纷在月下摆设香案，向善良的嫦娥祈求吉祥平安。从此，中秋节拜月的风俗在民间传开了。▲', poem_appreciation = '民间的传说又略有不同，大体谓嫦娥吃了丈夫从西王母那儿偷来的不死之药后，飞到月宫。但琼楼玉宇，高处不胜寒，所谓“嫦娥应悔偷灵药，碧海青天夜夜心”，正是她倍感孤寂之心情的写照。嫦娥向丈夫倾诉懊悔后，又说：“平时我没法下来，明天乃月圆之候，你用面粉作丸，团团如圆月形状，放在屋子的西北方向，然后再连续呼唤我的名字。到三更时分，我就可以回家来了。”翌日，照妻子的吩咐去做，届时嫦娥果由月中飞来，夫妻重圆，中秋节做月饼供嫦娥的风俗，也是由此形成。表现这一情节的嫦娥图，是世人渴望美好团圆，渴望幸福生活的情感流露。\n\n　　另一的“嫦娥奔月”版本是说嫦娥经受不住天上生活的诱惑，趁大羿外出狩猎，独自吞食了不死药，嫦娥由于背弃了丈夫，怕天庭诸神嘲笑，就投奔月亮女神常羲，想在月宫暂且安身。可是月宫空无一人，出奇的冷清，她在漫漫长夜中咀嚼孤独、悔恨的滋味，慢慢地变成了月精白蛤蟆，在月宫中终日被罚捣不死药，过着寂寞清苦的生活。李商隐曾有诗感叹嫦娥：“嫦娥应悔偷灵药，碧海青天夜夜心。”（《全上古文》辑《灵宪》则记载了“嫦娥化蟾”的故事：“嫦娥，羿妻也，窃王母不死药服之，奔月。将往，枚占于有黄。有黄占之：曰：‘吉，翩翩归妹，独将西行，逢天晦芒，毋惊毋恐，后且大昌。’嫦娥遂托身于月，是为蟾蜍。”）', poem_tags = '小学文言文,神话,故事' WHERE poem_title = '嫦娥奔月 / 嫦娥飞天' AND poem_author = '刘安 撰';
UPDATE edu_poem SET poem_tags = '婉约,感叹,人生,写景' WHERE poem_title = '采桑子·时光只解催人老' AND poem_author = '晏殊';
UPDATE edu_poem SET poem_translation = '唱完了一曲送别的歌儿，你便解开了那远别的行舟，\n两岸是青山，满山是红叶，水呀，在急急地东流。\n当暮色降临，我醒来了，才知道人已远去，\n而这时候，满天风雨，只有我一个人的身影独自离开了那西楼。', poem_notes = '劳歌：本指在劳劳亭送客时唱的歌，泛指送别歌。劳劳亭，在今南京市南面，李白诗有“天下伤心处，劳劳送客亭”。 \n水急流：暗指行舟远去，与“日暮酒醒”、“满天风雨”共同渲染无限别意。\n西楼即指送别的 谢亭 ，古代诗词中“南浦 ”、“西楼”都常指送别之处。', poem_appreciation = '第一句写友人乘舟离去。古代有唱歌送行的习俗。“劳歌”，原本指在劳劳亭（旧址在今南京市南面，也是一个著名的送别之地）送客时唱的歌，后来遂成为送别歌的代称。劳歌一曲，缆解舟行，从送别者眼中写出一种匆遽而无奈的情景气氛。\n\n　　第二句写友人乘舟出发后所见江上景色。时值深秋，两岸青山，霜林尽染，满目红叶丹枫，映衬着一江碧绿的秋水，显得色彩格外鲜艳。这明丽之景乍看似与别离之情不大协调，实际上前者恰恰是对后者的有力反衬。景色越美，越显出欢聚的可恋，别离的难堪，大好秋光反倒成为添愁增恨的因素了。江淹《别赋》说：“春草碧色，春水绿波，送君南浦，伤如之何！”借美好的春色反衬别离之悲，与此同一机杼。这也正是王夫之所揭示的：“以乐景写哀，以哀景写乐，一倍增其哀乐”（《姜斋诗话》）的艺术辩证法。\n\n　　这一句并没有直接写到友人的行舟。但通过“水急流”的刻画，舟行的迅疾读者可以想见，诗人目送行舟穿行于夹岸青山红叶的江面上的情景也生动地表现了出来。“急”字暗透出送行者“流水何太急”的心理状态，也使整个诗句所表现的意境带有一点逼仄忧伤、骚屑不宁的意味。这和诗人当时那种并不和谐安闲的心境是相一致的。\n\n　　诗的前后联之间有一个较长的时间间隔。朋友乘舟走远后，诗人并没有离开送别的谢亭，而是在原地小憩了一会。别前喝了点酒，微有醉意，朋友走后，心绪不佳，竟不胜酒力睡着了。一觉醒来，已是薄暮时分。天色变了，下起了雨，四望一片迷蒙。眼前的江面，两岸的青山红叶都已经笼罩在蒙蒙雨雾和沉沉暮色之中。而朋友的船，此刻更不知道随着急流驶到云山雾嶂之外的什么地方去了。暮色的苍茫黯淡，风雨的迷蒙凄清，酒醒后的朦胧，追忆别时情景所感到的怅惘空虚，使诗人此刻的情怀特别凄黯孤寂，感到无法承受这种环境气氛的包围，于是默默无言地独自从风雨笼罩的西楼上走了下来。（西楼即指送别的谢亭，古代诗词中“南浦”、“西楼”都常指送别之处。）\n\n　　第三句极写别后酒醒的怅惘空寂，第四句却并不接着直抒离愁，而是宕开写景。但由于这景物所特具的凄黯迷茫色彩与诗人当时的心境正相契合，因此读者完全可以从中感受到诗人的萧瑟凄清情怀。这样借景寓情，以景结情，比起直抒别情的难堪来，不但更富含蕴，更有感染力，而且使结尾别具一种不言而神伤的情韵。\n\n　　这首诗前后两联分别由两个不同时间和色调的场景组成。前联以青山红叶的明丽景色反衬别绪，后联以风雨凄其的黯淡景色正衬离情，笔法富于变化。而一、三两句分别点出舟发与人远，二、四两句纯用景物烘托渲染，则又异中有同，使全篇在变化中显出统一。', poem_tags = '送别,写景,抒情' WHERE poem_title = '谢亭送别' AND poem_author = '许浑';
UPDATE edu_poem SET poem_translation = '更深烛尽，烛光暗淡，画屏上的美人蕉模糊不辨。\n我昏昏欲睡，终于进入了梦乡，梦中是我久别的江南，正是青梅熟时，江南雨季，我独自在一艘船上，手握竹笛，和着船外那萧萧的夜雨尽情的吹奏，时而听见桥上驿亭边人语，操着那久违的乡音，诉说着难忘的故事。', poem_notes = '兰烬：因烛光似兰，故称。烬：物体燃烧后剩下的部分。\n暗红蕉：谓更深烛尽，画屏上的美人蕉模糊不辨。\n萧萧：同潇潇，形容雨声。\n驿：驿亭，古时公差或行人暂歇处。', poem_tags = '宋词三百首,婉约,写景' WHERE poem_title = '梦江南·兰烬落' AND poem_author = '皇甫松';
UPDATE edu_poem SET poem_translation = '萧条冷落的庭院，吹来了斜风细雨，一层层的院门紧紧关闭。春天的娇花即将开放，嫩柳也渐渐染绿。寒食节即将临近，又到了令人烦恼的时日，推敲险奇的韵律写成诗篇，从沉醉的酒意中清醒，还是闲散无聊的情绪，别有一番闲愁在心头。远飞的大雁尽行飞过，可心中的千言万语却难以托寄。\n连日来楼上春寒泠冽，帘幕垂得低低。玉栏杆我也懒得凭倚。锦被清冷，香火已消，我从短梦中醒来。这情景，使本来已经愁绪万千的我不能安卧。清晨的新露涓涓，新发出的桐叶一片湛绿，不知增添了多少游春的意绪。太阳已高，晨烟初放，再看看今天是不是又一个放晴的好天气。', poem_notes = '念奴娇：词牌名。又名“百字令”、“酹江月”、“大江东去”，双调一百字，前后阕各四仄韵。\n重门：多层的门。\n寒食：古代在清明节前两天的节日，焚火三天，只吃冷食，所以称寒食。\n险韵诗：以生僻而又难押之字为韵脚的诗。人觉其险峻而又能化艰僻为平妥，并无凑韵之弊。\n扶头酒：易醉之酒。\n征鸿：远飞的大雁\n玉阑干：栏杆的美称。慵：懒。\n烟敛：烟收、烟散的意思。烟，这里指像烟一样弥漫在空中的云气。\n晴未：天气晴了没有？未，同否，表示询问。', poem_appreciation = '这是一首怀人之作。它叙写了寒食节时对丈夫的怀念。开头三句写环境气候，景色萧条。柳、花而用“宠”、“娇”修饰，隐有妒春之意。接着写作诗填词醉酒，但闲愁却无法排解，已有万般怨尤。一句“征鸿过尽，万千心事难寄”，道出词人闲愁的原因：自己思念远行的丈夫，“万千心事”却无法捎寄。下阕开头三句，写出词人懒倚栏杆的愁闷情志，又写出她独宿春闺的种种感觉。“不许愁人不起”，写出作者已失去支撑生活的乐趣。“清露”两句转写新春的可爱，因之产生游春心思。结尾两句最为佳妙：天已放晴，却担心是否真晴，那种心有余悸的感觉，表现得极为凄迷。\n\n　　“萧条庭院”句写词人所处的环境，给人以寂寞幽深之感。庭院深深，寂寥无人，令人伤感；兼以细雨斜风，则景象之萧条，心境之凄苦，更觉怆然。一句“重门须闭”，写词人要把门儿关上，实际上她是想关闭心灵的窗户。\n\n　　“宠柳娇花寒食近，种种恼人天气”，这两句由斜风细雨，而想到宠柳娇花，既倾注了对美好事物的关心，也透露出惆怅自怜的感慨。“萧条庭院”句遣辞造句上，也显示了词人独创的才能。“宠柳娇花”是以和易安名句“绿肥红瘦”相比美，以其字少而意深，事熟而句生，足见锤炼功夫。其中可以引申出这么一些意思：春近寒食时节，垂柳繁花，犹得天宠，人来柳阴花下留连玩赏，花与柳便也如宠儿娇女，成为备受人们爱怜的角色。其中又以人之宠爱为主体奈何临近寒食清明这种多雨季节，游赏不成，只好深闭重门，而花受风雨摧残，也“恼人”之列。\n\n　　“险韵诗成，扶头酒醒，别是闲滋味”，由天气、花柳，渐次写到人物。风雨之夕，词人饮酒赋诗，借以排遣愁绪，然而诗成酒醒之后，无端愁绪重又袭上心头，“别是闲滋味”。一“闲”字，将伤春念远情怀，暗暗逗出，耐人寻味。“征鸿过尽”句点上片主旨，是虚写，实际上是用鸿雁传书的典故，暗寓赵明诚走后，词人欲寄相思，而信使难逢。“万千心事”，关它不住，遣它不成，寄也无方，最后还是把它深深地埋藏心底。\n\n　　“楼上几日春寒”句拓开一层，然仍承“万千心事”意脉。连日阴霾，春寒料峭，词人楼头深坐，帘垂四面。“帘垂四面”，是上阕“重门须闭”的进一步发展，既关上重门，又垂下帘幕，则小楼之幽暗可知；楼中人情怀之索寞，亦不言而喻了。“玉阑干慵倚”，刻画词人无聊意绪，而隐隐离情亦其中。征鸿过尽，音信无凭，纵使阑干倚遍，亦复何用。阑干慵倚，楼内寒深，枯坐更加愁闷，于是词人唯有恹恹入睡了。可是又感罗衾不耐春寒，渐渐从梦中惊醒。心事无人可告，唯有托诸梦境；而梦乡新到，又被寒冷唤回。其辗转难眠之意，凄然溢于言表。“不许愁人不起”，多少无可奈何的情绪，都包含这六字之中，词人为离情所折磨而痛苦不堪，又因明诚外出而实有此情，并非虚构。虚虚实实，感人至深。\n\n　　从“清露晨流”到篇终，词境为之一变。此前，词清调苦，婉曲深挚；此后，清空疏朗，低徊蕴藉。“清露晨流，新桐初引”写晨起时庭院中景色。从“重门须闭”，“帘垂四面”，至此帘卷门开，顿然令人感到一股盎然生意。日既高，烟既收，本是大好晴天，但词人还要“更看今日晴未”，说明春寒日久，阴晴不定，即便天已放晴，她还放心不下；暗中与前面所写的风雨春寒相呼应，脉络清晰。以问句作结，更有余味不尽的意味。\n\n　　全词从上片的天阴写到下片的天晴，从前的愁绪萦回到后面的轩朗，条理清晰，层次井然。词中感情的起伏和天气的变化相谐而生，全篇融情入景，浑然天成。是一首别具一格的闺怨词。', poem_tags = '宋词精选,婉约,寒食节,写景,怀人' WHERE poem_title = '念奴娇·春情' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '译文 五月盛开的榴花红似火，绿叶掩映着初结的小果。 静冷角落没有车马经过，任那谢了的花开了又落。', poem_appreciation = '这首诗开头两句点明时令，寥寥数语就勾画出了五月里石榴花开时的繁茂烂漫景象，尤其“照眼明”三字，生动传神。诗人即写了花，也写了看花人的愉快心情。后两句点明地点，这是生长在偏僻地方的石榴，没人去攀折损害他的花枝，殷红的石榴花繁多地落在青苔上，红青相衬，画面十分优美，使人觉得几多可爱和惋惜。其实诗人正是爱其无游人来赏，爱其满地“青苔”“绛英”，倘有人来赏，则车辙马蹄践踏得不堪了，还不如任其花开花落、果熟果烂，来得自然。委婉表达俩诗人孤独的心境。\n\n　　张十一是作者的一位好朋友,作者做此诗时张十一和他都被贬谪,诗人有感作诗前两句写景,后两句抒情。作者并不直接来写景，而是通过人的感觉，侧面烘托出榴花的绚烂多姿。但花开的再美又能如何，还不是寂寞无声落，诗人叹息花开无人来赏，亦即暗喻朋友满腹才华，却被统治者贬谪于穷乡僻壤，无法施展，“颠倒”二字更是有力批判了统治者的不识人才以及诗人和作者都怀才不遇的愤懑。', poem_tags = '咏物,抒情,怀才不遇' WHERE poem_title = '题张十一旅舍三咏榴花 / 题榴花' AND poem_author = '韩愈';
UPDATE edu_poem SET poem_translation = '银河纵横穿流、星斗横竖移动。\n银河与北斗星都是在无知无情的空自流转，又怎知我心中在想念一个人？\n空房之内，一盎孤灯半明不灭，不管天寒地冻，依然踏起织机，织起布来。\n泪流不止可又能向谁诉说呢？只能听着鸡鸣声发出一声声的叹息。', poem_notes = '河汉：这里指银河。', poem_appreciation = '《夜夜曲》，乐府杂曲歌辞的一种，它的创始人便是沈约。《乐府解题》云：“《夜夜曲》，伤独处也。”沈作有二首，皆写同样的主题。此为第一首，写空房独处的凄凉况味尤为具体而细致。\n\n　　此诗共八句，可分前后两段，段各四句。每段开头二句均用对偶，结尾二句以白描手法抒写思妇惆怅自怜的内心感情。从前段到后段，思妇的感情有发展，有变化，直至结尾，形成一个高潮。\n\n　　诗歌的开头两句借银河和北斗方位的变化来暗示时间的流逝。“河汉纵且横，北斗横复直”，写思妇长夜不眠，观看天空景象。诗人在这两句诗中交错使用了“纵”、“横”、“直”三个动词，忽纵忽横忽直，使人仿佛看到银河纵横穿流、星斗横竖移动的情景。诗中虽未直截写人，而人物的神情自可令人想见。古诗中用星辰位置的变易反衬思妇感情的愁苦，例子甚多。如《古诗十九首》云：“明月皎皎光，促织鸣东壁。玉衡指孟冬，众星何历历！”又云：“迢迢牵牛星，皎皎河汉女，纤纤擢素手，札札弄机杼。”前人皆以为本之于《诗经·小雅·大东》，如《文选》李善注“河汉女”云：“《毛诗》曰：‘维天有汉，监亦有光。跂彼织女，终日七襄。虽则七襄，不成报章。’毛苌曰：‘河汉，天河也。’”观沈约此诗，当系近承《古诗十九首》，远绍《诗经》之《大东》，当然在具体描写上也有所不同。它开头二句说银河由纵到横，北斗由横到直，通过写景显示了时间的迁延。用一句通俗的话说，便是斗转星移，时间已过了很长。在此漫漫长夜，思妇耿耿不寐，心中必有所想，于是诗人借她的口吻说道：“星汉空如此，宁知心有忆？”星汉本为无知无情之客体，怨它何来？这种写法便是古人所常说的“无理而妙”。仿佛在说：银河啊，你空自流转；北斗星啊，你徒然横斜，你们怎知我心中在想念一个人？接下去二句写思妇因星汉移动、时光流逝而起的惆怅心情。“星汉”句总括上文又作一顿挫，着一“空”字，似乎把前面铺排的两句一下子推倒，令人感到不可思议。“宁知”句把思妇胸中的一股怨气，喷薄而出，着一“宁”字，与前面的“空”字紧相呼应，把人物的感情引向内心深处。二句全系脱口而出，声情毕肖，确有如闻其声，如见其人的效果。\n\n　　如果说前半段以天空之景烘托思妇孤栖之苦，那么后半段则转而以室内之景映衬人物独处无聊的心态。诗人的笔锋由夜空转入闺房。空房之内，一盎孤灯，半明不灭，那暗淡的灯光，正象征着思妇的情怀。她孤独难耐，于是不管天寒地冻，踏起织机，织起布来。在这里，诗人没有照搬《诗经》与古诗，光写天上织女，而是将天上移到人间，写思妇亲理寒机。因此使人读来，更富有现实感。从对偶方面讲，这一联比前一联更为精当。因为前一联并列两件性质相近的事物，其弊如后人评价近体诗时所说的“合掌”。而这一联则意不相重，且层层推进，前句说灯不明，是在深夜；后句说晓犹织，则已到天亮了。从深夜到天明，思妇由独守孤灯到亲理寒机，层次鲜明，动作清晰，恰到好处地表现了她的孤独之感。\n\n　　结尾二句，承上文而来。思妇彻夜未眠，所忆之人缥缈无踪，眼望孤灯，手理寒机，心中分外凄苦，于是她情不自禁地哭了。尽管泪流不已，也没有人同情她，她不能向人诉说单身独处的苦闷。她只有哀哀自伤，徒然叹息。结句“鸡鸣”二字，紧扣上句的“晓”字，而“徒”字又与前段的“空”字遥相照映。此刻女主人翁的孤独之感已达到了顶点，天上的星汉也好，自己的忆念与叹息也好，一切的一切，都是空幻而徒然的。她只有默默地流泪，独自咀嚼着悲伤。听到鸡叫的声音，她不由发出长长的叹息。', poem_tags = '古诗三百首,乐府,妇女,孤独,思念,悲愁' WHERE poem_title = '夜夜曲' AND poem_author = '沈约';
UPDATE edu_poem SET poem_translation = '明月如此皎洁光亮，照亮了我罗制的床帏。\n夜里忧愁得无法入睡，披衣而起在空屋内徘徊。\n客居在外虽然有趣，但是怎比得上早日回家呢。\n一个人出门忧愁彷徨，满心愁苦应该告诉谁呢？\n伸颈远望还是只能回到房间，眼泪沾湿了衣裳。', poem_notes = '皎：本义是洁白明亮。此处用引申义，为光照耀的意思。\n罗床帏：指用罗制成的床帐。\n寐：入睡。\n揽衣：犹言“披衣”，“穿衣”。揽，取。\n客：这里指诗人自己。\n旋归；回归，归家。旋，转。\n彷徨：徘徊的意思。\n告：把话说给别人听。\n引领：伸着脖子远望。\n裳（cháng）衣：一作“衣裳”。裳，下衣，指古人穿的遮蔽下体的衣裙，男女都穿。', poem_appreciation = '对这首诗的主题主要有两种解读：一说此诗刻画了一个久客异乡、愁思辗转、夜不能寐的游子形象。一说此诗塑造了一个独守空闺、愁思难寐、徘徊辗转的闺中女子形象。\n\n　　按第一种说法，此诗为游子思乡之作。游子的乡愁是由皎皎明月引起的。更深人静，那千里与共的明月，最易勾引起羁旅人的思绪。谢庄《月赋》曰：“隔千里兮共明月。”李白《静夜思》曰：“床前明月光，疑是地上霜。举头望明月，低头思故乡。”对于这首无名氏古诗中的主人公来说，同样是这种情绪。“明月何皎皎，照我罗床帏。”当他开始看到明月如此皎洁时，也许是兴奋的赞赏的。银色的清辉透过轻薄透光的罗帐，照着这位拥衾而卧的人。可是，夜已深沉，他辗转反侧，尚未入眠。不是过于耀眼的月光打扰他的睡眠，而是“忧愁不能寐”。他怎么也睡不着，便索性“揽衣”而“起”，在室内“徘徊”起来。游子“看月”“失眠”“揽衣”“起床”“徘徊”这一连串的动作，说明他醒着的时间长，实在无法入睡；同时说明他心中忧愁很深。尤其是那起徘徊”的情态，深刻地揭示了他内心痛苦的剧烈。\n\n　　诗写到这里，写出了“忧愁不能寐”的种种情状，接着写“忧愁”的原因。“客行虽云乐，不如早旋归。”这是全诗的关键语，画龙点睛，点明主题。这两句虽是直说缘由，但语有余意，耐人寻味。“客行”既有“乐”，为何又说“不如早旋归”呢？实际上他乡作客，何乐而言。正如汉乐府相如歌辞《饮马长城窟行》所说：“枯桑知天风，海水知天寒。入门各自媚，谁与相为言。”而异乡游子欲归不归的情状和他们所处的客观现实是密切联系着的。即如此诗的作者，大概是东汉时一个无名文人，在他那个时代，往往为营求功名而旅食京师，却又仕途阻滞，进退两难。这两句诗正刻划出他想归而不得归无可奈何的心情，是十分真切的。\n\n　　作者点出这种欲归不得的处境后，下面四句又像开头四句那样，通过主人公的动作进一步表现他心灵最深层的痛苦。前面写到“揽衣起徘徊”，尚是在室内走走，但感到还是无法排遣心中的烦闷，于是他走出户外了。然而，“出户彷徨”，半夜三更，他像梦游似的，独自在月下彷徨，更有一阵孤独感袭上心头。“愁思当告谁？”正是这种“独”、这种“彷徨”的具体感受了。古乐府《悲歌》云：“悲歌可以当泣，远望可以当归。”于是诗人情不自禁地向千里之外的故乡云树引领而望，可是又不能获得“可以当归”的效果，反而引起了更大的失望。他实在受不了这种感情上的折磨了，他又回到室内去。从“出户”到“入房”，这一出一入，把游子心中翻腾的愁情推向顶点，以至再也禁不住“泪下沾裳衣”了。全诗共十句，除了“客行”二句外，所描写的都是极其具体的行动，而这些行动是一个紧接着一个，是一层深似一层，细致地刻画了游子欲归不得的心理状态，手法是很高明的。\n\n　　按第二种说法，此诗抒发女子闺中望夫之慨。闺中女子的愁思由明月引起。这里的“罗床帏”指闺房。夜深人静，孤寂难耐的时候，月光皎洁照耀着床帐。原本“忧愁不能寐”，月光的照临更勾起若许的情思，只好披衣而起，徘徊于闺室。开头两联，就形象生动地把一个辗转徘徊的孤闺女子亮相于明月清辉之中。“客行虽云乐，不如早旋归”，是女子心头对“客行”在外游子的劝说，有抱怨，也有期许。这一联是对全诗主题的揭示。但说归说，怨归怨，在此时此刻他不能听见，也不能回来。这满腹的愁思无人可以告诉。无可奈何，只好孤独地到院子里去流连彷徨，去对月倾诉。但月亮照我影，却难慰我情，抬头仰望愈久，而“忧愁”愈添，不得不回到房屋里去，止不住的泪水打湿了衣裳。这里诗人以泪写愁，以泪写苦，以泪写思念，“泪下沾裳衣”不但说泪多，而且把情感推向高峰。后两联如泣如诉，感人至深。', poem_tags = '古诗三百首,古诗十九首,月亮,思归' WHERE poem_title = '明月何皎皎' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '天命玄鸟降人间，简狄生契商祖先，住在殷地广又宽。当时天帝命成汤，征伐天下安四边。\n昭告部落各首领，九州土地商占遍。商朝先王后继前，承受天命不怠慢，裔孙武丁最称贤。武丁确是好裔孙，成汤遗业能承担。\n龙旗大车有十乘，贡献粮食常载满。国土疆域上千里，百姓居处得平安。\n开拓疆域达四海，四夷小国来朝拜，车水马龙各争先。景山外围黄河绕，殷受天命人称善，百样福禄都占全。', poem_notes = '玄鸟：黑色燕子。传说有娀氏之女简狄吞燕卵而怀孕生契，契建商。\n商：指商的始祖契。\n宅：居住。芒芒：同“茫茫”，广大的样子。\n古：从前。帝：天帝，上帝。武汤：即成汤，汤号曰武。\n正（zhēng）：同“征”。又，修正疆域。\n方：遍，普。后：上古称君主，此指各部落的酋长首领（诸侯）。\n奄：拥有。九有：九州。传说禹划天下为九州。《尔雅·释地》：“两河间曰冀州，河南曰豫州，河西曰雍州，汉南曰荆州，江南曰扬州，济南曰兖州，济东曰徐州，燕曰幽州，齐曰营州。”有，“域”的借字，疆域。\n先后：指先君，先王。\n命：天命。殆：通“怠”，懈怠。\n武丁：即殷高宗，汤的后代。\n武王：即武汤，成汤。胜：胜任。\n旂（qí）：古时一种旗帜，上画龙形，竿头系铜铃。乘（shèng）：四马一车为乘。\n糦（xī）：同“饎”，酒食。宾语前置，“大糦”作“承”的前置宾语。承，捧，进献。\n邦畿（jī）：封畿，疆界。\n止：停留，居住。\n肇域四海：始拥有四海之疆域。四海，《尔雅》以“九夷、八狄、七戎、六蛮”为“四海”。或释“肇”为“兆”，兆域，即疆域。开辟疆域以至于四海。\n来假（gé）：来朝。假，通“格”，到达。\n祁祁：纷杂众多之貌。\n景：景山，在今河南商丘，古称亳，为商之都城所在。景，广大。员，幅员。\n咸宜：谓人们都认为适宜。\n百禄：多福。何（hè）：通“荷”，承受，承担。', poem_appreciation = '这是殷商后代宋国祭祀其祖先武丁的乐歌。《毛诗序》云：“《玄鸟》，祀高宗也。”郑笺云：“祀当为祫。祫，合也。高宗，殷王武丁，中宗玄孙之孙也。有雊雉之异，又惧而修德，殷道复兴，故亦表显之，号为高宗云。崩而始合祭于契之庙，歌是诗焉。”郑玄的意思是《毛序》所说的“祀”是合祀，而他所讲到的“雊雉之异”，据《史记·殷本纪》记载，是这么一回事：“帝武丁祭成汤，明日有飞雉登鼎耳而呴(雊)。武丁惧。祖己曰：‘王勿忧，先修政事。’” 据今人的研究，商是以鸟为图腾的民族，“雊雉之异”的传说与“天命玄鸟，降而生商”的神话不无相关。而“天命玄鸟，降而生商”则是关于商的起源的最珍贵的早期文献资料。传说中商的祖先契是其母有娀氏之女吞下燕卵之后生下的。《史记·殷本纪》：“殷契，母曰简狄，有娀氏之女。……三人行浴，见玄鸟堕其卵，简狄取吞之，因孕生契。”上古典籍中对此传说有相当多的记载。《楚辞·离骚》：“望瑶台之偃蹇兮，见有娀之佚女。……凤鸟既受诒兮，恐高辛之先我。”《楚辞·天问》：“简狄在台，喾何宜？玄鸟致诒，如何喜？”《吕氏春秋·音初》：“有娀氏有二佚女，为之成之台，饮食必以鼓。帝令燕往视之，鸣若嗌嗌。二女爱而争搏之，覆以玉筐。少选，发而视之，燕遗二卵北飞，遂不反。”此外如《太平御览》卷八二引《尚书中候》，《史记·三代世表》褚少孙补引《诗含神雾》等纬书也记录了这同一传说。更有意思的是：传世的晚商青铜器《玄鸟妇壶》上有“玄鸟妇”三字合书的铭文，其含义表明作此壶者系以玄鸟为图腾的妇人。玄鸟是商部族的崇拜图腾，“天命玄鸟”的传说正是原始商部族的起源神话。从文化人类学角度审视这一神话，可发现它作为一种原型，有其典型意义。有关鸟卵生子的传说长期流传于东北地区，如《论衡·吉验》：“北夷橐离国王侍婢有娠。王欲杀之。婢对曰：‘有气大如鸡子，从天而下，我故有娠。”’《清太祖武皇帝实录》：“长白山，……有神鹊衔一朱果置佛古伦衣上，……其果入腹，既感而成孕。”高丽李奎极《李相国文集》中亦有鸟卵生子的传说，与《魏书·高句丽传》所记之事略同。而据傅斯年考证，商部族正是发迹于东北渤海地区。\n\n　　由此可见，所谓的“雊雉之异”是为了显示高宗武丁的中兴而造出的神话，它正基筑于商民族的玄鸟图腾信仰。商至盘庚而迁殷，发展兴旺，政局稳定。盘庚死后，传位二弟小辛，小辛不幸三年而亡，又传位三弟小乙，小乙即位十年而亡。其时殷道又衰，小乙之子武丁立，用傅说为相，伐鬼方、大彭、豕韦，修政立德，终使国家大治。诗云：“龙旂十乘，大糦是乘。”郑玄笺曰：“交龙为旗，高宗之孙子有武功，有王德于天下者，无所不胜服。乃有诸侯建龙旗者十乘，奉承黍稷而进之者，亦言得诸侯之欢心。十乘者，由二王后，八州之大国与？”中原部族建立联盟后，统以龙为标志，“龙以建旗”。商族在东北兴起后，南下黄河流域，进而控制诸夏。高宗武丁时，中原各部族以车载稻米进贡。诗云：“四海来假，来假祁祁”，则不但是中原诸夏部族，即使是氐、羌等四边民族也纷纷进贡朝见。武丁功业之隆，于此可见。', poem_tags = '诗经,祭祀,颂歌' WHERE poem_title = '商颂·玄鸟' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '读到一本好书，心中十分高兴，可惜没多久就读完了；与知心朋友亲切交谈，心中十分高兴，可惜朋友不能常常到来。\n世界上的事往往是这样美中不足与意愿相乖，人生百年，有多少次能够欢笑开怀？', poem_notes = '快意：称心满意。\n可人：合心意的人，品行可取的人。\n好怀：好兴致。', poem_tags = '感叹,人生,哲理' WHERE poem_title = '绝句·书当快意读易尽' AND poem_author = '陈师道';
UPDATE edu_poem SET poem_translation = '晋平公和臣子们在一起喝酒。酒喝的正高兴时，他就得意地说：“没有谁比做国君更快乐的了！只有他的话没有谁敢违背！”师旷正在旁边陪坐，听了这话，便拿起琴朝他撞去。晋平公连忙收起衣襟躲让。琴在墙壁上撞坏了。晋平公说：“乐师， 您撞谁呀?”师旷故意答道：“刚才有个小人在胡说八道，因此我气得要撞他。”晋平公说：“说话的是我呀。”师旷说：“哎！这不是为人君主的人应说的话啊！”左右臣子认为师旷犯上，都要求惩办他。晋平公说：“放了他吧，我要把这件事（或“师旷讲的话”）当作一个警告。”', poem_notes = '选自《韩非子》。\n莫乐为人君——没有比做人君再快乐的了。\n莫之违——没有人敢违背他\n师旷——名旷，字子野，是春秋后期晋国宫廷中的盲乐师。\n师旷侍坐于前——师旷陪坐在前面\n援——执持，拿。\n衽——衣襟、长袍。\n太师——师旷。谁撞，即撞谁。\n言于侧——于侧言。\n哑——表示不以为然的惊叹声。\n除——清除，去掉。除之：除掉他\n故——所以\n被——通“披”，披着。\n师旷——盲人乐师。\n是非君人者——这不是国君\n谁撞——撞谁\n释——放\n酣——（喝得）正高兴的时候\n喟然————叹息的样子\n\n倒装句\n太师谁撞：应为“太师撞谁”\n惟其言而莫之违：应为“惟其言而莫违之”', poem_tags = '小学文言文,故事,励志,哲理' WHERE poem_title = '师旷撞晋平公' AND poem_author = '韩非';
UPDATE edu_poem SET poem_translation = '从前有一个人，一开始把粮食存放到了瓮中。一头骆驼偷吃了瓮中的粮食，结果头被卡在里面出不来了。因为骆驼的头出不来，这个人就为此事发愁。有一个老人来到见了就说：“你不要发愁，我教你一个能让骆驼头出来的方法。你把骆驼的头斩断，自然就能够出来了。”这个人听了随即就采纳了老人的意见，用刀把骆驼头斩断了。已经杀死了骆驼，进而又要把瓮打破才能取出粮食。这样行事的人，被后人所耻笑。', poem_notes = '曩：从前，以往。\n先：先前。\n瓮(wèng)：一种口小腹大的盛器。\n食：吃。\n首：头。\n既：已经。\n以为忧：为此事而忧虑。\n语：告诉。\n即：就。\n依：依照，按照。\n其：那个。\n用：采纳。\n得：表示情况允许，有“能够”，“可以”的意思。\n之：第三人称代词，他、她、它（们）。这里指那个既杀死了骆驼，又打破了瓮的人。\n汝：你。\n复：又。\n老父：老人。\n患：担忧。', poem_appreciation = '虽然在通常情况下，集思广益，从善如流，往往能在做事时有事半功倍，锦上添花的效果．但如果不经思考就接受别人的意见，连旁人的“馊主意”也言听计从，结果只能像那个笨人一样赔了骆驼又折了瓮。\n\n　　世上不可能有那种“既杀驼，而复破瓮”的傻子，但思想方法呆板，机械的人是不少的。\n\n　　以譬喻的手段，来使人们获得无上的智慧，这是《百喻经》的根本所在。譬喻的形式就好像用来裹药的树叶，当人有病时，就取出药来用，而自然地将裹药用的叶子扔掉。所以有智慧的人读了这部书，应当抛开譬喻故事的形式，抓住其中所蕴含的意义。这个故事就启示我们：凡事要认真思考，仔细研究，不能因小失大，更不能盲目听从他人的建议。', poem_tags = '小学文言文,寓理,故事' WHERE poem_title = '杀驼破瓮' AND poem_author = '伽腽肭';
UPDATE edu_poem SET poem_translation = '远远地看见牧童骑着牛缓缓地在前村走过，轻风隔着田垄送来阵阵牧笛声。\n长安城内那些追逐名利的人，用尽心机也不如你这样清闲自在。', poem_notes = '1、陇（lǒng）：通“垄”，田垄。\n2、长安：唐代京城。\n3、机关用尽：用尽心机。', poem_appreciation = '这是一首饶有理趣，借题发挥的警世诗。前两句描写牧童自在自得的神情，悠然牛背上，短笛信口吹，宛然如画。牧童骑着牛儿，从前村慢慢走过；吹着笛儿，笛声在田间随风飘悠。“骑牛”与“吹笛”，生动地描摹出牧童洒脱的形象、悠闲的心情：同时，诗人把牧童放在“村”与“岸”的背景上，使画面境界外阔，显得“野”味浓郁。\n\n　　后两句即事论理，拉出逐利争名、机关算尽的“长安名利客”与悠然自得的牧童相比。有多少在官场上争名逐利的庸人，费尽心机，其实不如牧童自在快乐啊！在一贬一褒之中，表露出作者清高自赏、不与俗流合污的心态，同时也在赞美牧童。\n\n　　该《牧童诗》与《红楼梦》之“机关算尽太聪明，反误了卿卿性命。”有异曲同工之妙，诗中悠闲自得，吹笛牛背，早出晚归，不愁食衣的“田园牧歌式”的生活，自然既飘逸而又理想，可惜在黑暗的制度下，只不过是文人学士们的“空想”之一。', poem_tags = '古诗三百首,赞颂,儿童' WHERE poem_title = '牧童诗' AND poem_author = '黄庭坚';
UPDATE edu_poem SET poem_translation = '村头小路边桑树柔软的枝条，刚刚绽放嫩芽。东面邻居家养的蚕种已经有一些蜕变成了蚕儿。一脉平缓山岗上，细草间小黄牛犊儿在鸣叫，落日斜照枯寒的树林，树枝间休息着一只只乌鸦。\n山有的远些有的近些，路有的横向有的斜向，青布酒旗那边有家小酒铺，可以打一些酒来。城里的桃花李花把风雨当做折磨，一派愁苦，最明媚的春色，正在溪头一片荠菜花中盛开。', poem_notes = '鹧鸪天：小令词调， 双片55字， 上片四句三平韵， 下片五句三平韵。唐人郑嵎诗“春游鸡鹿塞，家在鹧鸪天”，调名取于此。又名《思佳客》、《思越人》、《剪朝霞》、《骊歌一叠》。\n些：句末语助词。\n平冈：平坦的小山坡。\n暮鸦：见王安石《题舫子》诗：“爱此江边好,留连至日斜。眠分黄犊草，坐占白鸥沙。”这里隐括其句。\n青旗：卖酒的招牌。\n荠菜：二年生草本植物,花白色，茎叶嫩时可以吃。', poem_appreciation = '全词从不同视角描绘乡村春意盎然的景象，看上去好象是随意下笔，但细细体会，情味盎然，意蕴深厚。上阕头二句在描写桑树抽芽、蚕卵开始孵化时，用了一个“破”字非常传神地写出了桑叶在春风的催动下，逐渐萌发、膨胀，终于撑破了原来包在桑芽上的透明薄膜。“破”字不仅有动态，让人感到桑芽萌发的力量和速度。第三句“平岗细草鸣黄犊 ”“平岗细草”和“黄犊”是相互关联的，黄犊在牛栏里关了一冬，当放牧在平坡上时被乍见春草，欢快无比 。“鸣”虽写声音，但可以让人想见黄犊吃草时的悠闲，神态。第四句中的“斜日”、“寒林”、“暮鸦”按说会构成一片衰飒景象，但由于用了一个动词“点”字，却使情调发生了变化。“点”状乌鸦或飞或栖，有如一团墨点，这是确切的写实，早春的寒林没有树叶，所以黑色的乌鸦，在林中历历可见。作者却是在欣赏一幅天然的图画。\n\n　　从表面看，这首词的下半片好象仍然接着上半片在写景。这里下半片的写景是不同于上半片的，是有波澜的。首先它是推远一层看，由平冈看到远山，看到横斜的路所通到的酒店，还由乡村推远到城里。“青旗沽酒有人家”一句看来很平常，全词都在写自然风景，只有这句才写到人的活动，这样就打破了一味写景的单调。这是写景诗的一个诀窍。尽管是在写景，却不能一味渲染景致，必须加入一些人的情调，有人的活动，诗才显得有生气。\n\n　　“城中桃李愁风雨，春在溪头荠菜花”两句是全词的画龙点睛，它又象是在写景，又象是在发议论。这两句决定了全词的情调。如果单从头三句及“青旗沽酒”句看，这首词的情调是很愉快的。但词人是一位忠义之士，处在南宋偏安杭州，北方金兵掳去了宋徽宗、宋钦宗二帝，还在节节进逼的情势之下，他想图恢复，而南宋朝中大半是些昏愦无能，苟且偷安者，叫他一筹莫展，心里十分痛恨。就是这种心情成了他的许多词的基本情调。这首词实际上是愁苦之音。“斜日寒林点暮鸦”句已透露了一点消息，到了“桃李愁风雨”句便把大好锦绣河山竟然如此残缺不全的感慨完全表现出来了。从前诗人词人每逢有难言之隐，总是假托自然界事物，把它象征地说出来。辛词凡是说到风雨打落春花的地方，大都是暗射南宋被金兵进逼的局面。这里的“城中桃李愁风雨”也是慨叹南宋受金兵的欺侮。\n\n　　词中用了反衬手法，反衬就是欲擒先纵。从愉快的景象说起，转到悲苦的心境，这样互相衬托，悲苦的就更显得悲苦。前人谈辛词往往用“沉痛”两字，他的沉痛就在这种地方。但是沉痛不等于失望，“春在溪头荠菜花”句可以见出词人对南宋偏安局面还寄托很大的希望。这希望是由词人在村中看到的劳动人民从事农桑的景象所引起的。上句说明“诗可以怨”（诉苦），下句说明“诗可以兴”（鼓舞兴起）。\n\n　　词人发现和捕捉农村中最平常也最典型的风光景物和生活情境，运用清新明快的笔调、素净淡雅的色彩，描绘出一幅幅意象鲜活、层次清晰、生机盎然的图画， 给人以丰富的美感享受，进而触发出心弦的共鸣。', poem_tags = '早春,乡村,忧国忧民' WHERE poem_title = '鹧鸪天·陌上柔桑破嫩芽' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '江宁的龙蟠里，苏州的邓尉山，杭州的西溪，都出产梅。有人说：“梅凭着弯曲的姿态被认为是美丽的，笔直了就没有风姿；凭着枝干倾斜被认为是美丽的，端正了就没有景致；凭着枝叶稀疏被认为是美丽的，茂密了就没有姿态。”本来就如此。（对于）这，文人画家在心里明白它的意思，却不便公开宣告，大声疾呼，用（这种标准）来约束天下的梅。又不能够来让天下种梅人砍掉笔直的枝干、除去繁密的枝条、锄掉端正的枝条，把枝干摧折、使梅花呈病态作为职业来谋求钱财。梅的枝干的倾斜、枝叶的疏朗、枝干的弯曲，又不是那些忙于赚钱的人能够凭借他们的智慧、力量做得到的。有的人把文人画士这隐藏在心中的特别嗜好明白地告诉卖梅的人，（使他们）砍掉端正的（枝干），培养倾斜的侧枝，除去繁密的（枝干），摧折它的嫩枝，锄掉笔直的（枝干），阻碍它的生机，用这样的方法来谋求大价钱，于是江苏、浙江的梅都成病态了。文人画家造成的祸害严重到这个地步啊！\n\n　　我买了三百盆梅，都是病梅，没有一盆完好的。我已经为它们流了好几天泪之后，于是发誓要治疗它们：我放开它们，使它们顺其自然生长，毁掉那些盆子，把梅全部种在地里，解开捆绑它们棕绳的束缚；把五年作为期限，一定使它们恢复和使它们完好。我本来不是文人画士，心甘情愿受到辱骂，开设一个病梅馆来贮存它们。\n\n　　唉！怎么能让我有多一些空闲时间，又有多一些空闲的田地，来广泛贮存南京、杭州、苏州的病态的梅树，竭尽我毕生的时间来治疗病梅呢！', poem_notes = '江宁：旧江宁府所在地，在今江苏南京。\n龙蟠：龙蟠里，在今南京清凉山下。\n邓尉：山名。在今江苏苏州西南。\n西溪：地名。\n欹（qī）：倾斜 。\n固也：本来如此。固，本来。\n明诏大号：公开宣告，大声疾呼。明，公开。诏，告诉，一般指上告下。号，疾呼，喊叫。\n绳：名作动，约束 。\n斫：砍削。\n直：笔直的枝干。\n夭梅病梅：摧折梅，把它弄成病态。夭：使……摧折（使……弯曲）。病，使……成为病态。\n蠢蠢：无知的样子。\n智力：智慧和力量。\n孤癖：特殊的嗜好。\n隐：隐衷，隐藏心中特别的嗜好 。\n鬻（yù）：卖。\n旁条：旁逸斜出的枝条。\n稚枝：嫩枝。\n重价：高价。\n遏（è）：遏制。\n泣：为……哭泣。\n纵：放纵。\n顺：使……顺其自然。\n悉：全。\n棕缚：棕绳的束缚。\n以……为：把……当做。\n复：使……恢复 。\n全：使……得以保全。\n诟厉：讥评，辱骂。厉，病。\n安得：怎么能够。\n暇：空闲。\n穷：穷尽。', poem_tags = '高中文言文,哲理,咏物,寓人' WHERE poem_title = '病梅馆记' AND poem_author = '龚自珍';
UPDATE edu_poem SET poem_tags = '行军,艰难,同情' WHERE poem_title = '苦寒行' AND poem_author = '曹操';
UPDATE edu_poem SET poem_translation = '手里玩赏着奇丽的彩石，面对着潺潺的溪水观赏。绕着寺旁那弯弯的小径，探寻着绚丽多姿的野山花。\n百灵声声脆，婉转歌唱。泉水咚咚响，脉脉流淌。', poem_notes = '遗爱寺：寺名，位于庐山香炉峰下。\n弄：在手里玩。\n鸟语：鸟鸣声。', poem_tags = '抒情,写景,早教古诗100首' WHERE poem_title = '遗爱寺' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '昨夜的春风吹开了露井边的桃花，未央宫前的明月高高地挂在天上。\n平阳公主家的歌女新受武帝宠幸，见帘外略有春寒皇上特把锦袍赐给她。', poem_notes = '春宫曲：一作“殿前曲”。\n露井：指没有井亭覆盖的井。\n未央：即未央宫，汉宫殿名，汉高祖刘邦所建。也指唐宫。\n平阳歌舞：平阳公主家中的歌女。新承：一作“承新”。', poem_appreciation = '前两句中，昨夜风开露井桃”点明时令，切题中“春”字；露井旁边的桃树，在春风的吹拂下，绽开了花朵。“未央前殿月轮高”点明地点，切题中“宫”字。未央宫的前殿，月轮高照，银光铺洒。字面上看来，两句诗只是淡淡地描绘了一幅春意融融、安详和穆的自然景象，触物起兴，暗喻歌女承宠，有如桃花沾沐雨露之恩而开放，是兴而兼比的写法。月亮，对于人们来说，本无远近、高低之分，这里偏说“未央前殿月轮高”，因为那里是新人受宠的地方，是这个失宠者心向往之而不得近的所在，所以她只觉得月是彼处高，尽管无理，但却有情。\n\n　　后两句写新人的由来和她受宠的具体情状。卫子夫原为平阳公主的歌女，因妙丽善舞，被汉武帝看中，召入宫中，大得宠幸。“新承宠”一句，即就此而发。为了具体说明新人的受宠，第四句选取了一个典型的细节。露井桃开，可知已是春暖时节，但宠意正浓的皇帝犹恐帘外春寒，所以特赐锦袍，见出其过分的关心。通过这一细节描写，新人受宠之深，显而易见。另外，由“新承宠”三字，人们自然会联想起那个刚刚失宠的旧人，此时此刻，她可能正站在月光如水的幽宫檐下，遥望未央殿，耳听新人的歌舞嬉戏之声而黯然神伤，其孤寂、愁惨、怨悱之情状。\n\n　　诗文中的写作特点就是咏的都是汉宫旧事，实际上是以汉喻唐，借古讽今。诗以“昨夜”总领全篇，一、二两句切题，点名时令和地点；后两句对新宠者进行直接描述，明写新人受宠的情状，暗抒旧人失宠之怨恨。这首诗通篇写春宫之怨，却无一怨语怨字。作者着力于背面敷粉，以侧面打光的手法，使其明暗清晰。全诗虚此实彼，言近意远：似乎无怨，怨至深；似乎无恨，恨至长。实乃弦外有音的手法，所谓“令人测之无端，玩之不尽”，这正体现了王昌龄七绝的特点。\n\n　　全诗写春宫之怨，却无怨语怨字。作者着力于背面敷粉，以侧面打光的手法，使其明暗清晰。诗明写新人受宠的情状，暗抒旧人失宠之怨恨。虚此实彼，言近意远：似乎无怨，怨至深；似乎无恨，恨至长。实弦外有音的手法。', poem_tags = '唐诗三百首,女子,宫怨' WHERE poem_title = '春宫曲' AND poem_author = '王昌龄';
UPDATE edu_poem SET poem_translation = '译文 请问远古开始之时，谁将此态流传导引？ 天地尚未成形之前，又从哪里得以产生？ 明暗不分浑沌一片，谁能探究根本原因？ 迷迷蒙蒙这种现象，怎么识别将它认清？ 白天光明夜晚黑暗，究竟它是为何而然？ 阴阳参合而生宇宙，哪是本体哪是演变？ 天的体制传为九重。有谁曾去环绕量度？ 这是多么大的工程。是谁开始把它建筑？ 天体轴绳系在哪里？天极不动设在哪里？ 八柱撑天对着何方？东南为何缺损不齐？ 平面上的九天边际，抵达何处联属何方？ 边边相交隅角很多，又有谁能知其数量？ 天在哪里与地交会？黄道怎样十二等分？ 日月天体如何连属？众星在天如何置陈？ 太阳是从旸谷出来。止宿则在蒙汜之地。 打从天亮直到天黑，所走之路究竟几里？ 月亮有着什么德行，竟能死了又再重生？ 月中黑点那是何物，是否兔子腹中藏身？ 神女女岐没有配偶，为何能够产下九子？ 伯强之神居于何处？天地瑞气又在哪里？ 天门关闭为何天黑？天门开启为何天亮？ 东方角宿还没放光，太阳又在哪里匿藏？ 鲧既不能胜任治水。众人为何将他推举？ 都说没有什么担忧，为何不让试着做去？ 鸱龟相助或曳或衔，鲧有什么神圣德行？ 治理川谷也见功劳，尧帝为何对他施刑？ 将鲧长久禁闭羽山。为何三年还不放他？ 大禹从鲧腹中生出，治水方法怎样变化？ 接手先人未竟事业，终使父亲遗志成功。 为何继承前任遗绪，他的谋略却不相同？ 洪水如渊深不见底。怎样才能将它填塞？ 天下土地肥瘠九等，怎样才能划分明白？ 应龙如何以尾画地？河海如何流通顺利？ 鲧是什么使他意乱？禹是什么使他事成？ 水神共工勃然大怒，东南大地为何侧倾？ 九州大地如何安置？河流山谷怎样疏浚？ 东流之水总不满溢，谁知这是什么原因？ 东西南北四方土地。哪边更长哪边更多？ 南北顺量比较狭长，长出地方又有几何？ 昆仑山上玄圃仙境，它的尾部又在哪里？ 山中还有增城九重，它的高度又有几里？ 昆仑山的四面门户，什么人物由此出入？ 西北两面大门敞开，什么气息通过此处？ 太阳光辉哪儿不到？烛龙又能照耀何方？ 羲和还没御日出行，若木之花为何放光？ 什么地方冬日长暖？什么地方夏日长寒？ 哪儿又有岩石成林？什么野兽会发人言？ 哪儿有着独角虬龙，以熊为妇游牝从容？ 雄的虺蛇九个头颅，来去迅捷生在何处？ 不死之国哪里可找？长寿之人持何神术？ 萍草蔓延根茎盘错，枲麻长在哪儿开花？ 一条长蛇吞下大象，它的身子又有多大？ 黑水之地玄趾之民，还有三危都在哪里？ 延年益寿得以不死，生命久长几时终止？ 奇形鲮鱼生于何方？怪鸟魁堆长在哪里？ 后羿怎样射下九日？日中之乌如何解体？ 大禹尽力成其圣功，降临省视天下四方。 哪儿得来涂山之女，与她结合就在台桑？ 爱涂山女与之匹配，得到继嗣儿子出生。 为何嗜欲与人同味，求欢饱享一朝之情？ 启代伯益作了国君，终究还是遇上灾祸。 为何启会遭此忧患，身受拘囚又能逃脱？ 都是勤谨鞠躬尽瘁，没有损害他们自身。 为何伯益福祚终结，禹的后嗣繁荣昌盛？ 夏启做梦上天作客，得到九辩九歌乐曲。 为何贤子竟伤母命，使她支解满地尸骨？ 帝尧派遣夷羿降临，消除忧患安慰夏民。 为何箭射那个河伯，夺取他的妻子洛嫔？ 持着宝弓套着扳指，把那巨大野猪射死。 为何献上蒸祭肥肉，天帝心中并不舒适？ 寒浞要娶纯狐氏女，羿妻合伙把羿谋杀。 为何羿能射穿皮革，其妻与浞能消灭他？ 西行之路遇阻受困，山岩重重怎么越过？ 鲧的身子化为黄熊，巫师如何使他复活？ 地上都已播种黑黍，芦苇水滩也已经营。 为何遭逐同于四凶，难道鲧真恶贯满盈？ 白虹披身作为衣饰，为何常仪这么堂皇？ 哪儿得到不死之药，却又不能长久保藏？ 天的法式有纵有横，阳气离散就会死亡。 大鸟金乌多么肥壮，为何竟会体解命丧？ 雨师屏翳号呼下雨，他怎样使雨势兴盛？ 有着驯良柔顺体质，鹿身风神如何响应？ 巨鳌背负神山舞动，神山怎样稳定不移？ 舍弃舟船行走陆地，龙伯巨人怎样迁徙？ 想那浇在家居之时，对他嫂嫂有何要求？ 为何少康驱赶猎犬，遇浇就能将他斩首？ 女艾借着缝补衣服，与浇同住一个房间。 为何少康取浇首级，浇虽力大仍然遇难？ 少康策划整顿部下，他是如何厚待众人？ 讨伐斟寻倾覆其船，他用什么方法取胜？ 夏桀出兵讨伐蒙山，所得之物又是什么？ 妺喜怎样恣肆淫虐？商汤怎样将桀诛杀？ 舜在家里非常仁孝，父亲为何让他独身？ 尧不告诉舜父瞽瞍，二妃如何与舜成亲？ 起初刚有淫奢萌芽，怎么就能预料结局？ 纣王建造十层玉台，谁使他到如此地步？ 承受天命登位称帝，什么道理受人敬仰？ 女娲有着特殊形体，是谁将她造成这样？ 舜帝友爱他的弟弟，弟弟还是对他加害。 为何放肆如同猪狗？其身并不危险失败？ 吴国得以长久存在，江南山川民众栖止。 谁能想到此中缘故，全因得到两个男子？ 饰鹄饰玉铜鼎调羹，美食拿来献飨君王。 为何承用伊尹之谋，汤能伐桀使他灭亡？ 商汤降临巡视四方，在外遇到贤臣伊尹。 为何桀在鸣条受罚，黎民百姓十分高兴？ 简狄住在瑶台之上，帝喾怎会对她中意？ 玄鸟高飞送来聘礼，简狄为何那么欢喜？ 王亥秉承王季之德，受到他的父亲褒奖。 为何终遭有易之难，当他在此放牧牛羊？ 王亥持盾跳起武舞，为何就有女子爱他？ 有易女子体态丰腴，为何王亥能够配她？ 有易国的放牧小子，又在哪里撞破私情？ 凶器击床王亥已出，如何得以保存性命？ 王恒秉承王季之德，哪里得到大牛满栏？ 为何去求有易赐禄，却不能够安然回返？ 上甲微能追随祖迹，有易国就不得安宁。 为何众鸟集于树丛，他会与其子妇偷情？ 弟弟昏乱共为淫虐，因此危害他的兄长。 为何善变狡诈多端，他的后代反而盛昌？ 成汤出巡东方之地，到达有莘氏的国土。 为何求得小臣伊尹，还能再得妃子贤淑？ 水边那株空桑木上，拾到那个小儿伊尹。 为何又会产生恶感，把他作为陪嫁礼品？ 汤从囚地重泉出来，究竟他有什么大罪？ 难忍耻辱起而伐桀，是谁挑起这场是非？ 诸侯前来朝会请盟，为何都能守约如期？ 苍鹰威武成群高飞，谁使它们聚在一起？ 整顿队伍攻击商纣，周公姬旦却不同意。 为何亲自为武王谋，奠定周朝又发叹息？ 天将天下授予殷商，纣的王位如何施设？ 成功之道违反则亡，他的罪过又是什么？ 诸侯踊跃拿起武器，武王如何动员他们？ 军队并进击敌两翼，他又如何指挥大兵？ 昭王盛治兵车出游，到达南方远地才止。 最后得到什么好处，难道只是遇见白雉？ 穆王御马巧施鞭策，为何他要周游四方？ 他的足迹环绕天下，有些什么要求愿望？ 妖人夫妇牵引叫卖，为何他们呼号街市？ 幽王究竟杀的是谁？哪里得来这个褒姒？ 天命从来反覆无常，何者受惩何者得佑？ 齐国桓公九合诸侯，最终受困身死尸朽。 那个殷商纣王自身，是谁使他狂暴昏乱？ 为何厌恶忠良辅佐，喜欢听信小人谗谄？ 比干有何悖逆之处，为何对他贬抑打击？ 雷开惯于阿谀奉承，为何给他赏赐封地？ 为何圣人品德相同，处事方法最终相异？ 梅伯受刑剁成肉酱，箕子装疯消极避世。 后稷原是嫡出长子，帝喾为何毒害翻脸？ 将他扔在寒冰之上，鸟儿为何覆翼送暖？ 为何长大仗弓持箭，善治农业怀有奇能？ 出生既已惊动上帝，为何后嗣繁荣昌盛？ 西伯姬昌号令衰世，执鞭来作雍州牧伯。 为何武王令治周社，承受天命享有殷国？ 带着宝藏迁居岐山，如何能使百姓依从？ 殷纣已受妲己迷惑，劝谏之言又有何用？ 纣王赐他儿子肉酱，西伯姬昌向天诉求。 为何纣王亲受天罚，殷商命运仍难挽救？ 太公吕望人在肉店，姬昌为何就能认识？ 听到挥刀振动发声，文王为何那么欢喜？ 武王姬发诛纣灭商，为何抑郁不能久忍？ 抬着文王木主会战，为何充满焦急之情？ 纣王烧柴上吊自焚，这样去死究竟何故？ 为何武王惊天动地，假托神灵却怀畏惧？ 上帝既降天命于殷，为何不再劝戒明白？ 纣王既已统治天下，为何又被他人取代？ 初把伊尹视作小臣，后来用作辅政宰相。 为何最终上追成汤，受到尊敬宗庙配享？ 阖庐有功寿梦之孙，少年遭受离散之苦。 为何壮年奋厉勇武，能使他的威严远布？ 彭祖烹调雉鸡之羹，为何帝尧喜欢品尝？ 得享高寿年岁太多，为何竞有那么久长？ 大地中央共同治民，列国君主为何发怒？ 蜂蛾生命原本微贱，自卫力量为何牢固？ 惊于女言不再采薇，白鹿为何庇佑夷齐？ 北行来到回水之地，一起饿死有何可喜？ 哥哥有着善咬猛犬，弟弟又打什么主意？ 一百辆车换一条狗，最终不成反失禄米。 傍晚时分雷鸣电闪，想要归去有何忧愁？ 国家庄严不复存在，对着上帝有何祈求？ 伏身藏匿洞穴之中，还有什么事情要讲？ 楚国勋旧军中殉国，国势如何能够久长？ 悔悟过失改正错误，我又有何言词可陈？ 吴王阖庐与楚争国，我们久已被他战胜！ 环绕穿越里社丘陵，为何生出令尹子文？ 我曾告诉贤者堵敖，楚国将衰不能久长。 为何自赞告诫君主，忠义之名欲更显扬？ ▲', poem_appreciation = '《天问》是屈原的代表作，该作层层设问，用提问的方式表达自己的观念和价值取向，情理交融，声情并茂，宛若梦笔生花，令人读来兴趣盎然，绝无枯燥之感。因此，清代学者刘献庭在《离骚经讲录》中赞其为“千古万古至奇之作”。\n\n　　《盘花歌》，布依族民间歌曲，通常以四季、十二月为序，青年男女以花寓情，内容以花为核心，相互盘问种花的过程和经验，涉及各种生产、生活知识，流行在贵州惠水一带。苗族民间歌曲，借花盘问，或以花比喻对方，两句为一段，三段成一首，流行在贵州望谟一带。\n\n　　那么，楚国庙堂里真的有壁画吗？答案是肯定的。人类开始绘画的历史目前已经追溯到数万年前，我们有理由相信，凡是能够画上图案的材质，当初人们都曾经尝试过，并由此而形成了种类繁多的绘画品种。例如人体画、服饰画、陶器画、木器画、石器画、金属器画、皮画、帛画、纸画（画面尺寸相对较小），以及岩画、地画和壁画（画面尺寸相对比较大）。\n\n　　一般来说，古代绘画内容，一是为了宗教或巫术目的，二是为了记述历史，三是为了传播知识。例如，我国畲族有一种古老的歌舞，名叫功德舞，亦称祭祖舞。每年农历正月初八祭祖，每三年举族大祭祖，以及丧葬仪式，都要由年长者主持，请师公（巫师）和祭祖者（丧葬仪式为八人），在祖先画像前，唱祭祀歌，跳表现祖先功德的舞蹈，众人随之共舞。祖先画像又称祖图，通常为长卷式，绘画内容为本民族起源与迁徙的传说。\n\n　　我国岩画分布地域非常广，其中比较著名的有内蒙古的阴山岩画，宁夏的桌子山岩画和贺兰山岩画，江苏连云港的将军崖岩画，以及西北地区（新疆、甘肃、青海）岩画、西南地区（西藏、云南、贵州、广西、四川）岩画和福建台湾岩画，此外牡丹江亦发现有岩画。多少令人有些奇怪的是，在文明发达甚早的中原地区（包括河北省、河南省、陕西省、山西省、山东省、安徽省、湖北省）的太行山、吕梁山、秦岭、熊耳山、伏牛山、泰山、大巴山、荆山、大别山等山脉却几乎不见有过什么样的岩画（吉林、辽宁、湖南、江西、浙江、广东、海南亦未发现岩画）。究其原因，可能是因为这里的人们很早就发展了地画、壁画等艺术形式，因此也就不需要在岩壁上绘画了。\n\n　　在我国，地画和壁画（包括墙壁、天花板）是两种相当古老的绘画形式，其起源可以追溯到先夏时期（通常所谓的新石器时代）。我国地画首次发现于1982年10月，当时考古工作者在甘肃省秦安王营大地湾文化遗址发掘中，在一处房屋居住面上方发现一幅用碳黑颜料绘制的地画，画面范围东西长1·2米，南北宽1·1米，图案为舞人和陈牲，现存画面有两个人物像，画像人物高约33厘米、宽约14厘米，状似一男一女翩翩起舞，绘画时间距今已有5000多。陕西省绥德小官道龙山文化遗址（距今4000多年前），一座半地穴式房屋后室的中央部位的地面上，也发现一幅黑红色装饰画，现存的椭圆形图饰，东西宽1·3米，南北长1·5米。此外，我国先民还创造有地面摆塑画，用贝壳或石块摆塑成动物、人物或星座等图案，例如著名的河南省濮阳西水坡仰韶文化遗址（距今6000多年前）的墓葬里出土有贝壳摆塑成的龙虎图案画、虎背卧鹿画、龙头蜘蛛画、人骑龙背画，它们也可以归入地面画。\n\n　　我国壁画最早见于5000多年前的辽宁牛河梁红山文化“女神庙”遗址，在出土的墙壁残块表面绘有几何形纹图案画，系赭红间黄白色交错三角形图案。遗憾的是，由于我国古代建筑绝大多数都是土木结构，难以持久存在；因此，随着古代建筑物的坍塌，建筑物内的壁画也随之烟消云散，了无踪迹。但是，这并不意味着古人不曾在庙堂里、墓室内广泛地绘制过壁画。\n\n　　丁晏在《天问笺·自序》中指出：“何以知其呵壁也？壁之有画，汉世犹然。汉鲁殿石壁，及文翁《礼殿图》，皆有先贤画像。武梁祠堂有伏戏、祝诵、夏桀诸人像。”事实上，许多典籍都记载有古代壁画，《汉书·霍光传》提到周公负成王图，《汉书·成帝纪》记有：“元帝在太子宫生甲观画堂。”应劭注：“画堂画九子母。”《汉书·叙传》称：“时乘舆幄坐张画屏风，画纣醉踞妲己作长夜之乐。”《文选》载王延寿《鲁灵光殿赋》云：“图画天地，品类群生，杂物奇怪，山神海灵。写载其状，托之丹青。”\n\n　　《太平广记》卷210引《王子年拾遗记》：“秦有烈裔者，骞霄国人，秦皇帝时，本国进之。口含丹墨，喷壁以成龙兽。以指历地，如绳界之。转手方圆，皆成规度。方寸内有五岳四读，列国备焉。善画龙凤，轩轩然惟恐飞去。”这是目前能够见到的，有关绘制壁画的有名有姓的画家的最早记录。\n\n　　有必要指出的是，《天问》的内容与《山海经》有许多相近相合的地方。《山海经》是由帝禹时代的《五藏山经》、夏代的《海外四经》、商代的《大荒四经》和周代的《海内五经》合辑而成的，相传《山海经》原本有图，如其不谬，那么《山海经图》也有可能曾经被绘制在上述历史朝代的庙堂墙壁上（常见的说法是，山海经图被铸造在九鼎上）。屈原创作《天问》长诗的时间，没有留下记载。从作品内容和作者流露的情感来看，当在创作《离骚》、《九歌》、《招魂》之后。这是因为，《天问》既没有像《离骚》那样娓娓道来，也没有像《九歌》那样全身心的敬天娱神，而是对天意对人事咄咄发问；显然，当诗人有了《天问》所传达的精神和认识之后，是不可能再写出《离骚》和《九歌》那样的作品的。', poem_tags = '楚辞' WHERE poem_title = '天问' AND poem_author = '屈原';
UPDATE edu_poem SET poem_translation = '夜气清新，尘滓皆无，月光皎洁如银。值此良辰美景，把酒对月，须尽情享受。名利都如浮云变幻无常，徒然劳神费力。人的一生只不过像快马驰过缝隙，像击石迸出一闪即灭的火花，像在梦境中短暂的经历一样短暂。\n虽有满腹才学，却不被重用，无所施展。姑且借现实中的欢乐，忘掉人生的种种烦恼。何时能归隐田园，不为国事操劳，有琴可弹，有酒可饮，赏玩山水，就足够了。', poem_notes = '行香子：词牌名，又名“爇心香”。“行香”即佛教徒行道烧香，调名本此。平韵双调小令。《词谱》以晁补之词为正格，六十六字，前段八句四平韵，后段八句三平韵。另有六十四字、六十八字、六十九字诸体。\n尘：尘滓，细小的尘灰渣滓。\n十分：古代盛酒器。形如船，内藏风帆十幅。酒满一分则一帆举，十分为全满。\n虚苦：徒劳，无意义的劳苦。\n叹隙中驹：感叹人生短促， 如快马驰过隙缝。\n石中火，梦中身：比喻生命短促，像击石迸出一闪即灭的火花，像在梦境中短暂的经历。\n开口谁亲：有话对谁说，谁是知音呢？\n陶陶：无忧无虑，单纯快乐的样子。“且陶陶、乐尽天真”是其现实享乐的方式。', poem_appreciation = '作者首先描述了抒情环境：夜气清新，尘滓皆无，月光皎洁如银。此种夜的恬美，只有月明人静之后才能感到，与日间尘世的喧嚣判若两个世界。把酒对月常是诗人的一种雅兴：美酒盈樽，独自一人，仰望长空，遐想无穷。唐代诗人李白月下独斟时浮想翩翩，抒写了狂放的浪漫主义激情。苏轼正为政治纷争所困扰，心情苦闷，因而他这时没有“把酒问青天”也没有“起舞弄清影”，而是严肃地思索人生的意义。月夜的空阔神秘，阒寂无人，正好冷静地来思索人生，以求解脱。苏轼以博学雄辩著称，在诗词里经常发表议论。此词在描述了抒情环境之后便进入玄学思辩了。作者曾在作品中多次表达过“人生如梦”的主题思想，但在这首词里却表达得更明白、更集中。他想说明：人们追求名利是徒然劳神费力的，万物在宇宙中都是短暂的，人的一生只不过是“隙中驹、石中火、梦中身”一样地须臾即逝。作者为说明人生的虚无，从古代典籍里找出了三个习用的比喻。《庄子·知北游》云：“人生天地之间，若白驹之过隙，忽然而已。”古人将日影喻为白驹，意为人生短暂得像日影移过墙壁缝隙一样。《文选》潘岳《河阳县作》李善《注》引古乐府诗“凿石见火能几时”和白居易《对酒》的“石火光中寄此身”，亦谓人生如燧石之火。《庄子·齐物论》言人“方其梦也，不知其梦也，梦之中又占其梦焉，觉而后知其梦也；且有大觉而后知此其大梦也，而愚者自以为觉”。唐人李群玉《自遣》之“浮生暂寄梦中身”即表述庄子之意。苏轼才华横溢，在这首词上片结句里令人惊佩地集中使用三个表示人生虚无的词语，构成博喻，而且都有出处。将古人关于人生虚无之语密集一处，说明作者对这一问题是经过长期认真思索过的。上片的议论虽然不可能具体展开，却概括集中，已达到很深的程度。下片开头，以感叹的语气补足关于人生虚无的认识。\n\n　　下片开头，以感叹的语气补足关于人生虚无的认识。“虽抱文章，开口谁亲”是古代士人“宏才乏近用”，不被知遇的感慨。苏轼在元祐时虽受朝廷恩遇，而实际上却无所作为，“团团如磨牛，步步踏陈迹”，加以群小攻击，故有是感。他在心情苦闷之时，寻求著自我解脱的方法。善于从困扰、纷争、痛苦中自我解脱，豪放达观，这正是苏轼人生态度的特点。他解脱的办法是追求现实享乐，待有机会则乞身退隐。“且陶陶、乐尽天真”是其现实享乐的方式。只有经常在“陶陶”之中才似乎恢复与获得了人的本性，忘掉了人生的种种烦恼。但最好的解脱方法膜过于远离官场，归隐田园。看来苏轼还不打算立即退隐，“几时归去”很难逆料，而田园生活却令人十分向往。弹琴，饮酒、赏玩山水，吟风弄月，闲情逸致，这是我国文人理想的一种消极的生活方式。他们恬淡寡欲，并无奢望，只需要大自然赏赐一点便能满足，“一张琴、一壶酒、一溪云”就足够了。这非常清高而富有诗意。\n\n　　苏轼是一位思想复杂和个性鲜明的作家。他在作品中既表现建功立业的积极思想，也经常流露人生虚无的消极思想。如果仅从某一作品来评价这位作家，都可能会是片面的。这首《行香子》的确表现了苏轼思想消极的方面，但也深刻地反映了他在政治生活中的苦闷情绪，因其建功立业的宏伟抱负在封建社会是难以实现的。苏轼从青年时代进入仕途之日起就有退隐的愿望。其实他并不厌弃人生，他的退隐是有条件的，须得像古代范蠡、张良、谢安等杰出人物那样，实现了政治抱负之后功成身退。因而“几时归去，作个闲人”，这就要根据政治条件而定了。事实上，他在一生的政治生涯中并未功成名遂，也就没有实现退隐的愿望，临到晚年竟还被远谪海南。\n\n　　全词在抒情中插入议论。人生很短暂，能做得不多，回首一看，一切都是虚无，就像偶尔掠过墙缝的阳光、又像燧石取火闪过的火花，或者是黄粱一梦中一段不切实际的经历，都是稍纵即逝、无法真正拥有的。与其浪费生命去追求名利浮云，不如放下一切做个闲人，对一张琴、倒一壶酒、听溪水潺潺、看白云飘飘，享受当下的美好自在。这是作者从生活中悟出人生认识，很有哲理意义，读者读后不致感到其说得枯燥。此词是东坡词中风格旷达的作品。\n\n　　行香子词音节流美，堪称词林中之佳调。 上下片领格字用去声，领下三言三句。下片第一、二句，一般和上片平仄相同并押韵，然亦有并以仄收不押韵。东坡此词可为定格之典范。在韵律上此词虽不如《行香子·过七里濑》优美，但也很不错，尤其是“隙中驹，石中火，梦中身”，“一张琴，一壶酒，一溪云”两段排比，很有韵律美。\n\n　　人生苦短，怀才不遇，建功无望，入仕之时亦生退隐之心，这是古代文人普遍的矛盾。于是有花间的沉沦，有避世的归隐，而苏轼是豪放达观之人，“且陶陶、乐尽天真”，似乎忘掉了人生的烦恼。此词虽在一定程度上流露了作者的苦闷、消极情绪，但“且陶陶、乐尽天真”的主题，基调却是开朗明快的。而词中语言的畅达、音韵的和谐，正好与这一基调一致，形式与内容完美地融合起来。据宋人洪迈《容斋四笔》所记，南宋绍兴初年就有人略改动苏轼此词，以讽刺朝廷削减给官员的额外赏赐名目，致使当局停止讨论施行。可见它在宋代文人中甚为流传，能引起一些不满现实的士大夫的情感共鸣。', poem_tags = '饮酒,抒怀' WHERE poem_title = '行香子·述怀' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '想留住情郎却无济于事，他酒醉后登上画船，扬帆而去。碧波荡漾的春江中，那船儿一定乘风疾驶，黄莺啼晓之声，会充满他的耳际。\n渡口空空荡荡只剩下杨柳郁郁青青，枝枝叶叶都满含着别意离情。从此后休要寄锦书再诉衷情，画楼里的欢娱不过是一场春梦，那山盟海誓毕竟空口无凭。', poem_notes = '留人不住：郑文宝《柳枝词》：“亭亭画舸系春潭，直到行人酒半酣。不管烟波与风雨，载将离恨过江南。”此处翻用其意。\n兰舟：木兰舟，以木兰树所造之船。此处泛指船只。\n锦书：书信的美称。前秦苏若兰织锦为字成回文诗，寄给丈夫窦滔。后世泛称情书为锦书。\n云雨：隐喻男女交合之欢。\n无凭：靠不住。', poem_tags = '宋词三百首,离别,柳树,分手' WHERE poem_title = '清平乐·留人不住' AND poem_author = '晏几道';
UPDATE edu_poem SET poem_translation = '繁华往事，已跟香尘一样飘荡无存；流水无情，野草却年年以碧绿迎春。啼鸟悲鸣，傍晚随着东风声声传来；落花纷纷，恰似那为石崇坠楼的绿珠美人。', poem_notes = '香尘：石崇为教练家中舞妓步法，以沉香屑铺象牙床上，使她们践踏，无迹者赐以珍珠。\n坠楼人：指石崇爱妾绿珠，曾为石崇坠楼而死。', poem_appreciation = '金谷园故址在今河南洛阳西北，是西晋富豪石崇的别墅，繁荣华丽，极一时之盛。唐时园已荒废，成为供人凭吊的古迹。据《晋书。石崇传》记载：石崇有妓曰绿珠，美而艳。孙秀使人求之，不得，矫诏收崇。崇正宴于楼上，谓绿珠曰：“我今为尔得罪。”绿珠泣曰：“当效死于君前。”因自投于楼下而死。杜牧过金谷园，即景生情，写下了这首咏春吊古之作。\n\n　　面对荒园，首先浮现在诗人脑海的是，金谷园繁华的往事，随着芳香的尘屑消散无踪。“繁华事散逐香尘”这一句蕴藏了多少感慨。王嘉《拾遗记》谓：“石季伦（崇）屑沉水之香如尘末，布象床上，使所爱者践之，无迹者赐以真珠。”此即石崇当年奢靡生活之一斑。“香尘”细微飘忽，去之迅速而无影无踪。金谷园的繁华，石崇的豪富，绿珠的香消玉殒，亦如香尘飘去，云烟过眼，不过一时而已。正如苏东坡诗云：“事如春梦了无痕”。可叹乎？亦可悲乎？还是观赏废园中的景色吧：“流水无情草自春”。“流水”指东南流经金谷园的金水。不管人世间的沧桑，流水照样潺湲，春草依然碧绿，它们对人事的种种变迁，似乎毫无感触。这是写景，更是写情，尤其是“草自春”的“自”字，与杜甫《蜀相》中“映阶碧草自春色”的“自”字用法相似。\n\n　　傍晚，正当诗人对着流水和春草遐想的时候，忽然东风送来鸟儿的叫声。春日鸟鸣，本是令人心旷神怡的赏心乐事。但是此时—红日西斜，夜色将临；此地—荒芜的名园，再加上傍晚时分略带凉意的春风，在沉溺于吊古之情的诗人耳中，鸟鸣就显得凄哀悲切，如怨如慕，仿佛在表露今昔之感。日暮、东风、啼鸟，本是春天的一般景象，着一“怨”字，就蒙上了一层凄凉感伤的色彩。此时此刻，一片片惹人感伤的落花又映入诗人的眼帘。诗人把特定地点（金谷园）落花飘然下坠的形象，与曾在此处发生过的绿珠坠楼而死联想到一起，寄寓了无限情思。一个“犹”字渗透着诗人多少追念、怜惜之情！绿珠，作为权贵们的玩物，她为石崇而死是毫无价值的，但她的不能自主的命运不是同落花一样令人可怜么？诗人的这一联想，不仅是“坠楼”与“落花”外观上有可比之处，而且揭示了绿珠这个人和“花”在命运上有相通之处。比喻贴切自然，意味隽永。\n\n　　一般怀古抒情的绝句，都是前两句写景，后两句抒情。这首诗则是句句写景，景中寓情，四句蝉联而下，浑然一体。', poem_tags = '唐诗三百首,怀古' WHERE poem_title = '金谷园' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '译文 苏溪亭边野草茁长，遍地青青，已是暮春时节。在东风吹拂中，斜倚阑干象《西洲曲》里的那人是谁呢？ 燕子还没有回到旧窝，而美好的春光已快要完了。迷蒙的烟雨笼罩着一片沙洲，料峭春风中的杏花，也失去了晴日下艳丽的容光，显得凄楚可怜。', poem_appreciation = '这首诗的写作时间与《兰溪棹歌》相近。戴叔伦公元780年在（唐德宗建中元年）旧历五月至次年春曾任东阳令，苏溪在今浙江省义乌市苏溪镇，与浙江省东阳市不远，这首诗大约是他在这段期间所作的。\n\n　　诗中所写的景是暮春之景，情是怨别之情。“苏溪亭上草漫漫”，写出地点和节候。野草茁长，遍地青青，已是暮春时节。这时的溪边亭上，“春草碧色，春水渌波”，最容易唤起人们的离愁别绪，正为下句中的倚阑人渲染了环境气氛。“谁倚东风十二阑”，以设问的形式，托出倚阑人的形象。在东风吹拂中，斜倚阑干的那人是谁呢？这凝眸沉思的身姿，多像《西洲曲》里的人：“鸿飞满西洲，望郎上青楼。楼高望不见，尽日阑干头。阑干十二曲，垂手明如玉。”\n\n　　这位倚阑人眼中所见、心中所思的是什么呢？“燕子不归春事晚，一汀烟雨杏花寒。”燕子还没有回到旧窝，而美好的春光已快要完了。虽是眼中之景，却暗喻着心中之情：游子不归，红颜将老。“一汀烟雨杏花寒”，正是“春事晚”的具体描绘。迷蒙的烟雨笼罩着一片沙洲，料峭春风中的杏花，也失去了晴日下艳丽的容光，显得凄楚可怜。这景色具体而婉曲地传出倚阑人无端的怅惘，不尽的哀愁。如此写法，使无形之情因之而可见，无情之景因之而可思。宋人贺铸《青玉案·凌波不过横塘路》词里的警句：“试问闲愁都几许？一川烟草，满城风絮，梅子黄时雨”，可能就是受到这首唐诗的启发的。\n\n　　四句诗全是写景，而景语即情语，情景融浑无迹。诗人描写暮春景色浓郁而迷蒙，恰和倚阑人沉重而忧郁的心情契合相印，诗韵人情，隽永醇厚。', poem_tags = '春天,闺怨' WHERE poem_title = '苏溪亭' AND poem_author = '戴叔伦';
UPDATE edu_poem SET poem_translation = '来堂前打枣我从不阻拦任随西邻，因为她是一个五食无儿的老妇人。\n若不是由于穷困怎会做这样的事？正因她心存恐惧反更该与她相亲。\n见你来就防着你虽然是多此一举，但你一来就插上篱笆却甚像是真。\n她说官府征租逼税已经一贫如洗，想起时局兵荒马乱不禁涕泪满巾。', poem_notes = '呈：呈送，尊敬的说法。这是用诗写的一封信，作者以前已写过一首《简吴郎司法》，这是又一首，所以说“又呈”。吴郎：系杜甫吴姓亲戚。杜甫将草堂让给他住。这位亲戚住下后，即有筑“篱”，护“枣”之举。杜甫为此写诗劝阻。\n妇人：成年女子的通称，多指已婚者。\n扑枣：击落枣子。汉王吉妇以扑东家枣实被遣。扑：打。任：放任，不拘束。西邻：就是下句说的“妇人”。\n不为：要不是因为。困穷：艰难窘迫。宁有此：怎么会这样（做这样的事情）呢？宁：岂，怎么，难道。此：代词，代贫妇人打枣这件事。\n只缘：正因为。恐惧：害怕。转须亲：反而更应该对她表示亲善。亲：亲善。\n即：就。防远客：指贫妇人对新来的主人存有戒心。防：提防，心存戒备。一作“知”。远客：指吴郎。多事：多心，不必要的担心。\n使：一作“便”。插疏篱：是说吴郎修了一些稀疏的篱笆。甚：太。\n征求：指赋税征敛。贫到骨：贫穷到骨（一贫如洗）。\n戎（róng）马：兵马，指战争。杜甫《登岳阳楼》诗：“戎马关山北，凭轩涕泗流。”盈：满。', poem_appreciation = '诗的第一句开门见山，从诗人自己过去怎样对待邻妇扑枣说起。“扑枣”就是打枣。这里不用那个猛烈的上声字“打”，而用这个短促的、沉着的入声字“扑”，是为了取得声调和情调的一致。“任”就是放任。之所以要放任，第二句说：“无食无儿一妇人。”原来这位西邻竟是一个没有吃的、没有儿女的老寡妇。诗人等于是在对吴郎说：“对于这样一个无依无靠的穷苦妇人，我们能不让她打点枣儿吗？”\n\n　　三四两句紧接一二句：“不为困穷宁有此？只缘恐惧转须亲。”“困穷”，承上第二句；“此”，指扑枣一事。这里说明杜甫十分同情体谅穷苦人的处境。陕西民歌中唱道：“唐朝诗圣有杜甫，能知百姓苦中苦。”说的正是杜甫。以上四句，一气贯串，是杜甫自叙以前的事情，目的是为了启发吴郎。\n\n　　五六两句才落到吴郎身上。“即防远客虽多事，便插疏篱却甚真。”这两句上下一气，相互关联，相互依赖，相互补充，要联系起来看。“防”的主语是寡妇。下句“插”字的主语是吴郎。这两句诗言外之意是：这不能怪她多心，倒是吴郎有点太不体贴人。她本来就是提心吊胆的，吴郎不特别表示亲善，也就够了，却不该还要插上篱笆。这两句诗，措词十分委婉含蓄。这是因为怕话说得太直、太生硬，教训意味太重，会引起对方的反感，反而不容易接受劝告。\n\n　　最后两句“已诉征求贫到骨，正思戎马泪盈巾”，是全诗结穴，也是全诗的顶点。表面上是对偶句，其实并非平列的句子，因为上下句之间由近及远，由小到大是一个发展的过程。上句，杜甫借寡妇的诉苦，指出了寡妇的、同时也是当时广大人民困穷的社会根源。这就是官吏们的剥削，也就是诗中所谓“征求”，使她穷到了极点。这也就为寡妇扑枣行为作了进一步的解脱。下句说得更远、更大、更深刻，指出了使人民陷于水深火热之中的又一社会根源。这就是“安史之乱”以来持续了十多年的战乱，即所谓“戎马”。由一个穷苦的寡妇，由一件扑枣的小事，杜甫竟联想到整个国家大局，以至于流泪。这一方面固然是他那热爱祖国、热爱人民的思想感情的自然流露；另一方面，也是点醒、开导吴郎的应有的文章。让他知道：“在这兵荒马乱的情况下，苦难的人还有的是，决不止寡妇一个；战乱的局面不改变，就连我们自己的生活也不见得有保障，我们现在不正是因为战乱而同在远方作客，而你不是还住着我的草堂吗？”最后一句诗，好像扯得太远，好像和劝阻吴郎插篱笆的主题无关，其实是大有关系，大有作用的。希望他由此能站得高一点，看得远一点，想得开一点，他自然就不会在几颗枣子上斤斤计较了。读者正是要从这种地方看出诗人的“苦用心”和他对待人民的态度。\n\n　　这首诗的人民性是强烈而鲜明的，在通常用来歌功颂德以“高华典雅”为特征的七言律诗中，尤其值得重视。诗的艺术表现方面也很有特点。首先是现身说法，用诗人自己的实际行动来启发对方，用颠扑不破的道理来点醒对方，最后还用诗人自己的眼泪来感动对方，尽可能地避免抽象的说教，措词委婉，入情入理。其次是，运用散文中常用的虚字来作转接。像“不为”、“只缘”、“已诉”、“正思”，以及“即”、“便”、“虽”、“却”等，因而能化呆板为活泼，既有律诗的形式美、音乐美，又有散文的灵活性，抑扬顿挫，耐人寻味。\n\n　　清人卢德水说：“杜诗温柔敦厚，其慈祥恺悌之衷，往往溢于言表。如此章，极煦育邻妇，又出脱邻妇；欲开导吴郎，又回护吴郎。八句中，百种千层，莫非仁音，所谓仁义之人其音蔼如也”（《读杜私言》）。全诗正是在这种委婉曲折的夹叙夹议中来展现诗人的心理和品质的。诗作表达了杜甫对穷困人民的深切同情。', poem_tags = '忧国忧民' WHERE poem_title = '又呈吴郎' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '夕阳西下暮色朦胧，花蕊笼罩轻烟，\n月华如练，我思念着情郎终夜不眠。\n柱上雕饰凤凰的赵瑟，我刚刚停奏，\n心想再弹奏蜀琴，又怕触动鸳鸯弦。\n这饱含情意的曲调，可惜无人传递，\n但愿它随着春风，送到遥远的燕然。\n忆情郎呵、情郎他迢迢隔在天那边，\n当年递送秋波的双眼，\n而今成了流泪的源泉。\n您若不信贱妾怀思肝肠欲断，\n请归来看看明镜前我的容颜！', poem_notes = '赵瑟：相传古代赵国的人善弹瑟。瑟：弦乐器。\n凤凰柱：或是瑟柱上雕饰凤凰形状。\n蜀琴句：旧注谓蜀琴与司马相如琴挑故事有关。按：鲍照有“蜀琴抽白雪”句。白居易也有“蜀琴安膝上，《周易》在床头”句。李贺“吴丝蜀桐张高秋”，王琦注云：“蜀中桐木宜为乐器，故曰蜀桐。”蜀桐实即蜀琴。似古人诗中常以蜀琴喻佳琴，恐与司马相如、卓文君事无关。鸳鸯弦也只是为了强对凤凰柱。', poem_appreciation = '“日色欲尽花含烟，月明如素愁不眠”一句，季节、时间、环境、情绪全出来了。春日的一个黄昏，日色将尽，夜幕降临，花辨上也似乎含着缕缕烟雾，女主人在干什么呢？月亮已经升起来了，明如镜、皎如绢，一种淡淡的愁绪让她开始感到闷倦，难以安眠。这样一烘托，一幅温婉细腻的场景率先浮现在了读者面前。\n\n　　紧接着一副工整的对仗“赵瑟初停凤凰柱，蜀琴欲奏鸳鸯弦”。古代赵国的妇女善鼓瑟，故称赵瑟，蜀中有桐木宜作琴，相传司马相如曾奏蜀琴来挑逗卓文君。诗人用这两句排比在暗喻什么呢。从字面上来看，赵瑟刚弹过，凤凰状的瑟柱停下来了，又不知不觉的拿起蜀琴，准备开始奏起鸳鸯弦。而凤凰、鸳鸯都是成双成对生活，正是男女之情的一种见证！哦，原来女主人是在思念她的爱人了。　\n\n　　再来看下句“此曲有意无人传，愿随春风寄燕然”，男人在思念至极呐喊“天长地远魂飞苦，梦魂不到关山难”，一片如火之热情。女人则如水，她不怨恨，她只是把满怀心事托与春风，希望春风能把因凤凰柱、鸳鸯弦带给她的那深切的别离之苦捎给远方的心上人。“寄燕然”一句告诉我们，原来她的丈夫是从征去了。李白在《关山月》中曾经这样描写过征客的心境“戍客望边邑，思归多苦颜。高楼当此夜，叹息未应闲”，这样的思念，比起“一种相思、两种闲愁”的“闲愁”更多了几分烟火气息和现实意义。\n\n　　心事已经寄予春风了，春风真的能给爱人带去自己的一片相思吗？女人心里依旧一片茫然，于是她发出了一声沉重的叹息：“忆君迢迢隔青天”！山水迢迢，对你的思念如此遥远，就象隔着那苍茫的青天。\n\n　　“昔日横波目，今为流泪泉”，一句想象奇特、大胆夸张的对偶把这个美丽的女子形象刻画出来了，旧日的那对顾盼灵秀、眼波如流的双目，如今却变成了泪水的源泉，可知二人分开之后，女子除了长夜无眠和深深叹息之外，竟是常常的以泪洗面。　\n\n　　末句“不信妾肠断，归来看取明镜前”，使这个女子的形象更加鲜明丰满了，你看她娇嗔的说道：如果你不相信我因为思念你而肝肠寸断，等你回来时，在明镜前看看我憔悴、疲惫的面容就知道了。一副天真、调皮的样子跃然纸上，让人倍加爱怜和心痛。　\n\n　　《长相思》第二首相比第一首，言语更加浅显易懂、音韵更加曲调化，我想，这与唐朝音乐鼎盛有关，从宫廷乐府到民间教坊，许多诗词都被谱上曲谱，四处吟唱，李白的乐府诗更是其中一颗璀璨的明珠。第二首又用了夸张、排比、想象、暗喻等手法，从多个角度把这个美丽多情的女子对出征边塞丈夫的思念之情表现得淋漓尽致。\n\n　　诗人虽不是女子，却能刻画如此生动、细腻的女子形象，就好像曹雪芹不是女人，却能读懂天下形形色色的女人一样，我想，世间无论男女，也许不必太多的在意付出，只要能真正的读懂对方，此生足矣！', poem_tags = '唐诗三百首,乐府,女子,思念' WHERE poem_title = '长相思·其二' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '春愁难以排遣，强打起精神眺望远山，往事让人触目惊心热泪将流。台湾的四百万同胞齐声大哭，去年的今天，就是祖国宝岛被割让的日子！', poem_notes = '潸：流泪的样子。\n四百万人：指当时台湾人口合闽、粤籍，约四百万人。\n去年今日：指1895年4月17日，清王朝与日本签订丧权辱国的《马关条约》，将台湾割让给日本。', poem_appreciation = '赏析 　　这首诗作于1896年春，即《马关条约》签订一年后。诗人痛定思痛，抒发了强烈的爱国深情。春天本是一年中最美好的季节，草绿林青，百花争艳，连春山也显得格外妩媚。但诗人为什么觉得春愁难以排遣，以致勉强地观看春山也毫无兴致呢？这是因为诗人始终未能忘记去年春天发生的那件令人痛心疾首的往事。台湾本是中国的神圣领土，诗人生于斯、长于斯，想不到满清卖国政府竟将它割让给了日本。这是对台湾人民的无耻出卖，也是台湾人民的奇耻大辱。回想起这一惊心动魄的惨剧，诗人怎能不愁情满怀、怆然泪下呢？“情能移景，景亦能移情”（吴乔《围炉诗话》）此时诗人被迫离开故乡，看见大陆的春山，联想起故乡台湾的青山绿水——那片被日寇侵占的土地，自然触景伤怀了。春愁难遣，看山落泪，正表现了诗人对祖国和故乡山水的热爱。末两句诗中，诗人又用逆挽句式描述了去年今日台湾被割让时，四百万台湾人民同声痛哭，俯地悲泣的情景。这一催人泪下的情景生动地表明了全体台湾人民是热爱祖国的，台湾是伟大祖国不可分割的一部分。从这一角度讲，这首诗鲜明地体现了当时的时代精神，又具有珍贵的史料价值。这首诗，语言朴实无华，但却具有震撼人心的艺术力量。这主要是由于诗人与自己的人民同呼吸，共爱憎，泪洒在一起。“感人心者，莫先乎情。”这首诗的动人，主要是因为它真实而强烈地表达了人民的情感和心声。 ▲', poem_tags = '古诗三百首,春天,爱国,感伤' WHERE poem_title = '春愁' AND poem_author = '丘逢甲';
UPDATE edu_poem SET poem_translation = '失意潦倒，携酒漂泊江湖，沉湎于楚灵王喜好的细腰女子和赵飞燕的轻盈舞姿。扬州十年的纵情声色，好像一场梦，醒悟回头，却在青楼女子这中落得一个薄情的名声。', poem_notes = '落魄：仕宦潦倒不得意，飘泊江湖。魄一作拓。楚腰：指细腰美女。《韩非子·二柄》：“楚灵王好细腰，而国中多饿人。”\n掌中轻：汉成帝皇后赵飞燕“体轻，能为掌上舞”（《飞燕外传》）。\n十年：一作三年。\n青楼：旧指精美华丽的楼房，也指妓院。薄幸：薄情。', poem_appreciation = '此追忆扬州岁月之作。杜牧于公元833-835年（文宗大和七年至九年）在淮南节度使牛僧孺幕府任推官，转掌书记，居扬州。当时他三十一、二岁，颇好宴游。从此诗看，他与扬州青楼女子多有来往，诗酒风流，放浪形骸。故日后追忆，乃有如梦如幻、一事无成之叹。这是诗人感慨人生自伤怀才不遇之作，非如某些文学史所论游戏人生，轻佻颓废，庸俗放荡之什。《唐人绝句精华》云：“才人不得见重于时之意，发为此诗，读来但见其兀傲不平之态。世称杜牧诗情豪迈，又谓其不为龊龊小谨，即此等诗可见其概。”\n\n　　诗的前两句是昔日扬州生活的回忆：潦倒江湖，以酒为伴；秦楼楚馆，美女娇娃，过着放浪形骸的浪漫生活。“楚腰纤细掌中轻”，运用了两个典故。楚腰，指美人的细腰。“楚灵王好细腰，而国中多饿人”（《韩非子·二柄》）。掌中轻，指汉成帝皇后赵飞燕，“体轻，能为掌上舞”（见《飞燕外传》）。从字面看，两个典故，都是夸赞扬州妓女之美，但仔细玩味“落魄”两字，可以看出，诗人很不满于自己沉沦下僚、寄人篱下的境遇，因而他对昔日放荡生涯的追忆，并没有一种惬意的感觉。“十年一觉扬州梦”，这是发自诗人内心的慨叹，好像很突兀，实则和上面二句诗意是连贯的。“十年”和“一觉”在一句中相对，给人以“很久”与“极快”的鲜明对比感，愈加显示出诗人感慨情绪之深。而这感慨又完全归结在“扬州梦”的“梦”字上：往日的放浪形骸，沉湎酒色；表面上的繁华热闹，骨子里的烦闷抑郁，是痛苦的回忆，又有醒悟后的感伤。这就是诗人所“遣”之“怀”。忽忽十年过去，那扬州往事不过是一场大梦而已。“赢得青楼薄幸名”—最后竟连自己曾经迷恋的青楼也责怪自己薄情负心。“赢得”二字，调侃之中含有辛酸、自嘲和悔恨的感情。这是进一步对“扬州梦”的否定，可是写得却是那样貌似轻松而又诙谐，实际上诗人的精神是很抑郁的。十年，在人的一生中不能算短暂，自己却一事无成，丝毫没有留下什么。这是带着苦痛吐露出来的诗句，非再三吟哦，不能体会出诗人那种意在言外的情绪。\n\n　　前人论绝句尝谓：“多以第三句为主，而第四句发之”（胡震亨《唐音癸签》），杜牧这首绝句，可谓深得其中奥妙。这首七绝用追忆的方法入手，前两句叙事，后两句抒情。三、四两句固然是“遣怀”的本意，但首句“落魄江湖载酒行”却是所遣之怀的原因，不可轻轻放过。前人评论此诗完全着眼于作者“繁华梦醒，忏悔艳游”，是不全面的。诗人的“扬州梦”生活，是与他政治上不得志有关。因此这首诗除忏悔之意外，大有前尘恍惚如梦，不堪回首之意。', poem_tags = '唐诗三百首,抒怀' WHERE poem_title = '遣怀' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '注释 碾雕白玉：茶碾是白玉雕成的。 罗织红纱：茶筛是红纱制成的。 铫：煎茶器具。 曲尘花：指茶汤上面的饽沫。', poem_appreciation = '一字至七字诗，俗称宝塔诗，在中国古代诗中较为少见。元稹的这首宝塔诗，先后表达了三层意思：一是从茶的本性说道了人们对茶的喜爱；二是从茶的煎煮说到了人们的饮茶习俗；三是就茶的功用说到了茶能提神醒酒。翠绿，香清高，味甘鲜，耐冲泡。此茶不仅可以消暑解渴生津，而且还有激情的助消化作用和治病功效。此诗一开头，就点出了主题是茶。接着写了茶的本性，即味香和形美。第三句是倒装句，说茶深受“诗客”和“僧家”的爱慕，茶与诗，总是相得益彰的。第四句写的是烹茶，因为古代饮的是饼茶，所以先要用白玉雕成的碾把茶叶碾碎，再用红纱制成的茶罗把茶筛分。第五句写烹茶先要在铫中煎成“黄蕊色”，尔后盛载碗中浮饽沫。第六句谈到饮茶，不但夜晚要喝，而且早上也要饮。到结尾时，指出茶的妙处，不论古人或者今人，饮茶都会谈到精神饱满，特别是酒后饮茶有助醒酒。\n\n　　这首诗饶有趣味，描写上，有动人的芬芳：香叶，有楚楚的形态：嫩芽、曲尘花，还有生动的色彩：“碾雕白玉，罗织红纱。铫煎黄蕊色”。饮茶之时，应是夜后陪明月，晨前对朝霞，真是享受着神仙般快乐的生活，可谓“睡起有茶饴有饭，行看流水坐看云”（《痴绝翁》）。茶还可以洗尽古人今人之不倦，这是茶的神奇妙用。\n\n　　首先要说这首诗的独特之处。元稹以宝塔的形式来排列诗歌，不仅形式特别，而且读起来朗朗上口，同时也描绘了茶的形态、功用和人们对它的喜爱之情。', poem_tags = '写茶' WHERE poem_title = '一七令·茶' AND poem_author = '元稹';
UPDATE edu_poem SET poem_appreciation = '（一）\n\n　　第一首先写草堂，举其四景：堂西的竹笋，堑北的行椒，园中的梅子，久七前的松树。诗人处在这远离闹市的幽静环境之中，因看到园中将熟的梅子，便想到待梅熟时邀朱老一同尝新；因看到堂前的松树，便希望和阮生在松荫下尽情地谈古论今。从中可以看出诗人对草堂的爱赏，以及他对生活的朴素的要求。他久经奔波，只要有一个安身之地就已经满足了。显然，这首诗虽属赋体却兼比兴，于平淡的写景叙事中寓含着诗人的淡泊心情，以作为组诗之纲。当时杜甫因好友严武再镇而重返草堂，足证严武在诗人心目中的重要地位，但这里他所想到的草堂的座上宾都不是严武，而是普普通通的朱老和阮生。这就可见诗人当时的心境和志趣了。\n\n　　（二）\n\n　　第二首诗写浣花溪，状其水势浩大，借“欲作鱼梁”而抒情，非真“欲作鱼梁”也。因为“作鱼梁，须劈竹沉石，横截中流，以为聚鱼之区，因溪有蛟龙，时兴云雨，故公不敢冒险以取利。”（《杜诗详注》卷十三引）对此解说，浦起龙《读杜心解》认为“是为公所愚也”。他说：“须知‘蛟龙，之想，只从‘云覆、‘雨寒，生出，值云雨而墩起文情也。”是有道理的。但浦氏以为这首诗“为作鱼梁而赋，而自况不凡”，则未免有点牵强。其实，这首诗并非什么“自况”，只是流露出诗人对能否在洗花溪畔的草堂安居下去的担心情绪。这才是“不敢安”三字的真实含意。诗人觉得自己在草堂尽管心境淡泊，无所奢求，但仍难保不测。诗中谓溪下有坟龙，时兴云雨，固是一种迷信的说法，却也十分形象化，隐隐可以显示出诗人身居草堂对成都局势的担心情状。这也正是诗人当时“三年奔走空皮骨”的心理状态。\n\n　　（三）\n\n　　这组诗一开始写草堂的春色，情绪是陶然的；而随着视线的游移、景物的转换、江船的出现，触动了他的乡情，四句景语完整表现了诗人这种复杂细致的内心思想活动。此诗两两对杖，写法非常精致考究，读起来却一点儿也不觉得雕琢，十分自然流畅。把读者由眼前景观引向广远的空间和悠长的时间之中，引入对历史和人生的哲思理趣之中。\n\n　　“两个黄鹂鸣翠柳，一行白鹭上青天。 窗含西岭千秋雪，门泊东吴万里船。”黄鹂、翠柳显出活泼的气氛，白鹭、青天给人以平静、安适的感觉。“鸣”字表现了鸟儿的怡然自得。“上”字表现出白鹭的悠然飘逸。黄、翠、白、青，色泽交错，展示了春天的明媚景色，也传达出诗人欢快自在的心情。诗句有声有色，意境优美，对仗工整。一个“含”字，表明诗人是凭窗远眺，此景仿佛是嵌在窗框中的一幅图画。这两句表现出诗人心情的舒畅和喜悦。“西岭”，即成都西南的岷山，其雪常年不化，故云“千秋雪”。“东吴”，三国时孙权在今江苏南京定都建国，国号为吴，也称东吴。这里借指长江下游的江南地区。“千秋雪”言时间之久，“万里船”言空间之广。诗人身在草堂，思接千载，视通万里，胸襟何等开阔！这两句也是全诗的点睛之笔，境界开阔，情志高远。在空间和时间两个方面拓宽了广度，使得全诗的立意一下子卓尔不群，既有杜诗一贯的深沉厚重，又舒畅开阔，实为千古名句。\n\n　　苏轼曾经说过：“少陵翰墨无形画”。此诗就像一幅绚丽生动的山水条幅：黄鹂、翠柳、白鹭、青天、江水、雪山，色调淡雅和谐，图象有动有静。画的中心是几棵翠绿的垂柳，黄莺儿在枝头婉转歌唱；画的上半部是青湛湛的天，一行白鹭映于碧空；远处高山明灭可睹，遥望峰巅犹是经年不化的积雪；近处露出半边茅屋，门前一条大河，水面停泊着远方来的船只。从颜色和线条看，作者把两笔鹅黄点染在一片翠绿之中，在青淡的空间斜勾出一条白线。点线面有机结合，色彩鲜明而又和谐。诗人身在草堂，思接千载，视通万里，胸次开阔，出语雄健。全诗对仗精工，着色鲜丽，动静结合，声形兼俱，每句诗都是一幅画，又宛然组成一幅咫尺万里的壮阔山水画卷。\n\n　　（四）\n\n　　第四首诗为药圃而赋。王嗣爽《杜臆》说：“公常多病，所至必种药，故有‘种药扶衰病，之句。”（《杜诗详注》卷十三引）。今影印本《杜臆》元，仇氏（仇兆鳌）当另有所据。”前两句写药圃景色，种药在两亭之间，青色叠映，临窗望去，油然而喜。后两句虽也是写药物的生长情状，与前两句写药物出土，发苗及枝柯的生长过程相连，对一药物生长于隙地的根部的形状作了描绘，足见诗人对药用植物形态学的认识；但就药寄慨，与首章淡泊之意略同，却不是一般的咏物诗，更绝非某些赏花玩月的作品可比。仇兆鳌注：“彼苗长荒山者，不能遍识其名，此隙地所栽者，又恐日浅术及成形身。”浦起龙亦说：“空山隙地，萧间寂寞之滨也，亦无取于见知矣。”可以参看，以见杜甫虽因严武再镇而重返草堂，但仍担心着“不测风云”，总是把自己同国家的命运联系在一起的。他毕竟不是那种忘乎一切的趋炎附势之人。', poem_tags = '抒情,组诗' WHERE poem_title = '绝句四首' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '我担任滁州太守后的第二年夏天，才喝到滁州的泉水，觉得甘甜。于是向滁州人询问泉水的发源地，就在距离滁州城南面一百步的近处。它的上面是丰山，高耸地矗立着；下面是深谷，幽暗地潜藏着；中间有一股清泉，水势汹涌，向上涌出。我上下左右地看，很爱这里的风景。因此，我就叫人疏通泉水，凿开石头，拓出空地，造了一座亭子，于是我和滁州人在这美景中往来游乐。\n\n　　滁州在五代混战的时候，是个互相争夺的地区。过去，太祖皇帝曾经率领后周兵在清流山下击溃李景的十五万军队，在滁州东门的外面活捉了他的大将皇甫晖、姚凤，就这样平定了滁州。我曾经考察过滁州地区的山水，查核过滁州地区的图籍，登上高山来眺望清流关，想寻找皇甫晖、姚凤被捉的地方。可是，当时的人都已经不在，大概是天下太平的时间长久了。自从唐朝败坏了它的政局，全国四分五裂，英雄豪杰们全都起来争夺天下，到处都是敌对的政权，哪能数得清呢？到了大宋朝接受天命，圣人一出现，全国就统一了。以前的凭靠险要的割据都被削平消灭。在一百年之间，静静地只看到山高水清。要想问问那时的情形，可是留下来的老年人已经不在人世了。如今，滁州处在长江、淮河之间，是乘船坐车的商人和四面八方的旅游者不到的地方。百姓活着不知道外面的事情，安心耕田穿衣吃饭，欢乐地过日子，一直到死。有谁晓得这是皇帝的功德，让百姓休养生息，滋润化育到一百年的长久呢！\n\n　　我来到这里，喜欢这地方僻静，而政事简单，又爱它的风俗安恬闲适。在山谷间找到这样的甘泉之后，于是每天同滁州的士人来游玩，抬头望山，低首听泉。春天采摘幽香的鲜花，夏天在茂密的乔木乘凉，刮风落霜结冰飞雪之时，更鲜明地显露出它的清肃秀美，四时的风光，无一不令人喜爱。那时又庆幸遇到民众为那年谷物的丰收成熟而高兴，乐意与我同游。于是为此根据这里的山脉河流，叙述这里风俗的美好，让民众知道能够安享丰年的欢乐，是因为有幸生于这太平无事的时代。宣扬皇上的恩德，和民众共享欢乐，这是刺史职责范围内的事。于是就写下这篇文章来为这座亭子命名。', poem_notes = '丰乐亭：在今安徽滁州城西丰山北，为欧阳修被贬滁州后建造的。苏轼曾将《丰乐亭记》书刻于碑。《舆地纪胜》：“淮南路滁州：丰乐亭，在幽谷寺。庆历中，太守欧阳修建。”清《一统志》：“安徽滁州丰乐亭在州西南琅琊山幽谷泉上。欧阳修建，自为记，苏轼书，刻石。”\n明年：第二年，即庆历六年。\n问诸滁人：向滁人打听泉水的出处。诸，兼词，之于。《与韩忠献王书》：“山川穷绝，比乏水泉，昨夏天之初，偶得一泉于川城之西南丰山之谷中，水味甘冷，因爱其山势回抱，构小亭于泉侧。”又有《幽谷泉》诗。\n耸然而特立：高峻挺拔地矗立着。耸然，高耸的样子。特，突出。\n窈然：深幽的样子。\n滃然：水势盛大的样子。\n俯仰：这里为环顾的意思。\n五代：指后梁、后唐、后晋、后汉、后周。\n干戈：古代兵器，此指战争。\n“昔太祖”五句：公元956年，宋太祖赵匡胤为后周大将，与南唐中主李璟的部将皇甫晖、姚凤会战于滁州清流山下，南唐部队败于滁州城。随后赵匡胤亲手刺伤皇甫晖，生擒皇甫晖、姚凤，夺下滁州城。周，指五代时后周。李景，即李璟，南唐的中主。清流山，在今滁州城西南。\n图记：指地图和文字记载。\n清流之关：在滁州西北清流山上，是宋太祖大破南唐兵的地方。\n“所在”二句：指到处都割据称王，难以计算。胜，尽。\n及：等到。\n圣人出而四海一：指宋太祖赵匡胤统一天下。\n向，从前。\n遗老：指经历战乱的老人。\n舟车商贾：坐船乘车的商人。\n畎：田地。\n乐生送死：使生的快乐，礼葬送死。\n涵煦：滋润教化。\n事简：公务简单。\n掇幽芳而荫乔木：春天采摘清香的花草，夏天在大树荫下休息。掇，拾取。荫，荫庇，乘凉。\n刻露，清楚地显露出来。\n岁物：收成。\n刺史：官名，宋人习惯上作为知州的别称。欧阳修此时为滁州知州，根据习惯自称为刺史。\n名：起名，命名。', poem_tags = '古文观止,叙事,抒情,散文' WHERE poem_title = '丰乐亭记' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '康熙七年六月十七日戍刻，发生了大地震。当时，我在稷下做客，正和表兄李笃之在灯下喝酒。忽然听见有种像打雷一样的声音，从东南方向过来，向西北方向滚去。大家都很惊骇诧异，不知是什么缘故。不一会儿，只见桌子摇晃起来，酒杯翻倒；屋梁房柱，发出一片咔咔的断裂声。众人大惊失色，面面相觑。过了好久，才醒悟过来是地震，急忙冲出屋子。只见外面的楼阁房屋，一会儿斜倒在地上，一会儿又直立起来；墙倒屋塌的声音，混合着孩子号哭的声音，一片鼎沸，震耳欲聋。人头晕得站不住，只能坐在地上，随着地面颠簸。河水翻腾出岸边一丈多远；鸡叫狗吠，全城大乱。过了一个时辰，才稍微安定下来。再看大街上，男男女女，都光着身子聚在一起，争相讲着刚才的事情，都忘了没穿衣服。\n　　后来，听说这次地震时，某处有口水井井筒倾斜了，不能再打水；某家楼台南北掉了个方向；栖霞山裂了道缝；沂水陷下了一个有几亩大的地穴。这真是少有的奇异灾变啊！', poem_notes = '康熙七年：即公元一六六八年。戌刻：晚七时至九时。\n稷（jì记）下：地名。此指临淄。《史记·田敬仲完世家》注引刘向《别录》：“齐有稷门，城门也。谈说之士期会于稷下也。”\n倾仄：倾斜。仄，通“侧”。\n栖霞：县名。今属山东省。\n沂水：县名。今属山东省。\n溲（sōu叟）溺（niào尿）：小便。\n缓颊：犹松嘴。\n一何：多么。', poem_appreciation = '这篇文章通过作者的耳闻目睹与体验，描述了康熙七年间发生在山东的大地震。文章记述地震的过程非常的清晰，从“声如雷”“几案摆簸”到“墙倾屋塌”“河水倾泼”，写出了地震由弱到强的过程，这是从物的角度描述。“众骇异”“相顾失色”到“男女裸聚”，从人的神态进行侧面烘托，写地震严重的程度。最后的耳闻，揭示出了地震破坏的程度，并由此发出了“真非常之奇变”的感慨。\n\n　　结构是作品形式美的重要因素之一。《地震》的格局虽小，但所营造的结构却完整缜密，平整均衡，单纯精美。记事由隐入显，循序渐进，层层开拓境界，逐步创造高潮、首尾连贯完美，通篇委区尽态。结构的艺术处理，贵在线索的贯穿。它运用自如地按记述文的表现形式，以事件发生、发展的时间为线索，把一幅幅惊心动魄的画面组装起来，连动式地推到读者面前：\n\n　　第一幅、烛前对饮图：闻有声如雷，众骇异，不解其故。\n\n　　第二幅、室内，震荡图：几案摆簸、酒杯倾覆，屋梁椽柱，错折有声，相顾失色。\n\n　　第三幅、户外，大震图；楼阁房舍，仆而复起；墙倒屋塌，儿啼女号。人不能立，随地转侧。河水倾泼，鸡呜犬吠。\n\n　　第四幅、街上，男女裸聚图：竞相告语，忘其未衣。\n\n　　第五幅、震后山河图：水井倾仄，楼台易向，栖霞山裂，沂水陷穴。\n\n　　此外，尚有一幅联想到的地震之外的“狼口夺子图”。此图既如绘画，又若小说。\n\n　　五幅画面，完整而形象地再现了一场怵目惊心的大地震的全部过程，正好表明地震发生(第一图)、发展(二图)、高潮(三图)、缓和(四图)、终结(五图)的程序。最后以联想方式出现的“夺儿图’’强化了第四图的思想。这里的文字都有极强的可感性与可绘性。\n\n　　事出突然，事先没有征兆，只听得隆隆雷声，由远及近，人们惊异，但不知原因。一会儿，桌子摇动，杯子倾倒，屋梁有声，人们你看我，我看你，大惊失色，但不知何故。过了好一会儿，才忽然明白——地震了！才快点跑出来。这种描写是人们在遇到突发事件时，一时惊慌失措，理性思维暂停的实际。以上是室内情况。\n\n　　跑出屋子以后，首先看到的是大的建筑物忽起忽落，说明地表在上下颠簸。继之是听到房屋倒塌声、儿啼女号声。刚才是从屋里跑着出来的，所有没感觉到不稳。停下来以后，才觉得站立不稳，于是快点坐下，随地转侧。\n\n　　此时，人惊恐万状，无暇交流情况。大约过了一个时辰，地震停了，人们情绪稍有安定，这时，大家才有可能“竞相告语”，急于宣泄内心恐惧，抱团取暖，竟然忘了自己没穿衣服。情急下的失态，真实地反映了当时的情况。\n\n　　在地震的当时，不可能了解其他地方情况。震情和缓了，十里八乡的亲戚朋友才互相探访，打听安危，于是外地情况不断传来，才有某处井倾侧，楼易向，栖霞山裂，沂水陷穴的传闻。\n\n　　写震前、震中、震后；写房内、房外、街上；写所见、所闻。先写什么，后写什么，合情合理，井井有条，紧紧相扣，一气呵成。再现地震现场画面，非亲临其境者写不出。', poem_tags = '初中文言文,地震' WHERE poem_title = '地震' AND poem_author = '蒲松龄';
UPDATE edu_poem SET poem_translation = '楚国大夫登徒子在楚王面前说宋玉的坏话，他说：“宋玉其人长得娴静英俊，说话很有口才而言辞微妙，又很贪爱女色，希望大王不要让他出入后宫之门。”\n\n　　楚王拿登徒子的话去质问宋玉，宋玉说：“容貌俊美，这是上天所生；善于言词辨说，是从老师那里学来的；至于贪爱女色，下臣则绝无此事。”楚王说：“你不贪爱女色确有道理可讲吗？有道理讲就留下来，没有理由可说便离去。”宋玉于是辩解道：“天下的美女，没有谁比得上楚国女子，楚国女子之美丽者，又没有谁能超过我那家乡的美女，而我家乡最美丽的姑娘还得数我邻居东家那位小姐。东家那位小姐，论身材，若增加一分则太高，减掉一分则太短；论其肤色，若涂上脂粉则嫌太白，施加朱红又嫌太赤，真是生得恰到好处。她那眉毛有如翠鸟之羽毛，肌肤像白雪一般莹洁，腰身纤细如裹上素帛，牙齿整齐有如一连串小贝，甜美地一笑，足可以使阳城和下蔡一带的人们为之迷惑和倾倒。这样一位姿色绝伦的美女，趴在墙上窥视我三年，而我至今仍未答应和她交往。登徒子却不是这样，他的妻子蓬头垢面，耳朵挛缩，嘴唇外翻而牙齿参差不齐，弯腰驼背，走路一瘸一拐，又患有疥疾和痔疮。这样一位丑陋的妇女，登徒子却非常喜爱她，并且生有五个孩子。请大王明察，究竟谁是好色之徒呢？”\n\n　　在那个时候，秦国的章华大夫在楚国，趁机对楚王进言说：“如今宋玉大肆宣扬他邻居的小姐，把她作为美人，而美色能使人乱性，产生邪念;臣自认为我自己老实遵守道德，我觉得还不如宋玉.并且楚国偏远之地的女子，东临之子，怎么能对大王说呢？如果说我眼光鄙陋，大家的确有目共睹，我便不敢说了。”\n\n　　楚王说：“你尝试着再对我说点。”大夫说：“是。臣年少的时候曾经出门远游，足迹踏遍九州，足迹踏遍繁盛的城市。离开咸阳，在邯郸游玩，在郑卫两国的溱水和洧水边逗留。当时是接近春末，将有夏天温暖的阳光，鸧鹒鸟喈喈鸣叫，众美女在桑间采桑叶。郑、卫郊野的美女美妙艳丽，光彩照人。体态曼妙，面容姣好。臣看她们里面美丽的人，称引《诗经》里的话：‘沿着大路与心上人携手同行。’把她送给这芳华美女最妙了。那美人好像要来又没有来，撩得人心烦意乱，恍忽不安。尽管情意密切，但形迹却又很疏远。那美人的一举一动都与众不同；偷偷地看看她，心中不由欣喜微笑，她正含情脉脉，暗送秋波。于是我又称引《诗经》里的话：‘万物在春风的吹拂下苏醒过来，一派新鲜茂密。那美人心地纯洁，庄重种持；正等待我惠赠佳音。似这样不能与她结合，还不如死去。’她引身后退，婉言辞谢。大概最终还是没能找到打动她的诗句，只有凭借精神上支持相依靠着；真的很想亲眼看看她的容颜，心里想着道德规范，男女之大防。口诵《诗经》古语，遵守礼仪，始终没有超越规矩的差错，所以也终于没有什么越轨的举动。”\n\n　　于是楚王同意说好，宋玉就不离去了。', poem_notes = '1.登徒子：复姓登徒，未知是否真有其人，可能仅为文学上的虚构角色。\n2.楚王：这里是指楚襄王。\n3.短：这里指攻其所短。\n4.闲丽：文雅英俊。\n5.微辞：不满的话。\n6.止：与下文“退“相对，指留下。\n7.东家之子：东边邻家的女儿。\n8.著（zhuó）：搽。\n9.施朱：涂烟脂。\n10.束素：一束白色生绢。这是形容腰细。\n11.惑阳城，迷下蔡：使阳城、下蔡两地的男子着迷。阳城、下蔡是楚国贵族封地。\n12.窥：偷看。\n13.未许：不同意，没有答应。\n14.挛（luán）：卷曲。\n15.齞（yàn）唇历齿：稀疏又不整齐的牙齿露在外面。齞：牙齿外露的样子。历齿：形容牙齿稀疏不整齐。\n16.旁行踽（jǔ）偻（lóu）：弯腰驼背，走路摇摇晃晃。踽偻：驼背。\n17.又疥且痔：长满了疥疮和痔疮。\n18.使有五子：使她生有五个儿女。\n19.孰察：孰，通“熟”。仔细端详。\n20.秦章华大夫在侧：当时秦国的章华大夫正在楚国。章华：楚地名。这里是以地望代称。\n21.愚乱之邪：美色能使人乱性，产生邪念。\n22.彼：他，指宋玉。\n23.南楚穷巷之妾：指楚国偏远之地的女子，也即“东邻之子”。\n24.周览九土：足迹踏遍九州。九土：九州。\n25.五都：五方都会，泛指繁盛的都市。\n26.咸阳：当时秦国都城，故址在今陕西省咸阳市东北。\n27.熙邯郸：在邯郸游玩。熙：游玩。邯郸：当时赵国都城，故址在今河北省邯郸市。\n28.从容郑、卫溱（zhēn）洧（wěi）之间：在郑卫两国的溱水和洧水边逗留。从容：逗留，停留。郑、卫：春秋时的两个国名，故址在今河南省新郑市到滑县、濮阳一带。溱洧：郑国境内的两条河。《诗经·郑风·溱洧》写每年上巳节，郑国力女在岸边聚会游乐的情况。\n29.向：接近，临近。\n30.迎夏之阳：将有夏天温暖的阳光。迎：迎接，将要出现。\n31.鸧（cāng）鹒（gēng）喈（jiē）喈：鸧鹒鸟喈喈鸣叫。\n32.群女出桑：众美女在桑间采桑叶。\n33.此郊之姝（shū）：意指郑、卫郊野的美女。\n34.华色含光：美妙艳丽，光彩照人。\n35.称诗：称引《诗经》里的话。\n36.遵大路兮揽子祛（qū）：沿着大路与心上人携手同行。祛：衣袖。《诗经·郑风·遵大路》：“遵大路兮，掺执子之祛兮。”\n37.怳（huǎng）：同“恍”。有望：有所期望。\n38.忽：与怳为互文，恍忽：心神不定的样子。这两句是说，那美人好像要来又没有来，撩得人心烦意乱，恍忽不安。\n39.意密体疏：尽管情意密切，但形迹却又很疏远。\n40.俯仰异观：那美人的一举一动都与众不同。\n41.窃视流眄（miǎn）：偷偷地看看她，她正含情脉脉，暗送秋波。\n42.寐春风兮发鲜荣：万物在春风的吹拂下苏醒过来，一派新鲜茂密。寐：苏醒。\n43.洁斋侯兮惠音声：那美人心地纯洁，庄重种持；正等待我惠赠佳音。斋：举止庄重。\n44.赠我如此兮不如无生：似这样不能与她结合，还不如死去。\n45.因迁延而辞避：她引身后退，婉言辞谢。\n46.微辞：指终于没能打动她的诗句。\n47.目欲其颜：很想亲眼看看她的容颜。\n48.心顾其义：心里想着道德规范，男女之大防。\n49.扬《诗》守礼，终不过差：口诵《诗经》古语，遵守礼仪，也终于没有什么越轨的举动。过差：过失，差错。\n50.足称：值得称道。', poem_appreciation = '“登徒子”一向被作为好色之徒的代名词。便是从赋后始。其实此赋中登徒子，说他是一个谗巧小人还可，说其好色，则有些令人啼笑皆非。赋中写登徒子在楚王面前诋毁宋玉好色，宋玉则以东家邻女至美而其不动心为例说明他并不好色。又以登徒子妻其丑无比，登徒子却和她生了五个孩子，反驳说登徒子才好色。作者描写的登徒子妻岂止是丑，简直令人恶心，而登徒子“悦之”，若好色如登徒子，可称为“色盲”。其实，作者是根据《离骚》“众女嫉余之蛾眉兮，谣诼谓余以善淫”推而广之，目的是指斥嫉贤妒能的谗巧小人而已。同时，更是借章华大夫的“‘发乎情，止乎礼’来假以为辞，讽于淫也”（李善《文选》本赋注），曲折地表达讽谏楚王之意。\n\n　　此赋写了三种对待男女关系的态度：登徒子是女人即爱；宋玉本人是矫情自高；秦章华大夫则好色而守德。作者以第二种自居，是为了反击登徒子之流，实则作者赞同的是第三种，即发乎情止乎礼，这种态度近于人性而又合乎礼制是我国古代文人大夫对待两性关系代表性的态度。和道学家或滥淫者比较，这确也是一种可取的态度。因此，古代文学作品中，时有反映。\n\n　　此赋极尽刻画之形容，如：“增之一分则太长，减之一分则太短；著粉则太白，施朱则太赤。”“眉如翠羽，肌如白雪，腰如束素，齿如含贝。”这种方法，继承了前人，如《诗经·卫风·硕人》：“手如柔夷，肤如凝脂，领如蝤蛴，齿如瓠犀，螓首蛾眉”，只是此赋的描写更细腻更极尽刻画形容之能事。\n\n　　这篇《登徒子好色赋》问世以后，登徒子便成了好色之徒的代称。然而只要细读此文，就不难发现，登徒子既不追逐美女，又从不见异思迁，始终不嫌弃他那位容貌丑陋的妻子，这实在非常难得。登徒子在夫妻生活方面感情如此专一，绝非好色之徒所能办得到的，因而有实事求是地加以澄清的必要。\n\n　　宋玉此赋之所以影响巨大，主要是因为作者巧妙地运用烘托的手法描绘了一幅美女的肖像。文中有这么几句：“东家之子，增之一分则太长，减之一分则太短，着粉则太白，施朱则太赤”，这段话不但一直被后世引用，而且还有人仿效其方法写作。如乐府民歌《陌上桑》在描写采桑女罗敷的美貌时，也采用了同样的手法。诗中写道：“行者见罗敷，下担捋髭须；少年见罗敷，脱帽着帩头。耕者忘其犁，锄者忘其锄，来归相怨怒，但坐观罗敷。”罗敷究竟有多么美丽，诗中并没有直接描写，只写出挑担子的人撂下担子，青年人脱下帽子，农夫忘记了犁地和锄草，甚至招来家人的怨怒，就因为观赏罗敷去了。这种描写美女的手法，一直沿用至今。号称“西部歌王”的王洛滨，在创作《在那遥远的地方》一歌时，也采用了此种手法。他在歌词中是这样描写那位美貌牧羊姑娘的：“在那遥远的地方，有位好姑娘，人们走过她的身旁，都要回头留恋地张望。”人们为什么要回头留恋地张望呢？就因为那位牧羊姑娘长得实在太漂亮了，乃至使作者发出了这样的感慨：“我愿变一只小羊，躺在她的身旁，每天让她用皮鞭轻轻地打在我的身上。”黄梅戏的《夫妻观灯》，也是同样。正月十五元宵夜，一对年轻夫妻去观花灯，看着看着，小伙子对周围观众不去看灯，而目不转睛地盯着她漂亮的妻子看很是不满。用此种烘托的手法去描写美女，可说已经成了一种传统的表现手法，追本溯源，盖出于宋玉的《登徒子好色赋》。', poem_tags = '写人' WHERE poem_title = '登徒子好色赋' AND poem_author = '宋玉';
UPDATE edu_poem SET poem_translation = '西汉的都城长安城上空已是黑云乱翻，李傕、郭汜等人在这里制造事端。\n我忍痛告别了中原的乡土，把一身暂托给遥远的荆蛮。\n送行时亲戚眼里噙着泪水，朋友们依依不舍攀着车辕。\n走出门满目萧条一无所见，只有堆堆白骨遮蔽了郊原。\n一个妇人面带饥色坐路边，轻轻把孩子放在细草中间。\n婴儿哭声撕裂母亲的肝肺，饥妇人忍不住回头看，但终于洒泪独自走去。\n“我自己还不知道死在何处，谁能叫我们母子双双保全？”\n不等她说完，我赶紧策马离去，不忍再听这伤心的语言。\n登上霸陵的高地继续向南，回过头我远望着西京长安。\n领悟了《下泉》诗作者思念贤明国君的心情，不由得伤心、叹息起来。', poem_notes = '西京：指长安，西汉时的国都。东汉建都在洛阳，洛阳称为东都。董卓之乱后，汉献帝又被董卓由洛阳迁到了长安。无象：无章法，无体统。　\n豺虎：指董卓的部将李傕郭汜等。遘患：给人民造成灾难。　\n中国：中原地区。　\n委身：置身。荆蛮：即指荆州。古代中原地区的人称南方的民族曰蛮，荆州在南方，故曰荆蛮。荆州当时未遭战乱，逃难到那里去的人很多。荆州刺史刘表曾从王粲的祖父王畅受学，与王氏是世交，所以王粲去投奔他。　\n追攀：追逐拉扯，表示依依不舍的样子。　\n完：保全。以上两句是作者听到的那个弃子的妇人所说的话。　\n霸陵：汉文帝刘恒的陵墓，在今陕西省长安县东。岸：高坡、高冈。汉文帝是两汉四百年中最负盛名的皇帝，这个时期的社会秩序比较稳定，经济发展较快。所以王粲在这里引以对比现实，抒发感慨。　\n《下泉》：《诗经·曹风》中的一个篇名，汉代经师们认为这是一首曹国人怀念明王贤伯的诗。下泉，流入地下的泉水。　\n喟（kūi亏）然：伤心的样子。这首诗最后四句的意思是，面对着汉文帝的陵墓，对比着当前的离乱现实，就更加伤心地领悟到《下泉》诗作者思念明主贤臣的那种急切心情了。', poem_appreciation = '“七哀”，《文选》六臣注吕向注云：“七哀，谓痛而哀，义而哀，感而哀，怨而哀，耳目闻见而哀，口叹而哀，鼻酸而哀。”这是望文生义。元人李冶《敬斋古今黈》云：“人之七情有喜、怒、哀、乐、爱、恶、欲之殊，今而哀戚太甚，喜、怒、乐、爱、恶、欲皆无有，情之所系惟有一哀而已，故谓之七哀也。”亦颇牵强。《七哀》是乐府歌辞，今人余冠英说：“所以名为‘七’哀，也许有音乐上的关系，晋乐于《怨诗行》用这篇诗（指曹植《七哀》）为歌辞，就分为七解。”（《三曹诗选》）较有道理，可以参考。\n\n　　“西京乱无象，豺虎方遘患。”西京，指长安。东汉都城洛阳，洛阳在东，长安在西，故称长安为西京。豺虎，指董卓部将李傕、郭汜等人。长安乱得不成样子，是因为李傕、郭汜等人正在作乱，他们大肆烧杀劫掠，百姓遭殃。这两句写社会的动乱。诗人正是在这种动乱之中离开长安的，这里交代了诗人离开长安的原因。\n\n　　“复弃中国去，委身适荆蛮。”这里点出诗人离开长安以后的去向。“复”，值得注意，这说明诗人的迁徙不是第一次。公元190年（初平元年），董卓胁迫汉献帝迁都长安，驱使吏民八百万人入关，诗人被迫迁移到长安，此时为了避难，又要离开长安。这个“复”字不仅表现了眼前凄楚的情况，而且勾起了悲惨的往事，蕴涵着无限的感慨和哀伤。“中国”，中原地区。我国古代建都黄河两岸，因此称北方中原地区为中国。“荆蛮”，指荆州。荆州是古代楚国的地方，楚国本称为荆，周人称南方的民族为蛮，楚在南方，故称荆蛮。这两句是说，离开中原地区，到荆州去。这是因为当时荆州没有战乱，所以很多人到那里去避乱。王粲因为荆州刺史刘表，与自己是同乡，而且刘表曾就学于王粲的祖父王畅，两家有世交，所以去投靠他。\n\n　　“亲戚对我悲，朋友相追攀。”写离别时的情景。这两句是互文，“悲”的不仅有“亲戚“，还有“朋友”；“相追攀”的也不仅有“朋友”，还有“亲戚”。诗人描写送别时的表情和动作，固然是为了表现诗人和亲戚朋友的深厚感情，更重要的是制造一种悲惨的气氛，使人感到这是一场生离死别。\n\n　　诗人离开了长安，离开了亲戚朋友，一路上见到的景象触目惊心：“出门无所见，白骨蔽平原。”见到的是累累的白骨，遮蔽了无垠的平原。这是“豺虎”作乱给人民带来的深重灾难。这场战乱造成的悲惨景象，曹操《蒿里行》写道：“白骨露于野，千里无鸡鸣。生民百遗一，念之断人肠。”所咏是同样的情景，可以参阅。以上是“鸟瞰”，下面六句写的才是典型事例：“路有饥妇人，抱子弃草间。顾闻号泣声，挥泪独不还：‘未知身死处，何能两相完？”这六句同样紧承“出门无所见”。诗人见到的不仅是“白骨蔽平原”，还有“饥妇人”弃子的事。妇人爱子，这是正常现象；妇人弃子，这是反常现象。这种反常现象的产生，是由于战乱。因此，诗人以惨绝人寰的事例深刻地揭露了战乱给人民带来的沉重灾难。鲜明而生动，催人泪下。吴淇说：“‘出门’以下，正云‘乱无象’。兵乱之后，其可哀之事，写不胜写，但用‘无所见’三字括之，则城郭人民之萧条，却已写尽。复于中单举妇人弃子而言之者，盖人当乱离之际，一切皆轻，最难割者骨肉，而慈母于幼子尤甚，写其重者，他可知矣。”（《六朝选诗定论》卷六）张玉谷说：“‘出门’十句，叙在途饥荒之景，然胪陈不尽，独就妇人弃子一事，备极形容，而其他之各不相顾，塞路死亡，不言自显。作诗解此举重该轻之法，庶几用笔玲珑。”（《古诗赏析》卷九）都道出了这种写法的艺术特点。这种写法对杜甫是有影响的，所以何焯说：“‘路有饥妇人’六句，杜诗宗祖。”（《义门读书记》卷四十六）\n\n　　妇人弃子的惨景，使诗人耳不忍闻，目不忍睹。所以他“驱马弃之去，不忍听此言”。这表现了诗人的哀伤和悲痛。诗人乘马继续向前行进。“南登霸陵岸，回首望长安。”霸陵，是汉文帝刘恒的陵墓所在地，在今陕西长安县东。汉文帝是汉代的明君，史书上赞他“以德化民，是以海内殷富”（《汉书·文帝纪》），有所谓“文景之治”。诗人南登霸陵高处，回首眺望长安，自然会想起汉文帝及“文景之治”。如果有汉文帝这样的贤明君主在世，长安就会不如此混乱、残破，百姓不至于颠沛流离，自己也不至于流亡他乡。登霸陵，眺长安，诗人感慨万端。\n\n　　“悟彼下泉人，喟然伤心肝。”连同上面两句，同为全篇的结尾。下泉，是《诗经·曹风》的篇名。《毛诗》序云：“下泉，思治也。曹人……思明王贤伯也。”“下泉人”，指《下泉》诗的作者。面对着汉文帝的陵墓，面对着动乱的社会现实，诗人才懂得《下泉》诗作者思念明王贤君的急切心情，因而从内心发出深深的哀叹。张玉谷说：“末日‘南登’‘回首’，兜应首段。‘伤心’‘下泉’，缴醒中段，收束完密，全篇振动。”（《古诗赏析》卷九）方东树也说：“‘南登霸陵岸’二句，思治，以下转换振起，沉痛悲凉，寄哀终古。”（《昭昧詹言》卷二）都指出了此诗结尾的艺术效果。\n\n　　这首诗写得悲凉沉痛，真切动人，是建安诗歌中的名作。方东树评为“冠古独步”，不是没有道理的。', poem_tags = '古诗三百首,叙事,抒情' WHERE poem_title = '七哀诗三首·其一' AND poem_author = '王粲';
UPDATE edu_poem SET poem_translation = '不要学许由用颍水洗耳，不要学伯夷和叔齐隐居收养采薇而食。\n在世上活着贵在韬光养晦，为什么要隐居清高自比云月？\n我看自古以来的贤达之人，功绩告成之后不自行隐退都死于非命。\n伍子胥被吴王弃于吴江之上，屈原最终抱石自沉汨罗江中。\n陆机如此雄才大略也无法自保，李斯以自己悲惨的结局为苦。\n（陆机）是否还能听见华亭的别墅间的鹤唳？（李斯）是否还能在上蔡东门牵鹰打猎？\n你不知道吴中的张翰是个旷达之人，因见秋风起而想起江东故都。\n生时有一杯酒就应尽情欢乐，何须在意身后千年的虚名？', poem_notes = '晋朝皇甫谧《高士传》卷上《许由》篇：“尧让天下于许由，……由于是遁耕于中岳颍水之阳，箕山之下……尧又召为九州长，由不欲闻之，洗耳于颍水滨。”\n《史记·伯夷列传》：“武王已平殷乱，天下宗周，而伯夷、叔齐耻之，义不食周粟，隐于首阳山，采薇而食之……遂饿死于首阳山。”《索引》：“薇，蕨也。”按薇、蕨本二草，前人误以为一。\n《高士传》：巢父谓许由曰：“何不隐汝形，藏汝光？”此句言不露锋芒，随世俯仰之意。\n鲍照《拟行路难》：“自古圣贤尽贫贱”。《史记·蔡泽列传》：“四时之序，成功者去。……商君为秦孝公明法令，……功已成矣，而遂以车裂。……白起……功已成矣，而遂赐剑死于杜邮。吴起……功已成矣，而卒枝解。大夫种为越王深谋远计……令越成霸，功已彰而信矣，勾践终负而杀之。此四子者，功成不去，祸至于身？”\n子胥：伍子胥。《吴越春秋》卷五《夫差内传》：“吴王闻子胥之怨恨也，乃使人赐属镂之剑，子胥……遂伏剑而死。吴王乃取子胥尸，盛以鸱夷之器，投之于江中。”又见《国语·吴语》。\n《晋书·陆机传》载：陆机因宦人诬陷而被杀害于军中，临终叹曰：“华亭鹤唳，岂可复闻乎？”\n《史记·李斯列传》载：李斯喟然叹曰：“……斯乃上蔡布衣……今人臣之位，无居臣上者，可谓富贵极矣。物极则衰，吾未知所税驾？”（《索引》：“税驾，犹解驾，言休息也”）\n《史记·李斯列传》：“二世二年七月，具斯五刑，论腰斩咸阳市。斯出狱，与其中子俱执，顾谓其中子曰：‘吾欲与若复牵黄犬俱出上蔡东门逐狡兔，岂可得乎！’”《太平御览》卷九二六：《史记》曰：“李斯临刑，思牵黄犬、臂苍鹰，出上蔡门，不可得矣。”', poem_tags = '唐诗三百首,乐府,人生,态度' WHERE poem_title = '行路难·其三' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '马儿穿行在山路上菊花已微黄，任由马匹自由地行走兴致悠长。\n千万的山谷回荡着声响静听夜，看数座山峰在夕阳下默默无语。\n棠梨的落叶红得好似胭脂一般，香气扑鼻的荞麦花啊洁白如雪。\n是什么让我在吟诗时忽觉惆怅，原来乡村小桥像极了我的家乡！', poem_notes = '信马：骑着马随意行走。野兴：指陶醉于山林美景，怡然自得的乐趣。\n晚籁：指秋声。籁，大自然的声响。\n棠梨：杜梨，又名白梨、白棠。落叶乔木，木质优良，叶含红色。\n荞麦：一年生草本植物，秋季开白色小花，果实呈黑红色三棱状。\n原树：原野上的树。原，原野。', poem_appreciation = '古代文人被贬谪期间，难免情绪抑郁，但却摆脱了案牍之劳形，可以纵情流连于山水胜景之中，而偏远之地，美丽的大自然最能安顿迁客的心灵。商州的自然美景带给王禹偁极大的抚慰，他曾在《听泉》诗里自嘲说：“平生诗句是山水，谪宦方知是胜游”。时间久了，一方山水之美也就渐渐融化在他那颗诗心里，化作人与自然相谐的动人诗篇。这首诗是他与商山的自然风景进行心灵对话的艺术结晶。\n\n　　开头两句，交代了时、地、人、事。时令是秋季，这是以“菊初黄”间接交待的；地点是山间小路，这是以“山径”直接点明的；人物是作者本人，这是从诗的结句中的“吾”字而得出的结论；事情是作者骑马穿山间小路而行，领略山野旖旎的风光，这是从诗行里透露出来的消息。这两句重在突出作者悠然的神态、浓厚的游兴。\n\n　　三、四两句分别从听觉与视觉方面下笔。前句写傍晚秋声万壑起，这是耳闻；后句写数峰默默伫立在夕阳里，这是目睹。这里，“有声”与“无语”两种截然不同的境界相映成趣，越发显示出山村傍晚的沉寂。尤其值得一提的是：“数峰”句写数峰宁静，不从正面着墨，而从反面出之，读来饶有情趣。这正如钱钟书先生在《宋诗选注》中所说的“山峰本来是不能语而‘无语’的，王禹偁说它们‘无语’或如龚自珍《己亥杂诗》说‘送我摇鞭竟东去，此山不语看中原’，并不违反事实；但是同时也仿佛表示它们原先能语、有语、欲语而此刻忽然‘无语’。这样，‘数峰无语’、‘此山不语’才不是一句不消说得的废话······”\n\n　　颔联耳闻“有声”与目睹“无语”两种截然不同的境界相映成趣，越发显示出山村傍晚的沉寂，富有情趣。诗人迷恋山间那份宁静，然而暮色已悄然降临，还是且行且回。第三联写山乡的红叶与荞麦花：经霜的棠梨叶随风飘落，红艳似火，在山野间分外耀眼；成片的荞麦花开如雪，阵阵清香扑鼻而来。“胭脂”与“白雪”对举，令红的更艳，白的更纯，给读者带来极唯美的视觉感受。诗人乘兴而游，胜景触目，吟咏成诗，可是吟完诗句，一丝怅惘涌上心头，诗人看见了：前面的小桥流水、原野平林，很是眼熟。似乎重归故里，那份近乡情切的感觉也许仅在刹那间一闪，便恍然回转过来，——此地并非诗人的故乡，诗人心中的那份恼意自不待言说，这次村行的情绪也由悠然转入怅然。满目山川，清晖娱人，宦途失意的异乡人却有家不得归，此情此景，真的是“夕阳西下，断肠人在天涯”。\n\n　　作者在前六句诗里描绘了一幅色彩斑斓、富有诗意的秋日山村晚晴图，较好地体现了宋人“以画入诗”的特点。诗的最后两句由写景转入抒情。前句设问，写诗人在吟诗之后不知为什么忽然感到闷闷不乐；后句作答，写这原来是诗人因蓦然发现村桥原野上的树像他故乡的景物而产生了思乡之情。这样写，就使上文的景物描写有了着落，传神地反映出了作者的心情由悠然至怅然的变化，拓深了诗意。', poem_tags = '古诗三百首,秋天,写景,思乡' WHERE poem_title = '村行' AND poem_author = '王禹偁';
UPDATE edu_poem SET poem_translation = '七月大火向西落，九月妇女缝寒衣。十一月北风劲吹，十二月寒气袭人。没有好衣没粗衣，怎么度过这年底？正月开始修锄犁，二月下地去耕种。带着妻儿一同去，把饭送到向阳的土地上去，田官十分高兴。\n\n　　七月大火向西落，九月妇女缝寒衣。春天阳光暖融融，黄鹂婉转唱着歌。姑娘提着深竹筐，一路沿着小道走。伸手采摘嫩桑叶，春来日子渐渐长。人来人往采白蒿，姑娘心中好伤悲，害怕要随贵人嫁他乡。\n\n　　七月大火向西落，八月要把芦苇割。三月修剪桑树枝，取来锋利的斧头。砍掉高高长枝条，攀着细枝摘嫩桑。七月伯劳声声叫，八月开始把麻织。染丝有黑又有黄，我的红色更鲜亮，献给贵人做衣裳。\n\n　　四月远志结了籽，五月知了阵阵叫。八月田间收获忙，十月树上叶子落。十一月上山猎貉，猎取狐狸皮毛好，送给贵人做皮袄。十二月猎人会合，继续操练打猎功。打到小猪归自己，猎到大猪献王公。\n\n　　五月蚱蜢弹腿叫，六月纺织娘振翅。七月蟋蟀在田野，八月来到屋檐下。九月蟋蟀进门口，十月钻进我床下。堵塞鼠洞熏老鼠，封好北窗糊门缝。叹我妻儿好可怜，岁末将过新年到，迁入这屋把身安。\n\n　　六月食李和葡萄，七月煮葵又煮豆。八月开始打红枣，十月下田收稻谷。酿成春酒美又香，为了主人求长寿。七月里面可吃瓜，八月到来摘葫芦。九月拾起秋麻子，采摘苦菜又砍柴，养活农夫把心安。\n\n　　九月修筑打谷场，十月庄稼收进仓。黍稷早稻和晚稻，粟麻豆麦全入仓。叹我农夫真辛苦，庄稼刚好收拾完，又为官家筑宫室。白天要去割茅草，夜里赶着搓绳索。赶紧上房修好屋，开春还得种百谷。\n\n　　十二月凿冰冲冲，正月搬进冰窖中。二月开初祭祖先，献上韭菜和羊羔。九月寒来始降霜，十月清扫打谷场。两槽美酒敬宾客，宰杀羊羔大家尝。登上主人的庙堂，举杯共同敬主人，齐声高呼寿无疆。', poem_notes = '七月流火：火（古读huǐ），或称大火，星名，即心宿。流，流动。每年夏历五月，黄昏时候，这星当正南方，也就是正中和最高的位置。过了六月就偏西向下了，这就叫做“流”。 \n授衣：将裁制冬衣的工作交给女工。九月丝麻等事结束，所以在这时开始做冬衣。 \n一之日：十月以后第一个月的日子。以下二之日、三之日等仿此。为豳历纪日法。觱（bì）发（bō）：大风触物声。 \n栗烈：或作“凛冽”，形容气寒。 \n褐：粗布衣。 \n于：犹“为”。为耜是说修理耒耜（耕田起土之具）。 \n趾：足。 “举趾”是说去耕田。 \n馌（yè）：馈送食物。亩：指田身。田耕成若干垄，高处为亩，低处为畎。田垄东西向的叫做“东亩”，南北向的叫做“南亩”。这两句是说妇人童子往田里送饭给耕者。 \n田畯（jùn）：农官名，又称农正或田大夫。\n春日：指二月。载：始。阳：温暖。\n仓庚：鸟名，就是黄莺。\n懿（yì）：深。\n微行：小径（桑间道）。\n爰（yuán）：语词，犹“曰”。柔桑：初生的桑叶。\n迟迟：天长的意思。\n蘩（fán）：菊科植物，即白蒿。古人用于祭祀，女子在嫁前有“教成之祭”。一说用蘩“沃”蚕子，则蚕易出，所以养蚕者需要它。其法未详。祁祁：众多（指采蘩者）。\n公子：指国君之子。殆及公子同归：是说怕被公子强迫带回家去。一说指怕被女公子带去陪嫁。\n萑（huán）苇：芦苇。八月萑苇长成，收割下来，可以做箔。\n蚕月：指三月。条桑：修剪桑树。\n斨（qiāng）：方孔的斧头。\n远扬：指长得太长而高扬的枝条。\n猗（yǐ）：《说文》《广雅》作“掎”，牵引。“掎桑”是用手拉着桑枝来采叶。南朝乐府诗《采桑度》云：“系条采春桑，采叶何纷纷”，似先用绳系桑然后拉着绳子采。女桑：小桑。\n鵙（jú）：鸟名，即伯劳。\n玄：是黑而赤的颜色。玄、黄指丝织品与麻织品的染色。\n朱：赤色。阳：鲜明。以上二句言染色有玄有黄有朱，而朱色尤为鲜明。\n葽（yāo）：植物名，今名远志。秀葽：言远志结实。\n蜩（tiáo）：蝉。\n陨萚（tuò）：落叶。\n貉：通“祃（mà）”。田猎者演习武事的礼叫祃祭或貉祭。于貉：言举行貉祭。《郑笺》：“于貉，往博貉以自为裘也。”\n同：聚合，言狩猎之前聚合众人。\n缵（zuǎn）：继续。武功：指田猎。\n豵（zòng）：一岁小猪，这里用来代表比较小的兽。私其豵：言小兽归猎者私有。\n豜（jiān）：三岁的猪，代表大兽。大兽献给公家。\n斯螽（zhōng）：虫名，蝗类，即蚱蜢、蚂蚱。旧说斯螽以两股相切发声，“动股”言其发出鸣声。\n莎鸡：虫名，今名纺织娘。振羽：言鼓翅发声。\n穹：穷尽，清除。窒：堵塞。穹窒：言将室内满塞的角落搬空，搬空了才便于熏鼠。\n向：朝北的窗户。墐：用泥涂抹。贫家门扇用柴竹编成，涂泥使它不通风。\n曰：《汉书》引作“聿”，语词。改岁：是说旧年将尽，新年快到。\n郁：植物名，唐棣之类。树高五六尺，果实像李子，赤色。薁（yù）：植物名，果实大如桂圆。一说为野葡萄。\n菽（shū）：豆的总名。\n剥（pū）：读为“扑”，打。\n春酒：冬天酿酒经春始成，叫做“春酒”。枣和稻都是酿酒的原料。\n介：祈求。眉寿：长寿，人老眉间有豪毛，叫秀眉，所以长寿称眉寿。\n壶：葫芦。\n叔：拾。苴（jū）：秋麻之籽，可以吃。\n樗（chū）：木名，臭椿。薪樗：言采樗木为薪。\n场：是打谷的场地。圃：是菜园。春夏做菜园的地方秋冬就做成场地，所以场圃连成一词。\n纳：收进谷仓。稼：古读如“故”。禾稼：谷类通称。\n重：即“种”，是先种后熟的谷。穋（lù）：即稑（lù），稑是后种先熟的谷。\n禾麻菽麦：这句的“禾”是专指一种谷，即今之小米。\n功：事。宫功：指建筑宫室，或指室内的事。\n索：动词，指制绳。綯（táo）：绳。索綯：是说打绳子。上两句言白天取茅草，夜晚打绳子。\n亟：急。乘屋：盖屋。茅和绳都是盖屋需用的东西。以上三句言宫功完毕后，急忙修理自己的屋子。因为播谷的工作又要开始了，不得不急。\n冲冲：古读如“沉”，凿冰之声。\n凌：是聚集的水。阴：指藏冰之处。\n蚤：读为“爪”，取。这句是说取冰。\n献羔祭韭（jiǔ）：这句是说用羔羊和韭菜祭祖。《礼记·月令》说仲春献羔开冰，四之日正是仲春。\n肃霜：犹“肃爽”，双声连语。这句是说九月天高气爽。\n涤场：清扫场地。这句是说十月农事完全结束，将场地打扫干净。一说“涤场”即“涤荡”，“十月涤荡”是说到了十月草木摇落无余。\n朋酒：两樽酒。这句连下句是说年终燕乐。\n跻（jī）：登。公堂：或指公共场所，不一定是国君的朝堂。\n称：举。兕（sì）觥（gōng）：角爵。古代用兽角做的酒器。\n万：大。无疆：无穷。以上三句言升堂举觞，祝君长寿。', poem_appreciation = '豳地在今陕西旬邑、彬县一带，公刘时代周之先民还是一个农业部落。《豳风·七月》反映了这个部落一年四季的劳动生活，涉及到衣食住行各个方面，它的作者当是部落中的成员，所以口吻酷肖，角度极准，从各个侧面展示了当时社会的风俗画，凡春耕、秋收、冬藏、采桑、染绩、缝衣、狩猎、建房、酿酒、劳役、宴飨，无所不写。\n\n　　诗从七月写起，按农事活动的顺序，以平铺直叙的手法，逐月展开各个画面。诗中使用的是周历。周历以夏历（今之农历，一称阴历）的十一月为正月，七月、八月、九月、十月以及四、五、六月，皆与夏历相同。“一之日”、“二之日”、“三之日”、“四之日”，即夏历的十一月、十二月、一月、二月。“蚕月”，即夏历的三月。戴震《毛郑诗考证》指出：周时虽改为周正（以农历十一月为正月岁首），但民间农事仍沿用夏历。\n\n　　首章以鸟瞰式的手法，概括了劳动者全年的生活，向读者展示了那个凄苦艰辛的岁月。同时它也为以后各章奠定了基调，提示了总纲。朱熹《诗集传》云：“此章前段言衣之始，后段言食之始。二章至五章，终前段之意。六章至八章，终后段之意。”在结构上如此安排，确是相当严谨。所谓“衣之始”、“食之始”，实际上指农业社会中耕与织两大主要事项。这两项是贯穿全篇的主线。首章是说九月里妇女“桑麻之事已毕，始可为衣”。十一月以后便进入朔风凛冽的冬天，农夫们连粗布衣衫也没有一件，怎么能度过年关，故而发出“何以卒岁”的哀叹。可是春天一到，他们又整理农具到田里耕作。老婆孩子则到田头送饭，田官见他们劳动很卖力，不由得面露喜色。民间诗人以粗线条勾勒了一个框架，当时社会生活的整体风貌已呈现在读者面前。以后各章便从各个侧面、各个局部进行较为细致的刻画。\n\n　　诗的二、三章情调逐渐昂扬，色调逐渐鲜明。明媚的春光照着田野，莺声呖呖。背着筐儿的妇女，结伴儿沿着田间小路去采桑。她们的劳动似乎很愉快，但心中不免怀有隐忧：“女心伤悲，殆及公子同归。”首章“田唆至喜”，只是以轻轻的一笔点到了当时社会的阶级关系，这里便慢慢地加以展开。“公子”，论者多谓豳公之子。豳公占有大批土地和农奴，他的儿子们对农家美貌女子也享有与其“同归”的特权。汉乐府《秋胡行》和《陌上桑》诗中似乎有这样的影子，虽然那是千年以后的事，但生活中的规律往往也会出现某些相似的地方。姑娘们的美貌使她们担心人身的不自由；姑娘们的灵巧和智慧，也使她们担心劳动果实为他人所占有：“八月载绩，载玄载黄，我朱孔阳，为公子裳。”她们织出五颜六色的丝绸，都成了公子身上的衣裳，正如宋人张俞的《蚕妇》诗所说：“遍身罗绮者，不是养蚕人。”\n\n　　四、五两章虽从“衣之始”一条线发展而来，但亦有发展变化。“秀葽”、“鸣蜩”，带有起兴之意，下文重点写狩猎。他们打下的狐狸，要“为公子裘”；他们打下的大猪，要贡献给豳公，自己只能留下小的吃。这里再一次描写了当时的阶级关系。五章着重写昆虫以反映季节的变化，由蟋蟀依人写到寒之将至，笔墨工细，绘影绘声，饶有诗意。《诗集传》云：“斯螽、莎鸡、蟋蟀，一物随时变化而异其名。动股，始跃而以股鸣也。振羽，能飞而以翅鸣也。”咏物之作，如此细腻，令人惊叹。“穹窒熏鼠”以下四句，写农家打扫室内，准备过冬，在结构上“亦以终首章前段御寒之意”。\n\n　　六、七、八章，承“食之始”一条线而来，好像一组连续的电影镜头，表现了农家朴素而安详的生活：六、七月里他们“食郁（郁李）及薁”、“亨（烹）葵（葵菜）及菽（豆子）”。七、八月里，他们打枣子，割葫芦。十月里收下稻谷，酿制春酒，给老人祝寿。可是粮食刚刚进仓，又得给老爷们营造公房，与上面所写的自己的居室的破烂简陋适成鲜明对比。“筑场圃”、“纳禾稼”，写一年农事的最后完成。正如《诗集传》引吕氏所云：“此章（第七章）终始农事，以极忧勤艰难之意。”\n\n　　到了最后一章，也就是第八章，诗人用较愉快的笔调描写了这个村落宴饮称觞的盛况。一般论者以为农夫既这么辛苦，上头又有田官监督、公子剥削，到了年终，不可能有条件有资格“跻彼公堂，称彼兕觥”。其实社会是复杂的，即使在封建社会的中期，农民年终时也相互邀饮，如宋代秦观《田居四首》所写：“田家重农隙，翁妪相邀迓。班坐酾酒醪，一行三四谢。”陆游《游山西村》诗也说：“莫笑田家腊酒浑，丰年留客足鸡豚。”《豳风·七月》所写上古社会的西周村落生活，农闲之时，举酒庆贺，也是情理中事。\n\n　　中国古代诗歌一向以抒情诗为主，叙事诗较少。这首诗却以叙事为主，在叙事中写景抒情，形象鲜明，诗意浓郁。通过诗中人物娓娓动听的叙述，又真实地展示了当时的劳动场面、生活图景和各种人物的面貌，以及农夫与公家的相互关系，构成了西周早期社会一幅男耕女织的风俗画。《诗经》的表现手法有赋、比、兴三种，这首诗正是采用赋体，“敷陈其事”、“随物赋形”，反映了生活的真实。', poem_tags = '诗经,长诗,叙事,妇女,奴隶' WHERE poem_title = '国风·豳风·七月' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '秋风送来了断续的寒砧声，在小庭深院中，听得格外真切。夜深了，月光和砧声穿进帘栊，更使人联想到征人在外，勾起了绵绵的离恨和相思。因而长夜不寐，愁思百结。', poem_notes = '砧（zhēn）：捣衣石。\n寒砧：寒夜捣帛声。古代秋来，家人捣帛为他乡游子准备寒衣。\n栊：窗户。', poem_appreciation = '这是一首本义词。白练是古代一种丝织品，其制作要经过在砧石上用木棒捶捣这道工序，而这工序一般都是由妇女操作的。这首词的词牌即因其内容以捣练为题材而得名。\n\n　　作者通过对一个失眠者夜听砧上捣练之声的描绘，写出了抒情主人公内心的焦躁烦恼。但作者却为这种忐忑不宁的心情安排了一个十分幽静寂寥、空虚冷漠的环境。头两句乍一看仿佛是重复的，后来汤显祖在《牡丹亭》里就写出“人立小庭深院”的句子，把“深院”和“小庭”基本上看成同义词。其实这两句似重复而并不重复。第一句是诉诸听觉，第二句是诉诸视觉。然而尽管耳在听目在看，却什么也没有听到和看到。这样，“静”和“空”这两个字，不仅在感受上给人以差别，而且也看出作者在斟酌用词时是颇费了一番心思的。至于“深院”，是写居住的人远离尘嚣；“小庭”则写所居之地只有一个空荡荡的小小天井，不仅幽静，而且空虚。头两句看似写景，实际是衬托出主人公内心的寂寞无聊。只有在这绝对安静的环境里，远处被断续风声吹来的砧上捣练之声才有可能被这小庭深院的主人听到。\n\n　　第三句是这首词的核心。自古以来，砧上捣衣或捣练的声音一直成为夫妇或情人彼此相思回忆的诗料；久而久之，也就成为诗词里的典故。比如李白在《子夜吴歌》的第三首里写道：“长安一片月，万户捣衣声。秋风吹不尽，总是玉关情。何日平胡虏，良人罢远征？”杜甫的一首题为《捣衣》的五律也说：“亦知戍不返，秋至拭清砧。已近苦寒月，况经长别心。宁辞捣衣倦，一寄塞垣深。用尽闺中力，君听空外音。”李杜两家所写，是从捣衣人的角度出发的。而李煜这首词却是从听砧声的人的角度来写的。这个听砧的人不管是男是女，总之是会因听到这种声音而引起相思离别之情的。不过，第三句虽连用两次“断续”字样，含义却不尽相同。一般地说，在砧上捣衣或捣练，总是有节奏的，因此一声与一声之间总有短暂的间歇，而这种断续的有节奏的捣练声并没有从头至尾一声不漏地送入小庭深院中来。这是因为风力时强时弱，风时有时无，这就使身居小庭深院中的听砧者有时听得到，有时听不到。正因为“风”有断续，才使得砧声时有时无，若断若续。这就把一种诉诸听觉的板滞沉闷的静态给写活了。下面两旬，明明是人因捣练的砧声搅乱了自己的万千思绪，因而心潮起伏，无法安眠；作者却偏偏翻转过来倒果为因，说人由于夜长无奈而睡不着觉，这才使砧声时断时续地达于耳畔。而且夜深了，砧声还在断断续续地响，是伴随着月光传入帘栊的。这就又把听觉和视觉相互结合起来，做到了声色交融——秋月的清光和捣练的音响合在一起，共同触动着这位“不寐”者的心弦。然而作者并没有绘声绘色，大事渲染，只是用单调的砧声和素朴的月光唤起了读者对一个孤独无眠者的同情。这正是李煜写词真正见功力的地方。\n\n　　前人评论李煜词的特点，都说他不假雕饰，纯用白描。其实李煜写词何尝不雕饰呢，只是洗尽铅华，摆脱了尘俗的浓妆艳抹，使人不觉其雕饰的痕迹而已。这首小词无论结构、布局、遣辞、造句，作者都经过了严密的构思和细致的安排，而给予读者的感受，却仿佛只是作者的自然流露。一个作家能于朴实无华之中体现匠心，才是真正的白描高手。', poem_tags = '宋词三百首,婉约,孤独' WHERE poem_title = '捣练子令·深院静' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '在南方，有一位美丽的女子，她的面容若桃花般芳艳，如李花般清丽。\n早晨她来到江北岸边游玩，夜晚她到萧湘的小岛中休憩。\n当世的风气轻视美丽的容颜，贝齿轻启的微笑为谁而发呢？\n转瞬间，岁月消逝，可是青春的美貌是难以永远存在的。', poem_notes = '南国：古代泛指江南一带。容华：容貌。　\n湘沚：湘水中的小洲。湘水在湖南，入洞庭湖。沚，水中小洲。朝游北岸，夕宿湘沚，是以湘水女神自喻，应取意于屈原《九歌》。此句一作“日夕宿湘沚”。　\n薄朱颜：不重视美貌的人，这里指不重视有才德的人。　\n发皓齿：指唱歌或说话，这里是指推荐、介绍。　\n俯仰：低头扬头之间，极言时间之短。　\n荣耀：花开绚艳的样子，这里指人的青春盛颜。久恃：久留，久待。', poem_tags = '古诗三百首,写人,感慨,怀才不遇' WHERE poem_title = '杂诗七首·其四' AND poem_author = '曹植';
UPDATE edu_poem SET poem_translation = '我的心追逐南去的云远逝了，\n身体却随着秋季由北向南飞回的大雁归来。\n故乡家里篱笆下栽种的菊花，\n今日又开了几朵呢？', poem_notes = '江总，南朝陈人。陈亡，入长安，仕于隋，后辞官南归，这首诗写于南归途中。\n岑参，盛唐边塞诗人。安史之乱中，长安沦陷，故有此诗。', poem_tags = '古诗三百首,重阳节,菊花,思乡' WHERE poem_title = '于长安归还扬州九月九日行薇山亭赋韵 / 长安九日诗' AND poem_author = '江总';
UPDATE edu_poem SET poem_translation = '一个人活在世上通常不满百岁，心中却老是记挂着千万年后的忧愁，这是何苦呢？\n既然老是埋怨白天是如此短暂，黑夜是如此漫长，那么何不拿着烛火，日夜不停地欢乐游玩呢？\n人生应当及时行乐才对啊！何必总要等到来年呢？\n整天不快乐的人，只想为子孙积攒财富的人，就显得格外愚蠢，不肖子孙也只会嗤笑祖先的不会享福！\n像王子乔那样成仙的人，恐怕难以再等到吧！', poem_notes = '昼短夜苦长二句：“秉”，执也。“秉烛游”，犹言作长夜之游。\n来兹：因为草生一年一次，所以训“兹”为“年”，这是引申义。“来兹”，就是“来年”。\n费：费用，指钱财。\n嗤：轻蔑的笑。\n仙人王子乔二句：“王子乔”，古代传说中著名的仙人之一。“期”，待也，指成仙之事不是一般人所能期待。\n说明：这首诗，和《东城高且长》《驱车上东门》两篇用意略同。诗中强调的是及时行乐的思想。', poem_appreciation = '思想意义\n\n　　从全诗来看，这首诗即以松快的旷达之语，对世间的两类追求者予以嘲讽。\n\n　　首先是吝啬聚财“惜费”者，生年不足百岁，却愚蠢到怀千岁忧，以“百年”、“千年”的荒谬对接，揭示那些活得吝啬的“惜费”者的可笑情态。\n\n　　“昼短苦夜长，何不秉烛游”！“游”者，文中的“游”与后文所提到的“为乐当及时”的“乐”都与常人理解的有异意，游及乐并不是那种酒肉池林，歌舞升平的放纵肉欲，是文人雅士的寄情山水，把酒言诗，忘却失意不得志之情殇的一种积极健康的享受生活之乐。这种乐也是建立在热爱生活基础之上，更是以旷达狂放之思，表现了人生毫无出路的痛苦。\n\n　　只要看一看文人稍有出路的建安时代，这种及时行乐的吟叹，很快又为悯伤民生疾苦、及时建功立业的慷慨之音所取代，就可以明白这一点。其实是对仰慕成仙者的嘲讽。但这种得遇神仙的期待，到了苦闷的汉末，也终于被发现只是一场空梦。\n\n艺术特点\n\n　　人生价值的怀疑，似乎常因生活的苦闷。在苦闷中看人生，许多传统的观念，都会在怀疑的目光中轰然倒塌。这首诗集以松快的旷达之语，给世间的两类追求者，兜头浇了一桶冷水。\n\n　　首先是对吝啬聚财的“惜费”者的嘲讽，它几乎占了全诗的主要篇幅。这类人正如《诗经·唐风》“山有枢”一诗所讥刺的：“子有衣裳，弗曳弗娄（穿裹着）；子有车马，弗驰弗驱。宛其死矣，他人是愉”——只管苦苦地聚敛财货，就不知道及时享受。他们所忧虑的，无非是子孙后代的生计。这在诗人看来，简直愚蠢可笑：“生年不满百，常怀千岁忧”——纵然人能活上百年，也只能为子孙怀忧百岁，这是连小孩都明白的常识；何况还未必活得了百年，偏偏想忧及“千岁”，真是愚不可及。开篇落笔，以“百年”、“千年”的荒谬对接，揭示那些活得吝啬的“惜费”者的可笑情态，真是妙不可言。接着两句更奇：“昼短苦夜长，何不秉烛游！”“游”者，放情游乐也。把生命的白昼，尽数沉浸在放情游乐之中，已够耸人听闻的了，诗人却还“苦”于白昼太“短”，竟异想天开，劝人把夜晚的卧息时间，也都用来行乐，真亏他想得出来。夜晚黑灯瞎火，就怕败了游兴。诗人却早备良策：那就干脆手持烛火而游！——把放情行乐之思，表述得如此赤裸而大言不惭，这不仅在汉代诗坛上，就是在整个古代诗歌史上，恐怕都算得上惊世骇俗之音了。至于那些孜孜追索于藏金窑银的守财奴，听了更要瞠目咋舌。这些是被后世诗论家叹为“奇情奇想，笔势峥嵘”的开篇四句（方东树《昭昧詹言》）。它们一反一正，把终生忧虑与放情游乐的人生态度，鲜明地对立起来。\n\n　　诗人似乎早就料到，鼓吹这样的放荡之思，必会遭到世俗的非议。也并非不想享受,只是他们常抱着“苦尽甘来”的哲学，把人生有限的享乐，推延到遥远的未来。诗人则断然否定这种哲学：想要行乐就得“及时”，不能总等待来年。诗中没有说为何不能等待来年，其弦外之音，却让《古诗十九首》的另一首点着了：“人生忽如寄，寿无金石固”——谁也不知道“来兹”不会有个三长两短，突然成了“潜寐黄泉下，千载永不寤”的“陈死人”（《古诗十九首·驱车上东门》）。那时再思享乐，已经晚了。这就是在诗人世间“及时”行乐的旷达之语后面，所包含着的许多人生的痛苦体验。从这一点看，“惜费”者的终日汲汲无欢，只想着为子孙攒点财物，便显得格外愚蠢了。因为他们生时的“惜费”，无非养育了一批游手好闲的子孙。当这些不肖子孙挥霍无度之际.不可能会感激祖上的积德。也许他们倒会在背底里，嗤笑祖先的不会享福。“愚者爱惜费，但为后世嗤”二句，正如方廷珪所说：“直以一杯冷水，浇财奴之背”（《文选集成》）。其嘲讽辞气之尖刻，确有对愚者的“唤醒醉梦”之力。\n\n　　全诗抒写至此，笔锋始终还都针对着“惜费”者。只是到了结尾，才突然“倒卷反掉”，指向了人世的另一类追求：仰慕成仙者。对于神仙的企羡，从秦始皇到汉武帝，都干过许多蠢事。就是汉代的平民，也津津乐道于王子乔被神秘道士接上嵩山、终于乘鹤成仙的传说。在汉乐府中，因此留下了“王子乔，参驾白鹿云中遨。下游来，王子乔”的热切呼唤。但这种得遇神仙的期待，到了苦闷的汉末，也终于被发现只是一场空梦（见《古诗十九首·驱车上东门》：“服食求神仙，多为药所误。不如饮美酒，被服纨与素”）。所以，对于那些还在做着这类“成仙”梦的人，诗人便无须多费笔墨，只是借着嘲讽“惜费”者的余势，顺手一击，便就收束：“仙人王子乔，难可与等期！”这结语在全诗似乎逸出了主旨，一下子岔到了“仙人”身上，但诗人之本意，其实还在“唤醒”那些“惜费”者，即朱筠《古诗十九首说》指出的：“仙不可学，愈知愚费之不可惜矣”。只轻轻一击，即使慕仙者为之颈凉，又照应了前文“为乐当及时”之意：收结也依然是旷达而巧妙的。\n\n　　这样一首以放浪之语抒写“及时行乐”的奇思奇情之作，似乎确可将许多人们的人生迷梦“唤醒”；有些研究者因此将这类诗作，视为汉代“人性觉醒”的标志。但仔细想来，“常怀千岁忧”的“惜费”者固然愚蠢；但要说人生的价值就在于及时满足一已的纵情享乐，恐怕也未必是一种清醒的人生态度。实际上，这种态度，大抵是对于汉末社会动荡不安、人命危浅的苦闷生活的无力抗议。从毫无出路的下层人来说，又不过是从许多迷梦（诸如“功业”、“名利”之类）中醒来后，所做的又一个迷梦而已——他们不可能真能过上“被服纨与素”、“何不秉烛游”的享乐生活。所以，与其说这类诗表现了“人性之觉醒”，不如说是以旷达狂放之思，表现了人生毫无出路的痛苦。只要看一看文人稍有出路的建安时代，这种及时行乐的吟叹，很快又为悯伤民生疾苦、及时建功立业的慷慨之音所取代，就可以明白这一点。', poem_tags = '古诗十九首,寓理,惜时' WHERE poem_title = '生年不满百' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '在秋风萧瑟，满眼凄凉的季节，一双相濡以沫的夫妻为生活所迫，不得不含怨辞别。在这令人肝肠寸断的时刻，两人眼含热泪，面面相视，想要向对方说点什么，可尚未开口已是泣不成声。心中早有千言万语，可是在此刻，因悲痛至极而无法诉说。分别后天各一方，相思之情能与谁人说，唯一能做的也只有天涯两地共赏一轮明月，寄托无尽的相思愁苦。', poem_notes = '古怨别：古人离别的怨情。\n飒飒：形容秋风吹的声音。\n相向：面对面。\n气先咽：因为伤心，气塞声断讲不出话来。\n心曲：心事。\n唯所思：（分别后）只有互相思念。', poem_tags = '秋天,离别,爱情' WHERE poem_title = '古怨别' AND poem_author = '孟郊';
UPDATE edu_poem SET poem_translation = '太史公说：《诗经》上有句话：“巍峨的高山可以仰望，宽广的大道可以循着前进。”我虽然不能到达那里，但是心中一直向往它。我读孔子的书，由推理可以知道他的为人。\n　　到了鲁国，看到孔子的祠堂、他的车子、衣服和礼器，许多儒生在他家里按时演习礼仪，我徘徊留恋，舍不得离开。\n　　天下的君王以及贤人是很多的，（他们大多是）当时的荣耀，死后就完了。\n　　孔子是一个平民，传到十几代，读书的人都尊崇他。从天子王侯，到全国研究六经的人，都以孔子的学说作为准则，孔子可以说是道德学问最高尚的人了！\n\n译文二\n　　太史公说：《诗经-小雅-车辖》中有这样的句子：“高山吗，人人都仰望着，大路吗，个个都可通行。”虽然不能人人都能登上那高山绝顶，踏上那大路坦途，但心总是向往着它。我读着孔子的书，便想见他的为人。到了鲁国，参观孔子的庙堂、孔子用过的车子、穿过的衣服以及祭祀器具，见到众儒生按时在他家里演习礼仪，我恭敬地徘徊留连，不肯离去。自古以来，天下的君王以及贤人太多了，一般都在当时荣显，死后也就完了。\n　　孔子是普通的百姓，传了十余代，学者仍然尊崇他。从天子、王侯起，中国讲说“六艺”的人，都以孔子作为判断是非的标准。孔子，可以说是最了不起的圣人了。\n\n译文三\n　　太史公说：《诗经》有这样的话：“巍峨的高山令人仰望，宽阔的大路让人行走。”\n　　尽管我不能回到孔子的时代，然而内心非常向往。我阅读孔氏的书籍，可以想见到他的为人。去到鲁地，观看仲尼的宗庙厅堂、车辆服装、礼乐器物，儒生们按时在孔子故居演习礼仪，我流连忘返以至留在那里无法离去。天下从君王直至贤人，是很多很多了，生前都荣耀一时，死后也就完。\n　　孔子是个平民，传世十几代，学者尊祟他。上起天子王侯，中原凡是讲习六经的都要以孔夫子为标准来判断是非，孔子可说是至高无上的圣人了！', poem_notes = '选自《史记·孔子世家》（中华书局1959年版）。《史记》一百三十篇，每篇最后都以“太史公曰”的形式，对所记的历史人物或事件加以评论，一般称为赞。赞，文体名。本文是《史记·孔子世家》的赞，是作者对孔子的评论。\n太史公：司马迁的官名，用以自称。\n高山仰止，景行行止：出自《诗经·小雅·车舝（xiá）》。仰，这里是仰慕、敬仰的意思。景行，大道。这里喻指高尚的品德。行，这里是效法的意思。止，句末语气助词，无意义。\n乡：通“向”。\n适：往。\n祗（zhī）回：相当于“低回”。流连，盘桓。祗，恭敬。有的版本作“低回”。\n布衣：没有官职的人。\n《六艺》：指六经，即《诗》《书》《礼》《乐》《易》《春秋》。\n折中：调和取证。', poem_tags = '古文观止' WHERE poem_title = '孔子世家赞' AND poem_author = '司马迁';
UPDATE edu_poem SET poem_tags = '豪放,登高,写景,长江,抒情' WHERE poem_title = '水调歌头·金山观月' AND poem_author = '张孝祥';
UPDATE edu_poem SET poem_translation = '闲下来围着水池看着水里的鱼自由地游动，正好遇到小童摆弄钓鱼船。一样地喜欢鱼但是心态却不一样，我来喂食你却来垂钓。', poem_notes = '闲步：散步。施食，喂食丢食。', poem_tags = '写景,抒情' WHERE poem_title = '观游鱼' AND poem_author = '白居易';
UPDATE edu_poem SET poem_tags = '议论' WHERE poem_title = '苦昼短' AND poem_author = '李贺';
UPDATE edu_poem SET poem_translation = '你栖身高枝之上才难以饱腹，悲鸣传恨无人理会白费其声。\n五更以后疏落之声几近断绝，满树碧绿依然如故毫不动情。\n我官职卑下像桃梗漂流不定，家园长期荒芜杂草早已长平。\n烦劳你的鸣叫让我能够警醒，我是一贫如洗全家水一样清。', poem_notes = '以：因。薄宦：指官职卑微。高难饱：古人认为蝉栖于高处，餐风饮露，故说“高难饱”。\n恨费声：因恨而连声悲鸣。费，徒然。\n五更（gēng）：中国古代把夜晚分成五个时段，用鼓打更报时，所以叫“五更”。疏欲断：指蝉声稀疏，接近断绝。\n碧：绿。\n薄宦：官职卑微。梗犹泛：典出《战国策·齐策》：土偶人对桃梗说：“今子东国之桃梗也，刻削子以为人，降雨下，淄水至，流子而去，则子漂漂者将何如耳。”后以梗泛比喻漂泊不定，孤苦无依。梗，指树木的枝条。\n故园：对往日家园的称呼，故乡。芜已平：荒草已经平齐没胫，覆盖田地。芜，荒草。平，指杂草长得齐平 。\n君：指蝉。警：提醒。\n亦：也。举家清：全家清贫。举，全。清，清贫，清高。', poem_appreciation = '评解 李商隐是唐代咏物诗的大家，他的咏物诗大多托物寓慨。这首诗表面写蝉，实际上是写自己。纪昀说：“前四句写蝉即自寓，后四句自写，仍归到蝉。隐显分合，章法可玩。”全诗层层深入，阐发主题。“高难饱”，鸣“徒劳”，声“欲断”，树“无情”，怨之深，恨之重，一目了然。“五更疏欲断，一树碧无情”被誉为“追魂之笔”，语出愤激却运思高妙、耐人寻味。后面就直接跳到自身的遭遇上来，直抒胸臆，足见其感情的强烈。最后却又自然而然地回到蝉身上，首尾圆融，意脉连贯。 钱钟书先生评论这首诗说：“蝉饥而哀鸣，树则漠然无动，油然自绿也。树无情而人有情，遂起同感。蝉栖树上，却恝置（犹淡忘）之；蝉鸣非为‘我’发，‘我’却谓其‘相警’，是蝉于我亦‘无情’，而我与之为有情也。错综细腻。”▲', poem_tags = '唐诗三百首,咏物' WHERE poem_title = '蝉' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '五寸的荷叶托着娇艳的荷花，荷叶密密的贴在水面，但这并不妨碍彩舟的荡漾。\n知道四五月间夏风微掠，这些荷叶荷花的高度依旧能恰巧把美人的腰遮住。', poem_notes = '薰风：和暖的风。指初夏时的东南风。', poem_tags = '咏物,荷花' WHERE poem_title = '荷花' AND poem_author = '石涛';
UPDATE edu_poem SET poem_translation = '绝代佳人与红艳牡丹相得益彰，美人与名花长使君王带笑观看。动人姿色似春风能消无限怨恨，在沉香亭北君王贵妃双依栏杆。', poem_notes = '清平调：一种歌的曲调，“平调、清调、瑟调”皆周房中之遗声。\n倾国：指绝代佳人\n得：使\n春风：代指君王', poem_tags = '唐诗三百首,写花,写人' WHERE poem_title = '清平调·名花倾国两相欢' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '微小的虚名薄利，有什么值得为之忙碌不停呢？名利得失之事自由因缘，得者未必强，失者未必弱。赶紧趁着闲散之身未老之时，抛开束缚，放纵自我，逍遥自在。即使只有一百年的时光，我也愿大醉它三万六千场。\n沉思算来，一生中有一半日子是被忧愁风雨干扰。又有什么必要一天到晚说长说短呢？不如面对这清风皓月，以苍苔为褥席，以高云为帷帐，宁静地生活。江南的生活多好，一千钟美酒，一曲优雅的《满庭芳》。', poem_notes = '满庭芳：词牌名。又名“锁阳台”，《清真集》入“中吕调”。双调九十五字，前片四平韵，后片五平韵。过片二字，亦有不叶韵连下为五言句者。 \n蜗角：蜗牛角。比喻极其微小。《庄子·则阳》谓在蜗之左角的触氏与右角的蛮氏，两簇常为争地而战。\n蝇头：本指小字，此取微小之义。\n些子：一点儿。\n“百年里”三句：语本李白《襄阳歌》：“百年三万六千日，一日须倾三百杯。”浑：整个儿，全部。\n“能几许”三句：意谓计算下来，一生中日子有一半是被忧愁风雨干扰。\n“苔茵”两句：以青苔为褥席铺展，把白云当帐幕高张。', poem_tags = '议论,讽刺,感叹,人生' WHERE poem_title = '满庭芳·蜗角虚名' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '鹅湖山下稻梁肥硕，丰收在望。牲畜圈里猪肥鸡壮，门扇半开。\n夕阳西沉，桑柘树林映照出长长的阴影。春社结束，家家搀扶着醉倒之人归来。', poem_notes = '社日：古代祭祀土神的日子，分为春社和秋社。在社日到来时，民众集会竞技，进行各种类型的作社表演，并集体欢宴，不但表达他们对减少自然灾害、获得丰收的良好祝愿，同时也借以开展娱乐。\n鹅湖：在江西省铅山县，一年两稻，故方仲春社日，稻梁已肥。稻梁肥：田里庄稼长得很好，丰收在望。粱：古代对粟的优良品种的通称。\n“豚栅”句：猪归圈，鸡归巢，家家户户的门还关着，村民们祭社聚宴还没回来。豚栅（tún zhà），小猪猪圈。鸡栖（qī），鸡舍。对，相对。扉，门。\n桑柘（zhè）：桑树和柘树，这两种树的叶子均可用来养蚕。影斜：树影倾斜，太阳偏西。春社散：春设的聚宴已经散了。\n醉人：喝醉酒的人。', poem_tags = '节日,农村,生活' WHERE poem_title = '社日' AND poem_author = '王驾';
UPDATE edu_poem SET poem_translation = '新春，我穿着白夹衣怅然地卧床；\n幽会的白门冷落了，我心中惘然。\n隔着雨丝凝视红楼，我倍觉冷寂；\n珠箔般雨滴飘打灯笼，独自归返。\n你在远路，到春晚应更悲凄伤感？\n只有残宵能梦中聚首，依稀空泛。\n耳环情书已备好，怎么才能送达；\n只寄希望于万里长空，飞来鸿雁。\n\n直译\n“怅卧新春白袷衣，白门寥落意多违。”新春时节，我穿着白夹衣，怅然地卧在床上；白门寂寞，令我心中万分感伤。\n“红楼隔雨相望冷，珠箔飘灯独自归。”隔着蒙蒙细雨凝视着那座红楼，只觉得凄冷茫茫，我只好顶着珠帘般的细雨，在依稀闪烁的灯光中黯然归来。\n“远路应悲春晼晚，残霄犹得梦依稀。”凄楚的暮春，遥远的路途，哪里可以寄托我的悲凄伤感？缠绵的思绪，化做空泛的梦，在残宵的梦中依稀与你相见。\n“玉铛缄札何由达，万里云罗一雁飞。”有玉珰一双作为信物，怎么样才可以送达；我只有寄希望于万里长空中，那一只刚刚飞来的鸿雁。', poem_notes = '白袷衣：即白夹衣，唐人以白衫为闲居便服。\n白门：指今江苏南京市。\n红楼：华美的楼房，多指女子的住处。\n珠箔：珠帘，此处比喻春雨细密。\n晼晚：夕阳西下的光景，此处还蕴涵年复一年、人老珠黄之意。\n玉珰：耳环。\n云罗：像螺纹般的云片。', poem_appreciation = '一个春雨绵绵的早晨，诗中的男主人公穿着白布夹衫，和衣怅卧。他的心中究竟隐藏着什么？究竟何以如此呢？诗在点明怅卧之后，用一句话作了概括的交待 ：“白门寥落意多违 。”据南朝民歌《杨叛儿》：“暂出白门前，杨柳可藏乌。欢作沉水香，侬作博山炉 。”白门当指男女欢会之所。过去的欢会处，今日寂寞冷落，不再看见对方的踪影。与所爱者分离的失意，便是他愁思百结地怅卧的原因。怅卧中，他的思绪浮动，回味着最后一次访见对方的情景：“红楼隔雨相望冷，珠箔飘灯独自归。”仍然是对方住过的那座熟悉的红楼，但是他没有勇气走进去，甚至没有勇气再靠近它一点，只是隔着雨凝视着。往日在他的感觉里，是那样亲切温存的红楼，如今是那样地凄寒。在这红楼前，他究竟站了多久，也许连自己都不清楚。他发现周围的街巷灯火已经亮了，雨从亮着灯光的窗口前飘过，恍如一道道珠帘。在这珠帘的闪烁中，他才迷蒙地沿着悠长而又寂寥的雨巷独自走回来。\n\n　　他是这样地茫然若失，所爱者的形影，始终在他的脑际萦回。“远路应悲春晼晚，残宵犹得梦依稀。”他想象着 ，在远方的那人也应为春之将暮而伤感吧？如今蓬山远隔，只有在残宵的短梦中依稀可以相会了。强烈的思念 ，促使他修下书札，侑以玉珰一双，作为寄书的信物 。这是奉献给对方的一颗痛苦的心，但路途遥远 ，障碍重重，纵有信使，又如何传递呢？“玉珰缄札何由达，万里云罗一雁飞 。”且看窗外的天空，阴云万里，纵有一雁传书，又能穿过这罗网般的云天么？\n\n　　以上是这首诗大致包含的意境。男主人公的处境、活动、心情，基本上是清楚的。读者所难于知道这种恋爱的具体对象和性质。据作品本身看，所爱的对方大约是由于某种不得已的原因，远离而去了。李商隐在他的组诗柳枝五首》序中便曾述及洛阳有一个女子属意于他，但不幸被“东诸候取去 ”，而铸成了遗憾事。《春雨》诗中推想对方“远路应悲春晼晚”，又感到当时的环境如“万里云罗 ”，可见这种恋爱或许也是与受到“东诸侯”之类权势者的阻离有关。不过，这终究只能是一种推测。\n\n　　李商隐在这首诗中，赋予爱情以优美动人的形象。诗借助于飘洒天空的春雨 ，融入主人公迷茫的心境、依稀的梦境，以及春晼晚、万里云罗等自然景象，烘托别离的寥落，思念的深挚，构成浑然一体的艺术境界 。“红楼隔雨相望冷，珠箔飘灯独自归”一联，前一句色彩（红）和感觉（冷）互相比照。红的色彩本来是温暖的，但隔雨怅望反觉其冷；后一句珠箔本来是明丽的，却出之于灯影前对雨帘的幻觉，极细微地写出主人公寥寂而又迷茫的心理状态。末联“玉珰缄札何由达，万里云罗一雁飞 ”，也富于象征色彩。特别有创造性地借助于自然景，把“锦书难托”的预感形象化了，并把忧郁怅惘的情绪与广阔的云天，融为一体。凡此，都成功地表现出了主人公的生活、处境和感情，情景、色调和气氛都令人久久难忘。这种真挚动人的感情和优美生动的形象结合在一起，构成一种艺术魅力，在它面前，人们是免不了要支付出自己的同情的。', poem_tags = '唐诗三百首,爱情,写雨' WHERE poem_title = '春雨' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '国子先生早上走进太学，召集学生们站立在学舍下面，教导他们说：“学业由于勤奋而专精，由于玩乐而荒废；德行由于独立思考而有所成就，由于因循随俗而败坏。当今圣君与贤臣相遇合，各种法律全部实施。除去凶恶奸邪之人，提拔优秀人才。具备一点优点的人全部被录取，拥有一种才艺的人没有不被任用的。选拔优秀人才，培养造就人才。只有才行不高的侥幸被选拔，绝无才行优秀者不蒙提举。诸位学生只要担心学业不能精进，不要担心主管部门官吏不够英明；只要担心德行不能有所成就，不要担心主管部门官吏不公正。”\n\n　　话没有说完，有人在行列里笑道：“先生在欺骗我们吧？我侍奉先生，到现在已经很多年了。先生嘴里不断地诵读六经的文章，两手不停地翻阅着诸子百家的书籍。对史书类典籍必定总结掌握其纲要，对论说类典籍必定探寻其深奥隐微之意。广泛学习，务求有所收获，不论是无关紧要的，还是意义重大的都不舍弃；夜以继日地学习，常常终年劳累。先生的学习可以说勤奋了。\n\n　　抵制、批驳异端邪说，排斥佛教与道家的学说，弥补儒学的缺漏，阐发精深微妙的义理。探寻那些久已失传的古代儒家学说，独自广泛地钻研和继承它们。指导异端学说就像防堵纵横奔流的各条川河，引导它们东注大海；挽救儒家学说就像挽回已经倒下的宏大波澜。先生您对于儒家，可以说是有功劳了。\n\n　　心神沉浸在古代典籍的书香里，仔细地品尝咀嚼其中精华，写起文章来，书卷堆满了家屋。向上效法法虞、夏时代的典章，深远博大得无边无际；周代的诰书和殷代的《盘庚》，多么艰涩拗口难读；《春秋》的语言精练准确，《左传》的文辞铺张夸饰；《易经》变化奇妙而有法则，《诗经》思想端正而辞采华美；往下一直到《庄子》、《离骚》，《史记》；扬雄、司马相如的创作，同样巧妙但曲调各异。先生的文章可以说是内容宏大而外表气势奔放，波澜壮阔。\n\n　　先生少年时代就开始懂得学习，敢于实践，长大之后精通礼法，举止行为都合适得体。先生的做人，可以说是完美的了。\n\n　　可是在朝廷上不能被人们信任，在私下里得不到朋友的帮助。进退两难，一举一动都受到指责。刚当上御史就被贬到南方边远地区。做了三年博士，职务闲散表现不出治理的成绩。您的命运与仇敌相合，不时遭受失败。冬天气候还算暖和的日子里，您的儿女们哭着喊冷；年成丰收而您的夫人却仍为食粮不足而啼说饥饿。您自己的头顶秃了，牙齿缺了，这样一直到死，有什么好处呢？不知道想想这些，倒反而来教导别人干什么呢？”\n\n　　国子先生说：“唉，你到前面来！要知道那些大的木材做屋梁，小的木材做瓦椽，做斗栱，短椽的，做门臼、门橛、门闩、门柱的，都量材使用，各适其宜而建成房屋，这是工匠的技巧啊。贵重的地榆、朱砂，天麻、龙芝，车前草、马屁菌，坏鼓的皮，全都收集，储藏齐备，等到需用的时候就没有遗缺的，这是医师的高明之处啊。提拔人材，公正贤明，选用人才，态度公正。灵巧的人和拙笨的人都得引进，有的人谦和而成为美好，有的人豪放而成为杰出，比较各人的短处，衡量各人长处，按照他们的才能品格分配适当的职务，这是宰相的方法啊！从前孟轲爱好辩论，孔子之道得以阐明，他游历的车迹周遍天下，最后在奔走中老去。荀况恪守正道，发扬光大宏伟的理论，因为逃避谗言到了楚国，被废黜而死在兰陵。这两位大儒，说出话来成为经典，一举一动成为法则，远远超越常人，德行功业足以载入圣人之行列，可是他们在世上的遭遇是怎样呢？现在你们的先生学习虽然勤劳却不能顺手道统，言论虽然不少却不切合要旨，文章虽然写得出奇却无益于实用，行为虽然有修养却并没有突出于一般人的表现，尚且每月浪费国家的俸钱，每年消耗仓库里的粮食；儿子不懂得耕地，妻子不懂得织布；出门乘着车马，后面跟着仆人，安安稳稳地坐着吃饭。局局促促地按常规行事，眼光狭窄地在旧书里盗窃陈言，东抄西袭。然而圣明的君主不加处罚，也没有为宰相大臣所斥逐，难道不幸运么？有所举动就遭到毁谤，名誉也跟着大了起来。被放置在闲散的位置上，实在是恰如其份的。至于度量财物的有无，计较品级的高低，忘记了自己有多大才能、多少份量和什么相称，指摘官长上司的缺点，这就等于所说的责问工匠的为什么不用小木桩做柱子，批评医师的用菖蒲延年益寿，却想引进他的猪苓啊！（顾易生）', poem_notes = '国子先生：韩愈自称，当时他任国子博士。唐朝时，国子监是设在京都的最高学府，下面有国子学、太学等七学，各学置博士为教授官。国子学是为高级官员子弟而设的。太学：这里指国子监。唐朝国子监相当于汉朝的太学，古时对官署的称呼常有沿用前代旧称的习惯。\n嬉：戏乐，游玩。随：因循随俗。治具：治理的工具，主要指法令。《史记·酷吏列传》：“法令者，治之具。”毕：全部。张：指建立、确立。\n畯：通“俊”，才智出众。\n率：都。庸：通“用”，采用、录用。\n爬罗剔抉：意指仔细搜罗人才。爬罗：爬梳搜罗。剔抉：剔除挑选。刮垢磨光：刮去污垢，磨出光亮；意指精心造就人才。\n有司：负有专责的部门及其官吏。\n六艺：指儒家六经，即《诗》、《书》、《礼》、《乐》、《易》、《春秋》六部儒家经典。百家之编：指儒家经典以外各学派的著作。《汉书·艺文志》把儒家经典列入《六艺略》中，另外在《诸子略》中著录先秦至汉初各学派的著作：“凡诸子百八十九家，四千三百二十四篇。”春秋战国时期，各种学派兴起，著书立说，故有“百家争鸣”之称。\n纂：编集。纂言者，指言论集、理论著作。\n膏油：油脂，指灯烛。晷（guǐ轨）：日影。恒：经常。兀（wù误）兀：辛勤不懈的样子。穷：终、尽。\n异端：儒家称儒家以外的学说、学派为异端。《论语·为政》：“攻乎异端，斯害也已。”朱熹集注：“异端，非圣人之道，而别为一端，如杨、墨是也。”焦循补疏：“异端者，各为一端，彼此互异。”攘（rǎng壤）：排除。老：老子，道家的创始人，这里借指道家。\n苴（jū居）：鞋底中垫的草，这里作动词用，是填补的意思。罅（xià下）：裂缝。皇：大。幽：深。眇：微小。\n绪：前人留下的事业，这里指儒家的道统。韩愈《原道》认为，儒家之道从尧舜传到孔子、孟轲，以后就失传了，而他以继承这个传统自居。\n英、华：都是花的意思，这里指文章中的精华。\n姚：姒（sì四）：相传虞舜姓姚，夏禹姓姒。周诰：《尚书·周书》中有《大诰》、《康诰》、《酒诰》、《召诰》、《洛诰》等篇。诰是古代一种训诫勉励的文告。殷《盘》、《尚书》的《商诰》中有《盘庚》上、中、下三篇。佶屈：屈曲。聱牙：形容不顺口。《春秋》：鲁国史书，记载鲁隐公元年（前）到鲁哀公十四年（前）间史事，相传经孔子整理删定，叙述简约而精确，往往一个字中寓有褒贬（表扬和批评）的意思。《左氏》：指《春秋左氏传》，简称《左传》。相传鲁史官左丘明作，是解释《春秋》的著作，其铺叙详赡，富有文采，颇有夸张之处。《易》：《易经》，古代占卜用书，相传周人所撰。通过八卦的变化来推算自然和人事规律。《诗》：《诗经》，我国最早的一部诗歌总集，保存西周及春秋前期诗歌三百零五篇。逮：及、到。《庄》：《庄子》，战国时思想家庄周的著作。《骚》：《离骚》。战国时大诗人屈原的长诗。太史：指汉代司马迁，曾任太史令，也称太史公，著《史记》。子云：汉代文学家扬雄，字子云。相如：汉代辞赋家司马相如。\n见信、见助：被信任、被帮助。“见”在动词前表示被动。\n跋（bá拔）：踩。踬（zhì至）：绊。语出《诗经·豳风·狼跋》：“狼跋其胡，载疐其尾。”意思说，狼向前走就踩着颔下的悬肉（胡），后退就绊倒在尾巴上。形容进退都有困难。辄：常常。\n窜：窜逐，贬谪。南夷：韩愈于贞元十九年（）授四门博士，次年转监察御史，冬，上书论宫市之弊，触怒德宗，被贬为连州阳山令。阳山在今广东，故称南夷。\n三年博士：韩愈在宪宗元和元年（）六月至四年任国子博士。一说“三年”当作“三为”。韩愈此文为第三次博士时所作（元和七年二月至八年三月）。冗（rǒng茸）：闲散。见：通“现”。表现，显露。\n几时：不时，不一定什么时候，也即随时。为：语助词，表示疑问、反诘。\n吁（xū虚）：叹词。\n杗（máng忙）：屋梁：桷（jué觉）：屋椽。欂栌（bólú博卢）：斗栱，柱顶上承托栋梁的方木。侏（zhū朱）儒：梁上短柱。椳（wēi威）：门枢臼。闑（niè聂）：门中央所竖的短木，在两扇门相交处。扂（diàn店）：门闩之类。楔（xiè屑）：门两旁长木柱。\n玉札：地榆。丹砂：朱砂。赤箭：天麻。青兰：龙兰。以上四种都是名贵药材。牛溲：牛尿，一说为车前草。马勃：马屁菌。以上两种及“败鼓之皮”都是贱价药材。\n纡（yū迂）馀：委婉从容的样子。妍：美。卓荦（luò落）：突出，超群出众。校（jiào较）：比较。\n孟轲好辩：《孟子·滕文公下》载：孟子有好辩的名声，他说：予岂好辩哉！予不得已也。”意思说：自己因为捍卫圣道，不得不展开辩论。辙（zhé哲）：车轮痕迹。\n荀卿：即荀况，战国后期时儒家大师，时人尊称为卿。曾在齐国做祭酒，被人谗毁，逃到楚国。楚国春申君任他做兰陵（今山东枣庄）令。春申君死后，他也被废，死在兰陵，著有《荀子》。\n离、绝：都是超越的意思。伦、类：都是“类”的意思，指一般人。\n繇：通“由”。\n靡：浪费，消耗。廪（lǐn凛）：粮仓。\n踵（zhǒng肿）：脚后跟，这里是跟随的意思。促促：拘谨局促的样子。一说当作“役役”，指劳苦。窥：从小孔、缝隙或隐僻处察看。陈编：古旧的书籍。\n财贿：财物，这里指俸禄。班资：等级、资格。亡：通“无”。\n庳（bēi卑）：通“卑”，低。前人：指职位在自己前列的人。\n瑕（xiá侠）：玉石上的斑点。\n疵（cī雌）：病。瑕疵，比喻人的缺点。如上文所说“不公”、“不明”。\n杙（yì亦）：小木桩。楹（yíng盈）：柱子。訾（zǐ紫）：毁谤非议。\n昌阳：昌蒲。药材名，相传久服可以长寿。\n豨（xī希）苓：又名猪苓，利尿药。这句意思说：自己小材不宜大用，不应计较待遇的多少、高低，更不该埋怨主管官员的任使有什么问题。', poem_appreciation = '解析 　　本文是元和七、八年间韩愈任国子博士时所作，假托向学生训话，勉励他们在学业、德行方面取得进步，学生提出质问，他再进行解释，故名“进学解”，借以抒发自己怀才不遇、仕途蹭蹬的牢骚。文中通过学生之口，形象地突出了自己学习、捍卫儒道以及从事文章写作的努力与成就，有力地衬托了遭遇的不平；而针锋相对的解释，表面心平气和，字里行间却充满了郁勃的感情，也反映了对社会的批评。按本文“业精于勤，荒于嬉；行成于思，毁于随”等语，凝聚着作者治学、修德的经验结晶；从“沉浸醲郁”到“同工异曲”一段，生动表现出他对前人文学艺术特点兼收并蓄的态度。韩愈作为散文家，也很推重汉代扬雄的辞赋。本文的写作即有所借鉴于扬雄的《解嘲》、《解难》等篇，辞采丰富，音节铿锵、对偶工切，允属赋体，然而气势奔放，语言流畅，摆脱了汉赋、骈文中常有的艰涩呆板，堆砌辞藻等缺点。林纾所谓“浓淡疏密相间，错而成文，骨力仍是散文”，故应说是韩愈特创的散文赋，为杜牧的《阿房宫赋》、苏轼的《赤壁赋》的前驱。文中有许多创造性的语句，后代沿用为成语。 ▲', poem_tags = '古文观止,劝学,抒怀,怀才不遇' WHERE poem_title = '进学解' AND poem_author = '韩愈';
UPDATE edu_poem SET poem_translation = '好似春天的云彩那样浓厚，又好似薄烟轻淡，绿树的长短影子映在江面上。\n夕阳斜下，不禁推开船篷坐下，富春江山水一片翠色似乎涌上了船头。', poem_notes = '这首绝句写诗人由富春至严陵旅行途中所见。富春，此指富春江，是浙江钱塘江的一部分。严陵，此指富春山。同题二首，这是其二。\n参差（cēn cī）：长短、高低、大小不齐。\n推篷：拉开船篷。', poem_tags = '古诗三百首,写景' WHERE poem_title = '富春至严陵山水甚佳' AND poem_author = '纪昀';
UPDATE edu_poem SET poem_translation = '高耸的群峰寒气逼人，一座佛寺屹立在山顶。\n疏疏的树木漏下几点星光，月亮迎着行云匆匆前行。\n高山绝顶来人稀少，苍松在林中犹如鹤立鸡群。\n一位年过八十的老僧，从未听说过世间所发生的事情。', poem_notes = '众岫：群山。岫：峰峦。\n精庐：这里指佛寺。\n流星透疏木：写出了从疏落的树枝空隙之间，看见夜空的流星划过的景象。\n走月逆行云：写出了月亮之侧云朵漂移，云行而反似月走，云与月看似逆向而行的画面。', poem_tags = '寺庙,写景,抒情' WHERE poem_title = '宿山寺' AND poem_author = '贾岛';
UPDATE edu_poem SET poem_translation = '我们两人在盛开的山花丛中对饮，一杯又一杯，真是乐开怀。\n我喝醉想要睡觉您可自行离开，如果余兴未尽，明天早晨抱着琴再来。', poem_notes = '幽人：幽隐之人；隐士。此指隐逸的高人。《易·履》：“履道坦坦，幽人贞吉。”对酌：相对饮酒。\n“我醉”句：此用陶渊明的典故。《宋书·陶渊明传》记载：陶渊明不懂音乐，但是家里收藏了一把没有琴弦的古琴，每当喝酒的时候就抚摸古琴，对来访者无论贵贱，有酒就摆出共饮，如果陶渊明先醉，便对客人说：“我醉欲眠卿可去。”', poem_appreciation = '李白饮酒诗特多兴会淋漓之作。此诗开篇就写当筵情景。“山中”，对李白来说，是“别有天地非人间”的；盛开的“山花”更增添了环境的幽美，而且眼前不是“独酌无相亲”，而是“两人对酌”，对酌者又是意气相投的“幽人”（隐居的高士）。此情此境，事事称心如意，于是乎“一杯一杯复一杯”地开怀畅饮了。次句接连重复三次“一杯”，采用词语的重复，不但极写饮酒之多，而且极写快意之至。读者仿佛看到那痛饮狂歌的情景，听到“将进酒，杯莫停”（《将进酒》）那样兴高采烈的劝酒的声音。由于贪杯，诗人许是酩酊大醉了，玉山将崩，于是打发朋友先走。“我醉欲眠卿且去”，话很直率，却活画出饮者酒酣耳热的情态，也表现出对酌的双方是“忘形到尔汝”的知交。尽管颓然醉倒，诗人还余兴未尽，还不忘招呼朋友“明朝有意抱琴来”呢。此诗表现了一种超凡脱俗的狂士与“幽人”间的感情，诗中那种随心所欲、恣情纵饮的神情，挥之即去、招则须来的声口，不拘礼节、自由随便的态度，在读者面前展现出一个高度个性化的艺术形象。\n\n　　诗的艺术表现也有独特之处。盛唐绝句已经律化，且多含蓄不露、回环婉曲之作，与古诗歌行全然不同。而此诗却不就声律，又词气飞扬，一开始就有一往无前不可羁勒之势，纯是歌行作风。惟其如此，才将那种极快意之情表达得酣畅淋漓。这与通常的绝句不同，但它又不违乎绝句艺术的法则，即虽豪放却非一味发露，仍有波澜，有曲折，或者说直中有曲意。诗前二句极写痛饮之际，三句忽然一转说到醉。从两人对酌到请卿自便，是诗情的一顿宕；在遣“卿且去”之际，末句又婉订后约，相邀改日再饮，又是一顿宕。如此便造成擒纵之致，所以能于写真率的举止谈吐中，将一种深情曲曲表达出来，自然有味。此诗直在全写眼前景口头语，曲在内含的情意和心思，既有信口而出、率然天真的妙处，又不一泻无余，故能令人玩味，令人神远。\n\n　　此诗的语言特点，在口语化的同时不失其为经过提炼的文学语言，隽永有味。如“我醉欲眠卿且去”二句明白如话，却是化用一个故实。《宋书·隐逸传》：“（陶）潜不解音声，而畜素琴一张，无弦，每有酒适，辄抚弄以寄其意。贵贱造之者，有酒辄设。潜若先醉，便语客：‘我醉欲眠，卿可去’，其真率如此。”此诗第三句几乎用陶潜的原话，正表现出一种真率脱略的风度。而四句的“抱琴来”，也不是着意于声乐的享受，而重在“抚弄以寄其意”、以尽其兴，这从其出典可以会出。\n\n　　古典诗词，是通向美的桥梁，是人生境界，是生命的沉醉。闲读诗词，是心灵的旅行，地图由汉字组成。趣味念歌诗。\n\n　　品味古典诗词的意境之美，感悟诗人的人生故事。今天欣赏的是唐代诗人李白的一首绝句《山中与幽人对酌》。\n\n　　两人对酌山花开，一杯一杯复一杯。我醉欲眠卿且去，明朝有意抱琴来。\n\n　　在山花丛中，你我相对饮酒，喝了一杯一杯又一杯。我喝醉想要去睡，你可暂且离开， 　如果有意明天抱琴再来。\n\n　　《山中与幽人对酌》是唐代伟大诗人李白的一首七言绝句。诗表现了诗人李白和幽居朋友随心所欲、不拘礼节的人生态度，展现出一个超凡脱俗的艺术形象。\n\n　　幽人是指隐居的高人。\n\n　　两人对酌山花开，一杯一杯复一杯。诗的一开头就点明了诗人李白与朋友喝酒的地点——山中。对李白来说，山中是“别有天地非人间”的所在。盛开的“山花”更加增添了两人喝酒的气氛。此情此境，称心如意，就“一杯一杯复一杯”开怀畅饮。一杯一杯复一杯，接连重复三次“一杯”，不但写饮酒之多，而且写快乐的程度。\n\n　　我醉欲眠卿且去，明朝有意抱琴来。由于贪杯，诗人李白的朋友喝得大醉，就告诉李白“我已经喝醉，想要睡了，你回去吧！明天你若还觉得有意的话，就请顺便抱只琴来！”“我醉欲眠卿且去”的典故出自晋代伟大诗人陶渊明。《宋书》记载，陶渊明不懂音乐，但是家里收藏了一把没有琴弦的古琴，每当喝酒的时候就抚摸古琴，醉了就和客人说“我醉欲眠卿可去”。我醉欲眠卿且去，几乎用陶潜的原话，表现出一种天真超脱的风度。唐代伟大诗人李白的《山中与幽人对酌》，在艺术表现上也有独特的所在。盛唐时期，绝句已经格律化。而李白的《山中与幽人对酌》却不迁就声音格律，语言上又有飞扬的气魄，有古代歌行的风格。', poem_tags = '生活,饮酒' WHERE poem_title = '山中与幽人对酌' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '梅子落地纷纷，树上还留七成。有心求我的小伙子，请不要耽误良辰。\n梅子落地纷纷，枝头只剩三成。有心求我的小伙子，到今儿切莫再等。\n梅子纷纷落地，收拾要用簸箕。有心求我的小伙子，快开口莫再迟疑。', poem_notes = '摽（biào）：一说坠落，一说掷、抛。有：语助词。\n七：一说非实数，古人以七到十表示多，三以下表示少。或七成，即树上未落的梅子还有七成。\n庶：众多。士：未婚男子。\n迨（dài）：及，趁。吉：好日子。\n今：现 在。\n顷筐：斜口浅筐，犹今之簸箕。塈（ jì或qì）：一说取，一说给。\n谓：一说聚会；一说开口说话；一说归，嫁。', poem_appreciation = '这是一首委婉而大胆的求爱诗。\n\n　　此篇的诗旨、诗艺和风俗背景，前人基本约言点出。《毛诗序》曰：“《摽有梅》，男女及时也。召南之国，被文王之化，男女得以及时也。”“男女及时”四字，已申明诗旨；后数语乃经师附会，应当略去。《周礼·媒氏》曰：“仲春之月，令会男女。于是时也，奔者不禁。若无故而不用令者，罚之。司男女之无夫家者而会之。”明白了先民的这一婚恋习俗，对这首情急大胆的求爱诗，就不难理解了。陈奂则对此篇巧妙的兴比之意作了简明的阐释：“梅由盛而衰，犹男女之年齿也。梅、媒声同，故诗人见梅而起兴”（《诗毛氏传疏》）。龚橙《诗本义》说“《摽有梅》，急婿也。”一个“急”字，抓住了此篇的情感基调，也揭示了全诗的旋律节奏。\n\n　　全诗三章，“庶士”三见。“庶”者，众多之意；“庶士”，意谓众多的小伙子。可见这位姑娘尚无意中人。她是在向整个男性世界寻觅、催促，呼唤爱情。青春无价，然流光易逝。“真正的青春，贞洁的妙龄的青春，周身充满了新鲜的血液、体态轻盈而不可侵犯的青春，这个时期只有几个月”（《罗丹艺术论·女性美》）。如今梅子黄熟，嫁期将尽，仍夫婿无觅，不能不令人情急意迫。青春流逝，以落梅为比。“其实七兮”、“其实三兮”、“顷筐塈之”，由繁茂而衰落；这也正一遍遍在提醒“庶士”：“花枝堪折直须折，莫待无花空折枝。”唐无名氏《金缕曲》之忧心“无花空折枝”，似乎深有《摽有梅》之遗意。\n\n　　从抒情主人公的主观心态看，“急”就急在青春流逝而夫婿无觅。从诗篇的艺术结构看，“急”就急在三章复唱而一步紧逼一步。重章复唱，是《诗经》基本结构。但从诗意的表达看，有两种不同的形态，即重章之易辞申意和重章之循序渐进。《摽有梅》属于重章之循序渐进。三章重唱，却一层紧逼一层，生动有力地表现了主人公情急意迫的心理过程。首章“迨其吉兮”，尚有从容相待之意；次章“迨其今兮”，已见敦促的焦急之情；至末章“迨其谓之”，可谓真情毕露，迫不及待了。三复之下，闻声如见人。\n\n　　珍惜青春，渴望爱情，是中国诗歌的母题之一。《摽有梅》作为春思求爱诗之祖，其原型意义在于建构了一种抒情模式：以花木盛衰比青春流逝，由感慨青春易逝而追求婚恋及时。\n\n　　《摽有梅》作为先民的首唱之作，质朴而清新，明朗而深情。', poem_tags = '诗经,抒情,民谣' WHERE poem_title = '摽有梅' AND poem_author = '佚名';
UPDATE edu_poem SET poem_tags = '怀人,友人,愁绪' WHERE poem_title = '采桑子·明月多情应笑我' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '译文 靠近水边的楼台（因为没有树木的遮挡），能先看到月亮的投影；而迎着阳光的花木，（光照自然好得多，所以发芽就早），最容易形成春天的景象。', poem_appreciation = '宋·俞文豹《清夜录》：“范文正公镇钱塘，兵官皆被荐，独巡检苏麟不见录，乃献诗云：‘近水楼台先得月，向阳花木易逢春。’”\n\n　　范仲淹是宋朝时的一位政治家、文学家，他学问很好，能诗能文。他写的《岳阳楼记》十分著名，那“先天下之忧而忧，后天下之乐而乐”的名句至今仍为人们所传诵。\n\n　　范仲淹曾多次在朝廷担任要职，也曾镇守过地方。有一段时间，他镇守杭州。任职期间对手下的人都有所推荐，不少人得到了提拔或晋升，大家对他都很满意。\n\n　　这时候，有一个叫苏麟的官员，因担任巡检，常常在外，却一直没有得到提拔。当他见到自己周围的同事，无论职位比自己高的、低的都一个个得到了升迁，而自己却没人理睬，心里很不是滋味。他担心自己一定是被这位范大人遗忘了。怎么办呢？直接去找范大人吧，是去争官位，又不便说。不说吧，心里又很不平衡。为此，他心情非常沉重。一天，他终于想出了一个委婉的办法来，这就是写首诗去向范大人请教，实际上去提醒他：千万别忘了自己！想到这里，苏麟高兴起来，他赶忙拿出纸认真地写了首诗，并将诗句呈给了范仲淹，很虚心地请他赐教。\n\n　　范仲淹读着苏麟的诗，很快就会意地笑了。他吟诵着诗中的“近水楼台先得月，向阳花木易为春”的诗句，完全懂得了苏麟的言外之意。是呀！怎么能把他忘了呢？很快，苏麟得到了提拔。\n\n　　苏麟的这首诗，因为只写了两句，所以称为“断句”。“易为春”，后来演变为“易逢春”、“早逢春”。', poem_tags = '哲理' WHERE poem_title = '断句' AND poem_author = '苏麟';
UPDATE edu_poem SET poem_translation = '凉风飕飕地从天边刮起，你的心境怎样呢？令我惦念不已。\n我的书信不知何时你能收到？只恐江湖险恶，秋水多风浪。\n创作诗文最忌讳坦荡的命途，奸佞小人最希望好人犯错误。\n你与沉冤的屈子同命运，应投诗于汨罗江诉说冤屈与不平。', poem_notes = '天末：天的尽头。秦州地处边塞，如在天之尽头。当时李白因永王李璘案被流放夜郎，途中遇赦还至湖南。\n君子：指李白。\n鸿雁：喻指书信。古代有鸿雁传书的说法。\n江湖：喻指充满风波的路途。这是为李白的行程担忧之语。\n命：命运，时运。文章：这里泛指文学。这句意思是：有文才的人总是薄命遭忌。\n魑（chī）魅：鬼怪，这里指坏人或邪恶势力。过：过错，过失。这句指魑魅喜欢幸灾乐祸，说明李白被贬是被诬陷的。\n冤魂：指屈原。屈原被放逐，投汨罗江而死。杜甫深知李白从永王李璘实出于爱国，却蒙冤放逐，正和屈原一样。所以说，应和屈原一起诉说冤屈。\n汨（mì）罗：汨罗江，在湖南湘阴县东北。', poem_appreciation = '首句以秋风起兴，给全诗笼罩一片悲愁。诗人说：时值凉风乍起，景物萧疏，怅望云天，此意如何？只此两句，已觉人海沧茫，世路凶险，无限悲凉，凭空而起。次句不言自己心境，却反问远人：“君子意如何？”看似不经意的寒暄，而于许多话不知应从何说起时，用这不经意语，反表现出最关切的心情。这是返朴归真的高度概括，言浅情深，意象悠远。以杜甫论，自身沦落，本不足虑，而才如远人，罹此凶险，定知其意之难平，远过于自己，含有“与君同命，而君更苦”之意。此无边揣想之辞，更见诗人想念之殷。代人着想，“怀”之深也。挚友遇赦，急盼音讯，故问“鸿雁几时到”；潇湘洞庭，风波险阻，因虑“江湖秋水多”。李慈铭曰：“楚天实多恨之乡，秋水乃怀人之物。”悠悠远隔，望消息而不可得；茫茫江湖，唯寄语以祈珍摄。然而鸿雁不到，江湖多险，觉一种苍茫惆怅之感，袭人心灵。\n\n　　对友人深沉的怀念，进而发为对其身世的同情。“文章憎命达”，意谓文才出众者总是命途多舛，语极悲愤，有“怅望千秋一洒泪”之痛：“魑魅喜人过”，隐喻李白长流夜郎，是遭人诬陷。此二句议论中带情韵，用比中含哲理，意味深长，有极为感人的艺术力量，是传诵千古的名句。高步瀛引邵长蘅评：“一憎一喜，遂令文人无置身地。”这二句诗道出了自古以来才智之士的共同命运，是对无数历史事实的高度总结。\n\n　　此时李白流寓江湘，杜甫很自然地想到被谗放逐、自沉汨罗的爱国诗人屈原。李白的遭遇和这位千载冤魂，在身世遭遇上有某些相同点，所以诗人飞驰想象，遥想李白会向屈原的冤魂倾诉内心的愤懑：“应共冤魂语，投诗赠汨罗。”\n\n　　这一联虽系想象之词，但因诗人对屈原万分景仰，觉得他自沉殉国，虽死犹存；李白是亟思平定安史叛乱，一清中原，结果获罪远谪，虽遇赦而还，满腔的怨愤，自然会对前贤因秋风而寄意。这样，“应共冤魂语”一句，就很生动真实地表现了李白的内心活动。最后一句“投诗赠汨罗”，用一“赠”字，是想象屈原永存，他和李白千载同冤，斗酒诗百篇的李白，一定作诗相赠以寄情。这一“赠”字之妙，正如黄生所说：“不曰吊而曰赠，说得冤魂活现。”（《读杜诗说》）\n\n　　这首因秋风感兴而怀念友人的抒情诗，感情十分强烈，但不是奔腾浩荡、一泻千里地表达出来，感情的潮水千回百转，萦绕心际。吟诵全诗，如展读友人书信，充满殷切的思念、细微的关注和发自心灵深处的感情，反复咏叹，低回婉转，沉郁深微，实为古代抒情名作。', poem_tags = '唐诗三百首,写风,怀人' WHERE poem_title = '天末怀李白' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '瑶草多么碧绿，春天来到了武陵溪。溪水上有无数桃花，花的上面有黄鹂。我想要穿过花丛寻找出路，却走到了白云的深处，彩虹之巅展现浩气。只怕花深处，露水湿了衣服。\n坐着玉石，靠着玉枕，拿着金徽。被贬谪的仙人在哪里，没有人陪我用田螺杯喝酒。我为了寻找灵芝仙草，不为表面繁华，长叹为了什么。喝醉了手舞足蹈地下山，明月仿佛在驱逐我回家。', poem_notes = '水调歌头：词牌名，又名“元会曲”“台城游”“凯歌”“江南好”“花犯念奴”等。双调九十五字，平韵（宋代也有用仄声韵和平仄混用的）。相传隋炀帝开汴河自制《水调歌》，唐人演为大曲， “歌头”就是大曲中的开头部分。\n瑶草：仙草。\n武陵溪：指代幽美清净、远离尘嚣的地方。武陵：郡名，大致相当于今湖南常德。桃源的典故在后代诗词中又常和刘晨、阮肇入天台山遇仙女的传说混杂在一起。\n枝：一作“花”。\n倚：依。一作“欹”。\n金徽：金饰的琴徽，用来定琴声高下之节。这里指琴。\n谪仙：谪居人间的仙人。\n螺杯：用白色螺壳雕制而成的酒杯。\n灵芝：菌类植物。古人以为灵芝有驻颜不老及起死回生之功，故称仙草。', poem_tags = '宋词三百首,纪游,想象,抒怀' WHERE poem_title = '水调歌头·游览' AND poem_author = '黄庭坚';
UPDATE edu_poem SET poem_translation = '玄都观偌大庭院中有一半长满了青苔，原盛开的桃花已经荡然无存，只有菜花在开放。\n先前那些辛勤种桃的道士如今那里去了呢？前次因看题诗而被贬出长安的我——刘禹锡又回来了啊！', poem_notes = '公元815年（元和十年）玄都观赏花诗写后，刘禹锡又被贬出京，十四年后重被召回，写下此篇。\n百亩庭中：指玄都观百亩大的观园。苔：青苔。\n净尽：净，空无所有。 尽:完。\n种桃道士：暗指当初打击王叔文、贬斥刘禹锡的权贵们。', poem_appreciation = '该诗是《元和十年自朗州至京戏赠看花诸君子》的续篇。诗前有作者一篇小序。其文云：“余贞元二十一年为屯田员外郎时，此观未有花。是岁出牧连州（今广东省连县），寻贬朗州司马。居十年，召至京师。人人皆言，有道士手植仙桃满观，如红霞，遂有前篇，以志一时之事。旋又出牧。今十有四年，复为主客郎中，重游玄都观，荡然无复一树，惟兔葵、燕麦动摇于春风耳。因再题二十八字，以俟后游。时大和二年三月。”\n\n　　序文说得很清楚，诗人因写了看花诗讽刺权贵，再度被贬，一直过了十四年，才又被召回长安任职。在这十四年中，皇帝由宪宗、穆宗、敬宗而文宗，换了四个，人事变迁很大，但政治斗争仍在继续。作者写这首诗，是有意重提旧事，向打击他的权贵挑战，表示决不因为屡遭报复就屈服妥协。\n\n　　和《元和十年自朗州至京戏赠看花诸君子》一样，此诗仍用比体。从表面上看，它只是写玄都观中桃花之盛衰存亡。道观中非常宽阔的广场已经一半长满了青苔。经常有人迹的地方，青苔是长不起来的。百亩广场，半是青苔，说明其地已无人来游赏了。“如红霞”的满观桃花，“荡然无复一树”，而代替了它的，乃是不足以供观览的菜花。这两句写出一片荒凉的景色，并且是经过繁盛以后的荒凉。\n\n　　与《元和十年自朗州至京戏赠看花诸君子》之“玄都观里桃千树”，“无人不道看花回”，形成强烈的对照。下两句由花事之变迁，关合到自己之升进退，因此连着想到：不仅桃花无存，游人绝迹，就是那一位辛勤种桃的道士也不知所终，可是，上次看花题诗，因而被贬的刘禹锡现在倒又回到长安，并且重游旧地了。这一切，是不能预料的。言下有无穷的感慨。\n\n　　再就其所寄托的意思看，则以桃花比新贵，与《元和十年自朗州至京戏赠看花诸君子》相同。种桃道士则指打击当时革新运动的当权者。这些人，经过二十多年，有的死了，有的失势了，因而被他们提拔起来的新贵也就跟着改变了他们原有的煊赫声势，而让位于另外一些人，正如“桃花净尽菜花开”一样。而桃花之所以净尽，则正是“种桃道士归何处”的结果。\n\n　　诗人想的是：这，也就是俗话说的“树倒猢狲散”。而这时，我这个被排挤的人，却又回来了，难道是那些人所能预料到的吗？对于扼杀那次政治革新的政敌，诗人在这里投以轻蔑的嘲笑，从而显示了自己的不屈和乐观，显示了他将继续战斗下去。\n\n　　刘禹锡玄都观两诗，都是以比拟的方法，对当时的人物和事件加以讽刺，除了寄托的意思之外，仍然体现了一个独立而完整的意象。这种艺术手法是高妙的。', poem_tags = '游历,看花' WHERE poem_title = '再游玄都观' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_tags = '古诗三百首,传说,述志' WHERE poem_title = '酌贪泉' AND poem_author = '吴隐之';
UPDATE edu_poem SET poem_translation = '光亮皎洁小白马，吃我园中嫩豆苗。拴好缰绳绊住脚，就在我家过今朝。所说那位贤德人，请在这儿尽逍遥。\n光亮皎洁小白马，吃我园中嫩豆叶。拴好缰绳绊住脚，就在我家过今夜。所说那位贤德人，在此做客心意惬。\n光亮皎洁小白马，快速来到我的家。为公为侯多高贵，安逸享乐莫还家。悠闲自在别过分，不要避世图闲暇。\n光亮皎洁小白马，空旷山谷留身影。一束青草作饲料，那人品德似琼英。走后别忘把信捎，切莫疏远忘友情。', poem_notes = '皎皎：毛色洁白貌。\n场：菜园。\n絷（zhí）：用绳子绊住马足。维：拴马的缰绳，此处意为维系，用作动词。\n永：长。此处用如动词，延长。今朝：今天。\n伊人：那人，指白驹的主人。\n于焉：在这里。\n藿（huò）：豆叶。\n贲（bì）然：文饰，装饰得很好。思：语助词。\n尔：你，即“伊人”。公、侯：古爵位名，此处皆作动词，为公为侯之意。\n逸豫：安乐。无期：没有终期。\n慎：慎重。优游：悠闲自得。\n勉：“免”之假借字，打消之意。遁：避世。\n空谷：深谷。空，“穹”之假借。\n生刍（chú）：喂牲畜的青草。\n其人：亦即“伊人”。如玉：品德美好如玉。\n金玉：此处皆用作意动词，珍惜之意。\n遐（xiá）心：疏远之心。', poem_tags = '诗经,友情,写马' WHERE poem_title = '小雅·白驹' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '摆脱尘劳事不寻常，须下力气大干一场。\n不经过彻骨寒冷，哪有梅花扑鼻芳香。', poem_notes = '尘劳：尘念劳心。迥（jiǒng）脱：远离，指超脱。\n紧把：紧紧握住。', poem_tags = '梅花,励志,哲理' WHERE poem_title = '上堂开示颂' AND poem_author = '黄蘖禅师';
UPDATE edu_poem SET poem_translation = '荷花落尽，香气消散，荷叶凋零，深秋的西风拂动绿水，使人愁绪满怀。美好的人生年华不断消逝。与韶光一同憔悴的人，自然不忍去看（这满眼萧瑟的景象）。\n细雨绵绵，梦境中塞外风物缈远。（醒来）寒笙呜咽之声回荡在小楼中。（想起故人旧事），（她）含泪倚栏，怀抱无穷幽怨。', poem_notes = '摊破浣溪沙：词牌名。又名“添字浣溪沙”“山花子”“南唐浣溪沙”。双调四十八字，前阕三平韵，后阕两平韵，一韵到底。前后阕基本相同，只是前阕首句平脚押韵，后阕首句仄脚不押韵。后阕开始两句一般要求对仗。这是把四十二字的“浣溪沙”前后阕末句扩展成两句，所以叫“摊破浣溪沙”。\n菡萏：荷花的别称。\n西风愁起：西风从绿波之间起来。以花叶凋零，故曰“愁起“。\n鸡塞：亦作鸡禄山。这里泛指边塞。\n彻：大曲中的最后一遍。“吹彻“意谓吹到最后一曲。笙以吹久而含润，故云”寒“。玉笙寒：玉笙以铜质簧片发声，遇冷则音声不畅，需要加热，叫暖笙。', poem_appreciation = '李璟流传下来的词作不多，所传几首词中，最脍炙人口的，就是这首《摊破浣溪沙》（有些本子作《浣溪沙》）。\n\n　　词的上片着重写景。菡萏，荷花的别称。文字的语言是形象的，所以作者一上来就说：“菡萏香销翠叶残”。说“香”，点其“味”；说“翠”，重其“色”。此时味去叶枯确然使人惆怅。西风，秋风之谓也。绿波，写的是莹莹秋水。如果说上句是重在写秋色，那么这一句则重在写秋容。一个“愁”字，把秋风和秋水都拟人化了，于是，外在的景物也霎时同作家的内在感情溶为一体了，词作也因之而笼罩了一层浓重的萧瑟气氛。三、四两句，由景生情，更进一步突出作家的主观感受。韶光，指春光。在这里，作家以其独特而深刻的感受告诉人们：在这秋色满天的时节，美好的春光连同荷花的清芬、荷叶的秀翠，还有观荷人的情趣一起憔悴了，在浓重的萧瑟气氛中又平添了一种悲凉凄清的气氛。“不堪看”三字，质朴而有力，明白而深沉，活脱脱地抒发了诗人的主观感情。“自古逢秋悲寂寥”（唐刘禹锡诗句）。李璟虽然位高为皇帝，但是生性懦弱，再加上当时内外矛盾重重，境遇相当危苦，此时此刻，触景伤情，从而产生无穷的痛苦和哀怨是十分自然的。\n\n　　词的下片着重抒情。首句，托梦境诉哀情。一梦醒来，雨声细细，梦境即便美好，但所梦之人毕竟远在边塞（鸡塞，鸡麓塞，在今陕西省。这里泛指边塞），可思可望而不可即。的确是“雨亦绵绵，思亦绵绵”。“小楼”句，以吹笙衬凄清。风雨高楼，玉笙整整吹奏了一曲（彻，遍，段。吹彻，吹完最后一段），因吹久而凝水，笙寒而声咽，映衬了作家的寂寞孤清。这两句亦远亦近，亦虚亦实，亦声亦情，而且对仗工巧，是千古传唱的名句。最后两句，直抒胸臆。环境如此凄清，人事如此悲凉，不能不使人潸然泪下，满怀怨恨。“多少”，“何限”，数不清，说不尽。流不完的泪，诉不尽的恨；泪因恨洒，恨依泪倾。语虽平淡，但很能打动人心。结语“倚栏干”一句，写物写人更写情，脉脉深长，语已尽而意无穷。\n\n　　这首词有些版本题名“秋思”，看来是切合的。李廷机评论过这首词是“字字佳，含秋思极妙”（《全唐五代词》四四一页）。确实，它布景生思，情景交融，其有很强的艺术感染力。', poem_tags = '宋词三百首,婉约,闺怨,写景,荷花,思念' WHERE poem_title = '摊破浣溪沙·菡萏香销翠叶残' AND poem_author = '李璟';
UPDATE edu_poem SET poem_translation = '雪花飘舞着飞入了窗户，我坐在窗前，看着青青的竹子变成白玉般洁白。 此时正好登上高楼去远望，那人世间一切险恶的岔路都被大雪覆盖了。', poem_notes = '六出：雪花呈六角形，故以“六出”称雪花。\n琼枝：竹枝因雪覆盖面似白玉一般。\n恶路歧：险恶的岔路。', poem_tags = '冬天,写雪,抒怀' WHERE poem_title = '对雪' AND poem_author = '高骈';
UPDATE edu_poem SET poem_translation = '连理枝头艳丽的鲜花正在盛开，\n但风雨嫉妒鲜花的美丽，时时刻刻想要催促鲜花凋谢。\n我真想让掌管春天的神长久做主，\n不让娇嫩可爱的鲜花落到碧绿的青苔上。', poem_notes = '青帝：掌管春天的神，又称东君，东皇。', poem_tags = '古诗三百首,写花,寓人,爱情' WHERE poem_title = '落花' AND poem_author = '朱淑真';
UPDATE edu_poem SET poem_tags = '咏物,梅花' WHERE poem_title = '汉宫春·梅' AND poem_author = '晁冲之';
UPDATE edu_poem SET poem_translation = '西湖的春天，像一幅醉人的风景画，三面群山环抱中的湖面，汪汪一碧，水平如镜。群峰上，松树密密麻麻排满山面，千山万峰显得一派苍翠。一轮圆月映入水中，好像一颗明珠，晶莹透亮，跳荡悬浮。\n　　早稻初生，似一块巨大的绿色地毯，上面铺满厚厚的丝绒线头；蒲叶披风，像少女身上飘曳的罗带群幅。一幅格调清新的山水画图展现眼前，诗人不由发出对西湖风光的赞美。春色如此秀丽，作者不愿离开杭州回京，有一半因素就是舍不得这风景如画的西湖。', poem_notes = '乱峰：参差不齐的山峰。\n松排山面：指山上有许多松树。\n月点波心：月亮倒映在水中。\n碧毯线头抽早稻,青罗裙带展新蒲：田野里早稻拔节抽穗，好像碧绿的毯子上的线头；河边菖蒲新长出的嫩叶，犹如罗裙上的飘带。\n勾留：留恋。', poem_appreciation = '西湖的春天，像一幅醉人的风景画，三面群山环抱中的湖面，汪汪一碧，水平如镜。群峰上，松树密密麻麻排满山面，千山万峰显得一派苍翠。一轮圆月映入水中，好像一颗明珠，晶莹透亮，跳荡悬浮。\n\n　　早稻初生，似一块巨大的绿色地毯，上面铺满厚厚的丝绒线头；蒲叶披风，像少女身上飘曳的罗带群幅。一幅格调清新的山水画图展现眼前，诗人不由发出对西湖风光的赞美。春色如此秀丽，作者不愿离开杭州回京，有一半因素就是舍不得这风景如画的西湖。\n\n　　诗的前三联绘景，尾联抒情，全诗则情景交融，物我划一。首句鸟瞰西湖春日景色，谓其“似画图”。作者以具有如此浓重感情色彩的字眼儿入诗，并非偶然。在孩童时代，白居易曾立志要到杭州做官，心愿得酬，自然为之欣喜，其对杭州的深情于此可见一斑。此诗不仅是白居易山水诗中的佳构，亦是历代描写西湖诗中的名篇之一。\n\n　　“乱峰”以下三句，具体描绘如画之景∶群山环绕，参差不一，湖上水面平展；排排青松装点着山峦，如重重叠叠的翡翠，皎洁的月亮映入湖心，象一颗闪光的珍珠，这是多么诱人的美景呵！然而诗的旨趣并没有凝滞在范山模水的层面上，“碧毯”二句出人意表地把笔舌转到对农作物的体察上。在山水诗中嵌入农事，弄不好会雅俗相悖，很不协调，而白居易却别出心裁地把农事诗化了━━早稻犹碧毯上抽出的线头、新蒲象青罗裙上的飘带。如此精妙新奇的比喻本身不仅体现出作者对湖区人民的关怀，使读者由此可以联想到正是这位自幼向往杭州的白刺史，一到任便体恤民瘼，浚井供饮，把杭州变成了人间天堂，从而铭戢其德惠。同时，在诗的写作上也是一种变格、一种可贵的出新，它比作者描绘西湖的另一名篇《钱塘湖春行》，立意更加新颖，语言益见精妙。\n\n　　这首诗的结构曲折委婉，别有情致，特别是最后两句“以不舍意作结，而曰‘一半勾留’，言外正有余情。”（《唐宋诗醇》）那么其“言外余情”是什么呢？这得联系作者的有关行迹和创作来探寻。除杭州刺史之前，白居易原在长安任中书舍人。面对国是日荒，民生益困的现实，屡屡上书言事而不被采纳，眼见时局日危，朋党倾轧加剧，便自求外任，来到杭州。这是问题的一方面，另一方面是他认为做隐士不好，做京官也不好，只有做杭州刺史闲忙得当，正合其意，即所谓“□溪殊冷僻，茂苑太繁雄。唯此钱塘郡，闲忙恰得中。”这话是出自《初到郡斋寄钱湖州李苏州》一诗，在其他篇目中 尚有不少类似的说法，这既是作者的心里话，也是此诗的“言外余情”。\n\n　　因为“皇恩只许住三年”，白居易抱着恋恋不舍的心情离开西湖，这种情绪本身具有很强的感染力。一千多年后的今天，西湖早已是驰名中外的湖山形胜之地，此诗亦不胫而走，值得玩味的是如今西湖十景中的“平湖秋月”、“苏堤春晓”、“三潭印月”等景观的命名，有的很可能是从这首《春题湖上》中的相应诗句衍化而来的。', poem_tags = '春天,西湖' WHERE poem_title = '春题湖上' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '枫树在深秋露水的侵蚀下逐渐凋零、残伤，巫山和巫峡也笼罩在萧瑟阴森的迷雾中。巫峡里面波浪滔天，上空的乌云则像是要压到地面上来似的，天地一片阴沉。花开花落已两载，看着盛开的花，想到两年未曾回家，就不免伤心落泪。小船还系在岸边，虽然我不能东归，飘零在外的我，心却长系故园。又在赶制冬天御寒的衣服了，白帝城上捣制寒衣的砧声一阵紧似一阵。看来又一年过去了，我对故乡的思念也愈加凝重，愈加深沉。\n\n　　夔州的高城上又迎来了落日。每当晚上北斗星出现的时候，我就按照它的方向来寻找长安的所在。听到巫峡的猿啼，我真的流下泪来。我也希望乘着浮槎回到自己的故乡，但这愿望终究还是落空了。我还记得我从前春宿左省值夜的时候，晚上熬夜写些明朝的封事，点燃书案上的香。可现在我早已不在那里就职。滞留此地，傍晚时分听到城楼上吹起悲笳，心中升起一股隐然的悲痛。你看，山石上爬满了藤萝。月亮刚刚升起来的时候，月光是照在藤萝上的，而现在它已经照到河洲前面的芦荻花上面去了。我一夜无眠，一直在怀念长安。\n\n　　白帝城里千家万户静静地沐浴在秋日的朝晖中，我天天去江边的楼上，坐着看对面青翠的山峰。连续两夜在船上过夜的渔人，仍泛着小舟在江中漂流。虽已是清秋季节，燕子仍然展翅飞来飞去。汉朝的匡衡向皇帝直谏，他把功名看得很淡薄；刘向传授经学，怎奈事不遂心。古人尚且如此，我更是不必说了。年少时一起求学的同学大都已飞黄腾达了，他们在长安附近的五陵，穿轻裘，乘肥马，过着富贵的生活，我却注定要为一个信念苦渡人间。\n\n　　听说长安的政坛就像一盘未下完的棋局，彼争此夺。反复不定，反思国家和个人所经历的动乱与流亡，有说不尽的悲哀。世道的变迁，时局的动荡，国运今非昔比，王侯们的家宅更换主人，无奈宦官当道，贤臣良相更成泡影。中央的典章、文物、制度都已废弃，在政治上我已经是一个被遗忘的人了。回纥内侵，关山号角雷动、兵戈挥舞；吐蕃入寇，传递情报的战马正急速奔驰。在这国家残破、秋江清冷、身世凄苦、暮年潦倒的情况下，昔日在长安的生活常常呈现在怀想之中。\n\n　　日复一日，大明宫遥望着终南山，却望不到。那些深居的隐士，天露和玉屑，都已被他们吸光饮尽，青鸟报信，西王母自瑶池驾临，紫气弥漫，老子骑牛西去。记得当年朝上，雉尾扇开合如同祥云移回，日光沐浴着圣殿，让我看清玄宗的容貌。记得当年位列朝班，青琐门下意气风发，而现在，疾病无情地消磨着时光……秋已渐深。\n\n　　谙练一种时空的分身术，瞿塘峡、曲江头，距离被心灵无限地缩短。十五年前我写《乐游园歌》，花萼楼、芙蓉园历历在目。安禄山的铁蹄已使一切烟消云散。那时，黄鹄还在亭院内高飞，成群的白鸥被游人的舟楫惊起。——而今，一切都消逝了，消逝了……没有任何留恋的事物。\n\n　　遥想汉武帝曾在昆明池上练习水兵，一面面战旗迎风击鼓。池中石刻的织女辜负了美好的夜色，只有那巨大的鲸鱼还会在雷雨天与秋风共舞。波浪中的菰米丛犹如黑云聚拢，莲子结蓬，红花坠陨。多想像飞鸟一般自由滑翔于秦中的天空，现实却困我在冷江上无言垂钓。\n\n　　从长安到渼陂，途径昆吾和御宿，紫阁峰在终南山上闪耀。我想念一路的香稻和碧梧，在丰收的季节 吸引着鹦鹉与凤凰……等到春天，曼妙的仕女们还会采摘花草相互赠送，伙伴们在暮晚时分仍要移棹出发，不愿归返。昔日，我可以凭借词语凿穿时代的黑井，痛饮山河甘洌，而今却只能在回忆中围拢水源，抚摸它岑寂的微光。', poem_notes = '玉露：秋天的霜露，因其白，故以玉喻之。凋伤：使草木凋落衰败。\n巫山巫峡：即指夔州（今奉节）一带的长江和峡谷。萧森：萧瑟阴森。\n兼天涌：波浪滔天。\n塞上：指巫山。接地阴：风云盖地。“接地”又作“匝地”。\n丛菊两开：杜甫此前一年秋天在云安，此年秋天在夔州，从离开成都算起，已历两秋，故云“两开”。“开”字双关，一谓菊花开，又言泪眼开。他日：往日，指多年来的艰难岁月。\n故园：此处当指长安。\n催刀尺：指赶裁冬衣。“处处催”，见得家家如此。\n白帝城：即今奉节城，在瞿塘峡上口北岸的山上，与夔门隔岸相对。急暮砧：黄昏时急促的捣衣声。 砧：捣衣石。急暮砧：黄昏时急促的捣衣声。砧，捣衣石。\n夔（kuí）府：唐置夔州，州治在奉节，为府署所在，故称。\n京华：指长安。\n槎：木筏。\n画省：指尚书省。\n山楼：白帝城楼。\n翠微：青山。\n信宿：再宿。\n匡衡：字雅圭，汉朝人。抗疏：指臣子对于君命或廷议有所抵制，上疏极谏。\n刘向：字子政，汉朝经学家。\n轻肥：即轻裘肥马。\n闻道：听说。杜甫因离开京城日久，于朝廷政局的变化，不便直言，故云“闻道”。似弈棋：是说长安政局像下棋一样反复变化，局势不明。\n百年：指代一生。\n第宅：府第、住宅。新主：新的主人。\n异昔时：指与旧日不同。\n北：正北，指与北边回纥之间的战事。金鼓振：指有战事，金鼓为军中以明号令之物。\n征西：指与西边吐蕃之间的战事。羽书：即羽檄，插着羽毛的军用紧急公文。驰：形容紧急。\n鱼龙：泛指水族。寂寞：是指入秋之后，水族潜伏，不在波面活动。\n故国：指长安。平居：指平素之所居。末二句是说在夔州秋日思念旧日长安平居生活。\n蓬莱宫阙：指大明宫。蓬莱，汉宫名。唐高宗龙朔二年（662），重修大明宫，改名蓬莱宫。南山：即终南山。\n承露金茎：指仙人承露盘下的铜柱。汉武帝在建章宫之西神明台上建仙人承露盘。唐代无承露盘，此乃以汉喻唐。霄汉间：高入云霄，形容承露金茎极高。\n瑶池：神化传说中女神西王母的住地，在昆仑山。降王母：《穆天子传》等书记载有周穆王登昆仑山会西王母的传说。\n东来紫气：用老子自洛阳入函谷关事。\n函关：即函谷关。此二句借用典故极写都城长安城宫殿的宏伟气象。\n云移：指宫扇云彩般地分开。雉尾：指雉尾扇，用雉尾编成，是帝王仪仗的一种。\n日绕龙鳞：形容皇帝衮袍上所绣的龙纹光彩夺目，如日光缭绕。圣颜：天子的容貌。\n一：一自，自从。卧沧江：指卧病夔州。岁晚：岁末，切诗题之“秋”字，兼伤年华老大。\n几回：言立朝时间之短，只不过几回而已。青琐：汉未央宫门名，门饰以青色，镂以连环花纹。后亦借指宫门。点朝班：指上朝时，殿上依班次点名传呼百官朝见天子。此二句慨叹自己晚年远离朝廷，卧病夔州，虚有朝官（检校工部员外郎）之名，却久未参加朝列。\n.瞿塘峡：峡名，三峡之一，在夔州东。曲江：在长安之南，名胜之地。\n万里风烟：指夔州与长安相隔万里之遥。素秋：秋尚白，故称素秋。\n花萼：即花萼相辉楼，在长安南内兴庆宫西南隅。夹城：据《长安志》记载，唐玄宗开元二十年（732），从大明宫依城修筑复道，经通化门，达南内兴庆宫，直至曲江芙蓉园。通御气：此复道因系方便天子游赏而修，故曰“通御气”。\n芙蓉小苑：即芙蓉园，也称南苑，在曲江西南。入边愁：传来边地战乱的消息。\n珠帘绣柱：形容曲江行宫别院的楼亭建筑极其富丽华美。黄鹄：鸟名，即天鹅。\n锦缆牙樯：指曲江中装饰华美的游船。锦缆，彩丝做的船索。牙樯，用象牙装饰的桅杆。此句说曲江上舟楫往来不息，水鸟时被惊飞。\n歌舞地：指曲江池苑。\n秦中：此处借指长安。帝王州：帝王建都之地。\n昆明池：遗址在今西安市西南斗门镇一带，汉武帝所建。\n武帝：汉武帝，亦代指唐玄宗。唐玄宗为攻打南诏，曾在昆明池演习水兵。旌旗：指楼船上的军旗。\n织女：指汉代昆明池西岸的织女石像，俗称石婆。\n机丝：织机及机上之丝。虚夜月：空对着一天明月。\n石鲸：指昆明池中的石刻鲸鱼。《三辅黄图》卷四引《三辅故事》曰：“池中有豫章台及石鲸，刻石为鲸鱼，长三丈，每至雷雨。常鸣吼。鬣尾皆动。”汉代石鲸今尚在，现藏陕西历史博物馆。\n菰（gū）：即茭白，一种草本植物，生浅水中，叶似芦苇，根茎可食。秋天结实，皮黑褐色，状如米，故称菰米，又名雕胡米。\n莲房：即莲蓬。坠粉红：指秋季莲蓬成熟，花瓣片片坠落。中二联刻画昆明池晚秋荒凉萧瑟之景。\n关塞：此指夔州山川。极天：指极高。唯鸟道：形容道路高峻险要，只有飞鸟可通。此句指从夔州北望长安，所见惟有崇山峻岭，恨身无双翼，不能飞越。\n江湖满地：指漂泊江湖，苦无归宿。渔翁：杜甫自比。\n昆吾：汉武帝上林苑地名，在今陕西蓝田县西。御宿：即御宿川，又称樊川，在今陕西西安市长安区杜曲至韦曲一带。\n逶迤：道路曲折的样子。\n紫阁峰：终南山峰名，在今陕西户县东南。阴：山之北、水之南，称阴。渼（měi）陂（bēi）：水名，在今陕西户县西，唐时风景名胜之地。陂，池塘湖泊。紫阁峰在渼陂之南，陂中可以看到紫阁峰秀美的倒影。\n香稻啄馀鹦鹉粒：即使是剩下的香稻粒，也是鹦鹉吃剩下的。此句为倒装语序。\n碧梧：即使碧梧枝老，也是凤凰所栖。同上句一样，是倒装语序。\n拾翠：拾取翠鸟的羽毛。相问：赠送礼物，以示情意。\n仙侣：指春游之伴侣，“仙”字形容其美好。晚更移：指天色已晚，尚要移船他处，以尽游赏之兴。\n彩笔：五彩之笔，喻指华美艳丽的文笔。\n干气象：喻指自己曾于天宝十载上《三大礼》赋，得唐玄宗赞赏。\n白头：指年老。望：望京华。', poem_appreciation = '《秋兴八首》这组诗，融铸了夔州萧条的秋色，清凄的秋声，暮年多病的苦况，关心国家命运的深情，悲壮苍凉，意境深闳。它是八首蝉联、结构严密、抒情深挚的一组七言律诗，体现了诗人晚年的思想感情和艺术成就。\n\n　　“秋兴”这个题目，意思是说因感秋而寄兴。这兴也就是过去汉儒说《诗经》的所谓“赋比兴”的“兴”（在四声应读去声）。晋代的潘岳有《秋兴赋》， 也是一篇感秋寄兴之作。但《秋兴赋》的体裁是属于辞赋类。而杜甫的《秋兴八首》则是律诗，是唐代新兴的一种诗体。若论它们创作的成就和对后世发生的影响，杜甫的《秋兴八首》当然不是潘岳的《秋兴赋》所可比拟。\n\n　　《秋兴八首》的结构，从全诗来说，可分两部，而以第四首为过渡。前三首详夔州而略长安，后五首详长安而略夔州；前三首由夔州而思及长安，后五首则由思长安而归结到夔州；前三首由现实引发回忆，后五首则由回忆回到现实。至于各首之间，则亦首尾相衔，有一定次第，不能移易，八首只如一首。八首诗，章法缜密严整，脉络分明，不宜拆开，亦不可颠倒。从整体看，从诗人身在的夔州，联想到长安；由暮年飘零，羁旅江上，面对满目萧条景色而引起国家盛衰及个人身世的感叹；以对长安盛世胜事的追忆而归结到诗人现实的孤寂处境、今昔对比的哀愁。这种忧思不能看作是杜甫一时一地的偶然触发，而是自经丧乱以来，他忧国伤时感情的集中表现。目睹国家残破，而不能有所作为，其中曲折，诗人不忍明言，也不能尽言。这就是他所以望长安，写长安，婉转低回，反复慨叹的道理。\n\n　　为理解这组诗的结构，须对其内容先略作说明。第一首是组诗的序曲，通过对巫山巫峡的秋色秋声的形象描绘，烘托出阴沉萧森、动荡不安的环境气氛，令人感到秋色秋声扑面惊心，抒发了诗人忧国之情和孤独抑郁之感。这一首开门见山，抒情写景，波澜壮阔，感情强烈。诗意落实在“丛菊两开他日泪，孤舟一系故园心”两句上，下启第二、三首。第二首写诗人身在孤城，从落日的黄昏坐到深宵，翘首北望，长夜不寐，上应第一首。最后两句，侧重写自己已近暮年，兵戈不息，卧病秋江的寂寞，以及身在剑南，心怀渭北，“每依北斗望京华”，表现出对长安的强烈怀念。第三首写晨曦中的夔府，是第二首的延伸。诗人日日独坐江楼，秋气清明，江色宁静，而这种宁静给作者带来的却是烦扰不安。面临种种矛盾，深深感叹自己一生的事与愿违。第四首是组诗的前后过渡。前三首诗的忧郁不安步步紧逼，至此才揭示它们的中心内容，接触到“每依北斗望京华”的核心：长安象“弈棋”一样彼争此夺，反复不定。人事的更变，纲纪的崩坏，以及回纥、吐蕃的连年进犯，这一切使诗人深感国运大非昔比。对杜甫说来，长安不是个抽象的地理概念，他在这唐代的政治中心住过整整十年，深深印在心上的有依恋，有爱慕，有欢笑，也有到处“潜悲辛”的苦闷。当此国家残破、秋江清冷、个人孤独之际，所熟悉的长安景象，一一浮现眼前。“故国平居有所思”一句挑出以下四首。第五首，描绘长安宫殿的巍峨壮丽，早朝场面的庄严肃穆，以及自己曾得“识圣颜”至今引为欣慰的回忆。值此沧江病卧，岁晚秋深，更加触动他的忧国之情。第六首怀想昔日帝王歌舞游宴之地曲江的繁华。帝王佚乐游宴引来了无穷的“边愁”，清歌曼舞，断送了“自古帝王州”，在无限惋惜之中，隐含斥责之意。第七首忆及长安的昆明池，展示唐朝当年国力昌盛、景物壮丽和物产富饶的盛景。第八首表现了诗人当年在昆吾、御宿、渼陂春日郊游的诗意豪情。“彩笔昔曾干气象”，更是深刻难忘的印象。\n\n　　八首诗是不可分割的整体，正如一个大型抒情乐曲有八个乐章一样。这个抒情曲以忧念国家兴衰的爱国思想为主题，以夔府的秋日萧瑟，诗人的暮年多病、身世飘零，特别是关切祖国安危的沉重心情作为基调。其间穿插有轻快欢乐的抒情，如“佳人拾翠春相问，仙侣同舟晚更移”；有壮丽飞动、充满豪情的描绘，如对长安宫阙、昆明池水的追述；有表现慷慨悲愤情绪的，如“同学少年多不贱，五陵衣马自轻肥”；有极为沉郁低回的咏叹，如“关塞极天惟鸟道，江湖满地一渔翁”、“白头吟望苦低垂”等。就以表现诗人孤独和不安的情绪而言，其色调也不尽相同。“江间波浪兼天涌，塞上风云接地阴”，以豪迈、宏阔写哀愁；“信宿渔人还泛泛，清秋燕子故飞飞”，以清丽、宁静写“剪不断、理还乱”的不平静的心绪。总之，八首中的每一首都以自己独特的表现手法，从不同的角度表现基调的思想情绪。它们每一首在八首中又是互相支撑，构成了整体。这样不仅使整个抒情曲错综、丰富，而且抑扬顿挫，有开有阖，突出地表现了主题。\n\n　　《秋兴八首》中，杜甫除采用强烈的对比手法外，反复运用了循环往复的抒情方式，把读者引入诗的境界中去。组诗的纲目是由夔府望长安──“每依北斗望京华”。组诗的枢纽是“瞿塘峡口曲江头，万里风烟接素秋”。从瞿塘峡口到曲江头，相去遥远，诗中以“接”字，把客蜀望京，抚今追昔，忧邦国安危……种种复杂感情交织成一个深厚壮阔的艺术境界。第一首从眼前丛菊的开放联系到“故园”。追忆“故园”的沉思又被白帝城黄昏的四处砧声所打断。这中间有从夔府到长安，又从长安回到夔府的往复。第二首，由夔府孤城按着北斗星的方位遥望长安，听峡中猿啼，想到“画省香炉”。这是两次往复。联翩的回忆，又被夔府古城的悲笳所唤醒。这是第三次往复。第三首虽然主要在抒发悒郁不平，但诗中有“五陵衣马自轻肥”，仍然有夔府到长安的往复。第四、五首，一写长安十数年来的动乱，一写长安宫阙之盛况，都是先从对长安的回忆开始，在最后两句回到夔府。第六首，从瞿塘峡口到曲江头，从目前的万里风烟，想到过去的歌舞繁华。第七首怀想昆明池水盛唐武功，回到目前“关塞极天惟鸟道”的冷落。第八首，从长安的“昆吾……”回到“白头吟望”的现实，都是往复。循环往复是《秋兴八首》的基本表现方式，也是它的特色。不论从夔府写到长安，还是从追忆长安而归结到夔府，从不同的角度，层层加深，不仅毫无重复之感，还起了加深感情，增强艺术感染力的作用，真可以说是“毫发无遗憾，波澜独老成”（《赠郑谏议十韵》）了。\n\n　　情景的和谐统一，是抒情诗里一个异常重要的方面。《秋兴八首》可说是一个极好的范例。如“江间波浪兼天涌，塞上风云接地阴”，波浪汹涌，仿佛天也翻动；巫山风云，下及于地，似与地下阴气相接。前一句由下及上，后一句由上接下。波浪滔天，风云匝地，秋天萧森之气充塞于巫山巫峡之中。我们感到这两句形象有力，内容丰富，意境开阔。诗人不是简单地再现他的眼见耳闻，也不是简单地描摹江流湍急、塞上风云、三峡秋深的外貌特征，诗人捕捉到它们内在的精神，而赋予江水、风云某种性格。这就是天上地下、江间关塞，到处是惊风骇浪，动荡不安；萧条阴晦，不见天日。这就形象地表现了诗人的极度不安，翻腾起伏的忧思和胸中的郁勃不平，也象征了国家局势的变易无常和臲硊不安的前途。两句诗把峡谷的深秋，诗人个人身世以及国家丧乱都包括在里面。这种既掌握景物的特点，又把自己人生经验中最深刻的感情融会进去，用最生动、最有概括力的语言表现出来，这样景物就有了生命，而作者企图表现的感情也就有所附丽。情因景而显，景因情而深。语简而意繁，心情苦闷而意境开阔（意指不局促，不狭窄）。苏东坡曾说：“赋诗必此诗，定知非诗人”（《书鄢陵王主簿所画折枝二首》），确实是有见识、有经验之谈。\n\n　　杜甫住在成都时，在《江村》里说“自去自来堂上燕”，从栖居草堂的燕子的自去自来，表现诗人所在的江村长夏环境的幽静，显示了诗人漂泊后，初获暂时安定生活时自在舒展的心情。在《秋兴八首》第三首里，同样是燕飞，诗人却说：“清秋燕子故飞飞。”诗人日日江楼独坐，百无聊赖中看着燕子的上下翩翩，燕之辞归，好像故意奚落诗人的不能归，所以说它故意飞来绕去。一个“故”字，表现出诗人心烦意乱下的着恼之情。又如“瞿塘峡口曲江头，万里风烟接素秋”，瞿塘峡在夔府东，临近诗人所在之地，曲江在长安东南，是所思之地。黄生《杜诗说》：“二句分明在此地思彼地耳，却只写景。杜诗至化处，景即情也”，不失为精到语。至如“花萼夹城通御气，芙蓉小苑入边愁”的意在言外；“鱼龙寂寞秋江冷”的写秋景兼自喻；“请看石上藤萝月，已映洲前芦荻花”的纯是写景，情也在其中。这种情景交融的例子，八首中处处皆是。\n\n　　前面所说的情景交融，是指情景一致，有力地揭示诗人丰富复杂的内心世界所产生的艺术效果。此外，杜甫善于运用壮丽、华美的字和词表现深沉的忧伤。《秋兴八首》里，把长安昔日的繁华昌盛描绘得那么气象万千，充满了豪情，诗人早年的欢愉说起来那么快慰、兴奋。对长安的一些描写，不仅与回忆中的心情相适应，也与诗人现实的苍凉感情成为统一不可分割、互相衬托的整体。这更有助读者体会到诗人在国家残破、个人暮年漂泊时极大的忧伤和抑郁。诗人愈是以满腔热情歌唱往昔，愈使人感受到诗人虽老衰而忧国之情弥深，其“无力正乾坤”的痛苦也越重。\n\n　　《秋兴八首》中，交织着深秋的冷落荒凉、心情的寂寞凄楚和国家的衰败残破。按通常的写法，总要多用一些清、凄、残、苦等字眼。然而杜甫在这组诗里，反而更多地使用了绚烂、华丽的字和词来写秋天的哀愁。乍看起来似和诗的意境截然不同，但它们在诗人巧妙的驱遣下，却更有力地烘托出深秋景物的萧条和心情的苍凉。如“蓬莱宫阙”、“瑶池”、“紫气”、“云移雉尾”、“日绕龙鳞”、“珠帘绣柱”、“锦缆牙樯”、“武帝旌旗”、“织女机丝”、“佳人拾翠”、“仙侣同舟”……都能引起美丽的联想，透过字句，泛出绚丽的光彩。可是在杜甫的笔下，这些词被用来衬托荒凉和寂寞，用字之勇，出于常情之外，而意境之深，又使人感到无处不在常情之中。这种不协调的协调，不统一的统一，不但丝毫无损于形象和意境的完整，而且往往比用协调的字句来写，能产生更强烈的艺术效果。正如用“笑”写悲远比用“泪”写悲要困难得多，可是如果写得好，就把思想感情表现得更为深刻有力。刘勰在《文心雕龙》的《丽辞》篇中讲到对偶时，曾指出“反对”较“正对”为优。其优越正在于“理殊趣合”，取得相反相成、加深意趣、丰富内容的积极作用。运用豪华的字句、场面表现哀愁、苦闷，同样是“理殊趣合”，也可以说是情景在更高的基础上的交融。其间的和谐，也是在更深刻、更复杂的矛盾情绪下的统一。\n\n　　有人以为杜甫入蜀后，诗歌不再有前期那样大气磅礴、浓烈炽人的感情。其实，诗人在这时期并没消沉，只是生活处境不同，思想感情更复杂、更深沉了。而在艺术表现方面，经长期生活的锻炼和创作经验的积累，比起前期有进一步的提高或丰富，《秋兴八首》就是明证。', poem_tags = '秋天,写景,抒情,忧国忧民,组诗' WHERE poem_title = '秋兴八首' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_tags = '田园,生活,感慨,人生' WHERE poem_title = '归园田居·其四' AND poem_author = '陶渊明';
UPDATE edu_poem SET poem_translation = '看吴山青青，看越山青青，钱塘两岸青山相对迎。怎忍心分手有离情。\n你泪儿盈盈，我泪儿盈盈，香罗带未结成同心结。江潮已涨，船儿扬帆要远行。', poem_notes = '吴山：指钱塘江北岸的山，此地古代属吴国。越山，钱塘江南岸的山，此地古代属越国。\n争忍：怎忍。\n罗带句：古代结婚或定情时以香罗带打成菱形结子，以示同心相怜。南朝《苏小小歌》：“何处结同心，西陵松柏下。”\n江边句：通过潮涨暗示船将启航。', poem_tags = '宋词三百首,宋词精选,婉约,送别' WHERE poem_title = '相思令·吴山青' AND poem_author = '林逋';
UPDATE edu_poem SET poem_translation = '楼外垂杨千条万缕，仿佛要拴住春天的脚步，春天却匆匆而过不曾稍停。只有柳絮仍然在风里飘飞，它随春风要看春归向何处？\n绿色的山川只听杜鹃乌啼叫，它本是无情的鸟，凄厉的叫声岂不也在为人愁苦。举杯送别春天，春天却不语，黄昏时候却下起了潇潇细雨。', poem_notes = '系：拴住。\n青春：大好春光。隐指词人青春年华。\n少住：稍稍停留一下。\n犹自：依然。\n杜宇：杜鹃鸟。\n便作：即使。\n莫也：岂不也。\n“把酒”句：把酒，举杯；把，持、拿。送春，阴历三月末是春天最后离去的日子，古人有把酒浇愁以示送春的习俗。此句与王灼《点绛唇》“试来把酒留春住，问春无语，席卷西山雨”写法相似。\n潇潇雨：形容雨势之疾。', poem_appreciation = '宋代有不少“惜春”词。暮春景色不外乎柳絮纷飞，杜鹃哀呜，暮雨淅沥，抒发的不过是作者的惋惜之情。然而，女词人朱淑真却通过丰富的想象力和贴切的拟人手法，将暮春景色表现得委婉多姿、细腻动人，在宋代诸多惜春之作中，显出它自己独有的艺术特色。\n\n　　朱淑真在少女时期也曾“天资秀发，性灵钟慧”（宋·魏仲恭《朱淑真断肠诗词序》），写过欢快明丽的《春景》诗：“斗草寻花正及时，不为容易见芳菲。谁能更觑闲针线，且滞春光伴酒卮。”──她要趁春光明媚而及时地去寻觅鲜花，去与女伴们斗草戏耍。这不仅因芬芳秾艳的春景不易常见（故而弥足珍贵），更重要的是由大自然的春光唤醒了自己的青春之感，激发了对自己美好青春的珍惜之情（所以对春天倍感可亲可爱），因而她不肯为闺中“女训”“女诫”所拘钳去拿针缝线学什么无味的女红，而要欢欣喜悦地举起酒杯，邀请春天这少女般的伴侣陪自己共度人生之良辰。然而，曾几何时，在经历了人世的辛酸折磨之后（传说她“早岁不幸父母失审，不能择伉俪”，“乃下配一庸夫”致使“一生抑郁不得志”，“每临风对月，触目伤怀”），朱淑真却给后人送来了悲凄幽悒的《送春》词。扫视这前后的强烈反差，读者既可感触到旧时代的凄风苦雨，又可从女作家不同风貌的艺术描述中领略到不同的审美韵致，从而丰富自己的美感经验。　\n\n　　词中首先出现的是垂杨。“楼外垂杨千万缕，欲系青春，少住春还去”三句，描绘了垂杨的绿姿。这种“万条垂下绿丝绦”（贺知章《咏柳》）的景色，对于阴历二月（即仲春时节），是最为典型的。上引贺诗中即有“不知细叶谁裁出，二月春风似剪刀”之句。它不同于“浓如烟草淡如金”的新柳（明人杨基《咏新柳》），也有别于“风吹无一叶”的衰柳（宋人翁灵舒《咏衰柳》）。为什么借它来表现惜春之情呢？主要利用那柔细如丝缕的枝条的构造成似乎可以系留着事物的联象。“少住春还去”，在作者的想象中，那打算系住春天的柳条没有达到目的，它只把春天从二月拖到三月末，春天经过短暂的逗留，还是决然离去了。　\n\n　　“犹自风前飘柳絮，随春且看归何处”两句，对暮春景物作了进一层的描写。柳絮是暮春最鲜明的特征之一，所以诗人们说：“飞絮著人春共老”（范成大《暮春上塘道中》）、“飞絮送春归”（蔡伸《朝中措》）。他们都把飞絮同残春联系在一起。朱淑真却独出心裁，把天空随风飘舞的柳絮，描写为似乎要尾随春天归去，去探看春的去处，把它找回来，像黄庭坚在词中透露的：“若有人知春去处，唤取归来同住”（《清平乐》）。比起简单写成“飞絮”“送春归”或“著人春意老”来，朱淑真这种“随春”的写法，就显得更有迂曲之趣。句中用“犹自”把“系春”同“随春”联系起来，造成了似乎是垂杨为了留春，“一计不成，又生一计”的艺术效果。 　\n\n　　像飞絮一样，哀鸣的杜宇（杜鹃鸟）也似看作是残春的标志。“绿满山川闻杜宇，便做无情，莫也愁人苦”，春残时节，花落草长，山野一片碧绿。远望着这暮春的山野，听到传来的杜鹃鸟的凄厉叫声，词人在想：杜鹃即使（便做）无情，也为“春去”而愁苦，因而发出同情的哀鸣，词人通过这摇曳生姿的一笔，借杜宇点出人意的愁苦，这就把上片中处于“暮后”的主人公引向台前。在上片，仅仅从“楼外”两个字，感觉到她的楼内张望；从“系春”“随春”，意识到是她在驰骋想象，主人公的惜春之情完全是靠垂杨和柳絮表现出来的。现在则由侧面烘托转向正面描写。　\n\n　　“把酒送春春不语”。系春既不可能，随春又无结果，主人公看到的只是暮春的碧野，听到的又是宣告春去的鸟鸣，于是她只好无可奈何地“送春”了。 　\n\n　　阴历三月末是春天最后离去的日子，古人常常在这时把酒举杯，以示送春。唐末诗人韩偓《春尽日》诗有“把酒送春惆怅在，年年三月病恹恹”之句。朱淑真按照旧俗依依不舍地“送春”，而春却没有回答。她看到的只是在黄昏中忽然下起的潇潇细雨。作者用一个“却”字，把“雨”变成了对春的送行。这写法同王灼的“试来把酒留春住，问春无语，帘卷西山雨”（《点绛唇》）相似，不过把暮雨同送春紧密相连，更耐人寻味：这雨是春漠然而去的步履声呢，还是春不得不去而洒下的惜别之泪呢？ 　\n\n　　这首词同黄庭坚的《清平乐》都将春拟人，抒惜春情怀，但写法上各有千秋。黄词从追访消逝的春光着笔，朱词从借垂柳系春、飞絮随春到主人公送春，通过有层次的心理变化揭示主题。相比之下，黄词更加空灵、爽丽，朱词则较多寄情于残春的景色，带有凄忱的情味，这大概和她的身世有关。', poem_tags = '宋词三百首,宋词精选,婉约,惜春' WHERE poem_title = '蝶恋花·送春' AND poem_author = '朱淑真';
UPDATE edu_poem SET poem_translation = '告急的军使跃马扬鞭，飞驰而来，一走马便是十里，一扬鞭便是五里，漫长的路程风驰电掣般一闪而过。这是西北都护府的军使，他传来了加急的军书，报告匈奴的军队已经包围了我大唐的西域重镇酒泉。在接到军书之后，举目西望，却只见漫天飞雪，一片迷茫，望断关山，不见烽烟的痕迹，原来军中的烽火联系已经中断了。', poem_notes = '陇西行：乐府古题，又名“步出夏门行”，属《相和歌·瑟调曲》。陇西，陇山之西，在今甘肃省陇西县以东。\n都护：官名。汉代设置西域都护，唐代设置六大都护府以统辖西域诸国。\n匈奴：这里泛指中国北部和西部的少数民族。酒泉：郡名，在今酒泉市东北。\n关山：泛指边关的山岳原野。\n烽戍：烽火台和守边营垒。古代边疆告警，以烽燧为号，白天举烟为“燧”，夜晚举火为“烽”。戍，一本作“火”。断：中断联系。', poem_tags = '边塞,战争' WHERE poem_title = '陇西行' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '故园远隔云山究竟在何处？归思悠长上心头情满胸怀。\n淮南秋雨绵绵的漫漫长夜，高斋独坐听雁声阵阵传来。', poem_notes = '故园：指作者在长安的家。眇（miǎo）：仔细地察看。\n方：刚开始。悠：远。\n淮南：作者所在地滁州（今安徽省滁州市，位于淮河南岸）。\n高斋：楼阁上的书房。闻雁：听到北来的雁叫声。', poem_appreciation = '“故园眇何处，归思方悠哉。”首二句言诗人雨夜思归。秋天的雨夜漫长而又寂寥，诗人独坐在高斋之中，孤灯长伴，孤影为侣，静静地听着外面渐渐沥沥的秋雨。窗外一片漆黑，只有雨打梧桐的声音。孤清的夜，深秋的凄寒，还有空寂的高斋，在这样一种萧瑟凄寂的环境气氛之中，诗人不免要触动羁旅他乡、远游为宦的思乡情思。诗人的家乡在长安，而此时却在远离家乡两千余里的滁州为官，“眇”字反映诗人内心的无奈情态，因为云山阻隔、归路迢递，即使在白天登楼引颈也无法看到故园，更何况是暗夜沉沉。故园的渺远，本来就和归思的悠长构成正比，再加上这漫漫长夜、绵绵秋雨，就更使这“归思”无穷无已、悠然不尽了。“方悠”二字表明清寂的氛围，加深了思乡之愁。“哉”是诗人久恩难平的叹息，这个长长的叹息，道尽了无尽思念的深渊。\n\n　　“淮南秋雨夜，高斋闻雁来。”这两句言闻雁而归思愈浓。“淮南”与第一句的“故园”相对，由思念中的故园回到今天为宦的淮南，落笔高妙。“秋雨”交待独坐时的清凉环境，“夜”既是表明时间很晚，是夜深人静的时候，也从侧面显露诗人贬谪滁州的苦痛如同黑夜一般。正当怀乡之情不能自控的时候，独坐高斋的诗人又听到了自远而近的雁叫声。这声音在寂寥的秋雨之夜，显得分外凄清，撩动诗人无尽的乡愁，使因思乡而永夜不寐的诗人浮想联翩，触绪万端，更加悲怆万分。诗写到这里，戛然而止，对“闻雁”而引起的感触不着一字，留下的是“此时无声胜有声”的结尾。\n\n　　沈德潜《说诗晬语》云：“五言绝句，右丞之自然，太白之高妙，苏州之古澹，并入化机。”“古澹”很好地概括了韦应物五言绝句的风格特征。在这首诗中，体现了诗人古澹的艺术风格。整首诗是一幅清淡的思乡图，清冷的夜晚，清凄的秋风，清寒的秋雨，清寂的高斋和清孤的人影，构成一种高古澹远的意境。此诗结构巧夺天工，含蓄委婉，先写“故园”，后写“淮南”，先托出“悠”思，后衬以“雁”鸣，就是在这样巧妙的安排中，使诗歌很短，但人的情思却句句深入，层层递进。另外，诗歌的情思表面触发的是乡愁，但结合诗人被贬滁州的事实。还可以从诗歌中体会出诗人对现实的不满情绪，这种情绪又完美地融入到萧瑟凄清的秋声秋意之中。', poem_tags = '思乡,秋天,大雁' WHERE poem_title = '闻雁' AND poem_author = '韦应物';
UPDATE edu_poem SET poem_translation = '空旷的原野被凄凉的风声充斥，原野上长满了枯黄的蒿草。\n把马的缰绳系住，我依靠在白杨树上，有谁知道我的怀抱所向呢。\n和那些同胞相逢的时候我们都衰老年高。\n向北登上汉家的陵墓，又向南眺望长安的大道。陵墓下面有枯树根，有鼯鼠的巢穴。\n刘邦的子孙已经无处可寻了，陵墓前千百年也没有人经过。\n陵墓中的宝玉频频被盗掘，神明又能怎么办呢。\n人应该对命运保持通达，有酒的时候就该放声高歌。', poem_notes = '悲风：让人感觉凄凉的风声，也指凄厉的寒风。\n饶：多，丰富。\n飕飕：象声词，指风声。\n同袍：同胞挚友。《诗经 秦风·无衣》岂曰无衣，与子同袍。\n汉家陵：汉代皇帝的陵墓。\n窼：巢穴。\n高皇：即汉太祖高皇帝刘邦。\n精灵：神仙精怪。\n达命：知命，通达生命。\n长歌：放声高歌。', poem_tags = '人生,抒怀,旷达' WHERE poem_title = '长歌行' AND poem_author = '王昌龄';
UPDATE edu_poem SET poem_translation = '春光幻照之下，山景气象万千。何必初见阴云，就要匆匆回家？\n就算天气晴朗，没有一丝雨意，走入云山深处，也会沾湿衣裳。', poem_notes = '山行：一作“山中”。\n春晖：春光。\n莫：不要。轻阴：阴云。便拟归：就打算回去。\n纵使：纵然，即使。\n云：指雾气、烟霭。', poem_appreciation = '这首诗紧扣诗题中的“留”字，借留客于春山之中，描绘了一幅意境清幽的山水画。\n\n　　首句“山光物态弄春辉”，写出了留客的前提条件——山中万物都在春天的阳光下争奇斗艳，呈现着一派醉人的美景。一个“弄”字出神入化，给山中景物赋予了人的性格，描绘了万物朝气蓬勃的盎然生机。全诗正面描写山景只有这一句诗。因为只有一句，所以诗人就不去描绘一泉一石，一花一木，而是从整体入手，着力表现春山的整个面貌，从万象更新的气象中，渲染出满目生机、引人入胜的意境。因为只有把这一句写得很浓，而且先声夺人，形成一种压倒的优势，“留”才有意义，客人所担心的问题才显得无足轻重。\n\n　　次句“莫为轻阴便拟归”，是诗人对客人的劝留之辞，恰值游兴正浓之际，天空中忽然浮过一片“轻阴”，大有大雨将至之势，这是令客人游兴顿减的惟一客观原因，暗示了客人主观上并非不恋山景的心灵信息。次句与首句紧密相关。由于第一句蕴含丰富，很有分量，第二句虽然是否定了客人的想法，但却显得顺流而下，毫不费力。\n\n　　最后两句“纵使晴明无雨色，入云深处亦沾衣”，采取以退为进、欲擒故纵的笔法，进一步劝慰客人既来之，则安之，不要错过美好春光，涉涉前行。因为客人怕“轻阴”致雨、淋湿衣服，诗人就婉曲地假设了一个晴天游春的问题——在晴天中，因为春季雨水充足，云深雾锁的山中也会水汽蒙蒙，行走在草木掩映的山径上，衣服和鞋子同样会被露水和雾汽打湿的。这也就是说，雨天游山，要“沾衣”；晴天游山，也要“沾衣”，“沾衣”是春日游山无法避免的问题，从某一角度说，这又是春日游山的一大乐趣，那么，就不必为一片“轻阴”而踯躅不前。\n\n　　这两句不只是消极地解除客人的疑虑，而是巧妙地以委婉的方式，用那令人神往的意境，积极地去诱导、去点燃客人心中要欣赏春山美景的火种。\n\n　　这首诗的意境异常清幽，还表现在隽永的哲理启迪上。它告诉人们：事物是复杂的，不应片面地看问题，对待困难也是如此。在人们前进的道路上，要正视困难，勇往直前，“莫为轻阴便拟归”；在克服困难中迎来的美景，才更加赏心悦目，其乐无穷。正由于诗中含义丰富而深刻，所以，这首诗与同类登山春游诗相比就更别具一番悠然不尽的韵味。', poem_tags = '春天,留客,写景' WHERE poem_title = '山中留客' AND poem_author = '张旭';
UPDATE edu_poem SET poem_tags = '写花,芍药,感慨' WHERE poem_title = '卜算子·芍药打团红' AND poem_author = '洪咨夔';
UPDATE edu_poem SET poem_translation = '水和污垢什么时候在一起共存过。仔细看来两个都有又好像两个都没有。我对擦背的人说，今日劳烦你要一直搓背了。只希望能轻点再轻点，我的身上本来也没有什么污垢。', poem_notes = '揩背：揩擦背部。\n尽日：犹终日，整天。', poem_tags = '叙事' WHERE poem_title = '如梦令·水垢何曾相受' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '庭院里一株佳美的树，满树绿叶衬托着茂密的花朵，显得格外春意盎然。\n我攀着树枝，摘下了最好看的一串花朵，想把它赠送给日夜思念的亲人。\n花香充满了我的衣服襟袖之间，可是天遥地远，没人能送到亲人的手中。\n并不是此花有什么珍贵，只是别离太久，想借着花儿表达怀念之情罢了。', poem_notes = '⑴奇树：犹“嘉木”，佳美的树木。\n⑵发华（huā）滋：花开繁盛。华，同“花”。滋，繁盛。\n⑶荣：犹“花”。古代称草本植物的花为“华”，称木本植物的花为“荣”。\n⑷遗（wèi）：赠送，赠与。\n⑸馨（xīn）香：香气。盈：充盈，充积。\n⑹致：送到。\n⑺贵：珍贵。一作“贡”。\n⑻感：感受，感动。别经时：离别之后所经历的时光。', poem_appreciation = '这首诗写一个妇女对远行的丈夫的深切怀念之情。由树及叶，由叶及花，由花及采，由采及送，由送及思。全诗八句，可分作两个层次，每四句为一个层次。\n\n　　前两句诗“攀条折其荣，将以遗所思。”描绘了这样一幅图景：在春天的庭院里，有一株嘉美的树，在满树绿叶的衬托下，开出了茂密的花朵，显得格外生气勃勃。这是环境描写，写出了春意盎然的景象。但首句中的“庭中”就暗示了这里的景色不是大自然中的，而是深闺中的，是一首表现思妇的闺怨诗。\n\n　　于是，思妇就出场了：“攀条折其荣，将以遗所思。”思妇面对这繁花似锦的景象，忍不住攀着枝条，折下了最好看的一束花，要把它赠送给日夜思念的亲人。以花寄情，揭示了诗歌的主旨——对远行人的思念。\n\n　　古诗中写女子的相思之情，常常从季节的转换来发端。因为古代女子受到封建礼教的严重束缚，生活的圈子很狭小，不像许多男子那样，环境的变迁，旅途的艰辛，都可能引起感情的波澜；这些妇女被锁在闺门之内，周围的一切永远是那样沉闷而缺少变化，使人感到麻木。唯有气候的变化，季节的转换，是她们最敏感的，因为这标志着她们宝贵的青春正在不断地逝去，而怀念远方亲人的绵绵思绪，却仍然没有头。\n\n　　诗的开头四句写得很朴素，其中展现的正是人们在日常生活中常常可以见到的一种场面。但是把这种场面和思妇怀远的特定主题相结合，却形成了一种深沉含蕴的意境，引发读者许多联想：这位妇女在孤独中思念丈夫，已经有了很久的日子吧。也许，在整个寒冬，她每天都在等待春天的来临，因为那充满生机的春光，总会给人们带来欢乐和希望。那时候，日夜思念的人儿或许就会回来，春日融融，他们将重新团聚在花树之下，执手相望，倾诉衷肠。可是，如今眼前已经枝叶扶疏，繁花满树了，而站在树下的她仍然只是孤零零的一个，不禁教人感到无限惆怅。再说，如果她只是偶尔地见了这棵树，或许会顿然引起一番惊讶和感慨：时光过得真快，转眼又是一年了！然而这树就生在她的庭院里，她是眼看着叶儿一片片地长，从鹅黄到翠绿，渐渐地铺满了树冠；她是眼见着花儿一朵朵地开，星星点点渐渐地就变成了绚烂的一片。她心里的烦恼也跟着一分一分地堆积起来，这种与日聚增的痛苦，更令人难以忍受。此时此刻，她自然会情不自禁地折下一枝花来，想把它赠送给远方的亲人。因为这花凝聚着她的哀怨和希望，寄托着她深深的爱情。也许，她指待这花儿能够带走一部分相思的苦楚，使那思潮起伏的心能够得到暂时的平静；也许，她希望这故园亲人手中的花枝，能够打动远方游子的心，催促他早日归来。总之，在这简短的四句诗中，蕴含着许多诗人没有写明的内容。\n\n　　自第五句发生转折，进入第二个层次。“馨香盈怀袖”一句紧承上面“攀条折其荣，将以遗所思”两句，同时描绘出花的珍贵和人物的神情。这花是“奇树”的花，它的香气特别浓郁芬芳，不同于一般的杂花野卉，可见用它来表达纯洁的爱情，寄托深切的思念，是再合适不过的。至于人物的神情，诗人虽没有明写，但一个“盈”字，却暗示着：主人公手执花枝，站立了很久。本来，她“攀条折其荣”，是因为思绪久积，情不自禁；可待到折下花来，才猛然想到：天遥地远，这花无论如何也不可能送到亲人的手中。古时交通不便，通信都很困难，更不用说这是一枝容易凋零的鲜花。此时的她，只是痴痴地手执着花儿，久久地站在树下，听任香气充满怀袖而无可奈何。她似乎忘记了时间也忘记了周围的一切，对着花深深地沉入冥想之中。\n\n　　“馨香盈怀袖，路远莫致之”两句简简单单的十个字，描绘了一幅清晰生动的画面；并引发读者进一步想象：这位妇女正在想些什么呢？她是否在回忆往日的幸福？因为这奇树生在他们的庭院之中，往日夫妻双双或许曾在花树下，消磨过许许多多欢乐的时光。在那叶茂花盛的时候，她所爱的人儿，是不是曾经把那美丽的花朵插在她鬓发之间呢？而如今，她时时思念的丈夫正在哪儿？可曾遭遇到什么？她自己所感受的痛苦，远方的人儿也同样感受到了吗？不管她想到了什么，有一点她总是不能摆脱的，那就是对青春年华在寂寞孤苦之中流逝的无比惋惜。古代妇女的生活，本来就那么狭窄单调，唯有真诚的爱情，能够给她们带来一点人生的乐趣。当这点乐趣也不能保有的时候，生活是多么暗淡无光啊！花开花落，宝贵的青春是经不住几番风雨的。\n\n　　再回顾这首诗对于庭中奇树的描写，就可以明明白白地看到，诗人始终暗用比兴的手法，以花来衬托人物，写出人物的内心世界。一方面，花事的兴盛，显示了人物的孤独和痛苦；另一方面，还隐藏着更深的一层意思，那就是：花事虽盛，可是风吹雨打，很快就会落，那正是主人公一生遭遇的象征。在《古诗十九首》的另一篇《冉冉孤生竹》里面，有这样一段话：“伤彼蕙兰花，含英扬光辉；过时而不采，将随秋草萎。”用蕙兰花一到秋天便凋谢了，比喻女主人公的青春不长，红颜易老。这是中国古诗中常用的一种比喻。但是在《庭中有奇树》这一篇中，这一层意思却并不是明白说出，而是留给读者去体会。\n\n　　诗的最后两句“此物何足贵，但感别经时”是主人公无可奈何而说出的自我宽慰的话，同时也点明了全诗的主题。人生苦短，女人也如手中的鲜花，经不起时间的等待，更经受不起风吹雨打。这样的情感意绪，也许就如温庭筠在《望江南》中写的：“梳洗罢，独倚望江楼。过尽千帆皆不是，斜晖脉脉水悠悠。肠断白蘋洲。”一个个希望，一个个失望，到头来也许“红颜未老恩先断，斜倚薰笼坐到明”（白居易《后宫词》），也许“一朝春尽红颜老，花落人亡两不知”（《红楼梦·葬花吟》）。\n\n　　从前面六句来看，诗人对于花的珍奇美丽，本来是极力赞扬的。可是写到最后，突然又说“此物何足贵”，未免使人有点惊疑。其实，对花落下先抑的一笔，正是为了后扬“但感别经时”这一相思怀念的主题。无论说花的可贵还是不足稀奇，都是为了表达同样的思想感情。但这一抑一扬，诗的感情增强了，最后结句也显得格外突出。\n\n　　诗写到这里，算结束了。然而题外之意，仍然耐人寻味：主人公折花，原是为了解脱相思的痛苦，从中得到一点慰藉；而偏偏所思在天涯，花儿无法寄达，平白又添了一层苦恼；相思怀念更加无法解脱。', poem_tags = '古诗十九首,写花,妇女,相思,孤独' WHERE poem_title = '庭中有奇树' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '你说来相会是空话，别后不见踪影；\n醒来楼上斜月空照，听得晓钟初鸣。\n梦里为伤远别啼泣，双双难以呼唤；\n醒后研墨未浓，奋笔疾书写成一信。\n残烛半照金翡翠的被褥，朦朦胧胧；\n麝香熏透芙蓉似的纱帐，软软轻轻。\n当年的刘郎，早已怨恨那蓬山遥远；\n你去的所在，要比蓬山更隔万重岭！\n\n注解\n半笼：半映。指烛光隐约，不能全照床上被褥。\n金翡翠：指饰以金翠的被子。《长恨歌》：“悲翠衾寒谁与共。”\n麝：本动物名，即香獐，其体内的分泌物可作香料。这里即指香气。\n度：透过。\n绣芙蓉：指绣花的帐子。\n刘郎：相传东汉时刘晨、阮肇一同入山采药，遇二女子，邀至家，留半年乃还\n乡。后也以此典喻“艳遇”。\n蓬山：蓬莱山，指仙境。▲', poem_appreciation = '首句“来是空言去绝踪”凌空而起，次句“月斜楼上五更钟”宕开写景，两句若即若离。这要和“梦为远别啼难唤”联系起来，方能领略它的神情韵味。远别经年，会合无缘，夜来入梦，两人忽得相见，一觉醒来，却踪迹杳然。但见朦胧斜月空照楼阁，远处传来悠长而凄清的晓钟声。梦醒后的空寂更证实了梦境的虚幻。如果说第二句是梦醒后一片空寂孤清的氛围，那么第一句便是主人公的叹息感慨。\n\n　　颔联出句追忆梦中情景。“梦为远别啼难唤”，远别的双方，梦中虽得以越过重重阻隔而相会；但即使是在梦中，也免不了离别之苦。梦中相会而来的梦中分别，带来的是难以抑止的梦啼。这样的梦，正反映了长期远别造成的深刻伤痛，强化了刻骨的相思。因此对句“书被催成墨未浓”写梦醒后立刻修书寄远。在强烈思念之情驱使下奋笔疾书的当时，是不会注意到墨的浓淡的，只有在“书被催成”之后，才意外地发现原来连墨也成磨浓。\n\n　　梦醒书成之际，残烛的余光半照着用金钱绣成翡翠鸟图案的帷帐，芙蓉褥上似乎还依稀浮动着麝熏的幽香。六、七句对室内环境气氛的描绘渲染，很富有象征暗示色彩。刚刚消逝的梦境和眼前所见的室内景象在朦胧光影中浑为一片，分不清究是梦境还是实境。烛光半笼，室内若明若暗，恍然犹在梦中；麝香微淡，使人疑心爱人真的来过这里，还留下依稀的余香，上句是以实境为梦境，下句是疑梦境为实境，写恍惚迷离中一时的错觉与幻觉极为生动传神。\n\n　　幻觉一经消失，随之而来的便是室空人杳的空虚怅惘，和对方远隔天涯、无缘会合的感慨。尾联借刘晨重寻仙侣不遇的故事，点醒爱情阻隔，“已恨”“更隔”，层递而进，突出了阻隔之无从度越。\n\n　　全篇围绕“梦”来写离别之恨。但它并没有按远别——思念——入梦——梦醒的顺序来写。而是先从梦醒时情景写起，然后将梦中与梦后、实境与幻觉来柔合在一起，创造出疑梦疑真、亦梦亦真的艺术境界，最后才点明蓬山万重的阻隔之恨，与首句遥相呼应。这样的艺术构思，曲折宕荡，有力地突出爱情阻隔的主题和梦幻式的心理氛围，使全诗充满迷离恍惚的情怀。', poem_tags = '唐诗三百首,记梦,爱情,思念' WHERE poem_title = '无题·来是空言去绝踪' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '响箭鸣叫着冲上云霄，草原之上无风，天地间一片安宁，显得响箭的声音更加清脆洪亮。\n数百个有着碧绿眼珠的矫健的外族骑士，纷纷提着带金勒向云端看去。', poem_notes = '鸣骹（xiāo）：同“鸣髇”，也叫“鸣镝”，一种发出响声的箭，古称“嚆矢”。\n骑：骑兵，这里指骑在马上的人。\n提：提收、提控，这里指拉紧马的缰绳。金勒：金属制作、装饰的带有嚼口的马笼头。', poem_tags = '古诗三百首,边塞,写人' WHERE poem_title = '塞上' AND poem_author = '柳开';
UPDATE edu_poem SET poem_translation = '再次来到苏州，只觉得万事皆非。曾与我同来的妻子为何不能与我同归呢？我好像是遭到霜打的梧桐，半生半死；又似白头失伴的鸳鸯，孤独倦飞。\n原野上，绿草上的露珠刚刚被晒干。我流连于旧日同栖的居室，又徘徊于垄上的新坟。躺在空荡荡的床上，听着窗外的凄风苦雨，平添几多愁绪。今后还有谁再为我深夜挑灯缝补衣衫！', poem_notes = '鹧鸪天：词牌名。因此词有“梧桐半死清霜后”句，贺铸又名之为“半死桐”。\n阊（chāng）门：苏州城西门，此处代指苏州。\n何事：为什么。\n梧桐半死：枚乘《七发》中说，龙门有桐，其根半生半死（一说此桐为连理枝，其中一枝已亡，一枝犹在），斫以制琴，声音为天下之至悲，这里用来比拟丧偶之痛。清霜后：秋天，此指年老。\n“原上草”二句，形容人生短促，如草上露水易干。语出《薤露》露晞明朝更复落，人死一去何时归。晞：(xī)干。\n旧栖：旧居，指生者所居处。新垅：新坟，指死者葬所。', poem_appreciation = '这是一首情真意切、语深辞美、哀伤动人的悼亡词，是中国文学史上与潘岳《悼亡》、元稹《遣悲怀》、苏轼《江城子·乙卯正月二十日夜记梦》等同题材作品并传不朽的名篇。\n\n　　上片开头两句用赋，直抒胸臆，写作者这次重回苏州经过阊门，一想起和自己相濡以沫的妻子已长眠地下，不禁悲从中来，只觉得一切都不顺心，遂脱口而出道：“同来何事不同归？”接以“同来何事不同归”一问，问得十分无理，实则文学往往是讲“情”而不讲“理”的，极“无理”之辞，正是极“有情”之语。\n\n　　“梧桐半死清霜后，头白鸳鸯失伴飞”两句，借用典故，用半死梧桐和失伴鸳鸯比喻自己知天命之年却成为鳏夫，孑身独存的苦状，寂寞之情，溢于言表。“清霜”二字，以秋天霜降后梧桐枝叶凋零，生意索然，比喻妻子死后自己也垂垂老矣。“头白”二字一语双关，鸳鸯头上有白毛（李商隐《石城》：“鸳鸯两白头。”），而词人此时已年届五十，也到了满头青丝渐成雪的年龄。这两句形象地刻画出了作者的孤独的凄凉。\n\n　　过片“原上草 ，露初晞“承上启下，亦比亦兴，既是对亡妻坟前景物的描写，又借露水哀叹妻子生命的短暂。同时这里也是用典，汉乐府丧歌《薤露》：“薤上露，何易晞！”用原草之露初晞暗指夫人的新殁，是为比，紧接上片，与“梧桐半死”共同构成“博喻”；同时，原草晞露又是荒郊坟场应有的景象，是为兴，有它寻夫先路，下文“新垅”二字的出现就不显得突兀。\n\n　　下片最后三句复用赋体。“旧栖新垅两依依。“因言“新垅”，顺势化用陶渊明《归园田居五首》其四“徘徊丘垅间，依依昔人居”诗意，牵出“旧栖”。居所依依，却天人永隔。下文即很自然地转入到自己“旧栖”中的长夜不眠之思——“空床卧听南窗雨，谁复挑灯夜补衣！”夜间辗转难眠中，昔日妻子挑灯补衣的情景历历在目，却再难重见。这既是抒情最高潮，也是全词中最感人的两句。这两句，平实的细节与意象中表现妻子的贤慧，勤劳与恩爱，以及伉俪间的相濡以沫，一往情深，读来令人哀惋凄绝，感慨万千。\n\n　　这首词在艺术构思上最突出之处在于将生者与死者紧密联系在一起，作者词笔始终关合自己与妻子双方，其情之深已侵入文章构思当中，如：\n\n　　“重过阊门万事非 ，同来何事不同归。”此处上半句写自己所见，下半句抒发对亡妻的思念。“梧桐半死清霜后，头白鸳鸯失伴飞”这是写作者自身。“原上草 ，露初晞“这是写妻子。“旧栖新垄两依依。“这是两个人在一起写。“空床卧听南窗雨，谁复挑灯夜补衣”与开头一样，前一句写自己，后一句写妻子。以夫妻间体贴关怀、情感交融的温馨生活为基础写成；”旧坟新垄“句有夫妻感情已经超越时间，超越生死之感。\n\n　　“重过阊门万事非 ，同来何事不同归”借叙事抒情；“梧桐半死清霜后，头白鸳鸯失伴飞”借比喻抒情；“原上草 ，露初晞，旧栖新垄两依依“借景物抒情；“空床卧听南窗雨，谁复挑灯夜补衣”借行为举止抒情；语言上两次运用反诘句，把情感推向高潮，动人心弦。', poem_tags = '宋词三百首,婉约,悼亡,典故,思念' WHERE poem_title = '半死桐·重过阊门万事非' AND poem_author = '贺铸';
UPDATE edu_poem SET poem_translation = '国家兴亡衰败自有其时运，吴人又何苦埋怨是西施使他们国家灭亡的呢？\n如果西施知道怎样颠覆吴国，那么后来让越国灭亡的又是谁呢？', poem_notes = '家国：家与国。亦指国家。\n何苦：用反问语气表示不值得（可用否定式）。\n解：懂，明白，理解。\n亡：灭亡。', poem_appreciation = '历来咏西施的诗篇多把亡吴的根由归之于女色，客观上为封建统治者开脱或减轻了罪责。罗隐这首小诗的特异之处，就是反对这种传统观念，破除了“女人是祸水”的论调，闪射出新的思想光辉。\n\n　　“家国兴亡自有时，吴人何苦怨西施。”一上来，诗人便鲜明地摆出自己的观点，反对将亡国的责任强加在西施之类妇女身上。这里的“时”，即时会，指促成家国兴亡成败的各种复杂因素。“自有时”表示吴国灭亡自有其深刻的原因，而不应归咎于西施个人，这无疑是正确的看法。有人认为这里含有宿命论成分，其实是出于误解。“何苦”，劝解的口吻中含有嘲讽意味：你们自己误了国家大事，却想要归罪一个弱女子，真是何必呢！当然，挖苦的对象并非一般吴人，而是吴国统治者及其帮闲们。\n\n　　“西施若解倾吴国，越国亡来又是谁？”后面这两句巧妙地运用了一个事理上的推论：如果说，西施是颠覆吴国的罪魁祸首，那么，越王并不宠幸女色，后来越国的灭亡又能怪罪于谁呢？尖锐的批驳通过委婉的发问语气表述出来，丝毫不显得剑拔弩张，而由于事实本身具有坚强的逻辑力量，读来仍觉锋芒逼人。\n\n　　罗隐反对嫁罪妇女的态度是一贯的。僖宗广明年间（880—881），黄巢起义军攻入长安，皇帝仓皇出逃四川，至光启元年（885）才返回京城。诗人有《帝幸蜀》一首绝句记述这件事：“马嵬山色翠依依，又见銮舆幸蜀归。泉下阿蛮应有语，这回休更怨杨妃。”“阿蛮”即“阿瞒”的通假，是唐玄宗的小名。前一回玄宗避安史之乱入蜀，于马嵬坡缢杀杨妃以杜塞天下人口。这一回僖宗再次酿成祸乱奔亡，可找不到新的替罪羊了。诗人故意让九泉之下的玄宗出来现身说法，告诫后来的帝王不要诿过于人，讽刺是够辛辣的。联系《西施》作比照，一咏史，一感时，题材不同，而精神实质并无二致。这样看来，《西施》的意义又何止为历史作翻案而已！', poem_tags = '咏史怀古,哲理' WHERE poem_title = '西施' AND poem_author = '罗隐';
UPDATE edu_poem SET poem_translation = '为死别往往使人泣不成声， 而生离却常令人更加伤悲。江南山泽是瘴疬流行之处， 被贬谪的人为何毫无消息？\n老朋友你忽然来到我梦里， 因为你知道我常把你记忆。梦中的你恐不会是鬼魂吧， 路途遥远生与死实难估计。\n灵魂飘来是从西南青枫林， 灵魂返回是由关山的黑地。你如今陷入囹圄身不由己， 哪有羽翼飞来这北国之地？\n明月落下清辉洒满了屋梁， 迷离中见到你的颜容憔悴。水深浪阔旅途请多加小心， 不要失足落入蛟龙的嘴里。', poem_notes = '吞声：极端悲恸，哭不出声来。恻恻：悲痛。开头两句互文。\n瘴疠：疾疫。古代称江南为瘴疫之地。逐客：被放逐的人，此指李白。\n故人：老朋友，此指李白。这是杜甫常用的越过一层、从对方写起、连带双方的手法。故人知我长相思念而入我梦，则我之思念自不必言，而双方之相知相忆又自然道出。\n恐非平生：疑心李白死于狱中或道路。这两句说：我梦到的该不是你的魂魄吧？山高路远，谁知道你是否还活着啊！\n枫林：李白放逐的西南之地多枫林。关塞：杜甫流寓的秦州之地多关塞。李白的魂来魂往都是在夜间，所以说“青”“黑”。\n罗网：捕鸟的工具，这里指法网。羽翼：翅膀。这两句说：既已身陷法网，系狱流放，怎么会这样来往自由呢？\n颜色：指容貌。\n这句指李白的处境险恶，恐遭不测。祝愿和告诫李白要多加小心。', poem_appreciation = '“死别已吞声，生别常恻恻。”诗要写梦，先言别；未言别，先说死，以死别衬托生别，极写李白流放绝域、久无音讯在诗人心中造成的苦痛。开头便如阴风骤起，吹来一片弥漫全诗的悲怆气氛。\n\n　　“故人入我梦，明我长相忆。”不说梦见故人，而说故人入梦；而故人所以入梦，又是有感于诗人的长久思念，写出李白幻影在梦中倏忽而现的情景，也表现了诗人乍见故人的喜悦和欣慰。但这欣喜只不过一刹那，转念之间便觉不对了：“君今在罗网，何以有羽翼？”你既累系于江南瘴疠之乡，怎么就能插翅飞出罗网，千里迢迢来到我身边呢？联想世间关于李白下落的种种不祥的传闻，诗人不禁暗暗思忖：莫非他真的死了？眼前的他是生魂还是死魂？路远难测啊！乍见而喜，转念而疑，继而生出深深的忧虑和恐惧，诗人对自己梦幻心理的刻画，是十分细腻逼真的。\n\n　　“魂来枫林青，魂返关塞黑。”梦归魂去，诗人依然思量不已：故人魂魄，星夜从江南而来，又星夜自秦州而返，来时要飞越南方青郁郁的千里枫林，归去要渡过秦陇黑沉沉的万丈关塞，多么遥远，多么艰辛，而且是孤零零的一个。“落月满屋梁，犹疑照颜色。”在满屋明晃晃的月光里面，诗人忽又觉得李白那憔悴的容颜依稀尚在，凝神细辨，才知是一种朦胧的错觉。相到故人魂魄一路归去，夜又深，路又远，江湖之间，风涛险恶，诗人内心祝告着、叮咛着：“水深波浪阔，无使蛟龙得。”这惊骇可怖的景象，正好是李白险恶处境的象征，这惴惴不安的祈祷，体现着诗人对故人命运的殷忧。这里，用了两处有关屈原的典故。“魂来枫林青”，出自《楚辞·招魂》：“湛湛江水兮上有枫，目极千里兮伤春心，魂兮归来哀江南！”旧说系宋玉为招屈原之魂而作。“蛟龙”一语见于梁吴均《续齐谐记》：东汉初年，有人在长沙见到一个自称屈原的人，听他说：“吾尝见祭甚盛，然为蛟龙所苦。”通过用典将李白与屈原联系起来，不但突出了李白命运的悲剧色彩，而且表示着杜甫对李白的称许和崇敬。', poem_tags = '唐诗三百首,典故,写人' WHERE poem_title = '梦李白二首·其一' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_tags = '写人,读书' WHERE poem_title = '司马光好学' AND poem_author = '朱熹';
UPDATE edu_poem SET poem_translation = '玉洁冰清的风骨是自然的，哪里会去理会那些瘴雾，它自有一种仙人的风度。海上之仙人时不时派遣来探视芬芳的花丛，那倒挂着绿羽装点的凤儿。\n它的素色面容施铅粉还怕弄脏，就算雨雪洗去妆色也不会褪去那朱唇样的红色。高尚的情操已经追随向晓云的天空，就不会想到与梨花有同一种梦想。', poem_notes = '玉骨：梅花枝干的美称。唐冯贽《云仙杂记》卷二：“袁丰居宅后，有六株梅……（丰）叹曰：‘烟姿玉骨，世外佳人，但恨无倾城笑耳。’即使妓秋蟾出比之。”瘴雾：犹瘴气。南方山林中的湿热之气。\n冰姿：淡雅的姿态。仙风：神仙的风致。\n芳丛：丛生的繁花。\n绿毛幺凤：岭南的一种珍禽，似鹦鹉。\n涴（wò）：沾污，弄脏。\n唇红：喻红色的梅花。\n高情：高隐超然物外之情。\n“不与”句：苏轼自注：“诗人王昌龄，梦中作梅花诗。”', poem_appreciation = '这首词明为咏梅，暗为悼亡，是苏轼为悼念毅然随自己贬谪岭南惠州的侍妾朝云而作。词中所描写的惠州梅花，实为朝云美丽的姿容和高洁的人品的化身。\n\n　　词的上阕写惠州梅花的风姿、神韵。起首两句，突兀而起，说惠州的梅花生长在瘴疠之乡，却不怕瘴气的侵袭，是因这它有冰雪般的肌体、神仙般的风致。接下来两句说它的仙姿艳态，引起了海仙的羡爱，海仙经常派遣使者来到花丛中探望；这个使者，原来是倒挂在树上的绿毛小鸟（状如幺凤）。以上数句，传神地勾勒出岭南梅花超尘脱俗的风韵。\n\n　　下阕追写梅花的形貌。“素面常嫌粉涴”，岭南梅天然洁白的容貌，是不屑于用铅粉来妆饰的；施了铅粉，反而掩盖了它的自然美容。岭南的梅花，花叶四周皆红，即使梅花谢了（洗妆），而梅叶仍有红色（不褪唇红），称得上是绚丽多姿，大可游目骋情。面对着这种美景的东坡，却另有怀抱：“高情已逐晓云空，不与梨花同梦”。东坡慨叹爱梅的高尚情操已随着晓云而成空无，已不再梦见梅花，不像王昌龄梦见梨花云那样做同一类的梦了。句中“梨花”即“梨花云”，“云”字承前“晓云”而来。晓与朝叠韵同义，这句里的“晓云”，可以认为是朝云的代称，透露出这首词的主旨所在。\n\n　　这一首悼亡词是借咏梅来抒发自己的哀伤之情的，写的是梅花，而且是惠州特产的梅花，却能很自然地绾合到朝云身上来。上阕的前两句，赞赏惠州梅花的不畏瘴雾，实质上则是怀念朝云对自己的深情。下阕的前两句，结合苏轼《殢人娇·赠朝云》一词看，明显也是写朝云。再结合末两句来看，哀悼朝云的用意，更加明朗。\n\n　　这首咏梅词空灵蕴藉，言近旨远，给人以深深的遐思。词虽咏梅，实有寄托，其中蕴有对朝云的一往情深和无限思恋。作者既以人拟花，又借比喻以花拟人，无论是写人还是写花都妙在得其神韵。张贵《词源》论及咏物词时指出：“体物稍真，则拘而不畅；模写差远，则晦而不明。要须收纵联密，用事合题，一段意思，全在结句，斯为绝妙。”以这一标准来衡量此词，可以窥见其艺术技巧的精湛。', poem_tags = '婉约,咏物,梅花,悼亡' WHERE poem_title = '西江月·梅花' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '小船横渡春天的江面，我睡在船中看两岸翠绿的山峦，其间有一座红色的高楼。那高高的栖霞楼直入云端，笑语声阵阵飘出，这是太守您在雅聚啊，美丽歌女都已醉意朦胧。演奏音乐声音高亢悲怨。这歌声回旋，悠扬动听，飘荡在云水之间。您虽然年事已高，但风流潇洒仍一如从前。我梦游春江，回头只看到您在烟波之中。\n推开枕头坐起身朱，这才发现是一场梦，眼前不见老友，只有空荡荡的江面，明月的清光无限。太守您懂得功成身退之道，已然早早去到苏州隐居了。您一定还记得当年我们在黄州之时吧，我们曾四处游玩，十分快乐。您是多情之人，料想您也定在梦中梦到我了，那情形大概就和我梦到您是一样的吧。', poem_notes = '水龙吟：词牌名，又名“龙吟曲”“庄椿岁”“小楼连苑”等。双调一百零二字，上片十一句四仄韵，下片十一句五仄韵。\n栖霞楼：唐宋时期黄州的四大名楼之一。最早为江西临川人王义庆所建，后为闾丘孝终守黄州时重建。\n闾（lǘ）丘大夫孝终公显：即闾丘孝终，字公显。作者友人。曾任黄州知州，致仕（退休）后归苏州故里。\n胜绝：绝佳的名胜。\n扁（piān）舟：小船。\n鼓笛慢：据考证指词牌“水龙吟”。清王亦清等编《钦定词谱》卷三十：“‘水龙吟’，姜菱词注无射商，俗名越调。……吕渭老词名‘鼓笛慢’。”\n致仕：退休。\n截：直渡。\n红楼：指栖霞楼。\n云间：形容栖霞楼之高。\n高会：雅聚。\n危柱哀弦：指演奏音乐，乐声凄绝。危，高，谓定音高而厉。柱，筝瑟之类乐器上的枕木，移至高处则声高厉。哀弦，指声音悲怨。\n“艳歌”两句：用秦青“响遏行云”典故。《列子·汤问》：“薛谭学讴于秦青，未穷青之技，自谓尽之；遂辞归。秦青弗止。饯于郊衢， 抚节悲歌，声振林木，响遏行云。薛谭乃谢求反，终身不敢言归。”绕云萦水，形容歌声高亢回旋，悠扬动听。\n故人老大：言闾丘孝终年事己高。老大，年岁大。\n惘（wǎng）然：迷茫的样子。\n“五湖”三句：五湖，泛指太湖一带地方。西子，西施。春秋时期，越相范蠡辅佐越王勾践灭吴。勾践命他为上将军，但他知道大名之下难以久居，就携带宝珠，乘舟浮海，终不返。传说范蠡还携带西施出走。\n云梦南州：指黄州，因其在古云梦泽之南。\n武昌东岸：亦指黄州。武昌为今湖北鄂城，与黄州隔江相对。长江经黄州时南流，黄州在武昌东岸。\n多情：多情的人，指闾丘孝终。\n端来：准来，定来。\n参（cēn）差（cī）是：大概如此，指如自己梦见闾丘孝终的情形。唐白居易《长恨歌》：“中有一人字太真，雪肤花貌参差是。”', poem_appreciation = '这首词前面的小序交代了背景和写作经过。词虽然是写梦，但一开篇却像是正在展开的令人兴致飞扬的现实生活。\n\n　　“小舟横截春江，卧看翠壁红楼起。”“横截春江”，就是序中所说的“扁舟渡江”。长江波深浪阔，渡江的工具不过是古代的木帆船，而句中所用的警示极快当的“横截”二字，可见词人那种飘飘欲仙的豪迈之气。“卧看”，意态闲逸。又因在舟中“卧看”高处，岸上的翠碧红楼必然更有矗天之势。春江水是横向展开的，翠碧红楼是纵向的。一纵一横，展示出一幅飞动而开展的图景。\n\n　　“云间笑语，使君高会，佳人半醉。危柱哀弦，艳歌余响，绕云萦水。”六句写闾丘公显在栖霞楼宴会宾客，席上笑语，飞出云间；美人半醉，伴随弦乐唱着艳歌，歌声响遏行云，萦回于江面。这里从听觉感受，写出乐宴的繁华。而由于词人是在舟中，并非身临高会，所以生出想象和怅望：“念故人老大，风流未减，独回首、烟波里。”前两句由对宴会的描写，转入对闾丘公显的评说，着重点其”风流“。后二句回首往事，从怅望里写出茫茫烟波和渺渺情怀。虽是那种特定环境中的情与景，但扑朔迷离，已为向下片过渡做了准备。\n\n　　下片开头，把上片那些真切得有如实际生活的描写，一笔启开。“推枕惘然不见，但空江、月明千里。”仅仅十三个字，就写出了由梦到醒的过程，乃至心情与境界的变化。“惘然不见”点心境，与下句“空江、月明千里”实际上是点与染的关系。醒后周围景色空旷，与梦中繁华对照，更加重了惘然失落之感。不过，正因为茫然失落，而又面对江月千里的浩淼景象，更容易引起浮想联翩。以下至篇末，即由此产生三重想想。“五湖闻道，扁舟归去，仍携西子。”是想象中闾丘公显的现实境况：他过着退休生活，像范蠡一样，携同美人，游览五湖。“扔携西子”应上面”风流未减“”佳人半醉“等描写，见出闾丘公显的生活情调一如既往。“云梦南州，武昌东岸，昔游应记。”追思闾丘公显。作者曾在这梦之南、武昌之东的黄州一带游览，其情其景，仍然留在闾丘公显与作者记忆里。“料多情梦里，端来见我，也参差是。”进一步推想重拾情谊的老友，会再梦中前来相见，刚才那真切的情景，差不多就是吧。这三层，由设想对方处境，一直到设想“梦来见我”，回应了上片，首尾相合，构成一个艺术整体。而在行文上，由“江月”到“五湖”，到武昌东岸，再由昔游引出今梦。种种意念活动互相发生，完全如行云流水之自然。\n\n　　作者写一场美好的梦。所梦的故人风流自在，重视情谊。彼此间既有美好的昔游，又有似真似幻的“梦来见我”的精神交会。其情调是浪漫的，因而有人认为这首词带有仙气。这从作者精神活动的广阔自由，从笔致的空灵浩淼看，并非没有根据。但如果因此认为词中所梦所想，都是也在一种神仙般的快乐心境上产生的，恐怕也不符合实际。苏轼谪居黄州，是他受打击非常沉重的时期。在实际生活中孤独寂寞，与亲朋隔绝离散，甚至音信不通。而另一方面，苏轼性格中又有豁达的、善于在逆境中自我派遣的特点。因之像词中所写的梦境和梦醒后的怀想，实质上是在孤独寂寞中，对自由、对友情、对生活中美好事物的一种向往。作者实际处境的孤独寂寞，虽然被他所写的色彩缤纷的梦境、昔游等所笼罩，但又并非掩盖无余。\n\n　　此词上下片衔接处的“空回首，烟波里”与“推枕惘然不见，但空江月明千里”，感情之怅惘，身世之孤孑还是很清楚的。结尾处不说自己梦故人，而想象故人梦来见自己。正像一切事物在超负荷重需要有超剂量的补偿一样，是由异常寂寞的心境上产生出来的浪漫幻想。这使得这首词在风流潇洒中又有沉郁之致。这种沉郁，正是诗人实际处境、心情的一种反应。', poem_tags = '记梦,向往,自由,友情' WHERE poem_title = '水龙吟·黄州梦过栖霞楼' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_tags = '宋词三百首,咏史怀古,豪放' WHERE poem_title = '浪淘沙令·伊吕两衰翁' AND poem_author = '王安石';
UPDATE edu_poem SET poem_translation = '月宫的老兔老兔寒蟾在悲泣天色，云楼门窗半开月光斜照粉壁惨白。\n月亮像玉轮轧过露水沾湿了团光，在桂花香陌欣逢身带鸾佩的仙娥。\n俯视三座神山之下茫茫沧海桑田，世间千年变幻无常犹如急奔骏马。\n遥望中国九州宛然九点烟尘浮动，那一汪海水清浅像是从杯中倾泻。', poem_notes = '梦天：梦游天上。\n老兔寒蟾：神话传说中住在月宫里的动物。屈原《天问》中曾提到月中有兔。《淮南子·览冥训》中有后羿的妻子姮娥偷吃神药，飞入月宫变成蟾的故事。汉乐府《董逃行》中的“白兔捣药长跪虾蟆丸”，说的就是月中的白兔和蟾蜍。此句是说在一个幽冷的月夜，阴云四合，空中飘洒下阵阵寒雨，就像兔和蟾在哭泣。\n云楼句：忽然云层变幻，月亮的清白色的光斜穿过云隙，把云层映照得像海市蜃楼一样。\n玉轮句：月亮带着光晕，像被露水打湿了似的。\n鸾佩：雕刻着鸾凤的玉佩，此代指仙女。\n三山：指海上的三座神山蓬莱、方丈、瀛洲。这里却指东海上的三座山。\n走马：跑马。\n齐州：中州，即中国。《尚书·禹贡》言中国有九州。\n泓：量词，指清水一道或一片。', poem_appreciation = '浪漫主义诗歌的突出特点是想象奇特。在这首诗中，诗人梦中上天，下望人间，也许是有过这种梦境，也许纯然是浪漫主义的构想。\n\n　　开头四句，描写梦中上天。第一句“老兔寒蟾泣天色”是说，古代传说，月里住着玉兔和蟾蜍。句中的“老兔寒蟾”指的便是月亮。幽冷的月夜，阴云四合，空中飘洒下来一阵冻雨，仿佛是月里玉兔寒蟾在哭泣似的。第二句“云楼半开壁斜白”是说，雨飘洒了一阵，又停住了，云层裂开，幻成了一座高耸的楼阁；月亮从云缝里穿出来，光芒射在云块上，显出了白色的轮廓，有如屋墙受到月光斜射一样。第三句“玉轮轧露湿团光”是说，下雨以后，水气未散，天空充满了很小的水点子。玉轮似的月亮在水汽上面辗过，它所发出的一团光都给打湿了。以上三句，都是诗人梦里漫游天空所见的景色。第四句则写诗人自己进入了月宫。“鸾佩”是雕着鸾凤的玉佩，这里代指仙女。这句是说：在桂花飘香的月宫小路上，诗人和一群仙女遇上了。这四句，开头是看见了月亮；转眼就是云雾四合，细雨飘飘；然后又看到云层裂开，月色皎洁；然后诗人飘然走进了月宫；层次分明，步步深入。\n\n　　下面四句，又可以分作两段。“黄尘清水三山下，更变千年如走马。”是写诗人同仙女的谈话。这两句可能就是仙女说出来的。“黄尘清水”，换句常见的话就是“沧海桑田”：“三山”原来有一段典故。葛洪的《神仙传》记载说：仙女麻姑有一回对王方平说：“接待以来，已见东海三为桑田；向到蓬莱，水又浅于往日会时略半耳。岂将复为陵陆乎？”这就是说，人间的沧海桑田，变化很快。“山中方七日，世上已千年”，古人往往以为“神仙境界”就是这样，所以诗人以为，人们到了月宫，回过头来看人世，就会看出“千年如走马”的迅速变化了。\n\n　　最后两句，是诗人“回头下望人寰处”所见的景色。“齐州”指中国。中国古代分为九州，所以诗人感觉得大地上的九州犹如九点“烟尘”。“一泓”等于一汪水，这是形容东海之小如同一杯水被打翻了一样。这四句，诗人尽情驰骋幻想，仿佛他真已飞入月宫，看到大地上的时间流逝和景物的渺小。浪漫主义的色彩是很浓厚的。\n\n　　李贺在这首诗里，通过梦游月宫，描写天上仙境，以排遣个人苦闷。天上众多仙女在清幽的环境中，你来我往，过着一种宁静的生活。而俯视人间，时间是那样短促，空间是那样渺小，寄寓了诗人对人事沧桑的深沉感慨，表现出冷眼看待现实的态度。想象丰富，构思奇妙，用比新颖，体现了李贺诗歌变幻怪谲的艺术特色。', poem_tags = '梦游,想象,月宫,哲理' WHERE poem_title = '梦天' AND poem_author = '李贺';
UPDATE edu_poem SET poem_translation = '这愁绪什么时候才是尽头？滴落在空空台阶上的细雨终于止住，夜晚如此清冷，正是适宜葬花的天气。你离我而去已整整三年，纵然是一场大梦，也早就应该醒来了。你一定是觉得人间没有趣味吧，不如泥土深处的黄泉，虽冷冷清清，但它能埋葬所有的愁怨。你倒是去了那清净之地，而我们生生世世不离不弃的约定，就这样被你抛弃。\n如果可以寄书信到黄泉该多好，好让我知道你这些年过得怎样，是谁在身旁照顾你。夜深了，我仍然辗转反侧，无法入睡，不忍听他们的续弦之议。让我们来生再结为知己吧，就怕真的有来生，我们两个仍然无法长相厮守。而今，我的泪水已经流尽，纸钱烧成灰，飘忽不定。', poem_notes = '金缕曲：词牌名。又名《贺新郎》《乳燕飞》，亦作曲牌名。一百十六字，前后片各六仄韵。\n葬花天气：指春末落花时节，大致是农历五月，这里既表时令，又暗喻妻子之亡如花之凋谢。\n夜台：指坟墓。\n钗钿约：钗钿即“金钗”、“钿合”，女子饰物。暗指爱人间的盟誓。\n重泉：即“黄泉”、“九泉”，指生死两隔。\n双鱼：书信，典出古乐府。\n湘弦：即湘灵鼓瑟之弦。传说舜之妃子溺湘水而亡，后为水神，古代诗词中常用琴瑟代指夫妻，这里指纳兰不忍再弹奏那哀怨凄婉的琴弦，否则会勾起悼亡的哀思。', poem_appreciation = '《金缕曲·亡妇忌日有感》是纳兰性德悼亡词中的代表作。其悼亡词有四十首之多，皆血泪交溢，语痴入骨。此词尤称绝唱。词从空阶滴雨，仲夏葬花写来，引起伤春之感和悼亡之思；又以夜台幽远，音讯不通，以至来生难期，感情层层递进，最后万念俱灰。此生已矣，来世为期？全词虚实相间，实景与虚拟，所见与所思，糅合为一，历历往事与冥冥玄想密合无间。纳兰词“哀感顽艳”、“令人不能卒读”，于此可见一斑。\n\n　　词起得突兀：“此恨何时已？”此乃化用李之仪《卜算子》词“此水几时休，此恨何时已”成句，劈头一个反问，道出词人心中对卢氏之死深切绵长、无穷无尽的哀思。作者既恨新婚三年竟成永诀，欢乐不终而哀思无限；又恨人天悬隔，相见无由，值此亡妇忌日，这种愁恨更有增无已。“滴空阶、寒更雨歇，葬花天气”三句，更渲染出悼亡的环境氛围。“滴空阶”二句，化用温庭筠《更漏子》下阕词意，温词曰：“梧桐树，三更雨。不道离情正苦。一叶叶，一声声，空阶滴到明。”能清晰听到夜雨停歇之后，残雨滴空阶之声的人，一定有着郁闷难排的心事，温飞卿是为离情所苦，纳兰容若则为丧妻之痛，死别之伤痛自然远过于生离，故其凄苦更甚。卢氏死于农历五月三十日，此时已是夏天，争奇斗艳的百花已大都凋谢，故称“葬花天气”。此处有两措辞当注意：其一明属夏夜，却称“寒更”，此非自然天气所致，乃寂寞凄凉之心境感受使然；其二是词人不谓“落花”，而称“葬花”，“葬”与“落”平仄相同自非韵律所限。人死方谓“葬”，用“葬”字则更切合卢氏之死，如春花一样美艳的娇妻，却如落花一样“零落成泥碾作尘”。如今之“葬花天气”，妻死整整三年，仿佛大梦一场，但果真是梦也早该醒了。“不及夜台尘土隔，冷清清一片埋愁地”二句承上句来，人间无味，倒不如一抔黄土，与人世隔开，虽觉冷清，却能将愁埋葬。夜台，即墓穴。埋愁地，亦指墓地。卢氏葬于玉河皂荚屯祖茔。“钗钿约，竟抛弃”二句，再从自身痛苦生发，谓你因觉人间无味而撒手归去，却不顾我俩当年白头到老的誓言，竟使我一人痛苦地生活在人间。古时夫妇常以钗钿作为定情之物，表示对爱情的忠诚。钗为古代妇女的首饰之一，乃双股笄，钿，即金花，为珠宝镶嵌的首饰，亦由两片合成。上片写词人对亡妇的深切怀念。\n\n　　下片开头，词人期望能了解卢氏亡故以后的情况。这当然是以人死后精神不死，还有一个幽冥的阴间世界为前提的。此亦时代局限使然，也未尝不是词人的精诚所至，自然无可厚非。“重泉若有双鱼寄。好知他、年来苦乐，与谁相依？”“重泉”，即黄泉，九泉，俗称阴间。双鱼，指书信。古乐府有“客从远方来，遗我双鲤鱼。呼儿烹鲤鱼，中有尺素书”之诗，后世故以双鲤鱼指书信。倘能与九泉之下的亡妻通信，一定得问问她，这几年生活是苦是乐，他和谁人伴。此乃由生前之恩爱联想所及。词人在另两首题为《沁园春》的悼亡词中也说：“记绣榻闲时，并吹红雨；雕栏曲处，同倚斜阳。”又曰：“最忆相看，娇讹道字，手剪银灯自泼茶。”由生前恩爱，而关心爱人死后的生活，钟爱之情，可谓深入骨髓。词人终夜辗转反侧，难以成眠。欲以重理湘琴消遣，又不忍听这琴声，因为这是亡妻的遗物，睹物思人，只会起到“举杯消愁”“抽刀断水”的作用，而于事无补。湘弦，原指湘妃之琴。顾贞观有和性德《采桑子》云：“分明抹丽开时候，琴静东厢，……孤负新凉，淡月疏棂梦一场。”由此可以看出卢氏在日，夫妇常在东厢理琴。理琴，即弹琴。捎信既难达，弹琴又不忍，词人只好盼望来生仍能与她结为知己。据叶舒崇所撰卢氏墓志，性德于其妻死后，“悼亡之吟不少，知己之恨尤多。”词人不仅把卢氏当作亲人，也当成挚友，在封建婚姻制度下，这是极难得的。词人欲“结个他生知己”的愿望，仍怕不能实现：“还怕两人俱薄命，再缘悭、剩月零风里。”词人甚至担心两人依旧薄命，来生的夫妻仍不能长久。缘悭，指缘份少；剩月零风，好景不长之意。读词至此，不能不使人潸然泪下。新婚三年，便生死睽隔，已足以使人痛断肝肠，而期望来生也不可得，这个现实不是太残酷了吗？在封建制度下，婚姻不以爱情为基础，故很少美满的，难得一两对恩爱夫妻，也往往被天灾人祸所拆散。许多痴情男女，只得以死殉情，以期能鬼魂相依。词人期望来生再结知己，已是进了一步。但又自知无望，故结尾“清泪尽，纸灰起”二句，格外凄绝。', poem_tags = '悼亡,伤春,怀念' WHERE poem_title = '金缕曲·亡妇忌日有感' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '张衡，字平子，是南阳郡西鄂县人。张衡年轻时就擅长写文章，曾到“三辅”一带游学，趁机进了洛阳，在太学学习，于是通晓五经，贯通六艺，虽然才华比一般的人高，但并不因此而骄傲自大。（他）平时举止从容，态度平静，不喜欢与世俗之人交往。永元年间，他被推举为孝廉，却不应荐，屡次被公府征召，都没有就任。此时社会长期太平无事，从王公贵族到一般官吏，没有不过度奢侈的。张衡于是摹仿班固的《两都赋》写了《二京赋》，用它来（向朝廷）讽喻规劝。（这篇赋，他）精心构思润色，用了十年才完成。大将军邓骘认为他的才能出众，屡次征召他，他也不去应召。\n\n　　张衡善于器械制造方面的巧思，尤其在天文气象和历法的推算等方面很用心。汉安帝常听说他擅长术数方面的学问，命公车特地征召他，任命他为郎中。两次迁升为太史令。于是，张衡就精心研究考核阴阳之学（包括天文气象历法诸种学问），精辟地研究出测天文仪器的正确道理，制作浑天仪，著成《灵宪》《算罔论》等书籍，论述极其详尽。\n\n　　（汉）顺帝初年，（张衡）又两次转任，又做了太史令之职。张衡不趋附当时的那些达官显贵，他所担任的官职，总是多年得不到提升。自他从太史令上离任后，过了五年，又回到这里。\n\n　　顺帝阳嘉元年，张衡又制造了候风地动仪。这个地动仪是用纯铜铸造的，直径有尺，上下两部分相合盖住，中央凸起，样子像个大酒樽。外面用篆体文字和山龟鸟兽的图案装饰。内部中央有根粗大的铜柱，铜柱的周围伸出八条滑道，还装置着枢纽，用来拨动机件。外面有八条龙。龙口各含一枚铜丸，龙头下面各有一个蛤蟆，张着嘴巴，准备接住龙口吐出的铜丸。仪器的枢纽和机件制造得很精巧，都隐藏在酒尊形的仪器中，覆盖严密得没有一点缝隙。如果发生地震，仪器外面的龙就震动起来，机关发动，龙口吐出铜丸，下面的蛤蟆就把它接住。铜丸震击的声音清脆响亮，守候机器的人因此得知发生地震的消息。地震发生时只有一条龙的机关发动，另外七个龙头丝毫不动。按照震动的龙头所指的方向去寻找，就能知道地震的方位。用实际发生的地震来检验仪器，彼此完全相符，真是灵验如神。从古籍的记载中，还看不到曾有这样的仪器。有一次，一条龙的机关发动了，可是洛阳并没有感到地震，京城的学者都奇怪它这次没有应验。几天后，驿站上传送文书的人来了，证明果然在陇西地区发生地震，大家这才都叹服地动仪的绝妙。从此以后，朝廷就责成史官根据地动仪记载每次地震发生的方位。\n\n　　当时政治昏暗，中央权力向下转移，张衡于是给皇帝上书陈述这些事。后来被升为侍中，皇帝让他进皇宫，在皇帝左右，对国家的政事提意见。皇帝曾经向张衡问起天下人所痛恨的是谁。宦官害怕张衡说出他们，都给他使眼色，张衡于是没对皇帝说实话。但那些宦党终究害怕张衡成为祸患，于是一起诋毁他。张衡常常思谋自身安全的事，认为福祸相因，幽深微妙，难以看清，于是写了《思玄赋》表达和寄托自己的情思。\n\n　　（汉顺帝）永和初年，张衡调离京城，担任河间王的相。当时河间王骄横奢侈，不遵守制度法令；又有很多豪族大户，豪门大户他们一起胡作非为。张衡上任之后治理严厉，整饬法令制度，暗中探得奸党的姓名，一下子同时逮捕，拘押起来，于是上下敬畏恭顺，称赞政事处理得好。（张衡）在河间相位上任职三年，给朝廷上书，请求辞职回家，朝廷任命他为尚书。张衡活了六十二岁，于永和四年去世。', poem_notes = '节选自《后汉书·张衡传》（中华书局版）。范晔（-），字蔚宗，南朝宋顺阳（在今河南淅川东）人，历史学家。\n南洋西鄂：南阳郡的西鄂县，在今河南南阳。\n属（zhǔ）文：写文章。属，连缀。\n游于三辅：在三辅一带游学。游，游历，游学，指考察学习。\n京师：指东汉首都洛阳（今河南省洛阳市）。\n太学：古代设在京城的全国最高学府，西汉武帝开始设立。\n遂：于是。\n通：通晓，全面透彻地理解。\n贯：贯通，与“通，为近义词。\n五经：汉武帝时将《诗》《书》《礼》《易》《春秋》定名为“五经”。\n六艺：指礼乐射御书数六种学问和技艺。\n高于世：比世上的人高明。于：比。\n骄尚之情：骄傲自大的情绪。尚：矜夸自大。\n从容：从容稳重，不急躁。淡静：恬淡宁静，不追慕名利。\n永元中，举孝廉不行：永元：东汉和帝刘肇的年号（公元年-年）。\n连辟公府不就：连，屡次。辟，（被）召请（去做官）。公府，三公的官署。东汉以太尉司徒司空为三公。不就：不去就职。以上几句的主语“衡”，承前省略。\n时天下承平日久：时，当时。承平，太平，指国家持续地太平安定。日久，时间长。\n王侯：封王封侯的大官贵族。\n莫：无指代词，表示“没有谁”的意思。\n逾侈：过度奢侈。\n乃：于是，就。\n拟：模仿。\n班固（-）：字孟坚，东汉著名的史学家和文学家。\n《两都》：指《两都赋》，分《西都赋》《东都赋》。\n《二京赋》：指《西京赋》《东京赋》。\n因：介词，通过。后省宾语“之”。\n以：连词。\n讽谏：用委婉的语言进行规劝而不直言其事。\n精思傅会：精心创作的意思。\n乃：才。\n邓骘（zhi）：东汉和帝邓皇后的哥哥，立安帝，以大将军的身份辅佐安帝管理政事。\n奇其才：认为他的才能出众。奇，认为……奇，形容词的意动用法。奇：奇特，少有的。\n累召：多次召请。应：接受。\n机巧：设计制造机械的技艺。巧，技巧技艺。\n致思：极力钻研。致，极，尽。\n阴阳：指日月运行规律。\n历算：指推算年月日和节气。\n于：对于。于……：介宾短语后置，译时提前作状语。\n雅闻：常听说。雅，副词，素来，常。术学：关于术数方面的学问，指天文历算等。\n公车：汉代官署名称，设公车令。\n特征：对有特出才德的人指名征召，为的与平常的乡举里选相区别，故称特征。\n拜：任命，授给官职。\n郎中：官名。\n再迁：再，两次。迁，调动官职。\n太史令：东汉时掌管天文历数的官，与西汉以前掌管天象历法兼有修史之责的太史令职责不完全相同。\n遂乃：于是就。\n研核：研究考验。\n阴阳：哲学名词，指两种对立的事物，如日月，寒暑等，这里指天象历算。\n妙尽：精妙地研究透了。\n璇玑：玉饰的测天仪器。\n正：道理。\n浑天仪：一种用来表示天象的仪器，类似的天球仪。\n《灵宪》：一部历法书。\n《算罔》：一部算术书。\n详明：详悉明确。\n再转：两次调动官职。第一次由太史令调任公车司马令，第二次由公车司马令又调任太史令。\n复：又。\n当世，指权臣大官。\n辄：常常，总是。\n积年：多年。徙：指调动官职。\n自去史职，五载复还：自；自从，表时间。\n阳嘉：东汉顺帝刘保的年号（公元--）。\n候风地动仪：测验地震的仪器。据竺可桢考证，这是两种仪器，一是测验风向的候风仪，一是测验地震的地动仪。\n以：用。\n员径八尺：员径：圆的直径。员，通“圆”。\n合盖隆起：上下两部分相合盖住，中央凸起。隆，高。\n尊：同“樽”，古代盛酒器。\n饰：装饰。“饰”后省宾语“之”，“之”代候风地动仪。\n以：用。据有人研究，候风地动仪外部八方书写不同的篆文以表明方位，脚部装饰山形，东南西北分别绘画代表四方的龙朱雀虎玄武（龟蛇）。\n都柱：大铜柱。都，大。“都柱”就是地动仪中心的震摆，它是一根上大下小的柱子，哪个方向发生地震，柱子便倒向哪边。傍，同“旁”，旁边。\n施关发机：设置关键（用来）拔动机件，意思是每组杠杆都装上关键，关键可以拨动机件（指下句所说的“龙”）。\n外有八龙，首衔铜丸：龙，指龙形的机件。首，头。\n下有蟾蜍（chánchú），张口承之：下，指龙首下面。蟾\n牙机巧制：互相咬合制作精巧的部件。\n尊中：酒樽形的仪器里面。\n覆盖周密无际：指仪器盖子与樽形仪器相接处没有缝隙。\n如有地动，尊则振龙：地动，地震。则，就。振，振动。机发吐丸，而蟾蜍衔之。\n机发：机件拨动。\n而：顺承连词，不必译出。\n振声激扬，伺者因此觉知：激扬，这里指声音响亮。伺者，守候观察候风地动仪的人。\n发机：拨动了机件。\n七首：指其余七龙之首。龙首，互文，都指龙首。\n验之以事，即以事验之：验，检验，验证。\n自书典所记，未之有也：自，在，可译为“在……中”。\n尝一龙机发，而地不觉动，京师学者咸怪其无征：尝，曾经，曾有一次。而，可是。\n驿：驿使，古时驿站上传递文书的人。\n至：指来到京师。\n果：果然。\n陇西：汉朝郡名，在今甘肃省兰州市临洮县陇西县一带。“陇西”前省介词“于”（在）。\n于是皆服其妙：其，它，代候风地动仪。妙，巧妙，神奇。\n乃：便。\n地动：地震。\n所从方起：从哪个方位发生。\n时：当时。损：腐败。因：于是。\n迁：升迁。\n帷幄：指帝王。天子居处必设帷幄，故称。\n讽议：讽谏议论；婉转地发表议论。\n左右：身边。\n尝问天下所疾恶者：尝，曾经。疾，憎恨；恶，指坏人坏事。\n目之：给他递眼色。目：名词活用为动词。\n诡对：不用实话对答。\n阉竖：对宦官的蔑称。\n谗：毁谤。\n图身之事：图谋自身安全的事。\n吉凶倚伏：祸福相因。出《老子》：祸兮福所倚，福兮祸所伏。\n幽微难明：幽深微妙，难以看清。\n宣寄情志：表达和寄托自己的情意。\n永和初，出为河间相：永和：也是东汉顺帝的年号（公元-）。\n时国王骄奢，不遵典宪：时，当时。国王，即河间王刘政。典宪，制度法令。\n豪右：豪族大户，指权势盛大的家族。\n不轨：指行动越出常轨的事，即违反法纪的事。\n衡下车，治威严，整法度：下车：官员初到任。治威严，树立威信。治，整治。整法度，整顿法纪制度。\n阴知奸党名姓，一时收禽：阴知，暗中察知。\n上下肃然，称为政理：肃然，这里是敬畏恭顺不敢为非做歹的意思。\n视事三年，上书乞骸（hái）骨：视事，这里指官员到职工作。乞骸骨， 古代官吏因年老请求退职的一种说法。\n尚书，官名，不同朝代的尚书职权不一样，东汉时是在宫廷中协助皇帝处理政务的官。\n年六十二，永和四年卒（zú）。卒：死。', poem_tags = '高中文言文,赞美,写人,传记' WHERE poem_title = '张衡传' AND poem_author = '范晔';
UPDATE edu_poem SET poem_translation = '清瘦的竹影和着诗句，梅花的香气伴着我入梦。\n可惜我的心情就像今晚的月亮，迟迟不肯落下西厢房。', poem_notes = '西厢：传统汉族建筑四合院里面西面的厢房。', poem_appreciation = '赏析 　　前两句一从视觉、一从嗅觉的角度来描写诗人居处的清幽境界。“竹”和“诗”，一为自然之物，一为社会之物，二者本无从比较，但诗人用一个“瘦”字把二者紧密地联系在一起，竹具有清瘦的形象，诗具有清瘦的风格。“瘦”字用得生新，为全诗定下了清瘦的意境氛围。而“入梦香”则将现实与梦境联系起来，梅花夜间在月光的朗照下也喷出清香，已不同凡响，而这香气还伴着诗人进入梦乡，则香气之浓郁、之悠长可以想见。将竹与梅这样的自然物象与诗与梦这样的人为之物炼在一句之中，这就构成了情在景中、景在情中，情景混融莫分的高妙意境。前两句字面上完全没有“月”，但透过竹影和梅香，我们可以感受到“月”自在其中。在后两句中，诗人便将“月”和盘托出。可怜者，可爱也。当诗人信步庭院时，月光与竹影、梅香是那样的和谐；而回到西厢房时，这月光却不能“下西厢”，这多么地令人遗憾！诗中透露出一股月与人不能互通情愫的遗憾或幽怨的情绪。诗人遗憾或幽怨的是什么？也许是有情人天各一方，不能互通情怀；也许是君臣阻隔，上下无法沟通；也许什么都不是，只是诗人置身此时此景之中的一种朦朦胧胧的感受而已。 ▲', poem_tags = '古诗三百首,竹子,梅花,月亮,感伤' WHERE poem_title = '绝句' AND poem_author = '王庭筠';
UPDATE edu_poem SET poem_translation = '译文 我巍巍大唐的猎猎旌旗在阴山飘扬， 突厥胡人胆敢来犯定叫他有来无还。 作为子民我愿以此身终生报效国家， 大丈夫建功立业何须活着返回家园。', poem_appreciation = '戴叔纶的《塞上曲》共两首，为七言绝句。这是第二首。这首较之第一首《塞上曲·军门频纳受降书》浅明了许多，里面有一典故，就是“生入玉门关”。这“生入玉门关”原本是定远侯班超的句子，是说班超出使西域30多年，老时思归乡里，上书言“臣不敢望到九泉郡，但愿生入玉门关”。班超30年驻使西域，为国家民族鞠躬尽瘁，老而思乡求返，本无可咎。但以戴叔纶之见，班超的爱国主义还是不够彻底——他不应提出“生入玉门关”，也无须提出“生入玉门关”，安心报国就是了。戴叔纶的爱国之切是好的，义无反顾也是好的，但放到班超这个实际例子上看，却不是那么近人情。知道了这个典故，全诗意思迎刃而解。前一联讲的是汉家重兵接敌，对胡兵一骑都不会放过。而后就是上文说过的典故——不回玉门关了，要以必死信念战胜胡兵，报国靖边以宁。\n\n　　戴诗同前人述志慷慨的边塞诗风一体同出，大都是吟咏壮士一去不复还的豪言志向，至于时代特征的分析、判断及有关主张，则稍嫌抽象，倘如不将上诗注为唐中期的戴诗，而随便说成为别个时代的，也是很难提出疑问来的。', poem_tags = '边塞,爱国' WHERE poem_title = '塞上曲二首·其二' AND poem_author = '戴叔伦';
UPDATE edu_poem SET poem_translation = '译文 总是今日又今日，今日能有多少呢！ 今天又没做事情，那么这件事情何时才能完成呢？ 人这一生能有几个今日，今日不做事情，真是可惜啊！ 假如说姑且等到明天到了再去做，但是明天还有明天的事情啊！ 现在为诸位写这首《今日》诗，请从今日就开始努力工作吧！', poem_tags = '古诗三百首,惜时' WHERE poem_title = '今日歌' AND poem_author = '文嘉';
UPDATE edu_poem SET poem_translation = '屈原名平，与楚国的王族同姓。他曾担任楚怀王的左徒。见闻广博，记忆力很强，通晓治理国家的道理，熟悉外交应对辞令。对内与怀王谋划商议国事，发号施令；对外接待宾客，应酬诸侯。怀王很信任他。\n　　上官大夫和他同在朝列，想争得怀王的宠幸，心里嫉妒屈原的才能。怀王让屈原制订法令，屈原起草尚未定稿，上官大夫见了就想强行更改它（想邀功），屈原不赞同，他就在怀王面前谗毁屈原说：“大王叫屈原制订法令，大家没有不知道的，每一项法令发出，屈原就夸耀自己的功劳说：除了我，没有人能做的。”怀王很生气，就疏远了屈原。\n　　屈原痛心怀王惑于小人之言，不能明辨是非，小人混淆黑白，使怀王看不明白，邪恶的小人妨碍国家，端方正直的君子则不为朝廷所容，所以忧愁苦闷，写下了《离骚》。“离骚”，就是遭到忧愁的意思。天是人类的原始，父母是人的根本。人处于困境就会追念本源，所以到了极其劳苦疲倦的时候，没有不叫天的；遇到病痛或忧伤的时候，没有不叫父母的。屈原行为正直，竭尽自己的忠诚和智慧来辅助君主，谗邪的小人来离间他，可以说到了困境了。诚信却被怀疑，忠实却被诽谤，能够没有怨恨吗？屈原之所以写《离骚》，其原因大概是从怨愤引起的。《国风》虽然多写男女爱情，但不过分而失当。《小雅》虽然多讥讽指责，但并不宣扬作乱。像《离骚》，可以说是兼有二者的特点了。它对远古上溯到帝喾，近世称述齐桓公，中古称述商汤和周武王，用来讽刺当时的政事。阐明道德的广阔崇高，国家治乱兴亡的道理，无不完全表现出来。他的文笔简约，词意精微，他的志趣高洁，行为廉正。就其文字描写来看，不过寻常事物，但它的旨趣是极大的（因为关系到国家的治乱），举的是近事，而表达的意思却十分深远。由于志趣高洁，所以文章中称述的事物也是透散着芬芳的，由于行为廉正，所以到死也不为奸邪势力所容。他独自远离污泥浊水之中，像蝉脱壳一样摆脱浊秽，浮游在尘世之外，不受浊世的玷辱，保持皎洁的品质，出污泥而不染。可以推断，屈原的志向，即使和日月争辉，也是可以的。\n　　屈原已被罢免。后来秦国准备攻打齐国，齐国和楚国结成合纵联盟互相亲善。秦惠王对此担忧。就派张仪假装脱离秦国，用厚礼和信物呈献给楚王，对怀王说：“秦国非常憎恨齐国，齐国与楚国却合纵相亲，如果楚国确实能和齐国绝交，秦国愿意献上商、於之间的六百里土地。”楚怀王起了贪心，信任了张仪，就和齐国绝交，然后派使者到秦国接受土地。张仪抵赖说：“我和楚王约定的只是六里，没有听说过六百里。”楚国使者愤怒地离开秦国，回去报告怀王。怀王发怒，大规模出动军队去讨伐秦国。秦国发兵反击，在丹水和淅水一带大破楚军，杀了八万人，俘虏了楚国的大将屈匄，于是夺取了楚国的汉中一带。怀王又发动全国的兵力，深入秦地攻打秦国，交战于蓝田。魏国听到这一情况，袭击楚国一直打到邓地。楚军恐惧，从秦国撤退。齐国终于因为怀恨楚国，不来援救，楚国处境极端困窘。第二年，秦国割汉中之地与楚国讲和。楚王说：“我不愿得到土地，只希望得到张仪就甘心了。”张仪听说后，就说：“用一个张仪来抵当汉中地方，我请求到楚国去。”到了楚国，他又用丰厚的礼品贿赂当权的大臣靳尚，通过他在怀王宠姬郑袖面前编造了一套谎话。怀王竟然听信郑袖，又放走了张仪。这时屈原已被疏远，不在朝中任职，出使在齐国，回来后，劝谏怀王说：“为什么不杀张仪？”怀王很后悔，派人追张仪，已经来不及了。\n　　后来，各国诸侯联合攻打楚国，大败楚军，杀了楚国将领唐昧。这时秦昭王与楚国通婚，要求和怀王会面。怀王想去，屈原说：“秦国是虎狼一样的国家，不可信任，不如不去。”怀王的小儿子子兰劝怀王去，说：“怎么可以断绝和秦国的友好关系！”怀王终于前往。一进入武关，秦国的伏兵就截断了他的后路，于是扣留怀王，强求割让土地。怀王很愤怒，不听秦国的要挟。他逃往赵国，赵国不肯接纳。只好又到秦国，最后死在秦国，尸体运回楚国安葬。\n　　怀王的长子顷襄王即位，任用他的弟弟子兰为令尹。楚国人都抱怨子兰，因为他劝怀王入秦而最终未能回来。屈原也为此怨恨子兰，虽然流放在外，仍然眷恋着楚国，心里挂念着怀王，念念不忘返回朝廷。他希望国君总有一天醒悟，世俗总有一天改变。屈原关怀君王，想振兴国家改变楚国的形势，一篇作品中，都再三表现出来这种想法。然而终于无可奈何，所以不能够返回朝廷。由此可以看出怀王始终没有觉悟啊。\n　　国君无论愚笨或明智、贤明或昏庸，没有不想求得忠臣来为自己服务，选拔贤才来辅助自己的。然而国破家亡的事接连发生，而圣明君主治理好国家的多少世代也没有出现，这是因为所谓忠臣并不忠，所谓贤臣并不贤。怀王因为不明白忠臣的职分，所以在内被郑袖所迷惑，在外被张仪所欺骗，疏远屈原而信任上官大夫和令尹子兰，军队被挫败，土地被削减，失去了六个郡，自己也被扣留死在秦国，为天下人所耻笑。这是不了解人的祸害。《易经》说：“井淘干净了，还没有人喝井里的水，使我心里难过，因为井水是供人汲取饮用的。君王贤明，天下人都能得福。”君王不贤明，难道还谈得上福吗！令尹子兰得知屈原怨恨他，非常愤怒，终于让上官大夫在顷襄王面前说屈原的坏话。顷襄王发怒，就放逐了屈原。\n　　屈原到了江滨，披散头发，在水泽边一面走，一面吟咏着。脸色憔悴，形体面貌像枯死的树木一样毫无生气。渔父看见他，便问道：“您不是三闾大夫吗？为什么来到这儿？”屈原说：“整个世界都是混浊的，只有我一人清白；众人都沉醉，只有我一人清醒。因此被放逐。”渔父说：“聪明贤哲的人，不受外界事物的束缚，而能够随着世俗变化。整个世界都混浊，为什么不随大流而且推波助澜呢？众人都沉醉，为什么不吃点酒糟，喝点薄酒？为什么要怀抱美玉一般的品质，却使自己被放逐呢？”屈原说：“我听说，刚洗过头的一定要弹去帽上的灰沙，刚洗过澡的一定要抖掉衣上的尘土。谁能让自己清白的身躯，蒙受外物的污染呢？宁可投入长流的大江而葬身于江鱼的腹中。又哪能使自己高洁的品质，去蒙受世俗的尘垢呢？”于是他写了《怀沙》赋。因此抱着石头，就自投汨罗江而死。\n　　屈原死了以后，楚国有宋玉、唐勒、景差等人，都爱好文学，而以善作赋被人称赞。但他们都效法屈原辞令委婉含蓄的一面，始终不敢直言进谏。在这以后，楚国一天天削弱，几十年后，终于被秦国灭掉。自从屈原自沉汨罗江后一百多年，汉代有个贾谊，担任长沙王的太傅。路过湘水时，写了文章来凭吊屈原。\n　　太史公说：我读《离骚》、《天问》、《招魂》、《哀郢》，为他的志向不能实现而悲伤。到长沙，经过屈原自沉的地方，未尝不流下眼泪，追怀他的为人。看到贾谊凭吊他的文章，文中又责怪屈原如果凭他的才能去游说诸侯，哪个国家不会容纳，却自己选择了这样的道路！读了《服鸟赋》，把生和死等同看待，认为被贬和任用是不重要的，这又使我感到茫茫然失落什么了。', poem_notes = '楚之同姓：楚王族本姓芈（mǐ米），楚武王熊通的儿子瑕封于屈，他的后代遂以屈为姓，瑕是屈原的祖先。楚国王族的同姓。屈、 景、昭氏都是楚国的王族同姓。\n楚怀王：楚威王的儿子，名熊槐，公元前328年至前299年在位。左徒：楚国官名，职位仅次于令尹。\n博闻强志：见识广博，记忆力强。志，同“记”\n明于治乱：通晓国家治乱的道理\n娴于辞令：擅长讲话。娴，熟悉。辞令，指外交方面应酬交际的语言。\n上官大夫：楚大夫。上官，复姓。\n宪令：国家的重要法令。\n属（zhǔ主）：写作。\n《离骚》：屈原的代表作，自叙生平的长篇抒情诗。关于诗题，后人有二说。一释“离”为“罹”的通假字，离骚就是遭受忧患。二是释“离”为离别，离骚就是离别的忧愁。\n反本：追思根本。反，通“返”。惨怛（dá达）：忧伤。\n盖：表推测性判断，大概。\n帝喾（kù库）：古代传说中的帝王名。相传是黄帝的曾孙，号高辛氏，齐桓：即齐桓公，名小白，春秋五霸之一，公元前685年至前643年在位。汤：商朝的开国君主。武：指周武王，灭商建立西周王朝。\n条贯：条理，道理。“见”同“现”。\n指：同“旨”。迩（ěr耳）：近。“见”同“现”。\n称物芳：指《离骚》中多用兰、桂、蕙、芷等香花芳草作比喻。\n疏：离开。濯淖（zhuó nào浊闹）：污浊。蝉蜕（tuì退）：这里是摆脱的意思。获：玷污。滋：通“兹”，黑。皭（jiào叫）然：洁白的样子。泥（niè聂）：通“涅”，动词，染黑。滓（zǐ子）：污黑。\n绌（chù处）：通“黜”，废，罢免。指屈原被免去左徒的职位。\n从（zòng纵）：同“纵”。从亲，合纵相亲。当时楚、齐等六国联合抗秦，称为合纵，楚怀王曾为纵长。惠王：秦惠王，公元前337年至311年在位。\n张仪：魏人，主张“连横”，游说六国事奉秦国，为秦惠王所重。详：通“佯”。委：呈献。质：通“贽”，信物。\n商、於（wū污）：秦地名。商，在今陕西商州市东南。於，在今河南内乡东。\n丹、淅（xī希）：二水名。丹水发源于陕西商州市西北，东南流入河南。淅水，发源于南卢氏县，南流而入丹水。屈匄：（gài丐）：楚大将军。汉中：今湖北西北部、陕西东南部一带。\n蓝田：秦县名，在今陕西蓝田西。\n邓：春秋时蔡地，后属楚，在今河南邓州市一带。\n明年：指楚怀王十八年（公元前311年）。\n靳尚：楚大夫。一说即上文的上官大夫。\n顾反：回来。反，通“返”。\n唐昧：楚将。楚怀王二十八年（公元前301年），秦、齐、韩、魏攻楚，杀唐昧。\n秦昭王：秦惠王之子，公元前306年至前251年在位。\n武关：秦国的南关，在今陕西省商州市东。\n内：同“纳”。\n顷襄王：名熊横，公元前298年至前262年在位。令尹：楚国的最高行政长官。\n虽放流：以下关于屈原流放的记叙，时间上有矛盾，文意也不连贯，可能有脱误。\n世：三十年为一世。\n《易》：即《周易》，又称《易经》。这里引用的是《易经·井卦》的爻辞。渫（xiè谢）：淘去泥污。这里以淘干净的水比喻贤人。\n被：通“披”。披发，指头发散乱，不梳不束。\n三闾大夫：楚国掌管王族昭、屈、景三姓事务的官。\n哺（bū埠）：吃，食。糟：酒渣。啜（chuò辍）：喝。醨（lí离）：薄酒。\n瑾、瑜：都是美玉。为：表示疑问的语气词。\n察察：洁白的样子。汶（mén门）汶：浑浊的样子。\n皓（hào）皓：莹洁的样子。温蠖（huò获）：尘滓重积的样子。\n《怀沙》：在今本《楚辞》中，是《九章》的一篇。令人多以为系屈原怀念长沙的诗。\n汨（mì密）罗：江名，在湖南东北部，流经汨罗县入洞庭湖。\n宋玉：相传为楚顷襄王时人，屈原的弟子，有《九辩》等作品传世。唐勒、景差：约与宋玉同时，都是当时的词赋家。\n“数十年”句：公元前223年秦灭楚。\n贾生：即贾谊（公元前200年前168年），洛阳（今河南洛阳东）人。西汉政论家、文学家。长沙王：指吴差，汉朝开国功臣吴芮的玄孙。太傅：君王的辅助官员。\n湘水：在今湖南省境内，流入洞庭湖。书：指贾谊所写的《吊屈原赋》。\n太史公：司马迁自称。\n《天问》、《招魂》、《哀郢》：都是屈原的作品。《招魂》一说为宋玉所作。《哀郢》是《九章》中的一篇。\n《鵩鸟赋》：贾谊所作。去：指贬官放逐。就：指在朝任职。\n如：去、到\n稚子：小儿子', poem_appreciation = '和从《史记》中选入中学课本的其它几篇人物传记（《廉颇蔺相如列传》、《鸿门宴》、《信陵君窃符求赵》、《毛遂自荐》、《陈涉世家》）相比，本文的特色是：\n\n　　选材上，《屈原列传》不具备曲折、生动、完整的故事情节，而是根据文献记载，粗线条地勾勒人物的生平事迹；\n\n　　写法上，记叙和议论相结合。全文四个部分都有“传”有“评”，因“传”而“评”，以“评”点“传”。议论方式各不相同，第一部分为评介式，第二部分为结语式，第三部分为陈述式，第四部分为比照式。\n\n　　语言上，本文具有浓厚的抒情色彩，叙中有情、倾向鲜明；议中有情、直抒胸臆。作者运用对偶、对比、排比、反复、比喻等修辞手法，增强了语言表达效果。\n\n　　司马迁推崇屈原有两个方面：推崇他正确的政治主张和伟大的人格；推崇他在语言艺术上的高深造诣。\n\n　　司马迁认为屈原联齐抗秦的主张是正确的。屈原是楚国的贵族。当时，秦国兵力最强。但是楚国和齐国从亲，是可以抵抗强秦的，因为楚国疆土最大，齐国财力最富，而且楚、齐从亲，其他山东之国也会跟楚齐一道合纵来共同对付秦国。如果楚王能始终用屈原的外交主张，并且修明内政，那当时的天下还不知鹿死谁手。本传用了很大的篇幅叙述楚国和齐、秦的关系，从历史的教训来证明屈原联齐抗秦的主张的正确。当楚怀王重用屈原任为左徒的时候，齐、楚从亲，秦国不敢侵犯。等到楚怀王听信了上官大夫的毁谤而疏远了屈原之后，秦国就令张仪来离间齐楚的关系，破坏两国的联盟，以便各个击破。张仪骗楚王说，楚国如能和齐国绝交，秦愿献商于之地六百里。楚怀王贪图便宜，便当真和齐国绝交。张仪又说是献地六里，不是六百里。楚怀王大怒，就兴兵伐秦。楚国没有了齐国的援助，弄得损兵折将，丧权失地。这才又命屈原出使于齐，和齐国恢复邦交。秦国又说把汉中地还给楚国来讲和。楚怀王因为恨透了张仪，说不愿得地，愿得张仪才甘心。张仪居然来到楚国，收买了楚王的宠臣靳尚和宠姬郑袖，竟又安然返国。\n\n　　等到屈原从齐国回来，问楚王为什么不杀张仪，他后悔已经来不及了。这样，又上了秦国的当。其后，诸侯兵击楚，楚又大败。其后，秦又骗楚怀王到秦国去，屈原劝他不要去，可是他听了他的幼子子兰的话到秦国去了。果然一到秦国，秦国就不放他回去，要挟他割让土地，终至客死于秦。他的儿子顷襄王忘却血海深仇，反而向秦屈膝，重用亲秦派子兰等人，放逐屈原。后来楚竟为秦所灭。\n\n　　这些事实充分表明了楚国亲齐，秦国就不敢侵犯；亲秦，就吃秦国的大亏。司马迁对屈原的政治才能是异常推崇的。本传说屈原的《离骚》是“上称帝喾，下道齐桓，中述汤武，以刺世事。明道德之广崇，治乱之条贯，靡不毕见。”他还慨叹说：“人君无愚智贤不肖，莫不欲求忠以自为，举贤以自佐。然亡国破家相随属，而圣君治国累世而不见者，其所谓忠者不忠，而所谓贤者不贤也。”可见司马迁认为屈原所理想的政治就是唐虞三代那样的政治，认为屈原主张举贤授能。从屈原的作品中，我们可以看出屈原这种政治倾向是强烈的。\n\n　　《离骚》里说：“皇天无私阿兮，览民德焉错辅。夫惟圣哲以茂行兮，苟得用此下土。瞻前而顾后兮，相观民之计极。夫孰非义而可用兮，孰非善而可服?”屈原反复地论述历代兴亡，认为亡是由于残害忠良，而兴是由于举贤授能。他主张要替人民打算，要选贤与能，这是有民主思想的因素的。因此，司马迁说他能够明道德之广崇，治乱之条贯，是正确的。司马迁不仅赞成他的贤能政治的主张，并且认为屈原就是贤能兼备的人。他说：“怀王以不知忠臣之分，故内惑于郑袖，外欺于张仪，疏屈平而信上官大夫、令尹子兰，兵挫地削，亡其六郡，身客死于秦，为天下笑。此不知人之祸也。”\n\n　　然而司马迁对屈原的推崇，最主要的还在于屈原的高尚人格和斗争精神。因为楚怀王昏庸贪婪，对外则亲齐亲秦摇摆不定，对内则宠任奸佞，听信谗言。屈原虽系贵族，并非近亲；虽有远大的政治眼光和卓越的政治才能，并没得到长久的重用。《离骚》里说：“世溷浊而嫉贤兮，好蔽美而称恶。闺中既以邃远兮，哲王又不悟。”正深刻地反映了他所处的时代的楚国政治情况。屈原为了坚持自己的理想，挽救楚国的危亡，坚决地起来斗争。他愤怒地控诉了贵族当权派的无耻：“众皆竞进以贪婪兮，凭不厌乎求索。”“固时俗之工巧兮，规矩而改错。背绳墨以追曲兮，竞周容以为度。”他痛斥他们弄得黑白不分，是非颠倒。《怀沙》里说：“玄文幽处兮，蒙谓之不章；离娄微睇兮，瞽以为无明。变白而为黑兮，倒上以为下；凤皇在兮，鸡雉翔舞。”他指斥他们将要把国家弄到濒于危亡的地步：“惟夫党人之偷乐兮，路幽昧以险隘。”因此，他宣称他决不妥协：“何方圜之能周兮?夫孰异道而相安?”屈原修德立行，忠心耿耿，原想导君于尧舜之治，可是怀王竟然不识，反而信谗疏远：“荃不察余之中情兮，反信谗而怒。”楚国弄到濒于危亡，怀王是应该负责任的，屈原对他也是不能无怨的。他说：“怨灵修之浩荡兮，终不察夫民心。”司马迁对屈原的为坚持理想而斗争的精神是歌颂的，对屈原的心情是深刻了解的。他叙述屈原作《离骚》的原因是这样的：“屈平疾王听之不聪也，谗谄之蔽明也，邪曲之害公也，方正之不容也，故忧愁幽思而作《离骚》。”又说《离骚》“自怨生”。说“疾”，说“怨”，可见司马迁认为《离骚》之作正体现了屈原的斗争精神。', poem_tags = '古文观止,写人,传记' WHERE poem_title = '屈原列传' AND poem_author = '司马迁';
UPDATE edu_poem SET poem_translation = '阳光照耀江水，腾起了薄薄的烟雾，两岸人家彩绘的屋檐相连,画梁相接。江面上荷花丛生秋光恬淡，看沙鸥正在江面上一次次飞舞盘旋，家家珠帘里飘出香风。美丽的船只好像从天边驶来，酒家的旗帜迎风招展。真让人喜爱啊，江南！', poem_notes = '“一江烟水”句：意思是说阳光照耀江水，腾起了薄薄的烟雾。烟水：江南水气蒸腾有如烟雾。晴岚：岚是山林中的雾气，晴天天空中仿佛有烟雾笼罩，故称晴岚（晴天空中仿佛有烟雾笼罩）。\n画檐：绘有花纹、图案的屋檐。\n芰（jì）荷：芰是菱的古称。芰荷指菱叶与荷叶。\n“卷香风”句：“即十里香风卷珠帘。”化用杜牧《赠别》诗句“春风十里扬州路，卷上珠帘总不如。”\n飐（zhǎn）：风吹物使之颤动\n杀：用在动词后，表示程度深。', poem_appreciation = '这是一首写江南水乡秋光的小令，这首曲写得很美，在读者面前展开的是风光秀丽、景物宜人，一幅多姿多彩的江南水乡秋景画。\n\n　　全曲八句，七句写景，最后用一句抒情句作结，并点题。\n\n　　多水是江南的特色，水面风光是江南所特有的，因此开头两句，作者就紧紧抓住这特点来进行描绘。一条浩浩的大江，在晴日照耀下，雾气迷蒙，影影绰绰，增添了几分迷茫，似梦如幻，恍惚迷离。两岸人烟稠密，真是“烟柳画桥，风帘翠幕，参差十万人家。”江南水乡秋景中，最大的特征无过于菱与荷了，被作者称赞的就是“三秋桂子，十里荷花，羌管弄晴，菱歌泛夜”（同前）这前三句是对江南景物的总体描写，接下来四句分别写了最有特色的具有代表性的事物。先看水面上沙鸥自由飞舞，再回到岸上，这第五句与杜牧的《赠别》联系起来，令人不知这香风是从荷花中飘来，还是从珠帘里美人身上飘下来。珠帘里似乎还有若隐若现的美人的身影，不禁令人神往。抬头远眺，看到画船儿从天边驶来，这祥华贵的游船上，当然还会有悠扬悦耳的乐声，在视觉、嗅觉中又加上了听觉，令人心旷神怡。正在这时，又看到了酒店用以招引客人的酒旗正在风中飘扬，于是在荷香、脂粉香中，又加上了阵阵扑鼻的酒香。至此，已令人心醉了，于睾情不自禁娥发出了“爱杀江南”的赞叹。在强烈的赞叹声中，结束了全曲，使这赞叹声久久萦绕在读者的耳际心上。\n\n　　这是一首写景曲，作者紧紧抓住江南水乡的特色来写，先烈总体从大处入手，再抓具有代表性的事物一一描写，注意巨细交叉，远近结合，灵活多变。全曲纯作客观描写，情寓景中，形象生动，感情真挚，处处蕴含着一腔热爱江南之情。\n\n　　这支令曲写得俊美异常。它描写了江南水乡的秀丽风光，反映了诗人热爱江南、流连忘返的心情。古代吟咏江南的诗词是不少的，有的借吟咏江南春光写江南之美，如白居易的《忆江南》，也有的从芳春与清秋两个季节中选取一些最突出的景物和情事反映江南之美，如李煜的《望江南·闲梦远》。而作者和他们不同，他抓住江南清秋时节几个富有特征意义的景物与情事，寥寥几笔，勾勒出一幅江南秋色图，这就使这支散曲有了个性。另外，在描写江南美好风光时，作者不仅描写了珠帘漫卷、香风四溢、画檐鳞次栉比的大江两岸的人家，还描写了江水拍天、烟岚缥缈、芰荷满塘的淡雅秋光，使自然景色与社会景色融为一体，浑然天成，富有诗情画意。', poem_tags = '江南,写景,抒情' WHERE poem_title = '水仙子·咏江南' AND poem_author = '张养浩';
UPDATE edu_poem SET poem_tags = '抒怀,愤懑,壮志未酬' WHERE poem_title = '游子吟' AND poem_author = '陈陶';
UPDATE edu_poem SET poem_translation = '江南水乡的雨后，空气更加清新怡人，阵阵莲花清香扑面而来。\n这样的天气让人倍感舒适，客居他乡的愁绪却又从心头泛起。\n社会动荡不安，兵戈四起，不知何日才能平息；而那在乱世中的旧友不知有几人能保全。\n这样的愁闷心情难以排解，只因未曾学习佛理宽慰己心。', poem_notes = '馀：同“余”。\n得所：适当；适宜。悄然：形容忧愁的样子。\n故：过去的、旧的。\n消遣：排解愁闷。', poem_tags = '中秋,写景,抒情' WHERE poem_title = '中秋' AND poem_author = '郑谷';
UPDATE edu_poem SET poem_translation = '赵太后刚刚掌权，秦国就加紧进攻赵国。赵国向齐国求救。齐国说：“一定要用长安君作为人质，才出兵。”赵太后不同意。大臣们极力劝谏。太后明白地对左右侍臣说说：“有再说让长安君为人质的，我老太婆一定朝他脸上吐口水！”\n\n　　左帅触龙（对侍臣）说，希望拜见太后。太后气冲冲地等着他。（触龙）走入殿内就用快走的姿势慢慢地走着小步，到（太后面前）谢罪，说：“老臣的脚有毛病，竟不能快跑，不能拜见您有很长时间了。我私下原谅了自己，但是又怕太后的福体有什么毛病，所以还是想来拜见太后。”说：“我（也是脚行毛病）要靠手推车行动。”（触龙）说：“您每天的饮食该不会减少吧？”（太后）说：“就靠喝点粥罢了。“（触龙）说：“老臣近来特别不想吃饭，于是强迫自己散步，每天走三四里，稍微增加了喜欢吃的食物，对身体也舒适些了。”太后说：“我不能（像您那样散步）。“太后的脸色稍微和缓了些。\n\n　　左帅公说：“老臣的犬子舒祺，年龄最小，不成器，可是臣已衰老，私心又疼爱他，希望（您）让他补充黑衣卫士的人数，来保卫王宫。我冒着死罪来求您！”太后说：“答应您！年龄多大了？”（触龙）回答：“十五岁了。虽然还小，但想趁我未死之前来托付给您。”太后说：“男人也疼爱他小儿子吗？”（触龙）回答：“比女人爱得厉害些。”太后笑着说：“女人爱得特别厉害。”（触龙）回答：“老臣认为老太太爱燕后超过爱长安君。”（太后）说：“您错了，不像爱长安君那样厉害。”左师公说：“父母爱子女，就要为他们考虑得长远些。老太太送燕后（出嫁）时，（她上了车）还握着她的脚后跟为她哭泣，惦念、伤心她的远嫁，这也够伤心的了。送走以后，不是不想念她了；但每逢祭祀您一定为她祈祷，祈祷说：‘一定别让她回来啊’这难道不是从长远考虑，（希望她）有子孙相继为王吗？”太后说：“是这样。”\n\n　　左帅公说：“从现在算起往上推三代，一直到赵氏建立赵国的时候，赵王的子孙凡被封侯的，他们的继承人还有在侯位的吗？”（太后）说：“没有。”（触龙又）问：“不仅是赵国（没有），其他诸侯国子孙被封候的，其继承人有在侯位的吗？”（太后）说：“我没有听说过。”（触龙）说：“这是这些被封侯的近的灾祸及于自身，远的灾祸及其子孙。难道是国君的子孙就一定不好吗？（根本的原因是他们）地位高贵却没有功，俸禄优厚却没有劳，而且拥有的贵重宝器多了。现在老太太让长安君的地位高贵，并且把肥沃的土地封给他，还给他很多贵重的宝器，却不趁现在（您健在时）让他有功于国，一旦您驾崩了，长安君凭什么在赵国立身呢？老臣认为老太太为长安君考虑得太短浅，所以认为您（对长安君）的爱不如燕后。”太后说：“（您说得）对。任凭您怎样支使他吧！”\n\n　　于址为长安君备车一百乘，到齐国去作人质。齐国才出兵。\n\n　　子义听到这事说：“国君的孩子，可算是国君的亲骨肉了，尚且还不能凭靠无功的尊位、没有劳绩的俸禄来守住金玉宝器，更何况是人臣呢！”', poem_notes = '太后：帝王的母亲，这里指赵孝成王的母亲赵威后。\n新用事：刚刚掌权。用事：指当权，掌管国事。\n急：加紧。\n求救于齐：向齐国求救。于：向，介词。\n必：一定。以……为：把……作为。\n长安君：赵威后的小儿子，封于赵国的长安，封号为长安君。\n质：人质。古代两国交往，各派世子或宗室子弟留居对方作为保证，叫“质”或“质子”。\n强（qiǎng）：竭力，极力。\n谏：古代臣对君、下对上的直言规劝。\n明：明白地。\n左右：指赵威后身边的侍臣。\n复言：再说。\n令：让，使。\n唾：吐唾沫，动词。唾其面：朝他脸上吐唾沫。\n左师：春秋战国时，宋、赵等国官制有左师、右师，为掌实权的执政官。\n言：说，是“言于左右”的省略，“左右”承前省。“言于左右”是“对太后的侍臣说”。\n见：谒见，拜见。\n盛气：怒气冲冲。\n揖：应为“胥”。年长沙马王堆汉墓出土帛书《触龙见赵太后章》和《史记·赵世家》均作“胥”。胥：通“须”，等待。\n入：进入殿内。\n徐趋：用快走的姿势，慢步向前走。徐：慢慢地。趋：小步快走。古礼规定，臣见君一定要快步往前走，否则便是失礼。触龙因年老病足，不能快走，又要做出“趋”的姿势，只好“徐趋”。\n自谢：主动请罪。谢：道歉。\n病足：脚有毛病。病：有病，动词。\n曾：竟，副词。\n疾：快。\n不得：不能。\n见：指拜见太后。\n窃：私下，私意，表谦敬的副词。\n自恕：原谅自己。恕：宽恕，原谅。\n玉体：贵体，敬词。古人重玉，所以用玉来比喻太后的身体。后来，玉体一词，常被用来形容美女的体态。\n郄（xì）：同“隙”，空隙，引申为毛病。所郄：是具有名词性的“所”字结构，作“有”的宾语。有所郄：有什么毛病。\n望见：这是一种表敬的说法，意思是不敢走得太近，只能在远处望望。\n恃（shì）：依靠，凭借。\n辇（niǎn）：古代用两人拉的车子，秦汉以后特指皇帝坐的车子。\n日：每日，时间名词作状语。\n得无：副词性固定结构，与语气词“乎”相呼应，表示带有揣测性语气的问话，可译为为“该不会……吧”。\n衰：减少。\n今者：近来。者：助词，附于时间词后，使时间词由单音词变成复音词，并起提顿作用。\n殊：很，特别，副词。\n强（qiǎng）步：勉强散散步。步：散步，步行，动词。\n日：每天（步行）。\n少：稍微，略微，副词。\n益：增加，动词。\n耆（shì）：同“嗜”，喜爱。耆食：喜爱吃的食物。\n和：和谐，这里是舒适的意思。\n色：脸色，指赵太后的怒色。\n少解：稍微不和缓了些。\n公：对人的尊称。\n贱息：卑贱的儿子。这是对别人谦称自己的儿子，与现在说的“犬子”“贱子”意同。息：儿子。\n舒祺：触龙幼子的名字。\n少（shào）：年幼。\n不肖（xiào）：原意是不像先辈（那样贤明），后来泛指儿子不成材、不成器。肖：像，似。\n怜：怜爱。文言里的“爱”和“怜”在亲爱的意义上是同义词。\n令：让（他）。“令”后省略兼语“之”，指舒祺。\n得：能够。\n黑衣：指卫士，王宫卫士穿黑衣，所以用“黑农”借代卫士。以：来，连词。\n没（mò）：冒昧。没死：冒着死罪。\n以：连词，来。\n闻：使上级知道，使动用法。这里可译为“请求”。\n敬：表示客气的副词。\n诺：表示答应的意思。敬诺：意为“答应”，是应答之词。几何：多少。\n愿：希望。\n及：趁。\n填沟壑（he）：指死后无人埋葬，尸体丢在山沟里。这是对自己死亡的谦虚说法。壑：山沟。托之：把他托付给（您）。\n丈夫：古代对成年男子的通称。\n甚：厉害，形容词。\n于：比，介词。\n异甚：特别厉害。\n以为：认为。\n媪（ǎo）：刘老年妇女的尊称，同今之“老太太”。\n燕后：赵太后的女儿，嫁给燕王为后。\n贤于：胜过。\n君：您，对人的尊称。\n过：错。\n之甚：那样厉害。\n子：这里泛指子女。\n为：替，介词。\n计：打算，考虑。\n深远：长远，作动词“计”的补语。\n持：握持。\n踵（zhǒng）：脚后跟。燕后上了车，赵太后在车下还要握着她的脚后跟，舍不得她离去。\n为之：为她。泣：小声哭。\n念悲：惦念并伤心。\n远：远去，形容词用如动词。\n非弗：不是不，都是副词。\n必：一定，副词。\n祝之：为她祈祷。祝：向神祈祷。\n使：让（她）。\n反：同“返”。古代诸侯的女儿嫁到别国，只有在被废或亡国的情况下，才能返回本国。所以赵太后为燕后祈祷：一定别让她回来。\n计久长：打算得长远。\n有子孙：（希望燕后）有子孙。\n世：代，古代父子相继为一代。今三世：从现在算起上推三代。现在第一代是赵孝成王，上推第二代是他的父亲赵惠文王，上推第三代是他的祖父赵武灵王。“三世以前”当指他的曾祖父赵肃侯（前—前）。\n赵之为赵：赵氏家族建立赵国（的时候）。前“赵”指赵氏家族。后“赵”指赵国。之：助词，变主谓句为词组，作状语。为：成为，建立，动词。赵国国君原是晋文公大臣赵衰的后代。周威烈王二十三年（前）韩、赵、魏三家分晋，赵烈侯山晋国一个大夫变为诸侯，正式建立赵国。\n侯者：被封为侯的人。侯：封侯，活用为动词。\n继：活用为名词，继承人。\n在者：在侯位的人。\n微独：不仅，不但。微：不，否定副词。独：仅，副词。\n此：这，指代上面说的三世以前封侯的、他们的子孙没有继承侯位的这件事。\n身：指“侯者”自身。远者及其子孙，“及”前竹略“祸”字。\n人主：国君，诸侯。\n则：就，连词。善：好。\n位：地位。\n尊：尊贵，高贵。\n而：可是，转折连词。\n奉：同“俸”，俸禄，相当现的工资待遇。\n劳：功劳。\n尊：使……尊贵，形容词使动用法。\n封：古代帝王或诸侯把土地分给子孙或臣下作为他的食邑或领地。\n膏腴（yú）：比喻土地肥沃。膏：汕脂。腴：腹下的肥肉。“以膏腴之地”是介词结构，在这里是补语。译成现代汉语时，要移到“封之”之前作状语，按“以膏腴之地封之”翻译。\n及今：趁现在（您在世）。\n令：是“令（之）“的省略，让（他）。\n山陵崩：古代用以比喻国君或王后的死，表明他们的死不同寻常，犹如山陵崩塌，这是一种委婉的说法。这里指赵太后去世。\n何以：疑问代词。以：介词。何以：凭什么，介词宾语前置。\n自托：寄托自己。\n以：认为，动词。\n为：替，介词。\n计短：考虑得太短浅。\n不若：不如。\n诺：应答之词，表示同意，可译“对”。\n恣：任凭。\n使之：支使他，派遣他。前“之”，助词，不译；后“之”，代词，代长安君。\n约车：套车。约：捆缚，套。\n乘（shèng）：量词，古代一车上马叫“乘”。质于齐。质：作人质，名词活用为动词。\n子义：赵国贤人。\n犹：还。尊：用作名词。指尊高的地位。', poem_tags = '古文观止,高中文言文,劝谏,历史,故事' WHERE poem_title = '触龙说赵太后' AND poem_author = '刘向';
UPDATE edu_poem SET poem_translation = '烧瓦工人成天挖呀挖，门前的土都挖光了，可自家的屋上却没有一片瓦。\n那些富贵人家，十指连泥也不碰一下，却住在铺满瓦片的高楼大厦。', poem_notes = '陶者：烧制陶器的人。这里指烧瓦工人。\n陶：同“掏”，指挖土烧瓦。\n无片瓦：没有一片瓦。\n沾：同“沾”。\n鳞鳞：形容屋瓦如鱼鳞般整齐排列。大厦：高大的屋子。', poem_tags = '古诗三百首,农民,生活' WHERE poem_title = '陶者' AND poem_author = '梅尧臣';
UPDATE edu_poem SET poem_translation = '情人双双共进果橙。破橙的刀具光洁，像清水那样澄澈；盛橙子的盘子明净，果蔬新鲜。美人端庄高雅，用她的纤纤细手亲自为心上人般破新橙。女子对男子的一片温情，男子怎能不知呢？室内，华美的帐幔轻轻低垂，袅袅的炉香是室内弥漫着暖融融的气息，彼此之间的柔情蜜意也似乎融化在这温馨的气息中了。他们相对而坐，男子陶醉在女子的笙曲中。夜深了，男子起身向与女子告别，女子低声问他：你现在哪里入宿呢？现在已经是三更时分了，外面寒风凛冽、路滑霜寒，很少有人行走，不如就别走了吧。', poem_notes = '并刀：并州出产的剪刀。如水：形容剪刀的锋利。\n吴盐：吴地所出产的洁白细盐。\n幄：帐。\n兽烟：兽形香炉中升起的细烟。\n谁行（háng）：谁那里。\n直是：就是这首词乃感旧之作。', poem_appreciation = '这首词，通过对女子特有口吻惟妙惟肖的刻画，曲折深微的写出对象的细微心理状态，追述作者自己在秦楼楚馆中的经历，大有呼之欲出之概。\n\n　　上片以男方的视角写美人的热情待客，抒发对女子情投意合的情感。\n\n　　“并刀如水，吴盐胜雪，纤手破新橙”──这是富于暗示力的特写镜头。出现在观众眼前的，仅仅是两件简单的道具（并刀，并州出产的刀子；吴盐，吴地出产的盐。）和女子一双纤手的微细动作，可那女子刻意讨好对方的隐微心理，已经为观众所觉察了。\n\n　　“锦幄初温，兽烟不断，相对坐调笙”──室内是暖烘烘的帏幕，刻着兽头的香炉（叶嘉莹：兽形的香）轻轻升起沉水的香烟。只有两个人相对坐着，女的正调弄着手里的笙，试试它的音响；男的显然也是精通音乐的，他从女的手中接过笙来，也试吹了几声，评论它的音色的音量，再请女的吹奏一支曲子。\n\n　　这里也仅仅用了三句话，而室内的气氛，两个人的情态，彼此的关系，男和女的身分，已经让人们看得清清楚楚了。\n\n　　下片以叙事的方式来抒情，改用女方的口吻来传情，有层次，有曲折，人物心情的宛曲，心理活动的幽微，人物形象的刻画和生活细节的描写更是十分细腻逼真。\n\n　　“低声问”一句直贯篇末。谁问？未明点。为何问？也未说明。\n\n　　“向谁行宿？”的文化自知是男子的告辞引起。写来空灵含蓄，挽留的意思全用“问”话出之，更有味。只说深夜“城上已三更”，路难“马滑霜浓”，“直是少人行。”只说“不如休去”，表情措语，分寸掌握极好。\n\n　　词结束在“问”上，结束在期待的神情上，意味尤长。无限情景，都自先手破橙人口中说出，更不别作一语。意思幽微，篇章奇妙。\n\n　　词中所写的男女之情，意态缠绵，恰到好处，可谓“傅粉则太白，施朱则太赤”，不沾半点恶俗气昧；又能语工意新。这种写生的技巧，用在散文方面已经不易着笔，用在诗词方面就更不容易了。单从技巧看，周邦彦实在是此中高手。', poem_tags = '宋词三百首,婉约,写人' WHERE poem_title = '少年游·并刀如水' AND poem_author = '周邦彦';
UPDATE edu_poem SET poem_translation = '院无风，柳丝垂，闺人昼寝。闺人安静昼寝之际，起风，庭院柳条摇摆。微风吹，汗味透香气，薄衫生凉意。凉衫子散出清淡的汗香气。\n红润的手端起了盛有冰块拌藕丝的小碗。盛有冰块拌藕丝的小碗冰冷了她红润的手。郎笑碗中的藕丝太长了。闺人一边吃长丝藕，一边又嘲笑她的情郎。', poem_notes = '柳庭风静人眠昼：院无风，柳丝垂，闺人昼寝。\n昼眠人静风庭柳：闺人安静昼寝之际，起风，庭院柳条摇摆。\n香汗薄衫凉：微风吹，汗味透香气，薄衫生凉意。\n凉衫薄汗香：凉衫子散出清淡的汗香气。\n手红冰碗藕：红润的手端起了盛有冰块拌藕丝的小碗。\n藕碗冰红手：盛有冰块拌藕丝的小碗冰冷了她红润的手。冰：古人常有在冬天凿冰藏于地窖的习惯，待盛夏之时取之消暑。\n郎笑藕丝长：郎笑碗中的藕丝太长了。“藕丝长”：象征着人的情意长久。在古典诗词中，常用“藕”谐“偶”，以“丝”谐“思”。\n长丝藕笑郎：闺人一边吃长丝藕，一边又嘲笑她的情郎（担心他薄情寡意不如藕丝长）。', poem_tags = '夏天,闺怨' WHERE poem_title = '菩萨蛮·回文夏闺怨' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '回想为官时的日子，没有比做刺史时更快意舒畅了。\n欢乐的接待来访的宾客，妻儿的生活能够得到保障。\n自从来到东都以后，生活清闲更胜从前。\n做分司时清闲的生活胜过刺史，辞去官职后生活清闲胜过分司。\n更不说是在这偏远的家乡，能收到你的书信非常欣喜。\n仰慕你的大名就像与你相识已久，一起做乐曲就像是新得的知己。\n下雪时就先到朗之家里拜访，不是花开时节不相约。\n边畅饮着自己酿造的美酒，边细细品味所作的诗句。\n作为邻里已来往无数遍，在那京都城门也已分别五次。\n翘首以盼你的来信，书信到时放能舒展眉头。\n槐亭院中已满是落叶，竹阁池中的水也结满冰霜。\n门庭冷落无处询问讯息，只得放弃追问。\n身体病痛增多，容貌与体力也在逐渐衰退。\n虽已年老记忆减退，但你我间那些相处场景仍历历在目从未忘却。', poem_notes = '历：经过了的。\n无如：不如，比不上。\n及：达到。\n东都：历代王朝在原京师以东的都城。\n安闲：安静清闲；安逸舒适。\n分司：唐宋制度，中央之官有分在陪都(洛阳)执行任务者，称为“分司”。但除御史之分司有实权外，其他分司多用以优待退闲之官，并无实权。又清制，“盐运使”下设“分司”，属运同、运副或运判管领。\n致仕：辞去官职。\n何况：用反问的语气表达更进一层的意思。\n欣然：喜悦貌。\n仰：尊敬仰慕。\n斗：中国市制容量单位（十升为一斗，十斗为一石）。\n醲：味浓烈的酒。\n里巷：街巷。\n都门：京都城门。\n岐：岐山，在中国陕西省。\n雀罗：捕雀的网罗。常用以形容门庭冷落。\n鹤氅：泛指一般外套。', poem_tags = '抒怀,感慨,思念,友人' WHERE poem_title = '偶作寄朗之' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '明月如霜般洁白，好风就如同清水一样清凉，秋天的夜景清幽无限。弯弯的水渠中，鱼儿跳出水面，圆圆的荷叶上，露珠随风落下，但夜深人静，这样好的美景却无人看见。三更鼓声，声声响彻夜空，一片树叶悄悄落到地上，轻音竟把我的梦惊断。夜色茫茫，再也见不到黄昏时的景色，醒来后我把小园处处寻遍。\n　　那长期在外地的游子早已疲倦，看那山中的归路，对着故乡家园苦苦地思念。看如今燕子楼空空荡荡，佳人盼盼已经不在，楼中的画堂里空留着那呢喃双燕。古今万事皆成空，还有几人能从梦中醒来，有的只是难了的旧欢新怨。后世有人，面对着这黄楼夜色，定会为我深深长叹。', poem_notes = '彭城：今江苏徐州。燕子楼：唐徐州尚书张建封（一说张建封之子张愔）为其爱妓盼盼在宅邸所筑小楼。\n紞如：击鼓声。\n铿然：清越的音响。\n梦云：夜梦神女朝云。云，喻盼盼。典出宋玉《高唐赋》楚王梦见神女：“朝为行云，暮为行雨”。惊断：惊醒。\n心眼：心愿。\n黄楼：徐州东门上的大楼，苏轼徐州知州时建造。', poem_appreciation = '上阕写清幽梦境及梦醒后的怅然若失之感。起三句总写秋夜清景，各以霜、水分喻月、风，并小结以“清景无限”，赏爱之心已溢于言外。首句写月色明亮，皎洁如霜；秋风和畅，清凉如水，把人引入了一个无限清幽的境地。“清景无限”既是对暮秋夜景的描绘，也是词人的心灵得到清景抚慰后的情感抒发。“\n\n　　下阕乃醒后述怀，语意沉郁而超然独悟。换头三句是实写心境，写在天涯漂泊感到厌倦的游子，想念山中的归路，心中眼中想望故园一直到望断，极言思乡之切。此句带有深沉的身世之感，道出了词人无限的怅惘和感喟。杜甫曾有诗云：“天畔登楼眼，随春入故园。”苏轼此处当是化用杜诗，写登楼后的思家心理。\n\n　　词人将景、情、理熔于一炉，围绕燕子楼情事而层层生发。景为燕子楼之景，情则是燕子楼惊梦后的缠绵情思，理则是由燕子楼关盼盼情事所生发的“人生如梦如幻”的关于人生哲理的永恒追问。全词融情入景，情理交融，境界清幽，风格在和婉中不失清旷，用典体认著题，融化不涩，幽逸之怀与清幽之境相得益彰，充分显示出苏轼造意行文的卓越不凡。\n\n　　这首词深沉的人生感慨包含了古与今、倦客与佳人、梦幻与佳人的绵绵情事，传达了一种携带某种禅意玄思的人生空幻、淡漠感，隐藏着某种要求彻底解脱的出世意念。词中“燕子楼空”三句，千古传诵，深得后人赞赏。', poem_tags = '宋词三百首,豪放,写景,抒情,怅惘,人生' WHERE poem_title = '永遇乐·彭城夜宿燕子楼' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_tags = '夏天,黄昏,写人' WHERE poem_title = '浣溪沙·玉碗冰寒滴露华' AND poem_author = '晏殊';
UPDATE edu_poem SET poem_translation = '微弱蜉蝣在空中振翅飞舞，漂亮的外衣色彩鲜明夺目。叹其生苦短我心溢满忧伤，我将如何安排人生的归宿？\n细小蜉蝣在空中振翅飞舞，尽情展示着它华美的衣服。叹其生短促我心涌满忧郁，我人生的归宿将栖落何处？\n柔嫩的蜉蝣刚刚破土而出，轻轻舞动雪白的麻纹衣服。叹其生命短暂我忧郁满怀，到哪里寻找我人生的归宿？', poem_notes = '蜉（fú）蝣（yóu）：一种昆虫，寿命只有几个小时到一周左右。\n蜉蝣之羽：以蜉蝣之羽形容衣服薄而有光泽。\n楚楚：鲜明貌。一说整齐干净。\n於（wū）：通“乌”，何，哪里。\n采采：光洁鲜艳状。\n掘阅（xué）：挖穴而出。阅：通“穴”。\n麻衣：古代诸侯、大夫等统治阶级日常衣服，用白麻皮缝制。\n说（shuì）：通“税”，止息，住，居住。', poem_appreciation = '蜉蝣是一种渺小的昆虫，生长于水泽地带。幼虫期稍长，个别种类有活到二三年的。但化为成虫，即不饮不食，在空中飞舞交配，完成其物种的延续后便结束生命，一般都是朝生暮死。蜉蝣又是漂亮的小虫。它身体软弱，有一对相对其身体而言显得很大、完全是透明的翅膀，还有两条长长的尾须，飘舞在空中时，那姿态是纤巧而动人的。而且，蜉蝣喜欢在日落时分成群飞舞，繁殖盛时，死后坠落地面，能积成一厚层。因而，这小东西的死，会引人瞩目，乃至给人以惊心动魄之感。二千多年前，敏感的诗人借这朝生暮死的小虫写出了脆弱的人生在消亡前的短暂美丽和对于终须面临的消亡的困惑。\n\n　　说起来，是“人生百年”——或者往少说，通常也有几十年。但相比于人对生命的贪恋程度，这远远是不够的。而且，人作为自觉的生物，在其生存过程中就意识到死的阴影，于是人生短暂之感愈益强烈。当然，活着是美好的，而且人与其他一切生物不同，他们懂得以人的方式来装饰自己，懂得追求美的姿态。然而放在死亡的阴影下来看，短暂生命的装饰与姿态，实也是最大的无奈与最大的哀伤。于是，蜉蝣的朝生暮死的生命过程，它的弱小、美丽，以及它对自己鲜明的羽翼、鲜洁的容貌的炫耀，被诗人提取出来描画成人的上述生存状态的象征。\n\n　　此诗开篇即以“蜉蝣之羽”为比，这个小生命的翅膀，像一件华美的衣裳那样艳丽多彩。但这种美丽来之不易，且只有一天的美丽，宛如昙花一现。诗人见此情景生发感慨。一种珍惜生命、把握现在的紧迫感油然而生。第二章意思大致相同。第三章，描述蜉蝣的初生，刚刚破土而出的时候，麻衣如雪，那薄如麻丝的翅羽好像初雪一样洁白柔嫩。但它很快就飞翔起来，尽情挥舞生命的光采。相比之下，人当然要学习蜉蝣精神，生之光华，死之绚烂。\n\n　　这诗的内容简单，结构更是单纯，却有很强的表现力。变化不多的诗句经过三个层次的反复以后给人的感染是浓重的：蜉蝣翅膀的小小美丽经这样处理，便有了一种不真实的艳光，那小虫的一生竟带上了铺张的华丽；但因这种描写之间相隔着对人生忧伤的深深感喟，所以对美的赞叹描画始终伴随着对消亡的无奈，那种昙花一现、浮生如梦的感觉就分外强烈。\n\n　　这诗的情调自然是有点消沉的。但人一旦追问自己：“你是谁？你往哪里去？”深入骨髓的忧伤根本上是无法避免的。特别是在缺乏强有力的宗教的古代中国，由于不能对生死的问题给出令人心安的解答，人心格外容易被忧伤笼罩。但从另一个角度说，对死的忧伤、困惑、追问，归根结蒂是表现着对生的眷恋，这也是人心中最自然的要求。阮籍《咏怀诗》之七十一，写木槿花、蟋蟀、蟪蛄、蜉蝣这一系列短寿的生物在世间各自发出声音和光色，感叹说：“生命几何时，慷慨各努力。”但这也就是世界的基本面目。', poem_tags = '诗经,咏物' WHERE poem_title = '蜉蝣' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '用眼看尽淮海，漫漫海上像银子一样白，千万道彩虹般的光芒下，蚌孕育着珍珠。\n天上的月如果没有人修治，桂树枝就会一直长，会撑破月亮的。', poem_notes = '万道虹光：引用民间传说。传说月圆之时，蚌才育珠。\n修月户：传说月亮是由七宝合成的，人间常有八万二千户给它修治。', poem_tags = '中秋节,写景' WHERE poem_title = '中秋登楼望月' AND poem_author = '米芾';
UPDATE edu_poem SET poem_translation = '杜陵地方，有我这么个布衣，年纪越大，反而越发不合时宜。对自己的要求，多么愚蠢可笑，私自下了决心，要向稷契看齐。这种想法竟然不合实际，落得个到处碰壁，头都白了，却甘愿辛辛苦苦，不肯休息。有一天盖上棺材，这事便无法再提，只要还没有咽气，志向就不能转移。一年到头，都为老百姓发愁、叹息，想到他们的苦难，心里像火烧似的焦急。尽管惹得同辈的先生们冷嘲热讽，却更加激昂无比，引吭高歌，毫不泄气。\n\n　　我何尝没有隐居的打算，在江海之间打发日子，岂不清高？只是碰上个像尧舜那样贤明的皇帝，不忍心轻易地丢下他，自己去逍遥。如今的朝廷上，有的是栋梁之材，要建造大厦，难道还缺少我这块料？可是连葵藿的叶子都朝着太阳，我这忠诚的天性，又怎能轻易改掉！\n\n　　回头一想，那些蚂蚁般的小人，只为谋求舒适的小窝，整天钻营。我为什么要羡慕百丈长鲸，常想在大海里纵横驰骋？偏偏不肯去巴结权贵，因此便耽误了自己的营生。到现在还穷困潦倒，怎忍心埋没在灰尘之中？没有像许由、巢父那样飘然世外，实在惭愧，虽然惭愧，却不愿改变我的操行。还有什么办法呢？只好喝几杯酒排遣烦闷，作几首诗放声高唱，破除忧愤。\n\n　　一年快完了，各种草木都已经凋零，狂风怒吼，像要把高山扫平。黑云像山一样压下来，大街上一片阴森，我这个孤零零的客子，半夜里离开京城。扑落满身寒霜，断了衣带，想结上它，指头儿却冻成僵硬。\n\n　　天蒙蒙亮的时候，我走到骊山脚下，骊山高处，那里有皇帝的御榻。大雾迷漫，塞满寒冷的天空，我攀登结冰铺霜的山路，二步一滑。华清宫真好像王母的瑶池仙境，温泉里暖气蒸腾，羽林军密密麻麻。乐声大作，响彻辽阔的天宇，皇帝和大臣纵情娱乐，享不尽贵富荣华。\n\n　　赐浴温泉的，都是些高冠长缨的贵人，参加宴会的，更不会有布衣麻鞋的百姓。达官显宦，都分到大量的绸帛，那些绸帛啊，都出自贫寒妇女的艰苦劳动。她们的丈夫和公公，被鞭打绳捆，一匹匹勒索，一车车运进京城。皇帝把绸帛分赏群臣，这个一筐，那个几笼，实指望他们感恩图报，救国活民；臣子们如果忽略了皇帝的这番好意，那当皇帝的，岂不等于把财物白扔！朝廷里挤满了“济济英才”，稍有良心的，真应该怵目惊心！\n\n　　更何况皇宫内的金盘宝器，听说都转移到国舅家的厅堂。神仙似的美人在堂上舞蹈，轻烟般的罗衣遮不住玉体的芳香。供客人保暖的，是貂鼠皮袄，朱弦、玉管，正演奏美妙的乐章，劝客人品尝的，是驼蹄羹汤，香橙、金橘，都来自遥远的南方。\n\n　　那朱门里啊，富人家的酒肉飘散出诱人的香气，这大路上啊，冻饿死的穷人有谁去埋葬！相隔才几步，就是苦乐不同的两种世界，人间的不平事，使我悲愤填胸，不能再讲！\n\n　　我折向北去的道路，赶到泾、渭河边。泾、渭合流处的渡口，又改了路线。河水冲激着巨大的冰块，波翻浪涌，放眼远望，象起伏的山岭，高接西天。我疑心这是崆峒山从水上飘来，怕要把天柱碰断！\n\n　　河上的桥梁幸好还没有冲毁，桥柱子却吱吱呀呀，摇晃震颇。河面这么宽，谁能飞越！旅客们只好牵挽过桥，顾不得危险。\n\n　　老婆和孩子寄居在奉先，无依无傍，漫天风雪，把一家人隔在两个地方。受冻挨饿的穷生活，我怎能长久不管？这一次去探望，就为了有难同当。\n\n　　一进门就听见哭声酸楚，我那小儿子，已活活饿死！我怎能压抑住满腔悲痛，邻居们也呜呜咽咽，泪流不止！说不出内心里多么惭愧，做父亲的人，竟然没本事养活孩子！谁能料到：今年的秋收还算不错，穷苦人家，却仍然弄不到饭吃！\n\n　　我好歹是个官儿，享有特权：既不服兵役，又没有交租纳税的负担。还免不了这样悲惨的遭遇，那平民百姓的日子啊，就更加辛酸。想想失去土地的农民，已经是倾家荡产，又想想远守边防的士兵，还不是缺吃少穿。忧民忧国的情绪啊，千重万叠，高过终南，浩茫无际，又怎能收敛！', poem_notes = '(1)杜陵：地名，在长安城东南，杜甫祖籍杜陵。因此杜甫常自称少陵野老或杜陵布衣。布衣：平民。此时杜甫虽任右卫率府胄曹参军这一八品小官，但仍自称布农。老大：杜甫此时已44岁。拙：笨拙。这句说年龄越大，越不能屈志随俗；同时亦有自嘲老大无成之意。\n(2)许身：自期、自许。一何愚：多么愚腐。稷与契：传说中舜帝的两个大臣，稷是周代祖先，教百姓种植五谷；契是殷代祖先，掌管文化教育。\n(3)濩落：即廓落，大而无用的意思。契阔：辛勤劳苦。\n(4)盖棺：指死亡。觊豁：希望达到。这两句说，死了就算了，只要活着就希望实现理想。\n(5)穷年：终年。黎元：老百姓。肠内热：内心焦急，忧心如焚。\n(6)弥：更加，越发。\n(7)江海志：隐居之志。潇洒送日月：自由自在地生活。\n(8)尧舜君：此以尧舜比唐玄宗。\n(9)廊庙具：治国之人才。\n(10)葵藿：葵是向日葵；藿是豆叶。\n(11)顾：想一想。蝼蚁辈：比喻那些钻营利禄的人。\n(12)胡为：为何？大鲸：比喻有远大理想者。辄：就，常常。拟：想要。偃溟渤：到大海中去。\n(13)以兹误生理：因为这份理想而误了生计。干谒：求见权贵。\n(14)兀兀：穷困劳碌的样子。\n(15)巢与由：巢父、许由都是尧时的隐士。\n(16)沉饮聊自遣：姑且痛饮，自我排遣。\n(17)天衢：天空。峥嵘：原是形容山势，这里用来形容阴云密布。客子：此为杜甫自称。发：出发。\n(18)骊山：在今陕西临潼县南。嵽嵲：形容山高，此指骊山。\n(19)蚩尤：传说中黄帝时的诸侯。黄帝与蚩尤作战，蚩尤作大雾以迷惑对方。这里以蚩尤代指大雾。\n(20)瑶池：传说中西王母与周穆王宴会的地方。此指骊山温泉。气郁律：温泉热气蒸腾。羽林：皇帝的禁卫军，摩戛：武器相撞击。\n(21)殷：充满。胶葛：山石高峻貌。这句指乐声震动山冈。\n(22)长缨：指权贵。缨，帽带。短褐：粗布短袄，此指平民。\n(23)彤庭：朝廷。\n(24)圣人：指皇帝。筐篚：两种盛物的竹器。古代皇帝以筐、篚盛布帛赏赐群臣。\n(25)“臣如”两句意为：臣子如果忽视此理，那么皇帝的赏赐不是白费了吗？\n(26)“多士”两句意为：朝臣众多，其中的仁者应当惶恐不安地尽心为国。\n(27)内金盘：宫中皇帝御用的金盘。卫、霍：指汉代大将卫青、霍去病，都是汉武帝的亲戚。这里喻指杨贵妃的从兄、权臣杨国忠。\n(28)中堂：指杨氏家族的庭堂。舞神仙：像神仙一样的美女在翩翩起舞。烟雾：形容美女所穿的如烟如雾的薄薄的纱衣。玉质：指美人的肌肤。\n(29)“暖客”以下四句：极写贵族生活豪华奢侈。\n(30)荣、枯：繁荣、枯萎。此喻朱门的豪华生活和路边冻死的尸骨。惆怅：此言感慨、难过。\n(31)北辕：车向北行。杜甫自长安至蒲城，沿渭水东走，再折向北行。泾渭：二水名，在陕西临潼境内汇合。官渡：官设的渡口。\n(32)高崪兀：河中的浮冰突兀成群。\n(33)崆峒：山名，在今甘肃省岷县。天柱：古代神话说，天的四角都有柱子支撑，叫天柱。恐触天柱折：形容冰水汹涌，仿佛共工头触不周山，使人有天崩地塌之感。表示诗人对国家命运的担心。\n(34)河梁：桥。坼：断裂。枝撑：桥的支柱。窸窣：象声词，木桥振动的声音。\n(35)行旅相攀援：行路的人们相互攀扶。\n(36)异县：指奉先县。十口隔风雪：杜甫一家十口分居两地，为风雪所阻隔。\n(37)庶：希望。\n(38)贫窭：贫穷。仓卒：此指意外的不幸。\n(39)名不隶征伐：此句自言名属“士人”，可按国家规定免征赋税和兵役、劳役。杜甫时任右卫卒府兵曹参军，享有豁免租税和兵役之权。\n(40)平人固骚屑：平民百姓本来就免不了赋役的烦恼。平人：平民，唐人避唐太宗李世民讳，改“民”为“人”。\n(41)失业徒：失去产业的人们。\n(42)忧端齐终南：忧虑的情怀像终南山那样沉重。澒洞：广大的样子。掇：收拾，引申为止息。', poem_appreciation = '这首诗作于天宝十四载(755)。十月，杜甫得到右卫率府兵曹参军的任命。十一月，杜甫从京城长安去奉先县(治所在今陕西蒲城)探家，安禄山恰在此时造反。杜甫经骊山时，安史之乱的消息还无从知晓，唐玄宗和杨贵妃正在骊山华清宫避寒享乐。久已积压在心头的政治危机感和大乱将临的预感，为沿途所见荣枯之异和到家后得知幼子饿死等事所激发，于是创作了这首名诗。\n\n　　全诗凡五百字，而其中叙述自京师出发，过骊山，就泾渭，抵奉先，不过数十字，其馀都是议论或感慨，因为题目毕竟是“咏怀“。作为杜甫五言古诗中的代表作，全诗所咏之怀，主题有二:一是叙说他素怀济世之志，却不得伸展，虽艰难困苦，仍不改初衷。二是对正在骊山行宫中肆意挥霍享乐的玄宗君臣提出责难，对社会上严重的贫富分化，及动乱的苗头表示了沉重的忧虑。全诗以“穷年忧黎元“为主线，标志着诗人忧国忧民的现实主义创作思想已经形成，具有划时代的意义。它是杜甫困居长安十年生活与思想的总结，在艺术上也已达到纯熟境地。', poem_tags = '咏怀,忧国忧民' WHERE poem_title = '自京赴奉先县咏怀五百字 / 自京赴奉先咏怀五百字' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '道上露水湿漉漉，难道不想早逃去？只怕露浓难行路。\n\n谁说麻雀没有嘴？怎么啄穿我房屋？谁说你尚未娶妻？为何害我蹲监狱？即使让我蹲监狱，你也休想把我娶！\n\n谁说老鼠没牙齿？怎么打通我墙壁？谁说你尚未娶妻？为何害我吃官司？即使让我吃官司，我也坚决不嫁你！', poem_notes = '厌浥（yì yì益益）：潮湿。行（háng），道路。\n谓：可能是畏之假借，意指害怕行道多露，与下文的“谁谓”的“谓”意不同；一说奈何。\n角(jiǎo旧读jué)：鸟喙。\n女：同汝，你。无家：没有成家、没有妻室。\n速：招，致。狱：案件、官司。\n家：媒聘求为家室之礼也。一说婆家。室家不足：要求成婚的理由不充足。\n墉（yōng拥）：墙。\n讼：诉讼。', poem_appreciation = '这首诗的主旨，从古至今，聚讼纷纭。《毛诗序》联系《甘棠》而理解为召伯之时，强暴之男不能侵陵贞女，而《韩诗外传》、《列女传·贞顺篇》却认为是申女许嫁之后，夫礼不备，虽讼不行的诗作，清龚橙《诗本谊》、吴闿生《诗义会通》等承袭此说。明朱谋玮《诗故》又以为是寡妇执节不贰之词，清方玉润《诗经原始》则以为是贫士却婚以远嫌之作。今人高亨《诗经今注》认为是一个女子嫌弃夫家贫穷，不肯回家，被丈夫讼于官府而作；余冠英《诗经选》认为是一个已有夫家的女子的家长对企图以打官司逼娶其女的强横男子的答复；陈子展《诗经直解》认为是一个女子拒绝与一个已有妻室的男子重婚的诗歌。笔者认为余说近是，但诗中的主人公应是那位女子。\n\n　　首章首句“厌浥行露”起调气韵悲慨，使全诗笼覃在一种阴郁压抑的氛围中，暗示这位女性所处的环境极其险恶，抗争的过程也将相当曲折漫长，次二句“岂不夙夜？谓行多露”，文笔稍曲，诗意转深，婉转道出这位女子的坚定意志。次章用比兴方法说明，即使强暴者无中生有，造谣诽谤，用诉讼来胁迫自己，她也决不屈服。“谁谓雀无角？何以穿我屋？谁谓女无家？何以速我狱”四句是正话反说，表示：雀虽有嘴而无穿我屋之理，你已有妻则无致我陷狱之理。委婉巧妙；而“虽速我狱，室家不足”两句则是正面表态，斩钉截铁，气概凛然。第三章谓：鼠虽有牙而无穿我墙之理，你已有妻则无使我遭诉讼之理，但你若欲陷我于诉讼，我也不会屈从你。句式复沓以重言之，使得感染力和说服力进一步加强。全诗风骨遒劲，格调高昂，从中读者不难体会到女性为捍卫自己的独立人格和爱情尊严所表现出来的不畏强暴的抗争精神。', poem_tags = '诗经' WHERE poem_title = '行露' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '今天的山岚雾霭特别的重，天涯广阔这里却是如此的偏僻深远。闻见滩头江水带来的秋意扑面而来，山谷的气候湿润，晴天也多像阴天。\n望向帝京但是云遮住了眼，想着故乡，檐上的雨一滴滴的滴到心里。用什么来安慰我这幽深彷徨的思绪，唯赖这北窗下的琴来解我心中孤独。', poem_notes = '岚雾：山中雾气。', poem_tags = '思乡' WHERE poem_title = '阴雨' AND poem_author = '白居易';
UPDATE edu_poem SET poem_tags = '怀念,友情,古体' WHERE poem_title = '沙丘城下寄杜甫' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '明晨驿使就要出发，思妇们连夜为远征的丈夫赶制棉衣。\n纤纤素手连抽针都冷得不行，更不说用那冰冷的剪刀来裁衣服了。\n妾将裁制好的衣物寄向远方，几时才能到达边关临洮？', poem_notes = '临洮：在今甘肃临潭县西南，此泛指边地\n驿：驿馆', poem_appreciation = '《子夜吴歌》诗题又作《子夜四时歌》，共四首，写春夏秋冬四时。这里所选是第四首。六朝乐府《清商曲·吴声歌曲》即有《子夜四时歌》，因属吴声曲，故又称《子夜吴歌》。此体原为四句，内容多写女子思念情人的哀怨，作六句是诗人的独造，而用以写思念征夫的情绪更具有时代之新意。\n\n　　《子夜吴歌·冬歌》不写景而写人叙事，通过一位女子“一夜絮征袍”的情事以表现思念征夫的感情。时间是传送征衣的驿使即将出发的前夜，大大增强了此诗的情节性和戏剧性。一个“赶”字，不曾明写，但从“明朝驿使发”的消息，读者从诗中处处看到这个字，如睹那女子急切、紧张劳作的情景。关于如何“絮”、如何“裁”、如何“缝”等等具体过程，诗人有所取舍，只写抽针把剪的感觉，突出一个“冷”字。素手抽针已觉很冷，还要握那冰冷的剪刀。“冷”既切合“冬歌”，更重要的是有助于加强情节的生动性。天气的严寒，使手指也不灵巧了，而时不我待，偏偏驿使就要出发，人物焦急情态宛如画出。“明朝驿使发”，分明有些埋怨的意思了。然而，她从自己的冷想到“临洮”（在今甘肃临潭县西南，此泛指边地）那边的更冷。因此又巴不得驿使早发、快发。这种矛盾心理亦从无字处表出。读者似乎又看见她一边呵着手一边赶裁、赶絮、赶缝。“一夜絮征袍”，言简而意足，然而随即又情急起来，她想：路是这样远，“寒到身边衣到无”呢？这回却是恐怕驿使行迟，盼望驿车加紧了。“裁缝寄远道，几日到临洮？”这迫不及待的一问包含极度的深情与牵挂。《子夜吴歌》中的第三首《秋歌》是正面归结到怀思良人之意，而《冬歌》却纯从侧面落笔，通过形象刻画与心理描写结合，塑造出一个活生生的思妇形象，成功表达了诗歌主题。结构上一波未平，一波又起，起势突兀，结句意远，情节生动感人。\n\n　　如果说《秋歌》是以间接方式塑造了长安女子的群像，《冬歌》则通过个体形象以表现出一类人——思妇形象。其语言的明转天然，形象的鲜明集中，音调的清越明亮，情感的委婉深厚，得力于民歌，真是“意愈浅愈深，词愈近愈远，篇不可以句摘，句不可以字求”（《诗薮·内编》卷二）的佳作。', poem_tags = '唐诗三百首,乐府,冬天,妇女,思念' WHERE poem_title = '子夜吴歌·冬歌' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '韵译\n\n黄昏时山寺的钟声回荡山谷，渔梁渡口处一片喧闹的声音。\n人们沿着沙岸向江村走过去，我也乘坐一叶小舟返回鹿门。\n鹿门的月光使山树显现出来，我忽然来到了庞公隐居之地。\n清冷的山岩路寂静的林间道，唯有隐居的人在此飘逸来去。\n\n散译\n\n天色已近黄昏，山寺里的钟声响起，渔梁渡口人们争着过河，喧闹不已。行人沿着沙岸向江村走去，我也乘着小舟返回鹿门山。皎洁的月光照映着鹿门山，山树一片迷朦。忽然，仿佛不知不觉就到了庞公曾隐居的地方，也到了我现在的栖身之地。如门的山岩、松间的小路幽幽静静，只有隐者独自来去，与这美妙的大自然融为一体。', poem_notes = '鹿门：山名，在襄阳。\n昼已昏：天色已黄昏。\n渔梁：洲名，在湖北襄阳城外汉水中。《水经注·沔水》中记载：“襄阳城东沔水中有渔梁洲，庞德公所居。”喧：吵闹。\n余：我。\n开烟树：指月光下，原先烟雾缭绕下的树木渐渐显现出来。\n庞公：庞德公，东汉襄阳人，隐居鹿门山。荆州刺史刘表请他做官，不久后，携妻登鹿门山采药，一去不回。\n岩扉：指山岩相对如门。\n幽人：隐居者，诗人自称。', poem_appreciation = '开篇二句写诗人傍晚江行的见闻。首句写白昼已尽，黄昏降临，幽僻的古寺传来了报时的钟声，次句写沔水口附近的渔梁渡头人们急于归家时抢渡的喧闹，首句表现的是安宁静谧的环境，次句却表现喧嚣，形成了鲜明而强烈的比照，这是远离人寰的禅境与喧杂纷扰的尘世的比照。\n\n　　第二联，前句承“渔梁”诗意，是写村人各自上岸还家；后句承“山寺”诗意，写自己回到鹿门。这两句是以人归引出自归，作为前文的具体补述。两种归途展现两样不同的心境，这又是一个比衬，从中表现出诗人与世无争的隐逸志趣和不慕荣利的淡泊情怀。\n\n　　第三联，鹿门山的林木本为暮霭所笼罩，朦胧而迷离，山月一出，清光朗照，暮雾竟消，树影清晰。诗人完全被大自然陶醉，他忘情地攀登着崎岖的山路，不知不觉间来到了庞公昔时隐居的地方。这微妙的感受，亲切的体验，表现出隐逸的情趣和意境，隐者为大自然所融化，至于忘乎所以。孟浩然仰慕庞公的志节，他在《登鹿门山怀古》中也吟有“昔闻庞德公，采药遂不返。隐迹今尚存，高风邈已远”的诗句。\n\n　　最后二句，这“幽人”，既指庞德公，也是自况，因为诗人彻底领悟了“遁世无闷”的妙趣和真谛，躬身实践了庞德公“采药不返”的道路和归宿。山岩之内，柴扉半掩，松径之下，自辟小径。这里没有尘世干扰，唯有禽鸟山林为伴，隐者在这里幽居独处，过着恬淡而寂寥的生活。\n\n　　全诗虽歌咏归隐的清闲淡素，但对尘世的热闹仍不能忘情，表达了隐居乃迫于无奈的情怀。感情真挚飘逸，于平淡中见其优美，真实。显然，这首诗的题材是写“夜归鹿门”，颇像一则随笔素描的山水小记。但它的主题是抒写清高隐逸的情怀志趣和道路归宿。诗中所写从日落黄昏到月悬夜空，从汉江舟行到鹿门山途，实质上是从尘杂世俗到寂寥自然的隐逸道路。\n\n　　诗人以谈心的语调，自然的结构，省净的笔墨，疏豁的点染，真实地表现出自己内心的体验和感受，动人地显现出恬然超脱的隐士形象，形成一种独到的意境和风格。前人说孟浩然诗“气象清远，心悰孤寂”，而“出语洒落，洗脱凡近”（《唐音癸签》引徐献忠语）。这首七古倒很能代表这些特点。从艺术上看，诗人把自己内心体验感受，表现得平淡自然，优美真实，技巧老到，深入浅出，是成功的，也是谐和的。也正因为诗人真实地抒写出隐逸情趣，脱尽尘世烟火，因而表现出消极避世的孤独寂寞的情绪。', poem_tags = '唐诗三百首,写景,归隐' WHERE poem_title = '夜归鹿门山歌 / 夜归鹿门歌' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '译文二 秋天真的是让人感觉悲凉的季节吗？ 未必是这样吧，轻微的寒冷正是最让人感觉舒适的天气。 碧绿的荷叶虽然快要落完了，但是粉红的荷花却还在盛开，新长出的荷叶就像最小的铜钱那么大。', poem_tags = '秋天,写景,抒怀' WHERE poem_title = '秋凉晚步' AND poem_author = '杨万里';
UPDATE edu_poem SET poem_translation = '从前想移居住到南村来，不是为了要挑什么好宅院；\n听说这里住着许多纯朴的人，愿意同他们度过每一个早晚。\n这个念头已经有了好多年，今天才算把这件大事办完。\n简朴的屋子何必求大，只要够摆床铺就能心安。\n邻居朋友经常来我这里，谈谈过去的事情，人人畅所欲言；\n见有好文章大家一同欣赏，遇到疑难处大家一同钻研。\n\n春秋两季有很多好日子，我经常同友人一起登高吟诵新诗篇。\n经过门前互相招呼，聚在一起，有美酒，大家同饮共欢。\n要干农活便各自归去，闲暇时则又互相思念。\n思念的时候，大家就披衣相访，谈谈笑笑永不厌烦。\n这种饮酒言笑的生活的确很美好，抛弃它实在无道理可言。\n穿的吃的需要自己亲自去经营，躬耕的生活永不会将我欺骗。', poem_notes = '南村：各家对“南村”的解释不同，丁福保认为在浔阳城（今江西九江）下（见《陶渊明诗笺注》）。卜宅：占卜问宅之吉凶。这两句是说从前想迁居南村，并不是因为那里的宅地好。\n素心人：指心性纯洁善良的人。李公焕注云：“指颜延年、殷景仁、庞通之辈。”庞通，名遵，即《怨诗楚调示庞主簿邓治中》之庞主簿。数：屡。晨夕：朝夕相见。这两句是说听说南村有很多朴素的人，自己乐意和他们朝夕共处。\n怀此：抱着移居南村这个愿望。颇有年：已经有很多年了。兹役：这种活动，指移居。从兹役：顺从心愿。这两句是说多年来怀有移居南村的心愿，今天终于实现了。\n蔽庐：破旧的房屋。何必广：何须求宽大。蔽床席：遮蔽床和席子。取足床席：能够放一张床一条席子就可取了。\n邻曲：邻居，指颜延之、殷景仁、庞通等，即所谓“索心人”。据他的《与殷晋安别》诗云：“去岁家南里，薄作少时邻。”可见殷景仁当时曾是他的邻居。抗：同亢，高的意思。抗言：抗直之言，高谈阔论或高尚其志的言论。在昔：指往事。这两句是说邻居经常来访，来后便高谈阔论往事。\n析：剖析文义。魏晋人喜欢辩难析理，如《晋春秋》记载：“谢安优游山水，以敷文析理自娱。”陶渊明也不免有这种爱好。所谓析义，主要是一种哲学理趣，与一般分析句子的含义不同。这两句是说共同欣赏奇文，一起剖析疑难文义的理趣。\n“春秋”两句：大意是说春秋多晴朗天气，恰好登高赋诗。\n斟：盛酒于勺。酌：盛酒于觞。斟酌：倒酒而饮，劝人饮酒的意思。这两句是说邻人间互相招呼饮酒。\n农务：农活儿。辄（zhé）：就。相思：互相怀念。这两句是说有农活儿时各自回去耕作，有余暇时便彼此想念。\n披衣：披上衣服，指去找人谈心。厌：满足。\n此理：指与邻里过从畅谈欢饮之乐。理：义蕴。将：岂。将不胜：岂不美。兹：这些，指上句“此理”。这两句是说，这种邻里之间过从之乐岂不比什么都美？不要忽然抛弃这种做法。\n纪：经营。这两句语意一转，认为与友人谈心固然好，但应当自食其力，努力耕作必有收获。', poem_appreciation = '其一\n\n　　第一首写移居求友的初衷，邻里过往的快乐。吟味全诗，每四句是一个层次。\n\n　　前四句：“昔欲居南村，非为卜其宅。闻多素心人，乐与数晨夕。”追溯往事，以“昔”字领起，将移居和求友联系起来，因事见意，重在“乐”字。古人迷信，移居选宅先卜算，问凶吉，宅地吉利才移居，凶险则不移居。但也有如古谚所云：“非宅是卜，惟邻是卜。”（《左传·昭公三年》）移居者不在乎宅地之吉凶，而在乎邻里之善恶。诗人用其意，表明自己早就向往南村，卜宅不为风水吉利，而为求友共乐。三、四两句，补足卜居的心情。诗人听说南村多有本心质素的人，很愿意和他们一同度日，共处晨夕。陶渊明生活在“真风告逝，大伪斯兴，闾阎懈廉退之节，市朝驱易进之心”（《感士不遇赋》）的时代，对充满虚伪、机诈、钻营、倾轧的社会风气痛心疾首，却又无力拨乱反正，只能洁身自好，归隐田园，躬耕自给。卜居求友，不趋炎附势，不祈福求显，唯择善者为邻，正是诗人清高情志和内在人格的表现。\n\n　　中间四句：“怀此颇有年，今日从兹役。弊庐何必广，取足蔽床席。”由卜居初衷写到如愿移居，是诗意的转折和深化。兹役，指移居搬家这件事。“弊庐”，破旧的房屋，这里指简陋的新居。诗人再次表明，说移居南村的愿望早就有了，终于实现的时候。其欣欣之情，溢于言表。接着又说，只要有好邻居，好朋友，房子小一点不要紧，只要能遮蔽一张床一条席子就可以了，不必一定求其宽敞。不求华堂广厦，唯求邻里共度晨夕，弊庐虽小，乐在其中，诗人旷达不群的胸襟，物外之乐的情趣不言而喻。在对住房的追求上，古往今来，不少有识之士都表现出高远的精神境界。孔子打算到东方少数民族地区居住，有人对他说：那地方太简陋，孔子答曰：“君子居之，何陋之有？”（《论语·子罕》）杜甫流寓成都，茅屋为秋风所破，愁苦中仍然热切呼唤：“安得广厦千万间，大庇天下寒士俱欢颜。呜呼！何时眼前突兀见此屋，吾庐独破受冻死亦足!”（《茅屋为秋风所破歌》）推己及人，表现出忧国忧民的崇高情怀。刘禹锡为陋室作铭：“山不在高，有仙则名；水不在深，有龙则灵。斯是陋室，惟吾德馨。”（《陋室铭》）其鄙视官场的卑污与腐败，追求高洁的品德与志趣，在审美气质上，和陶渊明这首诗有相通的一面。\n\n　　最后四句：“邻曲时时来，抗言谈在昔。奇文共欣赏，疑义相与析。”具体描写得友之乐。邻曲，即邻居。在义熙七年（411年）所作《与殷晋安别》诗中，诗人说：“去年家南里，薄作少时邻。”可知殷晋安（即前所说殷景仁）当时曾与诗人为邻。诗中所说的友人，多是读书人，交谈的内容自然不同于和农民“相见无杂言，但道桑麻长”限于农事（见《归园田居》），而带着读书人的特点和爱好。他们一起回忆往事，无拘无束，毫无保留地交心，他们一起欣赏奇文，共同分析疑难的文义，畅游学海，追求精神上的交流。诗人创作《移居二首》时，正值四十六、七岁的中年时代。这是人生在各方面均臻成熟的时期。中年的妙趣和魅力，在于相当地认识人生，认识自己，从而做自己所能做而且也愿意做的事，享受自己所能享受的生活。和读陶渊明归田以后其它作品一样，《移居二首》给人的感受是鲜明而强烈的：诗人厌恶黑暗污浊的社会，鄙视丑恶虚伪的官场，但他并不厌弃人生。在对农村田园、亲人朋友的真挚爱恋中，他找到了生活的快乐，生命的归宿，心灵的慰安和休息。高蹈、洒脱而又热爱人生，恋念人生，独特而亲切的情调，情趣与理趣共辉，陶渊明其人其诗的魅力，首先来自对人生与自然的诗意般的热爱和把握。\n\n　　陶渊明田园诗的风格向来以朴素平淡、自然真率见称。这种独特的风格，正是诗人质性自然的个性的外化。从这首诗来看，所写移居情事，原是十分平常的一件事。但在诗人笔下款款写来，读者却感到亲切有味。所用的语言，平常如口语，温和高妙，看似浅显，然嚼之味醇，思之情真，悟之意远。如写移居如愿以偿：“弊庐何必广，取足蔽床席。”纯然日常口语，直抒人生见解。“何必”二字，率直中见深曲，映出时人普遍追名逐利的心态，矫矫脱俗，高风亮节，如松间白鹤，天际鸿鹄。又如诗人写和谐坦诚的邻里友谊，仅以“时时来”出之，可谓笔墨省净，引人遐想。欣赏奇文，状以“共”字，分析疑义，状以“相与”，均是传神笔墨。如果奇文自赏，疑义自析，也无不可，却于情味锐减，更无法深化移居之乐的主题。而“共”与“相与”前后相续则热烈抗言之情态呼之欲出，使“奇文共欣赏，疑义相与析”，成为绝妙的诗句，赢得千古读者的激赏。胡仔《苕溪渔隐丛话后集》评陶渊明《止酒》诗云：“坐止高荫下，步止荜门里。好味止园葵，大欢止稚子。’余反复味之，然后知渊明用意……故坐止于树荫之下，则广厦华堂吾何羡焉。步止于荜门之里，则朝市深利吾何趋焉。好味止于噉园葵，则五鼎方丈吾何欲焉。大欢止于戏稚子，则燕歌赵舞吾何乐焉。”要达到这种心境和生活，是要经过长期的思想斗争和痛苦的人生体验，才能对人生有睿智的领悟的，正如包孕万汇的江海，汪洋恣肆，波涛澎湃之后而臻于平静。陶诗看似寻常，却又令人在低吟回味之中感到一种特殊的魅力——“问君何能尔，心远地自偏”；“弊庐何必广，取足蔽床席”等。读者读着这样的诗句，往昔对生活中一些困惑不解的矛盾，也许会在感悟诗意的同时豁然开朗，得到解释，以坦然旷达的胸怀面对万花筒般的人生。陶诗淡而有味，外质内秀，似俗实雅的韵致，在《移居》一诗中也得到生动地体现。\n\n　　其二\n\n　　前人评陶，统归于平淡，又谓“凡作清淡古诗，须有沉至之语，朴实之理，以为文骨，乃可不朽”（施补华《岘佣说诗》）。陶渊明生于玄言诗盛行百年之久的东晋时代，“理过其辞，淡乎寡味”乃诗坛风尚，故以理为骨，臻于平淡皆不为难，其可贵处倒在淡而不枯，质而实绮，能在真率旷达的情意中化入渊深朴茂的哲理，从田园耕凿的忧勤里讨出人生天然的乐趣。读陶诗《移居二首》其二，即可知此意。\n\n　　全诗以自在之笔写自得之乐，将日常生活中邻里过从的琐碎情事串成一片行云流水。首二句“春秋多佳日，登高赋新诗”，暗承第一首结尾“奇文共欣赏，疑义相与析”而来，篇断意连，接得巧妙自然。此处以“春秋”二字发端，概括全篇，说明诗中所叙并非“发真趣于偶尔”（谢榛《四溟诗话》），而是一年四季生活中常有的乐趣。每遇风和日丽的春天或天高云淡的秋日，登高赋诗，一快胸襟，历来为文人引为风雅胜事。对陶渊明来说，在柴桑火灾之后，新迁南村，有此登临胜地，更觉欣慰自得。登高不仅是在春秋佳日，还必须是在农务暇日，春种秋获，正是大忙季节，忙里偷闲，登高赋诗，个中趣味决非整天悠哉游哉的士大夫所能领略，何况还有同村的“素心人”可与共赏新诗。所以士大夫常有的雅兴，在此诗中便有不同寻常的意义。这两句用意颇深却如不经意道出，虽无一字刻划景物，而风光之清靡高爽，足堪玩赏，诗人之神情超旷，也如在眼前。\n\n　　移居南村除有登高赋诗之乐以外，更有与邻人过从招饮之乐：“过门更相呼，有酒斟酌之。”这两句与前事并不连属，但若作斟酒品诗理解，四句之间又似可承接。过门辄呼，无须士大夫之间拜会邀请的虚礼，态度村野，更觉来往的随便。大呼小叫，毫不顾忌言谈举止的风度，语气粗朴，反见情意的真率。“相呼”之意可能是指邻人有酒，特意过门招饮诗人；也可能是诗人有酒招饮邻人，或邻人时来串门，恰遇诗人有酒便一起斟酌，共赏新诗。杜甫说：“肯与邻翁相对饮，隔篱呼取尽余杯。”（《客至》）“叫妇开大瓶，盆中为吾取。……指挥过无礼，未觉村野丑。”（《遭田父泥饮》）诸般境界，在陶诗这两句中皆可体味，所以愈觉含蓄不尽。\n\n　　当然，人们也不是终日饮酒游乐，平时各自忙于农务，有闲时聚在一起才觉得兴味无穷：“农务各自归，闲暇辄相思。相思辄披衣，言笑无厌时。”有酒便互相招饮，有事则各自归去，在这个小小的南村，人与人的关系非常实在，非常真诚。“各自归”本来指农忙时各自在家耕作，但又与上句饮酒之事字面相连，句意相属，给人以酒后散去、自忙农务的印象。这就像前四句一样，利用句子之间若有若无的连贯，从时间的先后承续以及诗意的内在联系两方面，轻巧自如地将日常生活中常见的琐事融成了整体。这句既顶住上句招饮之事，又引出下句相思之情。忙时归去，闲时相思，相思复又聚首，似与过门相呼意义重复，造成一个回环，“相思则披衣”又有意用民歌常见的顶针格，强调了这一重复，使笔意由于音节的复沓而更加流畅自如。这种往复不已的章法在汉诗中较常见，如《苏武诗》、《古诗十九首·西北有高楼》、《古诗十九首·行行重行行》等，多因重叠回环、曲尽其情而具有一唱三叹的韵味。陶渊明不用章法的复叠，而仅凭意思的回环形成往复不已的情韵，正是其取法汉人而又富有独创之处。何况此处还不是简单的重复，而是诗意的深化。过门招饮，仅见其情意的真率，闲时相思，才见其友情的深挚。披衣而起，可见即使已经睡下，也无碍于随时相招，相见之后，谈笑起来没完没了，又使诗意更进一层。如果说过门辄呼是从地邻关系表明诗人与村人的来往无须受虚礼的限制，那么披衣而起、言笑无厌则表明他们的相聚在时间上也不受俗态的拘束。所以，将诗人与邻人之间纯朴的情谊写到极至，也就将摒绝虚伪和矫饰的自然之乐倾泻无余。此际诗情已达高潮，再引出“此理将不胜，无为忽去兹”的感叹，便极其自然了。这两句扣住移居的题目，写出在此久居的愿望，也是对上文所述过从之乐的总结。不言“此乐”，而说“此理”，是因为乐中有理，由任情适意的乐趣中悟出了任自然的生活哲理比一切都高。从表面上看，这种快然自足的乐趣所体现的自然之理与东晋一般贵族士大夫的玄学自然观没有什么两样。王羲之在《兰亭集序》中说：“夫人之相与，俯仰一世，或取诸怀抱，晤言一室之内；或因寄所托，放浪形骸之外。虽趣舍万殊，静躁不同，当其欣于所遇，暂得于己，快然自足，曾不知老之将至。”似乎也可以用来解释陶渊明《移居二首》其二中的真趣所在。但同是“人之相与”、“欣于所遇”之乐，其实质内容和表现方式大不相同。东晋士族自恃阀阅高贵，社会地位优越，每日服食养生，清谈玄理，宴集聚会所相与之人，都是贵族世家，一时名流；游山玩水所暂得之乐，亦不过是无所事事，自命风雅；他们所寄托的玄理，虽似高深莫测，其实只是空虚放浪的寄生哲学而已。陶渊明的自然观虽然仍以玄学为外壳，但他的自然之趣是脱离虚伪污浊的尘网，将田园当作返朴归真的乐土；他所相与之人是淳朴勤劳的农夫和志趣相投的邻里；他所寄托的玄理，朴实明快，是他在亲自参加农业劳动之后悟出的人生真谛。所以，此诗末二句“忽跟农务，以衣食当勤力耕收住，盖第耽相乐，本易务荒，乐何能久，以此自警，意始周匝无弊，而用笔则矫变异常”（张玉谷《古诗赏析》）。结尾点明自然之乐的根源在于勤力躬耕，这是陶渊明自然观的核心。“人生归有道，衣食固其端。孰是都不营，而以求自安？”（《庚戌岁九月中于西田获早稻》）诗人认为人生只有以生产劳动、自营衣食为根本，才能欣赏恬静的自然风光，享受纯真的人间情谊，并从中领悟最高的玄理——自然之道。这种主张力耕的“自然有为论”与东晋士族好逸恶劳的“自然无为论”是针锋相对的，它是陶渊明用小生产者朴素唯物的世界观批判改造士族玄学的产物。此诗以乐发端，以勤收尾，中间又穿插以农务，虽是以写乐为主，而终以勘为根本，章法与诗意相得益彰，但见笔力矫变而不见运斧之迹。全篇罗列日常交往的散漫情事，以任情适意的自然之乐贯串一气，言情切事，若离若合，起落无迹，断续无端，文气畅达自如而用意宛转深厚，所以看似平淡散缓而实极天然浑成。\n\n　　由此可见，作诗以理为骨固佳，其尤贵者当善于在情中化理。晋宋之交，玄风大炽，一般诗人都能谈理。山水诗中的谈玄说理成份多为后人所訾议，而产生于同时的陶渊明田园诗中亦有不少谈理之作，却博得了盛誉。原因就在刚刚脱离玄言诗的山水诗多以自然证理，理赘于辞；而陶诗则能以情化理，理入于情，不言理亦自有理趣在笔墨之外，明言理而又有真情融于意象之中。这种从容自然的境界，为后人树立了很高的艺术标准。', poem_tags = '田园,生活,友情' WHERE poem_title = '移居二首' AND poem_author = '陶渊明';
UPDATE edu_poem SET poem_translation = '我敲打树枝，赶走树上的黄莺，不让它在树上乱叫。\n它清脆的叫声，惊醒了我的梦，害得我在梦中不能赶到辽西，与戍守边关的亲人相见。', poem_notes = '辽西：古郡名，在今辽宁省辽河以西地方。\n妾：女子的自称。\n莫：不。', poem_appreciation = '这首诗，语言生动活泼，具有民歌色彩，而且在章法上还有其与众不同的特点：它通篇词意联属，句句相承，环环相扣，四句诗形成了一个不可分割的整体，达到了王夫之在《夕堂永日绪论》中为五言绝句提出的“就一意圆净成章”的要求。这一特点，人所共称。谢榛在《四溟诗话》中曾把诗的写法分为两种：一种是“一句一意”，“摘一句亦成诗”，如杜甫诗“日出篱东水，云生舍北泥。竹高鸣翡翠，沙僻舞鹍鸡”（《绝句六首》之一），属于此类；另一种是“一篇一意”，“摘一句不成诗”，这首《春怨》诗就是一个典型的例子。王世贞在《艺苑卮言》中更赞美这首诗的“篇法圆紧，中间增一字不得，着一意不得”。沈德潜在《唐诗别裁》中也说：“一气蝉联而下者，以此为法。”\n\n　　但这些评论只道出了这首诗的一个方面的特点，还应当看到的另一特点是：它虽然通篇只说一事，四句只有一意，却不是一语道破，一目了然，而是层次重叠，极尽曲析之妙，好似抽蕉剥笋，剥去一层，还有一层。它总共只有四句诗，却是每一句都令人产生一个疑问，下一句解答了这个疑问，而又令人产生一个新的疑问。这在诗词艺术手法上是所谓“扫处还生”。\n\n　　诗的首句似平地奇峰，突然而起。照说,黄莺是讨人欢喜的鸟。而诗中的女主角为什么却要“打起黄莺儿”呢?人们看了这句诗会茫然不知诗意所在，不能不产生疑问，不能不急于从下句寻求答案。第二句诗果然对第一句作了解释，使人们知道，原来“打起黄莺儿”的目的是“莫教枝上啼”。但鸟语与花香本都是春天的美好事物，而在鸟语中，黄莺的啼声又是特别清脆动听的。人们不禁还要追问：又为什么不让莺啼呢?第三句诗说明了“莫教啼”的原因是怕“啼时惊妾梦”。但人们仍不会满足于这一解释，因为黄莺啼晓，说明本该是梦醒的时候了。那么，诗中的女主角为什么这样怕惊醒她的梦呢?她做的是什么梦呢?最后一句诗的答复是：这位诗中人怕惊破的不是一般的梦，而是去辽西的梦，是惟恐梦中“不得到辽西”。\n\n　　到此，读者才知道，这首诗原来采用的是层层倒叙的手法。本是为怕惊梦而不教莺啼，为不教莺啼而要把莺打起，而诗人却倒过来写，最后才揭开了谜底，说出了答案。但是，这最后的答案仍然含意未伸。这里，还留下了一连串问号，例如：一位闺中少女为什么做到辽西的梦?她有什么亲人在辽西?此人为什么离乡背井，远去辽西?这首诗的题目是《春怨》，诗中人到底怨的是什么?难道怨的只是黄莺，只怨莺啼惊破了她的晓梦吗?这些，不必一一说破，而又可以不言而喻，不妨留待读者去想象、去思索。这样，这首小诗就不仅在篇内见曲折，而且还在篇外见深度了。\n\n　　如果从思想意义去看，它看来只是一首抒写儿女之情的小诗，却有深刻的时代内容。它是一首怀念征人的诗，反映了当时兵役制下广大人民所承受的痛苦。', poem_tags = '唐诗三百首,闺怨,怀人' WHERE poem_title = '春怨 / 伊州歌' AND poem_author = '金昌绪';
UPDATE edu_poem SET poem_translation = '官府粮仓里的老鼠，肥大得像量米的斗一样，看见人来开启粮仓也不逃走。\n守卫边疆的将士没有粮食，辛劳的老百姓正在挨饿，是谁天天把官仓里的粮食送入你们这些官仓老鼠嘴里去的呢？', poem_notes = '官仓（cāng）：官府的粮仓。\n斗（dǒu）：古代容量单位，十升为一斗。一作“牛”。\n健儿：前方守卫边疆的将士。\n谁遣（qiǎn）：谁让。朝朝（zhāozhāo）：天天。君：指老鼠。', poem_tags = '讽刺,官吏,早教古诗100首' WHERE poem_title = '官仓鼠' AND poem_author = '曹邺';
UPDATE edu_poem SET poem_translation = '越王勾践把吴国灭了之后，战士们都衣锦还乡。\n如花的宫女站满了宫殿，可惜如今却只有几只鹧鸪在王城故址上飞了。', poem_notes = '勾践破吴：春秋时期吴、越两国争霸。公元前494年，越王勾践为吴王夫差所败，此后他卧薪尝胆20年，于公元前473年灭吴。\n锦衣：华丽的衣服。《史记·项羽本纪》：“富贵不归故乡，如衣绣夜行，谁知之者？”后来演化成“衣锦还乡”一语。', poem_appreciation = '诗歌不是历史小说，绝句又不同于长篇古诗，所以诗人只能选取这一历史事件中他感受得最深的某一部分来写。他选取的不是这场斗争的漫长过程中的某一片断，而是在吴败越胜，越王班师回国以后的两个镜头。首句点明题意，说明所怀古迹的具体内容。二、三两句分写战士还家、勾践还宫的情况。消灭了敌人，雪了耻，战士都凯旋了；由于战事已经结束，大家都受到了赏赐，所以不穿铁甲，而穿锦衣。只“尽锦衣”三字，就将越王及其战士得意归来，充满了胜利者的喜悦和骄傲的神情烘托了出来。越王回国以后，踌躇满志，不但耀武扬威，而且荒淫逸乐起来，于是，花朵儿一般的美人，就站满了宫殿，拥簇着他，侍候着他。“春殿”的“春”字，应上“如花”，并描摹美好的时光和景象，不一定是指春天。只写这一点，就把越王将卧薪尝胆的往事丢得干干净净的情形表现得非常充分了。都城中到处是锦衣战士，宫殿上站满了如花宫女。这种场景十分繁盛、美好、热闹、欢乐，然而结句突然一转，将上面所写的一切一笔勾销。过去曾经存在过的胜利、威武、富贵、荣华，现在所剩下的，只是几只鹧鸪在王城故址上飞来飞去罢了。这一句写人事的变化，盛衰的无常，以慨叹来表达。过去的统治者莫不希望他们的富贵荣华是子孙万世之业，而诗篇却如实地指出了这种希望的破灭，这就是它的积极意义。\n\n　　诗人将昔时的繁盛和眼前的凄凉，通过具体的景物，作了鲜明的对比，使读者感受特别深切。一般地说，直接描写某种环境，是比较难于突出的，而通过对比，则效果往往能够大大地加强。所以，通过热闹的场面来描写凄凉，就使读者更觉得凄凉的可叹。如此诗前面所写过去的繁华与后面所写后来的冷落，对照极为强烈，前面写得愈着力，后面转得也就愈有力。为了充分地表达主题思想，诗人对这篇诗的艺术结构也作出了不同于一般七绝的安排。一般的七绝，转折点都安排在第三句里，而它的前三句却一气直下，直到第四句才突然转到反面，就显得格外有力量，有神采。这种写法，不是笔力雄健的诗人，是难以挥洒自如的。\n\n　　这首诗的重点在于明写昔日的繁华，以四分之三的篇幅竭力渲染，而以结句写后来的荒凉，由此加以抹杀，转而引出主旨，充分体现了诗人变化多端的艺术技巧。', poem_tags = '咏史怀古' WHERE poem_title = '越中览古' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '朦胧的月色下花儿是那么娇艳，在这迷人的夜晚我要与你秘密相见。我光着袜子一步步迈上香阶，手里还轻轻地提着那双金缕鞋。在画堂的南畔我终于见到了你呀！依偎在你的怀里，我内心仍不停的发颤。你可知道我出来见你一次是多么的不容易，今天晚上我要让你尽情地把我爱怜。', poem_notes = '暗，一作“黯”。笼轻雾：笼罩着薄薄的晨雾。笼，一作“飞”；一作“水”。\n今朝：今夜，一作“今宵”。郎边：一作“侬边”。\n刬（chǎn）：《全唐诗》及《南唐书》中均作“衩”。刬，只，仅，犹言“光着”。刬袜，只穿着袜子着地。唐《醉公子》词中有：“刬袜下香阶，冤家今夜醉。”步：这里作动词用，意为走过。香阶：台阶的美称，即飘散香气的台阶。\n手提：一作“手携”。金缕鞋：指鞋面用金线绣成的鞋。缕，线。\n画堂：古代宫中绘饰华丽的殿堂，这里也泛指华丽的堂屋。南畔：南边。\n一向：一作“一晌。”一向，同一晌，即一时，刹时间。偎：紧紧地贴着，紧挨着。一作“畏”。颤：由于心情激动而身体发抖。\n奴：一作“好”。奴，古代妇女自称的谦词，也作奴家。出来：一作“去来”。\n教君：让君，让你。一作“教郎”；一作“从君”。恣（zì）意：任意，放纵。恣，放纵，无拘束。怜：爱怜，疼爱。', poem_appreciation = '这首艳情词素以狎昵真切著称。\n\n　　上句以夜景铺垫，黯淡的月，迷离的雾，给半夜悄然赴约，生怕被人发觉的女主人公一点方便，暗影中的明艳花朵象征着偷情的少女的娇媚和青春。女人呼男子为“郎”，说明她的心已然相许了。如今主动前去践约，恐怕曾经多次犹豫才有今天的决心的。下面原该接续下片的幽会场面，词人却做了一个颠倒的结构：他把女人行动的一来一去、幽会的一首一尾，这两个画面捏在一起，作为上片，因为它们描摹的都是女人的单独行动。第一个是淡月轻雾中女子潜来的画面。第二个则是幽会事毕，女于仓皇离去的画面。“刬袜步香阶，手提金缕鞋。”女人何等慌张，因来不及穿鞋，光着袜底便跑了。一双手还提着鞋子。这个画面虽涉狠裹，但生动传神，饶有情致。少女初次偷情，上片是这等行为，下片是那样心态。一方面因做错了事而害怕，害羞；一方面因偷情成功，激动而有幸福感。\n\n　　下片写幽会的中心，更加精彩：“画堂西畔见，一向偎人颤。”女人走到践约之处——画堂西畔，一眼瞥见等待她的情郎，便扑过去，紧相偎倚，身子抖动着，好一会儿享受着难得的欢乐。词人用了一个“一向”，一个“颤”，描摹女子的情态，可谓大胆的暴露，狎昵的极度。末二句描摹女子的言语，更是写实之笔：“奴为出来难，教郎恣意怜。”越礼偷情，幽会不易，感郎挚爱，今来就郎。“任你恣意爱怜吧，我只珍惜这幸福的一刻！”女子如此毫无忌讳地吐露爱情，真令男子销魂无限。只有后主之情和他的笔，才会把本人的风流韵事传写得如此淋漓尽致。\n\n　　从这首词看，李煜是如何擅长写人物。他以白描手法，认真细致地描摹人物的行动、情态和语言，毫无雕饰和做作。只凭画面和形象，便做成了艺术品。不过如此狎昵的猥褒的内容，不足为法。和古代《诗经》、《汉乐府》五代诗词向等描摹妇女的热烈坦率的爱情、反叛坚定的性格的那些名著，是不可相提并论的。\n\n　　李煜的这首词，极俚，极真，也极动人，用浅显的语言呈现出深远的意境，虽无意于感人，而能动人情思，达到了王国维所说“专作情语而绝妙”的境地。', poem_tags = '少女,爱情' WHERE poem_title = '菩萨蛮·花明月暗笼轻雾' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '细细算来十年宦海沉浮，人在十处度过十个中秋。旧梦未了今秋忽如新梦，飘然人到黄鹤旧时山头。老子今夜豪兴不浅，忽忆当年庾亮守鄂州，天教历史上的聚会重现，我辈今朝宴饮赏月在南楼。迢迢银河暗淡无光，独见一轮皓月当空浮。\n江北烟散，江南雾收，江水平似白练滔滔东流。山河破碎，南北分裂，月光依然照临一片清愁。月中嫦娥冷眼相看，当笑我白发东归，空损貂裘，壮志不酬。我今举杯邀明月，肯否与我结伴共去沧洲？', poem_notes = '水调歌头：词牌名。唐朝大曲有《水调歌》，据《隋唐嘉话》，为隋炀帝凿汴河时所作。宋乐入“中吕调”，见《碧鸡漫志》卷四。凡大曲有“歌头”，此殆裁截其首段为之。九十五字，前后片各四平韵。亦有前后片两六言句夹叶仄韵者，有平仄互叶几于句句用韵者。\n新梦：未曾料到之意。\n黄鹤旧山头：指黄鹤山，又名黄鹄山，今称蛇山，在湖北武昌西。传说仙人王子安曾乘黄鹤过此，因此为名。\n“老子”三句：诗人自谓。东晋庾亮镇武昌时，曾与僚属殷浩等人秋夜登南楼，曰：“老子于此处兴复不浅”（《世说新语·容止》）。吟诗宴饮，谈笑甚欢。作者用以描绘自己此次登南楼游乐的情景。个中：此中。\n星汉：银河。这里指天上的星星。\n玉镜：指月亮。\n秦、楚：分指古时秦国和楚国的所在地，秦北楚南，借指北地与南地。\n熨江：此处形容江面平静。熨：烫平。江：指长江。\n关河：山河。关：指关塞。离合：这里用作偏义复词，指分裂。\n南北依旧照清愁：南北山河分裂，月光仿佛笼罩着无边的“清愁”。\n妲娥：即嫦娥。冷眼：对事物持冷静或冷淡的态度。\n霜鬓：鬓发如霜，形容年老。\n空敝黑貂裘：用《战国策·秦策》的故事。苏秦游说秦王，十次上书均未被采纳，资用乏绝，所穿黑貂皮衣服也已破旧不堪，只好离秦返家。这里比喻作者理想未能实现。空：徒然。敝黑貂裘：形容奔走连年，潦倒郎当。敝：破烂。\n酾酒（shāi）：斟酒。\n蟾（chán）兔：古代神话传说，月中有蟾蜍、白兔。此指月亮。\n沧洲：水边之地，隐者所居。此指故乡。', poem_tags = '豪放,中秋,月亮,思乡' WHERE poem_title = '水调歌头·细数十年事' AND poem_author = '范成大';
UPDATE edu_poem SET poem_translation = '女说：“公鸡已鸣唱。”男说：“天还没有亮。不信推窗看天上，启明星已在闪光。”“宿巢鸟雀将翱翔，射鸭射雁去芦荡。”\n\n“野鸭大雁射下来，为你烹调做好菜。佳肴做成共饮酒，白头偕老永相爱。”女弹琴来男鼓瑟，和谐美满在一块。\n\n“知你对我真关怀呀，送你杂佩答你爱呀。知你对我体贴细呀，送你杂佩表谢意呀。知你爱我是真情呀，送你杂佩表同心呀。”', poem_notes = '昧旦：天色将明未明之际。\n兴：起。视夜：察看夜色。\n明星：启明星，即金星。\n将翱将翔：指已到了破晓时分，宿鸟将出巢飞翔。\n弋（yi 义）射：用生丝做绳，系在箭上射鸟。凫：野鸭。\n言：语助词，下同。加：射中。一说“加豆”，食器。\n与：犹为。宜：用适当地方法烹饪。译为烹饪\n御：用，弹奏。\n静好：和睦安好。\n来：借为“赉”，慰劳。\n杂佩：古人佩饰，上系珠、玉等，质料和形状不一，故称杂佩。\n顺：柔顺。\n问：慰问，问候。\n好（hào耗）：爱恋。', poem_appreciation = '第一个镜头：鸡鸣晨催。起先，妻子的晨催，并不令丈夫十分惬意。公鸡初鸣，勤勉的妻子便起床准备开始一天的劳作，并告诉丈夫“鸡已打鸣”。“女曰鸡鸣”，妻子催得委婉，委婉的言辞含蕴不少爱怜之意；“士曰昧旦”，丈夫回得直白，直决的回答显露出明显的不快之意。他似乎确实很想睡，怕妻子连声再催，便辩解地补充说道：“不信你推窗看看天上，满天明星还闪着亮光。”妻子是执拗的，她想到丈夫是家庭生活的支柱，便提高嗓音提醒丈夫担负的生活职责：“宿巢的鸟雀将要满天飞翔了，整理好你的弓箭该去芦苇荡了。”口气是坚决的，话语却仍是柔顺的。钱钟书说：“‘子兴视夜’二句皆士答女之言；女谓鸡已叫旦，士谓尚未曙，命女观明星在天便知”（《管锥编》第一册）。此说符合生活实情；而士女的往覆对答，也使第一个镜头更富情趣。就女催起而士贪睡这一情境而言，《齐风·鸡鸣》与此仿佛，但人物的语气和行动与此不同。《鸡鸣》中女子的口气疾急决然，连声催促，警夫早起，莫误公事；男的却一再推脱搪塞，淹恋枕衾而纹丝不动。此篇女子的催声中饱含温柔缱绻之情，男的听到再催后作出了令妻子满意的积极反应。首章与次章之间的空白，可理解为对男子的举动作了暗场处理，这样就自然地进入下面的情节。\n\n　　第二个镜头：女子祈愿。妻子对丈夫的反应是满意的，而当他整好装束，迎着晨光出门打猎时，她反而对自己的性急产生了愧疚，便半是致歉半是慰解，面对丈夫发出了一连串的祈愿：一愿丈夫打猎箭箭能射中野鸭大雁；二愿日常生活天天能有美酒好菜；三愿妻主内来夫主外，家庭和睦，白首永相爱。丈夫能有如此勤勉贤惠、体贴温情的妻子，不能不充满幸福感和满足感。因此，下面紧接着出现一个激情热烈的赠佩表爱的场面，就在情理之中而不得不然的了。其实，诗人唱到这个琴瑟和谐的场面也为之激动，他情不自禁地在旁边感叹道：“琴瑟在御，莫不静好。”恰似女的弹琴，男的鼓瑟，夫妇和美谐调，生活多么美好。诗歌具有跳跃性，此篇的章节和诗句间的跳跃性更大。因而也给接受者留下了更为广宽的想像再创造的空间。关于这两句，张尔歧《蒿菴闲话》说：“此诗人凝想点缀之词，若作女子口中语，觉少味，盖诗人一面叙述，一面点缀，大类后世弦索曲子。”此解颇具创意，诗境也更饶情致，实为明通之言。\n\n　　第三个镜头：男子赠佩。投之以木瓜，报之以琼琚。丈夫这一赠佩表爱的热烈举动，既出于诗人的艺术想像，也是诗歌情境的逻辑必然。深深感到妻子对自己的“来之”、“顺之”与“好之”，便解下杂佩“赠之”、“问之”与“报之”。一唱之不足而三叹之，易词申意而长言之。在急管繁弦之中洋溢着恩酣爱畅之情。至此，这幕情意融融的生活小剧也达到了艺术的高潮。末章六句构成三组叠句，每组叠句易词而申意，把这位猎手对妻子粗犷热烈的感情表现得淋漓酣畅。\n\n　　王质《诗总闻》说：“大率此诗妇人为主辞，故‘子兴视夜’以下皆妇人之词。”此说影响直至清代，故清人论“对答体”诗，大多追溯至《孔雀东南飞》而不及《诗经》。其实，《女曰鸡鸣》是首极富情趣的对话体诗，对话由短而长，节奏由慢而快，情感由平静而热烈，人物个性也由隐约而鲜明。\n\n　　此篇的诗旨，至此也可以不辨自明了。《毛诗序》谓“刺不说德也；陈古义以刺今，不说德而好色也”，过于穿凿。朱熹《诗集传》以为“此诗人述贤夫妇相警戒之词”，则似有顾头不顾尾之嫌。闻一多《风诗类钞》曰：“《女曰鸡鸣》，乐新婚也。”也有难概全篇之感。统观全篇，实是赞美青年夫妇和睦的生活、诚笃的感情和美好的人生心愿的诗作。', poem_tags = '诗经,爱情,民谣' WHERE poem_title = '国风·郑风·女曰鸡鸣' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '齐国国王派遣使者去问候赵威后，书信还没有启封，威后就问使者说：“今年的年成好吗？老百姓好吗？齐王好吗？”使者不高兴，说：“下臣奉齐王的使命，出使到威后这里来，现在您不问齐王，反而先问年成和百姓，岂不是把贱的放在前面，把尊贵的放在后面吗？”威后说：“不是这样。假如没有收成，哪里有百姓？假如没有百姓，哪里有国君？因而有所问，能不问根本而问末节的吗？”\n\n　　威后进而又问他说：“齐国有个处士叫钟离子，平安无事吗？这个人做人呀，有粮食的人给吃，没粮食的人也给吃；有衣服的人给穿，没有衣服的人也给穿。这是帮助国君抚养老百姓的人呀，为什么到今天不让他在位成就功业？叶阳子平安无事吗？这个人做人呀，怜悯那些无妻无夫的人，顾念抚恤那些无父无子的人，救济那些困苦贫穷的人，补助那些缺衣少食的人，这是帮助国君养育百姓的人，为什么到今天不让他在位成就功业？北宫氏的女儿婴儿子平安无事吗？她摘掉耳环等装饰品，到老不嫁，来奉养父母。这是带领百姓尽孝心的人，为什么到今天还不让她上朝呢？这两个处士没有成就功业，一个孝女也不上朝，靠什么来统治齐国，做百姓的父母呢？於陵的那个子仲还在吗？这个人做人呀，对上不向国君称臣，对下不治理他的家，也不愿同诸侯交往，这是带领百姓无所作为的人，为什么到今天还不杀掉呢？', poem_notes = '1、齐王：战国时齐王建，齐襄王之子。赵威后：战国时赵惠文王妻。惠文王死，其子孝成王立，因年幼由威后执政。\n2、发：启封。\n3、岁亦无恙耶：年成还好吧？岁，年成。亦，语助词，无义。无恙，无忧，犹言“平安无事”。\n4、说：通“悦”。\n5、奉使使威后：奉使命出使到威后这里来。\n6、苟：假如。\n7、处士：有才能、有道德而隐居不仕的人。钟离子：齐国处士。钟离，复姓。子，古时对男子的尊称。\n8、食（sì）：拿食物给人吃。\n9、衣（yì）：拿衣服给人穿。\n10、不业：不是他做官以成就工业。\n11、叶（shè）阳子：齐国处士，叶阳，复姓。\n12、鳏（guān）：老而无妻。\n13、恤：抚恤。独，老而无子。\n14、振：通“赈”，救济。\n15、息：繁育。\n16:、北宫之女婴儿子：北宫氏的女子婴儿子。北宫，复姓。婴儿子是人名。\n17、彻：通“撤”，除去。环：指耳环、臂环一类的饰物。瑱：一种玉制的耳饰。\n18、是皆率民而出于孝情者也：这些都是带领百姓行孝的行为。\n19、不朝：不使她上朝。古时夫人受封而有封号者为“命妇”，命妇即可入朝。此句意即，为什么至今不封婴儿子为命妇，使她得以上朝见君呢？\n20、子万名：以万名为子女，犹言“为民父母”。\n21、於（wū）陵子仲：齐国的隐士。於陵：齐邑名，故城在今山东省长山县西南。\n22、索：求。', poem_tags = '古文观止,高中文言文,对话,忧国忧民' WHERE poem_title = '赵威后问齐使' AND poem_author = '佚名';
UPDATE edu_poem SET poem_tags = '咏物,写雪,品格,抒怀,感伤' WHERE poem_title = '采桑子·塞上咏雪花' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '夜中不能寐，夜里睡不着觉。\n起坐弹鸣琴。起床坐着弹琴。\n薄帷鉴明月，月光照在薄帷上。\n清风吹我襟。清风吹着我的衣襟。\n孤鸿号外野，孤鸿（天鹅）在野外哀号。\n翔鸟鸣北林。飞翔盘旋着的鸟在北林鸣叫。\n徘徊将何见？这时徘徊会看到些什么呢？忧思独伤心。', poem_notes = '炎光：日光。\n湍濑（tuúnlài团赖）：水流沙石之上叫作湍，也叫濑。这句话的实际意思即指大水在沙石的河滩上流着。\n扶桑：传说中的神树名，据说太阳每早就从这棵树上升起。说法详见《山海经》、《十洲记》。\n长剑句：宋玉《大言赋》：“长剑梗邰伲葩倚天外。”以上二句是用弓挂扶桑，剑倚天外来衬托此篇所写的“雄杰士”的形象高大。\n砥砺，磨刀石。二句是说，和“雄杰士”的形象比较起来，泰山小得如同一块磨刀石，黄河窄得象一条带子。《史记·高祖功臣侯者表》：“使河如带，泰山若砺，国以永宁，爱及苗裔。”这里袭用其句。\n庄周：战国时期的唯心主义哲学家，道家学派的代表人物之一，主张虚无随化，是没落阶级的代言人。著有《庄子》。\n荣枯：本意是开花和枯萎，一般引申为生死、兴衰等含义。\n《庄子·列御寇》云：庄子临死时，嘱咐门人们待他死后把他的尸体丢在旷野上，不必埋葬。门人说，怕让乌鸢啄食。庄子说，埋下去叫蝼蚁食，抛在上面叫乌鸢食，为什么要偏待乌鸢呢？以上四句是说，庄子虽然达观，但也不能长生不死；死后抛于旷野，也不能逃避乌鸢的啄食。\n雄杰士：阮籍所幻想的能摆脱人世，超然于天地之外的人物。他的《大人先生传》就是描绘的这样一个形象。\n功名：这里指道德名声。从此大：指一直响亮地传下去。', poem_appreciation = '魏晋之际，天下多故，政治严酷，名士多有生命之忧。自古以来困扰着人们的生命倏忽如逝水的忧虑更迫切地摆在人们的面前。面对人生短暂之忧，吃药求仙者有之，以扩展生命时间之长度；疯狂享乐者有之，以增加有限生命的密度。这几乎已成了当时士大夫企图摆脱生命之忧的两种基本生活态度。但是，在诗人阮籍看来，这两种消极的人生态度并不能从本质上超越人生的短暂，所以，《咏怀诗》中虽有大量忧生之嗟的作品，也有表现如何超越人生短暂的积极态度，提出不同于以上两种生活态度的积极主张的作品，这就是《咏怀诗》第三十八首《咏怀·炎光延万里》、第三十九首《咏怀·壮士何慷慨》两首诗。它们抒发了诗人欲建功立名、兼济天下的豪情壮志，以为只有功名和事业才能摆脱人生的荣枯，只有忠义和气节才能流令名于千古，从根本上超越生命之短暂。\n\n　　第三十八首《咏怀·炎光延万里》前六句以象征的手法，描绘了诗人心目中“雄杰士”的形象。开篇“炎光”二句出语恢弘，渲染出了一个极为雄阔的环境，为下四句直接描绘“雄杰士”的活动提供了一个无比壮阔的空间。这一联作为起句，横空而来，奠定了全诗并吞宇内，包举八荒的气势。“弯弓”二句写“雄杰士”的活动。“扶桑”是传说中东海日出处之神树。全句是说“雄杰士”把弯弯的弓弦挂在扶桑树上。“长剑”句是说“雄杰士”把长剑倚靠在天外。字面上看这句出典于宋玉《大言赋》，实则与前一句一样，是以极度夸张之语刻画了“雄杰士”无比高大的形象。这种夸张明显带有象征意味，所以大胆奇特而又不失之险怪，它与前二句壮阔的空间描写在气氛上十分谐和，更增强了此诗涵浑六合的壮浪气象。接下“泰山”二句是写“雄杰士”眼中所见。因为“雄杰士”形象无比高大，所以在他眼中，高高的泰山好像只是一块磨刀石（砥砺），长长的黄河也似乎只是一条衣带。这二句出典于《史记·高祖功臣年表序》中的“封爵之誓”：“使河为带，泰山若厉（砺）。国以永宁，爰及苗裔。”但誓词乃是表示黄河不能成为带，泰山也不能成为砺，故功臣后裔将永远享国的意思。阮籍借用这二句却赋予了新的意义，仍是为了烘托“雄杰士”的高大形象。\n\n　　以上六句总的说来是刻画“雄杰士”的形象，诗人是借以表现自已超越生命短暂的积极人生主张，即下文的“功名从此大”的意思。“视彼庄周子”以下四句是用了《庄子·列御寇》篇中的故事：庄子将死，他的学生要厚葬他，庄子却主张不要棺椁的天葬，学生们说，天葬会被乌鸢食尸，庄子却说：“在上为乌鸢食，在下为蝼蚁食，夺彼与此，何其偏也!”庄子的回答本是很旷达的了，但诗用此典却是表达诗人自己的人生态度，即人生无论是生（“荣”）还是死（“枯”）都不足倚凭，到头来谁还不是为乌鸢蝼蚁所食呢！仅从此四句看，似乎诗人与庄周子对人生的态度没有什么区别。庄子之荣枯不足赖就是齐生死，即视生死是同一的，没有什么区别；阮籍虽从庄子的故事中也看出“荣枯何足赖”，却并不如庄子那样以生死为同一的虚无，他实际上要超越生死之界线，建立永恒的“功名”。\n\n　　所以，最后诗人用“岂若雄杰士，功名从此大”二句点明主题，收束全篇。他承认庄子的命题：“荣枯何足赖”，但又指出：生命并不仅仅是一从生到死的过程；雄杰之士便是以其“功名”，延续了自己的存在。回顾开头的描写，便可以看出这一形象，实际是超越肉身生死的象征。\n\n　　关于这首诗古今多以为诗人是鄙薄“功名之辈”，黄节先生的看法具有代表性。他说：“‘雄杰士’——即指上挂弓、倚剑、砺山、带河——功名之辈。‘岂若’二字，有不与为伍意。亦犹传所云：‘不与尧舜齐德，不与汤武并功’也。”以为诗人用“岂若”二字否定了“雄杰士”，而实际上诗人是说“庄周子”的人生主张不如“雄杰士”的人生态度那样真正超越了生死之限，建立了永恒的功名。当然，阮籍在《咏怀诗》也说过否定功名的话，但这大都是在他感觉到功名无法实现的时候。', poem_tags = '古诗三百首,孤独,忧思,咏怀' WHERE poem_title = '咏怀八十二首·其一' AND poem_author = '阮籍';
UPDATE edu_poem SET poem_translation = '身穿一件羔皮裘，素丝合缝真考究。退朝公餐享佳肴，逍遥踱步慢悠悠。\n身穿一件羔皮袄，素丝密缝做工巧。逍遥踱步慢悠悠，公餐饱腹已退朝。\n身穿一件羔皮袍，素丝纳缝质量高。逍遥踱步慢悠悠，退朝公餐享佳肴。', poem_notes = '五紽：指缝制细密。五，通“午”，岐出、交错的意思；紽（tuó驼），丝结、丝钮，毛传释为数（cù促），即细密。\n食（sì四）：公家供卿大夫之常膳。\n委蛇（wěi yí尾移）：音义并同“逶迤”，悠闲自得的样子。\n革：裘里。\n緎（yù玉）：缝也。\n缝：皮裘；一说缝合之处。\n总（zǒng）：纽结。一说毛诗传释为“数”，与紽同。', poem_appreciation = '赞美说\n\n　　汉儒对《羔羊》篇的解释主要有毛齐鲁韩四家，其中毛诗的解释来自《毛诗正义》，而齐鲁韩三家诗几乎都已亡佚。 现依据王先谦之说，取其书《诗三家义集疏》中认定的齐鲁韩三家诗说观点。在《羔羊》篇中，“羔羊”、“素丝”、“退食”、“委蛇”四词是该诗的关键词，其中“羔羊”是主旨的代表，故理解汉儒对《羔羊》篇的解释，应先从后三词开始，再分析“羔羊”所代表的主旨。\n\n　　“素丝”。在《诗三家义集疏》的资料中，齐氏认为“素丝”指“君子朝服”；韩氏则认为素喻絜白，丝喻屈柔；注鲁诗的谷永注“素”为“行絜”，王逸注为“皎洁之行”；毛氏注为“白也”。《诗三家义集疏》总结为：“薛以性言，谓其心之精白，谷王以行言， 美其行之洁清也。‘丝喻屈柔’者，屈柔以行言，立德尚刚而处事贵忍，故屈柔亦为美德。 ”; 可见，齐氏是从“素丝”作为社会服装的角度进行分析以确定身份地位为大臣，而其余诸家则抓住其本身“白”与“柔”之特性，认为“素丝”是用来赞美大臣之高洁、谦忍。\n\n　　“退食”。 王先谦先生梳理齐鲁韩三家诗注，认为“‘退食自公’者，自公朝退而就食，非谓退归私家。 永疏‘私门不开’，正释‘公’之义。卿大夫入朝治事，公膳于朝，不遑家食，故私门为之不开也。 ”; 而《毛诗正义》中先列郑玄笺，云退食意谓减膳。再引孔颖达正义释“减膳”之意：“减膳食者，大夫常膳日特豚，朔月少牢，今为节俭减之也。 ”后引王肃、孙毓“减膳”论“减膳”为合理合制之举。故从身份属性上来讲，两种解释都将对象定义为朝堂之臣，非宦官等类属。 从特征属性来看，则知此人尊制守法，依朝廷之律，依传统之令，非标新立异或先斩后奏之人，可谓是遵从、执行制度法令的模范，是朝廷形象的代言。\n\n　　“委蛇”。 毛氏注曰：“委蛇，行可从迹也。 ”又言：“既外服羔羊之裘，内有羔羊之德，故退朝而食，从公门入私门，布德施行，皆委蛇然，动而有法，可使人踪迹而效之。 言其行服相称，内外得宜。 ”郑玄笺云：“从于公，谓正直顺于事也。委蛇，委曲自得之貌，节俭而顺，心志定，故可自得也。 ”; 韩氏注为：“逶迤，公正貌。 ”; 二者看似不同，实则互补。 恰如陈启源所云：“毛‘委蛇’传以为‘行可迹踪’，韩‘逶迤’训作‘公正貌’，两意义正相成，为其公正无私，故举动光明，始终如一，可从迹仿效，即毛序所谓正直也。 ”; 可知所美大臣之言行，首先是公正无私的，非弄权之人。 其次，该人言行有迹可循，则可使人仿迹模仿，谓其人有影响力，是值得他人对其进行赞美乃至宣扬的。\n\n　　“羔羊”为此诗篇之题，也是该诗主旨的代表，因而应以“羔羊”为核心来分析该诗主旨。 《毛诗正义》：“《羔羊》，《鹊巢》之功致也。召南之国，化文王之政，在位皆节俭正直，德如羔羊也。 ”后注：“《鹊巢》之君，积行累功，以致此《羔羊》之化，在位卿大夫竞相切化，皆如此《羔羊》之人。 ” 《诗三家义集疏》：齐说曰：“羔羊皮革，君子朝服。辅政扶德，以合万国。 ”韩说曰：“诗人贤仕为大夫者，言其德能称，有絜白之性，屈柔之行，进退有度数也。” 据此可知，该诗的主旨是赞美有德行之君子， 不同在与有的学者认为是在赞美召南大夫，而当时其他的学者认为是美召公， 毛氏则只说 “在位卿大夫”。实际上，召公于周朝亦是在朝之臣，故综合来看，可将《羔羊》一诗的主旨定为赞美有德之大臣。\n\n　　讽刺说\n\n　　对这首诗表现特点的理解，要反美为刺。即是说，全诗不用一个讥刺的词，更没有斥责之语，诗人只是冷静而客观地抉取大夫日常生活中习见的一个小片断，不动声色用粗线条写真。先映入诗人眼帘的是那官员的服饰——用白丝线镶边的羔裘。毛传说“大夫羔裘以居”，故依其穿戴是位大夫。头两句从视觉来写，暗示其人的身份，第三句是所见也是所想，按常规大夫退朝用公膳，故诗人见其人吃饱喝足由公门出来，便猜想其是“退食自公”。《左传·襄公二十八年》：“公膳，日双鸡。”杜预注：“谓公家供卿大夫之常膳。”这与当时民众的生活水准相对照，有天上地下之别，《孟子·梁惠王上》中孟子阐述的符合王道的理想社会，在丰收年成，也才是“七十者可以食肉矣”，而大夫公膳常例竟是“日双鸡”，非常奢侈。诗人虽然没有明言“食”是什么，以春秋襄公时代的公膳例之，大约相差无几。诗人生活在同时代，一见其人“退食自公”必然有所触动，想得很多，也许路有饿殍的惨象浮现在他眼前。正因为如此，所以厌恶之情不觉油然而生，“委蛇委蛇”诗句涌出笔端。这第四句“美中寓刺”，可谓点睛之笔，使其人仿佛活动起来：你看他，慢条斯理，摇摇摆摆，多么逍遥惬意。把这幅貌似悠闲的神态，放在“退食自公”这个特定的场合下，便不免显出滑稽可笑又丑陋可憎了，言外诗人的挖苦嘲弄可以想见：这个自命不凡的家伙，实则是个白吃饭的寄生虫！三章诗重复这个意思，回环咏叹，加深了讥刺意味。各章三、四两句，上下前后颠倒往复。', poem_tags = '诗经' WHERE poem_title = '羔羊' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '译文 春风就像贵客一般，所到之地立刻繁华起来。 春风吹来时融化千山的积雪，吹过后留下万国的花香。', poem_tags = '春天,赞颂,写风' WHERE poem_title = '春风' AND poem_author = '袁枚';
UPDATE edu_poem SET poem_translation = '年少之时，无忧无虑，体魄健全，精力充沛，真是朝气蓬勃。\n当梨枣成熟之时，少年杜甫频频上树摘取，一日至少千回。\n可又想现在由于年老力衰，行动不便，因此坐卧多而行立少。\n一生不甘俯首低眉，老来却勉作笑语，迎奉主人。不禁悲从中来，忧伤满怀。\n一进家门，依旧四壁空空，家无余粮，一贫如洗。老夫老妻，相对无言，满面愁倦之色。\n只有痴儿幼稚无知，饥肠辘辘，对着东边的厨门，啼叫发怒要饭吃。', poem_notes = '心尚孩：心智还未成熟，还像一个小孩子。杜甫十四五岁时已被当时文豪比作班固、扬雄，原来他那时还是这样天真。\n犊：小牛。健：即指下二句。\n少行立：走和站的时候少，是说身体衰了。\n强：读上声。强将笑语：犹强为笑语，杜甫作客依人，故有此说不出的苦处。真是：“声中有泪，泪下无声”。主人：泛指所有曾向之求援的人。\n依旧：二字痛心，尽管百般将就，却仍然得不到人家的援助，穷得只有四壁。\n此句是说老妻看见我这样愁眉不展也面有忧色。\n古时庖厨之门在东。这二句写出小儿的稚气，也写出了杜甫的慈祥和悲哀。他自己早说过：“所愧为人父，无食致夭折。”（《自京赴奉先县咏怀五百字》）但也正是这种主活实践，使杜甫对人民能具有深刻的了解和同情。', poem_appreciation = '首句不谈忧，而是谈喜；不说老，而忆少。从诗中可以同时看到他少年生活的一个片断。诗人回忆年少之时，无忧无虑，体魄健全，精力充沛，真是朝气蓬勃。所谓“健如黄犊走复来”，就是生动的写照。清杨伦称此句“形容绝倒，正为衬出下文”（《杜诗镜铨》卷八）。庭前，八月梨枣熟，一日上树能千回。即当梨枣成熟之时，少年杜甫频频上树摘取，一日千回。所谓“千回”，只是夸张的语气，喻其多也。少年杜甫“心尚孩”，这个尚字用得非常贴切，说明了一颗天真无邪的童心，在十五岁时，仍在持续跳跃着。一个“尚”字，就概括了杜甫由童年到少年的天真烂漫、活泼可爱。诗人抓住了少年的气质、性格特征，以跳动的笔触把它活灵活现地勾勒出来。这里并非没有目的地表现少年自我，也不是用喜悦的心情颂扬少年自我，而是以忧伤的心情去回忆少年自我的无忧无虑的生活，因而就深深地蕴含着悲痛、愤懑的感情。杨伦对这首诗开头的眉批是：“聊以泄愤，不嫌径直。”（《杜诗镜铨》卷八）\n\n　　“即今倏忽已五十，坐卧只多少行立。”诗人虽用“倏忽”二字，然从“十五”至“五十”其间沧桑都是读者可以想见。由于年老力衰，行动不便，因此坐卧多而行立少。体弱至此，却不能静养，因生活无着，还须出入于官僚之门，察言观色，养活一家老小。一生不甘俯首低眉，老来却勉作笑语，迎奉主人。内心痛苦不言而喻。不禁悲从中来，忧伤满怀，而发出“悲见生涯百忧集”的概叹。此为全诗之诗眼，它把诗人的情绪凝聚到“悲”字上。它不仅因老而悲，也因贫而悲，更因依附别人、缺乏自身独立存在的价值而悲。尤可悲者，诗人不是悲一时一事，而是悲其一生。悲其一生为人民而悲。“悲见生涯百忧集”实具有高度的概括性，这是全诗主线，它与诗题相呼应，又因往昔境遇凄惨而悲，联想到当时老窘之境而悲，在结构上可谓承上；由此出发，为以下具体描写家贫先写一笔，可谓启下。“入门依旧四壁空，老妻睹我颜色同。痴儿不知父子礼，叫怒索饭啼门东。”写家中凄景。一进家门，依旧四壁空空，家无余粮，一贫如洗。老夫老妻，相对无言，满面愁倦之色。只有痴儿幼稚无知，饥肠辘辘，对着东边的厨门，啼叫发怒要饭吃，经过诗人的具体描写，其忧伤痛苦之状，如在眼前。为了表现百感交集的感慨，诗人以数字强化衬托悲状，强化悲的情怀。例如，诗中以“十五”比“五十”，就划分了自我的两个时代。以“ 八月”果熟，“一日”上树“千回”，来形容“十五”岁的少年的灵敏活跃，天真烂漫。用“四壁空”写“百忧集”，就充实了忧的内容。用“健如黄犊”对比“坐卧只多”，用“走复来”对比“少行立”，用“强作笑语”对比“悲见生涯”，更见出悲的氛围之浓。尤其令人心酸的是，诗人还将自己的童心少年和自己的痴儿作了对比。自己年少时，无忧无虑，不愁吃穿，却想不到已入老境之际，自己的儿子却饥饿难忍，啼叫怒索。在诗人笔下，不仅如实地表现了自己的凄凉处境，而且逼真地写出了老妻、痴儿的表情、姿态，非常富于人情味。\n\n　　杜甫在《进雕赋表》中，称自己的作品善于“沉郁顿挫”。这也表现在《百忧集行》中。它“悲愤慷慨，郁结于中”，“沉郁苍凉，跳跃动荡”（陈廷焯《白雨斋词话》卷一）。诗人不幸的遭遇，切身的体验，内心的痛楚，在诗中化为一股股情感流 。它回旋激荡，悲愤呼号，久久不息。', poem_tags = '岁月,生活,凄凉' WHERE poem_title = '百忧集行' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '疏疏的星，淡淡的月，冷冷清清秋千院，愁如云，恨似雨，布满芙蓉般的脸面。\n寂寞伤心，深情在燕足上系红线，对镜照芳容，形影孤单好烦恼，百无聊赖摇团扇。\n看香炉里烟气低沉，池塘中落花成片。\n这些景物都像一行行字句写入了相思传。', poem_notes = '淡月：不太明亮的月亮或月光。\n愁云：谓色彩惨淡，望之易于引发愁思的烟云。\n伤情：伤感\n燕足留红线：曲出宋曾慥类说引《丽情集·燕女坟》：宋末妓女姚玉京后夫敬瑜，敬瑜死后，玉京守志奉养公婆。常有双燕筑巢于梁间。一日，其中一只被鸷鹰捉去，另一只孤飞悲鸣，停在玉京臂上，似要与她告别。玉京以红线系燕尾，嘱咐明年再来作伴，明年燕子果然来到，此后相伴六、七年。到玉京病死那年，燕子也飞到坟地悲鸣而死。\n恼人：令人着恼。\n鸾影：比喻女子身影。\n兽炉：兽形的金属香炉。\n沉水烟：即沉水香，俗名沉香。一种名贵香料。\n翠沼：翠绿的池塘。\n一行：当即。', poem_tags = '写人,相思,散曲' WHERE poem_title = '塞鸿秋·春情' AND poem_author = '张可久';
UPDATE edu_poem SET poem_translation = '译文 桃花朵朵盛开，那或深或浅的颜色，好似美貌姑娘面容上浓淡相宜的薄妆，让人心怡。 可无情的春风却将那美丽的花瓣吹落于我的白衣之上，这让人情何以堪啊！', poem_tags = '春天,写花,桃花,抒怀' WHERE poem_title = '桃花' AND poem_author = '元稹';
UPDATE edu_poem SET poem_translation = '人谁不顾虑要衰老，老了又有谁来对他表示爱怜？\n身体渐瘦衣带越来越要收紧，头发稀少戴正了的帽子也会自己偏斜到一边。\n书卷搁置起来不再看是为了爱惜眼睛，经常用艾灸是因为年迈力衰诸病多缠。\n经历过的世事见多识也就广，接触了解的人越多观察起来更加一目了然。\n细细想来老了也有好的一面，克服了对老的忧虑就会心情畅快无挂也无牵。\n不要说太阳到达桑榆之间已近傍晚，它的霞光余辉照样可以映红满天。', poem_notes = '酬乐天：作诗酬答白居易。\n顾：念，指考虑。\n怜：怜惜，爱惜。\n带：腰带。\n频减：多次缩紧。\n冠：帽子。\n废书：丢下书本，指不看书。\n灸（jiǔ）：艾灸，在穴位燃艾灼之。中医的一种治疗方法。\n随年：适应身老体衰的需要，这里指延长寿命。\n谙（ān）：熟悉。\n阅人如阅川：意谓阅历人生如同积水成川一样。语出陆机《叹逝赋》：“阅水以成川，水滔滔而日度；世阅人而为世，人冉冉而行暮。”阅，经历。\n幸：幸运，引申为优点。\n下此：指改变对衰老的忧虑心情。下，攻下，等于说“解决”、“领悟”。此，指“顾老”，对衰老的忧虑和担心。\n翛（xiāo）然：自由自在，心情畅快的样子。\n桑榆：指桑、榆二星。太阳下到桑榆二星之间，天色便晚了，喻人至晚年。曹植《赠白马王彪》：“年在桑榆间，影响不能追。”\n霞：霞光，这里指晚霞。', poem_appreciation = '诗的前六句承接白居易的原唱，表示对白居易的关于“老”的看法颇有同感。一二句写“顾老”是人之常情，人们谁都顾虑衰老，老了就没有人怜惜。接着四句进一步交代了“顾老”的原因，诗人用形象的语言作了描绘：因为衰老，身体一天天消瘦，腰带要不断地紧缩，头发渐渐稀疏，帽子就自然要偏斜。书卷废置不看，是为了保护眼睛；经常用艾灸，是为了延年益寿。\n\n　　“经事还谙事……下此便翛然”四句从另一个方面谈了对“老”的看法，是针对白居易的“伤老”而言。刘禹锡认为，老固然有老的短处，但是老也有老的长处。老的短处是体衰多病，“身瘦带频减，发稀帽自偏。”老的长处是阅历丰富，“经历还谙事，阅人如阅川。”年岁大了，经历的事多了，了解的事理也多，看见过的人多了，阅历也就更加深广。仔细想起来，这也是一件幸事。所以诗人吟道：“下此便翛然。”诗人劝慰他的朋友对待衰老不要过多的忧虑，只要正确对待，便可翛然自乐。\n\n　　最后两句是全诗点睛之笔，意境优美。气势豪放，大有曹操“老骥伏枥，志在千里。烈士暮年，壮心不已”之概。诗人面对衰老，不消极，不悲观，要用有生之年撒出满天的红霞。这两句诗既是诗人的内心世界的自我剖白，又是对老朋友白居易的宽慰和鼓励。\n\n　　这首诗前后两段一反一正，转折自然，很有辩证的观点和说服力量。最后两句尤为精辟，实为警策之语，后人多以此自勉自励。', poem_tags = '励志' WHERE poem_title = '酬乐天咏老见示' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '一场大雨过后池塘里涨满了水，非常平静，好像蘸水轻轻磨光的镜子照映着岸边房屋的倒影。\n东风忽然吹起，下垂的柳条袅娜起舞，柳枝上的水珠撇向荷叶中间，不断发出声响。', poem_notes = '池上：池塘。\n一雨池塘：一处雨后池塘。\n淡磨：恬静安适。淡，安静。\n明镜：如同明镜。\n檐楹：这里指房屋。檐，房檐。楹，房屋前面的柱子。\n舞：飘动。\n更作：化作。\n荷心：荷花。', poem_appreciation = '诗的第一句，是借时间来写景的。“一雨”二字，是统率全诗的关键。因为以下三句所写的自然景象。都因这“一雨”才得以出现的。\n\n　　第二句，是借空间写景。这一句所描绘的内容是对第一句中“水面平”的延展和补充。因为“平”只能状其形而不能显其色。所以续以“淡磨”、“明镜”，就把池面清亮之色渲染出来了。至于“照”，则是在静中求动的点睛之墨，它使池上的安详平静中暗含了动意，其作用不只是为了使写法上有所变化，更是为了让人对下两句所写的风起荷响的动景有精神上的准备。另外，从意境的创造上来说，它还有这样的作用：随着“照”字而出现的池面上的“檐楹”的倒影，无疑扩大了“雨后池上”的空间范围，因为“檐楹”自然是在池面之外的。当然，这里对池岸上的檐楹的描写是虚写。可是，这一笔虚写却为下面的池面之外的另一景物——垂杨的实写作了铺垫，使它的出现不显突兀，且使“雨后池上”这一标题所规定的空间范围，不仅限于池面之上，而是包括池岸之上了。\n\n　　以上二句，是对雨后的池上静景的描绘，用语质朴自然，结构绵密。\n\n　　三四两句，描绘的是一时平静之后的动景。“更作荷心万点声”一句，是全诗的精华，它使全诗的意境升华到了令人意想不到的高度。风吹树摇、积雨落入荷心，其实这正是不久前的“一雨”的余响。诗人正是由于动情于这一阵余响，才提笔写下这首诗的。那末，这阵余响之所令人动情的原因到底在哪里呢。不管诗人是有意还是无意，由于他从现实自然的景观出发，客观上却反映了自然界自身的运动规律：静总是暂时的、相对的，不静则是永恒的。如果从美学的角度看，人们在这首诗中所获得的美感享受，最大的既不是诗人对雨后池上的自然物色彩的描写，也不是在于诗对自然物的形态（包括静态的和动态的）描写，而是在于诗对自然景物由动到静，由静到动，这二者相互转换的关系上，人们看到了自然界自身律动的美。或者说，它表现的不是静止的绘画的美，而是流动的音乐的美。正是这种美，使人们感到自然界的亲切，又正是这种亲切感，使物境和人们的心境和谐起来，交融起来。这就是这首诗的艺术特色。', poem_tags = '古诗三百首,春天,池塘' WHERE poem_title = '雨后池上' AND poem_author = '刘攽';
UPDATE edu_poem SET poem_translation = '平生为人喜欢细细琢磨苦苦寻觅好的诗句，诗句的语言达不到惊人的地步，我就决不罢休。\n人已越来越老，写诗全都是随随便便敷衍而成，对着春天的花鸟，没有了过去的深深忧愁。\n江边新装了一副木栏，可供我悠然地垂钓，我又备了一只小木筏，可代替出入江河的小舟。\n希望有陶渊明、谢灵运这样的诗坛高手相伴，肯定会在这时一起做诗畅谈，一起浮槎漫游。', poem_notes = '值，正逢。水如海势，江水如同海水的气势。值奇景，无佳句，故曰聊短述。聊，姑且之意。\n此二句杜甫自道其创作经验。可见杜甫作诗的苦心。性僻，性情有所偏，古怪，这是自谦的话。不管是什么内容，诗总得有好的句子。耽（dān），爱好，沉迷。惊人，打动读者。死不休，死也不罢手。极言求工。\n此句是说如今年老，已不像过去那样刻苦琢磨。浑，完全，简直。漫与，随意付与。这话不能死看，杜老年作诗也并不轻率，不过由于功夫深了，他自己觉得有点近于随意罢了。）\n此句承上而来。莫，没有。愁，属花鸟说。诗人形容刻划，就是花鸟也要愁怕，是调笑花鸟之辞。\n新添，初做成的。水槛，水边木栏。故，因为。跟“新”字作对，是借对法。故着（zhuó），又设置了。槎（chá），木筏。\n焉得，怎么找到。陶谢，陶渊明、谢灵运，皆工于描写景物，故想到他们。思，即“飘然思不群”、“思飘云物外”的思。令渠（qú），让他们。“令渠”句，是说让他们来作诗，而自己则只是陪同游览。述作，作诗述怀。语谦而有趣。', poem_appreciation = '诗题中一个“如”字，突现了江水的海势 ，提高了江景的壮美层次，表现了江水的宽度、厚度和动态。江水如海势，已属奇观。然而诗题却偏偏曰 ：“聊短述 ”。诗题中就抑扬有致，这是诗人的一贯风格。\n\n　　既然是聊为短述，绝不能出语平平。诗人自谓“为人性僻耽佳句，语不惊人死不休”，足见“聊短述”的良苦用心，炉火纯青的诗艺，严肃认真的写作态度和动人心弦的审美效果。\n\n　　正由于杜甫艺术上的一丝不苟、勇于创新，因此老年臻于出神入化、妙手成春的极境。所谓“老去诗篇浑漫与，春来花鸟莫深愁”。仇兆鳌评杜甫“ 少年刻意求工，老则诗境渐熟，但随意付与，不须对花鸟而苦吟愁思矣 。”（《杜诗详注》卷之十）同时他还转引钱笺可相互发明：“春来花明鸟语，酌景成诗，莫须苦索，愁句不工也。若指花鸟莫须愁，岂知花鸟得佳咏，则光彩生色，正须深喜，何反深愁耶？”（《杜诗详注》卷之十）这里是说点明春光明媚，花香鸟语，快乐异常，因此不存在花鸟深愁的问题，“莫深愁”为杜甫自况。至于“ 浑漫与”中的“与”字，旧本曾作“兴”，清末郭曾忻解释说：“所谓漫兴，只是逐景随情，不更起炉作灶，正是真诗。”（《读杜札记》）此处强调任笔所之，自然而然。总之，首颔二联总体着眼，大处落墨，虽为短述，语实惊人，虽未直接描写江上海势，但胸中之海早已形成。它浑厚深涵，辽阔无垠，大气磅礴。心中之海，诗人采取了虚写的办法。正如金圣叹所说，此“不必于江上有涉，而实从江上悟出也。”（《杜诗解》卷二）所谓海势，其实是江，因此江上之景，亦应摄取，若完全避开江水，则海势亦无所依附，而不成其为江如海势。为此，诗人紧接首颔二联虚写海势以后，随即转入实写江水。故颈联道 ：“新添水槛供重钓，故著（着）浮槎替入舟。”此处虽写江水，但只是轻轻带过，如此触及江水、悟及海势的写法，令人玩味不尽。正如王嗣奭所说 ：“水势不易描写 ，故止咏水槛浮舟。此避实击虚之法。”（《杜臆》卷之四）又如金圣叹所说 ：“不必于江上无涉，而实非着意江上也。”（《杜诗解》卷二）尾联诗人以一“焉”字，即巧作转折，融注新意。诗人之语，已经惊人。诗人说：若得陶渊明、谢灵运那样的妙手，使其述作，并同游于江海之上，岂不快哉！尾联思路新奇，饶有兴味，且与首联相呼应，显示出诗人对艺术最高境界的执着追求。“更为惊人之语也。”（《杜诗解》卷二）对诗与诗题之间的关系金圣叹先生写道：“每叹先生作诗，妙于制题。此题有此诗，则奇而尤奇者也。诗八句中，从不欲一字顾题，乃一口读去，若非此题必不能弁此诗者。题是‘江上值水如海势’七字而止，下又缀以‘聊短述’三字。读诗者，不看他所缀之三字，而谓全篇八句，乃是述江水也，值江水之势如海也。则八句现在曾有一字及江海乎？”（《杜诗解》卷二）从他评析中，可以得知：此诗诗题与诗中八句，构成了一个浑厚海涵、博大精深的整体。虽未写海，而如海势。此诗以虚带实，出奇制胜，意在言外，令人叹为观止。', poem_tags = '写水,抒怀' WHERE poem_title = '江上值水如海势聊短述' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '译文 通往禹庙、兰亭的路，从古到今只有一条。一夜寒霜，使湖边的树林像染过一样。请您不要说酒杯太深，这一次分别，又不知在何方才能相逢。 时光飞逝，美好年华难以留住，镜里的年轻容颜，很快就老去了。只有一句话要记住：“只有闲人才能当神仙。”', poem_tags = '离别,感叹,时光' WHERE poem_title = '蝶恋花·禹庙兰亭今古路' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '孤云陪伴着野鹤，怎么能在人间居住。不要买下沃洲山，现在已经有人知道那儿了。\n\n韵译\n你是行僧象孤云和野鹤，怎能在人世间栖居住宿？\n要归隐请别买沃洲名山，那里是世人早知的去处。', poem_notes = '上人：对 僧人的敬称。\n孤云、野鹤：都用来比喻方外上人。将：与共。\n沃洲山：在浙江新昌县东，上有支遁岭，放鹤峰、养马坡，相传为晋代名僧支遁放鹤、养马之地。时人：指时俗之人。\n将：伴随。', poem_tags = '唐诗三百首,送别' WHERE poem_title = '送方外上人 / 送上人' AND poem_author = '刘长卿';
UPDATE edu_poem SET poem_translation = '村庄处处披满夕阳余辉，牛羊沿着深巷纷纷回归。\n老叟惦念着放牧的孙儿，柱杖等候在自家的柴扉。\n雉鸡鸣叫麦儿即将抽穗，蚕儿成眠桑叶已经薄稀。\n农夫们荷锄回到了村里，相见欢声笑语恋恋依依。\n如此安逸怎不叫我羡慕？我不禁怅然地吟起《式微》。', poem_notes = '渭川：一作“渭水”。渭水源于甘肃鸟鼠山，经陕西，流入黄河。田家：农家。\n墟落：村庄。斜阳：一作“斜光”。\n穷巷：深巷。\n野老：村野老人。牧童：一作“僮仆”。\n倚杖：靠着拐杖。荆扉：柴门。\n雉雊（zhìgòu）：野鸡鸣叫。《诗经·小雅·小弁》：“雉之朝雊，尚求其雌。”\n蚕眠：蚕蜕皮时，不食不动，像睡眠一样。\n荷（hè）：肩负的意思。至：一作“立”。\n即此：指上面所说的情景。\n式微：《诗经》篇名，其中有“式微，式微，胡不归”之句，表归隐之意。', poem_appreciation = '诗人描绘了一幅恬然自乐的田家暮归图，虽都是平常事物，却表现出诗人高超的写景技巧。全诗以朴素的白描手法，写出了人与物皆有所归的景象，映衬出诗人的心情，抒发了诗人渴望有所归，羡慕平静悠闲的田园生活的心情，流露出诗人在官场的孤苦、郁闷。\n\n　　夕阳西下、夜幕将临之际，夕阳的余辉映照着村落（墟落），归牧的牛羊涌进村巷中。老人惦念着去放牧的孙儿，拄着拐杖在柴门外望他归来。在野鸡声声鸣叫中，小麦已经秀穗，吃足桑叶的蚕儿开始休眠。丰年在望，荷锄归来的农民彼此见面，娓娓动情地聊起家常。这美好的情景使诗人联想到官场明争暗斗的可厌，觉得隐居在这样的农村该是多么安静舒心；惆怅之余不禁吟起《诗经》中“式微，式微，胡不归？”（意即：天黑啦，天黑啦，为什么还不回家呀？）的诗句，表明他归隐田园的志趣。王维精通音乐、绘画、书法，艺术修养深厚；苏东坡评他诗中有画，画中有诗。上面这首诗就可以说是一幅田园画。\n\n　　诗的核心是一个“归”字。诗人一开头，首先描写夕阳斜照村落的景象，渲染暮色苍茫的浓烈气氛，作为总背景，统摄全篇。接着，诗人一笔就落到“归”字上，描绘了牛羊徐徐归村的情景，使人很自然地联想起《诗经》里的几句诗：“鸡栖于埘，日之夕矣，羊牛下来。君子于役，如之何勿思？”诗人痴情地目送牛羊归村，直至没入深巷。就在这时，诗人看到了更为动人的情景：柴门外，一位慈祥的老人拄着拐杖，正迎候着放牧归来的小孩。这种朴素的散发着泥土芬芳的深情，感染了诗人，似乎也分享到了牧童归家的乐趣。顿时间，他感到这田野上的一切生命，在这黄昏时节，似乎都在思归。麦地里的野鸡叫得多动情啊，那是在呼唤自己的配偶呢；桑林里的桑叶已所剩无几，蚕儿开始吐丝作茧，营就自己的安乐窝，找到自己的归宿了。田野上，农夫们三三两两，扛着锄头下地归来，在田间小道上偶然相遇，亲切絮语，简直有点乐而忘归呢。诗人目睹这一切，联想到自己的处境和身世，十分感慨。自公元737年（开元二十五年）宰相张九龄被排挤出朝廷之后，王维深感政治上失去依傍，进退两难。在这种心绪下他来到原野，看到人皆有所归，唯独自己尚旁徨中路，不能不既羡慕又惆怅。所以诗人感慨系之地说：“即此羡闲逸，怅然吟式微。”其实，农夫们并不闲逸。但诗人觉得和自己担惊受怕的官场生活相比，农夫们安然得多，自在得多，故有闲逸之感。《式微》是《诗经·邶风》中的一篇，诗中反复咏叹：“式微，式微，胡不归？”诗人借以抒发自己急欲归隐田园的心情，不仅在意境上与首句“斜阳照墟落”相照映，而且在内容上也落在“归”字上，使写景与抒情契合无间，浑然一体，画龙点睛式地揭示了主题。读完这最后一句，才恍然大悟：前面写了那么多的“归”，实际上都是反衬，以人皆有所归，反衬自己独无所归；以人皆归得及时、亲切、惬意，反衬自己归隐太迟以及自己混迹官场的孤单、苦闷。这最后一句是全诗的重心和灵魂。如果以为诗人的本意就在于完成那幅田家晚归图，这就失之于肤浅了。全诗不事雕绘，纯用白描，自然清新，诗意盎然。', poem_tags = '唐诗三百首,田园,归隐' WHERE poem_title = '渭川田家' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '那高高的画船，系在春水边，一动不动。它在等谁？哦，是外出的游子，喝着别离的酒，情意正浓。\n游子惜别，画船可不管；无论是烟波浩荡，无论是风吹雨打，它总是带着满船离愁别恨，驶向江南。', poem_notes = '亭亭：高高耸立的样子。\n画舸（gě）：即画船。\n半酣：半醉。', poem_appreciation = '该诗首句是说一只漂亮的画船系在岸边的柳树上，表现的是一个“等”字。“亭亭”多用来形容姑娘之苗条、靓丽，作者却用来描写船，可见作者的构思不同一般。“系”的后面省略了宾语，与刘禹锡的“只有垂杨绾别离”手法相同，且暗切题意，手法不同凡响。“春潭”化用李白的“桃花潭水深千尺”，用笔老到，布局精巧。该句中没有正面写柳，但“系”字和诗题相照应，已暗示了所系之处。古代有折柳赠别的风俗，因为“柳”谐“留”音，寓有惜别之意，因此，首联所展示的系舟杨柳岸的画面，恰是一幅春江送别图。\n\n　　次句以“直待”接续，回答了等的对象：行人，也就是将要离开家乡的人。在船将发未发之际，送行者和行人依依话别，做最后一刻的流连。珍重彼此的友谊，珍重这别离的时刻，送行的人殷勤劝酒，“直到行人酒半酣”，这里含有“劝君更尽一杯酒，西出阳关无故人”的意思。同时也表明，行人所以喝得半醉，一来是朋友情重，二来是为了排遣离忧。作者在上一句“亭亭画舸”停在水中这一特写背景下，创立了似乎是游春的场面，而下句转入离别，出现心理的反差，离别的黯然销魂的意况隐现在句中。这两句语言很含蓄，意思却很明白。这里不说人有情而怨别，却怪画船无情，无理而妙。\n\n　　三四句作者直写离别。第三句在首句“点染的画船上做文章，说不管烟波浩渺，不管风风雨雨，行人终将离去，画船带走的只是离愁别恨。包含了送行者相留不住的怨情，也表现了行人欲留不能，不得不走的无奈，像是友人对行者的埋怨，又像是行者的自怨自艾，写得情意盎然。\n\n　　末句将抽象的离恨，化为有形体、有重量的东西，使人分外感到离恨的深刻沉重，意象非常新奇。作者不写船带走行人，也不写行人的离恨，而是说船带走的是离恨，多了一层转折，加深了意境。同时把离愁悲恨这一抽象的情态想象成实在的物质，可以放在船上运走，就更为奇妙。此诗在新巧上做文章。作者把离愁别恨变成有分量的东西，可用船来载，在“愁”的分量上做文章，更加深切地表现了心中的凄苦，为人所称道。这一手法为后代诗人借鉴。好的比喻，好的意境，是不怕重复的。\n\n　　该诗全篇构思精巧，把无形的别情写得具体、有形。作者用到如下几种手法：一是第四句中的“载”字，把抽象的别情化为有形的、可以被运载的东西，同时也显示出别情的沉重。这一形象化的说法，后来常被诗人所仿效；二是移情于物。似乎是无情的画舸，在经过一段沉默难耐的等待之后，只等行人上了船，便毫不迟疑地把人载向江南。人情无奈，迁怨于物，如此言情，深婉蕴藉。三是七绝诗通常分为两节，前两句与后两句间有一个转折，而此诗一气而下，使我们直觉得相别之干脆、舟行之飞速，不容人有丝毫的缠绵悱恻，有力地烘托出浓重的怨别之意。', poem_tags = '古诗三百首,柳树,送别,友情' WHERE poem_title = '柳枝词' AND poem_author = '郑文宝';
UPDATE edu_poem SET poem_translation = '挽了一个松松的云髻，化上了淡淡的妆容。青烟翠雾般的罗衣，笼罩着她轻盈的身体。她的舞姿就像飞絮和游丝一样，飘忽不定。\n此番一见不如不见，多情不如无情。笙歌散后，醉酒初醒，庭院深深，斜月高挂，四处无声。', poem_notes = '西江月：词牌名。\n宝髻：妇女头上带有珍贵饰品的发髻。\n铅华：铅粉、脂粉。\n“青烟翠雾”二句：形容珠翠冠的盛饰，皆为妇女的头饰。轻盈：形容女子的仪态美。\n争如：怎如、倒不如。', poem_appreciation = '司马光不以词作著名。然而，北宋词风甚盛之时，一些名臣如韩缜、韩琦、范仲淹都能事业之余写出很好的词，司马光也不例外。他的词作不多，遗留下来的只有三首，多系风情之作。其词不加虚饰，直抒胸臆，继承了“国风好色”、“《小雅》怨悱”的优良传统。此词中的“相见争如不见，多情何似无情”，即是写情的佳句。这说明，司马光并非假道学，而能表达真率的感情。\n\n　　上片写宴会所遇舞妓的美姿，下片写对她的恋情，开头两句，写出这个姑娘不同寻常：她并不浓妆艳抹，刻意修饰，只是松松地换成了一个云髻，薄薄地搽了点铅粉。次两句写出她的舞姿：青烟翠雾般的罗衣，笼罩着她的轻盈的体态，象柳絮游丝那样和柔纤丽而飘忽无定。下阕的头两句陡然转到对这个姑娘的情上来：“相见争如不见，有情何似无情”，上句谓见后反惹相思，不如当时不见；下句谓人还是无情的好，无情即不会为情而痛苦。以理语反衬出这位姑娘色艺之可爱，惹人情思。最后两句写席散酒醒之后的追思与怅惘。\n\n　　这首小令只幅之内把惊艳、钟情到追念的全过程都反映出来，而又能含蓄不尽，给人们留下想象的余地，写法别致。它不从正面描写那个姑娘长得多么美，只是从发髻上、脸粉上，略加点染就勾勒出一个淡雅绝俗的美人形象；然后又体态上、舞姿上加以渲染：“飞絮游丝无定”，连用两个比喻把她的轻歌曼舞的神态表现出来。而这首词写得最精彩的还是歇拍两句。当他即席动情之后，从醉中醒了过来，又月斜人静的时候，种种复杂的感受都尽括“深院月斜人静”这一景语中，达到了“不着一字，尽得风流”的境界。\n\n　　从结构上说，词的上片写其人其境，营造出惝恍飘忽，扑朔迷离的意境，下片写自己的感受，性灵流露，雅而不俗，余味深长。全词造句自然，意不晦涩，语不雕琢，随手写来，妥贴停匀，足见司马光作词虽为余技，却也显示出学识之厚与感情之富。', poem_tags = '婉约,宴会,思念,女子' WHERE poem_title = '西江月·宝髻松松挽就' AND poem_author = '司马光';
UPDATE edu_poem SET poem_translation = '天空中银河不断转动、星移斗转，人世间的帘幕却一动不动的低低下垂。枕席变凉，泪水更多的流淌，一片湿滋滋。和衣而睡，醒来脱去绸缎外衣，随即问道：“夜已到何时？”\n这件穿了多年的罗衣，用青绿色的丝线绣成的莲蓬已经变小；用金线绣制的荷叶颜色减退、变得单薄而稀疏。每逢秋凉，还总是还上这件罗衣。唯独人的心情不像从前舒畅适时。', poem_notes = '南歌子：又名《断肠声》等。一说张衡《南都赋》的“坐南歌兮起郑舞”，当系此调名之来源。而李清照此词之立意，则与又名《肠断声》相合。\n星河：银河，到秋天转向东南。\n枕簟（diàn）：枕头和竹席。滋：增益，加多。\n夜何其：《诗经·小雅·庭燎》“夜如何其？夜未央。夜已经到了什么时候了？”“其”，语助词。\n翠贴、金销：即贴翠、销金，均为服饰工艺。\n情怀：心情。旧家：从前。《诗词曲语辞汇释》卷六：“旧家犹言从前，家为估量之辞。”其所引例中即有此句。', poem_tags = '宋词三百首,宋词精选,抒情' WHERE poem_title = '南歌子·天上星河转' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '绿树绕着村庄，春水溢满池塘，淋浴着东风，带着豪兴我信步而行。小园很小，却收尽春光。桃花正红，李花雪白，菜花金黄。\n远远一带围墙，隐约有几间茅草屋。青色的旗帜在风中飞扬，小桥矗立在溪水旁。偶然乘着游兴，走过东面的山冈。莺儿鸣啼，燕儿飞舞，蝶儿匆忙，一派大好春光。', poem_notes = '陂（bēi）塘：池塘。\n徜（cháng）徉（yáng）：自由自在来回地走动。\n飚（yáng）：飞扬，飘扬。青旗：青色的酒幌子。', poem_tags = '宋词三百首,春天,乡村' WHERE poem_title = '行香子·树绕村庄' AND poem_author = '秦观';
UPDATE edu_poem SET poem_translation = '我有着深深思念的人，却相隔在远远的异乡。\n我有所感怀的事情，深深的刻在心上。\n故乡遥远回不去，我没有一天不遥望它。\n内心痛苦万分却无处化解，日日夜夜未曾停止思念。\n我的前途似乎也迷茫无望，孤独的在空空的屋子里睡觉。\n秋天尚未来临，却已风雨纷纷。\n不曾学过苦行僧的佛法，如何忘记曾经的过往！', poem_notes = '乡：家乡。\n瞻望：往远处或高处看，敬仰并寄以希望。\n夕：日落的时候：夕阳。夕照。朝夕相处。无夕：日日夜夜。\n残灯：不好的事。夜：黑夜，代指前途的黑暗。\n空堂：空屋。\n晓：到来，来临。\n正：此时。苍苍：纷纷。\n头陀：苦行僧。\n安：怎么。', poem_appreciation = '首句开门见山，写出了所要记叙的事情，强烈的感情色彩也在无需意像的渲染的情况下，立刻展现在读者面前。四句话形式上两两相同，但情感上却是层层深入的，第一句提到了人的思念和远，都是平平的概述，点到为止，并没有提及是一个什么样的人，如何的思念她。第二句则重点写到了思念，写到思念的程度，也并没有深写。行文至此，全诗的中心已经点明框架，已经明晰，但还只是一幅，如果用画画作比的话，构图，或者说是工笔前的白描图，线条简洁而有力。第三句对第一句进行了扩充和延伸，乡远远的程度，对故乡，更准确的说是对故乡的生活，故乡的人的思念之深。第四句是对第二句进行了扩充和延伸。一、三句是写实，故乡、人都是客观存在的。二、四句是写虚，回忆中的事和肝肠绞痛的感觉是诗人主观的感情。一实，一虚，把气氛渲染开来，行文至此，白描已经被染，出现了淡淡的色彩，阴阳、冷暖色初步分明。诗人付与“人”一个“隔”，付与“事”一个“结”字。“隔”、“结”都是冰凉凉的字眼，给人一种一对火热的恋人被活生生分扯开来的感觉。诗人用两个冰冷的字形象地写出了自己火热的情感，而火热又败于冰冷，这时引出自己肝肠绞痛的感觉显得自然，又打动了读者。在这里，诗人又用了一个打动人的动词“瞻望”。乡远，瞻望却不可相望见，可是还要望，纵是眼望不见那心也早已回到了那故乡的恋人身畔。\n\n　　前四句是对一个长时间一直以来状态的写，从“况此”一句开始，诗人就开始描绘一个夜雨的场景了。作者在描写夜雨场景的时候，却是惜字如金。他只用了两句话二十个字。这两句话不写思，不写念，不写人，不写事，只是用简洁的言语描绘了许多意像，灯、堂、天、风雨。一个况字说明这四句所描写的这些是在前四句的前提上进一步增加的。所以，在情感上也是在前四句的思念上增加的。一个“况”字就替代了千言万语的心理描写。“夜”是时间，在“夜”之前诗人用了一个名词作形容词来形容“夜”，“残灯”。灯从晚上点，点到残，一定已是深夜。诗人夜不能寐，久久的思念着心中的恋人。残灯昏暗的光下，长长的灯芯使光闪烁着，诗人在这情景万分伤心，没有言自然显得寂静，寂静使屋子显得“空”，显得寂寥。“空”不一定是真的缺少家具，而是因为缺少“人”。夜雨同话五更的人“空堂”不一定是堂“空”也写出诗人心中的怅然若失。“秋天”“未晓”“风雨”更是融情于景。“苍苍”二字既是对风雨的描写，又是诗人此时的心境。这两句，不着一字思念，而又字字句句把诗人的思念之情着色，分染过的白描已经基本上上好了颜色。最后一句话，可谓画龙点睛之笔，使用直抒胸意的写法，将全诗推向高潮。想忘，又不能忘，想忘，又不敢忘。诗人一段刻骨铭心的爱情就在这无果的结局中谢幕，无数的思念，向何处倾诉。\n\n　　整首诗贯穿着白居易的大、简、妙风格，虽是写爱情，写思念，但不像多数爱情诗一样婉约，它大气、又不失细腻，这不是刻意为之，而是一种情感之至，一种浑然天成。这首诗不是唐代所流行的工整的今体诗，它共有七句话，前四句大量的重复用字，也并不合乎诗歌的习惯。意像的描写被放在了叙事之后，全诗没有比喻、没有用典，也没有大量的兴、比之作，可以说是完全没有格律的羁绊，用最直白的语言，抒发了最真挚的情感。', poem_tags = '思念,爱情' WHERE poem_title = '夜雨' AND poem_author = '白居易';
UPDATE edu_poem SET poem_tags = '写景,抒怀,思乡,壮志未酬' WHERE poem_title = '游子吟' AND poem_author = '顾况';
UPDATE edu_poem SET poem_translation = '菟丝把低矮的蓬草和大麻缠绕，它的蔓儿怎么能爬得远！\n把女儿嫁给就要从军的人哪，倒不如早先就丢在大路旁边！\n我和你做了结发夫妻，连床席一次也没能睡暖；\n昨天晚上草草成亲，今天早晨便匆匆告别，这婚期岂不是太短，太短！\n你到河阳去作战，离家虽然不远，可已经是边防前线；\n我们还没有举行拜祭祖先的大礼呀，叫人怎么好去把公婆拜见？\n我做女儿的时光，不论黑夜还是白天，爹妈从不让我抛头露面；\n有道是“嫁鸡随鸡，嫁狗随狗”，如今我嫁到你家，爹妈盼的是平平安安！\n你今天就要上战场，我只得把痛苦埋藏在心间；\n多想跟你一块儿去呀，只怕是形势紧急，军情多变。\n你不用为新婚离别难过啊，要在战争中为国家多多出力；\n我不能随你去，妇女跟着军队，恐怕会影响士气。\n唉！我本是穷人家女儿，好不容易才制办了这套丝绸的嫁衣；\n可从现在起我就把它脱掉，再当面洗掉脂粉，一心一意等着你！\n你看，天上的鸟儿都自由自在地飞翔，不论大的小的，全是成对成双；\n可人世间不如意的事儿本来就多啊，但愿你和我两地同心，永不相忘！', poem_notes = '菟丝：即菟丝子，一种蔓生的草，依附在其他植物枝干上生长。比喻女子嫁给征夫，相处难久。\n结发：这里作结婚解。君妻：一作“妻子”。\n无乃：岂不是。\n河阳：今河南孟县，当时唐军与叛军在此对峙。\n身：身份，指在新家中的名份地位。唐代习俗，嫁后三日，始上坟告庙，才算成婚。仅宿一夜，婚礼尚未完成，故身份不明。\n姑嫜：婆婆、公公。\n藏：躲藏，不随便见外人。\n归：古代女子出嫁称“归”。\n将：带领，相随。这两句即俗语所说的“嫁鸡随鸡，嫁狗随狗”。\n往死地：指“守边赴河阳”。死地：冒死之地。\n迫：煎熬、压抑。中肠：内心。\n苍黄：同“仓皇”，匆促、慌张。这里意思是多所不便，更麻烦。\n事戎行：从军打仗。戎行：军队。\n“妇人”两句：意谓妇女随军，会影响士气。扬：高昂。\n久致：许久才制成。襦：短衣。裳：下衣。\n不复施：不再穿。\n洗红妆：洗去脂粉，不再打扮。\n双翔：成双成对地一起飞翔。此句写出了女子的寂寞和对那些能够成双成对的鸟儿的羡慕。\n错迕：错杂交迕，就是不如意的意思。\n永相望：永远盼望重聚。表示对丈夫的爱情始终不渝。', poem_appreciation = '杜甫“三别”中的《新婚别》，精心塑造了一个深明大义的少妇形象。这首诗采用独白的形式，全篇先后用了七个“君”字，都是新娘对新郎倾吐的肺腑之言，读来深切感人。\n\n　　全诗大致可分为三段，也可以说是三层，但是这三层并不是平列的，而是一层比一层深，一层比一层高，而且每一层当中又都有曲折。这是因为诗中人物的心情本来就是很复杂的。\n\n　　第一段，从“兔丝附蓬麻”到“何以拜姑嫜”，主要是写新娘子诉说自己的不幸命运。她是刚过门的新嫁娘，过去和丈夫没见过面，没讲过话。所以语气显得有些羞涩，有些吞吞吐吐。这表现在开头两句：“兔丝附蓬麻，引蔓故不长。”新嫁娘这番话不是单刀直入，而是用比喻来引起的。这很符合她的特定身份和她这时的心理状态。兔丝，即“菟丝”，是一种蔓生的草，常寄生在别的植物身上。“蓬”和“麻”也都是小植物，所以，寄生在蓬麻上的菟丝，它的蔓儿也就不能延长。在封建社会里，女子得依靠丈夫才能生活，可是现在她嫁的是一个“征夫”，很难指望白头偕老，用“菟丝附蓬麻”的比喻非常贴切。“嫁女与征夫，不如弃路旁”，这是一种加重的说法，这位新娘子之所以会伤心到这步田地，“结发为君妻”以下的八句，正是申明了这个问题的原因。“结发”二字，说明这个新娘子对丈夫的好歹看得很重，因为这关系到她今后一生的命运。然而，这洞房花烛之夜，却就是生离死别之时，头一天晚上刚结婚，第二天一早就得走，连床席都没有睡暖，这根本不像是结发夫妻过的生活。“无乃太匆忙”的“无乃”，是反问对方的口气，意即“岂不是”。如果是为了别的什么事，匆忙相别，也还罢了，因为将来还可以团圆，偏偏丈夫又是到河阳去作战，将来的事且不说，眼面前，媳妇的身份都没有明确，妻子也就无法去拜见公婆、侍候公婆。古代婚礼，新嫁娘过门三天以后，要先告家庙、上祖坟，然后拜见公婆，正名定分，才算成婚。“君行虽不远，守边赴河阳”两句，点明了造成新婚别的根由是战争；同时说明了当时进行的战争是一次“守边”战争。从诗的结构上看，这两句为下文“君今往死地”和“努力事戎行”张本。当时正值安史之乱，广大地区沦陷，边防不得不往内地一再迁移，而此时，边境是在洛阳附近的河阳，守边居然守到唐王朝自己家门口来了，这不能不让诗人感到十分可叹。所以，这两句也是对统治阶级昏庸误国的讥讽，诗人在这里用的是一种“婉而多讽”的写法。\n\n　　第二段，从“父母养我时”到“形势反苍黄”。新娘子把话题由自身进一步落到丈夫身上了。她关心丈夫的死活，并且表示了对丈夫的忠贞，要和他一同去作战。“父母养我时，日夜令我藏”，当年父母对她非常疼爱，把她当作宝贝似的。然而女大当嫁，父母也不能藏她一辈子，还是不能不把她嫁人，而且嫁谁就得跟谁。“鸡狗亦得将”，“将”字当“跟随”讲，就是俗话说的“嫁鸡随鸡，嫁狗随狗”。可是新婚之时，“君今往死地，沉痛迫中肠。”丈夫要到那九死一生的战场去，万一有个三长两短，她就不能再依靠谁了。想到这些，这让她沉痛得柔肠寸断。紧接着，新娘子表示：“我本来决心要随你前去，死也死在一起，省得牵肠挂肚。但又怕这样一来，不但没有好处，反而要把事情弄得糟糕，更复杂。军队里是不允许有年轻妇女的，你带着妻子去从军，也有许多不方便，我又是一个刚出门的闺女，没见过世面，更不用说是打仗了。真是叫人左右为难。”这段话，刻画了新娘子那种心痛如割、心乱如麻的矛盾心理，非常曲折、深刻。\n\n　　诗的第三段，是从“勿为新婚念”到“与君永相望”。在这里，女主人公经过一番痛苦的倾诉和内心剧烈的斗争以后，终于从个人的不幸中、从对丈夫的关切中，跳了出来，站在更高的角度，把眼光放得更远了。“勿为新婚念，努力事戎行！”她一变哀怨沉痛的诉说而为积极的鼓励，话也说得痛快，不像开始的时候那样吞吞吐吐的了，她决定不随同丈夫前去，并且，为了使丈夫一心一意英勇杀敌，她表示了自己生死不渝的坚贞爱情。这爱情，是通过一些看来好像不重要，其实却大有作用的细节，或者说具体行动表达出来的。这就是“自嗟贫家女”这四句所描写的。新娘说，费了许久的心血好不容易才备办得一套美丽的衣裳，现在不再穿了。并且，当着丈夫的面，她这就把脸上的脂粉洗掉。丈夫走了以后，我更没心情梳妆打扮了。这固然是她对丈夫坚贞专一的爱情的表白，但是更可贵的，是她的目的在于鼓励丈夫，好叫他放心地、并且满怀信心、满怀希望地去杀敌。她对丈夫的鼓励是明智的。因为只有把幸福的理想寄托在丈夫的努力杀敌、凯旋归来上面，才有实现的可能。应该说，她是识大体，明大义的。\n\n　　“仰视百鸟飞，大小必双翔。人事多错迕，与君永相望！”这四句是全诗的总结。其中有哀怨，有伤感，但是已经不像最初那样强烈、显著，主要意思还是在鼓励丈夫，所以才说出“人事多错迕”，好像有点人不如鸟，但立即又振作起来，说出了“与君永相望”这样含情无限的话，用生死不渝的爱情来坚定丈夫的斗志。\n\n　　《新婚别》是一首高度思想性和完美艺术性结合的作品。诗人运用了大胆的浪漫的艺术虚构，实际上杜甫不可能有这样的生活经历，不可能去偷听新娘子对新郎官说的私房话。在新娘子的身上倾注了作者浪漫主义的理想色彩。另一方面，在人物塑造上，《新婚别》又具有现实主义的精雕细琢的特点，诗中主人公形象有血有肉，通过曲折剧烈的痛苦的内心斗争，最后毅然勉励丈夫“努力事戎行”，表现战争环境中人物思想感情的发展变化，丝毫没有给读者勉强和抽象之感，而显得非常自然，符合事件和人物性格发展的逻辑，并且能让读者深受感染。\n\n　　人物语言的个性化，也是《新婚别》的一大艺术特点。诗人化身为新娘子，用新娘子的口吻说话，非常生动、逼真。诗里采用了不少俗语，这也有助于语言的个性化，因为他描写的本来就是一个“贫家女”。\n\n　　此外，在押韵上，《新婚别》和《石壕吏》有所不同。《石壕吏》换了好几个韵脚，《新婚别》却是一韵到底，《垂老别》和《无家别》也是这样。这大概和诗歌用人物独白的方式有关，一韵到底，一气呵成，更有利于主人公的诉说，也更便于读者的倾听。', poem_tags = '叙事,战争,妇女,离别' WHERE poem_title = '新婚别' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '人到晚年特别喜好安静，对人间万事都漠不关心。\n自思没有高策可以报国，只要求归隐家乡的山林。\n宽解衣带对着松风乘凉，山月高照正好弄弦弹琴。\n君若问穷困通达的道理，请听水浦深处渔歌声音。', poem_notes = '酬：以诗词酬答。张少府：当指张九龄，字子寿，一名博物。韶州曲江（今属广东）人。官至中书侍郎同中书门下平章事。后遭李林甫排挤罢相。少府，唐人称县尉为少府。从“君问穷通理”句看，张少府亦是诗人同道之人。\n晚年：年老之时。唯：亦写作“惟”，只。好（hào）：爱好。\n自顾：自念；自视。长策：犹良计。\n空知：徒然知道。旧林：指禽鸟往日栖息之所。这里比喻旧日曾经隐居的园林。\n吹解带：吹着诗人宽解衣带时的闲散心情。解带，表示熟不拘礼，或表示闲适。\n君：一作“若”。穷：不能当官。通：能当官。理：道理。渔歌：隐士的歌。浦深：河岸的深处。', poem_appreciation = '这是一首赠友诗。全诗写情多于写景。三、四句隐含不满朝政之牢骚。\n\n　　诗开头就说“晚年唯好静，万事不关心”，描述了晚年唯好清静、万事皆不关心的心态，看似达观，实则表露出诗人远大抱负无法实现的无奈情绪。说自己人到晚年，惟好清静，对什么事情都漠不关心了，乍一看，生活态度消极之至，但这是表面现象。仔细推求起来，这“唯好静”的“唯”字大有文章。一是确实“只”好静。二是“动”不了才“只得”好静。三是显示出极端消极的生活态度。既不写中年、早年“惟好静”，却写晚年变得“惟好静”，耐人寻味。如细细品味，不难发现此中包含着心灵的隐痛。\n\n　　颔联紧承首联，“自顾无长策”道出诗人理想的破灭和思想上的矛盾、痛苦，在冷硬的现实面前，深感无能为力。既然理想无法实现，就只好另寻出路。入世不成，便只剩下出世一条路了。亦即跳出是非场，放波山水，归隐田园，“空知返旧林”。一个“空”字，包含着几多酸楚与感慨！此两句亦透露了一个中年消息。王维此时虽任京官，但对朝政已经完全失望，开始过着半官半隐的生活，“晚年唯好静，万事不关心”，正是他此时内心的真实写照。\n\n　　王维早年，怀有政治抱负的雄心，在张九龄任相时，他对现实充满希望。然而，没过多久，张九龄罢相贬官，朝政大权落到奸相李林甫手中，忠贞正直之士一个个受到排斥、打击，政治局面日趋黑暗，王维的理想随之破灭。在严酷的现实面前，他既不愿意同流合污，又感到自己无能为力。“自顾无长策”，就是他思想上矛盾、苦闷的反映。他表面上说自己无能，骨子里隐含着牢骚。尽管在李林甫当政时，王维并未受到迫害，实际上还升了官，但他内心的矛盾和苦闷却越来越加深了。对于这个正直而又软弱、再加上长期接受佛教影响的封建知识分子来说，出路就只剩下跳出是非圈子、返回旧时的园林归隐这一途了。“空知返旧林”意谓：理想落空，归隐何益？然而又不得不如此。在他那恬淡好静的外表下，内心深处的隐痛和感慨，还是依稀可辨的。\n\n　　颈联写的是诗人归隐“旧林”后的通送适意。理想落空的悲哀被“松风吹解带，山月照弹琴”的闲适所取代。摆脱了仕宦的种种压力，诗人可以迎着松林清风解带敞怀，在山间明月的伴照下独坐弹琴，自由自在，悠然自得。然而在这恬淡闲适的生活中，依然可以感受到诗人内心深处的隐痛和感慨。诗人肯定、赞赏那种“松风吹解带，山月照弹琴”的隐逸生活和闲适情趣，实际上是他在苦闷之中追求精神解脱的一种表现。这既含有消极因素，又含有与官场生活相对照、隐示厌恶与否定官场生活的意味。\n\n　　“松风”、“山月”均含有高洁之意。王维追求这种隐逸生活和闲适情趣，说他逃避现实也罢，自我麻醉也罢，无论如何，总比同流合污、随波逐流好。诗人在前面四句抒写胸臆之后，抓住隐逸生活的两个典型细节加以描绘，展现了一幅鲜明生动的形象画面，将“松风”、“山月”都写得似通人意，情与景相生，意和境相谐，主客观融为一体，这就大大增强了诗歌的形象性。\n\n　　尾联诗人借答张少府，用《楚辞·渔父》的结意现出诗人企羡渔父悠然独居，不问人间穷通。歌入浦，以不答为咎，合不尽之意于言外。“君问穷通理，渔歌入浦深”，用一问一答的形式，照应了“酬”字；同时，又妙在以不答作答：若要问我穷通之理，我可要唱着渔歌向河浦的深处去了。末句含蓄蕴藉，耐人咀嚼，似乎在说：世事如此，还问什么穷通之理，不如跟我一块归隐去吧！又淡淡地勾出一幅画面，用它来结束全诗，可真有点“韵外之致”、“味外之旨”（司空图《与李生论诗书》）的“神韵”。王维避免对当世发表议论，隐约其词，似乎在说：通则显，穷则隐，豁达者无可无不可，何必以穷通为怀。而联系上文来看，又似乎在说：世事如此，还问什么穷通之理，不如跟我一块归隐去吧！这就带有一些与现实不合作的意味了。\n\n　　从表面上看，诗人显得很达观。可是，这种对万事不关心的态度，正是一种抑郁不满情绪的表现，字里行间流露出不得已的苦闷，说明了诗人仍然未忘朝政，消沉思想是理想幻灭的产物。“自顾无长策，空知返旧林”两句含义是非常深永的。他没有回天之力，又不愿同流合污，只能洁身隐遁。他又故意用轻松的笔调描写隐居之乐，并对友人说“君问穷能理，渔歌入浦深”，大有深意，似乎只有在山林生活中他才领悟了人生的真谛，表现出诗人不愿与统治者合作的态度，语言含蓄有致，发人深思。诗的末句又淡淡地勾出一幅画面，含蓄而富有韵味，耐人咀嚼，发人深思，正是这样一种妙结。', poem_tags = '唐诗三百首,赠别,友情,规劝' WHERE poem_title = '酬张少府' AND poem_author = '王维';
UPDATE edu_poem SET poem_tags = '婉约,闺怨,夏天,写景' WHERE poem_title = '阮郎归·初夏' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '相思过度，以致魂不守舍，恍惚迷离中竟将红色看成绿色。思念后果，身体憔悴，精神恍惚。\n如果你不相信我近来因思念你而流泪。那就开箱看看我石榴裙上的斑斑泪痕吧。', poem_notes = '看朱成碧：朱，红色；碧，青绿色。看朱成碧，把红色看成绿色。\n思纷纷：思绪纷乱。\n憔悴：瘦弱，面色不好看。\n比来：近来\n石榴裙：典故出自梁元帝《乌栖曲》。“芙蓉为带石榴裙”。本意是指红色裙子，转意指女性美妙的风情，因此才有了“拜倒在石榴裙下”一说。', poem_appreciation = '《乐苑》上说：“《如意娘》，商调曲，唐则天皇后所作也。”武则天十四岁入宫为才人，太宗李世民赐号武媚。而后太宗崩，居感业寺为尼。高宗李治在寺中看见她，复召入宫，拜昭仪。武则天在感业寺的四年，是她人生中最失意的四年，但祸兮福之所伏，武则天在感业寺的日子也充满了命运的转机。在感业寺，武则天写下了她最有名的诗歌《如意娘》，史载这首诗是写给唐高宗李治的。或许，正是这首诗，使得李治才忽然想到尚在削发为尼的旧情人武媚。\n\n　　《如意娘》一诗极写相思愁苦之感，短短四句，传达出多层次多方位的复杂情绪。\n\n　　首句“看朱成碧思纷纷”赋比兴兼具，有多重含意。一来明写抒情主人公相思过度，以致魂不守舍，恍惚迷离中竟将红色看成绿色。梁王僧孺诗“谁知心眼乱，看朱忽成碧”（《夜愁示诸宾》）为此句所本。正是心乱眼花使这位痴情女子五色不辨。二来暗指美好春光的流逝，眼见花红褪尽，枝头只剩下绿叶。三来借喻自己只身独处，花红叶绿不能相扶；又喻自己红颜薄命，由昔日欢聚的幸福坠入今日冰冷的相思之苦。\n\n　　“朱”、“碧”两种反差极大的颜色，构成了强烈的感情的冷暖对照。眼前和一片寒冷碧绿触目伤怀，引起思虑万千。“憔悴支离为忆君”一句直抒胸臆。从外表写入内心，尽言思妇的瘦弱不支和心力交瘁。至此，这两行诗辗转写的是凄切，是寂寞，是深深地哀怨。情绪的流向较为单一。\n\n　　接下来，作者笔锋一转，打破一二句的和弦，以全新的节奏和韵律再现诗的主题：“不信比来长下泪，开箱验取石榴裙。”意谓：如果你不相信我近来因思念你而流泪，那就开箱看看我石榴裙上的斑斑泪痕吧！执著、决然、不掩饰、不造作的独特形象跃然纸上，李白的《长相思》写“不信妾断肠，归来看去明镜前”与此句构思相似。这两句是全诗的高潮，它丰富了诗歌的情绪构成。“不信”句诉说着“断肠”的相思，也隐含着相思的无可奈何，相思的难以喻说。\n\n　　《如意娘》写得曲折有致，较好地融合南北朝乐府风格于一体，是武则天的上乘之作，对后世有一定的影响。\n\n　　看朱成碧后来成为唐宋人常用成语。李白诗：“催弦拂柱与君饮，看朱成碧颜始红。”也可以说看碧成朱。辛弃疾词：“倚栏看碧成朱，等闲褪了香袍粉。”《柳亭诗话》载：李白的《长相思》一诗中有“昔日横波目，今成流泪泉。不信妾肠断，归来看取明镜前”之句，据说李白的夫人看了这首诗，对他说：“君不闻武后诗乎？‘不信比来常下泪，开箱验取石榴裙’。”李白听了后“爽然若失”。后来有“刿目鉥心、掐擢胃肾”之称的孟郊又写出了“试妾与君泪，两处滴池水。看取芙蓉花，今年为谁死！”这样语出惊人的句子。但溯其本源，还是承袭了武则天的创意。', poem_tags = '相思,婉约' WHERE poem_title = '如意娘' AND poem_author = '武则天';
UPDATE edu_poem SET poem_translation = '郁郁葱葱棠梨树，不剪不砍细养护，曾是召伯居住处。\n郁郁葱葱棠梨树，不剪不毁细养护，曾是召伯休息处。\n郁郁葱葱棠梨树，不剪不折细养护，曾是召伯停歇处。', poem_notes = '蔽芾（fèi费）：小貌。一说树木高大茂密的样子。甘棠：棠梨，杜梨，落叶乔木，果实圆而小，味涩可食。芾：盛貌；蔽：谓可蔽风日也。\n翦：同“剪”，伐，砍伐。\n召（shào邵）伯：即召公，姬姓，封于燕。茇（bá拔）：草舍，此处用为动词，居住。\n败：伐，毁坏。\n憩：休息。\n拜：拔也，一说屈、折。\n说（shuì税）：通“税”，休憩，止息。', poem_appreciation = '《甘棠》一诗的主旨，自古至今，惟蓝菊荪《诗经国风今译》认为是讽刺召伯之作，其他几乎众口一辞，均认为是怀念召伯的诗作。如《毛诗序》云：“《甘棠》，美召伯也。召伯之教，明于南国。”郑笺云：“召伯听男女之讼，不重烦百姓，止舍小棠之下而听断焉，国人被其德，说其化，思其人，敬其树。”朱熹《诗集传》云：“召伯循行南国，以布文王之政，或舍甘棠之下。其后人思其德，故爱其树而不忍伤也。”\n\n　　这首诗的写作背景在《史记·燕召公世家》中记载得比较明确：“召公之治西方，甚得兆民和。召公巡行乡邑，有棠树，决狱政事其下，自侯伯至庶人，各得其所，无失职者。召公卒，而民人思召公之政，怀棠树，不敢伐，歌咏之，作《甘棠》之诗。”许多民间传说和地方志中的资料也都足以证明召公听讼甘棠树下的故事流播广远。召伯南巡，所到之处不占用民房，只在甘棠树下停车驻马、昕讼决狱、搭棚过夜，这种体恤百姓疾苦，不搅扰民间，而为民众排忧释纷的人，永远活在人民心中。\n\n　　全诗三章，每章三句，全诗由睹物到思人，由思人到爱物，人、物交融为一。对甘棠树的一枝一叶，从不要砍伐、不要毁坏到不要折枝，可谓爱之有加，这种爱源于对召公德政教化的衷心感激。而先告诫人们不要损伤树木，再说明其中原因，笔意有波折亦见诗人措辞之妙。方玉润《诗经原始》说：“他诗练字一层深一层，此诗一层轻一层，然以轻愈见其珍重耳。”顾广誉《学诗详说》说：“丕言爱其人，而言爱其所茇之树，则其感戴者益深；不言当时之爱，而言事后之爱，则怀其思者尤远。”陈震《读诗识小录》说：“突将爱慕意说在甘棠上，末将召伯一点，是运实于虚法。缠绵笃挚，隐跃言外。”对此诗的技巧、语言都有精辟的论述，读者可以善加体味。全诗纯用赋体铺陈排衍，物象简明，而寓意深远，真挚恳切，所以吴闿生《诗义会通》引旧评许为“千古去思之祖”。', poem_tags = '诗经,怀人' WHERE poem_title = '甘棠' AND poem_author = '佚名';
UPDATE edu_poem SET poem_appreciation = '此词以清丽质朴的语言，描写作者春日载舟颍州西湖上的所见所感。词的上片描摹明媚秀丽的春景和众多游人的欢娱，下片写作者画舫中宴饮的情况，着重抒情。整首词意境疏放清旷，婉曲蕴藉，意言外，别有意趣。\n\n　　“堤上游人逐画船”，写所见之人：堤上踏青赏春的人随着画船行走。一个“逐”字，生动地道出了游人如织、熙熙攘攘、喧嚣热闹的情形。“拍堤春水四垂天”，写所见之景：溶溶春水，碧波浩瀚，不断地拍打着堤岸；上空天幕四垂，远远望去，水天相接，广阔无垠。第三句“绿杨楼外出秋千”，写出了美景中人的活动。这句中的“出”字用得极妙。晁无咎说：“只一‘出’字，自是后人道不到处。”（吴曾《能改斋漫录》卷十六引）王国维则说：“余谓此本于正中（冯延巳字）《上行杯》词‘柳外秋千出画墙’，但欧语尤工耳。”《人间词话》卷上（“出”字突出了秋千和打秋千的人，具有画龙点睛的作用，使人们好像隐约听到了绿杨成荫的临水人家传出的笑语喧闹之声，仿佛看到了秋千上娇美的身影，这样就幽美的景色中，平添出一种盎然的生意。\n\n　　“白发戴花君莫笑”，“白发”，词人自指。这样的老人头插鲜花，自己不感到可笑，也不怕别人见怪，俨然画出了他旷放不羁、乐而忘形的狂态。下句“六幺催拍盏频传”和上句对仗，但对得灵活，使人不觉。“六幺”即“绿腰”，曲调名。“拍”，歌的节拍。此句形象地写出画船上急管繁弦、乐声四起、频频举杯、觥筹交错的场面。歇拍“人生何处似尊前”，虽是议论，但它是作者感情的升华，写得凄怆沉郁，耐人品味。\n\n　　此词写出欧阳修与民同乐，同庆春天莅临的情怀。在词中他忘却了贬官颍州的烦恼，他愿在春醪中沉醉，一如他的雅号“醉翁”。\n\n　　堤上，游人如织，笑语喧阗；湖上，画船轻漾，春水连天。好一幅踏青赏春的图画！ 然而，这图画的点晴之处，却不在堤上、湖上、而在湖岸边、院墙内、高楼下。那绿杨丛中荡起的秋千架儿、那随着秋千飞舞而生的盈盈笑声，才是青春少女的欢畅、才是春天气息荡漾的所在；唯因它曾经深锢墙内，故如今鼓荡而出，便分外使人感染至深。船中的太守，此时也顾不得有谁在窃笑了，他情不自禁在皤然白发上插入一朵鲜花、添上一段春色。让丝竹繁奏、将酒杯频传，他要与民同乐，同庆春的莅临。忘却贬官颍州的烦恼吧，他愿在春醪中沉醉，一如他的雅号：“醉翁“。', poem_tags = '春天,写景,宴饮' WHERE poem_title = '浣溪沙·堤上游人逐画船' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '士卒劳役是多么劳苦艰辛，在潼关要道筑城。\n大城比铁还要坚固，小城依山而筑，高达万丈。\n请问潼关吏：你们重新修筑潼关是为了防御叛军吗？\n潼关吏邀请我下马步行，为我指着山隅为我介绍情况：\n“那些防御工事高耸入云端，即使飞鸟也不能越逾。\n胡贼来犯只要据守即可，又何必担心西都长安呢。\n您看这个要害的地方，狭窄到只能一辆车子通过。\n在战事紧急时挥动兵器拒守，真是‘一夫当关万夫莫开”呀。”\n“令人哀痛的是桃林塞那一败仗，唐军死伤极多，惨死黄河。\n请嘱咐守关诸将领，千万别蹈哥舒翰仓促应战的覆辙。”', poem_notes = '潼关：在华州华阴县东北，因关西一里有潼水而得名。\n草草：疲劳不堪之貌。何：多么\n大城铁不如，小城万丈余：上句言坚，下句言高。城在山上故曰万丈余。\n备胡：指防备安史叛军。\n要：同“邀”，邀请。\n连云列战格：自此句以下八句是关吏的答话。连云言其高，战格即战栅，栅栏形的防御工事。\n西都：与东都对称，指长安。\n丈人：关吏对杜甫的尊称。\n艰难：战事紧急之时。奋：挥动。\n桃林，即桃林塞，指河南灵宝县以西至潼关一带的地方。\n哥舒：即哥舒翰。', poem_appreciation = '此诗开头四句可以说是对筑城的士兵和潼关关防的总写。漫漫潼关道上，无数的士卒在辛勤地修筑工事。“草草”，劳苦的样子。前面加一“何”字，更流露出诗人无限赞叹的心情。放眼四望，沿着起伏的山势而筑的大小城墙，既高峻又牢固，显示出一种威武的雄姿。这里大城小城应作互文来理解。一开篇杜甫就用简括的诗笔写出唐军加紧修筑潼关所给予他的总印象。\n\n　　“借问潼关吏：‘修关还备胡？’”这两句引出了“潼关吏”。胡，即指安史叛军。“修关”何为，其实杜甫是不须问而自明的。这里故意发问。而且又有一个“还”字，暗暗带出了三年前潼关曾经失守一事，从而引起人们对这次潼关防卫效能的关心与悬念。这对于开拓下文，是带关键性的一笔。\n\n　　接下来，应该是潼关吏的回答了。可是他似乎并不急于作答，却“要（邀）我下马行，为我指山隅”。从结构上看，这是在两段对话中插入一段叙述，笔姿无呆滞之感。然而，更主要的是这两句暗承了“修关还备胡”。杜甫忧心忡忡，而那位潼关吏看来对所筑工事充满了信心。他可能以为这个问题不必靠解释，口说不足为信，还是请下马来细细看一下吧。下面八句，都是潼关吏的话，他首先指看高耸的山峦说：“瞧，那层层战栅，高接云天，连鸟也难以飞越。敌兵来了，只要坚决自守，何须再担心长安的安危呢！”语调轻松而自豪，可以想象，关吏说话时因富有信心而表现出的神采。他又兴致勃勃地邀请杜甫察看最险要处：老丈，您看那山口要冲，狭窄得只能容单车通过。真是一夫当关，万夫莫开。这八句，“神情声口俱活”（浦起龙《读杜心解》），不只是关吏简单的介绍，更主要的是表现了一种“胡来但自守”的决心和“艰难奋长戟”的气概。而这虽然是通过官吏之口讲出来的，却反映了守关将士昂扬的斗志。\n\n　　紧接关吏的话头，诗人却没有赞语，而是一番深深的感慨。因为诗人并没有忘记“前车之覆”。三年前，占据了洛阳的安禄山派兵攻打潼关，当时守将哥舒翰本拟坚守，但为杨国忠所疑忌。在杨国忠的怂恿下，唐玄宗派宦官至潼关督战。哥舒翰不得已领兵出战，结果全军覆没，许多将士被淹死在黄河里。睹今思昔，杜甫余哀未尽，深深觉得要特别注意吸取上次失败的教训，避免重蹈覆辙。“请嘱防关将，慎勿学哥舒。”“慎”字意味深长，它并非简单地指责哥舒翰的无能或失策，而是深刻地触及了多方面的历史教训，表现了诗人久久难以消磨的沉痛悲愤之感。\n\n　　与“三别”通篇作人物独白不同，“三吏”是夹带问答的。而此篇的对话又具有自己的特点。首先是在对话的安排上，缓急有致，表现了不同人物的心理和神态。“修关还备胡”，是诗人的问话，然而关吏却不急答，这一“缓”，使人可以感觉到关吏胸有成竹。关吏的话一结束，诗人马上表示了心中的忧虑，这一“急”，更显示出对历史教训的痛心。其次，对话中神情毕现，形象鲜明。关吏的答话并无刻意造奇之感，而守关的唐军却给读者留下一种坚韧不拔、英勇沉着的印象。其中“艰难奋长戟，万古用一夫”两句又格外精警突出，塑造出犹如战神式的英雄形象，具有精神鼓舞的力量。', poem_tags = '边疆,战争,赞美,士卒' WHERE poem_title = '潼关吏' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '汴水往东流去，河水泛着很细的水波纹，清清的淮河早晨显出鸭头绿的春色。\n您看渡口流水淘沙的地方，渡过了人世间多少人。', poem_notes = '汴水：起于今河南省荥阳县，东流经安徽，至江苏入淮河。虎眼文：文通纹。形容水波纹很细。\n鸭头春：唐时称一种颜色为鸭头绿，这里形容春水之色。此诗言及汴水、清淮，刘禹锡曾于长庆年间任和州刺史，和州北临淮河流域。', poem_tags = '写景,抒情,早教古诗100首' WHERE poem_title = '浪淘沙·其三' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '只有远离故里外出做官之人，特别敏感自然物候转化更新。\n海上云霞灿烂旭日即将东升，江南梅红柳绿江北却才回春。\n和暖的春气催促着黄莺歌唱，晴朗的阳光下绿萍颜色转深。\n忽然听到你歌吟古朴的曲调，勾起归思情怀令人落泪沾襟。', poem_notes = '和：指用诗应答。晋陵：现江苏省常州市。\n宦游人：离家作官的人。\n物候：指自然界的气象和季节变化．\n淑气：和暖的天气。\n绿苹（pín）：浮萍。\n古调：指陆丞写的诗，即题目中的《早春游望》。\n巾：一作“襟”。', poem_appreciation = '这首一首和诗，作者是用原唱同题抒发自己宦游江南的感慨和归思。江南早春天气，和朋友一起游览风景，本是赏心乐事，但诗人却像王粲登楼那样，“虽信美而非吾土”，不如归去。所以这首和诗写得别有情致，惊新而不快，赏心而不乐，感受新鲜而思绪凄清，景色优美而情调淡然，甚至于伤感，有满腹牢骚在言外。\n\n　　诗一开头就发感慨，说只有离别家乡、奔走仕途的游子，才会对异乡的节物气候感到新奇而大惊小怪。言外即谓，如果在家乡，或是当地人，则习见而不怪。在这“独有”、“偏惊”的强调语气中，生动表现出诗人宦游江南的矛盾心情。这一开头相当别致，很有个性特点。\n\n　　中间二联即写“惊新”。表面看，这两联写江南新春伊始至仲春二月的物候变化特点，表现出江南春光明媚、鸟语花香的水乡景色；实际上，诗人是从比较故乡中原物候来写异乡江南的新奇的，在江南仲春的新鲜风光里有着诗人怀念中原暮春的故土情意，句句惊新而处处怀乡。\n\n　　“云霞”句是写新春伊始。在古人观念中，春神东帝，方位在东，日出于东，春来自东。但在中原，新春伊始的物候是“东风解冻，蛰虫始振，鱼上冰”（《礼记·月令》），风已暖而水犹寒。而江南水乡近海，春风春水都暖，并且多云。所以诗人突出地写江南的新春是与太阳一起从东方的大海升临人间的，像曙光一样映照着满天云霞。\n\n　　“梅柳”句是写初春正月的花木。同是梅花柳树，同属初春正月，在北方是雪里寻梅，遥看柳色，残冬未消；而江南已经梅花缤纷，柳叶翩翩，春意盎然，正如诗人在同年正月作的《大酺》中所形容的：“梅花落处疑残雪，柳叶开时任好风。”所以这句说梅柳渡过江来，江南就完全是花发木荣的春天了。\n\n　　接着，写春鸟。“淑气”谓春天温暖气候。“黄鸟”即黄莺，又名仓庚。仲春二月“仓庚鸣”（《礼记·月令》），南北皆然，但江南的黄莺叫得更欢。西晋诗人陆机说：“蕙草饶淑气，时鸟多好音。”（《悲哉行》）“淑气催黄鸟”，便是化用陆诗，而以一个“催”字，突出了江南二月春鸟更其欢鸣的特点。\n\n　　然后，写水草。“晴光”即谓春光。“绿苹”是浮萍。在中原，季春三月“萍始生”（《礼记·月令》）；在江南，梁代诗人江淹说：“江南二月春，东风转绿苹.”（《咏美人春游》）这句说“晴光转绿苹”，便是化用江诗，也就暗示出江南二月仲春的物候，恰同中原三月暮春，整整早了一个月。\n\n　　总之，新因旧而见奇，景因情而方惊。惊新由于怀旧，思乡情切，更觉异乡新奇。这两联写眼中所见江南物候，也寓含着心中怀念中原故乡之情，与首联的矛盾心情正相一贯，同时也自然地转到末联。\n\n　　“古调”是尊重陆丞原唱的用语。诗人用“忽闻”以示意外语气，巧妙地表现出陆丞的诗在无意中触到诗人心中思乡之痛，因而感伤流泪。反过来看，正因为诗人本来思乡情切，所以一经触发，便伤心流泪。这个结尾，既点明归思，又点出和意，结构谨严缜密。\n\n　　前人欣赏这首诗，往往偏爱首、尾二联，而略过中间二联。其实，它的构思是完整而有独创的。起结固然别致，但是如果没有中间两联独特的情景描写，整首诗就不会如此丰满、贯通而别有情趣，也不切题意。从这个意义上说，这首诗的精彩处，恰在中间二联。\n\n　　尾联点明思归和道出自己伤春的本意。诗采用拟人手法，写江南早春，历历如画，对仗工整，结构细密，字字锤炼。\n\n　　这首诗造语警策。体例上韵脚分明，平仄和谐，对仗工整，已是成熟的律诗作品。结构上，首联一个意群，颔联颈联一个意群，尾联又一个意群，并且首尾呼应、中间展开。这种行文方式是初唐律诗乃至此后的唐律中常用的格式。因此，这首诗可谓初唐时期完成近体诗体式定格的奠基之作，具有开源辟流的意义。', poem_tags = '唐诗三百首,春天,思乡,伤怀,和诗' WHERE poem_title = '和晋陵陆丞早春游望' AND poem_author = '杜审言';
UPDATE edu_poem SET poem_translation = '译文 到二三里远的地方，有四五个生着炊烟的人家。 路过六七座亭台楼阁，周围有十几枝花。', poem_tags = '写景,儿歌,早教古诗100首' WHERE poem_title = '山村咏怀' AND poem_author = '邵雍';
UPDATE edu_poem SET poem_translation = '我独自靠在危亭子上，那怨情就像春草，刚刚被清理，不知不觉又已长出来。一想到在柳树外骑马分别的场景，一想到水边与那位红袖佳人分别的情形，我就伤感不已。\n佳人，上天为何赐你如此美丽？让我深深投入无力自拔？当年在夜月里，我们共同醉入一帘幽梦，温柔的春风吹拂着你我。真是无可奈何，往日的欢乐都伴随着流水远去，绿纱巾上的香味渐渐淡去，再也听不到你那悦耳的琴声。如今已到了暮春时令，片片残红在夜色中飞扬，点点细雨下着下着又晴了，雾气一片迷迷蒙蒙。我的愁思正浓，忽然又传来黄鹂的啼叫声，一声一声。', poem_notes = '八六子：杜牧始创此调，又名《感黄鹂》。\n恨如芳草：李煜《清平乐》：离恨恰如芳草，更行更远还生。”\n刬（chǎn）：同“铲”。\n青骢（cōng）：毛色青白相间的马。\n袂（mèi）红：红袖，指女子，情人。\n娉（pīng）婷：美貌，指美人。\n“春风”句：杜牧《赠别》诗：“春风十里扬州路，卷上珠帘总不如。”\n怎奈向：即怎奈、如何。宋人方言，“向”字为语尾助词。\n销凝：消魂凝恨。\n黄鹂：又名黄莺。', poem_appreciation = '这是秦观写于元丰三年（1080）的一首怀人之作，当时秦观三十二岁，孔子有云：“三十而立。”而他此时还未能登得进士第，更未能谋得一官半职。在这种处境下，忆想起以往与佳人欢娱的美好时光，展望着今后的路程，使他不能不感怀身世而有所慨叹。从艺术上看，整首词缠绵悱恻，柔婉含蓄，融情于景，抒发了对某位佳人的深深追念，鲜明地体现了秦观婉约词情韵兼胜的风格特征。 “八六子”是词牌，始见于《尊前集》中所收的杜牧之作。分上下两片，上片三处平韵，下片五处平韵，共八十八字。通常以秦观的此作为定格。\n\n　　此词写作者与他曾经爱恋的一位歌女之间的离别相思之情。全词由情切入，突兀而起，其间绘景叙事，或回溯别前之欢，或追忆离后之苦，或感叹现实之悲，委婉曲折，道尽心中一个“恨”字。\n\n　　宋神宗元丰年间，秦观在扬州意外地遇上一位多情的女子。一帘幽梦，十里柔情，时时萦绕在他的心头。归来途中，独倚危亭，回头一望，芳草连天，好似无边的离恨。以芳草喻愁，是诗词常用的手法，这里秦观却用“划尽还生”四字把它强化到极点，因此前人称之为“神来之笔”。恋人分别了。往日的欢娱，变成了流水；断了的琴弦，何时能续上？面对片片飞花、蒙蒙残雨，他几乎失魂落魄。正在此时，恼人的黄鹂又在耳边叫了起来。打起黄鹂儿，莫教枝上啼。他的心真是烦极了！\n\n　　首先，秦观词最大的特色是“专主情致”。抒情性原本就是词长于诗的特点，秦观则将词的这一特长加以光大，在这首词中体现得十分明显。词的上片临亭远眺，回忆与佳人分手，以情直入，点出词眼在于一个“恨”字。以“芳草”隐喻离恨，又是眼前的景物。忆及“柳外”“水边”分手之时词人以“怆然暗惊”抒发感受，落到现实，无限凄楚。而词的下片则设情境写“恨”。用“怎奈”、“那堪”、“黄鹂又啼数声”等词句进一步把与佳人分手之后的离愁别绪与仕途不顺，有才得不到施展的身世之“恨”，融于一处，并使之具体化、形象化，达到融情于景、情景交融的境界。\n\n　　其次，这首词的意境蕴藉含蓄，情致悠长，耐人寻味。秦观善于通过凄迷、朦胧的意境来传达自己伤感、迷惘的意绪。在这首词中，上片以“萋萋刬尽还生”的芳草写离恨，使人感到词人的离别之恨就象原上之草，春风吹又生，生生不灭。为何如此呢？词的下片创设了三个情境告诉我们个中之由：“夜月一帘幽梦，春风十里柔情”的欢娱都随流水而去，“素弦声断，翠绡香减”，词人对好景不长、离别在即的无奈溢于言表，此其一；其二是离别之时情境的渲染，“片片飞花弄晚；濛濛残雨笼晴”，词人以凄迷之景寓怅惘、伤感之情，意蕴十分丰富，是极妙的景语。其三，结尾二句，以景结情，急转直下，声情并茂，“销凝之时，黄鹂又啼数声”，一“又”字，既与起笔“倚危亭，恨如芳草，萋萋刬尽还生”遥相呼应，又再次突出了前面所述的二种情境，真可谓意蕴境中，韵逸言外，凄楚伤感之思自在其中，会心的读者一看即知。秦观就是这样善于用画面说话，举重若轻，寄凝重之思于轻灵的笔触之中，如游龙飞空，似春风拂柳。\n\n　　下片“无端”三句，再进一步追忆当时欢聚之乐。“无端”是不知何故之意，言老天好没来由，赐予她一份娉婷之姿，致使作者为之神魂颠倒。“夜月”二句叙写欢聚情况，借用杜牧诗句“娉娉袅袅十三馀，豆蔻梢头二月初。春风十里扬州路，卷上珠帘总不知。”《赠别》含蓄出之无浅露之病。“怎奈向”三句（“怎奈向”义同“奈何”）叹惋好景不常，倏又离散。“素弦声断，翠绡香减”，仍是用形象写别离，有幽美凄清之致。“那堪”二句，忽又写眼前景物，以景融情。\n\n　　“片片飞花弄晚，蒙蒙残雨笼晴”，是凄迷之景，怀人的深切愁闷中，观此景更增惆怅，故用“那堪”二字领起。结尾“正销凝，黄鹂又啼数声”，又是融情入景，有悠然不尽之意。洪迈《容斋四笔》卷十三云：“秦少游《八六子》词云：‘片片飞花弄晚，蒙蒙残雨笼晴。正销凝，黄鹂又啼数声。’语句清峭，为名流推激。予家旧有建本《兰畹曲集》，载杜牧之一词，但记其末句云：‘正销魂，梧桐又移翠阴。’秦公盖效之，似差不及也。”洪迈指出秦观词此二句是从杜牧词中脱化出来。\n\n　　此词语言上好用对句，如“柳外水边”、“夜月春风”、“素琴翠绡”、“飞花残雨”皆是，尤以“夜月”和“飞花”两联为佳，不仅语言工丽，而且各具意境。全词情景交融，景语情语难分，可谓感人至深，独具匠心。\n\n　　最后，这首词的语言清新自然，情辞相称，精工而无斧凿之痕。前人曾这样评论：“子瞻辞胜乎情，耆卿情胜乎辞，辞情相称者，惟少游而已。”秦观的词能有如此高超的语言成就：一方面，他工于炼字。这首词中“飞花弄晚，残雨笼晴”这二句是互文的，意思是飞花残雨在逗弄晚晴。这里的一“弄”一“笼”，既音韵和谐，又能使人产生无限的想象，细细品味，会感到十分贴切生动。另一方面，由于秦观长于化用古人诗句入词，使之为己所用，更加富于表现力，达到青出于蓝而胜于蓝的效果。“倚危亭”三句周济称为“神来之笔”，实则从李后主《清平乐》词“离恨恰如春草，更行更远还生”脱化而来；“夜月一帘幽梦，春风十里柔情”则暗用杜牧的“春风十里扬州路，卷上珠帘总不如”；洪迈《容斋随笔》认为词的结尾两句是模仿杜牧同一词牌的结尾“正消魂，梧桐又有移翠阴”，不论模仿是否属实，秦观这两句的妙处远胜过杜牧的此句却是不争的事实。可见，秦观继承前人语言是有创造性的，惟有创造方能显其生命力。\n\n　　“多情自古伤离别”，接天的芳草是铲不完、除不尽的离恨，恨的是那一帘幽梦早已随风飘散，那一段柔情早已成东流逝水，写词的人也早已远离我们，但是，他那柔婉含蓄、情韵兼胜的词风，以及以此写成的名篇佳句则长留人间，永远使我们回味。', poem_tags = '宋词三百首,离别,爱情,怀人' WHERE poem_title = '八六子·倚危亭' AND poem_author = '秦观';
UPDATE edu_poem SET poem_translation = '无法还乡，悲歌一曲代替思家的哭泣，登高望远就当做回到了故乡。\n茫茫的草木，重重的山岗遮住了远望的视线，思乡的忧愁盈满心怀。\n家里已经没有亲人了，哪里还有家可归？即便是有家可归，也回不去，因为前途坎坷，走投无路，无船可渡。\n很想向人诉说思乡之情、痛苦遭遇，但有许多难言之隐，只好憋闷在心中，心里万分痛苦，就像车轮在肠子里转动一般，阵阵绞痛。', poem_notes = '可以：这里是“聊以”的意思。当（dāng）：代也。\n郁郁累累（léi léi）：重重积累之貌，形容忧思很重。郁郁，愁闷的样子。累累，失意的样子。\n思：悲也。\n“肠中”句：形容内心十分痛苦。司马迁《报任安书》：“肠一日而九回。”', poem_appreciation = '这首古辞收在《乐府诗集·杂曲歌辞》中，写游子思乡不得归的悲哀。“悲歌可以当泣”，诗一开头，劈头劈脑拦腰斩断许多内容，不难理解，这位悲歌者在此之前不知哭泣过多少回了，由于太伤心，以至最后以放声悲歌代替哭泣。接着写他这样悲哀的原因：“远望可以当归”。原来是一位游子，他远离故乡，无法还乡，只好以望乡来代替还乡了。不是真的“远望可以当归”，而只是聊以解忧，无可奈何罢了。这两句把许许多多人的生活体验作了典型的艺术概括，是最能引起读者共鸣的，所以成为千古名句。\n\n　　“思念故乡，郁郁累累”，这是承接“远望”写远望所见，远望还是没有见到故乡。“郁郁”是写草木郁郁葱葱。“累累”是写山岗累累。“岭树重遮千里目”，茫茫的草木，重重的山岗遮住了望眼，难见故乡，不见亲人。\n\n　　“欲归家无人，欲渡河无船。”这两句是写思乡而未还乡的原因。家里已经没有亲人了，已经无家可归了。即便是有家可归，也回不去，因为“欲渡河无船”。所谓“欲渡河无船”，不仅仅是指眼前无船可渡，而是说自己处处受阻，前途坎坷，走投无路的意思，是这位游子悲惨命运的形象写照。这正是他思乡、望乡的根本原因。这样写，就比《艳歌行》所表达的要沉痛得多了。\n\n　　“心思不能言，肠中车轮转。”这两句写游子心中纷烦复杂、无限愁怅的思绪难以倾诉，就好像有车轮在肠中转动。末句用形象的比喻手法写出远在他乡的征夫的无限离愁，把感觉中的心理体验转化为视觉上的形象存在，比喻贴切恰当，不但“转”字关合得自然，同时能准确传神地传达出痛楚之感：愁绪随车轮转动而缓缓抽出，绵延不绝。\n\n　　这首诗和《古歌·秋风萧萧愁杀人》在思想内容上相似。最后两句均是“心思不能言，肠中车轮转”。但《古歌》是触景生情，而这首诗，既不写景，也不叙事，它以肺腑之言，真挚的感情痛苦的体验而动人心弦。可以说，抒情诗的意境，并不在于写景和叙事，只要感情真挚感人能引起共鸣，那么诗的意境就在不同的读者的脑海中幻化为丰富多彩的艺术形象了。', poem_tags = '乐府,思乡,感伤' WHERE poem_title = '悲歌' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '奸臣伯嚭使吴国灭亡，恶名却推在西施身上。\n想当年浣纱春水滚滚，声声好似为美女不平。', poem_notes = '西施滩：西施，春秋时代的越国人，家住浙江诸暨县南的苎罗山。苎罗山下临浣江，江中有浣纱石，传说西施常在此浣纱，西施滩因而得名。\n宰嚭：即伯嚭。春秋时，吴国太宰，又称太宰嚭。在吴国与越国的争战中，吴王夫差打败越国，俘虏了越王勾践及群臣，勾践贿赂了伯嚭获得了释放，回国后卧薪尝胆，终于灭了吴国。\n陷：落得，这里指承担。\n浣：洗。', poem_tags = '吊古伤今,抒情,议论' WHERE poem_title = '西施滩' AND poem_author = '崔道融';
UPDATE edu_poem SET poem_translation = '漫长的白昼难以日暮，暑热熏蒸得我心如汤煮。\n如何才能唤来万里长风，飘飘然吹起我的衣裳？\n天空升起皎洁的月亮，茂林上承映着稀疏的月光。\n仲夏之夜苦于太短，打开窗子享受一下微凉。\n夜色空明能见到细微之物，昆虫也在振翅飞翔。\n生命之体无论大小，当然都以自得其乐为常情。\n于是我想到那些执戈的士兵，一年到头守卫边疆。\n怎样才能使他们能够洗洗澡呢？他们苦于炎热却无可奈何地互相观望！\n整夜在敲击刁斗忙于警戒，喧呼声响遍四面八方。\n青紫官服虽然加在他们身上，也不如早日回到故乡。\n华州城北吹响了悲凉的胡笳，鹳鹤哀号着四处飞翔。\n唉，这乱世已令人忧伤，再加上天热烦躁身体疲惫，我不禁热切地将太平时世盼想。', poem_notes = '乾元二年（759）夏天，华州及关中大旱，杜甫写下《夏日叹》和《夏夜叹》。\n永日：夏日昼长，故称。不可暮：言似乎盼不到日落。\n毒我肠：热得我心中焦燥不安。我，一作“中”。\n昊天：夏天。华月:明月。\n延：招来。\n仲夏：夏季的第二个月，即阴历五月。\n轩：窗。\n虚明：月光。\n羽虫：夜飞的萤火虫。\n巨细：大小。\n自适：自得其乐。\n荷戈士：戍卒。\n穷年：一年到头。\n洗濯：洗涤，沐浴。\n执热：苦热。\n竟夕：整夜。\n刁斗:古代军中用具，铜制，三足有柄。白天用来做饭，夜晚敲击示警。\n青紫：贵官之服。\n北城：指华州。\n鹳鹤：水鸟名，即鹳，长嘴，能捕鱼。\n复：一作“怀”。\n时康：天下安康太平。', poem_appreciation = '《夏夜叹》描写的是窗下纳凉的情景，开始两句就是对酷暑的控诉：“永日不可暮，炎蒸毒我肠”，然后就是对清凉的期盼：“安得万里风，飘飖吹我裳”。后面就是他纳凉时的情形，接着是由此的所思：关中大旱，灾民流离失所，局势动荡，对唐肃宗和朝廷中把持大权的重臣们已失去了信心。\n\n　　此章起结各四句，中二段各八句。\n\n　　“永日不可暮，炎蒸毒我肠。安得万里风，飘飖吹我裳。”这四句感叹白日漫长，不知道什么时候才能到夜晚，酷暑难耐，使杜甫的心情烦躁。他希望能够唤来万里长风，疏解夏日的燥热。这几句日暮思风，引起下面八句的夜景。\n\n　　“昊天出华月”以下八句，描写的是夏日夜凉之景：天空升起皎洁的月亮，茂林上承映着稀疏的月光。杜甫感叹仲夏之夜太过于短暂，白日漫长。他的诗真是道出了人民的心声啊，夏日的夜晚哪里是微凉啊，只能说不是很热罢了，要是夜再长一些，也许会凉快点儿！他打开窗户，能看到夜色下的细微之物、昆虫振翅飞翔。于是，他便由此联想到生命之体无论大小，当然都以自得其乐为常情。物情各适，起下文征人。\n\n　　“念彼荷戈士”以下八句，描写的是夜热之感。杜甫由景联想到人，想到那些执戈的士兵，一年到头守卫边疆，想到他们的痛苦，炎炎夏日怎么才能使他们能够洗澡呢？他们苦于炎热，却只能无可奈何！他们整夜在敲击刁斗忙于警戒，虽然身穿官服，却还不如早日回到故乡。\n\n　　“北城悲笳发，鹳鹤号且翔。况复烦促倦，激烈思时康。”末四句乃夜触所闻，而伤叹世事也，他期盼着太平盛世。在此时，他似乎对唐肃宗和朝廷中把持大权的重臣们已失去了信心。', poem_tags = '夏天,忧国忧民' WHERE poem_title = '夏夜叹' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '汉军已经占领我楚军阵地，汉军军营传来的楚歌歌声四面缭绕。\n大王（项羽）您的霸王气概都已不复存在（准备血战而死），我还有什么理由抛弃你而独自苟且偷生呢。', poem_notes = '略：抢，掠夺。\n聊生：赖以生活。', poem_appreciation = '此诗《史记》、《汉书》都未见收载。唐张守节《史记正义》从《楚汉春秋》中加以引录，始流传至今。《楚汉春秋》为汉初陆贾所撰，至唐犹异。刘知风、司马贞、张守节都曾亲见，篇数与《汉书·艺文志》所载无异。本诗既从此书辑出，从材料来源上说，并无问题。有人认为汉初不可能有如此成熟的五言诗，颇疑其伪，但从见载于《汉书·外戚传》的《戚夫人歌》及郦道元《水经注·河水注》的《长城歌》来看，可知秦汉时其的民间歌谣，不乏五言，且已比较成熟。宋王应麟《困学纪闻》卷十二《考史》认为此诗是我国最早的一首五言诗，可见其在中国诗歌史上地位之重要。\n\n　　关于《垓下歌》，时下尽管有着种种不同的分析理解，日人吉川幸次郎甚至认为此诗唱出了“把人类看作是无常的天意支配下的不安定的存在”“这样一种感情，”从而赋予了普遍性的永恒的意义（参看《中国诗史》第40页，章培恒等译，安徽文艺出版社），但若与《虞姬歌》对读，便不难发现，项羽的这首诗原本是唱给虞姬听的爱情诗。“虞兮虞兮奈若何！”不是明明在向虞姬倾诉衷肠吗？项羽十分眷恋虞姬，所以在戎马倥偬之际，让她“常幸从”；虞姬也深深地爱着项羽，因此战事再激烈，她也不肯稍稍离开项羽一步。项羽在历次战役中所向披靡的光荣经历，深深赢得了虞姬的爱慕，项羽成了她心目中最了不起的理想英雄；而项羽的这些胜利的取得，又焉知没有虞姬的一分爱情力量在鼓舞作用？从爱情心理而言，像项羽这条刚强汉子，是不会在自己心上人面前承认自己有什么弱点的，因此，他即使心里十分清楚自己为什么会落到如此不堪的地步，而在口头上却不能不推向客观，一会儿说是“时不利”，一会儿说是“骓不逝”，而自己呢？依然是“力拔山兮盖世”，一点折扣也没有打。项羽毕竟年轻，那会儿才三十出头，对爱情充满着浪漫的理想。他爱虞姬，就一意想在她的心目中保持一个完美的形象。对于虞姬来说，她也正需要这样。极度的爱慕和深情的倾倒，使她决不相信自己心目中最理想的英雄会有什么失误。尽管现实无情，“汉兵已略地，四方楚歌声，”步步进逼的汉兵与声声凄凉的楚歌已经使楚军到了瓦解边缘，但她仍对眼下发生的一切变化感到困惑不解。\n\n　　在这种心态下，项羽的这支歌便成了她最好的安慰，最乐意接受的解释。坚贞的爱情，不仅驱逐了死亡的恐惧，且将人生的千种烦恼，万重愁绪都净化了，从而使她唱出了最为震撼人心的诗句：“大王意气尽，贱妾何聊生！”拔山盖世的气概与失败的结局是不和谐的，但英雄美人誓不相负的坚贞爱情是和谐的。在生死存亡的总崩溃的关键时刻，虞姬的这支歌，对项羽来说，不是死的哀鸣，而是生的激励。项羽处此一筹莫展之际，虽然痛感失败已不可避免，一生霸业转瞬将尽，但这犹可置而不论；而祸及自己心爱之人，则于心何忍！虞姬深悉项羽此种用心，故以誓同生死为言，直以一片晶莹无瑕的情意奉献，其意盖欲激励项羽绝弃顾累，专其心志，一奋神威而作求生之最后努力。若此说尚能探得古人心意，则不妨代项羽试为重和虞姬歌，以为此文之结束：汉兵何足惧？百战无当前。挥戈跃马去，胜败付诸天！', poem_tags = '爱情' WHERE poem_title = '和项王歌' AND poem_author = '虞姬';
UPDATE edu_poem SET poem_translation = '登上岳阳楼览尽四周风光，江水辽远通向开阔的洞庭。\n看见大雁南飞引起我忧愁之心，远处的山峰又衔来一轮好月。\n在高入云间的楼上下榻设席，在天上传杯饮酒。\n醉酒之后兴起了凉风，吹得衣袖随风舞动我们随之而回。', poem_notes = '夏十二：李白的朋友，排行十二。\n岳阳楼：坐落在今湖南岳阳市西北高丘上，“西面洞庭，左顾君山”，与黄鹤楼、滕王阁同为南方三大名楼，于716年（开元四年）扩建，楼高三层，建筑精美。\n岳阳：即岳州，以在天岳山之南，故名。治所在巴陵，即今湖南岳阳市。\n下榻：用汉代陈蕃礼徐穉、周璆事，见《春陪商州裴使君游石娥溪》诗注。\n行杯：谓传杯饮酒。\n回：回荡，摆动。', poem_appreciation = '诗的一两句写登高临远所见到的辽阔景象。“尽”字，形容登上岳阳楼，俯瞰下界，岳阳一带的自然景色一览无余。“川迥洞庭开”一句紧承“尽”字而下，具体展示八百里洞庭浩邈无垠、横无涯际的景象。孟浩然《望洞庭湖赠张丞相》一诗中写道：“八月湖水平，涵虚混太清。气蒸云梦泽，波撼岳阳城。”把秋色中洞庭湖那种汪洋浩瀚、澎湃动荡的气势，写得很动人。此处一个“开”字，即是对那种景象的集中概括。句中“川迥”二字，是写更为辽远的长江。洞庭湖的北面与长江相连，人们在岳阳楼上，隔着那壮阔的湖水，迷茫中长江依稀可见。这两句意境阔大，诗人炼词造句给人一种雄浑豪放的感受。\n\n　　上两句是俯视下界所见，三四两句便写仰观天宇所感。鸿雁南飞，月升东山，这本是人们司空见惯的客观景物，但是在特定的环境气氛之下，能够荡人心神，触发人的情怀。正如刘勰所说：“献岁发春，悦豫之情畅；滔滔孟夏，郁陶之心凝；天高气清，阴沉之志远；霰雪无垠，矜肃之虑深。岁有其物，物有其容；情以物迁，辞以情发。”（《文心雕龙》）诗人处于浩渺无边的洞庭之上，那种忧戚烦闷的心情顿时为之一畅，所以“愁心去”、“好月来”便恰到好处地表现了畅然一适的愉悦心情。句中的“引”“衔”二字，并不是客观景物的实写，而是写诗人此时此景之下的主观感受。这两句是全诗诗眼的所在，写得精采传神。\n\n　　五六两句极言岳阳楼高耸入云。意在表明在“云间”“下榻”，在“天上”“行杯”，令人快慰。“连”、“接”，二字，是夸张之笔，用于此处同样是为了突出心情的愉快。七八两句写酣饮之乐，诗人醉后翩翩起舞，习习凉风吹拂着人的衣袖，似有仙举之妙。如上四句叙写诗人与友人饮酒放乐的情景，因为是在岳阳楼上，所以叙事中又表现了岳阳楼的高耸。这样，全诗就完整地写出了秋风明月下的浩荡无边的洞庭夜景，通过优美的意境描写，表达了诗人流放获释以后的喜悦心情。\n\n　　这首诗是一首五律。就其风格而论，意气豪放，境界阔大，抒情写景有一种长风浩荡的笔力。李白一生的律诗并不少，但他的作品中较为出色的大多不是律诗。五七律之中，以五律为主。这首诗代表了他的五言律诗的风格。《唐诗品汇》说：“盛唐五言律旬之妙，李翰林气象雄逸。”《李诗纬》也说：“若太白五律，犹为古诗之遗，情深而词显，又出乎自然，要其旨趣所归，开郁宣滞，特于《风》、《骚》为近焉。”这是说他的五律依然保留着古诗的遒劲特色，但其中又有情深词显、出乎自然的新的特点。', poem_tags = '地名,写景,喜悦' WHERE poem_title = '与夏十二登岳阳楼' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '一把柴火扎得紧，天上三星亮晶晶。今夜究竟是啥夜晚？见这好人真欢欣。要问你啊要问你，将这好人怎样亲？\n一捆牧草扎得多，东南三星正闪烁。今夜究竟是啥夜晚？遇这良辰真快活。要问你啊要问你，拿这良辰怎么过？\n一束荆条紧紧捆，天边三星照在门。今夜究竟是啥夜晚？见这美人真兴奋。要问你啊要问你，将这美人怎样疼？', poem_notes = '绸（chóu）缪（móu）：缠绕，捆束。犹缠绵也。束薪：喻夫妇同心，情意缠绵，后成为婚姻礼。薪：《诗经》中大部分关于男女婚事常言及“薪”，如《汉广》“翘翘错薪”，《南山》“析薪如之何”。\n三星：即参星，主要由三颗星组成。\n良人：丈夫，指新郎。\n子兮（xī）：你呀。\n刍（chú 除）：喂牲口的青草。\n隅（yú）：指东南角。\n邂（xiè）逅（hòu）：即解媾，解，悦也。原意男女和合爱悦，这里指志趣相投的人。\n楚：荆条。\n户：门。\n粲（càn）：漂亮的人，指新娘。', poem_appreciation = '诗文每章的头两句是起兴，当是诗人所见。\n\n　　下两章“束刍”、“束楚”同“束薪”。又参星黄昏后始见于东方天空。故知“绸缪束薪，三星在天”两句点明了婚事及婚礼时间。“在天”与下两章“在隅”、“在户”是以三星移动表示时间推移，“隅”指东南角，“在隅”表示“夜久矣”，“在户”则指“至夜半”。\n\n　　三章合起来可知婚礼进行时间——即从黄昏至半夜。后四句是以玩笑的话来调侃这对新婚夫妇：“今夕何夕，见此良人（粲者）。子兮子兮，如此良人（粲者）何！”问他或她在这千金一刻的良宵，见着自己的心上人，将是如何亲昵对方，尽情享受这幸福的初婚的欢乐。语言活脱风趣，极富有生活气息。其中特别是“今夕何夕”之问，含蓄而俏皮，表现出由于一时惊喜，竟至忘乎所以，连日子也记不起的极兴奋的心理状态，对后世影响颇大，诗人往往借以表达突如其来的欢愉之情，特别是男女之间的情爱。\n\n　　此诗每小节的后四句颇值得玩味，诗人以平淡之语，写常见之事，抒普通之情，却使人感到神情逼真，似乎身临其境，亲见其人，领受到闹新房的欢乐滋味，见到了无法用语言形容的美丽的新娘，以及陶醉于幸福之中几至忘乎所以的新郎。这充分显示了民间诗人的创造力。\n\n　　从整体上看这首诗好像洞房花烛夜新婚夫妻在逗趣，具有祝福调侃的意味，非常温馨、甜蜜。在这千金一刻的良宵，见着自己的心上人，将如何尽情享受这新婚的欢乐。语言活脱风趣，极富有生活气息。特别是 “今夕何夕”之问，含蓄而俏皮，表现出由于一时惊喜，竟至忘乎所以，连日子也记不起了的心理状态。', poem_tags = '诗经,婚姻' WHERE poem_title = '绸缪' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '我刚出生的时候天下太平无事，长大之后国运急剧衰退。苍天不仁降下灾祸，大地没有仁爱之心，让我遭逢乱世。战争连绵不休，这世道想要生存分外艰难；黎明百姓流离失所，痛苦难当啊！狼烟四起，匈奴大肆烧杀抢掠，违背本意苟且偷生，丢失了节操与义心心中有愧啊！匈奴的习俗与我汉族不同难以适应，遭受种种耻辱又应当向谁诉说？胡笳吹一下瑶琴谈一拍，只是满腔悲痛与怨无人能知啊！\n\n　　戎羯逼迫我成为其妾室，挟持向西而行就像要去到天涯。高山重重直入云霄，归程怕是遥遥无期；疾风吹过千里，尘沙飞扬。胡人人数众多又残暴凶狠如毒蛇，披甲持弓，一路骄横奢侈。琴弦上高唱两拍，心中悲痛欲绝；心中志气早被摧残殆尽，只有独自悲叹了。\n\n　　越过汉朝的国界，进入了胡人城中，家园已破又失清白，这般苟且偷生不如一死解脱。毡裘穿在身上让人心惊肉跳、不寒而栗，羊膻味让人难以忍受，只能逼迫自己勉强吞咽。胡人彻夜敲鼓，喧闹烦人，狂风呼啸，卷着黄沙将那营门堵塞。伤今感惜无穷尽，三拍已制成，心中积蓄的悲愤与仇恨又何时才能平复呢？\n\n　　日日夜夜都如此，叫我怎能不思念故土，世上生存的人啊！还有比我更苦的吗？天降灾祸国家动乱，汉家百姓无所依，只怨我红颜薄命沦落至这胡人之营啊！习俗不同心无所归，怎能与他们生活相处；爱好不同，心中所感又能与谁人说！回想我的经历，几多艰难险阻，四拍制成曲调更显哀怨凄楚。\n\n　　大雁南飞时想让它帮我捎去对家乡的思念，北归时为我捎来回信。大雁高飞而去，渐渐不见踪迹；肝肠寸断有能怎样，只能默默苦思。紧锁眉头对月抚琴，五拍的曲调清幽，心中积蓄的愁绪更深。\n\n　　冰霜寒冷刺骨却比不上我的身世苦寒，面对那羊肉和奶酪，就算是饥肠辘辘也没有胃口。夜间听闻那陇河水声呜咽哀怨，晨起遥望万里长城什么时候才能归去啊！回想这一路西行的路程是何等的艰难凄苦，六拍唱完悲从中来，不愿再弹琴！\n\n　　黄昏北风呼啸边声四起，不知心中忧愁与谁说！原野景象一片萧条设置的防守哨所遍布万里，匈奴习俗喜好青年崇尚力量，低贱老弱病残。哪里水草丰美就在哪里驻扎安家，牛羊遍地，聚在一起就像那蚁穴跟蜂巢。等到喝光水源吃光丰草再迁徙走，七拍唱尽更是悔恨居住于此。\n\n　　如果老天有眼为何看不见我独自漂泊？如果天神真的灵验为何让我天南海北凄怆孤苦？我从未辜负苍天，又为何给我匹配一个异族的丈夫？我从未辜负天神为何惩罚我沦落荒州？制出胡笳第八拍，希望借此排解忧愁；谁知制成后心中更是愁苦加倍。\n\n　　天无涯地无边，我心中的愁苦也没有休止。人生短暂仿如白驹过隙，可是我年华正当却是满怀忧愁，一点都不快乐。怨恨至极欲问天，上天遥遥无路攀登。仰望天幕只余滚滚云烟，九拍曲中满怀深情，可又能向谁传递呢？\n\n　　城头的烽火未曾熄灭，残酷的战争何时才能停止？城门口每天都是杀气腾腾，夜夜总是能听到那呼啸的北风。故乡的消息完全被阻绝，无声哭泣气将绝。一生的辛酸悲苦都来自这无尽别离，十拍饱含深深恨意，行行泪珠如泣血。\n\n　　我并不是贪生怕死才苟活至今，不能为国捐躯是心有期盼。活着就还有希望能回到故乡，死后葬于故土才能心安。来到匈奴已是一年又一年，胡人丈夫宠我爱我已是育有二子。养育他们并不觉得羞耻，只是怜惜孩子生长之地太偏远，苦了他们。十一拍也因此多了骨肉亲情，哀怨缠绵的声调直入心底。\n\n　　大地回春天气逐渐回暖，可能是知道汉家天子讲和了吧。载歌载舞一起欢唱庆祝，两国交合从此再无战争。突然遇到汉朝所来的使者，带来诏书跟千金专门来赎我身。欣喜有生之年能回去还能上朝面见圣君，可叹要抛弃幼子以后再无相聚之日。十二拍有喜有悲，心中的情绪难以言清。\n\n　　谁曾想到此生还有机会再回故土，抱着我那可怜的孩儿泪如雨下。汉朝使者带着四马的车架迎接我好不威风，孩儿哭嚎痛碎娘亲的心，只是谁又知道呢？为何偏在此时让我们母子生死离别，心中哀痛顿感日月无光，只希望自己能生出羽翼带他们一起回去。走一步就远一步啊，脚下如有千斤难以移动；孩子的身影已无，伤心欲绝。十三拍的曲调急切悲伤，肝肠寸断又有谁人能知。\n\n　　我能回归故土却孩儿难相随，心中空悬犹如常常饥饿未进食。天下万物四时兴旺衰败都有期限，只有我的愁苦从未停止。山高地阔相见遥遥无期，夜深人静时梦见孩儿好像就在身边。梦中拉着他的手，一个喜来一个悲，醒来后心痛难当什么时候才会休止。十四拍的曲调啊，一把鼻涕一把泪；那东流的黄河水啊，都是我思念孩子的泪水。\n\n　　十五拍曲调急促，满腔愁绪谁能体会？住在帐篷中嫁给胡人做妻子。天随人愿得以归来，心中无限欢欣。心中有所牵挂，所有的快乐又变成了更深的愁绪，太阳和月亮大公无私却对我如此的不公平。母子分离让我心中难以承受，同在一片天空下却要永远隔绝，从此生死不知叫人去何处相寻。\n\n　　十六拍愁思茫茫，我与孩子天各一方。日日夜夜隔空相望，不能随我回家让我思念断肠。忘忧草难以忘忧，独自弹琴更加忧伤！今日与子分别回故乡，旧怨才平息新怨又悠长！哭泣不止抬头向天哭诉，为何让我活下来却又给我如此多的磨难。\n\n　　弹到十七拍时心鼻酸，关山重重阻碍路难行。去时怀念故土心绪杂乱，回家时与孩子分别忧思漫漫。塞上的野草已是干枯一片，沙场尸骨如堆刀痕箭斑仍清晰。春夏季节交替时分的天气比那冬天还要刺骨寒冷，人马饥饿疲惫也已没了力气。哪里会想到还能重回故土，连连叹息眼泪也哭干了。\n\n　　胡笳本就出自匈奴中，换成琴曲音律相同。十八拍琴曲已经到尾声，余音袅袅忧思无穷。能够知道音乐的奥妙共性全是上苍命运的捉弄，忧愁欢乐跟随人心有了改变就能变通。匈奴与汉朝地域风俗不同，就像那天地相隔，孩子在西母在东。可叹我心中怨气太深仿似那被乌云遮蔽的长空，天地虽广也无法将我的哀愁包容！', poem_notes = '祚：福，这里之国家运势。\n干戈：指战争。\n烟尘：烽烟和战场上扬起的尘土。指战乱。\n胡虏：秦汉时称匈奴為胡虏，后世用為与中原敌对的北方部族之通称。\n殊：不同。\n笳：中国古代北方民族的一种乐器，类似笛子。\n戎羯：戎和羯。古族名。泛指西北少数民族。\n遐：远。\n控弦：拉弓；持弓。\n悲嗟：伤心叹息。\n毡裘：指古代北方游牧民族以皮毛製成的衣服。\n羯羶：羊臊气。\n衔悲：心怀悲戚。\n畜恨：积恨。\n嗜欲：嗜好与欲望。\n涉历：经过；经历。\n汉青：古时在竹简上记事，先以火烤青竹，使水分如汗渗出，便于书写，并免虫蛀，故称。一说，取竹青浮滑如汗，易于改抹。后以“汗青”指著述完成。\n攒眉：皱眉。\n陇水：河流名。源出陇山，因名。\n杳漫：渺茫旷远。\n烽戍：设置烽燧，驻兵防守之处。\n殊匹：异族的配偶。\n辛苦：辛酸悲苦。\n桑梓：借指故乡\n边鄙：边疆；边远的地方。\n应律：应合历象。\n不谓：不意，不料。\n騑騑：马行走不止貌。\n商参：参商。二十八宿的商星与参星，商在东，参在西，此出彼没，永不相见。后以“商参”比喻人分离不能相见。\n萱草：植物名。俗称金针菜、黄花菜、多年生宿根草本，其根肥大。叶丛生，狭长，背面有棱脊。花漏斗状，橘黄色或桔红色，无香气，可作蔬菜，或供观赏。根可入药。古人以為种植此草，可以使人忘忧，因称忘忧草。\n罹：遭受苦难或不幸。\n怀土：怀恋故土。\n黄蒿：枯黄了的蒿草。亦泛指枯草。\n岂知：哪里知道。\n翻出：重新改作。\n哀乐：悲伤、快乐。\n六合：天地四方；整个宇宙的巨大空间。', poem_appreciation = '《胡笳十八拍》是感人肺腑的千古绝唱，它的作者就是蔡文姬。欣赏此诗，不要作为一般的书面文学来阅读，而应想到是蔡文姬这位不幸的女子在自弹自唱，琴声正随着她的心意在流淌。随着琴声、歌声，我们似见她正行走在一条由屈辱与痛苦铺成的长路上……\n\n　　她在时代大动乱的背景前开始露面，第一拍即点“乱离”的背景：胡虏强盛，烽火遍野，民卒流亡。汉末天下大乱，宦官、外戚、军阀相继把持朝政，农民起义、军阀混战、外族入侵，陆续不断。汉末诗歌中所写的“铠甲生机虱，万姓以死亡。白骨露于野，千里无鸡鸣。”等等，都是当时动乱现象的真实写照。蔡文姬即是在兵荒马乱之中被胡骑掠掳西去的。\n\n　　被掳，是她痛苦生涯的开端，也是她痛苦生涯的根源，因而诗中专用第二拍写她被掳途中的情况，又在第十拍中用“一生辛苦兮缘别离，”指明一生的不辛源于被掳。她被强留在南匈奴的十二年间，在生活上和精神上承受着巨大的痛苦。胡地的大自然是严酷的：“胡风浩浩”、“冰霜凛凛”、“原野萧条”、“流水呜咽”，异方殊俗的生活是与她格格不入的。毛皮做的衣服，穿在身上心惊肉跳：“毡裘为裳兮骨肉震惊。”以肉奶为食，腥膻难闻，无法下咽，“羯膻为味兮枉遏我情。”居无定处，逐水草而迁徙，住在临时用草筏、干牛羊粪垒成的窝棚里；兴奋激动时，击鼓狂欢，又唱又跳，喧声聒耳，通宵达旦。总之，她既无法适应胡地恶劣的自然环境，也不能忍受与汉族迥异的胡人的生活习惯，因而她唱出了“殊俗心异兮身难处，嗜欲不同兮谁可与语”的痛苦的心声，而令她最为不堪的，还是在精神方面。\n\n　　在精神上，她经受着双重的屈辱：作为汉人，她成了胡人的俘虏；作为女人，被迫嫁给了胡人。第一拍所谓“志意乖兮节义亏”，其内涵正是指这双重屈辱而言的。在身心两方面都受到煎熬的情况下，思念故国，思返故乡，就成了支持她坚强地活下去的最重要的精神力量。从第二拍到第十一拍的主要内容便是写她的思乡之情。第四拍的“无日无夜兮不念我故土”，第十拍的“故乡隔兮音尘绝，哭无声兮气将咽”，第十一拍的“生仍冀得兮归桑梓”，都是直接诉说乡情的动人字句。而诉说乡情表现得最为感人的，要数第五拍。在这一拍中，蔡文姬以她执着的深情开凿出一个淡远深邃的情境：秋日，她翘首蓝夭，期待南飞的大雁捎去她边地的心声；春天，她仰望云空，企盼北归的大雁带来的故土的音讯。但大雁高高地飞走厂，杳邈难寻，她不由得心痛肠断，黯然销魂……。在第十一拍中，她揭出示自己忍辱偷生的内心隐秘：“我非贪生而恶死，不能捐身兮心有以。生仍冀得兮归桑梓，死得埋骨兮长已矣。”终于，她熬过了漫长的十二年，还乡的宿愿得偿，“忽遇汉使兮称近诏，遣千金兮赎妾身。”但这喜悦是转瞬即逝的，在喜上心头的同时，飘来了一片新的愁云，她想到自己生还之日，也是与两个亲生儿子诀别之时。第十二拍中说的：“喜得生还兮逢圣君，嗟别稚子兮会无因。十有二拍兮哀乐均，去住两情兮难具陈”，正是这种矛盾心理的坦率剖白。从第十三拍起，蔡文姬就转入不忍与儿子分别的描写，出语便咽，沉哀入骨。第十三拍写别子，第十四拍写思儿成梦，“抚抱胡几兮位下沾衣。……一步一远兮足难移，魂销影绝兮恩爱移”，“山高地阔兮见汝无期，更深夜阑兮梦汝来斯。梦中执手兮一喜一悲，觉后痛吾心兮无休歇时，”极尽缠绵，感人肺腑。宋代范时文在《对床夜话》中这样说：“此将归别子也，时身历其苦，词宣乎心。怨而怒，哀前思，千载如新；使经圣笔，亦必不忍删之也。”蔡文姬的这种别离之情，别离之痛，一直陪伴着她，离开胡地，重入长安。屈辱的生活结束了，而新的不幸：思念亲子的痛苦，才刚刚开始。“胡与汉兮异域殊风，天与地隔兮子西母东。苦我怨气兮浩于长空，六和虽广兮受之应不容。”全诗即在此感情如狂潮般涌动处曲终罢弹，完成了蔡文姬这一怨苦向天的悲剧性的人生旅程。\n\n　　《胡笳十八拍》既体现了蔡文姬的命薄，也反映出她的才高。《胡笳十八拍》在主人公，即蔡文姬自己的艺术形象创造上，带有强烈的主观抒情色彩，即使在叙事上也是如此，写被掳西去，在胡地生育二子，别儿归国，重入长安，无不是以深情唱叹出之。如写被掳西去：“云山万重兮归路遇，疾风千里兮扬尘沙。人多暴猛兮如狂蛇，控弦被甲兮为骄奢”，处处表露了蔡文姬爱憎鲜明的感情——“云山”句连着故土之思，“疾风”句关乎道路之苦。强烈的主观抒情色彩，更主要地体现在感情抒发的突发性上。蔡文姬的感情，往往是突然而来，忽然而去，跳荡变化，匪夷所思。正所谓“思无定位”，甫临沧海，复造瑶池。并且诗中把矛头直指天、神：“天不仁兮降乱离，地不仁兮使我逢此时。”“为天有眼兮何不见我独漂流？为神有灵兮何事处我海北天南头？我不负天兮天何配我殊匹？我不负神兮神何殛我越荒州？”把天、神送到被告席，更反映出蔡文姬的“天无涯兮地无边，我心愁兮亦复然，”“苦我怨气兮浩于长空”的心情。\n\n　　《胡笳十八拍》的艺术价值很高，明朝人陆时雍在《诗镜总论》中说：“东京风格颓下，蔡文姬才气英英。读《胡笳吟》，可令惊蓬坐振，沙砾自飞，真是激烈人怀抱。”\n\n　　《胡笳十八拍》的艺术价值高，与蔡文姬的才高有关，蔡文姬的才高是由她的家世和社会背景造成的。', poem_tags = '叙事,长诗,感伤,人生,乐曲' WHERE poem_title = '胡笳十八拍' AND poem_author = '蔡文姬';
UPDATE edu_poem SET poem_translation = '这座亭子用雨来命名，是为了纪念喜庆的事件。古时候有了喜事，就用它来命名事物，表示不忘的意思。周公得到天子赏赐的稻禾，便用“嘉禾”作为他文章的篇名；汉武帝得了宝鼎，便用“元鼎”称其年号；叔孙得臣打败敌人侨如，便用侨如作为儿子的名字。他们的喜事大小不一样，但表示不忘的意思却是一样的。\n\n　　我到扶风的第二年，才开始造官邸，在堂屋的北面修建了一座亭子，在南面开凿了一口池塘，引来流水，种上树木，把它当做休息的场所。这年春天，在岐山的南面下了麦雨，占卜此事，认为今年有个好年成。然而此后整整一个月没有下雨，百姓才因此忧虑起来。到了三月的乙卯日，天才下雨，甲子日又下雨，百姓们认为下得还不够；丁卯日又下了大雨，一连三天才停止。官吏们在院子里一起庆贺，商人们在集市上一起唱歌，农夫们在野地里一起欢笑，忧愁的人因此而高兴，生病的人因此而痊愈，而我的亭子也恰好造成了。\n\n　　于是我在亭子里开酒宴，向客人劝酒而告诉了这件事，问他们道：“五天不下雨可以吗？”他们回答说：‘五天不下雨，就长不成麦子了。”又问“十天不下雨可以吗？”他们回答说：“十天不下雨就养不活稻子了。”“没有麦没有稻，年成自然荒废了，诉讼案件多了，而盗贼也猖獗起来。那么我与你们即使想在这亭子上游玩享乐，难道可能做得到吗？现在上天不遗弃这里的百姓，刚有旱象便降下雨来，使我与你们能够一起在这亭子里游玩赏乐的，都靠这雨的恩赐啊！这难道又能忘记的吗？”\n\n　　既用它来命名亭子以后，又接着来歌唱此事。歌词说的是：“假使上天下珍珠，受寒的人不能把它当做短袄；假如上天下白玉，挨饿的人不能把它当做粮食。一场雨下了三天，这是谁的力量？百姓说是太守，太守说没有这力量。归功于天子，天子也否认。归之于造物主，造物主也不把它当作自己的功劳，归之于太空。而太空冥然飘渺，不能够命名它，于是我用它来为我的亭子命名。', poem_notes = '志：记。\n周公得禾，以名其书：周成王得一种“异禾”，转送周公，周公遂作《嘉禾》一篇。\n汉武得鼎，以名其年：汉武帝元狩七年（前116），得一宝鼎，于是改年号为元鼎元年。《通鉴考异》认为得宝鼎应在元鼎四年，元鼎年号是后来追改的。\n叔孙胜敌，以名其子：鲁文公派叔孙得臣抵抗北狄入侵，取胜并俘获北狄国君侨如。叔孙得臣遂更其子名为“侨如”。\n扶风：凤翔府。\n明年：第二年。\n治：修建。\n雨麦：麦苗返青时正好下雨。\n占：占卜。\n有年：年将有粮，引申为大丰收。\n弥：整、满。\n雨，下雨。\n乙卯：农历四月初二。\n甲子：农历四月十一日。\n丁卯：农历四月十四口。\n相与：汇聚。\n贾：指坐商。\n忭：欢乐、喜悦。\n适：恰巧。\n属：同“嘱”，意为劝酒。\n禾：谷子，即小米。\n荐饥：古人说：“连岁不熟曰荐”，因此“荐饥”意应为：连续饥荒。\n滋：增多。\n炽：旺盛。\n优游：安闲舒适、无优无虑的神态。\n斯：这些。\n踢：给予。\n襦：本意短衣，此处代表所有的衣服。\n伊：语助词，无意。\n不：通“否”，意为不然。\n造物：造物主（即上帝）或指上天。\n冥冥：高远渺茫。', poem_tags = '古文观止,咏物,写雨,忧国忧民' WHERE poem_title = '喜雨亭记' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '凿开混沌之地层，获得煤炭是乌金。蕴藏无尽之热力，心藏情义最深沉。\n融融燃起之炬火，犹如浩浩之春风。熊熊洪炉之烈焰，照破灰沉之夜空。\n钟鼎彝器之制作，全靠原力之生成。铁石虽然已死去，仍然保留最忠心。\n只是希望天下人，都能吃饱又穿暖。不辞辛劳与艰苦，走出荒僻之山林。', poem_notes = '混沌（dùn）：古代指世界未开辟前的原始状态。这里指未开发的煤矿。乌金：指煤炭，因黑而有光泽，故名。\n阳和：原指阳光和暖。这里借指煤炭蓄藏的热力。意最深：有深层的情意。\n爝（jué）火：小火，火把。浩浩：广大无际貌。\n烘炉：大火炉。\n鼎彝（yí）：原是古代的饮食用具，后专指帝王宗庙祭器，引申为国家、朝廷。这里兼含两义。鼎，炊具；彝，酒器。元：通“原”，本来。赖：依靠。生成力：煤炭燃烧生成的力量。\n“铁石”句：意谓当铁石被消融而化为煤炭的时候，它仍有为人造福之本心。古人误认为煤炭是铁石久埋地下变成的。\n苍生：老百姓。', poem_appreciation = '这首咏物诗，是作者以煤炭自喻，托物明志，表现其为国为民的抱负。于写物中结合着咏怀。\n\n　　第一句：咏煤炭点题。\n\n　　第二句：正面抒怀，说这里蕴藏着治国安民的阳和布泽之气。“意最深”，特别突出此重点的深意。“春浩浩”承接“阳和”，“照破夜沉沉 ”，对照着写，显示除旧布新的力量。古人称庙堂宰相为鼎鼐，这里说宰相的作为，有赖于其人具有生成万物的能力，仍从煤炭的作用方面比喻。\n\n　　第三句：“铁石”句表示坚贞不变的决心，也正是于谦人格的写照。\n\n　　第四句：“但愿苍生俱饱暖”，从煤炭进一步生发，即杜甫广厦万间大庇天下寒士之意而扩大之。末句绾结到自己出山济世，一切艰辛在所甘心历之的本意，即托物言志。\n\n　　综上：\n\n　　前四句描写煤炭的形象，写尽煤炭一生。后四句有感而发，抒发诗人为国为民，竭尽心力的情怀。全诗以物喻人，托物言志。 诗人一生忧国忧民，以兴国为己任。其志向在后四句明确点出，其舍己为公的心志在后两句表现得尤为明显。综合全诗，诗人在诗中表达了这样的志向：铁石虽然坚硬，但依然存有为国为民造福之心，即使历尽千辛万苦，他也痴心不改，不畏艰难，舍身为国为民效力。', poem_tags = '咏物,爱国,忧国忧民,抱负' WHERE poem_title = '咏煤炭' AND poem_author = '于谦';
UPDATE edu_poem SET poem_translation = '钴鉧潭，在西山的西面。钴鉧潭水由冉水自南向北奔流如注，碰到山石阻隔，曲折向东流去；冉水的上游和下游水势峻急，撞击更加激荡，侵蚀钴鉧潭的潭岸边，潭边广阔而中间水深，水流冲荡到山石才停止。水流形成车轮般的漩涡，然后才缓缓而流。潭水清澈而平缓，而且十亩有余，钴鉧潭四周有树木环绕，有瀑布垂悬而下。\n山上有居住者，因我多次来游玩，一天早晨敲门就来告诉我：“（我因为）无法负担越欠越多的官租私债，（没办法），想在山上锄草开荒，并愿意卖掉我潭上的田，暂时缓解一下债”。我很高兴答应了他的话。我就加高台面，延伸栏杆，疏导高处的泉水使泉水坠落入潭中，发出了悦耳的声音。特别是到了中秋时节赏月更为合适，可以看到天空更高，视野更加辽远。是什么使我乐于住在这夷人地区而忘掉故土？难道不是因为这钴鉧潭？', poem_notes = '（1）钴鉧（gǔ mǔ）：熨斗。钴鉧潭：形状像熨斗的水潭。也有学者认为钴鉧是釜锅。\n（2）冉水：即冉溪，又称染溪。\n（3）屈：通“曲”，弯曲。\n（4）其颠委势峻：其，指冉水的源头。颠委，首尾，这里指上游和下游。势峻，水势峻急。\n（5）荡击：猛烈冲击。益暴：更加暴怒。\n（6）啮（niè）其涯：啮，咬、啃。\n涯：边沿。这里指侵蚀着岸边。\n（7）轮：车轮般的漩涡。\n（8 ）然后徐行，徐：慢慢地。\n（9）有树环焉，有泉悬焉：环：环绕。焉：在那里。兼指代词。悬：自高处而下。有树环绕在潭上，有泉水从高处流入潭里。\n（10）以余之亟（qì）游：以：因为。余：我。亟：经常，多次。因为我经常去游玩。\n（11）款门：敲门。\n（12）不胜官租、私券之委积：不胜：承担不了。券：债务的借据。委积：累积的压力。承受不了官家租税和私人债务的重压。\n（13）芟（shān）：割草。\n芟山：割草开山。更居：搬迁居住的地方。\n（14）贸财以缓祸：贸财，以物变卖换钱。\n缓祸，缓解目前灾难。这里指解救税债之灾难。\n（15）崇其台：崇，加高。\n其，指示代词，这里指潭。加高潭边的台沿。\n（16）延其槛：延长那里的栏杆。\n延：加长。\n槛：栏杆。\n（17）行其泉于高者坠之潭：引导那些高处的泉水，使之坠落到潭里。\n（18）潨（cóng）然：水声淙淙的样子。\n（19）尤与中秋观月为宜：尤其是在中秋晚上赏月更为适合。\n（20）于以见天之高、气之迥：在这里可以看见天空的高远，感受到空气的清爽。\n于以：于此，在这里行。\n迥：辽远。\n（21）居夷：住在夷人地区。', poem_appreciation = '柳宗元青年时代就立下雄心壮志，仰慕“古之夫大有为者”，向往于“励材能，兴功力，致大康于民，垂不灭之声”。他25岁时已是“文章称首”的长安才子，刚考中了博学弘辞科，又与礼部郎中杨凭之女新婚，逐步成为文坛领袖，政坛新锐。在其后的几年里，柳宗元又成为了当时皇帝的老师王叔文革新派的中坚分子，以热情昂扬、凌励风发的气概，准备施展自己“辅时及物”、“利安开元”的抱负。然而，由于顺宗皇帝李诵即位时就已经中风，说话也不清楚，虽然有心改革朝政，但已是心有余而力不足了，加上宦官与藩镇势力强大，所以革新只实行了几个月，就以失败而告终。元和四年八月，反对革新的太子李纯即位，九月，柳宗元立刻被贬邵州刺吏，行未半路，朝议认为处之太轻，又改贬永州司马。当时同时被贬的包括刘禹锡等人共有八位，史称“八司马事件”。\n\n　　“永贞革新”的失败对政治上踌躇满志的柳宗元是沉重的打击，但对于他的文学创作却未尝不是一件好事。当时的永州“草中狸鼠足为患，一夕十顿惊且伤”，相当于俄罗斯的西伯利亚，所谓的“永州司马外置同正员”，其实是个编制外的闲职，没有官舍也没有具体的职务。柳宗元一家人寄居在冷清的小寺庙，未及半载，母亲也逝世了。除了精神上抑郁悲愤，正当壮年的柳宗元身体也越来越差，诸病缠身，虚弱到了“行则膝颤，坐则髀痹”的程度。但永州清新的山水给了柳宗元很大的慰藉和寄托，他很快从悲观与失意中振作起来，踏遍了永州的山山水水并和田翁农夫相交，远离了政坛上的明争暗斗，回归到田园诗意般的生活，他认为永州的山水和自己一样的为世人所遗弃和漠视，写出了许多千古传诵推崇永州山水的散文。余秋雨先生在《柳侯祠》中如此评价柳宗元的永州10年，他说：“炎难也给了他一份宁静，使他有了足够的时间与自然相晤，与自我对话！”确实，永州的10年，是柳宗元人生最晦暗最感伤的十年，却是他文学创作最丰富和哲学思想全面成熟的10年。\n\n　　柳宗元的文章多抒写抑郁悲愤、思乡怀友之情，幽峭峻郁，自成一路。最为世人称道者，是那些清深意远、疏淡峻洁的山水闲适之作。《永州八记》是柳宗元山水游记的代表作，也是我国游记散文中的一朵奇葩，其艺术魅力历久弥新。\n\n　　永州山水，在柳宗元之前，并不为世人所知。但这些偏居荒芜的山水景致，在柳宗元的笔下，却表现出别具洞天的审美特征，极富艺术生命力。正如清人刘熙载在《艺概·文概》中所说：“柳州记山水，状人物，论文章，无不形容尽致；其自命为‘牢笼百态’，固宜。”柳宗元时而大笔挥洒，描摹永州山水的高旷之美，使寂寥冷落的永州山水给人以气势磅礴之感。\n\n　　《永州八记》对自然美的描绘，贵在精雕细刻出一种幽深之美。八记描写的大都是眼前小景，如小丘、小石潭、小石涧、小石城山等，柳宗元总是以小见大，犹如沙里淘金，提炼出一副副价值连城的艺术精品。如《至小丘西小石潭记》对小石潭周围环境的描写，“四面竹树环合，寂寥无人，凄神寒骨，悄枪幽邃”，创造出一种空无人迹的山野清幽之美。又如《石渠记》对小石渠之水流经之处细腻的刻画，在长不过十许步的小水渠上，一处处幽丽的小景，美不胜收。逾石而往是昌蒲掩映、鲜苔环周的石泓，又折而西行，旁陷岩石之下是幅员不足百尺、鱼儿穿梭的清深的小水潭，又北曲行，皆诡石、怪木、奇卉、美竹。\n\n　　笔笔眼前小景，幽深宜人，展示出永州山水的特有风姿。柳宗元曾经说：“余虽不合于俗，亦颇以文墨自慰，漱涤万物，牢笼百态，而无所避之。”他的意思就是说虽然因永贞革新遭挫，但作者未改本色，于是借山水之题，发胸中之气，洗涤天地间万物，囊括大自然的百态，在用笔赞赏山水美的同时，把自己和山水融化在一起，借以寻求人生真谛，聊以自慰。因而，柳宗元在《永州八记》中刻画永州山水的形象美、色彩美和动态美，不是纯客观地描摹自然，而是以山水自喻，赋予永州山水以血肉灵魂，把永州山水性格化了。可以说，永州山水之美就是柳公人格美的艺术写照，物我和谐，汇成一曲动人心弦的人与自然的交响华章。\n\n　　《旧唐书·柳宗元传》说，柳宗元“下笔构思”，“精裁密致，璨若珠贝”。精裁密致可以概括《永州八记》结构之美。8篇游记，整体构思，一气贯通。文章以西山之怪特开始“然后知吾向之未始游，游于是乎始”发笔，通过对西山周围山水景致的描绘，袁家渴附近山水小景的刻画，最后，到《小石城山记》向苍天发出“吾疑造物者之有无久矣”的质问，对整个八记作结。8篇游记每篇多各以不同的方式与上篇相关联，前后呼应，成为一个不可分割的有机的艺术整体。如前四篇，首篇写了西山宴游之后，第二篇就以“钻拇潭在西山西”起笔，自然衔接，毫无斧凿的痕迹；第三篇又以“潭西二十三步”发端，同上篇相连；第四篇则以“从小丘西行百二十步”开篇。这就以西山为起点，向西出游，接连出现了三处胜景，一处连一处，一景接一景，给人以目不暇接之感。更令人折服的是，八记前后四篇相隔三全夕久，而作者巧妙组合，犹如一气呵成，毫无间隔之弊。', poem_tags = '辞赋精选,山水,游记' WHERE poem_title = '永州八记' AND poem_author = '柳宗元';
UPDATE edu_poem SET poem_translation = '黑夜里北斗七星挂得高高，哥舒翰勇猛守边夜带宝刀。\n吐蕃族至今牧马只敢远望，他们再不敢南来越过临洮。', poem_notes = '哥舒：指哥舒翰，是唐玄宗的大将，突厥族哥舒部的后裔。哥舒是以部落名称作为姓氏。《全唐诗》题下注：“天宝中，哥舒翰为安西节度使，控地数千里，甚著威令，故西鄙人歌此。”\n北斗七星：大熊座的一部分。\n窥：窃伺。牧马：指吐蕃越境放牧，指侵扰活动。\n临洮：今甘肃省洮河边的岷县。一说今甘肃省临潭县。秦筑长城西起于此。', poem_appreciation = '这是唐代西北边民对唐朝名将哥舒翰的颂歌。此诗从内容上看，是颂扬哥舒翰抵御吐蕃侵扰、安定边疆的；同时也通过这个形象寄寓了人民渴望和平、安定的理想和愿望。“北斗七星高，哥舒夜带刀”。第一句是起兴，诗人用高挂在天上的北斗星，表达边地百姓对哥舒翰的敬仰。“至今窥牧马，不敢过临洮”，牧马，就其含意而言，也就是代指一切侵扰活动。自从遭到哥舒翰的抵御，吐蕃再也不敢越过临洮进行骚扰。\n\n　　这首诗题为《哥舒歌》，哥舒之所以值得歌唱，是因为他戍边抗敌，保国为民。但是，作者并不从激烈的战斗中直接表现他如何英勇善战，如何机智果敢，用兵如神等等，而是通过侧面描写的手法来突出主题。诗的第一句就把哥舒翰在人民心中的威望渲染出来。人民为何赞扬，吐蕃何故畏惧；过去吐蕃长驱直入，如今又为什么“不敢过临洮”，这都是宣扬哥舒翰的赫赫武功。可见这样的描写是很富于启发性的。“哥舒夜带刀”，这个“夜”字是颇有讲究的，它把起兴的第一句和第二句巧妙地联系起来了，把赞扬和崇敬之情融注于人物形象之中；同时又将边地的紧张气氛和人物的警备神态刻画出来了。“哥舒夜带刀”五个字干净利落，好像是一幅引人注目的人物画像。在那简炼有力、富有特征的形象中，蕴藏了一股英武之气，给人一种战则能胜的信心，而给吐蕃以“屏足不敢近”的威慑。因此，就反映人物内心世界和表现诗的主题来讲，“哥舒夜带刀”比起那种冲锋陷阵的形象更丰富、更传神，更能诱导人们的想象。\n\n　　这首《哥舒歌》可能是经过修改加工后的作品，但是它那种朴实和巧妙、明朗和含蓄相统一的风格，依然显示出民歌的特色。', poem_tags = '唐诗三百首,赞颂,民歌' WHERE poem_title = '哥舒歌' AND poem_author = '西鄙人';
UPDATE edu_poem SET poem_translation = '注释 此词调名亦作《渔父词》，《历代诗余》中作《渔歌子》。据宋阮阅《诗话总龟》载：“予尝于富商高氏家，观贤画《盘车水磨图》，及故大丞相文懿张公弟，有《春江钓叟图》，上有南唐李煜金索书《渔父词》二首。其一曰：‘浪花有意千里雪，……’其二曰：‘一棹春风一叶舟，……’”。另《古今诗话》中亦云：“张文懿家有《春江钓叟图》，上有李煜《渔父词》二首。”又，《花草粹编》中此词有题作“题供奉卫贤《春江钓叟图》，并注云：“金索书，不知书名抑书法也。”据夏承焘《唐宋词人年谱·南唐二主年谱》引陶谷《清异录》云：“后主善书，作颤笔樛曲之状，遒劲如寒松霜竹，谓之‘金错刀’。”依王仲闻解，“金索书”即“金错刀书”，也就是李煜的书法。 浪花：《词谱》、《花草粹编》中均作“阆（láng）苑”。阆苑，传说中神仙居住的地方。有意：有本作“有情”。千里雪：一作“千重雪”，此据《全唐诗》。千重，千层，层层叠叠。 桃花：一作“桃李”，此据《全唐诗》。一队春：指桃李盛开，由近及远，好像队列有序一样排列着，言春色正浓，春意盎然。 身：《南唐二主词汇笺》中作“轮”；《诗话总龟》中作“鳞”。一竿身：一根钓竿。 侬（nóng）：我，江南口语。快活：《诗话总龟》中作“世上”。 ▲', poem_appreciation = '这首词是题《春江钓叟图》画之词。据《南唐书·后主纪》载：“文献太子恶其有奇表，后主避祸，惟覃思经籍。”由此，也有人认为，这首词是“后主为情势所迫，沈潜避祸，隐遁世尘并写词表露自己的遁世之心，以释文献太子的疑嫉”（蒲仁、梅龙《南唐二主词全集》辑注），也有道理。词史上最早写《渔父》词的，是唐代的张志和。李煜这首词，继承的就是张志和的“渔父家风”，写渔父的快乐逍遥。从词意上看，此词耽于隐逸、格调不高，当是李煜前期意念消沉的作品。\n\n　　此词开篇入画，将画中意境以言辞写出，以画境言心境。“浪花”成“千里雪”，“桃花”作“一队春”，写春江浪涌，春光明媚，中间嵌以“有意”和“无言”，作者以情见景，借景寓意，心态淡然而出。有酒、有竿、悠然独钓，这种情境虽静寂却清新，所以作者以问作结：“快活如侬有几人？”其叹如赞，表现出作者对隐逸生活的向往和满足。这首词语淡情疏，清丽简约，诗情与画境浑然一体，趣致盎然。\n\n　　这首词题画抒怀，借景寓意，虽然情趣不高，但悠然散淡之意境却清丽不俗，也可视为题画诗词中的精品。', poem_tags = '题画,抒怀,向往,隐逸,生活' WHERE poem_title = '渔父·浪花有意千里雪' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '如今年岁渐长，自己怀有满腔抱负却都未实现，空剩自怜。\n为了迎接新年一直忙碌不停，太阳落山后就意味着新的一年即将到来。', poem_notes = '甲子：年月，年岁。\n元日：一年之第一日。即农历正月初一。\n欹午：太阳偏西。', poem_tags = '节日,过年,感慨' WHERE poem_title = '元日' AND poem_author = '司空图';
UPDATE edu_poem SET poem_translation = '什么地方采白蘩，沼泽旁边沙洲上。采来白蘩做何用？公侯之家祭祀用。\n\n什么地方采白蘩，采来白蘩溪中洗。采来白蘩做何用？公侯之宫祭祀用。\n\n差来专为采白蘩，没日没夜为公侯。差来采蘩人数多，不要轻言回家去。', poem_notes = '⑴于以：问词，往哪儿。一说语助。蘩（fán）：白蒿。生彼泽中，叶似嫩艾，茎或赤或白，根茎可食，古代常用来祭祀。\n⑵沼：沼泽。沚（zhǐ）：《说文》：“小渚曰沚。”这里用为水中的小块陆地之意。\n⑶事：此指祭祀。\n⑷涧：山夹水也。山间流水的小沟。\n⑸宫：大的房子；汉代以后才专指皇宫。\n⑹被（bì）：同“髲”。首饰，取他人之发编结披戴的发饰，相当于今之假发。一说这里是用为施加之意。《尚书·尧典》：“施加允恭克让，光被四表。”僮（tóng）僮：首饰盛貌，一说高而蓬松，又说光洁不坏貌。一说这里用为未成年的僮仆、奴婢之意。《说文》：“僮，未冠也。”\n⑺夙：早。公：公庙。\n⑻祁（qí）祁：形容首饰盛，一说舒迟貌。这里用为众多之意。\n⑼薄：这里用为减少之意。归：归寝。', poem_appreciation = '此诗主人公采蘩者的身份，历来有很多说法。《毛诗序》曰：“采蘩，夫人不失职也。夫人可以奉祭祀，则不失职矣。”是以为此乃贵族夫人自咏之辞，说的是尽职“奉祭祀”之事。朱熹《诗集传》则曰：“南国被文王之化，诸侯夫人能尽诚敬以奉祭祀，而其家人叙其事以美之也。”定主人公为“家人”，这是对毛序的一大修正。不过以为那辛勤“采蘩”、“夙夜在公”的还是“诸侯夫人”，于诗意未免仍有隔膜。\n\n　　诚然，古代贵族夫人也确有主管宗庙祭祀的职责，但并不直接从事采摘、洗煮等劳作。《周礼·春官宗伯》称：“世妇，掌女宫之宿戒，及祭祀，比其具。”贾公彦疏谓“女宫”乃指有罪“从坐”、“没入县官”而供“役使”之女，又称“刑女”。凡宫中祭祀涉及的“濯摡及粢盛之爨”，均由“女宫”担任。而此诗中的主人公，既称“夙夜在公”，又直指其所忙碌的地方为“公侯之宫”，则其口吻显示的身份，自是供“役使”的“女宫”之类无疑。因此，把这首诗定为是一首反映宫女们为祭祀而劳作的诗，更为合理。\n\n　　诗之开篇，出现的正是这样一些忙于“采蘩”的女宫人。她们往来于池沼、山涧之间，采够了祭祀所需的白蒿，就急急忙忙送去“公侯之宫”。诗中采用的是短促的问答之语：“哪里采的白蒿？”“水洲中、池塘边。”“采来作什么？”“公侯之家祭祀用”答问之简洁，显出采蘩之女劳作之繁忙，似乎只在往来的路途中，对询问者的匆匆一语之答。答过前一问，女宫人的身影早已过去；再追上后一问，那“公侯之事”的应答已传自远处。这便是首章透露的氛圈。再加上第二章的复叠，便愈加显得忙碌无暇，简直可以从中读出穿梭而过的女宫人的匆匆身影，读出那从池沼、山涧飘来，又急促飘往“公侯之宫”的匆匆步履。\n\n　　第三章是一个跳跃，从繁忙的野外采摘，跳向了忙碌的宗庙供祭。据上引《周礼》“世妇”注疏，在祭祀“前三日”，女宫人便得夜夜“宿”于宫中，以从事洗涤祭器、蒸煮“粢盛”等杂务。由于干的是供祭事务，还得打扮得漂漂亮亮，戴上光洁黑亮的发饰。这样一种“夙夜在公”的劳作，把女宫人折腾得不成样子。诗中妙在不作铺陈，只从她们发饰“僮僮”（光洁）向“祁祁”（松散）的变化上着墨，便入木三分地画下了女宫人劳累操作而无暇自顾的情状。那曳着松散的发辫行走在回家路上的女宫人，此刻带几分庆幸、几分辛酸，似乎已不必再加细辨——“薄言还归”的结句，已化作长长的喟叹之声，对此作了无言的回答。\n\n　　如此看来，以《采蘩》为诸侯夫人自咏，固属附会；而认其为“家人”赞美夫人之作，亦属穿凿。穿行于诗中的，其实是夙夜劳瘁的女宫人而已：短促的同答，透露着她们为贵族祭祀采蘩的苦辛；发饰的变化，记录着她们“夙夜在公”的悲凉。古代的祭祀排场，原本就为鬼神“降福”贵族而设，卑贱的下人除了付出劳辛，没有幸福可言。\n\n　　还有一种说法，认为这是一首为封建王公贵族服劳役的山歌，是奴仆们在服劳役休息时闲唱的。山歌中第一、二段是互相问答，问答内容为采蘩的地点和目的。第三段则是奴仆们不满的牢骚怨言，因为王公贵族的祭祀，连小小的僮仆也要服劳役，更不要说是成年男女了。歌中所表现出的不满和无奈，在最后一句里发挥得淋漓尽致。人们夙夜在公侯家，昼夜服役，连想回家的话都不敢说，表现出封建王公贵族的残酷。为封建王公贵族服劳役，这本是召南地区的一种风俗习惯，但是，在以往的服劳役中，没有哪一次像这次一样劳累，所以这次的服劳役便以山歌的形式留传下来了。\n\n　　此诗为三章叠咏，而其主要特色在于前两章以一问一答出之。末章写采蘩者的仪容，用“僮僮”、“祁祁”，言语虽简，而人物之仪态神情可现。而一问一答的形式，明显地受了原始民歌的影响。', poem_tags = '诗经,写人,女子' WHERE poem_title = '采蘩' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '其一\n从西面登上香炉峰，向南望见瀑布高挂在山前。\n水流直下达三百丈，沿着山谷奔涌前行几十里。\n速度快如风驰电掣，隐约之中宛如有白虹腾空。\n乍以为是银河从天上落下，弥漫飘洒在半空中。\n仰观瀑布那气势真雄奇啊，这是神灵造化之功！\n再大的海风也吹不断，江上月光却能直透其中。\n水流在空中任意飞溅，冲刷着两侧青色的石壁。\n飞腾的水珠散发彩色霞光，水沫在巨石上沸腾。\n我本来就最爱游赏名山，面对此景心胸更宽广。\n不必像服琼浆一样成仙，此水已足以荡涤尘俗。\n遁世归隐本是我夙愿，只想久居此地永辞人间。\n其二\n香炉峰在阳光的照射下生起紫色烟霞，远远望见瀑布似白色绢绸悬挂在山前。\n高崖上飞腾直落的瀑布好像有几千尺，让人恍惚以为银河从天上泻落到人间。', poem_notes = '庐山：又名匡山，位于今江西省九江市北部的鄱阳湖盆地，在庐山区境内，耸立于鄱阳湖、长江之滨，江湖水气郁结，云海弥漫，多蝇岩、峭壁、清泉、飞瀑，为著名游览胜地。\n香炉峰：庐山北部名峰。水气郁结峰顶，云雾弥漫如香烟缭绕，故名。南见：一作“南望”。\n三百丈：一作“三千匹”。壑（hè）：坑谷。“喷壑”句：意谓瀑布喷射山谷，一泻数十里。\n歘（xū）：歘忽，火光一闪的样子。飞电：空中闪电，一作“飞练”。隐若：一作“宛若”。白虹：一种出现在雾上的淡白色的虹。“欻如”二句：意谓快如闪电而来，隐似白虹而起。\n河汉：银河，又称天河。一作“银河”。“半洒”句：一作“半泻金潭里”。\n造化：大自然。\n江月：一作“山月”。“江月”句：意谓瀑布在江月的映照下，显得更加清澈。\n潈（zōng）：众水汇在一起。“空中”二句：意谓瀑布在奔流过程中所激起的水花，四处飞溅，冲刷着左右青色的山壁。\n穹（qióng）石：高大的石头。\n乐：爱好。乐名山：一作“游名山”。益：更加。闲：宽广的意思。\n无论：不必说。漱：漱洗。琼液：传说中仙人的饮料。此指山中清泉。还得：但得。一作“且得”。尘颜：沾满风尘的脸。洗尘颜：喻指洗除在尘世中所沾染的污垢。\n谐：谐和。宿：旧。宿所好：素来的爱好。“且谐”二句：一作“集谱宿所好，永不归人间”，又一作“爱此肠欲断，不能归人间”。\n香炉：指香炉峰。紫烟：指日光透过云雾，远望如紫色的烟云。孟浩然《彭蠡湖中望庐山》：“香炉初上日，瀑布喷成虹。”“日照”二句：一作“庐山上与星斗连，日照香炉生紫烟”。\n遥看：从远处看。挂：悬挂。前川：一作“长川”。川：河流，这里指瀑布。\n直：笔直。三千尺：形容山高。这里是夸张的说法，不是实指。\n疑：怀疑。银河：古人指银河系构成的带状星群。九天：一作“半天”。古人认为天有九重，九天是天的最高层，九重天，即天空最高处。此句极言瀑布落差之大。', poem_appreciation = '这两首诗体裁不一，一首五古，一首七绝，内容也有部分重复。第二首诗流传很广，曾被选入小学语文教科书，题作“望庐山瀑布”。\n\n　　第一首诗是五言古诗。此诗共换四次韵，前八句为一韵；中间八句每四句各一韵；末六句为一韵。诗意也可按韵分为四层。前三层基本上是摹写瀑布的壮观奇姿，属景语；只有末一层言志抒怀，属情语。前三层也各有重点：第一层从正面描写瀑布的主体实景；第二层从虚处更深更细地描绘瀑布；第三层，从上下四旁来烘托瀑布之动态。最后一层先擒后纵，收束得自然平易。首二句交待“望庐山瀑布水”的立足点和所“望”的方向。接着十四句用各种形象从不同角度形容瀑布的壮伟气势和诗人的赞叹。所谓“挂流三百丈”，“初惊河汉落”，亦即第二首的“飞流直下三干尺，疑是银河落九天”之意，但不如后者的简练和生动。末六句抒写诗人的志趣和愿望。从这首诗中，可以看出李白思想中孤傲遁世的一面。\n\n　　五言古诗讲究兴寄，直抒胸臆，质朴真切，气象浑成。诗人的感情起伏与诗的节奏同步，由此形成感染人的力量。李白善于乐府和歌行，常以他横空出世，骏马绝尘的非凡才力，将乐府、歌行作为表达他飞腾的想象，纵横的才思，不羁的思想，奔放的情感之最合适的艺术形式，这些诗写得神识超迈，飘然而来，忽然而去，不屑于雕章琢句，亦不劳劳于镂心刻骨，自有天马行空，不可羁勒之势。这首五古正是如此。李白把庐山瀑布写得壮美阔大。诗人寄情于山水，从“西登香炉峰”到“流沫沸穹石”都是写景，而最后三句是抒情之句。“海风吹不断，江月照江空”中的“空”字更说明诗人寻求的是一种“闲”情，也体现李白的飘逸之风。在庐山美景之下，诗人借景直抒胸臆，语言质朴真切，但仍能感染读者。第一首虽是古诗，其中却有不少对仗。古今读者多谓此首不如第二首绝句写得好，但也有不少人指出此诗自有妙句。如《苕溪渔隐丛话后集》卷四：“然余谓太白前篇古诗云：‘海风吹不断，江月照还空’。磊落清壮，语简而意尽，优于绝句多矣。”葛立方《韵语阳秋》卷十二：“以余观之，银河一派，犹涉比类，未若白前篇云：‘海风吹不断，江月照还空’。凿空道出，为可喜也。”韦居安《梅硐诗话》亦谓此二句“语简意足，优于绝句，真古今绝唱”，并认为“非历览此景，不足以见诗之妙”。\n\n　　第二首诗是七言绝句。运用了比喻夸张的手法。此诗中的香炉，即第一首诗开头提到的香炉峰，“在庐山西北，其峰尖圆，烟云聚散，如博山香炉之状”（乐史《太平寰宇记》）。可是，到了诗人李白的笔下，便成了另一番景象：一座顶天立地的香炉，冉冉地升起了团团白烟，缥缈于青山蓝天之间，在红日的照射下化成一片紫色的云霞。这不仅把香炉峰渲染得更美，而且富有浪漫主义色彩，为不寻常的瀑布创造了不寻常的背景。接着诗人才把视线移向山壁上的瀑布。“遥看瀑布挂前川”，前四字是点题。“挂前川”，这是“望”的第一眼形象，瀑布像是一条巨大的白练高挂于山川之间。“挂”字很妙，它化动为静，惟妙惟肖地表现出倾泻的瀑布在“遥看”中的形象。第一首诗说，“壮哉造化功！”正是这“造化”才能将这巨物“挂”起来，所以这“挂”字也包含着诗人对大自然的神奇伟力的赞颂。第三句又极写瀑布的动态。“飞流直下三千尺”，一笔挥洒，字字铿锵有力。“飞”字，把瀑布喷涌而出的景象描绘得极为生动；“直下”，既写出山之高峻陡峭，又可以见出水流之急，那高空直落，势不可挡之状如在眼前。然而，诗人犹嫌未足，接着又写上一句“疑是银河落九天”，真是想落天外，惊人魂魄。“疑是”值得细味，诗人明明说得恍恍惚惚，而读者也明知不是，但是又都觉得只有这样写，才更为生动、逼真，其奥妙就在于诗人前面的描写中已经孕育了这一形象。巍巍香炉峰藏在云烟雾霭之中，遥望瀑布就如从云端飞流直下，临空而落，这就自然地联想到像是一条银河从天而降。可见，“疑是银河落九天”这一比喻，虽是奇特，但在诗中并不是凭空而来，而是在形象的刻画中自然地生发出来的。它夸张而又自然，新奇而又真切，从而振起全篇，使得整个形象变得更为丰富多彩，雄奇瑰丽，既给人留下了深刻的印象，又给人以想象的余地，显示出李白那种“万里一泻，末势犹壮”的艺术风格。\n\n　　宋人魏庆之说：“七言诗第五字要响。……所谓响者，致力处也。”（《诗人玉屑》）这个看法在这首诗里似乎特别有说服力。比如一个“生”字，不仅把香炉峰写“活”了，也隐隐地把山间的烟云冉冉上升、袅袅浮游的景象表现出来了。“挂”字前面已经提到了，那个“落”字也很精彩，它活画出高空突兀、巨流倾泻的磅礴气势。很难设想换掉这三个字，这首诗将会变成什么样子。\n\n　　中唐诗人徐凝也写了一首《庐山瀑布》。诗云：“虚空落泉千仞直，雷奔入江不暂息。千古长如白练飞，一条界破青山色。”场景虽也不小，但还是给人局促之感，原因大概是它转来转去都是瀑布，瀑布，显得很实，很板，虽是小诗，却颇有点大赋的气味。比起李白那种入乎其内，出乎其外，有形有神，奔放空灵，相去实在甚远。苏轼说：“帝遣银河一派垂，古来唯有谪仙词。飞流溅沫知多少，不与徐凝洗恶诗。”（《戏徐凝瀑布诗》）话虽不无过激之处，然其基本倾向还是正确的，表现了苏轼不仅是一位著名的诗人，也是一位颇有见地的鉴赏家。\n\n　　五言古诗因篇幅无限制，所以诗人任意挥洒，写“海风”，写“江月”，写“穹石”，写得大起大落，大开大阖，转折如意，挥洒自如，一气呵成。七言绝句因篇幅较小，诗人用夸张的比喻把景物升腾到更高的境界，达到写瀑布的极致，极为夸张，但又清新自然，浅显生动，同时具有动荡开阔的气势，飞动流走的章法，跳跃腾挪，纵横捭阖，亦有歌行的气势和特点。\n\n　　两首诗都是李白之作，同是写庐山瀑布之景，李白一生好入名山游在庐山秀丽的山水之中，更显诗人标名之灵气。其想象丰富，奇思纵横，气势恢宏，感情奔放，似江河奔腾，又自然清新，似云卷风清，其诗歌的审美特征是自然美、率真美和无拘无束的自由美。这两首诗歌都具有这样的审美特征。', poem_tags = '小学古诗,山水,组诗' WHERE poem_title = '望庐山瀑布水二首' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '玉炉散发着炉香烟，红色的蜡烛滴着烛泪，摇曳的光影映照出华丽屋宇的凄迷。她的蛾眉颜色已褪，鬓发也已零乱，漫漫长夜无法安眠，只觉枕被一片寒凉。 \n窗外的梧桐树，正淋着三更的冷雨，也不管屋内的她正为别离伤心。一滴一滴的雨点，正凄厉地敲打着一叶一叶的梧桐，滴落在无人的石阶上，一直到天明。', poem_notes = '更漏子：词牌名。它类似渊源于欧洲中世纪骑士文学的《小夜曲》，歌唱的是午夜情事。\n画堂：华丽的内室。 \n鬓（bìn）云：鬓发如云。 \n衾（qīn）：被子。 \n梧桐：落叶乔木，古人以为是凤凰栖止之木。\n不道：不管、不理会的意思。', poem_appreciation = '温庭筠共写过六首内容相仿的《更漏子》。这首《更漏子》，借“更漏”夜景咏妇女相思情事，词从夜晚写到天明。\n\n　　开头三个字，表面看是景语，不像后来李清照《醉花阴·重阳》的“薄雾浓云愁永昼，瑞脑消金兽”含有以炉烟袅袅来表示愁思无限的意思。次句“红蜡泪”就不同了：夜间燃烛，用以照明，但多了一个“泪”字，便含有了人的感情。说“玉炉”，既见其精美，又见其色洁；“红蜡”则透出色泽的艳丽而撩人情思，而闺中的寂寞也隐隐流露出来了。“画堂”，写居室之美，与“玉炉”、“红蜡”相映衬。这句紧承上句，说红蜡所映照是画堂中人的秋思。“秋思”，是一种看不见、摸不着、深藏于人心中的情愫，红蜡是不能“照”到的，可是作者却执拗地强调“偏照”。“偏照”者，非照不可也。这一来，将室内的华美陈设与人的感情，巧妙地联系起来了。此刻，在这美丽的画堂中，冷清寂静，只有玉炉之香，红蜡之泪，与女主人公相伴，不管它们是有意、无意，但在她看来，却是“偏照”。至此，是蜡在流泪，抑或人在流泪，浑融一体，更反衬女主人公的“秋思”之深。概言之，第一句主要是衬景，二句景中含情，三句感情色彩强烈，女主人公的愁肠百结，呼之而出了。陈匪石云：“词固言情之作，然但以情言，薄矣。必须融情入景，由景见情。”（《旧时月色斋词谭》）这里“融情入景”是逐步深入的，至“偏照”始喷涌而出。\n\n　　“眉翠薄，鬓云残”，两句写人。以翠黛描眉，见其眉之美。鬓云，是形容美发如云，可知其人之美。但紧接着用了一个“薄”字，一个“残”字，景况便完全不同了。“薄”字形容眉黛褪色，“残”字描绘鬓发不整。这两个字反映出她辗转反侧、无法入睡的情态，不仅写外貌，也同时写出了她内心难言的苦闷。“夜长衾枕寒”，继续写思妇独处无眠的感受，它不仅点明了时间：长夜漫漫；写出了人的感觉：衾枕生寒，如李清照怀念外出丈夫时的“半夜凉初透”。由此可知上面的一切景物，都是夜长不寐之人目之所见，身之所感。这些景物如粒粒珍珠，用“秋思”这条线把它们串了起来。\n\n　　上阕写画堂中人所见，下阕从室内转到室外，写人的所闻。秋夜三更冷雨，点点滴滴在梧桐树上，这离情之苦没有人可以理解。它与“偏照画堂秋思”呼应，可见“秋思”即是离情。下面再作具体描述：“一叶叶，一声声，空阶滴到明。”潇潇秋雨不理会闺中少妇深夜怀人的苦情，只管让雨珠洒在一张张梧桐叶上，滴落在窗外的石阶上，一直滴到天明，还没有休止。秋雨连绵不停，正如她的离情连绵无尽。李清照《声声慢》：“梧桐更兼细雨，到黄昏点点滴滴，这次第，怎一个愁字了得。”由玉炉生香、红蜡滴泪的傍晚，到闻“三更雨”，再看“滴到明”，女主人公的彻夜不眠，当然更非“一个愁字了得”了。\n\n　　这首词通首写画堂人的“秋思”“离情”，上阕的意境，在《花间集》中颇常见，下阕的写法则独辟蹊径。陈廷焯说“梧桐树”数语，用笔较快，而意味无上文章之厚。其实，“用笔快”如果一泻千里，言尽意止，固然不好；但这里并非如此。谭献说“梧桐树”以下似直下语，正从“夜长”逗出，亦书家“无垂不缩”之法。书法中的所谓“垂”，指竖笔；在作竖笔时，最后须往上逆缩一下，使字体不失其气势。比之于词，即是看似直率，纵笔而下，但须顿挫深厚，跌宕而有情致，似直而实纡也。《更漏子》下阕，写梧桐夜语，正有此特色。这里直接写雨声，间接写思妇，亦是“夜长衾枕寒”的进一步说明；但整夜不眠却仍用暗示，始终未曾点破，这就是直致中有含蓄之处。所以说此词深得书家 “无垂不缩”之法，即是指它“直说”中仍适当地配合以“含蓄”，否则便会使人有一览无余、索然寡味之感了。宋人聂胜琼《鹧鸪天·别情》词有句云：“枕前泪共阶前雨，隔个窗儿滴到明。”当是从此词脱胎而来，写得语浅情深；但全词并不像此词上下片浓淡相间，又缺乏转折变化，相较之下，韵味亦是略逊一筹。', poem_tags = '女子,孤独,相思' WHERE poem_title = '更漏子·玉炉香' AND poem_author = '温庭筠';
UPDATE edu_poem SET poem_translation = '在江汉就曾经一起作客，每次相逢都是尽醉而还。\n离别后如浮云飘流不定，岁月如流水一晃过十年。\n今日相见虽然欢笑如旧，可惜人已苍老鬓发斑斑。\n为何我不与故人同归去？因为淮上有秀美的秋山。', poem_notes = '淮上：淮水边。梁州：指兴元府（今陕西汉中市）。\n流水：喻岁月如流，又暗合江汉。\n淮上有秋山：言淮上风光可恋，伸足上“不归去”之意。', poem_appreciation = '这首诗描写诗人在淮上（今江苏淮阴一带）喜遇梁州故人的情况和感慨。他和这位老朋友，十年前在梁州江汉一带有过交往。诗题曰“喜会”故人，诗中表现的却是“此日相逢思旧日，一杯成喜亦成悲”那样一种悲喜交集的感情。　\n\n　　诗的开头，写诗人昔日在江汉作客期间与故人相逢时的乐事，概括了以前的交谊。那时他们经常欢聚痛饮，扶醉而归。诗人写这段往事，仿佛是试图从甜蜜的回忆中得到慰藉，然而其结果反而引起岁月蹉跎的悲伤。颔联一跌，直接抒发十年阔别的伤感。颈联的出句又回到诗题，写这次相会的“欢笑”之态。久别重逢，确有喜的一面。他们也像十年前那样，有痛饮之事。然而这喜悦，只能说是表面的，或者说是暂时的，所以对句又将笔宕开，写两鬓萧疏。十年的漂泊生涯，使得人老了。这一副衰老的形象，不言悲而悲情溢于言表，漂泊之感也就尽在不言之中。一喜一悲，笔法跌宕；一正一反，交互成文。末联以反诘作转，以景色作结。为何不归去，原因是“淮上有秋山”。诗人《登楼》诗云：“坐厌淮南守，秋山红树多。”秋光中的满山红树，正是诗人耽玩留恋之处。这个结尾给人留下了回味的余地。\n\n　　绘画艺术中有所谓“密不通风，疏可走马”之说。诗歌的表现同样有疏密的问题，有些东西不是表现的重点，就应从略，使之疏朗；有些东西是表现的中心，就应详写，使之细密。疏密相间，详略适宜，才能突出主体。这首诗所表现的是两人十年阔别的重逢，可写的东西很多，如果把十年的琐事絮絮叨叨地说来，不注意疏密详略，便分不清主次轻重，也就不成其为诗了。这就需要剪裁。诗的首联概括了以前的交谊；颈联和末联抓住久别重逢的情景作为重点和主体，详加描写，写出了今日的相聚、痛饮和欢笑，写出了环境、形貌和心思，表现得很细密。颔联“浮云一别后，流水十年间”，表现的时间最长。表现的空间最宽，表现的人事最杂。这里却只用了十个字，便把这一切表现出来了。这两句用的是流水对，自然流畅，洗练概括。别后人世沧桑，千种风情，不知从何说起，诗人只在“一别”、“十年”之前冠以“浮云”、“流水”，便表现出来了。意境空灵，真是“疏可走马”。“浮云”、“流水”暗用汉代苏武李陵河梁送别诗意。李陵《与苏武诗三首》有“仰视浮云驰，奄忽互相逾。风波一失所，各在天一隅”，苏武《诗四首》有“俯观江汉流，仰视浮云翔”，其后常以“浮云”表示漂泊不定，变幻无常，以“流水”表示岁月如流，年华易逝。诗中“浮云”、“流水”不是写实，都是虚拟的景物，借以抒发诗人的主观感情，表现一别十年的感伤，由此可见诗人的剪裁功夫。', poem_tags = '唐诗三百首,友情' WHERE poem_title = '淮上喜会梁川故人 / 淮上喜会梁州故人' AND poem_author = '韦应物';
UPDATE edu_poem SET poem_translation = '清澈的川水环绕一片草木，驾车马徐徐而去从容悠闲。\n流水好像对我充满了情意，傍晚的鸟儿随我一同回还。\n荒凉的城池靠着古老渡口，落日的余晖洒满金色秋山。\n在遥远又高峻的嵩山脚下，闭上门谢绝世俗度过晚年。', poem_notes = '嵩山：五岳之一，称中岳，地处河南省登封市西北面。\n清川：清清的流水，当指伊水及其支流。清：一作“晴”。川：河川。带：围绕，映带。薄：草木丛生之地，草木交错曰薄。\n去：行走。闲闲：从容自得的样子。\n暮禽：傍晚的鸟儿。禽：一作“云”。相与：相互作伴。\n荒城：按嵩山附近如登封等县，屡有兴废，荒城当为废县。临：当着。古渡：指古时的渡口遗址。\n迢递：遥远的样子。递：形容遥远。嵩高：嵩山别称嵩高山。\n且：将要。闭关：佛家闭门静修。这里有闭户不与人来往之意。闭：一作“掩”。', poem_appreciation = '这首诗写作者辞官归隐途中所见的景色和心情。嵩山，古称“中岳”，在今河南登封县北。\n\n　　“清川带长薄，车马去闲闲。”首联描写归隐出发时的情景，扣题目中的“归”字。清澈的河川环绕着一片长长的草木丛生的草泽地，离归的车马缓缓前进，显得那样从容不迫。这里所写望中景色和车马动态，都反映出诗人归山出发时一种安详闲适的心境。\n\n　　中间四句进一步描摹归隐路途中的景色。第三句“流水如有意”承“清川”，第四句“暮禽相与还”承“长薄”，这两句又由“车马去闲闲”直接发展而来。这里移情及物，把“流水”和“暮禽”都拟人化了，仿佛它们也富有人的感情：河川的清水在汩汩流淌，傍晚的鸟儿飞回林木茂盛的长薄中去栖息，它们好像在和诗人结伴而归。两句表面上是写“水”和“鸟”有情，其实还是写作者自己有情：一是体现诗人归山开始时悠然自得的心情，二是寓有作者的寄托。“流水”句比喻一去不返的意思，表示自己归隐的坚决态度；“暮禽”句包含“鸟倦飞而知还”之意，流露出自己退隐的原因是对现实政治的失望厌倦。所以此联也不是泛泛的写景，而是景中有情，言外有意的。\n\n　　“荒城临古渡，落日满秋山。”这一联运用的还是寓情于景的手法。两句十个字，写了四种景物：荒城、古渡、落日、秋山，构成了一幅具有季节、时间、地点特征而又色彩鲜明的图画：荒凉的城池临靠着古老的渡口，落日的余晖洒满了萧飒的秋山。这是傍晚野外的秋景图，是诗人在归隐途中所看到的充满黯淡凄凉色彩的景物，对此加以渲染，正反映了诗人感情上的波折变化，衬托出作者越接近归隐地就越发感到凄清的心境。\n\n　　“迢递嵩高下，归来且闭关。”“迢递”是形容山高远的样子，对山势作了简练而又形象的描写。“嵩高”，即嵩山。前句交待归隐的地点，点出题目中的“嵩山”二字。“归来”，写明归山过程的终结，点出题目中的“归”字。“闭关”，不仅指关门的动作，而且含有闭门谢客的意思。后句写归隐后的心情，表示要与世隔绝，不再过问社会人事，最终点明辞官归隐的宗旨，这时感情又趋向冲淡平和。\n\n　　整首诗写得很有层次。随着诗人的笔端，既可领略归山途中的景色移换，也可隐约触摸到作者感情的细微变化：由安详从容，到凄清悲苦，再到恬静澹泊。说明作者对辞官归隐既有闲适自得，积极向往的一面，也有愤激不平，无可奈何而求之的一面。诗人随意写来，不加雕琢，可是写得真切生动，含蓄隽永，不见斧凿的痕迹，却又有精巧蕴藉之妙。方回说：“不求工而未尝不工。”正道出了这首诗不工而工，恬淡清新的特点。', poem_tags = '唐诗三百首,山水,写景,抒情' WHERE poem_title = '归嵩山作' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '夕阳西下，酒家里好像也显得宁静闲适，只有几只船儿还未曾靠岸。空气里弥漫着花香，连水好像也变得香了，茅舍也进入了夜色之中。断桥头上卖鱼的人也散了。', poem_notes = '浦：水边。\n酒旆（pèi）：酒店的旗帘，酒家悬于门前以招徕顾客。\n两三航：两三只船。\n航：船\n着岸：靠岸', poem_tags = '高中古诗,写景,渔人' WHERE poem_title = '寿阳曲·远浦帆归' AND poem_author = '马致远';
UPDATE edu_poem SET poem_translation = '李白之前本来就有明月，只有李白诗歌才能题写。\n如今李白已经离开人世仙去，明月在天上几回圆来几回缺？\n今天的人仍在吟颂李白的诗，明月也还像李白生前的那时。\n我学着李白对着明月饮酒，月亮和李白又怎么能得知？\n李太白既能作诗又能喝酒，我如今也喝百杯作诗千首。\n我虽羞愧没有李白的才华，却料想明月不会嫌我陋丑。\n我也不曾登上天子船，我也不曾到过长安眠。\n住在苏州城外一间茅屋里，无数桃花盛开月光撒满天。', poem_notes = '把酒：端着酒杯。\n说：指描写月亮。\n仙去：对人死的委婉说法。\n李白诗：指李白的《把酒问月》一诗。\n安：怎么。\n料应：即应该料想到……。\n天子船：指杜甫《饮中八仙歌》中咏李白的诗句：“天子呼来不上船”句。\n长安眠：指杜甫《饮中八仙歌》中咏李白的诗句：“长安街上酒家眠”句。\n姑苏：苏州的别称。', poem_appreciation = '这首诗通过歌咏李白并引以自况。“把酒对月”这个题目本是李白所作的一首诗。李白一生爱月，所咏明月诸诗脍炙人口。这首诗一开始就以兀傲的口气，推倒一切月诗，独尊李白：“李白前时原有月，惟有李白诗能说。”有这样的气概，方许歌咏李白。这里推崇的“李白诗”，主要是指《把酒问月》这首诗。而作者唐寅这首诗，主要就受李白诗篇句调的影响，但他在诗中把李白加进去与明月反复对举，又是李白本人不能写的光景。“李白如今已仙去，月在青天几圆缺？”后句是李白式的，但配合前句，则是作者新意。月固有阴晴圆缺，但卒莫消长，而诗仙却不能复生。作者接着说其实这并不遗憾，因为“今人犹歌李白诗，明月还如李白时”，这句侧面说李白和明月一样永存。这调门是李白的，新意是作者的。\n\n　　这首诗最好的还是诗中在李白与明月之间，加入了“我”。如果失去了这个“我”，也就失去了李白精神。“我学李白对明月，月与李白安能知?”李白固不能知，但月能知。于是作者引李白自况：“李白能诗复能酒，我今百杯复千首。”“百杯复千首”就是“能诗复能酒”，也就是杜甫所说的“一斗诗百篇”。敢于自比李白，这也是李白风度，有胆量有信心，并非等同于狂妄，以下一转一合最为妥帖：“我愧虽无李白才，料应月不嫌我丑。“前句妙在自知之明；后句妙在不卑不亢，联想到辛弃疾诗句：“我爱青山多妩媚，料青山爱我应如是。情与貌，两相似。”这种有分寸的自负之语，读者反而不会感到反感而会容易接受。好比谢灵运说：“天下才有一石，曹子建独占八斗，我得一斗，天下共分一斗。”诗人是说，对李白我佩服得五体投地，而对他人则不多让。语意皆妙。\n\n　　最后作者讲出了他和李白同而不同的一点：“我也不登天子船，我也不上长安眠。”诗句化杜甫《饮中八仙歌》：“李白一斗诗百篇，长安市上酒家眠。天子呼来不上船，自称臣是酒中仙。”这里是说，我虽然没有李白得到皇帝征诏的经历，但也有他那种豪放不羁的禀性，“不上长安”倒也乐得：“姑苏城外一茅屋，万树桃花月满天。”这个茅屋就是作者在苏州建的桃花庵，作者晚年经常在桃花庵饮酒自乐。\n\n　　这首诗倜傥不群、超尘脱俗地追求自由反抗权势的精神，和豪放飘逸的句调风格都酷似李白。以其人之风格还咏其人，妙在古今同调。\n\n　　作者在这首诗中，用“把酒对月”的举动，处处将自己和李白相联系、相对比，用“月”、“诗”、“酒”为诗思的契机，并贯穿全篇，抒写了李白敢于蔑视权贵的品质，表明了作者学习李白不求功名利禄的愿望和蔑视权贵的态度。', poem_tags = '写人,对月,抒怀' WHERE poem_title = '把酒对月歌' AND poem_author = '唐寅';
UPDATE edu_poem SET poem_translation = '襄王和宋玉出游到云梦大泽的岸边，让宋玉向他描述高唐所见的事情。这天晚上宋玉就寝时，梦到与神女相遇，神女的容貌非常美丽，令宋玉十分惊异。第二天，宋玉告诉了楚襄王。楚王问：“你都梦到了什么？”宋玉回答说：“黄昏以后，我觉得精神恍惚，好像有什么喜事来临。搅得我心身不安，不知道什么缘故。正迷迷糊糊的时候，忽然觉得似曾相识的人到来。睁眼一看是一个女人，相貌非常奇特。睡着的时候梦见了她，醒来的时候她又不见了。闹得我心里好不痛快，失落的好像迷失了方向。这是我尽量定下心来，才又把梦延续下去。”大王问：“她长得什么样子呢？”宋玉说：“她那如花似玉的容姿，简直是无可挑剔；她那丰盈妩媚的仪态也无法寻根究底。上古时代完全不曾有，当今人间根本找不见；她那珍奇宝石般的风采，最好的赞美还会有疏漏。她刚开出现的时候，灿烂的像旭日初升照亮屋梁。当她走进一些的时候，皎洁的像明月洒下的光芒。只一会功夫，她的美妙风采我已领略不尽。时而亮丽的如同鲜花，时而柔和的好似美玉。五种颜色一起散发，我无法一一具体描绘。想要仔细观看，却被她的光采照得目晕眼花。她那华丽的服饰，就像上等丝绸织绘出精美的图案。绝妙的服饰无论在哪里都光彩照人。她挥动着身上的锈衣，那衣裙非常合身，既不显瘦，也不见长。她迈着娇娆的步子走进明亮的殿堂。忽而又改变姿态，宛如游龙乘云飞翔。她身穿的丽服盛饰，非常合适的将她的侗体包裹。她身上沐浴过兰草的雨露，时时散发着宜人的芳香。她的性情温柔娴雅，很适合侍奉在君王身旁。她懂得长幼尊卑的礼仪，还会用善解人意的花语调节情绪。”大王说：“这么美妙诱人的神女啊！你就尝试着为我描摹吧。”宋玉说：“好的，好的。”\n\n　　要说神女姣艳的美丽啊，那真是得天独厚的美质。身披着水草般的衣裙，就像张开翡翠色的翅膀。那相貌是举世无双，那美妙乃人间极品。毛嫱见了她举袖遮面，自知无法比量；西施与她照面双手捂脸，怎敢和她争艳。近处瞧已叫人神魂颠倒，远处望更让人魂牵梦绕。她还有非凡的气质风度，分明是陪伴君王的命相。看见她可是君王大饱眼福，谁会让她从眼前悄悄溜过？心想和她私下结为相好，倾慕她的心情无法估量。只可惜和她交往太少，不敢冒昧地倾吐衷肠。心愿别的人莫要和她相见，那会把她的体态和我分享。神女的美丽是那么丰盛，怎可能一下子说完道光？她的体态丰满庄重，她的容颜温润如玉。她的美眸炯炯放光，明亮的眼珠流转有神。弯弯的细眉象蚕蛾飞扬，鲜亮的红唇似点过朱砂。娇娆的身段富有弹性，娴雅的神态安闲无躁。既能在幽静处表现文静，又能在众人面前翩翩起舞。高唐殿这宽敞的地方正合她意，可任她尽情欢舞或是信步徜徉。\n\n　　裙纱飘动，她轻盈绰约地走来，纱裙拂阶，发出玉佩的响声，她望着我的门帘良久注视，灼热的目光象流波将要奔涌。她抬起衣袖整理衣襟，站在那里犹豫不决。表情文静又和悦淑善，秉性安详而又不烦躁。时而露出微微激动的面容，似乎她的渴望并未如愿。情在眼前却心向久远，想要走来忽而又回转。眼看她揭起我的床帐将要款待，我正想尽情地倾吐诚挚的衷肠。她却怀着坚贞洁清守身，突然表现出对我实难相从。她委婉地把我规劝一番，高雅的谈吐如嗅兰草。相互交流着彼此的爱恋，心里充满激昂和欢乐的情绪。独享着精神欢乐却未能交合，我又无端的感到孤独惆怅。分不清她是否答应相好，忍不住发出长长的叹息。她却怒而不发庄重矜持，一副不可触犯的表情。\n\n　　这时她摇动佩饰转过身去，敲响车子上的玉铃，整理好自己的衣装，收敛起先前的容颜，回头看身后的女乐师，吩咐侍从们起驾。这段欢情还未交合，神女就要告辞离去。她有意和我拉开距离，不让我上前与她亲近。在将要离去还未上车的时候，中途她好像又回过头来，情意脉脉地瞥了我一眼，传送着依依不舍的哀伤。她那复杂有矛盾的情态，我实在难以尽数细说。决意离去而又情意未绝，她心里有多少痛苦的反反复复啊。临走顾不上礼数小节，更来不及把话说完。\n\n　　我的心仍然沉湎在分手的时刻，神女啊，你走得太匆忙了！我是多么的痛苦忧伤，身体摇晃着失去依靠，只觉得天昏地又暗，不知道自己处在什么地方。我这种失落的独自情怀，说给谁可以理解呢？伤感失意之下泪流不止，苦苦等待直到天明。▲', poem_tags = '辞赋精选,写人,爱情,神话' WHERE poem_title = '神女赋' AND poem_author = '宋玉';
UPDATE edu_poem SET poem_translation = '山路被白云隔断在尘境之外，春光宛若清清溪流源远流长。\n不时有落花随溪水飘流而至，远远地就可闻到水中的芳香。\n闲静的荆门面对蜿蜒的山路，柳荫深处蕴藏着读书的斋堂。\n每当太阳光穿过柳荫的幽境，清幽的光辉便洒满我的衣裳。', poem_notes = '阙题：即缺题。“阙”通“缺”。因此诗原题在流传过程中遗失，后人在编诗时以“阙题”为名。\n道由白云尽：指山路在白云尽处，也即在尘境之外。道：道路。由：因为。\n春：春意，即诗中所说的花柳。\n闲门：指门前清净，环境清幽，俗客不至的门。\n深柳：即茂密的柳树。\n幽映：指“深柳”在阳光映照下的浓荫。每：每当。', poem_appreciation = '这首诗句句写景，画意诗情，佳句盈篇，可推为刘眘虚的代表作。诗描写深山中一座别墅及其幽美环境。一开头就写进入深山的情景。“道由白云尽”，是说通向别墅的路是从白云尽处开始的，可见这里地势相当高峻。这样开头，便已藏过前面爬山一大段文字，省掉了许多拖沓。同时，它暗示诗人已是走在通向别墅的路上，离别墅并不太远了。\n\n　　“春与青溪长”，伴随山路有一道曲折的溪水，其时正当春暖花开，山路悠长，溪水也悠长，而一路的春色又与溪水同其悠长。为什么春色也会“悠长”呢？因为沿着青溪一路走，一路上都看到繁花盛草，真是无尽春色源源而来。青溪行不尽，春色也就看不尽，似乎春色也是悠长的了。\n\n　　三、四两句紧接上文，细写青溪和春色，透露了诗人自己的喜悦之情。\n\n　　“时有落花至，远随流水香”这二句，要特别注意“随”字。它赋予落花以人的动作，又暗示诗人也正在行动之中，从中可以体味出诗人遥想青溪上游花在春光中静静绽放的景象。此时，水面上漂浮着花瓣，流水也散发出香气。芬芳的落花随着流水远远而来，又随着流水远远而去，诗人完全被青溪春色吸引住了。他悠然自适，丝毫没有“流水落花春去也”的感伤情调。他沿着青溪远远地走了一段路，还是不时地看到落花飘洒在青溪中，于是不期而然地感觉到流水也是香的了。\n\n　　总括上面四句：开头是用粗略的笔墨写出山路和溪流，往下就用细笔来特写青溪，仿佛是把镜头里的景物从远处拉到眼前，让读者也看得清清楚楚，甚至还可以闻到花香水香。\n\n　　一路行走，一路观赏，别墅终于出现在眼前。抬头一看，“闲门向山路”。这里是没有多少人来打扰的，所以门也成了“闲门”。主人分明爱好观山，所以门又向山路而设。进门一看，院子里种了许多柳树，长条飘拂，主人的读书堂就深藏在柳影之中。原来这位主人是在山中专心致志研究学问的。\n\n　　写到这里，诗人从登山到进门的一路经历，都曲曲折折地描述下来了。但他不过把几件景物摄进镜头，并没有叙述经过，仅仅给你以几种不同的变化着的形象。\n\n　　结末两句，诗人仍然只就别墅的光景来描写。“幽映每白日，清辉照衣裳。”这里的“每”作“虽然”讲。因为山深林密，所以虽然在白天里，也有一片清幽的光亮散落在衣裳上面。那环境的安谧，气候的舒适，真是专志读书的最好地方了。诗到这里，戛然而止，给读者留下了思索余地，更增加了诗的韵味。\n\n　　全诗都用景语织成，没有一句直接抒情，然而情韵盈然，意境幽美。王国维说过：“一切景语，皆情语也。”（《人间词话》删稿）诗人巧妙地运用景语，不但写出风景，给风景抹上感情色彩，而且又藏有人物，人物的行动、神态、感情、心理活动乃至身份、地位等等，给读者带来了直觉的美感和形象之外的趣味。因而这首诗余韵萦绕，有一种异乎寻常的艺术魅力。', poem_tags = '唐诗三百首,春天,写景' WHERE poem_title = '阙题' AND poem_author = '刘昚虚';
UPDATE edu_poem SET poem_translation = '长堤下，春水碧明一片悠悠，和漳河一起慢慢流。\n不要去理睬添愁助恨的棹声紧紧催促，要不然越来越多的离愁别恨一齐载到船上，船儿就会渐渐过重，就怕这桃花溪太浅，载不动这满船的离愁啊。', poem_notes = '宴词：宴会上所作的诗。\n长堤：绵延的堤坝。\n悠悠：指水的长久绵延之态。\n畎（quǎn）：田间小沟。\n漳河：位于今湖北省中部。\n催去棹（zhào）：催促船儿离开。催，催促。去，离开。棹，长的船桨。\n胜：承受。', poem_tags = '离愁,写景' WHERE poem_title = '宴词' AND poem_author = '王之涣';
UPDATE edu_poem SET poem_translation = '娇美的红花仿佛是美人含羞的笑脸，嫩绿的叶片点缀在她的鬓边，仿佛轻蹙黛眉，微微含恨。我怨恨晚风为什么不把花儿全部都吹落下来，这样飘落的花瓣就像彩绣点缀着厚厚的绿茵般的草地。那苏堤与白堤交叉像燕尾以分，湖面上桂木桨的舟船像轻轻浮荡的水鸥，我骑着勒缰的宝马就像倚在黄昏的残云边上。千丝万缕的绿柳丝轻轻飘拂令人伤神，水中的轻舟沿着柳径渐渐进入一个花丝环抱如屏的仙境，令人回肠荡气。我在岸上紧紧跟随着画船。为她美貌风情而消魂。隔着花朵柳丝，我不时地看见她那背面含羞的苗条婀娜的细腰身。\n我迟疑不决，好不容易才寻找到你的家门，又恰好遇到你不在家，只好满心怅惘地留言题门。后来终于可以得尝所愿，我脱下双鞋子进入你的闺中，那种欢爱的情景真是令人沉醉。以后我便时时刻刻地计算着下次幽会的日期，虽然有时也没有一个定准。不久我慢慢地发现，情思缭绕全是因为你那多情的眼神，衣带渐宽是因为感伤春天。到明天早晨，往事和孤烟一样清冷，满潮的凄风苦雨实在令人倍感忧愁。山色更加幽暗昏暝，水波淡淡，凌波仙子杳然无迹。', poem_notes = '1.渡江云三犯：词牌名，周邦彦创调，又名《渡江云》。双调，一百字，上片十句四平韵，下片九句四平韵，后片第四句为上一、下四句法，必须押一同部仄韵。\n2.羞红：脸上因羞愧而泛出的红晕。\n3.重茵：芳草地。\n4.燕尾：西湖苏堤与白堤交叉，形如燕尾。\n5.桂棹：以桂木为棹之舟，即芳舟。\n6.宝勒：以珍宝、金饰勒马络头，此指代宝马。\n7.残云：零散稀疏的云。\n8.千丝：柳条。\n9.迷津：迷失津渡；迷路。\n10.楚腰：《韩非子·二柄》：“ 楚灵王好细腰，而国中多饿人。”后因以“楚腰”泛称女子的细腰。借指细腰女子。\n11.逡（qūn）巡：徘徊不进；滞留。巡，有所顾虑而徘徊不前。\n12.题门：《世说新语》载，嵇康与吕安是朋友，安拜访嵇不遇，嵇康子嵇喜出门让吕安进屋，安未入，在门上题写“凤”字而去，意谓喜是一只“凡鸟”。此处单作“不遇”解。\n13.堕履：留宿。\n14.牵萦：纠缠；牵挂。\n15.宽带：衣带宽松。形容腰变瘦。\n16.留情缘眼，宽带因春：一本作“留情缘宽，带眼因春”；一本作“留情转眼，带减因春”。\n17.山黛：青葱浓郁的山色。\n18.暝：一本作“映”。\n19.尘：一本作“澄”。', poem_appreciation = '《渡江云三犯》，又名《渡江云》。双调，一百字，上片十句四平韵，下片九句四平韵，后片第四句为上一、下四句法，必须押一同部仄韵。\n\n　　上片追忆与杭妾始遇时的情景。“羞红颦”三句，描绘出湖边暮春景色。“重茵”，原指厚席，这里喻厚厚的芳草地。此言暮春的湖边阵阵晚风吹得落英缤纷，点缀着绿茸茸的芳草地。这落英恰像那少女们浅颦含羞微怨的娇态。“旧堤”三句，述湖景。“旧堤”指西湖苏、白两堤；“燕尾”言两堤在湖上交叉形如燕尾。“桂棹”，以桂木为桨的船，这里泛指西湖中游船；“宝勒”，即用珍宝装饰的马络头，这里指代马儿。三句言远望湖上苏、白两堤交叉，形如燕尾，湖中众多的游船与鸥鸟一起荡漾在碧波之中。词人骑着马，背衬着西天的彩云伫立在岸堤上观赏远近景色。“千丝”两句，游湖思亡妾。“千丝”指堤岸边的柳枝。此言眼前这些既青柔又浓密的柳枝却不能为词人挽留住就在这儿相识的亡妾。词人到了这湖边，像又回到了刘阮入天台而遇仙的地方（即点明词人与杭妾在此初见之事）。“柳”即留也，所以古人多有折柳赠别的习俗。今杭妾不幸亡故，不禁使词人见柳丝而“怨碧”。“肠漫回”两句，因思之深而致幻。“楚腰身”，楚谚有“楚王好细腰，宫中多饿死”。这里泛指美人的细腰身。此言词人对亡妾牵肠挂肚朝夕相思，以致伫立在这两人初识之处，幻觉中向花丛中望去似乎隐约看到了她美妙的背影。\n\n　　下片追忆不遇以悼念亡妾。“逡巡”四句，忆不遇。“题门”，事见《世说新语》吕安访嵇康不遇，题字其门。此处借代不遇。“堕履”，本《史记·留侯世家》，张良遇黄石公故事。这是作传艺、钟情解。此言词人想起从前初识之时曾多次来到她的门前徘徊，终因两人不能见面而心情惆怅，词人像张良盼望黄石公传艺那样希望她能对其钟情，但又因为好几次约会都没有实现而感到牵肠挂肚。又“堕履”，事见《北史·韦琼传》，有“不弃遗簪堕履”之语。“还始觉”两句，“缘”，因也；“宽带”，语出沈约与徐勉书：“老病百日数旬，革带常应移孔。”柳永《蝶恋花》词也有：“衣带渐宽终不悔，为伊消得人憔悴”之句，词人用柳词意境。此言词人对亡妾难舍难忘，细想原因，一是因为她有一双令人消魂的多情的媚眼。照现代人的说法，眼睛是人心灵的窗户；而古时作画也有“画龙点晴”之说，所以词人突出了亡妾双眼摄人心魄的魅力。二是词人值此清明时节，自然引起了对亡妾的怀念，以致因对她的刻骨相思而日渐消瘦。“明朝”两句，点出悼念。因为今天正是清明节，是祭奠亡灵之时，所以词人想到如今自己与杭妾早已阴阳异路，两人往日的恩爱情景已似幻梦般的风消烟散，词人对亡妾的悼念，也如那湖上的风风雨雨一样愁煞人啊。“山黛暝”一句，以景作结，点明游湖。此句语出苏轼《次韵促仲殊游西湖》诗：“水光潋滟犹浮碧”，言山色空蒙，湖面浮碧似镜，一切都归结于这平静之中。', poem_tags = '清明节,写景,追忆' WHERE poem_title = '渡江云三犯·西湖清明' AND poem_author = '吴文英';
UPDATE edu_poem SET poem_translation = '春风吹绿了芳草，在白云的映衬下，芳草显得葱绿可爱，是在晓梦中梦见了这如茵的芳草。花瓣轻轻地洒落在软草上，蒙茸的草地随着流水延伸向天际。一眼望去，伊人的芳踪已被无边的芳草阻隔，春恨别情无限。\n萋萋的芳草，遮盖了伊人的足迹，给人留下了多少相思别离之恨，使人追忆起像绿草地一样的翠罗裙。冷落的庭院，凄迷的古道，都笼罩在茫茫烟雨之中，这景象勾起了人满怀的愁绪。', poem_notes = '芳裀（yīn ）：形容春草茸茸如垫褥。\n香尘：带着花香的尘土。\n萋萋：指茂密的芳草。\n翠罗裙：借指人。化用牛希济《生查子》“记得绿罗裙，处处怜芳草”句意。\n闲门：代指情人居住处。\n凄迷：迷茫。', poem_appreciation = '在南宋诗词圈子里，吟物之风十分盛行。但平庸草草之作，屡见不鲜，不足为怪。高观国的这首吟草词却不沾不滞，以意贯串全词。通过写草色来抒发自己的离愁别恨。这首词的上半阕绘出了一幅纯净明丽的阳春烟景：春风吹绿了芊芊的芳草，在飘动的白云映衬下显得那样葱翠可爱；蒙茸的草地伴随着流水伸向天际，花瓣轻轻地洒落在草上。这的确是十分迷人的芳景。\n\n　　读者还应当注意到“晓梦入芳裀”这句的含意。“芳裀”，芳草有如厚厚的裀褥。关键是“晓梦”二字，原来这令人神往的如屏芳景，只是一场春梦中的幻境而已。大地山河，一经点破，并化烟云。用笔之虚幻，莫测端倪。“香尘”一句，补足梦境。“香尘”者，女子的芳踪也。刘长卿《陪辛大夫西亭观妓诗》：“任他行雨去，归路裛香尘”，与此词意境相似。可是美人的踪迹被无边的芳草隔断了。即使追寻到梦里也并不圆满，也只是一个凄迷的短梦而已。\n\n　　下片转写实境，写醒后的情怀。用“萋萋”一句换头，仍是从草字生发。“萋萋”，芳草美盛之貌。\n\n　　“芳草萋萋鹦鹉洲”（崔颢《黄鹤楼》）即是此意。那么鲜美的芳草与江南的恨思有什么关系呢？这里似有事而无典，就是说写自己经历过的事，以抒发他对远隔香尘的伊人的思念。“翻忆”句重笔渲染。用“罗裙”形容芳草，始于白居易的“谁开湖寺西南路，草绿裙腰一道斜”（《杭州春望》）；牛希济的“记得绿罗裙，处处怜芳草”（《生查子》），则以芳草拟罗裙。此词在“翠罗裙”上缀以“翻忆”二字，感情上又多了一个曲折。翻者，反也。本想眺望一下，略舒郁悒，没想到反而勾起了对绿色罗裙——这最具有女性特征的服饰的思念来。这一缕痴情真是不好收拾。“冷落”三句，以排体出之。句句切草、切情，化工之笔。“冷落闲门”，见出庭院之孤寂，而“庭草无人随意绿”之神理，即隐含其中。“凄迷古道”，流露出望远之悲心。“远芳侵古道，晴翠接荒城。又送王孙去，萋萋满别情”（白居易《赋得古原草送别》）为其所本。\n\n　　“凄迷”二字，将心绪之凄黯与望眼之迷蒙两重意象融会一起，并与前片之“望隔香尘”暗相挽合。以迷迷糊糊之睡眼，逐古道之轻尘，真令人难以为怀。然而作者述情之笔愈出愈精，最后又推出了“烟雨正愁人”之句，把这种怅惘的心境渲染到了十分。“烟雨”，在词人的笔下与草色结缘甚深。林和靖咏草词“金谷年年，乱生春色谁为主？余花落处，满地和烟雨。”（《点绛唇》）贺方回《青玉案》：“若问闲情都几许？一川烟草，满城风絮，梅子黄时雨”，便是显例。此词以“烟雨”结笔，将草色、离情与迷蒙的雨色化为一片，情景相伴，凄然无尽。况蕙风所谓“取神题外，设境意中”者，约略近之。\n\n　　咏吟春草是一个古代文人津津乐道的永恒题目，名篇佳作，数不胜数。有评论家说，在高手如林的名人队伍里，高观国用他那巧妙的艺术构思和秀美婉约的风格另起炉灶，独成一家。', poem_tags = '宋词精选,离别' WHERE poem_title = '少年游·草' AND poem_author = '高观国';
UPDATE edu_poem SET poem_translation = '峰峦叠嶂，环抱着小桥流水；河水青碧，萦绕着繁花翠草。竹林幽深秀美，几间茅舍静立其中。和煦的春风时时吹拂，使得房屋清洁，纤尘皆无。\n午睡醒来，满耳都是婉转的鸟鸣。斜倚枕头，想起当年做官时，听早朝的鸡鸣，此情景已恍如隔世。忽然想起故人都已老，自己当然也不例外。如今我贪恋闲适，已忘却了从政建功的美梦。', poem_notes = '渔家傲：词牌名。《词谱》卷十四云：“此调始自晏殊，因词有‘神仙一曲渔家傲’句，取以为名。”\n柔蓝：柔和的蓝色，多形容水。萦：萦绕。《广韵》：萦，绕也。\n窈窕：幽深的样子。\n欹眠：斜着身子睡觉。袁文《瓮牖闲评》卷五：“朝鸡者，鸣得绝早，盖以警入朝之人，故谓之朝鸡。”\n邯郸道：比喻求取功名之道路，亦指仕途。', poem_tags = '宋词三百首,山水,隐居,生活' WHERE poem_title = '渔家傲·平岸小桥千嶂抱' AND poem_author = '王安石';
UPDATE edu_poem SET poem_translation = '边塞的野草啊，边塞的野草！野草枯尽时。戍边的兵士已老。山南山北雪后放睛，千里万里处处月明。明月啊，明月！远处传来胡笳一声，令人肠断欲绝。', poem_notes = '调笑令：词牌名。唐·白居易《代书诗一百韵寄微之》曰：“打嫌《调笑》易，饮讶《卷波》迟。”自注：“抛打曲有《调笑令》，饮酒曲有《卷白波》。”词调名盖本唐曲。此调为单调，八句，三十二字。第四、五句押平声韵，其余各句均押仄声韵。其中第二句叠用第一句，第七句叠用第六句，第六句颠倒第五句末二字而成。\n边草：边塞之草。此草秋天干枯变白，为牛马所食。\n尽：死。\n雪晴：下过大雪后放晴。\n月明：月色皎洁。\n胡笳（jiā）：一种流行于北方游牧民族地区的管乐器，汉魏鼓吹乐常用之。\n绝：极，很，表示事物程度的副词。', poem_appreciation = '盛唐、中唐时代，北部、西北部边疆与异族的战争接连不断，边塞生活、边兵情怀就成为诗词中的常见题材。这首边塞词就抒写了久戍边陲的士兵冬夜对月思乡望归的心情。\n\n　　开头三句以边草起兴，感叹长期在边关征战的兵士的命运如同边草。边草就是边地的白草，据《汉书·西域传》颜师古注，谓白草“干熟时正白色，牛马所嗜也。”王先谦补注谓白草“冬枯而不萎，性至坚韧。”这种草在秋天开始变白，冬天枯干。士兵征战边关，春去冬来，年复一年，归期渺茫。他们望断边草渐渐变白枯干，深感青春消逝，年华老去，在这僻远广漠的边地，更勾起了浓重的乡思。而朝廷把他们征发到边关以后，却不加关心，他们戍边到老也无人来换防。眼见边草年年枯白，回乡的希望也随之渐渐破灭了。《诗经·小雅·采薇》写从军战士的心情：“我行不来（无人来关心慰问）”、“莫知我哀”。王之涣《凉州词》写戍卒怨情：“春风不度玉门关”，叹朝廷恩泽不到边关。这里的“边草”三句。在望草叹老中也包含着这种悲凉的感触，思乡之切与怨怅之深交织在字里行间。\n\n　　接下去视角从边草转到白雪、明月，更渲染了兵士静夜思归的心境。在这万籁俱寂的冬夜，伫立边关，但见白雪皑皑，晴空万里，月色皎洁。白雪与明月相映，一片银辉，愈见边地之寥廓明净。这不是赏景的雅兴，而是以乐景写哀，愈见其哀的曲折表现手法，来表露征人对景难排的无尽乡思。山南山北，千里万里，到处是雪，重叠排对的句式，愈显出征人的愁思萦回。望月常易触动乡情，何况远在边塞、久别故乡的征人，他的思绪更难以抑制，随着明月流光牵到万里以外的故乡。唐代边塞诗中常借望月来写征人乡思，有名的如李益的《从写北征》：“碛里征人三十万，一时回首月中看”；《夜上受降城闻笛》：“回乐峰前沙似雪，受降城外月如霜”，写平沙中望月所引起的“征人尽望乡”的心情。这首词也是如此，从雪晴、月明的宁静景象中，令人可以想见征人伫立苍茫的形象及其排解不尽的缭乱边愁和绵长悠远的思乡情怀。\n\n　　结尾三句，进一步加浓了这种思归无期的沉重压抑感。根据《转应曲》词调，六、七两句要将第五句末两字颠倒过来，再重复两次，增强抒情色调和音乐感。“明月，明月”，再强调一下月色，望月思乡的中心更突出了，喟然感叹之情溢于言表。明月已撩动乡思，而偏偏在此时又听到声声胡笳，在空寂的夜晚听来分外苍凉凄切。笳声、鼓角之类音响都是边塞战地的特有声音，塞上悲笳，使征人沉浸于乡思的心境猛然震醒：呵，现在还身处战争环境，战事不息，戍边未竟，何日是归期！望月思归，只是可望可思而已，而真正归故乡的现实却又在这笳声中化为泡影。这样的对月闻笳，真使人愁思郁结，肝肠寸断。征人那痛苦，哀怨的心声随着月光的流洒和笳声的飘扬，也在这大漠中留下了长长的余音。\n\n　　这首词借助草、雪、月、笳等景物来写征人的心情，也表露了作者对征人的深切同情，情在景中，蕴藉有味。戴叔伦主张：“诗家之景，如蓝田日暖，良玉生烟，可望而不可置于眉睫之前也”。（司空图《与极浦书》）这就是说，他要求诗中写景要有韵致，有余味。从这首词中，也可见出他追求情景相融所产生的艺术效果。', poem_tags = '宋词三百首,豪放,边塞,写景,思乡' WHERE poem_title = '调笑令·边草' AND poem_author = '戴叔伦';
UPDATE edu_poem SET poem_appreciation = '唐代经济繁荣，文化发达，诗酒关系有如血肉关系密不可分。柳宗元虽然比不上盛唐诗仙兼酒仙李白的浪漫，也不同于晚唐李商隐“身世醉时多”的悲伤，自有自己喝酒的情态与心态。全诗共１６句，开头四句为第一层：“今旦少愉乐，起坐开清樽。举觞酹先酒，为我驱忧烦。”清早起来就喝酒，原因是感到缺乏生活乐趣。相传杜康是我国酒的创始人。据郭沫若的《中国史稿》：杜康即少康，夏王相的儿子。当年夏王相被一部落领袖杀害，少康逃到今河南虞城县依附有虞氏，当了“疱正”，是个专管皇帝吃饭的职司。杜康为了迎合皇上，力求酿出好酒，亲自筛选精粮，采制神曲，调配奇方，酿出的酒果然味美可口。皇帝饮后神振食增，龙颜大悦，就封杜康为“酒仙”。故柳宗元先举杯祭酹造酒的祖师杜康，是他用勤劳与智慧造出美酒，给人们驱逐忧愁和烦恼。“须臾心自殊，顿觉天地喧。”酒入口，加快了血液循环，浑身感到一股暖流上涌，心情发生变化，天地之间也变得温暖起来。接着，一一叙说饮酒后的感受：“连山变幽晦，绿水函晏温。”幽晦，《楚辞九歌·山鬼》说：“山峻高以蔽日兮，下幽晦以多雨。”晏温，指天气晴暖。心感温暖，连自然界的景物也变得温暖，连绵的高山也改变了原来的幽晦，碧绿的水流含着温暖的气息。这是诗人从感官的角度来写的，随着时间的推移，夏天的太阳升起来了，天气自然变得暖和起来。“蔼蔼南郭门，树木一何繁。清明可自庇，竟夕闻佳言。”开篇点明时间，现在点明饮酒的地点──南郭门。南郭门指永州城南，南门城边，树木繁茂，清凉的树荫可以遮挡烈日，庇护自己，整天都可以在树下乘凉谈天。这四句描写了诗人在永州的闲适生活，既无衙门的公务缠身，又无日出而作的劳累，似乎是无拘无束，自由自在。也有注家认为：“清明”指草木，此句点化《左传·文公七年》“葛犹能庇其本根”句意，“无知的草木都懂得好好保护自己”。意思是说自己还不如草木，连保护自己都不懂得。下句说：“这些树木整夜好像在向自己诉说什么，现在才明白，原来它们要说的正是这种有启发性的话。”可做为一家之言。“尽醉无复辞，偃卧有芳荪。”谢灵运《道路忆山中诗》：“追寻栖息时，偃卧任纵诞。”与朋友们尽情畅饮，哪怕喝醉也不要推辞，芳草萋萋，可以供我们躺卧。这是第二层的小结，饮酒的快乐尽在“偃卧”之中，按理全诗可以到此结束了。然而，“彼哉晋楚富，此道未必存。”《孟子·公孙丑》：“曾子曰：晋楚之富，不可及也。彼以其富，我以吾仁；彼以其爵，我以吾义。吾何慊乎哉！”后两句“谓饮酒之乐也”。即使是那些富比晋楚的人，恐怕也未必知道饮酒的快乐吧？后两句为第三层，进一步说明饮酒的快乐，使诗意得到升华。\n\n　　研究者认为，柳诗受陶渊明影响较深，“柳宗元确有部分作品拟学陶渊明，大都作于贬永州之后……宗元学陶诗作实蓄忧愤于闲适恬谈之中。”（王国安《柳宗元诗笺释》）曾吉甫认为“《饮酒》诗绝似渊明。”陶渊明曾任彭泽县令，因对当时现实不满，四十一岁即弃官归隐，躬耕垄亩。他以《饮酒》为题写诗２０首，在序中说：“既醉之后，辄题数句自娱，纸墨遂多，辞无诠次。”诗主要写自己的生活遭遇，人生坎坷。其五：“结庐在人间，而无车马喧。向君何能尔？心远地自偏。采菊东篱下，悠然见南山。山气日夕佳，飞鸟相与还。此中有真意，欲辨已忘言”。全诗与饮酒无关，写的是归隐后悠闲恬静的心情。他的“盥濯息檐下，斗酒散襟颜”（《庚戍岁九月中于西田获早稻》），“过门更相呼，有酒斟酌之”（《移居》），反映诗人过的是自食其力的生活。而“子云性嗜酒，家贫无由得。时赖好事人，载醪祛所惑。（《饮酒》）”反映的是生活贫困，无酒可饮，只好接受别人的恩赐。陶是看破红尘，“种豆南山下，草盛豆苗稀。晨兴理荒秽，带月荷锄归。”隐居山村，做一名普通农民来与当时的黑暗社会抗挣。柳宗元却不同，少年得志，志向远大，在朝廷超取显美，成为王叔文革新集团的骨干。“永贞革新”失败后，被贬谪到南蛮之地永州，这对他是残酷打击。柳是不得已离开朝廷，政治理想并未放弃。在永州任司马，虽为闲职，官禄照领，不必象陶渊明那样亲自耕种，以求温饱。酒完全可以购买，与朋友饮酒是常事。他的郊游是追求闲适，他的饮酒是自我陶醉，其目的是转移视线，以求适应环境，安宁心情。然而，遭贬的打击，沉重的心理负担，无言的痛苦谁能领会？诗的开头就提到情绪低落，但整个基调并不衰飒，与一般的反映闲适的饮酒诗也不同。“它写出了诗人在特定环境中似醉非醉的特有状态，以及他蔑视世俗的鲜明个性，不失为自画像中的一幅佳作。”（胡士明《柳宗元诗文选注》）由此可见，柳宗元的《饮酒》等诗，受陶渊明、谢灵运的影响是客观存在的，却自有不同的个性与意蕴。', poem_tags = '归隐,饮酒,生活' WHERE poem_title = '饮酒' AND poem_author = '柳宗元';
UPDATE edu_poem SET poem_translation = '月亮初升时秋露已经稀微，身着单薄的罗衣并未更换别的衣裳。\n漫漫长夜满怀深情地银筝拨动，心中害怕独守空房，不忍进屋睡觉。', poem_notes = '秋夜曲：属乐府《杂曲歌辞》，是一首宛转含蓄的闺怨诗。\n桂魄：即月亮。相传月中有桂树，又月初生时的微光曰魄，故称初生之月为桂魄。\n轻罗：轻盈的丝织品，宜做夏装，在此代指夏装。\n已薄：已觉单薄。\n筝：拨弦乐器，十三弦。\n殷勤弄：频频弹拨。\n空房：谓独宿无伴。', poem_appreciation = '首句点明时间，夜幕初临，月充刚刚从东方升起，秋露虽生，却还微薄稀少，说明天气已经凉爽，但还不觉寒冷，给人一种清凉之感，烘托出女主人公清冷孤寂的心情。这与下面一句正好相互呼应，由于天气已凉，所穿的轻盈细软的罗衣，已感到单薄了。但还不觉得寒冷难忍，所以还没更换衣服。字里间隐隐充溢出女主人公因秋凉需要更衣而思念远方丈夫的情愫。\n\n　　第三句写女主人公的弹筝行动，实际是以乐曲寄情。讲述女主人公一直在室外弹筝，从月亮初升一直到夜深，仍然在频频弹拨，丝毫没有回房的意思。实写女主人公迷恋弹筝，以至废寝忘餐。实则醉翁之意不在酒，她并不是因为爱弹筝爱得入迷才这样，而是“心怯空房不忍归”，以揭穿了女主人公内心处的秘密。\n\n　　末句以巧妙的构思和奇特的表现方法，通过女主人公的心理活动，展示了她独守空房的哀怨。写女主人公在深深思念着远出的丈夫，夜不能寐，不愿独守空房，只有借弹筝来排遣凄凉寂寞的情怀。房空，心更空虚，其情悲切。\n\n　　此诗前两句是写景，写得颇为悠闲，秋夜微凉，景物凄清；诗人描写了一种清冷的景象，以此为“背景”，再写女主人公的“衣着”，以衬托其孤寂。末两句是写情，主人公寂寞难寝，殷勤弄筝，接写“弹筝”的行动，似迷恋乐曲，实际上以乐曲寄情。末句画龙点睛，通过正面抒情，对思妇的心理活动，进行了生动深刻的刻划，顿觉无限幽怨之情跃然于纸上。\n\n　　此诗语极委婉，情极细腻，把儿女羞涩的情感遮掩得严严实实。诗人借用女主人公心理活动来展示其独守空房的哀怨，曲尽其妙；代写思妇心境，抒发内心空虚的痛苦，更显深刻细腻生动，流露出女主人公独守空房、思念丈夫的怨情，表现出诗人诗艺的功力。', poem_tags = '唐诗三百首,秋天,女子,思念' WHERE poem_title = '秋夜曲' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '我酒醉后架着小船，在湖中荡漾，听任流水把小船推向花草深处。现实世界的名利缠身，不能解脱，没有办法在这如花的仙境住下去。\n烟水茫茫，笼罩在夕阳的余辉里。两岸的青山排列无数，晚风吹来，落花如雨，竟然不记得来时走过的路了。', poem_notes = '尘缘：佛教名词。佛经中把色、声、香、味、触、法称作 “六尘”。以心攀缘六尘，遂被六尘牵累，故名。\n乱红：落花。李贺《将进酒》：“况是青春日将暮，桃花乱落如红雨。”', poem_tags = '失意,生活' WHERE poem_title = '点绛唇·桃源' AND poem_author = '秦观';
UPDATE edu_poem SET poem_translation = '自从我们分别，两个人的心思差别可真大啊。\n当时只说三四个月后就相见，谁能想到如今已五六年。\n没有心情弹七弦古琴，也不想去寄书信。\n精致的连环玉断裂了，我在长亭里等你等得望眼欲穿。\n即使我有一百个心思在想你，有一千个挂念系在你身上，也只是无可奈何地责怪你。\n内心有万语千言说都说不完，可你不在身边我百无聊赖，徒劳地倚遍栏杆。\n在重阳节登高时看到孤零的大雁，在中秋时月亮圆满我们却没有团圆。\n七月半的时候我持烛烧香问苍天，\n六月的三伏天那么热，人们都在摇扇子，可我的心却是寒冷的。\n五月石榴花开红似火，偏偏遇上一阵阵的冷雨浇打花朵。\n四月的枇杷还没有成熟，我就在对着镜子心烦意乱了。\n春光奔走忙，三月的桃花凋落随水流婉转。\n二月的风筝断了线，飘零无依真可怜。\n唉，我的郎君啊，多想下一世你做妾来我为郎。', poem_notes = '一朝：一时，一旦。\n相悬：相去悬殊，差别大，也作“相县”。\n连环：连环成串的玉，比喻连续不断。\n重九：即重阳节，因在农历九月初九，故又称重九，有登高的习俗。\n仲秋：秋季的第二个月，即农历八月，八月仲秋即为中秋节，有团圆之俗。仲：排行第二或居中。\n秉烛：手持灯火来照明。', poem_tags = '回信,伤怀' WHERE poem_title = '怨郎诗' AND poem_author = '卓文君';
UPDATE edu_poem SET poem_translation = '你骑着白雪花毛的龙马，金鞍闪耀，好一个五陵豪侠。\n你所佩之剑，色如秋霜，切玉如泥；你所穿之袍，缀有明珠，耀如落日。\n原来你是侍奉皇上斗鸡徒，乘坐的马车轩盖高高。\n你张弓可摧南山虎，伸臂手接太行飞猱。\n你酒后风采飞扬，三杯下肚，笑弄宝刀。\n你杀人如剪草，与剧孟一同四海遨游。\n你终于想起改变自己的游荡生活，要争取功名。\n你于是发愤去了函谷关，跟随大军去到临洮前线。\n叱咤风云经百战，匈奴如鼠尽奔逃。\n你归来豪气不改，终日饮酒，不肯给萧曹宰相下拜。\n羞于学原宪，居住荒僻蓬蒿的地方。', poem_notes = '白马篇，乐府《杂曲歌辞》旧题。\n龙马，《周礼·夏官·廋人》：“马八尺以上为龙。”\n五陵，语出班固《西都赋》：“南望杜、灞，北眺五陵。”杜、灞谓杜陵、灞陵，在城南；五陵谓长陵、安陵、阳陵、茂陵、平陵，在渭北。皆汉代帝王陵墓，并徙入以置县邑，其所徙者皆豪右、富赀、吏二千石。见《后汉书·班固传》及：李贤注。五陵豪，谓五陵豪侠。\n“秋霜切玉剑，落日明珠袍”意谓：所佩之剑，色如秋霜，切玉如泥；所穿之袍，缀有明珠，耀如落日。秋霜:形容剑的颜色。切玉:形容剑的锋利。明珠袍:镶珠的衣袍。\n斗鸡，玄宗好斗鸡，善斗鸡者每召入宫中侍奉，甚得宠幸。轩盖，有篷盖之车，贵人所乘。\n万乘，指天子。古制，天子有兵车万乘。轩盖，车盖。\n弓摧南山虎，用晋周处事。《晋书·周处传》载:南山白额猛虎为患，周处入山射杀之。\n剧孟，汉时大侠。此代指当时豪侠中之雄杰者。\n函谷，古关名，在陕州灵宝县。此代指帝京以东之要塞。临洮，地名，属陇右道洮州。此代指帝京以西之边陲。\n临挑，古县名，在今甘肃眠县一带。\n叱咤，怒斥声。万战场:全诗校:“一作经百战。”\n萧曹，即汉相萧何、曹参。此代指时相。二句意谓：“五陵豪”因边功而傲视大臣。自篇首至此，皆写“五陵豪”。\n原宪，即子恩，孔子弟子。居处简陋，上漏下湿，不以为意，端坐而弦歌。见《韩诗外传》。二句李白自谓。善慕“五陵豪”之生涯，羞为蛰居陋室之穷儒。\n使酒气，因酒使气。萧曹:西汉名相萧何和曹参。拜，全诗校：“一作下。”', poem_appreciation = '“龙马花雪毛，金鞍五陵豪”，“秋霜切玉剑，落日明珠袍”，描绘豪侠的形象。\n\n　　“斗鸡事万乘，轩盖一何高”，“弓摧南山虎，手接太行猱”，讲述豪侠的倜傥不群和武艺高强。\n\n　　“酒后竞风采，三杯弄宝刀”，“杀人如剪草，剧孟同游遨”，表达豪侠不拘礼法，疾恶如仇。\n\n　　“发愤去函谷，从军向临洮”，“叱咤经百战，匈奴尽奔逃”，虽写豪侠的爱国精神，实则也隐隐流露出诗人想建功立业的寄望。\n\n　　“归来使酒气，未肯拜萧曹”，“羞入原宪室，荒淫隐蓬蒿”，最后四句是说打败敌人，胜利归来，既不会阿附权贵、居功邀赏，也不自命清高，隐居草野，要继续过游侠生活。\n\n　　在这首诗里，诗人以热烈的感情，丰富的想象，夸张的语言，刻划了一个武艺高强、报国杀敌、功成退隐的侠客形象。他出身高贵，剑如秋霜，袍饰明珠，艺高胆大，堪与名侠剧孟比肩。他虽身玺百战，威震胡虏，但功成后又任性使酒，不肯俯身下拜萧何曹参之类的高官，而是隐居于荒山野径。\n\n　　他潇洒倜傥，豪迈勇敢，不拘礼法，疾恶如仇。特别值得注意的是富于爱国精神。当祖国的统一和安定受到威胁时，便“发愤去幽谷，从军向临洮”，不计身家性命，英勇杀敌，立功疆场，而胜利归来时，既不阿附权贵，居功邀赏，又不消极退隐，逃避现实。在这个形象身上，集中体现着李白的任侠思想。显然，他的这种任侠思想和他进步的政治理想，他的反对腐朽权贵的斗争精神是有密切关系的，因而也显示了这种任侠思想在当时历史条件下的进步意义。', poem_tags = '爱国,壮志,侠客,写马' WHERE poem_title = '白马篇' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '春天的阴云垂落在旷野，田野里到处绿草青青。偶尔看见幽香的花开放，那一株树因此明亮美丽。\n黄昏的时候，我乘一叶孤舟停靠在古旧的祠堂下，在满河的烟雨中凝望那渐生渐满的潮水。', poem_notes = '淮：淮河。犊头：淮河边的一个地名。犊头镇，在今江苏淮阴县境内。\n春阴：春天的阴云。垂野，春天的阴云笼罩原野。\n幽花：幽静偏暗之处的花。\n古祠：古旧的祠堂。\n满川：满河。', poem_appreciation = '这首小诗题为“晚泊犊头”，内容却从日间行船写起，后两句才是停滞不前船过夜的情景。\n\n　　诗人叙述中所见的景象说：春云布满天空，灰蒙蒙地笼罩着淮河两岸的原野，原野上草色青青，与空中阴云上下相映。这样阴暗的天气、单调的景色，是会叫远行的旅人感到乏味。幸而，岸边不时有一树野花闪现出来，红的，黄的，白的，在眼前豁然一亮，那鲜明的影像便印在你的心田。\n\n　　阴云，青草，照眼的野花，自然都是白天的景色，但说是船行所见，何以见得呢？这就是“时有幽花一树明”那个“时”字的作用了。时有，就是时时有，不时地有。野花不是飞鸟，不是走兽，怎么能够一会儿一树，一会儿又一树，不时地来到眼前供人欣赏呢？这不就是所谓“移步换形”的现象，表明诗人在乘船看花吗？\n\n　　天阴得沉，黑得快，又起了风，眼看就会下雨，要赶到前方的码头是不可能的了，诗人决定将船靠岸，在一座古庙下抛锚过夜。果然不出所料，这一夜风大雨也大，呼呼的风挟着潇潇的雨，飘洒在河面上，有声有势；河里的水眼见在船底迅猛上上涨，上游的春潮正龙吟虎啸，奔涌而来。诗人呢？诗人早已系舟登岸，稳坐在古庙之中了。这样安安闲闲，静观外面风雨春潮的水上夜景，岂不是很快意的吗？\n\n　　欣赏这首绝句，需要注意抒情主人公和景物之间动静关系的变化。日间船行水上，人在动态之中，岸边的野草幽花是静止的；夜里船泊牧犊头，人是静止的了，风雨潮水却是动荡不息的。这种动中观静，静中观动的艺术构思，使诗人与外界景物始终保持相当的距离，从而显示了一种悠闲、从容、超然物外的心境和风度。', poem_tags = '春天,写景,闲适' WHERE poem_title = '淮中晚泊犊头' AND poem_author = '苏舜钦';
UPDATE edu_poem SET poem_translation = '夜风拂过，树叶纷纷下落好似雨声闯入耳中，皎洁的月光似清霜铺满大地。\n正当夜深人静要独自睡去，不禁感慨有谁愿来为我拭去床上的灰尘。', poem_notes = '叶声：树叶掉落的声音。\n方：正在，正当。\n拂：拭，掸去。', poem_tags = '秋天,夜晚,抒情,寂寞' WHERE poem_title = '秋夕' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '巴山楚水江上雨水多，巴人擅长吟唱本乡歌。\n今朝北方客子思归去，回乡迎来纥那披绿罗。', poem_notes = '楚水巴山：楚水：①水名。一名乳水。即今陕西省商县西乳河。楚水注之，水源出上洛县西南楚山。昔四皓隐于楚山，即此山也。其水两源合舍于四皓庙东，又东迳高车岭南，翼带众流，北转入丹水（北魏郦道元《水经注·丹水》）。②泛指古楚地的江河湖泽。巴山：①大巴山。巴山夜雨涨秋池。②泛指巴蜀一带。\n楚水巴山：泛指蜀楚之地的山水。\n巴人：此诗中指古巴州人。\n北客：作者自指，言客有思乡情也。\n纥（hé）那：踏曲的和声。绿罗：①绿色的绮罗。②比喻绿水微波。③荔枝名。川人有称荔枝为绿罗者。诗中所指解释历未能统一。三种解释者皆有，也都讲得通。', poem_appreciation = '《竹枝词》是古代四川东部的一种民歌，人民边舞边唱，用鼓和短笛伴奏。赛歌时，谁唱得最多，谁就是优胜者。刘禹锡任夔州刺史时，非常喜爱这种民歌，他学习屈原作《九歌》的精神，采用了当地民歌的曲谱，制成新的《竹枝词》，描写当地山水风俗和男女爱情，富于生活气息。体裁和七言绝句一样。但在写作上，多用白描手法，少用典故，语言清新活泼，生动流畅，民歌气息浓厚。刘禹锡创作多首《竹枝词》，分两组，这是其中一组的第二首。\n\n　　第二首不像第一首那样以谐音写含蓄情事，而是从身居蜀地耳闻巴人歌唱自然引发怀乡幽思。\n\n　　首句“楚水巴山江雨多”看似平易概括的摹写却流露出诗人因王叔文派政治革新案多年贬谪远任的愁苦。楚地巴山远离长安，虽然暂时避开政治漩涡，但对于心怀远大抱负的诗人来说却是心仍有不甘的。“总为浮云能蔽日，长安不见使人愁。”（李白《登金陵凤凰台》）这也许正是诗人内心最真实的想法。这不能不使人愁苦，伤心失意下也属正常。压在心头的大石无法移开，难以消除的寂寞和烦闷更无法排遣。江雨又来，淅沥不歇，更添伤情。\n\n　　“巴人能唱本乡歌。”于此伤情怀思之下巴人乡歌又传入耳。“歌者那知听者愁，一声一叹总牵情。”巴人歌唱本属常有之事，诗人却将其平常事入诗中，可见诗人自己心绪却是常常不平静的。自然不是只因耳听巴人歌声才起的不平静，人总是会因某事而及他情。这是再自然正常不过的了。本来由江雨多引起的伤情再又由巴人的歌唱更是雪上加霜了。\n\n　　闻歌思归，自然引出下两句：“今朝北客思归去，回入纥那披绿罗。”长安，不算是自己的归处，多次的贬谪打击，他怕是早已对政治不怀希望了，长安那里只是自己的伤心地而已。至于诗人想归何处，可以从诗句中推测。《纥那》当是诗人家乡的乡歌。身披绿色绮罗踏着《纥那》曲的和声边舞边歌的乡人想必是欢迎自己归来的一朝离乡，飘零天涯。也只有那里才不排拒自己。因有这样的想法，窗外的绿水微波渐渐幻成故乡人身上迎风而舞迎己归来的绿色绮罗，耳边听闻的《纥那》节拍又显得那样的清晰明了。\n\n　　组诗歌词的风格明快活泼，有浓郁的生活气息和鲜明的民俗特色。如同屈原作《九歌》一样，刘禹锡从当地民歌中汲取素材，变民俗风情为文人风雅，创作出有别于文人文学的民歌体诗歌，显示了文学创作中雅俗互补的重要意义。', poem_tags = '山水,思乡' WHERE poem_title = '竹枝词二首·其二' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '用不到去歌唱当年皇帝妃子的悲欢离合；在人间也有银河，使得千千万万人家夫妻离散。\n像石壕村那样的夫妻诀别数也数不清，老百姓的泪水比长生殿上洒的那点泪水多得多了。', poem_notes = '马嵬：即马嵬坡，在陕西省兴平县西。安史之乱时，唐玄宗逃到这里，在随军将士的胁迫下，勒死杨贵妃\n长恨歌：唐代诗人白居易所作之诗，写的是唐玄宗宠幸杨贵妃而造成的政治悲剧与爱情悲剧。\n银河：天河。神话传说中，牛郎织女被银河隔开，不得聚会。\n石壕村：“石壕村”二句：唐代诗人杜甫《石壕吏》诗，写在安史之乱中，官吏征兵征役，造成石壕村中一刘老年夫妻惨别的情形。\n长生殿：长生殿：旧址在陕西骊山华清宫内。', poem_appreciation = '唐玄宗李隆基与贵妃杨玉环之间悲欢离合的故事，引发了很多文人墨客的诗情文思。白居易的《长恨歌》，在揭示唐玄宗宠幸杨贵妃而造成政治悲剧的同时，也表达了对二人爱情悲剧的同情。袁枚此诗却能不落俗套，另翻新意，将李、杨爱情悲剧放在民间百姓悲惨遭遇的背景下加以审视，强调广大民众的苦难远非帝妃可比。《长恨歌》和《石壕吏》是有名的诗篇，其创作背景均为安史之乱。它们一以帝王生活为题材，一以百姓遭遇为主旨，恰好构成鲜明的对照。\n\n　　“莫唱当年长恨歌”，莫唱是因为《长恨歌》写的是唐玄宗和杨贵妃的爱情悲剧，对杨贵妃之死，对唐玄宗之无奈，表示了深切的同俏，并歌颂了他们的爱悄专一，为后代小说、戏曲创作提供了题材，如宋乐史的《杨太真外传》、元白朴的《梧桐雨》，明吴世美的《惊鸿记》、清洪异的《长生殿》等等，莫不受其影响。与其大书特书皇帝的悲欢离合，不如深入细致地描写人民群众的生离死别，故“莫唱”二宇又引出了第二句“人间亦自有银河”。“人间”就将银河这个民间传说引入现实生活中来。在唐玄宗统治时期，战争频繁，有开边之战，也有内战，其中规模大的，如用兵吐蕃，讨伐南诏，尤其是安史之乱，伤亡惨重，丁壮或死于战场，或死于摇役，或久戍不归，在人间划出了无数条银河，而最令作者痛心的，要数石壕村的一对老夫妻了。“老翁逾墙走”，老妇河阳役的惨状。杜甫还在同一时期作品《新婚别》中拟写一个“席不暖君床”的新娘子，送别刚刚结婚的新郎官应征入伍，造成一对新婚夫妇“暮婚晨告别”的痛苦。在《垂老别》中，又描写了一个“子孙阵亡尽”的老翁，在风烛残年之时还要应征入伍，与其老伴依依借别、“塌然摧肺肝”的情景。由此可见，“石壕村里夫妻别”是当时极其普遍的社会现象，所以作者感叹地说：“泪比长生殿上多。”长生殿上泪，唐玄宗与杨贵妃的泪没有多少，而要大书特书，深表同情，而不书及比长生殿上泪更多的石壕村。这里，作者严肃地批评了白居易，自有其道理在。似乎可以这样悦，衰枚的这首《马嵬》诗，高出于前人所有咏马嵬之事者。\n\n　　这首诗借吟咏马嵬抒情，提倡诗歌要多反映人民苦难生活的主张，表现了作者进步的文学创作观点。此诗虽为抒情之作，实际是议论之诗。前两句借马嵬为题提出论点，后面两句借用典故论证上述观点。论点和论据的材料本来都是旧的，但作者化陈腐为新奇，使其为自己提出新的观点服务，旧的也变为新的，颇有点铁成金之妙。全诗正如作者自己所云：“借古人往事，抒自己之怀抱”。（《随园诗话》）\n\n　　这首诗最大的艺术特色是比照。全诗两组比照：一组是《长恨歌》与牛郎织女故事的比照。这一比照，不仅批判了白居易的《长恨歌》，而且突出了人间牛郎织女才值得同情。值得注意的是作者运用“银河”，对唐玄宗与杨贵妃讥笑牛郎织女攀进行了再讥笑，很有情趣。第二组是石壕村与长生殿比照。石壕村是人民群众的材落，长生殿是皇帝皇后的夜殿，这一比照，暗示出村里泪是殿上人造成的，马嵬事变，恶果自食，不值得同情，值得同情的倒是劳动人民。这两组比照又有不同，前者深沉，后者浅近，前者重在映照，后者重在对比。两相配合，共同表达了作者民为贵、君为轻的民本思想。', poem_tags = '古诗三百首,咏史怀古,抒情,议论' WHERE poem_title = '马嵬' AND poem_author = '袁枚';
UPDATE edu_poem SET poem_translation = '闲坐无事为你悲伤为我感叹，人生短暂百年时间又多长呢！\n邓攸没有后代是命运的安排，潘岳悼念亡妻只是徒然悲鸣。\n即使能合葬也无法倾诉衷情，来世结缘是多么虚幻的企望。\n只能睁着双眼整夜把你思念，报答你平生不得伸展的双眉。', poem_notes = '邓攸：西晋人，字伯道，官河西太守。《晋书·邓攸传》载：永嘉末年战乱中，他舍子保侄，后终无子。\n潘岳：西晋人，字安仁，妻死，作《悼亡诗》三首。这两句写人生的一切自有命定，暗伤自己无妻无子的命运。\n窅冥：深暗的样子。', poem_appreciation = '首句“闲坐悲君亦自悲”，承上启下。以“悲君”总括上两首，以“自悲”引出下文。由妻子的早逝，想到了人寿的有限。人生百年，也没有多长时间。诗中引用了邓攸、潘岳两个典故。邓攸心地如此善良，却终身无子，这就是命运的安排。潘岳《悼亡诗》写得再好，对于死者来说，也没有什么意义，等于白费笔墨。诗人以邓攸、潘岳自喻，故作达观无谓之词，却透露出无子、丧妻的深沉悲哀。接着从绝望中转出希望来，寄希望于死后夫妇同葬和来生再作夫妻。但是，再冷静思量：这仅是一种虚无缥缈的幻想，更是难以指望的，因而更为绝望：死者已矣，过去的一切永远无法补偿了！诗情愈转愈悲，不能自已，最后逼出一个无可奈何的办法：“惟将终夜长开眼，报答平生未展眉。”诗人仿佛在对妻子表白自己的心迹：我将永远永远地想着你，要以终夜“开眼”来报答你的“平生未展眉”。真是痴情缠绵，哀痛欲绝。', poem_tags = '唐诗三百首,悼亡' WHERE poem_title = '遣悲怀三首·其三' AND poem_author = '元稹';
UPDATE edu_poem SET poem_translation = '隐约可以看见红妆照映着浅溪，薄薄的云带着稀稀的雨洒在地上不成泥。送君地在何处？在戏马台西。\n干涸的水塘昨夜后积满秋水，茂密的树林深处，晚莺啼叫不止。行人断肠之处，青草是那样凄凉迷离。', poem_notes = '浣溪沙：词牌名，本唐教坊曲名，又名《浣沙溪》、《小庭花》等。双调四十二字，五平韵。\n缥缈（piāo miǎo）：高远隐约的样子。红妆：一说为随行女仆，一说为彩云。\n君：指颜、梁。颜即颜复，宇长道，颜渊四十八世孙，赐进士出身，官至中书舍人兼国子监直讲。《宋史》有传。梁即梁先，字吉老，通经学，工小楷。苏轼在徐州曾与二人交游，并有诗。古台：即戏马台。故址在今徐州市彭城县南，相传为项羽所筑，又名掠马台。\n废沼：干涸的池塘。\n凄迷：形容景物凄凉而模糊。善住《送中上人归故里》诗：“野花秋寂历，江草晚凄迷。”', poem_appreciation = '这是一首送别之作。苏轼交游广泛，又多情善感，自通判杭州以来，已写下了大量的别情词，其中不乏脍炙人口的佳作。这首词虽然不甚引人注目，却自有其不可掩的艺术特色。\n\n　　寓情于景。这是这首词一个最显著的特点。全词大半篇幅写景，有点泼墨如云的劲头。上片先写在戏马台西送别友人时的眼前景物：远处，隐约见到一个女郎的盛装映照在浅浅的溪水之中，天空云气稀薄，零星小雨仍在下着，路面上泥泞倒也无多。而随着词人在郊野上行进的脚步，下片也拓展了境界：昨夜大雨滂沱，原来干涸的池沼已经涨满了秋水，天已傍晚，茂密的树林深处传来了黄莺的啼鸣，前方还有扑入人的视野的大片入秋枯萎的野草。这种种景物只有“红妆照浅溪”略具美感，而因“缥缈”充其量带有几分朦胧美，其余基本色调则是灰暗、荒凉。所以尽管词中对有关情事仅略予点明——“送君”、“行人肠断”，见出送别之意，对抒情主人公触目伤怀，感极而悲的情绪，还是可以深切体认的。质言之，词人是借萧瑟、凄凉的秋景，来写伤别之情。\n\n　　诗中有画。这体现了词人在创作中的一种审美追求。这种审美追求，来自对唐代诗人与画家集于一身的王维诗、画作品的深入体悟，也与词人持有诗画一律、诗词一体的艺术见解密不可分。在这首词创作中，词人充分调动视觉、听觉等感官方面的功能，运用白描手法，将远近、高下、隐显、明暗等不同的景物收入画幅，绘出了一长幅秋景图，就是这方面一个成功的例子。\n\n　　对面着笔。这可以从末句“行人肠断草凄迷”看出来的。词人说，面对一片凄凉而模糊的衰草，友人会极度伤心的。单就这一句而论，可以说是情景交融，而从表现别情的角度来说，则是从对面着笔。当然，写友人离别的悲伤，乃是为了深一层地表现词人自己的悲伤，因而有花面相映之妙。\n\n　　这首词大半写景，写景却栩栩如生，或视、或听、或声、或色，描绘一幅真切动人的送别场景，更加深了依依惜别的情意。', poem_tags = '写景,送别' WHERE poem_title = '浣溪沙·缥缈红妆照浅溪' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '专注的凝视着握在手中的半黄橙子，细细慢慢的搓磨片刻大拇指已沾染上独有的香味。清清楚楚的记得，连那衣袖的一角都已满是清香。\n离别已久的人远隔千里。看见这随处绽放的梅花不忍采摘。写好的书信却没有大雁能够传递，怎样才能让它到达收信人的手里呢。', poem_notes = '脉脉：凝视貌。\n擘：大拇指。\n分明：明确；清楚。\n关山：关隘山岭。', poem_tags = '怀人,思念' WHERE poem_title = '忆秦娥·情脉脉' AND poem_author = '程垓';
UPDATE edu_poem SET poem_translation = '在卖花人的担子上，买得一枝含苞待放的花。那晨曦的露珠也在那花色之中留下痕迹，让花显得更楚楚动人。我怕丈夫看了花之后犯猜疑，认为我的容颜不如花的漂亮。我这就将梅花插在云鬓间，让花与我的脸庞并列，教他看一看，到底哪个比较漂亮。', poem_notes = '减字木兰花：词牌名。\n一枝春欲放：此指买得一支将要开放的梅花。\n泪：指形似眼泪的晶莹露珠。\n奴：作者自称。\n云鬓：形容鬓发多而美。\n“徒要”一句：意谓自己比花更好看。徒：只、但。郎：在古代既是妇女对丈夫的称呼，也是对她所爱男子的称呼。这里当指前者。比并：对比。', poem_appreciation = '这首词作于建中靖国年间，其时词人与夫君赵明诚新婚燕尔，心中充满对爱情的热情挚着。全篇截取了作者新婚生活的一个侧面，显示她放纵恣肆的独特个性。 　\n\n　　上片主旨是买花。宋朝都市常有卖花担子，一肩春色，串街走巷，把盎然生趣送进千家万户。似乎小丫环入报以后，女主人李清照随即作了吩咐，买下一枝最满意的鲜花。整个上片便是截取了买花过程中最后一个画面，所写的便是女主人公手执鲜花，满怀深情地进行欣赏。“春欲放”三字，表达了她对花儿的由衷喜爱，其中“春”字用得特别好，既可以指春色、春光、春意和春天，也可以借指花儿本身。“春” 字境大，能给人以无穷的美感和联想。下面“泪染轻匀”二句，写花的容态。这花儿被人折下，似乎为自己命运的不幸而哭泣，直到此时还泪痕点点，愁容满面。着一“泪”字，就把花拟人化了，再缀以“轻匀”二字，便显得哀而不伤，娇而不艳，其中似乎渗透着女主人对它的同情与爱抚。前一句为虚，出自词人的想象；后一句属实，摹写了花上的露珠。“犹带彤霞晓露痕”，花朵上披着彤红的朝霞，带着晶莹的露珠，不仅显出了花之色彩新鲜，而且点明时间是清晨，整个背景写得清新绚丽，恰到好处地烘托了新婚的欢乐与甜蜜。 　\n\n　　下片主旨写戴花。首先，作者从自己一方说起，侧重于内心刻画萋。“怕郎猜道，奴面不如花面好”，活活画出一位新嫁娘自矜、好胜甚至带有几分嫉忌的心理。她青年妇女中，本已感到美貌超群，但同“犹带彤霞晓露痕”的鲜花相比，似乎还不够娇美，因此怀疑新郎是否爱她。这里表面上是说郎猜疑，实际上是她揣度郎心，曲笔表达，轻灵有致。同上片相比，前面是以花拟人，这里是以人比花，角度虽不同，但所描写的焦点都是新娘自己。接着二句，是从人物的思想写到人物的行动。为了争取新郎的欢爱，她就把花儿簪鬓发上，让新郎看看哪一个更美。然却终未说出谁强，含蓄蕴藉，留有余味。“云髻斜簪”，丰神如画。这里李清照，写出了一点闺房的乐趣。 　\n\n　　全篇通过买花、赏花、戴花、比花，生动地表现了年轻词人天真、爱美情和好胜的脾性。可谓达到了“乐而不淫”的艺术境界，全词语言生动活泼，富有浓郁的生活气息，是一首独特的闺情词。', poem_tags = '宋词精选,春天,生活,写花' WHERE poem_title = '减字木兰花·卖花担上' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '译文 柳树的青色却是让人伤心的颜色，多少个离别的人就是在这样的情景中分别。 附近的关卡周围也全是送别的人，每个人都折柳来送离别的友人。', poem_tags = '赠别,伤春' WHERE poem_title = '青门柳' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '我漂泊在江汉一带，思念故土却不能归，在茫茫天地之间，我只是一个迂腐的老儒。\n看着远浮天边的片云和孤悬暗夜的明月，我仿佛与云共远、与月同孤。\n我虽已年老体衰，时日无多，但一展抱负的雄心壮志依然存在；面对飒飒秋风，我觉得病情渐有好转。\n自古以来养老马是因为其智可用，而不是为了取其体力，因此，我虽年老多病，但还是能有所作为的。', poem_notes = '江汉：该诗在湖北江陵公安一带所写，因这里处在长江和汉水之间，所以诗称“江汉”。\n腐儒：本指迂腐而不知变通的读书人，这里是诗人的自称，含有自嘲之意。是说自己虽是满腹经纶的饱学之士，却仍然没有摆脱贫穷的下场；也有自负的意味，指乾坤中，如同自己一样的心忧黎民之人已经不多了。\n“片云”两句：这句为倒装句，应是“共片云在远天，与孤月同长夜”。\n落日：比喻自己已是垂暮之年。\n病欲苏：病都要好了。苏：康复。\n存：留养。老马：诗人自比。典出《韩非子·说林上》中“老马识途”的故事：齐桓公讨伐孤竹后，返回时迷路了，他接受管仲的“老马之智可用”的建议，放老马而随之，果然找到了正确的路。', poem_appreciation = '句解 　　江汉思归客,乾坤一腐儒. 　　漂泊江汉,我这思归故乡的天涯游子,在茫茫天地之间,只是一个迂腐的老儒.“江汉“,长江、汉水之间.首联表达出诗人客滞江汉的窘境,有自嘲意.“思归客“是杜甫自谓,因为身在江汉,时刻思归故乡,但思归而不得,饱含天涯沦落的无限辛酸.“乾坤“,即天地.“腐儒“,迂腐的读书人,这里实际是诗人自指不会迎合世俗.如果说前一句还只是强调诗人飘泊在外的思乡之心,后一句则将自己在天地间的渺小孤独感吐露无遗.诗人原来的抱负是要经天纬地的,然而越到人生的最后阶段,他越是痛感自己的渺小无力.其中的痛楚和无奈该有多深! 　　片云天共远,永夜月同孤. 　　像飘荡在远天的片云一样远客异乡;与明月一起,孤独地面对漫漫长夜.颔联为工对.“天共远“,承江汉客;“月同孤“,承一腐儒.诗人表面上是在写片云孤月,实际是在写自己.他把自己的感情和身外的景物融为一片,慨叹自己飘泊无依.不过,在明月的皎洁和孤清中,我们又体会到了诗人的孤高自许,他的心,仍然是光明的.“永夜“,长夜. 　　落日心犹壮,秋风病欲疏. 　　我虽已到暮年,就像日将落西山,但一展抱负的雄心壮志依然存在;面对飒飒秋风,我不仅没有悲秋之感,反而觉得病逐渐好转.颈联为借对,“落日“比喻暮年,而非写实.“秋风“句是写实.诗的意境阔大而深沉,形象地表达出诗人积极用世、身处逆境而壮心不已的精神,“疏“,复苏. 　　古来存老马,不必取长途. 　　自古以来存养老马是因为其智可用,而不必取其体力,跋涉长途.尾联用老马识途的典故,比喻自己身虽年老多病,但智慧犹可用,还能有所作为.《韩非子·说林上》里讲,春秋时管仲随齐桓公伐孤竹,春往冬返,迷失道路.管仲提议用老马领路,于是找到了归途.“老马“是诗人自比. ▲', poem_tags = '思归,壮志' WHERE poem_title = '江汉' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '燕赵一带自古就称说多有慷慨重义、悲壮高歌的豪杰之士。董生参加进士考试，接连几次未被主考官录取而不得志，怀抱着杰出的才能，心情忧郁地想去燕赵地区（谋职）。我料知他此去一定会有所遇合，（受到赏识）。董生努力吧！\n\n　　像你这样不走运，即使一般仰慕正义、力行仁道的人都会同情爱惜你的，更何况燕赵一带豪杰之士的仰慕仁义是出自他们的本性呢！然而我曾听说风俗是随着教化而改变的，我怎么能知道那里的风气跟古时说的有什么不同呢？姑且通过你这次的前往测定一下吧。董生努力吧！\n\n　　我因为你的这次前往而产生一些感想。请替我凭吊一下望诸君（乐毅）的墓，并且到那里的集市上去看看，还有像过去的屠狗者一类的埋没在草野的志士吗？替我向他们致意说：“有圣明的天子在上面当政，可以出来做官（为国家效力）了！”', poem_notes = '燕、赵：借指的河北一带。\n慷慨悲歌之士：用悲壮的歌声抒发内心悲愤的人，多指有抱负而不得施展的人。\n有司：这里是指礼部主管考试的官。\n利器：锐利的武器，这里比喻杰出的才能。\n郁郁适兹土：忧郁地到那个地方去。意思是董生想去燕赵地区谋职。适，到……去。兹，这。兹土，指燕赵之地，当时受地方割据势力统治。\n有合：有所遇合，指受到赏识和重用。\n夫以子之不遇时：像你这样不走运的人。\n慕义强（qiǎng)仁者：仰慕正义、力行仁道的人。\n矧（shěn)：何况。\n出乎其性：（仰慕正义）来自他们的本性。这句意思是，燕赵之士由于有这样的本性而更加同情董生。\n风俗与化移易：风俗随着教化而改变。与，跟随。易，改变。\n吾恶（wū)知其今不异于古所云邪：我怎么能知道那里的风气跟古时说得有什么不同呢？恶，怎么。\n聊以吾子之行卜之也：姑且凭你这次的前往测定一下吧。聊：姑且。卜：测验、判断。\n望诸君：即战国时燕国名将乐毅，后因政治失意，离燕至赵，赵封他为望诸君。望诸，古泽名，在河南东北部，又称“孟诸”。\n屠狗者：凡指高渐离一类埋没在草野的志士。高渐离，荆轲的朋友，他的职业是屠狗。荆轲死后，他也曾行刺秦始皇，失败后被杀。据《史记.刺客列传》记载，战国时燕国有以屠狗为业的义士，这里泛指隐于市廛暂不得志的侠义之士。\n谢：告诉。\n出而仕：出来做官。', poem_appreciation = '从文章的题目看，韩愈的《送董邵南游河北序》应是为送董邵南游河北作的送别赠序，但细思之，又有不同情味。\n\n　　其一，当时的河北是藩镇割据的地方，韩愈坚决主张削藩平镇，实现唐王朝的统一。因而在他看来，若有人跑到河北去投靠藩镇，那就是“从贼”，必须鸣鼓而攻之。\n\n　　其二，韩愈为了实现唐王朝的统一，很希望朝廷能够招揽人才，但在这一点上朝廷使他大失所望。所以他在许多诗文中，都替自己与他人抒发过怀才不遇的感慨。他有一篇《嗟哉董生行》的诗，也是为董邵南写的，诗中小序有这样的语句：“县人董生邵南隐居行义于其中，刺史不能荐，天子不闻名声，爵禄不及门。”全诗在赞扬董生“隐居行义”的同时，也对“刺史不能荐”表示遗憾。这位董生隐居了一段时间，大约不安于“天子不闻名声，爵禄不及门”的现状，终于主动出山了，选择了去河北投靠藩镇。对于董生的“郁郁不得志”，韩愈自然是抱有一定的同情的。\n\n　　在董生临行之前，韩愈要送一篇序文给他。但这样的序文是很难措辞的。赞成他去吗？固然如此，因对他有一定的同情，但若赞成，则违背了韩愈自己的政治主张；阻止他去吗？说明那是“从贼”，那就是变成了“留行”，而不是送别，也不合“赠序”的要求，更何况对于“怀抱利器”的董生去求发展（藩镇名义上还是唐王朝的一部分）提出反对意见，毕竟是说不通的，作者毕竟对董生怀有一定的同情。由此看来，这篇“赠序”实在是难以下笔了。\n\n　　但韩愈毕竟是文章大家，倡导“惟陈言之务去”的他，写文章常常因难见巧，以巧取胜。这篇赠序的构思、用语就颇为精巧。\n\n　　文章一上来就先赞美河北“多感慨悲歌之士”；接着即叙述董生“怀抱利器”而“不得志于有司”，因而要到河北去，“吾知其必有合也”，这很有点为董生预贺的味道。再加上一句：“董生勉乎哉！”仿佛是说：你就要找到出路了，努力争取吧！除此外，作者还深入一层：像你这样怀才不遇的人，只要是“慕义强仁”的人都会爱惜的，何况那些“仁义出乎其性”的“燕赵之士”呢？又将河北赞美一通，为董生贺。意思仿佛是：你的出路的确找对了！\n\n　　这其实都是些反话，所谓的“心否而词唯”。\n\n　　作者在赞美河北时有意识地埋伏了一个“古”字。为什么这样说呢？因为作者特意在“古”字后面用了一个“称”，使“古”隐藏其中，不那么引人注目。“古称”云云，即历史上如何如何。历史上说，“燕赵多感慨悲歌之士”，那呢？还是那样，或许已不是那样了。后文用一个“然”突转，将笔锋从“古称”移向现实，现实怎样，不言而喻了。由此可见，文章写“古”正是为了衬“今”，为下文写“今”蓄势。\n\n　　如今之燕赵是不是还多“感慨悲歌之士”呢？在作者心中，这个答案当然是否定的。但作者并不立刻否定，也不明确否定，而是提了一个原则：“风俗与化移易”。既然是“风俗与化移易”，那言外之意不言自明。既然河北已被“反叛朝廷”的藩镇“化”了好多年，其风俗怎么能不变呢？既然变了，那也就不再多“感慨悲歌之士”了，那么你董生到那里去，就不能“有合”。\n\n　　当时的藩镇为了壮大自己的势力，“竞引豪杰为谋主”。董生到河北去，“合”的可能性是很大的，他将会受到藩镇的重用。果如此，岂不证明了“今”之燕赵“不异于古所云”了吗？但是作者是早有埋伏的。他说“燕赵古称多感慨悲歌之士”，又说“感慨悲歌”的“燕赵之士”“仁义出乎其性”。预言董生与“仁义出乎其性”的人“必有合”，这是褒奖董生的话，但也是作者埋下的伏笔：如果你能同如今的“风俗与化移易”的藩镇们相合，那只能证明你已经丧失了“仁义”。前面的“扬”是为了后面的“抑”。“吾恶知其今不异于古所云邪，聊以吾子之行卜之也”的“邪”和“卜”，与其说是卜燕赵，毋宁说是卜董生此行的正确与错误，使语气婉转，又暗含警戒之意。“董生勉乎哉！”此处当为“好自为之”讲，勉其不可“从贼”也。\n\n　　最后一段，作者借原燕国大将乐毅被迫逃到赵国去的故事，来暗示董生。“为我吊望诸君之墓”，是提醒董生应妥善处理他和唐王朝的关系。还进一步照应前面的“古”字，委托他到燕市上去看看还有没有高渐离那样的“屠狗者”；如果有的话，就劝其入朝廷效忠。连河北的“屠狗者”都要劝他入朝，则对董生投奔河北依附藩镇之举所抱态度也就不言而喻了。\n\n　　文章表面上一直是送董生游河北。开头就预言前去“必有合”，是送他去；第二段虽怀疑燕赵的风俗可能变了，但要“以吾子之行卜之”，还是要送他去；结尾托他去吊望诸君之墓、劝谕燕赵之士归顺朝廷，仍然是送他去。总之，的确是一篇送行的文章，但送之正是为了留之，微情妙旨，全寄于笔墨之外。', poem_tags = '古文观止,初中文言文,送别,赠序' WHERE poem_title = '送董邵南游河北序' AND poem_author = '韩愈';
UPDATE edu_poem SET poem_translation = '深秋惨淡的阳光渐渐地照到镂刻着花纹的窗子上，梧桐树也应该怨恨夜晚来袭的寒霜。酒后更喜欢品尝团茶的浓酽苦味，梦中醒来特别适宜嗅闻瑞脑那沁人心脾的余香。\n秋天快要过去了，依然觉得白昼非常漫长。比起王粲《登楼赋》所抒发的怀乡情，我觉得更加凄凉。不如学学陶渊明，沉醉酒中以摆脱忧愁，不要辜负东篱盛开的菊花。', poem_notes = '萧萧：凄清冷落的样子。原为象声词，如风声、雨声、草木摇落声、马蹄声。《诗经·小雅·车攻》有“萧萧马鸣”，《楚辞·九怀·蓄英》有“秋风兮萧萧”，《史记·刺客列传》有“风萧萧兮易水寒”。琐窗：镂刻连锁纹饰之窗户。多本作锁窗，当以琐窗为胜。\n酒阑：酒尽，酒酣。阑：残，尽，晚。司马迁《史记·高祖本纪》有“酒阑”，裴骃集解曰“阑，言希也。谓饮酒者半罢半在，谓之阑。”文选·谢庄《宋孝武宣贵妃诔》有“白露凝兮岁将阑”，李善注曰“阑，犹晚也”。团茶：团片状之茶饼，饮用时则碾碎之。宋代有龙团、凤团、小龙团等多种品种，比较名贵。欧阳修《归田录》卷二：“茶之品，莫贵于龙凤，谓之团茶，凡八饼重一斤。”\n瑞脑：即龙涎香，一名龙脑香。\n仲宣：王粲，字仲宣，汉末文学家，“建安七子”之一。其《登楼赋》抒写去国怀乡之思，驰名文坛。\n随分：随便，随意。尊前：指宴席上。尊：同“樽”。\n东篱菊蕊黄：化用陶渊明《饮酒二十首》的“采菊东篱下”句。', poem_appreciation = '这首词写秋景，寄乡愁，是一首典型的易安晚期作品。通篇从醉酒写乡愁，悲慨有致，凄婉情深。此词开头两句写寒日梧桐，透出无限凄凉。“萧萧”这里是萧条、寂寞之意。“琐窗”是雕有连琐图案的窗棂。“上”字写出寒日渐渐升高，光线慢慢爬上窗棂，含着一个时间的过程，表明作者久久地观看着日影，见出她的百无聊赖。梧桐早凋，入秋即落叶，“恨霜”即恨霜落其叶。草木本无知，所以，梧桐之恨，实为人之恨。从而借景抒情，绘出了作者的孤独和寂寥。因为心情不好，只好借酒排遣，饮多而醉，不禁沉睡，醒来唯觉瑞胸熏香，沁人心脾。三、四两句分别着一“喜”字“宜”字，似乎写欢乐，实际它不是写喜而是写悲。“酒阑”谓饮酒结束的时候。“团茶”即茶饼，宋代有为进贡而特制的龙团、凤团，印有龙凤纹，最为名贵。茶能解酒；特喜苦茶，说明酒饮得特别多；酒饮得多，表明愁重。“瑞胸”，熏香名，又名龙脑，以龙脑木蒸馏而成。“宜”表面似乎是说香气宜人，实则同首句的寒日一样，是借香写环境之清寂，因为只有清冷寂静的环境中，熏香的香气才更易散发，因而变得更深更浓，更能使人明显感觉到。\n\n　　上片叙事，主写饮酒之实“秋已尽，日犹长”写作者个人对秋的感受。“仲宣”句用典，以王粲思乡心情自况。王粲，字仲宣，山阳高平（今山东邹县）人，十七岁时因避战乱，南至荆州依刘表，不受重视，曾登湖北当阳县城楼，写了著名的《登楼赋》，抒发壮志未酬、怀乡思归的抑郁心情。这两句透露出词人孤身漂泊，思归不得的幽怨之情。深秋本来使人感到凄清，加以思乡之苦，心情自然更加凄凉。“犹”、“更”这两个虚词，一写主观错觉，一写内心实感，都是加重描写乡愁。结句是为超脱语。时当深秋，篱外丛菊盛开，金色的花瓣光彩夺目，使她不禁想起晋代诗人陶潜“采菊东篱下，悠然见南山”的诗句，自我宽解起来：归家既是空想，不如对着尊中美酒，随意痛饮，莫辜负了这篱菊笑傲的秋光。“随分”犹云随便、随意。下片写饮酒之因，是对上片醉酒的说明：本来是以酒浇愁，却又故作达观之想，而表面上的达观，实际隐含着无限乡愁。李清照的这首词是其晚年流寓越中所作，词中表露的乡愁因和故国沦丧，流离失所的悲苦结合起来，其中的忧愤更深。', poem_tags = '秋天,写景,借古寄怀,思乡,抒情' WHERE poem_title = '鹧鸪天·寒日萧萧上琐窗' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '四野的战争还没得到安平，我已经老了却得不到安宁。\n子孙们在战场上尽都殉难，兵荒马乱又何需老命苟全。\n扔掉拐杖出门去拼搏一番，同行的人也为我流泪辛酸。\n庆幸牙齿完好胃口还不减，悲伤身骨瘦如柴枯槁不堪。\n男儿既披戴盔甲从戎征战，也只好长揖不拜辞别长官。\n听到老伴睡路上声声哀唤，严冬腊月仍然是裤薄衣单。\n明知道死别最后一次见面，贫贱夫妻怎么不怜她饥寒。\n今朝离去永不能回返家园，犹听她再三劝我努力加餐。\n土门关深沟高垒防守坚严，杏园镇天险足恃偷渡实难。\n形势变不比当年邺城之战，纵然是死去时间也有宽限。\n人生世上都有个离合悲欢，哪管你饥寒交迫衰老病残！\n想以前少壮年华国泰民安，竟不免徘徊踟蹰长吁短叹。\n普天下应征入伍戒备森严，战争的烽火已弥漫了岗峦。\n尸骸积山一草一木变腥膻，流血漂杵河流平原都红遍。\n战火遍地何处觅人间乐园，勤王杀敌又岂敢犹豫盘桓。\n毅然地抛弃茅棚奔赴前线，天崩地裂真叫人摧断肺肝！', poem_notes = '四郊：指京城四周之地。\n垂老：将老。\n焉用：犹哪用。身独完：独自活下去。完，全，即活。\n投杖：扔掉拐杖。\n骨髓干：形容筋骨衰老。\n介胄：犹甲胄，铠甲和头盔。\n长揖：不分尊卑的相见礼，拱手高举，自上而下。上官：指地方官吏。\n岁暮：年底。\n孰知：即熟知，深知。\n加餐：多进饮食。\n土门：即土门口，在今河阳孟县附近，是当时唐军防守的重要据点。壁：壁垒。\n杏园：在今河南汲县东南，为当时唐军防守的重要据点。\n势异：形势不同。\n岂择：岂能选择。端：端绪、思绪。\n迟回：徘徊。竟：终。\n被冈峦：布满山冈。\n丹：红。流血多，故川原染红。\n盘桓：留恋不忍离去。\n蓬室：茅屋。\n塌然：形容肝肠寸断的样子。摧肺肝：形容极度悲痛。', poem_appreciation = '在平定安史之乱的战争中，唐军于邺城兵败之后，朝廷为防止叛军重新向西进扰，在洛阳一带到处征丁，连老翁老妇也不能幸免。《垂老别》就是抒写一老翁暮年从军与老妻惜别的苦情。\n\n　　一开头，诗人就把老翁放在“四郊未宁静”的时代的动乱气氛中，让他吐露出“垂老不得安”的遭遇和心情，语势低落，给人以沉郁压抑之感。他慨叹着说：“子孙都已在战争中牺牲了，剩下我这个老头，又何必一定要苟活下来！”话中饱蕴着老翁深重的悲思。战火逼近，官府要他上前线，于是老翁把拐杖一扔，颤巍巍地跨出了家门。“投杖出门去”，笔锋一振，暗示出主人公是一个深明大义的老人，他知道在这个多难的时代应该怎样做。但是他毕竟年老力衰了，同行的战士看到这番情景，不能不为之感叹唏嘘。“同行为辛酸”，就势跌落，从侧面烘托出这个已处于风烛残年的老翁的悲苦命运。“幸有牙齿存，所悲骨髓干。”牙齿完好无缺，说明还可以应付前线的艰苦生活，表现出老翁的倔强；骨髓行将榨干，又使他不由得悲愤难已。这里，语气又是一扬一跌，曲折地展示了老翁内心复杂的矛盾和变化。“男儿既介胄，长揖别上官。”作为男子汉，老翁既已披上戎装，那就义无反顾，告别长官慷慨出发了。语气显得昂扬起来。\n\n　　接下去，就出现了全诗最扣人心弦的描写：临离家门的时候，老翁原想瞒过老妻，来个不辞而别，好省去无限的伤心。谁知走了没有几步，迎面却传来了老妻的悲啼声。他唯一的亲人已哭倒在大路旁，褴褛的单衫正在寒风中瑟瑟抖动。这突然的发现，使老翁的心不由一下子紧缩起来。接着就展开了老夫妻间强抑悲痛、互相爱怜的催人泪下的心理描写：老翁明知生离就是死别，还得上前去搀扶老妻，为她的孤寒无靠吞声饮泣；老妻这时已哭得泪流满面，她也明知老伴这一去，十成是回不来了，但还在那里哑声叮咛：“到了前方，你总要自己保重，努力加餐呀！”这一小节细腻的心理描写，在结构上是一大跌落，把人物善良凄恻、愁肠寸断、难舍难分的情状，刻画得入木三分。正如吴齐贤《杜诗论文》所说：“此行已成死别，复何顾哉？然一息尚存，不能恝然，故不暇悲己之死，而又伤彼之寒也；乃老妻亦知我不返，而犹以加餐相慰，又不暇念己之寒，而悲我之死也。”究其所以感人，是因为诗人把“伤其寒”、“劝加餐”这类生活中极其寻常的同情劝慰语，分别放在“是死别”、“必不归”的极不寻常的特定背景下来表现。再加上无可奈何的“且复”，迥出人意的“还闻”，层层跌出，曲折状写，便收到了惊心动魄的艺术效果。\n\n　　“土门”以下六句，用宽解语重又振起。老翁毕竟是坚强的，他很快就意识到必须从眼前凄惨的氛围中挣脱出来。他不能不从大处着想，进一步劝慰老妻，也似乎在安慰自己：“这次守卫河阳，土门的防线还是很坚固的，敌军要越过黄河上杏园这个渡口，也不是那么容易。情况和上次邺城的溃败已有所不同，此去纵然一死，也还早得很哩！人生在世，总不免有个聚散离合，哪管你是年轻还是年老！”这些故作通达的宽慰话语，虽然带有强自振作的意味，不能完全掩饰老翁内心的矛盾，但也道出了乱世的真情，多少能减轻老妻的悲痛。“忆昔少壮日，迟回竟长叹。”眼看就要分手了，老翁不禁又回想起年轻时候度过的那些太平日子，不免徘徊感叹了一阵。情思在这里稍作顿挫，为下文再掀波澜，预为铺垫。\n\n　　“万国”以下六句，老翁把话头进一步引向现实，发出悲愤而又慷慨的呼声：“睁开眼看看吧！如今天下到处都是征战，烽火燃遍了山冈；草木丛中散发着积尸的恶臭，百姓的鲜血染红了广阔的山川，哪儿还有什么乐土？我们怎敢只想到自己，还老在那里踌躇徬徨？”这一小节有两层意思。一是逼真而广阔地展开了时代生活的画面，这是山河破碎、人民涂炭的真实写照。他告诉老妻：人间的灾难并不只是降临在他们两人头上，言外之意是要想开一些。一是面对凶横的敌人，他们不能再徘徊了，与其束手待毙，还不如扑上前去拼一场。通过这些既形象生动又概括集中的话语，诗人塑造了一个正直的、豁达大度而又富有爱国心的老翁形象，这在中国诗史上还不多见。从诗情发展的脉络来看，这是一大振起，难舍难分的局面终将结束了。\n\n　　“弃绝蓬室居，塌然摧肺肝。”到狠下心真要和老妻诀别离去的时候，老翁突然觉得五脏六腑内有如崩裂似的苦痛。这不是寻常的离别，而是要离开生于斯、长于斯、老于斯的家乡。长期患难与共、冷暖相关的亲人，转瞬间就要见不到了，此情此景，老翁难以承受。感情的闸门再也控制不住，泪水汇聚成人间的深悲巨痛。这一结尾，情思大跌，却蕴蓄着丰厚深长的意境：独行老翁的前途将会怎样，被扔下的孤苦伶仃的老妻将否陷入绝境，仓皇莫测的战局将怎样发展变化，这一切都将留给读者去体会、想象和思索。\n\n　　这首叙事短诗，并不以情节的曲折取胜，而是以人物的心理刻画见长。诗人用老翁自诉自叹、慰人亦即自慰的独白语气来展开描写，着重表现人物时而沉重忧愤、时而旷达自解的复杂的心理状态；而这种多变的情思基调，又决定了全诗的结构层次，于严谨整饬之中，具有跌宕起伏、缘情宛转之妙。\n\n　　杜甫高出于一般诗人之处，主要在于他无论叙事抒情，都能做到立足生活，直入人心，剖精析微，探骊得珠，通过个别反映一般，准确传神地表现他那个时代的生活真实，概括劳苦人民包括诗人自己的无穷辛酸和灾难。他的诗，博得“诗史”的美称，绝不是偶然的。', poem_tags = '叙事,战争,惜别' WHERE poem_title = '垂老别' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '冬天的夜晚万籁静寂无声。已近五更时分被子却还是冰冰冷冷。炉中沉香已燃尽，灯光昏暗，孤冷凄清，这样的夜何时才是尽头。窗外也只有那结成的霜花伴着明月。\n孤寂寒冷夜，想着那迎风绽放的梅花也是烦恼的无法入眠的。我在想着梅花而梅花也在念着我，互相牵挂着。起床时看到那玉瓶中的水已全都凝结成冰。', poem_notes = '稜稜：严寒貌。\n关情：动心，牵动情怀。', poem_appreciation = '黄升是一位著名的词选家，其词如“晴空冰柱”，今读此词，颇有此感。\n\n　　上片写夜寒苦吟之景状。词人生在南宋中期，早年放弃科举，遯迹林泉，吟咏自适，填词是他精神生活中一个重要组成部分。从这首词看，即使夜阑人静之时，他还在苦吟不已。起二句云：“万籁寂无声，衾铁稜稜近五更。”夜，是静极了，一点动静也没有。只有深夜不睡的人，方能有此体会。“稜稜”二字，使人感到布衾硬得好像有稜角一般，难以贴体。至“香断灯昏吟未稳，凄清”二句，词人则把注意力从被窝移向室内：炉中沉香已尽，残灯如豆，昏暗异常，凄清异常。至“只有霜华伴月明”，词人又把注意力转向室外，描写了明月高悬、霜华遍地的景象。五句三个层次，娓娓写来，自然而又逼真。“吟未稳”者，吟诗尚未觅得韵律妥贴、词意工稳之句也，三字写出词人此时之所为，可称上片之词眼。由于“吟未稳”，故觉深夜寂静被子寒冷，香断灯昏；又由于“吟未稳”，才觉霜华伴月，碧空无边。而“凄清”二字，则烘托了本文的整个氛围，不贯穿整文，随处可以感到。由此可见，词的结构是井然有序、浑然一体的。\n\n　　下片词人从自己的“吟未稳”联想到梅花的“睡不成”。冰寒大地，长夜无眠，词人居然不说自己感到烦恼，却为梅花设身处地着想，说它该是烦恼得睡不成了。此语奇警，设想绝妙。接下去二句说：“我念梅花花念我，关情。”此句点明不仅他在想着梅花，梅花也怜念起他来了。他们竟成为一对知心好友！\n\n　　这种构思，确实是奇特异常；这种格调和意境，确实是空幻的。它非常形象地勾画了一个山中隐士清高飘逸的风采。它的妙处尤其表现在将梅花拟人化。\n\n　　结句“起看清冰满玉瓶”，跟以上两句不可分割，互为联系，词中句断乃为韵律所限。因为词人关切寒夜中梅花，于是不顾自己冷暖，披衣而出，结果看到，玉瓶中的水已结成了冰。至于梅花呢，他在词中未提及，留给读者想象的空间。蕴意深远，饶有余味。如果词人在词中将梅花说尽了，说梅花冻得不成样子，或说梅花凌霜傲雪，屹立风中，那就一览无余，毫无诗意了。由此可见词人手法之高明。\n\n　　从整个词来说，晶莹快洁，恰似玉树临风；托意高远，说它的风格如“晴空冰柱”，不是很相宜么？', poem_tags = '宋词精选,冬天,梅花,寓人' WHERE poem_title = '南乡子·冬夜' AND poem_author = '黄升';
UPDATE edu_poem SET poem_tags = '读书,心情' WHERE poem_title = '读书' AND poem_author = '皮日休';
UPDATE edu_poem SET poem_translation = '清晨卷起结着清霜的幕帘，呵暖双手试梳新式梅花妆。都因为内心有太多离愁别恨，所以把双眉涂得像远山那么长。\n回想那如烟往事，痛惜流逝的年华，更容易使人感伤。想唱歌又敛容，想欢笑眉头却紧皱，这日子最令人痛断肝肠。', poem_notes = '诉衷情：原为唐教坊曲名，后用为词牌名。唐温庭筠取《离骚》“众不可户说兮，孰云察余之中情”之意，创制此调。双调四十四字，上下片各三平韵。\n轻霜：薄霜，表明时节已是初秋。\n试梅妆：谓试着描画梅花妆。梅妆，“梅花妆”的省称。梅花妆是一种美妆，始于南朝宋寿阳公主。\n缘：因为。离恨：因别离而产生的愁苦。\n远山：指远山眉。形容把眉毛画得又细又长，有如水墨珈的远山形状。比喻离恨的深长。\n流芳：流逝的年华。\n敛（liǎn）：收敛表情。\n颦（pín）：皱眉，忧愁的样子。\n断人肠：悲痛之极，谓之断肠。', poem_appreciation = '这首词抒写女子的离愁别恨，用字并不多，几个场景切换却生动地刻画了女主人公复杂的内心世界。词以形传神，词人从环境描写到人物外貌描写，继而是女子的生活片段，表现出了女子内心的苦闷，对于逝水流年的追忆以及痛苦的生活经历。\n\n　　欧阳修的词，和他的诗文风格是很不一样的，说不上放荡，但至少是放得开。所以他的词中说男女之情，或写儿女之态的不少，而且写得很好，说明他其实并不是一个古板的人。题目叫“眉意”，就是以眉为题。古代女子化妆，画眉是最重要的步骤之一，画的花样也多，所以古人甚至以“蛾眉”为美丽女子的代称。《诗经·卫风·硕人》中就以“螓首蛾眉，巧笑倩兮，美目盼兮”描写美人。屈原的《离骚》中，也已经有“众女嫉余之蛾眉兮，谣诼谓余以善淫”的诗句。后人诗文中就举不胜举了。\n\n　　上片叙事，写画眉。“清晨帘幕卷轻霜”是环境描写，冬日的早晨，寒气袭人。“呵手试梅妆”，以素描手法勾勒出一幅图画：女主人公于冬日清晨临镜梳妆，呵气温暖着纤细的双手，精心地在额上勾勒着梅花妆。“帘幕卷”，暗示她已起床，虽然时间尚早，却要起床梳妆，表现出日常生活的艰辛。“轻霜”，暗示气候只微寒。因微寒而呵手，可见女主人公的娇怯，也体现出她迫于生计才如此辛苦。“试梅妆”，则突出她的秀慧俏丽。\n\n　　后二句写她内心本有离愁别恨，所以把眉儿“故画作远山长”。古人有以山水喻别离的习惯，眉黛之长，象征水阔山长。用远山比美人之眉，由来已久。托名汉伶玄《飞燕外传》就有“女弟合德入宫，为薄眉，号远山黛”之句。此二句极有情致。女子画了一个长眉，这是很正常的。唐明皇《好时光·宝髻偏宜宫样》云：“眉黛不须张敞画，天教入鬓长。”可见长眉是美的标志。眉毛画作“远山长”，也是平常的事。唐代张泌《妆楼记》说唐明皇避“安史之乱”逃到成都后，让画工作《十眉图》，也就是十种眉毛的画法。明代杨慎《丹铅续录·十眉图》中重新总结了这些眉式的图谱，计有鸳鸯眉、远山眉、五岳眉、三峰眉、垂珠眉、却月眉、分梢眉、涵烟眉、横云眉、倒晕眉共十种。“远山眉”就是其中一种。托名刘歆《西京杂记》卷二说“（卓）文君姣好，眉色如望远山”；晏几道《生查子·远山眉黛长》说李师师“远山眉黛长，细柳腰肢袅”。可见“远山眉”是很好看的，据说是一种淡淡的细长眉妆。这里，从歌女一番对镜梳妆、顾影自怜的举动中，尤其是从她描眉作“远山长”当中，可以窥见她内心的凄苦孤独和对爱情的渴望。词人高明的地方，是融情入景。把眉画作“远山”，不是因为它好看，而是“都缘自有离恨”，把画眉与思人联系得十分巧妙。\n\n　　下片抒情，写蹙眉。上片说到思人，下片就很自然地过渡到“思往事，惜流芳，自成伤”了。从举止、容色中，词人窥测女子有感伤的情绪，大概她正在思量着难追的往事，惋惜着易逝的芳年，内心伤感不已。此三句，极其成功地对女主人公进行了心理刻画，仅用寥寥数语便便充分表现了她内心的痛楚和感伤。\n\n　　结尾三句，以“拟歌先敛，欲笑还颦，最断人肠”的情态，活灵活现地刻画出女主人公无法获得幸福生活而为生计被迫卖唱的痛苦心情，道出了她对于自身命运不能自主而只得让美好年华虚度在陪人欢笑上的凄苦和悲凉，把一个心有千千结而又不得不强颜欢笑的女子写活了。由于她有感伤，触处皆愁，所以欲歌之际，却先敛容不欢；将笑之时，也还带恨含颦。她诚于中而形于外，人则见其外而知其中，故此情此态，最得知心者怜爱而为之魂销，因魂销乃至肠断。末句“最断人肠”隐含着作者的同情，语简意深，十分传神。\n\n　　通览全词，语浅情深，言短味长，用简单的语言写出了当时社会的黑暗与专制，充分体现了词人的悲悯之心。欧阳修善于发现，用心去感受贫苦人民的生活方式，用诗词反映底层人民的悲欢离合，这正是此词令读者动情之处。\n\n　　这首词由于既有环境的渲染，又有情感的转折，所以不仅情感真挚，而且耐人寻味。在词中，作者笔下出现一位娇柔羞涩的少女，她工愁善感，敏慧多情，这些，都没有作正面交待，却从侧面点拨，使读者从她的梳妆、歌唇、颦笑中想象而得，而她的形象栩栩如生、呼之欲出，足见词人生活体验和艺术功力之深。', poem_tags = '宋词三百首,宋词精选,女子,生活,抒情' WHERE poem_title = '诉衷情·眉意' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_tags = '怀古,写人,感慨' WHERE poem_title = '离骚' AND poem_author = '陆龟蒙';
UPDATE edu_poem SET poem_translation = '方山子，是光州、黄州一带的隐士。年轻时，仰慕汉代游侠朱家、郭解的品行，乡里的游侠之士都推崇他。（等到他）年岁稍长，就改变志趣，发奋读书，想以此来驰名当代，但是一直没有交上好运。到了晚年隐居在光州、黄州一带名叫岐亭的地方。住茅草屋，吃素食，不与社会各界来往。放弃坐车骑马，毁坏书生衣帽，徒步在山里来往，没有人认识他。人们见他戴的帽子上面方方的且又很高，就说：“这不就是古代乐师戴的方山冠遗留下来的样子吗？”因此就称他为“方山子”。\n\n　　我因贬官居住在黄州，有一次经过岐亭时，正巧碰见了他。我说：“哎，这是我的老朋友陈慥陈季常呀，怎么会在这里呢？”方山子也很惊讶，问我到这里来的原因。我把原因告诉了他，他低头不回答，继而仰天大笑，请我住到他家去。他的家里四壁萧条，然而他的妻子儿女奴仆都显出怡然自得的样子。\n\n　　我对此感到十分惊异。回想起方山子年轻的时候，是酗酒任性，喜欢使剑，挥金如土的游侠之士。十九年前，我在岐亭下，见到方山子带着两名骑马的随从，身藏两箭，在西山游猎。只见前方一鹊飞起，他便叫随从追赶射鹊，未能射中。方山子拉紧缰绳，独自跃马向前，一箭射中飞鹊。他就在马上与我谈论起用兵之道及古今成败之事，自认为是一代豪杰。至今又过了多少日子了，但是一股英气勃勃的神色，依然在眉宇间显现，这怎么会是一位隐居山中的人呢？\n\n　　方山子出身于世代功勋之家，理应有官做，假如他能置身官场，到现在已得声名显赫了。他原本家在洛阳，园林宅舍雄伟富丽，可与公侯之家相同了。在河北还有田地，每年可得上千匹的丝帛收入，这些也足以使生活富裕安乐了。然而他都抛开不去享用，偏偏要来到穷僻的山里，这难道不是因为他独有会心之处才会如此的吗？我听说光州、黄州一带有很多奇人异士，常常假装疯颠、衣衫破旧，但是无法见到他们；方山子或许能遇见他们吧。', poem_notes = '方山子：即陈慥，字季常。\n光、黄：光州、黄州，两州连界。光州州治在今河南潢川县。\n隐人：隐士。\n朱家、郭解：西汉时著名游侠，见《史记·游侠列传》。\n.闾里：乡里。\n侠：侠义之士。\n宗之：崇拜他，以他为首。宗，尊奉。\n折节：改变原来的志趣和行为。《后汉书·段颎传》：“颎少便习弓马······长乃折节好古学。”\n“驰骋”句：在当代施展才学抱负。\n遁：遁世隐居。\n岐亭：宋时黄州的镇名，在今湖北麻城县西南。\n屋：帽顶。\n岂：其意为“（这）难道不是······”。\n方山冠：唐宋时隐士戴的帽子。\n遗象：犹遗制。\n“余谪居”三句：苏轼《岐亭五首叙》：“元丰三年正月，余始谪黄州，至歧亭北二十五里，山上有白马青盖来迎者，则余故人陈恤季常也。为留五日，斌诗一篇而去。”谪，降职。\n矍（jué）然：惊讶睁眼相视貌。\n“环堵”一句：用陶渊明《五柳先生传》“环堵萦然，不蔽风日”成句，谓室内空无所有。\n使酒：喝醉酒后爱发脾气，任性而行。\n余在岐山：宋仁宗嘉祐七年，苏轼任风翔府签判，时陈糙之父陈希亮知凤翔府。苏轼这时始与陈糙相识订交。岐山，指凤翔。凤翔有岐山。\n怒马：愤怒地鞭马独自冲出去。\n“一发”一句：一箭射中它。\n“精悍”一句：精明英武的神情气度。精悍，精明强干。\n“然方山子”二句：苏轼《陈公弼传》：陈希亮（公弼）“当荫补子弟，辄先其族人，卒不及其子糙。”世有勋阀：世代有功勋，属世袭门阀。\n穷山中：荒僻的山中。“此岂”一句：难道没有独特的造诣修养能够作到这一点吗？\n异人：指特立独行的隐沦之士。\n佯狂：装疯。\n垢污：言行不屑循常蹈故，被人们认为是德行上的垢污。\n傥：或者。', poem_tags = '古文观止,写人,隐居,生活,抒怀' WHERE poem_title = '方山子传' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '一天，猫头鹰遇见了斑鸠，斑鸠问它：“你将要到哪儿去？”\n猫头鹰说：“我将要向东迁移。”\n斑鸠问：“是什么原因呢？”\n猫头鹰说：“村里人都讨厌我的叫声，所以我要向东迁移。”\n斑鸠说：“如果你能改变叫声，就可以了；你要是不改变叫声，那么即使你向东迁移，那里的人照样会讨厌你的叫声。”', poem_notes = '枭(xiāo)：又称鸺鹠(xiū liú)，一种凶猛的鸟，猫头鹰。\n逢：遇见，遇到。\n鸠（jiū）：斑鸠、雉鸠等的统称，形似鸽子。\n子将安之：您打算到哪里（安家）。\n子，古代对对方的尊称，表示“您”。\n将，打算、准备。\n安，哪里。 之，到。 安之，即“之安”，去哪儿。\n东徙（xǐ）：向东边搬迁。 徙，搬迁。\n何故：什么原因。 故，原因。\n乡人皆恶（wù）我鸣：乡里人都讨厌我的叫声。 皆，都。 恶，厌恶。 我，这里指代猫头鹰。\n以故：因此。 以，因为。 故，原因，缘故。\n更（gēng）：改变。\n犹（yóu)：仍旧，还。', poem_tags = '小学文言文,寓言,故事,哲理' WHERE poem_title = '枭逢鸠 / 枭将东徙' AND poem_author = '刘向';
UPDATE edu_poem SET poem_translation = '朱大你要到长安去，我有宝剑可值千金。\n现在我就把这宝剑解下来送给你，以表示我今生对你的友情。', poem_notes = '朱大：孟浩然的好友。\n秦：指长安：\n游人：游子或旅客，此诗指的是朱大。\n五陵：地点在长安，唐朝的时候是贵族聚居的地方。\n值千金：形容剑之名贵。值：价值。\n脱：解下。', poem_appreciation = '首句“游人五陵去”“游人”，强调其浪游者的身份。“五陵”本为汉高祖长陵、惠帝安陵、景帝阳陵、武帝茂陵、昭帝平陵，都在长安，诗中用作长安的代称。京华之地，是游侠云集之处。“宝剑值千金”，惜别赠别乃知之所为这句诗本为曹植《名都篇》诗句，这里信手拈来，不仅强调宝剑本身的价值，而且有身无长物的意味。这样的赠品，将是无比珍贵，不可等闲视之。诗中写赠剑，有一个谁赠谁受的问题。从诗题看，本可顺理成章地理解为作者送朱大以剑。而从“宝剑”句紧接“游人”言之，似乎还可理解为朱大临行对作者留赠以剑。在送别时，虽然只能发生其中一种情况；但入诗时，诗人的著意唯在赠剑事本身，似乎已不太注重表明孰失孰得。这反而耐人寻想。\n\n　　千金之剑，分手脱赠，大有疏财重义的慷慨之风。不禁令人联想到一个著名的故事，那便是“延陵许剑”。《史记·吴太伯世家》记载，受封延陵的吴国公子“季札之初使，北过徐君。徐君好季札剑，口弗敢言。季札心知之，为使上国，未献。还至徐，徐君已死，于是乃解其宝剑，系之徐君冢树而去。”季札挂剑，其节义之心固然可敬，但毕竟已成一种遗憾。“分手脱相赠”，痛快淋漓。最后的“平生一片心”，语浅情深，似是赠剑时的赠言，又似赠剑本身的含义——即不赠言的赠言。只说“一片心”而不说一片什么心，妙在含浑。却更能激发人海阔天空的联想。那或是一片仗义之心，或是一片报国热情。总而言之，它表现了双方平素的仗义相期，令人咀嚼，转觉其味深长。浩然性格中也有豪放的一面。唐人王士源在《孟浩然集序》中称他“救患释纷，以立义表”，“交游之中，通脱倾盖，机警无匿”，《新唐书·文艺传》谓其“少好节义，喜振人患难。”那么，这首小诗所表现的慷慨激昂，也就不是偶然的了。', poem_tags = '送别,友情' WHERE poem_title = '送朱大入秦' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '那个容貌美丽性格文静的姑娘，正在乡间岔路口忙着采桑。\n桑树的枝条柔柔的垂摆，采下的桑叶翩翩飘落。\n挽起的衣袖可见她的手，洁白的手腕上戴着金色的手镯。\n头上插着雀形的金钗，腰上佩戴着翠绿色的玉石。\n身上的明珠闪闪发光，珊瑚和宝珠点缀其间。\n丝罗衣襟在春风里飘舞，轻薄的裙纱随风旋转。\n她那回首顾盼留下迷人的光彩，吹口哨时流出的气息仿佛兰花的芳香。\n赶路的人停下车驾不肯走开，休息的人们傻看时忘记了用餐。\n有人打听这个姑娘家住哪里，她的家就住在城的正南门。\n青漆的楼阁紧临大路，高大的宅门用的是两道门栓。\n姑娘的容光像早晨的太阳，谁不爱慕她动人的容颜？\n媒人干什么去了呢？为什么不及时送来聘礼，订下婚约。\n姑娘偏偏爱慕品德高尚的人，寻求一个贤德的丈夫实在很困难。\n众人徒劳地议论纷纷，怎知道她看中的到底是什么样的人？\n青春年华在闺房里流逝，半夜里传来她一声声的长叹。', poem_notes = '本篇是《杂曲歌·齐瑟行》歌辞，以美女“盛年处房室”比喻自己虽有才具，而无可施展。\n妖：妖娆。\n闲：同“娴”，举止优雅。\n冉冉：动貌。\n攘袖：捋起袖子。\n约：缠束。\n金爵钗：雀形的金钗。“爵”，同“雀”。\n琅玕：形状像珠子的美玉或石头。\n木难：碧色珠，传说是金翅鸟沫所成。\n还（音“旋”）：转。\n啸：蹙口出声，今指吹口哨。\n城南端：城的正南门。\n青楼：涂饰青漆的楼，指显贵之家，和以青楼为妓院的意思不同。\n重关：两道闭门的横木。\n希令颜：慕其美貌。\n玉帛：指珪璋和束帛，古代用来定婚行聘。\n中夜：半夜。', poem_appreciation = '“美女妖且闲，采桑歧路间。”这是交代人物、地点。人物是一个美丽姑娘，她的容貌艳丽，性格娴静。地点是“歧路间”，即岔路口，她在采桑。“歧路间”是来往行人较多的地方，这就为下文“行徒”、“休者”的倾倒预作铺垫。“柔条纷冉冉，落叶何翩翩。”紧接“采桑”，写柔嫩的桑枝轻轻摇动，采下的桑叶翩翩飘落。这里明是写桑树，暗是写美女采桑的优美动作。景物的描写对表现人物起了烘托作用。\n\n　　“攘袖见素手，皓腕约金环。头上金爵钗，腰佩翠琅玕。明珠交玉休，珊瑚间木难。罗衣何飘飖，轻裾随风还。顾盼遗光彩，长啸气若兰。”主要写美人的服饰，也写到神情。“攘袖”二句，上承“柔条”二句，美女采桑必然挽袖。挽袖方能见到洁白的手。为了采桑，素手必须高举，这样又可见到带着金手镯的洁白而光泽的手腕。用词精当，次第井然。因为是采桑，所以先写美女的手和腕，然后写到头和腰，头上插着雀形的金钗，腰上挂着翠绿色的玉石。身上佩着明珠，还点缀着碧色宝珠和红色的珊瑚。以上几句写美女身上的装饰品，多为静态的描写。“罗衣”二句，写美女轻薄的丝罗上衣，衣襟随风飘动，是动态的描写。动静结合描写美女的服饰，写出美女婀娜的身姿和轻盈的步态。形象十分鲜明。“顾盼”二句，以精妙的字句，勾勒美女神情。美女的一顾一盼都给人留下迷人的光彩，长啸时呼出的气息，芬芳如幽兰。使人感到如见其人，如闻其声，能不为之倾倒吗？所以，“行徒用息驾，休者以忘餐”。行路的人见到美女停车不走了，休息的人见到美女忘了吃饭，从侧面描写美女的美貌。应该指出，曹植的这段描写，显然受了汉乐府《陌上桑》的影响。《陌上桑》描写罗敷的美貌是这样写的：“罗敷喜蚕桑，采桑城南隅。青丝为笼系，桂枝为笼钩。头上倭堕髻，耳中明月珠。缃绮为下裙，紫绮为上襦。行者见罗敷，下担捋髭须。少年见罗敷，脱帽著绡头。耕者忘其犁，锄者忘其锄，来归相怨怨，但坐观罗敷。”这是描写罗敷的美丽，并不直接描写她的容貌，而是描写她用的器物（“笼系”“笼钩”）和穿戴的服饰（“倭堕髻”“明月珠”“下裙”“上襦”）之美及“行者”“少年”“耕者”“锄者”四种人见到罗敷以后的反应，从正面和侧面来烘托罗敷的美丽。这些描写与《美女篇》的描写对比起来，二者在内容上虽然基本相同，但是写法却不尽相同，表现了曹植诗的一些变化和发展。\n\n　　“借问女安居？乃在城南端。青楼临大路，高门结重关。”交代美女的住处，点明她的高贵门第。美女住在城南大路附近的高楼里。“青楼”“高门”“重关”，说明她不是普通人家的女儿，而是大家闺秀。“容华耀朝日，谁不希令颜？”美女的容光如同早晨的阳光，谁不爱慕她的美貌呢？上句写美女容貌之美，可与前半首合观；下句说无人不为之倾倒，引起下文。这里写美女高贵的门第和美丽的容颜，是隐喻诗人自己的身份和才能。有才能而没有施展的机会，所为他不能不慨叹英雄无用武之地。\n\n　　“媒氏何所营？玉帛不时安。佳人慕高义，求贤良独难。众人徒嗷嗷，安知彼所观。”媒人都干什么去了呢？为什么不及时送来聘礼，订下婚约呢？诗人对媒人的责怪，反映了自己内心的不平。媒人不来行聘，这是客观上的原因。而美女爱慕的是品德高尚的人，要想寻求一个贤德的丈夫实在很困难。这是美女主观上的原因。这是比喻志士有理想，但难于实现。美女的理想不是一般人所能理解的，可而吵吵嚷嚷，议论纷纷，他们哪里知道她看得上的是怎样的人。这是比喻一般人不了解志士的理想。“盛年处房室，中夜起长叹。”美女正当青春盛年，而独居闺中，忧愁怨恨，深夜不眠，发出长长的叹息。这是比喻志士怀才不遇的苦闷。\n\n　　这首诗通篇用比，比是中国古代诗歌的传统手法，《诗经》、《楚辞》多用之。《美女篇》以绝代美人比喻有理想有抱负的志士，以美女不嫁，比喻志士的怀才不遇。含蓄委婉，意味深长。其实美女所喻之志士就是曹植自己。', poem_tags = '乐府,写人,美女,抒怀' WHERE poem_title = '美女篇' AND poem_author = '曹植';
UPDATE edu_poem SET poem_translation = '夜晚归来与大家举杯同祝又已增岁添寿，不经意却看到镜中的自己已两鬓斑白。\n正对着镜中自己偷偷笑了起来，看来这屠苏美酒怕是无法率先品尝了。', poem_notes = '戴星：顶着星星。喻早出或晚归。\n觞（shāng）：古代盛酒器。作为动词时有敬酒，饮酒的意思。\n好是：恰是，正是。\n屠苏：药酒名。古代风俗，于农历正月初一饮屠苏酒。\n不得：不能得到，得不到。', poem_tags = '节日,祝酒,感慨' WHERE poem_title = '元日' AND poem_author = '成彦雄';
UPDATE edu_poem SET poem_translation = '篱笆外面不知是谁家没有系好船只。春潮上涨小船被吹进了钓鱼湾。有一位小孩正玩得高兴，突然发现有船进湾来了，以为是村里来了客人，急急忙忙地跑回去，去把柴门打开。', poem_notes = '溪居：溪边村舍。\n即事：对眼前的事物、情景有所感触而创作。\n系（jì）：栓，捆绑。\n却关：打开门闩。', poem_tags = '乡村,写景,抒情' WHERE poem_title = '溪居即事' AND poem_author = '崔道融';
UPDATE edu_poem SET poem_translation = '曾经追逐东风，犹如舞女在宴席上翩翩起舞，那时正是繁花似锦的春日，人们在乐游原中游玩。怎么会到深秋的季节，已是夕阳斜照，秋蝉哀鸣的景象了。', poem_notes = '①断肠天：令人销魂的春天', poem_tags = '柳树,伤怀' WHERE poem_title = '柳' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '注释 1.“临水”之“水”和“江叟”之“江”均指浔阳江，即长江在九江市的一段。 2.甲乙第：指科举考试录取时所评定的等第，第一等为甲第，次等为乙等，应考中式称为“登第”。 3.承明庐：原为汉代承明殿旁屋，侍官值宿所居之屋为庐，后因以入承明庐为入朝或在朝为官的典故。 4.浮生”即人生。“外事”指世事；“盈虚”意即圆满与空虚。', poem_appreciation = '起句“临水一长啸”采用情感迸发式的写法领起全篇，把临水垂钓与发泄悲愤情绪融合起来，痛定思痛、长歌当哭的诗人形象跃然纸上，给人以震撼灵魂的感染力。\n\n　　紧接着便回首往事，概述人生旅途的变化，宦海沉浮、仕途得失、人间冷暖、世事盈虚，尽在一声长啸之中。\n\n　　诗中江州之贬在诗人心灵所造成的阴影时刻折磨着他，即使临水垂钓时也挥之不去。“忽思”一语正这种心理状态的真切表现。\n\n　　此诗颔联“三登甲乙第，一入承明庐”，是诗人对前期一帆风顺、春风得意情景的追溯，也是对贬谪所受精神创伤的反衬。\n\n　　那时，他既利用诗歌“补察时政”、“导泄人情”，往往使权贵们闻声变色。这自然给诗人留下了美好的回忆。可惜好景不长，逝者如流，这种回忆也带有浓浓的苦涩味了。\n\n　　后两联则表现了诗人后期的思想变化。这一联写的是诗人身遭贬谪、饱经风霜之后对世事人生的重新审视，也是他寻求心理平衡的一种自慰。\n\n　　可以看出，白居易头脑中的儒家入世思想逐渐让位于释、道出世思想。全诗以“今来伴江叟，沙头坐钓鱼”作结，轻快潇洒中隐含着深沉的苦闷，自我排遣中透露也几分达观。', poem_tags = '贬谪,怀念' WHERE poem_title = '垂钓' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '躺在精美的竹席上，思绪万千，久久不能平静。期待已久的一次与恋人的约会，在这个晚上告吹了。从今以后再也无心欣赏那良辰美景了，管他明月下不下西楼。', poem_notes = '水纹珍簟（diàn）：编织着水纹花样的珍贵竹席。思悠悠：思绪很多。悠悠：漫长，遥远。“水纹”句写独宿无眠，回忆往事。\n佳期：本指好时光，引申为男女约会的好时机。“千里”句是说，由于风云突变，千里佳期一下子破灭了。', poem_tags = '失恋,爱情' WHERE poem_title = '写情' AND poem_author = '李益';
UPDATE edu_poem SET poem_translation = '王的部队驻守在垓下，兵少粮尽，汉军及诸侯的军队把他重重包围。深夜，（项羽）听到汉军在四面唱着楚地的歌，项羽于是大为吃惊，说：“难道汉军把楚人都征服了吗？他们那边楚人为什么这么多呀！”项王于是在夜里起来，在帐中饮酒。有美人名虞，一直受宠跟在项王身边；有骏马名骓（zhuī，追），（项羽）一直骑着。这时候，项羽不禁情绪激昂唱起悲歌，自己作诗（吟唱）道：“力量能拔山啊，英雄气概举世无双，时运不济时骓马不再奔跑！骓马不奔跑可将怎么办，虞姬呀虞姬，（我）将怎么安排你才妥善？”项王唱了连唱几遍，美人虞姬应和着一同唱歌。项王眼泪一道道流下来，左右侍者也都跟着落泪，没有一个人忍心抬起头来看他。\n\n　　在这种情况下，项羽独自一人骑上马，部下壮士八百多人骑马跟在后面，当夜突破重围，向南冲出。天刚亮的时候，汉军才发觉，命令骑将灌婴带领五千骑兵去追赶。项王渡过淮河，部下壮士能跟上的只剩下一百多人了。项王到达阴陵，迷了路，去问一个农夫，农夫骗他说：“向左边走。”项王带人向左，陷进了大沼泽地中。因此，汉兵追上了他们。项王于是又带着骑兵向东跑，到达东城，这时就只剩下二十八人。汉军骑兵追赶上来的有几千人。项王自己估计不能逃脱了，对他的骑兵说：“我带兵起义至今已经八年，亲自打了七十多仗，抵挡我的敌人都被打垮，我攻击的敌人无不降服，从来没有战败，因而能够称霸，据有天下。可是如今最终被困在这里，这是上天要灭亡我，决不是作战的过错。今天必死无疑，我愿意给诸位打个痛痛快快的仗，一定胜它三回，给诸位冲破重围，斩杀汉将，砍倒军旗，让诸位知道的确是上天要灭亡我，决不是作战的过错。”\n\n　　于是把骑兵分成四队，面朝四个方向。汉军把他们包围起几层。项王对骑兵们说：“我来给你们拿下一员汉将！”命令四面骑士驱马飞奔而下，约定冲到山的东边，分作三处集合。于是项王高声呼喊着冲了下去，汉军像草木随风倒伏一样溃败了，项王杀掉了一名汉将。这时，赤泉侯杨喜为汉军骑将，在后面追赶项王，项王瞪大眼睛呵叱他，赤泉侯连人带马都吓坏了，退避了好几里。项王与他的骑兵在三处会合了 。汉军不知项王的去向，就把部队分为三路，再次包围上来。项王驱马冲了上去，又斩了一名汉军都尉，杀死有百八十人，聚拢骑兵，仅仅损失了两个人。项王问骑兵们道：“怎么样？”骑兵们都敬服地说：“正像大王说的那样。”\n\n　　这时候，项王想要向东渡过乌江。乌江亭长正停船靠岸等在那里，对项王说：“江东虽然小，但土地纵横各有一千里，民众有几十万，也足够让您称王了。希望大王快快渡江。现在只有我这儿有船，汉军到了，没法渡过去。”项王笑了笑说：“上天要灭亡我，我还渡乌江干什么！再说我和江东子弟八千人渡江西征，如今没有一个人回来，纵使江东父老兄弟怜爱我让我做王，我又有什么脸面去见他们？纵使他们不说什么，我项籍难道心中没有愧吗？”又对亭长说：“我知道您是位忠厚长者，我骑着这匹马征战了五年，所向无敌，曾经日行千里，我不忍心杀掉它，把它送给您吧。”命令骑兵都下马步行，手持短兵器与追兵交战。仅凭借项羽就杀死汉军几百人。项羽自己也负伤十多处。项王回头看见汉军骑司马吕马童，说：“你不是我的老朋友吗？”马童这时才跟项王打了个对脸儿，于是把项羽指给王翳看：“这才是项王。”于是项王说：“我听说汉王用黄金千斤，封邑万户悬赏征求我的脑袋，我送你个人情吧！”说完便自刎而死。▲', poem_appreciation = '本篇节选自《史记·项羽本纪》，题目为后人所拟。\n\n　　有人把《史记》誉之为悲剧英雄画廊，西楚霸王项羽则是悲剧群像中的绝代典型，“项羽之死”这个片断便是这部旷世悲剧的最后一幕。“喑叱咤，千人皆废”的英雄死了，留在人间的是历史长河中曾经“卷起千堆雪”的浪花，群山万壑中殷殷不绝的回响，两千年来无数读者掩卷而思、拍案而起的长叹息。\n\n　　这最后一幕，由垓下之围、东城快战、乌江自刎三场组成，其中包含了楚歌夜警、虞兮悲唱、阴陵失道、东城快战、拒渡赠马、赐头故人等一连串惊心动魄的情节和细节。司马迁怀着满腔激情，运用史实、传说和想像，传写了项羽的穷途末路，不断丰富、发展了他的性格，让这位英雄死在歌泣言笑之中，取得了可歌可泣的艺术效果。\n\n　　第一场：垓下之围。大幕刚启，夜空中传来若断若续、如泣如诉的四面楚歌之声，先奏起背景音乐；然后唱出变徵之音的“虞兮”主调：一起便哀音满耳，感人至深。“时不利兮可奈何！虞兮虞兮奈若何！”结尾三虚字反复唱叹，曼声苍凉。正如《史记评林》引吴贤齐说的那样：“一腔怨愤，万种低徊，地厚天高，托身无所，写英雄失路之悲，至此极矣！”这支歌由项羽主唱，美人和之，更显得英雄气短，儿女情长，以至这位从不曾流过泪的西楚霸王也不禁“泣数行下”；他的部属更是“左右皆泣，莫能仰视”，一片呜咽。这里唱出的不仅是个人在命运面前无可奈何的悲哀，也包含了连所宠爱的美人都无法保护的悲哀；这里流出的不仅是一位伟大的英雄犯了错误之后的悲哀的眼泪，也是一位伟大的英雄面对最终失败的忏悔与惭愧的眼泪。司马迁不愧是伟大的传记文学家，他对音乐的感发作用有着深邃的理解。在《刺客列传》中，他曾用“易水之歌”写荆轲的壮士之别，令“士皆垂泪涕泣”；在《留侯世家》中，他用“鸿鹄之歌”写刘邦晚年不得立如意为太子的痛苦心态，使戚夫人“嘘唏流涕”；而现在（公元前二〇二年），他又用“虞兮之歌”作为项羽之死这最后一幕的序曲，让悲怆的气氛笼罩全篇，把读者引进苍茫辽远、四顾寂寥的境界，噙着泪水一字一字地往下读，一读则欲罢不能。\n\n　　接下来是第二场——东城快战。当项羽“自度不得脱”之后，连连说：“此天之亡我，非战之罪也。”“令诸君知天亡我，非战之罪也。”与后面的“天之亡我，我何渡为”互相呼应，三复斯言；明知必死，意犹未平。钱钟书说：“认输而不服气，故言之不足，再三言之。”(《管锥编》)“不服气”，正显示了他的平生意气，说明了他自负、自尊而不知自省、自责。快战之前，司马迁设计了阴陵迷道这个极富表现力的细节。田父把他指向绝路，看似偶然，其实必然。这是他过去“所过无不残灭”，丧失人心的结果。“田父绐之曰：‘向左。’乃陷大泽中，以故汉追及之。”人家骗他，指向左边，他便不假思索地驰向左边，表现了他从来不惯骗人，也从来不相信别人敢骗他的直率、粗犷的性格。这里两“左”字独字成句，节奏短促，纸上犹闻其声，显示出当时形势严峻紧张，仿佛那五千骑追兵已从征尘滚滚中风驰雨骤而至，迫促感、速度感、力量感尽蓄笔端。\n\n　　写阴陵迷道，目的在揭示这位末路英雄丧失人心；写东城溃围、斩将、刈旗，则着意于进一步展开他拔山盖世的意气和个人英雄主义的性格。此刻，他丝毫不存幸胜突围之心，只图打一个痛快仗给追随他的残部看看，确证他的失败是“天之亡我”。在这位英雄心目中，死，从来就是不可怕的；英名受侮，承认自己失败，那才可怕。要死也死个痛快，死在胜利之中。这种心态，可笑而又可悲。在这场“快战”中，司马迁再一次运用细节描绘，写项羽的拔山之力，不世之威：“于是项王大呼驰下，汉军皆披靡”；“赤泉侯……追项王，项王嗔目叱之，赤泉侯人马俱惊，辟易数里”。这里，仍用虚笔，集中写他的声音。一呼则汉军披靡，一叱则不仅人惊，连马也吓得后退数里，这是何等的声威力量！他像一尊凛然不可犯的天神，一只被猎犬激怒了的猛虎，须眉毕张，咆哮跳踉，谁也不敢靠近他一步。特别是他“复聚其骑”后，“乃谓其骑曰：‘何如！’骑皆伏曰：‘如大王言！’”“何如”二字，写得意，写自负，声口毕见，活活画出项羽豪迈的性格。在这一瞬间，他感受到的只是一种不屈服的自我肯定的甜蜜，哪里还曾意识到自己是千枪万箭追杀的目标！\n\n　　第三场：乌江自刎。其中写了拒渡、赠马、赐头三个细节。项羽马到乌江，茫茫江水阻绝了去路。悲剧的大幕即将落下，司马迁偏偏在这最后时刻打了一个回旋，为他笔下的英雄形象补上了最后的浓墨重彩的一笔，设计了“乌江亭长舣船待”这个细节。文如水穷云起，又见峰峦。项羽本来已无路可逃，司马迁却写成他有充分的机会脱逃而偏偏不肯过乌江，好像他不是被追杀得走投无路，不得不死；而是在生与义，苟活幸存与维护尊严之间，从容地作出了选择。江边慷慨陈辞，英雄的形象更加丰满完美。那曾经“泣数行下”的血性男子，临了反而笑了。“项王笑曰”的笑，不是强自矜持，不是凄然苦笑，而是壮士蔑视死亡，镇定安详的笑；显示了他临大难而不苟免的圣者之勇——“知耻近乎勇”。自惭无面见江东父老，正是由于知耻。这个细节，展示出他的纯朴、真挚、重义深情。对自己的死，他毫不在意；却不忍爱马被杀，以赠亭长。因为，“吾骑此马五岁，所当无敌”。五年来无数胜利的回忆，猛然兜上心头。今昔如此，情何以堪！文章写到这里，实已神完气足，司马迁颊上添毫，再加上把头颅留赠故人这样一个出人意表、千古未闻的细节。“故人”追之、认之，必欲杀之以邀功取赏；项羽却慷慨赐头，“吾为若德”：蝼蚁之微，泰山之高，两两对比，何等鲜明！\n\n　　项羽终于自刎了，他是站着死的。帝王刘、项，将相萧、曹，对于两千年后的我们，本来无所轩轾。但当我们读完《项羽本纪》，特别是读完“项羽之死”这最后一幕的时候，总不免咨嗟叹息，起坐彷徨，这就见出司马迁传写人物的艺术魅力。在这最后一幕中，留给我们印象最深刻的，是三个场次之间的节奏变化，起伏张弛，抑扬徐疾。第一场重在抒情，节奏纡徐，情如悲笳怨笛，以变徵之音形成了呜咽深沉的境界。第二场重在叙事，全用短节奏，进行速度，铁马金戈，声情激越。第三场江畔陈辞，羽声慷慨。“纵江东父老怜而王我，我何面目见之！纵彼不言，籍独不愧于心乎！”连用两反诘句，顿挫抑扬，极唱叹之胜。此外，还用了许多形象生动，蕴涵丰富的细节，其中必有不少出于传闻、揣度，但无不使人感到可感可信、人情人理。清刘熙载《艺概》所谓“太史公时有河汉之言，而意理却细入无间”；钱钟书《管锥编》所谓“马（司马迁）善设身处地，代作喉舌”，都是赞扬他设计的细节情理兼胜，妙合无垠。虞姬悲歌，乌江拒渡，赠马赐头，一波三折，全凭细节传神，使全篇文字达到雄奇悲壮的美学境界，读之令人荡气回肠。在传记文学中，不说绝后，至少空前。', poem_tags = '高中文言文,历史,故事' WHERE poem_title = '项羽之死' AND poem_author = '司马迁';
UPDATE edu_poem SET poem_translation = '（题目）初秋在园子里散步\n夕阳看似无情，其实最有情，\n园里树上的蝉，正趁着太阳落下的短暂时间，拼命的高声歌唱，园子里一片蝉叫声。\n蝉的叫声好像就在身边，可是你却无法找到他们，\n因为，当你找到它跟前的时候，它好像知道你来了，鸣叫声立即停止了。', poem_notes = '圃：种植菜蔬、花草、瓜果的园子。行圃，即指在园子里散步。\n咫尺：周制八寸为咫，十寸为尺。形容距离很近。', poem_tags = '田园,生活,动物' WHERE poem_title = '初秋行圃' AND poem_author = '杨万里';
UPDATE edu_poem SET poem_translation = '携杖出门去寻找纳凉圣地，画桥南畔，绿树成荫，坐靠在胡床之上惬意非常。\n寂寂明月夜，参差的笛声响起在耳边萦绕不觉，晚风初定，池中莲花盛开，幽香散溢，泌人心脾。', poem_notes = '倚胡床：坐靠胡床。倚：坐靠。', poem_appreciation = '这句连用“携”、“来”、“追”三个动词，把诗人携杖出户后的动作，分出层次加以表现。其中“追”字更是曲折、含蓄地传达出诗人追寻理想中的纳凉胜处的内在感情，实自杜甫《羌村》“忆昔好追凉”句点化而成。这样，诗人急于从火海中解脱出来的情怀，通过一系列动作，就自然而然地表现出来。\n\n　　次句具体指出了柳外纳凉地方的方位和临时的布置：“画桥南畔倚胡床。”这是一个绿柳成行，位于“画桥南畔”的佳处。诗人选好了目的地，安上胡床，依“倚”其上，尽情领略纳凉的况味。在诗人看来，这也可算“最是人间佳绝处”（《睡足轩》）了。胡床，即交椅，可躺卧。陶潜“倚南窗以寄傲”（《归去来兮辞》），是为了远离尘俗；秦观“倚胡床”以“追凉”，是为了驱解烦热，都是对美好生活的一种向往，他们或多或少是有相通之处的。\n\n　　一二两句写仔细寻觅纳凉胜地。三四两句则展开了对它的美妙景色的描绘：“月明船笛参差起，风定池莲自在香。”月明之夜，船家儿女吹着短笛，笛声参差而起，在水面萦绕不绝。晚风初定，池中莲花盛开，自在幽香不时散溢，沁人心脾。诗人闲倚胡床，怡神闭目，不只感宫上得到满足，连心境也分外舒适。这两句采取了对偶句式，把纳凉时的具体感受艺术地组合起来，于是，一个纳凉胜地的自然景色，就活现在读者面前。\n\n　　此诗以纳凉为题，诗中着力表现的是一个绝离烦热之处。诗人首先经过寻访，发现了这个处所的秘密，其次进行具体布置，置身其间，与外境融而为一，把思想感情寄托在另外一个“自清凉无汗”的世界。\n\n　　宋人吕本中曾在《童蒙诗训》中评论“少游此诗闲雅严重”（《诗林广记》引），“闲雅”当指此诗词语上的特点而言，“严重”则涉及此诗严肃而郑重的内容。它很可能是秦观在仕途遭到挫折后的作品。\n\n　　《纳凉》是一首描写景物的短诗。从字面上看，可以说没有反映什么社会生活内容。但是，透过诗句的表面，却隐约地表现出：诗人渴望远离的是炙手可热的官场社会，这就是他刻意追求一个理想中的清凉世界的原因。秦观是一个有用世之志的诗人。他对官场的奔竞倾夺表示厌弃，力求远避，此诗表达的就是这种感情。这种把创作念图隐藏在诗句背后的写法，读者应着意体会。', poem_tags = '古诗三百首,夏天,生活,写景' WHERE poem_title = '纳凉' AND poem_author = '秦观';
UPDATE edu_poem SET poem_translation = '一场春雨，给山路上增添了许多鲜花，鲜花在风中摆动，又给满山带来了盎然春色。我走到小溪深处，无数黄鹂飞跃啼鸣。\n天空中飞动的云彩在眼前干变万化宛如奔腾的龙蛇，在碧空中屈伸舒展，十分自如。这时，我正醉卧古藤阴下，朦胧迷离，全然不知南北东西。', poem_notes = '①好事近：词牌名，又名钓鱼笛、倚秋千。\n②黄鹂：乌名，鸣声婉转。亦称黄莺、黄鸟。\n③龙蛇：似龙若蛇，形容快速移行的云彩。\n④夭矫：屈伸自如的样子。\n⑤空碧：碧空。\n⑥了：完全，全然。', poem_tags = '春天,写雨,写花,抒怀' WHERE poem_title = '好事近·梦中作' AND poem_author = '秦观';
UPDATE edu_poem SET poem_tags = '抒怀,志向,感慨' WHERE poem_title = '雨霖铃·孜孜矻矻' AND poem_author = '王安石';
UPDATE edu_poem SET poem_translation = '夕阳落入崦嵫山，我去茅屋里探访孤独的僧人。满地落叶，僧人何在？遍山寒云，山路要走多久？\n初夜时分只听他独自敲磐，闲适中靠着一枝青藤。大千世界都在微尘里，我为什么要有喜爱和憎恨？', poem_notes = '青萝：一种攀生在石崖上的植物，此处代指山。南朝江淹《江上之山赋》：“挂青萝兮万仞，竖丹石兮百重。”\n崦（yān）：即“崦嵫（zī）”， 山名，在甘肃。古时常用来指太阳落山的地方。《山海经》载：鸟鼠同穴山西南有山名崦嵫，日所入处。\n初夜：黄昏。\n磬（qìng）：古代打击乐器，形状像曲尺，用玉、石制成，可悬挂。佛寺中使用的一种钵状物，用铜铁铸成，既可作念经时的打击乐器，亦可敲响集合寺众。\n“世界”句：语本《法华经》：“书写三千大千世界事，全在微生中。”意思是大千世界俱是微生，我还谈什么爱和恨呢？《楞严经》说：“人在世间，直微尘耳。何必拘于憎爱而苦此心也！”宁：为什么。', poem_appreciation = '诗人在激烈的牛、李党争中被搞得心疲力尽，漂泊的生活，孤独的处境，使他感到生活在红尘中的不幸，迫切需要接触一下清净的佛家天地。\n\n　　首联写诗人寻访僧人之事。时当红日西沉山谷，诗人进入山中，去拜访一位住在茅屋中的僧人。“茅屋”，写出僧人居处的简朴，“孤僧”，写出僧人的不厌孤独。而诗人此时正逢生活清苦、亲朋离散的艰难岁月，他寻访这样一位清苦而孤居的僧人，显然是要从对方身上获得启示，以解除自身的苦恼。清苦人寻清苦地，孤独客访孤独僧，俗与佛已有了精神交流的契机。\n\n　　颔联写诗人寻访所经之路程、所见之景物。“落叶人何在，寒云路几层。”时当深秋，满山的林木飘下纷纷的黄叶，诗人要找的那位孤僧，却不知住在哪里。“人何在”，使人联想到诗人于山林间四处张望的神态，显现出山间林木的密集和僧人的幽藏，愈发表现出这位孤僧远避红尘的意趣，这正是诗人探访的目的。对句更将僧人的幽藏作进一步的渲染：诗人沿着寒云缭绕的山路，盘曲而上，已不知把那盘山之路走了几重。山路入云，已见其高，何况入的是“寒云”。“寒云路几层”不仅写出僧人的高居尘上，也写出诗人不畏辛劳和艰险、—心追寻禅理的热切之举。此联二句写景而兼记行踪，景中暗含着僧人和诗人的影子，言筒意丰，蕴藏极富，堪称方家妙笔。\n\n　　经过千回万转，诗人终于找到了茅屋，见到了孤僧，颈联以精炼的笔墨描绘了僧人的简静生活：“独敲初夜磐，闲倚一枝藤。”“初夜”二字与首句“残阳”相关照，写出到达茅屋的时间。夜幕降临，僧人在茅屋中独自敲磐诵经。“独”字与次句的“孤”字相呼应，因为是“孤僧”，所以独自敲磐。虽只身独处，而未怠佛事，可见其对佛的虔诚。诗人此时站在茅屋外边，耳听清脆的磐声，眼望寂静的星辰，深感佛界的静谧与安详，此中再无红尘之困扰。待到僧人佛事已毕，诗人走进茅屋，与之交谈，对交谈的情状仅用“闲倚一枝藤”五个字概括，却内蕴丰富。“藤”是藤条做的手杖，极为简朴，僧人所“倚”，仅此而已，生活之清苦可以想见；难得的是僧人那份“闲”态，居清贫而安闲自如，从容不迫。\n\n　　尾联写诗人获得了思想的启迪。“世界微尘里，吾宁爱与憎。”佛教认为大千世界全在微尘之中，人也不过就是微尘而已。诗人领悟了这个道理，表示今后不再纠缠爱憎，众心净虑，以淡泊之怀面对仕途荣辱。\n\n　　综观此诗，语言凝炼，富于蕴藏，层次清晰。诗人先写出访，次写途中，再写遇僧，最后以思想收获作结。诗人先将笔墨集中在探访之上，描写僧人居住状态的孤独。用“独敲”一联勾勒，“独”字和“一”字均照应了第二句中的“孤”字。用“闲”字写出佛家对红尘物欲的否定，突显出诗人希望从佛教思想中得到解脱，将爱憎抛却，求得内心的宁静。最后写诗人访僧忽悟禅理之意，更衬出孤僧高洁的心灵。此诗所表达的就是一种不畏辛劳艰险、—心追寻禅理、淡泊之怀面对仕途荣辱的愿望，既赞美了僧人清幽简静的生活，又表现出诗人对惮理的领悟，淡泊之怀面对现实、从容之心面对仕途荣辱。', poem_tags = '唐诗三百首,寻访' WHERE poem_title = '北青萝' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '公子王孙竞相争逐在后面，貌美的女子流泪湿透了罗巾。\n一旦进入深幽如海的侯门，从此萧郎便成为了陌路之人。', poem_notes = '公子王孙：旧时贵族、官僚，王公贵族的子弟。\n后尘：后面扬起来的尘土。指公子王孙争相追求的情景。\n绿珠：西晋富豪石崇的宠妾，非常漂亮，这里喻指被人夺走的婢女。\n罗巾：丝制手巾。\n侯门：指权豪势要之家。\n萧郎：原指梁武帝萧衍，南朝梁的建立者，风流多才，在历史上很有名气。后成为诗词中习用语，泛指女子所爱恋的男子。这里是作者自谓。', poem_appreciation = '这首诗写的是自己所爱者被劫夺的悲哀，但由于诗人的高度概括，便使它突破了个人悲欢离合的局限，反映了封建社会里由于门第悬殊所造成的爱情悲剧。诗的寓意颇深，表现手法含而不露，怨而不怒，委婉曲折。\n\n　　“公子王孙逐后尘，绿珠垂泪滴罗巾”，上句用侧面烘托的手法，即通过对“公子王孙”争相追求的描写突出女子的美貌；下句以“垂泪滴罗巾”的细节表现出女子深沉的痛苦。公子王孙的行为正是造成女子不幸的根源，然而这一点诗人却没有明白说出，只是通过“绿珠”一典的运用曲折表达的。绿珠原是西晋富豪石崇的宠妾，传说她“美而艳，善吹笛”。赵王伦专权时，他手下的孙秀倚仗权势指名向石崇索取，遭到石崇拒绝。石崇因此被收下狱，绿珠也坠楼身死。用此典故一方面形容女子具有绿珠那样美丽的容貌，另一方面以绿珠的悲惨遭遇暗示出女子被劫夺的不幸命运。于看似平淡客观的叙述中巧妙地透露出诗人对公子王孙的不满，对弱女子的爱怜同情，写得含蓄委婉，不露痕迹。\n\n　　“侯门一入深如海，从此萧郎是路人”，这两句没有将矛头明显指向造成他们分离隔绝的“侯门”，倒好像是说女子一进侯门便视自己为陌路之人了。但有了上联的铺垫，作者真正的讽意就很容易明白，之所以要这样写，一则切合“赠婢”的口吻，便于表达诗人哀怨痛苦的心情，更可以使全诗风格保持和谐一致，突出它含蓄蕴藉的特点。“侯门”，对应首句的“公子王孙”；“深如海”的比喻，表达出豪门威逼之下，弱者的绝望感受：无边无际，深不见底，得不到解脱。“一入”、“从此”两个关联词语，概括出寒门情侣长久、无止尽的痛苦，所表达的语气中透露出来的深沉的绝望，比那种直露的抒情更哀感动人，也更能激起读者的同情。“萧郎”和“路人”的鲜明对比，表明面对情人，却只能形同陌路，揭示出豪门权贵约束人身自由、践踏人的情感的冷酷现实。\n\n　　从语言上看，这首诗用词很准确。在封建社会里，造成这类人间悲剧的，上自皇帝，下至权豪势要，用“侯门”概括他们，恰当不过，比喻生动形象。诗人以此涛赠给心上人，既写女子的不幸，也描述了自己所爱被劫夺的哀痛，而造成这种痛苦的，正是那些只顾个人喜恶的侯门贵族、公子王孙。作者并没有直接指斥，但诗中流露出的弱者的哀怨、深沉的绝望，却比直露的指斥更厚重，也更能激起读者的同情。诗中的情感实际上也超越了一己的悲欢而具有普遍的社会意义。', poem_tags = '爱情,悲剧,分手' WHERE poem_title = '赠去婢' AND poem_author = '崔郊';
UPDATE edu_poem SET poem_translation = '不远万里去到岭南游玩，到时柳树仍郁郁葱葱、生机勃勃。\n整日只知逢迎他人，饮酒作乐。\n天晓时分可以看见随波浮动的华丽游船，暖风拂过让人不禁解下黑色的貂裘。\n如果行囊里的财资不够，也不要埋怨故乡太遥远。', poem_notes = '交州：泛指五岭以南。 汉武帝时為所置十叁刺史部之一，辖境相当今广东、广西大部和越南的北部、中部。 东汉末改為交州。 越南於十世纪叁十年代独立建国后，宋亦称其国為交趾。\n青雀：这里应是青雀舫。泛指华贵游船。“鷁，鸟名也。今江东贵人船前作青雀，是其像也。”后因称船首画有 ...之舟為“青雀舫”。', poem_tags = '写人,告诫' WHERE poem_title = '送人游岭南' AND poem_author = '司空曙';
UPDATE edu_poem SET poem_translation = '长安的大道连着各种小街小巷，水牛和白马，香木车子在街上来来往往。王公贵族的车子纵横在贵族家外，络绎不绝。有雕着龙的华美车盖，车盖上的凤嘴挂着流苏的车子从早到晚穿行于长安。飘摇着的虫丝有百尺长，都绕在树上，一群娇小的鸟儿朝着花啼叫。成群的蜂蝶飞在宫门两侧，绿色的树，银色的台子，在阳光下映出许多颜色。府第的阁道、交窗上刻着合欢花的图案，两座望楼连着的房脊的双阙上像金凤垂翅。梁家的画阁高大入天，汉武帝建的铜柱高耸触云。楼阁上的仕女与别人相对望而不知对方是谁，路上相逢又会知晓对方？问她们可曾吹箫，她们答说曾经学习舞蹈度过花样年华。只要能和心爱的人厮守在一起，就是死了也心甘情愿；只要能和心爱的人厮守在一起，愿做凡人不羡慕神仙。比目和鸳鸯真是值得羡慕，只是君看不见他们成双结对。最恨帐前绣着孤鸾，愿将门帘贴上双飞的绕着花木梁的燕，帷幔和翠色的羽被被撒上郁金香料。鬓发如浮动的轻云，把它梳成蝉翼般的式样，在额头涂上嫩黄色新月状的图形。一个个额头涂着嫩黄色新月状图形、唇红齿白的美女随车出游，她们千娇百媚，风情万种。轻浮子弟骑着白底青点的马，盘龙纹的铰链圈着车里坐着歌女。不久御史府前静得可以听到乌鸦的叫声，廷尉府门前的树上有雀鸟想休息。车上隐约可以看到府第旁的豪华道路，车上的帷幕隐没了远处坚固河堤。有人在杜陵北打猎，有人在渭桥的西边刺杀官吏，后来带着宝剑的刺客都被吸引入住妓院，和妓女共宿。娼客日夜想着妓女，她们婉转的歌声和身上散发出的香气充溢着房间。娼客每晚都和漂亮如月的妓女行乐，到早晨骑着马像行云。娼客脚下的路连着妓院，长安街道纵横交错，四通八达，与市场相连接。孱弱的翠柳、槐枝垂在地上，车马杂沓的热闹声音也在夜晚响起了。禁军的骑队来了，他们在妓院饮酒。妓女美丽的衣裳为他们而解开，舞蹈也为他们而跳起。显贵的人做起将相，左右在皇帝身边而不相让。权贵将相容不下贤臣，处处排挤他们。专权的人自以为是英雄豪杰，骑着马得意洋洋。妓女认为自己的舞蹈之技优于千古，枭雄认为自己的富贵超过五公。世间的事必定会有大改变，昔日的豪华府第，只见几棵青松。汉代扬雄，仕途失意后，甘于寂寞，年年岁岁潜心著书，终于以文章名世。只有凄静的南山一些桂花在纷飞，点点打在人的衣上。', poem_notes = '古意：“古意”是六朝以来诗歌中常见的标题，表示这是拟古之作。\n狭斜：指小巷。\n七香车：用多种香木制成的华美小车。\n玉辇：本指皇帝所乘的车，这里泛指一般豪门贵族的车。\n主第：公主府第。第，房屋。帝王赐给臣下房屋有甲乙次第，故房屋称“第”。\n络绎：往来不绝，前后相接。\n侯家：封建王侯之家。\n龙衔宝盖：车上张着华美的伞状车盖，支柱上端雕作龙形，如衔车盖于口。宝盖，即华盖。古时车上张有圆形伞盖，用以遮阳避雨。\n凤吐流苏：车盖上的立凤嘴端挂着流苏。流苏，以五彩羽毛或丝线制成的穗子。\n游丝：春天虫类所吐的飘扬于空中的丝。\n千门：指宫门。\n复道：又称阁道，宫苑中用木材架设在空中的通道。\n交窗：有花格图案的木窗。\n合欢：马缨花，又称夜合花。这里指复道、交窗上的合欢花形图案。\n阙：宫门前的望楼。\n甍：屋脊。\n垂凤翼：双阙上饰有金凤，作垂翅状。\n梁家：指东汉外戚梁冀家。梁冀为汉顺帝梁皇后兄，以豪奢著名，曾在洛阳大兴土木，建造第宅。\n金茎：铜柱。汉武帝刘彻于建章宫内立铜柱，高二十丈，上置铜盘，名仙人掌，以承露水。\n“楼前”两句：写士女如云，难以辨识。讵：同“岂”。\n吹箫：用春秋时萧史吹箫故事。\n向紫烟：指飞入天空。紫烟，指云气。\n比目：鱼名。古人用比目鱼、鸳鸯鸟比喻男女相伴相爱。\n生憎：最恨。\n帐额：帐子前的横幅。\n孤鸾：象征独居。鸾，传说中凤凰一类的神鸟。\n好取：愿将。\n双燕：象征自由幸福的爱情。\n翠被：翡翠颜色的被子，或指以翡翠鸟羽毛为饰的被子。\n郁金香：这里指一种名贵的香料，传说产自大秦国（中国古代对罗马帝国的称呼）。这里是指罗帐和被子都用郁金香熏过。\n行云：形容发型蓬松美丽。\n蝉翼：古代妇女的一种发式，类似蝉翼的式样。\n初月上鸦黄：额上用黄色涂成弯弯的月牙形，是当时女性面部化妆的一种样式。鸦黄，嫩黄色。\n妖童：泛指浮华轻薄子弟。\n铁连钱：指马的毛色青而斑驳，有连环的钱状花纹。\n娼妇：这里指上文所说的“鸦黄粉白”的豪贵之家的歌儿舞女。\n盘龙：钗名。此指金屈膝上的雕纹。\n屈膝：铰链。用于屏风、窗、门、橱柜等物，这里是指车门上的铰链。\n“御史”两句：写权贵骄纵恣肆，御史、廷尉都无权约束他们。御史：官名，司弹劾。乌夜啼：与下句“雀欲栖”均暗示执法官门庭冷落。廷尉：官名，掌刑法。\n朱城：宫城。\n玉道：指修筑得讲究漂亮的道路。\n翠幰：妇女车上镶有翡翠的帷幕。\n金堤：坚固的河堤。\n挟弹飞鹰：指打猎的场面。\n杜陵：在长安东南，汉宣帝陵墓所在地。\n探丸借客：指行侠杀吏，助人报仇等蔑视法律的行为。借客，指助人。\n渭桥：在长安西北，秦始皇时所建，横跨渭水，故名。\n芙蓉剑：古剑名，春秋时越国所铸。这里泛指宝剑。\n娼家：妓女。\n桃李蹊：指娼家的住处。此借用，一则桃李可喻美色，二则暗示这里是吸引游客纷至沓来的地方。蹊，小径。\n啭：宛转歌唱。\n氛氲：香气浓郁。\n北堂：指娼家。\n人如月：形容妓女的美貌。\n南陌：指妓院门外。\n骑似云：形容骑马的来客云集。\n北里：即唐代长安平康里，是妓女聚居之处，因在城北，故称北里。\n五剧：交错的路。三条，通达的道路。控，引，连接。三市，许多市场。“五剧”、三条”、“三市”都是用前人成语，其中数字均非实指。\n佳气红尘：指车马杂沓的热闹景象。\n金吾：即执金吾，汉代禁卫军官衔。唐代设左、右金吾卫，有金吾大将军。此泛指禁军军官。\n屠苏：美酒名。鹦鹉杯，即海螺盏，用南洋出产的一种状如鹦鹉的海螺加工制成的酒杯。\n罗襦：丝绸短衣。\n燕赵歌舞：战国时燕、赵二国以“多佳人”著称，歌舞最盛。此借指美妙的歌舞。\n转日回天：极言权势之大，可以左右皇帝的意志。“天”喻皇帝。\n灌夫：字仲孺，汉武帝时期的一位将军，勇猛任侠，好使酒骂座，交结魏其侯窦婴，与丞相武安侯田蚡不和，终被田蚡陷害，诛族见《史记·魏其武安侯列传》。\n萧相：指萧望之，字长倩，汉宣帝朝为御史大夫、太子太傅。汉元帝即位，辅政，官至前将军，他曾自谓“备位将相”。后被排挤，饮鸩自尽。\n青虬、紫燕：均指好马。虬：本指无角龙，这里借指良马。紫燕：骏马名。\n坐春风：在春风中骑马飞驰，极其得意。\n凌：超过。\n五公：张汤、杜周、萧望之、冯奉世、史丹。皆汉代著名权贵。\n节物风光：指节令、时序。\n桑田碧海：即沧海桑田。喻指世事变化很大。\n金阶白玉堂：形容豪华宅第。\n扬子：汉代扬雄，字子云，在长安时仕宦不得意，曾闭门著《太玄》、《法言》。\n一床书：指以诗书自娱的隐居生活。言避世隐居之意。\n裾：衣襟。', poem_tags = '咏史怀古' WHERE poem_title = '长安古意' AND poem_author = '卢照邻';
UPDATE edu_poem SET poem_translation = '哪儿可以去采蘋？就在南面涧水滨。哪儿可以去采藻？就在积水那浅沼。\n什么可把东西放？有那圆筥和方筐。什么可把食物煮？三脚錡与无足釜。\n安置祭品在哪里？祠堂那边窗户底。这次谁来做主祭？恭敬虔诚待嫁女。', poem_notes = '于以：犹言“于何”，在何处。蘋（pín）：又称四叶菜、田字草，蘋科，为生于浅水之多年生蕨类植物，可食。\n藻：杉叶藻科，为多年生水生草本植物，可食。一说水豆。\n行（xíng）潦（lǎo）：沟中积水。行，水沟；潦，路上的流水、积水。《毛传》：“行潦，流潦也。”\n筥（jǔ）：圆形的筐。方称筐，圆称筥。\n湘：烹煮供祭祀用的牛羊等。《毛传》：“亨也。”按即烹。\n錡（qí）：三足锅。釜：无足锅。锜与釜均为炊饭之器。\n奠：放置。\n宗室：宗庙、祠堂。《毛传》：“大宗之庙也。”大宗，即大夫之始祖。牖（yǒu）：窗户。\n尸：主持。古人祭祀用人充当神，称尸。《毛传》：“尸，主。齐，敬。季，少也。”\n有：语首助词，无义。齐（zhāi）：美好而恭敬，“斋”之省借。季：少、小。', poem_appreciation = '此诗叙述的是少女临出嫁前庄重严肃地准备祭品和祭祀的情况，详实地记载了祭品、祭器、祭地、祭人，反映了当时的风尚习俗。\n\n　　根据文献可以知道，在古代，贵族之女出嫁前必须到宗庙去祭祀祖先，同时学习婚后的有关礼节。这时，奴隶们为其主人采办祭品、整治祭具、设置祭坛，奔走终日、劳碌不堪，这首诗就是描写她们劳动过程的。全诗三章，每章四句。首章两问两答，点出采蘋、采藻的地点，次章两问两答，点出盛放、烹煮祭品的器皿，末章两问两答，点出祭地和主祭之人。\n\n　　俗话说：“上供神吃，心到佛知。”这些普普通通的祭品和繁琐的礼仪，却蕴积着人们的寄托和希冀，因而围绕祭祀的一切活动都无比虔诚、圣洁、庄重，正如《左传·隐公三年》所说：“苟有明信，涧溪沼沚之毛，蘋蘩蕰藻之菜，筐筥錡釜之器，潢污行潦之水，可荐于鬼神，可羞于王公。”因此，诗人不厌其烦，不惜笔墨，层次井然地叙写祭品、祭器、祭地、祭人，将繁重而又枯燥的劳动过程描写得绘声绘色。\n\n　　这首诗的艺术魅力主要源于问答体的章法，而其主要构成因素就是五个“于以”的运用。全诗节奏迅捷奔放，气势雄伟，而五个“于以”的具体含意又不完全雷同，连绵起伏，摇曳多姿，文末“谁其尸之，有齐季女”戛然收束，奇绝卓特，烘云托月般地将季女的美好形象展现给读者。', poem_tags = '诗经' WHERE poem_title = '采蘋' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '白银烛台放射出的光线照亮了画屏，在晴朗的夜晚静静地坐在亭子里。妇女们用蛛丝穿过绣针在乞巧，金鼎中焚烧着龙麝香，人们都在庆祝人间七夕这个佳节，躺下来看牵牛织女星得鹊桥相会月亮飘过梧桐树投下了倒影。', poem_notes = '七夕：农历的七月初七，是牛郎和织女相会之日。\n龙麝：一种香料。', poem_tags = '七夕节,风俗' WHERE poem_title = '沉醉东风·七夕' AND poem_author = '卢挚';
UPDATE edu_poem SET poem_tags = '元宵节,怀念,亲人,组诗' WHERE poem_title = '元夕二首' AND poem_author = '王守仁';
UPDATE edu_poem SET poem_translation = '昨夜的秋风好似来自万里之外的家乡。月亮攀上了寝息之所的帷帐，冷气透入人的衣袖。在异乡作客的我抱着被子愁得睡不着觉。更哪能忍受漏壶一滴滴的声音，越发觉得长夜漫漫。\n寄居他乡回家的日子遥遥无期。梦里醒来凄绝伤神，一觉醒来满面都是相思的泪水。衣带渐渐宽松，不为别的什么。只为新到的书信，又平添了许多憔悴。', poem_notes = '屏帏：屏，屏风；帏，床帐。\n衣袂：衣袖。\n衾：被子。\n玉漏：古代计时器。长如岁：度夜如年。\n衣带渐宽：指人因忧愁而消瘦。\n新书：新写的信。', poem_tags = '思乡,婉约' WHERE poem_title = '蝶恋花·昨夜秋风来万里' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '贫家的女儿不识绮罗的芳香，想托个良媒说亲更感到悲伤。\n谁能爱我高尚的品格和情调？却都喜欢时下正流行的俭妆。\n敢夸十指灵巧针线做得精美，决不天天描眉与人争短比长。\n深恨年年手里拿着金线刺绣，都是替富人家小姐做嫁衣裳。', poem_notes = '蓬门：用蓬茅编扎的门，指穷人家。绮罗：华贵的丝织品或丝绸制品。这里指富贵妇女的华丽衣裳。\n拟：打算。托良媒：拜托好的媒人。益：更加。\n风流高格调：指格调高雅的妆扮。风流：指意态娴雅。高格调：很高的品格和情调。\n怜：喜欢，欣赏。时事俭梳妆：当时妇女的一种妆扮。称“时世妆”，又称“俭妆”。时世：当世，当今。\n针：《全唐诗》作“偏”，注“一作纤”。\n斗：比较，竞赛。\n苦恨：非常懊恼。压金线：用金线绣花。“压”是刺绣的一种手法，这里作动词用，是刺绣的意思。', poem_appreciation = '这首诗，以语意双关、含蕴丰富而为人传诵。全篇都是一个未嫁贫女的独白，倾诉她抑郁惆怅的心情，而字里行间却流露出诗人怀才不遇、寄人篱下的感恨。\n\n　　“蓬门未识绮罗香，拟托良媒益自伤。”主人公的独白从姑娘们的家常──衣着谈起，说自己生在蓬门陋户，自幼粗衣布裳，从未有绫罗绸缎沾身。开口第一句，便令人感到这是一位纯洁朴实的女子。因为贫穷，虽然早已是待嫁之年，却总不见媒人前来问津。抛开女儿家的羞怯矜持请人去作媒吧，可是每生此念头，便不由加倍地伤感。这又是为什么呢？\n\n　　从客观上看：“谁爱风流高格调，共怜时世俭梳妆。”意思是说：如今，人们竞相追求时髦的奇装异服，有谁来欣赏我不同流俗的高尚情操？就主观而论：“敢将十指夸针巧，不把双眉斗画长。”意思是说：我所自恃的是，凭一双巧手针黹出众，敢在人前夸口；决不迎合流俗，把两条眉毛画得长长的去同别人争妍斗丽。\n\n　　这样的世态人情，这样的操守格调，调愈高，和愈寡。纵使良媒能托，亦知佳偶难觅啊。“苦恨年年压金线，为他人作嫁衣裳！”个人的亲事茫然无望，却要每天每天压线刺绣，不停息地为别人做出嫁的衣裳！月复一月，年复一年，一针针刺痛着自家伤痕累累的心灵！独白到此戛然而止，女主人公忧郁神伤的形象默然呈现在读者的面前。\n\n　　良媒不问蓬门之女，寄托着寒士出身贫贱、举荐无人的苦闷哀怨；夸指巧而不斗眉长，隐喻着寒士内美修能、超凡脱俗的孤高情调；“谁爱风流高格调”，俨然是封建文人独清独醒的寂寞口吻；“为他人作嫁衣裳”，则令人想到那些终年为上司捉刀献策，自己却久屈下僚的读书人──或许就是诗人的自叹。诗情哀怨沉痛，反映了封建社会贫寒士人不为世用的愤懑和不平。\n\n　　诗人刻画贫女形象，既没有凭借景物气氛和居室陈设的衬托，也没有进行相貌衣物和神态举止的描摹，而是把她放在与社会环境的矛盾冲突中，通过独白揭示她内心深处的苦痛。语言没有典故，不用比拟，全是出自贫家女儿的又细腻又爽利、富有个性的口语，毫无遮掩地倾诉心底的衷曲。\n\n　　从家庭景况谈到自己的亲事，从社会风气谈到个人的志趣，有自伤自叹，也有自矜自持，如春蚕吐丝，作茧自缚，一缕缕，一层层，将自己愈缠愈紧，使自己愈陷愈深，最后终于突破抑郁和窒息的重压，呼出那“苦恨年年压金线，为他人作嫁衣裳”的慨叹。这最后一呼，以其广泛深刻的内涵，浓厚的生活哲理，使全诗蕴有更大的社会意义。', poem_tags = '唐诗三百首,女子,生活,哲理,怀才不遇' WHERE poem_title = '贫女' AND poem_author = '秦韬玉';
UPDATE edu_poem SET poem_translation = '洞房里昨夜花烛彻夜通明，等待拂晓拜公婆讨个好评。\n打扮好了轻轻问丈夫一声：我的眉画得浓淡可合时兴？', poem_notes = '张水部：即张籍，曾任水部员外郎。\n洞房：新婚卧室。停红烛：让红烛通宵点着。停：留置。\n舅姑：公婆。\n深浅：浓淡。入时无：是否时髦。这里借喻文章是否合适。', poem_appreciation = '《近试上张水部》载于《全唐诗》卷五百一十五。下面是当代女文学家、著名学者沈祖棻教授对此诗的赏析。\n\n　　以夫妻或男女爱情关系比拟君臣以及朋友、师生等其他社会关系，乃是中国古典诗歌中从《楚辞》就开始出现并在其后得到发展的一种传统表现手法。此诗也是用这种手法写的。\n\n　　“近试上张水部”这个标题可以帮助读者明白诗的作意，唐代应进士科举的士子有向名人行卷的风气。临到要考试了，朱庆馀怕自己的作品不一定符合主考的要求，因此以新妇自比，以新郎比张籍，以公婆比主考，写下了这首诗，征求张籍的意见。\n\n　　古代风俗，头一天晚上结婚，第二天清早新妇才拜见公婆。此诗描写的重点，乃是她去拜见之前的心理状态。首句写成婚。洞房，这里指新房。停，安置。停红烛，即让红烛点着，通夜不灭。次句写拜见。由于拜见是一件大事，所以她一早就起了床，在红烛光照中妆扮，等待天亮，好去堂前行礼。这时，她心里不免有点嘀咕，自己的打扮是不是很时髦呢？也就是，能不能讨公婆的喜欢呢？因此，后半便接写她基于这种心情而产生的言行。在用心梳好妆，画好眉之后，还是觉得没有把握，只好问一问身边丈夫的意见了。由于是新娘子，当然带点羞涩，而且，这种想法也不好大声说出，让旁人听到，于是这低声一问，便成为极其合情合理的了。这种写法真是精雕细琢，刻画入微。\n\n　　仅仅作为“闺意”，这首诗已经是非常完整、优美动人的了，然而作者的本意，在于表达自己作为一名应试举子，在面临关系到自己政治前途的一场考试时所特有的不安和期待。应进士科举，对于当时的知识分子来说，乃是和女孩儿出嫁一样的终身大事。如果考取了，就有非常广阔的前途，反之，就可能蹭蹬一辈子。这也正如一个女子嫁到人家，如果得到丈夫和公婆的喜爱，她的地位就稳定了，处境就顺当了，否则，日子就很不好过。诗人的比拟来源于现实的社会生活，在当时的历史条件之下，很有典型性。即使如今看来，读者也不能不对他这种一箭双雕的技巧感到惊叹。\n\n　　朱庆馀呈献的这首诗获得了张籍明确的回答。在《酬朱庆馀》中，他写道：\n\n　　“越女新妆出镜心，自知明艳更沉吟。\n\n　　齐纨未足时人贵，一曲菱歌敌万金。”\n\n　　由于朱的赠诗用比体写成，所以张的答诗也是如此。在这首诗中，他将朱庆馀比作一位采菱姑娘，相貌既美，歌喉又好，因此，必然受到人们的赞赏，暗示他不必为这次考试担心。\n\n　　首句写这位姑娘的身分和容貌。她是越州的一位采菱姑娘。这时，她刚刚打扮好，出现在镜湖的湖心，边采菱边唱着歌。次句写她的心情。她当然知道自己长得美艳，光彩照人。但因为爱好的心情过分了，却又沉吟起来。（沉吟，本是沉思吟味之意，引申为暗自忖度、思谋。）朱庆馀是越州（今浙江省绍兴市）人，越州多出美女，镜湖则是其地的名胜。所以张籍将他比为越女，而且出现于镜心。这两句是回答朱诗中的后两句，“新妆”与“画眉”相对，“更沉吟”与“入时无”相对。全诗以“入时无”三字为灵魂。新娘打扮得入不入时，能否讨得公婆欢心，最好先问问新郎，如此精心设问寓意自明，令人惊叹。 后半进一步肯定她的才艺出众，说：虽然有许多其他姑娘，身上穿的是齐地（今山东省）出产的贵重丝绸制成的衣服，可是那并不值得人们的看重，反之，这位采菱姑娘的一串珠喉，才真抵得上一万金哩。这是进一步打消朱庆馀“入时无”的顾虑，所以特别以“时人”与之相对。朱的赠诗写得好，张也答得妙，文人相重，酬答俱妙，可谓珠联璧合，千年来传为诗坛佳话。', poem_tags = '唐诗三百首,新婚,考试' WHERE poem_title = '近试上张籍水部 / 近试上张水部 / 闺意献张水部' AND poem_author = '朱庆馀';
UPDATE edu_poem SET poem_translation = '看那莪蒿长得高，却非莪蒿是散蒿。可怜我的爹与妈，抚养我大太辛劳！\n\n看那莪蒿相依偎，却非莪蒿只是蔚。可怜我的爹与妈，抚养我大太劳累！\n\n汲水瓶儿空了底，装水坛子真羞耻。孤独活着没意思，不如早点就去死。没有亲爹何所靠？没有亲妈何所恃？出门行走心含悲，入门茫然不知止。\n\n爹爹呀你生下我，妈妈呀你喂养我。你们护我疼爱我，养我长大培育我，想我不愿离开我，出入家门怀抱我。想报爹妈大恩德，老天降祸难预测！\n\n南山高峻难逾越，飙风凄厉令人怯。大家没有不幸事，独我为何遭此劫？南山高峻难迈过，飙风凄厉人哆嗦。大家没有不幸事，不能终养独是我！', poem_notes = '蓼（lù）蓼：长又大的样子。莪（é）：一种草，即莪蒿。李时珍《本草纲目》：“莪抱根丛生，俗谓之抱娘蒿。”\n匪：同“非”。伊：是。\n劬（qú）劳：与下章“劳瘁”皆劳累之意。\n蔚（wèi）：一种草，即牡蒿。\n瓶：汲水器具。罄（qìng）：尽。\n罍（léi）：盛水器具。\n鲜（xiǎn）：指寡、孤。民：人。\n怙（hù）：依靠。\n衔恤：含忧。\n鞠：养。\n拊：通“抚”。畜：通“慉”，喜爱。\n顾：顾念。复：返回，指不忍离去。\n腹：指怀抱。\n昊（hào）天：广大的天。罔：无。极：准则。\n烈烈：通“颲颲”，山风大的样子。\n飘风：同“飙风”。发发：读如“拨拨”，风声。\n谷：善。\n律律：同“烈烈”。\n弗弗：同“发发”。\n卒：终，指养老送终。', poem_appreciation = '《毛诗序》说此诗“刺幽王也，民人劳苦，孝子不得终养尔”，只有最后一句是中的之言，至于“刺幽王，民人劳苦”云云，正如欧阳修所说“非诗人本意”（《诗本义》），诗人所抒发的只是不能终养父母的痛极之情。\n\n　　此诗六章，似是悼念父母的祭歌，分三层意思：首两章是第一层，写父母生养“我”辛苦劳累。头两句以比引出，诗人见蒿与蔚，却错当莪，于是心有所动，遂以为比。莪香美可食用，并且环根丛生，故又名抱娘蒿，喻人成材且孝顺；而蒿与蔚，皆散生，蒿粗恶不可食用，蔚既不能食用又结子，故称牡蒿，蒿、蔚喻不成材且不能尽孝。诗人有感于此，借以自责不成材又不能终养尽孝。后两句承此思言及父母养大自己不易，费心劳力，吃尽苦头。中间两章是第二层，写儿子失去双亲的痛苦和父母对儿子的深爱。第三章头两句以瓶喻父母，以罍喻子。因瓶从罍中汲水，瓶空是罍无储水可汲，所以为耻，用以比喻子无以赡养父母，没有尽到应有的孝心而感到羞耻。句中设喻是取瓶罍相资之意，非取大小之义。“鲜民”以下六句诉述失去父母后的孤身生活与感情折磨。汉乐府诗《孤儿行》说“居生不乐，不如早去从地下黄泉”，那是受到兄嫂虐待产生的想法，而此诗悲叹孤苦伶仃，无所依傍，痛不欲生，完全是出于对父母的亲情。诗人与父母相依为命，失去父母，没有了家庭的温暖，以至于有家好像无家。曹粹中说：“以无怙恃，故谓之鲜民。孝子出必告，反必面，今出而无所告，故衔恤。上堂人室而不见，故靡至也。”（转引自戴震《毛诗补传》）理解颇有参考价值。第四章前六句一一叙述父母对“我”的养育抚爱，这是把首两章说的“劬劳”、“劳瘁”具体化。诗人一连用了生、鞠、拊、畜、长、育、顾、复、腹九个动词和九个“我”字，语拙情真，言直意切，絮絮叨叨，不厌其烦，声促调急，确如哭诉一般。如果借现代京剧唱词“声声泪，字字血”来形容，那是最恰切不过了。这章最后两句，诗人因不得奉养父母，报大恩于万一，痛极而归咎于天，责其变化无常，夺去父母生命，致使“我”欲报不能！后两章第三层正承此而来，抒写遭遇不幸。头两句诗人以眼见的南山艰危难越，耳闻的飙风呼啸扑来起兴，创造了困厄危艰、肃杀悲凉的气氛，象征自己遭遇父母双亡的巨痛与凄凉，也是诗人悲怆伤痛心情的外化。四个入声字重叠：烈烈、发发、律律、弗弗，加重了哀思，读来如呜咽一般。后两句是无可奈何的怨嗟。\n\n　　赋比兴交替使用是此诗写作一大特色。三种表现方法灵活运用，前后呼应，抒情起伏跌宕，回旋往复，传达孤子哀伤情思，可谓珠落玉盘，运转自如，艺术感染力强烈。《晋书·孝友传》载王裒因痛父无罪处死，隐居教授，“及读《诗》至‘哀哀父母，生我劬劳’，未尝不三复流涕，门人受业者并废《蓼莪》之篇”；又《齐书·高逸传》载顾欢在天台山授徒，因“早孤，每读《诗》至‘哀哀父母’，辄执书恸泣，学者由是废《蓼莪》”，类似记载尚有，不必枚举。子女赡养父母，孝敬父母，本是中华民族的美德之一，实际也应该是人类社会的道德义务，而此诗则是以充沛情感表现这一美德最早的文学作品，对后世影响极大，不仅在诗文赋中常有引用，甚至在朝廷下的诏书中也屡屡言及。《诗经》这部典籍对民族心理、民族精神形成的影响由此可见一斑。', poem_tags = '诗经,悼亡,父亲,母亲' WHERE poem_title = '蓼莪' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '长江出了西陵峡,才进入平地，水势奔腾浩荡。南边与沅水、湘水合流，北边与汉水汇聚，水势显得更加壮阔。流到赤壁之下，波浪滚滚，如同大海一样。清河张梦得，被贬官后居住在齐安，于是他在房舍的西南方修建了一座亭子，用来观赏长江的胜景。我的哥哥子瞻给这座亭子起名叫“快哉亭”。\n　　在亭子里能看到长江南北上百里、东西三十里。波涛汹涌，风云变化不定。在白天，船只在亭前来往出没；在夜间，鱼龙在亭下的江水中悲声长啸。景物变化很快，令人惊心骇目，不能长久地欣赏。能够在几案旁边欣赏这些景色，抬起眼来就足够看了。向西眺望武昌的群山，（只见）山脉蜿蜒起伏，草木成行成列，烟消云散，阳光普照，捕鱼、打柴的村民的房舍，都可以一一数清。这就是把亭子称为“快哉”的原因。到了长江岸边古城的废墟，是曹操、孙权傲视群雄的地方，是周瑜、陆逊驰骋战场的地方，那些流传下来的风范和事迹，也足够让世俗之人称快。\n　　从前，楚襄王让宋玉、景差跟随着游兰台宫。一阵风吹来，飒飒作响，楚王敞开衣襟，迎着风，说：“这风多么畅快啊！这是我和百姓所共有的吧。”宋玉说：“这只是大王的雄风罢了，百姓怎么能和您共同享受它呢？”宋玉的话在这儿大概有讽喻的意味吧。风并没有雄雌的区别，而人有生得逢时，生不逢时的不同。楚王感到快乐的原因，而百姓感到忧愁的原因，正是由于人们的境遇不同，跟风又有什么关系呢?读书人生活在世上，假使心中不坦然，那么，到哪里没有忧愁？假使胸怀坦荡，不因为外物而伤害天性（本性），那么，在什么地方会不感到快乐呢？（读书人生活在世上，如果他的内心不能自得其乐，那么，他到什么地方去会不忧愁呢？如果他心情开朗，不因为环境的影响而伤害自己的情绪，那么，他到什么地方去会不整天愉快呢？）\n　　张梦得不把被贬官而作为忧愁，利用征收钱谷的公事之余，在大自然中释放自己的身心，这是他心中应该有超过常人的地方。即使是用蓬草编门，以破瓦罐做窗，都没有觉得不快乐，更何况在清澈的长江中洗涤，面对着西山的白云，尽享耳目的美景来自求安适呢？如果不是这样，连绵的峰峦，深陡的沟壑，辽阔的森林，参天的古木，清风拂摇，明月高照，这些都是伤感失意的文人士大夫感到悲伤憔悴而不能忍受的景色，哪里看得出这是畅快的呢！\n　　元丰六年十一月初一，赵郡苏辙记。', poem_notes = '【江出西陵】江，长江。出，流出。西陵，西陵峡，又名夷陵峡，长江三峡之一，在湖北宜昌西北。\n【始】才\n【奔放肆大】奔放，水势疾迅。肆大，水流阔大。肆，极，甚。\n【南合沅、湘，北合汉沔（miǎn）】沅，沅水（也称沅江）。湘，湘江。两水都在长江南岸，流入洞庭湖，注入长江。汉沔，就是汉水。汉水源出陕西宁羌，初名漾水，东流经沔县南，称沔水，又东经褒城，纳褒水，始称汉水。汉水在长江北岸。\n【益张】更加盛大。张，大。\n【赤壁】赤鼻矶，现湖北黄冈城外，苏辙误以为周瑜破曹操处。\n【浸（jìn）灌】浸，灌，意思都是“注”。此处指水势浩大。\n【清河张君梦得谪居齐安】清河，县名，现河北清河。张君梦得，张梦得，字怀民，苏轼友人。齐安，宋代黄冈为黄州齐按郡，因称。谪，贬官。居，居住。\n【即】就着，依着。\n【胜】胜景，美景。\n【亭之所见】在亭上能够看到的（范围）。所见，所看到的景象。\n【一舍（shè）】三十里。古代行军每天走三十里宿营，叫做“一舍”。\n【风云开阖（hé）】风云变化。意思是风云有时出现，有时消失。开，开启。阖，闭合。\n【倏忽】顷刻之间，一瞬间，指时间短。\n【动心骇目】犹言“惊心动魄”。这是指景色变化万端，能使见者心惊，并不是说景色可怕。这里动和骇是使动用法。解释为：使……惊动，使……惊骇\n【不可久视】这是说，以前没有亭子，无休息之地，不能长久地欣赏。\n【今乃得玩之几席之上】可以在亭中的几旁席上赏玩这些景色。几，小桌，茶几。\n【举目而足】抬起眼来就可以看个够。\n【草木行列】草木成行成列非常茂盛，形容草木繁荣。\n【指数】名词作状语，用手指清点。\n【长洲】江中长条形的沙洲或江岸。\n【故城之墟】旧日城郭的遗址。故城，指隋朝以前的黄州城（唐朝把县城迁移了）。墟，旧有的建筑物已被毁平而尚留有遗迹的空地。\n【曹孟德、孙仲谋之所睥睨】曹操（字孟德）、孙权（字仲谋）所傲视的地方。睥睨，斜视的样子，引申为傲视。赤壁之战时，曹操、孙权都有气吞对方的气概。\n【周瑜、陆逊之所骋骛（chěngwù）】周瑜、陆逊均为三国时东吴的重要将领。周瑜、陆逊活跃的地方。周瑜曾破曹操于赤壁，陆逊曾袭关羽于荆州，败刘备于夷陵，破魏将曹休于皖城。骋骛，犹言“驰马”，形容他们驰骋疆场。\n【称快世俗】使世俗之人称快。称快为使动用法，使……称快。\n【楚襄王从宋玉、景差于兰台之宫】宋玉有《风赋》，讽楚襄王之骄奢。楚襄王，即楚顷襄王，名横，楚怀王之子。宋玉、景差都是楚襄王之侍臣。兰台宫，遗址在湖北钟祥东。从，使……从。\n【快哉此风】特殊句式，主谓倒装，应为“此风快哉”，解释为这风多么让人感到畅快啊！\n【披】敞开\n【当】迎接\n【盖有讽焉】大概有讽谏的意味在里头。讽，讽喻。宋玉作《风赋》，讽楚襄王之骄奢。焉，兼词 于之，在那里。\n【人有遇不遇之变】人有遇时和不遇时的不同时候。遇，指机遇好，被重用。\n【与（yù）】参与，引申为有何关系。\n【使其中不自得】使，假使。中，内心，心中。自得，自己感到舒适、自在。\n【病】忧愁，怨恨。\n【以物伤性】因外物（指环境）而影响天性（本性）。\n【适】往，去。\n【患】忧愁。\n【窃会（kuài）计之余功】窃，偷得，这里即“利用”之意。会计，指征收钱谷、管理财务行政等事务。余功，公事之余。\n【自放】自适，放情。放，纵。\n【此其中宜有以过人者】其，代词，指心胸。\n【蓬户瓮牖】蓬户，用蓬草编门。瓮牖，用破瓮做窗。蓬、瓮，名词作状语。\n【濯】洗涤。\n【揖】拱手行礼。这里的意思是面对（西山白云）。\n【自适】自求安适。适，闲适。\n【此皆骚人思士之所以悲伤憔悴而不能胜者】此，指“连山绝壑，长林古木”等快哉亭上所见景物。骚人思士，指心中有忧思的人。胜，承受，禁（jīn）得起。\n【乌睹其为快也哉】哪里看得出这是畅快的呢！乌……哉，哪里……呢。乌，哪里。\n【赵郡】苏辙先世为赵郡栾城（今河北赵县）人\n【朔】夏历每月初一。\n【望】每月月圆时，即十五。\n【既望】夏历每月十六\n【晦】夏历每月最后一天。', poem_tags = '古文观止,叙事,写景,抒情,议论,散文' WHERE poem_title = '黄州快哉亭记' AND poem_author = '苏辙';
UPDATE edu_poem SET poem_translation = '床枕上弥漫着云气，使我恍若睡在千峰之上；阵阵松涛从万壑传来，似乎就在我床底下轰响。\n我忍不住想去看那如山般高高涌过的波浪，一打开窗户，滚滚长江仿佛扑进了我的窗栏。', poem_notes = '甘露：甘露寺，在江苏镇江北固山上。寺建于唐文宗大和年间，宋真宗大中祥符年间重建。北固山下临长江，当时江阔十余里。相传建寺时露水适降，因而得名。\n松声万壑（hè）：形容长江的波涛声像万壑松声一样。壑，山沟。\n银山拍天浪：形容波浪很大，像银山一样。', poem_appreciation = '甘露寺在镇江北固山巅，濒临大江，因此这首诗着力描绘地势，在构思时，不用实笔，全通过想象，描绘出一幅空阔奇妙的江南夜色图，写出了江水的壮观和甘露寺的险要。首句写山峰的云气，次句写山谷的松声，末两句写长江的风采。一句诗一个画面，全诗浑成合美。诗中有画，景中有情。\n\n　　写景诗，许多诗人往往爱从视觉落笔，如唐代诗人李白的：“危楼高百尺”（《夜宿山寺》），贾岛的“松下问童子”（《寻隐者不遇》）。曾公亮却避开这种传统的写法，另辟蹊径，独出机杼，从感受、听觉去写。诗题是“宿甘露僧舍”，所以围绕“宿”字展开。睡在寺里，房间中自然不可能有云雾，所谓“枕中云气”，当是长江水汽会在高处，令人觉得空气很湿，甚至枕中已经凝结了些许水珠。诗人躺在枕上，感受到枕中微湿，自然联想起长江之浩瀚，甚至误以为自己身处云峰之间。接着，诗人又写床底穿来的江水之声，那阵阵惊涛，仿佛狂风席卷山谷，招起无数苍松摇撼助威，其声壮烈奔腾之至。“枕中”“床底”，点明诗人已经就寝，紧扣诗题“宿”字。“万壑哀”，语出杜甫《诸将五首》之五：“巫峡清秋万壑哀”。曾公亮诗中的这一“哀”字，恰切地摹写了风吹松林所发出的低沉悲壮的声音。用“千”写“峰”，用“万”写“壑”，极尽形容，从纵向描写北固山奇险变幻、充满生机的景象。这起二句是睡在床上的感受与幻想，是通过感官来证实它存在，虽然没有具体的肯定，逼真感很强，尽管北固山没有千山万壑存在。“云气”、“松声”，一在枕上，一在床下，都反映了江水之猛劲；而感觉到云气，凝听到松涛，也反映了诗人心底的宁静。这两句写近景，对仗工稳，用笔细腻，文字跌宕生姿。\n\n　　三、四句写远景。诗人来到甘露寺原是为了住宿歇息的，可寺外千山万壑的松涛声和不尽江流的喧哗声，搅扰着他，辗转反侧，不能安眠。诗人情绪激动了，索性披衣起床，打开窗户，迎风伫立，凭栏远眺。天空没有月色星光，地上熄了万家灯火。周围的一切都被黑暗吞噬，看不见山，看不见树，也看不见远处的城廓。只有横躺在北固山下的长江，这条水的巨龙，力的怪神，在没日没夜、无休无止地掀起惊天的狂澜，发出动地的长吟，不甘沉默，永无睡意。诗人虽然看不清，但能想象出它那汹涌澎湃的壮阔气象。于是掉转诗笔，将描写对象由千峰、万壑转向长江、巨浪，开拓出一个奇丽广阔的新境界。“银山拍天浪”是写得很精彩的景语，气势警拔，形象生动，层层修饰，词约义丰。“银山”从色、形、质等多方面地细致入微地刻画波涛的光彩、巨大以及沉重感。“拍天”则状波峰的突兀和高峻，使人感到惊心动魄，惶惶不安。不用“玉山”而写“银山”，用词是雕琢的。银是仅次于金的贵重金属，色白而灿烂。用鲜亮的词把平凡的波涛写得十分美好，格外显豁，寄寓着诗人高洁的情怀。\n\n　　末句构思很奇特，仍用幻笔，不说开窗看如雪白浪，而说奔腾翻滚的长江被“放”进窗来，把长江的气势写透写活，作者眼前似乎看到浪花要扑进窗来的奇观，深深地被长江的伟观所震撼。“放入”，自然是长江先前想要入窗而不得，诗人到此刻才将它放了进来。原来所谓“枕中云气”，所谓“床底松声”，都是长江有意而为。长江想要冲进房间，好让诗人欣赏自己的奇伟，便先以枕云相示，后以骇浪相呼，不停地邀请着诗人，召唤着诗人，诗人便再也无心睡眠，欣然开窗，与长江陶醉在了一起。明明是诗人向往长江景色，到了诗人笔下，却成了长江招引着诗人去欣赏，通篇用反客为主而不露痕迹，前后呼应之间又只觉一气呵成，笔法高超。这一写作及炼字方法，与杜甫《绝句》“窗含西岭千秋雪”相仿，但杜诗写的是静态，曾诗写的是动态，更具魄力，只有稍后的王安石绝句“两山排闼送青来”可与媲美。\n\n　　此诗的艺术特色主要有三点：\n\n　　一、内容丰厚，境界阔大。仅二十八个字的绝句，就写了枕、床、窗、山、峰、壑、江、浪、银、云气、松声等许多事物，从而扩大了诗歌的表现力。诗人身处斗室之中，想象飞越千里之外，从上到下，由近及远，描写夜幕下的群山万壑、千里大江，展现了辽阔渺远，壮丽迷人的江南夜色，笔法空灵，词意蕴藉。\n\n　　二、以动写静，景中寓情。诗人创造了一种静谧的意境，却是用动的描写来取得这种效果的。流荡的“云气”，哀呜的“松声”，奔涌的大江，喧嚣的涛音，这些动的景物，给小诗注入了无限的生机，同时又通过动，更加突出地显示了大自然的宁静。诗中似无直接的抒情，但诗人热爱祖国河山、赞颂江南夜色的美好感情，却从有声有色、有动有静的景物描写中显现出来。曾公亮所处的北宋时代，党争激烈，阶级矛盾尖锐，在承平盛世的气象下，酝酿着深刻的社会危机。诗人对此不无隐忧。“万壑哀”“拍天浪”，正是一个清醒的政治家对时局深感不安的心理的曲折反映。\n\n　　三、语言质朴、平中见奇。诗人很注重选词炼语，用了许多朴素无华的词语，如“千”“万”“大”“哀”“放入”等等，重笔虚写浩茫夜色中的壮伟奇观：气势磅礴的大江，“银山拍天”的浪涛。造境，于宏阔中出雄奇；抒情，在平淡中见深沉；具有强烈的震撼人心的艺术力量。此诗一句一景，景中寓情，从小处着笔写出了长江的宏伟气势。', poem_tags = '古诗三百首,豪迈,写景,长江' WHERE poem_title = '宿甘露寺僧舍' AND poem_author = '曾公亮';
UPDATE edu_poem SET poem_translation = '水国之夜是笼罩在凄寒的月色之中的，寒冷的月色与夜幕笼罩中的深青山色浑为一体，苍苍茫茫。\n谁说友人千里之别从今晚就开始了？可离别后连相逢的梦也杳无踪迹，它竟像迢迢关塞那样遥远。', poem_notes = '水国：犹水乡。蒹葭（jiānjiā）：水草名。《诗经·秦风·蒹葭》：“蒹葭苍苍，白露为霜。所谓伊人，在水一方。”本指在水边怀念故人，后以“蒹葭”泛指思念异地友人。\n苍苍：深青色。\n今夕：今晚，当晚。\n离梦：离人的梦。杳（yǎo）：无影无声。关塞：一作“关路”。', poem_appreciation = '昔人曾称道这位“万里桥边女校书”“工绝句，无雌声”。她这首《送友人》就是向来为人传诵，可与“唐才子”们竞雄的名篇。此诗表明上似清空一气，其实短幅中有无限蕴藉，藏无数曲折。\n\n　　前两句写别浦晚景。“蒹葭苍苍，白露为霜”，可知是秋季。“悲哉秋之为气也，萧瑟兮草木摇落而变衰；憭栗兮若在远行，登山临水兮送将归”，这时节相送，当是格外难堪。诗人登山临水，一则见“水国蒹葭夜有霜”，一则见月照山前明如霜，这一派蒹葭与山色“共苍苍”的景象，令人凛然生寒。\n\n　　此处不尽是写景，句中暗暗兼用了《诗经·秦风·蒹葭》“蒹葭苍苍”两句以下的诗意：“所谓伊人，在水一方。溯回从之，道阻且长；溯游从之，宛在水中央”，以表达一种友人远去、思而不见的怀恋情绪。节用《诗经》而兼包全篇之意，王昌龄“山长不见秋城色，日暮蒹葭空水云”（《巴陵送李十二》）与此诗机杼相同。运用这种引用的修辞手法，就使诗句的内涵大为深厚了。\n\n　　人隔千里，自今夕始。“千里自今夕”一语，与李益名句“千里佳期一夕休”相似，表现了诗人的无限深情和遗憾。这里却加“谁言”二字，似乎要一反那遗憾之意，不欲作“从此无心爱良夜”的苦语。似乎意味着“海内存知已，天涯若比邻”，可以“隔千里兮共明月”，是一种慰勉的语调。这与前两句的隐含离伤构成一个曲折，表现出相思情意的执着。\n\n　　诗中提到“关塞”，大约友人是赴边去吧，那再见自然很不易了，除非相遇梦中。不过美梦也不易求得，行人又远在塞北。“天长地远魂飞苦，梦魂不到关山难”（李白《长相思》）。“关塞长”使梦魂难以度越，已自不堪，更何况“离梦杳如”，连梦也新来不做。一句之中含层层曲折，将难堪之情推向高潮。此句的苦语，相对于第三句的慰勉，又是一大曲折。此句音调也很美，“杳如”的“如”不但表状态，而且兼有语助词“兮”字的功用，读来有唱叹之音，配合曲折的诗情，其味尤长。而全诗的诗情发展，是“先紧后宽”（先作苦语，继而宽解），宽而复紧，“首尾相衔，开阖尽变”（《艺概·诗概》）。\n\n　　“绝句于六艺多取风兴，故视它体尤以委曲、含蓄、自然为高。”（《艺概·诗概》）此诗化用了前人一些名篇成语，使内涵更丰富；诗意又层层推进，处处曲折，愈转愈深，可谓兼有委曲、含蓄的特点。诗人用语既能翻新又不着痕迹，娓娓道来，不事藻绘，便显得“清”。又善“短语长事”，得吞吐之法，又显得“空”。清空与质实相对立，却与充实无矛盾，故耐人玩味。', poem_tags = '离别,写景' WHERE poem_title = '送友人' AND poem_author = '薛涛';
UPDATE edu_poem SET poem_translation = '译文 一道仙鹊架起的小桥横卧在那茫茫的银河上。 听着织女的配环叮咚,看她款款地过桥而来。 我和伊人的离别是不会停息地一年复一年。 怅然间抬头望去只见到牛郎星依旧闪烁,亘古光华不变；我的哀愁啊,就渐渐的不那么明显。', poem_tags = '七夕节' WHERE poem_title = '七夕' AND poem_author = '徐凝';
UPDATE edu_poem SET poem_translation = '天宝以后，农村寂寞荒凉，家园里只剩下蒿草蒺藜。我的乡里百余户人家，因世道乱离都各奔东西。\n活着的没有消息，死了的已化为尘土。因为邺城兵败，我回来寻找家乡的旧路。\n在村里走了很久只见空巷，日色无光，一片萧条凄惨的景象。只能面对着一只只竖起毛来向我怒号的野鼠狐狸。\n四邻还剩些什么人呢？只有一两个老寡妇。宿鸟总是留恋着本枝，我也同样依恋故土，哪能辞乡而去，且在此地栖宿。\n正当春季，我扛起锄头下田，到了天晚还忙着浇田。县吏知道我回来了，又征召我去练习军中的骑鼓。\n虽然在本州服役，家里也没什么可带。近处去，我只有空身一人；远处去终究也会迷失。\n家乡既已一片空荡，远近对我来说都是一样。永远伤痛我长年生病的母亲，死了五年也没有好好埋葬。\n她生了我，却得不到我的服侍，母子二人终身忍受辛酸。人活在世上却无家可别，这老百姓可怎么当？', poem_notes = '天宝后：指安史之乱以后。开篇是以追叙写起，追溯无家的原因，引出下文。庐：即居住的房屋。但，只有，极为概括也极为沉痛地传达出安禄山乱后的悲惨景象：什么都没有，唯有一片蒿藜（也就是野草）。\n贱子：这位无家者的自谓。阵败：指邺城之败。\n日瘦：日光淡薄，杜甫的自创语。\n怒我啼：对我发怒且啼叫。写乡村的久已荒芜，野兽猖獗出没。\n这句以“宿鸟”自比，言人皆恋故土，所以即便是困守穷栖，依旧在所不辞。\n这句是说他又要被征去打仗。\n携：即离。无所携，是说家里没有可以告别的人。\n这两句是以能够服役于本州而自幸。终转迷：终究是前途迷茫，生死凶吉难料。\n齐：齐同。这两句更进一层，是自伤语。是说家乡已经一无所有，在本州当兵和在外县当兵都是一样。\n从天宝十四年安禄山作乱到这一年正是五年。委沟溪：指母亲葬在山谷里。\n两酸嘶：是说母子两个人都饮恨。酸嘶，失声痛哭。\n蒸黎：指劳动人民。蒸，众。黎，黑。', poem_appreciation = '《无家别》叙事诗的“叙述人”不是作者，而是诗中的主人公。这个主人公是又一次被征去当兵的独身汉，既无人为他送别，又无人可以告别，然而在踏上征途之际，依然情不自禁地自言自语，仿佛是对老天爷诉说他无家可别的悲哀。\n\n　　从开头至“一二老寡妻”共十四句，总写乱后回乡所见，而以“贱子因阵败，归来寻旧蹊”两句插在中间，将这一大段隔成两个小段。前一小段，以追叙发端，写那个自称“贱子”的军人回乡之后，看见自己的家乡面目全非，一片荒凉，于是抚今忆昔，概括地诉说了家乡的今昔变化。“寂寞天宝后，园庐但蒿藜”，这两句正面写今，但背后已藏着昔。“天宝后”如此，那么就会想到天宝前的情况。于是自然地引出下两句。那时候“我里百余家”，应是园庐相望，鸡犬相闻，当然并不寂寞：“天宝后”则遭逢世乱，居人各自东西，园庐荒废，蒿藜（野草）丛生，自然就寂寞了。一起头就用“寂寞”二字，渲染满目萧条的景象，表现出主人公触目伤怀的悲凉心情，为全诗定了基调。“世乱”二字与“天宝后”呼应，写出了今昔变化的原因，也点明了“无家”可“别”的根源。“存者无消息，死者为尘泥”两句，紧承“世乱各东西”而来，如闻“我”的叹息之声，强烈地表现了主人公的悲伤情绪。\n\n　　前一小段概括全貌，后一小段则描写细节，而以“贱子因阵败，归来寻旧蹊”承前启后，作为过渡。“寻”字刻画入微，“旧”字含意深广。家乡的“旧蹊”走过千百趟，闭着眼都不会迷路，如今却要“寻”，见得已非旧时面貌，早被蒿藜淹没了。“旧”字追昔，应“我里百余家”：“寻”字抚今，应“园庐但蒿藜”。“久行见空巷，日瘦气惨凄。但对狐与狸，竖毛怒我啼。四邻何所有，一二老寡妻”，写“贱子”由接近村庄到进入村巷，访问四邻。“久行”承“寻旧蹊”来，传“寻”字之神。距离不远而需久行，见得旧蹊极难辨认，寻来寻去，绕了许多弯路。“空巷”言其无人，应“世乱各东西”。“日瘦气惨凄”一句，用拟人化手法融景入情，烘托出主人公“见空巷”时的凄惨心境。“但对狐与狸”的“但”字，与前面的“空”字照应。当年“百余家”聚居，村巷中人来人往，笑语喧阗；如今却只与狐狸相对。而那些“狐与狸”竟反客为主，一见“我”就脊毛直竖，冲着“我”怒叫，好像责怪“我”不该闯入它们的家园。遍访四邻，发现只有“一二老寡妻”还活着！见到她们，自然有许多话要问要说，但杜甫却把这些全省略了，给读者留下了驰骋想象的空间。而当读到后面的“永痛长病母，五年委沟溪”时，就不难想见与“老寡妻”问答的内容和彼此激动的表情。\n\n　　“宿鸟恋本枝，安辞且穷栖。方春独荷锄，日暮还灌畦。”──这在结构上自成一段，写主人公回乡后的生活。前两句，以宿鸟为喻，表现了留恋乡土的感情。后两句，写主人公怀着悲哀的感情又开始了披星戴月的辛勤劳动，希望能在家乡活下去，不管多么贫困和孤独！\n\n　　最后一段，写无家而又别离。“县吏知我至，召令习鼓鞞”，波澜忽起。以下六句，层层转折。“虽从本州役，内顾无所携”，这是第一层转折；上句自幸，下句自伤。这次虽然在本州服役，但内顾一无所有，既无人为“我”送行，又无东西可携带，怎能不令“我”伤心！“近行止一身，远去终转迷”，这是第二层转折。“近行”孑然一身，已令人伤感；但既然当兵，将来终归要远去前线的，真是前途迷茫，未知葬身何处！“家乡既荡尽，远近理亦齐”，这是第三层转折。回头一想，家乡已经荡然一空，“近行”、“远去”，又有什么差别！六句诗抑扬顿挫，层层深入，细致入微地描写了主人公听到召令之后的心理变化。如刘辰翁所说：“写至此，可以泣鬼神矣！”（见杨伦《杜诗镜铨》引）沈德潜在讲到杜甫“独开生面”的表现手法时指出：“……又有透过一层法。如《无家别》篇中云：‘县吏知我至，召令习鼓鞞。’无家客而遣之从征，极不堪事也；然明说不堪，其味便浅。此云‘家乡既荡尽，远近理亦齐’，转作旷达，弥见沉痛矣。”\n\n　　“永痛长病母，五年委沟溪。生我不得力，终身两酸嘶。”尽管强作达观，自宽自解，而最悲痛的事终于涌上心头：前次应征之前就已长期卧病的老娘在“我”五年从军期间死去了！死后又得不到“我”的埋葬，以致委骨沟溪！这使“我”一辈子都难过。这几句，极写母亡之痛、家破之惨。于是紧扣题目，以反诘语作结：“人生无家别，何以为蒸黎！”意思是：已经没有家，还要抓走，叫人怎样做老百姓呢？\n\n　　诗题“无家别”，第一大段写乱后回乡所见，以主人公行近村庄、进入村巷划分层次，由远及近，有条不紊。远景只概括全貌，近景则描写细节。第三大段写主人公心理活动，又分几层转折，愈转愈深，刻画入微。层次清晰，结构谨严。诗人还善用简练、形象的语言，写富有特征性的事物。诗中“园庐但蒿藜”、“但对狐与狸”，概括性更强。“蒿藜”、“狐狸”，在这里是富有特征性的事物。谁也不能容忍在自己的房院田园中长满蒿藜。在人烟稠密的村庄里，狐狸也不敢横行无忌。“园庐但蒿藜”、“但对狐与狸”，仅仅十个字，就把人烟灭绝、田庐荒废的惨象活画了出来。其他如“四邻何所有？一二老寡妻”，也是富有特征性的。正因为是“老寡妻”，所以还能在那里苟延残喘。稍能派上用场的，如果不是事前逃走，就必然被官府抓走。诗中的主人公就是刚一回村，就又被抓走了的。\n\n　　诗用第一人称，让主人公直接出面，对读者诉说他的所见、所遇、所感，因而不仅通过人物的主观抒情表现了人物的心理状态，而且通过环境描写也反映了人物的思想感情。几年前被官府抓去当兵的“我”死里逃生，好不容易回到故乡，满以为可以和骨肉邻里相聚了；然而事与愿违，看见的是一片“蒿藜”，走进的是一条“空巷”，遇到的是竖毛怒叫的狐狸，真是满目凄凉，百感交集！于是连日头看上去也消瘦了。“日”无所谓肥瘦，由于自己心情悲凉，因而看见日光黯淡，景象凄惨。正因为情景交融，人物塑造与环境描写结合，所以能在短短的篇幅里塑造出一个有血有肉的人物形象，反映出当时战区人民的共同遭遇，对统治者的残暴、腐朽，进行了有力的鞭挞。', poem_tags = '叙事,战争,写景,抒怀' WHERE poem_title = '无家别' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '骑马向西走几乎来到天边，离家以后已见到两次月圆。\n今夜不知道到哪里去投宿，在这沙漠中万里不见人烟。', poem_notes = '碛（qì）：沙石地，沙漠。这里指银山碛，又名银山，在今新疆库木什附近。\n走马：骑马。\n辞家：告别家乡，离开家乡。见月两回圆：表示两个月。月亮每个月十五圆一次。\n平沙：平坦广阔的沙漠、大漠。绝：没有。人烟：住户的炊烟，泛指有人居住的地方。', poem_appreciation = '在唐代诗坛上，岑参的边塞诗以奇情异趣独树一帜。他两次出塞，对边塞生活有深刻的体会，对边疆风物怀有深厚的感情。这首《碛中作》，就写下了诗人在万里沙漠中勃发的诗情。\n\n　　诗人精心摄取了沙漠行军途中的一个剪影，向读者展示他戎马倥偬的动荡生活。诗于叙事写景中，巧妙地寄寓细微的心理活动，含而不露，蕴藉感人。\n\n　　“走马西来欲到天”，从空间落笔，气象壮阔。走马疾行，显示旅途紧张。“西来”，点明了行进方向，表明诗人扬鞭跃马，从长安出发，沿着通往西域的丝绸之路，风尘仆仆地向西进发。“欲到天”，既写出了边塞离家之远，又展现了西北高原野旷天低的气势。诗人在《碛西头送李判官入京》中写过“过碛觉天低”的雄浑诗句。大漠辽阔高远，四望天地相接，真给人以“欲到天”的感觉。“辞家见月两回圆”，则从时间着眼，柔情似水。表面上看，似乎诗人只是点明了离家赴边已有两月，交代了时间正当十五月圆；然而细一推敲，诗人无穷思念正蕴藏其中。一轮团圞的明月当空朗照，触动了诗人的情怀，他不由得思想起辞别两个月的“家”来，时间记得那么清晰，表明他对故乡、对亲人的思念之殷切。“两回圆”是经历两月的艺术说法。这句诗含蕴很丰富。十五的月亮是最圆最亮的。人们爱用月亮的圆缺来比喻人的离合，看到圆月，就会想到与家人的团圆，现在是月圆人不圆，自然不免要牵动思乡之情。诗人刚刚把他的心扉向读者打开了一条缝隙，透露出这一点点内心深处的消息，却又立即由遐想回到现实──“今夜不知何处宿，平沙万里绝人烟”。上句故设疑问，提出一个眼前急需解决的宿营问题，下句诗不作正面回答，却转笔写景：好像诗人并不关心今宵宿在何处，把读者的注意力引向碛中之景，写出了明月照耀下，荒凉大漠无际无涯的朦胧景象。景色是苍凉的，但感情并不低沉、哀伤。在诗人笔下，戎马生涯的艰苦，边疆地域的荒凉，正显示诗人从军边塞的壮志豪情。正如诗人所说：“万里奉王事，一身无所求。也知塞垣苦，岂为妻子谋！”（《初过陇山途中呈宇文判官》）。\n\n　　《碛中作》诗仅四句，但每句诗都有不同的艺术特点。起句有一股勃发的激情和大无畏的精神，雄奇壮美而豪迈；次句情深意远，含蕴丰富；三句以设问兜转，宕开前句，有转折回旋的韵致；结句似答非答，以景作结，于暮色苍茫之中，使人感到气象壮阔。整首诗显示出悲壮苍凉的艺术风格。杜甫称赞岑参的诗“篇终接浑茫”（《寄彭州高三十五使君适虢州二十七长史参三十韵》），这是指他的诗结尾浑厚，气象阔大，不可窥其涯际。从结句“平沙万里绝人烟”（一本作“平沙莽莽绝人烟”）来看，境界阔大，茫无边际，“篇终接浑茫”五字，是当之无愧的。\n\n　　这首诗以鲜明的形象造境写情，情与景契合无间，情深意远，含蕴丰富，别有神韵。', poem_tags = '边塞,沙漠,军旅,生活' WHERE poem_title = '碛中作' AND poem_author = '岑参';
UPDATE edu_poem SET poem_translation = '去年那花开时节我们依依惜别，如今花开时节我们分别已一年。\n世事渺茫自我的命运怎能预料，只有黯然的春愁让我孤枕难眠。\n多病的身躯让我想归隐田园间，看着流亡的百姓愧对国家俸禄。\n早听说你将要来此地与我相见，我到西楼眺望几度看到明月圆。', poem_notes = '李儋（dān）元锡：李儋，曾任殿中侍御史，为作者密友；元锡，字君贶，为作者在长安鄠县时旧友。\n春愁：因春季来临而引起的愁绪。黯黯：低沉暗淡。一作“忽忽”。\n思田里：想念田园乡里，即想到归隐。\n邑有流亡：指在自己管辖的地区内还有百姓流亡。愧俸钱：感到惭愧的是自己食国家的俸禄，而没有把百姓安定下来。\n问讯：探望。', poem_tags = '唐诗三百首,思念,友人,忧国忧民' WHERE poem_title = '寄李儋元锡' AND poem_author = '韦应物';
UPDATE edu_poem SET poem_translation = '日日夜夜地思念啊，我思念的人在长安。\n秋夜里纺织娘在井栏啼鸣，微霜浸透了竹席分外清寒。\n孤灯昏暗暗思情无限浓烈，卷起窗帘望明月仰天长叹。\n亲爱的人相隔在九天云端。\n上面有长空一片渺渺茫茫，下面有清水卷起万丈波澜。\n天长地远日夜跋涉多艰苦，梦魂也难飞越这重重关山。\n日日夜夜地思念啊，相思之情痛断心肝。\n\n日色将尽花儿如含着烟雾，月光如水心中愁闷难安眠。\n刚停止弹拨凤凰柱的赵瑟，又拿起蜀琴拨动那鸳鸯弦。\n只可惜曲虽有意无人相传，但愿它随着春风飞向燕然。\n思念你隔着远天不能相见。\n过去那双顾盼生辉的眼睛，今天已成泪水奔淌的清泉。\n假如不相信我曾多么痛苦，请回来明镜里看憔悴容颜。\n\n美人在时，有鲜花满堂；美人去后，只剩下这寂寞的空床。\n床上卷起不睡的锦绣袭被，至今三年犹存昙香。\n香气是经久不润了，而人竟也有去无回。\n这黄叶飘髦更增添了多少相思？\n露水都已沾湿了门外的青苔。', poem_notes = '长相思：属乐府《杂曲歌辞》，常以“长相思”三字开头和结尾。\n络纬：昆虫名，又名莎鸡，俗称纺织娘。金井阑：精美的井栏。\n簟：供坐卧用的竹席。\n渌：清澈。\n关山难：关山难渡。\n欲素：一作“如素”。素：洁白的绢。\n赵瑟：一作弦乐器，相传古代赵国人善奏瑟。\n蜀琴：一作弦乐器，古人诗中以蜀琴喻佳琴。\n燕然：山名，即杭爱山，在今蒙古人民共和国境内。此处泛指塞北。\n横波：指眼波流盼生辉的样子。\n卷不寝：一作“更不卷”。\n闻余：一作“犹闻”。\n落：一作“尽”。\n湿：一作“点”。', poem_appreciation = '其一\n\n　　这首诗大致可分两段。第一段从篇首至“美人如花隔云端”，写诗中人“在长安”的相思苦情。诗中描绘的是一个孤栖幽独者的形象。他（或她）居处非不华贵──这从“金井阑”可以窥见，但内心却感到寂寞和空虚。作者是通过环境气氛层层渲染的手法，来表现这一人物的感情的。先写所闻──阶下纺织娘凄切地鸣叫。虫鸣则岁时将晚，孤栖者的落寞之感可知。其次写肌肤所感，正是“霜送晓寒侵被”时候，他更不能成眠了。“微霜凄凄”当是通过逼人寒气感觉到的。而“簟色寒”更暗示出其人已不眠而起。眼前是“罗帐灯昏”，益增愁思。一个“孤”字不仅写灯，也是人物心理写照，从而引起一番思念。“思欲绝”（犹言想煞人）可见其情之苦。于是进而写卷帷所见，那是一轮可望而不可即的明月呵，诗人心中想起什么呢，他发出了无可奈何的一声长叹。这就逼出诗中关键的一语：“美人如花隔云端。”“长相思”的题意到此方才具体表明。这个为诗中人想念的如花美人似乎很近，近在眼前；却到底很远，远隔云端。与月儿一样，可望而不可即。由此可知他何以要“空长叹”了。值得注意的是，这句是诗中唯一的单句（独立句），给读者的印象也就特别突出，可见这一形象正是诗人要强调的。\n\n　　以下直到篇末便是第二段，紧承“美人如花隔云端”句，写一场梦游式的追求。这颇类屈原《离骚》中那“求女”的一幕。在诗人浪漫的幻想中，诗中人梦魂飞扬，要去寻找他所思念的人儿。然而“天长地远”，上有幽远难极的高天，下有波澜动荡的渌水，还有重重关山，尽管追求不已，还是“两处茫茫皆不见”。这里，诗人的想象诚然奇妙飞动，而诗句的音情也配合极好。“青冥”与“高天”本是一回事，写“波澜”似亦不必兼用“渌水”，写成“上有青冥之高天，下有渌水之波澜”颇有犯复之嫌。然而，如径作“上有高天，下有波澜”（歌行中可杂用短句），却大为减色，怎么读也不够味。而原来带“之”字、有重复的诗句却显得音调曼长好听，且能形成咏叹的语感，正《诗大序》所谓“嗟叹之不足，故永歌之”（“永歌”即拉长声调歌唱），能传达无限感慨。这种句式，为李白特别乐用，它如“蜀道之难难于上青天”、“弃我去者，昨日之日不可留；乱我心者，今日之日多烦忧”、“君不见黄河之水天上来”等等，句中“之难”、“之日”、“之水”从文意看不必有，而从音情上看断不可无，而音情于诗是至关紧要的。再看下两句，从语意看，词序似应作：天长路远关山难（度），梦魂不到（所以）魂飞苦。写作“天长路远魂飞苦，梦魂不到关山难”，不仅是为趁韵，且运用连珠格形式，通过绵延不断之声音以状关山迢递之愁情，可谓辞清意婉，十分动人。由于这个追求是没有结果的，于是诗以沉重的一叹作结：“长相思，摧心肝！”“长相思”三字回应篇首，而“摧心肝”则是“思欲绝”在情绪上进一步的发展。结句短促有力，给人以执着之感，诗情虽则悲恸，但绝无萎靡之态。\n\n　　此诗形式匀称，“美人如花隔云端”这个独立句把全诗分为篇幅均衡的两部分。前面由两个三言句发端，四个七言句拓展；后面由四个七言句叙写，两个三言句作结。全诗从“长相思”展开抒情，又于“长相思”一语收拢。在形式上颇具对称整饬之美，韵律感极强，大有助于抒情。诗中反复抒写的似乎只是男女相思，把这种相思苦情表现得淋漓尽致；但是，“美人如花隔云端”就不象实际生活的写照，而显有托兴意味。何况我国古典诗歌又具有以“美人”喻所追求的理想人物的传统，如《楚辞》“恐美人之迟暮”。而“长安”这个特定地点更暗示这里是一种政治的托寓，表明此诗的意旨在抒写诗人追求政治理想不能实现的苦闷。就此而言，此诗诗意又深含于形象之中，隐然不露，具备一种蕴藉的风度。\n\n　　其二\n\n　　此诗首句“日色欲尽花含烟，月明如素愁不眠”，开篇造境，渲染了愁苦迷蒙的相思气氛，暮色低沉烟雾缭绕的景物特征使人感到一种深深的压抑之感，奠定了整首诗的悲凉调子。夕阳斜暮，渐渐西沉，几簇花丛在低沉的暮色里显得朦朦胧胧，如被烟雾缠绕。这种如烟似梦的感知显然部分来源于思妇的眼睛，来源于思妇被相思愁绪紧紧包裹的内心。牵肠挂肚的相思使思妇所观所感的一切都带上了浓重的忧郁色彩，不独花朵，也非烟雾使然。黑夜拉开帷幕，思妇却没有进入梦乡，对丈夫切切的思念使她辗转反侧无法成眠。更可恼的，是那一轮明月，依旧发出如绢如素光洁皎然的光辉，透过孤独的窗棂，搅得多情人心绪难宁。在这句诗中，代表着团圆的明月，因其特定情境而被诗人塑造成一个冷漠的、不解离人情怀的形象。北宋晏殊《蝶恋花》有“明月不谙离恨苦，斜光到晓穿朱户”也是这个意思。面对月色如水良辰美景，思妇却只能让他虚设，想起从前种种，一颗心久久不得平静。虽然思念只是徒劳，却也心甘情愿，无心睡眠。“日”与“月”在交替，白昼与黑夜在轮回，思妇的相思也像波浪中的小船，翻腾不息，相思之苦，也只有思妇最为明了。诗人用“愁”字把这种感情明白地表达出来。\n\n　　接下来诗人描写了无法安睡的思妇，只好在月下弹一曲哀伤凄美的琴瑟，在回忆和期待中与心上人夫唱妇随。是有“赵瑟初停凤凰柱，蜀琴欲奏鸳鸯弦”两句，琴瑟合鸣，鸳鸯凤凰都是用来喻指夫妻美满之意，诗人在这里互文见义，旨在表达思妇望夫心切而又无法排解的愁绪。琴瑟都作为传情达意之物，至于“蜀琴”，更被人传说与司马相如卓文君的爱情故事有所关联。但如今琴瑟独鸣，凤凰曲难成，原本以为可以白头到老长相厮守的一对鸳鸯，竟然也天各一方，思妇的伤情可想而知。就连这思君念君为君弹奏的一首相思之曲，也无法令心上人听到，关山重重，天遥地远，纵有动听的音符，又弹于谁听呢？\n\n　　紧承这个疑问，作者继续写出，“此曲有意无人传，愿随春风寄燕然”。曲中真意，绮丽动人，但此情此曲，却无人为我传递，思妇惆怅抱憾也于事无补。只有忽发奇想，托明日和煦的春风飞往燕然，送到夫君的手里，带去我的相思。燕然山远在塞北边疆，就算把相思曲寄到又能如何呢？范仲淹有诗云“浊酒一杯家万里，燕然未勒归无计”可做此诗的一个补充。只要边疆未靖，那么重逢之念便是惘然。只是思妇的一点聊胜于无的假想罢了。但不管怎样，诗人的奇特想象仍然令人惊叹，思妇情之真、情之切，也令人为之唏嘘。\n\n　　“忆君迢迢隔青天”独立成句，又承上启下，以青天的夸张比喻两人相隔万里，从而引出下文思妇回到现实，顾影自怜独自凄凉的描写。\n\n　　这四句诗可以看作是同一个情形的表达，思妇揽镜自照，发现自己容颜憔悴，不禁悲从中来无法断绝。“昔日横波目，今成流泪泉”是唐时名句，形象而巧妙、夸张而令人信服地写出了相思成空的思妇的哀伤之状。曾经清澈如水明眸善睐的双眼，而今却成了流泪不止的两眼清泉，如此的想象和夸张让思妇的形象更具灵动的色彩，艺术之美感也更加深入人心。如“衣带渐宽终不悔，为伊销得人憔悴”一样，令人为之动容。\n\n　　“不信妾肠断，归来看取明镜前”一句则深得含蓄隽永之妙，以思妇的口吻直抒对丈夫的思念，与前一句相得益彰。思妇不关心自己的容颜憔悴，也不担心自己双眼如泪泉，反而殷殷的希望，丈夫能够早日出现，哪怕他不相信自己切肤入骨的思念也无所谓，只要他早日归来，断肠人也就心满意足了。所谓“不信”云云，无须深究，只是夫妻俩的窃窃私语，取镜相照，更是带有了闺房亲密的意味，显然，在诗人奇特的构思中，在思妇恍惚的思念中，一切又都进入了想象。\n\n　　其三\n\n　　这首诗一题为《赠远》，一题为《闺情》，而《全唐诗》卷二十五把它与前两首收在一起，题为《杂曲歌辞·长相思三首》。\n\n　　这首诗开头“美人在时花满堂，美人去后馀空床”两句诗，是写美人“在时”和“去后”心灵的巨大落差。美人在时，鸟语花香，满堂生辉；美人去后，花儿凋落，只留下一张空空的床。这里并不是说满堂真的有花儿盛开，而是因为有了美人的存在，心灵的花儿缤纷烂漫，姹紫嫣红。有美一人在我堂，满室生辉留余香。因为屋子里有美人的身影，有美人的言笑，有美人的步态，一切便鲜活起来，灵动起来，也便有了流动的气韵和色彩。只因美人在侧，花是艳的，天是蓝的，风是柔的，雨是润的。而今，物是人非，只有一张空闲着的床，再也不想去触碰。\n\n　　诗人不言他物，只选择一张空床，来突出美人离去后的孤独寂寞，是很具匠心的。看到床，他想到了什么呢？他大概想到曾经的床笫之欢，想到了美人的冰肌玉骨，想到了美人的温柔缠绵，想到了美人的娇羞软语吧。美人在怀时，他度过了多少个销魂的夜晚。良宵苦短，日高庸起，那相爱相守的一幕幕，而今，都化作了梦。美人在时，越是幸福快乐，她离去后就越是孤苦和思念。\n\n　　美人离开后，床上的绣被也被卷了起来，三年后还能闻到美人的余香。香气缭绕不绝，而美人还没有回来。多少相思，多少难眠之夜，日复一日，年复一年。其实不是那香气真的还在，那是相思者思念至极的嗅觉错乱。被搁置了三年的空床，被卷起了三年的绣被，不可能会还留有香气。\n\n　　花和床本是无情物，但一旦与自己喜欢的人有关，便涂抹上了感情色彩。所以，杜甫才会有“感时花溅泪”。《诗经·邶风·静女》中，那个年轻的男子等着心仪的女子，没有等着，抓耳挠腮之际，摆弄着女子送他的荑草，欣喜地吟唱到：“自牧归荑，洵美且异。匪女之为美，美人之贻。”在他的眼里，荑草美得出奇，但这并不是荑草真的很美，而是美人送给他的，饱含着爱意。', poem_tags = '写人,思念' WHERE poem_title = '长相思三首' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '跟随丞相，游春观景，登上了铜雀台，欢娱之情油然而生。\n仰脸望天，天空显得无比开阔，低头看地，地上记载着丞相的伟绩.\n这真是个雄伟而高大的建筑，两边的高台好似漂浮在太空。\n美丽的飞阁高接云天，远远地连着西城。\n可以看到漳河之水曲弯流长，亦可看到座座花园郁郁青青。\n（在这里）左右还有另两座高台，台上有龙凤的金玉雕像。①\n而东西两侧又有两座高桥，如同空中彩虹一般。\n（在这里）低头可看到皇都的宏大壮丽之美，抬头则见云霞的轻慢浮动之美。\n（于高台上）喜悦于众多才子的争相荟萃，好似周文王梦见飞熊而得太公望。②\n（如此得意之下）仰头享受春风的温暖轻柔，闻听春季百鸟那宛如幼婴哭泣般的嘤嘤鸣叫。\n直达天云的高台既然都已经立起来了，那么家父的愿望必定能实现！\n对天下施以仁政，使得人们对京都倍加恭敬。\n这样还要说只有齐恒公和晋文公所治理的才算是盛世，这种人岂明白到底何为圣明之君？\n就（像家父管理的）这样已经很好了！恩惠和恩泽已经远扬于天下了！\n这般成功地辅助了皇帝，安定了四方啊！\n（家父）顺天地的规律而行，其辉煌的光芒如同日月一般！\n（这般人物）应该永远尊贵而没有终止的一天，其地位会和东皇太一般，其年岁也会和东皇太一一样长寿③\n（他会）拿着龙旗遨游天地，驾着鸾车周游浏览。\n其恩德广布五湖四海，美好的事物越来越多，百姓也安康。\n希望这台子永远牢固，快乐的心情永远都不会结束。', poem_notes = '①龙凤的金玉雕像：原文里的玉龙与金凤指的是铜雀台旁边的另两座高台，一为冰井台，一为金凤台，曹植谓之玉龙与金凤。\n②周文王梦见飞熊而得太公望：太公望即姜太公。传闻周文王梦见奇像，译梦为“虎生双翼为飞熊，必有贵人相助”，后来果然有姜太公相助。曹植此说是指家父必有贵人相助，得以成大业。\n③东皇太一：是汉代人崇敬的太阳神，是《九歌》中最高天神，人首鸟身。', poem_tags = '咏物' WHERE poem_title = '铜雀台赋' AND poem_author = '曹植';
UPDATE edu_poem SET poem_translation = '记得初次相遇时的洞房情景，就只想应该永远在一起。谁知道短短的幽会欢好，竟会变成分离前的最后情爱，又恰好是在阑珊的暮春。对着满眼乱飘的柳絮，心里恐慌着这美好的春光将全部随他的离去而消释了。\n一场情爱最终寂寞，又跟谁说呢？想起以前的海誓山盟，被轻易辜负了。早知道如此难受，后悔当初不把他留住。奈何他除了长得风流端正，更还有让人朝思暮想的地方。一天不想他就要皱千次眉了，更何况想他呢？', poem_notes = '昼夜乐：词牌名，《昼夜乐》调名之曰“乐”，乃快乐之“乐”，与《齐天乐》、《永遇乐》之出于乐章，为乐府之“乐”不同；义盖彻昼彻夜行乐狂欢之意也。吴均词：“式号式呼，俾昼作夜”即属此意。至李白诗：“行乐争昼夜，自言度千秋”，调名即本斯义以创焉。\n洞房：深邃的住室。后多用以指妇女所居的闺阁。\n只合：只应该。\n小会：指两个人的秘密相会。幽欢：幽会的欢乐。离情别绪：分离前后惜别、相思的愁苦情绪。\n阑珊：将残、将尽之意。\n春色暮：即暮春，春天最后一段时间，指农历三月。\n满目：充满视野。\n伊：为第三人称代词，此词的“伊”亦指男性。\n凭谁诉：向人诉说。\n前言：以前说过的话。轻负：轻易地辜负了昨日的誓言。\n恁(nèn)地难拼：这样地难过。恁地：如此。难拼：指难以和离愁相拼。\n攒(cuán)眉千度：皱眉一千遍，形容整天愁眉紧锁。攒眉，愁眉紧锁。', poem_appreciation = '词以抒情女主人公的语气叙述其短暂而难忘的爱情故事。她从头到尾，絮絮诉说其无尽的懊悔。作者以追忆的方式从故事的开头说起，不过省略了许多枝节，直接写她与情人的初次相会。这次欢会就是他们的初次相遇。初遇即便“幽欢”，正表现了市民恋爱直捷而大胆的特点。这样的初遇，自然给女性留下特别难忘的印象，她一心认定“便只合，长相聚”。但事与愿违，初欢即又是永久的分离。\n\n　　暮春时节所见到的是“乱花狂絮”，春事阑珊。春归的景象已经令人感伤，而恰恰这时又触动了对往日幽欢幸福与离别痛苦的回忆，愈加令人感伤了。“况值”两字用得极妙，一方面表示了由追忆回到现实的转换，另一方面又带出了见景伤情的原因。“直恐好风光，尽随伊归去”之“伊”为第三人称代词，既可指男性，也可指女性。柳永的俗词是供女艺人演唱的，故其中的“伊”一般都用以指男性，此词的“伊”亦指男性。女主人公将春归与情人的离去联系起来，美好的春光她的感受中好象是随他而去了。“直恐”两字使用得很恰当，事实上春归与人去是无内联系的，她所作的主观怀疑性的判断，将二者联系起来纯是情感的附着作用所致，说明思念之强烈。“一场寂寞凭谁诉”，词情的发展中具有承上启下的作用。\n\n　　“一场寂寞”是春归人去后最易感到的，但寂寞和苦恼的真正原因是无法向任何人诉说的，也不宜向人诉说，只有深深地埋藏自己内心深处。于是整个下片转入抒写自身懊悔的情绪。作者“算前言，总轻负”，是由于她的言而无信，或是损伤了他的感情，这些都未明白交代，但显然责任是女方；于是感到自责和内疚，轻易地辜负了他的情意。再讲“早知恁地难拚，悔不当时留住。”可以看出她当初未考虑到离别后情感上竟如此难于割舍。他不仅举措风流可爱，而且还品貌端正，远非一般浮滑轻薄之徒可比，实是难得的人物。而这个人“更别有、系人心处”，写说她才能体验到的好处，也是她“难拚”的最重要的原因。\n\n　　结句“一日不思量，也攒眉千度”，非常形象地表现了这位妇女悔恨和思念的精神状态。攒眉即愁眉紧锁，是“思量”时忧愁的表情。意思是，每日都思量，而且总是忧思千次的，可想见其思念之深且切了。这两句的表述方式很别致，正言反说，语转曲而情益深。不思量已是攒眉千度了，则每日思量时又将如何，如此造语不但深刻，而且俏皮，十分传神。', poem_tags = '宋词精选,婉约,女子,伤春,怀人' WHERE poem_title = '昼夜乐·洞房记得初相遇' AND poem_author = '柳永';
UPDATE edu_poem SET poem_translation = '那个采葛的姑娘，一天没有见到她，好像隔了三月啊！\n那个采萧的姑娘，一天没有见到她，好像隔了三秋啊！\n那个采艾的姑娘，一天没有见到她，好像隔了三年啊！', poem_notes = '采：采集。葛：葛藤，一种蔓生植物，块根可食，茎可制纤维。\n萧：植物名。蒿的一种，即艾蒿。有香气，古时用于祭祀。\n三秋：三个秋季。通常一秋为一年，后又有专指秋三月的用法。这里三秋长于三月，短于三年，义同三季，九个月。\n艾：多年生草本植物，菊科，茎直生，白色，高四五尺。其叶子供药用，可制艾绒灸病。\n岁：年。', poem_appreciation = '这是一首思念情人的小诗。采葛为织布，采萧为祭祀，采艾为治病。都是女子在辛勤劳动。男子思念起自己的情人来，一日不见，如隔三秋（月、年）。说一天会像三个月，三个季节，甚至三年那样长，这当然是物理时间和心理时间的区别所在。用这种有悖常理的写法，无非是为了极言其思念之切，之深而已。\n\n　　热恋中情人无不希望朝夕厮守，耳鬓相磨，分离对他们是极大的痛苦，所谓“乐哉新相知，忧哉生别离”，即使是短暂的分别，在他或她的感觉中也似乎时光很漫长，以至于难以忍耐。此诗三章正是抓住这一人人都能理解的最普通而又最折磨人的情感，反复吟诵，重叠中只换了几个字，就把怀念情人愈来愈强烈的情感生动地展现出来了。第二章用“秋”而不用“春”“夏”“冬”来代表季节，是因为秋天草木摇落，秋风萧瑟，易生离别情绪，引发感慨之情，与全诗意境相吻合。\n\n　　全诗既没有卿卿我我一类爱的呓语，更无具体的爱的内容叙述，只是直露地表白自己思念的情绪，然而却能流传千古，后人并将这一情感浓缩为“一日三秋”的成语。关于此诗艺术感染力的奥妙，蒋立甫《风诗含蓄美论析》曾剖析说：“妙在语言悖理。”其意是说：从科学时间概念衡量，三个月、三个季节、三个年头与“一日”等同，当是悖理的，然而从诗抒情看却是合理的艺术夸张，合理在热恋中情人对时间的心理体验，一日之别，逐渐在他或她的心理上延长为三月、三秋、三岁，这种对自然时间的心理错觉，真实地映照出他们如胶似漆、难分难舍的恋情。这一悖理的“心理时间”由于融进了他们无以复加的恋情，所以看似痴语、疯话，却能妙达离人心曲，唤起不同时代读者的情感共鸣。', poem_tags = '诗经,思念,民谣' WHERE poem_title = '采葛' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '你俩乘船走了，船儿飘飘远去。多么思念你呵，心中恋意难除。\n\n你俩乘船走了，船影渐远渐没。多么思念你呵，切莫遭遇灾祸！', poem_notes = '二子：卫宣公的两个异母子。\n景：通憬，远行貌。泛泛：飘荡貌。景：闻一多《诗经通义》“景读为‘迥’，言漂流渐远也”。\n愿：思念貌。\n养（yáng羊）养：心中烦躁不安。\n瑕：训“胡”，通“无”。“不瑕”，犹言“不无”，疑惑、揣测之词。', poem_appreciation = '此诗的写作背景，据《毛诗序》所说，有一个动人的故事。《毛诗序》云：“《二子乘舟》，思伋、寿也。卫宣公之二子，争相为死，国人伤而思之，作是诗也。”毛传云：“宣公为伋取于齐女而美，公夺之，生寿及朔。朔与其母诉伋于公，公令伋使齐，使贼先待于隘而杀之。寿知之，以告伋，使去之。伋曰：‘君命也，不可以逃。’寿窃其节而先往，贼杀之。伋至，曰：‘君命杀我，寿有何罪？’又杀之。”刘向《新序·节士》则说寿知其母阴谋，遂与伋同舟，使舟人不得杀伋，“方乘舟时，伋傅母恐其死也，闵而作诗”。现代学者有认同“闵伋、寿”之说者，但持不同意见者亦多。闻一多先生猜测它“似母念子之词”（《风诗类钞》），也有学者断为一位父亲送别“二子”之作，均相近似。倘若要将它视为妻子送夫、朋友送人的诗，恐怕也无错处。总之坐实诗的本事，似乎比较牵强，还是将此篇视为一首送别诗比较合适。\n\n　　这一次动情的送别，发生在河边。“二子乘舟，泛泛其景”，用的是描述笔法。首句还是近景，两位年轻人终于拜别亲友登船；二句即镜头拉开，刹那间化作了一叶孤舟，在浩淼的河上飘飘远去。画面视点在送行者这边，所以画境之由近而远，同时就融入了送行者久立河岸、骋目远望的悠长思情。而“泛泛”的波流起伏，也便全与送行者牵念之情的跌宕，有了“异质同构”的对应，令你说不清那究竟是波流，还是牵思之漫衍了。由此过渡到“愿言思子，中心养养”，直抒送行者牵念深情，就更见得送别匆匆间的难舍难离了。“养养”是一个奇特的词汇。按照前人的解说，“养养”即“思念”之意，总嫌笼统了些。有人训“养养”为“痒痒”，顿觉境界妙出：这是一种搔着心头痒处的感觉，简直令人浑身颤抖、无法招架的奇妙反应。以此形容那驿动于送行者心上的既爱又念，依依难舍又不得不舍的难言之情，实在没有其他词汇可以替代。\n\n　　诗之二章，采用了叠章易字的写法，在相似中改换了结句。景象未变，情感则因了诗章的回环复沓，而蕴蓄得更其浓烈、深沉了。此刻，“二子”所乘之舟，早已在碧天长河中消逝，送行者却还在河岸上久久凝望。当“二子”离去时，他（她）正“中心养养”，难断那千丝万缕的离愁别绪；而今，“二子”船影消逝，望中尽是滚滚滔滔的浪波。人生的旅途上，也是充满了浪波与风险。远去的人儿，能不能顺利渡过那令人惊骇的波峰浪谷，而不被意外的风险吞没——这正是伫立河岸的送行人，所深深为之担忧的。“愿言思子，不瑕有害”二句，即以祈愿的方式，传达了这一情感上的递进和转折，在割舍不了的牵念中，涌生出陡然袭来的忧思。于是，滚滚滔滔的河面上，“泛泛其逝”的天地间，便刹那间充斥了“不瑕有害”的祝告——那是一位老母、妻子或友人，带着牵念，带着惊惧，而发自心底的呼喊：远行的人儿，究竟听见了没有？\n\n　　同是一首送别诗，《邶风·二子乘舟》写得远比《邶风·燕燕》单纯。全诗无一句比兴，诗中的意象，只有“二子”和一再重现和消逝的小舟。情感的抒泻，也没有《燕燕》那种“瞻望弗及，泣涕如雨”的细节表现。但它的内涵却极为丰富：因为画面只有飘飘远逝的二子、船影，其余全为空白，便为读者的联想，留下了更多的空间；因为背景全无，甚至也不知道送行者究竟为谁，其表现的情感便突破了特定限制，而适合于“母子”、“男女”、“友朋”，成为一种具有极大涵盖面的“人间之情”。它之能够激发各种身份的读者之共鸣，而与诗人一起唏嘘、一起牵挂，甚至一起暗暗祈告，也就毫不奇怪了。', poem_tags = '诗经,离别' WHERE poem_title = '二子乘舟' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '梅花开枝头，枝头花影稀疏、花色浅浅，那天真自然的颜色何人能与之媲美？东君统领下的百花颜色绚丽、身姿百态，却无一株能有梅花之神韵，实乃可笑呀！梅花生长于水边，迎雪绽放，不借春风之力便能肆意绽放。玉洁冰清、香嫩魂冷，骨格奇绝，其品格超凡入圣。\n还记得它曾经迎寒自开，被那梦醒后的佳人隔窗轻摘，插戴鬓边，是何等的荣耀。现在虽然飘泊天涯，形体消瘦，但风韵仍不减当年，依然冰清高洁、傲骨无双。不管是万里风烟还是一溪寒月，都未能欺侮得了它。不如远离这尘世喧嚣，归入山林，至少仙宫中还有个人在想念它。', poem_notes = '阿谁：疑问代词。犹言谁，何人。\n东君：司春之神。\n篽（yù）：禁苑。\n琐窗：为雕刻或绘有连环形花纹之窗。\n标格：风范，风度。\n阆苑：传说中在昆仑山之巅，是西王母居住的地方。在诗词中常用来泛指神仙居住的地方。', poem_appreciation = '鉴赏 　　这是一首咏物词，是咏梅花的。梅花腊月发花、多白色，也有红色者，以坚贞耐寒著称，历代文人多咏之。词的上片写梅之风韵。开头二句写其颜色。“疏疏淡淡”，谓其花影稀疏，花色浅淡，颜色天真自然，没有什么能与其天然的风韵相比。“笑杀”二句紧承上文，对此做进一步描写。在这里，作者使用映衬的手法，言在东君的管领下，有的花白，有的花红，红红白白，颜色甚多，但山下千林花太俗，都没有梅花的神韵，枉称为花，实在可笑。“雪里”二句写其凌寒独放。言梅花长在水边，开在雪里，一味清新，十分幽静，温柔明秀，远非桃李可比。“骨清”二句是赞美梅花玉洁冰清、香嫩魂冷，骨格奇绝，具有超凡入圣的品格。词的下片写梅之遭遇，映带作者身世。“常记”三句写梅花曾一度受宠，被琐窗人“纤手轻摘”，插戴鬓边，何其荣耀。“漂泊”二句以人拟物，言梅花虽然漂泊天涯，形体瘦削，憔悴不堪，但风韵不减当年，依然冰清玉洁，高雅不俗。“万里”三句是说，不论是“万里风烟”还是“一溪霜月”，都无法使其屈服，表现出梅花的坚贞。“不如”二句借花言人，表达出作者的归隐情思。细读词之下片，可以清晰地感受到，作者虽然是在写梅，却已将自己的身世之感打并入其中，而以感慨系之，寓意很深，耐人寻味。 ▲', poem_tags = '咏物,梅花,抒怀' WHERE poem_title = '念奴娇·梅' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_tags = '小学文言文,寓理,故事' WHERE poem_title = '人有负盐负薪者' AND poem_author = '李延寿';
UPDATE edu_poem SET poem_translation = '译文 　　村居的远处是流水潺潺，环绕着山坡的田地。住宅外的小园，青竹绕篱，绿水映陂，一派田园风光。槿花稀疏，一树榆钱早就随风而去了。暮色朦胧，老牛缓缓归来。牛背上并不是短笛横吹的牧牛郎，而是伫立的寒鸦。', poem_tags = '古诗三百首,乡村,写景' WHERE poem_title = '村居' AND poem_author = '张舜民';
UPDATE edu_poem SET poem_tags = '春天,惜春' WHERE poem_title = '减字木兰花·莺初解语' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '小燕子飞落在雕梁画栋的华屋，静悄悄四下无人，梧桐阴儿转过了正午。傍晚清凉时美人刚出浴。手拿着丝织的白团扇，团扇与素手似白玉凝酥。渐渐困倦，斜倚枕睡得香熟。此时不知是谁在推响彩绣的门户？空叫人惊醒了瑶台好梦。侧耳听却原来是阵阵风在敲竹。\n石榴花半开像红巾叠簇，待桃杏等浮浪花朵落尽，它才会绽开与孤独的美人为伍。细看这一枝浓艳的石榴，花瓣千层恰似美人芳心紧束。又恐怕被那西风吹落只剩叶绿。来日如等到美人来到，在花前饮酒也不忍去碰触。那时节泪珠儿和花瓣，都会一同洒落，声簌簌。', poem_notes = '贺新郎：词牌名，又名“金缕曲””贺新凉““乳燕飞”“貂裘换酒”。传世作品以《东坡乐府》所收为最早。\n乳燕：雏燕儿。飞：宋赵彦卫《云麓漫钞》谓见真迹作“栖”。\n桐阴：梧桐树阴。\n生绡（xiāo）：未漂煮过的生织物，这里指丝绢。团扇：汉班婕妤《团扇诗》：“新裂齐纨素，鲜洁如霜雪。裁为合欢扇，团团似明月。”后常以喻指佳人薄命失宠。\n扇手：白团扇与素手。一时：一并，一齐。\n清熟：谓睡眠安稳沉酣。\n枉：空，白白地。瑶台：玉石砌成的台，神话传说在昆仑山上，此指梦中仙境。曲：形容处所幽深的样子。\n风敲竹：唐李益《竹窗闻风寄苗发司空曙》：“开门复动竹，疑是故人来。\n红巾蹙（cù）：形容石榴花半开时如红巾皱缩。蹙，皱。\n浮花浪蕊：指轻浮斗艳而早谢的桃、李、杏花等。唐韩愈《杏花》：“浮花浪蕊镇长有，才开还落瘴雾中。”\n幽独：默然独守。\n秾（nóng）艳：色彩艳丽。\n千重（chóng）似束，形容石榴花瓣重叠，也指佳人心事重重。\n秋风惊绿：指秋风乍起使榴花凋谢，只剩绿叶。\n两簌（sù）簌：形容花瓣与眼泪同落。簌簌，纷纷落下的样子。', poem_appreciation = '这是一首抒写闺怨的双调词，咏人兼咏物，上片描写在清幽环境中的一位美人，她高洁绝尘，又十分孤独寂寞；下片掉转笔锋，专咏榴花，借花取喻，时而花人并列，时而花人合一。作者赋予词中的美人、榴花以孤芳高洁、自伤迟暮的品格和情感，在这两个美好的意象中渗透进自己的人格和感情。词中写失时之佳人，托失意之情怀；以婉曲缠绵的儿女情肠，寄慷慨郁愤的身世之感。\n\n　　上片以初夏景物为衬托，写一位孤高绝尘的美丽女子。起调“乳燕飞华屋，悄无人，桐阴转午，”点出初夏季节、过午、时节、环境之幽静。“晚凉新浴”，推出傍晚新凉和出浴美人。“手弄生绡白团扇，扇手一时似玉”，进而工笔描绘美人“晚凉新浴”之后的闲雅风姿。作者写团扇之白，不只意在衬托美人的肌肤洁白和品质高洁，而且意在象征美人的命运、身世。自从汉代班婕妤（汉成帝妃，为赵飞燕谮，失宠）作《团扇诗》后，在古代诗人笔下，白团扇常常是红颜薄命，佳人失时的象征。上文已一再渲染“悄无人”的寂静氛围，这里又写“手弄生绡白团扇”，着一“弄”字，便透露出美人内心一种无可奈何的寂聊，接以“扇手一时似玉”，实是暗示“妾身似秋扇”的命运。\n\n　　以上写美人心态，主要是用环境烘托、用象征、暗示方式，隐约迷离。以下写美人初因孤寂无聊而入梦，继而好梦因风摇竹声而被惊断。“渐困倚、孤眠清熟”句，使人感受到佳人处境之幽清和内心的寂寞。以下数句是说：美人入梦后，朦胧中仿佛有人掀开珠帘，敲打门窗，不由引起她的一阵兴奋和一种期待。可是从梦中惊醒，却只听到那风吹翠竹的萧萧声，等待她的仍旧是一片寂寞。此处化用了唐人李益诗句“开门复动竹，疑是玉人来”的幽清意境，着重写由梦而醒、由希望而失望的怅惘；“枉教人”、“却又是”，将美人这种感情上的波折突现出来了。这几句，如梦似幻，动而愈静，极其婉曲地表现了女主人公的孤寂。从上片整个构思来看，主要写美人孤眠。写“华屋”，写“晚凉”，写“弄扇”，都是映衬和暗示美人的空虚寂寞和叹惋怅恨之情。\n\n　　下片用秾艳独芳的榴花为美人写照。过片转咏榴花。“石榴半吐红巾蹙”，化用唐人白居易诗“山榴花似结红巾”（《题孤山寺山石榴花示诸僧众》）句意形象地写出了榴花的外貌特征，又带有西子含颦的风韵，耐人寻味。“待浮花浪蕊都尽，伴君幽独”，这是美人观花引起的感触和情思。此二句既表明榴花开放的季节，又用拟人手法写出了它不与桃李争艳、独立于群芳之外的品格。这不与“浮花浪蕊 ”为伍的榴花，也即是女主人公的象征。“秾艳一枝细看取”，刻画出花色的明丽动人。“芳心千重似束”，不仅捕捉住了榴花外形的特征，并再次托喻美人那颗坚贞不渝的芳心，写出了她似若有情、愁心难展的情态。“又恐被秋风惊绿”，由花及人，油然而生美人迟暮之感。“若待得君来向此”至结尾，写怀抱迟暮之感的美人与榴花两相怜惜，共花落簌簌而泪落簌簌。\n\n　　词的下片借物咏情，写美人看花时触景伤情，感慨万千，时而观花，时而怜花惜花。这种花人合一的手法，产生一种婉曲缠绵、寻味不尽的效果。作者无论是直接写美人，还是通过榴花间接写美人，都紧紧扣住娇花美人失时、失宠这一共同点，而又寄托着词人自身的怀才不遇之情。\n\n　　这首词隐约地抒写了作者怀才不遇的抑郁情怀。苏轼笔下的佳人，大多丰姿绰约，雍容闲雅。无论《洞仙歌·冰肌玉骨》里“冰肌玉骨，自清凉无汗”的花蕊夫人，还是这首词中的出浴美女，都能给人一种洁净如玉、一尘不染的美感。从艺术上看，上片主要写佳人，但没有正面描写她的姿容，而是先写佳人的扇和执扇的手；下片别开异境，前五句写石榴，后五句佳人与石榴合写，亦花亦人，巧妙新颖，和谐自然。此词之意蕴，冠绝古今，取景清幽，意象清隽，托意高远。', poem_tags = '宋词精选,婉约,夏天,写景,写花,女子,孤独' WHERE poem_title = '贺新郎·夏景' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '浓妆艳抹打扮一新下红楼，深深庭院春光虽好只添愁。\n走到庭中查数新开的花朵，蜻蜓有情飞到了玉簪上头。', poem_notes = '春词：春怨之词。“春词”为白居易原诗题目。\n宜面：脂粉和脸色很匀称。一作“粉面”。朱楼：髹以红漆的楼房，多指富贵女子的居所。\n蜻蜓：暗指头上之香。玉搔头：玉簪，可用来搔头，故称。', poem_appreciation = '这首诗的标题写得很清楚，它是和白居易《春词》一诗的。白居易的《春词》：“低花树映小妆楼，春入眉心两点愁。斜倚栏杆背鹦鹉，思量何事不回头？”白居易诗先描绘一个斜倚栏杆、背向鹦鹉、眉目含愁的青年女子形象，接着以“思量何事不回头”的问句，轻轻一拨，引而不发，意味深长。而刘禹锡的和诗，也写闺中女子之愁，然而却写得更为婉曲新颖，别出蹊径。\n\n　　白诗开头是以“低花树映小妆楼”来暗示青年女子，而刘诗“新妆宜面下朱楼”说得十分明确，而且顺带把人物的心情也点出来了。诗中女主人公梳妆一新，急忙下楼。“宜面”二字，是说脂粉涂抹得与容颜相宜，给人一种匀称和谐的美感，这说明她妆扮得相当认真、讲究。看上去，不仅没有愁，倒似乎还有几分喜色。艳艳春光使她暂时忘却了心中苦恼，这良辰美景，使她心底萌发了一丝朦胧的希望。\n\n　　诗的第二句是说下得楼来，确是莺歌蝶舞，柳绿花红。然而庭院深深，院门紧锁，独自一人，更生寂寞，于是满目生愁。从诗的发展看，这是承上启下的一句。三、四两句是进一步把这个“愁”字写足。这位女主人公下楼的本意不是为了寻愁觅恨，要是早知如此，她就不必“下朱楼”，也不必“新妆宜面”。可是结果恰恰惹得无端烦恼上心头。这急剧变化的痛苦的心情，使她再也无心赏玩，只好用“数花朵”来遣愁散闷，打发这大好春光。“数花朵”的原因当亦有对这无人观赏、转眼即逝的春花，叹之、怜之、伤之的情怀。就在她在默默地数着时，“蜻蜓飞上玉搔头”。这是十分精彩的一笔。它含蓄地刻画出她那沉浸在痛苦中的凝神伫立的情态；它还暗示了这位女主人公有着花朵般的容貌，以至于使常在花中的蜻蜓也错把美人当花朵，轻轻飞上玉搔头；而且也意味着她的处境亦如这庭院中的春花一样，寂寞深锁，无人赏识，只能引来这无知的蜻蜓。真是花亦似人，人亦如花，春光空负。“为谁零落为谁开？”这就自然而含蓄地引出了人愁花愁一院愁的主题。有人说：“诗不难于结，而难于神”。这首诗的结尾是出人意料的，诗人剪取了一个偶然的镜头——“蜻蜓飞上玉搔头”，蜻蜓无心人有恨。这个结句是在回应“思量何事不回头”而设计的，它洗炼而巧妙地描绘了这位青年女子在春光烂漫之中的冷寂孤凄的境遇，新颖而富有韵味，真可谓结得有“神”。', poem_tags = '唐诗三百首,春天,女子,孤独' WHERE poem_title = '和乐天春词' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '楚军攻打宋国以援救郑国。宋襄公将要迎战，大司马公孙于是劝阻说，“上天遗弃商朝已经很久了，君王要振兴它，不可，赦免楚国吧。”襄公不听。宋襄公和楚国人在泓水交战。宋军已经排成战斗的行列，楚国人没有全部渡过泓水。子鱼说：“对方人多，我方人少，趁着他们没有全部渡过泓水，请攻击他们。”宋襄公说：“不行。”楚军全部渡河，但尚未排好阵势，（子鱼）再次报告（宋襄公）。宋襄公说：“还不行。”（楚军）摆好阵势（宋军）才攻击楚军。宋军大败，宋襄公大腿受伤，国君的卫士被杀绝了。\n\n　　国人都责备宋襄公。襄公说：“君子不再伤害已经受伤的人，不俘虏头发斑白的老人。古代用兵的道理，不凭借险隘的地形阻击敌人。我虽然是亡国者的后代，（也）不攻击没有排成阵势的敌人。”子鱼说：“主公不懂得作战。面对强大的敌人，（敌人）因地势险阻而未成阵势，这是上天帮助我们；阻碍并攻击他们，不也可以吗？还有什么害怕的呢？而且现在强大的，都是我们的敌人。即使是年纪很大的人，能俘虏就抓回来，还管什么头发斑白的敌人？教导士兵作战，使他们知道退缩就是耻辱来鼓舞战斗的勇气，教战士掌握战斗的方法，就是为了杀死敌人。（敌人）受伤却还没有死，为什么不能再杀伤他们？如果怜惜（他们，不愿）再去伤害受伤的敌人，不如一开始就不伤害他们；怜惜头发斑白的敌人，不如（对敌人）屈服。军队凭借有利的时机而行动，锣鼓用来鼓舞士兵的勇气。利用有利的时机，当（敌人）遇到险阻，（我们）可以进攻。声气充沛盛大，增强士兵的战斗意志，攻击未成列的敌人是可以的。”', poem_notes = '（1）宋公：宋襄公，名兹父。前638年,宋伐楚,楚救郑,这年冬天宋楚两军交战于泓.。\n（2）大司马：掌管军政、军赋的官职，这里指公孙固。\n（3）泓：泓水，在今河南省柘（zhè这）城县西。\n（4）既：已经。\n（5）济：渡过。\n（6）司马：统帅军队的高级长官，此指目夷，字子鱼。\n（7）告：报告。\n（8）陈：通“阵”，这里作动词，即摆好阵势。\n（9）败绩：大败。\n（10）股：大腿。\n（11）门官：国君的卫士。\n（12）咎：怪罪，归罪，指责。\n（13）重（chóng从）再次。\n（14）禽：通“擒”,俘虏。二毛：头发斑白的人，指代老人。\n（15）阻，迫也。隘，险也。言不迫人于险。\n（16）寡人：国君自称。亡国之余：亡国者的后代。宋襄公是商朝的后代，商亡于周。\n（17）鼓：击鼓（进军）名词做动词。\n（18）勍（qíng）敌：强敌，劲敌。勍：强而有力。\n（19）隘：这里作动词，处在险隘之地。\n（20）赞：助。\n（21）成列：排成战斗行列.\n（22）胡耇（gǒu苟）：年纪很大的人。胡：年老。\n（23）何有于二毛：意思是还管什么头发花白的敌人。\n（24）明耻:使认识什么是耻辱.教战:教授作战的技能。\n（25）爱重伤：怜悯受伤的敌人。\n（26）服：（对敌人）屈服。\n（27）三军：春秋时，诸侯大国有三军，即上军，中军，下军。这里泛指军队。用：施用，这里指作战。\n（28）金鼓：古时作战，击鼓进兵，鸣金收兵。金：金属响器。声气：振作士气。\n（29）儳（chán谗）：不整齐，此指不成阵势的军队。', poem_tags = '古文观止,议论,写人' WHERE poem_title = '子鱼论战' AND poem_author = '左丘明';
UPDATE edu_poem SET poem_translation = '梦中走向了烟水迷蒙的江南路，走遍了江南大地，也未能与离别的心上人相遇。梦境里黯然销魂无处诉说，醒后惆怅不已全因梦中消魂误。\n想诉说我的相思提笔给你写信，但是雁去鱼沉，到头来这封信也没能寄出。无可奈何缓缓弹筝抒发离情别绪，移破了筝柱也难把怨情抒。', poem_notes = '蝶恋花，又名“鹊踏枝”、“凤栖梧”。唐教坊曲。《乐章集》《张子野词》并入“小石调”，《清真集》入“商调”。双调六十字，上下片各四仄韵。\n消魂：魂魄消灭。多以名悲伤愁苦之状。\n惆怅：因失望或失意而哀伤。消魂：一作“佳期”。\n尺素：书写用之尺长素绢，借指简短书信。素：白绢。古人为书，多写于白绢上。\n浮雁沉鱼：古代诗文中常以鸿雁和鱼作为传递书信的使者。\n终了：纵了，即使写成。无凭据：不可靠，靠不住。\n移破：犹云移尽或移遍也。破：唐宋大曲术语。大曲十余遍，分散序、中序、破三大段。张相《诗词曲语辞汇释》：破，犹尽也，遍也，煞也。', poem_tags = '宋词精选,闺怨,叙梦,相思' WHERE poem_title = '蝶恋花·梦入江南烟水路' AND poem_author = '晏几道';
UPDATE edu_poem SET poem_translation = '一个有见识的人，他做学问必然喜欢向别人提问请教。“问”和“学”是相辅相成地进行的，不“学”就不能提出疑难，不“问”就不能增加知识。喜爱学习却不多问，不是真的喜爱学习的人。道理明白了，可是还不能应用于实际，认识了那些大的（原则、纲领、总体），可是还可能不了解那些细节，（对于这些问题）除了问，怎么能解决问题呢？\n\n　　（对于）比自己道德才能高的人，向他们问，借以破除那疑问，（这就是孔子）所说的到有道德有学问的人那里去匡正自己。（对于）不如自己的人，向他们问，借以求得一点正确的见解，（这就是曾子）所说的以高才能向低才能（的人）问，以道德高知识多向道德低知识少（的人）问。（对）同自己水平相等的人，向他们问，借以共同研究，（这就是《中庸》）所说的互相诘问，详细地考察，明确地分辨它。《尚书》不是说吗？“喜爱问（的人，学问知识）就丰富。”孟子论述：“找回自己的放纵散漫的心”（的时候），并提“学问之道”，“学”之后（就）紧跟着“问”。子思谈“重视品德修养”（时），归结到要（好）问（勤）学，（在他的提法中）“问”并且在“学”的前面。\n\n　　古代的人虚心采纳善言善事，不挑选事情地问，不挑选人地问，（只要能）求取那有益于自己修养和学业的就可以了。因此，狂妄的普通人的话，圣人（也）采纳它，地位低微的樵夫，古圣先王（也）询问他，舜帝有天子的身份都向平民询问，以（他们的）大智却注意到浅近平常的意见，不是偶然的谦虚，实在是要从多方面听取有益的意见。三代以后，有“学”而没有“问”，朋友间的交往，能做到规劝做好事，不做坏事就不错了，那种在大是大非问题上互相请教，勤勉地只是以进修为急务（的人）未多见，（更）何况世俗的人呢？\n\n　　认为自己对，别人不对，（这是）世俗人的共同毛病，学习有未贯通（不理解的地方），（却）偏偏以为理解，（所持的）道理有不稳妥（的地方），（却）胡乱地凭主观猜测，像这样，就终生几乎（都）没有（什么）可问的事（了）。（对）比自己道德才能高的人，（就）妒忌他，不愿意向他问，（对）不如自己的人，（就）轻视他，（认为）不值得向他问，（对）同自己水平相同的人，抱着嬉戏的态度而不敬重他，不甘愿向他问，像这样，就天下几乎没有可以问的人了。（什么）人（都）不值得佩服了，（什么）事（都）没有可疑的了，这只是自以为是罢了。自以为是，那错误还是小的；自己知道自己的浅薄却严密地掩盖自己的过错，宁愿让学习最终不进步，（也）不愿意虚心向别人请教，这样危害自己的内心修养，（错误可就）大了，而陷入这（种大错误）的人常常（占）十分之八九。\n\n　　不这样（的话），就所问的（也）不是（他）所学的：（如）问（一些）天下的奇字僻典和琐屑事物来说说好玩；甚至自己心里所已经明白的（问题，却故意拿它），问别人，来试试那人的才能；（或者）非常难解答的事情问别人，来逼使那人难堪。如果不是这样，（或者）即使有与自己思想品德修养有密切关系的事情，可以收到得到教益的效果的，要压低一下自己的尊严（虚心向别人请教）也不能做到。唉！学习之所以不能接近古人，不是（正）由于这（原因）吗？\n\n　　而且不喜爱问的人，（是）由于不能虚心；不能虚心（是）由于不诚心实意喜爱学习。也不是不专心用功的缘故，他学习的不是古代儒家学习的（东西），他喜爱的也不是古代儒家喜爱的（东西），不善于问是理所当然的。\n\n　　聪明的人考虑一千次，（也）一定会出现一次错误。圣人所不了解（的事物），普通的人不一定也不了解；普通的人所能做的，圣人不一定能做。真理不专门存在于某人，学习是没有止境的，那么，“问”可以少得了吗？《周礼》（说），朝堂之外（要）询问百姓（对朝政的意见），国家的大事还问到平民。所以贵人可以问身份低的人，道德才能高的人可以问道德才能低的人，老人可以问年轻的人，只考虑道德学问方面的成就罢了。 孔文子不以向比他低下的人请教为耻辱，孔子认为他道德学问高。古人把“问”作为美德，而并不认为它是可耻的，后代的君子反而争先把“问”当作耻辱，那么古人所深深地（感到）羞耻的（事），后代人却做着而不以为耻的（就）多了，可悲啊！', poem_notes = '君子：古时对有德有才人的称呼。\n辅：辅助。好：喜好\n无以致疑：不会发现疑问；无以：没有用来……的（办法）；致：求得。\n广识：增广知识；广：使……广，增广，增加。\n达于事：（使道理）用于实行。达，通晓，通达。\n舍问：放弃提问。舍：放弃。\n其奚决焉：怎么能解决问题呢；奚：何，怎么 。 其：之，代词，指代文中的“理”与“识” 。焉，代词，指代上述的“理”与“问”。 决：判断，解决。\n就有道而正：到有道德有学问的人那里去匡正自己；就：靠近；正：匡正；\n以资切磋：借以共同研究；资：凭借。\n交相问难（nàn）：互相诘问；难：驳诘。\n审：详细。\n是己而非人：以己为是，以人为非。是:以……为是；认为……对 非：以……为非。\n未安：不稳妥的地方。\n臆度（yì duó）：主观猜测；臆：主观的；度：猜测，估计\n狎（xiá）：亲近而不庄重。\n专在：专门存在于某人。\n唯，只。\n舍问，其奚决焉 舍，放弃。\n君子之学必好问 必：必须 好：喜欢，喜爱。\n而或：但却。\n不肖：不成器的人。\n是故：因此。\n相辅而行：互相协助进行。\n贤：道德才能高。\n破：破解。\n理：真理。\n知：了解，明白。\n强：勉强。\n不屑：不重视，轻视。\n问说：关于勤问的论说。\n几：几乎。\n然则：既然这样,那么。\n忌：嫉妒。\n或：有时。\n妄：胡乱地。\n得：某一方面的见解。', poem_tags = '小学文言文,学习,哲理' WHERE poem_title = '问说' AND poem_author = '刘开';
UPDATE edu_poem SET poem_translation = '汉末王朝权力失控，董卓专权乱了纲常朝政。他一心密谋杀君夺位，首先杀害了汉朝的好多贤臣。然后又焚烧洛阳宗庙宫室，逼迫朝廷西迁旧都长安，挟持幼主以扩张自己的势力。国内诸侯联盟发动正义之师，希望共同起兵讨伐董卓。董卓部下李傕、郭汜出兵函谷关东下平原，他们来势凶猛盔甲在阳光下闪着金光。平原地区的人软弱不强，抵抗不了来犯的北方胡羌。胡羌乱兵践踏了野外的庄稼，围攻了城池，乱兵所到之处残害的百姓家破人亡。他们疯狂砍杀不留一人，死人的骸骨相抵交叉。马边悬挂着男人的头颅，马后捆绑着抢来的妇女。在漫长的路上不停地驱马西进直入函谷关，西进的道路险峻遥远，所以行进十分艰难。被虏掠的人回望来路两眼墨黑迷茫不清，肝脾早已伤透如同烂泥。被掳掠者数以万计，胡羌兵不允许她们集中住在一起。如有亲人们偶然相遇，想说句话却又不敢吭气。只要使他们有一点的不如意，马上就说“杀死俘虏不要客气，正当刀刃有空闲，我辈本来就不想让你们活下去。”这时候难道还会有谁把性命顾惜，最不能忍受的是他们辱骂的恶语。有时他们顺手举起棍棒毒打，连骂带打交并齐下。白天嚎哭着被迫走路，夜里无奈地悲哀坐泣。想死死不成，想活却没有一点希望。老天啊！我们有什么罪过？让我们遭此恶祸！\n　　边地荒蛮和中原不一样，人性粗俗不讲道德礼仪。住的地方长时间盖满霜雪，北风不分春夏呼呼刮起。每当北风翩翩卷起我的衣裳，萧萧震入我的耳朵。就会激起我对父母的思念，这样的哀怨和叹息长此以往不能止息。每当有客人从外地到来，听到后我很是欣慰，急忙忙迎上前打听家乡的消息，却被告知说不是乡人邻里。想不到徼幸能满足平时的心愿，很庆幸亲人能来把自己接回家去。难得自己有幸可以解脱回去，可面对的是抛弃儿子的诀别。天性中母子心连着心，心想着分别后再也没有见面的机遇，从今后不管是活着还是死亡，我们母子将永远的天各一方，我怎么能忍心与儿子辞别。儿子跑上前来抱住了我的脖子，问：“母亲啊，你要到哪里去？有人告诉我母亲将要离去，难道说走后还能够再回来相聚！阿母你一贯的善良仁慈，今天你为什么变得这么无情？我还没有长大成人，为什么你就不能想想我的心情！”见儿子这样的苦苦哀求，我的五脏崩裂一样的沉痛，恍恍惚惚如痴如狂。哭泣着用手抚摩着我的儿子，当要出发时我多次返回去犹豫不决。还有同时掳掠来得同伴们赶来相送与我告别，她们羡慕并痛惜只有我一个人能够回去，哀叫声哭喊声伤痛欲绝。马儿为此悲哀的立在那里不走，车儿为此悲哀的轮子不转。围观的人都在跟着抽搐，过路的人也为此感动低泣。\n　　走啊走啊割断了母子依依不舍的情感，疾速的行走一天比一天遥远。漫长的道路阻隔啊，什么时候我们母子再能交相见面？ 想想从我腹中生出的儿子啊，我心中撕裂一样的疼痛。到家后发现家人早已死绝，甚至没剩下一个姑表亲戚。城里城外一派荒芜变成了山林，庭院和屋檐下长满了艾草和荆棘。眼前的白骨分不清他们是谁，横竖交错没有覆盖掩埋。出門听不到人的声音，只有豺狼呜嚎哭叫。孤零零对着自己的影子，不停的哭喊声撕肝裂肺。爬到高处向远方望去，突然觉得魂魄出窍飞逝离去。奄奄一息好像是寿命将尽，旁人们相继安抚宽慰。挣扎着睁开眼睛又勉强活了下去，虽然没死可又有什么希冀？把命运寄托于再嫁的丈夫董祀，尽心竭力自我勉励努力生活下去。自从流离后成为鄙贱之人，常常害怕丈夫废婚抛弃。想人生能有多少时间，怀着忧伤一年又一年。', poem_notes = '天常：天之常道。“乱天常”，犹言悖天理。\n篡弑：言杀君夺位。董卓于公元189年以并州牧应袁绍召入都，废汉少帝(刘辩)为弘农王，次年杀弘农王。\n诸贤良：指被董卓杀害的丁原、周珌、任琼等。\n旧邦：指长安。公元190年董卓焚烧洛阳，强迫君臣百姓西迁长安。\n兴义师：指起兵讨董卓。初平元年(190年)关东州郡皆起兵讨董，以袁绍为盟主。\n祥：善。“不祥”，指董卓。\n卓众：指董卓部下李榷、郭汜等所带的军队。初平三年(192年)李、郭等出兵关东，大掠陈留、颍川诸县。蔡琰于此时被掳。\n胡羌：指董卓军中的羌胡。董卓所部本多羌、氐族人(见《后汉书·董卓传》)。李榷军中杂有羌胡(见《后汉纪·献帝纪》记载)。\n截：斩断。\n孑：独。这句是说杀得不剩一个。\n相撑拒：互相支拄。这句是说尸体众多堆积杂乱。\n西入关：指入函谷关。卓众本从关内东下，大掠后还入关。\n迥：遥远。\n邈冥冥：渺远迷茫貌。\n弊：即“毙”，詈骂之词。“弊降虏”，犹言“死囚”。\n亭：古通“停”。“停刃”犹言加刃。\n我曹：犹我辈，兵士自称。以上四句是说兵士对于被虏者不满意就说：“杀了你这死囚，让你吃刀子，我们不养活你了。”\n毒：恨。\n参：兼。这句是说毒恨和痛苦交并。\n彼苍者：指天。这句是呼天而问，问这些被难者犯了什么罪。\n边荒：边远之地，指南匈奴，其地在河东平阳(今山西省临汾附近)。蔡琰如何入南匈奴人之手，此诗略而不叙，史传也不曾明载。《后汉书》本传只言其时在兴平二年(195年)。是年十一月李榷、郭汜等军为南匈奴左贤王所破，疑蔡琰就在这次战争中由李、郭军转入南匈奴军。\n少义理：言其地风俗野蛮。这句隐括自己被蹂躏被侮辱的种种遭遇。\n邂逅：不期而遇。\n徼：侥幸。这句是说平时所觊望的事情意外地实现了。\n骨肉：喻至亲。作者苦念故乡，见使者来迎，如见亲人，所以称之为骨肉。或谓曹操遣使赎蔡琰或许假托其亲属的名义，所以诗中说“骨肉来迎”。\n天属：天然的亲属，如父母、于女、兄弟、姐妹。\n缀：联系。\n五内：五脏。\n恍惚：精神迷糊。\n生狂痴：发狂。\n遄征：疾行。\n日遐迈：一天一天地走远了。\n中外：犹中表，“中”指舅父的子女，为内兄弟，“外”指姑母的子女，为外兄弟。以上二句是说到家后才知道家属已死尽，又无中表近亲。\n茕茕：孤独貌。\n景：同“影”。\n怛咤：惊痛而发声。\n相宽大：劝她宽心。\n息：呼息。这句是说又勉强活下去。\n何聊赖：言无聊赖，就是无依靠，无乐趣。\n新人：指作者重嫁的丈夫董祀。\n勖：勉励。\n捐废：弃置不顾。以上二句是说自己经过一番流离，成为被人轻视的女人，常常怕被新人抛弃。', poem_tags = '自传,骚体,苦难,生活,叙事,长诗' WHERE poem_title = '悲愤诗' AND poem_author = '蔡琰';
UPDATE edu_poem SET poem_tags = '清明节,踏青' WHERE poem_title = '清明日' AND poem_author = '温庭筠';
UPDATE edu_poem SET poem_translation = '幽幽沼泽仙鹤鸣，声传四野真亮清。深深渊潭游鱼潜，有时浮到渚边停。在那园中真快乐，檀树高高有浓荫，下面灌木叶凋零。他方山上有佳石，可以用来磨玉英。\n幽幽沼泽仙鹤唳，鸣声响亮上云天。浅浅渚滩游鱼浮，有时潜入渊潭嬉。在那园中真快乐，檀树高高枝叶密，下面楮树矮又细。他方山上有佳石，可以用来琢玉器。', poem_notes = '九皋：皋，沼泽地。九：虚数，言沼泽之多。\n渊：深水，潭。\n渚：水中小洲，此处当指水滩。\n爰（yuán）：于是。檀（tán）：古书中称檀的木很多，时无定指。常指豆科的黄檀，紫檀。\n萚（tuò）：酸枣一类的灌木。一说“萚”乃枯落的枝叶。\n“它山”二句：利用其它山上的石头可以错琢器物。错：砺石，可以打磨玉器。\n榖（gǔ）：树木名，即楮树，其树皮可作造纸原料。\n攻玉：谓将玉石琢磨成器。朱熹《诗集传》：“两玉相磨不可以成器，以石磨之，然后玉之为器，得以成焉。”', poem_appreciation = '此诗共二章，每章九句。前后两章共用了四个比喻，语言也相似，只是押韵不同。关于诗的主题，有几种不同的说法。《毛诗序》认为是“诲（周）宣王也”，郑笺补充说：“诲，教也，教宣王求贤人之未仕者。”王先谦《诗三家义集疏》举例证明鲁诗、齐诗、韩诗都与毛诗观点一致。到了宋代朱熹《诗集传》则说：“此诗之作，不可知其所由，然必陈善纳诲之辞也。”认为这是一篇意在劝人为善的作品。今人程俊英在《诗经译注》祖毛、郑旧说而加以发展，说：“这是一首通篇用借喻的手法，抒发招致人才为国所用的主张的诗，亦可称为‘招隐诗’。”这种说法较易为今人所理解。\n\n　　先谈朱熹的说法。他分析第一章说：“盖鹤鸣于九皋，而声闻于野，言诚之不可揜（掩）也；鱼潜在渊，而或在于渚，言理之无定在也；园有树檀，而其下维萚，言爱当知其恶也；他山之石，而可以为错，言憎当知其善也。由是四者引而伸之，触类而长之，天下之理，其庶几乎？”他将诗中四个比喻，概括为四种思想：即诚、理、爱、憎。并认为从这四者引申出去，可以作为“天下之理”——即普遍真理。他的说法看起来很辩证，都是用发展的变化的观点分析问题，而且兼顾一个问题的两个方面；然而他却是用程朱理学来说诗，这一点从他对第二章的解释中看得更加清楚。\n\n　　《诗集传》释第二章结句引程子曰：“玉之温润，天下之至美也。石之粗厉，天下之至恶也。然两玉相磨，不可以成器，以石磨之，然后玉之为器，得以成焉。犹君子之与小人处也，横逆侵加，然后修省畏避，动心忍性，增益预防，而义理生焉，道理成焉。”程子说诗与朱子说诗，如出一辙，皆为引申之词。“他山之石，可以攻玉”，就字面而言，就是另一座山上的石头，可以用来磨制玉器，今人也常常引以为喻。然而是否为诗的本义呢，似乎很难说。\n\n　　再谈今人程俊英关于此诗的解释。程先生在《诗经译注》中说：“诗中以鹤比隐居的贤人。”“诗人以鱼在渊在渚，比贤人隐居或出仕。”“园，花园。隐喻国家。”“树檀，檀树，比贤人。”“萚，枯落的枝叶，比小人。”“它山之石，指别国的贤人。”“毛传：‘榖，恶木也。’喻小人。”她从“招隐诗”这一主题出发，将诗中所有比喻都一一与人事挂钩，虽不无牵强附会，倒也自成一说。\n\n　　其实，就诗论诗，不妨认为这是一首即景抒情小诗。在广袤的荒野里，诗人听到鹤鸣之声，震动四野，高入云霄；然后看到游鱼一会儿潜入深渊，一会儿又跃上滩头。再向前看，只见一座园林，长着高大的檀树，檀树之下，堆着一层枯枝败叶。园林近旁，又有一座怪石嶙峋的山峰，诗人因而想到这山上的石头，可以取作磨砺玉器的工具。诗中从听觉写到视觉，写到心中所感所思，一条意脉贯串全篇，结构十分完整，从而形成一幅远古诗人漫游荒野的图画。这幅图画中有色有声，有情有景，因而也充满了诗意，读之不免令人产生思古之幽情。如此读诗，读者便会受到诗的艺术感染，产生无穷兴趣。若刻意求深，强作解人，未免有高深莫测之感。', poem_tags = '诗经,写鸟,抒情' WHERE poem_title = '小雅·鹤鸣' AND poem_author = '佚名';
UPDATE edu_poem SET poem_tags = '小学文言文,寓言,故事,哲理' WHERE poem_title = '外科医生' AND poem_author = '江盈科';
UPDATE edu_poem SET poem_tags = '抒情,羁旅,愁苦' WHERE poem_title = '卜算子·十载仰高明' AND poem_author = '赵长卿';
UPDATE edu_poem SET poem_translation = '弯弯的月儿爬上了凉州城头，城头的月儿升空照着全凉州。\n凉州方圆七里住着十万人家，这里的胡人半数懂得弹琵琶。\n动人的琵琶曲令人肝肠欲断，只觉得风声萧萧兮长夜漫漫。\n河西幕府里我有很多老朋友，老朋友分别以来已有三五春。\n如今在花门楼前又见到秋草，哪能互相看着在贫贱中变老？\n人生一世能有几回开怀大笑，今日相逢人人必须痛饮醉倒。', poem_notes = '凉州：唐朝河西节度府所在地，治所在今甘肃武威。馆：客舍。判官：唐代节度使、观察使下的属官。\n城墙上。唐王昌龄《出塞》诗之二：“城头铁鼓声犹振，匣里金刀血未干。”\n凉州：一作“梁州”。\n里：一作“城”。\n胡人：中国古代对北方边地及西域各民族人民的称呼。半解：半数人懂得。解，懂得，明白。\n萧萧：象声词。此处形容风声。漫漫：形容黑夜漫长。\n河西：汉唐 时指今甘肃、青海两省黄河以西，即河西走廊与湟水流域。此处指河西节度使，治所在凉州。故人：旧交；老友。\n花门楼：这里即指凉州馆舍的楼房。贫贱：贫苦微贱。唐崔颢《长安道》诗：“莫言贫贱即可欺，人生富贵自有时。”\n斗酒相逢：即相逢斗酒。斗酒，比酒量。', poem_appreciation = '这首诗中所说的凉州，治所在今甘肃武威，唐河西节度府设于此地。馆，客舍。从“河西幕府多故人，故人别来三五春”等诗句看，岑参此时在凉州作客。凉州河西节度使幕府中，诗人有许多老朋友，常欢聚夜饮。\n\n　　“弯弯月出挂城头，城头月出照凉州。”首先出现的是城头弯弯的明月。然后随着明月升高，银光铺泻，出现了月光照耀下的凉州城。首句“月出”，指月亮从地平线升起，次句“月出”，指月亮在城头上继续升高。\n\n　　“凉州七里十万家，胡人半解弹琵琶。”这是随着月光的照耀，更清晰地呈现了凉州的全貌。“凉州”，有的本子作“梁州”（今陕西汉中市）。这是因为后人看到“七里十万家”，认为甘肃凉州没有这种规模而妄改的。其实，唐前期的凉州是与扬州、益州等城市并列的第一流大都市。“七里十万家”，正是大笔淋漓地勾画出这座西北重镇的气派和风光。而下一句，就更见出是甘肃凉州了。凉州在边塞，居民中少数民族很多。他们能歌善舞，多半会弹奏琵琶。不用说，在月光下的凉州城，荡漾着一片琵琶声。这里写出了凉州城的歌舞繁华、和平安定，同时带着浓郁的边地情调。\n\n　　“琵琶一曲肠堪断，风萧萧兮夜漫漫。”仍然是写琵琶声，但已慢慢向夜宴过渡了。这“一曲琵琶”已不是“胡人半解弹琵琶”的满城琵琶声，乃是指宴会上的演奏。“肠堪断”形容琵琶动人。“风萧萧兮夜漫漫”，是空旷而又多风的西北地区夜晚所给人的感受。这种感受由于“琵琶一曲”的演奏更加增强了。\n\n　　以上六句主要写环境背景。诗人吸取了民歌的艺术因素，运用顶针句法，句句用韵，两句一转，构成轻快的、咏唱的情调，写出凉州的宏大、繁荣和地方色彩。最后一句“风萧萧兮夜漫漫”，用了一个“兮”字和迭字“萧萧”、“漫漫”，使节奏舒缓了下来。后面六句即正面展开对宴会的描写，不再句句用韵，也不再连续使用顶针句法。\n\n　　“河西幕中多故人，故人别来三五春。”两句重复“故人”二字，见出情谊深厚。因为“多故人”，与各人离别的时间自然不尽相同，所以说“三五春”，下语是经过斟酌的。\n\n　　“花门楼前见秋草，岂能贫贱相看老。”“花门楼”在这里即指凉州馆舍的楼房。二句接“故人别来三五春”，意思是说：时光迅速，又到了秋天草黄的季节了。岁月催人，哪能互相看着在贫贱中老下去呢？言下之意是要赶快建立功业。\n\n　　“一生大笑能几回，斗酒相逢须醉倒。”一个“笑”字，写出岑参和他朋友的本色。宴会中不时地爆发出大笑声，这样的欢会，这样的大笑，一生中也难得有几回，老朋友们端着酒杯相遇在一起，能不为之醉倒。\n\n　　这首诗把边塞生活情调和强烈的时代气息结合了起来。全诗由月照凉州开始，在着重表现边城风光的同时，那种月亮照耀着七里十万家和城中荡漾的一片琵琶声，也鲜明地透露了当时凉州的阔大的格局、和平安定的气氛。如果拿它和宋代范仲淹的《渔家傲·塞下秋来风景异》相比，即可见同样是写边城，写秋天的季节，写少数民族的音乐，但那种“长烟落日孤城闭”、“羌管悠悠霜满地”的描写，所表现的时代气氛就完全不同了。\n\n　　至于诗所写的夜宴，更是兴会淋漓，豪气纵横，不是盛唐的人不能如此。“花门楼前见秋草，岂能贫贱相看老。”不是有感于时光流逝，叹老嗟卑，而是有着能够掌握自己命运的豪迈感，表现出奋发的人生态度。“一生大笑能几回”的笑，更是爽朗健康的笑。它来源于对前途、对生活的信心。同样，末句“须醉倒”，也不是借酒浇愁，而是以酒助兴，是豪迈乐观的醉。以酒助兴，兴浓欢悦，笑声爽朗，豪迈乐观，读者从人物的神态中，能感受到盛唐的时代脉搏。', poem_tags = '友情,豪迈,地点,月亮,宴会' WHERE poem_title = '凉州馆中与诸判官夜集' AND poem_author = '岑参';
UPDATE edu_poem SET poem_tags = '写景,谴责,边将' WHERE poem_title = '凉州词三首·其三' AND poem_author = '张籍';
UPDATE edu_poem SET poem_tags = '春节,勉励,惜时' WHERE poem_title = '守岁' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '云朵的影子浸在江水里，鸿雁正打算向南飞。我带着酒壶，邀集客人，找一个苍翠清寂、烟雾氤氲的地方去饮酒。人世间难得一笑，还好有紫萸黄菊可以摘下来插在头上，自娱自乐一番。风景还是往年的风景，而人早已不是往昔的人了。\n为了庆贺重阳节，应该喝得酩酊大醉，请不要再推辞不喝了。人活着就像寄生在这个世界上，为什么非要奔波劳碌，到最后还怨恨人生苦短呢古往今来，无穷无尽。人间多少春花秋月，终难逃危机。你去问问齐景公，何必为人生短暂而泪沾衣襟。', poem_notes = '隐括：指对原有作品的内容、语言加以剪裁、修改而成新篇。\n结客：和客人们一起登山。\n尘世：即人生。\n紫萸：即茱萸，一种有浓烈香味的植物。\n酩酊：大醉貌。', poem_appreciation = '本词题为《隐括杜牧之齐山诗》，“隐括”，也就是对原作的内容、句子适当剪裁、增删，修改成新的作品，用今天的话说，也就是改写。《文心雕龙·镕裁》：“蹊要所司，职在镕裁，隐括情理，矫揉文采也。”由此可见，这种写作方法，很早就有了。\n\n　　朱熹“隐括”杜牧的《九日齐山登高》，也就是借这首诗来寄兴抒情托志。杜牧的诗是这样的：“江涵秋影雁初飞，与客携壶上翠微。尘世难逢开口笑，菊花须插满头归。但将酩酊酬佳节，不用登临恨落晖。古往今来只如此，牛山何必独沾衣！”对这首诗，历来就有很高的评价。杜牧出身于显赫的世代公卿之家，胸怀致仕用世的大志；朱熹是著名思想家，又是诗人。尽管他们生活的时间前后相隔三百多年，但都是主张积极入世的，因为思想上有共通之处，朱熹仰慕小杜的诗，近而“隐括”成词，也是可以理解的。', poem_tags = '重阳节,劝勉,人生,哲理' WHERE poem_title = '水调歌头·隐括杜牧之齐山诗' AND poem_author = '朱熹';
UPDATE edu_poem SET poem_translation = '微微的秋风正在细细吹拂，梧桐树叶正在飘飘坠下。初尝香醇绿酒便让人陶醉，在小窗之前一枕酣眠浓睡。紫薇和朱槿在秋寒里凋残，只有夕阳映照着楼阁栏杆。双燕到了将要南归的季节，镶银的屏风昨夜已微寒。', poem_notes = '金风：秋风。\n紫薇朱槿：花名。紫薇：落叶小乔木，花红紫或白，夏日开，秋天凋，故又名“百日红”。朱槿：红色木槿，落叶小灌木，夏秋之交开花，朝开暮落。又名扶桑。\n银屏：银饰屏风。', poem_appreciation = '这首词的特点是风调闲雅，气象华贵，二者本有些矛盾，但词人却把它统一起来，形成表现自己个性的特殊风格。晏殊以相位之尊，间为小歌词，得花间遗韵。刘攽《中山诗话》说：“晏元献尤喜冯延巳歌词，其所自作，亦不减延巳乐府。”也就是说他的词风酷似冯延巳。但从这首词来看，它的闲雅风调虽似冯词，而其华贵气象倒有点像温庭筠的作品。不过温词的华贵，大都表现词藻上的镂金错采，故王国维以“画屏金鹧鸪”状其词风。晏词的华贵却不专主形貌，而于精神。“每吟咏富贵，不言金玉锦绣，而惟说其气象，若‘楼台侧畔杨花过，帘幕中间燕子飞’，‘梨花院落溶溶月，柳絮池塘淡淡风’之类是也。”（见吴处厚《青箱杂记》）这首词中所写的风，正与上举两例相似。它所塑造的形象，借用晁补之评论其子晏几道词的说话，一看就知道“不是三家村中人”，而是一个雍容闲雅的士大夫。\n\n　　词的上阕是写酒醉以后的浓睡。起首二句在写景中点明时间，渲染环境。金风，即秋风。《文选》张协《杂诗》“金风扇素节”，李善注曰：“西方为秋而主金，故秋风日金风也。”此时庭院内是秋风落叶，画堂中的词人因饮了几杯绿酒，一会儿便醉眠了。用笔轻灵，色调淡雅，语气仿佛在与一位友人娓娓而谈。其巾“细细”、“叶叶”两组叠字，首尾相接，音律谐婉。以“细细”状金风，就没有秋风惯有的那种萧飒之感，而显得平静、悠闲。以“叶叶”这两个名词相连用，就在读者面前展开一片片叶子飘落的景象，显得很有次序，很有节奏。向来写梧桐经秋而落都是较为凄厉的，如白居易《长恨歌》：“秋雨梧桐叶落时。”温庭筠《更漏子》：“梧桐树，三更雨，不道离情正苦。一叶叶，一声声，空阶滴到明。”经过一代又一代词人的染笔，以至于使人一听到秋风吹拂梧桐，就产生凄凉况味。而像晏殊写得如此平淡幽细的，却极为少见。下面“绿酒”一句，因为用了“初”、“易”二字，就觉得他的酒量不大，浅尝辄醉，虽是淡淡的一笔，但却是陪笔；至“一枕小窗浓睡”，才写出此阕的主旨。小饮何以“易醉”？浅醉何得“浓睡”？原来词人有一点闲愁。然而以酒浇愁愁更愁，愁深故易醉，醉易故睡浓。此意于下阕尤能见出。\n\n　　如果说上阕是从昨晚的醉眠写起，那么下阕则是写次日薄暮酒醒时的感觉。词人一醉就睡了整整一个昼夜，睡极浓矣。浓睡中无愁无忧，酒醒后情绪如何，他没有言明，只是通过他眼巾所见的景象，折射出心情之悠闲，神态之慵怠；不过在结句中仍然透露出一丝丝哀愁。过片中的紫薇，植物名，夏季开花；朱槿，夏秋间吐艳。上阕说金风吹得梧桐叶坠，分明是秋季了，所以词人从小窗望出去，此刻这两种花都已凋残。值得注意的是，前阕的梧桐叶坠，为耳中所闻；后阕的两种花残，乃眼中所见。词人正是通过对周围事物的细微体察，来表现此际的情怀。“斜阳却照阑干”，紧承前句，描写静景。晏殊在《踏莎行》词中云：“一场愁梦酒醒时，斜阳却照深深院。”情境皆相似。两处都用了“却”字。却者，正也。此处是说抬头望去，一抹斜阳正照着阑干，颇有陶渊明“悠然见南山”的神韵，然而词人所见者不是南山，而是残花、斜阳，其中似寓有无可奈何的心境。\n\n　　日暮了，斜阳正照着阑干，也正是“双燕欲归时节”。此意平平说来，似不相干语，没要紧语。可是词不比诗，它往往用这样的语言，来调和气氛，缓冲节奏，烘托情感。吴衡照《莲子居词话》云：“言情之词，必借景色映托，乃具深婉流美之感。”“燕子欲归”，乃系景语，它对下旬“银屏昨夜微寒”，正好起了一个铺垫和烘托作用。双双紫燕即将归巢了，这个景象便兴起词人独居无愣的感觉。于是他想到昨夜醉后原是一个人独宿。一种凄凉意绪，落寞情怀，不禁油然而生。但他不用“枕寒”、“衾寒”那些用熟了的字面，偏偏说屏风有些寒冷。寓情于景，含蓄蕴藉，令人低徊不尽。\n\n　　此词之所以受到评论家们的一致称赏，主要在于它呈现了一种与词人富贵显达的身世相谐调的圆融平静、安雅舒徐的风格。这种风格，是大晏深厚的文化教养、敏锐细腻的诗人气质与其平稳崇高的台阁地位相浑融的产物。在这首词里，丝毫找不到自宋玉以来诗人们一贯共有的衰飒伤感的悲秋情绪，有的只是在富贵闲适生活中对于节序更替的一种细致人微的体味与感触。抒情主人公是在安雅闲适的相府庭园中从容不迫地咀嚼品尝着暑去秋来那一时间自然界变化给人之身心的牵动之感。这当中，也含有因节序更替、岁月流逝而引发的一丝闲愁，但这闲愁是淡淡的、细柔的，甚至是飘忽幽微若有若无的。作者通过对外物的描写，将他在这环境中特有的心理感触舒徐平缓地宣泄出来，使整个意境十分轻婉动人。这首词也是《珠玉词》中的名篇。它用精细的笔触和闲雅的情调，写出家作者这样的富贵高雅的文人在秋天刚来时的一种舒适而又略带无聊的感触。', poem_tags = '写风,婉约' WHERE poem_title = '清平乐·金风细细' AND poem_author = '晏殊';
UPDATE edu_poem SET poem_tags = '辞赋精选,地名,言志,讽刺' WHERE poem_title = '三都赋' AND poem_author = '左思';
UPDATE edu_poem SET poem_translation = '本该是阳光明媚的春日却是连日阴雨，乌云笼罩大地连日的大雨将堤坝冲毁。\n昨天感觉天气良好就启程上路，不成想让这大雨阻了前路停滞不前。', poem_notes = '花时：百花盛开的时节。常指春日。\n红锦：红色名贵的绢织品。', poem_tags = '春天,写雨' WHERE poem_title = '春雨' AND poem_author = '徐凝';
UPDATE edu_poem SET poem_translation = '秋霜落在荆门，树叶零落，由于山空使得江面也很开阔，秋风也为我送行，使我的旅途平安。\n这次远离家乡游历，不是为了口舌之贪，而是为了游览名山大川，因此才想去剡中这个地方。', poem_notes = '荆门：山名，位于今湖北省宜都县西北的长江南岸，与北岸虎牙山隔江对峙，地势险要，自古即有楚蜀咽喉之称。\n空：指树枝叶落已尽。\n布帆无恙：运用《晋书·顾恺之传》的典故：顾恺之从他上司荆州刺史殷仲堪那里借到布帆，驶船回家，行至破冢，遭大风，他写信给殷仲堪，说：“行人安稳，布帆无恙。”此处表示旅途平安。\n鲈鱼鲙：运用《世说新语·识鉴》的典故：西晋吴人张翰在洛阳做官时，见秋风起，想到家乡菰菜、鲈鱼鲙的美味，遂辞官回乡。\n剡中：指今浙江省嵊州市一带。《广博物志》：“剡中多名山，可以避灾。”', poem_appreciation = '荆门山战国时为楚国的西方门户，乘船东下过荆门，就意味着告别了巴山蜀水。这首诗写于诗人第一次出蜀远游时。对锦绣前程的憧憬，对新奇而美好的世界的幻想，使他战胜了对峨眉山月的依恋，去热烈地追求理想中的未来。诗中洋溢着积极而浪漫的热情。\n\n　　第一句是写景，同时点出题中的“秋”和“荆门”。荆门山原是林木森森，绿叶满山，然而诗人到来时，却是秋来霜下，木叶零落，眼前一空。由于山空，江面也显得更为开阔。这个“空”字非常形象地描绘出山明水净、天地清肃的景象，寥廓高朗，而无萧瑟衰飒之感。\n\n　　第二句“布帆无恙挂秋风”，承上句“江”字，并暗点题中“下”字。东晋大画家顾恺之为荆州刺史殷仲堪幕府的参军，曾告假乘舟东下，仲堪特地把布帆借给他，途中遇大风，顾恺之写信给殷仲堪说：“行人安稳，布帆无恙。”这里借用了“布帆无恙”这一典故，不仅说明诗人旅途平安，更有一帆风顺、天助人愿的意味。这种秋风万里送行舟的景象，生动地写出了诗人无比乐观欣慰的心情。\n\n　　前人有诗：“张翰江东去，正值秋风时。”这首诗的第三句，就是由第二句中的“秋风”连及而来的。据说西晋时吴人张翰在洛阳做官，见秋风起而想到故乡的莼羹、鲈鱼鲙，说：“人生贵得适志耳，何能羁宦数千里，以要名爵乎！”于是回到了故乡。李白此行正值秋天，船又是向着长江下游驶行，这便使他联想到张翰的故事，不过他声明“此行不为鲈鱼鲙”，此行目的与张翰不同，他自己是远离家乡。这样反跌一笔，不但使诗变得起伏跌宕，而且急呼下文“自爱名山入剡中”。剡中，今浙江嵊州，境内多名山佳水。句中“自”字，与上一句中“不为”相呼应，两句紧相连贯，增强了感情色彩。\n\n　　古人曾说过：“诗人之言，不足为实也。”那意思大概就是说诗具有凝炼、概括、夸张、含蓄等特色，诗中语言的含意，往往不能就字面讲“实”、讲死，所以说写诗的人也应该“不以辞害意”。这首诗的三四两句，如果只理解为诗人在表白“此行”的目的，不是为了吴地的美味佳肴，而是要去欣赏剡中的名山，那就未免太表面了，太“实”了。李白“入剡中”，是若干年以后的事。读者要知道它的含意到底是什么，还得回到诗的第三句。从张翰所说的话来看，张翰是把“名爵”与“鲈鱼鲙”对立起来，放弃前一个，而选后一个；而李白对后者的态度很明朗——“此行不为鲈鱼鲙”。至于对前者，诗人没有明说。可是，“秋下荆门”以后的所言，所行，就把这个问题说得很清楚了。第一，“此行”并没有“入剡中”，而是周游在江汉一带，寻找机会，以求仕进；第二，他还明白地声称：“大丈夫必有四方之志，乃仗剑去国，辞亲远游。”（《上安州裴长史书》）他还希求“奋其智能，愿为辅弼，使寰区大定，海县清一”（《代寿山答孟少府移文书》）。这种建功立业的宏愿，积极用世的精神，和张翰的态度恰恰相反。所以诗人此时对“名爵”和“鲈鱼鲙”都是一反张翰的意思，只不过在诗中说一半留一半罢了。当然，这也是“适志”，是辞亲远游、建功立业的“志”。诗的第四句说，饱览绍兴的名山佳水，也是诗人所向往的。这种兴趣，早在他出蜀之前就已经表露出来了，不过联系上一句来看，就不能仅仅局限于此了。自视不凡的李白，是不想通过当时一般文人所走的科举道路去获取功名的，而是要选择另一条富有浪漫色彩的途径，那便是游历，任侠，隐居名山，求仙学道，结交名流，树立声誉，以期达到目标。所以这里的“自爱名山入剡中”，无非是在标榜诗人自己那种高人雅士的格调，无非是那种不同凡俗的生活情趣的一种艺术概括。这种乐观浪漫、豪爽开朗、昂扬奋发的精神，生动地表现了诗人的个性，以及盛唐时代的精神风貌。\n\n　　这首诗在艺术表现上也颇有特色。全诗虽四句，但写景、叙事、议论各具形象，集中地抒发了诗人年轻时“仗剑去国”的热情，笔势变幻灵活，而又自然浑成。四句诗中连用了两个典故，或暗用而不露痕迹，或反用而有新意，使读者读来没有凝滞堆砌之感，达到了推陈出新、语如己出、活泼自然的境界。', poem_tags = '秋游,抒情' WHERE poem_title = '秋下荆门' AND poem_author = '李白';
UPDATE edu_poem SET poem_tags = '春天,写景,故事,抒情,愁绪' WHERE poem_title = '春江花月夜二首' AND poem_author = '张子容';
UPDATE edu_poem SET poem_translation = '和风煦煦自南方，吹在枣树嫩芽上。枣树芽心嫩又壮，母亲养儿辛苦忙。\n和风煦煦自南方，枣树成柴风吹长。母亲明理又善良，儿子不好不怨娘。\n寒泉之水透骨凉，源头就在浚邑旁。母亲养育儿七个，儿子长成累坏娘。\n黄雀婉转在鸣唱，悦耳动听真嘹亮。母亲养育儿七个，难慰母亲不应当。', poem_notes = '邶（bèi）：中国周代诸侯国名，地在今河南省汤阴县东南。\n凯风：和风。一说南风，夏天的风。这里喻母爱。马瑞辰《毛诗传笺通释》“凯之义本为大，故《广雅》云：‘凯，大也。’秋为敛而主愁，夏为大而主乐，大与乐义正相因。”\n棘心：酸枣树初发的嫩芽。这里喻子女。棘，落叶灌木，即酸枣。枝上多刺，开黄绿色小花，实小，味酸。心，指纤小尖刺。\n夭夭：树木嫩壮貌。\n劬（qú）劳：操劳。劬，辛苦。\n棘薪：长到可以当柴烧的酸枣树。这里比喻子女已长大。\n圣善：明理而有美德。\n令：善，好。\n爰（yuán）：何处。一说发语词，无义。寒泉：卫地水名，冬夏常冷。\n浚（xùn）：卫国地名。\n睍（xiàn）睆（huǎn）：犹“间关”，鸟儿宛转的鸣叫声。一说美丽，好看。黄鸟：黄雀。\n载：传载，载送。', poem_appreciation = '此诗以凯风吹彼棘心开篇，把母亲的抚育比作温暖的南风，把自己弟兄们小时候比作酸枣树的嫩芽，“丛生的”小嫩芽之所以能够健康成长，全是母亲大人辛勤哺育的功劳。七个儿子一个一个长大成人（材）了，母亲的大恩大德，堪称圣善，儿子却是不孝儿，这就是自责自称，总嫌自己做得还远远不够，与母亲的养育之恩相比，还差得很远很远，无以为报。\n\n　　从第三章开始，作者又以寒泉比母，以黄鸟比子，作进一步的自我批评。寒泉也成为母爱的代称。寒泉在地下流淌，滋养浚人。母亲生养弟兄七人，至今还如此劳苦，让作儿子的如何心安？黄鸟鸣叫得清丽婉转，尚且如此悦耳动听，为什么七个儿子却不能抚慰母亲那颗饱受孤苦的心呢？\n\n　　诗的前二章的前二句都以凯风吹棘心、棘薪，比喻母养七子。凯风是夏天长养万物的风，用来比喻母亲。棘心，酸枣树初发芽时心赤，喻儿子初生。棘薪，酸枣树长到可以当柴烧，比喻儿子已成长。后两句一方面极言母亲抚养儿子的辛劳，另一方面极言兄弟不成材，反躬以自责。诗以平直的语言传达出孝子婉曲的心意。\n\n　　诗的后二章寒泉、黄鸟作比兴，寒泉在浚邑，水冬夏常冷，宜于夏时，人饮而甘之；而黄鸟清和宛转，鸣于夏木，人听而赏之。诗人以此反衬自己兄弟不能安慰母亲的心。\n\n　　诗中各章前二句，凯风、棘树、寒泉、黄鸟等兴象构成有声有色的夏日景色图。后二句反覆叠唱的无不是孝子对母亲的深情。设喻贴切，用字工稳。诗中虽然没有实写母亲如何辛劳，但母亲的形象还是生动地展现出来。', poem_tags = '诗经,赞美,母亲' WHERE poem_title = '国风·邶风·凯风' AND poem_author = '佚名';
UPDATE edu_poem SET poem_tags = '古文观止,议论,寓理' WHERE poem_title = '杂说一·龙说' AND poem_author = '韩愈';
UPDATE edu_poem SET poem_translation = '注释 衢(qú)：四通八达的道路，云衢则为云中之路。', poem_tags = '中秋节,赏月,写诗' WHERE poem_title = '中秋玩月' AND poem_author = '佚名';
UPDATE edu_poem SET poem_tags = '离别,相思,回忆,爱情' WHERE poem_title = '无题·油壁香车不再逢' AND poem_author = '晏殊';
UPDATE edu_poem SET poem_translation = '一簇簇梅花绽放压低枝头，不用翻山越岭到处栽种，随处都可成活。\n只是权贵之家却看不到梅花的坚毅品性，和煦的春风迟迟不肯到来。', poem_notes = '五侯：泛指权贵之家。', poem_tags = '写花,梅花,抒怀' WHERE poem_title = '梅花' AND poem_author = '罗邺';
UPDATE edu_poem SET poem_translation = '译文 碧绿荷塘摇曳的荷花激起的涟漪好像连接着银河（星津指银河），船桨在荷塘滑动发出扎扎的声响，船驶入水草之中。 就像洛神步履轻盈地走在平静的水面上，荡起细细的涟漪（应该出自《洛神赋》“凌波微步 罗袜生尘”），到今天莲花都有洛神的香尘残留。', poem_tags = '咏物,荷花' WHERE poem_title = '莲花' AND poem_author = '温庭筠';
UPDATE edu_poem SET poem_translation = '草堂远离喧闹的成都，庭院开阔宽敞，四周没有村落，放眼一望无边。\n碧澄江水，几乎淹没两岸；葱茏树木，黄昏盛开鲜花。\n细雨蒙蒙，鱼儿欢快地跃出水面；微风习习，燕子倾斜着掠过天空。\n城里拥挤着十万人家，熙熙攘攘；这里却只有两三灯火，清闲自在。\n\n蜀地四川的天气常常在夜里下雨，在水边的栏杆旁已能看到天色转晴。\n花叶被雨水淋得湿润，树林里密密麻麻地布满水洼，我的衣服和枕席也干了。\n我不能承受现在的体弱多病，又哪里还看重功利与浮名。\n慢慢地倒酒来饮，我凭借它来陪伴我的余生。', poem_notes = '水槛（jiàn）：指水亭之槛，可以凭槛眺望，舒畅身心。\n去郭轩楹敞：去郭，远离城郭。轩楹：指草堂的建筑物。轩，长廊；楹（yíng），柱子。敞，开朗。\n无村眺望赊：因附近无村庄遮蔽，故可远望。赊（shē）：长，远。\n澄江平少岸：澄清的江水高与岸平，因而很少能看到江岸。\n城中十万户，此地两三家.：将“城中十万户”与“此地两三家”对照，见得此地非常清幽。城中，指成都。\n蜀天：蜀中雅州，常多阴雨，号曰漏天。\n槛：栏杆。\n祗（zhī）：恭敬。\n尚：崇尚，注重。浮名：虚名。\n涓涓：细水缓流的样子。', poem_appreciation = '第一首诗，首联先写草堂的环境：草堂离城郭很远，庭园开阔宽敞，旁无村落，因而诗人能够极目远眺。中间四句紧接着写眺望到的景色。“澄江平少岸”，诗人凭槛远望，碧澄清澈的江水，浩浩荡荡，似乎和江岸齐平了，这是写远景；“幽树晚多花”则写近景，草堂四周郁郁葱葱的树木，在春日的黄昏里，盛开着姹紫嫣红的花朵，散发出迷人的清香。五、六两句刻画细腻，描写极为生动：“细雨鱼儿出，微风燕子斜。”鱼儿在毛毛细雨中摇曳着身躯，喷吐着水泡儿，欢欣地游到水面来了。燕子轻柔的躯体，在微风的吹拂下，倾斜着掠过水蒙蒙的天空……这是历来为人传诵的名句。诗人遣词用意精微细致，描写十分生动。“出”写出了鱼的欢欣，极其自然；“斜”写出了燕子的轻盈，逼肖生动。诗人细致地描绘了微风细雨中鱼和燕子的动态，其意在托物寄兴。这二句诗流露出作者热爱春天的喜悦心情，是历来为人传诵的名句。叶梦得《石林诗话》云：“诗语忌过巧。然缘情体物，自有天然之妙，如老杜‘细雨鱼儿出，微风燕子斜’，此十字，殆无一字虚设。细雨着水面为沤，鱼常上浮而淰。若大雨，则伏而不出矣。燕体轻弱，风猛则不胜 ，惟微风乃受以为势 ，故又有‘轻燕受风斜’之句。”尾联呼应起首两句。以“城中十万户”与“此地两三家”对比，更显得草堂的闲适幽静。这首诗写傍晚时分所见到的微风细雨中的景象，表现了环境的清幽美好和诗人闲适宁静的心情及其对大自然的热爱。全诗八句都是对仗，而且描写中远近交错，精细自然，“自有天然工巧而不见其刻划之痕。”它句句写景，句句有“遣心”之意。诗中描绘的是草堂环境，然而字里行间含蕴的，却是诗人悠游闲适的心情和对大自然、对春天的热爱。\n\n　　第二首诗，前两联写景，后两联言志。开篇描绘的是四川一带夜里常常多雨的天气：晚上淅淅沥沥地下了一整夜的雨，等第二天出门以后，靠在水边的栏杆上远望，才看到天色已经开始放晴。夜里的降雨和天明后的放晴构成了对比，烘托出晴朗天气的可贵，由此也引出下文。由于雨水的淋洗，四周的花叶变得很湿润，树林里也布满了水洼；淋湿的衣服已经干了，枕席也变得干净。“叶润林塘密”，表现出诗人生活环境的清幽和静谧；“衣干枕席清”，显示出夜雨的绵长细密，也显示出诗人住所的简陋。紧接着，诗人描写了自己年老多病的现状，表达了他厌倦浮名的心情。“不堪”说明诗人老迈之甚，“何得”说明他对浮名厌倦之深，语气强烈，感情激荡。最后两句写他慢慢倒酒而饮，借此来消遣余生，表达了诗人对自己身世遭遇的感慨和无奈之情。这首诗与前诗相比基调就沉重了些，描绘了一番蜀地的景象。在咏物的同时抒发了诗人对现实的种种不满和郁郁不得志，而又感慨自己老迈无力去改变现世，无奈饮酒来得以消遣。', poem_tags = '春天,写景,写雨,感慨' WHERE poem_title = '水槛遣心二首' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '秋色渐渐浓郁，花儿都在睡觉，秋燥如火。\n秋霜早早地从北方来到这里，北方的云也把秋色带过了汾河。\n夜夜秋梦都缠绕着边区太原上空的月亮，而心却随着月光回到了故乡的绮楼上，她的身傍。\n思念家乡的心就象这绵绵不断的汾河水，无时无刻不在悠悠地流向家乡。', poem_notes = '太原：即并州，唐时隶河东道。\n岁落：光阴逝去。众芳歇：花草已凋零。\n大火：星名，二十八宿之一，即心宿。《诗经·七月》“七月流火”即指此星。这颗星每年夏历五月的黄昏出现于正南方，位置最高，六七月开始向下行，故称“流火”。时当大火流，即时当夏历七月之后。张衡《定情歌》：“大火流兮草虫鸣。”《图书编》：“大火，心星 也。以六月之昏，加于地之南，至七月之昏，则下而西流矣。”\n塞：关塞，指长城。李白北游曾到雁门一带的关塞上。秋天了，他想到塞外，当早感霜威。\n云色渡河秋：云彩飘过黄河，也呈现秋色。\n故国：家乡。\n汾水：汾河。黄河第二大支流，发源于山西宁武县管涔山，流经山西中部、南部入黄河。《唐六典注》：汾水出忻州，历太原、汾、晋、绛、蒲五州，入河。《太平寰宇记》：汾水，出静乐县北管涔山，东流入太原郡界。', poem_appreciation = '作者虽心绪不高，而此诗格调自高，且带边塞诗之雄健，即所谓“健举之至，行气如虹”（《唐宋诗醇》）。后半反复写怀归之意，意重而不觉其重，语直而不觉其直，原因在于诗人措辞设喻之新奇巧妙。\n\n　　首联“岁落众芳歇，时当大伙流”。“众芳歇”中“芳”指花，就是说很多的花儿已经凋落了。在自然界中，花草之类，逢春而荣，遇秋而衰，这是自然规律。“大火”指星名，二十八星宿之一，也就是“心宿星”，居于正南，“流”指向下行，这里点出了时至七月了。诗歌开头两句借自然景物含蓄地表明了诗歌所描写的季节——早秋。从律诗的结构来说，这一联是起。\n\n　　接着进入颔联，承接首联的“早秋”。“霜威出塞早，云色渡河秋。” “威”就是威力、威风，在此指秋霜很浓。“出塞”、“渡河”是地域位置。“塞”指边塞。“河”指黄河。这两句直接描写了太原早秋的自然气候。特别要注意的是诗人为了更好地表现太原自然地理条件的特点，除了用词语描写外，诗人还运用了镶嵌的修辞手法，也就是在两句末镶嵌了“早”、“秋”两字，巧妙点题。所谓镶嵌的修辞手法，谭永祥教授在《汉语修辞美学》中说过：“将特定的字、词镶嵌在特定的文句中，以便收到多种表达效果，这种修辞手法叫‘镶嵌’。”同时又说：“将特定的字、词置于句首或句尾者叫‘镶’，置于句中者叫‘嵌’。”这种修辞手法的表达效果不但具有突出和强调意义的作用，而且在是文章增强趣味性和视觉的感染性。在这首诗歌中，标题中“早秋”在诗句中得到形式和内容上的照应，而且把两句通过“早”和“秋”联系起来，不但强调了诗人所描绘的“早秋”景色特点，而且在形式上得到相照应，形成对偶，使之构成一个完整的整体。\n\n　　进入颈联，在上面描写“早秋”的景色中，转入对家乡亲人的思念。“梦绕边城月，心飞故国楼”。“梦绕边城月”写的是梦境，含蓄地写出诗人正处在异域他乡。“心飞故国楼”写梦醒之后的状况。这两句的意思是说，我（诗人）虽身在异域他乡，做的梦也在边城月中萦绕，“月亮代表我的心”啊；可是当我梦醒之后，我“心飞故国楼”了。这里，一个“飞”字，表现出了诗人急于回到故乡的心情。这一联两句在形式上相对，意义上层层递进，表明了诗人对故乡及其亲人的思念之情。\n\n　　尾联是合。“思归若汾水，无日不悠悠”。“悠悠”就是本是忧郁的意思，但也有情悠悠，思悠悠之意。同时，联系上一句“思归若汾水”来看，“悠悠”也有绵延不断的意思。这两句的意思是说，我思念归家之情时时刻刻萦绕心头，就如同汾河水一样，没有一天断绝过啊。以水喻情，这是古代诗歌中常用的方法，也是“流水”这一意象所蕴含的意义之一。如，李煜的“问君能有几多愁，恰似一江春水向东流”；张说的“闻道神仙不可接，心随湖水共悠悠”；李白的“孤帆远影碧山尽，唯见长江天际流”。在这首诗里，诗人为了强调自己的“思归”之情的深远，也通过日夜不停的汾河水不停流淌为喻，形象而生动地表现出了自己日夜思归的情怀。\n\n　　在艺术手法上，这首诗注重了文题相映，特别是在颔联运用镶嵌的修辞手法，在两句的末尾分别用了“早”、“秋”两个字，匠心独运地点题并照应诗题。其次，后两句运用了明喻的修辞手法，生动形象地把抽象的思归之情形象化，以水喻情，连绵不断，明确表达了自己的思归不断的情怀。', poem_tags = '秋天,写景,思乡' WHERE poem_title = '太原早秋' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '清澈的湖水在秋夜的月亮下发着亮光，我到洞庭湖采白蘋。\n荷花姿态娇媚好像有话要对我说，却愁坏了我这个摇船人。', poem_notes = '渌（lù）水曲：古乐府曲名。渌水：即绿水，清澈的水。\n明秋月：在秋夜的月亮下发光。“明”字是形容词用如动词。月：一作“日”。\n南湖：即洞庭湖。白蘋：一种水生植物，又称“四叶菜”“田字草”，是多年生浅水草本，根茎在泥中，叶子浮在水面之上。\n欲语：好像要说话。\n愁杀：即“愁煞”，愁得不堪忍受的意思。杀：用在动词后，表示极度。荡舟人：这里指思念丈夫的女子。《史记·齐太公世家》：“桓公与夫人蔡姬戏舟中。蔡姬习水，荡公，公惧，止之，不止，出船，怒，归蔡姬，弗绝。”', poem_appreciation = '《渌水曲》本古曲名，李白借其名而写渌水之景。王琦认为此诗为乐府古曲。这首小诗确属乐府，并深得南朝乐府诗的神韵，语言清新自然，内容含蓄深婉。\n\n　　诗的前两句写实，点明时间、地点与劳动内容。“渌水明秋月”中的“月”字有的版本作“日”，今从《全唐诗》，而且从全诗的意境来看，“月”字也比“日”字更好一些，故择善而从之。这句诗的大意是说，碧波荡漾的水面在皎洁月光的映照下更加明亮。这句诗写在南边的湖面上，一位美丽的姑娘正在月光下采撷着白蘋。那宽阔无垠的湖面晶莹闪烁，水波不兴；那柔和银白的月光，挥洒若洗，朦朦胧胧，天地间极为静谧空旷。那位架着一叶小舟的女主人公显得尤为孤独寂寥，这就为后面两句诗提供了典型环境。\n\n　　三四句转折，写这位采蘋女子的孤独寂寞之感。这两句诗的大意是：含苞待放的荷花简直就象一位娇媚多情的少女就要开口说话一样，半开半含，欲言犹止，羞羞答答，十分妩媚动人。这美丽的奇景触发了这位荡舟女子的情思，她不免神魂摇荡，无限哀婉惆怅起来。诗至此戛然而止，但其深层的意蕴却在不断地延续，撞击着读者的心扉，引起其遥思遐想。\n\n　　这位女子看到娇艳的荷花就要“愁煞”，不言而喻，这是触景生情的缘故。良辰美景最容易引发人的情思，更容易惹起对恋人的向往和思念。这位少女独自在空荡荡的湖面上，披着明月的素辉，这情景已经够令人寂寞难耐的了，当她再看到那美妍的荷花含苞待放的情景时，不能不引起她的怀春之心。她或许是在痴情地憧憬着，如果将来有那么一天，自己能和情人在一起共同享受领略这旖旎迷人的风光时，该是何等的幸福啊！她或许是沉浸在对往事的回忆之中，在脑际中又呈现出昔日里与情郎在同样的景色中共同渡过的甜蜜而温馨的终生难忘的美好时光。这一切诗人都未明说，给读者留下了驰骋想象的广阔空间，既可能是这样又可能是那样，所以显得更加含蓄委婉，余味盎然。\n\n　　此诗中最精彩的是“荷花娇欲语”一句，其间运用了非常巧妙而又隐微的比喻手法，须仔细体味方可悟出。荷花是极其娇柔纯净的花卉，清秀妩媚，出于污泥而不染，这正像白璧无瑕的少女。“欲语”二字尤其传神深蕴，人之“欲语”则显现出刚要张口的样子，花之“欲语”也正是花苞正欲绽开，花瓣将要张口时的景象。说其巧妙，不仅是因为此时的花朵最为美丽诱人，还因为她最形象而又恰如其分地象征着诗中主人公那青春的活力与少女情窦乍开的年龄特征。大概正是因为客体与主体如此相像契合，才能深深地拨动主体的心弦，触动了那位荡舟人的春心。可见这两句诗所蕴涵的情感内容极为丰富隽永。', poem_tags = '乐府,荷花,女子' WHERE poem_title = '渌水曲' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '我的心无法逃避爱神射来的神箭，我炽爱着仍遭受侵略和封建压迫的家园。\n这份情感寄托给天上的星星却没有人明了，我誓将我的一腔热血报效我的祖国。', poem_notes = '自题小像：这首诗原无题目，诗题为作者好友许寿裳在其发表的《怀旧》一文中所加。\n灵台：指心，古人认为心有灵台，能容纳各种智慧。\n神矢：爱神之箭。作者鲁迅在这里，是把中了爱神丘比特的神箭比喻为自己对祖国对人民的热爱和对当时帝国主义的憎恨感情。\n风雨如磐：风雨，在这里指帝国主义的侵略和封建主义的统治。磐，扁而厚的大石。风雨如磐，比喻国家和民族灾难的深重。\n故园：故国、祖国。\n寄意寒星：这里的寒星从“流星”转化而来。寄意寒星，是说作者当时远在国外，想把自己一片爱国赤诚寄托天上的寒星，让它代为转达于祖国人民。\n荃，香草名，古时比喻国君，这里借喻祖国人民。不察，不理解。\n荐：奉献。\n轩辕：即黄帝，是古代传说中的氏族帮落酋长。', poem_appreciation = '“灵台无许逃神失”，诗一开头就用希腊神话白虹神箭射心这个形象的比喻，倾诉了作者鲁迅强烈的爱国主义情思。作者鲁迅还在南京求学时，就努力学习西方的先进思想，密切注视当时的政治局势，关心国家大事，关心民族命运；到日本后，又接受了孙中山领导的民族民主革命的思潮影响，因而祖国的垂危、人民的苦难，更象神箭一样射中了他，使他无时无刻不为祖国和人民的命运担心和忧虑。这句诗展示了作者热爱祖国、热爱人民，把挽救国家危亡看作自己神圣职责的革命胸怀，表现了鲁迅积极战斗的人生观和彻底反帝反封建的革命民主主义立场。\n\n　　“风雨如磐暗故园”，是说帝国主义、封建主义的侵略和压迫，犹如磐石压顶，使祖国暗无天日，景象惨淡，岌岌可危。这句诗，高度概括了半封建半殖民地旧中国黑暗悲惨的现状，是产生“灵台无计逃神矢”这一强烈感情的客观原因。作者鲁迅这时虽身居异域，远隔重洋，但万里海天，并没有隔断他同祖国人民息息相通的联系。他遥念在帝国主义列强宰割蹂躏和清王朝反动统治下的祖国。灾难重重，危机四伏，内心的忧愤溢于字面。“暗”字不但写出了黑暗动荡的祖国的政治形势，而且写出鲁迅无法遏制的愤慨和深沉的忧虑。\n\n　　“寄意寒星荃不察“，“意”，指作者的救国救民的理想。“荃”，指人民。这里，作者用浪漫主义的想象表达自己拯救祖国的希望，希望他的救国救民的理想能为“荃“所理解，即希望祖国人民觉醒起来。作者鲁迅当时对人民群众的力量是有一定认识的，但是另一方面，由于历史的局限，鲁迅对人民群众的革命积极性还估计不足，因此发出了“寄意寒星荃不察”的慨叹。鲁迅慨叹“荃不察”，是迫切希望祖国人民能尽快觉醒，以便担当起拯救祖国的任务。\n\n　　最后一句“我以我血荐轩辕”，是鲁迅对祖国、对人民发出的庄严誓言，决心为祖国、为人民而献身。虽然人民暂时还未觉醒，但他要尽自己的努力，唤醒群众，和群众一起参加战斗，甘洒热血写春秋。这一肝胆照人，气贯长虹的诗句，字字倾注了作者鲁迅对祖国、对人民的无限忠心，表现了青年时代的鲁迅强烈的爱国主义精神和反帝反封建的革命英雄气概，将诗的感情升华到了一个激昂慷慨，热血沸腾的高度。\n\n　　这首诗，声调激越，感情强烈。作者运用顿挫跳跃的笔法，有曲折、有波澜、有起伏地把强烈的爱国主义情感抒发得深刻真切。全诗四句，先写作者热爱祖国的感情，继写由热爱而引起对处在“风雨如磬”之中的祖国的忧虑，再写由忧虑而感到“寄意寒星荃不察”，心情不免有点沉重，最后跃上一个新的高峰，激昂慷慨，热血沸腾，迸发出“我以我血荐轩辕”的最强音，充满着激励的力量。这首诗，还通过典故运用和比喻、象征的手法，使所抒发的感情形象化。如“神矢”这个典故的运用，就把抽象的爱国主义感情表现得更具体。“风雨如磬”这个富有象征性的比喻，十分形象地表现出黑暗势力的强大，民族危机的深重，国家处境的险恶。以“荃”这种芳香的草比喻人民，表现了鲁迅对人民热爱赞颂的感情。最后，用“轩辕”代祖国，并以血来奉献，更使爱国主义的思想得到最形象最突出的表现。', poem_tags = '爱国,忧民,励志' WHERE poem_title = '自题小像' AND poem_author = '鲁迅';
UPDATE edu_poem SET poem_translation = '杨柳围绕着曲折的池塘，偏僻的水渠旁，又厚又密的浮萍，挡住了采莲的姑娘。没有蜜蜂和蝴蝶，来倾慕我幽幽的芳香。荷花渐渐地衰老，结一颗芳心苦涩。\n潮水带着夕阳，涌进荷塘，行云夹着雨点，无情地打在荷花上。随风摇曳的她呀，像是向骚人诉说哀肠：当年不肯在春天开放，如今却在无端地在秋风中受尽凄凉。', poem_notes = '踏莎行：词牌名。又名《柳长春》《喜朝天》等。双调五十八字，仄韵。又有《转调踏莎行》，双调六十四字或六十六字，仄韵。\n回塘：环曲的水塘。\n别浦：江河的支流入水口。\n绿萍涨断莲舟路：这句话是说，水面布满了绿萍，采莲船难以前行。莲舟，采莲的船。\n红衣脱尽芳心苦：红衣，形容荷花的红色花瓣。芳心苦，指莲心有苦味。以上两句说，虽然荷花散发出清香，可是蜂蝶都断然不来，它只得在秋光中独自憔悴。\n返照：夕阳的回光。\n潮：指晚潮。\n行云：流动的云。\n依依：形容荷花随风摇摆的样子。\n骚人：诗人。\n不肯嫁春风：语出韩偓《寄恨》诗：“莲花不肯嫁春风。”张先在《一丛花》词里写道：“沉恨细思，不如桃杏，犹解嫁东风。”贺铸是把荷花来和桃杏隐隐对比。以上两句写荷花有“美人迟暮”之感。', poem_appreciation = '此词全篇咏写荷花，借物言情，暗中以荷花自况。诗人咏物，很少止于描写物态，多半有所寄托。因为在生活中，有许多事物可以类比，情感可以相通，人们可以利用联想，由此及彼，发抒文外之意。所以从《诗经》、《楚辞》以来，就有比兴的表现方式。词也不在例外。\n\n　　此词起两句写荷花所在之地。“回塘”，位于迂回曲折之处的池塘。“别浦”，不当行路要冲之处的水口。（小水流入大水的地方叫做浦。另外的所在谓之别，如别墅、别业、别馆）回塘、别浦，在这里事实上是一个地方。就储水之地而言，则谓之塘；就进水之地而言，则谓之浦。荷花在回塘、别浦，就暗示了她处于不容易被人发现，因而也不容易为人爱慕的环境之中。“杨柳”、“鸳鸯”，用来陪衬荷花。杨柳在岸上，荷花在水中，一绿一红，着色鲜艳。鸳鸯是水中飞禽，荷花是水中植物，本来常在一处，一向被合用来作装饰图案，或绘入图画。用鸳鸯来陪衬荷花之美丽，非常自然。\n\n　　第三句由荷花的美丽转入她不幸的命运。古代诗人常以花开当折，比喻女子年长当嫁，男子学成当仕，故无名氏所歌《金缕衣》云：“劝君莫惜金缕衣，劝君惜取少年时。花开堪折直须折，莫待无花空折枝。”而荷花长在水中，一般都由女子乘坐莲舟前往采摘，如王昌龄《采莲曲》所写：“吴姬越艳楚王妃，争弄莲舟水湿衣。来时浦口花迎入，采罢江头月送归。”但若是水中浮萍太密，莲舟的行驶就困难了。这当然只是一种设想，而这种设想，则是从王维《皇甫岳云溪杂题·萍池》“春池深且广，会待轻舟回。靡靡绿萍合，垂杨扫复开”来，而反用其意。以荷花之不见采由于莲舟之不来，莲舟之不来由于绿萍之断路，来比喻自己之不见用由于被人汲引之难，被人汲引之难由于仕途之有碍。托喻非常委婉。\n\n　　第四句再作一个比譬。荷花既生长于回塘、别浦，莲舟又被绿萍遮断，不能前来采摘，那么能飞的蜂与蝶该是可以来的吧。然而不幸的是，这些蜂和蝶，又不知幽香之可爱慕，断然不来。这是以荷花的幽香，比自己的品德；以蜂蝶之断然不来，比在上位者对自己的全不欣赏。\n\n　　歇拍承上两譬作结。莲舟不来，蜂蝶不慕，则美而且香的荷花，终于只有自开自落而已。“红衣脱尽”，是指花瓣飘零；“芳心苦”，是指莲心有苦味。在荷花方面说，是设想其盛时虚过，旋即凋败；在自己方面说，则是虽然有德有才，却不为人知重，以致志不得行，才不得展，终于只有老死牖下而已，都是使人感到非常痛苦的。将花比人，处处双关，而毫无牵强之迹。\n\n　　过片推开一层，于情中布景。“返照”二句，所写仍是回塘、别浦之景色。落日的余辉，返照在荡漾的水波之上，迎接着由浦口流入的潮水。天空的流云，则带着一阵或几点微雨，洒向荷塘。这两句不仅本身写得生动，而且还暗示了荷花在塘、浦之间，自开自落，为时已久，屡经朝暮，饱历阴晴，而始终无人知道，无人采摘，用以比喻在自己的生活经历中，也遭遇过多少世事沧桑、人情冷暖。这样写景，就同时写出了人物的思想感情乃至性格。\n\n　　“依依”一句，显然是从李白《渌水曲》“荷花娇欲语，愁杀荡舟人”变化而来。但指明“语”的对象为骚人，则比李诗的含义为丰富、深刻。屈原《离骚》：“制芰荷以为衣兮，集芙蓉以为裳。不吾知其亦已兮，苟余情其信芳。”正因为屈原曾设想采集荷花（芙蓉也是荷花，见王逸《注》）制作衣裳，以象征自己的芳洁，所以词中才也设想荷花于莲舟不来，蜂蝶不慕，自开自落的情况之下，要将满腔心事，告诉骚人。但此事究属想象，故用一“似”字，与李诗用“欲”字同，显得虚而又活，幻而又真。王逸《〈离骚经〉章句序》中曾指出：“《离骚》之文，依《诗》取兴，引类譬喻。故善鸟、香草，以配忠贞……宓妃、佚女，以譬贤臣。”从这以后，香草、美女、贤士就成为三位一体了。在这首词中，作者以荷花（香草）自比，非常明显，而结尾两句，又因以“嫁”作比，涉及女性，就同样也将这三者连串了起来。\n\n　　“当年”两句，以文言，是想象中荷花对骚人所倾吐的言语；以意言，则是作者的“夫子自道”。行文至此，花即是人，人即是花，合而为一了。“当年不肯嫁春风”，是反用张先的《一丛花令》“沉恨细思，不如桃杏，犹解嫁东风”，一看即知，而荷花之开，本不在春天，是在夏季，所以也很确切。春天本是百花齐放、万紫千红的时候，诗人既以花之开于春季，比作嫁给春风，则指出荷花之“不肯嫁春风”，就含有她具有一种不愿意和其它的花一样地争妍取怜那样一种高洁的、孤芳自赏的性格的意思在内。这是写荷花的身分，同时也就是在写作者自己的身分。但是，当年不嫁，虽然是由于自己不肯，而红衣尽脱，芳心独苦，岂不是反而没由来地被秋风耽误了吗？这就又反映了作者由于自己性格与社会风习的矛盾冲突，以致始终仕路崎岖，沉沦下僚的感叹。南唐中主《浣溪沙》云：“菡萏香销翠叶残，西风愁起绿波间。”王国维《人间词话》认为“大有众芳芜秽，美人迟暮之感”。（“惟草木之零落兮，恐美人之迟暮”“虽萎绝其亦何伤兮，哀众芳之芜秽”均《离骚》句。）这位著名的文学批评家是敏感地察觉到了这个偏安小国的君主为自己不可知的前途而发出的叹息的。晏几道的《蝶恋花》咏荷花一首，可能是为小莲而作。其上、下片结句“照影弄妆娇欲语，西风岂是繁华主”和“朝落暮开空自许，竟无人解知心苦”，与这首词“无端却被秋风误”和“红衣脱尽芳心苦”的用笔用意，大致相近，可以参照。\n\n　　由于古代诗人习惯于以男女之情比君臣之义、出处之节，以美女之不肯轻易嫁人比贤士之不肯随便出仕，所以也往往以美女之因择夫过严而迟迟不能结婚以致耽误了青春年少的悲哀，比贤士之因择主、择官过严而迟迟不能任职以致耽误了建立功业的机会的痛苦。曹植《美女篇》：“佳人慕高义，求贤良独难。……盛年处房室，中夜起长叹。”杜甫《秦州见敕目薛、毕迁官》：“唤人看腰?，不嫁惜娉婷。”陈师道《长歌行》：“春风永巷闭娉婷，长使青楼误得名。不惜卷帘通一顾，怕君着眼未分明。”“当年不嫁惜娉婷，抹白施朱作后生。说与旁人须早计，随宜梳洗莫倾城。”虽立意措词有所不同，但都是以婚媾之事，比出处之节。这首词则通体以荷花为比，更为含蓄。\n\n　　作者在词中隐然将荷花比作一位幽洁贞静、身世飘零的女子，借以抒发才士沦落不遇的感慨。《宋史》“虽要权倾一时，少不中意，极口诋之无遗辞。人以为近侠。竟以尚气使酒，不得美官，悒悒不得志”，这些记载，对于理解此词的深意颇有帮助。', poem_tags = '宋词三百首,婉约,咏物,荷花,抒怀,命运' WHERE poem_title = '芳心苦·杨柳回塘' AND poem_author = '贺铸';
UPDATE edu_poem SET poem_translation = '从城上高楼远眺空旷的荒野，如茫茫海天般的愁思涌了出来。\n急风胡乱地掀动水中的荷花，密雨斜打在长满薜荔的墙上。\n山上的树重重遮住了远望的视线，江流曲折就像九转的回肠。\n我们一起来到百越这个少数民族地区，虽然处于一地音书却阻滞难通。', poem_notes = '柳州：今属广西。\n漳州、汀洲：今属福建。\n封州、连州：今属广东。\n刺史：州的行政长官，相当于后世的知府。\n接：连接。一说，目接，看到\n大荒：旷远的广野。\n惊风：急风；狂风。\n乱飐（zhǎn）：吹动。\n芙蓉：指荷花。\n薜荔：一种蔓生植物，也称木莲。重遮：层层遮住。千里目：这里指远眺的视线。江：指柳江。九回肠：愁肠九转，形容愁绪缠结难解。\n共来：指和韩泰、韩华、陈谏、刘禹锡四人同时被贬远方。百越：即百粤，指当时五岭以南各少数民族地区。\n文身：古代南方少数民族有在身上刺花纹的风俗。文：通“纹”，用作动词。犹自：仍然是。音书：音信。滞：阻隔。', poem_appreciation = '这首抒情诗，赋中有比，象中含兴，情景交融，凄楚动人。\n\n　　全诗先从“登柳州城楼”写起。首句“城上高楼”，于“楼”前着一“高”字，立身愈高，所见愈远。作者长途跋涉，好容易才到柳州，却急不可耐地登上高处，为的是要遥望战友们的贬所，抒发难于明言的积愫。“接大荒”之“接”字，是说城上高楼与大荒相接，乃楼上人眼中所见。于是感物起兴，“海天愁思正茫茫”一句，即由此喷涌而出，展现在诗人眼前的是辽阔而荒凉的空间，望到极处，海天相连。而自己的茫茫“愁思”，也就充溢于辽阔无边的空间了。这么辽阔的境界和这么深广的情意，作者却似乎毫不费力地写入了这第一联，摄诗题之魂，并为以下的逐层抒写展开了宏大的画卷。\n\n　　第二联“惊风乱飐芙蓉水，密雨斜侵薜荔墙”，写的是近处所见。惟其是近景，见得真切，故写得细致。就描绘风急雨骤的景象而言，这是“赋”笔，而赋中又兼有比兴。屈原《离骚》有云：“制芰荷以为衣兮，集芙蓉以为裳。不吾知其亦已兮，苟余情其信芳。”又云：“擥木根以结茝兮，贯薜荔之落蕊；矫菌桂以纫蕙兮，索胡绳之纚纚。謇吾法大前修兮，非世俗之所服。”在这里，芙蓉与薜荔，正象征着人格的美好与芳洁。登城楼而望近处，从所见者中特意拈出芙蓉与薜荔，显然是它们在暴风雨中的情状使诗人心灵颤悸。风而曰惊，雨而曰密，飐而曰乱，侵而曰斜，足见对客观事物又投射了诗人的感受。芙蓉出水，何碍于风，而惊风仍要乱飐；薜荔覆墙，雨本难侵，而密雨偏要斜侵。这不禁使诗人产生联想，愁思弥漫。在这里，景中之情，境中之意，赋中之比兴，有如水中着盐，不见痕迹。\n\n　　第三联写远景。由近景过渡到远景的契机乃是近景所触发的联想：自己目前是处于这样的情境之中，好友们的处境又是如何呢？于是心驰远方，目光也随之移向漳、汀、封、连四州。“岭树”、“江流”两句，同写遥望，却一仰一俯，视野各异。仰观则重岭密林、遮断千里之目；俯察则江流曲折，有似九回之肠。景中寓情，愁思无限。从字面上看，以“江流曲似九回肠”对“岭树重遮千里目”，铢两悉称，属于“工对”的范围。而从意义上看，上实下虚，前因后果，以骈偶之辞运单行之气，又具有“流水对”的优点。\n\n　　尾联从前联生发而来，除表现关怀好友处境望而不见的惆怅之外，还有更深一层的意思：望而不见，自然想到互访或互通音问；而望陆路，则山岭重叠，望水路，则江流纡曲，不要说互访不易，即互通音讯，也十分困难。这就很自然地要归结到“音书滞一乡”。然而就这样结束，文情较浅，文气较直。作者的高明之处。在于他先用“共来百粤文身地”一垫，再用“犹自”一转，才归结到“音书滞一乡”，便收到了沉郁顿挫的艺术效果。而“共来”一句，既与首句中的“大荒”照应，又统摄题中的“柳州”与“漳、汀、封、连四州”。一同被贬谪于大荒之地，已经够痛心了，还彼此隔离，连音书都无法送到。余韵袅袅，余味无穷，而题中的“寄”字之神，也于此曲曲传出。可见诗人用笔之妙。', poem_tags = '唐诗三百首,抒情,怀人' WHERE poem_title = '登柳州城楼寄漳汀封连四州' AND poem_author = '柳宗元';
UPDATE edu_poem SET poem_translation = '五月的天山雪花仍在飘洒，看不见花朵开放只有刺骨的严寒。\n笛子吹着《折杨柳》的曲调，又何处寻觅杨柳青青的春天。\n拂晓时分随着号令之声作战，晚上枕着马鞍露宿入眠。\n只愿用腰下悬挂的宝剑，为君王过关斩将，打败敌人。\n\n我军向北方荒远地带进军，因为那里的游牧民族经常南下侵扰。\n横曳戈矛前往战场，身经百战，只是因为受皇恩眷顾太深了。\n在大沙漠里握雪成团而食，夜里拂去沙土露宿于旷野。\n什么时候才能打败敌人，然后就可以高枕无忧呢？\n\n骏马像狂风般地驰骋，在清脆的马鞭挥动声响中，飞快地奔出了渭桥。\n我们全副武装离开京城开赴边疆，奉命前去击破前来侵扰的匈奴。\n敌人的队伍被瓦解，边境的危机被解除，敌军的营寨已空无一人，战争的气氛消失了。\n成就大功而画像麒麟阁的，只有霍去病一人。\n\n白色的骏马，多沙的边塞，细碎的石粒，这一切都是因你而梦魂牵绕的。\n这愁苦的日子真不堪忍受，我远远地思念戍守边疆的你。\n秋天萤火虫满纱窗地乱飞乱撞，月光照在我的闺房前久不离去。\n梧桐叶在秋天里被摧落，空落的沙棠枝更让人心感萧条。\n常常独自吟唱着《独不见》，虽然流下了许多伤心的泪水，可是这一切也只有自己一个人知道。\n\n匈奴为掠夺秋季丰收的粮食而悍然入侵，朝廷派出军队抗击。\n将军受命出兵，战士们行军到塞外，在龙沙一带暂时安营扎寨。\n边塞的月光伴着弓影，胡地的雪霜拂过剑锋。\n战士们还远没有进入玉门关，少妇们不要长声感叹。\n\n烽火在沙漠深处燃起，连绵直到甘泉宫，照亮了甘泉宫上空的云层。\n汉武帝握剑拍案而起，回头召来李广将军。\n战斗的气氛弥漫着天空，震天的鼓声，连山坡底下都可清晰听闻。\n横行战场靠的是勇敢的气魄，在将士们的奋勇拼杀下，一仗就消灭了敌人。', poem_notes = '天山：指祁连山。\n折柳：即《折杨柳》，古乐曲名。\n金鼓：指锣，进军时击鼓，退军时鸣金。\n天兵：指汉朝军队。\n衔恩：受恩。甚：多。\n海：瀚海，大沙漠。陇头：田野。\n高枕：高枕无忧。\n鸣鞭：马鞭挥动时发出声响。渭桥：在长安西北渭水上。\n天骄：指匈奴。\n海雾：沙漠上的雾气，指战争的气氛。\n麟阁：即麒麟阁。霍嫖姚：即霍去病。\n云砂：细碎的石粒，指边塞风光。\n沙棠：植物名，果味像李子。\n独不见：《独不见》是乐府古题，吟诵的是思而不得见的落寞愁绪。\n虎竹：兵符。龙沙：即白龙堆，指塞外沙漠地带。\n剑花：剑刃表面的冰裂纹。\n殊：远。嗟：感叹。\n甘泉：甘泉山，秦时在山上造甘泉宫，汉武帝扩建。\n合：满。陇底：山坡下。\n负：凭借。妖氛：指敌人。', poem_appreciation = '李白有《塞下曲》六首。元人萧士赟云：“此《从军乐》体也。”这一组诗与其他许多初、盛唐边塞诗一样，以乐观高亢的基调和雄浑壮美的意境反映了盛唐的精神风貌。\n\n　　【其一】\n\n　　首句言“五月天山雪”，已经扣紧题目。五月，在内地正值盛夏。韩愈说“五月榴花照眼明，枝间时见子初成”，赵嘏说“和如春色净如秋，五月商山是胜游”。但是，李白所写五月却在塞下，在天山，自然，所见所感也就迥然有别。天山孤拔，常年被积雪覆盖。这种内地与塞下在同一季节的景物上的巨大反差，被诗人敏锐地捕捉，然而，他没有具体细致地进行客观描写，而以轻淡之笔徐徐道出自己内心的感受：“无花只有寒”。“寒”字，隐约透露出诗人心绪的波动，何况寒风之中又传来《折杨柳》的凄凉曲调呢!春天在边疆是看不到的，人们只能从笛曲之中去领受，去回味。《折杨柳》为乐府横吹曲，多写行客的愁苦。在这里，诗人写“闻折柳”，当亦包含着一层苍凉寒苦的情调。他是借听笛来渲染烘托这种气氛的。沈德潜评论这首《塞下曲》前四句说：“四语直下，从前未具此格。”又说：“一气直下，不就羁缚。”诗为五律，依惯例当于第二联作意思上的承转，但是李白却就首联顺势而下，不肯把苍凉情绪稍作收敛，这就突破了格律诗的羁绊，以气脉直行，豪纵不拘，语淡而雄浑为其特色了。\n\n　　“晓战随金鼓，宵眠抱玉鞍。”古代出征要敲击钲、鼓，用来节制士卒进退，五、六两句，写的正是这种情况。语意转折，已由苍凉变为雄壮。诗人设想：自己来到边塞，就在天山脚下，整日过着紧张的战斗生活。白天在钲、鼓声中行军作战，晚上就抱着马鞍子打盹儿。这里，“晓战”与“宵眠”相对应，当是作者有意在概括军中一日的生活，其军情之紧张急迫，跃然纸上。“随”字，摹状士卒的令行禁止。“抱”字，描绘士卒夜间警备的情况。二句写的是士卒的生活场景，而他们守边备战，人人奋勇，争为功先的心态则亦尽情流露出来。\n\n　　尾联“愿将腰下剑，直为斩楼兰”。斩楼兰：据《汉书·傅介子传》：“汉代地处西域的楼兰国经常杀死汉朝使节，傅介子出使西域，楼兰王贪他所献金帛，被他诱至帐中杀死，遂持王首而还”。这里是借用傅介子慷慨复仇的故事，表现诗人甘愿赴身疆场，为国杀敌的雄心壮志。“直”与“愿”字呼应，语气斩截强烈，一派心声，喷涌而出，自有夺人心魄的艺术感召力。\n\n　　【其二】\n\n　　这首诗写战士们努力征战，不辞辛苦，希望能真正营造出一个和平安宁的环境，让广大人民不再受外族入侵的威胁，过上安居乐业的生活。\n\n　　【其三】\n\n　　首句写战马飞奔，有如风驰电掣。写“骏马”实际上是写驾驭骏马的健儿们，马壮是为了借喻兵强。在唐代前期，胡马南侵是常有的，唐高祖李渊甚至一度被迫“称臣于突厥”（《旧唐书·李靖传》）。因此，健儿们杀敌心切，斗志昂扬，策马疾行。\n\n　　“出渭桥”和“辞汉月”，是指出军队的出发点和行军路线。“出渭桥”而“鸣鞭”，正所谓快马加鞭，进一步烘托出健儿们的急切心情，也渲染了军事任务的紧迫和唐军士气的旺盛。气势雄浑，大有高唱入云之势。\n\n　　从“辞汉月”到“破天骄”，即从军队出发到克敌制胜，是一个极大的转折。“插羽”，鞍上箭。“天骄”，匈奴曾自称“天之骄子”，这里泛指敌人。从“弯弓”到“插羽”，瞬间就完成了这样一个大转折，省掉了多少鏖战情节和厮杀场面的描写，足见布局的简洁，笔法的洗炼。然而这又是十分自然的、可信的。既然是兵强马壮，士气高昂，自然就会旗开得胜，马到成功。天兵所向，势如拉枯摧朽。这是符合逻辑和顺理成章的。也暗示将领指挥得当，这次战役完全符合“兵贵神速”的兵法要求。\n\n　　五、六句描写“破天骄”后的战场景象。在正义之师面前，敌人不堪一击，土崩瓦解，望风而逃。古人认为客星呈现白色的光芒，就是战争的征兆。星芒已尽，就意味着战争结束。北方沙漠、草原，广阔无垠，浩瀚如海，故名瀚海。“海雾消”，指漠北战争气氛已经消失。\n\n　　麟阁，即麒麟阁，汉代阁名，在未央宫中。汉宣帝时曾绘十一位功臣像于其上，后即以此代表卓越的功勋和最高荣誉。霍嫖姚，指霍去病，汉武帝时大将，曾任“嫖姚校尉”。清人王琦云：“末言功成奏凯，图形麟阁者，止上将一人，不能遍及血战之士。太白用一‘独’字，盖有感于其中欤。然其言又何婉而多风也。”（《李太白全集》注）从某种意义上讲，这两句确实或有讽刺之意。同时也是以士卒口吻表示：明知血战凯旋后只能有“上将”一人图形麟阁，但他们仍因能报效国家、民族而感到自豪和满足。功业不朽不一定必须画像麟阁。这更能体现健儿们的英雄主义和献身精神，使此诗具有更能震撼人心的悲壮色彩。诗人为“济苍生，安社稷”，是“愿为辅弼”的。但他一直希望功成身退，归隐林泉。他多次表示要“功成身不居”（《商山四皓》），“功成谢人间”（《翰林读书言怀》）。从中可以窥见诗人的素志和生活情趣。这首诗前六句为总的铺叙以引出结尾两句的感慨。在前六句中，前三句描绘出师时的雄壮，后三句妆摹破敌时的英威。全诗笔力雄健，结构新颖，篇幅布局，独具匠心。\n\n　　【其四】\n\n　　这首诗写的是闺中女子对远征亲人的思念。开头写闺中女子想象亲人戍守边塞的情形，以此寄托思念之情。接着写女子在离愁的煎熬中，度日如年的情景。\n\n　　【其五】\n\n　　首联两句，分述了敌我两军的态势，指明了这场战争的性质。“塞虏”，塞外的强盗，含有轻蔑、贬斥之意。当时的北方诸胡，有的还是原始部落，有的则转向世袭王权制，处于原始社会解体时期。他们对唐王朝的物质文明常怀觊觎之心，故边境屡遭蹂躏边塞战争大都起因于此。“乘秋下”，是指到了秋收季节，他们就乘隙而入，烧杀劫掠。“天兵”，天朝的军队，含有歌颂、赞美之意。他们堂堂正正，出塞去抗击胡虏。通过措词的褒贬色彩，表明了诗人鲜明的爱憎。\n\n　　颔联两句，与首联“天兵”照应。“虎竹”，兵符，分铜虎符与竹使符两种，合称虎竹，由朝廷和将领各执一半，发兵时相对合作为凭证。“将军分虎竹”，是指将领接到征战的诏令。“战士卧龙沙”，指军队已抵达塞外战场。“龙沙”，指白沙堆沙漠，在楼兰国附近。这两句属对工整，气势磅礴。从将军到战士，同仇敌忾，威严整肃，争相建功报国。刚刚颁发诏令，很快就已深入敌区，表明进军神速，所向无敌。清人吴汝纶说这两句“有气骨有采泽，是太白才华过人处”（《唐宋诗举要》），是深中肯綮的。\n\n　　颈联两句，描写边塞风光和战斗生活。“胡霜”与首联的“秋”相照应。“边月”、“胡霜”，均为静物。皎洁的月色，银白的寒霜，笼罩在一望无际的荒漠上，造成一派朦胧苍凉的气氛。而“弓影”飘移，“剑花”闪烁，则包含着战士的行动。用“随”和“拂”这样两个锤炼而得的动词把两者结合起来，就使静物和人物的动态融为一体，显得生机勃勃。这就构成一种奇妙的意境：于苍茫中见壮美，于异彩中显飘逸。诚如沈德潜所说：“只弓如月，剑如霜耳，笔端点染，遂成奇彩。”（《唐诗别裁》）弓与月，形状相似；剑与霜，颜色相同。诗人巧妙地利用它们的某种共性，使它们之间的联系显得自然、和谐，使艰苦的军旅生活衬托得轻松、愉快。因此邢昉说：“以太白之才咏关塞，而悠悠闲淡如此，诗所以贵淘炼也。”（《唐风定》）在尾联中以诗中主人公的口气抒发了“天兵”的必胜信念和献身精神，把全诗推向了高潮。“玉关殊未入，少妇莫长嗟”，是征人向少妇劝慰：未获全胜，玉门关还不能入，请亲人耐心等待，不必长吁短叹。大有“匈奴未灭，何以家为”的英雄气概。据《后汉书》，班超上疏云：“臣不敢望到酒泉郡，但愿生入玉门关。”这里是反其意而用之。《艺苑雌黄》云：“直用其事，人皆能之。反其意而用之者，非学业高人，超越寻常拘挛之见，不规规蹈袭前人陈迹者，何以臻此！”李白之善于用典，大率类此。结局不落边塞诗以乡愁，闺怨作结的窠臼，而造成余音袅袅余韵无穷之感。这别具一格的结尾，使贯串全诗的壮美情怀更加完善，崇高精神得到升华了。\n\n　　【其六】\n\n　　这首诗写了由于匈奴南侵引起新的战争，但在杰出将领的率领下，勇敢的战士们又一次赢得了战争的胜利。\n\n　　中原地区长期遭受北方游牧民族的侵扰，唐时北方突厥非常凶悍，对李唐王朝形成了长期严重的威胁。诗人选择汉军抗击匈奴的题材，部分原因即在于此。', poem_tags = '乐府,边塞,组诗' WHERE poem_title = '塞下曲六首' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '富贵袭人而来人也没有办法，一个人奋发，他的成就是止不住的。\n满堂的花香熏醉了无数宾客，一把利剑横扫两折十四州。\n战鼓和号角声冲入云霄使得天之气都变得寒冷，风浪席卷而来让天下好像入了秋。\n掌握这东南之地，作祥瑞天象的支柱，谁还羡慕旧时的万户侯呢。', poem_notes = '钱尚父：即钱镠，五代十国时期吴越国的创建者。\n贵逼人来：富贵逼人而来，即不求富贵而富贵自来。\n龙骧凤翥：也作凤翥龙骧，形容发奋有为。\n十四州：当时吴越王钱镠安居十四州。\n鼓角：战鼓和号角声。\n揭天：指声音高入天际。\n嘉气：即瑞气。\n金天：黄色的天，古时以为祥瑞。\n万户侯：食邑万户之侯，常用来泛指高爵显位。', poem_tags = '写人,赞美' WHERE poem_title = '献钱尚父' AND poem_author = '贯休';
UPDATE edu_poem SET poem_translation = '不知道香积寺在什么地方，攀登好几里误入云拥群峰。\n古木参天却没有人行路径，深山里何处传来古寺鸣钟。\n山中泉水撞危石响声幽咽，松林里日光照射也显寒冷。\n黄昏时来到空潭隐蔽之地，安然地修禅抑制心中毒龙。', poem_notes = '过：过访，探望。香积寺：唐代著名寺院，有争议，一说香积寺在长安县（今陕西省西安市）南神禾原上。”故址已废。一说在河南汝州，今风穴寺，唐时称香积寺。\n入云峰：登上入云的高峰。\n钟：寺庙的钟鸣声。\n咽：呜咽。危：高的，陡的。“危石”意为高耸的崖石。\n冷青松：为青松所冷。\n薄暮：黄昏。曲：水边。“安禅”即安静地打坐，在这里指佛家思想。\n安禅：为佛家术语，指身心安然进入清寂宁静的境界，在这里指佛家思想。毒龙：佛家比喻俗人的邪念妄想。见《涅槃经》：“但我住处有一毒龙，想性暴急，恐相危害。”', poem_appreciation = '诗题“过香积寺”的“过”，意谓“访问”、“探望”。既是去访香积寺，却又从“不知”说起；“不知”而又要去访，表现出诗人的洒脱不羁。因为“不知”，诗人便步入茫茫山林中去寻找，行不数里就进入白云缭绕的山峰之下。此句正面写人入云峰，实际映衬香积寺之深藏幽邃。还未到寺，已是如此云封雾罩，香积寺之幽远可想而知矣。\n\n　　接着四句，是写诗人在深山密林中的目见和耳闻。先看三四两句。古树参天的丛林中，杳无人迹；忽然又飘来一阵隐隐的钟声，在深山空谷中回响，使得本来就很寂静的山林又蒙上了一层迷惘、神秘的情调，显得越发安谧。“何处”二字，看似寻常，实则绝妙：由于山深林密，使人不觉钟声从何而来，只有“嗡嗡”的声音在四周缭绕；这与上句的“无人”相应，又暗承首句的“不知”。有小径而无人行，听钟鸣而不知何处，再衬以周遭参天的古树和层峦叠嶂的群山。这是十分荒僻而又幽静的境界。\n\n　　五六两句，仍然意在表现环境的幽冷，而手法和上二句不同，写声写色，逼真如画，堪称名句。诗人以倒装句，突出了入耳的泉声和触目的日色。“咽”字在这里下得极为准确、生动：山中危石耸立，流泉自然不能轻快地流淌，只能在嶙峋的岩石间艰难地穿行，仿佛痛苦地发出幽咽之声。诗人用“冷”来形容“日色”，粗看极谬，然而仔细玩味，这个“冷”字实在太妙了。夕阳西下，昏黄的余晖涂抹在一片幽深的松林上，这情状，不能不“冷”。诗人涉荒穿幽，直到天快黑时才到香积寺，看到了寺前的水潭。“空潭”之“空”不能简单地理解为“什么也没有”。王维诗中常用“空”字，如“空山不见人”、“空山新雨后”、“夜静春山空”之类，都含有宁静的意思。暮色降临，面对空阔幽静的水潭，看着澄清透彻的潭水，再联系到寺内修行学佛的僧人，诗人不禁想起佛教的故事：在西方的一个水潭中，曾有一毒龙藏身，累累害人。佛门高僧以无边的佛法制服了毒龙，使其离潭他去，永不伤人。佛法可以制毒龙，亦可以克制世人心中的欲念啊。“安禅”为佛家术语，即安静地打坐，在这里指佛家思想。“毒龙”用以比喻世俗人的欲望。\n\n　　王维晚年诗笔常带有一种恬淡宁静的气氛。这首诗，就是以他沉湎于佛学的恬静心境，描绘出山林古寺的幽邃环境，从而造成一种清高幽僻的意境。王国维谓“不知一切景语，皆情语也”。这首诗的前六句纯乎写景，然无一处不透露诗人的心情，可以说，王维是把“晚年惟好静”的情趣融化到所描写的景物中去的了。因此最后“安禅制毒龙”，便是诗人心迹的自然流露。\n\n　　诗采用由远到近、由景入情的写法，从“入云峰”到“空潭曲”逐步接近香积寺，最后则吐露“安禅制毒龙”的情思。这中间过渡毫无痕迹，浑然天成。诗人描绘幽静的山林景色，并不一味地从寂静无声上用力，反而着意写了隐隐的钟声和呜咽的泉声，这钟声和泉声非但没有冲淡整个环境的平静，反而增添了深山丛林的僻静之感。这就是通常所讲的“鸟鸣山更幽”的境界。', poem_tags = '唐诗三百首,写景' WHERE poem_title = '过香积寺' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '注释 更阑：午夜时分。 厌禳：谓以巫术祈祷鬼神除灾降福，或致灾祸于人，或降伏某物。 钝滞：迟钝呆滞。 两句合起来的解释就是，除夕夜直到午夜时分人们都还没有睡意，都在祈求神灵除灾降福、大家都呆滞的等待新的一年的临近和到来。', poem_tags = '节日,春节' WHERE poem_title = '卖痴呆词' AND poem_author = '范成大';
UPDATE edu_poem SET poem_translation = '其一\n大自然和人类社会不断的运动发展，新事物，新思想层出不穷。\n即使能预支五百年的新意作，到了一千年又觉得陈旧了。\n\n其二\n李白和杜甫的篇曾经被成千上万的人传颂，但读起来感觉已经没有什么新意了。\n国家代代都有很多有才情的人，他们的诗篇文章以及人气都会流传数百年。\n\n其三\n纷纷的艺苑里各种说法鱼龙混杂，良莠不齐，对错互见，深浅不一，对同一问题的看法有时也五花八门。这时需要的是独具慧眼，有自己的视角和观点。\n如果自己见识低下，就像矮人看戏似的，自己什么也没看见，对戏的好坏心中没有定数，只是随声附和罢了。', poem_notes = '李杜：指李白、杜甫。\n江山代有才人出：国家代代都有很多有才情的人。\n风骚：指《诗经》中的“国风”和屈原的《离骚》。后来把关于诗文写作的诗叫做“风骚”。这里指在文学上有成就的“才人”的崇高地位和深远影响。\n只眼：独到的见解，眼力出众。\n艺苑：艺坛，艺术领域。\n雌黄：即鸡冠石，黄赤色，可作颜料。古人写字用黄纸，写错了用雌黄涂掉再写。后用信口雌黄喻随口乱说。', poem_appreciation = '其二\n\n　　第一、二句人指出，即使是李白、杜甫这样伟大的诗人，他们的诗篇也有历史局限性。\n\n　　第三、四句诗人呼唤创新意识，希望诗歌写作要有时代精神和个性特点，大胆创新，反对演习守旧。\n\n　　世人常常用这句诗来赞美人才辈出，或表示一代新人替换旧人，或新一代的崛起，就如滚滚长江，无法阻拦。\n\n　　此反映了作者诗歌创作贵在创新的主张。他认为诗歌随时代不断发展，诗人在创作的时候也应求新求变，并非只有古人的作品才是最好的，每个时代都有属于自己的风格的诗人。写出了后人继承前人。本诗虽语言直白，但寓意深刻。“江山代有才人出，各领风骚数百年。”一句表达了文学创作随着时代变化发展的主题思想与中心。\n\n　　赵翼论诗提倡创新，反对机械模式。他通过对诗家李白、杜甫成就的回顾，以历史发展的眼光来看，各个时代都有其标领风骚的人物，不必为古人是从。诗歌也应随着时代不断发展。\n\n其三\n\n　　这是一首作者表白自己的艺术主张的诗。指出文艺批评应提倡有独到的见解，不可鹦鹉学舌，人云亦云。\n\n　　作者一针见血地指出：评论诗词的好坏优劣，应当有自己的见解和主张哪个，而不能像文坛艺苑中的某些人一样，心口雌黄。马克思哲学认为，要做到独具慧眼，深刻地认识、把握事物的本质，一是必须在实践中占有大量的感性材料；而是必须善于对感性材料进行“去粗取精、去伪存真、由此及彼、由表及里”的加工，实现由感性认识上升到理性认识的飞跃和发展。\n\n　　前二句点出在纷纷的艺苑里各种说法鱼龙混杂，这时　需要的是独具慧眼，有自己的视角和观点。当然这是相当不容易的，需要自己有深厚的学养和阅历，成为“高人”。\n\n　　后二句作一形象的比喻，用矮人看戏作比，矮人看戏时被前边的人挡住目光，哪里能看到戏台上的场景?戏散大家一起谈起来时，只能是附和人家的说法。这就好比我们自己对“艺苑”的看法，如果自己学力浅薄，不能“独具只眼”，那就只能“随人说短长”了，这种鹦鹉学舌，拾人牙慧的行为作者是坚决反对的。\n\n　　这首诗继承以诗歌体裁论诗歌的传统，见解卓异，说理畅达。全诗看似佶手拈来、随手而出，但却具有极为精辟深刻的理论内涵。李白、杜甫被称为诗中仙圣，在唐代即受到推崇，如韩愈在仕由逝世时才3岁，后来他熟读李杜诗篇，作有《调张籍》一诗，其中有“李杜文章在，光芒万丈长”“伊我生其后，举颈遥相望”等语，可谓敬佩得五体投地。而后世特别是明清两代，对李杜的崇拜更是前所未有，并且普遍地认为诗自唐以来诗道不振，一代不如一代。甚至有人还提出从《诗经》以来每况愈下、自宋元以来无诗之论，这种看法在明清诗歌理论中占有主导地位。\n\n　　诗人开篇即总论概述了这一普遍现象，以李杜为代表指出了他们的诗作固然光耀千秋，流传万古，其崇高地位与普及程度已是脸炙人家传户诵。接下来却陡然转笔，尖锐地指出了这种情况带来的另外的弊端：熟极而流，不仅令人觉得从内容到形式都没有新意，而且还隐隐含有这一现象在某一程度上阻碍了后世诗人的创新之意，其见解之深刻，笔触之辛辣，思虑之周到，足以发人深省。前两句并非真足在贬低李杜，而是为下文略作铺垫而已，以下即转入主题的抒发。' WHERE poem_title = '论诗五首' AND poem_author = '赵翼';
UPDATE edu_poem SET poem_translation = '怎样合成一个“愁”，是离别之人的心上加个秋。纵然是秋雨停歇之后，风吹芭蕉的叶片，也吹出冷气飕飕。别人都说是晚凉时的天气最好，可是我却害怕登上高楼，那明月光下的清景，更加令我滋生忧愁。\n往昔的种种情事好像梦境一样去悠悠，就像是花飞花谢，就像是滚滚的烟波般向东奔流。群群的燕子已经飞回南方的故乡，只有我这游子还在异地停留。丝丝垂柳不能系住她的裙带，却牢牢地拴住我的行舟。', poem_notes = '心上秋：“心”上加“秋”字，即合成“愁”字。\n飕（sōu）：形容风雨的声音。这里指风吹蕉叶之声。\n年事：指岁月。\n“燕辞归”句：曹丕《燕歌行》：“群燕辞归鹄南翔，念君客游多思肠。慊慊思归悉故乡，君何淹留寄他方。”此用其意。客，作者自指。\n淹留：停留。\n萦：旋绕，糸住。\n裙带：指燕，指别去的女子。', poem_appreciation = '吴文英的这首《唐多令》写的是羁旅怀人。全词字句不事雕琢，自然浑成，在吴词中为别调。\n\n　　就内容而论可分两段，然与此的自然分片不相吻合。\n\n　　“何处合成愁？离人心上秋。纵芭蕉不雨也飕飕。都道晚凉天气好；有明月，怕登楼。年事梦中休，花空烟水流。燕辞归、客尚淹留”为第一段，起笔写羁旅秋思，酿足了愁情，目的是为写别情蓄势。前二句先点“愁”字，语带双关。从词情看，这是说造成这些愁情的，是离人悲秋的缘故，秋思是平常的，说离人秋思方可称愁，单就这点说命意便有出奇制胜之处。从字面看，“愁”字是由“秋心”二字拼合而成，所以此二字又近于字谜游戏。这种手法，古代歌谣中经常可见，王士禛谓此二句为“《子夜》变体”，具“滑稽之隽”（《花草蒙拾》），是道著语。此词以“秋心”合成“愁”字，是离合体，皆入谜格，故是“变体”。此处似乎是信手拈来，涉笔成趣，毫无造作之嫌，且紧扣主题秋思离愁，实不该以“油腔滑调”（陈廷焯《白雨斋词话》卷二）目之。\n\n　　“何处合成愁？离人心上秋。”两句一问一答，开篇即出以唱叹，而且凿空道来，实可称倒折之笔。下句“纵芭蕉不雨也飕飕”是说，虽然没有下雨，但芭蕉也会因飕飕秋风，发出凄凉的声响。这分明想告诉读者，先时有过雨来。而起首愁生何处的问题，正由此处蕉雨惹起。所以前二句即由此倒折出来，平添千回百折之感。秋雨初停，天凉如水，明月东升，正是登楼纳凉赏月的好时候。“都道晚凉天气好”，可谓人云亦云，而“有明月，怕登楼”，才是客子真实独特的心理写照。“月是故乡明”，望月是难免会触动乡思离愁的。这三句没有直说愁，却通过客子心口不一的描写把它充分地表现了。\n\n　　秋属岁未，颇容易使人联想到晚岁。过片就叹息年光过尽，往事如梦。“花空烟水流”是比喻青春岁月的流逝，又是赋写秋景，兼有二义之妙。由此可见客子是长期飘泊在外，老大未回之人。看到燕子辞巢而去，心生无限感慨。“燕辞归”与“客尚淹留”，两相对照，自可见人不如候鸟。以上蕉雨、明月、落花、流水、去燕……虽无非秋景，而又不是一般的秋景，于中无往而非客愁，这也就是“离人心上秋”的具体形象化了。\n\n　　此下“垂柳不萦裙带住，谩长是、系行舟”为第二段，写客中孤寂的感叹。“垂柳”是眼中秋景，而又关离情别事写来承接自然。“萦”、“系”二字均由柳丝绵长思出，十分形象。“垂柳不萦裙带住”一句写的是其人已去，“裙带”二字暗示对方的身份和彼此之间的关系：“谩长是，系行舟”二句是自况，意思是自己不能随去。羁身异乡，又成孤零，本就有双重悲愁，何况离自己而去者又是一位情侣呢。由此方见篇着“离人”二字具有更多一重含意，是离乡又逢离别的人啊，其愁也就更其难堪了。伊人已去而自己既留，必有不得已的理由，却不明说（也无须说），只是埋怨柳丝或系或不系，无赖至极，却又耐人寻味。“燕辞归、客尚淹留”句与此三句，又形成比兴关系，情景相映成趣。\n\n　　全词第一段对于羁旅秋思着墨较多，渲染较详，为后边描写蓄足了力量。第二段写字中怀人，着笔简洁明快，发语恰到好处，毫无拖沓之感。较之作者的其它作品，此词确有其独到之处。', poem_tags = '宋词三百首,宋词精选,婉约,羁旅,孤独,怀人' WHERE poem_title = '唐多令·惜别' AND poem_author = '吴文英';
UPDATE edu_poem SET poem_translation = '当年在华丽的灯光下纵情地博弈，骑着骏马猎射驰骋，谁还记得我当年豪壮的军旅生活？那些无聊酒徒有许多如今都封了官爵，只有我等愿意隐居江边做渔翁。\n江边有八尺轻舟。撑着低低的三扇篷，独自享受长满蘋草的水边景色，镜湖本来就属于像我这样的闲适之人。又何必非要你“官家”赐与不可呢？', poem_notes = '华灯：装饰华丽的灯台。\n纵博：纵情赌博。此处视为豪爽任侠的一种行为表现。《剑南诗稿》卷二十五《九月一日夜读诗稿有感走笔作歌》：“四十从戎驻南郑，酣宴军中夜连日……华灯纵博声满楼，宝钗艳舞光照席。……”\n酒徒：犹言市井平民，普通人。《史记》卷九十七《郦生陆贾列传》：“郦生嗔目案剑叱使者曰：走，复入言沛公！吾高阳酒徒也，非儒人也。”\n渔父：渔翁，打鱼的老人。\n占断：完全占有。\n蘋洲：丛生苹草的小河。\n镜湖：在浙江会稽、山阴两县交界处，周遭三百余里，以水平如镜而出名。\n闲人：作者自称，乃愤激之辞。\n官家赐与：唐开元间，诗人贺知章告老还乡到会稽，唐玄宗诏赐镜湖剡溪一曲。陆游反用其典，表达自己的不满之情。官家，指皇帝，此处明指唐玄宗，实指当时的南宋皇帝。', poem_appreciation = '“华灯纵博，雕鞍驰射，谁记当年豪举。”开篇就追忆往事，发表感慨。这两句采用倒叙手法，回忆“当年”旧事。从“华灯纵博，雕鞍驰射”两个对偶句，知所谓当年是指在南郑从军一段时期。他对这一时期的“豪举”生活，印象极为深刻，后来多次见于吟咏。这是因为：一、他亲自到了接近国防前线的地区，接触许多激动人心的场景，如射猎、检阅、韩信拜将坛、武侯祠庙，登高远望长安诸山，义士冒死驰递情报等等。二、扩展了视野，丰富了生活，激发了爱国热情，获得了大量的创作题材，奠定了“诗外功夫”的理论。完全可以说，南郑从军，对他的诗歌艺术具有划时代的意义。他曾有诗说：“华灯纵博声满楼，宝钗艳舞光照席。”“分骑霜天伐狐兔，张灯雪夜掷枭卢。”前两句辞采华丽，极具象征意义，将当年南郑从戎时期，词人与同僚纵情欢赌、策马射猎的生活场景重现。此处赌博并无贬义，突显的恰是一掷千金的豪爽性格。“谁记”二字转折强烈，写华年消逝、世事变迁之后，还有谁记得当年的豪情壮志。\n\n　　“酒徒一半取封侯，独去作江边渔父。”这两句紧承“谁记”领起的转折，想过去，叹今朝。从此，下文分向“低沉”和“开朗”两方面开拓。封侯、渔父，是两种截然不同的人生遭遇，荣辱升沉，各有畔岸。“酒徒”是普普通通的平凡之人，暗用刘邦时策士郦生故事，在这儿是指原来和自己比肩而后来逐渐爬上去的达官贵人（如范成大、周必大都位至宰执）。当年与自己一起饮酒的人，至少有一半已经封侯进爵，可是自己却落得病老乡里，成了一个靠打渔为生的衰老渔夫。这里只作说明，并不见褒贬或感叹的痕迹。但也不禁使人发问：那些酒徒，是怎样取得封侯的，自己又为什么落拓江湖甘心去做钓徒渔父，但这不是作论文，为艺术法则所制约，不能说，也不必说了。诗词语者，有它的特色，留有余味，让读者自去咀嚼和解答，这就是“言有尽而意无穷”的妙处。“独”字突显出孤家寡人、顾影自怜之意。把成为“渔父”的自己置于“封侯者”之中，对比鲜明，写出陆游仕途的坎坷失意。还应看到，去做渔父，有他的天惠条件，门前宅旁，江湖满地，烟水迷离，是渔父生涯最理想的环境。无怪他在词作里常常提列。此篇而外，如《渔歌子》五首、《鹊桥仙·一竿风月》、《长相思》五首，都是歌颂渔钓生活的清丽超爽之作。诚然，这里也许微寓《楚辞·渔父》“举世皆浊而我独清”的惋叹。\n\n　　下阕紧承“渔父”二字，从小船写起。“轻舟八尺，低篷三扇”，八尺长的轻小舟船，只有三扇低矮的蓬窗，恐怕只能容下词人一人。但是，词人却说它“占断蘋洲烟雨”，别有新致。表现出词人对渔钓生活的喜爱。“占断颇洲烟雨”，情景交融，韵味殊胜。蘋洲之上，烟雨迷蒙，水云之乡，为自己独占．逍遥容与，可以尽情领略心境何等旷远。况周颐说：“善言情者，但写景而情在其中。”只此一句，抵得张志和全篇《渔歌子》，此可视为“当年豪举”在意境上的升华。在广阔的湖面这一背景中，相较于“轻舟”之小，湖水简直可称大而无当，如此轻巧纤弱的一叶扁舟，绝对不可能占尽风雨，唯词人胸怀宽广能为之。通过这样鲜明的对比，词人言明渔钓生活已成为自己的精神栖所。\n\n　　“镜湖元自属闲人，又何必官家赐与。”这两句引贺知章的典故。贺知章是会稽人，为官为文都很成功，天宝年间自请归乡为道士，唐玄宗特赐封地。这两句中，词人用略带嘲讽的口吻，打趣贺知章受皇恩所赐得以清闲归乡，实是用以自嘲，嘲笑自己衰鬓残年尚寸功未立。虽有怨念，但词人不仅把这种情怀表达得十分平淡，还显得英气凛然，可能是其晚年心境愈发冲和的缘故。\n\n　　后人论辛、陆诗词，谓“时时掉书袋．要是一癖”。其实用事只要贴切自然，没有什么不可以。近代词人、词论家况周颐指出必欲得天然妙语，“其道有二。曰性灵流露，曰书卷酝酿。”可谓知言。杨慎评此作：“英气可掬，流落亦可惜矣！”杨慎于此拈出“英气”二字．丁消沉遁世的基调中看到开朗超拔的一面，具见法眼。在任何时代，作为一个诗人的气质来说，这种“英挺之气”断不可少。这是在品格和艺术创作中的间架和脊梁。\n\n　　全词用笔蕴蓄，颇见炼字炼句之功。如开头只用八个字，就概括了南郑从军多方而的“豪举”。“酒徒”二句，指出持身不同，遭逢各异，亦自言外有意。“占断”一句，只用六字，诗情画意，境界全出。正如赵翼所说：“放翁功夫精到，出语自然老洁，他人数言不能了者，只在一二语了之。”若姚范说他“苍黯蕴蓄之风盖微”，并非公允之论。\n\n　　另外，此词虽用了一半篇幅描绘渔父生涯，但陆游与张志和一类烟波钓徒全然不同。被迫投闲的渔父即使表面上再潇洒悠闲，骨子里仍是时时不忘“当年豪举”的爱国志士。正是这股内在的豪纵之气，贯注于全词，便在字里行间和转折推进中流露了一种强烈的不平、怨愤、牢骚和孤傲，而词中“谁记”、“独去”、“占断”、“元自”、“何必”等词语，则在表现上述感情方面起了重要作用。', poem_tags = '宋词三百首,追忆,生活,壮志' WHERE poem_title = '鹊桥仙·华灯纵博' AND poem_author = '陆游';
UPDATE edu_poem SET poem_tags = '婉约,写景,抒情' WHERE poem_title = '菩萨蛮·绿芜墙绕青苔院' AND poem_author = '陈克';
UPDATE edu_poem SET poem_tags = '写景,山水,喜爱,赞美' WHERE poem_title = '江城子·前瞻马耳九仙山' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '孤零零旅舍灯光青冷，厌听这荒野鸡鸣，收拾起旅枕残梦。晓月渐渐淡去了白绢似的皎洁，微亮的晨霜一片晶莹；山上云白如展开的锦缎，朝露点点与晨光辉映。人世间的行程没个尽头，有限的是这劳顿的人生。似这般无足称道的平庸，难得有欢愉的心境。我这里独自低吟罢，征鞍上，悄无声，许多往事涌心中。\n当年我们风华正茂，同时客居在汴京，如同陆机、陆云兄弟，初到京城还年轻。幸有妙笔在手文思敏捷，诗书万卷在胸，自以为辅佐圣上使其成为尧舜，该是星月同辉，事业必成。其实重用与否在于时势，入世出世须由自己权衡。不妨闲处袖手看风云，少不得那分明哲与淡定。好在你我身体康健，只须终年悠闲游乐，姑且杯中寻醉慰平生。', poem_notes = '沁园春：词牌名，又名《寿星明》、《洞庭春色》等。双调一百十四字，平韵。\n孤馆：寓居客舍住的人很少。灯青：点着灯起床，灯发着青光。\n野店鸡号：说明走得早。野，村落。\n旅枕：喻旅店的睡眠。\n月华收练：月光像白色的绢，渐渐收起来了。\n耿耿：明亮的样子。\n摛（chī）锦：似锦缎展开。形容云雾缭绕的山峦色彩不一。\n溥溥（tuán）：露多的样子。一说为露珠圆的样子。\n世路：人世的经历。\n劳生：辛苦、劳碌的人生。\n区区：渺小，这里形容自己的处境不顺利。鲜，少。\n微吟：小声吟哦。\n凭征鞍：站在马身边。词题小序说“马上”，作者骑着马行进。\n千端：千头万绪，犹言多。\n共客长安：兄弟二人嘉佑间客居沐京应试。长安，代指汁京。\n二陆：指西晋文学家陆机、陆云兄弟。少年，年纪轻。\n笔头千字：即下笔千言之意。\n胸中万卷：胸中藏有万卷书。形容读书很多，学识渊博。\n致君：谓辅佐国君，使其成为圣明之主。\n行藏（cáng），意为被任用就出仕，不被任用就退隐。\n袖手：不过问。\n优游卒岁：悠闲地度过一生。\n且斗尊前：犹且乐尊前。斗，喜乐戏耍之词。尊，酒杯。', poem_tags = '议论,抒怀,人生' WHERE poem_title = '沁园春·孤馆灯青' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '天下最伤心的地方，就是这送别的劳劳亭。\n春风也会意离别的痛苦，不催这柳条儿发青。', poem_notes = '劳劳亭：在今南京市西南，古新亭南，为古时送别之所。《景定建康志》：劳劳亭，在城南十五里，古送别之所。吴置亭在劳劳山上，今顾家寨大路东即其所。《江南通志》：劳劳亭，在江宁府治西南。\n知：理解。\n遣：让。', poem_appreciation = '此诗的前两句“天下伤心处，劳劳送客亭”，诗人以极其洗练的笔墨、高度概括的手法，破题而入，直点题旨。单就句意而言，这两句就是屈原《楚辞·九歌·少司命》所说的“悲莫悲兮生别离”和江淹《别赋》所说的“黯然销魂者，唯别而已矣”。但诗人既以亭为题，就超越一步、透过一层，不说天下伤心事是离别，只说天下伤心处是离亭。这样直中见曲，越过了离别之事来写离别之地，越过了送别之人来写送别之亭，立言就更高妙，运思就更超脱。而读者自会因地及事，由亭及人。\n\n　　不过，这首诗的得力之处却非上面这两句，而是它的后两句。在上两句诗里，诗人为了有力地展示主题、极言离别之苦，指出天下伤心之地是离亭，也就是说天下伤心之事莫过于离别，已经把诗意推到了高峰，似乎再没有什么话好说，没有进一步盘旋的余地了。如果后两句只就上两句平铺直叙地加以引伸，全诗将纤弱无力，索然寡味。而诗人才思所至，就亭外柳条未青之景，陡然转过笔锋，以“春风知别苦，不遣柳条青”这样两句，别翻新意，另辟诗境。\n\n　　这一出人意表的神来之笔，出自诗人的丰富联想。《文心雕龙·物色篇》说：“诗人感物，联类不穷。”诗思往往是与联想俱来的。诗人在构思时，要善于由甲及乙，由乙及丙。联类越广，转折和层次越多，诗篇就越有深度，也越耐人寻味。王之涣的《送别》诗“杨柳东风树，青青夹御河。近来攀折苦，应为别离多”，也是从杨柳生意，构思也很深曲；但就诗人的联想而言，只不过因古时有杨柳送别习俗，就把送别与杨柳这两件本来有联系的事物联系在了一起，而诗中虽然说到杨柳是“东风树”，却没有把送别一事与东风相联。李白的这两句诗却不仅因送别想到折柳，更因杨柳想到柳眼拖青要靠春风吹拂，从而把离别与春风这两件本来毫不相干的事物联在了一起。如果说王诗的联想还是直接的，那么李诗的联想则是间接的，其联想之翼就飞得更远了。\n\n　　应当说，在古代诗歌中，从送别写到折柳，在从折柳写到春风的诗，并非绝无仅有。杨巨源的《折杨柳》诗“水边杨柳曲尘丝，立马烦君折一枝。惟有春风最相惜，殷勤更向手中吹”，写得也具见巧思，但与李白这两句相比，就显得巧而不奇。李白的这两句诗是把联想和奇想结合为一的。诗人因送别时柳条未青、无枝可折而生奇想，想到这是春风故意不吹到柳条，故意不让它发青，而春风之所以不让柳条发青，是因为深知离别之苦，不忍看到人间折柳送别的场面。从诗人的构思说，这是联想兼奇想；而如果从艺术手法来说，这是托物言情，移情于景，把本来无知无情的春风写得有知有情，使它与相别之人同具惜别、伤别之心，从而化物为我，使它成了诗人的感情化身。\n\n　　与李白的这首诗异曲同工、相映成趣的有李商隐的《离亭赋得折杨柳二首》之一：\n\n　　暂凭樽酒送无憀，莫损愁眉与细腰。\n\n　　人世死前惟有别，春风争似惜长条。\n\n　　对照之下，两诗都以离亭为题，都是从离别想到杨柳，从杨柳想到春风，也都把春风写得深知离别之苦，对人间的离别满怀同情。但两诗的出发点相同，而结论却完全相反：李白设想春风因不愿见到折柳送别的场面而不让柳条发青；李商隐却先说送别之人不忍折损杨柳的枝叶，再设想春风为了让人们在临别之时从折柳相赠中表达一片情意，得到一点慰藉，而不惜柳条被人攀折。这说明，同一题材可以有各种不同的构思、不同的写法。诗人的想象是可以自由飞翔的，而想象的天地又是无限广阔的。', poem_tags = '送别,离别,借景抒情' WHERE poem_title = '劳劳亭' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '汉文帝后元六年，匈奴大规模侵入汉朝边境。于是，朝廷委派宗正官刘礼为将军，驻军在霸上；祝兹侯徐厉为将军，驻军在棘门；委派河内郡太守周亚夫为将军，驻军细柳，以防备匈奴侵扰。\n\n　　皇上亲自去慰劳军队。到了霸上和棘门的军营，驱驰而入，将军及其属下都骑着马迎送。随即来到了细柳军营，只见官兵都披戴盔甲，手持锋利的兵器，开弓搭箭，弓拉满月，戒备森严。皇上的先行卫队到了营前，不准进入。先行的卫队说：“皇上将要驾到。”镇守军营的将官回答：“将军有令：‘军中只听从将军的命令，不听从天子的命令。’”过了不久，皇上驾到，也不让入军营。于是皇上就派使者拿符节去告诉将军：“我要进营慰劳军队。”周亚夫这才传令打开军营大门。守卫营门的官兵对跟从皇上的武官说：“将军规定，军营中不准驱车奔驰。”于是皇上的车队也只好拉住缰绳，慢慢前行。到了大营前，将军周亚夫手持兵器，双手抱拳行礼说：“我是盔甲在身的将士，不便跪拜，请允许我按照军礼参见。”皇上因此而感动，脸上的神情也改变了，俯身扶着横木上，派人致意说：“皇帝敬重地慰劳将军。”劳军礼仪完毕后辞去。\n\n　　出了细柳军营的大门，许多大臣都深感惊诧。文帝感叹地说：“啊！这才是真正的将军。先前的霸上、棘门的军营，简直就像儿戏一样，匈奴是完全可以通过偷袭而俘虏那里的将军，至于周亚夫，岂是能够侵犯他吗？”长时间对周亚夫赞叹不已。', poem_notes = '文帝：汉高祖刘邦之子刘恒，公元前180至公元前157年在位。吕后死后，周勃等平定诸吕，他以代王入为皇帝。在位期间，执行“与民休息”的政策，减轻地税、赋役和刑狱，使农业生产有所恢复发展，又削弱诸侯势力，以巩固中央政权。旧史家把他与景帝统治时期并举，称“文景之治”。 后六年，即后元六年（公元前158年）。\n匈奴：我国古代北方的游牧民族。入边，侵入边境。\n宗正：官名，负责皇族内部事务的长官，由皇族担任。\n军：驻军。\n霸上：古地名，一作灞上，又名霸头，因地处霸水西高原上得名，在今陕西西安市东。\n祝兹侯：封号。\n棘门：原为秦宫门，在今陕西咸阳东北。\n河内：郡名，今河南北部地区。守，郡的行政长官。\n细柳：古地名，在今陕西省咸阳西南，渭河北岸。 备：防备\n上：指汉文帝。\n被：通“披”。指穿。\n彀(gòu）：张满弓。弩（nǔ）：一种用机械力量射箭的弓，泛指弓。\n持满：把弓弦拉足。\n军门都尉：守卫军营的将官，职位略低于将军。\n节：符节，皇帝给的凭证。\n壁门：营门。车骑：汉代将军的名号。\n按：控制。辔：马缰绳。徐：慢慢地。\n持兵揖：手持兵器作揖。揖，双手抱拳行礼。\n介：铁甲；胄：头盔。为：被。\n式车：在车上俯身扶着车前的横木，表示尊敬。式，车前的横木，现在写作“轼”。\n谢：告知。\n曩：（nǎng）以往，从前，过去。\n将：将领。\n动：感动\n改容：改变神情。\n\n通假字\n军士吏被甲 被通披：披在身上\n改容式车 式通轼：车前的横木\n可得而犯邪　邪通耶：语气助词', poem_tags = '故事,赞颂,将军' WHERE poem_title = '周亚夫军细柳' AND poem_author = '司马迁';
UPDATE edu_poem SET poem_translation = '元宵节时，到处都能碰到女人们穿着盛装，化着美好的妆容来看灯；小孩子们则在街道上欢闹着。\n我这个穿朴素长衫的读书人做什么呢？也在游人欢声笑语的气氛中赏灯猜谜。', poem_notes = '京都：指汴京。今属河南开封。\n元夕：元宵，正月十五日晚上。\n袨（xuàn)服：盛服，艳服，漂亮的衣服。\n华妆：华贵的妆容。\n着处：到处。\n闹：玩耍嬉闹。\n长衫：读书人多穿着长衫。\n何为：为何，做什么。', poem_tags = '元宵节,游玩' WHERE poem_title = '京都元夕' AND poem_author = '元好问';
UPDATE edu_poem SET poem_translation = '最近也是最远的是东与西，最深也是最浅的是清溪。\n最高也是最明的是日和月，最亲也是最疏的是夫妻。', poem_notes = '至：最。八至：此以诗中有八个“至”字为题。\n东西：指东、西两个方向。\n疏：生疏，关系远，不亲近。', poem_tags = '哲理' WHERE poem_title = '八至' AND poem_author = '李冶';
UPDATE edu_poem SET poem_translation = '垂钓归来，却懒得把缆绳系上，任渔船随风飘荡；而此时残月已经西沉，正好安然入睡。\n即使夜里起风，小船被风吹走，大不了也只是停搁在芦花滩畔，浅水岸边罢了。', poem_notes = '即事：以当前的事物为题材所做的诗。\n罢：完了；系：系好。不系船：《庄子》曰“巧者劳而智者忧，无能者无所求，饱食而遨游，泛若不系之舟”，即以“不系之舟”为无为思想的象征。\n正堪眠：正是睡觉的好时候；堪：可以，能够。\n纵然：即使。', poem_appreciation = '此诗载于《全唐诗》卷二九二。诗写江村眼前事情，但诗人并不铺写村景江色，而是通过江上钓鱼者的一个细小动作及心理活动，反映江村生活的一个侧面，写出真切而又恬美的意境。\n\n　　“钓罢归来不系船”，首句写渔翁夜钓回来，懒得系船，而让渔船任意飘荡。“不系船”三字为全诗关键，以下诗句全从这三字生出。“江村月落正堪眠”，第二句上承起句，点明“钓罢归来”的地点、时间及人物的行动、心情。船停靠在江村，时已深夜，月亮落下去了，人也已经疲倦，该睡觉了，因此连船也懒得系。但是，不系船可能对安然入睡会有影响。这就引出了下文：“纵然一夜风吹去，只在芦花浅水边。”这两句紧承第二句，回答了上面担心的问题。“纵然”“只在”两个关联词前后呼应，一放一收，把意思更推进一层：且不说夜里不一定起风，即使起风，没有缆住的小船也至多被吹到那长满芦花的浅水边，也没有什么关系。这里，诗人并没有刻画幽谧美好的环境，然而钓者悠闲的生活情趣和江村宁静优美的景色跃然纸上，表达了诗人对生活随性的态度。\n\n　　这首小诗善于以个别反映一般，通过“钓罢归来不系船”这样一件小事，刻画江村情事，由小见大，就比泛泛描写江村的表面景象要显得生动新巧，别具一格。诗在申明“不系船”的原因时，不是直笔到底，一览无余，而是巧用“纵然”“只在”等关联词，以退为进，深入一步，使诗意更见曲折深蕴，笔法更显腾挪跌宕。诗的语言真率自然，清新俊逸，和富有诗情画意的幽美意境十分和谐。', poem_tags = '写景,乡村,生活' WHERE poem_title = '江村即事' AND poem_author = '司空曙';
UPDATE edu_poem SET poem_translation = '往事回想起来，只令人徒增哀叹；即便面对多么美好的景色，也终究难以排遣心中的愁苦。秋风萧瑟，冷落的庭院中，爬满苔藓的台阶，触目可见。门前的珠帘，任凭它慵懒地垂着，从不卷起，反正整天也不会有人来探望。\n横江的铁锁链，已经深深地埋于江底；豪壮的气概，也早已付与荒郊野草。傍晚的天气渐渐转凉，这时的天空是那样的明净，月光毫无遮拦地洒满秦淮河上。', poem_notes = '藓侵阶：苔藓上阶，表明很少有人来。\n一任：任凭。吴本、吕本、侯本《南唐二主词》、《花草粹编》作“一行”。《续选草堂诗余》、《古今词统》作“一片”。粟本《二主词》、《历代诗余》、《全唐诗》作“桁（héng）”。一桁：一列，一挂。如杜牧《十九兄郡楼有宴病不赴》：“燕子嗔重一桁帘。”\n终日谁来：整天没有人来。\n金锁：即铁锁，用三国时吴国用铁锁封江对抗晋军事。或以为“金锁”即“金琐”，指南唐旧日宫殿。也有人把“金锁”解为金线串制的铠甲，代表南唐对宋兵的抵抗。众说皆可通。锁：萧本、晨本《二主词》作“琐”。侯本《南唐二主词》、《花草粹编》、《词综》、《历代诗余》、《全唐诗》作“金剑”。《续选草堂诗余》、《古今词统》作“金敛”。《古今词统》并注：“敛，一作剑。”按：作敛不可解，盖承“金剑”而误。\n已：《草堂诗余续集》、《古今词统》作“玉”。《古今词统》并注：“玉，一作已。\n”蒿莱：蒿莱，借指野草、杂草，这里用作动词，意为淹没野草之中，以此象征消沉，衰落。\n净：吴讷《百家词》旧抄本、吕本、侯本、萧本《南唐二主词》、《花草粹编》、《词综》、《续集》、《词综》、《全唐诗》俱作“静”。\n秦淮：即秦淮河。是长江下游流经今南京市区的一条支流。据说是秦始皇为疏通淮水而开凿的，故名秦淮。秦淮一直是南京的胜地，南唐时期两岸有舞馆歌楼，河中有画舫游船。', poem_appreciation = '起句“往事只堪哀”，将全篇基调定出，并凝结到一个“哀”字上。这“哀”是如此深重，以至于“对景难排”。本来“对景难排”就在说无人可以倾诉，只好独自面对景物，希望能作排遣，在诉说哀痛深重的同时，已有孤独之意。由此拈出“难”，是说孤苦之深，面对景物也无法排遣。更接以“秋风庭院藓侵阶”，用苔藓满地写无人造访，用庭院秋风写空旷凄凉，景色已然寂寞，孤苦唯见深重。这样便将人的孤独写得很具体，很形象，那内心的哀伤，非但是“难排”，“对景”更是徒然增痛而已。时当秋天，是枯索萧瑟之季；身在庭院，有高墙围困之难。而在这小院中，秋风吹过，树叶黄落，唯一的绿色就是蔓延生长的苔藓，那层暗绿一直爬到了进入堂室的台阶上，看着令人心酸。刘禹锡的《陋室铭》有“苔痕上阶绿，草色入帘青”的名句，表现高逸脱俗的文人雅趣。这里写苔藓，是说生活的孤寂，在寒瑟的秋天虽然有这一点绿色，却是长年没有人行走的痕迹，尤增悲哀。于是作者“一任珠帘闲不卷”，既然“终日”都无人来。“一桁”写索性，不是痛快的豪放，而是无奈的放弃。“闲”写门帘长垂的状态，实指自己百无聊赖的生活处境，既不是“一帘风月闲”（《长相思》）的悠闲，也不是“同醉与闲平，诗随羯鼓成”（《菩萨蛮》）的闲散。上片就眼前景物而写孤苦的凄凉心境。\n\n　　下片转折而起，以“金锁已沉埋，壮气蒿莱”悲悼国家破灭、身陷为虏的遭遇。想当年，身为君主，群臣俯首，宫娥簇拥，有过颐指气使的威严，有过春花雪月的风流，而所有的繁华与富贵都一起随着金陵的陷落而烟消云散，化为了乌有。此时徘徊庭院，往事无限，看秋夜天高，秋月澄明，那金陵城中，“雕栏玉砌应犹在”，却不再是往日的气象。南唐已破灭，君主成囚虏，秋月还是那轮秋月，只是“空照秦淮”而已。这里的“玉楼瑶殿影”，可以分作两层理解。第一层是指秦淮河边的旧时宫苑，映照在月光下，投影在河水中，却是有楼影而无人影，重在一个“照”字。第二层是指神话传说中的月宫，华丽壮观却虚无缥缈，就像此刻记忆中的故国宫苑，重在一个“空”。就第一层讲，作者是凭着想象回到旧地，就第二层讲，则作者是在当地望月而遥寄哀思。这两层意思就将一人而两地的情思通过一轮秋月糅合到一起，“空照”不仅在秦淮的楼阁，也在汴京的人一心。“空照”的感受中有无尽的心酸与哀苦。\n\n　　这首词写当前的孤寂，与往日的繁华相对，不过不是直接道出，而是借景抒情。上片景色“秋风庭院藓侵阶”，写得寒瑟凄惨；下片景色“晚凉天净月华开”，虽然清冷，却是一片澄明。这两处景色，一明一暗，又一在白日，一在夜晚，就构成了双重的联系。在格调上是现在与过去的对比，在时间上则是日以继夜的相承。因此，“对景难排”不仅是说眼前景，而且是指所有的景物，无论四季，无论日夜，都不能为孤苦的作者排遣悲哀，不说“往事只堪哀”，用其他的话也是无法表达出悲哀的。', poem_tags = '追怀,帝王,生活' WHERE poem_title = '浪淘沙·往事只堪哀' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '我们的部队于兰圃休息，在青草丰茂的山坡喂马，在水边的原野用石弹（磻）打鸟，在长河里钓鱼。一边目送着南归的鸿雁，一边信手挥弹五弦琴。一举一动都悠然自得。对大自然的奥妙之道能够心领神会，十分快乐！不禁赞赏《庄子》中那位渔翁捕到了鱼，忘掉了筌（捕鱼工具）的风神。（以上几句委婉地劝谕其兄归隐田园，享受大自然的乐趣，放弃军旅生活。）同心同德的郢人已经死了，这些话跟谁多说了都没用。（作者担心嵇喜与他志趣相异，难以接受其劝谕，表示惋惜。）', poem_notes = '兰圃：有兰草的野地。\n秣马：饲马。\n磻（音波）：用生丝做绳系在箭上射鸟叫做弋，在系箭的丝绳上加系石块叫做磻。皋：水边地。这句是说在皋泽之地弋鸟。\n纶：指钓丝。\n五弦：乐器名，似琵琶而略小。\n太玄：就是大道。“游心太玄”，是说心中对于道有所领会，也就是上句“自得”的意思。\n筌：捕鱼竹器名。《庄子·外物》道：“筌者所以在鱼，得鱼而忘筌。”又道：“言者所以在意，得意而忘言。”“得鱼忘筌”是“得意忘言”的比喻，说明言论是表达玄理的手段，目的既达，手段就不需要了。\n郢：古地名，春秋楚国的都城。', poem_tags = '古诗三百首,想象,行军,抒情' WHERE poem_title = '赠秀才入军·其十四' AND poem_author = '嵇康';
UPDATE edu_poem SET poem_appreciation = '四印斋本《漱玉词补遗》题此词作“咏桐”，似未切。纵观全篇，这应是一首借景抒情之作。尽管因为难以考证它的作年，我们无法准确把握作者挥毫濡翰时的情境和心绪，因而也无法深究作者所抒之情的底蕴是黍离之悲还是相思之苦，但作者抒情的真挚程度却足以使我们受到感染，而不著痕迹地显现于其中的高超技巧也足以令我们折服。\n\n　　词的上篇写登楼的所见所闻。在一个秋天的傍晚，作者怀着“剪不断，理还乱”的愁思，缓步登临高阁，凭栏远眺。跃入她眼帘的竟是那样一番衰飒、悲凉的景象：缭乱的群山，平旷的原野，惨淡的烟光，以及聒噪着归巢的昏鸦。它们拼合为一幅令人伤心惨目的秋晚眺望图。有图若此，难堪已极，而作者偏偏还要为它配上撼人心魄的画外音——那在暮色中久久回荡的悲壮的号角声。号角声，不仅将作者的情思带入更寥廓的空间，而且为我们提供了捕捉作者情思的线索。由这作为背景之一的悲壮的号角声，我们无妨推测那是靖康之变发生后的兵荒马乱岁月。既然如此，联系作者靖康之变后亡国、丧失、贫病交加、流离失所的遭遇，似乎可以断言，渗透在这幅秋晚眺望图中的是一种揉合着国仇家恨的浑灏苍茫的忧伤之情。其实，秋景本不当这般萧瑟，只因为“伤心人别具眼目”，才在作者笔下萧瑟若此。以情役景，景因情设，这本是诗词家的惯伎。正因为这样，刘禹锡在《秋词》中用“晴空一鹤排云上，便引诗情到碧霄”的壮阔之景来表现志士的豪情，王维在《山居秋暝》中用“明月松间照，清泉石上流”的清丽之景来表现隐者的雅致，而李清照则在此词中用“乱山平野烟光薄。烟光薄。栖鸦归后，暮天闻角”这样的萧瑟之景来表现她的忧思，从中，我们似乎也可悟出些“诗家三昧”。\n\n　　词的下片写登楼所思所感。如果比较上下片在章法、技巧方面的异同，我们可以清楚地看到：同样表现为情与景的有机交融，但上片着重写景，而景中有情，下片则着重抒情，而情中有景。“断香”句，作者的视线由阁外移到阁中。一如“乱山平野烟光薄”，这撩人眼目、乱人情思的“断香残酒”，勾起作者闲愁万种，使她更加难以为怀，乃至一反固有的婉曲作法，于百般无奈中吐出“情怀恶”这样的直抒胸臆之语。“东风”句再度将视野拓开，摄下桐叶随风飘坠的特写镜头。这纷纷飘坠的桐叶，猛烈扣响了颤动在作者内心的生命之弦，使她情不自禁地联想到：在走完一大段痛苦和欢乐相伴、灾难与幸福相继的人生旅程后，自己岂不也到了飘坠、凋零的岁月？“梧桐落”三字的有意重复，虽然主要是为服从词律，却也昭示着我们：这一衰歇景象，给予作者怎样深刻的感受，又引起她内心怎样的强烈反响！“又还秋色，又还寂寞”两句便以作者的感受和反响作结。“又还”，表明作者因历览秋色而更感寂寞已非一遭，很难判断她这是第几回逢秋而悲。这就在相当程度上增加了抒情的广度和深度。细绎全词，画面是那样惨淡、萧飒，情感又是那样凝重、沉痛，与作者早期那些抒写相思之情的哀婉却不失明丽的词作有着不同的韵味，因而视之为后期的作品，或许并无武断之嫌。', poem_tags = '咏物,登高,伤怀' WHERE poem_title = '忆秦娥·咏桐' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '傍晚夕阳斜照，微风吹过湖面，蝉鸣不歇。夜晚降临，颗颗清露点缀在红莲之上，煞是可爱。停留片刻后骑马赶赴即将开始的酒宴。\n离别之酒请不要推辞，让我们开怀畅饮。入朝为官就像靠近玉炉中的熏香让人心中欢畅，只是至此一别不知何时才能再欢聚一堂。', poem_notes = '歌筵：有歌者唱歌劝酒的宴席。\n为别：犹分别，相别。\n莫辞：不要推辞。\n入朝：谓进入中央朝廷做官。\n须：必得，应当。', poem_tags = '写景,宴会,抒怀,离别' WHERE poem_title = '浣溪沙·湖上西风急暮蝉' AND poem_author = '晏殊';
UPDATE edu_poem SET poem_translation = '谁能看得懂西湖的美丽？西湖任何时候都是美景。驱车去追寻。只愿在花丛绿树中饮酒贪欢。\n谁知道随意站立在那水气交错的迷离之中，绿草斜阳正美。水波幽远，烟雾飘渺，白鹭飞来，仿佛水滨之间只有一点。', poem_notes = '采桑子：词牌名，又名“丑奴儿令”、“罗敷艳歌”、“罗敷媚”。四十四字，前后片各三平韵。\n飞盖相追：化用曹植《公讌》诗：“清夜游西园，飞盖相追随。”盖：车篷；飞盖指奔驰的马车。\n玉卮：玉做的杯子。卮：饮酒的圆形器皿。\n阑干：“阑干”最早指一种竹子木头或者其他东西编织的一种遮挡物。后来就引申为纵横交错的样子，这里指水气交错的样子。\n晖：阳光。\n沧洲：水边的陆地。', poem_tags = '写景,写水,西湖' WHERE poem_title = '采桑子·何人解赏西湖好' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '泪水湿透了罗巾无法入睡好梦难成，深夜时分听到前殿传来按着节拍唱歌的声音。红颜尚未老去已经失去了君王的恩宠，斜靠着熏笼一直坐到天明。\n\n韵译\n泪水湿透罗巾，好梦却难做成；\n深夜，前殿传来有节奏的歌声。\n红颜尚未衰减，恩宠却已断绝；\n她独倚着熏笼，一直坐到天明。', poem_notes = '宫词：此诗题又作《后宫词》。\n按歌声：依照歌声的韵律打拍子。\n红颜：此指宫宫女。\n恩：君恩。\n熏笼：覆罩香炉的竹笼。香炉用来熏衣被，为宫中用物。', poem_appreciation = '诗的主人公是一位不幸的宫女。她一心盼望君王的临幸而终未盼得，时已深夜，只好上床，已是一层怨怅。宠幸不可得，退而求之好梦；辗转反侧，竟连梦也难成，见出两层怨怅。梦既不成，索性揽衣推枕，挣扎坐起。正当她愁苦难忍，泪湿罗巾之时，前殿又传来阵阵笙歌，原来君王正在那边寻欢作乐，这就有了三层怨怅。倘使人老珠黄，犹可解说；\n\n　　偏偏她盛鬓堆鸦，红颜未老，生出四层怨怅。要是君王一直没有发现她，那也罢了；事实是她曾受过君王的恩宠，而现在这种恩宠却无端断绝，见出五层怨怅。夜已深沉，濒于绝望，但一转念，犹翼君王在听歌赏舞之后，会记起她来。于是，斜倚熏笼，浓熏翠袖，以待召幸。不料，一直坐到天明，幻想终归破灭，见出六层怨怅。一种情思，六层写来，尽缠绵往复之能事。而全诗却一气浑成，如笋破土，苞节虽在而不露；\n\n　　如茧抽丝，幽怨似缕而不绝。短短四句，细腻地表现了一个失宠宫女复杂矛盾的内心世界。夜来不寐，等候君王临幸，写其希望；听到前殿歌声，君王正在寻欢作乐，写其失望；君恩已断，仍斜倚熏笼坐等，写其苦望；天色大明，君王未来，写其绝望。泪湿罗巾，写宫女的现实；求宠于梦境，写其幻想；恩断而仍坐等，写其痴想；坐到天明仍不见君王，再写其可悲的现实。全诗由希望转到失望，由失望转到苦望，由苦望转到最后绝望；由现实进入幻想，由幻想进入痴想，由痴想再跌入现实，千回百转，倾注了诗人对不幸者的深挚同情。', poem_tags = '唐诗三百首,宫怨' WHERE poem_title = '后宫词' AND poem_author = '白居易';
UPDATE edu_poem SET poem_appreciation = '此诗题为《梅花》，却不是一首咏物诗，而是咏叹与梅花相关的人和事。据《全唐诗》载：“后主尝与周后移植梅花于瑶光殿之西，及花时，而后已殂，因成诗见意。”\n\n　　此诗首联起句“殷勤移植”语，即指这次移植梅花之事；“移植地”便是“瑶光殿之西”的“曲槛小栏边”。李煜、周后（即昭惠皇后）都是极富雅趣之人，又凭着帝王皇后的特殊条件，便为自己的生活极力营造出优美的氛围。他们以销金红罗罩壁，以绿钿刷丝隔眼，糊以红罗，种梅花其外，兴之所至，便有了移植梅花之事。颔联写道“共约重芳日，还忧不盛妍”，意思是记得当时还曾担心，梅花“重芳日”，只恐“不盛妍”。唯其如此，颈联便接着说：“阻风开步障，乘月溉寒泉。”为了给梅花“阻风”，这两位形影相随的伴侣还特意为梅花牵开了漂漂亮亮、长长宽宽的“步障”；为了给梅花浇水，也还曾不辞“乘月”披星之劳。实指望来年能观赏到夫妻共同移植、一块浇灌的梅花的艳美风姿。可是，又有谁能料到花开前后，这正该供夫妻共赏同乐的美景良辰，而“蛾眉却不前”。尾联的这一慨叹，紧承在语流上逐层推进的前三联而发，于升至极高处的波峰浪尖，忽发哀音，跌入深潭，凄恻动人，给读者心灵以强烈冲击。', poem_tags = '梅花,抒情' WHERE poem_title = '梅花' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '今天晚上劝您务必要喝个一醉方休，酒桌前千万不要谈论明天的事情。就珍重现在热情的主人的心意吧，因为主人的酒杯是深的，主人的情谊也是深的。\n我忧愁的是像今晚这般欢饮的春夜太短暂了，我不再推辞说您又将我的酒杯斟得太满。既然有酒可喝再怎么样也得打起精神来，人生能有多长呢？', poem_notes = '尊前：酒席前。尊：同“樽（zūn）”，古代盛酒器具。《淮南子》：“圣人之道，犹中衢而设樽耶，过者斟酌，各得其宜。”　\n“须愁”句：应愁时光短促。漏：刻漏，指代时间。\n莫诉：不要推辞。\n呵呵（huōhuō）：笑声。这里是指“得过且过”，勉强作乐。', poem_appreciation = '这首词头两句说“劝君今夜须沈（沉）醉，尊前莫话明朝事”，下半首又说“须愁春漏短，莫诉金杯满”，四句之中竟有两个“须”字，两个“莫”字，口吻的重叠成为这首词的特色所在，也是佳处所在，下面写“遇酒且呵呵，人生能几何”，又表现得冷漠空泛。有的选本因为这重叠和空泛而删去了这首词，叶嘉莹教授认为这实际上等于割裂了一个完整的生命进程，都是未能体会出这首词真正好处的缘故。\n\n　　“劝君今夜须沈醉，尊前莫话明朝事”，是深情的主人的劝客之语，一个“今夜”，一个“明朝”具有沉痛的含义。这两句是说：你今夜定要一醉方休，酒杯之前不要说起明天的事情。人是要有明天才有希望的，明天是未来希望的寄托，可是他现在用了一个“莫”字，今朝有酒今朝醉，明天的事千万别提起。“莫话明朝事”，那必然是明天的事情有不可期望，不可以诉说的悲哀和痛苦，所以他这里反映了非常沉痛的悲哀。这是主人劝客之词，如果联想到他的“红楼别夜”的美人劝他早归家，则当时他的希望原当在未来，在明天，明天回去可以见到他“绿窗人似花”的美人，而现在主人劝他“尊前莫话明朝事”，是明天绝无回去的希望了。“珍重主人心，酒深情亦深”，意思是说：纵然是对红楼别夜的美人还是这般的锺情和怀念，但是没有再见的希望，我就珍重现在热情的主人的心意吧，因为主人敬给我的酒杯是深的，主人对我的情谊也是深的。李白有首诗是这样写的：“兰陵美酒郁金香，玉碗盛来琥珀光。但使主人能醉客，不知何处是他乡。”大意是：兰陵的美酒散发着郁金花的香气，白玉碗中的酒浆闪泛着琥珀般的光泽，只要主人能使我沉醉，我就忘记了什么地方是他乡。一般人只知道欣赏李白诗潇洒飞扬的一面，其实李白诗也有非常沉痛的一面，李白写饮酒的诗最多，而且多与“悲愁”联系在一起，像“抽刀断水水更流，举杯消愁愁更愁”，“五花马，千金裘，呼儿将出换美酒，与尔同消万古愁”，都属此类。在韦庄这二句写的主人劝酒之情中，也隐含了深重的悲哀。\n\n　　下半阕的“须愁春漏短，莫诉金杯满”，叶嘉莹认为此处乃是客人自劝之词：我忧愁的是像今晚这般欢饮的春夜非常短暂，而不会以你把酒杯斟得太满作为推托之辞。“遇酒且呵呵”，“呵呵”是笑声，如果读者认为是真的欢笑就错了。因为“呵呵”两个字只是空洞的笑的声音，没有真正欢笑的感情，韦庄所写的正是强做欢笑的酸辛。他说：如果你再不珍惜今天“春漏短”的光阴，今天的欢笑，今天这“酒深情亦深”的感情，明天也都不会再存在了。唐朝灭亡，当时的韦庄已经是七十岁以上的老人了，所以他说“遇酒且呵呵，人生能几何”。', poem_tags = '宋词三百首,饮酒,感伤' WHERE poem_title = '菩萨蛮·劝君今夜须沉醉' AND poem_author = '韦庄';
UPDATE edu_poem SET poem_translation = '我本为浩然正气而生，仅为国而死，浩气当还于太空，虽我将死，但丹心可永存，可千秋万代照耀后世。\n生平早有报国心，却未能报国留下遗憾，留下忠魂作厉鬼仍要为国除害杀敌作补偿。', poem_notes = '浩气：正气。正大刚直的精神。 还：这里是回归的意思。 太虚：太空。\n丹心：红心，忠诚的心。 千古：长远的年代，千万年。\n生平：一辈子，一生。 报国：报效国家。\n忠魂：忠于国家的灵魂，忠于国家的心灵、精神。 魂：作者的原意是指死后的魂灵，这是古人的看法。', poem_tags = '古诗三百首,爱国,壮志' WHERE poem_title = '就义诗' AND poem_author = '杨继盛';
UPDATE edu_poem SET poem_translation = '在草木阴阴的映照下，弯曲的小溪显得格外碧绿，一场小雨滴落在草坪上溅起细沙。\n鹅鸭不知道春天已过，还争相随着流水去追赶桃花。', poem_notes = '阴阴：草木繁盛。趁：追逐。', poem_tags = '古诗三百首,写景,惜春' WHERE poem_title = '春日' AND poem_author = '晁冲之';
UPDATE edu_poem SET poem_translation = '茂密的青草可使我想起久客不归的王孙。杨柳树外楼阁高耸，她终日徒劳地伫望伤神。杜鹃乌儿一声声啼叫，悲凄的声音令人不忍听闻。眼看又到了黄昏，暮雨打得梨花凌落，深深闭紧闺门。', poem_notes = '萋萋：形容春草茂盛的样子。\n王孙：这里指游子，行人。\n杜宇：即杜鹃鸟，鸣声凄厉，好象在劝说行人“不如归去”。', poem_tags = '宋词三百首,婉约,伤春,怀人' WHERE poem_title = '忆王孙·春词' AND poem_author = '李重元';
UPDATE edu_poem SET poem_translation = '我潦倒穷困漂泊落魄，唯有借酒消愁，主人持酒相劝，相祝身体健康。\n当年主父偃向西入关，资用困乏滞留异乡，家人思念折断了门前杨柳。\n哎，我听说马周客居新丰之时，天荒地老无人赏识。\n只凭纸上几行字，就博得了皇帝垂青。\n我有迷失的魂魄，无法招回，雄鸡一叫，天下大亮。\n少年人应当有凌云壮志，谁会怜惜你困顿独处，唉声叹气呢？', poem_notes = '致酒：劝酒。\n行：乐府诗的一种体裁。\n零落：漂泊落魄。\n奉觞（shāng）：捧觞，举杯敬酒。\n客长寿：敬酒时的祝词，祝身体健康之意。\n主父：《汉书》记载：汉武帝的时候，“主父偃西入关见卫将军，卫将军数言上，上不省。资用乏，留久，诸侯宾客多厌之。”后来，主父偃的上书终于被采纳，当上了郎中。\n折断门前柳：折断门前的杨柳。\n马周：《旧唐书》记载：“马周西游长安，宿于新丰，逆旅主人唯供诸商贩而不顾待。周遂命酒一斗八升，悠然独酌。主人深异之。至京师，舍于中郎将常何家。贞观五年（631年），太宗令百僚上书言得失，何以武吏不涉经学，周乃为陈便宜二十余事，令奏之，皆合旨。太宗怪其能，问何，对曰：‘此非臣所能，家客马周具草也。’太宗即日招之，未至间，遣使催促者数四。及谒见，与语甚悦，令值门下省。六年授监察御史。”\n龙颜：皇上。\n恩泽：垂青。\n迷魂：这里指执迷不悟。宋玉曾作《招魂》，以招屈原之魂。\n拿云：高举入云。\n呜呃：悲叹。', poem_appreciation = '这首诗写诗人客居长安，求官而不得的困难处境和潦倒感伤的心情。诗人以不得志的人的身份作客饮酒，前四句写作客的情形和潦倒自伤的心情。中间四句，诗人由自伤转为自负和自勉，引汉代名士主父偃和唐代名士马周自比，说明他自己有经世之才，早晚会得到皇帝赏识。后四句，诗人又由自负和自勉转为自伤，感慨自己冷落寂寞的处境。三层意思转折跌宕，沉郁顿挫，而以怀才不遇之意加以贯通。《李长吉集》引黄淳耀的话评价说：“绝无雕刻，真率之至者也。”黎简评价说：“长吉少有此沉顿之作。”\n\n　　从开篇到“家人折断门前柳”四句一韵，为第一层，写劝酒场面。先总说一句，“零落栖迟”（潦倒游息）与“一杯酒”连缀，大致地表示以酒解愁的意思。不从主人祝酒写起，而从客方（即诗人自己）对酒兴怀落笔，突出了客方悲苦愤激的情怀，使诗一开篇就具“浩荡感激”（刘辰翁语）的特色。接着，诗境从“一杯酒”而转入主人持酒相劝的场面。他首先祝客人身体健康。“客长寿”三字有丰富潜台词：忧能伤人，折人之寿，而“留得青山在”，才能“不怕没柴烧”。七字画出两人的形象，一个是穷途落魄的客人，一个是心地善良的主人。紧接着，似乎应继续写主人的致词了。但诗笔就此带住，以下两句作穿插，再引申出“零落栖迟”的意思，显得委婉含蓄。“主父西游困不归”，是说汉武帝时主父偃的故事。主父偃西入关，郁郁不得志，资用匮乏，屡遭白眼（见《汉书·主父偃传》）。诗人以他来自比，“困不归”中含有无限辛酸之情。古人多因柳树而念别。“家人折断门前柳”，通过家人的望眼欲穿，写出诗人自己的久羁异乡之苦，这是从对面落笔。引古自喻与对面落笔同时运用，都使诗情曲折，生动有味。经过这两句的跌宕，再继续写主人致词，诗情就更为摇曳多姿了。\n\n　　“吾闻马周昔作新丰客”到“直犯龙颜请恩泽”是第二层，为主人致酒之词。“吾闻”二字领起，是对话的标志；同时通过换韵，与上段划分开来。这几句主人的开导写得很有意味，他抓住上进心切的少年心理，甚至似乎看穿诗人引古自伤的心事，有针对性地讲了另一位古人一度受厄但终于否极泰来的奇遇：唐初名臣马周，年轻时受地方官吏侮辱，在去长安途中投宿新丰，逆旅主人待他比商贩还不如，他的处境比主父偃更为狼狈。为了强调这一点，诗中用了“天荒地老无人识”的生奇夸张造语，那种抱荆山之玉而“无人识”的悲苦，以“天荒地老”四字来表达，看似无理，实际上极能尽情。马周一度像这样困厄难堪，以后却时来运转，因替他寄寓的主人、中郎将常何代笔写条陈，唐太宗十分高兴，予以破格提拔。（注：原文见作品注释。）“空将笺上两行书，直犯龙颜请恩泽”说的就是这件事。主人的话到此为止，只称引古事，不加任何发挥。但这番语言很富于启发性。他说马周只凭“两行书”即得皇帝赏识，言外之意似乎是：政治出路不只是有一种途径，“囊锥”终有出头之日，科场受阻也不能悲观。事实上，马周只是被唐太宗偶然发现，这里却说成“直犯龙颜请恩泽”，主动自荐，似乎又在怂恿少年要敢于进取，创造成功的条件。这四句以古事对古事，话中有话，极尽循循善诱之意。\n\n　　“我有迷魂招不得”至篇终为第三层，直抒胸臆作结。“听君一席话，胜读十年书”，主人的开导使“我”这个“有迷魂招不得”者，茅塞顿开。诗人运用擅长的象征手法，以“雄鸡一声天下白”写主人的开导生出奇效，使他的心胸豁然开朗。这“雄鸡一声”是一鸣惊人，而“天下白”的景象更是光明璀璨。这一景象激起了诗人的豪情，于是末二句写道：“少年正该壮志凌云，怎能一蹶不振！老是唉声叹气，那是谁也不会来怜惜你的。”“谁念幽寒坐呜呃”，“幽寒坐呜呃”五字，用语独造，形象地刻画出诗人自己“咽咽学楚吟，病骨伤幽素”（《伤心行》）的苦态。“谁念”句，同时也就是一种对旧我的批判。末二句音情激越，颇具兴发感动的力量，使全诗具有积极的思想色彩。\n\n　　《致酒行》以抒情为主，却运用主客对白的方式，不作平直叙写。诗中涉及两个古人故事，却分属宾主，《李长吉歌诗汇解》引毛稚黄的话说：“主父、马周作两层叙，本俱引证，更作宾主详略，谁谓长吉不深于长篇之法耶？”这篇的妙处，还在于它有情节性，饶有兴味。另外，诗在铸词造句、辟境创调上往往避熟就生，如“零落栖迟”、“天荒地老”、“幽寒坐呜呃”，尤其是“雄鸡一声”句等等，或语新，或意新，或境奇，都对表达诗情起到了积极作用，是李贺式的锦心绣口。', poem_tags = '怀才不遇,饮酒,抒怀' WHERE poem_title = '致酒行' AND poem_author = '李贺';
UPDATE edu_poem SET poem_translation = '春风柔日光暖满目荡漾春光，蝴蝶和蜜蜂不时乱飞进厅房。\n门前的几枝柳条低拂着衣架，一片山花飘落在了笔床之上。\n\n梁园之中夕阳已西下，只有点点乱飞的乌鸦，放眼望去满目的萧条，零零落落三两户人家。\n园中树木你怎能知道，人已散尽失去了繁华，一年一度春风又吹过，依然开着昔日的鲜花。', poem_notes = '山房：营造于山野的房舍、别墅。春事：春色、春光。\n恬：这里指风柔和。\n衣桁（héng）：犹衣架，挂衣服的横木。\n笔床：卧置毛笔的器具。南朝陈徐陵《〈玉台新咏〉序》：“翡翠笔床，无时离手。\n梁园：兔园，俗名竹园，西汉梁孝王刘武所建，故址在今河南省商丘市东，周围三百多里。园中有百灵山、落猿岩、栖龙岫、雁池、鹤洲、凫渚，宫观相连，奇果佳树，错杂其间，珍禽异兽，出没其中。日暮：傍晚，太阳落山的时候。\n极目：纵目，用尽目力远望。萧条：寂寞冷落；凋零。\n发：绽放。', poem_appreciation = '第一首诗切合题意，纯是一首写景诗，写的是浓郁的春光充天塞地，不仅山野处处万紫千红，连山房书屋都被蜂蝶花木占领。这在一定程度上反映出作者对生活的热爱，对前途充满信心。作者先写近景，在他笔下，春风是柔和的，日光是温暖的，春意盎然。第二句选取了春天里很有代表性的生命：蝴蝶和蜜蜂，作者没有描写它们忙着采蜜的景象，而是写了它们误入厅房，并着一“乱”字，生动形象表现了蜂蝶之忙，进一步表现了春日的勃勃生机。第三、四句转入写静景，柳树的枝条在春风中飘舞，低过了晾衣的横木，在风的吹送下，一片山花落在了笔床上。虽是静景，但作者却是动静结合的描绘——两句都与风有关，而并没有直接写风，可见作者观察细微而笔力不凡。\n\n　　第二首诗是吊古之作。梁孝王曾在梁园中设宴，一代才人枚乘、司马相如等都应召而至。到了春天，更见热闹：百鸟鸣啭，繁花满枝，车马接轸，士女云集。\n\n　　就是这样一个繁盛所在，如今所见，则是：“梁园日暮乱飞鸦，极目萧条三两家。”这两句描画出两幅远景：仰望空中，晚照中乱鸦聒噪；平视前方，一片萧条，唯有三两处人家。当年“声音相闻”、“往来霞水”（枚乘《梁王兔园赋》）的各色飞禽不见了，宫观楼台也已荡然无存。不言感慨，而今古兴亡、盛衰无常的感慨自在其中。从一句写到二句，极自然，却极工巧：人们对事物的注意，常常由听觉引起。一片聒噪声，引得诗人抬起头来，故先写空中乱鸦。“日暮”时分，众鸟投林，从天空多鸦，自可想见地上少人，从而自然引出第二句中的一派萧条景象。\n\n　　诗人在远望以后，收回目光，就近察看，只见庭园中的树木，繁花满枝，春色不减当年。就象听到丁丁的伐木声，更感到山谷的幽静一样，这突然闯入他的视野中的绚丽春光，进一步加深了他对梁园极目萧条的印象。梁园已改尽昔日容颜，春花却依旧盛开。“庭树不知人去尽，春来还发旧时花。”诗人不说自己深知物是人非，却偏从对面翻出，说是“庭树不知”；不说此时梁园颓败，深可伤悼，自己无心领略春光，却说无知花树遵循自然规律，偏在这一片萧条之中依然开出当年的繁花。感情极沉痛，出语却极含蓄。\n\n　　作为一首吊古之作，梁园的萧条是诗人所要着力描写的。然而一、二两句已经把话说尽，再要顺着原有思路写出，势必叠床架屋。诗人于紧要处别开生面，在画面的主题位置上添上几笔艳丽的春色。以乐景写哀情，相反而相成，梁园的景色愈见萧条，诗人的吊古之情也愈见伤痛了，反衬手法运用得十分巧妙。\n\n　　全诗分前后两部分，笔法不同，色调各异，然而又并非另起炉灶，“庭树”与“飞鸦”暗相关合（天空有鸟，地上有树）。篇末以“旧时花”遥应篇首“梁园”，使全诗始终往复回还于一种深沉的历史感情之中。历来运用反衬手法表现吊古主题的作品固然不少，但有如此诗老到圆熟的，却不多见。', poem_tags = '春天,吊古' WHERE poem_title = '山房春事二首' AND poem_author = '岑参';
UPDATE edu_poem SET poem_tags = '元宵节,月亮' WHERE poem_title = '元夕无月' AND poem_author = '丘逢甲';
UPDATE edu_poem SET poem_translation = '在一个凄清的深秋，枫叶漂浮于江水之上。这时一阵西风吹来，漫山的树木发出萧萧之声，闻见此景，小女子我伤感了。极目远眺，见江桥掩映于枫林之中。日已垂暮，咋还不见情郎乘船归来。不见情郎归，小女子我焦灼了。我对情郎的思念如西江之水延绵不绝，流水有多长，我的思念就有多久。', poem_notes = '江陵：唐朝时江陵府东境达今湖北潜江汉水南岸。诗中“江陵”指长江南岸之潜江，而非北岸之江陵。子安，即李亿，为朝廷补阙。《情书寄子安》题下注云：“一本题下有补阙二字。”可知李子安即李亿。但也有人认为子安为另一人。\n掩映：时隐时现，半明半暗。暮帆：晚归的船。\n“忆君”二句：同南唐李煜《虞美人·春花秋月何时了》“问君能有几多愁，恰似一江春水向东流”与北宋欧阳修《踏莎行·候馆梅残》“离愁渐远渐无穷，迢迢不断如春水”表现手法相似。', poem_appreciation = '鱼玄机这首《江陵愁望寄子安》载于《全唐诗》卷八〇四。下面是中国李白研究学会理事、四川大学文学与新闻学院教授周啸天先生对此诗的赏析。\n\n　　建安诗人徐干有著名的《室思》诗五章，第三章末四句是：“自君之出矣，明镜暗不治。思君如流水，无有穷已时。”后世爱其情韵之美，多仿此作五言绝句，成为“自君之出矣”一体。女诗人鱼玄机的这首写给情人的诗，无论从内容、用韵到后联的写法，都与徐干《室思》的四句十分接近。但体裁属七绝，可看作“自君之出矣”的一个变体。惟其有变化，故创获也在其中了。\n\n　　五绝与七绝，虽同属绝句，二体对不同风格的适应性却有较大差异。朱自清说：“论七绝的称含蓄为‘风调’。风飘摇而有远情，调悠扬而有远韵，总之是余味深长。这也配合着七绝的曼长的声调而言，五绝字少节促，便无所谓风调。”（《唐诗三百首指导大概》）读鱼玄机这首诗，觉着它比《自君之出矣》多一点什么的，正是这里所说的“风调”。本来这首诗也很容易缩成一首五绝：“枫叶千万枝，江桥暮帆迟。忆君如江水，日夜无歇时”，字数减少而意思不变，但总感到少一点什么，也是这里所说的“风调”。试逐句玩味鱼诗，看每句多出两字是否多余。\n\n　　首句以江陵秋景兴起愁情。《楚辞·招魂》：“湛湛江水兮上有枫，极目千里兮伤春心。”枫生江上，西风来时，满林萧萧之声，很容易触动人的愁怀。“千枝复万枝”，是以枫叶之多写愁绪之重。它不但用“千”“万”数字写枫叶之多，而且通过“枝”字的重复，从声音上状出枝叶之繁。而“枫叶千万枝”字减而音促，没有上述那层好处。\n\n　　“江桥掩映──暮帆迟”。极目远眺，但见江桥掩映于枫林之中；日已垂暮，而不见那人乘船归来。“掩映”二字写出枫叶遮住望眼，对于传达诗中人焦灼的表情是有帮助的。词属双声，念来上口。有此二字，形成句中排比，声调便曼长而较“江桥暮帆迟”为好听。\n\n　　前两句写盼人不至，后两句便接写相思之情。用江水之永不停止，比相思之永无休歇，与《室思》之喻，机杼正同。乍看来，“西江”、“东流”颇似闲字，但减作“忆君如流水，日夜无歇时”，比较原句便觉读起来不够味了。刘方平《春怨》末二句云：“庭前时有东风入，杨柳千条尽向西”，晚清王闿运称赞说“以东、西二字相起，（其妙）非独人不觉，作者也不自知也”，“不能名言，但恰入人意。”（《湘绮楼说诗》）鱼玄机此诗末两句妙处正同。细味这两句，原来分用在两句之中非为骈偶而设的成对的反义字（“东”“西”），有彼此呼应，造成抑扬抗坠的情调，或擒纵之致的功用，使诗句读来有一唱三叹之音，亦即所谓“风调”。而删芟这样字面，虽意思大致不差，却必损韵调之美。因此鱼玄机此诗每句多二字，有助于加强抒情效果，它们充分发挥了作用。所以比较五绝“自君之出矣”一体，艺术上正自有不可及之处。', poem_tags = '写景,思念' WHERE poem_title = '江陵愁望寄子安 / 江陵愁望有寄' AND poem_author = '鱼玄机';
UPDATE edu_poem SET poem_tags = '书法,赞美' WHERE poem_title = '书' AND poem_author = '李峤';
UPDATE edu_poem SET poem_translation = '白日真黑夜假谁去分辨，从古到今的事无尽无休。\n只喜臧生能骗过圣人，又怎知甯子识破了装傻的。\n萤火虫有光非真的火光，荷叶上的露水虽圆岂是真珠？\n不要烧柴去照亮车马，可怜的光彩有甚么不同呢？', poem_notes = '放言：意即无所顾忌，畅所欲言。\n元九：即元稹，“九”是其排行。他在元和五年（810年）被贬为江陵士曹参军。其间曾作《放言五首》，见《元氏长庆集》卷十八。\n长句诗：指七言诗，相对五言诗而言；五言为短句。\n李颀：唐代诗人，开元十三年（725年）进士，诗以写边塞题材为主，风格豪放，慷慨悲凉，七言歌行尤具特色。此举其两句诗见于他的《杂兴》诗。济水：源出河南省济源县西王屋山，其故道过黄河而南，东流入今山东省境内。河：黄河。周公：姓姬名旦，周武王弟，成王之叔，武王死，成王年幼，周公摄政，管、蔡、霍三叔陷害，制造流言，诬蔑周公要篡位。周公于是避居于东，不问政事。后成王悔悟，迎回周公，三叔惧而叛变，成王命周公征之，遂定东南。\n接舆（yú）狂：接舆，传说是春秋时楚国的一个隐士，他以佯狂避世，故此说“接舆狂”。其真实姓名不可考，因他曾迎着孔子的车而歌，故称接舆（见《论语·微子》、《庄子·逍遥游》）。舆，本指车厢，亦泛指车。\n予：我。出佐浔阳：被贬出京，到江州去做司马，辅助治事。浔（xún）阳：指江州。隋设九江郡，唐代叫江州或浔阳郡。治所在今江西省九江市。\n未届所任：还未到达任所。届：到。\n暇（xiá）：空闲时间。\n缀（zhuì）：撰写。续其意：谓读元稹《放言》之意。耳：叹词。\n辨：一作“辩”。底：啥。\n臧（zāng）生：指臧武仲。臧：一作“庄”。防：是武仲的封地。武仲凭借其防地来要挟鲁君。武仲：臧孙氏，名纥，官为司寇，在贵族中有“圣人之称”（《左传·襄公二十二年》杜氏注：“武仲多知，时人谓之圣”）。诈圣：欺诈圣人。甯（nìng）子：指甯武子。甯：今亦作“宁”。知：同“智”。燔（fán）柴：此用为名词，指火光。照乘：珠名。殊：异。', poem_tags = '抒情' WHERE poem_title = '放言五首·其一' AND poem_author = '白居易';
UPDATE edu_poem SET poem_appreciation = '、　　此诗开头两句写自己胸怀壮志，寻找救国救民的革命真理。接着四句转入正题，就日俄战争图抒发感慨。最后两句表示诗人不惜牺牲生命，誓将用鲜血拯救祖国于水深火热之中的决心。全诗篇幅不长，却情辞激越，令人为之动容。光绪三十三年（1907年）秋瑾在浙江绍兴起义，失败后不幸被捕，在绍兴轩亭口英勇就义，她以自己的热血履行了自己的誓言。\n\n　　这是一首七言律诗。首联大气磅礴，展现出意气风发的诗人主体形象。颔联点出观图之事，从而引发对日俄横行东北的极大愤恨。干宝《搜神记》说，汉武帝开凿昆明池，挖到深处全是灰墨，问学识渊博的东方朔是怎么回事，东方朔说要西域人才知道。到了东汉明帝时，西域有道人来，问道人，回答是：圣经上说，天地大劫将尽，着劫烧，灰墨便是劫烧的余灰。这里借指战火的灰烬，说岂能把大好河山给人作战场，遭受战火的破坏。这两句写忧国怀抱，渴望有救国的志士能出现，也含有以出群之才自期的意思。颈联两句充分表现诗人的忧国之情，并由忧国而思济世。尾联表达愿为祖国而抛头颅洒热血的崇高志向。\n\n　　全篇所写，都是忧国的思想和救时的抱负，充满动人的爱国激情。语言朴素自然，直抒胸臆，不假雕饰，“忍看”“拚将”“须把”等词语的运用，将悲愤而激昂的感情，表达得淋漓尽致，劲健有力。全诗语言浅显明快，风格刚健豪放。情愫真率，披襟见怀；字重千钧，力能扛鼎。一腔豪气喷薄而出，丝毫不见女儿态。', poem_tags = '爱国,抒怀' WHERE poem_title = '黄海舟中日人索句并见日俄战争地图' AND poem_author = '秋瑾';
UPDATE edu_poem SET poem_appreciation = '此词作于元丰二年（1079）三月，为苏轼由徐州调至湖州途中。词中化用李商隐《无题》诗中“相见时难别亦难，东风无力百花残。春蚕到死丝方尽，蜡炬成灰泪始干”句意，将积郁的愁思注入即事即地的景物之中，抒发了作者对徐州风物人情无限留恋之情，并在离愁别绪中融入了深沉的身世之感。\n\n　　词的上片以感慨起调，言天涯流落，愁思茫茫，无穷无尽。“天涯流落”，深寓词人的身世之感。苏轼外任多年，类同飘萍，自视亦天涯流落之人。他在徐州仅两年，又调往湖州，南北辗转，这就更增加了他的天涯流落之感。这一句同时也饱含着词人对猝然调离徐州的感慨。“既相逢，却匆匆”两句，转写自己与徐州人士的交往，对邂逅相逢的喜悦，对骤然分别的痛惜，得而复失的哀怨，溢于言表。“携手”两句，写他永远不能忘记自己最后离开此地时依依惜别的动人一幕。“携手佳人”，借与佳人乍逢又别的感触言离愁。“和泪折残红”，写作者面对落花，睹物伤怀，情思绵绵，辗转不忍离去，同时也是写离徐的时间，启过拍“为问”三句。末三句由残红而想到残春，因问东风尚余几许，感叹纵使春光仍在，而身离徐州，与谁同春。此三句通过写离徐后的孤单，写对徐州的依恋，且笔触一波三折，婉转抑郁。\n\n　　词的下片即景抒情，继续抒发上片未了之情。过片“隋堤三月水溶溶”，是写词人离徐途中的真景，将浩荡的悲思注入东去的三月隋堤那溶溶春水中。“背归鸿，去吴中”，亦写途中之景，而意极沉痛。春光明媚，鸿雁北归故居，而词人自己却与雁行相反，离开徐州热土，南去吴中湖州。苏轼是把徐州当成了他的故乡，而自叹不如归鸿。“彭城”即徐州城。“清泗与淮通”暗寓作者不忍离徐，而现实偏偏无情，不得不背鸿而去，故于途中频频回顾，直至去程已远，回顾之中，唯见清澈的泗水由西北而东南，向着淮水脉脉流去。看到泗水，触景生情，自然会想到徐州（泗水流经徐州）。歇拍三句，即景抒情，于沉痛之中交织着怅惘的情绪。徐州既相逢难再，因而词人欲托清泗流水把千滴相思之泪寄往徐州，无奈楚江（指泗水）东流，相思难寄，令词人不禁怅然若失。托淮泗以寄泪，情真意厚，且想象丰富，造语精警；而楚江东流，又大有“自是人生长恨水长东”之意，感情沉痛、怅惘，读之令人肠断。\n\n　　此词写别恨，采用了化虚为实的艺术手法。作者由分别之地彭城，想到去湖州途中沿泗入淮，向吴中新任所的曲折水路；又由别时之“和泪”，想到别后的“寄泪”。这样，离愁别绪更显深沉、哀婉。结句“流不到，楚江东”，别泪千点因春水溶溶而愈见浩荡，犹如一声绵长的浩叹，久远地回响在读者的心头。', poem_tags = '春天,离别,写景,抒情' WHERE poem_title = '江神子·恨别' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '译文 你从哪里得到这一个屏风？上面分明有怀素书法的踪迹。 虽然有很多灰尘、颜色的沾染，但还能够见到墨痕的浓重。 写的字的点就像怪石奔向秋天的山涧，字的竖和勾的笔画就像寒枯的古藤倒挂在古松下。 如果把屏风放到水边，每个字恐怕都要化成蛟龙，游到水里去了。' WHERE poem_title = '草书屏风' AND poem_author = '韩偓';
UPDATE edu_poem SET poem_translation = '日子闲散的时候，没有一样事情不自如从容，往往一觉醒来，东边的窗子早已被日头照得一片通红。\n静观万物，都可以得到自然的乐趣，人们对一年四季中美妙风光的兴致都是一样的。\n道理通著天地之间一切有形无形的事物，思想渗透在风云变幻之中。\n只要能够富贵而不骄奢淫逸，贫贱而能保持快乐，这样的男子汉就是英雄豪杰了。', poem_notes = '从容：不慌不忙。 \n觉：醒。 \n静观：仔细观察。 \n自得：安逸舒适的样子 \n四时：指春、夏、秋、冬四季。 \n通：通达 \n淫：放纵。 \n豪雄：英雄。', poem_appreciation = '心情闲静安适，做什么事情都不慌不忙的。一觉醒来，红日已高照东窗了。静观万物，都可以得到自然的乐趣，人们对一年四季中美妙风光的兴致都是一样的。道理通著天地之间一切有形无形的事物，思想渗透在风云变幻之中。只要能够富贵而不骄奢淫逸，贫贱而能保持快乐，这样的男子汉就是英雄豪杰了。\n\n　　人生在世也就那么三、四十年的好日子，真不算长，转眼间已进“天命”之年，可自我感觉还没怎么活，人活着易，活出质量来难，在我看来，快乐的人生才是最对得起自己，也对得起他人的人生。人啊，怎么活才能活快乐，这里面的学问还真大。常从朋友们的文章中看到各种各样的烦恼，多是悲情、伤感，充满对现实的无奈与苦闷，真正能把自己的快乐传递给大家的实在不多。\n\n　　反躬自问，自我感觉是个活的快乐的人，尽管生活中遇到了诸多的挫折与磨难，在别人看来我应该是脸上挂满愁容的，可事实恰恰相反，我脸上的微笑已经成为一种常态，很难有什么事情能让我的心情阴晴不定了。', poem_tags = '秋天,人生,哲理' WHERE poem_title = '秋日' AND poem_author = '程颢';
UPDATE edu_poem SET poem_translation = '梅花啊，你在百花开放之前绽开，在寒冷中出现。春寒料峭中，朦胧的月亮总是先照亮梅花。\n主人十分喜爱你，不管江妃如何抱怨，也要折下最繁茂的枝头，插进壶中，供人玩赏。', poem_notes = '重叶梅（zhòng yè meí）：梅花的一种。 宋代范成大《梅谱》：“重叶梅，花头甚丰，叶重数层，盛开如小白莲，梅中之奇品。”\n头上：先。\n见（xiàn）： “现”的古字，显现，出现。\n霜月：月色如秋霜。\n相知：了解我。相，范围副词，在此为“我”之意。\n春风面：春风中花容。\n江妃：即梅妃，唐明皇开元中，“高力士使闽、粤，见江采萍少而丽，选归，侍明皇，大见宠幸。性喜梅，所居悉植之。帝以其所好，戏名曰梅妃。”这里以江妃代梅妃。\n许：答应，应诺。\n冰壶荐（jiàn）：即荐给冰壶。冰壶，即玉壶，可用来盛冰或浸花，比喻洁白。荐：进，进献 。', poem_appreciation = '这是一首咏重叶梅的咏物词。\n\n　　开头二句写重叶梅雪中独放。化用“春脚移从何处来，未到百花先到梅。”和“前村深雪里，昨夜一枝开。”写出重叶梅不怕风雪严冬，在百花开放之前开放，从容自如，从而突出重叶梅不怕雪虐风威的高尚品格。\n\n　　三、四句写梅花报春。在早春开放的重叶梅，与寒霜冷月相知与晁无咎说的“一萼故应先腊破，百花浑未觉春来。”意思相近，在“百花浑未觉看来”的时候“先识春风面”，具有先百花而报春的先觉者的独特风神。南宋思想家、文学家陈亮说：“欲传春信息，不怕雪里埋。”宋代政治家，文学家向子湮（yīn）在《虞美人·梅花盛开，走笔戏呈韩叔夏司谏》中也说：“满城桃李不能春，独向雪花深处、露花身。”写的都是“雪里已知春信至”的品格，表现出重叶梅在百花开放之前的特性。\n\n　　五六句写重叶梅受到主人喜爱和主人对重叶梅的情深意重，而且主人对重叶梅的喜爱从没动摇过。这两句词除了说明主人爰梅之外，也从侧面衬托出重叶梅之美与可贵。\n\n　　最后两句词紧承上句“情意深”，是对主人爱梅之情做具体的描述，写主人把最好的重叶梅折下来，插在冰壶水中，供自己和友人玩赏。从主人再一次握重叶梅那一方面来说是花、人合一，可以说是“无花饿伯仲，得雪愈精神”。\n\n　　重叶梅在百花开放之前开放，在寒风凛冽中独自绽放，表现出重叶梅的不惧风雪；主人对重叶梅的情深意重，从把最好的重叶梅折下来供友人欣赏，更加表现出主人对重叶梅的喜爱。', poem_tags = '咏物,梅花' WHERE poem_title = '生查子·重叶梅' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '万树上都有蝉在鸣叫，惊吓了河对面的虹彩，在乐游原里有阵阵的西风。\n羲和驾着太阳车，一直到黄昏时分才停下来休息，不肯让这夕阳结束，不肯让太阳掉头向东。', poem_notes = '乐游原：亦作“乐游苑”，古苑名。\n隔岸：河的对岸。\n羲和：古代神话中驾驭太阳车的神。\n虞泉：亦作“虞渊”，传说为日没处。', poem_tags = '夏天,写景' WHERE poem_title = '乐游原' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '春风吹拂柳枝随风起舞，绽出嫩芽一片嫩黄比丝柔软。\n永丰坊西角的荒园里，整日都没有人，这柳枝属于谁？', poem_notes = '⑴千万枝：一作“万万枝”。\n⑵永丰：永丰坊，唐代东都洛阳坊名。\n⑶阿（ā）谁：疑问代词。犹言谁，何人。', poem_appreciation = '此诗前两句写柳的风姿可爱，后两句抒发感慨，是一首咏物言志的七绝。\n\n　　诗中写的是春日的垂柳。最能表现垂柳特色的，是它的枝条，此诗亦即于此着笔。首句写枝条之盛，舞姿之美。“春风千万枝”，是说春风吹拂，千丝万缕的柳枝，随风起舞。一树而千万枝，可见柳之繁茂。次句极写柳枝之秀色夺目，柔嫩多姿。春风和煦，柳枝绽出细叶嫩芽，望去一片嫩黄；细长的柳枝，随风飘荡，比丝缕还要柔软。“金色”、“丝”，比譬形象，写尽早春新柳又嫩又软之娇态。此句上承春风，写的仍是风中情景，风中之柳，才更能显出枝条之软。句中叠用两个“于”字，接连比况，更加突出了“软”和“嫩”，而且使节奏轻快流动，与诗中欣喜赞美之情非常协调。这两句把垂柳之生机横溢，秀色照人，轻盈袅娜，写得极生动。《唐宋诗醇》称此诗“风致翩翩”，确是中肯之论。\n\n　　这样美好的一株垂柳，照理应当受到人们的赞赏，为人珍爱；但诗人笔锋一转，写的却是它荒凉冷落的处境。诗于第三句才交代垂柳生长之地，有意给人以突兀之感，在诗意转折处加重特写，强调垂柳之不得其地。“西角”为背阳阴寒之地，“荒园”为无人所到之处，生长在这样的场所，垂柳再好，又有谁来一顾呢？只好终日寂寞了。反过来说，那些不如此柳的，因为生得其地，却备受称赞，为人爱惜。诗人对垂柳表达了深深的惋惜。这里的孤寂落寞，同前两句所写的动人风姿，正好形成鲜明的对比；而对比越是鲜明，越是突出了感叹的强烈。\n\n　　这首咏物诗，抒发了对永丰柳的痛惜之情，实际上就是对当时政治腐败、人才埋没的感慨。白居易生活的时期，由于朋党斗争激烈，不少有才能的人都受到排挤。诗人自己，也为避朋党倾轧，自请外放，长期远离京城。此诗所写，亦当含有诗人自己的身世感慨在内。\n\n　　此诗将咏物和寓意熔在一起，不着一丝痕迹。全诗明白晓畅，有如民歌，加以描写生动传神，当时就“遍流京都”。后来苏轼写《洞仙歌》词咏柳，有“永丰坊那畔，尽日无人，谁见金丝弄晴昼”之句，隐括此诗，读来仍然令人有无限低回之感，足见其艺术力量感人至深了。', poem_tags = '乐府,咏物,柳树' WHERE poem_title = '杨柳枝词' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '作者走在新安县的大路上，听到新安吏在按户籍册点兵。\n作者问新安吏：“难道因新安县小，壮丁已抽完，才抓这些不成丁的青年？”\n新安吏回答“府帖昨夜才下达，并下令说没有壮丁就依次抽未成年男子。”\n作者又问“抽来的未成年男子实在太小了，如何能守住王城呢？”\n健壮的中男还有母亲相送，瘦小的由于父母在战乱中去世，就变得孤苦伶仃了。\n河水日夜向东流，青山还留着哭声呢！\n“不要让眼泪哭干，收住你们纵横的泪水。\n眼泪哭干了会露出头骨，但天地终归是无情的，不能改变这悲痛的安排。\n我们官军攻取相州，日夜盼望收复其地。\n可是贼心难料，致使官军溃败。\n我们就去原先营垒就食，练兵也依凭着洛阳。\n挖掘壕沟也不会深得见水，放牧军马的劳役也还算轻。\n何况朝廷官军是符合正义的，一切必然顺利，爱护战士一目了然。\n送行战士不要哭得那么悲伤，长官会像父兄一样关爱你们。', poem_notes = '新安：地名，今河南省新安县。\n更：岂。\n次：依次。\n中男：指十八岁以上、二十三岁以下成丁。这是唐天宝初年兵役制度规定的。\n伶俜（pīng）：形容孤独。\n不到水：指掘壕很浅。\n仆射：指郭子仪。如父兄：指极爱士卒。\n相州：即“三男邺城戍”之“邺城”，今河南安阳。\n旧京：指东都洛阳。\n借问新安吏：作者问新安吏。此处省略主语“作者”。', poem_appreciation = '“客行新安道，喧呼闻点兵。”这两句是全篇的总起。“客”，杜甫自指。以下一切描写，都是从诗人“喧呼闻点兵”五字中生出。\n\n　　借问新安吏：“县小更无丁？”这是杜甫的问话。624年（唐高祖武德七年）定制：男女十六岁为中男，二十一岁为丁。至744年（唐玄宗天宝三年），又改以十八岁为中男，二十二岁为丁。按照正常的征兵制度，中男不该服役。杜甫的问话是很尖锐的，眼前明明有许多人被当作壮丁抓走，却撇在一边，跳过一层问：“新安县小，再也没有丁男了吧？”大概他以为这样一问，就可以把新安吏问住了。“府帖昨夜下，次选中男行。”官吏很狡黠，也跳过一层回答说，州府昨夜下的军帖，要挨次往下抽中男出征。官吏敏感得很，他知道杜甫用中男不服兵役的王法难他，所以立即拿出府帖来压人。讲王法已经不能发生作用了，于是杜甫进一步就实际问题和情理发问：“中男又矮又小，怎么能守卫东都洛阳呢？”王城，指洛阳，周代曾把洛邑称作王城。这在杜甫是又逼紧了一步，但接下去却没有答话。也许官吏被问得张口结舌，但更大的可能是官吏不愿跟杜甫啰嗦下去了。这就把官吏对杜甫的厌烦，杜甫对人民的同情，以及诗人那种迂执的性格都表现出来了。\n\n　　“肥男有母送，瘦男独伶俜。白水暮东流，青山犹哭声。”跟官吏已经无话可说了，于是杜甫把目光转向被押送的人群。他怀着沉痛的心情，把这些中男仔细地打量再打量。他发现那些似乎长得壮实一点的男孩子是因为有母亲照料，而且有母亲在送行。中男年幼，当然不可能有妻子。之所以父亲不来，是因为前面说过“县小更无丁”，有父亲在就不用抓孩子了。所以“有母”的言外之意，正是表现了另一番惨景。“瘦男”的“瘦”已叫人目不忍睹，加上“独伶俜”三字，更显得他们无亲无靠。怀着无限的痛苦，但却茫然而无法倾诉，这就是“独伶俜”三字展现给读者的情形。杜甫对着这一群哀号的人流泪站了很久，只觉天已黄昏了，白水在暮色中无语东流，青山好像带着哭声。这里用一个“犹”字便见恍惚。人走以后，哭声仍然在耳，仿佛连青山白水也呜咽不止。似幻觉又似真实，使读者惊心动魄。以上四句是诗人的主观感受。它在前面与官吏的对话和后面对征人的劝慰语之间，在行文与感情的发展上起着过渡作用。\n\n　　“莫自使眼枯，收汝泪纵横。眼枯即见骨，天地终无情！”这是杜甫劝慰征人的开头几句话。本来中男已经走了，他的话不能讲给他们听。这里，既像是把先前曾跟中男讲的话补叙在这里，又像是中男走过以后，杜甫觉得太惨了，一个人对着中男走的方向自言自语。那种发痴发呆的神情，更显出他茫然的心理。抒发悲愤一般总是要把感情往外放，可是此处却似乎在进行收束。“使眼枯”、“泪纵横”本来可以再作淋漓尽致的刻画，但杜甫却加上了“莫”和“收”。“不要哭得使眼睛发枯，收起奔涌的热泪吧。”然后再用“天地终无情”来加以堵塞。“莫”、“收”在前，“终无情”在后一笔煞住，好像要人把眼泪全部吞进肚里。这就收到了“抽刀断水水更流”的艺术效果。这种悲愤也就显得更深、更难控制，“天地”也就显得更加“无情”。\n\n　　杜甫写到“天地终无情”，已经极其深刻地揭露了兵役制度的不合理，然而这一场战争的性质不同于写《兵车行》的时候。当此国家存亡迫在眉睫之时，诗人从维护祖国的统一角度考虑，在控诉“天地终无情”之后，又说了一些宽慰的话。相州之败，本来罪在朝廷和唐肃宗，杜甫却说敌情难以预料，用这样含混的话掩盖失败的根源，目的是要给朝廷留点面子。本来是败兵，却说是“归军”，也是为了不致过分叫人丧气。“况乃王师顺，抚养甚分明。”唐军讨伐安史叛军，可以说名正言顺，但实际上又谈不上爱护士卒、抚养分明。另外，所谓战壕挖得浅，牧马劳役很轻，郭子仪对待士卒亲如父兄等等，也都是些安慰之词。杜甫讲这些话，都是对强征入伍的中男进行安慰。诗在揭露的同时，又对朝廷有所回护，杜甫这样说，用心良苦。实际上，人民蒙受的惨痛，国家面临的灾难，都深深地刺激着他沉重而痛苦的心灵。\n\n　　一方面，当时安史叛军烧杀掳掠，对中原地区生产力和人民生活的破坏是空前的。\n\n　　另一方面，唐朝统治者在平时剥削、压迫人民，在国难当头的时候，却又昏庸无能，把战争造成的灾难全部推向人民，要捐要人，根本不顾人民死活。这两种矛盾，在当时社会现实中尖锐地存在着，然而前者毕竟居于主要地位。可以说，在平叛这一点上，人民和唐王朝多少有一致的地方。因此，杜甫的“三吏”、“三别”既揭露统治集团不顾人民死活，又旗帜鲜明地肯定平叛战争，甚至对应征者加以劝慰和鼓励，读者也就不难理解了。因为当时的人民虽然怨恨唐王朝，但终究咬紧牙关，含着眼泪，走上前线支持了平叛战争。“白水暮东流，青山犹哭声”表达了作者对应征的“中男”的无限同情之心。', poem_tags = '战争,忧国忧民' WHERE poem_title = '新安吏' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '可惜这《白雪》古曲，没有遇到它的知音。\n我因为军事而忙碌不安，在淮海边蹉跎流离。\n山涧的树上还有晨雨，山鸟在剩余的春天里鸣叫。\n我有一瓢酒，可以用来慰藉奔波的生活。', poem_notes = '卢陟：人名,韦应物外甥。.\n白雪：古琴曲名，传为春秋师旷所作。\n恓惶：忙碌不安貌。\n戎旅：军旅，兵事。\n哢：鸟鸣，鸟叫。', poem_tags = '抒怀,感慨,生活' WHERE poem_title = '简卢陟' AND poem_author = '韦应物';
UPDATE edu_poem SET poem_translation = '今天是四月十七，去年这个日子，正是与你离别的时候。忍住泪水假装着低下脸，含羞皱着眉头。\n自别后我魂销肠断，如今只能在梦里与你相见。我的相思之情，除了天边的月亮，又有谁知道呢？', poem_notes = '佯（yáng羊）低面：假装着低下脸。\n敛眉：皱眉头。敛（liǎn脸）：蹙。', poem_appreciation = '这首词在《草堂诗余别集》中题作《闺情》，写女子追忆与情人的相别以及别后相思，抒发了闺中少女的相思之情。词句质朴率真，哀惋动人，是历来广为传诵的名篇。上片忆与郎君相别。“四月十七，正式去年今日。”连用记载日期的二句，在整个词史上少见。似乎是脱口而出，有似乎是沉醉之中的惊呼。“正是”二字用得传神，表现出记忆之深，让人如闻其声。“别君时”非常直接地点明让这个少女如此痴迷的原因。原来是与郎君分别了，痴迷、沉醉于苦苦的相思忘了时间的飞逝，忘了四季的轮回，忘了身在何处。好像是在一觉醒来，忽然发现，别离已一年，相思也一年了。然而，这一年似快又慢，快是指别离太快，相聚太短，慢是蕴涵了无数煎熬，无数牵挂。“忍泪佯低面，含羞半敛眉。”“佯”是掩饰，但不是故意做作，是基于感情的真挚。害怕郎君发现脸上的泪水，而牵挂、担心，而假装低头；“含羞”是别时有千言万语却有无从说起，欲说还休，难于启齿。这两句通过白描手法，生动地再现了送别时女子玲珑剔透的面部表情，细腻真实的心理活动。\n\n　　下片抒别后眷念。“不知魂已断”，是过片。“魂断”即“魂销”，江淹《别赋》云：“黯然消魂者，唯别而已。”紧扣上片“别君时”，承上；只好“空有梦相随”，启下，过渡自然，不留痕迹。“不知”故作糊涂，实指知，但比知更深更悲。知是当时，是如今，还是这一年，却又不知。事实上，三者已融于一起，无从分别，也无需分别。君去人不随，也不能随，只好梦相随。日有所思，夜有所梦，但这里的梦是凄苦的，是在无法选择的前提下，不得不选择聊以慰藉的方式，可见相思之深，相思之苦，相思之无奈。“除却天边月，无人知。”“天边月”与首句“四月十七”在时间上相应。“无人知”即是不知，重复上文，加强凄苦。魂销梦断都无法派遣相思之苦，那就只有对月倾诉了，这是古人常用的寄托方式，没有人知道，但明月知道，不仅知，还理解，更会把这一切记住，作为见证。在少女的心目中，月竟成了她在人间的唯一知己，这是十分无奈的选择，更见其孤独，寂寞。况且明月的“知“，本是子虚乌有。寄托相思，相思却更浓，排遣相思，相思却更深。真是欲哭无泪，欲罢不能。少女受相思折磨，为相思煎熬，楚楚动人，愈发憔悴的形象跃然纸上，让人为之流泪。\n\n　　这首词也可以看成是男子的回忆。刘永济先生《唐五代两宋词简析》评道：“此二首（包括后一首《女冠子·昨夜夜半》）乃追念其宠姬之词。前首是回忆临别时情事，后首则梦中相见之情事也。明言‘四月十七’者，姬人被夺之日，不能忘也。”', poem_tags = '宋词三百首,爱情,离别,相思' WHERE poem_title = '女冠子·四月十七' AND poem_author = '韦庄';
UPDATE edu_poem SET poem_translation = '我独自一人来到这江边的高楼，我思绪纷然好像有满腹的忧愁。\n我看见月光就像是水一般流淌，流淌的水又像是天空茫茫悠悠。\n我还记得我们曾经一同来望月，而如今同来的你们又在哪勾留？\n要知道这江楼水光相接的风景，和去年所见一样幽美一样轻柔。', poem_notes = '江楼：江边的小楼。感旧：感念旧友旧事。\n思渺然：思绪怅惘。渺（miǎo）然：悠远的样子。\n依稀：仿佛；好像。', poem_appreciation = '此诗是唐人赵嘏的作品，原沈阳师范学院中文系教授徐竹心先生认为：这是一首情味隽永、淡雅洗炼的好诗。\n\n　　在一个清凉寂静的夜晚，诗人独自登上江边的小楼。“独上”，透露出诗人寂寞的心境；“思渺然”三字，又形象地表现出他那凝神沉思的情态。而对于诗人在夜阑人静的此刻究竟“思”什么的问题，诗人并不急于回答。第二句，故意将笔移开去从容写景，进一层点染“思渺然”的环境气氛。登上江楼，放眼望去，但见清澈如水的月光，倾泻在波光荡漾的江面上，因为江水是流动的，月光就更显得在熠熠闪动。“月光如水”，波柔色浅，宛若有声，静中见动，动愈衬静。诗人由月而望到水，只见月影倒映，恍惚觉得幽深的苍穹在脚下浮涌，意境显得格外幽美恬静。整个世界连同诗人的心，好像都溶化在无边的迷茫恬静的月色水光之中。这一句，诗人巧妙地运用了叠字回环的技巧，一笔包蕴了天地间景物，将江楼夜景写得那么清丽绝俗。这样迷人的景色，一定使人尽情陶醉了吧。然而，诗人却道出了一声声低沉的感喟：“同来望月人何处？风景依稀似去年。”“同来”与第一句“独上”相应，巧妙地暗示了今昔不同的情怀。原来诗人是旧地重游。去年也是这样的良夜，诗人结侣来游，凭栏倚肩，共赏江天明月，那是非常欢快的。曾几何时，人事蹉跎，昔日伴侣不知已经飘泊何方，而诗人却又辗转只身来到江楼。面对依稀可辨的风物，缕缕怀念和怅惘之情，正无声地啃啮着诗人孤独的心。写到这里，诗意豁然开朗，篇首“思渺然”的深远意蕴得到充分展示，诗人江楼感旧的旨意也就十分清楚了。\n\n　　短小的绝句律诗，一般不宜写得太实，而应“实则虚之”，这才会有余情余味。这首诗，诗人运笔自如，赋予全篇一种空灵神远的艺术美，促使读者产生无穷的联想。诗中没有确指登楼的时间是春天还是秋天，去年的另一“望月人”是男还是女，是家人、情人还是朋友，“同来”是指点江山还是互诉情衷，离散是因为世乱飘荡还是情有所阻，这一切都隐藏在诗的背后。只有充分发挥想象，才能充分领略这首小诗的幽韵和醇美。', poem_tags = '孤独,怀念,友人' WHERE poem_title = '江楼旧感 / 江楼感旧' AND poem_author = '赵嘏';
UPDATE edu_poem SET poem_translation = '犹如二龙争战以决雌雄，赤壁一战，曹操的楼船被一扫而空。烈火熊熊焰烟冲天，照耀云海，周瑜于此地大破曹公。\n君去大江观看青碧澄明的江水，看到了当时留下的大鲸演行争斗的遗迹。请您将实地的观感一一写信给我，使我看过信后也大快一下壮心。', poem_notes = '⑴二龙：指争战之双方。此指曹操和孙权。雌雄：指输赢。\n⑵“赤壁”句：建安十二年（208年），刘备与孙权联合与曹操在赤壁作战。周瑜用黄盖诈降计，“盖放诸船同时发火，时风威猛，悉延烧岸上营落。顷之，烟炎涨天，人马烧溺死者甚众”（见《三国志·吴书·周瑜传》。\n⑶沧江：指长江，因古时长江较清澈呈青苍色，故称。望：一作“弄”。\n⑷鲸鲵：大鱼名，比喻吞食小国的不义之人。《左传·宣公十二年》“古者明王伐不敬。取其鲸鲵而封之，以为大戮。”杜预注：“鲸鲵，人鱼名，以喻不义之人吞食小国。”此指曹操与孙刘联军鏖兵的军队。', poem_appreciation = '从此诗题目可以看出，诗人的创作意图在于把歌咏赤壁和送别友人这两个内容艺术地统一起来，并突出前者。\n\n　　全诗八句，前四句讲的是赤壁之战的事迹，后四句则是送别时的有感而发，形式上组成两个相对独立的段落。使人惊异的是，李白在前半短短四句中，就成功地完成了咏史的任务。\n\n　　“二龙争战决雌雄，赤壁楼船扫地空。”赤壁之战，曹操用大量军队，深入东吴国土，一心要同周瑜“决”战，“争”雌雄。周瑜虽处于劣势，但能化不利为有利，以火攻取胜，曹操只落得全军溃败的下场。上述内容在这两句诗里艺术地得到表现。上句化用《周易》里“龙战于野”的典故。“二龙争战”是魏吴相持的象征。下句以突如其来之笔，直接写出了赤壁之战曹操水师以失败告终的结局。“楼船扫地空”五字颇见妙思。曹军楼船云集江面，构成庞大的水上阵地，自谓坚如金城。不料这阵“地”顷刻间就被横“扫”一“空”。诗人不说楼船在水上安营，而说在“地”上扎寨，这既是对曹操水师在吴地彻底完蛋的如实刻画，也是对他吞并东吴土地梦想落空的含蓄讽刺。\n\n　　“烈火张天照云海，周瑜于此破曹公。”前面诗人用“楼船扫地空”五字预示了战争的结局。这两句才把造成这结局的缘由具体说出。但“烈火”句绝不仅仅是对“楼船扫地空”的原因的说明，更重要的是对古战场上赤焰烧天，煮水蒸云，一片火海的景象的真实写照。上句“张”“照”二字，极大地渲染了吴军的攻势。诗人把因果关系颠倒处理，既起到了先声夺人的作用，也显示了诗人对稳操胜券者的辉煌战果的深情赞许。赤壁之战的胜败，成因固然是吴方采用火攻法，但归根到底取决于两军统帅在战略战术上的水平。下句诗人以凝重之笔指出：善于决战决胜的周瑜，就是这样从容不迫地在赤壁山下击破曹操几十万大军的。这句虽然加入了议论成分，但周瑜的儒将风度，却朴实自然地表现出来了。\n\n　　后半的送别，是在咏史的基础上进行的。字数虽与前半相等，实则等于前半的附庸。“君去沧江望澄碧”，这位友人就要离他而去，望着清澄碧绿的江波，少不了要兴起南浦送别的感伤。但古战场上“二龙争战”的“馀迹”还在脑际留存。“鲸鲵唐突留馀迹。”“鲸鲵”，是由《左传》上的典故引起的联想。“鲸鲵”是“大鱼名”，以喻那“吞食小国”的“不义之人”。“唐突”义同触犯。这里李白大约是喻指曹操倚仗权势，想吞食东吴。李白在送别的诗行中，并没有完全割裂咏史的情感线索。但诗人又立即回到现实中来，“一一书来报故人”，希望友人走后经常来信报告佳音。这友人想必是一位有功业抱负的人物。所以诗人在结尾写道：“我欲因之壮心魄。”诗人能从友人那里得到鼓舞人心的信息，可以因之而大“壮”自己的“心”胆与气“魄”。\n\n　　李白早年就有“大定”“寰区”（《代寿山答孟少府移文书》）的政治抱负，这首诗在一定程度上反映出他壮年时代济世救民的思想感情。此诗把咏史与送别结合起来并特别突出前者，原因就在这里。\n\n　　此诗韵脚“平仄相半”，在形式上与王勃《滕王阁诗》一类“初唐短歌”相似。但避用律体，变婉丽和平之调为慷慨雄壮之声，这又是与王勃异趣的。', poem_tags = '地名,咏史怀古,送别' WHERE poem_title = '赤壁歌送别' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '红色的桃花还含着隔夜的新雨，碧绿的柳丝更带着淡淡的春烟。\n花瓣凋落家中的小童没有打扫，黄莺啼叫闲逸的山客犹自酣眠。', poem_notes = '宿雨：昨夜下的雨。\n朝烟：指清晨的雾气。\n家童：童仆。\n山客：隐居山庄的人，这里指诗人自己。\n犹眠：还在睡眠。', poem_appreciation = '诗中写到春“眠”、“莺啼”、“花落”、“宿雨”，与孟浩然的五绝《春晓》相似。两首诗写的生活内容有那么多相类之处，而意境却很不相同。彼此相较，最易见出王维此诗的两个显著特点。\n\n　　第一个特点是绘形绘色，诗中有画。这并不等于说孟诗就无画，只不过孟诗重在写意，虽然也提到花鸟风雨，但并不细致描绘，它的境是让读者从诗意间接悟到的。王维此诗可完全不同，它不但有大的构图，而且有具体鲜明的设色和细节描画。写桃花、柳丝、莺啼，捕捉住春天富于特征的景物，这里，桃、柳、莺都是确指，比孟诗一般地提到花、鸟更具体，更容易唤起直观印象。通过“宿雨”、“朝烟”来写“夜来风雨”，也有同样的艺术效果。在勾勒景物基础上，进而有着色，“红”、“绿”两个颜色字的运用，使景物鲜明怡目。读者眼前会展现一派柳暗花明的图画。“桃之夭夭，灼灼其华”，加上“杨柳依依”，景物宜人。着色之后还有进一层渲染：深红浅红的花瓣上略带隔夜的雨滴，色泽更柔和可爱，雨后空气澄鲜，弥散着冉冉花香；碧绿的柳丝笼在一片若有若无的水烟中，更袅娜迷人。经过层层渲染、细致描绘，诗境自成一幅工笔重彩的图画；相比之下，孟诗则似不着色的写意画。一个妙在有色，一个妙在无色。孟诗从“春眠不觉晓”写起，先见人，后入境。王诗正好相反，在入境后才见到人。因为有“宿雨”，所以有“花落”。花落就该打扫，然而“家童未扫”。未扫非不扫，乃是因为清晨人尚未起的缘故。无人过问满地落花的情景，别有一番清幽的意趣。这正是王维所偏爱的境界。“未扫”二字有意无意得之，毫不着力，浑然无迹。末了写到“莺啼”，莺啼却不惊梦，山客犹自酣睡，这正是一幅“春眠不觉晓”的入神图画。但与孟诗又有微妙的差异，孟诗从“春眠不觉晓”写起，其实人已醒了，所以有“处处闻啼鸟”的愉快和“花落知多少”的悬念，其意境可用“春意闹”的“闹”字概括。此诗最后才写到春眠，人睡得酣恬安稳，于身外之境一无所知。花落莺啼虽有动静有声响，只衬托得“山客”的居处与心境越见宁静，所以其意境主在“静”字上。王维之“乐”也就在这里。崇尚静寂的思想固有消极的一面，然而，王维诗难能可贵在它的静境与寂灭到底有不同。他能通过动静相成，写出静中的生趣，给人的感觉仍是清新明朗的美。唐诗有意境浑成的特点，但具体表现时仍有两类，一种偏于意，如孟诗《春晓》就是；另一种偏于境，如此诗就是。而由境生情，诗中有画。是此诗最显著优点。\n\n　　第二个特点是对仗工致，音韵铿锵。孟诗《春晓》是古体五言绝句，在格律和音律上都很自由。由于孟诗散行，意脉一贯，有行云流水之妙。此诗则另有一工，因属近体六言绝句，格律极精严。从骈偶上看，不但“桃红”与“柳绿”、“宿雨”与“朝烟”等实词对仗工稳，连虚字的对仗也很经心。如“复”与“更”相对，在句中都有递进诗意的作用；“未”与“犹”对，在句中都有转折诗意的作用。“含”与“带”两个动词在词义上都有主动色彩，使客观景物染上主观色彩，十分生动。且对仗精工，看去一句一景，彼此却又呼应联络，浑成一体。“桃红”、“柳绿”，“宿雨”、“朝烟”，彼此相关，而“花落”句承“桃”而来，“莺啼”句承“柳”而来，“家童未扫”与“山客犹眠”也都是呼应着的。这里表现出的是人工剪裁经营的艺术匠心，画家构图之完美。对仗之工加上音律之美，使诗句念来铿锵上口。中国古代诗歌以五、七言为主体，六言绝句在历代并不发达，佳作尤少，王维的几首可以算是凤毛麟角了。', poem_tags = '田园' WHERE poem_title = '田园乐七首·其六 / 闲居' AND poem_author = '王维';
UPDATE edu_poem SET poem_tags = '小学文言文,寓言,故事,哲理' WHERE poem_title = '承宫樵薪苦学' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '北方的鸿雁悠然自在，从太湖西畔随着白云飘浮。几座孤峰萧瑟愁苦，好像在商量黄昏是否下雨。\n我真想在第四桥边，跟随天随子一起隐居。可他如今在何处？我独倚栏杆缅怀千古，只见衰柳参差风中飞舞。', poem_notes = '丁未：即公元1187年（宋孝宗淳熙十四年）。吴松：即今吴江市，属江苏省。\n燕雁：指北方幽燕一带的鸿雁。燕雁无心：羡慕飞鸟的无忧无虑，自由自在。\n太湖：江苏南境的大湖泊。\n商略：商量、酝酿。\n第四桥：即吴松城外的甘泉桥。\n天随：晚唐陆龟蒙，自号天随子。\n何许：何处，何时。', poem_appreciation = '姜夔论诗有四素：气象、体面、血脉、韵度。对四者的要求且是“气象欲其浑厚”、“体面欲其宏大”、“血脉欲其贯通”、“韵度欲其飘逸”。虽是论诗之语，移之于词，也甚贴切。读此词，知其所言非虚。此词之意境，呈为一宇宙。\n\n　　上片之境，乃词人俯仰天地之境。“燕雁无心”。燕念平声（yān烟），北地也。燕雁即北来之雁。时值冬天，正是燕雁南飞的时节。陆龟蒙咏北雁之诗甚多，如《孤雁》：“我生天地间，独作南宾雁。”《归雁》：“北走南征象我曹，天涯迢递翼应劳。”《京口》：“雁频辞蓟北。”《金陵道》：“北雁行行直。”《雁》：“南北路何长。”白石诗词亦多咏雁，诗如《雁图》、《除夜》，词如《浣溪沙》及此词。可能与他多年居无定所，浪迹江湖的感受及对龟蒙的万分心仪有关。劈头写入空中之燕雁，正是暗喻飘泊之人生。无心即无机心，犹言纯任天然。点出燕雁随季节而飞之无心，则又喻示自己性情之纯任天然。此亦化用龟蒙诗意。陆龟蒙《秋赋有期因寄袭美》：“云似无心水似闲。”《和袭美新秋即事》：“心似孤云任所之，世尘中更有谁知。”下句紧接无心写出：“太湖西畔随云去。”燕雁随着淡淡白云，沿着太湖西畔悠悠飞去。燕雁之远去，暗喻自己飘泊江湖之感。随云而无心，则喻示自己纯任天然之意，宋陈郁《藏一话腴》云：白石“襟期洒落，如晋宋间人。语到意工，不期于高远而自高远。”范成大称其“翰墨人品，皆似晋宋之雅士。”张羽《白石道人传》亦曰其“体貌轻盈，望之若神仙中人。”但白石与晋宋名士实有不同，晋宋所谓名士实为优游卒岁的贵族，而白石一生布衣，又值南宋衰微之际，家国恨、身世愁实非晋宋名士可比。故下文写出忧国伤时之念。太湖西畔一语，意境阔大遥远。太湖包孕吴越，“天水合为一”（陆龟蒙《初入太湖》）。此词意境实与天地同大也。“数峰清苦。商略黄昏雨。”商略一语，本有商量之义，又有酝酿义。湖上数峰清寂愁苦，黄昏时分，正酝酿着一番雨意。此句的数峰之清苦无可奈何反衬人亡万千愁苦。从来拟人写山，鲜此奇绝之笔。比之辛稼轩之“我见青山多妩媚，料青山，见我应如是”（《虞美人》），又是不同的况味。\n\n　　下片之境，乃词人俯仰今古之境。“第四桥边，拟共天随住。”第四桥即“吴江城外之甘泉桥”（郑文焯《绝妙好词校录》），“以泉品居第四”故名（乾隆《苏州府志》）。这是陆龟蒙的故乡。《吴郡图经续志》云：“陆龟蒙宅在松江上甫里。”松江即吴江。天随者，天随子也，龟蒙之自号。天随语出《庄子。在宥》“神动而天随”，意即精神之动静皆随顺天然。龟蒙本有胸怀济世之志，其《村夜二首》云：“岂无致君术，尧舜不上下。岂无活国力，颇牧齐教化。”可是他身处晚唐末世，举进士又不第，只好隐逸江湖。白石平生亦非无壮志，《昔游》诗云：“徘徊望神州，沉叹英雄寡。”《永遇乐》：“中原生聚，神京耆老，南望长淮金鼓。”但他亦举进士而不第，飘泊江湖一生。此陆、姜二人相似之一也。龟蒙精于《春秋》，其《甫里先生传》自述：“性野逸无羁检，好读古圣人书，探大籍识大义”，“贞元中，韩晋公尝著《春秋通例》，刻之于石”，“而颠倒漫漶翳塞，无一通者，殆将百年，人不敢指斥疵纇，先生恐疑误后学，乃著书摭而辨之。”白石则精于礼乐，曾于南宋庆元三年“进《大乐议》于朝”，时南渡已六七十载，乐典久已亡灭，白石对当时乐制包括乐器乐曲歌辞，提出全面批评与建树之构想，“书奏，诏付太常。”（《宋史·乐志六》）以布衣而对传统文化负有高度责任感，此二人又一相同也。正是这种精神气质上的认同感，使白石有了“沉思只羡天随子，蓑笠寒江过一生”（《三高祠》诗），及“三生定是陆天随”（《除夜》诗）之语。第四桥边，拟共天随住，即是这种认同感的体现。\n\n　　第四桥边，其地仍在，天随子，其人则往矣。中间下拟共二字，便将仍在之故地与已往之古人与自己连结起来，泯没了古今时间之界限。这是词人为打破古今局限寻求与古人的精神句诵而采取的特殊笔法。再如刘过《沁园春》之与东坡、乐天、林和靖交游，亦是此一笔法。以上写了自然、人生、历史，笔笔翻出新意结笔更写出现时代，笔力无限。“今何许”三字，语意丰富，涵盖深广。何许有何时、何处、为何、如何等多重含义。故“今何许”包含今是何世、世运至于何处、为何至此、如何面对等意。此是囊括宇宙、人生、历史、时代之一大反诘，是充满哲学反思意味一大反诘。而其中重点，主要在“今”之一字。凭栏怀古，笔力雄劲，气象阔大。古与今上下映照成文，补足“今何许”一大反诘之历史意蕴。应知此地古属吴越，吴越兴亡之殷鉴，曾引起晚唐龟蒙之无限感慨：“香径长洲尽棘丛，奢云艳雨只悲风。吴王事事须亡国，未必西施胜六宫。”（《吴宫怀古》）亦不能不引起南宋白石之无限感慨：“美人台上昔欢娱，今日空台望五湖。残雪未融青草死，苦无麋鹿过姑苏。”（《除夜》）\n\n　　怀古正是伤今。“残柳参差舞，”柳本纤弱，那堪又残，故其舞也参差不齐，然而仍舞之不已。舞之一字执著有力，苍凉中寓含悲壮，悲壮中透露苍凉。“残柳参差舞”这一自然意象，实际上是南宋衰世的象征，隐然包含着虽已残破仍不甘灭亡的意味。这与李商隐《登乐游原》“夕阳无限好，只是近黄昏”，象征唐朝国运的不可挽回有同工之妙。而其作为自然意象之本身，则又补足“今何许”一大反诘之自然意蕴。结笔之意境，实为南宋国运之写照。返观数峰清苦二句，其意蕴正为结尾之伏笔。在此九年之前，辛稼轩作《摸鱼儿》，结云：“休去倚危栏，斜阳正在烟柳断肠处。”乃是同一意境。白石本词用舞字结穴，蕴含无限苍凉悲壮。\n\n　　善于提空描写，从虚处着笔，是白石词的一大特点。此词将身世之感、家国之恨融为一片，乃南宋爱国词中无价瑰宝。而身世家国皆以自然意象出之，自然意象在词中占优势，又将自然、人生、历史（尚友天随与怀古）、时代打成一片，融为一体。\n\n　　尤其“今何许”之一大反诘，其意义虽着重于今，但其意味实远远超越之，乃是词人面对自然、人生、历史、时代所提出之一哲学反思。全词意境遂亦提升至于哲理高度。“今何许”，真可媲美于《桃花源记》“问今是何世”，《登幽州台歌》“前不见古人，后不见来者”。这首词无限感慨，全在虚处，正是“意愈切而词愈微”，这种写法，易形成自我抒写之形象与所写之意象间接开距离，造成朦胧之美感。此词声情之配合亦极精妙。上片首句首二字燕雁为叠韵，末句三四字黄昏为双声，下片同位句同位字第四又为叠韵，参差又为双声。分毫不爽，自然天成。双声叠韵之回环，妙用在于为此一尺幅短章增添了声情绵绵无尽之致。', poem_tags = '宋词三百首,婉约,怀古' WHERE poem_title = '点绛唇·丁未冬过吴松作' AND poem_author = '姜夔';
UPDATE edu_poem SET poem_appreciation = '这首词作于建炎三年，是一首寄寓南渡之恨的力作。\n\n　　上片首句“永夜恹恹欢意少”开门见山。南渡以后，清照隽永含蓄的风格，一变而为沉郁苍凉。上巳虽是传统的水边修禊节日，但词人此时心情不愉，欢意甚少。“空梦长安，认取长安道”，写长夜辗转反侧，梦见汴京，看到汴京的宫阙城池，然而实不可到，故说“空”，抒写对汴京被占的哀思和沉痛。\n\n　　“为报今年春色好，花光月影宜相照”写今年的自然春色和往年一样好，而今年的政局远远不如从前了。“为报”二字，点明这春天的消息是从他人处听来的，并非词人游春所见。实际上是说，今年建康城毫无春意，虽是朝花夜月如故，而有等于无。“宜相照”的“宜”字，作“本来应该”解。“相照”前著一“宜”字，其意似说它们没有相照，更确切一点，是词人对此漫不经心，反映出她的忧闷。\n\n　　“随意杯盘虽草草。酒美梅酸，恰称人怀抱”承上启下，点明题旨，透露了女主人公并无心过好这个上巳节日，酸梅酿成的酒，和自己辛酸的怀抱是相称的。这两句，貌似率直，其实极婉转，极沉痛。\n\n　　“醉里插花花莫笑，可怜春似人将老”，这里把“花”拟人化。“花莫笑”，就是不要笑我老大不小还插花，这一层词意，与末句“可怜春似人将老”紧接，意思是说最需要怜念的是春天也像人一样快要衰老了。“春”暗喻“国家社稷”，“春将老”暗喻“国将沦亡”。\n\n　　《蝶恋花》是一首六十字的词，这首词题是“上巳召亲族”，带含丰富的思想内容，深厚的感伤情绪，写得委婉曲折，层层深入而笔意浑成，具有长调铺叙的气势。写出作者的国破家亡之恨，寄寓词人对国家社稷的赤子之情', poem_tags = '爱国,哀思' WHERE poem_title = '蝶恋花·上巳召亲族' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '王维乘坐着小船迎接贵宾，小船在湖上悠然开来。\n宾主围坐临湖亭开怀畅饮，四周一片盛开的莲花。', poem_notes = '轻舸（gě）：轻便的小船。吴楚江湘一带方言，称船为舸。 上客。尊贵的客人。\n芙蓉：此指荷花，即水芙蓉。\n当轩。临窗。轷。有窗的长廊。樽（zūn）：盛酒的器具。', poem_appreciation = '赏析 　　以摩诘之敏感与淡怀难得有此情趣盎然之作。此诗颇同《山居秋瞑》“竹喧”“莲动”之意。然“竹喧”“莲动”是从他人着笔，而此诗则是自我抒怀。与“上客”挚友相约湖上一游，良辰、美景、高朋，人生之快哉莫过如此。诗中最为精彩处乃最后一句，此本为唐诗小绝句之惯例，喜以收束处点缀二三意象，以达言尽无穷之效。技法众人皆，唯如何遣词造句则有凡圣之异。“四面”显景色之开阔以见心境之敞亮。芙蓉之嫣然，映衬游客之欢颜。诗人轻松欢快之情韵传播于辞章，使小诗亦随之简明单纯，无甚深意揣摩，只以清新自然得一时之欢然欣悦。此类风调甚似孟襄阳之作，世以“王孟”并称，即多着意于此。襄阳思虑单纯，酣然以乐，无幽思而多甜美。心田得此滋润，无须深意仍能回味萦怀。稍有不同处，襄阳乐之欢畅，故而兴高而采烈。摩诘思虑深沉，难得有此闲淡。因此心性，而淡然以欢并无神采飞扬之色。襄阳亦是“开轩面场圃”，但末尾仍不忘叮咛“待到重阳日，还来就菊花”，可见其兴致之高昂。而摩诘只一“四面芙蓉开”，点到为止，幽喜意俱在无言之中。▲', poem_tags = '写景,宴饮,抒情' WHERE poem_title = '临湖亭' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '狐狸在那慢慢走，就在淇水石桥上。我的心里真忧愁，你的身上没衣裳。\n狐狸在那慢慢走，就在淇水浅滩上。我的心里真忧愁，你没腰带不像样。\n狐狸在那慢慢走，就在淇水河岸旁。我的心里真忧愁，你没衣服我心伤。', poem_notes = '狐：狐狸。一说狐喻男性。\n绥（suí）绥：慢走貌。朱熹《诗集传》训为独行求匹貌。\n淇：卫国水名。淇水在今河南浚县东北。梁：河梁。河中垒石而成，可以过人，可用于拦鱼。\n之子：这个人，那个人。裳（cháng）：下身的衣服。上曰衣，下曰裳。\n厉：水深及腰，可以涉过之处。一说通“濑”，指水边沙滩。\n带：束衣的带子。实指衣服。\n侧：水边。\n服：衣服。', poem_appreciation = '这是一首情诗。有人把它理解为妻子担忧在外的丈夫没有御寒衣物的诗，则诗以主人公看见有狐开篇，以狐之绥绥，来比久役于外的丈夫茕茕孑立、形影相吊之貌。只见有一只身材单薄的狐狸，狐独地散漫地出没在淇河水落石出的地方。这应该是一幅冷清的秋天的景象，淇水河边，水落石出，狐狸身单影只地行走在石梁上。见此情景，女主人公心里对丈夫的担忧油然而生，他想到那久役于外的丈夫还没有御寒的下裳。\n\n　　全诗一唱三叹，每章只更换两个字，反复强化，深入地表达担忧之情。狐狸走在水浅的地方，湿了腿脚，由此想到自己男人还没有束紧衣裤的带子呢。狐狸走在河的岸边，完全没有弄湿身上，她就想到丈夫还没有成身的衣服呢。随着视线所及，看到狐狸从水落石出的地方，一步步走到岸上来，她就想到丈夫该穿什么衣物，真可谓知冷知热。从这个角度上说，此诗是贤妇人惦念远方丈夫冷暖的佳作。\n\n　　有人把此诗解为寡妇表白有心求偶之情，也可通。狐为妖媚之兽，诗人称此妇为“狐”，看来此妇也颇有风姿，诗人以诗揭露其心事，比之为狐、以物喻人，别饶风致。全诗三章，皆用比意。\n\n　　首章言“有狐绥绥，在彼淇梁”，梁为石不沾水之处，在梁则可以穿好下裳，所以这多情的寡妇，以有狐求偶，对其所怜惜的鳏夫，表白自我的爱心说：“我心里所忧愁的，是那人还无以为裳，若是他娶了我他就可以不愁没有衣裳了。”次章言“有狐绥绥，在彼淇厉”，“厉”为深水可涉之处。《邶风·匏有苦叶》诗云：“深则厉，浅则揭”，涉过深水。需要有衣带束衣。此妇担心的，是心上所爱慕的那人还没有衣带。她想：“若是我嫁给他，我可以替他结成衣带他就不愁涉过深水时没有衣带了。”三章言此狐“在彼淇侧”，既然已在淇侧，可见已经渡过淇水，可以穿好衣服了。可是她担心那个人，还无以为服，她心想：“若是我和他结为婚姻，那么，那人就不愁没有衣服了。”\n\n　　这三章诗充分而细致地表露了这位年青寡妇的真挚爱心，即事抒怀，不作内心的掩蔽，大胆吐露真情，自是难得的佳作。在旧时代，遭逢丧乱，怨女旷夫，在各自失去配偶之后，想重建家庭，享受室家之爱，这是人生起码的要求，自然是无可非议的。这首诗，表白了寡妇有心求偶之情，在《国风》中是一首独特的爱情诗。至于此妇所爱慕的对方，是否已经觉察到她的爱心，以及如何作相应的表态，那是另外的事了。', poem_tags = '诗经' WHERE poem_title = '有狐' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '细雨霏霏，浸湿了光阴，芳草萋萋，年复一年，与离恨一起生长。凤楼深深，多少情事如烟，封存在记忆之中。恍如隔世呦，望着饰有鸾鸟图案的铜镜，绣着鸳鸯的锦被，思念往事，寸断肝肠。\n梦魂，信马由缰，千里飘荡，魂回梦觉，蓦然见杨花点点，飘满绣床。薄情负心的人呀，我半掩闺门，你却迟迟不来，夕阳西下，眼看辜负了三春的良辰美景，洒下清淡的泪珠几行。', poem_notes = '流光：流动，闪烁的光采。\n凤楼：即凤台、秦楼，语本《列仙传》秦穆公之女弄玉所 居之楼，尝引来凤凰。此处指妆楼。\n鸾镜：妆镜的美称。\n薄悻：薄情郎。', poem_appreciation = '“细雨湿流光”，虽则五字，却道尽了初春的无限风光。细雨蒙蒙，洒落在春草叶上，留下滴滴水珠，微风吹过，泛起流光。“湿流光”意指主人公所度过的随春雨而流逝的岁月也是那样的冷涩恼人，正是“梧桐更兼细雨”“怎一个愁字了得”。“流光”一词还将冷凄扰人的静态烦闷与时光流逝的动态惧忧结合起来，冷寂独处的日子往往感觉太慢，本希望快点度过，可是女人出于青春容颜易老的心理却又希望时间慢慢流逝。而“流光”一词又给人快速流去的感觉，如此矛盾纠结的心理集于此短短五个字中。在表现爱情相思苦闷的同时，还渗透着一种人生苦短的生命忧患意识。“芳草年年与恨长”也是以具象表现抽象的妙句，将无形的离恨比托于年年生、年年长的芳草，可感可触，极形象地道出抒情主人公忍受长久离别的痛苦。\n\n　　“烟锁凤楼无限事，茫茫”。一方面，它确切地描绘出了春天细雨绵绵之时。烟雾缭绕，茫茫一片的景象；另一方面，雾笼凤楼，人如同被困锁在无人知晓的地方，无限心事，茫茫无以倾诉。两相对照，景情交融，给读者的感染力就非常之深。\n\n　　“鸾镜鸳衾两断肠”。鸾凤成双，鸳鸯成对，“鸾镜鸳衾两断肠”中的这个“两”字既有两两成偶之物与自身形单影只的对比，也包含着两对成双之物对自身孤独情怀的连续刺激，语意双关，极有意蕴。\n\n　　“魂梦任悠扬，睡起杨花满绣床”。“魂梦任悠扬” ，是对“烟锁凤楼”的反弹，禁锢在空闺中的少妇在梦中可以无拘无束，任情驰骋。可睡起所能看到的只是“杨花满绣床”。“杨花满绣床”与上句“魂梦任悠扬”相印相称，一虚一实，互文见义。从这两句所描述的情景看来，思妇魂牵梦萦的意中人杳不见踪影。洒脱之余，更显悲凉。\n\n　　“薄悻不来门半掩，斜阳”。她半掩闺门，等待恋人的到来，可是从清晨等到红日西斜，还未见踪影，她忍不住骂了一声“薄情郎”。爱之深，方恨之切。她口头称为“薄悻”，内心深处爱的深切。\n\n　　“负你残春泪几行”。当无望中的盼望最终落空时，她便簌簌的落下泪来。词人不说抒情主人公是为所思之人流泪，而说因辜负了三春的良辰美景而为春光洒泪。此为本词又一出新的写法，同时也是对抒情主人公心怀的一种委婉诗意的表达。', poem_tags = '怨妇,思归' WHERE poem_title = '南乡子·细雨湿流光' AND poem_author = '冯延巳';
UPDATE edu_poem SET poem_translation = '阿房宫内罗袖翻飞，歌舞升平；金谷园里玉楼拔地，再添新景；隋堤上古柳葱郁，江中龙舟显威名。往事难回首，东风又起，暮春时候一片凄清。\n美人虞姬自尽在乌江岸边，战火也曾焚烧赤壁万条战船，将军班超徒然老死在玉门关。伤心秦汉的烽火，让百万生民涂炭，读书人只能一声长叹。', poem_notes = '阿房（旧读ēpáng）：公元前212年，秦始皇征发刑徒七十余万修阿房宫及郦山陵。阿房宫仅前殿即“东西五百步，南北五十丈；上可以坐万人，下可以建五丈旗；周驰为阁道，自殿下直抵南山”（《史记·秦始皇本纪》）。但实际上没有全部完工。全句大意是说，当年秦始皇曾在华丽的阿房宫里观赏歌舞，尽情享乐。\n金谷名园：在河南省洛阳市西面，是晋代大官僚大富豪石崇的别墅，其中的建筑和陈设异常奢侈豪华。\n隋堤古柳：隋炀帝开通济渠，沿河筑堤种柳，称为“隋堤”，即今江苏以北的运河堤。缆龙舟：指隋炀帝沿运河南巡江都（今扬州市）事。\n东风还又：现在又吹起了东风。这里的副词“又”起动词的作用，是由于押韵的需要。\n“美人”句：言楚汉相争时项羽战败自刎乌江。公元前202年，项羽在垓下（今安徽灵璧县东南）被汉军围困。夜里，他在帐中悲歌痛饮，与美人虞姬诀别，然后乘夜突出重围。在乌江（今安徽和县东）边自刎而死。这里说美人自刎乌江，是这个典故的活用。\n“战火”句：言三国时曹操惨败于赤壁。公元208年，周瑜指挥吴蜀联军在赤壁之战中击败曹操大军。\n“将军”句：言东汉班超垂老思归。班超因久在边塞镇守，年老思归，给皇帝写了一封奏章，上面有两句是：“臣不敢望到酒泉郡（在今甘肃），但愿生入玉门关”。见《后汉书·班超传》。\n秦汉：泛指历朝历代。\n涂炭：比喻受灾受难。涂，泥涂；炭，炭火。', poem_appreciation = '这组曲子由两首小令曲组成。下面是四川大学文学与新闻学院教授周啸天先生对这组曲的赏析。\n\n　　令曲与传统诗词中的绝句与令词，有韵味相近者，有韵味全殊者。这两首怀古的令曲，前一首便与诗词相近，后一首则与诗词相远。\n\n　　第一首曲子开头先用三个典故。一是秦始皇在骊山建阿房宫行乐，二是西晋富豪石崇筑金谷园行乐，三是隋炀帝沿运河南巡江都游乐。这三个典故都是穷奢极欲而不免败亡的典型。但这组仅仅典出事情的发端而不说其结局。“不堪回首”四字约略寓慨，遂结以景语：“东风还又，野花开暮春时候。”这是诗词中常用的以“兴”终篇的写法，同时，春意阑珊的凄清景象和前三句所写的繁华盛事形成鲜明对照，一热一冷，一兴一衰，一有一无，一乐一哀，真可兴发无限感慨。这与刘禹锡的七绝《乌衣巷》“朱雀桥边野草花，乌衣巷口夕阳斜。旧时王谢堂前燕，飞入寻常百姓家”有异曲同工之妙。而这首曲子的长短参差，奇偶间出，更近于令词。不过，一开篇就是鼎足对的形式，所列三事不在一时、不在一地且不必关联（但相类属），这是它与向来的“登临”怀古诗词有所不同之处。\n\n　　相比较而言，第二首更有新意。这首在手法上似乎与前首相同，也是列举三事：一是霸王别姬的故事，二是吴蜀破曹的故事，三是班超从戎的故事。看起来这些事彼此毫无逻辑联系，拼凑不伦。然而紧接两句却是“伤心秦汉，生民涂炭”，说到了世世代代做牛做马做牺牲的普通老百姓，可见前三句所写的也有共通的内容。那便是英雄美人或轰烈或哀艳的事迹，多见于载籍，但遍翻二十四史，根本就没有普通老百姓的地位。这一来，作者揭示了一个严酷的现实，即不管哪个封建朝代，民生疾苦更甚于末路穷途的英雄美人。在这种对比上，最后激发直呼的“读书人一声长叹”，也就惊心动魄了。这个结尾句意义深刻且耐人回味。“读书人”可泛指当时有文化的人，也可特指作者本人，他含蓄地要表达这样的含义：其一，用文化人的口吻去感慨历史与现实，寄寓着丰富的感情，有对“风流总被雨打风吹去”、“大江东去，浪淘尽，千古风流人物”的叹惋，有对“兴，百姓苦；亡，百姓苦”的责难，有对“争强争弱，天丧天亡，都一枕梦黄梁”的感伤。其二，用文化人的思想眼光去理解看待历史与现实，能加深作品的思想深度，显得真实准确。最后的“叹”字含义丰富，一是叹国家遭难，二是叹百姓遭殃，三是叹读书人无可奈何。在语言风格上，此曲与前曲的偏于典雅不同，更多运用口语乃至俗语，尤其是最后一句的写法，更是传统诗词中见所未见、闻所未闻的。这种将用典用事的修辞，与俚俗的语言结合，便形成一种所谓的“蒜酪味儿”和“蛤蜊风致”，去诗词韵味远甚。两首相比，这一首是更为本色的元曲小令。\n\n　　这两首怀古元曲，在内容上极富于人民性，无论是抨击社会现实，还是审视历史，都称得上是佳作。', poem_tags = '咏史怀古' WHERE poem_title = '卖花声·怀古' AND poem_author = '张可久';
UPDATE edu_poem SET poem_translation = '参星横北斗转已经快到三更时分，雨绵绵风不停老天爷也应该放睛。\n云忽散月儿明用不着谁人来点缀，长空净沧海色本来就是澄澈清明。\n虽乘船渡大海空怀孔子救世之志，仿佛听到了黄帝成池优美的乐声。\n被贬南荒虽然九死一生吾不悔恨，这次远游是我平生最奇绝的经历。', poem_notes = '参（shēn）横斗转：参星横斜，北斗星转向，说明时值夜深。参，斗，两星宿名，皆属二十八星宿。横，转，指星座位置的移动。\n苦雨终风：久雨不停，终日刮大风。\n“天容”句：青天碧海本来就是澄清明净的。比喻自己本来清白，政乱污陷如蔽月的浮云，终会消散。\n鲁叟：指孔子。乘桴（fú）：乘船。桴，小筏子。据《论语·公冶长》载，孔子曾说：“道（王道）不行，乘桴浮于海。”\n奏乐声：这里形容涛声。也隐指老庄玄理。《庄子·天运》中说，黄帝在洞庭湖边演奏《咸池》乐曲，并借音乐说了一番玄理。轩辕，即黄帝。\n南荒：僻远荒凉的南方。恨：悔恨。\n兹游：这次海南游历，实指贬谪海南。', poem_appreciation = '纪昀评此诗说：“前半纯是比体。如此措辞，自无痕迹。”“比”，即“以彼物比此物”；而“以彼物比此物”，就很难不露痕迹。但这四句诗，却是不露“比”的痕迹的。\n\n　　“参横斗转”，是夜间渡海时所见；“欲三更”，则是据此所作的判断。曹植《善哉行》：“月没参横，北斗阑干。”这说明“参横斗转”，在中原是指天快黎明之时的景象。而在海南，则与此不同，王文诰指出：“六月二十日海外之二、三鼓时，则参已早见矣。”这句诗写了景，更写了人。一是表明“欲三更”，黑夜已过去了一大半；二是表明天空是晴朗的，剩下的一小半夜路也不难走。因此，这句诗调子明朗，可见当时诗人的心境。而在此之前，还是“苦雨终风”，一片漆黑。连绵不断的雨叫“苦雨”，大风叫“终风”。这一句紧承上句而来。诗人在“苦雨终风”的黑夜里不时仰首看天，终于看见了“参横斗转”，于是不胜惊喜地说：“苦雨终风也解晴。”\n\n　　三、四两句，就“晴”字作进一步抒写。“云散月明”，“天容”是“澄清”的；风恬雨霁，星月交辉，“海色”也是“澄清”的。这两句，以“天容海色”对“云散月明”，仰观俯察，形象生动，连贯而下，灵动流走。而且还用了句内对：前句以“月明”对“云散”，后句以“海色”对“天容”。这四句诗，在结构方面又有共同点：短句分两节，先以四个字写客观景物，后以三个字表主观抒情或评论。唐人佳句，多浑然天成，情景交融。宋人造句，则力求洗练与深折。从这四句诗，既可看出苏轼诗的特点，也可看出宋代诗的特点。\n\n　　三、四两句看似写景，而诗人意在抒情，抒情中又含议论。就客观景物说，雨止风息，云散月明，写景如绘。就主观情怀说，始而说“欲三更”，继而说“也解晴”；然后又发一问：“云散月明”，还有“谁点缀”呢？又意味深长地说：“天容海色”，本来是“澄清”的。而这些抒情或评论，都紧扣客观景物，贴切而自然。仅就这一点说，已经是很有艺术魅力的好诗了。\n\n　　然而上乘之作，还应有言外之意。三、四两句，写的是眼前景，语言明净，不会让读者直接觉得得用了典故。但仔细寻味，又“字字有来历”。《晋书·谢重传》载：谢重陪会稽王司马道子夜坐，“于时月夜明净，道子叹以为佳。重率尔曰：‘意谓乃不如微云点缀。’道子戏曰：‘卿居心不净，乃复强欲滓秽太清耶？’”（参看《世说新语·言语》）“云散月明谁点缀”一句中的“点缀”一词，即来自谢重的议论和道子的戏语，而“天容海色本澄清”则与“月夜明净，道子叹以为佳”契合。这两句诗，境界开阔，意蕴深远，已经能给读者以美的感受和哲理的启迪；再和这个故事联系起来，就更能让人多一层联想。王文诰就说：上句，“问章惇也”；下句，“公自谓也”。“问章惇”，意思是：你们那些“居心不净”的小人掌权，“滓秽太清”，弄得“苦雨终风”，天下怨愤。如今“云散明月”，还有谁“点缀”呢？“公自谓”，意思是：章惇之流“点缀”太空的“微云”既已散尽，天下终于“澄清”，强加于他的诬蔑之词也一扫而空。冤案一经昭雪，他这个被陷害的好人就又恢复了“澄清”的本来面目。从这里可以看出，如果用典贴切就可以丰富诗的内涵，提高语言的表现力。\n\n　　五、六两句，转入写“海”。三、四句上下交错，合用一个典故；这两句则显得有变化。“鲁叟”指孔子。孔子是鲁国人，所以陶渊明《饮酒诗》有“汲汲鲁中叟”之句，称他为鲁国的老头儿。孔子曾说过“道不行，乘桴浮于海”（《论语·公冶长》），意思是：我的道在海内无法实行，坐上木筏子飘洋过海，也许能够实行吧！苏轼也提出过改革弊政的方案，但屡受打击，最终被流放到海南岛。在海南岛，“饮食不具，药石无有”，尽管和黎族人民交朋友，做了些传播文化的工作；但作为“罪人”，是不可能谈得上“行道”的。此时渡海北归，回想多年来的苦难历程，就发出了“空余鲁叟乘桴意”的感慨。这句诗，用典相当灵活。它包含的意思是：在内地，他和孔子同样是“道不行”。孔子想到海外去行道，却没去成；他虽然去了，并且在那里呆了好几年，可是当他离开那儿渡海北归的时候，却并没有什么“行道”的实绩值得他自慰，只不过空有孔子乘桴行道的想法还留在胸中罢了。这句诗，由于巧妙地用了人所共知的典故，因而寥寥数字，就概括了曲折的事，抒发了复杂的情；而“乘桴”一词，又准确地表现了正在“渡海”的情景。“轩辕”即黄帝，黄帝奏乐，见《庄子·天运》：“北门成问于黄帝曰：‘帝张咸池之乐于洞庭之野，吾始闻之惧，复闻之怠，卒闻之而惑；荡荡默默，乃不自得。’”苏轼用这个典，以黄帝奏咸池之乐形容大海波涛之声，与“乘桴”渡海的情境很合拍。但不说“如听轩辕奏乐声”，却说“粗识轩辕奏乐声”，就又使人联想到苏轼的种种遭遇及其由此引起的心理活动。就是说：那“轩辕奏乐声”，他是领教过的；那“始闻之惧，复闻之怠，卒闻之而惑”，他是亲身经历、领会很深的。“粗识”的“粗”，不过是一种诙谐的说法，口里说“粗识”，其实是“熟识”。\n\n　　尾联推开一步，收束全诗。“兹游”，直译为现代汉语，就是“这次出游”或“这番游历”，这首先是照应诗题，指代六月二十日夜渡海；但又不仅指这次渡海，还推而广之，指自惠州贬儋县的全过程。1094年（绍圣元年），苏轼抵惠州贬所，不得签书公事。他从1097年（绍圣四年）六月十一日与苏辙诀别、登舟渡海，到1100年（元符三年）六月二十日渡海北归，在海南岛渡过了三个年头的流放生涯。这就是所谓“兹游”。下句的“兹游”与上句的“九死南荒”并不是互不相承的两个概念，那“九死南荒”，即包含于“兹游”之中。不过“兹游”的内容更大一些，它还包含此诗前六句所写的一切。\n\n　　弄清了“兹游”的内容及其与“九死南荒”的关系，就可品出尾联的韵味。“九死”，多次死去的意思。“九死南荒”而“吾不恨”，是由于“兹游奇绝冠平生”，看到了海内看不到的“奇绝”景色。然而“九死南荒”，全出于政敌的迫害；他固然达观，但也不可能毫无恨意。因此，“吾不恨”毕竟是诗的语言，不宜呆看。这句既含蓄，又幽默，对政敌的调侃之意，也见于言外。', poem_tags = '游历,写景,抒情,猖狂' WHERE poem_title = '六月二十日夜渡海' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '冰一样的肌肤，玉一般的身骨，自然是遍身清凉没有汗。宫殿里清风徐来幽香弥漫。绣帘被风吹干，一线月光把佳人窥探。佳人还没有入睡，她斜倚绣枕钗横发乱。\n他起来携着她的小手，走出无声的庭院，随时可见流星横穿河汉。试问夜已多深？已过了三更，月光暗淡，玉绳星向下旋转。她掐着手计算，秋风几时吹来，不知不觉间感到，流年似水，岁月在暗暗变换。', poem_notes = '洞仙歌：词牌名。\n眉州：今在四川眉山境内。\n孟昶：五代时蜀国君主，在位三十一年，后国亡降宋，深知音律，善填词。\n花蕊夫人：孟昶的妃子，别号花蕊夫人；摩诃池：故址在今成都昭觉寺，建于隋代，到蜀国时曾改成宣华池。\n具：通俱，表都的意思。\n足：补足。\n冰肌：肌肤洁白如冰雪，《庄子·逍遥游》有神人焉，肌肤若冰雪，绰约若处子。\n水殿：建在摩诃池上的宫殿。\n欹：斜靠。\n河汉：银河。\n金波：指月光；玉绳：星名，位于北斗星附近。\n玉绳：星名。《太平御览·天部五》引《春秋元命苞》曰：“玉衡北两星为玉绳。玉之为言沟，刻也。瑕而不掩，折而不伤。”宋均注曰：“绳能直物，故名玉绳。沟，谓作器。”玉衡，北斗第五星也。秋夜半，玉绳渐自西北转，冉冉而降，时为夜深或近晓也。\n流年：流逝之岁月；年华。', poem_appreciation = '此词描述了五代时后蜀国君孟昶与其妃花蕊夫人夏夜在摩河池上纳凉的情景，着意刻绘了花蕊夫人姿质与心灵的美好、高洁，表达了词人对时光流逝的深深惋惜和感叹。\n\n　　上片写花蕊夫人帘内欹枕。首二句写她的绰约风姿：丽质天生，有冰之肌、玉之骨，本自清凉无汗。接下来，词人用水、风、香、月等清澈的环境要素烘托女主人公的冰清玉润，创造出境佳人美、人境双绝的意境。其后，词人借月之眼以窥美人欹枕的情景，以美人不加修饰的残妆——“钗横鬓乱”，来反衬她姿质的美好。上片所写，是从旁观者角度对女主人公所作出的观察。\n\n　　下片直接描写人物自身，通过女主人公与爱侣夏夜偕行的活动，展示她美好、高洁的内心世界。“起来携素手，”写女主人公已由室内独自倚枕，起而与爱侣户外携手纳凉闲行。“庭户无声”，制造出一个夜深人静的氛围，暗寓时光在不知不觉中流逝。“时见疏星渡河汉”，写二人静夜望星。以下四句写月下徘徊的情意，为纳凉人的细语温存进行气氛上的渲染。以上，作者通过写环境之静谧和斗转星移之运动，表现了时光的推移变化，为写女主人公纳凉时的思想活动作好铺垫。结尾三句是全词点睛之笔，传神地揭示出时光变换之速，表现了女主人公对时光流逝的深深惋惜。\n\n　　这首词写古代帝王后妃的生活，在艳羡、赞美中附着作者自身深沉的人生感慨。全词清空灵隽，语意高妙，想象奇特，波澜起伏，读来令人神往。\n\n　　值得注意的是，花蕊夫人本是孟昶的宠妃，后蜀灭亡之后，花蕊入宋，以“十四万人齐解甲，更无一人是男儿”的诗句令赵匡胤大为倾倒。不久，孟昶暴亡，花蕊成了太祖的贵妃，据说跟太宗赵光义也有瓜葛。对这样一个与三个皇帝有绯闻的“亡国之妃”，苏轼坦然地把她刻画得几近仙女，且毫不避讳地写她与孟昶的爱情。此词在宋朝广为传唱，还没有一个道学家跳出来说三道四。', poem_tags = '宋词三百首,女子,生活,感叹,人生' WHERE poem_title = '洞仙歌·冰肌玉骨' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '围绕着杏花的是满塘的春水，岸上的花，水中的花影，都是那么地鲜艳动人。\n即使被无情的东风吹落，飘飘似雪，也应飞入清澈的水中，胜过那路旁的花，落了，还被车马碾作灰尘。', poem_notes = '陂（bēi）：池塘。\n花影：花枝在水中的倒影。\n纵：即使。\n绝胜：远远胜过。南陌：指道路边上。', poem_appreciation = '这首绝句写于王安石贬居江宁之后，是他晚年心境的写照。王安石是宰相中的读书人，到晚年，他的绝句尤好。曾有人言，唐代以后无诗，此论太极端了点。王安石晚年的绝句有不少是直追唐人的，在议论入诗上，他的议论与描叙结合得很紧，而且议论不浅白直切，而是含蕴有味。\n\n　　一、二句写景状物，描绘杏花临水照影之娇媚。首句点明杏花所处地理位置。“陂”，此处是指池塘。一池碧绿的春水环绕着杏树，预示着勃发的生机。“绕”字用得精巧，既写陂水曲折蜿蜒之流势，又写水花之相依相亲。王安石爱用“绕”字摹写山形水势，如他《江上》一诗中说：“青山缭绕疑无路，忽见千帆隐映来。”在《书湖阴先生壁》（其一）中写到：“一水护田将绿绕，两山排闼送青来。”又在《钟山即事》中说“涧水无声绕竹流”，有清婉、柔媚、幽静之感。\n\n　　次句从花与影两个方面写杏花的绰约风姿。满树繁花竞相开放，满池花影摇曳迷离。“妖娆”二字本用于写人，这里移用于杏花，展现了杏花争奇斗妍的照人光彩。一个“各”字，表明在诗人眼中，花与影一样地美艳、多情，一样令人流连忘返、沉迷自失。宋人许顗《彦周诗话》说：“荆公爱看水中影，此亦性所好，如‘秋水泻明河，迢迢藕花底’，又《桃花诗》云：‘晴沟涨春渌周遭，俯视红影移鱼舠’，皆观其影。”王安石写花善于从本体和投影两方面着手，如此刻画，虚实相生：一方面使景物更具立体的美，另一方面也透露出诗人的审美趣味，即对虚静恬淡之美的情有独钟。\n\n　　三四句议论抒情，褒扬北陂杏花品性之美。这两句对偶精工，如陈衍《宋诗精华录》说：“荆公绝句，多对语甚工者，似是作律诗未就化成截句（绝句）。”这两句托物言志，耐人玩味。“东风吹作雪”，这一笔淋漓地描绘出风吹杏树，落英缤纷，似漫天飞雪，而随波逐流的凄美景象，比喻生动，浮想联翩。即便是春风轻拂，娇媚的花儿也不堪吹折，它凋谢了，零落了，这本是让人黯然神伤的。但诗人却偏说它胜过南陌杏花，矜持与自足之意溢于言表。这一对比启人深思：“南陌”在此诗中与“北陂”相对立，这两个背景意象包含着一种空间的隐喻。若说清幽静谧的“北陂”是远离浮世喧嚣的隐逸之所，则“南陌”正是熙来攘往、物欲横陈的名利之场。“南陌”繁华，“北陂”僻静；“南陌”热闹，“北陂”空寂；北陂杏花即使零落了，尚可在一泓清波中保持素洁；而南陌的杏花要么历尽亵玩、任人攀折；要么凋零路面、任人践踏，碾成尘土，满身污秽。若说这南陌杏花是邀功请赏、党同伐异的得势权臣的影射，则北陂杏花是诗人刚强耿介、孤芳自赏的自我人格的象征。王安石从1070年（熙宁三年）到1076年（熙宁九年），两次拜相，又两次罢相，最后退居江宁，寄情于半山。罢相之后，他虽被迫退出政治舞台，但仍然坚持自己原有的改革信念与立场，积极倡言“天命不足畏，人言不足恤，祖宗之法不足守”。一“纵”，一“绝”，呼应紧密，激浊扬清，掷地有声地表明他的政治立场与人生操守。\n\n　　绝句由于篇幅短小，很忌一气直下，没有波折。这首诗句句写临水杏花，第二句承第一句；第三、四句承第二句，却宕开一层，以“纵被”领句，用“绝胜”作呼应，便使全诗跌宕有致，富于曲折变化。这样布局，有直写，有侧写，有描绘，有议论，诗人自己爱好高洁的品格也就贯注其中了。', poem_tags = '杏花' WHERE poem_title = '北陂杏花' AND poem_author = '王安石';
UPDATE edu_poem SET poem_translation = '参星横北斗转已经快到三更时分，雨绵绵风不停老天爷也应该放睛。\n云忽散月儿明用不着谁人来点缀，长空净沧海色本来就是澄澈清明。\n虽乘船渡大海空怀孔子救世之志，仿佛听到了黄帝成池优美的乐声。\n被贬南荒虽然九死一生吾不悔恨，这次远游是我平生最奇绝的经历。', poem_notes = '参（shēn）横斗转：参星横斜，北斗星转向，说明时值夜深。参，斗，两星宿名，皆属二十八星宿。横，转，指星座位置的移动。\n苦雨终风：久雨不停，终日刮大风。\n“天容”句：青天碧海本来就是澄清明净的。比喻自己本来清白，政乱污陷如蔽月的浮云，终会消散。\n鲁叟：指孔子。乘桴（fú）：乘船。桴，小筏子。据《论语·公冶长》载，孔子曾说：“道（王道）不行，乘桴浮于海。”\n奏乐声：这里形容涛声。也隐指老庄玄理。《庄子·天运》中说，黄帝在洞庭湖边演奏《咸池》乐曲，并借音乐说了一番玄理。轩辕，即黄帝。\n南荒：僻远荒凉的南方。恨：悔恨。\n兹游：这次海南游历，实指贬谪海南。', poem_appreciation = '纪昀评此诗说：“前半纯是比体。如此措辞，自无痕迹。”“比”，即“以彼物比此物”；而“以彼物比此物”，就很难不露痕迹。但这四句诗，却是不露“比”的痕迹的。\n\n　　“参横斗转”，是夜间渡海时所见；“欲三更”，则是据此所作的判断。曹植《善哉行》：“月没参横，北斗阑干。”这说明“参横斗转”，在中原是指天快黎明之时的景象。而在海南，则与此不同，王文诰指出：“六月二十日海外之二、三鼓时，则参已早见矣。”这句诗写了景，更写了人。一是表明“欲三更”，黑夜已过去了一大半；二是表明天空是晴朗的，剩下的一小半夜路也不难走。因此，这句诗调子明朗，可见当时诗人的心境。而在此之前，还是“苦雨终风”，一片漆黑。连绵不断的雨叫“苦雨”，大风叫“终风”。这一句紧承上句而来。诗人在“苦雨终风”的黑夜里不时仰首看天，终于看见了“参横斗转”，于是不胜惊喜地说：“苦雨终风也解晴。”\n\n　　三、四两句，就“晴”字作进一步抒写。“云散月明”，“天容”是“澄清”的；风恬雨霁，星月交辉，“海色”也是“澄清”的。这两句，以“天容海色”对“云散月明”，仰观俯察，形象生动，连贯而下，灵动流走。而且还用了句内对：前句以“月明”对“云散”，后句以“海色”对“天容”。这四句诗，在结构方面又有共同点：短句分两节，先以四个字写客观景物，后以三个字表主观抒情或评论。唐人佳句，多浑然天成，情景交融。宋人造句，则力求洗练与深折。从这四句诗，既可看出苏轼诗的特点，也可看出宋代诗的特点。\n\n　　三、四两句看似写景，而诗人意在抒情，抒情中又含议论。就客观景物说，雨止风息，云散月明，写景如绘。就主观情怀说，始而说“欲三更”，继而说“也解晴”；然后又发一问：“云散月明”，还有“谁点缀”呢？又意味深长地说：“天容海色”，本来是“澄清”的。而这些抒情或评论，都紧扣客观景物，贴切而自然。仅就这一点说，已经是很有艺术魅力的好诗了。\n\n　　然而上乘之作，还应有言外之意。三、四两句，写的是眼前景，语言明净，不会让读者直接觉得得用了典故。但仔细寻味，又“字字有来历”。《晋书·谢重传》载：谢重陪会稽王司马道子夜坐，“于时月夜明净，道子叹以为佳。重率尔曰：‘意谓乃不如微云点缀。’道子戏曰：‘卿居心不净，乃复强欲滓秽太清耶？’”（参看《世说新语·言语》）“云散月明谁点缀”一句中的“点缀”一词，即来自谢重的议论和道子的戏语，而“天容海色本澄清”则与“月夜明净，道子叹以为佳”契合。这两句诗，境界开阔，意蕴深远，已经能给读者以美的感受和哲理的启迪；再和这个故事联系起来，就更能让人多一层联想。王文诰就说：上句，“问章惇也”；下句，“公自谓也”。“问章惇”，意思是：你们那些“居心不净”的小人掌权，“滓秽太清”，弄得“苦雨终风”，天下怨愤。如今“云散明月”，还有谁“点缀”呢？“公自谓”，意思是：章惇之流“点缀”太空的“微云”既已散尽，天下终于“澄清”，强加于他的诬蔑之词也一扫而空。冤案一经昭雪，他这个被陷害的好人就又恢复了“澄清”的本来面目。从这里可以看出，如果用典贴切就可以丰富诗的内涵，提高语言的表现力。\n\n　　五、六两句，转入写“海”。三、四句上下交错，合用一个典故；这两句则显得有变化。“鲁叟”指孔子。孔子是鲁国人，所以陶渊明《饮酒诗》有“汲汲鲁中叟”之句，称他为鲁国的老头儿。孔子曾说过“道不行，乘桴浮于海”（《论语·公冶长》），意思是：我的道在海内无法实行，坐上木筏子飘洋过海，也许能够实行吧！苏轼也提出过改革弊政的方案，但屡受打击，最终被流放到海南岛。在海南岛，“饮食不具，药石无有”，尽管和黎族人民交朋友，做了些传播文化的工作；但作为“罪人”，是不可能谈得上“行道”的。此时渡海北归，回想多年来的苦难历程，就发出了“空余鲁叟乘桴意”的感慨。这句诗，用典相当灵活。它包含的意思是：在内地，他和孔子同样是“道不行”。孔子想到海外去行道，却没去成；他虽然去了，并且在那里呆了好几年，可是当他离开那儿渡海北归的时候，却并没有什么“行道”的实绩值得他自慰，只不过空有孔子乘桴行道的想法还留在胸中罢了。这句诗，由于巧妙地用了人所共知的典故，因而寥寥数字，就概括了曲折的事，抒发了复杂的情；而“乘桴”一词，又准确地表现了正在“渡海”的情景。“轩辕”即黄帝，黄帝奏乐，见《庄子·天运》：“北门成问于黄帝曰：‘帝张咸池之乐于洞庭之野，吾始闻之惧，复闻之怠，卒闻之而惑；荡荡默默，乃不自得。’”苏轼用这个典，以黄帝奏咸池之乐形容大海波涛之声，与“乘桴”渡海的情境很合拍。但不说“如听轩辕奏乐声”，却说“粗识轩辕奏乐声”，就又使人联想到苏轼的种种遭遇及其由此引起的心理活动。就是说：那“轩辕奏乐声”，他是领教过的；那“始闻之惧，复闻之怠，卒闻之而惑”，他是亲身经历、领会很深的。“粗识”的“粗”，不过是一种诙谐的说法，口里说“粗识”，其实是“熟识”。\n\n　　尾联推开一步，收束全诗。“兹游”，直译为现代汉语，就是“这次出游”或“这番游历”，这首先是照应诗题，指代六月二十日夜渡海；但又不仅指这次渡海，还推而广之，指自惠州贬儋县的全过程。1094年（绍圣元年），苏轼抵惠州贬所，不得签书公事。他从1097年（绍圣四年）六月十一日与苏辙诀别、登舟渡海，到1100年（元符三年）六月二十日渡海北归，在海南岛渡过了三个年头的流放生涯。这就是所谓“兹游”。下句的“兹游”与上句的“九死南荒”并不是互不相承的两个概念，那“九死南荒”，即包含于“兹游”之中。不过“兹游”的内容更大一些，它还包含此诗前六句所写的一切。\n\n　　弄清了“兹游”的内容及其与“九死南荒”的关系，就可品出尾联的韵味。“九死”，多次死去的意思。“九死南荒”而“吾不恨”，是由于“兹游奇绝冠平生”，看到了海内看不到的“奇绝”景色。然而“九死南荒”，全出于政敌的迫害；他固然达观，但也不可能毫无恨意。因此，“吾不恨”毕竟是诗的语言，不宜呆看。这句既含蓄，又幽默，对政敌的调侃之意，也见于言外。', poem_tags = '游历,写景,抒情,猖狂' WHERE poem_title = '六月二十日夜渡海' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '州桥南北的天街之上，中原父老伫足南望，他们年年盼望王师返回。\n哭不成声，强忍泪水询问使者：什么时候真有我们朝廷的军队过来？', poem_notes = '州桥：正名为天汉桥，在汴梁（今河南省开封市）宣德门和朱雀门之间，横跨汴河。\n朱雀门：汴京（今河南开封市）旧城南面有三座门，朱雀门是中间的一座，为正南门。\n宣德楼：宫城的正门楼。\n天街：京城的街道叫天街，这里说州桥南北街，是指当年北宋皇帝车驾行经的御道。\n父老：指汴梁的百姓。等驾回：等候宋朝天子的车驾回来。驾，皇帝乘的车子。\n失声：哭不成声。询：探问，打听。\n六军：古时规定，一军为一万二千五百人，天子设六军。此处借指王师，即南宋的军队。', poem_appreciation = '此诗四句，截取了一个生动的场面，有人物、有环境、 有情节、有对话，完全可以作为一篇小小说来看。环境背景，是第一句的交代，州桥，是一个特定的环境，因为其南北是御路，作者经过此地，不直写自己内心的亡国之痛，而是从对面写来，写中原父老的感情。丧国的痛楚，沦为异邦蹂躏的凄惨，令中原父老苦不欲生。这里，“父老”是宋金两个时期的人，他们对故国的怀念远比青年人深切，所以让其出场很典型；同时，这也是实情。他们盼啊盼，盼了几十年，忽然见到宋朝使者，一时间该有多少话要说、有多少泪欲流啊！可他们强行忍住，因为屈辱的遭遇虽然难堪，盼望官军的情绪最是激烈。接下来，两句忍泪失声的询问，是这个场面的高潮，然突然收结。从内容上看，这样更深刻地表现了中原人民盼望北伐的心情；从艺术上说， 在感情的顶点收结是诗歌创作的妙法， 往往起到语尽不尽的效果。此诗正是如此，诗在到达顶点时戛然而止，可是并非语意都尽，而是余音袅袅。诗人没有以使者身份回答“父老”的问题，也没有以作者口吻发表议论；但他的感情已经与诗笔叙说的事实、描绘的形象融合为一了。如果一定要作想象的话，那范成大可能只是无言以对，因为南宋统治者的既定政策根本不想收复失地，这是十分可悲的。因此此诗对南宋王朝的投降政策也有一定的批判。\n\n　　诗歌的创作多用比、兴，然而“赋”──直接叙述或描写也是不可少的。尤其是直接叙述，往往比描写更难驾御，这就要求诗人要有敏锐的目光，能抓住典型环境中的典型细节，将感情倾注于其中。这首诗的特色就在于此。诗中的典型细节在于两个字──“等”和“询”。父老岁岁年年在等着“王师北定中原日”，几乎到了望穿双眼，几乎要化作“望驾石”，其强烈的愿望和痛苦的心情自然就融于“等”字中。而含泪失声的“询”则惟妙惟肖地描绘出父老的神情，那颤颤巍巍的身影，如在眼前，那哽哽咽咽的声调，尤在耳旁，真是“沉痛不可多读”。而“几时真有”更是意味深长，早也盼，晚也盼，朝思暮想，朝朝暮暮州桥畔，伫立凝眸，企首悬望，父老们的急切心情溢于言表。“遗民泪尽胡尘里，南望王师又一年。”这是他们的弦外之音，因为他们的热切盼望一次又一次地变成失望。而诗人的无言以对，可谓“此时无声胜有声”。', poem_tags = '古诗三百首,爱国' WHERE poem_title = '州桥' AND poem_author = '范成大';
UPDATE edu_poem SET poem_translation = '很久来为公务所累，幸好被贬谪到南方少数民族地区。闲静无事，与农人的菜圃为邻，有的时候就像个山林中的隐士。早晨耕田，翻锄带着露水的野草，晚上撑船游玩回来，船触到溪石发出声响。独来独往，碰不到其他的人，眼望楚天一片碧绿，放声高歌。\n\n韵译\n长久被官职所缚不得自由， 有幸这次被贬谪来到南夷。\n闲时常常与农田菜圃为邻， 偶然间象个隐居山中的人。\n清晨我去耕作翻除带露杂草， 傍晚乘船沿着溪石哗哗前进。\n独往独来碰不到那庸俗之辈， 仰望楚天的碧空而高歌自娱。', poem_notes = '簪组：古代官吏的服饰，此指官职。束：约束，束缚。南夷：古代对南方少数民族的称呼。谪：被降职或调往边远地区。当时作者被贬为永州司马。\n夜榜：夜里行船。榜：此处读“彭音，意为进船。此句指天黑船归，船触溪石而发出的声音。\n楚天：永州原属楚地。\n束：束缚。\n南夷：这里指永州。\n谪：贬官流放。\n农圃：田园。\n偶似：有时好像。\n山林客：山林间的隐士。\n榜：划船。\n响溪石：水激溪石的声响。\n长歌：放歌。', poem_appreciation = '这首诗是柳宗元贬官永州时在愚溪之畔筑屋而居时的作品。诗歌表面是写在此生活的惬意自适，其实是强写欢愉，将被贬的郁愤之情隐晦写出。\n\n　　诗人被贬谪永州，应该是有满腹牢骚的，却在诗的开头将其称为幸事：“久为簪组柬，幸此南夷谪。”诗人认为他长久地为在朝中做官所累，幸亏贬谪南来这荒夷之地，可以让他过上闲适的生活。此两句正话反说，将不幸之事说成是幸事，表达了对朝中当权派的不满。\n\n　　“闲依农圃邻，偶似山林客。晓耕翻露草，夜榜响溪石”，这四句是强调在此生活的闲适之情。闲暇时与种菜的老农为邻，有时还真像是在山林隐居的人。一大早带着露水就去锄草，晚上乘船沿着溪水前进。“闲依”表现作者的闲散之态， “偶似”是故作放旷之语，自我安慰。柳宗元少有才名，胸怀大志，可是仕途不顺，一再遭贬。这次更是被贬永州，远离长安。他满腔的热情得不到施展的空间，有志而不得伸，有才而不被重用。于是，在此贬所，只好强写欢愉，故作闲适，称自己对被贬感到庆幸，假装很喜欢这种安逸舒适的生活。\n\n　　“来往不逢人，长歌楚天碧”，有时整日独来独往碰不见一个行人，于是放声高歌，声音久久地回荡在沟谷碧空之中，多么清越空旷。这闲适潇洒的生活，让诗人仿佛对自己的不幸遭贬无所萦怀，心胸旷达开朗。这里诗人看似自由自在，无拘无束，但毕竟也太孤独了。这两句恰恰透露出诗人是强作闲适，无人问津时自娱自乐，也只是一种无奈的调侃。\n\n　　纵观全诗，诗人似乎已经淡忘了遭贬的痛苦，诗中把被贬谪的不幸称之为幸，将孤独冷静的生活诠释为飘逸闲适的生活。实际上这全都是诗人激愤的反语，在这种被美化了的谪居生活的背后，隐蕴的是诗人内心深深的郁闷和怨愤。表面的平淡所蕴含的激愤，更让人为之怦然心动，正如清代的沈德潜所说： “愚溪诸咏，处连蹇困厄之境，发清夷淡泊之音，不怨而怨，怨而不怨，行间言外，时或遇之。”这是很中肯的评价。\n\n　　全诗清丽简练，含蓄深沉，意在言外，耐人寻味。', poem_tags = '唐诗三百首,生活,孤独' WHERE poem_title = '溪居' AND poem_author = '柳宗元';
UPDATE edu_poem SET poem_translation = '秦地有位罗敷女，曾在绿水边采桑。\n素手在青条上采来采去，在阳光下其红妆显得特别鲜艳。\n她宛转地拒绝了太守的纠缠，说：蚕儿已饥，我该赶快回去了，太守大人，且莫在此耽搁您宝斑的时间了。', poem_notes = '子夜吴歌：《子夜歌》属乐府的吴声曲辞，又名《子夜四时歌》，分为“春歌”、“夏歌”、“秋歌”、“冬歌”。《唐书·乐志》说：“《子夜歌》者，晋曲也。晋有女子名子夜，造此声，声过哀苦。”因起于吴地，所以又名《子夜吴歌》。\n“秦地”句：秦地，指今陕西省关中地区。罗敷女，乐府诗《陌上桑》有“日出东南隅，归我秦氏楼。秦氏有好女，自名为罗敷。罗敷善蚕桑，采桑城南隅”的诗句。\n素：白色。\n“红妆”句：指女子盛妆后非常艳丽。\n妾：古代女子自称的谦词。\n“五马”句：意思是，贵人莫要在此留连。五马，《汉官仪》记载：“四马载车，此常礼也，惟太守出，则增一马。”故称五马。这里指达官贵人。', poem_tags = '唐诗三百首,乐府,春天,赞美,女子' WHERE poem_title = '子夜吴歌·春歌' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '沅江的波浪连接着武冈，送你不觉得有离别的伤感。\n你我一路相连的青山共沐风雨，同顶一轮明月又何曾身处两地呢？', poem_notes = '侍御：官职名。\n通波（流）：四处水路相通。\n武冈：县名，在湖南省西部。\n两乡：作者与柴侍御分处的两地。', poem_appreciation = '“沅水通波接武冈，送君不觉有离伤”，点出了友人要去的地方，语调流畅而轻快，“流水”与“通波”蝉联而下，显得江河相连，道无艰阻，再加上一个“接”字，更给人一种两地比邻相近之感，这是为下一句作势。龙标、武冈虽然两地相“接”，但毕竟是隔山隔水的“两乡”。\n\n　　“青山一道同云雨，明月何曾是两乡”。运用灵巧的笔法，一句肯定，一句反诘，反复致意，恳切感人。也承接了一二句，表达出了诗人的思念之情。如果说诗的第一句意在表现两地相近，那么这两句更是云雨相同，明月共睹，这种迁想妙得的诗句，既富有浓郁的抒情韵味，又有它鲜明的个性。\n\n　　这首诗通过想象来创造各种形象，以化“远”为“近”，使“两乡”为“一乡”。语意新颖，出人意料，然亦在情理之中，因为它蕴涵的正是人分两地、情同一心的深情厚谊。而这种情谊也是别后相思的种子。又何况那青山云雨、明月之夜，更能撩起诗人对友人的思念，一面是对朋友的宽慰，另一面已将深挚不渝的友情和别后的思念，渗透在字里行间了。\n\n　　读者可以感到诗人未必没有“离伤”，但是为了宽慰友人，也只有将“离伤”强压心底，不让自己的“离伤”感染对方。更可能是对方已经表现出“离伤”之情，才使得工于用意、善于言情的诗人用乐观开朗又深情婉转的语言，以减轻对方的离愁。这是更体贴、更感人的友情。正是如此，“送君不觉有离伤”，更能让人感到无比的亲切和难得的深情。这种“道是无情却有情”的抒情手法，比那一览无余的直说更加耐人寻味。', poem_tags = '送别,友情' WHERE poem_title = '送柴侍御' AND poem_author = '王昌龄';
UPDATE edu_poem SET poem_translation = '远处的山峦笼罩着一片乌云，大雨倾盆而下，河水上涨。乌云低飞使半山腰一片昏暗，风吹雨斜撒满了山的曲折处。一串串雨滴如珍珠般滴下，又如珍珠般结在树叶上；大雨在如镜的湖面上泛起了一阵阵涟漪。柳丝在雨气中一片迷濛（或说迷濛的雨气使柳丝密密麻麻的分不出个来了），连绵的大雨如帘，风吹雨丝在空中织起了一片片罗幕。', poem_notes = '“罩”的意思为“覆盖、笼罩”，“罩云”的意思就是笼罩在天空中的乌云。“远岫”是指远处的峰峦。“岭腹”即半山腰；“岩阿”是指山的曲折处。“泫”的本义是“水珠下滴”；“泫丛”的意思是“一串串下滴的水珠”；“缔叶”是说“（雨滴）结在树叶上”。“起溜”是指河水泛起了一阵阵涟漪。“含吹”这两个字是唐代才有的词，见于唐代的诗文中，它的本意就是“风吹”。如唐．李峤的诗句：“青苹含吹转，紫蒂带波流。”（〈萍〉）也许是古人认为风是“风神”从嘴里吹出的一口气吧，所以把“风次”说成为“含吹”。', poem_appreciation = '通过笔者的讲解，我想大家可以发现，唐太宗写的这首诗，每一句就如一段动画，而整首诗又构成了一幅远近景色结合的动态的“山雨飘洒图”。各位读者可以看看本文所配的图片，这张图片用“珠缔叶”三个字就说明了，而“泫丛（一串串雨滴如珍珠般滴下）”的动态景象却看不到。换一句话说，笔者所找到的这张图片只是“泫丛珠缔叶”这个动画片中的一个画面。\n\n　　这首诗还有一个写作特点是每句都包含了一个动词的片语，这些片语是 罩云、喷雨、低飞、斜足、泫从、起溜、濛柳、含吹。这八个词把雨写活了，就好像是施雨龙王、推云童子、布风婆婆等天神在天上操控的那样。现在有些人不相信有神的存在，认为下雨是自然现象，其实就笔者个人在很浅的层次上所见，所谓的“自然”其实是不存在的，神在控制着一切。请各位读者权且相信有施雨龙王、推云童子、布风婆婆等天神的存在，并重新读一下这首诗，可能您会发现对诗的意境的理解和您刚开始读的时候不一样了。也许您会发现，万事万物在唐太宗的笔下都是活的，都是有生命的。也就是把大自然的神韵通过诗的形式描写出来了。', poem_tags = '咏物,写雨' WHERE poem_title = '咏雨' AND poem_author = '李世民';
UPDATE edu_poem SET poem_translation = '鼓声擂得震天响，盛大万舞要开场，正是红日当空照，舞蹈领队站前方。\n舞师健壮又英武，公庭上面演万舞。动作有力如猛虎，手握缰绳似丝足。\n左手拿着龠管吹，右手野鸡翎毛挥。红光满面像赭涂，公侯连说快赐酒。\n高高山上有榛树，低田苍耳绿油油。心里思念是谁人？四方舞师真英武。那英俊的男子啊，那是从西方来呀！', poem_notes = '邶（bèi）：中国周代诸侯国名，地在今河南省汤阴县东南。\n简：一说鼓声，一说形容舞师武勇之貌。朱熹注“简易不恭之意”。\n方将：将要。万舞：舞名。\n方中：正好中午。\n在前上处：在前列的上头。\n硕人：身材高大的人。俣（yǔ）俣：魁梧健美的样子。\n公庭：公爵的庭堂。\n辔（pèi）：马缰绳。组：丝织的宽带子。\n龠（yuè）：古乐器。三孔笛。\n秉：持。翟（dí）：野鸡的尾羽。\n赫：红色。渥（wò）：厚。赭（zhě）：赤褐色，赭石。\n锡：赐。爵：青铜制酒器，用以温酒和盛酒。\n榛（zhēn）：落叶灌木。花黄褐色，果实叫榛子，果皮坚硬，果肉可食。\n隰（xí）：低下的湿地。苓（líng）：一说甘草，一说苍耳，一说黄药，一说地黄。\n西方：西周地区，卫国在西周的东面。美人：指舞师。', poem_appreciation = '《简兮》一诗的主题，旧说是讽刺卫君不能任贤授能、使贤者居于伶官的诗，如《毛诗序》、朱熹《诗集传》、方玉润《诗经原始》、吴闿生《诗义会通》等均持此说。而今人多以为《毛诗序》不足征，纷出新解。邓荃《诗经国风译注》认为是描写舞女辛酸的诗歌，翟相君《诗经新解》却考定诗中舞者为庄姜，此篇是讽谕卫庄公沉湎声色的作品。案据诗中所用“山有榛，隰有苓”这一隐语，可知有关男女情思，所以余冠英《诗经选》、高亨《诗经今注》、袁梅《诗经译注》等认为是卫国宫廷女子（贵族妇女或一般侍女）赞美、爱慕舞师的诗歌，此说可从。最后一章的低回缠绵之气与前三章所描写的豪迈壮阔气象反差极大，疑为错简。然古代一直这么错下来，以误区当真境，亦无不可。\n\n　　全诗的艺术魅力主要来自第四章，吴闿生《诗义会通》曾引旧评说“末章词微意远，缥缈无端”，这一章用朦胧的意象和晦涩的隐语将这位女性绵邈低徊的相思展示无遗。诗歌用“山有榛，隰有苓”托兴，根据《诗经》中其他七处“山有……”“隰有……”对举句式的理解，此处是以树隐喻男子，以草隐喻女子，托兴男女情思，引出下文“云谁之思？西方美人。彼美人兮，西方之人兮。”“西方美人”，旧说多附和曲解，诗意因此玄之又玄。在诗中，“西方美人”乃是指舞师，其例一同于屈原用美人代指楚王。后四句若断若连，回环复沓，意味深远。“彼美人兮，西方之人兮”两句是“云谁之思？西方美人”两句的扩展延伸，钟惺《评点诗经》云：“看他西方美人，美人西方，只倒转两字，而意已远，词已悲矣。”而“后一章两‘兮’字忽作变调，亦与首章首句神韵相应”（陈继揆《读诗臆补》），以“细媚淡远之笔作结，神韵绝佳”（牛运震《诗志》）。', poem_tags = '诗经,写人' WHERE poem_title = '简兮' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '我这白发稀疏的老头幽住在镜湖旁，只有公正的天地能洞察我报国无门的忠肝义肠。\n遭难的苏武熬住了十数年吞毡咽雪的风霜，忧愤的张巡面对叛贼恨得把牙齿咬碎嚼光。\n丝丝的春雨飘洒在上林苑的乱草上，清冷的夜月照见了洛阳宫的断砖破墙。\n我的壮心并没有同年岁一起衰老消亡，纵然死了我也能做鬼中雄杰英明流芳！\n\n岁月流逝，挡不住镜里会照出两鬓秃残的模样，自信我的报国红心却依然忠贞刚强！\n年老了就该不穿紧身的军装，但悲愤常在，还要让寒光闪闪的宝剑刺向敌人的心脏！\n曾经近十年驻守在遥远的的博岭的前哨，还要到万里皋兰跃马横枪实现我宏伟的理想！\n古往今来征战的事无休无止地发生在边远地方，谁能料到现在却让我在这里袖手观望！', poem_notes = '书愤：书写自己的愤恨之情。书，写。\n萧萧：头发花白稀疏的样子。泽中：陆游所住三山别业，南为鉴湖，北为大泽（今为蜻蜓湖），故曰。\n鉴：照。孤忠：忠心耿耿而得不到支持。\n餐毡（zhān）：指身居异地，茹苦含辛﹐而心向朝廷。\n“优愤”句：《旧唐书·张巡传》：“及城陷，尹子奇谓巡曰：‘闻君每战眦裂，嚼齿皆碎，何至此耶？’巡曰：‘吾欲气吞逆贼，但力不遂耳。’子奇以大刀剔巡口，视其齿，存者不过三数。”张巡（709-757），唐邓州南阳（今属河南）人。安史之乱时，与许远共守睢阳（今河南商丘），内无粮草，外无援兵，坚守数月，城破被害\n春芜（wú）：春草。上林苑：秦时宫苑名，在陕西省。泛指皇家园林。当时在沦陷区。\n颓垣（yuán）：断墙残壁。洛阳宫：汉时东都洛阳的宫殿。当时在沦陷区。\n鬼雄：鬼中豪杰。《九歌·国殇》：“身既死兮神以灵，魂魄毅兮为鬼雄。”\n寸心：微小的心意。\n衰迟：衰老。戎衣：军衣。\n的博：又作“滴博”，山岭名，在四川理番县东南。这里泛指川陕。\n壮图：宏伟的意图。皋兰：山名，在今甘肃省兰州市南。\n关河：关山河川。\n袖手看：袖手旁观。', poem_appreciation = '陆游曾说“盖人之情，悲愤积于中而无言，始发为诗。不然，无诗矣。”（《渭南文集》卷十五《澹斋居士诗序》）正是在这种思想的支配下，陆游经常在作品中抒发出浓勃深沉的积愤。这两首所抒发的，“就是塞上长城空自许”，“但悲不见九州同”的悲愤。\n\n　　前一首抒发自己的满怀壮志和一片忠心不被人理解的愤懑。其时，诗人年迈力衰，远离朝廷。他想到，光阴既不待我，衷肠亦无处可诉，只好凭天地来鉴察自己的一片孤忠。紧接着，诗人抚今追昔，想起了古人。苏武厄于匈奴，餐毡吞雪而忠心不泯。安史乱中，张巡死守睢阳数月，被俘后仍骂敌不止，最后竟嚼齿吞牙，不屈而死。作者的耿耿孤忠，不减他们二人，有天地可鉴。此联补足上联之意。上林苑，汉时旧苑。它和“洛阳宫”，在这里都是用来代指皇宫所在之地。首二联情绪激昂，一气直下。这一联则描写细腻，对偶精工，起到了铺垫的作用。最后一联一吐胸臆，直点主题，语气激昂，情绪悲壮，表现了“亘古男儿一放翁”（梁启超《读陆放翁集》诗语）的英雄本色。\n\n　　在第二首中，诗人的愤慨和前一首有所不同。虽然这一首似乎是承接着上一首最后两句，诗人不得不发出无可奈何的叹谓。这一篇的首联和上篇“壮心未与年俱老”句，意思一脉相承，是说对镜照容，已是两鬓苍苍，但是年华虽逝，而自己的壮心依然炽热，不减当年。第二联承上：自己迟暮衰弱，不胜戎衣，但是，悲愤存胸，宝剑在握，寒光闪烁，还是想拼一拼的。于是想起了当年之事。那时，他一腔热血，满怀激情，为了收回失地，远戍的博，鏖战皋兰。然而，时光流逝，那自古以来的关河无穷之事，在种植身上终于无法实现。当年是壮志凌云，岂料到今日成了一个袖手旁观之人。其心情之悲痛苍凉，溢于字里行间。这便是后二联的意境。\n\n　　陆游的这两首《书愤》诗，笔力雄健，气壮山河，充分地显示了他诗歌风格特征的一个主要方面。特别是其中表现出来的对国家、民族的每饭不忘、终生难释的深厚情意，更是陆游整个创作中的精华所在。', poem_tags = '抒怀,壮志未酬,愤懑' WHERE poem_title = '书愤二首' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '乌黑的长发像乌云堆砌在枕上，发间的翠翘也已经歪落。午睡间突然被惊醒，望着满眼却只是春色的温红软绿。轻柔优美的人儿，哪经得起又一春的岁月煎熬。只怕，人老珠黄玉减香消。 柳树下的红门伴着小桥。多少次等到天黑点上蜡烛映红了窗子，多少次误以为是他打马经过。断肠呀，风花雪月可怜无尽长宵。忍着萎靡的样子，却又，十分无聊。', poem_notes = '鸣镳（míng biāo）：马衔铁。借指乘骑。\n恹恹（yān yān）：精神萎靡的样子\n嬛嬛一袅：嬛嬛（xuān）：轻柔美丽；袅：指体态优美的样子；形容女子婀娜多姿。\n楚宫腰：形容女性细小的腰身。\n宵（xiāo）：夜。', poem_tags = '闺怨,女子,岁月' WHERE poem_title = '一剪梅·堆枕乌云堕翠翘' AND poem_author = '蔡伸';
UPDATE edu_poem SET poem_translation = '行路难》为乐府旧题，古辞不存。《乐府解题》说：“《行路难》备言世路艰难及离别悲伤之意，多以‘君不见’为首。”《续晋阳秋》说：“袁山松善音乐，北人旧歌有《行路难》曲，辞颇疏质，山松好之，乃为文其章句，婉其节制。每因酒酣从而歌之，听者莫不流涕。”可见《行路难》词多悲哀之音。\n\n　　此诗由三个层次构成。首四句为第一层，写游子思妇，两个方面同时着笔，而以秋夜闻雁声贯串。以孤雁哀鸣写游子思妇，这是古诗中常用的手法。如曹丕《杂诗》：“草虫鸣何悲，孤雁独南翔。郁郁多悲思，绵绵思故乡。……向风长叹息，断绝我中肠。”又说：“漫漫秋夜长，烈烈北风凉。展转不能寐，披衣起彷徨。彷徨忽已久，白', poem_tags = '游子,相思' WHERE poem_title = '行路难' AND poem_author = '释宝月';
UPDATE edu_poem SET poem_translation = '译文 　　一枝淡红的杏花探出墙头，而墙外的行人（作者）正伤春惆怅。这枝杏花的样子好像跟我一样伤春惆怅，我们哪里禁受得了相逢在这春去匆匆难相留的时节？天色已晚，寂静的树林中黄鹂鸟最先归来，春色尚早，杏花在料峭的春寒中独自绽放，却没有蜂飞蝶舞。这时候我更怀念长安的千万株桃浓杏淡，可淡淡的暮色已经笼罩住了夕阳的光辉，整个神州一片黯淡。', poem_tags = '写花,抒情' WHERE poem_title = '途中见杏花' AND poem_author = '吴融';
UPDATE edu_poem SET poem_translation = '一边是就要枯死的梧桐树一边是久病的身躯，每当想到人死后要去九泉之下心里感到悲伤。\n夜晚手拉着年幼的儿子回到了自己的故园中，寒冷的月光下空空的房子里没有看见任何人。', poem_notes = '重泉：犹九泉。旧指死者所归。', poem_tags = '悼亡' WHERE poem_title = '为薛台悼亡' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '湖海之滨冷风次得泥土冻裂，枯桐叶飘落了，树枝折下来。\n远远听到横笛声却看不到人，把红旗一直插上天山头顶雪。', poem_notes = '从军行：乐府《相和歌辞·平调曲》名。歌词内容多写边塞情况和将士生活。\n海：古代西域的沙漠、大湖泊都叫“海”。这里指天山脚下的湖泊。\n折：断。\n横笛：横吹的一种笛子。\n直上：一直向上、向前。', poem_appreciation = '这是一首写风雪行军的仄韵绝句，全诗写得十分壮美。一、二句写从军将士面对的环境极为严酷：天山脚下寒风劲吹，湖边（“海畔”）冻泥纷纷裂开，梧桐树上的叶子已经刮光，枝梢被狂风折断。就在这一严酷的背景上，映出皑皑雪山，传出高亢嘹亮的笛声。诗人以这一笛声，就点出了这里也许有人的联想，同时又将人隐去，以“不见人”造成悬念：那风里传来的笛声究竟来自何处呢？从而自然转出末句：寻声望去，只见在天山白雪的映衬下，一行红旗正在向峰巅移动。风雪中红旗不乱，已足见出从军将士的精神，“直上”的动态描写，更使画面生机勃然，高昂的士气、一往无前的精神，尽在这“直上”二字中溢出。\n\n　　这首诗在艺术上善于映衬与妙用指代。一、二句对环境的描写，竭力突出自然环境的恶劣，用浓重氛围映衬从军将士无所畏惧的精神风貌。如果是在风和日丽、山明水净的条件下行军，便难能见出士气的昂扬坚强了。适应氛围描写的需要，在押韵上采用了入声的韵脚，一、二、四句末一字入韵，“裂”、 “折”、“雪”都是入声“屑”韵字，韵尾为舌尖音，收音短促，适宜于抒写或悲或壮的诗情。\n\n　　前两句的氛围描写与入声韵的选用，为抒写壮美的诗情打下了良好的基础。但映衬毕竟是陪宾，描写的成败，关键在于作为主体的三、四两句。后两句意在写人，却不正面写出，更不和盘托出，而只是拈出与人相关的二物——“横笛”、“红旗”，不言人而自有人在。这种指代手法的运用，既节省了笔墨，又丰富了作品的艺术容量，给了读者广阔的想象的空间。军中物品无数，只写笛、旗二者，不仅出于只有笛声、红旗才会被远处发现，还因为只有此二物最足以表见行军将士的精神。在写法上，先写“横笛闻声”，后写“红旗直上”，符合人们对远处事物的注意往往“先声后形”的一般习惯。特别巧妙的是“不见人”三字的嵌入。“闻声”而寻人，寻而“不见”，从而形成文势的跌宕，使末句的动人景象更为显豁地表现出来。\n\n　　这首《从军行》兼有诗情画意之美，莽莽大山，成行红旗，雪的白，旗的红，山的静，旗的动，展示出一幅壮美的风雪行军图。', poem_tags = '边塞,行军' WHERE poem_title = '从军行' AND poem_author = '陈羽';
UPDATE edu_poem SET poem_translation = '泉水汨汨流不息，还是回归入淇水。怀念卫国我故乡，没有一天不在想。同来姬姓好姐妹，且与她们来商量。\n回想当初宿泲地，摆酒饯行在祢邑。女子出嫁到别国，远离父母和兄弟。临行问候我姑母，还有众位好姊妹。\n如能回乡宿在干，饯行之地就在言。车轴上油插紧键，直奔故乡跑得欢。疾驰速奔回到卫，不会招来甚后患？\n我是思绪在肥泉，声声叹息用不休。再想须城与漕邑，我的忧伤无尽头驾着马车去出游，借此排解我忧愁。', poem_notes = '邶（bèi）：中国周代诸侯国名，地在今河南省汤阴县东南。\n泉水：卫国水名，即末章所说的“肥泉”。\n毖（bì）：“泌”的假借字，泉水涌流貌。\n淇：淇水，卫国河名。\n有怀：因怀念。有，以，因。\n靡：无。\n娈（luán）：美好的样子。诸姬：指卫国的同姓之女，卫君姓姬。\n聊：一说愿，一说姑且。\n泲（jǐ）：卫国地名。或以为即济水。\n饯：以酒送行。祢（nǐ）：卫国地名。\n行：指女子出嫁。\n姑：父亲的姊妹称“姑”。\n干：卫国地名。\n言：卫国地名。\n载：发语词。脂：涂车轴的油脂。舝（xiá）：同“辖”，车轴两头的金属键。此处脂、舝皆作动词。\n还车：回转车。迈：远行。\n遄（chuán）：疾速。臻：至。\n瑕：通“胡”、“何”；一说远也。\n肥泉、须、漕：皆卫国的城邑。肥泉一说同出异归之泉。\n兹：通“滋”，增加。\n须、漕：均为卫国地名。\n悠悠：忧愁深长。\n写（xiè）：通“泻”，除也。与“卸”音、义同。', poem_appreciation = '思乡是对家园的依恋。谁都会说家乡好。这是人类普遍的心态。衡量家乡好的标准，显然不是物质条件，而是那份梦绕魂牵 的亲情。家乡完全可能很穷，很落后，很寒伧，没有丰富的物产 和妩媚的山水，但这些对思乡人来说都不重要，都可以被忽略。\n\n　　重要的是，生于斯、长于斯、铭刻在心灵深处的人生体验，以 及由此产生的不可割舍的亲情。这些体验和亲情对个人来说一生 只有一次，既不可重复，也不可替代。哪怕是一些极小的细节，比 如曾经采摘邻居的花朵而遭到责骂，背着父母下河洗澡，爬上屋 顶恶作剧，放学路上漫无目的地游荡和东张西望，都可能随着岁 月的流逝而在脑海里突现出来，变成思乡恋情中的一部分。\n\n　　家园感可以说是人类心灵中最为持久和强烈的冲动的来源。 久居家园不容易体验到这种冲动的强烈程度，也难以对思乡愁绪 有深切的感触。一旦脱离家园，或者丧失家园，方才体会到家园 的可亲可爱。游子思家，古今中外皆然，也是文学艺术表现的永 恒主题。失去家园，既是失去了肉体的寄居之所，同时也是失去 了情感的寄托和精神的归依。犹太民族为重建失去的家园，忍辱 负重，历尽坎坷，奋斗了三千年，为此付出了一代又一代人的牺 牲。可见，无论对一个民族来说，还是对一个人来说，都不可能 一日无家园。即使没有实际存在的家园，必定会有心目中既神圣 又可亲的家园。\n\n　　有家不能回的忧愁，丝毫都不亚于无家可归的悲哀。在人遭 受痛苦磨难的时候，家园家乡常常取代神灵上帝而成为人们精神 上的支柱和依靠，成为人们在痛苦磨难中坚持下去、与之抗争的 力量源泉之一。从这个意义上说，乡愁是可贵的。', poem_tags = '诗经,思乡' WHERE poem_title = '国风·邶风·泉水' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '天色朦胧就去迎候远道而来的客人，晨曦渐渐地染红了群山。傍晚泛舟西湖，天上飘来了一阵阵雨，客人不胜酒力已渐入醉乡。\n西湖晴雨皆宜，如此迷人，但客人并没有完全领略到。如要感受人间天堂的神奇美丽，还是应酌酒和西湖的守护神“水仙王”一同鉴赏。', poem_notes = '饮湖上：在西湖的船上饮酒。\n朝曦：早晨的阳光。\n水仙王：宋代西湖旁有水仙王庙，祭祀钱塘龙君，故称钱塘龙君为水仙王。', poem_tags = '赞美,西湖,美景' WHERE poem_title = '饮湖上初晴后雨二首·其一' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '从军疆场的壮志难酬令人怅惘，东南形势的忧虑情怀注满诗行。\n赋诗抒怀和仗剑抗敌是我平生志愿，十五年来完全辜负了“狂士”声名。', poem_notes = '绝域：隔绝的地域，言其远。此指我国边疆。\n惘（wǎng）然：失志的样子。指从军的愿望未能实现。\n东南：指我国东南沿海一带。当时英、美、葡等国已开始在东南沿海一带的广州、漳州(今属厦门)、宁波进行经济掠夺。\n词笺（jiān）：写诗词的纸，亦可作“诗词”看。笺，古代小幅而极精致的纸。\n负：辜负。十五年：诗人于嘉庆十四年（1809）十八岁时成人立志，在北京与被目为“狂士”的著名诗人王昙订为忘年交，当时已在社会上小有名气，从那时到此时，前后正好十五年。', poem_tags = '爱国,励志' WHERE poem_title = '漫感' AND poem_author = '龚自珍';
UPDATE edu_poem SET poem_translation = '满地凝结着寒霜，浓得像覆上一层白雪。人们立在西风中话别，瘦马也向着残月不断悲鸣。送别时，《阳关》一曲犹未奏完，离人就已出发了。咿轧的车声仿佛应和着歌声，在痛苦地呜咽。\n天涯芳草青青的颜色已换作枯黄，可是，陌头上深深的车辙依旧是我来时的模样。三句为前人未道之语。静安于是年春跟随罗振玉入京，数月后即奔丧回里。来去匆匆，情事已更，故深感人生之无常。这虚浮无定的人生，还有什么可说呢？在人间最令伤心的事莫过于离别了。', poem_notes = '霜华，此指严霜。因其每呈结晶状，故云。张祜《旅次上饶溪》诗：“秋竹静霜华。”\n阳关，指《阳关三叠》曲。为古代送别的曲调。王维《送元二使安西》诗：“渭城朝雨浥轻尘，客舍青青柳色新。劝君更尽一杯酒，西出阳关无故人。”后来谱入乐府，即以诗中“渭城”或“阳关”名曲。\n浮生，《庄子·刻意》：“其生若浮，其死若休。”老庄学说认为人生世事虚幻无定，故云。\n耽（dān）：指沉溺、迷恋；也有停留、拖延、延误的含义。', poem_tags = '离别' WHERE poem_title = '蝶恋花·满地霜华浓似雪' AND poem_author = '王国维';
UPDATE edu_poem SET poem_translation = '燕子归来的时节，吹起了西风。希望在人世间我们还能能相聚在一起，在菊花丛中举杯共饮。歌声悠扬有你粉嫩的脸庞。\n夕阳穿过幕帘，阴影包围了梧桐。有多少情话说不尽，写在给你的词曲中。这份情千万重。', poem_notes = '破阵子：唐教坊曲名，又名《十拍子》。\n金尊：酒杯。\n斜日：夕阳。\n更：正。\n蛮笺：谓蜀笺，唐时指四川地区所造彩色花纸。', poem_appreciation = '这首词，仍然是惜别、思念之作。寂寞是爱的一种声音，孤独是爱的另外一种声音。而心，则是爱的道路。爱情是盏灯，思念是其中的灯油。当有一天，一个人站在往事的回廊中观望的时候，纵有如火的红豆，也点不亮那断了纹路的情伤。情已断，爱已走，心已碎，手已凉。这样的现实，不知不觉地站在一个女子的心里。\n\n　　于自己内心思念的尽头，发现，心被那远去的人牵得很紧，很疼。世界这么大，但幸运的是，那别人的名字，仍然还在心里，牵挂着，等待着，等待他的归期。只是不知道，是不是还能穿过茫茫的红尘，找到那把可以打开距离的钥匙。\n\n　　真的如同徐再思所说的那样：平生不会相思，才会相思，便害相思。\n\n　　这首词，仍然是一个女子的伤情。\n\n　　叶嘉莹先生在《大晏词的欣赏》中这样评价此词：“至于写艳情者，如其……《破阵子》之‘多少襟怀言不尽，写向蛮笺曲调中，此情千万重’，若以这些词句与柳永《定风流》之‘彩线慵拈伴伊坐’，《菊花新》之‘欲掩香帏论缱绻’诸作相较，则大晏正所谓‘虽作艳语，终有品格’，因为大晏所唤起人的只是一份深挚的情意，而此一份情意虽然或者乃因儿女之情而发，然而却并不为儿女之情所限，较之一些言外无物的浅露淫亵之作，自然有高下、雅鄙的分别。”\n\n　　有权威的解析认为，这是一首秋日席间赠妓之作。全篇代歌妓述事言情，先写这位歌女对“时节”的感受，次写她在筵席上与情人“小会”的欢欣及她的即席演唱，最后写她与情人依依惜别的种种情状。\n\n　　这样的解析虽然没有什么问题，但是我总是觉得太过实在了一些。晏殊自己没有明说这是代歌女而作或赠妓之作，我们如果断成代歌女而作或赠妓之作，也不是不可，只是在我看来，有点喧宾夺主的嫌疑。所以，我坚持认为，这就是一首惜别、思念之作。和一个女子有关。除此之外，不做其他的推断。\n\n　　“燕子欲归时节，高楼昨夜西风。”\n\n　　这里点明了时节。从“燕子欲归”和“昨夜西风”这两句来看，当是晚春至秋初的这段时节。\n\n　　这句，其实存在着一个人物特写。一个女子站在高楼之上，望着远方的姿态写满了思念。虽然晏殊从词语上没有写到这个女子，但从“燕子”、“高楼”这两句，我们就可以在自己的脑海中勾画出一个女子婀娜多姿的身姿。真正的高手，就高在“以物衬人”或“以物写人”的境界上。\n\n　　诗词从来都是一种省略文体，不可能说得过于明白。所以，这就需要我们有想象力，甚至是合理的、大胆的想象。\n\n　　“燕子欲归”，这其实是女子内心的愿望和最真最深的疼。你看那燕子，都双飞在她的眼前，可是，他却独自留下她，忍受这漫长的寂寞的煎熬，甚至是孤独的思念的掏挖。\n\n　　燕子欲归，人未归。我想，这才是晏殊最想写出来的结果。不过，却留着，让读者自己去想象。明白无误的是，词中女子的内心和思念已经寄出去，而且，一直没有找到可以收留的地方，一直在路上跋涉。\n\n　　不过，他仍然在她的心里燃烧着。他拿走了她的梦、她的泪水和她的思念。', poem_tags = '惜别,思念,女子' WHERE poem_title = '破阵子·燕子欲归时节' AND poem_author = '晏殊';
UPDATE edu_poem SET poem_tags = '初中文言文,寓理,教育,故事' WHERE poem_title = '墨子怒耕柱子' AND poem_author = '墨子及弟子 撰';
UPDATE edu_poem SET poem_translation = '卷起珍珠做的帘子，挂上帘钩，在高楼上远望的我和从前一样，愁绪依然深锁。风里的落花那么憔悴，谁是它的主人呢？这使我越想越加茫然。\n信使不曾捎来远方行人的音讯，雨中的丁香花让我想起凝结的忧愁。我回头眺望暮色里的三峡，看江水从天而降，浩荡奔流。', poem_notes = '摊破浣溪沙：词牌名。又名“添字浣溪沙”“山花子”“南唐浣溪沙”。双调四十八字，前阕三平韵，后阕两平韵，一韵到底。前后阕基本相同，只是前阕首句平脚押韵，后阕首句仄脚不押韵。后阕开始两句一般要求对仗。这是把四十二字的“浣溪沙”前后阕末句扩展成两句，所以叫“摊破浣溪沙”。\n真珠：以珍珠编织之帘。或为帘之美称。《西京杂记》：“昭阳殿织珠为帘，风至则鸣，如珩佩之声”。玉钩：帘钩之美称。\n依前：依然，依旧。春恨：犹春愁，春怨。锁：这里形容春恨笼罩。\n悠悠：形容忧思不尽。\n青鸟：传说曾为西王母传递消息给汉武帝。这里指带信的人。《史记·司马相如列传》：“幸有三足鸟为之使。”注：“三足鸟，青鸟也。主西王母取食。”云外：指遥远的地方。\n丁香结：丁香的花蕾。此处诗人用以象征愁心。\n三楚：指南楚、东楚、西楚。三楚地域，说法不一。这里用《汉书·高帝纪》注：江陵（今湖北江陵一带）为南楚。吴（今江苏吴县一带）为东楚。彭城（今江苏铜山县一带）为西楚。“三楚暮”，一作“三峡暮”。', poem_appreciation = '这是一首伤春词、春恨词。词人赋恨在者所在多有，然惯用暗笔，像这首在词中点明“春恨”还是罕见的。词的上片从落花无主着笔，写春恨所以产生的触媒；下片从思念难解立意，将春恨产生的根源揭示得含蓄而又深沉。作者用了词家惯用的对景抒情的手法，然而却用得很不一般。\n\n　　词的开头头先来了句“手卷真珠上玉钩”，即非景语，也非情语，而是客观平直的叙述，算不上以景呼情，也算不上以情唤景。首句“真珠”二字或作“珠帘”，但正如古人所云：“言‘真珠’，千古之善读者都知其为帘，若说‘珠帘’，宁知其为真珠耶！是举真珠可包珠帘，举珠帘不足以包真珠也。后人妄改，非所谓知音。”“手卷真珠上玉钩，依前春恨锁重楼”二句委婉、细腻，卷帘本欲观省景物，借抒怀抱，而既卷之后，依旧春愁浩荡。可见，“锁”是一种无所不在的心灵桎梏，使人欲销愁而不可得。而“春恨”并不是抽象的，“风里落花谁是主”，风不仅吹落花朵，更将凋零的残红吹得四处飞扬，无处归宿。在这里可以看到的是人的身世飘零，孤独无依。\n\n　　上片结句“思悠悠”，正是因此而思绪萧索，悠然神往。\n\n　　下片从人事着笔，是对春恨的进一步申说，也是“思悠悠”的直接结果。“青鸟不传云外信，丁香空结雨中愁”，则点出了“春恨”绵绵的缘由所在。此句反用西王母与汉武帝典故。据说三足的青鸟是西王母的侍者，七月七日那天，汉武帝忽见青鸟飞集殿前，遂后西王母即至。然而所思主人远在云外，青鸟也不为之传信，思念难解的主人公就更加感到春恨的沉重了。“丁香结”本是丁香的花蕾，取固结难解之意，诗人多用它比喻相思之愁的郁结不散，如李商隐《代赠》诗有句：“芭蕉不展丁香结，同向春风各自愁。”李璟的独创就在于将丁香结化入雨中的境界，使象征愁心的喻体丁香花蕾更加凄楚动人，更加令人怜悯，“青鸟”、“丁香”二句合看又恰是一联工稳的对仗，一人事，一时景，这律诗般的俊语将思念难解之情写得既空灵透脱而又真挚实在。至此，词的感情已经十分浓郁、饱满。当手卷真珠上玉钩的时刻，已经春恨绵绵；风里落花无主，青鸟不传信，丁香空结，则徒然的向往已经成为无望，这已是无可逃避的结局。\n\n　　最后以景语作结：“回首绿波三楚暮，接天流”。楚天日暮，长江接天，这样的背景暗示着愁思的深广。“接天流”三个字让人想起“问君能有几多愁，恰似一江春水向东流”。就这一意境而言，李璟李煜父子是一脉相承的。另外，从整首词来看，末句的境界突然拓展，词中的一腔愁怀置于一个与其身世密切相关的历史地理环境中，与心灵的起伏波动也是密切相合的。\n\n　　那充满“春恨”的人事内容究竟具体何指。据马令《南唐书》卷二十五载：李璟即位，歌舞玩乐不辍，歌师王感化尝为之连唱“南朝天子爱风流”句至再三再四以剌之，李璟遂悟，作《浣溪沙》二阕并手书以赐感化，其中就包括这一首。这样看来，词中的春恨就不是这位风流天子对景抒情的一般闲愁，很可能是南唐受周威胁时的危苦感慨，而“青鸟”句就是忧国之思的深沉寄托了。', poem_tags = '宋词三百首,婉约,写景,伤春' WHERE poem_title = '摊破浣溪沙·手卷真珠上玉钩' AND poem_author = '李璟';
UPDATE edu_poem SET poem_translation = '对着席案上的美食却难以下咽，拔出宝剑对柱挥舞发出长长的叹息。\n大丈夫一辈子能有多长时间，怎么能小步走路的失意丧气？\n放弃官衔辞职离开，回到家中休养生息。\n早上出家门与家人道别，傍晚回家依然在亲人身边。\n在床前与孩子玩耍，看妻子在织布机前织布。\n自古以来圣贤的人都生活得贫贱，更何况我这样的清高孤寒又正直的人呢？', poem_notes = '案：一种放食器的小几。又，案，即古“椀”（碗）字。　\n会：能。这句是说一个人生在世上能有多久呢？　\n安能：怎能。蹀躞（diéxiè叠谢）：小步行走的样子。这句是说怎么能裹足不前，垂翼不飞呢。　\n弄儿：逗小孩。戏：玩耍。　\n孤且直：孤高并且耿直。这二句是说自古以来圣人贤者都贫困不得意，何况像我们这样孤高而耿直的人呢！', poem_appreciation = '全诗分三层。前四句集中写自己仕宦生涯中倍受摧抑的悲愤心情。一上来先刻画愤激的神态，从“不能食”、“拔剑击柱”、“长叹息”这样三个紧相连结的行为动作中，充分展示了内心的愤懑不平。诗篇这一开头劈空而来，犹如巨石投江，轰地激起百丈波澜，一下子抓住了读者的关注。接着便叙说愤激的内容，从“蹀躞”、“垂羽翼”的形象化比喻中，表明了自己在重重束缚下有志难伸、有怀难展的处境。再联想到生命短促、岁月不居，更叫人心焦神躁，急迫难忍。整个心情的表达，都采取十分亢奋的语调；反问句式的运用，也加强了语言的感情色彩。\n\n　　中间六句是个转折。退一步着想，既然在政治上不能有所作为，不如丢开自己的志向，罢官回家休息，还得与亲人朝夕团聚，共叙天伦之乐。于是适当铺写了家庭日常生活的场景，虽则寥寥几笔，却见得情趣盎然，跟前述官场生活的苦厄与不自由，构成了强烈的反差。当然，这里写的不必尽是事实，也可能为诗人想象之辞。如果根据这几句话，径自考断此诗作于诗人三十来岁一度辞官之时，不免过于拘泥。\n\n　　然而，闲居家园毕竟是不得已的做法，并不符合作者一贯企求伸展抱负的本意，自亦不可能真正解决其思想上的矛盾。故而结末两句又由宁静的家庭生活的叙写，一跃而为牢骚愁怨的迸发。这两句诗表面上引证古圣贤的贫贱以自嘲自解，实质上是将个人的失意扩大、深化到整个历史的层面——怀才不遇并非个别人的现象，而是自古皆然，连大圣大贤在所不免，这足以证明现实生活本身的不合理。于是诗篇的主旨便由抒写个人失意情怀，提升到了揭发、控诉时世不公道的新的高度，这是一次有重大意义的升华。还可注意的是，诗篇终了用“孤且直”三个字，具体点明了像作者一类的志士才人坎坷凛冽、抱恨终身的社会根源。所谓“孤”，就是指的“孤门细族”（亦称“寒门庶族”），这是跟当时占统治地位的“世家大族”相对讲的一个社会阶层。六朝门阀制度盛行，世族垄断政权，寒门士子很少有仕进升迁的机会。鲍照出身孤寒，又以“直”道相标榜，自然为世所不容了。钟嵘《诗品》慨叹其“才秀人微，故取湮当代”，是完全有根据的。他的诗里不时迸响着的那种近乎绝望的抗争与哀叹之音，也不难于此得到解答。\n\n　　前面说过，同为诗人抗议人生的哀歌，此诗较之《拟行路难·泻水置平地》的正言若反、半吐半吞，写法上要直露得多，但此诗也并非一泻到底。起调的高亢，转为中间的平和，再翻出结语的峭拔，照样是有张有弛，波澜顿挫。音节安排上由开首时七言长调为主，过渡到中间行云流水式的五言短句，而继以奇峰突出的两个长句作收煞，其节奏的高下抗坠也正相应于情感旋律的变化。所以两首杂言体乐府仍有许多共同之处。再进一步，拿这两首感愤言志之作，来同前面那些借思妇口吻言情的篇什相比较，风格上又有不少异同。前诗婉曲达意，这里直抒胸臆；前诗节拍舒徐，这里律动紧促；前诗情辞华美，这里文气朴拙——随物赋形，各有胜境。不过无论哪一类题材，都能显现出作者特有的那种奇思焕发、笔力健劲的色调，这正是鲍照诗歌最能打动人心的所在。《南史》本传用“遒丽”二字评论他的乐府创作，后来杜甫也以“俊逸”概括其诗风，其实“俊”和“丽”还只标示出它的体貌，“逸”和“遒”才真正摄得它的神理。从鲍照的“俊逸”到李白的“飘逸”，是有着一脉相承的关系的。', poem_tags = '古诗三百首,乐府,失意,哀歌' WHERE poem_title = '拟行路难·其六' AND poem_author = '鲍照';
UPDATE edu_poem SET poem_translation = '夜晚独自登上小楼，烟雾朦胧，忧愁漫上心头就像醉酒似的。大雁飞来了，可是爱人却远走了，想到这更加惆怅。窗帘边一钩新月，这凄凄黄昏最是难熬。\n所爱的人心音全无，我这幽恨何时才能除去呢。那绕着花儿飞舞的蝴蝶若是懂我的心的话，麻烦到我的梦里去，飞去我爱人的地方，寄去我的相思。', poem_notes = '玉楼：华丽的楼阁。\n相亲：互相亲爱；相亲近。', poem_tags = '思念,爱情' WHERE poem_title = '虞美人·玉楼缥缈孤烟际' AND poem_author = '欧阳澈';
UPDATE edu_poem SET poem_tags = '宋词三百首,月亮,婉约,离别,女子,惜别' WHERE poem_title = '蝶恋花·早行' AND poem_author = '周邦彦';
UPDATE edu_poem SET poem_translation = '自入春以来，见到那绿叶红花也像是带着愁苦，我这一寸芳心越显得百无聊赖。太阳已经升到了树梢，黄莺开始在柳条间穿飞鸣叫，我还拥着锦被没有起来。细嫩的肌肤已渐渐消瘦，满头的秀发低垂散乱，终日里心灰意懒，没心情对镜梳妆。真无奈，可恨那薄情郎自从去后，竟连一封书信也没有寄回来。\n早知如此，悔当初没有把他的宝马锁起来。真该把他留在家里，只让他与笔墨为伍，让他吟诗作词，寸步不离开。我也不必躲躲闪闪，整日里与他相伴，手拿着针线与他相倚相挨。有他厮守，免得我青春虚度，苦苦等待。', poem_notes = '是事可可：对什么事情都不在意，无兴趣。一切事全含糊过去。可可：无关紧要；不在意。 \n暖酥：极言女子肌肤之好。\n腻云：代指女子的头发。亸（duǒ）：下垂貌。\n无那：无奈。\n恁么：这么。\n鸡窗：指书窗或书房。语出《幽明录》：“晋兖州刺史沛国宋处宗尝得一长鸣鸡，爱养甚至，恒笼著窗间。鸡遂作人语，与处宗谈论极有言智，日不辍。处宗因此言巧大进。”（《艺文类聚·鸟部》卷九十一引）。\n蛮笺象管：纸和笔。蛮笺：古时四川所产的彩色笺纸。象管：即象牙做的笔管。\n镇：常。\n和：允诺。', poem_appreciation = '这是一首写爱情的词篇，具有鲜明的民间风味，是柳永“俚词”中具有代表性的作品。这首词以一个少妇（或妓女）的口吻，抒写她同恋人分别后的相思之情，刻画出一个天真无邪的少妇形象。这首描写闺怨的词在宋元时期曾经广为流传，受到普通民众，尤其是歌妓的喜爱。到了元代时，关汉卿更是把它写进了描写柳永与歌妓恋情的杂剧《谢天香》里。\n\n　　上片，通过艳丽春光和良辰美景来衬托少妇的孤寂之情。开头三句，写春回大地，万紫千红。少妇因此反而增愁添恨。这里暗示出，过去的春天她曾与“薄情”者有过一段火热的恋情生活。次三句，写红日高照，莺歌燕舞，是难得的美景良辰，而她却怕触景伤情，拥衾高卧。接三句，写肌肤消瘦，懒于梳妆打扮。这和《诗经．卫风·伯兮》“自伯之东，首如飞蓬，岂无膏沐，谁适为容”的精神是一致的，表现出爱情的坚贞不渝。未三句，揭示出这位少妇之所以“倦梳裹”的真正原因：“恨薄情一去，音信无个。”作者在上片用的是一种倒叙手法，不仅总结上片中的三个层次，而且还很自然地引出下面的内心活动和感情的直接抒发。\n\n　　下片，极写内心的悔恨和对美好生活的向往。头三句，点明“悔”字，反映出这位少妇的悔恨之情。继之，又用“锁”字与此相衬，烘托出感情的真挚、热烈与性格的泼辣。在特别重视功名利禄的封建社会，一个闺中少妇为了爱情而敢于设想把丈夫“锁”在家里，这无疑是一个大胆的反叛行动。这位少妇的举措，可以使人联想到《红楼 梦》中林黛玉对功名利禄，对仕途经济的批判，而且与柳永《鹤冲天》词中所反映的思想感情也是一脉相通的。中六句是对理想中的爱情生活的设想和追求。他们坐在窗明几净的书房里吟诗作赋，互相学习，终日形影不离。结尾三句明确责示对青春的珍惜和对生活的热爱。\n\n　　这首词具有浓厚的民歌风味。它不仅吸取了民歌的特点，保留了民间词的风味，而且还具有鲜明的时代特色。作者没有采取传统的比兴手法，也不运用客观的具体形象来比喻和暗示自己爱情的炽烈与坚贞，而是采取感情的直接抒写和咏叹。词中，感情的奔放热烈带有一种赤裸无遗的色彩，明显地具有一种市民性。这是柳永生活时代都市高度繁荣的客观反映。\n\n　　从思想上看，这首词明显带有市民意识。这首词的另一特点是语言通俗，口吻自然，纯用白描，这说明柳永在向民间词学习方面获得了巨大的成功。他扩大了“俚词”的创作阵地，丰富了词的内容和词的表现力。以深切的同情，抒写了沦落于社会下层的歌伎们的思想感情，反映了她们对幸福生活的追求与向往，以及内心的烦恼与悔恨。', poem_tags = '宋词三百首,宋词精选,婉约,女子,闺怨,思念' WHERE poem_title = '定风波·自春来' AND poem_author = '柳永';
UPDATE edu_poem SET poem_translation = '夏日的若耶溪傍，美丽的采莲女三三俩俩采莲子。隔着荷花共人笑语，人面荷花相映红。\n阳光照耀采莲女的新妆，水底也显现一片光明。风吹起,衣袂空中举，荷香体香共飘荡。\n那岸上谁家游冶郎在游荡？三三五五躺在垂杨的柳阴里。\n身边的紫骝马的嘶叫隆隆，落花纷纷飞去。见此美景，骚人踟蹰，愁肠空断。', poem_notes = '采莲曲：属乐府清商曲辞。起于梁武帝萧衍父子，后人多拟之。\n若耶溪：在今浙江绍兴市南。\n袂：衣袖。全诗校:“一作袖。”\n游冶郎：出游寻乐的青年男子。\n紫骋：毛色枣红的良马。\n踟蹰：徘徊。', poem_appreciation = '李白诗将吴越采莲女的娇艳清纯放在荷花丛中加以表现，又用岸上游冶郎的徘徊踯躅不忍离去反衬采莲女的魅力，描绘出明艳、活泼、大方的采莲女的新形象，语言入清水芙蓉，天然雅清，毫无做作，一气呵成，展示出诗人的姿态高雅、清新脱俗。弥补了六朝以来采莲女形象的苍白与虚饰。\n\n　　第一句：若耶河边采莲女，笑隔荷花共人语。溪边采莲花的女孩，隔着荷花谈笑风生，互相嬉戏，或是和风细雨，或是娇喘微微。荷叶田田，芙蓉朵朵，与春风满面的姑娘的粉颊交相辉映，正如王昌龄《采莲曲》中所道“乱入池中看不见，闻歌始觉有人来。”隔着莲花，似有似无的朦胧之美，意趣盎然，富有生活气息。“笑隔荷花”将采莲女纤手拨荷花愉快交谈的神态细腻的表现出来，生动形象。\n\n　　第二句：日照新妆水底明，风飘香袖空中举。温和的阳光，浓抹的新妆，清澈的流水，风飘香袖的妩媚，勾勒出一幅清新明丽的采莲图，节奏轻快，活泼自然。采莲女不知是在挥手还是在故意摆弄，将香袖高举，河面倒映着采莲女精心准备的新妆，最是那一低头的闲花照水，露出她娇羞的神态，腼腆不胜凉风的吹拂，正如“照花前后镜，画面交相映”，人花难辨。这两句勾勒出了“江南可采莲，莲叶何田田”的美好意境，如闻其声，如见其人，如临其境，让人感受到一股勃勃生机，领略到采莲人内心的欢乐，所谓“菱歌唱不彻，知在此塘中”。\n\n　　第三句：岸上谁家游冶郎，三三五五映垂杨。欢声笑语吸引了岸上的游冶郎，不知哪家的公子，三三五五、似隐非隐在垂杨下，我们可以想象出此时的采莲女面对岸边的游冶郎会有多么的娇羞，所谓“女为悦己者容”，心里怦跳的喜悦之情溢于言表。李白笔下的娇羞之态并未点明，只是从“日照新妆水底明，风飘香袖空中举”联想到的，有着明丽可人的浪漫情调，自有一种清新脱俗。诗人将她们置于青翠欲滴的荷叶丛中，又以游冶郎的徘徊搔首来衬托她们的娇美，使用乐府写罗敷的手法，从而更加委婉传神。\n\n　　第四句：紫骝嘶入落花去，见此踟蹰空断肠。诗人骑着紫骝，马儿嘶鸣着，惊花，花落，空见那一份景色，使人凄怆断肠。这里充斥着诗人对时光飞逝、岁月不饶人的感叹，及对美景易逝的无奈之情，寄托着作者因怀才不遇、壮志难伸而发出的愁思，这与他平素洒脱自信、率真不羁、清新飘逸的风格有所不同，而以一种细腻温婉的笔触，引人遐思。“踟蹰空断肠”，似是断肠人在天涯，象他《月下独酌》中一身孤傲与月为伴，与影为伴，还是免不了苍茫寂寥、清绝孤独之感，一向大气豪迈的李白也有避不了的人生悲哀。\n\n　　诗人笔下生风，使一曲采莲，景因情而媚，情因景而浓，而毫无堆砌之嫌，清新自然，仍是一如既往的浪漫。', poem_tags = '乐府,荷花,女子' WHERE poem_title = '采莲曲' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '译文 　　隆冬过去，一泓春水溢满了田野和水泽夏天的云变幻莫测，大多如奇峰骤起，千姿万态秋月朗照，明亮的月光下，一切景物都蒙上了一层迷离的色彩冬日高岭上一棵严寒中青松展现出勃勃生机。', poem_tags = '四季,写景,述志' WHERE poem_title = '四时' AND poem_author = '陶渊明';
UPDATE edu_poem SET poem_translation = '鹳雀楼高高的在飞鸟之上，远离尘世间。\n在上面能看到天空笼罩着平坦的原野，江河流入峻峭的高山。', poem_notes = '唐代河中府名胜，因经常有鹳雀栖息，故得名，后被河水冲没。\n迥临：高高的在上面。迥：常作远或独自的样子解释，此处应描写高远。\n世尘：尘世。\n平野：平坦开阔的原野。晁错《言兵事书》：平原广野，此车骑之地，步兵十不当一。\n断山：陡峭的高山。杜甫《远游》：云长出断山。', poem_tags = '景点,抒情' WHERE poem_title = '登鹳雀楼' AND poem_author = '畅当';
UPDATE edu_poem SET poem_tags = '哲理,故事' WHERE poem_title = '苛政猛于虎' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '今夜可爱的月亮娇媚千般，你向什么地方走去，悠悠慢慢？是不是天外还有一个人间，那里的人刚刚看见月亮升起在东边？茫茫的宇宙空阔无沿，是浩浩长风将那中秋的明月吹远？是谁用绳索系住明月在天上高悬？是谁留住了嫦娥不让她嫁到人间？\n据说月亮是经海底运转，这其中的奥秘无处寻探，只能让人捉摸不透而心中愁烦。又怕那长鲸在海中横冲直撞，撞坏了华美的月中宫殿。蛤蟆本来就熟悉水性，为什么玉兔也能在海中游潜？假如说这一切都很平安，为什么圆月会渐渐变得钩一样弯？', poem_notes = '将旦：天快亮了。\n《天问》体：《天问》是《楚辞》篇名，屈原作，文中向“天”提出了一百七十多个问题，用《天问》体即用《天问》的体式作词。\n可怜：可爱。\n悠悠：遥远的样子。\n别有：另有。\n光影东头：月亮从东方升起。光影：指月亮。\n天外：指茫茫宇宙。\n汗漫：广阔无边。\n送中秋：送走了中秋明月。\n飞镜：喻明月。\n妲娥：传说中的月中仙女嫦娥。\n“谓经海底问无由，恍惚使人愁”两句：意思是据人说月亮运行经过海底，又无法探明其究竟，真让人不可捉摸而发愁。谓：据说。问无由：无处可询问。恍惚：模模糊糊、隐隐约约。\n“怕万里长鲸，纵横触破，玉殿琼楼”三句：意思是如果月亮果真是从海底经过，就怕海中的鲸鱼横冲直撞，把月中的玉殿琼楼撞坏。长鲸：巨大的鲸鱼。纵横：横冲直撞。玉殿琼楼：代指月亮。神话传说云月亮中有华丽的宫殿名广寒宫。\n“虾蟆故堪浴水，问云何玉兔解沉浮”两句：意思是蛤蟆本来就会游泳，月经海底对它并无妨害，为什么玉兔也能在海中沉浮？虾蟆：蛤蟆。传说月中有蟾蜍（蛤蟆）。故：本来。堪：能够。云何：为什么。玉兔：传说中月亮上有白兔在捣药。解沉浮：识枷生，会游泳。\n若道：假如说。\n无恙：安好，无损伤。\n渐渐如钩：圆月慢慢变成弯月。', poem_appreciation = '这是一首具有浪漫主义特色的词篇。作者在小序中明白提示，这首词有两个特点：一是构思与前人不同，”前人诗词有赋待月，无送月者”，而这首却写的是月亮西沉以后的情景；二是自觉地学习屈原，运”用《天问》体”形式。　咏月，是古代诗词中常见的主题之一。仅以唐宋诗词而论，张若虚的《春江花月夜》以”月”为线索，组织全篇，提出了某些带有哲理意味的问题：”江天一色无纤尘，皎皎空中孤月轮。江畔何人初见月？江月何年初照人？”李白《把酒问月》：”但见宵从海上来，宁知晓向云间没。白兔捣药秋复春，姮娥孤栖与谁邻？”苏轼《水调歌头》：”明月几时有？把酒问青天?”看，这些不同的诗词都在向”天”提问，故此也都与屈原的《天问》有千丝万缕的联系。这首《木兰花慢》实际上是继上述诸诗词之后，在歌咏明月这一题材上的新的发展。其特点可归纳为下述三个方面。\n\n　　一是构思有新意。作者不写待月，而是从月亮落去之后起笔，并由此展开想象的翅翼，一会儿飞向广阔的太空，一会儿沉入深幽的海底。最令人惊异的是，生活在八百年前的辛弃疾，竟然在词中接触到月亮绕地球旋转这一科学现象：”是别有人间，那边才见，光景东头？”在作者心目中还有了西半球（”那边”、”别有人间”），当我们这里月亮西沉后，那边才看见月亮东升?光景东头”）。王国维在《人间词话》中禁不住赞叹说：”直悟月轮绕地之理，……可谓神悟。”这的确是难能可贵的。\n\n　　二是巧妙安排神话传说。词中把有关月亮的神话传说集中起来，经过选择、加以编排，使之成为统一整体，创造出带有浪漫色彩的神话形象。词中神话的安排主要按三个焦点加以集中：一是人间（”是别有人间…”）二是天外（”是天外，空汗漫”）；三是海底（”谓经海底问无由”）。三是全篇设问。词是学《天问》，故保留《天问》形式上的特点，但因词的字句可长可短，所以节奏上比《天问》更加生动活泼。\n\n　　本篇是辛词中别具一格的作品。', poem_tags = '中秋节,咏物,月亮,抒怀,忧国' WHERE poem_title = '木兰花慢·可怜今夕月' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_tags = '婉约,女子,惜春,柳树' WHERE poem_title = '忆江南·春去也' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '自己寻访春色去的太晚，以至于春尽花谢，不必埋怨花开得太早。\n自然界的风雨变迁使得鲜花凋谢，春天已然过去，绿叶繁茂，果实累累，已经快到收获的季节了。', poem_notes = '自是：都怪自己\n校：即“较”，比较\n狂风：指代无情的岁月，人事的变迁\n深红色：借指鲜花\n子满枝：双关语。即使是说花落结子，也暗指当年的妙龄少女如今已结婚生子。', poem_appreciation = '关于此诗，有一个传说故事：杜牧游湖州，识一民间女子，年十余岁。杜牧与其母相约过十年来娶，后十四年，杜牧始出为湖州刺史，女子已嫁人三年，生二子。杜牧感叹其事，故作此诗。这个传说不一定可靠，但此诗以叹花来寄托男女之情，是大致可以肯定的。它表现的是诗人在浪漫生活不如意时的一种惆怅懊丧之情。\n\n　　全诗围绕“叹”字着笔。前两句是自叹自解，抒写自己寻春赏花去迟了，以至于春尽花谢，错失了美好的时机。首句的“春”犹下句的“芳”，指花。而开头一个“自”字富有感情色彩，把诗人那种自怨自艾，懊悔莫及的心情充分表达出来了。第二句写自解，表示对春暮花谢不用惆怅，也不必怨嗟。诗人明明在惆怅怨嗟，却偏说“不须惆怅”，明明是痛惜懊丧已极，却偏要自宽自慰，这在写法上是腾挪跌宕，在语意上是翻进一层，越发显出诗人惆怅失意之深，同时也流露出一种无可奈何、懊恼至极的情绪。\n\n　　后两句写自然界的风风雨雨使鲜花凋零，红芳褪尽，绿叶成阴，结子满枝，果实累累，春天已经过去了。似乎只是纯客观地写花树的自然变化，其实蕴含着诗人深深惋惜的感情。\n\n　　此诗主要用“比”的手法。通篇叙事赋物，即以比情抒怀，用自然界的花开花谢，绿树成阴子满枝，暗喻少女的妙龄已过，结婚生子。但这种比喻不是直露、生硬的，而是若即若离，婉曲含蓄的，即使不知道与此诗有关的故事，只把它当作别无寄托的咏物诗，也是出色的。隐喻手法的成功运用，又使此诗显得构思新颖巧妙，语意深曲蕴藉，耐人寻味。', poem_tags = '春天,写景,抒情' WHERE poem_title = '叹花 / 怅诗' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '面对北山岭上白云起伏霏霏，我这隐者自己能把欢欣品味。\n我试着登上高山是为了遥望，心情早就随着鸿雁远去高飞。\n忧愁每每是薄暮引发的情绪，兴致往往是清秋招致的氛围。\n在山上时时望见回村的人们，走过沙滩坐在渡口憩息歇累。\n远看天边的树林活象是荠菜，俯视江畔的沙洲好比是弯月。\n什么时候你能载酒到这里来，重阳佳节咱们开怀畅饮共醉。', poem_notes = '兰山：一作“万山”。万山，一名汉皋山，又称方山、蔓山，在湖北襄阳西北十里。张五：一作“张子容”，兄弟排行不对，张子容排行第八。有人怀疑张五为张八之误。\n“北山”二句：晋陶弘景《诏问山中何所有赋诗以答》：“山中何所有？岭上多白云。只可自怡悦，不堪持赠君。”这两句由此变化而来。北山：指张五隐居的山。北：一作“此”。隐者：指张五。\n相望：互相遥望。试：一作“始”。\n“心随”句：又作“心飞逐鸟灭”、“心随飞雁灭”、“心随鸟飞灭”等。\n薄暮：傍晚，太阳快落山的时候。《楚辞·天问》：“薄暮雷电，归何忧？厥严不奉，帝何求？”\n清秋：明净爽朗的秋天。晋殷仲文《南州桓公九井作》诗：“独有清秋日，能使高兴尽。”一作“清境”。\n归村人：一作“村人归”。\n沙行：一作“沙平”，又作“平沙”。渡头：犹渡口。过河的地方。\n“天边”二句：隋薛道衡《敬酬杨仆射山斋独坐》中有：“遥原树若荠，远水舟如叶。”这两句似是据此变化而成。荠：荠菜。洲：又作“舟”。\n何当：商量之辞，相当于”何妨“或”何如“。\n重阳节：古以九为阳数之极。九月九日故称“重九”或“重阳”。魏晋后，习俗于此日登高游宴。', poem_appreciation = '这是一首临秋登高远望，怀念旧友的诗。全诗情随景生，以景烘情，情景交融，浑为一体。“情飘逸而真挚，景情淡而优美。”诗人怀故友而登高，望飞雁而孤寂，临薄暮而惆怅，处清秋而发兴，希望挚友到来一起共度佳节。“愁因薄暮起，兴是清秋发”，“天边树若荠，江畔洲如月”，细细品尝，够人玩味。\n\n　　开头二句从晋代陶弘景《答诏问山中何所有》诗脱化而来，点明”自怡悦“，为登高望远的缘由之一。\n\n　　三四两句起，进入题意。“相望”表明了对张五的思念。由思念而登山远望，望而不见友人，但见北雁南飞。这是写景，又是抒情，情景交融。雁也看不见了，而又近黄昏时分，心头不禁泛起淡淡的哀愁，然而，清秋的山色却使人逸兴勃发。\n\n　　“时见归村人，平沙渡头歇，天边树若荠，江畔洲如月”，是写从山上四下眺望。天至薄暮，村人劳动一日，三三两两逐渐归来。他们有的行走于沙滩，有的坐歇于渡头。显示出人们的行动从容不迫，带有几分悠闲。再放眼向远处望去，一直看到“天边”，那天边的树看去细如荠菜，而那白色的沙洲，在黄昏的朦胧中却清晰可见，似乎蒙上了一层月色。\n\n　　这四句诗是全篇精华所在。在这些描述中，作者既未着力刻画人物的动作，也未着力描写景物的色彩。用朴素的语言，如实地写来，是那样平淡，那样自然。既能显示出农村的静谧气氛，又能表现出自然界的优美景象。正如皮日休所谓：“遇景入咏，不拘奇抉异。……涵涵然有云霄之兴，若公输氏当巧而不巧者也。”沈德潜评孟诗为“语淡而味终不薄”，实为孟诗的重要特征之一。这四句诗创造出一个高远清幽的境界，同“松月生夜凉，风泉满清听”“微云淡河汉，疏雨滴梧桐”“野旷天低树，江清月近人”等诗的意境，是颇为近似的。这也代表了孟诗风格的一个重要方面。\n\n　　“何当载酒来，共醉重阳节”，照应开端数句。既明点出“秋”字，更表明了对张五的思念，从而显示出友情的真挚。', poem_tags = '唐诗三百首,秋天,登高,怀人' WHERE poem_title = '秋登兰山寄张五 / 九月九日岘山寄张子容' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '其一\n　　我的头发刚刚盖过额头，在门前折花做游戏。你骑着竹马过来，把弄着青梅，绕着床相互追逐。我们同在长干里居住，两个人从小都没什么猜忌。十四岁时嫁给你作妻子，害羞得没有露出过笑脸。低着头对着墙壁的暗处，一再呼唤也不敢回头。十五岁才舒展眉头，愿意永远和你在一起。常抱着至死不渝的信念，怎么能想到会走上望夫台。十六岁时你离家远行，要去瞿塘峡滟滪堆。五月水涨时，滟滪堆不可相触，两岸猿猴的啼叫声传到天上。门前是你离家时徘徊的足迹，渐渐地长满了绿苔。绿苔太厚，不好清扫，树叶飘落，秋天早早来到。八月里，黄色的蝴碟飞舞，双双飞到西园草地上。看到这种情景我很伤心，因而忧愁容颜衰老。无论什么时候你想下三巴回家，请预先把家书捎给我。迎接你不怕道路遥远，一直走到长风沙。\n其二\n　　想当初我在深闺的时候，不曾见识烟尘；可嫁给长干的男人后，整天在沙头等候风色。五月南风吹动的时候，想你正下巴陵；八月西风吹起的时候，想你正从扬子江出发。来来去去，聚少离多，悲伤几何？什么时候到湘潭呢？我最近天天梦见那里大起风波。昨夜又见狂风吹度，吹折了江头的大树。江水淼淼，昏暗无边，夫君啊你在何处？我将乘坐浮云骢，与你相会在兰渚东。鸳鸯嬉戏在绿蒲池上，翡翠鸟儿绣在锦屏当中。自顾自怜才十五岁多，面容正如桃花一般嫣红。哪里想到嫁为商人妇，既要愁水又要愁风。', poem_notes = '长干行：属乐府《杂曲歌辞》调名。下篇一作张潮。黄庭坚作李益诗。\n长干里：在今南京市，当年系船民集居之地，故《长干曲》多抒发船家女子的感情。\n抱柱信：典出出《庄子·盗跖篇》，写尾生与一女子相约于桥下，女子未到而突然涨水，尾生守信而不肯离去，抱着柱子被水淹死。\n滟滪堆：三峡之一瞿塘峡峡口的一块大礁石，农历五月涨水没礁，船只易触礁翻沉。\n天上哀：哀一作“鸣”。\n迟行迹：迟一作“旧”。\n生绿苔：绿一作“苍”。\n长风沙：地名，在今安徽省安庆市的长江边上，距南京约700里。\n忆妾深闺里：妾一作“昔”。\n沙头：沙岸上。风色：风向。\n下：一作“在”。巴陵：今湖南岳阳。\n发：出发。扬子：扬子渡。\n湘潭：泛指湖南一带。\n淼淼：形容水势浩大。\n浮云骢：骏马。西汉文帝有骏马名浮云。\n兰渚：生有兰草的小洲。\n翡翠：水鸟名。', poem_appreciation = '诗人李白写过许多反映妇女生活的作品，《长干行两首》就是其中杰出的诗篇。\n\n　　长干是地名，在今江苏南京。乐府旧题有《长干曲》，郭茂倩《乐府诗集》卷七二载有古辞一首，五言四句，写一位少女驾舟采菱、途中遇潮的情景。与李白同时的崔颢有《长干曲》，崔国辅有《小长干曲》，也都是五言四旬的小乐府体，所描绘的都是长江中下游一带男女青年的生活场景。这些诗歌内容都较简单。李白《长干行》的篇幅加长了，内容也比较丰富。它以一位居住在长干里的商妇自述的口气，叙述了她的爱情生活，倾吐了对于远方丈夫的殷切思念。它塑造了一个具有丰富深挚的情感的少妇形象，具有动人的艺术力量。\n\n　　这是两首爱情叙事诗。第一首诗对商妇的各个生活阶段，通过生动具体的生活侧面的描绘，在读者面前展开了一幅幅鲜明生动的画面。诗人通过运用形象，进行典型的概括，开头的六句，婉若一组民间孩童嬉戏的风情画卷。“十四为君妇”以下八句，又通过心里描写生动细腻地描绘了小新娘出嫁后的新婚生活。在接下来的诗句中，更以浓重的笔墨描写闺中少妇的离别愁绪，诗情到此形成了鲜明转折。“门前迟行迹”以下八句，通过节气变化和不同景物的描写，将一个思念远行丈夫的少妇形象，鲜明地跃然于纸上。最后两句则透露了李白特有的浪漫主义色彩。这阕诗的不少细节描写是很突出而富于艺术效果的。如“妾发初覆额”以下几句，写男女儿童天真无邪的游戏动作，活泼可爱。“青梅竹马”成为至今仍在使用的成语。又如“低头向暗壁，千唤不一回”，写女子初结婚时的羞怯，非常细腻真切。诗人注意到表现女子不同阶段心理状态的变化，而没有作简单化的处理。再如“门前迟行迹，一一生绿苔”，“八月胡蝶黄，双飞西园草”，通过具体的景物描写，展示了思妇内心世界深邃的感情活动，深刻动人。\n\n　　第二首诗与第一首诗同是写商妇的爱情和离别的诗。第二首诗恰似第一首诗中的少妇风尘仆仆地划着小船来到长风沙的江边沙头上等候久别的丈夫。此诗在描述女子情感脉络上非常细密柔婉，像是山林中的清泉涓涓流畅而又还回曲折，给读者留下数不清的情韵，把少妇的闺怨描写得淋漓酣畅。这首诗中，诗人用“嫁与长干人，沙头候风色”两句便将女主人公的身世交代得清清楚楚。“五月南风兴”以下四句交代了诗中丈夫的行踪。“昨日狂风度，吹折江头树”则表现了她对夫婿安危的深切关怀，最后，“自怜十五余，颜色桃花江。那作商人妇，愁水复愁风”以少妇感怀身世的方式将满腔离愁别恨渲染得恰到好处。这首诗将南方女子温柔细腻的感情刻画得十分到位。全诗感情细腻，缠绵婉转，步步深入，语言坦白，音节和谐，格调清新隽永，也属诗歌艺术的上品。\n\n　　但是，与第一首诗相比起来，第二首诗显得要稍逊一筹。第二首诗与其他描写闺怨题材的诗一样，是从少妇时期入手， 而第一首诗却别出心裁，偏偏从童年时期的两小无猜写起，李白在此诗中打破了陈规，自出机杼。它通过描绘出的一副副生活场景 ，精心渲染环境气氛，使得人物性格更加生鲜自然，显示出完整性和独创性。一连串具有典型意义的生活片段和心理活动的描写，几乎显示了女主人公的一部性格发展史。这些是第二首诗所没有达到的艺术高度。\n\n　　透过第一首诗典型化的语言，塑造出了一个典型的商人小妇形象。这就是典型的塑造——典型环境中的典型人物。用“清水出芙蓉，天然去雕饰”来赞美这首诗是最贴切不过了，相形之下，第二首诗略显平庸，一则在于它的遣词用句没有前者的创新性，二者它的叙述方式没有摆脱掉其他相同题材诗歌的影子。它更加注重愁怨的描写，而第一首的最后两句“相迎不道远，直至长风沙”则带有一丝脱离封建礼教的解放色彩。因此，第一首诗塑造的人物更加鲜明饱满，更令读者喜爱。\n\n　　《长干行二首》的风格缠绵婉转，具有柔和深沉的美。商妇的爱情有热烈奔放的特点，同时又是那样地坚贞、持久、专一、深沉。她的丈夫是外出经商，并非奔赴疆场，吉凶难卜；因此，她虽也为丈夫的安危担心，但并不是摧塌心肺的悲恸。她的相思之情正如春蚕吐丝，绵绵不绝。这些内在的因素，决定了作品风格的深沉柔婉。', poem_tags = '乐府,妇女,爱情,叙事,思念,生活' WHERE poem_title = '长干行二首' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '万里奔流的长江，像一匹白色的素绢；对岸几处小点，像是染上了青色的颜料，那是淮地的远山。几片白帆，箭一般地驶过了江面；而近处的高山上，长长的泉流飞下，犹如一道流电。天色渐渐昏黄，暮色中的云层难以分辨，仿佛化作了这满地的露点。一钩新月模仿着扇形，在天上高悬。逼近了，逼近了，成“一”字的横线在空中排开，那是北方飞来的大雁。', poem_notes = '浔阳：今江西九江市。\n即景：写眼前景物。\n练：白绢。\n淮山：泛指长江以北淮河流域的山。\n淀：同“靛”，即靛青，一种青兰色染料。\n江帆：江面上的船。\n“新月”句：新月开始像团扇那样圆了起来。\n塞鸿：边地的鸿雁。\n新月初学扇：言新出的月亮，圆得象团扇似的。班婕妤《怨歌行》：“裁成合欢扇，团团似明月。”', poem_tags = '秋天,写景' WHERE poem_title = '塞鸿秋·浔阳即景' AND poem_author = '周德清';
UPDATE edu_poem SET poem_tags = '牡丹,惜花,组诗' WHERE poem_title = '惜牡丹花二首' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '春风卷着漫天大雪，飘来飘去，落得到处都是。\n你看那欣赏雪景的人们，原都是居住在洛阳城中的富贵人家啊！', poem_notes = '徘徊：来回地行走。诗中指雪花飞来飞去。\n君：相当于“你”，有尊敬的意思。\n似花处：指雪花落在树枝上，如盛开的梨花一般。\n洛城：即洛阳；洛城中：即“洛城东”，当时豪贵宅第之所在。', poem_appreciation = '“飞雪带春风，徘徊乱绕空”，是写景；第三句“君看似花处”，有承有转，过渡句，使诗文由景转情。第四句“洛城中”，一作“洛城东”，这里指富贵人家居住之地。联系诗题来看这两句，那意思是说冬天已经结束，突然来了一场春雪，这在那些无饥寒之虑的富贵人心中，不由得产生了一种难得又见的满足和喜悦，于是这熟悉而又新鲜的飞雪，在他们的眼中便成了飞花舞空的美景。但是，对于“洛城外”的穷人来说，他们好不容易在饥寒交迫中熬过了大雪纷飞的隆冬，盼来了春回大地，谁知又来一场大雪，这逝而复回的威胁和灾难，所带来的艰难与怨恨是不难想见的。这首诗的得力之处正在尾句，尾句之中又得力于一个“偏”字，是它构成了虚实两个空间，两种境界，两种生活，两种感情的对比，而诗人的爱与恨，同情与憎恶，也都融入这个对比之中。通过对比所展现的不同状况，及其所孕育的主题等，都留在了诗外，为读者开拓了广阔的想象空间。\n\n　　此诗通过描写一场突如其来的春雪，侧面写出了富人们在屋内赏雪以美酒相伴，穷人们却在雪天流落街头，形成鲜明对比。诗人用曲折的笔法，讽刺了那班达官贵人只图自己享乐，忘了广大地区人民的贫困。', poem_tags = '写雪' WHERE poem_title = '春雪' AND poem_author = '刘方平';
UPDATE edu_poem SET poem_translation = '注释 花絮，指桃柳。 《唐书》：广德二年十月，仆固怀恩诱吐蕃、回纥入寇。十一月，吐蕃遁去。永泰元年二月，党项寇富平。【鹤注】富平，属京兆府。 【顾注】周亚夫营，在昆明池南，今桃市是也。时郭子仪屯兵泾原，为吐蕃请盟之故。', poem_tags = '春天,思乡' WHERE poem_title = '春远 / 春运' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '译文 这匹马不像是人间的凡马， 似乎是天上的房星下凡。 它看上去瘦骨磷峋，可你如果上前去敲一敲它的瘦骨， 好像还能听见铮铮的铜声。', poem_appreciation = '首句开门见山，直言本意，肯定并且强调诗歌所表现的是一匹非同寻常的好马。起句平直，实在没有多少诗味。\n\n　　次句“房星本是星”，乍看起来像是重复第一句的意思。“房星”指马，句谓房星原是天上的星宿，也就是说这匹马本不是尘世间的凡物。如果这句的含义仅限于此，与首句几乎一模一样，那就犯了重沓的毛病。诗只四句，首句平平，次句又作了一次重复，那么这首诗就有一半索然无味，没有价值。但如细细咀嚼，便会发现第二句别有新意，只是意在言外，比较隐晦曲折。《晋书·天文志》中有这样一段话：“房四星，亦曰天驷，为天马，主车驾。房星明，则王者明。”它把“房星”和“王者”直接联系起来，就是说马的处境如何与王者的明暗、国家的治乱息息相关。既然马的素质好遭遇不好，那么，王者不明，政事不理的状况就不言可喻了。这是一种“渗透法”，通过曲折引申，使它所表达的实际意义远远超过字面的含义。\n\n　　三、四句写马的形态和素质。如果说前二句主要是判断和推理，缺乏鲜明生动的形象，那么，后二句恰恰相反，它们绘声绘影，完全借助形象表情达意。李贺写诗，善于捕捉形象，“状难见之景如在目前”，这两句就是突出的例子。“瘦骨”写形，表现马的处境；“铜声”写质，反映马的素质。这匹马瘦骨嶙嶙，说明境遇不好。在常人的眼里，它不过是匹筋疲力尽的凡马，只有真正爱马并且善于相马的人，才不把它当作凡马看待。“向前敲瘦骨，犹自带铜声。”尽管它境遇恶劣，被折腾得不成样子，却仍然骨带铜声。“铜声”二字，读来浑厚凝重，有立体感。它所包含的意思也很丰富：铜声悦耳，表明器质精良，从而生动地显示了这匹马骨力坚劲的美好素质，使内在的东西外现为可闻、可见、可感、可知的物象。“素质”原很抽象，“声音”也比较难于捉摸，它们都是“虚”的东西。以虚写虚，而又要化虚为实，的确很不容易，而诗人只用了短短五个字就做到了，形象化技法之高妙，可说已达到炉火纯青的程度。尤其可贵的是，诗歌通过写马，创造出物我两契的深远意境。诗人怀才不遇，景况凄凉，恰似这匹瘦马。他写马，不过是婉曲地表达出郁积心中的怨愤之情。', poem_tags = '写马,抒怀,怀才不遇' WHERE poem_title = '马诗二十三首·其四' AND poem_author = '李贺';
UPDATE edu_poem SET poem_translation = '我所思念的人，就在大海的南边。\n我拿什么赠给你呢？这是一支玳瑁簪，\n上面装饰有珍珠和玉环。\n听说他有二心，心里伤悲，拆碎它。\n捣毁它，烧掉它！烧掉它，风把灰尘扬起！\n从今往后，不再思念你，\n我同你断绝相思！\n当初与你约会时，不免引起鸡鸣狗吠。\n兄嫂也可能了知道此事，哎……\n听到屋外秋风声里鸟儿飞鸣，情绪更乱，\n一会儿天亮了，我就会知道该怎么做的。', poem_notes = '有所思：指她所思念的那个人。\n何用：何以。问遗（wèi）：“问”、“遗”二字同义，作“赠与”解，是汉代习用的联语。\n玳瑁（dài mào）：即玳瑁，是一种龟类动物，其甲壳光滑而多文采，可制装饰品。簪：古人用以连接发髻和冠的首饰，簪身横穿髻上，两端露出冠外，下缀白珠。\n绍缭：犹“缭绕”，缠绕。\n拉杂：堆集。这句是说，听说情人另有所爱了，就把原拟赠送给他的玉、双珠堆集在一块砸碎，烧掉。\n相思与君绝：与君断绝相思。\n鸡鸣狗吠：即“惊动鸡狗”。古诗中常以“鸡鸣狗吠”借指男女幽会。\n妃(bēi)呼豨（xū xī）：妃，训为“悲”，呼豨，训为“歔欷”。\n肃肃：飕飕，风声。晨风飔(sī)：据闻一多《乐府诗笺》说：晨风，就是雄鸡，雉鸡常晨鸣求偶。飔当为“思”，是“恋慕”的意思。一说，“晨风飔”，晨风凉。\n须臾：不一会儿。高（hào）：是“皜”、“皓”的假借字，白。“东方高”，日出东方亮。', poem_appreciation = '这是汉代《铙歌十八曲》之一。铙歌本为“建威扬德，劝士讽敌”的军乐，然今传十八曲中内容庞杂，叙战阵、记祥瑞、表武功、写爱情者皆有。清人庄述祖云：“短箫铙歌之为军乐，特其声耳；其辞不必皆序战阵之事。”（《汉铙歌句解》）本篇就是用第一人称，表现一位女子在遭到爱情波折前后的复杂情绪的。\n\n　　开头五句写其对远方的情郎心怀真挚热烈的相思爱恋：她所思念的情郎，远在大海的南边。相去万里，用什么信物赠与情郎，方能坚其心而表己意呢？问遗，犹言赠与。她经过一番精心考究，终于选择了“双珠瑇瑁簪”。“瑇瑁簪”，即用玳瑁(一种似龟的动物)那花纹美观的甲片精制而成的发簪。“双珠”，谓在发簪两端各悬一颗珍珠。这在当时可谓精美绝伦的佩饰品了。然而女主人公意犹未足，再用美玉把簪子装饰起来，更见美观（绍缭，缠绕之意）。单从她对礼品非同寻常的、不厌其烦的层层装饰上，就可测出她那内心积淀的爱慕、相思的浓度和分量了。这几句写物寄情，以少总多，表达已言简意丰，情调复缠绵悱恻。试看汉末繁钦《定情诗》中“何以致拳拳？绾臂双金环。”“何以致区区？耳中双明珠。”“何以结恩情？佩玉缀罗缨。”“何以慰别离？耳后瑇瑁钗”等句，分明是受本篇启发而化出，此亦正可发明本诗“何用”三句意蕴之妙处。\n\n　　可惜天有不测风云，晴光滟敛的爱河上顿生惊涛骇浪，爱情的指针突然发生偏转，“闻君有他心”以下六句，写出了这场风波及其严重后果：她听说情郎已倾心他人，真如晴天霹雳！骤然间，爱的柔情化作了恨的力量，悲痛的心窝燃起了愤怒的烈火。她将那凝聚着一腔痴情的精美信物，愤然地始而折断(拉杂)，再而砸碎 (摧)三而烧毁，摧毁烧掉仍不能泄其愤，消其怒，复又迎风扬掉其灰烬。“拉、摧、烧、扬”，一连串动作，如快刀斩乱麻，干脆利落，何等愤激！“从今以后，勿复相思！”一刀两断，又何等决绝！非如此，不足以状其“望之深，怨之切。”（陈祚明《采菽堂古诗选》评语）\n\n　　“相思与君绝”以下六句，写其由激怒渐趋冷静之后，欲断不能的种种矛盾、彷徨的复杂心态。“相思”句较上文“勿复相思”之果断决绝，口气已似强弩之末。盖 “相思”乃长期的感情积淀，而“与君绝”，只一时愤激之念，二者本属对立而难统一，故此句实乃出于矛盾心情的叹惋，大有“剪不断，理还乱”之意蕴。循此绪端，自然生出“鸡鸣狗吠，兄嫂当知之”的回忆和忧虑。“鸡鸣狗吠”“喻风声布闻。”（《诗比兴笺》）《易林·随之既济》：“当年早寡，孤与（宇）独居；鸡鸣狗吠，无敢问者。”即指鳏夫与寡妇夜间来往，惊鸡动狗，已露风声。此处亦谓女子忆昔与郎幽会往来，不免风吹草动，使兄嫂备悉隐情，而今若断绝，居家将何以见人？对兄嫂又如何解释？所谓“不待父母之命，媒妁之言，钻隙穴相窥，逾墙相从，则父母国人皆贱之。”(《孟子·滕文公下》）加上始乱终弃的严重后果，自然使她不无顾虑和动摇。何况那“鸡鸣狗吠”中幽会的柔情蜜意时刻，仍然顽固地在牵动着她那旧日的缕缕情思，使她依依难舍呢！“妃呼豨”，正是她在瞻前顾后，心乱如麻的处境中情不自禁地发出的一声歔欷长叹。清人陈本礼《汉诗统笺》云：“妃呼豨，人皆作声词读，细观上下语气，有此一转，便通身灵豁，岂可漫然作声词读耶？”闻一多《乐府诗笺》亦云：“妃读为悲，呼豨读为?歔欷。”训释至为允当。三字悲叹，在感情、语气上承上启下，直贯结尾二句意脉。“肃肃”，形容风声凄紧；“晨风”，即晨风鸟。《诗·秦风·晨风》：“鴥彼晨风，郁彼北林。未见君子，忧心钦钦。”晨风鸟即雉，朝鸣以求偶。“飔”，闻一多训为乃 “思”字之讹，言晨风鸟慕类而悲鸣。“高”，音、义皆同“皓”，指东方发白，天将欲晓。二句写女子在悲叹中但闻秋风阵阵凄紧，野雉求偶不得的悲鸣不时传来，使她更加感物共鸣，相思弥甚，犹豫不决。然而她又自信：只待须臾东方皓白，定会知道该如何解决这一难题的。陈本礼云：“言我不忍与君绝决之心，固有如曒日也。谓予不信，少待须臾，俟东方高则知之矣。”（《汉诗统笺》）如此，则“高”尚有喻其心地光明皎洁，感情热烈持恒之义。不过，这层隐喻之底奥，在字面上却是含而不露、引而不发的，读者似乎亦拭目以待其下文。故庄述祖、闻一多皆以为《上邪》即本篇下文，应合为一篇。余冠英亦认为“合之则双美，离之则两伤。”此说确实发人深省。\n\n　　此诗的结构，以“双珠瑇瑁簪”这一爱情信物为线索，通过“赠”与“毁”及毁后三个阶段，来表现主人公的爱与恨，决绝与不忍的感情波折，由大起大落到余波不竭。中间又以“摧烧之”、“相思与君绝”两个顶真句，作为爱憎感情递增与递减的关纽；再以“妃呼豨”的长叹，来联缀贯通昔与今、疑与断的意脉，从而构成了描写女子热恋、失恋、眷恋的心理三部曲。层次清晰而又错综，感情跌宕而有韵致。其次，这首诗通过典型的行动细节描写（选赠礼物的精心装饰，摧毁礼物的连贯动作）和景物的比兴烘托（“鸡鸣狗吠”及末尾二句）来刻画人物的细微心曲，也是相当成功的。', poem_tags = '乐府,闺怨,爱情,思念,分手' WHERE poem_title = '有所思' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '西王母在瑶池上把绮窗打开；\n只听得黄竹歌声音动地悲哀。\n八骏神马的车子日行三万里；\n周穆王为了何事违约不再来？', poem_notes = '瑶池阿母：《穆天子传》卷三：“天子宾于西王母，天子觞西王母于瑶池之上。西王母为天子谣曰：‘白云在天，山陵自出。道里悠远，山川间之。将子无死，尚能复来。’天子答之曰：‘予归东土，和治诸夏。万民平均，吾顾见汝。比及三年，将复而野。’”《武帝内传》称王母为“玄都阿母”。\n黄竹歌声：《穆天子传》卷五：“日中大寒，北风雨雪，有冻人。天子作诗三章以哀民。”\n八骏：传说周穆王有八匹骏马，可日行三万里。《列子》、《穆天子传》等记载不一。\n穆王：西周人，姓姬名满，传说他曾周游天下。\n此诗讽刺求仙之虚妄。首句写西王母倚窗伫望，候穆王而不至。次句借黄竹歌声暗示穆王已死。三四句则写西王母因穆王不来而心生疑问。斥神仙而以神仙（王母）的口气写出，句句对比，以见长生之虚妄，求仙之荒诞。《李义山诗集笺注》引程梦星曰：“此追叹武宗之崩也。武宗好仙，又好游猎，又宠王才人。此诗熔铸其事而出之，只用穆王一事，足概武宗三端。用思最深，措辞最巧。”', poem_tags = '唐诗三百首,神话,讽刺' WHERE poem_title = '瑶池' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '和十年(公元815年)，韩愈作《示儿》诗，元和十一年，作《符读书城南》。后世对退之示儿诗争议颇多。如苏东坡称“退之示儿云云，所示皆利禄事也”。邓肃：“用玉带金鱼之说以激之，爱子之情至矣，而导子之志则陋也。”后世反驳的说法也很多。', poem_tags = '亲情' WHERE poem_title = '示儿' AND poem_author = '韩愈';
UPDATE edu_poem SET poem_translation = '楼殿高阁前有芳林花草竞相争春，妃子们本就貌美如花，再加上盛装打扮，更加显出倾城之貌。\n妃子起初掩映着窗子，外面春光的娇美之景无法进入她们的芳阁。但妃子一出闺阁，万般春日丽景都失去了颜色。妃子笑容可掬，盈盈走出门户。\n她们的脸就像带着晶莹雨露的鲜花，她们的美态就如玉树那样秀丽，流光溢彩，清雅别致。\n花儿从开放时的争奇斗艳到枯萎的凋零是很短暂的时光，到花瓣都落光的时候一切又都归于了平凡。', poem_notes = '对：相对，对面。这里指高阁前有芳林花草。\n倾城：使城池倾倒，形容女子貌美。\n乍：开始，起初。\n帷：帷帐，帷幄。\n玉树：玉树的树冠挺拔秀丽，茎叶碧绿，顶生白色花朵，十分清雅别致。\n流光：玲珑剔透，流光溢彩。', poem_appreciation = '陈后主所作的《玉树后庭花》歌，写的是嫔妃们娇娆媚丽，堪与鲜花比美竞妍，其词哀怨靡丽而悲凉，后来成为亡国之音的代称。\n\n　　“丽宇芳林对高阁，新妆艳质本倾城。”诗的开头概括了宫中环境，并化用汉朝李延年的“一顾倾人城，再顾倾人国”诗句，来映衬美人的美丽。华丽的殿宇，花木繁盛的花园，没人居住的高阁就在这殿宇的对面，在花丛的环绕之中。美人生来就美丽，再经刻意妆点，姿色更加艳丽无比。\n\n　　“映户凝娇乍不进，出帷含态笑相迎。”写美人们应召见驾时的情态，仪态万千，风情万种。无论是应召时的“乍不进”，还是接驾时的“笑相迎”，都讨得后主的无比欢欣。“妖姬脸似花含露，玉树流光照后庭。”诗的结尾处与开头相呼应，重点描绘了宫中美人的“倾国倾城之貌”，也成了陈后主留恋后宫，贪恋美人的最好注脚。\n\n　　诗歌在艺术上有以下几个方面的特点：一是着意于从侧面、动态的角度去描写，力求舍形而求神，诗中所用的“似花含露”、“玉树流光”的描写都极为生动传神；二是全诗结构紧凑，回环照应，景与人相互映衬，意象美不胜收。这首诗在一定程度上，代表了宫体诗的最高水平。从一个侧面可以看出，陈后主虽然是一个糟糕的皇帝，但却是一个具有一定艺术修养的诗人。', poem_tags = '乐府,宫廷,写花,寓人' WHERE poem_title = '玉树后庭花' AND poem_author = '陈叔宝';
UPDATE edu_poem SET poem_translation = '临川郡城的东面，有一块地微微高起，并且靠近溪流，叫做新城。新城上面，有个池子低洼呈长方形，说是王羲之的墨池，这是荀伯子《临川记》里说的。\n\n　　羲之曾经仰慕张芝“临池学书，池水尽黑”的精神，(现在说)这是羲之的(墨池)遗址，难道是真的吗？当羲之不愿勉强做官时，曾经游遍东方，出游东海，在山水之间使他的心情快乐。莫非他在尽情游览时，曾在这里停留过？羲之的书法，到晚年才特别好。那么他能达到这步，大概也是靠他自己的精神和毅力取得的，并不是天生的。但是后代没有能够赶上他的人，是不是后人学习下的功夫不如他呢？那么学习的功夫难道可以少下吗？何况想在道德修养上深造的人呢？\n\n　　墨池的旁边，现在是抚州州学的校舍，教授王盛先生担心墨池不能出名，写了“晋王右军墨池”六个字挂在屋前两柱之间，又请求我说：“希望有一篇(墨池)记。”推测王先生的用心，是不是喜爱别人的优点，即使是一技之长也不让它埋没，因而推广到王羲之的遗迹呢？莫非也想推广王羲之的事迹来勉励那些学员吧？一个人有一技之长，就能使后人像这样尊重他；何况那些品德高尚、行为端庄的人，遗留下来令人思慕的美好风范，对于后世的影响那就更不用说了！\n\n　　庆历八年九月十二日，曾巩作记。', poem_notes = '临川：临川：宋朝的抚州临川郡(今江西省临川市)。\n隐然而高：微微地高起。隐然：不显露的样子。\n临：从高处往低处看，这里有“靠近”的意思。\n洼然：低深的样子。\n方以长：方而长，就是长方形。\n王羲之(321—379)：字逸少，东晋人，官至右军将军，会稽内史，世称王右军。他是古代有名的大书法家，世称“书圣”。苟伯子：南朝宋人，曾任临川内史。著有《临川记》六卷，其中提到：“王羲之尝为临川内史，置宅于郡城东南高坡，名曰新城。旁临回溪，特据层阜，其地爽垲(kǎi，地势高而干燥)，山川如画。今旧井及墨池犹存。”\n张芝：东汉末年书法家，善草书，世称“草圣”。王羲之“曾与人书云：‘张芝临池学书，池水尽黑，使人耽(dān，酷爱)之若是，未必后之也。’”(《晋书·王羲之传》)\n信然：果真如此。\n邪：吗，同“耶”。\n方：当……时。\n强以仕：勉强要(他)作官。王羲之原与王述齐名，但他轻视王述，两人感情不好。后羲之任会稽内史时，朝廷任王述为扬州刺史，管辖会稽郡。羲之深以为耻，称病去职，誓不再仕，从此“遍游东中诸郡，穷诸名山，泛沧海”。\n极东方：游遍东方。极，穷尽。\n出沧海：出游东海。沧海，指东海。\n娱其意：使他的心情快乐。\n岂有：莫非。\n徜徉肆恣：尽情游览。徜徉，徘徊，漫游。肆恣，任意，尽情。\n休：停留。\n书：书法。\n晚乃善：到晚年才特别好。《晋书·王羲之传》：“羲之书初不胜(不及)庾翼、郄愔(xìyìn)，及其暮年方妙。尝以章草答庾亮，而(庾)翼深叹伏。”所能：能够达到这步。\n盖：大概，副词。以精力自致者：靠自己的精神和毅力取得的。\n致，取得。天成：天然生成。\n及：赶上。\n岂其学不如彼邪：是不是他们学习下的功夫不如王羲之呢？岂，是不是，表示揣测，副词。学，指勤学苦练。\n则学固岂可以少哉：那么学习的功夫难道可以少下吗？则，那么，连词。固，原来，本。岂，难道，表示反问，副词。\n深造道德：在道德修养上深造，指在道德修养上有很高的成就。\n州学舍：指抚州州学的校舍。\n教授：官名。宋朝在路学、府学、州学都置教授，主管学政和教育所属生员。\n其：指代墨池。\n章：通“彰”，显著。\n楹间：指两柱子之间的上方一般挂匾额的地方。楹，房屋前面的柱子。\n揭：挂起，标出。\n推：推测。\n一能：一技之长，指王羲之的书法。\n不以废：不让它埋没。\n因以及乎其迹：因此推广到王羲之的遗迹。\n推：推广。\n学者：求学的人。\n夫：语气词，放在句首，表示将发议论。\n尚之如此：像这样尊重他。尚，尊重，崇尚。\n仁人庄士：指品德高尚、行为端庄的人。\n遗风余思：遗留下来令人思慕的美好风范。余思，指后人的怀念。余，也是“遗”的意思。\n被于来世：对于后世的影响。被，影响。\n何如哉：会怎么样呢？这里是“那就更不用说了”的意思。', poem_tags = '辞赋精选,状物,写人,寓理' WHERE poem_title = '墨池记' AND poem_author = '曾巩';
UPDATE edu_poem SET poem_tags = '边塞,组诗' WHERE poem_title = '凉州词三首' AND poem_author = '张籍';
UPDATE edu_poem SET poem_translation = '在遥远的故乡，曾听过子规鸟凄恻的鸣啼；如今在异乡宣城，又看到盛开的杜鹃花。\n子规鸣叫悲啭，使人愁肠寸断。暮春三月，这鸟鸣花开的时节，游子正思念他的故乡三巴。', poem_notes = '宣城：今属安徽。\n蜀国：指四川。\n子规鸟：又名杜鹃，因鸣声凄厉，动人乡思，故俗称断肠鸟，蜀地最多；传说是古蜀王杜宇死后所化。\n杜鹃花：即映山红，每年春末盛开，正是杜鹃鸟啼之时，故名杜鹃花。\n三春：指春季。三巴：巴郡、巴东、巴西三郡，即指蜀国，今四川。', poem_appreciation = '此诗是感物而起兴的。“蜀国曾闻子规鸟，宣城还见杜鹃花。”暮春三月，寄寓在宣城的李白，觉得昏花的老眼中忽然映入一片红色，仔细瞧，原来是杜鹃花开了。这杜鹃好像就是故乡的花。诗人的乡思因此被触动了。\n\n　　在蜀中，每逢杜鹃花开的时候，子规鸟就开始啼鸣了。子规鸟，又名杜鹃，花与鸟的名字相同，也是勾起诗人联想的一个原因。这鸟，相传是古蜀帝杜宇的精魂化成。杜宇号称望帝，他自以为德薄，于是禅让了帝位而出亡，死后化为杜鹃鸟。暮春时节，它就悲鸣起来，鸣声仿佛是呼叫着：“不如归去！不如归去！”昼夜不止，一直啼叫得嘴边淌出血来。此刻，诗人耳边似乎响起了子规鸟的蹄叫声，一声声地呼唤他归去。\n\n　　诗的一、二句，形成自然的对仗，从地理和时间两个方面的对比和联结中，真实地再现了触动乡思的过程。这两句的语序倒置：本来是先看见宣城的杜鹃花，才联想到蜀国的子规鸟，诗人却将它倒了过来，先写回忆中的虚景，后写眼前的实景。这样，就把故国之思放在了突出的位置上，表明这故国之思原本就郁积于心，此时一旦勾起，大为凄苦强烈。然而，被乡思苦苦折磨着的诗人，眼下不能回到故乡去。青年时代，他“仗剑去国，辞亲远游”，要到故乡之外的广阔天地中去实现宏伟抱负。本想功成名退再荣归故里。不料功业无成，老来竟落到这步田地，他觉得没有面目见蜀中父老。何况，李白眼下困居宣城，拖着老迈的病体，也无法踏上旅途。飘泊终生的诗人，到头来不但政治与事业上没有归宿，就连此身也无所寄托，遥望着千里之外的故乡，他心中的悲戚可想而知。\n\n　　三、四句，分别承接一、二句，进一步渲染浓重的乡思。首句说“曾闻”，第三句则强调了真切如闻：子规鸟的俗名，就叫断肠鸟，“一叫一回肠一断”，它啼叫起来，没完没了，诗人的愁肠也断成一寸寸了。末句点明时令，用“三春三月”四字，补叙第二句；“忆三巴”三字，则突现了思乡的主题，把杜鹃花开、子规悲啼和诗人的断肠之痛融于一体，以一片苍茫无涯的愁思将全诗笼罩了起来。诗的三、四句看似对仗，其实对得又不甚工。诗句把“一”“三”两个字各自串连起来，纡结萦回，使人感到乡思袭来时无比的悲切伤痛。', poem_tags = '思乡' WHERE poem_title = '宣城见杜鹃花 / 子规' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '烟波渺渺，垂柳依依，芳草萋萋蔓延至天际，远处斜横着几间茅屋，在夕阳余辉的映照中又飞舞着片片杏花。江南的春天已经过去，离人愁思萦绕；汀州长满了蘋花，心上人还未回还。', poem_notes = '江南春：词牌名。\n柳依依：化用《诗经·小雅·采薇》诗句：“昔我往矣，杨柳依依。”\n芳草远：化用《楚辞·招隐士》句：“王孙游兮不归，春草生兮萋萋。”\n蘋满汀洲：代指春末夏初的时令。蘋：一种水生植物，也叫四叶菜、田字草。汀州：水中的小块陆地。', poem_tags = '宋词精选,写景,女子,怀人' WHERE poem_title = '江南春·波渺渺' AND poem_author = '寇准';
UPDATE edu_poem SET poem_translation = '江南丹桔叶茂枝繁，经冬不凋四季常青。\n岂止南国地气和暖，而是具有松柏品性。\n荐之嘉宾必受称赞，山重水阻如何进献？\n命运遭遇往往不一，因果循环奥秘难寻。\n只说桃李有果有林，难道丹桔就不成阴？', poem_notes = '伊：语助词。岁寒心：意即耐寒的特性。\n荐：进奉意。\n树：种植意。', poem_appreciation = '诗开头两句，诗人就以饱满的热情，颂扬橘树经得起严冬考验，绘制了一幅江南橘林的美丽图景，形成了一个优美的艺术境界。橘树是果树中的上品，又能经得起严冬风霜的熬煎，终年常绿，因此诗人以丹橘自喻是有深刻含意的。这是诗人借用橘树来比喻自己“受命不迁”、“横而不流”的人格。这里，诗人不仅写了橘树的外形，而在着意表现它坚强不屈的精神，达到了形神的有机结合。同时呈献在读者面前的，并非一棵橘树，而是一片橘林。诗人是在描写包括他自己在内的“群像”。这就使得诗的意境更为深远开阔，形象更为高大生动。\n\n　　三、四两句，写橘树的特点。诗人告诉读者橘树的经冬翠绿，并非因为江南气候暖和，而是因为它有着耐寒的本性。在这里，诗人采用的是问答的形式，问得自然出奇，答得分外有味，把橘树本身的特性简明地概括出来。诗人通过“岁寒心”的双关语，一方面巧妙地指出橘树的耐寒本性，同时又用以比喻诗人的高尚美德。这是借橘树的本性写诗人的心灵之美，既是诗中主人公的自我画像，也是当时千万个正直知识分子的品德的写照。从而使诗的主旨又深化了一层。\n\n　　下面六句，是叙事，也是抒情。五、六两句是说：这些甜美的丹橘本可以送到远方呈献给尊贵的客人，无奈关山重叠，通道受阻。言下之意，他本可以将贤者推荐给朝廷，可惜道路被阻塞。这两句妙喻天成，不露痕迹。诗人借用眼前的景物，通过丰富的想象，表现了封建社会一个忠君爱国的知识分子，在遭贬的情况下，仍然不甘沉沦，依旧关心国家前途和命运的可贵品质。七、八两句是诗人从感慨中得出的判断：命运的好坏，只是因为遭遇的不同；而这又如同周而复始的自然规律一样，其中的道理实在难以捉摸。这是诗人根据自身经历所发出的感叹。最后两句是紧承“运命”两句而来。诗人大声疾呼：不要只说种桃李，橘树难道不能供人乘凉吗？很清楚，诗人在为橘树鸣不平，也是在为贤者鸣不平。也就是说，贤者能人，不会不如李林甫之流。这两句是对朝廷听信谗言、邪正不辨、严厉斥责，也是全诗的主旨所在。由于诗人有深刻的洞察力和高度的艺术概括力，因此这两句议论写得十分亲切自然，深刻有力，大大增加了诗的内涵。这里运用暗喻来抨击时弊，能发人深思，给人以很大的启迪。\n\n　　从结构上看，这首诗短短五十字，构思精巧，结构严密，抒情写意，回环起伏。开头以橘起，最后以橘结，前呼后应，且深化主题。尤其是最后出人意料的设问，震人心弦，增添了诗的艺术魅力.　张九龄诗歌语言生动、比喻贴切，毫无矫揉造作、雕琢晦涩之病。刘熙载在《艺概》中，称张九龄的诗歌“独能超出一格，为李、杜开先”。这一评价是非常恰当的。刘禹锡说九龄“自内职牧始安（今桂林），有瘴疠之叹；自退相守荆户，有拘囚之思。托讽禽鸟，寄词草树，郁然与骚人同风。”就是指这类《感遇诗》。', poem_tags = '唐诗三百首,咏物,写树,寓人,人格' WHERE poem_title = '感遇·江南有丹橘' AND poem_author = '张九龄';
UPDATE edu_poem SET poem_translation = '我怀疑春风吹不到这荒远的天涯，\n不然已是二月这山城怎么还看不见春花？\n残余的积雪压在枝头好象有碧桔在摇晃，\n春雷震破冰冻那竹笋也被惊醒想发嫩芽。\n夜晚听到归雁啼叫勾起我对故乡的思念，\n带着病进入新的一年面对春色有感而发。\n我曾在洛阳做官观赏过那里的奇花异草，\n山城野花开得虽迟也不必为此嗟叹惊讶。', poem_notes = '元珍：丁宝臣，字元珍，常州晋陵(今江苏常州市)人，时为峡州军事判官。\n天涯：极边远的地方。诗人贬官夷陵(今湖北宜昌市)，距京城已远，故云。\n山城：亦指夷陵。\n“残雪”二句：诗人在《夷陵县四喜堂记》中说，夷陵“又有橘柚茶笋四时之味”。残雪：初春雪还未完全融化。 冻雷：初春时节的雷，因仍有雪，故称。\n“夜闻”二句一作“鸟声渐变知芳节，人意无聊感物华”。归雁：春季雁向北飞，故 云。隋薛道衡《人日思归》：“人归落雁后，思发在花前。”感物华：感叹事物的美好。 物华 ：美好的景物。\n“曾是”句：宋仁宗天圣八年(1030)至景元年(1034)，欧阳修曾任 西京(洛阳)留守推官。洛阳以花著称，作者《洛阳牡丹记 风俗记》：“洛阳之俗，大抵好花。春时，城中无贵贱皆插花，虽负担者亦然。花开时，士庶竞为游遨。”\n冻雷：寒日之雷\n乡思：思乡、相思之情\n物华：自然景物', poem_appreciation = '宋仁宗景祐三年(1036)，欧阳修被贬为峡州夷陵县令。此诗乃次年春在夷陵 作。一本题为《戏答元珍花时久雨之什》。题目冠以“戏”字，是声明此篇不过是游戏之作，其实正是他受贬后政治上失意的掩饰之辞。全诗先是描写荒远山城的凄凉春景，接着抒发自己迁谪山乡的寂寞情怀及眷眷乡思，最后则自作宽慰之言，看似超脱，实是悲凉，表现出作者平静的表面下更深沉的痛苦。写景清新自然，抒情一波三折而真切诚挚，感人至深。开头二句起得超妙，欧阳修自己也颇为自得，他曾说：“若无下句，则上句不见佳处。并读之，便觉精神顿出。”(蔡眦《西清诗话》)起句不凡，下面又环环相扣，故方回《瀛奎律髓》说：“以后句句有味。”陈衍《宋诗精华录》说：“结韵用高一层意自慰。”\n\n　　首句写夷陵山城的恶劣环境。二月时分在其他地方早就应该花开满眼香气逼人了，但在此地却遍地荒凉。诗人表面上是写自然环境的恶劣，但实际上是写政治环境的不善，言下之意是朝廷的关怀怎么就不再远度天涯光顾一下这小城的官员呢？残雪压枝，但夷陵还有鲜美的柑橘可以品味，意即尽管如此，但在山城该怎么生活就怎么生活着，并且还要品出美味打破生活的寂寞；冻雷初响，惊醒熟睡的竹笋，它亦积蓄着力量，正要冒出新生的嫩芽，突破严厉的压制。“夜闻归雁”与“病入新年”两句反映出诗人心里的苦闷，流放山城兴起乡思之情在所难免，而这乡思之情又变成乡思之病，面对新年又至物华更新不免要感慨时光的流逝和人生的短暂。\n\n　　诗末两句诗人虽然是自我安慰，但却透露出极为矛盾的心情，表面上说他曾在洛阳做过留守推官，见过盛盖天下的洛阳名花名园，见不到此地晚开的野花也不须嗟叹了，但实际上却充满着一种无奈和凄凉，不须嗟实际上是大可嗟，故才有了这首借“未见花”的日常小事生发出人生乃至于政治上的感慨。\n\n　　此诗之妙，就妙在它既以小孕大，又怨而不怒。它借“春风”与“花”的关系来寄喻君臣、君民关系，是历代以来以“香草美人”来比喻君臣关系的进一步拓展，在他的内心中，他是深信明君不会抛弃智臣的，故在另一首《戏赠丁判官》七绝中说“须信春风无远近，维舟处处有花开”，而此诗却反其意而用之，表达了他的怀疑，也不失为一种清醒。但在封建朝政中，君臣更多的是一种人身依附、政治依附的关系，臣民要做到真正的人生自主与自择是非常痛苦的，所以他也只能以“戏赠”“戏答”的方式表达一下他的怨刺而已，他所秉承的也是中国古典诗歌的“怨而不怒”的风雅传统。据说欧阳修很得意这首诗，原因恐怕也就在这里。', poem_tags = '古诗三百首,写景,抒情' WHERE poem_title = '戏答元珍' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '每经过一次赤壁矶就引发一次怀古心绪。想当年，周瑜意气风发，一心吞并环宇。万骑临江，鼓声震天；在千艘列炬的拼搏中，那些潜居江中的鱼龙因为受到战火的影响都变得怒不可遏。水面上卷起了长长的火龙，在鼓角声中，孙刘联军围困住了曹操。现在又怎样呢?\n江上渡口，江边小路，全是地形险要的战略要地，是当年众雄生死争斗的地方。今天我在此凭吊古迹，自己得到的深切感受，胜过读历史书籍。东风吹，光景移，已经改朝换代无数次了，历史的往事随江潮而i折。问道旁的杨柳年年为谁而春，为谁摇动金黄的枝条。', poem_notes = '赤壁矶：即黄州赤壁。\n周郎：指赤壁大战吴蜀联军的统帅周瑜。\n区宇：即寰（huán）宇，宇宙。\n万骑：借指孙刘联军。\n貅（xiū）虎：猛兽，指军队，勇士。\n列炬（jù）：猛烈的火炬。列，同烈，火势猛。\n鱼龙怒：潜蛰在深水中的鱼龙类水族因受到战火威胁而怒。这是侧面写战争场面的惊心动魄。\n卷长波：水面上卷起了长长的火龙。\n曹瞒（mán）：指曹操，曹操小名叫阿瞒。\n今如许：如今又怎么样呢\n形胜地：地形险要的战略要地。\n兴亡处：当年众雄生死争斗的地方。\n傍：同旁。\n春：春色，此用如动词。\n金缕（lǚ）：指嫩黄色的柳条。化用白居易《杨柳枝词》：“一树春风千万枝，嫩于金色软于丝。”', poem_tags = '豪迈,怀古,感伤' WHERE poem_title = '满江红·赤壁怀古' AND poem_author = '戴复古';
UPDATE edu_poem SET poem_translation = '清澈的溪流欢快地奔流而出，穿越了青山的重重障碍。方圆十里的一片小平原。就坐落在青山与溪流的环抱之中。\n茫茫今古，曾经发生过多少次沧桑陵谷的变迁，许多昔日繁华兴旺的都市，后来却变成种植庄稼的田野。这个地方的山川形势不比寻常，莫非也曾经历过某种小小的盛衰兴废么！', poem_notes = '清平乐：词牌名，又名《清平乐令》、《醉东风》、《忆萝月》，为宋词常用词牌。晏殊，晏几道，黄庭坚，辛弃疾等著名词人均用过此调，其中晏几道尤多。\n上卢桥：在江西上饶境内。\n不管：不许。\n更著：再加上。\n陵谷：高山深谷。《诗经·小雅·十月之交》：“高岸为谷，深谷为陵。”\n市朝：人口聚集的都市。耕桑：田地。\n形胜：地理形势优越。', poem_tags = '宋词精选,写景,山水,思索,人生' WHERE poem_title = '清平乐·题上卢桥' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '抬头观看西北方向的浮云，驾驭万里长空需要长剑，人们说这个地方，深夜的时候，常常能看见斗牛星宿之间的光芒。我觉得山高，水潭的水冰冷，月亮明亮星光惨淡，待点燃犀牛角下到水中看看，刚靠近栏杆处却害怕，风雷震怒，鱼龙凶残。\n两边高山约束着东溪和西溪冲过来激起很高的浪花，过高楼，想飞去但还是收敛作罢，我有心像陈元龙那样但是身体精神都已老了，不妨高卧家园，凉爽的酒，凉爽的席子，一时登上双溪楼就想到了千古兴亡的事情，想到我自己的一生不过百年的悲欢离合，嬉笑怒骂。是什么人又一次卸下了张开的白帆，在斜阳夕照中抛锚系缆？', poem_notes = '水龙吟：词牌名。\n南剑：即南剑州，宋代州名。双溪楼：在南剑州府城东。\n西北浮云：西北的天空被浮云遮蔽，这里隐喻中原河山沦陷于金人之手。\n斗牛：星名，二十八宿的斗宿与牛宿。\n待：打算，想要。\n鱼龙：指水中怪物，暗喻朝中阻遏抗战的小人。惨：狠毒。\n束：夹峙。\n欲飞还敛：形容水流奔涌直前，因受高山的阻挡而回旋激荡，渐趋平缓。\n冰壶凉簟：喝冷水，睡凉席，形容隐居自适的生活。\n百年悲笑：指人生百年中的遭遇。\n卸：解落，卸下。\n缆：系船用的绳子。', poem_tags = '宋词三百首,豪放,山水,壮志' WHERE poem_title = '水龙吟·过南剑双溪楼' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '后蜀国的君王城楼上竟然竖起了白旗，你们哪知道我被封锁在了这冷清清的行宫里？\n守卫君王的十四万人一起脱下了金闪闪的铠甲，其实这些人中没有一个是守卫国家的男子！', poem_notes = '妾：花蕊夫人自称。\n解甲：解除武装，指投降。\n更无：一作“宁无”。', poem_tags = '爱国' WHERE poem_title = '述国亡诗' AND poem_author = '花蕊夫人';
UPDATE edu_poem SET poem_translation = '高阁上的游客们已经竞相离去；\n小园的春花随风凋零纷纷乱飞。\n花影参差迷离接连着弯弯小径；\n远望落花回舞映着斜阳的余晖。\n我的肝肠欲断不忍把落红扫去；\n望眼欲穿盼来春天却匆匆回归。\n爱花惜花自然要怨春去得太早；\n春尽花谢所得的只是落泪沾衣。', poem_notes = '参差：指花影的迷离，承上句乱飞意。\n芳心：指花，也指自己看花的心意。\n沾衣：指流泪。', poem_appreciation = '这首诗写于会昌六年（公元846年），作者正闲居永业。当时，李商隐陷入牛李党争之中，境况不佳，心情郁闷，故本诗流露出幽恨怨愤之情。\n\n　　首联直接写落花。上句叙事，下句写景。落花虽早有，客在却浑然不觉，待到人去楼空，客散园寂，诗人孤寂惆怅之情顿上心头，诗人这才注意到满园缤纷的落花，而且心生同病相怜的情思，用语巧妙。\n\n　　颔联从不同角度写落花的具体情状。上句从空间着眼，写落花飘拂纷飞，连接曲陌；下句从时间着笔，写落花连绵不断，无尽无休。对“斜晖”的点染，透露出诗人内心的不平静。整个画面笼罩在沉重黯淡的色调中，显示出诗人的伤感和悲哀。\n\n　　颈联直接抒情。春去花落，“肠断未忍扫”，表达的不只是一般的怜花惜花之情，而是断肠人又逢落花的伤感之情。“眼穿仍欲稀”，写出了诗人面对落花的痴情和执着。\n\n　　尾联语意双关。花朵用生命装点了春天，落得个凋残、沾衣的结局；而诗人素怀壮志，却屡遭挫折，也落得个悲苦失望、泪落沾衣、低回凄凉、感慨无限的人生际遇。\n\n　　全诗咏物伤己，以物喻己，感伤无尽。\n\n新解 　　高阁上，曲终人散；小园里，落花随风漫天飞舞，飘落到了田间曲折的小径上，斜阳在花雨中徐徐西下。我痛惜这如雨的落花，不忍将落红扫去。我望眼欲穿，盼来的春天却又匆匆归去。赏花的心意也随着春天的归去而消失，春去花谢，只留下我泪湿衣裳。 　\n\n意境浅尝 　　花朵，用生命装点着春天；春天，却用凋残凄凉了花朵。\n\n　　所谓“落花有意随流水，而流水无心恋落花。”痴心在左，无情在右。世间最无奈，也莫过于此。\n\n　　花朵痴情，恨不能一次绽放几世的美丽；春日寡义，视花朵只一抹不起眼的风景。这飘零、沾衣的结局，似乎早已注定。一如那梦想碎灭后的感花人，只落得泪垂沾衣、低回凄凉的惨际遇。\n\n　　此刻，竟有了一丝心疼，花开花谢花舞漫天，不忍看到它的坠地，然而，耳畔却残忍的传来了你落地的声音，像抽丝一般绞痛，像山崩一样巨响。我想到了祭奠，洁白的纸花，洁白的衣纱，洁白的面容，洁白的悲伤。\n\n　　花落处，小径独自幽香，有人说，这是美人出生的地方，只可惜这倾国倾城的绝代风华在一季的绚烂后，却风尘天涯。抬头望，何处是归家？那一朵育下了匈奴的文姬花，尚且在历史的书页里夹杂了一片芳华；那一只月夜魂过沙漠的昭君花，是否还能启开家乡门前的破旧篱笆？\n\n　　或许落红不是无情物，化作春泥更护花？但却偏偏选择了秋日葬身陪水逝前随风撒，这是极尽绚烂后的落寞，留的千古一声遗憾：红颜，多薄命！日悬山巅，命薄如花，昔日秦淮河上还弹奏着声声琵琶，今日却不闻扬子畔掩抑鼓瑟。既然生于红尘，亦当归于红尘，或许，多年以后，红尘外我们还能依稀记得她当初沉鱼落雁的红颜！\n\n　　步非烟下，人道是青楼师师，纵然哭倒了长城，也不能下世轮回再次香君！落花渐入迷人眼，一朝花落终不见。落泪的时候，花还在飘洒，春归的时候，你却已不在。人生，几多花开，几多花败，衣衫湿透，红尘看破，一切都是轮回之道！', poem_tags = '唐诗三百首,咏物,写花,抒怀' WHERE poem_title = '落花' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '屋梁上来了一双燕子，翩翩飞舞，一雄一雌。\n衔泥在椽条间垒窝，一窝生下乳燕四只。\n四只乳燕日夜成长，求食的叫声喳喳不住。\n青虫不容易抓到，黄口小燕似乎从来没吃饱饭。\n双燕用爪抓，用嘴衔，气力用尽，不知疲倦。\n不一会儿往返十来转，还怕饿着窝里的小燕。\n辛辛苦苦忙了三十天，拖瘦了母燕喂肥了小燕。\n喃喃不断教小燕发音，一一为它们梳理打扮。\n小燕一朝羽毛长得丰满，引上了庭院里的树枝，再不回头，随着风儿四下飞散。\n雌雄双燕，空中叫喊，声嘶力竭，也唤不回还。\n只好回到空窝里面，悲鸣通宵不断！\n老燕啊，切莫悲叹，你们应当回想从前：\n想想你们是乳燕的时代，也同样远走高飞，\n抛弃父母那时父母多么挂念，今天你们应有体验！', poem_notes = '翩翩（piān）：鸟飞轻疾的样子。\n椽（chuán）：装于屋顶以支持屋顶盖材料的木杆。\n索食：求食。孜（zī）：勤勉、努力不懈的样子。\n黄口：小儿。《淮南子·汜论训》：“古之伐国，不杀黄口。”高诱注：“黄口，幼也。”\n觜 （zī ）：觜爪指鸟类的爪和嘴。敝（bì）：这里指疲惫，困乏，衰败。\n心力：指精神与体力。\n须臾（yú）：顷刻；瞬间。\n雏（chú）：幼小的鸟。\n刷毛：整理羽毛。\n庭树枝：庭院里的树枝。\n“举翅”句：向上伸起翅膀而不回头看。\n啁啾（zhōu jiū）：形容鸟叫声、奏乐声等。', poem_tags = '感恩,父母' WHERE poem_title = '燕诗示刘叟' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '在猛烈狂疾的大风中才能看得出是不是强健挺拔的草，在激烈动荡的年代里才能识别出是不是忠贞不二的臣。\n一勇之夫怎么懂得为公为国为民为社稷的正义的道理，而智勇兼具的人内心里必然怀有忠君为民的仁爱之情。', poem_notes = '萧瑀：字时文，隋朝将领，被李世民俘后归唐，封宋国公。\n疾风：大而急的风。劲草：强劲有力的草。\n板荡：动乱之世。\n勇夫：有胆量的人。\n智者：有见识的人。', poem_appreciation = '这首诗极富于哲理。诗的前两句是历来传颂的名句。“疾风知劲草”一语，出自宋·范晔《后汉书·王霸传》。此语原为汉光武帝刘秀赞誉王霸之言。光武谓霸曰：“颍川从我者皆逝，而子独留努力，疾风知劲草。”后世遂用以比喻只有经过危难或战乱的严峻考验，才能识别出谁的意志坚强，谁是忠诚可靠者。作者李世民在此诗中用此赞美萧瑀。次句的“板荡”乃《诗经·大雅》中两篇作品的名称。《板》、《荡》二诗讥刺周厉王无道，败坏政局。后以“板荡”代指政局变乱。在风和日丽的日子里，“劲草”混同于一般的草；在和平安定的环境中，“诚臣”也容易混同于一般的人，其特殊性没有显现出来，因而不易鉴别。只有经过猛烈大风和动乱时局的考验，才能看出什么样的草是强劲的，什么样的人是忠诚的。\n\n　　后二句则另换角度，继续盛赞萧瑀。徒有一时之勇的“勇夫”并不懂得真正的“义”，而真正的“智者”必然心怀仁德。这里告诉读者，只有忠诚还是不够的，要智勇双全，才算是有用之才。有勇无谋，莫言义；有智无勇，难施仁。\n\n　　这首诗诗意浅显，说理形象，寓意深刻，言简意赅地揭示了“智”、“勇”、“仁”、“义”之间的辩证关系。这不仅对于知人善任具有现实意义，而且，对于读者的自我完善，如何使自己成为智勇双全的有用之才方面，也具有启迪作用。“疾风知劲草，板荡识诚臣”二句，如今引用它，比喻只有经过尖锐复杂斗争的考验，才能考查出一个人的真正品质和节操，才能显示出谁是忠贞的强者。', poem_tags = '哲理,启示,早教古诗100首' WHERE poem_title = '赐萧瑀' AND poem_author = '李世民';
UPDATE edu_poem SET poem_translation = '鲜艳明亮的荷花代表着祥瑞，亭亭玉立站在水中。\n一根花茎引出翠绿之色，两个花朵分用一片鲜红。\n花颜好像拿走了歌伎的面色，香气迷乱好像舞动衣服引起的微风。\n这样的莲花必然会互相思念，更何况它们的心是在一起的。', poem_notes = '灼灼：明亮貌。\n况复：何况，况且。', poem_tags = '咏物,荷花,寓人,爱情' WHERE poem_title = '咏同心芙蓉' AND poem_author = '杜公瞻';
UPDATE edu_poem SET poem_translation = '当年十五二十岁青春之时，徒步就能夺得胡人战马骑。\n年轻力壮射杀山中白额虎，数英雄岂止邺下的黄须儿？\n身经百战驰骋疆场三千里，曾以一剑抵当了百万雄师。\n汉军声势迅猛如惊雷霹雳，虏骑互相践踏是怕遇蒺藜。\n卫青不败是由于天神辅助，李广无功却缘于命运不济。\n自被摈弃不用便开始衰朽，世事随时光流逝人成白首。\n当年象后羿飞箭射雀无目，如今不操弓疡瘤生于左肘。\n象故侯流落为民路旁卖瓜，学陶令门前种上绿杨垂柳。\n古树苍茫一直延伸到深巷，寥落寒山空对冷寂的窗牖。\n誓学耿恭在疏勒祈井得泉，不做颍川灌夫为牢骚酗酒。\n贺兰山下战士们列阵如云，告急的军书日夜频频传闻。\n持节使臣去三河招募兵丁，招书令大将军分五路出兵。\n老将揩试铁甲光洁如雪色，且持宝剑闪动剑上七星纹。\n愿得燕地的好弓射杀敌将，绝不让敌人甲兵惊动国君。\n莫嫌当年云中太守又复职，还堪得一战为国建立功勋。', poem_notes = '“步行”句：汉名将李广，为匈奴骑兵所擒，广时已受伤，便即装死。后于途中见一胡儿骑着良马，便一跃而上，将胡儿推在地下，疾驰而归。见《史记·李将军列传》。夺得：一作“夺取”。\n“射杀”句：与上文连观，应是指李广为右北平太守时，多次射杀山中猛虎事。白额虎（传说为虎中最凶猛一种），则似是用晋名将周处除三害事。南山白额虎是三害之一。见《晋书·周处传》。中山：一作“山中”，一作“阴山”。\n肯数：岂可只推。邺下黄须儿：指曹彰，曹操第二子，须黄色，性刚猛，曾亲征乌丸，颇为曹操爱重，曾持彰须曰：“黄须儿竟大奇也。”这句意谓，岂可只算黄须儿才是英雄。邺下，曹操封魏王时，都邺（今河北临漳县西）。\n蒺藜：本是有三角刺的植物，这里指铁蒺藜，战地所用障碍物。\n卫青：汉代名将，汉武帝皇后卫子夫之弟，以征伐匈奴官至大将军。卫青姊子霍去病，也曾远入匈奴境，却未曾受困折，因而被看作“有天幸”。“天幸”本霍去病事，然古代常卫、霍并称，这里当因卫青而联想霍去病事。\n“李广”句：李广曾屡立战功，汉武帝却以他年老数奇，暗示卫青不要让李广抵挡匈奴，因而被看成无功，没有封侯。缘，因为。数，命运。奇，单数。偶之对称，奇即不偶，不偶即不遇。\n飞箭无全目：鲍照《拟古诗》：“惊雀无全目。”李善注引《帝王世纪》：吴贺使羿射雀，贺要羿射雀左目，却误中右目。这里只是强调羿能使雀双目不全，于此见其射艺之精。飞箭：一作“飞雀”。\n垂杨生左肘：《庄子·至乐》：“支离叔与滑介叔观于冥柏之丘，昆仑之虚，黄帝之所休，俄而柳生其左肘，其意蹶蹶然恶之。”沈德潜以为“柳，疡也，非杨柳之谓”，并以王诗的垂杨“亦误用”。他意思是说，庄子的柳生其左肘的柳本来即疡之意，王维却误解为杨柳之柳，因而有垂云云。高步瀛说：“或谓柳为瘤之借字，盖以人肘无生柳者。然支离、滑介本无其人，生柳寓言亦无不可。”高说似较胜。\n故侯瓜：召平，本秦东陵侯，秦亡为平民，贫，种瓜长安城东，瓜味甘美。\n先生柳：晋陶渊明弃官归隐后，因门前有五株杨柳，遂自号“五柳先生”，并写有《五柳先生传》。\n苍茫：一作“茫茫”。连：一作“迷”。\n“誓令”句：后汉耿恭与匈奴作战，据疏勒城，匈奴于城下绝其涧水，恭于城中穿井，至十五丈犹不得水，他仰叹道：“闻昔贰师将军（李广利）拔佩刀刺山，飞泉涌出，今汉德神明，岂有穷哉。”旋向井祈祷，过了一会，果然得水。事见《后汉书·耿恭传》。疏勒：指汉疏勒城，非疏勒国。\n颍川空使酒：灌夫，汉颍阴人，为人刚直，失势后颇牢骚不平，后被诛。使酒：恃酒逞意气。\n聊持：且持。星文：指剑上所嵌的七星文。\n天将：一作“大将”。\n“耻令”句：意谓以敌人甲兵惊动国君为可耻。《说苑·立节》：越国甲兵入齐，雍门子狄请齐君让他自杀，因为这是越甲在鸣国君，自己应当以身殉之，遂自刎死。呜：这里是惊动的意思。吴军：一作“吾君”。\n取：一作“树”。', poem_appreciation = '这首诗叙述了一位老将的经历。他一生东征西战，功勋卓著，结果却落得个“无功”被弃、不得不以躬耕叫卖为业的可悲下场。边烽再起，他又不计恩怨，请缨报国。作品揭露了统治者的赏罚蒙昧，　　冷酷无情，歌颂了老将的高尚节操和爱国热忱。\n\n　　全诗分三段，开头十句为第一段，是写老将青壮年时代的智勇、功绩和不平遭遇。先说他少时就有李广之智勇，“步行”夺得过敌人的战马，引弓射杀过山中最凶猛的“白额虎”。接着改用曹操的次子曹彰故事，彰绰号黄须儿，奋勇破敌，却功归诸将。诗人借用这两个典故，描绘老将的智勇才德。接下去，以“一身转战三千里”，见其征战劳苦；“一剑曾当百万师”，见其功勋卓著；“汉兵奋迅如霹雳”，见其用兵神速，如迅雷之势；“虏骑崩腾畏蒺藜”见其巧布铁蒺藜阵，克敌制胜。但这样难得的良将，却无寸功之赏，所以诗人又借用历史故事抒发自己的感慨。汉武帝的贵戚卫青所以屡战不败，立功受赏，官至大将军，实由“天幸”；而与他同时的著名战将李广，不但未得封侯授爵，反而得罪、受罚，最后落得个刎颈自尽的下场，是因“数奇”。这里的“天幸”，既指幸运之“幸”，又指皇帝宠幸；“数奇”，既指运气不好，又指皇恩疏远，都是语意双关的。诗人借李广与卫青的典故，暗示统治者用人唯亲，赏罚失据，写出了老将的不平遭遇。\n\n　　中间十句为第二段，写老将被遗弃后的清苦生活。自从被弃置之后老将便“衰朽”了，岁月蹉跎，心情不好，连头发都白了。他昔日虽有后羿射雀而使其双目不全的本领，但久不习武，双臂就如同生了疡瘤，很不利落了。古人常以“柳”谐“瘤”，并且“杨”“柳”通假。在这里诗人以“杨”谐“疡”（疮）是照顾到诗的平仄声调。老将被弃，疡生左肘，却还得自寻生计，“路旁时卖故侯瓜”。“故侯”，指秦东陵侯召平，秦破，为布衣，种瓜于长安东城。这里说他不仅种瓜，而且“路旁时卖”，可知生活没有着落；“门前学种先生柳”，也是指他以耕作为业的意思。陶渊明门前有五柳，因自号“五柳先生”。至于住处则是“苍茫”一片“古木”丛中的“穷巷”，窗子面对着的则是“寥落寒山”，这更见世态炎凉，门前冷落，从无宾客往还。但是老将并未因此消沉颓废，他仍然想“誓令疏勒出飞泉”，象后汉名将耿恭那样，在匈奴疏勒城水源断绝后，与战士们同甘共苦，终于又得泉水却敌立功；而决不像前汉颍川人灌夫那样，解除军职之后，使酒骂坐，发泄怨气。\n\n　　最末十句为第三段，是写边烽未熄，老将时时怀着请缨杀敌的爱国衷肠。先说西北贺兰山一带阴霾沉沉，阵战如云，告急的文书不断传进京师；次写受帝命而征兵的军事长官从三河（河南、河内、河东）一带征召大批青年入伍，诸路将军受诏命分兵出击。最后写老将，他再也呆不住了，先是“拭拂铁衣如雪色”，把昔日的铠甲摩擦得雪亮闪光；继之是“聊持宝剑动星文”，又练起了武功。他的宿愿本就是能得到燕产强劲的名弓“射天将”擒贼擒王，消灭入寇的渠魁；并且“耻令越甲鸣吾君”，绝不让外患造成对朝廷的威胁。结尾为老将再次表明态度：“莫嫌旧日云中守，犹堪一战立功勋”，借用魏尚的故事，表明只要朝廷肯任用老将，他一定能杀敌立功，报效祖国。魏尚曾任云中太守，深得军心，匈奴不敢犯边，后被削职为民，经冯唐为其抱不平，才官复旧职。\n\n　　这首诗十句一段，章法整饬，大量使事用典，从不同的角度和方面，刻画出“老将”的艺术形象，增加了作品的容涵量，完满地表达了作品的主题。沈德潜《唐诗别裁》谓“此种诗纯以对仗胜”。诗中对偶工巧自然，如同灵气周运全身，使诗人所表达的内容，犹如璞玉磨琢成器，达到了理正而文奇，意新而词高的艺术境界。', poem_tags = '唐诗三百首,乐府,赞颂,写人,猖狂' WHERE poem_title = '老将行' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '我多少次坐在花下吹箫，银河红墙对我来说是那样的遥远。\n眼前的星辰已不是昨夜的星辰，我为了谁在风露中伫立了整整一夜呢？\n缠绵的情思已尽如抽丝的蚕茧，宛转的心已经像被剥的芭蕉。\n回想起她十五岁时在那月圆之夜的情景，可叹我手中的这杯酒竟已无法消除心中的忧愁。', poem_notes = '银汉红墙：李商隐《代应》：“本来银汉是红墙，隔得卢家白玉堂。”\n星辰：李商隐《无题》“昨夜星辰昨夜风，画楼西畔桂堂东。”风露：高启《芦雁图》“沙阔水寒鱼不见，满身风露立多时。”\n思，丝。心，芯。皆双关语。李商隐《无题》“春蚕到死丝方尽，蜡炬成灰泪始干。”', poem_tags = '怀念,母亲' WHERE poem_title = '思母' AND poem_author = '与恭';
UPDATE edu_poem SET poem_tags = '宋词三百首,相思,宴会,歌女' WHERE poem_title = '鹧鸪天·小令尊前见玉箫' AND poem_author = '晏几道';
UPDATE edu_poem SET poem_tags = '冬天,离别,写雪,组诗' WHERE poem_title = '对雪二首' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '蜀僧怀抱着绿绮琴，来自遥远的峨眉山。\n为我随意挥手一弹，如同听到万壑松声。\n余音袅袅，汇入霜天钟声，我心清静，如经流水洗过。\n不知不觉，暮色笼罩青山，秋云黯淡，布满黄昏天空。', poem_notes = '蜀僧濬：即蜀地的僧人名濬的。有人认为“蜀僧濬”即李白集中《赠宣州灵源寺仲濬公》中的仲濬公。\n绿绮（qǐ）：琴名。诗中以绿绮形容蜀僧濬的琴很名贵。\n峨眉：山名，在四川省峨眉县。\n一：助词，用以加强语气。挥手：这里指弹琴。\n万壑（hè）松：指万壑松声。这是以万壑松声比喻琴声。琴曲有《风入松》。壑：山谷。这句是说，听了蜀僧濬的琴声好像听到万壑松涛雄风。\n客：诗人自称。流水：语意双关，既是对僧濬琴声的实指，又暗用了伯牙善弹的典故。\n余响：指琴的余音。霜钟：指钟声。\n“碧山”句：意思是说，因为听得入神，不知不觉天就黑下来了。\n秋云：秋天的云彩。暗几重：意即更加昏暗了，把上句“暮”字意伸足。', poem_appreciation = '这首五律写的是听琴，听蜀地一位法名叫濬的和尚弹琴。开头两句：“蜀僧抱绿绮，西下峨眉峰。”说明这位琴师是从四川峨眉山下来的。李白是在四川长大的，四川绮丽的山水培育了他的壮阔胸怀，激发了他的艺术想象。峨眉山月不止一次地出现在他的诗里。他对故乡一直很怀恋，对于来自故乡的琴师当然也格外感到亲切。所以诗一开头就说明弹琴的人是自己的同乡。“绿绮”本是琴名，汉代司马相如有一张琴，名叫绿绮，这里用来泛指名贵的琴。司马相如是蜀人，这里用“绿绮”更切合蜀地僧人。“蜀僧抱绿绮，西下峨眉峰”，简短的十个字，把这位音乐家写得很有气派，表达了诗人对他的倾慕与敬佩。\n\n　　二三句正面描写蜀僧弹琴。“挥手”是弹琴的动作。嵇康《琴赋》：“伯牙挥手，钟期听声。”“挥手”二字就是出自这里的。“为我一挥手，如听万壑松”，这两句用大自然宏伟的音响比喻琴声，使人感到这琴声一定是极其铿锵有力的。\n\n　　“客心洗流水”，这一句就字面讲，是说听了蜀僧的琴声，自己的心好像被流水洗过一般地畅快、愉悦。但它还有更深的含义，其中包涵着一个古老的典故，即《列子·汤问》中“高山流水”的典故，借它，表现蜀僧和自己通过音乐的媒介所建立的知己之感。“客心洗流水”五个字，很含蓄，又很自然，虽然用典，却毫不艰涩，显示了李白卓越的语言技巧。\n\n　　下面一句“余响入霜钟”也是用了典的。“霜钟”出于《山海经·中山经》：“丰山……有九钟焉，是知霜鸣。”郭璞注：“霜降则钟鸣，故言知也。”“霜钟”二字点明时令，与下面“秋云暗几重”照应。“余响入霜钟”，意思是说，音乐终止以后，余音久久不绝，和薄暮时分寺庙的钟声融合在一起。这句诗写琴音与钟声交响，也兼寓有知音的意思。《列子·汤问》里有“余音绕梁，三日不绝”的话。宋代苏东坡在《前赤壁赋》里用“余音袅袅，不绝如缕”，形容洞箫的余音。这都是乐曲终止以后，入迷的听者沉浸在艺术享受之中所产生的想象。“余响入霜钟”也是如此。清脆、流畅的琴声渐远渐弱，和薄暮的钟声共鸣着，这才发觉天色已经晚了：“不觉碧山暮，秋云暗几重。”诗人听完蜀僧弹琴，举目四望，不知从什么时候开始，青山已罩上一层暮色，灰暗的秋云重重叠叠，布满天空。感觉时间过得真快。\n\n　　唐诗里有不少描写音乐的佳作。白居易的《琵琶行》用“大珠小珠落玉盘”来形容忽高忽低、忽清忽浊的琵琶声，把琵琶所特有的繁密多变的音响效果表现了出来。唐代另一位诗人李颀有一首《听安万善吹觱篥歌》，用不同季节的不同景物，形容音乐曲调的变化，把听觉的感受诉诸视觉的形象，取得很好的艺术效果。李白这首诗描写音乐的独到之处是，除了“万壑松”之外，没有别的比喻形容琴声，而是着重表现听琴时的感受，表现弹者、听者之间感情的交流。其实，“如听万壑松”这一句也不是纯客观的描写，诗人从琴声联想到万壑松声，联想到深山大谷，是结合自己的主观感受来写的。\n\n　　律诗讲究平仄、对仗，格律比较严。而李白的这首五律却写得极其清新、明快，似乎一点也不费力。其实，无论立意、构思、起结、承转，或是对仗、用典，都经过一番巧妙的安排，只是不着痕迹罢了。这种“清水出芙蓉，天然去雕饰”的自然的艺术美，比一切雕饰更能打动人的心灵。', poem_tags = '唐诗三百首,音乐' WHERE poem_title = '听蜀僧濬弹琴 / 听蜀僧浚弹琴' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '碧海青天，年年如此，而云间的月亮，却为何时圆时缺。今夜里，金风送爽，土花映碧，画栏桂树悬挂着一缕秋香；月亮光就像白雪一般晶莹透澈。谁知道，这好天良夜，却让人忧愁，让人悲咽。孤身只影，怎么可面对旧时明月。\n那时节，也是这么个中秋夜，你和我，花径里捉迷藏，曾经将金井梧桐的霜叶惊落。手上轻巧的小纨扇，至今又经历几番凉热。一时间，不由得百感丛生；但这又与一般的相思离别无关。面对这旧时明月，只好让无情的紫玉萧，于寒风中吹烈。', poem_notes = '碧海：传说中的海名。\n冰轮：月亮代名之一，历来用以形容皎洁的满月。\n吹到二句：谓秋风把一片秋花吹开了，那明亮的月光犹如白雪。清辉，指明亮的月光。\n花径二句：捉迷藏，又称逮猫儿，儿童玩的一种游戏。井梧叶：谓井边的梧桐树叶。\n轻纨小扇：即纨扇。\n一任二句：紫玉，指笛箫，因截紫竹所制，故名。', poem_appreciation = '“碧海年年，试问取、冰轮为谁圆缺？”在苍茫的夜色中，作者抬头仰望天空，中秋月圆，其景何其美好；然而他却触景生情，发此疑问。通过此句，我们似乎看出了他心中的悲凉：日月轮回不断，春花秋月年年，这些都只会令他徒增烦恼；是因为佳人不在，如今的他形影相吊么？“吹到一片秋香，清辉了如雪”，不知哪里吹来的秋风，带来一阵芬芳；月亮的清辉笼罩了周围寂寞的空气，如同冰雪一样寒冷。此句是写景，却是寄情于景，情景交融，寒冷的是清辉还是他那颗受伤的心？回想往昔，那“一生一代一双人”，曾经花前月下，欣赏这良宵美景，“记当时，垂柳丝，花枝，满庭蝴蝶儿。”只影而今，物是人非，在这如同旧时的明月下重拾往事，只会令他“填膺百感”。\n\n　　词的上片写现实，现实是充满了悲凉，其情之苦，足以震憾一切感性的心灵。用“冰轮”喻明月，用“雪”喻明月的清辉，更增加了意境的清冷。“只影而今，那堪重对，旧时明月。”此句道出了作者“尽成悲咽”的缘由：原来是故人不在，作者在思念他的亡妻；然而“明月不谙离恨苦”，偏要打动他那颗敏感脆弱的心，叫他情何以堪。\n\n　　下阙写词人仰望明月忆及往事。“花径里、戏捉迷藏，曾惹下萧萧井梧叶。”明月下，芳丛里，词人与心上人嬉戏，游玩，虽然并未着墨描摹具体情状，而梧桐叶的缓缓飘落中，纵情的欢笑声，亲昵的嘶闹声，在一片月色下朗朗可闻，其人之天真烂漫，其情之亲密无间，已不言自明，词人对故人往事的深深思恋，直抵人心深处。只是光阴荏苒，轻纨小扇轻摇又摇走了几番寒暑，去者不可追，如今只剩下词人中宵独立，“填膺百感”，而明月还是当时的明月，清辉未减分毫。中秋月光照耀，本该是众家欢聚之时，容若心中却荒凉如大漠。吹裂紫玉萧也难散愁心。', poem_tags = '中秋节,孤独,感伤' WHERE poem_title = '琵琶仙·中秋' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_tags = '忆旧,抒愤' WHERE poem_title = '诉衷情·青衫初入九重城' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '在宜州看到梅花开放，知道春天即将来临。夜尽时，迟迟闻不到梅花的香味，以为梅花还没有开放；早晨起来，才发现在面南的枝条上已开满了梅花，真是没有想到。女子在镜台前化妆，引起了梅花的羡妒，就飘落在她的眉心上。要在平常见到这种景象，便希望畅怀酣饮；现在就不同了，自从被贬离开汴京，十年来，那种青年人的情怀、兴致已经不存在了。', poem_notes = '宜州：今广西宜山县一带。\n梅破知春近：梅花绽破花蕾开放，预示着春天的来临。\n开遍向阳枝：南枝由于向着太阳，故先开放。\n“玉台”二句：玉台，传说中天神的居处，也指朝廷的宫室。\n粉：把梅花的开放比作天宫“弄粉”。\n⑥飘到眉心住：宋武帝女寿阳公主人日卧于含章殿下。梅花落于公主额上，成五出花，拂之不去。词中意谓由于群花的妒忌，梅花无地可立，只好移到美人的眉心停住，古代妇女化妆时常在眉心点梅花砂痣。\n“平生个里愿杯深”两句：年轻时遇到良辰美景，总是尽兴喝酒，可是经十年贬谪之后，再也没有这种兴致了。个里，个中、此中。去国，离开朝廷。', poem_appreciation = '此词为山谷因写《承天院塔记》被朝廷指为“幸灾谤国”而贬谪地处西南的边地宜州后所作。全词以咏梅为中心，把天涯与江南、垂老与少年、去国十年与平生作了一个对比性总结，既表现出天涯见梅的喜悦，朝花夕拾的欣慰，又抒写不胜今昔之慨，表现出作者心中郁结的不平与愤懑。\n\n　　“天涯也有江南信，梅破知春近”。宜州地近海南，去京国数千里，说是“天涯”不算夸张。到贬所居然能看到江南常见的梅花，作者很诧异。“梅破知春”，这不仅是以江南梅花多冬末春初开放，意谓春天来临；而且是侧重于地域的联想，意味着“天涯”也无法隔断“江南”与我的联系（作者为江西修水人，地即属江南）。“也有”，是始料未及、喜出望外的口吻，显见环境比预料的好。\n\n　　紧接二句则由“梅破”，写到梅开。梅花开得那样早，那样突然，夜深时嗅到一阵暗香，没能想到什么缘故，及至“晓来”才发现向阳的枝头已开繁了。\n\n　　虽则“开遍”，却仅限于“向南枝”，不失为早梅，令人感到新鲜，喜悦。“夜阑（其时声息俱绝，暗香易闻）风细（恰好传递清香）”时候才“得香”，故云“迟”。此处用笔细致。“也有”表现出第一次惊喜，“不道”则表现出又一次意外，作者惊喜不迭之情，溢于言表。\n\n　　至此，作者已满怀江南之春心。一个关于梅花的浪漫故事，遂见于作者笔端。《太平御览。时序部》引《杂五行书》：“宋武帝女寿阳公主人日卧于含章殿檐下。梅花落公主额上，成五出花，拂之不去。”一句“玉台弄粉花应妒，飘到眉心住”不但将旧典翻出新意，而且还表现出一个被贬的老人观梅以致忘怀得失的心情，暗伏下文“少年心”三字。\n\n　　想到往日赏梅，对着如此美景（“个里”，此中，这样的情景中），总想把酒喝个够；但现不同了，经过十年的贬谪，宦海沉沦之后，不复有少年的兴致了。结尾词情上是一大兜转，“老”加上“尽”的程度副词，更使拗折而出的郁愤之情得到充分表现。用“愿杯深”来代言兴致好，亦形象有味。\n\n　　这首词写得极为深挚，是山谷孤清抑郁的人格风貌的写照。全词由景入手，婉曲细腻；以情收结，直抒胸臆。整首词风格疏宕，颇具韵味。\n\n　　作者先写在边地宜州看到梅含苞欲放，接着写夜晚微风中传来梅花幽香，最后写早晨梅花开满枝头。由“梅破”到“得香”再到“开遍”，作者很有层次地描写了梅花。', poem_tags = '咏物,梅花,抒怀' WHERE poem_title = '虞美人·宜州见梅作' AND poem_author = '黄庭坚';
UPDATE edu_poem SET poem_tags = '赞颂,女子' WHERE poem_title = '木兰歌' AND poem_author = '韦元甫';
UPDATE edu_poem SET poem_translation = '一头死鹿在荒野，白茅缕缕将它包。有位少女春心荡，小伙追着来调笑。\n林中丛生小树木，荒野有只小死鹿。白茅捆扎献给谁？有位少女颜如玉。\n“慢慢来啊少慌张！不要动我围裙响！别惹狗儿叫汪汪 ！”\n\n意译\n野地死了香獐子，白茅包裹才得体。少女怀春心不已，美男善诱情意起。\n林中朴樕无人理，野地死鹿还施礼。白茅包裹埋地里，少女如玉属意你。\n缓脱裙衣是何企，别碰腰带对不起。莫使狗儿叫不已，少女今生跟定你。', poem_notes = '麕（jūn）：同“麇（jūn）”，也可用“野有死麇”，獐子。比鹿小，无角。\n白茅：草名。属禾本科。在阴历三四月间开白花。包：古音读bǒu。\n怀春：思春，男女情欲萌动。\n吉士：男子的美称。\n朴樕（sù）：小木，灌木。\n纯束：捆扎，包裹。“纯”为“稇（kǔn）”的假借。\n舒：舒缓。脱脱（tuì）：动作文雅舒缓。\n感（hàn）：通假字，通：撼 ，动摇。帨（shuì）：佩巾，围腰，围裙。\n尨（máng）：多毛的狗。', poem_tags = '诗经,爱情' WHERE poem_title = '国风·召南·野有死麕' AND poem_author = '佚名';
UPDATE edu_poem SET poem_tags = '抒情,相思' WHERE poem_title = '虞美人·小梅枝上东君信' AND poem_author = '晏几道';
UPDATE edu_poem SET poem_translation = '吹开了京城花园中的早梅，继而让樱杏桃李也竞相绽放，令人感到生机盎然。\n春的来临同样也给乡村送去了欢笑，春风拂过，田野里开放的荠花榆英欢呼雀跃，欣喜地称道：“春风为我而来！”', poem_tags = '写花,春天' WHERE poem_title = '春风' AND poem_author = '白居易';
UPDATE edu_poem SET poem_tags = '清明,心情,惆怅' WHERE poem_title = '清明' AND poem_author = '孙昌胤';
UPDATE edu_poem SET poem_translation = '莪蒿葱茏真繁茂，丛丛生长在山坳。已经见到那君子，快快乐乐好仪表。\n莪蒿葱茏真繁茂，簇簇生长在小洲。已经见到那君子，我的心里乐悠悠。\n莪蒿葱茏真繁茂，蓬蓬生长在丘陵。已经见到那君子，赐我贝币千百朋。\n荡漾水面杨木舟，随着波涛任漂流。已经见到那君子，我的心里乐无忧。', poem_notes = '菁（jīng）菁：草木茂盛。莪：莪蒿，又名萝蒿，一种可吃的野草。\n阿：山坳。中阿，阿中也，大陵曰阿。\n仪：仪容，气度。\n沚：水中小洲。中沚，沚中也。小中小洲曰沚。\n中陵：陵中也。丘陵高坡之地。\n锡：同“赐”。朋：上古以贝壳为货币，五贝或十贝一串，两串为“朋”。王国维《说珏朋》云：“古制贝玉皆五枚为一系，二系一朋。”\n泛泛：漂浮不定的样子。杨舟：杨木做成的小船。\n载：或，又。\n休：喜。', poem_appreciation = '此诗的主旨，由于诗的境界的空泛性和意象的可塑性，对其内涵可以有不同的开掘和把握。《毛诗序》“乐育材”说流传二千多年，影响至巨。连批评《毛诗序》全失诗意的朱子，在其《白鹿洞赋》中，亦有“广‘青衿’之疑问，乐《菁莪》之长育”的句子。此所谓习用典记，约定俗成者也。对诗的主题，不同的理解可以并存，似不必存此没彼。这首诗的主题，爱情说更有道理，证据之一是人们公认《小雅》中典型描写男女相悦之情的《小雅·隰桑》篇，同《小雅·菁菁者莪》不论章法、句式都非常相似；前三章中“既见君子”句式一般无二，第四章都变换声调，各自成章。\n\n　　此诗前三章都以“菁菁者莪”起兴，也可以理解成记实，然不必过于拘泥，因“在彼中阿”、“在彼中沚”、“在彼中陵”的植物，除了“莪”，当然还有很多，举一概之而已。第一章，女子在莪蒿茂盛的山坳里，邂逅了一位性格开朗活泼、仪态落落大方、举止从容潇洒的男子，两人一见钟情，在女子内心深处引起了强烈震颤。第二章写两人又一次在水中沙洲上相遇，作者用一个“喜”字写怀春少女既惊又喜的微妙心理。第三章，两人见面的地点从绿荫覆盖的山坳、水光萦绕的小洲转到了阳光明媚的山丘上，暗示了两人关系的渐趋明朗化。“锡我百朋”一句，写女子见到君子后，因获得厚赐而不胜欣喜。第四章笔锋一转，以“泛泛杨舟”起兴，象征两人在人生长河中同舟共济、同甘共苦的誓愿。不管生活有顺境，有逆境，只要时时有恋人相伴，女子永远觉得幸福。\n\n　　这首诗虽然只有短短十六句，但把一个美妙动人的爱情故事表现得引人入胜。和《秦风·蒹葭》相比，《蒹葭》在水乡泽国的氛围中有一缕渺远空灵、柔婉缠绵的哀怨之情，把一腔执着、艰难寻求但始终无法实现的惆怅之情，寄托于一派清虚旷远、烟水濛濛的凄清秋色之中。而《菁菁者莪》处处烘托着清朗明丽的山光和灵秀迷人的水色，青幽的山坡，静谧的水洲，另是一番情致。两首诗可谓珠联璧合，各有千秋。', poem_tags = '诗经,写景,爱情' WHERE poem_title = '菁菁者莪' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '江水决堤啊又流回，心爱的人儿别处飞，从此再不和我相随。没有我相伴相陪你，终有一天你会懊悔。\n江水静流啊积沙岛，心爱的人儿别处飞，从此再不和我相交。在没有我的日子里，祝你平安岁月静好。', poem_notes = '江：长江。汜（sì）：由主流分出而复汇合的河水。\n归：荣归故里。妇人谓嫁曰归。\n不我以：不带我。我，媵自我也。\n渚（zhǔ）：水中小洲。王先谦《诗三家义集疏》“水中小洲曰渚，洲旁小水亦称渚。”\n不我与：不与我相聚。\n处：忧愁。朱骏声《说文通训定声》“‘处’，假借为‘癙’，实为‘鼠’”《诗经·小雅·雨无正》“鼠思泣血”，鼠思，忧思也。\n沱（tuó）：长江的支流名称。或以为与“汜”同。\n过：至也。一说度。\n其啸也歌：啸是唱歌没有谱和调的意思。有“狂歌当哭”的含义。一口出声，以抒愤懑之气，一说号哭。闻一多《诗经通义》“啸歌者，即号哭。谓哭而有言，其言又有节调也。”啸，蹙口出声，以舒愤懑之气，言其悔时也。歌，则得其所处而乐也。', poem_appreciation = '全诗三章。三章诗的开头都是写景。“汜”、“渚”、“沱”，上面的译文都从支流这一意义上翻译，而在弃妇心目中，这一条条不同的支流都是看得见的具体存在。她住在“汜”、“渚”、“沱”一带，她丈夫当年从水路而来，最后又从这些支流中的一条乘坐小船悄然离去。从表现手法说，各章的首句都是直陈其事，用的是赋体；从江水有支流，引出“之子归”的事实，则在赋体之中又兼有比兴的意味。\n\n　　诗中的丈夫是一位薄情郎。在三章诗中，那弃妇分别用“不我以”、“不我与”、“不我过”来诉说丈夫对她的薄情。“不我以”，是不一道回去；“不我与”，是行前不和“我”在一起；“不我过“，是有意回避，干脆不露面。丈夫在感情上是如此吝啬，做的是那样地恩尽义绝，无需再添加笔墨，其薄情薄意已如画出。\n\n　　诗中的弃妇是一位自信心很强的女人。她相信自己在丈夫感情生活中的重要地位，因而预言丈夫今日的背弃行为，日后必将在感情上受到自我惩罚，这就是各章结句所说的“其后也悔”、“其后也处”、“其啸也歌”。值得注意的是，丈夫将受到的感情上的自我惩罚与他背弃自己妻子的行为之间的对应关系：“不我以”引出“悔”，“不我与”带来“处”，“不我过”导致“啸歌”。其愈是绝情，其后果也就愈加严重。当然，这只是弃妇一厢情愿的假想之辞。事实上，那男子很可能事过境迁，在感情上并不引起任何震动。对于理解这首诗来说，重要的不在于弃妇自信的论断日后是否会成为事实，而是隐藏在这一论断背后的弃妇思想感情的复杂性。弃妇设想故夫日后会后悔今日的背弃行为，其中就隐含了弃妇对于夫妇关系重归于好的企盼；预言故夫今日的轻率必将招致日后的痛苦，这又泄露出弃妇恨过于爱的报复性的心态。这是她的软弱，也是她的坚强。由此决定了这首诗风格上的特点，既一唱三叹，极尽缠绵，又柔中见刚，沉着痛快。\n\n　　此诗每章的前三句叙事，后两句抒情。其中第三、四句重出——男子的薄情集中表现在这一句，女子的痛苦不幸也根源于这一句，因而采取了反覆咏叹的形式。重出的这一句子中的关键字，各章不同。从一章的“以”，一转而为二章的“与”，再转而为三章的“过”，愈转愈深，丈夫如何薄情，做妻子的又是如何痛苦不幸，都因了这一关键字的置换而得到一层深于一层的表现。全诗形式整齐，结构严谨，用字精审，笔法却极为自然，语言又十分浅近，达到了精工与自然、深入与浅出的完美结合，显示出极高的艺术水平。\n\n　　全诗以“江有汜”起兴，反复申述，大意是：不让我陪嫁，你会后悔的，你就痛苦去吧，你就一个人哭去吧。诗中“有”字为语助虚词，“汜”、“渚”、“沱”都是具体的水名，“以”、“与”、“过”都是动词，表示“陪同”（随嫁）的意思。', poem_tags = '诗经,闺怨' WHERE poem_title = '江有汜' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '一夜过后，初降的寒霜轻轻地附在瓦上，使得芭蕉折断，荷叶倾倒。\n耐寒的只有东边篱笆旁的菊花，它花蕊初开，让早晨多了一份清香。', poem_notes = '金粟：黄色的花蕊。', poem_tags = '咏物,菊花,品格,寓人,言志' WHERE poem_title = '咏菊' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '缑山仙子王子乔性情高远，不像牛郎织女要下凡人间。皎洁的月光中停下吹凤箫，摆一摆手告别人间去成仙。\n听说黄河竹筏能直上银河，一路上还挟带着天风海雨。今天相逢一醉是前生缘分，分别后谁知道各自向何方？', poem_notes = '鹊桥仙：词牌名，又名《鹊桥仙令》、《金风玉露相逢曲》、《广寒秋》等。\n缑（gōu）山：在今河南偃师县。缑山仙子指在缑山成仙的王子乔。\n云渺（miǎo）：高远貌。\n痴（chī）牛騃（ái）女：指牛郎织女。在这里不仅限于指牛郎织女，而是代指痴迷于俗世的芸芸众生。\n凤箫声：王子乔吹笙时喜欢模仿凤的叫声。\n时人：当时看到王子乔登仙而去的人们。\n槎（chá）：竹筏。\n银河：天河。\n尚（shàng）：还。\n前缘：前世的因缘。', poem_tags = '七夕节,月夜,送别,豪放' WHERE poem_title = '鹊桥仙·七夕' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '夏日初晴，诗人午睡醒来，只看到窗外的绿树和青苔。忽然一阵南风把房门吹开，又掀起桌上的书页，诗人说这是他的老相识，来偷偷访问他了。', poem_notes = '新晴：天刚放晴；刚放晴的天气。\n青苔：苔藓。\n梦余：梦后。', poem_tags = '古诗三百首,写风' WHERE poem_title = '新晴' AND poem_author = '刘攽';
UPDATE edu_poem SET poem_translation = '苕溪和霅溪的水是清澈的，更是有人像水这样清澈啊。秋天的江湖水横在天边簇拥着远处的山阿，相对映着十分美好。\n溪水上有鸳鸯，小船驶来他们被频频惊起。鸳鸯们回到碧玉色的池子里，生长在栏杆下面如何呢。', poem_notes = '苕霅：苕溪和霅溪的并称。是唐代张志和的隐居之处。\n盈盈：形容美好貌。\n艇子：小船。\n阑干：即栏杆设在楼阁或路边水边。李白《清平调词》：沉香亭北倚阑干。', poem_tags = '写景' WHERE poem_title = '卜算子·苕霅水能清' AND poem_author = '吴潜';
UPDATE edu_poem SET poem_translation = '辛亥年冬天，我冒雪去拜访石湖居士。居士要求我创作新曲，于是我创作了这两首词曲。石湖居士吟赏不已，教乐工歌妓练习演唱，音调节律悦耳婉转。于是将其命名为《暗香》、《疏影》。\n\n昔日皎洁的月色，曾经多少次映照着我，对着梅花吹得玉笛声韵谐和。笛声唤起了美丽的佳人，跟我一道攀折梅花，不顾清冷寒瑟。而今我像何逊已渐渐衰老，往日春风般绚丽的辞采和文笔，全都已经忘记。但是令我惊异，竹林外稀疏的梅花，谒将清冷的幽香散入华丽的宴席。\n江南水乡，正是一片静寂。想折枝梅花寄托相思情意，可叹路途遥遥，夜晚一声积雪又遮断了大地。手捧起翠玉酒杯，禁不住洒下伤心的泪滴，面对着红梅默默无语。昔日折梅的美人便浮上我的记忆。总记得曾经携手游赏之地，千株梅林压满了绽放的红梅，西湖上泛着寒波一片澄碧。此刻梅林压满了飘离，被风吹得凋落无余，何时才能重见梅花的幽丽？', poem_notes = '辛亥：光宗绍熙二年。\n石湖：在苏州西南，与太湖通。范成大居此，因号石湖居士。\n止既月：指住满一月。\n简：纸。\n征新声：征求新的词调。\n工伎：乐工、歌妓。隶习：学习。\n何逊：南朝梁诗人，早年曾任南平王萧伟的记室。任扬州法曹时，廨舍有梅花一株，常吟咏其下。后居洛思之，请再往。抵扬州，花方盛片，逊对树彷徨终日。杜甫诗“东阁官梅动诗兴，还如何逊在扬州。”\n但怪得：惊异。\n翠尊：翠绿酒杯，这里指酒。\n红萼：指梅花。\n耿：耿然于心，不能忘怀。\n千树：杭州西湖孤山的梅花成林。', poem_appreciation = '“自作新词韵最娇，小红低唱我吹箫。曲终过尽松陵路，回首烟波十四桥。”淡远蕴藉的笔墨描画出烟霭深沉的旅行，而这“韵最娇”的“新词”便是《暗香》《疏影》二首。沈祖棻云，“《暗香》《疏影》虽同时所作，然前者多写身世之感，后者则属兴亡之悲，用意小别，而其托物言志则同。”小诗流露出的才子词人姜夔于音乐中的那丝陶醉与忧郁，使人不禁想去赏析这首“读之使人神观飞跃”的《暗香》，走进笛里梅花，走进姜夔的清刚幽冷之境。\n\n　　“旧时月色，算几番照我，梅边吹笛。”月光清美，梅花溢香，这位词人吹的想必是笛曲《梅花落》了。笛韵悠然，当时的词人之心可是恬淡安闲，怡然自适，或是心有幽怀，黯然神伤，还是柔情蜜意，“相看好处却无言”？资人遐想，含有韵味。“算几番照我”，回忆并勾勒往事。“几番”约言其多，不止一次。唯“当时只道是寻常”，才有今日的追忆与幽思。“算”字送出一种回忆往事的凝神静思的状态，而这种回忆从根本上是缘于内心生发的感情，这是一种怀旧的情绪，于是引起下句对往事的追述。\n\n　　“唤起玉人”句，在月下、梅边、笛里复加一“玉人”，则美人梅花互衬，俨然有春日里“人面桃花相映红”之美。著一“唤”字则静中有动，静止的美丽图景变得立体而鲜活，出现了情趣。“不管清寒与攀摘”，冒着清寒，攀折梅花，则内心感情之热烈可知。这里清而不凄，清而非冷，清寒而不刺骨。“清”本是极普通的字，作者信笔写来，则天气之清寒，月色之清美，梅花之清香，都可融而为一，这里似乎凝含着往日的幸福之感与甜蜜之情。回视起句清空，它既可能是在“玉人”身旁的“吹笛”，也可能是孤身一人，因思念而吹笛，更可能是兼而有之，以“几番”二字囊括。和次句意脉似断非断，似连非连。这三个分句以寻常的字眼包蕴了广阔的时空，构造了悠远的意境，暗含了凄婉的感情，可谓很有笔力的开篇。\n\n　　下句笔锋陡转，以何逊自比，而着意在于“渐老”的衰飒。“而今”和开篇“旧时”相对，扩大了时间的厚重感。这里不仅有对往日恋人的怀念，还含有对逝去的美好岁月、青春风华的怀念和惋惜，正与“临晚镜，伤流景，往事后期空记省”的嗟悼悲慨暗合。说“忘却春风词笔”，却隐约含有往事不胜悲的意味，正如那位独上高楼望尽天涯路的伤心人，欲寄彩笺却又说“无尺素”一样。而今识尽愁滋味“却道天凉好个秋”，低徊如斯，哀婉如斯，“春风词笔”如何忘却？否则，“竹外疏花，香冷入瑶席”何以入眼，又何以“怪”之？此句又转入现时，竹外疏花萧瑟，冷香吹入瑶席，引人幽思，勾起回忆。正是“相思一夜梅花发，忽到窗前疑是君”，梅花与人两相思。这里见花思人，生出“怪得”之心，必是至深之情。“疏”“冷”烘托凄凉，“瑶席”反衬哀苦，用字可见匠心。', poem_tags = '宋词三百首,宋词精选,婉约,咏物,抒怀' WHERE poem_title = '暗香·旧时月色' AND poem_author = '姜夔';
UPDATE edu_poem SET poem_tags = '看花,讽刺' WHERE poem_title = '元和十年自朗州至京戏赠看花诸君子 / 玄都观桃花' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '江楼上醉饮话别橘柚正飘香，江风吹洒细雨带给小船凄凉。\n想象你独自远在潇湘明月下，满怀愁绪梦里静听猿啼悠长。', poem_notes = '魏二：作者友人。排行第二，名字及生平均不详。\n潇湘月：一作“湘江上”。潇湘：潇水在零陵县与湘水会合，称潇湘。泛指今湖南一带。\n清猿：即猿。因其啼声凄清，故称。南朝梁任昉《齐竟陵文宣王行状》：“清猿与壶人争旦，缇幕与素濑交辉。”', poem_appreciation = '送别魏二的饯宴设在靠江的高楼上，空中飘散着橘柚的香气，环境幽雅，气氛温馨。这一切因为朋友即将分手而变得尤为美好。这里叙事写景已暗挑依依惜别之情。“今日送君须尽醉，明朝相忆路漫漫”（贾至《送李侍郎赴常州》），首句“醉”字，暗示着“酒深情亦深”。\n\n　　“留恋处，兰舟催发”，送友人上船时，眼前秋风瑟瑟，“寒雨连江”，气候已变。次句字面上只说风雨入舟，却兼写出行人入舟；诗中不仅写了江雨入舟，然而“凉”字却明白的表现出登舟送客的惜别场景来，“凉”字既是身体上的感触，更暗含诗人心中对友人的不舍和对离别的伤怀。“引”字与“入”字呼应，有不疾不徐，飒然而至之感，善状秋风秋雨特点。此句寓情于景，句法字法运用皆妙，耐人涵咏。凄凄风雨烘托诗人惜别知音，借酒消愁的悲凉心情。\n\n　　按通常作法，后二句似应归结到惜别之情。但诗人却将眼前情景推开，“忆君遥在潇湘月”，以“忆”字勾勒，从对面生情，为行人虚构了一个境界：在不久的将来，朋友夜泊在潇湘之上，那时风散雨收，一轮孤月高照，环境如此凄清，行人恐难成眠吧。即使他暂时入梦，两岸猿啼也会一声一声闯入梦境，令他睡不安恬，因而在梦中也摆不脱愁绪。诗人从视（月光）听（猿声）两个方面刻画出一个典型的旅夜孤寂的环境。月夜泊舟已是幻景，梦中听猿，更是幻中有幻。所以诗境颇具几分朦胧之美，有助于表现惆怅别情。\n\n　　末句的“长”字状猿声相当形象，有《水经注·三峡》中描写猿声的意境：“时有高猿长啸，属引凄异，空谷传响，哀转久绝。”“长”字作韵脚用在此诗之末，更有余韵不绝之感。\n\n　　这首诗运用了虚实结合的手法。第一、二两句写在一个空中飘散着橘柚清香的清秋的日子里，诗人在靠江的高楼上设宴为朋友送别，然后在秋风秋雨中送友人上船。这两句是写眼前实景。后两句诗人以“忆”为行人虚构了一个典型的旅夜孤寂的场景：友人难以成眠，即使友人暂时入梦，两岸猿啼也会一声一声闯入梦境，使他摆不脱愁绪。这两句是虚拟，月夜泊舟已是幻景，梦中听猿，更是幻中有幻。这样整首诗虚实结合，借助想像，拓展了表现空间，扩大了意境，使诗更具朦胧之美，深化了主题，更有助于表现惆怅别情。通过造境，“道伊旅况愁寂而已，惜别之情自寓”（敖英评，《唐诗绝句类选》），“代为之思，其情更远”（陆时雍《诗镜总论》）。在艺术构思上是颇有特色的。', poem_tags = '写景,送别,友情' WHERE poem_title = '送魏二' AND poem_author = '王昌龄';
UPDATE edu_poem SET poem_translation = '江水决堤啊又流回，心爱的人儿别处飞，从此再不和我相随。没有我相伴相陪你，终有一天你会懊悔。\n江水静流啊积沙岛，心爱的人儿别处飞，从此再不和我相交。在没有我的日子里，祝你平安岁月静好。', poem_notes = '江：长江。汜（sì）：由主流分出而复汇合的河水。\n归：荣归故里。妇人谓嫁曰归。\n不我以：不带我。我，媵自我也。\n渚（zhǔ）：水中小洲。王先谦《诗三家义集疏》“水中小洲曰渚，洲旁小水亦称渚。”\n不我与：不与我相聚。\n处：忧愁。朱骏声《说文通训定声》“‘处’，假借为‘癙’，实为‘鼠’”《诗经·小雅·雨无正》“鼠思泣血”，鼠思，忧思也。\n沱（tuó）：长江的支流名称。或以为与“汜”同。\n过：至也。一说度。\n其啸也歌：啸是唱歌没有谱和调的意思。有“狂歌当哭”的含义。一口出声，以抒愤懑之气，一说号哭。闻一多《诗经通义》“啸歌者，即号哭。谓哭而有言，其言又有节调也。”啸，蹙口出声，以舒愤懑之气，言其悔时也。歌，则得其所处而乐也。', poem_appreciation = '全诗三章。三章诗的开头都是写景。“汜”、“渚”、“沱”，上面的译文都从支流这一意义上翻译，而在弃妇心目中，这一条条不同的支流都是看得见的具体存在。她住在“汜”、“渚”、“沱”一带，她丈夫当年从水路而来，最后又从这些支流中的一条乘坐小船悄然离去。从表现手法说，各章的首句都是直陈其事，用的是赋体；从江水有支流，引出“之子归”的事实，则在赋体之中又兼有比兴的意味。\n\n　　诗中的丈夫是一位薄情郎。在三章诗中，那弃妇分别用“不我以”、“不我与”、“不我过”来诉说丈夫对她的薄情。“不我以”，是不一道回去；“不我与”，是行前不和“我”在一起；“不我过“，是有意回避，干脆不露面。丈夫在感情上是如此吝啬，做的是那样地恩尽义绝，无需再添加笔墨，其薄情薄意已如画出。\n\n　　诗中的弃妇是一位自信心很强的女人。她相信自己在丈夫感情生活中的重要地位，因而预言丈夫今日的背弃行为，日后必将在感情上受到自我惩罚，这就是各章结句所说的“其后也悔”、“其后也处”、“其啸也歌”。值得注意的是，丈夫将受到的感情上的自我惩罚与他背弃自己妻子的行为之间的对应关系：“不我以”引出“悔”，“不我与”带来“处”，“不我过”导致“啸歌”。其愈是绝情，其后果也就愈加严重。当然，这只是弃妇一厢情愿的假想之辞。事实上，那男子很可能事过境迁，在感情上并不引起任何震动。对于理解这首诗来说，重要的不在于弃妇自信的论断日后是否会成为事实，而是隐藏在这一论断背后的弃妇思想感情的复杂性。弃妇设想故夫日后会后悔今日的背弃行为，其中就隐含了弃妇对于夫妇关系重归于好的企盼；预言故夫今日的轻率必将招致日后的痛苦，这又泄露出弃妇恨过于爱的报复性的心态。这是她的软弱，也是她的坚强。由此决定了这首诗风格上的特点，既一唱三叹，极尽缠绵，又柔中见刚，沉着痛快。\n\n　　此诗每章的前三句叙事，后两句抒情。其中第三、四句重出——男子的薄情集中表现在这一句，女子的痛苦不幸也根源于这一句，因而采取了反覆咏叹的形式。重出的这一句子中的关键字，各章不同。从一章的“以”，一转而为二章的“与”，再转而为三章的“过”，愈转愈深，丈夫如何薄情，做妻子的又是如何痛苦不幸，都因了这一关键字的置换而得到一层深于一层的表现。全诗形式整齐，结构严谨，用字精审，笔法却极为自然，语言又十分浅近，达到了精工与自然、深入与浅出的完美结合，显示出极高的艺术水平。\n\n　　全诗以“江有汜”起兴，反复申述，大意是：不让我陪嫁，你会后悔的，你就痛苦去吧，你就一个人哭去吧。诗中“有”字为语助虚词，“汜”、“渚”、“沱”都是具体的水名，“以”、“与”、“过”都是动词，表示“陪同”（随嫁）的意思。', poem_tags = '诗经,闺怨' WHERE poem_title = '江有汜' AND poem_author = '佚名';
UPDATE edu_poem SET poem_tags = '哲理' WHERE poem_title = '哀溺文序' AND poem_author = '柳宗元';
UPDATE edu_poem SET poem_translation = '天上升起一轮明月，\n都说每个地方都是一样的月色。\n哪里知道远在千里之外，\n就没有急风暴雨呢？', poem_notes = '圆魄：指中秋圆月。\n安知：哪里知道。', poem_appreciation = '这首诗借咏中秋的月亮，表明世上万物不可能完全一样，存在着千差万别。\n\n　　“圆魄上寒空，皆言四海同。安知千里外，不有雨兼风。”意思是此时此地“圆魄”（明月）当空，又怎见得此时彼地（“千里外”）“不有雨兼风”呢？千里指很远的意思，风雨可借指人生的无常和艰辛。你怎么会知道外边千里之外的世界，没有风雨呢？\n\n　　人人“皆言”的未见得就是真理。大千世界，变化万千，人类对自然和社会的认识是随着人类认识能力的提高而不断深化、发展的，一种认识的正确与否，并不取决于持这种认识的人数的多寡，即便对人人“皆言”为是的，也要敢于怀疑，不断深入地探索。其二，认识问题最忌以此代彼，以偏代全，以对局部、片面的现象描述替代对整体或本质的探求。见到此时此地皓月当空而想象四海皆同，便正是以此代彼、以偏概全。\n\n　　这首五言绝句，写此地有月光，彼地有风雨，意在风雨，而非赏月。李峤其人曾三度任职宰相，对政坛的风云变幻自然十分敏感——高空中一轮明月照射大地，众人都说今夜各处的月光都一样明亮；可是谁能晓得千里之外，无雨骤风狂？这首诗以咏月为题，揭示了一个真理：世上的事千差万别，千变万化，不可能全都一样。正如中秋夜，此处皓月当空，他处却风雨交加。', poem_tags = '中秋节,月亮,哲理' WHERE poem_title = '中秋月二首·其二' AND poem_author = '李峤';
UPDATE edu_poem SET poem_tags = '爱情,回忆,相思' WHERE poem_title = '荷叶杯·记得那年花下' AND poem_author = '韦庄';
UPDATE edu_poem SET poem_translation = '乘一叶小舟，荡着双桨，像惊飞的鸿雁一样，飞快地掠过水面。天空碧蓝，水色清明，山色天光，尽入江水，波平如镜。水中游鱼，清晰可数，不时跃出明镜般的水面；水边沙洲，白鹭点点，悠闲自得。白天之溪，清澈而见沙底；清晓之溪，清冷而有霜意；月下之溪，是明亮的水晶世界。\n两岸连山，往纵深看则重重叠叠，如画景；从横列看则曲曲折折，如屏风。笑严光当年白白地在此终老，不曾真正领略到山水佳处。皇帝和隐士，而今也已如梦一般消失，只留下空名而已。只有远山连绵，重峦叠嶂；山间白云，缭绕变幻；晓山晨曦，青翠欲滴。', poem_notes = '行香子：词牌名。\n七里濑：又名七里滩、七里泷，在今浙江省桐庐县城南三十里。钱塘江两岸山峦夹峙，水流湍急，连绵七里，故名七里濑。濑，沙石上流过的急水。\n一叶：舟轻小如叶，故称“一叶”。\n湛（zhàn）：清澈。\n藻鉴：亦称藻镜，指背面刻有鱼、藻之类纹饰的铜镜，这里比喻像镜子一样平的水面。藻，生活在水中的一种隐花植物。鉴，镜子。\n鹭：一种水鸟。汀（tīng）：水中或水边的平地，小洲。\n屏：屏风，室内用具，用以挡风或障蔽。\n严陵：即严光，字子陵，东汉人，曾与刘秀同学，并帮助刘秀打天下。刘秀称帝后，他改名隐居。刘秀三次派人才把他召到京师。授谏议大夫，他不肯接受，归隐富春江，终日钓鱼。\n君臣：君指刘秀，臣指严光。\n空名：世人多认为严光钓鱼是假，“钓名”是真。这里指刘秀称帝和严光垂钓都不过是梦一般的空名而已。', poem_tags = '江南,水乡,人生,哲学' WHERE poem_title = '行香子·过七里濑' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '美丽的邻家女子，白天时用衣袖遮住脸，春日里更添惆怅，懒得装扮，都是有原因的。\n她深深慨叹着，像她这样的女子，在人世间求得无价的珍宝，是很容易办到的事，而想要获得一个志诚的心灵伴侣，却是如此的困难。\n为此她夜夜在枕上暗自垂泪感伤，为此她经过花丛间也不免有了断肠的思量。\n然而，既然已有了这样的才貌，那么，只要再鼓起勇气，主动争取，便是宋玉这样的才子也能求得的，又何必怨恨王昌这样的才子，若即若离的态度呢？', poem_notes = '此诗一作《寄李员外》，一作《寄李亿员外》。\n遮罗袖：一作“障罗袖”。\n宋玉：战国楚辞赋家，屈原弟子，著录赋十六篇，颇多亡佚。\n王昌：唐人习用。', poem_appreciation = '韦毅《才调集》将这首诗直标为《寄李亿员外》。从诗意可以看出，此诗是在咸宜观当道士时写的，可以把这首诗看成是鱼玄机对李亿绝望后表示心迹的诗。\n\n　　古代女人毫无地位，常被男人随意冷落抛弃，所以古代女人多有对男人之无情的不满和哀叹。男子可以妻妾成群，女子却只能从一而终，不能自由恋爱。腐朽的制度，造成许多男子在爱情上喜新厌旧，情意不专，因而女子要想寻得一个有情有义的丈夫，比寻求一件无价之宝还难。\n\n　　此诗是至情之语，不仅表现了她对李亿之无情的怨恨，也写出了古代被遗弃女子的怨愤，高度概括了封建社会中妇女普遍不幸的遭遇，喊出了被侮辱被损害妇女痛苦的心声。\n\n　　鱼玄机才十七八岁便嫁给李亿为妾，原先甚得李的宠爱，后李因其妻之谗言，而将玄机冷落。她从自己的切身经历出发，总结出了当时女子的爱情，哀婉的韵律，蕴含着深刻的哲理。', poem_tags = '女子,爱情,哲理' WHERE poem_title = '赠邻女 / 寄李亿员外' AND poem_author = '鱼玄机';
UPDATE edu_poem SET poem_translation = '白雪融化是因为阴阳之气的交合，寒冰化开是因为得到了温暖阳光的照耀。\n春天到来，消解不掉的，只有鬓边像霜一样的白发了。', poem_notes = '和气：阴阳交合之气。\n鬓边霜：鬓边的白发。', poem_tags = '写雪,抒情,愁绪' WHERE poem_title = '早春' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '春回大地，万象更新，满怀游春逸兴来到山中，山中有许多美好的事物，备感赏心悦目，欣慰无比，以至夜幕降临后仍留恋不已，竟而忘返。捧起清澄明澈的泉水，泉水照见月影，好像那一轮明月在自己的手里一般；摆弄山花，馥郁之气溢满衣衫。游兴正浓真是不忍离去，哪管它规程迢迢；几番下定决心离开，却又依恋山中一草一木。怀着矛盾的心情，在山道上漫步徐行，这时一阵幽远的钟声传来，抬头望那钟鸣之处，原来是隐于翠绿丛中、月色之下的山中楼台。', poem_notes = '春山：一作“春来”。\n掬（jū）：双手捧起。《礼记·曲礼上》云：“受珠玉者以掬。”\n鸣钟：一作“钟鸣”。\n翠微：指山腰青翠幽深处，泛指青山。庾信《和宇文内史春日游山》诗云：“游客值春晖，金鞍上翠微。”', poem_appreciation = '此诗载于《全唐诗》卷二百七十五。诗的开头二句点出：春天的山中有许多美好的事物，自己游春只顾迷恋玩赏，天黑了，竟然忘了归去。这两句，提纲挈领，统率全篇。以下六句，具体展开对“胜事”与“赏玩忘归”的描述。一、二句之间，有因果关系，“多胜事”是“赏玩忘归”的原因。而“胜事”又是全诗发脉的地方。从通篇着眼，如果不能在接着展开的三、四句中将“胜事”写得使人心向往之，那么，其余写“赏玩忘归”的笔墨，势将成为架空之论。\n\n　　在这吃紧处，诗人举重若轻，毫不费力地写道：“掬水月在手，弄花香满衣”。此处描写堪称恰到好处：第一，从结构上来看，“掬水”句承第二句的“夜”，“弄花”句承首句的“春”，笔笔紧扣，自然圆到。一、二句波纹初起，至这两句形成高潮，以下写赏玩忘归的五、六两句便是从这里荡开去的波纹。第二，这两句写山中胜事，物我交融，神完气足，人情物态，两面俱到。既见出水清夜静与月白花香，又从“掬水”“弄花”的动作中显出诗人的童心不灭与逸兴悠长。所写“胜事”虽然只有两件，却足以以少胜多，以一当十。第三，“掬水”句写泉水清澄明澈照见月影，将明月与泉水合而为一；“弄花”句写山花馥郁之气溢满衣衫，将花香衣香浑为一体。艺术形象虚实结合，字句安排上下对举，使人倍觉意境鲜明，妙趣横生。第四，精于炼字。“掬”字，“弄”字，既写景又写人，既写照又传神，确是神来之笔。\n\n　　诗人完全沉醉在山中月下的美景之中了。唯兴所适，根本不去计算路程的远近。而当要离开时，对眼前的一花一草不能不怀依依惜别的深情。这就是诗人在写出“胜事”的基础上，接着铺写的“兴来无远近，欲去惜芳菲”二句的诗意。这两句写赏玩忘归，“欲去”二字又为折入末两句南望楼台埋下伏笔。\n\n　　正当诗人在欲去未去之际，夜风送来了钟声。他翘首南望，只见远方的楼台隐现在一处青翠山色的深处。末两句从近处转向远方，以声音引出画面。展示的虽是远景，但仍然将春山月下特有的情景，用爱怜的笔触轮廓分明地勾勒了出来，并与一、二、三句点题的“春山”、“夜”、“月”正好遥相呼应。\n\n　　综上所述，可见三、四两句是全诗精神所在的地方。这两句在篇中，如石韫玉，似水怀珠，照亮四围。全诗既精雕细琢，又出语天成，自具艺术特色。', poem_tags = '春天,游历,山水,月亮' WHERE poem_title = '春山夜月' AND poem_author = '于良史';
UPDATE edu_poem SET poem_translation = '斟酒给你请你自慰自宽，人情反复无常就像波澜。\n相交到老还要按剑提防，先贵者却笑我突然弹冠。\n野草新绿全经细雨滋润，花枝欲展却遇春风正寒。\n世事浮云过眼不值一提，不如高卧山林努力加餐。', poem_notes = '裴迪：唐代诗人。字、号均不详，关中（今属陕西）人。官蜀州刺史及尚书省郎。盛唐著名的山水田园诗人。王维的好友。\n自宽：自我宽慰。《列子·天瑞》：“孔子曰：‘善乎，能自宽者也。’”\n人情：人心。翻覆：谓反覆无常；变化不定。\n相知：互相知心的朋友。按剑：以手抚剑，预示击剑之势，表示提防。\n朱门：红漆大门。指贵族豪富之家。先达：有德行学问的前辈。弹冠：弹去帽子上的灰尘，准备做官。\n经：一作“轻”。\n花枝：开有花的枝条。\n世事：世务，世上的事。何足问：不值得一顾。何足，犹言哪里值得。\n高卧：安卧；悠闲地躺着。指隐居不仕。\n加餐：慰劝之辞。谓多进饮食，保重身体。', poem_appreciation = '此诗是王维晚年诗作中十分值得玩味的一篇。首句“酌酒与君君自宽”，“君”字重复强调，这是障眼法；骨子里其实是胸中郁积愤懑，需与挚友一起借酒浇化。所谓“宽”者，宽人也即宽己，正是因为无法排遣。故次句“人情翻覆似波澜”，一曰翻覆，二曰波澜，足见心中愤激之情。三四句紧承“人情翻覆”，照应止水波澜的外部刺激，强调矛盾两端，铺叙反目成仇，人心无常。白首相知尚且如此，其他的人就不用说了。相知成仇，先达不用，说尽了世态炎凉，当是实有所指。前四句关键在“笑”字。弹冠”本为援手荐引乃同契之义，此处则反用其意，一旦“先达”即笑侮后来弹冠（出仕）者，轻薄排挤，乃至下井落石，此为淋漓之戟骂。金圣叹以为“自是千古至今绝妙地狱变相”，诚为得言。\n\n　　从内容上说，五六两句是即景即情，从户内至室外，为酌酒时举目所见，由世态炎凉，人情翻覆展示天地无私，万物亲仁，豁然呈现一新境界。被王静安先生誉为“摄春草之魂”的“细雨湿流光”，诗人用以描写映窗草色；禅宗关于“心动”“物动”的著名偈语，诗人借以描绘照眼花枝，即使单纯作“景语”看，也属上乘。而其蕴涵则在“全经”，“欲动”，由彰显至深密，从象外到象内，大千世界，无所不容；仅观人间之蝇营狗苟，于义愤之外，恍然顿悟。从章法上说，律诗中间两联要求虚实相生，三四句实写，五六句则应当化实为虚，措辞表意不可复犯，方能体现“神韵”“气象”之妙。从禅学上说，佛家主“虚静”，尚“自然”，和光同尘；深一层探求，五六句似还参合“有无”“生灭”“变常”之理；即处“静观”“达观”态度，与三四句世俗的“势利”“凉薄”恰成对照。末两句“世事浮云”与“高卧加餐”由禅意而来。“何足问”有不屑一顾的鄙薄之意，所指实有其人其事，承三四句，“高卧”承五六句，超凡脱俗。前后既错综成文，又一气贯注，构思布局缜密精妙。\n\n　　亦显亦隐、半儒半释的人生经历与处世态度，给王维造成巨大的心理矛盾，犹如碧潭止水，宜清心静观；但仰望高谷急湍，依旧凛然飞动，怵目惊心。王维全部诗作均可作如是观，通过《酌酒与裴迪》一诗即可透视此种矛盾心态。', poem_tags = '写景,愤懑' WHERE poem_title = '酌酒与裴迪' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '戴着一顶斗笠披着一件蓑衣坐在一只小船上，一丈长的渔线一寸长的鱼钩；\n高声唱一首渔歌喝一樽酒，一个人在这秋天的江上独自垂钓。', poem_notes = '蓑（suō）笠：蓑衣、笠帽。用草编织成的古时渔家、农民的防雨草衣；笠：用竹篾或芦秆篾片编织的帽子，也是渔家、农民防日晒、防雨淋的帽子。扁舟：小船。\n丝纶（lún）：即丝织编成的钓鱼的绳子。\n樽（zūn）：酒杯。\n扁舟：小船。', poem_appreciation = '全诗描写了一个渔夫打扮的人，在江上垂钓的情形：一件蓑衣、一项斗笠、一叶轻舟、一支钓竿，垂钓者一面歌唱，一面饮酒，垂钓的潇洒被刻画得活灵活现。虽然独自钓起一江的秋意，但逍遥中不免深藏几许萧瑟和孤寂。\n\n　　前两句近乎白描，后两旬却有着无穷意味。图中看似不可能的“一曲高歌一樽酒”在作者的想象中展现出来。而最后一句“一人独钓一江秋”似是回归原图，但此“钓”已非彼“钓”了，赏一江秋景，感一江秋色，联想开去，那是一种感怀，或者说，最后一句已是“虚实相映”了。\n\n　　再观全诗，九个“一”巧妙嵌入其中，将诗与图的意境表现得分毫不差，细细品味，这些“一”用得十分贴切又有情趣。最后一句“一人独钓一江秋”，渔人钓的是鱼？是秋？是潇洒自在的生活？是无拘无束的心情？在诗人看来，这样的秋江独钓者，才是真正懂得生活乐趣的人。', poem_tags = '题画,渔人' WHERE poem_title = '题秋江独钓图' AND poem_author = '王士祯';
UPDATE edu_poem SET poem_translation = '痛心啊，由于进谏而招来不幸，我要倾诉心中的激情和怨情。\n　　如果我的话不是出于忠诚啊，我愿上指苍天让他来作证。\n　　让五方神帝来公平裁决吧，我愿面对六宗神祇把事理说清。\n　　请山川众神都来听证做陪审啊，命法官皋陶把是非曲直判明。\n　　我竭尽忠诚来侍奉君王啊，反被小人看作是多余的瘤肿。\n　　我不懂奉迎谄媚而惹恼小人啊，只有等待明君体察我的衷情。\n　　我的一言一行都有迹可查啊，我表里如一从不变更。\n　　所以考察臣子没有比得上君王的啊，因为这种考察在眼前就可得到印证。\n　　我坚守人生道义是先君后己，竟然被众人怨恨仇视。\n　　我心中思念的只有君王您啊，众人却把我当做仇敌。\n　　我忠诚专一毫不迟疑，可结果却不能保全自己。\n　　我极力地亲近君王别无他想，却成了招灾惹祸的根基！\n　　为君王着想没人比我更忠心啊，我竟然忘却了自己人微才疏。\n　　侍奉君王我从不三心二意啊，根本不知什么取宠邀幸的门路。\n　　忠心有何罪竟遭惩罚啊，这真是我心中从未意想到。\n　　行为不同俗随流就要跌跤，还要受到群小的讥讽嗤笑。\n　　一连串的责怪，不断的诽谤啊，真使我愁肠百结不平难消！\n　　心情郁郁难以倾诉啊，君王受蒙蔽忠心难剖。\n　　心头愁闷失意潦倒啊，又有谁理解我心头的苦恼。\n　　本来有说不完的话却无法投寄啊，我愿陈述心志却无路使君王知晓。\n　　隐退沉默吧，可谁又明白我呢？\n　　上前呼喊吧，可谁又听我的呼号？\n　　一再的失意使我心烦意乱啊，满怀的愁绪呵，难写难描。\n　　从前我曾梦中飞游苍天啊，魂悠悠中途遇河却无渡船。\n　　我请大神替我占卜啊，他说：“你有大志可惜无外人助援。”\n　　“难道我就终将孤独被君王疏远？”\n　　他说：“可以为君王着想却不可依仗。\n　　因为众口一词可以把黄金熔化啊，当初你就是这样忠诚才遭受到危险。\n　　被汤烫过的人见到凉菜也要吹气，为什么你不把初衷改变改变？\n　　想不用天梯就打算登天，你的态度一丝没改还像从前。\n　　众人害怕你，不与你同心同德，为什么会和你做伴？\n　　虽同事一君但你们路途各异，为什么会给你助援？\n　　晋国的申生是个孝子啊，父亲把他逼死就是听信了谗言。\n　　鲧为人刚直不活转，他的功业因此不得实现。”\n　　我听说尽忠君王容易与人结怨，对此我毫不在意以为是夸大。\n　　手臂多次折伤的人可能成良医，如今我才明白这话一点儿不差。\n　　如今这个世道，天上利箭横飞，地上张罗设网。\n　　处处暗设机关陷害君王，哪里有我立足容身的地方。\n　　我徘徊不去以求留在君王身旁啊，又怕更大的祸患落在头上。\n　　我想抽身远走高飞啊，又怕君王诬我说：“你背叛我，要去什么地方？”\n　　想放弃正路像小人那样乱窜啊，可我一向心坚志专又不忍心。\n　　我的前胸和后背就像裂开一样啊，我心头郁闷难舒，绞痛难忍。\n　　捣碎木兰，揉碎蕙草啊，舂碎申椒做干粮。\n　　再播种下江离栽上菊花啊，待到春天做成干粮芬芳。\n　　唯恐我的真情得不到表达啊，所以三番五次表明衷肠。\n　　保持自己的美德，离群索居吧，我反复想过隐身远藏。\n\n涉江\n　　我从小就爱好这奇特的服饰啊，直到老年这习惯也没有衰减。\n　　腰间挂着长长的宝剑啊，头上戴着高高的通天冠。\n　　缀着明月珠啊，身佩美玉串串。\n　　世道混浊没有人理解我啊，我要远走高飞，毫不留恋。\n　　驾起青龙白龙车啊，我与舜帝啊同游天帝的玉园。\n　　登上昆仑山啊，把玉树花美餐。\n　　我和天地啊一样长寿，我和日月啊一样光灿灿。\n　　痛心啊南方并没有人了解我，天一亮我就渡过了湘水长江。\n　　登上鄂渚我回头眺望啊，唉，丝丝寒风凄苦悲凉。\n　　让我的马儿在山边漫步，把我的车儿停放在林旁。\n　　我驾一叶扁舟上溯沅水啊，齐力摇起船桨，拍水击浪。\n　　船儿随波起伏不肯前进啊，陷入旋涡打转波荡。\n　　早晨，从枉渚出发，晚上，投宿在辰阳。\n　　如果我的心是正直的啊，虽处穷乡僻壤又有何伤！\n　　行到溆浦我有些打不定主意啊，心中迷惘不知该去何方。\n　　茂密的山林一片阴暗啊，那本是猿猴住的地方。\n　　高峻的大山遮天蔽日啊，山下淫雨霏霏迷迷茫茫。\n　　无边无际的雪花啊飞飞扬扬，布满天空的浓云阴沉无光。\n　　可怜我一生无欢乐啊，孤独地生活在这高山老林中。\n　　我不能改变心志去随波逐流啊，当然就要穷愁潦倒终生。\n　　接舆愤世剃去自己的头发，桑扈穷得裸体而行。\n　　忠心的人啊，不被重用，贤明的人求进身也难成功。\n　　伍子胥终遭祸殃啊，比干被剖心不得善终。\n　　纵观历史都是这样啊，我又何苦抱怨今人的行径！\n　　但我要坚持正道而毫不犹豫，当然那将使我一生遭难不见光明！\n　　尾声：鸾鸟和凤凰啊，一天比一天远了。\n　　燕雀和乌鹊啊，却把窝筑在庙堂上面。\n　　瑞香和辛夷啊，都死在林丛草间。\n　　腥的臊的都被重用啊。\n　　芳的香的却不得靠前。\n　　阴阳错位都颠倒了位置，这世道真是失常大变。\n　　怀抱忠心的人反失意，我还是赶快远走别迟疑！\n\n哀郢\n　　上天不再保佑我家邦啊，为什么让人们这样凄凄惶惶？\n　　他们颠沛流离，亲人失散啊，正当仲春二月逃向东方。\n　　离开故乡郢都走向远处啊，沿着长江夏水流亡。\n　　一走出城门我心不禁一阵疼痛啊，甲日的早晨我动身向东方。\n　　从郢都出发离开家乡啊，我心中恍惚，前途渺茫。\n　　举起船桨让船儿随水飘荡啊，可怜我再也见不到君王。\n　　远望那高大的梓树我不禁长叹啊，眼泪就像雪珠般簌簌流淌。\n　　过了夏首一路飞流直下啊，回头已看不见郢都城门在何方。\n　　牵肠挂肚心悲伤啊，前途渺茫不知何处是我停脚的地方。\n　　随着风波任其漂泊吧，从此我就是一个无家的浪子到处飘荡。\n　　航行在汹涌的波涛上啊，就像飞了起来不知把我抛向何方。\n　　情思郁结难排解啊，愁肠百曲不舒畅。\n　　我将让我的船儿顺流东下啊，先南入洞庭再北上长江。\n　　离开了世世代代居住的故土啊，而今漂泊来东方！\n　　我的心一直想回去啊，何曾一时一刻把它忘记。\n　　船背夏首向东行啊，心儿却飞向西，悲伤啊郢都一天比一天远离。\n　　登上水边高地纵目远望啊，想借此暂且舒散一下我的愁绪。\n　　可一见这片安乐的土地悲心又起啊，可怜大江两岸还保存着古朴的风气。\n　　面对着洪波巨浪往哪儿去啊，烟波浩渺南渡又将到何处？\n　　想不到高屋大厦变成废墟啊，两座东门怎么能荒草簇簇？\n　　心中不快这样久啊，旧忧未去又添新愁。\n　　想郢都的道路是多么遥远啊，长江夏水怎么能回头再渡！\n　　忽然间被疏远不再被任用啊，至今已整整过了九个年头。\n　　满怀悲苦心不畅啊，失意潦倒真忧愁。\n　　那群小为邀君欢一副媚态啊，实际内心空虚毫无操守。\n　　我一片忠心希望为国献身啊，反被小人嫉妒使我们君臣离分。\n　　尧舜的德行多么高尚啊，光明远烛直达天庭。\n　　众小人把他们嫉妒诽谤，给他们加上“不慈”的恶名。\n　　忠诚有德的人被君王厌恶憎恨啊，反喜欢那巧嘴滑舌夸夸其谈的人。\n　　众群小奔走钻营一天天高升啊，贤臣良士被冷落日益疏远不亲近。\n　　尾声：我放眼眺望四方啊，何时能回一次故乡？\n　　飞鸟还要飞回自己的巢窝啊，狐狸死了还把头朝向生他养他的山冈。\n　　我真是无罪啊而被抛弃流放，日日夜夜我怎能把它忘！\n\n抽思\n　　心头闷闷一团忧思啊，独自长叹倍增忧伤。\n　　愁思如麻难理难剪啊，夜啊偏偏又这样漫长。\n　　秋风使草木改变了颜色啊，为什么天地也在秋风中浮荡？\n　　我常常想起您是那么爱动怒，真伤透了我的心痛苦难当。\n　　有时我真想立刻离您远去啊，见人们动辄得咎又打消此想。\n　　还是把心中的话写成诗篇吧，把它进献给您，我的君王。\n　　先前你曾和我约定啊，说：“黄昏就是我们的佳期。”\n　　谁料想你半路又翻悔啊，违背前言又打别的主意。\n　　你对我夸耀你的美貌丽容啊，你对我炫示你的媚态娇姿。\n　　和我说过的话你全不算数啊，为什么还对我大发脾气？\n　　我本想找空闲向你解释明白啊，可一直心里害怕不敢倾吐。\n　　我悲伤犹豫，可仍想对你说啊，真是苦啊，满腹悲伤不能诉。\n　　我把这情形向你陈述啊，可你假装耳聋不肯听。\n　　本来正直的人就不会献媚啊，群小真就把我当成害人精。\n　　当初我所说的是那样明白啊，难道至今你就把它全遗忘？\n　　为什么我爱忠心耿耿地向你进言，就是希望你的美德更加光大发扬。\n　　愿你以三王五霸做楷模啊，我把彭咸作为自己的榜样。\n　　什么目标不能达到啊，美名远播，万古流芳。\n　　善良的品德全靠自己修养啊，美好的名声不能浪得空想。\n　　不付出哪能得到回报啊，不结果实怎会收获满仓？\n　　小歌：\n　　我向君王倾诉出我的委屈啊，从早说到晚却得不到公平的裁定。\n　　你一味地向我炫耀你的美貌啊，你骄傲得连我的陈辞听也不听。\n　　唱：\n　　有只鸟儿从南方飞来啊，飞落在汉水以北的地方。\n　　羽毛模样是多么美丽啊，孤孤单单栖息在异乡。\n　　我孤苦零丁无伴侣啊，也没有好媒人在身旁。\n　　路途遥远你一天天把我遗忘啊，我欲诉深情却又无门见到君王。\n　　遥望南山止不住眼泪流淌啊，对着流水我叹息哀伤。\n　　初夏的夜本来很短啊，为什么竟像一年般的长！\n　　想来郢都的路是多么遥远啊，可是魂梦一夜跑九趟。\n　　我不顾道路是弯还是直啊，直奔南方的群星和月亮。\n　　想径直南行识不得路啊，魂灵为找路来往奔忙。\n　　为什么我的心那样正直啊？\n　　别人的心不与我一样。\n　　提亲的人太弱不能为我沟通啊，还不知我心胸磊落坦荡。\n　　尾声：\n　　长长的浅滩湍急的流水，我溯江而上。\n　　我频频地望着南行的大道，聊以平慰我的愁肠。\n　　我的心坚如高大的磐石，飞回郢都是我的愿望。\n　　山高路险心儿早已飞过，人啊还缓缓地走在路上。\n　　走走停停路难行，夜晚投宿在北姑。\n　　心烦意乱满怀苦楚，就像不断的流水难消除。\n　　我悲苦，我叹息，我呻吟，我的心啊在思念着远方。\n　　路又远啊地又偏，又没人替我传达衷肠。\n　　倾诉愁思写成诗章，聊以自慰宽愁肠啊。\n　　忧心忡忡不遂意，这些话儿对谁讲！\n\n怀沙\n　　初夏的江水一片汪洋啊，草木繁茂莽莽苍苍。\n　　痛心啊，止不住的哀伤，我急急地奔向南方。\n　　举目四望一片昏暗啊，死一般沉寂听不到一丝声响。\n　　无穷的委屈和悲痛郁结心头啊，身遭不幸有喝不完的苦浆。\n　　拍拍心窝问问心啊，强自压下满腹的委屈和冤枉。\n　　虽说方的可以削成圆啊，可正常的法度并不因此而废弃。\n　　如果把初衷和追求来改变啊，定会被贤人君子看不起。\n　　章程规划早已出之笔墨啊，当初图谋的经国大法不能改移。\n　　品行淳厚心地正直啊，才是贤人君子所赞许的。\n　　巧倕如果不砍上几斧啊，谁知他有变曲为直的神工妙技？\n　　黑色的彩绘放在暗处啊，瞎人说它不鲜艳。\n　　离娄微微闭着眼啊，盲人说他是瞎眼汉。\n　　硬把白的说成黑啊，把上当下颠倒颠。\n　　凤凰关进竹笼里啊，反叫鸡鸭翱翔舞翩翩。\n　　美玉沙石混在一起啊，一样看待不分贵和贱。\n　　想那小人鄙陋又愚顽啊，根本不知我心良善。\n　　我肩负重任责任大啊，陷入泥沼我不能起航向前。\n　　我怀揣美玉手握宝啊，无人知我不知给谁看。\n　　村犬成群乱狂吠啊，全因少见多怪无识见。\n　　诽谤俊士忌英贤啊，本是庸人的本性和习惯。\n　　我外表质朴心豁达啊，众人不知我出众的才干。\n　　成材原木堆一起啊，没人知我栋梁在里面。\n　　我重仁义不停地自修啊，忠厚朴实才感充实心里安。\n　　明君舜帝不再遇啊，有谁知道我雍容大方，气定神闲？\n　　贤臣不遇明君自古就有啊，这其中的缘故有谁了然？\n　　商汤、夏禹时代久远啊，千载悠悠，难慕难羡。\n　　止住恨啊不再怨，要坚强，自把苦水咽。\n　　遭受祸患不悔改啊，愿为后人做模范。\n　　向北赶路去投宿啊，夕阳沉沉将落山。\n　　把忧愁痛苦全忘掉吧，生命的尽头已不远。\n　　尾声：\n　　浩浩荡荡的沅水湘水啊，各自奔流涌向前。\n　　漫长的道路多险阻啊，它是那么渺茫遥远。\n　　我怀抱一颗忠心和真情啊，却孤独无依没人来相伴。\n　　相马的伯乐已经死去啊，纵有千里马又有谁来分辨？\n　　世上众人的命啊，各自的生死早注定。\n　　安下心来放宽怀啊，我又何必惧死恋生？\n　　诉不尽的忧伤止不住的悲哀啊，长吁短叹一声连一声。\n　　世道混浊无人了解我啊，人心难测，看不透啊说不清。\n　　我知道一死已不可免啊，那就不必再吝惜这残生。\n　　告诉你啊，以死守志的先贤，我将加入到你们的行列中。\n\n思美人\n　　怀念着我心爱的人啊，揩干眼泪而远望。\n　　没人介绍而路又迢遥，有话却无法成章。\n　　我至诚一片而蒙冤，我进退两难而不前。\n　　愿每日陈述我的心思，心思沉顿而难表现。\n　　愿浮云为我捎信，云师却不肯讲情。\n　　托鸿鸟为我传书，鸿高飞而不应命。\n　　我难比帝喾高辛，能遇凤凰而授卵。\n　　要变节而随流俗，我知耻而有所不敢。\n　　多年来我遭受摧残，毫不减我心中的愤懑。\n　　宁失意而长此终身，我何能如掌之易反？\n　　我明知正路难通，但我不能不走正路。\n　　尽管是车翻而马倒，我依然望着前途。\n　　我再把好马辔上，请造父为我执鞭。\n　　慢慢地走,不必驱驰，让我把光景流连。\n　　指着嶓冢山的西边,那汉水发源地点,\n　　就走到日落昏黄,也莫嫌道途遥远。\n　　我姑且等待明年，艳阳的春日绵绵。\n　　我要放怀地歌唱，逍遥在江水、夏水之边。\n　　我攀摘灌木中的苻蓠，我采集沙滩上的卷施。\n　　和古人可惜不能同时，摘来香草啊同谁赏识。\n　　采取萹薄与同蔬菜，尽可以纽成环佩。\n　　也未尝不好看一时，终萎谢而遭毁败。\n　　我姑且快乐逍遥，观赏南方人的异态。\n　　只求我心中快活，把愤懑置之度外。\n　　芳香与污秽杂混一起啊，芳花终会卓然自现。\n　　馥郁的芳香必然远扬，内部充实外表自有辉光。\n　　只要真诚的素质长保不亡，声名会突破一切的阻障。\n　　想请薜荔替我说合，又怕走路去攀上树枝。\n　　想采荷花替我媒介，又怕下水打湿了裙子。\n　　登高吧,我不高兴，下水吧,我也不能。\n　　固然是我手足不惯。\n　　我犹豫而心不能定。\n　　完全依照着旧贯，我始终不肯改变。\n　　命该受难我也不管，趁着这日子还未过完。\n　　一个人孤单地走向南边，只想追求彭咸的典范。\n\n惜往日\n　　痛想当年曾受君王的信任啊，受王命草宪令使政事清明。\n　　继承先王的功业恩惠百姓啊，修明法度的缺陷和漏洞。\n　　国家富强法度建起啊，忠臣理事君王安乐自轻松。\n　　国家机密大事放在心上啊，纵或有过错君王也宽容。\n　　我心地淳朴守口如瓶啊，于是遭到小人的嫉妒和围攻。\n　　君王从此对我含怒没笑脸啊，根本不把是非对错来澄清。\n　　小人蒙住君王的耳和眼啊，挑拨是非造谣生事把君王欺蒙。\n　　你不调查验证就信以为真啊，不加思考地就把我弃置不用。\n　　你听信小人的一派胡言乱语啊，怒气冲冲地指责我不义不忠。\n　　忠贞的臣子并无罪过啊，为什么反遭诽谤受指责？\n　　真是愧对天日啊，一片忠诚反蒙冤，我还是逃到幽暗之处躲一躲。\n　　面对着沅水湘水的深渊啊，强忍满腔悲愤自沉江河。\n　　终于身死名也灭啊，可惜昏君依然昏昏不理解。\n　　君王心无分寸又不明察啊，使芳草埋没在荒林草野。\n　　我向何处倾诉衷情陈说忠信啊，宁愿默默死去也决不偷生苟活！\n　　我孤独地被隔绝抛弃在荒漠啊，致使忠贞之臣啊无从尽忠报国。\n　　听说百里奚曾当过俘虏啊，伊尹也曾在厨房煮饭烧过火。\n　　吕望曾在朝歌做过屠夫啊，宁戚也曾半夜喂牛叩角而歌。\n　　如果不遇圣君汤武和桓缪啊，世上谁又知道他们才能卓绝？\n　　吴王听信谗言不知悔改啊，伍子胥死后终遭祸。\n　　介子推一片忠心抱树而死啊，晋文公醒悟后才去追寻搜索。\n　　改绵山为介山并封山禁伐啊，用来报答介子推的大恩大德。\n　　想起追随自己多年的故旧啊，便穿起白丧服痛哭不绝。\n　　有的人一片忠信守节而死啊，有的人欺蒙诈骗而高官得做。\n　　不去考察了解事实真相啊，只听信小人的一派信口胡说。\n　　鲜花的芬芳和美玉的光泽混合在一起啊，谁又能清清楚楚地把它们分别？\n　　为什么芳草这么早地凋零啊，只因薄霜已降而不知防戒。\n　　实在是君王昏昏受蒙蔽啊，让谗谀小人日益洋洋自得。\n　　小人妒贤自古就是这样啊，说什么不可佩的是蕙草杜若。\n　　嫉妒美人的风姿秀韵啊，丑女嫫母搔首弄姿自作风骚。\n　　纵使有西施般的美貌啊，制造流言斐语取代她的美好。\n　　我希望陈述真情表白心意啊，竟会获罪真是出乎意料。\n　　我的真情和冤枉日益清楚啊，就像众星在天空排列着。\n　　跨上骏马放开四蹄飞奔啊，却没有勒马的缰绳和铁嚼。\n　　乘上竹木筏顺流急下啊，却没有船桨任水飘。\n　　不遵法度单凭主观去治国啊，就像上面的譬喻一样危险一样糟。\n　　我宁愿早些死去被水飘走啊，我担心祸殃再一次来到。\n　　话没说完就投向深渊啊，可惜这一切君王不会知道。\n\n橘颂\n　　天地间生长着一种佳树，那是橘树，习服这一方水土。\n　　天生的习性不能移植，只生长在南国荆楚。\n　　根深坚牢难以迁徙，那是因为它心志专一。\n　　碧绿的叶子，洁白的花朵，缤纷一片令人心喜。\n　　枝条繁密刺儿尖利，挂满团团的橘实。\n　　绿中透出点点橘黄，色彩多么斑斓绚丽。\n　　鲜艳的外表，纯洁的内里，如同可担重任的贤人志士。\n　　枝繁叶茂，风姿美丽，美得真是无可挑剔。\n　　啊，你自幼的志气，就与众人殊异。\n　　你卓然独立从不变易，怎不令人可敬可喜！\n　　根深坚固难以迁徙，心胸坦荡别有希冀。\n　　你清醒地独立于世，宁愿绝水横渡也不随水流去。\n　　你断绝私欲谨慎自守，永不会犯错误。\n　　你坚守美德从无偏私，为人高尚可配天地。\n　　我愿与日月共生死，长结友谊不离不弃。\n　　至善至美而不过分，枝干坚直又有纹理。\n　　你虽然年纪轻轻，却可做人们的老师。\n　　你的德行可与伯夷相比，为人榜样，供人学习。\n\n悲回风\n　　悲哀啊，旋风撕卷着蕙草，我心郁结，我心忧伤。\n　　柔弱的蕙草易被摧残啊，秋风无形却能产生巨大影响。\n　　为什么彭咸令人长久思慕啊，他那高尚节操和志向令人难忘。\n　　千变万化岂能把真情掩盖啊，哪有虚伪能够保持久长？\n　　鸟兽鸣叫把同伴呼唤啊，鲜草靠近枯草堆就失去芬芳。\n　　鱼儿鼓鳞炫示自己与众不同啊，蛟龙潜入渊底把美丽的鳞甲隐藏。\n　　所以苦菜与甜菜从不种在一地啊，兰芷生在幽僻的深山才独具芳香。\n　　只有佳人才能永葆美好啊，虽历经百世也自善良。\n　　我的志向是那么远大啊，可惜就像白云飘浮在天上。\n　　我高远的志向不被理解啊，我只好赋诗一表我的衷肠。\n　　思想起我孤独幽怨的情怀啊，只好折枝杜若和椒枝独自守在这里。\n　　我止不住地一次次长吁短叹啊，人虽隐伏荒野可心头的思虑难息。\n　　我涕泪交流心悲凄啊，彻夜不眠愁思如缕。\n　　难挨的漫漫长夜终于熬过啊，可心头的悲哀依然长留不去。\n　　我还是起身去四处游荡吧，姑且逍遥一番自解愁绪。\n　　悲伤叹息可怜我的不幸啊，满怀的苦闷郁悒难解难舒。\n　　把我满心的愁思结成一条佩带啊，把我满怀的愁苦编为一件内衣。\n　　折一枝若木枝遮蔽阳光啊，任随旋风把我飘来荡去。\n　　眼前的一切模模糊糊看不清啊，我的心像开了锅翻腾不止。\n　　整一整衣裳稳一稳神啊，走吧，恍恍惚惚若有所失。\n　　岁月匆匆很快地流逝啊，我的生命也渐渐走到尽头。\n　　芳草枯萎茎折叶落啊，一片凋零香消芳收。\n　　可怜我的愁思永不止啊，我的这些表白也无济于事。\n　　我宁愿死去或永远漂泊啊，也不忍我的心永远这般愁苦。\n　　我孤儿般的呻吟着，擦着眼泪啊，我像被赶出家门的孤儿不得回去。\n　　谁能思想起这些而不心痛啊，我决心仿效先贤走彭咸的路。\n　　我登上高山向远处眺望啊，漫漫长路死一般的寂静。\n　　我走进这无影无声的寂寞世界啊，连看一看、听一听、想一想都不可能。\n　　这里只有无穷的愁苦没有一丝欢乐啊，满心是解不开、驱不散的愁绪苦情。\n　　我的心被束缚不得舒展啊，像被千万条绳索把它捆紧。\n　　辽阔无边四周一片寂静啊，莽苍苍空荡荡无像无形。\n　　秋声虽小可使草木感应啊，蕙草虽本性纯真却难抵秋风。\n　　世事茫茫不可预料啊，愁思不断缥缈绵长。\n　　愁满心怀常使我悲苦啊，在黑暗中飞舞也难欢畅。\n　　驾着波涛顺水漂流啊，投向彭咸居住的地方。\n　　我飞上高山峭壁啊，站在虹霓的顶端。\n　　我占据青空吐气成虹啊，突一挥手抚摸青天。\n　　我吸饮着清露串串啊，又含漱着洁白的霜花片片。\n　　我依在风穴旁闭目休息啊，陡然间翻身醒来又愁思绵绵。\n　　我背靠昆仑俯瞰云雾滚滚飞腾啊，我依凭岷山下视江水奔流直前。\n　　急流击石令人惊心啊，涛声不绝震响耳畔。\n　　乱纷纷江水横冲直撞啊，白茫茫江水汪洋一片。\n　　波涛滚滚不知流向哪里啊，弯弯曲曲流到何处才算完。\n　　浪涛翻滚忽上忽下啊，又或左或右翻腾在两边。\n　　江水波起浪涌忽前忽后啊，就像潮汐的涨落定时不变。\n　　看炎夏的热气一阵阵升腾啊，看水汽上升凝成为雨露云烟。\n　　悲叹啊，霜雪都飘落大地，潮水撞击的声音又传到耳边。\n　　我凭借着日光月影上下往来啊，我用弯曲的黄棘神木充做马鞭。\n　　我寻求介子推隐居过的居处啊，我发现了伯夷隐居的遗址首阳山。\n　　心里思忖我不再离开他们啊，抱定决心不再去别处的打算。\n　　尾声：\n　　我怨恨以往不识时务的追求啊，我痛惜后来无辜蒙受的惊惧。\n　　我愿随着江淮漂流入海啊，跟从伍子胥以满足自己的心意。\n　　我望见大河中的沙洲啊，悲哀地想起申徒狄的高行骨气。\n　　一次次规谏君王而不被听信啊，抱石自沉又将有何益？\n　　心头郁闷不舒畅啊，愁思百结难消释。▲', poem_appreciation = '《楚辞》篇名。包括9篇作品。依王逸《楚辞章句》的次序是：《惜诵》、《涉江》、《哀郢》、《抽思》、《怀沙》、《思美人》、《惜往日》、《桔颂》、《悲回风》。这9篇的作者，王逸都定为屈原。\n\n　　宋代洪兴祖则疑《思美人》、《惜往日》、《桔颂》、《悲回风》4篇非屈原作（《楚辞补注》）。明代许学夷也以《惜往日》、《悲回风》二篇非屈原口气，疑为唐勒、景差等人所作（《诗源辨体》）。清代顾成天则定《惜诵》、《惜往日》二篇为河、洛间人所作(《读骚别论》)。而近人还有说《哀郢》为庄辛所作的（钱穆《先秦诸子系年》）。但所有这些怀疑，多以文气为判定真伪的标准，尚无确凿有力的证据。\n\n　　关于《九章》名称的意思，王逸训“章”字为“著也，明也，言己所陈忠信之道甚著明也”，显系出于汉代经生陋说，不足为训；朱熹认为《九章》乃“后人辑之，得其九章，合为一卷”（《楚辞集注》），较为合理。至于辑录、题名者，或认为是刘向，或认为是淮南王幕府中的文学之士，尚无定论。\n\n　　关于《九章》各篇的写作时、地问题，王逸认为它们都是屈原流放于江南时所作；朱熹则认为“非必出于一时之言也”（《楚辞集注》）。细观《九章》各篇内容，朱说较符合作品实际。至于《九章》中各篇的具体写作时间及其排列次序，明代黄文焕，清代林云铭、蒋骥及现代楚辞学者各有考订，说法不一。\n\n　　《九章》各篇的思想内容，因并非出于一时一地，所以应当分别看待。其中：\n\n　　《惜诵》表现了诗人在政治上遭受打击后的愤懑心情，内容略与《离骚》前半篇相似。\n\n　　《涉江》似是自叙放逐江南的行迹，反映了诗人高洁的情操与黑暗混浊的现实生活的矛盾。\n\n　　《哀郢》一说作于庄□暴郢之后，一说作于白起破郢（前278）之后，抒写了诗人对破国亡家的哀思及对人民苦难的同情。\n\n　　《抽思》大概作于屈原被疏于汉北之时，抒发了诗人见疏于怀王之后的怫郁幽怨之情。\n\n　　《怀沙》为屈原自沉之前不久所作，一说为怀沙石沉江，一说为怀念长沙，其中着重叙写了诗人正道直行、不随世浮沉的节操以及准备以死来殉理想、殉信仰的决心。\n\n　　《思美人》反映了诗人思念其君而不能自达，但又不愿变心从俗的心情。\n\n　　《惜往日》有人认为是屈原的绝命词。概叙了诗人一生的政治遭遇，为因谗人破坏和国君昏庸使自己的理想不能实现而深感痛惜，也表示了必死的决心。\n\n　　《桔颂》一般认为是屈原早期的作品，通篇就桔的形象和特征作出拟人化的描写,可以看成是作者人格和个性的缩影。\n\n　　《悲回风》则流露了一种低徊缠绵的忧苦之情。\n\n　　《九章》各篇的艺术风格和成就，也不一律。其中《桔颂》一篇清新秀拔，别具一格，从辞赋的体裁上说，开了体物写志的先河。《哀郢》、《涉江》、《怀沙》三篇情景交融，诗味腴厚，在《楚辞》中允称上品。其写景之句如“山峻高以蔽日兮，下幽晦以多雨；霰雪纷其无垠兮,云霏霏而承宇”,宛然如画。抒情语句如“楫齐扬以容与兮，哀见君而不再得。望长楸而太息兮，涕淫淫其若霰”,恳挚缠绵,颇有回肠荡气之致。至于《惜往日》、《悲回风》二篇，艺术上较他篇略为逊色。《九章·桔颂》图清代门应兆作。', poem_tags = '楚辞,抒怀' WHERE poem_title = '九章' AND poem_author = '屈原';
UPDATE edu_poem SET poem_translation = '兰花生长在山岩的顶处，它的香气飘散四溢，在突出的岩石和岩缝中，美妙的花香浓郁芬芳。\n不是脚下没有浮云翻滚的喧闹，只是兰花不愿去理睬它们，不知道它们什么时候来到，更不会在它们离去时去挽留。', poem_notes = '顶：顶头\n突：高出周围\n稠：浓郁\n非：不是\n浮云：天上的云\n闹：喧哗', poem_tags = '咏物,写花,述志' WHERE poem_title = '题画兰' AND poem_author = '郑燮';
UPDATE edu_poem SET poem_translation = '周厉王暴虐，百姓纷纷指责他。召穆公对厉王说：“老百姓忍受不了暴政了！“厉王听了勃然大怒，找到卫国的巫师，让卫国的巫师去监视批评国王的人，按照卫国的巫师的报告，就杀掉批评国王的人。国人不敢说话，路上相见，以目示意。\n　　周厉王颇为得意，对召穆公说：“我能消除指责的言论，他们再也不敢吭声了!“\n　　召公回答说：“你这样做是堵住人们的嘴。阻塞老百姓的嘴，好比阻塞河水。河流如果堵塞后一旦再决堤，伤人一定很多，人民也是这样。因此治水的人疏通河道使它畅通，治民者只能开导他们而让人畅所欲言。所以君王处理政事，让三公九卿以至各级官吏进献讽喻诗，乐师进献民间乐曲，史官进献有借鉴意义的史籍，少师诵读箴言，盲人吟咏诗篇，有眸子而看不见的盲人诵读讽谏之言，掌管营建事务的百工纷纷进谏，平民则将自己的意见转达给君王，近侍之臣尽规劝之责，君王的同宗都能补其过失，察其是非，乐师和史官以歌曲、史籍加以谆谆教导，元老们再进一步修饰整理，然后由君王斟酌取舍，付之实施，这样，国家的政事得以实行而不违背道理。老百姓有口，就像大地有高山河流一样，社会的物资财富全靠它出产；又像高原和低地都有平坦肥沃的良田一样，人类的衣食物品全靠它产生。人们用嘴巴发表议论，政事的成败得失就能表露出来。人们以为好的就尽力实行，以为失误的就设法预防，这是增加衣食财富的途径啊。人们心中所想的通过嘴巴表达，他们考虑成熟以后，就自然流露出来，怎么可以堵呢？如果硬是堵住老百姓的嘴，那赞许的人还能有几个呢？“\n　　周厉王不听，在这种情况下老百姓再也不敢公开发表言论指斥他。过了三年，人们终于把这个暴君放逐到彘地去了。', poem_notes = '谤：指责，公开的批评。\n弭（mǐ）谤：消除议论。弭，消除。谤，公开批评指责别人的过失；谤言，这个词后来一般作贬义词。\n巫：古代以降神事鬼为职业的人。\n莫：没有谁。\n目：用眼睛看看，用作动词。表示敢怒不敢言。\n障：障碍。\n川壅(yōng)而溃：壅（yōng），堵塞。溃：水冲破堤坝。\n为川者决之使导:治水的人疏通河道使他畅通，为：治，决：挖开，排除，导：疏通。为川者：治水的人；决之使导，引水使它流通。\n宣之使言：治民者必宣导百姓，使之尽言。宣，放，开导。\n听政：治理国政。听，治理，处理。\n公卿：三公九卿。至于：以及。列士：上士，中士，下士。诗：指采集于民间的讽谏诗，不是指《诗经》。\n瞽(gǔ)献曲：盲人乐师向国王进献乐曲。瞽，无目，失明的人。\n史献书：史官向国王进献记载史实的书籍。\n师箴(zhēn)：少师进献规劝的文辞。箴规谏的文辞。\n瞍(sǒu)赋：无眸子的盲人吟咏（公卿烈士所献的诗）。瞍，没有眸子的盲人。赋，朗诵。\n曚诵：有眸子而看不见的盲人诵读（讽谏的文章）。曚，有眸子而看不见东西的人。\n百工：百官。\n庶人传语：百姓的意见间接传给国王。\n近臣尽规：常在左右的臣子，进献规谏的话。尽规：尽力规劝。\n亲戚补察：同族的亲属，弥补并监察国王的过失。\n耆(qí)、艾修之：国内元老大臣把这些规谏修饬整理。耆，六十岁的人。艾，五十岁的人。\n而后王斟酌焉：而后由国王仔细考虑，付之实行。\n是以事行而不悖(bèi）：国王的行事由此才不至于违背事理。悖，违背。事行，政事畅行，政令通行。而：转折连词，但是。\n于是乎出：从这里生产出来。于，从。 是，这。 乎，助词。\n犹其有原隰衍沃也 ：犹：如同，其，指代土地，原，宽阔。隰，地下而潮湿的土地。衍，地下而平坦的土地。沃，肥美得土地，就好比土地有原隰衍沃的一样。\n原：宽阔而平坦的土地。\n隰（xí）：低下而潮湿的土地。\n衍：低下而平坦的土地。\n沃：有河流灌溉的土地。\n口之宣言也，善败于是乎兴：由于百姓用口发表意见国家政治的好坏才能从中表现出来。\n宣言：发表议论。宣：宣泄，引导。善败， 治乱：于是，从这里面。兴：暴露出来。\n行善而备败，其所以阜(fù)财用衣食者也：这两句是说，凡是老百姓认为好的就做，反之就得加以防备， 这是增多衣食财物 的办法。.备：防备。\n所以，用来……的方法。其：副词，表示揣测，(这)大概(就是)。 所以：用来……的。阜，增加。使……丰富。意动用词。\n成：成熟。行，自然流露，自然表现。胡，怎么。\n其与能几何：能有什么帮助呢？这句是说，那赞同的人能有多少呢?其，代词，那。与，帮助，《战国策》说：“君不与胜者，而与不胜者。“\n乃流王于彘（zhì）：把国王放逐到彘地去。乃：终于，副词。流：流放，放逐。于：到，介词。.于是：从，从这里。彘：地名，在今山西省霍县境内。\n甚:比……更严重。超过。', poem_appreciation = '本篇在结构上与前篇《祭公谏征犬戎》完全相同，仍然是谏因、谏言、谏果的三段式。首尾叙事，中间记言，事略言详，记言为主，体现了《国语》的一般特点。但本文的开头结尾却仍有独到之处。\n\n　　文章开头，妙语传神。“厉王虐，国人谤王”，寥寥七字，胜于千言。一边是厉王虐，一边是国人谤。谤由虐起，事出必然，因果明了，壁垒分明，一开篇便展现给读者一对不可调和的矛盾。既引出召公苦谏的缘由，也为厉王的可悲下场埋下了伏笔。接下来厉王的一“怒”一“喜”，两个动词，如千钧之力，又将矛盾推向高潮，且把这位暴虐无道的昏君形象斧砍刀削得更加逼真。结尾是戛然而止，给读者留下很大的想象空间。开头“国人莫敢言，道路以目”，此语真乃神来之笔，厉王以为高压就可止谤，因而“大喜”，其实高压下的沉默，只是火山喷发前的死寂。结尾“王弗听，于是国人莫敢出言”，这是愤怒与反抗的岩浆在凝聚力量。终于火山喷发，国人暴动，厉王被逐，那该是何等壮观的场面，何其复杂的斗争。但作者全都略去，只写了“三年，乃流王于彘”，淡淡的七个字，对厉王是何等轻蔑，而留给后人的思考又是何等深刻!\n\n　　召公的谏词，前后都是比喻。前一个比喻，说明“防民之口”的害处；后一个比喻，说明“宣之于口”的好处。只有中间一段切入正题，以“天子听政”总领下文，从正面写了“宣之使言”的种种好处。从公卿列士，史、瞽、师、蒙，到百工庶人，广开言路，畅所欲言，而后经天子斟酌取舍，补察时政，就使政策、政令不背真理。如此，恰当生动的比喻与严肃认真的正题有机结合，夹和成文，笔意纵横，态度真诚，用心良苦。', poem_tags = '高中文言文' WHERE poem_title = '召公谏厉王弭谤' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '注释 莲花漏：一种状如莲花的铜制漏水计时器，相传为庐山僧惠远所造。 酴酥：即屠苏，酒名。 东君：春神。', poem_tags = '婉约,春节,抒情' WHERE poem_title = '玉楼春·己卯岁元日' AND poem_author = '毛滂';
UPDATE edu_poem SET poem_tags = '黄河,典故,讽刺' WHERE poem_title = '黄河' AND poem_author = '罗隐';
UPDATE edu_poem SET poem_translation = '当年有位洒脱狂放之人名叫李白，人称谪仙。\n看到他落笔，风雨为之感叹；看到他的诗，鬼神都为之感动哭泣。\n从此李白之名震动京师，以前的困顿失意自此一并扫除，并被玄宗召入朝廷任翰林；\n他那惊天地、泣鬼神的诗篇必将万古流传。\n他陪玄宗泛舟，一直到很晚，最后被皇帝赏赐锦袍。\n玄宗经常召见李白，李白颇受宠信。\n后来他因受奸人诬陷而被赐金放还，途中与我相遇。\n李白既没有隐藏自己的远大志向，又能在受宠和被放逐的不同境遇中自保。\n我与他相遇后，李白非常理解我的洒脱不羁，我也十分欣赏他的坦荡胸怀。\n我们夜里在梁园饮酒起舞，春季则在泗水纵情吟唱。\n虽然才华超群却无用武之地，虽然道德崇高却无人理解。\n虽然才智堪比东汉祢衡，但命运却如穷困失意的原宪。\n李白投靠永王肯定是生活所迫，有人传说他收了永王的重金，这实属造谣。\n但是他却因此被流放，长期漂泊。\n几年之间屡遭祸患，心中必然悲伤。\n苏武最终返回汉廷，夏黄公难道会为暴秦做事吗？\n遭受君主冷遇，李白也曾上书为自己辩护。\n如果当时事理难明，就让李白服罪，那么，现在谁又能将此事上报朝廷呢？\n晚年时，李白犹自吟诗不辍，希望他早日康复，多作好诗。\n不要埋怨皇帝寡恩，而要上书朝廷，了解事情的真相。', poem_notes = '狂客：指贺知章。贺知章是唐越州永兴人，晚年自号四明狂客。谪仙：被贬谪的神仙。贺知章第一次读李白诗时，如是赞道。\n“诗成”句：据《本事诗》记载，贺知章见了李白的《乌栖曲》，“叹赏苦吟曰：‘此诗可以泣么神矣。’”说明李白才华超绝，满朝为之倾倒。\n汩（gǔ）没：埋没。\n承殊渥（wò）：受到特别的恩惠。这里指唐玄宗召李白为供奉翰林。\n“龙舟”句：指唐玄宗泛白莲池，在饮宴高兴的时候召李白作序。“兽锦”句：《唐诗纪事》载：“武后游龙门，命群官赋诗，先成者赐以锦袍。左史东方虬诗成，拜赐。坐未安，之问诗后成，文理兼美，左右莫不称善，乃就夺锦袍衣之。”这里是说李白在皇家赛诗会上夺魁。\n“祢（mí）衡”句：才能像祢衡一样好。祢衡：东汉时人，少有才辩。孔融称赞他“淑质贞亮，英才卓跞”。“原宪”句：家境像原宪一样贫困。原宪：春秋时人，孔子弟子，家里十分贫穷。\n“薏苡”句：马援征交趾载薏苡种还，人谤之，以为明珠大贝。这里指当时一些人诬陷李白参与永王李璘谋反。\n三危：山名，在今甘肃敦煌县南，乃帝舜窜三苗之处。\n“几年”句：耽心李白处境危险。鵩（fú）鸟：古代认为是不祥之鸟。“独泣”句：叹道穷。\n楚筵（yán）辞醴（lǐ）：汉代穆生仕楚元王刘交为中大夫。穆生不喜欢饮酒，元王置酒，常为穆生设醴。元王死，子戊嗣位，初常设醴以待。后忘设醴。穆生说：“醴酒不设，王之意怠。”遂称病谢去。这里是指李白在永王璘邀请他参加幕府时辞官不受赏之事。李白在《经乱离后天恩流夜郎忆旧游书怀赠江夏韦太守良宰》诗中说：“半夜水军来，寻阳满旌旃。空名适自误，迫胁上楼船。徒赐五百金，弃之若浮烟。辞官不受赏，翻谪夜郎天。”“梁狱”句：汉代邹阳事梁孝王，被谗毁下狱。邹阳在狱中上书梁孝王，力辩自己遭受冤屈。后获释，并成为梁孝王的上客。这里是指李白因永王璘事坐系浔阳后力辩己冤。\n“老吟”二句：老病秋江，说明李白已遇赦还浔阳。\n槎（chá）：木筏。', poem_appreciation = '此诗旨在为李白晚年不幸的遭遇辩护申冤，并为他不平凡的一生写照。 王嗣奭说：“此诗分明为李白作传，其生平履历备矣。”卢世傕认为这是“天壤间维持公道，保护元气文字”（《杜诗详注》）。诗歌本身也是一篇“惊风雨”，“泣鬼神”的传世杰作。李白同辈排行第十二，所以称“李十二白”。\n\n　　此诗分三大段，一个结尾。第一段从“昔年有狂客”到“青云满后尘”，追述李白于公元730年（开元十八年）和742年（天宝元年）两入长安的经历，对李白的前半生作了高度的概括，同时，对李白诗歌的艺术成就进行了热情的赞颂。前六句记叙李白初游长安事。唐人孟棨《本事诗·高逸》记载：李白初至长安，贺知章“闻其名，首访之。既奇其姿，复请其为文。白出《蜀道难》以示之。读未竟，称叹者数四，号为谪仙。”书中还记载，贺知章读李白的《乌栖曲》后说：“此诗可以泣鬼神矣！”贺知章号“四明狂客”。诗人根据这些史实，赞扬李白妙笔生花，连风雨也为之感到惊叹，连鬼神也为之感动哭泣。李白经贺知章的宣扬，于是名震京师。汨没：埋没。三十年来默默无闻，此后就名满天下了。此诗一开头就显得笔锋突兀，气势不凡。非“狂客之誉”，无以彰“谪仙”之名。而“谪仙”这一美誉出自久负盛名的大诗人贺知章之口，更增加了它的份量。李白初出茅庐，一鸣惊人，恰如演员登台亮相，光彩照人，赢得满堂喝彩。“笔落惊风雨，诗成泣鬼神”这两句历来被人们看成是描写李白的佳句。诗人以高度夸张的手法，盛赞了李白诗歌强大的艺术魅力。落笔能惊动狂风暴雨，说明李白的诗歌气势磅礴；诗成能使鬼神哭泣，说明李白的诗歌感人肺腑。诗人用精妙的语言赞美了李白的旷世才华，而“诗仙”李白也确实有资格接受这一赞誉。从这里可以看出杜甫对李白的推崇和钦敬。\n\n　　后六句叙写李白二游长安事。“文彩”二句是说李白因擅长诗赋被玄宗召入京，供奉翰林；他那些无与伦比的诗篇必将流传千古。以下四句记叙的是李白供奉翰林期间的事。“龙舟”句见唐人范传正《李公新墓碑》：玄宗“泛白莲池，公不在宴，皇欢既洽，召公作序。时公已被酒于翰苑中，仍命高将军扶以登舟。”“兽锦”句见李白《温泉侍从归逢故人》：“激赏摇天笔，承恩赐御衣。”蔡梦弼《杜诗注》引《李白外传》云：“白作乐章赐锦袍。”李白常被召入宫中为皇帝草拟文告和乐章，因为身受宠待，一些文士慕名追随左右。这时李白意得志满，盛极一时，诗人亦不惜浓墨重彩，加以渲染。诗人通过对李白两入长安的描写，用极为洗炼的笔触就勾勒出一个风流倜傥、飘逸豪放的诗人形象。\n\n　　第二段从“乞归优诏许”到“诸生原宪贫”，追叙李白于公元744年（天宝三年）春被赐金放还后，南北漫游、潦倒落魄的情景，并回忆自己在与李白相识交往中建立起来的亲如兄弟的深厚感情。“乞归”句，这既是对李白的回护，也是对玄宗的隐讳。李白离京，实际上是遭到张垍、高力士等人的诽谤而被玄宗放逐的。李白离开长安后于这年夏天来到梁宋（今河南开封、商丘一带），与杜甫一见如故，情同手足。“未负幽栖志，兼全宠辱身”是说李白既没有辜负隐幽之志，又能在受宠被重用和遭谗被逐的不同境遇中善自保全自己。这仍是那种回护心情的继续。“剧谈怜野逸，嗜酒见天真”指两人相遇后，李白很能理解自己的“野逸”，即放达不羁，自己也很欣赏李白的“天真”即胸怀坦荡。“醉舞”句指李白的梁宋之游；“行歌”句指李白回到寓家之处山东兖州。这两句在时间上和空间上都是一次跳跃，李白从此开始南北漫游。接着四句，笔锋一转，专写李白怀才不遇。虽才华横溢，但宏图未展；仕途受挫，虽道德高尚却无人理解。虽如东汉文士祢衡一样才智卓群，但却难逃像孔子弟子原宪那样穷愁潦倒的命运。\n\n　　这一段，诗人巧妙地运用了多层对比的手法。首先，李白奉诏入京与赐金放还，通过“宠”与“辱”的对比，说明“乞归”出于被迫，暗讽“优诏许”的虚伪性。其次，才高而命蹇，空有祢衡之俊却难免原宪之贫，诗人通过这一对比控诉了人间的不平。第三，“醉舞”、“行歌”，似乎是一派欢乐气氛，但紧接着写李白的遭遇坎坷、穷愁潦倒，这又形成鲜明对比，原来那不过是苦中作乐。\n\n　　第三段从“稻粱求未足”到“谁将此义陈”，着重记述李白长流夜郎前后的经历，篇幅寄慨最深，为全篇重点。安史之乱起，李白求仕不得，报国无门，于公元756年（至德元年）秋隐居庐山。正值永王李璘奉玄宗诏节度江陵，率军东下，路过寻阳。李白心怀“扫胡尘”、“救河南”的愿望入了永王幕，却不自觉地卷入了肃宗和永王争权夺位的矛盾漩涡之中。次年一月，永王败死。李白入狱，继而长流夜郎（今贵州正安县）。“稻粱”二句，是说李白受聘不过是为生活所迫，有人说他得了永王的重赂，纯属诽谤。诗人极力将李白入永王幕的政治色彩冲淡，力图在为李白开脱。李白于公元757年（至德二年）冬开始流放，还没到夜郎，于公元759年（乾元二年）夏历三月在渝州遇赦，还憩江夏。因取道岳阳，南赴苍梧避祸。苍梧指湖南零陵、九疑山一带，其地与五岭接壤。“五岭”二句，因格律关系，将时序倒置。前一句指避祸苍梧，后一句指长流夜郎。“三危”，山名，在今甘肃敦煌县南，乃帝舜窜三苗之处。\n\n　　“几年遭鵩鸟”。西汉贾谊谪居长沙，屋中飞来鵩鸟（即鵩鸟），自认为交了恶运，忧郁而死。李白当时作《放后遇恩不沾》：“独弃长沙国，三年未许回。何时入宣室，更问贾生才？”自比贾生，诗人因此亦以贾生比之。李白卧病当涂以手稿付李阳冰时，作《古风·大雅久不作》压卷，诗中说：“我志在删述，垂辉映千春。希圣如有立，绝笔于获麟。”自比孔子，自伤道穷。“独泣向麒麟”，用的就是这句诗意。\n\n　　以上六句叙写李白晚年悲惨的遭遇和凄楚的心境。以下六句则是发议论，抒感慨，极力为李白鸣不平。借苏武终于归汉和夏黄公不事暴秦的故事，说明李白不会真心附逆。借穆生辞别楚王刘戊的故事，说明李白能够自重，永王也并未任用他。梁“狱”句，是说李白曾象邹阳那样上书为自己辩护。“已用”二句，是说如果当时因事理难明，李白服了流刑，那么，如今又有谁能够将这些道理去向朝廷陈述呢？一个反问句，把无人仗义执言的感慨表达得深沉幽怒。\n\n　　而这一段，因为涉及极为敏感的政治问题和微妙的皇室矛盾，须委婉含蓄，故在十二句中有七句用典。本来，诗不贵用事，以防晦涩板滞。但“若能自出己意，借事以相发明，变态错出，则用事虽多，亦何所妨！”（《诗人玉屑》）“薏苡”句，是借题发挥。“几年”二句，是以事比人。“苏武”二句，是以人喻事（“元还汉”是正写，“不事秦”是反说）。“楚筵”句，以彼事喻此事；“梁狱”句，借前人譬今人。这一连串的用典，准确贴切。所以后人评曰：“诗家使事难，若子美，所谓不为事使者也。”（《察宽夫诗话》）最后四句是结束语。诗人称赞李白在垂老之年，仍吟咏不辍，祝愿他早日“病起”，为人间多作好诗。劝李白不要抱怨没有得到皇帝的恩泽，表示自己要设法向朝廷探明究竟。这是在无可奈何中的安慰之词，让老朋友在困境中感到一点人间的温暖。\n\n　　此诗对仗工稳，辞藻富丽，用典精当。在杜甫的一百二十多首五言排律中，此诗无论在思想性和艺术性方面，均不失为上乘之作。', poem_tags = '赞颂,写人,友情' WHERE poem_title = '寄李十二白二十韵' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '两湖江浙紧接壤，河道纵横水为乡。您去正值春江满，烟云弥漫水茫茫。\n暮色深沉天已晚，孤舟一叶停何方？心随友人望天涯，无限思念痛断肠。', poem_notes = '杜十四：杜晃，排行十四。之：去，到。\n荆吴：荆是古代楚国的别名，在今湖北、湖南一带。吴也是古代国名，在今江苏、安徽、浙江一带。荆吴在这里泛指江南。为：一作“连”。\n春江：一作“江村”。淼茫：即渺茫。\n何处泊：一作“何处泊”。\n天涯：犹天边。指极远的地方。', poem_appreciation = '这是一首送别诗。揆之元杨载《诗法家数》：“凡送人多托酒以将意，写一时之景以兴怀，寓相勉之词以致意”，如果说这是送别诗常见的写法，那么，相形之下，孟浩然这首诗就显得颇为出格了。\n\n　　诗题一作“送杜晃进士之东吴”。唐时所谓“进士”，实后世所谓举子（举进士）。得第者则称“前进士”。可见杜晃此去东吴，是落魄的。\n\n　　诗开篇就是“荆吴相接水为乡”，既未点题意，也不言别情，全是送者对行人一种宽解安慰的语气。以“荆吴相接”几个字将千里之遥写得近如比邻，给人以比邻咫尺之感，恰似说“天涯若比邻”，“谁道沧江吴楚分”。说两地，实际已暗关送别之事。但先作宽慰，超乎送别诗常法，却别具生活情味：落魄远游的人是最需要精神上的支持与鼓励的。这里就有劝杜晃放开眼量的意思。长江中下游地区，素称水乡。不说“水乡”而说“水为乡”，意味隽永：以水为乡的荆吴人对飘泊生活习以为常，不以暂离为憾事。“水为乡”描出江南特点，也有以水为家之意。语属宽解，情实至深。这样说来虽含“扁舟暂来去”意，却又不著一字，造语洗炼、含蓄。此句初读似信口而出的常语，细咀其味无穷。若作“荆吴相接为水乡”，则诗味顿时“死于句下”。\n\n　　“君去春江正淼茫”。此承“水为乡“说到正题上来，话仍平淡。“君去”是眼前事，“春江正淼茫”是眼前景，写来几乎不用费心思。但这寻常之事与寻常之景联系在一起，又产生一种味外之味。“春江淼茫”，春江水满，正好行船，含有祝友人一帆风顺之意，但“淼茫”二字又透出凄惘之情。“淼茫”一词包含着复杂的情感，从字面上来看它是描写眼前景：春江上烟波浩淼，雨雾蒙蒙，其实是写诗人心中的茫然，写出诗人送别友人时的怅然若失。既有喜“君去”得航行之便，也有恨“君去”太疾之意，景中有情在，让读者自去体味。这就是“素处以默，妙机其微”（司空图《诗品·冲淡》）了。\n\n　　“日暮征帆何处泊”，撇景入情。朋友刚才出发，便想到“日暮征帆何处泊”，联系上句，这一问来得十分自然。春江渺茫与征帆一片，形成一个强烈对比。阔大者愈见阔大，渺小者愈见渺小。由景入情，抒发别绪。写出友人的孤单寂寞。友人走后，诗人遥望江面，但见“日暮孤帆”，航行在渺茫春江之上，于是代人设想，船停何处？投宿何方？通过渺茫春江与孤舟一叶的强烈对照，发出深情一问，对朋友的关切和依恋在这一问中表达得淋漓尽致。同时，揣度行踪，可见送者的心追逐友人东去，又表现出一片依依惜别之情。这一问实在是情至之文。\n\n　　“天涯一望断人肠”，诗人遥望渐行渐远的行舟，送行者放眼天涯，极视无见，不禁情如春江，汹涌澎湃。“断人肠”将别情推向高潮，在高潮中结束全诗，离愁别恨，悠然不尽。“断人肠”点明别情，却并不伤于尽露，可谓“不胜歧路之泣”（蒋仲舒评）。原因在于前三句已将此情孕育充分，结句点破，恰如水库开闸，感情的洪流一涌而出，源源不断。若无前三句的蓄势，就达不到这样持久动人的效果。\n\n　　此诗前三句全出以送者口吻，“其淡如水，其味弥长”，已经具有诗人风神散朗的自我形象。末句“天涯一望”四字，更勾画出“解缆君已遥，望君犹伫立”（王维《齐州送祖三》）的送者情态，十分生动。读者在这里看到的，与其“说是孟浩然的诗，倒不如说是诗的孟浩然，更为准确”（闻一多《唐诗杂论》）。\n\n　　此诗用散行句式，如行云流水，近歌行体，写得颇富神韵，不独在谋篇造语上出格，自然流畅地表现了诗人对友人杜晃的深切怀念，也体现出诗人与友人杜晃之间的真挚友谊。诗中四句从写景入笔，寓主观感情于客观景象之中，使客观的景象染上浓重的主观感情的色彩。', poem_tags = '离别' WHERE poem_title = '送杜十四之江南 / 送杜晃进士之东吴' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '望着你的小船驶向茫茫云水，频频挥手惜别泪水沾湿佩巾。\n你像一只飞鸟不知归宿何处，留下这一片青山空对着行人。\n江水浩浩一叶孤帆远远消失，落日下你将欣赏着五湖之美。\n谁能见我伫立汀洲上怀念你，望着白蘋心中充满无限愁情。', poem_notes = '饯别：设酒食送行。王十一：名不详，排行十一。\n烟水：茫茫的水面。\n飞鸟：比喻远行的人。没何处：侧写作者仍在凝望。没：消失。\n空向人：枉向人，意思是徒增相思。\n落日：指王十一到南方后，当可看到夕照下的五湖春色。五湖：这里指太湖。此句与下面“谁见”两句均出自梁朝柳恽《江南曲》：“汀洲采白蘋，落日江南春。洞庭有归客，潇湘逢故人。故人何不返，春花复应晚。不道新知乐，只言行路远。”\n汀（tīng）洲：水边或水中平地。\n白蘋（pín）：水中浮草，花白色，故名。', poem_appreciation = '这是首送别诗，写与友人离别时的情景。友人已乘舟向烟水迷蒙的远方驶去，但诗人还在向他洒泪挥手送别。渐渐地，看不见友人的旅舟了，江面上鸟在飞着，不知它们要飞往何处；远处只有青山默默地对着诗人。朋友乘坐的船儿沿长江向远处去了，诗人在斜阳里伫立，想象着友人即将游五湖的情景。就这样离别了，不知有谁知道诗人对朋友的悠悠相思。诗人借助眼前景物，通过遥望和凝思，来表达离愁别恨，手法新颖，不落俗套。\n\n　　诗题虽是“饯别”，但诗中看不到饯别的场面，甚至一句离别的话语也没有提及。诗一开始，他的朋友王十一（此人名字爵不详）已经登舟远去，小船行驶在浩渺的长江之中。诗人远望着烟水空茫的江面，频频挥手，表达自己依依之情。此时，江岸上只留下诗人自己。友人此刻又如何，读者已无从知道，但从诗人送别的举动，却可想象到江心小舟友人惜别的情景。笔墨集中凝炼，构思巧妙。诗人以“望”、“挥手”、“泪沾巾”这一系列动作，浓墨渲染了自己送别友人时的心情。他没有直抒心中所想，而是借送别处长江两岸的壮阔景物入诗，用一个“望”字，把眼前物和心中情融为一体，让江中烟水、岸边青山、天上飞鸟都来烘托自己的惆怅心情。　\n\n　　第三句是虚实结合，诗中“飞鸟”隐喻友人的南游，写出了友人的远行难以预料，倾注了自己的关切和忧虑。“没”字，暗扣“望”。“何处”则点明凝神远眺的诗人，目光久久地追随着远去的友人，愁思绵绵，不绝如缕。真诚的友情不同于一般的客套，它不在当面应酬，而在别后思念。诗人对朋友的一片真情，正集聚在这别后的独自久久凝望上。这使人联想到《三国演义》描写刘备与徐庶分别时的情景。\n\n　　然而，目力所及总是有限的。朋友远去了，再也望不到了。别后更谁相伴？只见一带青山如黛，依依向人。一个“空”字，不只点出了诗人远望朋友渐行渐远直至消失的情景，同时烘托出诗人此时空虚寂寞的心境。回曲跌宕之中，见出诗人借景抒情的功力。\n\n　　五六两句，从字面上看，似乎只是交代了朋友远行的起止：友人的一叶风帆沿江南去，渐渐远行，抵达五湖（当指太湖）畔后休止。然而，诗句所包含的意境却不止于此。友人的行舟消逝在长江尽头，肉眼是看不到了，但是诗人的心却追随友人远去一直伴送他到达目的地。在诗人的想象中，他的朋友正在夕阳灿照的太湖畔观赏明媚的春色。\n\n　　诗的最后，又从恍惚的神思中折回到送别的现场来。诗人站在汀洲之上，对着秋水苹花出神，久久不忍归去，心中充满着无限愁思。情景交融，首尾相应，离思深情，悠然不尽。', poem_tags = '唐诗三百首,送别,友情' WHERE poem_title = '饯别王十一南游' AND poem_author = '刘长卿';
UPDATE edu_poem SET poem_translation = '一弯月牙照人间，多少人家欢乐，多少人家忧愁。\n有多少人家能夫妻团聚，享受天伦之乐；又有多少人家无依无靠，四处飘零？', poem_notes = '九州：指中国。此处借指人间。', poem_appreciation = '这首歌揭露南宋统治阶级在外族入侵时，对外实行不抵抗主义，对内残酷压迫人民，偏安江南，过着骄奢淫逸的生活，使老百姓饱受离乱之苦。月亮照耀着中华大地，同在一片蓝天下，有的家庭欢乐生活，而广大人民愁容满面，过着衣不遮体食不饱腹的苦日子。\n\n　　诗人从月照人间写起，月亮的阴晴圆缺好像是同人间的悲欢离合连在一起，因为将自然现象的变化同人事联系在一起，是古人的一种心理倾向。但是诗人否定了这种看法，认为人间的忧伤和痛苦是由人自己导致的，同月亮的变化没有任何干系，要摆脱这些烦扰人心的事，还要善于宽容。诗人非常积极地看待人生的欢乐喜忧，认为只有把自己的心态放宽，才会有磊落豁达的人生境界。', poem_tags = '古诗三百首,感叹,生活' WHERE poem_title = '月儿弯弯照九州' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '上百次的征战使壮士疲劳、士气低落，中原之战的失败之势再难挽回。\n虽然江东子弟现在仍在，但他们是否还愿意跟楚霸王卷土重来？', poem_notes = '乌江亭：故址在今安徽和县乌江镇，为项羽兵败自刎之处。\n壮士：指项羽。\n中原一败：括项羽垓下之败。\n江东：指长江下游芜湖、南京以下的江南地区，是项羽起兵之地。\n肯：岂肯，怎愿。卷土来：即卷土重来。指失败之后，整顿以求再起。', poem_appreciation = '杜牧在他的《题乌江亭》中写到：“ 胜败兵家事不期， 包羞忍耻是男儿。江东子弟多才俊， 卷土重来未可知。”意思是批评项羽胸襟不够宽广，如果项羽能够再回江东重整旗鼓的话，说不定还可以卷土重来。而王安石则根据自己的理解，认为项羽的失败已成定局，即便是江东子弟还在，项羽也不可能再带领江东子弟卷土重来，以为他们不一定再肯为战争卖命了。\n\n　　诗歌开篇就以史实扣题，针对项羽的失败直接指出“势难回”。楚霸王的转折点在“鸿门宴”，没能杀成刘邦，到“垓下之围”时已经面临着众叛亲离的境地。而细数项羽失败的原因，最大的因素恐怕就是他自身的刚愎自用了吧。所以文章“壮士哀”就隐含着这样的信息，那时的项羽已经失去人心，天时、地利、人和中，人和是最重要的因素，而项羽已经失去，要挽回大业是十分艰难，概率也是很低的。\n\n　　所以，王安石在三、四两句中进一步阐释“江东子弟今虽在，肯为君王卷土来”，他以辛辣的口吻明确地表示，即使项羽真的重返江东，江东子弟是不会替他卖力的。杜、王的观点不同是因为他们的出发点和立场不同。杜牧着眼于宣扬不怕失败的精神，是借题发挥，是诗人咏史；王安石则审时度势，指出项羽败局已定，势难挽回，反驳了杜牧的论点，是政治家的咏史。诗中最后的反问道出了历史的残酷与人心向背的变幻莫测，也体现出王安石独到的政治眼光。\n\n　　如果说杜牧是为项羽翻案，那么王安石则是为历史本身翻案，人与历史的关系本来就是“顺之则昌，逆之则亡”。这首诗中，作为北宋著名政治家，王安石将变法中的革新精神带到咏史诗的创作中，表达自己的政治观点，对前人提出质疑，这也是一种创新。这种史论史评是王安石完成咏史诗从叙事体向抒情体，最终走向议论体的转变，对当时的诗文革新运动起了推动作用。 王安石则属意史论史评，延伸了咏史诗的内容深度，有着独到的政治见解。\n\n　　王安石的诗，十分辛辣冷峻，但却抓住了人心向背是胜败的关键这个根本，可以说是一针见血。', poem_tags = '古诗三百首,咏史' WHERE poem_title = '叠题乌江亭' AND poem_author = '王安石';
UPDATE edu_poem SET poem_translation = '荷叶倾倒展现出新绿之色，陈旧的红色榴巾满是褶皱。水中的亭子，朦胧的水榭都在傍晚的凉风中。天上又是一弯新月，静静地照着窗栊。\n莲藕洁白如雪，橱柜的纱窗细薄得犹如不存在。这样美好的夜晚和谁一起维持呢，最好是唤来美子一同沐浴在一帘春风里。', poem_notes = '荷盖：即荷叶。\n新绿：指初春草木显现的嫩绿色。\n榭：建在高台上的房屋。\n栊：窗户的框格，窗栊。', poem_tags = '写景,月夜,抒情' WHERE poem_title = '南歌子·荷盖倾新绿' AND poem_author = '程垓';
UPDATE edu_poem SET poem_tags = '豪放,典故,祝寿' WHERE poem_title = '水龙吟·甲辰岁寿韩南涧尚书' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '初春的早晨在藤床纸帐这样清雅的环境中醒来，却有一种说不尽的伤感与思念。此时室内唯有时断时续的香烟以及香烟灭了的玉炉相伴，我的情绪如水一样凄凉孤寂。《梅花三弄》的笛曲吹开了枝头的梅花，春天虽然来临了，却引起了我无限的幽恨。\n门外细雨潇潇下个不停，门内伊人枯坐，泪下千行。明诚既逝，人去楼空，纵有梅花好景，又有谁与自己倚阑同赏呢 ？今天折下梅花，找遍人间天上，四处茫茫，没有一人可供寄赠。', poem_notes = '孤雁儿：《孤雁儿》原名《御街行》。《古今词话》无名氏《御街行》词有“听孤雁声嘹唳”句，故更名《孤雁儿》。\n藤床：藤条编织的床。纸帐：茧纸做的帐子。\n佳思：好心情。\n沉香：薰香的一种。玉炉：玉制的香炉或是香炉的代称。\n三弄：即“梅花三弄”，古代笛由名，或称“梅花引”。\n梅心惊破：指梅花闻笛而心伤。\n春情意：喻指当年夫妻情深。\n萧萧地：淅淅沥沥。地，语助词。\n吹箫人去：《列仙传》：“萧史者，秦穆公时人也，善吹箫，能致孔雀、白鹤于庭。穆公有女字弄玉，好之。公遂以女妻焉。”此言其夫赵明诚之去世。\n肠断：这里形容因丧夫而悲伤之极。《世说新语·黜免》：“桓公入蜀，至三峡中，部伍中有得猿子者，其母缘岸哀号，行百馀里，不去，遂跳上船，至便即绝。破视其腹中，肠皆寸寸断。”\n一枝折得三句：化用陆凯《赠范晔》诗意。折梅相送，丈夫故去，所以说没人堪寄。', poem_appreciation = '“藤床纸帐朝眠起，说不尽，无佳思。”开门见山，倾诉寡居之苦。藤床，乃今之藤躺椅。据明高濂《遵生八笺》记载，藤制，上有倚圈靠背，后有活动撑脚，便于调节高低。纸帐，亦名梅花纸帐。据宋林洪《山家清供》云，其上作大方形帐顶，四周用细白布制成帐罩，中置布单、楮衾、菊枕、蒲褥。宋人词作中，这种陈设大都表现凄凉慵怠情景。朱敦儒《念奴娇》云：“照我藤床凉似水。”意境相似，写一榻横陈，日高方起，心情孤寂无聊“沉香断续玉炉寒”，使人想起词人《醉花阴》中的“瑞胸销金兽”。然而这一“寒”字，更突出了环境的凄冷与心境之痛苦。此时室内唯有时断时续的香烟以及香烟灭了的玉炉相伴。“伴我情怀如水”一句，把悲苦之情变成具体可感的形象。', poem_tags = '咏物,梅花,悼亡' WHERE poem_title = '孤雁儿·藤床纸帐朝眠起' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '买到池塘，在岸边栽上杨柳，看上去好似淮岸江边，风光极为秀美。刚下过雨，鹭、鸥在池塘中间的沙洲上聚集，很是好看。而最好看的是一川溪水映着明月，点点银光照着水上沙洲。四周无人，翩然独舞，自斟自饮。头上是浓绿的树幕，脚底有如茵的柔草，酒喝光了还不忍离开。\n不要留恋过去的仕宦生涯，读书做官是耽误了自己。自己也曾做过地方官，但仍一事无成，反而因做官而使田园荒芜。您不妨看看，从镜子里可发现鬓发已经白了不少。所谓“功名”，不过是一句空话。连班超那样立功于万里之外，被封为定远侯，但归故乡时已经年岁老大，也是太晚了。', poem_notes = '摸鱼儿：本为唐教坊曲，后用为词牌。又名“摸鱼子”。双调一百一十六字，前片六仄韵，后片七仄韵。东皋：即东山。作者在贬谪后退居故乡时，曾修葺了东山的归来园。寓居：寄居。\n陂（bēi）塘：池塘。\n旋：很快，不久。\n依稀：好像是。\n嘉雨：一场好雨。\n沙觜（zuǐ）：即沙嘴，突出在水中的沙洲。觜，同“嘴”。\n渚（zhǔ）：水中的小洲（岛）。\n翠幄（wò）：绿色的帐幕，指池岸边的垂柳。\n柔茵：柔软的褥子。这里指草地。藉：铺垫。\n青绫被：汉代制度规定，尚书郎值夜班，官供新青缣白绫被或锦被。这里用来代表做官时的物质享受。\n金闺：汉朝宫门的名称，又叫金马门，是学士们著作和草拟文稿的地方。这里泛指朝廷。晁补之曾做过校书郎、著作佐郎这样的官。\n儒冠：指读书人。\n弓刀千骑（jì）：指地方官手下佩带武器的卫队。\n邵平瓜圃：邵平是秦时人，曾被封为东陵侯。秦亡，在长安城东种瓜，瓜有五色，味很甜美。世称东陵瓜。\n觑（qù）：细看，细观。\n青镜：青铜镜。古代镜子多用青铜制成，故称青镜。\n星星：指头发花白的样子。如许：这么多。\n浪语：空话，废话。\n班超：东汉名将，在西域三十余年，七十余岁才回到京都洛阳，不久即去世。\n迟暮：晚年，此指归来已晚。', poem_appreciation = '这首《摸鱼儿》，是晁补之的代表作。此词不仅描写了东山“归去来园”的园中景色，还叹恨自己为功名而耽误了隐居生涯。其主旨是表示对官场生活的厌弃，对美好的田园生活的向往。\n\n　　上片写景，描绘出一幅冲淡平和，闲适宁静的风景画，表现了归隐的乐趣：陂塘杨柳，野趣天成，仿佛淮水两岸，湘江之滨的青山绿水。东皋新雨，草木葱茏，山间溪水的涨痕清晰可辨，沙州上聚集着白鹭、鸥鸟，一片静穆明净的景色。然而最令人神往的，莫过于满山明月映照着溪流，将那一川溪水与点点沙洲裹上了一层银装。以“一川”形容夜月，可见月色朗洁，清辉遍照。“光流渚”三字则将宁谧的月色写得流动活跃，水与月浑然一体，那滔滔汩汩流动着的，难以辩识那是溪水还是月光：完全是一幅动静谐和的山中月夜图。面对着此景，词人翩然起舞。池塘四周，绿草如茵，偌大的世界好像只剩下他一个人，他尽情地领略这池塘月色，酒尽了还不忍离开。词之上片，寓情于景，表现了归隐的乐趣。绘色绘影的描写中，可见到作者“诗传画外意，贵有画中态”的高超艺术表现力。词中用了由大及细，由抽象到具体的写法，先说园内景色如淮岸湘浦，是大处落墨，总述全貌；接着写雨至水涨，鸥鹭悠闲，是水边常见景物，但已见其明丽清幽；最后以“堪爱处”、“最好是”引出野居幽栖的最佳景象。\n\n　　下片即景抒情，以议论出之，表现了厌弃官场、激流勇退的情怀。词人直陈胸臆，以为作官拘束，不值得留恋，儒冠误身，功名亦难久恃，这一句是从杜甫《奉赠韦左丞丈》“儒冠多误身”句化出。他深感今是昨非，对自己曾跻身官场、虚掷时日表示后悔。词人开函对镜，已是白发种种，益见功名如过眼云烟，终为泡影。末句说显赫如班超，也只能长期身居西域，到了暮年才得还乡。作者通过此句来表现厌弃官场、激流勇退的情怀。\n\n　　作者对于“功名浪语”“儒冠曾把身误”，有着切身的感受，并非一般的激愤之词。所以，是不能把这首词简单地归结为“有强烈的消极退隐思想”之列的。\n\n　　此词一反传统词家所谓“词须宛转绵丽”的常规，慷慨磊落，直抒胸臆，辞气充沛，感情爽豁，词境开阔，颇富豁达清旷的情趣，与作者的恩师苏东坡在词风上一脉相承，并对辛弃疾的词作产生了重要影响。', poem_tags = '宋词三百首,写景,田园,抒怀' WHERE poem_title = '摸鱼儿·东皋寓居' AND poem_author = '晁补之';
UPDATE edu_poem SET poem_translation = '不管是天北还是天南，小草总是长满路边，它连绵不断地向远处生长，处处都能够扎根繁衍。\n茂盛的春草总是催人早日归家，春风吹绿小草又是一年。', poem_notes = '托：依赖。\n萋萋：草长得茂盛的样子。“春草生兮萋萋”，“山中兮不可久留”。春草催人归家，所以称之为“无情物”。', poem_tags = '春天,写草,思归' WHERE poem_title = '春草' AND poem_author = '唐彦谦';
UPDATE edu_poem SET poem_translation = '先主刘备英雄气概充满天地，千秋万代一直令人肃然起敬。\n建国与吴魏三分天下成鼎足，恢复五铢钱币志在汉室振兴。\n拜诸葛亮为丞相开创了国基，可惜生个儿子不像其父贤明。\n最凄惨的是那蜀宫中的歌伎，在魏宫歌舞刘禅也毫无羞情。', poem_notes = '诗题下原有注：“汉末谣，黄牛白腹，五铢当复。”\n天地英雄：一作“天下英雄”。《三国志·蜀志·先主传》：曹操曾对刘备说：“天下英雄，唯使君与操耳”。\n“势分”句：指刘备创立蜀汉，与魏、吴三分天下。\n五铢钱：汉武帝时的货币。此代指刘汉帝业。“业复”句：王莽代汉时，曾废五铢钱，至光武帝时，又从马援奏重铸，天下称便。这里以光武帝恢复五铢钱，比喻刘备想复兴汉室。\n相：此指诸葛亮。\n不象贤：此言刘备之子刘禅不肖，不能守业。\n“凄凉”两句：刘禅降魏后，东迁洛阳，被命为安乐县公。魏太尉司马昭在宴会中使蜀国的女乐表演歌舞，旁人见了都为刘禅感慨，独刘禅“喜笑自若”，乐不思蜀（《三国志·蜀志·后主传》裴注引《汉晋春秋》）。妓：女乐，实际也是俘虏。', poem_appreciation = '《蜀先主庙》是刘禹锡五律中传诵较广的一首。这首咏史之作立意在赞誉英雄，鄙薄庸碌。\n\n　　首联“天地英雄气，千秋尚凛然”，高唱入云，突兀挺拔。细品诗意，其妙有三：一、境界雄阔奇绝。“天地”两字囊括宇宙，极言“英雄气”之充塞六合，至大无垠；“千秋”两字贯串古今，极写“英雄气”之万古长存，永垂不朽。遣词结言，又显示出诗人吞吐日月、俯仰古今之胸臆。二、使事无迹。“天地英雄”四字暗用曹操对刘备语：“今天下英雄，惟使君与操耳”（《三国志·蜀志·先主传》）。刘禹锡仅添一“气”字，便有庙堂气象，所以纪昀说：“起二句确是先主庙，妙似不用事者。”三、意在言外。“尚凛然”三字虽然只是抒写一种感受，但诗人面对先主塑像，肃然起敬的神态隐然可见；其中“尚”字用得极妙，先主庙堂尚且威势逼人，则其生前叱咤风云的英雄气概，自不待言了。\n\n　　颔联紧承“英雄气”三字，引出刘备的英雄业绩：“势分三足鼎，业复五铢钱。”刘备起自微细，在汉末乱世之中，转战南北，几经颠扑，才形成了与曹操、孙权三分天下之势，实在是得之不易。建立蜀国以后，他又力图进取中原，统一中国，这更显示了英雄之志。“五铢钱”是公元前118年（汉武帝元狩五年）铸行的一种钱币，后来王莽代汉时将它罢废。东汉初年，光武帝刘秀又恢复了五铢钱。此诗题下诗人自注：“汉末童谣：‘黄牛白腹，五铢当复’。”这是借钱币为说，暗喻刘备振兴汉室的勃勃雄心。这一联的对仗难度比较大。“势分三足鼎”，化用孙楚《为石仲容与孙皓书》中语：“自谓三分鼎足之势，可与泰山共相终始。”“业复五铢钱”纯用民谣中语。两句典出殊门，互不相关，可是对应自成巧思，浑然天成。\n\n　　如果说，颔联主要是颂扬刘备的功业，那么，颈联进一步指出刘备功业之不能卒成，为之叹惜。“得相能开国”，是说刘备三顾茅庐，得诸葛亮辅佐，建立了蜀国；“生儿不象贤”，则说后主刘禅不能效法先人贤德，狎近小人，愚昧昏聩，致使蜀国的基业被他葬送。创业难，守成更难，刘禹锡认为这是一个深刻的历史教训，所以特意加以指出。这一联用刘备的长于任贤择相，与他的短于教子、致使嗣子不肖相对比，正反相形，具有词意颉颃、声情顿挫之妙。五律的颈联最忌与颔联措意雷同。此诗颔联咏功业，颈联说人事，转接之间，富于变化；且颔联承上，颈联启下，脉络相当清晰。\n\n　　尾联感叹后主的不肖。刘禅降魏后，被迁到洛阳，封为安乐县公。一天，“司马文王（昭）与禅宴，为之作故蜀伎。旁人皆为之感怆，而禅喜笑自若。”（《三国志·蜀志·后主传》裴注引《汉晋春秋》）尾联两句当化用此意。刘禅不惜先业、麻木不仁至此，足见他落得国灭身俘的严重后果决非偶然。字里行间，渗透着对于刘备身后事业消亡的无限嗟叹之情。\n\n　　从全诗的构思来看，前四句写盛德，后四句写业衰，在鲜明的盛衰对比中，道出了古今兴亡的一个深刻教训。诗人咏史怀古，其着眼点当然还在于当世。唐王朝有过开元盛世，但到了刘禹锡所处的时代，已经日薄西山，国势日益衰颓。然而执政者仍然那样昏庸荒唐，甚至一再打击迫害像刘禹锡那样的革新者。这使人感慨万千。全诗措词精警凝炼，沉着超迈，并以形象的感染力，垂戒无穷。这也许就是它千百年来一直传诵不息的原因。', poem_tags = '唐诗三百首,咏史怀古' WHERE poem_title = '蜀先主庙' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_appreciation = '这是一首汉乐府民歌，它书写了大唐平定天下，开创贞观之治后太宗皇帝的感慨。全诗没有具体描写两军作战的场面，而是形象地描述了这场战争的发生发展与胜利的过程，是一首描写当时现实事件的史诗。\n\n　　“塞外悲风切，交河冰已结。”切，凄切。交河，北方河名。句意为：塞外，寒风悲鸣，十分凄切，交河上，严冰封冻了河道。据《旧唐书·太宗本纪》所载，太宗平定宋金刚之乱时，于“（武德）二年十一月，太宗率众趣龙门关，履冰而渡之”，可见诗中所描写的悲壮之景当是诗人亲眼所见，想必此诗亦是濡笔马上而作。\n\n　　“瀚海百重波，阴山千里雪。”瀚海，沙漠。波，沙丘起伏状。句意为：广袤的沙漠上，沙丘连绵不断，阴山上千里雪覆。此联进一步写塞外之景，壮阔迷茫，渲染了一种壮烈豪迈之情。其眼光，其气度，真有指点江山，总揽寰宇之势，这一点是此后的许多诗人都难以企及的。\n\n　　“迥戍危烽火，层峦引高节。”迥戌，远方的边戍。高节，旗帜。句意为：烽火中传来了远方的紧急军情，我于是挥兵远赴边疆，一路上层叠的山峦引导着我的旗帜。此二句点明为救边而出征，军队沿着山路前行，仿佛是山引领着队伍，意即此战很得天时，必将获胜。\n\n　　“悠悠卷旆旌，饮马出长城。”句意为：风儿轻轻地吹起旗帜，我们挥师出长城而饮水放马。马是古代战争最重要的交通工具，到某处饮马，意即对某处用兵，占领某地。自秦以来，长城一直是重要的守御工事，诗人敢为前人所不敢为，兵出长城，争雄天下，其傲视寰宇的胸怀确实令后人追慕不已。这两句点明了题中驰骋宇内，以天下为牧场之意。\n\n　　“寒沙连骑迹，朔吹断边声。”朔吹，北风。句意为：寒冷的沙漠上，骑兵过处，迹印连绵；凛冽的北风阻隔了边塞的噪杂之声。这是写进军途中所遇到的艰难险阻。\n\n　　“胡尘清玉塞，羌笛韵金钲。”玉塞，玉门关。金钲，锣声。句意为：玉门关一带，胡人入侵的嚣尘已经消逝，羌人们正吹着笛子，敲着金锣，载歌载舞。大军所指，蛮夷慑服，边境一带很快呈现出一片祥和、安宁的和平气象。并非倚仗武力，更多的是以德感召，所以使羌人载歌载舞心悦诚服。《旧唐书·太宗本纪》载：“自是西北诸蕃成请上尊号为‘天可汗’。”可见在处理与边疆少数民族的关系上，太宗是做得很成功的，从这两句诗中就可以看到这一点。\n\n　　“绝漠干戈戢，车徒振原隰。”绝漠，大漠。干戈，指武器。戢，收藏。原隰，原野。句意为：大漠之上，武器收藏，车仗过处，原野为之震动。平夷战祸后，军队凯旋，所到之处，群情振奋。所谓“吊民伐罪”，正义的战争，人民从来都是支持的。\n\n　　“都尉反龙堆，将军旋马邑。”龙堆，即白龙堆，今新疆库木塔格沙漠。句意为：都尉从龙堆返回，将军们从马邑凯旋而归。这两句是互文见义，称述得胜还朝，所用地名都是边塞一带，给人以真实感，此后的边塞诗也常用这种手法，罗列多个边关地名，虽然这些地区往往与诗中的事件并无关联，而且地名之间常常不具有确定的逻辑关系。\n\n　　“扬麾氛雾静，纪石功名立。”纪石，刻石纪功。句意为：旗帜飘扬，云雾弥漫的氛围因之消歇，将士们功勋卓著，应该把他们的功绩刻在石头上，永远流传后世。这里运用了象征手法，“扬麾”指唐军旗帜鲜明地出战，“氛雾”形容外敌入侵，一片纷扰之状。这是对将士们的称述，也是勉励将士们努力作战以名垂千古，同时也是自勉。\n\n　　“荒裔一戎衣，灵台凯歌入。”荒裔，边荒。戎衣，战士。灵台，周代台名。《后汉书·桓谭传》：“其后有诏会议灵台所处。”《三国志·魏书·王朗传》注：“明堂所以祀上帝，灵台所以观天文。”这里指代朝廷。句意为：边远、荒凉之地只需一介之士戍守，朝廷中已有凯歌高奏。大唐王朝，威镇四夷，只需很少的守兵，就可以保证国家的长治久安。李唐全盛时，的确如这两句所描述的那样，边境安宁，四境宾服。', poem_tags = '冬天,边塞,爱国,战争,生活' WHERE poem_title = '饮马长城窟行' AND poem_author = '李世民';
UPDATE edu_poem SET poem_translation = '秋意来到边城，声声号角哀鸣，平安烽火映照着高兴亭。击筑高歌，站在高处把酒洒向国土，引起了收复关中的无限兴致。\n谁能像多情的南山明月，把层层的暮云都推开？灞桥边的如烟翠柳，曲江池畔的美丽楼台，应该在月下伫立，等待着我军收复失地，胜利归来。', poem_notes = '秋波媚：词牌名。双调四十八字，前片三平韵，后片两平韵。\n高兴亭：亭名，在南郑（今属陕西）内城西北，正对当时在金占领区的长安南山。南郑地处南宋抗金前线，当时陆游在南郑任上。\n角声：行军打仗用的鼓角之声。\n烽火：古代边防措施，于高峰处建台，镇守士卒于敌炬，白昼举烟，夜间置火，警视军民作好防御和迎敌准备。后又有每日处夜放烟一炬，谓之平安火。此指报前线无事的平安烽火。高台：本处指高兴亭。\n筑：古代的一中弦乐器。\n酹（lèi）酒：把酒洒在地上的祭祀仪式。\n灞桥：在今陕西西安城东。唐人送客至此桥，折柳赠别。为唐代长安名胜。\n曲江：池名，在今陕西西安东南。为唐代以来的游览胜地。\n应：应该。人：指宋军，也包括作者。', poem_appreciation = '一个“望”字把诗人爱国情怀和等待胜利在望的心情表达无疑。7月16日夜晚，长安南山头，诗人登高远望，皎洁的月轮正在升起光华。\n\n　　词的上片写秋天来到边城，鼓角声充满悲哀，首句一个“哀”字充分表达了词人对国土沦丧的惋惜和悲哀。下片从上片的“凭高”和“此兴悠哉”过渡，全面表达了“高兴”的“兴”。整首词由“哀”到“兴”，反映了作者的乐观主义精神和爱国壮志。\n\n　　从角声烽火写起，烽火指平安火，高台指高兴亭。《唐六典》说：“镇戍每日初夜，放烟一炬，谓之平安火。”陆游《辛丑正月三日雪》诗自注：“予从戎日，尝大雪中登兴元城上高兴亭，待平安火至”。又《感旧》自注：“平安火并南山来，至山南城下。”又《频夜梦至南郑小益之间慨然感怀》：“客枕梦游何处所，梁州西北上危台。暮云不隔平安火，一点遥从骆谷来。”都可以和这首词句互证。高歌击筑，凭高洒酒，引起收复关中成功在望的无限高兴，从而让读者体会到上面所写的角声之哀歌声之悲，不是什么忧郁哀愁的低调，而是慷慨悲壮的旋律。“此兴”的“兴”，兼切亭名。\n\n　　下片从上片的“凭高”和“此兴悠哉”过渡，全面表达了“高兴”的“兴”。作者把无情的自然物色的南山之月，赋予人的感情，并加倍地写成为谁也不及它的多情。多情就在于它和作者热爱祖国河山之情一脉相通，它为了让作者清楚地看到长安南山的面目，把层层云幕都推开了。这里，也点明了七月十六日夜晚，在南郑以东的长安南山头，皎洁的月轮正在升起光华。然后进一步联想到灞桥烟柳、曲江池台那些美丽的长安风景区，肯定会多情地等待收复关中的宋朝军队的到来。应，应该。这里用“应”字，特别强调肯定语气。\n\n　　人，指宋军，也包括作者。词中没有直接说到收复失地的战争，而是以大胆的想象，拟人化的手法，描绘上至“明月”、“暮云”，下至“烟柳”、“池馆”，都在期待宋军收复失地、胜利归来的情景，来暗示作者所主张的抗金战争的前景。这种想象是在上片豪情壮志抒发的基础上，自然引发而出，具有明显的浪漫主义情调。', poem_tags = '宋词三百首,月亮,秋天,爱国' WHERE poem_title = '秋波媚·七月十六日晚登高兴亭望长安南山' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '天气刚刚变暖，时而还透出一丝丝的微寒。一整天风雨交加，直到傍晚方才停止。时近清明，庭院里空空荡荡，寂寞无声。目睹残花落叶更令人伤情，不觉借酒消愁竟然大醉酩酊，这又是去年种下的旧病。\n一阵阵轻冷的晚风，夹着城楼上画角凄厉的嘶鸣，把我吹醒。夜幕降临，重门紧闭，更显得庭院中死一般的寂静。正心烦意乱、心绪不宁，哪料到那溶溶的月光，把邻院中荡秋千的少女倩影送入我的眼里。', poem_notes = '庭轩：庭院，走廊。清明：清明节。\n残花中酒：悼惜花残春暮，饮酒过量。\n楼头画角：楼头，指城上的戍楼。画角，军用的号角，涂了彩色，故称画角。', poem_tags = '宋词三百首,婉约,春天,孤独,怀人' WHERE poem_title = '青门引·春思' AND poem_author = '张先';
UPDATE edu_poem SET poem_translation = '谁说画不出六朝古都的伤心事，只不过是那些画家为了迎合当权者的心态而不画伤心图而已。\n你看这六幅描摹南朝往事的画中，枯老的树木和寒凉的云朵充满了整个金陵城。', poem_notes = '金陵：古地名，即今江苏南京及江宁等地，为六朝故都。\n逐：随，跟随。《玉篇》：“逐，从也。”这里可作迎合解。\n老木：枯老的树木。’', poem_appreciation = '这是一首题画之作，诗人看了六幅描写南朝史事的彩绘，有感于心，挥笔题下了这首诗。\n\n　　画家是什么人，已不可考。他画的是南朝六代（东吴、东晋、宋、齐、梁、陈）的故事，因为六代均建都于金陵。这位画家并没有为南朝统治者粉饰升平，而是写出它的凄凉衰败。他在画面绘出许多老木寒云，绘出危城破堞，使人看到三百年间的金陵，并非什么郁郁葱葱的帝王之州，倒是使人产生伤感的古城。这真是不同于一般的历史组画。\n\n　　比韦庄略早些时的诗人高蟾写过一首《金陵晚望》：\n\n　　“曾伴浮云归晚翠，犹陪落日泛秋声。\n\n　　世间无限丹青手，一片伤心画不成。”\n\n　　结尾两句，感慨深沉。高蟾预感到唐王朝危机四伏，无可挽回地正在走向总崩溃的末日，他为此感到苦恼，而又无能为力。他把这种潜在的危机归结为“一片伤心”；而这“一片伤心”，在一般画家笔下是无法表达出来的。\n\n　　韦庄显然是读过高蟾这首《金陵晚望》的。当他看了这六幅南朝故事的彩绘之后，高蟾“一片伤心画不成”的诗句，似乎又从记忆中浮现。“真个是画不成么？”你看这六幅南朝故事，不是已把“一片伤心”画出来了吗！于是他就提起笔来，好象针对高蟾反驳道：\n\n　　“谁谓伤心画不成？画人心逐世人情。”为什么就画不成社会的“一片伤心”呢？只是因为一般的画家只想迎合世人的庸俗心理，专去画些粉饰升平的东西，而不愿意反映社会的真实面貌罢了。\n\n　　诗人在否定了“伤心画不成”的说法后，举出了一个出色的例证来：“君看六幅南朝事，老木寒云满故城。”请看这幅《金陵图》吧，画面上古木枯凋，寒云笼罩，一片凄清荒凉。南朝六个小朝廷，哪一个不是昏庸无道，最后向敌人投降而结束了它们的短命历史的？这就是三百年间金陵惨淡现实的真实写照。\n\n　　将高蟾的《金陵晚望》和本篇作一比较，颇耐人寻味。一个感叹“一片伤心画不成”，一个反驳说，现在不是画出来了么！其实，二人都是借六朝旧事抒发对晚唐现实的深忧，在艺术上有异曲同工之妙。', poem_tags = '唐诗三百首,咏史怀古,题画,地名' WHERE poem_title = '金陵图' AND poem_author = '韦庄';
UPDATE edu_poem SET poem_translation = '钟陵醉饮一别已经十余春，又见到云英轻盈的掌上身。\n当年我未成名你也未出嫁，难道我们两个都不如别人？', poem_notes = '钟陵：县名，即今江西进贤。\n掌上身：形容云英体态窈窕美妙。此用赵飞燕典故。\n卿：古代用为第二人称，表尊敬或爱意。此指云英。成名：指科举中式。俱：都', poem_tags = '愤慨,感叹' WHERE poem_title = '赠妓云英 / 嘲钟陵妓云英' AND poem_author = '罗隐';
UPDATE edu_poem SET poem_translation = '有一个楚国人，既卖盾又卖矛。他夸耀自己的盾，说：“我的盾坚固无比，没有什么东西能够穿透它。”又夸耀自己的矛，说：“我的矛锋利极了，任何坚固的东西都穿得透。”有人问他：“如果用您的矛刺您的盾，结果会怎么样呢？”那人张口结舌，一句话也回答不上来。什么都不能刺穿的盾与什么都能刺穿的矛，不可能同时存在于这个世界上。', poem_notes = '矛:古代用来刺杀敌人的长柄兵器，矛的基本形制有狭叶、阔叶、长叶、叶刃带系和凹口骹式等。\n盾:盾牌,古代作战时遮挡刀剑用。\n誉：赞誉，夸耀。\n曰：说，讲。\n吾：我。\n陷：穿透、刺穿的意思 。\n或：有人。\n以：使用；用。\n子：您，对人的尊称。\n何如：怎么样。\n应：回答。\n利：锋利，锐利。\n其：助词。这里指那个卖矛和盾的人。\n弗能：不能。\n之：的。\n鬻（yù)：卖.\n者：...的人\n莫：没有什么\n夫“用在首句，引起议论', poem_tags = '小学文言文,哲理,故事' WHERE poem_title = '矛与盾' AND poem_author = '韩非';
UPDATE edu_poem SET poem_translation = '王冕是诸暨县人。七八岁时,父亲叫他在田地上放牛,他偷偷地跑进学堂去听学生念书。听完以后,总是默默地记住。傍晚回家,他把放牧的牛都忘记了，有人牵着牛来责骂他们家的牛践踏田地，踩坏了庄稼。王冕的父亲大怒,打了王冕一顿。事情过后,他仍是这样。他的母亲说:“这孩子想读书这样入迷,何不由着他呢?”王冕从此以后就离开家,寄住在寺庙里。一到夜里,他就暗暗地走出来,坐在佛像的膝盖上,手里拿着书就借着佛像前长明灯的灯光诵读,书声琅琅一直读到天亮。佛像大多是泥塑的,一个个面目狰狞凶恶,令人害怕。王冕虽是小孩,却神色安然,好像没有看见似的。安阳的韩性听说以后对此感到很惊讶,收他做弟子,后来他成了大学问家。韩性死后，他的门人像侍奉韩性一样的侍奉王冕。那时王冕的父亲已死，王冕便将母亲带入越城供养。时间久了，母亲想念故乡，王冕就买了头白牛驾着母亲，自己穿戴着古式的帽子衣服跟随在车子后面，乡里的小孩都聚集在道两旁笑，王冕也笑。', poem_notes = '牧：放牧。\n陇：田埂。\n窃：偷偷地，暗中。\n辄：总是（常常）、就。\n或：有人；有的人\n蹊田：践踏田地，指踩坏了庄稼\n挞：鞭打。\n曷：通“何”，为什么。\n去：古义—离开，离去。今义：到。。。。。。去。\n潜：暗暗地、悄悄地。\n执策：拿着书卷。\n旦：早晨，天亮。\n狞恶可怖：狰狞凶恶，令人害怕。\n恬：心神安适。\n异：（意动)\n一词多义（之）\n父怒，垯之：他。\n执策应长明灯读之：无实义。\n“被”通“披”：穿戴\n亦：也', poem_tags = '写人,读书,励志' WHERE poem_title = '王冕好学' AND poem_author = '宋濂';
UPDATE edu_poem SET poem_translation = '借着醉意拍春衫，回想着，旧日春衫上的香。天将离愁与别恨，折磨我这疏狂人。路上年年生秋草，楼中日日进夕阳。登楼望；云渺渺，水茫茫。征人归路在哪方。相思话语无诉处，又何必，写在信纸上，费了泪千行。', poem_notes = '旧香：指过去欢乐生活遗留在衣衫上的香泽。\n无凭语：没有根据的话。', poem_appreciation = '鉴赏 　　此词在对作者往日欢歌笑乐的回忆中，流露出他对落拓平生的无限感慨和微痛纤悲。上片于室内的角度写离恨。起首两句抒写离恨的无法排遣。“旧香”是往日与伊人欢乐的遗泽，乃勾起“离恨”之根源，其中凝聚着无限往昔的欢乐情事，自觉堪惜，“惜”字饱含着对旧情的深切留念。而“醉拍春衫”则是产生“惜旧香”情思的活动，因为“旧香”是存留在“春衫”上的。句首用一“醉”字，可使人想见其纵恣情态，“醉”，更容易触动心怀郁积的情思。次句乃因“惜旧香”而激起的无可奈何之情。“疏狂”二字是作者个性及生活情态的自我写照。“疏”为阔略世事之意。这句意谓以自己这个性情疏狂的人却被离恨所烦恼而无法排遣，而在句首着一“天”字，使人觉得他的无可奈何之情是无由开解的。“年年”两句选取最常见的秋草、夕阳，烘托思妇日复一日、年复一年的思念之情。路上秋草年年生，实写征人久久不归；日日楼中朝暮独坐，实写为离恨折磨之苦。过片承“夕阳”而写云、水，将视野扩展，从云水渺茫、征人归路难寻中，突出相见无期。此二句即景生情，以景喻情，道出了主人公于楼上怅望时的情思。结拍两句是无可奈何的自慰，措辞无多，然而读之使人更觉哀伤。“莫向花笺费泪行”虽是决绝之辞，却是情至之语，从中带出已往情事，当是曾向花笺多费泪行。既然离恨这般深重，非言辞所能申写，如果再“向花笺费泪行”，那便是虚枉了。 ▲', poem_tags = '宋词精选,回忆,离别,思念,爱情' WHERE poem_title = '鹧鸪天·醉拍春衫惜旧香' AND poem_author = '晏几道';
UPDATE edu_poem SET poem_translation = '河边的草地草儿青绿一片，园中茂盛的柳树郁郁葱葱。\n站在绣楼上的那位女子体态盈盈，她靠着窗户容光照人好像皎皎的明月。\n她打扮得红装艳丽，伸出纤细白嫩的手指扶着窗儿向远方盼望她的亲人。\n从前她曾经是个青楼女子，她希望过上正常人的生活才成了游子的妻子。\n不想游子远行在外总是不回来，丢下她一个独守空房实在难以忍受寂寞。', poem_notes = '郁郁：茂盛的样子。\n盈盈：形容举止、仪态美好。\n皎皎：皎洁，洁白。牖（yǒu）：古建筑中室与堂之间的窗子。古院落由外而内的次序是门、庭、堂、室。进了门是庭，庭后是堂，堂后是室。室门叫“户”，室和堂之间有窗子叫“牖”，室的北面还有一个窗子叫“向”。上古的“窗”专指在屋顶上的天窗，开在墙壁上的窗叫“牖”，后泛指窗。\n娥娥：形容女子姿容美好。《方言》：“秦晋之间，美貌谓之娥。”\n倡家：古代指从事音乐歌舞的乐人。《说文》：“倡，乐也，就是指歌舞妓。”\n荡子：即“游子”，辞家远出、羁旅忘返的男子。《列子》里说“有人去乡土游于四方而不归者，世谓之为狂荡之人也”可以为证。', poem_appreciation = '此诗叙述的是一个生活片断，大致描述如下：女主人公独立楼头，体态盈盈，如临风凭虚；她倚窗当轩，容光照人，皎皎有如轻云中的明月；她红妆艳服，打扮得十分用心；她牙雕般的纤纤双手，扶着窗棂，在久久地引颈远望：她望见了园林河畔，草色青青，绵绵延延，伸向远方。“青青河畔草，绵绵思远道；远道欲何之，宿昔梦见之”（《古诗》），原来她的目光，正随着草色，追踪着远行人往日的足迹；她望见了园中那株郁郁葱葱的垂柳，她曾经从这株树上折枝相赠，希望柳丝儿，能“留”住远行人的心儿。原来一年一度的春色，又一次燃起了她重逢的希望，也撩拔着她那青春的情思。希望，在盼望中又一次归于失望；情思，在等待中化成了悲怨。她不禁回想起生活的拨弄。她，一个倡家女，好不容易挣脱了欢场泪歌的羁绊，找到了惬心的郎君，希望过上正常的人的生活；然而造化竟如此弄人，她不禁在心中呐喊：“远行的荡子，为何还不归来，这冰凉的空床，叫我如何独守！”\n\n　　此诗写的就是这样一个重演过无数次的平凡的生活片断，用的也只是即景抒情的平凡章法、“秀才说家常话”（谢榛语）式的平凡语言；然而韵味却不平凡。能于平凡中见出不平凡的境界来，就是此诗——也是《古诗十九首》——那后人刻意雕镌所不能到的精妙。\n\n　　这首诗其实就是一首歌词，是能够歌唱的诗句，也是《古诗十九首》中唯一使用了第三人称叙说的形式。\n\n　　诗的结构看似平直，却直中有婉，极自然中得虚实相映、正反相照之妙。诗境的中心当然是那位楼头美人，草色柳烟，是她望中所见，但诗人——他可能是偶然望见美人的局外人，也可能就是那位远行的荡子——代她设想，则自然由远而近，从园外草色，收束到园内柳烟，更汇聚到一点，园中心那高高楼头。自然界的青春，为少妇的青春作陪衬；青草碧柳为艳艳红妆陪衬，美到了极至。而唯其太美，所以篇末那突发的悲声才分外感人，也只是读诗至此，方能进一步悟到，开首那充满生命活力的草树，早已抹上了少妇那梦思般的哀愁。这也就是前人常说的《十九首》之味外味。如以后代诗家的诗法分析，形成前后对照，首尾相应的结构。然而诗中那朴茂的情韵，使人不能不感到，诗人并不一定作如此巧妙营构，他，只是为她设想，以她情思的开展起伏为线索，一一写成，感情的自然曲折，形成了诗歌结构的自然曲折。\n\n　　诗的语言并不经奇，只是用了民歌中常用的叠词，而且一连用了六个，但是贴切而又生动。青青与郁郁，同是形容植物的生机畅茂，但青青重在色调，郁郁兼重意态，且二者互易不得。柳丝堆烟，方有郁郁之感，河边草色，伸展而去，是难成郁郁之态的，而如仅以青青状柳，亦不足尽其意态。盈盈、皎皎，都是写美人的风姿，而盈盈重在体态，皎皎重在风采，由盈盈而皎皎，才有如同明月从云层中步出那般由隐绰到不鲜的感觉，试先后互易一下，必会感到轻重失当。娥娥与纤纤同是写其容色，而娥娥是大体的赞美，纤纤是细部的刻划，互易不得。六个叠字无一不切，由外围而中心，由总体而局部，由朦胧而清晰，烘托刻画了楼上女尽善尽美的形象，这里当然有一定的提炼选择，然而又全是依诗人远望或者悬想的的过程逐次映现的。也许正是因为顺想象的层次自然展开，才更帮助了当时尚属草创的五言诗人词汇用得如此贴切，不见雕琢之痕，如凭空营构来位置辞藻，效果未必会如此好。这就是所谓“秀才说家常话”。\n\n　　六个叠字的音调也富于自然美，变化美。青青是平声，郁郁是仄声，盈盈又是平声，浊音，皎皎则又为仄声，清音；娥娥，纤纤同为平声，而一浊一清，平仄与清浊之映衬错综，形成一片宫商，谐和动听。当时声律尚未发现，诗人只是依直觉发出了天籁之音，无怪乎南朝钟嵘《诗品》要说“蜂腰鹤膝，闾里已具”了。这种出于自然的调声，使全诗音节在流利起伏中仍有一种古朴的韵味，细辨之，自可见与后来律调的区别。\n\n　　六个叠词声、形、两方面的结合，在叠词的单调中赋予了一种丰富的错落变化。这单调中的变化，正入神地传达出了女主人公孤独而耀目的形象，寂寞而烦扰的心声。\n\n　　这位诗人不可能懂得个性化、典型化之类的美学原理，但深情的远望或悬想，情之所钟，使他恰恰写出了女主人公的个性与典型意义。这是一位倡女，长年的歌笑生涯，对音乐的敏感，使她特别易于受到阳春美景中色彩与音响的撩拔、激动。她不是唐代王昌龄《闺怨》诗中那位不知愁的天真的贵族少女。她凝妆上楼，一开始就是因为怕迟来的幸福重又失去，而去痴痴地盼望行人，她娥娥红妆也不是为与春色争美，而只是为了伊人，痴想着他一回来，就能见到她最美的容姿。因此她一出场就笼罩在一片草色凄凄，垂柳郁郁的哀怨气氛中。她受苦太深，希望太切，失望也因而太沉重，心灵的重压，使她迸发出“空床难独守”这一无声却又是赤裸裸的情热的呐喊。这不是“悔教夫婿觅封侯”式的精致的委婉，而只是，也只能是倡家女的坦露。也唯因其几近无告的孤苦呐喊，才与其明艳的丽质，形成极强烈的对比，具有震撼人心的力量。诗人在自然真率的描摹中，显示了从良倡家女的个性，也通过她显示出在游宦成风而希望渺茫的汉末，一代中下层妇女的悲剧命运。这就是个性化的典型性。', poem_tags = '古诗十九首,女子,闺怨,思念' WHERE poem_title = '青青河畔草' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '庾信的文章到了老年就更加成熟了，其笔力高超雄健，文思如潮，文笔挥洒自如。当今的人讥笑、指责他留下的文章，如果庾信还活着，恐怕真会觉得你们这些后生可畏了。\n\n　　王勃、杨炯、卢照邻和骆宾王四杰在当时的时代条件下，他们的作品已经达到最高的造诣。四杰的文章被认为是轻薄的，被守旧文人讥笑。你们这些守旧文人，在历史的长河中本微不足道，因此只能身名俱灭，而四杰却如江河不废，万古流芳。\n\n　　即便是王杨卢骆四杰操笔作诗，作品比不上汉魏的诗歌而接近《诗经》《楚辞》，但他们还是龙文虎脊的千里马，可以为君王驾车，纵横驰骋，不像你们一跑长途就会跌倒。\n\n　　你们的才力应难以超越上述几位，现在谁成就能超出他们？你们这些人所作的浓丽纤巧的诗文，不过是像翡翠飞翔在兰苕之上一般的货色，缺少大的气度，而没有如掣取鲸鱼于碧海之中那样的雄健才力和阔大气魄，只是一些小灵小巧的玩意。\n\n　　你们学诗要爱古人但也不能鄙薄像庾信、四杰这样的今人，要把他们的清词丽句引为同调。如果你们要在内心里追攀屈原、宋玉，应当具有和他们并驾齐驱的精神和才力，否则就会沿流失源，堕入齐、梁时期那种轻浮侧艳的后尘了。\n\n　　那些轻薄之辈不及前贤是毋庸置疑的，继承前人、互相学习的优秀传统应该是不用分先后的。区别和裁剪、淘汰那些形式内容都不好的诗，学习《诗经》风雅的传统，虚心向前贤学习，老师越多，这才是你们真正的老师。', poem_notes = '庾信：南北朝时期的著名诗人。文章：泛言文学。老更成：到了老年就更加成熟了。\n凌云健笔：高超雄健的笔力。意纵横：文思如潮，文笔挥洒自如。\n嗤点：讥笑、指责。\n前贤：指庾信。畏后生：即孔子说的“后生可畏”。后生，指“嗤点”庾信的人。但这里是讽刺话，意思是如果庾信还活着，恐怕真会觉得“后生可畏”了。\n王杨卢骆：王勃、杨炯、卢照邻、骆宾王。这四人都是初唐时期著名的作家，时人称之为“初唐四杰”。诗风清新、刚健，一扫齐、梁颓靡遗风。当时体：指四杰诗文的体裁和风格在当时自成一体。\n轻薄（bó)：言行轻佻，有玩弄意味。此处指当时守旧文人对“四杰”的攻击态度。哂（shěn）：讥笑。\n尔曹：你们这些人。\n不废：不影响。这里用江河万古流比喻包括四杰在内的优秀作家的名字和作品将像长江黄河那样万古流传。\n翰墨：笔墨。\n风骚：“风”指《诗经》里的《国风》，“骚”指《楚辞》中的《离骚》，后代用来泛称文学。\n龙文虎脊：喻瑰丽的文辞。\n翡翠：鸟名。兰苕（tiáo）：兰花和苕花。郭璞《游仙诗》：“翡翠戏兰苕，容色更相鲜”。\n掣（chè）：拉，拽。\n薄：小看，看不起，轻视。\n必为邻：一定要引以为邻居，即不排斥的意思。\n窃攀：内心里追攀。屈宋：屈原和宋玉。方驾：并车而行。这是诗人对轻薄文士说的：“你们想与屈原、宋玉齐名，应当具有和他们并驾齐驱的精神和才力。”齐、梁文风浮艳，重形式轻内容。这一句，诗人紧承上句说：“如若不然，恐怕你们连齐梁文人还不如呢！”\n未及前贤更勿疑：这句是说那些轻薄之辈不及前贤是毋庸置疑的。\n递相祖述：互相学习，继承前人的优秀传统。复先谁：不用分先后。\n别裁伪体：区别和裁减、淘汰那些形式内容都不好的诗。亲风雅：学习《诗经》风、雅的传统。\n转益多师：多方面寻找老师。汝师：你的老师。', poem_appreciation = '清人李重华在《贞一斋诗话》里有段评论杜甫绝句诗的话：“七绝乃唐人乐章，工者最多。……李白、王昌龄后，当以刘梦得（注：指刘禹锡）为最。缘落笔朦胧缥缈，其来无端，其去无际故也。杜老七绝欲与诸家分道扬镳，故尔别开异径。独其情怀，最得诗人雅趣。”他说杜甫“别开异径”，在盛唐七绝中走出一条新路子，这是熟读杜甫绝句的人都能感觉到的。除了极少数篇章如《赠花卿》、《江南逢李龟年》等外，他的七绝确是与众不同。\n\n　　首先，从内容方面扩展了绝句的领域。一切题材，感时议政，谈艺论文，纪述身边琐事，凡是能表现于其它诗体的，杜甫同样用来写入绝句小诗。其次，与之相联系的，这类绝句诗在艺术上，它不是朦胧缥缈，以韵致见长的作品；也缺乏运用于管弦的唱叹之音。它所独开的胜境，在于触机成趣，妙绪纷披，显得情味盎然，如同和读者围炉闲话，剪烛谈心；无论是感慨唏嘘也好，或者嬉笑怒骂也好，都能给人以亲切、真率、恳挚之感，使读者如见其人，如闻其声。朴质而雅健的独特风格，是耐人咀嚼不尽的。\n\n　　《戏为六绝句》（以下简称《六绝句》）就是杜甫这类绝句诗标本之一。以诗论诗，最常见的形式是论诗绝句。它，每首可谈一个问题；把许多首连缀成组诗，又可表现出完整的艺术见解。在中国诗歌理论遗产中，有不少著名的论诗绝句，而最早出现、最有影响的则是杜甫的《六绝句》。《六绝句》前三首评论作家，后三首揭示论诗宗旨。其精神前后贯通，互相联系，是一个不可分割的整体。\n\n　　《戏为六绝句》第一首论庾信。杜甫在《春日忆李白》里曾说，“清新庾开府”。此诗中指出庾信后期文章（兼指诗、赋），风格更加成熟：“庾信文章老更成，凌云健笔意纵横。”健笔凌云，纵横开阖，不仅以“清新”见长。唐代的“今人”，指手划脚，嘲笑、指点庾信，足以说明他们的无知。因而“前贤畏后生”，也只是讽刺的反话罢了。\n\n　　第二、三首论初唐四杰。初唐诗文，尚未完全摆脱六朝时期崇尚辞藻浮华艳丽的余习。第二首中，“轻薄为文”，是当时的人讥笑“四杰”的话。史炳《杜诗琐证》解释此诗说：“言四子文体，自是当时风尚，乃嗤其轻薄者至今未休。曾不知尔曹身名俱灭，而四子之文不废，如江河万古长流。”第三首，“纵使”是杜甫的口气，“卢王操翰墨，劣于汉魏近风骚”则是当时的人讥笑四杰的话（诗中以“卢王”来指四杰）。杜甫引用了他们的话而加以驳斥，所以后两句才有这样的转折。意思是即便如此，但四杰能以纵横的才气，驾驭“龙文虎脊”般瑰丽的文辞，他们的作品是经得起时间考验的。\n\n　　这三首诗的用意很明显：第一首说，观人必须全面，不能只看到一个方面，而忽视了另一方面。第二首说，评价作家，不能脱离其时代的条件。第三首指出，作家的成就虽有大小高下之分，但各有特色，互不相掩。应该恰如其分地给以评价，要善于从不同的角度向前人学习。杜甫的这些观点是正确的。但这三首诗的意义，远不止这些。\n\n　　第四首诗继续第三首诗意，对那些不负责任地胡乱糟蹋前贤现象的批评，指责这些人自己的作品不过是一些翡翠戏兰苕一般的货色，而没有掣鲸鱼于碧海那样的伟著。\n\n　　“不薄今人爱古人”中的“今人”，指的是庾信、四杰等作家。杜甫之所以“爱古”而不“薄今”，是从“清词丽句必为邻”出发的。“为邻”，即引为同调之意。在杜甫看来，诗歌是语言的艺术，“清词丽句”不可废而不讲。更何况庾信、四杰除了“清词丽句”而外，尚有“凌云健笔”、“龙文虎脊”的一面，因此他主张兼收并蓄：力崇古调，兼取新声，古、今体诗并行不废。“不薄今人爱古人，清词丽句必为邻”，应当从这个意义上去理解。\n\n　　但是，仅仅学习六朝，一味追求“翡翠戏兰苕，容色更相鲜”一类的“清词丽句”，虽也能赏心悦目，但风格毕竟柔媚而浅薄；要想超越前人，必须以恢宏的气度，充分发挥才力，才能在严整的体格之中，表现出气韵飞动的巧妙；不为篇幅所困，不被声律所限，在法度之中保持从容，在规矩之外保持神明。要想达到这种艺术境界，杜甫认为只有“窃攀屈宋”。因为《楚辞》的精彩绝艳，它才会成为千古诗人尊崇的典范，由六朝而上一直追溯到屈原、宋玉，才能如刘勰所说：“酌奇而不失其真，玩华而不坠其实，则顾盼可以驱辞力，咳唾可以穷文致”（《文心雕龙·辨骚》），不至于沿流失源，堕入齐、梁时期那种轻浮侧艳的后尘了。而杜甫对六朝文学既要继承、也要批判的思想，集中表现在“别裁伪体”、“转益多师”上。\n\n　　《六绝句》的最后一首，前人说法不一。这里的“前贤”，是泛指前代有成就的作家（包括庾信、四杰）。“递相祖述”，意思是因袭成风。“递相祖述”是“未及前贤”的根本原因。“伪体”之所以伪，症结在于以模拟代替创造。真伪相混，则伪可乱真，所以要加以“别裁”。创造和因袭，是杜甫区别真、伪的分界线。诗人只有充分发挥创造力，才能直抒襟抱，自写性情，写出真的文学作品。庾信的“健笔凌云”，四杰的“江河万古”，就在于此。反过来，拾人牙慧，傍人门户，必然是没有生命力的。堆砌词藻，步齐、梁时期的后尘，固然是伪体；而一味模仿汉、魏时期古人的作品，也是伪体。在杜甫的心目中，只有真、伪的区别，并无古、今的成见。\n\n　　“别裁伪体”和“转益多师”是一个问题的两面。“别裁伪体”，强调创造；“转益多师”，重在继承。两者的关系是辩证的。“转益多师是汝师”，意思是无所不学，没有固定的学习对象。这话有好几层意思：只有“无所不师”，才能兼取众长；没有固定的学习对象，不限于一家，虽然有所继承、借鉴，但并不妨碍诗人自己的创造性，这是第一层意思。只有在“别裁伪体”，区别真伪的前提下，才能确定“师”谁，“师”什么，才能真正做到“转益多师”，这是第二层意思。要做到“无所不师”而没有固定的学习对象，就必须善于从不同的角度学习别人的成就，在吸取的同时，也就有弘扬和舍弃的地方，这是第三层意思。在既批判又继承的基础上，进行创造，熔古今于一炉，创作出诗人自己的佳句，这就是杜甫“转益多师”、“别裁伪体”的精神所在。\n\n　　《六绝句》虽然主要是谈艺术方面的问题，但和杜甫总的创作精神是分不开的。诗中“窃攀屈宋”、“亲风雅”则是他创作的指导思想和论诗的宗旨。这六首小诗，实质上是杜甫诗歌创作实践经验的总结，诗论的总纲；它所涉及的是关系到唐诗发展中一系列的重大理论问题。在这类小诗里发这样的大议论，是前所未有的。诗人通过各种事例来总结出一系列的要点，将严正的笔意寄寓在轻松幽默的笔调中，娓娓道来，庄谐杂出。李重华说杜甫七绝“别开异径”，正在于此。明白了这一点，这组诗之所以标为《戏为六绝句》，读者也就不难理解了。', poem_tags = '议论,艺术,文学,组诗' WHERE poem_title = '戏为六绝句' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '天下的祸患，最不能挽回的，莫过于表面上社会安定没有祸乱，而实际上却存在着不安定因素。消极地看着祸乱发生却不去想方设法对付，那么恐怕祸乱就会发展到无可挽回的地步。起来坚决地制止它，又担心天下人已经习惯于这种安定的表象却不相信我。只有那些仁人君子、豪杰人物，才能够挺身而出为国家安定而冒天下之大不韪，以求得成就伟大的功业。这本来就不是能够在短时间内一蹴而就的，更不是企图追求名利的人所能做到的。国家安定平静，无缘无故地触发巨大的祸患的导火线。我触发了它，我又能制止它，然后才能有力地说服天下人。祸乱发生却想躲躲闪闪地避开它，让别人去承担平定它的责任，那么天下人的责难，必定要集中到我的身上。\n\n　　从前晁错殚精竭虑效忠汉室，建议景帝削弱山东诸侯各国的实力。于是山东诸侯各国共同起兵，借着杀晁错的名义。可是景帝没有洞察到他们的用心，就把晁错杀了来说服他们退兵。天下人都为晁错因尽忠而遭杀身之祸而痛心，却不明白其中部分原因却是晁错自己造成的。\n\n　　自古以来凡是做大事业的人，不仅有出类拔萃的才能，也一定有坚韧不拔的意志。从前大禹治水，凿开龙门，疏通黄河，使洪水东流入海。当他的整个工程尚未最后完成时，可能也时有决堤、漫堤等可怕的祸患发生，只是他事先就预料到会这样，祸患发生时就不惊慌失措而能从容地治理它，所以能够最终取得成功。\n\n　　七国那样强大，却突然想削弱它，他们起来叛乱难道值得奇怪吗？晁错不在这个时候豁出自己的性命，为天下人承受抵挡大难从而控制吴、楚等国的命运，却居然为了保全自己的性命想让景帝御驾亲征平定叛乱而自己留守京城。再说那挑起七国之乱的是谁呢？自己想赢得那个美名，又怎么能躲避这场患难呢？拿亲自带兵平定叛乱的极其危险，与留守京城的极其安全相比，自己是个引发祸乱的主谋，选择最安全的事情去做，却把最危险的事情留给皇帝去做，这就是让忠臣义士们愤怒不平的原因啊。在这个时候，即使没有袁盎，晁错也不可能免于杀身之祸。为什么呢？自己想要留守京城，却叫皇帝御驾亲征，按情理来说，皇帝本来已经觉得这是勉为其难的事情，但又不好反对他的建议，这样正好给袁盎以进谗言的机会，使他的目的能够得逞。假若吴、楚等七国叛乱时，晁错豁出性命承担这一危险的平叛重担，夜以继日像淬火磨刀似的训练军队，向东边严阵以待，让自己的君主不至于受到烦忧，那么皇帝就会充分依靠他而不觉得七国叛乱有什么可怕。纵使有一百个袁盎，能有机可乘离间他们君臣吗？\n\n　　唉！世上的君子如果想要建立伟大的功业，那就不要考虑保全性命的计策。假如晁错自己亲自带兵去讨伐吴、楚等七国，不一定就不会成功。只因他一心想保全自身，而惹得皇帝不高兴，奸臣正好趁此钻了空子。晁错企图保全自己的性命，正是他招致杀身之祸的原因啊！', poem_notes = '晁错：前200年—前154年，颍川今河南禹州人，是西汉文帝时的智囊人物。主张重农贵粟，力倡削弱诸候，更定法令，招致王侯权贵忌恨。汉景帝四年（前154年），吴、楚等七国以“讨晁错以清君侧”为名，发动叛乱，晁错因此被杀。\n患：祸患。\n为：治理，消除。\n治平：政治清明，社会安定\n其：代词，指祸患。\n所：处所。这里指解决问题的措施。\n狃（niǔ）：习惯。\n不吾信：不相信我。\n惟：只有。\n出身：挺身而出。\n犯：冒着。\n以：而，表顺接。\n固：原本。\n期（jī）月：一个月。这里泛指短时期\n端：开头，开始。\n发：触发。\n收：制止。\n然后有辞于天下：然后才能有力地说服天下人。\n循循焉：缓慢的样子。循循，徐徐。焉，……的样子。\n去：逃避\n昔者晁错尽忠为汉：从前晁错殚精竭虑效忠汉朝。昔者，从前。\n山东：指崤山以东。\n并起：一同起兵叛乱。\n以诛错为名：以诛杀晁错作为名义。以······为，把······作为。\n而天子不以察，以错为之说：但汉景帝没有洞察到起兵的诸侯的用心，把晁错杀了来说服他们退兵。\n天下悲错之以忠而受祸，不知错有以取之也：天下人都为晁错因尽忠而遭受杀身之祸而悲痛，却不明白其中一部分是晁错自己造成的。以，因为。取，招致。\n古之立大事者，不惟有超世之才，亦必有坚忍不拔之志：自古以来能够成就伟大功绩的人，不仅仅要有超凡出众的才能，也一定有坚韧不拔的意志。\n之：用在主、谓语之间，取消句子的独立性，无实义。\n龙门：今陕西韩城东北，是黄河奔流最湍急处。\n大河：指黄河。\n方：当。\n盖亦有溃冒冲突可畏之患：可能也有决堤、漫堤等可怕的祸患。\n是以：所以，因此。\n夫：句首发语词。\n骤：突然。\n其为变，岂足怪哉：他们起来叛乱，难道值得奇怪吗？足，值得。\n乃：竟然。\n欲使天子自将而己居守：想让皇帝御驾亲征平定叛乱，而自己留守京城。\n己欲求其名，安所逃其患：自己想求得这个美名，怎么能逃避这场患难呢？安，怎么。\n此忠臣义士所以愤怨而不平者也：这是忠臣义士们之所以愤怒不平的原因啊。\n虽：即使。\n何者：为什么呢？\n以情而言：按照情理来说。以，按照。\n天子固已难之矣，而重违其议：皇帝本来已经觉得这是勉为其难的事情，但又不好反对他的建议。\n使：假若。\n淬砺：锻炼磨砺。引申为冲锋陷阵，发愤图强。\n虽有百盎，可得而间哉：即使有一百个袁盎，能有机可乘离间他们君臣吗？\n嗟夫：感叹词，唉。\n则无务为自全之计：就不要考虑保全性命的计策。务，从事。\n隙：空隙，空子。\n乃其所以自祸欤：正是他招致杀身之祸的原因啊！欤，语气助词，表感叹。', poem_appreciation = '苏轼在其人物史论中写了大量的翻案文章，立意新颖深刻，高远幽邃。治国之策，行事之则；爱民之心，嫉恶之恨；他人之思，自我之省，都别出新见，发人之所未见，启人之所未思。晁错曾提出“削藩”建议，后被汉景帝所杀。“晁错之死，人多叹息”，苏轼却翻空出奇，以独特的视角，一家之言，阐述了晁错受祸原因，提出了仁人君子、豪杰之士应“出身为天下犯大难，以求成功”的主张。\n\n　　文章开篇为泛泛概说：“天下之患，最不可为者，名为治平无事，而其实有不测之忧。”起句看似虚写，实则却在暗说汉景帝时国泰民安中隐含着的诸侯之患。接着，作者便围绕“患”字，从“坐”、“起”两方面进行分说。“坐观其变”而不对祸患采取措施，那么祸患便会蔓延得无可救药；“起而强为之”而不等待时机，则夭F也同样不能保持治平安定的局面。作者说的“起而强为之”，暗指晃错的削落。下面，文章又结止上两句的意思。引出“仁人君子豪杰之行”的作为，以此而暗与晃错柑比。用“此固非勉强期月之间。而苟以求名者之所能也。”概写出历史上的失败者、又具体落实在晁错身上，暗含着对晃错失败原因的评论。这两句堪称全篇关键之处，是作者论说的中心。在此处，它还有承上启下的妙用：“此固非勉强期月之间”，上承“起而强为之”;“苟以求名者”，下启“事至而循循焉欲去之”。后面，“天下治平”几句，暗写景帝时的“七国之乱”；“事至而循循焉欲去之”几句，又虚写七国起兵后晁错的态度。因此，首段虽没直接点出晃错，但却句句在写晃错。抽象中有具体，虚写里含实写，虚实相生中既使后面的论述高屋建扳，又让文章排宕开闺，具有一种滔滔的气势。\n\n　　第二段，丈章在前面基础上较而易举地由抽象而具体，由隐而显。由历史的抽象概说，过渡到具体的史事论述。西汉社会诸侯的割据势力严重威胁着封建的中央集权、晃错继贾谊之后，屡次建议景帝“削藩”。他说诸侯王“削之亦反，不削亦反、削之，其反呕，祸小；不削之，其反迟，祸大。”汉景帝用其策，于是出现了“七国之乱”。后来因谗言晁错被杀，后代之人多悲叹晃错的尽忠而蒙害。但苏轼这里却一反传统老调，认为晃错获罪是由于“有以取之也”，从而使文章蹊径独辟、不同凡响。\n\n　　第三段，作者一方面紧扣史事，另一方面却把笔触拉开，先提出“古之立大事者，不唯有超世之才，亦必有坚忍不拔之志介的观点。然后便旁征博引用大禹治水的凿龙门、决江河和溃冒冲突来举例论证，提出“事至而不惧”、“徐为之所”才能使大事成功，以此而暗中指责晁错的临危而逃。\n\n　　第四段是全篇的主体，这一段议论变得丰富，行文也变得曲折。这一段通过有力的论说鞭辟近里地阐述了晃错取祸的原因。“夫以七国之强而骤削之，其为变岂足怪哉！”苏轼认为“削藩”应该逐步进行，徐为之所”，而不应“骤削之”，骤削则必然导致“七国之乱”，这便是“无故而发大难之端”。仁人君子豪杰却于此时挺身而出，所以能成大业，但晃错不在此时捐身，力挡大难，击溃七国，反而临危而逃，“使他人任其责”，那么“天下之祸”自然便集中在晁错身上了。文章至此。所议之事、所立之沦虽与前文相近，但观点与史事却逐渐由隐而显、由暗而明。文章的气势也慢慢由弱而强、由平易而近汹涌。紧接着，作者又连用了两个反问句，把文章的气势推向了的顶峰。“且夫发七国之难者，谁乎？”是谁引发出七国之难而又临危而逃了选择最安全的处所，把天子陷入至危的境地，这是忠义之士所愤惋之人，既使无袁盎的谗一也不会幸免十祸。这样的结局的原因是“己欲居守，而使人主自将。”这两个问句一波未平又起一波，使文覃呈现出汪洋惩肆的特征。然而苏轼并不就此搁笔，他用两个条件再从反面假设晁错，把文章跳起的高浪又推向了深远广阔。“使吴、楚反，错以身任其危，日夜淬砺，东向而待之”，这是假设晃错不临危而逃；“使不至于家其君。则天子将恃之以为无恐”，这是假设晃错不使人主自将。那么即使有一百个袁盎也不能使晃错获祸。\n\n　　最后一段，文章的气势渐渐平缓，在感叹历史之时，再一次指出临危而逃自固其身是晁错取祸的原因，从而增重了题旨的作用。\n\n　　作者生活时代，治平已久，文恬武嬉，积贫积弱，作者思治，故此论实为有感而发。起首议论雄深浑徽，有很强的针对性。全篇文章由虚而实，由实而气势滔滔，由气势滔滔而渐渐平缓，把舒缓与紧凑有机地融为一体。', poem_tags = '古文观止,议论,写人,抒情' WHERE poem_title = '晁错论' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '郑武公、郑庄公是周平王的卿士（官名）。（周平王）分权给虢公，郑庄公怨恨周平王。周平王说：“没有的事（偏心于虢公）。”于是周王、郑国交换人质（证明互信）：（周平王）的儿子狐在郑国做人质，郑庄公的儿子忽在周王室做人质。\n\n　　周平王死（后），周王室准备让虢公掌政。四月，郑国的祭足帅军队收割了温邑的麦子。秋季，又收割了成周的稻谷。周和郑互相仇恨。\n\n　　君子说：“信用不发自心中，盟约抵押也没用。开诚布公互相谅解地行事，用礼教约束，即使没有抵押，谁能离间他们呢？假如有真诚的信用，山涧溪流中的浮萍，蕨类水藻这样的菜，装在竹筐铁锅一类的器物里，用低洼处沟渠中的水，都可以供奉鬼神，献给王公为食，何况君子缔结两国的盟约，按礼去做，又哪里用得着人质啊？《国风》中有《采蘩》、《采苹》，《大雅》中有《行苇》、《泂酌》诗，都是昭示忠信的。”', poem_notes = '卿士：周朝执政官。\n贰于虢（guó）：二心，这里有“偏重”的意思。此指平王想把政权一部分让虢执掌。虢，指西虢公，周王室卿士。\n郑伯：诸侯国郑国的君主，这里是郑庄公。\n交质：交换人质。\n王子狐：即姬狐，是周平王的次子、姬泄父的弟弟，史称“王子狐”，在长兄“太子泄父”死后，被立为太子。\n公子忽：郑庄公太子，后即位为昭公。\n王崩：周平王去世。崩，君主时代称帝王死。\n畀（bì）：交给。\n祭（zhài）足：即祭仲，郑大（dà）夫。温，周朝小国,在今河南温县南。\n成周：周地，今在河南洛阳市东。\n中：同“衷”，内心。\n明恕：互相体谅。\n要（yāo）：约束。\n间：离间。\n明信：彼此了解，坦诚相待。\n沼沚：沼，池塘。沚，水中小洲。\n蘋（píng）：水生植物，即浮萍。蘩（fán），白蒿。蕴藻，一种聚生的藻类。菜，野菜。\n筐莒（jǔ）：竹制容器，方形为筐，圆形为莒。锜（qí）釜，均为烹饪器，有足为錡，无足为釜。\n潢（huáng）：积水池。污，积水。行（háng）潦（lǎo）， 路上的积水。\n荐：享祭，祭祀。\n羞：同“馐”，进奉。\n《采蘩》、《采苹》：均为《诗·召南》篇名，写妇女采集野菜以供祭祀。\n《行苇》、《泂（jiǒng）酌》：均为《诗·大雅》篇名，前者写周祖先晏享先人仁德，歌颂忠厚。后者写汲取行潦之水供宴享。\n昭：表明。', poem_appreciation = '文章先简要记述了事情的前因后果，一方面揭示了郑庄公两次入侵东周之地，强逼平王立质、咄咄逼人的姿态；另一方面则反映了东周王室已然衰微、任人欺凌、委曲求全的历史情状。并由此得出结论，周天子与郑庄公想通过交换人质来缓解矛盾、取信对方的做法是不可靠、也不可取的，因为周郑之间并没有诚信之心，又不依“礼”行事，所以双方即使交换了人质，也还是不能够维持他们之间的关系。\n\n　　最后，君子通过对此事的评论，指出相互之间的了解和信任要建立在彼此体谅、坦诚相待的基础之上，强调了恪守礼仪、忠于信义的重要性。\n\n　　文章虽然不长，但叙事朴实，议论周严，有事实，有根据，有结论，语言中肯，说服力很强。文末“君子日”一段评论，以信和礼为标准。一针见血地指出周郑交质之非。数层转折与整齐的排旬，使作者的论断显示出不可逆转的气势，空灵排宕、辞采纵横而又风韵悠然。\n\n　　自幽王烽火戏诸侯及平王东迁以来，周王权威早已实际崩溃。但周王及诸侯都没有将此事捅破。周郑交质作为一个可供观测或曰方便标记的事件点而成为周王权威崩溃的标志。《左传》认为周郑交质“无信（已堕落到需靠人质故曰无信）不礼（周郑上下失序故曰不礼）”，是东周“礼崩乐坏”的缩影。\n\n　　在《周郑交质》中，君子对双方都有责难，但侧重于批评周王室。左丘明认为这种局面的出现是因其不能以信服人，是以礼驭下造成的。周、郑由“交质”到“交恶”，其根本原因，是利益和权力再分配问题上矛盾冲突的必然结果。也就是说，决定周、郑双方关系的最终原则是利益和权利的再分配。尽管由于历史的局限，《左传》作者不可能揭示周、郑由“交质”到“交恶”的历史本质，但由于作者是“用事实说话”，所以，还是使我们看到了这一时代历史发展的总趋势和总动向。而“用事实说话”，也正是此文的最大特点。至于此文用较多的文字阐发诚信的重要性，那只是作者的一种美好愿望而已，因为在历史进入“礼崩乐坏”的春秋时代以后，就很难看到各诸侯国“要之以礼”并“行之以礼”的事情了。《周郑交质》这篇文章反映了《左传》崇霸贬王思想。全文先讲事实，再进行评论，这是《左传》的典型写法。君子的议论以“礼信”为中心，引经据典，辞理畅达。对后世史论有极大的影响。', poem_tags = '古文观止,历史,故事' WHERE poem_title = '周郑交质' AND poem_author = '左丘明';
UPDATE edu_poem SET poem_translation = '在大海的寒波中，我同倭寇周旋已有十年之久；我站在这里，遥望着京城宫阙。\n我的心血如同洒在千山万岭上的浓霜，把满山的秋叶都染红了。', poem_notes = '望阙（quē）台：在今福建省福清县.为戚继光自己命名的一个高台。戚在《福建福清县海口城西瑞岩寺新洞记》中记道：“一山抱高处，可以望神京.名之日望阙台。”阙，宫闱，指皇帝居处。\n十年，指作者调往浙江，再到福建抗倭这一段时间。从嘉靖三十四年调浙江任参将，到嘉靖四十二年援福建，前后约十年左右。\n孤臣，远离京师，孤立无援的臣子，此处是自指。\n宸（chēn）銮（luán）：皇帝的住处。', poem_tags = '爱国,战争,励志' WHERE poem_title = '望阙台' AND poem_author = '戚继光';
UPDATE edu_poem SET poem_translation = '者在小序中为读者讲述了一个凄切哀婉的爱情故事。泰和年间，河北大名府有两个青年男女，彼此相恋却遭家人反对，固而愤而投河自尽。后来人们才发现他们在水中的尸体。由于这一爱情悲剧，后来那年的荷花全都并蒂而开，为此鸣情。故事哀婉，令人动情。这首词就是作者闻听此事后，抒发感想，向为争取爱情自由而牺牲的青年男女表示同情，显示作者比较进步开明的思想。此词与《雁丘词》同为姊妹篇。\n\n　　全词写爱情悲剧，直言其人其事。上片写莲花并蒂的奇观，由此揭开故事的源头。“问莲根”三句，起首一个“问”字引起人们的注意。“丝”谐“思”，意为为情而殉身的青年男女，沉于荷塘，仍藕接丝连，爱情之思永存。“莲', poem_tags = '爱情,故事,荷花' WHERE poem_title = '摸鱼儿·问莲根有丝多少' AND poem_author = '元好问';
UPDATE edu_poem SET poem_translation = '肥水汪洋向东流，永远没有停止的时候。早知今日凄凉，当初真不该苦苦相思。梦里的相见总是看不清楚，赶不上看画像更加清晰，而这种春梦也常常无奈会被山鸟的叫声惊起。\n春草还没有长绿，我的两鬓已成银丝，苍老得太快。我们离别得太久，慢慢一切伤痛都会渐渐被时光忘去。可不知是谁，让我朝思暮想，年年岁岁的团圆夜，这种感受，只有你和我心中明白。', poem_notes = '元夕：旧历正月十五元宵节。\n肥水：源出安微合肥紫蓬山，东南流经将军岭，至施口入巢湖。\n种相思：留下相思之情，谓当初不应该动情，动情后尤不该分别。\n丹青：泛指图画，此处指画像。\n红莲夜：指元夕。红莲，指花灯。', poem_appreciation = '这首《鹧鸪天·元夕有所梦》，乃姜夔为怀念身在合肥的恋人而作，作于宁宗庆元三年（1197）元宵节之时。据夏承焘先生考证，姜夔在初遇合肥恋人时，约为二十余岁，在他三十六岁这年，曾经两次到过合肥。“绍熙元年（1190），姜夔再客合肥，此年冬，姜夔戴雪诣石湖，授范成大以咏梅之《暗香》、《疏影》新声两阕，成大喜以歌妓小红为赠。”而作此词时，姜夔已是四十二岁，与旧恋人初遇已相隔近二十年。\n\n　　上阙首句“肥水东流无尽期”，点明了当初相恋的地方，并借水流悠悠、绵绵无尽之意，谓已相思亦是了无尽期。“当初不合种相思”，表面上有怨极生恨的后悔之意，称当初就不应该发生这段感情，然实则说，自已根本就摆脱不了这段刻骨铭心的恋情，始终被相思缠绕，太过苦恼。有李太白《秋风词》“长相思兮长相忆，短相思兮无穷极。早知如此绊人心，何如当初莫相识”之感慨。“梦中未比丹青见”则写出了词人梦中的遗憾。在梦里，恋人的面容模糊依稀，没有画像那般清晰。潜在地表明了词人在这二十年里，刻未能忘恋人的样子，时常在她的画像前流连这样一个事实。结句“暗里忽闻山鸟啼”沉痛已极，离别已久，又相隔遥远，只能在梦中相见了，然而，这模糊不清晰的梦，竟然还被鸟啼声惊醒。情伤若斯，痛彻心脾。\n\n　　下阙起首句“春未绿、鬓先丝”，言春乍始，然发已先白；也暗写自已二十年来，伤春如故的恒久之思。“人间别久不成悲”道出人间世情的悲哀。分别久了，人的情感已变得麻木不堪，再也感觉不到当初离别时的那种铭心刻骨的痛苦了。暗合佛家“有情皆幻，有色皆空”之理。然细细想来，世情欢爱，又莫不如此，读之心中尤觉感伤。“谁教岁岁红莲夜，两处沉吟各自知”两句，点出主旨，收结全篇。在元夕之夜，你是否会触景生情想起了我？而我对你的思念，你是否又能感应到？这个问题是个天问，没有答案，只有身在两地的双方各自心里明白。由此推求出，这段恋情在元夕之夜的花灯会，曾有过甜蜜地回忆。在这一特定的时刻，能够引发彼此的回忆和相思。\n\n　　东坡云：“言有尽而意无穷者，天下之至言也。”该词情境深永，含而不露，其意可神会，无法以言语尽达，心有戚戚者，自会其中之意。', poem_tags = '宋词精选,婉约,记梦,怀人' WHERE poem_title = '鹧鸪天·元夕有所梦' AND poem_author = '姜夔';
UPDATE edu_poem SET poem_translation = '快上西楼赏月，担心中秋月有浮云遮挡，不够明朗。请美人吹笛，驱散浮云，唤出明月。月夜的天地一片清凉洁爽，刚经玉斧修磨过的月亮，又回又亮。追问月宫里独处的嫦娥，孤冷凄寂时有没有愁恨？应该有很多白发。\n回忆当年歌舞欢聚的情景，长袖善舞的佳人，清歌悲咽的佳人为之助兴添欢。叹明月十有八九悖人心意，总是圆时少、缺时多。愿明月如今夜常圆，人情未必总是别离。我欲化离恨为聚欢，待人归时再细细倾诉。', poem_notes = '寄远：寄语远人。就词意看，这个远人可能是词人眷恋过的歌舞女子。\n“但唤取”两句：请美人吹笛，驱散浮云，唤出明月。按：此暗用吴殊中秋赏月事。玉纤：洁白纤细，指美人的手。横管：笛子。\n冰壶：盛冰的玉壶。此喻月夜的天地一片清凉洁爽。玉斧修时节：刚经玉斧修磨过的月亮，又回又亮。\n“问嫦娥”两句：想来月中嫦娥，孤冷凄寂白发。此暗用丰商隐《嫦娥》诗意：“嫦娥应悔偷灵药，碧海青天夜夜心。”孤令：即孤零。\n“云液”四句：回忆当年歌舞欢聚的情景。云液满：斟满美酒。琼杯：玉杯。咽：指歌声凄清悲咽。\n“叹十常”两句：叹明月十有八九津人心意，欲圆还缺。此即苏轼“何事常向别时圆”（《水调歌头》）之意。磨：修磨，指把月修圆磨亮。\n“但愿”两句：愿明月如今夜常圆，人情未必总是别离。此化用苏轼《水调歌头》词意： “但愿人长久，千里共婵娟。”看承别：别样看待。', poem_appreciation = '此词是一首望月怀人之作，可能是与词人有着感情纠葛的歌舞女子。这个女子令词人爱慕不已。美月当空，已能勾起人无限秋思。面对中秋夜月，那怀人之情便愈发浓烈了。于是词人借月写意，传递了词人对歌舞女子的怨尤与不忍相舍的复杂感情。\n\n　　词的上片就中秋月这一面来写，主要展现词人的飞扬意兴。起韵即激情喷涌，以一“快”字为催促，表达要上西楼赏月的酣畅兴致。而一“怕”字，又泄露出词人担心中秋月不够明朗的心思。在情感节奏上，此韵一扬一抑，起伏有致。接韵借用前人故事，写词人由西楼待月而请美人吹笛唤月，这就为中秋月的出场蓄足了势。三韵正面赋写中秋月的无垠光华，写得气势酣畅。在这里，词人采用了一个精彩的比喻——把月色笼罩下的世界比喻为冰壶中的世界，则月色的皎洁无垠、透明清凉之状可感。又采用了一个玉斧修月的神话，把月亮的圆美无瑕之状也形容了出来。这里的“谁做”、“最怜”二词，不仅显出了词人对此中秋月的无比赏爱之情，而且形成了相当空灵的意境。上片末韵由无边的月色回转到月亮本体，追问月宫里独处的嫦娥有没有愁恨，这也是古代赏月者在神话时代容易产生的绮情。但是通过“应华发”的自答就可以发现。词人在这里问讯娠娥的目的，并不止于发一发严格古典男子的绮情幽思，而有借之诉愁的用意。这就使上片的词情至此气脉暗转，为下文抒发别恨调好了调子。\n\n　　下片开始，词人先用状写满天月色的“云液满”一句承上启下，然后展现自己在月下酣饮欢乐的情状。长袖善舞的佳人，清歌悲咽的佳人为之助兴添欢。这是最令词人愉快的场面。但是词人的心意匀不在此，词人由此中秋明月夜、由此歌舞助兴人想到的是令自己牵情的远人，于是不由自主地发出了深沉的叹息。词人叹息人生不如意事十常八九，就像天上的明月总是圆时少、缺时多一样。这一叹息，是承接着苏轼《水调派头·明月几时有》而来，其中不能不含有苏拭词中对于“月圆人不圆”的恨意，但词人此句意思显然又有所变化，词人主要是借月亮的不得长圆，叹息人事不得圆满特别是情人之间不得遂愿长聚的遗憾。“但愿”一韵，更明显地折向题目，表明尽管词人理解人事的不如意不可改变，但还是衷心地希望能够与所爱者长相聚，就像词人希望此夜月色好景能够长久护持一样。由此“不讲理”的态度，读者可以洞见词人内心的痴情。而“人情”一句，虽像是对于人间常情的遗憾却实际上是指向词人所痴情的那个人。意谓一旦离别，别人在心里未必与自己一样珍惜护持这段感情。这样的口吻，使得词人的内心幽怨苦可触及。结韵出入意想，又化幽怨的情感为期待相逢的急切之情。词人说假如能够回到她的身边，词人会将离别时所生的幽恨，转换成劝乐的感受向她尽情诉说。在这样的结韵里，词人的入骨痴情和体贴怜爱的幽绪，被传递得婉转动人。表达词人内心隐藏着的无限痴情。真豪杰，其志过人，其情也必过人。', poem_tags = '中秋节,望月,怀人' WHERE poem_title = '满江红·中秋寄远' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '沉潜的龙，姿态是多么的幽闲多么的美妙啊！高飞的鸿鸟，声音是多么的响亮多么的传远啊！我想要停留在天空（仕进功名），却愧对天上的飞鸿；我想要栖息川谷（隐退沉潜），却惭对深渊的潜龙。我仕进修德，却智慧拙劣；我退隐耕田，却又力量无法胜任。为了追求俸禄，我来到这偏远的海边做官，兼又卧病在床，面对著光秃秃的树林。（每天）蒙著被子，睡著枕头，浑不知季节气候的变化。偶然间揭开窗帷，暂且登楼眺望。倾耳细听有那流水波动的声音，举目眺望有那巍峨高峻的山岭。初春的阳光已经代替了残余的冬风，新来的阳气也更替了去冬的阴冷。（不知不觉）池塘已经长满了春草，园中柳条上的鸣禽也变了种类、换了声音。想起《出车》这首豳诗，真使我伤悲，想到《春草生兮萋萋》这首楚歌，更是让我感慨。唉！独居的生活真容易让人觉得时间难捱、特别长久，而离开群体的处境也真是让人难以安心。坚持节操那里仅仅是古人才做得到呢？所谓的“遯世无闷”今天在我的身上已经验证、实践了。', poem_notes = '池：谢灵运居所的园池。\n潜虬媚幽姿：潜游的虬龙怜惜美好的姿态。\n响：发出\n远音：悠远的鸣声。\n薄：迫近，靠近。\n愧：惭愧\n栖川：指深渊中的潜龙\n怍：内心不安，惭愧。\n进德：增进道德，这里指仕途上的进取。\n徇禄：追求禄位。\n疴：病\n衾枕昧节候：卧病衾枕之间分不清季节变化。衾，大被。昧，昏暗。\n褰开：揭开帷帘，打开窗子。\n岖嵚：山势险峻的样子。\n初景革绪风：初春的阳光消除了冬季残留下来的寒风。\n新阳改故阴：新春改变了已过去的残冬。\n塘：堤岸\n祁祁伤豳歌：“采蘩祁祁”这首豳歌使我悲伤。祁祁，众多的样子。豳歌，指《诗经·豳风·七月》：“春日迟迟，采蘩祁祁。女心伤悲，殆及公子同归”的句子。\n萋萋感楚吟：“春草兮萋萋”这首楚歌使我感伤。萋萋，茂盛的样子。楚吟，指，《楚辞·招隐士》：“王孙游兮不归，春草生兮凄凄”的句子。\n索居：独居。\n群：朋友\n处心：安心\n持操：保持节操\n无闷：没有烦闷。出自《易经·乾卦》：“遁世无闷。”意为贤人能避世而没有烦恼。\n征：验证，证明。', poem_appreciation = '全诗可分为三个层次。第一层写他出任永嘉大守的矛盾心情，懊悔自己既不能像潜藏的虬那样安然退隐，又不可能像高飞的鸿那样声震四方，建功立业。第二层写他在病中临窗远眺。第三层写他的思归之情。\n\n　　前八句为第一层，主要写官场失意后的不满与当时矛盾的处境。魏晋南朝时代权力斗争激烈，仕途风波险恶，因此士族文人既有进取之志，又有企羡隐逸之心，而诗人所面临的，却是两者俱无所得的困境。诗一开头即由此下笔：“潜虬”一句喻深藏不露、孤高自赏的生活，“飞鸿”一句喻奋进高飞、声名动世的境界；下面两句说无论前者还是后者，自己都不能做到，深感惭傀。四句中，第三句紧接第二句，第四句远承第一句，诗意连贯而有变化。以上四句用形象的比喻写出自己的困境，但为何会这样，并未交代清楚，所以又有后四句把前四句加以落实。“进德”谓进取功业，施恩德于世人，与“飞鸿”一句相应。——但虽有此志，却是才智不及。这句实际的意思，是说自己耿直守正，乃至受人陷害。“退耕”谓退隐田园，以耕作自资，与“潜虬”一句相应。——但徒怀此愿，却是力所未能。以谢氏的富有，当然谈不上“退耕力不任”的问题。这句实际的意思，是说自己颇有退隐之心，只是为形势所格，无法实现。因为当时谢灵运如果拒绝赴任，就是公开表示与当权者对抗，极可能招致更大麻烦。下面进一步写自己于无奈中来到这偏僻的海隅，入冬后久卧病床，所对唯有萧索枯瑟之空林。全诗由虚入实，由远及近，气氛渐渐降到最低点。\n\n　　自“衾枕”以下八句为第二层，写登楼所见满目春色。“衾枕昧节候”紧承前一句”卧疴对空林”而来，写卧病中不知不觉，已是冬去春来，同时自然而然引出下旬“褰开暂登临”。“暂”谓短时间，有抱病强起之意。“倾耳”、“举目”两句，写出诗人对自然风光的极度喜爱。池塘水波轻拍，在倾耳细听之际，令人虑澄意解；远山参差耸立，于放眼遥望之中，使人心旷神怡。眼前是一派景色：“初景”即新春的阳光，正在革除“绪风”即残冬的余风，“新阳”即春代替了“故阴”即冬的统治。“初景”、“新阳”写出总体的感受，是虚笔，下面“池塘”、“园柳”两句，转为近景的具体描绘。“池塘生春草，园柳变鸣禽”，是谢诗中最著名的诗句之一，曾引起很多人的赞赏，甚至引出一些带有神秘性的传说。但也有人提出：这二句实在很平常，没有什么可夸耀的。究竟应如何看待，颇可稍加分析。\n\n　　看起来，这一联诗（特别是前一句）确实很平常，毫无锤炼之功，所写景色亦并无特别之处．但应该注意到，它很好地表现了初春之特征及诗人当时的心情。池塘周围（尤其是向阳处）的草，因为得池水滋润，又有坡地挡住寒风，故复苏得早，生长得快，其青青之色也特别的鲜嫩，有欣欣向荣的生气。但它委实太平常，一般人都注意不到。谢灵运久病初起，这平时不太引人注意的景色突然触动了他，使之感受到春天万物勃发的生机，于是很自然地得到这一清新之句。“园柳变鸣禽”，写柳枝上已有刚刚迁徙来的鸟儿在鸣叫，这同样是细微而不易察觉的变化。两句诗表现了诗人敏锐的感觉，以及忧郁的心情在春的节律中发生的振荡。再有，宋初诗坛，以谢灵运其人为代表，有一种追求佳句的风气，而通常的佳句，都以反复雕琢、精于刻画取胜。在这样的风气中，此种自然生动而富有韵味的诗句，更显得特出。总之，放在特定的文学环境和具体的诗篇之中来看，“池塘生春草，园柳变鸣禽”的确不失为佳句，单独抽出来加以评论，就没有多少意义了。从全诗来看，写到这里，情绪渐渐转向开朗欣喜的暖色调。\n\n　　第二层是全诗最精彩的部份。诗人在病榻上度过了一个冬天，现已是初春时节了。他凭窗而坐，倾耳细听远处波涛拍岸之声；举目远望群山起伏之影。而近处所见的景致则是：“池塘生春草，园柳变鸣禽。”诗人从冬去春回的众多景象中选择了一个细小而典型的镜头：不知不觉间楼外枯草瑟瑟的池塘里竟然春草繁生了；小园垂柳丛中禽鸟鸣声也已变换。正是从池塘小园的变化中，久病的诗人突然意识到，外面已是一派浓郁的春意。这里写景，有声有色，远近交错，充满了蓬勃生气。“池塘”二句为历来诗论家交口赞赏。它的妙处就在于自然清新，不假绳削。\n\n　　最后六句为第三层。开头两句由登楼观春联想到古代描写春景的诗，借用典故表示自己的感慨，情绪又转向感伤。“祁祁伤豳歌”的“豳歌”，指《诗经·豳风·七月》一篇，诗中有“采蘩祁祁”等描写春景之句。“伤豳歌”，按照《毛诗序》《诗谱》等传统的解释，《七月》是周公在遭受流言、出居东都以避谗害时作的，谢灵运用此典故，带有暗喻的意思。“萋萋感楚吟”的“楚吟”，指《楚辞·招隐士》一篇，其中有“春草生兮萋萋”之句。所谓“感楚吟”，是说有感于隐士的生活。这两句回复到第一层的内容，但并非单纯的重复，而是表示要从困窘的处境中摆脱出来，决心走隐居的道路。接着“索居”“离群”两句，写隐居生活令人难以接受的一面，意思是：离群索居的生活，使人容易感到岁月漫长，枯索无味，难以安心。这两句从诗意上说，是指一般人的想法，并非说自己。但在潜在心理上，这种被否定的想法，也隐约透露了他自己的某种疑虑。谢灵运出身华胄，为世人所重，且骄纵自负，与世隔绝的隐居生活对于他确非易事。但不管怎祥，他归隐的决心已下。全诗结束两句说：“持操岂独古，无闷征在今！”“无闷”语出《周易·乾卦》，意谓大德之人，避世而无所烦忧。这两句意思是：坚持节操岂止古人能够做到，《周易》所谓“遁世无闷”在今人身上同样可以得到征验！这样，诗的情绪便从进退维谷的困境中解脱出来，以高亢的声调收结全篇。也就在这大约半年之后，谢灵运终于称疾辞职，归隐到始宁的祖居。\n\n　　在这首诗中，诗人用各种方式来表达自己内心的郁闷，或是比兴，用虬和鸿的进退得所来说明自己进退失据；或是直抒胸臆，诉说独居异乡的孤苦；或是以景写情，用生趣盎然的江南春景，来衬托诗人内心的抑郁。\n\n　　此诗以登池上楼为中心，抒发了种种复杂的情绪。这里有孤芳自赏的情调，政治失意的牢骚，进退不得的苦闷，对政敌含而不露的怨愤，归隐的志趣等等，虽然语言颇觉隐晦，却是真实地表现了内心活动的过程。诗中写景部分与抒情结合得相当密切，并且成为诗中情绪变化的枢纽。对景物的描绘，也体现出诗人对自然的喜爱和敏感，而这正是他能够开创山水诗一派的条件。只是，语言过于深奥、句式缺少变化，因求对仗而造成某些重复，也是显著的弱点。这些都有待于诗歌的发展来纠正。', poem_tags = '春天,写景,抒情,失意,思归' WHERE poem_title = '登池上楼' AND poem_author = '谢灵运';
UPDATE edu_poem SET poem_translation = '贾谊在长沙做了三年太傅，有只鵩鸟飞进他的住所。鵩鸟长得很像猫头鹰，是不祥的鸟。贾谊因为被贬到长沙，长沙气候很潮湿，此时看到猫头鹰，认为自己寿命已不长了，于是写了一篇赋来自我安慰。赋文说：\n\n　　汉文帝六年，丁丑年，四月孟夏时节。四月里的一天太阳西斜时，有一支鵩鸟停在我的屋子上。它停在座位的一角，形态非常从容不惊。有怪物停栖于此，我心中暗中怀疑它飞来的缘故。打开书本占卜它，预示说到它吉凶的定数：“有野鸟进入我的房屋，主人即将离去。”我请求向鵩鸟发问：“我将要到哪里去呢？如果有吉事，你就告诉我，即使有凶事，也请你把什么灾祸说明。死生迟速的吉凶定数啊，请告诉我它的期限吧。”鵩鸟就叹息着，昂起头张开翅膀，口却不能说话，而请用胸中所想的来对答：\n\n　　“时间万物的变化，本来就没有停止。运转迁移，或推移回还，万物变化运转，反复无定。形与气互相移转连续变迁蜕化，精微深远，没有穷尽。福是祸的诱因，祸是福的根源。忧与喜聚集在一门之中，吉与凶同在一个区域。吴国很强大，夫差却失败了，越国栖息于会稽山，但勾践却称霸于世。李斯游于秦国，身登相位，达到成功，最终却身受五刑而死。傅说在傅岩操服劳役，殷高宗武丁以为他是贤人，用他为相。福祸相互依附纠缠，如同绳索绞合在一起，天命不可解说，谁知道他的究竟？水流矢飞，为外物所激，则或悍或远，发生变化，万物往返相激，震荡转化，人事也有时因祸而至于福，互相影响，反复无常。云因势而上升为雨，雨因冷而下降为云，事物的变化复杂纷纭。自然界造化推动万物，使之运行变化是无边无际的。天和道，其理深远，不可预为思虑谋度，死生迟速有命，哪能预知它的期限！\n\n　　天地像一个冶金之匠炉，造化像一个冶金之匠，阴阳所以铸化为物故喻为炭，物由阴阳铸化而成故喻为铜。聚散灭生怎么会有一定的法则？千变万化未必有终极。偶然为人，哪里值得贪恋珍惜，而死亡又有什么值得忧患的呢？智慧浅小的人，只顾自身，以他物为贱，以自己为贵。在达人看来，自己和万物可以相互适应，故没有一物不合适。贪婪的人为财而死，刚烈之士为名誉而死。贪求虚名的人，死于权势，一般人贪求生命。为权力所诱为贫贱所迫的人，东奔西走，趋利避害；与天地合其德的伟人不为物欲所趋，对亿万变化的事物都等量齐观，一视同仁。愚笨的人为俗界所牵连，困窘得如罪人之受拘束；有至德的人遗弃物累，独和大道同行。众人惑乱之甚，所爱所憎，积聚甚多；得天地之道的人安然宁静，独和大道相处。放弃智虑，遗弃形体，超脱于万物之外自忘其身，深远空阔，与道浮游。人生如木浮水，行止随流；把自己的身躯完全托付给命运，任凭自然，不私爱身躯把它归于自己作为私物，活着仿佛随波逐流，死去好像休憩长眠。深邃得好像深渊潭水般幽然，漂浮得好像没有羁绊的小舟般自在，涵养空虚之性而浮游，德人不被万物牵累，知天命而不忧愁。因此像鵩鸟飞入舍内这种琐细小事，又有什么值得疑虑的啊！”', poem_notes = '⑴单（chán）阏（è）：卯年的别称。这是古代太岁纪年法。\n⑵谶（chèn）：预示吉凶的话。\n⑶淹速：指寿命的长短。\n⑷斡（wò）流：运转。\n⑸沕（wù）穆：精微深远貌。\n⑹纠纆（mò）：二、三股捻成的绳子。这里比喻祸福纠缠在一起。\n⑺合散：指生死。\n⑻异物：指死亡。\n⑼夸者：指贪求虚名的人。\n⑽怵迫：怵指为利益所诱，迫指为贫贱所迫。\n⑾至人：指至德之人。\n⑿真人：指得道之人。', poem_appreciation = '第一段是简单的叙事。当一个人有着无法释怀的疑问时，总是希望有人倾听，即使得不到答案，也是一种慰藉。贾谊谪居独处，找不到别的倾听者，他只能向这只带来死亡之兆的鸟儿诉说，而这只鸟是注定无法给出答案的，它甚至也无法表示些许的同情，可见一个人面对死亡时是如此的孤独无助。鵩鸟虽然无法开口说话，但是贾谊让它具备了高妙的智慧，并且让自己能够洞透这只鸟儿的想法，这是汉赋里对话体的开始。鵩鸟所具有的思想不过是贾谊自己的思想，贾谊之所以要用这么曲折的手法来表达自己的想法，是因为这样一来他就具有了诉说者与安慰者的双重身份，也就是这篇赋序里所说的“为赋以自广”。诉说者所提出的问题是：他要到哪儿去，是凶还是吉？而安慰者却避而不答这个问题，它所回答的是：死亡不过是万物变化的一种，不值得为生留恋，为死悲伤。在这种答非所问中，贾谊其实是在强调自己对于死亡的预感。这也许是最后一次诉说，最后一次安慰自己：也许死并不那么可怕。\n\n　　第二大段是虚拟的鵩鸟的回答，实际上是贾谊在阐发自己的思想。其中引用了很多的道家思想，如物相转化、福祸无常等；生命的偶然性和死亡的超然性等；大人至人与世俗之人对人生追求的不同看法等。似乎都在渲染一种人生短暂，生命渺小和具有不确定性的人生感受；一种无欲无求，幽远宁静的生活态度；表现的是乐观而豁达的精神境界。\n\n　　这位安慰者提起了几部道家著作对于福祸、吉凶的看法，世间万物总是变动迁流，吉与凶、祸与福也总是互相转化，它举了历史上的三个例子：夫差国强而败勾践势弱而称霸、李斯游说成功而被五刑，傅说胥靡乃相武丁。作为一个政治家，这些正是贾谊关心的，第一个例子是帝王的兴衰史，后面两个，则是与贾谊身份相当的士大夫的悲喜剧。年未届而立的贾谊，在他迅速崛起又迅速衰落的仕途生涯中早已尝到了这种大喜大悲的滋味，此时，在困顿之中，他产生了一种无力感，“命不可说兮，孰知其极”，“天不可与虑兮，道不可与谋”。人对于这个世界是无力把握的，既然天道深远精妙无从探究，则不如顺应万物的变化，或者走向另一种超越——相信人处在一种无所不在的相对转化之中，在齐同万物、泯灭生死之中逍遥自得。接着贾谊从大人、至人、真人与一般凡夫俗子的人生追求中得出的对比，可以看作是窥破生命，看透人生的一种感叹，表现自己要遗世独立，顺应自然的恬淡安然。“忽然为人兮，何足控抟。化为异物兮，又何足患”，在道家的经典里，这些道理早已说得很清楚。人面对死亡的态度是“纵躯委命兮，不私与己”。在活着的时候，如果已将好恶之心去除，那么死亡到来的那一刻，就寻常得跟生命中的其他时刻一样了。吉祥之兆与不祥之兆也没有什么区别。这仿佛是死神的使者所作的演说，这只不祥之鸟的面目没有狰狞，没有残忍，也许死亡就是这么安详。中国古人对死亡的看法不是在信仰里找到归宿，而是在智慧里找到归宿。\n\n　　这篇赋引用了很多道家思想，比如第二段中的物相转化、福祸无常等，而第三段中熔炉的比喻，则来自于庄子，庄子在《大宗师》中引述了一则寓言：“有个铜匠在冶炼铜汁，铜汁突然跳起来说‘我将要成为干将、莫邪那样的宝剑！’铜匠一定认为是不祥的金属，将把它弃去不用。现在天地就像个大熔炉，万物都在里头熔炼，偶尔幻化人形，就跳起来大叫‘我是人！我是人！’天地也会认为是不祥的人，将弃去不用。”其中的思想可以用一句人们熟知的话来概括：“不以物喜，不以己悲。”实际上，整个第三段都是在渲染一种无欲无求、悠逸宁静的生活态度，表现的是乐观而豁达的精神世界。\n\n　　贾谊在《鵩鸟赋》一文中虽然含有道家对生死的看法，但又有所不同。虽然在文章中潇潇洒洒、海阔天空，贾谊的真实状态却完全不是这样：为怀才不遇而悲愤、为身心疲惫而感伤、为前途未卜而惆怅。可以感悟到作者当时的心境是一种出离的悲愤，正是这悲愤促使其在文章中处处反其道而行之，于是写得越欢娱，就越是衬出现实的凄凉；写得越洒脱，就越是衬出无力割舍的迷茫；写得越圆满，就越是衬出那颗颠沛潦倒的心，早已支离破碎。\n\n　　在艺术上，《鵩鸟赋》的形式十分奇特，它以人鸟对话而展开。这种形式是受到庄子寓言的影响，同时也开汉赋主客问答体式之先河。此赋最突出的特点是以议论为主，以议论来抒写对生命忧患的思考，来阐发人生的哲理。议论之中也常运用一些贴切的比喻，来增强议论的形象性，也常用感叹语气来加强议论的情感性。此赋语言凝炼精警，形式上以整齐的四言句为主，也有散文化的倾向，体现着向汉大赋的过渡。', poem_tags = '辞赋精选,写鸟,对话,议论,人生,哲理' WHERE poem_title = '鵩鸟赋' AND poem_author = '贾谊';
UPDATE edu_poem SET poem_tags = '悼亡,友情,组诗' WHERE poem_title = '哭李商隐' AND poem_author = '崔珏';
UPDATE edu_poem SET poem_translation = '天亮了，井台上响起了辘轳声。一夜风雨，满阶落花，凋零中透出一丝冷意。在这样一个清晨，“我”和她蓦然相逢。“我”对她一见钟情，却难以明了她迷离的眼波背后暗藏的心事。谁能明白?谁能明白呢?从此以后，无论是在簟席上辗转反侧、孤枕难眠之时，还是独对孤灯、辗转徘徊之际，我都会想念她。', poem_notes = '辘轳：井上汲水的工具。\n砌：台阶。\n蓦地：突然地。\n省（xing）：明白。', poem_appreciation = '这阕短小的《如梦令》仿佛是在描绘纳兰容若的一生，前段是满砌落花红冷，眼波心事难定的少年风流，后半段是从此簟纹灯影的忧郁惆怅，其意境心境吻合“如梦”二字。这首词最耐人咀嚼思索的便是那个“冷”字，这并不是一个单纯的情境修饰语词，而是词人心绪最真实贴切的写照。\n\n　　首句点明了相遇的地点。辘轳金井本是深庭豪门极常见的事物，但从词句一开始，这一寻常不过的并台在他心里就不一般了，“正是”二字，托出了分量。“满砌落花红冷”既渲染了辘轳金井之地的环境浪漫，又点明了相遇的时节。金井周围的石阶上层层落红铺砌，使人不忍践踏，而满地的落英又不可遏止地勾起了词人多愁善感的心绪。常人以落红喻无情物，红色本是暖色调， “落红”便反其意而用，既反映他自己寂寞阑珊的心情，也象征词中所描写的恋爱的必然结局。\n\n　　暮春时节，两人突然相逢， “蓦地”是何等的惊奇，是何等的出人意料，故而这种情是突发的，不可预料的，也是不可阻拦的。“心事眼波难定”一句惊艳妙绝，写出两人乍相逢的惊疑窃喜，极传神。伊人眼波横流，媚态撩人，然而结句则笔锋陡转，一句“簟纹灯影”将前事化空，露出相思无用的无限惆怅，使人黯然神伤。人事的残酷，藏在希望的背后，如此美妙的邂逅，也不过是昙花前的满眼芳华。\n\n　　这首初恋情词极为精巧雅致，细细读来如观仕女图般，字虽简练，情却绵密。只是幸福感过于短暂，更凸显其相思的痛苦忧伤。', poem_tags = '婉约,爱情,抒情' WHERE poem_title = '如梦令·正是辘轳金井' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '楚襄王在兰台宫游玩，由宋玉景差陪同。一阵风飒飒吹来，楚襄王就敞开衣襟迎着吹来的清风说：“这风好爽快呵！这是我与百姓共同享受的吗？”宋玉回答道：“这只是大王享受的风，百姓怎么能与王共同享受它呢！”\n楚襄王说。“风是天地间流动的空气，它普遍而畅通无阻地吹送过来，不分贵贱高下，都能吹到。现在你却认为只有我才能享受它，难道有什么理由吗？”宋玉答道。“我听老师说，枳树弯曲多叉，就容易招引鸟来作窝。有空洞的地方，风就会吹过来。由于所依托的环境条件不同，风的气势也就不同了。”\n楚襄王问道：“那风，最初是从哪里生成的呢？”宋玉答道：“风在大地上生成的，从青翠小草尖上兴起，逐渐扩展到山谷，在大山洞口怒吼，沿着大山坳，在松柏林下狂舞。疾风往来不定，形成撞击物体的声音；风势迅疾飘扬，犹如怒火飞腾，风声如雷，风势交错相杂。飞砂走石，大风摧树折木，冲击森林原野。等蓟风势逐渐平息下来，风力微弱，四面散开，只能透进小孔，摇动门栓了。风定尘息之后，景物显得鲜明灿烂，微风渐渐向四面飘散。所以使人感到清凉舒畅的雄风，就飘动升降，凌越高高的城墙，进入深深的王宫。它吹动花草，散发香气，在桂树和椒树之间往来回旋，在疾流的水徊上缓缓飞翔。于是风吹拂水上的荷花，掠过蕙草，分开秦蘅，吹平新夷，覆盖在初生的草木之上，它急剧回旋冲击山陵，致使各种芳草香花凋零殆尽。然后风就在院子里徘徊，向北吹进宫室，上升到丝织的帷帐里，进入深邃的内室，这才成为大王的风了。所以那种风吹到人身上，其情状简直凄凉寒冷得很，清凉的冷风使人为之感叹。清清凉凉的，既能治病，又可解酒，使人耳聪目明，身心安宁，这就是所说的唯大王所有的雄风呀！”\n楚襄王说。“你对这件事解说论述得太好了！那么老百姓的风，是不是也可以说给我听听呢？”宋玉回答说：“老百姓的风是从冷落偏僻的小巷中忽然刮起来的，扬起的尘土，烦躁愤懑地回旋盘转，冲击空隙，侵入门户。刮起尘沙，吹散灰堆，搅起污秽肮脏的东西，扬起腐烂的垃圾，歪歪斜斜逼近用破瓮口做的窗户，一直吹到百姓住的草屋里。所以那种风吹到人身上，其情状简直令人心烦意乱，忧郁苦闷，受到闷热之气，得了湿病，使人内心愁昔，生病发烧。风吹到嘴唇上就生唇疮，吹刭眼睛上就使得眼睛红肿，受风得病后使人嘴巴抽搐，咬牙吮咂大叫，陷于半死不活状态。这就是所讲的老百姓的雌风呀。”', poem_notes = '楚襄王：即楚顷襄王，名横，楚怀王之子，周赧王十七年至五十二年（前—前）在位。\n兰台之宫：朝廷收藏典籍收罗文士之所，也为楚王冶游之处，在郢都以东，汉北云梦之西。\n景差：楚大夫，《汉书·古今人表》做“景磋”。“差”为“磋”之省借。\n侍：站立左右侍候，这里指随从。\n飒：风声。\n披襟：敞开衣襟。\n当之：迎着风。当，对着，面对。\n寡人：古代君王对自己的谦称，意为“寡德之人”。\n庶人：众人，指人民。\n共：指共同享有。\n邪：同“耶”，疑问语气词。\n独：唯独，只是。\n安：疑问代词，怎么。\n得：得以，能够。\n溥：通“普”，普遍。\n畅：畅通。\n枳：一种落叶小乔木，也称枸橘，枝条弯曲，有刺。\n句（gōu）：弯曲。\n来：招致。\n巢：用作动词，筑巢。\n空穴来风：有洞穴的地方就有风进来。空穴，连绵词，即孔穴。\n其：指“鸟巢”和“风”。\n托：依靠，凭借。\n然：如此，这样。\n殊：异，不同。\n夫：句首发语词，无实义。\n始：开始，最初。\n安：怎样。\n青蘋（pín）之末：即青蘋的叶尖。蘋，蕨类植物，多年生浅水草本。亦称“四叶菜”，“田字草”。\n侵淫：渐渐进入。\n溪谷：山谷。\n盛怒：暴怒，形容风势猛烈。\n囊（náng）：洞穴。\n缘：沿着。\n泰山：大山。泰：通“太”。\n阿（ē）：山曲。\n飘忽：往来不定的样子，此处形容风很大。\n淜滂（péng pāng）：大风吹打物体发出的声音。\n激飏（yáng）：鼓动疾飞。\n熛（biāo）怒：形容风势猛如烈火。熛，火势飞扬。\n耾耾（hóng hóng）：风声。\n雷声：言风声如雷。\n回穴：风向不定，疾速回荡。\n错迕（wǔ）：盘旋错杂貌。\n蹶（jué）石：摇动山石，飞沙走石。蹶，撼动。\n伐木：摧断树木。\n梢（shāo）杀林莽（mǎng）：摧毁树林和野草。梢杀，指毁伤草木。莽，草丛。\n被丽披离：皆连绵词，四散的样子。\n冲孔：冲进孔穴。\n动楗（jiàn）：吹动门闩。楗，门闩。\n眴（xuàn）焕粲烂：皆连绵词，色彩鲜明光华灿烂的样子。\n离散转移：形容微风向四处飘散的样子。\n飘举：飘飞飘动的意思。\n升降：偏义复词，“升”意。\n乘凌：上升。乘，升。\n高城：高大的城垣。\n深宫：深邃的宫苑。\n邸（dǐ）：通“抵”，触。\n华：同“花”。\n振：摇动振荡。\n桂：桂树，一种香木。\n椒（jiāo）：花椒，一种香木。\n翱翔：形容风像鸟一样在空中翱翔回旋。\n激水：激荡的流水，犹言急水。\n芙蓉之精：芙蓉的花朵。精，通“菁”，即华（花）。\n猎：通“躐”，践踏，此处为吹掠之意。\n蕙（huì）：香草名，和兰草同类。\n离：经历。《史记·苏秦列传》张守节《正义》：“离，历也。”\n秦蘅：本产于秦地（今天水一带）的一种杜衡。\n概：古代量谷物时刮平斗斛的器具，此处为吹平意。\n新夷：即“辛夷”，又名“留夷”，一种香草。\n被：覆盖，此处为掠过之意。\n荑（tí）杨：初生的杨树。\n回穴冲陵：回旋于洞穴之中，冲激于陵陆之上。冲，冲撞。陵，通“凌”，侵犯。\n萧条众芳：使各种香花香草凋零衰败。萧条在此处用为动词。\n倘佯（cháng yáng）：犹“徘徊”。\n中庭：庭院之中。一说即位置居中的庭院。\n玉堂：玉饰的殿堂，亦为殿堂的美称。\n跻（jī）：上升，登上。\n罗帏（wéi）：用丝罗织成的帷幔。\n洞房：指宫殿中深邃的内室。洞，深。\n中（zhòng）人状：指风吹到人身上的样子。中，吹中，吹到。状，状况，情形。\n直：特意，特别。\n憯（cǎn）凄：凄凉悲痛的样子。\n惏栗：寒冷的样子。\n增：通“层”，重复，反复。\n欷（xī）：唏嘘。本是叹息或叹息声，这里是说在酷热的天气，遇到一阵清凉的风吹来，不禁爽快地舒了一口气。\n清清泠（líng）泠：清凉的样子。\n愈病：治好病。\n析酲（chéng）：解酒。酲，病酒，酒后困倦眩晕的状态。\n发明耳目：使耳目清明。发，开。明，使之明亮。\n宁体便人：使身体安宁舒适。\n论事：分析事理。\n岂：通“其”，表示期望。\n塕（wěng）然：风忽然而起的样子。\n穷巷：偏僻小巷。\n堀（kū）堁（kè）：风吹起灰尘。堀，冲起。堁，尘埃。\n勃郁：抑郁不平。\n烦冤：烦躁愤懑。\n袭：入。\n沙堁：沙尘，沙土。\n死灰：冷却的灰烬。\n骇：惊起。此处为搅动之意。\n溷（hùn）浊：指污秽肮脏之物。溷，通“混”。\n腐馀（yú）：腐烂的垃圾。\n邪薄：指风从旁侵入。邪，通“斜”。薄，迫近。\n瓮牖（wèng yǒu）：在土墙上挖一个圆孔镶入破瓮做成的窗户。瓮，一种圆底圆口的陶制器。牖，窗户。\n室庐：指庶人所居住的简陋小屋。庐，草屋。\n憞（dùn）溷：烦乱。\n郁邑：忧闷。\n殴温致湿：驱来温湿之气，使人得湿病。殴，通“驱”。\n中心：即心中。\n惨怛（dá）：悲惨忧伤。怛，痛苦。\n造热：得热病。\n中唇：吹到人的嘴唇上。\n胗（zhěn）：唇上生的疮。\n得目为蔑：吹进眼里就得眼病。\n啗齰嗽获（dàn zé sòu huò）：中风后口动的样子。啗，吃。齰，咬。嗽，嚼。嗽，吸吮。获，大叫。\n死生不卒：不死不活。此言中风后的状态。生，活下来，指病愈。卒，通“猝”，仓卒，比较快地。', poem_appreciation = '风没有生命，本无雄雌之分，但王宫空气清新，贫民窟空气恶浊，这乃是事实。作者从听觉、视觉、嗅觉对风的感知不同，生动、形象、逼真地描述了“雄风”与“雌风”的截然不同，反映了帝王与贫民生活的天壤之别。前者骄奢淫逸，后者凄惨悲凉。寓讽刺于描述之中，意在言外。\n\n　　帝王幽居深宫，生存环境优越，肆虐的狂风进了高城深宫，早已化为清凉治病的和风；而生活在穷巷贫窟的庶民生存环境恶劣，没有防护实施，狂风肆意侵凌，无奈的遭受着风的凄苦。正如文中指出“枳勾来巢，空穴来风，所托者然也，则风气也殊焉。”因为生存条件的不同，所以对风的感受也就不同，风带给帝王的是享受，带给贫民的是灾难。不管宋玉是插科打诨，逗帝王开心，还是暗藏讽谏，风带给不同条件的人的祸福感受是客观存在的。\n\n　　文章从开头到“臣闻於师：枳句来巢，空穴来风。其所托者然，则风气殊焉。”为第一段。这段通过引起“雄风”和“雌风”论辩的背景，提出风气带给人不同感受的论点。\n\n　　第二段论述了风的形成、起源以及由弱到强、由强衰弱直至进入深宫化为清风四处飘散吸取万物精华而后带给帝王享受的过程。肆虐的狂风在入城前飘散为清风乘越高墙入於深宫，摇动华叶，徘徊香木之间，寻取其幽香；临池采芙蓉芳香；出水掠蕙草浓香；劈开秦衡，摆动新夷掠取清香，披开荑杨收取嫩香，然后带着五香的新鲜徜徉中庭，北上玉宫，又通过层层帷幕进入深宫。这段描写颇为生动，像是描写一个殷情而又谨慎的君王侍臣，小心的调制着君王需求的和风。这里对风的描写暗喻了帝王贪欲的神圣特权，以及臣民伺候帝王的恭敬与虔诚。帝王得到的不像是自然的风，而是精心调制的服务。这风带给帝王的享受，好像是一付神药，这种轻松与愉悦像是病愈酒醒，耳聪目明，舒服至极，使得帝王不由的感叹“好痛快！”这就是帝王享受的雄风。这也是对帝王的生活侧面写照，揭示了帝王生活的奢求与贪欲。\n\n　　第三段论述了庶人的风。突然起於闭塞的巷道中，扬起沙尘，像愤怒的冤魂恶鬼叫嚣着冲孔袭门。光这来势，就让人感觉这风对于贫民不怀好意的侵犯是何等的嚣张可怕啊！继而卷起沙粒，吹起死灰，搅起污秽肮脏的垃圾，扬起腐臭的气味，斜插进破瓮做的窗户，直冲茅庐。这阴风在贫窟里肆意妄为，使得贫民头昏胸闷，伤心劳神，疲软无力，继而发烧生病，吹到嘴上生口疮，吹到眼上害红眼病，进而嘴巴抽搐吮动，咿呀叫喊，说不出话来，得了中风病。这就是庶人的雌风。通过这段描写，我们可以深切感受的庶民生存环境的恶劣，以及庶民生存的艰难与痛苦。\n\n　　通过帝王的雄风与贫民的雌风，我们深切感受到同在一片蓝天下的生命是如此的不平等。这不平等的根源不是自然灾害，而是人权的肆意践踏。因为生存环境的不同，造成雄风带来的是无与伦比的享受，而雌风带来的是欲哭无泪的灾殃。', poem_tags = '辞赋精选,写风,忧国忧民' WHERE poem_title = '风赋' AND poem_author = '宋玉';
UPDATE edu_poem SET poem_translation = '注释 蕃：吐蕃。 沙州：治所在今敦煌。', poem_appreciation = '这首《凉州词》与其说它有一定的艺术价值，莫不如说更具有史料价值。从诗中“沙州”、“凉州”等地名可以推断，反映的是中唐河湟(今青海)一带的战事。此地本是吐谷浑领地，后来因闹内哄，国王被部下杀死，唐朝一度降服了那里的军队。但凶悍的吐蕃不断侵扰，经过多年的战争，便把这片土地争夺过去。\n\n　　公元851年一天的夜里，沙州的节度使(又称都护)张义潮乘吐蕃的内乱，率领当地的蕃兵(为唐朝守边的少数民族士兵)一举夺取了凉州，收回了被吐蕃占领的属地，这便是诗中头两句：“昨夜蕃兵报国仇，沙州都护破凉州。”第三句的“黄河九曲今归汉”，颇有自豪的味道，流过九十九道弯的、绵延数千里的黄河终于又回到唐朝(唐代诗人多以“汉”代“唐”)，可是第四句便转出了悲凉：“塞外纵横战血流!”战乱并没有因这次军事上的胜利而终止，人民依然在流血。这句是指吐蕃内部的纷争，论恐热发动叛乱长达二十余年，据《通鉴》所载：“所过残灭，尸相枕籍”，“杀其壮丁……焚其室庐，五千里间，赤地殆尽。”由此看来，诗人为祖国军队收复失地而产生的喜悦之情，又为吐蕃人民深受内乱之苦而冲淡。这悲喜情感的起伏，使这首小诗的主题从爱国主义的层次上升到人道主义的领域。诗人是爱国的，但他更呼吁把和平和安宁还给各族人民！\n\n　　这首诗，是反映张义潮收复凉州、吐蕃内乱史实的唯一的一篇作品。', poem_tags = '爱国' WHERE poem_title = '凉州词' AND poem_author = '薛逢';
UPDATE edu_poem SET poem_translation = '译文 秋天阴云密布,夜晚略微感到寒气。 只觉得衣裳潮湿,没有雨点也没有风声。', poem_tags = '秋天,写雨' WHERE poem_title = '微雨夜行' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '春天来了，我这个远离家乡的人，什么时候才能回家呢？最让我悲伤的是，连那江城的大雁都可以自由自在地向北飞去，而我却挪不动步呢。', poem_notes = '此二句，自问自。客，指自己。几年，犹几时。东，一作“春”。\n末句正是申明“肠断”之故。', poem_appreciation = '“东来万里客，乱定几年归？”点明了时间和客居情况，表达急切渴望回归故乡的心情。安史之乱以后，八年来，杜甫带着一家老小背井离乡，从长安、洛阳、秦州辗转流离到四川成都。诗中“东来”二字亦作“春来”。这年初春，他在川北的阆州飘泊时，就已经作好了准备，打算由水路下渝州出峡，以便回河南老家。但由于老朋友严武第二次到成都任东西川节度使，邀请杜甫到成都，于是打消了出峡的念头，举家重新迁回成都草堂居住。“万里客”三字，饱含着经年奔波的凄楚况味和浓烈的乡思之情。此时，安史之乱已经平息，按说应当回家了。他在不久前写的“生平第一首快诗”（浦起龙语）《闻官军收河南河北》中，就满怀激情地表示过：“白日放歌须纵酒，青春作伴好还乡。即从巴峡穿巫峡，便下襄阳向洛阳。”如今又来到成都，早就萦绕于怀的回乡之愿，不知要到何年才能实现？一个问句，表现了诗人渴望回乡而不能的急迫心情。\n\n　　正当诗人为乡情所苦、愁思百结的时候，一队队大雁正从滨临锦江的成都上空，高高地向北归飞。“高高”有自由自在、畅通无阻之意。大雁北飞之地就是中原地带，它既是作者故乡的所在地，也是唐王朝中央政权的所在地。诗人想到大雁一年一度地回到故乡，而自己却多年滞留异地，不禁愁思缕缕。\n\n　　这首诗短小精悍，含义隽永，余味无穷。这原因，一方面是诗人将自己的一片真情，融于字里行间，在平易朴实的语言里，蕴含着强烈的激情。另一方面，写归雁的诗，往往都是先从大雁本身着笔，然后再抒发议论，然而这首诗却是先写思归的心情，一开始就直抒胸怀，先给读者一个思乡的强烈印象，然后再将描写的笔触对准空中的大雁，让生动的形象去充分体现作者的思想，给人以具象化的感觉，先赋而后兴。\n\n　　不仅使情景交融，也使思乡恋国之情表达得更为强烈，更为深长。另外，在绝句格式上，这一首采用了对起散结的方式。盛唐绝句重散行，四个散句起承转合，句与句之间不讲究对偶。而此诗一、二句用了对偶。后两句用散句，又纯任天然。这样，在形式上把精巧与自然二者有机结合起来，读来节奏优美，“神味高远”（浦起龙语）。杜甫“常常把绝句作为遣兴手段，即兴漫成，但这并不妨碍他在形式上有意识进行多种尝试。”（周啸天《唐绝句史》）从这首五言绝句中，也可以看出杜甫“语不惊人死不休”的创作态度。', poem_tags = '写鸟,思乡' WHERE poem_title = '归雁' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '注释 应诏：诏，皇帝的颁发的命令文告。应诏，旧指奉皇帝之命而做诗文。应诏诗又称应制诗，唐代以后大都为五言六韵或八韵的排律。除夜：即除夕，一年最后一天的晚上，也指一年的最后一天。唐代诗人杜审言《守岁侍宴应制》诗有“季冬除夜接新年”句。 逐（zhú）：追随。 风光：时光，春光。著（zhuó）：“着”的本字。附着，贴近。唐代皎然《寻陆鸿渐不遇》有“近种篱边菊，秋来未著花”句，“著花”一词意为长出花蕾或花朵。这里“著后园梅”采用此意。这两句诗的意思是，人们没有感觉到春光的到来，已催开了后园的梅花。', poem_tags = '春节' WHERE poem_title = '应诏赋得除夜' AND poem_author = '史青';
UPDATE edu_poem SET poem_translation = '子说：“我大约十五岁志于学习尧、舜、禹、汤、文、武等先王之道。认真研究历史，用心学习《诗》、《礼》、《书》等文化。三十岁时，我的学说已经建立了基础，我也可以以我的学说立身于社会。四十岁时，我已知道我的学说是上天的旨意，故能信道不疑。虽听到各种议论，也不疑惑动摇。五十岁时，我已经明白道就是天。同时明白我是上天的仆人，上天交给我的使命就是修道、传道。六十岁时，一听别人的话，就能准确的理解，并能辨别判断他的话正确与否。如果他的话有错误，我也知道他的话错在什么地方，为什么错。而我的判断也符合上天的旨意。别人提出的问题，我也能立即回答。而我的回答也符合上天的旨意。七十岁时，天在我里面，我在天里面，天与我同在，天与我合一。因此能随心所欲也不逾越上天的规矩、法则。”\n\n　　这是孔子对自己一生各阶段的总结。\n\n　　孔子说：“君子，吃食不要求饱足，居住不要求舒适，对工作勤劳敏捷，说话却谨慎，到有道的人那里去匡正自己，这样，可以说是好学了。”\n\n　　孔子说：“吃粗粮，喝冷水，弯着胳膊来做枕头，这样做我很快乐。用不正当的手段使自己富有、尊贵，这对我如同浮云一般（指不值得关心）。”\n\n　　敝緼袍：敝，破坏义。緼，乱絮。古无木棉，袍皆以絮。絮之好者称绵，如今之丝绵\n\n　　狐貉：以狐貉之皮为裘，裘之贵者。\n\n　　其由也与：《檀弓》，子路曰：“伤哉贫也，生无以为养，死无以为礼也。”《家语》：子路为亲负米。则衣敝緼袍乃实况，非设辞。\n\n　　不忮不求，何用不臧：此《卫风•雄雉》之诗。忮，害义。嫉人之有而欲加以害伤之心也。求，贪义。耻己之无而欲求取于人。臧，善义。若能不忮不求，则何为而不善?\n\n　　是道也，何足以臧：孔子引诗以美子路，子路终身诵之。是以一善沽沾自喜，将不复于道更求进，故孔子复言此以警之。或说：不忮不求以下当别为一章。今按：不忮不求，正承上敝组狐貉之对立来，分章则义不见，今不从。\n\n　　先生说：“穿着破旧的绵絮袍，和穿狐裘的人同立在一起，能不感为耻辱的，只有由了吧!”“《诗经》上说不忮刻，不贪求，这有什么不好呀?”子路听了，从此常诵止此诗。先生说：“这样又何够算好呀。”\n\n　　子贡问怎样培养仁德。孔子说：“工匠要做好他的工作，一定要磨快他的工具。我们住在这个国家里，就要敬奉那些贤能的大夫，结交那些仁德的士人。”\n\n　　“为仁”，培养仁德，修炼仁德。子贡问如何培养仁德，孔子回答怎样做事。敬奉贤德的大夫，结交仁德的士人，目的是为了培养仁德，人的才德，是经过磨砺熏陶形成的；工匠磨快他的工具，目的是为了做好他的工作，工匠的工具是经过切磋琢磨形成的。二者一个是为了培养仁德，一个是为了做好工作，把做事比喻成为仁。做事须要锋利的工具，培养仁德须要敬奉结交贤德之人；有了锋利的工具就能做好事情，有了学习贤人的机会就能培养仁德。\n\n　　此文明确地告诉人们，培养仁德必须深入社会进行磨砺，以谦恭的态度尊重贤德之人，以真诚的行动结交仁德之士，有了这样的机会和环境，就能成功地修炼仁德。\n\n　　注釋：（1）“善其事”，做好他的工作。“善”，做好。“事”，工作。（2）“利”，磨鋒利。“器”，工具。（3）“事其大夫賢者”，“事”，敬奉。“友”，結交朋友。\n\n　　子贡问孔子说：“全乡人都喜欢、赞扬他，这个人怎么样？”孔子说：“这还不能肯定。”子贡又问孔子说：“全乡人都厌恶、憎恨他，这个人怎么样？”孔子说：“这也是不能肯定的。最好的人是全乡的好人都喜欢他，全乡的坏人都厌恶他。”\n\n　　孔子对子贡说，“你和颜回比哪个更强些？”子贡答道，“我怎么敢和颜回相比呢？颜回能闻一知十，我只能闻一知二。”孔子说，“不如啊，我和你都不如啊！”▲', poem_tags = '哲理' WHERE poem_title = '论语七则' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '孟夏的时节草木茂盛，绿树围绕着我的房屋。众鸟快乐地好像有所寄托，我也喜爱我的茅庐。\n耕种过之后，我时常返回来读我喜爱的书。居住在僻静的村巷中远离喧嚣，即使是老朋友驾车探望也掉头回去。\n（我）欢快地饮酌春酒，采摘园中的蔬菜。 细雨从东方而来，夹杂着清爽的风。\n泛读着《周王传》，浏览着《山海经图》。（在）俯仰之间纵览宇宙，还有什么比这个更快乐呢？', poem_notes = '这组诗共十三首，这是第一首。山海经：一部记载古代神话传说、史地文献、原始风俗的书。\n孟夏：初夏。农历四月。\n扶疏：枝叶茂盛的样子。\n欣有托：高兴找到可以依托的地方。\n深辙：轧有很深车辙的大路。\n频回故人车：经常让熟人的车调头回去。\n欢然：高兴的样子。\n与之俱：和它一起吹来。\n泛览：浏览。周王传：即《穆天子传》，记载周穆王西游的书。\n流观：浏览。山海图：带插图的《山海经》。\n俯仰：在低头抬头之间。终宇宙：遍及世界。', poem_tags = '古诗三百首,田园,读书' WHERE poem_title = '读山海经·其一' AND poem_author = '陶渊明';
UPDATE edu_poem SET poem_translation = '君王当年离开了人间，将军破敌收京让开了山海关。全军痛哭披上了缟素，哪知道将军冲冠一怒是为了红颜。还说红颜流落不是他所系恋，还说逆贼命定灭亡是因为迷于饮宴。像闪电般扫荡黄巾平定黑山．哭毕君王和老父亲再和她相见。\n　　初次和她相见是在田弘遇之家，侯门的歌舞演起来真像繁花。田弘遇把会演唱的她献给将军，只等将军来娶就送上油壁香车。她的家本在姑苏浣花里，小名叫圆圆衬上罗绮更娇丽。她曾在梦里到当年夫差的宫苑里游嬉，被宫娥拥簇进去君王正身起。她前身真应是西施采莲女，门前也正临横塘水清碧。横塘里双桨摇动船去快如飞，哪家豪门硬要把她强买回。这时谁知不是薄命。这时只有泪湿褛表。田弘遇将陈圆圆送入宫中，可明眸皓齿的她竟没有获得君王怜惜。从宫掖里领回来仍留在田弘遇家，让她练好时兴歌曲来倾倒贵客。责客们传杯宴饮直到日暮，哀弦中她的心曲向谁倾诉。只有平西伯这位白净英俊的少年，拣中了花枝对她频频回顾。该早点把她这娇乌带出牢笼，要等什么时候才能把银河飞渡。只恨军书拼死地催促，只好留下信约把人耽误。相约恩深但相见可难，一朝蚁贼拥满了长安。可怜她本是思妇楼头的杨柳，却被人当作天边的杨花相看。像索取绿珠那样围住了内宅，硬是她叫出了雕栏。如果不是将军大获全胜，哪能用匹马载她归还。\n　　她在马上一路传呼前进．云鬟还来不及梳整可惊魂已定。战场上点起蜡炬把她迎到，她满面啼痕还残留着红印。奏起箫鼓将军专征兵进秦川，金牛道上有车马千乘。斜谷里云深之处是她的画楼。散关前明月西落她打开了妆镜。消息传遍了江南水乡．乌栖泛红已经历十度秋霜。可怜她当年教她歌曲的妓师还操旧业，和她一同演奏的女伴也记起这位同行。在旧巢里本都是衔泥的燕子，她却飞上了枝头变成凤凰。女伴们只好老是在宴会上悲叹年龄长大，而她却找了个好夫婿贵为侯王。当年正为有了声名反受累，贵戚豪门都抢着要延致。一斛明珠的身价给她带来万斛的愁思．关山漂泊瘦损了她的腰肢。但也不必怨恨飘扬落花的狂风，无边春色到来已使天地呈现芳姿。\n　　曾听说有了倾国倾城的美人，反而使周郎损伤了声名。妻子怎应影响大局，英雄无夸过于多情。全家的白骨早已化为灰土，一代红妆已照耀汗青。君不见，当年馆娃宫刚盖起鸳鸯双飞双宿，花朵般的西施君王怎么看也不会厌足。可是如今采香径尽是尘土只有鸟在啼叫，响尿廊也不见人迹空让苔长青绿。换羽移宫使万里之外也生愁，珠歌翠舞还热闹在咕梁州。给君另唱了一首吴宫曲，汉水向东南日日夜夜不停地奔流。', poem_notes = '鼎湖：典出《史记·封禅书》。传说黄帝铸鼎于荆山下，鼎成，有龙垂胡须下迎黄帝，黄帝即乘龙而去。后世因称此处为“鼎湖”。常用来比喻帝王去世。此指崇祯帝自缢于煤山（今景山）。\n敌：指李自成起义军。\n玉关：即玉门关，这里借指山海关。\n恸（tòng）哭：放声痛哭，号哭。\n缟（gǎo）素：丧服。\n冲冠一怒：即怒发冲冠，典出《史记·廉颇蔺相如列传》。\n红颜：美女，此指陈圆圆。\n天亡：天意使之灭亡。\n荒宴：荒淫宴乐。\n黄巾：汉末农民起义军，这里借指李自成。\n黑山：汉末农民起义军，这里借指李自成。\n君：崇祯帝。\n亲，吴三桂亲属。吴三桂降清后，李自成杀了吴父一家。\n田窦（dòu）：西汉时外戚田蚡、窦婴。这里借指崇祯宠妃田氏之父田宏遇。\n侯门：指显贵人家。\n戚里：皇帝亲戚的住所，指田府。\n箜篌伎（kōng hóu jì）：弹箜篌的艺妓，指陈圆圆。\n油壁车，指妇女乘坐的以油漆饰车壁的车子。\n姑苏：即苏州。\n浣（huàn）花里：唐伐名妓薛涛居住在成都浣花溪，这里借指陈圆圆在苏州的住处。\n娇罗绮（qǐ）：长得比罗绮（漂亮的丝织品）还群艳美丽。\n夫差（fū chāi）：春秋时代吴国的君王。\n宫娥：宫中嫔妃、侍女。\n合：应该。\n采莲人：指西施。\n横塘：地名，在苏州西南。\n熏天：形容权势大。\n宫掖（yè）：皇帝后宫。\n永巷（yǒng xiàng）：古代幽禁妃嫔或宫女的处所。\n良家：指田宏遇家。\n倾：使之倾倒。\n飞觞（shāng）：一杯接一杯不停地喝酒。\n白皙通侯：画色白净的通侯，指吴三桂。\n花枝：比喻陈圆圆。\n银河几时渡：借用牛郎织女七月初七渡过银河相会的传说，比喻陈圆圆何时能嫁吴三桂。\n抵死：拼死，拼命。\n蚁贼：对起义军的诬称。\n长安：借指北京。\n可怜思妇：意谓陈圆圆已是有夫之人，却仍被当作妓女来对待。\n天边粉絮：指未从良的妓女。粉絮：白色的柳絮。\n遍索：意谓李自成部下四处搜寻圆圆。\n绿珠：晋朝大臣石崇的宠姬。\n内第：内宅。\n绛树（jiàng shù）：汉末著名舞妓。这里二人皆指陈圆圆。\n壮士：指吴三桂。\n争得：怎得，怎能够。\n蛾眉：喻美女，此指圆圆。\n云鬟（huán）：高耸的环形发髻\n专征：指军事上可以独当一面，自己掌握征伐大权，不必奉行皇帝的命令。\n秦川：陕西汉中一带。\n金牛道：从陕西沔县进入四川的古栈道。\n千乘（qiān shèng）：这里指千辆，虚指车辆之多。\n斜谷：陕西郿县西褒斜谷东口。\n画楼：雕饰华丽的楼房。\n散关：在陕西宝鸡西南大散岭上。\n乌桕（jiù）：树名。\n浣纱女伴：西施入吴宫前曾在绍兴的若耶溪浣纱。这里是说陈圆圆早年做妓女时的同伴。\n尊：酒杯。老大：年岁老大。\n有人：指陈圆圆。\n延致：聘请。\n斛（hú）：古代十斗为一斛。\n细：指瘦损。\n倾国：形容极其美貌的女子。\n倾城：形容极其美貌的女子。典出《汉书·李夫人传》：“北方有佳人，绝世而独立。一顾倾人城，再顾倾人国。”\n周郎：指三国时吴国名将周瑜，因娶美女小乔为妻而更加著名。这里借喻吴三桂。\n一代红妆：指陈圆圆。\n照汗青：名留史册。\n馆娃：即馆娃宫，在苏州附近的灵岩山，吴王夫差为西施而筑。\n越女：指西施。\n香径：即采香径，在灵岩山附近。\n屧（xiè）廊：即响屧廊，吴王让西施穿木屐走过以发出声响来倾听。欣赏的一条走廊，在馆娃宫。\n羽、宫：都是古代五音之一，借指音乐。这皇是用音调变化比喻人事变迁。\n珠歌：指吴三桂沉浸于声色之中。\n古梁州：指明清时的汉中府，吴三桂曾在汉中建藩王府第，故称。\n别唱：另唱。\n吴宫曲：为吴王夫差盛衰所唱之曲，此指《圆圆曲》。\n汉水：发源于汉中，流入长江。此句语出李白《江上吟》诗：“功名富贵若长在，汉水亦应西北流。”暗寓吴三桂覆灭的必然性。', poem_tags = '长篇,叙事' WHERE poem_title = '圆圆曲' AND poem_author = '吴伟业';
UPDATE edu_poem SET poem_translation = '登楼极目四望，不觉百感交集，可叹自己的这番心意，古往今来，又有几人能够理解呢？镇江一带的山川形势极其险要，简直是鬼斧神工，非人力所能致。然而这样险要的江山却不被当作进取的凭藉，而是都看成了天设的南疆北界。镇江北面横贯着波涛汹涌的长江，东、西、南三面都连接着起伏的山岗。这样的地理形势，正是进可以攻，退可以守，足以与北方强敌争雄的形胜之地。六朝的旧事，原来全不过是为少数私家大族的狭隘利益打算！\n　　于是笑王谢等人，他们空洒英雄之泪，却无克服神州的实际行动。他们依仗着长江天险，自以为可以长保偏安，哪里管得到广大的中原地区，长久为异族势力所盘踞，广大人民呻吟辗转于铁蹄之下呢？凭借这样有利的江山形势，正可长驱北伐，无须前怕狼，后怕虎，应该象当年的祖逖那样，中流击水，收复中原。南方并不乏运筹帷幄、决胜千里的统帅，也不乏披坚执锐、冲锋陷阵的猛将，完全应该象往日的谢安一样，对打败北方强敌具有充分信心，一旦有利之形势已成，便当长驱千里，扫清河洛，收复国土，何须顾虑对方的强大呢？', poem_notes = '①多景楼：在江苏镇江市北固山上甘露寺内，北面长江。\n②王谢诸人：泛指当时有声望地位的士大夫。\n③小儿破贼：《通鉴》记淝水之战、谢安得驿书，知秦兵已破，时方与客围棋，摄书置床上，围棋如故。客问之，徐答曰：“小儿辈遂已破贼。”当时率军作战的是其弟侄，故称“小儿辈”。\n④强对：强敌也。', poem_appreciation = '这是一首借古论今之作。多景楼，在镇江北固山上甘露寺内，北临长江。这首词的写作背景是孝宗淳熙十五年春天，陈亮到建康和镇江考察形势，准备向朝廷陈述北伐的策略。词的内容以议论形势、陈述政见为主，正是与此行目的息息相通的。\n\n　　开头两句，凌空而起。撇开登临感怀之作先写望中景物的俗套，大笔挥洒，直抒胸臆，借景抒情：登楼极目四望，不觉百感交集，可叹自己的这番心意，古往今来，又有几人能够理解呢？因为所感不止一端，先将“此意”虚提，总摄下文。南宋乾道年间镇江知府陈天麟《多景楼记》说：“至天清日明，一目万里，神州赤县，未归舆地，使人慨然有恢复意。”对于以经济之略自负的词人来说，“恢复意”正是这首词所要表达的主题思想，围绕这个主题思想的还有对南北形势及整个抗金局势的看法。以下抒写作者认为“今古几人曾会”的登临意。“今古”一语，暗示了此词是借古论今。\n\n　　接下来两句，从江山形势的奇险引出对“天限南疆北界”主张的抨击。“鬼设神施”，是形容镇江一带的山川形势极其险要，简直是鬼斧神工，非人力所能致。然而这样险要的江山却不被当作进取的凭藉，而是都看成了天设的南疆北界。当时南宋统治者不思进取，苟且偷安，将长江作为拒守金人南犯的天限，作者所抨击的，正是这种藉天险以求苟安的主张。“浑认作”三字，亦讽亦慨，笔端带有强烈感情。\n\n　　“一水横陈，连岗三面，做出争雄势。”镇江北面横贯着波涛汹涌的长江，东、西、南三面都连接着起伏的山岗。这样的地理形势，正是进可以攻，退可以守，足以与北方强敌争雄的形胜之地。“做出”一语，表达了词人目击山川形势时兴会淋漓的感受。在词人眼中，山川仿佛有了灵气和生命，活动起来了。\n\n　　他在《戊申再上孝宗皇帝书》中写道：“京口连岗三面，而大江横陈，江旁极目千里，其势大略如虎之出穴，而非若穴之藏虎也。”所谓“虎之出穴”，也正是“做出争雄势”的一种形象化说明。这里对镇江山川形势的描绘，本身便是对“天限南疆北界”这种苟安论调的否定。在作者看来，山川形势足以北向争雄，问题在于统治者缺乏争雄的远大抱负与勇气。因此，下面紧接着就借批判六朝统治者，来揭示现实中当权者苟安论调的思想实质：“六朝何事，只成门户私计？”前一句是愤慨的斥责与质问，后一句则是对统治者划江自守的苟安政策的揭露批判，——原来这一切全不过是为少数私家大族的狭隘利益打算！词锋犀利，入木三分。\n\n　　换头“因笑”二字，承上片结尾对六朝统治者的批判，顺势而下，使上下片成为浑然一体。前三句用新亭对泣故事，“王谢诸人”概括东晋世家大族的上层人物，说他们空洒英雄之泪，却无克服神州的实际行动，借以讽刺南宋上层统治集团中有些人空有慷慨激昂的言辞，而无北伐的行动。“也学英雄涕”，讽刺尖刻辛辣，鞭辟入里。\n\n　　“凭却长江，管不到、河洛腥膻无际。”他们依仗着长江天险，自以为可以长保偏安，哪里管得到广大的中原地区，长久为异族势力所盘踞，广大人民呻吟辗转于铁蹄之下呢？这是对统治者“只成门户私计”的进一步批判。“管不到”三字，可谓诛心之笔。到这里，由江山形势引出的对当权者的揭露批判已达极致，下面转面承上“争雄”，进一步正面发挥登临意。\n\n　　“正好长驱，不须反顾，寻取中流誓。”中流誓，用祖逖统兵北伐，渡江击楫而誓的故实。在词人看来，凭借这样有利的江山形势，正可长驱北伐，无须前怕狼，后怕虎，应该象当年的祖逖那样，中流击水，收复中原。这几句词情由前面的愤郁转向豪放，意气风发，辞采飞扬，充分显示出词人豪迈朗爽的胸襟气度。\n\n　　歇拍二句，承上“长驱”，进一步抒写必胜的乐观信念。“小儿破贼”见《世说新语·雅量》。淝水之战，谢安之侄谢玄等击败苻坚大军，捷报送达，谢安方与客围棋，看书毕，缄默无语，依旧对局。客问淮上利害，答曰：“小儿辈大破贼。”“强对”，强大的对手，即强敌。《三国志·陆逊传》：“刘备天下知名，曹操所惮，今在境界，此强对也。”作者认为，南方并不乏运筹帷幄、决胜千里的统帅，也不乏披坚执锐、冲锋陷阵的猛将，完全应该象往日的谢安一样，对打败北方强敌具有充分信心，一旦有利之形势已成，便当长驱千里，扫清河洛，收复国土，何须顾虑对方的强大呢？作者《上孝宗皇帝第一书》中曾言：“常以江淮之师为虏人侵轶之备，而精择一人之沈鸷有谋、开豁无他者，委以荆襄之任，宽其文法，听其废置，抚摩振厉于三数年之间，则国家之势成矣。”词中之“势成”亦同此意。作者的主张在当时能否实现，可以置而不论，但这几句豪言壮语，是可以“起顽立懦”的。到这里，一开头提出的“今古几人曾会”的“此意”已经尽情发挥，全词也就在破竹之势中收笔。\n\n　　同样是登临抒慨之作，陈亮的这首《念奴娇·登多景楼》和他的挚友辛弃疾的《水龙吟·登建康赏心亭》便显出不同的艺术风格。辛词也深慨于“无人会登临意”，但通篇于豪迈雄放之中深寓沉郁盘结之情，读来别具一种回肠荡气、抑塞低回之感；而陈词则纵论时弊，痛快淋漓，充分显示其词人兼政论家的性格。从艺术的含蕴、情味的深厚来说，陈词自然不如辛词，但这种大气磅礴、开拓万古心胸的强音，是足以振奋人心的。', poem_tags = '豪放,登楼,借古论今' WHERE poem_title = '念奴娇·登多景楼' AND poem_author = '陈亮';
UPDATE edu_poem SET poem_translation = '春天的庭院黎明过后，晶莹的露水趴在花上，花丛曲折连环。\n黄蜂一飞过花朵就变得慵懒困倦，每夜都停留在芬芳的花蕊上。', poem_notes = '逦迤：曲折连环貌。\n慵：困倦，懒得动。', poem_tags = '春天,写景' WHERE poem_title = '春晓' AND poem_author = '陆龟蒙';
UPDATE edu_poem SET poem_translation = '燕支的叶子枯黄而落下，女子独自登台远望。看到天空中青云纷散，单于带着秋色到来。\n胡人的兵队在沙漠边塞集合，汉使往玉门关折回。在他乡的客人还没有归期，徒然为蕙草的摧折感到悲伤。', poem_notes = '燕之：草名，可做红色染料。\n碧云：青云，碧空中的云。\n单于：外族首领。\n沙塞：沙漠边塞。\n玉关：即玉门关。\n蕙草：一种香草。\n征客：做客他乡的人。', poem_tags = '秋天,抒怀,悲伤' WHERE poem_title = '秋思' AND poem_author = '李白';
UPDATE edu_poem SET poem_tags = '抒怀,志向' WHERE poem_title = '长歌行' AND poem_author = '李泌';
UPDATE edu_poem SET poem_translation = '作官做了三十多年，官职已经到了最高等级，可是学业一点也没有成就，德行一点儿也没有可赞许的地方，到岁数大了只有伤悲，不胜惊慌惭愧。现在将要与你们永别，特将以下四条教给你们兄弟。\n\n　　第一、一个人独处时思想、言语、行为谨慎就能在处世时做到心安理得，心平气和。修身养性做人做学问的道路，最难的就是养心，养心中最难的，就是做到在一个人独处时思想、言语、行为谨慎。能够做到在一个人独处时思想、言语、行为谨慎，就可以问心无愧，就可以对得起天地良心和鬼神的质问。如果一个人在独处时没有做过一件问心有愧的事，那么他就会觉得十分安稳，自己的心情也常常会是快乐满足宽慰平安的，（做到在一个人独处时思想、言语、行为谨慎）是人生中最好的自强不息的道路和寻找快乐的方法，也是做到守身如玉的基础。\n\n　　第二、主观上对人对事对物态度恭恭敬敬就能使身心强健。内心专一宁静浑然一体，外表衣着整齐态度严谨，这是对人对事对物态度恭恭敬敬的方法；一出门就像要去拜访一个尊贵的客人，就像普通老百姓在祭祀祖先时所表现出来的那种恭恭敬敬的样子，这是对人对事对物态度恭恭敬敬的气氛。想要凭借自己掌握的知识来安抚老百姓，必须做到一丝不苟恭恭敬敬这样老百姓才能信服，这是对人对事对物态度恭恭敬敬的效果。聪明的人和机智的人，因为他们都能够做到对人对事对物态度恭恭敬敬，所以总能够给别人留下一个美好的印象。主观上对人对事对物态度庄重严谨恭恭敬敬，就会一天比一天壮大自己，主观上对人对事对物态度傲慢无礼肆意而为，就会一天比一天消亡自己。如果能做到无论对一个人还是一群人、无论对小事情还是大事情都态度恭恭敬敬，不敢有一丝一毫松懈怠慢的意思，那么自己身体和内心的强健，还用值得怀疑吗？\n\n　　第三、讲究仁爱就能使人心悦诚服。天底下人的生命，都是得到了天和地的机理才成就自我的性格，都是得到了天和地的气息才成就自我的形象，我（指曾国藩）和普通老百姓相比，对于生命生生不息的意义其实都是相同的。假如我（指曾国藩）只知道自私自利而不知道对老百姓讲究仁爱对事物加倍爱惜，那么就是违背甚至抛弃了生命生生不息的意义。至于那些享有丰厚俸禄的大官，高高地位于众人之上，就应该承担起拯救老百姓于溺水之时和拯救老百姓于饥饿之中的责任。读古书学习古人的思想，大概知道了古书中的意思，就应该有大力推行古书中自己已经领悟的古人正确思想的责任。孔子的儒家学派教育子弟，大都要求子弟要讲究仁爱，而讲究仁爱最根本的，就是要想成就自己首先就要成就他人，要想富贵自己首先就要富贵他人。能够成就他人富贵他人的人，人们哪会有不心悦诚服的归顺于他的呢？\n\n　　第四、努力工作、辛勤劳动就能使神明感到钦佩。一个人每一天所穿的衣服、所吃的食物，能做到与他白天所做的事情所用的力气相匹配的，就会得到旁人的认可和鬼神的赞许，这是因为他是在靠自己的本事吃饭。假如普通人家男人耕田女人织布，一年到头辛苦劳动，才有了几担谷和几匹布的收入，而富贵人家的老爷少爷却一年到头安逸淫乐，不做一件事情，而吃的都是山珍海味，穿的都是锦罗绸缎。喝醉了酒以后就像猪一样呼呼大睡，醒来后他一叫唤就有下人们对他唯唯喏喏，这是天底下最不公平的事情，连鬼神看见了都不会允许他（富贵人家）这样胡作非为，难道富贵人家就可以长期这样安逸淫乐享福吗？古代圣明的帝王和贤良的大臣，没有一个无时不刻不是把勤劳工作作为座右铭来激励自己。如果从个人安身立命的角度来说，就应该努力操练和学习技术本领，积极煅练自己的体魄，感觉到自己知识太少时就加倍努力去学习知识，时时刻刻做到居安思危，这样才能够做到通过增长自己的学识来增长自己的才干。而从为天底下老百姓着想的角度来说，就应该做到让普天下的百姓都吃饱饭、穿暖衣，不再处于水深火热之中，让他们都接受教育，不再像水边的蒿草一样没有自己的主见，这些都是我们应该背负的责任。大禹、墨子大都提倡对于个人生活应该非常节俭，而对于工作应该非常努力，辛勤劳动以使自己丰衣足食。勤苦劳动的人长寿，安逸享受的人短寿，勤劳的人因为经常参加社会劳动，学有才干而能够派上用场，安逸享受的人因为从不参加社会劳动，毫无才干而会被社会所淘汰，一个人努力工作辛勤劳动就能为社会创造财富给别人带来好处从而使神明都对他的行为感到钦佩敬仰，一个人贪图安逸享乐就不能为社会创造财富不能给别人带来好处从而使鬼神都他的行为感到厌恶。\n\n　　这四条是我从数十年的人生中积累的，你们兄弟们记住并且履行，而且要把它传给子子孙孙，这样,我们曾家就可以长盛不衰，每代都有人才。▲', poem_tags = '家训' WHERE poem_title = '曾国藩诫子书' AND poem_author = '曾国藩';
UPDATE edu_poem SET poem_translation = '春光明媚、和风徐徐的西子湖畔，游人如织。\n到了傍晚，踏青游湖人们已散，笙歌已歇，但西湖却万树流莺，鸣声婉转，春色依旧。\n把佳节清明的西湖，描绘得确如人间天堂，美不胜收。', poem_notes = '苏堤，元佑间苏轼官杭州刺束时建于西湖。\n梨花风，古代认为从小寒至Ⅱ谷雨有二十四番应花期而来的风。梨花风为第十七番花信风。梨花风后不久即是清明。\n笙歌，乐声、歌声。\n属，归于。\n按，古人极重清明节，有“朝朝清明，夜夜元宵”之说。该诗意境与周密《曲游春》词“沸十里、乱弦丛笛。看画船，尽入西泠，闲却半湖春色”相似。\n即事，歌咏眼前景物\n梨花风，梨花为第十七番花信风。\n吴惟信，字仲孚，霅川（今浙江吴兴）人。南宋后期诗人。', poem_appreciation = '这首诗对大好春光和游春乐境并未作具体渲染，只是用“梨花”、“笙歌”等稍作点染，此诗的构思之绝，就体现在作者不由正面入手，而是借游人的纵情、黄莺的恣意，从侧面措意，促人去展开联想。游子寻春，不但“半出城”，而且“朝而往，暮而归”，痛玩了整整一天，足见西湖胜景令人目不暇接，节日气氛使人流连忘返。再看“流莺”，当人们“笙歌鼎沸，鼓吹喧天”之时，它的世界被人类“强占”。现在，“游人去而禽鸟乐也”，被压抑了一天的黄莺，又受了游人情绪的感染，当它重成了绿林的主人，怎能不欣喜若狂？不难想象，黄莺匿迹，是因人喧场面的热烈；而它的再现，正说明宜人秀色的魅力。这样，诗人叙节日情景，状清明景色，不是直接绘描，而是就有情之人和无情之莺的快乐，由侧面实现自己的创作目的。\n\n　　前两句写西湖春景和游春的热闹场面。后两句说日暮人散以后，景色更加幽美，那些爱赶热闹的人既然不知道欣赏，只好让给飞回来的黄莺享受去了。 反映了清明时节郊游踏青的乐趣：“梨花风起正清明，游子寻春半出城。日暮笙歌收拾去，万株杨柳属流莺。”江南三月正是“梨花万朵白如雪”的季节，青年人结伴出城，踏青寻春，笙笛呜咽，歌声袅袅，微风拂面，杨柳依依，真是“心旷神怡，把酒临风，其喜洋洋者矣”。', poem_tags = '清明节,春游,写景' WHERE poem_title = '苏堤清明即事' AND poem_author = '吴惟信';
UPDATE edu_poem SET poem_translation = '我第三次经过平山堂，前半生在弹指声中过去了。整十年没见老仙翁了，只有墙上他的墨迹，仍是那样气势雄浑，犹如龙飞蛇舞。\n我在平山堂前“欧公柳”的下面，写下这首词悼念文坛英杰，故扬州太守欧阳修。别说人死后万事皆空，即使活在世上，也不过是一场大梦呀!', poem_notes = '西江月：词牌名取自李白《苏台览古》“只今唯有西江月，曾照吴王宫里人”。西江是长江的别称，调咏吴王西施的故事。原唐教坊曲，后用作词调。又名《白苹香》、《步虚词》、《晚香时候》、《玉炉三涧雪》、《江月令》。双调五十字，前后阕各两平韵，一仄韵，同部平仄互押，前后阕起首两句例用对仗。\n平山堂：在扬州大明寺侧，欧阳修所建。《舆地纪胜》：“负堂而望，江南诸山拱列檐下，故名。”\n弹指：佛教名词，比喻时间短暂。《翻译名义集》卷五《时分》：“时极短者谓刹那也”，“壮士一弹指顷六十五刹那”，又云“二十念为一瞬，二十瞬为一弹指。”\n老仙翁：指欧阳修。苏轼于熙宁四年于扬州谒见欧阳修，至此为九年，十年盖举成数。\n龙蛇飞动：指欧阳修在平山堂壁留题之墨迹。\n文章太守、杨柳春风：欧阳修《朝中措》：“平山栏槛倚晴空，山色有无中。手种堂前垂柳，别来几度春风。文章太守，挥毫万字，一饮千钟。行乐直须年少，樽前看取衰翁。”是为“文章太守”、“杨柳春风”所本。\n未转头时是梦：白居易《自咏》：“百年随手过，万事转头空。”此翻进一层，谓未转头时，已是梦幻。', poem_tags = '抚今,追昔' WHERE poem_title = '西江月·平山堂' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '系着雨拖着风的柳树难以保持自己的形态，全身无力，向人倾垂。\n把这纤细如玉的柳枝折下赠给在远方的人，它就像观音手里玉净瓶中的柳枝一样珍贵。', poem_notes = '褭：系着。有用丝带系马的意思。', poem_tags = '咏柳' WHERE poem_title = '咏柳' AND poem_author = '韩偓';
UPDATE edu_poem SET poem_tags = '古诗三百首,送别,友情,写景' WHERE poem_title = '三江小渡' AND poem_author = '杨万里';
UPDATE edu_poem SET poem_translation = '杨柳飘拂的渡口行客疏疏稀稀，艄公摇荡着船桨一直驶向临圻。\n只有相思的别恨像无边的春色，不论江南江北时刻送你把家归。', poem_notes = '沈子：一作“沈子福”，作者的友人。归：又作“之”。江东：指长江下游以东地区。长江自九江以下向东北方向流去，故称长江中下游地区为江东。\n渡头：犹渡口。过河的地方。行客：过客；旅客。《淮南子·精神训》：“是故视珍宝珠玉犹砾石也，视至尊穷宠犹行客也。”\n罟（gǔ）师：渔人，这里借指船夫。临圻（qí）：临近曲岸的地方。当指友人所去之地。“圻”，曲岸。明嘉靖本洪迈《万首唐人绝句》作“临沂”，为东晋侨置的县名，在今江苏省南京市东北，与题中“归江东”吻合。\n相思：此处指友人间的彼此想念。\n江：大江，今指长江。', poem_appreciation = '王维这首送别之作意韵悠长，风神摇曳，绵邈蕴藉。饱含劝勉，一叙理想抱负之情。诗的开篇直接入题，描写送别情形。渡头是送客之地，杨柳是渡头现成之景，景中却蕴含深情：“柳”与“留”同音，唐人有折柳送行的习俗，表示不忍离别，希望远行的人留下来。但分别终究是不可避免的，此时友人乘坐的船只已经起航。这里写杨柳，不仅写现成之景，更是烘托送别气氛。行客已稀，见境地的凄清，反衬出送别友人的依依不舍之情。第一句点明送别之地。第二句醒出“归江东”题意。刚才还很热闹的渡头，一下变得行客稀少，冷冷清清。惟有诗人自己，仍然立在那里，目送着友人渐渐远去。他的脑海里，或许在重温刚才与友人依依话别的情景，或许想起了之前和友人交往的点点滴滴。但这一切，都只能是追忆了。眼前只见友人所乘的船顺水而下，离自己越来越远。\n\n　　李白《黄鹤楼送孟浩然之广陵》诗中也有目送友人乘舟而去的情形：“孤帆远影碧空尽，唯见长江天际流。”李白站在高高的黄鹤楼上，远眺孤舟，写的是远景。而王维捕捉的是船夫荡桨的细节，写的是近景。同样写送行，李白之潇洒与王维之细腻，可见一斑。\n\n　　船儿渐行渐远，友人的身影也越来越模糊。友人乘船而去，只要再过一会儿，他们就将消失在诗人的视线之外。而这一别，又不知何时才能重新相逢。想到这些，诗人的心中难免有些怅惘。这时，诗人依依不舍，望着大江南北两岸，春满人间，春光荡漾，桃红柳绿，芳草萋萋。诗人感觉到自己心中的无限依恋惜别之情，就像眼前春色的无边无际。诗人忽发奇想：让我心中的相思之情也像这无处不在的春色，从江南江北，一齐扑向你，跟随着你归去吧？“惟有相思似春色，江南江北送君归”，是十分美丽的想象，有着无比蕴藉而深厚的感情。诗人似乎在对友人说：你在江上走，江南江北的春色包围着你；我的牵挂、友谊也和这春色一样，时时刻刻包围着你，陪你一路前行。春满江南江北，情亦满江南江北。不必特意写离愁别苦，别情已经充盈了满篇。更巧的是，自然之景与深挚之情妙合无间，耐人寻味。将自然界的春色比心灵中的感情，即景寓情，情与景妙合无间，极其自然。这里藉难写之景以抒无形之情，功夫当然又深了一层。写离情别绪哀而不伤，形象丰满，基调明快，这是盛唐诗歌的特色。\n\n　　此诗描写的是最具普遍性的离别。与许多别诗一样，先用景色来制造—定的气氛，“行客稀”可见境地的凄清，反衬与友人的依依不舍之情。此诗末两句“惟有相思似春色，江南江北送君归”与牛希济《生查子》诗中：“记得绿罗裙，处处怜芳草。”两句有着异曲同工之妙；与王维“惟有相思似春色，江南江北送君归”诗句比较，手法相同，思路相近，同样具有动人的艺术魅力，但感情一奔放一低徊，风格一浑成一婉约，各具姿态。“惟有相思似春色，江南江北送君归”两句是作者突发的奇想，将春色比作心中对朋友的情谊，情景妙合无间，表露得非常自然。原本充满愁绪的离别被诗人写得哀而不伤，反而觉得形象丰满、基调明快，其动人的艺术魅力不可否认。', poem_tags = '送别,即景,寓情,思念' WHERE poem_title = '送沈子归江东 / 送沈子福之江东' AND poem_author = '王维';
UPDATE edu_poem SET poem_tags = '秋天,闺怨,思念' WHERE poem_title = '秋夜曲' AND poem_author = '张仲素';
UPDATE edu_poem SET poem_translation = '蔺相如完璧归赵，人人都称道他。但是，我却不敢苟同。\n\n　　秦国用十五座城的空名，来欺骗赵国，并且勒索它的和氏璧。这时说它要骗取璧是实情，但不是想要借此窥视赵国。赵国如果知道了这个实情就不给它，不知道这个实情就给它。知道了这个实情而害怕秦国而给它，知道这个实情而不害怕秦国就不给它。这只要两句话就解决了，怎么能够既害怕秦国又去激怒秦国呢？\n\n　　况且，秦国想得到这块璧，赵国不给它，双方本来都没有什么曲直是非。赵国交出璧而秦国不给城池，秦国就理亏了。秦国给了城池，而赵国却拿回了璧，就是赵国理亏了。要想使秦国理亏，不如就放弃璧。害怕丢掉璧，就不如不给它。秦王既然按照地图给了城池，又设九宾的隆重礼仪，斋戒之后才来接受璧，那种形势是不得不给城池的。如果秦王接受了璧而不给城池，蔺相如就可以上前质问他：“我本来就知道大王是不会给城池的，这块璧不是赵国的吗？而十五座城池也是秦国的宝物。现在假使大王因为一块璧的缘故而抛弃了十五座城池，十五座城中的百姓都会深恨大王，说把我们像小草一样抛弃了。大王不给城池，而骗夺了赵国的璧，因为一块璧的缘故，在天下人面前失去信用，我请求死在这里，来表明大王的失信。”这样，秦王未必不归还璧。但是当时为什么要派手下人怀揣着璧逃走而把秦国处在理直的一方呢？\n\n　　那时秦国并不想与赵国断绝关系。假如秦王发怒，在街市上杀掉蔺相如，派武安君率领十万大军进逼邯郸，追问璧的下落和赵国的失信，一次获胜就可以使相如灭族，再次获胜而璧最终还是要落到秦国手里。\n\n　　因此我认为，蔺相如能保全这块璧，那是上天的保佑。至于他在渑池以强硬的态度对付秦国，在国内以谦和的姿态对待廉颇，那是策略上越来越高明了。所以说赵国之所以能得以保全，的确是上天在偏袒它啊！', poem_notes = '蔺相如之完璧：蔺相如，战国时赵国大臣。赵惠文王得到稀世之宝——和氏璧，秦昭王想用十五座城换取这块璧。当时秦强赵弱，赵王恐给了秦璧却得不到城。蔺相如请命奉璧入秦，见秦王无意给赵城，用计赚回和氏璧，并叫随从化装从小路逃走，完璧归赵。\n情：实情、本意。\n九宾：古代举行大典时所用的极隆重的礼仪。宾指摈相，迎宾礼赞的官吏。\n绐：欺骗。\n令：假如。\n僇：通“戮”，杀戳。\n武安君：秦国大将白起的封号。邯郸：赵国都城，在今河北邯郸市。\n族：灭族。\n劲渑池：公元前279年，秦王约赵王会于渑池。宴会上秦王请赵王鼓瑟以辱赵王。蔺相如随行，便以刺杀秦王相威胁，请秦王为赵王击缶。劲：强劲。果敢的意思。\n柔廉颇：廉颇，赵国名将。蔺相如因“完璧归赵”和“渑池会”功大，拜为上卿、位在廉颇之上。廉颇不服，打算侮辱他。蔺相如以国家利益为重，多次避让廉颇。廉颇受到感动，负荆请罪。廉蔺遂成刎颈之交。柔：忍让。退让的意思。', poem_tags = '古文观止,初中文言文,赞颂,写人,故事' WHERE poem_title = '蔺相如完璧归赵论' AND poem_author = '王世贞';
UPDATE edu_poem SET poem_translation = '洛阳的东城门外，高高的城墙。\n从曲折绵长鳞次栉比的楼宇、房舍外绕过一圈，又回到原处.。\n四野茫茫，转眼又有秋风在大地上激荡而起。空旷地方自下而上吹起的旋风，犹如动地般的吹起。\n使往昔葱绿的草野霎时变得凄凄苍苍。\n转眼一年又过去了!在怅然失意的心境中，就是听那天地间的鸟啭虫鸣，也会让人苦闷。\n鸷鸟在风中苦涩地啼叫，蟋蟀也因寒秋降临而伤心哀鸣。\n不但是人生，自然界的一切生命不都感到了时光流逝。\n与其处处自我约束，等到迟暮之际再悲鸣哀叹。\n何不早些涤除烦忧，放开情怀，去寻求生活的乐趣呢! \n那燕赵宛洛之地本来就有很多的佳人美女，美女艳丽其颜如玉般的洁白秀美。\n穿著罗裳薄衣随风飘逸拂动，仪态雍容端坐正铮铮地习练著筝商之曲。\n《音响一何悲》之曲因为琴瑟之柱调得太紧促，那琴声竟似骤雨疾风，听起来分外悲惋动人。\n由于听曲动心，不自觉地引起遐思，手在摆弄衣带，无以自遣怅惘的心情。\n反复沉吟，双足为之踯躅不前，被佳人深沉的曲调所感动。\n心里遥想着要与佳人成为双飞燕，衔泥筑巢永结深情。', poem_notes = '东城：洛阳的东城。\n逶迤：曲折而绵长的样子。\n回风动地起：“回风”空旷地方自下而上吹起的旋风。“动地起”言风力之劲。\n秋草萋已绿：“已”，一作“以”。“萋”，通作“凄”。绿是草的生命力的表现，“萋已绿”，犹“绿已萋”，是说在秋风摇落之中，草的绿意已凄然向尽。\n四时更变化二句：“更”，替也。“更变化”，谓互相更替在变化着。\n晨风怀苦心二句：“晨风”，鸟名，就是鹯，鸷鸟。是健飞的鸟。“怀苦心”，即“忧心钦钦”之意。“蟋蟀”，是承上文“岁暮”而言。“局促”，不开展也。“蟋蟀在堂”就是“局促”的意思。秋季渐寒，蟋蟀就暖，由旷野入居室内，到了“在堂”，则是秋意已深的时候，而蟋蟀的生命也就垂垂向尽了。“伤局促”，隐喻人生短暂的北哀，提示下文“何为自结束”的及时行乐的想法。\n荡涤放情志二句：“荡涤”，犹言洗涤，指扫除一切忧虑。“放情志”，谓展胸怀。“结束”，犹言拘束。“自结束”，指自己在思想上拘束自己。\n燕赵多佳人二句：“燕赵”，犹言美人。“如玉”，形容肤色洁白。\n被服罗裳衣二句：“被服”，犹言穿著，“被”，披也。“理”，指“乐理”，当时艺人练习音乐歌唱叫做“理乐”。\n弦急知柱促：“弦急”“柱促”是一个现象的两面，都是表明弹者情感的激动。\n驰情整中带二句：“驰情”，犹言遐想，深思。“中带”，内衣的带子。一作“衣带”。“沈吟”，沉思吟咏。“踯躅”，住足也。是一种极端悲哀的情感的表现。这两句是说：由于听曲感心，不自觉地引起遐想、深思，反复沉吟，体味曲中的涵义，手在弄着衣带，足为之踯躅不前，完全被歌者深沉的悲哀吸引住了。“聊”，姑且。表现无以自遗的怅惘心情。\n思为双飞燕二句：上句是说愿与歌者成为“双飞燕”。下句是“君”，指歌者。“衔泥巢屋”，意指同居。', poem_appreciation = '处在苦闷的时代，而又悟到了“人生非金石，岂能长寿考”的生命哲理，其苦闷就尤其深切。苦闷而无法摆脱，便往往转向它的对立一极——荡情行乐。此诗所抒写的，就正是这种由苦闷所触发的滔荡之思。\n\n　　诗人大约是独自一人，徘徊在洛阳的东城门外。高高的城墙，从眼前“逶迤”（绵长貌）而去，在鳞次栉比的楼宇、房舍外绕过一圈，又回到原处、自相连接——这景象正如周而复始的苦闷生活一样，单调而又乏味。四野茫茫，转眼又有“初淅沥以萧飒，忽奔腾而砰湃”的秋风，在大地上激荡而起，使往昔葱绿的草野，霎时变得凄凄苍苍。这开篇四句，不仅描述着诗人目击的景象，其中还隐隐透露着诗人内心的痛苦骚动。生活竟如此重复、单调变化的只有匆匆逝去的无情时光。想到人的生命，就如这风中的绿草一般，繁茂的春夏一过，便又步入凄凄的衰秋，诗人能不惊心而呼：“四时更变化，岁暮一何速”！眼前的凄凄秋景，正这样引发出诗人对时光速逝的震竦之感。在怅然扔失意的心境中，就是听那天地间的鸟啭虫鸣，似乎也多一重苦闷难伸的韵调：“晨风怀苦心，蟋蟀伤局促。”“晨风”即“?鸟”，“局促”有紧迫、窘困之意。鸟在风中苦涩地啼叫，蟋蟀也因寒秋降临、生命窘急而伤心哀鸣。不但是人生，自然界的一切生命，都受到了时光流驶的迟暮之悲。这一切似乎都从相反方面，加强着诗人对人生的一种思索和意念：与其处处自我约束，等到迟暮之际再悲鸣哀叹，应当早些涤除烦忧、放开情怀，去寻求生活的乐趣——这就是突发于诗中的浩然问叹：“荡涤放情志，何为自结束？”\n\n　　以上为全诗之第一节。读者可以看到，在此节中盘旋往复的，其实只有一个意念，即“荡涤放情”之思。这种思绪，原本来自于诗人自身生活中的苦闷，与所见景象并无关涉。但诗人却将它移之于外物，从衰飒悲凉的秋景中写来。便令人感到，从“高且长”的东城，到凄凄变衰的秋草，以至于?鸟、蟋蟀，似乎都成了苦闷人生的某种象征，似乎都在用同一个声调哀叹：“何为自结束”、“何为自结束”！这就是审美心理上的“移情”效果。这种贯注于外物、又为外物所烘托而强化的情感抒写，较之于直抒其怀，无疑具有更蓬勃的葱茏的感染力。自“燕赵多佳人”以下，即上承“荡情”之意，抒写诗人的行乐之境。－－当“何为自结束”的疑虑一经解除，诗人那久抑心底的声色之欲便勃然而兴。此刻，身在“东城”外的诗人，竟做了一个极美妙的“燕赵佳人”梦：他恍惚间在众多粉黛丛中，得遇了一位“颜如玉”的佳人；而且奇特的是，一转眼，这佳从便“罗裳”飘拂、仪态雍容地端坐在诗人家中，分明正铮铮地习练着靖商之曲。大约是因为琴瑟之柱调得太紧促，那琴间竟似骤雨急风，听来分外悲惋动人——读者自然明白，这情景虽然描述得煞在介事，实际上不过是诗人那“荡情”之思所幻化的虚境而已。所以画面飘忽、转换也快，呈现出一种梦寐般的恍惚感。\n\n　　最妙的是接着两句：“驰情整中带，沈吟聊踯躅（且前且退貌）”。“中带”，一本作“巾带”。关于这两句写的指何人，照张庚的说法：“凡人心慕其人，而欲动其人之亲爱于我，必先自正其容仪……以希感到佳人也”（《古诗十九首解》）。那么，“驰情”而“整中带”者，就是诗人了。那当然也有道理（只与整句不太连贯）。不过，苦将其视为佳人的神态表现，恐怕还更有韵致些。因为佳人之“当户”理琴，本来并非孤身一人。此刻在她对面，正目光灼灼注视着她，并为她的容颜、琴音所打动，而为之目凝神移的，还有一位梦想着“荡涤放情志”的诗人。正如吴淇所说：“曰‘美者’，分明有个人选他（按，即“她”）；曰‘知柱促’，分明有个人促他”分明有个人在听他；“曰‘整中带’，分明有个人看他；曰‘踯躅’，分明有个人在促他”（《选诗定论》）。“驰情整巾带”两句，正是写佳人在这“选”、“听”、“看”、“促”之下的反应——多情的佳人面对着诗人的忘形之态，也不觉心旌摇荡了。但她不免又有些羞涩，有些踌躇，故又是“沉吟”、又是“踯躅”（已舍琴而起），表现出一种“理欲交战情形”；但内心则“早已倾心于君矣”——这就是前人称叹的“‘驰情’二句描写入神”处。在这种图画也“画不出的捉衣弄影光景”中，佳人终于羞羞答答地吐露了心意：“思为双飞燕，衔泥巢君屋”。借飞燕双双衔泥巢屋之语，传达与诗人永结伉俪之谐的深情，真是“结得又超脱、又缥缈，把一万世才子佳人勾当，俱被他说尽”（朱筠《古诗十九首说》）。\n\n　　这就是诗人在“东城高且长”的风物触发下，所抒写的“荡涤放情志”的一幕；或者说，是诗人苦闷之际所做的一个“白日梦”。这“梦”在表面上很“驰情”、很美妙。但若将它放在上文的衰秋、“岁暮”、鸟苦虫悲的苍凉之境中观察，就可知道：那不过是苦闷时代人性备受压抑一种“失却的快东与美感的补偿（尼采），一种现实中无法“达成”的虚幻的“愿望”而已。当诗人从这样的“白日梦”中醒来的时候，还是会因苦闷时代所无法摆脱的“局促”和“结束”，而倍觉凄怆和痛苦。', poem_tags = '古诗三百首,古诗十九首,抒情,人生,哲理' WHERE poem_title = '东城高且长' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '夜宿金陵渡口的小山楼，辗转难眠心中满怀旅愁。\n斜月朦胧江潮正在下落，对岸星火闪闪便是瓜洲。', poem_notes = '金陵渡：渡口名，在今江苏省镇江市附近。\n津：渡口。小山楼：渡口附近小楼，作者住宿之处。\n宿：过夜。行人：旅客，指作者自己。可：当。\n斜月：下半夜偏西的月亮。星火：形容远处三三两两像星星一样闪烁的火光。\n瓜州：在长江北岸，今江苏省邗江县南部，与镇江市隔江相对，向来是长江南北水运的交通要冲。', poem_tags = '唐诗三百首,旅途,抒情' WHERE poem_title = '题金陵渡' AND poem_author = '张祜';
UPDATE edu_poem SET poem_translation = '昨夜萧瑟的秋风卷入驻守的关塞；极目四望，但见边月西沉，寒云滚滚。\n一再命令那些勇猛的将士追击敌人，不要让敌人一兵一马从战场上逃回。', poem_notes = '汉关：汉朝的关塞，这里指唐朝军队驻守的关塞。\n朔云边月：指边境上的云和月。月：一作“雪”。朔：北方。边：边境。西山：指今四川省西部的岷山，是当时控制吐蕃内侵的要地。\n更催：再次催促。飞将：西汉名将李广被匈奴称为“飞将军”，这里泛指严武部下作战勇猛的将领。骄虏：指唐朝时入侵的吐蕃军队。\n莫遣：不要让。沙场：战场。', poem_appreciation = '《军城早秋》载于《全唐诗》卷二六一。下面是安徽师范大学文学院教授赵其钧先生对此诗的赏析。\n\n　　这首《军城早秋》，一方面使读者看到严武作为镇守一方的主将的才略和武功，另一方面也表现了这位统兵主将的词章文采，能文善武，无怪杜甫称其为“出群”之才。\n\n　　诗的第一句“昨夜秋风入汉关”，看上去是写景，其实是颇有寓意的。我国西北和北部的少数民族的统治武装，常于秋高马肥的季节向内地进犯。“秋风入汉关”就意味着边境上的紧张时刻又来临了。“昨夜”二字，紧扣诗题“早秋”，如此及时地了解“秋风”，正反映了严武作为边关主将对时局的密切关注，对敌情的熟悉。\n\n　　第二句接着写诗人听到秋风的反映，这个反映是很有个性的，他立即注视西山，表现了主将的警觉、敏感，也暗示了他对时局所关注的具体内容。西山，寒云低压，月色清冷，再加上一个“满”字，就把那阴沉肃穆的气氛写得更为浓重，这气氛正似风云突变的前兆，大战前的沉默。“眼中形势胸中策”（宗泽《早发》），这是一切将领用兵作战的基本规律。所以诗的前两句既然写出了战云密布的“眼中形势”，那胸中之策就自不待言了，诗中略去这一部分内容，正表现了严武是用兵的行家。\n\n　　“更催飞将追骄虏，莫遣沙场匹马还”。“更催”二字暗示战事已按主将部署胜利展开。两句一气而下，笔意酣畅，字字千钧，既显示出战场上势如破竹的气势，也表现了主将刚毅果断的气魄和胜利在握的神情，而整个战斗的结果也自然寓于其中了。这就是古人所说的“墨气所射，四表无穷，无字处皆其意也”（王夫之《董斋诗话》）。\n\n　　如果把一、二句和三、四句的内容放在一起来看，就会发现中间有着很大的跳跃。了解战争的人都知道，一个闭目塞听、对敌情一无所知的主将，是断然不会打胜仗的，战争的胜负往往取决于战前主将对敌情的敏感和了解的程度。诗的一、二句景中有情，显示出主将准确地掌握了时机和敌情，这就意味着已经居于主动地位，取得了主动权，取得了克敌制胜的先决条件，这一切正预示着战争的顺利，因而，胜利也就成了人们意料中的结果，所以读到三、四句非但没有突兀、生硬之感，反而有一种水到渠成、果然如此的满足。这首诗写得开阖跳跃，气概雄壮，干净利落，表现出地道的统帅本色。\n\n　　诗的思想感情、语言风格，也都富有作者本人的个性特征。这不是一般诗人所能写得出的。', poem_tags = '写风,边塞' WHERE poem_title = '军城早秋' AND poem_author = '严武';
UPDATE edu_poem SET poem_translation = '有些人交友，翻手覆手之间，一会儿像云的趋合，一会儿像雨的纷散，变化多端，这种贿赂之交、势利之交、酒肉之交是多么地让人轻蔑愤慨、不屑一顾！\n可是你看，古人管仲和鲍叔牙贫富不移的君子之交，却被今人弃之如粪土。', poem_notes = '贫交行：描写贫贱之交的诗歌。贫交，古歌所说：“采葵莫伤根，伤根葵不生。结交莫羞贫，羞贫友不成。”贫贱方能见真交，而富贵时的交游则未必可靠。\n覆：颠倒。\n管鲍：指管仲和鲍叔牙。管仲早年与鲍叔牙相处很好，管仲贫困，也欺骗过鲍叔牙，但鲍叔牙始终善待管仲。现在人们常用“管鲍”来比喻情谊深厚的朋友。\n弃：抛弃。', poem_appreciation = '诗的开篇“翻手为云覆手雨”，就给人一种势利之交“诚可畏也”的感觉。得意时的趋合、失意时的纷散，翻手覆手之间，忽云忽雨，其变化迅速无常。“只起一语，尽千古世态。”（浦起龙《读杜心解》）“翻云覆雨”的成语，就出在这里。所以首句不但凝炼、生动，统摄全篇，而且在语言上是极富创造性的。\n\n　　虽然世风浇薄如此，但人们普遍对交友之道毫不在意，“皆愿摩顶至踵，隳胆抽肠；约同要离焚妻子，誓殉荆轲湛（沉）七族”，“援青松以示心，指白水而旌信”（刘峻《广绝交论》），说穿了，不过是“贿交”、“势交”而已。第二句斥之为“纷纷轻薄”，诗人说“何须数”，轻蔑之极，愤慨之极。寥寥几个字，强有力地表现出诗人对假、恶、丑的东西极度憎恶的态度。\n\n　　这黑暗冷酷的现实使人绝望，于是诗人记起一桩古人的交谊。《史记》载，鲍叔牙早年与管仲交游，知道管仲的贤能。管仲贫困，曾欺负鲍叔牙，而鲍叔牙却始终善待他。后来鲍叔牙辅佐齐国的公子小白（即后来齐桓公），又向公子小白荐举管仲。管仲终于辅佐齐桓公成就了霸业，他感喟说：“生我者父母，知我者鲍叔牙也。”鲍叔牙对待管仲的这种贫富不移的交道是感人肺腑的。“君不见管鲍贫时交”，当头一喝，将古道与现实作一对比，给这首抨击黑暗的诗篇添了一点理想光辉。但其主要目的，还在于鞭挞现实。古人以友情为重，重于磐石，相形之下，“今人”的“轻薄”越发显得突出。“此道今人弃如土”，末尾三字极形象，古人的美德被“今人”像土块一样抛弃了，抛弃得十分彻底。这话略带夸张意味。尤其是将“今人”一概而论，范围过大。但只有这样，才能把世上真交绝少这个意思表达得更加充分。\n\n　　这首诗“作‘行’，止此四句，语短而恨长，亦唐人所绝少者”（见《杜诗镜铨》）。其所以能做到“语短恨长”，是由于它发唱惊挺，造形生动，通过正反对比手法和过情夸张语气的运用，反复咏叹，造成了“慷慨不可止”的情韵，吐露出诗人心中郁结的愤懑与悲辛。', poem_tags = '友情,愤懑,怀古' WHERE poem_title = '贫交行' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '难以抑制的诗兴从早到晚把我纠缠，只好围绕着篱笆散步或倚在石头上独自低吟。\n笔端蕴涵着智慧对着秋菊临摹，口齿中含着对秋菊的芳香对着月亮吟咏。\n满纸书写的都是自己的愁怨，谁能透过片言只语理解自己内心的情愫呢？\n自从陶潜写了咏菊以后秋菊的高尚品格一直被人称道。', poem_notes = '无赖：无聊赖，无法可想。诗魔：佛教把人们有所欲求的念头都说成是魔，宣扬修心养性用以降魔。所以，白居易的《闲吟》诗说：“自从苦学空门法，销尽平生种种心；唯有诗魔降未得，每逢风月一闲吟。”后遂以诗魔来说诗歌创作冲动所带来的不得安宁的心情。昏晓侵：从早到晚地侵扰。 \n欹：这里通作“倚”。沉音：心里默默地在念。\n毫端：笔端。蕴秀：藏着灵秀。“毫端蕴秀”是心头蕴秀的修辞说法。临霜写：对菊吟咏的修辞说法。临，即临摹、临帖之“临”。霜，非指白纸，乃指代菊，前已屡见。写，描绘。这里说吟咏。\n口齿噙香：噙，含着。香，修辞上兼因菊、人和诗句三者而言。\n素怨：即秋怨，与下句“秋心”成互文。秋叫“素秋”。“素”在这 里不作平素解，却兼有贞白、高洁的含义。“素怨”、“秋心”皆借菊的孤傲抒自己的情怀。\n一从：自从。陶令：陶渊明（365—427），东晋诗人，字符亮，一说名潜字渊明。曾做过八十多天彭泽县令，所以称陶令。他喜欢菊，诗文中常写到。评章：鉴赏，议论。亦借说吟咏，如：评章风月。\n高风：高尚的品格。在这里并指陶与菊。自陶潜后，历来文人咏菊，或以“隐逸”为比，或以“君子”相称，或赞其不畏风霜，或叹其孤高自芳，而且总要提到陶渊明。', poem_appreciation = '这首诗出现在《红楼梦》第三十八回《林潇湘魁夺菊花诗　薛蘅芜讽和螃蟹咏》里。这是《海棠诗社》的第二次活动，也是贾府表面上处于最鼎盛的时期。此次活动，由史湘云和薛宝钗拟定题目，共十二道题目，限定七律，但不限韵，由宝玉、黛玉、宝钗、湘云、探春等五人自由选题。在这次吟诗比赛中，“蘅芜君”薛宝钗选了《忆菊》、《画菊》之后，“怡红公子”贾宝玉选了《访菊》和《种菊》两道诗题。“潇湘妃子”林黛玉选了其中三道诗题：《咏菊》、《问菊》和《菊梦》。其余五题分别由湘云和探春选得。只“有顿饭工夫, 十二题已全,各自誊出来,都交与迎春,另拿了一张雪浪笺过来,一并誊录出来”。这首诗是在蘅芜君的《忆菊》、怡红公子的《访菊》和《种菊》，枕霞旧友史湘云的《对菊》、《供菊》之后，由潇湘妃子林黛玉写出的三首诗中的第一首。“众人看一首,赞一首,彼此称扬不已.李纨笑道: ‘等我从公评来.通篇看来,各有各人的警句.今日公评:<<咏菊>>第一,<<问菊>>第二,<<菊梦>>第三,题目新,诗也新,立意更新,恼不得要推潇湘妃子为魁了”。林黛玉可谓是囊括金、银、铜牌。“　宝玉听说,喜的拍手叫“极是,极公道。“”\n\n　　首联“无赖诗魔昏晓侵，绕篱欹石自沉音。”交代了诗作的时间、地点以及作者创作时的心情。潇湘妃子咏菊的时候跟一般人不同：“无赖诗魔昏晓侵，绕篱欹石自沉音.”一种强烈的创作冲动，象神魔附体似的，使得她从早到晚激动不已.，欲罢不能。创作灵感来了，她甚至不能静坐于闺房，只好绕过篱笆，来到假山旁边，斜靠在山石上，面对着菊花，专心致志地去构思、低吟。诗词来源于生活，来源于实践，来源于自然，来源于真实情感。这一句道尽了所有诗人的创作经验。不仅如此，还把诗人的兴奋、专心致志的艺术形象活灵活现地呈现出来了。潇湘妃子仅此一联就可足以技压群芳了。颔联“毫端蕴秀临霜写，口齿噙香对月吟。”胸有成竹，于是提起笔来，一泻千里，把赞美菊花的秀丽篇章写了出来。这还不够，还要对着天上的明月反复诵。可见，作者完全沉浸在完成诗作后的巨大幸福之中。接着，笔锋一转，颈联：“满纸自怜题素怨，片言谁解诉秋心。”又回到了林黛玉多愁善感的情绪之中：借颂扬菊花来抒发我愁怨的诗篇，又有谁能够理解我像素秋一样高洁的情怀呢？尾联“一从陶令平章后，千古高风说今。”这在诗词创作中叫“合”，于是又回到了咏菊的主题。自从陶渊明在诗歌中评说、赞扬菊花以后，千百年来菊花的不畏风霜、孤标自傲的高尚品格，一直为人们所仰慕，所传颂，直到今天。\n\n　　在这首诗中，直接写到菊花的字句并不多。但意在诗外，功夫在诗外。这才是诗词创作中的佳品。在这里，不能不回顾曹雪芹自题《红楼梦》的一首绝句：“满纸荒唐言，一把辛酸泪。 都云作者痴，谁解其中味。”这首绝句与林妹妹的这首诗，无论从语气上还是内容上，是何等的相似！这是巧合，还是曹雪芹故意为之，谁能读得懂？林黛玉的《咏菊》及其它诗词又有谁能读得懂它的真正含义？洋洋百余万言的《红楼梦》，两百余年来，多少人孜孜不倦地探讨和研究，又有谁能真正地理解？但是，无论如何，人们都会承认，在《红楼梦》林林总总的人物中，只有林妹妹的品质与菊花最为相符。在评选过程中，包括社长李纨在内的众姐妹们交口称赞颔联“ 毫端蕴秀临霜写，口齿噙香对月吟。”本也不错。因为这一联体现了林黛玉的才气与潇洒。但是，细细品来，窃以为末联“一从陶令平章后，千古高风说到今。”更具魅力，更意味深长！\n\n　　余不禁叹曰：千行妃子悲凄泪，一块石头说到今！\n\n　　这首诗以“咏菊”为题，所写的是写菊花诗的情景。\n\n　　首联“无赖诗魔昏晓侵，绕篱欹石自沉音”，紧扣诗题，描述了为写菊花诗，有如着魔了一般，从早到晚构思，绕篱欹石地推敲。只有苦心作诗的人才有此真切的体会。\n\n　　颔联“毫端蕴秀临霜与，口角噙香对月吟”，俏丽、秀美，只有锦心秀口之人，才能写出如此精彩的诗句。\n\n　　颈联“满纸自怜题素怨，片言谁解诉秋心”，诗中所题写的都是平素的哀怨，有谁能理解这感伤的心情呢？这分明是借“咏菊”在抒发诗人自己的情怀。也只有黛玉才如此多愁善感，又不被一些人理解。\n\n　　尾联“一从陶令评章后，千古高风说到今”，菊花的高洁品格，自从受到诗人陶渊明的好评之后，一直被世人议论至今。陶渊明爱菊是出了名的，以此作结，可谓奇思妙想的神来之笔。', poem_tags = '写诗,抒怀' WHERE poem_title = '咏菊' AND poem_author = '曹雪芹';
UPDATE edu_poem SET poem_tags = '小学文言文,故事,赞美,写人' WHERE poem_title = '画地学书' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '雨绵绵，恨意难消，云层层，愁绪堆积，江南景色，依旧被称为上好美丽。水边村落，湖畔渔市，袅袅升起一缕孤零零的炊烟，那么淡，那么细。\n一行长途跋涉的鸿雁，在那水天相连的遥远的天际，远远望去，款款飞行，好似列队首尾连缀。回想平生事业，此时此刻，凝视征鸿，谁理会我凭栏远眺的含意！', poem_notes = '孤烟：炊烟。\n行如缀：排成行的大雁，一只接一只，如同缀在一起。\n凝睇：凝视。睇：斜视的样子。\n会：理解。', poem_appreciation = '王禹偁是继柳开之后起来反对宋初华靡文风的文学家，有《小畜集》传世，留下来的词仅此一首。这首词以清丽的笔触，描绘了江南的雨景，含蓄地表过了用世的抱负和不被人理解的孤独愁闷。\n\n　　借景抒情、缘情写景是诗词惯用的手法。景是外部的客观存在，并不具备人的感情。但在词人眼里，客观景物往往染上强烈的感情色彩。此即王国维《人间词话》中所谓“以我观物”，使“物皆著我之色彩”。此词劈头一句“雨恨云愁”即是主观感觉的强烈外射。云、雨哪有什么喜怒哀乐，但词人觉得，那江南的雨，绵绵不尽，分时是恨意难消；那灰色的云块，层层堆积，分明是郁积着愁闷。即使是这弥漫着恨和愁的云雨之中，江南的景色，依旧是美丽的。南齐诗人谢朓《入朝曲》写道：“江南佳丽地，金陵帝王州。”王禹偁用“依旧”二字，表明自己是仅承旧说，透露出一种无可奈何的情绪。\n\n　　上片煞拍写的是：蒙蒙的雨幕中，村落渔市点缀湖边水畔；一缕淡淡的炊烟，从村落上空袅袅升起；水天相连的远处，一行大雁，首尾相连，款款而飞。但如此佳丽的景色，却未能使词人欢快愉悦，因为“天际征鸿，遥认行如缀”。古人心目中，由飞鸿引起的感想有许多。如“举手指飞鸿，此情难具论”（李白《送裴十八图南归嵩山》）。这里，词人遥见冲天远去的大雁，触发的是“平生事”的联想，想到了男儿一生的事业。王禹偁中进士后，只当了长洲知县。这小小的芝麻官，无法实现他胸中的大志，于是他恨无知音，愁无双翼，不能像“征鸿”一样展翅高飞。最后，王词将“平生事”凝聚对“天际征鸿”的睇视之中，显得含蓄深沉，言而不尽。\n\n　　这首词艺术风格上一改宋初小令雍容典雅、柔靡无力的格局，显示出别具一格的面目。词中交替运用比拟手法和衬托手法，层层深入，含吐不露，语言清新自然，不事雕饰，读来令人心旷神怡。从思想内容看，此词对于改变北宋初年词坛上流行的“秉笔多艳冶”的风气起了重要作用，为词境的开拓作了一定的贡献。', poem_tags = '宋词三百首,宋词精选,婉约,写景,抒情,无奈' WHERE poem_title = '点绛唇·感兴' AND poem_author = '王禹偁';
UPDATE edu_poem SET poem_translation = '我辈梦魂经常萦绕着未光复的祖国中原之路。在萧瑟的秋风中，一方面，金兵营垒相连，军号凄厉；另方面，故都汴京的皇宫宝殿已成废墟，禾黍充斥，一片荒凉，真是令人惆怅呵！为什么黄河之源昆仑山的天柱和黄河的中流砥柱都崩溃了，黄河流域各地泛滥成灾？如今，中原人民国破家亡，流离失所。人口密聚的万落千村都变成了狐兔盘踞横行之地。杜甫句云：“天意高难问，人情老易悲。”从来是天高难问其意。如今我与君都老了，也容易产生悲情，我们的悲情能向谁倾诉呢?我只能默默地相送到南浦。送君远去！\n别后，我仍然会伫立江边眺望，不忍离去。见柳枝随风飘起，有些凉意，残暑渐消。夜幕降临，银河横亘高空，疏星淡月，断云缓缓飘动。万里江山，不知君今夜流落到何处？回忆过去与君对床夜语，畅谈心事，情投意合，这情景已不可再得了。俗话说雁断衡阳，君去的地方连大雁也飞不到，写成了书信又有谁可以托付？我辈都是胸襟广阔，高瞻远瞩之人，我们告别时，看的是整个天下，关注的是古今大事，岂肯像小儿女那样只对彼此的恩恩怨怨关心？让我们举起酒杯来，听我唱一支《金缕曲》，送君上路！', poem_notes = '底事：言何事。\n昆仑倾砥柱：古人相信黄河源出昆仑山，《淮南子·地形训》：“河水出昆仑东北陬”。传说昆化山有铜柱，其高入天，称为天柱。此以昆仑天柱，黄河砥柱，连类并书。\n九地黄流乱注：喻金兵的猖狂进攻。\n聚万落千村狐兔：形象描写中原经金兵铁蹄践踏后的荒凉景象。\n耿：明亮。\n大白：酒杯名。', poem_appreciation = '“贺新郎”是这首词的词牌，“送胡邦衡谪新州”是这首词的题目，亦可看作是小序，作者在这里交待了词的写作背景、原因和主题。\n\n　　词的上阕述时事。有三层意思：\n\n　　第一层：梦绕神州路。怅秋风、连营画角，故宫离黍。写中原沦陷的惨状，形象地概括了北宋灭亡的历史事实，有尺幅千里之势。\n\n　　首句：梦绕神州路。写作者自己日夜思念北方国土，连做梦都在围着北宋故都汴京的路转。“绕”，即萦绕，牵挂心间，不能忘怀。这里有徘徊、巡回之意。“神州路”，古称中国为赤县神州，（见《史记·孟子荀卿列传》）这里指中原沦陷区。作者为什么要将中原沦陷之惨状托之于梦呢？含意有二：一是中原沦陷不可去，沦陷之惨唯可于梦中见之；二是中原之沦陷如恶梦一般。实景虚写，写出人心之惨痛，故有第二层的质问。\n\n　　怅秋风、连营画角，故宫离黍。这两句写梦中所见。中原沦陷惨状，以“怅”为领字。所怅者，一是“连营画角”金兵军营相望，军号凄厉。 二是“故宫离黍”。当他在梦中来到汴京的时候，那萧瑟的秋风，更引起了他的无限悲伤，当年繁华的汴京，已成了金兵的军营，一阵阵哀厉高亢的军号声连成一片，原来的皇宫大殿长满了野草，完全变成了荒凉的废墟。\n\n　　以上几句，层层递转，字字沉实，词人悲愤之情，愈转愈深沉。因为胡铨主张收复中原、反对议和而得罪权臣，被贬谪岭南，所以起笔即从中原写起。“梦绕神州路。怅秋风、连营画角，故宫离黍。”是写对中原地区的深沉怀念和收复失地的愿望。作者通过对北宋灭亡、汴京荒凉的描写，表达了对国事的忧伤。这就与坚决主战的胡铨沟通了感情，因为他们的心情和意志都是一致的。所以这个开头很不寻常，作者不写送别之情，不写景物之状，而从共同关心的国事写起，表示对友人被贬谪的同情，并引以为知已，说明他们是志同道合的。\n\n　　第二层：底事昆仑倾砥柱，九地黄流乱注。聚万落、千村狐兔。严词质问悲剧产生的根源，是对开头四句的追问和深思。到底是什么原因，使我们的国家变成这个样子呢？\n\n　　底事昆仑倾砥柱，底事，即何事，什么事，什么原因，为什么？“昆仑倾砥柱”即“倾昆仑砥柱”。昆仑,即昆仑山。古人相信黄河源出昆仑山，传说昆仑山有铜柱，其高入天，称为天柱。见《淮南子·地形训》：“河水出昆仑东北陬。”《神异经·中荒经》：“昆仑之山，有铜柱焉。其高入天，所谓天柱也。”古人以昆仑为至高无上的山。砥柱，即砥柱山，在今河南陕县东北黄河中。《水经·河水注》：“砥柱，山名也。昔禹治洪水，山陵当中者凿之，故破山以通河，河水分流，包山而过，山见水中如柱然，故曰砥柱也。”《禹贡》称：“异河积石，至于龙门，又东至于砥柱。”倾，即摧毁、倒塌。作者在这里以昆仑天柱，黄河砥柱，连类并书，比喻北宋王朝倾垮。\n\n　　九地黄流乱注。喻指金人的入侵以及战争带来的惨景。九地：九州，即中国，这里指中原沦陷区。黄流乱注：黄河泛滥，洪水横流。这里喻指金兵的猖狂入侵。\n\n　　聚万落、千村狐兔。即“万落千村狐兔聚”，形象描写中原经金兵铁蹄践踏后的荒凉破败景象。正如曹操在《蒿里行》描写的那样：“白骨露于野，千里无鸡鸣。生民百遗一，念之断人肠。”落，即村落。狐兔，这里指入侵之敌。\n\n　　在这里，作者叙述了国家残破之恨和人民遭难的惨状，以山崩地裂，洪水泛滥比喻国家的破亡和金兵的入侵，用狐狸和野兔的聚集，表现了战争造成的荒凉，反映出人民所承受的灾难。又以“九地黄流乱注”与上层的“连营画角”，“聚万落、千村狐兔”与上层的“故宫离黍”，上下照应，显得生动形象，深沉悲愤。\n\n　　在第二层中，诗人提出了疑问，问而不答。乃因答案分明，不言即知，况且涉及朝廷统治者而不能言。故而笔锋一转，写出了以下几句：天意从来高难问，况人情、老易悲难诉。更南浦，送君去。其言外之意是：天高固然难测，而衣冠华族沦于异族之手，实乃人事使然。此为第三层，感慨时事，点明送别。\n\n　　天意从来高难问，天意：上天的意志。此指皇帝的态度。高难问：难以让人琢磨，猜不透。\n\n　　况人情、老易悲难诉。况：况且。人情：人们之间的交往情谊。一说“人之常情”。老易悲，是说天意既难测，而人越到老了，想起人们之间交往的友情，越容易感到悲伤，今有深仇而不思报，故长叹：悲难诉。从这里可以看出，“悲难诉”的内涵是：北宋议和灭亡之悲难诉；南宋王朝苟且偷生、偏安江左、迫害忠良，这种悲伤是难以诉说的。\n\n　　“天意从来高难问，况人情、老易悲难诉。”出自杜甫诗《暮春江陵送马大卿公恩命追赴阙下》“天意高难问，人情老易悲”，以表示对高高在上的执政者的心意难测，一味妥协投降、忘了亡国之仇的不满。\n\n　　更南浦，送君去。写送别。作者的笔锋自然转至送别胡铨。南浦，泛指送别的地方。出自屈原《九歌·河伯》：“子交手兮东行，送美人兮南浦。”或江淹《别赋》：“春草碧色，春水渌波。送君南浦，伤如之何！”\n\n　　以上几句是写作者对南宋朝廷的不满和对胡铨的慰勉。在上一层里，作者用浓重的笔墨写出了亡国之痛，至此便很自然地要问：这一切是怎么造成的？究竟是谁的过错呢？在当时，这答案不能明白讲出，所以作者只好借杜甫的“天意高难问，人情老易悲”这两句诗，来暗示国破家亡的罪责，应由最高统治者来承担。诗人以怨愤的笔调写道：上天的意志向来都是难以令人猜测的，何况人越到老了，想起人们的交往之情越容易悲伤，这种悲伤的原因也很难诉说得清楚。是为国家的命运悲伤，还是因为朋友的贬谪悲伤，作者使用“难诉”二字，其意丰蕴含蓄，即是对上面问题的回答，又给人留下了回味的余地。人老了容易悲伤，现在为自己的知已送别，其悲伤更属必然了，所以，作者用“更”字，又深入了一层，具体落实在送别上，至此点明主题。\n\n　　上阕的安排，突出了作者同友人共同的忧国思想，而把个人的伤离放在了次要地位，使作者与友人的惜别之情不同于一般，这就与那些只写离情别绪的俗套之作有明显的区别。突出了共同的爱国思想，也就把词的境界，提到了新的高度。故词的下阕转写友谊与慰勉，叙别情：凉生岸柳催残暑。耿斜河、疏星淡月，断云微度。万里江山知何处。回首对床夜语。雁不到、书成谁与。目尽青天怀今古，肯儿曹、恩怨相尔汝。举大白，听金缕。\n\n　　下阕也有三层意思：\n\n　　第一层：凉生岸柳催残暑。耿斜河、疏星淡月，断云微度。换头四句紧扣上阕结尾送君“南浦”之意，通过景物描写，说明送别的时间与地点。\n\n　　首句：凉生岸柳催残暑。点明季节，说明作者写词时，是在夏末秋初之夜。初秋的凉风从岸边烟柳丛里吹来，驱散了残余的暑气，这是地面景象。而夜空中，则是耿斜河、疏星淡月，断云微度。在横斜的银河里，散布着稀疏的星星，月亮洒着淡淡的月光，不时，偶有一两片云彩轻轻地缓缓地漂荡在空中。耿：明亮。斜河：天河，即银河；银河偏斜，又称斜汉，表示夜已深。这里作者以凄清的夜景衬托离别时的气氛和心情。此时此刻，有何感受呢？心里想了些什么呢？\n\n　　第二层：万里江山知何处。回首对床夜语。雁不到、书成谁与。设想分别后的情形，表达怀恋的深情。。\n\n　　万里江山知何处。极言今后相隔万里，不知道你在何处。\n\n　　回首对床夜语。回首：回忆，回想。对床夜语：两人对躺在床上谈话到深夜，说明友谊之深。对床，出自白居易《雨中招张司业宿》：“能来同宿否，听雨对床眠。”夜雨，出自李商隐《夜雨寄北》：“君问归期未有期，巴山夜雨涨秋池。何当共剪西窗烛，却话巴山夜雨时。”\n\n　　这几句曲曲折折抒写留恋之情：既反映了他们深厚的友情，也表达了他们对国事的感慨：君此去道路茫茫，国家前途亦茫茫。\n\n　　雁不到、书成谁与。书，即书信。雁不到：相传雁能传书，但北雁南飞止于衡阳回雁峰，而新州在衡阳之南。故民间有“大雁飞不到岭南，书信难以寄出”的说法。范仲淹《渔家傲》“塞下秋来风景异，衡阳雁去天留意”也是说宋代朝臣贬谪远方，好友大都不敢互通音讯。苏轼等人，也常在诗中提到过。“雁不到”，为假托而已。\n\n　　这几句是先从眼前的分别写起，次忆旧情，复叹别后悲伤。意思是：今宵分别之后，我们相隔千山万水，谁能知道你究竟在什么地方呢？从今以后，天各一方，而我们对床夜话的情景，将成为美好的回忆，唯有通过书信表达我们的友情。但是，新州是个连大雁也飞不到的地方，就是写成了书信，又有谁捎得去呢？这里由眼前的送别，想到了今后可能书信难通，只能回忆以前的友情，这就更深入一层地表达了作者对友人离去的留恋和悲伤。\n\n　　以上几句，格调悲沉。词的结尾，作者劝慰友人，调子转而激昂：目尽青天怀今古，肯儿曹、恩怨相尔汝。举大白，听金缕。这是第三层：遣愁致送别意。\n\n　　“目尽青天怀今古”照应“天意从来高难问”，远望天空，想到古今世态的变化，有四顾苍茫之感。目尽：极目远望。\n\n　　肯儿曹、恩怨相尔汝。言大丈夫不能“无为在歧路，儿女共沾巾”。意思是：我们谈的都是国家大事，怎么能像孩子一样只顾说个人恩怨呢？肯，在这里是怎么肯的意思。儿曹，即小儿女辈。儿曹恩怨：指小孩之间一会儿好，一会儿埋怨。相尔汝，形容两人讲话时互相指着对方的那种样子。尔和汝，都是“你”的意思。出自韩愈《听颖师弹琴》：“昵昵儿女语，恩怨相尔汝。”\n\n　　举大白，听《金缕》。作者满腹悲愤感情，通过层次井然的多次转折，这几句是说，遥望苍天，俯仰今古，历史上出现了多少英雄人物，我们也要象他们那样，决不做只念恩怨私情的儿女之辈。请满饮此杯后，听我唱一曲《金缕》，为你壮行送别吧！词的煞拍，创造了一个激昂阔大的意境，雄壮的笔调，表现了作者不肯屈服，坚持斗争的精神，传达了对朋友的鼓励和支持，具有鼓舞人心的力量。\n\n　　通观全词，可以看出，这是一首不寻常的送别词，它打破了历来送别词的旧格调，把个人之间的友情放在了民族危亡这样一个大背景中来咏叹，既有深沉的家国之感，又有真切的朋友之情；既有悲伤的遥想，又有昂扬的劝勉。作者以慷慨悲凉的笔调，所抒发的不是缠绵悱恻的离愁别恨，而是忧念国事艰危的愤慨之情。作者连梦中都思念着被金军蹂躏的中原河山，表现了对南宋投降路线的不满与愤恨，特别是词的结尾所表白的与友人共勉的磊落胸襟和远大的抱负，在当时的艰难困境中，是十分可贵的。', poem_tags = '宋词三百首,豪放,送别,忧国忧民' WHERE poem_title = '贺新郎·送胡邦衡待制赴新州' AND poem_author = '张元干';
UPDATE edu_poem SET poem_translation = '徒手搏猛虎，辩口若河悬，车象鸡笼驰马如狗窜。头戴平民白丝巾，黄尘追着飞马卷。谁知我们这些人，是否来蓬篱草民间？道边衰兰泣落送我出京城，苍天有情也会衰老不忍把眼睁。谁管旗亭美酒一杯值万钱，\n我要痛快淋漓倾酒坛。睡如雷鸣行如颠，只管将来，搬，搬，搬！倒大杯，满，满，满！为我们健康，干，干，干！鬓发常青古未有。转眼红颜变苍颜。你看卖酒秦地女，婚然一笑有多甜。翩翩起舞赛天仙，刚刚十五如花年，莺歌燕语如琴弦。还记得汉武帝遗音《秋风辞》，千年过去，至今犹恨人生短！抓住流逝光阴不松手，把太阳拴在扶桑颠。哎，无奈，忧愁袭来，一天一天长一天。', poem_notes = '缚虎手：即徒手打虎。\n悬河口：言辞如河水倾泻，滔滔不绝，即“口若悬河”，比喻人的健谈。\n车如鸡栖马如狗：车盖如鸡栖之所，骏马奔如狗。\n白纶（guān）巾：白丝头巾。\n扑黄尘：奔走于风尘之中。\n“衰兰”二句：李贺《金铜仙人辞汉歌》中的句子。\n旗亭：即酒楼。此指送别之地。\n当垆秦女：用辛延年《羽林郎》诗：“胡姬年十五，春日独当垆”。语如弦：韦庄词《菩萨蛮》：“琵琶金翠羽，弦上黄莺语。”这里指胡姬的笑语象琵琶弦上的歌声。\n遗音：遗留下的歌曲。秋风曲：指汉武帝《秋风辞》，其结尾云：“欢乐极兮哀情多，少壮几时兮奈老何！”感叹欢乐不长，人生苦短。\n扶桑：神话中神树，古谓为日出处。《淮南子》：“日出于旸谷，浴于咸池，拂于扶桑。”系扶桑，即要留住时光，与“揽流光”意同。\n争奈：怎奈。', poem_appreciation = '贺铸这一首词就抒写了词人报国无门、功业难成的失意情怀。\n\n　　“缚虎手，悬河口”均借代人才。手能暴虎者为勇士，可引申为有军事才能的人；口如悬河者为谋士，可引申为有政治才干的人。倘若逢辰，这样的文武奇才当高车驷马，上黄金台，封万户侯。可眼前却穷愁潦倒，车不大，像鸡窝，马不壮，像饿狗。“车如鸡栖马如狗”极形车敝马瘦，与“缚虎手，悬河口”的夸张描写适成强烈对照，不平之气溢于言表。以下正面申抱负，写感慨：“白纶巾，扑黄尘，不知我辈可是蓬蒿人？”白纶巾亦犹白衣之类，为未出仕之人所著。黄尘指京城的尘土，黄庭坚《呈外舅孙莘老》诗：“九陌黄尘乌帽底，五湖春水白鸥前。”任渊注引《三辅黄图》：“长安城中，八街九陌。”这六字两句参用陆机《代顾彦先赠妇》“京洛多风尘，素衣化为缁”之意，谓白衣进京。结合下句“不知我辈可是蓬蒿人”，谓此行不知可否取得富贵。李白《南陵别儿童入京》：“游说万乘苦不早，著鞭跨马涉远道。会稽愚妇轻买臣，余亦辞家西入秦。仰天大笑出门去，我辈岂是蓬蒿人！”李诗题说“入京”，诗句说“游说万乘（皇帝）”、“辞家西入秦”，皆贺词“扑黄尘”注脚。词径取李诗末句，而易一字增二字作“不知我辈可是蓬蒿人”，虽自负而带一种傍徨苦闷情态，与李白的仰天大笑、欣喜如狂不同，读来别有意味。以下“衰兰送客咸阳道，天若有情天亦老”，则袭用李贺《金铜仙人辞汉歌》原句。但原辞是通过汉魏易代之际铜人的迁移，写盛衰兴亡之悲感，言天若有感情天也会衰老，何况乎人。此处则紧接上文抒写不遇者奔走风尘，“天荒地老无人识”的悲愤。以上从志士之困厄写到志士之牢骚，继而便写狂放饮酒。做了侠义之事不受酬金，像“雷颠”一样；唯遇美酒则不问价。李白《行路难》云：“金樽清酒斗十千，玉盘珍羞值万钱。”“作雷颠，不论钱，谁问旗亭美酒斗十干”，写出不趋名利，纵酒放歌，乘醉起舞，一种狂放情态。其中含有无可奈何的悲愤，但写得极有气派，使词情稍稍上扬。\n\n　　简言之，此词上片由愁写到酒，而下片则由酒写到愁。过片极自然。不过上片所写的愁，主要是志士失路的忧愁；而下片则转出另一重愁情，即人生短促的忧愁：“酌大斗，更为寿，青鬓长青古无有。”词情为之再抑。以下说到及时行乐，自非新意，但写得极为别致。把歌舞与美人打成一片写来，写笑以“嫣然”，写舞以“翩然”，形容简妙；“当垆秦女十五”云云是从乐府《羽林郎》“胡姬年十五，春日正当垆”化出，而“语如弦”三字，把秦女的声音比作音乐一样动人，新鲜生动，而且不必写歌已得歌意。这里极写生之欢愉，是再扬，同时为以下反跌出死之可悲作势。汉武帝《秋风辞》云：“欢乐极兮哀情多，少壮几时兮奈老何。”秋风曲虽成“遗音”，但至今使人记忆犹新，觉“事去千年犹恨促”。由于反跌的作用，此句比“青鬓长青古无有”句更使人心惊。于是作者遂生出“揽流光，系扶桑”的奇想。似欲挽住太阳，系之于扶桑之树，“使之朝不得回，夜不得伏。自然老者不死，少者不哭”（李贺《苦昼短》）。这种超现实的奇想，都恰好反映出作者无法摆脱的现实苦闷。“志士惜日短”，只有怀才不遇的人最易感到生命短促、光阴虚掷的痛苦。·所以下片写生命短暂的悲愁，与上片写志士失路的哀苦也就紧密联系在一起。“行路难”的题意也已写得淋漓尽致了。不料最末一句却来了个大转折：“争奈愁来一日却为长！”前面说想留驻日光，使人长生不死，这里却说愁人情愿短命；前面说“事去千年犹恨促”，这里却说一天的光阴也长得难过。一句几乎翻转全篇，却更深刻地反映出志士苦闷而且矛盾的心情，将“行路难”的“难”字写到入木三分。\n\n　　全词艺术特点有三：“词别是一家”，在当时是很流行的看法，而这首词却写得像诗中的歌行体。“行路难”本就是乐府歌行的题目，此其一；《小梅花》的调式也很特殊，以三字句、七字句为主，间用九字句，“三三七”、“三三九”、“七七”的句式交替使用，句句入韵，平仄韵互换，都与歌行相近，此其二；大量化用前人歌行诗句，其中以采自李白、李贺者为多，此其三。贺铸曾说：“吾笔端驱使李商隐、温庭筠常奔命不暇”（厨密《浩然斋雅读》引贺语），可见善于隐括前人诗意或化用前人诗句，是贺词的一个艺术特点，此词表现很突出。\n\n　　全词表现作者于失意无聊纵酒放歌之际，既感乐往悲来、流光易逝，又觉愁里光阴无法排遣的矛盾苦闷心情，但却用刚健的笔调、高亢的声调写成，章法上极抑扬顿挫之能事，行文上跌宕生姿，属于贺词中的幽洁悲壮之作，在北宋词坛上也是很突出的作品。', poem_tags = '豪放,失意,友情' WHERE poem_title = '行路难·缚虎手' AND poem_author = '贺铸';
UPDATE edu_poem SET poem_translation = '我长年在外，每年一到春天的时候，独自在他乡不胜悲伤，坐在树下饮酒，那树上的黄莺也应该了解我思乡的心情吧。看到江岸渐落的残阳，就仿佛心肠被撕扯成片片柳叶。', poem_notes = '题名：乡，《绝句》作“归”。\n岸上：席本作“上岸”。', poem_tags = '思乡' WHERE poem_title = '江外思乡' AND poem_author = '韦庄';
UPDATE edu_poem SET poem_translation = '我虽然胸怀匡国之志，也有郭元振《宝剑篇》那样充满豪气的诗篇，但却不遇明主，长期羁旅在外虚度华年。\n黄叶已经衰枯，风雨仍在摧毁，豪门贵族的高楼里，阔人们正在轻歌曼舞，演奏着急管繁弦。\n新交的朋友遭到浇薄世俗的非难，故旧日的老友又因层层阻隔而疏远无缘。\n心中想要断绝这些苦恼焦烦，要用新丰美酒来销愁解闷，管它价钱是十千还是八千。', poem_notes = '这首诗取第三句诗中“风雨”二字为题，实为无题。\n宝剑篇：为唐初郭震（字元振）所作诗篇名。《新唐书·郭震传》载，武则天召他谈话，索其诗文，郭即呈上《宝剑篇》，中有句云：“非直接交游侠子，亦曾亲近英雄人。何言中路遭捐弃，零落飘沦古岳边。虽复沉埋无所用，犹能夜夜气冲天。”武则天看后大加称赏，立即加以重用。\n羁泊：即羁旅飘泊。穷年：终生。\n黄叶：用以自喻。仍：仍旧，依然。\n青楼：青色的高楼。此泛指精美的楼房，即富贵人家。\n新知：新的知交。遭薄俗：遇到轻薄的世俗。\n旧好：旧日的好友。隔：阻隔，断绝。\n心断：意绝。新丰：地名，在今陕西省临潼县东，古时以产美酒闻名。《新唐书·马周传》载，马周不得意时，宿新丰旅店，店主人对他很冷淡，马周便要了一斗八升酒独酌。后得常何推荐，受到唐太宗的赏识，授监察御史。\n几千：指酒价，美酒价格昂贵。', poem_appreciation = '诗人李商隐一生坎坷，仿佛一直在受到风雨的摧残，故此诗慷慨悲歌，一伸抑郁愤懑之气。\n\n　　这首诗一开篇就在苍凉沉郁的气氛中展示理想与现实的矛盾。唐代前期名将郭元振也因曾落拓未遇，但因《宝剑篇》而深得武后赏爱，终于实现匡国之志。这里暗用此典。首句中的“宝剑篇”，系借指自己抒发不遇之感的诗作，故用“凄凉”来形容。从字面看，两句中“凄凉”、“羁泊”连用，再加上用“欲穷年”来突出凄凉羁泊生涯的无穷无已，似乎满纸悲酸凄苦。但由于“宝剑篇”这个典故本身所包含的壮怀激烈的意蕴和郭元振这位富于才略的历史人物在读者脑海中引起的联想，它给人们的实际感受，却是在羁旅飘泊的凄凉中蕴积着一股金剑沉的郁勃不平之气。\n\n　　颔联承上，进一步抒写羁泊异乡期间风雨凄凉的人生感受。前句触物兴感，实中寓虚，用风雨中飘零满地的黄叶象征自己不幸的身世遭遇，与后句实写青楼管弦正形成一喧一寂的鲜明对比，形象地展现出沉沦寒士与青楼 豪贵苦乐悬殊、冷热迥异的两幅对立的人生图景。两句中“仍”、“自”二字，开合相应，极富神味。“仍”是更、兼之意。黄叶本已凋衰，再加风雨摧残，其凄凉景象更令人触目神伤。它不仅用加倍法写出风雨之无情和不幸之重沓，而且有力地透出内心难以忍受的痛苦。“自”字既有转折意味，又含“自顾”之意，画出青楼豪贵得意纵恣、自顾享乐、根本无视人间另有忧苦的意态。它与“仍”字对应，正显示出苦者自苦、乐者自乐那样一种冷酷的社会现实和人间关系，而诗人对这种社会现实的愤激不平，也含蓄地表现了出来。 [2] 在羁泊异乡的凄凉孤孑境况中，友谊的温暖往往是对寂寞心灵的一种慰藉，颈联因此自然引出对“新知”、“旧好”的忆念。但思忆的结果却反而给心灵带来更深的痛苦——“新知遭薄俗，旧好隔良缘。”由于无意中触犯了朋党间的戒律，诗人不但仕途上偃蹇不遇，坎坷终身，而且人格也遭到种种诋毁，被加上“放利偷合”、诡薄无行”（《新唐书·李商隐传》）一类罪名。在这种情况下，“旧好”关系疏远，“新知”遭受非难便是必然的了。两句中一“遭”一“隔”，写出了诗人在现实中孑然孤立的处境，也蕴含了诗人对“薄俗”的强烈不满。从“青楼自管弦”到“旧好隔良缘”，既是对自己处境的深一层描写，也是对人生感受的深一层抒发。凄冷的人间风雨，已经渗透到知交的领域，茫茫人世，似乎只剩下冰凉的雨帘，再也找不到任何一个温暖的角落了。\n\n　　唯一能使凄凉的心得到暂时温暖的便只有酒——”心断新丰酒，销愁斗几千？”和首联的“宝剑篇”一样，这里的“新丰酒”也暗用典故。初唐的马周落拓未遇时，西游长安，住新丰旅舍。受到冷遇，遂取酒独酌，表现出不凡的气度和性格。后来受到皇帝赏识，拔居高位。诗人想到自己只有马周当初未遇时的落拓，却无马周后来的幸遇，所以只能盼望着用新丰美酒一浇胸中块垒。然而羁泊异乡，远离京华，即使想如马周失意时取新丰美酒独酌也不可得，所以说“心断”。通过层层回旋曲折，终于将诗人内心的郁积苦闷发抒到极致。末句以问语作收，似结非结，正给人留下苦闷无法排遣、心绪茫然无着的印象。\n\n　　诗题“风雨”，具有象征意蕴。象征着包围、压抑、摧残、扼杀贤才的冷酷无情的社会现实。但品味全诗，便会体会到作者在批判揭露阴暗现实的同时又表现一种积极用世的生活热情。首、尾两联用郭元振、马周之典也流露出对初唐开明政治的向往和匡时济世的强烈要求。这正是一切正直的有事业心而又不遇于时的知识分子所共有的心境，故此诗具有典型性和深广的社会意义。', poem_tags = '唐诗三百首,怀才不遇,风雨' WHERE poem_title = '风雨' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '长江春水碧绿如染料，刚刚破出水面的点点荷叶只有铜钱大小。\n自己在那江头种下的橘树，也无法拴住将要远行的小舟。', poem_notes = '堪：能，可。\n钱：指铜钱。', poem_tags = '春天,长江' WHERE poem_title = '春别曲' AND poem_author = '张籍';
UPDATE edu_poem SET poem_translation = '新婚夫妇，夫君就像是女萝草，妻妾就如菟丝花。\n女子有了心上人，就好像轻柔的枝条，只有在春风里才会摇曳生姿。\n新婚以后，妻妾希望依附夫君，让彼此关系缠绵缱倦、永结同心。\n谁说见一面很容易，我们各自在青色山崖的两边。\n君在外春风得意、如鱼得水，而妻妾却在家里忧心匆匆、痛断肝肠。\n妻妾在家除了相夫教子外，别无旁务，因而想入非非。\n我的归宿在哪里？夫君该不会在外面与别的女子“共芬芳”、做“鸳鸯”吧？\n夫君啊！假如为妾的有二心的话，那么海水也可以用斗来量了。', poem_notes = '女萝：一种靠依附他物生长的地衣类植物。古人常以此比喻新婚夫妇。\n菟丝：一种利用爬藤状构造攀附在其他植物上的寄生植物。古人常以此比喻新婚夫妇。\n引：避开，退却。\n托：寄托，依靠。\n竞：争逐，比赛。\n上宿：指睡觉。', poem_appreciation = '这是一首怨妇诗。李太白乃浪漫主义豪放派诗人。很多作品均狂放不羁，如“飞流直下三千尺”、“黄河之水天上来”等等。细腻的描写风花雪月、儿女情长的作品不是太多。\n\n　　“君为女萝草，妾作冤丝花”。古人常以“菟丝”、“女萝”比喻新婚夫妇，优美贴切，因而传诵千古 。冤丝花为曼生植物，柔弱，茎细长略带黄色，常常缠绕在其他植物之上；女萝草为地衣类植物，有很多细枝。诗人以“菟丝花”比作妻妾，又以「女萝草」比喻夫君，意谓新婚以后，妻妾希望依附夫君，让彼此关系缠绵缱倦、永结同心。即所谓“百丈托远松，缠绵成一家”。\n\n　　“女萝发馨香，菟丝断人肠。枝枝相纠结，叶叶竞飘扬”。大意可能是说，夫君在外春风得意、如鱼得水，而妻妾却在家里忧心匆匆、痛断肝肠。\n\n　　“生子不知根，因谁共芬芳。中巢双翡翠，上宿紫鸳鸯”。我只想用一个字来理解——怨。过去，男主外、女主内。妻妾在家除了相夫教子外，别无旁务，因而想入非非。我的归宿在哪里？夫君该不会在外面与别的女子“共芬芳”、做“鸳鸯”吧？\n\n　　“若识二草心，海潮亦可量”。妻妾向夫君表明态度：夫君啊！假如为妾的有二心的话，那么海水也可以用斗来量了。大约相当于今天的“海枯石烂不变心”吧！', poem_tags = '妇女,闺怨' WHERE poem_title = '古意' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '宜阳城外，长满了繁盛的野草，连绵不绝，山涧溪水向东流去，复又折回向西。\n春山之中，树木繁茂芬芳，然空无一人，花儿自开自落，一路上鸟儿空自鸣啼。', poem_notes = '宜阳：古县名，在今河南省福昌县附近，在唐代是个重要的游览去处，著名的连昌宫就建在这里。\n芳树、春山：这两句互文见义，即春山之芳树。', poem_tags = '春天,写景,感伤' WHERE poem_title = '春行即兴' AND poem_author = '李华';
UPDATE edu_poem SET poem_tags = '咏物,言志,赞美,写风' WHERE poem_title = '咏风' AND poem_author = '王勃';
UPDATE edu_poem SET poem_translation = '仲子哥啊你听我说，别翻越我家门户，别折了我种的杞树。哪是舍不得杞树啊，我是害怕我的父母。仲子哥实在让我牵挂，但父母的话也让我害怕。\n仲子哥啊你听我讲，别翻越我家围墙，别折了我种的绿桑。哪是舍不得桑树啊，我是害怕我的兄长。仲子哥实在让我牵挂，但兄长的话也让我害怕。\n仲子哥啊你听我言，别越过我家菜园，别折了我种的青檀。哪是舍不得檀树啊，我是害怕邻人毁谗。仲子哥实在让我牵挂，但邻人毁谗也让我害怕。', poem_notes = '将（qiāng）：愿，请。一说发语词。仲子：兄弟排行第二的称“仲”。\n逾：翻越。里，居也，五家为邻，五邻为里，里外有墙。越过里墙。\n杞（qǐ）：木名，即杞柳。又名“榉”。落叶乔木，树如柳叶，木质坚实。树：种植。一说树桑、树檀，即桑树、檀树，倒文以协韵。\n爱：吝惜。\n怀：思念。\n檀：木名，常绿乔木。一名“紫檀”。', poem_appreciation = '《郑风·将仲子》所表现的，便正是一位青年女子在春秋时期社会舆论压迫下的畏惧、矛盾心理。首章开口即是突兀而发的呼告之语：“将仲子兮，无逾我里，无折我树杞！”这呼告初听令人摸不着头脑，细细品味又不免莞尔而笑：诗行中分明透露着，有一对青年男女正要私下相会。热恋中的男子（仲子）大约有点情急，竞提出了要翻墙过园前来相会的方案。这可把女子吓坏了，须知“钻穴隙相窥，逾墙相从”，是要遭父母、国人轻贱和斥骂的；她想：“倘若心上人也如此鲁莽，可教我把脸儿往哪里搁？”于是便有了开章那三句的突发呼告。这呼告是温婉的，一个“将”（愿）字，正传达着女子心间的几多情意；但它又是坚决的，那两个“无”（不要）字，简直没有商量的余地。如果读者读得再深入些，当还能想见女主人公此刻因惶急而变得苍白的面容，还有“仲子”那因被拒绝而失望的神情。\n\n　　这失望也为女主人公感觉到了，诗中由此跳出了一节绝妙的内心表白：“岂敢爱之？畏我父母。仲可怀也，父母之言，亦可畏也。”前一句反问问得蹊跷，正显出了女主人公的细心处，她唯恐“无折我树杞”的求告，会被心上人误会，故又赶紧声明：“岂敢爱之？畏我父母。”——我不是吝惜杞树，我只是怕我父母知道；因此虽然爱着你，却不能让你翻墙折杞前来，我实在是迫不得已啊。这番对心上人作解释的自白，一个“畏”字，吐露着她对父母的斥责，竟是如何的胆战心惊。这样一来，仲子却也不是完全绝望。“仲可怀也”三句表明，可怜的女主人公在担心之余，毕竟又给了心上人以温言软语的安慰：“我实在是天天想着你呀，只是父母的斥骂，也实在让我害怕呀……”话语絮絮、口角传情，似乎是安慰，又似乎是求助，活脱脱画出了热恋中少女那既痴情、又担忧的情态。\n\n　　第二、三两章初看只是对首章的重复，其实却是情意抒写上的层层递进。从女主人公呼告的“无逾我里”，到“无逾我墙”、“无逾我园”，可推测她那热恋中的“仲子”，已怎样不顾一切地翻墙逾园、越来越近。但男子可以鲁莽行动，女子却受不了为人轻贱的闲话。所以女主人公的畏惧也随之扩展，由“畏我父母”至于“畏我诸兄”，最后“畏”到左邻右舍的“人之多言”。让人觉得那似乎是一张无形的大网，从家庭一直布向社会，谁也无法挣得脱它。这就是不准青年男女恋爱、私会的礼法之网，它经了“父母”、“诸兄”和“人之多言”的重重围裹，已变得多么森严和可怕。由此品味女主人公的呼告之语，也难怪一次比一次显得急切和焦灼了——她实在孤立无助，难于面对这众口嚣嚣的舆论压力。\n\n　　字面上只见女主人公的告求和疑惧，诗行中却历历可见“仲子”的神情音容：那试图逾墙来会的鲁莽，那被劝止引发的不快，以及唯恐惊动父母、兄弟、邻居的犹豫，连同女主人公既爱又怕的情态，俱可于诗中得之。中国古代诗论，特别推重诗的“情中景”“景中情”，《将仲子》所创造的，正是这种情中见景的高妙诗境。', poem_tags = '诗经,爱情,民谣' WHERE poem_title = '将仲子' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '有一个名字叫工之侨的人得到一块上好的桐木，砍来做成了一把琴，装上琴弦弹奏起来，发声和应声如金玉之声。他自认为这是天下最好的琴，就把琴呈现给太常寺（的主管人）；（主管人）让优秀的乐师来看，乐师说：“（这个琴）不是古琴。”于是便把琴退还回来。\n　　工之侨拿着琴回到家，跟漆匠商量，把琴身画上残断不齐的花纹；又跟刻工商量，在琴上雕刻古代的款式；把它装在匣子里埋在泥土中。过了一年挖出来，抱着它到集市上。有个达官贵人路过集市看到了琴，就用一百两黄金买了它，把它献到朝廷上。乐官们传递着观赏它，都说：“这琴真是世上少有的珍品啊！”\n　　工之侨听到这种情况，感叹道：“这个社会真可悲啊！难道仅仅是一把琴吗？不是这样的啊!世上的事情没有不是这样的。如果不早做打算，就要和这国家一同灭亡了啊！”于是离去,至宕冥附近的山,不知道他最终去哪儿了。', poem_notes = '工之侨：虚构的人名。\n良桐：上等桐木，即梧桐，青桐，木质理疏而坚，是制作古琴的好材料。桐，桐木，制古琴的材料。\n斫（zhuó）：砍削。\n弦而鼓：装上弦弹奏。弦、鼓，都是名词作动词用。弦：琴弦。这里作动词用，装上弦。鼓琴，指弹奏古琴。\n金声而玉应：发声和应声如金玉碰撞的声音。\n天下之美：天下最美的（琴）。美：美琴，形容词作名词用。\n太常：太常寺，祭祀礼乐的官署。\n使：让。\n国工：最优秀的工匠，这里指乐师。\n弗：不。\n谋：谋划。\n诸：兼词，之于。\n篆工：刻字的工匠。刻字多用篆体字。\n古窾（kuǎn）：古代的款式。窾,同“款“,款式。\n匣而埋诸土：（把它）装在匣子里并埋在泥土中。匣，装在匣子里。而，递进连词，并且。诸，兼语词，之于。\n期（ji第一声）年：第二年；满一年。\n适：到……去。\n贵人：大官。\n易：换，交易。\n乐官：掌管音乐的官吏。\n传视：大家传递看着。\n希：同“稀”，稀世：世上少有。\n悲哉世也：这个社会真可悲啊。\n岂：难道。\n独：只。\n莫：没有什么。\n然：如此。\n其：大概，表推测的语气副词\n其：代词，代指工之侨\n珍:珍宝。', poem_tags = '初中文言文,寓理,故事' WHERE poem_title = '工之侨献琴' AND poem_author = '刘基';
UPDATE edu_poem SET poem_translation = '我听说天下谈士聚在一起议论道：“人生不用封为万户侯，只愿结识一下韩荆州。”怎么使人敬仰爱慕，竟到如此程度！岂不是因为您有周公那样的作风，亲自做吐哺握发之事，故而使海内的豪杰俊士都奔走而归于您的门下。士人一经您的接待延誉，便声名大增，所以屈而未伸的贤士，都想在您这儿获得美名，奠定声望。希望您不因自己富贵而对他们骄傲，不因他们贫贱而轻视他们，那么您众多的宾客中便会出现毛遂那样的奇才。假使我能有机会显露才干，我就是那样的人啊。\n　　我是陇西平民，在楚汉游历。十五岁时爱好剑术，谒见了许多地方长官；三十岁时文章成就，拜见了很多卿相显贵。虽然身长不满七尺，但志气雄壮，胜于万人。王公大人都赞许我有气概，讲道义。这是我往日的心事行迹，怎敢不尽情向您表露呢？\n　　您的著作堪与神明相比，您的德行感动天地；文章与自然造化同功，学问穷极天道人事。希望您度量宽宏，和颜悦色，不因我长揖不拜而拒绝我。如若肯用盛宴来接待我，任凭我清谈高论，那请您再以日写万言试我，我将手不停挥，顷刻可就。如今天下人认为您是决定文章命运、衡量人物高下的权威，一经您的品评，便被认作美士，您何必舍不得阶前的区区一尺之地接待我，而使我不能扬眉吐气、激厉昂扬、气概凌云呢？\n　　从前王子师担任豫州刺史，未到任即征召荀慈明，到任后又征召孔文举；山涛作冀州刺史，选拔三十余人，有的成为侍中、尚书。这都是前代人所称美的。而您也荐举过一位严协律，进入中央为秘书郎；还有崔宗之、房习祖、黎昕、许莹等人，有的因才干名声被您知晓，有的因操行清白受您赏识。我每每看到他们怀恩感慨，忠义奋发，因此我感动激励，知道您对诸位贤士推心置腹，赤诚相见，故而我不归向他人，而愿意托身于您。如逢紧急艰难有用我之处，我当献身效命。\n　　一般人都不是尧、舜那样的圣人，谁能完美无缺？我的谋略策画，岂能自我夸耀？至于我的作品，已积累成为卷轴，却想要请您过目。只怕这些雕虫小技，不能受到大人的赏识。若蒙您垂青，愿意看看拙作，那便请给以纸墨，还有抄写的人手，然后我回去打扫静室，缮写呈上。希望青萍宝剑、结绿美玉，能在薛烛、卞和门下增添价值。愿您顾念身居下位的人，大开奖誉之门。请您加以考虑。\n\n译文二\n　　我李白听说天下一些谈论世事的人，聚集在一起时就会说：“人生不必封万户侯，只愿结识一下韩荆州。”为什么使人景仰爱慕竟然到了这样的程度呢!难道不是因为您有周公的风度，躬行吐哺、握发接待贤者的美德，才使得海内豪杰俊才，都奔集到您的门下，一经接待，如登龙门，立刻名声身价大增，十倍于前吗？所以那些才能超群的读书人，都希望在君侯处获得美名，得到评价。君侯不因为自己的富贵而傲视他们，也不因为他们的寒贱而轻忽他们，那么在众多的宾客中定有毛遂那样的奇才,假使我李白能有脱颖而出的机会，我就是那样的人啊。\n　　我李白是陇西平民，流落在楚地汉水一带。十五岁爱好剑术，拜访了许多地方长官；三十岁诗文有了成就，屡次拜谒朝廷高官。尽管我身高不满七尺，而心志超过万人。王公大人都赞许我有志节，讲道义。这是我从前的思想和行迹，怎敢不尽情地向您倾诉呢?\n　　君侯的功业堪比神明，您的德行感动天地，您的文章阐明了宇宙变化规律，学问探究了天道与人事的关系。希望君侯敞开胸怀，和颜接纳，不要因为我行长揖之礼晋见而拒绝我。假如能用盛大的宴席接待我，听任我纵情畅谈，那么我请以日试万言来测试，我将手不停笔，倚马可待。当今天下人以君侯为评论文章的主宰，权衡人物的权威，士人一经您的好评就成为德才兼备的佳士。君侯为什么吝惜庭阶前一尺见方的地方，不使我李白扬眉吐气，奋发昂扬于青云之上呢?\n　　从前王允任豫州剌史。尚未到任就征辟荀爽；到任之后又征辟孔融。山涛任冀州剌史，考查选拔了三十余人，有的任侍中，有的做尚书，这都是为前代所赞美的。\n　　君侯您也先荐举过严协律，进入朝廷担任秘书郎；还有崔宗之、房习祖、黎昕、许莹这班人，有的因为才干声名而得到您的了解，有的因品行清白而被您赏识。李白每每看到他们感恩戴德，抚躬自问,以忠义奋发自勉。李白也因此而感激，知道君侯对许多贤人赤诚相待，所以不归依他人，而愿把身心命运托付给国中才德至高的人。倘使君侯在急难之际，有用得着我的地方，我自当献身效命。\n　　而且，人不是尧舜，谁能十全十美?李白我在谋略策划方面，怎么能自负呢?至于写作，已经积累成卷轴，却想呈请君侯抽暇过目，只怕雕虫小技，不能受到大人的赏识。倘蒙垂顾，愿意看看拙作，那么，请赐予纸笔，加上书写人员。然后回去打扫安静的小屋，誊抄呈上。希望青萍宝剑、结绿美玉，在薛烛、卞和的手中提高价值。但愿君侯推恩于身处下位的人，大开奖励之门。请君侯考虑我的要求吧!', poem_notes = '谈士：言谈之士。孔融《与曹操论盛孝章书》：“天下谈士，依以扬声。”\n万户侯：食邑万户的封侯。唐朝封爵已无万户侯之称，此处借指显贵。\n景慕：敬仰爱慕。\n周公：即姬旦，周文王子，周武王弟。因采邑在周（今陕西歧山县北），故称周公。\n吐握：吐哺（口中所含食物）握发（头发）。周公自称“我一沐（洗头）三握发，一饭三吐哺，起以待士，犹恐失天下之贤人”（见《史记·鲁世家》），后世因以“吐握”形容礼贤下士。\n龙门：在今山西河津西北黄河两岸，峭壁对峙，形如阙门。传说江海大鱼能上此门者即化为龙。东汉李膺有高名，当时士人有受其接待者，名为登龙门。\n龙盘凤逸：喻贤人在野或屈居下位。收名定价：获取美名，奠定声望。\n君侯：对尊贵者的敬称，尤指上级。毛遂：战国时赵国平原君食客。秦围邯郸，赵王使平原君求救于楚，毛遂请求随同前往，自荐说：“臣乃今日请处囊中耳。使遂早得处囊中，乃颖脱而出，非特其末见而已。”随从至楚，果然说服了楚王，使其同意发兵。平原君于是奉他为上客（见《史记·平原君虞卿列传》）。颖（yǐng）：指锥芒。颖脱而出，喻才士若获得机会，必能充分显示其才能。\n陇西：古郡名，始置于秦，治所在狄道（今甘肃临洮）。李白自称十六国时凉武昭王李暠之后，李暠为陇西人。布衣：平民。楚汉：当时李白安家于安陆（今属湖北），往来于襄阳、江夏等地。\n干：干谒，对人有所求而请见。诸侯：此指地方长官。\n历：普遍。抵：拜谒，进见。卿相：指中央朝廷高级官员。畴曩（chóu nǎng）：往日。\n制作：指文章著述。侔（móu）：相等，齐同。东汉崔瑗《张平子碑》：“数术穷天地，制作侔造化。”\n参，参与。造化：自然的创造化育。天人：天道和人道。南朝梁钟嵘《诗品序》：“文丽日月，学究天人。”\n开张：开扩，舒展。长揖：相见时拱手高举自上而下以为礼。\n清谈：汉末魏晋以来，士人喜高谈阔论，或评议人物，或探究玄理，称为清谈。\n倚马可待：喻文思敏捷。东晋时袁宏随同桓温北征，受命作露布文（檄文、捷书之类），他倚马前而作，手不辍笔，顷刻便成，而文极佳妙。\n司命：原为神名，掌管人之寿命。此指判定文章优劣的权威。权：秤锤；衡：秤杆。此指品评人物的权威。\n惜阶前盈尺之地：意即不在堂前接见我。\n王子师：东汉王允字子师，灵帝时豫州刺史（治所在沛国谯县，今安徽亳县），征召荀爽（字慈明，汉末硕儒）、孔融（字文举，孔子之后，汉末名士）等为从事。全句原出西晋东海王司马越《与江统书》。\n山涛：字巨源，西晋名士，竹林七贤之一。为翼州（今河北高邑西南）刺史时，搜访贤才，甄拔隐屈。侍中、尚书：中央政府官名。\n严协律：名不详。协律，协律郎，属太常寺，掌校正律吕。秘书郎：属秘书省，掌管中央政府藏书。崔宗之：李白好友，开元中入仕，曾为起居郎、尚书礼部员外郎、礼部郎中、右司郎中等职，与孟浩然、杜甫亦曾有交往。房习祖：不详。黎昕：曾为拾遗官，与王维有交往。许莹：不详。\n抚躬：犹言抚膺、抚髀，表示慨叹。抚，拍。\n推赤心于诸贤腹中：《后汉书·光武本纪》：“萧王（刘秀）推赤心置人腹中。”\n国士：国中杰出的人。\n傥：同“倘”。\n且：提起连词。\n谟猷（yóu）：谋画，谋略。\n卷轴：古代帛书或纸书以轴卷束。\n尘秽视听：请对方观看自己作品的谦语。\n雕虫小技：西汉扬雄称作赋为“童子雕虫篆刻”，“壮夫不为”（见《法言·吾子》）。虫书、刻符为当时学童所习书体，纤巧难工。此处是作者自谦之词。\n刍荛（chú ráo）：割草为刍，打柴为荛，刍荛指草野之人。也是作者用以谦称自己的作品。\n闲轩：静室。\n青萍：宝剑名。结绿：美玉名。薛：薛烛，古代善相剑者，见《越绝书外传·记宝剑》。卞：卞和，古代善识玉者，见《韩非子·和氏》。\n惟：念。下流：指地位低的人。惟，一作“推”。\n奖饰：奖励称誉。', poem_appreciation = '李白《与韩荆州书》是他初见韩时的一封自荐书。文章开头借用天下谈士的话－－“生不用封万户侯，但愿一识韩荆州”，赞美韩朝宗谦恭下士，识拔人才。接着毛遂自荐，介绍自己的经历、才能和气节。文章表现了李白“虽长不满七尺，而心雄万夫”的气概和“日试万言，倚马可待”的自负，以及他不卑不亢，“平交王侯”的性格。文章写得气势雄壮，广为传诵。\n\n　　李白的《与韩荆州书》在创作上颇具个性。他在漫游荆州时，听说荆州长史韩朝宗喜欢推荐有才之士，便写了这封求荐的信。对于古人而言，尽管这样做也是正常的，但也总是有求于别人的事情。文气大体上总是以谦抑为好，就是说自己的优点，也应含蓄一点。然而李白这篇求荐书，却完全将自己放在与对方平等的地位上，毫无掩饰地讲述自己的才华。把一篇求荐文章，写得文气纵横恣肆，气概凌云。这同样反映了李白纯真无邪的诗人气质，决不因求人而有半点委琐的私意、屈懦的鄙态。这是因为他相信自己的才华足以用世，而其用世之志，则在于忠义奋发、以报君国。故求韩荐己，同样完全是出于一片公心；而想象韩如能荐己，同样是出于这一片公心。两片公心的相识，两位贤士的相与，这中间自然不必要有任何世俗的表现。这样，就将这封信写得极其光明磊落，内心无私，文风自然就能尽情地抒发。为此我们现在看到的这篇原本是世俗交际的文字，却犹如他的诗一样，充分表现出他的个性。这里面所具有的，正是“天生我才必有用”那样的自信。\n\n　　《与韩荆州书》在写作艺术方面的特点是顿挫跌宕，起伏照应。由古及今，以古人喻韩朝宗达三四次之多。渐次道来，而意在言外，发人深思。一些佳句流传至今，如“龙蟠凤逸”、“颖脱而出”、“扬眉吐气”等。典故使用也恰当得体，起到了激发韩朝宗的作用。', poem_tags = '古文观止,荐书' WHERE poem_title = '与韩荆州书' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '微风轻拂着湖水，更觉得波光浩渺，正是深秋的时候，红花叶凋，芳香淡薄。水光山色与人亲近，唉！我也说不清这无比的美好。\n莲子已经成熟，莲叶也已衰老，清晨的露水，洗涤着水中蘋花，汀上水草。眠伏沙滩的水鸟也不回头，似乎怨恨人们归去的太早。', poem_notes = '双调忆王孙：词牌名。忆王孙，原为单调三十一字，此扩充为双调。此词词牌原为“怨王孙”，有误。\n浩渺：形容湖面空阔无边。\n秋已暮：秋时已尽。\n红、香：以颜色、气味指代花。\n蘋：亦称田字草，多年生浅水草本蕨类植物。汀：水边平地。\n眠沙鸥鹭：眠伏在沙滩上的水鸟。', poem_appreciation = '词的上片写初到湖上的感受，下片写归时的心情。\n\n　　起句写湖。从语气上看，初去时真是秋高气爽，日丽晴和，那辽阔的湖面上，水波不兴，平如明镜，湖光澈能，景色触和。忽然风起，吹皱湖水，层层涟漪，荡漾开来，激起浪花。因此说“湖上风来波浩渺”。“风来，”是事物变让的起因，对游人的印象较深，所以特地拈出。\n\n　　次句写荷。“秋已暮”，就是“时维九月，序属三秋”（王勃《滕王阁序》中语），用以点明节候。这时湖中荷花已经葵谢，枝叶开始凋零，只有残存着的红花点点，不时散发出断续余香，整个湖面上呈现出一派秋日萧瑟的气象。\n\n　　但，这无损于湖上的秀丽风光，它仍然是如济人刘凤浩咏湖诗说的“四面荷花三面柳，一城山色半城湖”此刻虽因节候不同，有所变化，但湖上景象仍然一样。尽管荷花色褪，乃至零落，而群山诸峰，倒影湖中，特别是遍山红叶与湖边垂柳，交相映衬，更加妩媚。树上鸣禽，吱吱喧喳；洲诸鸥鹭，负日眠沙；一动一静，饶有情趣，在给人以快慰之感，极尽游赏之乐，真有说不尽的无穷好。\n\n　　“水光山色与人亲”是词人在凝神观照事物时所得最突出印象，“说不尽、无穷好，”是她陶醉于景色后的深刻感受。这两句语虽直率、浅近，却饶有韵味。它体现出词人游赏时怡然自得的欢悦心情和她那开朗乐观的内心世界。在这里，作者把热爱自然、歌颂自然的主观意识赋予了客观存在的景物，分明是自己爱好“水光山色，”却偏说“水光山色与人亲。”移情于物，融情于景，使无情事物有情化。虽是有我之境，却较之后来辛弃疾《贺新郎》“我见青山多妩媚，料青山见我亦如是，”更加超脱，更加优美。\n\n　　过片“莲子已成荷叶老，”是对“秋已暮”的呼应，更是“红稀香少”的具体化。但在荷花盛开，团荷复盖湖面时，丛生水上的白苹，岸边的绿草，是无由得到清露的滋润，只有到了莲熟叶残时，才能分享清露的沾溉，生机旺盛，青翠欲滴。’“清露洗”中的“洗”字，最富生活气息，它为湖上增添色彩，提供游人以赏玩之资。\n\n　　象这样佳丽胜地，幽美的风光，不只游人为它所吸引，流连忘返，连山禽水鸟也不忍离去。那沙滩上常有鸥鹭栖宿。特别是沙鸥与白鹭性颇温驯，也很机灵，来往游人很喜欢逗弄它们，与之亲近，久了它们也不怕人，仿佛彼此之间，消除了隔膜，象朋友一些般。由于它们经常栖息于水边洲渚之间，人们遂以为隐者的象征。不少诗人常有愿与鸥鹭结盟的吟咏。诗歌中盟鸥之辞，如李白“明朝拂衣去，永与白鸥盟”可能是最早的两句。后来黄庭坚也有“万里归舟弄长笛，此心吾与白鸥盟。”因之当游兴已尽，与同游者相偕归去时，看到沙滩上的鸥鹭睡在那里动也不动，头也不回，便觉得那是责怪他们过早的归去，象是不够朋友似的。\n\n　　“眠沙鸥鹭不回头，似也恨，人归早，”乃是作者把自己的人格泯化于物类中，尽量缩小自我，使之臻于“民胞物与”的思想境界，把分明是自己不愿离开沙鸥与白鹭的心意，却说沙鸥、白鹭责怪她为何匆匆归去？这便是拟人化手法的运用。\n\n　　拟人化手法，在古典诗歌中经常运用。盛唐诗人王维《积雨栩川庄作》诗：“野老与人争席罢，海鸥何为更相疑？”五代西蜀人欧阳炯《南乡子》词：“孔雀自怜金翠尾，临水，认得行人惊不起。”北宋初年欧阳修《采桑子》词：“鸥鹭闲眠，应惯寻常听管弦”和稍后的秦观《还自广陵》诗：“天寒水鸟自相依，十百为群戏落晖，过尽行人都不起，忽闻冰响一齐飞。”都是运用这手法，写出动人的场景。但他们的诗或词，虽各具特定的意义，收到应有如艺术效果，终不及李词亲切感人，所寓的哲学意义和文学趣味，更为深长，更为丰满。\n\n　　这真是一幅绚烂夺目的晚秋景色图。它具有生动、鲜明、清新、自然的特色，洋溢着浓郁的生活气息和诗情画意，语言颇有行云流水之势，能给人以美的享受和回味的余地。从前苏轼评王维诗画说：“味摩诘之诗，诗中有画，观摩诘之画，画中有诗。”李清照也擅长绘画，但画多不传，画中有词与否，难以断定，而李清照词中有画，是可以这样说的，且不仅《怨王孙》一词而已。\n\n　　值得一提的，是这词有些句子，颇与南唐中主李璟《浣溪沙》上片“苗萏香销翠叶残，西风愁起绿波间，还与韶光共憔悴，不堪看！”相类似处，然而词的情调却迥然不同：李璟把香销叶残的画面，用西风愁起、韶光憔悴来衬说，突出那种不堪目睹的形象，“大有众芳芜秽，美人迟荟之感。”（王国维《人间词话》）情调是低沉的、悲观的、消极的。而李词从红稀香少、莲熟叶老中生发出水光山色、苹花汀草、鸥鹭眠沙来。抽出那篇著名的《论词》中批评江南李氏“尚文雅，故有‘小楼吹彻玉笙寒’之词，语虽奇甚，所谓亡国之音哀以思者也，”不是没有道理的。', poem_tags = '宋词精选,赞颂,秋天,写景' WHERE poem_title = '怨王孙·湖上风来波浩渺' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '有情风从万里之外卷潮扑来，无情时又送潮返回。请问在钱塘江上或西兴渡口，我俩共赏过几次夕阳斜晖？用不着仔细思量古今的变迁，一俯一仰的工夫，早已物是人非。谁像我东坡苏老。白首之年，淡忘了仕进的机会。\n记住西湖的西岸，春日最美的山隈，就是那空明的翠微，如烟的云霏。算起来诗人中相处得宜。如我与您这样的友情，确实稀微，弥足珍贵。约定日后，像东晋宰相谢安那样，沿着直通大海的长江航道，向东引退、回归。别让这一高雅志向与未来事实彼此违背。不应在西州路上回首恸哭，为了我而沾湿衣襟，洒落泪水。', poem_notes = '八声甘州：词牌名。源于唐大曲，又名《甘州》、《潇潇雨》。\n参寥子：即僧人道潜，字参寥，浙江于潜人。精通佛典，工诗，苏轼与之交厚。元祐六年（1091年），苏轼应召赴京后，寄赠他这首词。\n钱塘江：浙江最大河流，注入杭州湾，江口呈喇叭状，以潮水壮观著名。\n西兴：即西陵，在钱塘江南，今杭州市对岸，萧山县治之西。\n几度斜晖：意谓度过多少个伴随着斜阳西下的夜晚。\n俯仰昔人非：语出王羲之《兰亭集序》：“俯仰之间，已为陈迹。”\n忘机：忘却世俗的机诈之心。见《列子·黄帝》，传说海上有一个人喜欢鸥鸟，每天坐船到海上，鸥鸟便下来与他一起游玩。一天他父亲对他说，“吾闻鸥鸟皆从汝游，汝取来吾玩之”，于是他就有了捉鸟的“机心”（算计之心），从此鸥鸟再也不下来了。这里说苏轼清除机心，即心中淡泊，任其自然。李白《下终南山过斛斯山人宿置酒》：“我醉君复乐，陶然共忘机。“苏轼《和子由送春》：“芍药樱桃俱扫地，鬓丝禅榻两忘机。“\n相得：相交，相知。\n谢公雅志：《晋书·谢安传》载：谢安虽为大臣，“然东山之志始末不渝”，“造讽海之装，欲经略初定，自江道还东。雅志未就，遂遇疾笃”。雅志，很早立下的志愿。\n“西州路”三句：《晋书·谢安传》载：安在世时，对外甥羊昙很好。安死后，其外甥羊昙“辍乐弥年，行不由西州路”。某次醉酒，过西州门，回忆往事，“悲感不已”，“恸哭而去”。 西州，古建业城门名。晋宋间建业（今江苏南京）为扬州刺史治所，以治所在城西，故称西州。', poem_tags = '写水,感叹,人生,哲理,离别,友情' WHERE poem_title = '八声甘州·寄参寥子' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_tags = '古诗三百首,写景,伤怀' WHERE poem_title = '晚出新亭' AND poem_author = '阴铿';
UPDATE edu_poem SET poem_tags = '乐府,感叹,悼念' WHERE poem_title = '薤露' AND poem_author = '曹操';
UPDATE edu_poem SET poem_translation = '我的兄长的儿子马严和马敦，都喜欢讥讽议论别人的事，而且爱与侠士结交。我在前往交趾的途中，写信告诫他们：“我希望你们听说了别人的过失，像听见了父母的名字：耳朵可以听见，但嘴中不可以议论。喜欢议论别人的长处和短处，胡乱评论朝廷的法度，这些都是我深恶痛绝的。我宁可死，也不希望自己的子孙有这种行为。你们知道我非常厌恶这种行径，这是我一再强调的原因。就像女儿在出嫁前，父母一再告诫的一样，我希望你们不要忘记啊。”\n\n　　“龙伯高这个人敦厚诚实，说的话没有什么可以让人指责的。谦约节俭，又不失威严。我爱护他，敬重他，希望你们向他学习。杜季良这个人是个豪侠，很有正义感，把别人的忧愁作为自己的忧愁，把别人的快乐作为自己的快乐，无论好的人坏的人都结交。他的父亲去世时，来了很多人。我爱护他，敬重他，但不希望你们向他学习。（因为）学习龙伯高不成功，还可以成为谨慎谦虚的人。正所谓雕刻鸿鹄不成可以像一只鹜鸭。一旦你们学习杜季良不成功，那就成了纨绔子弟。正所谓“画虎不像反像狗了”。到现今杜季良还不知晓，郡里的将领们到任就咬牙切齿地恨他，州郡内的百姓对他的意见很大。我时常替他寒心，这就是我不希望子孙向他学习的原因。”', poem_notes = '讥议：讥讽，谈论。\n通轻侠客：通，交往；轻，轻佻；与侠士轻佻之人交好。\n交趾：汉郡，在今越南北部。\n汝曹：你等，尔辈。\n是非：评论、褒贬。\n正法：正当的法制。\n大恶：深恶痛绝。\n施衿结缡，申父母之戒：衿：佩带。缡：佩巾。古时礼俗，女子出嫁，母亲把佩巾、带子结在女儿身上，为其整衣。父戒女曰：“戒之敬之，夙夜无违命。”母戒女曰：“戒之敬之，夙夜无违宫事。”\n龙伯高敦厚周慎：龙伯高这个人敦厚诚实；龙伯高：东汉名士，史书上记载其““在郡四年，甚有治效”，“孝悌于家，忠贞于国，公明莅临，威廉赫赫”。周慎：周密，谨慎。\n口无择言：说出来的话没有败坏的，意为所言皆善。 择：通“殬(dù)”，败坏。\n杜季良：杜季良，东汉时期人，官至越骑司马。\n清浊无所失：意为诸事处置得宜。\n数郡毕至：很多郡的客人全都赶来了。\n谨敕：谨敕：谨慎。\n鹄：天鹅。鹜：野鸭子。此句比喻虽仿效不及，尚不失其大概。\n画虎不成反类狗：比喻弄巧成拙。\n下车：指官员初到任。切齿：表示痛恨。\n以为言：把这作为话柄。', poem_appreciation = '马援的侄子马严、马敦平时喜讥评时政、结交侠客，很令他担忧，虽远在交趾军中，还是写了这封情真意切的信。文章出语恳切，言词之中饱含长辈对晚辈的深情关怀和殷殷期待，所以能产生这样的效果，原因有三。\n\n　　其一、以“汝曹”称子侄，在文中反复出现，使子侄们在阅读时倍感亲切。不远千里致书教谕，也能收到耳提面命的效果。同一称谓反复出现，固然可使被称者自感受到重视，而更重要的是，作者选用的这一称谓也传达出丰富的信息。古人名、字并行，各有其用。一般长辈称晚辈用名，同辈相称则用字，如果“尔”“汝”相称，往往是不礼貌的，但在特定场合下却又能用以表示亲近，如韩愈《听颖师弹琴》“昵昵儿女语，恩怨相尔汝”句。作者在信中不依常规称呼子侄，却以“汝曹”相称，这就显得随和、亲切，拉近了长辈和晚辈之间的距离。被称的晚辈则可以从中体会到长辈的真情关怀。\n\n　　其二、苦口婆心，现身说法，用自己的生活经验和晚辈沟通，而不是空讲大道理。如首段说“好议论人长短，妄是非正法，此吾所大恶也，宁死不愿闻子孙有此行也。”只说自己如何，但是态度明确，感情浓烈，自然可以感染晚辈，又何必命令式地不许这不许那呢？至于“施衿结缡”句，更是反复叮咛，语重心长，使人感动不已。次段对当世贤良的作为得失加以对比评析，都是自己观察社会人生得来的经验之谈。其“刻鹄不成尚类鹜”、“画虎不成反类狗”的比喻，警拔有力，发人深省，是传之千古的警句。而诸如“愿汝曹效之”、“不愿汝曹效也”的话，虽然只是表示希望，但是字里行间满盈着真挚的关爱，比之“汝曹当效之”、“汝曹勿效也”这样板着面孔的口吻真不知要强过多少倍了！\n\n　　其三、文中大量而恰当地使用句末语气词，起到了表达意义以简驭繁，只着一字而含义丰富；表达感情以无胜有，不着情语而情尤真、意尤切的突出效果。文中用“也”表达自己的肯定和期望，态度坚绝；用“矣”、“耳”表达自己的爱憎倾向，情深意长；用“者也”，则表达出对评说对象有所保留或不以为然。这些合在一起，不仅读来语气抑扬，更能使人由此领会充盈在文字背后的教诲、期望、关怀和爱护。', poem_tags = '古文观止,劝诫,书信' WHERE poem_title = '诫兄子严敦书' AND poem_author = '马援';
UPDATE edu_poem SET poem_tags = '散曲,抒情,生活' WHERE poem_title = '一枝花·不伏老' AND poem_author = '关汉卿';
UPDATE edu_poem SET poem_translation = '那西北方有一座高楼矗立眼前,堂皇高耸恰似与浮云齐高。\n高楼镂著花纹的木条,交错成绮文的窗格,四周是高翘的阁檐，阶梯有层叠三重。\n楼上飘下了弦歌之声，这声音是多么的让人悲伤啊！谁能弹此曲,是那悲夫为齐君战死,悲恸而“抗声长哭“竟使杞之都城为之倾颓的女子.。\n商声清切而悲伤,随风飘发多凄凉!这悲弦奏到“中曲“,便渐渐舒徐迟荡回旋.\n那琴韵和“叹“息声中,抚琴堕泪的佳人慷慨哀痛的声息不已。\n不叹惜铮铮琴声倾诉声里的痛苦,更悲痛的是对那知音人儿的深情呼唤。\n愿我们化作心心相印的鸿鹄,从此结伴高飞,去遨游那无限广阔的蓝天白云里!', poem_notes = '疏：镂刻。绮：有花纹的丝织物。这句是说刻镂交错成雕花格子的窗。　\n阿（e）阁：四面有曲檐的楼阁。这句是说阿阁建在有三层阶梯的高台上。　\n无乃：是“莫非”、“大概”的意思。杞梁妻：杞梁妻的故事，最早见于《左传·襄公二十三年》，后来许多书都有记载。据说齐国大夫杞梁，出征莒国，战死在莒国城下。其妻临尸痛哭，一连哭了十个日夜，连城也被她哭塌了。《琴曲》有《杞梁妻叹》，《琴操》说是杞梁妻作，《古今注》说是杞梁妻妹朝日所作。这两句是说，楼上谁在弹唱如此凄惋的歌曲呢？莫非是象杞梁妻那样的人吗？　\n清商：乐曲名，声情悲怨。清商曲音清越，宜于表现哀怨的情绪。　\n中曲：乐曲的中段。徘徊：指乐曲旋律回环往复。　\n慷慨：感慨、悲叹的意思。《说文》：“壮士不得志于心也。”　\n惜：痛。　\n知音：识曲的人，借指知心的人。相传俞伯牙善鼓琴，钟子期善听琴，子期死后，伯牙再不弹琴，因为再没有知音的人。这两句是说，我难过的不只是歌者心有痛苦，而是她内心的痛苦没有人理解。\n⑨鸿鹄：据朱骏声《说文通训定声》说：“凡鸿鹄连文者即鹄。”鹄，就是“天鹅”。一作“鸣鹤”。此二句以双鸿鹄比喻情志相通的人，意谓愿与歌者同心，如双鹄高飞，一起追求美好的理想。　\n高飞：远飞。这二句是说愿我们像一双鸿鹄，展翅高飞，自由翱翔。', poem_appreciation = '慨叹着“何不策高足，先据要路津”的汉末文人，面对的却是一个君门深远、宦官挡道的苦闷时代。是骐骥，总得有识马的伯乐才行；善琴奏，少不了钟子期这样的知音。壮志万丈而报国无门，——在茫茫人和事，没有什么比这更教人嗟伤的了。\n\n　　此诗的作者，就是这样一位彷徨中路的失意人。这失意当然是政治上的，但在比比倾诉之时，却幻化成了“高楼”听曲的凄切一幕。\n\n　　从那西北方向，隐隐传来铮铮的弦歌之音。诗人寻声而去，蓦然抬头，便已见有一座“高楼”矗立眼前。这高楼是那样堂皇，而且在恍惚之间又很眼熟：“交疏结绮窗，阿阁三重阶”——刻镂着花纹的木条，交错成绮文的窗格；四周是高翘的阁檐，阶梯有层叠三重，正是诗人所见过的帝宫气象。但帝宫又不似这般孤清，而且也比不上它的高峻：那巍峨的楼影，分明耸入了飘忽的“浮云”之中。\n\n　　欣赏指要\n\n　　这是一首写知音难觅的诗。从诗意看，诗中主人公是一位在生活中因失意而彷徨的人。凄凉的弦歌声从重门紧锁的高楼上隐隐传来，其声调的悲凉深深地感染了楼下听歌的人。从那清婉悠扬、感慨哀伤而又一唱三叹的歌声中，诗人清晰地感受到了歌者经历的惨痛和被压抑的内心痛苦。这令人不禁要推想，歌者是谁？莫非是杞梁妻那样的忧伤女子？可是，最值得忧伤的不是歌者的哀痛，而是没有人能够理解她个中的伤感，知音难觅可能才是她感伤叹息的真正原因。诗人借高楼上的歌者之悲抒写的是自己的人生感受，“但伤知音稀”是一种具有广泛社会性的苦闷、悲伤和期待。\n\n　　作者将所抒之情融于幻景之中。对于声音的描写细腻生动，歌者与听者遥相呼应，把失意之人的徘徊、悲切、希冀全面地展现出来了。阅读时，要细细体会诗中那种若隐若现、缥缈空灵的意境。\n\n　　诗中的“托”\n\n　　人们常把这四句所叙视为实境，甚至还有指实其为“高阳王雍之楼”的（杨炫之《洛阳伽蓝记》）。其实是误解。明人陆时雍指出，《古诗十九首》在艺术表现上的一大特点，就是“托”：“情动于中，郁勃莫已，而势又不能自达，故托为一意、托为一物、托为一境以出之”（《古诗镜》）。此诗即为诗人假托之“境”，“高楼”云云，全从虚念中托生，故突兀而起、孤清不群，而且“浮云”缥缈，呈现出一种奇幻的景象。\n\n　　那“弦歌”之声就从此楼高处飘下。诗中没有点明时间，从情理说大约正什夜晚。在万籁俱寂中，听那“音响一何悲”的琴曲，恐怕更多一重哀情笼盖而下的感觉吧。这感觉在诗人心中造成一片迷茫：“谁能为此曲？无乃杞梁妻！”“杞梁”即杞梁殖。传说他为齐君战死，妻子悲恸于“上则无父，中则无夫，下则无子，人生之苦至矣”，乃“抗声长哭”竟使杞之都城为之倾颓（崔豹《古今注》）。而今，诗人所听到的高楼琴曲，似乎正有杞梁妻那哭颓杞都之悲，故以之为喻。全诗至此，方着一“悲”字，顿使高楼听曲的虚境，蒙上了一片凄凉的氛围。\n\n　　诗中的“歌者”是谁\n\n　　那哀哀弦歌于高处的“歌者”是谁，诗人既在楼下，当然无从得见；对于读者来说，便始终是一个未揭之谜。不过有一点是清楚的：诗中将其比为“杞梁妻”，自必是一位女子。这女子大约全不知晓，此刻楼下正有一位寻声而来、伫听已久的诗人在。她只是铮铮地弹着，让不尽的悲哀在琴声倾泻：“清商随风发，中曲正徘徊。”“商”声清切而“多伤”，当其随风飘发之际，听去该是无限凄凉。这悲弦奏到“中曲”，便渐渐舒徐迟回，大约正如白居易《琵琶行》所描述的，已到了“幽咽泉流水下滩”、“冰泉冷涩弦凝绝”之境。接着是铿然“一弹”，琴歌顿歇，只听到声声叹息，从高高的楼窗传出。“一弹再三叹，慷慨有余哀”：在这阵阵的叹息声中，正有几多压抑难伸的慷慨之情，追着消散而逝的琴韵回旋！这四句着力描摹琴声，全从听者耳中写出。但“摹写声音，正摹写其人也”。', poem_tags = '古诗十九首,咏物,抒怀,失意' WHERE poem_title = '西北有高楼' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '鸿雁翩翩空中飞，扇动双翅嗖嗖响。那人离家出远门，野外奔波苦尽尝。可怜都是穷苦人，鳏寡孤独心悲伤。\n鸿雁翩翩空中飞，聚在沼泽的中央。那人筑墙服苦役，先后筑起百堵墙。虽然辛苦又劳累，不知安身在何方。\n鸿雁翩翩空中飞，阵阵哀鸣声嗷嗷。惟有那些明白人，知我作歌唱辛劳。惟有那些糊涂虫，说我闲暇发牢骚。', poem_notes = '鸿雁：水鸟名，即大雁；或谓大者叫鸿，小者叫雁。\n于：语助词。\n肃肃：鸟飞时扇动翅膀的声音。\n之子：那人，指服劳役的人。征：远行。\n劬（qú）劳：勤劳辛苦。\n爰（yuán）：语助词。矜（jīn）人：穷苦的人。\n鳏（guān）：老而无妻者。寡：老而无夫者。\n集：停。中泽：即泽中。\n于垣：筑墙。\n堵：长、高各一丈的墙叫一堵。作：筑起。\n究：终。宅：居住。\n嗷（áo）嗷：鸿雁的哀鸣声。\n哲人：通情达理的人。\n宣骄：骄奢。', poem_appreciation = '这是一首“饥者歌其食，劳者歌其事”的现实主义诗作，具有国风民歌的特点。全诗三章，每章均以“鸿雁”起兴，并借以自喻。首章写流民被迫到野外去服劳役，连鳏寡之人也不能幸免，反映了受害者的广泛，揭露了统治者的残酷无情。振翅高飞的大雁勾起了流民颠沛流离无处安身的感叹，感叹中包含着对繁重徭役的深深哀怨。次章承接上章，具体描写流民服劳役筑墙的情景。鸿雁聚集泽中，象征着流民在工地上集体劳作，协同筑起很多堵高墙，然而自己却无安身之地。“虽则劬劳，其究安宅”的发问，道出了流民心中的不平和愤慨。末章写流民悲哀作歌，诉说悲惨的命运，反而遭到那些贵族富人的嘲弄和讥笑。大雁一声声的哀叫引起了流民凄苦的共鸣，他们就情不自禁地唱出了这首歌，表达了心中的怨愤。\n\n　　这首诗感情深沉，语言质朴，韵调谐畅，虽是一首抒情诗，但又兼有叙事、议论的成份。然而此诗最大的特点是比兴手法的运用，每章开头都以鸿雁起兴，不仅可以引起丰富的联想，而且兼有比义。鸿雁是一种候鸟，秋来南去，春来北迁，这与流民被迫在野外服劳役，四方奔走，居无定处的境况十分相似。鸿雁长途旅行中的鸣叫，声音凄厉，听起来十分悲苦，使人触景生情，平添愁绪。所以以之起兴，是再贴切不过的了。全诗三章根据所述内容的不同，或是兴而比，或是比而兴。一章以鸿雁振羽高飞兴流民远行的劬劳，二章以鸿雁集于泽中，兴流民聚集一处筑墙。这两章都是兴中有比，具有象征意味。第三章以鸿雁哀鸣自比而作此歌，是比中含兴。比兴意蕴的交融渗透，增强了诗歌的形象性和艺术表现力。由于此诗贴切的喻意，以后“哀鸿”“鸿雁”即成了苦难流民的代名词。\n\n　　另外，此诗每章所写的具体内容虽各不相同，但却有内在的逻辑联系。首章写出行野外，次章写工地筑墙，末章表述哀怨，内容逐层展开，主题得到了升华。再加上“鸿雁”“劬劳”等词在诗中反覆出现，形成了重章叠唱的特点，有一唱三叹的韵味。', poem_tags = '诗经,写鸟,抒情' WHERE poem_title = '鸿雁' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '山谷来风迅又猛，阴云密布大雨倾。夫妻共勉结同心，不该动怒不相容。采摘萝卜和蔓青，难道要叶不要根？往日良言休抛弃：到死与你不离分。\n迈步出门慢腾腾，脚儿移动心不忍。不求送远求送近，哪知仅送到房门。谁说苦菜味最苦，在我看来甜如荠。你们新婚多快乐，亲兄亲妹不能比。\n渭水入泾泾水浑，泾水虽浑河底清。你们新婚多快乐，不知怜惜我心痛。不要到我鱼坝来，不要再把鱼篓开。既然现在不容我，以后事儿谁来睬。\n好比过河河水深，过河就用筏和船。又如河水清且浅，我就游泳到对岸。家中有这没有那，为你尽心来备办。左邻右舍有灾难，奔走救助不迟延。\n你不爱我到也罢，不该把我当仇家。我的好心你不睬，就像货物没人买。从前害怕家贫穷，患难与共苦经营。如今家境有好转，嫌你厌我如毒虫。\n备好干菜和腌菜，贮存起来好过冬。你们新婚多快乐，拿我积蓄来挡穷。粗声恶气欺负我，粗活重活我担承。当初情意全不念，往日恩爱一场空。', poem_notes = '邶（bèi）：中国周代诸侯国名，地在今河南省汤阴县东南。\n谷风：东风，生长之风。一说来自大谷的风，为盛怒之风。\n习习：和舒貌。一说逢连续不断貌’。\n以阴以雨：为阴为雨，以滋润百物，以喻夫妇应该和美。一说没有晴和之意，喻其夫暴怒不止。\n黾（mǐn）勉：勤勉，努力。\n葑（fēng）：蔓菁也。叶、根可食。菲：萝卜之类。\n无以下体：意指要叶不要根，比喻恋新人而弃旧人。以，用。下体，指根。\n德音：指丈夫曾对她说过的好话。\n迟迟：迟缓，徐行貌。\n中心：心中。有违：行动和心意相违背。\n伊：是。迩：近。\n薄：语助词。畿（jī）：指门槛。\n荼（tú）：苦菜。\n荠：荠菜，一说甜菜。\n宴：快乐。昏：即“婚”。\n泾、渭：河名。\n湜（shí）湜：水清见底。沚（zhǐ）：水中小洲。一说底。\n屑：顾惜，介意。一说洁。\n逝：往，去。梁：捕鱼水坝。\n发：“拨”的假借字，搞乱。一说打开。笱（gǒu）：捕鱼的竹篓。\n躬：自身。阅：容纳。\n遑：暇，来不及。恤（xù）：忧，顾及。后：指走后的事。\n方：筏子，此处作动词。\n亡（wú）：同“无”。\n民：人。这里指邻人。\n匍（pú）匐（fú）：手足伏地而行，此处指尽力。\n能：乃。慉（xù）：好，爱惜。\n雠（chóu）：同“仇”，仇人。\n贾（gǔ）：卖。用：指货物。不售：卖不出。\n育：长。育恐：生于恐惧。鞫（jū）：穷。育鞫：生于困穷。\n颠覆：艰难，患难。\n于毒：如毒虫。\n旨蓄：蓄以过冬的美味干菜和腌菜。旨，甘美。蓄，聚集。\n御：抵挡。\n穷：窘困。\n有洸（guāng）有溃（kuì）：即“洸洸溃溃”，水流湍急的样子，此处借喻人动怒。\n既：尽。诒（yí）：遗，留给。肄（yì）：劳苦的工作。\n伊：句首语气词。一说维。余：我。来：语助词。一说是。塈（jì）：爱。', poem_appreciation = '作为一个社会问题，丈夫因境遇变化或用情不专而遗弃结发之妻，在《诗经》这部汉族文学史上最早的诗歌总集中已多有反映，《卫风·氓》是一篇，《邶风·谷风》又是一篇。同样是用弃妇的口吻陈述被弃的痛苦，与《卫风·氓》相比，《邶风·谷风》中的女子在性格上不如前者决绝果断，因此在回忆往事和述说情怀时怨而不怒，并没有对负心汉进行直接的谴责，然而在艺术风格上，则更能体现被孔子称道的温柔敦厚的诗教传统。\n\n　　从全诗的叙说来看，这位女子的丈夫原来也是贫穷的农民，只是由于婚后两人的共同努力，尤其是年轻妻子的辛劳操持，才使日子慢慢好过了起来。但是这种生活状况的改善，反倒成了丈夫遗弃她的原因。这个负心汉不但不顾念患难中的糟糠之妻，相反却喜新厌旧，把她当作仇人，有意寻隙找岔，动辄拳脚相加，最后终于在迎亲再婚之日，将她赶出了家门。诗中的弃妇就是在这种情形下，如泣如诉地倾吐了心中的满腔冤屈。\n\n　　这首诗在抒情方面最可注意的有以下几点：首先是选取了最能令人心碎的时刻，使用对比的手法，凸现了丈夫的无情和自己被弃的凄凉。这个时刻就是新人进门和旧人离家，对于一个用情专一、为美好生活献出了一切的女子来说，没有比这一刻更让人哀怨欲绝的了。诗由此切入，非常巧妙地抓住了反映这一出人生悲剧的最佳契机，从而为整首诗的抒情展开提供了基础。而一方面“宴尔新昏，如兄如弟”的热闹和亲密，另一方面“不远伊迩，薄送我畿”的绝情和冷淡，形成了一种高度鲜明的对比，更突出了被弃之人的无比愁苦，那种典型的哀怨气氛被渲染得十分浓烈。\n\n　　其次是借用生动的比喻言事表情，具有浓郁的生活气息。全诗共分六章，每章都有含蓄不尽的妙喻。如第一章入手便以大风和阴雨，来表现丈夫的经常无故发怒；以采来蔓菁萝卜的根茎被弃，来暗示他丢了根本，视宝为废。这主要用于言事。第二章则转用食荼如荠、以苦为甜，来反衬人物在见了丈夫新婚时内心的苦涩程度，远在荼菜的苦味之上。这又是主要用于表情。另如第三章的“泾以渭浊，湜湜其沚”，是用泾水因渭水流入表面变浊、其底仍清，来比喻自己尽管被丈夫指责却依然不改初衷的清白；第四章以河深舟渡、水浅泳渡，喻写以往生活不论有何困难，都能想方设法予以解决；第五章用“贾用不售”比丈夫的嫌弃、“比予于毒”喻对己的憎恶；第六章又把自己往日的辛劳比作御冬的“旨蓄”，将丈夫的虐待喻为湍急咆哮的水流。这些比喻取喻浅近，无不切合被喻情事的特征，大大增强了作品的艺术性和表现力。\n\n　　最后，作品的一唱三叹、反复吟诵，也是表现弃妇烦乱心绪和一片痴情的一大特色。从首章的“黾勉同心，不宜有怒”、“德音莫违，及尔同死”，到二章的“行道迟迟，中心有违”，从三章的“毋逝我粱，毋发我笱”，到四、五章的前后对比，再到六章的“不念昔者，伊余来塈”，在反覆的述写和表白中，淋漓尽致地展示了弃妇沉溺于往事旧情而无法自拔的复杂心理。顺着这一感情脉络的延伸展开，循环往复，人们更能接近和触摸这个古代女子的善良和多情的心，更能感受到被弃带给她的精神创痛。至于作品在二、三、六章中一而再、再而三地出现“宴尔新昏”这样的句子，又在断续错杂的回忆和抒情中，突出和强调了丈夫背信弃义对她产生的强烈刺激，她无法忍受眼前出现的这一现实，更不能以平常之心来接受这一现实，所以反复咏之，以示铭心刻骨，难以忽忘。\n\n　　由此可见，这首诗在抒写弃妇哀怨方面是很有特色的。它的出现，表明古代妇女在爱情和婚姻生活中，很早就处在弱者的地位，充当着以男子为中心的社会的牺牲品，她们的命运是值得同情的。尽管作品没有直接对负情男子作明确的谴责，但最初的信誓旦旦和最终的弃如脱靴，仍为此作了有力的点示，具有深刻的警世作用。', poem_tags = '诗经,闺怨' WHERE poem_title = '国风·邶风·谷风' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '听那隆隆的雷声，在南山的阳坡震撼。怎么这时候离家出走？实在不敢有少许悠闲。勤奋有为的君子，归来吧，归来吧！\n\n听那隆隆的雷声，在南山的边上响起。怎么这时候离家出走？实在不敢有片刻休息。勤奋有为的君子．归来吧，归来吧！\n\n听那隆隆的雷声，在南山的脚下轰鸣。怎么这时候离家出走？实在不敢有一会暂停。勤奋有为的君子，归来吧，归来吧！', poem_notes = '殷：声也。\n雷：喻车声\n遑：闲暇\n殷其雷．劝以义也．召南之大夫远行从政．不遑宁处．其室家能闵其勤劳．劝以义也．\n题解：妇人盼望远役丈夫早早归来', poem_appreciation = '《毛诗序》关于此诗的主题，不仅今文学派的三家无异议，而且后来的解诗者也无大的争论。虽然所思念的对象不必如《毛诗序》之泥定为“大夫”，但从诗中所称“君子”来看，则这位行役在外者当是统治阶级中人，不可能是平民百姓。\n\n　　据毛传与郑笺，前一“斯”字指君子，后一“斯”字指此地。朱熹承袭此说，释为：“何此君子独去此而不敢少暇乎?”(《诗集传》)而严粲释云：“言殷然之雷声，在彼南山之南。何为此时速去此所乎？”(《诗缉》)从上下文看，后一种说法更为顺理成章。感叹之后，女主人公又转念为丈夫设身处地着想：只因为了公事，才不敢稍事休息。想到丈夫一心为公事奔忙，故而接下去才有“振振君子”的赞叹。毛传与郑笺均释“振振”为信厚。朱熹亦承此说。姚际恒《诗经通论》云：“盖振为振起、振兴意，亦为众盛意。”而王先谦的《诗三家义集疏》训“振振”为“振奋有为”，似更切合情理。这样“振振”一词就成了称扬其夫君勤奋有为的赞语了。女主人公作出这样的赞叹之后，却发出了“归哉归哉”的呼唤，表明女主人公虽然明白丈夫是为公事奔走，但还是希望他能早早归来。这种转折实质上表现了情与理的矛盾冲突。《诗序》称“劝以义”，就是着眼于其理的一面，以张扬其伦理教化的意义，但忽视了其情的一面，而且是此诗的主要一面，因而受到后人的质疑。姚际恒在《诗经通论》中批评了《诗序》的这一偏颇：“按诗‘归哉归哉’，是望其归之辞，绝不见有‘劝以义’之意。”崔述的《读风偶识》也称：“今玩其词意，但有思夫之情，绝不见所谓‘劝义’者何在。”然而“绝不”云云又走向了另一个极端，同样失之偏执。还是朱熹概括得好：“于是又美其德，且冀其早毕事而还归也。”(《诗集传》)近人陈子展《诗经直解》称此诗“既劝以大义，又望其生还，可谓得情理之正者也”，诚为中肯之论。\n\n　　此诗以重章复叠句的形式唱出了妻子对丈夫的思念之情，在反覆咏唱中加深了情感的表达。每章均以雷起兴，却变易雷响的地点，不仅写出了雷声飘忽不定的特点，而且还引逗出对丈夫行踪无定的漂泊生活的挂念，诚如胡承珙所云：“细绎经文三章，皆言‘在’而屡易其地，正以雷之无定在，兴君子之不遑宁居。”(《诗经后笺》)“遑”、“息”、“居”三字则层层深入地表现了忠于职守、不敢懈怠的态度。此诗的每一章虽只寥寥数语，却转折跌宕，展示了女主人公抱怨、理解、赞叹、期望等多种情感交织起伏的复杂心态，活现出一位思妇的心理轨迹，堪称妙笔。初读此诗会不得要领，或以偏概全，产生上文所述的岐见，因而姚际恒会这样批评朱熹：“夫冀其归，可也，何必美其德耶!二义难以合并，诗人语意断不如是。”殊不知诗作为心灵的自白，断不是非此即彼的逻辑推理，可以说诗人之语正当如是。此诗之妙正在于其上下不一的语意转折，在否定亦复肯定中呈现活的心灵。此外，此诗的语言简洁朴素，齐言中又有长短相错，模拟说话的声口，在一唱三叹中倾吐衷情，颇为传神。（黄宝华）', poem_tags = '诗经,写雷' WHERE poem_title = '殷其雷' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '黄金屋”指代荣华富贵的生活，“颜如玉”指代美貌的女子。\n\n　　“书中自有黄金屋，书中自有颜如玉”概括了过去许多读书人读书的目的和追求。其实列举这两者只是一种借代的说法，它们是一朝金榜题名出人头地后最具代表性的收获，这里也就代指出人头地。古代许多读书人读书的目的求的就是一个出人头地。所以人们也就常用这句话鼓励别人或子女读书。\n\n　　字里行间给我们的启示是读书考取功名是当时人生的一条绝佳出路。用现代理念去解释，读书就是接受教育，教育是社会的一个功能，让学生掌握知识学能，以投身社会，服务人群。', poem_tags = '劝勉,读书' WHERE poem_title = '劝学诗' AND poem_author = '赵恒';
UPDATE edu_poem SET poem_translation = '注释 银艾：“银”是银印。“艾”是绿色像艾草一样拴印的丝带。借指做官。 丘壑：指隐者所居的山林幽深处。 脍新鲈：指隐居生活。 三江：指吴淞江、娄江、东江，这三江都流入太湖。 挽天河：杜甫《洗兵马》中针对国家内乱唱出了“安得壮士挽天河，净洗兵甲长不用”的心声。 霄汉：即高空，暗喻朝廷。', poem_tags = '豪放,爱国,壮志' WHERE poem_title = '水调歌头·平生太湖上' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '下过雪的清晨，有清幽笳声响起，梦中所游之地，不知道是什么地方。铁骑无声，望过去如水流淌一般绵延不绝。我猜想这样的关河，应该在雁门关西边，青海的边际。\n在寒灯照射下睡醒时，更漏声已经滴断了，月光斜斜透过窗纸。我自许可在万里之外的战场封侯，但有谁能知道呢？我鬓发虽残败灰白，可我（在战场杀敌立功报效祖国的）心却并未死去！', poem_notes = '记梦：记录梦境；师伯浑，词人的朋友。\n雪晓清笳乱起：大雪飘飞的清早笳声乱起。笳，古代军队中用的一种管乐器。\n想关河：想必这样的边关河防。\n雁门：雁门关，在今山西省代县西北。\n青海际：青海湖边。青海湖在今青海省。\n睡觉：睡醒。\n漏声断：漏声尽。指夜深。漏，古代计时器。\n自许句：自己许下诺言在万里疆场为国杀敌，建功立业。\n残：此指头发脱落稀疏，意即年老。', poem_tags = '宋词三百首,豪放,爱国,壮志' WHERE poem_title = '夜游宫·记梦寄师伯浑' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '小睡之后，就因薄被而被冻醒，突然觉有种难以名状的离别滋味涌上心头。辗转反侧地细数着寒夜里那敲更声次，起来了又重新睡下，反复折腾终究不能入睡，一夜如同一年那样漫长。\n也曾打算勒马再返回，无奈，为了生计功名已动身上路，又怎么能就这样无功而回呢？千万次的思念，总是想尽多种方法加以开导解释，最后只能就这样寂寞无聊地不了了之。我将一生一世地把你系在我心上，却辜负了你那流不尽的伤心泪！', poem_notes = '忆帝京：词牌名，柳永制曲，盖因忆在汴京之妻而命名，《乐章集》注“南吕调”。双调七十二字，上片六句四仄韵，下片七句四仄韵。\n薄衾（qīn）：薄薄的被子。小枕：稍稍就枕。\n乍觉：突然觉得。\n展转：同“辗转”，翻来覆去。《楚辞·刘向》：“忧心展转，愁怫郁兮。”数寒更（gēng）：因睡不着而数着寒夜的更点。古时自黄昏至拂晓，将一夜分为甲、乙、丙、丁、戊五个时段，谓之“五更”，又称“五鼓”。每更又分为五点，更则击鼓，点则击锣，用以报时。\n拟待：打算。向子諲《梅花引·戏代李师明作》：“花阴边，柳阴边，几回拟待偷怜不成怜。”征辔（pèi）：远行之马的缰绳，代指远行的马。潘问奇《自磁州趋邯郸途中即事》：“旁午停征辔，炊烟得几家？”\n争奈：怎奈。张先《百媚娘·珠阙五云仙子》：“乐事也知存后会，争奈眼前心里？”\n行计：出行的打算。\n只恁（nèn）：只是这样。辛弃疾 《卜算子·饮酒不写书》：“万札千书只恁休，且进杯中物。”厌厌：同“恹恹”，精神不振的样子。', poem_tags = '宋词精选,离别,相思,思归' WHERE poem_title = '忆帝京·薄衾小枕凉天气' AND poem_author = '柳永';
UPDATE edu_poem SET poem_translation = '水不停地流走，花儿不断地凋零，这是多么无情啊。正是这无情的时节，我送着最后一缕春风吹过了楚城。\n在睡梦中梦见了万里之外的家乡，醒来时正值夜里三更时分，杜鹃在树枝上凄厉地啼叫。\n家乡的来信动辄几年都收不到，春天万物萌生，镜中的我却已是满头白发了。\n我现在是因为自己抱负未展而不愿归去，我要归去时自然就归去了，故乡五湖的风景是没有人来和我争抢的。', poem_notes = '《全唐诗》此诗题下注：一本下有“旅怀”二字。\n楚城：指湖北、湖南一带的城市，泛指旅途经过的楚地，作者另有《湘中秋怀迂客》《夷陵夜泊》等诗。首二句感时，慨叹春光易逝。\n胡蝶：即蝴蝶。胡蝶梦：意即往事如梦。语出《庄子·内篇·齐物论》：“昔者庄周梦为胡蝶，栩栩然胡蝶也。”\n子规：一作“杜鹃”，其鸣声凄切。上句写思家，下句写春夕。子规（即杜鹃）夜啼切“春夕”，与“家万里”联系。\n动：动辄、每每之意。经：一作“多”。绝：一作“别”。\n华发：白发。唯：一作“移”。满镜：一作“两鬓”。\n五湖：春秋时，范蠡佐越王勾践成就霸业之后，辞宫，乘扁舟泛五湖而去。这两句说：我现在还没有归去，我要归去就可以归去，故乡的五湖风景是没有人来和我争夺的。言外之意：既然如此为什么还留滞他乡呢？有自嘲意。', poem_appreciation = '此诗载于《全唐诗》卷六百七十九。诗一起笔，就渲染出一片暮春景色：春水远流，春花凋谢。流水落花春去也——诗人深深感叹春光易逝，岁月无情。诗第二句“送尽东风过楚城”更加感伤。诗人把春光（“东风”）拟人化了，依依为她送别。这里，不是春风他送我回故乡，而是他在异乡送春归。这一“送”字表达了诗人凄楚的情怀。诗人面对着落红满地、柳絮漫天的残春景物，不可能不更加思念故乡。由送春而牵动的思乡之情，笼罩全篇。\n\n　　以下句句写的是思乡衷曲。“蝴蝶梦中家万里，子规枝上月三更。”这一联进入正题，写“春夕”，写得极为精粹，是传诵的名句。诗人运用了新奇的造语，对仗工整，韵律和谐，创造出一种曲折幽深的情境。上句巧写梦境。由于游子日有所思，夜间便结想成梦，梦见自己回到了万里之外的家园。然而，这只不过象庄周梦见自己变成蝴蝶，翩翩飞舞于花间，虽然有趣，毕竟虚幻而短暂，醒来之后，蝴蝶还是蝴蝶，庄周还是庄周。游子从“蝴蝶梦”中获得片刻的回乡之乐，但梦醒以后，发现自己依旧孤眠异乡，家园依旧远隔万里，岂不更加空虚、失望，更加触动思乡之情。何况此时又正当“子规枝上月三更”——夜深人静，月光如水；子规鸟（即杜鹃）在月下哀哀啼唤：“子归！子归！……”听着子规啼，想着蝴蝶梦，游子的心，该是何等的痛苦哀伤，真如李白诗句中所谓道“一叫一回肠一断！”这里，十四个字写出了三层意思：由思乡而入梦，一层；梦醒而更思乡，二层；子规啼唤，愁上加愁，三层。这三层，一层比一层深，而且互相烘托、映衬，如蝴蝶梦与家万里，一虚一实；蝴蝶梦与子规啼，一乐一悲；子规啼与三更月，一声一色，构成一片清冷、凄凉、愁惨的气氛，令人触目伤怀。\n\n　　上一联以景传情，下一联则直接诉说思乡之苦。“故园书动经年绝，华发春唯满镜生。”诗人长期不能回家，连家信也动不动长年断绝，音讯杳然，他不可能不望眼欲穿，忧心如焚。这句中的一个“动”字，把诗人那种由期待而沮丧、而嗟怨的复杂的心理，逼真地传达出来了。“书动经年绝”暗示当时社会动乱不安。诗人愁家忧国到“华发春唯满镜生”的程度。春天万物萌生，欣欣向荣，而诗人却唯独生出了白发满头。一个“唯”字，更加突出了他的内心愁苦之深。如此深愁，难以解脱。\n\n　　诗的最后两句更耐人寻味。“自是不归归便得，五湖烟景有谁争？”这两句是倒装。从暗用五湖典故看，这里的“归”字，还含有归隐田园之意。诗人仆仆风尘，仕途坎坷，“自是不归归便得”一语，是无可奈何的伤心话，深刻地反映出诗人在政治上走投无路、欲干不能而又欲罢难休的苦闷、彷徨的心理。\n\n　　这首诗情切境深，风格沉郁。诗的前四句通过对暮春之夕特定情景的描绘，缘情写景，因景抒情，景物之间互相映衬、烘托，构成一片凄凉愁惨的气氛。诗中没有直接点出思乡，而一片思乡之情荡漾纸上。后四句直抒心曲，感情真切，凄婉动人。尾联自慰自嘲，墨中藏意，饶有情味。', poem_tags = '春天,写景,思乡' WHERE poem_title = '春夕' AND poem_author = '崔涂';
UPDATE edu_poem SET poem_translation = '长时间来一直处于混沌醉梦之中，无端地耗费着人生这点有限的时光。有一天，忽然发现春天即将过去了，于是便强打精神登上南山去欣赏春色。\n在游览寺院的时候，无意中与一位高僧闲聊了很久，难得在这纷扰的世事中暂且得到片刻的清闲。', poem_notes = '强：勉强。\n因：由于。\n过：游览，拜访。\n竹院：即寺院。\n此处“偷”在有的诗歌版本中作“又”字\n浮生：语出《庄子》“其生若浮”。意为人生漂浮无定，如无根之浮萍，不受自身之力所控，故谓之“浮生”。', poem_appreciation = '“终日昏昏醉梦间”，这一句是诗人对自己遭遇流放时的内在情绪与外在情态的真实描述。诗人从“抑”起笔，首先抒写其消极浑噩的内心情态。在“醉梦”前面修饰以“终日昏昏”，可见诗人面对流放遭遇所表现出来的极度消沉和一蹶不振。从写法上这是采取了先抑后扬的写法，为下文的“扬”做了一个很好的蓄势和铺垫。\n\n　　“忽闻春尽强登山”，这句是写诗人在百无聊赖之际，浑浑噩噩之中，忽然发现明媚的春光已经快要离他而远去了，于是强打精神走出户外，登上南山，想借欣赏春色以排遣积郁已久的愁苦与不快。这里的“春尽”我们应该不仅仅理解为自然界的春天将要过去了，还应该想到人生青春岁月之有限。诗人不甘心就此消沉下去，不能就这样枉费青春，不甘心庸庸碌碌了此一生，因此才在“忽闻春尽”之后振作精神“强登山”。\n\n　　“因过竹院逢僧话”，“因”，当为介词，有“由于”之意；“竹院”，就是寺院，僧人参禅悟道修行之地。诗人来这里干什么？有意来的也好，无意路过也罢，总之，人还是进去了，并且与寺内的高僧谈禅悟道闲聊了很久。“逢僧话”之“逢”字告诉读者是无意之中碰到的；“话”，即与老和尚谈禅悟道，聊天，吐露心中的苦闷与不快，探讨人生之喜怒哀乐。作为佛家，对待人生的观念自古多为淡化人生功利，平和情绪心态，面对惨淡现实，视若罔闻，处变不惊。不论有多大的烦恼与不快，学会深藏于心底，这样才能忘记过去，笑对人生，憧憬未来。\n\n　　“又得浮生半日闲”，点睛之笔。浮生半日闲，是因为过竹院逢僧话。此句深深禅意，揭示了无趣盲目的人生，半日闲最难得。\n\n　　作者已经对人生有所觉悟，并找出自己的答案。这首诗就是他心境的写照，有人以为是“偷得浮生半日闲”，并对之解释，其实不然“偷得”也好，“又得”也好，并非对人生的消极应对，而是一种自然之道。', poem_tags = '抒情,人生' WHERE poem_title = '题鹤林寺僧舍' AND poem_author = '李涉';
UPDATE edu_poem SET poem_translation = '进入黄花川游览，每每都去追逐那条青溪。\n溪水随着山势，百转千回，经过的路途，却不足百里。\n水声在山间乱石中喧嚣，水色在深密的松林里幽静深沉。\n水草在溪水中轻轻摇荡，芦苇清晰地倒映在碧水之中。\n我的心一向悠闲，如同清澈的溪水淡泊安宁。\n但愿我能留在溪边的盘石上，在垂钓中度过我的一生。', poem_notes = '青溪：在今陕西勉县之东。\n言：发语词，无义。黄花川：在今陕西凤县东北黄花镇附近。\n趣途：趣，同“趋”，指走过的路途。\n声：溪水声。色：山色。\n漾漾：水波动荡。菱荇（língxìng）：泛指水草。\n葭（jiā）苇：泛指芦苇。“漾漾”二句描写菱荇在青溪水中浮动，芦苇的倒影映照于清澈的流水。\n素：一向。闲：悠闲淡泊。\n澹（dàn）：恬静安然。澹：溪水澄澈平静。\n磐石：大石。\n将已矣：将以此度过终生。已：结束。', poem_appreciation = '此诗借颂扬名不见经传的青溪，来印证自己的素愿。以青溪之淡泊，喻自身之素愿安闲。\n\n　　这是一首写于归隐之后的山水诗。诗的每一句都可以独立成为一幅优美的画面，溪流随山势蜿蜓，在乱石中奔腾咆哮，在松林里静静流淌，水面微波荡漾，各种水生植物随波浮动，溪边的巨石上，垂钓老翁消闲自在。诗句自然清淡，绘声绘色，静中有动，托物寄情，韵味无穷。\n\n　　诗开头四句对青溪作总的介绍后，接着采用“移步换形”的写法，顺流而下，描绘了溪水一幅幅各具特色的画面。你看，当它在山间乱石中穿过时，水势湍急，潺潺的溪流声忽然变成了一片喧哗。“喧”字造成了强烈的声感，给人以如闻其声的感受。当它流经松林中的平地时，这同一条青溪却又显得那么娴静、安谧，几乎没有一点声息。澄碧的溪水与两岸郁郁葱葱的松色相映，融成一片，色调特别幽美、和谐。这一联中一动一静，以动衬静，声色相通，极富于意境美。再看，当青溪缓缓流出松林，进入开阔地带后，又是另一番景象：水面上浮泛着菱叶、荇菜等水生植物，一片葱绿，水流过处，微波荡漾，摇曳生姿；再向前走去，水面又似明镜般的清澈碧透，岸边浅水中的芦花、苇叶，倒映如画，天然生色。这一联，“漾漾”绘水动貌，“澄澄”状水静貌，也是一动一静，极为传神。诗人笔下的青溪，既喧闹，又沉静，既活泼，又安详，既幽深，又素净，从不断的流动变化中，表现出了鲜明个性和盎然生意。读后令人油然而生爱悦之情。\n\n　　其实，青溪并没有什么奇景，它那素淡的景致，为什么在诗人的眼中、笔下，会具有如此的魅力呢？诚如王国维所说：“一切景语皆情语也。”（《人间词话删稿》）王维也正是从青溪素淡的天然景致中，发现了与他那恬淡的心境、闲逸的情趣高度和谐一致的境界。“我心素已闲，清川澹如此。”诗人正是有意借青溪来为自己写照，以清川的淡泊来印证自己的素愿，心境、物境在这里已融合为一了。最后，诗人暗用了东汉严子陵垂钓富春江的典故，也想以隐居青溪来作为自己的归宿了。这固然说明诗人对青溪的喜爱，更反映了他在仕途失意后自甘淡泊的心情。这一点，写来含而不露，耐人寻味。\n\n　　这首诗，自然、清淡、素雅，写景抒情均不刻意为之，表面上看似不着力，而读来韵味隽永醇厚，平淡而有思致。前人评“王右丞如秋水芙蕖，倚风自笑”，是最恰当不过的。', poem_tags = '唐诗三百首,山水,托物寄情' WHERE poem_title = '青溪 / 过青溪水作' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '殷王武丁神勇英武，是他兴师讨伐荆楚。王师深入敌方险阻，众多楚兵全被俘虏。扫荡荆楚统治领土，成汤子孙功业建树。\n你这偏僻之地荆楚，长久居住中国南方。从前成汤建立殷商，那些远方民族氐羌，没人胆敢不来献享，没人胆敢不来朝王。殷王实为天下之长。\n上天命令诸侯注意，建都大禹治水之地。每年按时来朝来祭，不受责备不受鄙夷，好好去把农业管理。\n上天命令殷王监视，下方人民恭谨从事。赏不越级罚不滥施，人人不敢怠慢度日。君王命令下达诸侯，四方封国有福享受。\n殷商都城富丽堂皇，它是天下四方榜样。武丁有着赫赫声名，他的威灵光辉鲜明。既享长寿又得康宁，是他保佑我们后人。\n登上那座景山山巅，松树柏树挺拔参天。把它砍断把它远搬，削枝刨皮加工完善。长长松木制成方椽，楹柱排列粗壮溜圆。寝庙落成神灵安恬。', poem_notes = '挞（tà）：勇武貌。殷武：即殷高宗武丁，殷朝的一位中兴之主，曾任用贤人傅说（yuè）为相，并不断对西北的贡方、土方、鬼方、羌、周族等用兵，在位五十九年。\n荆楚：即荆州之楚国。《史记·楚世家》：“吴回生陆终。陆终生子六人，其长曰昆吾；二曰参胡；三曰彭祖；四曰会人；五曰曹姓；六曰季连，芈姓，楚其后也。昆吾氏，夏之时尝为侯伯，桀之时汤灭之。彭祖氏，殷之时尝为侯伯，殷之末世灭彭祖氏。…周文王之时，季连之苗裔曰鬻熊。鬻熊子事文王，蚤（早）卒。其子曰熊丽。熊丽生熊狂，熊狂生熊绎。熊绎当周成王之时，举文、武勤劳之后嗣，而封熊绎于楚蛮，封以子男之田，姓芈氏，居丹阳。”\n罙（shēn）：同“深”。古深字本作“突”，隶变作“罙”。\n裒（póu）：“捊”之别体，通“俘”，俘获。\n汤孙：指商汤的后代武丁。绪：功业。\n女（rǔ）：同“汝”，你。\n乡（xiàng）：通“向”。\n自彼氐羌：自，犹“虽”；氐、羌，散居在今西北狭西、甘肃、青海一带的边远民族。\n常：长。“常”是“尚声”字，与“长”字古音同部，故可释为“长”。\n多辟（bì）：众多诸侯国君。\n绩：通“迹”。\n来辟：犹言“来王”、“来朝”。\n祸适：读同“过谪”，义为谴责。\n解（xiè）：同“懈”。\n严（yǎn）：同“俨”，敬谨。\n不僭（jiàn）不滥：毛传：“赏不僭、刑不滥也。”\n封：毛传：“大也。”\n商邑：指商朝的国都西亳。《史记·殷本纪》正义：“汤自南亳迁西亳，仲丁迁隞，河亶甲居相，祖乙居耿，盘庚渡河，南居西亳，是五迁也。”殷高宗武丁是盘庚之后的中兴之主，其时建都西亳，在今河南偃师。翼翼：都城盛大貌。\n极：准则。\n濯（zhuó）濯：形容威灵光辉鲜明。\n后生：犹言后代子孙。\n景山：陈奂《诗毛氏传疏》：“考今河南偃师县有缑氏城，县南二十里有景山，即此诗之景山也。”\n丸丸：形容松柏条直挺拔。\n方：是，乃。斲（zhuó）：同“斫”，砍。虔：马瑞辰《毛诗传笺通释》以为“削”。此指用刀削木。\n桷（jué）：方形的椽子。梃（chān）：木长貌。\n旅：当依毛传释为“陈列”。有闲：闲闲，大貌。\n寝：此指为殷高宗所建的寝庙。古时的寝庙分两部分，后面停放牌位和先人遗物的地方叫“寝”，前面祭祀的地方叫“庙”。孔：很。', poem_appreciation = '《商颂·殷武》这首诗的主旨，是通过高宗寝庙落成举行的祭典，极力颂扬殷高宗继承成汤的事业所建树的中兴业绩。\n\n　　全诗共六章，一、四、五章每章六句，二、六章每章七句，三章五句。前五章写殷高宗武丁中兴之事，最后一章写高宗寝庙落成的情景。\n\n　　这首诗歌在艺术表现上的突出特色，是各章都有它描写的侧重点。第一章言武丁伐楚之功。“挞彼殷武，奋伐荆楚”二句，表现了武丁对楚用兵的勇猛神速。“罙（深）入其阻，裒荆之旅”，写出武丁的军队是在突破险阻中取得节节胜利。“有截其所，汤孙之绪”，特别点明武丁之所以能征服荆楚之地，那是因为他是成汤的后世子孙，理应有所作为。第二章写武丁对荆楚的训诫。“维女（汝）荆楚，居国南乡（向）”二句，从荆楚所处的地理位置，指出它理应俯首听命。“昔有成汤，自彼氐羌。莫敢不来享，莫敢不来王，曰商是常。”这是以成汤征服氐、羌的先例来告诫荆楚归服，可谓是“刚柔并举”。第三章只有五句，可能有脱文，是写四方诸侯来朝。说殷武丁秉承“天命”统治诸侯，因之诸侯入国朝见天子、在封地勤治农事，都是他们应尽的职守。第四章，进一步申述武丁是受“天命”的中兴之主，人民百姓只能安分守己，按商朝的政令行动。第五章，写商朝的国都西亳地处中心地带的盛况，这里曾是中兴之主殷武丁运筹帷幄、决胜千里的地方，故特别用“商邑翼翼，四方之极”两句诗来渲染它，而武丁在位长达五十九年，说他“赫赫厥声，濯濯厥灵”，并不过分。末章描写修建高宗寝庙的情景，用“陟彼景山，松柏丸丸”两句诗作比兴，不但形象生动，而且有象征意义，象征殷武丁的中兴业绩垂之不朽。\n\n　　这首诗在用韵上也有其特色。第一章句句用韵，“武”“楚”“阻”“旅”“所”“绪”同叶鱼部韵；第二章除“维女荆楚”一句不用韵，其余句句用韵，“乡”“汤”“羌”“享”“王”“常”同叶阳部韵；第三章句句用韵，“辟”“绩”“辟”“适（谪）”“解（懈）”是锡支通韵；第四章句句用韵，前后换韵，“监”“严”“滥”“遑”是谈阳合韵，“国”“福”叶职部韵；第五章句句用韵，前后换韵，“翼”“极”叶职部韵，“声”“灵”“宁”“生”叶耕部韵；最后一章句句用韵，“山”“丸”“迁”“虔”“梃”“闲”“安”叶元部韵。由于末章用元韵一韵到底，颇能渲染出宗庙落成的喜庆气氛。', poem_tags = '诗经,祭祀,颂歌' WHERE poem_title = '商颂·殷武' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '鸳鸯双双轻飞翔，遭遇大小罗与网。祝福君子万年寿，福禄一同来安享。\n鸳鸯相偎在鱼梁，喙儿插进左翅膀。祝福君子万年寿，一生幸福绵绵长。\n拉车辕马在马房，每天喂草喂杂粮。祝福君子万年寿，福禄把他来滋养。\n拉车辕马在马槽，每天喂粮喂饲草。祝福君子万年寿，福禄齐享永相保。', poem_notes = '鸳鸯：鸭科水鸟名。古人以此鸟雌雄双居，永不分离，故称之为“匹鸟”。\n毕：长柄的捕鸟小网。罗：无柄的捕鸟网。\n宜：《说文解字》：“宜，所安也。”引申为享。\n梁：筑在水中拦鱼的石坝，即鱼梁。\n戢（jí）：插。谓鸳鸯栖息时将喙插在左翅下。\n遐（xiá）：长远。\n乘（shèng）：四匹马拉的车子。乘马引申为拉车的马。厩（jiù）：马棚。\n摧（cuò）：通“莝”，铡草喂马。郑笺：“今‘莝’字也。”《说文解字》：“莝，斩刍也。”秣（mò）：用粮食喂马。\n艾：养。一说意为辅助。\n绥（suí）：安。', poem_appreciation = '此诗前二章以鸳鸯起兴，后二章以马起兴。鸳鸯是成双成对的鸟，马和亲迎之礼有关，故可以认为这是一首同婚姻有关的诗歌。前二章赞美男女双方才貌匹配，爱情忠贞；后二章祝福其生活富足美满。\n\n　　此诗一、二章以鸳鸯匹鸟兴夫妇爱慕之情。两章描绘了一对五彩缤纷的鸳鸯，拍动着羽毛绚丽的翅膀，双双飞翔在辽阔的天空，雌雄相伴，两情相依，情有独钟，心有所许，多么美妙的时刻，多么美好的图画！在遭到捕猎的危险时刻，仍然成双成对，忠贞不渝，并不是大难临头各自飞。从同甘到共苦两种境遇的转变，进一步展现了鸳鸯高洁的品格，挖掘了鸳鸯的典型的独特的禀性，较好地运用了象征的艺术手法，为后面对人物的抒写做了充分的准备。在第二章中，诗人抓住鸳鸯小憩时的一个细节，描摹入微，观察至细。在芳草萋萋的小坝上，一对鸳鸯相依相偎，红艳的嘴巴插入左边的翅膀，闭目养神，恬静悠闲，如一幅明丽淡雅的江南水墨风景图，满含着对美好生活的深深眷恋与无限追求。这二章一动一静，描摹毕肖，既是对今后婚姻生活的象征性写照，也是对婚姻的主观要求和美好希望。生活之中，欢乐与痛苦必然并存，既有甜蜜的欣悦，也有凄苦的哀愁，但只要双方心心相印、相濡以沫，苦乐之中就都有幸福在，即无所畏惧。诗人以鸳鸯比喻夫妻，贴切自然，易于引起欣赏者的共鸣，其形象逐渐积淀为中国传统文化的一种原型，为后世所普遍接受。\n\n　　诗的第三、四章以摧秣乘马，兴结婚亲迎之礼，充满了对婚后生活的美好憧憬。抓住迎亲所用的厩中肥马这一典型细节，引发人对婚礼情景的丰富联想：隆重、热烈、喜庆；并且厩有肥马也反映着生活的富足。这都含蓄地暗示了婚姻美好的客观条件：男女般配，郎才女貌，感情专一，家产丰裕；反映了诗人的婚姻价值观念，也是对理想人生、美好人生的由衷礼赞。', poem_tags = '诗经,婚姻' WHERE poem_title = '鸳鸯' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '译文 悲哉！秋之为气也。 悲哉，这秋天的萧飒之气! 萧瑟兮，草木摇落而变衰。 秋风凄凉草木都枯萎而凋零。 憭栗兮，若在远行。 冷落啊好像一人独自在远行， 登山临水兮，送将归。 又像登山临水送人踏归程。 泬寥兮，天高而气清； 天气清朗啊空旷又清凉， 寂寥兮，收潦而水清。 浊水退尽水面清澈又澄静。 憯凄增欷兮，薄寒之中人； 凄惨唏嘘秋寒侵人阵阵冷； 怆怳懭悢兮，去故而就新； 失意惆怅中去故而就新， 坎廪兮，贫士失职而志不平； 坎坷啊穷士困顿意难平。 廓落兮，羁旅而无友生； 在孤独的旅程中我没有朋友， 惆怅兮，而私自怜。 孤独寂寞哀怜之情独自生。 燕翩翩其辞归兮，蝉寂漠而无声。 燕子翩翩向温暖的南方飞，蝉儿困守寂寞无响声。 雁痈痈而南游兮，鹍鸡啁哳而悲鸣。 大雁和谐呜叫着高飞，鹃鸡却一直唧唧喳喳在悲鸣。 独申旦而不寐兮，哀蟋蟀之宵征。 从夜到明我都无法入梦乡，夜里蟋蟀哀鸣触动我幽情。 时亹亹而过中兮，蹇淹留而无成。 时光流逝不觉已过了中年，可还是停留在原地无所成。 悲忧穷戚兮独处廓，有美一人兮心不绎； 处境悲惨穷困啊又孤寂空落，有一个美人啊他心中不欢喜。 去乡离家兮徕远客，超逍遥兮今焉薄！ 离开家乡来这遥远地方做客，飘飘荡荡何时才是至期? 专思君兮不可化，君不知兮可柰何！ 思念君王的心意从未变化，君王不知无可奈何! 蓄怨兮积思，心烦憺兮忘食事。 积累着层层怨恨和思念，忧心如焚竟忘了吃饭的事情。 愿一见兮道余意，君之心兮与余异。 希望和您见一面来表白我心，可是您的想法与我不相应。 车既驾兮朅而归，不得见兮心伤悲。 车子已经驾好那我只能离去，不能与你相见让我悲伤不已。 倚结軨兮长太息，涕潺湲兮下沾轼。 倚着结拎长叹息，眼泪落下车前衡木湿。 慷慨绝兮不得，中瞀乱兮迷惑。 愤懑至极无法抑制，心中昏迷错落再也不能平静。 私自怜兮何极？心怦怦兮谅直。 这样的自叹自怜何时是尽头，内心忠诚正直永远是坚定! 皇天平分四时兮，窃独悲此廪秋。 老天平分春夏秋冬四季，独有这凄冷的秋天让我悲伤。 白露既下百草兮，奄离披此梧楸。 冰凉的露水降落在百草之上，一时间桐楸树都纷纷叶凋丧。 去白日之昭昭兮，袭长夜之悠悠。 昭昭白日离人远去，进入沉沉暗夜悠悠长。 离芳蔼之方壮兮，余萎约而悲愁。 芳菲繁茂的旺盛已成过去，如今只剩下萎缩和哀伤。 秋既先戒以白露兮，冬又申之以严霜。 白露降下预告秋来临，秋天过去又接着冬天的严霜。 收恢台之孟夏兮，然欿傺而沈藏。 孟夏浩大生气已收缩，那繁盛的景象早就被收藏。 叶烟邑而无色兮，枝烦挐而交横。 叶子颜色黯淡再也没有光泽，空枝交错纷乱一片杂乱相。 颜淫溢而将罢兮，柯彷佛而萎黄。 万物的色泽逐渐在凋落，颜色褪去只剩下稀疏的枯黄。 萷櫹槮之可哀兮，形销铄而瘀伤。 可怜那树梢光秃秃高耸，形体消磨郁积着病伤。 惟其纷糅而将落兮，恨其失时而无当。 那败叶与衰草相杂都将摇落，可惜它们已经失去了时光。 揽騑辔而下节兮，聊逍遥以相佯。 拉住马的缰绳停下车子，就消闲散步吧在这旦徜徉。 岁忽忽而遒尽兮，恐余寿之弗将。 岁时如水一年即将完结，恐怕从此我的性命不会太长。 悼余生之不时兮，逢此世之俇攘。 悲痛我的生不逢时，遇见的是这混乱无序的世相。 澹容与而独倚兮，蟋蟀鸣此西堂。 就一人散淡逍遥，巴走走停停，听蟋蟀悲鸣在西堂。 心怵惕而震荡兮，何所忧之多方。 叫声让心中震荡惊惧，百千忧思一齐涌上心房。 昂明月而太息兮，步列星而极明。 抬头仰望明月长长叹息，星光下徘徊一直到天亮。 窃悲夫蕙华之曾敷兮，纷旖旎乎都房。 暗悲那曾经花朵丰腴的香蕙，在华屋散播过浓郁芬芳。 何曾华之无实兮，从风雨而飞扬！ 为何如此好花却不曾结果实，遭遇到风雨瞬间香消玉飘扬。 以为君独服此蕙兮，羌无以异于众芳。 原以为君王独爱这蕙花，哪知道待她和普通花一样。 闵奇思之不通兮，将去君而高翔。 可怜这曲折心思不能告诉君，我就要离开到远方翱翔。 心闵怜之惨凄兮，愿一见而有明。 心哀悯而凄凉，我多么想见君王倾吐衷肠。 重无怨而生离兮，中结轸而增伤。 深念自己无罪却要生离，悲愁缠结越来越多增忧伤。 岂不郁陶而思君兮？君之门以九重！ 难道我不是心神郁结思念您，可是君的大门九重深。 猛犬狺狺而迎吠兮，关梁闭而不通。 凶猛的狗冲着我狺狺狂吠，不能通行的正是门关和桥梁。 皇天淫溢而秋霖兮，后土何时而得漧？ 上天总是连绵不绝降秋雨，潮湿的大地何时才干爽! 块独守此无泽兮，仰浮云而永叹！ 块然独守在这芜泽地，对着浮云长长叹息长哀伤。 何时俗之工巧兮？背绳墨而改错！ 为何时俗这样善于取巧?背离规矩并且抛弃法度。 却骐骥而不乘兮，策驽骀而取路。 拒绝乘坐那优良的骏马，却一定要鞭策劣马让它上路。 当世岂无骐骥兮，诚莫之能善御。 难道当今世上再无骏马，其实是没车夫可以将它驾驭。 见执辔者非其人兮，故驹跳而远去。 看见操缰的人滥竽充数，它就跳跃着远远逃去。 凫雁皆唼夫梁藻兮，凤愈飘翔而高举。 野鸭都吃着精米和水菜，凤凰也只得展开翅膀远举。 圜凿而方枘兮，吾固知其鉏铻而难入。 在圆的榫眼里放入方榫头，我就知道它一定相抵触。 众鸟皆有所登栖兮，凤独遑遑而无所集。 凡鸟都有地方可栖息，唯有凤凰无处可停好孤独。 愿衔枚而无言兮，尝被君之渥洽。 愿从此缄口不言做哑巴，又难忘您曾给我恩泽厚。 太公九十乃显荣兮，诚未遇其匹合。 姜太公九十岁才尊荣，诚因先前明君不曾遇。 谓骐骥兮安归？谓凤皇兮安栖？ 你说骏马到哪里找归处?你说凤凰到何处寻归宿? 变古易俗兮世衰，今之相者兮举肥。 世风衰败俗与往不同，相马的人眼里只有马肥瘦。 骐骥伏匿而不见兮，凤皇高飞而不下。 骏马全都藏起来再也不出现，凤凰也都高飞不下远远走。 鸟兽犹知褱德兮，何云贤士之不处？ 鸟兽尚且知道怀念有德的人，为何还要质问贤士不能留? 骥不骤进而求服兮，凤亦不贪餧而妄食。 良马从不贸然求驾车，凤凰也不贪婪地随便吃食物。 君弃远而不察兮，虽愿忠其焉得？ 君主轻于抛弃从不明察，贤人想效忠可怎能施展抱负! 欲寂漠而绝端兮，窃不敢忘初之厚德。 想从此沉默断除思念，心底不敢忘记当初你的厚遇。 独悲愁其伤人兮，冯郁郁其何极？ 独自悲秋伤心怀，愤懑浓愁何时住! 霜露惨凄而交下兮，心尚幸其弗济。 漫天的寒霜露水一齐落，我心里还希冀他们不会成功。 霰雪雰糅其增加兮，乃知遭命之将至。 雪糁雪花纷纷扬扬齐夹杂，才知道我的坏命运将显形。 愿徼幸而有待兮，泊莽莽与野草同死。 心里还侥幸能等待您的醒悟，却要腐烂在荒野与野草相同。 愿自往而径游兮，路壅绝而不通。 想亲自走捷径游说君王，可是道路却堵塞断绝了交通。 欲循道而平驱兮，又未知其所从。 想要沿着大路驱车来见，可不知何去又何从。 然中路而迷惑兮，自厌按而学诵。 路的中途就陷入迷惑，压制着愤懑学着将诗歌诵。 性愚陋以褊浅兮，信未达乎从容。 天性愚笨性格又狭隘，遇到这样的挫折实在难从容。 窃美申包胥之气晟兮，恐时世之不固。 暗自赞美申包胥的大志气，又担心时世不相同。 何时俗之工巧兮？灭规矩而改凿！ 为何时代风俗偷奸取巧，破坏了规矩妄自改凿孔。 独耿介而不随兮，愿慕先圣之遗教。 要独自耿直光明不随波逐流，仰慕先圣遵从德教老传统。 处浊世而显荣兮，非余心之所乐。 在混浊的世界身处高位，不是我心希望的光荣。 与其无义而有名兮，宁穷处而守高。 与其徒有虚名失道义，情愿保持节操永远都贫穷。 食不偷而为饱兮，衣不苟而为温。 决不苟且求饱食，决不苟且求衣暖融融。 窃慕诗人之遗风兮，愿托志乎素餐。 敬佩诗人留下的遗风，决不白白吃饭不做事情。 蹇充倔而无端兮，泊莽莽而无垠。 穷困褴褛无终止，飘零在野外茫茫永无尽。 无衣裘以御冬兮，恐溘死不得见乎阳春。 没有衣服抵御这刺骨寒气，怕要忽然死去再见不到阳春 靓杪秋之遥夜兮，心缭悷而有哀。 安静的暮秋夜正长，郁结缠绕无尽忧。 春秋逴逴而日高兮，然惆怅而自悲。 春秋替代渐渐年事高，于是独自惆怅独自忧。 四时递来而卒岁兮，阴阳不可与俪偕。 四季更替一年又结束，阴和阳永远不能共存处。 白日晼晚其将入兮，明月销铄而减毁。 天色苍茫太阳将落下，明月也残缺圆满不再显露。 岁忽忽而遒尽兮，老冉冉而愈弛。 岁月在恍惚中又迫近了年尾，年纪越老心志也跟着在朽蠹。 心摇悦而日幸兮，然怊怅而无冀。 心意摇动每日总生起些期盼，可又惆怅这都是白日在做梦。 中憯恻之凄怆兮，长太息而增欷。 沉痛迫中肠啊我心苦楚，长长的叹息一声声。 年洋洋以日往兮，老嵺廓而无处。 时光荏冉年华空流逝，老迈人在这空旷世界无宿处。 事亹亹而觊进兮，蹇淹留而踌躇。 勤勉国事希望得到进用，一生就白白度过空踯躅。 何泛滥之浮云兮？猋痈蔽此明月。 浮云何其翻滚又腾涌，迅速升起将明月来遮蔽。 忠昭昭而愿见兮，然霠曀而莫达。 昭昭的忠心希望君主能见到，可是天色昏暗无法知晓。 愿皓日之显行兮，云蒙蒙而蔽之。 希望太阳能光明显耀地运行，可是乌云蒙蒙总是将它遮盖。 窃不自料而愿忠兮，或黕点而污之。 自不量力想献出一片忠心，可是有人将我诬蔑和陷害。 尧舜之抗行兮，了冥冥而薄天。 唐尧虞舜的品行是多么高尚，光辉耀眼可以上与天齐。 何险巇之嫉妒兮？被以不慈之伪名。 嫉妒小人多么险恶，横加诬蔑说他们没有恩慈。 彼日月之照明兮，尚黯黮而有瑕。 日月在天空照耀，尚且还有点点的瑕疵。 何况一国之事兮，亦多端而胶加。 何况是一国大事，更是头绪繁多纠葛。 被荷裯之晏晏兮，然潢洋而不可带。 穿上柔和的荷叶衣裳真好看，可是宽大空荡又不能系带子。 既骄美而伐武兮，负左右之耿介。 您总是夸耀自己美好又勇武，自负左右亲信都是耿介之士。 憎愠惀之修美兮，好夫人之慷慨。 美德之人总被你憎恶，装腔作势的小人却总让你喜。 众踥蹀而日进兮，美超远而逾迈。 小人投机钻营一天天在高升，贤德们总是越来越远离开你。 农夫辍耕而容与兮，恐田野之芜秽。 农夫都停下耕作来休息，恐怕田野会凋敞。 事绵绵而多私兮，窃悼后之危败。 国事纷纭群小以私多害公，真担心国家终归要溃崩。 世雷同而炫曜兮，何毁誉之昧昧！ 群小雷同相互炫耀，毁誉颠倒错乱一片糊涂。 今修饰而窥镜兮，后尚可以窜藏。 现在对着镜子来修饰，到后来如何逃脱罪责和惩处! 愿寄言夫流星兮，羌儵忽而难当。 愿意托流星带封信给楚王，可是它飞来飞去难相遇。 卒痈蔽此浮云，下暗漠而无光。 天地都被这浮云遮住，下界昏暗一片模糊。 尧舜皆有所举任兮，故高枕而自适。 唐尧虞舜选贤任能，因此高枕无忧自逍遥。 谅无怨于天下兮，心焉取此怵惕？ 自信没有辜负天下期望，就不会心里有鬼总恐慌。 乘骐骥之浏浏兮，驭安用夫强策？ 骏马驾车总会畅行如流水，何用鞭笞强督促? 谅城郭之不足恃兮，虽重介之何益？ 如果城郭都不可靠，厚重的盔又有什么用处? 邅翼翼而无终兮，忳惛惛而愁约。 小心谨慎又竭身恭敬，可郁闷沉沉心被缚。 生天地之若过兮，功不成而无嶜。 人生天地如过客，事业不成名声也无从树。 愿沉滞而不见兮，尚欲布名乎天下。 想就这样隐姓埋名人不见，又想四海之内名声布。 然潢洋而不遇兮，直怐□而自苦。 飘飘荡荡不受重用，就这样空怀愚忠自愁苦。 莽洋洋而无极兮，忽翱翔之焉薄？ 空落旷野茫茫无边际，一身漂泊何处是归处! 国有骥而不知乘兮，焉皇皇而更索？ 国有良马却不知乘，还急匆匆到哪去求索? 宁戚讴于车下兮，桓公闻而知之。 宁戚在车下一唱歌，桓公就知道他有大抱负。 无伯乐之相善兮，今谁使乎誉之？ 如果世上没有了伯乐的慧眼，谁还能将良马来称数? 罔流涕以聊虑兮，惟着意而得之。 怅惘流泪姑且抒发忧愁，望国君能体察我的忠厚。 纷纯纯之愿忠兮，妒被离而鄣之。 纯纯的心意想要献给君主，无休无止的嫉妒将我来障堵。 愿赐不肖之躯而别离兮，放游志乎云中。 望还我轻贱身躯让我离去，我要在云中闲游找个住处。 乘精气之抟抟兮，骛诸神之湛湛。 乘着团团的精气，在众多的神灵之中驰骋奔逐。 骖白霓之习习兮，历群灵之丰丰。 驾着白虹在天空飘飘飞，众神灵纷纷飘过也不曾停步。 左朱雀之苃苃兮，右苍龙之躣躣。 左边有南方神雀翩翩飞翔，右边有东方神龙在奔走。 属雷师之阗阗兮，通飞廉之衙衙。 雷师在身后鼓起阗阗的雷声，风神在前面呼呼作响来开路。 前轻辌之锵锵兮，后辎乘之从从。 前面有轻车响起了悦耳铃声，后面辎重车轰隆隆一齐集聚。 载云旗之委蛇兮，扈屯骑之容容。 车上插着的云旗随风飘飘舞，跟随的车队容容飞扬好气度。 计专专之不可化兮，愿遂推而为臧。 拳拳忠贞的心意终不可改变，终愿自进做名贤。 赖皇天之厚德兮，还及君之无恙。 靠着皇天的厚恩，保佑我君无病无灾永安然。 ▲', poem_appreciation = '宋玉是屈原之后最重要的楚辞作家。在《史记·屈原列传》、《汉书-艺文志》、《汉书·古今人表》中，都说宋玉生于屈原之后，到王逸才第一个说宋玉是屈原的弟子，还说《九辩》是思师之作。宋玉的作品，现存十四篇，据《汉书·艺文志》说是十六篇（其中一些已残缺），可见有些作品已亡佚。现存作品中，以《九辩》、《高唐赋》、《神女赋》、《登徒子好色赋》、《风赋》等最为著名。\n\n　　这些作品的共同特点是以情胜理，用形象思维的手法，把浪漫主义的情感抒发得淋漓尽致，在中国文学传统上，他的作品与屈原的作品一样，无疑具有开创性意义。作品中悲秋、神女、美人、风雨、山川、游历等主题，一直影响着后代的中国文学。主题\n\n　　《九辩》的悲秋主题，使之成为中国文学史上第一篇情深意长的悲秋之作。把秋季万木黄落、山川萧瑟的自然现象，与诗人失意巡游、心绪飘浮的悲怆有机地结合起来，人的感情外射到自然界，作品凝结着一股排遣不去、反覆缠绵的悲剧气息，勾起人们对自然变化、人事浮沉的感喟，千古之下，仍感动着无数读者。\n\n　　《九辩》现传本子中，有分为九章的，也有分为十章的。其实，无论分九章、十章，都没有必要作过多的争辩，因为全篇作品，贯穿的只是悲秋主题。在不同的诗章中，不过是把悲秋情怀反覆咀嚼、重沓喻示而已。今参酌洪兴祖《楚辞补注》、朱熹《楚辞集注》，分为十章。\n\n　　开头，就鲜明地点明了主题：“悲哉秋之为气也！草木摇落而变衰。憭栗兮若在远行，登山临水兮送将归。”在先秦典籍中，虽然不乏人们对秋寒的畏惧，但更多是秋天农作物收获的喜悦。宋玉却把秋天万木凋落与人的遭遇联系起来。“坎廪兮贫士失职而志不平”、“廓落兮羁旅而无友生”、“怆怳懭悢兮去故而就新”、“时亹亹而过中兮，蹇淹留而无成”，失去官职，没人同情，独自流浪，人过中年事业无成，所有不幸，仿佛都集中在诗中抒情主人公的身上。于是，这位贫困、孤独、哀怨的流浪者，眼目中秋天的景物，无不带上悲伤的颜色。贫士悲秋主题一旦确定，诗歌就顺利地展开了。\n\n　　从第二章到第十章，《九辩》反覆抒述见秋而悲的原因。不能为世所用而事业无成，是萦绕心怀的痛苦。造成这种痛苦也是多方面的。第二章说“有美一人兮心不绎，去乡离家兮徕远客，超逍遥兮今焉薄”。美丽的女人竟然被抛弃，独自飘零远方，而所思恋之君却不理睬，爱情破灭了，能不伤心吗！第三章写一路所见秋色，眼中都是凄凉。你看，“白露既下百草兮，奄离披此梧楸”，寒露下来，百草焦黄，乔木落叶，春天的群芳与夏日的浓荫，都消失了。“惟其纷糅而将落兮，恨其失时而无当。”季节过去了，草木只能黄落；机遇失去了，贫士唯有悲哀。第四章在脉络上遥接第二章，还是以一个被君所弃的美人口吻，写她求爱不遂的悲苦。“猛犬狺狺而迎吠兮，关梁闭而不通。”大门紧闭，门外恶狗狂吠，怎能传送去一片心意呢?无奈之下。只好“块独守此无泽兮，仰浮云而永叹”。在秋草摇摇的水泽边，伤心人只能仰天悲叹了！\n\n　　第五章是直接模仿屈原的《离骚》和《涉江》的，所以历来评论者，大都认为《九辩》的政治性社会性就在这一章中。特别是诗中用了姜太公九十岁才获得尊荣的典故，显示诗人参与军国大事、建功立业的希冀。不过，诗中直接论及当时国家形势并不明显，反而是突出不为世用的悲哀：“君弃远而不察兮，虽愿忠其焉得?”如果与诗歌中的贫士形象相联系，就可以领会到，宋玉所说的是：如果贫士为君王所用，也能像姜太公一样立下赫赫功勋；如果不能为君王赏识，只能“冯郁郁其何极”，悲愤郁结，不知何年何月才能消散了！这一章笔墨集中在贫士自身进行抒情。\n\n　　第六章承第五章，意蕴主旨复沓。不过，着重写霜露霰雪，突出了秋已深、冬即至的季节特点。“愿徼幸而有待兮，泊莽莽与野草同死”，季节不等人，岁月不等人，贫士失意，虽然怀着侥幸心情等待，然而仍然是无望的等待。冬季来临，能熬过这严寒吗：“无衣裘以御冬兮，恐溘死而不得见乎阳春！”由悲秋发展到惧冬，贫士的心情更紧迫也更凄苦了。\n\n　　第七章全然抒发岁月流逝的感伤，诗中秋夜、夕阳、流水、明月，无不加强了岁月不居、一事无成的慨叹。\n\n　　第八章、第九章，诗歌集中突出“失人”的悲哀。所谓“失人”，一方面指掌权得势的都是薄幸小人，奸臣当道，把持国柄，使社会污秽混乱；一方面指如贫士一类贤人被弃置不用，心怀壮志宏才却不得施展，还受到小人的排挤、压迫。在悲怨之后，诗人仍然抱有希望，“罔流涕以聊虑兮，惟著意而得之”。要擦干眼泪去唱歌，壮气可嘉，但底气不足，因为“失人”的现实仍然存在，贫士要抒怀，只能依赖幻想了。这秋天的悲哀，仍然盘结在贫士心胸之间。\n\n　　最后第十章，是全诗的结束。悲秋如何了结呢?只有依赖浪漫主义的想像：人间得不到的，天上能够补偿。于是，贫士“愿赐不肖之躯而别离兮，放游志乎云中。”离开躯体的精魂，穿过太空的日月虹气，成了天上神灵的主宰，朱雀、苍龙、雷师、风神都听他调遣，成了他车驾的扈从，多么神气又多么得意！贫士之贫变成了贵，悲秋之悲变成了喜。悲秋的主旨却引出一个欢乐结尾，然而那欢乐只是幻想的虚构的欢乐。贫士得志，是虚幻的想像的得志，现实社会中，秋天仍然是草木黄落，贫士仍然是不为世用。现实与想像的强烈对比，把悲秋主题更加强化了。\n\n　　《九辩》把一个贫士在深秋时节“失时”、“失人”的心境写得生动精彩，有很强烈的感染力。悲秋主题得到形象的感性的抒述。不过，从社会意义而言，此诗虽然也有伤时之语，但总的说来缺乏社会的指涉性。所以司马迁说“皆祖屈原之从容辞令，终莫敢直谏”（《史记·屈原贾生列传》）。\n\n　　从文学艺术的创造性来看，《九辩》是很成功的作品。悲秋题旨，本来是古代南方文学（以《楚辞》为代表）的特点之一，最能显示楚骚精神的浪漫主义色彩。《九辩》把悲秋题旨发挥得淋漓尽致，也成为后代人们学习的典范。从此，在中国文学中，悲秋一直是诗文家喜爱的题材，雄才大略的汉武帝有《秋风辞》，潇洒俊秀的曹植有《秋思赋》、《遥逝》，高瞻远瞩的曹丕有《燕歌行》。魏晋南北朝诗人笔下的秋天，大都带有《九辩》悲秋的气息，庾信《拟咏怀二十七首》之十一“摇落秋为气，凄凉多怨情”，以悲秋带出身世之感、家国之恨，更为悲秋主题谱写出新曲。此后历经唐宋元明清，诗词中的悲秋之风始终弥漫不散。悲秋已经成为中国传统文学的母题之一，产生了许多动人的作品，而《九辩》原创性的功劳，当是不可抹杀的。', poem_tags = '楚辞,悲秋,长诗' WHERE poem_title = '九辩' AND poem_author = '宋玉';
UPDATE edu_poem SET poem_translation = '译文 　　苏武字子卿，年轻时凭着父亲的职位，兄弟三人都做了皇帝的侍从，并逐渐被提升为掌管皇帝鞍马鹰犬射猎工具的官。当时汉朝廷不断讨伐匈奴，多次互派使节彼此暗中侦察。匈奴扣留了汉使节郭吉、路充国等前后十余批人。匈奴使节前来，汉朝庭也扣留他们以相抵。 公元前100年，且鞮刚刚立为单于，唯恐受到汉的袭击，于是说：“汉皇帝，是我的长辈。”全部送还了汉廷使节路充国等人。汉武帝赞许他这种通晓情理的做法，于是派遣苏武以中郎将的身份出使，持旄节护送扣留在汉的匈奴使者回国，顺便送给单于很丰厚的礼物，以答谢他的好意。 　　苏武同副中郎将张胜以及临时委派的使臣属官常惠等，加上招募来的士卒、侦察人员百多人一同前往。到了匈奴那里，摆列财物赠给单于。单于越发傲慢，不是汉所期望的那样。单于正要派使者护送苏武等人归汉，适逢缑王与长水人虞常等人在匈奴内部谋反。缑王是昆邪王姐姐的儿子，与昆邪王一起降汉，后来又跟随浞野侯赵破奴重新陷胡地，在卫律统率的那些投降者中，暗中共同策划绑架单于的母亲阏氏归汉。正好碰上苏武等人到匈奴。虞常在汉的时候，一向与副使张胜有交往，私下拜访张胜，说：“听说汉天子很怨恨卫律，我虞常能为汉廷埋伏弩弓将他射死。我的母亲与弟弟都在汉，希望受到汉廷的照顾。”张胜许诺了他，把财物送给了虞常。一个多月后，单于外出打猎，只有阏氏和单于的子弟在家。虞常等七十余人将要起事，其中一人夜晚逃走，把他们的计划报告了阏氏及其子弟。单于子弟发兵与他们交战，缑王等都战死；虞常被活捉。 　　单于派卫律审处这一案件。张胜听到这个消息，担心他和虞常私下所说的那些话被揭发，便把事情经过告诉了苏武。苏武说：“事情到了如此地步，这样一定会牵连到我们。受到侮辱才去死，更对不起国家！”因此想自杀。张胜、常惠一起制止了他。虞常果然供出了张胜。单于大怒，召集许多贵族前来商议，想杀掉汉使者。左伊秩訾说：“假如是谋杀单于，又用什么更严的刑法呢？应当都叫他们投降。”单于派卫律召唤苏武来受审讯。苏武对常惠说：“丧失气节、玷辱使命，即使活着，还有什么脸面回到汉廷去呢！”说着拔出佩带的刀自刎，卫律大吃一惊，自己抱住、扶好苏武，派人骑快马去找医生。医生在地上挖一个坑，在坑中点燃微火，然后把苏武脸朝下放在坑上，轻轻地敲打他的背部，让淤血流出来。苏武本来已经断了气，这样过了好半天才重新呼吸。常惠等人哭泣着，用车子把苏武拉回营帐。单于钦佩苏武的节操，早晚派人探望、询问苏武，而把张胜逮捕监禁起来。 　　苏武的伤势逐渐好了。单于派使者通知苏武，一起来审处虞常，想借这个机会使苏武投降。剑斩虞常后，卫律说：“汉使张胜，谋杀单于亲近的大臣，应当处死。单于招降的人，赦免他们的罪。”举剑要击杀张胜，张胜请求投降。卫律对苏武说：“副使有罪，应该连坐到你。”苏武说：“我本来就没有参予谋划，又不是他的亲属，怎么谈得上连坐？”卫律又举剑对准苏武，苏武岿然不动。卫律说：“苏君！我卫律以前背弃汉廷，归顺匈奴，幸运地受到单于的大恩，赐我爵号，让我称王；拥有奴隶数万、马和其他牲畜满山，如此富贵！苏君你今日投降，明日也是这样。白白地用身体给草地做肥料，又有谁知道你呢！”苏武毫无反应。卫律说：“你顺着我而投降，我与你结为兄弟；今天不听我的安排，以后再想见我，还能得到机会吗？” 苏武痛骂卫律说：“你做人家的臣下和儿子，不顾及恩德义理，背叛皇上、抛弃亲人，在异族那里做投降的奴隶，我为什么要见你！况且单于信任你，让你决定别人的死活，而你却居心不平，不主持公道，反而想要使汉皇帝和匈奴单于二主相斗，旁观两国的灾祸和损失！南越王杀汉使者，结果九郡被平定。宛王杀汉使者，自己头颅被悬挂在宫殿的北门。朝鲜王杀汉使者，随即被讨平。唯独匈奴未受惩罚。你明知道我决不会投降，想要使汉和匈奴互相攻打。匈奴灭亡的灾祸，将从我开始了！”卫律知道苏武终究不可胁迫投降，报告了单于。单于越发想要使他投降，就把苏武囚禁起来，放在大地窖里面，不给他喝的吃的。天下雪，苏武卧着嚼雪，同毡毛一起吞下充饥，几日不死。匈奴以为神奇，就把苏武迁移到北海边没有人的地方，让他放牧公羊，说等到公羊生了小羊才得归汉。同时把他的部下及其随从人员常惠等分别安置到别的地方。 　　苏武迁移到北海后，粮食运不到，只能掘取野鼠所储藏的野生果实来吃。他拄着汉廷的符节牧羊，睡觉、起来都拿着，以致系在节上的牦牛尾毛全部脱尽。一共过了五、六年，单于的弟弟於靬王到北海上打猎。苏武会编结打猎的网，矫正弓弩，於靬王颇器重他，供给他衣服、食品。三年多过后，於靬王得病，赐给苏武马匹和牲畜、盛酒酪的瓦器、圆顶的毡帐篷。王死后，他的部下也都迁离。这年冬天，丁令人盗去了苏武的牛羊，苏武又陷入穷困。 　　当初，苏武与李陵都为侍中。苏武出使匈奴的第二年，李陵投降匈奴，不敢访求苏武。时间一久，单于派遣李陵去北海，为苏武安排了酒宴和歌舞。李陵趁机对苏武说：“单于听说我与你交情一向深厚，所以派我来劝说足下，愿谦诚地相待你。你终究不能回归本朝了，白白地在荒无人烟的地方受苦，你对汉廷的信义又怎能有所表现呢？以前你的大哥苏嘉做奉车都尉，跟随皇上到雍的棫宫，扶着皇帝的车驾下殿阶，碰到柱子，折断了车辕，被定为大不敬的罪，用剑自杀了，只不过赐钱二百万用以下葬。你弟弟孺卿跟随皇上去祭祀河东土神，骑着马的宦官与驸马争船，把驸马推下去掉到河中淹死了。骑着马的宦官逃走了。皇上命令孺卿去追捕，他抓不到，因害怕而服毒自杀。我离开长安的时候，你的母亲已去世，我送葬到阳陵。你的夫人年纪还轻，听说已改嫁了，家中只有两个妹妹，两个女儿和一个男孩，如今又过了十多年，生死不知。人生像早晨的露水，何必长久地像这样折磨自己！我刚投降时，终日若有所失，几乎要发狂，自己痛心对不起汉廷，加上老母拘禁在保宫，你不想投降的心情，怎能超过当时我李陵呢！并且皇上年纪大了，法令随时变更，大臣无罪而全家被杀的有十几家，安危不可预料。你还打算为谁守节呢？希望你听从我的劝告，不要再说什么了！” 　　苏武说：“我苏武父子无功劳和恩德，都是皇帝栽培提拔起来的，官职升到列将，爵位封为通侯，兄弟三人都是皇帝的亲近之臣，常常愿意为朝廷牺牲一切。现在得到牺牲自己以效忠国家的机会，即使受到斧钺和汤镬这样的极刑，我也心甘情愿。大臣效忠君王，就像儿子效忠父亲，儿子为父亲而死，没有什么可恨，希望你不要再说了！” 李陵与苏武共饮了几天，又说：“你一定要听从我的话。”苏武说：“我料定自己已经是死去的人了！单于一定要逼迫我投降，那么就请结束今天的欢乐，让我死在你的面前！”李陵见苏武对朝廷如此真诚，慨然长叹道：“啊，义士！我李陵与卫律的罪恶，上能达天！”说着眼泪直流，浸湿了衣襟，告别苏武而去。 　　李陵不好意思亲自送礼物给苏武，让他的妻子赐给苏武几十头牛羊。后来李陵又到北海，对苏武说：“边界上抓住了云中郡的一个俘虏，说太守以下的官吏百姓都穿白的丧服，说是皇上死了。”苏武听到这个消息，面向南放声大哭，吐血，每天早晚哭吊达几月之久。汉昭帝登位，几年后，匈奴和汉达成和议。汉廷寻求苏武等人，匈奴撒谎说苏武已死。后来汉使者又到匈奴，常惠请求看守他的人同他一起去，在夜晚见到了汉使，原原本本地述说了几年来在匈奴的情况。告诉汉使者要他对单于说：“天子在上林苑中射猎，射得一只大雁，脚上系着帛书，上面说苏武等人在北海。”汉使者万分高兴，按照常惠所教的话去责问单于。单于看着身边的人十分惊讶，向汉使道歉说：“苏武等人的确还活着。”于是李陵安排酒筵向苏武祝贺，说：“今天你还归，在匈奴中扬名，在汉皇族中功绩显赫。即使古代史书所记载的事迹，图画所绘的人物，怎能超过你！我李陵虽然无能和胆怯，假如汉廷姑且宽恕我的罪过，不杀我的老母，使我能实现在奇耻大辱下积蓄已久的志愿，这就同曹沫在柯邑订盟可能差不多，这是以前所一直不能忘记的！逮捕杀戮我的全家，成为当世的奇耻大辱，我还再顾念什么呢？算了吧，让你了解我的心罢了！我已成异国之人，这一别就永远隔绝了！”李陵起舞，唱道：“走过万里行程啊穿过了沙漠，为君王带兵啊奋战匈奴。归路断绝啊刀箭毁坏，兵士们全部死亡啊我的名声已败坏。老母已死，虽想报恩何处归！” 　　李陵泪下纵横，于是同苏武永别。单于召集苏武的部下，除了以前已经投降和死亡的，总共跟随苏武回来的有九人。苏武于汉昭帝始元六年（前81年）春回到长安。昭帝下令叫苏武带一份祭品去拜谒武帝的陵墓和祠庙。任命苏武做典属国，俸禄中二千石；赐钱二百万，官田二顷，住宅一处。常惠、徐圣、赵终根都任命为皇帝的侍卫官，赐给丝绸各二百匹。其余六人，年纪大了，回家，赐钱每人十万，终身免除徭役。常惠后来做到右将军，封为列侯，他自己也有传记。苏武被扣在匈奴共十九年，当初壮年出使，等到回来，胡须头发全都白了。 ▲', poem_appreciation = '1.本文在写作上有什么特点？\n\n　　首先，以典型环境和细节描写表现人物。苏武留胡十九年，经历坎坷曲折，汉与匈奴的关系错综复杂。作者抓住苏武经历中的关键之处，运用典型环境和细节描写，使苏武这个人物跃然纸上。苏武出使匈奴，因突发事变，被扣幽禁。在他的周围，有操生杀予夺之权的单于和卫律的屠刀，有贪生怕死的副使张胜的屈降，有曾为同事、朋友的李陵的声泪俱下的劝降。而冰天雪地廪食不至的北海牧羊，苏武更是被置之死地。这些典型环境，把苏武这个人物推到了矛盾斗争的风口浪尖上，让人物一展风采。作者又通过一些细节描写，表现了苏武不屈的民族气节。如写苏武的两次自杀，第一次被“胜、惠共止之”；第二次又被救活。又如写苏武被幽禁在大窖中，“卧啮雪，与旃毛并咽之”；流放北海，“掘野鼠去草实而食之。杖汉节牧羊，卧起操持，节旄尽落”等。苏武的语言也具有典型意义。如卫律逼降时，说：“副有罪，当相坐。”苏武斥责说：“本无谋，又非亲属，何谓相坐？”使卫律哑口无言，只得无耻地“举剑拟之”，但苏武岿然不动。又如，李陵劝降，苏武仍然不为其情所动，表示“虽蒙斧钺汤镬，诚甘乐之”，表现出至死不屈的品德。\n\n　　其次，为了突出表现苏武的民族气节，文中着重写了三个叛徒，与苏武形成鲜明对比：一个是副使张胜，一个是为虎作伥的卫律，一个是曾为朋友的李陵。他们都在匈奴的威势面前丧失了民族气节，拜倒在敌人脚下。唯独苏武大义凛然，为了民族尊严和汉王朝的利益，宁死不屈。作者为我们塑造了一个丰满的、动人的、高大的民族英雄形象。\n\n　　2.苏武在被囚禁流放以前两度要自杀，后来又想方设法要活下去。这是否矛盾？\n\n　　并不矛盾。苏武在胡地以维护国家民族尊严作为自己的崇高使命和行为准则。我们不难明白，匈奴对苏武等人的劝降实际上是匈奴与汉朝的一次对峙，关乎国家尊严、民族气节。事发时他已经意识到“事如此，此必及我，见犯乃死，重负国”。“重负国”是因为事先没有发现副使张胜的阴谋而导致祸及国家，苏武意识到，一旦被匈奴审讯，就会给国家带来羞辱，所以要自杀以避免受审。后来，在审讯时被卫律威逼利诱，他在说完一番大义凛然的话后引刀自刺，一是以行动表示坚决不投降的决心，二是要为国家雪耻。匈奴明白了苏武的决心，知道威权、富贵无法征服他，便要以摧毁苏武肉体的方式来征服其意志。所以苏武采取的反抗方式也由以前的求死而变成以后的求生，他要在各种艰难困苦中坚强地活下去，但活的前提与支柱依然是汉朝使者的身份，所以他“杖汉节牧羊，卧起操持”。从全文看来，苏武将生死全然置之度外，一心考虑的是汉朝的荣誉与利益，所以在局势变化的情况下，他的对抗方式也在发生着变化。', poem_tags = '高中文言文,传记,赞美,写人' WHERE poem_title = '苏武传(节选)' AND poem_author = '班固';
UPDATE edu_poem SET poem_translation = '杨柳丝丝风中摆弄轻柔，烟缕迷漾织进万千春愁。海棠尚未经细雨湿润，梨花却已盛开似雪，真可惜春天已过去一半。\n而今往事实在难以重忆，梦魂归绕你住过的闺楼。刻骨的相思如今只在，那芬芳的丁香枝上，那美丽的豆蔻梢头。', poem_notes = '眼儿媚：词牌名，又名《秋波媚》。双调四十八字，前片三平韵，后片两平韵。\n弄轻柔：摆弄着柔软的柳丝。秦观《江城子》：“西城杨柳弄春柔。”\n海棠三句：指春分时节。海棠常经雨开花，梨花开时似雪，故云。\n难重省：难以回忆。省（xǐng）：明白、记忆。\n秦楼：秦穆公女弄玉与其夫萧史所居之楼。此指王雱妻独居之所。\n丁香：常绿乔木，春开紫或白花，可作香料。\n豆蔻：草本植物，春日开花。', poem_appreciation = '“杨柳丝丝弄轻柔，烟缕织成愁。”上片第一句“杨柳丝丝弄轻柔”，柳条细而长，可见季节是在仲春。“弄轻柔”字写杨柳在春风中轻摇的柔美，分外点出垂柳初萌时的细软轻盈、盎然春意。以“烟缕”来形容轻柔的杨柳，大概是由于四月的时候，垂柳的顶端远远望去，宛如一抹浅绿的烟云。杨柳如烟这个比喻并不新鲜，但“烟缕织成愁”，则出语新奇，耐人寻味。如烟的垂柳和心中的愁思并没有直接的关系，却用一个“织”字将二者绾合，仿佛杨柳能通晓人性。“愁”字的出现．为整首词披上淡淡哀愁的羽衣。然而这忧伤从何而来，词人并未解释。只是在写完垂柳之后，他将笔触转向春日的另两种花朵：海棠与梨花。\n\n　　“海棠未雨，梨花先雪，一半春休。”“雨”“雪”都是名词活用作动词，这句的意思是说，海棠的花瓣还未像雨点般坠，。梨花的白色花瓣已经如雪花般纷纷飘落。由此知道，原来春天已经过去一半了。在韶华易逝的感喟中，词人不禁触目生愁。\n\n　　“而今往事难重省，归梦绕秦楼。”原来有一段值得留恋、值得追怀的往事。但是年光不能倒流，历史无法重演，旧地又不能再到，则只有凭借回归的魂梦，围绕于女子所居的值得怀念的地方了。\n\n　　“相思只在：丁香枝上，豆蔻梢头。”词人的相思之情，只有借丁香和豆蔻才能充分表达。这分明就是在感叹自己心底的深情正像丁香一般忧郁而未吐，但又是非常希望能和自己心爱的人像豆蔻一般共结连理。整个下片的意思是说，尽管一切的梦幻都已失落，然而自己内心缠绵不断的情意依然专注在那个可人身上，真是到了“春蚕到死丝方尽”的境界。', poem_tags = '宋词三百首,宋词精选,婉约,写景,怀旧,感伤' WHERE poem_title = '眼儿媚·杨柳丝丝弄轻柔' AND poem_author = '王雱';
UPDATE edu_poem SET poem_translation = '时近年终冰霜渐渐减少，春回大地草木最先知晓。\n眼前只觉一片生机盎然，东风吹来水面绿波荡摇。', poem_notes = '立春：阳气回苏的开头，也是一年的最后月份。代表着春季的开始。偶成，即偶有所感而成。\n律回：即大地回春的意思。黄帝命伶伦断竹为筒（后人也用金属管），以定音和候十二月之气。阳六为律，即黄钟、太簇、姑洗、蕤宾、夷则、无射；阴六为吕，即大吕、夹钟、仲吕、林钟、南吕、应钟。农历十二月属吕，正月属律，立春往往在十二月与一月之交，所以曰“律回”。从节气上说，立春即是一年之始，但在历算上，立春之日可能赶在上一年的腊月下旬，即在上一年未尽之时，新一年的春天就已经来到了。古人认为律属阳气，吕属阴气，各代表一年的六个月，律回阴往即言立春。\n岁（suì）晚：年终。\n草木：泛指一切能受到季节变化影响的事物，如动植物、水、山等等。\n生意：生机、生气。\n满：遍布，充满。\n参（cēn）差（cī）：高低不齐。形容水面波纹起伏的样子。', poem_tags = '古诗三百首,春天' WHERE poem_title = '立春偶成' AND poem_author = '张栻';
UPDATE edu_poem SET poem_tags = '菊花,思乡' WHERE poem_title = '醉花阴·黄花谩说年年好' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '新月弯弯如眉毛，没有圆的意思。不忍心看红豆，满眼都是相思泪。\n整天劈核桃，那人像桃仁嵌在核壳中一样嵌在我心中。两朵隔墙相望的花，早晚会结成连理枝。', poem_notes = '生查子（zhā zǐ）：原为唐教坊曲名，后用为词牌名。《尊前集》注：双调。元高拭词注：南吕宫。四十字，上下片格式相同，各两仄韵，上去通押。\n新月：阴历月初的月亮。\n团圞（luán）：团圆。\n红豆：又名相思豆，草本植物，种子形如豌豆。\n劈：剖开。桃穰（ráng）：桃核。\n仁儿：桃仁。这里“仁”与“人”谐音，意思双关。\n连理：不同根的草木，它们的枝干连成为一体。古人喻夫妇为“连理枝”。', poem_appreciation = '上阕以“传情入景”之笔，抒发男女间的相思之苦。作者借“移情”笔法，赋予视野中的客观景象以强烈的主观情感，使天边新月、枝上红豆都染上别离相思的情愫。“新月曲如眉，未有团圞意”，明为写月，实则喻人，作者以眉比月，正暗示出相思人儿因不见团聚而双眉紧蹙，郁闷不欢的愁苦之态。“红豆”本是相思的信物，但在离人的眼里却是贮满了忧伤，令人见之落泪。一弯新月，数枝红豆，词人撷取传统的寄寓人间悲欢离合、别离思念之情的两种意象，正表达出对爱人的无限深情和思之不得的痛切缺憾。\n\n　　就内容而言，下阕为上阕之顺延；就感情的“走向”而言，二者又有着微妙的差异。如果说上阕中写相思还只是借助于意象的寄托，情感的附着还比较虚幻，词中的情绪基调也是一种充满残缺感的低沉．那么下阕中的情感就相对地落到了实处，词中流露着的、是充满希冀的向上的基凋。“终日劈桃穰，人在心儿里”，一语双关，看似百无聊赖的行为，正寄托着主人公对心上人丝丝缕缕的情爱和日复一日的期盼。“两朵隔墙花，早晚成连理”更表明对爱情的充满信心，尽管花阡两朵，一“墙”相隔，但相爱的人儿终将冲破阻碍，喜结连理。整首词写得情致深长，淋漓沉至。\n\n　　这首词在艺术上的一个显著特色，就是极其自然地运用了南北朝民歌中的吴歌“子夜体”，以下句释上句，托物抒情，论词家评曰：“妍词妙喻，深得六朝短歌遗意。五代词中希见之品。”', poem_tags = '宋词三百首,乐府,民歌,月亮,思念,爱情' WHERE poem_title = '生查子·新月曲如眉' AND poem_author = '牛希济';
UPDATE edu_poem SET poem_translation = '韵译\n长安的殿阁内弥漫着一片烟霞，杨广还想把芜城作为帝王之家。\n如果不是李渊得到传国的玉玺，那么他的龙舟还会游遍到天涯。\n如今隋朝的宫苑中已不见萤虫，只有低垂的杨柳和归巢的乌鸦。\n如果杨广在地下和陈后主相遇，有心欣赏淫逸辱国的后庭花吗？\n散译\n长安的殿阁千门闲闭，空自笼罩着一片烟霞，又想在繁丽的江都，把宫苑修建得更加豪华。\n若不是皇帝的玉印归到了李家；隋炀帝的锦帆或许会游遍天涯。\n当年放萤的场所只剩下腐草，萤火早就断绝了根芽；多少年来隋堤寂寞凄冷，两边的垂杨栖息着归巢乌鸦。\n他若是在地下与陈后主重逢，难道能再去赏一曲《后庭花》', poem_notes = '隋宫：指隋炀帝杨广在江都（今江苏扬州市）所建的行宫。\n紫泉：即紫渊，长安河名，因唐高祖名李渊，为避讳而改。司马相如《上林赋》描写皇帝的上林苑“丹水亘其南，紫渊径其北”。此用紫泉宫殿代指隋朝京都长安的宫殿。锁烟霞：空有烟云缭绕。\n芜城：即广陵（今扬州）。帝家，帝都。\n玉玺（xǐ）：皇帝的玉印。日角：额角突出，古人以为此乃帝王之相。此处指唐高祖李渊。\n锦帆：隋炀帝所乘的龙舟，其帆用华丽的宫锦制成。\n腐草无萤火：古人以为萤火虫是腐草变化出来的。\n垂杨：隋炀帝自板诸引河达于淮，河畔筑御道，树以柳，名曰隋堤，一千三百里。\n陈后主：南朝陈末代皇帝陈叔宝，荒淫亡国之君。后庭花：即《玉树后庭花》，陈后主所创，歌词绮艳。', poem_tags = '唐诗三百首,咏史,讽刺' WHERE poem_title = '隋宫' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '我的丈夫真威猛，真是邦国的英雄。我的丈夫执长殳，做了君王的前锋。\n自从丈夫东行后，头发散乱像飞蓬。膏脂哪样还缺少？为谁修饰我颜容！\n天要下雨就下雨，却出太阳亮灿灿。一心想着我丈夫，想得头痛也心甘。\n哪儿去找忘忧草？种它就在屋北面。一心想着我丈夫，使我伤心病恹恹。', poem_notes = '伯：兄弟姐妹中年长者称伯，此处系指其丈夫。朅（qiè）：英武高大。\n桀：同“杰”。\n殳（shū）：古兵器，杖类。长丈二无刃。\n膏沐：妇女润发的油脂。\n适（dí）：悦。\n杲（gǎo）：明亮的样子。\n谖（xuān）草：萱草，忘忧草，俗称黄花菜。\n背：屋子北面。\n痗（mèi）：忧思成病。', poem_appreciation = '战争会破坏很多东西，而它首先破坏的是军人自身的家庭生活。军人尚未走到战场，他们的妻子已经被抛置在孤独与恐惧中了。她们的怀念不是一般的怀念，那永远是充满不安和忧虑的。等待出征的丈夫回来，几乎成为她们生活中唯一有意义的内容。\n\n　　然而战争又总是不可避免的。不管一场正在进行的战争其必要性如何、能否被评判为“正义”，从事这场战争的群体和它的领导者，总是要勉励群体中的成员为之付出最大的努力、最大的牺牲。国家给军人以荣誉，使他们认为自己付出的努力和牺牲是值得的；这荣誉也会影响他们的家人——尤其是妻子，使她们认为家庭生活的破坏以及自身的痛苦都是有价值有意义的。因此，写妻子怀念从军的丈夫的诗篇，通常会包含两方面的内容：为丈夫而骄傲——这骄傲来自国家、来自群体的奖勉；思念丈夫并为之担忧——这种情绪来自个人的内心。《卫风·伯兮》就是典型的这种诗篇。\n\n　　诗一开篇，写一个女子用自豪的口吻在描述她的丈夫。“伯”本是兄弟间排行的第一位，也就是老大，这里转用为妻子对丈夫的称呼，口气中带着亲切感。这位丈夫值得骄傲的地方在于：一则他长得英武伟岸，是一国中的豪杰，同时也因为他非常勇敢，充当了君王的先锋（由此看“伯”身份，当是贵族阶层中的武士）。而骄傲的来源，主要恐怕是在后一点上。假如“伯”虽然长得高大英武，在战争发生时却畏缩不前，妻子就没什么可以公然夸耀的了。——其实，一般人所知道的光荣，也就是社会所认定的光荣，个人在这方面是没有多少独立判断的能力的。\n\n　　转入第二章，写自从丈夫出征，妻子在家就不再打扮自己了，任由头发——女性身体最富装饰性的部分——零乱得像一蓬草。这是以对女性的美丽的暂时性的毁坏，表明她对异性的封闭，也即表明她对丈夫的忠贞。不过，作为军人的妻子，这种举动还有进一步的意味。在古代，妇女是不能上战场的，因此妻子对从军的丈夫的忠贞，实也是间接表现了对于国家的忠贞——这就不仅是个人行为，也是群体——国家的要求。假定一个军人在前方冒着生命危险打仗，他的妻子却在后方整天打扮得花枝招展，走东家串西家，哪怕并无不轨之举，他也不能够安心。这不仅对于家庭是危险的，对于国家也有极大的不利。所以，社会尤其需要鼓励军人的妻子对其丈夫表现彻底的忠贞。此诗不管是出于什么人之手（它可能是一位妇女的自述，也可能是他人的拟写），这样写才是符合上述要求的。后来杜甫的《新婚别》写一位新娘对从军的丈夫表示“罗襦不复施”，还要“当君洗红妆”，好让他安心上战场，与此篇可谓一脉相承。\n\n　　然而，尽管诗中的女主人公算得上“深明大义”，她对自己的丈夫能“为王前驱”很感骄傲，但久久的盼待一次次落空仍然给她带来巨大的痛苦。对于古代妇女来说，生活的全部内容、幸福的唯一来源就是家庭；家庭被破坏了，她们的人生也就被彻底破坏了。而等待从军的丈夫，这与一般的别离相思是不同的——其背后有很深的忧惧。潘岳《寡妇赋》用此诗为典故，有云：“彼诗人之攸叹兮，徒愿言而心疼……荣华晔其始茂兮，良人忽已指背。”正是揭示了诗中未从正面写出，而又确实隐藏在字面之下的恐怕丈夫最终不能归来的忧惧。这一点是理解第三、四两章所描写的女主人公的期待、失望与难以排遣的痛苦之情的基础。她甚至希望自己能够“忘忧”，因为这“忧”已经使她不堪负担了。\n\n　　诗必须有真实的感情，否则不能打动人；但诗人的感情也并非可以尽情抒发的，它常常受到社会观念的制约。拿《卫风·伯兮》来说，如果一味写那位妻子为丈夫的报效国家而自豪，那会让人觉得不自然——至少是不近人情；反过来，如果一味写妻子对丈夫的盼待，乃至发展到对战争的厌恶（这在事实上绝非不可能），却又不符合当时社会的要求。所以最后它成为这个样子：对亲人的强烈感情经过责任感的梳理而变得柔婉，有很深的痛苦与哀愁，但并没有激烈的怨愤。\n\n　　在艺术构思上，全诗采用赋法，边叙事，边抒情。紧扣一个“思”字，思妇先由夸夫转而引起思夫，又由思夫而无心梳妆到因思夫而头痛，进而再由头痛到因思夫而患了心病，从而呈现 出一种抑扬顿挫的跌宕之势。描述步步细致，感情层层加深，情节层层推展，主人公的内心冲突以及冲突的辗转递升，既脉络清晰，又符合人物的心理逻辑，使人物形象具有饱满的精神内涵。同时，诗情奇崛不平，充满辩证色彩。', poem_tags = '诗经,闺怨' WHERE poem_title = '国风·卫风·伯兮' AND poem_author = '佚名';
UPDATE edu_poem SET poem_tags = '追忆,抒情,壮志未酬' WHERE poem_title = '自题金山画像' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '人在溪边行走溪水映照出人影，蓝天倒映在清清的溪水里。蓝天上有飘动的白云，人正行走在那飘动的白云里。\n我放声高歌，谁来应和？只听空幽的山谷清音响起。那响声不是来自鬼怪神仙，而是桃花旁的流水声悦耳无比。', poem_notes = '雨岩：在江西永丰县西南博山附近，岩中有泉水飞出，如风雨之声。\n行云：云彩流动。\n和（hè）：跟着唱\n余：我\n空谷：深谷。《诗经·小雅·白驹》：“皎皎白驹，在彼空谷。”\n清音：指空谷中潺潺的流水声。《淮南子·兵略训》：“夫景不为曲物直，响不为清音浊。”晋·左思《招隐》：“未必丝与竹，山水有清音。”\n非鬼亦非仙：苏轼《夜泛西湖五绝》：“湖光非鬼亦非仙，风恬浪静光满川。”\n一曲：一湾。\n桃花水：即桃花汛。农历二三月桃花盛开时节，冰化雨积，黄河等处水猛涨，称为桃花汛。《汉书·沟洫志》：“如使不及今冬成，来春桃华水盛，必羡溢，有填淤反壤之害。”注云：“盖桃方华时，既有雨水，川谷冰泮，众流猥集，玻澜盛长，故谓之桃华水耳。”《水衡记》：“黄河二月三月水，名桃花水。”唐·杜甫《南征》诗：“春岸桃花水，云帆枫树林。”', poem_appreciation = '上片写词人游览雨岩见到的景色。第一句“溪边照影行”，是点题，写游人；第二句“天在清溪底”，写清溪和蓝天；第三句“天上有行云”，写行云；第四句“人在行云里”如同电影中的定格，总写溪、人、云，展示了水底的一个画面。作者在这里所描写的人、天、云都不是实体，而是水中的倒影。清清的溪水，不但是雨岩的优美景色之一，而且也成了词人摄取这张风景小照的胶卷。游人的身影、碧蓝的天空、飘动的浮云，都通过清清的溪水映现出来。“人在行云里”这样神奇美妙的景象，真可谓巧夺天工，不但使描写的景物高度集中，而且意境更为清新活泼，整个画面非常生动，所描写的景物，全部处在变化之中，溪水自然是流动的，游人漫步岸边——“影行”，白云飘转空中——“行云”，这就使画面充满了动感，给人以身临其境的感觉。\n\n　　如果说上片的写景，重在刻画形象的话，那么这个下片的抒情，则是着力描绘声音。哗哗的流水，飘荡的歌声，不仅使寂静的山谷增添了生气，也为上面的图画配上了音乐。\n\n　　清人沈祥龙《论词随笔》说：“词贵藏于内……于言外有所感触。”蓦然读去，这首词意境优美，静中有动的图画，配着富于形象的歌声与音乐，平易通俗、流畅自然的语言，也令人赞叹不绝。但仔细咀嚼，就会发现：作者把辛酸的感触，藏在迷人的画面背后；把满心的苦闷，融于优美的乐律之中。题目中的“独”字，已经为全词规定了基调，透露出苦闷的气息。下面的内容，自然全都围绕“独”字展开，所以起拍第一句就是“溪边照影行”。这一画面里，只有一个倒映在水中的人影，点出了“独游”，而比“独游”更深刻，因为它渲染出一种悲凉的气氛。\n\n　　在这特定的氛围里，那清清的溪水，蔚蓝的天空，飘动的白云，这些美好的景物，也染上了凄凉冷清的色彩，成为词人表达孤独之感的衬景。“人在行云里”，不止是倒影交织的画面，也写出了词人不苟随世俗的决心和孤傲清高的品格，暗写了自己遭受打击的原因。内心澎湃的激情和遭受压抑的苦闷，终究是掩遮不住的，“高歌”正是词人内心感情的流露和发泄。然而，并没有人能理解他，与他相和的，只是空谷里的溪水。词人的“独”唱，同哗哗的水声，从声音方面渲染了凄凉忧伤的气氛。这种“高山流水少知音”的感慨，是他内心苦闷的表现；而这种“曲高和寡”的情景，正是他收复中原的主张不能得到采纳的写照。那幽深寂静的山谷，那溪水漂浮的残花，不能不说带有象征意义。所以，这首词表面上是记游，描写水光山色，实际上处处贯注着词人愤激的感情，表现了词人遭受排挤、闲居家乡、有志难伸的苦闷和寂寞，也反映了他对时局的不满和对国事的关心。他热爱大自然的风光，又不忘怀于世事，正表现了词人退居时期的内心矛盾，说明他并没有因自然风光的优美而陶醉、而颓废。\n\n　　这首词通过记叙独游雨岩的情景，抒发了遭受打击、闲居乡里的苦闷，反映了作者内心的不平和对国事的系念。同时，这首词构思新颖，剪裁精妙。题为“独游雨岩”，作者就在“独”字上作文章，上片写“形”独，下片写“声”独。随即带出了雨岩的优美景色，如清溪、蓝天、行云、山谷等。寓情于景，情景交融，意境清新自然而又沉郁，景愈美，愈可反衬出词人的不平与愤懑。语言通俗流畅，以虚写实，虚实结合，高度集中。所有这些都显示出了这首词的高度艺术性。王国维《人间词话》称：“幼安之佳处，在有性情，有境界。”于此可见。\n\n　　清代乾嘉时期岭南的著名诗人和画家黎简，有诗云：“七十二峰倒江水，俯见峰尖插天底；一舟天上棹海松，回合三万寒虬龙。”其构思与辛词同，可见辛词影响之远。', poem_tags = '山水,孤独,壮志难酬' WHERE poem_title = '生查子·独游雨岩' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '一年中看到梅花，于是作诗追和，始终遗憾有儿女似的忸怩情态。\n竹林里的一枝梅花经过雨水的冲洗显得柔美可人，亭亭静立。让人怀疑这是美人在傍晚时绰约的身影。\n心中出现的遗憾有谁知道呢，往事不堪回首啊。眠梦绕着小平台游走，回来后只有寂寞作陪，此时沾在袖子上梅花的余香已经冷淡了。', poem_notes = '娟娟:姿态柔美貌。', poem_tags = '写花,梅花,抒情,寂寞' WHERE poem_title = '卜算子·竹里一枝梅' AND poem_author = '向子諲';
UPDATE edu_poem SET poem_tags = '孤独,感伤' WHERE poem_title = '蝶恋花·雨霰疏疏经泼火' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '前，楚襄王和宋玉游览云梦台，远望高唐观，高唐观上云气特异，状如峰峦，升腾直上，忽然又改变形状，顷刻之间，千变万化。襄王问宋玉：“这是什么云气呀？”宋玉回答：“这就是所说的朝云。”襄王又问：“什么是朝云？”宋玉回答：“从前先王曾经游览高唐观，感到困倦，白天就睡着了，梦见一个女子，说：‘我是巫山之女，高唐之客，听说大王游览高唐观，愿为你侍寝。’先王于是和她同寝，离开时告辞说：‘我住在巫山南面险峻的高山，早上化作灿烂的云霞，傍晚变成霏微的烟雨。朝朝暮暮，就生活在阳台之下。’先王早上起来观看，果真象她说的那样，所以给她修建庙宇，封号为朝云。”襄王问：“朝云刚出现时，是怎样的情景？”宋玉回答说：“她刚出现的时候，宛若茂盛挺拔的青松，稍微过了一会，现出亮丽婀娜的姿容，扬起长袖，遮住眩目的阳光，凝神伫望，若有所思。忽然又变幻了模样，驾着驷马之车疾驰，车上插着饰有羽毛的旌旗，凉风习习，细雨清凄，等到风住雨停，云清雾散，无处可寻。”襄王问：“我现在可以游赏一番吗？”宋玉说：“行啊。”襄王问：“那里的情形如何？”宋玉说：“那里高峻而广阔，登临眺望，极目辽远。宽广无边，好象万物都从那里生出。上接青天，下临深渊，珍贵怪异，奇特伟岸，简直难以用语言来描述。”襄王说：“你试着为我说说看。”宋玉说：“是”。\n\n　　那高唐的概貌，绝对无物可比。莽莽巫山，何以匹敌。道路错综曲折，重叠层递。登上峭岩下望，长坡潭水蓄积。正遇雨后初晴，远观百川汇聚，波涛汹涌，无声无息。川水交流，水满四溢。集水成潭，水深无底。大风扬波，有如山间高突的田地。大浪拍岸，险隘之处回旋撞击。怒涛奔涌，有如航海望见碣石耸峙。巨响震天，水波撞击累累的山石。巨石沉没水中，大浪高高掀起。水波荡漾，旋转盘曲。大水远流，腾起阵阵雾气。奔涌翻滚，声响入云相激。猛兽拼命远逃，惊骇至极。虎豹豺兕，惊恐万状，全无往日气势；雕鹗鹰鹞，高飞低窜，屏气颤抖，怎敢如往日搏击？于是水族受惊，都浮上水面，到小洲北边躲避；鼋鼍鳣鲔，东歪西斜，纵横交积，张鳞奋翼，游动拥挤。\n\n　　站在高坡遥望，冬天的树木依然郁郁苍苍。光彩鲜明，夺人目光。难以言表，烂若群星排列天上。榛林茂盛，重叠的花美丽芬芳。成对的山桐累累，枝叶交错展扬。轻风吹拂，倒影隐约，随波飘荡。伸展的枝条繁茂柔美，就象鸟儿张开翅膀。红茎白蒂，碧绿的叶子中露出紫红的花房。微风吹动，纤枝悲鸣，就像竽籁奏出的乐章。清浊相和，五音变化，应和着四方的音响。闻之动心，荡气回肠。孤儿寡妇，落泪心伤。长官废职，贤士失意惆怅，愁思无尽，叹息流泪彷徨。\n\n　　登高远望，使人心伤。盘岸峭壁，整齐排列，巍峨挺拔。磐石险峻，倾斜着像要倒塌。山岩长短纵横，仿佛追逐着一比高下。角落里堵塞道路的岩石横卧，偏僻处洞穴在山岩高挂。山石堆积交加，重重叠叠更是高大。形如中流砥柱，屹立巫山之下。仰望山顶，山林清静浓绿，耀眼如虹霓光华。俯看山下，幽深无底是峥嵘的山崖。只听见松涛阵阵，洋洋大水好象要把江岸冲垮。野熊吓得要死，直立起来往树上攀爬，久久不敢离开，脚心汗水滴下。悠悠忽忽，失意伤感，令人惊心，无故惧怕。既使有孟贲、夏育的决断，要显示勇敢也是无法。突遇不知从何而来的怪物，叫人又惊又怕。怪石林立，形态各异，有如鬼神变化。有的象奔跑的野兽，有的像禽鸟飞上飞下。变幻莫测，奇特瑰伟，不能一一陈叙描画。\n\n　　登上高唐观的旁边，地势一遍平坦。连绵不绝，如簸箕的后半。芬芳的香草，遍地长满。秋兰、茝蕙和江离，鲜花盛开。青荃、射干和揭车，争奇斗妍。草木蘩茂，艳丽绵延。群鸟鸣唱，在花草的芳香里远传。雌雄失伴，鸣声哀婉。王雎、黄鹂、正冥、楚鸠、子规、思妇和垂鸡，把巢筑得高高，百鸟合鸣，其声宛转。当年遨游，唱和交替更换，鸣声如歌，传向极远。有法术的方士，羡门、高溪、上成、郁林等神仙，在山林间兴高采烈地聚餐。\n\n　　祈祷在玉饰的宫室，供奉纯一色的牺牲，祭祀众多的神灵，向东皇太一礼敬。祝辞已经备好，祷告已经完成。君王才乘着玉舆，驾着青色的蛟龙飞奔。配合协调的旗帜飘飘，那是表示王者身份的旒旌。拨动琴弦，奏出典雅的乐声。寒风吹拂，更添悲哀一层。于是依调而歌，令人悲痛凄惨，屏息伤心。于是就让猎手纵马驰骋，山下人马排列，密如天上繁星。传令羽林骑士，口衔枚，不出声，弓箭不发射，猎网不张挂，在大水中跋涉，在草丛里驰骋。群鸟来不及起飞，野兽来不及逃命。马蹄溅满鲜血，车马片刻暂停。那先获头功的猎手，猎物已装满车乘。\n\n　　大王您想去见巫山之女，必先斋戒沐浴。选择吉日良时，减少车骑，穿上黑衣。车上树起霓旌和云旗，车盖用翠鸟的羽毛装饰。恍如风起雨止，千里转瞬即逝。为了启发蒙昧，前去相会神女。想着天下百姓，为国家祸患忧思。任用贤能之臣，弥补自己过失。九窍通泰，精神舒畅，寿与天齐。▲', poem_tags = '辞赋精选,爱情,神话' WHERE poem_title = '高唐赋' AND poem_author = '宋玉';
UPDATE edu_poem SET poem_tags = '写山' WHERE poem_title = '望岳三首·其三' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '风儿整天价猛吹又多狂暴，他有时冲我回头只笑一笑，全是调戏放荡嘲讽又慢傲，让我心内深感悲伤更寂寥。\n风儿整日价狂吹呀雨雾罩，他是否愿意痛快回家来哟？这个负心人不来也不往啊，让我空思念呀悠悠又遥遥。\n风儿整日价吹呀天色阴沉，前天阴沉沉没几天又发昏。一梦醒来就再也难以入睡，为你我伤风感冒思念殷勤。\n风凄凄呀天昏地暗阴沉沉，雷声远远地传来约约隐隐。梦乡醒来就再也难以入睡，我总是不能排谴倍感伤心。', poem_notes = '终：一说终日，一说既。暴：急骤，猛烈。\n谑（xuè）浪笑敖：戏谑：谑，调戏。浪，放荡。敖，放纵。\n中心：心中。是悼：悼是。悼，伤心害怕。\n霾（mái）：阴霾。空气中悬浮着的大量烟尘所形成的混浊现象。\n惠：顺。\n莫往莫来：不往来。\n曀（yì）：阴云密布有风。\n不日：不见太阳。有，同“又”。\n寤：醒着。言：助词。寐：睡着。\n嚏（tì）：打喷嚏。民间有“打喷嚏，有人想”的谚语。\n曀曀：天阴暗貌。\n虺（huǐ）：形容雷声。\n怀：思念。', poem_appreciation = '此诗共四章。以女子的口吻，写她因丈夫的肆意调戏而悲凄，但丈夫离开后，她又转恨为念，忧其不来；夜深难寐，希望丈夫悔悟能同样也想念她。其感情一转再转，把那种既恨又恋，既知无望又难以割舍的矛盾心理真实地传达出来了。\n\n　　第一章写欢娱，是从男女双方来写。“谑浪笑敖”，《鲁诗》曰：“谑，戏谑也。浪，意萌也。笑，心乐也。敖，意舒也。”连用四个动词来摹写男方的纵情粗暴，立意于当时的欢娱。“中心是悼”，悼，担心忧惧的意思，是女方担心将来的被弃，着意于将来的忧惧。\n\n　　第二章承“悼”来写女子被弃后的心情。“惠然肯来”，疑惑语气中不无女子的盼望；“莫往莫来”，肯定回答中尽是女子的绝望。“悠悠我思”转出二层情思，在结构上也转出下面二章。\n\n　　第三、四章表现“思”的程度之深。“寤言不寐”，是直接来写，“愿言则嚏”、“愿言则怀”则是女子设想男子是否想她，是曲折来写。而归结到男子，又与第一章写男子欢娱照应。全诗结构自然而有法度。\n\n　　诗各章都采用“比”的表现手法。因比而兴，诗中展示出狂风疾走、尘土飞扬、日月无光、雷声隐隐等悚人心悸的画面，衬托出女主人公悲惨的命运，有强烈的艺术震撼力。这在古代爱情婚姻题材的诗歌中是别具一格的。', poem_tags = '诗经,闺怨,民谣' WHERE poem_title = '终风' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '落叶飘零是深知宋玉的悲哀，他的风流儒雅堪当我的老师。\n怅望千秋往事洒下同情泪水，身世同样凄凉可惜生不同时。\n江山依旧故宅犹在空留文藻，云雨荒台难道真是荒唐梦思。\n最可叹楚王宫殿早荡然无存，驾船人还指点遗迹让人生疑。', poem_notes = '摇落：凋残，零落。\n风流儒雅：指宋玉文采华丽潇洒，学养深厚渊博。\n“萧条”句：意谓自己虽与宋玉隔开几代，萧条之感却是相同。\n故宅：江陵和归州 （秭归） 均有宋玉宅，此指秭归之宅。空文藻：斯人已去，只有诗赋留传下来。\n云雨荒台：宋玉在《高唐赋》中述楚之“先王”游高唐，梦一妇人，自称巫山之女，临别时说：“妾在巫山之阳，高丘之岨，旦为行云，暮为行雨，朝朝暮暮，阳台之下。”阳台，山名，在今重庆市巫山县。\n“最是”两句：意谓最感慨的是，楚宫今已泯灭，因后世一直流传这个故事，至今船只经过时，舟人还带疑似的口吻指点着这些古迹。楚宫：楚王宫。', poem_appreciation = '第二首是推崇楚国著名辞赋作家宋玉的诗。诗是作者亲临实地凭吊后写成的，因而体会深切，议论精辟，发人深省。诗中的草木摇落，景物萧条，江山云雨，故宅荒台，舟人指点的情景，都是诗人触景生情，所抒发出来的感慨。它把历史陈迹和诗人哀伤交融在一起，深刻地表现了主题。诗人瞻仰宋玉旧宅怀念宋玉，从而联想到自己的身世，诗中表现了诗人对宋玉的崇拜，并为宋玉死后被人曲解而鸣不平。全诗铸词溶典，精警切实。有人认为，杜甫之“怀宋玉，所以悼屈原；悼屈原者，所以自悼也”。这种说法自有见地。\n\n　　宋玉的《高唐赋》、《神女赋》写楚襄王和巫山神女梦中欢会故事，因而传为巫山佳话。又相传在江陵有宋玉故宅。所以杜甫暮年出蜀，过巫峡，至江陵，不禁怀念楚国这位作家，勾起身世遭遇的同情和悲慨。在杜甫看来，宋玉既是词人，更是志士。而他生前身后却都只被视为词人，其政治上失志不遇，则遭误解，至于曲解。这是宋玉一生遭遇最可悲哀处，也是杜甫自己一生遭遇最为伤心处。这诗便是诗人瞩目江山，怅望古迹，吊宋玉，抒己怀；以千古知音写不遇之悲，体验深切；于精警议论见山光天色，艺术独到。\n\n　　杜甫到江陵的时候是秋天。宋玉名篇《九辩》正以悲秋发端：“悲哉秋之为气也，萧瑟兮草木摇落而变衰。”杜甫当时正是产生悲秋之情，因而便借以兴起本诗，简洁而深切地表示对宋玉的了解、同情和尊敬，同时又点出了时节天气。“风流儒雅”是庾信《枯树赋》中形容东晋名士兼志士殷仲文的成语，这里借以强调宋玉主要是一位政治上有抱负的志士。“亦吾师”用的是王逸的说法：“宋玉者，屈原弟子也。闵惜其师忠而被逐，故作《九辩》以述其志。”这里借以表示杜甫自己也可算作师承宋玉，同时表明这首诗旨意也在闵惜宋玉，“以述其志”。所以次联接着就说明诗人自己虽与宋玉相距久远，不同朝代，不同时代，但萧条不遇，惆怅失志，其实相同。因而望其遗迹，想其一生，不禁悲慨落泪。\n\n　　诗的前半感慨宋玉生前怀才不遇，后半则为其身后不平。这片大好江山里，还保存着宋玉故宅，世人总算没有遗忘他。但人们只欣赏他的文采辞藻，并不了解他的志向抱负和创作精神。这不符宋玉本心，也无补于后世，令人惘然，所以用了“空”字。就像眼前这巫山巫峡，使诗人想起宋玉的两篇赋文。赋文的故事题材虽属荒诞梦想，但作家的用意却在讽谏君主淫惑。然而世人只把它看作荒诞梦想，欣赏风流艳事。这更从误解而曲解，使有益作品阉割成荒诞故事，把有志之士歪曲为无谓词人。这一切，使宋玉含屈，令杜甫伤心。而最为叫人痛心的是，随着历史变迁，岁月消逝，楚国早已荡然无存，人们不再关心它的兴亡，也更不了解宋玉的志向抱负和创作精神，以至将曲解当史实，以讹传讹，以讹为是。到如今，江船经过巫山巫峡，船夫们津津有味，指指点点，谈论着哪个山峰荒台是楚王神女欢会处，哪片云雨是神女来临时。词人宋玉不灭，志士宋玉不存，生前不获际遇，身后为人曲解。宋玉悲在此，杜甫悲为此。前人说“言古人不可复作，而文采终能传也”，恰好与杜甫的原意相违背。\n\n　　体验深切，议论精警，耐人寻味，是这诗的突出特点和成就。但这是一首咏怀古迹诗，诗人亲临实地，亲自凭吊古迹，因而山水风光自然在诗中显露出来。杜甫沿江出蜀，飘泊水上，旅居舟中，年老多病，生计窘迫，境况萧条，情绪悲怆，本来无心欣赏风景，只为宋玉遗迹触发了满怀悲慨，才洒泪赋诗。诗中的草木摇落，景物萧条，江山云雨，故宅荒台，以及舟人指点的情景，都从感慨议论中出来，蒙着历史的迷雾，充满诗人的哀伤，诗人仿佛是泪眼看风景，隐约可见，其实是虚写。从诗歌艺术上看，这样的表现手法富有独创性。它紧密围绕主题，显出古迹特征，却不独立予以描写，而使其溶于议论，化为情境，渲染着这首诗的抒情气氛，增强了咏古的特色。\n\n　　这是一首七律，要求谐声律，工对仗。但也由于诗人重在议论，深于思，精于义，伤心为宋玉写照，悲慨抒壮志不酬，因而通篇用赋，在用词和用典上精警切实，不被格律所拘束。它的韵律和谐，对仗工整，写的是律诗这种近体诗，却有古体诗的风味，同时又不失清丽。前人认为这首诗“首二句失粘”，只从形式上进行批评，未必中肯。', poem_tags = '唐诗三百首,怀古,抒怀' WHERE poem_title = '咏怀古迹五首·其二' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '在阁楼中好似春天一般，平常不用的窗子将白昼都隔在了外面，走在画廊里，发现这里非常深幽。篆香烧尽了，日影移上帘箔了，才发现黄昏将近。我喜爱梅花，自己种的江梅渐已长好，为什么一定要再临水登楼赏玩风月而荒废了时光呢。没有人来找我谈话聊天，如今在这样的寂寥环境里独自面对梅花，就好像当年何逊在扬州对花彷徨。\n梅花色泽美艳，它虽不像别的花那么畏惧霜雪，但毕竟娇弱，难以禁受寒风冷雨的摧残。又是谁吹起横笛曲《梅花落》，吹动了我的愁绪。不要怨恨暗香消失，落花似雪，要相信，虽然梅花踪迹难寻而它情意长留。我很难说出我的家世，多想有一个美好的夜晚，淡淡的月光投下梅枝横斜优美的姿影，从这姿影里还能显示出梅花的俊俏风流。', poem_notes = '满庭芳：词牌名。\n篆香：对盘香的喻称。\n江梅：此指梅中上品，非泛指江畔、水边之梅。\n临水登楼：语出王粲《登楼赋》“登兹楼以四望兮，聊暇日以销忧”之句。\n浑似：完全像。\n何逊在扬州：语出杜甫《和裴迪登蜀州东亭送客逢早梅相忆见寄》“东阁官梅动诗兴，还如何逊在扬州”之句。\n韵胜：优雅美好。\n难堪雨藉：难以承受雨打。\n不耐风揉：《乐府雅词》卷下、《梅苑》卷三、《全宋词》第二册均作“不耐风柔”，“柔”字不通，故改。\n横笛：汉横吹曲中有《梅花落》。\n扫迹：语见孔稚珪《北山移文》“乍低枝而扫迹”。原意谓扫除干净，不留痕迹。此处系反其意而用之。', poem_tags = '咏物,梅花,生活,抒情' WHERE poem_title = '满庭芳·小阁藏春' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '拂晓的月亮坠下蓝天，夜空云雾已经微淡，默默无语倚在枕上。梦醒仍恋芳草绵绵，雁声消失遥远天边。\n啼晓的黄莺散，零落的飞花乱，只留下寂寞画堂深深院。任落红遍地休扫它，留待跳舞人回当地毯。', poem_notes = '喜迁莺：词牌名。\n坠：落下。\n微：疏淡。\n欹（qī）：斜倚。\n馀（yú）花：馀即余，残花。\n埽（sào）：扫去。\n尽从伊：这里指全由落花，任凭它飘落一地。', poem_tags = '写景,时光,思念' WHERE poem_title = '喜迁莺·晓月坠' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '太平时闲游有趣却是无能，闲爱天上孤云安静爱山僧。\n我愿手持旌麾去吴兴上任，乐游原上再望望风雨昭陵。', poem_notes = '吴兴：即今浙江省湖州市。乐游原：在长安城南，地势高敞，可以眺望，是当时的游览胜地。\n“清时”句：意谓当这清平无所作为之时，自己所以有此闲情。 \n一麾（huī）：旌旗。\n昭陵：唐太宗的陵墓。', poem_appreciation = '在唐人七绝中，也和在整个古典诗歌中一样，以赋、比二体写成的作品较多，兴而比或全属兴体的较少。杜牧这首诗采用了“托事于物”的兴体写法，表达了作者的爱国之情，称得上是一首“言在此而意在彼”、“言已尽而意有余”的名篇。\n\n　　杜牧不但长于文学，而且具有政治、军事才能，渴望为国家作出贡献。当时他在京城里任吏部员外郎，投闲置散，无法展其抱负，因此请求出守外郡。对于这种被迫无所作为的环境，他当然是很不满意的。诗从安于现实写起，反言见意。武宗、宣宗时期，牛李党争正烈，宦官擅权，中央和藩镇及少数民族政权之间都有战斗，根本算不上“清时”。诗的起句不但称其时为“清时”，而且进一步指出，既然如此，没有才能的自己，倒反而可以借此藏拙，这是很有意趣的。次句承上，点明“闲”与“静”就是上句所指之“味”。而以爱孤云之闲见自己之闲，爱和尚之静见自己之静，这就把闲静之味这样一种抽象的感情形象地显示了出来。\n\n　　第三句一转。汉代制度，郡太守一车两幡。幡即旌麾之类。唐时刺史略等于汉之太守。这句是说，由于在京城抑郁无聊，所以想手持旌麾，远去江海。（湖州北面是太湖和长江，东南是东海，故到湖州可云去江海。）第四句再转。昭陵是唐太宗的陵墓，在长安西边醴泉县的九嵏山。古人离开京城，每每多所眷恋，如曹植诗：“顾瞻恋城阙，引领情内伤。”（《赠白马王彪》）杜甫诗：“无才日衰老，驻马望千门。”（《至德二载自京金光门出乾元初有悲往事》）都是传诵人口之句。但此诗写登乐游原不望皇宫、城阙，也不望其他已故皇帝的陵墓，而独望昭陵，则是别有深意的。唐太宗是唐代、也是我国封建社会中杰出的皇帝。他建立了大唐帝国，文治武功，都很煊赫；而知人善任，惟贤是举，则是他获得成功的重要因素之一。诗人登高纵目，西望昭陵，就不能不想起当前国家衰败的局势，自己闲静的处境来，而深感生不逢时之可悲可叹了。诗句虽然只是以登乐游原起兴，说到望昭陵，戛然而止，不再多写一字，但其对祖国的热爱，对盛世的追怀，对自己无所施展的悲愤，无不包括在内。写得既深刻，又简练；既沉郁，又含蓄，真所谓“称名也小，取类也大”。', poem_tags = '唐诗三百首,爱国' WHERE poem_title = '将赴吴兴登乐游原一绝' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_tags = '春节,孤独,思乡' WHERE poem_title = '除夜宿石头驿' AND poem_author = '戴叔伦';
UPDATE edu_poem SET poem_translation = '世俗的人互相结交需要以黄金为纽带，黄金用得不多，交情自然不深。\n纵然口头上暂时承诺了什么，实际上他的心就如路人一样冷漠。', poem_notes = '世人：指世俗之人。\n纵令：纵然，即使。\n然诺：许诺。然：答应，信守。\n悠悠：平淡隔膜、庸俗不堪的样子。\n行路心：路上行人的心理。', poem_appreciation = '“世人结交须黄金，黄金不多交不深。”揭露出金钱对人情世态的“污染”。黄金一直是古代社会的硬通货，而金钱换“友谊”的事情无论古今都不乏其例。早在西晋，鲁褒就深刻地指出：“舟车上下，役使孔方。凡百君子，同尘和光。上交下接，名誉益彰。”（《钱神论》）\n\n　　“纵令然诺暂相许，终是悠悠行路心。”形象地勾画出长安壁主人虚情假意的笑脸和冷漠无情的心。“然诺”是信义的标志，金钱是欲望的化身，道德和欲望之间的沟壑永难填平，这是作为社会动物的人本然而终极的顽疾。“悠悠行路心”正指向这个本性，“悠悠”两字，形容“行路心”，十分恰当地表现出这份本性长久而自然地生长于世人心中。这样一种看似平淡的口气，对人的讥刺不露骨而能达到鞭挞入骨的效果。\n\n　　文学是社会的一画镜子。这首诗言浅意深，富有哲理意义，反映了唐代社会世态人情的一个侧面。', poem_tags = '友情,哲理' WHERE poem_title = '题长安壁主人' AND poem_author = '张谓';
UPDATE edu_poem SET poem_translation = '会稽山上的雾气散了，显露出高峻的山体和葱郁的草木，明净的水面上没有风也起了水波。\n别说春天已经结束花草都凋谢完了，另有人在水流中央采摘菱叶和荷叶呢。', poem_notes = '稽山：会稽山的省称。\n嵯峨：山高峻貌。\n芳菲：芳香的花草。\n中流：水流的中央。\n芰荷：菱叶与荷叶。《离骚》：制芰荷以为衣兮，集芙蓉以为裳。', poem_tags = '写景' WHERE poem_title = '采莲曲' AND poem_author = '贺知章';
UPDATE edu_poem SET poem_tags = '重阳节,饮酒,思乡' WHERE poem_title = '九月九日登玄武山 / 九月九日玄武山旅眺' AND poem_author = '卢照邻';
UPDATE edu_poem SET poem_translation = '译文 惆怅底想着人生如浮云，来去匆匆之情景，听见琴瑟之音也是满耳凄凉。和朋友之情非常深厚，怨恨朋友之间的离别，在分别之际，一起登上青山眺望河水。眼看着朋友消失在茫茫原野，在静静的夜里传来了零星的声音。 满眼是秋天萧条景象，黄叶零星飘落，天不下雨却是阴沉沉的，让人心情忧郁。天若有情感也会和凡人一样为情所困而变老，幽幽的恨意总是那以消除。忧郁的想起我们以前高兴的情景，等我一觉醒来，再到哪里去寻找呢。', poem_appreciation = '这首词是作者在秋夜送别友人的词，是一首集合多种秋景融入秋心的小词。词虽欠含蓄，但天然绝妙。词的上片重在写景，下片由景入情。全词对友感情真挚，和友离别充满了惆怅之情。上片以情写景，情景交融。下片由秋景来抒情，不忍和朋友离别。\n\n　　“怅望浮生急景，凄凉宝瑟余音”：惆怅底想着人生如浮云，来去匆匆之情景，听见琴瑟之音也是满耳凄凉。\n\n　　“楚客多情偏怨别，碧山远水登临”：和朋友之情非常深厚，怨恨朋友之间的离别，在分别之际，一起登上青山眺望河水。\n\n　　“目送连天衰草，夜阑几处疏砧”：眼看着朋友消失在茫茫原野，在静静的夜里传来了零星的声音。\n\n　　“黄叶无风自落，秋云不雨长阴”：满眼是秋天萧条景象，黄叶零星飘落，天不下雨却是阴沉沉的，让人心情忧郁。\n\n　　“天若有情天亦老，摇摇幽恨难禁”：“天若有情天亦老”是历来诗人常引用的诗句，出自于唐诸王孙李长吉遂作《金铜仙人辞汉歌》。歌曰：“衰兰送客咸阳道，天若有情天亦老。”写得悲悲切切，感人尤深。此词也是送客，悲悲切切之情一炉无遗。上天若有和我一样的感情，也会有我这样的情感衰落，和朋友分别，飘飘荡荡的隐隐之恨，怎么能禁得住啊。\n\n　　“惆怅旧欢如梦，觉来无处追寻”：忧郁的想起我们以前高兴的情景，等我一觉醒来，再到哪里去寻找呢？\n\n　　上片“怅惘浮生急景”，一“浮”一“急”，铺垫了下文的感情色彩。“宝瑟余音”，呼应了“凄凉”二字。通篇两处“怅”字，尽显怆情，而上片尤以末句“目送连天衰草，夜阑几处疏砧。”为妙。下片中“黄叶无风自落，秋云不雨常阴”可谓千古佳句。以两种自然景物的变化不仅显出秋天的悲怆之情，“自”字，更写出了悲伤的不由自主。末句“惆怅旧欢如梦，觉来无处追寻。”可呼应首句“浮生急景”，将一生的悲欢离合演绎得如一幕幕场景，仿佛梦幻的片段浮现，若隐若现。一个“觉来”后的空荡，将“惆怅”表现地淋漓尽致。', poem_tags = '送别,友人' WHERE poem_title = '河满子·秋怨' AND poem_author = '孙洙';
UPDATE edu_poem SET poem_translation = '迎着风儿，想要劝春光停住脚步。春光却停留在了城南的青草路上。它不愿同岸边的落花一样随流水而去，暂且就成为在泥土上飘舞的飞絮。\n看着镜中头发花白的自己，惋惜逝去的时光。人没有辜负春天，是春天自己辜负了自己啊！从梦中醒来才感觉远离了许多忧愁，只是牵挂着风雨中的梨花是否安然。', poem_notes = '住：停，止，停留。\n星星：头髮花白貌。', poem_appreciation = '这是一首伤春词，由伤春而感伤自己年华流逝。\n\n　　第一、两句，想要留住春光，然而已是芳草萋萋的暮春时节，开头即点出伤春的意味，为全词奠定了感伤的基调，接着似站在春天的角度说春不甘和落花一样随水而去，了无踪迹，只好暂且作粘于泥上的飞絮。“落花”、“飞絮”均为飘零之物，然在词人笔下，似落花流逝更快，而飞絮尚可在泥上暂存，生动形象地写出了春之不愿逝去的不甘和无奈。运用比喻，用春来比喻自己的青春年华，表达出想要留住青春之感。五、六两句，看到镜中的华发，想自己年华流逝，自己不愿辜负青春，然而无奈的还是辜负了，一事无成，表达出因功业未就而人已老去，美好的青春理想破灭的浓浓愁绪。“梦回人远许多愁”梦中醒来，似已消愁，貌似洒脱，实则更为沉痛，最后一句，以景作结，将这许多的愁都凝聚在风雨中的梨花之上，用风雨梨花象征自己的命运处境，含蓄动人。', poem_tags = '伤春,感伤,岁月' WHERE poem_title = '玉楼春·风前欲劝春光住' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_tags = '宋词三百首,闺怨,女子,孤独' WHERE poem_title = '鹊踏枝·几日行云何处去' AND poem_author = '冯延巳';
UPDATE edu_poem SET poem_translation = '译文 雨后原野一片翠绿，烟景渺茫， 晴空里余霞像一幅幅绮锦。 东风跟随春姑娘回来了，催开了我家的鲜花。 现在正是花落日暮的时候，怎么不让人嗟叹不止？ 我想去游名山大川，找仙人学道炼丹砂金丹。', poem_tags = '春天,写风' WHERE poem_title = '落日忆山中' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '秋夜行舟停泊在西江牛渚山，蔚蓝的天空中没有一丝游云。\n我登上小船仰望明朗的秋月，徒然地怀想起东晋谢尚将军。\n我也能够吟哦袁宏的咏史诗，可惜没有那识贤的将军倾听。\n明早我将挂起船帆离开牛渚，这里只有满天枫叶飘落纷纷。', poem_notes = '牛渚：山名，在今安徽当涂县西北。诗题下有注：此地即谢尚闻袁宏咏史处。\n西江：从南京以西到江西境内的一段长江，古代称西江。牛渚也在西江这一段中。\n谢将军：东晋谢尚，今河南太康县人，官镇西将军，镇守牛渚时，秋夜泛舟赏月，适袁宏在运租船中诵己作《咏史》诗，音辞都很好，遂大加赞赏，邀其前来，谈到天明。袁从此名声大振，后官至东阳太守。\n高咏：谢尚赏月时，曾闻诗人袁宏在船中高咏，大加赞赏。\n斯人：指谢尚。\n挂帆席：一作“洞庭去”。挂帆：扬帆。\n落：一作“正”。', poem_appreciation = '首句开门见山，点明“牛渚夜泊”。次句写牛渚夜景，大处落墨，展现出一片碧海青天、万里无云的境界。寥廓空明的天宇，和苍茫浩渺的西江，在夜色中融为一体，越显出境界的空阔渺远，而诗人置身其间时那种悠然神远的感受也就自然融合在里面了。\n\n　　三、四句由牛渚“望月”过渡到“怀古”。谢尚牛渚乘月泛江遇见袁宏月下朗吟这一富于诗意的故事，和诗人眼前所在之地（牛渚西江）、所接之景（青天朗月）的巧合，固然是使诗人由“望月”而“怀古”的主要凭藉，但之所以如此，还由于这种空阔渺远的境界本身就很容易触发对于古今的联想。空间的无垠和时间的永恒之间，在人们的意念活动中往往可以相互引发和转化，陈子昂登幽州台，面对北国苍莽辽阔的大地而涌起“前不见古人，后不见来者”之感，便是显例。而今古长存的明月，更常常成为由今溯古的桥梁，“月下沉吟久不归，古来相接眼中稀”（《金陵城西月下吟》），正可说明这一点。因此，“望”、“忆”之间，虽有很大跳跃，读来却感到非常自然合理。“望”字当中就含有诗人由今及古的联想和没有明言的意念活动。“空忆”的“空”字,表现了诗人对过去的回忆，也暗示了这份回忆注定没有回应。暗逗下文。\n\n　　如果所谓“怀古”，只是对几百年前发生在此地的“谢尚闻袁宏咏史”情事的泛泛追忆，诗意便不免平庸而落套。诗人别有会心，从这桩历史陈迹中发现了一种令人向往追慕的美好关系—贵贱的悬隔，丝毫没有妨碍心灵的相通；对文学的爱好和对才能的尊重，可以打破身份地位的壁障。而这，正是诗人在当时现实中求之而不可的得。诗人的思绪，由眼前的牛渚秋夜景色联想到往古，又由往古回到现实，情不自禁地发出“余亦能高咏，斯人不可闻”的感慨。尽管自己也象当年的袁宏那样，富于文学才华，而象谢尚那样的人物却不可复遇了。“不可闻”回应“空忆”，寓含着世无知音的深沉感喟。\n\n　　“明朝挂帆席，枫叶落纷纷。”末联宕开写景，想象明朝挂帆离去的情景。在飒飒秋风中，片帆高挂，客舟即将离开江渚；枫叶纷纷飘落，象是无言地送着寂寞离去的行舟。秋色秋声，进一步烘托出因不遇知音而引起的寂寞凄清情怀。\n\n　　诗意明朗而单纯，并没有什么深刻复杂的内容，但却具有一种令人神远的韵味。这种神韵的形成，离不开具体的文字语言和特定的表现手法。这首诗，写景的疏朗有致，不主刻画，迹近写意；写情的含蓄不露，不道破说尽；用语的自然清新，虚涵概括，力避雕琢；以及寓情于景，以景结情的手法等等，都有助于造成一种悠然不尽的神韵。李白的五律，不以锤炼凝重见长，而以自然明丽为主要特色。此篇行云流水，纯任天然。这本身就构成一种萧散自然、风流自赏的意趣，适合表现抒情主人公那种飘逸不群的性格。诗的富于情韵，与这一点也不无关系。', poem_tags = '唐诗三百首,月亮,怀古' WHERE poem_title = '夜泊牛渚怀古' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '千古以来，兴亡更替就像繁华的春梦一样。诗人用疲倦的眼睛远望着天边。孔子家族墓地中长满乔木，吴国的宫殿如今荒革萋萋，楚庙中。乌鸦飞来飞去。\n几间茅屋里，藏着万卷书，我回到了老村生活。山中有什么事？用松花酿酒，用春天的河水煮茶。', poem_notes = '人月圆：曲牌名。此词调始于王诜，因其词中“人月圆时”句，取以为名。《中原音韵》入“黄钟宫”。曲者，小令用。有幺篇换头，须连用。\n诗眼：诗人的洞察力。\n孔林：指孔丘的墓地，在今山东曲阜。\n吴宫：指吴国的王宫。也可指三国东吴建业（今南京）故宫。\n楚庙：指楚国的宗庙。\n投老：临老，到老。', poem_tags = '感慨,历史,抒怀' WHERE poem_title = '人月圆·山中书事' AND poem_author = '张可久';
UPDATE edu_poem SET poem_translation = '赵国将要出战燕国，苏代为燕国对惠王说：“今天我来，路过了易水，看见一只河蚌正从水里出来晒太阳，一只鹬飞来啄它的肉，河蚌马上闭拢，夹住了鹬的嘴。鹬说：‘今天不下雨，明天不下雨，就会干死你。’河蚌也对鹬说：‘今天你的嘴不取，明天你的嘴不取，就会饿死你。’两个不肯互相放弃，结果一个渔夫把它们俩一起捉走了。现在赵国将要攻打燕国，燕赵如果长期相持不下，老百姓就会疲惫不堪，我担心强大的秦国就要成为那不劳而获的渔翁了。所以我希望大王认真考虑出兵之事。”赵惠文王说：“好吧。”于是停止出兵攻打燕国。', poem_notes = '方：刚刚。 \n蚌：贝类，软体动物有两个椭圆形介壳，可以开闭 \n曝：晒。 \n支：支持，即相持、对峙 \n鹬：一种水鸟，羽毛呈茶褐色，嘴和腿都细长，常在浅水边或水田中捕食小鱼、昆虫、河蚌等。 \n箝：同“钳”，把东西夹住的意思 \n喙：嘴，专指鸟兽的嘴。 \n雨：这里用作动词，下雨。 \n即：就，那就。 \n谓：对……说。 \n舍：放弃。 \n相舍：互相放弃。 \n并：一起，一齐，一同。 \n禽：同“擒”，捕捉，抓住。 \n且：将要。 \n弊：弊病；害处，这里指疲弊的意思。 \n禽：通“擒”，捕捉。 \n恐：担心。 \n为：替，给。', poem_appreciation = '有一天，天气很好，太阳照在大地上，一只河蚌顺着河水上了岸，躺在沙滩上，张开两个蚌壳悠闲地晒着太阳。\n\n　　这时，一只名鹬的水鸟从河边飞过。鹬鸟悄悄地落在河蚌附，轻轻地走到河蚌旁边，猛地伸着又长又尖的嘴巴，猛的捉住了甲壳内的蚌肉。\n\n　　河蚌反应也很快，鹬鸟一咬住蚌肉，它就猛然合上蚌壳，紧紧夹住了鹬鸟的长嘴。\n\n　　鹬鸟急了，赶紧甩动长嘴，想甩开河蚌。可是河蚌夹得很紧，根本甩不开。它们各自用力搏斗了一会儿，鹬鸟和河蚌谁也不肯相让，就这样僵持着。\n\n　　双方争吵起来。鹬鸟威胁河 蚌说：“你若不张开甲壳，今天不下雨，明天也不下雨，你会被晒死在这里的， 我看你能撑到什么时候。\n\n　　河蚌也不甘示弱地说：我今天不放你，明天不放你，您的嘴巴抽不出来，你就会在这里饿死和憋死在这河滩上，\n\n　　就这样，鹬鸟和河 蚌谁也不肯让谁。时间一长，它们俩都累得筋疲力尽。\n\n　　正在这时，一个老渔夫从河滩打鱼回家路过，就从沙滩上走过。看见鹬蚌相争的情景，渔夫觉得很有趣。他悄悄地走上前去，没有费多大力气， 把两个一起抓住，高兴地拿走了。', poem_tags = '小学文言文,哲理,故事' WHERE poem_title = '鹬蚌相争' AND poem_author = '刘向';
UPDATE edu_poem SET poem_tags = '夏天,写景,山水,伤怀' WHERE poem_title = '幽居初夏' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '杨子的邻人走失了一只羊。那人央请了许多亲戚朋友一道去寻找（丢失的羊），又请杨子的家僮也一同去追捕。杨子说：“唉！走失了一只羊，何必要这么多人去寻找呢？“邻人说：“因为岔路太多了！“杨子的家僮回来后，杨子问：“找到羊了吗？“邻居说：“丢掉了！“杨子问：“怎麼会让羊走失呢？“邻居说：“每条岔路的中间又有岔路，我们不知道要往哪条路走，所以只好回来了。“\n\n　　杨子听了，脸色变得很忧伤，过了些时还不说话，整天闷闷不乐。他的学生觉得很奇怪，便请问杨子说：“羊不过是只贱畜，而且又不是老师的，为什麼为了这事整天都不笑呢？“杨子没有回答他们……心都子就说：“大路因为岔路多了而走失了羊，读书人则因为不能专心一致而葬送了一生。“', poem_notes = '竖：未成年的童仆\n反：通“返”，返回\n戚然：悲伤的样子\n怪：以......为怪\n多方：不能专心致志\n杨子之竖追：之：的。\n杨子：杨朱，战国时卫国人，思想家。\n党：家族亲属。\n损：减少。\n党：亲戚朋友', poem_tags = '小学文言文,寓言,故事,哲理' WHERE poem_title = '多歧亡羊' AND poem_author = '列御寇';
UPDATE edu_poem SET poem_translation = '译文 城外萧萧刮起了寒冷的的北风， 城楼上守城的将士被寒风吹得连耳朵都要掉了一样。 将军在帐篷里面身披貂鼠大衣， 手持酒杯忧愁的看着帐外的飞雪。', poem_appreciation = '这是一首起眼绝句，第一句诗中“萧萧”说明风很大，而“北风”即北方吹来的风，北方吹来的风都是非常寒冷的，所以风很大，而且很冷。在这种环境之下，在城上守卫的将士（健儿），自然会很冷，冷到什么程度呢？冷到连耳朵都快被萧萧寒风吹落。所以第二句紧接着就写了守城将士在此种恶劣环境下的状况。在颈联中作者再次突出天气之寒冷，将军在帐篷中都还要穿着貂鼠大衣才能御寒。在这时候，将军面对这样的天气和环境也能能持酒望着帐外飞雪而已。尾联即将军的反应。\n\n　　全诗通过对这种恶劣天气和环境的描写，对将士们的反应刻画，表达出了将士们行军打仗的艰辛，也从侧面表达了作者对战争的批判和对将士们的怜爱之情。', poem_tags = '写风,将士,战争' WHERE poem_title = '北风行' AND poem_author = '刘基';
UPDATE edu_poem SET poem_translation = '她说过要来的，其实是句空话，一去便杳无影踪。我在楼上等着，直到残月西斜，传来五更的晓钟。\n因为远别而积思成梦，梦里悲啼，久唤难醒；醒后便匆忙提笔写信，心情急切，墨未磨浓。\n蜡烛的余光，半罩着饰有金翡翠的帷幕；兰麝的香气，熏染了被褥上刺绣的芙蓉。\n我像古代的刘郎，本已怨恨蓬山仙境的遥远；我所思念的人啊，哪堪更隔着蓬山千重万重！\n\n飒飒的东风吹来阵阵的细雨，阵阵轻雷响彻荷花池塘内外。\n从金蟾的炉内飘出缕缕清香，转动玉虎辘轳可以汲上饮水。\n贾氏隔帘偷窥韩寿英俊年少，宓妃赠送玉枕钦慕曹植文采。\n爱情的种子不要和春花开放，寸寸相思只会化成寸寸尘灰。\n\n含情脉脉地凝望不觉春日已晚，短暂见上一面也已经是夜深时分。\n听到楼梯响起想登上去又胆怯，灯光明亮透出窗帘欲去探访又很难。\n不如钗上之燕，可整日接近其人；不如镜中之鸾，能频对其人倩影。\n怅然归去经过横塘堤天已拂晓，微弱的晨星宛如在送着宝马金鞍。\n\n哪儿传来阵阵清亮的筝声，伴随着急骤的箫管？在樱花怒放的深巷，在垂杨轻拂的河岸。\n东邻的贫家中有位姑娘，年纪大了还嫁不出去，对着这当空的丽日，对着这暮春三月半。\n溧阳公主刚刚十四岁，在这清明回暖的日子，与家人一起在园墙里赏玩。\n这位贫家姑娘回到家后一夜辗转无眠，只有梁间的燕子，听到她的长叹。', poem_notes = '空言：空话，是说女方失约。\n蜡照：烛光。半笼：半映。指烛光隐约，不能全照床上被褥。金翡翠：指饰以金翠的被子。《长恨歌》：“悲翠衾寒谁与共。”\n麝熏：麝香的气味。麝本动物名，即香獐，其体内的分泌物可作香料。这里即指香气。度：透过。绣芙蓉：指绣花的帐子。\n刘郎：相传东汉时刘晨、阮肇一同入山采药，遇二女子，邀至家，留半年乃还 乡。后也以此典喻“艳遇”。\n蓬山：蓬莱山，指仙境。\n芙蓉塘：荷塘。轻雷：司马相如《长门赋》：“雷殷殷而响起兮，声像君之车音。”起二句以风、雨、雷等景物起兴，烘托女子怀人之情。\n金蟾：金蛤蟆。古时在锁头上的装饰。啮：咬。\n玉虎：用玉石作装饰的井上辘轳，形如虎状。丝：指井索。\n贾氏：西晋贾充的次女。她在门帘后窥见韩寿，爱悦他年少俊美，两人私通。贾氏以皇帝赐贾充的异香赠寿，被贾充发觉，遂以女嫁给韩寿。韩掾：指韩寿。韩曾为贾充的掾属。\n宓（fú）妃：古代传说，伏羲氏之女名宓妃，溺死于洛水上，成为洛神。这里借指三国时曹丕的皇后甄氏。相传甄氏曾为曹丕之弟曹植所爱，后来曹操把她嫁给曹丕。甄后被馋死后，曹丕把她的遗物玉带金缕枕送给曹植。曹植离京途径洛水，梦见甄后来相会，表示把玉枕留给他作纪念。醒后遂作《感甄赋》，后明帝改为《洛神赋》。魏王：指魏东阿王曹植。\n春心：指相思之情。\n晼（wǎn）晚：日暮。春晼晚：春暮。晼：一作“院”。\n夜阑干：夜深。\n烘：灯光明达透出窗帘的情状。\n多羞钗上燕：《洞冥记》谓汉武帝元鼎间有神女留玉钗与帝，至昭帝时化白燕升天，因名玉燕钗。句言己不能如钗上燕接近其人，故“羞”。\n镜中鸾：指镜背的鸾鸟图案。句谓己不如镜中鸾之频对其人倩影。\n华星：犹明星。\n哀筝：高亢清亮的筝声。急管：急促的管乐。永巷：深长的街巷。\n东家老女：宋玉《登徒子好色赋》：“臣里之美者，莫若臣东家之子。”此处用此意暗示这位老女是容华美艳的姑娘。嫁不售：嫁不出去。\n溧（lì）阳公主：梁简文帝的女儿。这里泛指贵家女子。同墙看：谓东家老女也随俗游春，同在园墙里看花。', poem_appreciation = '《无题四首》包括两首七律、一首五律和一首七古。体裁既杂，各篇之间在内容上也看不出有明显的联系，似乎不一定的同时所作的有统一主题的组诗。\n\n　　第一首是一首艳情诗。诗中写女主人思念远别的情郎，有好景不常在之恨。“梦为远别”为一篇眼目。全诗就是围绕“梦”来写离别之恨。但它并没有按远别——思念——入梦——梦醒的顺序来写。而是先从梦醒时情景写起，然后将梦中与梦后、实境与幻觉来柔合在一起，创造出疑梦疑真、亦梦亦真的艺术境界，最后才点明蓬山万重的阻隔之恨，与首句遥相呼应。这样的艺术构思，曲折宕荡，有力地突出爱情阻隔的主题和梦幻式的心理氛围，使全诗充满迷离恍惚的情怀。\n\n　　首句凌空而起，次句宕开写景，两句若即若离。这要和“梦为远别啼难唤”联系起来，方能领略它的神情韵味。远别经年，会合无缘，夜来入梦，两人忽得相见，一觉醒来，却踪迹杳然。但见朦胧斜月空照楼阁，远处传来悠长而凄清的晓钟声。梦醒后的空寂更证实了梦境的虚幻。如果说第二句是梦醒后一片空寂孤清的氛围，那么第一句便是主人公的叹息感慨。\n\n　　颔联出句追忆梦中情景。远别的双方，梦中虽得以越过重重阻隔而相会；但即使是在梦中，也免不了离别之苦。梦中相会而来的梦中分别，带来的是难以抑止的梦啼。这样的梦，正反映了长期远别造成的深刻伤痛，强化了刻骨的相思。因此对句写梦醒后立刻修书寄远。在强烈思念之情驱使下奋笔疾书的当时，是不会注意到墨的浓淡的，只有在“书被催成”之后，才意外地发现原来连墨也成磨浓。\n\n　　梦醒书成之际，残烛的余光半照着用金钱绣成翡翠鸟图案的帷帐，芙蓉褥上似乎还依稀浮动着麝熏的幽香。六、七句对室内环境气氛的描绘渲染，很富有象征暗示色彩。刚刚消逝的梦境和眼前所见的室内景象在朦胧光影中浑为一片，分不清究是梦境还是实境。烛光半笼，室内若明若暗，恍然犹在梦中；麝香微淡，使人疑心爱人真的来过这里，还留下依稀的余香，上句是以实境为梦境，下句是疑梦境为实境，写恍惚迷离中一时的错觉与幻觉极为生动传神。\n\n　　幻觉一经消失，随之而来的便是室空人杳的空虚怅惘，和对方远隔天涯、无缘会合的感慨。尾联借刘晨重寻仙侣不遇的故事，点醒爱情阻隔，“已恨”“更隔”，层递而进，突出了阻隔之无从度越。\n\n　　第二首写一位深锁幽闺的女子追求爱情而失望的痛苦，是一篇“刻意伤春”之作。\n\n　　首联描绘环境气氛：飒飒东风，飘来蒙蒙细雨；芙蓉塘外，传来阵阵轻雷。既隐隐传达了生命萌动的春天气息，又带有一些凄迷黯淡的色调，烘托出女主人公春心萌动和难以名状的迷惘苦闷。东风细雨，容易令人联想起“梦雨”的典故；芙蓉塘即莲塘，在南朝乐府和唐人诗作中，常常代指男女相悦传情之地；“轻雷”则又暗用司马相如《长门赋》：“雷殷殷而响起兮，声象君之车音。”这一系列与爱情密切相关的词语，所给予读者的暗示和联想是很丰富的。纪昀说：“起二句妙有远神，可以意会。”所谓“远神，是指这种富于暗示性的诗歌语言所构筑的渺远的艺术意境，一种难以言传的朦胧美。\n\n　　颔联写女子居处的幽寂。金蟾是一种蟾状香炉；“锁”指香炉的鼻钮，可以开启放入香料；玉虎，是用玉石装饰的虎状辘轳，“丝”指井索。室内户外，所见者惟闭锁的香炉，汲井的辘轳，它们衬托出女子幽处孤寂的情景和长日无聊、深锁春光的惆怅。香炉和辘轳，在诗词中也常和男女欢爱联系在一起，它们同时又是牵动女主人公相思之情的东西，这从两句分别用“香”、“丝”谐音“相”、“思”可以见出。总之，这一联兼用赋、比，既表现女主人公深闭幽闺的孤寞，又暗示她内心时时被牵动的情丝。\n\n　　颈联出句使用贾充女与韩寿的爱情故事。见《世说新语》载：晋韩寿貌美，大臣贾充辟他为掾（僚属）。一次充女在帘后窥见韩寿，私相慕悦，遂私通。女以皇帝赐充之西域异香赠寿。被充所发觉，遂以女妻寿。对句使用甄后与曹植的爱情故事。见《文选·洛神赋》李善注说：魏东阿王曹植曾求娶甄氏为妃，曹操却将她许给曹丕。甄后被谗死后，曹丕将她的遗物玉带金镂枕送给曹植。曹植离京归国途经洛水，梦见甄后对他说：“我本托心君王，其心不遂。此枕是我在家时从嫁，前与五官中郎将（曹丕），今与君王。”曹植感其事作《感甄赋》，后明帝改名《洛神赋》（句中“宓妃”即洛神，代指甄后）。由上联的“烧香”引出贾氏窥帘，赠香韩掾；由“牵丝（思）”引出甄后留枕，情思不断，藕断丝连。这两个爱情故事，尽管结局有幸有不幸，但在女主人公的意念中，无论是贾氏窥帘，爱韩寿之少俊，还是甄后情深，慕曹植之才华，都反映出青年女子追求爱情的愿望之强烈，奔放。\n\n　　末联突然转折，向往美好爱情的心愿切莫和春花争荣竞发，因为寸寸相思都化成了灰烬。这是深锁幽闺、渴望爱情的女主人公相思无望的痛苦呼喊。热情转化成幻灭的悲哀和强烈的激愤。以“春心”喻爱情的向往，是平常的比喻；但把“春心”与“花争发”联系起来，不仅赋予“春心”以美好的形象，而且显示了它的自然合理性。“相思”本是抽象的概念，诗人由香销成灰联想出“一寸相思一寸灰”的奇句，化抽象为具象，用强烈对照的方式显示了美好事物之毁灭，使这首诗具有一种动人心弦的悲剧美。\n\n　　第三首也是写失意的爱情。而这种失意的爱情中又常常融入自己的某些身世之感。在相思成灰的爱情感慨中也可窥见他仕途失意的不幸遭际。\n\n　　第四首开头两句只是描写环境，人物并未出场，但景物描写中隐含着人物的感情活动。“哀筝随急管”，不只表现出急管繁弦竞逐的欢快、热烈和喧闹，也暗示出听者对音乐的那种撩拨心弦的力量的特殊感受。照一般的写法，这两句似乎应该写成“樱花永巷垂杨岸，哀筝急管相驰逐”，现在却以“何处”发问领起，先写闻乐，再写乐声从樱花盛开的深巷、垂杨飘拂的河边传出，传神地表现了听者闻乐神驰、寻声循踪的好奇心。\n\n　　三、四句写“东家老女”婚嫁失时，自伤迟暮。宋玉《登徒子好色赋》说：“臣里之美者，莫若臣东家之子（指女儿）。”可见东家老女之所以不嫁，并非貌不美，只是家境贫寒。这两句先推出人物，再展开一幅丽日当天，春光将暮的图景。不用任何说明，读者自能想见容华绝世而婚嫁失时的东家老女面对春光将暮之哀伤。 五、六句写另一女子。溧阳公主是梁简文帝的女儿，嫁侯景，为景所宠。这里借用此名代称贵家女子。同样是阳春三月，丽日当天，一边是年长难嫁，形单影只；一边却是少年得志，夫妇同游。用对比鲜明的图景，表现了两种不同社会地位的女子完全不同的境遇。\n\n　　结尾写东家老女归来后的情景。暮春三月、芳华将逝的景色，丝管竞逐、赏心乐事的场面，贵家女子得意美满的生活，触动了她身世孤孑之感，增添内心的苦闷与哀怨。在漫长难挨的深夜展转难眠。末句以不解人意的梁燕犹“闻长叹”，反衬东家老女的痛苦心情却无人理解与同情，侧面虚点，倍觉隽永而有余味。\n\n　　历代诗家都有以美女的无媒难嫁，朱颜的见薄于时，寓才士不遇的诗歌传统。这首无题从内容到写法，都很容易使读者联想起曹植的《美女篇》、《杂诗·南国有佳人》以及其他一些比兴寓言体作品。\n\n　　李商隐的无题，以七律为主要形式。这类无题，以抒情的深细婉曲，意境的含蓄朦胧为主要特色，多取抒情主人公内心独白的表达方式，很少叙写事件、人物和客观生活场景。这首七古无题却不主抒情，不作心理刻画，以第三人称的表达方式，描写出一幕有人物、有事件的生活场景，诗的旨意通过生活场景表现出来。语言朴素无华，与七律无题那种华美而富于象征暗示色彩的语言有所区别，别具一格。', poem_tags = '相思,爱情' WHERE poem_title = '无题四首' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '墓地兰花上凝聚的露珠，宛如她悲伤的泪眼。\n再没有编织同心结的东西，墓地上的繁花更不堪修剪。\n芳草犹如她的席垫，松树犹如她的车盖。\n清风作为她的衣衫，碧玉作为她的玉佩。\n生前乘坐的油壁车，傍晚时准在一旁等待。\n森冷翠绿的磷火，殷勤相随，闪着光彩。\n她走了，在西陵之下，只有风挟雨，呼呼地吹。', poem_notes = '苏小小：《乐府广题》记载：“苏小小，钱塘名倡也，盖南齐时人。”《方舆胜览》：“苏小小墓在嘉兴县西南六十步，乃晋之歌妓。今有片石在通判厅，题曰苏小小墓。”\n幽兰露：兰花上凝结着露珠。\n结同心：用花草或别的东西打成连环回文样式的结子，表示爱情坚贞如一。\n烟花：此指墓地中艳丽的花。\n茵：垫子。\n盖：车盖，即车上遮阳防雨的伞盖。\n佩：身上佩带的玉饰。\n油壁车：妇人所乘的车，车身为油漆为饰。”\n夕：一作“久”。\n冷翠烛：磷火，俗称鬼火，有光无焰，所以说“冷翠烛”。\n劳：不辞劳苦的意思。\n西陵：今杭州西泠桥一带。\n风吹雨：一作“风雨吹”。', poem_appreciation = '李贺的“鬼”诗，总共只有十来首，不到他全部作品的二十分之一。李贺通过写“鬼”来写人，写现实生活中人的感情。这些“鬼”，“虽为异类，情亦犹人”，绝不是那些让人谈而色变的恶物。《苏小小墓》是其中有代表性的一篇。\n\n　　苏小小是南齐时钱塘名妓。李绅在《真娘墓》诗序中说：“嘉兴县前有吴妓人苏小小墓，风雨之夕，或闻其上有歌吹之音。”李贺的这首诗以苏小小的故事为题材，写幽灵形象和幽冥境界。全诗由景起兴，通过一派凄迷的景象和丰富的联想，刻画出飘飘忽忽、若隐若现的苏小小鬼魂形象。诗中寄寓着诗人独特的身世之感。\n\n　　诗的前四句直接刻画苏小小的形象。一、二两句写她美丽的容貌：那兰花上缀着晶莹的露珠，像是她含泪的眼睛。这里抓住心灵的窗户眼睛进行描写，一是让人通过她的眼睛，想见她的全人之美，二是表现她的心境。兰花是美的，带露的兰花更美。但着一“幽”字，境界迥然不同，给人以冷气森森的感觉。它照应题中“墓”字，引出下面的“啼”字，为全诗定下哀怨的基调，为鬼魂活动创造了气氛。三、四两句写她的心境：生活在幽冥世界的苏小小，并没有“歌吹”欢乐，而只有满腔忧怨。她生前有所追求，古乐府《苏小小歌》中说：“我乘油壁车，郎乘青骢马。何处结同心？西陵松柏下。”但身死之后，她的追求落空了，死生悬隔，再没有什么东西可以绾结同心，坟上那萋迷如烟的野草花，也不堪剪来相赠，一切都成了泡影。这种心绪，正是“啼”字的内在根据。仅用四句一十六字，形神兼备地刻画出苏小小的鬼魂形象，表现出诗人惊人的艺术才华。\n\n　　中间六句写苏小小鬼魂的穿着服饰和使用物品：芊芊绿草，像是她的茵褥；亭亭青松，像是她的伞盖；春风拂拂，就是她的衣袂飘飘；流水叮咚，就是她的环佩声响；她生前乘坐的油壁车，如今还依然在等待着她去赴“西陵松柏下”的幽会。这一部分，暗暗照应了前面的“无物结同心”。用一个“待”字，更加重了景象、气氛的凄凉：车儿依旧，却只是空相等待，再也不能乘坐它去西陵下，实现她“结同心”的愿望了。物是人非，触景伤怀，徒增哀怨而已。\n\n　　最后四句描绘西陵之下凄风苦雨的景象：风凄雨零之中，有光无焰的鬼火，在闪烁着暗淡的绿光。这一部分紧承“油壁车，夕相待”而来。翠烛原为情人相会而设。有情人不能如约相会，翠烛就如同虚设。有烛而无人，更显出一片凄凉景象。“翠烛”写出鬼火的光色，加一“冷”字，就体现了人的感觉，写出人物内心的阴冷：“光彩”是指“翠烛”发出的光焰，说“劳光彩”，则蕴涵着人物无限哀伤的感叹。期会难成，希望成灰，翠烛白白地在那里发光，徒费光彩而一无所用。用景物描写来渲染哀怨的气氛，同时也烘托出人物孤寂幽冷的心境，把那种怅惘空虚的内心世界，表现得淋漓尽致。\n\n　　这首诗以景起兴，通过景物幻出人物形象，把写景、拟人融合为一体。写幽兰，写露珠，写烟花，写芳草，写青松，写春风，写流水，笔笔是写景，却又笔笔在写人。写景即是写人。用“如”字、“为”字，把景与人巧妙地结合在一起，既描写了景物，创造出鬼魂活动的环境气氛，同时也就塑造出了人物形象。诗中美好的景物，不仅烘托出苏小小鬼魂形象的婉媚多姿，同时也反衬出她心境的索寞凄凉，收到了一箭双雕的艺术效果。这些景物描写都围绕着“何处结同心，西陵松柏下”这一中心内容，因而诗的各部分之间具有内在的有机联系，人物的内心世界也得到集中的、充分的揭示，显得情思脉络一气贯穿，具有浑成自然的特点。\n\n　　这首诗的主题和意境借鉴了屈原《九歌·山鬼》中对神、鬼的描写方法。从苏小小鬼魂兰露啼眼、风裳水佩的形象上，可以找到山鬼“被薜荔兮带女萝”、“既含睇兮又宜笑”的影子；苏小小那“无物结同心，烟花不堪剪”的坚贞而幽怨的情怀，同山鬼“折芳馨兮遗所思”、“思公子兮徒离忧”的心境有一脉神传；西陵下风雨翠烛的境界，与山鬼期待所思而不遇时“雷填填兮雨冥冥”、“风飒飒兮木萧萧”的景象同样凄冷。由于诗人采用以景拟人的手法，他笔下的苏小小形象，比之屈原的山鬼，更具有空灵缥缈、有影无形的鬼魂特点。她一往情深，即使身死为鬼，也不忘与所思之人绾结同心。她牢落不偶，死生异路，竟然不能了却心愿。她怀着缠绵不尽的哀怨在冥路游荡。在苏小小这个形象身上，即离隐跃之间，读者可以看到诗人自己的影子。诗人也有他的追求和理想，就是为挽救多灾多难的李唐王朝做一番事业。然而，他生不逢时，奇才异能不被赏识，他也是“无物结同心”。诗人使自己空寂幽冷的心境，通过苏小小的形象得到了充分流露。在绮丽秾艳的背后，有着哀激孤愤的思想，透过凄清幽冷的外表，有着诗人炽热如焚的肝肠。鬼魂，只是一种形式，它所反映的，是人世的内容，它所表现的，是人的思想感情。', poem_tags = '写鬼,写景,抒情' WHERE poem_title = '苏小小墓' AND poem_author = '李贺';
UPDATE edu_poem SET poem_translation = '枝头上，草蔓中，眼前百花盛开，有大有小，有白有红，恰如美女的香腮。\n可惜到了黄昏，娇艳芳香的花儿凋零，随着春风乱飞，像草草嫁出的女儿连媒人也不用。(其一)\n\n我虽然三十不到，但已二十有余，常日受饥饿，靠吃蔬菜充肠肚。\n有一位桥头老人对我怜念，赠给我讲军家韬略的一卷兵书。(其四)\n\n男子汉大丈夫为什么不带上锋利的吴钩，去收复那黄河南北割据的关山五十州？请\n你且登上那画有开国功臣的凌烟阁去看，又有哪一个书生能被册封为食邑万户的列侯？(其五)\n\n在典籍中寻觅典故，摘取词句来写诗文，老于雕虫小技之中。往往当破晓的残月对着帘幕、状如弯弓挂在天边时，还在伏案疾书。\n难道没有看见辽东一带还战乱连年吗？国家正当用武之际，即使写出像宋玉那样的悲秋文章，又有什么地方需要它呢？(其六)\n\n司马长卿不得志，住在空房子里悲吟。东方朔侍奉汉武帝，靠幽默滑稽换取宽容。看来应该买把若耶溪所出的宝剑，明日回去拜个猿公那样的师傅练习武功。(其七)\n\n我这今日的边让想起奖进贤能的蔡邕，无心制曲吟诗，只好闲卧春风中。\n舍南有片竹林，削成青简倒可以写字，到老年时，索性在溪边做个钓鱼翁。(其十)\n\n树丛里的小路在晨光中渐渐开朗，细嫩的杂草夜来被烟雾湿染。\n柳絮落满河边，令人惊奇，以为是雪，一场春雨，使水涨满了溪边的麦田。\n古庙里远远传来缓慢的钟声，山头云气中一弯缺月高悬。\n到了晚上，渔人们在岸边敲石取火，点燃竹子，火光映照着渔船。(其十三)', poem_notes = '⑴小白长红：指花有小有大，颜色各种各样。越女：习称春秋时越国美女西施，这里泛指美女。\n⑵嫣香：娇艳芳香，指花。\n⑶未有：一作“未满”。\n⑷小甲蔬：原为莩甲尚小的蔬菜，此处指野菜。\n⑸戎韬：即《太公六韬》，此处指兵书。\n⑹吴钩：吴地出产的弯形的刀，此处指宝刀。一作“横刀”。\n⑺凌烟阁：唐太宗为表彰功臣而建的殿阁，上有秦琼等二十四人的像。\n⑻寻章摘句：指创作时谋篇琢句。老雕虫：老死于雕虫的生活之中。\n⑼哭秋风：即悲秋的意思。\n⑽长卿：汉代辞赋家司马相如的字。\n⑾曼倩：汉代滑稽家东方朔的字。\n⑿事猿公：据《吴越春秋》所载，越王勾践曾请一位善剑法的女子到王都去。她在途中遇到一老翁，自称袁公，与此女以竹竿比剑术，后来老翁飞上树梢，化作白猿。\n⒀边让：后汉人，有才能文。蔡邕荐之于朝廷，但没被重用。此句以边让、蔡邕的关系比喻作者与韩愈的关系。\n⒁裁曲：指制曲吟诗。\n⒂古刹：古寺。\n⒃岚：山头云气。破月：农历月半以后的月亮。', poem_appreciation = '其一\n\n　　这是一首描摹南园景色、慨叹春暮花落的小诗。前两句写花开。春回大地，南园百花竞放，艳丽多姿。首句的“花枝”指木本花卉，“草蔓”指草本花卉，“花枝草蔓”概括了园内所有的花。其中“花枝”高昂，“草蔓”低垂，一者刚劲，一者柔婉，参差错落，姿态万千。李贺写诗构思精巧，包孕密致，于此可见一斑。次句“小白长红”写花的颜色，意思是红的多，白的少。“越女腮”是由此产生的联想，把娇艳的鲜花比作越地美女的面颊，赋予物以某种人的素质，从而显得格外精神。 　　后两句写花落。日中花开，眼前一片姹紫嫣红，真是美不胜收。可是好景不长，到了“日暮”，百花凋零，落红满地。“可怜”二字表达了诗人无限惋惜的深情。是惜花、惜春，也是自伤自悼。李贺当时不过二十来岁，正是年青有为的时期，却不为当局所重用，犹如花盛开时无人欣赏。想到红颜难久，容华易谢，不免悲从中来。“落花不再春”，待到花残人老，就再也无法恢复旧日的容颜和生气。末句用拟人的手法写花落时身不由已的状态。“嫁与春风不用媒”，委身于春风，不须媒人作合，没有任何阻拦，好像两厢情愿。其实，花何尝愿意离开本枝，随风飘零，只为盛时已过，无力撑持，春风过处，便不由自主地坠落下来。这句的“嫁”字与第二句中的“越女腮”相映照，越发显得悲苦酸辛。当时盛开，颜色鲜丽，宛如西施故乡的美女。而今“出嫁”，已是花残“人老”，非复当时容颜，抚今忆昔，倍增怅惘。结句婉曲深沉，制造了浓烈的悲剧气氛。这首七言绝句，以赋笔为主，兼用比兴手法，清新委婉，风格别具，是不可多得的抒情佳品。\n\n其四\n\n　　此诗表达了诗人欲弃文从武、为国效力的抱负。首句写年龄，抒发了怀才不遇、英年遭弃的愤懑情怀。次句极写诗人困苦的处境，为下文弃笔从戎的描写作必要的铺垫。后两句表明诗人对前途并没有绝望，祈愿能以投笔从戎的方式得到重用，而有一番作为，为国效力。全诗辞意显豁，情怀激越，代表了李贺诗风激壮豪迈的一面。\n\n其五\n\n　　这首诗由两个设问句组成，顿挫激越，而又直抒胸臆，把家国之痛和身世之悲都淋漓酣畅地表达出来了。 　　第一个设问是泛问，也是自问，含有“国家兴亡，匹夫有责”的豪情。“男儿何不带吴钩”，起句峻急，紧连次句“收取关山五十州”，犹如悬流飞瀑，从高处跌落而下，显得气势磅礴。“带吴钩”指从军的行动，身佩军刀，奔赴疆场，那气概多么豪迈！“收复关山”是从军的目的，山河破碎，民不聊生，诗人怎甘蛰居乡间，无所作为呢？因而他向往建功立业，报效国家。一、二两句，十四字一气呵成，节奏明快，与诗人那昂扬的意绪和紧迫的心情十分契合。首句“何不”二字极富表现力，它不只构成了特定句式（疑问），而且强调了反诘的语气，增强了诗句传情达意的力量。诗人面对烽火连天、战乱不已的局面，焦急万分，恨不得立即身佩宝刀，奔赴沙场，保卫家邦。“何不”云云，反躬自问，有势在必行之意，又暗示出危急的军情和诗人自己焦虑不安的心境。此外，它还使人感受到诗人那郁积已久的愤懑情怀。李贺是个书生，早就诗名远扬，本可以才学入仕，但这条进身之路被“避父讳”这一封建礼教无情地堵死了，使他没有机会施展自己的才能。“何不”一语，表示实在出于无奈。次句一个“取”字，举重若轻，有破竹之势，生动地表达了诗人急切的救国心愿。然而“收取关山五十州”谈何容易？书生意气，自然成就不了收复关山的大业，而要想摆脱眼前悲凉的处境，又非经历戎马生涯，杀敌建功不可。这一矛盾，突出表现了诗人愤激不平之情。 　　“请君暂上凌烟阁，若个书生万户侯？”诗人问道：封侯拜相，绘像凌烟阁的，哪有一个是书生出身？这里诗人又不用陈述句而用设问句，牢骚的意味显得更加浓郁。看起来，诗人是从反面衬托投笔从戎的必要性，实际上是进一步抒发了怀才不遇的愤激情怀。由昂扬激越转入沉郁哀怨，既见出反衬的笔法，又见出起伏的节奏，峻急中作回荡之姿。就这样，诗人把自己复杂的思想感情表现 在诗歌的节奏里，使读者从节奏的感染中加深对主题的理解、感受。 　　李贺《南园十三首》组诗，多就园内外景物讽咏，以写其生活与感情。但此首不借所见发端，却凭空寄慨，于豪情中见愤然之意。盖只是同时所作，拉杂汇编，不能以题目限的。\n\n其六\n\n　　慨叹读书无用、怀才见弃，是这首绝句的命意所在。 　　诗的前两句描述艰苦的书斋生活，其中隐隐地流露出怨艾之情。首句说我的青春年华就消磨在这寻章摘句的雕虫小技上了。此句诗意，好像有点自卑自贱，颇耐人寻绎。李贺向以文才自负，曾把自己比作“汉剑”，“自言汉剑当飞去”（《出城寄权璩杨敬之》），抱负远大。可是，现实无情，使他处于“天荒地老无人识”（《致酒行》）的境地。“雕虫”之词出于李贺笔下，显然是愤激之辞。句中的“老”字用作动词，有终老纸笔之间的意思，包含着无限的辛酸。 　　次句用白描手法显现自己刻苦读书、发奋写作的情状：一弯残月，低映檐前，抬头望去，象是当帘挂着的玉弓；天将破晓，而自己还在孜孜不倦地琢句谋篇。这里，诗人惨淡苦吟的精神和他那只有残月作伴的落寞悲凉的处境形成鲜明的比照，暗示性很强。 　　读书为何无用？有才学为何不能见用于世？三、四句遒劲悲怆，把个人遭遇和国家命运联系起来，揭示了造成内心痛苦的社会根源，表达了郁积已久的忧愤情怀。“辽海”指东北边境，即唐河北道属地。从元和四年（809）到元和七年，这一带割据势力先后发生兵变，全然无视朝廷的政令。唐宪宗曾多次派兵讨伐，屡战屡败，弄得天下疲惫，而藩镇割据的局面依然如故。国家多难，民不聊生，这是诗人所以要痛哭流涕的原因之一；由于战乱不已，朝廷重用武士，轻视儒生，以致斯文沦落，这是诗人所以要痛哭流涕的原因之二。末句的“文章”指代文士，实即作者自己。“哭秋风”不是一般的悲秋，而是感伤时事、哀悼穷途的文士之悲。此与屈原的“悲回风之摇蕙兮，心冤结而内伤。……鱼葺鳞以自别兮，蛟龙隐其文章”（《九章·悲回风》）颇有相似之处。时暗君昏则文章不显，这正是屈原之所以“悲回风”（按：“回风”即秋风）、李贺之所以“哭秋风”的真正原因。 　　这首诗比较含蓄深沉，在表现方法上也显得灵活多变。首句叙事兼言情，满腹牢骚通过一个“老”字倾吐出来，炼字的功夫极深。次句写景，亦即叙事、言情，它与首句相照应，活画出诗人勤奋的书斋生活和苦闷的内心世界。“玉弓”一词，暗点兵象，为“辽海”二句伏线，牵丝带笔，曲曲相关，见出文心之细。第三句只点明时间和地点，不言事（战事）而事自明，颇具含蓄之致。三、四两句若即若离，似断实续，结构得非常精巧；诗人用隐晦曲折的手法揭示了造成斯文沦落的社会根源，从而深化了主题，加强了诗歌的感染力量。\n\n其七\n\n　　这是一首述怀之作。前两句写古人，暗示前车可鉴；后两句写自己，宣称要弃文习武，易辙而行。 　　首句描述司马相如穷愁潦倒的境况。这位大辞赋家才气纵横，早年因景帝“不好辞赋”，长期沉沦下僚，后依梁孝王，厕身门下，过着闲散无聊的生活。梁孝王死后，他回到故乡成都，家徒四壁，穷窘不堪。（见《汉书·司马相如传》）“空舍”，正是这种情况的写照。李贺以司马相如自况，出于自负，更出于自悲。次句写东方朔。这也是一位很有才能的人，他见世道险恶，在宫廷中，常以开玩笑的形式进行讽谏，以避免直言悖上。结果汉武帝只把他当作俳优看待，而在政治上不予信任。有才能而不得施展，诙谐取容，怵惕终生，东方朔的遭遇是斯文沦丧的又一个例证。诗人回顾历史，瞻望前程，不免感到茫然。 　　三、四句直接披露怀抱，借用春秋越国范蠡学剑的事迹，表示要弃文习武。既然历来斯文沦丧，学文无用，倒不如买柄利剑去访求名师，学习武艺，或许还能有一番作为。诗人表面显得很冷静，觉得还有路可走，其实这是他在屡受挫折，看透了险恶世道之后发出的哀叹。李贺的政治理想并不在于兵戈治国，而是礼乐兴邦。弃文习武的违心之言，只不过是反映理想幻灭时痛苦而绝望的反常心理。 　　这首诗，把自己和前人揉合在一起，把历史和现实揉合在一起，把论世和述怀揉合在一起，结构新奇巧妙。诗歌多处用典。或引用古人古事据以论世，或引用神话传说借以述怀。前者是因，后者是果，四句一气呵成，语意连贯，所用的典故都以各自显现的形象融入整个画面之中，无今无古，无我无他，显得浑化蕴藉，使人有讽咏不尽之意。\n\n其八\n\n　　南园的春天，生机勃勃，富有意趣。春水初生，乳燕始飞，蜂儿采花酿蜜，鱼儿拥钩觅食，这些都是极具春天特征的景物，而远景透过窗户直入书房，使人舒心惬意，欢欣不已。这首诗生动传神，清新流转，读来令人神清气逸。\n\n其十\n\n　　李贺曾得到韩愈的推重和相助，但仍不得志。这首诗反映了他的抑郁心情，无心苦吟，打算写字消遣，年老时做一个渔翁了事。\n\n其十三\n\n　　这是一首诗，也是一幅画。诗人以诗作画，采用移步换形的方法，就像绘制动画片那样，描绘出南园一带从早到晚的水色山光，旖旎动人。 　　首二句写晨景。夜雾逐渐消散，一条蜿蜒于绿树丛中的羊肠小道随着天色转明而豁然开朗。路边的蒙茸细草沾满了露水，湿漉漉的，分外苍翠可爱。诗歌开头从林间小路落笔，然后由此及彼，依次点染。显然，它展示的是诗人清晨出游时观察所得的印象。 　　三、四句写白昼的景色。诗人由幽静、逼仄的林间小道来到空旷的溪水旁边。这时风和日暖，晨露已晞，柳絮纷纷扬扬，飘落在溪边的浅滩上，白花花的一片，像是铺了一层雪。阳春三月，莺飞草长，诗人沿途所见多是绿的树，绿的草，绿的田园。到了这里，眼前忽地出现一片银白色，不禁大为惊奇。惊定之后，也就尽情欣赏起这似雪非雪的奇异景象来。 　　诗人在诗中着意刻画了田园生活的安逸，流露出浓厚的归隐情绪，表现了诗人对仕途的失望、无奈之感。', poem_tags = '写景,抒情,田园,生活,组诗' WHERE poem_title = '南园十三首' AND poem_author = '李贺';
UPDATE edu_poem SET poem_translation = '山色昏暗听到猿声使人生愁，桐江苍茫夜以继日向东奔流。两岸风吹树动枝叶沙沙作响，月光如水映照江畔一叶孤舟。\n建德风光虽好却非我的故土，我仍然怀念扬州的故交老友。相忆相思我抑不住涕泪两行，遥望海西头把愁思寄去扬州。', poem_notes = '桐庐江：即桐江，在今浙江省桐庐县境。广陵：今江苏省扬州市。旧游：指故交。\n暝：指黄昏。\n沧江：指桐庐江。沧同“苍”，因江色苍青，故称。\n建德：唐时郡名，今浙江省建德县一带。非吾土：不是我的故乡。王粲《登楼赋》：“虽信美而非吾土兮，曾何足以少留。”\n维扬：即扬州。《洞书·禹贡》：“淮海维扬州。”\n遥寄：远寄。海西头：指扬州。隋炀帝《泛龙舟歌》：“借问扬州在何处，淮南江北海西头。”因古扬州幅员辽阔，东临大海，故称。', poem_appreciation = '这首诗在意境上显得清寂或清峭，情绪上则带着比较重的孤独感。\n\n　　诗题点明是乘舟停宿桐庐江的时候，怀念扬州（即广陵）友人之作。桐庐江为钱塘江流经桐庐县一带的别称。“山暝听猿愁，沧江急夜流。”首句写日暮、山深、猿啼。诗人伫立而听，感觉猿啼似乎声声都带着愁情。环境的清寥，情绪的黯淡，于一开始就显露了出来。次句沧江夜流，本来已给舟宿之人一种不平静的感受，再加上一个“急”字，这种不平静的感情，便简直要激荡起来了，它似乎无法控制，而像江水一样急于寻找它的归宿。接下去“风鸣两岸叶，月照一孤舟。”语势趋向自然平缓了。但风不是徐吹轻拂，而是吹得木叶发出鸣声，其急也应该是如同江水的。有月，照说也还是一种慰藉，但月光所照，惟沧江中之一叶孤舟，诗人的孤寂感，就更加要被触动得厉害了。如果将后两句和前两句联系起来，则可以进一步想象风声伴着猿声是作用于听觉的，月涌江流不仅作用于视觉，同时还有置身于舟上的动荡不定之感。这就构成了一个深远清峭的意境，而一种孤独感和情绪的动荡不宁，都蕴含其中了。\n\n　　诗人之所以在宿桐庐江时会有这样的感受，是因为“建德非吾土，维扬忆旧游。”建德当时为桐庐邻县，这里即指桐庐江流境。维扬，扬州的古称。按照诗人的诉说，一方面是因为此地不是他自己的故乡，“虽信美而非吾士”，有独客异乡的惆怅；另一方面，是怀念扬州的老朋友。这种思乡怀友的情绪，在眼前这特定的环境下，相当强烈，不由得潸然泪下。他幻想凭着沧江夜流，把他的两行热泪带向大海，带给在大海西头的扬州旧友。\n\n　　这种凄恻的感情，如果说只是为了思乡和怀友，那是不够的。孟浩然出游吴越，是他四十岁去长安应试失败后，为了排遣苦闷而作长途跋涉的。“山水寻吴越，风尘厌洛京”（《自洛之越》），这种漫游，就被罩上一种悒悒不欢的情绪。然而在诗中，诗人只淡淡地把“愁”说成是怀友之愁，而没有往更深处去揭示。这可以看作孟浩然写诗“淡”的地方。孟浩然作诗，原是“遇思入咏”，不习惯于攻苦着力的。然而，这样淡一点着笔，对于这首诗却是有好处的。一方面，对于他的老朋友，只要点到这个地步，朋友自会了解。另一方面，如果把那种求仕失败的心情，说得过于刻露，反而会带来尘俗乃至寒伧的气息，破坏诗所给人的清远的印象。\n\n　　除了感情的表达值得读者注意以外，诗人在用笔上也有轻而淡的一面。全诗读起来只有开头两句“山暝听猿愁，沧江急夜流”中的“愁”、“急”二字给人以经营锤炼的感觉，其余即不见有这样的痕迹。特别是后半抒情，更像是脱口而出，跟朋友谈心。但即使是开头的经营，也不是追求强刺激，而是为了让后面发展得更自然一些，减少文字上的用力。因为这首诗，根据诗题“宿桐庐江寄广陵旧游”，写不好可能使上下分离，前面是“宿”，下面是“寄”，前后容易失去自然的过渡和联系。而如果在开头不顾及后面，单靠后面来弥补这种联系，会分外显得吃力。现在头一句着一个“愁”字，便为下面作了张本。第二句写沧江夜流，着一“急”字，就暗含“客心悲未央”的感情，并给传泪到扬州的想法提供了根据。同时，从环境写起，写到第四句，出现了“月照一孤舟”，这舟上作客的诗人所面临的环境既然是那样孤寂和清峭，从而生出“建德非吾土，维扬忆旧游”的想法便非常自然了。因此，可以说这首诗后面用笔的轻和淡，跟开头稍稍用了一点力气，是有关系的。没有开头这点代价，后面说不定就要失去浑成和自然。\n\n　　孟浩然写诗，“遇思入咏”，是在真正有所感时才下笔的。诗兴到时，他也不屑于去深深挖掘，只是用淡淡的笔调把它表现出来。那种不过分冲动的感情，和浑然而就的淡淡诗笔，正好吻合，韵味弥长。这首诗也表现了这一特色。', poem_tags = '唐诗三百首,写水,怀人' WHERE poem_title = '宿桐庐江寄广陵旧游' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '人生的愁恨怎能免得了？只有我伤心不已悲情无限！我梦见自己重回故国，一觉醒来双泪垂落。\n有谁与我同登高楼？我永远记得一个晴朗的秋天，在高楼眺望。往事已经成空，就仿佛在梦中一般。', poem_notes = '子夜歌：此词调又名《菩萨蛮》、《花问意》、《梅花句》、《晚云烘日》等。此词于《尊前集》、《词综》等本中均作《子夜》，无“歌”字。\n何能：怎能。何：什么时候。免：免去，免除，消除。\n销魂：同“消魂”，谓灵魂离开肉体，这里用来形容哀愁到极点，好像魂魄离开了形体。独我：只有我。何限：即无限。\n重归：《南唐书·后主书》注中作“初归”。全句意思是说，梦中又回到了故国。\n觉来：醒来。觉：睡醒。垂：流而不落之态。\n谁与：同谁。\n长记：永远牢记。秋晴：晴朗的秋天。这里指过去秋游欢l青的景象。望：远望，眺望。\n还如：仍然好像。还：仍然。', poem_appreciation = '这首词的上片写作者感怀亡国的愁恨和梦回故国的痛苦。\n\n　　起首二句由悲叹、感慨而入，用直白的方式抒发胸中的无限愁恨。“人生”句是一种感叹，也是对生活的一种抽象概括，既是说自己，也是说众生，其“愁恨”自有一番别样的滋味，“愁”是自哀，也是自怜，是自己囚居生活的无奈心情：“恨”是自伤，也是自悔，是自己亡国之后的无限追悔。也正因有如此“愁恨”，作者才“销魂独我情何限”，而句中“独我”语气透切，词意更进，表现了作者深切体会的一种特殊的悲哀和绝望。正如俞陛云《南唐二主词集述评》中所云：“起句用翻笔，明知难免而自我销魂，愈觉埋愁之无地。”第三句“故国梦重归”是把前两句关于愁恨的感慨进一步的具体化和个人化。李煜作为亡国之君，自然对自己的故国有不可割舍的情感，所以定会朝思夜想。可是事非昨日，人非当年，过去的欢乐和荣华只能在梦中重现，而这种重现带给作者却只能是悲愁无限、哀情不已，所以一觉醒来，感慨万千、双泪难禁。“觉来双泪垂”不仅是故国重游的愁思万端，而且还有现实情境的孤苦无奈，其中今昔对比，抚今追昔，反差巨大，情绪也更复杂。\n\n　　词的下片续写作者往日成空、人生如梦的感伤和悲哀。\n\n　　“高楼谁与上”是无人与上，也是高楼无人之意，进一步点明作者的困苦环境和孤独心情。所谓登高望远，作者是借登高以远眺故国、追忆故乡。故国不可见，即便可见也已不是当年之国，故乡不可回，此恨此情只能用回忆来寄托。所以作者的一句“长记秋晴望”，实是一种无可奈何的哀鸣。现实中的无奈总让人有一种空虚无着落之感，人生的苦痛也总给人一种不堪回首的刺激，作者才有“往事已成空，还如一梦中”的感慨。在现实中，“往事”真的“成空”。但这种现实却是作者最不愿看到的，他希望这现实同样是一场梦。“如一梦”不是作者的清醒，而是作者的迷惘，这种迷惘中有太多的无奈，以此作结，突显全词的意境。\n\n　　全词以“梦”为中心，集中写“空”，笔意直白，用心挚真。全词八句，句句如白话入诗，以歌代哭，不事雕琢，用情挚切。全词有感慨，有追忆，有无奈，有悲苦，这一切因其情真意深而感人不浅，同时也因其自然流露而愈显其曲致婉转。', poem_tags = '爱国,思怀' WHERE poem_title = '子夜歌·人生愁恨何能免' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '一年年过去，白头发不断添新，\n戎马匆匆里，又一个春天来临。\n为了什么事长久留我在边塞？\n岁月太无情，年纪从来不饶人。\n念念不忘是一片忠心报祖国，\n想起尊亲来便不禁双泪直淋。\n孤独的情怀激动得难以排遣，\n就凑个五辛盘，聊应新春节景。', poem_notes = '马上：指在征途或在军队里。\n关河：关山河川，这里指边塞上。\n簇五辛：蔟，攒聚的意思。五辛，指五种辛味的菜；《本草纲目》：“元旦、立春，以葱、蒜、韭、蓼蒿、芥辛嫩之叶杂和食之，取迎新之意，谓之五辛盘。”', poem_tags = '爱国,思乡' WHERE poem_title = '立春日感怀' AND poem_author = '于谦';
UPDATE edu_poem SET poem_tags = '回忆,无奈' WHERE poem_title = '浣溪沙·伏雨朝寒愁不胜' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '衔着泥土的燕子，飞到装饰华丽的大堂前，占据着梁间安稳的地方，体态轻盈只有主人伶爱，好烟缘可堪羡慕。', poem_notes = '占得：占据。\n杏梁：用杏树所做的屋梁，泛指优质木材所做的梁柱。\n因缘：指双燕美好的结合。', poem_appreciation = '这首词借物咏怀，表达了女主人公对美满爱情的追求。\n\n　　暮春三月，繁花盛开，草木葱茏，一双燕子飞去飞回，匆匆忙忙的衔泥筑巢。它们将巢安安稳稳的筑在房屋的杏梁之上，终成就了美好的烟缘。而独处于闺中的女子勒？她看到了筑巢的燕子，它们双宿双飞的恩爱情态多么令她羡慕。\n\n　　“衔泥燕，飞到画堂前。占得杏梁安稳处，”这三句写燕子筑巢，以动态咏物。“衔”、“飞”、“占”三个动作，便将燕子筑巢的全过程完整的写了出来，一气呵成。\n\n　　“体轻唯有主人怜，堪羡好因缘。”这两句写闺中思妇的感叹。这首咏物词并非止于对燕子的描写，而是借物喻情，由燕及人。女主人公看到结伴而飞的燕子不禁感悟伤神她哀叹自己形单影只，无人怜爱，羡慕梁间燕子的美好烟缘。\n\n　　这首小令仅仅二十七个字，却写得形神兼备，深隐含蓄，极富情致。语言通俗，感情真挚，带有浓郁的民间风味。', poem_tags = '宋词三百首,咏物,写鸟,抒怀,爱情' WHERE poem_title = '忆江南·衔泥燕' AND poem_author = '牛峤';
UPDATE edu_poem SET poem_translation = '一望无际的稻田里，水波微漾，整齐的稻子如刀削一般。清晨的阳光穿过树叶，投影在地上，晨雾在树间缭绕。\n黄莺也喜欢早晨的清凉时光，在青山的影子里欢快的啼鸣。', poem_notes = '新凉：指初秋凉爽的天气。\n田畴：耕熟的田地。泛指田地。', poem_appreciation = '这是一首清新、明快的田园小诗，虽无深意，却具恬适、自然的情致。\n\n　　“凉”是一种“心境”，很不好表现，所以，必须采用以“物境”来表达“心境”的手法，通俗一点说，就是化无形为有形，构成诗中的“图画”，以渲染气氛。诗人用白描的手法勾勒出三幅小画面，第一幅是稻田，从它灌满了水和长得绿油油、齐整整的稻叶中透出凉意。第二幅是树丛，“晓”字自含凉意，低压的雾气也自含凉意，“日”本有热意，因其初升，故也“沧沧凉凉”，何况其穿树而来。第三幅是飞莺，黄莺儿越过田野，飞向晨雾迷蒙的山阴，纳凉去了，诗人的心中仿佛也顿生凉意。把这三幅小画面合起来，便构成了一幅清新、明快的田园山水大图画。\n\n　　由此，“新凉”这一心境，也就从这大图画中的每一个组成部分里渗透出来。而那黄莺的啼鸣，又为这幅大图画添上画外音，呼唤诗人投身其中，共纳新凉。诗人悠然自得的心情，一吟即出。', poem_tags = '古诗三百首,田园,写鸟' WHERE poem_title = '新凉' AND poem_author = '徐玑';
UPDATE edu_poem SET poem_translation = '牵马饮水渡过了那大河，水寒刺骨秋风如剑如刀。\n沙场广袤夕阳尚未下落，昏暗中看见遥远的临洮。\n当年长城曾经一次鏖战，都说戍边战士的意气高。\n自古以来这里黄尘迷漫，遍地白骨零乱夹着野草。', poem_notes = '饮（yìn）马：给马喝水。\n平沙：广漠的沙原。\n黯（àn）黯：昏暗模糊的样子。临洮：古县名，秦置，治所在今甘肃岷县，以临近洮水得名。秦筑长城，西起于此，故有“昔日长城战”之语。\n昔：一作“当”。长：一作“龙”。\n足：一作“漏”，一作“是”。\n蓬蒿：蓬草蒿草之类杂草。', poem_appreciation = '此诗在构思上的特点，是用侧面描写来表现主题。诗中并没具体描写战争，而是通过对塞外景物和昔日战争遗迹的描绘，来表达诗人对战争的看法。开头四句是从军士饮马渡河的所见所感，描绘了塞外枯旷苦寒景象。诗人把描写的时间选在深秋的黄昏，这样更有利于表现所写的内容。写苦寒，只选择了水和风这两种最能表现环境特征的景物，笔墨简洁，又能收到很好的艺术效果。首句的“饮马”者就是军士。诗中的“水”指洮水，临洮城就在洮水畔。“饮马”须牵马入水，所以感觉“水寒”，看似不经意，实则工于匠心。中原或中原以南地区，秋风只使人感到凉爽，但塞外的秋风，却已然“似刀”。足见其风不但猛烈，而且寒冷，仅用十字，就把地域的特点形象地描绘了出来。三四两句写远望临洮的景象。“平沙”谓沙漠之地。临洮，古县名，因县城临洮水而得名。即今甘肃东部的岷县，是长城的起点，唐代为陇右道岷州的治所，这里常常发生战争。暮色苍茫，广袤的沙漠望不到边，天边挂着一轮金黄的落日，临洮城远远地隐现在暮色中。境界阔大，气势恢宏。\n\n　　临洮一带是历代经常征战的战场。据新旧《唐书·王晙列传》和《吐蕃传》等书载：公元714年（开元二年）旧历十月，吐蕃以精兵十万寇临洮，朔方军总管王晙与摄右羽林将军薛讷等合兵拒之，先后在大来谷口、武阶、长子等处大败吐蕃，前后杀获数万，获马羊二十万，吐蕃死者枕藉，洮水为之不流。诗中所说的“长城战”，指的就是这次战争。“昔日长城战，咸言意气高”，这是众人的说法。对此，诗人不是直接从正面进行辩驳或加以评论，而是以这里的景物和战争遗迹来作回答：“黄尘足今古，白骨乱蓬蒿。”“足”是充满的意思。“白骨”是战死者的尸骨。“今古”贯通两句，上下句都包括在内；不仅指从古到今，还包括一年四季，每月每天。意思是说，临洮这一带沙漠地区，一年四季，黄尘弥漫，战死者的白骨，杂乱地弃在蓬蒿间，从古到今，都是如此。这里的“白骨”，包含开元二年这次“长城战”战死的战士，及这以前战死的战士。这里没有一个议论字眼，却将战争的残酷极其深刻地揭示出来。这里是议论，是说理，但这种议论、说理，却完全是以生动的形象来表现，因而更具有震撼人心的力量，手法极其高妙。\n\n　　这首诗着重表现军旅生活的艰辛及战争的残酷，其中蕴含了诗人对黩武战争的反对情绪。', poem_tags = '唐诗三百首,战争,乐府' WHERE poem_title = '塞下曲' AND poem_author = '王昌龄';
UPDATE edu_poem SET poem_translation = '金陵风光美丽如画，秋色明净清爽。碧天与秋水一色，何处是尽头呢？雨后晴朗的天色与秋水闪烁的冷光相辉映。蓼草荻花丛生的小岛上，隐约可见几间竹篱环绕的草舍。\n江水尽头客船上的帆仿佛高挂在云端，烟雾笼罩的岸边，有低垂的酒旗。那些六朝兴盛和衰亡的往事，如今已成为渔民、樵夫闲谈的话题。在高楼上独自遥望，倍感苍凉，凄冷的太阳默默地向西落下。', poem_notes = '离亭燕：词牌名。\n一带：指金陵（今南京）一带地区。\n风物：风光景物。潇洒：神情举止自然大方。此处是拟人化用法。\n浸：液体渗入。此处指水天溶为一体。断：接合部。\n霁色：雨后初晴的景色。冷光：秋水反射出的波光。相射：互相辉映。\n蓼屿：指长满蓼花的高地。荻花洲：长满荻草的水中沙地。\n竹篱茅舍：用竹子做成的篱笆，用茅草搭盖的小房子。\n客帆：即客船。\n低亚：低垂。\n六朝：指东吴、东晋、宋、齐、梁、陈六个朝代，均在南京一带建都。\n渔樵：渔翁樵夫。代指普通老百姓。\n怅望：怀着怅惘的心情远望。', poem_appreciation = '这是一首写景兼怀古的词，在宋怀古词中是创作时期较早的一首。词的上片描绘金陵一带的山水，雨过天晴的秋色里显得分外明净而爽朗；下片通过怀古，寄托了词人对六朝兴亡盛衰的感慨。这首词语朴而情厚，有别于婉约派词的深沉感慨。全词层层抒写，勾勒甚密，语卜而情夺取，有别于婉约派的词风。\n\n　　开头一句“一带江山如画”，先对金陵一带的全景作一番鸟瞰，概括地写出了它的山水之美。秋天草木摇落景色萧索，但这里作者却说“风物向秋潇洒”，一切景物显得萧疏明丽而有脱尘绝俗的风致，这就突出了金陵一带秋日风光的特色。接着“水浸碧天何处断”具体地描绘了这种特色。这个“水”字承首句的“江”而来，词人的视线随着浩瀚的长江向远处看去，天幕低垂，水势浮空，天水相连，浑然一色，看不到尽头。将如此宏阔的景致，用一个“浸”字形象而准确地描绘出来。近处则是“霁色冷光相射”，“霁色”紧承上句“碧天”而来，“冷光”承“水”字而来，万里晴空所展现的澄澈之色，江波潋滟所闪现的凄冷的光，霁色静止，冷光翻动，动景与静景互相映照，构成一幅绮丽的画面。一个“射”字点化了这一画面。接着词人又把视线从江水里移到了江洲上，却只见“蓼屿荻花洲，掩映竹篱茅舍。”洲、屿是蓼荻滋生之地，秋天是它发花的季节，密集的蓼荻丛中，隐约地现出了竹篱茅舍。这样，从自然界写到了人家，暗暗为下片的抒发感慨作了铺垫。\n\n　　下片先荡开两笔，写词人，再抬头向远处望去。“云际客帆高挂，烟外酒旗低亚”，极目处，客船的帆高挂着，烟外酒家的旗子低垂着，标志着人活动，于是情从景生，金陵的陈迹涌上心头：“多少六朝兴废事”，这里在历史上短短的三百多年里经历了六个朝代的兴盛和衰亡，它们是怎样兴盛起来的，又是怎样的衰亡的，这许许多多的往事，却是“尽入渔樵闲话”。“渔樵”承上片“竹篱茅舍”而来，到这里猛然一收，透露出词人心里的隐忧。这种隐忧在歇拍两句里，又作了进一步的抒写：“怅望倚层楼”，“怅望”表明了词人瞭望景色时的心情，倚高楼的栏杆上，怀着怅惘的心情，看到眼前景物，想着历史上的往事。最后一句“寒日无言西下”之“寒”字承上片“冷”字而来，凄冷的太阳默默地向西沉下，苍茫的夜幕即将降临，更增加了他的孤寂之感。歇拍的调子是低沉的，他的隐忧没有说明白，只从低沉的调子里现出点端倪，耐人寻味。\n\n　　在宋代词坛上，张昪与范仲淹一样，创作中透露出词风逐渐由婉约向豪放转变的时代信息，对于词境的开拓作出了自己的贡献。', poem_tags = '宋词三百首,豪放,写景,怀古,感慨' WHERE poem_title = '离亭燕·一带江山如画' AND poem_author = '张昪';
UPDATE edu_poem SET poem_translation = '两鬓已经稀疏病后又添白发了，卧在床榻上看着残月照在窗纱上。将豆蔻煎成沸腾的汤水，不用强打精神分茶而食。\n靠在枕上读书是多么闲适，门前的景色在雨中更佳。整日陪伴着我，只有那深沉含蓄的木犀花。', poem_notes = '摊破浣溪沙：又名《山花子》。原为唐教坊曲名，后用为词牌。在唐五代时即将《浣溪沙》的上下片，各增添三个字的结句，成为“七、七、七、三”字格式，名曰《摊破浣溪沙》或《添字浣溪沙》。又因南唐李璟词“菡萏香销”之下片“细雨梦回”两句颇有名，故又有《南唐浣溪沙》之称。双调四十八字，平韵。\n萧萧：这里形容鬓发华白稀疏的样子。\n豆蔻：药物名。熟水：当时的一种药用饮料。陈元靓《事林广记》别集卷七之《豆蔻熟水》 ： “夏月凡造熟水，先倾百盏滚汤在瓶器内，然后将所用之物投入。密封瓶口，则香倍矣……白豆蔻壳拣净，投入沸汤瓶中，密封片时用之，极妙。每次用七个足矣。不可多用，多则香浊。”《百草正义》则说： “白豆蔻气味皆极浓厚，咀嚼久之，又有一种清澈冷洌之气，隐隐然沁入心脾。则先升后降，所以又能下气 \n分茶：杨万里《澹庵坐上观显上人分茶》诗有云：“分茶何似煎茶好，煎茶不似分茶巧”，由此可见，“分茶”是一种巧妙高雅的茶戏。其方法是用茶匙取茶汤分别注入盏中饮食。\n书：《历代诗余》作“篇”字。\n酝藉：宽和有涵容。《汉书·薛广德传》：“广德为人，温雅有酝藉。 ”\n木犀花：即桂花。', poem_appreciation = '这首词创作于作者的晚年，是一首抒情词，主要写她病后的生活情状，委婉动人。词中所述多为寻常之事、自然之情，淡淡推出，却起扣人心弦之效。 　\n\n　　“病起”，说明曾经长期卧床不起，此刻已能下床活动了。“萧萧”是头发花白稀疏的样子。词中系相对病前而言，因为大病，头发白了许多，而且掉了不少。至此，作者即刻打住，下句另起一意。这个处理极妙，意思似乎是说，头发已经那样，何必再去管它，还是料理今后罢。这不仅表现了作者的乐观态度，行文也更简洁。 　\n\n　　下面接写了看月与煎药。因为还没有全好，又夜里，作者做不了什么事，只好休息，卧着看月。“卧看”，是因为大病初起，身子乏力，同时也说明作者心情闲散，漫不经心，两字极为传神。“上”字说明此乃初升之月，则此残月当为下弦月，此时入夜还浅。病中的人当然不能睡得太晚，写得极为逼真。上句写的是衰象，此句却是乐事，表明作者确实不太以发白为念了。“豆蔻”为植物名，种子有香气，可入药，性辛温，能去寒湿。“熟水”是宋人常用饮料。分茶是宋人以沸水冲茶而饮的一种方法，颇为讲究。“莫分茶”即不饮茶，茶性凉，与豆蔻性正相反，故忌之。以豆蔻熟水为饮，即含有以药代茶之意。这又与首句呼应。人儿斜卧，缺月初上，室中飘散缕缕清香，一派闲静气氛。　\n\n　　下片写白日消闲情事。观书、散诗、赏景，确实是大病初起的人消磨时光的最好办法。“闲处好”一是说这样看书只能闲暇无事才能如此；一是说闲时也只能看点闲书，看时也很随便，消遣而已。对一个成天闲散家的人说来，偶然下一次雨，那雨中的景致，却也较平时别有一种情趣。俞平伯说这两句“写病后光景恰好。说月又说雨，总非一日的事情。”（《唐宋词选释》）所见极是。末句将木犀拟人化，结得隽永有致。“木犀”即桂花，点出时间。本来是自己终日看花，却说花终日“向人”，把木犀写得非常多情，同时也表达了作者对木犀的喜爱，见出她终日都把它观赏。“酝藉”，写桂花温雅清淡的风度。“酝藉”一词，常用来形容学问渊深、胸怀宽博、待人宽厚的人中表率，如《归唐书·权德舆传》称他“风流酝藉，为缙绅羽仪”。木犀花小淡黄，芬芳徐吐，不像牡丹夭桃那样只以浓艳媚人，用“酝藉”形容，亦极得神。“酝藉”又可指含蓄香气而言。\n\n　　此词格调轻快，心境怡然自得，与同时其他作品很不相同。通篇全用白描，语言朴素自然，情味深长。', poem_tags = '月亮,闲适,生活' WHERE poem_title = '摊破浣溪沙·病起萧萧两鬓华' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '百花盛开，宫院却寂寂地紧闭大门；\n俏丽宫女，相依相并伫立廊下赏春。\n满怀幽情，都想谈谈宫中忧愁的事，\n鹦鹉面前，谁也不敢吐露自己苦闷。', poem_notes = '琼轩：对廊台的美称。', poem_tags = '唐诗三百首,写景,宫怨' WHERE poem_title = '宫词 / 宫中词' AND poem_author = '朱庆馀';
UPDATE edu_poem SET poem_translation = '垂钓在春天的绿水湾，春已深杏花盛开纷繁。\n潭水澄澈疑心水清浅，荷叶摇动才知鱼游散。\n直到日暮等待知心人，系上小船停靠绿杨岸。', poem_notes = '春深：春意浓郁。宋秦观《次韵裴仲谟和何先辈》：“支枕星河横醉后，入帘飞絮报春深。”乱：纷繁的样子。\n情人：志同道合的人。\n维舟：系船停泊。维：系。南朝梁何逊《与胡兴安夜别》诗：“居人行转轼，客子暂维舟。”', poem_tags = '春天,钓鱼,爱情' WHERE poem_title = '钓鱼湾' AND poem_author = '储光羲';
UPDATE edu_poem SET poem_translation = '你身着羔皮礼服豹纹袖饰，竟然对我们如此大模大样。难道你就这样目中无人吗？我们可是看在老交情份上。\n你身着羔皮礼服豹纹袖饰，竟对我们一副傲慢的模样。难道你就这样目中无人吗？我们可是看在老朋友份上。', poem_notes = '羔裘：羊皮袄。羔：羊之小者。\n袪（qū）：袖口，豹祛即镶着豹皮的袖口。\n自我人：对我们。自，对；我人，我等人。居（jù ）居：即“倨倨”，傲慢无礼。\n维：惟，只。子：你。故：指爱。或作故旧，也通。\n褎（xiù）：同“袖”，衣袖口。\n究究：心怀恶意不可亲近的样子，指态度傲慢。', poem_appreciation = '此诗两章，脉络极清楚，每章的前二句极写卿大夫的服饰之威和对故旧的侮慢之态；后二句则通过自问自答，表现了原为友人的那位先生的怨愤不平的情绪，而诗句的语气显得“怨而不怒”，很能体现“温柔敦厚”的诗教。\n\n　　此诗一开头，描述了卿大夫的服饰，可见，这位卿大夫是一位政治新秀，刚刚步入了从政的圈子。但他很不低调，以为自己了不起了，一种强烈的优越感立马就显出来了：“自我人居居。”活画出衣服傲慢无礼的神情。但他的故旧老友，虽然没有他的官阶高，但一点也不气馁，显示出很强的个性。\n\n　　从结构上来看，此诗显得十分简单，艺术上也没有太多的特色，比较明显的也就是反复吟咏、反复唱叹、回环往复的手法。这种手法实际上在《诗经》中已相当普遍，有着民歌民谣的风味，从这也正说明了《诗经》与民歌之间的密切关系。\n\n　　此外，该诗中所用的设问和作答的形式，在《诗经》中也时而可见。这种修辞方法作为讽刺或表现一种强烈的情绪是很合适的。', poem_tags = '诗经,怨刺' WHERE poem_title = '国风·唐风·羔裘' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '我原本也是个狂妄的小子，我在京城混迹于官场，这不过是因为出身于高贵门第和命运的偶然安排罢了。我真心仰慕平原君的广结贤士，希望能有赵国平原君那样招贤纳士的人来善待天下贤德才士，可是却没有谁会理解我的这片心意。万万没有想到，今天竟然遇到了您这位知己。今天，趁我们还不算老，擦去感伤的眼泪，纵酒高歌，把精神振作起来。\n　　今天我们一定要开怀畅饮，一醉方休。从古到今，才干出众、品行端正的人遭受谣言中伤，这都是常有的事，姑且由他去吧。人生岁月悠悠，难免遭受点挫折苦恼，这些都没必要放在心上，思过之后冷笑一声放在一边就完事儿了。若总是耿耿于怀，那么从人生一开始就错了。今天我们一朝以心相许，成为知己，他日即使经历千万劫难，我们的友情也要依然长存。这后半生的缘分，恐怕要到来世也难以补足。这个诺言是很沉重的，您一定要牢牢记在心里。', poem_notes = '金缕曲：词牌名。\n梁汾：顾贞观（1637～1714年），字华峰，号梁汾。江苏无锡人，纳兰性德的朋友。清康熙五年（1666年）顺天举人。著有《积书岩集》及《弹指词》。清康熙十五年（1676年）与纳兰性德相识，从此交契，直至纳兰性德病殁。\n德也狂生耳：我本是个狂放不羁的人。德，作者自称。\n偶然间，淄尘京国，乌衣门第：我在京城混迹于官场，又出身于高贵门第，这只是命运的偶然安排。淄尘京国，表居北京之无奈。淄尘，黑尘，喻污垢。此处作动词用，指混迹。淄，通“缁”，黑色。京国，京城。乌衣门第：东晋王、谢大族多居金陵乌衣巷，后世遂以该巷名指称世家大族。\n有酒惟浇赵州土：用李贺《浩歌》“买丝绣作平原君，有酒唯浇赵州土”句意，是说希望有战国时赵国平原君那样招贤纳士的人来善待天下贤德才士。浇，浇酒祭祀。赵州土，平原君墓土。\n谁会成生此意：谁会理解我的这片心意。会，理解。成生，作者自称。作者原名成德，后避太子讳改性德。\n不信道、竟逢知己：万万没有想到，今天竟然遇到了知己。\n青眼高歌俱未老：趁我们青壮盛年，纵酒高歌。青眼，契重之眼光，此指青春年少。\n向尊前、拭尽英雄泪：姑且面对酒杯，擦去英雄才有的眼泪。为二人均不得志而感伤。尊，同“樽”。\n且由他、娥眉谣诼，古今同忌：姑且由他去吧，才干出众，品行端正的人容易受到谣言中伤，这是古今常有的事。娥眉，亦作“蛾眉”，喻才能。谣诼，造谣毁谤。忌，语助词，无实义。\n身世悠悠何足问：人生岁月悠悠，遭受挫折苦恼，不必去追究。悠悠，遥远而不定貌。\n寻思起、从头翻悔：若对挫折耿耿于怀，反复寻思，那么从人生一开始就错了。\n一日心期千劫在：一日以心相许成为知己，即使经历千万劫难，我们二人的友情也将依然长存。心期：以心相许，情投意合。\n后身缘、恐结他生里：来世他生，我们的情缘还将保持。后身缘，来生情缘。\n然诺重，君须记：朋友间信用为重，您要切记。然诺重，指守信誉，不食言。', poem_appreciation = '纳兰容若写的这首“金缕曲”有个故事，他这首词是赠给好友顾梁汾的，但词中的“蛾眉谣诼，古今同忌”说的却是另一个朋友的事。这个朋友名叫吴汉槎，是当时有名的江南才子（籍贯江苏吴江），和顾梁汾及纳兰的交情都很好。顺治丁酉年，吴汉槎考中举人，但不幸得很，这场考试，由于主考官有舞弊的事情发生，闹成大狱。吴汉槎虽然是凭真才实学考中的，也受牵连，被判充军宁古塔。\n\n　　顾梁汾全力营救朋友，想尽一切方法，过了二十年之久，顺治换了康熙，仍然无济于事。纳兰容若的父亲纳兰明珠在康熙年间官封“太傅”（相当于宰相），顾梁汾就在纳兰的家里做他父亲的幕客。他在太傅府中，想起好友在边塞之地受尽寒苦，于是就写了两首金缕曲寄去给他。这是中国文学史上非常出名的两首词，被认为足可以比美李陵与苏武的‘河梁生别诗’并向秀怀念嵇康的“思旧赋”的。\n\n　　纳兰容若看了大为感动，于是也写了两阕“金缕曲”给顾梁汾。其中之一就是开篇那首，词中的“娥眉谣诼，古今同忌”指的就是那个“科场舞弊案”吴汉槎所受的冤枉事了。他又在另一首“金缕曲”的结尾说：“绝塞生还吴季子，算眼前此外皆闲事。知吾者，梁汾耳。”表示他和顾梁汾一样，所要达成的目标，就是要把吴汉槎救回来。后来他等到了一个适当的机会，求他父亲援手。纳兰明珠出了点力，朋友们大家再凑了点钱，终于把吴汉槎赎回来。时人称顾梁汾那两闺金缕曲为“赎命词”。又有个名叫顾忠的写诗记其事道：“金兰倘使无良友，关塞终当老健儿。”赞美了顾梁汾、纳兰容若和吴汉槎的友情。', poem_tags = '豪放,友情' WHERE poem_title = '金缕曲·赠梁汾' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '你如同谢公最受偏爱的女儿，嫁给我这个贫士事事不顺利。\n你见我没有衣衫就在箱子找，你拔下金钗因我相求而买酒。\n你用野蔬充饥却说食物甘美，你用落叶作薪你用枯枝做炊。\n如今我高官厚禄你却离人间，为你寄点延请僧道超度士灵。', poem_notes = '谢公东晋宰相谢安，他最偏爱侄女谢道韫。\n黔娄：战国时齐国的贫士。此自喻。言韦丛以名门闺秀屈身下嫁。百事乖：什么事都不顺遂。\n荩箧：竹或草编的箱子。\n泥：软缠，央求。\n藿：豆叶，嫩时可食。\n奠：祭奠，设酒食而祭。', poem_appreciation = '赏析 　　这首诗追忆妻子生前的艰苦处境和夫妻情爱，并抒写自己的抱憾之情。一、二句引用典故，以东晋宰相谢安最宠爱的侄女谢道韫借指韦氏，以战国时齐国的贫士黔娄自喻，其中含有对方屈身下嫁的意思。“百事乖”，任何事都不顺遂，这是对韦氏婚后七年间艰苦生活的简括，用以领起中间四句。“泥”，软缠。“长藿”，长长的豆叶。中间这四句是说：看到我没有可替换的衣服，就翻箱倒柜去搜寻；我身边没钱，死乞活赖地缠她买酒，她就拔下头上金钗去换钱。平常家里只能用豆叶之类的野菜充饥，她却吃得很香甜；没有柴烧，她便靠老槐树飘落的枯叶以作薪炊。这几句用笔干净，既写出了婚后“百事乖”的艰难处境，又能传神写照，活画出贤妻的形象。这四个叙述句，句句浸透着诗人对妻子的赞叹与怀念的深情。末两句，仿佛诗人从出神的追忆状态中突然惊觉，发出无限抱憾之情：而今自己虽然享受厚俸，却再也不能与爱妻一道共享荣华富贵，只能用祭奠与延请僧道超度亡灵的办法来寄托自己的情思。“复”，写出这类悼念活动的频繁。这两句，出语虽然平和，内心深处却是极其凄苦的。 ▲', poem_tags = '唐诗三百首,悼亡' WHERE poem_title = '遣悲怀三首·其一' AND poem_author = '元稹';
UPDATE edu_poem SET poem_translation = '身佩雕羽制成的金仆姑好箭，旌旗上扎成燕尾蝥弧多鲜艳。\n大将军威严地屹立发号施令，千军万马一呼百应动地惊天。\n\n林中昏暗风吹草动令人惊，将军夜中搭箭拉弓显神勇。\n天明寻找昨晚射的白羽箭，箭头深深插入巨大石块中。\n\n死寂之夜，乌云遮月。天边惊起一群大雁。原来敌军首领趁着夜色，悄悄逃跑。\n正想要率领轻骑一路追杀，纷纷大雪，已经洒满了将士的弓刀。\n\n在野外天幕下摆设劳军盛宴，边疆兄弟民族都来祝贺我军凯旋。\n喝醉酒后还穿着金甲起舞，欢腾的擂鼓声震动了周围的山川。\n\n逐猎前将军把箭弓调整到最佳，并召唤猎鹰前来助阵。将军威风凛凛英姿焕发的一亮相，周边均感受到将军玉树临风颇具出世之能的威风。\n逐猎者把胡飞乱窜的野鸡们赶得惊跳逃窜，猎手们把那些狼狈窜跳的猎物在这片古老的丘陵地带上一扫而光。\n\n我就像挺拔而立的七叶莲，虽然独立孤行，但胸怀坦荡，品格高洁。\n有一天能够功成名就，提名麒麟阁的话，也不借此沽名钓誉。', poem_notes = '张仆射：一说为张延赏，一说为张建封。塞下曲：古时的一种军歌。\n鹫翎：箭尾羽毛。金仆姑：神箭名。\n燕尾：旗的两角叉开，若燕尾状。蝥（máo，一说音wù）弧：旗名。\n独立：犹言屹立。扬新令：扬旗下达新指令。\n惊风：突然被风吹动。\n引弓：拉弓，开弓，这里包含下一步的射箭。\n平明：天刚亮的时候。白羽：箭杆后部的白色羽毛，这里指箭。\n没：陷入，这里是钻进的意思。石棱：石头的棱角。也指多棱的山石。\n月黑：没有月光。\n单于（chányú）：匈奴的首领。这里指入侵者的最高统帅。遁：逃走。\n将：率领。轻骑：轻装快速的骑兵。逐：追赶。\n弓刀：像弓一样弯曲的军刀。\n野幕：野外帐篷。敞：开。琼筵：美宴。\n羌戎：此泛指少数民族。\n雷鼓：大鼓，以声大如雷，故称。\n出世：一作“百中”。\n奔狐：一作“奔猨”。\n唯应独不名：一作“谁知独有名”。', poem_appreciation = '《塞下曲》为汉乐府旧题，属《横吹曲辞》，内容多写边塞征战景象。卢纶《和张仆射塞下曲六首》全系五绝，虽然受和诗的限制，但他却善于运用这种诗体。这种诗体本不必须遵用诗律，五七言皆可，但卢纶凭他出色的文才，以六首精巧的五绝组成了这部如画的佳作。这六首诗分别写发号施令、射猎破敌、奏凯庆功等等军营生活，语多赞美之意。\n\n　　组诗的第一首，歌咏边塞景物，描写将军发号时的壮观场面。前两句用严整的对仗，精心刻划出将军威猛而又矫健的形象。“鹫翎金仆姑”，是写将军的佩箭。“金仆姑”，箭名，《左传》：“乘丘之役，公以金仆姑射南宫长万。”箭用金做成，可见其坚锐。并且用一种大型猛禽“鹫” 的羽毛（“翎”）来做箭羽，既美观好看，发射起来又迅疾有力，威力无穷。“燕尾绣蝥弧”，是写将军手执的旗臶。“绣蝥弧”，一种军中用作指挥的旗臶，《左传》：“颖考叔取郑之旗蝥弧以先登。”这种象燕子尾巴形状的指挥旗，是绣制而成的，在将军手中显得十分精美。这两句没有直接写将军的形貌，只是从他身上惹人注目的佩箭、旗臶落笔，而将军的矫健身影已经屹立在读者面前。诗中特意指出勇猛的“鹫”和轻捷的“燕”这两种飞禽，借以象征人物的精神状态。通过这两句的描写、衬托，一位威武而又精明干练的军事将领的形象，跃然纸上。 后两句写发布新令。将军岿然独立，只将指挥令旗轻轻一扬，那肃立在他面前的千营军士，就齐声发出呼喊，雄壮的呐喊之声响彻云天、震动四野，显示出了豪壮的军威。“独立”二字，使前两句中已经出现的将军形象更加挺拔、高大，并且与后面的“千营”形成极为悬殊的数字对比，以表明将军带兵之多，军事地位之显要，进一步刻划了威武形象。那令旗轻轻一扬，就“千营共一呼”，在整齐而雄壮的呐喊声中，“千营”而“一”，充分体现出军队纪律的严明，以及将军平时对军队的严格训练，显示出了无坚不摧、无攻不克的战斗力。这一句看似平平叙述，但却笔力千钧，使这位将军的形象更为丰满突出，给人留下了深刻的印象。 在五言绝句中，像这首诗这样描写场面如此壮阔，声势如此浩大的作品，并不多见。前两句对仗工整，在严整中收敛力量；后两句改为散句，将内敛的力量忽然一放，气势不禁奔涌而出。这一敛一放，在极少的文字中，包孕了极为丰富的内容，显示出强大的力量。\n\n　　组诗的第二首，写将军夜猎，见林深处风吹草动，以为是虎，便弯弓猛射。天亮一看，箭竟然射进一块石头中去了。通过这一典型情节，表现了将军的勇武。诗的取材，出自《史记·李将军列传》。据载，汉代名将李广猿臂善射，在任右北平太守时，就有这样一次富于戏剧性的经历：“广出猎，见草中石，以为虎而射之。中石没镞，视之石也。因复更射之，终不能复入石矣。” 首句写将军夜猎场所是幽暗的深林；当时天色已晚，一阵阵疾风刮来，草木为之纷披。这不但交代了具体的时间、地点，而且制造了一种气氛。右北平是多虎地区，深山密林是百兽之王的猛虎藏身之所，而虎又多在黄昏夜分出山，“林暗草惊风”，着一“惊”字，就不仅令人自然联想到其中有虎，呼之欲出，渲染出一片紧张异常的气氛，而且也暗示将军是何等警惕，为下文“引弓”作了铺垫。次句即续写射。但不言“射”而言“引弓”，这不仅是因为诗要押韵的缘故，而且因为 “引”是“发”的准备动作，这样写能启示读者从中想象、体味将军临险是何等镇定自若，从容不迫。在一“惊”之后，将军随即搭箭开弓，动作敏捷有力而不仓皇，既具气势，而形象也益鲜明。后二句写“没石饮羽”的奇迹，把时间推迟到翌日清晨（“平明”），将军搜寻猎物，发现中箭者并非猛虎，而是蹲石，令人读之，始而惊异，既而嗟叹，原来箭杆尾部装臵着白色羽毛的箭，竟“没在石棱中”，入石三分。这样写不仅更为曲折，有时间、场景变化，而且富于戏剧性。“石棱”为石的突起部分，箭头要钻入殊不可想象。神话般的夸张，为诗歌形象涂上一层浪漫色彩，读来特别尽情够味，只觉其妙，不以为非。\n\n　　组诗的第三首。诗由写景开始：“月黑雁飞高”。这样的景是难于刻画的：“月黑”，则茫无所见；“雁飞高”，则无迹可寻。雁飞而且高。是由声音觉察到的。这样的景，并非眼中之景，而是意中之景。雪夜月黑，本不是雁飞的正常时刻。而宿雁惊飞，正透露出敌人正在行动。寥寥五字，既交待了时间，又烘托了战斗前的紧张气氛，直接逼出下句“单于夜遁逃”来。单于本是古匈奴的君主，这里借指敌军统帅。敌军在夜间行动，应当有各种可能。然而诗人但谓“单于夜遁逃”。读诗至此，顿觉一股豪迈之情扑面而来。敌人夜间行动，并非率兵来袭，而是借夜色的掩护仓惶逃遁。诗句语气肯定，判断明确，充满了对敌人的蔑视和我军必胜的信念，足令读者为之振奋，于上句造成的神秘气氛中，发一惊采。敌酋遁去，我军纵兵追擒，这是自然的发展。“欲将轻骑逐”，是追兵将发而未发。不用大军而仅派“轻骑”，绝不仅仅因为快捷，同时也还显示厂一种高度的自信。仿佛敌人已是瓮中之鳖，只须少量“轻骑”追剿。便可手到擒来。当勇士们列队准备出发时。虽然站立不过片刻．而大雪竟落满弓刀。“大雪满弓刀”一句，又发惊采，将全诗意境推向高潮。在茫茫的夜色中，在洁白的雪地上，一支轻骑兵正在集结，雪花顷刻便落满了他们全身，遮掩了他们武器的寒光。他们就象一支支即将离弦的箭。虽然尚未出发，却早就满怀着必胜的信心。这是一幅非常动人的画图：在静谴中蕴藏着呐喊，在昏暗中酝酿着闪电。虽然是在漆黑的夜间，勇士们被白雪勾画出的英姿仍然是“焕尔触目”。“离首即尾、离尾即首”虽然是绝句的难点，但诗人倘能大胆剪裁，巧妙构思，抓住典型环境与典型场景，完全能够写出精采的佳作。\n\n　　组诗的第四首，描写边防将士取得重大胜利后，边地兄弟民族在营帐前设宴劳军的场面，气氛热烈融洽，同时也描绘了将士“醉和金甲舞”的欢乐神态，赞颂了边地人民和守边将士团结一心，保卫国家安宁与统一的豪迈气概，也说明了将士们的得到兄弟民族的支持的。此诗取材典型，剪裁大胆，洋溢着民族间和睦团结的气氛。全诗语言精炼含蓄，情态活跃鲜明，写得慷慨而豪迈，爽朗而明快。\n\n　　组诗的第五首，描述的是将士们利用战事顺利边关稍靖的时机乘兴逐猎的情景。字面上是说边关将士在敌人遁逃后，利用暂时的战事稍歇进行狩猎，其实饱含了诗人对将士们豪情满怀的钦佩、颂扬和祝福。\n\n　　组诗的第六首，则是颂扬了将士们只为保疆安民，不求功名利禄的高尚情怀。由于诗中多有双关，古今后人对此有各种不同的解释。或说七叶莲喻淡泊功名，或说七叶莲象征特立独行，莫衷一是。\n\n　　卢纶所和张仆射原诗今已不传，而和诗竟流诵千古，可见它的价值经得起历史的检验。胡震亨《唐音癸笺》卷七谓：“大历十才子，并工五言诗。卢郎中（纶）辞情捷丽，所作尤工。”又说：“卢诗开朗，不作举止，陡发惊采，焕尔触目。”组诗语言凝练，构思巧妙，细吟全诗，军营之生活，守边之艰苦，胜利之欢腾，无不历历在目，令人感奋。', poem_tags = '边塞,军旅,将士' WHERE poem_title = '和张仆射塞下曲六首' AND poem_author = '卢纶';
UPDATE edu_poem SET poem_translation = '分手之日容易，岂料相见之日如此难，山长路远，天各一方。想念他以致忧思聚集，却不敢说出口，为解相思之情，想托飘荡之浮云寄去问讯的书信，但浮云一去而不见踪影。整日以泪洗面，使得自己的容颜很快老去。百忧在心，谁能不独自感叹啊！唯有浅吟低唱怀人幽思的《燕歌行》，来聊自宽解一下，可是，欢愉难久，忧戚继之。夜深了，忧思煎熬难以入眠，只有披衣出去，徘徊于中庭。抬头看云间星绕月明，然而人却没有团圆。可怜晨雾中飞鸽发出阵阵鸣叫声，留恋徘徊不能慰存。', poem_notes = '郁陶：忧思聚集。\n耿耿：犹言炯炯，耿耿不寐的意思。', poem_tags = '乐府,写鸟,抒情,相思' WHERE poem_title = '燕歌行二首·其二' AND poem_author = '曹丕';
UPDATE edu_poem SET poem_translation = '注释 粉堕：形容柳絮飘落。百花洲：指百花盛开处。 燕子楼：相传是唐代女子关盼盼所居之处。这里泛指女子所居的“绣楼”。 缱绻：情意深挚，难舍难分。 说风流：意即空有风流之名。 “嫁与东风”句：柳絮被东风吹落，春天不管。自喻无家可依、青春将逝而无人同情。', poem_tags = '婉约,柳树,感叹,命运' WHERE poem_title = '唐多令·柳絮' AND poem_author = '曹雪芹';
UPDATE edu_poem SET poem_tags = '宋词三百首,宋词精选,婉约,追忆,离别' WHERE poem_title = '蝶恋花·醉别西楼醒不记' AND poem_author = '晏几道';
UPDATE edu_poem SET poem_translation = '我就像王粲在灞陵上眺望长安，又像潘岳在河阳回顾洛阳那样登上三山回望京城。\n夕阳使飞耸的屋脊色彩明丽，京城内的屋宇高低不齐，历历在目。\n残余的晚霞铺展开来就像彩锦，澄清的江水平静得如同白练。\n喧闹的群鸟覆盖了春天的小洲，各种花朵开满了芳草遍地的郊野。\n我将远离京城在他乡久留，真怀念那些已停办的欢乐宴会。\n回乡的日期在何时，我惆怅不已泪落如雪珠。\n有感情的人都知道思念家乡，谁的黑头发能不改变？', poem_notes = '三山：山名，在今南京市西南。还望：回头眺望。京邑：指南齐都城建康，即今南京市。\n灞，水名，源出陕西蓝田，流经长安城东。河阳视京县：借用西晋诗人潘岳《河阳县诗》“引领望京室” 诗意。河阳：故城在今河南梦县西。京县：指西晋都城洛阳。两句意为：我怀着眷恋之情，傍晚登上三山，回头眺望都城建康。\n丽：使动用法，这里有“照射使……色彩绚丽”的意思。飞甍：上翘如飞翼的屋脊。甍：屋脊。参差：高下不齐的样子。\n绮：有花纹的丝织品，锦缎。澄江：清澈的江水。练：洁白的绸子。喧鸟覆春洲：形容鸟儿众多。覆：盖。杂英：各色的花。甸：郊野。\n方：将。滞淫：久留。淹留。怀：想念。\n佳期：指归来的日期。怅：惆怅。霰：雪珠。两句意为：分别了，想到何日才能回来，不由得令人惆怅悲伤，留下雪珠般的眼泪。\n鬒：黑发。变：这里指变白。两句意为：怀着望乡之情的人，又有谁能不白了头发呢？', poem_appreciation = '唐代伟大诗人李白的诗句“月下沉吟久不归，古来相接眼中稀。解道澄江静如练，令人长忆谢玄晖。”（李白《金陵城西楼月下吟》），吟哦的是南齐诗人谢朓的名句。金陵城（今南京）西楼前的美景使李白深深领悟了“澄江静如练”的意境，追忆前贤，这位大诗人不禁发出了古来知音难遇的长叹。然而李白应未想到，由于他的叹赏，谢朓这句诗却在后世得到了无数的知音。\n\n　　《晚登三山还望京邑》是一首五言古诗，抒写诗人登上三山时遥望京城和大江美景引起的思乡之情。\n\n　　这首诗应作于公元495年（齐明帝建武二年），谢朓出为宣城太守时。在这次出守途中，他还做了一首题为《之宣城出新林浦向板桥》的古诗，据《水经注》记载，江水经三山，从板桥浦流出，可见三山当是谢朓从京城建康到宣城的必经之地。三山因上有三峰、南北相接而得名，位于建康西南长江南岸，附近有渡口，离建康不远，相当于从灞桥到长安的距离。此诗开头借用王粲《七哀诗》“南登霸陵岸，回首望长安”的意思，形容他沿江而上，傍晚时登上江岸的三山回望建康的情景，十分贴切。“河阳视京县”一句从字面上看似乎与上句语意重复，其实不然。这儿借用潘岳《河阳诗》“引领望京室”句暗示自己此去宣城为郡守，遥望京邑建康，正如西晋的潘岳在河阳为县令，遥望京城洛阳一样。王粲的《七哀诗》作于汉末董卓被杀，李傕、郭汜大乱长安之时，他在灞涘回望长安，所抒发的不仅是眷恋长安的乡情，更有向往明王贤伯、重建清平之治的愿望。谢朓这次出守之前，建康一年之内换了三个皇帝，也正处在政治动荡不安的局面之中。因此首二句既交代出离京的原因和路程，又借典故含蓄地抒写了诗人对京邑眷恋不舍的心情，以及对时势的隐忧。\n\n　　首二句领起望乡之意，以下六句写景，六句写情。诗人扣住题意，选取富有特征性的景物，将登临所见层次清楚地概括在六句诗里。远远望去，皇宫和贵族第宅飞耸的屋檐高低不齐，在日光照射下清晰可见。只“白日丽飞甍，参差皆可见”两句，便写尽满城的繁华景象和京都的壮丽气派。此处“白日”指傍晚的日光。“丽”字本有“附著”、“明丽”两个意思，这里兼取二义，描绘出飞甍在落日中愈加显得明丽辉煌的情景，可以见出谢朓炼字的功夫。“参差”二字既写京城宫殿楼阙的密集，又使整个画面显得错落有致。“皆可见”三字则暗中传达出诗人神情的专注：既然全城飞甍都历历可见，那么从中辨认自己的旧居当也是一般登高望乡之人的常情。所以这两句虽是写景，却隐含着一个凝目远眺的抒情主人公的形象。诗人没有点明在山上流连凝望的时间有多久，但从“白日”变为“余霞”的景色转换中自然就显示出时辰的推移过程。\n\n　　“余霞散成绮，澄江静如练”二句，描写白日西沉，灿烂的余霞铺满天空，犹如一匹散开的锦缎，清澄的大江伸向远方，仿佛一条明净的白绸。这一对比喻不仅色彩对比绚丽悦目，而且“绮”、“练”这两个喻象给人以静止柔软的直觉感受，也与黄昏时平静柔和的情调十分和谐。“静”字一作“净”，亦佳。明人谢榛曾批评“澄”、“净”二字意思重复，想改成“秋江净如练”。另一位诗论家王世贞不以为然，认为江澄之后才谈得上净。清代诗人王士祯也讥讽谢榛说:“何因点窜‘澄江练’？笑杀谈诗谢茂秦！”（《论诗绝句》）其实，如果没有谢榛窜改，这“澄”字的好处还真容易被人忽视。唯其江水澄清，“净”（或“静”）字才有着落，才能与白练的比喻相得益彰。同时，“澄”净的江水还能唤起天上云霞与水中倒影相互辉映的联想。李白在《金陵城西楼月下吟》中引用“澄江静如练”以形容大江沉浸在月光之中的清空透明之感，“澄”字就更有点晴意义。可见“静如练”这一比喻是因为有了“澄”字的衬托，才成功地表现出大江宁静澄澈的境界。“静”与“净”相比，“静”字写境更为传神。唐代徐凝曾用白练来比喻瀑布:“千古长如白练飞，一条界破青山色。”被王世贞讥为“恶境界”，原因就在用静态的白练来形容飞泻的水瀑，反将活景写呆了。这个例子可以帮助读者从反面体味“静如练”的好处。如果将谢朓这两句诗与谢灵运的“云日相辉映，空水共澄鲜”（《登江中孤屿》）相比较，可以看出谢朓在景物描写上的飞跃。谢灵运以直叙的手法来说明水天辉映、空明澄澈的景象，意思较实。而谢朓则能够利用恰当的比喻进行形容，使水天相映的景象不但有鲜明悦目的色彩，并能融进主人公对景物情调的感受，表达更为空灵。\n\n　　如果说“余霞”两句是用大笔晕染江天的景色，那么“喧鸟覆春洲，杂英满芳甸”两句则是以细笔点染江洲的佳趣。喧闹的归鸟盖满了江中的小岛，各色野花开遍了芬芳的郊野。群鸟的喧嚷越发衬出傍晚江面的宁静，遍地繁花恰似与满天落霞争美斗艳。鸟儿尚知归来，而人却离乡远去，何况故乡正满目春色如画，直教人流连难舍。\n\n　　无怪诗人叹息:“去矣方滞淫，怀哉罢欢宴。”这两句巧用此处字义可作两解的特点，既抒发了将要久客在外的离愁和对旧日欢宴生活的怀念，又写出了诗人已去而复又半途迟留、因怀乡而罢却欢宴的情态。“去矣”、“怀哉”用虚词对仗，造成散文式的感叹语气，增强了声情摇曳的节奏感。\n\n　　至此登临之意已经写尽，往下似乎无可再写。但诗人却巧妙地跳过一步，由眼前对京城的依恋之情，想到此去之后还乡遥遥无期，泪珠像雪糁般散落在胸前，感情便再起一层波澜。“有情知望乡，谁能鬒不变”则又由自己的离乡之苦，推及一般人的思乡之情：人生有情，终知望乡。长此以往，谁也不能担保黑发不会变白。结尾虽写远忧，而实与开头呼应，仍然归到还望的本意，而诗人的情绪也在抒发人生感慨之时跌落到最低点。\n\n　　这首诗写景色调绚烂纷繁、满目彩绘，写情单纯柔和，轻清温婉。诗人将京邑的黄昏写得如此明丽美好，毫无苍凉暗淡之感，固然是为了渲染他对故乡的热爱，但也与诗中所表现的游宦怀乡之情并无深永的感伤意味有关。全诗结构完整对称，而给人印象最深的则是“余霞散成绮，澄江静如练”两句。这种情景分咏、名句往往突出于一篇之中的现象是宋齐山水诗还处于早期阶段的共同特点，也与谢朓诗存在着钟嵘所说“篇末多踬”的毛病有关。谢朓山水诗仍然沿袭谢灵运前半篇写景、后半篇抒情的程式。由于思想感情贫乏，没有远大的理想和志趣，后半篇的抒情大多缺乏健举的风力，加之又“专用赋体”，直陈其意，不像写景那样凝炼形象，更觉意弱而文散。此篇结尾情绪柔弱消沉，便与前面所写的壮丽开阔的景色稍觉不称。但尽管如此，他在景物剪裁方面的功力，以及诗风的清丽和情韵的自然，却标志着山水诗在艺术上的成熟，对唐人有很大的影响。所以李白每逢胜景，常“恨不能携谢朓惊人诗句来”（《云仙杂记》），“解道澄江静如练”只是这类佳话中的一例而已。', poem_tags = '古诗三百首,写景,山水,思乡' WHERE poem_title = '晚登三山还望京邑' AND poem_author = '谢朓';
UPDATE edu_poem SET poem_translation = '夕，阴历七月七日，相传为牛郎渡过银河与织女为一年一度相会。这天晚上，民间陈列瓜果，穿针乞巧。这首诗就是写七夕的。首联：“络角星河菡萏天，一家欢笑设红筵。”角是二十八宿中的角宿，络是网络，当指雾气网络在角宿上。星河，天上的银河，是分离牛郎织女的。菡萏天，是荷花盛开的天气。大概想象牛郎织女在银河边看到角宿和荷花。这是说的天上情景。下句指人间，有一家人家欢笑地在院子里铺置红布的筵席，摆上瓜果，来穿针乞巧。\n\n　　次联：“应倾谢女珠玑箧，尽写檀郎锦绣篇。”谢女檀郎，泛指女子和男子。这家的女子把箧中的珠子倒空，要这家的男子写出歌咏七夕的锦绣诗篇，放到那个箧里。这里就要写七夕的诗', poem_appreciation = '七夕，阴历七月七日，相传为牛郎渡过银河与织女为一年一度相会。这天晚上，民间陈列瓜果，穿针乞巧。这首诗就是写七夕的。首联：“络角星河菡萏天，一家欢笑设红筵。”角是二十八宿中的角宿，络是网络，当指雾气网络在角宿上。星河，天上的银河，是分离牛郎织女的。菡萏天，是荷花盛开的天气。大概想象牛郎织女在银河边看到角宿和荷花。这是说的天上情景。下句指人间，有一家人家欢笑地在院子里铺置红布的筵席，摆上瓜果，来穿针乞巧。\n\n　　次联：“应倾谢女珠玑箧，尽写檀郎锦绣篇。”谢女檀郎，泛指女子和男子。这家的女子把箧中的珠子倒空，要这家的男子写出歌咏七夕的锦绣诗篇，放到那个箧里。这里就要写七夕的诗而言。玑：小珠。三联：“香帐簇成排窈窕，金针穿罢拜婵娟。”上一句指天上，香帐制作成功，安排得很美好。李商隐《无题》：“凤尾香罗薄几重，碧文圆顶夜深缝。”这是制作结婚用的圆帐。牛郎织女相会，也要制作圆帐。簇是指丛聚成团，把香罗几重叠起来缝制圆顶帐子，正是丛聚成团，故称簇。窈窕，状美好。“排窈窕”，既指安排得很好，也指安排好织女，窈窕也指女子的美好。这联下一句指人间，那家人家的妇女引线穿针来乞巧。穿好针来拜美好的织女星。婵娟，美好，指织女星。牛郎织女在七夕相会，古代计时的铜壶滴漏报天将亮了，牛郎织女又要分别了，所以惆怅茫然，这样相会的佳期又要等一年。\n\n　　这首诗的特点是用对比写法，第一句写天上的景物，第二句写人间的情状，有景物，又有欢笑，构成天上与人间相对照。二联专写人间，不提七夕，在“锦绣篇”里暗指咏七夕。三联又是对照写法，“香帐簇成”指天上，“金针穿罢”指人间。“铜壶漏报”二句指天上。此外，第一联写人间“欢笑”，与第四联写天上惆怅相对。一乐一悲，构成映衬。再像写谢女的空出箧子来装檀郎的锦绣篇，写人间男女在七夕的欢乐，又与牛郎织女的临别惆怅构成映衬。在这样的映衬里，就是衬出天上不如人间了。再就写天上或人间的词句来看，首句、五句、七句、八句写天上，二句、三句、四句、六句写人间，即四句写天上，四句写人间。但这首诗题为《七夕》，应以写牛郎织女相会为主，因此使人感到作者还是看重人间，所以这样安排。作者写人间的欢乐胜过天上，在当时有这样的想法，是非常难得的。', poem_tags = '七夕节' WHERE poem_title = '七夕' AND poem_author = '罗隐';
UPDATE edu_poem SET poem_translation = '你守卫在边关，我却在吴地，凉飕飕的西风吹到我身上的时候，我正在为你而担忧。\n我寄上一封简短的书信，信中每一行字上都浸透了我的眼泪，寒气来到你身边的时候，我寄出的寒衣不知收到没有？', poem_notes = '妾：旧时妇女自称。\n吴：指江苏一带。', poem_tags = '女子,思念,关怀' WHERE poem_title = '寄外征衣' AND poem_author = '陈玉兰';
UPDATE edu_poem SET poem_translation = '听着凄风苦雨之声，我独自寂寞地过着清明。掩埋好遍地的落花，我满怀忧愁地起草葬花之铭。楼前依依惜别的地方，如今已是一片浓密的绿荫。每一缕柳丝，都寄托着一分柔情。料峭的春寒中，我独自喝着闷酒，想借梦境去与佳人重逢，不料又被啼莺唤醒。\n西园的亭台和树林，每天我都派人去打扫干净，依旧到这里来欣赏新晴的美景。蜜蜂频频扑向你荡过的秋千、绳索上还有你纤手握过而留下的芳馨。我是多么惆怅伤心，你的倩影总是没有信音。幽寂的空阶上，一夜间长出的苔藓便已青青。', poem_notes = '草：草，起草，拟写。愁草，没有心情写。\n瘗（yì）：埋葬。铭，文体的一种。庾信有《瘗花铭》。古代常把铭文刻在墓碑或者器物上，内容多为歌功颂德，表示哀悼，申述鉴戒。\n分携：分手，分别。\n绿暗：形容绿柳成荫。\n料峭：形容春天的寒冷。\n中酒：醉酒。“中酒”见《史记·樊哙传》，亦见《汉书》，意酒酣也。中，读仄声也。又如杜牧：“残春杜陵客，中酒落花前”（《睦州四韵》），\n交加：形容杂乱。\n双鸳：指女子的绣花鞋，这里兼指女子本人。', poem_appreciation = '这是西园怀人之作。西园在吴地，是梦窗和情人的寓所，二人亦在此分手，所以西园诚是悲欢交织之地。梦窗在此中常提到此地，可见此地实乃梦萦魂绕之地。\n\n　　这也是一首伤春之作。词的上片情景交融，意境有独到之处。前二句是伤春，三、四两句写伤别，五、六两句则是伤春与伤别的交融，形象丰满，意蕴深邃。“听风听雨过清明”，起句貌似简单，不象梦窗绵丽的风格，但用意颇深。不仅点出时间，而且勾勒出内心细腻的情愫。\n\n　　寒食、清明凄冷的禁烟时节，连续刮风下雨，意境凄凉。风雨不写“见”而写“听”，意思是白天对风雨中落花，不忍见，但不能不听到；晚上则为花无眠、以听风听雨为常。首句四个字就写出了词人在清明节前后，听风听雨，愁风愁雨的惜花伤春情绪，不由让读者生凄神憾魄之感。“愁草瘗花铭”一句紧承首句而来，意密而情浓。落花满地，将它打扫成堆，予以埋葬，这是一层意思；葬花后而仍不安心，心想应该为它拟就一个瘗花铭，瘐信有《瘗花铭》，此借用之，这是二层意思；草萌时为花伤心，为花堕泪，愁绪横生，故曰“愁草”，这是三层意思。词人为花而悲，为春而伤，情波千叠，都凝炼在此五字中了。“楼前绿暗分携路，一丝柳，一寸柔情”，是写分别时的情景。梦窗和情人在柳丝飘荡的路上分手，自此柳成为其词中常出现的意象。古代有送别时折柳相送的风俗，是希望柳丝能够系住将要远行的人，所以说“一丝柳，一寸柔情”，可谓语浅意深。\n\n　　“料峭春寒中酒，交加晓梦啼莺”，伤春又伤别，无以排遣，只得借酒浇愁，希望醉后梦中能与情人相见。无奈春梦却被莺啼声惊醒。这是化用唐诗“打起黄莺儿，莫教枝上啼。啼时惊妾梦，不得到辽西”之意。上阙是愁风雨，惜年华，伤离别，意象集中精炼，而又感人至深，显出密中有疏的特色。\n\n　　下阙写清明已过，风雨已止，天气放晴了。阔别已久的情人，怎么能忘怀！按正常逻辑，因深念情人，故不忍再去平时二人一同游赏之处了，以免触景生悲，睹物思人。但梦窗却用进一层的写法，那就是照样（依旧）去游赏林亭。于是看到“黄蜂频扑秋千索”，仿佛佳人仍在。“黄蜂”二句是窗梦词中的名句，妙在不从正面写，而是侧面烘托，佳人的美好形象凸现出来。怀人之情至深，故即不能来，还是痴心望着她来。“日日扫林亭”，就是虽毫无希望而仍望着她来。离别已久，秋千索上的香气未必能留，但仍写黄蜂的频扑，这不是在实写。陈洵说：“见秋千而思纤手，因蜂扑而念香凝，纯是痴望神理。”\n\n　　结句“双鸳不到”（双鸳是一双乡绣有鸳鸯的鞋子），明写其不再惆怅。“幽阶一夜苔生”，语意夸张。不怨伊人不来，而只说“苔生”，可见当时伊人常来此处时，阶上是不会生出青苔来的，此时人去已久，所以青苔滋生，但不说经时而说“一夜，”由此可见二人双栖之时，欢爱异常，仿佛如在昨日。这样的夸张，在事实上并非如此，而在情理上却是真实的。', poem_tags = '宋词三百首,宋词精选,婉约,伤春,离别,怀人' WHERE poem_title = '风入松·听风听雨过清明' AND poem_author = '吴文英';
UPDATE edu_poem SET poem_translation = '陵墓上长得青翠的柏树，溪流里堆聚成堆的石头。\n人生长存活在天地之间，就好比远行匆匆的过客。\n区区斗酒足以娱乐心意，虽少却胜过豪华的宴席。\n驾起破马车驱赶着劣马，照样在宛洛之间游戏着。\n洛阳城里是多么的热闹，达官贵人彼此相互探访。\n大路边列夹杂着小巷子，随处可见王侯贵族宅第。\n南北两个宫殿遥遥相望，两宫的望楼高达百余尺。\n达官贵人们虽尽情享乐，却忧愁满面不知何所迫。\n\n英译\nGreenGreen,theCypressontheRidge\nGreengreenthecypress*ontheridge,\nstonesheapedaboutinmountainstreams:\nbetweenheavenandearthourlivesrushpast\nliketravelerswithalongroadtogo.\nLetthismeasureofwinebeourmerriment;\nvalueithighly,withoutdisdain.\nIracethecarriage,whipthelagginghorses,\nroamforpleasuretoWanandLo**.\nHereinLo-yang,whatsurgingcrowds,\ncappedandbeltedoneschasingeachother;\nlongavenuesfringedwithnarrowalleys,\nthemanymansionsofprincesandpeers.\nTheTwoPalacesfaceeachotherfromafar,\npairedtowersoverahundredfeettall.\nLetthefeastlastforever,delighttheheart--\nthenwhatgrieforgloomcanweighusdown?', poem_notes = '青青：本意为蓝色，引申为深绿色，这里的“青青”，犹言长青青，是说草木茂盛的意思。陵：表示与地形地势的高低上下有关，此处指大的土山或墓地。柏：四季常青的树木，可供建筑及制造器物之用。\n磊：众石也，即石头多。会意字，从三石。\n生：生长，生活。\n忽：本义为不重视、忽略，此处指快的意思。远行客：在此有比喻人生的短暂如寄于天地的过客的意思。客，表示与家室房屋有关，本义为寄居、旅居、住在异国他乡。此句言人在世上，为时短暂，犹如远道作客，不久得回去。\n斗酒：指少量的酒。\n薄：指酒味淡而少。\n驽马：本义为劣马，走不快的马。亦作形容词，比喻才能低劣。\n宛：南阳古称宛，位于河南西南部，与湖北、陕西接壤，因地处伏牛山以南，汉水之北而得名。洛：洛阳的简称。\n郁郁：盛貌，形容洛中繁盛热闹的气象。\n冠带：顶冠束带者，指京城里的达官显贵。冠带是官爵的标志，用以区别于平民。索：求访。\n衢：四达之道，即大街。夹巷：央在长衢两旁的小巷。\n第：本写作“弟”。本义为次第、次序，此指大官的住宅。\n两宫：指洛阳城内的南北两宫。\n阙：古代宫殿、祠庙或陵墓前的高台，通常左右各一，台上起楼观，二阙之间有道路。亦为宫门的代称。\n极宴：穷极宴会。\n戚：忧思也。迫：逼近。', poem_appreciation = '这首诗与《古诗十九首》中的另一首《驱车上东门》在感慨生命短促这一点上有共同性，但艺术构思和形象蕴含却很不相同。《驱车上东门》的主人公望北邙而生哀，想到的只是死和未死之前的生活享受；这首诗的主人公游京城而兴叹，想到的不止是死和未死之时的吃好穿好。\n\n　　开头四句，接连运用有形、有色、有声、有动作的事物作反衬、作比喻，把生命短促这样一个相当抽象的意思讲得很有实感，很带激情。主人公独立苍茫，俯仰兴怀：向上看，山上古柏青青，四季不凋；向下看，涧中众石磊磊，千秋不灭。头顶的天，脚底的地，当然更其永恒；而生于天地之间的人呢，却像出远门的旅人那样，匆匆忙忙，跑回家去。《文选》李善注引《尸子》《列子》释“远行客”：“人生于天地之间，寄也。寄者固归。”“死人为‘归人’，则生人为‘行人’。”《古诗》中如“人生寄一世”，“人生忽如寄”等，都是不久即“归”（死）的意思。\n\n　　第五句以下，写主人公因感于生命短促而及时行乐。“斗酒”虽“薄”，也可娱乐，就不必嫌薄，姑且认为厚吧！驽马虽劣，也可驾车出游，就不必嫌它不如骏马。借酒销忧，由来已久；“驾言出游，以写我忧”（《诗经·邶风·泉水》），也是老办法。这位主人公，看来是两者兼用的。“宛”（今河南南阳）是东汉的“南都”，“洛”（今河南洛阳）是东汉的京城。这两地，都很繁华，何妨携“斗酒”，赶“驽马”，到那儿去玩玩。接下去，用“何郁郁”赞叹洛阳的繁华景象，然后将笔触移向人物与建筑。“冠带自相索”，达官显贵互相探访，无非是趋势利，逐酒食，后面的“极宴娱心意”，就明白地点穿了。“长衢”（大街），“夹巷”（排列大街两侧的胡同），“王侯第宅”，“两宫”，“双阙”，都不过是“冠带自相索”，“极言娱心意”的场所。主人公“游戏”京城，所见如此，会有什么感想呢？结尾两句，就是抒发感想的，可是歧解纷纭，各有会心，颇难作出大家都感到满意的阐释。有代表性的歧解是这样的： 一云结尾两句，都指主人公。“极宴”句承“斗酒”四句而来，写主人公享乐。 一云结尾两句，都指“冠带”者。“是说那些住在第宅、宫阙的人本可以极宴娱心，为什么反倒戚戚忧惧，有什么迫不得已的原因呢？”一云结尾两句，分指双方。“豪门权贵的只知‘极宴娱心’而不知忧国爱民，正与诗中主人公戚戚忧迫的情形形成鲜明对照”（《两汉文学史参考资料》）。\n\n　　从全诗章法看，分指双方较合理，但又绝非忧乐对照。“极宴”句承写“洛中”各句而来，自然应指豪权贵。主人公本来是因生命短促而自寻“娱乐”、又因自寻“娱乐”而“游戏”洛中的，结句自然应与“娱乐”拍合。当然，主人公的内心深处未尝不“戚戚”，但口上说的毕竟是“娱乐”，是“游戏”。从“斗酒”“驽马”诸句看，特别是从写“洛中‘所见诸句看，这首诗的主人公，其行乐有很大的勉强性，与其说是行乐，不如说是借行乐以销忧。而忧的原因，也不仅是生命短促。生当乱世，他不能不厌乱忧时，然而到京城去看看，从“王侯第宅”直到“两宫”，都一味寻欢作乐，醉生梦死，全无忧国忧民之意。自己无权无势，又能有什么作为，还是“斗酒娱乐”，“游戏”人间吧！“戚戚何所迫”，即何所迫而戚戚，是反诘句，如果用现代汉语肯定语气说，便是：没有什么迫使我戚戚不乐。全诗内涵，本来相当深广；用这样一个反诘句作结，更其余味无穷。', poem_tags = '古诗十九首,感叹,生命' WHERE poem_title = '青青陵上柏' AND poem_author = '佚名';
UPDATE edu_poem SET poem_tags = '抒情,思念,故国' WHERE poem_title = '忆江南·多少泪' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '注释 ① 吊：哀悼。 ② “童子”二句重点突出白居易的两篇代表作《长恨歌》《琵琶行》。', poem_appreciation = '作为一国之君的皇帝为一位诗人作悼亡诗，这在古代是非常罕见的。由此可见唐宣宗李忱对白居易其人的器重、对其诗的喜爱，也从侧面表现出了白居易卓越的才能。\n\n　　诗的首联运用比喻，巧妙概括了白居易一生的艺术成就。“缀玉联珠”是形容他诗文的艳丽光彩，而“六十年”，则指他的创作生涯。“诗仙”，是溢美之辞，是对白居易的高度评价。\n\n　　“谁教冥路作诗仙”一句其悲可见，其哀可闻。唐宣宗是说，对于这位世间不可多得的诗仙，我敬重不够、仰慕不够呀！你怎么就突然间走到冥路上去了呢？读到这里，读者似乎可以看到一位多情的皇帝，正眼含热泪，仰望长天，低声呼唤，令人感动。\n\n　　诗的颔联则表达了诗人无比惋惜之情。唉！浮云，造化也没有办法挽留住白乐天了，他永远地去了，我又有什么回天之力呢？只有扼腕长叹罢了。这里运用对仗和互文的修辞，将作者对白居易的浓浓思念之情凝聚在精练的语句中，情愫深，意韵长。\n\n　　接下来的颈联，借白居易的两篇代表作《长恨歌》与《琵琶行》来赞美他的艺术成就与巨大的影响力。“童子解吟”“胡儿能唱”蕴涵深意：其诗所知人多，所晓域广，通俗易懂，音韵和谐，圆润悦耳。作者没有直接说他的诗多么美、多么富有魅力，而只让读者自己去品味。\n\n　　尾联则进一步直接表达了作者对白居易的器重、难以割舍和对白居易去世的无比悲怆之情。这是在颈联基础上的更进一步，“文章已满行人耳”，白居易的诗如风一般流行，与行人形影不离：你只要出行在外，就能听到吟诵白诗的声音。而作者听到吟诵之声，就会牵动起思念白居易的感情，内心充满无比悲伤与哀痛。\n\n　　全诗语言通俗凝练，感情真挚，既表现了对白居易仙逝的哀痛，又表现了对他诗歌的赞赏，同时突出了白诗非同凡响的艺术成就。', poem_tags = '悼亡' WHERE poem_title = '吊白居易' AND poem_author = '李忱';
UPDATE edu_poem SET poem_translation = '破窑赋》透出的是人生命运和天地自然变化循环的思想，文章以自己从凄惨到富贵的经历，列举了自古以来历史上诸多名人经历的各种命运和磨难，摆事实讲道理，来说明这世界人生命运的起起落落。\n\n　　人生的始与终，在无运与有运、得时与失时的这种天地时空自然变化循环中，会产生天差地别和意想不到的人为和自然变化。只有经历过太多苦难沧桑和大起大伏的人才能够体会到最深刻地天道无常和人情冷暖的巨大变化，才会体会到在人困、人为和天地自然变化循环中，命运的巨烈地沉浮与很多人生无奈的结局。\n\n　　吕蒙正寻求的是他的听天地循环变化、富贵不可尽用，贫贱不可自欺的的人困人为的人生智慧。开篇就', poem_tags = '劝诫,人生,思想' WHERE poem_title = '破窑赋 / 寒窑赋 / 劝世章' AND poem_author = '吕蒙正';
UPDATE edu_poem SET poem_translation = '注释 炼金丹--指修仙求道。从禅--信佛念经。 商贾--经商。耕田--务农。 写就青山卖--指卖画。', poem_tags = '古诗三百首,言志' WHERE poem_title = '言志' AND poem_author = '唐寅';
UPDATE edu_poem SET poem_translation = '说是梨花又不是。道是杏花也不是。花瓣白白又红红，风韵独特有情趣。曾记得。曾记得。武陵渔人被陶醉。', poem_notes = '道是梨花不是：说它是梨花它又不是梨花，梨花是白色的，所以看到白色的桃花这样说。道，说。\n白白：这里指白色的桃花。\n红红：这里指红色的桃花。\n东风：春风。\n武陵（líng）：郡名，郡治在今湖南省常德县境。陶渊明《桃花源记》曾写到武陵渔者发现世外桃源的事，这里“武陵”也有世外桃源的意思。', poem_tags = '咏物,桃花,言志' WHERE poem_title = '如梦令·道是梨花不是' AND poem_author = '严蕊';
UPDATE edu_poem SET poem_translation = '绵绵的细雨微微的风，千家万户掩映在杨柳密荫青烟绿雾中。淋湿的花瓣贴在树枝上不再飞。心中愁无穷，连同春色都付与江水流向东。\n九十天的光阴能够留多久？解尽金龟换酒也无法将春光挽留。告诉那东阳城里卖酒人，而今只求拼个一醉方休，不管今日乐事成为他年热泪流。', poem_notes = '渔家傲：词牌名。\n纤纤：细小，细微，多用以形容微雨。\n和春：连带着春天。\n九十：指春光三个月共九十天。\n金龟：唐三品以上官佩金龟。此处“金龟解尽”意即彻底解职。\n东阳：今浙江省金华市，宋属婺（wù）州东阳郡。沽酒：卖酒。\n拼（pīn）：豁出去，甘冒。', poem_appreciation = '这首词风格俊丽，是作者的得意之作。原题为“春词”。\n\n　　开头两句“小雨纤纤风细细，万家杨柳青烟里”，写暮春时节，好风吹，细雨润，满城杨柳，郁郁葱葱，万家屋舍，掩映杨柳的青烟绿雾之中。正是“绿暗红稀”，春天快要悄然归去了。次三句：“恋树湿花飞不起，愁无比，和春付与东流水”，借湿花恋树寄寓人的恋春之情。“恋树湿花飞不起”是个俊美的佳句。“湿花”应上“小雨”，启下“飞不起”。“恋”字用拟人法，赋落花以深情。花尚不忍辞树而留恋芳时，人的心情更可想而知了。春天将去的时候，落花有离树之愁，人也有惜春之愁，这“愁无比”三字，尽言二愁。如此深愁，既难排遣，故而词人将它连同春天一道付与了东流的逝水。\n\n　　“九十光阴能有几？金龟解尽留无计。”感叹春来春去，虽然是自然界的常态，然而美人有迟暮之思，志士有未遇之感，这九十日的春光，也极短暂，说去也就要去的，即使解尽金龟换酒相留，也是留她不住的。词句中的金龟指所佩的玩饰，唐代诗人贺知章，曾经解过金龟换酒以酬李白，成为往昔文坛上的佳话。作者借用这个典故，表明极意把酒留春。“寄语东城沽酒市。拚一醉，而今乐事他年泪。”虽然留她不住，也要借酒浇愁，拚上一醉，以换取暂时的欢乐。“寄语”一句，谓向酒肆索酒。结句“而今乐事他年泪”，一语两意，乐中兴感。\n\n　　这首词袭用传统作词法：上片写景，下片写情。结句“而今乐事他年泪”，一意化两，示遣愁不尽，无限感伤。作者亦自以“而今”句为得意之笔。', poem_tags = '宋词三百首,婉约,春天,抒情,感伤' WHERE poem_title = '渔家傲·小雨纤纤风细细' AND poem_author = '朱服';
UPDATE edu_poem SET poem_tags = '宋词三百首,宋词精选,写花,感叹,人生' WHERE poem_title = '燕山亭·北行见杏花' AND poem_author = '赵佶';
UPDATE edu_poem SET poem_translation = '小路边的红花日渐稀少，郊野却被萋萋芳草占遍，绿树成荫高楼台榭若隐若现。春风不懂得去管束杨花柳絮，让它们迷迷蒙蒙乱扑人面。\n翠绿的树叶里藏着黄莺，红色窗帘把燕子隔在外面，静静的炉香像游丝般袅袅升腾。醉酒后一场愁梦醒来时，夕阳正斜照着深深的庭院。', poem_notes = '踏莎（suō）行：词牌名，又名“喜朝天”“柳长春”“踏雪行”“平阳兴”“踏云行”“潇潇雨”等。双调小令，《张子野词》入“中吕宫”。五十八字，上下片各三仄韵。四言双起，例用对偶。\n红稀：花儿稀少、凋谢。意思是到了晚春时节。红：指花。\n高台：高高的楼台，这里指高楼。阴阴见：暗暗显露。阴阴：隐隐约约。\n不解：不懂得。\n蒙蒙：形容细雨。这里形容杨花飞散的样子。\n翠叶藏莺，珠帘隔燕：意谓莺燕都深藏不见。这里的莺燕暗喻“伊人”。\n游丝转：烟雾旋转上升，像游动的青丝一般。', poem_appreciation = '此词描绘暮春景色，上片写郊外景，下片写院内景，最后以“斜阳却照深深院”作结，流露出淡淡的哀愁。\n\n　　起首三句描绘一幅具有典型特征的芳郊春暮图：小路两旁，花儿已经稀疏，只间或看到星星点点的几瓣残红；放眼一望只见绿色已经漫山遍野；高台附近，树木繁茂成荫，一片幽深。“红稀”“绿遍”“树色阴阴”，标志着春天已经消逝，暮春气息很浓。三句所写虽系眼前静景，但“稀”“遍”“见”这几个词却显示了事物发展的进程和动态。从“小径”“芳郊”“高台”的顺序看，也有移步换形之感。“春风不解禁杨花，蒙蒙乱扑行人面。”所写的杨花扑面，也是暮春典型景色。但词人描绘这一景象时，却注入了自己的主观感情，写成春风不懂得约束杨花，以致让它漫天飞舞，乱扑行人之面。这一方面暗示已经无计留春，只好听任杨花飘舞送春归去；另一方面又突出了杨花的无拘无束和活跃的生命力。这里虽写暮春景色，却无衰颓情调，富有生趣。“蒙蒙”“乱扑”，极富动态感。“行人”二字，点醒以上所写，都是词人郊行所见。\n\n　　过片“翠叶藏莺，珠帘隔燕”两句，分写室外与室内，一承上，一启下，转接自然。上句说翠绿的树叶已经长得很茂密，藏得住黄莺的身影，与上片“树色阴阴”相应；下句说燕子为朱帘所隔，不得进入室内，引出下面对室内景象的描写。着“藏”“隔”二字，生动地写出了初夏嘉树繁阴之景与永昼闲静之状。\n\n　　“炉香静逐游丝转”写如此闲静的室内，香炉里的香烟，袅袅上升，和飘荡的游丝纠结、缭绕，逐渐融合一起，分不清孰为香烟，孰为游丝了。“逐”“转”二字，表面上是写动态，实际上却反托出整个室内的寂静。“逐”上着一“静”字，境界顿出。\n\n　　结拍“一场愁梦酒醒时，斜阳却照深深院。”跳开一笔，写到日暮酒醒梦觉之时，原来词人午间小饮，酒困入睡，等到一觉醒来，已是日暮时分，西斜的夕阳正照着这深深的朱门院落。这里点明“愁梦”，说明梦境与春愁有关。梦醒后斜阳仍照深院，遂生初夏日长难以消遣之意。贺铸《薄幸》词“人间昼永无聊赖。厌厌睡起，犹有花梢日在”，也正是此意。', poem_tags = '婉约,春天,写景,抒情,怅惘' WHERE poem_title = '踏莎行·小径红稀' AND poem_author = '晏殊';
UPDATE edu_poem SET poem_translation = '大丈夫何尝没有滔滔眼泪，只是不愿在离别时涕泗横流。\n面对离酒慷慨高歌挥舞长剑，耻如一般游子模样满脸离愁。\n一旦被蝮蛇螫伤手腕之后，当断手臂就断壮士决不踌躇。\n既然决心闯荡天下建功立业，离别家常便饭何须叹息怨尤。', poem_notes = '杖剑：同“仗剑”，持剑。尊：酒器。\n游子颜：游子往往因去国怀乡而心情欠佳，面带愁容。\n蝮蛇：一种奇毒的蛇。螫（shì）：毒虫刺人。\n解腕：斩断手腕。\n志：立志，志向。', poem_tags = '离别,写人,议论' WHERE poem_title = '别离' AND poem_author = '陆龟蒙';
UPDATE edu_poem SET poem_translation = '织着凤尾纹的绫罗，薄薄重重；\n碧纹的圆顶罗帐，我深夜赶缝。\n那回邂逅，来不及用团扇掩盖；\n可你驱车隆隆而过，无语相通。\n曾因寂寥不眠，想到更残烛尽；\n却无你的消息，等到石榴花红。\n也许你在垂杨岸，栓系斑骓马；\n怎能等到，送去会你的西南风。\n\n注解\n凤尾香罗：凤纹罗；罗：绫的一种。\n顶：指帐顶。\n扇裁：指以团扇掩面。', poem_appreciation = '李商隐的七律无题，艺术上最成熟，最能代表其无题诗的独特艺术风貌。这首七律无题，内容是抒写青年女子爱情失意的幽怨，相思无望的苦闷，又采取女主人公深夜追思往事的方式，因此，女主人公的心理独白就构成了诗的主体。她的身世遭遇和爱情生活中某些具体情事就是通过追思回忆或隐或显地表现出来的。\n\n　　起联写女主人公深夜缝制罗帐。凤尾香罗，是一种织有凤纹的薄罗；碧文圆顶，指有青碧花纹的圆顶罗帐。李商隐写诗特别讲求暗示，即使是律诗的起联，也往往不愿意写得过于明显直遂，留下一些内容让读者去玩索体味。像这一联，就只写主人公在深夜做什么，而不点破这件事意味着什么，甚至连主人公的性别与身份都不作明确交代。通过“凤尾香罗”、“碧文圆顶”的字面和“夜深缝”的行动，可以推知主人公大概是一位幽居独处的闺中女子。罗帐，在古代诗歌中常常被用作男女好合的象征。在寂寥的长夜中默默地缝制罗帐的女主人公，大概正沉浸在对往事的追忆和对会合的深情期待中吧。\n\n　　接下来是女主人公的一段回忆，内容是她和意中人一次偶然的相遇──“扇裁月魄羞难掩，车走雷声语未通。”对方驱车匆匆走过，自己因为羞涩，用团扇遮面，虽相见而未及通一语。从上下文描写的情况看，这次相遇不象是初次邂逅，而是“断无消息”之前的最后一次照面。否则，不可能有深夜缝制罗帐，期待会合的举动。正因为是最后一次未通言语的相遇，在长期得不到对方音讯的今天回忆往事，就越发感到失去那次机缘的可惜，而那次相遇的情景也就越加清晰而深刻地留在记忆中。所以这一联不只是描绘了女主人公爱情生活中一个难忘的片断，而且曲折地表达了她在追思往事时那种惋惜、怅惘而又深情地加以回味的复杂心理。起联与颔联之间，在情节上有很大的跳跃，最后一次照面之前的许多情事（比如她和对方如何结识、相爱等）统统省略了。\n\n　　颈联写别后的相思寂寥。和上联通过一个富于戏剧性的片断表现瞬间的情绪不同，这一联却是通过情景交融的艺术手法概括地抒写一个较长时期中的生活和感情，具有更浓郁的抒情气氛和象征暗示色彩。两句是说，自从那次匆匆相遇之后，对方便绝无音讯。已经有多少次独自伴着逐渐黯淡下去的残灯度过寂寥的不眠之夜，眼下又是石榴花红的季节了。“蜡炬成灰泪始干”，“一寸相思一寸灰”，那黯淡的残灯，不只是渲染了长夜寂寥的气氛，而且它本身就仿佛是女主人公相思无望情绪的外化与象征。石榴花红的季节，春天已经消逝了。在寂寞的期待中，石榴花红给她带来的也许是流光易逝、青春虚度的怅惘与伤感吧。“金烬暗”、“石榴红”，仿佛是不经意地点染景物，却寓含了丰富的感情内涵。把象征暗示的表现手法运用得这样自然精妙，不露痕迹，这确实是艺术上炉火纯青境界的标志。\n\n　　末联仍旧到深情的期待上来。“斑骓”句暗用乐府《神弦歌·明下童曲》“陆郎乘斑骓……望门不欲归”句意，大概是暗示她日久思念的意中人其实和她相隔并不遥远，也许此刻正系马垂杨岸边呢，只是咫尺天涯，无缘会合罢了。末句化用曹植《七哀》“愿为西南风，长逝入君怀”诗意，希望能有一阵好风，将自己吹送到对方身边。李商隐的优秀的爱情诗，多数是写相思的痛苦与会合的难期的，但即使是无望的爱情，也总是贯串着一种执着不移的追求，一种“春蚕到死丝方尽，蜡炬成灰泪始干”式的真挚而深厚的感情。希望在寂寞中燃烧，读者在这首诗中所感受到的也正是这样一种感情。这是他的优秀爱情诗和那些缺乏深挚感情的艳体诗之间的一个重要区别，也是这些诗尽管在不同程度上带有时代、阶级的烙印，却至今仍然能打动人们的一个重要原因。', poem_tags = '唐诗三百首,思念' WHERE poem_title = '无题·凤尾香罗薄几重' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '韵译\n住在旅馆中并无好的旅伴；忧郁的心情恰似凝固一般。\n对着寒灯回忆起故乡往事；就象失群的孤雁警醒愁眠。\n家乡太远归梦到破晓未成；家书寄到旅馆已时隔一年。\n我真羡慕门外沧江的烟月；渔人船只就系在自家门前。\n\n直译\n旅馆里没有知心朋友，我独自静静地沉思凝神。\n对着寒灯回忆往事，孤雁的叫声，惊醒了凄寂梦魂。\n乡关道路迢远，梦魂拂晓时才得归去，家人的书信要等来年方能寄到此地。\n沧江上月色含烟，风光是多么美好，钓鱼船就系在我家门前。', poem_notes = '良伴：好朋友。\n凝情：凝神沉思。悄然：忧伤的样子。这里是忧郁的意思。\n寒灯：昏冷的灯火。这里指倚在寒灯下面。思旧事：思念往事。\n断雁：失群之雁，这里指失群孤雁的鸣叫声。警：惊醒。\n远梦归：意谓做梦做到侵晓时，才是归家之梦，家远梦亦远，恨梦归之时也甚短暂，与下句家书隔年方到，恨时间之久，相对而更增烦愁。侵晓：破晓。沧江：泛指江，一作“湘江”。\n好烟月：指隔年初春的美好风景。\n门：门前。', poem_appreciation = '这是羁旅怀乡之作。离家久远，目睹旅馆门外的渔船即加以艳羡。幽恨乡愁、委实凄绝。颈联“远梦归侵晓，家书到隔年”意思曲折多层，实乃千锤百炼的警句。\n\n　　首联起，直接破题，点明情境，羁旅思乡之情如怒涛排壑，劈空而来。可以想见，离家久远，独在异乡，没有知音，家书也要隔年才到，此时孤客对寒灯，浓厚深沉的思乡之情油然而生，必会陷入深深的忧郁之中。“凝情自悄然”是此时此地此情此景中抒情主人公神情态度的最好写照：静对寒灯，专注幽独，黯然伤神，将诗人的思念之情写到极致。\n\n　　颔联承，是首联“凝情自悄然”的具体化，诗人融情于景，寒夜孤灯陪伴孤客，思念故乡旧年往事，失群孤雁声声鸣叫，羁旅之人深愁难眠，细致地描绘出了一幅寒夜孤客思乡图景。“思”字和“警”字极富炼字功夫。灯不能思，却要寒夜愁思陈年旧事，物尤如此，人何以堪。由灯及人，显然用意在人不在物。“警”字也极富情味。旅人孤灯，长夜难眠，一声雁叫，引孤客嫠妇愁思惊梦，归思难收。\n\n　　首联与颔联极言乡关遥远，幽愁满怀。梦见自己回到家中，因路途遥远，梦醒时分天已大明，家书须隔年才能寄到旅馆，可见离家之远，表达出对家乡深沉的思念。\n\n　　颈联转，用设想之词，虚实结合，想象奇特，表现出此时此地此情此景中诗人因愁思难耐、归家无望而生出的怨恨。故乡远在千里，只能梦中相见，也许是短梦，也许是长梦，但梦中醒来却已到天明。字里行间，流露出梦短情长的幽怨。而这一切又都由于“家书到隔年”的实际情况。作为诗歌由写景向抒情的过渡，转句用梦境写旅宿思愁哀怨，亦虚亦实，虚中写实，以实衬虚的特点读来回肠荡气。\n\n　　尾联合，收拢有力，却并非直抒胸意，而是以设想之词，勾勒家乡美丽的生活图景，融情于景，借景抒情，把浓烈的归思之情融入家乡优美的风景之中。沧江烟霭，云霞明灭，月色溶溶，家门外系着钓鱼船，一幅优美宁静祥和的家乡风光图景。画面中虽然没有写人物，但一条静静地系于家门外的钓鱼船却让人产生丰富的联想。面对这样一幅家乡优美的画面，谁人不梦绕魂牵，更何况旅宿在外的诗人呢！家乡远隔千里，旅人归思难收，如此优美的家乡风光图景非但没有给诗人以慰藉，反而加深了诗人的思乡愁苦。这是用乐景反衬哀情的典型。美景幽思、怨恨乡愁、委实凄绝。除却个中人，任何人也难以深味个中情。不过，“烟月”在此实际上是借代，并非一定就是“烟”，就是“月”。正所谓，文学作品的形象大于思维，此处一个“烟月”可以触发不同的旅人思妇产生不同的意象联想，从而产生强大的艺术感染力。\n\n　　颈联与尾联看似跳出了乡愁，艳羡门外沧江鱼船的清闲自在，其实是借他乡之物，更曲折地表达出诗人思乡之情。全诗层层推进，写景抒情都有独到之处。', poem_tags = '唐诗三百首,羁旅,思乡' WHERE poem_title = '旅宿' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '大地一片雪白，风色寒厉，纷纷的雪花片片如大手。\n笑死了陶渊明，就因为你不饮杯中酒。\n你真是浪抚了一张素琴，虚栽了五株翠柳。\n辜负了戴的头巾，我对你来说意味着什么？', poem_notes = '王历阳：指历阳姓王的县丞。历阳县，秦置。隋唐时，为历阳郡治。\n五株柳：陶渊明畜素琴一张，宅边有五柳树。\n空负头上巾：语出陶渊明诗“若复不快饮，空负头上巾”。', poem_tags = '冬天,写雪,饮酒,抒情' WHERE poem_title = '嘲王历阳不肯饮酒' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '译文 淮河两岸舟船背驰、波痕接触也难以做到。 只能看到鸥鹭无拘无束无人管束，自在的在南北之间飞翔。', poem_tags = '古诗三百首,写水,写鸟,抒情,爱国' WHERE poem_title = '初入淮河四绝句·其三' AND poem_author = '杨万里';
UPDATE edu_poem SET poem_translation = '南京城上西楼，倚楼观看清秋时节的景色。万里的长江在夕阳下流去。公元1127年（宋钦宗靖康二年）金人侵占中原，官僚们散了，什么时候收复国土？试请悲风吹泪过扬州。', poem_notes = '金陵：南京。城上西楼：西门上的城楼。\n倚清秋：倚楼观看清秋时节的景色。\n中原乱：指公元1127年（宋钦宗靖康二年）金人侵占中原的大乱。\n簪缨：当时官僚贵族的冠饰，这里代指他们本人。\n收：收复国土。\n倩：请。\n扬州：地名，今属江苏，是当时南宋的前方，屡遭金兵破坏。', poem_appreciation = '古人登楼、登高，每多感慨。王粲登楼，怀念故土。杜甫登楼，感慨“万方多难”。许浑登咸阳城西楼有“一上高城万里愁”之叹。李商隐登安定城楼，有“欲回天地入扁舟”之感。尽管各个时代的诗人遭际不同，所感各异，然而登楼抒感则是一致的。\n\n　　这首词一开始即写登楼所见。在词人眼前展开的是无边秋色，万里夕阳。秋天是冷落萧条的季节。宋玉在《九辩》中写道：“悲哉，秋之为气也，萧瑟兮，草木摇落而变衰。”杜甫在《登高》中也说：“万里悲秋常作客。”所以古人说“秋士多悲”。当离乡背井，作客金陵的朱敦儒独自一人登上金陵城楼，纵目远眺，看到这一片萧条零落的秋景，悲秋之感自不免油然而生。又值黄昏日暮之时，万里大地都笼罩在恹恹的夕阳中。“垂地”，说明正值日薄西山，余晖黯淡，大地很快就要被淹没在苍茫的暮色中了。这种景物描写带有很浓厚的主观色彩。王国维说：“以我观物，故物皆着我之色彩。”朱敦儒就是带着浓厚的国亡家破的伤感情绪来看眼前景色的。他用象征手法使人很自然地联想到南宋的国事亦如词人眼前的暮景，也将无可挽回地走向没落、衰亡。作者的心情是沉重的。\n\n　　下片忽由写景转到直言国事，似太突然。其实不然。上片既已用象征手法暗喻国事，则上下两片暗线关连，意脉不露，不是突然转折，而是自然衔接。“簪缨”，是指贵族官僚们的帽饰。簪用来连结头发和帽子；缨是帽带。此处代指贵族和士大夫。中原沦陷，北宋的世家贵族纷纷逃散。这是又一次的“衣冠南渡”。“几时收？”这是作者提出的一个无法回答的问题。这种“中原乱，簪缨散”的局面何时才能结束呢？表现了作者渴望早日恢复中原，还于旧都的强烈愿望，同时也是对朝廷苟安旦夕，不图恢复的愤慨和抗议。\n\n　　结句“试倩悲风吹泪过扬州”。悲风，当然也是作者的主观感受。风，本身无所谓悲，而是词人主观心情上悲，感到风也是悲的了。风悲、景悲、人悲，不禁潸然泪下。这不只是悲秋之泪，更重要的是忧国之泪。作者要倩悲风吹泪到扬州去，扬州是抗金的前线重镇，国防要地，这表现了词人对前线战事的关切。\n\n　　全词由登楼入题，从写景到抒情，表现了词人强烈的亡国之痛和深厚的爱国精神，感人至深。', poem_tags = '宋词三百首,豪放,爱国,怀念' WHERE poem_title = '相见欢·金陵城上西楼' AND poem_author = '朱敦儒';
UPDATE edu_poem SET poem_translation = '柳丝柔长春雨霏霏，花丛外漏声不断传向远方。塞雁向南归去令人惊心，杂乱的城鸟寻觅着栖巢，望着画屏上对对金鹧鸪令人格外伤感。\n薄薄的香雾透入帘幕之中，美丽的楼阁池榭啊再无人一起观赏。绣帘低垂独自背着垂泪的红色蜡烛，长梦不断远方亲人啊可知道我的衷肠？', poem_notes = '1、更漏：古人用铜壶滴漏来计时，将一夜分为五更。\n2、子：曲子的简称。\n3、漏声：指报更报点之声。\n4、迢递（tiáo dì）：遥远。\n5、塞雁：北雁，春来北飞。\n6、城乌：城头上的乌鸦。\n7、画屏：有图饰品的屏风，为女主人公居室中的摆设。\n8、金鹧鸪（zhè gū）：金线绣成的鹧鸪，可能绣在屏风上，也可能是绣在衣服上的。\n9、薄：通“迫”，逼来。\n10、惆怅（chóu chàng）：失意、烦恼。\n11、谢家池阁：豪华的宅院，这星即指女主人公的住处。谢氏为南朝望族，居处多有池阁之胜。后来便成为一共名。韦庄归国遥词中有“日落谢家池阁”句。\n12、红烛背：背向红烛；一说以物遮住红烛，使其光线不向人直射。', poem_tags = '宋词三百首,春天,写景,女子,闺思' WHERE poem_title = '更漏子·柳丝长' AND poem_author = '晏几道';
UPDATE edu_poem SET poem_translation = '黄初四年五月，白马王彪、任城王彰与我一起前往京城朝拜，迎奉节气。到达洛阳后，任城王不幸身死；到了七月，我与白马王返回封国。后来有司以二王返回封地之故，使我二人在归途上的住宿起居相分隔，令我心中时常忧愤！因为诀别只在数日之间，我便用诗文自剖心事，与白马王离别于此，悲愤之下，作成此篇。\n\n　　在承明庐谒见我的皇兄，去时返回那旧日封国的疆土。清晨从帝都扬鞭启程，黄昏经过首阳山的日暮。伊水和洛水，多么广阔而幽深；想要渡过川流，却为没有桥梁所苦。乘舟越过翻涌的波涛，哀怨于东方漫长的旅途；回首瞻望洛阳的城楼，转头难禁我哀伤反复。\n\n　　浩荡的空谷何等寥廓，山间的古木郁郁苍苍。暴雨让路途充满泥泞，污浊的石浆纵横流淌。中间的路途已绝不能再前进，改道而行，登临高峻的山冈。可是长长的斜坡直入云天，我的座马又身染玄黄之疾。\n\n　　马染玄黄，可是仍能奋蹄；我怀哀思，却曲折而忧郁。忧郁而曲折的心志啊，究竟何所牵念？只为我挚爱的王孙即将分离。原本试图一同踏上归路，中途却变更而无法相聚。可恨鸱枭鸣叫着阻扰着车马；豺狼阻绝了当途的要津；苍蝇之流让黑白混淆；机巧的谗言，疏远了血肉之亲。想要归去却无路能行，手握缰绳，不由得踟蹰难进！\n\n　　踟蹰之间，此地又有什么留恋？我对王孙的思念永远没有终极！秋风激发微薄的凉意，寒蝉在我的身侧哀鸣。广袤的原野啊，多么萧条；白色的日影倏忽间向西藏匿。归鸟飞入高大的林木，翩翩然地扇动着羽翼。孤单的野兽奔走着寻觅兽群，口衔着蒿草也无暇独食而尽。感于物象触伤了我的胸怀，以手抚心发出悠长的叹息。\n\n　　长叹又能有什么用处？天命已与我的意志相违！何能想到，我那同胞的兄长，此番一去，形体竟永不返归！孤独的魂魄飞翔在昔日的故土，灵柩却寄存在帝都之内。尚存之人，须臾间也将过世而去，亡者已没，我的身体已自行衰微。短暂的一生居住在这世间，忽然好比清晨蒸干的露水。岁月抵达桑榆之年的迟暮，光影和声响都已无法追回。自我审思并非金石之体，顿挫嗟叹间令我满心忧悲。\n\n　　心境的悲伤触动了我的形神，望弃置下忧愁不再复述哀情。大丈夫理应志在四海，纵使相隔万里也犹如比邻。假若兄弟的眷爱并无削减，分离远方，反会加深你我的情谊，又何必一定要同榻共眠，来传达你我的殷勤？过度的忧思会导致疾病，切莫沉溺在儿女之情的缧绁；只是仓卒间割舍的骨肉之情，怎能不让人心怀愁苦和酸辛！\n\n　　愁苦与酸辛引起了怎样的思虑？如今我笃信了天命的可疑！向众仙寄托祈求终究虚妄，让神人赤松子久久地把我诓欺。人生的变故发生在短暂的须臾，有谁能持有百年的长寿；一旦离别永无相会之日，再执王孙的手，将要等到何期？但愿白马王啊，珍爱您尊贵的躯体，与我一同安度寿者的黄发之年；饮泪踏上漫漫的长路，从此收笔永诀，与君分离。', poem_notes = '[1]白马王彪：三国魏白马王曹彪。据《三国志·魏志·陈思王传》：“（黄初）四年，（植）徙封雍丘王，其年，朝京师。”裴松之注引《魏氏春秋》：“是时待遇诸国法峻。任城王暴薨，诸王既怀友于之痛，植及白马王彪还国，欲同路东归，以叙隔阔之思，而监国使者不听。植发愤告离而作诗。”\n[2]黄初：魏文帝（曹丕）的年号。黄初四年是公元223年。\n[3]白马王：曹彪，曹植的异母弟。任城王：曹彰，曹植的同母兄。朝京师：到京师参加朝会。会节气：魏有诸侯藩王朝节的制度，每年立春、立夏、立秋、立冬四个节气之前，各藩王都会聚京师参加迎气之礼，并举行朝会。\n[4]薨（hōng）：古代诸侯王死称为薨。据《世说新语·尤悔》记载，任城王是被曹丕毒死的。\n[5]还国：返回封地。\n[6]有司：官吏，指监国使者灌均。监国使者是曹丕设以监察诸王、传达诏令的官吏。毒恨：痛恨。\n[7]大别：永别。自剖：表明自己的心迹。\n[8]谒帝：朝见皇帝。承明庐：汉长安宫殿名，此泛指曹魏的宫殿。逝：语词，无义。旧疆：指鄄（juàn）城（山东省荷泽市），时曹植为鄄城王。\n[9]皇邑：皇都，指洛阳。日夕：天晚的时候。首阳：山名，洛阳东北。\n[10]伊洛：二水名。伊，指伊水，发源于河南栾川县，到偃师县入洛水；洛，洛水，源出陕西冢岭山，至河南巩县入黄河。济：渡。川：河。梁：桥。\n[11]东路：东归鄄城的路。\n[12]顾瞻：回首眺望。城阙：指京城洛阳。引领：伸长脖子。\n[13]太谷：谷名，一说是关名，在洛阳城东南五十里。\n[14]霖雨：连续几日的大雨。泥：作动词，使道路泥泞。流潦（lǎo）：积水。\n[15]中逵：通衢大路。逵，四通八达的大道。轨：车道。改辙：改道。\n[16]修坂：高高的山坡。修，长。坂，斜坡。造：到、往。玄以黄：指马病。《诗经·周南·卷耳》：“我马玄黄。”\n[17]郁以纡（yū）：愁思郁结。郁，愁。纡，萦绕。\n[18]不克俱：不能在一起。克，能。\n[19]鸱枭（chīxiāo）：猫头鹰，古人认为这是不祥之鸟。衡轭（è）：车辕前的横木和扼马颈的曲木，代指车。衢：四通八达的道路。\n[20]间：离间。谗巧：谗言巧语。\n[21]蹊：路。揽辔：拉住马缰。踟蹰：徘徊不前。\n[22]西匿：夕阳西下。\n[23]乔林：乔木林。乔，高大的树木。翩翩：飞动貌。厉：振动。\n[24]走索群：奔跑着寻找同伴。不遑：不暇，不空。\n[25]太息：叹息。\n[26]往：指死亡。\n[27]故域：指曹彰的封地任城。灵柩：放有尸首的棺木。\n[28]存者：指自己与曹彪。黄节说：“‘存者’，谓己与白马也。‘忽复过’，谓须臾亦与任城同一往耳。”又说：“‘亡殁身自衰’句，倒文，谓身由衰而殁耳。指存者也。”二句说自己和白马王曹彪目前虽还活着，但很快也会死去的。刘履认为存者和亡殁应互换，意思是死者已成过去，存者身体渐衰，也难久长。\n[29]晞（xī）：干。汉乐府《薤露歌》：“薤上露，何易晞。”说人生短暂。\n[30]桑榆：二星名，都在西方。《文选》李善注说：“日在桑榆，以喻人之将老。”影响：影子和声音。\n[31]顾：念。非金石：《古诗十九首》回车驾言迈：“人生非金石，岂能长寿考。”咄唶（duōjiè）：惊叹声。\n[32]陈：说、提起。\n[33]比邻：近邻。\n[34]亏：欠缺。分：情分。日亲：一天比一天亲密。\n[35]衾帱（qīnchóu）：被子和帐子。后汉姜肱与弟仲海、季江相友爱，常同被而眠，见《后汉书·姜肱传》。慇懃：同殷勤，情意恳切。\n[36]疾疢（chèn）：疾病。无乃：岂不是。儿女仁：指小儿女的脆弱感情。\n[37]仓卒：匆忙之间。\n[38]虑思：思虑，考虑。信：确实。\n[39]虚无：指求仙事不可靠。松子：赤松子，传说中的仙人。吾欺：欺吾，骗我。\n[40]变故：灾祸。斯须：须臾之间。百年：指长寿，古诗：“生年不满百。”持：获得。\n[41]黄发期：指高寿。黄发，人老发黄，故以指老人。\n[42]收泪：停止哭泣。即长路：踏上漫长的归途。援笔：提笔，指写诗赠别。', poem_appreciation = '《赠白马王彪》一诗共分七章，表现了曹植恐怖、悲伤、痛恨和愤怒相互交织的复杂感情，深刻地揭发了统治阶级内部的尖锐矛盾。\n\n　　第一章共十句，写这次“会节气”结束之后启程返回封地的经过和心情。诗人在“承明庐”朝见了魏文帝曹丕之后，将要返回自己的封地鄄城。按曹植于黄初二年（221年）改封鄄城侯，次年立为鄄城王。清晨从京都洛阳出发，傍晚经过了首阳山。这前四句都是过程的介绍。接着“伊洛广且深，欲济川无梁”则寓有深意。说伊水、洛水既宽广又幽深，已经感到路途艰难。“欲济川无梁”竟然说过河无桥，更表明是难以克服的因难。作者瞻望前途，寸步难行。只好从水路“泛舟”，却又遇见“洪涛”，因而“怨彼东路长”：东归鄄城还有好长一段路呢！这个“怨”字，不止怨路，实际还包括怨人，怨曹丕和他的爪牙。“顾瞻恋城阙，引领情内伤”是在旅途的困苦之中回头再朝京城看了一眼，内心不是怀念曹丕，更不是留恋“会节气”的活动，而是想到了曹彰在洛阳暴死得不明不白，引起作者的极大悲愤，甚至恐怖，所以在伸着脖子遥望城阙时心情也是悲伤的。\n\n　　第二章共八句，写归途中的困苦。诗人经过寥廓的太谷关，山上的树木郁郁苍苍。接上章可知诗人弃舟登岸，走入山谷。不巧“霖雨泥我途，流潦浩纵横”，连降大雨，道路泥泞不堪，积水纵横流淌，行路和“泛舟”同样困难。这里路途难行，也隐喻处境危险。下文“中途绝无轨”和上文“欲济川无梁”一样，还是无路可走，这里可以体会出曹植身受的痛苦和威胁多么深重。水上有洪涛，山谷遇大雨，只好改道登上山坡，然而长长的斜坡直入云天，前面的路程辽远而又高峻。恰在此时马又得了玄黄的病。困难加剧，矛盾激化，东行归藩的路途竟然如此充满险阻，有如唐诗人李白《行路难三首》说的那样：“欲渡黄河冰塞川，将登太行雪满山”，隐约说明了曹植人生的道路多么坎坷不平。\n\n　　第三章共十二句，开始直接抒发内心的悲愤，进入诗的核心部分。在这进退两难之际，作者还得骑着病马前进，说明当时诗人已失去自由，只能返回封地，没有其他选择。因此“我思郁以纡”，心中愁闷郁结。接着提出自己和亲密的弟弟曹彪不得团聚的问题：“亲爱在离居。”这点明了写这首诗的直接原因。途中派有监国使者灌均，灌均使他们弟兄“离居”。灌均其人，过去就曾经“奏植酒醉悖慢，劫胁使者”（《三国志》曹植本传）。如今曹植想在途中同曹彪互叙兄弟情谊，灌均竟然不准，因此曹植对他恨之人骨。把他比做鸱枭、豺狼、苍蝇。他们窃据要津，混淆黑白，搬弄是非，挑拨离间，进谗言，说坏话，使得亲人之间都疏远了。这里当然有难言之隐和违心之论。由于当时的恶劣的政治环境和君臣名份的限制，诗人不能也不敢明目张胆地表露对曹丕的不满，而只能把满腔怒火烧向使他们“亲爱在离居”的监国使者灌均之流。诗人表面还要回护一下曹丕，好像曹丕对他们本来很好，是“谗巧令亲疏”的。“中更不克俱”是说中途才改变主意不让他们弟兄同行的，似乎说曹丕本来是没有明确让他们分路而行的。曹植的这种用心是清清楚楚的，也是可以理解的。诗人受到这帮势利小人的胁迫，心情沮丧愤慨，一时想要重回京城，但“欲还绝无蹊”，没有退路，只能拉起绳在那里徘徊犹豫。\n\n　　第四章十二句，诗人于路上触景生情，感物伤怀。曹植在路上徘徊，前途茫茫，自己不禁发问：但在这里又有什么可以留恋的呢？原来相思之情是无穷无尽的。“相思”指弟兄之间的关怀，也就是指他对曹彰的悼念和对曹彪的思念。在陷入相思的苦痛之中，又面对着秋风、寒蝉、萧条的原野和西匿的白日。秋风没有温暖，寒蝉发出哀鸣，一派肃杀凄清景色。此外“归鸟赴乔林，翩翩厉羽翼；孤兽走索群，衔草不遑食”，更引起诗人的无限伤感。归鸟有林可赴，孤兽有群可归，鸟兽尚且各自寻求归宿，然而曹植本人却无路可走，无家可归，从而产生人不如物的感触，这就是“感物伤我怀”。最后只能“抚心长太息”，拍着胸脯长叹罢了，现实生活，没有前途和希望。\n\n　　第五章共十四句，表现了曹植对曹彰暴死的哀悼和对人生的感慨。这章接触到写这首诗的根本原因。作者深知，叹息没有什么用。好像上天安排的命运故意和他作对。这种念头是由曹彰暴死引起的。根本不会料想到一母所生的兄弟，一道来到洛阳就突然死去了，落得“孤魂翔故域，灵柩寄京师”，曹彰如果死而有知，也会感到孤独寂寞的。其实这是作者当时的心境。曹彰之死，使曹植感到前途未卜，命运难料，不免产生兔死狐悲的颓丧情绪。曹彰突然间就死去，活着的人身体也渐渐衰弱下来。人生一世，只不过像早晨的露水那样，太阳出来一照就干了。而且进入晚年，时光流逝更快得惊人。诗人又自知不如金石长寿，只能叹息悲伤。曹植写作此诗时年龄不过32岁，正在有为的壮年，然而居然认为“年在桑榆间”，到了人生的暮年，这种反常的心理，是他对个人命运难以把握的反映。“人生如朝露”或“人命若朝霜”（曹植《送应氏二首》），为汉代末年士大夫中较为流行的思想。《古诗十九首·驱车上东门》就有“浩浩阴阳移，年命如朝露。人生忽如寄，寿无金石固”的诗句，但较之曹植的忧愤深广就显得肤浅得多了。\n\n　　第六章共十二句，诗人以豪言壮语和曹彪互相慰勉。上一章诗表现的是由曹彰之死引起的悲愤，感人肺腑，催人落泪。然而一味沉湎于忧伤之中，于身无益，于事无补。曹植清醒地知道“心悲动我神”，因而毅然“弃置莫复陈”，不能陷入忧伤的深渊而不能自拔。诗人抖擞精神振作起来，用“丈夫志四海，万里犹比邻”的豪言壮语和曹彪共勉。唐代诗人王勃的“海内存知己，天涯若比邻”的名句（《送杜少府之任蜀川》）是受了曹植的启发。情绪的由低沉而变得昂扬，使诗的情调也变得开朗豪迈了。下面“恩爱苟不亏，在远分日亲。何必同衾帱，然后展殷勤。忧思成疾疢，无乃儿女仁”是对曹彪的开导。告诉他：弟兄之间的情谊如果没有减弱，离得远了情份反倒会日益亲密。不一定要像后汉姜肱那样，和弟弟常常共被而眠才算表示深情。言外之意是说对这次途中没得同行不要介意。如果因此而得病，那就是失掉了大丈夫的气概而沉溺于儿女之情了。和上文所引的王勃诗中的“无为在歧路，儿女共沾巾”是一个意思。话是这样说，但诗人还是不能从沉重的忧愤之中完全解脱出来，因此末二句“仓卒骨肉情，能不怀苦辛？”情绪又急转直下，曹彰的暴死以及由此产生的兄弟残杀的恐怖阴影是永远不能忘怀和消除的。\n\n　　最后的第七章共十二句，在赠诗惜别的情意之中，表示了诗人对天命的怀疑和对神仙的否定。作者后半生形同囚禁，动辄得咎，生活没有乐趣，前途没有希望。经过这次“会节气”和归国途中受到的刁难，使他对统治阶级内部的矛盾和弟兄骨肉之间的权力之争的残酷性，有了深刻的认识。以前还认为命运不好，“天命与我违”；如今知道“天命信可疑”了。似乎意识到，他的遭遇，不是上天意志的安排，而是人世斗争的产物。至于神仙，更是骗人已久了。汉末建安时期，求仙之风很盛行，曹操的诗有一半是描写神仙世界的。曹植也有不少游仙题材的诗。略早于建安产生的《古诗十九首·驱车上东门》里也有“服食求神仙，多为药所误”的抒写。曹植对神仙的虚无有所认识，不能不说是一种觉悟。曹植感到“变故在斯须”，顷刻之间就会发生曹彰暴死的惨剧。那么，人生百年，谁能把握不了，曹丕随时都可能加害于他，所以他说“离别永无会，执手将何时”，不然，和年青的兄弟分手是不会有诀别之感的。在这作者看来是生离死别的时刻，只能祝愿对方保重身体，并且互相祝福而已。诗人与白马王曹彪最后洒泪而别。\n\n　　《赠白马王彪》一诗，直接反映的是曹植对曹丕手下的鹰犬爪牙的仇恨和愤慨，实际是对其兄曹丕对他们弟兄残酷迫害的抗议。\n\n　　这首诗是继屈原《离骚》之后，中国文学史上又一首长篇抒情诗。诗的正文共80句，400字，篇幅之长，结构之巧，感情之深都是在古典文学作品中罕见的。全诗气魄宏伟，结构严谨。曹彰之死有如一个阴影笼罩全篇，由此构成的悲剧气氛，在序文和一、五、六、七各章里都反覆渲染，突出了这一事件的严重后果。中间“欲济川无梁”，“中途绝无轨”，“欲还绝无蹊”的“三无”，把作者走投无路，进退失据，悲愤交加的境遇和心情联结起来，并使文气贯通，前后勾连，全诗是一个有机的整体。\n\n　　全诗结构的浑然一体，和各章之间运用辘轳体有密切的关系。辘轳体即修辞学里的“顶真格”，它要求行文在段与段或句与句之间用相同的字句相互衔接。古代《诗经》中的《大雅·文王》和《大雅·既醉》两篇；乐府诗《平陵东》、《西洲曲》都运用了这种形式。《赠白马王彪》除第一章和第二章没有使用辘轳体（《古诗源》把第一章和第二章视为一章）之外，其余各章都用了。如第二章的末句是“我马玄以黄”，第三章的首句就是“玄黄犹能进”；第三章的末句是“揽辔止踟蹰”，第四章的首句就是“踟蹰亦何留”，下皆仿此。这种手法能够使结构紧凑、段落分明而又便于人们记忆和传诵。\n\n　　此诗抒情的方式也时有变化，有时直抒胸臆，有时却把抒情和叙事、写景结合起来。“伊洛广且深，欲济川无梁”，“霖雨泥我途，流潦浩纵横”，看起来是叙事，实际是抒情。第四章借景抒情，情景相生，发人深思，耐人寻味。诗中的寒蝉、归鸟、孤兽都是诗人自身的写照。冷落空旷的秋季原野，也是当时诗人所处的政治环境的形象再现。\n\n　　另外，恰当的比喻也是此诗的特色之一。作者把监国使者比之为“鸱枭”、“豺狼”和“苍蝇”，惟妙惟肖，入木三分。这些比喻不仅可以收到强烈的艺术效果，而且免于授人以柄。', poem_tags = '抒情,长诗,离别,亲情,悼念' WHERE poem_title = '赠白马王彪·并序' AND poem_author = '曹植';
UPDATE edu_poem SET poem_translation = '登上这座楼来眺望四周，暂且在闲暇的时光消解忧愁。（我）看这座楼宇所处的地方，实在是明亮宽敞少有匹敌。携带着清澈的漳水的浦口，倚临着弯曲的沮水的长长的水中陆地。背靠着高而平的广大的陆地，俯临水边高高低低的地面上可以灌溉的河流，北边的重点是陶朱公放牧的原野，西边连接着楚昭王的陵墓。花果遮蔽原野，谷物布满田地。但即使（这里）的确很美却不是我的乡土，又怎么能够值得我在此逗留？\n　　（我因为）逢上纷乱混浊的乱世而迁移流亡（到这里），到现在已经超过漫长的十二年。心中思念故乡希望归去，谁能忍受这种（思乡的）忧思啊！凭靠着楼上的栏杆来（向远方）遥望，面对着北风（我）敞开衣襟。（北方的）平原（是那么）遥远，（我）纵目远望，（视线）被荆山的高峰所遮蔽。道路弯弯曲曲又长又远，河水浩大无边深不可测。悲叹故乡被阻隔，眼泪横流情不能禁。昔日孔子在陈国的时候，发出过“归欤”的叹息。钟仪被囚禁（在晋国）而演奏楚国的地方乐曲，庄舄（在楚国）做了大官但仍说家乡越国的方言。人思念故乡的感情是相同的，岂会因为穷困还是显达而表现不同？\n　　念及时光的流逝，等待天下太平要到什么时候啊！（我）期望王道平易，在太平盛世施展自己的才能。担心像葫芦瓢一样徒然挂在那里（不被任用），害怕清澈的井水无人饮用。漫步游息徘徊，太阳很快就下山了。（接着）刮起了萧瑟的寒风，天色也阴沉沉地暗了下来。野兽慌忙地左顾右盼寻找兽群，鸟雀也纷纷鸣叫着展翅高飞。原野一片寂静没有游人，（只有）征夫在行走不停。（我的）心情凄凉悲怆而且感伤，心中也充满了忧伤和悲痛。（于是）沿着台阶走下楼来，心中却气愤难平。（一直）到了半夜还不能入睡，惆怅徘徊翻来覆去睡不着。', poem_notes = '兹：此。麦城楼故城在今湖北当阳东南，漳、沮二水汇合处\n聊：姑且，暂且。暇日：假借此日。暇：通“假”，借。销忧：解除忧虑。\n斯宇之所处：指这座楼所处的环境。\n实显敞而寡仇：此楼的宽阔敞亮很少能有与它相比的。寡，少。仇，匹敌。\n挟清漳之通浦：漳水和沮水在这里会合。挟，带。清障，指漳水，发源于湖北南漳，流经当阳，与沮水会合，经江陵注入长江。通浦，两条河流相通之处。\n倚曲沮之长洲：弯曲的沮水中间是一块长形陆地。倚，靠。曲沮，弯曲的沮水。沮水发源于湖北保康，流经南漳。当阳，与漳水会合。长洲，水中长形陆地。\n背坟衍之广陆：楼北是地势较高的广袤原野。背：背靠，指北面。坟：高。衍：平。广陆：广袤的原野。\n临皋（gāo）隰（xí）之沃流：楼南是地势低洼的低湿之地。临：面临，指南面。皋隰：水边低洼之地。沃流：可以灌溉的水流。\n北弥陶牧：北接陶朱公所在的江陵。弥：接。.陶牧：春秋时越国的范蠡帮助越王勾践灭吴后弃官来到陶，自称陶朱公。牧：郊外。湖北江陵西有他陶朱公墓，故称陶牧。\n昭邱：楚昭王的坟墓，在当阳郊外。\n华实蔽野：（放眼望去）花和果实覆盖着原野。华：同“花”。\n黍（shǔ）稷（jì）盈畴：农作物遍布田野。黍稷：泛指农作物。\n信美：确实美。吾土：这里指作者的故乡。\n曾何足以少留：竟不能暂居一段.曾,竟.\n遭纷浊而迁逝：生逢乱世到处迁徙流亡。纷浊：纷乱混浊，比喻乱世。\n漫逾纪以迄今：这种流亡生活至今已超过了十二年。逾：超过。纪：十二年。迄今：至今。\n眷眷（juàn）：形容念念不忘。\n孰忧思之可任：这种忧思谁能经受的住呢？任，承受。\n凭，倚，靠。开襟：敞开胸襟。\n蔽荆山之高岑（cén）：高耸的荆山挡住了视线。荆山，在湖北南漳。高岑：小而高的山。\n路逶迤（wēiyí）而脩迥：道路曲折漫长。修，长。迥，远。\n川既漾而济深：河水荡漾而深，很难渡过。这两句是说路远水长归路艰难。\n悲旧乡之壅（yōng）隔兮：想到与故乡阻塞隔绝就悲伤不已。壅，阻塞。\n涕横坠而弗禁：禁不住泪流满面。涕，眼泪。弗禁，止不住。\n昔尼父之在陈兮，有“归欤”之叹音：据《论语·公冶长》记载，孔子周游列国的时候，在陈、蔡绝粮时感叹：“归欤，归欤！”尼父，指孔子。\n钟仪幽而楚奏兮：指钟仪被囚，仍不忘弹奏家乡的乐曲。《左传·成公九年》载，楚人钟仪被郑国作为俘虏献给晋国，晋侯让他弹琴，晋侯称赞说：“乐操土风，不忘旧也。”\n庄舄（xì）显而越吟：指庄舄身居要职，仍说家乡方言。《史记·张仪列传》载，庄舄在楚国作官时病了，楚王说，他原来是越国的穷人，现在楚国作了大官，还能思念越国吗？便派人去看，原来他正在用家乡话自言自语。\n人情同于怀土兮：人都有怀念故乡的心情。\n岂穷达而异心：哪能因为不得志和显达就不同了呢？\n惟日月之逾迈兮：日月如梭，时光飞逝。惟，发语词，无实义。\n俟（sì）河清其未极：黄河水还没有到澄清的那一天。俟，等待。河，黄河。未极，未至。\n冀王道之一平：希望国家统一安定。冀，希望。\n假高衢（qú）而骋力：自己可以施展才能和抱负。假，凭借。高衢：大道。\n惧匏（páo）瓜之徒悬：担心自己像匏瓜那样被白白地挂在那里。《论语·阳货》：“吾岂匏瓜也哉？焉能系而不食？” 比喻不为世所用。\n畏井渫（xiè）之莫食：害怕井淘好了，却没有人来打水吃。渫，淘井。《周易·井卦》：“井渫不食，为我心恻。” 比喻一个洁身自持而不为人所重用的人。\n步栖（qī）迟以徙倚：在楼上漫步徘徊。栖迟，徙倚都有徘徊、漫步义。\n白日忽其将匿（nì）：太阳将要沉没。匿，隐藏。\n风萧瑟而并兴：林涛阵阵，八面来风。萧瑟，树木被风吹拂的声音。并兴，指风从不同的地方同时吹起。\n天惨惨而无色：天空暗淡无光。\n兽狂顾以求群：野兽惊恐地张望寻找伙伴。 狂顾：惊恐地回头望。\n鸟相鸣而举翼：鸟张开翅膀互相地鸣叫。\n原野阒（qù）其无人：原野静寂无人。阒，静寂。\n征夫行而未息：离家远行的人还在匆匆赶路。\n心凄怆以感发：指自己为周围景物所感触，不禁觉得凄凉悲怆。\n意忉怛（dāodá）而憯（cǎn）恻：指心情悲痛，无限伤感。这两句为互文。憯，同“惨”。\n循阶除而下降：沿着阶梯下楼。循，沿着。除，台阶。\n气交愤于胸臆：胸中闷气郁结，愤懑难平。\n夜参半而不寐：即直到半夜还难以入睡。\n怅盘桓以反侧：惆怅难耐，辗转反侧。盘桓，这里指内心的不平静。', poem_appreciation = '这篇赋以铺叙手法，由登楼极目四望而生忧时伤事之慨，并把眷恋故乡、怀才不遇之情巧妙地结合起来，而各层自有重点，深挚的感情，徐徐道来，感人至深，真不愧名家手笔。\n\n　　这篇赋主要抒写作者生逢乱世、长期客居他乡、才能不能得以施展而产生思乡、怀国之情和怀才不遇之忧，表现了作者对动乱时局的忧虑和对国家和平统一的希望，也倾吐了自己渴望施展抱负、建功立业的心情。全篇抒情意味很浓，“忧”字贯穿全篇，风格沉郁悲凉，语言流畅自然，是建安时代抒情小赋的代表性作品。\n\n　　此赋有如下特点：一、层次清晰。全文分为三段，首段写登楼所见，次段叙怀乡之情，末段抒身世之惧，遵循主人公情绪的自然发展而来，层次极为清晰。\n\n　　二、结构严谨。第一段写景中透露出“忧思”，“望”“忧” 两字，奠定了全文的抒情基调。第二段集中表达了作者内心的沉重忧思。开头四句承上文“非吾土”抒发怀乡之情，“凭轩槛以遥望兮”中的“望”字，化景物为情思。第三段对思乡之情进一步开掘，揭示出“忧思”深层的政治内涵。情景交融。首段写异乡风光：地势开阔，山川秀美，物产富饶，以眼前乐景反衬心中哀情。末段写傍晚景色：日惨风萧，兽狂鸟倦，原野寂寥，烘托出作者内心的凄怆。前后景物描写，即景生情，寓情于景，一乐一悲，相互照应，真切的反映出作者愁绪步步加深、忧伤至极的过程。\n\n　　三、语言清丽。文章用典贴切，注意与主观感情的抒发相契合。例如“瓠瓜徒悬”、“井渫莫食”等典故，都传达出作者的怀乡之情和怀才不遇的怨愤。文章大量运用富有音乐性的修饰词语。例如“眷眷”、“惨惨”、“凄怆”、“憯恻”、“盘桓”等，音节流畅，琅琅上口。\n\n　　四、主题深刻。这篇文章超越了一般的怀乡之作，揭示了深厚的政治内涵。“遭迁逝”句，概括了当时动荡的时代特征和作者悲惨不幸的遭遇；“惟日月”两句，表达了作者时不我待、急欲乘时而起的紧迫感；“冀王道” 两句，表达了作者以天下为己任、急于建功立业的使命感。总之，作者通过登楼四望，抒发了浓重的故土之思，倾吐了宏图难展的悲慨，表达了建功立业的迫切愿望。\n\n　　综上所述，这篇赋体貌高度精练，情思深厚丰腴，使读者自然而然地感觉其意味深永，形象感人，因此成为建安时期抒情小赋的杰作。', poem_tags = '辞赋精选,怀才不遇,思乡,抱负' WHERE poem_title = '登楼赋' AND poem_author = '王粲';
UPDATE edu_poem SET poem_translation = '一院子的菊花金黄金黄，中间有一丛白似霜的花儿是这么孤独。\n就像今天的酒席，老人家进了少年去的地方。', poem_notes = '郁金黄：花名，即金桂，这里形容金黄色的菊花似郁金黄。\n孤丛：孤独的一丛。\n白头翁：诗人自谓。', poem_appreciation = '白居易这首《重阳席上赋白菊》诗写得新颖而别致，词约而意丰。全诗表达了诗人虽然年老仍有少年的情趣。以花喻人，饶有情趣。\n\n　　题为“赋白菊”，诗开头却先道满园的菊花都是金黄色。“满园花菊郁金黄，中有孤丛色似霜。”这是用陪衬的手法，使下句中那白色的“孤丛”更为突出，犹如“万绿丛中一点红”，那一点红色也就更加显目了。“满”“郁”与“孤”两相对照，白菊更为引入注目。“色似霜”生动的比喻，描绘了白菊皎洁的色彩。\n\n　　更妙的是后两句：“还似今朝歌酒席，白头翁人少年场。”诗人由花联想到人，联想到歌酒席上的情景，比喻自然贴切，看似信手拈来，其实是由于诗人随时留心观察生活，故能迅速从现实生活中来选取材料，作出具体而生动的比喻。这一比喻紧扣题意，出人意料又在情理之中。结句“白头翁人少年场”，颇有情趣。白菊虽是“孤丛”，好似“白头翁”，但是却与众“少年”在一起，并不觉孤寂、苍老，仍然充满青春活力。', poem_tags = '菊花,重阳节' WHERE poem_title = '重阳席上赋白菊' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '天津桥下的冰刚结不久，洛阳的大道上便几乎没了行人。\n叶落枝秃的榆柳掩映着静谧的楼台亭阁，万籁俱寂，悄无人声。在明静的月光下，一眼便看到了嵩山上那皑皑白雪。', poem_notes = '天津桥：即洛桥，在今河南省洛阳西郊洛水之上。\n萧疏：形容树木叶落。\n嵩山：位于河南省西部，地处河南省登封市西北面，是五岳中的中岳。', poem_tags = '冬天,写景,抒情' WHERE poem_title = '洛桥晚望' AND poem_author = '孟郊';
UPDATE edu_poem SET poem_translation = '端午佳节，皇上赐予名贵的宫衣，恩宠有加。\n香罗衣是细葛纺成，柔软得风一吹就飘起，洁白的颜色宛如新雪。\n来自皇天，雨露滋润，正当酷暑，穿上它清凉无比。\n宫衣的长短均合心意，终身一世承载皇上的盛情。', poem_notes = '宫衣，指官服。被恩荣：指得到赏识而觉得荣幸。\n细葛含风软，香罗叠雪轻。葛，是一种植物，可用来织布，细葛，指用最细最好的葛丝做的布，含风软，指葛布像风那么柔软。香罗，罗是一种有孔的丝织品，香罗指罗的香味；叠雪轻，像雪花叠在一起那么轻。\n自天题处湿，当暑著来清。题，指衣服的领子部分，湿，不是说湿润的湿，而是柔软的料子贴在颈上，凉凉的很舒服。当暑，指在天气热的时候，著，指穿着；清，凉爽。\n意内，指心里。称长短，指计算了一下衣服的大小。荷圣情，指充满圣上的恩情。', poem_tags = '端午节,感恩' WHERE poem_title = '端午日赐衣' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '长江延绵曲折长达万里，分作九条支流就如同九条巨龙盘踞。江水四溢，泛滥于中国，波涛汹涌迅疾奔流。六代的帝王沉寂沦亡之后，三吴已没有了昔日之盛，无足称赏。我朝圣明之君统一天下，垂衣拱手无为而冶。今天的任公子，已无需沧海垂钓而罢竿了。', poem_notes = '派：河的支流。长江从庐江、浔阳开始分作九支。盘：盘踞。\n横溃：泛滥。豁：打开。中国：中南地区。\n崔嵬：山峦高耸的样子，这里用长,J-i皮涛的汹涌来比喻六朝动荡的政局。迅湍：飞奔而下的激流。\n六帝：即六朝，指以金陵为都的六个朝代的君主，吴、东晋、宋、齐、梁、陈。\n三吴：史称古吴地后分为三，即吴兴、吴郡、会稽。这两句合起来是说自从六朝之后，长江以东的吴地就日渐分裂，远不如从前那么兴盛了。\n我君：指当朝皇帝唐玄宗。混：混合，统一。区宇：全国的范围。\n垂拱：垂衣拱手，无为而治。指天下太平的景象。众流安：各条江河均平安，借指国泰民安，政治稳定。\n任公子：《庄子·外物篇》中一个传说人物。他在长江中下游广大的地区用很大的钓钩和极多的食饵钧起一只巨大的鱼，可供许多人一起享用。这里用任公子比喻有大作为和才能的人。\n沧浪：据《孟子》，有隐者唱《沧浪歌》以表明隐居之志，后人用沧浪指代隐居垂钓之地。', poem_appreciation = '这首诗以金陵为中心，写眺望长江远去的感想。全诗情景合一，寓比兴之意于写景之中。诗的前两句“汉水回万里，派作九龙盘。横溃豁中国，崔嵬飞迅湍。”都写出了长江下游万流横溃，直下东海，水势浩瀚，气势博大的特点，写出了远去的长江气势浩大，切中题旨，铺垫出一派雄壮气象。接着用江水泛滥造成的巨大影响和损失来写近古的国运不兴，为歌颂当下盛世蓄好气势。但诗的后四句“我君混区宇，垂拱众流安。今日任公子，沧浪罢钓竿。”并不是单纯而热烈地歌颂盛世，在一派祥和安宁之中，也透露出英雄无用武之地的淡淡悲哀。诗的感情深沉而表达稳妥，比喻以江水壮阔的气势与盛唐的国力相对应，贴切得体，从而自然又蕴含丰富地表达出盛世才子的惆怅。\n\n　　在此诗中李白已对万里长江的风光作了一个全面的描绘：上游之秀丽，三峡之急险，中游之宏阔，下游之浩瀚，都有极生动之描写，可以说李白用他的生花妙笔，为读者绘制了一幅极其宏伟的万里长江风光图卷。这是其它任何诗人所作不到的。而其他诗人，由于局于经历所限，对长江的描绘也只能是一时一处、一鳞一爪的个别描写，虽然他们可能写得很精彩，而不可能对万里长江绘出全图。即使是有人像李白那样有游万里长江的经历，但也未必像李白对长江那样的钟情，或虽钟情而不善于诗。\n\n　　李白漫游扬州时赋《秋日登扬州西灵塔》，称誉像教有“照迷方”之效。而《金陵望汉江》更值得关注，嘲笑东吴、东晋、宋、齐、梁、陈割据者依恃金陵钟山之险而称帝终归复亡的历史命运，同时盛赞李唐一统天下之伟绩。', poem_tags = '长江,写景,抒情,忧国忧民' WHERE poem_title = '金陵望汉江' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '雄雉在空中飞翔，舒展着五彩翅膀。我如此思念夫君，给自己带来忧伤。\n雄雉在空中飞翔，上下鸣唱声嘹亮。我那诚实的夫君，实让我心劳神伤。\n看日月迭来迭往，思念是那样悠长。道路相隔真遥远，何时才能回家乡？\n那些在位君子们，不知我夫德高尚。不贪荣名不贪利，为何让他遭祸殃！', poem_notes = '邶（bèi）：中国周代诸侯国名，地在今河南省汤阴县东南。\n雉（zhì）：野鸡，雄者有冠，长尾，身有文采，善斗。一说雉为耿介之鸟，交有时，别有伦。\n于：往。一说语助词。\n泄（yì）泄：鼓翅飞翔的样子。朱熹《诗集传》：“泄泄，飞之缓也。”\n怀：因思念而忧伤。\n自诒：自己给自己。诒（yí）：通”贻“，遗留。伊：此，这。阻：忧愁，苦恼。一说阻隔。\n下上其音：叫声随飞翔而忽上忽下。\n展：诚，确实。\n劳我心：即”我心劳“，因挂怀而操心、忧愁。劳，忧。\n瞻：远看，望。\n悠悠：绵绵不断。\n云：与下句的“云”同为语气助词。\n曷（hé）：何。此处指何时。\n百尔君子：你们这些君子。百，凡是，所有。尔，你们。君子，在位，有官职的大夫。\n德行：品德和行为。\n忮（zhì）：忌恨，害也。一说”贪求“。求：贪求。\n何用：何以，为何。不臧（zāng）：不善，不好。', poem_appreciation = '此诗前二章都是以雄雉起兴。“兴”就是见景生情：看到漂亮的雄野鸡在空中自由自在地飞，欢快自得地鸣叫，这个独守空房的女人心中很不是滋味。雄雉就在眼前，能见到它舒畅地拍翅膀，能听到它咯咯的叫声。而丈夫久役，既不能见其人，也不能闻其声。先是怀想，后是劳心，思妇的感情层层迭起。此二章只举雄雉，不言双飞，正道出离别，引出下文“怀”“劳”的情绪，写雄雉，又是从“飞”这一动态去描写它的神情（“泄泄其羽”）和声音（“下上其音”），突出其反复不止，意在喻丈夫久役不息，思妇怀想不已。\n\n　　第三章以日月的迭来迭往，来兴丈夫久役不归。同时，以日月久长来拟自己的悠悠思绪。而关河阻隔，怅问丈夫归来何期，亦可见思妇怀念之切。此章中的“瞻”字涵盖思妇所见。思妇与所见的日月构成意象空间，虚拟出一幅思妇正在伫立遥望的情景，加以前文所见雄雉的点染，便传递出强烈的画面感。“道之云远”把思妇的视线指向其久役的丈夫，它与第一章“自诒伊阻”相承为义，分别从空间的距离（“远”）和空间的间断（“阻”）来说的。“曷云能来”，是对思妇“悠悠我思”的现实回答，也是思妇瞻望的必然结果。道远路阻，丈夫无法回来，这也深深透露出对当时现实的无奈。\n\n　　第四章语气一转，忧其丈夫仕于乱世，希望他善能周全，可见其深思至爱之意。传说雉是耿介之鸟，就其品性可比君子，《王风·兔爰》“雉离于罗”，即比君子遭罪。此章“不知德行”从反面伸足此义，就其品性来讽劝君子。\n\n　　全诗前三章的意思可以归纳为一个词：思念。女主人公思念远在天边从役的丈夫，自己内心沮丧，不能排解。每天看着日升日落，月圆月缺，女人心中的思念也如这日月一样悠长。最后一章的意思可以归纳为一个词：批判。女主人公指责那些贵族君子们，是他们的贪欲造成了夫妻分离的悲剧。前三章的思念是为后一章的批评蓄势；而末章对在位君子的批判，突破个人私情，使诗歌的境界提升了一个高度。', poem_tags = '诗经,思念' WHERE poem_title = '雄雉' AND poem_author = '佚名';
UPDATE edu_poem SET poem_tags = '题画,抒情' WHERE poem_title = '水调歌头·题西山秋爽图' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '王勃路过钟陵，正赶上九月九日都督在滕王阁大宴宾客，事先背地里命他的女婿作一篇序以向宾客夸耀，于是拿出纸笔遍请宾客作序，大家都不敢担承。到王勃那里，竟漫不经心地接过笔来，也不推辞。都督大怒，起身假装上厕所，暗中派遣下属窥探王勃的文章，随时汇报。汇报了一两次之后，文章的语言越来越奇妙，都督兴奋地说：“这真是个天才！”连忙请他将文章全部写完，宾主尽欢而散。王勃做文章的时候，刚开始并不精密思索，先磨数升墨汁，然后大量饮酒，拉过一床被子蒙头而卧，等醒来之后，拿过笔来就写完全篇，一字不改，当时的人称王勃为“腹中写稿”。', poem_notes = '宿：事先。\n夸客：向宾客夸耀(女婿的才能)。\n勃：指王勃。\n泛然：轻松、愉快之意。\n语益奇：(勃文)更加奇妙（这里指一句比一句奇妙）。\n矍(jué)：惊惶貌。\n属(zhǔ)文：写文章。属，连缀。\n寤：睡醒。\n易：更改。', poem_tags = '小学文言文,故事,赞美,写人' WHERE poem_title = '王勃故事' AND poem_author = '宋祁';
UPDATE edu_poem SET poem_translation = '斑竹枝啊斑竹枝，泪痕点点寄托着相思。楚地的游子啊若想听听瑶瑟的幽怨，在这潇水湘江之上当着夜深月明之时。', poem_notes = '潇湘神：词牌名，一名《潇湘曲》。此词作于朗州（今湖南省常德市）时期，诗中所及山水和故事皆在湘沅间。潇湘：湖南西南部潇水、湘水。\n斑竹：即湘妃竹。相传舜崩苍梧，娥皇、女英二妃追至，哭啼极哀，泪染于竹，斑斑如泪痕，故谓“斑竹”。\n泪痕点点寄相思：《述异记》载，“舜南巡，葬于苍梧。尧二女娥皇、女英泪下沾竹，文悉为之斑。”\n楚客：本指屈原，此处为作者自况。作此词时刘禹锡正值贬官朗州（治所在今湖南常德）。\n瑶瑟：以美玉妆饰成的瑟。古代之管弦乐器。\n潇湘：潇水在今湖南零陵县西北合于湘水，称潇湘。', poem_tags = '宋词三百首,婉约,咏物,怀古,哀怨' WHERE poem_title = '潇湘神·斑竹枝' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '山坡上一级一级的畦田像楼梯，平原上整整齐齐的畦田像棋盘。\n白鹭忽然飞到水稻田上来，在一片绿色的秧苗上点上了白点。', poem_notes = '郊：泛指城外、野外、郊外。\n高田：沿着山坡开辟的田畦，又叫梯田。\n平田：指山下平地上的田块。\n棋局：象棋盘。\n鹭：一种长颈尖嘴的水鸟，常在河湖边、水田、沼泽地捕食鱼虾。\n点破：打破了。\n秧针：水稻始生的秧苗。', poem_tags = '古诗三百首,春天,田园,写景' WHERE poem_title = '出郊' AND poem_author = '杨慎';
UPDATE edu_poem SET poem_translation = '绿叶繁茂一片浓阴，池塘中布满水阁，这里最凉快。石榴花刚开，妖娆艳丽散发扑鼻的香气。老燕携带着小燕，叽叽地说着话，高高的柳枝上有蝉鸣相和。骤雨刹时飞来，像珍珠一般乱洒，打遍池塘里一片片新荷。\n人生能有多长时间，想想那良辰美景，好像刚刚做了一场梦一样。命运的好坏是由前生而定的，何必要自己苦苦操劳呢。邀请宾客朋友玩赏，喝酒唱歌，暂且喝个酩酊大醉，任凭它日月轮转，来往像穿梭。', poem_notes = '海榴：即石榴。\n撒：撒落。\n几：几许，此处指多长时间。\n穷通前定：意为失意得意命运的好坏由前生而定。\n命友：邀请朋友。\n芳尊：美酒。尊，即樽，酒杯。', poem_appreciation = '《唐诗三百首》中，只有两首是专抒夏日好处的，一首是孟浩然《夏日南亭怀辛大》：“山光忽西落，池月渐东上。散发乘夕凉，开轩卧闲敞。荷风送香气，竹露滴清响。……”一首是韦应物《郡斋雨中与诸文士燕集》：“兵卫森画戟，燕寝凝清香。海上风雨至，逍遥池阁凉。……”不约而同，都突出了“凉”的美感。夏日景物的色彩要比春天浓烈和热闹得多，文人却偏偏不敢去全身心地迎接，先要为自己留一块虚静的凉荫。也许这是因为在夏季的炎熇中，澄怀涤烦是娱目游心的首要前提，有“闲情”才有“逸致”。\n\n　　本篇前半绘写夏日园亭的自然景色，首先也是强调“凉多”。这是从池塘水阁遍布的一片“绿叶阴浓”来呈现的，屏绝了骄阳和暑气，构筑了理想的适于憩息的清凉世界。作者写的是“阴浓”，却不忘点明“绿叶”。因为随后两句便叙出了“朵朵蹙红罗”的石榴花，红绿相映，绘出了园亭夏景的浓烈色彩。这五句的基调是静谧的，于是作者又搜索到了园中的声：“老燕携雏弄语，对高柳鸣蝉相和。”燕子呢喃，蝉鸣高柳，表现了万物的安适自得，这不仅没有破坏宁和的氛围，反而更增添了夏景的恬美。在“偏趁凉多”的澄怀意境中，去进一步发现和领略夏令的美感，这是诗人高出一筹之处。\n\n　　最值得称妙的是诗人并不以此为满足，而是在写景的结尾添出一场“骤雨”。雨点“似琼珠乱撒”，跳跃奔放，“打遍新荷”，历历如闻，这一切都表现出诗人对它的欣赏。这一场骤雨的洗礼推出了一番全新的景象，不同于叠床架屋的泛泛之笔，但它的别开生面，却使前时的种种美感锦上添花。“凉多”是不用说了，从“选色”的方面看，它增出了“新荷”，且使前时的池亭水阁、绿树红花在“雨过”后更为明洁、泽润；从“征声”的一面说，燕语蝉鸣可能有一时的沉默，而“骤雨打新荷”的琤琮声却不啻是一支更为动听的乐曲，且仍有愈喧愈静、以闹助恬之妙。作者以之作为“良辰美景”的充分体现，并随之接出“休放虚过”的感慨，我们是能深会其心的。\n\n　　曲的下片转入抒写感慨的内容，一是人生苦短，二是穷通有命，于是得出了及时行乐的结论。这种感想本属于老生常谈，但我们并不觉陈腐可厌，正是因为它得自即景抒情，而前时的写景已作了成功的铺垫。一来是上片的景语中确实充分集中了夏日的“良辰美景”，值得不计代价地去“玩赏”、“酩酊”；二来是诗人在叙景中洋溢着一派隐逸脱俗的天趣，“何用苦张罗”，便带有蔑视奔竞、看破红尘的高士风味；三来是“骤雨打新荷”这一自然现象的变化与“两轮日月，来往如梭”的人世社会的变化同有可味之处，顺适自然，委运任化，也就有了逻辑上的联系。“人生如梦”四字算得耳熟能详了，但我们读了苏东坡“大江东去”的《念奴娇》，照样觉得震铄耳目。可见一首成功的文学作品，于自身的艺术美感之外，还往往能激起读者对人生常理的深思与共鸣。\n\n　　这是作者在《小圣乐》曲调基础上的自度曲，问世后流播人口，“名姬多歌之”。笔记载赵孟頫日后在歌筵上听歌女献唱此曲，感慨作诗，有“主人自有沧洲趣，游女仍歌白雪词”之句（见《辍耕录》）。可见此曲对散曲的初创及扩大影响，起了不小的作用。早期文人的自度散曲本质是词，亦以词法为之；不同于晚期宋词的是它配上了北曲的宫调。《四库全书总目提要》：“自宋赵彦肃以句字配协律吕，遂有曲谱。至元代，如《骤雨打新荷》之类，则愈出愈新”，便指出了这一特点。言下也有视此曲为散曲开山之祖的含意。', poem_tags = '写景,抒怀' WHERE poem_title = '骤雨打新荷' AND poem_author = '元好问';
UPDATE edu_poem SET poem_tags = '冬天,月夜,写雪' WHERE poem_title = '十二月十五夜' AND poem_author = '袁枚';
UPDATE edu_poem SET poem_translation = '去年相送于余杭门外，大雪纷飞如同杨花。如今春天已尽，杨花飘絮似飞雪，却不见离人归来，怎能不叫人牵肠挂肚呢？\n卷起帘子举起杯，引明月作伴，可是风露又乘隙而入，透过窗纱，扑入襟怀。月光无限怜爱那双宿双栖的燕子，把它的光辉与柔情斜斜地洒向画梁上的燕巢。', poem_notes = '少年游：词牌名。\n润州：今江苏镇江。\n余杭门：北宋时杭州的北门之一。\n“对酒”句：写月下独饮。\n姮娥：即嫦娥，月中女神。亦代指月。', poem_appreciation = '宋神宗熙宁七年(1074)三月底、四月初，任杭州通判的苏轼因赈济灾民而远在润州时(今江苏镇江)。为寄托自己对妻子王润之的思念之情，他写下了这首词。此词是作者假托妻子在杭思己之作，含蓄婉转地表现了夫妻双方的一往情深。\n\n　　上片写夫妻别离时间之久，诉说亲人不当别而别、当归而未归。前三句分别点明离别的时间——“去年相送”；离别的地点——“余杭门外”；分别时的气候——“飞雪似杨花”。把分别的时间与地点说得如此之分明，说明夫妻间无时无刻不在惦念。大雪纷飞本不是出门的日子，可是公务在身，不得不送丈夫冒雪出发，这种凄凉气氛自然又加深了平日的思念。后三句与前三句对举，同样点明时间——“今年春尽”，气候——“杨花似雪”，可是去年送别的丈夫“犹不见还家”。原以为此次行役的时间不长，当春即可还家，可如今春天已尽，杨花飘絮，却不见人归来，怎能不叫人牵肠挂肚呢？这一段引入了《诗·小雅·采薇》“昔我往矣，杨柳依依；今我来思，雨雪霏霏”的手法，而“雪似杨花”、“杨花似雪”两句，比拟既工，语亦精巧，可谓推陈出新的绝妙好辞。\n\n　　下片转写夜晚，着意刻画妻子对月思己的孤寂、惆怅。“对酒卷帘邀明月，风露透窗纱”，说的是在寂寞中，本想仿效李白的“举杯邀明月，对影成三人”，卷起帘子引明月作伴，可是风露又乘隙而入，透过窗纱，扑入襟怀。结尾三句是说，妻子在人间孤寂地思念丈夫，恰似姮娥在月宫孤寂地思念丈夫后羿一样。姮娥怜爱双栖燕子，把她的光辉与柔情斜斜地洒向那画梁上的燕巢，这就不能不使妻子由羡慕双燕，而更思念远方的亲人。', poem_tags = '婉约,思念' WHERE poem_title = '少年游·润州作' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '杨贵妃绝代佳人与红艳牡丹相得益彰，美人与名花常使君王带笑观看。动人姿色似春风能消无限怨恨，在沉香亭北君王贵妃双双倚靠着栏杆。', poem_notes = '名花：指牡丹花。\n倾国：指杨贵妃。\n解释：消除。\n沉香亭：亭子名称。在唐兴庆宫龙池东。', poem_tags = '乐府,写人,写花' WHERE poem_title = '清平调·其三' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '这样寂寞还等待着什么？天天都是怀着失望而归。\n我想寻找幽静山林隐去，又可惜要与老朋友分离。\n当权者有谁肯能援引我，知音人在世间实在稀微。\n只应该守寂寞了此一生，关闭上柴门与人世隔离。', poem_notes = '寂寂：落寞。竟何待：要等什么。\n空自：独自。\n欲寻芳草去：意思是想归隐。芳草：香草，常用来比喻有美德的人。\n违：分离。\n当路：当权者。假：提携。\n扉：门扇。', poem_appreciation = '这首诗是孟浩然回襄阳临行前留给王维的。诗人抒发出由于没人引荐，缺少知音而失意的哀怨情怀。这首诗表达直率，语言浅显，怨怼之中，又带有辛酸意味，感情真挚动人，耐人寻味。\n\n　　第一联写落第后的景象：门前冷落，车马稀疏。“寂寂”两字，既是写实，又是写虚，既表现了门庭的景象，又表现了作者的心情。一个落第士子，没有人来理睬，更没有人来陪伴。只有孤单单地“空自归”了。在这种情形下，长安虽好，也没有什么可留恋的。他考虑到返回故乡了，“竟何待”正是他考试不中必然的想法。\n\n　　第二联写惜别之情。“芳草”一词，来自《离骚》，王逸认为用以比喻忠贞，而孟浩然则用以代表自己归隐的理想。“欲寻芳草去”，表明他又考虑归隐了。“惜与故人违”，表明了他同王维友情的深厚。一个“欲”字，一个“惜”字，充分地显示出作者思想上的矛盾与斗争，从这个思想活动里，却深刻地反映出作者的惜别之情。\n\n　　“当路谁相假，知音世所稀”两句，说明归去的原因。语气沉痛，充满了怨怼之情，辛酸之泪。一个“谁”字，反诘得颇为有力，表明他切身体会到世态炎凉、人情如水的滋味。能了解自己心事，赏识自己才能的人，只有王维，这的确是太少了！一个“稀”字，准确地表达出知音难遇的社会现实。这在封建社会里是具有典型意义的。\n\n　　这一联是全诗的重点，就是由于这两句，使得全诗才具有一种强烈的怨怼、愤懑的气氛。真挚的感情，深刻的体验，是颇能感动读者的，特别是对于那些有类似遭遇的人，更容易引起共鸣。如果再从结构上考虑，这一联正是全诗的枢纽。由落第而思归，由思归而惜别，从而在感情上产生了矛盾，这都是顺理成章的。只是由于体验到“当路谁相假，知音世所稀”这一冷酷的现实，自知功名无望，才下定决心再回襄阳隐居。这一联正是第四联的依据。\n\n　　“只应守寂寞，还掩故园扉”，表明了归隐的坚决。“只应”二字，是耐人寻味的，它表明了在作者看来归隐是唯一应该走的道路。也就是说，赴都应举是人生道路上的一场误会，所以决然地“还掩故园扉”了。\n\n　　综观全诗，既没有优美的画面，又没有华丽辞藻，语句平淡，平淡得近乎口语。对偶也不求工整，却极其自然，毫无斧凿痕迹。然而却把落第后的心境，表现得颇为深刻。言浅意深，颇有余味，耐人咀嚼。\n\n　　这首诗是作者科举落第离开长安时赠别友人王维的作品。首联直接说出“自归”，颔联则写题意“惜别”，颈联说明“自归”之故——乃是知音既少，当道不用，此时不走，更待何时。尾联叙写决心隐居不仕，归隐田园。诗以失意后的牢骚贯穿全诗。语言平淡朴实，近于口语，不讲究对偶，顺其自然。\n\n　　在京求仕不成， 诗中便充溢着对“当路谁相假”的愤懑，并用“独寻芳草去”自我解嘲。\n\n　　综观全诗，既没有优美的画面，又没有华丽辞藻，语句平淡，平淡得近乎口语。对偶也不求工整，却极其自然，毫无斧凿痕迹。然而却把落第后的心境，表现得颇为深刻。言浅意深，颇有余味，耐人咀嚼。', poem_tags = '唐诗三百首,离别,友情,哀怨,归隐' WHERE poem_title = '留别王侍御维 / 留别王维' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '庭院很深很深，不知有多少层深，云雾缭绕的楼阁门窗经常关闭。骋目四望，只见柳梢返青和梅枝吐蕊的景象越来越分明了。在古秣陵城的周围，树木渐绿，宣告春已归来，但我却无家可归，看来要老死建康城了。\n忆往昔多少回吟赏风月，饮酒作诗，那是多么幸福啊，而如今却人已老去，什么事也做不成了！还有谁会怜悯你的憔悴与衰败？元宵试灯也好，踏雪赏景也好，都没有这份心情了。', poem_notes = '临江仙：原唐教坊曲名，双调小令，后用作词牌名。此词上下片共六十字，平韵格。\n欧阳公：即北宋文学家欧阳修。《蝶恋花》：指欧阳修词作《蝶恋花·庭院深深深几许》。\n予：我。酷爱：非常喜爱。\n数阕：几首。阕，首。\n声：指词牌。\n几许：多少。\n云窗雾阁：云雾缭绕的楼阁。扃（jiōng）：门环、门闩等。在此谓门窗关闭。\n梅萼（è）：梅花的蓓蕾。\n秣（mò）陵：秦改金陵为秣陵，与下文“建康城”是同一地方，即今江苏南京。\n人老建康城：一作“人客建安城”。建康，又作“远安”。\n感月吟风：即“吟风弄月”，指以风月等自然景物为题材写诗填词，形容心情悠闲自在。\n无成：这里并不是一般意思上的事业无成，而是承上词意，指对“风月”不感兴趣，也不敢去接触，什么也写不出来。\n凋零：形容事物衰败。\n试灯：旧俗农历正月十五日元宵节晚上张灯，以祈丰稔，未到元宵节而张灯预赏谓之试灯。\n踏雪：谓在雪地行走。亦指赏雪。', poem_appreciation = '词作上片写春归大地，词人闭门幽居，思念亲人，自怜飘零。“庭院深深深几许？云窗雾阁常扃”，首二句写词人闭门幽居。首句与欧阳修《蝶恋花》词一样，连用三个“深”字，前两个“深”字为形容词，形容庭院之深；后一个“深”字为动词，作疑问句，加重语气，强调深。连叠三个“深”字，乃比兴之作。貌写闺情，实蕴国恨。次句是用韩文公《华山仙女诗》“云窗雾阁事恍惚，重重翠幕深金屏”，再加强“深”的意境，“常扃”与陶渊明《归去来辞》“门虽设而常关”，同一机杼，孤寂之心，忧愤之情，跃然纸上。词境静穆，不言愁苦，而使人更难为怀。云雾缭绕着楼阁，门窗常常紧闭，虽不深而似深，这是对庭院之深的具体描写。云雾缭绕是自然状况，是地处闽北高山地区建安所特有的，而门窗“常扃”，则是词人自己关闭的了。这表明词人自我幽闭阁中，不愿步出门外，甚至不愿看见外面景况，所以不仅闭门而且关窗。李清照酷爱“深深深几许”之语，是很有艺术见地的。因为它一连叠用三个“深”字，不仅渲染出庭院的深邃，而且收到了幽婉、复沓、跌宕、回环的声情效果。它跟下句合起来，便呈现出一幅鲜明的立体图画：上句极言其深远，下句极言其高耸。用皎然的话说，这就叫“取境偏高”（《诗式·辨体有一十九字》）；用杨载的话说，这就叫“阔占地步”（《诗法家数》）。它给欣赏者以空间无限延伸的感觉。但句尾一缀上“常扃”二字，就顿使这个高旷的空间一变而为令人窒息的封闭世界。\n\n　　第三句写的就是词人所不愿见到的景物：“柳梢梅萼渐分明。”柳梢吐绿，梅萼泛青，一片早春、大地复苏的风光。写景如画，不设色，淡墨钩线，着一“渐”字，为点睛之笔。李清照是位感情十分丰富细腻的词人，对大自然的细微变化，有着敏感的悟性。“雪里已知春信至”（《渔家傲》）、“春到长门春草青，江梅些子破，未开匀”（《小重山》），在这些早期作品里，表现的是喜春之情。可如今却怕见春光。结二句写的就是怕见春光的原因：“春归秣陵树，人客建安城。”这两句内涵极其丰富，所蕴含的痛楚情怀是相当深沉的。两句铺叙，合时、合地，境界自成。“春归”时间概念，“秣陵树”空间概念，意谓南宋偏安建康又一度春光来临了；“人老”时间概念，“建康城”空间概念，痛北人将老死南陲，创造出一种悲恸欲绝的境界。秣陵、建康，同地异名。它被分别置于上下对句之中，看似合掌（诗文内对句意义相同谓之“合掌”）。但上句写春归，是目之所见；下句写人老，是心之所感。它把空间的感受转化为时间的感受，从初春来临联想起人的青春逝去。情致丰富，毫不显得单调、重复。它貌似“正对”（即同义对）而实比“反对”（即反义对）为优，可视为此篇的警策。\n\n　　词作下片，承上片怕触景伤怀，进而追忆往昔，对比眼前，感到一切心灰意冷。“感月吟风多少事？如今老去无成”，今昔对比，无限感喟。李清照与赵明诚是一对有较高文化修养的恩爱夫妻，他们共迷金石，同醉诗文，烹茗煮酒，展玩赏鉴，沉醉于富有诗意的幸福生活之中。李清照以其女性的独特敏感和文学修养，以春花秋菊为题材，曾写过不少好词。“多少事”，以强调语气，表示很多，记也记不清了。可如今年老飘零，心情不好，什么事也做不成。至此，词人情绪极为激动，不禁呼出：“谁怜憔悴更凋零！”破碎山河无人收拾，词人憔悴瘦损、流落江南。词人在《永遇乐》中曾以“风鬟雾鬓”描绘她的“如今憔悴”。“谁怜”二字，表明词人身处异乡，孤身一人，无人可诉。而一个“更”字，道出了词人的心境日渐一日的悲凄。\n\n　　结末，“试灯无意思，踏雪没心情”。这二句并非写实，而是举出她一生中印象最深、与她夫妻生活最有关系，作为“感月吟风”绝佳题材的事件。“试灯”，是宋人元霄节前是盛事。词人在《永遇乐》中曾回忆当年：“中州盛日，闺门多暇，记得偏重三五。铺翠冠儿，捻金雪柳，簇带争济楚。”“踏雪”，宋周辉《清波杂志》卷八载：“顷见易安族人言，明诚在建康日，易安每值天大雪，即顶笠披蓑，循城远览以寻诗，得句必邀其夫赓和，明诚每苦之也。”这两件事，在空间上，从北（汴京）到南（建康）；在时间上，从词人青年时期到中年时期。当年，她对这两件事都很感兴趣，可如今，却认为“无意思”、“没心情”，与上片的怕见春光遥相呼应，进一步表露了词人对一切都感到心灰意冷。下片以对往昔生活的追怀、眷恋与如今飘零异地、悲凄伤感相对比，写出一位年老憔悴、神情倦怠的女词人形象。\n\n　　南渡以后，清照词风，从清新俊逸，变为苍凉沉郁，这首《临江仙》是她南渡以后的第一首能准确编年的词作。国破家亡，奸人当道，个中愁苦，不能不用含蓄曲折的笔法来表达。少女时代的清纯，中年时代的忧郁，一化而为老年时期的沉隐悲怆。', poem_tags = '春天,伤怀' WHERE poem_title = '临江仙·庭院深深深几许' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '你们。指学童们。\n立身：自立成人。\n朱紫：指达官显贵。唐制，官员五品以上穿红色的官服，三品以上穿紫色官服。故诗文中常以朱紫色代指高官。\n萤窗：晋人车胤，家贫无钱买灯油，就捕捉许多萤火虫放在丝囊中，供夜读时照明。后世便常以萤窗、萤案比喻刻苦读书。三冬：像三春、三秋一样，指三年。\n田舍郎：农夫、村夫。\n“将相”句：意谓当将相之人并非生来就是。语出《史记陈涉世家》。\n席上珍：宴席上的珍品。比喻儒生具有美善的才德。语出《礼记儒行》。\n儒冠：古代读书人所戴的一种帽子。借指以读书为业。\n相天下：当宰相治理天下。穷：事业不发达。善其身：使本身具有良好的修养。语出《孟子尽心上》。锦轴：用锦缎装饰的卷轴，指华丽的文书。古代书籍不分页，而用轴卷成一卷来展读。千文：即南朝梁人周兴嗣所作的《千字文》，是现存的较早的启蒙读物。间出：相间出现(在《千字文》中)。发：启发。蒙童：智慧还没有得到开发的幼童。\n惹春风：引来春风。\n谒：谒见。正式会见。相公：宰相。\n登科：也称登第，指在科举考试中考试及第。此指县试中考取秀才。\n大比：明清两代，每隔三年，各县、州、府的生员集中在省会考试，称乡试，亦称大比。考取者称举人。\n乡书：周代制度，乡大夫等地方官每隔三年献当地贤明者的书给周王，供周王挑选授职。因此后代称乡试中选为登乡书或登贤书。\n仙桂籍：即桂籍的美称。明清两代，举人在京城会试中选的，称进士；考中进士犹如月中折桂，所以进士的名册被称为桂籍。\n天府：天宫。这儿比喻皇宫。明清两代，考中进士后还得在皇宫参加殿试，以定名次。快：喜悦。\n青钱选：古时的铜钱以色青为贵，故人挑选铜钱都先选青钱。这里比喻科举考试时文章写得好，每次都被选中。\n俊英：指文才出众的人。\n脱迹：超脱，摆脱。雁塔：即大雁塔，在今陕西西安市东南四公里大慈恩寺内。唐代，每年新考中的进士都在大雁塔题上姓名，作为一种荣耀，故后世常称考中进士为雁塔题名。禹门：即龙门。在今山西稷山县西北黄河流经处，相传是大禹在治水时开凿。此处水流湍急，相传鱼若逆水游上就能变成龙。唐代以后将科举考试中选比喻为登龙门。三汲浪：三次跃出波浪。比喻在乡试、会试、殿试中屡次中选。比喻考取进士引起的震动。端的：果然。金榜：公布科举及第者姓名的布告。因贯用黄纸，故称。状头：即状元，进士中的第一名。三百辈：三百人。明清科举制度，每次会试录取三百名进士。瀛洲：传说中东海里神仙所栖之三座仙山之一。唐太宗设立文学馆，被延聘的人全国仰慕，称为“登瀛洲”、“步瀛洲”。\n岧峣(tiáo,yáo)：高大峻峭的样子。\n衢(qú)：四通八达的街道。物华：万物之精华。此指各种各样精美的货物。\n“风云”句：指明君贤臣会合的大好时机。语出王褒《圣主得》。\n“日月”二句：陈后主《入隋侍宴应诏》中的诗句。\n万年书：使国家能长治久安、永远兴盛的施政方案。\n土脉：土地的脉络。阳和：温暖和畅之气，即春气。\n韶华：春光，春天的景象。\n梅花初放，冲破了寒冬腊月，迎来了新春正月。腊：本是古代岁末祭祀众神之名。汉代起于农历十二月腊祭众神，故称之为腊月。\n侵：在这儿是染、映的意思。\n长安：今陕西省西安市。西汉、唐代等朝，都建都于此。此被用作京都的代称。游冶：也作冶游，在春天外出游玩。雨刚停不久，又飘洒下几点雨来。寒食：古代节日，在清明节前一、两天。节日期间，家家熄火种，不得举火，故名寒食。古代神话传说，蜀国国王杜宇，死后化为杜鹃，鸣声凄厉如泣，啼至血出乃止。杜鹃花色红如血，相传是社鹃的血泪染成的。底事：何事，为什么。\n凤阁：四面开窗，夏天用以纳凉的楼房。\n霁(jì)：雨止放晴。\n金风：秋风。\n农历七月七日是七夕节。相传每年的七夕夜晚，银河两岸的牛郎星和织女星登上临时由喜鹊架成的桥在银河中相会。人们在庭院中陈列瓜果酒食祭祀牵牛、织女二星，谓之“乞巧”。\n相传唐代的郭子仪初从军时，曾在七夕见仙女坐彩车从天而降，郭子仪知是织女，固向她祷求长寿富贵。后郭子仪果然寿至九十，官至太尉、尚书令。\n《世说新语排调》载：七夕那天，人们都晒衣物，郝隆却仰卧庭中。人们问他干什么这样，他口答说：“我在晒肚子里的书。”郝隆子：郝隆是晋代名士；子是尊称。\n这四句是唐诗人李白《九日龙山饮》诗。龙山在今湖北江陵西郊。古人习于农历九月九日重阳节登高饮酒。东晋时征西大将军桓温曾在重阳节携孟嘉等佐吏登龙山饮酒，孟嘉的帽子被风吹落而不觉，一时传为佳话。“舞爱”句，在月下舞蹈，月光皓洁可爱，如在挽留游人。\n四句是李白《九月十日即事》诗。觞(shāng)：盛着酒的酒杯。两重阳：唐俗，京城的人们常在重阳后的一天再次宴会赏菊，故九月十日有“小重阳”之称。\n北帝：指主管冬季的天神。纳嘉禾：庄稼丰收。冬至日太阳最为偏南，过后就一天比一天升高一些。云物：天上的云彩。古人以为云彩的颜色能预报天下的吉凶，在冬至那天有登上高台观察云色的礼仪。更筹：古代在夜间用来计时的竹签，亦名更签。斗柄：北斗七星状若斗勺，其第五至第七之三星似斗勺之柄，称斗柄；北斗星随季节的推移在空中转动，周而复始，每年立春时，斗柄正指向东方；立秋时指西方。暄：温暖。“客鬓”句：除夕之夜隔开寒暖新旧两年，旅客离乡在外，过此一夜就经历了两个不同的年份，思乡之情更加急迫，催人老去，以上四句是宋人李福源《岭外守岁》诗。\n解：懂得，会。\n以上四句出自李峤的《风》。\n典出唐诗人崔护《题都城南庄》诗，原诗是去年今日此门中，人面桃花相映红。人面不知何处去，桃花依旧笑春风。\n(带雨的梨花)像是正在哭泣的美人杨贵妃的脸。出自白居易诗。\n霜葩：色白如霜的花。\n色间：花色间杂在一起，即承上句说李花与桃花结为伴侣。以上四句诗形容李花。\n(牡丹花)像倾国倾城的美人，其姿态、容貌与众不同。\n轻薄：看轻，瞧不起。以上四句描写牡丹花。\n化用宋诗人林逋《咏梅诗》中诗句“暗香浮动月黄昏”。以上四句引用王安石《梅花》诗；王诗“一”作“数”，“惟”作“为”。谓梅花适宜与竹、松等量齐观。我国古代称松、竹、梅三种耐寒的观赏植物为“岁寒三友”。以上四句都是形容梅花的。谓居住的地方不可没有君子，故应种植松、竹、梅等像君予那样耐得住风霜寒冷的有节操的植物来作为长久相交的朋友。语出金代元好问《丐论》。《酉阳杂俎》载李德裕言北都童子寺有竹一窠，每日竹报平安。\n泗泽：河流和沼泽。泗即泗河，在今江苏省北部。此泛指河流。\n夏天的云朵大多状如奇形怪状的山峰。\n秀孤松：孤立的苍松一株独秀。\n古代的文人以弹琴、下棋、作诗、饮酒为风雅高尚的娱乐活动。\n风花雪月：古人以夏季的风、春季的花、冬季的雪、秋季的月作为四季风光的典型事物，故常以“风花雪月”来概括四季的景象。\n悠闲富贵又高名远扬。散神仙：道教传说中不在神仙世界担任官职的神仙。比喻悠闲自在。\n道院：有道之士所居住的院落。仙客：像仙人一样高雅脱俗的宾客。\n栖凤竹：竹的美称。相传凤凰以竹实为食物。\n化龙鱼：鲤鱼的美称。相传鲤鱼跃过龙门就变化为龙。\n黄花：菊花。▲' WHERE poem_title = '神童诗' AND poem_author = '汪洙';
UPDATE edu_poem SET poem_translation = '楚襄王问宋玉说：“先生也许有不检点的行为吧？为什么士人百姓都那么不称赞你呢？”\n　　宋玉回答说：“是的，是这样，有这种情况。希望大王宽恕我的罪过，允许我把话说完。”\n　　“有个人在都城里唱歌，起初他唱《下里》、《巴人》，都城里跟着他唱的有几千人；后来唱《阳阿》、《薤露》，都城里跟着他唱的有几百人；等到唱《阳春》、《白雪》的时候，都城里跟着他唱的不过几十人；最后引其声而为商音，压低其声而为羽音，夹杂运用流动的徵声时，都城里跟着他应和的不过几个人罢了。这样看来，歌曲越是高雅，和唱的人也就越少。\n　　“所以鸟类中有凤凰，鱼类中有鲲鱼。凤凰展翅上飞九千里，穿越云霓，背负着苍天，两只脚搅乱浮云，翱翔在那极高远的天上；那跳跃在篱笆下面的小鷃雀，岂能和它一样了解天地的高大！鲲鱼早上从昆仑山脚下出发，中午在渤海边的碣石山上晒脊背，夜晚在孟诸过夜；那一尺来深水塘里的小鲵鱼，岂能和它一样测知江海的广阔！\n　　“所以不光是鸟类中有凤凰，鱼类中有鲲鱼，士人之中也有杰出人才。圣人的伟大志向和美好的操行，超出常人而独自存在，一般的人又怎能知道我的所作所为呢？”\n\n译文二\n　　楚襄王向宋玉问道：“先生难道有什么不好的行为吗？为什么广大士民都说您不好呢？”\n　　宋玉回答说：“是的，不错，有这么回事。但希望您能宽恕我的过失，让我把话说完。”\n　　“有一位在郢都唱歌的客人，开始他唱《下里》、《巴人》，都城里聚集起来跟着唱的有数千人，接着他唱《阳阿》、《薤露》，都城里聚集起来跟着唱的有数百人，后来他唱《阳春》，《白雪》，都城里聚集起来跟着唱的不过几十人，最后他时而用商音高歌，时而以羽声细吟，其间杂以宛转流利的徵音，这时都城里聚拢来跟着唱的不过数人而已。这说明他唱的歌越是高深，能跟着和唱的就越少。”\n　　“故此，鸟中有凤凰而鱼中有大鲲。凤凰拍击空气，直上九千里的高空，贯穿云霞，背负青天，在高渺的天空展翅翱翔；而那跳跃于篱笆之间的鷃雀，哪能和风凰同样衡量天地的高大呢？鲲鱼早上从昆仑大山出发，在碣石晒背曝鳍，晚上在孟诸大泽投宿；那处于小小池塘之中的鱼儿，怎能与大鲲一样测知江海的浩瀚呢？不只是鸟中有凤鱼中有鲲啊！在‘士’中也有出类拔萃的人物。那些高洁的人物有如美玉一般的品行，超世独立；而那些世上的凡夫俗子又怎能理解我的行为呢？”', poem_notes = '其：用在谓语“有”之前，表示询问，相当于现代汉语的“大概”、“可能”、“或许”等。\n何士民众庶不誉之甚也：为什么那么多士民不称誉您呀？这是一种委婉的说法，实际的意思是说许多士民在指责你。何，用于句首，与句末的“也”相配合，表示反问或感叹的语气。士民，这里指学道艺或习武勇的人。古代四民之一。众庶，庶民，众民。誉，称誉，赞美。甚，厉害，严重。\n唯：独立成句，表示对对方的话已经听清楚或同意，相当于现代汉语的“是”、“嗯”等。然：这样。用来代上文所说的情况。\n愿：希望。毕：完毕，结束。\n客：外来的人。歌：唱。郢（yǐng）：楚国的国都，在今湖北江陵县西北，《下里》、《巴人》：楚国的民间歌曲，比较通俗低级。下里，乡里。巴人，指巴蜀的人民。国：国都，京城，属（zhǔ）：连接，跟着。和（hè）：跟着唱。\n《阳阿（-ē）》、《薤露（xiè-）》：两种稍为高级的歌曲。《阳阿》，古歌曲名。《薤露》，相传为齐国东部（今山东东部）的挽歌，出殡时挽柩人所唱。薤露是说人命短促，有如薤叶上的露水，一瞬即干。\n《阳春》、《白雪》：楚国高雅的歌曲。\n引：引用。刻：刻画。商、羽、徽：五个音级中的三个。古代音乐有宫、商、角、徵（zhǐ）、羽五个音级，相当于简谱中的1、2、3、5、6.杂：夹杂，混合。流。流畅。\n是：这。弥（mí）：愈，越。\n凤：凤凰，古代传说中的鸟王。一说雄的叫“凤”，雌的叫“凰”，通常都称作“凤”。鲲（kūn）：古代传说中的一种大鱼。\n绝：尽，穷。云霓：指高空的云雾。负：背，用背驮东西。苍天：天。翱翔（áoxiáng）：展开翅膀回旋地飞。平：用法相当于介词“于”，在。杳冥（yǎo）：指极远的地方。\n夫：那，那个。用在作主语的名词之前，起指示作用。下文的“夫”同。藩篱：篱笆。鷃（yàn）：一种小鸟。岂：用在谓语“料”前，与句末的“哉”一起，表示反诘。之：作介词“与”的宾语，代上文的“凤凰”。下文的“岂能与之量江海之大哉”的“岂”、“哉”、“之”同。料（liào）：估量，估计。\n朝（zhāo）：早晨。发：出发。昆仑：我国西北部的著名大山，西起帕米尔高原东部，横贯新疆、西藏间，东延入青海境内。墟（xū）：土丘。暴：暴露。鬐（qí）：鱼脊。碣石（jié-）：渤海边上的一座山。在今河北昌黎北。孟诸：古代大泽名，在今河南商丘东北、虞城西北。\n尺泽：尺把大的小池。鲵（ní）：小鱼。量：衡量，计量。\n非独：不但。\n瑰意琦行（guī-qí-）：卓越的思想、美好的操行。世俗：指当时的一般人。多含有平常、凡庸的意思。安：怎么，哪里，表示反问。\n世俗之民：这里是指一般的人，普通人。', poem_tags = '古文观止,写人,品格' WHERE poem_title = '对楚王问' AND poem_author = '宋玉';
UPDATE edu_poem SET poem_translation = '城上春光明媚莺啼燕啭，城下碧波荡漾拍打堤岸。绿杨芳草几时才会衰败？我泪眼迷蒙愁肠寸断。\n人到晚年渐觉美好情怀在衰消，面对鸾镜惊看红颜已暗换。想当年曾因多病害怕举杯，而如今却唯恐酒杯不满。', poem_notes = '莺语：黄莺婉转鸣叫好似低语。\n拍岸：拍打堤岸。\n鸾镜：镜子。古有“鸾睹镜中影则悲”的说法，以后常把照人的镜子称为“鸾镜”。朱颜：这里指年轻的时候。\n芳尊：盛满美酒的酒杯，也指美酒。', poem_tags = '宋词精选,春天,婉约,失意,遣怀' WHERE poem_title = '木兰花·城上风光莺语乱' AND poem_author = '钱惟演';
UPDATE edu_poem SET poem_translation = '采集花草的姑娘巳经无踪无影，我也顿时失去游山玩水的心情。流落异乡总是以写诗诉说愁苦，那有心思细细欣赏春天的光景。\n去年的燕子已飞向辽远的南方，今年的燕子该落在谁家的梁栋?暮春三月不要听那夜间的风雨，雨声不催花开，但见遍地落红。', poem_notes = '采芳人：指游春采花的女子。 杳（yǎo）：没有踪迹。 顿觉：顿时觉得。 游情：游玩的心情。\n草草：草率。\n燕子：词人自喻。\n天涯：形容很远的地方。\n谁家：何处。', poem_tags = '写景,伤春,写鸟,抒怀' WHERE poem_title = '清平乐·采芳人杳' AND poem_author = '张炎';
UPDATE edu_poem SET poem_translation = '壮年从军，曾经有一口气吞下敌人的豪迈气魄。浓重的云层高挂在天上。原来是烽火狼烟点着了。红润的面庞、头发乌黑（的年轻人），捧着雕饰精美的戈向西去戍边。讥笑自古以来的儒生大多耽误了宝贵的青春时光。\n上阵杀敌、建功立业的梦想已经破灭，却只能在吴楚大地上泛一叶扁舟。漫自悲歌，伤心地凭吊古人。烟波浩渺无际，边关到底在何处？感叹年华又被虚度了。', poem_notes = '“谢池春”：词牌名，又名“风中柳”、“玉莲花”等。\n“虏”：古代对北方外族的蔑视的称呼。\n“阵云”：浓重厚积形似战阵的云层。\n“狼烟”：烽火。古代边疆烧狼粪生烟以报警，所以称狼烟。\n“戍”：守边的意思。\n“儒冠”：儒生冠帽，后来指儒生。\n“流年”：流逝的岁月，年华。', poem_appreciation = '上片写词人过往的军旅生涯及感叹。“壮岁从戎，曾是气吞残虏。阵云高、狼烟夜举。朱颜青鬓，拥雕戈西戍”，这几句是词人对南郑生活的回忆。他那时是多么地意气风发，胸中怀抱着收复西北的凌云壮志，一身戎装，手持剑戈，乘马于胯下，随军止宿，气吞残虏。字里行间洋溢着一股豪气，颇能振奋人心。\n\n　　但接着词急转直下：“笑儒冠自来多误。”这一句化用杜甫《奉赠韦左丞丈二十二韵》的“纨绔不饿死，儒冠多误身”而来，感叹自已被儒家忠孝报国的思想所误，一生怀抱此志，却时至暮年仍旧一事无成。看上去，词人有悔意，悔恨自己不该学习儒家思想，执著于仕进报国，但实是对“壮岁从戎”的生活不再的哀叹。\n\n　　下片写老年家居江南水乡的生活和感慨。“功名梦断，却泛扁舟吴楚。”词人求取功名的愿望落空，被迫隐居家乡。为排遣愁怀，他四处泛舟清游。“漫悲歌、伤怀吊古”，虽身在江湖，但心仍在朝堂之上。词人没有办法真正做到自我宽解。他“泛扁舟吴楚”，吴楚古迹仍旧引发起他无限怀古伤今之意。\n\n　　“烟波无际，望秦关何处？叹流年又成虚度。”“秦关”，即北国失地。那淼淼的烟波仍不能消除词人对秦关的向往，因壮怀激烈，他至老仍旧不忘收复失地，不甘断送壮志，故闲散的隐居生活使他深感流年虚度。\n\n　　这首词上片怀旧，慷慨悲壮；下片写今，沉痛深婉。作者强烈的爱国感情在字里行间充分地流露出来，感人至深。\n\n　　爱国之情在陆游这篇作品里频有表述，且多慷慨激昂，壮怀激烈，而当词人晚年赋闲乡里，鬓白体衰之后回忆往事，更加悲恸万分，却又因无力回天，只落得无奈叹息。', poem_tags = '豪放,回忆,感慨,生活,爱国' WHERE poem_title = '谢池春·壮岁从戎' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '拂晓的云与攀在漫天游动，楼台殿阁高高耸立触天空。\n残星点点大雁南飞越关塞，悠扬笛声里我只身倚楼中，\n艳萦的菊花静静地吐芳幽，红红的莲花落瓣忧心忡仲。\n可惜鲈鱼正美回也回不去，头戴楚冠学着囚徒把数充。', poem_notes = '凄清：指秋天到来后的那种乍冷未冷的微寒，也有萧索之意。清，一作“凉”。拂曙：拂晓，天要亮还未亮的时候。流：指移动。\n汉家宫阙（què）：指唐朝的宫殿。动高秋：形容宫殿高耸，好像触动高高的秋空。\n残星，天将亮时的星星。雁横塞：因为是深秋，所以长空有飞越关塞的北雁经过。横，渡、越过。塞，关塞。\n长笛：古管乐器名，长一尺四寸。\n紫艳：艳丽的紫色，比喻菊花的色泽。篱：篱笆。\n红衣：指红色莲花的花瓣。渚：水中小块陆地。\n鲈（lú）鱼正美：西晋张翰，吴（治今江苏苏州）人。齐王司马冏执政时，任为大司马东曹掾。预知司马冏将败，又因秋风起，想念故乡的菜莼妒鱼脍的美味，便弃官回家。不久，司马冏果然被杀。\n南冠：楚冠。因为楚国在南方，所以称楚冠为南冠。《左传·成公九年》：“晋侯观于军府，见钟仪，间之日：‘南冠而絷者谁也？’有司对曰：‘郑人所献楚囚也。使悦之，召而吊之。’后用以“南冠”指囚徒或战俘。', poem_appreciation = '这首七律，通过诗人望中的见闻，写深秋拂晓的长安景色和羁旅思归的心情。\n\n　　首联总揽长安全景。在一个深秋的拂晓，诗人凭高而望，眼前凄冷清凉的云雾缓缓飘游，全城的宫观楼阁都在脚下浮动，景象迷蒙而壮阔。诗中“凄清”二字，既属客观，亦属主观，秋意的清冷，实衬心境的凄凉。正是这两个字，为全诗定下了基调。\n\n　　颔联写仰观。“残星几点”是目见，“长笛一声”是耳闻：“雁横塞”取动势，“人倚楼”取静态。景物描写见闻动静的安排，颇见匠心。寥落的残星，南归的雁阵，这是秋夜将晓时天空中最具特征的景象；高楼笛声又为之作了饶有情韵的烘托。这两句是说：晨曦初见，西半天上还留有几点残余的星光，北方空中又飞来一行避寒的秋雁。诗人的注意力正被这景象所吸引，忽闻一声长笛悠然传来，寻声望去，在那远处高高的楼头，依稀可见有人背倚栏杆吹奏横笛。笛声那样悠扬，那样哀婉：是在喟叹人生如晨星之易逝，还是因见归雁而思乡里、怀远人？吹笛人，你只管在抒写自己内心的衷曲，却可曾想到你的笛音竟这样地使闻者黯然神伤吗？这一联是赵嘏的名句。据《唐诗纪事》卷五十六记载，诗人杜牧对此赞叹不已，因称赵嘏为“赵倚楼”。杜牧如此激赏，恐怕就是由于它选景典型、韵味清远的缘故。\n\n　　颈联写俯察。夜色褪尽，晨光大明，眼前景色已是历历可辨：竹篱旁边紫艳的菊花，一丛丛似开未开，仪态十分闲雅静穆；水塘里面的莲花，一朵朵红衣脱落，只留下枯荷败叶，满面愁容。紫菊半开，红莲凋谢，正是深秋时令的花事；以“静”赋菊，以“愁”状莲，都是移情于物，拟物作人，不仅形象传神，而且含有浓厚的主观色彩。这与李清照《声声慢》中“满地黄花堆积，憔悴损”借菊之憔悴写人的愁苦有着异曲同工之妙。目睹眼前这憔悴含愁的枯荷，追思往日那红艳满塘的莲花，使人不禁会生出红颜易老、好景无常的伤感；而篱畔静穆闲雅的紫菊，俨然一派君子之风，更令人忆起“采菊东篱下”的陶靖节，油然而起归隐三径之心──写菊而冠以“篱”字，取意就在于此。\n\n　　上面三联所写清晨的长安城中远远近近的秋色，无不触发着诗人孤寂怅惘的愁思；末联则抒写胸怀，表示诗人毅然归去的决心。诗人说：家乡鲈鱼的风味此时正美，我不回去享用，却囚徒也似的留在这是非之地的京城，所为何来！“鲈鱼正美”，用西晋张翰事，表示故园之情和退隐之思；下句用春秋锺仪事，“戴南冠学楚囚”而曰“空”，是痛言自己留居长安之无谓与归隐之不宜迟。\n\n　　诗中的景物不仅有广狭、远近、高低之分，而且体现了天色随时间推移由暗而明的变化。特别是颔颈两联的写景，将典型景物与特定的心情结合起来，景语即是情语。雁阵和菊花，本是深秋季节的寻常景物，南归之雁、东篱之菊又和思乡归隐的情绪，形影相随，诗人将这些形象入诗，意在给人以丰富的暗示；加之以拂曙凄清气氛的渲染，高楼笛韵的烘托，思归典故的运用，使得全诗意境深远而和谐，风格峻峭而清新。', poem_tags = '秋天,写花,菊花,思归' WHERE poem_title = '长安晚秋 / 秋望 / 秋夕' AND poem_author = '赵嘏';
UPDATE edu_poem SET poem_translation = '春光幻照之下，山景气象万千。何必初见阴云，就要匆匆回家？\n就算天气晴朗，没有一丝雨意，走入云山深处，也会沾湿衣裳。', poem_notes = '山行：一作“山中”。\n春晖：春光。\n莫：不要。轻阴：阴云。便拟归：就打算回去。\n纵使：纵然，即使。\n云：指雾气、烟霭。', poem_tags = '春景,友情' WHERE poem_title = '山行留客' AND poem_author = '张旭';
UPDATE edu_poem SET poem_translation = '漫步城东门，美女多若天上云。虽然多若云，非我所思人。唯此素衣绿头巾，令我爱在心。\n漫步城门外，美女多若茅花白。虽若茅花白，亦非我所怀。唯此素衣红佩巾，可娱可相爱。', poem_notes = '东门：城东门。\n如云：形容众多。\n匪：非。思存：想念。思：语助词。存：一说在；一说念；一说慰籍。\n缟（gǎo 稿）：白色；素白绢。綦（qí 其）巾：暗绿色头巾。\n聊：愿。员（yún 云）：同“云”，语助词。\n闉闍（yīn dū 因都）：外城门。\n荼：茅花，白色。茅花开时一片皆白，此亦形容女子众多。\n且（jū 居）：语助词。一说慰籍。\n茹藘（rú lǘ 如驴）：茜草，其根可制作绛红色染料，此指绛红色蔽膝。“缟衣”、“綦巾”、“茹藘”之服，均显示此女身份之贫贱。', poem_appreciation = '郑之春月，也确如姚际恒所说，乃是“士女出游”、谈情说爱的美妙时令。《郑风·溱洧》一诗说，在清波映漾的溱水、洧水之畔，更有“殷且盈”的青年男女，“秉兰”相会、笑语“相谑”，互相赠送着象征爱情的“芍药”之花。此诗所展示的，则是男女聚会于郑都东门外的一幕，那景象之动人，也决不逊色于“溱洧”水畔。“出其东门，有女如云”、“出其闉阇，有女如荼”——二章复叠，妙在均从男主人公眼中写来，表现着一种突见众多美女时的惊讶和赞叹。“如云”状貌众女之体态轻盈，在飞彩流丹中，愈显得衣饰鲜丽、缤纷照眼；“如荼”表现众女之青春美好，恰似菅茅之花盛开，愈见得笑靥灿然、生气蓬勃。面对着如许众多的美丽女子，纵然是枯木、顽石，恐怕也要目注神移、怦然动心的。\n\n　　在迈出城门的刹那间，此诗的主人公也被这“如云”、“如荼”的美女吸引了。那毫不掩饰的赞叹之语，正表露着这份突然涌动的不自禁之情。然而，人的感情是奇特的，“爱情”则更要微妙难猜：“虽则如云，匪我思存”、“虽则如荼，匪我思且”——在众多美女前怦然心动的主人公，真要作出内心所爱的选择时，吐语竟如此出人意料。两个“虽则……匪我……”的转折句，正以无可动摇的语气，表现着主人公的情有独钟。好奇的读者自然要打听：他那幸运的恋人而今安在？“缟衣綦巾，聊乐我员”、“缟衣茹藘，聊可与娱”二句，即带着无限的喜悦和自豪，将这位恋人推到了你的眼前。如果你还知道，“缟衣綦巾”、“缟衣茹藘”，均为“女服之贫贱者”（朱熹），恐怕在惊奇之际，更会对主人公肃然起敬：原来他所情有独钟的，竟是这样一位素衣绿巾的贫贱之女！只要两心相知，何论贵贱贫富——这便是弥足珍惜的真挚爱情。主人公以断然的语气，否定了对“如云”、“如荼”美女的选择，而以喜悦和自豪的结句，独许那“缟衣茹藘”的心上人，也足见他对伊人的相爱之深。\n\n　　由此回看诗章之开篇，那对东门外“如云”、“如荼”美女的赞叹，其实都只是一种渲染和反衬。当诗情逆转时，那盛妆华服的众女，便全在“缟衣綦巾”心上人的对照下黯然失色了。这是主人公至深至真的爱情所投射于诗中的最动人的光彩，在它的照耀下，贫贱之恋获得了超越任何势利的价值和美感。', poem_tags = '诗经,爱情' WHERE poem_title = '出其东门' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '唉!国家兴盛与衰亡的命运，虽然说是天命，难道不是由于人事吗?推究庄宗得天下和他失天下的原因，就可以知道了。\n　　世人说晋王将死的时候，拿三支箭赐给庄宗，告诉他说：“梁国，是我的仇敌；燕王，是我扶持建立起来的；契丹与我订立盟约，结为兄弟，他们却都背叛晋而归顺梁。这三件事，是我的遗憾；给你三支箭，你一定不要忘记你父亲的愿望。”庄宗接了箭，把它收藏在祖庙里。此后出兵，就派随从官员用猪、羊各一头祭告祖庙，请下那三支箭，用锦囊盛着，背着它走在前面，等到凯旋时再把箭藏入祖庙。\n　　当庄宗用绳子捆绑着燕王父子，用木匣装着梁君臣的首级，进入太庙，把箭还给先王，向先王禀告成功的时候，他意气骄盛，多么雄壮啊。等到仇敌已经消灭，天下已经平定，一个人在夜间呼喊，作乱的人便四方响应，他仓皇向东出逃，还没有看到叛军，士卒就离散了，君臣相对而视，不知回到哪里去。以至于对天发誓，割下头发，大家的泪水沾湿了衣襟，又是多么衰颓啊。难道是得天下艰难而失天下容易吗?或者说推究他成功与失败的事迹，都是由于人事呢?《尚书》上说：“自满招来损害，谦虚得到好处。”忧虑辛劳可以使国家兴盛，安闲享乐可以使自身灭亡，这是自然的道理。\n　　因此，当庄宗强盛的时候，普天下的豪杰，都不能跟他抗争；等到他衰败的时候，几十个伶人围困他，就自己丧命，国家灭亡，被天下人讥笑。\n　　人生中的祸患常常是从细微的事情中积淀下来的，人的智慧和勇气常常被自己所溺爱的事物所困，难道只有宠爱伶人才会这样吗?', poem_notes = '伶官：伶，戏子，或唱戏杂技演员，现代的娱乐人员。伶官：宫庭里供统治者娱乐表演的人物。可见封建朝代不思于民生，不思于进取，奢华淫乐而痛失天下！伶官尚能使天下易主，可见不居安思危之害！\n理：道理。\n岂：难道。\n人事：指政治上的得失。\n原：推究，推其根本，形容词用作动词。\n世言：世人说。\n以：把。\n立：即位。\n其：语气副词，表示期望、命令的语气，一定。\n乃：你的。\n庙：太庙，帝王祭祀祖先的宗庙。\n从事：这里指负责具体事物的官员。\n少牢：祭品，用一猪一羊。牢，祭祀用的牲畜。\n锦囊：丝织的袋子。\n前：在前。\n负：背负。\n及：等到。\n凯：凯歌，打胜仗时所奏的曲子。\n旋：归，回。\n方：正在。\n系：捆绑。\n组：丝编的绳索，这里泛指绳索。\n函：匣子，名词用作动词，指用匣子装。\n仇雠：“雠”与“仇”同义，仇敌。\n一夫：一个人。\n仓皇：急急忙忙的样子。\n及：等到。\n断发：把发髻割下扔在地上，表示甘愿掉脑袋。\n抑：还是。\n本：探求，考察。\n书：《尚书》，儒家经典著作。\n兴：使……兴旺。\n逸豫：安闲快乐。\n迹：迹象。\n举：全，所有的。\n莫：没有人。\n忽微：极细小的东西。\n所溺：沉溺迷恋的人或事物。', poem_appreciation = '第一，选材与剪裁。\n\n　　本文属于史论性质，而用的主要是归纳论证方法。运用这种论证方法关键在于准确地选择具体事例。本文所用的主要事例是“晋王三矢”的故事，作者对此是下过一番选材和剪裁工夫的。任何历史家撰写历史都会面临两项要求，即记事既要全面，又要可信，但二者往往发生矛盾。为了全面最好能“有闻必录”，但所闻未必可信，所以又要遵守“无征不信”的原则。“晋王三矢”的故事在当时社会上是有影响的。所以宋初王禹在《五代史阙文》对此作了记录，以弥补薛居正等人所编的《旧五代史》的缺陷。欧阳修撰写《新五代史》，如果仍然不用这条材料，恐怕难免被人讥为疏陋；而如果加以引用，却又无法证明它确实可信。因此他采用了一种巧妙的处理方法：在《新五代史》的《庄宗本纪》中不用这条材料，表现了应有的谨严态度；同时却把这条材料写进《伶官传》的“序”中，并且加上“世言”二字，这就恰当地表明了这个材料的社会影响及其可信程度。这一处理不但解决了求全与求信的矛盾，而且对《伶官传序》来说还是一种积极的选材。因为序中如果再拿一些《庄宗本纪》写过的事来发议论，未免重复无味；而“晋王三矢”故事既是《庄宗本纪》所未记的，用在这里便显得新鲜，而且很有助于论证本篇的中心论点。这正是一石二鸟恰到好处。同时作者又通过恰当剪裁来突出这个事例。全文想说明“忧劳可以兴国，逸豫可以亡身”，写得比较详细的只是这个“晋王三矢”的故事，加上兴亡两种不同结果，此外并没有写李存勖如何“忧劳”，又如何“逸豫”。然而读者对他从“忧劳”发展到“逸豫”却已留下了很深的印象。这就叫做“存大而略小，举重以明轻”，表现了相当高的写作艺术。\n\n　　第二，叙事议论的波澜。\n\n　　《新五代史·伶官传序》篇幅不长，但由于叙事议论配合恰当，行文中又注意了轻重缓急节奏的变化，所以整个文章显得波澜起伏，很有厚度。例如“晋王三矢”故事叙述相当充分，笔势则比较平缓；等到摆完这个生动事例之后，便立即用繁弦促节把文章推向高潮：“方其系燕父子以组，函梁君臣之首，入于太庙，还矢先王，而告以成功，其意气之盛，可谓壮哉！及仇雠已灭，天下已定，一夫夜呼，乱者四应，仓皇东出，未及见贼而士卒离散，君臣相顾，不知所归，至于誓天断发，泣下沾襟，何其衰也！”这两个长句，一扬一抑，大起大落。前者好像驾机起飞，直指长空；后者又似高山坠石，一落千丈，这就形成了全文中一个很有声势的大波。再则两个长句分别用“可谓壮哉”“何其衰也”两个分句感叹作结，也是又唱又叹，遥遥相对，使人感到笔墨酣畅，痛快淋漓。大波过去以后，下文还有小波与之呼应配合，这就是“故方其盛也”至“为天下笑”各句。这样便显得笔有余力，文不单薄。本文的中心论点在于宣扬“忧劳兴国”“逸豫亡身”的道理，因此对李存勖的扬和抑的对比度越大，便越能证明作者所要宣扬的道理。所以文章中出现的波澜正是为表现中心论点服务的。\n\n　　第三，语言的锤炼。\n\n　　锤炼语言不是为了卖弄词藻，而是为了准确而充分地表现主题。《新五代史·伶官传序》为了突出“忧劳”和“逸豫”的对比，很注意使用对称的词句。例如“人事”和“天命”、“盛”和“衰”、“得”和“失”、“难”和“易”、“成”和“败”、“兴”和“亡”等等，这些对称的词，散见于全篇。再从句子上看，本文更有骈散结合的特点。欧阳修是著名的古文家，原则上是反对骈文的；但他没有陷入形而上学，而是很善于运骈入散、以散破骈，使句式多彩而富有表现力。本文在这一点上尤其突出，凡是叙事议论吃紧之处，作者都着意锤炼了四六成文的对偶句，例如“虽曰天命，岂非人事”，“系燕父子以组，函梁君臣之首”，“一夫夜呼，乱者四应”，“忧劳可以兴国，逸豫可以亡身”，“祸患常积于忽微，而智勇多困于所溺”等等，这些句子都是经过锤炼的，很有助于造成鲜明的对比感。另外本文还比较多用转折句、疑问句和感叹句。前人说欧阳修的说理文“一唱三叹”，富有感情色彩，看来这和用语上的“三多”也不无关系。因为转折句使语气委婉，疑问句给读者留下思索和回答的空隙，这两种句子用得好都可以增加文章的情致；至于感叹句更是直接地表露着感情。当然本文之富于感情色彩，根本上是由于作者对北宋封建统治者满怀忠厚恻怛之情，这是应加识别的。但作为写作经验来看，欧阳修能够把说理文写得颇有情味，这还是值得研究的。', poem_tags = '高中文言文,史论,序文' WHERE poem_title = '伶官传序' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '道不专反复无常啊，为何使老百姓在动乱中遭殃？人民妻离子散、家破人亡啊，正当仲春二月迁往东方。\n\n　　离别家乡到远处去啊，沿着长江、夏水到处流亡。走出都门我悲痛难舍啊，我们在甲日的早上开始上道。离开旧居，从郢都出发，前途渺茫，我罔然不知何往。桨儿齐摇船儿却徘徊不前啊，可怜我再也不能见到君王。望见故国高大的楸树，我不禁长叹啊，泪落纷纷象雪粒一样。经过夏水的发源处又向西浮行啊，回头看郢都东门却不能见其模样。心绪缠绵牵挂不舍而又无限忧伤啊，渺渺茫茫不知落脚在何方。顺着风波随着江流漂泊吧，于是乎飘流失所客居他乡。船儿行驶在滚滚的波浪之上啊，就象鸟儿飞翔却不知停泊在哪个地方。心中郁结苦闷而无法解脱啊，愁肠百结心情难以舒畅。\n\n　　将行船向下顺流而去啊，过了洞庭湖又进入长江。离开自古以来的住所啊，如今漂泊来到东方。\n\n　　我的灵魂时时都想着归去啊，哪会片刻忘记返回故乡？背向夏水边而思念郢都啊，故都日渐遥远真叫人悲伤！登上大堤而举目远望啊，姑且以此来舒展一下我忧愁的衷肠。可叹楚地的土地宽平广博、人民富裕安乐啊，江汉盆地还保持着传统的楚国风尚。\n\n　　面对着凌阳不知到何处去啊？大水茫茫也不知道南渡到何方？连大厦荒废成丘墟都不曾想到啊，又怎么可以再度让郢都东门荒芜？心中久久不悦啊，忧愁还添惆怅。郢都的路途是那样遥远啊，长江和夏水有舟难航。时光飞逝的使人难以相信啊（另：神志恍惚地仿佛梦中不可信啊），不能回郢都至今已有九年时光。悲惨忧郁心情不得舒畅啊，怅然失意满怀悲伤。\n\n　　群小顺承楚王的欢心表面上美好啊，实际上内心虚弱没有坚定操守。有人忠心耿耿愿被进用为国效力啊，却遭到众多嫉妒者的障蔽。唐尧、虞舜具有高尚的品德啊，高远无比可达九天云霄，而那些谗人们却要心怀妒嫉啊，竟然在他们的头上加以“不慈”的污蔑之名。楚王讨厌那些不善言辞的忠贤之臣啊，却喜欢听那些小人表面上的激昂慷慨。小人奔走钻营而日益显进啊，贤臣却越来越被疏远。\n\n　　尾声：放眼四下观望啊，希望什么时候能返回郢都一趟。鸟儿高飞终要返回旧巢啊，狐狸死时头一定向着狐穴所在的方向。确实不是我的罪过却遭放逐啊，日日夜夜我哪里能忘记它我的故乡！ ▲', poem_tags = '叙事,抒情,爱国' WHERE poem_title = '哀郢' AND poem_author = '屈原';
UPDATE edu_poem SET poem_translation = '平山堂的栏杆外是晴朗的天空，远山似有似无，一片迷蒙。\n我在堂前亲手栽种的那棵柳树啊，离别它已经好几年了。\n我这位爱好写文章的太守，下笔就是万言，喝酒一饮千杯。\n年轻人，趁现在赶快行乐吧，你看我一把年纪了，都还不是照样饮酒作乐豪情万丈？', poem_notes = '平山栏槛：平山堂的栏槛。\n手种堂前垂柳：平山堂前，欧阳修曾亲手种下杨柳树。\n别来：分别以来。作者曾离开扬州八年，此次是重游。\n文章太守：作者当年知扬州府时，以文章名冠天下，故自称“文章太守”。\n挥毫万字：作者当年曾在平山堂挥笔赋诗作文多达万字。\n千钟：饮酒千杯。\n直须：应当。\n尊：通“樽”，酒杯。\n衰翁：词人自称。此时作者已年逾五十。', poem_appreciation = '宋仁宗至和元年（1054），与欧阳修过从甚密的刘敞（字原甫）知制诰；嘉祐元年（1056），因避亲出守扬州，欧公便作此词送给他。欧公曾于仁宗庆历八年（1048）知扬州，此词借酬赠友人之机，追忆自己扬州的生活，塑造了一个风流儒雅、豪放达观的“文章太守”形象。词中所写平山堂为欧公任扬州太守时所建。\n\n　　这首词一发端即带来一股突兀的气势，笼罩全篇。“平山栏槛倚晴空”，顿然使人感到平山堂凌空矗立，其高无比。这一句写得气势磅礴，便为以下的抒情定下了疏宕豪迈的基调。接下去一句是写凭阑远眺的情景。据宋王象之《舆地纪胜》记载，登上平山堂，“负堂而望，江南诸山，拱列檐下”，则山之体貌，应该是清晰的，但词人却偏偏说是“山色有无中”。这是因为受到王维原来诗句的限制，但从扬州而望江南，青山隐隐，自亦可作“山色有无中”之咏。\n\n　　以下二句，描写更为具体。此刻当送刘原甫出守扬州之际，词人情不自禁地想起平山堂，想起堂前的杨柳。“手种堂前垂柳，别来几度春风”，深情又豪放。其中“手种”二字，看似寻常，却是感情深化的基础。词人平山堂前种下杨柳，不到一年，便离开扬州，移任颍州。这几年中，杨柳之枝枝叶叶都牵动着词人的感情。杨柳本是无情物，但中国传统诗词里，却与人们的思绪紧密相连。何况这垂柳又是词人手种的。可贵的是，词人虽然通过垂柳写深婉之情，但婉而不柔，深而能畅。特别是“几度春风”四字，更能给人以欣欣向荣、格调轩昂的感觉。\n\n　　过片三句写所送之人刘原甫，与词题相应。此词云“文章太守，挥毫万字”，不仅表达了词人“心服其博”的感情，而且把刘敞的倚马之才，作了精确的概括。缀以“一饮千钟”一句，则添上一股豪气，栩栩如生地刻画了一个气度豪迈、才华横溢的文章太守的形象。\n\n　　词的结尾二句，先是劝人，又回过笔来写自己。饯别筵前，面对知己，一段人生感慨，不禁冲口而出。无可否认，这两句是抒发了人生易老、必须及时行乐的消极思想。但是由于豪迈之气通篇流贯，词写到这里，并不令人感到低沉，反有一股苍凉郁勃的情绪奔泻而出，涤荡人的心灵。\n\n　　欧词突破了唐、五代以来的男欢女爱的传统题材与极力渲染红香翠软的表现方法，为后来苏轼一派豪放词开了先路。此词的风格，即与苏东坡的清旷词风十分接近。欧阳修政治逆境中达观豪迈、笑对人生的风范，与苏东坡非常相似。', poem_tags = '豪放,写人,抒怀' WHERE poem_title = '朝中措·平山堂' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '没有见到李白已经好久，他佯为狂放真令人悲哀。\n世上那些人都要杀了他，只有我怜惜他是个人才。\n文思教捷下笔成诗千首，飘零无依消愁唯酒一杯。\n匡山那有你读书的旧居，头发花白了就应该归来。', poem_notes = '“李生”句：李生，指李白。杜甫与李白天宝四载（745年）在山东兖州分手后，一直未能见面，至此已有十六年。\n佯（yáng）狂：故作颠狂。李白常佯狂纵酒，来表示对污浊世俗的不满。\n“世人”句：指李白因入永王李璘幕府而获罪，系狱浔阳，不久又流放夜郎。有人认为他有叛逆之罪，该杀。\n怜才：爱才。\n匡山：指四川彰明县（今江油县）境内的大匡山，李白早年曾读书于此。\n“头白”句：李白此时已经61岁。杜甫这时在成都，李白如返回匡山，久别的老友就可以相见了，故云归来。', poem_appreciation = '开头一句，突兀陡起，好像蓄积于内心的感情一下子迸发出来了。“不见”二字置于句首，表达了渴望见到李白的强烈愿望，又把“久”字放到句末，强调思念时间之长。杜甫和李白在兖州分手，已有整整十五年没有见面了。\n\n　　紧接着第二句，诗人便流露出对李白怀才不遇、因而疏狂自放的哀怜和同情。古代一些不满现实的人也往往佯狂避世，象春秋时的接舆。李白即自命“我本楚狂人”（《庐山谣寄卢侍御虚舟》），并常常吟诗纵酒，笑傲公侯，以狂放不羁的态度来抒发欲济世而不得的悲愤心情。一个有着远大抱负的人却不得不“佯狂”，这实在是一个大悲剧。“佯狂”虽能蒙蔽世人，然而杜甫却深深地理解和体谅李白的苦衷。“真可”两字修饰“哀”，生动地传达出诗人无限叹惋和同情的心事。\n\n　　这种感情在颔联中得到进一步展现。这两句用了一个“反对”，产生了强烈对比的艺术效果。“世人”指统治集团中的人，永王李璘一案，李白被牵连，这些人就叫嚷要将“乱臣贼子”李白处以极刑。这里“皆欲杀”和“独怜才”，突出表现了杜甫与“世人”态度的对立。“怜”承上“哀”而来，“怜才”不仅是指文学才能，也包含着对李白政治上蒙冤的同情。杜甫另有《寄李十二白二十韵》一诗，以苏武、黄公比李白，力言他不是叛臣，又用贾谊、孔子之典来写他政治抱负不能实现的悲剧。而这种悲剧也同样存在于杜甫的身上，他因疏救房琯而被逐出朝廷，也是“世人”的不公。“怜才”也是怜己。共同的遭遇使两位挚友的心更加紧密地连在一起了，这就是杜甫深切哀怜的根本原因。\n\n　　颈联宕开一笔，两句诗是对李白一生的绝妙概括，勾勒出一个诗酒飘零的浪漫诗人的形象。杜甫想象李白在飘泊中以酒相伴，酒或许能浇其块垒，慰其忧愁。这一联仍然意在写李白的不幸，更深一层地抒发了怀念挚友的绵绵情思。\n\n　　深情的怀念最后化为热切的呼唤：“匡山读书处，头白好归来。”诗意承上“飘零”而来，杜甫为李白的命运担忧，希望他叶落归根，终老故里，声声呼唤表达了对老友的深长情意。“匡山”，指绵州彰明（在今四川北部）之大匡山，李白少时读书于此，这时杜甫客居成都，因而希望李白回归蜀中正是情理中事。就章法言，开头慨叹“不见”，结尾渴望相见，首尾呼应，全诗浑然一体。\n\n　　这首诗在艺术上的最大特色是直抒胸臆，不假藻饰。律诗往往借景抒情，或情景结合，胡应麟说：“作诗不过情景二端。如五言律体，前起后结，中四句，二言景，二言情，此通例也。”（《诗薮》）杜甫往往打破这种传统写法，“通篇一字不粘带景物，而雄峭沈著，句律天然”（同上）。这首诗就是用的倾诉心曲的写法，不装点景物，感情深厚，同样产生巨大的艺术感染力。采用这种写法必然要吸收口语、散文的成分入诗，首先是剥落华藻，语言质朴自然，如本诗语言看似平常，却写出了对友人的一往情深；其次是通过散文化使精工整饬的律体变得灵活多姿，便于传情达意，如此诗用虚字转折诗意，使对偶不切等。这种律诗改变了传统的妃青俪白、四平八稳的老调，增强了律诗的表现力。', poem_tags = '写人' WHERE poem_title = '不见' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '夕阳越过了西边的山岭，千山万壑忽然昏暗静寂。\n月照松林更觉夜晚清凉，风声泉声共鸣分外清晰。\n山中砍柴人差不多走尽，烟霭中鸟儿刚归巢安息。\n丁大约定今晚来寺住宿，独自抚琴站在山路等你。', poem_notes = '业师：法名业的僧人。一作“来公”。山房：僧人居所。期：一作“待”。\n度：过、落。\n壑：山谷。倏：一下子。\n满清听：满耳都是清脆的响声。\n樵人：砍柴的人。\n烟：炊烟和雾霭。一作“磴”。\n之：此。子：古代对男子的美称。宿来：一作“未来”。\n孤琴：一作“孤宿”，或作“携琴”。', poem_appreciation = '此诗写诗人在山中等候友人到来而友人仍不至时的情景。前六句展示了山寺一带黄昏时美丽的自然景色。诗人先后描绘夕阳西下、群壑昏暝、松际月出、风吹清泉、樵人归尽、烟鸟栖定等生动的意象，渲染环境气氛。随着景致的流动，时间在暗中转换，环境越来越清幽。孟浩然在山水诗中，很善于表现自然景物在时间中的运动变化。山区寻常的景物，一经作者妙笔点染，便构成一幅清丽幽美的图画。\n\n　　这首诗所描绘的自然景物形象，不仅仅准确地表现出山中从薄暮到深夜的时态特征，而且融统着诗人期盼知音的心情。特别是“松月生夜凉，风泉满清听”两句，写诗人见松月而觉夜凉，听见泉而感山幽，细致入微地传达出日暮山间听泉时的全部感受，很有韵味。全篇前六句都是融情入景，到了第七句，才点出“之子期宿来”，然后在第八字再点出一个“候”字。“孤琴候萝径”，以“孤”修饰琴，更添了孤清之感。\n\n　　孤琴的形象，兼有期待知音之意。而用“萝”字修饰“径”，也似有意似无意地反衬诗人的孤独。因为藤萝总是互相攀援、枝蔓交错地群生的。这一句诗，在整幅山居秋夜幽寂清冷的景物背景上，生动地勾勒出了诗人的自我形象，使人如见这位风神散朗的诗人，抱着琴，孤零零地伫立在洒满月色的萝径上，望眼欲穿地期盼友人的到来。诗的收尾非常精彩，使诗人深情期待知音的形象如在读者眼前。\n\n　　扎看起来，前六句是写景，只有结尾两句写候友。其实不然，诗从一开始就在写候友，不过诗人暗藏在景物中，没有露面罢了。前六句看起来是无人之境，实际上是有人之境。“群壑倏已暝”是诗人看到的，“松月生夜凉”是诗人感到的，“风泉满清听”是诗人的感觉，“樵人归欲尽，烟鸟栖初定”也是诗人看到的。透过这些诗句，可想而知诗人候友已经有一段时间了。待读到“孤琴候萝径”，暗藏在景物中的人，与抚琴候友的人迭在一起，形象蓦地活起来，跃然纸上，呼之欲出。\n\n　　全诗色彩不断变幻，景物描写十分清幽，语言含蓄委婉却不失韵味。“松月生夜凉，风泉满清听”两句是此诗名句。', poem_tags = '唐诗三百首,写景' WHERE poem_title = '宿业师山房期丁大不至 / 宿业师山房待丁大不至' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '姑娘和我同乘车，容貌就像花一样。体态轻盈如飞鸟，珍贵佩玉泛光芒。她是美丽姜姑娘，举止娴雅又大方。\n姑娘和我同路行，容貌就像木槿花。体态轻盈像鸟翔，佩玉锵锵悦耳响。美丽姑娘她姓姜，美好声誉人难忘。', poem_notes = '同车：同乘一辆车。一说男子驾车到女家迎娶。\n舜华（huā）：木槿花，即芙蓉花。\n将翱（áo）将翔：形容女子步履轻盈。一说遨游徘徊。翱、翔，飞翔。\n琼琚：指珍美的佩玉。\n孟姜：姜姓长女。《毛传》：“齐之长女。”排行最大的称孟，姜则是齐国的国姓。后世孟姜也作为美女的通称。\n洵（xún）：确实。都：闲雅，美。\n英：花。\n将（qiāng）将：即“锵锵”，玉石相互碰击摩擦发出的声音。\n德音：美好的品德声誉。', poem_appreciation = '这是一首贵族男女的恋歌。诗以男子的语气，赞美了女子容貌的美丽和品德的美好。\n\n　　时当夏秋之际，木槿花盛开，诗中的男女一同出外游览。他们一会儿赶着车子，在乡间道路上飞快地奔驰；一会儿又下车行走，健步如飞。诗中洋溢着欢乐的情绪，明快的节奏。\n\n　　这个女孩姓姜，“孟”是老大的意思，即这个孟姜在家里排行第一，就是姜家的大姑娘。中国有句古话：“情人眼里出西施”，在那男人看来，孟姜真是“细看诸处好”，美不可言。她的面颊像木槿花一样又红又白；她走起路来像鸟儿飞翔一样，十分轻盈；她身上还佩带着珍贵的环佩，行动起来，环佩轻摇，发出悦耳的响声。她不但外貌美丽，而且品德高尚，风度娴雅。总之，诗人以无比的热情，从容颜、行动、穿戴以及内在品质诸方面，描写了这位少女的形象，同《诗经》中写平民的恋爱迥然有别。这也可以说是此诗的主要特色。\n\n　　木槿花朝开暮谢，所以白居易有“槿枝无宿花”的说法，李商隐对之也有“风露凄凄秋景繁，可怜荣落在朝昏”的叹息。这是文人心中的木槿花，带着伤逝的美。所谓“舜华”，是描述这花朝开暮谢的瞬息之美。有人认为，诗中描述的这两情相悦的欣喜在“舜华”这一美丽的词汇中蕴含了危机。\n\n　　此诗二章，自宋范处义《诗补传》以下皆以之为赋体。也就是说它是用叙事或铺陈的方法进行描写的，但作者在叙写时是饱含感情的。两章字数、句数完全相等，意思也大致一样，唯有所押的韵不同。第一章“舜华”之“华”，朱熹《诗集传》谓“叶芳无反”，用反切的方法说明这个“华”字音“夫”，因此与以下的“琚”“都”属于一个韵部。《说文通训定声》将“华”字归入“豫部”，与《诗集传》相同，可证。第二章的“行”字，《诗集传》注云：“叶户郎反”，即音杭（háng） ；“英”字“叶於良反”，即音央（yāng），皆与以下的“将”“忘”属于一个韵部。从首章“六鱼”韵到次章“七阳”韵的转换，也反映了诗中情绪的变化，它更为欢快和昂扬了。', poem_tags = '诗经,女子' WHERE poem_title = '国风·郑风·有女同车' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '信陵君杀了晋鄙，救下邯郸，打败了秦兵，使赵国得以幸存。赵孝成王亲自到郊外去迎接他。这时，唐雎对信陵君说：“我听说，事情有不可以知道的，有不可以不知道的；有不可以忘掉的，有不可以不忘掉的。”信陵君说：“这话怎样讲呢？”唐雎回答说：“别人憎恨我，不可以知道；我憎恶别人，是不可以让人知道的；别人有恩德于我，是不可以忘记的；我有恩德于别人，是不可以不忘记的。如今，你杀了晋鄙，救下邯郸，打败秦兵，保存了赵国，这对赵国是大恩德。现在，赵王亲自到郊外迎接你。你很快就会见到赵王了，希望你把救赵王的事忘掉吧!”信陵君说：“无忌我敬遵你的教诲。”', poem_notes = '唐雎：唐雎（jū）,战国时代魏国著名策士。为人有胆有识，忠于使命，不畏强权，敢于斗争并敢于为国献身。有90岁高龄西说强秦使秦不敢加兵的魏国。曾经在魏国灭亡后出使秦国，冒死与秦王抗争，粉碎秦王吞并安陵（魏国属国）的阴谋。\n说：游说之意。\n信陵君杀晋鄙：指信陵君杀了晋鄙，救下邯郸，打败了秦兵，保存了赵国之事。\n破：打败，打垮。\n存：存在，存活。这里是使......幸存。\n憎：憎恨，讨厌，厌烦等不好的方面。\n德：恩惠。这里指别人对自己好的的方面。\n卒然：“卒”通“猝”，突然。\n谨:郑重。\n受教：接受教诲。', poem_appreciation = '鲁迅先生说，《史记》“不拘于史法，不囿于字句，发于情，肆于心而为文”（《汉字学史纲要》）。司马迁对信陵君礼贤下士、急人之难的侠义精神非常钦佩，他在《史记太史公自序》里说：“能以富贵下贫贱，贤能诎于不肖，唯信陵君为能行之。”在本篇中，他连用了一百四十多个“公子”，在公子身上倾注了真挚而又深沉的崇敬爱戴之情，文章中材料的取舍和剪削都从表现感情的需要出发。文章主要写了信陵君一生中的两桩大事，一是救赵，二是存魏，因为这两件事最能表现公子的侠义精神。其他的则一概剪去不提。可是，在文章的开头，作者却兴致勃勃地讲了一个公子与魏王赌棋的故事。说“赌棋”，却又不讲二人棋艺高低、赌注大小、胜负如何，很明显，这些与塑造公子的形象、表现作者的感情关系不大。太史公紧紧抓住不放的是，在“北境传举烽”的危急关头，兄弟二人的神情动作。尽管这个故事总共才一百来字，作者还是剥茧抽丝般地写了魏王的“释”、“恐”、“惊”、“畏”，公子的“止王”、“复博”和从实相告。魏王的胆小无能、心胸狭窄，公子的贤能沉着、襟怀坦白，无不跃然于纸面。\n\n　　全文不枝不蔓。公子一死，文章理应结束，可是，作者却又横添上两节文字。一节写公子死后，秦如何“攻魏”、“拔二十城”、“虏魏王”、“屠大梁”；一节写高祖对公子的敬佩，“常祠公子”，“为公子置守冢五家”。这里形象地告诉人们：公子是魏国的中流砥柱，公子又是光耀后代、万世景仰的\n\n　　一颗明星。根据金圣叹的说法，这首尾两处分别运用了“弄引法”和“獭尾法”。所谓“有一段大文字，不好突然便起，且先作一段小文字在前引之。”“一段大文字后，不好寂然便住，更作余波演漾之。”（《读第五才子书法》）作者所以运用这两种写法，则完全是根据表达感情的需要。开头的一个故事是公子的第一个亮相，寄寓了作者强烈的爱憎，鲜明的褒贬，为全篇定下了感情的基调。最后两节文字，是作者不可遏止的感情潮水的余波，是完成公子形象的最后一笔。', poem_tags = '古文观止,高中文言文,对话,劝谏' WHERE poem_title = '唐雎说信陵君' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '组诗作于清道光十九年己亥（1839年）。这年龚自珍辞官，由北京南返杭州，后又北上接取家属，在南北往返的途中，他看着祖国的大好河山，目睹生活在苦难中的人民，不禁触景生情，思绪万千，即兴写下了一首又一首诗，于是诞生了《己亥杂诗》。', poem_tags = '抒情' WHERE poem_title = '己亥杂诗（三百十五首选四）' AND poem_author = '龚自珍';
UPDATE edu_poem SET poem_translation = '她体态轻盈、语声娇软的形象，我分明又从好梦中见到了。我仿佛听到她在对我说：长夜多寂寞呀，你这薄情郎怎么会知道呢？春天才刚开头，却早已被我的相思情怀染遍了。\n自从分别以后，她捎来书信中所说的种种，还有临别时为我刺绣、缝纫的针线活，都令我思念不已。她来到我的梦中，就像是传奇故事中的倩娘，魂魄离了躯体，暗地里跟随着情郎远行。我西望淮南，在一片洁白明亮的月光下，千山是那么的清冷。想必她的魂魄，也像西斜的月亮，在冥冥之中独自归去。也没有个人照管。', poem_notes = '踏莎行：词牌名。又名《柳长春》《喜朝天》等。双调五十八字，仄韵。又有《转调踏莎行》，双调六十四字或六十六字，仄韵。\n沔（miǎn）东：唐、宋州名，今湖北汉阳（属武汉市），姜夔早岁流寓此地。丁未元日：孝宗淳熙十四年（1187年）元旦。\n燕燕、莺莺：借指伊人。苏轼《张子野八十五岁闻买妾述古令作诗》：“诗人老去莺莺在，公子归来燕燕忙。”\n华胥（xū）：梦境。\n郎行：情郎那边。\n淮南：指合肥。\n冥冥（míng）：自然界的幽暗深远。', poem_appreciation = '这首词一开始即借“莺莺燕燕”字面称意中人，从称呼中流露出一种卿卿我我的缠绵情意。这里还有第二重含义，即比喻其人体态“轻盈”如燕，声音“娇软”如莺。可谓善于化用。这“燕燕轻盈，莺莺娇软”乃是词人梦中所见的情境。《列子》载黄帝曾梦游华青氏之国，故词写好梦云“分明又向华胥见”。夜有所梦，乃是日有所思的缘故。以下又通过梦中情人的自述，体贴对方的相思之情。她含情脉脉道：在这迢迢春夜中，“薄情”人（此为呢称）啊，你又怎能尽知我相思的深重呢？言下大有“换我心，为你心，始知相忆深”的意味。\n\n　　过片写别后睹物思人，旧情难忘。“别后书辞”，是指情人寄来的书信，捡阅犹新；“别时针线”，是指情人为自己所做衣眼，尚著在体。二句虽仅写出物件，而不直接言情，然皆情至之语。紧接着承上片梦见事，进一层写伊人之情。“离魂暗逐郎行远”，“郎行”即“郎边”，当时熟语，说她甚至连魂魄也脱离躯体，追逐词人来到远方。末二句写作者梦醒后深情想象情人魂魄归去的情景：在一片明月光下，淮南千山是如此清冷，她就这样独自归去无人照管。一种借玉怜香之情，一种深切的负疚之感，洋溢于字里行间，感人至深。\n\n　　这首词紧扣感梦之主题，以梦见情人开端，又以情人梦魂归去收尾，意境极浑成。词的后半部分，尤见幽绝奇绝。在构思上借鉴了唐传奇《离魂记》，记中倩娘居然能以出窍之灵魂追逐所爱者远游，着想奇妙。在意境与措语上，则又融合了杜诗《梦李白》“魂来枫林青，魂返关塞黑”、《咏怀古迹》“画图省识春风面，环佩空归月夜魂”句意。妙在自然浑融，不著痕迹。', poem_tags = '宋词三百首,记梦,怀人' WHERE poem_title = '踏莎行·自沔东来丁未元日至金陵江上感梦而作' AND poem_author = '姜夔';
UPDATE edu_poem SET poem_translation = '林叶转红，黄菊开遍，又是晚秋时节，我不禁想念起千里之外的游子来了。天边的云彩不断向远处飘去，归来的大雁也没有捎来他的消息，不知道游子的去处，能往何处寄书呢？我越失望越思念，伤心得临窗挥泪，泪流不止，滴到砚台上，就用它研墨写信吧。点点滴滴，一直写到离别后，情到深处，泪水更是一发不可收，滴到信笺上，竟然把红笺的颜色给染褪了。', poem_notes = '思远人：晏几道创调。词中有“千思念行客”句，取其意为调名，选自《小山词》。 \n红叶：枫叶。黄花：菊花。\n千里念行客：思念千里之外的行客。\n就砚旋研墨：眼泪滴到砚中，就用它来研墨。\n别来：别后。\n红笺：女子写情书的信纸，是红色的。', poem_appreciation = '《思远人·红叶黄花秋意晚》就“寄书”二字发挥，写以泪研墨，泪滴红笺，情愈悲而泪愈多，竟至笺上的红字褪尽。用夸张的手法表情达意，写出感情发展的历程，是此词艺术上的突出特点。\n\n　　起首两句，写女主人公因悲秋而怀远，既点明时令、环境，又点染烘托主题。一“晚”字，暗示别离之久，“千里”，点明相隔之远。两句交代了时间和空间，给下文留了铺展的余地。“飞云过尽，归鸿无信”两句是客；“何处寄书得”一句是主。鸿雁，随着天际的浮云，自北向南飞去。闺中人遥望渺渺长空，盼望归鸿带来游子的音信。“过尽”，已极写其失望之意了，由于“无信”，便不知游子而今所在，自己纵欲寄书也无从寄与。\n\n　　过片词意陡转：弹洒不尽的那两行珠泪，还当窗滴下来，并滴进了砚台中，就用它来研磨香墨。下片出人意表，另开思路。正因无处寄书，更增悲感而弹泪，泪弹不尽，而临窗滴下，有砚承泪，遂以研墨作书。故而虽为转折，却也顺理成章了。明知书不得寄，仍是要写，一片痴情，惘惘不甘，用意尤其深厚。语本孟郊《归信吟》“泪墨洒为书”一句，而情真意足，写出小儿女的情态，巧而不纤，较诸“和泪濡墨”的套语自有深浅真伪之别。“渐写到别来，此情深处，红笺为无色。”收语写闺人此时作书，纯是自我遣怀，她把自己全部的内心本质力量投进其中，感情也升华到物我两忘的境界。对此，陈匪石《宋词举》有一段极为透辟的分析：“‘渐’字极宛转，却激切。‘写到别来、此情深处’，墨中纸上，情与泪粘合为一，不辨何者为泪，何者为情。故不谓笺色之红因泪而淡，却谓红笺之色因情深而无。”无论是泪、墨、红笺，都融进闺人的深情之中，物与情已浑然一体。这首词与小晏惯常的“情溢词外，未能意蕴其中”这一风格不同。全词用笔甚曲，下字甚丽，宛转入微，味深意厚，堪称小晏词中别出机杼的异调。', poem_tags = '宋词精选,悲秋,怀远' WHERE poem_title = '思远人·红叶黄花秋意晚' AND poem_author = '晏几道';
UPDATE edu_poem SET poem_translation = '最新裁出的齐地上好丝绢，犹如霜雪一般洁白。\n用它缝制出一把合欢团扇，像轮浑圆浑圆的明月。\n随你出入，伴你身侧，摇动起来微风徐徐拂面。\n团扇呵，常常担心秋来的季节，那时凉风会代替夏天的炎热。\n用不着的团扇将被抛弃，扔进竹箱，往日的恩情也就半路断绝。', poem_notes = '怨歌行：属乐府《相和歌·楚调曲》。\n新裂：指刚从织机上扯下来。裂，截断。齐纨（wán）素：齐地（今山东省泰山以北及胶东半岛地区）出产的精细丝绢。纨素都是细绢，纨比素更精致。汉政府在齐设三服官，是生产纺织品的大型作坊，产品最为著名。素，生绢。\n皎洁：一作“鲜洁”，洁白无瑕。\n合欢扇：绘有或绣有合欢图案的团扇。合欢图案象征和合欢乐。\n团团：圆圆的样子。\n君：指意中人。怀袖：胸口和袖口，犹言身边，这里是说随身携带合欢扇。\n动摇：摇动。\n秋节：秋季。节，节令。\n凉飙（biāo）：凉风。飙，疾风。\n捐：抛弃。箧（qiè）笥（sì）：盛物的竹箱。\n恩情：恩爱之情。中道绝：中途断绝。', poem_appreciation = '该诗又题为《团扇诗》《纨扇诗》《怨诗》，是一首著名的宫怨诗。\n\n　　该诗通首比体，借秋扇见捐喻嫔妃受帝王玩弄终遭遗弃的不幸命运。前六句是第一层意思。起首二句写纨扇素质之美；从织机上新裁（裂）下来的一块齐国出产的精美丝绢，像霜雪一般鲜明皎洁。纨和素，皆精美柔细的丝绢，本来就皎洁无瑕，更加是“新”织成，又是以盛产丝绢著称的齐国的名产，当然就更加精美绝伦，“鲜洁如霜雪”了。二句喻中套喻，暗示了少女出身名门，品质纯美，志节高尚；也是写其内在本质之美。三四句写纨扇制作之工：把这块名贵精美的丝绢裁制成绘有合欢图案的双面团扇，那团团的形状和皎洁的色泽，仿佛天上一轮团圆的月亮。此二句则写其经过精工制作，更具有外表的容态之美。“合欢”，是一种对称的图案花纹，象征男女和合欢乐之意，如《古诗》中“文彩双鸳鸯，裁为合欢被”，《羽林郎》中“广袖合欢襦”，皆属此类。故这里的“合欢”，不仅突出了团扇的精致美观，以喻女子的外貌出众，而且也寄托了少女对于美好爱情的向往；“明月”不仅比喻女子的光彩照人，同时也象征着她对永远团圆的热望。“出入”二句，因古人衣服宽大，故扇子可置于怀袖之中；天气炎热时则取出摇动，顿生微风，使人爽快。李善注云：“此谓蒙恩幸之时也。”但这话只说对了一半，其实，这两句更深的含义是：嫔妃即使受宠，亦不过是侍候君侧，供其欢娱惬意的玩物而已。\n\n　　后四句为第二层意思：团扇在夏季虽受主人宠爱，然而却为自己恩宠难以持久而常常担心恐惧，因为转瞬间秋季将临，凉风吹走了炎热，也就夺去了主人对自己的爱宠；那时，团扇将被弃置在竹箱里，从前与主人的恩情也就半途断绝了。“秋节”隐含韶华已衰，“凉飙”，象征另有新欢；“炎热”，比爱恋炽热；“箧笥”，喻冷宫幽闭，也都是语义双关。封建帝王充陈后宫的佳丽常是成千上万，皇帝对她们只是以貌取人，满足淫乐，对谁都不可能有专一持久的爱情；所以，即使最受宠幸的嫔妃，最终也难逃色衰爱弛的悲剧命运。嫔妃制度又使后宫必然争宠相妒，互相倾轧，阴谋谗陷，班婕妤不就为赵飞燕所谗而失宠了吗?“常恐”，正说明乐中伏悲，居安思危；这种战战兢兢，如履薄冰，乃是封建嫔妃的普遍心理状态。此诗本是女诗人失宠后之作，而这里说“常恐”、用失宠前语气，更显得她早知此事已属必然之势，正不待夺宠之后，方始恍然醒悟。诗人用语之隐微、怨怒之幽深，千载之下，犹不得不令人惊叹其才情丽感慨其不幸！\n\n　　该诗完全符合这两条美学要求：借扇拟人，巧言宫怨之情；设喻取象，无不物我双关，贴切生动，似人似物，浑然难分。而以秋扇见捐以喻女子似玩物遭弃，尤为新奇而警策，是前无古人的创造。正因为如此，其形象就大于思想，超越了宫怨范围而具有更典型更普遍的意义，即反映了封建社会中妇女被玩弄被遗弃的普遍悲剧命运。这正是本诗最突出的艺术成就所在。在后代诗词中，团扇几乎成为红颜薄命、佳人失时的象征，就是明证。\n\n　　其次，诗中欲抑先扬的反衬手法和绮丽清简的语言也是值得欣赏的。前六句写纨扇之盛，何等光彩旖旎!后四旬写恐扇之衰，何等哀感顽艳!在两相照映之下，女主人公美好的人生价值和这价值的毁灭，又对比何等鲜明!短短十句，却写出盛衰变化的一生，而怨情又写得如此抑扬顿挫，跌宕多姿，蔚为大观。', poem_tags = '咏物,写人,宫怨' WHERE poem_title = '怨歌行' AND poem_author = '班婕妤';
UPDATE edu_poem SET poem_translation = '史，凡是贤明的国家，成功源于勤俭，衰败起于奢华。\n为什么非要琥珀才能作枕头，为什么镶有珍珠才是好坐车？\n想要远行，却没遇见千里马，力单势孤，难以拔动蜀山的猛蛇。\n有几人曾经亲耳听过舜帝的《南风歌》？天长地久，只有在苍梧对着翠绿的华盖哭泣份儿。', poem_appreciation = '李商隐以其高度的历史责任感和艺术上的创新精神，创作了占他全部诗篇七分之一强的史诗，它们扩展了传统咏史诗的涵义，丰富了咏史诗的题材，探索了咏史诗新的手法，将其独特的思想性艺术性臻于和谐统—，在咏史诗的发展史上具有里程碑的意义。他的咏史诗不仅咏古况今，充分反映了他进步的历史观，而且借古讽今，含蓄地表达了他的现实主义倾向。同时还借题寄慨，委婉地抒发了他怀才不遇的苦闷。相对于一般诗人对时政的深沉感慨，李商隐的诗作扩大了咏史诗的表现容量。\n\n　　这首诗的第一句是说，回顾以往的朝代，勤俭能使国家昌盛而奢侈腐败会使国家灭亡，提出了一切政权成败的关键。\n\n　　第二句是两个典故，第一个是琥珀枕，南朝一个皇帝在四处征战的时候得到一个非常名贵的琥珀枕，但他将琥珀枕捣碎了给战士敷。第二个是齐桓公，当年齐桓公和另一个君主相遇，那个君主有很多车，每一俩车都有一颗非常大的珍珠，那个君主为此非常自豪视之为奇珍，但齐桓公说他有人才，那才是他的宝物。这一联是说明人才的重要性。\n\n　　第三句也是两个典故。青海马是指能担当军国大事的人才，蜀山蛇指亡国的祸胎（当年蜀国因为五壮士拔蛇而蜀路开，导致了蜀国灭亡），这两句话其实有种国家灭亡也隐隐有天意的意思。义山其实很矛盾，他虽然知道“历览前贤国与家，成由勤俭败由奢。”，但当时是唐文宗很有雄心壮志的，可惜被家奴所制，抑郁而亡，所以义山也无法解释为何国家会走向衰败，所以他只能将其解释为天意。\n\n　　最后一句的南薰曲是当年舜唱的《南风歌》，一唱而天下太平，几人曾预南薰曲的意思就是没人再听到舜的《南风歌》了，意思便是天下将打乱。苍梧是舜埋葬的地方，翠华是皇帝仪仗中顶上的华盖，最后一句话的意思是，国家如此衰败，不复当年尧舜之风了。\n\n　　这首诗，诗人根据历史兴亡的史实，概括为“历览前贤国与家，成由勤俭破由奢”。这些明确的以古鉴今的态度，包含着深刻的用意，比前人的认识更自觉完整。在兴亡系于何人的问题上，尽管李商隐受时代的局限，还只能将理乱的命脉系于帝王，但在他的诗中，大都是指责他们败乱国家的。因此这种揭露更有进步意义。', poem_tags = '咏史,典故,抒怀' WHERE poem_title = '咏史二首·其二' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '其五\n茫茫大漠沙石洁白如雪，燕山顶上新月如钩。\n什么时候能够给骏马套上镶金的笼头，让它在秋日辽阔的原野尽情驰骋。', poem_notes = '其十\n乌江：一作江东。\n君王：一作吾王。\n其十六\n拳：“卷”下换“毛”。', poem_tags = '抒怀,怀才不遇' WHERE poem_title = '马诗二十三首' AND poem_author = '李贺';
UPDATE edu_poem SET poem_translation = '北风刮来冰样凉，大雪漫天白茫茫。你和我是好朋友，携起手来快逃亡。岂能犹豫慢慢走？事情紧急祸将降。\n北风刮来透骨凉，大雪纷飞漫天扬。你和我是好朋友，携起手来归他邦。岂能犹豫慢慢走？事情紧急快逃亡！\n没有红的不是狐，没有黑的不是乌。你和我是好朋友，携手乘车同离去。岂能犹豫慢慢走？事情紧急快逃出。', poem_notes = '邶（bèi）：中国周代诸侯国名，地在今河南省汤阴县东南。\n其凉：即“凉凉”，形容风寒冷。\n雨（yù）雪：下雪。雨，作动词。其雱（páng）：即“雱雱”，雪盛貌。\n惠而：即惠然，顺从、赞成之意。好我：同我友好。\n其：同“岂”，语气词。虚邪：宽貌。一说徐缓。邪，一本作“徐”。\n既：已经。亟（jí）：急。只且（jū）：作语助。\n喈（jiē）：疾貌。一说寒凉。\n霏：雨雪纷飞。\n同归：一起到较好的他国去。\n莫赤匪狐：没有不红的狐狸。莫，无，没有。匪，非。狐狸比喻坏人。一说古人将狐狸比喻为男性伴侣。\n莫黑匪乌：乌鸦没有不是黑色的。乌鸦比喻坏人。一说古人将乌鸦视为吉祥鸟。', poem_appreciation = '此诗开篇即大肆渲染背景：吹的是凉飕飕的北风，飘的是纷纷扬扬的雪。这既是实时描述，也是国家危乱之象。众人为了逃难，呼朋引伴，携手同行。诗中展现了一幅急惶惶四处奔逃的惨景。\n\n　　全诗共三章，前两章内容基本相同，只改了三个字。把“北风其凉”改为“北风其喈”，意在反覆强调北风的寒凉。而改“雨雪其雱”为“雨雪其霏”，无非是极力渲染雪势的盛大密集。把“携手同行”改为“携手同归”，也是强调逃离的意向。复沓的运用产生了强烈的艺术效果。\n\n　　诗各章末二句相同。“其虚其邪”，虚邪，即舒徐，为叠韵词，加上二“其”字。语气更加宽缓，形象地表现同行者委蛇退让、徘徊不前之状。“既亟只且”，“只且”为语助词，语气较为急促，加强了局势的紧迫感。语言富于变化，而形象更加生动。\n\n　　北风与雨雪，是兴体为主，兼有比体。它不只是逃亡时的恶劣环境的简单描写，还是用来比喻当时的虐政。后面赤狐、黑乌则是以比体为主，兼有兴体。它不仅仅是比喻执政者为恶如一，还可以看作逃亡所见之景。这种比兴手法的运用，使诗句意蕴丰富，耐人玩味。\n\n　　朱熹《诗集传》说此诗“气象愁惨”，指出了其基本风格。诗三章展示了这样的逃亡情景：在风紧雪盛的时节，一群贵族相呼同伴乘车去逃亡。局势的紧急（“既亟只且”），环境的凄凉（赤狐狂奔，黑乌乱飞）跃然纸上。', poem_tags = '诗经,写风' WHERE poem_title = '北风' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '太尉执事：苏辙生性喜好写文章，对此想得很深。我认为文章是气的外在体现，然而文章不是单靠学习就能写好的，气却可以通过培养而得到。孟子说：“我善于培养我的浩然之气。”现在看他的文章，宽大厚重宏伟博大，充塞于天地之间，同他气的大小相衬。司马迁走遍天下，广览四海名山大川，与燕、赵之间的英豪俊杰交友，所以他的文章疏放不羁，颇有奇伟之气。这两个人，难道曾经执笔学写这种文章吗？这是因为他们的气充满在内心而溢露到外貌，发于言语而表现为文章，自己却并没有觉察到。\n　　苏辙出生已经十九年了。我住在家里时，所交往的，不过是邻居同乡这一类人。所看到的，不过是几百里之内的景物，没有高山旷野可以登临观览以开阔自己的心胸。诸子百家的书，虽然无所不读，但是都是古人过去的东西，不能激发自己的志气。我担心就此而被埋没，所以断然离开家乡，去寻求天下的奇闻壮观，以便了解天地的广大。我经过秦朝、汉朝的故都，尽情观览终南山、嵩山、华山的高峻，向北眺望黄河奔腾的急流，深有感慨地想起了古代的英雄豪杰。到了京城，抬头看到天子宫殿的壮丽，以及粮仓、府库、城池、苑囿的富庶而且巨大，这才知道天下的广阔富丽。见到翰林学士欧阳公，聆听了他宏大雄辩的议论，看到了他秀美奇伟的容貌，同他的学生贤士大夫交游，这才知道天下的文章都汇聚在这里。太尉以雄才大略称冠天下，全国人依靠您而无忧无虑，四方异族国家惧怕您而不敢侵犯，在朝廷之内像周公、召公一样辅君有方，领兵出征像方叔、召虎一样御敌立功。可是我至今还未见到您呢。\n　　况且一个人的学习，如果不是有志于大的方面，即使学了很多又有什么用呢？苏辙这次来，对于山，看到了终南山、嵩山、华山的高峻；对于水，看到了黄河的深广；对于人，看到了欧阳公；可是仍以没有谒见您而为一件憾事。所以希望能够一睹贤人的风采，就是听到您的一句话也足以激发自己雄心壮志，这样就算看遍了天下的壮观而不会再有什么遗憾了。\n　　苏辙年纪很轻，还没能够通晓做官的事情。先前来京应试，并不是为了谋取微薄的俸禄，偶然得到了它，也不是自己所喜欢的。然而有幸得到恩赐还乡，等待吏部的选用，使我能够有几年空闲的时间，将用来更好地研习文章，并且学习从政之道。太尉假如认为我还可以教诲而屈尊教导我的话，那我就更感到幸运了。', poem_notes = '执事：侍从。\n文者气之所形。然文不可以学而能，气可以养而致：文章是由气形成的，然而文章不能靠学来达到好，气质却可以靠加强修养得到它。\n养：培养。\n浩然之气：正大刚直的气质。\n宽厚宏博：宽大厚重宏伟博大。\n充：充满。\n称：相称，符合。\n周览：饱览。\n豪俊交游：豪杰来往。\n疏荡：洒脱而不拘束。\n颇：很。\n奇气：奇特的气概。\n岂尝：难道，曾经。\n气充乎其中：精神气质充满在他们的胸中。\n而溢乎其貌：洋溢在他们的外表。\n动乎其言：反映在他们的言辞里。\n而见乎其文：表现在他们的文章中。\n游：交往。\n乡党：乡里。\n自广：扩大自己的视野。\n陈迹：陈旧的东西。\n以：用来。\n其：我。\n治：研习。\n遂汩没：因而埋没。\n决然舍去：毅然离开。\n求：探求。\n奇闻壮观：奇异的事物和宏伟的景象。\n广大：广阔。\n恣观：尽情观赏。\n高：高峻。\n顾：看到。\n奔流：奔腾流泻。\n慨然想见：感慨的想到。\n仰观：瞻仰。\n壮：壮丽。\n仓廪：粮仓。\n苑囿：猎苑。\n富：富丽。\n大：广大。\n巨丽：极其美好。\n宏辩：宏伟善辩。\n秀伟：秀美魁梧。\n聚：聚集。\n以才略冠天下，天下之所恃以无忧：凭借才能谋略天下第一全国人依靠他可以无忧无虑。\n四夷之所惮以不敢发：四方夷人害怕你才不敢作乱。\n而：可是。\n焉：啊。\n不志其大，虽多而何为：没有立下大志，即使学得多又有什么用。\n大：浩大。\n深：深远。\n而犹以为未见太尉也：却还是因为没有见到太尉（感到遗憾）。\n观：看到。\n光耀：风采。\n闻一言以自壮：听到你的一句话来激励自己。\n尽：看尽。\n大观：雄伟景象。\n通习吏事：通晓官吏的业务。\n向：先前。\n斗升之禄：微薄的俸禄。\n赐归待选：朝廷允许回乡等待朝廷的选拔。\n优游：从容闲暇。\n益治：更加研究。\n且学为政：并且学习治理政务。\n苟：如果。\n辱教之：屈尊教导我。\n幸：幸运。', poem_appreciation = '此文是苏辙19岁时写给韩琦的信。选自《栾城集》卷二十二。枢密韩太尉（即韩琦），当时任枢密使（掌管军事大权）。“太尉”，秦、汉时官名，掌兵权。枢密使相当于太尉，所以称韩琦为太尉。 作者写这封信的目的，是希望得到韩琦的接见。一个是刚刚考取进士的青年，一个是掌管全国军权的大官，怎么开口下笔呢?\n\n　　首先是称谓问题。为了表示尊重，不直呼对方，而称“太尉执事”。“执事”，左右的人。这是表示谦谨的说法。\n\n　　正文分为四段。\n\n　　第一段，先从作文当有养气之功谈起，明确提出：“以为文者，气之所形”，文章是“气”的表现。气，指人的修养、气质、精神力量。接着提出总领全文的“养气”说。“气可以养而致”：“气”，可以通过加强修养而得到。在具体阐述“养气”说的时候，作者引古人事例作了说明。一是孟子的“我善养吾浩然之气”。“浩然之气”：即博大刚正之气。作者认为，孟子的文章，内容宽厚宏博，并且充溢在天地之中，正是跟他的“气”的大小相称。这实际上强调的是内在修养问题。二是司马迁。作者认为司马迁遍游天下，知多见广，所以他的文章风格疏放潇洒，跌宕多姿，颇有奇气。这实际上是强调外在阅历问题。最后，作者总结道，孟子、司马迁二人的文章，都不是学出来的，而是因为“气”充满在他们心中。这段论述很周严。\n\n　　第二段，就自身经历进一步对“养气”说展开论述。作者有前后不同的两种学习经历。第一种是交游不广、见闻不博，只学古人陈旧过时的东西。第二种是“求天下奇闻壮观，以知天地之广大”。作者在谈到第二种学习经历时，列举了四个事实：一是经过秦汉故都，尽情观赏；二是眺望黄河，想像着古时的英雄人物；三是到了京城，饱览一切，知道了天地的广阔、美丽；四是谒见了欧阳公，知道天下的好文章都汇集在这里。归纳起来，实际上是游览天下名山大川 ，广交天下的文人学士。而这两样，实际上说的都是外在的阅历，可见，苏辙是更重视外在的阅历的。\n\n　　写信的目的是想要求韩琦接见，文章至此，却还只字未提。\n\n　　第三段：由上文欧阳公，自然引出韩琦。这一段主要是颂扬韩琦。表明欲见之意。“才略冠天下”，才能谋略位居天下第一。“入则周公、召公，出则方叔、召虎”，是说韩琦在内政方面有如周、召二公之贤，在领兵方面就像方叔、召虎那样能干。“不志其大”：志，有志于。这段最后“故愿得观贤人之光耀，闻一言以自壮，然后可以尽天下之大观而无憾者矣”，明确求见之意。\n\n　　第四段，再次自明志气，再次表明求见之意。“益治”：进一步钻研。“且学为政”，并且学习治理政事。“辱教”，屈尊指教。这一段特别申明入京师“非有取于斗升之禄”，可见其志向宏大。\n\n　　最后对此文谈几点意见：\n\n　　1．“养气说”有值得借鉴处。作者在论述“气可以养而致”的时候，特别强调了客观阅历的重要，这实际上是强调了生活体验对一个作家的重要作用。今天看来，这个观点也是正确的。但文中所说“文不可以学而能”的观点，是有片面性的。同“气可以养而致”也相矛盾。郭绍虞在《中国文学批评史》中，对这句话也有微词。他说：“……子由上不能如子瞻之入化境，而下又不敢有作文之意，不欲求工于言语句读以为奇，此所以谓‘文不可以学而能’。”\n\n　　2．写作手法上比较新颖、巧妙。先离开主旨，纵论其他，到了第三段“太尉以才略冠天下”，笔意才收拢来，扣紧题目，读来不但没有离题万里之感，而且仔细体味，前面所述，正是烘托下文。特别是第四段，从另一角度申述非求“斗升之禄”，而以“益治其文”为其志，来进一步说明求见韩琦的原因。这样的文章，在构思上是需要功力的。\n\n　　3．即使从写法上看，也不能说没有作态的意味。信中流露出的当时社会所流行的浮夸阿谀的风气，更是不能效法。', poem_tags = '古文观止,书信' WHERE poem_title = '上枢密韩太尉书' AND poem_author = '苏辙';
UPDATE edu_poem SET poem_translation = '一夜间，春风吹遍了衡阳城，雁儿盘算着路程，准备立刻从楚水边飞回燕山旁。\n不要怪我春天一来就要回去，江南虽好，却是他乡！', poem_notes = '衡阳：今属湖南省，在衡山之南、有山峰势如大雁回旋，名回雁峰。相传北来的大睚到此不再南飞，遇春飞回北方。\n楚水：泛指古代楚地的江湖。战国时，楚国占有湖北、湖南、安徽、四川、江浙的大部地区，这里言楚，即指江南。\n燕山：在河北平原北侧从潮白河谷到山海关，由西向东绵延数百里。这里泛指北方地区。', poem_tags = '抒情,思乡' WHERE poem_title = '春雁' AND poem_author = '王恭';
UPDATE edu_poem SET poem_translation = '楚宣王问群臣，说:“我听说北方诸侯都害怕楚令尹昭奚恤，果真是这样吗？”群臣无人回答。 \n江乙回答说:“老虎寻找各种野兽来吃。找到了一只狐狸，狐狸对老虎说:‘您不敢吃我，上天派我做群兽的领袖，如果您吃掉我，这就违背了上天的命令。您如果不相信我的话，我在前面走，您跟在我的后面，看看群兽见了我，有哪一个敢不逃跑的呢？’老虎信以为真，就和狐狸同行，群兽见了它们，都纷纷逃奔。老虎不明白群兽是害怕自己才逃奔的，却以为是害怕狐狸。\n现在大王的国土方圆五千里，大军百万，却由昭奚恤独揽大权。所以，北方诸侯害怕昭恤，其实是害怕大王的军队，这就像群兽害怕老虎一样啊。”', poem_notes = '荆宣王：楚宣王。\n求 ：寻求，寻找。\n食：吃。\n子：你。\n无敢：不敢。\n天帝：上天。\n使：派遣、命令。\n长（zhǎng）：长官，首领。这里作动词，意为“做……首领”，掌管。\n逆：违抗。\n以......为......：认为......是......。\n不信：不真实，不可靠。\n走：逃跑。\n以为：认为。\n然：认为......正确。\n故：所以。\n畏：害怕。\n皆：都。\n曰：说。\n而：才。\n是：这\n遂：于是，就。', poem_tags = '小学文言文,寓言,故事,哲理' WHERE poem_title = '虎求百兽' AND poem_author = '刘向';
UPDATE edu_poem SET poem_tags = '宋词三百首,宋词精选,写景,惜春,感慨,时光' WHERE poem_title = '清平乐·春晚' AND poem_author = '王安国';
UPDATE edu_poem SET poem_tags = '清明节,游春,写水,西湖' WHERE poem_title = '采桑子·清明上巳西湖好' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '高大城墙上有百尺高的城楼，在绿杨林子外是水中的沙洲。\n年少有为的贾谊徒然地流泪，春日登楼的王粲再度去远游。\n常向往老年自在地归隐江湖，要想在扭转乾坤后逍遥扁舟。\n不知道腐臭的死鼠成了美味，竟对鹓雏的爱好也猜忌不休。', poem_notes = '安定：郡名，即泾州（今甘肃省泾川县北），唐代泾原节度使的治所。\n迢递：此形容楼高而且连续绵延。谢朓《随王鼓吹曲》：“逶迤带绿水，迢递起朱楼。”\n枝外：一作“枝上”。汀洲：汀指水边之地，洲是水中之洲渚。此句写登楼所见。\n贾生：指西汉人贾谊。《史记·贾生传》：“贾生……年少，颇通诸子百家之书。文帝召以为博士……一岁中至太中大夫。”又《汉书·贾谊传》载：贾谊认为“时事可为痛哭者一，可为流涕者二，可为太息者六。“因此”数上书陈政事，多所欲匡建”。但文帝并未采纳他的建议。后来他呕血而亡，年仅33岁。李商隐此时27岁，以贾生自比。\n王粲：东汉末年人，建安七子之一。《三国志·魏书·王粲传》载：王粲年轻时曾流寓荆州，依附刘表，但并不得志。他曾于春日作《登楼赋》，其中有句云：“虽信美而非吾土兮，曾何足以少留？”李商隐此以寄人篱下的王粲自比。\n永忆：时常向往。江湖归白发：年老时归隐。\n欲回天地入扁舟：《史记·货殖列传》：春秋时范蠡辅佐越王勾践灭吴后，乘扁舟归隐五湖。李商隐用此事，说自己总想着年老时归隐江湖，但必须等到把治理国家的事业完成，功成名就之后才行。\n“不知”二句：鹓雏是古代传说中一种像凤凰的鸟。《庄子·秋水》：“惠子相梁，庄子往见之。或谓惠子曰：‘庄子来，欲代子相。’于是惠子恐，搜于国中三日三夜。庄子往见之，曰：‘南方有鸟，其名为鹓雏。……发于南海而飞于北海，非梧桐不止，非练实不食，非醴泉不饮。于是鸱得腐鼠，鹓雏过之，仰而视之曰：吓！今子欲以子之梁国而吓我邪？’”李商隐以庄子和鹓雏自比，说自己有高远的心志，并非汲汲于官位利禄之辈，但谗佞之徒却以小人之心度之。', poem_appreciation = '首二句登楼即景：登上高耸百尺的安定城楼，远处绿杨树边的洲渚尽收眼底。按泾州城东有“美女湫”广袤数里（见《太平广记》），汀洲殆指其地。登最高之楼；望最远之处，高瞻远瞩，气象万千。即景所以生情，以下六句的豪情壮志、无穷感慨都由此生发。\n\n　　三、四句先以两位古人自比。贾谊献策之日，王粲作赋之年，都与作者一般年轻。贾谊上《治安策》，不为汉文帝所采纳，因《治安策》开头有“臣窃惟事势，可为痛哭者一”之语，故谓“虚垂涕”；作者应博学宏词科试而名落孙山，其心境与贾谊上书未售，同样萦纡抑郁。王粲避乱至荆州，依刘表；作者赴泾州，入王茂元幕，都属寄人篱下。用两位古人的古事，比自己当前的处境和心情，取拟于伦，十分贴切。这是第一层。\n\n　　五、六句抒露志趣和抱负。作者的遭遇虽然困顿，可是他的凌云之志，未稍减损。江湖、扁舟乃使用春秋时代范蠡的典故；范蠡佐越王勾践，“既雪会稽之耻”，“乃乘扁舟，浮于江湖”（见《史记·货殖列传》）。意谓，自己早有归隐江湖之志，但等回天撼地之日，旋乾转坤之时，头飘白发，身入扁舟。永忆江湖，即怀淡于名利之心；欲回天地，即抱建立功业之志。两者似相反，实相成。因为如果没有永忆江湖的志趣，便成为争名逐利的禄蠹巧宦，就不会有欲回天地的宏愿。在这里，这个“永”字下得很好，这个字，有力地表达作者毕生的抱负。这两句诗，既洒脱，又遒劲。从诗的表达形式着眼，锤字坚实，结响凝固，工力固颇近社诗；而更为关键的，这两句诗反映了封建社会里才志之士的积极向上思想，既怀着恬淡的心情，又有担当事业的志气，这与杜甫的胸襟怀抱，极为相似，因为王安石也从这两句诗中照到自己的影子，所以击节称赏。这是第二层。\n\n　　七、八句借庄子寓言表示自己敝履功名利禄，正告他人不要妄加猜测。寓言谓：惠施相梁，生怕庄子争夺他的相位，百般防范，惟恐不周。于是庄子去见惠施，坦率地对他说；鵷鶵（传说中与凤凰同类的鸟，庄子自比）非练实不食，非醴泉不饮，从来不会把鸱（鹞鹰，比惠施）的腐鼠（比相位）当美味而希羡！（见《庄子·秋水》）意为，你的位置我一向不屑一顾，你切莫杞人忧天，自相惊扰。这两句诗，既阐明自己没有患得患失的私心杂念，胸次光明磊落，淡泊宁静，为上面“永忆江湖”句提供有力的论证；又表示对世间一切恶浊事物，睥睨蔑视，决不妥协容忍；还尖锐地批判那些捧住权位不放的禄蠹，对他们尽调侃奚落的能事。据近人张采田《玉溪生年谱会笺》，作者应博学宏词试被摈，是由于牛党的打击，诚如是，这时句诗乃是有的放矢的。这是第三层。\n\n　　这首诗，笔力健举：风骨清峻，结构严谨，而语句灵活变化，特别在使用典故方面，非常成功。由于贾谊、王粲的身世遭遇与作者有相似之处，抓住相似的典型事例——贾生垂涕、王粲远游，比拟自己的忧时羁旅之感，若合符券，而使一位奋发有为又遭受压抑的少年志士形象跃然纸上。复次，作者的曲曲心事，本不可能用片言只字表达出来，现在借助庄子寓言，不但足以表露他不汲汲于荣利的猖介品质，又反映他睥睨一切的精神状态，还反击了政敌的恶意中伤，如此用典，既灵活，又确切，既含蓄，又锐利，充分发挥了典故的功能。', poem_tags = '登楼,抱负' WHERE poem_title = '安定城楼' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_tags = '写花,爱情,女子,相遇' WHERE poem_title = '荷花' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '你是嵩山云我是秦川树，长久离居；\n千里迢迢，你寄来一封慰问的书信。\n请别问我这个梁园旧客生活的甘苦；\n我就像茂陵秋雨中多病的司马相如。\n\n注解\n嵩：中岳嵩山，在今河南。\n双鲤：指书信。\n梁园：梁孝王在梁地大兴土木，以睢阳为中心，根据自然景色，修建了一个很大的花园，称东苑，也叫菟园，后人称为梁园。\n茂陵：今陕西兴平县东北，以汉武帝陵墓而得名。', poem_appreciation = '首句“嵩云秦树久离居”中，嵩、秦指自己所在的洛阳和令狐所在的长安。“嵩云秦树”化用杜甫《春日忆李白》的名句：“渭北春天树，江东日暮云。”云、树是分居两地的朋友即目所见之景，也是彼此思念之情的寄托。“嵩云秦树”更能够同时唤起对他们相互思念情景的想象，呈现出一副两位朋友遥望云树、神驰天外的画面。\n\n　　次句“双鲤迢迢一纸书”是说令狐从远方寄书问候自己。双鲤，语出古乐府《饮马长城窟行》：“客从远方来，遗我双鲤鱼。呼童烹鲤鱼，中有尺素书。”\n\n　　这里用作书信的代称。久别远隔，两地思念，正当自己闲居多病、秋雨寂寥之际，忽得故交寄书殷勤问候自己，格外感到友谊的温暖。“迢迢”、“一纸”显出对方情意的深长和自己接读来书时油然而生的亲切感念之情。\n\n　　三、四两句“休问梁园旧宾客，茂陵秋雨病相加。”转写自己目前的境况，对来书作答。据《史记·司马相如列传》，司马相如曾为梁孝王宾客。梁园是梁孝王的宫苑，此喻指楚幕。作者从公元829年（大和三年）到837年（开成二年），曾三居绹父令狐楚幕，得到令狐楚的知遇；公元837年（开成二年）应进士试时又曾得到令狐绹的推荐而登第，此处以“梁园旧宾客”自比。司马相如晚年“尝称病闲居，.既病免，家居茂陵”，作者公元842年（会昌二年）因丁母忧而离秘书省正字之职，几年来一直闲居。这段期间，他用世心切，常感闲居生活的寂寞无聊，心情悒郁，身弱多病，此以闲居病免的司马相如自况。', poem_tags = '唐诗三百首,写景,思念,友情' WHERE poem_title = '寄令狐郎中' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '作客异乡，年关已经临近；边防前线，战争还在进行。\n警报传来，敌人进犯雪岭；军鼓号角，响声振动江城。\n前方将士，日夜流血牺牲；朝廷大员，可有一人请缨？\n国难当头，岂敢吝惜性命；报效无路，空有一片豪情！', poem_notes = '“岁暮”句：这年十二月作者客居梓州。\n雪岭：即西山，在成都西面，因终年积雪得名。\n江城：指梓州城（今四川三台县），梓州滨临涪江。\n请缨：将士自告奋勇请命杀敌，语本《汉书．终军传》：“军自请愿受长缨，必羁南越王而致之阙下。”', poem_appreciation = '这首诗的诗题“岁暮”二字，在直观上有一种“岁云暮矣多北风”的凄凉之感，且二字均仄声，读来更抑郁寡欢，仿佛给全诗定了一种低沉的调子，罩上一层黯淡的色彩。\n\n　　首联“岁暮远为客”，“远”字不是对成都草堂言，而是对河南老家言。诗人流寓西蜀，一直过着寄人篱下的羁旅生活，故有“远为客”之叹。但是西蜀一隅也仍然不平静，所以接下去便说“边隅还用兵”。“还用兵”之“还”字，有仍然之意，言自己虽避地西蜀，暂得一席安身之所，没想到这里仍有战争。另外，“还”字又有又、复意，意谓中原战事未了，川中徐知道叛乱刚平，而吐蕃之侵袭又至，战乱似永无宁日。 “还”字隐含诗人对生活和时局的失望与叹息。于此可见杜甫炼字的功力，极为平常的字，出自杜手，便往往辞警意丰，耐人咀嚼。当时吐蕃的威胁日益严重，当年七月，吐蕃入寇，侵取河陇，十月攻入长安，唐代宗出奔陕州，十二月又攻陷松维保三州（均在四川境），及云山新筑二城，西川节度使高适不能抵御，全川为之震动。\n\n　　颔联“烟尘犯雪岭，鼓角动江城”二句承上“用兵”，具体写吐蕃侵蜀之事。“烟尘”，吐蕃兵马过处尘土蔽天，代指吐蕃军队。“鼓角动江城”写备战情形。“动”字既显出战争的紧迫，形势的严重，又写出吐蕃入侵给社会带来的动荡。这一联相当警策生动，前句写雪岭，后句写江城；前句写吐蕃，后句写唐军；前句是所闻，后句是亲见；一远一近，概括而形象地写出吐蕃来势之猛和在社会上引起的震动。\n\n　　颈联“天地日流血，朝廷谁请缨。”此句既指吐蕃入侵以来的情况，又是对安史之乱以来时局的高度概括。在内忧外患的夹击下，人民天天都在流血，在呻吟，国家处于十分危急之中。“朝廷谁请缨”一句，是杜甫对当时那些贪禄恋位、庸懦无能的文武大臣的讽刺和责问，表现了他深深的失望和愤怒。杜甫和他们不同，他早年就怀有“致君尧舜”的宏愿，当此国家危殆、生民涂炭之际，更激发了他舍身报国的意愿。\n\n　　尾联“济时敢爱死”，为济时活民，岂敢爱惜一己之性命而苟且偷安，杜甫是希望“请缨”的，但是虽有捐躯之志，却无报国之门。自从疏救房培，他被朝廷冷落，流寓西蜀，寄人篱下，连生活尚且经常发生危机，哪有机会和条件过问国事。“寂寞壮心惊”，在客居边隅的寂寞岁月中，壮志一天天消磨，每想及此，诗人便感到愤激，不由得拍案惊起，心如刀割。\n\n　　这首诗，前四句主要陈时事，后四句主要抒怀抱，层次清楚，结构井然，语无虚设，字字中包含着诗人对时局的殷忧和关注，对国家的热爱，对庸懦无能的文武大员的失望和谴责，也抒发了他不被朝廷重用、壮志难酬的苦闷。全诗出语浑朴，感情挚厚；语言精简，音韵律工谐。\n\n　　这首诗的艺术手法也很有特色，如借代修辞手法，颔联中的“烟尘”代边境战争；与后文“鼓角”相应，从视角和听觉两方面突出了战争的紧张，渲染了时局的艰危。而且还运用了用典的修辞手法，如“请缨”，典出《汉书·终军传》，在诗句中暗示朝中无人为国分忧，借以表达诗人杜甫对国事的深深忧虑。又如“对偶”和“双关”手法，诗题“岁暮”表面指的是时序岁末，深层指杜甫已进入人生暮年，还指唐帝国由盛而衰进入风雨飘摇的晚唐。这首诗还运用了虚实结合描写手法，如“边偶还用兵，烟尘犯雪岭”“朝廷谁请缨”是杜甫的想象，是虚写；“鼓角动江城，天地日流血”是眼下情景，是实写。表现手法中有对比，如朝廷之臣无人请缨与江湖之士的杜甫“敢爱死”对比；杜甫高远的心志与报国无门对比。“济时敢爱死，寂寞壮心惊”，自己的言行反差的对比；“鼓角动江城”暗含战争前后对比；诗歌开头“远为客”与结尾“寂寞壮心惊”思想感情对比。', poem_tags = '爱国,战争' WHERE poem_title = '岁暮' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '谷口呼呼刮大风，大风夹带阵阵雨。当年担惊受怕时，唯我帮你分忧虑。如今富裕又安乐，你却弃我掉头去。\n\n谷口呼呼刮大风，大风旋转不停息。当年担惊受怕时，你搂我在怀抱里。如今富裕又安乐，将我抛开全忘记。\n\n谷口呼呼风不停，刮过巍巍高山岭。刮得百草全枯死，刮得树木都凋零。我的好处你全忘。专门记我小毛病。', poem_notes = '习习：大风声。\n维：是。\n将：方，正当。\n与：助。女：同“汝”，你。\n转：反而。\n颓：自上而下的旋风。\n寘：同“置”。\n遗：遗忘。\n崔嵬（wéi）：山高峻的样子。', poem_appreciation = '这首诗的主题，旧说大体相同，《毛诗序》说：“《谷风》，刺幽王也。天下俗薄，朋友道绝焉。”朱熹也认为是朋友相怨之诗，但他没有将伤友道之绝与刺周幽王硬拉到一起。方玉润《诗经原始》认同朱熹的观点，并力驳《毛诗序》“刺幽王”之说穿凿空泛。今人高亨的《诗经今注》、程俊英的《诗经译注》等均取弃妇之诗说。陈子展《诗经直解》虽仍取旧说，但又说：“此诗风格绝类《国风》，盖以合乐入于《小雅》。《邶风·谷风》，弃妇之词。或疑《小雅·谷风》亦为弃妇之词。母题同，内容往往同，此歌谣常例。《后汉·阴皇后纪》，光武诏书云：‘吾微贱之时，娶于阴氏。因将兵征伐，遂各别离。幸得安全，俱脱虎口。……“将恐将惧，维予与女。将安将乐，女转弃予。”风人之戒，可不慎乎！’此可证此诗早在后汉之初，已有人视为弃妇之词矣。”\n\n　　诗中的女主人公被丈夫遗弃，她满腔幽怨地回忆旧日家境贫困时，她辛勤操劳，帮助丈夫克服困难，丈夫对她也体贴疼爱；但后来生活安定富裕了，丈夫就变了心，忘恩负义地将她一脚踢开。因此她唱出这首诗谴责那只可共患难，不能同安乐的负心丈夫。\n\n　　诗歌用风雨起兴，这手法同《邶风·谷风》如出一辙，两首《谷风》诗的主题也完全相同，这大概是在风雨交加的时候最容易触发人们的凄苦之情。被丈夫遗弃的妇女，面对凄风苦雨，更会增添无穷的伤怀愁绪，发出“秋风秋雨愁煞人”的哀叹。\n\n　　此诗语言凄恻而又委婉，只是娓娓地叙述被遗弃前后的事实，不加谴责骂詈的词句，而责备的意思已充分表露，所谓“怨而不怒”，说明主人公是一位性格善良懦弱的劳动妇女。这也反映了几千年以前，妇女就处在被压迫的屈辱境地，没有独立的人格和地位。', poem_tags = '诗经,弃妇' WHERE poem_title = '小雅·谷风' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '我从北门出城去，心中烦闷多忧伤。既受困窘又贫寒，没人知我艰难样。既然这样算了吧，都是老天安排定，我有什么办法想！\n王家差事派给我，衙门公务也增加。我从外面回到家，家人纷纷将我骂。既然这样算了吧，都是老天安排定，我有什么好办法！\n王家差事逼迫我，衙门公务也派齐。我从外面回家里，家人纷纷将我讥。既然这样算了吧，都是老天安排定，我有什么好主意！', poem_notes = '邶（bèi）：中国周代诸侯国名，地在今河南省汤阴县东南。\n殷殷：忧愁深重的样子。\n终：王引之《经义述闻》引王念孙说：“终，犹既也。”窭（jù）：贫寒，艰窘。\n已焉哉：既然这样。\n谓：犹奈也，即奈何不得之意。\n王事：周王的事。适（zhì）：同“擿”，扔，掷。适我，扔给我。\n政事：公家的事。一：都。埤（pí）益：增加。\n徧：同“遍”。讁（zhé）：谴责，责难。\n敦：逼迫。\n遗：交给。\n摧：挫也，讥刺。', poem_appreciation = '这是一首小官吏诉说自己愁苦的诗。从诗的语言看，并没有“忠臣不得其志”或“安于贫仕”之意，旧说未免令人感到迂曲，今人的“怨诉”说则解释较为圆满。诗中的小官吏公事繁重苛细，虽辛勤应付，但生活依然清贫。上司非但不体谅他的艰辛，反而一味给他分派任务，使他不堪重负。辛辛苦苦而位卑禄薄，使他牢骚满腹，家人的责备更使他难堪，他深感仕路崎岖，人情浇薄，所以长吁短叹，痛苦难禁，悲愤之余，只好归之于天，安之若命。\n\n　　此诗经北门开篇，自古以来，北通“背”，朱熹解读第一章开篇为“比”，就预先注明诗的主人公正面临着背时的命运。其实，从府衙北门而出，当然是背对光明而来的，自然是形象暗淡无光，精神萎靡不振。他一副忧心忡忡的样子，低着头走回家。因为无职无权，当然就要受穷了，想体面也体面不起来，其内心之黯然神伤，可想而知。但别人却不知道他的这份艰难，这个别人不只包括他的饱食终日无所用心的上司，还包括靠他糊那点薪俸养活的家人。他也自知没有本事，但又无能为力，只剩下愁眉苦脸、唉声叹气的份了。这个小官吏，甘于清贫，内外交困，穿着寒酸，愧对家人，但又如此任劳任怨，忠于王事，勤于政事，真是具有敬业精神的忠谨之士。\n\n　　这首诗的主人公虽然是一名官吏，但全诗并非无病呻吟，的确体现了《诗经》“饥者歌其食，劳者歌其事”的现实主义精神。对诗中连用“我”字而蕴含的感情色彩。全诗纯用赋法，不假比兴，然而每章末尾“已焉哉，天实为之，谓之何哉”三句重复使用，大大增强了语气，深有一唱三叹之效，牛运震《诗志》认为这些句段与《古诗十九首》中“弃捐勿复道，努力加餐饭”等一样，“皆极悲愤语，勿认作安命旷达”，这是很有见地的。', poem_tags = '诗经' WHERE poem_title = '北门' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '春天的杜鹃叫了，好像在说“不如归去”。你走的时候说是春天就回来，而今春已到，却不见你的踪影。近日才几天面色已显得枯槁瘦弱，憔悴多了。等了整整一个春天，九十个日夜啊，却一点消息也没等到；而旧时檐前燕子早已归来，忙忙碌碌地营巢筑窝干得多欢！', poem_notes = '双调：宫调名。大德歌：曲牌名。\n子规啼，不如归：子规啼声很像人说“不如归”，容易引起离人的乡愁。\n憔悴：疲惫没有精神。\n鱼雁：书信的代称。\n则见双燕斗衔泥：只见一对对燕子争相衔泥筑巢。斗：竞相，争着。', poem_tags = '春天,妇女,相思' WHERE poem_title = '大德歌·春' AND poem_author = '关汉卿';
UPDATE edu_poem SET poem_translation = '注释 皎洁：形容月光明亮。', poem_tags = '婉约,中秋节,月亮' WHERE poem_title = '中秋月·中秋月' AND poem_author = '徐有贞';
UPDATE edu_poem SET poem_translation = '投送边荒经历万死两鬓斑斑，如今活着走出瞿塘峡滟滪关。\n还未到江南先自一笑，站在岳阳楼上对着君山。\n\n满江的风雨独自倚靠栏杆，挽成湘夫人的十二髻鬟。\n可惜我不能面对湖水，只在银山堆里看君山。', poem_notes = '岳阳楼：在湖南岳阳城西门，面临洞庭湖。唐张说谪岳州时所建，宋庆历五年（1045年）滕宗谅重修，范仲淹为撰《岳阳楼记》。君山：洞庭湖中的一座小岛。\n投荒：被流放到荒远边地。唐独孤及《为明州独孤使君祭员郎中文》：“公负谴投荒，予亦左衽异域。”鬓（bìn）毛：鬓发。唐贺知章《回乡偶书》诗：“少小离家老大回，乡音无改鬓毛衰。”斑：花白。\n瞿（qú）塘：瞿塘峡，在今重庆市奉节县东，长江三峡之首。滟（yàn）滪（yù）关：滟滪堆是矗立在瞿塘峡口江中的一块大石头，突兀江心，形势险峻。附近的水流得非常急，是航行很危险的地带。古代民谣有“滟滪大如襆，瞿塘不可触”的话。因其险要，故称之为关。生入瞿塘滟滪关：东汉班超从军西域三十一年，年老思归，有“但愿生入玉门关”的话。此用其语。入：一作“出”。\n江南：这里泛指长江下游南岸，包括作者的故乡分宁在内。\n川：这里指洞庭湖。\n“绾结”句：写风雨凭栏时所见君山。绾（wǎn）结：（将头发）向上束起。一作“绾髻”。湘娥：《楚辞·九歌》中的湘君和湘夫人，相传即帝舜二妃娥皇和女英，君山是她们居住的地方。鬟（huán）：发髻。十二鬟：是说君山丘陵起伏，有如女神各式各样的发髻。\n当：正对着，指在湖面上面对着湖水。\n银山：一作“银盘”。', poem_appreciation = '第一首诗写遇赦归来的欣悦之情。首句写历尽坎坷，九死一生，次句谓不曾想还活着出了瞿塘峡和滟滪关，表示劫后重生的喜悦。三四句进一步写放逐归来的欣幸心情：还没有到江南的家乡就已欣然一笑，在这岳阳楼上欣赏壮阔景观，等回到了家乡，还不知该是如何的欣慰。此诗意兴洒脱，诗人乐观豪爽之情可以想见，映照出诗人不畏磨难、豁达洒脱的情怀。全诗用语精当，感情表述真切。\n\n　　诗以望君山一个动作，让读者自己去猜测揣摸，去体会。这样的结尾，与王维《酬张少府》结句“君问穷通理，渔歌入浦深”及杜甫《缚鸡行》结句“鸡虫得失无了时，注目寒江倚山阁”相同，都是不写之写，有有余不尽之意。\n\n　　第二首诗写凭栏远眺洞庭湖时的感受。“满川风雨”，隐指作者所处的恶劣的政治形势。即使是在这样一个困苦的环境中，他还兴致勃勃地凭栏观赏湖山胜景，足见其胸次之高。次句写凭栏时所得印象，说放眼远望，君山众峰的形状好像湘水女神盘结起的十二个发髻，写出了君山的灵秀之气。三四句推开一步，设想如能在湖风扑面白浪掀天的波心浪峰上，细细观赏君山，当是非常惬意。“银山堆里看青山”，以简洁的笔墨，写出了极为壮丽景观。诗人忧患余生，却能以如此开阔之胸襟，写出如此意气风发的诗句，千载之下，令人钦佩不已。\n\n　　独上高褛，可以望洞庭湖；楼在岳阳城西门上，和湖还有一段距离，则在风雨中又不能在“银山堆里看青山”，所以只好出之以想象，而将其认作湘峨鬟髻了。刘禹锡《望洞庭》云：“遥望洞庭山水翠，白银盘里一青螺。”雍陶《望君山》云：“应是水仙梳洗罢，一螺青黛镜中心。”可能给黄庭坚以某种启发，给他提供了想象的依据。\n\n　　诗人自绍圣初因修国史被政敌诬陷遭贬，到徽宗即位，政治地位才略有改善。此时从湖北沿江东下，经过岳阳，准备回到故乡去。诗人历经磨难，长途漂泊，旅况萧条，在风雨中独上高楼，所以一方面为自己能够在投荒万死之后平安地通过滟滪天险活着生还而感到庆幸，另一方面回首平生，瞻望前路，又不能不痛定思痛，黯然伤神。因而欣慨交心，凄然一笑。苏轼的《六月二十日夜渡海》中“九死南荒吾不恨，兹游奇绝冠平生”，此老真是胸次浩然，早已将一切忧患置之度外，真像关汉卿在套曲《南吕·一枝花·不伏老》中所说的“我却是蒸不烂、煮不熟、槌不匾、炒不爆，响当当一粒铜豌豆”。黄庭坚与之相比，似乎还未能完全忘怀得失。这种气质上的差异，很准确地表现在作品中。', poem_tags = '古诗三百首,喜悦,登楼,抒情' WHERE poem_title = '雨中登岳阳楼望君山' AND poem_author = '黄庭坚';
UPDATE edu_poem SET poem_translation = '大地如此广阔，你我都是胸怀大志的英雄豪杰，现在虽然如同蛟龙被困禁在池中，但是蛟龙终当脱离小池，飞腾于广阔天地。秋风秋雨煞人，再加上牢房的蟋蟀叫个不停，我心烦意乱愁肠百结，你我像曹操、槊题诗那样的英雄气概，王粲登楼作岍那样的名士风流，都成了空中花一般的往事，眼前长江滚滚，后浪推前浪，将来肯定还有英雄豪杰起来完成未竞的事业。\n\n现在，你我在落叶随风飘雪，又来到秦淮河畔，正是凉风吹来的那一刻，镜中的你我已两鬓白发，只是我们的英雄之心不会改变。我就要离开故都，放逐到沙漠之地，回望故国的江山一片青色，谦逊我越来越远，去只有一死，希望老朋友以后怀念我的时候，就听听树枝上杜鹃的悲啼吧！那是我的灵魂归来看望我的祖国。', poem_notes = '酹江月：词牌名，即“念奴娇”。友：指邓剡，文天祥的同乡好友。\n寒蛩（qióng）：深秋的蟋蟀。\n横槊题诗：用曹操典故。\n登楼作赋：用王粲典故。\n龙沙：指北方沙漠。《后汉书·班超传赞》：“定远慷慨，专功西遐。坦步葱雪，咫尺龙沙。”李贤注：“葱岭、雪山，白龙堆沙漠也。”\n一线青如发：语出苏轼《澄迈驿通潮阁》诗：“青山一发是中原。”', poem_tags = '豪放,爱国' WHERE poem_title = '酹江月·和友驿中言别' AND poem_author = '文天祥';
UPDATE edu_poem SET poem_translation = '译文及注释 译文 菊花黄黄的开放在那深深的小巷，枫叶红红的映照着低矮的门窗，凄凉一片都是那秋天的声音。豆子开花的时候却来了下雨的声音，那中间还夹带着风声。稀稀疏疏一夜二十五点也就到了五更，高高的谯楼大门，却锁不住那些声音。老朋友离我那么远，请问是哪一个摇晃着玉佩发出了声音，原来是那屋檐底下的风铃声？ 系着彩绸的号角发出的声音一直吹到月亮落下了却还在那里慢腾腾，渐渐地那军营里的人马才接连不断地骚动起来了，可是四周却又扬起了胡笳的声音。邻居的灯光闪烁着，灯前还有那女人为军人在石砧上捣衣的声音。谁知她一边捣衣一边咕咕叨叨地诉说着愁苦一直诉说到天明，碎碎琐琐咕咕哝哝的，就像那数不清的秋蝉哀鸣。她诉说得没完没了，还把一半分给那天空的大雁，让大雁代替她的怨声。 注释 声声慢：词牌名。据传蒋捷作此慢词俱用“声”字入韵，故称此名。亦称胜胜慢、凤示凰、寒松叹、人在楼上，最早见于北宋晁补之笔下。双调，九十七字。前后阕各五仄韵。 豆雨：即豆花雨。 二十五点：指更点。古代用铜壶滴漏计时，一夜分为五更，一更分为五点，所以叫更点。 丽谯门：魏武帝曹操曾筑楼名“丽谯”。谯门：指城上能望远的楼。 彩角：即画角。 笳声：胡笳的声音，其声悲凉。 砧声：砧杆声，即捣衣的声音。砧：捶物时，垫在底下的器具。 ▲', poem_appreciation = '在词中，词人写了一个秋夜中的种种秋声。笔锋非凡，意味亦显独特。词人以“豆雨声”起，以“雁声”收，写了秋夜中听到的十种秋声。但声声总离不了凄凉意，使一个正在发愁的人谛听这些声音，使作为声音的客体，严重地被染上“愁人”的主体印记，因而从笳声、雁声、蛩声、铃声中听到的，都是词人的苦闷心声。\n\n　　“黄花深巷，红叶低窗，凄凉一片秋声。”三句领起全词。点明这是菊花盛开、红叶掩映的深秋时节。凭窗谤听着连绵不断的秋声引起心中阵阵凄凉。“凄凉”是把词中各种声音串联起来的线索。\n\n　　“豆雨声来，中间夹带风声。”“豆花雨”，指阴历八月豆子开花时的雨，这里点出秋雨声杂风声率先而来。风雨凄凉，长夜难眠。风声中又传来了稀疏的更点声。这更声来自城门上的更鼓楼。“疏疏二十五点，丽谯门、不锁更声”。“不锁”，流露了主人公怪罪的意味，因为他是不想听到的。古代把一夜分为五更，一更分为五点。这里直写“二十五点”，意在表明主人公尤感秋夜的漫漫难捱。风不仅送来了更声，又摇响了檐底的风铃。“故人远，问谁摇玉佩，檐底铃声”揭示了主人公听到铃声引起的心理活动，他最初以为这是老友身上玉佩的声。但老友都在远方不可能来，那么这会是谁呢？突然明白原来是风铃的声音。作者这里用笔极为巧妙，看似是误听，实则借写对老友思念之情。\n\n　　“彩角声吹月堕，渐连营马动，四起笳声。”把笔触从深夜转向黎明。月亮沉落，号角声起。军营中人马骚动。蒋捷生活于宋末元初，进士及第不久，南宋被灭。他隐居太湖竹山，一直不肯出来作官。这声音表明，元朝统治了全国，而且军旅遍布这些声音，对于不肯和元统治者合作的词人来说，岂不是比之秋风秋雨的声音更加刺耳惊心吗？\n\n　　“闪烁邻灯，灯前尚有砧声”。灯光闪烁之处，又传来了邻舍在砧石上擣练之声。邻家主妇一夜未眠赶制寒衣，天明未睡。这也不能使词人宽慰。\n\n　　“知他诉愁到晓，碎哝哝、多少蛩声”。“昨夜寒蛩不住鸣，惊四千里梦”岳飞这句词和词人心境相同，皆因满腹心事起。把蛩的叫声称为“诉愁”，借把自己的愁怀转嫁给蛩鸣罢了。“诉未了，把一半、分与雁声。”似乎是蟋蟀把愁苦又分给了横空的过雁。巧妙地又点出大雁叫声的凄凉和它带给主人公的愁意，大雁给人的愁绪往往同引起人对远人的怀念分不开。收尾以雁声，反映了词人独特的构思。', poem_tags = '秋天,声音,抒怀' WHERE poem_title = '声声慢·秋声' AND poem_author = '蒋捷';
UPDATE edu_poem SET poem_appreciation = '此词系作者为思念一个自己曾经深爱过的女子而作，全词写情婉转而含蓄。作者正面写了与女子的初见与重逢，而对于两人关系更为接近后的锦屏前相叙一节却未作正面表现，给读者留下了充分的想象空间。梦中相寻一节也写得很空朦，含蓄地暗示了多量的情感内涵，把心中的哀愁抒写得极为深沉婉曲。\n\n　　上片不过是寥寥五句，可是一句一景，一景一情。景中不仅有人，也有人物的感情透出；而且，通过这情景交融的描写，又暗暗交代了双方的感情由浅丽深，逐步递变。更妙的是，这个女子的音容笑貌，也仿佛可以呼之欲出。\n\n　　“斗草阶前初见，穿针楼上曾逢。”忆叙他与她在两个特定环境中的初次相见和再次相逢。“斗草阶前初见”写有一天女子同别的姑娘阶前斗草的时候，词人第一次看见了她。斗草，据《荆楚岁时记》：“五月五日，四民并踏百草。又有斗百草之戏”。“穿针楼上曾逢”写转眼又到了七夕。女子楼上对着牛郎织女双星穿针，以为乞巧。这种风俗就从汉代一直流传下来。这天晚上，穿针楼上，他又同她相逢了。\n\n　　“罗裙香露玉钗风。靓妆眉沁绿，羞脸粉生红。”这三句，是补叙两次见面时她的情态。她的裙子沾满了花丛中的露水，玉钗头上迎风微颤。她“靓妆眉沁绿，羞脸粉生红”，靓妆才罢，新画的眉间沁出了翠黛，她突然看到了他，粉脸上不禁泛起了娇红。以上既有泛写，又有细腻的刻画，一位天真美丽的女子形象如在眼前。末句一“羞”字，已露情意。\n\n　　下片则陡转话题，抛开往日美好的回忆，陷入眼前苦苦相思的苦闷之中。\n\n　　“流水便随春远，行云终与谁同”用巫山神女的典故，表达了心中的无限惆怅。“流水便随春远”说随着时光的流逝，共同生活结束了，姑娘不知流落何方。“春”也是象征他们的欢聚，可惜不能长久。“行云终与谁同”，用巫山神女“旦为朝云，暮为行雨”（见《高唐赋》）的典故，说她像传说中的神女那样，不知又飘向何处，依附谁人了。\n\n　　“酒醒长恨锦屏空”，人是早已走了，再也不回来了。可是，那情感却一直留了下来。每当夜阑酒醒的时候，总觉得围屏是空荡荡的，他永远也找不回能够填满这空虚的那一段温暖了。正因为她象行云流水，不知去向，所以只好梦里相寻了。“相寻梦里路，飞雨落花中”，春雨飞花中，他独个儿跋山涉水，到处寻找那女子。尽管这是梦里，他仍然希望能够找到她。此处以梦境相寻表现了词人对自己深爱过的女子深沉的爱恋和思念。\n\n　　这首词写怀人。表现作者对往日相逢的美好回忆和如今孤独相思的不堪。全词前后反衬，对比鲜明，形成强烈的情感落差，所以有很强的感染力。', poem_tags = '宋词精选,思念,女子' WHERE poem_title = '临江仙·斗草阶前初见' AND poem_author = '晏几道';
UPDATE edu_poem SET poem_translation = '客人风尘仆仆，从远方送来了一端织有文彩的素缎。\n它从万里之外的夫君处捎来，这丝丝缕缕，该包含着夫君对我的无尽关切和惦念之情！\n绮缎上面织有文彩的鸳鸯双栖，我要将它做条温暖的合欢被。\n床被内须充实以丝绵，被缘边要以丝缕缀。丝绵再长，终究有穷尽之时，缘结不解，终究有松散之日。\n唯有胶和漆，黏合固结，再难分离。那么，就让我与夫君像胶和漆一样投合、固结吧，看谁还能将我们分隔？', poem_notes = '遗：给予、馈赠的意思。一端：即半匹。古人以二丈为一“端”，二端为一“匹”。绮：绫罗一类的丝织品。\n故人：古时习用于朋友，此指久别的“丈夫”。尚：犹也。尔：如此。\n鸳鸯：匹鸟。古诗文中常用以比夫妇。这句是说缔上织有双鸳鸯的图案。\n合欢被：被上绣有合欢的图案。合欢被取“同欢”的意思。\n著：往衣被中填装丝绵叫“著”。绵为“长丝”，“丝”谐音“思”，故云“著以长相思”。\n缘：饰边，镶边。这句是说被的四边缀以丝缕，使连而不解。缘与“姻缘”的“缘”音同，故云“缘以结不解”。\n投：本义为投掷，这里是加入混合的意思。\n别离：分开。', poem_appreciation = '此诗似乎是《孟冬寒气至》的姊妹篇。它以奇妙的思致，抒写了一位思妇的意外喜悦和痴情的浮想。\n\n　　这喜悦是与远方客人的突然造访同时降临的：客人风尘仆仆，送来了“一端”（二丈）织有文彩的素缎（“绮”），并且郑重其事地告诉女主人公，这是她夫君特意从远方托他捎来的。女主人公不禁又惊又喜，喃喃而语曰：“相去万余里，故人心尚尔！”一端文彩之绮，本来也算不得怎样珍贵；但它从“万里”之外的夫君处捎来，便带有了非同寻常的意义：那丝丝缕缕，包含着夫君对她的无限关切和惦念之情。女主人公不能不睹物而惊、随即喜色浮漾。如果将此四句，与前一首诗《古诗十九首·孟冬寒气至》的“客从远方来，遗我一书札”对照着读，人们将会感受到，其中似还含有更深一层意蕴：前诗是诉说着“置书怀袖中，三岁字不灭”的凄苦，一封“书札”而竟怀袖“三岁”，可知这“万里”相隔不仅日久天长，而且绝少有音讯往还。这对家中的妻子来说，是非常痛苦难挨的事。在近乎绝望的等待中，则会有被遗弃的疑惧，时时袭上女主人公心头。而今竟意外地得到夫君的赠绮，那“千思万想而不得一音”的疑惧便烟消云散。那么，伴随女主人公的惊喜而来的，还有那压抑长久的凄苦和哀伤的翻涌。张庚《古诗十九首解》对“故人心尚尔”一句的评价，正体味到了诗行之间所传达的这种悲喜交集之感。\n\n　　适应着这一情感表现特点，此诗开篇也一改《古诗十九首解》常从写景入手的惯例，而采用了突兀而起、直叙其事的方式。恐怕正是为了造成一种绝望中的“意外”之境，便于更强烈地展示女主人色那交织着凄苦、哀伤、惊喜，慰藉的“感切”之情——这就是开篇的妙处。\n\n　　自“文彩双鸳鸯”以下，诗情又有奇妙的变化：当女主人公把绮缎展开一瞧，又意外地发同，上面还织有文彩的鸳鸯双栖之形。鸳鸯双栖，历来是伉俪相偕的美好象征（如《孔雀东南飞》之结尾就是一例）。夫君之特意选择彩织鸳鸯之绮送她，正是倾诉着愿与妻子百年相守的热烈情意。女主人公睹绮思夫，不禁触发起联翩的浮想：倘若将它裁作被面，则可以做条温暖的“合欢被”，再“著以长相思，缘以结不解”，非常地惬人心意。“著”有“充实”之意，“缘”指被之边饰。床被内须充实以丝绵，被缘边要以丝缕缀结，这是制被的常识。但在痴情的女主人公心中，这些平凡的事物，都获得了特殊的含义：“丝绵”使她联想到男女相思的绵长无尽；“缘结”暗示她夫妻之情永结难解。这两句以谐音双关之语，把女主人公浮想中的痴情，传达得既巧妙又动人。制成了“合欢被”，夫君回来就可以和她同享夫妇之乐了。那永不分离的情景，激得女主人公喜气洋洋，不禁又脱口咏出了“以胶投漆中，谁能别离此”的奇句。“丝绵”再长，终究有穷尽之时；“缘结”不解，终究有松散之日。这世上惟有“胶”之与“漆”，粘合固结，再难分离。女主人公说：就让我与夫君像胶、漆一样投合、固结吧，看谁还能将我们分隔！这就是诗之结句所的奇思、奇情。前人称赞此结句“语益浅而情益深”。女主人公的痴情，正有如此深沉和美好。\n\n　　初读起来，《客从远方来》所表现的，就是上述的喜悦和一片痴情。全诗的色彩很明朗；特别是“文彩双鸳鸯”以下，更是奇思、奇语，把诗情推向了如火似锦的境界。但读者应注意到：当女主人公欢喜地念叨着“以胶投漆中，谁能别离此”的时候，她恰恰正陷于与夫君“万里”相隔的“别离”之中。以此反观全诗，则它所描述的一切，其实都不过是女主人公的幻想或虚境罢了。根本不曾有远客之“来”，也不曾有彩“绮”之赠。倘若真能与夫君“合欢”，她就不必要在被中“著”以长相之思、缘以不解之结了。此诗所描述的意外喜悦，实蕴含着夫妇别离的不尽凄楚；痴情的奇思，正伴随着苦苦相思的无声咽泣。钟嵘《诗品》称《古诗十九首》“文温而丽，意悲而远，惊心动魄”。这首诗正以温丽的“遗绮”之喜，抒写了悲远的“别离”之哀，“正笔反用”，就愈加“惊心动魄”。', poem_tags = '古诗三百首,古诗十九首,离别,相思' WHERE poem_title = '客从远方来' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '诗以 “ 忧 ” 贯穿全诗，作者抒发了生活的艰辛；命途的不 顺；生命的衰老。首联通过描写和比喻表现了作者的百忧缠心。颈联从视觉角度与听觉角度。树上集聚的早鸦，是作者所见之景；沉闷的鼓声是作者所闻之景。又这些景物凄冷萧条，传达出作者愁闷落寞的心情。\n\n　　此诗妙就妙在借物抒情 的深厚功底，而且可以体会出诗人壮志未酬身先死的感叹，字里行间流露出一种无可奈何花落去的情伤。诗人借此诗抒怀，表达对时政的不满，以及对自己不能尽力抱负的伤感。', poem_tags = '写景,写雨,抒怀' WHERE poem_title = '长安夜雨' AND poem_author = '薛逢';
UPDATE edu_poem SET poem_translation = '云母屏风后面的美人格外娇，京城寒冬已过却怕短暂春宵。\n无端地嫁了个做高官的丈夫，不恋温暖香衾只想去上早朝。', poem_notes = '云屏：雕饰着云母图案的屏风，古代皇家或富贵人家所用。\n凤城：此指京城。\n无端：没来由。金龟婿：佩带金龟（即作官）的丈夫。', poem_appreciation = '诗歌一、二句“为有云屏无限娇，凤城寒尽怕春宵。”描述一对宦家夫妇的怨情。开头用“为有”二字把怨苦的缘由提示出来。“云屏”，云母屏风，指闺房陈设富丽，“无限娇”称代娇媚无比的少妇。金屋藏娇，两情缱绻，当春风送暖，京城寒尽之时，便双双地怕起春宵来了。丈夫既富且贵，妻子年轻貌美，两人处在云屏环列的闺房之中，更兼暖香暗送，气候宜人，理应有春宵苦短之感，应该不会产生“怕”的心情。首句的“因”和次句的“果”有抵牾之处，这就造成一种悬念引人追询答案。\n\n　　三、四句“无端嫁得金龟婿，辜负香衾事早朝。”通过少妇的口说出“怕春宵”的原因。冬寒已尽，衾枕香暖，两口子情意款洽，本应日晏方起，可是偏偏嫁了你这个身佩金龟的作官夫婿，天不亮就要起身去早朝，害得我一个人孤零零地守在闺房里，实在不是滋味。这些似是枕畔之言，当丈夫正欲起身离去时，妻子对他说了这番话，又好象是埋怨自己，流露出类似“悔教夫婿觅封侯”那样一种痴情；或是责怪丈夫，向他倾诉“孤鹤从来不得眠”的苦衷。“无端”二字活画出这位少妇娇嗔的口吻，表达了她对丈夫、对春宵爱恋的深情。其实，妻子的苦恼也是丈夫的苦恼。\n\n　　前面的“为有”和“凤城”二句就正面描述了丈夫的怨情。应当说他“怕春宵”比妻子有过之而无不及。除了留恋香衾，不愿过早地离去，撇下娇媚多情的妻子，让她忍受春宵独卧的痛苦；还怕听妻子嗔怪的话，她那充满柔情而又浸透泪水的怨言，听了叫人不禁为之心碎。不愿早起离去，又不得不早起离去。对于娇妻，有内疚之意；对于早朝，有怨恨之情；对于爱情生活的受到损害，则有惋惜之感。“辜负”云云，出自妻子之口，同时也表达了丈夫的心意，显得含蓄深婉，耐人寻味。\n\n　　这首诗的中心字眼是第二句里的“怕”，关于怕什么的问题，三、四两句的解答是“无端嫁得金龟婿，辜负香衾事早朝”。仅仅因为丈夫要早起上朝，就产生这么大的怨气，似乎有点不近情理。总之读完全诗，读者由“怕”字造成的悬念并未完全消除，诗有言外之还意，弦外之音。\n\n　　屈复的《玉溪生诗意》分析说：“玉溪以绝世香艳之才，终老幕职，晨入暮出，簿书无暇，与嫁贵婿、负香衾何异？其怨也宜。”李商隐一生长期沉沦幕府，落魄江湖，不是他没有才能，或有才能得不到赏识，而是不幸卷入牛李党争的漩涡之中，成了朋党之争的受害者。当他认识到这一点时，已为时太晚，不可自拔。“无端嫁得金龟婿”所表达的正是这样一种悔恨莫及的痛苦心情。\n\n　　这首绝句含蓄深沉而又富于变幻。前两句一起一承，一因一果，好像比较平直。但着一“怕”字，风波顿起，情趣横生。后面两句围绕着“怕”字作进一步的解说，使意境更加开拓明朗。这样写，前后连贯，浑然一体。其中“为有”“无端”等语委婉尽情，极富感染力。', poem_tags = '唐诗三百首,怨情' WHERE poem_title = '为有' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '注释 玉惨花愁：形容女子愁眉苦脸。 凤城：指北宋都城汴京。 莲花楼：饯饮之处。 阳关曲：古人送别时唱此曲。 人人：那个人，指所爱的人。 程：里程，古人称一站为一程。', poem_appreciation = '这是一首根据在离别时的所感所受而做的词。《青泥莲花记》载：“李之问仪曹解长安幕，诣京师改秩。都下聂胜琼，名倡也，质性慧黠，公见而喜之。李将行，胜琼送别，饯钦于莲花楼，唱一词，末句曰：‘无计留春住，奈何无计随君去。’李复留经月，为细君督归甚切，遂饮别。不旬日，聂作一词以寄李云云，盖寓调《鹧鸪天》也。之问在中路得之，藏于箧间，抵家为其妻所得。因问之，具以实告。妻喜其语句清健，遂出妆奁资夫取归。琼至，即弃冠栉，损其妆饰，委曲以事主母，终身和悦，无少间焉。”这一段记载，叙述了聂胜琼创作这首词的全过程。聂胜琼虽然是京师名妓，见到人非常多，但感情却非常真诚和专一。\n\n　　词的上阕写离别，下阕既写临别之情，又写别后思念之情，实与虚写结合，现实与想象融合为一。起句以送别入题，“玉惨花愁出凤城”，“玉”与“花”喻作者自己，“惨”与“愁”表现送别的愁苦，显示她凄凉的内心世界。凤城指京都，她送别李之问时，情意绵绵，愁思满怀，显示了她不忍分别的真挚情感。莲花楼是送别的地方，楼下青青的柳色，正与离别宴会上回荡的《阳关》曲相应：“渭城朝雨浥轻尘，客舍青青柳色新。劝君更尽一杯酒，西出阳关无故人。”眼前的青青柳色与悲哀的离别之曲一起颤动着离人的心弦。何况“一唱《阳关》后”，心中的人儿马上就要起程了。“别个人人”意谓送别那个人，“人人”指李之问，“第五程”极言路程之远。在唱完一曲《阳关》之后，就一程又一程地远远离开了她。离别是痛苦的，但别后更苦；词的下阕，叙写别后思念的心情。\n\n　　相见时难，别也难，但作者别后希望在梦里依稀可见自己的心上人，更令人悲哀的，是难以成梦。“寻好梦，梦难成”句，写相恋之深，思念之切。词人把客观环境和主观感情相结合，以大自然的夜雨寄托了离人凄苦，“况谁知我此时情”一句，道出了词人在雨夜之中那种强烈的孤独感与痛苦的相思之情。接下去，“枕前泪共帘前雨，隔个窗儿滴到明”两句，画面感人而意境凄静深沉，显示了词人独特的个性，也突现了词的独特的美。“帘前雨”与“枕前泪”相衬，以无情的雨声烘染相思的泪滴，窗内窗外，共同滴到天明。好像大自然也被她的感情所感动，温庭筠《更漏子》一词的下阕，曾这样描写过雨声：“梧桐树，三更下雨，不道离情正苦。一叶叶，一声声，空阶滴到明。”而万俟咏的《长相思·雨》也写到：“一声声，一更更。窗外芭蕉窗里灯，此时无限情。梦难成，恨难平。不道愁人不喜听，空阶滴到明。”跟温庭筠词相类似，都写雨声对内心情感的触动。然相比之下，聂胜琼这首词对夜雨中情景交融的描绘，更显得深刻细腻。它把人的主体活动与雨夜的客体环境紧密结合在一起，以“枕前泪”与“帘前雨”这两幅画面相联相叠，而“隔个窗儿”更见新颖，突出了词人的独特之处，也更深化了离别之苦，因为这里所刻画的“滴到明”，不仅是“帘前雨”，而且也是“枕前泪”。后来李之问的妻子读到这首词时，“喜其语句清健”。她欣赏作者的艺术才华，被作品中的真挚感情所感染，因而作了毅然的决定，“出妆奁资夫取归”，让聂胜琼能遂所愿。\n\n　　宋时的歌妓得以从良成为士人的小妾，已是相当美满的归宿了。能得到这样结果的人并不是很多的。聂胜琼这位“名倡”注重自己的前途。这首词和它的故事，与乐婉同施酒监唱和的《卜算子》词所反映的感情来比较，结局的喜剧和悲剧性质虽然不同，但对于理解当时歌妓的命运和她们的心理，具有同样的价值。', poem_tags = '婉约,离别,相思' WHERE poem_title = '鹧鸪天·别情' AND poem_author = '聂胜琼';
UPDATE edu_poem SET poem_translation = '不知是谁在窗前种下的芭蕉树，一片浓阴，遮盖了整个院落。叶片和不断伸展的叶心相互依恋，一张张，一面面，遮蔽了庭院。\n满怀愁情，无法入睡，偏偏又在三更时分下起了雨，点点滴滴，响个不停。雨声淅沥，不停敲打着我的心扉。我听不惯，于是披衣起床。', poem_notes = '添字丑奴儿：词牌名。一作“添字采桑子”。“丑奴儿”与“采桑子”同调而异名。添字：在此词中具体表现为——在“丑奴儿”原调上下片的第四句各添入二字，由原来的七字句，改组为四字、五字两句。增字后，音节和乐句亦相应发生了变化。\n中庭：庭院里。\n舒卷：一作“舒展”，在此可一词两用，舒，以状蕉叶；卷，以状蕉心。且卷，有通“婘”之训，谓好貌。馀清：此据王学初《李清照集校注》和吴熊和《唐宋词通论》，此首断句亦从吴著。“馀清”，今本多作“馀情”，“情”字在此其意似欠当，因此词上片旨在咏物并非简单的拟人之法。馀清，意谓蕉叶舒卷；蕉心贻人以清凉舒适之感。视“清”字为“情”字的谐音，其意似胜于径用“馀情”二字。\n霖霪：本为久雨，此处指接连不断的雨声。', poem_tags = '咏物,爱国,思乡' WHERE poem_title = '添字丑奴儿·窗前谁种芭蕉树' AND poem_author = '李清照';
UPDATE edu_poem SET poem_tags = '秋天,闺怨' WHERE poem_title = '菩萨蛮·回文秋闺怨' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '漫漫的秋夜多么深长，烈烈的北风吹来正凉。\n躺在床上辗转不能睡，披衣而起徘徊在前堂。\n徘徊不定时光忽已久，白露渐渐浸湿我衣裳。\n俯视池中清水起微波，仰看空中皎皎明月光。\n心星噣星排列呈纵横，银河转而流向正西方。\n草虫的叫声多么可悲，鸿雁孤独地向南飞翔。\n内心闷闷不乐忧愁多，连续不断地思念故乡。\n想要高飞何处得双翅，想要渡河河面无桥梁。\n面对长风而微微叹息，忧思不尽断我腹中肠。\n\n西北天空有一朵浮云，耸立无依形状如车盖。\n可惜浮云没遇好时机，恰巧与突起的暴风遇。\n暴风吹我飘行到东南，南行来到吴郡会稽郡。\n吴会二郡不是我故乡，如何能够在此久停留。\n抛开忧愁不必说其他，客子身居异乡畏人欺。', poem_notes = '烈烈：风吹过之声。\n展转：展同辗，指睡觉时翻来覆去。寐：入睡。\n彷徨：徘徊，犹豫不决，心神不定。\n天汉：指银河。西流：指银河由西南转而向正西流转，表示已是夜深时分。\n三五：指星。三指心星，五指噣星。\n郁郁：苦闷忧伤。\n济：渡。梁：桥。\n中：同“衷”。中肠：谓腹中之肠，喻愁苦之甚。\n浮云：漂浮的云。\n亭亭：耸立而无所依靠的样子。车盖：车蓬。\n时不遇：没遇到好时机。\n适：正值，恰巧。\n行行：走了又走，这里是极言漂泊之远。吴会：指吴郡与会稽郡，今江、浙一带。\n滞：停留。\n弃置勿复陈：此为乐府诗套语。弃置：放在一边。陈：叙说。\n畏人：言客子力单，怕被他人所欺。', poem_tags = '游子,思归,组诗' WHERE poem_title = '杂诗二首' AND poem_author = '曹丕';
UPDATE edu_poem SET poem_translation = '二月蚕未结茧，早成抵债之物；五月谷未成熟，也已忍痛卖出。\n这是挖掉心头好肉，来补眼前烂疮。\n希望帝王之心，化作光明之烛。\n不照豪华筵席，只照灾民空屋。', poem_notes = '粜（tiào）：出卖谷物。\n眼前疮（chuāng）：指眼前的困难，眼前的痛苦。\n剜（wān）却：挖掉，用刀挖除。 心头肉：身体的关键部位，这里喻指赖以生存的劳动果实。\n绮（qǐ）罗：贵重的丝织品。这里指穿绫罗绸缎的人。筵（yán）：宴席。\n逃亡屋：贫苦农民无法生活，逃亡在外留下的空屋。', poem_appreciation = '《咏田家》是聂夷中的代表作，也是晚唐诗歌创作中的艺术佳品。诗中运用形象生动的比喻和鲜明对比的表现手法，愤怒地控诉了形形色色的高利贷给唐末农民所带来的深重苦难，表达了诗人对广大农民的深厚同情。\n\n　　诗的前四句为第一层，主要描写残酷的高利贷剥削给广大农民所带来的剜心割肉般的痛楚。开篇就揭露封建社会农村一种典型“怪”事：“二月卖新丝，五月粜新谷”，写出了农民在青黄不接之时被迫借贷的悲惨境地。二月还未着手养蚕，五月稻子尚处青苗期，然而，贫苦的农民迫于生计，为济燃眉之急，竟不得不以未来的新丝、新谷作抵押，借上“驴打滚”的高利贷。“二”“五”月极言时间之早，这么早就背上阎王债，足以说明农民已到了山穷水尽、骨枯髓干的地步。“卖”“粜”状其只出不入，深刻反映了农民的辛酸血泪和无比痛苦。“医得眼前疮，剜却心头肉”两句，运用比喻的手法，形象地揭示出高利贷吮血噬骨的残酷剥削本质。“眼前疮”固然比喻眼前急难，“心头肉”固然比喻丝谷等农家命根，但这比喻所取得的惊人效果决非“顾得眼前顾不了将来”的概念化表述能及万一。剜却性命攸关的“心头肉”以疗眼前毒疮，是迫不得已，其后果更是不堪想象。旧伤未愈添新伤，穷困伴着死亡行，这就是对当时广大农民濒临绝境的高度概括和生动写照。“挖肉补疮”，自古未闻，但如此写来最能尽情，既深刻又典型，因而成为千古传诵的名句。\n\n　　诗的后四句为第二层，主要是直抒胸臆，尽吐胸中块垒，表达诗人对解决正在激化中的社会矛盾的希望和设想，深寄对“君主”的讥刺之意，表达改良现实的愿望，颇合新乐府倡导者提出的“惟歌生民病，愿得天子知”（白居易《寄唐生》）的精神。诗人把解决矛盾的希望寄托在“君王”身上，这反映出作者存在一定的时代和阶级的局限性，但是，也从另一个侧面深刻地揭露了封建社会最高统治者“君王”所代表的个人利益。“君王”之“烛”只照地主豪绅，权贵达官，而其光不可射及逃亡的农舍，即客观反映其一向只代表豪富的利益而不恤民病，不满之意见于言外，妙在运用反笔揭示皇帝昏聩，世道不公。“绮罗筵”与“逃亡屋”构成鲜明对比，反映出两极分化的尖锐阶级对立的社会现实，增强了批判性。它形象地暗示出农家卖青破产的原因，又由“逃亡”二字点出其结果必然是：“殚其地之出，竭其庐之入，呼号而转徙，饥渴而顿踣”，“非死而徙尔”（柳宗元《捕蛇者说》），充满作者对田家的同情，并含蓄而尖锐地讥刺了“君王”的不恤黎庶，使读者能够透过黑暗的社会现实，思味出那激化社会矛盾的真正罪手。\n\n　　这首诗之所以向为人们所传诵，除了它真实而带有高度概括性地再现了封建社会的黑暗现实、反映了农民的痛苦生活、具有高度的思想性之外，还在于它有高超的表现技巧。\n\n　　首先，形象的比喻，高度的概括，使得诗歌的容量更为广阔。对农民被迫借取高利贷及其更惨痛的后果，诗人并未明白道出，而是用“剜却心头肉”以“医得眼前疮”来比喻之。剜肉补疮，并非根本的疗毒之策，它只会造成更加严重的新局面。这样以剜肉补疮来比喻农民以借高利贷济燃眉之急，是再形象不过了，也是再具有高度概括力不过的了。这个比喻，一方面使诗歌的形象具备了可感性，另一方面也深刻地揭示了问题的本质，使有限的形式容纳了无限广阔深厚的社会内容。\n\n　　其次，鲜明的对比手法的运用，把封建社会中贫富悬殊的阶级差别给历历如绘的描写出来了。“不照绮罗筵，只照逃亡屋”，本是对“君王”的希冀之语，但其中却包含了双重对比的意味。从“君王”的角度来说，恩泽不均，只顾富室，不恤贫苦，这一对比，就把“君王”的阶级立场给鲜明地展示在读者面前；从社会现实的角度来看，一边是权贵豪门华丽的衣着，丰盛的筵宴，一边却是无衣无食，贫困破产，逃亡在外。这一对比，就把地主富室用高利贷剥削农民的严重恶果给突现出来了。如此形象的对比，也把作者鲜明的爱憎之情给烘托得淋漓尽致。\n\n　　此外，这首诗的语言颇质朴通俗，感情也很真诚感人，充分显示了聂夷中驾驭语言、节制感情的功力。胡震亨论唐诗，认为聂夷中等人“洗剥到极净极省，不觉自成一体”，而“夷中诗尤关教化”（《唐音癸签》），从此诗即可看出。其所以如此，与语言的朴素凝炼同取材造境的典型都是分不开的。', poem_tags = '同情,农民' WHERE poem_title = '咏田家 / 伤田家' AND poem_author = '聂夷中';
UPDATE edu_poem SET poem_translation = '葛藤覆盖了一丛丛的黄荆，野葡萄蔓延在荒凉的坟茔。我的亲密爱人长眠在这里，谁和他在一起？独守安宁！\n葛藤覆盖了丛生的酸枣枝，野葡萄蔓延在荒凉的坟地。我的亲密爱人埋葬在这里，谁和他在一起？独自安息！\n他头下的角枕是那样光鲜，身上的锦被多么光华灿烂！我的亲密爱人安眠在这里，谁和他在一起？独枕待旦！\n没有你的日子里夏天煎熬，冬夜是那样漫长难耐孤寒。终有一天我也要化作清风，随你而来相会在碧落黄泉！\n没有你的日子里冬夜漫漫，夏天是那样漫长尤感孤寂。终有一天我也要化为泥土，随你而来相聚在这块宝地！', poem_notes = '葛：藤本植物，茎皮纤维可织葛布，块根可食，花可解酒毒。\n蒙：覆盖。楚：灌木名，即牡荆。\n蔹（liǎn）：攀缘性多年生草本植物，根可入药，有白蔹、赤蔹、乌蔹等。\n予美：我的好人。郑笺：“我所美之人。”朱熹《诗集传》：“妇人指其夫也。”亡此：死于此处，指死后埋在那里。\n棘：酸枣，有棘刺的灌木。\n域：坟地。毛传：“域，营域也。”马瑞辰《毛诗传笺通释》：“营域，或作茔域，古为葬地之称。《说文》：‘茔，墓地也’是也。”\n角枕：牛角做的枕头。据《周礼·王府》注，角枕用于枕尸首。粲：同“灿”。\n锦衾：锦缎褥。闻一多《风诗类钞》：“角枕、锦衾，皆敛死者所用。”烂：灿烂。\n旦：天亮。朱熹《诗集传》：“独旦，独处至旦也。”一说旦释为安，闻一多《风诗类钞》：“旦，坦。”“坦，安也。”\n夏之日、冬之夜：夏之日长，冬之夜长，言时间长也。\n其居：亡夫的墓穴。下文“其室”义同。', poem_appreciation = '全诗五章，每章四句，从结构上看，可分两大部分，前一部分为有“予美亡此”句的三章，后一部分为有“百岁之后”句的两章。对后一部分是用赋法，诸家无异议，但对前一部分，除第三章皆认为是赋外，第一、二两章却有“兴”、“比而赋”、“赋”等三种说法。“葛生蒙楚（棘），蔹蔓于野（域）”两句，互文见义，都既有兴起整章的作用，也有以藤草之生各有托附比喻情侣相亲相爱关系的意思，也有对眼前所见景物的真实描绘，可以说是“兴而比而赋”。这一开篇即出现的兴、比、赋兼而有之的意象，设置了荒凉凄清、冷落萧条的规定情境，显示出一种悲剧美作。接着，“予美亡此，谁与独处”两句，是表达对去世的配偶表示哀悼怀念之情。这里的比兴意义是：野外蔓生的葛藤蔹茎缠绕覆盖着荆树丛，就像爱人那样相依相偎，而诗中主人公却是形单影只，孤独寂寞，好不悲凉。第三章写“至墓则思衾枕鲜华”（郝懿行《诗问》），“角枕、锦衾，殉葬之物也。极惨苦事，忽插极鲜艳语，更难堪”（牛运震《诗志》）。而“谁与独旦”如释“旦”为旦夕之旦，其意义又较“独处”、“独息”有所发展，通宵达旦，辗转难眠，其思念之深，悲哀之重，几乎无以复加。\n\n　　后两章，语句重复尤甚于前三章，仅“居”、“室”两字不同，而这两字意义几乎无别。可它又不是简单的重章叠句，“夏之日，冬之夜”颠倒为“冬之夜，夏之日”，不能解释为作歌词连番咏唱所自然形成，而是作者刻意为之。两章所述，体现了诗中主人公日复一日、年复一年的永无终竭的怀念之情，闪烁着一种追求爱的永恒的光辉。而“百岁之后，归于其居（室）”的感慨叹息，也表现出对荷载着感情重负的生命之旅最终归宿的深刻认识，与所谓“生命的悲剧意识”这样的现代观念似乎也非常合拍。', poem_tags = '诗经,悼亡' WHERE poem_title = '葛生' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '你若爱我想念我，赶快提衣蹚溱河。你若不再想念我，岂无别人来找我？你真是个傻哥哥！\n你若爱我想念我，赶快提衣蹚洧河。你若不再想念我，岂无别的少年哥？你真是个傻哥哥！', poem_notes = '褰（qiān）：提起。裳（cháng）：古代指遮蔽下体的衣裙。\n惠：见爱。\n溱（zhēn）：郑国水名，发源于今河南密县东北。\n不我思：即“不思我”的倒装，不思念我。\n狂童：谑称，犹言“傻小子”。狂，痴。也且（jū）：作语气助词。\n洧（wěi）：郑国水名，发源于今河南登封县东阳城山，即今河南省双泪河。溱、洧二水汇合合于密县。\n士：未娶者之称。', poem_appreciation = '在爱情生活中，有失去情人而悲泣自怜的弱女子，也有泼辣、旷达的奇女子。在以男子为本位的中国古代，虽然二者均避不开命运的摆弄，但后者毕竟表现出了一种独立、自强的意气，足令巾帼神旺。\n\n　　《郑风·褰裳》中的主人公，就正是这样一位奇女子。她与其他女子一样，此刻大抵也正处于热恋之中。因为所恋的心上人，在溱洧之水的对岸，所以也免不了等待相会的焦躁和疑虑。不过她的吐语却爽快：“子惠思我，褰裳涉溱。”——你倘要思念我，就提起衣襟渡溱来！真是快人快语，毫不拖泥带水。较之于《郑风·将仲子》那“无逾我里，无折我树杞”的瞻前顾后，显得非常泼辣和爽朗。\n\n　　但她的心上人，似乎并没有及时来会，便不免引得女主人公有点伤心了。只是伤心中的吐语也毫不示弱：“子不我思，岂无他人？”——你若不想我，我岂没有他人爱！这话说得也真痛快，简直就像是指着对方的鼻子，声称“天下的男人都死光了么，我就只能爱你一个？”那样快利。这态度又是很旷达的，爱情本就是男女相悦、两厢情愿的事，倘若对方不爱，就不必强拉硬扯放不开。所谓“天涯何处无芳草”，正可为“岂无他人”四字作注。较之于《郑风·狡童》中那“彼狡童兮，不与我言兮。维子之故，使我不能餐兮”的呜咽吞声，此诗的女主人公，又显得通达和坚强多了。但倘若以为她就真的不把对方放在心上，恐怕还有几分误解，其实那不过是她所说的气话，而且还带有假设的意味，这从“狂童之狂也且”的戏谑语气，即可推知。须知女主人公心里，实在是很看重这份爱情的，但在外表，却又故意装出不在意的样子，无非是要激得心上人更疼她、爱她而已。所以她刚冷若寒霜，吐出“岂无他人”一句，即又噗哧一笑，戏谑地调侃对方“傻小子呀真傻态”了。可见这位泼辣、爽朗的女主人公，在爱情上既颇认真，也还带着几分狡黠。唯其如此，于自矜、刚强之中，又显得可亲、可爱。\n\n　　全诗只短短二章，用的是富于个性的口语描摹，故涵咏之际，只觉女主人公泼辣、爽朗的音容笑貌，如接于眉睫之间，堪称抒情小诗中的精品。虽说女主人公并未看轻爱情，倘若她真的被心上人抛弃，也未必能做到诗中所说的那样旷达；但这种建立在自信、自强上的爱情观，以及纵遭挫折也不颓丧的意气，却是颇能令溺于情者警醒，而给天下弱女子以鼓舞的。远古的接近自然状态的男欢女爱，同现代建立在个人独立意识基础上的男欢女爱固然有许多不同，但在符合人性的自由选择这一点上，却是没有太大差别的。从这个意义上说，其精神也是现代的。', poem_tags = '诗经,民谣,女子' WHERE poem_title = '国风·郑风·褰裳' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '花光多么绚烂浓郁，绿柳丝丝轻柔鲜明，人们在花前安排酒宴，热情地为我送行。\n我只不过是像平日一样和大家一同相聚畅饮，请不要让管弦奏出令人感伤的离别哀音。', poem_notes = '别滁：告别滁州。\n浓烂：形容鲜花灿烂。轻明：一作“轻盈”。\n且：一作“只”。\n离声：指别离歌曲。', poem_tags = '古诗三百首,离别,叙事,抒情' WHERE poem_title = '别滁' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '自己成仙成佛的道路渺茫，都无法成功，只能在深夜独自作诗，抒发心中的不平。\n飘泊不定的落魄生活，把诗人诗歌中慷概激昂之气消磨而尽。万念俱寂、对女子已经没有轻狂之念的人，却得到负心汉的名声。\n十个人中有九个人是可以用白眼相向的，最没有用处的就是书生。\n不要忧愁自己写的愁苦之诗会成为吉凶的预言，春天的鸟儿和秋天的虫儿都会发出自己的声音。', poem_notes = '风蓬：蓬草随风飘转，比喻人被命运拨弄，踪迹不定。\n泥絮：被泥水沾湿的柳絮，比喻不会再轻狂。\n薄幸：对女子负心。\n谶：将来会应验的话。', poem_appreciation = '首联开门见山，点出本诗基调：无法参禅得道，心中的不平亦不能自抑。一个“只”字仿佛自嘲，实是发泄对这个世界的不平。仙佛茫茫两未成，只知独夜不平鸣。不平鸣，韩愈在《送孟东野序》中说：“大凡物不得其平则鸣。……人之言也也亦然。有不得已者而后言，其歌也有思，其哭也有怀。”自己成仙成佛的道路渺茫，都无法成功，只能在深夜独自作诗，抒发心中的不平。\n\n　　风中飞蓬飘尽悲歌之气，一片禅心却只换得薄幸之名。宋道潜诗有云：“禅心已作沾泥絮，不逐春风上下狂。”如此清妙之音被作者如此化用，倒成了牢骚满腹的出气筒。风蓬飘尽悲歌气，泥絮沾来薄幸名。风蓬，蓬草随风飘转，比喻人被命运拨弄，踪迹不定。泥絮，被泥水沾湿的柳絮，比喻不会再轻狂。薄幸，对女子负心。飘泊不定的落魄生活，把诗人诗歌中慷概激昂之气消磨而尽。万念俱寂、对女子已经没有轻狂之念的人，却得到负心汉的名声。\n\n　　颈联更是狂放愤慨：世上的人十之八九只配让人用白眼去看，好似当年阮籍的做派；“百无一用是书生”更是道出了后来书生的酸涩心事，此句既是自嘲，亦是醒世。\n\n　　尾联说不要因为诗多说愁，成了谶语，春鸟与秋虫一样要作声。不是只能作春鸟欢愉，秋虫愁苦一样是一种自然。此句传承以上愤慨之气，再次将作者心中的不平推至高潮。莫因诗卷愁成谶，春鸟秋虫自作声。\n\n　　黄景仁短暂的一生，大都是在贫病愁苦中度过的。他所作诗歌，除了抒发穷愁不遇、寂寞凄苦的情怀，也常常发出不平的感慨。七言律诗《杂感》就是这样的一首诗。', poem_tags = '杂诗' WHERE poem_title = '杂感' AND poem_author = '黄景仁';
UPDATE edu_poem SET poem_tags = '女子,理想' WHERE poem_title = '念奴娇·天南地北' AND poem_author = '施耐庵';
UPDATE edu_poem SET poem_translation = '我感到人生衰老，早年的情怀、趣味全减，面对着送别酒，怯惧年华流变。何况屈指指计算中秋佳节将至，那一轮美好的圆月，偏不照人的团圆。无情的流水全不管离人的眷恋，与西风推波助澜，只管将归舟送归。祝愿你在这晚秋的江面，能将莼菜羹、鲈鱼脍品尝，回家后怀儿女团取在夜深的灯前。\n趁旅途的征衫未换，正好去朝见天子，而今朝廷正思贤访贤。料想在深夜的承明庐，正留下来教你检视翰林院草拟的文件，还派遣筹划边防军备。说都故友倘若问到我，只说我依然是愁肠满腹借酒浇愁愁难遣。遥望秋天的云霄里一只落雁消逝不见，我沉醉中听到有谁奏响了空弦！', poem_notes = '范倅：即范昂，滁州（今安徽滁县）通判。倅，副职。\n莼：指莼菜羹。\n鲈：指鲈鱼脍。\n儿女：有二义，一指青年男女。一指儿子和女儿。此处当指作者。\n朝天：指朝见天子。\n玉殿：皇宫宝殿。\n夜半承明：汉有承明庐，为朝官值宿之处。源自李商隐《贾生》诗：“宣室求贤访逐臣，贾生才调更无伦。可怜夜半虚前席，不问苍生问鬼神。”\n视草：为皇帝起草制诏。\n筹边：筹划边防军务。\n殢酒：困酒。', poem_appreciation = '稼轩词多是感时抚事之作，并且词情豪放。即或是送别词，也多是慷慨悲吟，此词即是如此。这首词是公元1172年（宋孝宗乾道八年）作者在滁州任上，为送他的同事范倅赴临安而作。范倅，名昂。这次范昂被召回临安，作者对他寄与了殷切的期望，希望他能受到皇帝的重用，并热情地鼓励他到前方去筹划军事，充分发挥他的才能。作者借送别的机会，倾吐自己满腹的忧国深情，在激励友人奋进之时，又宣泄了自己壮志难酬的苦闷，慷慨悲凉之情，磊落不平之气，层见叠出。\n\n　　上阕头三句“老来情味减，对别酒，怯流年。”陡然而起，直抒胸臆，以高屋建瓴之势笼罩全篇。苏轼有“对尊前，惜流年”的词句（《江神子·冬景》），此处便化用了但感觉更深沉悲慨。词人意有所郁结，面对别酒随事触发。本意虽含而未露，探其幽眇，“老来”两字神貌可鉴。词人作此词时正值壮年，何以老迈自居，心情萧索至此呢？词人存其弱冠之年“突骑渡江”，率众南归后，正拟做一番扭转乾坤的事业，不料竟沉沦下僚，辗转宦海。公元1172年（乾道八年）他出任滁州知州，乃是大材小用，况且朝廷苟安，北伐无期，旌旗未展头先白，怎能不“对别酒，怯流年呢？”“况屈指中秋，十分好月，不照人圆。”作者身处政治逆境中，对于寒暑易节，素魄盈亏，特别敏感，双眼看友人高蹈离去，惜别而外，另有衷曲，于是浮想联翩，情思奔涌。“无情水都不管，共西风、只管送归船。”“都不管”和“只管”道尽“水”与“西风”的无情，一语双关。既设想了友人别后归途的情景，又暗喻范氏离任乃朝中局势所致。以西风喻恶势力，在辛词中不乏其例。如“吴楚地，东南坼。英雄事，曹刘敌。被西风吹尽，了无尘迹。”（《满江红》）归船何处去？联想更深一层。“秋晚莼鲈江上，夜深儿女灯前。”笔锋陡转，变刚为柔，一种浑厚超脱的意境悠然展现出来，前句用张翰的故事，后句用黄庭坚的诗意，使人读之翕然而有“归欤”之念。此二句当是悬想范倅离任后入朝前返家的天伦之乐。\n\n　　下阕，转到送别主旨上。“征衫，便好去朝天，玉殿正思贤。”由上阕末句初跌而出，格调转亢，与上面“归欤”之境构成迥然不同的画面。词人有意用积极精神，昂扬语调，为友人入朝壮色。头二句言友人入朝前勤劳忠奋，三句言朝廷求贤若渴。“想夜半承明，留教视草，却遣筹边”，好一派君臣相得，振邦兴国的景象！夜里在承明庐修改诏书，又奉命去筹划边事，极言恩遇之深。承明，庐名，是汉代朝官值宿（犹后代的值班）之地，词里借指宫廷。这几句寄托了词人的理想，表明愿为光复中原竭股肱之力、效忠贞之节，大有“但用东山谢安石，为君谈笑静胡沙”（李白《永王东巡歌》）的气概。下面再一转折，将滔滔思潮訇然闸住。“长安故人问我，道愁肠殢酒只依然”，变奋激昂扬为纡徐低沉。倘若友人去了京城，遇到老朋友，可以告诉他们，自己仍然是借酒销愁，为酒所困。长安，这里代指南宋都城临安。“愁肠殢酒”乃化用唐未韩偓《有忆》诗“肠殢？酒人千里”句，殢是困扰之意。话语外表露出自己报国无门的无限悲愤。\n\n　　前面几经翻跌，蓄意蓄势，至结尾，突然振拔：“目断秋霄落雁，醉来时响空弦”。词人醉中张弓满月，空弦虚射，却惊落了秋雁，真乃奇思妙想。“目断”两字极有神韵，其实是翻用《战国策》“虚弓落病雁”的典故，可是不着痕迹。一个壮怀激烈、无用武之地的英雄形象通过这两句显现出来，他的情怀只能在酒醉后发泄出来。正如清陈廷焯说：“稼轩有吞吐八荒之慨而机会不来，……故词极豪雄而意极悲郁。”（《白雨斋词话》）\n\n　　这首词在艺术手法上的高明之处在于联想与造境上。丰富的联想与跌宕起伏的笔法相结合，使跳跃性的结构显得整齐严密。全词的感情由联想展开。“老来情味减”一句实写，以下笔笔虚写，以虚衬实。由“别酒”想到“西风”，“归船”；由“西风”、“归船”想到“江上”，灯前下边转到朝廷思贤，再转到托愁肠殢酒，最后落到醉中发泄。由此及彼，由近及远；由反而正，感情亦如江上的波涛大起大落，通篇蕴含着开阖顿挫、腾挪跌宕的气势，与词人沉郁雄放的风格相一致。', poem_tags = '送别,抒怀,壮志未酬' WHERE poem_title = '木兰花慢·滁州送范倅' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '门外的东风把春雪吹洒在先生您的衣襟上，当您登上太行山头时一定会回过头来眺望三吴故乡。既然做了学官，就不应计较被派到了那艰苦的地方。\n上党地势险要，历来被人称作天下之脊，先生志向远大，原来就以治理天下为己任。恰逢太平之时也是您不被重用的原因。', poem_notes = '浣溪沙：本唐代教坊曲名，因西施浣纱于若耶溪，故又名《浣溪纱》或《浣沙溪》。上下片三个七字句。四十二字。分平仄两体。平韵体流传至今。最早的是唐人韩偓词，是正体。上片三句全用韵，下片末二句用韵。过片二句用对偶句的居多。仄韵体始于南唐李煜。又有《小庭花》等二十余种异名。另有《摊破浣溪沙》，又名《山花子》，上下片各增三字，韵位不变。此调音节明快，句式整齐，易于上口，为婉约、豪放两派词人所常用。\n梅庭老：作者友人，生平不详，学官，州学教授。从词里可知他是三吴地区（“三吴”，众说不一，大概指今浙东、苏南一带）人。\n上党：一作“潞州”，位于现在的山西长治，北宋时与辽国接近，地属偏远。\n学官：官职名，负责地方文教，职位不显。\n裾：衣的前襟。\n三吴：古地区名，说法不一，大致指今江苏、浙江的苏州、吴兴、绍兴一带。\n弹铗为无鱼：战国齐人冯谖为孟尝君食客，嫌生活清苦，弹剑而歌：“长铗归来乎，食无鱼！”铗，指剑把或剑。\n脊：脊梁。上党其地甚高，古有与天为党之说，故云“天下脊”。\n先生：指梅庭老。\n鲁连书：《史记·鲁仲连列传》：齐军攻打聊城一年多不能下，鲁仲连写书信给守城燕将，燕将见书哭泣三日，犹豫不决而自杀。这句话：如今天下太平用不上鲁仲连这类书信。意劝梅庭老安心去作学官，不要想去立什么奇功。', poem_tags = '送别,抒怀' WHERE poem_title = '浣溪沙·送梅庭老赴上党学官' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '少壮从军马上飞，身未出家心依归。\n年老头陀秋山住，犹忆当年射虎威。', poem_notes = '雪山童子：亦称雪山大士，原本是释迦牟尼在过去世修菩萨道时在雪山苦行时的称谓。该诗用以比喻头陀师未出家时。缁衣：僧人所穿之衣，紫而浅黑，非正黑。\n头陀：梵语Dhata之音译，又作杜荼、杜多，意译有抖擞、抖拣、浣洗等，意为去除衣服、饮食、住处三种贪着之行法。俗则称僧人之行脚乞食者为头陀。此诗取前一意。', poem_tags = '赞美,写人' WHERE poem_title = '赠头陀师' AND poem_author = '刘商';
UPDATE edu_poem SET poem_translation = '益的边塞诗，主要是抒发将士们久戍思归的怨望情绪，情调偏于感伤，但也有一些慷慨激昂之作，《塞下曲》便是这方面较著名的一首。\n\n　　诗以前代戍边名将作比，抒发了将士们的豪情壮志。头二句夸赞东汉两个名将马援和班超。“伏波惟愿裹尸还”，这句说的是马援的故事。东汉马援屡立战功，被封为伏波将军。他曾经说：男儿当战死在边疆，以马革裹尸还葬。“定远何须生入关”，这句说的是班超的故事。东汉班超投笔从戎，平定西域一些少数民族贵族统治者的叛乱，封定远侯，居西域三十一年。后因年老，上书皇帝，请求调回，有“但愿生入玉门关”句。\n\n　　以上两句说：为保家卫国，边塞将士应长期驻守边疆', poem_appreciation = '李益的边塞诗，主要是抒发将士们久戍思归的怨望情绪，情调偏于感伤，但也有一些慷慨激昂之作，《塞下曲》便是这方面较著名的一首。\n\n　　诗以前代戍边名将作比，抒发了将士们的豪情壮志。头二句夸赞东汉两个名将马援和班超。“伏波惟愿裹尸还”，这句说的是马援的故事。东汉马援屡立战功，被封为伏波将军。他曾经说：男儿当战死在边疆，以马革裹尸还葬。“定远何须生入关”，这句说的是班超的故事。东汉班超投笔从戎，平定西域一些少数民族贵族统治者的叛乱，封定远侯，居西域三十一年。后因年老，上书皇帝，请求调回，有“但愿生入玉门关”句。\n\n　　以上两句说：为保家卫国，边塞将士应长期驻守边疆，宁愿战死疆场，无须活着回到玉门关。后二句表示灭敌及长期卫边的决心。\n\n　　“莫遣只轮归海窟”，“只轮”，一只车轮。《春秋公羊传》：“僖公三十三年，夏四月，晋人及姜戎败秦于肴..晋人与羌戎要之肴而击之，匹马只轮无反（返）者。”“海窟”，本指海中动物聚居的洞穴，这里借指当时敌人所居住的瀚海（沙漠）地方。这句意思是说，不能让一个敌人逃跑。\n\n　　“仍留一箭定天山”，“一箭定天山”，说的是唐初薛仁贵西征突厥的故事。《旧唐书·薛仁贵传》说：“唐高宗时，薛仁贵领兵在天山迎击九姓突厥十余万军队，发三矢射杀他们派来挑战的少数部队中的三人，其余都下马请降。薛仁贵率兵乘胜前进，凯旋时，军中歌唱道：“将军三箭定天山，战士长歌入汉关。”\n\n　　以上两句意思是说：“要全歼敌人，不能让一个敌人逃跑，而且应该留驻边疆，叫敌人不敢再来侵犯。”\n\n　　这首诗通过东汉马援、班超和唐初薛仁贵三个名将的故事，讴歌了将士们激昂慷慨、视死如归、坚决消灭来犯之敌的英雄气概和勇于牺牲的精神，反映了当时人民要安边定远的心愿。全诗情调激昂，音节嘹亮，是一首激励人们舍身报国的豪迈诗篇。', poem_tags = '边塞,写人,壮志' WHERE poem_title = '塞下曲' AND poem_author = '李益';
UPDATE edu_poem SET poem_translation = '大雁啊，潇湘下游，水碧沙明，风景秀丽，食物丰美，你为什么随便离开这么好的地方，回到北方来呢？大雁回答：潇湘一带风景秀丽，食物丰美，本来是可以常住下去的。可是，湘灵在月夜鼓瑟，从那二十五弦上弹出的音调，实在太凄清、太哀怨了！我的感情，简直承受不住，只好飞回北方。', poem_notes = '潇湘：二水名，在今湖南境内。等闲：轻易、随便。\n水碧沙明：《太平御览》卷六五引《湘中记》：“湘水至清，……白沙如雪。”苔，鸟类的食物，雁尤喜食。\n二十五弦：指瑟。《楚辞·远游》：“使湘灵鼓瑟兮。”\n胜（音shēng）：承受。', poem_tags = '咏物,写鸟,思乡' WHERE poem_title = '归雁' AND poem_author = '钱起';
UPDATE edu_poem SET poem_translation = '听说从这里去蜀国的道路，崎岖艰险自来就不易通行。\n山崖从人的脸旁突兀而起，云气依傍着马头上升翻腾。\n花树笼罩从秦入川的栈道，春江碧水绕流蜀地的都城。\n你的进退升沉都命中已定，用不着去询问善卜的君平。', poem_notes = '见说：唐代俗语，即“听说”。蚕丛：蜀国的开国君王。蚕丛路：代称入蜀的道路。\n崎岖：道路不平状。\n山从人面起：人在栈道上走时，紧靠峭壁，山崖好像从人的脸侧突兀而起。\n云傍马头生：云气依傍著马头而上升翻腾。\n芳树：开著香花的树木。秦栈：由秦（今陕西省）入蜀的栈道。\n春流：春江水涨，江水奔流。或指流经成都的郫江、流江。蜀城：指成都，也可泛指蜀中城市。\n升沉：进退升沉，即人在世间的遭遇和命运。\n君平：西汉严遵，字君平，隐居不仕，曾在成都以卖卜为生。', poem_appreciation = '这是一首以描绘蜀道山川的奇美而著称的抒情诗，公元743年（唐玄宗天宝二年）李白在长安送友人入蜀时所作。\n\n　　全诗从送别和入蜀这两方面落笔描述。首联写入蜀的道路，先从蜀道之难开始：“见说蚕丛路，崎岖不易行。”\n\n　　“见说蚕丛路，崎岖不易行。”临别之际，李白亲切地叮嘱友人：听说蜀道崎岖险阻，路上处处是层峦叠嶂，不易通行。语调平缓自然，恍若两个好友在娓娓而谈，感情显得诚挚而恳切。它和《蜀道难》以饱含强烈激情的感叹句“噫吁嚱，危乎高哉，蜀道之难难于上青天”开始，写法迥然不同，这里只是平静地叙述，而且还是“见说”，显得很委婉，浑然无迹。首联入题，提出送别意。颔联就“崎岖不易行”的蜀道作进一步的具体描画：“山从人面起，云傍马头生。”\n\n　　蜀道在崇山峻岭上迂回盘绕，人在栈道上走，山崖峭壁宛如迎面而来，从人的脸侧重迭而起，云气依傍着马头而升起翻腾，像是腾云驾雾一般。“起”、“生”两个动词用得极好，生动地表现了栈道的狭窄、险峻、高危，想象诡异，境界奇美，写得气韵飞动。\n\n　　蜀道一方面显得峥嵘险阻，另一方面也有优美动人的地方，瑰丽的风光就在秦栈上：“芳树笼秦栈，春流绕蜀城。”\n\n　　此联中的“笼”字是评家所称道的“诗眼”，写得生动、传神，含意丰满，表现了多方面的内容。它包含的第一层意思是：山岩峭壁上突出的林木，枝叶婆娑，笼罩着栈道。这正是从远处观看到的景色。秦栈便是由秦（今陕西省）入蜀的栈道，在山岩间凿石架木建成，路面狭隘，道旁不会长满树木。“笼”字准确地描画了栈道林荫是由山上树木朝下覆盖而成的特色。第二层的意思是：与前面的“芳树”相呼应，形象地表达了春林长得繁盛芳茂的景象。最后，“笼秦栈”与对句的“绕蜀城”，字凝语炼，恰好构成严密工整的对偶句。前者写山上蜀道景致，后者写山下春江环绕成都而奔流的美景。远景与近景上下配合，相互映衬，风光旖旎，有如一幅瑰玮的蜀道山水画。诗人以浓彩描绘蜀道胜景，这对入蜀的友人来说，无疑是一种抚慰与鼓舞。尾联忽又翻出题旨：“升沉应已定，不必问君平。”\n\n　　李白了解他的朋友是怀着追求功名富贵的目的入蜀，因而临别赠言，便意味深长地告诫：个人的官爵地位，进退升沉都早有定局，何必再去询问善卜的君平呢！西汉严遵，字君平，隐居不仕，曾在成都卖卜为生。李白借用君平的典故，婉转地启发他的朋友不要沉迷于功名利禄之中，可谓谆谆善诱，凝聚着深挚的情谊，而其中又不乏自身的身世感慨。尾联写得含蓄蕴藉，语短情长。\n\n　　这首诗，风格清新俊逸。诗的中间两联对仗非常精工严整，而且，颔联语意奇险，极言蜀道之难，颈联忽描写纤丽，又道风景可乐，笔力开阖顿挫，变化万千。最后，以议论作结，实现主旨，更富有韵味。\n\n　　此诗与《蜀道难》都是写蜀地风光，但在写法上有较大区别。其同者都是从“传说”“见说”入题，着力虚拟夸说蜀道迷离神奇的色彩和点染烘托蜀道的艰险诡奇的气氛，突出难和险，继之按由秦入蜀的时空顺序，绘声绘色，穷形尽相地描绘了蜀道山水风光雄奇峻伟、高危惊险的独有特点。然而，两诗之异则迥然有别。《蜀道难》充满想象与夸张，而《送友人入蜀》则比较写实。《蜀道难》着意于“难”，寓情于“忧”，诗突然“以嗟叹起，嗟叹结”，中间再以“蜀道之难，难于上青天”复呼再叹，呼前应后，将蜀道开辟之极苦，蜀道行路之极难，蜀地留居之极险，浑成为一，全诗起结开合，纵横起伏，既有雄浑之势，又有飘逸之神。《送友人入蜀》着眼于“送别”，归结于“入蜀”，从诗旨上讲，不宜夸说渲染蜀道之险难，从五言律诗体裁讲，更毋庸备述蜀道难行的苦况。首联平静点出蜀道“崎岖不易行”的题旨，颔联则化虚说为“实感”，紧承“崎岖”二字。“山从人面起，云傍马头生”，尽显蜀道的狭窄、险峻、高危、诡异，颈联“芳树笼秦栈，春流绕蜀城。”则灵笔一转，由险峻奇诡而优美瑰丽，清丽明畅。尾联则以旷达顺适之情，劝慰友人随缘应机。全诗起承转合皆紧贴诗题，叙事状物，写景寄情，一脉相连。', poem_tags = '送别,山水,抒情,劝勉' WHERE poem_title = '送友人入蜀' AND poem_author = '李白';
UPDATE edu_poem SET poem_appreciation = '万山，在襄阳西北，汉水南岸，又名汉皋山。此地环境清幽，为襄阳名胜，又有神女解佩的传说，更增添了一层迷人的色彩。浩然常游此地，诗集中就有三首于此得题。“万山潭”，指山旁江水深曲处。\n\n　　首联写诗人冲淡的心情和垂钓之乐。垂钓本身，已乐在其中，何况静坐磐石之上。“坐”字一字，更显安闲。且潭水清澈，与闲适的心境相默契。诗中未提一个乐字，但乐字已融入闲淡之中。\n\n　　颔联，所谓“鱼行潭树下”，似不合理，盖鱼是水中之物，不可能行之于树下。细细体味，就可理解潭侧之树高于潭中之鱼，且树影映入潭水之中，鱼儿翕翕游动，自由自在。故“鱼行潭树下”。在这里，诗人虽没有正面描写树的倒影，但却可以领悟出树的倒影的荡漾美，与游鱼的动态美相互参差，更显出美的多样性。且“鱼行”与“猿挂”，一低一高，遥相呼应，更拓展出空间的距离美。“潭树下”与“岛藤间”，一潭一岛，一树一藤，一下一上，也显示出对称美。颈联借当地典故抒发情怀。曹植《洛神赋》中说：“交甫之弃言兮，怅犹豫而狐疑。”意思是郑交甫曾游于万山，巧遇两个游山的神女，羡慕不已，向神女索取佩带上的饰物，游女解佩赠之，但霎时，游女及佩饰均不见。郑交甫怅惘良久。这个美丽的神话，为万山潭增添了迷人的风采，也触动着诗人的心弦，并自然地引出下句诗来。\n\n　　尾联写心中向往，求之不得，于是月下放歌，乘舟而返。游女解佩的故事，给诗人以无穷的遐思。诗人不禁悠然神往。“沿”字，用得亦极其神妙，更增添了月儿的动态美，表明不仅仅是一点月色，而是沿途通明，明月满舟，银辉一路，歌声不绝。此情此景，令人向往。\n\n　　全诗有动有静。首、颔二联，以静为主，寓动于静；颈、尾二联，以动为主，寓静于动。冲淡之风，显隐于动静之中。闻一多说：“真孟浩然不是将诗紧紧的筑在一联或一句里，而是将它冲淡了，平均的分散在全篇中，”“甚至淡到令你疑心到底有诗没有。”（《唐诗杂论》）所谓“羚羊挂角，无迹可求”（严羽《沧浪诗话·诗辩》），正是此中境界的写照。刘熙载说：“诗品出于人品”（《艺概·诗概》）。\n\n　　关于孟浩然的人品，王士源说他“骨貌淑清、风神散朗。救患释纷、以立义表。灌疏艺竹，以全高尚。”（《孟浩然集序》）王维在绢本上绘制的孟浩然肖像“颀而长，峭而瘦，风仪落落，凛然如生。”（《韵语阳秋》引张洎题识）可见，孟浩然的人品可用风清骨峻四个字来形容。它体现在孟氏诗中，就浇铸出孟浩然的诗品。\n\n　　正如闻一多所说，《万山潭作》一诗，这是诗的孟浩然，又是孟浩然的诗。诗人的心境是非常悠闲、清静、旷达、淡泊的；诗人的形象是“风神散朗”、“风仪落落”的。这确是诗如其人、人即其诗了。孟浩然所创造的人入其诗、诗显其人的最高境界就是冲淡。\n\n　　孟浩然和王维，都推崇冲淡，却各有千秋。胡应麟在《诗薮》中说：“浩然清而旷，王维清而秀。”可见，王、孟虽同样具有冲淡中“清”的特点，王维偏重秀字，孟浩然偏重一个旷字。王维的《青溪》，虽然写了素、闲、清、澹，但从“声喧乱石中，色静深松里。漾漾泛菱荇，澄澄映葭苇”的诗句中，却可看见大自然的秀丽景色。孟浩然的《万山潭作》，虽然也写了清、闲，但从神寄游女、归舟放歌的情境中，读者却可窥见他的旷达情怀。', poem_tags = '山水' WHERE poem_title = '万山潭作' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '屋上有一只春鸠在鸣叫，村边开着大片的白色杏花。\n手持斧子去整理桑树那长长的枝条，扛起锄头去察看泉水的通路。\n去年的燕子飞回来了，好像认识它的旧巢。屋里的旧主人在翻看新年的日历。\n举杯欲饮，又停了下来，想到离开家园作客在外的人，不由惆怅惋惜。', poem_notes = '春中（zhòng）：即仲春，农历二月。\n春鸠（jiū）：鸟名，即布谷鸟、杜鹃，象鸽子，有斑鸠、山鸠等。曹植《赠徐干》：“春鸠鸣飞栋，流飙激棂轩”。\n远扬：又长又高的桑枝。《诗经·豳风·七月》：“蚕月条桑，取彼斧斨，以伐远扬”。砍去又高又长的桑枝，便于以后采桑。\n觇（chān）：探测、察看。泉脉：地下的泉水。地层中的泉流象人体内血脉一样，故称之泉脉。\n看新历：开始新的一年。\n觞（shāng）：古代饮酒用的器皿，此指酒杯。御：进用，饮、喝的意思。\n惆怅远行客：即“远行客惆怅”。远行客：出远门的人。', poem_appreciation = '此诗写出了春天的欣欣向荣和农民的愉快欢欣，结尾则表达远行者对乡土的眷恋。全诗健康活泼，清新醇朴。\n\n　　冬天很难见到的斑鸠，随着春的来临，很早就飞到村庄来了，在屋上不时鸣叫着，村中的杏花也赶在桃花之前争先开放，开得雪白一片，整个村子掩映在一片白色杏花之中。开头两句十个字，通过鸟鸣、花开，就把春意写得很浓了。接着，诗人由春天的景物写到农事，好像是春鸠的鸣声和耀眼的杏花，使得农民在家里呆不住了，农民有的拿着斧子去修整桑枝，有的扛着锄头去察看泉水的通路。整桑理水是经冬以后最早的一种劳动，可说是农事的序幕。\n\n　　归燕、新历更是春天开始的标志。燕子回来了，飞上屋梁，在巢边呢喃地叫着，似乎还能认识它的故巢，而屋中的旧主人却在翻看新一年的日历。旧人、归燕，和平安定，故居依然，但“东风暗换年华”，生活在自然地和平地更替与前进。对着故巢、新历，燕子和人将怎样规划和建设新的生活，这是用极富诗意的笔调，写出春天的序幕。新历出现在人们面前的时候，就像春天的布幕在眼前拉开了一样。\n\n　　诗的前六句，都是写诗人所看到的春天的景象。结尾两句，写自己的感情活动。诗人觉得这春天田园的景象太美好了，“物欣欣而向荣，泉涓涓而始流”，一切是那样富有生气，充满着生活之美。诗人很想开怀畅饮，可是，对着酒又停住了，想到那离开家园作客在外的人，无缘享受与领略这种生活，不由得为之惋惜、惆怅。\n\n　　此诗春天的气息很浓，而诗人只是平静地淡淡地描述，始终没有渲染春天的万紫千红。但从淡淡的色调和平静的活动中却成功地表现了春天的到来。诗人凭着敏锐的感受，捕捉的都是春天较早发生的景象，仿佛不是在欣赏春天的外貌，而是在倾听春天的脉搏，追踪春天的脚步。诗中无论是人是物，似乎都在春天的启动下，满怀憧憬，展望和追求美好的明天，透露出唐代前期的社会生活和人的精神面貌的某些特征。人们的精神状态也有点像万物欣欣然地适应着春天，显得健康、饱满和开拓。', poem_tags = '春天,田园,写景,农事' WHERE poem_title = '春中田园作' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '傍晚的夕阳斜照着华丽的宫殿，岁月使宫廷更加美丽。\n年终岁寒，冬雪消融，暖洋洋的宫闱里似乎吹进了和煦的春风。\n巨大红烛点燃了，远远看上去，像一簇簇花团。\n君臣欢宴饮酒，喜度良宵，迎新年，辞旧岁，通宵歌舞。', poem_notes = '芳殿：华丽的宫殿。下文绮宫亦同。\n丽：使动用法，使······美丽。\n馥（fù）：香气。\n盘花：此指供品。', poem_tags = '春节,闲适' WHERE poem_title = '守岁' AND poem_author = '李世民';
UPDATE edu_poem SET poem_translation = '《文选》卷八。上林，上林苑，故址在今陕西西安市西及周至、户县界。它本是秦代的旧苑，汉武帝时重修并加扩大。\n⑵亡是公：作者假托的人名。亡，通“无”。听（yǐn引）然：张口而笑的样子。\n⑶失：指不对。《上林赋》是承《子虚赋》而来，《子虚赋》是借楚国子虚和齐国乌有先生的对话展开，以折齐称楚结束，所以本文这样承接。\n⑷纳贡：交纳贡物。\n⑸述职：古代诸侯朝见天子，陈述政务方面的情况。\n⑹封疆画界：指画定诸侯国之间的疆界。古代植树为界，称封疆，在两封之间又树立标志，称画界。\n⑺淫：放纵，过分。指诸侯国不知节制，侵入别国疆界。\n⑻东藩：东方的藩国。齐国在东，故称“东藩”。藩，藩篱、屏障。\n⑼私：指私自交好。肃慎：古国名，在今长白山以北至黑龙江一带。⑩捐国：指离开自己的国家。逾限：越过本国边界。\n⑾越海而田：指《子虚赋》言齐王“秋田乎青丘”之事。“青丘”为传说中的海外国名，故云“越海”。田，通“畋”，畋猎。\n⑿二君：指《子虚赋》中的子虚和乌有先生。\n⒀相胜：相互压服。\n⒁扬名发誉：即发扬名誉。意思是使好的名声传播开来。\n⒂贬君自损：贬低君主，损害自己的声誉。\n⒃乌：何。⒄左：指东方。苍梧：汉郡名，治所在今广西苍梧县。苍梧古属交州，在长安东南，故言“左”。\n⒅右：指西方。西极：古指豳地，在长安西北一带，故言“右”。\n⒆丹水：水名，出陕西商州市西北冢岭山，东南流入河南境。更：经过。\n⒇紫渊：当为上林苑北边水名。径：同“经”。\n（21）终始灞浐：指灞水和浐水始终流在上林苑中。终始，作动词用。灞浐，都是渭水的支流。（22）出入泾渭：指泾水和渭水流入苑中又流出苑去。泾，泾水，源出宁夏南部六盘山东麓，流经甘肃，至陕西高陵县境入渭水。渭，渭水，源出甘肃渭源县之鸟鼠山，东流至陕西潼关县入黄河。\n（23）酆镐（hào浩）潦（lǎo老）潏（jué决）：皆为水名。酆，源出陕西宁陕县东北秦岭，东北流经长安入渭水。镐，源出陕西长安县南，北注于渭水。现下游已湮，上游北注于潏水。潦，源出陕西□县南山涝谷，东北经咸阳西南境注于渭水。潏，源出陕西□县南山石鳖谷，北经长安入渭水。\n（24）纡馀委蛇（yí移）：形容水流曲折宛转的样子。委蛇，同“逶迤”。\n（25）经营乎其内：指诸水流经其中。经营，周旋。\n（26）八川分流：指上述灞、浐、泾、渭、酆、镐、潦、潏八条河流各自流动。\n（27）相背：指诸水流向不一。\n（28）驰骛：马疾行的样子，这里指水流很快。\n（29）椒丘之阙：生满椒树的山相对而立，类似于阙的形状。阙，又名门观。门前两旁建台，上有楼观，中间有阙口为通道，故称阙。\n（30）洲淤：水中可居之地。古时长安一带人呼洲为淤。浦：水边。\n（31）桂林：指上林苑中的桂树林。\n（32）泱漭：广大、辽阔。\n（33）汩（yù玉）乎混流：指水流很急，水势很大。汩，水流迅速。混，水势浩大。\n（34）阿：高大的山丘。\n（35）隘陿：即狭隘。陿，同“狭”。\n（36）穹石：大石。\n（37）堆埼（qí奇）：高大曲折的河岸。\n（38）滭弗（bìfèi毕沸）同“觱沸”，水上涌的样子。宓（mì密)汩：水流疾去的样子。\n（39）逼侧：水迫近岸边。泌瀄（jié节）：水浪涌起互相冲击的样子。逼，同“逼”。\n（41）转腾：旋转激荡。潎（piē瞥）冽：水波互相冲击的样子。\n（41）滂濞（pāngpì乓僻）：即“彭湃”，水波相互撞击的声音。沆（hàng杭去声）溉：水浪愤怒涌起的样子。\n（42）穹隆：水势高起的样子。云桡：形容\n水势回旋翻滚如云涌。桡，扰动。\n（43）宛潬（shàn善）：水流盘曲的样子。胶□：水流纠绞在一起的样子。□，同“戾”。\n（44）逾波：一波超一波，即后浪推前浪。趋浥：指很快地流向低处。\n（45）涖（lì利）涖：水流急的样子。濑（lài赖）：浅水沙石滩。\n（46）批：击打。拥：同“壅”，防水堤。\n（47）奔扬：水流奔腾。滞沛：浪花翻卷。\n（48）临坻（chí持）：临近小丘。坻，水中小丘。注壑：流入沟壑之中。\n（49）瀺灂（chánzhuó馋着）：小水声。指水流近小丘时发出的细小声音。霣坠：指水从高处落到低处。霣，通“陨”。\n（51）沈沈：水深的样子。隐隐：水势盛大。\n（51）砰磅（pēngpāng烹乓）：即“乒乓”，象声词。訇礚（hōngkē轰科）：指水流激荡发出轰隆隆的声音。\n（52）潏（jué决）潏淈（gǔ古）淈：水涌出的样子。潏，水涌出貌。淈淈，同“汩汩”。\n（53）湁潗（chìjí赤集）鼎沸：形容水流上涌如沸腾的样子。湁潗，水沸腾的样子。\n（54）驰波跳沫：水流疾泻而飞沫跳荡。\n（55）汩濦（yùxī遇吸)：水流急转的样子。濦，《汉书》作“□”。漂疾：同“剽疾”，形容水势猛悍。\n（56）怀：归往。\n（57）寂漻：同“寂寥”，水流平缓而无声。\n（58）肆：安，指水流平稳安定。\n（59）灏溔（hàoyǎo号杳）：水势广大无际的样子。潢（guāng光）漾：水势深广，水波荡漾。\n（60）安翔徐回：形容水流缓慢。回，回旋。\n（61）翯（hè鹤）乎滈（hào浩）滈：谓大水泛着白光。□，白而有光泽。滈滈，指水泛着白光。\n（62）太湖：在今江苏省。因在长安东方，故曰“东注”。\n（63）衍溢陂（pí皮）池：谓水流满池塘。陂池，池塘。\n（64）螭（chī吃）：传说中蛟龙一类动物，无角。\n（65）䱭䲛（gèngméng更去声萌）：鱼名，形似鳝。渐离：鱼名，形状不详。\n（66）鰅（yú于）：鲶类的一种，皮肤有文。鰫（yōng庸）：同“鳙”，即花鲢鱼。鳍（qián虔）：鱼名，形似鲤而体长。鮀（tuō托）：即河豚。或说即黄颊鱼，口大而食小鱼。\n（67）禺禺：黄地黑文，皮上有毛的一种鱼。魼（qū区）：即比目鱼。鳎（tǎ塔）：亦比目鱼一类。\n（68）揵（qiān虔）：扬起。掉：摇动。\n（69）讙：喧哗，闹嚷。\n（70）明月：宝珠名。\n（71）的□（lì历）江靡（méi眉)：谓宝珠的光芒照耀江边。的□，明亮的样子。靡，通“湄”，水边。\n（72）蜀石：质次于玉的一种石。黄碝（ruǎn软）：黄色的碝石。碝，石名，质地次于玉。\n（73）水玉：即水晶石。磊砢（luǒ裸）：众多。\n（74）磷磷烂烂：谓玉石色泽鲜明，光彩灿烂。\n（75）“采色”二句：谓玉石积聚于水中，光芒辉映。澔汗，同“浩汗”，盛多的样子。这里指光彩灼灼，相互映辉。藂，同“丛”。\n（76）鸿：大雁。鹔（sù肃）：即鹔鹴，雁的一种，毛为绿色。鹄：天\n鹅。鸨：似雁而大，灰颈白腹，背部有黄褐和黑色斑纹。\n（77）□（jiā家）鹅：雁的一种，形比鸭大而嘴小。《方言》：“雁，自关而东谓之□鹅。”□，同“□”。属（zhú烛）玉：即“鸀□”，水鸟，似鸭而大。\n（78）交精：同“□□”，水鸟名，俗名茭鸡，形如凫而腿长。旋目：鸟名，大于鹭而尾短，眼旁毛呈现回旋的样子。\n（79）烦鹜：鸟名，外形像鸭而小。庸渠：鸟名，俗名水鸡，外形像鸭而鸡足。\n（80）箴疵：水鸟名，形似鱼虎，毛呈苍黑色。□卢：俗称水老鸦。\n（81）泛淫泛滥：指鸟浮于水面上自由自在的样子。泛，同“泛”，飘浮。\n（82）澹淡：此指飘动的样子。\n（83）奄薄水渚：指群鸟止息于小洲之上。奄，息。薄，集。\n（84）唼喋（zādié匝谍）：指鸟聚在一起吃食。菁、藻：都是水草名。\n（85）矗矗：山直立高耸的样子。\n（86）巃嵷（lóngzōng龙宗）崔巍：山高峻的样子。\n（87）崭（chán缠）岩□嵳：山势险要高低不平。崭，同“□”。□嵳，同“参差”。\n（88）九嵕（zōng宗）：山名，在陕西醴泉县东北。嶻嶭（jiéniè截聂）：山高峻的样子。\n（89）南山：终南山，主峰在陕西西安市南。峨峨：高大。\n（90）岩陁（zhì志）□（yǎn眼）锜（qí其)：指山中多穴洞。陁，坂，山坡。□，瓦器名，即甑。锜，三只脚的釜。王先谦《补注》说：“山之嵌空玲珑有若锜然，与□对文。”\n（91）摧崣：同“崔巍”，山势高峻的样子。崛崎：形容山势陡峭险绝。\n（92）振溪通谷：指大的山谷。振，开放。溪，溪谷。通，通达。\n（93）蹇产：曲折的样子。\n（94）谽（hān酣）呀豁閕（xiā虾）：指山谷幽远空洞的样子。谽呀，形容山谷幽深。豁閕，空虚的样子。\n（95）阜陵别□：谓山丘像被水分成的一个个小岛。□，同“岛”。\n（96）崴磈（wéi危）□廆（wēi伟）：都是高峻的意思。\n（97）丘虚堀礨（juélěi决垒）：指山特起不平的样子。虚，通“墟”。\n（98）隐辚郁□（lěi磊）：指山堆积不平的样子。\n（99）登降施（yǐ以）靡：指山势高下绵延。施靡，山势倾斜绵延的样子。\n（100）陂池貏豸（bǐzhì比至）：指山势渐渐平坦。陂池，读如“坡陀”，倾斜的样子。貏豸，渐趋平坦。\n（101）沇（wěi伟）溶淫鬻：指水在山涧中缓缓流动。淫鬻，水流缓慢。\n（102）散涣：涣散，散开。夷陆：平坦的原野。\n（103）“亭皋”二句：谓水边地方没有不平坦的。亭，平。皋，水边地。被筑，指筑地令平。\n（104）揜（yǎn眼）：遮盖。绿蕙：香草名。\n（105）被：覆盖。江蓠：香草名。\n（106）糅：掺杂。蘪芜：香草名，又名蕲芷。\n（107）留夷：香草名。\n（108）布：布满。结缕：草名，多年曼生，叶如白茅。\n（109）攒戾莎：戾莎丛聚而生。戾莎，草名。\n（110）揭车衡兰：指揭车、杜衡和兰草三种香草。\n（111）槀（gǎo稿)本：香草名，根可入药。射干：草名，根可入药。\n（112）茈姜：即紫姜，嫩姜。茈，同“紫”。蘘（ráng瓤）荷：一名蘘草，茎叶似姜，根可食，也可入药。\n（113）葴（zhēn针）持：即酸浆草。若荪：杜若和荪草，都是香草。\n（114）鲜支：香草名，又名燕支，可染红色。黄砾：香草名，可染黄色。\n（115）蒋：即菰蒲草，又名茭，所结实即菰米。苎（zhù注）：同“芧”，草名，即三棱草。青薠：草名，形状类莎（suō蓑）草而稍大。\n（116）布濩（hù户）：散布，布满。闳泽：大水泽。闳，宏大。\n（117）延曼：蔓延。太原：广大原野。\n（118）离靡：连绵不断的样子。广衍：广泛散布开来。衍，展开。\n（119）吐芳扬烈：谓花草散发出浓烈的香气。\n（120）郁郁菲菲：形容香气浓烈。\n（121）发越：发扬，散发。\n（122）肸蚃（xīxiǎng希响）：指香气四散，沁入人心。肸，响声传布。蚃，对声音反映敏感的一种虫子。布写：四散传布。写，通“泻”。\n（123）晻薆咇茀（bìbó必伯）：形容香气充盛。\n（124）缜纷：茂密繁多。轧芴（wù勿）：致密而不可分辨。\n（125）芒芒恍忽：眼花缭乱的样子。\n（126）东沼：上林苑东边池沼。\n（127）西陂：亦上林苑池名。与上句联系，极言上林苑之大。\n（128）“其南”二句：指上林苑面积广阔，其南部隆冬也草木生长，水不结冻。\n（129）□（róng容）：又名封牛，颈上有肉堆，有力而善于奔走。旄：旄牛。貘（mò莫）：形似犀牛而略小，鼻长无角。□（lí犁）：小于旄牛，皮黑色。\n（130）沈牛：水牛。麈（zhǔ主）：鹿类，一角，尾大，可作拂尘。麋：即驼鹿，又叫犴（hān鼾)，四不像。\n（131）赤首：传说中的一种兽的名称。圜题：亦是一种兽名。传说两兽均生活在南方。题，额。\n（132）穷奇：传说中的怪兽，能食人，外形像牛，毛如猬，声音像嗥狗。\n（133）其北：指上林苑北部。\n（134）揭（qì器）：提起衣服度水。\n（135）角端：兽名，外形像貊（形似熊），角生在鼻上。\n（136）騊駼（táotú陶途）：兽名，形似马。橐驼：即骆驼。\n（137）蛩（qióng穷）蛩：一种白色野兽，形似马。□騱（tuóxī驼溪）：野马的一种，青黑色，有白色鳞纹。\n（138）駃騠（juótí决提）：骏马名。□：同“骡”。\n（139）离宫别馆：指皇宫以外供皇帝临时居住的宫殿馆舍。\n（140）四注：四面围绕。\n（141）重坐：指两层楼房。曲阁：指曲折连结的楼阁。\n（142）华榱（cuī崔）：用花纹装饰的椽子。璧珰：用璧玉装饰的瓦当。\n（143）辇道□（xǐ喜）属：指宫中辇道四通八达。辇道，可以乘辇而行的阁道。□属，阁道回环，如织丝之相连属。□，束发的帛。\n（144）步櫩（yán言）：可以通行的长廊。櫩，同“檐”。周流，周遍。\n（145）长途中宿：谓长廊走不完，中间需要停宿。\n（146）夷嵕（zōng宗）筑堂：削平山岭，建筑房屋。夷，\n削平。嵕，高的山。\n（147）累台增成：高的楼台一层又一层。增，通“层”。成，一层叫一成。\n（148）岩窔（yǎo咬）：深邃的样子。洞房：幽深的房屋。\n（149）頫：同“俯”。杳眇：深邃的样子。此句是形容亭台极高，下视不见地。\n（150）橑（lǎo老)：屋椽。扪（mén门）：用手摸。此句亦形容亭台极高。\n（151）奔星：流星。更：经过。闺闼：宫中的小门。\n（152）宛虹：弯曲的虹。扦：同“拖”。楯（shǔn吮）轩：指门窗的栏杆。\n（153）“青龙”句：谓青龙驾的车子可以在东厢房行进。此极力形容房屋的宽阔。蚴蟉（yǒuliú友流），龙行的样子。此用以形容车子。东箱，东边厢房。箱，通“厢”。原作“葙”，据《考异》改正。\n（154）象舆：象拉的车子。婉僤（shàn善）：车行进的样子。西清：指西厢房。清，清静之处。\n（155）灵圄（yǔ语）：对于仙人的总称。燕：燕息，闲居。闲馆：清雅的馆舍。\n（156）偓佺：古代传说的仙人名。伦：类。\n（157）暴：通“曝”，晒太阳。荣：指飞檐。\n（158）醴泉：甘甜的泉水。清室：即静室。\n（159）通川：流水。\n（160）盘石：大石。盘，通“磐”。振崖：砌成整齐的石崖。振，《考异》以为当作“裖（zhèn振）”，累积整齐。\n（161）嵚（qīn钦）岩：倾斜的样子。倚倾：偏斜倾侧。\n（162）嵯峨：高大的样子。□□（jiéyè捷业）：高峻的样子。\n（163）刻削：形容石崖险峻，像刀削过一样。\n（164）玫瑰：珍珠名。碧琳：玉石名。\n（165）琘玉：像玉的美石。琘，同“珉”。旁唐：如说“磅礴”，广大的样子。\n（166）玢（bīn宾）豳：有纹理的样子。文鳞：文彩斑烂像鳞片一样排列。\n（167）赤瑕：赤色的玉。驳荦（luò洛）：色彩斑驳。驳，同“驳”。（168）杂臿：夹杂。臿，通“插”。\n（169）晁采：美玉名。琬琰（yǎn演）：美玉名。\n（170）和氏：指和氏璧。为春秋时楚国人卞和所发现。\n（171)卢橘：橘子的一种，皮厚，大小像柑。秋天结实，第二年夏天始熟。\n（172）黄甘：即黄柑，橘的一种。楱（còu凑）：橘的一种，又称小橘。\n（173）橪（rán然）：即酸枣。\n（174）亭：即棠梨，又名海棠果。奈：属苹果一类的水果。厚朴：树名，果实甘美，树皮可入药。\n（175）梬（yǐng影）枣：枣类，外形似柿而小。\n（176）蒲陶：即葡萄。\n（177）隐夫：果木名，形状不详。薁（yù郁）棣：即唐棣，又名郁李，果实可食，种子入药。\n（178）答沓（tà踏）：木名，果实像李子。离支：即荔枝。\n（179）□（yí宜）：通“迤”，延及，绵延。\n（180）扤（wù物）：摇动不定。\n（181）荣：木本植物的花。\n（182）煌煌扈扈：光彩鲜艳的样子。\n（183）钜野：广阔的原野。钜，同“巨”。\n（184）沙棠：果名，俗名沙果。栎（lì立）：橡实。槠（zhū朱）：苦槠，木名，常绿乔木，果实小于橡实。\n（185）华：即桦树。枰（píng平）：平仲树，即银杏树。栌（lú卢）：黄栌。\n（186）留落：石榴树。胥邪：即椰子树。\n（187）仁频：即槟榔树。并闾：即棕榈树。\n（188）欃檀：檀木的一种。木兰：又名杜兰，木名。\n（189）豫章：即樟树。女贞：即冬青树。\n（190）大连抱：指树干很粗，几个人才能合抱过来。\n（191）夸条：指花朵和枝条。夸，通“荂（huā花)”，花。直畅：指任意舒展。\n（192）葰楙（jùnmào俊茂）：肥大茂盛。葰，大。楙，同“茂”。\n（193）攒立丛倚：指草木丛聚而生，或直立，或相互依傍。\n（194）连卷（quán拳）：即“连蜷”，指枝柯屈曲生长。□佹（lìguǐ立鬼）：指树枝相互交错，向背不一。□，依附。佹，背离。\n（195）崔错：错杂的样子。癹骫（bōwěí拨委）：指枝条屈曲错杂的样子。骫，通“委”。\n（196）坑衡：抗衡。坑，通“抗”。□砢（kěluǒ可裸）：指枝条盘屈扭结，互相倾倚。\n（197）落英：落花。幡□（xǐ喜）：飞扬的样子。\n（198）纷溶：繁盛的样子。箾□（xiāosēn萧森）：高大的样子。\n（199）猗狔从风：指花随风飘动。猗狔，同“旖旎”，柔美的样子。\n（200）藰莅：风吹草木发出的声音。卉歙（xī吸）：如同说“呼吸”，指风迅疾吹木的声音。\n（201）籥：古代的一种管乐器。\n（202）“偨池”二句：指高高低低树木围绕后宫生长。偨池，同“差池”，高低不平的样子。茈虒（cíchí词池），义亦同“差池”，不整齐。旋还，环绕。\n（203）杂袭：错杂重复。絫辑：同“累集”，众多繁盛。\n（204）循：沿着。阪：山坡。隰（xí习）：低湿的地方。\n（205）无端：无边。\n（206）玄猨素雌：黑色的雄猿，白色的雌猿。猨，同“猿”。\n（207）蜼（wěi伟）：一种长尾猿，形如猕猴黑色。玃（jué觉）：大母猴。鸓（lěi垒）：鼯鼠。前后肢间有薄膜，能从树上飞翔。\n（208）蛭：传说中一种能飞的兽，四翼。蜩：当作“□（zhǒu帚）”，传说中一种兽名，大如驴，形如猴，善爬树。蠼猱（juénáo决挠)：同“玃猱”，老猕猴\n（209）獑（chán馋）胡：同“獑猢”，兽名，似猿。縠（hú狐）：即白狐子，以猴类为食物。蛫（guǐ诡）：猿类。\n（210）翩幡：鸟飞轻疾的样子。这里指猿类来往轻捷灵巧。幡，通“翻”。互经：互相经过。\n（211）夭□（jiǎo狡）：指猿猴跳荡矫健的动作。枝格：长的树枝。\n（212）偃蹇：指猿猴身体活动屈曲宛转的样子。杪（miǎo秒）颠：树枝顶端。杪，树梢。\n（213）隃：同“逾”，越过。绝梁：断的桥梁。这里形容从甲树跃到乙树如越绝梁，非实指。\n（214）腾：跃上。殊榛（zhēn真）：另一片榛树丛。\n（215）捷垂条：拉住下垂的树枝。捷，通“接”。\n（216）掉希间：指猿猴在树枝稀疏的空间荡来荡去。掉，摆动，摇荡。\n（217）牢落陆离：指猿猴零落不齐，聚散无常。牢落，散漫的样子。陆离，参差不齐。\n（218）烂漫远迁：指猿\n猴往来迁徙。烂漫，形容猿猴奔走蹦跳的样子。\n（219）宫宿馆舍：在离宫止宿，在别馆居住。\n（220）“庖厨”三句：谓离宫别馆中有庖厨，有宫女，有百官奉侍，不必从朝廷调来。\n（221）背秋涉冬：指秋末冬初。背，离开。涉，入。\n（222）校（jiào较）猎：用木栏圈起猎场打猎。校，木栏。\n（223）镂象：指用象牙雕刻装饰的车子。\n（224）六玉虬：指用六匹马驾车。虬，无角的龙。这里指马。\n（225）拖：曳。蜺旌：指色彩斑斓有如虹蜺的旌旗。蜺，同“霓”。\n（226）靡：倾斜。云旗：画有熊虎的大旗。\n（227）皮轩：以兽皮作饰的车子。\n（228）道游：指道车和游车。古代天子出行，用道车五乘、游车九乘作为前导。道，通“导”。\n（229）孙叔：古代善于驾车的人。一说，指汉武帝时的太仆公孙贺（字子叔）。奉：捧。\n（230）卫公：也是指古代善于驾车的人。一说，指汉武帝时大将军卫青。参乘：陪乘，即车右，担任护卫。参，通“骖”。\n（231）扈从：即护从，指天子的侍卫。\n（232)四校：指天子射猎时的四支扈从部队。\n（233）鼓严簿：指在戒备森严的仪仗侍卫队伍中击鼓。簿，卤簿，天子出行时的随行仪仗。\n（234）河江：即江河。阹（qù去）：阻拦禽兽的围阵。\n（235）橹：望楼。\n（236）雷起：形容车骑声很大，如同雷响。\n（237）殷天：震天。\n（238）陆离：分散。\n（239）别追：指分别追逐禽兽。\n（240）淫淫裔裔：指围猎的人来来往往。\n（241）流泽：指打猎的车骑密密麻麻地拥向水泽。\n（242）生貔（pí皮）豹：活捉貔豹等野兽。貔，豹一类的猛兽。\n（243）搏：搏击。\n（244）手：徒手击杀。罴：熊类猛兽。\n（245）足：用脚踏住。壄：同“野”。\n（246）蒙鹖苏：指戴着用鹖鸟尾装饰的帽子。鹖，鸟名，形像雉鸡，斗时至死不退却。苏，尾。\n（247）绔（kù库）白虎：穿着织有白虎纹饰的裤子。绔，同“袴”，套裤，此指穿套裤。\n（248）被：通“披”，穿着。班文：指用虎豹一类兽皮作成的衣服。\n（249）跨：骑。壄马：指北地所产的良马，又名騊駼。\n（250）凌：登。三嵕：山名。危：顶巅。\n（251）碛（qì气）历：高低不平的样子。坻（dǐ底）：山斜坡。\n（252）径：同“经”，过。\n（253）厉：涉水。\n（254）椎：击杀。蜚廉：龙雀，鸟身鹿头。\n（255）弄：用手摆弄，此也指擒获。獬豸：神兽名，相传似鹿而一角。\n（256）格：搏杀。虾蛤：猛兽名。\n（257）鋋（chán谗）：铁柄短矛。这里指用短矛刺杀。猛氏：兽名，形状像熊而小，毛短，有光泽。\n（258)羂（juǎn卷）：用绳索绊取野兽。騕褭（yǎoniǎo咬鸟）：神马名，传说能日行千里。\n（259）封豕：大野猪。\n（260）箭不苟害：指每箭必射中要害，而不是胡乱将猎物射伤即可。\n（261）解：分解，分开。脰（dòu豆）：颈项。\n（262）乘（shèng胜）舆：皇\n上乘坐的车。此指皇上。弭节：驻节，停车。\n（263）睨：视。部曲：指参加围猎的队伍。\n（264）变态：指各种各样的形态。\n（265）侵淫促节：逐渐加快行驶的速度。\n（266）儵夐（shūxiòng抒兄去声）：忽然远去的样子。儵，同“倏”。\n（267）流离：四散，即冲散。轻禽：指飞鸟。轻，轻捷。\n（268）蹴履：即践踏。狡兽：猛兽。狡，健。\n（269）轊（wèi卫）白鹿：用车轴头挂住白鹿。轊，车轴头。\n（270）捷：疾取。\n（271）轶赤电：形容车骑疾速。轶，超过。\n（272）遗光耀：也极言车骑迅疾。遗，指抛在后面。\n（273）怪物：指奇珍怪兽。\n（274）出：超出。宇宙：指天地之间的空间。天地四方称“宇”，古往今来称“宙”。\n（275）蕃弱：传说中夏后氏良弓名。\n（276）满：拉弓到箭头称为满。白羽：指用白色翎毛作尾羽的箭。\n（277）游枭：各处游荡的枭。枭，一名枭羊，兽名。一说即狒狒。\n（278）栎（lì力）：击打。蜚遽：神兽名，鹿头龙身。\n（279）择肉：指选择肥胖的。一说选择禽兽身上可射的地方。\n（280）“先中”句：谓先指明要射中什么地方，然后射中预定目标。\n（281）艺：箭靶。这里指射的目标。殪（yì意）仆：指猎物被射死倒下。\n（282)扬节而上浮：旌节飞扬上游于太空。\n（283）骇猋（biāo标）：即惊风，疾风。猋，通“飙”，从下向上刮的疾风。\n（284）乘：升，登。虚无：指天空。\n（285）躏：践踏。玄鹤：黑色的鹤。\n（286）乱：指使其行列混乱。昆鸡：同“鹍鸡”，鸟名，形状似鹤，赤喙长颈，全身黄白色。\n（287）遒：迫，追捕。孔鸾：孔雀和鸾鸟。\n（288）促：捕捉。鵔鸃：即赤雉，毛五彩，有花纹。\n（289）拂：击。翳鸟：传说中的大鸟，毛五彩，飞起能遮蔽一乡。\n（290）捎：同“箾”，以竹竿击打。\n（291）捷：取。鹓雏：凤凰一类的鸟。\n（292）揜：同“掩”，捕捉。焦明：西方鸟名，也属凤凰一类。又作“焦朋”。\n（293）消遥：同“逍遥”，悠游自得的样子。襄羊：同“倘佯”，自由俳徊的样子。\n（294）降集：停留。降，下降。集，止。北纮：指极北边的地方。古代认为地的周围有八泽，八泽之外有八纮，北纮称为委羽。纮，维。\n（295）率乎：直指的样子。直指：一直往前。\n（296）晻乎：迅速的样子。反乡：即“反向”，返回。\n（297）“蹷（jué厥）石阙”四句：指经过了石阙、封峦、□鹊、露寒四个观。这四个观是汉武帝建元间所建，在甘泉宫外。蹷，踏过。望，探看。\n（298）下：住。棠梨：宫名，在甘泉宫东南三十里。\n（299）宜春：宫名，在陕西杜县以东。\n（300）宣曲：宫名，在昆明池以西（今陕西西安市西南）。\n（301）濯鹢：指划船。濯，通“櫂”，摇船的工具。鹢，船头有鹢鸟图形装饰的船。牛首：池名，在上林苑西边（今陕西西安市西北）。\n（302）龙台：观名，在今陕西户县东\n北，靠近渭水。\n（303）掩：止息。细柳：观名，在昆明池南面（今陕西西安市西南）。\n（304）勤略：辛勤巡查。略，巡行。\n（305）均：比较多少。得获：获得。\n（306）徒车：指士卒和车骑。徒，车前步行的士卒。轥（lìn吝）：践踏。轹（lì历）：碾压。\n（307)步骑：指步兵骑士。蹂若：践踏。\n（308）蹈籍：踏踩。籍，通“藉”。\n（309）穷极倦谻（jù剧）：走投无路，疲惫不堪。谻，极度疲惫。\n（310）惊惮詟（zhé折）伏：惊恐而不敢活动。詟，同“慑”，恐惧。\n（311）他他籍籍：纵横交错的样子。\n（312）掩平：遮蔽了平原。弥泽：填满了大泽。此句极言死亡禽兽之多。\n（313）懈怠：疲劳懒怠。此指射猎活动后放松。\n（314）颢天之台：上接天宇的高台。颢天，同“昊天”。\n（315）张：陈设。轇輵之□：指空旷辽阔的屋子。轇輵，寥廓。□，同“宇”，屋宇。\n（316）石：古代重量单位，一石重一百二十斤。\n（317）虡（jù巨）：悬挂钟磬的木架。\n（318）翠华之旗：以翠羽装饰的旗子。\n（319）灵鼍（túo驼）之鼓：用鼍皮做成的鼓。鼍，鳄鱼一类的动物。\n（320）陶唐氏：即唐尧。\n（321）葛天氏：古代部落首领，据说其善歌。\n（322）巴渝宋蔡：指这些地方的歌舞。巴、渝，今四川一带。宋、蔡，今河南一带。\n（323）淮南：诸侯国名，相当于今安徽淮河以南、和县以北地区，治所寿春。干遮：曲名。\n（324）文成：县名，当今河北卢龙县境，其地人善歌。颠歌：指滇地的乐歌。颠，同“滇”，即今云南一带，汉时属西南夷的一部分。\n（325）族居：聚集在一起。递奏：互相交替地演奏。\n（326）铿鎗：同“铿锵”，指钟声。闛鞈（tángtà唐踏）：指鼓声。\n（327）洞心：响彻内心。\n（328）韶：虞舜时乐名。濩：商汤时乐名。武：周武王时乐名。象：周公旦时乐名。\n（329）阴淫案衍：指过度而无节制的音乐。\n（330）鄢郢：都是楚地名。缤纷：指舞蹈时交杂错落的样子。\n（331）激楚：指楚地的歌曲。结风：指歌曲结尾馀音悠长。\n（332）俳优：古代表演杂戏等以供人取乐的人。侏儒：矮人。此指侏儒中任优伶、乐师者。\n（333）狄鞮（dī低)：西方部族名。倡：女乐工。\n（334）丽靡烂漫：美好华丽、色彩鲜明。\n（335）靡曼：指美人的细腻润泽，姿态美妙。\n（336）青琴：传说中的古代神女。宓（fú伏）妃：传说中的伏羲氏之女，溺死于洛水，遂为洛水之神。\n（337）妖冶：美好。娴都：美丽典雅。\n（338）靓（jìng静）妆：指以粉黛妆扮。刻饰：指修整头发。以胶刷鬓发，使其整齐如刻画。\n（339）便嬛（huán环）：轻盈俏丽的样子。绰约：柔婉的样子。\n（340）柔桡嫚嫚：指身体柔软苗条、姣好多姿。桡，曲。\n（341）妩媚：容貌美丽，悦人心意。孅弱：指身体轻细柔软。\n（342）独茧：一个蚕茧的丝。指丝线颜色纯净一致。褕（yú\n俞）：短衣。绁：同“袣（yì异）”，衣袖。此皆指衣服。\n（343）眇：美好，形容下文“阎易”、“恤削”。阎易：衣长的样子。恤削：指衣服线条整齐清晰。\n（344）便姗嫳（piè撇去声）屑：衣服翩翩飘动的样子。\n（345）沤郁：郁积，指香气浓盛。\n（346）淑郁：形容香气浓厚、美好。\n（347）宜笑：微露牙齿的笑。的皪（lì历）：指牙齿鲜白的样子。\n（348）连娟：又弯又细的样子。\n（349）微睇：微微顾盼。睇，流盼。绵藐：指眼光的绵长悠远。\n（350）色授魂与：指女子以颜色、精神勾引人。一说“色授”是指女子以色勾引男子，“魂与”，是指男子与之精神相应。\n（351）心愉于侧：指倾心于侧。愉，通“输”，心输，即倾心。\n（352）酒中：饮酒到一半时。\n（353）芒然：怅然。芒，通“茫”。\n（354）亡：失。\n（355）览听馀闲：指处理政事之后的空闲时间。\n（356）无事弃日：指没有政事，只是虚度时日。弃，抛弃、闲置。\n（357）“顺天道”句：指顺应天道在秋末冬初打猎。\n（358)此：指上林苑。\n（359）后叶：后世。靡丽：奢华。\n（360）往而不返：指一味追求奢侈，不知回头。\n（361）继嗣：继承者，后嗣。创业垂统：创立基业，留传后代。\n（362）农郊：农田。郊，田。\n（363）萌隶：农夫。萌，通“氓”。\n（364）隤（tuí颓）墙填堑：谓把上林苑四周的墙推倒，把壕沟填平。隤，毁坏。\n（365）实陂池：指在陂池中放养鱼类。勿禁：指让百姓随意打鱼。\n（366）“虚宫馆”句：指不再使用上林苑中的宫馆。虚宫馆，使宫馆空虚。仞，满。\n（367）出德号：指发布实行德政的命令。\n（368）革正朔：改革历法。正，指每年的正月。朔，指每月的初一。古代封建王朝新建立之时，总要易服色，革正朔，以表示与前个朝代不同。\n（369）更始：指重新开始。更，变更。\n（370）历：选择。斋戒：古人在举行典礼之前，为了表示恭敬，不饮酒，不吃荤，不宿内寝，称为斋戒。\n（371）袭：穿。\n（372）法驾：天子车驾的一种，用于通常的行动，由奉车郎御车，侍中骖乘，属车四十六乘。\n（373）鸣玉鸾：指车辆行走时发出和谐悦耳的铃声。鸾，马辔上的铃。\n（374）六艺：即《诗》、《书》、《礼》、《乐》、《易》、《春秋》六经。此句是说遍读六经。\n（375）涂：通“途”。\n（376）《春秋》之林：指《春秋》中包含的众多的经验道理。\n（377）射：指行射礼。《狸首》：古逸诗的篇名。古代诸侯举行射礼时，奏《狸首》乐章。\n（378）《驺虞》：《诗经·召南》中的一篇。古代天子举行射礼时，奏《驺虞》乐章。驺虞，相传是一种动物，性仁慈。\n（379）弋玄鹤：指表演弋射玄鹤的舞蹈。弋，用弓缴来射。玄鹤，黑色的鹤，古代认为它是一种瑞鸟。\n（380）干戚：盾和斧。相传舜舞干戚，感服了南方的有苗氏。后演化为舞干戚的大夏舞。\n（381）云䍐（hǎn罕）：本指捕捉禽兽的网，此指旌旗。古注说，云䍐用以猎兽，今载之于车，象征“捕群雅”。\n（382）揜：罩住，捕。这里指收罗。群雅：指众多的有才能的人。雅，既指才俊之士，又同“鸦”，语义双关。\n（383）悲《伐檀》：谓汉天子因读《伐檀》而兴悲。《伐檀》，《诗经·魏风》篇名。旧说这首诗是讽刺贤者不遇明主。\n（384）乐乐胥：谓汉天子因读到“乐胥”的诗句而高兴。《诗经·小雅·桑扈》：“君子乐胥，受天之祜。”郑玄笺：“胥，有才智之名也。祜，福也。王者乐臣下有才智，知文章，则贤人在位，庶官不旷，政和而民安，天予之以福禄。”\n（385）修容：修饰容仪。礼园：指《礼》的规定范围。\n（386）翱翔：往来游观。书圃：指《尚书》的规定范围。\n（387）《易》：指六经之一的《易经》。古人认为《易》包含有一些洁静微妙的道理。\n（388)明堂：古代天子朝见诸侯的地方。此指处理政事、朝见大臣的地方。\n（389）清庙：太庙，天子祭祖先之庙。\n（390）靡不受获：没有人不受到天子的恩泽。获，猎获物，此处指恩惠。\n（391）说：通“悦”。\n（392）“乡风”二句：谓像风行水流一样，百姓乐意服从天子。乡，通“向”。\n（393）芔（huì卉）然：勃然兴起的样子。兴道：指按道行事。迁义：指逐渐接近义。迁，登，接近。\n（394）错：通“措”，弃置。\n（395）“德隆”句：谓德高过了三王。隆，高，盛。三王，即夏禹，商汤，周文王、周武王。\n（396）羡：溢，超过。五帝：指黄帝、颛顼、帝喾、尧、舜。\n（397）罢：通“疲”。作动词用。\n（398）抏（wán完）：损耗。精：指精力。\n（399）繇：通“由”，从。此句指仁德之人不照这个样子做。\n（400）囿居九百：极言苑囿之广。\n（401）细：微小。\n（402）乐万乘之侈：喜好天子的奢华。万乘，代指天子。\n（403）被其尤：遭受那种做法带来的祸殃。尤，祸患。\n（404）愀然改容：改变了脸色。愀然，脸色改变的样子。\n（405）超若自失：怅然若失。超，怅惘，惆怅。若，义同“然”。\n（406）逡巡：向后退。避席：古人席地而坐，有所敬则离坐而起，谓之避席。\n（407）鄙人：粗鄙的人，谦称。固陋：指见识狭隘浅陋，不合于礼义。\n（408）忌讳：指不应当说、不应当做的事。▲', poem_appreciation = '《上林赋》是《子虚赋》的姊妹篇。据《史记》记载，《子虚赋》写于梁孝王门下，《上林赋》写于武帝朝廷之上，是司马相如最著名的作品。《上林赋》以夸耀的笔调描写了汉天子上林苑的壮丽及汉天子游猎的盛大规模，歌颂了统一王朝的声威和气势。在写作上，它充分体现了汉大赋铺张夸饰的特点，规模宏大，叙述细腻。\n\n　　《上林赋》作为司马相如最重要的代表作，是文学史上第一篇全面体现汉赋特色的大赋。在内容上，它以宫殿、园囿、田猎为题材，以维护国家统一、反对帝王奢侈为主旨，既歌颂了统一大帝国无可比拟的声威，又对最高统治者有所讽谏，开创了汉代大赋的一个基本主题。在形式上，它摆脱了模仿楚辞的俗套，以“子虚”、“乌有先生”、“无是公”为假托人物，设为问答，放手铺写，结构宏大，层次严密，语言富丽堂皇，句式亦多变化，加上对偶、排比手法的大量使用，使全篇显得气势磅礴，形成铺张扬厉的风格，确立了汉代大赋的体制。鲁迅先生指出：“盖汉兴好楚声，武帝左右亲信，如朱买臣等，多以楚辞进，而相如独变其体，益以玮奇之意，饰以绮丽之辞，句之短长，亦不拘成法，与当时甚不同。”（《汉文学史纲要》）这就概括了司马相如在文体创新方面的非凡成就。正是这种成就，使司马相如成为当之无愧的汉赋奠基人。', poem_tags = '写景,叙事' WHERE poem_title = '上林赋' AND poem_author = '司马相如';
UPDATE edu_poem SET poem_tags = '送别,豪迈,爱国' WHERE poem_title = '送紫岩张先生北伐' AND poem_author = '岳飞';
UPDATE edu_poem SET poem_translation = '离家远游之人试着换上了单薄的春衣，枝头的桃花已凋谢，野生的梅子已经发酸。\n奇怪的是忽然一晚蛙鸣声停止了，原来是东风又起，带来了数日的寒冷。', poem_notes = '游子：指离家远游之人。\n春衫：单薄的春装。\n试单：尝试着换上单衣。\n怪来：惊疑。\n歇：停，这里指蛙畏寒而声息全无。\n作：起。', poem_tags = '古诗三百首,羁旅' WHERE poem_title = '绝句' AND poem_author = '吴涛';
UPDATE edu_poem SET poem_translation = '伫立漫长的淮河岸边极目望远，关塞上的野草丛茂是平阔的荒原。北伐的征尘已暗淡，寒冷的秋风在劲吹，边塞上的静寂悄然。我凝神伫望，心情黯淡。追想当年的中原沧陷，恐怕是天意运数，并非人力可扭转；在孔门弟子求学的洙水和泗水边，在弦歌交秦的礼乐之邦，也已变成膻腥一片。隔河相望是敌军的毡帐，黄昏落日进牛羊返回圈栏，纵横布置了敌军的前哨据点。看金兵将令夜间出猎，骑兵手持火把照亮整片平川，胡笳鼓角发出悲壮的声音，令人胆战心寒。\n想我腰间弓箭，匣中宝剑，空自遭了 虫尘埃的侵蚀和污染，满怀壮志竟不得施展。时机轻易流失，壮心徒自雄健，刚暮将残。光复汴京的希望更加渺远。朝廷正推行礼乐以怀柔靖远，边境烽烟宁静，敌我暂且休兵。冠服乘车的使者，纷纷地奔驰匆匆，实在让人羞愧难以为情。传说留下中原的父老，常常盼望朝廷，盼望皇帝仪仗，翠盖车队彩旗蔽空，使得行人来到此地，一腔忠愤，怒气填膺，热泪倾洒前胸。', poem_notes = '六州歌头：词牌名。\n长淮：指淮河。宋高宗绍兴十一年（1141年）与金和议，以淮河为宋金的分界线。此句即远望边界之意。\n关塞莽然平：草木茂盛，齐及关塞。谓边备松驰。莽然，草木茂盛貌。\n“征尘暗”三句：意谓飞尘阴暗，寒风猛烈，边声悄然。此处暗示对敌人放弃抵抗。\n黯销凝：感伤出神之状。黯，精神颓丧貌。\n当年事：指靖康二年（1127年）中原沧陷的靖康之变。\n殆：似乎是。\n“洙泗上”三句：意谓连孔子故乡的礼乐之邦亦陷于敌手。洙、泗：鲁国二水名，流经曲阜（春秋时鲁国国都），孔子曾在此讲学。弦歌地：指礼乐文化之邦。《论语·阳货》：“子之武城，闻弦歌之声。”邢昺疏：“时子游为武城宰，意欲以礼乐化导于民，故弦歌。”膻（shān），腥臊气。\n毡乡：指金国。北方少数民族住在毡帐里，故称为毡乡。\n落日牛羊下：定望中所见金人生活区的晚景。《诗经·王风·君子于役》：“日之夕矣，羊牛下来。”\n区（ōu）脱纵横：土堡很多。区脱，匈奴语称边境屯戍或守望之处。\n“名王”二句：写敌军威势。名王：此指故方将帅。宵猎：夜间打猎。骑火：举者火把的马队。\n埃蠹（dù）：尘掩虫蛀。\n零：尽。\n渺神京：收复京更为渺茫。神京，指北宋都诚汴京。\n干羽方怀远：用文德以怀柔远人，谓朝廷正在向敌人求和。干羽，干盾和翟羽，都是舞蹈乐具。\n静烽燧（suì）：边境上平静无战争。烽燧，即烽烟。\n“冠盖”三句：冠盖：冠服求和的使者。驰鹜（wù）：奔走忙碌，往来不绝。若为情：何以为情，犹太今之“怎么好意思”。\n翠葆霓旌：指皇帝的仪仗。翠葆，以翠鸟羽毛为饰的车盖。霓旌，像虹霓似的彩色旌旗。\n填膺：塞满胸怀。', poem_appreciation = '此词里描写了沦陷区的荒凉景象和敌人的骄横残暴，抒发了反对议和的激昂情绪。\n\n　　上阕，描写江淮区域宋金对峙的态势。“长淮”二字，指出当时的国境线，含有感慨之意。自绍兴十一年十一月，宋“与金国和议成，立盟书，约以淮水中流画疆”（《宋史·高宗纪》）。昔日曾是动脉的淮河，如今变成边境。这正如后来杨万里《初入淮河》诗所感叹的：“人到淮河意不佳”，“中流以北即天涯！”国境已收缩至此，只剩下半壁江山。极目千里淮河，南岸一线的防御无屏障可守，只是莽莽平野而已。江淮之间，征尘暗淡，霜风凄紧，更增战后的荒凉景象。\n\n　　“黯销凝”一语，揭示出词人的壮怀，黯然神伤。追想当年靖康之变，二帝被掳，宋室南渡。谁实为之？天耶？人耶？语意分明而着以“殆”、“非”两字，便觉摇曳生姿。洙、泗二水经流的山东，是孔子当年讲学的地方，如今也为金人所占，这对于词人来说，不禁从内心深处激起震撼、痛苦和愤慨。自“隔水毡乡”直贯到歇拍，写隔岸金兵的活动。一水之隔，昔日耕稼之地，此时已变为游牧之乡。帐幕遍野，日夕吆喝着成群的牛羊回栏。“落日”句，语本于《诗经·王风·君子于役》，更应警觉的是，金兵的哨所纵横，防备严密。尤以猎火照野，凄厉的笳鼓可闻，令人惊心动魄。金人南下之心未死，国势仍是可危。\n\n　　下阕，抒写复国的壮志难酬，朝延当政者苟安于和议现状，中原人民空盼光复，词情更加悲壮。换头一段，词人倾诉自己空有杀敌的武器，只落得尘封虫蛀而无用武之地。时不，徒具雄心，却等闲虚度。绍兴三十一年的秋冬，孝祥闲居往来于宣城、芜湖间，闻采石大捷，曾在《水调歌头·和庞佑甫》一首词里写道：“我欲乘风去，击楫誓中流。”但到建康观察形势，仍感报国无门。所以“渺神京”以下一段，悲愤的词人把词笔犀利锋鋩直指偏安的小朝廷。汴京渺远，何时光复！所谓渺远，岂但指空间距离之遥远，更是指光复时间之渺茫。这不能不归罪于一味偷安的朝廷。“干羽方怀远”活用《尚书·大禹谟》“舞干羽于两阶”故事。据说舜大修礼乐，曾使远方的有苗族来归顺。词人借以辛辣地讽刺朝廷放弃失地，安于现状。所以下面一针见血揭穿说，自绍兴和议成后，每年派遣贺正旦、贺金主生辰的使者、交割岁币银绢的交币使以及有事交涉的国信使、祈请使等，充满道路，在金受尽屈辱，忠直之士，更有被扣留或被杀害的危险。即如使者至金，在礼节方面仍须居于下风。岳珂《桯史》记载：“……礼文之际，多可议者，而受书之仪特甚。逆亮（金主完颜亮）渝平，孝皇（宋孝宗）以奉亲之故，与雍（金世宗完颜雍）继定和好，虽易称叔侄为与国，而此仪尚因循未改，上（孝宗）常悔之。”这就是“若为情”——何以为情一句的事实背景，词人所以叹息痛恨者。“闻道”两句写金人统治下的父老同胞，年年盼望王师早日北伐收复天地。“翠葆霓旌”，即饰以鸟羽的车盖和彩旗，是皇帝的仪仗，这里借指宋帝车驾。词人的朋友范成大八年后使金，过故都汴京，有《州桥》一诗：“州桥南北是天街，父老年年等驾回。忍泪失声询使者，几时真有六军来！”曾在陕西前线战斗过的陆游，其《秋夜将晓出篱门迎凉有感》一诗中也写道：“遗民泪尽胡尘里，南望王师又一年！”皆可印证。这些爱国诗人、词人说到中原父老，真是同深感慨。作者举出中原人民向往故国，殷切盼望复国的事实，就更深刻地揭露偏安之局是多么违反人民意愿，更使人感到无比气愤的事。结尾三句顺势所至，更把出使者的心情写出来。孝祥伯父张邵于建炎三年使金，以不屈被拘留幽燕十五年。任何一位爱国者出使渡淮北去，就都要为中原大地的长期不能收复而激起满腔忠愤，为中原人民的年年伤心失望而倾泻出热泪。“使行人到此”一句，“行人”或解作路过之人，亦可通。北宋刘潜、李冠两首《六州歌头》，一咏项羽事，一咏唐玄宗、杨贵妃事，末皆用此句格。刘作曰“遣行入到此，追念痛伤情，胜负难凭”；李作曰“使行人到此，千古只伤歌，事往愁多”。孝祥此语大概亦袭自前人。\n\n　　纵观全词，上阕又可各分为三小段，作者在章法上也颇费心思。宴会的地点在建康，词人唱出“长淮望断”，他不让听者停留在淮河为界的苦痛眼前现实，而且紧接着以“追想当年事”一语把大家的心绪推向北方更广大的被占区，加重其山河破碎之感。这时又突然以“隔水毡乡”提出警告，把众宾的注意力再引回到“胡儿打围涂塘北，烟火穹庐一江隔”（张孝祥《和沈教授子寿赋雪》诗句）的现实中来。一阕之内，波澜迭起。换头以后的写法又有变化。承上阕指明的危急形势，首述恢复无期、报国无门的失望；继斥朝廷的忍辱求和；最后指出连过往的人（包括赴金使者）见到中原遗老也同样悲愤。这样高歌慷慨，愈转愈深，不仅充分表达了词人的无限悲愤之情，更有力地激发起人们的爱国热情。据南宋无名氏《朝野遗记》说：“歌阕，魏公（张浚）为罢席而入”，可见其感人之深。\n\n　　这首词的强大生命力就在于词人“扫开河洛之氛祲，荡洙泗之膻腥者，未尝一日而忘胸中”的爱国精神。正如词中所显示，熔铸了民族的与文化的、现实的与历史的、人民的与个人的因素，是一种极其深厚的爱国主义精神。所以一旦倾吐为词，发抒忠义就有“如惊涛出壑”的气魄（南宋滕仲固跋郭应祥《笑笑词》语，据称于湖一传而得吴镒，再传而得郭）。同时，《六州歌头》篇幅长，格局阔大。多用三言、四言的短句，构成激越紧张的促节，声情激壮，正是词人抒发满腔爱国激情的极佳艺术形式。词中，把宋金双方的对峙局面，朝廷与人民之间的尖锐矛盾，加以鲜明对比。多层次、多角度地展示了那个时代的宏观历史画卷，强有力地表达出人民的心声。就像杜甫诗历来被称为诗史一样，这首《六州歌头》，也完全可以被称为词史。', poem_tags = '宋词三百首,豪放,爱国,壮志' WHERE poem_title = '六州歌头·长淮望断' AND poem_author = '张孝祥';
UPDATE edu_poem SET poem_translation = '梅花稀疏，色彩轻淡，冰雪正在消融，春风吹拂暗暗换了年华。想昔日金谷胜游的园景，铜驼街巷的繁华，趁新晴漫步在雨后平沙。总记得曾误追了人家香车，正是柳絮翻飞蝴蝶翩舞，引得春思缭乱交加。柳荫下桃花小径，乱纷纷将春色送到万户千家。\n西园夜里宴饮，乐工们吹奏起胡笳。缤纷高挂的华灯遮掩了月色，飞驰的车盖碰损了繁花。花园尚未凋残，游子却渐生霜发，重来旧地事事感慨吁嗟。暮霭里一面酒旗斜挂。空倚楼纵目远眺，时而看见栖树归鸦。见此情景，我油然而生归隐之心，神思已暗自随着流水奔到天涯。', poem_notes = '梅英：梅花。\n冰澌（sī）：冰块流融。溶泄：溶解流泄。\n芳思：春天引起的情思。\n桃蹊：桃树下的小路。\n西园：即金谷园。笳：胡笳，古代西北少数民族的一种管乐器。\n飞盖：飞驰车辆上的伞盖。\n兰苑：美丽的园林，亦指西园。\n烟暝：烟霭弥漫的黄昏。', poem_appreciation = '此词不止于追怀过去的游乐生活，还有政治失意之慨叹其中。\n\n　　上片起头三句，写初春景物：梅花渐渐地稀疏，结冰的水流已经溶解，东风的煦拂之中，春天悄悄地来了。“暗换年华”，既指眼前自然界的变化，又指人事沧桑、政局变化。此种双关的今昔之感，直贯结句思归之意。\n\n　　“金谷俊游”以下十一句，都是写的旧游，实以“长记”两字领起，“误随车”固“长记”之中，即前三句所写金谷园中、铜驼路上的游赏，也同样内。但由于格律关系就把“长记”这样作为领起的字移后了。“金谷”三句所写都是欢娱之情，纯为忆旧。“长记”之事甚多，而这首词写的只是两年前春天的那一次游宴。金谷园是西晋石崇的花园，洛阳西北。铜驼路是西晋都城洛阳皇宫前一条繁华的街道，以宫前立有铜驼而得名。故人们每以金谷、铜驼代表洛阳的名胜古迹。但词里，西晋都城洛阳的金谷园和铜驼路，却是用以借指北宋都城汴京的金明池和琼林苑，而非实指。与下面的西园也非实指曹魏邺都（今河北临漳西）曹氏兄弟的游乐之地，而是指金明池（因为它位于汴京之西）同。这三句，乃是说前年上已，适值新晴，游赏幽美的名园，漫步繁华的街道，缓踏平沙，非常轻快。\n\n　　因忆及“细履平沙”故连带想起当初最令人难忘的“误随车”那件事来。“误随车”出韩愈《游城南十六首》的《嘲少年》：“直把春偿酒，都将命乞花。只知闲信马，不觉误随车。”而李白的《陌上赠美人》：“白马骄行踏落花，垂鞭直拂五云车。美人一笑搴珠箔，遥指红楼是妾家。”以及张泌的《浣溪沙》：“晚逐香车入凤城，东风斜揭绣帘轻，慢回娇眼笑盈盈。消息未通何计是？便须佯醉且随行，依稀闻道太狂生。”则都可作随车的注释。尽管那次“误随车”只是无心之误，但却也引起了词人温馨的遐思，使他对之长远地保持着美好的记忆。“正絮翻蝶舞”四句，写春景。“絮翻蝶舞”、“柳下桃蹊”，正面形容浓春。春天的气息到处洋溢着，人这种环境之中，自然也就“芳思交加”，即心情充满着青春的欢乐了。此处“乱”字下得极好，它将春色无所不，乱哄哄地呈现着万紫千红的图景出色地反映了出来。\n\n　　换头“西园”三句，从美妙的景物写到愉快的饮宴，时间则由白天到了夜晚，以见当时的尽情欢乐。西园借指西池。曹植的《公宴》写道：“清夜游西园，飞盖相追随。明月澄清景，列宿正参差。”曹丕《与吴质书》云：“白日既匿，继以朗月。同乘并载，以游后园。舆轮徐动，参从无声；清风夜起，悲笳微吟。”又云：“从者鸣笳以启路，文学托乘于后车。”词用二曹诗文中意象，写日间外面游玩之后，晚间又到国夫人园中饮酒、听乐。各种花灯都点亮了，使得明月也失去了她的光辉；许多车子园中飞驰，也不管车盖擦损了路旁的花枝。写来使人觉得灯烛辉煌，车水马龙，如目前。“碍”字和“妨”字，不但显出月朗花繁，而且也显出灯多而交映，车众而并驰的盛况。把过去写得愈热闹就愈衬出现的凄凉、寂寞。\n\n　　“兰苑”二句，暗中转折，逼出“重来是事堪嗟”，点明怀旧之意，与上“东风暗换年华”相呼应。追忆前游，是事可念，而“重来”旧地，则“是事堪嗟”，感慨至深。此时酒楼独倚，只见烟暝旗斜，暮色苍茫，既无飞盖而来的俊侣，也无鸣笳夜饮的豪情，极目所至，已经看不到絮、蝶、桃、柳这样一些春色，只是“时见栖鸦”而已。这时候，宦海风波，仕途蹉跌，也使得词人不得不离开汴京，于是归心也就自然而然地同时也是无可奈何地涌上心头。\n\n　　此词的艺术特色主要是：其一，结构别具一格，上片先写今后写昔，下片先承上写昔后再写今，忆昔部分贯通上下两片。其二，大量运用对比手法，以昔衬今，极富感染力。', poem_tags = '宋词三百首,春天,追忆,抒情' WHERE poem_title = '望海潮·洛阳怀古' AND poem_author = '秦观';
UPDATE edu_poem SET poem_translation = '长久的相思啊，长久的相思。若问这相思何时是尽头，除非是在相见之时。\n长久的相思啊，长久的相思。这相思之情说给谁听呢，薄情寡义的人是不能体会的。', poem_notes = '长相思：词牌名，唐教坊曲名。\n甚（shèn）了期：何时才是了结的时候。\n似（sì）：给与。\n浅情人：薄情人。', poem_appreciation = '此词纯用民歌形式，上下片均以“长相思”迭起，上片言只有相见才得终了相思之情；下片言由于不得相见，相思之情无处诉说，以浅情人不能理解自己的心情反衬自己一往而情深。词的上片，一气流出，情溢乎辞，不加修饰。“若问”两句，自问自答，痴人痴语。要说“相见”是解决“相思”的唯一办法，这纯是痴语，痴心，可是，小晏却认认真真地把它说了出来，正是如黄庭坚《小山词序》所云“其痴亦自绝人”。\n\n　　结句非同凡响，抒写了比相思不相见更大的悲哀。“说似谁”，犹言说与谁、向谁说。纵使把相思之情说了出来，那浅情的人儿终是不能体会。浅情是深情的对面，多情的小晏却总是碰到那样的人，可是，当那人交暂情浅，别后又杳无音信，辜负了自己的刻骨相思时，词人依然是一往情深，不疑不恨，只是独自伤心而已。下片四句，以“浅情人”反衬小晏相思苦恋之情，无奈和遗憾。\n\n　　此词为作者词中别调，语极浅近，情极深挚，在朴直中自饶婉曲之致，缠绵往复，姿态多变，回肠荡气，音节尤美。用对比的手法突出词人用情之深。', poem_tags = '宋词精选,相思' WHERE poem_title = '长相思·长相思' AND poem_author = '晏几道';
UPDATE edu_poem SET poem_translation = '阳关与故国相隔万里之遥，年年盼望却至今不能南归。\n只有黄河岸边南来的大雁，秋天一到仍可以自由南飞。', poem_notes = '庾信有《咏怀二十七首》，这首诗篇原列第七首。周尚书：即周弘正（496—574），字思行，汝南安城（今河南平舆县）人，周颚之孙。梁元帝时为左户尚书，魏平江陵，逃归建业。\n阳关：在今甘肃敦煌市西，汉朝时地属边陲，这里代指长安。万里：指长安与南朝相去甚远。\n一人：庾（yǔ）信自指。\n河：指黄河。\n南向：向着南方。', poem_appreciation = '诗的开头写自己独留长安不得南返的悲哀。阳关，在今甘肃敦煌县西南，自古与玉门关同为通往西域的必经之地。庾信在这里是借用，因为阳关已成了“大道”的代称，如同我们把“阳关道”与“独木桥”对举。诗中的“阳关万里道”是喻指长安与金陵之间的交通要道。下旬“不见一人归”的“一人”指庾信自己而言，这二句说在长安至金陵的阳关大道上，有多少南北流离之士已经归还故国了。只有我一人不能归故土，这是令人伤心的事。\n\n　　“惟有河边雁，秋来南向飞”两句，“河边雁”喻指友人周弘正，这不是眼前的实景，而是一种虚拟，是庾信的内心感觉借助外物的一种表现形式。前已指出，庾、周分别是在早春，这时不可能出现秋雁南飞的实景，即使九尽春回，也只能看到鸿雁北去的景象。这两句诗有两层含义：一是把周弘正的返陈比作南归之雁，大有羡慕弘正回南之意；二是鸿雁秋去春来，来去自由，而自己却丧失了这种自由，以见自己不如鸿雁。沈德潜评这首诗说“从子山时势地位想之，愈见可悲。”这是知人论世之见，于诗歌鉴赏尤为重要。\n\n　　此诗表现手法有两个特点：一是借代手法，开头即用“阳关万里道”借指长安至金陵的交通大道。此种手法增加了诗的含蓄美。另一艺术手法是虚拟，“惟有河边雁，秋来南向飞”两句便是虚拟的景物，这种带象喻性的虚拟，使诗歌形象的含蕴更加丰富。可以想见，庾信在长安看到秋去春来的大雁已经二十多个春秋了，他自己不如大雁来去自由的感受已经隐藏多年了。送友人南归时，这种多年积淀在心头的情感一触即发，其内涵非三言两语所能说尽。只有细味庾信的良苦用心，才能欣赏此诗谋篇遣词之妙。', poem_tags = '送别,友情' WHERE poem_title = '重别周尚书' AND poem_author = '庾信';
UPDATE edu_poem SET poem_translation = '车马遥遥行远去到何方，追念你的行踪啊不能把你遗忘。\n你游历到哪里呢？是否西入秦地，我愿像影子跟随在你身旁。\n你在暗处时影子无法随身，希望你永远依傍着光亮。', poem_notes = '遥遥：言远去。\n洋洋：同“扬扬”，通假字，得意的样子。\n安：怎么，代词。\n阴：暗处。\n光：明处。', poem_tags = '爱情,相思' WHERE poem_title = '车遥遥篇' AND poem_author = '傅玄';
UPDATE edu_poem SET poem_translation = '注释 旧山：此指江油境内的大匡山，李白长期在此隐居读书。 染尘缨：沾满灰尘的帽子。 芳草平：即芳草坪。 篁（huáng）：竹子。 雉（zhì）：野鸡。 素鱼：白色的蛀虫。 素贞：指清操。这两句的意思是要发愤读书，养成青松一样高尚的品格。 三清：最高的神仙境界，比喻朝廷。', poem_tags = '冬天,写景,励志' WHERE poem_title = '冬日归旧山' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '见君如见晋人裴叔则，如行玉山之上，朗然照人。\n君之胸怀之阔大，如黄河落天，直入东海，当纳入其间矣；\n君之浩瀚，即使是河伯也不敢骑白鼋冒然横渡；君之高大，即使是金高南山买君一顾，也是值得的。\n君徘徊于六合之中，而无相知之人，如今看天上的浮云，即将飘然西去矣。', poem_notes = '裴十四：当是裴政，为李白好友，“竹溪六逸”之一。\n“朝见”二句：裴叔则，即晋朝的裴楷，尝任中书令，人称裴令公，仪容儁伟。《世说新语·容止》：“裴令公有俊容仪，脱冠冕，粗头乱服皆好。时人以为玉人。见者曰：‘见裴叔则如玉山上行，光映照人。’”此以裴叔则喻裴十四。\n“黄河”二句：以黄河入海喻裴十四胸怀的阔大。\n“身骑”句：《楚辞·九歌·河伯》：“乘白鼋兮逐文鱼，与女游兮河之渚。”此谓裴十四之才学心胸之深广，己不敢轻易测度。\n“金高”句：《列女传·节义传》：“郑子瞀者，楚成王之夫人也。初，成王登台，子瞀不顾。王曰：‘顾，吾又与女千金，而封若父兄。’子瞀遂不顾。子瞀曰：‘不顾，告以夫人之尊，示以封爵之重而后顾，则是妾贪贵乐利以忘义理也。’”此句谓须千金才可买裴十四之一顾，可见李白对友人裴十四推许之重。\n六合：上下四方谓之六合。', poem_appreciation = '裴十四，是一位超尘脱俗之士。他即将离别李白而西去，诗人作这首诗赠别。\n\n　　“裴叔则”，即晋朝的裴楷，尝任中书令，人称裴令公，仪容儁伟，“时人以为玉人，见者曰：‘见裴叔则如玉山上行，光映照人。’”（《世说新语·容止》）因为与主人公同姓诗人借裴叔则代指裴十四，言裴十四仪表堂堂，清朗如玉山，光彩照人。“黄河落天走东海，万里写入胸怀间。”黄河水从西部飞流直下流向中原，一泻万里，奔流入东海。此诗以奔腾的黄河水，象征裴十四宽阔宏大的襟怀。诗人倒插喻意在前，一笔点醒于后，手法变幻矫健。\n\n　　诗至五、六句，转入别意，叙写裴十四的遭际和他的不贪图富贵的性格。“身骑白鼋不敢度”，骑白鼋，语出屈原《九歌·河伯》“乘白鼋兮逐文鱼”。骑鼋的人，自然是裴十四。诗人用汹涌的水势，比喻社会环境的险恶和人生道路的艰难，裴十四身骑白鼋，面对汹涌的江水，不敢度过。“金高南山买君顾”句，借用郑子瞀的故事，见《列女传》卷五《节义传》，郑子瞀是楚成王的夫人，一日，与成王共登台，“王曰：‘顾，吾又与女千金，而封若父兄’，子瞀遂不顾。子瞀曰：‘不顾，告以夫人之尊，示以封爵之重而后顾，则是妾贪贵乐利以忘义理也’。”千金难买一顾，表现郑子瞀不贪贵乐利的品格；高比南山的金银，定然也难买裴十四的一顾，运用郑子瞀的典故，是为了盛赞裴十四的高贵品格。在那险恶的政治环境里，襟怀豪迈的裴十四不肯摧眉折腰，不肯为富贵而忘义；在“众人皆醉”的庸俗的黑暗社会里，裴十四难觅知音，“徘徊六合无相知”句，揭示了品格磊落的人不容于世的生活真实。结尾“飘若浮云且西去”，写裴十四即将西去，行踪飘忽不定，点到赠别上；以飘若浮云状其人，也为裴十四涂上了灵异脱俗的光彩，与全诗诗意相吻合。\n\n　　赠别诗，除了抒写离绪别情以外，还可以颂美离别者，描绘和刻画他们的形象、思想、品格、精神面貌，表达诗人对他们的钦慕、敬仰的感情。《赠裴十四》就是如此。李白用诗人的心灵，自己的品格和审美情趣，去感知对方，因此，在裴十四身上，读者看到了诗人的个性、气韵和精神，沈德潜说：“黄河落天二语，自道所得。”（《唐诗别裁集》）李白也亲历“身骑白鼋不敢度”的社会环境，也同样具有“金高南山”难买一顾的品格，也同样为世俗所不容，甚至到达“世人皆欲杀”（杜甫语）的地步。用颂美友人的诗赠给友人，引为知音，并在友人的精神风貌里，照见自己的襟怀和人格，是《赠裴十四》诗思想艺术的基本特征。', poem_tags = '赠别,赞颂,友人' WHERE poem_title = '赠裴十四' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '是谁在翻唱著凄切悲凉的乐府旧曲？风萧萧肃肃，雨潇潇洒洒，房里点燃的灯烛又短瘦了，一个凄苦孤独的一夜，在烛泪中逝去。\n不知道是什么事萦绕心怀，难以放下，醒时醉时都一样无聊难耐，就是梦里也没有到过谢桥。', poem_notes = '翻乐府：指填词。翻，按曲调作歌词。“乐府，本为汉代管理，祭祀、巡行、宫廷所用音乐的官署，亦称由官署采集来的民歌为乐府。后来将一切可以入乐的诗歌均称为乐府，容若词中取其广义，代指词。\n瘦尽句：意思是说眼望着灯花一点一点地烧尽散作灯花，彻夜不眠。\n萦怀抱：萦绕在心。', poem_appreciation = '纳兰的词中有一部分爱情词很朦胧，又无本事可寻，所以很难确定其所指。这首词便是这样。从词里所描写的情景来看，很像是对一位情人的深深怀念。通篇表达了一种百无聊赖的意绪。此阕《采桑子》无一字绮词艳语，而当中哀艳凄婉处又动人心魄，明说是“瘦尽灯花又一宵”，然而憔悴零落的又何止是灯花而已？不是不知何事萦怀抱，而是知道也无能为力。解得开的就不叫心结，放得下的又怎会今生今世意难平？纳兰容若这样深情的男子，哀伤如雪花，漫天飞舞不加节制，悼亡之作苏子之后有纳兰，可是容若之后谁还能做悼亡的凄凉曲？嫁了这样的男人不要想着白头到老，因为情深天也妒，注定要及早谢幕留爱情佳话来让人怀念。\n\n　　上阕侧重写景，刻画了萧萧雨夜，孤灯无眠，耳听着风声、雨声和着凄凉乐曲声的氛围与寂寞难耐的心情；\n\n　　下阕侧重写不眠之夜，孤苦无聊的苦情。词情凄惋徘恻，哀怨动人。下阕紧承上片“瘦尽灯花又一宵”，扣住彻夜未眠，进一步诉说自己百无聊赖的心绪：“不知何事萦怀抱，醒也无聊，醉也无聊。”不知道何事萦绕心怀？清醒时意兴阑珊；沉醉也难掩愁情。无论是清醒或是沉醉，那个人始终忘不掉。\n\n　　晏小山《鹧鸪天》词有“梦魂惯得无拘检，又踏杨花过谢桥”句，不知是何因缘，连一贯严谨的理学家程颐都拜倒其冶艳之下，极之赞许。容若此处更翻小山语意：“梦也何曾到谢桥？”纵能入梦，就真能如愿到访谢桥，与伊人重聚吗？相较于小山的梦魂自由不羁能踏杨花与伊人欢会的洒然，容若的孤苦凄凉斑然若现，以此句结全篇，语尽而意不尽，意尽而情不尽。\n\n　　整首词以清婉笔调写相思，相思也仿佛临风而动，萦人怀抱。风也萧萧，雨过天晴也萧萧，醒也无聊，醉也无聊，又是凄凉又是缠绵，并非雕琢之语。灯光瘦尽亦是人神伤消瘦，一字镂尽风神，尽得其妙。', poem_tags = '写景,抒情,爱情,相思' WHERE poem_title = '采桑子·谁翻乐府凄凉曲' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '时在红尘中见到月亮，心都能清静下来，何况是在这清秋时节的神仙洞府间？凝聚起来的光芒悠悠地象寒露坠落下来，而我此刻站在桃源的最高处。碧空之中没有一丝云彩，风也不见一缕，可以看见山上高高的松树和山下的流水。那些行动的物体全在视野之中，天那么高，地那么平，仿佛可以看见千万里之外：“少君”把我带到了玉坛之上，远远地施礼请仙人相见。云彩聚集，星斗挪动，仙乐奏响，让人肌骨寒肃。金色的霞光从东面渐渐升起，月轮西斜，仙影远去，我还在频频回望。只因为良辰美景难以再回来，以后到了中秋这天应该很惆怅吧！\n\n　　诗里面的“少君”是指能和神仙沟通的人。西汉武帝时有一个方士叫李少君，他自言见过神仙，能得长生不老之法，骗取了汉武帝的信任。以后人们就以“少君”代指游仙的向导。▲', poem_appreciation = '这首诗共十六句，每四句一韵，每一韵又是一个自然段落。第一段写桃源玩月，有月之景，有玩之情；第二段写八月十五夜色，以月光朗照下的天地山水反衬中秋之月；第三段浪漫畅想，写欲仙之感，由景及情，生发自然；最后一段从畅想中曳回，写日出月落，更就“绝景良时“抒发情感，略出桃源别后，难再重游一意。全诗景物随时而变，情调随景而移，有起伏跌宕之感。\n\n　　这首诗表面上可以归入游仙诗，把中秋之夜写得如梦如幻。尤其“凝光悠悠寒露坠，此时立在最高山”一句已经成为中秋时节人们常用的佳句。至于其他欣赏者怎么理解，可以说百人百解。有联系刘禹锡仕宦失意，解释后半部分是以仙宫比喻朝廷，盼望早日回归；也有把前半部分解释为用“寒露坠”代指人生祸福无常，说这是刘禹锡对人生的感慨之作。也许这种种理解，正好体现了“诗豪”作品多彩的艺术魅力。', poem_tags = '中秋节,游仙,抒怀' WHERE poem_title = '八月十五夜桃源玩月' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '都说春江景物芳妍，而三春欲尽，怎么会不感到伤感呢？拄着拐杖漫步江头，站在芳洲上，只看见柳絮如颠似狂，肆无忌惮地随风飞舞，轻薄不自重的桃花追逐流水而去。', poem_notes = '漫兴：随兴所至，信笔写来。\n芳洲：长满花草的水中陆地。\n颠狂：本指精神失常，引申为放荡不羁。', poem_tags = '写景,桃花,寓人,抒情,早教古诗100首' WHERE poem_title = '绝句漫兴九首·其五' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '注释 枕簟(diàn)：枕席。 玉漏：玉做的计时器。', poem_tags = '夏天,写雨' WHERE poem_title = '夏日杂诗' AND poem_author = '陈文述';
UPDATE edu_poem SET poem_tags = '古诗三百首,童谣,选官,制度' WHERE poem_title = '桓灵时童谣' AND poem_author = '佚名';
UPDATE edu_poem SET poem_tags = '宋词精选,冬天,写雪,写花,婉约' WHERE poem_title = '踏莎行·雪似梅花' AND poem_author = '吕本中';
UPDATE edu_poem SET poem_translation = '还记得当年刚刚进士登第时，春风得意，自以为前途似锦。可如今却是官职卑微身老天涯。分别十年以来我一事无成，白白辜负了当年新科进士的宴会。\n听说您要到的阆州有阆山可以通往神仙阆苑，可我登上高楼却望不到您的家。独处孤城寒日无端西斜，离别愁绪难以说尽，只见那经霜的红树连接着远处的红霞。', poem_notes = '临江仙：原为唐教坊曲，后用作词牌名，双调小令，共六十字。又名“谢新恩”“雁后归”“画屏春”“庭院深深”“采莲回”“想娉婷”“瑞鹤仙令”“鸳鸯梦”“玉连环”。\n金銮：帝王车马的装饰物。金属铸成鸾鸟形，口中含铃，因指代帝王车驾。这里指皇帝的金銮殿。前蜀毛文锡《柳含烟》词：“昨日金銮巡上苑，风亚舞腰纤软。”唱第：科举考试后宣唱及第进士的名次。唐元稹《酬翰林白学士代书一百韵》：“唱第听鸡集，趋朝忘马疲。”\n上国：指京师。南朝梁江淹《四时赋》：“忆上国之绮树，想金陵之蕙枝。”\n薄宦：卑微的官职。有时用为谦辞。晋陶潜《尚长禽庆赞》：“尚子昔薄宦，妻孥共早晚。”\n曲江花：代指新科进士的宴会。\n阆山：即阆风巅。山名，在昆仑之巅。《海内十洲记·昆仑》：“山三角：其一角正北，干辰之辉，名曰阆风巅；其一角正西，名曰玄圃堂；其一角正东，名曰昆仑宫。”阆苑：指传说中神仙居住的地方。\n君家：敬词。犹贵府，您家。《玉台新咏·古诗为焦仲卿妻作》：“非为织作迟，君家妇难为。”\n孤城：边远的孤立城寨或城镇。唐王昌龄《从军行》之四：“青海长云暗雪山，孤城遥望玉门关。”寒日：寒冬的太阳。唐李百药《登叶县故城谒沉诸梁庙》诗：“总辔临秋原，登城望寒日。”\n离愁：离别的愁思。金董解元《西厢记诸宫调》卷六：“驴鞭半袅，吟肩双耸，休问离愁轻重，向个马儿上驼也驼不动。”', poem_tags = '友情,送别,感伤' WHERE poem_title = '临江仙·记得金銮同唱第' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_tags = '古诗三百首,咏物,抒怀' WHERE poem_title = '登江中孤屿' AND poem_author = '谢灵运';
UPDATE edu_poem SET poem_translation = '荒弃的营垒上黄叶纷纷飘落，心怀壮志你告别了古塞险关。\n飒飒秋风将送你到汉阳渡口，初升的太阳会迎你在郢门山。\n江东亲友有几人正望眼欲穿，等候着你的孤舟从天涯回还。\n什么时候我们才能再次相见，举杯畅饮以抚慰离人的愁颜。', poem_notes = '荒戍：荒废的边塞营垒。\n浩然：意气充沛、豪迈坚定的样子，指远游之志甚坚。《孟子·公孙丑下》：“予然后浩然有归志。”\n汉阳渡：湖北汉阳的长江渡口。\n郢门山：位于今湖北宜都县西北长江南岸，即荆门山。\n江：指长江。几人：犹言谁人。\n孤棹：孤舟。棹：原指划船的一种工具，后引申为船。\n何当：何时。\n樽酒：犹杯酒。樽：古代盛酒的器具。离颜：离别的愁颜。', poem_appreciation = '这首《送人东游》诗载于《全唐诗》卷五百八十一。下面是古典诗词鉴赏家赵庆培先生对此诗的赏析。\n\n　　诗人在秋风中送别友人，倍感凄凉，对友人流露出关切，表现了两人深厚的友谊。这首诗意境悲凉雄壮，情真意切，质朴动人。\n\n　　关于此诗的发端，清人沈德潜曰：“起调最高。”（《唐诗别裁》）按首句，地点既傍荒凉冷落的古堡，时令又值落叶萧萧的寒秋，此时此地送友人远行，那别绪离愁，的确令人难以忍受。然而次句诗思却陡然一振：“浩然离故关”——友人此行，心怀浩气而有远志。气象格调，自是不凡。\n\n　　颔联两句互文，意为：初日高风汉阳渡，高风初日郢门山。初日，点明送别是在清晨。汉阳渡，长江渡口，在今湖北省武汉市；郢门山，位于湖北宜都市西北长江南岸。两地一东一西，相距千里，不会同时出现在视野之内，这里统指荆山楚水，从而展示辽阔雄奇的境界，并以巍巍高山、浩浩大江、飒飒秋风、杲杲旭日，为友人壮行色。\n\n　　颈联仿效李白“孤帆远影碧空尽，唯见长江天际流”（《黄鹤楼送孟浩然之广陵》）而赋予两重诗意：诗人一面目送归舟孤零零地消失在天际，一面遥想江东亲友大概正望眼欲穿，切盼归舟从天际飞来。几人，犹言谁人。“江上几人在”，想象归客将遇见哪些故人，受到怎样的接待，是对友人此后境遇的关切；诗人早年曾久游江淮，此处也寄托着对故交的怀念。\n\n　　尾联写当此送行之际，友人把酒言欢，开怀畅饮，设想他日重逢，更见依依惜别之情意。\n\n　　这首诗逢秋而不悲秋，送别而不伤别。如此离别，在友人，在诗人，都不曾引起更深的愁苦。诗人只在首句稍事点染深秋的苍凉气氛，便大笔挥洒，造成一个山高水长、扬帆万里的辽阔深远的意境，于依依惜别的深情之中，回应上文“浩然”，前后紧密配合，情调一致。结尾处又突然闪出日后重逢的遐想。论时间，一笔宕去，遥遥无期；论空间，则一勒而收，从千里之外的“江上”回到眼前，构思布局的纵擒开合，是很见经营的。', poem_tags = '唐诗三百首,秋天,送别,友情,惜别' WHERE poem_title = '送人东游' AND poem_author = '温庭筠';
UPDATE edu_poem SET poem_translation = '家住在孟津河旁，家门与孟津渡口相对。\n每天沿河有来自江南的小船，是否有丈夫从江南寄回的书信呢？\n\n您是刚从我们家乡来的，一定了解家乡的人情世态。\n请问您来的时候我家雕画花纹的窗户前，那一株腊梅花开了没有？\n\n看见梅花已经开了，又听见鸟儿的啼叫声。\n一颗充满忧愁的心看着春草生长，愈来愈茂盛的春草眼看就要连到阶前，禁不住惶恐起来了。', poem_notes = '孟津河：指河南洛阳北部的黄河南岸一带，是“武王伐纣，与八百诸侯会盟”之地，为古代交通要道。 \n君：对对方的尊称，您。\n故乡：家乡，这里指作者的故乡。\n来日：来的时候。\n绮窗：雕画花纹的窗户。\n寒梅：冬天绽放的梅花。\n著花未：开花没有？着（zhuó）花，开花。未，用于句末，相当于“否”，表疑问。\n玉阶：《万首唐人绝句》作“阶前”。', poem_appreciation = '其一：这首诗从触发、联想展开情感活动。女主人公住近渡口，每天沿河上下的船只从门前经过；于是她就想，其中也许有从江南来的船。丈夫在江南的某地长久不归。既然有江南船，就可能有丈夫从江南寄回的书信。她可能每天都倚门望几次。每当看到渡头有船只停泊，就不免要上前去打问，可结果总是失望而归。诗中说江南船“常有”，就是说书信“总无”。然而，主人公仍把希望寄托于下一趟船来，她想：大概书信已经寄出，正在途中，所以诗的结句“寄书家中否”便是这位少妇不断幻灭又不断复生的希望。\n\n　　其二：这首诗表现作者的情趣与倾向。诗人想念故乡，自然是情理之中；而喜欢梅花，则溢于言表。\n\n　　诗中的抒情主人公（“我”，不一定是作者），是一个久在异乡的人，忽然遇上来自故乡的旧友，首先激起的自然是强烈的乡思，是急欲了解故乡风物、人事的心情。开头两句，正是以一种不加修饰、接近于生活的自然状态的形式，传神地表达了“我”的这种感情。“故乡”一词迭见，正表现出乡思之殷：“应知”云云，迹近噜，却表现出了解乡事之情的急切，透露出一种儿童式的天真与亲切。纯用白描记言，却简洁地将“我”在特定情形下的感情、心理、神态、口吻等表现得栩栩如生，这其实是很省俭的笔墨。\n\n　　关于“故乡事”，那是可以开一张长长的问题清单的。初唐的王绩写过一篇《在京思故园见乡人问》，从朋旧童孩、宗族弟侄、旧园新树、茅斋宽窄、柳行疏密一直问到院果林花，仍然意犹未尽，“羁心只欲问”；而这首诗中的“我”却撇开这些，独问对方：来日绮窗前，寒梅著花未？仿佛故乡之值得怀念，就在窗前那株寒梅。这就很有些出乎常情。但又绝非故作姿态。\n\n　　一个人对故乡的怀念，总是和那些与自己过去生活有密切关系的人、事、物联结在一起。所谓“乡思”，完全是一种“形象思维”，浮现在思乡者脑海中的，都是一个个具体的形象或画面。故乡的亲朋故旧、山川景物、风土人情，都值得怀念。但引起亲切怀想的，有时往往是一些看来很平常、很细小的情事，这窗前的寒梅便是一例。它可能蕴含着当年家居生活亲切有趣的情事。因此，这株寒梅，就不再是一般的自然物，而成了故乡的一种象征。它已经被诗化、典型化了。因此这株寒梅也自然成了“我”的思乡之情的集中寄托。从这个意义上去理解，独问“寒梅著花未”是完全符合生活逻辑的。\n\n　　古代诗歌中常有这种质朴平淡而诗味浓郁的作品。它质朴到似乎不用任何技巧，实际上却包含着最高级的技巧。象这首诗中的独问寒梅，就不妨看成一种通过特殊体现一般的典型化技巧，而这种技巧却是用一种平淡质朴得如叙家常的形式来体现的。这正是所谓寓巧于朴。王绩的那首《在京思故园见乡人问》，朴质的程度也许超过这首诗，但它那一连串的发问，其艺术力量却远远抵不上王维的这一问。\n\n　　“君自故乡来，应知故乡事。”这一句看起来是问家乡的情况，但诗人只是笼统的以“故乡事”来设问，诗人心里满腹的问题一时竟不知从何问起了。这句描写出诗人的踌躇，对方的诧异。“来日绮窗前，寒梅著花未？”这一问倒令对方感到困惑，不问人事而问物事，可是正是这样一问，才是妙趣横生，令人回味无穷。其实诗人的真正目的，哪里是梅花啊。诗人想说的话，想问的问题不知从何说起，对家乡的思念竟在这一个不经意的问题之中。\n\n　　其三：这首诗以时序的递进、物候的变化，加深主人公的情感。“已见寒梅发”一句是对上一首询问寒梅著花的呼应。此句是女主人公失望的深深怨情。因为光景蹉跎，不能如期践约，此时在女主人公眼中，寒梅花发已由希望之光变为幻灭之色。不仅如此。便是这象征青春、爱情的春天，欣欣向荣的春天，也发生了质的变化。梅花开了，早春已过。百鸟叫了，仲春也已飞逝。现在是莺飞草长的暮春了。随着节序的推移，女主人公的心绪也由百无聊赖到终日惆怅，以至看花落泪、见月伤心了。以前，她觉得，时间过去一天，距离自己美好愿望的实现就近一日。现在完全是逆反心理：时间愈是过得快，幻灭就愈彻底，犹如滔滔日下的江河，无可如何。此时，鸟鸣，春草都变作主人公情感的对立物。诗人说女主人公是以一颗充满忧愁的心“视春草”，她看到愈来愈茂盛的春草眼看就要连到阶前，禁不住惶恐起来了。', poem_tags = '组诗,思念' WHERE poem_title = '杂诗三首 / 杂咏三首' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '弓箭沐浴着霞光，宝剑照耀着寒霜。\n剑起案列的秋风，驰马飞出了咸阳。\n国土一角仍沦陷，天子没有收河湟。\n这种情况不改变，不拟回头望故乡。', poem_notes = '少年行：古代歌曲名。\n走：跑。咸阳：指京城长安。\n河湟：指青海湟水流域和黄河西部，当时为异族所占。', poem_tags = '出征,爱国,壮志' WHERE poem_title = '少年行四首·其三' AND poem_author = '令狐楚';
UPDATE edu_poem SET poem_translation = '注释 菩萨蛮：词牌名。近人杨宪益《零墨新笺》考证《菩萨蛮》为古缅甸曲调，唐玄宗时传入中国，列于教坊曲。变调，四十四字，两仄韵，两平韵。②休：罢休，双方断绝关系。 参辰：星宿名。参星在西方，辰星（即商星）在东方，晚间此出彼灭，不能并见；白天一同隐没，更难觅得。 北斗：星座名，以位置在北、形状如斗而得名。 即：同“则”。', poem_appreciation = '它没有文人词深婉曲折的风致和含蓄蕴藉的神韵。从写法上的铺排、衬字的运用、表意的泼辣直露看，似元曲。但又无元曲的圆熟流丽、挥洒曲折。然而它却激动人心，千古不衰。\n\n　　原因在于主人以忠贞热烈的感情激发的想象和这种想象的感染力。词中的想象多样而新奇。主人公一连想到六种自然景物和非现实现象。青山、水面、黄河、参辰、北斗、日头，这些是习见的，并不奇。但经浪漫主义的想象之后，立刻变得引人入胜了。这些奇想反复表达了主人公的愿望，使人感到分明有一种“理”在：真正的爱情不一定是已经长久不分的，而是希望天长地久的。如果没有这种希望，整日厮守也徒然，有这种希望，即使天涯海角甚至人间天上的分离也美满。在主人公的眼中，爱情与山河同在，与日月共存。夸张地强调了爱情永固，但又不觉得过分，读者只为主人公崇高的感情而激动。相形之下，那些不严肃的爱情观是多么暗淡、空虚和渺小。由羡慕进而想到主人公如此之情是怎样产生的。\n\n　　尽管因素多种，依现在的理解，最重要的是它有充实的内容。但词中却只字未提，明快而又耐人寻味。诗中的想象是广阔大胆的。由大地到天空是其想象的空间，由山河到星日是其想象的对象。以宇宙间最雄伟的景物来烘托爱情，敢于把爱的生命与永恒的宇宙并提，形成一种奇妙的类比推理：青山不会烂，水面浮不起秤锤，黄河不会枯竭，参星和辰星不会在白天出现，北斗不会回到南天，半夜不会升起太阳，爱情不会中断。这样的类推也可说是理不通而情通，无理而妙。诗中提到的自然现象都遵循一个共同的规律，存在于天地之间，根据人们的经验，这规律是万古不变的。词中主人公正是依据这些自然现象与爱情理想在时间上的相似点，进行想象的。但未从正面写，却将爱的中止与这些规律的改变联系起来让前者发生在后者之后，由于后者是不会实现的，前者就不会发生。爱情永存的愿望被表现得十分生动有力，体现了从反面写与从正面写的不同效果。对可能出现的意外的担心，是更深的爱。愿其长久和害怕失去虽然意思相近，但后者对于对象的珍爱远胜前者，往往是精神上难以缺少的。诗中的奇伟想象正是由这深情所激发，而想象又使感情表达得更真挚、明朗、坚定、感人。', poem_tags = '宋词三百首,婉约,爱情' WHERE poem_title = '菩萨蛮·枕前发尽千般愿' AND poem_author = '佚名';
UPDATE edu_poem SET poem_tags = '婉约,抒情,相思' WHERE poem_title = '点绛唇·花信来时' AND poem_author = '晏几道';
UPDATE edu_poem SET poem_translation = '唐大历二年十月十九日，我在夔府别驾元持家里，观看临颍李十二娘跳剑器舞，觉得舞姿矫健多变非常壮观， 就问她是向谁学习的？她说：“我是公孙大娘的学生”。玄宗开元三年，我还年幼，记得在郾城看过公孙大娘跳《剑器》和《浑脱》舞，流畅飘逸而且节奏明朗，超群出众，当代第一，从皇宫内的宜春、梨园弟子 到宫外供奉的舞女中，懂得此舞的，在唐玄宗初年，只有公孙大娘一人而已。当年她服饰华美，容貌漂亮，如今我已是白首老翁，眼前她的弟子李十二娘，也已经不是年轻女子了。既然知道了她舞技的渊源，看来她们师徒的舞技一脉相承，抚今追昔，心中无限感慨，姑且写了《剑器行》这首诗。 听说过去吴州人张旭，他擅长书写草书字帖，在邺县经常观看公孙大娘跳一种《西河剑器》舞，从此草书书法大有长进，豪放激扬，放荡不羁，由此可知公孙大娘舞技之高超了。\n\n从前有个漂亮女人，名叫公孙大娘，每当她跳起剑舞来，就要轰动四方。\n观看人群多如山，心惊魄动脸变色，天地也被她的舞姿感染，起伏震荡。\n剑光璀灿夺目，有如后羿射落九日， 舞姿矫健敏捷，恰似天神驾龙飞翔，\n起舞时剑势如雷霆万钧，令人屏息，收舞时平静，好象江海凝聚的波光。\n鲜红的嘴唇绰约的舞姿，都已逝去，到了晚年，有弟子把艺术继承发扬。\n临颍美人李十二娘，在白帝城表演，她和此曲起舞，精妙无比神采飞扬。\n她和我谈论好久，关于剑舞的来由，我忆昔抚今，更增添无限惋惜哀伤。\n当年玄宗皇上的侍女，约有八千人，剑器舞姿数第一的，只有公孙大娘。\n五十年的光阴，真好比翻一下手掌，连年战乱烽烟弥漫，朝政昏暗无常。\n那些梨园子弟，一个个地烟消云散，只留李氏的舞姿，掩映冬日的寒光。\n金粟山玄宗墓前的树木，已经合抱，瞿塘峡白帝城一带，秋草萧瑟荒凉。\n玳弦琴瑟急促的乐曲，又一曲终了，明月初出乐极生悲，我心中惶惶。\n我这老夫，真不知哪是要去的地方， 荒山里迈步艰难，越走就越觉凄伤。', poem_notes = '①公孙大娘：唐玄宗时的舞蹈家。\n②弟子：指李十二娘。\n③剑器：指唐代流行的武舞，舞者为戎装女子。\n④大历二年：公元七六七年。\n⑤开元三载：公元七一七年。\n⑥剑器浑脱：《浑脱》是唐代流行的一种武舞，把《剑器》和《浑脱》综合起来，成为一种新的舞蹈。', poem_appreciation = '诗的开头八句是先写公孙大娘的舞蹈：很久以前有一个公孙大娘，她善舞剑器的名声传遍了四面八方。人山人海似的观众看她的舞蹈都惊讶失色，整个天地好像也在随着她的剑器舞而起伏低昂，无法恢复平静。“霍如羿射九日落”四句，或称为“四如句”，前人解释不一，这大体是描绘公孙舞蹈给杜甫留下的美好印象。羿射九日，可能是形容公孙手持红旗、火炬或剑器作旋转或滚翻式舞蹈动作，好象一个接一个的火球从高而下，满堂旋转；骖龙翔舞，是写公孙翩翩轻举，腾空飞翔；雷霆收怒，是形容舞蹈将近尾声，声势收敛；江海凝光，则写舞蹈完全停止，舞场内外肃静空阔，好象江海风平浪静，水光清澈的情景。\n\n　　“绛唇珠袖两寂寞”以下六句，突然转到公孙死后剑器舞的沉寂无闻，幸好晚年还有弟子继承了她的才艺。跟着写她的弟子临颍李十二娘在白帝城重舞剑器，还有公孙氏当年神采飞扬的气概。同李十二娘一席谈话，不仅知道她舞技的师传渊源，而且引起了自己抚今思昔的无限感慨。\n\n　　“先帝侍女八千人”以下六句，笔势又一转折，思想又回到五十年前。回忆开元初年，当时政治清明，国势强盛，唐玄宗在日理万机之暇，亲自建立了教坊和梨园，亲选乐工，亲教法曲，促成了唐代歌舞艺术的空前繁荣，当时宫廷内和内外教坊的歌舞女乐就有八千人，而公孙大娘的剑器舞又在八千人中“独出冠时”，号称第一。可是五十年历史变化多大啊！一场安史之乱把大唐帝国的整个天下闹得风尘四起、天昏地黑。唐玄宗当年亲自挑选、亲自培养的成千上万的梨园弟子、歌舞人材，也在这一场浩劫中烟消云散了，如今只有这个残存的教坊艺人李十二娘的舞姿，还在冬天残阳的余光里映出美丽而凄凉的影子。对曾经亲见开元盛世的文艺繁荣，曾经亲见公孙大娘《剑器舞》的老诗人杜甫说来，这是他晚年多么难得的精神安慰，可是又多么地令他黯然神伤啊！这一段是全诗的高潮。善于用最简短的几句话集中概括巨大的历史变化和广阔的社会内容，正是杜诗“沉郁顿挫”的表现。\n\n　　“金粟堆南木已拱”以下六句，是全诗的尾声。诗人接着上段深沉的感慨，说玄宗已死了六年，在他那金粟山上的陵墓上，树已够双手拱抱了。而自己这个玄宗时代的小臣，却流落在这个草木萧条的白帝城里。末了写别驾府宅里的盛筵，在又一曲急管繁弦的歌舞之后告终了，这时下弦月已经东出了，一种乐极哀来的情绪支配着诗人，他不禁四顾茫茫，百端交集，行不知所往，止不知所居，长满老茧的双足，拖着一个衰老久病的身躯，寒月荒山，踽踽独行。身世的悲凉，就不言而可知了。“转愁疾”三字，是说自己以茧足走山道本来很慢，但在心情沉重之时，却反而怪自己走得太快了。\n\n　　这首七言歌行自始至终并没有离开公孙大娘师徒和剑器舞，但是从全诗那雄浑的气势，从“五十年间似反掌，风尘澒洞昏王室”这样力透纸背的诗史之笔，又感到诗人的确是在通过歌舞的事，反映五十年来兴衰治乱的历史。王嗣总评这首诗说：“此诗见剑器而伤往事，所谓抚事慷慨也。故咏李氏，却思公孙；咏公孙，却思先帝；全是为开元天宝五十年治乱兴衰而发。不然，一舞女耳，何足摇其笔端哉！”（《杜诗祥注》引《杜臆》）这一段评语，分析全诗的层次、中心，说得相当中肯。但是，他说“一舞女耳，何足摇其笔端哉！”并不符合杜甫本来的思想，杜甫是十分重视和热爱艺术的。\n\n　　这首诗的艺术风格，既有“浏漓顿挫”的气势节奏，又有“豪荡感激”的感人力量，是七言歌行中沉郁悲壮的杰作。开头八句，富丽而不浮艳，铺排而不呆板。“绛唇珠袖”以下，则随意境之开合，思潮之起伏，语言音节也随之顿挫变化。全诗既不失雄浑完整的美，用字造句又有浑括锤炼的功力。篇幅虽然不太长，包容却相当广大。从乐舞之今昔对比中见五十年的兴衰治乱，没有沉郁顿挫的笔力是写不出来的。', poem_tags = '唐诗三百首,妇女,舞蹈,咏史' WHERE poem_title = '观公孙大娘弟子舞剑器行' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '清晨听到游子高唱离别之歌，昨夜下薄霜你一早渡过黄河。\n怀愁之人最怕听到鸿雁鸣叫，云山冷寂更不堪落寞的过客。\n潼关晨曦催促寒气临近京城，京城深秋捣衣声到晚上更多。\n请不要以为长安是行乐所在，以免白白地把宝贵时光消磨。', poem_notes = '魏万：又名颢。上元（唐高宗年号，674—676）初进士。曾隐居王屋山，自号王屋山人。\n游子：指魏万。离歌：离别的歌。\n初渡河：刚刚渡过黄河。魏万家住王屋山，在黄河北岸，去长安必须渡河。\n“鸿雁”二句：设想魏万在途中的寂寞心情。客中：即作客途中。\n关城：指潼关。树色：有的版本作“曙色”，黎明前的天色。催寒近：寒气越来越重，一路上天气愈来愈冷。\n御苑：皇宫的庭苑。这里借指京城。砧声：捣衣声。向晚多：愈接近傍晚愈多。\n“莫见”句：勉励魏万及时努力，不要虚度年华。蹉跎：此指虚度年华。说文新附：“蹉跎，失时也。”', poem_appreciation = '这是一首送别诗，被送者为诗人晚辈。诗中一、二两句想象魏万到京城沿途所能见的极易引起羁旅乡愁的景物。中间四句或在抒情中写景叙事，或在写景叙事中抒情，层次分明。最后两句劝勉魏万到了长安之后，不要只看到那里是行乐的地方而沉溺其中，蹉跎岁月，应该抓住机遇成就一番事业。这表达了诗人对魏万的深情厚意，情调深沉悲凉，但却催人向上。\n\n　　诗一开首，“朝闻游子唱离歌”，先说魏万的走，后用“昨夜微霜初渡河”，点出前一夜的景象，用倒戟而入的笔法，极为得势。“初渡河”，把霜拟人化了，写出深秋时节萧瑟的气氛。\n\n　　秋夜微霜，挚友别离，自然地逗出了一个“愁”字。“鸿雁不堪愁里听”，是紧接第二句，渲染氛围。“云山况是客中过”，接写正题，照应第一句。大雁，秋天南去，春天北归，飘零不定，有似旅人。它那嘹唳的雁声，从天末飘来，使人觉得怅惘凄切。而抱有满腹惆怅的人，当然就更难忍受了。云山，一般是令人向往的风景，而对于落寞失意的人，坐对云山，便会感到前路茫茫，黯然神伤。他乡游子，于此为甚。这是李颀以自己的心情来体会对方。“不堪”“况是”两个虚词前后呼应，往复顿挫，情切而意深。\n\n　　五、六两句，诗人对远行客又作了充满情意的推想：“关城树色催寒近，御苑砧声向晚多。”从洛阳西去要经过古函谷关和潼关，凉秋九月，草木摇落，一片萧瑟，标志着寒天的到来。本来是寒气使树变色，但寒不可见而树色可见，好像树色带来寒气，见树色而知寒近，是树色把寒催来的。一个“催”字，把平常景物写得有情有感，十分生动，傍晚砧声之多，为长安特有，“长安一片月，万户捣衣声”。然而诗人不用城关雄伟、御苑清华这样的景色来介绍长安，却只突出了“御苑砧声”，发人深想。魏万前此，大概没有到过长安，而李颀已多次到过京师，在那里曾“倾财破产”，历经辛酸。两句推想中，诗人平生感慨，尽在不言之中。“催寒近”“向晚多”六个字相对，暗含着岁月不待，年华易老之意，顺势引出了结尾二句。\n\n　　“莫见长安行乐处，空令岁月易蹉跎”，纯然是长者的语气，予魏万以亲切的嘱咐。这里用“行乐处”三字虚写长安，与上二句中的“御苑砧声”相应，一虚一实，恰恰表明了诗人的旨意。他谆谆告诫魏万：长安虽是“行乐处”，但不是一般人可以享受的。不要把宝贵的时光，轻易地消磨掉，要抓紧时机成就一番事业。可谓语重心长。\n\n　　这首诗以长于炼句而为后人所称道。诗人把叙事、写景、抒情交织在一起。如次联两句用了倒装手法，加强、加深了描写。先出“鸿雁”“云山”——感官接触到的物象，然后写“愁里听”“客中过”，这就由景生情，合于认识规律，容易唤起人们的共鸣。同样，第三联的“关城树色”和“御苑砧声”，虽是记忆中的形象，联系气候、时刻等环境条件，有声有色，非常自然。而“催”字、“向”字，更见推敲之功。', poem_tags = '唐诗三百首,送别,友情,叙事,写景,抒情' WHERE poem_title = '送魏万之京' AND poem_author = '李颀';
UPDATE edu_poem SET poem_translation = '全身衣服都沾满了血泪和尘埃，\n尽管现在战乱结束了，但是回到故乡也还会感到悲哀。\n在风雨中，梨花落尽了，寒食节也过去了，\n清明扫墓的时候，有几户人家的坟墓还会有后人来祭拜呢。（因为他们的后人在战乱中死去了）', poem_notes = '满衣：全身衣服。\n乱后：战乱之后。\n过：过去了，尽了。', poem_tags = '清明节,送别,感伤' WHERE poem_title = '送陈秀才还沙上省墓' AND poem_author = '高启';
UPDATE edu_poem SET poem_translation = '赏析 　　这首冬雪诗，前四句首先交代时间：冬日的黄昏，地点：孤村；接着，从听觉方面写处处风声急；继而，采用虚实结合的手法，突出了“溪深”、“山冻”，紧扣一个“雪”字。后四句具体描绘雪景，以沙鸥与鹭鸶难以辨认，“汀”与“洲”不能区分来映衬大雪覆盖大地的景象，突出“望”之特点。“野桥”两句写几株梅树枝头上都是白梅与积雪，令人分不清哪是白梅哪是雪，与唐代诗人岑参的“忽如一夜春风来，干树万树梨花开”(《白雪歌送武判官归京》)有异曲同工之妙。此诗形象生动，清新别致，可谓咏雪诗中纯属描写雪景之代表作。', poem_tags = '冬天,写雪' WHERE poem_title = '雪望' AND poem_author = '洪升';
UPDATE edu_poem SET poem_translation = '宁可少活十年，也不可一日没有权。大丈夫时运不顺，命途多艰。有朝一日如果天随人愿，一定要赛过田文养客三千。', poem_notes = '天净沙：又名塞上秋，属于越调宫曲调。体段短小，宜即兴抒情。\n时乖命蹇：时运不顺，命运不好。乖，相背；不合。蹇，不顺利。\n田文：即孟尝君，战国时齐国贵族，以好客重人才著称，门下食客数千人。', poem_tags = '人生' WHERE poem_title = '天净沙·宁可少活十年' AND poem_author = '严忠济';
UPDATE edu_poem SET poem_translation = '疾风驱使着骤雨倾倒在高城，乌云密布，雷声殷殷隆隆。\n一会儿，那兴云作雨的龙挟着雷电乌云离去，眼前出现的是池塘水溢，青草滴翠，万蛙齐鸣。', poem_notes = '驱：驱使。\n急雨：骤雨。\n云：这里指乌云。\n殷（yīn）：震动。\n池：池塘。', poem_appreciation = '《五月十九日大雨》这首诗非常形象地描述了夏天所特有的雷阵雨前后的自然景象，开门见山，展现了大雨奇观。诗人站在城楼上，眼见疾风驱使着大雨，顿时大雨磅礴。然而夏天的阵雨来得快，去得疾。不一会儿雨过天晴，只留下一片蛙鸣。诗人通过自然界的风雨，感悟到了人生哲理。\n\n　　前两句已把大雨写得十分畅满，极力描述了大雨的气势。黑云压城，风急雨骤，电闪雷鸣，大雨倾盆。“急”、“驱”、“洒”三字形象地表现出夏雨的骤猛。云是“压”的，雷是“殷”的，又说明黑云、雷电的迅疾。后两句描述雨过天晴的景象：雷雨过后，草色更青，池塘水涨，蛙声一片，诗人匠心独运，在震耳欲聋的雷声雨声后，仍写蛙鸣声，而两种声音，收到的是一闹一静的不同效果。雨后恬静平和的景象，与前两句磅礴威猛的雨景形成鲜明的对照。\n\n　　此诗写的是雨来到和雨止的景象。诗的前半句写出雷雨交作，气势雄峻；后半句写雨过天晴，平淡恬淡。前雷声，后蛙鸣，两两对照，逸趣横生。诗人通过写大自然的景况，告诉读者大风大雨虽然猛烈，但时间不会长久，当人遇到困难时，要坚持、要勇敢顽强，与之斗争，难关是会度过的。\n\n　　这首诗在造词遣句上虽模仿唐人，但在立意框架上与宋人咏景诗相近。刘基是诗人，更是政治家。政治家的胸怀往往与大自然的景况相融合，喜欢通过自然景观抒发人生的哲理，使天籁中赋有理趣。', poem_tags = '写雨,写景,哲理' WHERE poem_title = '五月十九日大雨' AND poem_author = '刘基';
UPDATE edu_poem SET poem_tags = '西湖,回忆' WHERE poem_title = '长相思·游西湖' AND poem_author = '康与之';
UPDATE edu_poem SET poem_translation = '做儿子的能死节于孝，做臣子的能死节于忠，那就是死得其所。安史乱起，正气崩解，不见尽忠报国之士，反多无耻降敌之徒，士风不振，大义不存。张巡骂贼寇直到双眼出血，许远温文尔雅爱君能守死节，他们都留下万古芳名。后来的人已经没有他们那样的操守，那种如百炼精钢似的精诚。\n　　人生短促，转眼生离死别。更应该轰轰烈烈做一番为国为民的事业。如果他们当时甘心投降卖国，则必受人唾骂，以至遗臭万年，又怎么能够流芳百世呢？双庙幽邃深沉，二公塑像庄严典雅。夕阳下寒鸦枯木示万物易衰，而古庙不改。邮亭下，如有奸雄经过，面对先烈，则当仔细思量、反躬自省。', poem_notes = '潮阳：今广东潮阳县。\n文天祥主张以孔孟之道立身行事。这三句就提出应该为忠、孝而死。\n光岳：高大的山。光岳气分：指国土分裂，即亡国。君臣义缺：指君臣之间欠缺大义。刚肠：指坚贞的节操。这四句是说自宋室沦丧以来，士大夫不能保全节操，君臣之间欠缺大义，是谁辜负了凛然不屈、刚正不阿的品德。\n张巡：与睢阳（今河南商丘县）太守许远共守危城，城陷后两人先后被害，他们英勇抗敌，宁死不屈的精神受到后人敬仰。\n后来者：指以后的士大夫。操：操守。\n翕歘（音唏嘘）：即倏忽，如火光之一现。云亡：死去。“云”字无义。\n古庙：即张、许公庙。仪容：指张、许两人的塑像。\n邮亭：古代设在沿途、供给公家送文书及旅客歇宿的会馆。这三句是对卖国投降的宋末奸臣的警告。', poem_tags = '赞美,爱国,忠义' WHERE poem_title = '沁园春·题潮阳张许二公庙' AND poem_author = '文天祥';
UPDATE edu_poem SET poem_tags = '宋词三百首,婉约,写景,感叹' WHERE poem_title = '南柯子·十里青山远' AND poem_author = '仲殊';
UPDATE edu_poem SET poem_tags = '岁月,怀念' WHERE poem_title = '卜算子·感旧' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '其一\n我劝你不要顾惜华贵的金缕衣，我劝你一定要珍惜青春少年时。\n花开宜折的时候就要抓紧去折，不要等到花谢时只折了个空枝。\n\n其十三\n时令将近寒食，春雨绵绵春草萋萋；春风过处苗麦摇摆，堤上杨柳依依。\n这是为什么啊，此前我有家却归去不得。杜鹃啊，不要在我耳边不停地悲啼。', poem_notes = '其一\n金缕衣：缀有金线的衣服，比喻荣华富贵。\n堪：可以，能够。\n直须：不必犹豫。直：直接，爽快。\n莫待：不要等到。\n\n其十三\n著：吹入。\n早是：此前。\n杜鹃：鸟名，即子规。\n休：不要。', poem_tags = '抒情' WHERE poem_title = '杂诗' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '焚书的烟雾刚刚散尽，秦始皇的帝业也随之灭亡，函谷关和黄河天险，也锁守不住始皇的故国旧居。\n焚书坑的灰烬还没冷却，山东群雄已揭竿起义，起义军领袖刘邦和项羽，原来都不读书！', poem_notes = '焚书坑：秦始皇焚烧诗书之地，故址在今陕西省临潼县东南的骊山上。\n竹帛：代指书籍。烟销：指把书籍烧光。帝业：皇帝的事业。这里指秦始皇统治天下，巩固统治地位的事业。虚：空虚。\n关河：代指险固的地理形势。关：函谷关。河：黄河。空锁：白白地扼守着。祖龙居：秦始皇的故居，指咸阳。祖龙：代指秦始皇。\n山东：崤函之东。一说指太行山之东，即为秦始皇所灭的六国旧有之地。\n刘项：刘邦和项羽，秦末两支主要农民起义军的领袖。不读书：刘邦年青时是市井无赖，项羽年青时习武，两人都没读多少书。', poem_appreciation = '这首诗就秦末动乱的局面，对秦始皇焚书的暴虐行径进行了辛辣的嘲讽和无情的谴责。\n\n　　公元前213（秦始皇三十四年），采纳丞相李斯的奏议，下令在全国范围内搜集焚毁儒家《诗》、《书》和百家之书，令下之后三十日不烧者，罚作筑城的苦役，造成中国历史上一场文化浩劫。\n\n　　焚书坑据传是当年焚书的一个洞穴，旧址在今陕西省临潼县东南的骊山上。章碣或者到过那里，目之所触，感慨系之，便写了这首诗。\n\n　　诗一开始就接触主题。首句用略带夸张的语言揭示矛盾：竹帛化为灰烟消失了，秦始皇的帝业也就跟着灭亡了，好像当初在焚书坑里焚烧的就是他的嬴氏天下。这一句夹叙夹议，明叙暗议，有实有虚。“竹帛烟销”是实写，有形象可见。“竹帛”是古代写书的材料，这里指书。“帝业虚”是虚写。这种虚实相间的表现手法极富韵致。\n\n　　次句就“帝业虚”之意深进一层，说是虽然有关河的险固，也保卫不住秦始皇在都城中的宫殿。“关河”主要指函谷关与黄河，当然也包括其他关隘、河流，如散关、萧关、泾河、渭河、崤山、华山等。贾谊《过秦论》：“秦地被山带河以为固，四塞之国也。”说“关河”，便概括一切可以倚恃的地理险阻。秦都咸阳四周虽有这许多关山河川包围着，但仍然锁守不住，所以《过秦论》又说：“秦人阻险不守，关梁不阖，长戟不刺，强弩不射。楚师深入，战于鸿门，曾无藩篱之艰。”再坚固的“篱笆”也挡不住起义军队的长驱直入。诗以“关河空锁祖龙居”一句总括了整个秦末动乱以至秦朝灭亡的史实，言简意深；并且以形象示现，把“帝业虚”这个抽象的概念写得有情有景，带述带评，很有回味。“祖龙”指秦始皇。这里不用“始皇”而用“祖龙”，决非单纯追求用典，而是出于表情达意的需要。《史记·秦始皇本纪》记载一项传说：始皇三十六年，有神人对秦使者说：“今年祖龙死。”使者回报始皇，始皇听了，好久不讲话，过后自作解释说：“祖龙者，人之先也。”秦始皇一心要做子孙万代诸“龙”之祖。而此时江山易主，“祖龙”一词正话反用，又添新意成了对秦始皇的绝妙讽刺，而且曲折有文采，合乎诗歌用语韵味。\n\n　　第三句点题，进一步用历史事实对“焚书”一事做出评判。秦始皇和李斯等人把“书”看成是祸乱的根源，以为焚了书就可以消灾弭祸，从此天下太平。结果适得其反，嬴秦王朝很快陷入风雨飘摇、朝不保夕的境地。“未冷”云云是夸张的言辞，旨在突出焚书行为的乖谬，实际上从焚书到陈胜吴广在大泽乡首举义旗，前后相隔整整四年时间。\n\n　　末句抒发议论、感慨。山东之乱持续了一个时期，秦王朝最后亡于刘邦和项羽之手。这两人一个曾长期在市井中厮混，一个出身行伍，都不是读书人。可见“书”未必就是祸乱的根源，“焚书”也未必就是巩固“子孙帝王万世之业”（《过秦论》）的有效措施。说“刘项原来不读书”，而能灭亡“焚书”之秦，全句纯然是揶揄调侃的口吻，包含着极为辛辣的讽刺意味。从“竹帛”写起，又以“书”作结，首尾相接如环，显得圆转自然。\n\n　　议论性的诗歌，既要剖析事理，又要显示意象，委实很不容易。这首诗采用了近乎喜剧的表现手法：揭示矛盾，使秦始皇处于自我否定的地位。这样写表面似乎很委婉，很冷静，其实反对的态度和憎恶的感情十分鲜明。如果说这就是“怨而不怒”的表现，那么，它也不失为一种成功的艺术手法。', poem_tags = '咏史怀古,叙事,议论,讽刺' WHERE poem_title = '焚书坑' AND poem_author = '章碣';
UPDATE edu_poem SET poem_translation = '秋天夜晚的南湖水面水澄澈无烟，（不由生出遗世独立、羽化登仙的“上天”之念），可怎么能够乘流上天呢？姑且向洞庭湖赊几分月色，痛快地赏月喝酒。', poem_notes = '耐可：哪可，怎么能够。\n赊：赊欠。', poem_appreciation = '诗人为我们描绘了月夜泛舟的情形：明月皎皎，湖水悠悠。洞庭秋水澄澈无烟，水月相映，清辉怡人。\n\n　　诗人与友人（此处，我们不妨把其族叔也当作友人）泛舟湖上，与清风朗月为伴，不由生出遗世独立、羽化登仙的“上天”之念。但乘流上天终不可得，诗人也只好收起这份不羁的想象，姑且向洞庭湖赊几分月色，痛快地赏月喝酒。\n\n　　首句写景，同时点出秋游洞庭事。“南湖秋水夜无烟”，初读平淡无奇，似是全不费力，脱口而出，实则极具表现力：月夜泛舟，洞庭湖水全不似白日烟波浩渺、水汽蒸腾之气象。波澜不惊，澄澈如画。无烟水愈清，水清月更明。溶溶月色溶于水，悠悠湖光悠月明。这种景象，这种意味，非置身其中不可得，非写意简笔不可得。诗人虽然没有精工细绘，但读者心中自会涌现出一幅水天一色的美好图景。', poem_tags = '月夜,行舟,写景,抒怀' WHERE poem_title = '游洞庭湖五首·其二' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '划船到江中去荡漾秋天的江水，更喜爱这荷花的鲜艳。\n拨弄那荷叶上为水珠，滚动着却总不成圆。\n美好的佳人藏在彩云里，要想赠给她鲜花，又远在天际。\n苦苦相思而相见无期，惆怅遥望在凄凉的秋风里。', poem_notes = '涉：本义是步行渡水，这里有泛舟游历之意。玩：赏玩、欣赏。秋水：秋天的江湖水，雨水。唐王勃《滕王阁序》：“落霞与孤鹜齐飞，秋水共长天一色。”\n红蕖（qú）：荷花盛开的样子。蕖：芙蕖，荷花的别名。\n弄：有把玩、欣赏之意。\n荡漾：水波微动。李白《梦游天姥吟留别》：“谢公宿处今尚在，渌水荡漾清猿啼。”\n佳人：美女。宋玉《登徒子好色赋》：“天下之佳人，莫若楚国；楚国之丽者，莫若臣里；臣里之美者，莫若臣东家之子。”\n远天：遥远的天宇，说明空间距离之远。\n相似：彼此想念。后多指男女相悦而无法接近所引起的想念。汉苏武《留别妻》诗：“生当复来归，死当长相思。”无因：没有门径，没有办法。\n凉风：秋风。《礼记·月令》：“（孟秋之月）凉风至，白露降，寒蝉鸣。”李白《秋思》诗：“芜然蕙草暮，飒尔凉风吹。”', poem_tags = '荷花,言志,惆怅' WHERE poem_title = '折荷有赠' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '离愁萦绕，看着眼前连绵无际的春草，想起与心上人同游时它们还刚在路边吐出香馨。闺中人想到心上人要远行，暗暗地流下泪珠，哽咽着目送远去的车轮。人已远去她还痴痴地张望，可见到的已是重重远水、片片孤云。她又登楼极目远望，但望穿秋水也难见游子踪影。\n伤心啊伤心，自从池塘分别后无日不黯然销魂。想当年同游的地方连绿草都妒忌她的罗裙。那时候他携着她的手，在花丛柳絮之中，在翠绿香茵上信步徜徉。如今她的容颜虽已渐渐老去，但心中情意仍像芳草一样年年常新。她要再游遍绿野，忘情嬉戏酣饮，不辜负这珍贵的年少青春。', poem_notes = '凤箫吟：词牌名。\n陌上初熏：路上散发着草的香气。陌：道路。熏：花草的香气浓烈侵人。\n绣帏：绣房、闺阁。\n暗垂珠露：暗暗落下一串串珠露般的眼泪。\n王孙：这里指送行之人。汉淮南小山《招隐士》：“王孙游兮不归，芳草生兮萋萋。”\n绿妒轻裙：轻柔的罗裙和芳草争绿。\n恁（nèn）：那。恁时：即那时、彼时。素手：指女子洁白如玉的手。\n香茵：芳草地。', poem_tags = '宋词三百首,宋词精选,离愁' WHERE poem_title = '凤箫吟·锁离愁' AND poem_author = '韩缜';
UPDATE edu_poem SET poem_tags = '送别,春天,写景,抒情,孤独' WHERE poem_title = '蝶恋花·京口得乡书' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_tags = '伤怀,感慨,愁闷' WHERE poem_title = '临江仙·夜到扬州席上作' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '公子贵族莫把菊苗看成普通野生草，\n重阳佳节，插菊在鬓发，朵朵争俏。\n露水阳光让菊花更丰润，香满池岸绿满池岸，\n因此它从来不用羡慕寄生的瓦松是不是很高。', poem_notes = '菊：此处暗指品德高尚的人。\n王孙：公子哥。\n比：看作。\n蓬蒿：野生草。\n九日：重阳节。\n秋香：菊花。\n由来：因此从来。\n瓦松：一种寄生在高大建筑物瓦檐处的植物，但“高不及尺，下才如寸”，没有什么用处。', poem_tags = '咏物,菊花,抒怀' WHERE poem_title = '菊' AND poem_author = '郑谷';
UPDATE edu_poem SET poem_translation = '齐国有一人叫冯谖。因为太穷而不能养活自己。他便托人告诉孟尝君，表示意愿在他的门下寄居为食客。孟尝君问他有什么擅长。回答说没有什么擅长。又问他有什么本事？回答说也没有什么本事。孟尝君听了后笑了笑，但还是接受了他（《战国策·冯谖客孟尝君》）。\n　　旁边的人认为孟尝君看不起冯谖，就让他吃粗劣的饭菜。（按照孟尝君的待客惯例，门客按能力分为三等：上等（车客）出有车；中等（门下之客）食有鱼；下等（草具之客）食无鱼。）过了一段时间，冯谖倚着柱子弹着自己的剑，唱道：“长剑我们回去吧！没有鱼吃。”左右的人把这事告诉了孟尝君。孟尝君说：“让他吃鱼，按照中等门客的生活待遇。”又过了一段时间，冯谖弹着他的剑，唱道：“长剑我们回去吧！外出没有车子。”左右的人都取笑他，并把这件事告诉给孟尝君。孟尝君说：“给他车子，按照上等门客的生活待遇。”冯谖于是乘坐他的车，高举着他的剑，去拜访他的朋友，十分高兴地说：“孟尝君待我为上等门客。”此后不久，冯谖又弹着他的剑，唱道：“长剑我们回去吧！没有能力养家。”此时，左右的手下都开始厌恶冯谖，认为他贪得无厌。而孟尝君听说此事后问他：“冯公有亲人吗？”冯谖说：“家中有老母亲。”于是孟尝君派人供给他母亲吃用，不使她感到缺乏。于是从那之后。冯谖不再唱歌。\n　　后来，孟尝君拿出记事的本子来询问他的门客：“谁熟习会计的事？”冯谖在本上署了自己的名，并签上一个“能”字。孟尝君见了名字感到很惊奇，问：“这是谁呀？”左右的人说：“就是唱那‘长铗归来’的人。”孟尝君笑道：“这位客人果真有才能，我亏待了他，还没见过面呢！”他立即派人请冯谖来相见，当面赔礼道：“我被琐事搞得精疲力竭，被忧虑搅得心烦意乱；加之我懦弱无能，整天埋在国家大事之中，以致怠慢了您，而您却并不见怪，倒愿意往薛地去为我收债，是吗？”冯谖回答道：“愿意去。”于是套好车马，整治行装，载上契约票据动身了。辞行的时候冯谖问：“债收完了，买什么回来？”孟尝君说：“您就看我家里缺什么吧。” 冯谖赶着车到薛，派官吏把该还债务的百姓找来核验契据。核验完毕后，他假托孟尝君的命令，把所有的债款赏赐给欠债人，并当场把债券烧掉。百姓都高呼“万岁”。 冯谖赶着车，马不停蹄，直奔齐都，清晨就求见孟尝君。冯谖回得如此迅速，孟尝君感到很奇怪，立即穿好衣、戴好帽，去见他，问道：“债都收完了吗？怎么回得这么快？”冯谖说：“都收了。”“买什么回来了？”孟尝君问。冯谖回答道：“您曾说‘看我家缺什么’，我私下考虑您宫中积满珍珠宝贝，外面马房多的是猎狗、骏马，后庭多的是美女，您家里所缺的只不过是‘仁义’罢了，所以我用债款为您买了‘仁义’。”孟尝君道：“买仁义是怎么回事？”冯谖道：“现在您不过有块小小的薛邑，如果不抚爱百姓，视民如子，而用商贾之道向人民图利，这怎行呢？因此我擅自假造您的命令，把债款赏赐给百姓，顺便烧掉了契据，以至百姓欢呼‘万岁’，这就是我用来为您买义的方式啊。”孟尝君听后很不快地说：“嗯，先生，算了吧。” 过了一年，齐闵王对孟尝君说：“我可不敢把先王的臣子当作我的臣子。”孟尝君只好到他的领地薛去。还差百里未到，薛地的人民扶老携幼，都在路旁迎接孟尝君到来。孟尝君见此情景，回头看着冯谖道：“您为我买的‘义’，今天才见到作用了。” 冯谖说：“狡猾机灵的兔子有三个洞才能免遭死患，现在您只有一个洞，还不能高枕无忧，请让我再去为您挖两个洞吧。”孟尝君应允了，就给了五十辆车子，五百斤黄金。冯谖往西到了魏国，他对惠王说：“现在齐国把他的大臣孟尝君放逐到国外去，哪位诸侯先迎住他，就可使自己的国家富庶强盛。”于是惠王把相位空出来，把原来的相国调为上将军，并派使者带着千斤黄金，百辆车子去聘请孟尝君。冯谖先赶车回去，告诫孟尝君说：“黄金千斤，这是很重的聘礼了；百辆车子，这算显贵的使臣了。齐国君臣大概听说这事了吧。”魏国的使臣往返了三次，孟尝君坚决推辞而不去魏国.\n　　齐王听到这个消息，君臣震恐，连忙派遣太傅带“黄金千金、文车二驷、服剑一、封书”等物，非常隆重地向孟尝君谢罪，请孟尝君要“顾先王之宗庙，姑反国统万人乎”。冯谖劝孟尝君趁机索取先王的祭器，“立宗庙于薛”。等齐国的宗庙在薛地落成后，冯谖向孟尝君报告说：“三窟已就，君姑高枕为乐矣”。（《战国策·齐策》）自从齐泯王罢免了孟尝君的相位后，门下食客多离他而去。孟尝君恢复相位后，冯谖策马前去迎接，其他门客都未到。孟尝君感慨地对冯谖说，自己一生好客，对待客人从来不敢有所闪失，而他们见我被罢官，却都离我而去了。今仰赖冯谖先生得以恢复相位，门客还有什么脸面再见我呢？我如果再见到他们，“必唾其面而大辱之”。冯谖听了忙下马向孟尝君叩头，孟尝君急下马制止，问他是否是替其他的门客谢罪。冯谖说，不是。而是为“君之言失”。他说，任何事物发展都有自身的规律，像有生命的东西一定会死亡一样，这是一种必然规律；“富贵多士，贫贱寡友”，这也是一种规律。赶集上市的人，清晨时都急急地赶往集市；但到日落时，人们就是经过集市，也只是甩着膀子走过去，看也不看一眼。他们不是爱好清晨，厌恶傍晚，而是因为傍晚时分，希望得到的东西，在那儿已经没有了。您失去相位，宾客自然都离去了，您不应该因此埋怨士人，希望孟尝君能够“遇客如故”。孟尝君非常感激冯谖的提醒，于是再次拜谢并接受了冯谖的建议，“敬从命矣，闻先生之言，敢不奉教焉”。（《史记·孟尝君列传》）\n　　冯谖有超人的智慧，极具战略眼光。他抱着对孟尝君高度负责的态度，积极为孟尝君政治地位的稳定出谋划策。在孟尝君做齐国相国的几十年时间里，“无纤介之祸”（《战国策·齐策》），是与冯谖的精心谋划分不开的。', poem_notes = '冯谖（xuān宣），齐国游说之士。谖，一作“煖”，《史记》又作“驩”，音皆同。 客，做门客。\n孟尝君，齐国贵族，姓田名文，齐闵王时为相。其父田婴在齐宣王时为相，并受封于薛，故本篇中有“寡人不敢以先王之臣为臣“之说。田婴死后，田文袭封地，封号为孟尝君。孟尝君好养士，据说有门客三千，成为以养士而著称的“战国四公子“之一，其中还有魏国信陵君，楚国春申君，赵国平原君。\n存，生存，生活。\n属（zhǔ主），通“嘱“,嘱咐。\n寄食门下，在孟尝君门下作食客。\n好（hào耗），爱好，擅长，喜好。\n诺，答应声。\n以，因为，因为孟尝君的态度而轻视冯谖。\n能，才能，本事。\n贱，轻视，看不起。\n食（sì四），通饲，给人吃。\n草具，粗劣的饭菜。具，供置，也能作酒肴。\n居有顷，过了不久。\n铗（jiá夹），剑。\n归来，离开，回来。乎，语气词。\n比，和……一样，等同于。\n为之驾，为他配车。\n揭，举。\n过，拜访。\n客我，待我以客，厚待我。即把我当上等门客看待。\n归来，回去。\n弹，敲打。\n无以为家，没有能力养家。\n恶（wù物），讨厌。\n给（jǐ己），供给。\n出记，出了一个文告。记，账册，古代一种公文文种。\n计会（kuài），会计。\n习，熟悉。\n责，同”债“。债的本字。\n署，署名，签名。（可见“记“不能作帐册，而当做告示。）\n负，辜负，对不住。实际意思是没有发现它的才干。\n谢，道歉。\n倦于事，忙于事务，疲劳不堪。\n愦（kuì）于忧，忧愁思虑太多，心思烦乱。愦，同“溃”，乱。\n懧愚，懦弱无能。懧，nuò同懦。\n沉，沉浸，埋头于。\n开罪，得罪。\n不羞，不以为羞。\n约车治装，准备车马、整理行装。约，缠束，约车即套车。\n券契，债契。债务关系人双方各持一半为凭。古时契约写在竹简或木简上，分两半，验证时，合起来查对，故后有合券之说。\n市，买。\n反，同”返“，返回。\n寡有，没有。\n驱，赶着车。 之，往。\n当偿者：应当还债的人。\n合券，验合债券。可知前面应解为“债务契约”。古代契约分为两半，立约双方各执其一。\n矫命，假托（孟尝君）命令。\n按：此节描述《史记》更合情理。\n疾，迅速。\n晨而求见：“见”读音xiàn，谒见。\n下陈，堂下，后室。\n区区，少，小，此亦隐指放债之利。\n拊爱，爱抚。拊，同“抚”，抚育，抚慰。\n子其民，视民如子。\n贾，做买卖。贾（gǔ）利之，做买卖获利。（不必视为名词作商人解。）\n说，通“悦”。\n休矣，算了吧。\n后期年，一周年之后。期（jī）年，整整一年。\n齐王，齐湣王。《史记·孟尝君列传》：“齐（湣）王惑于秦、楚之毁，以为孟尝君各高其主，而擅齐国之权，遂废孟尝君。”所谓“不敢以先王之臣为臣”，是托词。\n就国，回自己的封地。国，指孟尝君的封地薛。\n顾，回顾，旁顾。\n乘shèng，古代四马一车为一乘，亦可泛指车。\n窟，洞。\n梁，大梁，魏的国都。惠王，梁惠王，魏武侯之子。\n放，放逐。\n虚上位，把上位（宰相之位）空出来。\n先驱，驱车在前。\n重币，贵重的财物礼品。\n显使，地位显要的使臣。\n三反，先后多次往返。反，同“返”。\n固辞，坚决辞谢。\n太傅，官名，为辅弼国君之官。掌制定颁行礼法。\n赍jī，带着，抱着\n文车，文饰华美的车辆。\n驷，四马驾的车，比较：乘不一定是四马，驷一定是四马。\n服剑，佩剑。\n不祥，意为糊涂。 一说不善，没有福气。\n封书，写信，古代书信用封泥加印，故曰封书。\n谢，赔礼道歉。\n不祥，通详，审慎，不详即失察。\n被，遭受。\n被（pī）于宗庙之祟，遭受祖宗神灵降下的灾祸。被，同“披”，遭受。\n沉于谄谀（chǎnyú）之臣，被阿谀奉承的奸臣所迷惑。\n不足为，不值得你看重并辅助。一说无所作为。\n顾，顾念。\n姑，姑且。万人，指全国百姓。\n纤介，介同芥，纤丝与草籽，比喻极微小。', poem_tags = '古文观止,历史,故事,写人' WHERE poem_title = '冯谖客孟尝君' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '西风送来万里之外的家书，问我何时归家？\n鸿雁在红叶满山的季节呼唤着同伴南迁，而离人却对着黄花遍地的景色沉醉其中，听着雨打芭蕉的声音，却只能籍着秋夜的清凉，但愿做个好梦，能梦回家乡探望亲人。', poem_notes = '清江引：曲牌名。\n未：什么时候。\n红叶天：秋天。红叶，枫叶。深秋枫叶红遍，霜林如醉。杜牧《山行》：“停车坐爱枫林晚，霜叶红于二月花。”\n黄花地：菊花满地。', poem_appreciation = '秋风中接到家信，远自万里之外寄来，谆谆“问我归期未”，这两句从空间和时间的两个方面表现了“我”与“家”的暌隔。而诗人未对来信的殷望作任何正面的答复，仅是铺排了自己所处客乡的秋景。“红叶天”、“黄花地”，显然受了《西厢记·长亭送别》中“碧云天，黄花地，西风紧北雁南飞”的启导，而《西厢记》又是移用了范仲淹《苏幕遮》词的“碧云天，黄叶地”，亦为感秋之作。红叶黄花勾勒了清秋的轮廓，色彩鲜明，但却有一种苍凉冷颓的情韵。尤其是作者在这一背景中添现了“雁”、“人”的活动主角，且雁啼于天，人醉于地，便使这种苍凉冷颓发挥到了极致。“雁啼”最牵愁惹恨，“人醉”则是为了忘忧，而“芭蕉雨声秋梦里”，秋雨的萧疏冷酷，使得乡梦也为之惊醒。这三句景句无不暗寓着人物的客乡况味和主观感受，代表着诗人的“秋怀”。深沉的乡思与有家难归的羁愁，便足以回答“归期未”的提问了。\n\n　　这三句是作者收信后无言的感受，但它也可以视作诗人因家信问起归期而惆怅苦闷的应接。可以这样想象：诗人因在现实上不可能回到万里以外的乡园，无语可复，心中充满了忧愁与歉疚。他抬头望天，想看看那传书的鸿雁可在，结果发现“雁啼红叶天”，大雁似乎也在为他发出悲鸣。满地秋菊盛开，但那并不是故园的黄花，诗人只能借酒狂饮，在酩酊中暂忘乡愁。入夜了，他希望能在梦中实现回乡的心愿，可是“隔窗知夜雨，芭蕉先有声”（白居易《夜雨》），蕉叶上的雨声又无情地提醒着他的孤寂。“问我归期未”，不敢答复，至此也无须答复。小令的这三句景语，在时间的跨度上可前可后，代表了“秋怀”的一贯凄凉，确实是颇见妙味的。\n\n　　应该说这个概括在这首短小精悍的曲里能够得到很好的体现，至于熔铸名句这点，恐怕元曲三百首里没有多少非香艳的题材的作品能跳出唐宋的成就。\n\n　　回到曲上，“西风信来家万里，问我归期未？”看似简单，实则也简单明了，直奔主题，唯一比较特别之处是以西风送信，这个并不是很多见，古人一般是鱼传尺素，雁寄归思，青鸟传音，西风送信便是把西风拟人，赋予看似凛冽的西风一点人情味；“问我归期未”，平实却亲切，仿佛正面对面问话一般。又令人想起“道是归期未有期”这种情怀，有点淡淡哀愁。可见，这两句应该没有经过太多斟酌，完全是作者的真情实感的流露，因此读来也没有丝毫矫揉造作之感。\n\n　　“雁啼红叶天，人醉黄花地，芭蕉雨声秋梦里”这一句其实颇为经典，既充分体现张可久“清丽派”的作风，又充分体现曲在营造意境上对诗词手法的传承，强调了一种有构图讲究的图画般的美感。这一句却能够从人的多种感官角度把一种写来写去的思乡情怀具体化，形象化，把主观感受融入客观景物里，虽是一种常用的表现手法，又因作者能对颜色、声音、炼字、音韵都做出很好地把握，使得此曲经得起反复的品读。“红叶”“黄花”秋意尽显，颜色鲜明，令人印象深刻，脑海中立即出现相似的画面；“啼”“醉”可以说是有炼字的功夫在内的，雁啼虽不同于杜鹃啼，但只要说到啼声，总是会有些感情在其中，无非雁就是像“我”一样，呼唤着同伴南迁，顺便一提，张可久是浙江人，也就是南方人，那么北雁南飞对于他的意义就更为具体了，而这啼声中，也夹杂着一些复杂的情绪，也许隐含了悲伤、急切、思念、担忧等等，醉，作者认为黄花遍地的景色醉人，但有道是景不醉人人自醉，能够归乡的喜悦心情才真正让作者沉醉其中；芭蕉雨声秋梦里，芭蕉在古代是有特定所指的意象，一般指代愁思、闺思、乡怀、悲凉，而雨打芭蕉一般是指愁上加愁，不可排解。李清照就常用芭蕉的意象。作者是十分心急的，急得发愁，也许正遇上某些事，回乡无望，因而听着雨打芭蕉的声音，似乎只能籍着秋夜的清凉，做个好梦，梦回家乡探望亲人。\n\n　　从押韵这方面来说，不看曲有没有固定韵位，应该是没有的，“里”“未”“地”“里”都是有押韵的，故而朗读起来，此曲也是琅琅上口，音韵和谐的。\n\n　　当一句话，一首曲有一种让人在相似的情形下想起的力量时，已经可以算是成功的作品。正如每逢秋夜下雨时，都会想到“芭蕉雨声秋梦里”以及另一些无名氏的作品“一声声，一更更。窗外芭蕉窗里灯，此时无限情”“楼外凉蟾一晕生，雨余秋更清”把几种意境重叠在一起，然后整理起自己种种的愁绪。\n\n　　本诗前两句，作者道出自己的乡思情。然而这种乡思情有多深有多浓？作者没有直接外露，却是以“西风”“红叶”“黄花”“芭蕉”“秋雨”这些富有季节特征的一组景物构成意境，渲染出一幅色彩浓丽的秋景图，衬自己浓浓的乡思情。\n\n　　唐李商隐《夜雨寄北》：“君问归期未有期，巴山夜雨涨秋池。”是在归未有期但又存在着“何当共剪西窗烛”可能的情形下，生慨于寄身之处的旁景。而本作连“未有期”的吐诉都鼓不起勇气，心上的伤口就可想而知了。', poem_tags = '秋天,写景,抒怀,思乡' WHERE poem_title = '清江引·秋怀' AND poem_author = '张可久';
UPDATE edu_poem SET poem_tags = '言志' WHERE poem_title = '山坡羊·道情' AND poem_author = '宋方壶';
UPDATE edu_poem SET poem_translation = '译文 杏花在细细的如青烟的柳丝中若隐若现， 夜晚的露珠轻柔的拂去深绿色柳叶的尘沙。 柳枝也有他风流的一面呀， 悄悄的倒映着钱塘美女在夜色中点灯梳妆。', poem_tags = '古诗三百首,柳树' WHERE poem_title = '柳' AND poem_author = '寇准';
UPDATE edu_poem SET poem_translation = '雨一直下着，听着窗外的雨滴声，直到深更都难以入睡。雨中的芭蕉和屋里的油灯此时似乎也变得多情起来，安慰孤独的我。\n好梦难成，此恨难消，窗外的雨可不管忧愁的人喜不喜欢听，仍是不停地下着，雨滴一直滴到天明才停了下来。', poem_notes = '长相思：词牌名，唐教坊曲名。\n一更更：一遍遍报时的更鼓声。\n恨，遗撼。\n道：知。\n阶：台阶。', poem_appreciation = '万俟咏作词喜用淡语，且工于音韵。这样连续重复用字，吟咏起来便很有音乐上的美感。 《雨》首句“一声声，一更更”形容雨声，连用两个叠宇，描摹雨断断续续的声音，既显得形象，在声音上也显得贴近。雨声之所以如此清晰入耳，是因为人夜深难寐。“窗外芭蕉窗里灯”，听雨之人点。一盏孤灯，隔窗昕雨。“芭蕉”暗示雨打芭蕉的声音，使雨的声音更加响亮。“此时无限情”，直接道出人的心情。然而“无限”二字又使这种直言显得暖昧模糊。只知情意无限，心事无边，却不知究竟是什么样的心事使人长夜失眠，寂寞听雨。 “梦难成，恨难平”，用两个“难”字突出人的愁苦心情。因难以入睡，所以道．“梦难成”，连暂时逃避到好梦中去都是一种奢望；又因情在心头辗转，更兼一夜风雨，触动愁思，故日“恨难平”。但是雨不管这些，它“不道愁人不喜听”，只管“空阶滴到明”。“愁人”怪雨无情，不顾人的心情，就这样在空洞洞的台阶上一点一点滴到天明，这说明人一夜未睡。“一声声，一更更”的雨声，凄凄凉凉，仿佛人心中的愁绪一般，永远没有尽头。全词无一处提及“雨”字，却处处是雨。作者将雨声与听雨之人的心情融合得毫无痕迹，显示出高超的运笔功力。', poem_tags = '宋词精选,写雨,声音,孤独' WHERE poem_title = '长相思·雨' AND poem_author = '万俟咏';
UPDATE edu_poem SET poem_tags = '七夕节' WHERE poem_title = '鹊桥仙·七夕' AND poem_author = '范成大';
UPDATE edu_poem SET poem_translation = '深秋霜降时节，水位下降，远处江心的沙洲都露出来了。酒力减退了，才觉察到微风吹过，让人觉得凉飕飕的。破帽却多情留恋，不肯被风吹落。\n重阳节如何度过，只借酒消忧，打发时光而已，世间万事都是转眼成空的梦境，因而不要再提往事。重阳节后菊花色香均会大减，连迷恋菊花的蝴蝶，也会感叹发愁了。', poem_notes = '南乡子：唐教坊曲名，后用为词牌。原为单调，有二十七字、二十八字、三十字各体，平仄换韵。单调始自后蜀欧阳炯。南唐冯延巳始增为双调。冯词平韵五十六字，十句，上下片各四句用韵。另有五十八字体。又名《好离乡》、《蕉叶怨》等。\n重九：农历九月初九重阳节。\n涵辉楼：在黄冈县西南。徐君猷：名大受，当时黄州知州。\n水痕收：指水位降低。\n浅碧：水浅而绿。\n鳞鳞：形容水波如鱼鳞一般。\n若为酬：怎样应付过去。\n尊：同“樽”，酒杯。\n休休：不要，此处意思是不要再提往事。', poem_appreciation = '词的上片写楼中远眺情景。首句“霜降水痕收，浅碧鳞鳞露远洲”，描绘大江两岸晴秋景象。江上水浅，是深秋霜降季节现象，以“水痕收”表之。“浅碧”承上句江水，“鳞鳞”是水泛微波，似鱼鳞状：“露远洲”，水位下降，露出江心沙洲，“远”字体现的是登楼遥望所见。两句是此时此地即目之景，勾勒出天高气清、明丽雄阔的秋景。\n\n　　“酒力渐消风力软，飕飕，破帽多情却恋头”，此三句写酒后感受。“酒力渐消”，皮肤敏感，故觉有“风力”。而风本甚微，故觉其“力软”。风力虽“软”，仍觉有“飕飕”凉意。但风力再软，仍不至于落帽。此三句以“风力”为轴心，围绕它来发挥。晋时孟嘉落帽于龙山，是唐宋诗词常用的典故。苏轼对这一典故加以反用，说破帽对他的头很有感情，不管风怎样吹，抵死不肯离开。“破帽”这里具有象征隐喻意义，指的是世事的纷纷扰扰、官场的勾心斗角。作者说破帽“多情恋头”，不仅不厌恶，反而深表喜悦，这其实是用戏谑的手法，表达自己渴望超脱而又无法真正超脱的无可奈何。\n\n　　下片就涵辉楼上宴席，抒发感慨。“佳节若为酬，但把清樽断送秋”两句，化用杜牧《重九齐山登高》诗“但将酩酊酬佳节，不用登临怨落晖”句意。“断送”，此即打发走之意。政治上所受重大打击，使他对待世事的态度有所变化，由忧惧转为达观，这乃是他黄州时期所领悟到的安心之法。\n\n　　歇拍三句申说为何要以美酒断送秋。“万事到头都是梦”是化用宋初潘阆“万事到头都是梦，休嗟百计不如人”句意。“明日黄花蝶也愁”反用唐郑谷咏《十日菊》中“节去蜂愁蝶不知，晓庭还绕折残枝”句意，意谓明日之菊，色香均会大减，已非今日之菊，连迷恋菊花的蝴蝶，也会为之叹惋伤悲。此句以蝶愁喻良辰易逝，好花难久，正因为如此，此时对此盛开之菊，更应开怀畅饮，尽情赏玩。\n\n　　“万事到头都是梦，休休”，这与苏轼别的词中所发出的“人间如梦”、“世事一场大梦”、“未转头时皆梦”、“古今如梦，何曾梦觉”，“君臣一梦，古今虚名”等慨叹异曲同工，表现了苏轼后半生的生活态度。他看来，世间万事，皆是梦境，转眼成空；荣辱得失、富贵贫贱，都是过眼云烟；世事的纷纷扰扰，不必耿耿于怀。如果命运不允许自己有为，就饮酒作乐，终老余生；如有机会一展抱负，就努力为之。这种进取与退隐、积极与消极的矛盾双重心理，在词中得到了集中体现。', poem_tags = '宋词精选,秋天,写景,抒怀' WHERE poem_title = '南乡子·重九涵辉楼呈徐君猷' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_tags = '怀古,写人' WHERE poem_title = '筹笔驿' AND poem_author = '罗隐';
UPDATE edu_poem SET poem_translation = '几里远就能听到凄寒的水声，山区人家居住分散没有近邻。\n怪禽从旷野上传来声声鸣叫，昏惨的落日惊恐过路的行人。\n一弯新月未得照彻漫漫长夜，边关的烽火并没有越过三秦。\n远处几棵萧条的桑柘树外面，袅袅炊烟渐觉与人相近相亲。', poem_notes = '寒水：此指清冷的流水。唐杜牧《泊秦淮》诗：“烟笼寒水月笼沙，夜泊秦淮近酒家。”\n山家：山野人家。唐杜甫《从驿次草堂复至东屯茅屋》诗之二：“山家蒸栗暖，野饭射麋新。”四邻：周围邻居。汉刘向《列女传·周主忠妾》：“主闻之乃厚币而嫁之，四邻争娶之。”\n怪禽：此指鸱鸮（chīxiāo）一类的鸟。啼：后省略“于”字。旷野：空阔的原野。《诗经·小雅·何草不黄》：“匪兕匪虎，率彼旷野，哀我征夫，朝夕不暇。”\n恐：此处为使动用法，使……惊恐。行人：出行的人。《管子·轻重己》：“十日之内，室无处女，路无行人。”\n初月：新月。《乐府诗集·清商曲辞一·子夜四时歌春歌五》：“碧楼冥初月，罗绮垂新风。”终夕：通宵，彻夜。唐杜甫《八哀诗·故著作郎贬台州司户荥阳郑公虔》：“操纸终夕酣，时物集遐想。”\n边烽：边境上报告战事的烽火。唐沈佺期《塞北》诗之一：“海气如秋雨，边烽似夏云。”秦：指今陕西南部一带。\n萧条：此处为稀疏之意。汉扬雄《羽猎赋》：“羡漫半散，萧条数千里外。”桑柘（zhè）：此处用本意，桑木与柘木。《礼记·月令》：“（季春之月）命野虞无伐桑柘，鸣鸠拂其羽，戴胜降于桑。”\n烟火：指炊烟，泛指人烟。《史记·律书》：“天下殷富，粟至十馀钱，鸣鸡吠狗，烟火万里，可谓和乐者乎？”', poem_appreciation = '贾岛以“幽奇寒僻”的风格著称，这一首羁旅诗充分体现了他的创作特色。\n\n　　起句从听觉形象写起。一个秋天的黄昏，诗人路过一座山村，远远便闻到山涧的潺潺流水声：“数里闻寒水”。在“数里”的范围内能清晰地听到细微的水声，可见山区的寂静凄冷。而映在眼帘的是稀稀落落的人家──“山家少四邻”。这一听觉形象和视觉形象相互衬托，生动地渲染出山村的萧索而冷落的氛围。首联点题，作者用淡墨勾勒出一幅荒凉的山村远景。\n\n　　颔联，重点描摹山区萧瑟阴森的景象：“怪禽啼旷野，落日恐行人。”“怪禽”大概是鸱鸮一类的鸟。这种怪禽在荒漠凄寂的旷野上鸣叫，本来就令人闻而惊惶不安；刚好又碰上夕阳下山，山区渐渐暗黑下来，孤单的行人此时此刻自然更加感到不寒而栗。这两句诗写声写色，声色均骇人听闻。诗的境界幽深险僻，自是贾岛本色。\n\n　　诗人从数里外的旷野走向山村，一路行来，时间不知不觉地过去，夜幕悄悄地拉开。颈联转写夜景：“初月未终夕，边烽不过秦。”边烽，指边境的烽火。唐代边烽有两种：一种是报边境有事的紧急烽火，一种是报平安的烽火。秦，指今陕西南部一带。这两句的意思是说，初升的月亮高悬天空，烽火点燃起来，没有越过秦地，表明这一地区平安无事，山区更显得阒静，安谧。这时候诗人逐渐走近山庄。\n\n　　尾联即写接近山村时的喜悦感受：“萧条桑柘外，烟火渐相亲。”诗人经过萧疏荒凉的山区旷野，终于隐隐约约地看到山村人家宅边常种的桑树柘树和茅舍上升起的袅袅轻烟，内心不禁感到无比的温暖与亲切，先前的惊惧心情渐渐平静下来，转而产生一种欢欣喜悦的感情。结句“烟火渐相亲”，写得极富生活情趣与韵味。诗人对生活的感受相当敏锐，体验深刻，又着意炼句，因此，诗里的心理刻画也显得细致入微而耐人寻味。\n\n　　这样，诗的格局便显得有波澜，有开阖，寓变化多样于章法井然之中。\n\n　　诗的形象写得险怪寒瘦，境界幽深奇异，在中唐诗歌中确实别具一格。明胡应麟推崇“浪仙之幽奇”为“五言独造”（《诗薮·内编》卷四）。从风格这一角度上看，这一评语也说得中肯。', poem_tags = '羁旅,山村' WHERE poem_title = '暮过山村' AND poem_author = '贾岛';
UPDATE edu_poem SET poem_translation = '花开时我们一同醉酒以销春之愁绪，醉酒后盼着了花枝当做喝酒之筹码。\n突然间，想到老友远去他乡不可见，屈指算来，你今天行程该到梁州了。', poem_notes = '破：破除，解除。\n酒筹：饮酒时用以记数或行令的筹子。\n天际：肉眼能看到的天地交接的地方。\n计程：计算路程。梁州：地名，在今陕西汉中一带。', poem_appreciation = '唐人喜欢以行第相称。这首诗中的“元九”就是在中唐诗坛上与白居易齐名的元稹。809年（元和四年），元稹奉使去东川。白居易在长安，与他的弟弟白行简和李杓直（即诗题中的李十一）一同到曲江、慈恩寺春游，又到杓直家饮酒，席上忆念元稹，就写了这首诗。\n\n　　诗的首句，据当时参加游宴的白行简在他写的《三梦记》中记作“春来无计破春愁”，照说应当是可靠的；但《白氏长庆集》中却作“花时同醉破春愁”。一首诗在传钞或刻印过程中会出现异文，而作者对自己的作品也会反复推敲，多次易稿。就此诗来说，白行简所记可能是初稿的字句，《白氏长庆集》所录则是最后的定稿。诗人之所以要作这样的修改，是因为在章法上，诗的首句是“起”，次句是“承”，第三句当是“转”。从首句与次句的关系看，把“春来无计”改为“花时同醉”，就与“醉折花枝”句承接得更紧密，而在上下两句中，“花”字与“醉”字重复颠倒运用，更有相映成趣之妙。再就首句与第三句的关系看，“春愁”原是“忆故人”的伏笔，但如果一开头就说“无计破春愁”，到第三句将无法显示转折。这样一改动，先说春愁已因花时同醉而破，再在第三句中用“忽忆”两字陡然一转，才见波澜起伏之美，从而跌宕出全篇的风神。\n\n　　这首诗的特点是，即席拈来，不事雕琢，以极其朴素、极其浅显的语言，表达了极其深厚、极其真挚的情意。而情意的表达，主要在篇末“计程今日到梁州”一句。“计程”由上句“忽忆”来，是“忆”的深化。故人相别，居者忆念行者时，随着忆念的深入，常会计算对方此时已否到达目的地或正在中途某地。这里，诗人意念所到，深情所注，信手写出这一生活中的实意常情，给人以特别真实、特别亲切之感。\n\n　　白居易对元稹行程的计算是很准确的。当他写这首《醉忆元九》诗时，元稹正在梁州，而且写了一首《梁州梦》：“梦君同绕曲江头，也向慈恩院院游。亭吏呼人排去马，忽惊身在古梁州。”元稹对这首诗的说明是：“是夜宿汉川驿，梦与杓直、乐天同游曲江，兼入慈恩寺诸院，倏然而寤，则递乘及阶，邮吏已传呼报晓矣。”巧的是，白居易诗中写的真事竟与元稹写的梦境两相吻合。这件事，表面上有一层神秘色彩，其实是生活中完全可能出现的巧合，而这一巧合正是以元稹、白居易平日的友情为基础的。唐代长安城东南的慈恩寺和曲江是当时的游赏胜地。而且，进士登科后，皇帝就在曲江赐宴；慈恩寺塔即雁塔，又是新进士题名之处。他们两人应当常到这两处共同游宴。对元稹说来，当他在孤寂的旅途中怀念故人、追思昔游时，这两处长安名胜，不仅在日间会时时浮上他的心头，当然也会在夜间进入他的梦境。由于这样一个梦原本来自对故人、对长安、对旧游的朝夕忆念，他也只是如实写来，未事渲染，而无限相思、一片真情已全在其中。其情深意真，是可以与白居易的诗比美的。\n\n　　读者更可见两人的交谊之笃，也更可见白居易的这首诗虽像是偶然动念，随笔成篇，却有其深厚真挚的感情基础。如果把两人的诗合起来看：一写于长安，一写于梁州；一写居者之忆，一写行人之思；一写真事，一写梦境；诗中情事却如《本事诗》所说，“合若符契”。而且，两诗写于同一天，又用的是同一韵。这是两情的异地交流和相互感应。读者不仅可以领略诗篇的艺术魅力，而且可以从它的感情内容得到真和美的享受。', poem_tags = '友情,思念' WHERE poem_title = '同李十一醉忆元九' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '注释 有所思：汉乐府《铙歌》名，以首句“有所思”为名。写一女子欲与情郎决绝时的犹豫之情；一说当与《上邪》合为一篇，系男女问答的之词，后人以此为题赋诗，多写男女情爱事。 青楼：豪华精致的楼房，常指美人的居所。 珠箔：即珠帘子。 姮娥：即“嫦娥”。 翠眉、蝉鬓：均指美人。翠眉，用深绿色的螺黛画眉。蝉鬓，古代妇女的一种发式，望之缥缈如蝉翼，故云。', poem_tags = '爱情' WHERE poem_title = '有所思' AND poem_author = '卢仝';
UPDATE edu_poem SET poem_translation = '常常恼恨言语的表达粗浅有限，不像人的心意那么丰富深厚。\n今天两个人你看着我我看着你，默默地用眼神传达着心中复杂的情感。', poem_notes = '视刀环歌：刘禹锡创乐府新题。典出《汉书·李广苏建传》，含盼人早日还归之意。\n恨：遗憾。\n人意：人的意愿、情绪。\n脉脉：默默地用眼神或行动表达情意的样子。万重心：极言内心感情的复杂。', poem_tags = '爱人,分别,抒怀' WHERE poem_title = '视刀环歌' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '听说春天已经回还我还未识其面，前去依傍寒梅访寻消息。\n昨夜东风吹入江夏，路边陌上的杨柳冒出嫩芽一片金黄。\n碧水浩浩云雾茫茫，王汉阳您啊不来令我空白断肠。\n我已预先拂净青山上一片石摆下酒宴，要与您连日连夜醉在壶觞之中。', poem_notes = '王汉阳：其人姓王，官职汉阳县令。生平不详。\n走傍：走近。\n武阳：此指江夏。\n陌（mò）：田间东西方向的道路，泛指田间小路。陌头：街头。\n美人：古人往往以美人、香草比君子，此指王汉阳。\n预拂：预先拂拭。\n壶觞（shāng）：酒器。壶：盛液体的容器。觞：古代酒器；欢饮，进酒。晋陶潜《归去来辞》：“引壶觞以自酌，眄庭柯以怡颜。”唐白居易《将至东都先寄令狐留守》诗：“诗境忽来还自得，醉乡潜去与谁期？东都添箇狂宾客，先报壶觞风月知。”金马定国《送图南》诗：“壶觞送客柳亭东，回首三齐落照中。”清顾炎武《陶彭泽归里》诗：“瓮盎连朝浊，壶觞永日酣。”清阮葵生《茶馀客话》卷四：“先生辨舟中几人，服某某色；杯斝壶觞之属，历历可数。”', poem_tags = '春天,思念' WHERE poem_title = '早春寄王汉阳' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '在木兰为桨沙棠为舟的船上，箫管之乐在船的两头吹奏着。\n船中载着千斛美酒和美艳的歌妓，任凭它在江中随波逐流。\n黄鹤楼上的仙人还有待于乘黄鹤而仙去，而我这个海客却毫无机心地与白鸥狎游。\n屈原的词赋至今仍与日月并悬，而楚王建台榭的山丘之上如今已空无一物了。\n我兴酣之时，落笔可摇动五岳，诗成之后，啸傲之声，直凌越沧海。\n功名富贵若能常在，汉水恐怕就要西北倒流了。', poem_notes = '江上吟，李白自创之歌行体。江，指汉江。此诗宋本、王本题下俱注云：一作“江上游”。\n木兰，即辛夷，香木名。枻，同“楫”，舟旁划水的工具，即船桨。《九歌·湘君》：“桂棹兮兰枻”。沙棠，木名。南朝梁任昉《述异记》：“汉成帝与赵飞燕游太液池，以沙棠木为舟。其木出昆仑山，人食其实，入水不溺。”木兰枻、沙棠舟，形容船和桨的名贵。\n玉箫金管，用金玉装饰的箫笛。此处指吹箫笛等乐器的歌妓。\n樽，盛酒的器具。置，盛放。斛，古时十斗为一斛。千斛，形容船中置酒极多。\n妓，歌舞的女子。\n乘黄鹤，用黄鹤楼的神话传说。黄鹤楼故址在今湖北省武汉市武昌西黄鹤山上，下临江汉。旧传仙人子安曾驾黄鹤过此，因而得名。一说是费文祎乘黄鹤登仙，曾在此休息，故名。\n海客，海边的人。《列子·黄帝篇》：“海上之人有好沤鸟者，每旦之海上，沤鸟之至者百住而不止。其父曰：‘吾闻沤鸟皆从汝游，汝取来，吾玩之’。明日之海上，沤鸟舞而不下也”。\n屈平，屈原名平，战国末期楚国大诗人，著有《离骚》《天问》等。《史记·屈原贾生列传》评价《离骚》是：“自疏濯淖污泥之中，蝉蜕于浊秽，以浮游尘埃之外，不获世之滋垢，皭然泥而不滓者也。推此志也，虽与日月争光可也”。\n榭，台上建有房屋叫榭。台榭，泛指楼台亭阁。楚灵王有章华台，楚庄王有钓台，均以豪奢著名。\n兴酣，诗兴浓烈。五岳，指东岳泰山，西岳华山，南岳衡山，北岳恒山，中岳嵩山。此处泛指山岳。\n凌，凌驾，高出。沧洲，江海。\n汉水，发源于陕西省宁强县，东南流经湖北襄阳，至汉口汇入长江。汉水向西北倒流，比喻不可能的事情。', poem_tags = '自由,生活' WHERE poem_title = '江上吟' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '译文 罗浮山下四季都是春天，枇杷和黄梅天天都有新鲜的。 如果每天吃三百颗荔枝，我愿意永远都做岭南的人。', poem_appreciation = '从“荔枝诗”看东坡先生的岭南心境。\n\n　　苏东坡于宋哲宗绍圣元年被人告以“讥斥先朝”的罪名被贬岭南，“不得签书公事”。于是，东坡先生流连风景，体察风物，对岭南产生了深深的热爱之情，连在岭南地区极为平常的荔枝都爱得那样执着。\n\n　　绍圣二年四月十一日，苏轼在惠州第一次吃荔枝，作有《四月十一日初食荔枝》一诗，对荔枝极尽赞美之能事：“……垂黄缀紫烟雨里，特与荔枝为先驱。海山仙人绛罗襦，红纱中单白玉肤。不须更待妃子笑，风骨自是倾城姝……”自此以后，苏轼还多次在诗文中表现了他对荔枝的喜爱之情。例如，《新年五首》：“荔子几时熟，花头今已繁。”《赠昙秀》：“留师笋蕨不足道，怅望荔枝何时丹。”《〈和陶归园田居六首)引》：“有父老年八十五，指(荔枝)以告余曰：‘及是可食，公能携酒来游乎?’意欣然许之。”《和陶归园田居》其五：“愿同荔枝社，长作鸡黍局。”《食荔枝二首》其二：“日啖荔枝三百颗，不辞长作岭南人。”\n\n　　其中“日啖荔枝三百颗，不辞长作岭南人”二句最为脍炙人口，解诗者多以为东坡先生在此赞美岭南风物，从而抒发对岭南的留恋之情，其实这是东坡先生满腹苦水唱成了甜甜的赞歌。\n\n　　不错，从一些现象上看起来，苏轼在岭南时的心情与初贬黄州时相比，确实显得更加平静，不见了“空庖煮寒菜，破灶烧湿苇”的失意与苦闷。《宋史》本传说苏轼在惠州“居三年，泊然无所蒂介，人无贤愚，皆得其欢心”。贬为琼州别驾后，居在“非人所居”的地方，“初僦官屋以居，有司犹谓不可。轼遂买地筑室，儋人运甓畚土以助之。独与幼子过处，著书以为乐，时时从其父老游，若将终身。”苏辙《东坡先生和陶诗引》介绍： “东坡先生谪居儋耳，置家罗浮之下……华屋玉食之念，不存于胸中。”苏东坡在岭南时，除了关心自然风光和民情风俗以外，还与出家人交往频繁，诗文中就留有很多与僧人唱和的作品。这一定程度上确实表现了避世意识。\n\n　　我们实在无法相信苏东坡这样具有强烈社会责任感的仁人志士会避世遁俗。有一件事实很能说明这个有趣的问题。\n\n　　晚年的苏东坡似乎很喜欢陶渊明，不厌其烦地和陶渊明的诗，并把和陶的诗专门编为一集。苏东坡和陶渊明诗以居岭南时为最多。从绍圣二年正月在惠州贬所到元符三年八月迁舒州团练副使，徙永州安置，在短短的五年零八个月里，和陶诗凡四十四次一百余首。东坡先生还自述其和陶用意：“平生出仕以犯世患，此所以深愧渊明，欲以晚节师范其万一也。” (见苏辙《东坡先生和陶诗引》)这仿佛在告世人：苏东坡从此绝意仕途，欲效陶渊明归隐园田，长作岭南人了。\n\n　　有意思的是，东坡先生那位心迹相通的老弟却对东坡自述的和陶诗用意提出了疑问，他在《东坡先生和陶诗引》一文中说：“嗟乎，渊明不肯为五斗米一束带见乡里小儿。而子瞻出仕三十余年，为狱吏所折困，终不能悛，以陷大难，乃欲以桑榆之末景，自托于渊明，其谁肯信之!”清人纪昀也以为苏轼“敛才就陶，亦时时自露本色”。\n\n　　苏辙不信其兄会真心归隐，几百年后纪昀的看法也一样。他们的看法可以在苏东坡和陶诗中可以得到印证。《和陶饮酒二十首》其十一曰：“诏书宽积欠，父老颜色好。再拜贺吾君，获此不贪宝。”其十八曰：“芜城阅兴废，雷塘几开塞。明年起华堂，置酒吊亡国。”其二十曰：“当时刘项罢，四海疮痍新。三杯洗战国，一斗消强秦。”《和陶咏三良》有：“杀身固有道，大节要不亏。君为社稷死，我则同其归。”这都可以看出苏轼恬淡的外表掩饰不了牵挂国运民生的忧患情怀。\n\n　　这种忧患情怀在《荔枝叹》一诗中表现得更加淋漓尽致。他首先借汉唐故实抨击统治阶级只顾自己享乐而不关民生疾苦的丑恶本质：“十里一置飞尘灰，五里一堠兵火催。颠坑仆谷相枕藉，知是荔枝龙眼来。飞车跨山鹘横海，风枝露叶如新采。宫中美人一破颜，惊尘溅血流千载。”千年以后，我们尤可想见苏学士老泪纵横，祈求上苍：“我愿天公怜赤子，莫生尤物为疮痏。雨顺风调百谷登，民不饥寒为上瑞。”\n\n　　苏东坡因仕途坎坷曾经想避世遁俗，又因恋恋不忘国运民生终于没能做到归隐山林。在岭南时，东坡先生的内心正处于这种出世与入世两难的心境之中。“日啖荔枝三百颗，不辞长作岭南人”正是这种两难心境的形象描述。', poem_tags = '地名,赞美,荔枝' WHERE poem_title = '惠州一绝 / 食荔枝' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '孟子说：“对于君王的不聪明，不必奇怪。即使有天下最容易生长的东西，（如果）晒它一天，冻它十天，没有能生长的。我见君王的次数很少，我一离开他，那些给他泼冷水的人马上又围上去了，（这样，）我对他刚有的那点善心的萌芽又能怎么样呢？（好比下棋，）下棋作为技艺，是小技艺；不专心致志，就学不到手。　奕秋是全国的下棋圣手，让他教两个人下棋。一个人专心专意，只听奕秋的话。另一个呢，虽然听着，但心里却想着有只天鹅快要飞来，要拿起弓箭去射它。这样，即使跟人家一道学习，他的成绩也一定不如人家的。是因为他的聪明不如人家吗？自然不是这样的。', poem_notes = '孟子，名轲，字子舆东周战国时期伟大的思想家、教育家、政治家、文学家。\n无或：不值得奇怪。或：同“惑”，奇怪。\n易生：容易生长。\n暴（pù）：同“曝”，晒。\n罕：少。\n如……何：对……怎么样。\n弈：围棋。\n数：技术，技巧。\n秋，人名，因他善于下棋，所以称为弈秋。\n通：整个，全部。\n之：的。\n善：善于，擅长做…的人。\n使：假使。\n诲：教导。\n以为：认为，觉得。\n鸿鹄（hú）：天鹅。\n将至：将要到来。\n思：想。\n援：拿起。\n缴（zhuó）：系在箭上的绳，代箭。', poem_tags = '高中文言文,寓理,故事' WHERE poem_title = '弈秋' AND poem_author = '孟子及弟子';
UPDATE edu_poem SET poem_translation = '（我）找到西山后的第八天，沿着山口向西北走两百步，又发现了钴鉧潭。钴鉧潭西面二十五步（的地方），在水流急而深处是一道坝。坝顶上有一座小丘，（小丘）上面生长着竹子和树木。小丘上的石头突出隆起、高然耸立，破土而出、争奇斗怪的，几乎（多得）数不清。那些重叠着、相负而下的石头，好像是（俯身）在小溪里喝水的牛马；那些高耸突出、如兽角斜列往上冲的石头，好像是在山上攀登的棕熊。\n\n　　小丘很小，不到一亩，可以把它装到笼子里占有它。（我）打听它的主人是谁，（有人）说：“这是唐家不要的地方，想出售却卖不出去。”（我）问它的价钱，（有人）说：“只要四百文。”我很喜欢（这个小丘），就（把它）买了下来。李深源、元克己这时和我一起游览，（他们）都非常高兴，（认为这是）出乎意料的收获。（我们）随即轮流拿起工具，铲割杂草，砍伐杂树，点燃大火把它们烧掉。美好的树木树立起来了，秀美的竹子显露出来了，奇峭的石头呈现出来了。（我们）站在小丘中间眺望，（只见）高高的山岭、漂浮的云朵、潺潺的溪流、自由自在游玩的飞鸟走兽，全都欢快地呈巧献技，来为这个小丘效力。（我们在小丘上）枕着石头席地而卧，眼睛触及的是清澈明净的景色，耳朵触及的是淙淙潺潺的水声，精神感受到的是悠远空旷的浩然之气，心灵感受到的是恬静幽深的境界。不满十天（我）就得到了两处风景胜地，即使古代爱好山水的人士，也许没有到过这地方吧。\n\n　　唉！凭着这小丘优美的景色，（如果）把它放到（京都附近的）沣、镐、鄠、杜（等这些繁华的地方），那么喜欢游赏的、争相购买的人每天增加几千文钱（购买）反而（恐怕）更加买不到。如今（它）被抛弃在（这荒僻的）永州，连农民、渔夫走过也鄙视它，售价（只有）四百文钱，一连几年也卖不出去。而唯独我和李深源、元克己因为得到它了而高兴，难道遇到这个小丘真的要靠运气吗？（我）把这篇文章写在石碑上，用来祝贺（我和）这小丘的遇合。', poem_notes = '寻：通“循”，沿着。\n道：行走。\n步：指跨一步的距离。\n潭：原选本无，据中华书局版《柳河东集》补。\n湍（tuān）：急流。\n浚（jùn）：深水。\n鱼梁：用石砌成的拦截水流、中开缺口以便捕鱼的堰。\n突怒：形容石头突出隆起。\n偃蹇（yǎnjiǎn）：形容石头高耸的姿态。\n殆：几乎，差不多。\n嵚（qīn）然：山势高峻的样子。\n冲（chòng）然：向上或向前的样子。\n角列：争取排到前面去，一说，像兽角那样排列。\n罴（pí）：棕熊。\n不能：不足，不满，不到。\n笼：包笼，包罗。\n货：卖，出售。\n不售：卖不出去。\n怜：爱惜。\n售：买。\n更：轮番，一次又一次。\n器用：器具，工具。\n刈（yì）：割。\n其中：小丘的当中。\n举：全。\n熙熙然：和悦的样子。\n回巧：呈现巧妙的姿态，\n技：指景物姿态的各自的特点。\n效：效力，尽力贡献。\n清泠（líng）：形容景色清凉明澈。\n谋：这里是接触的意思。\n瀯瀯（yíngyíng）：象声词，像水回旋的声音。\n匝（zā）旬：满十天。匝，周。旬，十天为一旬。\n虽：即使，纵使，就是。\n好（hào）事：爱好山水。\n或：或许，只怕，可能。\n焉：表示估量语气。\n胜：指优美的景色。\n陋：鄙视，轻视。\n连岁：多年，接连几年。\n其：岂，难道。\n遭：遇合，运气。\n所以：用来……的。', poem_appreciation = '内容结构\n\n　　第一段，写小丘的基本情况。“得西山后八日，寻山口西北道二百步，又得钴鉧潭。西二十五步，当湍而浚者为鱼梁。”两句，介绍发现小丘的时间及小丘的方位。“梁之上有丘焉，生竹树。”句后的第一段内容，写小丘的景物。钴鉧潭的形势主体是水，小丘的形势主体则是石。作者仅用“生竹树”三字概括其一般景物，而把重点放在写山石的奇特上。着重描写石的“奇”，主要运用了拟人的手法。“突怒偃蹇”，不仅写出了石的形状，更写出了石的神态；“负土而出”的“出”字，又写出了石的动作；“争为奇状者”的“争”字突出了山石不甘心被埋在泥土中、顽强地抗争逆境的品格：不甘心被埋在泥土中，也可看作是作者自身品格的写照。石的奇状既多到殆不可数，作者无法写尽，于是举出其中的两组作为代表，“其然相累而下者，若牛马之饮于溪；其冲然角列而上者，若熊罴之登于山”一句，既是对偶又运用比拟的方法，形象地将一堆堆静止的无生命的石头描绘成了一群群虎虎有生气的牛马和猛兽，生动细致，联想奇妙，下笔传神，可谓“词出意表，而刻画无上”。\n\n　　第二段，写小丘的遭遇和小丘带给自己的享受。小丘美好奇特却被主人抛弃，作者自然萌生购买的念头。“唐氏之弃地，货而不售”明写的是小丘的遭遇，实际上暗含着作者自身的遭遇；作者被贬到永州，怀才不遇，同样是被遗弃，和小丘的命运非常相似。“价止四百”进一步印证了小丘售价之低廉，同时也暗含着作者被无辜贬低的愤慨。得到小丘后，“即更取器用，铲刈秽草，伐去恶木，烈火而焚之。”这番去除务尽的行动，是对自然界秽草恶木的憎恶，又传达出作者对社会邪恶势力的深恶痛绝，声东击西，指桑骂槐而已。“立”、“露”、“显”三个动词，准确地表现了作者除去秽草恶木的成果，暗含作者锄奸扶良、改革朝政的主张和理想。“山之高，云之浮，溪之流，鸟兽之遨游，举熙熙然回巧献技，以效兹丘之下”可见新生的小丘恢复了它天然幽美的风姿，主要写外部景致，把静物寓于动态之中。“枕席而卧，则清泠之状与目谋，瀯瀯之声与耳谋，悠然而虚者与神谋，渊然而静者与心谋”这一段排比句写作者的感受，其所描绘的境界同文章开头有明显不同：开头写被弃山石的姿态，抒发了作者愤世疾时的愤慨；此时写在整修后的小丘上所感受到的暂时的怡适和宁静，既显示了小丘的价值，也表现作者为自己在不满一旬的时间里得到两处奇异的地方，而感到由衷的欣慰。\n\n　　最后一段，作者直抒胸臆。作者感叹同样一个小丘，在繁华之地被争相购买，在穷乡僻壤遭人鄙视。被弃置的小丘“农夫过而陋之”，却被作者和他的朋友赏识从而彻底地改变了命运；如此前写小丘之胜，后写弃掷之感，高兴之余顿处凄清，转折之中独见幽怜，名为小丘，实为作者。“而我与深源、克己独喜得之，是其果有遭乎”一句表明了小丘遭人鄙视的原因；“果有遭”一是说小丘被“我”喜而得之，是它有了好的际遇，得到了赏识，二是说自己的遭遇同小丘一样；正如宋人洪迈所说：“士之处世，遇与不遇，其亦如是哉！”，刘海峰认为“前写小丘之胜，后写弃掷之感，转折独见幽冷”，也是这个意思。“书于石，所以贺兹丘之遭也”最后说明写此文的目的，字面上是祝贺小丘得到赏识，真正的用意是为自己被贬谪的不公平待遇而气恼和忧伤，通过“贺兹丘之遭”来发泄胸中的积郁。\n\n文学价值\n\n　　永州山水，在柳宗元之前，并不为世人所知。但是这些偏居荒芜的山水景致，在柳宗元的笔下，却表现出别具洞天的审美特征，极富艺术生命力。正如清人刘熙载在《艺概·文概》中所说：“柳州记山水，状人物，论文章，无不形容尽致；其自命为‘牢笼百态’，固宜。”柳宗元时而大笔挥洒，描摹永州山水的高旷之美，使寂寥冷落的永州山水给人以气势磅礴之感。\n\n　　《钴鉧潭西小丘记》不是客观描摹自然风景，而是蕴藏着作者深厚的思想感情。他慨叹这样美好的风景被遗弃在僻远的荒野中无人赏识，受人轻蔑，正是借以倾吐自己的抱负和才能被埋没、遭打击的不平之鸣。正如他在《愚溪诗序》中所说，他是以心与笔“漱涤万物，牢笼百态”。像《钴鉧潭西小丘记》中所写的景物“清泠之状与目谋，瀴瀴之声与耳谋，悠然而虚者与神谋，渊然而静者与心谋”，这山水便不仅仅是一种视觉、听觉的客观对象，而是投射了作者心境的活生生的亲切的自然。所以，他笔下的山水，都具有他所向往的高洁、幽静、清雅的情趣，也有他诗中孤寂、凄清、幽怨的格调。在同病相怜的情况下，能够努力发掘、欣赏这遗弃的美好风景的只有柳宗元，而能够安慰孤苦受辱的柳宗元的也就是这些山水了。\n\n　　《永州八记》对自然美的描绘，贵在精雕细刻出一种幽深之美。八记描写的大都是眼前小景，如小丘、小石潭、小石涧、小石城山等，柳宗元总是以小见大，犹如沙里淘金，提炼出一副副价值连城的艺术精品。如《小石潭记》对小石潭周围环境的描写，“四面竹树环合，寂寥无人，凄神寒骨，悄怆幽邃”，创造出一种空无人迹的山野清幽之美。又如《石渠记》对小石渠之水流经之处细腻的刻画，在长不过十许步的小水渠上，一处处幽丽的小景，美不胜收。越过石渠是昌蒲掩映、苔藓环绕的石泓，又折而西行，旁陷岩石之下是幅员不足百尺、鱼儿穿梭的清深的小水潭，又向北曲行，则全都是诡石、怪木、奇卉、美竹。\n\n　　作者眼前的这些小景，幽深宜人，展示出永州山水的特有风姿。柳宗元曾经说：“余虽不合于俗，亦颇以文墨自慰，漱涤万物，牢笼百态，而无所避之。”他的意思就是说虽然因永贞革新遭挫，但他未改本色，于是借山水之题，发胸中之气，洗涤天地间万物，囊括大自然的百态，在用笔赞赏山水美的同时，把自己和山水融化在一起，借以寻求人生真谛，聊以自慰。因而，柳宗元在《永州八记》中刻画永州山水的形象美、色彩美和动态美，不是纯客观地描摹自然，而是以山水自喻，赋予永州山水以血肉灵魂，把永州山水性格化了。可以说，永州山水之美就是柳宗元人格美的艺术写照，可谓情景交融。', poem_tags = '古文观止,山水,游记,咏物,寓人,抒愤' WHERE poem_title = '钴鉧潭西小丘记' AND poem_author = '柳宗元';
UPDATE edu_poem SET poem_appreciation = '小说中，林黛玉病卧潇湘馆，秋夜听雨声淅沥，灯下翻看《乐府杂稿》，见有《秋闺怨》、《别离怨》等词，“不觉心有所感，亦不禁发于章句，遂成《代别离》一首，拟《春江花月夜》之格，乃名其词曰《秋窗风雨夕》。”《春江花月夜》系初唐诗人张若虚所作，是一首写离愁别恨的歌行。这首诗在格调和句法上都有意模仿它。“代别离·秋窗风雨夕”，前者是乐府题。代，如同“拟”，仿作的意思。用“代”字的乐府题，南朝诗人鲍照的集中特多。一般情况下，乐府诗不另外再加题目，这里因为又仿初唐歌行《春江花月夜》而作，所以又拟一个字面上与唐诗完全对称的、更具体的诗题。\n\n　　《秋窗风雨夕》的作意，如果不加深求，可以说与《葬花吟》一样，都可以看作是林黛玉伤悼身世之作，所不同的是它已没有《葬花吟》中那种抑塞之气和傲世态度，而显得更加苦闷、颓伤。这可以从以下的情况得到解释：林黛玉当时被病魔所缠，薛宝钗对她表示关心，使她感激之余深自悔恨，觉得往日种种烦恼皆由她自己多心而生，以至自误到今。林黛玉本来脆弱，在病势加深的情况下，又加上了这样的精神负担，就变得更加消沉。但是，如果读者认为作者写此诗并非只为了一般地表现林黛玉的多愁善感，要细究其深意，那么也就会发现一些问题。首先，无论是《秋闺怨》、《别离怨》或者《代别离》这类题目，在乐府中从来都有特定的内容，即只写男女别离的愁怨，而并不用来写背乡离亲、寄人篱下的内容。此时林黛玉双亲都已过世，家中又别无亲人，诗中“别离”、“离情”、“离人”等等用语更是用不上的。再从其借前人“秋屏泪烛”诗意及所拟《春江花月夜》原诗来看，也都是写男女别离之思。可见，要说“黛玉不觉心有所感”感的是她以往的身世遭遇是很难说得通的。这首诗只能是写一种对未来命运的隐约预感，而这一预感恰恰被后半部佚稿中贾宝玉获罪被拘走因而与林黛玉生离死别的情节所证实（参见《红楼梦曲·枉凝眉》、《葬花吟》等诗鉴赏），曹雪芹的文字正有这种草蛇灰线的特点。《红楼梦曲》中写林黛玉的悲剧结局是：“想眼中能有多少泪珠儿，怎禁得秋流到冬，春流到夏！”脂砚斋所读到的潇湘馆后来的景象是：“落叶萧萧，寒烟漠漠。”这些也都在这首诗中预先作了写照。\n\n　　小说中林黛玉刚写完诗搁下笔，贾宝玉就进来了，下面所描写的主要细节是：林黛玉先说贾宝玉像渔翁，接着说漏了嘴，又把她自己比作“画儿上画的和戏上扮的渔婆”，因而羞红了脸。对此，用心极细的脂砚斋用批语揭示作者这样写的用意说：“妙极之文！使黛玉自己直说出夫妻来，却又云‘画的’，‘扮的’，本是闲谈，却是暗隐不吉之兆，所谓‘画中爱宠’是也。谁曰不然？”这一批语，对帮助读者理解作者写这首诗的用意，是很有启发的。', poem_tags = '秋天,雨夜,伤悼,命运' WHERE poem_title = '代别离·秋窗风雨夕' AND poem_author = '曹雪芹';
UPDATE edu_poem SET poem_translation = '站在南楼上靠着栏杆向四周远望，只见山色和水色连接在一起，辽阔的水面上菱角、荷花盛开，飘来阵阵香气。清风明月没有人看管自由自在，月光融入清风从南面吹来，使人感到一片凉爽和惬意。', poem_notes = '鄂（è）州：在今湖北省武汉、黄石一带。南楼：在武昌蛇山顶。 \n四顾：向四周望去。山光、水光：山色、水色。 \n凭栏：靠着栏杆。十里：形容水面辽阔。芰（jì）：菱角。 \n并：合并在一起。一味凉：一片凉意。', poem_appreciation = '《鄂州南楼书事》描述的情景是：武昌的夏天，热得可怕。那天晚上，诗人登上高高的南楼乘凉。他倚栏而望，明月已近中天，皎洁的清辉倾泻而下。四面的山光与水光相连相映，一片通明；方圆十数里、盛开着芰（菱）花、荷 花，凉爽的夜风中，不断有淡淡的芳香扑面而来。习习清风，朗朗明月，谁也不能对它们管束驱遗，它们慷慨、殷勤地为南楼送来清清爽爽的夜凉，供游人称心快意地消受啊！\n\n　　欣赏这首小诗，读者很容易忘记自身的处境，仿佛自己也登上南楼来乘凉了。这样的感觉是这样来的。先从外界景象来看：四外山水落石出，十里芰荷 ，楼头清风，空中明月，远方近处，天上地下，以南楼为中心，构成一个高远、清空、富有立体感的艺术境界。再从自身感受来说：山光、水光、月光，是眼睛的视觉所感到的；芰花、荷花的香气，是鼻子的嗅觉所感到的；清风——夜凉，是皮肤的触觉以及耳朵的听觉听感到的；而“南楼一味凉”的“味”字，还隐含着口舌的味觉在起作用，好像在那里细细地美美地品尝一般。总之，读者的眼睛、鼻子、耳朵、口舌、皮肤种种器官司的视觉、嗅觉、听觉、味觉、触觉种种功能，统统被调动起来，集中起来，共同参与对这南楼夜景的感觉、领略、体验。此景此情，令人生出如临其境的感受，成了自然而然的事。这便是作品的艺术魅力，诗人的艺术追求了。\n\n　　黄庭坚一生，道路崎岖坎坷，由于遭受人陷害中伤，曾贬官司蜀中六年之久；召回才几个月，又被罢官司来武昌闲居。当夜纳凉南楼，眼见明月清风，无拘无束，各行其是，想到自己每欲有所作为，却是动辄得罪，怅恨之情，于是潜滋暗长。“清风明月无人管”，正是诗人这种心绪的自然流露。', poem_tags = '古诗三百首,写景' WHERE poem_title = '鄂州南楼书事' AND poem_author = '黄庭坚';
UPDATE edu_poem SET poem_translation = '夜已阑，月满西楼，深院锁着寂寞的梧桐，秋虫低吟一曲惆怅。你凝视摇红的烛影，不觉睡去，白日所思夜入梦来：“丁巳重阳三日，梦亡妇淡妆素服，执手哽咽……临别有云：‘衔恨愿为天上月，年年犹得向郎圆’。”思念在梦中哽咽着，片片碎了，飞落似春尽溪畔散落的桃花，而爱却如大漠孤坟上的青草，至死都坚持着葱茏之色！你叹，“瞬息浮生，薄命如斯，低徊怎忘？”。你忆，“锈榻闲时，并吹红雨；雕栏曲处，同倚斜阳”。你悲，“梦好难留，诗残莫续，赢得更深哭一场”。风轻云淡，月华如水，今夕何夕？纵有红巾翠袖，谁又能拭你腮边之。\n梦醒了，伊人软语仿佛仍在耳边徘徊，伊人泪眼仿佛仍在眼前婆娑，然而伊人何在？词人竟沉溺于梦境不能自拔，披衣而起，在茫茫“碧落”中“寻寻觅觅”。又有谁能见证这一夜的辗转，一夜的奔波，一夜的背情呢？或许只有早落在头发上的秋霜吧。真是秋霜？还是“朝如青丝暮成雪”（李白《将进酒》）？谁知道呢。“便人间天上，尘缘未断”，“死者长已矣”（杜甫《石壕吏》），又怎么能再续前缘？只有未亡人的回忆、愁绪还在不断的滋长吧！看着曾经一起流连过的“春花秋叶”，又一次勾起了莫名的伤感。怎么能够承受如此痛苦的煎熬？还是把你忘却吧！抹去了你留在我生活中的印痕。然而邻院幽幽的笛声，又一次把你带回我的身旁。“真无奈”！', poem_notes = '丁巳重阳前三日:指康熙十六年(1677}农历九月初六日，即重阳节前三日。此时亡妻已病逝三个多月。\n并吹红雨：唐虞世南《奉和咏风应魏王教》云:“动枝生乱影，吹花送远香。”宋杨万里《九月四日生辰》有“重九吹花节，千龄梦日时”之句，故本谓风吹花动，而后演变为重阳节之意。胡翼龙《满庭芳》：“吹花题叶事，如梦里，记得依然。”是说重阳佳节曾有游赏吟咏之事。纳兰此句是说曾与爱妻共度过美好时光，有所赏心乐事。又，李贺《将进酒》有“桃花乱落如红雨”之句，故红雨指桃花，谓落花时节曾与爱妻共度。\n灵飙：灵风。这里指梦中爱妻飘乎之身影。\n重寻句：语出白居易《长恨歌》：“上穷碧落下黄泉，两处茫茫皆不见。”此谓梦醒之后，爱妻之音容俱逝，天地茫茫，无处可寻，不胜凄怆。\n绸缪：指夫妻之恩爱。\n减尽句：《太平御览》卷七○三引晋习凿齿《襄阳记》云：“刘季和曰:‘荀令君(荀彧)至人家，坐处三日香。’“后以“荀衣”“荀香”“荀令衣香”等，或喻人之风流倜傥，或喻惆怅之情，或喻花卉异香。此处是作者自喻，说自己往日的风流神采早已消损殆尽了。宋刘克庄《风入松?福清道中作》:“改尽潘郎鬓发，消残荀令衣香。”\n邻笛：晋向秀《思旧赋·序》:“余与稳康、吕安居止接近。其人并有不羁之才，然嵇志远而疏，吕心旷而放。其后各以事见法。……余适将西迈，经其旧庐。于时日薄虞渊，寒冰凄然。邻人有吹笛者，发声寥亮。追思囊昔游宴之好，感音而叹，故作赋云。”后多以此典表示笛声凄婉，或表示怀旧伤逝、心绪惆怅等。如袁去华《兰陵王次周美成韵》：“正难续幽梦，厌闻邻笛。”这里是说一声声幽怨哀感、回肠荡气的笛声，更使人怅惘难耐。', poem_appreciation = '词的上片以低婉的叹息起笔，既是叹息亡妻早逝命薄，也是哀叹自己的薄命。接下去写往日的夫妻恩爱情景，反衬出今日永别的苦情，梦醒后的凄清难禁。结穴处再点梦中“只灵飙一转”，为之无限的怅惘，无穷的恨憾。下片进一步刻画苦苦追寻亡妻的踪影和追寻而不可得的沉痛心情。这里用料想之情景表达了对亡妻的爱怜和深深的怀念。结处又以幻境谱叙衷肠。全篇屈曲跌宕，一波三折，低回深婉，哀怨动人。', poem_tags = '婉约,重阳节,叹息,怀念' WHERE poem_title = '沁园春·丁巳重阳前' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_tags = '抒情,亡国,悲痛' WHERE poem_title = '忆秦娥·烧灯节' AND poem_author = '刘辰翁';
UPDATE edu_poem SET poem_tags = '豪放,记梦,抒怀,思念,壮志难酬' WHERE poem_title = '沁园春·梦孚若' AND poem_author = '刘克庄';
UPDATE edu_poem SET poem_tags = '感伤,失望,感叹' WHERE poem_title = '水龙吟·老来曾识渊明' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '野棠花儿飘落，匆匆又过了清明时节。东风欺凌着路上的行客，竟把我的短梦惊醒。一阵凉气吹来，向我的孤枕袭来，我感到丝丝寒意。在那弯曲的河岸边，我曾与佳人举杯一起饮酒。在垂柳下，我曾在此地与佳人离别。如今人去楼空，只有往日的燕子还栖息在这里，那时的欢乐，只有它能作见证。\n听说在繁华街道的东面，行人曾在帘下见过她的美足。旧日的情事如东流的春江，一去不回，新的遗憾又像云山一样一层层添来。假如有那么一天，我们在酒宴上再相遇合，她将会像镜里的鲜花，令我无法去折。她会惊讶我又白了头发。', poem_notes = '东流：东流县，旧地名。治所在今安徽省东至县东流镇。\n野棠：野生的棠梨。\n匆匆：形容时间过得飞快的样子。唐牟融《送客之杭》诗：“西风吹冷透貂裘，行色匆匆不暂留。”\n刬（chàn）地：宋时方言，相当于“无端地”、“只是”。\n云屏：云母镶制的屏风。寒怯：形容才气或才力不足。\n觞：中国古代的一种盛酒器具。\n系（jì）马：指拴马。\n“楼空”句：苏轼《永遇乐》：“燕子楼空，佳人何在？空锁楼中燕。”\n绮陌：多彩的大道，宋人多用以指花街柳苍。\n纤纤月：形容美人足纤细。刘过《沁园春》（咏美人足）：“知何似，似一钩新月，浅碧笼云。”\n料得：预测到；估计到。明朝（zhāo）：以后，将来。\n尊：指酒器。重见（ jiàn）：重新相见，重新遇到。\n华发：花白的头发。《墨子·修身》：“华发隳颠，而犹弗舍者，其唯圣人乎？”', poem_tags = '婉约,游子,思念,爱情' WHERE poem_title = '念奴娇·书东流村壁' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '月圆之夜，大型宫廷歌舞酒宴。出场前先是画妆。因是晚妆，为了适合舞场与烛光，画眉点唇，都不妨色泽浓艳。宫娥们刚画完妆的一刻，是何等光彩照人呀！妆毕，春殿上美女如云，她们队列整齐，鱼贯而入，虽是层层娇娘的行列，望之也顿生军旅的浩荡之感。\n歌罢宴散，月色更明。当即吩咐随从灭尽红烛，纯任得得马蹄，踏着一路月色归去，方见得歌舞虽散，而余兴未尽！', poem_notes = '此词调《木兰花》，《全唐诗》注曰：“一名《玉楼春》，一名《春晓曲》，一名《惜春容》。”《草堂诗余》、《词的》、《古今词统》、《古今诗余醉》等本中有题作“宫词”。\n晓妆：一作“晚妆”。《全唐诗》中作“晓妆”。晓妆初了，晓妆刚结束。初了，刚刚结束。明肌雪：形容肌肤明洁细腻，洁白如雪。\n春殿：即御殿。以其豪华、盛大而称“春殿”。李白《越中览古》诗有“宫女如花满春殿”之句。嫔（pín）娥：这里泛指宫中女子。鱼贯列：像游鱼一样一个挨一个地依次排列，这里指嫔娥依次排列成行的样子。\n笙箫吹断水云间：笙箫，《词综》、《历代诗余》、《古今词统》、《全唐诗》等本作“凤箫”。《花草粹编》作“笙歌”。笙箫，笙和箫，泛指管乐器。吹断，吹尽。水云间，吕本二主词、侯本二主词、吴本二主词于“间”处空格。《全唐诗》、《花草粹编》、《古今词统》、《词综》等本中均作“水云闲”；《松隐文集》作“水云中”。水云间即水和云相接之处，谓极远。\n重按霓（ní）裳歌遍彻：重按，一再按奏。按，弹奏。霓裳，《霓裳羽衣曲》的简称。唐代宫廷著名法曲，传为唐开元年间河西节度使杨敬忠所献。初名《婆罗门曲》，后经唐玄宗润色并配制歌词，后改用此名。唐白居易《琵琶行》中有句：“轻拢慢捻抹复挑，初为《霓裳》后《六幺》。”歌遍彻，唱完大遍中的最后一曲，说明其歌曲长、久，音调高亢急促。遍，大遍，又称大曲，即整套的舞曲。大曲有排遍、正遍、遍、延遍诸曲，其长者可有数遍之多。彻，《宋元戏曲史》中云：“彻者，入破之末一遍也”，六一词《玉楼春》有“重头歌韵响铮，入破舞腰红乱旋”之句，可见曲至入破以后则高亢而急促。\n临春：《词综》、《历代诗余》、《古今词统》、《全唐诗》等本中均作“临风”。郑骞《词选》中云：“临春，南唐宫中阁名，然作‘临风’则与‘飘’字有呼应，似可并存。”香屑：香粉。飘香屑：相传后主宫中的主香宫女，拿着香粉的粉屑散布于各处。\n醉：心醉、陶醉。拍：拍打，这里兼有为乐曲击出拍节之意。阑干：即栏杆。情味：《花草粹编》、《词谱》、《全唐诗》、《词林纪事》等本中均作“情未”。切：恳切，真挚而迫切的心情。\n归：回。休放：《词综》、《词谱》、《历代诗余》、《全唐诗》等本中同此。萧本二主词、吕本二主词、吴本二主词、《词林纪事》、《类编草堂诗余》等本中均作“休照”。烛光：晨本二主词中同此；吕本二主词、吴本二主词、萧本二主词、《花草粹编》、《词综》、《词谱》、《全唐诗》等本中均作“烛花”。烛光红，指明亮的烛光。\n待踏：《词综》、《历代诗余》、《词谱》、《全唐诗》等本中同此。吕本二主词、萧本二主词、吴本二主词、《类编草堂诗余》等本中均作“待放”。踏马蹄：策马缓慢而行，有踏月之意。有本作“放马蹄”，意为让马随意而行。', poem_appreciation = '此词是李煜于南唐全盛时期所创作的一篇代表作。词的上片主要写春夜宴乐的盛大场面。首句突出描绘“晚妆初了”的嫔娥们的盛妆和美艳，由此写出作者对这些明艳丽人的一片飞扬的意兴，同时从开篇即渲染出夜宴的奢华豪丽。继之两句宴乐开始，歌舞登场，作者极写音乐的悠扬和器物的华美。比如，笙箫二字可以给人一种精美、奢丽的感觉，与词中所描写的奢靡之享乐生活、情调恰相吻合。而“吹”作“吹断”，“按”作“重按”，不但字字可见作者的放任与耽于奢逸，而且十分传神地赋予音乐以强烈的感情色彩。据马令《南唐书》载：“唐之盛时，《霓裳羽衣》最为大典，罹乱，瞽师旷职，其音遂绝。后主独得其谱，乐工曹生亦善琵琶，按谱粗得其声，而未尽善也。（大周）后辄变易讹谬，颇去哇淫，繁手新音，清越可听。”李煜与大周后都精通音律，二人情爱又笃深，更何况《霓裳羽衣》本为唐玄宗时的著名大曲，先失后得，再经过李煜和周后的发现和亲自整理，此时于宫中演奏起来，自然欢愉无比。所以不仅要“重按”，而且要“歌遍彻”，由此也可想见作者之耽享纵逸之情。\n\n　　词的下片是描写曲终人散、踏月醉归的情景。“临春”一句明是写香，暗是写风，暗香随风飘散，词人兴致阑珊，由“谁更”二字而出，更显得活泼有致。“醉拍”二字直白而出，写醉态，写尽兴尽欢妥贴至极。到这里，作者有目见的欣赏，有耳听的享受，有闻香的回味，加上醉拍由口饮而生的意态，正是极色、声、香、味之娱于一处，心旷神驰，兴奋不已，因此才“情味切”，耽溺其中无以自拔。结尾二句，写酒阑歌罢却写得意味盎然，余兴未尽，所以向来为人所称誉。《弇州山人词评》中赞其为“致语也”。今人叶嘉莹曾详评此句：“后主真是一个最懂得生活之情趣的人。而且‘踏马蹄’三字写得极为传神，一则，‘踏’字无论在声音或意义上都可以使人联想到马蹄得得的声音；再则，不曰‘马蹄踏’而曰‘踏马蹄’，则可以予读者以双重之感受，是不仅用马蹄去踏，而且踏在马蹄之下的乃是如此清夜的一片月色，且恍闻有得得之声入耳矣。这种纯真任纵的抒写，带给了读者极其真切的感受。”读此二句，既可感作者的痴醉心情，也可视清静朗洁的月夜美景，更可见作者身上充盈着的文人骚客的雅致逸兴。\n\n　　全词笔法自然奔放，意兴流畅挥洒，语言明丽直快，情境描绘动人。作者从个人宫廷生活场面出发，虽然带有较为浓郁的富贵脂粉气，未能表现出深刻的思想内容，但短短一篇就把一次盛大欢宴的情形淋漓尽致地表现出来，艺术描绘生动逼真，情景刻画细腻动人，由喻象中见情思，于浅白处见悠远，充分显示了作者高妙的艺术功力，是“写得极为俊逸神飞的一首小词”。', poem_tags = '宴饮,音乐,生活' WHERE poem_title = '木兰花·晚妆初了明肌雪' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '流莺儿啊，到处飘荡，上下翻飞；越过小路，临近河边，无法自持。\n美妙地鸣啭，怎么能没有本意？碰到了良辰，也未必就有佳期。\n鸣啭在风朝霞夜阴晴之日，鸣啭在千门万户开闭之时。\n我曾经苦于伤春而不忍再听，京城哪里有可以栖息的花枝？', poem_notes = '流莺：指漂荡流转、无所栖居的黄莺。\n参差：参差，本是形容鸟儿飞翔时翅膀张敛振落的样子，这里用如动词，犹张翅飞翔。\n不自持：不能自主，无法控制自己。\n啭（zhuàn）：鸟宛转地鸣叫。\n佳期：美好的时光。南朝齐谢朓《晚登三山还望京邑》诗：“佳期怅何许，泪下如流霰。”\n“风朝”二句：《汉书·郊祀志》：“作建章宫，度为千门万户。”《汉书·东方朔传》：“起建章宫，左凤阙，右神明，号千门万户。”此联写京华莺声，无论风露阴晴、门户开闭，皆漂荡啼啭不已。\n不忍：一作“不思”。\n凤城：此借指京城长安。冯注引赵次公注杜诗：“弄玉吹箫，凤降其城，因号丹凤城。其后曰京师之盛曰凤城”。花枝：指流莺栖息之所。此句言凤城虽有花枝，而流莺难以借寓，故有伤春之苦吟，而令人不忍卒听。', poem_appreciation = '张《会笺》系此诗为大中三年（849）春长安之作。此诗乃苦闷之词，写自己仕途穷困，漂泊无定所，怀才不遇知音，心意无人理解。全诗咏物抒情，借流莺自喻，寄托身世之感。清陆昆曾《李义山诗解》云：“此作者自伤漂荡，无所归依，特托流莺以发叹耳。渡陌临流，喻己之东川、岭表，身不由己也。“此诗风格轻倩流美，情思深婉。张《会笺》曰：“含思宛转，独绝今古。“\n\n　　这是李商隐托物寓怀、抒写身世之感的诗篇。写作年份不易确定。从诗中写到“漂荡”、“巧啭”和“凤城”来看，可能是“远从桂海，来返玉京”以后所作。宣宗大中三年（849）春，作者在长安暂充京兆府掾属，“天官补吏府中趋，玉骨瘦来无一把”（《偶成转韵》），应是他当时生活和心情的写照。\n\n　　流莺，指漂荡流转、无所栖居的黄莺。诗的开头两句，正面重笔写“流”字。参差，本是形容鸟儿飞翔时翅膀张敛振落的样子，这里用如动词，犹张翅飞翔。漂荡复参差，是说漂荡流转之后又紧接着再飞翔漂泊。“度陌”、“临流”，则是在不停地漂荡流转中所经所憩，应上句“复”字。流莺这样不停地漂泊、飞翔，究竟是为什么呢？又究竟要漂荡到何时何地呢？诗人对此不作正面交代，只淡淡接上“不自持”三字。这是全联点眼，暗示出流莺根本无法掌握自己的命运，仿佛是被某种无形的力量控制着。用流莺的漂荡比喻诗人自己的辗转幕府的生活，是比较平常的比兴寓托，独有这“不自持”三字，融和着诗人的独特感受。诗人在桂林北返途中就发出过怅然的叹息：\n\n　　“昔去真无奈，今还岂自知”（《陆发荆南始至商洛》）。“去真无奈”、“还岂自知”，正象是“不自持”的注脚。它把读者的思绪引向“漂荡复参差”的悲剧身世后面的社会原因，从而深化了诗的意境。\n\n　　漂荡流转，毕竟是流莺的外在行动特点，接下来三、四两句，便进一步通过对流莺另一特点—— 巧啭的描写，来展示它的内心苦闷。“巧啭岂能无本意，良辰未必有佳期。”流莺那圆转流美的歌吟中分明隐藏着一种殷切的愿望—— 希望在美好的三春良辰中有美好的相会。然而，它那“巧啭”中所含的“本意”却根本不被理解，因而虽然适逢春日芳辰也不能盼来“佳期”，实现自己的愿望。如果说，流莺的漂泊是诗人飘零身世的象征，那么流莺的巧啭便是诗人美妙歌吟的生动比喻。它的独特之处，就在于强调巧啭中寓有不为人所理解的“本意”，这“本意”可以是诗人的理想抱负，也可以是诗人所抱的某种政治遇合的期望。这一联和《蝉》的颔联颇相似。但“五更疏欲断，一树碧无情”所强调的是虽凄楚欲绝而不被同情，是所处环境的冷酷；而“巧啭”一联所强调的却是巧啭本意的不被理解，是世无知音的感叹。“岂能”、“未必”，一纵一收，一张一弛，将诗人不为人所理解的满腹委屈和良辰不遇的深刻伤感曲曲传出，在流美圆转中有回肠荡气之致。可以说这两句诗本身就是深与婉的统一。\n\n　　颈联承上“巧啭”，仍写莺啼。“风朝露夜阴晴里，万户千门开闭时。”这是“本意”不被理解、“佳期”不遇的流莺永无休无止的啼鸣：无论是刮风的早晨还是降露的夜晚，是晴明的天气还是阴霾的日子，无论是京城中万户千门开启或关闭的时分，流莺总是时时处处在啼啭歌吟。它仿佛执着地要将“本意”告诉人们，而且在等待着渺茫无尽的佳期。这一联是两个略去主、谓语的状语对句构成的，每句中“风朝”与“露夜”、“阴”与“晴”、“万户”与“千门”、“开”与“闭”又各自成对，读来别有一种既整饬又优美，既明畅又含蓄的风调。\n\n　　尾联联系到诗人自身，点明“伤春”正意。“凤城”借指长安，“花枝”指流莺栖息之所。两句是说，自己曾为伤春之情所苦，实在不忍再听流莺永无休止的伤春的哀鸣，然而在这广大的长安城内，又哪里能找到可以栖居的花枝呢？初唐诗人李义府《咏乌》云：\n\n　　“上林多少树，不借一枝栖。”末句从此化出。伤春，就是伤佳期之不遇；佳期越渺茫，伤春的情绪就越浓重。三春芳辰就要在伤春的哀啼中消逝了，流莺不但无计留春，而且连暂时栖息的一枝也无从寻找。这已经是杜鹃啼血般的凄怨欲绝的情境了。诗人借“不忍听”流莺的哀啼强烈地抒发了自己的“伤春”之情—— 抱负成空、年华虚度的精神苦闷。末句明写流莺，实寓自身，读来既像是诗人对无枝可栖的流莺处境的关心，又像是诗人从流莺哀啼声中听出的寓意，更像是诗人自己的心声，语意措辞之精妙，可谓臻于化境。', poem_tags = '咏物,抒情,写鸟,身世' WHERE poem_title = '流莺' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '锦江西面烟波浩瀚水碧绿，雨后山坡上荔枝已经成熟。\n城南万里桥边有许多酒家，来游的人喜欢向谁家投宿？', poem_notes = '锦江：在四川省，流经成都。\n烟水：雾霭迷蒙的水面。\n万里桥：桥名，在成都城南。\n爱向：爱戴归向。', poem_appreciation = '这是张籍游成都时写的一首七绝，诗通过描写成都市郊的风物人情和市井繁华景况，表现了诗人对太平生活的向往。因为这诗不拘平仄，所以用标乐府体的“曲”字示之。\n\n　　锦江，以江水清澄、濯锦鲜明而著称。它流经成都南郊，江南为郊野，江北为市区，江中有商船。地兼繁华、幽美之胜。诗的前两句展现诗人顺锦江西望时的美景。新雨初霁，在绿水烟波的背景下，山头岭畔，荔枝垂红，四野飘溢清香。那如画的景色十分诱人。这两句写眼前景，景中含情，韵味深长，如跳动的音符，悠扬的旋律，拨动了人们的心弦。\n\n　　上面写郊野景色，后两句则是由于“桥”和“酒家”的跳入眼帘，逗引起人们对市井繁华情况的想象。桥下水入岷江流至宜宾，与金沙江合为长江，东流直达南京，唐时商贾往来，船只很多。“万里桥边多酒家，游人爱向谁家宿？”唐时酒家多留宿客人。读了这两句，使人由“万里桥”而想到远商近贾，商业兴盛，水陆繁忙；由“多酒家”想到游人往来，生意兴隆。最后说：游人呀，你究竟选择那一酒家留宿更称心如意呢？从这问人和自问的语气里，使人想到处处招待热情、家家朴实诚恳的风土人情和店店别具风味、各有诱人“闻香下马”的好酒。处处酒家好，反而不知留宿何处更好了。\n\n　　沈德潜说：“七言绝句，以语近情遥、含吐不露为主；只眼前景，口头语，而有弦外音，味外味，使人神远。”（《说诗晬语》）张籍此诗，句句含景，景景有情，特别是后二句，近似口语，却意味深远，读后感到精警而又自然。诗人既善于抓住富于特征的一般景物，又善于抓住思绪中最闪光的一瞬间——“游人爱向谁家宿？”这样就能使一篇之朴，养一句之神；一句之灵，回一篇之运。这就是张籍“看似寻常最奇崛”之风格所在，也是诗作具有弦外音、味外味、使人神远的艺术魅力之所在。', poem_tags = '地名,写景' WHERE poem_title = '成都曲' AND poem_author = '张籍';
UPDATE edu_poem SET poem_translation = '交交黄鸟鸣声哀，枣树枝上停下来。是谁殉葬从穆公？子车奄息命运乖。谁不赞许好奄息，百夫之中一俊才。众人悼殉临墓穴，胆战心惊痛活埋。苍天在上请开眼，坑杀好人该不该!如若可赎代他死，百人甘愿赴泉台。\n交交黄鸟鸣声哀，桑树枝上歇下来。是谁殉葬伴穆公？子车仲行遭祸灾。谁不称美好仲行，百夫之中一干才。众人悼殉临墓穴，胆战心惊痛活埋。苍天在上请开眼，坑杀好人该不该!如若可赎代他死，百人甘愿化尘埃。\n交交黄鸟鸣声哀，荆树枝上落下来。是谁殉葬陪穆公？子车针虎遭残害。谁不夸奖好针虎，百夫之中辅弼才。众人悼殉临墓穴，胆战心惊痛活埋。苍天在上请开眼，坑杀好人该不该!如若可赎代他死，百人甘愿葬蒿莱。', poem_notes = '交交：鸟鸣声。马瑞辰《毛诗传笺通释》：“交交，通作‘咬咬’，鸟声也。”黄鸟：即黄雀。\n棘：酸枣树。一种落叶乔木。枝上多剌，果小味酸。棘之言“急”，双关语。\n从：从死，即殉葬。穆公：春秋时秦国国君，姓嬴，名任好。\n子车：复姓。奄息：字奄，名息。下文子车仲行、子车针虎同此，这三人是当时秦国有名的贤臣。\n特：杰出的人材。\n“临其穴”二句：郑笺（jiān）：“谓秦人哀伤其死，临视其圹，皆为之悼栗。”\n彼苍者天：悲哀至极的呼号之语，犹今语“老天爷哪”。\n良人：好人。\n人百其身：犹言用一百人赎其一命。\n桑：桑树。桑之言“丧”，双关语。\n防：抵当。郑笺：“防，犹当也。言此一人当百夫。”\n楚：荆树。楚之言“痛楚”。亦为双关。', poem_appreciation = '诗分三章。第一章悼惜奄息，分为三层来写。首二句用“交交黄鸟，止于棘”起兴，以黄鸟的悲鸣兴起子车奄息被殉之事。据马瑞辰《毛诗传笺通释》的解释，“棘”之言“急”，是语音相谐的双关语，给此诗渲染出一种紧迫、悲哀、凄苦的氛围，为全诗的主旨定下了哀伤的基调。中间四句，点明要以子车奄息殉葬穆公之事，并指出当权者所殉的是一位才智超群的“百夫之特”，从而表现秦人对奄息遭殉的无比悼惜。\n\n　　诗的后六句为第三层，写秦人为奄息临穴送殉的悲惨惶恐的情状。“惴惴其栗”一语，就充分描写了秦人目睹活埋惨象的惶恐情景。这惨绝人寰的景象，灭绝人性的行为，使目睹者发出愤怒的呼号，质问苍天为什么要“歼我良人”。这是对当权者的谴责，也是对时代的质询。“如果可以赎回奄息的性命，即使用百人相代也是甘心情愿的啊！”由此可见，秦人对“百夫之特”的奄息的悼惜之情了。第二章悼惜仲行，第三章悼惜针虎，重章叠句，结构与首章一样，只是更改数字而已。\n\n　　秦穆公用殉177人，而作者只痛悼“三良”，那174个奴隶之死却只字未提，则此诗作者的身分地位不言而喻。殉葬的恶习，春秋时代各国都有，相沿成习，不以为非。《墨子·节葬》篇即云：“天子杀殉，众者数百，寡者数十；将军大夫杀殉，众者数十，寡者数人。”不过到了秦穆公的时代，人们已清醒地认识到人殉制度是一种极不人道的残暴行为，《黄鸟》一诗，就是一个证据。尽管此诗作者仅为“三良”遭遇大鸣不平，但仍然是历史的一大进步。', poem_tags = '诗经,悼亡' WHERE poem_title = '国风·秦风·黄鸟' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '葫芦瓜有苦味叶，济水边有深渡口。深就垂衣缓缓过，浅就提裙快快走。\n\n济水茫茫涨得满，岸丛野雉叫得欢。水涨车轴浸不到，野雉求偶鸣声传。\n\n又听嗈嗈大雁鸣，天刚黎明露晨曦。男子如果要娶妻，趁未结冰来迎娶。\n\n船夫挥手频招呼，别人渡河我不争。别人渡河我不争，我将恋人静静等。', poem_notes = '匏（páo袍）：葫芦之类。苦：一说苦味，一说枯。意指葫芦八月叶枯成熟，可以挖空作渡水工具。\n济：水名。涉：一说涉水过河，一说渡口。\n厉：带。一说解衣涉水，一说拴葫芦在腰泅渡。\n揭（qì气）：提起下衣渡水。\n弥（mí弥）：大水茫茫。盈：满。\n鷕（yǎo咬）：雌山鸡叫声。\n不濡（音如）：不，语词；濡，沾湿。轨：车轴头。\n牡：雄雉。\n雝雝（yōng拥）：大雁叫声和谐。\n旦：天大明。\n归妻：娶妻。\n迨（dài带）：及，等到；乘时。泮（pàn盼）：分，此处当反训为“合”。冰泮，指冰融化。\n招招：招唤之貌，一说摇橹曲伸之貌。舟子：摆渡的船夫。\n人涉：他人要渡河。卬：（áng昂），代词，表示“我”。否：不（渡河）。卬否：即我不渡河之意。\n须：等待。友：指爱侣。', poem_appreciation = '期盼的爱情充满了喜悦，而爱情的等待，却又令人焦躁。这首诗所歌咏的，正是一位年轻女子对情人的又喜悦、又焦躁的等候。\n\n　　这等候发生在济水渡口。从下文交代可知，女主人公大抵一清早就已来了。诗以“匏有苦叶”起兴，即暗示了这等候与婚姻有关。因为古代的婚嫁，正是用剖开的匏瓜，做“合卺”喝的酒器的。匏瓜的叶儿已枯，则正当秋令嫁娶之时。女主人公等候的渡口，却水深难涉了，因此她深情地叮咛着：“深则厉，浅则揭”。那无非是在心中催促着心上人：水浅则提衣过来，水深就垂衣来会，就不必犹豫了。催对方垂衣涉济，正透露出她这边等候已急。\n\n　　诗中说：现 在天已渐渐大亮，通红的旭日升起在济水之上，空中已有雁行掠过，那“雝雝”鸣叫显得有多欢快。但对于等候中的女主人公来说，心中的焦躁非但未被化解，似乎更还深了几分。要知道雁儿北飞，预告着冬日就要结束，春天就要到来。当济水冰融化的时候，按古代的规矩便得停办嫁娶之事了。所谓“霜降而妇功成，嫁娶者行焉；冰泮而农业起，昏（婚）礼杀（止）于此”（《孔子家语》），说的就是这一种古俗。明白乎此，就能懂得女主人公何以对“雝雝鸣雁”特别关注了：连那雁儿都似在催促着姑娘，她就不能不为之着急。于是“士如归妻，迨冰未泮（合）”二句，读来正如发自姑娘心底的呼唤，显得十分热切。\n\n　　诗之末章终于等来了摆渡船，那定是从对岸驶来载客的。船夫大约早就体察了女主人公的焦躁不安，所以关切地连声招唤：“快上船吧！”他不可能知道，这姑娘急的并不是过河，恰是在驶来的船上没见到心上人。“人涉昂否”二句之重复，重复得可谓妙极：那似乎是女主人公怀着羞涩，对船夫所作的窘急解释——“不是我要急着渡河，……不是的，我是在等我的……朋友哪……”以“昂须我友”的答语作结，结得情韵袅袅。船夫的会意微笑，姑娘那脸庞飞红的窘态，以及将情人换作“朋友”的掩饰之辞，所传达的似怨还爱的徽妙心理，均留在了诗外，任读者自己去体味。\n\n　　据毛诗旧序称，此诗为“刺”卫宣公与夫人“并为淫乱”之作；连颇不尊序的清人姚际恒《诗经通论》，亦以为“其说可从”。这真不知从何说起。拂去旧说之附会，此诗实在就是一首等候“未婚夫”“赶快过来迎娶”（余冠英《诗经选》）的绝妙情诗。', poem_tags = '诗经,爱情' WHERE poem_title = '匏有苦叶' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '运行万里而来的瞿塘峡的月亮，今春以来已经是第六次出现上弦月了。\n月光常常照亮我幽暗的居室，洒满无垠的蓝天。\n月光静静洒下，凉爽透过衣襟，格外宜人；月亮高高地悬挂天空，空自对着我挂满泪痕的脸，竟无动于衷。\n有一只南飞的乌鹊，在月下盘旋良久，无枝可依，只好落在江边。', poem_notes = '万里：言月运行万里而来，又暗喻漂泊万里的诗人。\n瞿唐：瞿塘峡，位于长江三峡奉节至巫山段，安史之乱后，杜甫曾困居于此。\n春来：今春以来。\n上弦：上弦月，农历每月初七、初八的弓形月亮。\n时时：常常。与“故故”变文同义。\n开：指照亮。满：指月光洒满。\n青天：蓝天。\n爽：清爽，凉爽。\n合：环绕，充满。\n风襟：衣襟。宋玉《风赋》：“有风飒然而至，王乃披襟而当之。”\n当：对着。\n悬：悬挂天空。\n乌鹊：乌鸦。\n夜久：夜深。', poem_appreciation = '“万里瞿唐月，春来六上弦”：“万里”，作者先在读者面前展现了一个大的背景，然后现一轮孤月。使人感到，天地之中，作为个体的诗人孤独寂寞之情。“六上弦”从时间的角度写时间之久，与“夜久”相呼应，表明长期在外漂泊的厌倦。\n\n　　“时时开暗室，故故满青天”：主体仍然是月，有情开室，但满眼望去仍然是漫天的清辉。独处陋室，浴漫天清辉，那是一种什么样的凄清孤独啊！叠词的运用还构成了节奏的美。\n\n　　“爽合风襟静，高当泪脸悬”：“爽”该是“清朗”之意，“合”当是“匹配”之意；清朗的月色加细风，可以很美妙，可以很凄凉；“高”句语序该是“（月）高悬对泪脸”化被动为主动，既是题目的需求，也是诗歌新奇的需要。也有人说“风襟”是“外衣”的意思，本人认为有点太实，好像词典也没有这一词语（或许太过孤陋）。\n\n　　“南飞有乌鹊，夜久落江边”：这一句写南飞的鸟急于回归，疲倦的落在江边栖息。可以看做诗人的自况。\n\n　　杜甫一生颠沛流离，漂泊不定，经常远离故乡远离亲人。对于自己的家乡、亲人，他是思念情切，刻骨铭心。全诗以明月兴思情，同一轮明月寄寓着两地彼此的思念，思情的悠远绵长与月夜的孤独寂寞，相织相融，形成一种清丽深婉、寂寥苦思的凄清氛围，使读者不觉之间与之同悲共泣。一生颠沛流离，漂泊不定，经常远离故乡远离亲人。对于自己的家乡、亲人，他是思念情切，刻骨铭心。全诗以明月兴思情，同一轮明月寄寓着两地彼此的思念，思情的悠远绵长与月夜的孤独寂寞，相织相融，形成一种清丽深婉、寂寥苦思的凄清氛围，使读者不觉之间与之同悲共泣。', poem_tags = '月亮,孤独,思念' WHERE poem_title = '万里瞿塘月' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '是组诗《竹枝词九首》的最后一首。这首诗是一幅巴东山区人民生活的风俗画。它不是一般的模山范水，不是着力于表现山水的容态精神，而是从中发掘出一种比自然美更为可贵的劳动的美，创造力的美。\n\n　　“山上层层桃李花，云间烟火是人家。”开头用一个“山”字领起，一下子把诗人面对春山、观赏山景的形象勾画出来了。俗谚说：“桃花开，李花败。”一般是李花先开，桃花后开。现在桃花、李花同时盛开，这是山地气候不齐所特有的景象。“层层”状桃李花的繁茂与普遍。此山彼山，触处皆是。那种色彩绚烂、满山飘香的景象可以想见。次句由景及人。“云间”形容山顶之高。诗人遥望山顶，在花木掩映之中，升起了袅袅的炊烟', poem_appreciation = '这是组诗《竹枝词九首》的最后一首。这首诗是一幅巴东山区人民生活的风俗画。它不是一般的模山范水，不是着力于表现山水的容态精神，而是从中发掘出一种比自然美更为可贵的劳动的美，创造力的美。\n\n　　“山上层层桃李花，云间烟火是人家。”开头用一个“山”字领起，一下子把诗人面对春山、观赏山景的形象勾画出来了。俗谚说：“桃花开，李花败。”一般是李花先开，桃花后开。现在桃花、李花同时盛开，这是山地气候不齐所特有的景象。“层层”状桃李花的繁茂与普遍。此山彼山，触处皆是。那种色彩绚烂、满山飘香的景象可以想见。次句由景及人。“云间”形容山顶之高。诗人遥望山顶，在花木掩映之中，升起了袅袅的炊烟。他推断，这一定是村民聚居之处。“是人家”三字是诗人注意力的归着点。“是”字下得醒豁，表明诗人探寻的目光越过满山的桃李，透过山顶的云雾，终于找到了绣出这满山春色的主人的所在，美是由人创造的。山美、花木美，都来自山村居民的劳动之美。以下即转为富有地方色彩的山村居民的劳动场景的描画。\n\n　　“银钏金钗来负水，长刀短笠去烧畲。”两句写山村居民热气腾腾的劳动生活。挎着长刀、戴着短笠的男人们根据传统的办法前去放火烧荒，准备播种；戴着饰物的青年妇女们下山担水，准备做饭。在这里，作者运用了两种修辞手法。一、借代。用“银钏金钗”借代青年妇女，用“长刀短笠”借代壮年男子，正好捕捉了山民男女形象的特征，具有浓厚的地方色彩。二、对仗。不仅上下两句相对，而且还采用了句中自为对（即当句对）的办法，把语言锤打得十分凝炼。\n\n　　全诗短短四句，每句一景，犹如四幅画图，孤立起来看，有其相对的独立性，合起来看，恰好构成一个完满的艺术整体。由满山的桃李花引出山村人家，又由山村人家引出劳动男女戮力春耕的情景，全诗至此戛然而止，而把妇女们负水对歌、烧畲时火光烛天以及秋后满山金黄等情景统统留给读者去想象，画面的转接与安排极有理致。诗中没有直接发出赞美，但那种与劳动生活的旋律十分合拍的轻快的节奏，那种着力描绘创造力之美的艺术构思，都隐隐透露出诗人欣喜愉快的心情和对劳动生活的赞叹。刘禹锡贬谪巴山楚水之时，接近了人民，南国的风土人情，激荡了他的诗情，丰富和提高了他的艺术情趣，使他在美的探索中扩大了视野，在审美鉴赏力和表现力方面，都有了新的突破。', poem_tags = '生活,风俗' WHERE poem_title = '竹枝词九首·其九' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '我家住在有着苍茫如烟的云气和夕阳晚照的乡间，\n与世上的事情毫不相关。\n喝完了玉瀣就散步穿过了竹林；\n看完了《黄庭》就躺下来观赏山中美景。\n贪图的是任意放纵，蔑视世俗的生活，任凭自己在这种无拘无束的生活中衰老，\n别妨碍自己的处处开心，\n本来就知道上天另有一种心肠，\n就是使英雄无所作为地衰老就像是对待平常是一样。', poem_notes = '玉瀣（xiè）：美酒。\n《黄庭》：道家经典著作，论养生之道。\n啸傲：放歌长啸，傲然自得。\n元：通假字，同“原”，本来。', poem_appreciation = '刘克庄《后村诗话续集》把陆游的词分为三类：“其激昂慷慨者，稼轩不能过；飘逸高妙者，与陈简斋、朱希真相颉颃；流丽绵密者，欲出晏叔原、贺方回之上。”这首《鹧鸪天》可以算是陆游飘逸高妙一类作品中的代表作之一。\n\n　　上阕开头二句：“家住苍烟落照间，丝毫尘事不相关。”把自己所居住的环境写得是如此的优美而又纯净。“苍烟落照”四字，不禁让人联想起陶渊明《归园田居》其一“蔼蔼远人村，依依墟里烟”的意境，一经讽诵便难以忘怀。“苍烟”犹青烟，字面已包含着作者的感情色彩。“落照”这个词里虽然没有表示颜色的字，但也有色彩暗含其中，引起读者的多种的联想。词人以“苍烟落照”四字点缀自己居处的环境，意在与龌龊的仕途作鲜明的对比。所以在第二句中就直接点明住在这里与尘事毫不相关，可以一尘不染，安心地过着隐居的生活。这也正是陶渊明《归园田居》里“户庭无尘杂，虚室有余闲”的体现。\n\n　　三、四句对仗工稳：“斟残玉瀣行穿竹，卷罢《黄庭》卧看山。”“玉瀣”是一种美酒的名称，明人冯时化在《酒史》卷上写有：“隋炀帝造玉瀣酒，十年不败。”陆游在诗中也不止一次写到过这种酒。“黄庭”是道经的名称，《云笈七签》胡《黄庭内景经》、《黄庭外景经》、《黄庭遁甲缘身经》，都是道家谈论养生之道的书这两句的大意是说：喝完了玉瀣就散步穿过了竹林；看完了《黄庭》就躺下来观赏山中美景。一二句写居处环境的优美，三四句写自己生活的闲适，体现了作者惬意的生活。陆游读的《黄庭经》是卷轴装，所以边读边卷，“卷罢黄庭”就是看完了一卷的意思。\n\n　　下阕开头：“贪啸傲，任衰残，不妨随处一开颜。”“啸傲”，指作者歌咏自得，形容旷放而不受拘束的样子。不单是陆诗用了“啸傲”此词，其他诗人也经常用此词，比如郭璞《游仙诗》：“啸傲遗世罗，纵情在独往。”陶渊明《饮酒》其七：“啸傲东轩下，聊复得此生。”词人说自己贪恋这种旷达的生活情趣，任凭终老田园；随处都能见到使自己高兴的事物，何不随遇而安呢？这几句可以说是旷达到极点也消沉到了极点，可是末尾两句陡然一转：“元知造物心肠别，老却英雄似等闲。”这两句可以说是对以上所写的自己的处境作出了解释。词人说原先就已知道造物者无情（他的心肠与常人不同），它白白地让英雄衰老死去却等闲视之。这难道不是在怨天吗？但同时也是在抱怨南宋统治者无心恢复中原，以致使自己英雄无用武之地。\n\n　　据夏承焘、吴熊和《放翁词编年笺注》中讲到，南宋乾道二年陆游四十二岁，以言官弹劾谓其“交结台谏，鼓唱是非，力说张浚用兵”，免隆兴通判，始卜居镜湖之三山。这首词和其他两首《鹧鸪天》（两首开头句分别为：插脚红尘已是颠、懒向青门学种瓜），都是这时候写下的。词中虽极写隐居之闲适，但那股抑郁不平之气仍然按捺不住，在篇末终于流露出来。也正因为有词人那番超脱尘世的表白，所以篇末的两句就尤其显得冷隽。', poem_tags = '宋词精选,写景,隐居,抒怀' WHERE poem_title = '鹧鸪天·家住苍烟落照间' AND poem_author = '陆游';
UPDATE edu_poem SET poem_tags = '宋词精选,咏物,写花,言志' WHERE poem_title = '卜算子·兰' AND poem_author = '曹组';
UPDATE edu_poem SET poem_translation = '在高楼上眺望而伤感，苦苦地思念着远方的心上人，这样的事何时才能结束呢？看来在这世界上再没有什么东西能比爱情更为强烈的了！离愁别恨正牵连着千丝万缕的柳条纷乱不已，更何况东陌之上，垂柳已是飞絮蒙蒙了呢。我眼前还浮现着你的马儿嘶鸣着，越跑越远，一路不断扬起灰尘的情景，情郎啊，你叫我到哪里寻找你的踪迹呢？\n池水溶溶，一对鸳鸯在戏水，这水南北可通，时见有小船往来。雕梁画栋的楼阁上梯子已经撤去，黄昏以后，依然还是独个儿面对帘栊，望着斜照在它上面的冷冷清清的月亮。怀着深深的怨恨，我反复思量，我的命运竟然不如桃花杏花，它们倒还能嫁给东风，随风而去呢。', poem_notes = '伤高：登高的感概。怀远：对远方征人的思念。穷：穷尽，了结。\n千丝：指杨柳的长条。\n东陌：东边的道路。此指分别处。\n嘶骑：嘶叫的马声。\n小桡：小桨；指代小船。\n梯横：是说可搬动的梯子已被横放起来，即撤掉了。\n栊：窗。\n解：知道，能。嫁东风：原意是随东风飘去，即吹落；这里用其比喻义“嫁”。李贺《南园十三首》诗之一：“可怜日暮嫣香落，嫁与东风不用媒。”', poem_tags = '婉约,相思,爱情,生活' WHERE poem_title = '一丛花令·伤高怀远几时穷' AND poem_author = '张先';
UPDATE edu_poem SET poem_translation = '晚风中的红叶萧萧落下，长亭里痛饮下别酒一瓢。\n天上残云飞回太华山上，稀疏的细雨越过中条岭。\n苍莽的树色随城关远去，黄河呼啸流进遥远海洋。\n明日里就要抵达都城中，我仍在做那渔人樵夫梦。', poem_notes = '阙：指唐都城长安。潼关：关名，在今陕西省潼关县境内。\n红叶晚萧萧：一作“南北断蓬飘”。\n长亭：古时道路每十里设长亭，供行旅停息。\n太华：即西岳华山，在今陕西省华阴县境内。\n过：一作“落”。中条：山名，一名雷首山，在今山西永济县东南。\n山：一作“关”。迥：远。\n海：一作“塞”。\n帝乡：京都，指长安。\n梦：向往。末两句一作“劳歌此分手，风急马萧萧”。', poem_appreciation = '此诗开头两句，诗人先勾勒出一幅秋日行旅图，把读者引入一个秋浓似酒、旅况萧瑟的境界。“红叶晚萧萧”，用写景透露人物一缕缕悲凉的意绪：“长亭酒一瓢”，用叙事传出客子旅途况味，用笔干净利落。此诗另一版本题作“行次潼关，逢魏扶东归”，这个材料，可以帮助读者了解诗人何以在长亭送别、借瓢酒消愁的原委。\n\n　　然而诗人没有久久沉湎在离愁别苦之中。中间四句笔势陡转，大笔勾画四周景色，雄浑苍茫，全是潼关的典型风物。骋目远望，南面是主峰高耸的西岳华山；北面，隔着黄河，又可见连绵苍莽的中条山。残云归岫，意味着天将放晴；疏雨乍过，给人一种清新之感。从写景看，诗人拿“残云”再加“归”字来点染华山，又拿“疏雨”再加“过”字来烘托中条山，这样，太华和中条就不是死景而是活景，因为其中有动势——在浩茫无际的沉静中显出了一抹飞动的意趣。\n\n　　诗人把目光略收回来，就又看见苍苍树色，随关城一路远去。关外便是黄河，它从北面奔涌而来，在潼关外头猛地一转，径向三门峡冲去，翻滚的河水咆哮着流入渤海。“河声”后续一“遥”字，传出诗人站在高处远望倾听的神情。诗人眼见树色苍苍，耳听河声汹汹，把场景描写得绘声绘色，使读者有耳闻目睹的真实感觉。这里，诗人连用四句景句，安排得如巨鳌的四足，缺一不可，丝毫没有臃肿杂乱、使人生厌之感。其中三、四两句，又出现在他的另一首作品《秋霁潼关驿亭》诗的颔联，完全相同，是诗人偏爱的得意之笔。\n\n　　“帝乡明日到，犹自梦渔樵”。本来，离长安不过一天的路程，作为入京的旅客，总该想着到长安后便要如何如何，满头满脑盘绕“帝乡”去打转子了。可是诗人却出人意外地说：“我仍然梦着故乡的渔樵生活呢！”含蓄地表白了他并非专为追求名利而来。这样结束，委婉得体，优游不迫，有力地显出了诗人的身份。', poem_tags = '唐诗三百首,写景,送别' WHERE poem_title = '秋日赴阙题潼关驿楼 / 行次潼关逢魏扶东归' AND poem_author = '许浑';
UPDATE edu_poem SET poem_translation = '天时人事，每天变化得很快，转眼又到冬至了，过了冬至白日渐长，天气日渐回暖，春天即将回来了。\n刺绣女工因白昼变长而可多绣几根五彩丝线，吹管的六律已飞动了葭灰。\n堤岸好像等待腊月快点的过去，好让柳树舒展枝条，抽出新芽，山也要冲破寒气，好让梅花开放。\n我虽然身处异乡，但这里的景物与故乡的没有什么不同之处，因此，让小儿斟上酒来，一饮而尽。', poem_notes = '小至：指冬至前一日，一说指冬至日的第二天\n五纹：指五色彩线。《唐杂录》载，冬至后日渐长，宫中女工比常日增一线之功。添弱线：古代女工刺绣，因冬至后，白天渐长，就可以多绣几根丝线。\n葭：初生的芦苇。琯：古代乐器，用玉制成，六孔，像笛。动浮灰：古时为了预测时令变化，将芦苇茎中的薄膜制成灰，放在律管内，每到节气到来，律管内的灰就相应飞出。浮灰：一作“飞灰”。\n腊：腊月。\n云物：景物。乡国：家乡。\n覆：倾，倒。', poem_tags = '时光,生活' WHERE poem_title = '小至' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '渔舟顺溪而下，追寻那美妙的春景，夹岸桃花映红了古渡口两旁。花树缤纷，忘记了路程远近；行到青溪尽处，忽然隐约似见人烟。走入了幽深曲折的山口，再往前，豁然开朗一片平川。远望去丛丛绿树有如云霞绮聚集，进村见户户门前翠竹鲜花掩映。第一次才听说汉以后的朝代，村民穿戴的还是秦代衣装。他们世代聚居在武陵源，在这里共建了世外田园。明月朗照，松下房栊寂静；旭日升起，村中鸡犬声响起。村人惊讶地把外客迎接，争相邀请，询问那世上的消息。清晨的街巷，家家打扫花径；傍晚的溪边，渔樵乘船回村。当初因避乱世逃出尘寰，寻到这桃源仙境便不归还。从此隐居峡谷，再不管外间变化；世人求访异境，不过是空望云山。渔人不怀疑这是难得的仙境，但凡心未尽只把家园挂牵；出洞后他不顾隔山隔水，又决定辞家来此仙源。自认为来过的地方不会迷路，怎知道眼前的峰壑全然改变。当时曾记得山径幽深，沿青溪几回弯曲才到桃林。此日又逢春天，依然遍地桃花水；仙源何处，已杳杳难寻，不辨道路！', poem_notes = '逐水：顺着溪水。\n古津：古渡口。\n坐：因为。\n一说“行尽青溪忽值人”。见人：遇到路人。\n隈：山、水弯曲的地方。\n旷望：指视野开阔。旋：不久。\n攒云树：云树相连。攒，聚集。\n散花竹：指到处都有花和竹林。\n樵客：原本指打柴人，这里指渔人。\n武陵源：指桃花源，相传在今湖南桃源县（晋代属武陵郡）西南。武陵，即今湖南常德。\n物外：世外。\n房栊：房屋的窗户。\n喧：叫声嘈杂。\n俗客：指误入桃花源的渔人。\n引：领。都邑：指桃源人原来的家乡。\n平明：天刚亮。闾巷：街巷。开：指开门。\n薄暮：傍晚。\n避地：迁居此地以避祸患。去：离开。\n灵境：指仙境。\n尘心：普通人的感情。乡县：家乡。\n游衍：留连不去。\n自谓：自以为。不迷：不再迷路。\n峰壑：山峰峡谷。\n云林：云中山林。\n桃花水：春水。桃花开时河流涨溢。', poem_tags = '唐诗三百首,乐府,写景,写狗古诗18首' WHERE poem_title = '桃源行' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '艳丽的姿色向来为天下器重，美丽的西施怎么能久处低微？\n原先她是越溪的一个浣纱女，后来却成了吴王宫里的爱妃。\n平贱时难道有什么与众不同？显贵了才惊悟她丽质天下稀。\n曾有多少宫女为她搽脂敷粉，她从来也不用自己穿著罗衣。\n君王宠幸她的姿态更加娇媚，君王怜爱从不计较她的是非。\n昔日一起在越溪浣纱的女伴，再不能与她同车去来同车归。\n奉告那盲目效颦的邻人东施，光学皱眉而想取宠并非容易！', poem_notes = '西施：吴越春秋：越得苎萝山鬻薪之女，曰西施，郑旦，饰以罗谷，教以容步，三年学成而献于吴。\n傅香粉：即搽脂敷粉。香：一作“脂”。\n浣纱：环宇记：会稽县东有西施浣纱石。水经注：浣纱溪在荆州，为夷陵州西北，秋冬之月，水色净丽。\n持谢：奉告。\n效颦：庄子：西施病心而颦，其里之丑人见而美之，归亦捧心而效其颦，富人见之，闭门而不出，贫人见之，挈妻子而去之，彼知美颦而不知颦之所以美。按：颦古作膑。\n安可希：怎能希望别人的赏识。', poem_appreciation = '此诗通过借咏西施而抒发现世感愤不平的讽刺诗，语意深微，很有普遍性。诗人通过西施的故事来发表诗人对人生的一点体会。即“贱日岂殊众，贵来方悟稀”的现象。这一现象有两种情况：一是一般人难于辨别好歹，一旦美好事物被发现后，大家才吃惊地感叹艳羡；二是某些人与事物本来也平常无奇，一旦被评为上品或提拔成高官贵妇后，大家就刮目相看，敬佩不已。\n\n　　春秋时越国诸暨芋萝山的美女西施，被越王勾践选送给吴王夫差，成为吴宫邀幸擅宠、娇怜命贵的艳妃，左右了吴王，支配了吴国。当然，西施这样做是有她的政治目的，但王维的本诗并不是取材她的政治图谋，而是用她入官后艳色凌人，写令人感到厌恶的恃宠擅权的官场世态。\n\n　　开始两句从通常世态的角度提出了一个很有概括性的问题：“艳色天下重，西施宁久微?”是说：天下入好德者少，重色者多，有这种社会习俗，象西施那样的人物，安能长久地处于微贱之地?因此生活中象西施这样的人物，会有被尊贵的一天，只是时机之遇的早晚。这两句是对取人不重德能的当政者的讥讽，并同时表明，那些得势者一朝之内便娇骄得判若两人，根源还在于重色者。\n\n　　三四句“朝为越溪女，暮作吴宫妃”，是前两句中的有“重”而不“微“的一个突出的事实证明。一个越国的山村中的普通女子，一朝之间身价十倍，原因就是因为遇到了重艳色的人；重色人有多大权力，有色者就有多么贵重，如此的逻辑适合于说明历史上的一切权臣和宠姬。王维就是借宠姬而抨击权臣的，鄙视权臣并不是以自身的德能显出贵重的意义，而是借“重”而“贵”的，王维提醒当权的不要忘乎所以，用意是很尖刻的。\n\n　　从第五句“贱日岂殊重”开始，到“莫得同车归”，连续八句，是对“西施”的讥刺，针对性是世俗心理和那些得宠后便殊众自贵、颐指气使的娇骄者。在王维看来，有一种社会性的心理惰性，就是一个美的事物，被埋没的时候谁也看不出它的“殊众”之处，而一旦被人发现了之后，它就成了世上稀有的宝贝。诗人认为西施就是这种心理的一个代表对象。诗人好象要问一问西施：“当年你在苎萝村溪边浣纱时，你意识到你自己是那么天下少有吗？比所有的浣纱姑娘都美吗？可为什么一进吴官，成为贵人，便感到自己成了稀世之珍呢？”对于自贵自稀的人，王维最鄙夷那种“君宠益娇态，君怜无是非”的得幸者，得幸者愈宠愈娇，借高权保护，唯己为是，非己为非，以致到了无有是非的程度。王维在仕途里不乏坎坷，接触了不少炙手可热的权臣，诗人很憎恶这种人，此刻诗人指着西施，一点也不客气地针砭了这些小人。诗中主要不是评价历史上的西施。\n\n　　诗的最后两句：“持谢邻家子，效颦安可希?”这是归结性的道德评价。这里包含的意义是很复杂的。在时间上，诗人回到了西施的时代，找到了那个被人传为笑柄的东施，向东施致语。向西施效颦学不到真西施的样子，又告诉她：这样的西施怎么可能学得了，况且她“君宠益娇态，君怜无是非“，再不屑与当年浣纱伴为伍了，没有什么可效之处。王维的话当时的人是听得见的，诗人的真正的“邻家子”乃是现世人，不可效的是那些“君宠益娇态，君怜无是非”的衮衮诸公。\n\n　　世间确实有某些品质才能很好的人，周围的人却不理解而以常人待之，待际遇一到，被入发现后，周围的人又要群起而效法。效法者有不理解其所以然，只一味学习其所然；不免便成了效颦的东施。', poem_tags = '唐诗三百首,写人,怀古,怀才不遇' WHERE poem_title = '西施咏' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '阴历十月的时候，大雁就开始南飞，\n据说飞到大庾岭，它们就全部折回。\n鸟儿不进，我却行程未止远涉岭南，\n真不知何日何时，我才能遇赦归来？\n潮水退落了，江面静静地泛着涟漪，\n深山老林昏暗暗，瘴气浓重散不开。\n来日我登上高山顶，向北遥望故乡，\n抑或能看到：那山头上初放的红梅。', poem_notes = '大庾岭：在江西、广东交界处，为五岭之一。北驿：大庾岭北面的驿站。\n阳月：阴历十月。\n殊：还。“我行”句意谓自己要去的贬谪之地还远，所以自己还不能停下。\n瘴：旧指南方湿热气候下山林间对人有害的毒气。\n望乡处：远望故乡的地方，指站在大庾岭处。\n陇头梅：大庾岭地处南方，其地气候和暖，故十月即可见梅，旧时红白梅夹道，故有梅岭之称。陇头：即为“岭头”。', poem_appreciation = '大庾岭在今江西大庾，岭上多生梅花，又名梅岭。古人认为此岭是南北的分界线，因有十月北雁南归至此，不再过岭的传说。宋之问被贬途径大庾岭北驿时，怀乡的忧伤涌上心头，悲切之音脱口而出：“阳月南飞雁，传闻至此回。我行殊未已，何日复归来？”意谓：阳月（即农历十月）雁南飞至此而北回，而我呢，却像“孤雁独南翔”（曹丕《杂诗》），非但不能滞留，还要翻山越岭，到那荒远的瘴疠之乡；群雁北归有定期，而我呢，何时才能重来大庾岭，再返故乡和亲人团聚！由雁而后及人，诗人用的是比兴手法。两两相形，沉郁、幽怨，人不如雁的感慨深蕴其中。这一鲜明对照，把诗人那忧伤、哀怨、思念、向往等等痛苦复杂的内心情感表现得含蓄委婉而又深切感人。\n\n　　人雁比较以后，五六两句，诗人又点缀了眼前景色：“江静潮初落，林昏瘴不开。”黄昏到来了，江潮初落，水面平静得令人寂寞，林间瘴气缭绕，一片迷蒙。这景象又给诗人平添了一段忧伤。因为江潮落去，江水尚有平静的时候，而诗人心潮起伏，却无一刻安宁。丛林迷瞑，瘴气如烟，故乡望眼难寻；前路如何，又难以卜知。失意的痛苦，乡思的烦恼，面对此景就更使他不堪忍受。\n\n　　恼人的景象，愁杀了这位落魄南去的逐臣，昏暗的境界，又恰似他内心的迷离惝恍。因此，这二句写景接上二句的抒情，转承得实在好，以景衬情，渲染了凄凉孤寂的气氛，烘托出悲苦的心情，使抒情又推进一层，更加深刻细腻，更加强烈具体了。\n\n　　最后二句，诗人又从写景转为抒情。他在心中暗暗祈愿：“明朝望乡处，应见陇头梅。”意思是说：明晨踏上岭头的时候，再望一望故乡吧！虽然见不到她的踪影，但岭上盛开的梅花该是可以见到的！《荆州记》载，南朝梁时诗人陆凯有这样一首诗：“折梅逢驿使，寄与陇头人。江南何所有，聊赠一枝春。”诗人暗用了这一典故。虽然家不可归，但他十分希望也能寄一枝梅，安慰家乡的亲人。\n\n　　情致凄婉，绵长不断，诗人怀乡之情已经升发到最高点，然而却收得含吐不露。宋人沈义父说：“以景结情最好”，“含有余不尽之意”。（《乐府指迷》）这一联恰好如此，诗人没有接续上文去写实景，而是拓开一笔，写了想象，虚拟一段情景来关合全诗。这样不但深化了主题，而且情韵醇厚，含悠然不尽之意，令人神驰遐想。\n\n　　全诗写的是“愁”，却未着一“愁”字。尽管如此，人们还是感到愁绪满怀，凄恻缠绵。之所以能产生这样的艺术魅力，是因为“善道景者，绝去形容，略加点缀”，“善言情者，吞吐深浅，欲露还藏”（陆时雍《诗镜总论》）。这首诗正是在道景言情上别具匠心。全诗情景交融，用词考究，思乡之忧伤与行程之艰难紧密结合，表达了强烈的哀伤与沉痛之意，感人肺腑。', poem_tags = '唐诗三百首,思乡,地名' WHERE poem_title = '题大庾岭北驿' AND poem_author = '宋之问';
UPDATE edu_poem SET poem_translation = '僖宗广明元年（880年）黄巢军攻入长安，僖宗出逃成都，韦庄因应试正留在城中，目赌长安城内的变乱，兵中弟妹一度相失，又多日卧病；离开长安的第二年，中和三年（883年）在东都洛阳，他将当时耳闻目见的种种乱离情形，通过一位从长安逃难出来的女子——即秦妇的“自述”，写成长篇叙事诗《秦妇吟》。\n\n　　《秦妇吟》无疑是我国诗史上一才华横溢的长篇叙事诗之一。长诗诞生的当时，民间就广有流传，并被制为幛子悬挂；作者则被呼为“秦妇吟秀才”，与白居易曾被称为“长恨歌主”并称佳话。其风靡一世，盛况空前。然而这首“不仅超出韦庄《浣花集》中所有的诗，在三唐歌行中亦为不二之作”（俞平伯）的（秦妇吟', poem_appreciation = '唐僖宗广明元年（880年）黄巢军攻入长安，僖宗出逃成都，韦庄因应试正留在城中，目赌长安城内的变乱，兵中弟妹一度相失，又多日卧病；离开长安的第二年，中和三年（883年）在东都洛阳，他将当时耳闻目见的种种乱离情形，通过一位从长安逃难出来的女子——即秦妇的“自述”，写成长篇叙事诗《秦妇吟》。\n\n　　《秦妇吟》无疑是我国诗史上一才华横溢的长篇叙事诗之一。长诗诞生的当时，民间就广有流传，并被制为幛子悬挂；作者则被呼为“秦妇吟秀才”，与白居易曾被称为“长恨歌主”并称佳话。其风靡一世，盛况空前。然而这首“不仅超出韦庄《浣花集》中所有的诗，在三唐歌行中亦为不二之作”（俞平伯）的（秦妇吟），却厄运难逃。由于政治缘故，韦庄本人晚年即讳言此诗，“他日撰家戒，内不许垂《秦妇吟》幛子，以此止谤”（《北梦琐言》）。后来此诗不载于《浣花集》，显然出于作者割爱。至使宋元明清历代徒知其名，不见其诗。至近代，《秦妇吟》写本复出于敦煌石窟，真乃天幸。\n\n　　从公元880年（唐僖宗广明元年）冬到公元883年（中和三年）春，即黄巢起义军进驻长安的两年多时间里，唐末农民起义发展到高潮，同时达到了转折点。由于农民领袖战略失策和李唐王朝官军的疯狂镇压，斗争残酷，而百姓蒙受着巨大的苦难和悲惨的牺牲。韦庄本人即因应举羁留长安，兵中弟妹一度相失，又多日卧病，他便成为这场震撼神州大地的社会巨变的目击者。经过一段时间酝酿，在他离开长安的第二年，即中和三年，在东都洛阳创作了这篇堪称他平生之力作的史诗。在诗中，作者虚拟了一位身陷兵中复又逃离的长安妇女“秦妇”对邂逅的路人陈述其亲身经历，从而展现了那一大动荡的艰难时世之各个方面。总之，《秦妇吟》既是一篇诗体小说，当然具有纪实性质。全诗共分五大段。首段叙述诗人与一位从长安东奔洛阳的妇人（即秦妇）于途中相遇，为全诗引子；二段为秦妇追忆黄巢起义军攻占长安前后的情事；三段写秦妇在围城义军中三载怵目惊心的各种见闻；四段写秦妇东奔途中所见所闻所感；末段通过道听途说，对刚刚平定的江南寄予一线希望，为全诗结尾。\n\n　　《秦妇吟》用了大量篇幅叙述了农民军初入长安引起的动乱。毫无疑问，在这里，作者完全站在李唐王朝的立场，是以十分敌视的态度看待农民革命的。由于戴了有色眼镜，即使是描述事实方面也就不无偏颇，攻其一点而不及其余。根据封建时代正史（两唐书）记载，黄巢进京时引起坊市聚观，可见大体上做到井然有序。义军头领尚让慰晓市人的话是：“黄王为生灵，不似李家不恤汝辈，但各安家。”而军众遇穷民于路，竟行施遗，唯憎官吏，黄巢称帝后又曾下令军中禁妄杀人。当然，既是革命，便难免流血；加之队伍庞大，禁令或不尽行，正如《新唐书·黄巢传》所记载“贼酋择甲第以处，争取人妻女乱之”的破坏纪律的行为总或不免。而韦庄却抓住这一端作了“放大镜”式的渲染：\n\n　　适逢紫盖去蒙尘，已见白旗来匝地。扶羸携幼竞相呼，上屋缘墙不知次。南邻走入北邻藏，东邻走向西邻避。北邻诸妇咸相凑，户外崩腾如走兽。轰轰琨琨乾坤动，万马雷声从地涌。火迸金星上九天，十二官街烟烘烔。家家流血如泉沸，处处冤声声动地，舞伎歌姬尽暗捐，婴儿稚女皆生弃。“秦妇”的东西南北邻里遭到烧杀掳夺，几无一幸免。仿佛世界的末日到了，整个长安城就只有嘶杀声与哭喊声。由于作者把当时的一些传闻，集中夸大，不免失实。但是，就在这些描述中，仍有值得读者注意的地方。在农民起义风暴的席卷下，长安的官吏财主们的惶惶不可终日的仇视恐惧心理，得到了相当生动的再现。在他们眼中，不仅起义军的“暴行”令人发指，就连他们的一举一动，包括沿袭封建朝廷之制度，也是令人作恶的：“衣裳颠倒语言异，面上夸功雕作字。柏台多半是狐精，兰省诸郎皆鼠魅。还将短发戴华簪，不脱朝衣缠绣被。翻持象笏作三公，倒佩金鱼为两史。”诗中表现的统治阶级对农民起义的仇视心理，可谓入木三分。这段文字，却从另一个角度，生动地反映出黄巢进入长安后的失策，写出农民领袖是怎样惑于帝王将相的错误观念，在反动统治阶级力量未曾肃清之际就忙于加官赏爵，作茧自缚。由此发现诗中涉及这方面的内容相当丰富，它还写到了农民起义军是怎样常处三面包围之中，与官军进行拉锯战，虽经艰苦卓绝的奋争而未能解围；他们又是怎样陷入困境，自顾不暇，也就无力解民于倒悬，致使关辅人民饿死沟壑、析骸而食；以及他们内部藏纳的异己分子是如何时时在祈愿他们的失败，盼望恢复失去的天堂。而这些生动形象的史的图景，是正史中不易看到的，它们体现出作者的才力。\n\n　　正如上文所说，《秦妇吟》是一个动乱时代之面面观，它的笔锋所及，又远不止于农民军一面，同时还涉及了封建统治者内部矛盾。韦庄在描写自己亲身体验、思考和感受过的社会生活时，违背了个人的政治同情和阶级偏见，将批判的锋芒指向了李唐王朝的官军和割据的军阀。诗人甚至痛心地指出，他们的罪恶有甚于“贼寇”黄巢。《秦妇吟》揭露的官军罪恶主要有二：其一是抢掠民间财物不遗余力，如后世所谓“寇来如梳，兵来如篦”。诗中借新安老翁之口控诉说：“千间仓兮万斯箱，黄巢过后犹残半。自从洛下屯师旅，日夜巡兵入村坞。匣中秋水拔青蛇，旗上高风吹白虎。入门下马如旋风，罄室倾囊如卷土。家财既尽骨肉离，今日残年一身苦。一身苦兮何足嗟，山中更有千万家。”\n\n　　其二便是杀人甚至活卖人肉的勾当。这一层诗中写得较隐约，陈寅恪、俞平伯先生据有关史料与诗意互参，发明甚确，扼要介绍如下。据《旧唐书·黄巢传》，“时京畿百姓皆寨于山谷，累年废耕耘。贼坐空城，赋输无入，谷食腾踊。米斗三四千。官军皆执山寨百姓鬻于贼，人获数十万”。《秦妇吟》则写道：“尚让厨中食木皮，黄巢机上刲人肉”、“夜卧千重剑戟围，朝餐一味人肝脍”，而这些人肉的来源呢？诗中借华岳山神的引咎自责来影射讽刺山东藩镇便透漏了个中消息：“闲日徒歆奠飨恩，危时不助神通力。寰中箫管不曾闻，筵上牺牲无处觅。旋教魇鬼傍乡村，诛剥生灵过朝夕。”俞平伯释云：“筵上牺牲”指三牲供品；“无处觅”就得去找；往哪里去找？“乡村”，史所谓“山寨百姓”是也。“诛剥”，杀也。“诛剥生灵过朝夕”，以人为牺也，直译为白话，就是靠吃人过日子。以上云云正与史实相符。黄巢破了长安，珍珠双贝有的是——秦妇以被掳之身犹曰“宝货虽多非所爱”，其他可知——却是没得吃。反之，在官军一方，虽乏金银，“人”源不缺。“山中更有千万家”，新安如是，长安亦然。以其所有，易其所无，于是官军大得暴利。\n\n　　凡此两端（抢掠与贩人），均揭露出封建官军与人民对立的本质。而韦庄晚年“北面亲事之主”王建及其僚属，亦在此诗指控之列。陈寅恪谓作者于《秦妇吟》其所以讳莫如深，乃缘“志希免祸”，是得其情实的。\n\n　　韦庄能写出如此具有现实倾向的巨作，诚非偶然。他早岁即与老诗人白居易同寓下邽，可能受到白氏濡染；又心仪杜甫，寓蜀时重建草堂，且以“浣花”命集。《秦妇吟》这首诗正体现了杜甫、白居易两大诗人对作者的影响，在艺术上且有青出于蓝之处。\n\n　　杜甫没有这种七言长篇史诗，唯白居易《长恨歌》可以譬之。但《长恨歌》浪漫倾向较显著，只集中表现两个主人公爱的悲欢离合。《秦妇吟》纯乎写实，其椽笔驰骛所及，时间跨度达两三年之久，空间范围兼及东、西两京，所写为历史的沧桑巨变。举凡乾坤之反覆，阶层之升降，人民之涂炭，靡不见于诗中。如此宏伟壮阔的画面，元、白亦不能有，唯杜甫（五言古体）有之。但杜诗长篇多政论，兼及抒情。《秦妇吟》则较近于纯小说的创作手法，例如秦妇形象的塑造、农民军入城的铺陈描写，金天神的虚构、新安老翁的形容，都是如此。这比较杜甫叙事诗，可以说是更进一步了。在具体细节的刻划上，诗人摹写现实的本领也是强有力的。如从“忽看门外红尘起”到“下马入门痴似醉”一节，通过街谈巷议和一个官人的仓皇举止，将黄巢军入长安之迅雷不及掩耳之势和由此引起的社会震动，描绘得十分逼真。战争本身是残酷无情的，尤其在古代战争中，妇女往往被作为一种特殊战利品，而遭到非人的待遇。所谓“马边悬男头，马后载妇女”。（蔡琰）《秦妇吟》不但直接通过一个妇女的悲惨遭遇来展示战乱风云，而且还用大量篇幅以秦妇声口毕述诸邻女伴种种不幸，画出大乱中长安女子群像，具有相当的认识价值。其中“旋抽金线学缝旗，才上雕鞍教走马”二句，通过贵家少妇的生活突变，“路上乞浆逢一翁”一段，通过因破落而被骨肉遗弃的富家翁的遭遇，使人对当时动乱世情窥班见豹。后文“还将短发戴华簪”数句虽属漫画笔墨，又足见农民将领迷恋富贵安乐，得意忘形，闹剧中足悲者。从“昨日官军收赤水”到“又道官军悉败绩”十数句，既见农民军斗争之艰难顽强，又见其志气实力之日渐衰竭，凡此刻划处，皆力透纸背；描摹处，皆情态毕见。没有十分的艺术功力，焉足办此。《秦妇吟》还着重环境气氛的创造。从“长安寂寂今何有”到“天街踏尽公卿骨”十二句，写兵燹后的长安被破坏无遗的现状，从坊市到宫室，从树木到建筑，一一道来，纤毫毕见，其笔力似在《长恨歌》、《连昌宫词》描写安史之乱导致毁坏的文字之上。尤其“内库烧为锦绣灰，天街踏尽公卿骨”，竟使时人惊讶，堪称警策之句。“长安寂寂今何有，废市荒街麦苗秀”，洛阳是“东西南北路人绝，绿杨悄悄香尘灭”，而一个妇人在茫茫宇宙中踽踽独行，“朝携宝货无人问，暮插金钗唯独行”。到处是死一般的沉寂，甚至比爆发还可怕，这些描写较之汉魏古诗“出门无所见，白骨蔽平原”这类诗句表现力更强，更细致成功地创造了一种恐怖气氛。总之，《秦妇吟》在思想内容上是复杂而丰富的，艺术上则有所开创，在古代叙事诗中堪称扛鼎之作。由于韦庄的写实精神在相当程度上克服了他的个人偏见，从而使得此诗在杜甫“三吏三别”、白居易《长恨歌》之后，为唐代叙事诗树起了第三座丰碑。', poem_tags = '叙事,长诗' WHERE poem_title = '秦妇吟' AND poem_author = '韦庄';
UPDATE edu_poem SET poem_translation = '冬天，晋文公去世了。十二月十日，要送往曲沃停放待葬。刚走出国都绛城，棺材里发出了像牛叫的声音。卜官郭偃让大夫们向棺材下拜，并说：“国君要发布军事命令，将有西方的军队越过我们的国境，我们袭击它，一定会获得全胜。”\n\n　　秦国大夫杞子从郑国派人向秦国报告说：“郑国人让我掌管他们国都北门的钥匙，如果悄悄派兵前来，就可以占领他们的国都。”秦穆公向秦国老臣蹇叔征求意见。蹇叔说：“让军队辛勤劳苦地偷袭远方的国家，我从没听说有过。军队辛劳精疲力竭，远方国家的君主又有防备，这样做恐怕不行吧？军队的一举一动，郑国必定会知道。军队辛勤劳苦而一无所得，一定会产生叛逆念头。再说行军千里，有谁不知道呢？”秦穆公没有听从蹇叔的意见。他召见了孟明视，西乞术和白乙丙三位将领，让他们从东门外面出兵。蹇叔哭他们说：“孟明啊，我看着大军出发，却看不见他们回来了！”秦穆公派人对蹇叔说：“你知道什么？要是你蹇叔只活个中寿就去世的话，你坟上的树都有两手合抱一般粗了（你现在离中寿都过去多少年了，早已昏聩）。”\n\n　　蹇叔的儿子跟随军队一起出征，他哭着送儿子说：“晋国人必定在崤山抗击我军，崤有两座山头。南面的山头是夏王皋的坟墓，北面的山头是周文王避过风雨的地方。你们一定会战死在这两座山之间，我到那里收拾你的尸骨吧。”于是秦国军队东行。', poem_notes = '殡：停丧。曲沃：晋国旧都，晋国祖庙所在地，在今山西闻喜。\n绛：晋国国都，在今山西翼城东南。\n柩（jiù）：装有尸体的棺材。\n卜偃：掌管晋国卜筮的官员，姓郭，名偃。\n大事：指战争。古时战争和祭祀是大事。\n西师：西方的军队，指秦军。过轶：越过。\n杞子：秦国大夫。\n掌：掌管。管，钥匙。\n潜：秘密地。\n国：国都。\n访：询问，征求意见。\n远主：指郑君。\n勤：劳苦。无所：一无所得。\n悖（beì）心：违逆之心，反感。\n孟明：秦国大夫，姜姓，百里氏，名视，字孟明。秦国元老百里奚之子。西乞：秦国大夫，字西乞，名术。秦国元老蹇叔之子。白乙：秦国大夫，字白乙，名丙。秦国元老蹇叔之子。这三人都是秦国将军。\n中（zhōng）寿：有两种解释。1.参见中寿。2.中等年纪。不管哪种解释，就句意，均为秦穆王讽刺蹇叔现已年老昏聩，要是你蹇叔只活个差不多就去世的话，你坟上的树都有两手合抱一般粗了。\n拱：两手合抱。\n肴（xiáo）：同崤，山名，在今河南洛宁西北。\n陵：大山。崤山有两陵，南陵和北陵，相距三十里，地势险要。\n夏后皋：夏代君主，名皋，夏桀的祖父。后：国君。\n尔骨：你的尸骨，焉：在那里。', poem_appreciation = '蹇叔的论战之道几千年来一直为世人称道，被奉为“知己知彼”的楷模。然而秦穆公没有听从蹇叔的正确意见。秦穆公利令智昏，一意孤行，执意要派孟明视（百里奚的儿子）、白乙丙、西乞术（蹇叔的两个儿子）三帅率部出征。蹇叔实际上已失去进谏的正常渠道，但他仍然不放弃努力——以“哭师”的形式来进谏，直言不讳地指出此次袭郑的必然结果。在送别秦国出征之师的时候，痛哭流涕地警告官兵们说：“恐怕你们这次袭郑不成，反会遭到晋国的埋伏，我只有到崤山去给士兵收尸了。” “哭师”召来了秦伯的诅咒、辱骂，这在封建社会是非常可怕的事情，但是蹇叔继续进谏——以“哭子”的形式来进谏，准确地指出晋国“必御师于崤”。想通过“哭子”的形式再次使自己的意见传导给国君。\n\n　　文中卜官郭偃和老臣蹇叔的预见有如先知，料事真如神，秦军后来果然在崤山大败而归，兵未发而先哭之，实在是事前就为失败而哭，并非事后诸葛亮。\n\n　　郭偃托言的所谓“君命大事”，不过是个借口，人们根据经验 完全可以作出类似的判断，乘虚而入，乱而取之，是战争中常用的手法。作为政治家和军事家，如果不具备这种经验和头脑，应 当属于不称职之列。从蹇叔一方看，他作为开国老臣，也具有这方面的经验，对手并非等闲之辈，不可能在非常时刻没有防备，因此，此时出征无异于自投罗网。\n\n　　秦穆公急欲扩张自己势力的心情，导致他犯了一个致命的常识性的错误，违反了“知己知彼”这个作战的基本前提。敌手早有防备，以逸待劳，必定获胜；劳师远袭，疲惫不堪，没有战斗力，必定惨败。其中原因大概是攻城略地的心情太急切了，以至 连常识都顾不上，当然是咎由自取。马有失前蹄的时候，人也有过失的时候，而在利令智昏的情况下所犯的错误，则是不可宽恕的。利令智昏而犯常识性的错误，更是不可宽恕。\n\n　　再说，当初秦国曾与晋国一起企图消灭郑国，后来又与郑国订立盟约。此时不仅置盟约不顾，就连从前的同伙也成了觊觎的 对象。言而无信，自食其言，不讲任何道义、仁德，这同样应当遭天谴，遭惩罚。当人心目中没有权威之时，便没有了戒惧；没有了戒惧，就会私欲急剧膨胀；私欲急剧膨胀便会为所欲为，无法无天。春秋的诸侯混战，的确最充分地使人们争权夺利的心理。手法、技巧发挥到了极致，也使命运成了最不可捉模和把握的东西。弱肉强食是普遍流行的无情法则，一朝天子一朝臣，泱泱大国可能在一夜之间倾覆，区区小国也可能在一夜之间暴发起来。由此可见，“先知”是没有的；而充满睿智并富有经验者，往往被人们认为是“先知”。\n\n　　这篇文章虽短，但结构上却充分体现了《左传》的叙事特色，即情节曲折多变，行文起伏跌宕，叙述有条不紊。文章以秦国老臣蹇叔谏阻、哭师、哭子为线索，复以秦穆公拒谏、诅咒相间其中，使全文在结构上起伏有致、曲折多变。\n\n　　其次，这篇文章在塑造形象上也充分体现出《左传》通过人物的语言和行动刻划人物性格，将人物与情节结构融为一体的特色。这篇文章虽短，却成功地塑造了一个老成先见、忧国虑远的老臣形象和一个刚愎自用、利令知昏的君主形象。两个形象一明一暗，一显一隐，然而又相互映衬，相得益彰。俗话说，姜是老的辣。蹇叔虽老，但仍不失足智多谋、思深虑远。', poem_tags = '古文观止,历史,故事,寓理' WHERE poem_title = '蹇叔哭师' AND poem_author = '左丘明';
UPDATE edu_poem SET poem_translation = '暮春时节，眺望江面，风雨连天。篷蔽的茅屋里，烛灯明灭，悄无人言。连树林里的黄莺都停止了鸣叫，惟有杜鹃，在月夜里孤苦哀啼。\n啼声越来越远，带着深深的漆黑的影子，惊醒了我的梦，让人清泪欲洒。年已半百，一畸零人，漂泊在孤旅的路上，想那只故园的杜鹃，带着故园的山水，让我不堪听闻矣。', poem_notes = '杜鹃：鸟名，又称“杜宇”、“子规”、“ 鶗鴂”、“怨鸟”。传 说古蜀国王，名“杜宇”，号“望帝”，禅位于开明之士，隐于西山，死后，其魂化为杜鹃鸟。啼声哀苦，每至血流于喙。\n蓬窗：犹蓬户，即编蓬草为窗，谓窗户之简陋。《庄子·让王》：“原宪居鲁，环堵之室，茨以生草，蓬户不完，桑以为柜。”宋刘克犀《打夕诗》：“蓬窗亦有精勤士。”《剪灯新话·至正妓人行》：“土炕蓬窗愁寂夜，挑灯快读解愁颐。”皆可证。\n春晚：即晚春，暮春时节。\n杜宇：即杜鹃。\n深枝：树林深处的枝条。\n故山：故乡的山林，即故乡。\n羁旅：寄居他乡。羁，停留。', poem_tags = '豪放,杜鹃,感叹,人生' WHERE poem_title = '鹊桥仙·夜闻杜鹃' AND poem_author = '陆游';
UPDATE edu_poem SET poem_appreciation = '这是一首抒发伤春情怀的词。\n\n　　首先值得注意的是，词人抒发伤春之情，并非因先睹物而引致伤感，而是深处闺中，即敏锐地感悟到大自然细微的变化，由此引起情感变化。“风定落花深，帘外拥红堆雪”，词人由风住，即断定“帘外”定然是落花遍地，红白堆积。表现了词人的敏感与对美好事物的关注之情。唐孟浩然《春晓》诗云：“春眠不觉晓，处处闻啼鸟。夜来风雨声，花落知多少？”韩偓《懒起》诗云：“昨夜三更雨，临明一阵寒。海棠花在否？倒卧卷帘看。”这两位诗人对风雨后花的状况均无所知，虽有怜花之意，但毕竟不如李清照。当然，李清照对落花给予极大关注，在其潜意识中，多少带有以之自况的成分。首二句虽为状物，但伤感之情已隐然可感。“长记海棠开后，正伤春时节”，次二句，词人的回忆闸门被打开，但对往事的具体内容却避而不谈，只是说此时海棠花落之时，亦是自己伤春时节。“长记”，即常记，说明以往的“伤心时节”之事，常萦绕于心。此外，词人在诸多花卉中，对海棠情有独钟，这或许是海棠有“花中神仙”之美称，以及如霞似雪般的秾丽娇娆，尤其是其高贵优雅之美，与词人个性颇为近似。词人的《如梦令》词：“昨夜风疏雨骤，浓睡不消残酒。试问卷帘人，却道海棠依旧。知否？知否？应是绿肥红瘦。”也表达了对海棠的钟爱，其抒情方式与此词上片也相似。\n\n　　上片侧重由景生情，为落花而慨叹，而伤春。下片则自然过渡到对闺门独处、孤寂苦闷生活的描绘。“酒阑歌罢玉尊空，青缸暗明灭。”词人在这里并没有直言其如何的孤寂，愁苦，而是通过四个极富象征意味的物体刻画酒阑、歌罢、空的酒杯以及忽明忽暗的油灯，整个画面幽暗、凄清、空冷。试想，一个闺中思妇置身于如此环境中，其心情该是怎样的凄怆孤寂，一切尽在不言之中了。“魂梦不堪幽怨，更一声啼鴂”，白日词人是惜花伤时，夜晚则借酒浇愁愁更愁，想在梦中得到一丝慰藉，然而梦中的情景，依旧使梦魂幽怨哀愁。醒来之时，听到窗外凄厉的“啼鴂”声，更增添了悲怆的情感。因为“恐鹈鴂之先鸣兮，使夫百草为之不芳”（屈原《离骚》），春已逝去，百花也已凋落殆尽。\n\n　　这首词抒写的是伤春凄苦之情，但词人并没有正面来抒写自己的情感，而是通过室内外景物的刻画，把自己的凄情浓愁寄寓其中，因而全词读来，更感其情深沉、凝重。', poem_tags = '闺怨,伤春' WHERE poem_title = '好事近·风定落花深' AND poem_author = '李清照';
UPDATE edu_poem SET poem_appreciation = '根据这首词本身看来，很可能写于李清照南渡后。词中写的是一种思乡的浓愁，颇耐思味。当时是早春时节，天气温和，风光柔丽，女词人刚刚卸去冬装，换上夹衫，心情轻快而又愉悦。这是美好的大自然给词人心灵投上的一抹明亮的色彩。女词人睡起，感到几丝寒意，鬓上的“梅花”也已残破。上阕四句，委婉地透露出来的是一种含蓄、朦胧、带有几分凄冷的心境和幽细的愁思；女词人先淡淡几笔轻轻拈出了春“寒”和花“残”这样的审美感觉，放在读者的心头，通过这种“微寒”之感和残破的“梅花”意象，巧妙地闪射出她心灵深处的某种不如人意但又难言的惆怅之感。一位心灵触觉极为敏锐细腻的知识女性对良辰美景的复杂感触在这里已微露端倪。\n\n　　下阕则波澜顿起，女词人将上阕曲折透露出来的那种凄清感和残缺美的底蕴一笔揭示出来：“故乡何处是，忘了除非醉。”这实在是带着血泪的痛楚悲呼。她只能将一怀思乡愁绪诉诸杯中物。至此，读者已经明白了女词人心灵深处不安的原因；而上阕预先作为一种情感铺垫而悬垂的“微寒”之感以及那残破的“梅花”，也有了着落。\n\n　　李清照在表达白己的这种思乡心绪时，很讲究笔法和技巧。全词风格婉约、含蓄，深沉、强烈的情绪并不施以浓墨重彩，却以清淡、省简的文字轻描淡写，情感表达得强烈而又有羁勒，陡然从心灵深处涌出，但随即又轻轻一笔打住，使这短短的一首小词在情感表达上产生一种起伏和跌宕，形成美感上的节奏。上阕的情感，一路平稳而冲淡，下阕劈头便是“故乡何处是”，使前面那一路冲淡的情绪顿起波澜。而上阕那种乍着夹衫的好心情到了下阕也陡然一变，跳到思念故乡的一怀愁绪上来。这种情感上的节奏和突变，无疑具有诗词创作和审美欣赏上的美学意义，但从另一方面看，也实在是女词人复杂、深刻的精神心理的真实显示。这首词相当深刻、有力地揭示出女词人灵魂深处的悲愤、不安和强烈的思乡情绪。细心的读者不难透过女词人深闺中的袅袅香雾、沉沉酒杯、昏昏醉意而窥见那颗与民族命运共存亡的崇高心灵。', poem_tags = '写景,思乡' WHERE poem_title = '菩萨蛮·风柔日薄春犹早' AND poem_author = '李清照';
UPDATE edu_poem SET poem_tags = '写景,地名,离别,友情' WHERE poem_title = '虞美人·有美堂赠述古' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_tags = '写人,赞美' WHERE poem_title = '满江红·忧喜相寻' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_tags = '女子,怀人' WHERE poem_title = '春残' AND poem_author = '翁宏';
UPDATE edu_poem SET poem_translation = '不要再给北面朝廷上书，让我回到南山破旧茅屋。\n我本无才难怪明主见弃，年迈多病朋友也都生疏。\n白发频生催人日渐衰老，阳春来到逼得旧岁逝去。\n满怀忧愁辗转难以入睡，月照松林窗外一片空虚。', poem_notes = '岁暮：年终。南山：唐人诗歌中常以南山代指隐居题。这里指作者家乡的岘山。一说指终南山。\n北阙：皇宫北面的门楼，汉代尚书奏事和群臣谒见都在北阙，后因用作朝廷的别称。《汉书·高帝纪》注：“尚书奏事，渴见之徒，皆诣北阙。”休上书：停止进奏章。\n敝庐：称自己破落的家园。\n不才：不成材，没有才能，作者自谦之词。明主：圣明的国君。\n多病：一作“卧病”。故人：老朋友。疏：疏远。\n老：一作“去”。\n青阳：指春天。逼：催迫。岁除：年终。\n永怀：悠悠的思怀。愁不寐：因忧愁而睡不着觉。寐：一作“寝”。\n虚：空寂。一作“堂”。', poem_appreciation = '“人事有代谢，往来成古今”，是一个平凡的真理。大至朝代更替，小至一家兴衰，以及人们的生老病死、悲欢离合，人事总是在不停止地变化着，没有谁没有感觉到。寒来暑往，春去秋来，时光也在不停止地流逝着，这也没有谁没有感觉到。首联两句凭空落笔，似不着题，却引出了作者的浩瀚心事，饱含着深深的沧桑之感。\n\n　　颔联两句紧承首联。“江山留胜迹”是承“古”字，“我辈复登临”是承“今”字。作者的伤感情绪，便是来自今日的登临。此处所说的“胜迹”，是指山上的羊公碑和山下的鱼梁洲等。\n\n　　颈联两句写登山所见。“浅”指水，由于“水落”，鱼梁洲更多地呈露出水面，故称“浅”；“深”指梦泽，辽阔的云梦泽，一望无际，令人感到深远。登山远望，水落石出，草木凋零，一片萧条景象。作者抓住了当时当地所特有的景物，提炼出来，既能表现出时序为严冬，又烘托了作者心情的伤感。\n\n　　尾联两句将“岘山”扣实。“羊公碑尚在”，一个“尚”字，十分有力，它包含了复杂的内容。羊祜镇守襄阳，是在晋初，而孟浩然写这首诗却在盛唐，中隔四百余年，朝代的更替，人事的变迁，是非常巨大的。然而羊公碑却还屹立在岘首山上，令人敬仰。与此同时，又包含了作者伤感的情绪。四百多年前的羊祜，为国（指晋）效力，也为人民做了一些好事，是以名垂千古，与山俱传；想到自己仍为“布衣”，无所作为，死后难免湮没无闻，这和“尚在”的羊公碑，两相对比，令人伤感，因之，就不免“读罢泪沾襟”了。\n\n　　这首诗前两联具有一定的哲理性，后两联既描绘了景物，富有形象，又饱含了作者的激情，这就使得它成为诗人之诗而不是哲人之诗。同时，语言通俗易懂，感情真挚动人，以平淡深远见长。清沈德潜评孟浩然诗词：“从静悟中得之，故语淡而味终不薄。”这首诗的确有如此情趣。', poem_tags = '唐诗三百首,抒情,失意' WHERE poem_title = '岁暮归南山 / 归故园作 / 归终南山' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_translation = '春江月出大堤坦平，堤上女郎牵手前行。\n唱尽新词情郎不见，红霞映树鹧鸪啼鸣。', poem_notes = '连袂（mèi）：犹联袂。晋葛洪《抱朴子·疾谬》：“携手连袂，以遨以集。”袂：指衣袖。\n欢：古时女子对所爱男子的爱称。\n映：《乐府》作“影”。鹧鸪（zhègū）：鸟名。为中国南方留鸟。古人谐其鸣声为“行不得也哥哥”，诗文中常用以表示思念故乡。', poem_tags = '爱情,民歌' WHERE poem_title = '踏歌词四首·其一' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '唉！盛衰的道理，虽说是天命决定的，难道说不是人事造成的吗？推究庄宗所以取得天下，与他所以失去天下的原因，就可以明白了。\n　　世人传说晋王临死时，把三枝箭赐给庄宗，并告诉他说：“梁国是我的仇敌，燕王是我推立的，契丹与我约为兄弟，可是后来都背叛我去投靠了梁。这三件事是我的遗恨。交给你三枝箭，你不要忘记你父亲报仇的志向。”庄宗受箭收藏在祖庙。以后庄宗出兵打仗，便派手下的随从官员，用猪羊去祭告祖先，从宗庙里恭敬地取出箭来，装在漂亮的丝织口袋里，使人背着在军前开路，等打了胜仗回来，仍旧把箭收进宗庙。\n　　当他用绳子绑住燕王父子，用小木匣装着梁国君臣的头，走进祖庙，把箭交还到晋王的灵座前，告诉他生前报仇的志向已经完成，他那神情气概，是多么威风！等到仇敌已经消灭，天下已经安定，一人在夜里发难，作乱的人四面响应，他慌慌张张出兵东进，还没见到乱贼，部下的兵士就纷纷逃散，君臣们你看着我，我看着你，不知道哪里去好；到了割下头发来对天发誓，抱头痛哭，眼泪沾湿衣襟的可怜地步，怎么那样的衰败差劲呢！难道说是因为取得天下难，而失去天下容易才像这样的吗？还是认真推究他成功失败的原因，都是由于人事呢？\n　　《尚书》上说：“自满会招来损害，谦虚能得到益处。”忧劳可以使国家兴盛，安乐可以使自身灭亡，这是自然的道理。因此，当他兴盛时，普天下的豪杰，没有谁能和他相争；到他衰败时，数十个乐官就把他困住，最后身死国灭，被天下人耻笑。祸患常常是由一点一滴极小的错误积累而酿成的，纵使是聪明有才能和英勇果敢的人，也多半沉溺于某种爱好之中，受其迷惑而结果陷于困穷，难道只有乐工（是所溺的成分）吗？于是作《伶官传》。', poem_notes = '伶官：伶，戏子，或唱戏杂技演员，现代的娱乐人员。宫庭里供统治者娱乐表演的人物。可见封建朝代不思于民生，不思于进取，奢华淫乐而痛失天下！伶官尚能使天下易主，可见不居安思危之害！\n原：推本求源，推究。\n其：语气副词，表示期望、命令的语气。\n庙：太庙，帝王祭祀祖先的宗庙。\n从事：这里指负责具体事物的官员。\n一少牢：用猪、羊各一头作祭品。牢，祭祀用的牲畜。\n组：丝带，这里指绳索。\n抑：或者\n逸豫：逍遥游乐，不能居安思危。\n所溺：沉溺迷恋的人或事物。\n乃:你，你的。\n顾：看。\n函：用木匣装。\n忽微：极细小的东西。\n纳：放回。\n仇雠：仇敌。\n《书》曰：语出《尚书·大禹谟》。\n及：等到。\n所溺：沉溺迷爱的人或事物。', poem_appreciation = '这是一篇著名的史论。作者认为，国家的盛衰，事业的成败，主要取决于人事，取决于执政者的思想行为。并扼要提出“忧劳可以兴国，逸豫可以亡身”，“祸患常积于忽微，而智勇多困于所溺”等具体论断，精辟透彻，发人深省。\n\n　　本文阐明观点的主要论据，是五代后唐庄宗先盛后衰，先成后败的历史事实，例据典型而有说服力。在写法上，则欲抑而先扬，先极赞庄宗成功时意气之“壮”，再叹其失败时形势之“衰”，通过盛与衰，兴与亡，得与失，成与败的强烈对比，突出庄宗历史悲剧的根由所在，使“本其成败之迹，而皆自与人”的结论，显得更加令人信服。\n\n　　文章笔力雄健而有气势，表达情见乎辞，篇幅虽然短小，却是一篇搏兔而用全力之作。\n\n　　文中所议论的后唐庄宗李存勖是沙陀族人李克用之长子，是五代的风云人物。李克用在临终之前，以三矢付庄宗要他报仇，叮嘱切切。李克用死后，李存勖嗣位，他谨记父亲遗言，讨刘仁恭，伐契丹，灭后梁，建立了后唐政权。但称帝后却沉迷于奢侈享乐的生活，宠信伶人，不问国事。四方藩镇见伶人被宠爱，纷纷贿以财物，谋取私利。而那些正直的臣僚因不肯行贿，为伶人谗言所诬陷，竟无辜被杀。后唐国政于是日趋衰败，动乱接连而生，李存勖本人最终也死在他极为宠信的伶人郭从谦的手中.。欧阳修目睹国家积弱不振的现实和当权者的骄奢淫逸，忧心仲仲，正是出于以古鉴今的考虑。欧阳修在这篇史论中，提出了“忧劳可以兴国，逸豫可以亡身”的见解，意在为当时的统治者敲响警钟，可谓寄语深长，发人深省。', poem_tags = '古文观止,史论,传记,序文' WHERE poem_title = '五代史伶官传序' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '当时红楼离别之夜，令人惆怅不已，香灯隐约地映照着半卷的流苏帐。残月将落，天刚破晓时，“我”就要出门远行，美人含着泪珠为“我”送行，真是“寸寸柔肠，盈盈粉泪”的样子。临别时为我弹奏一曲如泣如诉的乐章，那琵琶杆拨上装饰着用金制成的翠羽，雍容华贵；那琵琶弦上弹奏着娇软的莺语，婉转动人。那凄恻的音乐分明是在劝“我”早些儿回家，碧纱窗下有如花美眷在等着他。', poem_notes = '红楼：红色的楼，泛指华美的楼房。此指官贵人家女子的闺一说犹青楼，妓女所居。\n堪惆怅：堪，“那堪”的省文。此指因失意或失望而伤感、懊恼。\n香灯：即长明灯。通常用琉璃釭盛香油燃点。\n流苏帐：用彩色羽毛或丝线等制成的穗状垂饰物。常饰干车马、帐帐等物上。此指饰有流苏的帷帐。\n残月出门时美人和泪辞：此句是当黎明之时将要出门离去女子留着眼泪与之辞别。\n琵琶：初创批把。见《释名释乐器》。此类乐器原流行于波斯、阿拉伯等地，汉代传人我国。后经改造，团体修颈，有四弦、十二柱。俗称“秦汉子”。南北朝时又有曲项琵琶传八我国。四弦腹呈半梨形颈上有四柱，横抱怀中用拨子弹奏即现今琵琶的前身。唐宋以来经不断改进柱垃逐渐增多改横抱为竖抱，废拨子改用手指弹奏，观今民间的琵琶有十七柱，通常称四相十三品革新的琵琶有六相十八品；后者能弹奏所有半音技法丰富成为重要的民族乐器。\n金翠羽：指琵琶上用黄金和翠玉制成的饰物。\n弦上黄莺语：此句是指琵琶之声犹如黄莺的啼叫。\n绿窗：绿色纱窗。指贫女的闺室。与红楼相对，红楼为富家女子闺室。\n据唐圭璋《唐宋词简释》记载。', poem_tags = '宋词三百首,离别,思归' WHERE poem_title = '菩萨蛮·红楼别夜堪惆怅' AND poem_author = '韦庄';
UPDATE edu_poem SET poem_translation = '绵绵的江水有三千里长，家书有十五行那么长。\n行行之间没有其他的言语，只是告诉我要尽早回到故乡。', poem_notes = '京师:指都城。', poem_tags = '古诗三百首,思乡' WHERE poem_title = '京师得家书' AND poem_author = '袁凯';
UPDATE edu_poem SET poem_translation = '片片花瓣像蝶翅般轻盈，殷红点点，娇小可爱。\n如果说上天不爱花，为何把它们设计得这么巧妙？\n早上看见树上花儿朵朵，傍晚却剩下不多。\n如果说上天爱花，为何又用风雨摧残它们？', poem_notes = '卜算子，《词律》以为调名取义于“卖卜算命之人”。《词谱》以苏轼词为正体。又名《百尺楼》《眉峰碧》《缺月挂疏桐》等。双调，四十四字，仄韵。\n蝶衣轻，花瓣象蝴蝶翅膀那样轻盈。\n猩红，象猩猩血一样鲜红。\n了，尽。', poem_appreciation = '辛派词人素以豪放闻名。刘克庄词，尤以豪放见长，不写儿女情长，晓风残月。但刘克庄也写婉约词，而且糅豪放于婉约之中，更见其独具一格的豪放。这首《卜算子》即是如此，用比兴手法，委婉含蓄地表达了词人才不见用的凄楚情怀。\n\n　　上片先写花的可爱。起首一韵为花描态绘色：片片花瓣儿宛如蝴蝶轻盈的翅膀；点点花朵儿猩红如染，那么鲜艳娇美。上句写花之态，从花瓣儿着墨，因花瓣儿薄，故云“轻”；下句写花之色从整个花朵儿落笔，海棠花朵儿个小，所以在写花之色的同时再著一“小”字，并补足上文“轻”字。两句同一写花，而角度各异，为下句“百种千般巧”伏笔。而“片片”又见花瓣儿之多，“点点”又见花朵儿之密，为下片换头句“朝见树头繁”埋下伏笔。歇拍一韵旨在写花的可爱，可词人偏不直说，而是以揣度的口吻插入一句议论，用“道是天公不惜花”衬起，然后再说出花的“百种千般巧”。这样写，不仅沉着有力，使行文不板；而且，由于引进了“天公”即自然界的主宰“天老爷”丰富了全词的含蕴，突出了作者创作本词的寓意，很耐人寻味。歇拍句的“百种千般巧”，当然包括上文所说的姿致轻盈、体态娇小、色彩鲜艳，但细味“巧”字，又分明包含着花的气韵美和内在美。只有形貌和气韵、外在的表现和内在的含蕴配合相宜、谐和一致，方可谓之“巧”，谓之美。\n\n　　下片写花被“雨洗风吹了”的惋惜之情。上片极写花的可爱，这是为下片写花被雨打风吹去作铺垫。所以过片一韵便说：“朝见树头繁，暮见枝头少。”这里，“繁”、“少”对写，“朝”、“暮”对提，不仅见花事变化之遽，亦且见词人对花事的关心。从中我们可以想见“爱花成癖”的词人秉烛逐枝察看的忧惧情态，这一韵不似上片起首一韵，似对非对，却极有韵致，一段惜花情思宛然若揭。\n\n　　最后一韵乃全词的核心所在，但词人也不直说，而先用“道是天公果惜花”句衬起，然后再说出花事被“雨洗风吹了”的可悲现实。这话也很发人深思，同样具有一种哲理性味道，因为同上片歇拍一韵所说，本来就是一个问题的两个方面。而且，上片的“道是”句是扬，这里的“道是”句是抑，欲抑先扬，抑扬之间，流露出词人对天老爷任凭风雨摧残花事的不满。', poem_tags = '宋词三百首,豪放,写花,惜花' WHERE poem_title = '卜算子·片片蝶衣轻' AND poem_author = '刘克庄';
UPDATE edu_poem SET poem_translation = '浅水边，沙洲外，城郊早春的寒气悄然尽退。枝头繁花，晴光下的倩影，纷乱如坠地颠颤微微。流莺在花丛，轻巧的啼啭声，听来太急促，太细碎。啊，只身飘零，消愁的酒盏渐疏，难得有一回酣然沉醉。日复一日的思念，心身已煎熬成枯灰。相知相惜的挚友，迢迢阻隔，眼前，悠悠碧云，沉沉暮色，相对。\n想当年，志士俊才共赴西池盛会，一时豪情逸兴，华车宝马驱弛如飞。不料风云突变，如今，看携手同游处，剩几人未折摧？啊，秉舟绕过日月，那梦已断毁，只有镜中古铜色，照出红润的容颜已非。春，去了落花千点万点，飘飞着残败的衰颓，牵起一怀愁绪，如海，潮涌潮推。\n\n散译\n浅浅春寒，从溪水边、城郭旁悄一悄地溜走了。花影摇曳，莺声呖呖。因人在外地漂零，不能在一起喝酒，彼此相思，衣带也宽松了。所等之人迟迟不来，同自己相对的只有黄昏天边的碧云。\n一忆往昔汴京金明池相会，同僚们一块乘车出游。握手言观处，今日还有谁在？回到皇帝身边的好梦破灭了，一照镜子才发现容颜渐老。好的光景不再，官僚们的愁苦如海深。', poem_notes = '碎：形容莺声细碎。\n飘零：飘泊。疏酒盏：多时不饮酒。\n宽衣带：谓人变瘦。\n西池：故址在丹阳（今南京市），这里借指北宋京都开封西郑门西北之金明池二秦观于元佑间居京时，与诸同僚有金明池之游会。\n鹓鹭：鹓（yuān）鹭，谓朝官之行列，如鹓鸟和鹭鸟排列整齐有序。《隋书·音乐志》：“怀黄绾白，鹓鹭成行”，鹓鹭即指朝廷百官。飞盖，状车辆之疾行，出自曹植《公宴诗》：“清夜游西园，飞盖相追随。”这里代指车。\n日边：见《世说新语·夙惠》：“晋明帝数岁，坐元帝膝上；有入从长安来，元帝问洛下消息，潸然流涕、明帝问何以致泣？具以东渡意告之。因间明帝：‘汝意谓长安何如口远？’答曰：‘日远，不闻人从日边来，居然可知。’元帝异之，明日集群臣宴会，告以此意：更重问之，乃答曰：‘日近。’元帝失色，曰：‘尔何故异昨日之言邪？’答曰：‘举目见日，不见长安。”’后以日边喻京都帝王左右。清梦：美梦。\n朱颜：指青春年华。\n飞红：落花。', poem_appreciation = '这是秦观借描写春景春情，集中表现交织在一起的今与昔、政治上的不幸和爱情上的失意，抒发贬谪之痛、飘零之愁的一首词作。\n\n　　上片着重写今日生活情景。首写眼前景致，“水边沙外，城郭春寒退”二句，点明地点、时令，轻轻着笔，朴实自然。紧接着“花影乱，莺声碎”二句，细写春景特色，以“乱”字状花之纷繁，“碎”字表莺声盈耳，用笔尤工，各极其妙，洋溢着对自然的喜爱之情。“飘零”以下四句，忽而由喜转悲，由春景春情转写远谪索居，形体瘦损，不复有以往对酒当歌之情，转折有致，词情哀怨。歇拍“人不见，碧云暮合空相对”二句，人情艳情，孤情凄情，蕴藉含蓄，耐人寻味。\n\n　　下片抒发由昔而今的生活之情。换头直点昔日西池宴集，以“鸩鹭同飞盖”描写其盛况。比喻形象，用语简明，隐含着不能忘怀的情味。“携手处”以下四句，又由昔而今，由喜而悲，景物依旧，诸友却已飘泊云散。委婉曲折，缠宛凄侧。结尾“春去也，飞红万点愁如海”，再由眼前想到今后。“飞红万点”是春归的自然写照，“愁如海”却新奇绝妙。这两句既是惜春春去，又是对前途的无望。\n\n　　此词在内容上由春景春情引发，由昔而今由今而昔，由喜而悲，由悲而怨，把政治上的不幸和爱情上的失意融为一体，集中抒发了贬徙之痛，飘零之苦。在艺术上一波三折，一唱三叹，蕴藉含蓄，感人肺腑；以景结情，境界深远，余味无穷。\n\n　　新旧党争，损害的不只秦观一人，所以此词抒发的感情是具有一定的普适意义的，苏轼、黄庭坚、孔平仲、李之仪等人都有和词存今，可见对“元祜党人”震动之大，感触之深。\n\n　　词中所体现的情感极为悲伤，充分体现这位“古之伤心人”（冯煦语）的性格特征。即：当他身处逆境之时．往往不能自拔，无法像苏轼那样，善于自我解脱，而是自叹、自伤，一往而深，直至于死。所以，当他的朋友看到这首词的时候，即担心其“不久于世”（后作者逝于五年后）。这也就是作者所谓独具善感“词心”的体现。', poem_tags = '宋词三百首,宋词精选,婉约,失意,写景,惜春' WHERE poem_title = '千秋岁·水边沙外' AND poem_author = '秦观';
UPDATE edu_poem SET poem_tags = '抒情,谪居,生活' WHERE poem_title = '南乡子·自古帝王州' AND poem_author = '王安石';
UPDATE edu_poem SET poem_tags = '羁旅,写景,离别,怀古伤今' WHERE poem_title = '少年游·参差烟树灞陵桥' AND poem_author = '柳永';
UPDATE edu_poem SET poem_translation = '贾谊做了长沙王的太傅，已经由于被贬谪离开京城，自己感到很不得意；等到坐船渡过湘水的时候，就写了一篇赋来凭吊屈原。屈原是楚国的贤能之臣。遭受谗言的诬陷而被放逐，作了离《离骚》这篇文章，文章的结尾说：“算了罢，国家没有一个正直贤能的人，没有一个人了解我啊”于是就跳到汨罗江自杀了。贾谊我追念感伤这件事情，借此来比喻自己，那文章的词句说：\n　　恭敬地承受这美好的恩惠啊，到长沙去做官。途中听说屈原啊，自己沉到汨罗江自杀了。到了这湘江后写一篇文章投到江水中啊，（我）恭敬的凭吊屈原先生，（你）遭受了世间无尽的谗言啊，乃至毁灭了自己的生命。唉！唉！遭逢的时代不好啊。鸾鸟凤凰躲避流窜啊，猫头鹰却在高空翱翔。宦官内臣尊贵显耀啊，用谗言奉承阿谀的人能得志；贤才能臣无法立足啊，端方正派的人却郁郁不得志。世人都认为卞随、伯夷恶浊啊，认为盗跖、庄蹻廉洁，（认为）宝剑莫邪粗钝啊，铅质的刀锋利。慨叹抱负无法施展，屈原你无故遇祸啊！这就好比是抛弃了周鼎，而把瓦盆当成了宝物啊；乘坐、驾驶疲牛，使跛驴作骖啊，反让骏马吃力的去拖盐车啊；帽冠低居在下，鞋履反高高再上；这种倒行逆施的行为是不会长久的。慨叹先生你真不幸啊，竟遭遇到这样的祸难！”\n　　总之：算了吧！整个国家没有一个人了解我啊，一个人独自忧愁抑郁能够和谁说呢？凤凰飘飘然向高处飞去啊，自己本来就打算远走高飞。效法深渊中的神龙啊，深深地潜藏在渊底来保护自己；弃离了蟂獭去隐居啊，怎么能够跟从蛤蟆与水蛭、蚯蚓？我所认为珍贵的东西是圣人的神明德行啊，要远离污浊的世界而自己隐居起来；假使骐骥也能够被束缚而受羁绊啊，怎么能够说与狗和羊有分别呢？盘桓在这样混乱的世上遭受祸难啊，也是您的原因。无论到哪里都能辅佐君主啊，又何必留恋国都呢？凤凰在千仞的高空翱翔啊，看到人君道德闪耀出的光辉才降落下来；看到德行卑鄙的人显出的危险征兆啊，就远远的高飞而去。那窄窄的小水沟啊，怎么能够容下吞舟的巨鱼？横行江湖的鳣鱼、鲸鱼，（出水后）也将受制于蝼蚁。', poem_notes = '此赋是贾谊赴长沙王太傅任途中，经过湘水时所作。屈原自沉于湘水支流汨罗江，贾谊触景生情，作此凭吊屈原同时亦以自伤。\n长沙王：指西汉长沙王吴芮的玄孙吴差。太傅：官名，对诸侯王行监护之责。谪（zhé）：贬官。\n湘水：在今湖南境内，注入洞庭湖。贾谊由京都长安赴长沙必渡湘水。\n《离骚》赋：楚辞既称辞也称赋。\n汨罗：水名，湘水支流，在今湖南岳阳市境内。\n因自喻：借以自比。\n恭承：敬受。嘉惠：美好的恩惠，指文帝的任命。俟罪：待罪，这里是谦词。\n侧闻：谦词，说不是正面听到，尊敬的说法。\n造：到。讬（tuō）：同“托”，寄托。先生：指屈原，古人单称先生而不称名，表示尊敬。\n罔极：没有准则。殒（yǔn）：殁，死亡。厥：其，指屈原。\n不祥：不幸。\n伏窜：潜伏，躲藏。鸱枭：猫头鹰一类的鸟，古人认为是不吉祥的鸟，此喻小人。翱翔：比喻得志升迁。\n闒（tà）：小门。茸：小草。\n逆曳：被倒着拖拉，指不被重用。倒植：倒立，指本应居高位反居下位。\n随：卞随，商代的贤士。夷：伯夷。二者都是古贤人的代表。溷（hún）：混浊。跖：春秋时鲁国人，传说他是大盗。蹻（jué）：庄蹻，战国时楚国将领，庄蹻接受楚顷襄王之命开辟云南，后来退路被秦国斩断，他回不来就在云南做了王，客观上背叛了楚国。传说中这两个人成为“坏人”的代表。\n莫邪[yé]：古代宝剑名。铅刀：软而钝的刀。铦（xiān）：锋利。\n默默：不得志的样子。生：指屈原。无故：《文选》注谓“无故遇此祸也”。\n斡（wò）：旋转。斡弃：抛弃。周鼎：比喻栋梁之材。康瓠（hù）：瓦罐，比喻庸才。\n腾驾：驾驭。罢（pí）：．疲惫。骖：古代四马驾一车，中间的两匹叫服，两边的叫骖。蹇：跛脚。\n服：驾。《战国策·楚策》：“夫骥之齿至矣，服盐车而上太行，中坂纤延，负辕不能上。”骥是骏马，用骏马来拉盐车，比喻糟蹋有才能的人。\n章甫：古代的一种礼帽。荐：垫。履：鞋。章甫荐履：用礼貌来垫鞋子。渐：逐渐，这里指时间短暂。\n离：通“罹”，遭遇。咎：灾祸。\n讯曰：告曰。相当于《楚辞》的“乱曰”。\n巳矣：“算了吧”之意。\n壹郁：同“抑郁”。\n漂漂：同“飘飘”，飞翔貌。高逝：飞得高高的。自引：自己升高。\n袭：效法。九渊：九重渊，深渊。沕（wù）：深潜的样子。\n偭（miǎn）：面向。蟂獭（xiāotǎ）：水獭一类的动物。从：跟随。虾（há）：蛤蟆。蛭（zhì）：水蛭，蚂蟥一类。螾：同“蚓”，蚯蚓。这两句是说面向蟂獭一类动物隐居，不与蛤蟆、水蛭、蚯蚓一类小虫为伍。\n系：用绳系住。羁：用络头络住。这两句的意思是能够停留的地方就停留，就像犬、羊哪样。\n般：久。纷纷：乱纷纷的样子。尤：祸患。夫子：指屈原。意思是说屈原自己该走不走，长久停留在那乱纷纷的地方，怎么不会遭祸呢。\n历：走遍。相：考察。此都：指楚国都城郢。这是贾谊为屈原提的建议，要他到处走一走，看到有贤君才停下来帮助他。\n千仞：极言其高。仞，七尺为一仞。览：看到。德辉：指君主道德的光辉。\n细德：细末之德，指品德低下的国君。险征：危险的征兆。曾击：高翔。曾，高飞的样子。去：离开。\n污渎：污水沟。\n鱣（zhān）：鲟一类的大鱼。鲸：鲸鱼。固：本来。《庄子·庚桑楚》：“吞舟之鱼，砀而失水，则蝼蚁苦之。”', poem_appreciation = '贾谊在赋中对屈原的遭遇表示的深切悼惜，其实就是对自身处境的伤感，因为两人经历有着太多的相似之处，他是将自己心中的愤慨不平与屈原的忧愁幽思融汇在一起，以表达对世间贤人失意、小人得志这种不公平状况的极大不满。不过，在感情一致的前提下，贾谊并不赞同屈原以身殉国的行动。他认为尽管环境恶劣，也应当顽强地活下去，自己虽然将居住在卑湿的长沙，或许因此而不能长寿，但仍不愿去自尽。\n\n　　贾谊和屈原这种见解的差异，是因为他们具有不同的生死观。屈原所怀的是儒家杀身成仁的思想，理想不能实现就不惜殉以生命；而贾谊除具有儒家思想外，还兼有盛行于汉初的道家旷达精神。所以，如将两人 的作品加以对比，就可以发现在忧国忧民的忧患意识方面，贾谊没有屈原那样深沉；在对自身理想的追求上，贾谊也不及屈原那么执着，似乎他对世事显得更豁达，更彻悟。 贾谊任长沙王太傅第三年的一天，有一只鸟（猫头鹰）飞入他的住宅。长沙民间认为猫头鹰所到的人家，主人不久将会死去。贾谊谪居长沙本已郁郁不得志，又凑巧碰上这事，更是触景生情，倍感哀伤，便写下《鵩鸟赋》，假借与鹏鸟的问答，抒发自己的怀才不遇之情，并用老庄“齐生死，等祸福”的思想来自我宽解。《鵩鸟赋》开始记述何年何月何日鸟入屋，主人以为怪事，便翻开策数之书进行占卜，所得到的回答是房主人将死去（或远去）。主人占卜后要鸟告诉吉凶和死期的迟速。\n\n　　通达的评述，企图以此来求得自己精神上的解脱，但人们通过这些豁达的辞语，还是可以感觉到在贾谊旷达的精神世界中，其实还隐忍着深沉的悲哀！ 赋是汉代文学的代表，是在楚辞基础上发展而成的一种文体。汉赋大致分两种，一种是直接摹仿屈原《离骚》体的骚体赋，一种是汉代新创的散体大赋，它日益发展，成为汉赋的主体。贾谊在长沙地区所作的《吊屈原赋》是汉初骚体赋的代表作，它和《鵩鸟赋》都作于长沙，所以长沙在汉赋的形成过程中具有重要作用。 贾谊任职长沙王太傅其间，虽然心情是忧郁的，但并没有忘怀对国家政治的关心。\n\n　　如汉初朝廷准允民间铸钱，贾谊就上书反对，他认为民间铸钱有三弊：一、将有许多假钱；二、各地所铸的钱会轻重不一，不利流通；三、铸钱利厚，若吸引大量劳力投向铸钱，便会影响农业生产。可惜意见未得到采纳。\n\n　　贾谊在长沙居住了四年多，他的活动和著述对长沙及湖南的文化影响很大。历代长沙文人均为贾谊这位文化巨匠曾在自己故乡生活过而感到自豪，许多诗人辞家以屈贾后人自命。贾谊故宅在今长沙市天心区太平街太傅里，原建有贾太傅词，汉之后许多文人曾来此凭吊。唐代刘长卿留下了“三年谪宦此栖迟，万古惟留楚客悲”的诗句。明代李东阳写过《贾太傅祠碑记》。祠前巷侧有井，上敛下大，其状如壶，相传是贾谊所凿，称太傅井或壶井。因杜甫有“长怀贾谊井依然”的诗句，所以又称长怀井。清代贾太傅祠有治安堂、潇湘别墅、大观楼、佩秋亭等建筑。今尚存祠屋一间，宅内留有贾谊木雕像一座，表现了长沙人对这位汉赋大家的怀念与追忆。\n\n　　作为一位才气“陵轶飞免”的英才，贾谊留存下来的赋像他的鸿文巨论一样“沾溉后人,其泽甚远”。贾谊赋在赋史上具有“振其绪”之功。既上承楚骚的余绪。又奠定了汉代骚体赋的基础。在贾谊仅存的四篇赋中，《吊屈原赋》是以文辞清丽，抒情浓郁而饮誉于世的。 “辞清而理哀”，刘勰对《吊屈原赋》的这一评价的确是中肯之语，道出了贾谊这篇短赋被历代文人心慕手追的原因。贾谊的境遇与屈原相类似，因而在此赋中作者借屈原以自况，用清丽的言辞，抒写出悲愤哀伤的感情。', poem_tags = '辞赋精选,悼惜,抒怀' WHERE poem_title = '吊屈原赋' AND poem_author = '贾谊';
UPDATE edu_poem SET poem_translation = '注释 寻常：平常。三五：一十五，指农历每月十五日，通常称为“望日”，此日当太阳西下时，月亮正从东面升起，呈现出日月东西相望的情景。 婵娟：本意指女子容貌姿态的美好，此处借指月光柔曼秀美。有时即以“婵娟”代指月亮，苏轼《水调歌头》中有“但愿人长久，千里共婵娟”之句。 中秋：本为农历八月十五日，此处扩展其意指八月十八日。 皓魄：皎洁的月亮。魄通霸，是月始生或将灭时的微光，此处代指月亮或月光。', poem_tags = '月亮,节日' WHERE poem_title = '八月十五夜玩月' AND poem_author = '栖白';
UPDATE edu_poem SET poem_translation = '译文二 满坡的稻禾长势喜人，苗肥棵壮，在春风的吹拂下，层层梯田绿浪翻滚，直接云天。 在这绿色海洋的上空，数不尽的白鹭自由翱翔，宛如飞入一幅天然的彩色画屏。', poem_tags = '田园,写景,喜悦' WHERE poem_title = '稻田' AND poem_author = '韦庄';
UPDATE edu_poem SET poem_translation = '营州一带的少年习惯在旷野草原上生活，穿着狐皮袍子在城外打猎。\n他们即使喝上千杯酒也不会醉倒，这些少数民族的孩子10岁就能骑马奔跑。', poem_notes = '营州：唐代东北边塞，治所在今辽宁朝阳。\n厌（yàn）：同“餍”，饱。这里作饱经、习惯于之意。\n狐裘（qiú）：用狐狸皮毛做的比较珍贵的大衣，毛向外。\n蒙茸（róng）：裘毛纷乱的样子。语出《诗经·邶风·旌丘》：“狐裘蒙戎”。“茸”通“戎”。\n城下（xià）：郊野。\n虏（lǔ）酒：指营州当地出产的酒。\n千钟（zhōng）：极言其多；钟，酒器。\n胡儿：指居住在营州一带的奚、契丹少年。', poem_appreciation = '唐代东北边塞营州，原野丛林，水草丰盛，各族杂居，牧猎为生，习尚崇武，风俗犷放。高适这首绝句有似风情速写，富有边塞生活情趣。\n\n　　从中原的文化观念看，穿着毛茸茸的狐皮袍子在城镇附近的原野上打猎，似乎简直是粗野的儿戏，而在营州，这些却是日常生活，反映了地方风尚。生活在这里的汉、胡各族少年，自幼熏陶于牧猎骑射之风，养就了好酒豪饮的习惯，练成了驭马驰骋的本领。即使是边塞城镇的少年，也浸沉于这样的习尚，培育了这样的性情，不禁要在城镇附近就犷放地打起猎来。诗人正是抓住了这似属儿戏的城下打猎活动的特殊现象，看到了边塞少年神往原野的天真可爱的心灵，粗犷豪放的性情，勇敢崇武的精神，感到新鲜，令人兴奋，十分欣赏。诗中少年形象生动鲜明。“狐裘蒙茸”，见其可爱之态：“千钟不醉”，见其豪放之性：“十岁骑马”，见其勇悍之状。这一切又都展示了典型的边塞生活。\n\n　　这首绝句的艺术特点是构思上即兴寄情，直抒胸臆；表现上白描直抒，笔墨粗放。诗人仿佛一下子就被那城下少年打猎活动吸引住，好像出口成章地赞扬他们生龙活虎的行为和性格，一气呵成，不假思索。它的细节描写如实而有夸张，少年性格典型而有特点。诗人善于抓住生活现象的本质和特征，并能准确而简炼地表现出来，洋溢着生活气息和浓郁的边塞情调。在唐人边塞诗中，这样热情赞美各族人民生活习尚的作品，实在不多，因而这首绝句显得可贵。', poem_tags = '边塞,生活' WHERE poem_title = '营州歌' AND poem_author = '高适';
UPDATE edu_poem SET poem_translation = '清香的松树叶可以用来酿造甘甜的美酒，春天已经来临，不知这种美酒你到底酿造了多少呢？\n虽然山路崎岖遥远，但我不会推辞你的盛情邀请；纵使大雪厚积，也要踏雪前往拜访，何况现在已经是春天，冰雪已经消融。', poem_notes = '陆澧:作者友人，生平不详。\n堪:即可以，能够。\n过:意即拜访、探望。', poem_tags = '田园' WHERE poem_title = '答陆澧' AND poem_author = '张九龄';
UPDATE edu_poem SET poem_translation = '有个妇人白天将两个小孩安置在沙滩上，而自己去河边洗衣服。老虎从山上跑了下来，妇人慌忙地潜入水里来躲避老虎，两个小孩还是像刚才一样在沙滩上玩耍。老虎仔细地盯着他们看了很久，甚至用头来触碰他们，希望让其中一个能够感到害怕，可是小孩很天真，最终还是不知道害怕，最后，老虎终于离开了。估计老虎吃人，先要对人施加威风来吓唬人；可是（对于）不害怕的人，它的威风也就没有施展的地方！', poem_notes = '浣衣：洗衣服。\n自若：神情不紧张。\n庶几：差不多，有那么一点。在这里是“希望”的意思。\n意虎之食人 意：估计。\n虎熟视久之 熟: 仔细。\n至以首抵触 首: 头。\n虎亦寻卒去 卒: 最终。寻：副词，随即，不久。去：离开\n仓皇：匆忙而慌张。\n惧：害怕 。\n被：施加，给......加上。\n意：估计，推断。\n置：安放。\n驰：向往。这里指：老虎从山上（往沙滩）跑下来。\n避：躲避\n痴：此指无知识。\n昼日：白天', poem_tags = '初中文言文,哲理,寓言,故事' WHERE poem_title = '小儿不畏虎' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '诸葛亮的大名永远留在天地间，他的遗像清高让人肃然起敬。\n为了三分天下周密地筹划策略，万代好像鸾凤高翔，独步青云。\n伊尹、吕尚难分伯仲，不相上下，指挥军队作战镇定从容，让萧何曹参都为之失色。\n汉朝帝位转移是因为运气，诸葛亮也难以复兴，但他意志坚决，因军务繁忙而鞠躬尽瘁。', poem_notes = '臣：后人崇拜的大臣。\n羽毛：指鸾凤。\n身歼：身灭。', poem_appreciation = '“诸葛大名垂宇宙”，上下四方为宇，古往今来为宙，“垂于宙”，将时间空间共说，给读者以“名满寰宇，万世不朽”的具体形象之感。首句如异峰突起，笔力雄放。次句“宗臣遗像肃清高”，进入祠堂，诗人瞻望诸葛遗像，不由肃然起敬，遥想一代宗臣，高风亮节，更添敬慕之情。“宗臣”二字，总领全诗。\n\n　　接下去进一步具体写诸葛亮的才能、功绩。从艺术构思讲，它紧承首联的进庙、瞻像，诗人看了各种文物后，自然地对其丰功伟绩作出高度的评价：“三分割据纡筹策，万古云霄一羽毛。”纡，屈的意思。纡策而成三国鼎立之势，好比鸾凤高翔，独步青云，奇功伟业，历代敬仰。然而诗人用词精微，一个“纡”字，突出诸葛亮委屈地处在偏僻的地方，经世怀抱只能算“百施其一”而已，三分功业，也只不过是“雄凤一羽”罢了。“万古云霄”句形象有力，议论达情，情托于形，是议论中高于其他诗人之处。\n\n　　诗人联想起诸葛亮超人的才智和胆略，如同见到了他那羽扇纶巾、一扫千军万马的潇洒风度。感情所至，诗人不由呼出“伯仲之间见伊吕，指挥若定失萧曹”的赞语。伊尹是商代开国君主汤的大臣，吕尚辅佐周文王、武王灭商有功，萧何和曹参，都是汉高祖刘邦的谋臣，汉初的名相，诗人盛赞诸葛亮的人品与伊尹、吕尚不相上下，而胸有成竹，从容镇定的指挥才能却使萧何、曹参为之黯然失色。这一方面是表现了对武侯的极度崇尚之情，同时也表现了作者不以事业成败持评的高人之见。刘克庄说：“卧龙没已千载，而有志世道者，皆以三代之佐许之。此诗侪之伊吕伯仲间，而以萧曹为不足道，此论皆自子美发之。”黄生说：这一评论，“区区以成败持评者，皆可废矣。”读者可见诗人这一论断的深远影响。\n\n　　最后，“运移汉祚终难复，志决身歼军务劳。”诗人抱恨汉朝“气数”已终，长叹尽管有武侯这样稀世杰出的人物，下决心恢复汉朝大业，但竟未成功，反而因军务繁忙，积劳成疾而死于征途。这既是对诸葛亮“鞠躬尽瘁，死而后已”高尚品节的赞歌，也是对英雄未遂平生志的深切叹惋。\n\n　　这首诗，由于诗人以自身肝胆情志吊古，所以能涤肠荡心，浩气炽情动人肺腑，成为咏古名篇。诗中除了“遗像”是咏古迹外，其余均是议论，不仅议论高妙，而且写得极有情韵。三分霸业，在后人看来已是赫赫功绩了，而对诸葛亮来说，轻若一羽：“萧曹”尚不足道，那区区“三分”就更不值得挂齿。诗句写得这样曲折跌宕，处处都是抬高了诸葛亮。这首诗通篇议论但不空泛，句句含情，层层蓄势，到诗的尾联达到高潮：“志决身歼军务劳。”——全诗就结束于这里的最强音上。', poem_tags = '唐诗三百首,怀古,议论' WHERE poem_title = '咏怀古迹五首·其五' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '一直没有遇上圣明的君主，没作上官，过着隐居的生活，谁肯信服呢？而今才显现了名声和踪迹：画工将我画在风筝上，那么我正好借着风力，乘风直上。\n在半空中，风慢慢吹来，我觉得身体渐渐平稳了，只觉得要飘到月宫去了。此时正是雨后，夕阳西下之时，又有多少人身在平地，羡慕我登上了碧霄之中啊！', poem_notes = '临江仙：词牌名。本为唐教坊曲名，多用以咏水仙，故名。双调五十八字或六十字，皆用平韵。\n未遇：未得到赏识和重用；未发迹。行藏：指出处或行止。语本《论语·述而》：“用之则行，舍之则藏。”\n无端：谓无由产生。引申指无因由，无缘无故。良匠：泛指在某方面技艺精湛的人。形容：形体和容貌。\n当风：正对着风。\n吹嘘：吹助，指风吹。唐孟郊《哭李观》诗：“清尘无吹嘘，委地难飞扬。”\n蟾宫：月宫，月亮。唐以来称科举及第为蟾宫折桂，因以指科举考试。\n碧霄：青天。', poem_tags = '宋词三百首,言志' WHERE poem_title = '临江仙·未遇行藏谁肯信' AND poem_author = '侯蒙';
UPDATE edu_poem SET poem_translation = '躺在水边阁楼的竹席上，清冷冷好似凉秋，片片的浮云顺水悠悠，黄昏的暮色使它们渐渐敛收。红艳艳莲花互相倚靠，简直像姑娘喝醉了酒，羽毛雪白的水鸟安闲静默，定然是独个儿在发愁。\n与其像殷浩朝天空书写“咄咄怪事”发泄怨气，倒不如像司空图寻觅美好的山林安闲自在地去隐居，一座山丘，一条谷壑，也是风流潇洒多逸趣。我不知而今衰损了多少精力，只觉得近来上楼懒登梯。', poem_notes = '鹧鸪天：词牌名。鹅湖：《铅山县志》记载：“鹅湖山在县东，周回四十馀里...《鄱阳记》云：‘山上有湖多生荷，故名荷湖。’东晋人龚氏居山蓄鹅，其双鹅育子数百，羽绒成乃去，更名鹅湖。” 鹅湖原名荷湖，因山中有湖，多生荷。晋人龚氏居山，养鹅湖中，于是更名鹅湖。\n簟（diàn）：竹席；溪堂：临溪的堂舍。\n收：敛收。\n浑如：非常像，酷似。\n无言：不鸣。\n咄咄：用殷浩事。《世说新语·黜免》篇：“殷中军被废，在信安，终日恒书空作字。扬州吏民寻义逐之，窃视，唯作“咄咄怪事”四字而已。”表示失意的感叹。\n休休：用司空图事。《新唐书·卓行传》：“司空图字表圣。……本居中条山王官谷，有先人田，遂隐不出。作亭观素室，……名亭曰休休，作文以见志，曰：‘休，美也。既休而美具。故量才，一宜休，揣分，二宜休，耄而瞆，三宜休，又，少也堕，长也率，老也迂，三者非济时用，则又宜休。’因自目为耐辱居士，其言诡激不常，以免当时祸灾云。”又，《旧唐书·司空图传》引图所作《耐辱居士歌》曰：“咄咄！休休休！莫莫莫！伎俩虽多性情恶，赖是长教闲处著。休休休，莫莫莫，一局棋，一炉药，天意时情可料度。”\n一丘句：《世说新语·品藻》篇：“明帝问谢鲲：‘君自谓何如庾亮’？答曰：‘端委庙堂，使百僚准则，臣不如亮；一丘一壑，自谓过之”。又《巧艺》篇：“顾长康画谢幼舆在岩石里。人问其所以，顾曰：‘谢云一丘一壑，自谓过之，此子宜置丘壑中。’”风流：优美，有风韵。\n不知二句：唐刘禹锡《秋日书怀寄白宾客》诗：“兴情逢酒在，筋力上楼知。”俞文豹《吹剑录》：“古今诗人，间见层出，极有佳句，无人收拾，尽成遗珠。……陈秋塘诗：‘不知筋力衰多少，但觉新来懒上楼。’”筋力：精力。但：只。', poem_appreciation = '题解 　　本词是作者病后所作，借景抒情，调子很低沉，上片绘景状物，渲染气氛，突出悉字，花鸟也知有情。下片剖诉心曲，通过两具典故委婉抒发对统治集团迫害爱国志士的畴及自己对仕途已经失望的无可奈何的心态。有沉哀茹痛之语，无剑拔弩之势。不知筋力衰多少，但觉新来懒上楼。“不知”二字，以“衰”、“懒”二字写出词人隐奶鹅湖，病后衰弱，不知不觉筋力疲乏之感，“但觉”复转进一步，强调出上楼登高眺望，新近越来越见慵懒无聊，流露出“烈士暮年”无用武，“壮心不已”竟蹉跎 的悲愤和凄怆，较之其激昂慷慨之作。意象清丽，色彩鲜明，涵义隽永，精妙至极。下片用殷浩无故遭贬，司空图无奈退隐的两个典故，貌似旷达而实含怨忿，感慨颇深。陈廷焯评此词云：“信笔写去，格调自苍劲，意味自沉厚，不必剑拔弩张，洞穿已过七扎，斯为绝技”（《白雨斋词话》）。此词则表现得深婉、沉郁，别具一格。 ▲', poem_tags = '写景,抒情' WHERE poem_title = '鹧鸪天·鹅湖归病起作' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '夏日午眠，梦见荡舟西湖荷花间，满湖烟水迷茫、荷花清香扑鼻。突然如筛豆般的阵雨敲击船篷，发出“扑”、“扑”的声音，把我从西湖赏荷的梦境中惊醒。\n以为是在西湖赏荷，却原来是在家中午休，遇急雨击池中荷叶把我惊醒，梦醒后观庭院荷池，急雨敲打荷叶，雨珠跳上跳下，晶莹的雨点忽聚忽散，散了如断线的珍珠，四处迸射，使人眼花缭乱，最后聚在叶心，像一窝泛波的水银，亮晶晶的。', poem_notes = '昭君怨：词牌名，又名《宴西园》、《一痕沙》。四十字，全阕四换韵，两仄两平递转，上下片同。\n扁舟：小船。\n烟水：雾霭迷蒙的水面。\n打篷声：雨落船篷之声。\n真珠：即珍珠。形圆如豆，乳白色，有光泽，是某些软体动物(如蚌)壳内所产。为珍贵的装饰品，并可入药。\n水银：喻水珠。\n清波：清澈的水流。', poem_appreciation = '这首小令用轻松活泼的笔调写自己梦中泛舟西湖和被雨惊醒后的情景。\n\n　　上片写梦中泛舟西湖花底，骤雨打篷，从梦中惊醒。“午梦扁舟花底，香满西湖烟水。”“扁舟”，小船；花底，花下。词人午睡，梦中驾着小船在西湖荷花之下泛游，烟雾缭绕的水面上荷花的香味四溢。这两句写的虽是梦境，但形象逼真，如同一幅绝妙的水墨画，淡笔素描，勾勒出湖面胜景的一个轮廓，呈现在读者面前。“急雨打篷声，梦初惊。”突然，一阵暴雨击打船篷的声音，把他从梦中惊醒，一瞬间，先前的扁舟、荷花、烟水顿时消失，可以想见，词人此时对梦境还有些留恋，对雨声打断他的美梦不无遗憾。\n\n　　下片写醒来所见景物，与先前的梦境相映成趣。“却是池荷跳雨，散了真珠还聚。”“却是”二字，承上启下，把梦境和现实串在一起。原来，先前梦中听到的“急雨打篷声”，睁眼一看，是雨点落在门前池塘中的荷叶发出的声音。“跳”字说明雨下得很急，与上片的“打”字相呼应。雨珠在荷叶上活蹦乱跳，形同一粒粒的珍珠，“珠珠”被雨点击散，又重新聚合，因此说“散了……还聚”，若不是观察仔细，是很难提炼出这样的佳句来的。“聚作水银窝，泻清波。”“水银”二字作比喻，形象地写出水珠在荷叶上滚动聚合的状貌。这两句是说，雨点聚多了，聚成水银般的一窝，此时叶面无法承受它的重量，叶上的积水便泻入池中。“跳”、“散”、“聚”、“泻”，四个动词连用，把雨打荷叶，荷叶面上水珠滚动，周而复始的情景写得活灵活现。\n\n　　词构思巧妙，意境新颖，梦境与现实对照写来，曲折而有层次，极富变化，细细品味，似乎看到晶莹璀灿的珍珠在碧绿的“盘”中滚动；似乎嗅到荷花的阵阵幽香，有很强的艺术魅力。', poem_tags = '咏物,写雨' WHERE poem_title = '昭君怨·咏荷上雨' AND poem_author = '杨万里';
UPDATE edu_poem SET poem_translation = '看到叶子落下忽然惊觉秋天到了，这秋色交给了东去的流水。流水殷勤地流过白苹洲，沙洲上有帘幕半卷的小楼，楼中的人应该在识别返回的小舟。\n回望之前和友人出游心里依然怀恋，出游的痕迹消失了那份心情却保存了下来。动听的歌曲消散了，美人也不见了，只有饮酒时看到的月亮和以前一样，和人交相愁苦。', poem_notes = '分付：意为交给。\n白苹洲：泛指长满白色苹花的沙洲。\n歌尘：形容歌声动听。\n梦云：战国宋玉《高唐赋》中的人物，所以泛指美女。', poem_tags = '秋天,写景,怀人' WHERE poem_title = '浪淘沙·一叶忽惊秋' AND poem_author = '贺铸';
UPDATE edu_poem SET poem_translation = '注释 这首诗题为《断句》，“断句”同于“绝句”，就是联句未成的意思。 鄣：边地险要处的城堡。', poem_tags = '古诗三百首,写景' WHERE poem_title = '断句' AND poem_author = '刘昶';
UPDATE edu_poem SET poem_translation = '译文 　　上次离去时，雪像花一样地飘落，如今再度前来，花开得像雪一般的白艳。这两句诗是感叹相聚太短，离别太长，每次分手后总要经过许久才能相见。', poem_tags = '离别,重逢' WHERE poem_title = '别诗二首·其一' AND poem_author = '范云';
UPDATE edu_poem SET poem_translation = '注释 初解：指开始能听懂大人讲话的意思。呕哑：小孩子学说话的声音。 缕金华：用金线绣的花儿。华：同“花”。', poem_tags = '儿童' WHERE poem_title = '与小女' AND poem_author = '韦庄';
UPDATE edu_poem SET poem_translation = '秋夜床席冰冷梦也难以做成，天空碧蓝如水夜云像沙样轻。\n雁声凄厉远远地飞过潇湘去，十二楼中的明月空自放光明。', poem_notes = '瑶瑟：玉镶的华美的瑟。\n冰簟：清凉的竹席。银床：指洒满月光的床。\n远：一作“还”。过：一作“向”。潇湘：二水名，在今湖南境内。此代指楚地。\n十二楼：原指神仙的居所，此指女子的住所。', poem_appreciation = '这首诗咏闺怨。全诗没有透出一个“怨”字，只描绘清秋的深夜，主人公凄凉独居、寂寞难眠，以此来表现她深深的幽怨。诗是写女子别离的悲怨，蘅塘退士批注：“通首布景，只梦不成三字露怨意。”\n\n　　诗所写的是梦不成之后之所感、所见、所闻的情景。全诗象是几种衔接紧密的写景镜头，表现了女主人公的心理活动和思想感情。冰簟、银床、碧空、明月、轻云，南雁、潇湘，以至于月光笼罩下的玉楼，组成了一组离人幽怨的秋夜图，渲染了一种和主人公离怨情绪统一和谐的情调和氛围。诗中虽无“怨”字，然而怨意自生。\n\n　　诗的题目和内容都很含蓄。瑶瑟，是玉镶的华美的瑟。瑟声悲怨，相传“泰帝使素女鼓五十弦瑟，悲，帝禁不止，故破其瑟为二十五弦”（《汉书·郊祀志》）。在古代诗歌中，它常和别离之悲联结在一起。题名“瑶瑟怨”，正暗示诗所写的是女子别离的悲怨。\n\n　　头一句正面写女主人公。冰簟银床，指冰凉的竹席和银饰的床。“梦不成”三字很可玩味。它不是一般地写因为伤离念远难以成眠，而是写她寻梦不成。会合渺茫难期，只能将希望寄托在本属虚幻的梦寐上；而现在，难以成眠，竟连梦中相见的微末愿望也落空了。这就更深一层地表现出别离之久远，思念之深挚，会合之难期和失望之强烈。一觉醒来，才发觉连虚幻的梦境也未曾有过，伴着自己的，只有散发着秋天凉意和寂寞气息的冰簟银床。—这后一种意境，似乎比在冰簟银床上辗转反侧更隽永有情韵。读者仿佛可以听到女主人公轻轻的叹息。\n\n　　第二句不再续写女主人公的心情，而是宕开写景。展现在面前的是一幅清寥淡远的碧空夜月图：秋天的深夜，长空澄碧，月光似水，只偶尔有几缕飘浮的云絮在空中轻轻掠过，更显出夜空的澄洁与空阔。这是一个空镜头，境界清丽而略带寂寥。它既是女主人公活动的环境和背景，又是她眼中所见的景物。不仅衬托出了人物皎洁轻柔的形象，而且暗透出人物清冷寂寞的意绪。孤居独处的人面对这清寥的景象，心中萦回着的也许正是“碧海青天夜夜心”一类的感触吧。\n\n　　“雁声远过潇湘去”，这一句转而从听觉角度写景，和上句“碧天”紧相承接。夜月朦胧，飞过碧天的大雁是不容易看到的，只是在听到雁声时才知道有雁飞过。在寂静的深夜，雁叫更增加了清冷孤寂的情调。“雁声远过”，写出了雁声自远而近，又由近而远，渐渐消失在长空之中的过程，也从侧面暗示出女主人公凝神屏息、倾听雁声南去而若有所思的情状。古有湘灵鼓瑟和雁飞不过衡阳的传说，所以这里有雁去潇湘的联想，但同时恐怕和女主人公心之所系有关。雁足传书。听到雁声南去，女主人公的思绪也被牵引到南方。大约正暗示女子所思念的人在遥远的潇湘那边。\n\n　　“十二楼中月自明”。前面三句，分别从女主人公所感、所见、所闻的角度写，末句却似撇开女主人公，只画出沉浸在明月中的“十二楼”。《史记·孝武本纪》集解引应劭曰：“昆仑玄圃五城十二楼，此仙人之所常居也。”诗中用“十二楼”，或许借以暗示女主人公是女冠者流，或许借以形容楼阁的清华，点明女主人公的贵家女子身份。“月自明”的“自”字用得很有情味。孤居独处的离人面对明月，会勾起别离的情思，团圆的期望，但月本无情，仍自照临高楼。“玉户帘中卷不去，捣衣砧上拂还来。”诗人虽只写了沉浸在月光中的高楼，但女主人公的孤寂、怨思，却仿佛融化在这似水的月光中了。这样以景结情，更增添了悠然不尽的余韵。\n\n　　这首写女子别离之怨的诗颇为特别。全篇除“梦不成”三字点出人物以外，全是景物描写。整首诗就象是几个组接得很巧妙的写景镜头。诗人要着重表现的，并不是女主人公的具体心理活动、思想感情，而是通过景物的描写、组合，渲染一种和主人公相思别离之怨和谐统一的氛围、情调。冰簟、银床、秋夜、碧空、明月、轻云、南雁、潇湘，以至笼罩在月光下的玉楼，这一切，组成了一幅清丽而含有寂寥哀伤情调的画图。整个画面的色调和谐地统一在轻柔朦胧的月色之中。读了这样的诗，对诗中人物的思想感情也许只有一个朦胧的印象，但那具有浓郁诗意的情调、气氛却将长时间留在记忆中。\n\n　　回到诗题。“瑶瑟怨”不仅仅暗示女子的别离之怨，同时暗示诗的内容与“瑟”有关。“中夜不能寐，起坐弹鸣琴”（阮籍《咏怀》），写女主人公夜间弹琴（瑟）抒怨也是可能的。如果说温诗首句是写“中夜不能寐”，那么后三句可能就是暗写“起坐弹鸣琴（瑟）”了。不过，写得极含蓄，几乎不露痕迹。它把弹奏时的环境气氛，音乐的意境与感染力，曲终时的情景都融化在鲜明的画面中。弹瑟时正好有雁飞向南方，就像是因瑟声的动人引来，又因不胜清怨而飞去一样。曲终之后，万籁俱寂，惟见月照高楼，流光徘徊。弹奏者则如梦初醒，怅然若失。这样理解，诗的抒情气氛似乎更浓一些，题面与内容也更相称一些。', poem_tags = '唐诗三百首,离别,闺怨' WHERE poem_title = '瑶瑟怨' AND poem_author = '温庭筠';
UPDATE edu_poem SET poem_translation = '在霜风凌厉、大漠草凋之际，胡人又背着精坚的弓箭，骑着骄悍的战马入侵了。\n这时，朝廷派出威猛如霍嫖姚一样的将军，率领三十万战士出征迎敌。\n将士们腰插着速如流星一样的白羽箭，手持闪耀着秋莲寒光的利剑。\n向着战场进发。朝廷大军在玉门关与胡兵雪中交战，敌人的箭簇像沙石一样的射在我军战士的衣甲上。\n双万龙争虎斗，经过多次回合的激战，战士们奋勇杀敌，又有太白入月，胡虏必灭的吉兆，大家都坚信一定能够打败敌人。\n敌虏可摧，胡星将灭，要将胡虏彻底消灭。\n将胡虏之首悬挂在空中，将羽虏之尸埋在边塞上，看他们可敢再来兴兵浸犯？\n胡无兵将可侵，中国自然和平昌盛。\n陛下圣寿三干岁，稳坐庙堂之上，但须高歌汉高祖的大风歌：“安用猛士兮守四方！”', poem_notes = '胡无人：乐府旧题。《乐府诗集》卷四十列于《相和歌辞》，题为”胡无人行“。南朝梁王僧虔《技录》中有《胡无人行》，乃李白此诗所本。\n“严风”句：谓冬天的寒风将雪刮起，塞外湖沼边的水草凋零。严风，冬天的风。海，胡地沙漠中的湖沼，即所谓“海子”。\n“筋干”句：意谓胡人的弓强马壮。筋干，谓弓箭精良坚固。筋，弓弦也。干，即竿，箭杆也。《周礼·考工记·弓人》：凡为弓，冬析干而春液（浸渍）角，夏治筋，秋合三材。骄，马强壮的样子。\n“汉家”二句：谓汉家派猛将与胡兵交战。《史记·匈奴传》：（武帝元光二年，公元前87年）汉伏兵三十余万马邑旁。《汉书·霍去病传》：去病以皇后姊子，年十八为侍中。善骑射，再从大将军。大将军受诏，予壮士，为嫖姚校尉。颜师古注：嫖姚，劲疾之貌，。霍嫖姚，即霍去病，这里泛指猛将。\n“流星”二句：言战士腰插白羽箭，宝剑出匣，光芒四射。流星白羽，指箭。流星，喻箭之疾速。白羽，以箭羽代指箭。秋莲，宝剑上饰以秋莲之花，亦喻宝剑洁白清冷。\n“天兵”二句：写胡汉交兵。汉兵在大雪纷飞中，开赴玉门关；胡兵射箭如沙，顽强对抗。天兵，王师，即汉家朝廷大军。\n“云龙”句：喻两军厮杀之激烈，如龙虎相斗。云龙风虎，皆阵名。《易·乾》：云从龙，风从虎，圣人作而万物睹。尽交回，言交战激烈也。\n“太白”句：谓这次战争，胡兵可被打败。太白，星名，一名启明星。太白入月，按星象家的说法，太白星主杀戮，入月入昴为灭胡之象。诗文中常指战事。摧，挫败。\n旄头灭：灭胡之星象。旄头，也作髦头，即昴星，为胡星。这里代指胡兵。\n紫塞：北方边塞。晋崔豹《古今注》：《都邑》：秦筑长城，土色皆紫，汉塞亦然，故称紫塞焉。\n三千霜：三千岁。霜：谓秋也。\n“但歌”二句：引汉高祖刘邦《大风歌》入句：“大风起兮云飞扬，威加海内兮归故乡，安得猛士兮守四方？”敦煌残卷唐诗写本无“陛下”三句。诗末一本还有两句：“胡无人，汉道昌。”苏轼等人谓“陛下”后几句为后之好事者画蛇添足，按诗意，应删去。', poem_tags = '战争,豪迈' WHERE poem_title = '胡无人' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '你若要归山无论深浅都要去看看；\n山峦沟壑清净秀美要尽情地赏玩。\n千万别学陶渊明笔下那个武陵人，\n只在桃花源游了几天就匆匆出山。', poem_notes = '武陵人：指陶潜《桃花源记》的武陵渔人。', poem_appreciation = '“归山深浅去，须尽丘壑美。”这两句是说这次回到山里之后，不论入山深浅，都要饱览山川之秀丽，林木之幽美。这当然是劝勉崔兴宗不要再留恋世俗的生活，把对山水的感情升华到一种与世俗生活相对立的高度，这与他们对现实的厌倦与反感有关。“莫学武陵人，暂游桃源里。”这两句是劝崔兴宗隐居丘壑，既然在山水间找到了生活的真趣，就不要再从那个境界里返回到现实中来了。这一方面表达了对隐居生活的肯定，另一方面也表达了对现实的不满。作者为什么要人留恋那个“不知有汉，无论魏晋”的世外桃源呢？这是由于他们在现实中屡屡失败，一方面产生了对现实生活的反感，另一方面也更深刻地认识了现实生活。作者生活的时代大约属于唐玄宗和唐肃宗时期，这首诗大约作于唐玄宗后期。那个时候由于唐玄宗任用奸相李林甫，宠幸杨贵妃，政治十分黑暗，下层知识分子无法入仕，像裴迪、崔兴宗这样的寒士没有出路。所以他们宁愿隐居山林，过一种与世隔绝的生活。因此作者劝他的朋友，既然在山水之间找到了真趣，找到了自己思想感情的寄托，就不要像陶渊明《桃花源记》里的武陵人一样，找到了桃花源却轻易地放弃了。作者认为这是一个错误，因此他说：“莫学武陵人，暂游桃源里。”\n\n　　这首诗语言浅显易懂，但立意很深，不失为一首好诗。', poem_tags = '唐诗三百首,离别,规劝' WHERE poem_title = '崔九欲往南山马上口号与别 / 留别王维 / 送崔九' AND poem_author = '裴迪';
UPDATE edu_poem SET poem_translation = '首诗是初唐诗人张若虚的作品，全诗艳丽工整，欲出宫体之篱，似启温李之风，张若虚的诗风上承齐梁，下开盛唐，在诗歌的历史中起到了承上启下的作用。大家往往认为，是初唐四杰为盛唐诗歌的兴盛局面打下了良好的开端。实际上，张若虚也是功不可没的一员。这首拟闺怨诗就是最好的证明。\n\n　　诗人首句点题，为戍守关塞，年轻的丈夫与妻子离别了。场景是凄清动人的，但作者仅仅是一笔带过，给读者以无穷的想象空间。他仅仅描绘了送别的尾声：妻子伫立于楼台之上，遥望着三步一回头的丈夫，直到他的身影消失在遥远的地平线。这是送别的结束，却是全诗的开始。\n\n　　离别之后，这位女主人公就陷入了漫长的', poem_appreciation = '这首诗是初唐诗人张若虚的作品，全诗艳丽工整，欲出宫体之篱，似启温李之风，张若虚的诗风上承齐梁，下开盛唐，在诗歌的历史中起到了承上启下的作用。大家往往认为，是初唐四杰为盛唐诗歌的兴盛局面打下了良好的开端。实际上，张若虚也是功不可没的一员。这首拟闺怨诗就是最好的证明。\n\n　　诗人首句点题，为戍守关塞，年轻的丈夫与妻子离别了。场景是凄清动人的，但作者仅仅是一笔带过，给读者以无穷的想象空间。他仅仅描绘了送别的尾声：妻子伫立于楼台之上，遥望着三步一回头的丈夫，直到他的身影消失在遥远的地平线。这是送别的结束，却是全诗的开始。\n\n　　离别之后，这位女主人公就陷入了漫长的苦思中，但也要强打精神来梳妆打扮。穿上了新衫，才感觉到了春天的温暖。简单的梳妆后，她把目光投向了窗外。窗外生机盎然、花红柳绿。偶有燕子飞过，透过罗幕看看她。不知何时，有几只蜜蜂也打起了她那件“画衣”的主意。诗人在此著一生花妙笔，画衣上绣的花竟然能把蜜蜂引来，可见其逼真生动，又可见思妇对这画衣是如何的用心。这句将她百无聊赖却又想借此给心上人带来惊喜的心情彰显无疑。\n\n　　春季正是山花烂漫的季节，桃红李白，而女主人公的心绪却纷乱如麻。忽然从遥远的方向，传来了悠扬的乐声，大约是《折柳》吧！于是她让自己沉醉在其中，让自己的心飞向遥远的边塞，飞到丈夫的身边。\n\n　　上面四句借对外物描写，来烘托女主人公的心境。而下面笔锋一转，又转到了女主人公本人。她幻想着丈夫会在未来的某一天回来，于是盛装打扮，等待着遥远的离人。而春去秋来，花开花落，该回来的人却还没有回来。夜渐渐深了，她进入了梦乡。但她却陷入了“惟梦闲人不梦君”的新的苦恼中。最后她醒了，重重的长叹一声，“唉——”在寂静的夜里，这一声长叹竟是回声重重。在重重的回声中，她无奈的再次把大门关上了。\n\n　　作者多用侧面烘托的手法，借助带有感情色彩的事物来抒情。另外，这首诗对于人物心理描写的方式又可称得起是别具一格。句句不直接描绘心境，可句句写的都是心境。如果要将这首诗翻译成为意识流作品，那就韵味大减。好比将一个曲曲折折的迷宫拉直，明了易懂，但趣味却荡然无存了。\n\n　　张若虚有很多优秀的作品，但仅仅流传下来两首。除了这首之外，还有一首就是广为流传的 《春江花月夜》。余下的诗，都在漫长的岁月中散失了。', poem_tags = '闺怨' WHERE poem_title = '代答闺梦还' AND poem_author = '张若虚';
UPDATE edu_poem SET poem_translation = '终南山上有什么？有山楸来有梅树。有位君子到此地，锦绣衣衫狐裘服。脸儿红红像涂丹，莫非他是我君主？\n\n终南山上有什么？有棱有角地宽敞。有位君子到此地，青黑上衣五彩裳。身上佩玉响叮当，富贵寿考莫相忘。\n\n译文二\n终南山上有什么？有山楸来有梅树。有位君子到此地，锦绣衣衫狐裘服。脸儿红红像涂丹，那是我的君王啊。\n\n终南山上有什么？有棱有角地宽敞。有位君子到此地，青黑上衣五彩裳。身上佩玉响叮当，到寿命终结也忘不了。\n\n注：在此“也哉”可用语助词解，而且“也”的其他用法中一般不存在在这种情况下当或许的可能。考为寿命终结和长寿的意思，这样就形成了本诗的不同理解模式。', poem_notes = '终南：终南山，在今陕西西安市郊外。\n条：树名，即山楸。材质好，可制车板。\n锦衣狐裘：当时诸侯的礼服。《礼记·玉藻》：“君衣狐白裘，锦衣以裼之。”\n渥（wò）：涂。丹：赤石制的红色颜料，今名朱砂。\n纪：山角。堂：山上宽平处。朱熹《诗集传》：“纪，山之廉角也。堂，山之宽平处也。”一说纪和堂是两种树名，即杞柳和棠梨。\n黻（fú）衣：黑色青色花纹相间的上衣。绣裳：五彩绣成的下裳。当时都是贵族服装。\n将将：同“锵锵”，象声词。\n考：高寿。亡：通“忘”。', poem_appreciation = '关于这首诗作者身份的推测，前人有两种说法：其一，秦大夫所作。《诗序》以为“（襄公）能取周地，始为诸侯，受显服，大夫美之故作是诗，以戒劝之”。其二，周遗民所作。方玉润《诗经原始》云：“此必周之耆旧，初见秦君抚有西土，皆膺天子命以治其民，而无如何，于是作此。”其最有力的推断即是“其君也哉”一句。严粲《诗缉》云：“‘其’者，将然之辞。‘哉’者，疑而未定之意。”此句意为：“这个人将成为我们的君主吗？”方玉润说：“秦臣颂君，何至作疑而未定之辞，曰‘其君也哉’，此必不然之事也。”理由较充足，可信为周遗民之作。现代有的研究者认为是终南山的姑娘，对进山的青年表示爱慕之心而作，亦别开生面，可备参考。　又关于此诗究竟是“美”还是“戒”，前人亦意见不一。朱熹《诗集传》主“此秦人美其君之词”，姚际恒亦肯定“有美无戒”。而《诗序》的总体评价是：“《终南》，戒襄公也。”方玉润则以为此诗“美中寓戒，非专颂祷”。从诗的实际情况来看，方氏所见较为平允。\n\n　　诗的“美”，最主要是赞颂秦公的容颜、服饰和仪态。两章诗都对“君子”的来到表示出敬仰和赞叹的态度。那君子的脸红润丰泽，大有福相。那诸侯的礼服，内里狐白裘，外罩织锦衣，还有青白相间斧形上装和五次斑斓的下裳，无不显得精美华贵，熠熠生辉。诗中对秦公的衣着有着一种新鲜感，不像是司空见惯习以为常的感觉，秦公也像是在炫耀华服似的，在在证明这确是秦襄公被始封为诸侯而穿上显服的情景。《史记·秦本纪》：“（周）平王封襄公为诸侯，赐之歧以西之地。其子文公，遂收周遗民有之。”诗大约就作于那时期。除了服装外，诗还写到了饰物的佩声锵锵，那身上琳琅的美玉挂件叮当作响，音韵悦耳。这就见出诗所描摹的形象是动态的，行进中的，仿佛让人感觉到秦公步履雍容来到终南山祭祀行礼。诗通过视觉、听觉形象的勾勒，至少在外观上透出富贵气派和令人敬仰感。\n\n　　至于作者所代表的周遗民的内心感受是怎样的，似乎不像外在敬意那样简单，两章末尾各有一句耐人寻味的结语。第一句是“其君也哉”，从那惊疑不定的揣测口吻中，显出忐忑不安忧喜参半的复杂心情。新君降临一方，旧地遗民自有前途未卜的紧张心理，这很真实自然。第二句是“寿考不忘”，意谓：秦君哪，你富贵寿考，但最终不要忘记这里曾是周王的土地和百姓呵！将祝福、叮咛、告诫、期望种种难以直言的心境委婉托出。辨味这两句，诗确实是意存劝戒，希望秦君是明君，而不是暴君。至于为什么那么含蓄婉曲，汪中《述学·释三九》说：“周人尚文，君子之于言不径而致也，是以有曲焉。”倒是较为圆通的。不过，最主要的恐怕还是不便直说。\n\n　　最后看看两章诗的起兴有何意味。首先，周民搬出引以为豪的周地名山起兴，显示了王都之民的身分和某种程度的优越感，也可使初来乍到的秦公不至小觑他们。就此意义而言，或有借当地名胜以壮胆撑门面的虚荣心理吧。其次，更为重要的是，终南山又名中南山，巍峨险峻，为万众仰慕。《尚书·禹贡》：“终南悖物。”《左传·昭公四年》：“荆山、中南，九州之险。”皆指此山。终南山有丰富的物产，尤以根深叶茂的林木为代表。还有宽衍险奥气象万千的山势。这些表面物象，明眼人都不难看清。那么作者何以要如数家珍不惜饶舌呢？一层意思是以隆崇的终南山，暗寓对秦公尊严身分的褒扬，有以伟物兴伟人的奉承之意。另一层意思是让秦公好好思忖一下：你真的能像终南山一样的受人尊崇吗？你只有修德爱民，不负众望，才能与名山的地位相媲美。正如后世曹操《短歌行》诗所云：“山不厌高，水不厌深。周公吐哺，天下归心。”其寓戒于颂一石两鸟的用意非常含蓄巧妙。\n\n　　而另一解，诗只是对主君的赞扬。纵观秦风各部与其他各师不同不是大多言色，如果按本诗前文到最后的意思承接来看只是对秦君的赞扬，参照朱熹《诗集传》主“此秦人美其君之词”，姚际恒亦肯定“有美无戒”，可以解释为第二种。', poem_tags = '诗经,赞美' WHERE poem_title = '终南' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '古往今来北邙山下的道路，黄尘滚滚不知老尽了多少英雄。人生常有怨恨就像那流水常年向东。郁抑的情怀能和谁说，放眼把空中的归雁远送。\n举世显赫的功名有什么用，过去实在是错怪了天公。放声高唱一曲饮酒千钟。男儿行事处世就应如此，不要计较什么穷困亨通。', poem_notes = '临江仙：词牌名，原为唐代教坊曲名。格律俱为平韵格，双调小令，字数有五十二字、五十四字、五十八字、五十九字、六十字、六十二字六种。常见者全词分两片，上下片各五句，三平韵。\n孟津： 黄河渡口名。在今河南孟津县东，洛阳东北。\n北邙（máng）山：即邙山，在洛阳北，黄河南。王公贵胄多葬于此。\n黄尘： 指岁月时光。\n幽怀： 隐藏在内心的情感。\n底：何，什么。\n浩歌： 放声高歌，大声歌唱。\n钟： 同盅。\n行处： 做官或退隐。\n穷通： 穷困与显达。', poem_appreciation = '该词上片以回顾历史起句，拢“今古英雄”于笔端，词人将自己的感情融于历史长河，写出了滔滔不尽、起伏跌宕的痛惜与感伤。“远目送归鸿”的意象，动静结合，相辅相成，动的是归鸿的悠悠远去，静的是词人凝重的望眼；飞去的是天空的鸿雁，搅起的是满腔的幽怨。该词描绘出了一幅凄凉而又充满美感，谐调而又扣人心弦的画面。鸿雁飞，鸿雁归，人将何处回？ 词人的感情随着这激荡人心的画面盘旋弥漫，感人至深。\n\n　　下片强压“长恨”浩歌放饮的意象，是“抽刀断水水更流”式的自我宽解，词人的郁愤欲盖而弥彰，显得蕴藉而深远，更加挥之不去，难以摆脱。词人身处江河日下的时代，又遭“莫须有”的诘难，心中的郁愤自不待言。词作通过描写阔大的意象，以辽阔显苍凉，以浩歌掩感伤，词人内心的矛盾与痛苦可想而知。\n\n　　全词开篇写景，景即眼中所见： 北邙山上的坟墓； 黄尘路上奔波到老的英雄； 春北飞秋南归的大雁以及日日奔腾的东流水，景物选取由近及远，然后由写景转入抒情，此景引起的是作者内心的无限惆怅，因此词人低吟出“人生长恨水长东”的词句。再由抒情转入下片的议论： 对人生短暂的无可奈何和对未来的玩世安排，水到渠成汩汩而出。“盖世功名将底用，从前错怨天公。”是词人纵观自然及人事沧桑，感情经过激烈碰撞后得出的人生结论，不无哲理意义，它涵了封建社会大多数读书人的生活道路和人生体味，起到了一种生活教科书作用。', poem_tags = '豪放,吊古伤今' WHERE poem_title = '临江仙·自洛阳往孟津道中作' AND poem_author = '元好问';
UPDATE edu_poem SET poem_translation = '诗寓意深微邃却含而不露。元朝统治者奉行种族歧视政策，以蒙古、色目人为上等人，以汉人、南人为下等人。蒙古、色目人到江南之地也凌驾于南人之上作威作福。他们靠江南的条件富有了，却仍辱骂江南人不绝。诗人心中不平，故作此诗以讥之。\n\n　　揭傒斯的五言短古，在很大程度上体现了宋元以来“重逸轻俗”的审美倾向。如《寒夜 》：“ 疏星冻霜空，流月湿林薄。虚馆人不眠，时闻一叶落。”《题风烟雪月四梅图》之二：“高花开几点，澹霭拂成衣。遥瞻应不见，相对尚依稀。”《洞庭秋月》：“灏气自澄穆，碧波还荡漾。应有凌风人，吹笛君山上。”《平沙落雁》：“天寒关塞远，水落洲渚阔。已逐夕阳低，还向黄芦没。”', poem_appreciation = '此诗寓意深微邃却含而不露。元朝统治者奉行种族歧视政策，以蒙古、色目人为上等人，以汉人、南人为下等人。蒙古、色目人到江南之地也凌驾于南人之上作威作福。他们靠江南的条件富有了，却仍辱骂江南人不绝。诗人心中不平，故作此诗以讥之。\n\n　　揭傒斯的五言短古，在很大程度上体现了宋元以来“重逸轻俗”的审美倾向。如《寒夜 》：“ 疏星冻霜空，流月湿林薄。虚馆人不眠，时闻一叶落。”《题风烟雪月四梅图》之二：“高花开几点，澹霭拂成衣。遥瞻应不见，相对尚依稀。”《洞庭秋月》：“灏气自澄穆，碧波还荡漾。应有凌风人，吹笛君山上。”《平沙落雁》：“天寒关塞远，水落洲渚阔。已逐夕阳低，还向黄芦没。”《烟寺晚钟》：“朝送山僧去，暮唤山僧归。相唤复相送，山露湿人衣。”这些诗作是承续王维、孟浩然、韦应物、刘长卿一系的诗风而又加以发展的。其境界高逸，远离尘俗，表达了一种宋元以来的士大夫情调。其中《寒夜》最让人回味，小诗以寥寥二十字的白描，传神地绘出一幅清夜客旅图。一、二句状写户外的景色，以凝冻在布满霜气的夜空中的疏星、沾湿了草木的月的流光（“林薄”，谓草木丛生），制造出一种清旷冷寂的氛围。三句转入客舍，在“虚馆”的典型环境中，“人不眠”的主体便格外突出。最精彩的是末句的五字。“一叶落”的声音是够细微的了，馆中人却能清晰的辨闻，足见夜间的寂静；而一个“时”（时时、时而之意）字，更将漫漫长夜中不眠人的警醒，表现得淋漓尽致。这一句不仅沟通了馆内外的联系，而且传达出诗人在长捱客栈中愁苦的心绪，可谓是神来之笔。', poem_tags = '秋天,写鸟,讽刺' WHERE poem_title = '秋雁' AND poem_author = '揭傒斯';
UPDATE edu_poem SET poem_translation = '从前有两个老翁住在同一个城市里关系和特别好甲老翁的妻子和孩子早去世了只有他自己而已一天他带着酒去乙翁的家两个人一起喝酒十分快乐!乙翁说:“以前我曾去巴蜀远处交游但没有登过泰山心中很悔恨你能不能和我一起去呢?“甲翁说:“那山很陡峭我也没有登过总想着他然而老了恐怕力气不够“乙翁说:“你说的不对吧以前的愚公九十岁的时候还可以移山今日我们才六十来岁哪里老呢!“甲翁说:“那太好了“第天两个老人都去了走过钱塘渡过长江走着从鸸到泰山的北面晚上住下休息凌晨上山乙翁要扶他甲翁说:“我的力气还可以不用互相搀扶“从太阳出来到薄暮降临已经走过了半坐大山', poem_notes = '昔：以前从前\n里：乡（古代居民行政组织的一种，五家为一邻，五邻为一里。）\n妻子：妻子和孩子\n叟：老头\n（唯叟一人）而已：罢了\n携：携带\n第：房屋、宅子、家\n酌：饮（酒）\n向：以前\n吾：我\n远游：到远处游玩\n冀、雍：古代两个州名，在今约山西、陕西、甘肃一带\n是:这　然：但是\n意：意愿\n同行：一同出行\n余：我\n亦：也\n未：没有\n然：然而\n恐：担心\n胜：能承受，承担。\n差矣，汝之言：是“汝之言差矣”的倒装句\n曩：以往过去\n年：年龄\n且：将近\n辈：等，类，表示人或物的多数同属一类\n方：才\n逾：超过\n甚善：太好了\n翌日：第二天\n偕：一起，一同\n越：经过\n绝：横渡\n相：互相，此指代“我”\n自：从\n至：到，达\n薄暮：傍晚，日将落时\n阴:古代山北水南叫“阴”\n尝：曾经\n去：离开\n何老之有：即为“有何老”；之，宾语前置的标志。\n是：这', poem_tags = '小学文言文,故事,哲理,初中文言文,励志,故事' WHERE poem_title = '二翁登泰山' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '团扇，团扇，宫中的美人病后用它来遮面。\n抱病三年，容颜憔悴，再没有谁同她商量管弦！\n管弦，管弦，无情的春草把通往昭阳殿的道路阻断。', poem_notes = '调笑令：词牌名，此调亦即《宫中调笑》（又称《转应曲》。黄升云：“王仲初（王建字仲初）以宫词百首著名，《三台令》、《转应曲》，其余技也。”此词即属“宫词”之余。词调本以“转应”为特点，凡三换韵，仄平仄间换；而此词内容上亦多转折照应，大体一韵为一层次。\n团扇：圆形的扇子，古代歌女在演唱时常用以遮面。\n管弦：用丝竹做的乐器，如琴、箫、笛。\n昭阳：昭阳殿，借指皇帝和宠妃享乐之地。', poem_appreciation = '“团扇，团扇，美人病来遮面。”以咏扇起兴，同时绘出一幅妍妙的宫中仕女图。“新裂齐纨素，皎洁如霜雪。裁成合欢扇，团团如明月。”（班婕妤《怨歌行》）美的团扇，是美人的衬托。人的处表美当与健康分不开，但在封建时代，士大夫的审美观却是：西子捧心则更添妍姿。词起首写美人病来，自惭色减，以扇遮面，而纨扇与玉颜掩映，反有“因病致妍”之妙。如此写人，方为传神；如此咏物，方觉生动。倘如说“病态美”于今天的读者已经隔膜，那也无关紧要，因为全词的旨趣并不在此。作者最多不过是借此表明一种“红颜未老恩先断”的感慨罢了。\n\n　　“玉颜憔悴三年，谁复商量管弦！”“玉颜憔悴”上应“美人病来”，却从咏物及人的外部动态过渡到写人物的命运和内心活动，转折中词意便深入一层。从下句的“复”字可会出，“三年”前美人曾有人与同“商量管弦”，以歌笑管领春风，而这一切已一去不复返。可见美人的“病”非常病，乃是命运打击所致，是由承恩到失宠的结果。“玉颜憔悴三年”，其中包含多少痛苦与辛酸。“谁复商量管弦！”将一腔幽怨通过感叹句表出。谁，有谁，也即“没有谁”。冷落三年之久，其为无人顾问，言下自明，语意中状出一种黯然神伤、独自叹息的情态。\n\n　　“弦管，弦管，春草昭阳路断。”点明宫怨之意。“昭阳”，汉殿名，为汉成帝赵昭仪所居，用来指得宠的所在。“昭阳路断”即“君恩”已断，不直言这是因为君王喜新厌旧所致，而托言是春草萋萋遮断通往昭阳之路，含怨于不怨，尤婉曲有味。这从昭阳殿那边隐约传来的歌吹之声，会勾起久已不复有人“商量管弦”的宫人多深的惆怅，是不言面喻的。于是，“团扇”的兴义立见，它暗用了班婕妤著名的《怨歌行》的全部诗意，即以“秋扇见弃”暗示“恩情中道绝”。则所谓“美人病来遮面”亦不仅是自惭形秽而已，其中颇含“且将畴扇共徘徊”（王昌龄《长信秋词》）的感慨，见物我同情。这又是首尾转应了。\n\n　　本来“弦管”的叠语按律只为上句末二字“管弦”倒文重叠咏叹，不必具实义。此词用来却能化虚为实，使二叠语大有助于意境的深化和词意的丰富。全词这所以能曲尽“转应”之妙，与此大有关系。这样的句子，方称得上“活句”。', poem_tags = '宋词三百首,婉约,乐府,咏物,感慨,时光' WHERE poem_title = '宫中调笑·团扇' AND poem_author = '王建';
UPDATE edu_poem SET poem_translation = '译文 江边上空的夕阳笼罩江边沙滩。潮水退了，渔船倾斜着靠在岸边。 一对白色水鸟停在江水旁。闻得有人来，就警觉地飞入芦苇丛中。', poem_tags = '古诗三百首,写景' WHERE poem_title = '江村晚眺' AND poem_author = '戴复古';
UPDATE edu_poem SET poem_translation = '转回车子驾驶向远方，路途遥远，长途跋涉，难以到达。\n一路上四野广大而无边际，春天的东风吹摇枯萎的野草。\n眼前看到的都不是过去的事物，人怎么能够不迅速衰老？\n盛和衰各有不同的时间，只恨建立功名的机会来得太迟。\n人不如金石般坚固，生命是脆弱的，怎么能够长寿不老？\n倏忽之间生命就衰老死亡了，应立刻进取获得声名荣禄。', poem_notes = '回：转也。驾：象声词。言：语助词。迈：远行也。一说喻声音悠长。\n悠悠：远而未至之貌。涉长道：犹言“历长道”。涉，本义是徒步过水；引申之，凡渡水都叫“涉”；再引申之，则不限于涉水。\n茫茫：广大而无边际的样子。这里用以形容“东风摇百草”的客观景象。\n东风：指春风。百草：新生的草。\n无故物：承“东风摇百草”而言。故，旧也。\n“焉得”句：是由眼前事物而产生的一种联想，草很容易由荣而枯，人又何尝不很快地由少而老呢？\n各有时：犹言“各有其时”，是兼指百草和人生而说的。“时”的短长虽各有不同，但在这一定时间内，有盛必有衰，而且是由盛而衰的。\n立身：犹言树立一生的事业基础。早：指盛时。\n“人生”句：言生命的脆弱。金，言其坚。石，言其固。\n寿考：犹言老寿。考，老也。即使老寿，也有尽期，不能长久下去。\n奄忽：急遽也。随物化：犹言“随物而化”，指死亡。\n荣名：美名。一说指荣禄和声名。', poem_appreciation = '此诗含义为何，佳处为何，要理解正确，关键在于对篇末“荣名”二字的解诂。古今注本于荣名有二解。一说荣名即美名，又一说则谓荣名为荣禄和声名。由前说，结二句之意为人生易尽，还是珍惜声名为要；由后说，则其意变为：人生苦短，不如早取荣禄声名，及时行乐显身。二说之境界高下，颇有不同。今按荣名一词，古籍屡见。如《战国策·齐策》：“且吾闻效小节者不能行大威，恶小耻者不能立荣名。”《淮南子·修务训》：“死有遗业，生有荣名。”其均为令誉美名之义甚明。\n\n　　疑义既释，则诗意及结构自明。诗以景物起兴，抒人生感喟。回车远行，长路漫漫，回望但见旷野茫茫，阵阵东风吹动百草。这情景，使行旅无已，不知税驾何处的诗人思绪万千，故以下作句，二句一层，反复剀陈而转转入深。“所遇”二句由景入情，是一篇枢纽。因见百草凄凄，遂感冬去春来，往岁的“故物”已触目尽非，那么新年的自我，就不能不匆匆向老。这是第一层感触。人生固已如同草木，那么一生又应该如何度过呢？“盛衰各有时，立身苦不早。”“立身”，应上句“盛衰”观之，其义甚广，当指生计、名位、道德、事业，一切卓然自立的凭借而言。诗人说，在短促的人生途中，应不失时机地产身显荣。这是诗人的进一层思考。但是转而又想：“人和非金石，岂能长寿考”，即使及早立身，也不能如金石之永固，立身云云，也属虚妄。这是诗人的第三层想头。那么什么才是起初的呢？只有荣名——令誉美名，当人的身躯归化于自然之时，如果能留下一点美名为人们所怀念，那末也许就不虚此生了吧。终于诗人从反复的思考中，得出了这一条参悟。\n\n　　当汉末社会的风风雨雨，将下层的士子们恣意播弄时，他们都不约而同地对生命的真谛进行思索。有的高唱“何不策高足，先据要路津，无为守贫贱，轗轲常苦辛”（《今日良宴会》），表现出争竞人世的奋亢；有的则低吟“服食求神仙，多为民误。不如饮美酒，被服纨与素”（《驱车上东门》），显示为及时行乐的颓唐。而这位愿以荣名为宝的诗人，则发而为洁身自好的操修。虽然他同样摆脱不了为生命之谜而苦恼的世纪性的烦愁，然而相比之下，其思致要深刻一些，格调也似乎更高一点。\n\n　　显然，这是一首哲理性的杂诗，但读来却非但不觉枯索，反感到富于情韵。这一方面固然因为他的思索切近生活，自然可亲，与后来玄言诗之过度抽象异趣，由四个层次的思索中，能感到诗人由抑而扬，由扬又以抑，再抑而再扬的感情节奏变化。另一方面，也许更重要的是，这位诗人已开始自觉不自觉地接触到了诗歌之境主于美的道理，在景物的营构，情景的交融上，达到了前人所未有的新境地。诗的前四句，历来为人们称道，不妨以之与《诗经》中相近的写法作一比较。\n\n　　“彼黍离离，彼稷之苗。行迈靡靡，中心摇摇。知我者谓我心忧，不知我者谓我何求。悠悠苍天，此何人哉！”\n\n　　这首《王风·黍离》是《诗经》的名篇。如果不囿于先儒附会的周大夫宗国之思的教化说，不难看出亦为行人所作。以此诗与之相比，虽然由景物起兴而抒内心忧苦的机杼略近，但构景状情的笔法则有异。《王风·黍离》三用叠词“离离”、“靡靡”、“摇摇”，以自然的音声来传达情思，加强气氛，是《诗经》作为上古诗歌的典型的朴素而有效的手法。而此诗则显得较多匠心的营造。“回车驾言迈，悠悠涉长道。四顾何茫茫，东风摇百草。”“迈”、“悠悠”、“茫茫”、“摇”，叠词与单字交叠使用，同样渲染了苍茫凄清的气氛，然而不但音声历落，且由一点——“车”，衍为一线——“长道”，更衍为整个的面——“四顾”旷野。然后再由苍茫旷远之景中落到一物“草”上，一个“摇”字，不仅生动地状现了风动百草之形，且传达了风中春草之神，而细味之，更蕴含了诗人那思神摇曳的心态。比起《黍离》之“中心摇摇”来，此诗之“摇”字已颇具锻炼之功，无怪乎前人评论这个摇字为“初见峥嵘”。这种构景与炼字的进展与前折“所遇”二句的布局上的枢纽作用，已微逗文人诗的特征。唐皎然《诗式·十九首》云：“《十九首》辞精义炳，婉而成章，始见作用之功。”（作用即艺术构思），可称慧眼别具；而此诗，对于读者理解皎然这一诗史论析，正是一个好例。\n\n　　皎然所说“初见作用之功”很有意思，这又指出了《古诗十九首》之艺术构思尚属于草创阶段。此诗前四句的景象营构与锻炼，其实仍与《黍离》较近，而与后来六朝唐代诗人比较起来，是要简单得多，也自然得多。如陆云《答张博士然》：“行迈越长川，飘摇冒风尘。通波激枉渚，悲风薄丘榛。”机杼亦近，但刻炼更甚，而流畅不若。如果说《十首诗》是“秀才说家常话”（谢榛《四溟诗话》），那末陆云则显为秀才本色了。由《黍离》到此诗，再到陆云上诗，可以明显看出中国古典诗歌的演进足迹，而此诗适为中介。所以陆时雍《古诗镜·总论》说“《十九首》谓之《风》馀，谓之诗母”。\n\n　　对于人生目的意义之初步的朦胧的哲理思考，对于诗歌之文学本质的初步的朦胧的觉醒。这两个“初步”，也许就是此诗乃至《古诗十九首》整组诗歌，那永久的艺术魅力之所在。', poem_tags = '古诗三百首,古诗十九首,感叹,人生,哲理' WHERE poem_title = '回车驾言迈' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '在丹江外城边上送别行舟，今天一别我知道两地悲愁。\n天晚我仍站在江南望江北，乌鸦都已归巢只见水悠悠。', poem_notes = '参军：古代官名。\n丹阳：地名。唐天宝间以京口（今江苏镇江）为丹阳郡，曲阿为丹阳县（今江苏丹阳县）。二者地理位置相近。\n郭：古代在城外围环城而筑的一道城墙。\n行舟：表示友人将从水路离去。\n别：离别。\n日晚：日暮，此处暗示思念时间之久。\n江：长江。\n寒鸦：也叫慈乌，体型较小，背部为黑色。\n悠悠：长久遥远。', poem_appreciation = '江淹《别赋》说：“黯然销魂者，唯别而已矣!”古往今来，多少人为世间的“生别离”而浩叹、而惆怅。发而为诗，便出现许多传世的佳作。严羽说：“唐人好诗，多是征戍、迁谪、行旅、离别之作，往往能感动激发人意。”(《沧浪诗话·诗评》)因为这一类作品一般都感情真实充沛，极少造作，故最易打动人心。\n\n　　《丹阳送韦参军》是一首送别的好诗，它感情真挚深厚，造语清丽流畅，读之余味无穷。\n\n　　首句“丹阳郭里送行舟”，交代了送别的地点——丹阳的内外城之间，友人出行的方式——由水路乘船。古代城防有内外两道，内为城而外为郭。丹阳是江城，故郭里也能行船。\n\n　　次句“一别心知两地秋”，交代送别的时间——秋天。“一叶落而知天下皆秋”。“两地秋”之语，并不是说两地秋色有何不同，而是说同样秋色，而人已分两地。惜别之情，溢于言外。值得注意的还有句中隐含着的“愁”字。“愁”字可以被分解为“心”、“秋”两字，故诗人往往用“秋心”、“心上秋”之类的辞藻来暗指“愁”字。本句“一别心知两地秋”，明写秋而隐写愁，耐人寻味。\n\n　　第三、四句写别后的情景。“日晚江南望江北”，点明友人远行的方向——江北。兰舟已逝，离情难舍。天色向暮；连成群的寒鸦也纷纷飞尽，各自归入巢中。但是，诗人仍在江畔伫立，久久地凝望着友人离去的方向。“寒鸦飞尽水悠悠”，是望中之景，然而景中有情，情景交融，合为一体。友人远去，相见无期，鸟儿飞尽，无踪可寻。天地间显得多么空阔、多么寂寞。只有那无尽的江水在无言地流淌，恰如诗人心中无限的忧愁。\n\n　　补充：这首七绝是作者抒写他给韦参军送行以及送走之后的情景，表现了他们之间的真挚情谊。', poem_tags = '送别,思念,友情' WHERE poem_title = '丹阳送韦参军' AND poem_author = '严维';
UPDATE edu_poem SET poem_translation = '春天来了，垂杨荡漾在白云绿水间，它那美丽的枝条随着春风飘扬，好不娇美。这里适逢生机蓬勃的春天，花儿争相开放，但玉关边塞此时却是冰雪交加，美人每当想起这些，都会倍感惆怅。她在金窗前独自凭依，看叶暖烟空，心中更有无限离愁。她面对此景心中常会荡起一种凄凉之感。真想攀折柳条，以远寄到情郎所在的龙城前，让他明白她的一片相思。', poem_notes = '摇艳：美丽的枝条随风飘扬。\n年：时节。\n长想：又作“长恨”。\n龙庭：又叫龙城。是匈奴祭天、大会诸部之地。', poem_tags = '乐府,春天,女子,思念' WHERE poem_title = '折杨柳' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '咚咚作响伐木声，嘤嘤群鸟相和鸣。鸟儿出自深谷里，飞往高高大树顶。小鸟为何要鸣叫？只是为了求知音。仔细端详那小鸟，尚且求友欲相亲。何况我们这些人，岂能不知重友情。天上神灵请聆听，赐我和乐与宁静。\n伐木呼呼斧声急，滤酒清纯无杂质。既有肥美羊羔在，请来叔伯叙情谊。即使他们没能来，不能说我缺诚意。打扫房屋示隆重，嘉肴八盘桌上齐。既有肥美公羊肉，请来舅亲聚一起。即使他们没能来，不能说我有过失。\n伐木就在山坡边，滤酒清清快斟满。行行笾豆盛珍馐，兄弟叙谈莫疏远。有人早已失美德，一口干粮致埋怨。有酒滤清让我饮，没酒快买我兴酣。咚咚鼓声为我响，翩翩舞姿令我欢。等到我有闲暇时，一定再把酒喝完。', poem_notes = '丁（zhēng）丁：砍树的声音。\n嘤嘤：鸟叫的声音。\n相：审视，端详。\n矧（shěn）：况且。伊：你。\n听之：听到此事。\n终……且……：既……又……。\n许（hǔ）许：砍伐树木的声音。\n酾酒：筛酒。酾（shī），过滤。有藇：即“藇藇”，酒清澈透明的样子。藇（xù），甘美，或释为“溢貌”。\n羜（zhù）：小羊羔。\n速：邀请。\n宁：宁可。适：恰巧。\n微：非。弗顾：不顾念。\n於（wū）：叹词。粲：光明、鲜明的样子。埽：同“扫”。\n陈：陈列。馈（kuì）：食物。簋（guǐ）：古时盛放食物用的圆形器皿。\n牡：雄畜，诗中指公羊。\n诸舅：异姓亲友。\n咎：过错。\n有衍：即“衍衍”，满溢的样子。\n笾（biān）豆：盛放食物用的两种器皿。践：陈列。\n民：人。\n乾餱（hóu）：干粮。愆（qiān）：过错，过失。\n湑（xǔ）：滤酒。\n酤：买酒。\n坎坎：鼓声。\n蹲蹲：舞姿。\n注释编辑丁（zhēng）丁：砍树的声音。\n嘤嘤：鸟叫的声音。\n相：审视，端详。\n矧（shěn）：况且。伊：你。\n听之：听到此事。\n终……且……：既……又……。\n许（hǔ）许：砍伐树木的声音。\n酾酒：筛酒。酾（shī），过滤。有藇：即“藇藇”，酒清澈透明的样子。藇（xù），甘美，或释为“溢貌”。\n羜（zhù）：小羊羔。\n速：邀请。\n宁：宁可。适：恰巧。\n微：非。弗顾：不顾念。\n於（wū）：叹词。粲：光明、鲜明的样子。埽：同“扫”。\n陈：陈列。馈（kuì）：食物。簋（guǐ）：古时盛放食物用的圆形器皿。\n牡：雄畜，诗中指公羊。\n诸舅：异姓亲友。\n咎：过错。\n有衍：即“衍衍”，满溢的样子。\n笾（biān）豆：盛放食物用的两种器皿。践：陈列。\n民：人。\n乾餱（hóu）：干粮。愆（qiān）：过错，过失。\n湑（xǔ）：滤酒。\n酤：买酒。\n坎坎：鼓声。\n蹲蹲：舞姿。\n迨（dài）：等待。', poem_appreciation = '历代学者一般认为这是一首宴享诗。但诗的作者及创作年代前人没有深考。\n\n　　《伐木》和《伐檀》不同，它不是描述伐木劳动，而是由伐木兴起，说到友情可贵。无论亲朋故旧还是新的相识，都要相互关心，相互帮助，并且常来常往。\n\n　　诗共三章，除首章外，都集中笔墨写宴饮。显然是把宴饮当做建立和联系友情的重要手段。\n\n　　在抒情方式之选择上，《伐木》的作者采用了一种先迂回后正面的表达方式。诗一开头，就以“丁丁”的伐木声和“嘤嘤”的鸟鸣声，令读者仿佛置身于一个远离尘世的仙境。在这里，时间仿佛停止，一切自在自为。只有这伐木之声和悦耳的鸟鸣在空旷的幽谷里回荡。一个孤独的伐木者，一个出谷迁乔去寻找知音的鸟儿，这两个意象在这仙境一般的氛围中被不断地进行视觉和听觉上的重叠和加强：声音使人联想到形象，形象又赋于声音特殊的内涵。从而最终幻化出一个远离现实政治的、借以寄托内心苦闷的超然之境。这一境界是诗人内心的人生理想在潜意识中迂回曲折的表露。同时也是厉王暴政下朝臣们心有余悸、不敢谈论政治而另寻寄托的普遍心态。现实毕竟是现实，随着这一比兴手法的完结，作为政治家的诗人终于强迫自己面对这冷酷的存在世界：“相彼鸟矣，犹求友生。矧伊人矣，不求友生。”号召人们起来改变现实，叙亲情，笃友谊，一切从头开始。然后又申之以“神之听之，终和且平”。从人情天理处说起，避开政治而为政治，这就是诗人既体察人心，又深谙做诗劝戒之道的地方。\n\n　　第二章全然是写人的活动，也就是“求友生”之具体表现。开头用语与首章部分重叠，显得整饬又有变化，读来流转而且自然。这里仍然由物兴起，但只用“伐木许许”一句，其余如对鸟鸣的描述一概略去。论者往往因为“伐木”句与后面的“酾酒”句联系紧密，就误认为它也是“赋”（直陈其事）。其实“伐木”云云，乃相应之词，不止形式上叠合延绵，内容也相仿佛，只是为避免刻板滞重，才作此省略。省略也是变化的方式，有变化才有发展，内容为之深化，形式也愈加富丽多姿。于是出现备办筵席的热闹场面：酒是甘美的，菜肴中有肥嫩羊羔，还有许多其他可口的食物，屋子也打扫得干干净净，可以看出主人的诚心诚意，因为宴请客人，不仅是出于礼仪，更是为了寻求友情。被邀请的客人都是长者，有同姓的（诸父），也有异姓的（诸舅）。诗人希望他们全都光临。“宁适不来？微我顾弗！”“宁适不来？微我有咎！”这是他的担心。由于希望甚殷，就生怕它落空。这种“患得患失”的情绪是真实的，也是感人的。它表明主人的态度十分诚恳，对友情的追求坚定不移。\n\n　　诗人还批评了不顾情谊、互相猜忌的不良现象：“既有肥羜”，“於粲洒埽，陈馈八簋”，邀请“诸父”、“诸舅”而“不来”，又于我“弗顾”。这样的局面是不利于重振祖业的政治理想的。\n\n　　第三章分两部分。前半部分是第二章的延续和发展，依然写设宴请客，不过用笔极简，旨在“示异”，以免拖沓。“笾豆有践，兄弟无远!”这次邀请是同辈，但酒菜之丰盛，礼节之周到不减于前。联系前面的有关描述，它明确地表达了这样的观点：无论长幼和亲疏（即诗中所谓“诸父”“诸舅”和“兄弟”）都应互相有爱。这种类似博爱的思想充斥整个诗篇，可以说是总的命意所在。但建议和发展友情的手段却比较单调，用现代的观点来看也未见合适，因为在酒席台上交的朋友多不可靠。也许饮食还是古人主要的交际方式，他们又多以诚待人，布设酒肉圈套，故而被诗人选作表达友情题旨的材料。另外还有反面教训，就是“民之失德，乾餱以愆”。人与人之间的矛盾和纷争往往由饮食细故引起，要创建和平局面，就得处理好饮食问题。\n\n　　后半部分是尾声，似乎由众人合唱，表达了欢乐的情绪与和睦亲善的愿望。三方面的人（主人、来宾和受邀而未至者）团结一致，气氛和谐，令人鼓舞。\n\n　　作者还为失去的友情和亲情而振臂高呼，他用饱经沧桑的笔调描绘着自己的希望和要求：普通人之间以诚相待绝不“乾餱以愆”。亲友之间相互理解（“有酒湑我，无酒酤我”）、信任，和睦快乐地相处。人和者政必通，最后，作者又是以一个超越于现实之上的境界结束全诗：在咚咚的鼓声伴奏下，人们载歌载舞、畅叙衷情，一派升平景象。这是作为政治家的诗人中兴周室之政治理想的艺术展示。\n\n　　此诗是燕乐歌词，因而它的博爱的题旨可广泛传播，有一定的影响。在艺术上它给人的突出印象有三个方面：一是靠头的比兴部分不仅构成比较鲜明的画面，而且有生动的情节，它既是独立的，又与主题部分联系紧密，这样，主体部分的命意就更加明朗，便于读者和听众感受；二是把被邀的客人分别用“诸父”“诸舅”和“兄弟”指代，覆盖面大，而又意象分明，对表达诗歌的题旨起着重要的作用，可见作者选用词语的匠心；三是结尾表现的场面色彩浓丽，节奏明快，全然是就筵席写筵席，没有穿插“点题”笔墨，却成功地渲染出团结友善的醉人气氛。诗人把自己的人生追求化作可以闻见景象，因而颇具艺术魅力。', poem_tags = '诗经,友情' WHERE poem_title = '小雅·伐木' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '泰山的南面，汶河向西流去；泰山的北面，济水向东流去。南面山谷的水都流入汶水，北面山谷的水都流入济水。处在那阳谷和阴谷南北分界处的，是古代春秋时期齐国所筑长城的遗址。最高的日观峰，在古长城以南十五里。\n　　我在乾隆三十九年（年）十二月从京城里出发，冒着风雪启程，经过齐河县、长清县，穿过泰山西北面的山谷，跨过长城的城墙，到达泰安。这月日，我和泰安知府朱孝纯从南边的山脚登山。攀行四十五里远，道路都是石板砌成的石级，那些台阶共有七千多级。泰山正南面有三条水道，（其中）中谷的水环绕泰安城，这就是郦道元书中所说的环水。我起初顺着中谷进去。（沿着小路）走了不到一半，翻过中岭，再沿着西边的水道走，就到了泰山的巅顶。古时候登泰山，沿着东边的水道进入，道路中有座天门。这东边的山谷，古时候称它为“天门溪水”，是我没有到过的。现在（我）经过的中岭和山顶，挡在路上的像门槛一样的山崖，世上人都称它为“天门”。一路上大雾弥漫、冰冻溜滑，石阶几乎无法攀登。等到已经登上山顶，只见青山上覆盖着白雪，（雪）光照亮了南面的天空。远望夕阳映照着泰安城，汶水、徂徕山就像是一幅美丽的山水画，停留在半山腰处的云雾，又像是一条舞动的飘带似的。\n　　戊申这一天是月底，五更的时候，我和子颖坐在日观亭里，等待日出。这时大风扬起的积雪扑面打来。日观亭东面从脚底往下一片云雾弥漫，依稀可见云中几十个白色的像骰子似的东西，那是山峰。天边的云彩形成一条线（呈现出）奇异的颜色，一会儿又变成五颜六色的。太阳升上来了，红的像朱砂一样，下面有红光晃动摇荡着托着它。有人说，这是东海。回头看日观峰以西的山峰，有的被日光照到，有的没照到，或红或白，颜色错杂，都像弯腰曲背鞠躬致敬的样子。\n　　日观亭西面有一座东岳大帝庙，又有一座碧霞元君（东岳大帝的女儿）庙。皇帝的行宫（出外巡行时居住的处所）就在碧霞元君庙的东面。这一天，（还）观看了路上的石刻，都是从唐朝显庆年间以来的，那些更古老的石碑都已经模糊或缺失了。那些偏僻不对着道路的石刻，都赶不上去看了。\n　　山上石头多，泥土少。山石都呈青黑色，大多是平的、方形的，很少有圆形的。杂树很少，多是松树，松树都生长在石头的缝隙里，树顶是平的。冰天雪地，没有瀑布，没有飞鸟走兽的声音和踪迹。日观峰附近几里以内没有树木，积雪厚得同人的膝盖一样平齐。\n　　桐城姚鼐记述。', poem_notes = '选自《惜宝轩诗文集》（《四部丛刊》影音原刊本）。姚鼐（nài），字姬传，一字梦谷，室名惜抱轩，清代代桐城（今安徽桐城）人。桐城派古文家。\n阳：山的南面。\n汶（Wèn）水：也叫汶河。发源于山东莱芜东北原山，向西南流经泰安东。\n济水：发源于河南济源县西王屋山，东流到山入海东。后来下游被黄河冲没。\n阳谷：指山南面谷中的水。谷，两山之间的流水道，现在通称山涧。\n当其南北分者：在那（阳谷和阴谷）南北分界处的。\n古长城：指春秋时期齐国所筑长城的遗址，古时齐鲁两国以此为界。\n日观峰：在山顶东岩，是泰山观日出的地方。\n以：在。\n乾隆三十九年：即年。\n乘：趁，这里有“冒着”的意思。\n齐河、长清：地名，都在山东省。\n限：门槛，这里指像一道门槛的城墙。\n泰安：即今山东泰安，在泰山南面，清朝为泰安府治所。\n丁未：丁未日（十二月二十八日）。\n朱孝纯子颖：朱孝纯，字子颖。当时是泰安府的知府。\n蹬（dèng）：石级。\n级：石级。\n环水：即中溪，俗称梳洗河，流出泰山，傍泰安城东面南流。\n循以入：顺着（中谷）进去。\n道少半：路不到一半。\n中岭：即黄岘（xiàn）岭，又名中溪山，中溪发源于此。\n天门：泰山峰名。《山东通志》：“泰山周回一百六十里，屈曲盘道百余，经南天门，东西三天门，至绝顶，高四十余里。”\n崖限当道者：挡在路上的像门槛一样的山崖。\n云：语气助词。\n几：几乎。\n苍山负雪，明烛天南：青山上覆盖着白雪，（雪）光照亮了南面的天空。负，背。烛，动词，照。\n徂徕（cúlái）：山名，在泰安东南。\n居：停留。\n戊申晦：戊申这一天是月底。晦：农历每月最后一天。\n五鼓：五更。\n日观亭：亭名，在日观峰上。\n漫：迷漫。\n摴蒱（chūpú）：又作“樗蒲”，古代的一种赌博游戏，这里指博戏用的“五木”。五木两头尖，中间广平，立起来很像山峰。\n极天：天边。\n采：通“彩”。\n丹：朱砂。\n东海：泛指东面的海。这里是想象，实际上在泰山顶上看不见东海。\n或得日，或否：有的被日光照着，有的没有照着。\n绛皓驳色：或红或白，颜色错杂。绛，大红。皓：白色。驳：杂。\n若偻：像脊背弯曲的样子。引申为鞠躬、致敬的样子。日观峰西面诸峰都比日观峰低，所以这样说。偻，驼背。\n岱祠：东岳大帝庙。\n碧霞元君：传说是东岳大帝的女儿。\n行宫：皇帝出外巡行时居住的住所。这里指乾隆登泰山时住过的宫室。\n显庆：唐高宗的年号。\n漫失：模糊或缺失。漫：磨灭。\n僻不当道者：偏僻，不在道路附近的。\n圜：通“圆”。\n瀑水：瀑布。', poem_tags = '初中文言文,写山,写景' WHERE poem_title = '登泰山记' AND poem_author = '姚鼐';
UPDATE edu_poem SET poem_translation = '石桥和茅草屋绕在曲岸旁，溅溅的流水流入西边的池塘。\n晴朗的天气和暖暖的微风催生了麦子，麦子的气息随风而来。碧绿的树荫，青幽的绿草远胜春天百花烂漫的时节。', poem_notes = '石梁：石桥\n弯碕：曲岸\n溅溅：流水声。唐人李端《山下泉》：“碧水映丹霞，溅溅度浅沙。”\n陂：池塘。\n晴日暖风：语本唐人薛能《折杨柳》：“暖风晴日断浮埃，废路新条发钓台。”\n花时：花开的季节，指春天。白居易《寄元九》：“月夜与花时，少逢杯酒乐。”', poem_tags = '写风,田园,写景' WHERE poem_title = '初夏即事' AND poem_author = '王安石';
UPDATE edu_poem SET poem_translation = '昨晚我裙带忽然松弛解开，早晨又看见蟢子双双飞来。\n要赶紧描眉擦粉梳妆打扮，莫非是我的丈夫快要回来。', poem_notes = '蟢子：小蜘蛛脚长者，俗称蟢子。\n铅华：指脂粉。\n藁砧：丈夫的隐语。', poem_appreciation = '南朝徐陵曾把梁代以前的诗选作十卷，定名《玉台新咏》。严羽说：“或者但谓纤艳者玉台体，其实则不然。”（《沧浪诗话》）可知这一诗集，香艳者居多。权德舆此组诗共十二首，标明仿效“玉台体”，写的是闺情，感情真挚，朴素含蓄，可谓俗不伤雅，乐而不淫。这是第十一首，写一位新娘初入夫家，惟恐处事不当的心态。\n\n　　人在寂寞郁闷之时，常常喜欢左顾右盼，寻求解脱苦恼的征兆。特别当春闺独守，愁情难耐之时更易表现出这种情绪和心理。我国古代妇女，结腰系裙之带，或丝束，或帛缕，或绣绦，一不留意，有时就难免绾结松弛，这，自古以来被认为是夫妇好合的预兆，当然多情的女主人公马上就把这一偶然现象与自己的思夫之情联系起来了。“昨夜裙带解”，或许是丈夫要回来了。她欢情入怀，寝不安寐，第二天一早，正又看到屋顶上捕食蚊子的蟢子（喜蛛，一种长脚蜘蛛）飘舞若飞：“蟢”者，“喜”也，“今朝蟢子飞”，祥兆频频出现，这不会是偶然的。喜出望外的女主人公于是由衷地默念：“铅华不可弃，莫是藁砧归！”意思是：我还得好好严妆打扮一番，来迎接丈夫的归来。藁砧，代指丈夫。\n\n　　此诗文字质朴无华，但感情却表现得细致入微。像“裙带解”、“蟢子飞”，这都是些引不起一般人注意的小节，但却荡起了女主人公心灵深处难以平静的涟漪。诗写得含蓄而耐人寻味。通篇描摹心理，用语切合主人公的身分、情态，仿旧体而又别开生面。', poem_tags = '唐诗三百首,女子,思念' WHERE poem_title = '玉台体' AND poem_author = '权德舆';
UPDATE edu_poem SET poem_tags = '古诗三百首,咏史怀古,愤懑,言志' WHERE poem_title = '渡易水' AND poem_author = '陈子龙';
UPDATE edu_poem SET poem_translation = '今天郡斋里很冷，忽然想起山中隐居的人。\n你一定在涧底打柴，回来以后煮些清苦的饭菜。\n想带着一瓢酒去看你，让你在风雨夜里得到些安慰。\n可是秋叶落满空山，什么地方能找到你的行迹？', poem_notes = '寄：寄赠。全椒：今安徽省全椒县，唐属滁州。\n郡斋：滁州刺史衙署的斋舍。山中客：指全椒县西三十里神山上的道士。\n涧：山间流水的沟。束：捆。荆薪：杂柴。白石：《神仙传》云：“白石先生者，中黄丈人弟子也，常煮白石为粮，因就白石山居，时人故号曰白石先生。”此指山中道士艰苦的修炼生活。\n瓢：将干的葫芦挖空，分成两瓣，叫做瓢，用来作盛酒浆的器具。风雨夕：风雨之夜。\n空山：空寂的深山。行迹：来去的踪迹。', poem_appreciation = '此诗题目叫“寄全椒山中道士”。既然是“寄”，自然会吐露对山中道士的忆念之情。但忆念只是一层，还有更深的一层，需要读者细心领略。\n\n　　诗的关键在于那个“冷”字。全诗所透露的也正是在这个“冷”字上。首句既是写出郡斋气候的冷，更是写出诗人心头的冷。然后，诗人由于这两种冷而忽然想起山中的道士。山中的道士在这寒冷气候中到涧底去打柴，打柴回来却是“煮白石”。葛洪《神仙传》说有个白石先生，“尝煮白石为粮，因就白石山居。”还有道家修炼，要服食“石英”。那么“山中客”是谁就很清楚了。\n\n　　道士在山中艰苦修炼，诗人怀念老友，想送一瓢酒去，好让他在这秋风冷雨之夜，得到一点友情的安慰。然而诗人进一层想，他们都是逢山住山、见水止水的人，今天也许在这块石岩边安顿，明天恐怕又迁到别一处什么洞穴安身了。何况秋天来了，满山落叶，连路也不容易找，走过的脚迹自然也给落叶掩没了，因而也不知去何处找对方。\n\n　　诗虽淡淡写来，却使读者能感到诗人情感上的种种跳荡与反复。开头，是由于郡斋的冷而想到山中的道士，再想到送酒去安慰他，终于又觉得找不着他而无可奈何；而诗人自己心中的寂寞之情，也终于无从消解。\n\n　　诗人在风雨之夜想起友人，想带着酒去拜访，可见两人的深厚友情。而满山落叶，恐不能相遇，只能寄诗抒情，又流露出淡淡的惆怅。全诗淡淡写来，却于平淡中见深挚，流露出诗人情感上的种种跳荡与反复。开头，是由郡斋的冷而想到山中的道士，又想到送酒去安慰他，终于又觉得找不着他们而无可奈何。而自己的寂寞之情，也就无从排解。\n\n　　这首诗，看来像是一片萧疏淡远的景，启人想象的却是表面平淡而实则深挚的情。在萧疏中见出空阔，在平淡中见出深挚。这样的用笔，就使人有“一片神行”的感觉，也就是形象思维的巧妙运用。韦应物这首诗，情感和形象的配合十分自然，所谓“化工笔”，也就是这个意思。', poem_tags = '唐诗三百首,怀念' WHERE poem_title = '寄全椒山中道士' AND poem_author = '韦应物';
UPDATE edu_poem SET poem_translation = '傍晚光景小鹰隼疾飞掠过，栖落在郁郁苍苍的北树林。至今我还没见过他的踪影，内心里忧心忡忡满怀担心。真想不到你怎么会这样呢？恐怕早忘了我吧我的夫君！\n高高的山上有茂密的栎树，洼地里梓树榆树繁茂成荫。至今我还没见过他的踪影，内心里满怀悒郁忧心如焚。真想不到你怎么会这样呢？恐怕早忘了我吧我的夫君！\n高高的山上有茂密的唐棣，洼地里生长着如云的山梨。至今我还没见过他的踪迹，内心里忧心忡忡如醉如痴。真想不到你怎么会这样呢？早忘了我啊没有丝毫记忆！', poem_notes = '晨风：鸟名，即鹯（zhān）鸟，属于鹞鹰一类的猛禽。\n鴥（yù）：鸟疾飞的样子。\n郁：郁郁葱葱，形容茂密。\n钦钦：忧思难忘的样子。朱熹《诗集传》：“忧而不忘之貌。”\n如何：奈何，怎么办。\n苞：丛生的样子。栎（lì）：树名。\n隰（xí）：低洼湿地。六驳（bó）：木名，梓榆之属，因其树皮青白如驳而得名。\n棣：唐棣，也叫郁李，果实色红，如梨。\n树：形容檖树直立的样子。檖（suí）：山梨。', poem_appreciation = '一个女子痴心地渴望着，等待着重新见到那位朝思暮想的“君子”，她望穿秋水，等得心碎神伤。其实那位“君子”，恐怕压根儿已将她忘个罄尽。这首诗的内容实有揶揄嘲弄这位“君子”“二三其德”的况味。\n\n　　全诗三章，章六句。首章用鹯鸟归林起兴，也兼有赋的成分。鸟倦飞而知返，还会回到自己的窝里，而人却忘了家，不想回来。这位女子望得情深意切。起首两句，从眼前景切入心中情，又是暮色苍茫的黄昏，仍瞅不到意中的“君子”，心底不免忧伤苦涩。再细细思量，越想越怕。她想：怎么办呵怎么办？那人怕已忘了我！不假雕琢，明白如话的质朴语言，表达出真挚感情，使人如闻其声，如窥其心，这是《诗经》语言艺术的一大特色。从“忘我实多”可以揣测他们间有过许许多多花间月下、山盟海誓的情事，忘得多也就负得深，这位“君子”实在是无情无义的负心汉。不过诗意表达得相当蕴藉。\n\n　　“山有……隰有……”是《诗经》常出现的起兴成句，用以比况物各得其宜。上古时代先民物质生活尚不丰富，四望多见山峦坑谷正是历史的必然。那颙望着的女子瞥见晨风鸟箭样掠过飞入北林后，余下所见就是山坡上有茂密栎树和洼地里有树皮青白相间的梓榆。三章则换了两种树：棣和檖。之所以换，其主要作用怕是在于换韵脚。万物各得其所，独有自己无所适从，那份惆怅和凄凉可想而知，心里自然不痛快。三章诗在表达“忧心”上是层层递进的。“钦钦”形容忧而不忘；“靡乐”，不再有往事和现实的欢乐；“如醉”，如痴如醉精神恍惚。再发展下去，也许就要精神崩溃了。全诗各章感情的递进轨迹相当清晰和真实可信。', poem_tags = '诗经,弃妇' WHERE poem_title = '国风·秦风·晨风' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '当初，张衡写作《定情赋》，蔡邕写作《静情赋》，他们摒弃华丽的辞藻、崇尚恬淡澹泊的心境，文章之初将（功名场里的）思虑发散开来，末了则归总到自制中正的心绪。这样来抑制流于歪邪或坠于低鄙的不正当的心念，想来也有助于讽喻时弊、劝谏君主。缀字成文的雅士们，代代承继（他们的传统）写作这种文赋并将之发扬，又（往往）从某些相似点推而之广言及其他，把原来的辞义推广到更开阔的境地。平日闲居里巷深园，多有闲暇，于是也重提笔墨，作此情赋；虽然文采可能不比前人精妙，大约也并不致歪曲作文章者的本意。\n　　（啊，）她的绰约风姿多么瑰丽飘逸，而与众不同、秀丽绝伦。她的美貌可谓倾城倾国、绝艳殊色，她的美德的传闻又令人心生向往。只有玎珰作响的玉佩才比得上她的纯洁，只有高洁的幽兰才能与她一较芬芳。（于是我）将一片柔情淡化在了俗世里，将高雅的情志寄于浮云。悲叹着（时光易逝）晨曦又到了迟暮，如何不让人深深感慨人生艰勤；同样将在百年后（逝去的那时）终止，为何人生中欢欣如此难得而愁绪却是时时不断！（那时她）撩起大红帏帐居中正坐，拨泛古琴而为之欣欣，纤长的手指在琴上拂出佳音，雪白的手腕上下作舞（使我）目为之迷。顾盼之际美目中秋波流动，时而微笑言语而不分散奏乐的心神。乐曲正奏到一半，红日缓缓向西厢那边沉。略作悲伤的商宫的乐声在林中久久回荡，山际云气缭绕白烟袅袅。（她）时而仰面望天，时而又低头催动手里的弦作急促的乐声，神情那么风采妩媚，举止又那么安详柔美。\n　　（她）奏出的清越乐声使我心动，渴望（与她）接膝而坐作倾心的交谈。想要亲自前往与她结下山盟海誓，却怕唐突失礼受之谴责，要倩青鸟使递送我的信辞，又怕被别人抢在前面。心下如此惶惑，一瞬间神魂已经不知转了多少回：愿化作她上衣的领襟呵，承受她姣美的面容上发出的香馨，可惜罗缎的襟衫到晚上便要从她身上脱去，（长夜黯暗中）只怨秋夜漫漫天光还未发白！愿化作她外衣上的衣带呵，束住她的纤细腰身，可叹天气冷热不同，（变化之际）又要脱去旧衣带而换上新的！愿化作她发上的油泽呵，滋润她乌黑的发鬓在削肩旁披散下来，可怜佳人每每沐浴，便要在沸水中经受苦煎！愿作她秀眉上的黛妆呵，随她远望近看而逸采张扬，可悲脂粉只有新描初画才好，卸妆之时便毁于乌有！愿作她卧榻上的蔺席呵，使她的柔弱躯体安弱于三秋时节，可恨（天一寒凉）便要用绣锦代替蔺席，一长年后才能再被取用！愿作丝线成为她（足上）的素履呵，随纤纤秀足四处遍行，可叹进退行止都有节度，（睡卧之时）时只能被弃置在床前！愿在白天成为她的影子呵，跟随她的身形到处游走，可怜到多荫的大树下（便消失不见），一时情境又自不同！愿在黑夜成为烛光呵，映照她的玉容在堂前梁下焕发光彩，可叹（平旦）日出大展天光，登时便要火灭烛熄隐藏光明！愿化为竹枝而作成她手中的扇子呵，在她的盈盈之握中扇出微微凉风，可是白露之后早晚幽凉（便用不到扇子），只能遥遥望佳人的襟袖（兴叹）！愿化身成为桐木呵，做成她膝上的抚琴，可叹一旦欢乐尽而哀愁生，终将把我推到一边而止了靡靡乐音！\n　　推详我的愿望都不能如意，徒然一厢情愿地用心良苦。为情所困的心情却无人倾诉，缓缓踱到南面的树林。在尚带露汁的木兰边略作栖息，在苍苍青松的遮蔽下感受凉荫。若是在这里（与心仪的人）对面相觑，惊喜与惶恐将如何在心中交集？而树林里空寞寂寥一无所见，只能独自郁闷地念想而空自追寻。回到原路上整理衣裾，抬头已见夕阳西下，不由发出一声叹息。一路走走停停流连忘返，林中景色凄凄惨惨。（身边）叶子不住离枝簌簌而下，林中气象凄凄戚戚。红日带着它的（最后一丝）影子没入了地平，明月已在云端作出另一幅美景。宿鸟凄声鸣叫着独自归来，求偶的兽只还没有回还。。在迟暮的年纪凭吊当年，深深慨叹眼前的（美好）光景顷刻就会终结。回想夜来梦中的情景想要再入梦境，又思绪万千不能定心，如同泛舟的人失落了船桨，又似登山者无处攀缘。。此刻，毕昂二宿的星光将轩内照得透亮，室外北风大作声音凄厉，神智愈加清醒再也不能入眠，所有的念想都在脑海里回旋。（于是）起身穿衣束带等待天明，屋前石阶上的重重冷霜晶莹泛光。（司晨的）鸡也还敛着双翅（栖息）而未曾打鸣，笛声清嘹忧郁的声音往远处荡扬：起初节奏细密而悠闲平和，最终寂寥清亮中又含了颓败的声音。 在这样的光景里思念佳人，请天上的行云来寄托我的心怀，行云很快流过不语，光阴也如此荏苒而过。徒然殷殷思念着独自体味悲心，终是山阻脚步河滞行。迎风而立，希望清风能扫去我的疲累，对泛来的阵阵轻波寄托我的微薄心愿——（期望与你）作《蔓草》那样的聚晤，吟诵从《诗经·召南》起未曾断绝的长歌余风。（而这终究是不能的）（还是）将万千杂虑坦然释怀，只存下本真的赤心，让心情在遥阔的八荒空遐外休憩流连。', poem_notes = '定情赋：东汉张衡的赋作，仅存《艺文类聚》十八，所录九句。\n静情赋：东汉蔡邕（yōng）的赋作，仅存残局，见《艺文类聚》。\n宕（dàng）：同“荡”。\n奕（yì）：重叠。奕代：累代。\n褰（qiān）：拉开。\n眄（miǎn）：顾盼。\n睇：凝视。\n愆（qiān）：过错。\n颓肩：颓，坠，水往下流。颓肩，削肩。古代女子双肩以削为荣。\n缅邈（miǎo）：遥远\n翳（yì）：遮蔽，障蔽。\n傥（tǎng）：倘，或许。觌（dí）：相见。\n燮（xiè）燮：落叶声。\n炯炯：本竖心旁，思索而不安的样子。\n粲（càn）：鲜明。\n憩（qì）：休息，此处意为休止。八遐（xiá）：遥远的八方。', poem_appreciation = '《闲情赋》的第一节极尽夸饰之能事描写美人之容貌与品行：“夫何飘逸之令姿，独旷世以秀群。表倾城之艳色，期有德于传闻。”容貌举世无双，德行也远近闻名，“佩鸣玉以比洁，齐幽兰以争芬。淡柔情于俗内，负雅志于高云。”既有冰清玉洁的气质，又有深谷兰花的芬芳，情怀超世出俗，志趣高尚入云。这与其说是写美人，不如说是在自我表白。这位美人就是作者理想的外化，是作者心志、情怀的投射与再造。屈原《离骚》中说：“纷吾既有此内美兮，又重之以修能。扈江离与辟芷兮，纫秋兰以为佩，” 显然是陶作的样板，只不过屈原是自赞自怜，而陶渊明含蓄地用自己的理想塑造出一位美人而已。“ 悲晨曦之易夕，感人生之长勤。同一尽于百年，何欢寡而愁殷！”美好时光易逝，人生旅途艰辛，百年之后都将同归尘土，何必郁郁于心！这是在劝慰美人，也是在劝慰自己。“褰朱帏而正坐，泛清瑟以自欣。送纤指之余好，攘皓神之缤纷。瞬美目以流眄，含言笑而不分。”进一步状写美人的情态。\n\n　　第二节写诗人对美人欲亲近又顾虑重重的复杂心情。“曲调将半，景落西轩。悲商叩林， 白云依山。仰睇天路，俯促鸣弦。神仪妩媚，举止详妍。”一系列四字句，短促顿挫，使我们仿佛看到一个平素持重淡泊的男子，此时面对仪态万方的绝代佳人，心脏在急剧跳动。“激清音以感余，愿接膝以交言。欲自往以结誓，慎冒礼为□。待凤鸟以致辞，恐他人之我先。意惶惑而靡宁，魂须臾而九迁。”有心无胆，犹豫彷徨，正是陶渊明性格的写照。心烦意乱不得安宁，魂不守舍，须臾之间几番往返，末二句极得恋爱中人心之真态，令人好笑又感动。\n\n　　第三节是全赋的高潮，一反作者朴素淡远的风格，炽热无比。“愿在衣而为领，承华首之余芳； 悲罗襟之霄离，怨秋夜之未央。愿在裳而为带，束窈窕之纤身；嗟温凉之异气，或脱故而服新。愿在发而为泽，刷云鬓于颓肩；悲佳人之屡沐，从白水以枯煎。愿在眉而为黛，随瞻视以闲扬；悲脂粉之尚鲜，或取毁于华妆。愿在莞而为席，安弱体于三秋；悲文茵之代御，方经年而见求。愿在丝而为履，附素足以周旋，悲行止之有节，空委弃于床前。愿在昼而为影，常依形而西东；悲高树之多荫，慨有时而不同。愿在夜而为烛，照玉容于两楹；悲扶桑之舒光，奄天景而藏明。愿在竹而为扇，含凄飙于柔握；悲白露之晨零，顾襟袖之缅邈。愿在木而为桐，作膝上之鸣琴；悲乐极以哀来，终推我而辍音。”\n\n　　十愿连翩，一气呵成，要化己身为美人衣之领，腰之带，发之膏泽，眉之黛墨，身下之席，脚上之鞋，随身之影，照颜之烛，手中之扇，膝上之琴，只为了亲近美人，陪伴美人。一连串拟物手法的运用，构思奇特，想象丰富。十种物事，寄托同一个美好心愿，十番转折，十种设想的结果，表达同一种担忧，尤为衬出心愿的强烈。\n\n　　空怀十愿，无以表白，作者情绪渐渐变得低沉。“考所愿而必违，徒契契以苦心。拥劳情而罔讷，步容与于南林。栖木兰之遗露，翳轻松之余阴。倘行行之有觌，交欣惧于中襟。竟寂寞而无见，独悄想以空寻！”抒情主人公过分消极，仅仅停留于心愿，不敢付诸行动，很有无故寻愁觅恨的味道。凭空设想出一个情人，本就只是为了抒发心中那份郁郁不得志的情绪，本就只是枉自嗟怨，不会有什么结果也不求有什么结果。\n\n　　第五节诗人由美人乏不可求回复到自己平生志愿之不得遂上来。“敛轻裾以复路，瞻夕阳而流叹； 步徒倚以忘趣，色惨凄而矜颜。叶燮燮以去条，气凄凄而就寒；日负影以偕没，月媚景于云端。鸟凄声以孤归，兽索偶而不还；悼当年之晚暮，恨兹岁之欲殚。思宵梦以从之，神飘瓢而不安；若凭舟之失悼，譬缘崖而无攀。”这里梦中情人已退居次席，作者开始比较直接地表现自己不知路在何方的迷惘，一事无成而时光易逝的惆怅。坐卧不安，神魂飘游，是为了那始终追求不到的梦中情人一般美好而又缥缈的理想。\n\n　　赋之末节，诗人经过一夜辗转苦思，终于在无计可施中放弃了追求，也平复了烦燥不安的情绪。“ 于是毕昴盈轩，北风凄凄。久久不寐，众念徘徊。”四字句的再次夹入，表明情感的再度转折。起摄带以伺晨，繁霜粲于素阶；鸡敛翅而未鸣，笛流运以清哀，始妙密以闲和，终寥亮而藏摧。意夫人之在兹，托行云以送怀；行云逝而无语，时奄冉而就过。徒勤思以自悲，终阻山而带河；迎清风以祛累，寄弱志于归波。尤《蔓草》之为会，诵《郡南》之馀歌；但万虑以存诚，憩遥情于八遐。”诗人极力使自己认为没有希望，万种相思只是徒然自寻烦恼，以让自己完全放弃努力也放弃心愿，让他胸中的郁闷与梦幻付诸清风流水。发乎情而止乎礼，浮想联翩的白日梦终究没有什么意义，诗人要摒除各种杂念，保持一片纯心。\n\n　　通观全赋，总体来讲作者的情调是低沉、消极的，即是“十愿”，也把那股火一般的情感深深压抑，以悲观的情绪来淡化。末几节更是将其消解至无，诗人之心仍然回复为一汪死水。\n\n　　这篇赋结构新颖，想象丰富，辞句清丽，灵活地运用了比兴手法，其中的十愿表现出极大的创造性，荡除了汉赋那种着意铺排、堆砌辞藻、典故、用语生涩的积弊，清新自然，因此被人们久诵不衰。', poem_tags = '写人,美人' WHERE poem_title = '闲情赋' AND poem_author = '陶渊明';
UPDATE edu_poem SET poem_translation = '花前没有了她的陪伴，独自在花间徘徊，看繁花似锦，芳草天涯，一株株、一簇簇，都有他寻找的往昔旧梦，触目悲凉。虽是春光美景，却是欢乐难再，既使笙歌入耳，婉转悠扬，也只能唤起他对爱侣的追忆，从而更添感伤惆怅。\n转眼望去，林间彩蝶对对，帘间飞燕双双，皆在快乐嘻逐，恩爱相偕。不思量、难思量，抬头望天边，还是夕阳西沉、残阳如血。血色勾勒了天边的绿树，涂抹了林中的青苔，也笼罩了他的心，明丽而惨烈。', poem_notes = '纵有：纵使有。\n笙歌：笙代指各种乐器；笙歌即指各种乐器演奏声和歌声。\n忍：作“怎忍”解。', poem_tags = '婉约,孤独,思念' WHERE poem_title = '采桑子·花前失却游春侣' AND poem_author = '冯延巳';
UPDATE edu_poem SET poem_translation = '只知道寻觅胜景而忘了天寒，偶立在春风中夕阳晚照之间。\n我最喜欢那东山晴后的雪景，软红的光芒里涌来座座银山。\n\n东山的积雪留不到天放新晴，多成了湿润的泥土少许成冰。\n我最喜欢那东山晴后的雪景，发愁适合观赏而不适合攀登。', poem_notes = '东山：指作者家乡的山。\n逐胜：寻觅胜景。\n银山：形容雪后东山如银山。\n群山：指东山。新晴：刚放晴的天气。\n泥融：湿润的泥土。', poem_appreciation = '这组诗的题目直接言明“最爱”，表达情感取向。第一首诗描写了东山雪后阳光朗照的美丽景象。这首诗作于早春，天气乍暖还寒时候。东风轻拂，万物开始复苏，四山开始挣脱冬日的枯黄，泛出片片青绿。诗人整日都在追逐那一片片青绿，早已忘记了早春还有丝丝寒意。在春风夕照间停留，环顾群山，原来此刻最美的是东山上那一片雪。\n\n　　第一句“只知逐胜忽忘寒”，写自己因为只顾着追逐寻觅胜景而忘记了寒冷，第二句“小立春风夕照间”写偶尔在春风中站立，在夕阳中放眼赏看美景。这两句写诗人不惧寒冷，寻觅美景，立于风中，在夕阳中欣赏美景的形象，把一个因爱美景而不顾寒冷的“痴人”形象展现出来。\n\n　　第三句“最爱东山晴后雪”直言自己最喜爱东山天晴之后的雪景，而第四句“软红光里涌银山”则为全诗最妙的景语。其中“软”字写出白雪映照下的夕阳红光，是那么的柔和细微，赋予夕阳光芒以形象的触觉，写出了夕阳的无限美好。另一个“涌”字则把白雪覆盖的群山在夕阳之下闪耀光芒，在视觉上产生向自己涌动而来的动态感描绘出来，有化静为动的奇功。\n\n　　第二首诗描写了阳光照耀下东山积雪消融的景象。随着时间推移，东山上的雪渐渐消融，多是变成了湿润的泥土而少许成冰，而这时还没到新晴之时。这就是前两句所写，不仅很好承接上一首点出雪后消融的景象，而且为下面“宜看不宜登”讲明原因。\n\n　　值得注意的是第三句，这句“最爱东山晴后雪”在前首同样的位置就出现了，而再写一次就进一步表现了对东山之雪的喜爱，这样的情感是非常有力的。但略不同于前首，这句话的是带有些许愁意的。第四句直接点出了愁，作者所愁的是“宜看不宜登”，可以远观而不可登攀近赏，对于作者来说却是十分失望的，而且其中又隐含着对白雪消融掉的可惜。', poem_tags = '写雪,写景,喜爱' WHERE poem_title = '雪后晚晴四山皆青惟东山全白赋最爱东山晴后雪二绝句' AND poem_author = '杨万里';
UPDATE edu_poem SET poem_translation = '明妃当时初起程出行离别汉宫时，泪湿桃花春风面鬓脚微微亦低垂。\n低头回看身影间周围无有此颜色，还让我君王的感情都难以控制。\n离别归来却怪罪丹青画图手，美貌如此在眼中平生实未曾见有。\n天仙意态由自生画笔难以描摹成，当时冤枉杀死画工毛延寿。\n从此一离去心知更不能回归，可怜还不能穿尽汉朝皇城之宫衣。\n万里寄语欲相问塞南遥远家乡事，只有年年日日里眼望鸿雁往南飞。\n家人虽然在万里传来亲人之消息，好好安心在毡城不要常将家相忆。\n您还不曾见近在咫尺长门里幽幽阿娇被锁闭，人生如果要失意无分天南和地北。\n\n明妃当初嫁给胡人的时候，身旁上百两的毡车上乘坐的都是胡人女子。\n她多想找个人说话但无处可说，只能把心语寄托于琵琶声中，心事只有自己知道。\n她用能弹出美妙声音的手拨动黄金做的杆拨，弹起琵琶仰望空中飞鸿劝着胡酒。\n随嫁的汉宫侍女暗中垂泪，行走在大漠上的返国者频频回首。\n汉朝之恩实在是浅薄啊，胡人之恩还要更深，人生的欢乐在于心与心相知。\n可怜王昭君的青冢已经荒芜埋没，还是有悲哀的乐曲流传至今。', poem_notes = '明妃：即王昭君，汉元帝宫女，容貌美丽，品行正直。晋人避司马昭讳，改昭为明，后人沿用。\n春风；比喻面容之美。杜甫《咏怀古迹五首》中咏昭君一首有“画图省识春风面”之句。这里的春风即春风面的省称。\n低徊：徘徊不前。\n不自持：不能控制自己的感情。\n归来：回过来。丹青手：指画师毛延寿。\n意态：风神。\n着尽汉宫衣：指昭君仍全身穿着汉服。\n塞南：指汉王朝。\n毡城：此指匈奴王宫。游牧民族以毡为帐篷（现名蒙古包）。\n咫尺：极言其近。长门闭阿娇：西汉武帝曾将陈皇后幽禁长门宫。长门：汉宫名。阿娇：陈皇后小名字。\n“毡车”句：写匈奴派了大队胡姬来接昭君。《诗经·召南·鹊巢》：“之子于归，百两御之。”写贵族女子出 嫁，陪从很多。两：同辆。\n杆拨：弹琵琶的工具。春风手：形容手能弹出美妙的声音。\n汉宫侍女：指陪昭君远嫁的汉官女。\n青冢：杜甫诗中有“独留青冢向黄昏”及“千载琵琶作胡语，分明怨恨曲中论”诸句，此用其意。相传昭君墓上的草常青，故名青冢，在今呼和浩特市南。', poem_appreciation = '说来有趣，昭君出塞，是喜剧还是悲剧，历来就有两种不同的看法，唱对台戏的不仅杜甫和王安石而已。\n\n　　昭君墓周围有很多诗碣，其中一首诗碣刻的诗是：闺阁堪垂世，明妃冠汉宫。一身归朔汉，万里靖兵戎。若以功名论，几与卫霍同。人皆悲远嫁，我独羡遭逢。纵使承恩宠，焉能保始终。至今青冢在，绝域赋秋风。“卫霍”即汉朝的名将卫青和霍去病，诗人把王昭君与“卫霍”相提并论，对她可说是高度赞扬了。不过诗中虽没明言，但显而易见，诗人笔下的王昭君是抱着“自我牺牲”的精神和番的。是则在昭君的“得意”（诗人“我独羡遭逢”的“得意”）中也还有怨在。\n\n　　近人郁达夫也有一首咏王昭君的诗，命意和此诗相类。郁诗道：马上琵琶出塞吟，和戎端的爱君深。当年若贿毛延寿，哪得诗人说到今。\n\n　　写王昭君是抱着“爱君”（汉元帝）之心，为保主上江山而去“和戎”。就命意和技巧来说，这首诗都不能算是佳作。不过这是郁达夫的“少作”，他写这首诗时，只有18岁。\n\n　　王安石《明妃曲》在艺术上颇堪注意之处，是对王昭君形象的刻画。第一部分中描绘王昭君的美貌，不在其面容、体态上穷尽笔力，而是着重写昭君的风度、情态之美，以及这种美得感染力，并从中宣泄她内心悲苦之情。这样就写出了呼吸可闻、音容毕现的活生生古代美女形象。第二部分，着重写王昭君的内心情感。前人于此，往往以抒写昭君的哀情、怨情和渲染悲剧气氛为重点，而此诗除描写其身世可悲之外，还揭示出她对故国、亲人的挚爱之情，与推己及人的善良心肠。这样的王昭君，就不惟可悲，而且可敬。', poem_tags = '咏史怀古,怀才不遇,组诗' WHERE poem_title = '明妃曲二首' AND poem_author = '王安石';
UPDATE edu_poem SET poem_tags = '励志' WHERE poem_title = '贺新郎·寄辛幼安和见怀韵' AND poem_author = '陈亮';
UPDATE edu_poem SET poem_translation = '我好像那荒野里孤生的野竹，希望能在大山谷里找到依靠的伴侣。\n你我相亲新婚时你远赴他乡，犹如兔丝附女萝我仍孤独而无依靠。\n兔丝有繁盛也有枯萎的时候，夫妻也应该会要有俩相厮守的时宜。\n我远离家乡千里来与你结婚，正是新婚恩爱时你却离我远赴他乡。\n相思苦岁月摧人老青春有限，多麼的盼望夫君功成名就早日归来。\n我自喻是朴素纯情的蕙兰花，正是含苞待放楚楚怜人盼君早采撷。\n怕过了时节你还不归来采撷，那秋雨飒风中将随著秋草般的凋谢。\n你信守高节而爱情坚贞不渝，那我就只有守著相思苦苦的等著你。', poem_notes = '冉冉：柔弱下垂貌。孤生竹：犹言野生竹。孤，独。\n泰山：即“太山”，犹言“大山”“高山”。阿（ē）：山坳。\n为新婚：刚出嫁婚娶。\n兔丝：一作“菟丝”，一种旋花科的蔓生植物，女子自比。女萝：一说即“松萝”，一种缘松而生的蔓生植物，以比男子。\n生有时：草木有繁盛即有枯萎，以喻人生有少壮即有衰老。\n宜：犹言适当的时间。\n悠悠：遥远貌。山陂：泛指山和水。吕向注：“陂，水也。”\n轩车：有篷的车。这里指迎娶的车。\n蕙兰花：女子自比。蕙、兰是两种同类香草。\n含英：指花朵初开而未尽发。含，没有完全发舒。英，花瓣。扬光辉：形容容光焕发。\n萎：枯萎，凋谢。\n亮：同“谅”，料想。执高节：即守节情不移的意思。\n贱妾：女子自称。', poem_appreciation = '“冉冉孤生竹，结根泰山阿。”竹而曰“孤生”以喻其孑孑孤立而无依靠，“冉冉”是女子自寓柔弱。竹结根之处是大山，又在山阿之处，可以避风，这是以山比喻男方。《文选》李善注曰：“结根于山阿，喻妇人托身于君子也。”\n\n　　“与君为新婚，兔丝附女萝。”兔丝（菟丝）和女萝是两种蔓生植物，其茎蔓互相牵缠，比喻两个生命的结合。《文选》五臣注：“菟丝女萝并草，有蔓而密，言结婚情如此。”从下文看来，菟丝是女子的自喻，女萝是比喻男方。“为新婚”不一定是已经结了婚。清方廷珪《文选集成》说，此是“媒妁成言之始”而“非嫁时”。“为新婚”可能是指已经订了婚，但还没有迎娶。\n\n　　“兔丝生有时，夫妇会有宜。”这还是以“兔丝（菟丝）”自喻，既然菟丝之生有一定的时间，则夫妇之会亦当及时。言外之意是说既然订婚，就及时结合，不要错过了自己的青春时光。从女子的心境，可以感受到诗人珍惜时光的思想，珍惜美好人生的情感的态度。\n\n　　“千里远结婚，悠悠隔山陂。”从这两句看来，男方所在甚远，他们的结婚或非易事。这女子曾企盼着，不知何时他的车子才能到来，所以接下来说：“思君令人老，轩车来何迟！”这首诗开头的六句都是比，这四句改用赋，意尽旨远，比以上六句更见性情。\n\n　　“伤彼蕙兰花，含英扬光辉。过时而不采，将随秋草萎。”这四句又用比。女子以蕙和兰两种香草自喻，把现时的自已比作为娇艳的含苞待放的花朵，如果不及时采摘就会错过时候，娇艳美丽的蕙兰花就将像秋草一样枯黄凋萎。这是希望男方趁早来迎娶，不要错过了时光。唐杜秋娘《金缕衣》：“花开堪折直须折，莫待无花空折枝。”与此两句意思相近。\n\n　　最后二句“君亮执高节，贱妾亦何为？”这女子的疑虑已抒写毕尽，最后遂改为自我安慰。她相信男方谅必坚持高尚的节操，一定会来的，那么自己则不必怨伤。\n\n　　在艺术上，这首诗歌主要表现在这几方面：首先，运用比喻，形象生动；其次，心理描写，情感丰富；再次，层次清楚，结构严谨；第四，结尾反问，增强效果。', poem_tags = '古诗十九首,女子,相思,孤独' WHERE poem_title = '冉冉孤生竹' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '每次阅读那些有才气作家的作品，对他们创作时所有的心思自己都有体会。诚然，作家行文变化无穷，但文章的美丑，好坏还是可以分辨并加以评论的。每当自己写作时，尤其能体会到别人写作的甘苦。作者经常感到苦恼的是，意念有能下确反映事物，语言不能完全表达思想。大概这个问题，不是难以认识，而是难以解决。因此作《文赋》借评前人的优秀作品，阐述作样写有利，作样写有害的道理。或许可以说，前人的优秀之作，已把为文的奥妙委婉曲折也体现了出来。至于前人的写作决窍，则如同比着斧子做斧柄，虽然样式就在眼前，但那介心应手的熟练技巧，却难以用语言表达详尽，大凡能用语言说明的我都在这篇《文赋》里了。\n\n　　久立天地之间，深入观察万物；博览三坟五典，以此陶冶性灵。随四季变化感叹光阴易逝，目睹万物盛衰引起思绪纷纷。临肃秋因草木凋零而伤悲，处芳春由杨柳依依而欢欣。心意肃然台胸怀霜雪，情志高远似上青云。歌颂前贤的丰功伟业，赞咏古圣的嘉行。漫步书林欣赏文质并茂的佳作，慨然有感有感投书提笔写成诗文。\n\n　　开始创作，精心构思。潜心思索，旁搜博寻。神飞八极之外，心游万刃高空。文思到来，如日初升，开始朦胧，逐渐鲜明。此时物象，清晰互涌。子史精华，奔注如倾。六艺辞采，荟萃笔锋。驰骋想象，上下翻腾。忽而漂浮天池之上，忽而潜入地泉之中。有是吐辞艰涩，如衔钩之鱼从渊钓出；有时出语轻快，似中箭之鸟坠于高空。博取百代未述之意，广采千载不用之辞。前人已用辞意，如早晨绽开的花朵谢而去之；前人未用辞意，象傍晚含苞的蓓蕾启而开之。整个构思过程，想象贯穿始终。片刻之间通观古今，眨眼之时天下巡行。\n\n　　完成构思，布局谋篇。选辞精当，事理井然，有形之物尽绘其形，含声之物尽现其者。葳者层层阐述，由隐至显或者步步深入，从易 到难，有时纲举目张，如猛虎在山百兽驯伏，有时偶遇奇句，似蛟龙出水海鸟惊散。有时信手拈来辞意贴切，有时煞费苦心辞意不合，这时要排除杂念专心思考，整理思诉诸语言，将天地概括为形象，把万物融会于笔端，开始好象话在干唇难以出口，最后酣畅淋漓泻于文翰。事理如树木的主体，要突出使之成为骨干，文辞象树木析枝条，干壮才能叶茂校繁。情貌的确非常一致，情绪变化貌有表现。内心喜悦面露笑容，说到感伤不禁长。有时提笔一挥而就，有时握笔心理感到茫然。写作充满着乐取，一向为圣贤们推尊。它在虚无中搜求形象，在无声中寻找声音。有限篇幅容纳无限事理，宏大思想出自小小寸心。言中之意愈扩愈广，所含内容越挖越深像花朵芳香四溢，象柳条郁郁成荫。光灿灿如旋风拔地而起，沉甸甸如积支笔下生文。\n\n　　文章体式千差万别，客观事物多种多样，事物繁多变化无穷，圆满此很难描摹形象。辞采如同争献技艺的能互，文意好比掌握蓝图的巧匠，文辞当不当用他要仔细斟酌文章或深或浅他都分豪不让。即或违反写作常规，也要极力描绘形象。因此喜欢渲染的人，崇沿华丽词藻；乐于达理的人，重视语言精当。言辞过于简约，文章格局不大论述充分畅达，文章气势旷放。诗用以抒发感情，要辞采华美感情细腻，赋用以铺陈事物。要条理清晰，语言清朗碑用以刻记功德，务必文质相当，诔用以哀悼死者，情调应该缠绵凄怆。铭用以记载功劳，要言简意深，温和顺畅。箴用以讽谏得失，抑杨顿挫，文理清壮。颂用以歌功倾德，从容舒缓，繁采华彰，论用以评述是非功过，精辟缜密，语言流畅。奏对上陈叙事，平和透彻，得体适当。说明以论辨说理，奇诡诱人，辞彩有光，文体区分大致如此，共同要求禁止邪放。辞义畅达说理全面，但要切记不能冗长。\n\n　　客观事物千姿百态，文章体式也常变迁。为文立意崇尚冷气巧，运用文辞贵在华妍、音调高低错落有致，好象五色配合鲜艳。虽说取舍本无定律，文辞安排很难合适；但要通晓变化的规律、次序，就象开泉纳流吻自然。假如错过变化时机再去凑合，犹如以尾续首，颠倒混乱。如果颜色配搭不当，就会混浊不清色泽有艳。\n\n　　有时下文对上文有损害，有时上文对下文影响。有时语言不顺而事理连贯，有时语言连贯而事有妨。把它分开两全齐美，合在一起互相损伤。所用辞意严格考较，去留取舍他细衡量。如用法度加以权衡，丝毫不差合乎词章。\n\n　　有时辞藻繁多义理丰富，欲达之意却不清楚。文章主题只有一个，意思说尽不再赘述。关键地方简要几句，突出中心这是警语。尽管讲得条条有理，借助警句才更有力。文章果能利多弊少，就该满足不再改易。\n\n　　有时组织词义如编彩绘，严密漂亮光泽鲜艳。辞采富丽象斑烂锦秀，情调凄婉如乐器和弦。果真自己没有独创，恐怕就要雷同前贤。虽出自个人锦心绣口，也怕别人用于我先。假如确能有伤品誉，虽然心爱一定削删。\n\n　　有时个别句子出类拨萃，象芦苇开花禾苗秀稳。如声不可拴，影不可追，佳句孤零零超然独立，绝非庸言能够相配。心茫然很难再寻佳句，犹豫徘徊又不忍将客观存它舍弃。文有奇就象石中藏玉使山岭坐辉，又象水中含珠令河川秀媚。未经整枝的灌木踢然不美，招来翠鸟也会为它增加。\n\n　　文章作用很大，许多道理借它传扬。道传万里畅通无阻，勾通亿载它是桥梁。往能挽救文武之道使之不至衰落，它能宏扬教化使其免于泯灭。人生道路多么广远它都能指明，世间哲理多么精微客观存在都能囊括。它的作用同雨露滋润万物本比，它的手法幽微简直与鬼神相似。文章刻于金石美德传遍天下，文章播于管弦更能日新月异。▲', poem_appreciation = '《文赋》是中国最早系统地探讨文学创作问题的论著。全文以赋的形式写成。作者是西晋著名文学家陆机。\n\n　　陆机在《文赋》中用他的文学实践的亲身体会，生动地描述和分析了创作的心理特征和过程，表达了他的美学美育思想。主要包括：\n\n　　（1）“情因物感，文以情生”。《文赋》认为，情感是文学创作冲动的来由和起点。在艺术想象过程中，许多心理活动交织在一起，情、理、物象，文辞纷至沓来，所要创造的艺术形象也愈加清晰鲜明。在这过程中，作者的情感起着重要的作用，正所谓“思涉乐其必笑，方言哀而已叹”。\n\n　　（2）“笼天地于形内，挫万物于笔端”。《文赋》充分肯定了艺术想象的作用，认为在构思阶段，则“收视反听，耽思傍讯，情骛八极，公游成仞”，“观古今于须臾，扶四海于一瞬”，“笼天地于形内，挫万物于笔端”表明作者在创作过程中完全沉入艺术想象过程中。\n\n　　（3）“应感之会，通塞之纪”。《文赋》强调灵感在文学创作中的作用，指出艺术创作成就的取得同“应感之会，通塞之纪。即灵感问题有密切关系。认为灵感具有“来不可遏，去不可止”，“或竭情而多悔，或率意而寡尤”的特征。\n\n　　（4）“其会意也尚巧，其遣言也贵妍”。《文赋》在艺术风格上，崇尚华丽之美，强调“丽辞”。这反映了六朝时期讲求形式美的新时尚。\n\n　　（5）《文赋》将文体区分为十种，简明概述了各体的特征。可以说，《文赋》在一定程度上概括了整个艺术创作思维的规律。\n\n　　《文赋》是我国古代研究文学创作特点的最早的一篇专论，在美学史上有重要的意义和价值。' WHERE poem_title = '文赋' AND poem_author = '陆机';
UPDATE edu_poem SET poem_translation = '肩吾有个天真可爱的小女儿，在诗中不止一次提到，如：“姊妹无多兄弟少，举家钟爱年最小。有时绕树山雀飞，贪看不待画眉了。”（《效古词》）而这首《幼女词》更是含蓄兼风趣的妙品。\n\n　　诗一开始就着力写幼女之“幼”，先就年龄说，“才六岁”，说“才”不说“已”，意谓还小着呢。再就智力说，尚“未知巧与拙”。这话除表明“幼”外，更有多重意味。表面是说她分不清什么是“巧”、什么是“拙”这类较为抽象的概念；其实，也意味着因幼稚不免常常弄“巧”成“拙”，比方说，会干出“浓朱衍丹唇，黄吻烂漫赤”（左思），“移时施朱铅，狼藉画眉阔”（杜甫）一类令人哭笑不得的事。此外，这里提“巧拙”实偏义于“', poem_appreciation = '施肩吾有个天真可爱的小女儿，在诗中不止一次提到，如：“姊妹无多兄弟少，举家钟爱年最小。有时绕树山雀飞，贪看不待画眉了。”（《效古词》）而这首《幼女词》更是含蓄兼风趣的妙品。\n\n　　诗一开始就着力写幼女之“幼”，先就年龄说，“才六岁”，说“才”不说“已”，意谓还小着呢。再就智力说，尚“未知巧与拙”。这话除表明“幼”外，更有多重意味。表面是说她分不清什么是“巧”、什么是“拙”这类较为抽象的概念；其实，也意味着因幼稚不免常常弄“巧”成“拙”，比方说，会干出“浓朱衍丹唇，黄吻烂漫赤”（左思），“移时施朱铅，狼藉画眉阔”（杜甫）一类令人哭笑不得的事。此外，这里提“巧拙”实偏义于“巧”，暗关末句“拜新月”事。读者一当把二者联系起来，就意会这是在七夕，如同目睹如此动人的“乞巧”场面：“七夕今宵看碧霄，牵牛织女渡河桥。家家乞巧望秋月，穿尽红丝几万条。”（林杰《乞巧》）诗中并没有对人物往事及活动场景作任何叙写，由于巧下一字，就令人想象无穷，收到含蓄之效。\n\n　　前两句刻划女孩的幼稚之后，末二句就集中于一件情事。时间是七夕，因前面已由“巧”字作了暗示，三句只简作一“夜”字。地点是“堂前”，这是能见“新月”的地方。小女孩干什么呢？她既未和别的孩子一样去寻找萤火，也不向大人索瓜果，却郑重其事地在堂前学着大人“拜新月”呢。读到这里，令人忍俊不禁。“开帘见新月，即便下阶拜”的少女拜月，意在乞巧，而这位“才六岁”的乳臭未干的小女孩拜月，是“不知巧”而乞之，“与‘细语人不闻’（李端《拜新月》）情事各别”（沈德潜语）啊。尽管作者叙述的语气客观，但“学人”二字传达的语义却是揶揄的。小女孩拜月，形式是成年的，内容却是幼稚的，这形成一个冲突，幽默滑稽之感即由此产生。小女孩越是弄“巧”学人，便越发不能藏“拙”。这个“小大人”的形象既逗人而有趣，又纯真而可爱。\n\n　　这类以歌颂童真为主题的作品，可以追溯到晋左思《娇女诗》，那首五古用铺张的笔墨描写了两个小女孩种种天真情事，颇能穷形尽态。而五绝容不得铺叙。如果把左诗比作画中工笔，则此诗就是画中写意，它删繁就简，削多成一，集中笔墨，只就一件情事写来，以概见幼女的全部天真，甚而勾画出了一幅笔致幽默、妙趣横生的风俗小品画，显示出作者白描手段的高超。', poem_tags = '儿童' WHERE poem_title = '幼女词' AND poem_author = '施肩吾';
UPDATE edu_poem SET poem_translation = '九日在龙山宴饮，黄色的菊花盛开似在嘲弄我这个逐臣。\n醉眼看看秋风把我的帽子吹落，月下醉舞，明月留人。', poem_notes = '龙山：在当涂县南十里，蜿蜒如龙，蟠溪而卧，故名。见《太平府志》。\n黄花：谓菊花。菊花有多种颜色，古人以黄菊为正色，故常以黄花代称。\n逐臣：被贬斥、被驱逐的臣子，诗人自称。\n风落帽：用晋孟嘉九日登高落帽事。详见《九日登山》诗注。东晋大司马桓温曾在重阳节登龙山，其部下参军孟嘉被风吹落帽，孟嘉仍浑然不觉，桓温命人作文嘲之，孟嘉作答，挥笔而就，一时传为佳话。', poem_appreciation = '在咏菊诗中，“龙山之会”、“落帽人”是常被引用的典故。李白把这个典故与自己的龙山之游紧密结合在一起抒发了内心的失意愤懑、旷达洒脱的复杂感情。\n\n　　在重阳节之际，诗人登上了当涂附近的名胜之地龙山，与好友痛饮菊花酒，借吟诗来倾泻胸中之情。首句点明时间地点，既写诗人的宴饮，也扣晋桓温同宾僚的宴饮，这样写就使以后的用典不仅自然吻合，且合情合理，亦即顺理成章。次句“黄花笑逐臣”，着重写宴饮时菊花的神态。“笑”，十分生动、形象地写出了菊花盛开时的美艳的容颜。“逐臣”，追随诗人。这是说菊花开得到处都是，无论诗人到了哪里，都能看到喷吐异香的黄花，同样，诗人无论到了哪里，都有朵朵怒绽的黄花向他微笑。在登龙山之际，联想起这里曾经上演过的名士清流之事，以“逐臣”自比的李白，暂时忘却了政治上的不得意，把自己比作被风吹落帽的名士孟嘉，表达了对名士的向往和对自然的热爱。三、四句“醉看风落帽，舞爱月留人。”前一句用典，重在“醉”字，后一句写实，重在“舞”字。饮美酒赏黄花，酒不醉人人自醉，花不能舞人自舞，体现出饮酒赏花的乐趣，表现出诗人放旷的性格、浪漫的气质。“陶然共忘机”，正是此情此景的真实描绘。可见，后两句诗是前两句诗的深化。诗的最后一句“舞爱月留人”，巧妙地将月亮拟人化，以“月留人”收尾，显得生动别致，表面上是说月亮挽留诗人，而实际上是诗人留恋这脱俗忘尘的自然之境，不愿割舍而去。\n\n　　孟嘉九日龙山落帽事，是魏晋名士飘逸风度的典型体现，历来文人多爱诵之。李白在这里以孟嘉自比，临风醉酒落帽，对月起舞弄影，自有一分超放的情味。但“逐臣”一语，也透出了他胸中的牢落不平，这就使本诗不仅仅是一篇吟赏前辈风流之作，同时也有其现实遭际的感慨在。', poem_tags = '重阳节,饮酒,抒情,典故' WHERE poem_title = '九日龙山饮' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '春风多么会忙忙碌碌啊！它同花儿生活在一起，能使花儿开放；同柳树在一起，就使柳树早早发青。\n春风又同燕子一起衔泥作窝，还催开百花帮助蜜蜂晴酿蜜；刚刚吹来阴云下了一阵小雨，又将乌云送走，带来了蓝蓝的晴天。', poem_notes = '多可：多么能够的意思。\n忙生：忙的样子。', poem_tags = '春天,赞颂,写风' WHERE poem_title = '春思' AND poem_author = '方岳';
UPDATE edu_poem SET poem_translation = '赏析 　　这首诗举例了读书的益处与不读书的坏处，忠告人们要热爱读书，读书要持之以恒，并将其道理表达得淋漓尽致。', poem_tags = '规劝,读书,哲理' WHERE poem_title = '读书有所见作' AND poem_author = '萧抡谓';
UPDATE edu_poem SET poem_translation = '折下美丽的花枝，不觉又怨恨起花技，原来打算花开时我们一起赏花共饮，谁知花开后情人一去不返不见踪影。\n害怕相思折磨自己，相思之情却早愁人，到相思时却事无办法摆脱它，心中稍稍平静眉头又露几分。', poem_notes = '选自《明词综》。长相思 ： 词牌名。原为唐教坊曲。后用为词调之称。又名《忆多娇》、《双红豆》、，《相思令》、《长相思令》、《长思仙》、《山渐青》、《吴山青》、“青山相送迎》、《越山青》等。仄韵调名为《叶落秋窗》。双调，每段四句，押四平韵，三十六字。\n准拟：打算，约定。\n人共卮（zhi支）：指饮酒定婚。卮，古代盛酒器。\n辞：躲避。\n丝：丝与“思”谐音，以双关语既形眉态，又表心绪。', poem_appreciation = '这首词笔法简洁细腻，以女子的口吻，写主人公与情人分别后的相思之情，情极深挚，非至情者莫能道出。写法上，运用复杂而微妙的感情交织，在对花的爱与恨以及对于相思的怕而又不得不相思的矛盾交织中，体现其对爱情的忠贞和对幸福的向往。该词化用了范仲淹《御街行》的“都来此事，眉间心上，无计相回避”及李清照《一剪梅》的“才下眉头，却上心头”。\n\n　　上片从“花”字生发，鲜花象征着美好的事物，代表着纯真的爱情，并常常被用来比喻美丽的女子。“折花枝”尽管只是写了女主人公的一个动作，但也自然会使人联想到青春少女美丽的面庞及折花枝时的优美姿态，联想起“人面桃花相映红”（唐崔护《题都城南庄》）的艺术境界。“恨花枝”三字接得突兀，词人着一“恨”字，准确地刻划了折花人心灵深处的悲苦，这首词即以盈盈春色反衬人的失意。“准拟花开入共卮，开时人去时”，令人仿佛看到折花人流下相思泪，含情凝睇着伊入离去的方向。女主人公本来打算同恋人在花开时节共同饮酒赏花，可是花开之日却是人去之时，离愁既生，迁恨于花枝也是必然的。其实“花枝”并没有什么过错，“恨花枝”，说到底就是恨自己的恋人，本来说好的事情，为何能轻易违约匆匆离去。不过，这“恨”中也包含着爱的成份。\n\n　　下片紧承上片意脉，娓娓道来，生动地写出自己的刻骨相思。这“相思”二字所包容的巨大能量，曾使古今中外的多少有情男女愁苦不已，损心伤神。回想昔日花好月圆共饮时，湖边柳下细和语，卿卿我我蜜意时，女子惧怕孤独、不甘寂寞， “怕相思，已相思”将女主人公怨恨、思念、爱怜的感情，细腻、逼真地表达出来，直抒胸臆。但“怕”又有何用，谁能摆脱这“剪不断，理还乱”的忧愁。但当心里有了“相思”的想法时，就已经在相思了。“怕”和“恨”连起来，正是白居易所描绘的“思悠悠，恨悠悠，恨到归时方始休”的同义语。对一位感情丰富，情窦已开的女子来说，“恨”是“爱”的折光·，“怕”是“恋”的延伸，相思之苦，难遣胸怀。“轮到”，表明主人公过去还未曾品尝过相思之苦，正因为是初尝，才更能体会到相思是那样的折磨人，纠缠人，让人没法回避，无法推辞。心中所思，形诸面容，“眉间”自然会“露一丝”，这“一丝”凝聚着主人公对恋人的无限深情与怀念，其中有恨，有爱，有失望，有希望，有痛苦，有幸福，个中滋味难以表达。以“丝”谐“思”，采用民歌抒情惯用手法，清新含蓄，娇态可怜。\n\n　　该词上片写实记事，下片抒情展怀。上下片虚实结合，相映相衬，情味浓郁，完美地塑造了一位多情女的形象。上下片打头的两个三字句，有很别致的形式：第二，三两字相互重复，句首第一字相互对照。例如白居易的“汴水流，泗水流——思悠悠，恨悠悠”，林逋的“吴山青，越山青——君泪盈，妾泪盈”，俞彦这首词颇具匠心地借助了这种形式上的奇突。“折花枝，恨花枝”和“怕相思，已相思”，前者是心理与行为，后者是心理与情势的比照和冲突，两者都不着痕迹地投射出词的主旋律——情绪上的双重体验（眷恋与痛苦），由此超越了语言结构的外壳，成为构成作品内在完整的有机因素。', poem_tags = '婉约,相思' WHERE poem_title = '长相思·折花枝' AND poem_author = '俞彦';
UPDATE edu_poem SET poem_translation = '注释 即事：对眼前事务，情景有所感触而创作。 闾（lǘ ），古代二十五家为一闾。 原指里巷的大门，后指人聚居处：倚闾而望。闾里。闾巷。闾左（秦代居于里门之左的贫苦百姓）。 汇聚：尾闾（水闾汇聚之处，泄水的处所）。 门闾1.城门与里门。2.宫门。3.指乡里、里巷。4.家门;家庭;门庭。 大概意思：站在门口对眼前事务，情景有感触而作的诗。', poem_tags = '清明节,感伤' WHERE poem_title = '闾门即事' AND poem_author = '张继';
UPDATE edu_poem SET poem_translation = '宽阔的黄河，只有不多几条船在航行，眼前是波浪滚滚，一派渺茫。我独自登上河边的亭子，斜靠着栏杆，愁绪像河水，源源不断。\n那河边、远处，萧瑟秋风中，有片稀疏的树林，林后是耸立的高山，一半沐浴着西斜的阳光。', poem_notes = '这是四首（春、夏、秋、冬）组诗中的第三首。诗前有序，说明此诗是作者被贬谪时写的。\n河，黄河。\n凭，靠。危，高。\n萧萧，风声。\n危槛：高高的栏杆。', poem_tags = '古诗三百首,写景,黄河,抒情' WHERE poem_title = '书河上亭壁' AND poem_author = '寇准';
UPDATE edu_poem SET poem_tags = '婉约,春天,咏物,伤春,思归' WHERE poem_title = '苏幕遮·草' AND poem_author = '梅尧臣';
UPDATE edu_poem SET poem_translation = '长恨啊！实在更长恨！我把它剪裁成《短歌行》。及时唱歌行乐吧！什么人了解我，来为我跳楚舞？听我唱楚狂人接舆的《凤兮》歌？我在带湖既种了九畹的兰花，又栽了百亩的蕙，到了秋天可以吃菊花的落花。在我的门外有沧浪的清水可以洗我的丝带。\n　　请问：一杯酒与身后名誉，哪一件重要？身后名当然重要。但是，现今是人间万事都是本末倒置，毫发常常是重的，而泰山却倒很轻。最悲伤也没有比生离死别更悲伤的，最欢乐也没有比结识了一个志同道合的新朋友更欢乐的。这是古今以来儿女的常情。富贵不是我谋求的事，还是回到带湖的家去，与我早已订立过同盟的老朋友白鸥聚会的好。', poem_notes = '水调歌头：词牌名，又名“元会曲”“台城游”“凯歌”“江南好”“花犯念奴”等。双调，九十五字，平韵（宋代也有用仄声韵和平仄混用的）。相传隋炀帝开汴河自制《水调歌》，唐人演为大曲， “歌头”就是大曲中的开头部分。\n壬子：指绍熙三年（1192年）。陈端仁：即陈岘，字端仁，闽县人。绍兴二十七年进士。曾先后任平江守、两浙转运判官、福建市舶。淳熙九年在四川安抚使任上罢职回家。给事，给事中，官名。为门下省。宋制，门下省的给事中有四人，掌管：侍从规谏，掌读中外出纳，日编章奏目录以进，驳正政令失当，考其稽违而纠正之。（见《宋史·职官志》门下省条）\n长恨复长恨二句：长恨，即《长恨歌》。白居易《长恨歌》：“天长地久有时进，此恨绵绵无绝期。”《短歌行》，乐府平调曲名。《乐府解题》：“魏武帝‘对酒当歌，人生几何。’晋陆机‘置酒高堂，悲来临觞。’皆言当及时为乐。”\n何人为我楚舞二句：《史记·留侯世家》：汉高祖刘帮欲废吕后的儿子，另立戚夫人的儿子赵王如玉为太子，事情没有成。“戚夫人泣，上曰：‘为我楚舞，吾为若楚歌。’”楚狂声，楚国的狂人接舆的《凤兮歌》。接舆曾路过孔子的门口，歌：“凤兮！凤兮！何德之衰？往者不可谏，来者犹可追。已而！已而！今之从政者殆而！”（见《论语·微子篇》）\n余既滋兰九畹三句：《离骚》：“余既滋兰 之九畹，又树蕙之百亩”“朝饮木兰之坠 露兮，夕餐秋菊之落英”。\n门外沧浪水二句：《孟子·离屡篇》：“沧浪之水清兮，可以濯我缨，沧浪之水浊兮，可以濯我足。”缨，丝带子。这两句的意思是：对清水、浊水态度要明确，不要然然可可。表示了他刚正清高的品德。\n毫发常重泰山轻：这是说人世间的各种事都被颠倒了。\n悲莫悲生离别三句：屈原《楚辞·九歌·少司命》：“悲莫悲兮生离别，乐莫乐兮新相识。”这里是对陈端仁说的。表示对陈端仁有深厚的感情。\n富贵非吾事二句：陶渊明《归去来辞》：“富贵非吾愿，帝乡不可期。”', poem_appreciation = '辛弃疾的这首《水调歌头》，是一首感时抚事的答别之作。\n\n　　此词上片分两层，前两韵是第一层，直接抒写诗人的“长恨”和“有恨无人省”的感慨。作者直接以“长恨复长恨，裁作短歌行”句开篇，乍看似觉突兀；其实稍加思索，就会明白其深刻的感情背景。由于北方金朝的入侵，战乱不息，被占区人民处在金人统治之下，而偏安一隅的南宋小朝廷却非但不图恢复，还对主张抗金北伐的人士加以压制和迫害，作者就曾多次受到打击。这对于一个志在恢复的爱国者来说，不能不为此而感到深切的痛恨。如此“长恨”，在“饮饯席上”难以尽言，所以词人只能用高度浓缩的语言，把它“裁作短歌行”。“短歌行”，原是古乐府《平调曲》名，多用作饮宴席上的歌辞。词人信手拈来，融入句中，自然而巧妙地点明了题面。“长恨”而“短歌”，不仅造成形式上的对应美，更主要的是显示出那种恨不得尽言而又不能不言的情致。“何人为我楚舞，听我楚狂声”一句，合用了两个典故。据《史记·留侯世家》载，汉高祖刘邦“欲废太子，立戚夫人子赵王如意”，由于留侯张良设谋维护太子，此事只好作罢，戚夫人因向刘邦哭泣，刘邦对她说：“为我楚舞，吾为若楚歌。”歌中表达了刘邦事不从心、无可奈何的心情。又《论语·微子篇》载，楚国隐士接舆曾唱歌当面讽刺孔子迷于从政，疲于奔走，《论语》因称接舆为“楚狂”。辛弃疾在这里运用这两个典故，目的是为了抒发他虽有满腔“长恨”而又无人理解的悲愤，一个“狂”字，更突出了他不愿趋炎附势、屈从权贵的耿介之情。从遣词造句看，这一韵还妙在用“何人”呼起，以反诘语气出之，大大增强了词句的感人力量；而“为我楚舞”，“听我楚狂声”，反复咏言，又造成一种一唱三叹，回肠荡气的艺术效果。词人在直抒胸臆以后，紧接着就以舒缓的语气写道：“余既滋兰九畹，又树蕙之百亩，秋菊更餐英。”一韵三句，均用屈原《离骚》诗句。前两句径用屈原原句，只是“兰”字后少一“之”字，“畹”字后少一“兮”字。“餐英”句则从原句“朝饮木兰之坠露兮，夕餐秋菊之落英”概括而来。兰、蕙都是香草，“滋兰”、“树蕙”，是以培植香草比喻培养自己美好的品德和志节。而“饮露”、“餐英”，则是以饮食的芳洁比喻品节的纯洁和高尚。作者在这里引用屈原诗句，并用“滋兰”、“树蕙”之词，显然是为了表达自己的志节和情操。屈原在忠而被谤、贤而见逐的情况下，仍然坚定地持其“内美”和“修能”，执着地追求自己的理想，词人在遭朝中奸臣谗言排挤，被削职乡居的情况下，依然不变报国之志，表明自己决不肯随波逐流与投降派同流合污，沆瀣一气。“门外沧浪水，可以濯吾缨”一句，仍承前韵词意，从另一个角度表明自己的志节和操守。这里又用一典。《楚辞·渔父》中说，屈原被放逐，“游于江潭”，“形容枯槁”，渔父问他为什么到了这种地步，屈原说：“举世皆浊我独清，众人皆醉我独醒，是以见放。”渔父劝他“与世推移”，不要“深思高举”，自讨其苦。屈原说：“宁赴湘流，葬于江鱼之腹”，也不肯“以皓皓之白，而蒙世俗之尘埃”。渔父听后，一边摇船而去，一边唱道：“沧浪之水情兮，可以濯我缨；沧浪之水浊兮，可以濯我足。”意思是劝屈原要善于审时度势，采取从时随俗的处世态度。词人化用此典，意在进一步表明自己的志节情操。\n\n　　下片头三句“一杯酒，问何似，身后名？”遥应篇首，意在抒发自己理想无从实现的感慨，情绪又转入激昂。据《世说新语·任诞》载，西晋张翰（字季鹰），为人“纵任不拘”，有人问他：“卿乃可纵适一时，独不为身后名耶？”他说：“使我有身后名，不如即时一杯酒。”词人用张翰的典故，乃是牢骚之气。\n\n　　他的抗金复国理想难以实现，志业难遂，还要那“身后”的虚名干什么！词人为什么会发此牢骚呢？辛弃疾接着写：“人间万事，毫发常重泰轻。”这一韵是全词的关键所在，道出“长恨复长恨”的根本原因，就是因为南宋统治集团轻重倒置，是非不分，置危亡于不顾，而一味地苟且偷安。这是词人对南宋小朝廷腐败政局的严厉批判和愤怒呼喊。最后两韵是下片第二层，通过写惜别再一次表明自己的心志，词人的情绪这时又渐渐平静下来。前三句写惜别，用屈原《九歌》点明恨别乐交乃古往今来人之常情，表明词人和饯行者陈端仁的情谊深厚，彼此都不忍离别之情。“富贵非吾事，归与白鸥盟”一句，又引用两个典故。陶渊明《归去来兮辞》云：“富贵非吾愿，帝乡不可期。”陶渊明生于东晋末叶，社会动乱，政治黑暗，而他本人又“质性自然”（《归去来兮辞序》），“不慕荣利”（《五柳先生传》），因有是辞。这里词人引用陶诗，表明自己此次奉召赴临安并不是追求个人荣利，并且也不想在那里久留，以表明自己的心迹。“归与白鸥盟”，是作者从正面表明自己的心迹。据《列子·黄帝篇》载，相传海上有位喜好鸥鸟的人，每天早晨必在海上与鸥鸟相游处，后遂以与鸥鸟为友比喻浮家泛宅、出没云水间的隐居生活。在这里，词人说归来与鸥鸟为友，一方面表明自己宁可退归林下，也不屑与投降派为伍，另一方面也有慰勉陈端仁之意。\n\n　　与一般的离别之词不同，辛弃疾的这首《水调歌头》，虽是答别之词，却无常人的哀怨之气。通观此篇，它答别而不怨别，溢满全词的是他感时抚事的悲恨和忧愤，而一无凄楚或哀怨。词中的声情，时而激越，时而平静，时而急促，时而沉稳，形成一种豪放中见沉郁的艺术情致。此外，词中还成功地运用比兴手法，不仅丰富了词的含蕴，而且对抒发词人的志节等，也都起到了很好的艺术效果。', poem_tags = '答别,感时,抚事,抒志' WHERE poem_title = '水调歌头·壬子三山被召陈端仁给事饮饯席上作' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '窗南有棵孤傲的青松，枝叶是多么茂密。\n清风时时摇着它的枝条，潇洒终日是多么惬意。\n树阴下老早以前就长满绿苔，秋日的云雾到此也被它染碧。\n何时才能枝叶参天长到云霄外面，直上千尺巍然挺正。', poem_notes = '南轩：轩原本指多窗的长廊，这里泛指当南的窗外。\n柯叶：枝叶。\n绵幂：密密层层的样子，枝叶稠密而相覆之意。\n潇洒：洒脱，无拘束貌。此以形容松树枝叶在清风中摆动的样子。\n日夕：早晚。“终日夕”与上句“无闲时”对举。\n“阴生”句：阴凉处生出的青苔颜色深绿。\n“色染”句：苍翠的青松似乎将秋一的烟岚都染绿了。\n何当：犹言何日、何时。\n凌云霄：直上云霄。', poem_appreciation = '安旗《李白全集编半注释》云，此诗于开元十五年（727）而作。\n\n　　“南轩有孤松，柯叶自绵幂”运用铺叙的手法，描绘出一幅松树苍劲挺拔、松树枝叶稠密昂首天外的景致。诗一开头，就说这是一棵“孤松”，突出了它的不同凡俗。接着写松树枝叶繁茂、生机勃勃、四季常青，塑造出松树郁郁苍苍、古朴高洁的形象。\n\n　　“清风无闲时，潇洒终日夕”，风吹劲松，更觉松树苍劲。古人有诗云：“亭亭山上松，瑟瑟谷中风。风声一何盛，松枝一何劲。”“清风”、“潇洒”、“日夕”等有巨大气势的事物和表现大起大落的动词，使得诗意具有飞扬跋扈、迅猛阔大的气势。风因松而见其盛，松因风而见其劲，为下文期盼“孤松”向往着“直上数千尺”的凌云之势作铺垫。\n\n　　“阴生古苔绿，色染秋烟碧”两句，再对松树生长的环境进行描写，来烘托松树高大苍翠。“阴生古苔绿”，是说由于松树高大，在它的阴处长出了碧绿的古苔。既言“古苔”足见这棵松树的年岁之长。半空中松树茂密的枝叶，一片浓密翠绿，而地上的古苔也呈现出一片绿色，上下辉映，似乎将周围的空气都要染绿了似的。“色染秋烟碧”，形象地描绘了这一迷人景象。其中一个“染”字用得妙，将景物都着上了宜人的色彩。\n\n　　“何当凌云霄，直上数千尺”以夸张的口吻极言其高。正是抒写的诗人见“孤松”而生的感叹，但不是以上所说的那种感觉，却是一种因不满足于眼前之景而萌生的期待、盼望之情。\n\n　　此诗的前六句，重在描绘诗人所见“孤松”之景，写“孤松”枝叶繁茂、清风中显得那样潇洒自得；“孤松”苔绿叶翠，秋烟中更添膘胧之美。这给人以孤傲自恃，超然物外的感觉。末二句，侧重体现出诗人不满足于“孤松”的潇洒自得，向往着“直上数千尺”的凌云之势。（唐）范传正《李白新墓碑》所谓：“常欲一鸣惊人，一飞冲天”之意。这种情感，显然是诗人虽来得重用，却时时怀有凌云壮志渴望施展的内心情怀的一种“借越发挥”。\n\n　　此诗借用“孤松”、“清风”、“游云”、“日夕”、“苔绿”、“秋烟”、“苔绿”、“云霄”、“染”、“凌”等有巨大气势的事物和表现大起大落的动词，使得诗意具有飞扬跋扈、不可一世的气势，易使读者产生激昂振奋的感觉，侧面衬托出“孤松”潇洒高洁、顽强挺拔的品性，表现出诗人不满足于“孤松”的潇洒自得，向往着“直上数千尺”的凌云之势，表达了诗人刚正不阿的高尚品格，道明诗人崇高的理想和远大的抱负。', poem_tags = '咏物,抒怀,理想' WHERE poem_title = '南轩松' AND poem_author = '李白';
UPDATE edu_poem SET poem_tags = '送别,友情' WHERE poem_title = '送李判官之润州行营' AND poem_author = '刘长卿';
UPDATE edu_poem SET poem_translation = '水上柔嫩的苹叶，衬着岸边洁的杏花；翠红美丽的鸳鸯，拖着长长的绿漪浮漾。一叶轻盈的画摇出船，添几阕情韵袅袅的“棹歌”。\n春光，轻灵摇荡，明媚可人！水，好在无风无浪；天，好在半雨半晴。在疏淡的暮霭中，伴一二红粉知已泛舟南浦，更多了几分含蕴不露的情意！', poem_notes = '软：一作“嫩”。\n明：鲜艳。\n绿汀（tīng）：芳草丛生的水边平地。\n棹歌：船歌。\n红粉：借代为女子。\n几含情：屡次含着深情。李颀《采莲曲》：“时逢岛屿泊，几伴鸳鸯眠。”白居易《东南行一百韵》：“几见林抽笋，频惊燕引雏。”', poem_appreciation = '此词作于《花间集》结集之后，所以不见于《花间集》。作品描绘的是成都的的风光和生活。词中突出了春天日光和煦、万物欣欣向荣的特点，并使描写的物象有机地组合为一体，构成一幅明丽和谐的春色图。\n\n　　此词发端以淡淡的笔墨点明时令：“天初暖，日初长。”成都四季分明，冬尽春始，景象不同。这两句写春天来了，用两“初”字，而且都是就感受着笔的。天初暖，写气候特征；日初长，写昼夜特征。两句看似平易，却是咏早春的不可移易之语。大地经过沉睡的冬季之后苏醒了。无边的春色使词人情不自禁地叫出一声“好春光”。紧接着以“万汇此时皆得意，竞芬芳”来补充“好”字的内容。万汇，包括各种竹木花树。它们新叶不同，颜色不同，花儿不同，在春风的吹拂下争奇斗艳，处处给人以竞相比美之感。词人先用一个“得意”，再用一个“竞”字，像以浓墨重彩在表现热闹的春意。\n\n　　下片写园林春色，是特写，是近景。一场春雨，竹林中新笋从点点如钱的绿苔地里迸发出来，第二句“花偎雪坞浓香”与首句“笋迸苔钱嫩绿”对仗，景致互相映衬，香色纷陈，更为突出。繁花，花团锦簇，如绰约少女依偎着雪坞，浓香四溢。词人在迷人的春色中流连忘返，不觉到了黄昏。天空泛出彩霞，他举目望去，柳丝夕阳，构成了天然图画，词人忽发奇想问道：“谁把金丝裁剪却，挂斜阳？”春柳嫩叶初萌，色如金线，故白居易《杨柳枝》说：“一树春风千万枝，嫩于金色软于丝。”均匀的柳丝，两两相对的柳叶，像天工剪裁而成。贺知章《咏柳》说：“碧玉妆成一树高，万条垂下绿丝绦。不知细叶谁裁出，二月春风似剪刀。”后二句人称神来之笔，欧阳炯化用其意以写早春园林夕照，创造了新的意境，余味无穷。', poem_tags = '春游' WHERE poem_title = '春光好·蘋叶软' AND poem_author = '和凝';
UPDATE edu_poem SET poem_translation = '神女寺依旧傍着青山，楚王的细腰宫依旧枕着碧绿的江流。潺潺流水和暖暖翠岚环绕着昔日梳妆的楼台，悠悠往事真叫人感慨万千。\n巫山从早到晚雨迷云轻，春去秋来花开花落，岁月就这般流逝。何必要猿啼声声传向孤舟，远行的旅客自有许多忧愁。', poem_notes = '巫山一段云：唐教坊曲，原咏巫山神女事。后用为词牌。双调小令，四十四字，前后片各三平韵。\n古庙：指巫山脚下供奉神女的祠庙。\n青嶂（zhàng）：即十二峰。嶂：形势高险象屏障的山峰。\n行宫：京城以外供帝王出巡时居住的宫室，此处指楚细腰宫遗址。\n枕（zhěn）碧流：意为行宫临水而建。\n妆楼（zhuāng lóu）：寝楼，指细腰宫中宫妃所居。\n云雨：指宋玉《高唐赋序》楚怀王梦中幽会巫山神女之事。\n烟花：泛指自然界艳丽的景物。\n啼猿（tí yuán）：巫峡多猿，猿声凄厉如啼。', poem_tags = '宋词三百首,婉约,寺庙,山水,行舟,怀念' WHERE poem_title = '巫山一段云·古庙依青嶂' AND poem_author = '李珣';
UPDATE edu_poem SET poem_translation = '寂静的前庭空无一人，只有秋月仍旧明亮。夜里的清霜将要落下，空气中也充满了清朗的气息。\n梧桐树矗立在庭前，也不甘就此衰落。树上的梧桐叶迎风摇摆，发出了些许声音。', poem_notes = '气：气氛。\n清：冷清。\n甘：甘心。', poem_tags = '古诗三百首,秋夜,写景,抒怀' WHERE poem_title = '夜坐' AND poem_author = '张耒';
UPDATE edu_poem SET poem_translation = '清早出去，笼一蓑霏微烟雨，傍晚归来，钓一竿迷蒙风月，家就居在富春江滨的子陵钓台西边。卖鱼的时候惟恐走近城门跟前，更不用说还会到闹市深处去了。\n潮生时泛船出去打鱼，潮平时摆船靠岸系缆，潮落时高唱渔歌归家。当时的人们错把我比作披蓑垂钓的严光，然而，我更愿作一位无名的渔父。', poem_notes = '鹊桥仙：词牌名，此调专咏牛郎织女七夕相会事。\n一竿风月：风月中垂一钓竿。\n蓑（suō）：蓑衣。\n钓台：汉代隐士严光隐居的地方，在今浙江省富春江畔的桐庐县。\n况肯：更何况。\n红尘：指俗世。\n棹（zhào）：指船桨。\n潮平系缆：潮水满涨时停船捕鱼。\n浩歌：指放声高歌，大声歌唱。\n严光：即严子陵，汉代著名隐士。\n渔父：渔翁，捕鱼的老人。', poem_appreciation = '“一竿风月，一蓑烟雨”，是渔父的生活环境。“家在钓台西住”，这里借用了严光不应汉光武的征召，独自披羊裘钓于浙江的富春江上的典故。以此来喻渔父的心情近似严光。上片结句说，渔父虽以卖鱼为生，但是他远远地避开争利的市场。卖鱼还生怕走近城门，当然就更不肯向红尘深处追逐名利了。以此来表现渔父并不热衷于追逐名利，只求悠闲、自在。\n\n　　下片头三句写渔父在潮生时出去打鱼，在潮平时系缆，在潮落时归家。生活规律和自然规律相适应，并无分外之求，不象世俗中人那样沽名钓誉，利令智昏。最后两句承上片“钓台”两句，说严光还不免有求名之心，这从他披羊裘垂钓上可看出来。宋人有一首咏严光的诗说：“一着羊裘便有心，虚名留得到如今。当时若着蓑衣去，烟水茫茫何处寻。”也是说严光虽拒绝光武征召，但还有求名心。陆游因此觉得：“无名”的“渔父”比严光还要清高。\n\n　　这词上下片的章法相同，每片都是头三句写生活，后两句写心情，但深浅不同。上片结尾说自己心情近似严光，下片结尾却把严光也否定了。文人词中写渔父最早、最著名的是张志和的《渔父》，后人仿作的很多，但是有些文人的渔父词，用自己的思想感情代替劳动人民的思想感情，很不真实。\n\n　　陆游这首词，论思想内容，可以说在张志和等诸人之上。显而易见，这词是讽刺当时那些被名牵利绊的俗人的。读者不可错会他的写作意图，简单地认为它是消极的、逃避现实的作品。\n\n　　陆游另有一首《鹊桥仙》词：“华灯纵博，雕鞍驰射，谁记当年豪举？酒徒一半取封候，独去作江边渔父。轻舟八尺，低逢三扇，占断苹洲烟雨。镜湖元自属闲人，又何必官家赐与！”也是写渔父的。它上片所写的大概是他四十八岁那一年在汉中的军旅生活。而这首词可能是作者在王炎幕府经略中原事业夭折以后，回到山阴故乡时作的。两首词同调、同韵，都是写他自己晚年英雄失志的感慨，决不是张志和《渔父》那种恬淡、闲适的隐士心情。读这首词时，应该注意他这个创作背景和创作心情。', poem_tags = '咏怀,渔父,生活,心情' WHERE poem_title = '鹊桥仙·一竿风月' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '一夜霜冻过后，菊花凋残，荷花枯萎，而新橘和绿叶相映衬，光亮照眼，竹篱茅舍掩映在青黄相间的橘林之间。\n刚刚剥开橘子，芳香的水雾喷洒出来让人惊喜不已；带着几分胆怯楞尝新橘，甜中带酸的汁水在齿颊间如清泉流过，使人格外欣喜。江南女子的手剥橘后三日还有香味。', poem_notes = '浣溪沙：唐代教坊曲名，后用为词牌。分平仄两体，双调，上片三句全用韵，下片末二句用韵。\n一夜霜：橘经霜之后，颜色开始变黄而味道也更美。白居易《拣贡橘书情》：“琼浆气味得霜成。”\n新苞：指新橘。\n青黄：指橘子，橘子成熟时，果皮由青色逐渐变成金黄色。屈原《橘颂》“青黄杂糅，文章烂兮”。\n“香雾”二句：宋韩彦直《橘录》卷上《真柑》：“真柑在品类中最贵可珍······始霜之旦，园丁采以献，风味照座，擘之则香雾噀人。”噀（xùn），喷。半破，指刚刚剥开橘皮。清泉，喻橘汁。\n吴姬：吴地美女。', poem_appreciation = '咏物诗词，义兼比兴，讲求气象，自然容易受到好评。唐宋诗人，遵循《诗经》以来的“美”、“刺”原则，每借物寓意，有所寄讽，并以此为咏物“正宗”，而直写物象的纯粹的咏物之作，似乎已落入第二义了。其实，“纯用赋体，描写确肖”的咏物诗词，只要在选材炼意、琢句谋篇方面技巧娴熟，精美工致，也不失为佳构。\n\n　　苏轼是咏物能手，他的诗词中既有托讽深远的名篇，也有刻画精工的妙制，像这首咏橘词，可谓“写气图貌，既随物以宛转；属采附声，亦与心而徘徊”（《文心雕龙·物色》），巧言切状，体物细微，虽无深刻的思想内容，却饱有余味。\n\n　　“菊暗荷枯一夜霜”，先布置环境。咏物词，特别是咏小物的词，往往由于题材狭窄，难以展开，低手为之，易成枯窘。东坡才大，先在题前落笔，下文便有余地抒发。唐人皮日休《石榴歌》首句“蝉噪秋枝槐叶黄”，同此手段。“菊暗荷枯”四字，是东坡《赠刘景文》诗“荷尽已无擎雨盖，菊残犹有傲霜枝”的概括。“一夜霜”，经霜之后，橘始变黄而味愈美。晋王羲之帖：“奉橘三百枚，霜未降，未易多得。”又白居易《拣贡橘书情》诗：“琼浆气味得霜成。”皆可参证。“新苞”句，轻轻点出题目。橘有皮包裹，故称新苞。又因橘树常绿，凌寒不凋。《楚辞·橘颂》：“绿叶素荣，纷其可嘉兮。”沈约《橘》诗：“绿叶迎露滋，朱苞待霜润。”东坡用“新苞绿叶”四字，描写自然，再以“照林光”描绘之，可谓得橘之神了。“竹篱茅舍出青黄”，好在一“出”字。竹篱茅舍，掩映于青黄相间的橘林之中，可见橘树生长之盛，人家环境之美，一年好景，正当此时。上片三句，纯是赋体，不杂一点抒情成分，然词人对橘的喜爱之情自见于字里行间。\n\n　　过片二句，写尝橘的情状。擘开橘皮，芳香的油腺如雾般喷溅；初尝新橘，汁水在齿舌间如泉般流淌。“香雾”、“清泉”之喻，大概是东坡颇为得意的，他的《食柑》诗也有“清泉簌簌先流齿，香雾霏霏欲噀人”之句，后来南宋诗人曾几更把它压缩为“流泉喷雾真宜酒”（《曾宏甫分饷洞庭柑》）一语了。此词中“惊”、“怯”二字，活画出女子尝橘时的娇态。惊，是惊于橘皮迸裂时香雾溅人，怯，是怯于橘汁的凉冷和酸味。末句点出“吴姬”，实际也点明新橘的产地。吴中产橘，尤以太湖中东西两洞庭山所产者为最著，洞庭橘在唐宋时为贡物。词中谓“三日手犹香”，着意夸张。以此作结，余音不绝，亦自有“三日绕梁”之妙。', poem_tags = '咏物,橘子' WHERE poem_title = '浣溪沙·咏橘' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '成千上万的彩船行驶在运河两岸的翠柳中间，但这支船队载到扬州后再也没有回还。\n应该是上天教人们开通汴河，这里一千余里的地面上看不到一座山峦。\n\n都说隋朝亡国是因为这条河，但是到现在它还在流淌不息，南北舟楫因此畅通无阻。\n如果不是修龙舟巡幸江都的事情，隋炀帝的功绩可以和大禹平分秋色。', poem_notes = '舸：大船。\n载到扬州尽不还：隋炀帝杨广游览扬州时被部将宇文化及杀死。\n汴水：汴河，即通济渠。\n水殿龙舟事：隋炀帝下扬州乘龙舟的风景的事。\n共禹论功：作者在这里肯定了隋朝大运河的积极意义，是可以和大禹治水的功绩相比的。', poem_appreciation = '第一首诗的“万艘龙舸”代指隋炀帝的船队。全诗描述了隋炀帝游览扬州的豪华船队以及大运河的地理环境，诗中隐含了隋炀帝被部将宇文化及杀死的历史事实。诗说当年的浩然盛大的场面如今已经不复存在，实质是说当时的唐帝国早已是连隋炀帝时也比不得了。这是对当政者的警训，意味深长。\n\n　　第二首诗第一句从隋亡于大运河这种论调说起，而以第二句反面设难，予以批驳。诗中说：很多研究隋朝灭亡原因的人都归咎于运河，视为一大祸根，然而大运河的开凿使南北交通显著改善，对经济联系与政治统一有莫大好处，历史作用深远。用“至今”二字，以表其造福后世时间之长；说“千里”，以见因之得益的地域之辽阔；“赖”字则表明其为国计民生之不可缺少，更带赞许的意味。此句强调大运河的百年大利，一反众口一辞的论调，使人耳目一新。这就是唐人咏史怀古诗常用的“翻案法”。翻案法可以使议论新颖，发人所未发，但要做到不悖情理，却是不易的。大运河固然有利于后世，但隋炀帝的暴行还是暴行，皮日休是从两个不同角度来看开河这件事的。当年运河竣工后，隋炀帝率众二十万出游，自己乘坐高达四层的“龙舟”，还有高三层、称为浮景的“水殿”九艘，此外杂船无数。船只相衔长达三百余里，仅挽大船的人几近万数，均著彩服，水陆照亮，所谓“春风举国裁宫锦，半作障泥半作帆”（李商隐《隋宫》，其奢侈糜费实为史所罕闻。第三句“水殿龙舟事”即指此而言。\n\n　　作者对隋炀帝的批斥是十分明显的。然而他并不直说。第四句忽然举出大禹治水的业绩来相比，甚至用反诘句式来强调：“共禹论功不较多？”意思就是：论起功绩来，炀帝开河不比大禹治水更多些吗？这简直荒谬离奇，但由于诗人的评论，是以“若无水殿龙舟事”为前提的。仅就水利工程造福后世而言，两者确有可比之处。然而“若无”云云这个假设条件事实上是不存在的，极尽“水殿龙舟”之侈的炀帝终究不能同躬身治水、“三过家门而不入”的大禹相与论功，流芳千古。故作者虽用了翻案法，实际上为大运河洗刷不实的“罪名”，而炀帝的罪反倒更加实际了。这种把历史上暴虐无道的昏君与传说中受人景仰的圣人并提，是欲夺故予之法。说炀帝“共禹论功不较多”，似乎是最大恭维奖许，但有“若无水殿龙舟事”一句的限制，又是彻底的剥夺。“共禹论功”一抬，“不较多”再抬，高高抬起，把分量重重地反压在“水殿龙舟事”上面，对炀帝的批判就更为严厉，谴责更为强烈。这种手法的使用，比一般正面抒发效果更好。\n\n　　此诗以议论为主，在形象思维、情韵等方面较李商隐《隋宫》一类作品不免略逊一筹；但在立意的新奇、议论的精辟和“翻案法”的妙用方面，自有其独到处，仍不失为晚唐咏史怀古诗中的佳品。', poem_tags = '咏史怀古,组诗' WHERE poem_title = '汴河怀古二首' AND poem_author = '皮日休';
UPDATE edu_poem SET poem_translation = '扎紧战袍，系上红缨大刀，打马前行，雪夜度过洮水河。\n旗子高扬，连夜冲入单于帐内，砍杀胡兵，宝刀都残缺破损了。', poem_notes = '金带：大刀柄上系的红绸子。连环：一种刀。束：捆。\n临洮（táo）：古县名，在今甘肃省岷县，以临洮水得名，在临河沿岸。\n卷（juǎn）旗：指急行军，军旗高高飘扬。\n劫：劫持，冲杀。\n斫：读zhuó，砍。缺：破损。', poem_tags = '边塞,战争' WHERE poem_title = '出塞词' AND poem_author = '马戴';
UPDATE edu_poem SET poem_translation = '犹如一对亲昵的小儿女轻言细语，卿卿我我聚两个俏冤家暗叙哀曲。\n豪放得如风展旗是谁正高歌引吭，有勇士似电掣马挥长剑杀敌擒王。\n又转成浮云依依柳絮起无根无蒂，没奈何圆天茫茫道路迷宕东宕西。\n叽叽啾啾分明是烟霞中羽光翻浪，影影绰绰兀立在乔木上百凤朝凰。\n峭壁悬崖压人来寸步都攀援难上，黑壑深渊崩石下千丈犹轰隆传响。\n惭愧呀我空有耳朵一双，对音乐太外行不懂欣赏。\n听了你这琴声忽柔忽刚，振人起强人坐令人低昂。\n仓皇中我伸手把琴遮挡，泪潮呀早已经汹涌盈眶。\n颖师傅好功夫实非寻常，别再把冰与火填我胸膛。', poem_notes = '颖师：颖师是当时一位善于弹琴的和尚，他曾向几位诗人请求作诗表扬。李贺《听颖师弹琴歌》有“竺僧前立当吾门，梵宫真相眉棱尊”之句。\n昵（nì）昵：亲热的样子。一作“妮妮”。\n尔汝：至友之间不讲客套，以你我相称。这里表示亲近。《世说新语·排调》：“晋武帝问孙皓：闻南人好作尔汝歌，颇能为不？”《尔汝歌》是古代江南一带民间流行的情歌，歌词每句用尔或汝相称，以示彼此亲昵。\n划然：忽地一下。轩昂：形容音乐高亢雄壮。宋魏庆之《诗人玉屑·陵阳论晚唐诗律卑浅》：“唐末人诗，虽格致卑浅，然谓其非诗则不可。今人作诗，虽句语轩昂，但可远听，其理略不可究。”\n“浮云”两句：形容音乐飘逸悠扬。\n“喧啾”四句：形容音乐既有百鸟喧哗般的丰富热闹，又有主题乐调的鲜明嘹亮，高低抑扬，起伏变化。喧啾（jiū）：喧闹嘈杂。凤皇：即“凤凰”。跻（jī ）攀：犹攀登。唐杜甫《白水县崔少府十九翁高斋三十韵》：“清晨陪跻攀，傲睨俯峭壁。”\n未省（xǐng）：不懂得。丝篁（huáng）：弹拨乐器，此指琴。\n起坐：忽起忽坐，激动不已的样子。旁：一作“床”。\n推手：伸手。遽（jù）：急忙。\n滂滂：热泪滂沱的样子。《晏子春秋·谏上十七》：“景公游于牛山，北临其国城而流涕曰：‘若何滂滂去此而死乎！’”\n诚能：指确实有才能的人。《荀子·王霸》：“人主胡不广焉，无恤亲疏，无偏贵贱，唯诚能之求？”\n冰炭置我肠：形容自己完全被琴声所左右，一会儿满心愉悦，一会儿心情沮丧。 犹如说水火，两者不能相容。《庄子·人间世》：“事若成，则必有阴阳之患。”郭象注：“人患虽去，然喜惧战于胸中，固已结冰炭于五藏矣。”此言自己被音乐所感动，情绪随着乐声而激动变化。', poem_appreciation = '一千多年前，在中国的唐朝，相传有一个名叫颖的和尚，从印度来到中国，人们尊称他为颖师。颖师演奏古琴十分出名，他的古琴长八尺一寸，用质地优良的古桐木制成，音色非常优美。颖师弹琴的技艺精湛，演奏时有特别的韵味，而且曲目很丰富，远近知名。据说有一个生病的人，躲在床上，听到颖师弹琴的声音，顿然觉得已经病好了，坐了起来，不用再服药了。韩愈是唐代著名的诗人和文学家，也慕名前来欣赏颖师弹琴。\n\n　　开始的时候，琴音柔和细弱，婉转轻盈，像一对年轻的少男少女在静悄悄地温柔细语，倾诉彼此心里的爱慕之情。韩愈听得十分愉悦，像是听到了一首美丽的情诗。突然，琴声激昂高亢，像是万马奔腾，勇士们奔赴沙场，刹时间刀剑齐鸣，悲壮惨烈。韩愈为之精神震奋不已，好像自己也在战场厮杀。一会儿，琴声又悠扬飘逸，像柳絮轻场，随风飘忽，在蓝天白云下自由飞舞。韩愈也如醉如痴，仿佛自己也飘上了太空。\n\n　　很快地，琴声又热闹起来，到处是莺歌燕舞，百鸟齐鸣，又见有一只凤凰引领高歌。此时百鸟围着凤凰飞舞，一片乐观升平气象。\n\n　　接着，琴音激越地往上攀升，越攀越高，仿佛在攀登峭壁悬崖，一寸一寸地艰难前进。不料，琴声从最高处忽然下滑到最低音，好像是攀登者忽然失足，从千丈高峰一下子掉落到无底的深渊。把韩愈骇得心惊胆跳……\n\n　　韩愈听到这里，激动得坐也不是，站也不是，泪如雨下，把衣襟也湿透了。他不得不伸手拦阻，请颖师中止弹奏，对颖师说：“我虽然长着两只耳朵，但是不懂音乐。不过这次听到你的弹奏，却把我激动得控制不了自己。你的演奏实在太高明了，好像是把冰和炭火放在我的心窝似的，你要是再弹下去，我可真的受不了了。”韩愈后来把他听颖师弹琴的感受写成了一首诗。这首诗一直流传至今天。上面所说的就是他在诗中所述当时听琴时的感受。', poem_tags = '音乐' WHERE poem_title = '听颖师弹琴' AND poem_author = '韩愈';
UPDATE edu_poem SET poem_translation = '西岳高耸似一位德高望重的老人，群峰在其周围则像他的儿孙。\n怎么才能求得仙人杖，拄着它登上华山去玉女祠呢？\n可进了车箱谷就难以回归了，而山峰像通天的箭尾直抵天门，难以登爬。\n稍稍等待天气转凉后，登上山顶去，看山本貌。', poem_notes = '崚嶒：高耸突兀。\n九节杖：《刘根外传》：“汉武登少室，见一女子以九节杖仰指日，闭左目，东方朔曰：‘此食日精者。’”《真诰》：“杨羲梦蓬莱仙翁，拄赤九节杖而视白龙。”\n玉女洗头盆：《集仙录》：“明星玉女，居华山，服玉浆，白日升天，祠前有五石白，号玉女洗头盆。其水碧绿澄彻，雨不加溢，旱不减耗。祠有玉女马一匹。”\n车箱入谷：《太平寰宇记》：“车箱谷，一名车水涡，在华阴县西南二十五里，深不可测。祈雨者以石投之，中有一鸟飞出，应时获雨。”\n箭栝：箭的末端。\n白帝：中国古代神话中的五天帝之一，古代指西方之神。', poem_appreciation = '简析 　　咏华山一首，作者所写的华山亦同样雄伟。不过，与年青时代一首相比，这无疑是一首失意之作。自天宝乱来，作者饱历忧患方得重返朝廷，而今因宰相房琯败绩丧师于陈涛斜被罚，抗疏救之而获罪被贬。作者人至中年，除了官拜左拾遗一年境遇较佳，一直极备艰辛。因此，诗中亦有流露出失意徬徨之感。作者发端“西岳崚嶒竦处尊，诸峰罗立似儿孙”即写华山崇高。作者虽然极欲登山，但“安得仙人九节杖”一句“安得”二字诘问，已表明了作者之愿难以实现。这好比作者欲要报国，却总是报国无门，无可奈何的心情。“车箱入谷无归路，箭栝通天有一门”两句写作者仰望之余，预计攀登之路。不过这始终并未实行，只是作者在望岳时的盘算，藉以自我安慰而已。情况一如作者纵有一腔抱负理想，却只能空自盘算，无法行之于世。最后，本诗以“稍待西风凉冷后，高寻白帝问真源。”作结，作者宦途的坎坷更是可见。现实环境的不顺，使得作者产生了厌倦宦途之情，期望于热闹中寻得凉冷以自疗创痛。以华山之顶比白帝之居，更表现了作者自感理想无可实现的失意徬徨。 ▲', poem_tags = '写山,咏物' WHERE poem_title = '望岳三首·其二' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '五月的火焰山行人稀少，看着您骑马迅疾如飞鸟。\n都护军营在太白星西边，一声号角就把胡天惊晓。', poem_notes = '武威：即凉州，今甘肃武威。判官：官职名，为地方长官的僚属。碛西：即沙漠之西，指安西。行军：指出征的军队。\n火山：即火焰山，在今新疆，从吐鲁番向东断续延伸到鄯善县以南。\n都护行营：指安西节度使高仙芝的行营。行营：出征时的军营。太白：即金星。古时认为太白是西方之星，也是西方之神。\n角：军中乐器，亦用以报时，略似今日的军号。', poem_tags = '送别,惜别,写人' WHERE poem_title = '武威送刘判官赴碛西行军' AND poem_author = '岑参';
UPDATE edu_poem SET poem_translation = '园子里的树上结满了鲜桃，那些甜美的果实可吃个饱。但我内心里充满忧伤情怀，低唱着伤心曲浅呤着歌谣。那些不理解我痛苦的人啊，肯定说我书呆子清高孤傲。这些通达之人说的很对啊，但请你告诉我怎么办为好？我内心里无尽的忧伤情怀，普天下之人你们谁能知道！你们谁能真正理解我心啊，我还是不要空自伤怀的好！\n园子里的小枣树枝繁叶茂，那些鲜美的果实可吃个饱。但我内心里充满忧伤情怀，姑且到广袤田里转悠一遭。那些不理解我痛苦的人啊，肯定说我书呆子是大傻冒。这些通达之人说的很对啊，但请你告诉我怎么办才好？我内心里无尽的忧伤情怀，普天下之人你们谁能知道！你们谁能真正理解我心啊，我还是不要空自伤怀的好！', poem_notes = '之：犹“是”。肴，吃。“其实之肴”，即“肴其实”。\n之：犹“其”。\n歌、谣：曲合乐曰歌，徒歌曰谣，此处皆作动词用。\n士：古代对知识分子或一般官吏的称呼。\n彼人：那人。是：对，正确。\n子：你，即作者。何其：为什么。其，作语助词。\n盖（hé）：通“盍”，何不。亦：作语助词。\n棘：指酸枣。\n聊：姑且。行国：离开城邑，周游国中。“国”与“野”相对，指城邑。\n罔极：无极，无常，妄想，没有准则。', poem_appreciation = '这首诗语言极明白，表现的思想感情也很清楚，然而对诗人“忧”什么，时人为何不能理解他的“忧”，反认为他骄傲、反常，难以找到确切答案。同时他自称“士”，而“士”代表的身份实际并不确定，《诗经》中三十三篇有“士”字，共54个，仅毛传、郑笺就有多种解释，如：“士，事也”，指能治其事者；“士，卿士也”；“士者，男子成名之大号也”；“士者，男子之大号也”；“言士者，有德行之称”；“士，军士也”；“他士，犹他人也”等，所以这个自称“士”的诗人是何等角色，很难认定。与之相应，对此篇的主旨就有了多种臆测：《毛诗序》谓“刺时”，何楷《诗经世本古义》作实为“晋人忧献公宠二骊姬之子，将黜太子申生”；丰坊《诗说》说是“忧国而叹之”；季本《诗说解颐》以为是“贤人怀才而不得用”；牟庭《诗切》以为是“刺没入人田宅也”。今人或说“伤家室之无乐”，或说“叹息知己的难得”，或说“没落贵族忧贫畏饥”，或说“自悼身世飘零”，或说“反映了爱国思想”，不一而足。《诗经选注》说：“我们从诗本身分析，只能知道这位作者属于士阶层，他对所在的魏国不满，是因为那个社会没有人了解他，而且还指责他高傲和反覆无常，因此他在忧愤无法排遣的时候，只得长歌当哭，自慰自解。最后在无可奈何中，他表示‘聊以行国’，置一切不顾了。因此，从诗的内容和情调判断，属于怀才不遇的可能性极大。”故指此为“士大夫忧时伤己的诗”。\n\n　　此诗两章复沓，前半六句只有八个字不同；后半六句则完全重复。两章首二句以所见园中桃树、枣树起兴，诗人有感于它们所结的果实尚可供人食用，味美又可饱腹，而自己却无所可用，不能把自己的“才”贡献出来，做一个有用之人。因而引起了诗人心中的郁愤不平，所以三、四句接着说“心之忧矣，我歌且谣”，他无法解脱心中忧闷，只得放声高歌，聊以自慰。《毛诗序》说：“永歌之不足，不知手之舞之，足之蹈之也。”这位正是因为歌之不足以泻忧，决定“聊以行国”，离开他生活的这个城市，到别处走一走，看一看。这只是为了排忧，还是想另谋出路，无法测知。但从诗的五六句看，他“行国”是要换一换这个不愉快的生活环境，则是可以肯定的。诗云：“不我知者，谓我士也骄（罔极）。”诗人的心态似乎是“众人皆醉我独醒”。因为他的思想，他的忧虑，特别是他的行为，国人无法理解，因此不免误解，把他有时高歌，有时行游的放浪行动，视为“骄”，视为“罔极”，即反常。诗人感到非常委屈，他为无法表白自己的心迹而无可奈何，所以七、八两句问道：“彼人是哉？子曰何其？”意思是：他们说得对吗？你说我该怎么办呢？这两句实际是自问自答，展现了他的内心无人理解的痛苦和矛盾。最后四句：“心之忧矣，其谁知之！其谁知之，盖亦勿思！”诗人本以有识之士自居，自信所思虑与所作为是正确的，因而悲伤的只是世无知己而已，故一再申说“其谁知之”，表现了他深深的孤独感。他的期望值并不高，只是要求时人“理解”罢了，然而这一丁点的希望，在当时来说也是不可能的，因此他只得以不去想来自慰自解。全诗给人以“欲说还休”的感觉，风格沉郁顿挫。\n\n　　这首诗以四言为主，杂以三言、五言和六言，句法参差。押韵位置两章诗相同，前半六句韵脚在一、二、四、六句末；后半六句换韵，韵脚在七、八、十、十一、十二句末，并且十、十一两句重复，哀思绵延，确有“长歌当哭”的味道。', poem_tags = '诗经' WHERE poem_title = '园有桃' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '雨点纷落，把东坡洗得格外干净，月亮的光辉也变得清澈。城里的人早已离开，此处只有山野中人闲游散步。\n千万别去嫌弃这些坎坷的坡路不如城里平坦，我，就是喜欢这样拄着拐杖铿然的声音。', poem_notes = '野人：泛指村野之人；农夫。\n荦确：怪石嶙峋貌，或者坚硬貌。\n铿然：声音响亮貌。', poem_appreciation = '东坡是一个地名，在当时黄州州治黄冈（今属湖北）城东。它并不是什么风景胜地，但对作者来说，却是灌注了辛勤劳动、结下深厚感情的一个生活天地。宋神宗元丰初年，作者被贬官到黄州，弃置闲散，生活很困窘。老朋友马正卿看不过眼，给他从郡里申请下来一片撂荒的旧营地，苏轼加以整治，躬耕其中，这就是东坡。诗人在此不只经营禾稼果木，还筑起居室——雪堂，亲自写了“东坡雪堂”四个大字，并自称东坡居士了。所以，他对这里是倾注着爱的。\n\n　　诗一开始便把东坡置于一片清景之中。僻冈幽坡，一天月色，已是可人，又加以雨后的皎洁月光，透过无尘的碧空，敷洒在澡雪一新、珠水晶莹的万物上，这是何等澄明的境界！确实当得起一个“清”字。谢灵运写雨后丛林之象说：“密林含余清”。诗人的用字直可追步大谢。\n\n　　诗人偏偏拈出夜景来写，不是无谓的。这个境界非“市人”所能享有。“日中为市”，市人为财利驱迫，只能在炎日嚣尘中奔波。唯有“野人”，脱离市集、置身名利圈外而躬耕的诗人，才有余裕独享这胜境。唯幽人才有雅事，所以“市人行尽野人行”。这读来极其自然平淡的一句诗，使我们不禁从“市人”身上嗅到一股奔走闹市嚣尘的喧闹气息，又从“野人”身上感受到一股幽人守志僻处而自足于怀的味道，而那自得、自矜之意，尽在不言中。诗人在另一首诗里说：“也知造物有深意，故遣佳人在空谷。”那虽是咏定惠院海棠的，实际是借海棠自咏身世，正好帮助我们理解这句诗所包含的意境。\n\n　　那么，在这个诗人独有的天地里，难道就没有一点缺憾吗？有的。那大石丛错、凸凹不平的坡头路，就够磨难人的了。然而有什么了不起呢？将拐杖着实地点在上面，铿然一声，便支撑起矫健的步伐，更加精神抖擞地前进了。没有艰险，哪里来征服的欢欣！没有“荦确坡头路”，哪有“铿然曳杖声”！一个“莫嫌”，一个“自爱”，那以险为乐、视险如夷的豪迈精神，都在这一反一正的强烈感情对比中凸现出来了。这“荦确坡头路”不就是作者脚下坎坷的仕途么？作者对待仕途挫折，从来就是抱着这种开朗乐观、意气昂扬的态度，绝不气馁颓丧。这种精神是能够给人以鼓舞和力量的。小诗所以感人，正由于诗人将这种可贵的精神与客观风物交融为一，构成浑然一体的境界；句句均是言景，又无句不是言情，寓情于景，托意深远，耐人咀嚼。同一时期，作者有《定风波》词写在风雨中的神态：“莫听穿林打叶声，何妨吟啸且徐行。竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。”与此诗可谓异曲同工，拿来对照一读，颇为有趣。\n\n　　诗的第一段，通过景物描写，突出当时的静。说明作者对田园生活的热爱，对世俗名利的不屑，但愿长醉山水间之意。', poem_tags = '田园,生活' WHERE poem_title = '东坡' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '陶渊明的语言平淡、自然天成，摒弃纤丽浮华的敷饰，露出真朴淳厚的美质，令人读来万古常新。\n陶渊明自谓自己是上古时代的人，但并未妨碍他仍然是个晋人。', poem_notes = '天然：形容诗的语言平易，自然天真。\n豪华：指华丽的词藻。\n真淳：真实淳朴。\n羲皇上：羲皇上人，指上古时代的人。', poem_tags = '组诗,议论' WHERE poem_title = '论诗三十首·其四' AND poem_author = '元好问';
UPDATE edu_poem SET poem_translation = '春天，隐公准备到棠地观看渔民捕鱼。臧僖伯进谏说：“凡是物品不能用到讲习祭祀、军事等大事上，或者所用材料不能制作礼器和兵器，那么，国君就不要亲自去接触它。国君是把民众引向社会规范和行为准则的人。所以，讲习大事以法度为准则进行衡量，叫做‘轨’，选取材料制作器物以显示它的文彩，叫做‘物’。事情不合乎轨、物，叫做乱政。屡屡乱政，这就是所以败亡的原因了。所以，春、夏、秋、冬四季的狩猎活动，都是在农闲时节进行，并（借这个机会）讲习军事。每三年演练一次，回国都要对军队进行休整。并要到宗庙进行祭告，宴饮庆贺，清点军用器物和猎获物。（在进行这些活动的时候，）要（使车马、服饰、旌旗等）文彩鲜艳，贵贱分明，等级井然，少长有序：这都是讲习大事的威仪啊!鸟兽的肉不能拿来放到祭祀用的器具里，皮革、牙齿、骨角和毛羽不能用来制作军事器物，这样的鸟兽，君主就不会去射它，这是自古以来的规矩啊！至于山林川泽的物产，一般器物的材料，这都是仆役们去忙活，有关官吏按职分去管理的事，而不是君主所应涉足的事。”隐公说：“我准备到那里去巡视。”于是就去了（棠地），让渔民把各种渔具都摆出来捕鱼，他在那里观赏。僖伯推说有病没有随同前往。《春秋》上说：“隐公在棠地陈设渔具。”（这是说他棠地观鱼这一行为）不合礼法啊，并且说他去的地方远离国都。', poem_notes = '春：指鲁隐公五年（前718）春季。\n公：指鲁隐公。公元前722年至公元前712年在位。按《春秋》和《左传》的编著体例，凡是鲁国国君都称公，后边《曹刿论战》等篇均如是。鲁国是姬姓国，其开国君主是周公旦之子伯禽，其地在今山东西南部。如：往。\n如：往。\n棠：也写作唐，鲁国邑名，在今山东鱼台县东。\n鱼：通“渔”，动词，捕鱼。\n臧僖伯：鲁孝公之子、鲁惠公之兄、鲁隐公之伯父，名彄（又作“驱”“弓区”）（kōu），字子臧，封于臧（今郯城县），伯为排行，僖是谥号。 丗本：孝公生僖伯彄，彄生哀伯达（臧哀伯或臧孙达），达生伯氏缾，缾生文仲辰（臧文仲），辰是臧僖伯曾孙。\n讲：讲习，训练。\n大事：指祭祀和军事活动等。\n材：材料，原料。\n器用：指祭祀所用的器具与军事物资。\n举：指行动。\n纳：纳入。\n轨物：法度和准则。\n度（duó）：衡量。\n量：程度。\n章：通“彰”，彰明，发扬。\n采：物之有华饰者又彩色也，五彩相间曰采。\n亟：多次，屡次。\n春蒐（sōu）：指春天打猎。蒐，搜寻，谓搜寻不产卵、未怀孕的禽兽。\n夏苗：指夏天打猎，谓捕猎伤害庄稼的禽兽。\n秋狝（xiǎn）：指秋天打猎。狝，杀，谓顺秋天肃杀之气，进行捕猎活动。\n冬狩（shòu）：指冬天打猎。狩，围守，谓冬天各种禽兽都已长成，可以不加选择地加以围猎。按：“春蒐、夏苗、秋狝、冬狩”云云，说明我们的先民在狩猎活动中已有生态平衡意识，也同时说明大凡有组织的狩猎活动，都带有军事演习的性质，并不单单是为狩猎而狩猎。\n治兵：指练兵、比武等军事演习活动。\n振旅：整顿部队。\n饮至：古代的一种礼仪活动。凡盟会、外交和重大军事行动结束以后，都要告于宗庙，并举行宴会予以庆贺。\n军实：指军用车辆、器物和战斗中的俘获等。\n昭：表明。文章：服饰、旌旗等的颜色花纹。\n登：装入，陈列。\n俎（zǔ）：古代举行祭祀活动时用以盛牛、羊等祭品的礼器。\n射：激矢及物曰射。\n山林：材木樵薪之类。\n川泽：菱芡鱼龟之类。\n资：材资也。\n皂（zào）隶：本指奴隶，这里指做各种杂务的仆役。\n略地：到外地巡视。\n陈：陈设，张设也。\n称疾：推说有病。（注意：古代分言“疾”和“病”，轻者为“疾”，重者为“病”。）\n书：指《春秋》。\n矢：通“施”，实施，陈设。这一句的意思是：隐公在棠陈列渔具。', poem_appreciation = '读罢此文，读者也许会提出这样的问题：鲁隐公作为一国之君，到棠地看看渔民怎样捕鱼，有什么了不得，也值得这位臧大夫大惊小怪，还要苦口婆心、掰开揉碎地讲那么多大道理?难道国君连这点自由也没有吗?马克思主义认为：分析、考察和认识任何一种历史现象，都必须把该历史现象放回到产生它的历史环境中去。臧僖伯之所以谏阻隐公到棠地观鱼，是因为隐公这一活动，不符合那个时代一个国君应该遵循并身体力行的行为规范。不符合，就会“乱政”；而屡屡“乱政”，就会导致国家的败亡。况且，隐公远离国都，到棠地观鱼，并非为了体察民情，更不是与民同乐，而仅仅是他本人的一种游乐活动。也正因为如此，他才不敢对臧僖伯的谏言说一个“不”字，最后不得不以“吾将略地焉”为借口,坚持到那里寻乐去。\n\n　　这篇谏辞的最大特点，是紧紧围绕着一个“礼”字展开劝谏，从观点到为阐明观点所举述的诸多理由及作为论据的事物和行为，都没有稍稍离开这个“礼”字。也就是说，没有稍稍离开制约当时国君行为的规范和准则。另一个也很明显的特点是,劝谏的缘起虽然是“公将如棠观鱼”，劝谏的直接目的也是阻止隐公“如棠观鱼”，但谏辞中对此事却不着一语。这不单单是婉言法，更重要的是，这种表达法反映出进谏者进谏的着眼点，并不在于隐公“如棠观鱼”这一具体行为，而是当时的整个礼制。如果隐公听了臧僖伯这番谏辞明白了“礼”对他的制约性，“如棠观鱼”这种“非礼”的事自然也就不会发生了。', poem_tags = '古文观止,劝谏' WHERE poem_title = '臧僖伯谏观鱼' AND poem_author = '左丘明';
UPDATE edu_poem SET poem_translation = '泰山不能损坏毫发，颜渊无意羡慕老聃和彭祖。\n松树活了一千年终究要死，槿木仅开花一天也自觉荣耀。\n何必眷恋尘世常怕死，也不要嫌弃而厌恶生活。\n生与死都是一种幻觉，梦幻人的悲哀欢乐又维系人间情呢。', poem_notes = '槿（jǐn）：即木槿花。开花时间较短，一般朝开暮落。\n嫌身：嫌弃自己。\n漫：随便。\n厌生：厌弃人生。', poem_tags = '哲理' WHERE poem_title = '放言五首·其五' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '创作背景 　　诗人是清末著名外交家黄遵宪，面对腐败的大清一而再，再而三的割地赔款尤其是甲午海战更是输给了东瀛小国，签订了《马关条约》再次割地，悲愤无比的黄遵宪写下这首传世名篇，但是他相信中华民族拥有精卫填海般的恒心一定会有收复国土的那天。', poem_appreciation = '《赠梁任父同年》这首诗是1896年黄遵宪邀请梁启超到上海办《时务报》时写给梁的一首诗。诗中表现了作者为国献身，变法图存的坚强决心和对梁启超的热切希望。\n\n　　诗题中梁任父即指梁启超，梁启超号任公，父是作者对梁的尊称，旧时“父”字是加在男子名号后面的美称。“同年”，旧时科举制度中，同一榜考中的人叫同年。\n\n　　首句“寸寸河山寸寸金”作者起笔便饱含深情的赞美作国的大好河山，蕴涵着对大好河山的珍爱之情。如果联系当时的历史背景我们又会体会出作者内心的几多痛楚，这么好的河山却被列强瓜分殆尽，此种局面又怎不让人扼腕叹息，痛恨。\n\n　　次句“侉离分裂力谁任”侉(kuǎ)离,这里是分割的意思，意指当时中国被列强瓜分的现实，面对着山河破碎，风雨飘摇的受灾受难的国家，作者不禁仰天长问：什么人才能担当起救国于危难之中的重任。一片爱国激情溢于言表。\n\n　　第三句“杜鹃再拜忧天泪”杜鹃，传说中古代蜀国的国王望帝所化。望帝把帝位传给丛帝，丛帝后来有点腐化堕落，望帝便和民众一起前去劝说丛帝，丛帝以为望帝回来夺取皇位，就紧闭城门，望帝没有办法，但他誓死也要劝丛帝回头，最后化成一只杜鹃进入城里，对着丛帝苦苦哀哀的叫，直到啼出血来死去为止。丛帝也因此受到感动，变成了一个爱民如子的好皇帝。据传说望帝始终在叫着这样的话“民为贵，民为贵”。这里是作者自比，表达了深切的忧国之情，表达了作者愿意为国家像杜鹃一样啼叫哀求，呼唤着国家栋梁之材，共同为国家出力。再拜，古代的一种礼节，先后拜两次，表示隆重，此处体现的是作者的拳拳爱国之心。\n\n　　最后一句“精卫无穷填海心”精卫，中国古代传说中的神鸟，本是炎帝的女儿，因游东海淹死在那里，灵魂便化为精卫鸟，不停的衔来西山之木石，誓把东海填平。后来用精卫填海这个典故作为力量虽然微弱，斗志却极坚强的象征。这句诗歌借精卫填海典故表达了自己，──同时也勉励梁氏──要像精卫那样，为挽救国家民族的危亡而鞠躬尽瘁，死而后已坚定决心。\n\n　　诵读此诗，觉字字含情，句句蕴泪，作者那一腔忧国报国之情，跃然纸上。其殷殷之心，皇天可鉴。', poem_tags = '爱国,忧国忧民' WHERE poem_title = '赠梁任父母同年 / 题梁任父同年' AND poem_author = '黄遵宪';
UPDATE edu_poem SET poem_translation = '寒冷的溪上飘满红色落叶，一路上山林寂静无人，树木整齐划一。试着登上小楼极目远眺，群山高低连绵。十里山坡，一片烟雾笼罩。\n狗吠声夹杂着鸡鸣，灯光闪烁，找不到回去的路。沿着横亘之山而行，忽远忽近，时东时西。家在秋冬的林木深处，正孤独地关着门儿。', poem_notes = '南乡子：词牌名，原为唐教坊曲。分单调、双调两体：单调二十七字，两平韵、两仄韵；双调五十六字，上下片各四平韵，亦有五十八字或五十四字。 \n寒溪：寒冷的溪流。\n齐：一致。这里意即秋天到了，万木都笼罩在一片肃杀的气氛中。 \n陂（bēi）：池塘、湖泊。\n荧（yíng）荧：灯光闪烁的样子。唐杜牧《阿房宫赋》： “明星荧荧，开妆镜也。”\n寒林：秋冬的林木。\n扉（fēi）：门。', poem_appreciation = '该词先叙去“村居”的路上所见：“红叶满寒溪，一路空山万木齐。”这也是《秋暮村居》的第一个画面：它由“红叶”、“寒溪”、“空山”和“万木”构成。接下来是《秋暮村居》的第二个画面，第二个画面形成了三个小层次：\n\n　　一、 “一片烟笼十里陂。”这里“陂”是一个关键词。 对这个词，注释者都解释为：“池塘”，或者是“积水，指池塘湖泊”。其实，这一句“望”的是远处，又是在“烟笼”的情境下“望”的，所以眼中的景象不是很分明：有池塘，有水边或者水岸，有山坡或者斜坡。这画面虽然很淡很淡，味道却是很浓很浓，同时也为下一个层次的推出，提供了极佳的背景。\n\n　　二、“吠犬杂鸣鸡，灯火荧荧归路迷。”这一句整合了陶渊明的“狗吠深巷中，鸡鸣桑树颠”两句。其中，“吠”、“鸣”声把词人从远处拉到了眼前：狗叫声和鸡叫声此起彼伏或者同时并发。但是这“鸡鸣狗吠”（或“鸡犬相闻”），并不是这种现实情状，词人可能更把它当乍一种情趣的寄托，一种精神的追求。\n\n　　三、“乍逐横山时近远，东西。家在寒林独掩扉。”在“相低昂”而悠悠的“钟梵”声里，目光又投向了“村居”的远山，可能由于那“一片烟”，也可能是视觉的灵动或者思绪的变幻，横着的远山竟然时而“近远”延缩，时而“东西”变换，可是那“在寒林”的人家，柴扉“独掩”，并没有随着远山的变幻而变换。这“东西”是“东方与西方”和“东边与西边”的空间方位，这个远山变幻而柴扉“独掩”层面的画意，令读者明白词人需要的就是“独掩”的与世隔绝那份淡定。\n\n　　把第二个画面细分为三个层面来抒写，来解读，这是为了抒写、解读的方便，其实这三个层面是有内在的逻辑性的：有次第展开的景随望而布的客观性，情感随景的变换而变幻的主观性，情景交融，浑然一体。第一个画面的情感基调是萧瑟、忧愁，而第二个画面则是淡雅、欣赏。这样是为了表达的别致而独特：要去“秋暮村居”就是为了闲适，路上所见却非如愿，是那么的萧瑟、忧愁，这是一变；登楼所望则由迷蒙开始，这是顺承，接着核心的“秋暮村居”图，终于得到了“吠犬杂鸣鸡”的陶式闲适，满足了预期的意愿，这是二变；再是从变幻的远山到柴扉“独掩”，这是第三变。\n\n　　全词以轻灵浑朴的笔调描绘出村野田园的风光情趣，读之犹如欣赏一幅优美安详，恬淡静谧的水墨山水画。景象由远及近，层次分明，动静相间，有声有色。其中洋溢着诗人陶然欣喜的情致，这在纳兰词中是少见的。尤其那点睛一般的双音节词语的巧妙运用更是让全篇风景霎时有了层次。于是一幅极具透视效果的风景画跃然纸上。', poem_tags = '秋天,田园,写景,写狗古诗18首' WHERE poem_title = '南乡子·秋暮村居' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_tags = '古诗三百首,咏物,写花,寓人' WHERE poem_title = '落花' AND poem_author = '宋祁';
UPDATE edu_poem SET poem_translation = '喝完饯别酒，友人们终于挥手别去，常常怨恨这种漂泊不定短暂虚浮的人生。回首看到如烟似雾的杨柳早已遮断视线。往前看去，风清云淡，孤雁远征。孤单的寒日傍晚天空一片酡红。\n今夜画船将停在什么地方？只怕夜间潮平水落，泊船岸边，一片清月迷漾。到酒消人也醒时，那种愁绪倍加难以排遣了。蜡烛残尽孤枕难眠；五更时轻风吹来激起点点浪花。', poem_notes = '饮散：饮完酒后离散。离亭：送别的驿亭。\n浮生：一生。古人谓“人生世上，虚浮无定”，故曰“浮生”。\n飘蓬（péng）：飘浮无定之意。\n重重（chóng chóng）：一层又一层，形容很多。\n暮（mù）天红：指傍晚天空一片酡红。\n画船：装饰华丽的船。多指游船。\n淮（huái）月：指照临淮水上空的月亮。\n朦胧（méng lóng）：模糊不清。\n奈：怎奈，奈何。\n孤枕（zhěn）梦：这里指孤枕难眠。\n五更风：指黎明前的寒风。', poem_appreciation = '上阕写的是离别后的情景，是实写。首两句直写别离，“散”、“离”、“去”已带怨意，而一个“恨”字则是直抒胸臆，又点明本词的主题，写出了词人内心的凄凉，羁旅之恨。且这恨又是“长恨”，这就道出了“饮散”“西去”对词人来说并非第一次了，每重演一次，就会增加一分身世飘零之恨。一个“长”字，使恨的情感深化了。第三句描绘的是词人一步三回头，不忍离去的情态，“烟柳渐重重”，既写出了离愁的层层加深，也写出了离愁的“有形”情态，衬托出了行人心头的迷惘。四、五两句描绘的是作者眼中的惨淡画面。“淡云”暗示行人心头的落寞，“孤雁”则是行人的化身；“寒日”显其心头之冷，“暮天红”虽是美景，但“夕阳无限好，只是近黄昏”，又充满了伤感。这两句极写浪迹飘零之苦，是移情于景。\n\n　　下阕都是词人想象中的情景。首句以问引起下文。“潮平淮月艨胧”暗示他那离别时的剧烈情绪已逐渐平静下来，可是心头却又一片迷惘。心里空虚只能借酒浇愁，可是在短暂的麻痹之后，还是要醒来，醒来时的静夜中心头却是更加空虚，更加愁苦难耐。词人通过气氛的渲染和景物的烘托，使内心的感伤之情与外在的空冷之景交融为一，传达出词人此时此地的冷寂情怀。“酒醒人静奈愁浓”，一旦酒醒，回到现实，只能更增愁情，不是三杯两盏淡酒就冲刷得掉的。一个“奈”字，突出了词人万般无奈的苦闷心情。末两句“残灯孤枕梦，轻浪五更风”描绘的是一幅多么凄凉可怕的景象。灯里的油就要燃尽，灯火忽明忽暗；一个人躺在枕头上，没有人陪伴，想入睡做个梦都不可得；五更时的寒风吹来更是倍增寒意。而从“潮平”到“残灯”再到“五更”，足见行人一夜未睡，“愁浓”之情不虚，此情此景，人何以堪。\n\n　　全词最为独特之处当在下阕，在于虚境实写，化虚为实，而又虚中浸实，写尽羁旅之情，含蓄隽永，耐人寻味。词人巧妙地融情与景为一体，写离愁却很少直接抒情，而是借助于外在的景物来表现词人内心的离愁别恨。词人沿情布景，景物的转承和变换、环境气氛的渲染和烘托，处处反衬出词人的内心世界。', poem_tags = '宋词三百首,婉约,孤独,写景' WHERE poem_title = '临江仙·饮散离亭西去' AND poem_author = '徐昌图';
UPDATE edu_poem SET poem_translation = '梁甫吟啊梁甫吟，自从诸葛亮唱响以来，多少志士吟颂过你，心中期盼着事业的春天。你知道周朝居住在棘津的姜太公吗？七十岁的人了，清晨即起，边屠牛时边唱歌，为了做一番大事业，辞别故乡来到长安边的渭水河边，用直钩钓了十年鱼。\n　　清澈的河水映照着他的白发，刺痛了他的心。当风云际会的时候，当文王来拜师的时候，那是气如东海，势比泰山，治国方略，那是一套一套的，小人们，别小看我现在普通人一个，机会来临，小猫也变大老虎！\n　　你知道秦末汉初居住高阳的酒鬼俪食其吗？六十多岁了，草莽出身，见了刘邦硬是不跪拜，做个长揖就算给足面子了！一阵雄辩就折服了他，让刘邦立即停止洗脚，马上放弃美女的按摩！改为洗耳恭听了。你看他就凭三寸不烂之舌，就攻下了齐国七十二座城市。把刘邦和项羽玩得象呼啦圈一样的转啊转！你看看，他那样的落泊之知识分子还云开雾散大干了一番，何况我身强力壮，智勇双全！\n　　我胸有治国大略，我必须为国家担忧，我想见皇上！可是皇上在干什么呢？鼓声敲得震天响，皇上和宫女贵妃们做投壶的游戏忙又忙！一脸的牙齿笑得多灿烂。可是宫墙外已经危机四起，安禄山准备反叛，这些事情皇上你知道吗？可是你周围的人却不容许我警告你，还责怪我打扰了你的雅兴。说我是杞国之人无事担忧天倾塌。白日啊，你整天被乌云蒙蔽着啊，你怎么可以照到我忠诚忧国的心肠？\n　　现在各地的军阀官僚一个个如同吃人的野兽——猰貐，阴险残暴。我却是驺虞样的猛虎，羞与合流，目前形势危险如同焦原——周围深渊高千丈而方圆才几十米，我却可以象姜太公和俪食其一样，斡旋处置游刃有余。别看他们力可拔山的外表，我要去除他们却只需要两三个桃子，知道晏婴杀公孙接、田开疆，古冶子等三人的故事吗？其关键是要利用他们之间的矛盾，别硬碰硬的乱整。我可是去探过安禄山的虚实，他手下根本没有象剧孟一样的智谋之士，匹夫一个，根本成不了什么大事。\n　　梁甫吟啊梁甫吟，心事重啊声音悲，古之名剑——干将和莫邪什么时候可以相合呢？那时候就会天下无敌，我什么时候才可以与皇上风云际会呢？那时候天下将平安无事。等待吧，安心地等待，等待最好的时机！', poem_notes = '长啸：吟唱。\n朝歌屠叟：指吕尚（即吕望、姜太公）。《战国策·秦策三》：“臣（范雎）闻始时吕尚之遇文王也，身为渔父而钓于渭阳之滨耳。”又《秦策五》：“太公望，齐之逐夫，朝歌之废屠。”《韩诗外传》卷七：“吕望行年五十，卖食棘津，年七十屠于朝歌，九十乃为天子师，则遇文王也。”又《韩诗外传》：“太公望……屠牛朝歌，赁于棘津，钓于磻溪，文王举而用之，封于齐。”\n经纶：《易经·屯卦》：“君子以经纶。”经纶：喻治理国家。\n三千六百钓：指吕尚在渭河边垂钓十年，共三千六百日。风期：风度和谋略。\n大贤：指吕尚。虎变：《易经·革卦》九五：“大人虎变。”喻大人物行为变化莫测，骤然得志，非常人所能料。\n高阳酒徒：西汉人骊食其。《史记·骊生陆贾列传》：“骊生食其者，陈留高阳人也。好读书，家贫落魄，无以为衣食业，为里监门吏。然县中贤豪不敢役，县中皆谓之狂生。……沛公至高阳传舍，使人召骊生。骊生至，入谒，沛公方倨床使两女子洗足，而见骊生。骊生入，则长揖不拜。”骊生尝自称高阳酒徒。隆准：高鼻子。隆准公：指刘邦。《史记·高祖本纪》：“高祖为人，隆准而龙颜。”趋风：疾行如风前来迎接。《史记·骊生陆贾列传》载：楚、汉在荥阳、成皋一带相持，骊生建议刘邦联齐孤立项羽。他受命到齐国游说，齐王田广表示愿以所辖七十余城归汉。\n旋蓬：在空中飘旋的蓬草。狂客：指骊食其。\n攀龙：《后汉书·光武帝纪》：耿纯对刘秀说：“天下士大夫所以跟随大王南征北战，本来是希望攀龙鳞，附凤翼，以成就功名。”后人因以攀龙附凤比喻依附帝王建立功业。\n雷公：传说中的雷神。砰訇：形容声音宏大。\n帝旁投壶多玉女：《神异经·东荒经》载：东王公常与一玉女玩投壶的游戏，每次投一千二百支，不中则天为之笑。天笑时，流火闪耀，即为闪电。三时：早、午、晚。倏烁：电光闪耀。晦冥：昏暗。这两句暗指皇帝整天寻欢作乐，权奸和宦官弄权，朝廷政令无常。\n阊阖：神话中的天门。阍者：看守天门的人。《离骚》：“吾令帝阍开关兮，倚阊阖而望予。”这两句指唐玄宗昏庸无道，宠信奸佞，使有才能的人报国无门。\n杞国无事忧天倾：《列子·天瑞》：“杞国有人忧天地崩坠，身亡所寄，废寝食者。”二句意谓皇帝不理解我，还以为我是杞人忧天。此自嘲之意。\n⒀猰貐：古代神话中一种吃人的野兽。这里比喻阴险凶恶的人物。竞人肉：争吃人肉。驺虞：古代神话中一种仁兽，白质黑纹，不伤人畜，不践踏生草。这里李白以驺虞自比，表示不与奸人同流合污。\n接：搏斗。飞揉、雕虎：比喻凶险之人。焦原：传说春秋时莒国有一块约五十步方圆的大石，名叫焦原，下有百丈深渊，只有无畏的人才敢站上去。\n智者二句：智者可忍一时之屈，而愚者只知一味骄横。世俗人看不起我。\n力排二句：《晏子春秋》内篇卷二《谏》下载：齐景公手下有公孙接、田开疆、古冶子三勇士，皆力能搏虎，却不知礼义。相国晏婴便向齐景公建议除掉他们。他建议景公用两只桃子赏给有功之人。于是三勇士争功，然后又各自羞愧自杀。李白用此典意在讽刺当时权相李林甫陷害韦坚、李邕、裴敦复等大臣。\n吴楚句：汉景帝时，吴楚等七国诸侯王起兵反汉。景帝派大将周亚夫领兵讨伐。周到河南见到剧孟（著名侠士），高兴地说：吴楚叛汉，却不用剧孟，注定要失败。咍尔：讥笑。\n张公：指西晋张华。据《晋书·张华传》载：西晋时丰城（今江西省丰城）县令雷焕掘地得双剑，即古代名剑干将和莫邪。雷把干将送给张华，自己留下莫邪。后来张华被杀，干将失落。雷焕死后，他的儿子雷华有一天佩带着莫邪经过延平律（今福建南平市东），突然，剑从腰间跳进水中，与早已在水中的干将会合，化作两条蛟龙。这两句用典，意谓总有一天自己会得到明君赏识。\n风云感会：即风云际会。古人认为云从龙，风从虎，常以风云际会形容君臣相得，成就大业。大人：有才干的人。□（左山右皃）屼：不安。此指暂遇坎坷。', poem_appreciation = '李白这首也有“力排南山三壮士，齐相杀之费二桃”之句，显然是袭用了诸葛亮那首的立意。诗大概写在李白“赐金放还”，刚离开长安之后。诗中抒写遭受挫折以后的痛苦和对理想的期待，气势奔放，感情炽热，是李白的代表作之一。\n\n　　开头两句：“长啸梁甫吟，何时见阳春？”“长啸”是比高歌更为凄厉激越的感情抒发。诗一上来就单刀直入，显示诗人此时心情极不平静，为全诗定下了感情的基调。宋玉《九辩》中有“恐溘死而不得见乎阳春”之句，故“见阳春”有从埋没中得到重用、从压抑中得以施展抱负的意思。以下诗句，全是由此生发。\n\n　　接着，连用两组“君不见”提出两个历史故事。一是说西周吕望（即姜太公）长期埋没民间，五十岁在棘津当小贩，七十岁在朝歌当屠夫，八十岁时还垂钓于渭水之滨，钓了十年（每天一钓，十年共三千六百钓），才得遇文王，遂展平生之志。一是说秦末的郦食其，刘邦原把他当作一个平常儒生，看不起他，但这位自称“高阳酒徒”的儒生，不仅凭雄辩使刘邦改变了态度，以后还说服齐王率七十二城降汉，成为楚汉相争中的风云人物。诗人引用这两个历史故事，实际上寄寓着自己的理想与抱负：“大贤虎变愚不测，当年颇似平常人”，“狂客落魄尚如此，何况壮士当群雄”。他不相信自己会长期沦落，毫无作为。诗人对前途有着坚定的信念，所以这里声调高亢昂扬，语言节奏也较爽利明快，中间虽曾换过一次韵，但都押平声韵，语气还是舒展平坦的。\n\n　　自“我欲攀龙见明主”句起，诗人一下子从乐观陷入了痛苦。加上改用了仄声韵，语气拗怒急促，更使人感到犹如一阵凄风急雨劈面打来。这一段写法上很象屈原的《离骚》，诗人使自己置身于惝恍迷离、奇幻多变的神话境界中，通过描写奇特的遭遇来反映对现实生活的感受。你看，他为了求见“明主”，依附着夭矫的飞龙来到天上。可是，凶恶的雷公擂起天鼓，用震耳欲聋的鼓声来恐吓他，他想求见的那位“明主”，也只顾同一班女宠作投壶的游戏。他们高兴得大笑时天上闪现出耀眼的电光，一时恼怒又使天地昏暗，风雨交加。尽管如此，诗人还是不顾一切以额叩关，冒死求见。不料竟触怒了守卫天门的阍者。在这段描写中，诗人的感情表现得那么强烈，就象浩荡江水从宽广的河床突然进入峡谷险滩一样，旋涡四起，奔腾湍急，不可抑止。诗人在天国的遭遇，实际上就是在现实生活中的遭遇，他借助于幻设的神话境界，尽情倾诉了胸中的忿懑与不平。\n\n　　自“白日不照吾精诚”以下十二句又另作一段，在这段中，诗人通过各种典故或明或暗地抒写了内心的忧虑和痛苦，并激烈地抨击了现实生活中的不合理现象：上皇不能体察我对国家的一片精诚，反说我是“杞人忧天”。权奸们象恶兽猰?那样磨牙厉齿残害人民，而诗人的理想则是以仁政治天下。他自信有足够的才能和勇气去整顿乾坤，就象古代能用左手接飞猱、右手搏雕虎的勇士那样，虽置身于危险的焦原仍不以为苦。诗意象是宕起，可是马上又重重地跌了下来。在现实的生活中，只有庸碌之辈可以趾高气扬，真有才能的人反而只能收起自己的聪明才智，世人就把我看得轻如鸿毛。古代齐国三个力能排山的勇士被相国晏子设计害死，可见有才能的人往往受到猜疑。明明有剧孟这样的能人而摒弃不用，国家的前途真是不堪设想了。这一段行文的显著特点是句子的排列突破了常规。如果要求意思连贯，那么“手接飞猱”两句之后，应接写“力排南山”两句，“智者可卷”两句之后，应接写“吴楚弄兵”两句。可是诗人却故意把它们作上下错落的排列，避免了平铺直叙。诗人那股汹涌而来的感情激流，至此一波三折，成迂回盘旋之势，更显得恣肆奇横，笔力雄健。这段的语气节奏也随着感情发展而跌宕起伏，忽而急促，忽而舒展，忽而押平声韵，忽而换仄声韵，短短十二句竟三易其韵，极尽变化之能事。\n\n　　最后一段开头，“梁甫吟，声正悲”，直接呼应篇首两句，语气沉痛而悲怆。突然，诗人又笔锋一折，“张公两龙剑”以下四句仍是信心百倍地回答了“何时见阳春”这一设问。诗人确信，正如干将、莫邪二剑不会久没尘土，我同“明主”一时为小人阻隔，终当有会合之时。既然做过屠夫和钓徒的吕望最后仍能际会风云，建立功勋，那自己也就应该安时俟命，等待风云感会的一天到来。饱经挫折的诗人虽然沉浸在迷惘和痛苦之中，却仍在用各种办法自我慰藉，始终没有放弃对理想的追求。\n\n　　写长篇歌行最忌呆滞平板，这首诗最大的艺术特色正在于布局奇特，变化莫测。它通篇用典，但表现手法却不时变换。吕望和郦食其两个故事是正面描写，起“以古为鉴”的作用，接着借助于种种神话故事，寄寓自己的痛苦遭遇，第三段则把几个不相连属的典故交织在一起，正如清人沈德潜说的“后半拉杂使事，而不见其迹”，因而诗的意境显得奇幻多姿，错落有致：它时而和风丽日，春意盎然，时而浊浪翻滚，险象纷呈；时而语浅意深，明白如话，时而杳冥惝恍，深不可测。加上语言节奏的不断变化起伏，诗人强烈而又复杂的思想感情表现得淋漓尽致。', poem_tags = '咏史怀古,写人,典故,抒情' WHERE poem_title = '梁甫吟' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '挟来阵阵寒意的水浪，也有些心事重重；只有西去的阳光，投下惨淡的影子，渐渐地消失；南面的水岸是我送别的地方，你走了，一阵阵萧索的风，带来易水上的苍凉。那风呵，又吹起来了，吹起河岸上的柳。受尽霜冻的柳枝啊，落下最后一片黄叶，影子是这样的孤单。还记得吗，还得那飞絮如雪的时候？我久久瞭望你远去的帆影，直到夜幕降临，浪花飘起来了，是茫茫的烟雾，迷糊了最后一抹夕阳。只有那孤苦柳树，迎来匆忙的过客，扭动着瘦弱的腰身，好象要轻轻地舞动。\n春天里，我们彼此相爱，却在这寒冷的秋季，催生出无数相思的落泪。回忆起携手并肩时的亲密，那份感伤，就象无数的细绳把我的心捆扎。笙歌劲舞的画舫，依然绕着河岸缓缓地移动，可是我的心里却是这样的冷落，水在流，云还是那样地飘，只不知道心上的人儿，你在何处。想着那些相恋的日子，如同一阵吹来的东风，可是那是多么微弱风呵，吹不进重叠的窗帘，只是让这一份相思深深地刻在我的眉间。我只能等待那个梅花的精灵，在夜阑人静的时候，在月淡星稀的时候，我对她说出自己心中的苦闷，让她传达我对你深深的思念。', poem_notes = '金明池：词牌名，秦观创调，词咏汴京金明池，故取以为名。\n怅：失意，懊恼。\n萧萧：风声，草木经风摇落之声。\n霜条：经霜的树枝条。\n旧时飞絮：化用刘禹锡《杨柳枝词》九首之九：“春尽絮飞留不得，随风好去落谁家”。\n晚来：夜晚来临之际。\n行客：来往的行旅客人。\n燕台佳句：燕台，又指燕昭王延揽天下贤士的黄金台。柳氏此处喻指几社文人雅集赋诗的地方。\n春日酿成秋日雨：指当年几社名流与柳氏交游，曾为她作春闺风雨的艳词，竞成为今日飘零秋雨的预兆。\n畴昔：过去，以前。\n如许：如此，此为概指之辞。\n绕堤画舸：化用汤显祖《紫钗记》中“河桥路，见了些无情画舸，有恨香车”句意。\n忆从前：“忆”，回忆。此为回忆从前那些相恋的时光。\n眉儿愁苦：陆游《钗头凤》：“一杯愁绪，几年离索”，表现词人怀念恋人，柔肠寸断的心绪。\n梅魂：化用苏轼《复出东门诗》：“长与东风约今日，暗香先返玉梅魂。”\n伊：彼，他或她。', poem_tags = '咏物,柳树,寓人,爱情' WHERE poem_title = '金明池·咏寒柳' AND poem_author = '柳如是';
UPDATE edu_poem SET poem_translation = '大雪粉白光华，像飞舞的梨花，遮住了郊野三三两两的农家。雪花密密层层的漂洒堪描堪画。看那稀疏的树林上鸣叫着晚归的寒鸦。一条钓鱼的小船正斜揽在枯黄芦苇掩映的清江下。', poem_notes = '双调：宫调名。大德歌：曲牌名。\n华：光彩、光辉。\n黄芦：枯黄的芦苇。\n艖（chā）：小船。', poem_tags = '冬天,写景,向往,闲适,生活' WHERE poem_title = '大德歌·冬景' AND poem_author = '关汉卿';
UPDATE edu_poem SET poem_translation = '译文 　　小路可真是细长！高桥不用倚扶吗?远处山上的枫叶朦胧色淡，麦田边的小屋显得很孤独。野草一夜间又随风生长出来，刚过一年的小路就消失了。清明后梨花会生长，到这个季节我很思念你。', poem_tags = '寒食节,写景,思念' WHERE poem_title = '寒食上冢' AND poem_author = '杨万里';
UPDATE edu_poem SET poem_translation = '春色将尽，莺声燕语渐渐不闻，满地落花堆积，稀疏的青梅斜挂枝头，眼见到了春末夏初了。濛濛细雨中，一个消瘦的女子静静地独立在画阁外，眼前的屏风半掩着厅堂，惟见缕缕沉香从屏风后袅袅散来，更添了几分幽幽的心事。\n遥想当年依依惜别时的深情约定啊。如今一别经年，依然杳无音讯，可晓得我这份断肠的思念吗？妆奁久未开，菱饰尘灰满，眼下竟然连照镜的心都懒了。只是落寞地倚在栏杆上，心下纵有万语千言，却又向谁人说起？惟有无语凝噎，暗自销魂罢了。天空灰蒙蒙的，黯然地衔着绵绵不尽的芳草，一如我的思念。', poem_notes = '踏莎（suō）行：词牌名。又名“柳长春”“喜朝天”等。双调五十八字，仄韵。\n阑（lán）：残，尽，晚。\n红英：红花。南唐李煜《采桑子》词：“亭前春逐红英尽。”\n屏山：指屏风。唐温庭筠《南歌子》词：“扑蕊添黄子，呵花满翠鬟，鸳枕映屏山。”\n密约：指男女之间互诉衷情，暗约佳期。沉沉：深沉。此指重大之事，即终身之事。\n杳（yǎo）杳：深远无边际。\n菱花：指菱花镜，亦泛指镜子。慵（yōng）将照：懒得拿起镜子来照。慵：懒散。将：拿。\n销魂：形容极度伤心。', poem_tags = '宋词三百首,宋词精选,婉约,闺怨,伤春,思念' WHERE poem_title = '踏莎行·春暮' AND poem_author = '寇准';
UPDATE edu_poem SET poem_translation = '注释 ⑴岁正月：公元822年（唐穆宗长庆二年）正月。公元821年（长庆元年）冬，刘禹锡被任为夔州（今重庆市奉节县）刺史，大约到任时已是次年正月。 ⑵建平：郡名，三国吴置，隋改为巫山县（参见《隋书·地理志》上巴东郡），今属重庆市。此当指夔州。 ⑶睢：仰视。 ⑷激讦：激越清脆。吴声：吴地的乐歌。 ⑸伧儜不可分：听不太懂。 ⑹淇、濮：周代卫国（今河南省内）的两条水名。《诗经》多处咏及。《汉书·地理志》下：“卫地……有桑间濮上之阻，男女亦亟聚会，声色生焉，故俗称郑卫之音。”此以淇濮之艳代指情歌，意谓巴渝民歌亦多涉男女爱情。 ⑺俾：使。巴歈：巴即巴郡，约当现在重庆一带。歈即民歌。变风：《毛诗序》：“至于王道衰，礼义废，政教失，国异政，家殊俗，而变风变雅作矣。”后人对变风变雅的解说很多，大意是说太平盛世产生的风、雅之诗是正风正雅；而乱世产生的诗歌则失去了雅正平和之气，故称变风、变雅。刘禹锡此处使用变风一词，似乎并非强调世事之治乱，而是侧重于体察民俗风情之意。 ⑻白帝城：在今重庆市奉节县东白帝山上，下临瞿塘峡口之夔门。东汉初公孙述筑城。述自号白帝，因名。三国时刘备为吴将陆逊所败，退居于此，卒于城中永安宫。 ⑼山桃：野桃。上头：山头，山顶上。 ⑽瀼西：今重庆奉节瀼水西岸。陆游《入蜀记》：“土人谓山间之流通江者曰瀼。”縠文：水波纹。 ⑾兰桡：兰木桨。兰指木兰树，又名杜兰、林兰。但古诗、文中常说兰舟、兰桨、兰桡等，只是一种美称，不一定都是兰木所作。如屈原《九歌·湘君》：“桂棹兮兰枻，斫冰兮积雪。”苏轼《前赤壁赋》：“桂棹兮兰桨，击空明兮溯流光。”亦本自屈原。 ⑿永安宫：故址在今重庆奉节县城内。公元222年，蜀先主刘备自猇亭战败后，驻军白帝城，建此宫，次年卒于此。 ⒀城西门：此当指奉节城西门。滟滪堆：原是瞿塘峡口江中的大石（今已炸去），亦作“淫预堆”“犹豫堆”“英武石”“燕窝石”等。 ⒁瞿塘：瞿塘峡，在重庆奉节县。嘈嘈：水的急流声。 ⒂巫峡：在重庆巫山县东，湖北省巴东县西。 ⒃银钏二句：描写戴着银钏金钗的妇女们到江边汲水；持长刀披短笠的男子到山上开荒种田。 ▲', poem_tags = '组诗,民歌,爱情,生活,山川,景物,风土,人情' WHERE poem_title = '竹枝词九首' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_translation = '我很久没有画我的柳叶眉了，面上的残妆和著眼泪打湿了我的红绡衣。\n我自是很久没有梳洗过了，你也不必送一斛珍珠来安慰我的寂寥之心。', poem_notes = '红绡：红色薄绸\n寂寥：寂寞空虚。', poem_tags = '女子,宫怨,思念' WHERE poem_title = '谢赐珍珠' AND poem_author = '江采萍';
UPDATE edu_poem SET poem_translation = '墙上长满了蒺藜，无论如何扫不掉。你们宫中私房话，实在没法说出口。如果真要说出来，那话就难听死啦。\n墙上长满了蒺藜，无论如何除不掉。你们宫中私房话，实在没法详细说。如果真要说详细，那话说来可长啦。\n墙上长满了蒺藜，没有办法打捆走。你们宫中私房话，实在不能对人说。如果真的传开来，简直就是羞辱啊。', poem_notes = '鄘（yōng）：中国周代诸侯国名，在今河南省汲县北。\n茨（cí）：植物名，蒺藜。一年生草本植物，果实有刺。\n埽（sǎo）：同‘’扫‘’。\n中冓（gòu）：内室，宫中龌龊之事。\n道：说。\n所：若。\n襄：除去，扫除。\n详：借作“扬”，传扬。\n束：捆走。这里是打扫干净的意思。\n读：宣扬。', poem_tags = '诗经' WHERE poem_title = '国风·鄘风·墙有茨' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '作为将领的原则，应当首先修养心性。必须做到泰山在眼前崩塌而面不改色，麋鹿在身边奔突而不眨眼睛，然后才能够控制利害因素，才可以对付敌人。\n　　军事崇尚正义。如果不合乎正义，即使有利可图也不要行动。并非一动就有危害，而是因为后来将有不能应付的事情发生。只有正义能够激愤士气，用正义激愤士气，就可以投入一切战斗。\n　　作战的措施大致是：当战争尚未发生的时候，要积蓄财力；当战争即将发生的时候，要培养战斗力；当战争已经打起来的时候，要培养士气；当战争已经取得胜利的时候，就要修养心性。小心谨慎地设置报警的烽火，严格认真地在边境巡逻放哨，使农民无所顾忌，安心耕种，这就是积蓄财力的做法。用丰盛的酒食等物慰劳战士，让他们悠闲自在，养精蓄锐，这就是培养战斗力的做法。取得小的胜利，要使战士感到更加紧迫；受到小的挫折，要让战士得到更大的激励，这就是培养士气的做法。使用战士要注意不让他们完全实现自己的欲望，这就是修养心性的做法。所以战士们常常积蓄着怒气，心中怀有欲望却不能完全实现。怒气没有消除干净就有余勇可贾，欲望没有完全实现就将继续追求，所以即使吞并了天下，战士也不厌恶打仗。这就是黄帝的军队经历了七十次战斗也不懈怠的原因。如果不修养心性，战士们打了一次胜仗后就不能继续作战了。\n　　将领要聪明而严厉，战士要愚昧。聪明就不可预测，严厉就不可冒犯，所以战士们都把自身完全交出来听从命令，怎么能不愚昧呢?惟其战士愚昧，然后才能跟他们一道舍生忘死。\n　　大凡出动军队，要了解敌方的君主，了解敌方的将领，然后才能够在危险的地方出兵。魏将邓艾率兵伐蜀汉，从阴平小道行无人之地七百余里，用绳子拴着士兵从山上坠下深谷，如果不是蜀汉后主刘禅昏庸无能，那么百万大军也可以坐而捆绑擒获。邓艾本来就对刘禅轻慢，所以才出兵于危险之地。因此，古代的良将，能用大军去试探敌人的强弱、虚实，同时也用敌人的反应来衡量自己，这样就可以决定行动方针了。\n　　作为主将的原则是：明白道理然后可以出兵，了解形势然后可以增兵，懂得节制然后可以用兵。明白道理就不会屈服，了解形势就不会丧气，懂得节制就不会困窘。见了小利益不轻举妄动，遇上小祸难不回避。小利益、小祸难不值得辱没我的本领，然后才能够应付大利益、大祸难。只有善于蓄养本领又爱惜自己军队的人，才无敌于天下。所以一忍可以抵御百勇，一静可以控制百动。\n　　军队自有长处和短处，无论敌我都如此。请问：我方的长处，我拿出来运用，敌人却不与我较量；我方的短处，我隐蔽起来，敌人却竭力与我对抗，怎么办呢?回答道：我方的短处，我故意显露出来，使敌人心生疑虑而退却；我方的长处，我暗中隐蔽起来，使敌人轻慢而陷人圈套。这就是灵活运用自己的长处和短处的方法。\n　　善于用兵打仗的人，要使战士们没有什么顾忌但有所依靠。战士们没有什么顾忌，就知道牺牲了也不值得可惜；有所依靠，就知道不至于一定失败。手握一尺长的鞭子，面对着猛虎，敢于奋力呐喊而挥鞭打击；空着手遇上了蜥蜴，也会吓得面容变色连连后退，这是人之常情。懂得这个道理，就可以带兵了。假如赤身露臂但手握着剑，那大力士乌获也不敢逼近；要是头戴着盔，身穿铠甲，靠着武器而睡觉，那小童也敢弯弓射杀了。所以善于用兵打仗的人，利用各种条件来巩固自己；能够利用各种条件来巩固自己，那就威力无穷了。', poem_notes = '治心：指锻炼培养军事上的胆略、意志和吃苦的精神等。\n麋：麋鹿，鹿类的一种。\n左：附近。\n瞬：眨眼。\n制：掌握\n上：通“尚”，崇尚。\n怒：激发\n烽燧：即烽火，古代边防报警的信号。白天放烟叫“烽”，夜间燃火叫“燧”。\n斥堠：古代用来瞭望敌情的土堡，这里指放哨、瞭望。\n犒：犒赏，旧指用酒食或财物慰劳将士。\n优游：闲暇自得的样子。\n挫：挫折，这里指打了败仗。\n厉：激励。并天下：兼并天下。\n黄帝：传说中我国中原各族的共同祖先。相传曾在战争中多次取胜，打败了炎帝、蚩尤，成为部落联盟的领袖。\n殆：通“怠”，懈怠。\n智：有智慧。\n严：有威严。\n欲：应该。\n委：委屈。\n邓艾缒兵于蜀中：邓艾，三国时魏国的将领，魏元帝景元四年（263年），他率兵从一条艰险的山路进攻蜀汉，山高谷深，士兵都用绳子系着放下山去，邓艾自己也用毡布裹着身体，滑下山去。缒，系在绳子上放下去。\n刘禅：三国时蜀后主，小名阿斗，刘备之子，公元223年至263年在位。\n侮：轻视、轻侮。\n尝：试探，检验。\n节：节制。\n沮：沮丧。\n辱：玷污。\n技：本领。\n支：经得起，对付得了。\n校：较量。\n角：角斗。\n抗：高，引申为突出地。\n暴：显露。却：退。\n狎：轻忽。\n堕：落。\n蜥蜴：一种爬行动物，形似壁虎，俗称“四脚蛇”。\n袒裼：脱衣露体。\n乌获：战国时秦国的大力士，相传能力举千钧。\n冠胄衣甲：戴着头盔，穿着铠甲。胄，盔。冠、衣，都用作动词。\n据兵：靠着兵器。\n以形固：指利用各种有利形势来巩固自己。以，凭借，利用。形，各种有利的形式和条件。固，巩固。', poem_tags = '古文观止,议论,用兵' WHERE poem_title = '心术' AND poem_author = '苏洵';
UPDATE edu_poem SET poem_translation = '潇湘的静夜里，清风吹拂着秋天的荻花，橘子洲头的美景，宛如屏上的山水画。浩淼的烟波中，皎洁的月光下，我收拢钓鱼的丝线，摇起小船回家。\n绿水就是我的家园，船篷就是我的屋舍，山珍海味也难胜过我每日三餐的糙米鱼虾。面对盈杯的水酒，望着诗书满架，我已心满意足，再不用将名利牵挂。', poem_notes = '渔歌子：词牌名。原唐教坊曲名，后成为词牌名。单调二十七字，四平韵。中间三言两句，例用对偶。\n荻（dí）：多年生草本植物，秋季抽生草黄色扇形圆锥花序，生长在路边和水旁。\n潇湘：两水名，今湖南境内。《山海经》：“潇水，源出九巅山，湘水，源出海阳山。至零陵合流而于洞庭也。”\n橘洲：在长沙市境内湘江中，又名下洲，旧时多橘，故又称“橘子洲”。《水经注·湘水》：“湘水又北经南津城西，西对橘洲。”\n垂纶（lún）：垂钓。纶，较粗的丝线，常指钓鱼线。\n篷：船帆，此处代指船。\n“名利”句：即心不将名利牵挂。', poem_appreciation = '这首词主要描写了词人的隐逸生活。\n\n　　上片写景。开头三句点明时间、地点，是地处潇湘的橘子洲的秋夜，荻花临风，美景如画。“碧烟中”三句，将镜头渐次拉近，月光下的江水，轻柔澄碧，云烟淡淡，词中主人公刚刚垂钓完毕，划着小艇在水上荡漾。真是如诗如画，如梦如幻。\n\n　　下片写人事，主要写词人的隐逸生活及其乐趣。隐在民间，云水就是家乡，蓬舍就是住所，经常吃的是家常的鱼羹稻米饭。杯中斟满美酒，架上摆满书籍，开怀惬意，其乐陶陶，绝不把名利挂在心上。\n\n　　词人淡淡地写景，不事雕琢，明白如话，把一个一个远离名利，以隐逸为乐的词人的内心活动真实地展示出来，旷达超脱，余韵悠悠，受中唐张志和《渔父》词的影响颇大。', poem_tags = '秋天,写景,归隐' WHERE poem_title = '渔歌子·荻花秋' AND poem_author = '李珣';
UPDATE edu_poem SET poem_translation = '译文 整个春日大概都没有连续十天清明无雨的日子，到处都是在天上的云彩携带着雨水漂浮而行。 野外田里的一潭绿油油的春水比镜子还要碧绿光亮，古渡口边人经过时水边的鸥鹭却自在不受惊吓。 篱笆外将开未开的桃花探头伸出，看上去是如此嫣然含情。 草屋边烟雨靡靡，打湿了行客的衣裳，午后鸡鸣一声将人从闲梦中唤引回了现实。', poem_tags = '古诗三百首,咏物,写花,寓人' WHERE poem_title = '春日' AND poem_author = '汪藻';
UPDATE edu_poem SET poem_translation = '斟满淡绿色的美酒，请您再住几日，不要就这样匆匆离去。剩下的三分春色，二分都是离愁别绪，一分又充满了凄风苦雨。\n年年都见花开花谢，相思之情又有多少呢？就让我们高歌畅饮，不要谈论伤感之事。明年牡丹盛开的时候，不知我们会在哪里相逢？', poem_notes = '贺圣朝：唐教坊曲名，后用为词牌。《花间集》有欧阳炯词，本名“贺明朝”，《词律》混入“贺圣朝”，误。有十余种格式。此词格式为：双调四十九字，仄韵格，上片四句三仄韵，下片五句三仄韵。\n绿醑（xǔ）：即绿色的美酒。\n几许：犹言多少。', poem_appreciation = '这首词大约是作者北宋首都汴京留别友人之作。全词以别易会难为主旨，上片写留饮，下片写惜别。\n\n　　开篇写作者满斟绿色的美酒，劝友人暂留，且不要匆匆归去。继而，词中又写作者纵酒高歌，劝友人钧，切切絮絮倾诉离情。这里，用春色、离愁、风雨，构成了一幅离别图：阳春佳月，风雨凄凄，离愁万绪，为下片抒情作了有力的铺垫。“三分春色二分愁，更一分风雨”，虽然还是以词家习惯运用的情景交融的手法来描写离愁，但设想奇特，不落俗套，给人以新颖巧妙的感觉。词人设想“春色”总体为“三分”，而其中的“二分”是“愁”，“一分”是“风雨”。这样，此时此刻的“春色”就成了“愁”与“风雨”的集合体。而此处的“风雨”，只是表象，实质上是明写风雨暗写愁。\n\n　　这里写“风雨”，用的就是这种以景写情的笔法。所谓三分春色实际上都是愁。词人用全部的春色来写与挚友分手时的离愁别绪，其友情之深，离别之难，不言而喻。作者用笔，貌轻实重，饱和了作者的全部感情，确实是情景交融、情深意长。苏轼著名的《水龙吟》（次韵章质夫杨花词）有句云：“春色三分，二分尘土，一分流水。”大约即是从此处脱胎。\n\n　　上片，由举杯挽留写到离别情怀，由外部行动而至内心感情，多为顺笔。下片则转折颇多。过片“花开”两句，紧承上片的离愁别绪，并进一步预写别后的相思。“花开”句，用韩偓《谪仙怨》“花开花谢相思”句意，但作者只写“花开花谢”而不说“相思”，实际上“相思”已包容上片的离愁别绪之中。“都来几许”，是说这种相思总的算来会有多少，由挚友不得长聚而引起的时序更迭、流年暗换的慨叹与迷惘，亦暗寓其中。这两句深化了上片的离愁。但作者马上又冲破了感伤缠绵的氛围，用“且高歌休诉”句一变而为高亢旷达。这是对友人的劝慰，也是作者的自我排遣，表现出作者开朗豁达的胸怀。可是一想到别易会难，明年此际不知能否重逢，心里不免又泛起怅惘之情，使全词再见波折。这首词先写离愁，继而排解宽慰，终写怅惘之情，曲折细致，语短情长。', poem_tags = '宋词三百首,宋词精选,婉约,饮酒,惜别' WHERE poem_title = '贺圣朝·留别' AND poem_author = '叶清臣';
UPDATE edu_poem SET poem_translation = '是一首著名的咏梅词。傲立霜雪，一枝独秀的梅花是历来文人墨客的吟诵对象，特别是宋代咏梅词更多，其中能尽得梅花神韵的上乘之作却并不多见。\n\n　　李清照的这首《玉楼春》当属其中的佼佼者，不仅写活了梅花，而且活画出赏梅者虽愁闷却仍禁不住要及时赏梅的矛盾心态。作者出手便不俗。首句以“红酥”比拟梅花花瓣的宛如红色凝脂，以“琼苞”形容梅花花苞的美好，都是抓住了梅花特征的准确用语，“肯放琼苞碎”者，是对“含苞欲放”的巧妙说法。\n\n　　上片皆从此句生发。“探著南枝开遍未”，便是宛转说出梅花未尽开放。初唐时李峤《梅》诗云：“大庾敛寒光，南枝独早芳。”张方注：“大庚岭上梅，南', poem_appreciation = '这是一首著名的咏梅词。傲立霜雪，一枝独秀的梅花是历来文人墨客的吟诵对象，特别是宋代咏梅词更多，其中能尽得梅花神韵的上乘之作却并不多见。\n\n　　李清照的这首《玉楼春》当属其中的佼佼者，不仅写活了梅花，而且活画出赏梅者虽愁闷却仍禁不住要及时赏梅的矛盾心态。作者出手便不俗。首句以“红酥”比拟梅花花瓣的宛如红色凝脂，以“琼苞”形容梅花花苞的美好，都是抓住了梅花特征的准确用语，“肯放琼苞碎”者，是对“含苞欲放”的巧妙说法。\n\n　　上片皆从此句生发。“探著南枝开遍未”，便是宛转说出梅花未尽开放。初唐时李峤《梅》诗云：“大庾敛寒光，南枝独早芳。”张方注：“大庚岭上梅，南枝落，北枝开。如今对南枝之花还须问“开遍未”，则梅枝上多尚含苞，宛然可知。三、四两句“不知酝藉几多香，但见包藏无限意”，用对偶句，仍写未放之花，“酝藉”、“包藏”，点明此意。而“几多香”、“无限意”，又将梅花盛开后所发的幽香、所呈的意态摄纳其中，精神饱满，亦可见词人的灵心慧思。\n\n　　下片由咏梅转写赏梅之人。“道人”是作者的自称，意为学道之人。“憔悴”和“闷”、“愁”，讲李清照的外貌与内心情状，“春窗”和“阑干”交代客观环境，表明她当时困顿窗下，愁闷煞人，连阑干都懒得去倚。这是一幅名门闺妇的春愁图。\n\n　　不写梅花的盛开，却由含苞直跳到将败，这是咏梅的奇笔，写赏梅却先道自己的憔悴和愁闷，这是赏梅之妙想。反映了她自己“挼尽梅花无好意，赢得满衣清泪”（《清平乐·年年雪里》）的心态。此词盖作于晚年流落江南之后反常写法恰好能传达出当时正常的心态。虽然心境不佳，但梅花还是要赏的，所以“要来小酌便来休，未必明朝风不起”。“休”字这里是语助词，含罢、了的意思。这是作者心中的话：想要来饮酒赏梅的话便来罢，等到明天说不定要起风了呢！此句隐含着莫错过大好时机且举杯遣怀的意味。\n\n　　易安词是咏物抒情诗中的上品，这首咏梅诗尽得梅花之诗，也尽似词人之情，是不可多得的佳作。', poem_tags = '咏物,梅花,抒情' WHERE poem_title = '玉楼春·红酥肯放琼苞碎' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '天上碧桃露滋养，不同俗卉与凡花。乱山之中，萦水之畔，可惜一支如画为谁开？\n清寒细雨显柔情，怎奈春光短暂，美景将逝。为君酣醉又何妨，只怕酒醒时分人断肠。', poem_notes = '碧桃：一种观赏桃花。此指仙桃，借以赞颂主人的宠姬碧桃。\n数：辈。\n萦（yíng）回：盘转回旋。\n不道：不奈，不堪。这里“春”为双关语，既指喻作者对碧桃的赏爱，也寓有碧桃春心萌动，又难以表述之意。\n君：指花，也指双方。', poem_appreciation = '这首词有一段颇具传奇色彩的本事：“秦少游寓京师，有贵官延饮，出宠妓碧桃侑觞，劝酒惓惓。少游领其意，复举觞劝碧桃。贵官云：‘碧桃素不善饮。’意不欲少游强之。碧桃曰：‘今日为学士拼了一醉！”引巨觞长饮。少游即席赠《虞美人》词曰（略）。合座悉恨。贵官云：‘今后永不令此姬出来！’满座大笑。”（《绿窗新话》卷上）\n\n　　是否真有此“本事”，不得而知。但它对理解此词的蕴意、寄托却颇有启发。生于非地的一支碧桃，在乱山深处孤独自开，不被人赏，那正是美人命运的象征。\n\n　　“碧桃天上栽和露，不是凡花数。”首句化用唐诗人高蟾《下第后上永崇高侍郎》：“天上碧桃和露种，日边红杏倚云栽”语。先声夺人，高雅富丽。那是只有天宫才可能有的一株碧桃啊！又况和露而种，更呈其鲜艳欲滴之娇情妍态。如此光艳照人，自然不是凡花俗卉之胚数。词人从正、反两面对其褒扬至极。“不是”二字颇耐人玩味。诗歌理论家们常常强调中国诗词在不用系词的情况下所取得的成就，并认为这种成就正是得益于系词的缺失。其实，这并不完全正确。系词的出现，从语法角度看，它表示的只是两个词之间的等同，但当其运用于中国古典诗词之中时，它却传达出某些与这种等同相抵触的言外之意，换言之，“是”暗含了“不是”或“也许不是”，“不是”又暗含着“已经是”或“然而却是”，以其内在的歧义达到一种反讽的陈述。“不是凡花数”越是说得斩钉截铁，越是让人感到隐含有不愿接受的现实在。事实正是如此：“乱山深处水萦回。”一“乱”一“深”，见其托身非所、处地之荒僻。尽管依然在萦回盘旋的溪水边开得盈盈如画，“可惜一枝如画为谁开？”没人欣赏没人问，美又何然？也许可以保持那份高洁与矜持，然而总是遗恨！从而表现出碧桃不得意的遭遇和寂寞难耐的凄苦心境。杜甫有：“桃花一簇开无主，可爱深红爱浅红？”，陆游有“驿外断桥边，寂寞开无主。”意蕴与此略似，而此篇吟咏之深沉过之。杜诗、陆词皆正面点出花之“无主”，而秦词只以“为谁开”的探询语气，将“无主”之慨妥婉出之，音情更显得低徊摇荡。\n\n　　上片以花象征美人，然着笔在花。高贵不凡之身无奈托于荒山野岭，盈盈如画只是孤独自开，洁爱自好也难禁凄凄含愁，款款妙笔传其形神兼备。\n\n　　下片始转写美人。前二句见其惜春之心。微微春寒，细雨霏霏，这如画一枝桃花更显出脉脉含情。然而也许女主人公的忧虑太深重了，春天宜人的风物也很快从她忧伤的目光底下滑过去，终于发出了“不道春难管”的一声伤叹。是啊，无奈春光不由人遣，无法把留。它已经是“寂寞开无主”了，有何人来怜爱它呢？到了明年此时，它是否还是“依旧笑春风”呢？叹之、怜之、伤之。伤春也是自伤。即如此般芳洁光艳，终是青春难驻，年华易往！尾末两句写惜别。“为君沉醉又何妨。”难得知音怜爱，却又要匆匆行别，为报所欢，拼却一醉，应是理所为然，何况更是欲借以排遣愁绪。醉意恍惚中也许能减却几分离索的凄凉吧！可是转念一想：“只怕酒醒时候断人肠。”如今一醉颜红，自然是容易的，然而，酒醒之后呢？心爱的人儿不见了，不是更令人肠断？不，不能沉醉，哪怕只是一起度过这短暂的离别时分也是好的啊！沉醉又不能沉醉的矛盾以“只怕”二字委婉出之。“何妨”是为了他，“只怕”也是因为他，惜别之情深自见。\n\n　　全词情感发展万转千回，深沉蕴藉。词情亦进亦退，亦退亦进地委婉曲折地前进，每一份情感，都紧紧地跟随着它的否定：“不是凡花数”却是凡花命；乱山深处“一枝如画”，依然无人赏识；“轻寒细雨”，风物宜人，又恨留春不住；为君不惜一醉颜红，又怕酒醒时候更添愁，只好任凭愁来折磨她了。最后，在“断人肠”的怨叹声中词情戛然而止，收到了凄咽恻断的艺术效果。\n\n　　词作在艺术表现上运用的是传统的香草美人的比兴手法。花，为美人之象征，在美人身上，我们又不难看出词人自身的影子，亦花亦美人亦词人。词人本是一位“少豪俊，慷慨溢于言辞”（《宋史·秦观传》）的才俊之士，却不为世用，仕途抑塞，历尽坎坷，自然是满腹怀才不遇的不平。然而在那埋没人才的社会里，这不平，向谁去诉说？诉说又有何用？只好“借他人酒杯，浇胸中块垒”。于是当词人为美人的命运深情叹咏的时候，他其实正是在寄寓身世，抒自身怀抱。也正是词人身世之感的打入，使得此词的意义大大超越于这则“本事”。词心所系，寄托遥深，乃是香草美人手法极其成功的运用。全词处处紧扣，而又不着痕迹，极尽含蓄委婉之致，表现了精湛的艺术技巧。读者可知，骚赋之法，“衣被辞人，非一代也”。', poem_tags = '宋词精选,美人,命运' WHERE poem_title = '虞美人·碧桃天上栽和露' AND poem_author = '秦观';
UPDATE edu_poem SET poem_tags = '怀人,胞弟' WHERE poem_title = '满江红·怀子由作' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '在朝中做官的我和在南寺的自远禅师，什么时候能再相见呢？\n大概要等到我心中没有世俗之事的时候吧。', poem_notes = '东宫：太子所居之宫，也用来代指太子。\n白庶子：即白居易，白居易曾在东宫担任庶子（大夫）。\n远禅师：指与白居易同时代的自远禅师。', poem_tags = '老师,抒情' WHERE poem_title = '远师' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '三月三日阳春时节天气清新，长安曲江河畔聚集好多美人。\n姿态凝重神情高远文静自然，肌肤丰润胖瘦适中身材匀称。\n绫花绫罗衣裳映衬暮春风光，金丝绣的孔雀银丝刺的麒麟。\n头上戴的是什么珠宝首饰呢？翡翠玉做的花饰垂挂在两鬓。\n在她们的背后能看见什么呢？珠宝镶嵌的裙腰多稳当合身。\n其中有几位都是后妃的亲戚，里面有虢国和秦国二位夫人。\n翡翠蒸锅端出香喷的紫驼峰，水晶圆盘送来肥美的白鱼鲜。\n她们捏着犀角筷子久久不动，厨师们快刀细切空忙了一场。\n宦官骑马飞驰不敢扬起灰尘，御厨络绎不绝送来海味山珍。\n笙箫鼓乐缠绵宛转感动鬼神，宾客随从满座都是达官贵人。\n有一个骑马官人是何等骄横，车前下马从绣毯上走进帐门。\n白雪似的杨花飘落覆盖浮萍，青鸟飞去衔起地上的红丝帕。\n杨家气焰很高权势无与伦比，切勿近前以免丞相发怒斥人！', poem_notes = '三月三日：为上巳日，唐代长安士女多于此日到城南曲江游玩踏青。\n态浓：姿态浓艳。意远：神气高远。淑且真：淑美而不做作。\n肌理细腻：皮肤细嫩光滑。骨肉匀：身材匀称适中。\n“绣罗”两句：用金银线镶绣着孔雀和麒麟的华丽衣裳与暮春的美丽景色相映生辉。\n翠微：薄薄的翡翠片。微：一本作“为”。 訇叶：一种首饰。鬓唇：鬓边。\n珠压：谓珠按其上，使不让风吹起，故下云“稳称身”。 腰衱：裙带。\n就中：其中。云幕：指宫殿中的云状帷幕。椒房：汉代皇后居室，以椒和泥涂壁。后世因称皇后为椒房，皇后家属为椒房亲。\n“赐名”句：指天宝七载（748）唐玄宗赐封杨贵妃的大姐为韩国夫人，三姐为虢国夫人，八姐为秦国夫人。\n紫驼之峰：即驼峰，是一种珍贵的食品。唐贵族食品中有“驼峰炙”。釜：古代的一种锅。翠釜，形容锅的色泽。\n水精：即水晶。行：传送。素鳞：指白鳞鱼。\n犀筯：犀牛角作的筷子。厌饫：吃得腻了。\n鸾刀：带鸾铃的刀。缕切：细切。空纷纶：厨师们白白忙乱一番。贵人们吃不下。\n黄门：宦官。飞鞚，即飞马。\n八珍：形容珍美食品之多。\n宾从：宾客随从。杂遝：众多杂乱。要津：本指重要渡口，这里喻指杨国忠兄妹的家门，所谓“虢国门前闹如市”。\n后来鞍马：指杨国忠，却故意不在这里明说。逡巡：原意为欲进不进，这里是顾盼自得的意思。\n“杨花”句：是隐语，以曲江暮春的自然景色来影射杨国忠与其从妹虢国夫人（嫁裴氏）的暧昧关系，又引北魏胡太后和杨白花私通事，因太后曾作“杨花飘荡落南家”，及“愿衔杨花入窠里”诗句。后人有“杨花入水化为浮萍”之说，萍之大者为蘋。杨花、萍和蘋虽为三物，实出一体，故以杨花覆蘋影射兄妹苟且乱伦。据史载：“虢国素与国忠乱，颇为人知，不耻也。每入谒，并驱道中，从监、侍姆百余骑，炬密如昼，靓妆盈里，不施帏障，时人谓为雄狐。”\n青鸟：神话中鸟名，西王母使者。相传西王母将见汉武帝时，先有青鸟飞集殿前（见《汉武故事》）。后常被用作男女之间的信使。\n“炙手”二句：言杨氏权倾朝野，气焰灼人，无人能比。丞相：指杨国忠，天宝十一载（752年）十一月为右丞相。嗔：发怒。', poem_appreciation = '这首诗讽刺了杨家兄妹骄纵荒淫的生活，曲折地反映了君王的昏庸和时政的腐败。\n\n　　成功的文学作品，它的倾向应当从场面和情节中自然而然地流露出来，不应当特别把它指点出来，作者的见解愈隐蔽，对艺术作品来说就愈好；而且作家不必要把他所描写的社会冲突的历史的未来的解决办法硬塞给读者。《丽人行》就是这样的一篇成功之作。这篇歌行的主题思想和倾向倒并不隐晦难懂，但确乎不是指点出来而是从场面和情节中自然而然地流露出来的。从头到尾，诗人描写那些简短的场面和情节，都采取像《陌上桑》那样一些乐府民歌中所惯常用的正面咏叹方式，态度严肃认真，笔触精工细腻，着色鲜艳富丽、金碧辉煌，丝毫不露油腔滑调，也不作漫画式的刻画。但令人惊叹不置的是，诗人就是在这一本正经的咏叹中，出色地完成了诗歌揭露腐朽、鞭挞邪恶的神圣使命，获得了比一般轻松的讽刺更为强烈的艺术批判力量。诗中首先泛写上巳曲江水边踏青丽人之众多，以及她们意态之娴雅、体态之优美、衣着之华丽。\n\n　　辛延年《羽林郎》：“胡姬年十五，春日独当垆。长裾连理带，广袖合欢襦。头上蓝田玉，耳后大秦珠。两鬟何窈窕，一世良所无。”《陌上桑》：“头上倭堕髻，耳中明月珠。缃绮为下裙，紫绮为上襦。”《焦仲卿妻》：“着我绣夹裙，事事四五通。足下蹑丝履，头上玳瑁光。腰若流纨素，耳着明月珰。指如削葱根，口如含朱丹。纤纤作细步，精妙世无双。”回环反复，咏叹生情，“态浓”八句就是从这种民歌表现手法中变化出来的。前人已看到了这诗用工笔彩绘仕女图画法作讽刺画的这一特色。胡夏客说：“唐宣宗尝语大臣曰：‘玄宗时内府锦袄二，饰以金雀，一自御，一与贵妃；今则卿等家家有之矣。’此诗所云，盖杨氏服拟于宫禁也。”总之，见丽人服饰的豪华，见丽人非等闲之辈。写到热闹处，笔锋一转，点出“就中云幕椒房亲，赐名大国虢与秦”，则虢国、秦国（当然还有韩国）三夫人在众人之内了。着力描绘众丽人，着眼却在三夫人；三夫人见，众丽人见，整个上层贵族骄奢淫佚之颓风见，不讽而讽意见。肴馔讲究色、香、味和器皿的衬托。“紫驼之峰出翠釜，水精之盘行素鳞”，举出一二品名，配以适当颜色，便写出器皿的雅致，肴馔的精美丰盛以及其香、其味来。这么名贵的山珍海味，缕切纷纶而厌饫久未下箸，不须明说，三夫人的骄贵暴殄，已刻画无遗了。“黄门飞鞚不动尘，御厨络绎送八珍”，内廷太监鞚马飞逝而来，却路不动尘，可见其规矩和排场。皇家气派，毕竟不同寻常。写得真好看煞人，也惊恐煞人。如此煞有介事地派遣太监前来，络绎不绝于途，原来是奉旨从御厨房里送来珍馐美馔为诸姨上巳曲江修禊盛筵添菜助兴，头白阿瞒（唐玄宗宫中常自称“阿瞒”）不可谓不体贴入微，不可谓不多情，也不可谓不昏庸了。\n\n　　乐史《杨太真外传》载：“时新丰初进女伶谢阿蛮，善舞。上与妃子钟念，因而受焉。就按于清元小殿，宁王吹玉笛，上羯鼓，妃琵琶，马仙期方响，李龟年觱篥，张野狐箜篌，贺怀智拍。自旦至午，欢洽异常。时唯妃女弟秦国夫人端坐观之。曲罢，上戏曰：‘阿瞒乐籍，今日幸得供养夫人。请一缠头！’秦国曰：‘岂有大唐天子阿姨，无钱用邪？’遂出三百万为一局焉。”黄门进馔是时人目睹，曲罢请赏是宋人传奇，真真假假，事出有因，两相对照，风流天子精神面貌的猥琐可以想见了。“箫鼓哀吟”、“宾从杂遝”，承上启下，为“后来”者的出场造作声势，烘托气氛。彼“后来”者鞍马逡巡，无须通报，意然当轩下马，径入锦茵与三夫人欢会：此情此景，纯从旁观冷眼中显出。北魏胡太后曾威逼杨白花私通，杨白花惧祸，降梁，改名杨华。胡太后思念他，作《杨白花歌》，有“秋去春来双燕子，愿衔杨花入窠里”之句。“青鸟”是神话传说中西王母的使者，唐诗中多用来指“红娘”一类角色。章碣《曲江》诗有“落絮却笼他树白”之句，可见曲江沿岸盛植杨柳。又隋唐时期，关中地域气温较高，上巳（阴历三月三日）飘杨花，当是实情。“杨花”二句似赋而实比兴，暗喻杨国忠与虢国夫人的淫乱。乐史《杨太真外传》载：“虢国又与国忠乱焉。略无仪检，每入朝谒，国忠与韩、虢连辔，挥鞭骤马，以为谐谑。从官监妪百余骑。秉烛如昼，鲜装袨服而行，亦无蒙蔽。”他们倒挺开通，竟敢招摇过市，携众遨游，公开表演种种肉麻丑态。既然如此，“先时丞相未至，观者犹得近前，乃其既至，则呵禁赫然”（黄生语），不许游人围观，固然是为了显示其“炙手可热”权势之烜赫，但觥筹交错，酒后耳热，放浪形骸之外，虽是开通人，也有不想让旁人窥见的隐私，这也是重要的原因。“春色满园关不住，一枝红杏出墙来”，青鸟衔去的一方红手帕，便于有意无意中泄露了一点春光。\n\n　　全诗场面宏大，鲜艳富丽，笔调细腻生动，同时又含蓄不露，诗中无一断语处，却能使人品出言外之意。语极铺排，富丽华美中蕴含清刚之气。虽然不见讽刺的语言，但在维妙维肖的描摹中，隐含犀利的匕首，讥讽入木三分。', poem_tags = '唐诗三百首,乐府,咏叹,讽刺' WHERE poem_title = '丽人行' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '少女戴着高高的帽子，拂动着宽广的衣袖，打扮成南方贵族妇女的模样，\n夜晚独自在凉爽寂静的庭院中漫步。\n自己拿着玉钗敲台阶下的竹子，打出拍子,\n一曲清越的歌声之后，月色显得十分皎洁。', poem_notes = '张立本女：《全唐诗》载：“草场官张立本女，少未读书，忽自吟诗，立本随口录之。”\n危冠：高冠。楚宫妆：即南方贵族妇女式样的打扮。\n闲庭：空旷的庭院。\n玉钗：一种妇女头饰。砌竹：庭院中临阶而生的竹子。\n月如霜：月光皎洁。', poem_tags = '女子,故事' WHERE poem_title = '听张立本女吟' AND poem_author = '高适';
UPDATE edu_poem SET poem_translation = '注释 大荒：指极其偏远荒僻的地方。 朔风：北风。轸归虑：意为归家的思虑使人心痛。轸：痛。 虏骑：指塞北匈奴骑兵，此处指突厥等少数民族骑兵。 翩翩：形容马骑轻疾的样子。 边声：边地所特有的声响。 海气：指湖泊上的雾气。 定远：指定远侯班超。 行路难：乐府旧题，属《杂曲歌辞》。 角弓：指用兽角装饰的硬弓。持弦：张弦。 龙城：匈奴单于祭天的地方，在今蒙古国境内。 金鼓：分别指钲和鼓，是古时军中用于号令的两种乐器。 南庭：指南匈奴单于的住处。 蓬：一种多年生草本植物。', poem_tags = '边塞,感伤,思归,组诗' WHERE poem_title = '从军行二首' AND poem_author = '王昌龄';
UPDATE edu_poem SET poem_tags = '七夕节' WHERE poem_title = '七夕' AND poem_author = '杨朴';
UPDATE edu_poem SET poem_translation = '水的北面有一条小溪，往东流入潇水。有人说，过去有个姓冉的住在这里，所以把这条溪水叫做冉溪。还有人说，溪水可以用来染色，用它的功能命名为染溪。我因愚犯罪，被贬到潇水。我喜爱这条溪水，沿着它走了二三里，发现一个风景绝佳的地方，就在这里安家。古代有愚公谷，如今我把家安置在这条溪水旁，可是它的名字没人能定下来，当地的居民还在争论不休，看来不能不改名了，所以把它定名为愚溪。\n\n　　我在愚溪上面买了个小丘，叫做愚丘。从愚丘往东北走六十步，发现一处泉水，又买下来作为积蓄，称它为愚泉。愚泉共有六个泉眼，都在山下平地，泉水都是往上涌出的。泉水合流后弯弯曲曲向南流去，经过的地方就称作愚沟。于是运土堆石，堵住狭窄的泉水通道，筑成了愚池。愚池的东面是愚堂，南面是愚亭。池子中央是愚岛。美好的树木和奇异的岩石参差错落。这些都是山水中瑰丽的景色，因为我的缘故都用愚字玷污了它们。\n\n　　水是聪明人所喜爱的。可现在这条溪水竟然被愚字辱没，这是为什么呢?因为它水道很低，不能用来灌溉。又险峻湍急，有很多浅滩和石头，大船进不去；幽深浅狭，蛟龙又不屑于此，不能兴起云和雨，对世人没有什么好处，正像我。既然如此，即使是玷辱了它，用愚字来称呼它，也是可以的。\n\n　　宁武子“在国家动乱时就显得很愚蠢”，是聪明人故意装糊涂。颜子“从来不提与老师不同的见解，像是很愚笨”，也是明智的人而故意表现得很愚笨。他们都不是真正的愚笨。如今我在政治清明时却做出与事理相悖的事情，所以再没有像我这么愚蠢的人了。因此，天下人谁也不能和我争这条溪水，我有给它命名的专利。\n\n　　溪水虽然对世人没有什么好处，可它却能够映照万物，清秀明澈，能发出金石般的响声，能使愚蠢的人喜笑颜开，对它眷恋爱慕不忍离去。我虽然不合世俗，也还能稍用文章来安慰自己，用文笔自由驱使万物，创造出一个称心满意的审美境界，世间万象没有什么能逃得出我的笔墨形容。我用愚笨的言辞歌唱愚溪，觉得茫茫然没什么悖于事理的，昏昏然似乎都是一样的归宿，超越天地尘世，融入玄虚静寂之中，而寂寞清静之中没有谁能了解我。于是作《八愚诗》，记在溪石上。▲', poem_tags = '古文观止,写景,抒愤,序文' WHERE poem_title = '愚溪诗序' AND poem_author = '柳宗元';
UPDATE edu_poem SET poem_translation = '注释 咏牡丹：亦指王随，王曙作。 牡丹：多年生落叶小灌木，生长缓慢，株型小，株高多在0.5～2米之间；根肉质，粗而长，中心木质化，长度一般在0.5～0.8米，极少数根长度可达2米。牡丹是我国特有的木本名贵花卉，花大色艳、雍容华贵、富丽端庄、芳香浓郁，而且品种繁多，素有“国色天香“、“花中之王“的美称，长期以来被人们当做富贵吉祥、繁荣兴旺的象征。 桑叶：桑科植物桑的干燥叶，又名家桑、荆桑、桑椹树、黄桑等。 斗大：大如斗。对小的物体，形容其大。南朝宋刘义庆《世说新语·尤悔》：“周曰：‘今年杀诸贼奴，当取金印如斗大系肘后。’”清二石生《十洲春语》卷下：“不能如介子定远辈，投笔立功，勒铭燕然，以博取斗大悬肘之印。” ▲', poem_appreciation = '赏析 　　王溥的这首之所以能给人耳目一新的直觉印象，是他一反人们对牡丹一向喜爱赞美的心态。题目用“咏”，先顺从人众的普遍心理定势，先诱导你，鄙人可没说牡丹的坏话，我是要歌咏它。读者乍眼一看，心理必然想着，歌咏牡丹者夥矣，王溥还能说出什么？这样想着，就好奇的往下读，结果却读出了对牡丹的说三道四。虽然有些生气，但细品，诗人的审美情思落在了两个点上——外表美和实用美。他担心人们不服气，先拿枣桑来示例：枣花虽小，秋后有枣儿甜脆可口；桑叶很柔弱，他能养蚕结丝，美艳的绫罗由桑叶生成。这回晾晾牡丹的底吧：花朵真大呀！大得无法形容，好像人们喜欢用“斗”来形容大，那就说她“如斗大”吧。还有，她的美艳，她的光彩，耀人眼目，让人心荡神怡，诗人是知道的，但他有意无视这些，因为，这些都是没有实用价值的虚妄的外在美，仅此一点，不值一提，值得一提的是，她一旦开完美艳的花，就花去枝空，空空如也，有什么好赞美的呢？诗我可写完了，读不读是你的事，读懂读不懂更是你的事，认同不认同我也不管你，我只写我的诗。诗人表完态了，我也表态：仅就诗而言绝对是好诗，如果取作对待人生的价值观，那就不好了。人生既离不开更多具有实用价值的东西，也离不了一些外表美而虚无缥缈的事物，人们有时喜欢画饼充“饥”和做梦——化蝶梦或黄粱梦。 ▲', poem_tags = '咏物,写花,抒怀' WHERE poem_title = '咏牡丹' AND poem_author = '王溥';
UPDATE edu_poem SET poem_translation = '遥望着窗外，朦胧的月亮就好像一团白银。夜深人静，身边风声渐紧。月亮被乌云遮住了。风呀，请你吹散月亮边上的乌云，让它照到我那负心汉。', poem_notes = '更阑：更残，即夜深。 \n奴：古代女子的谦称。\n负：原误作“附”，王国维校改。', poem_tags = '宋词三百首,怨妇,月亮,思念' WHERE poem_title = '望江南·天上月' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '五月是石榴花开得季节，杨柳被细雨润湿，枝叶低低沉沉地垂着。人们用五彩的丝线包扎多角形的粽子，煮熟了盛进镀金的盘子里，送给闺中女子。\n这一天正是端午，人们沐浴更衣，想祛除身上的污垢和秽气，举杯饮下雄黄酒以驱邪避害。不时的，窗外树丛中黄鹂鸟儿鸣唱声，打破闺中的宁静，打破了那纱窗后手持双凤绢扇的睡眼惺忪的女子的美梦。', poem_notes = '妖艳：红艳似火。\n生绡：未漂煮过的丝织品。古时多用以作画，因亦以指画卷。\n浴兰：见浴兰汤。\n惊破：打破。', poem_tags = '端午节,风俗,女子,生活,情思' WHERE poem_title = '渔家傲·五月榴花妖艳烘' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_tags = '景点,感伤' WHERE poem_title = '夕阳楼' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '译文 花草树木们似乎都知道春天就要离去，因此它们费尽心思争芳斗艳。 杨花榆荚没有百花的芬芳，只知道飘洒花絮像雪花般漫天飞舞。', poem_tags = '春天,景物' WHERE poem_title = '晚春二首·其二' AND poem_author = '韩愈';
UPDATE edu_poem SET poem_translation = '满月，明镜里也是满月，思乡的情绪如同刀在心头乱割！\n辗转流离，家乡越来越远；桂花攀折，天空如此远阔！\n归去吧！路上的霜露像雪一样洁白，林中栖息的小鸟正梳理着羽毛。\n看着那月宫中的兔儿，正在明亮的月光下，悠闲地数着新生白毛。\n\n圆月慢慢落下巫山深峡，犹自被白帝城衔挂着。\n江上雾气沉沉，江浦昏暗，但是车轮一样倾斜的圆月依然把半座楼照得通明。\n兵营里士兵的刁斗敲响了催晓的声音，月宫的蟾蜍也自然倾斜。\n圆月如同张满的弓，苍白的魂魄不仅仅照耀汉家营盘。', poem_appreciation = '这是诗人避乱蜀中之作。此组诗主调应该是悲伤苍凉的。第一首诗前两联睹月兴感，用象征团圆的八月十五的月亮反衬自己飘泊异乡的羁旅愁思。“归心折大刀”说的是吴刚在月宫被罚砍桂花树，杜甫猜想，吴刚也不是情愿砍树，一心想回到人间来。归去之心，竟然折断了砍树的大刀。“蓬”，蓬草，遇风飞转，故叫“飞蓬”。这里诗人用“转蓬”遇风飞转的形象，比喻自己飘泊不定的生活，隐示自己羁旅漂泊的苦味。由景入情，转篷象征漂泊无依的情感，杜甫空有归心只可惜无处还乡的凄凉。“行地远”指诗人自己当时处在偏远的夔州。诗人借此表达了反对战乱的思想。后两联描状中秋夜色，“见羽毛”、“数秋毫”极力写月亮之亮，进一步反衬自己思念远征的亲人，祈愿平息战争，国泰民安。末两句，“直”通“特”，“简直”的意思。“此时瞻白兔，直欲数秋毫”意为，这个时候仰望玉兔（指月亮），简直会数得清它的毫毛，形容月亮的明亮。第一首诗采用了反衬手法，在鲜明的比照中，表露了避乱生涯中的愁闷。\n\n　　第二首诗全诗写景，景中见情。“气沈全浦暗，轮仄半楼明。”描写的月光给人的感觉是苍茫的，悲凉的。“刁斗皆催晓，蟾蜍且自倾。”刁斗声起，让诗人想起离乡戍边的“汉家营”里的士卒，更想到了普天下在战乱中背景离乡的劳苦大众。忧己更忧民，这正表现了杜甫的伟大之处。', poem_tags = '中秋节,月亮,思乡' WHERE poem_title = '八月十五夜月二首' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '莺歌燕语预报了临近新年，马邑龙堆是几千里的疆边。\n家住京城比邻着汉室宫苑，心随明月飞到边陲的胡天。\n织锦回文诉说思念的长恨，楼上花枝取笑我依然独眠。\n请问你主帅车骑将军窦宪，何时班师回朝刻石燕然山。', poem_notes = '马邑：秦所筑城名，今山西朔县，汉时曾与匈奴争夺此城。龙堆：白龙堆得简称，指沙漠。\n层城：因京城分内外两层，故称。\n苑：这里指行宫。\n机中句，窦滔为苻坚秦州刺史，后谪龙沙，其妻苏蕙能文，颇思滔，乃织锦为回文旋图诗寄之。共八百四十字，纵横反覆，皆成文意。论：表露，倾吐。\n为问两句：后汉窦宪为车骑将军，大破匈奴，遂登燕然山，命班固作铭，刻石而还。元戎：犹主将。返旆：犹班师。勒：刻。燕然：燕然山，即今蒙古人民共和国杭爱山。', poem_appreciation = '这首诗题为《春思》，大意是写一位出征军人的妻子。在明媚的春日里对丈夫梦绕魂牵的思念，以及对反侵略战争早日胜利的盼望。盛唐是社会相对安定的时期，但边境战争却并未停息。前方将士与家乡亲人相互思念之情。仍然是诗人们吟咏的重要主题。这一类诗作总的来说具有较为深刻的社会意义，内容也较为充实。由于富有真情实感．其中不乏千古传涌的佳作。\n\n　　首联“莺啼燕语报新年，马邑龙堆路几千”，对比鲜明，动人心弦。“莺啼燕语”，这是和平宁静的象征；新年佳节，这是亲人团聚的时辰。但是，另一方面，在那遥远的边关，从征的亲人却不能享受这宁静，无法得到这温情。上句“莺啼燕语”四字，写得色彩浓丽，生意盎然。使下句“马邑龙堆”，更显得沉郁悲壮。诗人好似信笔而下，但震撼力却很强。\n\n　　良辰美景，未必便能带来欢乐；温柔乡里，最易惹动离情。“家住秦城邻汉苑”，秦城指咸阳，汉苑指长安。诗中的女主人公虽然目睹京畿的繁华与和平，却是“心随明月到胡天”，早巳飞到丈夫的身边。关河万里，能隔断人的形体，却隔不断心灵的呼唤，而作为心灵交通媒介的，大概只有那普照万方的明月了。\n\n　　为了寄托无穷的思念，女主人公纤纤擢素手，札札弄机杼，仿照古人故事，为远方的夫君织一幅锦字回文诗。回文诗循环可读，无始无终，思妇的离恨也缠绵不尽，地久天长。“机中锦字论长恨，楼上花枝笑独眠。”上句一个“论”字。下句一个“笑”字，都是拟人化的写法。锦字回文诗的内容。无非离情别恨。锦字诗有多长，恨便有多长，锦字诗无穷，恨也无穷。楼上花枝本无情，然而在诗人眼中。那花团锦簇的样子，很像是在嘲笑独眠之人。\n\n　　诗的结尾笔锋一转，提出一个意义深远的问题：“为问元戎窦车骑，何时返旆勒燕然？”不问别人而问元戎，因为他是军中主帅：你什么时候才能得胜班师，勒石而还？女主人公对亲人的思念是痛苦而深挚的，然而她也深明大义。她当然懂得，只有彻底战胜了敌人，才会有不光自己，同时也包括普天之下所有离散家庭的重新团聚。就这样，诗中女主人公将自己的命运和国家民族的命运统一起来，赋予了这首诗以比较积极的社会意义。', poem_tags = '唐诗三百首,妇女,春天,闺怨,思念' WHERE poem_title = '春思' AND poem_author = '皇甫冉';
UPDATE edu_poem SET poem_tags = '春江,景色' WHERE poem_title = '春江晚景' AND poem_author = '张九龄';
UPDATE edu_poem SET poem_translation = '柏木小船在漂荡，漂泊荡漾河中央。垂发齐眉少年郎，是我心中好对象。至死不会变心肠。我的天啊我的娘，为何对我不体谅？\n柏木小船在漂荡，漂泊荡漾河岸旁。垂发齐眉少年郎，是我倾慕的对象。至死不会变主张。我的天啊我的娘，为何对我不体谅？', poem_notes = '鄘（yōng）：中国周代诸侯国名，在今河南省汲县北。\n泛：浮行。这里形容船在河中不停漂浮的样子。\n中河：河中。\n髧（dàn）：头发下垂状。两髦（máo）：男子未行冠礼前，头发齐眉，分向两边状。\n维：乃，是。仪：配偶。\n之死：到死。之，到。矢靡它：没有其他。矢，通“誓”，发誓。靡它，无他心。\n只：语助词。\n谅：相信。\n特：配偶。\n慝（tè）：通“忒”，变更，差错，变动。也指邪恶，恶念，引申为变心。', poem_appreciation = '此诗的主人公可能是一个待嫁的姑娘，她选中的对象是一个不到二十的少年郎。姑娘的选择未能得到母亲的同意，所以她满腔怨恨，发誓要和母亲对抗到底。\n\n　　开篇以柏舟泛流起兴，写女主人公为自己的婚姻恋爱受阻而苦恼，就好比那在河中飘荡的柏木小舟一样。她早已自己相中了一个翩翩少年，他的发型很好看，透出活泼灵动的精神劲儿。这就是女主人公的心上人，她非他不嫁，至死不渝。可是她的母亲千般阻挠万般阻拦，死活不同意这门亲事。母女的意见不统一，爱情就发生了危机。女儿要么放弃己见，要么作坚决的抗争。看来诗中女主人公是持后一种态度的：至死誓靡它！坚决到这种程度，母亲也就难办了。但要为娘的改变主意，也不是那么容易的。所以女主人公一面誓死维护爱情，一面从内心发出沉重的叹息：娘呀天啊，为什么就不相信我是有眼力的呢！这一声叹息，使得诗的内容变得沉甸甸的。\n\n　　古代男女婚姻，都是父母之命，媒妁之言。像这种敢爱敢恨的女子自己找婆家的事情，真是有违传统习俗的，当父母的当然不会同意。可能也不一定是父母要展示权威，多半是他们凭自己的生活经验在为儿女把关，以确保日后生活美满。但是代沟的存在，使两代人的择偶观念不可避免地存在着差异和冲突。这原也正常。问题的关键是，母女二人的矛盾不可调和，因此才有了“之死矢靡他”的决绝抗争。\n\n　　这首诗反映了先秦时代汉族民间婚恋的现实状况：一方面，人们在政令许可的范围内仍享有一定的性爱自由，原始婚俗亦有传承；另一方面普遍的情况已是“取妻如之何？必告父母”、“取妻如之何？非媒不得”（《齐风·南山》），礼教已通过婚俗和舆论干预生活。所以诗中女子既自行择欢，却又受到母亲的制约。而哪里有压迫哪里就有反抗，诗中也就表现了青年男女为了争取婚恋自由而产生的反抗意识，这是一个很新很有价值的信息。', poem_tags = '诗经,婚恋' WHERE poem_title = '国风·鄘风·柏舟' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '请问大哥你的家在何方。我家是住在建康的横塘。\n停下船吧暂且借问一声，听口音恐怕咱们是同乡。', poem_notes = '长干行：乐府曲名。 是长干里一带的民歌，长干里在今江苏省南京市南面。\n君：古代对男子的尊称。\n妾：古代女子自称的谦词。\n横塘：现江苏省南京市江宁区。　\n暂：暂且、姑且。\n借问：请问一下。\n或恐：也许。', poem_appreciation = '这首抒情诗抓住了人生片断中富有戏剧性的一刹那，用白描的手法，寥寥几笔，就使人物、场景跃然纸上，栩栩如生。它不以任何色彩映衬，似墨笔画；它不用任何妆饰烘托，是幅素描；它不凭任何布景借力，犹如一曲男女声对唱；它截头去尾，突出主干，又很象独幕剧。题材平凡，而表现手法不凡。\n\n　　一个住在横塘的姑娘，在泛舟时听到邻船一个男子的话音，于是天真无邪地问一下：你是不是和我同乡？就是这样一点儿简单的情节，只用“妾住在横塘”五字，就借女主角之口点明了说话者的性别与居处。又用“停舟”二字，表明是水上的偶然遇合，用一个“君”字指出对方是男性。那些题前的叙事，用这种一石两卵的手法，就全部省略了。诗一开头就单刀直入，让女主角出口问人，现身纸上，而读者也闻其声如见其人，绝没有茫无头绪之感。从文学描写的技巧看，“声态并作”，达到了“应有尽有，应无尽无”，既凝炼集中而又玲珑剔透的艺术高度。\n\n　　在寥寥二十字中，诗人仅用口吻传神，就把女主角的音容笑貌，写得活灵活现。他不象杜牧那样写明“娉娉袅袅十三余”，也不象李商隐那样点出“十五泣春风，背面秋千下”。他只采用了问话之后，不待对方答复，就急于自报“妾住在横塘”这样的处理，自然地把女主角的年龄从娇憨天真的语气中反衬出来了。在男主角并未开口，而这位小姑娘之所以有“或恐是同乡”的想法，不正是因为听到了对方带有乡音的片言只语吗？这里诗人又省略了“因闻声而相问”的关节，这是文字之外的描写，所谓“不写之写”。\n\n　　这首诗还表现了女主角境遇与内心的孤寂。单从她闻乡音而急于“停舟”相问，就可见她离乡背井，水宿风行，孤零无伴，没有一个可与共语之人。因此，他乡听得故乡音，且将他乡当故乡，就这样的喜出望外。诗人不仅在纸上重现了女主角外露的声音笑貌，而且深深开掘了她的个性和内心。\n\n　　诗的语言朴素自然，有如民歌。却拥有无尽的艺术感染力。', poem_tags = '唐诗三百首,女子,孤独,思乡' WHERE poem_title = '长干行·君家何处住' AND poem_author = '崔颢';
UPDATE edu_poem SET poem_tags = '宋词精选,重阳节,友情,思乡' WHERE poem_title = '阮郎归·天边金掌露成霜' AND poem_author = '晏几道';
UPDATE edu_poem SET poem_translation = '春天，诗人在偎依着青山的十里楼台边，听见了从盛开的百花深处传来的杜鹃啼叫声。那声声杜鹃鸣就像和行道中人说话似的，与那随意飞飞停停的流莺不同。\n在晴明的春日，杜鹃不断卖弄它那“不如归去”的“殷勤”的叫声，“行人”似从梦中惊醒。这“行人”岂是不想回家啊，只是回家的日子还不能期望定下啊。', poem_notes = '翠微：青翠的山气，此指青翠掩映的山间幽深处。\n杜鹃：又名杜宇、子规，叫声像“不如归去”；啼：叫。\n行人：离别在外的游子。\n流莺：指黄莺。取次：随意、任意。\n惊梦觉：从睡梦中惊醒；弄晴时：弄指卖弄，杜鹃在晴明的春日卖弄自己的叫声。\n不如归：杜鹃的叫声像“不如归去”。\n争奈：怎奈。惊梦”两句：在晴朗温和的春日，杜鹃似乎在卖弄叫声，将客人砂梦中惊醒。未可期：未可肯定的意思。 “期“，必韵意思。', poem_appreciation = '这首词通过咏杜鹃而思归怀人，构思巧妙。\n\n　　上片写羁旅行人梦中得到杜鹃“殷勤”劝慰：山色青翠、春深花繁之时，流莺漫不经心地随意飞鸣，唯有杜鹃善解人意，于百花深处向行人殷勤劝慰。“十里楼台倚翠微，百花深处杜鹃啼”，写鹃啼的环境和季节。青翠的山色，如何逊“《仰赠从兄兴宁真南》：“高山郁翠微”；也用以指代青山，如杜牧《九日齐山登高》：“与客携壶上翠微”。此处指青山，说在靠着青山的十里楼台的旁边，在春天百花盛开的深处，听见了杜鹃啼叫。“殷勤白与行人语，不似流莺取次飞”，说杜鹃在花间不断地叫着，好像对“行人”很有情感，不惜“殷勤”相告，比起黄莺的随意飞动，对人漠不关心，大不相同。黄庭坚《次韵裴仲谋同年》：“烟沙篁竹江南岸，输与鸬鹚取次眠。”也是用这个词来写鸟。“行人”走在春色绚烂的优美环境中，心情本来是会愉悦的，但因为离家作客，所以听了杜鹃叫声，不免会引起思家之念，作客之愁。那么，词中所写的美丽景色，又正好为杜鹃叫声的感人作了反衬。\n\n　　下片写杜鹃对行人梦醒之后的声声规劝：羁旅之人一梦惊醒，已是阳光明媚，杜鹃仍在喋喋不休，“声声只道不如归”，本是好心规劝，谁知却帮了倒忙，反而使得羁旅之人益发孤寂、更多春愁，惹得他久久蓄积在心的思归怀人之情倾泻而出，再也控制不住，因而斥责杜鹃，“天涯岂是无归意，争奈归期未可期”。“惊梦觉，弄晴时，声声只道不如归”，在晴明的春日，杜鹃偏又卖弄它的叫声，“行人”从梦中惊醒，听到的还是声声的“不如归去”。前面路上初闻鹃啼，感到“殷勤”；听得太多，睡在床上也被叫得不安，叫的又是一句人所做不到的话，那“行人”心中自然也就变得有点烦躁了。“天涯岂是无归意，争奈归期未可期”，不是自己不想回家，只是自己不能决定回去的日期，生活不能由自己主宰，没有什么办法。结句以反诘句收束全词，突出行客思归怀人之深切，点明本词题旨，同时又回答了杜鹃“不如归去”的声声规劝，句法巧妙，抒情委婉沉郁。这是在烦躁中的思念，说是自言自语行，说是对杜鹃的回答也行。这里表面上有埋怨鹃鸟无知、强聒难耐的意思，但归根到底，是对真正“作弄”人的生活遭遇的愤慨。这片词，话说得比较直致，但内容还有曲折。\n\n　　同样听到一种鹃声，不同的诗人、词家，可以从各自的处境、各样的角度写出不同的感受。杜荀鹤的“啼得血流无用处，不如缄口过残春”，是愤慨文章无用之言；韦应物的“邻家孀妇抱儿泣，我独展转为何情”，是同情丈夫死在外地的寡妇之言；朱敦儒的“月解重圆星解聚，如何不见人归？今春还听杜鹃啼”，是痛心国土沦陷，南北亲人不能团聚之言；范仲淹的“春光无限好，犹道不如归”，是豁达之言；杨万里的“自出锦江归未得，至今犹劝别人归”，是诙谐之言。晏几道这首词，则是对浪迹在外、有家难归的生活的叹息之言，写得真切，有一定的感染力；结尾两句，用反跌之笔表曲折之情，意境尤深。', poem_tags = '春天,羁旅,写鸟' WHERE poem_title = '鹧鸪天·十里楼台倚翠微' AND poem_author = '晏几道';
UPDATE edu_poem SET poem_translation = '在咸阳桥上遇雨了，那牛毛细雨随风飘摇不定，宛如悬在空中的水晶帷帘；那泊着的钓鱼船被这连绵的水晶帷帘阻隔，如烟如画。眼前这烟水空濛的景色多么像初春时节洞庭湖上那烟波浩渺的景致；还有那沉沉的暮霭，好像正驮载着水气缓缓地向岳阳城的上空飘去，真是美极了。', poem_notes = '咸阳桥：又名西渭桥，故址在今陕西省咸阳市南，古代多于此送别。\n还：一作“绝”。\n将：携带。岳阳天：岳阳楼在洞庭湖边，可俯瞰洞庭春色。', poem_appreciation = '这是一首对雨即景之作，明快、跳荡，意象绵渺，别具特色。咸阳桥，又名便桥，在长安北门外的渭水之上，是通往西北的交通孔道。古往今来，有多少悲欢离合、兴废存亡的历史在这里幕启幕落。然而诗人此番雨中徜徉，却意度闲适，并无愁眉锁眼之态，笔墨染出，是一派清旷迷离的山水图景。\n\n　　首句入题。“咸阳桥”点地，“雨”点景，皆直陈景物，用语质朴。句末炼出一个“悬”字，便将一种雨脚绵延如帘箔之虚悬空际的质感，形象生动地传出，健捷而有气势，令人神往。接下一句，诗人把观察点从桥头推向远处的水面，从广阔的空间来描写这茫茫雨色。这是一种挺接密衔的手法。“万点”言雨阵之密注。“空蒙”二字最有分量，烘托出云行雨施、水气蒸薄的特殊氛围，点出这场春雨所引起的周围环境的色调变化来。用笔很像国画家的晕染技法，淡墨抹出，便有无限清蔚的佳致。这种烟雨霏霏的景象类似江南水乡的天气，是诗人着力刻画的意境，并因而逗出下文的联翩浮想，为一篇转换之关键。“钓船”是诗中实景，诗人用一个“隔”字，便把它推到迷蒙的烟雨之外，若隐若现，似有似无，像是要溶化在设色清淡的画面里一样，有超于象外的远致。\n\n　　前两句一起一承，围绕眼前景物生发，第三句纵笔远扬，转身虚际，出人意外地从咸阳的雨景，一下转到了洞庭的春色。论地域，天远地隔；论景致，晴雨不侔。实现这两幅毫不相干的水天图画的联结转化的媒介，乃是存在于二者之间的某种共同点—即上面提到的烟水空蒙的景色。这在渭水关中也许是难得一见的雨中奇观，但在洞庭泽国，却是一种常见的色调。诗人敏感地抓住这一点，发挥艺术的想象，利用“还似”二字作有力的兜转，就把它们巧妙在联到一起，描绘出一幅壮阔飞动、无比清奇的图画来。洞庭湖为海内巨浸，气蒸波撼，吞天无际。在诗人看来，湿漉的晓云好像是驮载着接天的水气飘进了岳阳古城的上空。这是极其壮观的景象。“将入”二字，可说是笔挟云涛。\n\n　　作者着意描写巴陵湖畔的云容水色，其目的在于用它来烘托咸阳的雨景，使它更为突出。这是一种借助联想，以虚间实，因宾见主的借形之法，将两种似乎无关的景物，从空间上加以联系，构成了此诗在艺术上的特色。', poem_tags = '写景,写雨' WHERE poem_title = '咸阳值雨' AND poem_author = '温庭筠';
UPDATE edu_poem SET poem_translation = '晚上在江楼上向东望去，海天相连，一片茫茫；山川形势，又阔又长。\n城的四周亮起了万家灯火，一道银河映入水的中央。\n晴天时，风吹古树，瑟瑟作响，好像是在下雨一般；夏夜里，月光撒满了平地，就跟秋霜一样。\n能不能到江楼来消消暑气？比起您的茅屋，的确要更加清凉。', poem_notes = '江楼：杭州城东楼，又叫“望潮楼”或“望海楼”，也叫“东楼”。\n四畔：四边。\n星河：银河，也叫天河。\n晴天雨：风吹古木，飒飒作响，像雨声一般，但天空却是晴朗的，所以叫“晴天雨”。\n平沙：平地。\n夏夜霜：月照平沙，洁白似霜，但却是夏夜，所以叫“夏夜霜”。\n就：近，到。\n消暑：消除暑气。\n较：又作“校”。', poem_appreciation = '诗人写出了黄昏时站在楼上所看到的杭州城外繁华景色。\n\n　　海天东望夕茫茫，山势川形阔复长一首句写仲夏之夜，登上江楼，极目远眺，海天暮色“茫茫”一片，写出海上夜色。次句推展画面，山川形势，气象壮阔。\n\n　　灯火万家城四畔，星河一道水中央一次联泼墨挥洒，江城万家灯火四面闪烁天际银河倒映在江心。同首联所写海天茫茫、山高水阔，相互辉映。都是“夕望”之景\n\n　　风吹古木晴天雨，月照平沙夏夜霜——腹联使用了“晴天雨“、“夏夜霜“两个形象比喻。前者将风吹古木树叶的萧瑟声同雨声联系，说明酷似雨声；后者将皓月临照平沙的银白色同霜色比并说明形如秋霜。以强烈的主观想象把互相矛盾的自然现象通过艺术的对接，合情合理，使景色透射出一股清凉气息。\n\n　　能就江楼销暑否？比君茅舍校清凉尾联以问答的形式，以江楼茅舍消暑“校清凉”亲切、诙谐，因口吻而使人物形象跃然纸上。\n\n　　在夕阳西下的时候，诗人登上江楼，向东望去，总览余杭山川形势，只见海天一色莽莽苍苍，山川分外开阔空旷。而当夜幕降临，城四周燃起了万家灯火，钱塘江中江船密集，待渔火纷纷点燃之时，就仿佛是天上的星河映在了水的中央。森森古木高旷而幽寒，就是在晴天也像下雨一样阴凉潮湿，月亮照在平沙之上，就是在夏天也像是落下了层白霜那样清寒。\n\n　　于是，诗人描写了俯瞰万家灯火星河灿烂的繁华夜景和月白风清的感受。用“晴天雨”来形容夜风，把风吹树叶的飒飒声和雨声联系起来；用“夏夜霜”来形容月光，又把月照白沙的颜色，和霜色结合起来，诗人丰富的想象力于此可见一斑，壮美的山河，凉爽宜人的气候，加上主人的殷勤，客人便欣然而至了。\n\n　　诗人把江城夏夜的景色描写得分外美丽。不仅有海天一色山川阔大的自然之美，又有万家灯火、水中渔火的人间安宁，繁华的气象。而·古木”、“平沙”二句的描绘，便把一片清朗幽寒写得淋漓尽致，让人顿觉暑意全消，精神为之一爽——这的确是一个消暑的好地方。\n\n　　诗中所写都是寻常景物：海、天、山川、灯火、星河、风雨树木，月下的霜……但其妙处就在于在短短一首七律中用这么多事物组合出一幅幅清新优美的画面，就像一幅疏朗悠远的山水画，最后以人的心情作结，使整幅画更增加了人情之美。', poem_tags = '夏天,写景' WHERE poem_title = '江楼夕望招客' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '自从和老友在江海分别，隔山隔水已度过多少年。\n突然相见反而怀疑是梦，悲伤叹息互相询问年龄。\n孤灯暗淡照着窗外冷雨，幽深的竹林漂浮着云烟。\n明朝更有一种离愁别恨，难得今夜聚会传杯痛饮。', poem_notes = '云阳：县名，县治在今陕西泾阳县西北。韩绅：《全唐诗》注：“一作韩升卿。”韩愈的四叔名绅卿，与司空曙同时，曾在泾阳任县令，可能即为此人。宿别：同宿后又分别。\n江海：指上次的分别地，也可理解为泛指江海天涯，相隔遥远。\n几度：几次，此处犹言几年。\n乍：骤，突然。翻：反而。\n年：年时光景。\n离杯：饯别之酒。杯：酒杯，此代指酒。共传：互相举杯。', poem_appreciation = '这是首惜别诗。诗写乍见又别之情，不胜黯然。诗一开端由上次别离说起，接着写此次相会，然后写叙谈，最后写惜别，波澜曲折，富有情致。“乍见翻疑梦，相悲各问年”乃久别重逢之绝唱，与李益的“问姓惊初见，称名忆旧容”也有异曲同工之妙。\n\n　　上次别后，已历数年，山川阻隔，相会不易，其间的相思，自在言外。正因为相会不易，相思心切，所以才生发出此次相见时的“疑梦”和惜别的感伤心情来，首联和颔联，恰成因果关系。\n\n　　“乍见”二句是传诵的名句，人到情极处，往往以假为真，以真作假。久别相逢，乍见以后，反疑为梦境，正说明了上次别后的相思心切和此次相会不易。假如别后没有牵情，相逢以后便会平平淡淡，不会有“翻疑梦”的情景出现了。“翻疑梦”，不仅情真意切，而且把诗人欣喜、惊奇的神态表现得维妙维肖，十分传神。即使说久别初见时悲喜交集的心情神态，尽见于三字之中，也是不为过的。\n\n　　颈联和尾联接写深夜在馆中叙谈的情景。相逢已难，又要离别，其间千言万语，不是片时所能说完的，所以诗人避实就虚，只以景象渲染映衬，以景寓情了。寒夜里，一束暗淡的灯火映照着蒙蒙的夜雨，竹林深处，似飘浮着片片烟云。\n\n　　孤灯、寒雨、浮烟、湿竹，景象是多么凄凉。诗人写此景正是借以渲染伤别的气氛。其中的孤、寒、湿、暗、浮诸字，都是得力的字眼，不仅渲染映衬出诗人悲凉暗淡的心情，也象征着人事的浮游不定。二句既是描写实景，又是虚写人的心情。\n\n　　结处表面上是劝饮离怀，实际上却是总写伤别。用一“更”字，就点明了即将再次离别的伤痛。“离怀惜共传”，在惨淡的灯光下，两位友人举杯劝饮，表现出彼此珍惜情谊和恋恋不舍的离情。惜，珍惜。诗人用在此处，自有不尽的情意。综观全诗，中四句语极工整，写悲喜感伤，笼罩寒夜，几乎不可收拾。但于末二句，却能轻轻收结，略略冲淡。这说明诗人能运笔自如，具有重抹轻挽的笔力。', poem_tags = '唐诗三百首,惜别,友情' WHERE poem_title = '云阳馆与韩绅宿别' AND poem_author = '司空曙';
UPDATE edu_poem SET poem_translation = '黄昏时分，猿声凄切，江边送客早已四散。江水滚滚，一片苍茫，独自更觉伤心悲凉。\n同被贬逐漂泊，只是君行更远。青山万里，我真是挂念你的一叶扁舟。', poem_notes = '重送：是指因为这以前诗人已写过一首同题的五言律诗。刘、裴曾一起被召回长安又同遭贬谪，同病相怜，发为歌吟，感情真挚动人。\n裴郎中：不详何人，大致为诗人的朋友。二人同时被贬官。\n吉州：治所在今江西吉安。\n暮江：日落时的江边。\n逐臣：被贬官而同时离开京城的人。指作者与裴郎中同时被贬。', poem_tags = '送别,写景,抒情' WHERE poem_title = '重送裴郎中贬吉州' AND poem_author = '刘长卿';
UPDATE edu_poem SET poem_translation = '野兔往来任逍遥，山鸡落网惨凄凄。在我幼年那时候，人们不用服兵役；在我成年这岁月，各种苦难竟齐集。长睡但把嘴闭起！\n野兔往来任逍遥，山鸡落网悲戚戚。在我幼年那时候，人们不用服徭役；在我成年这岁月，各种忧患都经历。长睡但把眼合起！\n野兔往来任逍遥，山鸡落网战栗栗。在我幼年那时候，人们不用服劳役；在我成年这岁月，各种灾祸来相逼。长睡但把耳塞起！', poem_notes = '爰（音缓）：缓之借，逍遥自在。离：同罹，陷，遭难。罗：罗网。\n为：指徭役。郑笺：“为，谓军役之事也。”\n罹：忧。\n无吪（音俄）：不说话。一说不动。\n罦（音浮）：一种装设机关的网，能自动掩捕鸟兽，又叫覆车网。\n造：指劳役。朱熹《诗集传》：“造，亦为也。”\n觉：清醒。\n罿（音冲）：捕鸟兽的网。\n庸：指劳役。郑笺：“庸，劳也。”\n聪：听觉。', poem_appreciation = '这是一首伤时感事的诗。《毛诗序》说：“《兔爰》，闵周也。桓王失信，诸侯背叛，构怨连祸，王师伤败，君子不乐其生焉。”这是依《左传》立说，有史实根据，因此《毛诗序》说此诗主题不误。但意谓作于桓王时，与诗中所写有出入。崔述《读风偶识》说：“其人当生于宣王之末年，王室未骚，是以谓之‘无为’。既而幽王昏暴，戎狄侵陵，平王播迁，室家飘荡，是以谓之‘逢此百罹’。故朱子云：‘为此诗者盖犹及见西周之盛。’（见朱熹《诗集传》）可谓得其旨矣。若以为在桓王之时，则其人当生于平王之世，仳离迁徙之余，岂得反谓之为‘无为’？而诸侯之不朝，亦不始于桓王，惟郑于桓王世始不朝耳。其于王室初无所大加损，岂得遂谓之为‘百罹’、‘百凶’也哉？窃谓此三篇者（按：指《中谷有蓷》、《葛藟》及此篇）皆迁洛者所作。”\n\n　　诗共三章，各章首二句都以兔、雉作比。兔性狡猾，用来比喻小人；雉性耿介，用以比喻君子。罗、罦、罿，都是捕鸟兽的网，既可以捕雉，也可以捉兔。但诗中只说网雉纵兔，意在指小人可以逍遥自在，而君子无故遭难。通过这一形象而贴切的比喻，揭示出当时社会的黑暗。\n\n　　各章中间四句，是以“我生之初”与“我生之后”作对比，表现出对过去的怀恋和对现在的厌恶：在过去，没有徭役（“无为”），没有劳役（“无造”），没有兵役（“无庸”），我可以自由自在地生活；而现在，遇到各种灾凶（“百罹”“百忧”“百凶”），让人烦忧。从这一对比中可以体会出时代变迁中人民的深重苦难。这一句式后来在传为东汉蔡琰所作的著名长篇骚体诗《胡笳十八拍》中被沿用，“我生之初尚无为，我生之后汉祚衰；天不仁兮降乱离，地不仁兮使我逢此时”，那悲怆的诗句，是脱胎于《兔爰》一诗。\n\n　　各章最后一句，诗人发出沉重的哀叹：生活在这样的年代里，不如长睡不醒。愤慨之情溢于言表。方玉润说：“‘无吪’、‘无觉’、‘无聪’者，亦不过不欲言、不欲见、不欲闻已耳”（《诗经原始》），这也是《毛诗序》中所点出的君子“不乐其生”的主题。\n\n　　全诗三章风格悲凉，反覆吟唱诗人的忧思，也正是《王风》中的黍离之悲，属乱世之音、亡国之音，方玉润评云：“词意凄怆，声情激越，（三国魏）阮步兵（籍）专学此种。”（《诗经原始》）', poem_tags = '诗经,伤怀' WHERE poem_title = '国风·王风·兔爰' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '舞师喜洋洋，左手握笙簧，右手招我奏“由房”。心里乐又爽！\n舞师乐陶陶，左手摇羽毛，右手招我奏“由敖”。快乐真不少！', poem_notes = '君子：指舞师。阳阳：洋洋得意。\n簧：古乐器名，竹制，似笙而大。\n我：舞师（君子）的同事。由房：为一种房中乐。毛传：“由，用也。国君有房中之乐。”胡承珙《毛诗后笺》：“由房者，房中，对庙朝言之。人君燕息时所奏之乐，非庙朝之乐，故曰房中。”一说由房即游放。\n只且（音居）：语助词。\n陶陶：和乐舒畅貌。\n翿（音道）：歌舞所用道具，用五彩野鸡羽毛做成，扇形。\n由敖：当为舞曲名。马瑞辰《毛诗传笺通释》：“敖，疑当读为骜夏之骜，《周官·钟师》：奏九夏，其九为骜夏。”郑笺：“右手招我，欲使我从于燕舞之位。”朱熹《诗集传》：“骜，舞位也。”', poem_appreciation = '按余冠英的说法，这是一首描写歌舞晚会场面的小诗，只有欢乐而已，没有多深的政治意义。\n\n　　在一个贵族欢宴的场合，有一个身份高贵的青年男子，在中央为大家起舞助兴。只见他一幅少年得志、得意洋洋之态，边舞蹈边吹奏笙竽之类乐器，人们欢呼雷动。他得意之际，便左手执定乐器，右手来招呼诗人与他协奏《由房》之乐。受这种氛感染，人人都能感到无比欢欣快乐。接着写这位男子狂欢之余，放下乐器，开始跳起舞来，其乐陶陶，令人陶醉。他左手执定羽旄，右手招诗人与他共舞《由敖》之曲。场面欢畅淋漓。\n\n　　诗共二章，摄取了两组歌舞的画面，一是奏“由房”、一是舞“由敖”。“由房”可能是“由庚”、“由仪”一类的笙乐，属房中之乐。胡承珙《毛诗后笺》：“由房者，房中，对庙朝言之。人君燕息时所奏之乐，非庙朝之乐，故曰房中。”而“由敖”可能即骜夏，马瑞辰《毛诗传笺通释》：“敖，疑当读为骜夏之骜， 《周官·钟师》：奏九夏，其九为骜夏。”今天已不知两舞曲的内容，但从君子（舞师）“阳阳”、“陶陶”等神情上看，当是两支欢快的舞乐。“其乐只且”恰恰说明其乐之甚。“只”，韩诗作“旨”；《诗三家义集疏》：“旨本训美，乐旨，犹言乐之美者，意为乐甚。”\n\n　　诗的格调流美。所演奏的是房中宴乐，乐曲比较轻快，而演奏者本人也自得其乐，《程子遗书）：“阳阳，自得。陶陶，自乐之状。皆不任忧责，全身自乐而已。”想见舞师与乐工是乐在其中。诗人为乐工，故诗中“我”在描写歌舞场面时也就比较轻快这与《王风》其他篇章那种苍凉的风格迥然不同。\n\n　　如果按朱熹的解释，此诗写夫妻歌舞为乐。丈夫邀请妻子一起跳舞，由妻子唱出来，表现了他们自得自乐、欢畅无比的情绪。古代的文学作品中，写夫妻恩爱、歌舞自娱的情形并不多，多的是征夫愁弃妇怨。因为这样做，至少要这样一些前提：两个人情深意笃，有较高的修养和情趣，以及拥有较多的闲暇。日出而作、日落而息的夫妻，大字不识的衣夫，恐怕难以歌舞自娱。由此可以推断，此诗的主人公大概应是殷实人家，或是已经衰落了的世家子弟。这也容易让人想到，闲暇是人们自娱自乐、吟诗作画、游山玩水的重要前提。整日为生计而忙碌的人，不会有此雅兴。', poem_tags = '诗经' WHERE poem_title = '君子阳阳' AND poem_author = '佚名';
UPDATE edu_poem SET poem_tags = '写景,抒情,胸怀' WHERE poem_title = '忆秦娥·娄山关' AND poem_author = '毛泽东';
UPDATE edu_poem SET poem_translation = '注释 白玉堂：这里形容柳絮所处高贵。春解舞：说柳花被春风吹散，像翩翩起舞。 均匀：指舞姿柔美，缓急有度。 “蜂围”句：意思是成群蜂蝶纷纷追随柳絮。有人以为是以蜂蝶之纷乱比飞絮，亦通。 随逝水：落于水中，随波流去。喻虚度年华。以逝水比光阴。 委芳尘：落于泥土中。喻处于卑贱的地位。 “万缕”二句：意谓不管柳絮是否从枝上离去，柳树依旧长条飘拂。喻不因别人对我的亲疏而改变自己固有的姿态。 青云：高天。也用以说名位极高。如《史记·伯夷列传》：“闾巷之人欲砥行立名，非附青云之士，恶能施于后世哉？”', poem_appreciation = '薛宝钗与林黛玉这两个人物的思想、性格是对立的。作者让宝钗作欢愉之词，来翻黛玉之所作情调缠绵悲戚的案，看上去只是写诗词吟咏上互相争胜，实际上这是作者借以刻划不同的思想性格特征的一种艺术手段。\n\n　　但是，作者所写的钗、黛对立，并非如续书中所写的那样为了争夺同一个婚姻对象而彼此成为情敌（黛玉对宝钗的猜疑，在第四十二回“薛芜君兰言解疑癖”后已不复存在。事实如脂评指出，贾府上下，人人心目中宝黛都是一对未来的“好夫妻”），作者也并不想通过他们的命运来表现封建包办婚姻的不合理。作者所描写的宝黛悲剧是与全书表现封建大家庭败亡的主题密切相关的。他们的悲剧是贾府事变的结果。\n\n　　细看词的双关隐义，不难发现“蜂围蝶阵乱纷纷”正是变故来临时大观园纷乱情景的象征。宝钗一向以高洁自持，“丑祸”当然不会沾惹到她的身上，何况她颇有处世的本领，所以词中以“解舞”、“均匀”自诩。黛玉就不同了，她不禁聚散的悲痛，就像落絮那样“随逝水”、“委芳尘”了。宝钗能“任他随聚随分”而“终不改”故态，所以黛玉死后客观上就必然造成“金玉良缘”的机会而使宝钗青云直上。但这种结合并不能从根本上消除宝钗和宝玉在对待封建礼教、仕途经济上的思想分歧，也不能使宝玉忘怀死去的知己而倾心于她。所以，宝钗最终仍不免被宝玉所弃，词中的“本无根”也就是这个意思。', poem_tags = '咏物,柳树,写风' WHERE poem_title = '临江仙·柳絮' AND poem_author = '曹雪芹';
UPDATE edu_poem SET poem_translation = '鉴赏 　　《凤凰台上忆吹箫·寸寸微云》这首词是为别韩西而作，细腻地表现了作者内心抑郁的情绪，再现与女友分别使她堕入深渊的情景。巧用叠字抒情写意，堪与词作大家李清照的“寻寻觅觅，冷冷清清，凄凄惨惨戚戚”之句媲美，并将她后半生的酸楚尽相倾诉。这首词，情境哀凄，词义悲苦。“偷素粉、写写描描。谁还管，生生世世，夜夜朝朝。”用双字二十余叠，丝毫不露牵强痕迹。末尾三句，“谁还管，生生世世，夜夜朝朝”更是余怨无穷，紧紧扣人心弦，令人动容。此词通篇语言质朴，且巧用叠字，造成回环咏叹的艺术效果，缠绵悱恻，旋律优美，可谓情苦词哀，已达极致，加上连用叠字二十余韵，真可与李易安的《声声慢》相媲美，确是双卿自述境况的凄绝的哀 展开阅读全文 ∨', poem_appreciation = '鉴赏 　　《凤凰台上忆吹箫·寸寸微云》这首词是为别韩西而作，细腻地表现了作者内心抑郁的情绪，再现与女友分别使她堕入深渊的情景。巧用叠字抒情写意，堪与词作大家李清照的“寻寻觅觅，冷冷清清，凄凄惨惨戚戚”之句媲美，并将她后半生的酸楚尽相倾诉。这首词，情境哀凄，词义悲苦。“偷素粉、写写描描。谁还管，生生世世，夜夜朝朝。”用双字二十余叠，丝毫不露牵强痕迹。末尾三句，“谁还管，生生世世，夜夜朝朝”更是余怨无穷，紧紧扣人心弦，令人动容。此词通篇语言质朴，且巧用叠字，造成回环咏叹的艺术效果，缠绵悱恻，旋律优美，可谓情苦词哀，已达极致，加上连用叠字二十余韵，真可与李易安的《声声慢》相媲美，确是双卿自述境况的凄绝的哀歌。 ▲', poem_tags = '离别,伤怀' WHERE poem_title = '凤凰台上忆吹箫·寸寸微云' AND poem_author = '贺双卿';
UPDATE edu_poem SET poem_translation = '明亮的蜡烛吐着缕缕青烟，高举金杯面对精美丰盛的席宴。饯别的厅堂里回忆着朋友的情意融洽，分别后要绕山过水，路途遥远。宴席一直持续到明月隐蔽在高树之后，银河消失在拂晓之中。走在这悠长的洛阳道上，不知什么时候才能相会？', poem_notes = '琴瑟：比喻友情。\n长河：指银河。\n注解：首联采用对偶句形式，“青”与“绮”相对，都为绿色的意思。', poem_appreciation = '陈子昂的《春夜别友人》共两首，这是第一首。约作于公元684年（武则天光宅元年）春。时年二十六岁的陈子昂离开家乡四川射洪，奔赴东都洛阳，准备向朝廷上书，求取功名。临行前，友人设宴欢送他。席间，友人的一片真情触发了作者胸中的诗潮。旋即写成这首离别之作。\n\n　　这首律诗一开头便写别筵将尽，分手在即的撩人心绪和寂静状态。作者抓住这一时刻的心理状态作为诗意的起点，径直但却自然地进入感情的高潮，情怀颇为深挚。“银烛吐青烟”，着一“吐”字，使人想见离人相对无言，怅然无绪，目光只是凝视着银烛的青烟出神的神情。“金樽对绮筵”，用一“对”字，其意是面对华筵，除却频举金樽“劝君更尽一杯酒”的意绪而外，再也没有什么可以勉强相慰的话了。此中境界，于沉静之中更见别意的深沉。\n\n　　颔联“离堂思琴瑟，别路绕山川”，“琴瑟”指朋友宴会之乐，源出《小雅·鹿鸣》“我有嘉宾，鼓琴鼓瑟”，是借用丝弦乐器演奏时音韵谐调来比拟情谊深厚的意思。“山川”表示道路遥远，与“琴瑟”作为对仗，相形之下，不由使人泛起内心的波澜：“离堂”把臂，伤“琴瑟”之分离；“别路”迢遥，恨“山川”之缭绕。这两句着意写出了离情的缠绵，令人感慨唏嘘。\n\n　　颈联“明月隐高树，长河没晓天”，承上文写把臂送行，从室内转到户外的所见。这时候，高高的树荫遮掩了西向低沉的明月；耿耿的长河淹没在破晓的曙光中。这里一个“隐”字，一个“没”字，表明时光催人离别，不为离人暂停须臾，难舍难分时刻终于到来了。\n\n　　结尾两句写目送友人沿着这条悠悠无尽的洛阳古道踽踽而去，不由兴起不知何年何月再能相聚之感。末句着一“何”字，强调后会难期，流露了离人之间的隐隐哀愁。\n\n　　这首诗中作者没有套用长吁短叹的哀伤语句，却在沉静之中见深挚的情愫。而要达到这样的境界，应不温不火。“火”则悲吟太过而感情浅露；“温”则缺乏蕴藉而情致不深。此诗写离情别绪意态从容而颇合体度，有如琵琶弦上的淙淙清音，气象至为雍雅，不作哀声而多幽深的情思。\n\n　　此诗通篇畅达优美，除了开头一联因场面描写之需而适当选用华丽辞藻外，其余用语都不加藻饰，平淡自然。他所追求的乃是整首诗的深厚和雅。清人纪昀说得好：“此种诗当于神骨气脉之间得其雄厚之味，若逐句拆开，即不得其佳处。如但摹其声调，亦落空腔”。再有，此诗虽写眼前景，心中情，却有所继承和借鉴。有人指出，它“从小谢《离夜》一首脱化来”。《离夜》即谢朓《离夜同江丞王常侍作》，也是写一次夜宴。两相比较可知，陈诗在章法、用语等方面都明显受了谢诗影响。但陈子昂并没有简单地模拟前人，而是有所创新。谢诗较直露和简洁，陈诗则婉转而细腻，在结构上更善于回环曲折地精心布局，情和景的安排上，先以秾丽之笔铺写宴会之盛，次以婉曲之调传达离别之愁，再以宏大的时空背景烘托出宴会之久与友谊之长，最后以展望征途来结束全篇，层次分明。通篇情景合一，从优美的意象描写中自然地流露感情。胜于一般的离别之作。', poem_tags = '离别,宴饮,相思' WHERE poem_title = '春夜别友人二首·其一' AND poem_author = '陈子昂';
UPDATE edu_poem SET poem_translation = '片写梨花开放的时间、风姿、周围的环境。前两句点出梨花开于晚春的寒食节前后，“春游浩荡”表明是芳草萋萋、漫天飞花的暮春季节。“白锦”二句，以白锦和白雪比喻梨花的洁白无瑕与香花烂漫的盛开模样，反用岑参的“忽如一夜春风来，千树万树梨花开”，形象真实而鲜明。“静夜”至上片末，写梨花开放的环境，暮霭沉沉天地阔的静夜里，梨花悄悄地绽放在月光溶溶的夜色中。“冷”字，生动地烘托出宁静、微寒的夜景，使读者想到曹雪芹的“冷月葬花魂”。人间与天上都溶浸在皓月与花色交织而成的氛围中，月光皎洁、花似雪明，给人一种高洁、脱俗的感受。\n\n　　下片前三句用典，继续以“天姿灵秀”的姑射真人来比喻梨花，', poem_tags = '咏物,梨花' WHERE poem_title = '无俗念·灵虚宫梨花词' AND poem_author = '丘处机';
UPDATE edu_poem SET poem_translation = '西北部的军队士兵会整理戎装，打扮自己，早晚在黄河转弯的地方奔驰狩猎。\n在不绝的豪壮燕歌声中，边塞的鸿雁高飞，放牧的马儿叫着。春天快到了，地上的草开始转绿。', poem_notes = '蕃州：泛指西北地区。\n结束：装束，打扮。\n燕歌：泛指悲壮的燕地歌曲。', poem_appreciation = '唐代边塞诗不乏雄浑之作，然而毕竟以表现征戍生活的艰险和将士思乡的哀怨为多。即使一些著名的豪唱，也不免夹杂危苦之词或悲凉的情绪。当读者翻到李益这篇塞上之作，感觉便很不同，一下子就会被那天地空阔、人欢马叫的壮丽图景吸引住。它在表现将士生活的满怀豪情和反映西北风光的壮丽动人方面，是比较突出的。\n\n　　1.诗中“蕃州”乃泛指西北边地（唐时另有蕃州，治所在今广西宜山县西，与黄河不属），“蕃州部落”则指驻守在黄河河套（“黄河曲”）一带的边防部队。军中将士过着“岁岁金河复玉关，朝朝马策与刀环”的生活，十分艰苦，但又被磨炼得十分坚强骁勇。首句只夸他们“能结束”，即善于戎装打扮。作者通过对将士们英姿飒爽的外形描写，示意读者其善战已不言而喻，所以下句写“驰猎”，不复言“能”而读者自可神会了。\n\n　　2.军中驰猎，不比王公们佚游田乐，乃是一种常规的军事训练。健儿们乐此不疲，早晚都在操练，作好随时迎敌的准备。正是“为报如今都护雄，匈奴且莫下云中”（同组诗其四）。“朝暮驰猎黄河曲”的行动，表现出健儿们慷慨激昂、为国献身的精神和决胜信念，句中饱含作者对他们的赞美。\n\n　　这两句着重刻画人物和人物的精神风貌，后两句则展现人物活动的辽阔背景。西北高原的景色是这样壮丽：天高云淡，大雁群飞，歌声飘荡在广袤的原野上，马群在绿草地撒欢奔跑，是一片生气蓬勃的气象。\n\n　　3.征人们唱的“燕歌”，有人说就是《燕歌行》的曲调。目送远去的飞雁，歌声里诚然有北国战士对家乡的深切怀念。然而，飞鸿望断而“燕歌未断”，这开怀放歌中，也未尝不包含歌唱者对边地的热爱和自豪情怀。如果说这一点在三句中表现尚不明显，那么读末句就毫无疑义了。\n\n　　4.“牧马群嘶边草绿”。在赞美西北边地景色的诗句中，它几乎可与“风吹草低见牛羊”的奇句媲美。“风吹草低”句是写高原秋色，所以更见苍凉；而“牧马群嘶”句是写高原之春，所以有油然生意。“绿”字下得绝佳。因三、四对结，上曰“塞鸿飞”，下对以“边草绿”，可见“绿”字是动词化了。它不尽然是一片绿油油的草色，而且写出了“离离原上草”由枯转荣的变化，暗示春天不知不觉又回到草原上。这与后来脍炙人口的王安石的名句“春风又绿江南岸”，都以用“绿”字见胜。在江南，春回大地，是啼鸟唤来的。而塞北的春天，则由马群的欢嘶来迎接。“边草绿”与“牧马群嘶”连文，意味尤长；似乎由于马嘶，边草才绿得更为可爱。诗所表现的壮美豪情是十分可贵的。', poem_tags = '边塞,将士,生活,写景' WHERE poem_title = '塞下曲·其一' AND poem_author = '李益';
UPDATE edu_poem SET poem_translation = '吴头楚尾之地的路是坎坷还是顺坦？在细雨之中慢慢进了深秋，秋天的江水暗自起伏。\n晚上趁着寒冷的潮水渡过江去，眼中尽是黄叶，耳边尽是雁嘶。', poem_notes = '吴头楚尾：今江西北部，此地春秋时是吴楚两国交界的地方。\n烟雨：蒙蒙细雨。\n寒潮：寒冷的潮水。', poem_tags = '秋天' WHERE poem_title = '江上' AND poem_author = '王士祯';
UPDATE edu_poem SET poem_translation = '楚襄王曾梦遇神女。此喻好事如梦。\n伊行：你这里。', poem_tags = '写景,抒情' WHERE poem_title = '临江仙·浅浅余寒春半' AND poem_author = '晏几道';
UPDATE edu_poem SET poem_translation = '扬州的少女们无忧无虑，笑脸迎人，娇美的脸上怎能藏住眼泪，她们可爱的眉梢上所挂的一点忧愁也容易被人察觉。\n天下明月的光华有三分吧，可爱的扬州啊，你竟然占去了两分。', poem_notes = '扬州：今江苏省扬州市。\n萧娘：南朝以来，诗词中的男子所恋的女子常被称为萧娘，女子所恋的男子常被称为萧郎。\n脸薄：容易害羞，这里形容女子娇美。\n胜：能承受。\n桃叶：晋代王献之有妾名桃叶，笃爱之，故作《桃叶歌》（南朝陈僧智匠《古今乐录》载）。后常用作咏歌妓的典故。这里代指所少女的代称或指思念的佳人。\n觉：察觉。\n天下三分：《论语》有“三分天下有其二以服事殷勤。”\n无赖：杜甫《奉陪郑驸马韦曲二首》有“韦曲花无赖，家家恼杀人”句，本意是可爱，反说它无赖，无赖正是爱惜的反话。陆游诗：“江水不胜绿，梅花无赖香。”也有可爱、可喜意。', poem_appreciation = '《忆扬州》是一首怀人的作品，但标题却不明题怀人，而偏说怀地。诗人并不着力描写这座“绿扬城郭”的宜人风物，而是以离恨千端的绵绵情怀，追忆当日的别情。不写自己的殷切怀念，而写远人的别时音容，以往日远人的情重，衬出诗人自己情怀的不堪，这是深一层的写法。\n\n　　前两句“萧娘脸薄难胜泪，桃叶眉尖易觉愁”，极写当日的别离景象。所谓“相见时难别亦难”，“萧娘”、“桃叶”均代指所思；“愁眉”、“泪眼”似是重复，而用一个“难”字和一个“易”字表达出来，不但不显得累赘，反而有反复留连、无限萦怀之感。当日的愁眉，当日的泪眼，以及当日的惨痛心情，都作成别离后无穷的思念。\n\n　　后两句“天下三分明月夜，二分无赖是扬州”，在这思念殷切的时候，诗人唯觉一片惆怅，没有可以诉说的人，于是，抬头而见月，但此月偏偏又是当时扬州照人离别之月，更加助愁添恨。虽然时光冲淡了当日的凄苦，却割不断缠绵的思念。这种挣不断、解不开的心绪，本与明月无关，但它曾照过离人的泪眼，好比对人有情，而离别后偏偏照着愁人，又好像无动于衷，这便显得“可憎”。诗人在深夜抬头望月的时候，原本欲解脱这一段愁思，却想不到月光又来缠人，所以说“明月无赖”。“无赖”二字，原本有褒和贬的两重意义，这里因明月恼人，有抱怨的意思。但后世因为惊赏这种扬州明月的新奇形象，就离开了诗人原意，把它截下来只作为描写扬州夜月的传神警句来欣赏，这时的“无赖”二字又成为爱极的昵称了。这也是形象有时会大于作者构思的一例。\n\n　　古人律体绝句的结尾处，有时用一种叫做“一笔荡开”的方法，往往会产生一种“寄意无穷”的效果。这首诗所不同的，是它不在第四句用，而在第三句时即已“荡开”。说愁眉，说泪眼，虽然作者余情未尽，而其他的事情已不必增添，于是忽然揽入一轮明月，以写无可奈何的情态，体现了构思的险谲。这两句看似将全诗截为两段，实际上则是欲断不断，题中用“忆”字，将全诗连贯起来，依然是“剪不断，理还乱”的“别是一般滋味”。本来月光普照，遍及人寰，并不偏宠扬州。而扬州的魅力，也不是仅在月色。诗为传神，有时似乎违反常理，却能深入事理骨髓。“三分”、“无赖”的奇幻设想，也有它的渊源与影响。《论语》中有“三分天下有其二以服事殷勤。”不过这是赞颂周文王的句子，没有半点诗意。谢灵运说：“天下才有一石，曹子建独占八斗，我得一斗，天下共分一斗。”而徐凝这首诗中的“三分之二”不但是诗意的，而且是新奇的。这些数目字，都不可以常理而论，而具有很强的艺术效果，致使后世之人对扬州的向往如醉如痴，“二分明月”成为扬州的代称。此后宋人苏轼的《水龙吟·和章质夫杨花》中“春色三分，二分尘土，一分流水”也不逊色。至于“月色无赖”，后世如王安石“春色恼人眠不得，月移花影上栏杆”中的“春色恼人”，即运用了同一手笔。\n\n　　诗人把扬州明月写到了入神的地步，并用“无赖”之“明月”，把扬州装点出无限的风姿，与《忆扬州》的标题吻合无间，使人向往扬州的美好。这也许是诗人有意的安排，这种大胆的艺术构思所产生的效果，令人为之惊叹。', poem_tags = '怀人' WHERE poem_title = '忆扬州' AND poem_author = '徐凝';
UPDATE edu_poem SET poem_translation = '关中兵荒马乱百姓流离失所，躲避战乱漂泊流浪来到西南。\n长久地停留三峡楼台熬日月，与五溪民族都住在一片云山。\n羯胡人狡诈事主终究不可靠，伤时感世的诗人至今未回还。\n梁代庾信的一生处境最凄凉，到晚年作的诗赋轰动了江关。', poem_notes = '支离：流离。风尘：指安史之乱以来的兵荒马乱。\n楼台：指夔州地区的房屋依山而建，层迭而上，状如楼台。淹：滞留。日月：岁月，时光。\n五溪：指雄溪、樠溪、酉溪、潕溪、辰溪，在今湘、黔、川边境。共云山：共居处。\n羯（jié）胡：古代北方少数民族，指安禄山。\n词客：诗人自谓。未还：未能还朝回乡。\n庾（yǔ）信：南北朝诗人。\n动江关：指庾信晚年诗作影响大。“江关”指荆州江陵，梁元帝都江陵。', poem_tags = '唐诗三百首,怀古,感叹' WHERE poem_title = '咏怀古迹五首·其一' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '一路上经过的地方，青苔小道留下鞋痕。\n白云依偎安静沙洲，春草环绕道院闲门。\n新雨过后松色青翠，循着山路来到水源。\n看到溪花心神澄静，凝神相对默默无言。', poem_notes = '莓苔：一作“苍苔”，即青苔。履痕：一作“屐痕”，木屐的印迹，此处指足迹。\n渚：水中的小洲。一作“者”。\n春草：一作“芳草”。\n“溪花”两句：因悟禅意，故也相对忘言。禅：佛教指清寂凝定的心境。', poem_appreciation = '全诗围绕着题目的“寻”字，逐渐展开。“一路经行处，莓苔见履痕”，开始二句就突出一个“寻”字来，顺着莓苔履痕（一作“屐痕”），一路寻来。语言浅淡质朴，似乎无须赘言：那人迹罕至的清幽山径，正是常道士出入往来之地，这里没有人间喧嚣，满路莓苔。履痕屐齿给来访者带来希望和猜想：幽人不远，晤面在即；否则就是其人出晤，相会须费些周折。\n\n　　颔联写由顺其路而始入其居境。两句写景平列，用意侧重“闭门”寻人不遇。“白云依静渚”，为远望。\n\n　　白云絮絮，缭绕小渚。“依”字有意趣。越溪（或是缘溪）而至其巖扉，近看则“春草闭闲门”，蓬门长闭，碧草当门，道士不在寓所。如果说一路莓苔给人幽静的印象，那么这里的白云、芳草、静渚、闲门，则充满静穆淡逸的氛围。渚是“静”的，白云、芳草也是静静的。门“闲”，不遇之人，来访者不期然而然的心境也“闲”。一切都显得恬静自然，和谐默契，不受丝毫纷扰。在自然景物的观照中，悄然融入自在平静的心绪，来访不遇的怅然，似乎被这清幽、宁静的环境，带有内省参照的“禅意”所冲化，渐趋恬然。\n\n　　独闭的闲门，摇曳的小草，使人浸润在“绿满窗前草不除”的幽静自在境界，滋味咸化于这静默的世界之中。\n\n　　上四句叙寻而不遇，意绪明白。后四句继写一路景观，浑化无迹须缓缓味出。“过雨看松色，随山到水源”。这看松寻源，所趋何向，是不遇而再寻，还是顺便一游其山，还是返回，诗人没有说出。两句以景带叙，下句叙事成份更多些。“水源”，应该不是指来时“经行处”，所以“随山”不是下山，而是入山，随山转折，缘山道探寻水源。道士不在寓所，因此这寻水源，也就是寻道士，“随”字简洁，山道纡绕，峰回路转，随山探源，缘水经山。其间林壑深秀，水声潺潺，都由这个“随”字导人神游，启迪丰富的“曲径通幽”的想象。上句“过雨看松色”，或指道士居所“门外景”，或指“随山”时的景致。“过雨”暗示忽然遇雨，诗人仅仅用一“过”字表示它的刚刚存在，而着意于雨霁云收之后翠绿生新的松色。“过”字，把阵雨带来的清新宜人的气息、物色，轻松自然地托显出来，同时也隐隐带出漫步山道的时间进程。\n\n　　“过雨”，涮新了松色，也带来冥想。自生自灭的短暂一“过”，和静静白云一样，已在写“禅意”（金性尧）。\n\n　　尾联的“禅意”，用得精妙。诗人看见了“溪花”，却浮起“禅意”，从幽溪深涧的陶冶中得到超悟，从摇曳的野花静静的观照中，领略到恬静的清趣，溶化于心灵深处是一种体察宁静，荡涤心胸的内省喜悦，自在恬然的心境与清幽静谧的物象交融为一。况且禅宗本来就有拈花微笑的故事，这都溶入默契不言的妙悟中，而领会出“禅意”，因用“与”，把物象和情感联结起来。禅宗的妙悟和道家的得意忘言，有内在相通之处。佛道都喜占山林，幽径寻真，荡入冥思，于此佛道互融，而进入“相对亦忘言”的精神境界。\n\n　　芳草松色、白云溪花的美感，“禅意”默想的清享，都清美极了。乘兴而来，兴尽而返的惬意自得的感受，也都含融在诗的“忘言”之中。', poem_tags = '唐诗三百首,写景' WHERE poem_title = '寻南溪常山道人隐居 / 寻南溪常道士' AND poem_author = '刘长卿';
UPDATE edu_poem SET poem_translation = '自从你离开家乡远行，我再不去动破旧织机。\n想念你犹如天边圆月，一夜一夜减弱了光辉。', poem_notes = '赋得：凡摘取古人成句为题之诗，题首多冠以“赋得”二字。“自君之出矣”是乐府诗杂曲歌辞名。\n君之出矣：夫君离家。之，助词，无实际意义。矣，了。\n不复：不再。理残机：理会残破的织布机。\n思：思念。满月：农历每月十五夜的月亮。\n减：减弱，消减。清辉：指皎洁的月光。', poem_appreciation = '此诗是赋得体，无论是赋诗得题，还是赋诗得句，总之是拟作。自六朝至唐代，拟此者代不乏人。诗人拟之，自是一次学诗演练。\n\n　　首句“自君之出矣”，即拈用成句。良人离家远行而未归，表明了一个时间概念。良人离家有多久，诗中没有说，只写了“不复理残机”一句，发人深思：首先，织机残破，久不修理，表明良人离家已很久，女主人长时间没有上机织布了；其次，如果说，人去楼空给人以空虚寂寥的感受。那么，君出机残也同样使人感到景象残旧衰飒，气氛落寞冷清；再次，机上布织来织去，始终未完成，它仿佛在诉说，女主人心神不定，无心织布，内心极其不平静。\n\n　　以上，是对事情起因的概括介绍，接着，诗人便用比兴手法描绘她心灵深处的活动：“思君如满月，夜夜减清辉。”古诗十九首中，以“相去日已远，衣带日已缓”（《古诗十九首·行行重行行》）直接描摹思妇的消瘦形象，写得相当具体突出，而在这里，诗人用皎皎明月象征思妇情操的纯洁无邪，忠贞专一。“夜夜减清辉”，写得既含蓄婉转，又真挚动人。比喻美妙贴切，想象新颖独特，使整首诗显得清新可爱，充满浓郁的生活气息。', poem_tags = '乐府,闺怨,妇女,相思' WHERE poem_title = '赋得自君之出矣' AND poem_author = '张九龄';
UPDATE edu_poem SET poem_translation = '远万里跨海渡江，征讨辽东，终于剪除了辽东巨寇，使风云弥漫的战场硝烟归于平静。此时正应当熔化兵器放养马牛，尽享太平。将士们班师回朝，在京都设宴庆功。酒席上歌舞欢闹，更显现出军威。战士们开怀畅饮，直到醉了方才归去。我盛大之国，决不会去辽东白走一遭，空手归来中原，要战就一定会胜利而回！\n\n　　我军威浩荡去平定辽东，敌军被俘虏，我们在战争中取得胜利。我们凯旋而归，在洛阳宫开宴庆功。这次战争取得胜利是全军智慧凝聚的结果，庆功宴上，对全军论功行赏，丝毫不吝惜对大家的封赏。这次征讨辽东获得大的胜利，别说是尚书省这样高级的官员得到了封赏，就连雍齿那样素来有积怨的人也毫不例外。', poem_tags = '乐府,战争' WHERE poem_title = '纪辽东二首' AND poem_author = '杨广';
UPDATE edu_poem SET poem_translation = '黄冈地方盛产竹子，大的粗如椽子。竹匠剖开它，削去竹节，用来代替陶瓦。家家房屋都是这样，因为竹瓦价格便宜而且又省工。\n　　子城的西北角上，矮墙毁坏，长着茂密的野草，一片荒秽，我于是就地建造小竹楼两间，与月波楼相接连。登上竹楼，远眺可以尽览山色，平视可以将江滩、碧波尽收眼底。那清幽静谧、辽阔绵远的景象，实在无法一 一描述出来。夏天宜有急雨，人在楼中如听到瀑布声；冬天遇到大雪飘零也很相宜，好像碎琼乱玉的敲击声；这里适宜弹琴，琴声清虚和畅；这里适宜吟诗，诗的韵味清雅绝妙；这里适宜下棋，棋子声丁丁动听，这里适宜投壶，箭声铮铮悦耳。这些都是竹楼所促成的。\n　　公务办完后的空闲时间，披着鹤氅，戴着华阳巾，手执一卷《周易》，焚香默坐于楼中，能排除世俗杂念。这里江山形胜之外，只见轻风扬帆，沙上禽鸟，云烟竹树一片而已。等到酒醒之后，茶炉的烟火已经熄灭，送走落日，迎来皓月，这也是谪居生活中的一大乐事。\n　　那齐云、落星两楼，高是算高的了；井干、丽谯两楼，华丽也算是非常华丽了，可惜只是用来蓄养妓女，安顿歌儿舞女，那就不是风雅之士的所作所为了，我是不赞成的。\n　　我听竹匠说：“竹制的瓦只能用十年，如果铺两层，能用二十年。”唉，我在至道元年，由翰林学士被贬到滁州，至道二年调到扬州，至道三年重返中书省，咸平元年除夕又接到贬往齐安的调令，今年闰三月来到齐安郡。四年当中，奔波不息，不知道明年又在何处，我难道还怕竹楼容易败坏吗？希望接任我的人与我志趣相同，继我爱楼之意而常常修缮它，那么这座竹楼就不会朽烂了。\n　　咸平二年八月十五日撰记。', poem_notes = '黄冈：今属湖北。\n椽（chuán）：椽子，架在屋顶承受屋瓦的木条。\n刳（kū）：削剔，挖空。\n陶瓦：用泥烧制的瓦。\n比屋：挨家挨户。比，紧挨，靠近。\n子城：城门外用于防护的半圆形城墙。\n雉堞（dié）圮（pǐ）毁：城上矮墙倒塌毁坏。雉堞，城上的矮墙。圮毁，倒塌毁坏。\n月波楼：黄州的一座城楼。\n吞：容纳。\n濑：沙滩上的流水。\n幽阒（qù）辽夐（xiòng）：幽静辽阔。幽阒，清幽静寂。夐，远、辽阔。\n丁丁（zhēng）：形容棋子敲击棋盘时发出的清脆悠远之声。\n投壶：古人宴饮时的一种游戏。以矢投壶中，投中次数多者为胜。胜者斟酒使败者饮。\n助：助成，得力于。\n公退：办完公事，退下休息。\n鹤氅（chǎng）衣：用鸟羽制的披风。\n华阳巾：道士所戴的头巾。\n胜概：美好的生活状况。胜，美好的。概，状况，此指生活状况。\n齐云、落星：均为古代名楼。\n井干、丽谯：亦为古代名楼。\n骚人：屈原曾作《离骚》，故后人称诗人为“骚人”，亦指风雅之士。\n稔（rěn）：谷子一熟叫作一稔，引申指一年。\n至道乙未岁，自翰林出滁上：955年（宋太宗至道元年），作者因讪谤朝廷罪由翰林学士贬至滁州。\n广陵：即现在的扬州。\n又入西掖：指回京复任刑部郎中知制诰。西掖，中书省。\n戊戌岁除日：戊戌年除夕。除日：除夕。戊戌：998年（宋真宗咸平元年）。\n齐安：黄州。\n己亥：999年（咸平二年）。\n嗣而葺（qì）之：继我之意而常常修缮它。嗣，接续、继承。葺，修整。\n庶：表示期待或可能。\n（谪：封建王朝官吏降职或远调。', poem_appreciation = '这篇文章以竹楼为核心，先记叙黄冈多竹，可以用来代替陶瓦，且价廉工省。继而描写在竹楼上可观山水、听急雨、赏密雪、鼓琴、咏诗、下棋、投壶，极尽人间之享乐；亦可手执书卷，焚香默坐，赏景、饮酒、品茶、送日、迎月，尽得谪居的胜概。藉齐云、落星、井干、丽谯各名楼反衬竹楼的诗韵，表明作者甘居清苦、鄙夷声色的高尚情怀。继而写奔走不暇，眷恋竹楼之意。\n\n　　全文具有以下特点：\n\n　　一、结构明晰。文章开篇即写黄州多竹和用竹造屋的好处，为下文详写竹楼作下铺垫。接着作者以声写楼，以声抒情，详写了在楼中可以领略到的种种别处无法领略的清韵雅趣。“远吞”四句写幽静辽阔之景，“夏宜”四句言作者四季不同之感，“宜鼓琴”八句，述竹楼特有之趣。第三段写作者悠闲自得、幽雅飘逸的谪居生活，既回扣上文，又为下文言志张本。文章最后一段，作者借竹楼的命运表达了自己对前途的自信，并交代了写作时间。\n\n　　二、寄慨深远。黄冈竹楼，是作者洁身自好的人格和高远情志的载体，是作者人格力量、人格理想的象征，是作者苦闷心灵聊以栖居的寓所。作者把竹楼写得情趣盎然，实际上抒发了自己的飘泊无定之苦、仕途失意之叹；同时也传达出作者身处逆境而矢志不渝的信念以及庄重自持的思想情操。宦海沉浮的不幸遭遇，不但没有消弥作者积极入世的热情，反而使他有竹楼“听雨如瀑”“闻雪若玉”的从容，有“岂惧竹楼之易朽乎”的自信。\n\n　　三、修辞精警。对比：作者将简易的竹楼与四大名楼对比，以“贮妓女、藏歌舞”的腐朽与“焚香默坐，消遣世虑”的儒雅对比，抒写了作者高洁的品格和磊落的襟抱。象征：四大名楼的高贵象征着朝廷的腐败，竹楼的寒伧却是作者当下自身地位的写照，尽管地位卑微，却拥有高洁的心灵。排比：“夏宜急雨，有瀑布声”以下，连用六“宜”，以三个两两相对的句式，构成有力的排比，生动地写出了竹楼主人的雅洁崇高。\n\n　　该文是作者著名的抒情小品，艺术上很有特色，结构严谨，构思巧妙，层次分明，多用排比，寓情于景，轻快自然，既抒写了作者随遇而安、贬谪不惧的心态，也含蓄地表现了其愤懑不平之情。文章清幽潇洒，可以与欧阳修的《醉翁亭记》相媲美。', poem_tags = '古文观止,咏物,抒情' WHERE poem_title = '黄冈竹楼记' AND poem_author = '王禹偁';
UPDATE edu_poem SET poem_translation = '译文 　　芭蕉叶是那样多情，一片叶子才舒展开一片叶子又生长了。（芭蕉叶初生多卷曲，到一定程度才舒展开，诗人认为就像相思之情那样绵绵不断。）芭蕉自己相思之情舒卷不尽，倒也罢了，风雨吹芭蕉作一片秋声，更能惹动无限愁思。', poem_tags = '咏物,抒情,哀怨' WHERE poem_title = '咏芭蕉' AND poem_author = '郑燮';
UPDATE edu_poem SET poem_tags = '记梦,思念' WHERE poem_title = '菩萨蛮·朔风吹散三更雪' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '在南郊的园林中游春，和暖的春风中，时时听到马的嘶鸣。青青的梅子，才豆粒一样大小，细嫩的柳叶，像眉毛一般秀灵。春日渐长，蝴蝶飞得多么轻盈。\n花上露珠晶莹，春草茂密如烟，这户人家已放下窗帘。她荡罢秋千格外疲倦，轻解罗衣床上眠，伴她的只有梁上双燕。', poem_notes = '踏青：春日郊游。唐宋踏青日期因地而异。有正月初八者．也有二月二日或三月三日者。后世多以清明出游为踏青。\n风和：春风暖和。\n马嘶：指游人车马的声音。嘶，叫。\n青梅如豆柳如眉：青梅结得像豆子那么大，柳叶长得像美人的眉毛。后世多以此句描绘明媚的春日风景。\n日长：过了春分的节令，白天渐渐长了。这里还有整个白天的意思。\n草烟：形容春草稠密。\n帘幕：帘子和帷幕。\n慵（yōng）困：困倦。\n罗衣：香罗衫。\n画堂：彩画装饰的堂屋。', poem_appreciation = '此词描写少妇因游春有感而忆所思的无可排遣之情。　\n\n　　首句点明时序：芳春过半，踏青游赏，戏罢秋千。由动境而归静境，写其季节天色之气氛，闺阁深居之感受，读来宛如亲历。　\n\n　　次句“风和闻马嘶”五字为一篇关键，虽用笔闲淡，不扬不厉，而造境传神，常人难及。“闻马嘶”之宝马振鬣长嘶，成为古人游春这一良辰美景之一种不可或缺的意象。时节已近暮春，青梅结子，小虽如豆，已过花时，柳尽舒青，如眉剪黛；而日长气暖，蝴蝶不知从何而至，翩翩于花间草际，好一幅闹春图画。“蝶蝶飞”以一动作点活了暮春之景。　\n\n　　过片“人家帘幕垂”极写静境。而“花露重，草烟低”，正与写静有关：花觉其露重欲滴，草见其烟伏不浮，正是极静之物境心境下。　\n\n　　“秋千”句是写静至精微处，再以动态一为衬染，然亦虚笔，而非实义。出秋千，写戏罢秋千，只觉慵困，解衣小憩，已是归来之后。既归画堂，忽有双燕，亦似春游方罢，相继归来。不说人归，只说燕归，以燕衬。人，物人一也，不可分辨。然而燕归来，可知天色近晚，由此一切动态，悉归静境。结以燕归，又遥与开篇马嘶相呼应。于是春景芳情，浑然莫辩。\n\n　　前人谓“冯词如古蕃锦，如周、秦宝鼎彝，琳琅满目，美不胜收”。此词写仲春景色，豆梅丝柳，日长蝶飞，花露草烟，秋千慵困，画梁双燕，令人目不暇接。而人物踏青时的心情，则仅于“慵困”、“双燕栖”中略予点泄，显得雍容蕴藉。', poem_tags = '宋词精选,婉约,妇女,春游' WHERE poem_title = '阮郎归·南园春半踏青时' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_tags = '写景,抒情' WHERE poem_title = '临江仙·樱桃落尽春归去' AND poem_author = '李煜';
UPDATE edu_poem SET poem_translation = '(在昨日)蜡烛点点、滴泪成灰，凄凄满别情的送别宴席上，（您的儿子）十岁的韩偓文思敏捷的就像东晋的袁虎一样，走马之间即成文章；\n（不久，您将带您的儿子到果州上任了）在那万里长的丹山路上，桐花盛开，花丛中传来那雏凤的鸣声，一定会比那老凤更为清亮动听（您儿子的才华会比你这只老凤凰的声音还清亮）。\n\n我在靠近剑门栈道的巴蜀之地，你在有风樯的江南，我们俩天各一方。当初分别正值冰天雪地的时候，没想到，现在又到了春暖花开的季节。\n如果将韩冬郎的诗才比作何逊，将我自己比作沈东阳的话，为了休联句，我就要像沈某人般瘦尽了。', poem_notes = '十岁：公元851年（大中五年），韩偓十岁。\n裁诗：作诗。\n走马成：言其作诗文思敏捷，走马之间即可成章。《世说新语·文学》：“桓宣武北征，袁虎时从，被责免官。会须露布文，唤袁倚马前令作。手不辍笔，俄得七纸，殊可观。东亭在侧，极叹其才。”李白《与韩荆州书》：“虽日试万言，倚马可待。”\n冷灰残烛：当是当时饯别宴席上的情景。\n桐花：《诗·大雅·卷阿》：“凤皇鸣矣，于彼高岗。梧桐生矣，于彼朝阳。”。现常用后句，泛指后起之秀将更有作为，不可限量。桐，梧桐，传说凤凰非梧桐不宿。\n丹山：《山海经·南山经》：“丹穴之山，丹水出焉，有鸟焉，其状如鸡，五采而文，名曰凤凰。”《史记·货殖传》：“巴蜀寡妇清，其先得丹穴，而擅其利数世。” 现常用后句，泛指后起之秀将更有作为，不可限量。丹山：传说为凤凰产地。\n雏凤清于老凤声：此戏谑韩瞻，并赞其子韩偓的诗才。《晋书·陆云传》：“陆云幼时，吴尚书广陵闵鸿见而奇之，曰：‘此儿若非龙驹，当是凤雏。’”又杜甫有“清新庾开府”“庾信文章老更成”诗句，商隐此言“清”“老”，当即此意。在商隐赴梓幕后不久，韩瞻亦出任果州刺史，韩偓必随行，所以这里说丹山路上，有“雏凤”“老凤”之声。“雏凤“指韩冬郎，“老凤”指韩瞻，有长江后浪推前浪的意思。\n剑栈：剑阁栈道，此指李商隐在梓州柳仲郢幕府中。\n风墙：当指赴蜀途中的一段水程，指韩瞻在江南之地。\n各苦辛：兼指水陆行程。\n别时冰雪到时春：商隐大中五年冬赴梓，故说“别时冰雪”。大中十年春随柳仲郢还长安，故说“到时春”。\n凭：请。此诗“别时冰雪到时春”巧妙联合何逊与范云联句中的“昔去雪如花，今来花似雪”。\n姓沈人：沈约曾为东阳太守，其《与徐勉书》中说到自己的老瘦：“百日数旬，革带常应移孔；以手握臂，率计月小半分。”此处以何逊比偓，以沈约自比。', poem_appreciation = '其一\n\n　　酒宴上的蜡烛烧残了大半，烛芯的灰烬也冷却了。用“冷灰残烛”，说明送别的筵宴已近尾声，阖座的人触动离情。在这种惨淡的气氛中，十岁的冬郎触发了诗思，飞速地挥写成送别的诗章。这就是此篇头两句对当年情景的追述。别宴的情况交代简略，重点突出冬郎题诗，是为了主题的需要。\n\n　　记事已毕，转入评赞。为了不使诗句沦于一般的套语，诗人使用了比喻的手法，将冬郎父子比作凤，以“雏凤清于老凤声”表明青出于蓝，抽象的道理从而转化为具体的形象。如此还不够生动。诗人又联想到，传说中凤凰产在丹山，它喜欢栖息的是梧桐树。经过想象的驰骋，便构成这样一幅令人神往的图景：遥远的丹山道上，美丽的桐花覆盖遍野，花丛中不时传来雏凤清脆圆润的鸣声，附和着老凤苍凉的呼叫，显得更为悦耳动人。这是非常富于诗情画意的描绘。看了这幅图画，冬郎的峥嵘年少和俊拔诗才就都跃然纸上了。\n\n　　使用鲜活生动的联想和想象，将实事实情转化为虚拟的情境、画面，这可以说是李商隐诗歌婉曲达意的又一种表达形式。一首本来容易写得平凡的寄酬诗，以“雏凤声清”的名句历来传诵不衰，除了诗人对后辈的真切情意外，跟这样的表达形式是分不开的。\n\n　　其二\n\n　　李商隐自注：“沈东阳约尝谓何逊曰：‘吾每读卿诗，一日三复，终未能到。’余虽无东阳之才，而有东阳之瘦矣。”《南史·何逊 传》：“沈约尝谓逊曰：‘吾每读卿诗，一日三复，犹不能已。’”\n\n　　李商隐自注在文字上与此语略有出入。凭：请。何逊：南朝梁代著名诗人。《南史·何逊传》： “逊字仲言，八岁能赋诗，弱冠，州举秀才。南乡范云见其对策，大相称赏，因结忘年交。”何逊与范云曾合作写《范广州宅联句》一诗：“洛阳城东西，却作经年别。昔去雪如花，今来花似雪。濛濛夕烟起，奄奄残晖灭。非君爱满堂，宁我安车辙。”此诗的前四句为范云作，后四句为何逊作。东阳：沈约（441—513） 字休文，号东阳，吴兴武康（今浙江德清）人，南朝著名的文学家。沈约自幼孤贫，笃志好学，博览群书，历仕宋、齐、梁等三朝，官至尚书令，封建昌县侯。瘦： 瘦弱。《南史·沈约传》：“初，约久处端揆，有志台司。论者咸谓为宜，而帝（梁武帝）终不用。乃求外出，又不见许。与徐勉素善，遂以书陈情于勉。言己老 病，百日数旬，革带常应移孔（意谓自己年老多病，因瘦弱的缘故，身上的腰带常常要移动孔洞）。”\n\n　　在写法上，此诗别开生面。首句中的 “各”字，紧扣诗题“兼呈畏之员外”，写与韩瞻天各一方的思念之情。二句顺势而下，将这种思念之情从冬季延续到春天，即通过时间上的延长暗寓思念之长久。 三四句回到赞扬韩偓的诗才方面，“瘦尽”二字回应首句中的“苦辛”，以沈约瘦弱之事并写两面，一写才不如韩偓，二写身世之感，暗寓诗人政治上的失意。', poem_tags = '叙事,回忆' WHERE poem_title = '韩冬郎即席为诗相送一座尽惊他日余方追吟连宵侍坐裴回久之句有老成之风因成二绝寄酬兼呈畏之员外·其一' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '桥边的池水里的月亮，真是难忘惹人恋爱。\n帘子在明亮的夜晚打开，竹帘卷起时已经是很凉的天气了。\n月光流转处水花湍急，婵辉倾吐出来使得云朵也有了光彩。\n月中的女神不施粉黛，她的美貌全靠这月光了。', poem_notes = '簟：竹帘。\n云叶：云朵。\n姮娥：神话中的月中女神。\n婵娟：月亮。', poem_tags = '写景,夜晚,月亮' WHERE poem_title = '月' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '武侯庙的孔明先生的画像早已遗落不知何处，整座山空寂只有草木徒长。\n站在这里好似还能听到诸葛亮作辞别后主的声音，可他壮志未酬，病死军中，再也无法功成身退，回到故地南阳了啊。', poem_notes = '武侯：指诸葛亮。诸葛亮于后主建兴元年（223年），封为武乡侯，省称武侯。武侯庙：指祭祀诸葛亮的庙。其庙有多处，如襄阳、成都、南阳、夔州等地都有武侯庙。这里指夔州武侯庙，在今四川省奉节县白帝城西。张震《武侯祠堂记》：“唐夔州治白帝，武侯祠在西郊。”\n丹青落：庙中壁画已脱落。丹青指庙中壁画。\n草木长：草木茂长。两句写庙景，言武侯去世时间之久远。\n辞后主：蜀后主刘禅建兴五年，诸葛亮上《出师表》，辞别后主，率兵伐魏。\n南阳：诸葛亮本以布衣躬耕于南阳（今河南南阳），因刘备三顾之于草庐中，遂佐备建立蜀汉、与魏、吴成鼎足之势。', poem_tags = '咏史怀古,赞颂,写人' WHERE poem_title = '武侯庙' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '早晨起来看见太阳升起，傍晚时分看见归鸟还巢。\n身在异乡内心本已酸楚，何况还面对着木瓜山。', poem_notes = '木瓜山，在贵阳县木瓜铺。木瓜：蔷薇科落叶灌木或小乔木，果实长椭圆形，其味酸。', poem_tags = '忧伤,思乡,地名' WHERE poem_title = '望木瓜山' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '水清的时候可以用来洗涤冠缨；\n水浊的时候就可以用来洗脚。', poem_notes = '濯：洗。\n缨：用线或绳等做的装饰品。', poem_tags = '楚辞,哲理' WHERE poem_title = '沧浪歌' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '年年春社的日子妇女们停下针线，孤单的她怎忍看见，双飞双栖的春燕？今日江城春色已过去大半，我独自还羁身于乱山深处，寂寞地伫立在小溪畔。\n春衫穿破了谁给我补缀针线？点点行行的泪痕洒满春衫。落日时分我解鞍驻马在芳草萋萋的河岸，虽有花枝却无人佩戴，虽有美酒却无人劝酒把盏，纵然醉了也无人照管。', poem_notes = '社日：指立春以后的春社。\n停针线：《墨庄漫录》说：“唐、宋社日妇人不用针线，谓之忌作。”唐张籍《吴楚词》：“今朝社日停针线。”\n“春衫”两句：春衫已经穿破，这是谁做的针线活呢？这里的“谁针线”与“停针线”相呼应，由著破春衫想起那制作春衫的人，不觉凄然泪下，泪痕沾满了破旧的春衫。', poem_appreciation = '此词在《阳春白雪》、《翰墨大全》、《花草粹编》等书中皆列入无名氏之作。唯《历代诗余》、《词林万选》题作黄公绍，唐圭璋先生认为此乃失考所致。这首词是思归怀人之作。它之所以由无名氏经过辗转而堂皇地列在著名词人的名下，说明它曾流传很广，并且有着较高的审美价值。\n\n　　“年年社日停针线，怎忍见、双飞燕？”社日是古时祭祀土神的日子，分春社与秋社，《统天万年历》云：“立春后五戊为春社，立秋后五戊为秋社”，这里指春社。每逢社日，妇女有停针线的习惯，《墨庄漫录》云：“唐宋妇人社日不用针线，谓之忌作。”张籍诗亦云：“今朝社日停针线”，此即诗人所本。诗人一开始就着意于远方的爱妻：在这社日来临，百无聊赖之际，她一定会因思念异乡的丈夫而愁绪万端。由于诗人用春燕的成双反衬夫妻的分离，所以，不用细致的描写，一个忧伤憔悴的思妇的形象便如在目前。“年年”二字下得尤其沉痛，它暗示读者，这对不幸的情侣已经历了长期的别离，今日的忧伤只不过是往昔的延续罢了！\n\n　　“今日江城春已半，一身犹在，乱山深处，寂寞溪桥畔。”此三句写诗人自身的寂寞，因和意中人凄凉的处境遥相呼应，更显得沉着动人。春日已过大半，自己却仍在乱山深处、溪桥之畔淹留，固守离愁之苦。“乱”字包含了诗人全部的况味，它既意味着身世的孤独，又象征着离愁的紊乱和深重。这样，词中的“乱山”就不仅仅是一个客观存在，同时也是惹起诗人愁思的情感化的产物，它的沉重与凄凉，使我们自然联想到词人精神上的压抑。\n\n　　“春衫著破谁针线，点点行行泪痕满。”这两句的意思是：春衣已破，谁为补缀？想到此，不由得泪洒春衫。此处看似俚俗，实为诗人的卓越之处。因为词人表达相思之苦，一般不外乎两种情形，或以物喻愁，或直抒胸臆，诗人抛弃了陈旧的套式，从夫妻这一特殊的关系着眼，选择了日常生产中最普通的“针线”情节作为表达情感的契机，这样就具体而不抽象，真切而不矫饰，正如贺裳所评：“语淡而情浓，事浅而言深。”\n\n　　“落日解鞍芳草岸，花无人戴，酒无人劝，醉也无人管。”这四句是全词的关键所在，也是写得最精彩的片断。它的高妙之处在于把思念之情落实到具体事物上，因此显得充沛之至，缠绵之至。从形式上看，它很像晁补之的《忆少年》起句：“无穷官柳，无情画轲，无根行客，”排句连蝉直下，给人以气势非凡之感。从意境上看，它更接近李商隐的诗句“纵使有花兼有月，可堪无酒又无人”的韵味：当红日西沉，诗人解鞍归来，虽有鲜花，却无人佩戴，以酒浇愁，又无人把盏，醉后更无人照管。这是无比凄楚的情景。于此，诗人的情感恣肆了，笔调放纵了，但读来并不会使人产生轻薄之感，此中奥秘，正如陈廷焯所说：“不是风流放荡，只是一腔血泪耳。”', poem_tags = '宋词三百首,婉约,思归,怀人' WHERE poem_title = '青玉案·年年社日停针线' AND poem_author = '黄公绍';
UPDATE edu_poem SET poem_translation = '从美人登发上的袅袅春幡，看到春已归来。虽已春归，但仍时有风雨送寒，似冬日徐寒犹在。燕子尚未北归，料今夜当梦回西园。已愁绪满怀，无心置办应节之物。\n东风自立春日起，忙于装饰人间花柳，闲来又到镜里，偷换人的青春容颜。清愁绵综如连环不断，无人可解。怕见花开花落，转眼春逝，而朝来塞雁却比我先回到北方。', poem_notes = '汉宫春：词牌名。《高丽史·乐志》名《汉宫春慢》。《梦窗词集》入“夹钟商”。各家句读多有出入，通常以《稼轩长短句》为准。九十六字，前后片各四平韵。\n立春日：古称“立春”春气始而建立，黄河中下游地区土壤逐渐解冻。《岁时风土记》：“立春之日，士大夫之家，剪彩为小幡，谓之春幡。或悬于家人之头，或缀于花枝之下。”南朝·陈·徐陵《杂曲》：“立春历日自当新，正月春幡底须故”。\n“春已”三句：谓从美人登发上的袅袅春幡，看到春已归来。春幡：古时风俗，每逢立春，剪彩绸为花、煤、燕等状，插于妇女之发，或缀于花枝之下，曰春播，也名恬胜，彩胜。稼轩《蝶恋花·元日立春)词起句云：“谁向椒盘答彩胜。”此风宋时尤盛。\n“无端”两句：言虽已春归，但仍时有风雨送寒，似冬日徐寒犹在。无端：平白无故地。\n“年时”两句：燕子尚未北归，料今夜当梦回西园。年时燕子：指去年南来之燕。酉园：汉都长安西邦有上林苑，北宋都城汴京西门外有琼林苑，都称西园，专供皇帝打猎和游赏。此指后者，以表现作者的故国之思。\n“浑末办”两句：言已愁绪满怀，无心置办应节之物。浑：全然。黄柑荐洒：黄柑酪制的腊酒。立春日用以互献致贸。更传：更谈不上相互传送，青韭堆盘：《四时宝鉴》谓“立春日，唐人作春饼生菜，号春盘”。又一说，称五辛盘。《本草纲目·菜部》：“五辛菜，乃元旦、立春，以葱、蒜、韭、募惹、芥辛嫩之菜和食之，取迎新之意，号五辛盘。故苏拭《立春日小集戏辛端叔》诗云：“辛盘得青韭．腊酒是黄柑。”辛词本此，但反用其意。\n“却笑”五句：言“东风”自立春日起，忙于装饰人间花柳，闲来又到镜里，偷换人的青春容颜。黄梅染柳：吹得梅花飘香、柳丝泛绿。镜里转变朱颜：谓年华消逝，镜里容颜渐老。更：何况。\n“清愁“两句：言清愁绵综如连环不断，无人可解。解连环：据《战国策·齐策》．秦昭王遣使齐国，送上玉连环一串，请齐人解环。群臣莫解。齐后以椎击破之，曰：环解矣。辛词用此喻忧愁难解。\n“生怕见”两句：言怕见花开花落，转眼春逝，而朝来塞雁却已先我还北。生怕：最怕，只怕。塞雁：去年由塞北飞来的大雁。', poem_tags = '婉约,写景,怀念,故国' WHERE poem_title = '汉宫春·立春日' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '我来凭吊古人的陈迹，登上高楼，却落得愁闷无穷。当年虎踞龙蟠的帝王之都今在何处？满目所见只是千古兴亡的遗踪。夕阳斜照着迷茫的柳树，水边觅食的鸟儿急促地飞回窝中，风儿吹拂着高树，掠过荒凉的丘垄。一只孤独的船儿在秦淮河中匆匆西去，不知何人把激越的寒笛吹弄。\n回想当年那功业显赫的谢安，晚年被迫在东山闲居，也被悲哀的筝声引起伤恸。建功扬名的希望都寄托在儿辈身上，漫长的白日只有消磨在棋局中。表明心迹的宝镜已难于寻觅，岁月又将无情地逝去，谁能安慰我的情怀共饮酒一盅？早晨以来江上便狂风怒号，高浪似要翻倒房屋，真令人忧悚。', poem_notes = '念奴娇：词牌名，又名《百字令》《酹江月》等，双调一百字，前后阕各四仄韵。\n赏心亭：位于建康下水门之上，下临秦淮河，是当时的游览名胜，辛弃疾特爱登此亭眺望。史留守致道：史正志，字致道，扬州人，高宗时进士，除枢密院编修。宋孝宗乾道三年至六年（1167—1170）知建康府，兼建康行宫留守、沿江水军制置使。留守，即行宫留守，宋室南渡初，高宗一度驻跸建康，故称建康为行宫。\n吊古：凭吊古迹。\n危楼：高楼，此代指赏心亭。\n斛：度量容器，古人以十斗为一斛。\n虎踞龙蟠：形容建康城地势之险要，气势之峥嵘。\n兴亡：指六朝兴亡古迹。偏重于“亡”。\n陇：田埂，此泛指田野。乔木：高大的树木。\n片帆：孤舟。\n喷霜竹：谓吹笛。喷，吹奏。霜竹，秋天之竹，借以指笛。\n安石：谢安，字安石，东晋著名政治家。风流：指谢安丰采照人，英才盖世。\n东山岁晚：谓谢安晚年。\n泪落哀筝曲：晋孝武帝末年，谢安位高遭忌。\n“儿辈”二句：言谢安将建功立业的机会都交付给儿辈，自己惟以下棋度日。\n宝镜难寻：喻知我者难觅。\n碧云将暮：言天色将晚，喻岁月消逝，人生易老。\n杯中绿：杯中酒。\n波浪翻屋：形容水势汹涌浩大。', poem_appreciation = '登览怀古之作，往往以历史的变迁寄寓对国事的感慨，借古讽今，以雄深跌宕为胜。对于知己的唱和之作，往往是心语的倾诉，以诚挚深切为高。要将这两种意思打和成一片，就需要糅合两种不同的美学风格，兼有雄深与温婉。这是一种难以达到的妙境，而本词显然达到了这一境界。此词分以下几个方面下笔：建康的地理形势、眼前的败落景象，并用东晋名相谢安的遭遇自喻，表达词人缺乏知音同志之士的苦闷，最后用长江风浪险恶，暗指南宋的危局。\n\n　　开头三句，开门见山，直接点明主题，抒发内心感情基调。然后再围绕主题，一层一曲地舒展开来。“上危楼，赢得闲愁千斛”，是说词人登上高楼，触景生情，引起无限感慨。“闲愁千斛”，是形容愁苦极多。“闲愁”，是作者故作轻松之笔，其实是作者关心国事但身不在要位始终不能伸抗金之志的深深忧愁。\n\n　　四、五两句，采用自问自答的方式，把“吊古伤今”落到实处。“虎踞龙蟠何处是”？问话中透出今不比昔的悲凉。据《金陵图经》记载：“石头城在健康府上元县西五里。诸葛亮谓吴大帝曰：‘秣陵地形，钟山龙蟠，石城虎踞，真帝王之都也。’”正因为如此，健康曾经成为六朝的国都。但在辛弃疾看来，此时却徒留空名，和一片败亡的气息。这里暗中，谴责南宋朝廷不利用健康的有利地形抗击金兵、收复中原饱含感情的问答异常生动地勾画出词人大声疾呼、痛苦欲绝、气愤填膺的形象。“兴亡满目”，“兴亡”是偏义词，侧重于“亡”字。\n\n　　“柳外斜阳”五句，是健康眼前的景象，把“兴亡满目”落到实处，渲染一种国势渐衰悲凉凄楚的气氛：夕阳斜照在迷茫的柳树上；在水边觅食的鸟儿，急促地飞回窝巢；垅上的乔木，被狂风吹打，飘落下片片黄叶；一只孤零零的小船，漂泊在秦淮河中，匆匆地向西边驶；不知何人，吹奏起悲凉的笛声。映入词入眼帘怎能不勾起作者忧国的感叹。同时词人独选此景，也正是意在表达自己内心的情感。从构思而言，上片三个层次，采用层层递进、环环紧扣的笔法，衔接极为严密。而各个层次，又都从不同的角度，加深和强化主题。\n\n　　上片十句侧重于吊古伤今。下片十句则侧重于表现词人志不得神、无法实现抗金国收河山壮志的愁苦，及其对国家前途的忧虑。下片亦分三个层次，前五句为一个层次，是曲笔。次三句为一个层次，是直抒胸臆。最后两句为一个层次，是比喻。各层次的笔法虽不相同，但能相辅相成，浑然符契。\n\n　　“却忆安石风流”五句，用谢安（安石）受谗被疏和淝水之战等典故。前三句写谢安早年寓居会稽，与王羲之等知名文人，“渔弋山水”、“言咏属文”，风流倜傥逍遥洒脱。作者借此表达自己本也可隐居安逸但忧国之心使其尽小国事，以至“泪落哀筝曲”。晋孝武帝司马曜执政，谢安出任宰相，后来受谗被疏远。\n\n　　“泪落哀筝曲”，是写谢安被疏远后，孝武帝有次设宴款待大将桓伊，谢安在座。桓伊擅长弹筝，谢安为孝武帝弹一曲《怨诗》，借以表白谢安对皇帝的忠心，和忠而见疑的委屈，声节慷慨，谢安深受感动，泪下沾襟。孝武帝亦颇有愧色。词人在此借古人之酒杯，浇自己之块垒，曲折隐晦地表达未见重用志不得伸的情怀。“儿辈”两句，写谢安出任宰相未被疏前，派弟弟谢石和侄儿谢玄领兵八万，在淝水大败前秦苻坚九十万大军的事。当捷报传到健康，谢安正在和别人下棋。谢安了无喜色，仍下棋如故。别人问谢安战况时，谢安才漫不经心的答道：“小儿辈遂已破贼。”这段历史，本来说明谢安主持国事，沉着与矜持。可是，辛弃疾改变了它的原意，把词意变成：建立功名的事，让给小儿辈干吧，我只须整天下棋消磨岁月！不难看出，这里包含着词人壮志未酬、虚度年华的愁苦，同时也给予议和派以极大的讽刺。\n\n　　辛弃疾为词气魄不亚于东坡，但这里却屡用喻指，语含讥讽，可见长期的压抑使之极度愤懑，而面对现实除了无奈更别无他法。\n\n　　“宝镜”三句，笔锋又双从历史转到现实，词人用寻觅不到“宝镜”、夜幕降临、无人劝酒，暗喻壮志忠心不为人知、知音难觅的苦闷。“宝镜”，唐李濬《松窗杂录》载秦淮河有渔人网得宝镜，能照见五脏六腑，渔人大惊，失手宝镜落水，后遂不能再得。这里借用此典，意在说明自己的报国忠心保国之才无人鉴察。刘熙载说：“稼轩词龙腾虎掷，任古书中俚语、瘦语，一经运用，便得风流，天姿是何敻异！”（《艺概·词曲概》）的确，“宝镜”三句，感情基调虽然悲愤沉郁，但词句却含蓄蕴藉，优美动人。\n\n　　最后两句，境界幽远，寓意颇深。它写词人眺望江面，看到狂风怒号，便预感到风势将会愈来愈大，可能明朝长江卷起的巨浪，会把岸上的房屋推翻。这两句不仅写出江上波涛的险恶，也暗示对时局险恶的忧虑。\n\n　　“吊古”之作，大都抒发感慨或鸣不平。辛弃疾写得尤其成功，感人至深。《宋史》本传称其“雅善长短句，悲壮激烈”。即说明辛词此类作品的豪放风格。', poem_tags = '吊古伤今' WHERE poem_title = '念奴娇·登建康赏心亭呈史致道留守' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_tags = '少女,伤春,孤独' WHERE poem_title = '蝶恋花·蝶懒莺慵春过半' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_tags = '女子' WHERE poem_title = '蝶恋花·越女采莲秋水畔' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_tags = '离愁,凄凉,思乡' WHERE poem_title = '蝶恋花·凤栖梧' AND poem_author = '柳永';
UPDATE edu_poem SET poem_translation = '我因获罪而被贬为庶人，没有可以去的地方，乘船在吴地旅行。起初租房子住。时值盛夏非常炎热，土房子都很狭小，不能呼气，想到高爽空旷僻静的地方，来舒展心胸，没有能找到。\n　　一天拜访学宫，向东看到草树郁郁葱葱，高高的码头宽阔的水面，不像在城里。循着水边杂花修竹掩映的小径，向东走数百步，有一块荒地，方圆约六十寻，三面临水。小桥的南面更加开阔，旁边没有民房，四周林木环绕遮蔽，询问年老的人，说：“是吴越国王的贵戚孙承佑的废园。”从高高低低的地势上还约略可以看出当年的遗迹。我喜爱这地方，来回地走，最后用钱四万购得，在北面构筑亭子，叫“沧浪”。北面是竹南面是水，水的北面又是竹林，没有穷尽，澄澈的小河翠绿的竹子，阳光、阴影在门窗之间交错相接，尤其是在有风有月的时候更宜人美丽。\n　　我常常乘着小船，穿着轻便的衣服到亭上游玩，到了亭上就率性玩乐忘记回去，或把酒赋诗，或仰天长啸，即使是隐士也不来这里，只与鱼、鸟同乐。形体已然安适，神思中就没有了烦恼；所听所闻都是至纯的，如此人生的道理就明了了。回过头来反思以前的名利场，每天与细小的利害得失相计较，同这样的情趣相比较，不是太庸俗了吗！\n　　唉！人本来会受外物影响而感动。情感充塞在内心而性情压抑，一定要借外物来排遣，停留时间久了就沉溺，认为当然；不超越这而换一种心境，那么悲愁就化解不开。只有仕宦之途、名利之场最容易使人陷入其中，自古以来，不知有多少有才有德之士因政治上的失意忧闷致死，都是因为没有悟出主宰自己、超越自我的方法。我虽已经被贬却获得这样的胜境，安于冲淡旷远，不与众人一道钻营，因此又能够使我的内心和形体找到根本，心有所得，笑悯万古。尚且没有忘记内心的主宰，自认为已经超脱了。', poem_notes = '沧浪亭，在今江苏苏州城南三元坊附近，原为五代时吴越国广陵王钱元璙的花园。五代末此处为吴军节度使孙承祐的别墅。北宋庆历年间为诗人苏舜钦购得，在园内建沧浪亭，后以亭名为园名。后代人在它的遗址上修建了大云庵。本文作者用朴素简洁的语言，自然流畅的笔调，记述了沧浪亭演变的始末。\n吴中：今江苏省，大致相当于春秋时吴国地方\n租赁\n过：拜访\n]郡学：苏州府学宫，旧址在今苏州市南，沧浪亭就在其东面,郡国的最高学府。\n崇阜：高山\n并（bàng)：通“傍”\n杠：独木桥\n钱氏：指吴越王钱镠\n孙承祐：吴越王钱俶的小舅子，任节度使，镇守苏州，在苏州大建园亭\n北碕：北边曲岸上\n冲旷：冲淡旷远，这里既指沧浪亭的空旷辽阔的环境，也兼指淡泊旷适的心境\n闵：同“悯”，悲悯。\n寻：长度单位\n锱珠：比喻极其微小的数量', poem_tags = '辞赋精选,生活,抒情' WHERE poem_title = '沧浪亭记' AND poem_author = '苏舜钦';
UPDATE edu_poem SET poem_tags = '女子,怀人,相思' WHERE poem_title = '青春' AND poem_author = '韩偓';
UPDATE edu_poem SET poem_tags = '咏史怀古,赞美,爱国,志士' WHERE poem_title = '金陵新亭' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '驿马奔驰在长远的路途，一路上马蹄飞跃，马影摇曳晃动着。\n你驿马长游泰山之东，要曳着秋风才能往东又向东的追游着。\n多么祈望我是星星你是月，每一个夜里你我光明洁白的光彩辉映着。\n秋夜！月儿常暮掩在云堆里，而星星却辉映高挂着，多么的期待月儿的出现！\n期待那十五月圆盈满时，你我星月皎洁辉映成天之佳偶。', poem_notes = '遥遥：长远的距离。\n憧憧：晃动，摇曳不定。\n东山：泰山顶东侧（山东省泰安县）。因为这里可以观看日出时的美景，故称为日观峰。亦称为东山。\n西风：秋风。\n流光：光彩闪耀、辉映的样子。\n皎洁：光明洁白。\n晦：昏暗不显\n三五：十五日。盈盈：充满的样子。', poem_tags = '抒怀,思念' WHERE poem_title = '车遥遥篇' AND poem_author = '范成大';
UPDATE edu_poem SET poem_translation = '在近已咫尺的阳春三月，在一户普通的老百姓家中 。\n为了迎接新一年里燕子的归来，不放下破旧的帘子把房屋遮蔽起来。\n一场春雨后燕子的翅膀上沾着丝丝的雨滴， 土地里散发出一股淡淡的泥土香味，里面还混杂着雨滴砸落的花瓣。\n燕巢早已筑修好了，连小燕子都长大了 。一人家一燕家两户家庭相伴着又度过了一个美丽的年华。', poem_notes = '选自《全宋诗》卷二七二五（北京大学出版社1998年版）。葛天民，字无怀，南宋越州山阴（今浙江绍兴）人。有《无怀小集》。\n咫（zhí）尺：距离很近。比喻春天的短暂。咫，古代称八寸为咫。', poem_appreciation = '燕子秋去春来，巢于檐下，民间视为吉祥物。“寻常百姓家”即借鉴刘禹锡的“旧时王谢堂前燕，飞入寻常百姓家。”正因为燕子不嫌贫爱富、趋炎附势，主人也“不下旧帘遮”，热情的迎接燕子的归来。“巢成雏长大，相伴过年华”两句，更是把燕子看成生活的一部分了。\n\n　　古诗中燕子往往象征着幸福的生活。它们双宿双飞，本诗中的燕子也在主人的檐下幸福的生活。燕子的自由自在，正是诗人隐居生活的反映；燕子之乐，足见诗人之乐。诗歌生动的描绘了燕子的生活习性，表达了燕子与老百姓的深厚情谊。\n\n　　首句一个“咫”字，指八寸，也表现了暮春的转瞬即逝，抒发了作者对春的珍惜之情。“寻常百姓家”借用了刘禹锡的“飞入寻常百姓家”，歌颂了燕子不趋炎附势，不嫌贫爱富的质朴、高尚的品格，表达了燕子对百姓的眷恋。第三句“微”形容雨之小，描写了燕子在雨中穿梭无数次，为幸福的生活勤劳地筑巢，“泥香带落花”描写了春天温馨、幸福的场面。尾句是对燕子勤劳地赞美，也再次表现了人与燕之间的深厚情谊，同时又是诗人幸福隐居生活的写照。', poem_tags = '燕子' WHERE poem_title = '迎燕' AND poem_author = '葛天民';
UPDATE edu_poem SET poem_translation = '译文 　　一树梅花长在背阴的山谷，加上枝条伸向北方，阳光终年罕至，所以每年开花总是比较迟。但你可知道它那高尚的气节、优美的风度？……要知道，当它吐苞，正是那冰雪覆盖、最为酷烈的严冬时节啊！', poem_tags = '咏物,梅花,抒怀,爱国' WHERE poem_title = '梅花绝句·其二' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '晋侯又向虞国借路去攻打虢国。\n\n　　宫之奇劝阻虞公说：“虢国，是虞国的外围，虢国灭亡了，虞国也一定跟着灭亡。晋国的这种贪心不能让它开个头。这支侵略别人的军队不可轻视。一次借路已经过分了，怎么可以有第二次呢？俗话说‘面颊和牙床骨互相依着，嘴唇没了，牙齿就会寒冷’，就如同虞、虢两国互相依存的关系啊。”\n\n　　虞公说：“晋国，与我国同宗，难道会加害我们吗？”宫之奇回答说：“泰伯、虞仲是大王的长子和次子，泰伯不听从父命，因此不让他继承王位。虢仲、虢叔都是王季的第二代，是文王的执掌国政的大臣，在王室中有功劳，因功受封的典策还在主持盟会之官的手中。现在虢国都要灭掉，对虞国还爱什么呢？再说晋献公爱虞，能比桓庄之族更亲密吗？桓、庄这两个家族有什么罪过？可晋献公把他们杀害了，还不是因为近亲对自己有威胁，才这样做的吗？近亲的势力威胁到自己，还要加害于他们，更何况对一个国家呢？”\n\n　　虞公说：“我的祭品丰盛清洁，神必然保佑我。”宫之奇回答说：“我听说，鬼神不是随便亲近某人的，而是依从有德行的人。所以《周书》里说：‘上天对于人没有亲疏不同，只是有德的人上天才保佑他。’又说：‘黍稷不算芳香，只有美德才芳香。’又说：‘人们拿来祭祀的东西都是相同的，但是只有有德行的人的祭品，才是真正的祭品。’如此看来，没有德行，百姓就不和，神灵也就不享用了。神灵所凭依的，就在于德行了。如果晋国消灭虞国，崇尚德行，以芳香的祭品奉献给神灵，神灵难道会吐出来吗？”\n\n　　虞公不听从宫之奇的劝阻，答应了晋国使者借路的要求。宫之奇带着全族的人离开了虞国。他说：“虞国的灭亡，不要等到岁终祭祀的时候了。晋国只需这一次行动，不必再出兵了。”\n\n　　冬天十二月初一那天，晋灭掉虢国，虢公丑逃到东周的都城。晋军回师途中安营驻扎在虞国，乘机突然发动进攻，灭掉了虞国，捉住了虞公和他的大夫井伯，把井伯作为秦穆姬的陪嫁随从。然而仍继续祭祀虞国的祖先，并且把虞国的贡物仍归于周天子。所以《春秋》中记载说“晋国人捉住了虞公。”这是归罪于虞公，并且说事情进行得很容易。', poem_notes = '晋：国名，在今山西省翼城县东。晋侯：晋献公。复假（jiǎ）道：又借路。僖公二年晋曾向虞借道伐虢，今又借道，故用“复”。虞（yú）：国名，姬姓。周文王封予古公亶父之子虞仲后代的侯国，在今山西省平陆县东北。虢（guó国）：国名，姬姓。周文王封其弟仲于今陕西宝鸡东，号西虢，后为秦所灭。本文所说的是北虢，北虢是虢仲的别支，在今山西平陆。虞在晋南，虢在虞南。\n表：外表，这里指屏障、藩篱。\n启：启发，这里指启发晋的贪心。\n寇：凡兵作乱于内为乱，于外为寇。翫（wán完）：即“玩”，这里是轻视、玩忽的意思。\n其：反诘语气词，难道。\n辅：面颊。车：牙床骨。\n宗：同姓，同一宗族。晋、虞、虢都是姬姓的诸侯国，都同一祖先。\n大（tài）伯、虞仲：周始祖太王（古公亶父）的长子和次子。昭：古代宗庙制度，始祖的神位居中，其下则左昭右穆。昭位之子在穆位，穆位之子在昭位。昭穆相承，所以又说昭生穆，穆生昭。大伯、虞仲、王季俱为大王之子，都是大王之昭。\n不从：指不从父命。嗣：继承（王位）。大伯知道大王要传位给他的小弟弟王季，便和虞仲一起出走。宫子奇认为大伯没继承王位是不从父命的结果。\n虢仲、虢叔：虢的开国祖，王季的次子和三子，文王的弟弟。王季于周为昭，昭生穆，故虢仲、虢叔为王季之穆。\n卿士：执掌国政的大臣。盟府：主持盟誓、典策的宫府。\n将虢是灭：将灭虢。将，意同“要”。是，复指提前的宾语“虢”。\n桓庄：桓叔与庄伯，这里指桓庄之族。庄伯是桓叔之子，桓叔是献公的曾祖，庄伯是献公的祖父。晋献公曾尽杀桓叔、庄伯的后代。其：岂能，哪里能。之：指虞。\n桓庄之族何罪，而以为戮：庄公25年晋献公尽诛同族群公子。以为戮：把他们当作杀戮的对象。唯：因为。逼（bì毙）：通“逼”，这里有威胁的意思。\n亲：指献公与桓庄之族的血统关系。宠：在尊位，指桓、庄之族的高位。况以国乎：此句承上文，因此省略了“以国”下的“逼”字。\n享祀：祭祀。絜（jié洁）：同“洁”。据我：依从我，即保佑我。\n实：同“是”复指提前的宾语。\n皇：大。辅：辅佐，这里指保佑。所引《周书》已亡佚，这两句引见伪古文《尚书》，下同。\n黍（shǔ）：黄黏米；稷（jì寄）：不黏的黍子，黍稷这里泛指五谷。馨（xīn心）：浓郁的香气。\n易物：改变祭品。繄（yī医）：句中语气词。\n冯（píng）：同“凭”。\n明德：使德明。馨香：指黍稷。其：语气词，加强反问。吐：指不食所祭之物。\n以：介词，表率领。以其族行：指率领全族离开虞。\n腊：岁终祭祀。这里用作动词，指举行腊祭。\n此句以下有删节。\n丙子：十二月初一正逢干支的丙子。朔：每月初一日。\n丑：虢公名。京师：东周都城。今河南洛阳。\n馆：为宾客们设的住处。这里用作动词，驻扎的意思。\n媵（yìng映）：陪嫁的奴隶。秦穆姬：晋献公女，嫁秦穆公。\n书：指《春秋》经文。\n其：代词，那只谚语说的道理。', poem_appreciation = '文章首先陈述了虞虢之间的紧密关系，然后揭露出晋侯残酷无情的本质，最后提醒虞国公国家存亡在于德行，而不在与神灵。文章批判了迷信宗族关系和神权至上的迂腐，反映了当时的民本思想。文章结构严谨，条理清晰，开头只用“晋侯复假道于虞以伐虢”一句点明事件的起因及背景，接着便通过人物对话来揭示主题。语言简洁有力，多用比喻句和反问句。如用“辅车相依，唇亡齿寒”比喻虞晋的利害关系，十分贴切、生动，很有说服力。\n\n　　晋献公吞并虢国和虞国的成功，要归功于他的心狠手毒：一方面以本国宝物作诱饵，诱敌手上钩；一方面六亲不认，不顾同宗亲情，唯利是图。于是，不惜以阴谋诡计骗取虞国信任，将两国逐个吞食。俗话说，“舍不得孩子，打不到狼。”“将欲取之，必先予之”晋献公实实在在地照这样去做了，并且得到了回报，实际上什么都没有损失。但是，攻城略地的成功，却以不顾礼义廉耻为代价，得到了实际利益和好处，而因此失去了人心和道义。对于重视民心和道义的人来说，这样做是得不偿失；对于寡廉鲜耻的人来说，失去的无所谓，得到的才是实在的。人们总是站在自己的立场上来决定取舍的。\n\n　　如此说来，对于寡廉鲜耻、心狠手毒之徒不应当以仁义道德之心去对待，最好是以强硬的态度，以其人之道，还治其人之身。虞国的灭亡，就灭在太相信同宗亲情，对不义之徒抱着不切实际的幻想，以为对方跟自己是一类人，以一种近乎于农夫的心肠，去对待凶狠的毒蛇。如果说这也是一场悲剧的话，那么则是由自己推波助澜、助纣为虐而导致的。如果灭亡的结果是自己一时糊涂、认识不清，被披着羊皮的狼蒙蔽了，尚还可以寄予一点同情，然而有贤臣坦诚相谏，苦口婆心地开导，在这种情况下仍然执迷不悟，固执己见，则可以说是咎由自取，不值得一点同情。\n\n　　曾经是作威作福的国君，一朝变成随他人之女陪嫁的奴隶，这种天上、地下的巨变，不能不使人感叹。这也应了那句老话：“天作孽，犹可违；自作孽，不可活。”\n\n　　历史是不应当忘记的，读史可以使人明鉴，使人清醒。即使弱小而无法与强暴抗衡，那么弱小者之间的彼此照应、鼓励。安慰、同病相怜、支持，也可以让人在风雨之中同舟共济，患难与共，正所谓唇齿相依，唇亡齿寒。这些从惨痛的历史中总结出来的教训，完全可以说是千古不易的。就连平民百姓都懂得，听人劝得一半。欺人太甚的事不可一而再，再而三地容忍，即使无法奋起抗争，最起码是可以想法避开的。既不听劝，又不抗争，的确算是病入膏肓，不可救药了。', poem_tags = '古文观止,历史,故事,劝谏' WHERE poem_title = '宫之奇谏假道' AND poem_author = '左丘明';
UPDATE edu_poem SET poem_translation = '卫庄公娶了齐国太子得臣的妹妹，叫庄姜，容貌很漂亮，却没有儿子。卫国人做了一首名为《硕人》的诗就是描写她的美貌的。庄公又从陈国娶了一个妻子，叫厉妫，生了儿子孝伯，早死。跟她陪嫁来的妹妹戴妫，生了桓公，庄姜就把他作为自己的儿子。\n\n　　公子州吁，是庄公爱妾生的儿子，卫庄公十分宠爱他，又喜欢军事，但庄公不禁止，庄姜很厌恶他。\n\n　　石碏规劝庄公道：“我听说一个人爱自己的儿子，一定要以正确的礼法来教导约束他，这样才能使他不走上邪路。骄傲、奢侈、淫荡、逸乐，就是走向邪路的开端。这四个方面的产生，都是宠爱和赏赐太过的缘故。如果要立州吁做太子，就应该定下来；要是还没有，这样就会引导他造成祸害。受宠爱而不骄傲，骄傲了而能受压制，受了压制而不怨恨，有怨恨而不为非作歹的人，是很少有的呀。再说卑贱的妨害高贵的，年少的欺负年长的，疏远的离间亲近的，新的挑拨旧的，地位低的压着地位高的，淫乱的破坏有礼义的，这是人们常说的六种逆理的事。君主行事公正适宜，臣子服从命令，父亲慈爱儿子，儿子孝顺父亲，哥哥爱护弟弟，弟弟敬重哥哥，这是人们常说的六种顺礼的事。不做顺应礼义的事去做违背礼的事，就会招致祸害。做君主的应尽力除掉祸害，现在却反而招致祸害的到来，这恐怕是不可以的吧！”庄公不听。\n\n　　石碏的儿子石厚和州吁交往，石碏禁止他，但是州吁不允，从而放弃。到了桓公即位，石碏于是告老还乡。', poem_notes = '卫：国名，姬姓，在今河南淇县一带。齐：国名，姜姓，在今山东北部、中部地区。东宫：太子的居所。\n硕人：典出《诗经 · 卫风》中的一篇，乃歌颂庄姜美丽的诗篇。庄姜：卫庄公的夫人，“庄”是她丈夫的谥号，“姜”则是她娘家的姓，故称庄姜。\n陈：国名，妫姓在今河南东部及安徽西部。\n厉妫（guī）：“厉”和下文“戴妫”的“戴”均为谥号，“妫”是娘家的姓。\n蚤：通”早“。\n娣：妹。古时诸侯娶妻，妹可随姊同嫁。\n桓公：名完，在位十六年，后为州吁所杀。\n嬖（bì）人：出身低贱而受宠的人，这里指卫庄公的宠妾。\n石碏（què）：卫国大夫。\n义方：为人行事的规范。\n佚（yì）：这里指逸乐。\n阶：阶梯，这里用作动词，指一步步引向。\n眕（zhěn）：自安自重，忍耐而不轻举妄动。\n鲜（xiǎn）：少见。\n陵：欺侮。\n去：抛弃。\n速：招致。\n是：通“事”\n无乃：恐怕。\n立：继承。\n老：告老致仕。', poem_appreciation = '文章记述了前720年（隐公三年），石碏劝谏卫庄公爱子应“教之以义方，弗纳于邪”的事。州吁是卫庄公的一个宠妾所生，卫庄公爱屋及乌，对他也格外宠爱，即使对他喜好军事这种十分犯忌的事，也不加禁止。卫国大夫石碏看到了问题的严重性，于是向卫庄公进谏，劝庄公爱子应该用道义，不要让他走上邪路。但庄公听不进去，结果前719年即第二年，就发生了州吁弑桓公而自立的事件。多亏石碏用计，大义灭亲，借陈国国君之手把弑君乱国的州吁和自己的儿子——助纣为虐的石厚抓住，并派人把他们杀死。\n\n　　如何爱子，对一个国君来说，决不单单是他个人的问题，这将关系到国家的安危、社会的治乱。正因为这样，所以石碏才进谏卫庄公。但石碏进谏，并没有像许多进谏者那样，举述以往有关的历史经验教训；而是开门见山，一上来就切入谏旨，提出“爱子”应“教之以义方，弗纳于邪”的观点。接着，便有的放矢地指出“骄、奢、淫、佚”是使“爱子”走上邪路的来由；而这四种恶习的养成，则是为人君者过分溺爱所致。然后，话题轻轻一转，就落到州吁身上。须知，州吁作为庶子而“好兵”，这往往是作乱的前兆。所以石碏一针见血却又语重心长地指出：“将立州吁，乃定之矣；若犹未也，阶之为祸。”之后，又连用四个顶针（也叫“顶真”或“联珠”）句，断定州吁决不会心甘情愿地屈居人下。再接下来，又根据传统的伦理关系和社会规范，总括出“六逆”和“六顺”，提醒庄公：“去顺效逆”只能加速祸患的发生，作为人君必须防患未然，全力消除祸患的根由。这样，就把“教之以义方，弗纳于邪”这一爱子观的现实性、重要性和紧迫性进一步突出出来。然而，被糊涂蒙了心的卫庄公却根本听不进去。\n\n　　石碏的谏言有三层意思，环环相扣，入情入理，深入地分析了由“宠”导致灭亡的必然性。其一，“骄、奢、淫、佚，所自邪也”， “四者之来，宠禄过也”，说明骄奢淫逸来源于娇纵溺爱；其二、受宠爱就会变得骄横，骄横就不会安于自己地位低下，地位低下就会有怨恨之心，心生怨恨就不会安分守已；其三，从此以后，地位低贱的就会欺压地位尊贵的，年纪小的就会想办法凌年纪大的，关系疏远的就会找机会离间关系亲近的，新的离间旧的，小的欺凌大的，淫乱的就会破坏有道德的。如此这般，祸事就注定要来了！\n\n　　劝主谏君，须在紧紧把握谏旨韵前提下，动之以情，晓之以理。而理，则须说透，说到位。做到了这点，被劝谏者却听不进去，那只能证明被劝者太顽固不化，《石碏谏宠州吁》正具有这样的特点。可以肯定地说，“教之以义方，弗纳于邪”的爱子方法，历来被认为有借鉴意义和实践意义。', poem_tags = '古文观止,劝谏' WHERE poem_title = '石碏谏宠州吁' AND poem_author = '左丘明';
UPDATE edu_poem SET poem_translation = '译文 雪花落下，给植物披上了银装，一点颜色的都没有；在南边的树枝上有一些花，没有叶子。在小溪旁我都闻到了香味，抬头一看，只见梅花的影子映在农家的墙壁上。', poem_tags = '梅花' WHERE poem_title = '早梅' AND poem_author = '道源';
UPDATE edu_poem SET poem_translation = '禹锡的乐府小章《杨柳枝词》，一共有九首，这是其中的第一首，可说是这组诗的序曲，鲜明地表现了他在文学创作上的革新精神。\n\n　　首句“梅花”，指汉乐府横吹曲中的《梅花落》曲，用笛子吹奏（羌笛是笛的一种），其曲调流行后世，南朝以至唐代文人鲍照、吴均、徐陵、卢照邻、沈佺期等都有《梅花落》歌词，内容都与梅花有关。（见《乐府诗集》卷二四）这句意思说，起源于塞北的《梅花落》是用笛子吹奏的乐曲。\n\n　　次句讲的是《楚辞》中的《招隐士》篇。相传西汉淮南王刘安门客小山之徒作《招隐士》篇来表现对屈原的哀悼。《招隐士》首句云，“桂树丛生兮山之幽”，下文又两处有“攀援桂枝兮聊淹留', poem_tags = '乐曲' WHERE poem_title = '杨柳枝词九首·其一' AND poem_author = '刘禹锡';
UPDATE edu_poem SET poem_tags = '宋词三百首,无奈,思念' WHERE poem_title = '鹧鸪天·寒日萧萧上琐窗' AND poem_author = '李清照';
UPDATE edu_poem SET poem_translation = '春日暖暖的阳光，像在抚弄着杨柳轻柔的枝条，在花园的小径上，涌动着浓浓的香气。可过了清明节天却阴了起来，云雾笼罩着红楼，好似是把它锁住，那往事，真是不堪回首！\n午睡醒来，听到莺儿美妙的鸣叫声，却又唤起了我的春愁。这莺儿却在哪里呢？是在绿杨影里，是在海棠亭畔，还是在红杏梢头？', poem_notes = '眼儿媚：词牌名，又名《秋波媚》。双调四十八字，前片三平韵，后片两平韵。\n迟迟：阳光温暖、光线充足的样子。\n轻柔：形容风和日暖。\n花径：花间的小路。\n暗香：指幽香。\n朱楼：指富丽华美的楼阁。\n梢头：树枝的顶端。', poem_tags = '宋词三百首,婉约,女子,春愁' WHERE poem_title = '眼儿媚·迟迟春日弄轻柔' AND poem_author = '朱淑真';
UPDATE edu_poem SET poem_translation = '译文 在此风声呼啸之地熟人故交已是很少了，那里可以找一登高远望之处送别归去的友人呢？ 今天还能聚在一起同饮芬芳的菊香之酒，明日就要成为断根的飘蓬一般匆匆离去了。', poem_tags = '重阳节,离别,饮酒' WHERE poem_title = '九日送别' AND poem_author = '王之涣';
UPDATE edu_poem SET poem_tags = '春天,写花,伤怀,青春' WHERE poem_title = '落花落' AND poem_author = '王勃';
UPDATE edu_poem SET poem_translation = '金井边的梧桐秋叶渐黄，珠帘不卷可知夜里飞霜。\n熏笼玉枕有如容颜憔悴，静卧愁听南宫漏声悠长。\n\n秋天高殿内捣衣声响彻夜阑，夜里霜重还记起君王御衣寒。\n更深人静银灯下裁衣才停歇，目光还转向宫城明主那边看。\n\n天亮就拿起扫帚打扫金殿尘埃，百无聊赖时手执团扇且共徘徊。\n美丽的容颜还不如乌鸦的姿色，它还能带着昭阳殿的日影飞来。\n\n果真成为薄命人长久陷入沉思，梦中又见到君王醒后心里生疑。\n灯火照耀着西宫知道是在夜饮，眼前分明浮现复道蒙恩受宠时。\n\n长信宫中惟有秋月尚明，昭阳殿下响起捣衣声声。\n白露堂中满是杂草印迹，那边红罗帐里绵绵深情。', poem_notes = '长信秋词：又作“长信怨”，《汉书·外戚传》载，班婕妤以才学入宫，为赵飞燕所妒，乃自求供养太后于长信宫。“长信怨”由此而来。长信：汉宫名。\n金井：井栏上有雕饰的井。一般用以指宫庭园林里的井。南朝梁费昶《行路难》诗之一：“唯闻哑哑城上乌，玉栏金井牵辘轳。”\n珠帘：用珍珠缀成或饰有珍珠的帘子。《西京杂记》卷二：“昭阳殿织珠为帘，风至则鸣，如珩佩之声。”\n熏（xūn）笼：指宫中取暖的用具，与熏炉配套使用的笼子，作熏香或烘干之用。熏：一作“金”。笼：一作“炉”。玉枕：即枕头。\n南宫：指皇帝的居处。一作“宫中”。清漏：漏是古代计时的器具，利用滴水和刻度以指示时辰。清漏指深夜铜壶滴漏之声。南朝宋鲍照《望孤石》诗：“啸歌清漏毕，徘徊朝景终。”\n秋砧（zhēn）：秋日捣衣的声音。北周庾信《夜听捣衣》诗：“秋砧调急节，乱杵变新声。”夜阑：夜残；夜将尽时。汉蔡琰《胡笳十八拍》：“山高地阔兮，见汝无期；更深夜阑兮，梦汝来斯。”\n御衣：帝王所著的衣服。唐李峤《春日游苑喜雨应诏》诗：“密雨迎仙步，低雨拂御衣。”\n青琐：装饰皇宫门窗的青色连环花纹。《汉书·元后传》：“曲阳侯根骄奢僭上，赤墀青琐。”\n金城：即皇帝所住之城。明主：贤明的君主。《左传·襄公二十九年》：“美哉，沨沨乎！大而婉，险而易行，以德辅此，则明主也。”\n奉帚：持帚洒扫。多指嫔妃失宠而被冷落。平明：指天亮。金殿：指宫殿。一作“秋殿”。\n团扇：即圆形的扇子。班婕妤曾作《团扇诗》。暂：一作“且”。共：一作“暂”。\n玉颜：指姣美如玉的容颜，这里暗指班婕妤自己。寒鸦：寒天的乌鸦；受冻的乌鸦。暗指掩袖工谄、心狠手辣的赵飞燕姐妹。\n昭阳：汉代宫殿名，代指赵飞燕姐妹与汉成帝居住之处。\n薄命：命运不好；福分差。《汉书·外戚传下·孝成许皇后》：“妾薄命，端遇竟宁前。”寻思：思索；考虑。唐白居易《南池早春有怀》诗：“倚棹忽寻思，去年池上伴。”\n西宫：皇帝宴饮的地方。\n复道：两层阁楼间的通道。《墨子·号令》：“守宫三杂，外环隅为之楼，内环为楼，楼入葆宫丈五尺，为复道。”\n昭阳殿：指赵飞燕姐妹与汉成帝居住之宫殿。\n白露堂：指失宠妃子或宫女所住之处。\n红罗：红色的轻软丝织品。《汉书·外戚传下·孝成班倢伃》：“感帷裳兮发红罗，纷綷縩兮纨素声。”', poem_appreciation = '其一\n\n　　这首宫怨，运用深婉含蓄的笔触，采取以景托情的手法，写一个被剥夺了青春、自由和幸福的少女，在凄凉寂寞的深宫中，形孤影单、卧听宫漏的情景。这是从这位少女的悲惨的一生中剪取下来的一个不眠之夜。\n\n　　在这个不眠之夜里，诗中人忧思如潮，愁肠似结，她的满腔怨情该是倾吐不尽的。这首诗只有四句，总共二十八个字，照说，即令字字句句都写怨情，恐怕还不能写出她的怨情于万一。可是，作者竟然不惜把前三句都用在写景上，只留下最后一句写到人物，而且就在这最后一句中也没有明写怨情。这样写，乍看像是离开了这首诗所要表现的主题，其实却在艺术效果上更显得有力，更深刻地表现了主题。这是因为：前三句虽是写景，却并非为写景而写景，它们是为最后人物的出场服务的。就通首诗而言，四句诗是融合为一的整体，不论写景与写人，都是为托出怨情服务的。\n\n其二\n\n　　第二首诗描写在夜深霜重的凄凉环境中，宫中女子孤独寂寞的悲惨情景。她彻夜难眠，想起进宫以来的日子实在不堪回首。她渴望得到君王的眷顾，在银灯下守到夜深，最后还是失望而终。这首诗情感抒发较为直接，心理刻画较为生动，充分地表现了宫中失宠女子的幽怨之情。\n\n　　古乐府歌辞中有《怨歌行》一篇，其辞是：“新裂齐纨素，皎洁如霜雪。裁为合欢扇，团团似明月。出入君怀袖，动摇微风发。常恐秋节至，凉飚夺炎热。弃捐箧笥中，恩情中道绝。”此诗相传是班婕妤所作，以秋扇之见弃，比君恩之中断。王昌龄就《怨歌行》的寓意而加以渲染，借长信故事反映唐代宫廷妇女的生活。\n\n　　夜深霜重，木石敲击秋砧的声音响彻寒夜。在这样一个孤寂的深夜，深宫中那个失宠的女子依旧牵挂着君主是否添了衣裳，昏暗的银灯下，独自裁剪缝补，明知道君主不会眷顾，却还是在内心深处怀着深切的期盼。\n\n这首诗以心理上的深刻描写见长，抒情直接，寥寥数语将一个深宫失宠的女子渴望君主眷顾，挂念君主寒暖又间杂着对君主弃自己于不顾，对自己的一厢深情视而不见的怨愤和痛苦。淋漓尽致地表现了深宫失宠女子难于言表的幽怨之情。\n\n其三\n\n　　第三首诗中前两句写天色方晓，金殿已开，就拿起扫帚，从事打扫，这是每天刻板的工作和生活；打扫之余，别无他事，就手执团扇，且共徘徊，这是一时的偷闲和沉思。徘徊，写心情之不定，团扇，喻失宠之可悲。说“且将”则更见出孤寂无聊，唯有袖中此扇，命运相同，可以徘徊与共而已。\n\n　　后两句进一步用一个巧妙的比喻来发挥这位宫女的怨情，仍承用班婕妤故事。昭阳，汉殿，即赵飞燕姊妹所居。时当秋日，故鸦称寒鸦。古代以日喻帝王，故日影即指君恩。寒鸦能从昭阳殿上飞过，所以它们身上还带有昭阳日影，而自己深居长信，君王从不一顾，则虽有洁白如玉的容颜，倒反而不及浑身乌黑的老鸦了。她怨恨的是，自己不但不如同类的人，而且不如异类的物——小小的、丑陋的乌鸦。按照一般情况，“拟人必于其伦”，也就是以美的比美的，丑的比丑的，可是玉颜之白与鸦羽之黑，极不相类；不但不类，而且相反，拿来作比，就增强了表达效果。因为如果都是玉颜，则虽略有高下，未必相差很远，那么，她的怨苦，她的不甘心，就不会如此深刻了，而上用“不及”，下用“犹带”，以委婉含蓄的方式表达了其实是非常深沉的怨愤。凡此种种，都使得这首诗成为宫怨诗的佳作。\n\n其四\n\n　　同样是抒写失宠宫嫔的幽怨，表现她们内心的深刻痛苦，在王昌龄笔下，却很少艺术上的雷同重复。第四首诗则带有更多的直接抒情和细致刻画心理的特点。\n\n　　第一句就单刀直入，抒写失宠宫嫔的内心活动。“真成薄命”，是说想不到竟真是个命运不幸的失宠者。这个开头，显得有些突兀，让人感到其中有很多省略。看来她不久前还是得宠者。但宫嫔得宠与否，往往取决于君主一时好恶，或纯出偶然的机缘。因此这些完全不能掌握自己命运的宫嫔就特别相信命运。得宠，归之幸运；失宠，归之命薄。而且就在得宠之时，也总是提心吊胆地过日子，生怕失宠的厄运会突然降临在自己头上。“真成薄命”这四个字，恰似这位失宠宫嫔内心深处一声沉重的叹息，把她那种时时担心厄运降临，而当厄运终于落到头上时既难以置信，又不得不痛苦地承认的复杂心理和盘托出了。这样的心理刻画，是很富包蕴的。\n\n　　失宠的命运降临之后，她陷入久久的寻思。因“思”而入“梦”，梦中又在重温过去的欢乐，表现出对命运的希冀，对君主的幻想，而在自己心中重新编织得宠的幻影。但幻梦毕竟代替不了现实，一觉醒来，眼前面对的仍是寂寞的长信宫殿，梧桐秋叶，珠帘夜霜，听到的仍是悠长凄凉的铜壶清漏。于是又不得不怀疑自己这种侥幸的希望原不过是无法实现的幻梦。以上两句，把女主人公曲折复杂的心理刻画得细致入微而又层次分明。\n\n　　就在这位失宠者由思而梦，由梦而疑，心灵上倍受痛苦煎熬的时刻，不远的西宫那边却向她展示了一幅灯火辉煌的图景。不用说，此刻西宫中又正在彻夜宴饮，重演“平阳歌舞新承宠”的场面了。这情景对她来说是那样的熟悉，使她一下子就唤起了对自己“新承宠”时的记忆，仿佛回到了当初在复道受君主恩宠的日子。可是这一切此刻又变得那样遥远，承宠的场面虽在重演，但华美的西宫已经换了新主。“分明”二字，意余言外，耐人咀嚼。它包含了失宠者在寂寞凄凉中对往事历历分明的记忆和无限的追恋，也蕴含着往事不可回复的深沉感慨和无限怅惘，更透露出不堪回首往事的深刻哀伤。\n\n其五\n\n　　这是一首抒发宫怨的诗歌。昭阳殿是西汉赵飞燕得宠时住的寝宫，后来以昭阳殿泛指得宠嫔妃。长信宫是在赵飞燕得宠时失宠嫔妃班婕妤住的寝宫，后来泛指失宠嫔妃。\n\n　　后两句运用对比描写出失宠于得宠截然不同的差距，白露堂中细草迹是指失宠嫔妃的宫闱清冷，杂草丛生，一片荒凉凄清，使得人物也显得十分幽怨。\n\n　　红罗帐里不胜情，是指得宠的嫔妃寝宫里红帐高挂，与君王软语温存，不胜惬意，说不完的情意绵绵话。\n\n　　王昌龄从女性角度出发，运用对比，生动形象刻画了失宠嫔妃与得宠嫔妃的天壤之别，是宫怨诗中难得的题材。对那些嫔妃寄予深深的同情。', poem_tags = '唐诗三百首,秋天,闺怨' WHERE poem_title = '长信怨' AND poem_author = '王昌龄';
UPDATE edu_poem SET poem_translation = '清邑军队驻在彭，驷马披甲真威风。两矛装饰重缨络，黄河边上似闲庭。\n清邑军队驻在消，驷马披甲威又骄。两矛装饰野鸡毛，黄河边上自逍遥。\n清邑军队驻在轴，驷马披甲任疾跑。左转身子右拔刀，军中好像准备好。', poem_notes = '清人：指郑国大臣高克带领的清邑的士兵。清，郑国之邑，一说卫国邑名，在今河南省中牟县西。\n彭：郑国地名，在黄河边上。\n驷（sì）介：一车驾四匹披甲的马。介：甲。旁旁：同“彭彭”，马强壮有力貌。一说行走、奔跑貌。\n二矛：酋矛、夷矛，插在车子两边。重（chóng）英：以朱羽为矛饰，二矛树车上，遥遥相对，重叠相见。重，重叠。英，矛上的缨饰。\n翱（áo）翔：游戏之貌。\n消：黄河边上的郑国地名。\n镳（biāo）镳：英勇威武貌。\n乔：借为“鷮（jiāo）”，长尾野鸡，此指矛上装饰的鷮羽毛。\n逍遥：闲散无事，驾着战车游逛。\n轴：黄河边上的郑国地名。\n陶陶：和乐貌。一说马疾驰之貌。\n左旋右抽：御者在车左，执辔御马；勇士在车右，执兵击刺。旋，转车。抽，拔刀。\n中军：即“军中”。一说指古三军之中军主帅。作好：容好，与“翱翔”“逍遥”一样也是连绵词，指武艺高强。一说做好表面工作，指装样子，不是真要抗拒敌人。', poem_appreciation = '这是一首辛辣的讽刺诗。在此诗作者眼中，高克带领的部队，战马披甲，不可谓不雄壮；战车插矛，不可谓不威武。可是清邑的士兵却不是在为抵御敌人随时可能的入侵而认真备战，却在河上逍遥游逛，耍弄刀枪；身为将帅的高克也闲来无事，只是以练武来消磨时光而已。此诗讽刺的对象是高克，而最终深深斥责的是郑文公的昏庸。\n\n　　至于为什么说讽刺的矛头最终是对准郑文公，古代有一位论者分析得很有道理：“人君擅一国之名宠，生杀予夺，唯我所制耳。使高克不臣之罪已著，按而诛之可也。情状未明，黜而退之可也。爱惜其才，以礼驭之亦可也。乌可假以兵权，委诸竟上（边境），坐视其离散而莫之恤乎！《春秋》书曰：‘郑弃其师。’其责之深矣！”（朱熹《诗集传》引胡氏语）。总之，在抵御外敌之时，郑文公因讨厌高克反而派他带领清邑士兵去河边驻防的决策是完全错误的。\n\n　　全诗共三章，写清邑士兵在黄河边上的彭地、消地、轴地驻防时的种种表现。表面上是在称颂他们，说他们的披甲战马如何强壮，奔驰起来又如何威风；战车上装饰着漂亮的矛，是如何的壮盛；军中的武士也好，主帅也好，武艺又是如何高强。而实际上他们却是在河上闲散游逛。每章的最后一句如画龙点睛，用“翱翔”、“逍遥”、“作好”等词来揭出本相，其讽刺的手法是较为含蓄的。从诗的章法上说，三个章节的结构和用词变化都不甚大，只有第三章与前两章不同处较多。作者采用反复咏叹的手法，以增强诗歌的气势和表现力，从而达到其讽刺的效果。', poem_tags = '诗经,战争' WHERE poem_title = '清人' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '从道州城向西走一百多步，有一条小溪。这条小溪向南流几步远，汇入营溪。两岸全是一些奇石，（这些石头）有的倾斜嵌叠，有的盘曲回旋，不能够用言语形容（它们的美妙）。清澈的溪流撞击着岩石，水回旋而流，激水触石溅起高高的浪花，激荡倾注；岸边美丽的树木和珍奇的青竹，投下的阴影互相掩映。\n\n　　这条溪水如果在空旷的山间田野，就是很适合避世隐居的人和隐士居住的；如果它在人烟密集的地方，也可以成为都会城镇（市民游览）的胜地，仁者休憩的园林。但是自从道州成为州的治所以来，至今也没有人来欣赏和关爱（它）；我在溪水边走来走去，为它（景色秀丽但无人知晓）而惋惜！于是进行疏导开通，清除掉杂乱的草木，建起了亭阁，栽上了松树、桂树，又种植了鲜花香草，来增益它优美的景致。因为溪水在道州城的右面，便命名为“右溪”。把这些文字刻在石上，明白地告诉后来人。', poem_notes = '右溪：唐代道州城西的一条小溪，元结任道州刺史时曾对它进行修葺，并刻石铭文，取名“右溪”。道州唐代时属江南西道，治所在今湖南道县。“右”，古以东为左，西为右，此溪在城西，所以作者取名“右溪”。\n南：向南。\n合：汇合。\n营溪：谓营水，源出今湖南宁远，西北流经道县，北至零陵入湘水，湘江上游的较大支流。\n抵：击拍。\n悉皆：都是。悉，全。\n敧嵌(qīqiàn)：石块错斜嵌插溪岸的样子；“攲”，倾斜。盘屈，怪石随着溪岸弯曲曲折的样子。\n不可名状：无法形容它们的状态。名，形容。状，（它们的）状态。\n洄(huí)：水回旋而流。悬，激水触石溅起高高的浪花。激，形容被石遏制而造石成的急流。注，形容水急如灌注一般。\n佳木：美丽的树木。佳，美好。\n垂阴：投下阴影。\n相荫：彼此遮蔽荫护。荫，遮蔽。\n逸民退士：指不仕的隐者和归隐的官宦。\n人间：与前文“山野”对称，谓世俗社会，主要相对隐逸而言，指仕宦于朝。嵇康《答山巨源绝交书》：“又每非汤、武而薄周、孔，在人间不止，此事会显，世教所不容。”其义同此。\n都邑：都会城镇。邑，县城。\n胜境：风景优美的境地。\n静者：喜欢清静的人，谓仁人。《论语·雍也》载：“孔子曰：‘知者乐水，仁者乐山。知者动，仁者静。’”\n置州：谓唐朝设置道州。唐高祖武德四年(612年)设置南营州，太宗贞观八年(634年)改为道州，玄宗天宝元年(742年)改设江华郡，肃宗乾元元年(758年)复称道州。\n已来：同“以来”。\n为之怅然：为它景色优美却无人知晓而惋惜。之，指右溪“无人赏爱”。怅然，惆怅抱憾的样子。\n乃：于是。\n疏凿芜秽：疏通水道，开挖乱石，去除荒草杂树。芜秽，杂草积土。\n俾(bǐ)：使。为，修筑。亭宇，亭子房屋。\n兼之：并且在这里种植。\n裨(bì）：补助，增添。\n形胜，优美的风景。\n命：命名。\n铭：铭文，指作者为右溪所作的铭文。作者的《阳华志铭》、《五如石铭》、《浯溪铭》等其它同类作品，大多以铭文为主，前有小序。则本篇当同其例，应有铭文，此记属序。但铭文已佚，后人为拟题作“记”。\n彰示来者：告诉后来的游人。来者，后来的游者。', poem_tags = '写景,抒情,怀才不遇' WHERE poem_title = '右溪记' AND poem_author = '元结';
UPDATE edu_poem SET poem_translation = '苏秦起先主张连横，劝秦惠王说：“大王您的国家，西面有巴、蜀、汉中的富饶，北面有胡貉和代马的物产，南面有巫山、黔中的屏障，东面有肴山、函谷关的坚固。耕田肥美，百姓富足，战车有万辆，武士有百万，在千里沃野上有多种出产，地势形胜而便利，这就是所谓的天府，天下显赫的大国啊。凭着大王的贤明，士民的众多，车骑的充足，兵法的教习，可以兼并诸侯，独吞天下，称帝而加以治理。希望大王能对此稍许留意一下，我请求来实现这件事。”\n　　秦王回答说：“我听说：羽毛不丰满的不能高飞上天，法令不完备的不能惩治犯人，道德不深厚的不能驱使百姓，政教不顺民心的不能烦劳大臣。现在您一本正经老远跑来在朝廷上开导我，我愿改日再听您的教诲。”\n　　苏秦说：“我本来就怀疑大王不会接受我的意见。过去神农讨伐补遂，黄帝讨伐涿鹿、擒获蚩尤，尧讨伐驩兜，舜讨伐三苗，禹讨伐共工，商汤讨伐夏桀，周文王讨伐崇国，周武王讨伐纣王，齐桓公用武力称霸天下。由此看来，哪有不用战争手段的呢？古代让车辆来回奔驰，用言语互相交结，天下成为一体，有的约从有的连横，不再储备武器甲胄。文士个个巧舌如簧，诸侯听得稀里胡涂，群议纷起，难以清理。规章制度虽已完备，人们却到处虚情假意，条文记录又多又乱，百姓还是衣食不足。君臣愁容相对，人民无所依靠，道理愈是清楚明白，战乱反而愈益四起。穿着讲穿服饰的文士虽然善辩，攻战却难以止息。愈是广泛地玩弄文辞，天下就愈难以治理。说的人说得舌头破，听的人听得耳朵聋，却不见成功，嘴上大讲仁义礼信，却不能使天下人相亲。于是就废却文治、信用武力，以优厚待遇蓄养勇士，备好盔甲，磨好兵器，在战场上决一胜负。想白白等待以招致利益，安然兀坐而想扩展疆土，即使是上古五帝、三王、五霸，贤明的君主，常想坐而实现，势必不可能。所以用战争来解决问题，相距远的就两支队伍相互进攻，相距近的持着刀戟相互冲刺，然后方能建立大功。因此对外军队取得了胜利，对内因行仁义而强大，上面的国君有了权威，下面的人民才能驯服。现在，要想并吞天下，超越大国，使敌国屈服，制服海内，君临天下百姓，以诸侯为臣，非发动战争不可。现在在位的国君，忽略了这个根本道理，都是教化不明，治理混乱，又被一些人的奇谈怪论所迷惑，沉溺在巧言诡辩之中。象这样看来，大王您是不会采纳我的建议的。”\n　　劝说秦王的奏折多次呈上，而苏秦的主张仍未实行，黑貂皮大衣穿破了，一百斤黄金也用完了，钱财一点不剩，只得离开秦国，返回家乡。缠着绑腿布，穿着草鞋，背着书箱，挑着行李，脸上又瘦又黑，一脸羞愧之色。回到家里，妻子不下织机，嫂子不去做饭，父母不与他说话。苏秦长叹道：“妻子不把我当丈夫，嫂子不把我当小叔，父母不把我当儿子，这都是我的过错啊！”于是半夜找书，摆开几十只书箱，找到了姜太公的兵书，埋头诵读，反复选择、熟习、研究、体会。读到昏昏欲睡时，就拿针刺自己的大腿，鲜血一直流到脚跟，并自言自语说：“哪有去游说国君，而不能让他拿出金玉锦绣，取得卿相之尊的人呢？”满一年，研究成功，说：“这下真的可以去游说当代国君了！”\n　　于是就登上名为燕乌集的宫阙，在宫殿之下谒见并游说赵王，拍着手掌侃侃而谈，赵王大喜，封苏秦为武安君。拜受相印，以兵车一百辆、锦绣一千匹、白璧一百对、黄金一万镒跟在他的后面，用来联合六国，瓦解连横，抑制强秦，所以苏秦在赵国为相而函谷关交通断绝。\n　　在这个时候，那么大的天下，那么多的百姓，王侯的威望，谋臣的权力，都要被苏秦的策略所决定。不花费一斗粮，不烦劳一个兵，一个战士也不作战，一根弓弦也不断绝，一枝箭也不弯折，诸侯相亲，胜过兄弟。贤人在位而天下驯服，一人被用而天下合纵，所以说：应运用德政，不应凭借勇力；应用于朝廷之内，不应用于国土之外。在苏秦显赫尊荣之时，黄金万镒被他化用，随从车骑络绎不绝，一路炫耀，华山以东各国随风折服，从而使赵国的地位大大加重。况且那个苏秦，只不过是出于穷巷、窑门、桑户、棬枢之中的贫士罢了，但他伏在车轼之上，牵着马的勒头，横行于天下，在朝廷上劝说诸侯王，杜塞左右大臣的嘴巴，天下没有人能与他匹敌。\n　　苏秦将去游说楚王，路过洛阳，父母听到消息，收拾房屋，打扫街道，设置音乐，准备酒席，到三十里外郊野去迎接。妻子不敢正面看他，侧着耳朵听他说话。嫂子像蛇一样在地上匍匐，再三再四地跪拜谢罪。苏秦问：“嫂子为什么过去那么趾高气扬，而现在又如此卑躬屈膝呢？”嫂子回答说：“因为你地位尊贵而且很有钱呀。”苏秦叹道：“唉！贫穷的时候父母不把我当儿子，富贵的时候连亲戚也畏惧，人活在世上，权势地位和荣华富贵，难道是可以忽视的吗？”', poem_notes = '苏秦：字季子，战国时洛阳人，著名策士，纵横派代表人物，先用连横之说说秦，后又主张合纵，为东方六国所任用，后因在齐国为燕昭王从事反间活动被发觉，车裂而死。\n连横：战国时代，合六国抗秦，称为约从（或“合纵”）；秦与六国中任何一国联合以打击别的国家，称为连横。\n说（shuì）：劝说，游说。\n秦惠王：前年至前年在位。\n巴：今四川省东部。\n蜀：今四川省西部。\n汉中：今陕西省秦岭以南一带。\n胡：指匈奴族所居地区。\n貉（hé）：一种形似狐狸的动物，毛皮可作裘。\n代：今河北、山西省北部。以产良马闻世。\n巫山：在今四川省巫山县东。\n黔中：在今湖南省沅陵县西。\n限：屏障。\n肴：同“肴”，肴山在今河南省洛宁县西北。\n函：函谷关，在今河南省灵宝县西南。\n奋击：奋勇进击的武士。\n天府：自然界的宝库。\n俨然：庄重矜持。\n愿以异日：愿改在其他时间。\n神农：传说中发明农业和医药的远古帝王。\n补遂：古国名。\n黄帝：姬姓，号轩辕氏，传说中中原各族的共同祖先。\n涿鹿：在今河北省涿鹿县南。\n禽：通“擒”。\n蚩尤：神话中东方九黎族的首领。\n驩（huān）兜（dōu）：尧的大臣，传说曾与共工一起作恶。\n三苗：古代少数民族。\n共工传为尧的大臣，与驩兜、三苗、鲧并称四凶。\n有夏：即夏桀。“有”字无义。\n崇：古国名，在今陕西省户县东。\n纣：商朝末代君主，传说中的大暴君。\n伯：同“霸”，称霸。\n恶：同“乌”，何。\n毂（gǔ）：车轮中央圆眼，以容车轴。这里代指车乘。\n饬：通“饰”，修饰文词，即巧为游说。\n万端俱起：群议纷起。\n稠浊：多而乱。\n聊：依靠。\n章：同“彰”，明显。\n伟服：华丽的服饰。\n厉：通“砺”，磨砺。\n徒处：白白地等待。\n五伯：伯同“霸”，“五伯”即春秋五霸。指春秋时先后称霸的五个诸侯：齐桓公、宋襄公、晋文公、秦穆公、楚庄王。\n杖：持着。\n橦（chōng）：冲刺。\n凌：凌驾于上。\n万乘：兵车万辆，指大国。\n诎：同“屈”，屈服。\n元元：人民。\n嗣主：继位的君王。\n至道：指用兵之道。\n惛：不明。\n说不行：指连横的主张未得实行。\n羸（léi）：缠绕。\n縢（téng）：绑腿布。\n蹻（jué）草鞋。\n橐（tuó）：囊。\n犁：通“黧”（lí），黑色。\n归：应作“愧”。\n紝（rèn）：纺织机。\n太公：姜太公吕尚。\n阴符：兵书。\n简：选择。\n练：熟习。\n足：应作“踵”，足跟。\n摩：靠近。\n燕乌集：宫阙名。\n华屋：指宫殿。\n抵：通“抵”（zhǐ），拍击。\n武安：今属河北省。\n溢：通“镒”。一镒二十四两。\n关：函谷关，为六国通秦要道。\n式：用。\n廊庙：指朝廷。\n隆：显赫。\n山东：指华山以东。\n使赵大重：谓使赵的地位因此而提高。\n掘门：同窟门，窰门。\n桑户：桑木为板的门。\n棬（quān）枢：树枝做成的门枢。\n轼：车前横木。\n撙（zǔn）：节制。\n伉：通“抗”。\n张：设置。\n倨：傲慢。\n季子：苏秦的字。\n盖：同“盍”，何。', poem_tags = '古文观止,故事,写人' WHERE poem_title = '苏秦以连横说秦' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '时令将近寒食，春雨绵绵春草萋萋；春风过处苗麦摇摆，堤上杨柳依依。\n这是为什么呵，我却有家归去不得？杜鹃呵，不要在我耳边不停地悲啼。', poem_notes = '著：吹入。\n等是：为何。\n杜鹃：鸟名，即子规。', poem_tags = '唐诗三百首,寒食节,思乡,感伤' WHERE poem_title = '杂诗' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '自从那天送你远去，我心里总是对你难分难舍，一点相思情在心中萦绕不绝。记得送别时我斜倚着栏杆目送你远行。我用衣袖拂去如雪的杨花，以免妨碍视线。然而你的身影已看不见了，只见弯弯曲曲的小溪向东流去，重重的山峦遮住了你远行的道路，我才意识到心上的人，真的走远了。', poem_notes = '南吕：宫调名。四块玉：曲牌名。\n绝：断。\n凭阑袖拂杨花雪：写主人公靠着阑干，用袖拂去如雪的飞絮，以免妨碍视线。杨花雪，语出苏轼《少年游》：“去年相送，余杭门外，飞雪似杨花。今年春尽，杨花似雪，犹不见还家。”如雪花般飞舞的杨花。\n斜：此处指溪流拐弯。', poem_appreciation = '这是一首描写离别情绪的小令，用代言体写男女离别相思，从语言、结构到音情都有值得称道之处。\n\n　　“自送别，心难舍，一点相思几时绝。”自从送别以后，心中万分难舍，一点相思之情，绵绵不断，不知何时能停止？作者以主人公——一名与爱人分离的女子口吻写来，直抒其缠绵的相思、真挚的爱情。曲从别后说起，口气虽平易，然送别的当时，既觉“难舍”，过后思量，心绪自然无法平静。说“相思”只“一点”，似乎不多，但又不知“几时”能绝。这就强调了别情缠绵的一面，比起强调别情沉重的那一面，似乎更合情理，此即所谓藕断丝连。“一点相思几时绝”是全篇的中心，它强调了别情的缠绵，使之成为全篇描写和抒情的基调，也使前三句显得十分形象。\n\n　　“凭阑袖拂杨花雪”一句有二重意味：首先点明季节为暮春（杨花如雪）时候，此时节容易动人离思，句中或许还含有“去年相送，余杭门外，飞雪似杨花。今年春尽，杨花似雪，犹不见还家”（苏轼《少年游》）那种暗示别离情景的意味；二是点明处所系有阑干处，当是高楼；与此同时也就点明了女主人公是独上高楼，她在楼上站了很久，以致杨花飞满衣襟，须时时“袖拂”。\n\n　　末尾三句“溪又斜，山又遮，人去也”，分明是别时景象，它与前数句的关系不甚确定。可有多种解会。可作顺承看，女主人公既在“凭阑”，不免由望情人的去路而引起神伤，“人去也”是痛定思痛的口吻。另一种是作逆挽看，可认为作者在章法上作了倒叙腾挪，近乎小山词所谓“从别后，忆相逢”（晏几道《鹧鸪天》）的写法。两种解读都可以，就造就了作品的多义性和启发性，体现了作品之妙。', poem_tags = '离别,相思' WHERE poem_title = '四块玉·别情' AND poem_author = '关汉卿';
UPDATE edu_poem SET poem_translation = '为别离伤感，江南的大雁无法传来你的消息。音讯断绝，我内心愁肠郁结，流下眼泪。想起之前中秋节的时候，月亮和今天的一样。那时候我们还未分别，可今天啊，月亮是圆满的，我们是残缺的。', poem_notes = '音书：音讯，书信。\n珠泪：眼泪，因泪滴圆如珠，故称。', poem_tags = '离别｜抒情｜伤感｜怀人' WHERE poem_title = '忆秦娥·伤离别' AND poem_author = '何梦桂';
UPDATE edu_poem SET poem_translation = '汉水滔滔，向东流去；它冲净了那些满脸长着胡须的敌人嘴上沾着人民的膏血。人们都说：当年你家的飞将军，英勇威列地打击敌人。攻破敌人坚固的城池的时候，迅速勇猛，像迅雷过耳那么快；在玉帐里谈论兵法或者是研究战术的时候，态度激昂兴奋，语言慷慨激烈，两颊都结了冰。回想王郎，你才到结发的年令，就从事戎马生活。继承着先人的事业。\n我腰里悬挂的宝剑没有用了，只有在无聊的时候，把它当作乐器，弹着剑柄唱唱歌。今天拿着酒杯，喝着酒为你送别。况且这是我的好朋友你，又是重新被任用，你簇拥旌节的仪仗，登上了拜将坛，封你为编率大军的将军。你是大丈夫男儿汉，应当把马革裹尸当作自己的誓言，为了消灭敌人，为国捐躯是最光荣的。有些人，贪图安乐，迷恋女色，是自伐生命，应以为戒，再也不要说它了。从今后，要牢牢记住：咱们在楚楼、裴台吟风赏月的这段友谊。', poem_notes = '汉水：长江支流，源出陕西，流经湖北，穿武汉市而入长江。\n髭（zī）胡：代指入侵的金兵。膏血：指尸污血腥。\n飞将：指西汉名将李广。他善于用兵，作战英勇，屡败匈奴，被匈奴誉为“飞将军”。《史记·李将军列传》：“广居右北平，匈奴闻之，号曰‘汉之飞将军’，避之数岁，不敢人右北平。”\n金城：言城之坚，如金铸成。雷过耳：即如雷贯耳，极言声名大震。\n玉帐：主帅军帐的美称。宋张淏《云谷杂记》：“《艺文志》有《玉帐经》一卷，乃兵家厌胜之方位，谓主将于其方置军帐，则坚不可犯，犹玉帐然，其法出于皇帝遁甲云。”冰生颊：言其谈兵论战明快爽利，辞锋逼人，如齿颊间喷射冰霜。宋苏轼《浣溪沙·有赠》：“上殿云霄生羽翼，论兵齿颊带风霜”\n结发：即束发。古代男子二十岁束发，表示成年。从戎：从军。《三国志·魏书·王粲传》：“年十七，司徒辟，诏除黄门侍郎，以西京扰乱，皆不就。乃之荆州依刘表。……魏国既建，拜侍中。曹操于建安二十年三月西征张鲁于汉中，张鲁降。是行也，侍中王粲作《从军行》五首以美其事。”\n弹铗：敲击剑柄。《战国策·齐策四》：“齐人有冯谖者，贫乏不能自存，使人属孟尝君，愿寄食门下。孟尝君曰：‘客何好？’曰：‘客无好也。’曰：‘客何能？’曰：‘客无能也。’孟尝君笑而受之曰：‘诺。’……居有顷，倚柱弹其剑，歌曰：‘长铗归来乎！食无鱼。’”\n汉坛旌（jīng）节：暗用刘邦筑坛拜韩信为大将事。《汉书·高帝纪》：“于是汉王斋戒，设坛场，拜信为大将军。”\n马革裹尸：用马皮裹卷尸体。《后汉书·马援传》：“方今匈奴、乌桓尚扰北边，欲自请击之。男儿要当死于边野，以马革裹尸还葬耳，何能卧床上在儿女子手中邪？”\n蛾眉：女子修长而美丽的眉毛，代指美女。汉枚乘《七发》：“洞房清宫，命曰寒热之媒；皓齿娥眉，命曰伐性之斧；甘脆肥醲，命曰腐肠之药。”\n楚楼：即兰台。故址在今湖北江陵。宋李曾伯《可斋杂著》卷二八《登江陵沙市楚楼》：“壮丽中居荆楚会，风流元向蜀吴夸。 楼头恰称元龙卧，切勿轻嗤作酒家。”\n庾（yǔ）台：一称南楼，在今湖北武昌市。东晋庾亮为荆州刺史时，曾偕部属登斯楼赏月。', poem_appreciation = '这首词是一首送别之作，因为友人军职升迁是一件大喜事，所以此词全无哀婉伤感之情，通篇都是对友人的赞扬与鼓励，只是最后提醒友人不要忘记知音好友，一点即止。\n\n　　上片写战争过去，人们的战争，敌情观念薄弱了，“髭胡膏血”都被汉水洗净了，这是一句反义用语，道出了作者心里的不平。接着用“人尽说”回忆王君的“归时英烈”。下片的过片与上片的开头遥相照应。既然没有战争了，刀剑就应入库了。腰间剑，聊弹铗；尊中酒，堪为别——前两句由友人写到自己，以战国时的冯谖为喻，表达作者勇无所施、报国无门的愤懑。后两句表达自己对送行友人的歉意，言自己无物可送，只能用杯子之酒为别去的朋友送行。\n\n　　况故人新拥、汉坛旌节——“汉坛”，汉高祖刘邦曾在汉中筑坛拜韩信为大将。这两句言朋友官职地位之重，言外之意，朋友处此重位，定能像当年的韩信一样一展抱负，发挥自己的才能，为国立功。马革裹尸当自誓，蛾眉伐性休重说。——这两句承上，前句用东汉马援之典。后句化用枚乘《七发》中“皓齿蛾眉，命曰伐性之斧”语句，是说贪恋女色，必当自残生命。词人认为男儿应当立誓以马革裹尸死在沙场而还，至于那些沉溺酒色自戕生命之行再也休提，以此激励友人要以杀敌报国为务，勿沉溺于男女私情而堕了青云之志。\n\n　　但从今，记取楚台风，庾台月。——引用战国宋玉和东晋庾亮的典故。以此劝诫友人：不要忘记咱们在楚楼、裴台吟风赏月的这段友谊。全词激昂沉郁，愤懑与不平隐含在曲折之中。', poem_tags = '咏史怀古,告诫' WHERE poem_title = '满江红·汉水东流' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '秋色日渐变浓，金黄的菊花传报霜降的信息。小窗低户深深掩映在菊花丛中，小路盘山而上，曲折倾斜。询问山公到底有什么心事， (原来是不忍心)坐看时光轻易流逝而双鬓花白。在太湖边上徘徊凝望，天空澄澈，湖水映照着明丽的彩霞。\n追忆往日，漂泊不定，走遍天涯海角，却毫无建树。归来后重新打扫庭院中的小路，松竹才是我的家。却恨悲凉的秋风不时吹起，南归的大雁缓缓地飞行在云间，哀怨的胡笳声和边马的悲鸣声交织在一起。谁能像东晋谢安那样，谈笑间就扑灭了胡人军马扬起的尘沙。', poem_notes = '秋色渐将晚，霜信报黄花。：暮秋景物渐呈苍老深暗之色，菊花开时报来了将要降霜的信息。黄花，指菊花。\n小窗低户：指简陋的房屋。\n微路，小路。\n敧（qī）斜：倾斜，歪斜。\n山翁：《晋书·山简传》载山简好酒易醉。作者借以自称。\n何事：为什么。\n坐看：空看、徒欢。\n流年：指流逝的岁月。\n拚（pàn判） 却：甘愿。\n华：同花，指在闲居中空白了鬓发。\n徙（xǐ）倚：徘徊，流连不去。\n沧海：此指临近湖州的太湖。作者时居汴山，在太湖南岸。\n平昔：往日。\n遍：这里是“走遍”的意思。\n天涯，天边，喻平生飘荡之远。\n归来三径重扫，松竹本吾家：写辞官归隐家园。化用晋代陶渊明《归去来兮辞》：“三径就荒，松菊犹存。”三径，庭院间的小路。据晋代赵岐《三辅决录-逃名》记载，西汉末，王莽专权，兖州刺史蒋诩辞官归里，院中辟有三径，只与求仲、羊仲往来。后来遂以“三径”作为隐士居所之称。松竹，代指山林隐居处，含有贞节自持之意。三径：王莽专权时，兖州刺史蒋诩辞宫回家，于园中辟三径，惟与求仲、羊仲往来。后常用三径喻隐居生活。\n却恨悲风时起，冉冉云间新雁，边马怨胡笳。：这里化用三国时魏国蔡琰《悲愤诗》。“胡笳动兮边马鸣，孤雁归兮声嘤嘤!”悲风，悲凉的秋风。冉冉，指大雁缓缓飞行的样子。新雁，指最初南归之雁。边马，指边地的军马。胡笳，古代塞外民族的一种乐器。此处指军中的号角。\n谁似东山老，谈笑净胡沙：化用李白《永王东巡歌》中的“但用东山谢安石，为君谈笑净胡沙”。胡沙。指代胡人发动的战争。', poem_appreciation = '这首词是作者晚年退居卞山所作。它是一首自叙平生、抒写情怀的词。表达了作者心中的悲愤之情和对国事担忧。\n\n　　词分上下两片。上片以写景为主，兼寓流年虚度的慨叹。\n\n　　“秋色渐将晚，霜信报黄花。”词的第一个字“秋”，点明时序，是泛指。然后再具体写秋色。“晚”字是形象的说法，它既不是“来得晚”的意思，也不是确指“晚上”，而是由“老”引伸出来的含意。意思是说，暮秋的景物渐渐地呈现出苍老深暗的颜色了。伴随深秋而来的，自然是凛冽的冰霜，以及那“颜色只从霜后好，不知人世有春风”性本高洁的菊花，即词里所说的黄花。黄花开，霜降至。\n\n　　“小窗低户深映，微路绕敧斜。”“小窗低户”形容房屋简陋，敧斜即倾斜的意思。这两句是说，简陋的小屋掩映于秋色黄花之中，屋前是曲折倾斜的小路。这里既写出了环境的幽清孤寂，也由门前的曲折小路折射出作者的九曲愁肠。\n\n　　“为间山翁何事，坐看流年轻度，拚却鬓双华。”“为”在这里作助词用，没有实在意义。山翁指晋代山简，”这里作者以山简自比。拚却是甘愿的意思。这里有反洁意，是说“难道甘愿”。双鬓华:指年事已高，两鬓生霜。它与上边的“霜信报黄花”有着巧妙的内在联系。前者写秋色将晚，后者写人近晚年。作者以山翁自比。前加“问”字，说明他不甘寂寞，时时在反躬自省。言外之意是我每天干些什么呢?白白地看着年华轻易逝去，这是何等痛心的事情!国难当头，我能甘心服老吗？\n\n　　“徙倚望沧海，天净水明霞”。这一句真实地记录了他经过反复的思考后此刻的开阔心境。徙倚是留连徘徊的意思。沧海即大海，作者以谢安自比，明显地表达了他对谢安不甘示芜的小路，观赏观赏自家的青松翠竹，看似悠弱、泛海东还的退隐之志的仰慕与追求。“天净水明霞”则是眼前美景的写照，以此衬托出他一旦有了明确的人生追求之后的开阔心胸:如秋天长空那样纯净，如霞映水中那样明丽。这短短的几个字，看似平平淡淡，内容却实实在在。既写了体现诗词形象的人，又写了水天明净的景；既写了流连徘徊的貌，又写了泛滥于内心深处的情。情中见景，景中含情，可谓浑然一体了。\n\n　　下片直抒胸怀。写虽然在家闲居，却对国事深怀忡忡忧心，自恨不能为国建功立业。\n\n　　“念平昔，空飘荡，遍天涯。”三字一句，短促有力，如响板敲来，铿然有声，抒发了作者回想往事，空在四方飘游而无所成就的自责自罪、自怨自艾的怅惘心情。“空飘荡，遍天涯”既显示了他的谦谨胸怀，又委婉地传达出他企望重操旧业、再立新功的心声。\n\n　　“归来三径重扫，松竹本吾家。”写的是闲居生活的无聊小事。作者写自己:每天在庭院中扫扫荒芜的小路，观赏观赏自家的青松翠竹，看似悠闲自在，实则这绝不是他心甘情愿的。\n\n　　“却恨悲风时起，冉冉云间新雁，边马怨胡茄。”悲风指凄厉的寒风。却恨是更恨的意思。“悲风”之前加上“却恨”，强化了词人的情感波澜，即由怅惘不安进而愤愤不平了。为什么？因为冉冉飞翔于白云之间的新雁带来了敌人侵扰的消息，边境很不安宁啊!胡茄是汉代流行于塞北和西域一带的管乐器，其音悲凉。作者用眼前悲风、新雁、战地边马、胡茄组接的凄清图景，烘托边地悲凉的战争景象。而作者身在深山、心存国事，为敌人的入侵骚扰而忧心忡忡的心绪便于这“眼前景、身外事”的看似平淡的记叙中得到实实在在的展示。\n\n　　“谁似东山老，谈笑净胡沙。”这一句大笔淋漓，一语见雄杰。东山在浙江上虞县西南，谢安早年隐居在这里。又临安、金陵均有东山，也是谢安游憩之地。所以后人称谢安为东山老。胡沙即胡人。因胡人多居风沙时起的塞外。静胡沙是使边塞安宁的意思，这里指的是消灭敌人。这里借用李白《永王东巡歌》里“但用东山谢安石，为君谈笑静胡沙”的诗意抒写自己的报国情怀。“谁似东山老”两句，既是说，在当今时代，没有人能像谢安那样，指挥若定地歼灭敌人，也是说自己不能像谢安那样，“谈笑静胡沙”作者运用反洁语气，长声仰叹，既是精忠报国的宣言，也是对腐朽朝廷的愤怒控告!读来气势磅礴，声情并壮，足可泣鬼神、撼日月、振山河。', poem_tags = '宋词三百首,豪放,隐居,生活,忧国忧民' WHERE poem_title = '水调歌头·秋色渐将晚' AND poem_author = '叶梦得';
UPDATE edu_poem SET poem_translation = '我酒醉后架着小船，在湖中荡漾，听任流水把小船推向花草深处。现实世界的名利缠身，不能解脱，没有办法在这如花的仙境住下去。\n烟水茫茫，笼罩在夕阳的余辉里。两岸的青山排列无数，晚风吹来，落花如雨，竟然不记得来时走过的路了。', poem_notes = '尘缘：佛教名词。佛经中把色、声、香、味、触、法称作 “六尘”。以心攀缘六尘，遂被六尘牵累，故名。\n乱红：落花。李贺《将进酒》：“况是青春日将暮，桃花乱落如红雨。”', poem_tags = '写景,抒情,山水' WHERE poem_title = '点绛唇·醉漾轻舟' AND poem_author = '秦观';
UPDATE edu_poem SET poem_tags = '离别,相思' WHERE poem_title = '江城子·孤山竹阁送述古' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '紧急征召的文书从边塞岗亭传来，战争爆发的消息已经传到京都。被征召的骑兵驻扎在广武县，将兵分几路解救被困的朔方。肃杀的秋天虽然十分寒冷，但战士们的战斗豪情丝毫没有减弱，他们手里的弓箭更加强劲了。但敌人的战阵也精锐而坚强。天子听到敌兵气焰嚣张的消息，按不住心中的怒火，也亲临战场与敌人一搏。战争十分激烈，传送军情战况的使者往来不绝。军队沿石径行进，如雁飞排成的行列；士兵依次渡过桥梁，如游鱼前后连贯。军乐流露出汉人的情思，战士们的旌旗和铠甲都披上了胡地的霜雪。他们冒着疾风冲锋陷阵，战场上的沙砾被扬起，随风飘荡。因为天气寒冷，马毛都像刺猬一样缩成一团，角弓也拉不开了。但在时局危险的时候，才可以看出那些臣子的节操；天下乱的时候，才能看出一个人是否忠良。战士们为回报君主之恩，都奋力拼杀，不顾自己的性命安危。身死之后，他们会成为为国牺牲的光荣的烈士。', poem_notes = '《代出自蓟北门行》是乐府旧题，属杂曲歌辞。此诗通过边庭紧急战事和边境恶劣环境的渲染，突出表现了壮士从军卫国、英勇赴难的壮志和激情。蓟，古代燕国京都，在今北京市西南。\n羽檄（xí）：古代的紧急军事公文。边亭：边境上的瞭望哨。\n烽火：边防告警的烟火，古代边防发现敌情，便在高台上燃起烽火报警。咸阳：城名，秦曾建都于此，借指京城。\n征师：征发的部队。一作“征骑”。屯：驻兵防守。广武：地名，今山西代县西。\n朔方：汉郡名，在今内蒙古自治区河套西北部及后套地区。\n严秋：肃杀的秋天。这句的意思是弓弦与箭杆都因深秋的干燥变得强劲有力。\n虏阵：指敌方的阵容。虏，古代对北方入侵民族的恶称。\n天子按剑怒：指天子闻警后大怒。\n使者句：意思是军情紧急，使者奔走于路，络绎不绝，遥相望见。\n雁行：排列整齐而有次序，像大雁的行列一样。缘，沿着。\n鱼贯：游鱼先后接续。飞梁：凌空飞架的桥梁。\n萧鼓：两种乐器，此指军乐。流汉思：流露出对家国的思念。\n旌（jīng）甲：旗帜、盔甲。\n砾（lì）：碎石。\n缩：蜷缩。蝟：刺猬。角弓：以牛角做的硬弓。\n投躯：舍身；献身。国殇（shāng）：为国牺牲的人。', poem_appreciation = '诗开头就表现了边亭告警的紧急情况：“羽檄起边亭，烽火入咸阳。征骑屯广武，分兵救朔方。”敌方入侵的信息接连传入京城，汉军征集马队，屯驻广武，分遣精兵，出救朔方。前两句“羽檄”、“烽火”用互文见义法，强化了军情的危急。后两句为一触即发的生死搏斗埋下了伏笔。\n\n　　诗进而表现了胡焰嚣张，天子震怒的严重局势：“严秋筋竿劲，虏阵精且强。天子按剑怒，使者遥相望。”胡方利用深秋弓坚矢劲，大举入犯，汉方天子震怒，使者促战，相望于道。四句有力地暗示一场激烈的战斗即将展开，很能唤起读者的兴趣。\n\n　　接着用两联工整对句极写汉军准备投入战斗的壮阔场面，颇有先声夺人气势。“雁行缘石径，鱼贯度飞粱。箫鼓流汉思，旌甲被胡霜。”石径迂折，飞粱直跨，大军行进，秩序井然。但闻箫鼓中传出汉军的豪情壮思，旌甲上沾满胡地的霜露雪花。前两句用雁行、鱼贯两个比喻刻画汉军跋涉辛苦，纪律严明的英雄风貌。后两句则突出将士们战胜恶劣环境的大无畏精神。缘、度、流、被四字，分别起了传神点睛作用。\n\n　　然后着重描写进入实战状态时气候剧变的特殊情况：“疾风冲塞起，沙砾自飘扬。马毛缩如猬，角弓不可张。”疾风冲塞而起，沙砾满天飘扬。战马瑟缩，不能奔驰，劲弓冻结，难以开张。这四句把边塞风光与战地生活紧紧衔联，很自然地为英勇顽强的壮士安排好一个典型环境，使他们在艰苦条件下表现的可贵战斗精神有效地得到显示。\n\n　　最后四句是全诗的精华：“时危见臣节，世乱识忠良。投躯报明主，身死为国殇。”自古以来的忠节之士，都是在严峻考验中察“见”和“识”别出来的。他们必须在紧急关头付出最大牺牲。诗人用《九歌·国殇》礼赞勇武刚强、死于国事的“鬼雄”的辞语，颂扬为国捐躯的壮士，寄托了他对英烈的无比崇敬之情。这两联流传万口，几乎成了封建时代衡量忠良行为准则的诗句，产生了鼓舞人心的力量。\n\n　　此诗在思想与艺术上能达到较完美的统一，是由于紧凑曲折的情节，不断变化的画面和鲜明突出的形象在诗里得到了有机的结合。其中紧凑的情节，更起了重要作用。它由边亭告警，征骑分兵，加强防卫，进而写到虏阵精强，天子按剑，使者促战。然后着重写了汉军壮伟场面和战地自然风光。最后以壮士捐躯，死为国殇的高潮作结。\n\n　　贯串于上述紧凑情节中的，是各种生活画面，如边亭、咸阳、广武、朔方、虏阵、胡霜，包括了胡汉双方的广阔空间。活跃其中的，有交驰的羽檄，连天的烽火，雁行的队列，鱼贯的军容，箫鼓的节奏，旌甲的辉光等。尤其是疾风起，沙砾场，马瑟缩，弓冻凝的边塞风光画面，“神气光舞”（陈祚明语），“分明说出边塞之状”（朱熹语），更为此诗增添了艺术光彩，是鲍照表现边塞生活的重要艺术标志。\n\n　　上述画面从多角度进行描绘，而位于其中心的，则是壮士的英雄群像。不只征骑、分兵、缘石径、度飞粱、吹箫伐鼓、执旌被的严峻时刻，他们的形象也十分耀眼。尤其是时危世乱之际表现的忠节，更突出地闪现了英烈们为国献身的思想亮光。\n\n　　鲍照没有边塞生活的直接经验，却写出了成功的边塞作品，很可能是因为他善于把自己积累的北方边塞生活的间接知识和前辈作家的创作经验艺术地结合起来，他能自出心裁，自显身手，为南朝诗坛开出一朵奇葩，说明他对庄子《逍遥游》“有待”、“无待”的境界，是很领会的。', poem_tags = '乐府,边塞,生活,励志' WHERE poem_title = '代出自蓟北门行' AND poem_author = '鲍照';
UPDATE edu_poem SET poem_translation = '时至暮春，独守空闺，莺啼声稀稀落落，应和着我的阵阵低泣。扯起珠帘，扑面央入满眼芳草。\n一阵东风从小院里吹过；千万条柳枝便如同千万缕离情，一条一缕都向西指；那迢迢的西陲啊，正是爱人守戍的地方。', poem_notes = '代：犹拟，说作者完全以一个闺妇身份来写这首诗。\n残莺：春暮时之莺。春暮则莺稀，故称残莺。\n萋萋：形容草生长得茂盛。暗用《楚辞·招隐士》春草、王孙意。意诣征人未归。 \n尽向西：唐时征战多在西陲。', poem_tags = '春天,闺怨' WHERE poem_title = '代春怨' AND poem_author = '刘方平';
UPDATE edu_poem SET poem_translation = '贾谊被贬在此地居住三年，可悲遭遇千万代令人伤情。\n我在秋草中寻觅人迹不在，寒林里空见夕阳缓缓斜倾。\n汉文帝重才恩德尚且淡薄，湘江水无意凭吊有谁知情？\n寂寞冷落深山里落叶纷纷，可怜你不知因何天涯飘零？', poem_notes = '贾谊：西汉文帝时政治家、文学家。后被贬为长沙王太傅，长沙有其故址。\n谪宦：贬官。栖迟：淹留。像鸟儿那样的敛翅歇息，飞不起来。\n楚客：流落在楚地的客居，指贾谊。长沙旧属楚地，故有此称。一作“楚国”。\n独：一作“渐”。\n汉文：指汉文帝。\n摇落处：一作“正摇落”。', poem_appreciation = '这是一篇堪称唐诗精品的七律。\n\n　　“三年谪宦此栖迟，万古惟留楚客悲。”“三年谪宦”，只落得“万古”留悲，上下句意钩连相生，呼应紧凑，给人以抑郁沉重的悲凉之感。“此”字，点出了“贾谊宅”。“栖迟”，像鸟儿那样的敛翅歇息，飞不起来，这种生活本就是惊惶不安的，用以暗喻贾谊的侘傺失意，是恰切的。“楚客”，流落在楚地的客居，标举贾谊的身份。一个“悲”字，直贯篇末，奠定了全诗凄怆忧愤的基调，不仅切合贾谊的一生，也暗寓了刘长卿自己迁谪的悲苦命运。\n\n　　“秋草独寻人去后，寒林空见日斜时。”颔联是围绕题中的“过”字展开描写的。“秋草”，“寒林”，“人去”，“日斜”，渲染出故宅一片萧条冷落的景色，而在这样的氛围中，诗人还要去“独寻”，一种景仰向慕、寂寞兴叹的心情，油然而生。寒林日斜，不仅是眼前所见，也是贾谊当时的实际处境，也正是李唐王朝危殆形势的写照。\n\n　　“汉文有道恩犹薄，湘水无情吊岂知？”颈联从贾谊的见疏，隐隐联系到自己。出句要注意一个“有道”，一个“犹”字。号称“有道”的汉文帝，对贾谊尚且这样薄恩，那么，当时昏聩无能的唐代宗，对刘长卿当然更谈不上什么恩遇了；刘长卿的一贬再贬，沉沦坎坷，也就是必然的了。这就是所谓“言外之意”。\n\n　　诗人将暗讽的笔触曲折地指向当今皇上，手法是相当高妙的。接着，笔锋一转，写出了这一联的对句“湘水无情吊岂知”。这也是颇得含蓄之妙的。湘水无情，流去了多少年光。楚国的屈原哪能知道上百年后，贾谊会来到湘水之滨吊念自己；西汉的贾谊更想不到近千年后的刘长卿又会迎着萧瑟的秋风来凭吊自己的遗址。后来者的心曲，恨不起古人于地下来倾听，当世更没有人能理解。诗人由衷地在寻求知音，那种抑郁无诉、徒呼负负的心境，刻画得十分动情，十分真切。\n\n　　“寂寂江山摇落处，怜君何事到天涯！”读此尾联的出句，好像刘长卿就站在读者面前。他在宅前徘徊，暮色更浓了，江山更趋寂静。一阵秋风掠过，黄叶纷纷飘落，在枯草上乱舞。这幅荒村日暮图，正是刘长卿活动的典型环境。它象征着当时国家的衰败局势，与第四句的“日斜时”映衬照应，加重了诗篇的时代气息和感情色彩。“君”，既指代贾谊，也指代刘长卿自己；“怜君”，不仅是怜人，更是怜己。“何事到天涯”，可见二人原本不应该放逐到天涯。这里的弦外音是：我和您都是无罪的呵，为什么要受到这样严厉的惩罚！这是对强加在他们身上的不合理现实的强烈控诉。读着这故为设问的结尾，仿佛看到了诗人抑制不住的泪水，听到了诗人一声声伤心哀惋的叹喟。\n\n　　诗人联系与贾谊遭贬的共同的遭遇，心理上更使眼中的景色充满凄凉寥落之情。满腹牢骚，对历来有才人多遭不幸感慨系之，更是将自己和贾谊融为一体。\n\n　　这首怀古诗表面上咏的是古人古事，实际上还是着眼于今人今事，字里行间处处有诗人的自我在，但这些又写得不那么露，而是很讲究含蓄蕴藉的，诗人善于把自己的身世际遇、悲愁感兴，巧妙地结合到诗歌的形象中去，于曲折处微露讽世之意，给人以警醒的感觉。', poem_tags = '唐诗三百首,怀古,迁谪,生活' WHERE poem_title = '长沙过贾谊宅' AND poem_author = '刘长卿';
UPDATE edu_poem SET poem_translation = '黑犬颈圈丁当响，猎人英俊又善良。\n黑犬脖上套双环，猎人英俊又勇敢。\n黑犬脖上环套环，猎人英俊又能干。', poem_notes = '卢：黑毛猎犬。令令：即“铃铃”，猎犬颈下套环发出的响声。\n其人：指猎人。仁：仁慈和善。\n重（chóng ）环：大环套小环，又称子母环。\n鬈（quán ）：勇壮。一说发好貌。\n重鋂（méi ）：一个大环套两个小环。\n偲（cāi ）：多才多智。一说须多而美。', poem_tags = '诗经,赞美' WHERE poem_title = '卢令' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '驾起轻车快驰骋，回去吊唁悼卫侯。挥鞭赶马路遥远，到达漕邑时未久。许国大夫跋涉来，阻我行程令我愁。\n竟然不肯赞同我，哪能返身回许地。比起你们心不善，我怀宗国思难弃。竟然没有赞同我，无法渡河归故里。比起你们心不善，我恋宗国情不已。\n登高来到那山冈，采摘贝母治忧郁。女子心柔善怀恋，各有道理有头绪。许国众人责难我，实在狂妄又稚愚。\n我在田野缓缓行，垄上麦子密密遍。欲赴大国去陈诉，谁能依靠谁来援？许国大夫君子们，不要对我生尤怨。你们考虑上百次，不如我亲自跑一遍。', poem_notes = '载（zài）：语助词。驰、驱：孔疏：“走马谓之驰，策马谓之驱。”\n唁（yàn）：向死者家属表示慰问，此处不仅是哀悼卫侯，还有凭吊宗国危亡之意。毛传：“吊失国曰唁。”卫侯：指作者之兄已死的卫戴公申。\n悠悠：远貌。\n漕：地名，毛传：“漕，卫东邑。”\n大夫：指许国赶来阻止许穆夫人去卫的许臣。\n嘉：认为好，赞许。\n视：表示比较。臧：好，善。\n思：忧思。远：摆脱。\n济：止。\n閟（bì）：同“闭”，闭塞不通。\n陟（zhì）：登。阿丘：有一边偏高的山丘。\n言：语助词。蝱（méng）：贝母草。采蝱治病，喻设法救国。\n怀：怀恋。\n行：指道理、准则，一说道路。\n许人：许国的人们。尤：责怪。\n众：“众人”或“终”。穉（zhì）：同“稚”，幼稚。\n芃（péng）芃：草茂盛貌。\n控：往告，赴告。\n因：亲也，依靠。极：至，指来援者的到达。\n之：往，指行动。', poem_appreciation = '据清魏源《诗古微》考证，《诗经》中许穆夫人的作品有三篇，除此篇外尚有《邶风·泉水》《卫风·竹竿》二诗也为其所作，其中尤以《鄘风·载驰》思想性最强，它在强烈的矛盾冲突中表现了深厚的爱国主义思想。全诗分为四章，不像《周南·桃夭》《鄘风·相鼠》等篇每章句数、字数甚至连意思也基本相似，而是每多变化，思想感情也复杂得多。之所以如此，是因为作者的叙事抒情是从现实生活出发，从现实所引起的内心矛盾出发。故诗歌的形式随着内容的发展而发展，形成不同的语言和不同的节奏。\n\n　　诗的第一章，交代本事。当诗人听到卫国灭亡、卫侯逝世的凶讯后。立即快马加鞭，奔赴漕邑，向兄长的家属表示慰问。可是目的地未到，她的丈夫许穆公便派遣大夫跋山涉水，兼程而至，劝她马上停止前进。处此境地，她内心极为忧伤。这一章先刻画了诗人策马奔驰、英姿飒爽的形象，继而在许国大夫的追踪中展开了剧烈的矛盾冲突。其情景就好似京剧《萧何月下追韩信》中的场景。\n\n　　现实的冲突引起内心的冲突，经过以上的铺叙，第二章便开始写诗人内心的矛盾。此时诗中出现两个主要人物：“尔”，许国大夫；“我”，许穆夫人。一边是许国大夫劝她回去，一边是许穆夫人坚持赴卫，可见矛盾之激烈。按诗意理解，应有两层意思：前四句为一层，是说：你既待我不友好，我就不能返回许国，比起你这般没良心来，我对宗国总是念念不忘的；后四句为第二层，是说：你既待我不友好，我就不能渡过黄河到卫国，比起你这般没良心来，我的感情是不会轻易改变的。诗人正是处于这种前不能赴卫、后不能返许的境地之中，左右为难，十分矛盾。然而她的爱与憎却表现得非常清楚：她爱的是娘家，是宗国；憎的是对她不予理解又不给支持的许国大夫及其幕后指挥者许穆公。\n\n　　第三章矛盾没有前面那么激烈，诗的节奏渐渐放慢，感情也渐渐缓和。夫人被阻不能适卫，心头忧思重重，路上一会儿登上高山以舒解愁闷，一会儿又采摘草药贝母以治疗抑郁而成的心病。所谓“女子善怀，亦各有行”，是说她身为女子，虽多愁善感，但亦有她的做人准则——这准则就是关心生她养她的宗国。而许国人对她毫不理解，给予阻挠与责怪，这只能说明他们的愚昧、幼稚和狂妄。这一段写得委婉深沉，曲折有致，仿佛让人窥见她有一颗美好而痛苦的心灵，简直催人泪下。\n\n　　第四章写夫人归途所思。此时夫人行迈迟迟，一路上考虑如何拯救祖国。“我行其野，芃芃其麦”，说明时值暮春，麦苗青青，长势正旺。所谓“控于大邦”，指向齐国报告狄人灭卫的情况，请求他们出兵，但诗人又想不出用什么办法才能达到目的。此处既写了景，又写了情，情景双绘中似乎让人看到诗人缓辔行进的形象。同第一章的策马奔驰相比，表现了不同的节奏和不同的情绪。而这个不同完全是从生活出发的，盖初来之时因始闻卫亡的消息，所以心急如焚，快马加鞭，不暇四顾；而被许大夫阻挠之后，报国之志难酬，心情沉重，故而行动迟缓，眼看田野中的麦浪好似诗人起伏不定的心潮。诗笔至此，真是令人赞叹。\n\n　　最后四句，有的本子另作一章，不无道理，然依旧本，多与前四句并为一节，这样似更为合理。这四句当是承前而言，谓夫人归途中一边想向齐国求救，求救不成，又对劝阻她的许大夫心怀愤懑。此处朱熹《诗集传》释云：“大夫，即跋涉之大夫；君子，谓许国之众人也。”“大夫君子，无以我为有过，虽尔所以处此百方，然不如使我得自尽其心之为愈也。”照此解释则与首章“大夫跋涉，我心则忧”，前后呼应。字面上虽是“无我有尤”，实质上应是她对许大夫不让她适卫赴齐产生怨尤，正话反说，语气委婉，体现了《诗经》“温柔敦厚”之旨。末二句，表现了夫人的自信心，意为：那些大夫君子纵有千条妙计，总不如我的救卫之策高明。“我所之”的“之”字，若作动词解，便是往卫国或齐国去一趟的意思；也有训为“思”的，就是自指夫人的想法。不管哪一种解释，都反映了许穆夫人是一个颇有主张的人，她的救国之志、爱国之心始终不渝。全诗至此戛然而止，但它却留下无穷的诗意让读者去咀嚼回味，真是语尽而意不尽，令人一唱而三叹。', poem_tags = '诗经,爱国' WHERE poem_title = '载驰' AND poem_author = '佚名';
UPDATE edu_poem SET poem_tags = '端午节,风俗' WHERE poem_title = '乙卯重五诗' AND poem_author = '陆游';
UPDATE edu_poem SET poem_tags = '爱情,思念' WHERE poem_title = '清平乐·风鬟雨鬓' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '注释 泰定三年丙寅岁除夜：公元1326年除夕。泰定三年即为丙寅年。 玉山：今江西玉山县，在长北岸。 的的：鲜明貌。 溅溅：流水声， 玉沙：指银白色的浪花。 瓦瓯篷：一种简陋的船篷，形如瓦瓯（小盆）。 阿戎家：指亲人所在。杜甫《杜位宅守岁》：“守岁阿戎家，椒盘已颂花。”阿戎，指堂弟，这是晋宋以来的习惯称呼。杜位即杜甫堂弟。曲中泛指近亲。', poem_tags = '春节,思念' WHERE poem_title = '喜春来·泰定三年丙寅岁除夜玉山舟中赋' AND poem_author = '张雨';
UPDATE edu_poem SET poem_appreciation = '此词是黄山谷与甘居山野、不求功名的“眉山隐客”史应之互相酬唱之作，全词通过一个“淫坊酒肆狂居士”的形象，展现了山谷从坎坷的仕途得来的人生体验，抒发了自己胸中的苦闷和激愤。词中所塑造的狂士形象，是作者自己及其朋友史念之的形象，同时也是那一时代中不谐于俗而怀不平傲世之心的文人的形象。\n\n　　上片是劝酒之辞，劝别人，也劝自己到酒中去求安慰，到醉中去求欢乐。首句“黄菊枝头生晓寒”是纪实，点明为重阳后一日所作。因史应之有和词，故自己再和一首，当亦是此数日间事。赏菊饮酒二事久已有不解之缘，借“黄菊”自然过渡到“酒杯”，引出下一句“人生莫放酒杯干”。意即酒中自有欢乐，自有天地，应让杯中常有酒，应该长入酒中天。“风前横笛斜吹雨，醉里簪花倒著冠”，着意写出酒后的浪漫举动和醉中狂态，表明酒中自有另一番境界。横起笛子对着风雨吹，头上插花倒戴帽，都是不入时的狂放行为，只有酒后醉中才能这样放肆。\n\n　　下片则是对世俗的侮慢与挑战。“身健在，且加餐。舞裙歌板尽清欢。”仍是一种反常心理，其含意于世事纷扰，是非颠倒，世风益衰，无可挽回，只愿身体长健，眼前快乐，别的一无所求。这是从反面立言。“黄花白发相牵挽，付与时人冷眼看”，则是正面立言。菊花傲霜而开，常用以比喻人老而弥坚，故有黄花晚节之称。这里说的白发人牵换着黄花，明显地表示自己要有御霜之志，决不同流合污，而且特意要表现给世俗之人看。这自然是对世俗的侮慢，不可能为时人所理解和容忍。\n\n　　此词以简洁的笔墨，勾勒出一个类似狂人的形象，抒写了山谷久抑胸中的愤懑，表现出对黑暗、污浊的社会现实无言的反抗。词中所塑造的主人公形象，以自乐自娱、放浪形骸、侮世慢俗的方式来发泄心中郁结的愤懑与不平，对现实中的政治迫害进行调侃和抗争，体现了词人挣脱世俗约束的高旷理想。主人公旷达的外表后，隐藏着无尽的辛酸与伤痛。', poem_tags = '宋词三百首,宋词精选,饮酒,抒怀,旷达' WHERE poem_title = '鹧鸪天·座中有眉山隐客史应之和前韵即席答之' AND poem_author = '黄庭坚';
UPDATE edu_poem SET poem_translation = '雨过后一只蝉在聒噪，松桂飘萧气候已交秋。\n青苔长满台阶，白鸟故意迟留。\n暮霭已生深树，斜阳渐下小楼。\n谁知这条寂静的竹西路，通向那歌吹繁华的扬州。', poem_notes = '禅智寺：也叫上方寺、竹西寺，在扬州使节衙门东三里。史载其位于蜀冈之尾，原是隋炀帝故宫，后建为寺，居高临下，风景绝佳，是扬州胜景之一。\n蝉噪：指秋蝉鸣叫。北朝梁王籍《入若耶溪》有：“蝉噪林逾静，鸟鸣山更幽。”\n飘萧：飘摇萧瑟。\n阶砌：台阶。\n白鸟：指通常为白色羽毛的鸟，如鹤、鹭一类的鸟。故：故意。迟留：徘徊不愿离去。\n暮霭：黄昏的云气。\n竹西路：指禅智寺前官河北岸的道路。竹西，在扬州甘泉之北。后人在此筑亭，名日竹西亭，或称歌吹亭。\n歌吹是扬州：典出鲍照《芜城赋》：“车挂轊，人驾肩。廛闬扑地，歌吹沸天。”芜城即扬，由此化出“歌吹是扬州”。歌吹，歌声和音乐声；吹，指吹奏乐器。', poem_tags = '寺庙,写景,孤独' WHERE poem_title = '题扬州禅智寺' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '登上燕台眺望不禁感到震惊，笳鼓喧闹之地原是汉将兵营。\n万里积雪笼罩着冷冽的寒光，边塞的曙光映照着旌旗飘动。\n战场烽火连天遮掩边塞明月，南渤海北云山拱卫着蓟门城。\n少年时虽不像班超投笔从戎，论功名我想学终军自愿请缨。', poem_notes = '蓟门：在今北京西南，唐时属范阳道所辖，是唐朝屯驻重兵之地。\n燕台：原为战国时燕昭王所筑的黄金台，这里代称燕地，用以泛指平卢、范阳这一带。客：诗人自称。\n笳：汉代流行于塞北和西域的一种类似于笛子的管乐器，此处代指号角。\n三边：古称幽、并、凉为三边。这里泛指当时东北、北方、西北边防地带。危旌：高扬的旗帜。\n烽火：古代用于军事通信的设施，遇敌情时点燃狼粪，以传警报。\n投笔吏：汉人班超家贫，常为官府抄书以谋生，曾投笔叹曰：“大丈夫当立功异域以取封侯，安能久事笔砚 间。”后终以公封定远侯。\n论功：指论功行封。请长缨：汉人终军曾自向汉武帝请求：“愿受长缨，必羁南越王而致之阙下。”后被南越相所杀，年仅二十余。\n一去：一作“一望”。\n危旌：高扬的旗帜。\n请长缨：汉终军曾自向汉武帝请求，“愿受长缨，心羁南越王而致之阙下。”后被南越相所杀，年仅二十余。缨：绳。', poem_appreciation = '这首诗写作者到边地见到壮丽景色，抒发立功报国的壮志。全诗一气呵成，体现了盛唐诗人的昂扬情调。\n\n　　燕台原为战国时燕昭王所筑的黄金台，这里代称燕地，用以泛指平卢、范阳这一带。“燕台一去”犹说“一到燕台”，四字倒装，固然是诗律中平仄声排列的要求，更重要的是，起笔即用一个壮大的地名，能增加全诗的气势。诗人初来闻名已久的边塞重镇，游目纵观，眼前是辽阔的天宇，险要的山川，不禁激情满怀。一个“惊”字，道出他这个远道而来的客子的特有感受。这是前半首主意所在，开出下文三句。\n\n　　客心因何而惊呢？首先是因为汉家大将营中，吹笳击鼓，喧声重叠。此句运用南朝梁人曹景宗的诗意：“去时儿女悲，归来笳鼓竞。借问行路人，何如霍去病？”表现军营中号令之严肃。但仅仅如此，还未足以体现这个“惊”字。三四两句更进一步，写这笳鼓之声，是在严冬初晓之时发出的。冬季本已甚寒，何况又下雪，何况又是多少天来的积雪，何况又不止一处两处的雪，而是连绵千万里的雪；这些雪下得如此之广，又积得如此之厚，不说它是怎样的冷了，就是雪上反映出的寒光，也足以令人两眼生花。“万里寒光生积雪”这一句就这样分作四层，来托出一个“惊”字。这是往远处望。至于向高处望，则见朦胧曙色中，一切都显得模模糊糊，唯独高悬的旗帜在半空中猎猎飘扬。这种肃穆的景象，暗写出汉将营中庄重的气派和严整的军容。边防地带如此的形势和气氛，自然令诗人心灵震撼了。\n\n　　以上四句已将“惊”字写足，五六两句便转。处在条件如此艰苦。责任如此重大的情况下，边防军队却是意气昂扬。笳鼓喧喧已显出军威赫然，而况烽火燃处，紧与胡地月光相连，雪光、月光、火光三者交织成一片，不仅没有塞上苦寒的悲凉景象，而且壮伟异常。这是向前方望。“沙场烽火连胡月”是进攻的态势。诗人又向周围望：“海畔云山拥蓟城”，又是那么稳如磐石。蓟门的南侧是渤海，北翼是燕山山脉，带山襟海，就像天生是来拱卫大唐的边疆重镇的。这是说防守的形势。这两句，一句写攻，一句说守；一句人事，一句地形。在这样有力有利气势的感染下，便从惊转入不惊，于是领出下面两句，写“望”后之感。诗人虽则早年并不如东汉时定远侯班超初为佣书吏（在官府中抄写公文），后来投笔从戎，定西域三十六国，可是见此三边壮气，却也雄心勃勃，要学西汉时济南书生终军，向皇帝请发长缨，缚番王来朝，立一下奇功了。末联连用了两个典故。第一个是“投笔从戎“：东汉班超原在官府抄公文，一日，感叹说，大丈夫应该“立功异域“，后来果然在处理边事上立了大功。第二个是“终军请缨“：终军向皇帝请求出使南越说服归附，为表现自己有足够的信心，他请皇帝赐给长带子，说是在捆南越王时要用它。祖咏用了这两个典故，意思很明白，更有豪气顿生之感。末二句一反起句的“客心惊”，水到渠成，完满地结束全诗。\n\n　　这首诗从军事上落笔，着力勾画山川形胜，意象雄伟阔大。全诗紧扣一个“望”字，写望中所见，抒望中所感，格调高昂，感奋人心。诗中多用实字，全然没有堆砌凑泊之感；意转而辞句中却不露转折之痕，于笔仗端凝之中，有气脉空灵之妙。此即骈文家所谓“潜气内转”，亦即古文家所谓“突接”，正是盛唐诗人的绝技。', poem_tags = '唐诗三百首,冬天,边塞' WHERE poem_title = '望蓟门' AND poem_author = '祖咏';
UPDATE edu_poem SET poem_translation = '雨后新晴的原野格外开阔空旷，极目远望不见半点雾气尘埃。\n外城的门楼紧靠着摆渡的码头，村庄边的绿树连接着溪流的入河口。\n银白色的河水闪动着粼粼波光使得田野外面特别明亮，青翠的山峰突兀出现在山脊背后。\n正是农忙时节没有悠闲的人，农民们一家一家全都在田亩间忙碌着呢。', poem_notes = '新晴：初晴。野望：放眼向田野眺望。\n极目：穷尽目力向远处看。氛垢：雾气和尘埃；氛，雾气，云气；垢，污秽，肮脏。\n郭门：外城之门。郭：外城。\n白水明田外：田埂外流水在阳光下闪闪发光。\n农月：农忙季节。\n倾家：全家出动。事南亩：在田野干活。事：动词，从事。南亩：《诗经》有“今适南亩，或耘或耔”句，指到南边的田地里耕耘播种，后来南亩便成为农田的代称。', poem_appreciation = '诗中描写初夏的乡村，雨过天晴，诗人眺望原野所见到的景色和农耕活动，抒写了诗人爱自然、爱田园、爱生活的思想感情。诗的语言秀丽，情调明朗健康，意境清新，明净、开阔，宛若一幅优美迷人的水彩风景色。表现了王维高度的写景艺术才能。一般地说，刻画自然景色并不难，难的是用极精炼的文字，描绘出特定的时间、空间和特定的季节、气候中的景色。这必须有敏锐的观察力和想象力，并善于抓住景物的主要特征，突出自己最鲜明的印象和感受。这首诗就是王维的一次成功的艺术实践。全诗写景，紧紧扣住初夏农村雨后新睛的特征。\n\n　　首联的“原野旷”和“无氛垢”六个字，便展现出经过雨水冲洗，空气特别清新明净，没有丝毫尘埃，原野显得格外空旷开阔。由于抓准了环境特征，不假雕绘地真切地再现出来，一下子就把读者引进雨后新晴的原野上去，同诗人一起极目远眺，一道呼吸新鲜的、潮润的空气。\n\n　　颔联写诗人纵目四望乡村周围的远近景色：远处，遥见外城的门楼临靠着河边的渡头；近处，可以看到村边的绿树紧连着溪流的入河口。由总写原野的新晴、开阔，到写乡村周围景色，过渡自然。正因为空气洁净，增大了“望”中的透明度和深远度，才有可能如此清晰地看到郭门、渡头、村树、溪口。所以这一联所写景色，仍是雨后新晴之景。颈联最为精彩：田野外面，溪水与河水闪烁着粼粼银光；近山背后，一座座青翠的峰峦突兀而出。上句的“白”字和“明”字，非常准确地表现出雨后水涨，晴日辉映，河流溪涧比平时显得明亮夺目；下旬的“碧”字和“出”字，也十分逼真地描绘了雨洗远山，格外碧绿，雨后空气清新，山背峰峦得以叠现。这两个意象画面。都紧扣着雨后新晴的特点，因而生动、具体、逼真，在总体的静态中富于动感，清幽明丽，生机勃勃，决非泛泛写景。\n\n　　尾联“农月无闲人，倾家事南亩“虽然只是虚点一笔，却给原野平添了无限生意，使人感受到农忙劳动的热烈欢快气氛，呼吸到农村浓郁的生活气息。这一笔既丰富了诗的生活内容，又因动静映衬而使这幅诗中画整个活起来了。\n\n　　苏轼评王维“诗中有画”。“诗中有画”并非王维所独有。凡是比较生动逼真地描绘出自然景色，使人产生视觉想象的诗，都会有画意。然而，王维诗中的画意最浓，王维的诗中的画意不仅有形似，而且富有神韵和气象，不仅有形态、色彩和构图，而且有光线和颜色的和谐映衬，明与暗的对比，远近、高低、大小、虚实的巧妙布置而形成的层次感、纵深感，甚至还能表现出亮度、湿度。在《新晴野望》诗中，清新开阔的原野，明净无尘的天空，仿佛是画幅中的大背景。在这大背景下，乡村前面，较远处有郭门、渡头，较近处有村树、溪口；村庄后面，近处是田野和田外白水，远处是山后的碧峰。近景、中景和远景，组成了画面的纵深感和层次感，而山后的碧峰又构成立体的景深。明亮的白水，碧翠的峰峦，明与暗，光与色配置得多么和谐入妙！在“无氛垢”、“临渡头”、“连溪口”中有亮度，在田外白水、山后碧峰中有湿度。王维是大画家，善于以画家的眼睛观察和描绘景物，又精通画理，擅长将绘画技法运用于诗中，所以王维的诗最富于绘画的效果，既有画意，又有画理。\n\n　　当然，王维主要是诗人。王维的“诗中有画”，最主要的还是由于王维能“最大限度地发挥语言的启示性，在读者头脑中唤起了对于光、色、态的丰富联想和想象，组成一幅幅生动的图画”（袁行霈《王维诗歌的禅意与画意》）。王维很懂得画长于描绘静态，诗长于表现动态的艺术规律。在此诗中，王维描写静景，便有意选用“明”、“出”等字眼以动写静，‘给静物赋予动感，最后又给这幅静态的山水画面加上了动态的人物。', poem_tags = '田园,写景' WHERE poem_title = '新晴野望' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '我年幼时秉赋清廉的德行，献身于道义而不稍微减轻。\n具有如此盛大的美德，被世俗牵累横加秽名。\n君王不考察这盛大的美德，长期受难而愁苦不尽。\n上帝告诉巫阳说：\n“有人在下界，我想要帮助他。\n但他的魂魄已经离散，你占卦将灵魂还给他。”\n巫阳回答说：\n“占卦要靠掌梦之官，上帝的命令其实难以遵从。”\n“你一定占卦让魂魄还给他，恐怕迟了他已谢世，再把魂招来也没有用。”\n巫阳于是降至人间招魂说：\n“魂啊回来吧！\n何必离开你的躯体，往四方乱走乱跑？\n舍弃你安乐的住处，遇上凶险实在很糟。\n“魂啊回来吧！\n东方不可以寄居停顿。\n那里长人身高千丈，只等着搜你的魂。\n十个太阳轮番照射，金属石头都熔化变形。\n他们都已经习惯，而你的魂一去必定消解无存。\n回来吧，那里不能够寄居停顿。\n“魂啊回来吧！\n南方不可以栖止。\n野人额上刻花纹长着黑牙齿，掠得人肉作为祭祀，还把他们的骨头磨成浆滓。\n那里毒蛇如草一样丛集，大狐狸千里内到处都是。\n雄虺蛇长着九个脑袋，来来往往飘忽迅捷，为求补心把人类吞食。\n回来吧，那里不能够长久留滞。\n“魂啊归来吧！\n西方的大灾害，是那流沙千里平铺。\n被流沙卷进雷渊，糜烂溃散哪能止住。\n侥幸摆脱出来，四外又是空旷死寂之域。\n红蚂蚁大得像巨象，黑蜂儿大得像葫芦。\n那里五谷不能好好生长，只有丛丛茅草可充食物。\n沙土能把人烤烂，想要喝水却点滴皆无。\n榜徨怅惘没有依靠，广漠荒凉没有终极之处。\n回来吧。\n恐怕自身遭受荼毒!\n“魂啊回来吧！\n北方不可以停留。\n那里层层冰封高如山峰，大雪飘飞千里密密稠稠。\n回来吧，不能够耽搁得太久！\n“魂啊归来吧!\n你不要径自上天。\n九重天的关门都守着虎豹，咬伤下界的人尝鲜。\n另有个一身九头的妖怪，能连根拔起大树九千。\n还有眼睛直长的豺狼，来来往往群奔争先。\n把人甩来甩去作游戏，最后扔他到不见底的深渊。\n再向上帝报告完毕，然后你才会断气闭眼。\n回来吧，上天去恐怕也身遭危险!\n“魂啊回来吧！\n你不要下到幽冥王国。\n那里有扭成九曲的土伯，它头上长着尖角锐如刀凿。\n脊背肥厚拇指沾血，追起人来飞奔如梭。\n还有三只眼睛的虎头怪，身体像牛一样壮硕。\n这些怪物都喜欢吃人，回来吧!\n恐怕自己要遭受灾祸。\n“魂啊回来吧！\n快进入楚国郢都的修门。\n招魂的巫师引导君王，背向前方倒退着一路先行。\n秦国的篝笼齐国的丝带，还有作盖头的郑国丝绵织品。\n招魂的器具已经齐备，快发出长长的呼叫声。\n魂啊回来吧!\n返回故居不再离乡背井。\n“天地上下四面八方，多有残害人的奸佞。\n仿照你原先布置的居室，舒适恬静十分安宁。\n高高的大堂深深的屋宇，栏杆围护着轩廊几层。\n层层亭台重重楼榭，面临着崇山峻岭。\n大门镂花涂上红色，刻着方格图案相连紧。\n冬天有温暖的深宫，夏天有凉爽的内厅。\n山谷中路径曲折，溪流发出动听的声音。\n阳光中微风摇动蕙草，丛丛香兰播散芳馨。\n穿过大堂进入内屋，上有红砖承尘下有竹席铺陈。\n光滑的石室装饰翠羽，墙头挂着玉钩屈曲晶莹。\n翡翠珠宝镶嵌被褥，灿烂生辉艳丽动人。\n细软的丝绸悬垂壁间，罗纱帐子张设在中庭。\n四种不同的丝带色彩缤纷，系结着块块美玉多么纯净。\n“宫室中那些陈设景观，丰富的珍宝奇形怪状。\n香脂制烛光焰通明，把美人花容月貌都照亮。\n二八十六位侍女来陪宿，倦了便互相替代轮流上。\n列国诸侯的淑美女子，人数众多真不同凡响。\n发式秀美有各种各样，充满后宫熙熙攘攘。\n容颜姿态姣好互相比并，真是风华绝代盖世无双。\n娇柔的面貌健康的身体，流露出缠绵情意令人心荡。\n俏丽的容颜美妙的体态，在洞房中不断地来来往往。\n纤秀的弯眉下明眸转动，顾盼之间双目秋波流光。\n肌肤细腻如脂如玉，留下动人一瞥意味深长。\n离宫别馆有修长的大幕，消闲解闷她们侍奉君王。\n“张挂起翡翠色的帷帐，装饰那高高的殿堂。\n红漆髹墙壁丹砂涂护版，还有黑玉一般的大屋粱。\n抬头看那雕刻的方椽，画的是龙与蛇的形象。\n坐在堂上倚着栏干，面对着弯弯曲曲的池塘。\n荷花才开始绽放花朵，中间夹杂着荷叶肥壮。\n紫茎的荇菜铺满水面，风起水纹生于绿波之上。\n身着文彩奇异的豹皮服饰，侍卫们守在山丘坡岗。\n有篷有窗的安车已到。\n步骑随从分列两旁。\n丛丛兰草种在门边，株株玉树权当做篱笆护墙。\n魂啊回来吧！\n为什么还要滞留远方？\n“家族聚会人都到齐，食品丰富多种多样。\n有大米小米也有新麦，还掺杂香美的黄粱。\n大苦与咸的酸的有滋有味，辣的甜的也都用上。\n肥牛的蹄筋是佳肴，炖得酥酥烂扑鼻香。\n调和好酸味和苦味，端上来有名的吴国羹汤。\n清炖甲鱼火烤羊羔，再蘸上新鲜的甘蔗糖浆。\n醋溜天鹅肉煲煮野鸭块，另有滚油煎炸的大雁小鸽。\n卤鸡配上大龟熬的肉羹，味道浓烈而又脾胃不伤。\n甜面饼和蜜米糕作点心，还加上很多麦芽糖。\n晶莹如玉的美酒掺和蜂蜜，斟满酒杯供人品尝。\n酒糟中榨出清酒再冰冻，饮来醇香可口遍体清凉。\n豪华的宴席已经摆好，有酒都是玉液琼浆。\n归来吧返回故居，礼敬有加保证无妨。\n“丰盛的酒席还未撤去，舞女和乐队就罗列登场。\n安放好编钟设置好大鼓，把新作的乐歌演奏演唱。\n唱罢《涉江》再唱《采菱》，更有《阳阿》一曲歌声扬。\n美人已经喝得微醉，红润的面庞更添红光。\n目光撩人脉脉注视，眼中秋波流转水汪汪。\n披着刺绣的轻柔罗衣，色彩华丽却非异服奇装。\n长长的黑发高高的云鬓，五光十色艳丽非常。\n二八分列的舞女一样妆饰，跳着郑国的舞蹈上场。\n摆动衣襟像竹枝摇曳交叉，弯下身子拍手按掌。\n吹竽鼓瑟狂热地合奏，猛烈敲击鼓声咚咚响。\n宫殿院庭都震动受惊，唱出的《激楚》歌声高昂。\n献上吴国蔡国的俗曲，奏着大吕调配合声腔。\n男女纷杂交错着坐下，位子散乱不分方向。\n解开绶带帽缨放一边，色彩斑斓缤纷鲜亮。\n郑国卫国的妖娆女子，纷至沓来排列堂上。\n唱到《激楚》之歌的结尾，特别优美出色一时无两。\n“赌具有饰玉筹码象牙棋，用来玩六簙棋游戏。\n分成两方对弈各自进子，着着强劲紧紧相逼。\n掷彩成枭就取鱼得筹，大呼五白求胜心急。\n赢得了晋国制的犀带钩，一天光阴耗尽不在意。\n铿锵打钟钟架齐摇晃，抚弦再把梓瑟弹奏起。\n饮酒娱乐不肯停歇，沉湎其中日夜相继。\n带兰香的明烛多灿烂，华美的灯盏错落高低。\n精心构思撰写文章，文采绚丽借得幽兰香气。\n人们高高兴兴快乐已极，一起赋诗表达共同的心意。\n酣饮香醇美酒尽情欢笑，也让先祖故旧心旷神怡。\n魂啊回来吧！\n快快返回故里。”\n尾声：\n新年开始春天到来，我匆匆忙忙向南行。\n绿苹长齐了片片新叶，白芷萌生又吐芳馨。\n道路贯通穿越庐江，左岸上是连绵的丛林。\n沿着泽沼水田往前走，远远眺望旷野无垠。\n四匹青骊驾起一乘车，千乘猎车并驾前行。\n点起火把蔓延燃烧，夜空黑里透红火光腾。\n步行的赶到乘车的停留，狩猎的向导又当先驰骋。\n勒马纵马进退自如，又引车向右掉转车身。\n与君王一起驰向云梦泽，赛一赛谁先谁后显本领。\n君王亲手发箭射猎物，却怕射中青兕有祸生。\n黑夜之后红日放光明，时光迅速流逝不肯停。\n水边高地兰草长满路，这条道已遮没不可寻。\n清澈的江水潺潺流，岸上有成片的枫树林。\n纵目望尽千里之地，春色多么引人伤心。\n魂啊回来吧，江南堪哀难以忘情！', poem_notes = '1.朕：我，屈原自指。\n2.沫（mei4妹）：微暗。引伸为消减。\n3.主：守、持有。\n4.芜秽：萎枯污烂。\n5.上：指楚王。\n6.离：遭遇。殃:祸患。\n7.帝：上帝。巫阳:古代神话中的巫师。\n8.人：指楚王。\n9.辅：帮助。特指上天辅助人间帝王。\n10.筮予之：通过卜筮知魂魄之所在，招还给予其人。\n11.掌梦：掌梦之官，实司其事。巫阳因其难招，故作托词。\n12.若：你，指巫阳。\n13.谢：凋落。按：“若必筮予之”三句作为上帝言语，首见项安世《项氏家说》，闻一多、陈子展从之。\n14.焉乃：于是。按：“巫阳焉”属此句。“焉乃”连文用王引之《经传释词》说。\n15.些：语尾助词，读音“唆”（suo）疑同今民歌中“啰“音。\n16.离：同“罹”，遭。\n17.雕题黑齿：额头上刻花纹，牙齿染成黑色。指南方未开化的野人。题，额头。\n18.醢（hai3海）：肉酱。\n19.蓁（zhen1真）蓁：树木丛生貌，此指积聚在一起。\n20.封狐：大狐。\n21.虺（hui3毁）：毒蛇。\n22.儵（shu1舒）忽：同“倏忽”，忽然。\n23.益：补。\n24.淫：久留。\n25.雷渊：神话中的深渊。\n26.爢（mi3米）：同“靡”，粉碎。\n27.壶：通“瓠”，葫芦。\n28.藂（cong2丛）：聚集。菅（jian1坚）：一种野草，细叶绿花褐果。\n29.贼：残害。\n30.增（ceng2层）：通“层”。\n31.九关：指九重天门。\n32.从（zong4纵）：同“综”，直。\n33.侁（shen1申）侁：众多貌。\n34.致命：上报。\n35.幽都：神话中地下鬼神统治的地方。\n36.土伯：地下王国的神灵。约：弯曲。一说，尾也。一说，肚下肉块。\n37.觺（yi2疑）觺：尖利貌。\n38.敦脄（mei2梅）：很的背肉。疑为神怪名。\n39.駓（pi1披）駓：跑得很快的样子。\n40.参：同“三”。\n41.甘人：以食人为甘美。\n42.修门：郢都城南三门之一。\n43.工祝：工巧的巫人。\n44.背行：倒退着走。\n45.秦篝：秦国出产的竹笼，用以盛被招者的衣物。齐缕：齐国出产的丝线，用以装饰“篝”。\n46.郑绵络：郑国出产的丝棉织品，用作“篝”上遮盖。\n47.招具：招魂用品，擅上文“秦篝”、“齐缕”、“郑绵络”等。\n48.永：长。招魂者要长声呼唤被招者。\n49.反：同“返”。\n50.像设：假想陈设。\n51.槛：栏杆。轩:走廊。\n52.网户：刻镂网状空格的门户。朱缀：交缀处涂上红色。\n53.方连：方格图案，即指“网户”。\n54.宎（yao4要）：深密。\n55.径：直。复：曲，指川谷水流曲折。\n56.崇：通“丛”。\n57.奥：内室。\n58.尘筵：铺在地上的竹席。\n59.砥室：形容地面、墙璧都磨平光亮像磨刀石一样。翠翘：翠鸟尾上的毛羽。\n60.曲琼：玉钩。\n61.齐光：色彩辉映。\n62.蒻（ruo4弱）阿：细软的缯帛。\n63.帱（chou2筹）：璧帐。\n64.纂组绮缟：指四种颜色不同的丝带。纂，赤色丝带；组，杂色丝带；绮：带花纹丝织品；缟：白色丝织品。\n65.琦璜：美玉。\n66.兰膏：泛言有香气的油脂。\n67.二八：以八人为行。二八十六人。\n68.射（yi4义）：厌。递：更替。\n69.九侯：泛指列国诸侯。\n70.迅：通“洵”，真正。\n71.盛鬋（jian3剪）：浓密的鬓发。鬋，下垂的鬓发。\n72.比：并。\n73.顺：通“洵”，诚然。弥代：盖世。\n74.弱颜：容貌柔嫩。固植：身体健康。\n75.謇：发语词。\n76.姱（kua1夸）：美好。修：美。\n77.絙（geng4）：绵延。\n78.曼：长。睩（lu4录）：眼珠转动。\n79.靡：细致。腻：光滑。理：肌肤。\n80.矊（mian3免）：目光深长。\n81.桷（jue2决）：方的椽子。\n82.芰（ji4技）荷：荷叶。\n83.屏风：荇莱，又名水葵。一种水生植物。\n84.文：同：“纹”，指波纹。\n85.文异：文彩奇异。豹饰：以豹皮为饰，指侍卫武士的装束。\n86.陂陁（po1 tuo2坡陀）：高低不平的山坡。\n87.轩：有篷的轻车。辌（liang2凉）：可以卧息的安车。低：通“抵”，到达。\n88.薄：草木丛生。\n89.宗：聚。\n90.多方：多种多样。\n91.粢（zi1资）：小米。穱（zhuo1桌）：早熟麦。\n92.挐（ru2如）：掺杂。黄梁：黄小米。\n93.辛：辣。行：用。\n94.腱（jian4健）：蹄筋。\n95.臑（er2而）：炖烂。若：与“而”意同。\n96.吴羹：吴地浓汤。\n97.胹(er2而):煮。炮:烤。\n98.柘（zhe4这）浆：甘蔗汁。\n99.鹄酸：据闻一多校。当作“酸鹄”。鹄，天鹅。臇（juan4倦）：少汁的羹。\n100.鸿鸧（cang1仓）鸿，大雁；鸧，即鸧鸹，一种似鹤的水鸟。\n101.露：借为“卤”。一说借为“烙”。臛（huo4霍）：肉羹。蠵（xi1西）：大龟。\n102.厉：浓烈。爽：败、伤。\n103.粔籹（ju4 nv3巨女）：用蜜和面粉制成的环状饼。饵：糕。\n104.餦餭（zhang1 huang2张皇）：即麦芽糖，也叫饴糖。\n105.勺：通“酌”。\n106.羽觞：古代一种酒嚣。\n107.酎（zhou4胄）：醇酒。\n108.通：通“彻”，撤去。\n109.涉江、采菱：楚国歌曲名。\n110.扬荷：多作《阳阿》，楚国歌曲名。\n111.酡（tuo2驼）：喝酒脸红。\n112.嬉光：形容撩人的目光。眇：通“妙”。\n113.曾：通“层”。\n114.被（pi1技）：披。文：文绣。纤：细软。\n115.陆离：形容色彩斑斓。\n116.二八：指两队女乐。齐容：装束一样。\n117.郑舞：郑国的舞蹈，比较放纵。\n118.衽：衣襟。交竿：衣襟相交如竿。\n119.抚：通“拊”，拍击。案：同“按”。下：似指弯腰下屈的舞蹈动作。\n120.搷（tian2填）：猛击。\n121.激楚：楚国的歌舞曲名。或谓指激烈的楚歌之声。\n122.吴歈（yu2俞）：吴地之歌。蔡讴：蔡地之歌。\n123.大吕：乐调名。\n124.组：系佩饰的丝带。缨:帽带。\n125.班：同“斑”。\n126.妖玩：指妖绕的女子。\n127.秀先：优秀出众。\n128.菎（kun1昆）蔽：饰玉的筹玛。赌博用具。象棋：象牙棋子。六簙用具。\n129.六簙（bo2伯）：一种棋戏。可用以赌博。\n130.分曹：相对的两方。\n131.枭：博戏术语。成枭棋则可取得棋局上的鱼，得二筹。牟：取。\n132.五白：五颗骰子组成的特彩。得此可胜。\n133.犀比：犀角制的带钩，用作赌胜负的彩注。一说用犀角制成的赌具。\n134.白日：指一天时光。\n135.铿：象声词。簴（ju4巨）：钟架。\n136.揳（ia2夹）：抚。梓瑟:梓木所制之瑟。\n137.错：错落安置。\n138.结撰：构思。至思：尽心思考。\n139.极：极至，此当指极度快乐。\n140.先故：先祖与故旧。\n141.乱：乱辞，尾声。\n142.献：进。\n143.汩（yu4玉）：形容匆匆而行。\n144.菉：通“绿”。苹：一种水草。\n145.白芷：一种香草。\n146.贯：通。庐江：洪兴祖《楚辞补注》云：“庐江出陵阳东南，北入江。”谭其骧以为当指今襄阳、宜城界之潼水。春秋时，地为庐戎之国，因有此称。\n147.长薄：杂草丛生的林子。\n148.倚：沿。畦:水田。瀛：大水。\n149.博：旷野之地。\n150.青骊（li2离）：青黑色的马。驷:驾一乘车的四匹马。\n151.悬火：焚林驱兽的火把。\n152.玄颜：黑里透红。指天色。烝:上升。\n153.步：步行的随从。骤处：乘车的随从停下。骤，驰；处，止。\n154.诱：导。打猎时的向导。\n155.抑：勒马不前。骛（wu4务）：奔驰。若:顺，指进退自如。\n156.梦：指云梦泽。这一带是楚国的大猎场,地跨大江南北。\n157.课：比试。\n158.惮青兕：怕射中青兕。兕，犀牛一类的野兽。楚人传说猎得青兕者，三月必死。\n159.朱明：指太阳。\n160.淹：留。\n161.皋：水边高地。\n162.渐（jian1坚）：遮没。\n163.湛湛：水深的样子。', poem_appreciation = '在《楚辞》中，《招魂》是一篇独具特色的作品。它是模仿民间招魂的习俗写成的。其中却又包含了作者的思想感情。\n\n　　关于《招魂》的作者，历来存在着争论。东汉王逸《楚辞章句》称《招魂》作者是宋玉，因哀怜屈原“魂魄放佚”，因作以招其生魂“《招魂》者宋玉之作也。招者，召也。以手曰招，以言曰召。宋玉哀怜屈原，忠而见弃，愁懑山泽，魂魄放佚，厥命将落，故作《招魂》，欲以其复精神，延其年寿，外陈四方之恶，以讽谏怀王，冀其觉悟而还之也”。但西汉中，司马迁作《史记》，在《屈原贾生列传》中，将《招魂》与《离骚》、《天问》、《哀郢》并列，并说读了这些作品，而“悲其(指屈原)志”，明显将《招魂》定为屈原作品。后世读《楚辞》，多用王逸注，故注本、诗词中每从其说。明代黄文焕始反对王逸之说。清林云铭亦辩之并提出两大疑点。林氏之说出后，蒋骥亦赞其说，陈本礼亦然。近代梁启超，游国恩亦皆认为是屈原所作。近世以来，研究者重视司马迁的提示，多主张《招魂》为屈原所作。但又分别有招楚怀王魂和屈原自招两种说法。同样主张屈原招怀王魂的，又有招生魂或死魂的两说。说法如此分歧，所举证据也很纷繁。简而言之，我赞成屈原招楚怀王死魂一说。理由如下：第一，篇中所写奢侈享受，非楚王莫属。尤其像“九侯淑女，多迅众些”，娶一国之女，其他诸侯送女作媵妾从嫁，这必是像楚王这样的身份，才能拥有。第二，文献所载，上天所辅必是帝、王，而非臣民。“有人在下，我欲辅之”必是指楚王(陈子展说)。第三，乱曰之后写打猎，既提到“汩吾南征”，又提到“与王趋梦”、“君王亲发”，明是作者回忆与楚王狩猎情形。最后并深情呼唤“魂兮归来，哀江南”，这只可能是屈原来招楚怀王之魂。\n\n　　《招魂》的形式主要来自民间。古人迷信，以为人有会离开躯体的灵魂，人生病或死亡，灵魂离开了，就要举行招魂仪式，呼唤灵魂归来。在许多民族残留的原始歌谣中，都有招魂歌谣。内容一般都是告诫灵魂不要到上下四方去，而应赶快回到家里来。为此目的，自然要讲讲上下四方的可怖，家中的安乐。后来规范为礼仪。如《礼记·礼运》所载“及其死也，升屋而号，告曰‘皋(嗥)某复’”，其仪式是由小臣举死者衣，登上屋顶，向上下四方呼号，招唤灵魂。作为礼仪，已非原始信仰，而是“尽爱之道也，有祷祠之心焉”。古老的迷信演变为一种风俗。杜甫《彭衙行》云“暖汤濯我足，剪纸招我魂”。远方来客，历经艰险，剪纸为其压惊、招魂。这倒是颇具人情味的风俗。民间一直流传有叫魂的迷信，曹禺《原野》中，曾借用来营造黑松林中的凄厉气氛，这也是古代招魂仪式的遗存。屈原写作《招魂》，就是模仿民间的创作，“外陈四方之恶，内崇楚国之美”(王逸《楚辞章句》)，呼唤楚怀王的灵魂回到楚国来。\n\n　　《招魂》当作于公元前296年，即顷襄王三年。公元前299年楚怀王受秦欺骗，入武关而被拘于秦，逃跑不成，怨愤而死。顷襄王三年，秦欲与楚修好，归怀王丧，“楚人皆怜之，如悲亲戚”，楚人同情怀王这个昏君，除敌忾之心外，还因怀王囚秦时，不肯割地屈服，总算有些骨气。对比只想苟安的顷襄王，自易引起人们的怀念。屈原曾受怀王信用，后来被谗见疏，但总希望怀王有所觉悟。怀王一死，楚国又面临亲秦、拒秦的斗争。屈原写作《招魂》，即认同楚人“如悲亲戚”之情，其中自然就包含了对秦的敌忾之心。\n\n　　《招魂》的结构是：一、序引，二、招魂辞，三、乱辞，总共三个部分。招魂辞中又分为“外陈四方之恶”与“内崇楚国之美”两大部分。一般招魂辞是没有序引和乱辞的。而且招魂辞每句结束都有“些”字，据旧注读苏贺切，其音与今湘南民歌尾音“啰”相近。而序引、乱辞语气词都用“兮”字，与《离骚》、《九章》等篇相同。由此可见，托为巫阳的招魂辞，主要遵从招魂的习俗要求，而序引和乱辞，则更显示出屈原的主体色彩。以下即依《招魂》的结构，略作鉴赏性介绍。\n\n　　序引一开头，便有作者出现，自“朕幼清以廉洁兮”至“长离殃而愁苦”，当是屈原自叙。屈原从来是以清廉、服义自许的。只是因楚王受到蒙蔽，不能“考此盛德”，而使他遭受不幸而忧愁痛苦。在这几句之后，忽然说到“帝告巫阳日：‘有人在下……’”，这就使人容易错会为上帝令巫阳为之招魂的，就是这位“长离殃而愁苦”之人，也就是屈原自己。于是主张“招怀王魂说”者，一般也将前四句解为称说怀王之词。然而既有“朕”字自称(如《离骚》)，形容又不相当。这确是一个难题。闻一多曾怀疑，开头四句，本非《招魂》所有，是错简于此。我想，如果说其下有脱简，也未始不可能。假设加上“上往而不返兮，朕冤结将谁诉”之类的句子，就自然过渡到招魂的事了。“帝告巫阳曰”以下几句是对话形式，表示出招魂的迫切性。实已暗示怀王已死，灵魂招来也不能复用。这几句有多种断句法，但大意都是：帝命巫阳下招——巫阳推辞——巫阳受命下招。这三层意思是大家公认的。\n\n　　作为《招魂》主干的是巫阳的招辞。招辞的第一部分写东、南、西、北、天上、地下的可畏可怖。这里取用了许多神话材料，写得诡异莫测。神话的瑰奇本是具有现实基础的，联系这种基础，可知想像的合理性；神话又是经过幻想加工改造的，赋予了令人眩目的奇幻色彩，更能激发起人们的审美兴味。《招魂》正是如此，如写到东方，东方是太阳升起的地方，而古代神话有十日并出烤焦大地的故事，作者用来形容东方的危险，便十分巧妙。又如写到西方，沙漠无边，不生五谷，无水可饮，又有赤蚁、玄蜂等毒虫，使人无法生存。这种种描写相当准确，使人惊叹作者具有相当丰富的地理知识，夸张的描写并未脱离现实基础。又如写到天上、地下，都有残忍无比的怪物据守着。保存了原始神话中的神秘性和原始性的特点。\n\n　　招魂辞的第二部分，是写郢都修门之内的豪华生活。作为前一部分的强烈对照，这一部分基本写实。从2002年对许多楚墓的发掘，完全可以证实其写实性。这一部分展示了故居的宫室、美女、饮食、歌舞、游戏之盛，描写了那种无日无夜的享乐生活。作者的描写是具体生动的。如写宫室园圃，既总写了建筑的外观、布局，池苑风物，又详写室内的装饰、布置，以及处于其间的人的活动——主要是美女的活动。又如写饮食，多种多样的主食、菜肴、饮料一一列举，且加形容：“臑若芳”、“酎清凉”、“厉而不爽”，让人感到的确是美味佳肴。文章中时时点染以人的活动、感受，更为传神。如写饮食、歌舞之余，“士女杂坐，乱而不分些。放陈组缨，班其相纷些”；写赌博的场面“分曹并进，遒相迫些。成枭而牟，呼五白些”。将那种不顾礼仪、忘乎所以的情形，那种捋袖揎拳，呼五喝六的神态，穷形尽相地描绘了出来。写得最精彩的，要数对美人和风物的刻画。如写美女说：“美人既醉，朱颜酡些。嬉光眇视，目曾波些。”写人着力写眼睛，是《诗经》已开始了，《硕人》便有“巧笑倩兮，美目盼兮”之句，而这里则发展为写挑逗的目光，流动的眼波，更为巧妙生动。整个的美人醉态，犹之一副“贵妃醉酒”图。又如写到苑中之景，说：“川谷径复，流潺湲些。光风转蕙，氾崇兰些。”溪流蜿蜒，汩汩有声，微风挟着阳光，摇动着香草，泛起阵阵清香。“光风”二字语简义丰，形容极为准确。这两句确实是当之无愧的名句。\n\n　　客观叙述，一般不着作者主观色彩。然其中所写醉酒后的种种失态，客观上是有批评性的。那些描写多切合楚王身份。“归来反故室，敬而无妨些”一句，强调归来仍受尊敬而无妨害，应是针对楚怀王可能具有的愧悔心情的。\n\n　　《招魂》的最后部分“乱曰”一段，是全篇的结束语。“乱曰”主要写打猎。在《招魂》影响下的汉大赋，打猎是描写的主要内容。这里却归入了乱辞，原因是这与巫阳招魂辞无关，而是作者自身的活动。这里屈原又以第一人称出现，叙其在南征途中，回忆起参加怀王狩猎的情况。云梦一带是楚国著名的猎场，面积极广，汉赋对云梦之猎有很精彩的描写。而这里并未多写狩猎过程，只写了开始时的壮丽场景，“青骊结驷兮，齐千乘。悬火延起兮，玄颜烝”。实际狩猎只有“君王亲发兮惮青兕”这一句。《吕氏春秋·至忠篇》载有楚王射中随兕的故事：据楚国《故记》说，杀随兕者不到三月必死，楚王射中随兕，申公子培出于忠心，夺归己有，果然代王而死。有这种传说作为依据，“君王亲发兮惮青兕”其实表现了屈原曾经对楚怀王的安危十分关心，也就是“系心怀王，不忘欲反”的意思。然而怀王终于“客死于秦”不得归楚了。诗人最后以“湛湛江水兮，上有枫。目极千里兮，伤春心。魂兮归来，哀江南！”这样极其凄婉的诗句，结束了这一篇千古绝唱。而这结尾几句，堪称《楚辞》中最著名的情景交融片段之一，绝不亚于《九歌·湘夫人》开头“帝子降兮北渚，目眇眇兮愁予。嫋嫋兮秋风，洞庭波兮木叶下”等名句。它对后世的影响甚大，如果说宋玉《九辩》的“悲哉秋之为气也，萧瑟兮草木摇落而变衰，憭栗兮若在远行，登山临水送将归”数语是中国古典文学悲秋传统的滥觞，那么不妨说《招魂》末尾的这几句是中国古典文学伤春传统的滥觞。后世如北朝庾信的《哀江南赋》，题目即取自“魂兮归来哀江南”句，感伤时事，眷怀故国，精神亦与楚辞屈赋相仿佛，其深受《招魂》影响固不待言；即如唐司空曙《送郑明府贬岭南》“青枫江色晚，楚客独伤春”二句，虽所感限于身世之悲，其意象又何尝不是脱胎于《招魂》的乱辞。', poem_tags = '楚辞' WHERE poem_title = '招魂' AND poem_author = '屈原';
UPDATE edu_poem SET poem_translation = '江南有一位贤人，字子固，他不是现在一般人所说的那种贤人，我敬慕他，并和他交朋友。淮南有一位贤人，字正之，他也不是现在一般人所说的那种贤人，我敬慕他，也和他交朋友。这两位贤人，不曾互相往来，不曾互相交谈，也没有互相赠送过礼品。他们的老师和朋友，难道都是相同的吗？我注意考察他们的言行，他们之间的不同之处竟是多么少呀！应该说，这是他们学习圣人的结果。学习圣人，那么他们的老师和朋友，也必定是学习圣人的人。圣人的言行难道会有两样的吗？他们的相似就是必然的了。\n　　我在淮南，向正之提起子固，正之不怀疑我的话。回到江南，向子固提起正之，子固也很相信我的话。于是我知道被人们认为是贤人的人，他们的言行既相似，又互相信任而不猜疑。\n　　子固写了一篇《怀友》赠给我，其大意是希望互相帮助，以便达到中庸的标准才肯罢休。正之也经常这样说过。驾着车子稳步前进，辗过中庸的门庭而进入内室，除了这两位贤人还能有谁呢？我过去不敢肯定自己有可能达到中庸的境地，但也愿意跟在他们左右奔走。在他们的帮助下前进，大概能够达到目的。\n　　唉！做官的各有自己的职守，由于个人私事的牵挂，我们之间不能经常相聚，作《同学一首别子固》，用来互相告诫，并且互相慰勉。\n\n译文二\n　　长江之南有一位贤人，字子固（曾巩字子固），他不是当今世俗所称道的贤人，我敬慕他，和他交为朋友。淮河之南有一位贤人，字正之（孙侔字正之），他不是当今世俗所称道的贤人，我敬慕他，和他交为朋友。二位贤人，从未互相交往过，从未互相交谈过，从未互相赠过钱物，他们的老师和朋友难道都是相同的吗？我考察他们的言语行为，不相似的地方是何等少啊！我说，这恐怕是他们都向圣人学习的结果吧！他们学习圣人，那么他们的老师、朋友也一定是向圣人学习的了。圣人的言语行为难道会有两种样子吗？所以，他们二人的相似也是必然的了。\n　　我在淮河之南，向正之谈及子固，正之不怀疑我说的话；回到长江之南，向子固谈及正之，子固也认为我说的话确实。因此，我又知道了所谓的圣贤之人，既很相似又相互信任，从不猜疑。\n　　子固做了一首《怀友》诗送给我。意思大概是希望我们能相互勉励，一直到达中庸的境界才罢休。正之也曾经说过类似的话。驾着车子安稳行进，通过中庸的门庭而到达内室，除这二位贤人还会有谁呢？我过去不敢肯定自己一定会达到这种境界，不过也愿意跟在他们的左右努力去做，通过他们的帮助使我进入这种境界应该是可能的。\n　　唉！官有自己的职守，私下又有别的事牵累，我们的聚会不可能是经常的，因此，我作了一篇《同学一首别子固》，以相互警策，并相互劝勉。\n\n译文三\n　　长江的南面有一位贤人，表字子固，不是现在所说的一般贤人，我敬仰他，和他交友。淮河的南面有一位贤人，表字正之，也不是现在所说的一般贤人，我也敬仰他，和他交友。\n　　这两位贤人，脚不曾相互来住，嘴也不曾相互讲话，书信和礼物也不曾接受过。他们的老师或朋友，难道完全相同吗？我考察他们的言论和行为，那些不相似的地方多么少啊！说：学习圣人罢了。学习圣人，那么他们的老师或朋友，必定是学习圣人的。圣人的言论和行为，难道会有两样吗？他们的相似也是恰好的。\n　　我在淮南，向正之称道子固，正之对我不怀疑。我回到江南，向子固称道正之，子固也以为对的。我又知道所说的贤人，既是相似的又是互相信任和深信不疑的。子固作《怀友》一首诗赠送我，这首诗的大致意思是希望互相帮助，拉着我以至于到达中庸的境界罢了。正之大概也曾经这样讲过。\n　　安稳地前进，慢慢地行走，车轮碾过中庸之道的庭上，就进入他的家，舍弃这两位贤人还有谁呢？我过去不敢自信必定能达到的，今天也愿意在你们左右干，帮助我进家恐怕就可以了。\n　　唉！官员有职守，私家有牵扯，我们会合不能够经常啊！因此写作《同学》一首向子固告别，来互相警诫，并且互相安慰。', poem_notes = '慕而友：慕：仰慕。友：与之交朋友，动词。\n相过：拜访，交往。\n辞：这里指书信往来。币：帛，丝织品，这里指礼品。\n考：考察。\n适然：理所当然的事情。\n大略：大体上。扳：同“攀”，援引。\n安驱：稳稳当当地驾车。\n辅：车轮碾过。\n造于：到达。\n昔：昔日。', poem_tags = '古文观止,赠别,友情' WHERE poem_title = '同学一首别子固' AND poem_author = '王安石';
UPDATE edu_poem SET poem_tags = '悼亡,回忆,思念' WHERE poem_title = '浪淘沙·帘外五更风' AND poem_author = '李清照';
UPDATE edu_poem SET poem_tags = '古诗三百首,写景,山水' WHERE poem_title = '东溪' AND poem_author = '梅尧臣';
UPDATE edu_poem SET poem_translation = '蟋蟀哀鸣欲断魂，秋风萧瑟秋江岸，人与秋虫共鸣。冷月落沙洲，澄江如彩绢，千里芦花望断，不见归雁行踪。\n默默愁煞庾信，可怜夜夜脉脉含离情。只有那一叶梧桐悠悠下，不知寄托了多少秋凉悲声！', poem_notes = '清平乐：唐代教坊曲名，后用为词牌。又名《清平乐令》、《忆萝花》、《醉东风》等。双调四十六字。前段四句四仄韵；后段四句三平韵。又一体，前段四句四仄韵；后段四句三仄韵。\n蛩（qióng）：蟋蟀。\n练：素白未染之熟绢。\n芦花：芦絮。芦苇花轴上密生的白毛。\n愁损：愁杀。\n兰成：北周庾信的小字。\n关情：动心，牵动情怀。', poem_appreciation = '据《珊瑚网》卷八记载：陆行直《清平乐·重题碧梧苍石图》序中有“候虫凄断，人语西风岸。月落沙平流水漫，惊见芦花来雁。可怜瘦损兰成，多情因为卿卿。只有一枝梧叶，不知多少秋声！”一词。词中所言“卿卿”为当时陆之歌伎，才色皆称。此词定稿后关键字句有较大改动。大概是在作者收入词集时，有意为之。原词无非是写一点“花情柳思”，表达出一种风流艳情，而定稿则将艳情转向“愁情”——为国破为家亡而发的感慨致深的悲愁。\n\n　　上片“候蛩”四句写出秋意：候蛩（即蟋蟀）的哀鸣，西风的衰飒，秋月的清冷，秋江的澄净，无雁的芦花，一幅萧杀的“秋晓图”。以中，人们不难触发出一股悲愤忧愁的“共鸣”来。作者选景立意颇深：写秋寒，不言西风呼啸，而言候蛩凄断；写秋感，不半个愁字，而言芦花盼雁。既含蓄又有美感，表现作者深厚的功力。\n\n　　下片“暗教”四句，道出无限“秋愁”：“兰成”，南朝梁时诗人廋信的小字，后其被北方政权所俘。“梧叶”，梧桐之叶，其最易引发秋感。白居易《长恨歌》中有“春风桃李花开日，秋雨梧桐叶落时”，把“秋雨梧桐”作为人世中最易引起愁情悲感的事来写。而晚唐词人“温庭筠”又有“梧桐树，三更雨，不道离情正苦。一叶叶，一声声，空阶滴到明”（《更漏子》），更为梧叶增添丰厚的感情积淀。而作者言梧叶而写“一枝”，正是更加形象地表现出孤苦潦落，刻划人物情景入木三分。下片短短几句，却把上片所写之景统统升华、提炼成了情语，借廋信之事道出人间道不尽的悲欢离合，借梧叶之孤义表达人世的苍沧。而最后一句“梧叶秋声”又极具概括性和艺术性，又成为盖世佳句。\n\n　　此词在艺术上是成功的，从选景的巧妙，从言情的深远，都极具特色。其笔调精练，含蓄；其风韵幽雅独特；其意境清空淡远；其情感真切感人。正是由于这样的造诣，张炎的“秋词”可以与宋玉的《九辩》、欧阳修的《秋声赋》并列。', poem_tags = '宋词三百首,秋天,感伤' WHERE poem_title = '清平乐·候蛩凄断' AND poem_author = '张炎';
UPDATE edu_poem SET poem_translation = '我独自守一盏残灯，灯已快要燃尽，天乍凉，秋气充塞罗帷和银屏，三更雨点点洒上梧桐，一叶叶、一声声，都是离别的哀音。\n那时，我和她相对调弄宝瑟，拨动炉中温馨的沉水香，同声齐唱《鹧鸪词》，曾是多么欢欣。如今，孤寂地在这西楼，当此风雨凄凄的暗夜，不听清歌也悲泪难禁。', poem_notes = '残红：此指将熄灭的灯焰，也有版本作残釭（gāng）。\n屏帏：屏风和帷帐。\n调：抚弄乐器。宝瑟：瑟的美称。\n金猊（ní）：狮形的铜制香炉。猊，狻猊（suān ní），即狮子。\n西楼：指作者住处。', poem_appreciation = '周紫芝喜欢晏几道的词，因此多有模仿。这首《鹧鸪天》不仅在写作手法和词境上与晏几道词相近，而且题材也是晏几道写得最多的“忆别歌女”主题。词中以今昔对比、悲喜交杂、委婉曲折而又缠绵含蓄的手法写雨夜怀人的别情。\n\n　　词从室内环境写起，“一点残红欲尽时，乍凉秋气满屏帷”，点染出清寂的氛围。夜阑人静时分，油灯将枯，灯火将残，“残红欲尽”，夜晚也即将过去，而人尚未入睡，室内满是“乍凉”的“秋气”。“乍凉”是人对周围环境的感受，“满屏帷”则进一步强化了人对“凉”的体认。凉意本是一种看不见摸不着的东西，人之所以感觉满室生寒，是因为人满怀凄凉愁绪。\n\n　　“梧桐叶上三更雨，叶叶声声是别离”写出词人的听觉，点出“三更秋雨”这个特定环境；此系化用温庭筠《更漏子》下片词意：“梧桐树，三更雨，不道离情正苦，一叶叶，一声声，空阶滴到明。”温词直接写雨声，间接写人，这首词亦复如此。这秋夜无寐所感受到的别离之悲，以雨滴梧桐的音响来暗示，能使人物在特定环境中的感受更富感染力量。所谓“叶叶声声是别离”，与欧阳修的“夜深风竹敲秋韵，万叶千声皆是恨”（《木兰花·别后不知君远近》）异曲同工，都是借情感对声音的反应表达由此构成的心理影响。那“空阶滴到明”和“叶叶声声是别离”，同样都是为了更深入地刻绘出别离所带来的悲苦心情。\n\n　　“调宝瑟，拨金猊”一句，承接“别离”二字，自然过渡到对往事的追忆。一“调”一“拨”，写过去相聚之时，主人公曾与她一起抚琴调瑟，一起拨动炉中的燃香，使满室生香，暖意融融。“那时同唱鹧鸪词”，“鹧鸪”常被当做男女爱情的象征。在这样美好的氛围中，二人一起唱起吟咏爱情的曲词，那时的情景，亲密而快乐，令人难以忘怀。\n\n　　由以上两句可见，女子的身份是一名歌女。末句以“如今”开启今昔对比。“风雨西楼夜”呼应上阕所描写的环境和景状，将往日的欢乐与今时今日的寂寞凄凉进行对比，从而引出“不听清歌也泪垂”的慨叹。过去，主人公听到歌女所唱“清歌”，曾因其感人肺腑而潸然泪下，如今，不仅无“清歌”可听，而且又因回忆往昔欢聚景象而牵扯出更多的孤寂情怀，故日“泪垂”。这里的“泪”既为过去不可追回而流，更为今日之愁苦而流。\n\n　　词人围绕“风雨西楼夜”落笔，先摹写整体环境，写景不忘烘托悲愁情绪；次写主人公身处西楼回望往事，极言往日之欢；最后词情停顿于“如今”，在往日欢聚的对比下，进一步叙说主人公深切的怀念和对当下处境的喟叹。结构层次分明，而感情绵延悱恻，贯穿全词始末，工整疏密中见摇曳。', poem_tags = '宋词三百首,宋词精选,婉约,离别,怀人' WHERE poem_title = '鹧鸪天·一点残红欲尽时' AND poem_author = '周紫芝';
UPDATE edu_poem SET poem_tags = '秋天,写景' WHERE poem_title = '戚氏·晚秋天' AND poem_author = '柳永';
UPDATE edu_poem SET poem_translation = '注释 雊，读如够，野鸡叫。 转薄，回旋停泊。薄，通“ 泊 ”。', poem_appreciation = '此诗写军旅生活的艰辛。薇，野菜，即野豌豆苗。白天我们到山上去采野豌豆苗，因为到黄昏的时候会很饿。溪谷中风很大，又有霜露打湿大家的衣裳，真是非常寒冷。野鸡的叫声遍布山野，猿猴在相互追逐。\n\n　　在这样的荒郊野外，不免使人回望故乡，然而，故乡又在哪里？忧郁如石头一般垒积胸中。每座山都有山崖，每棵树都有树枝，可我内心的忧愁又是从哪里来的呢？没有人知道。\n\n　　人生不过是暂时寄托于人世，何必如此忧愁呢？我现在不快乐，时光也照样流逝。就像河里的那一只小舟，随着水波流转，也不知道会停在哪里，这就好比是我们的人生啊，谁也不知道自己会在哪里停泊。\n\n　　还是披上我的皮裘，骑着良马，在飞驰中暂时地忘却这人生的烦恼吧。\n\n　　从此诗我们可以看到，曹丕也是一个颇有诗意的人。在远离故土的荒郊野外，不免会产生莫名的忧愁，但这忧愁从何而来、到何而止，我们谁也不知道。而这人生，似乎也正如这忧愁一般，不知从何而来，也不知到何而止。因而，还是暂时地忘却吧，不要去想它。', poem_tags = '乐府,军旅,生活' WHERE poem_title = '善哉行·其一' AND poem_author = '曹丕';
UPDATE edu_poem SET poem_translation = '明亮皎洁的月光照耀着夜空，东边墙角下不时地传来蟋蟀的吟唱。\n北斗星中的玉衡星已指向了孟冬，天上众多的星星是这样闪烁璀璨。\n晶莹的露珠啊已沾满了地上的野草，时节流转转瞬间又是夏去秋来。\n树枝间传来秋蝉断续的鸣叫，燕子啊不知又要飞往何方？\n昔日与我携手同游的同门好友，已经举翅高飞腾达青云了。\n可是他们一点也不念曾经的交情，就像行人遗弃脚印一样把我抛弃！\n南箕星、北斗星都不能用来盛物斟酒，牵牛星也不能用来负轭拉车！\n再好的友情也不能像磐石那样坚固，仔细想来炎凉世态虚名又有何用？', poem_notes = '皎夜光：犹言明夜光。\n促织：蟋蟀的别名，一作“趣织”。\n玉衡：指北斗七星中的第五星。北斗七星形似酌酒的斗：第一星至第四星成勺形，称斗魁；第五星至第七星成一条直线，称斗柄。由于地球绕日公转，从地面上看去，斗星每月变一方位。古人根据斗星所指方位的变换来辨别节令的推移。孟冬：本指冬季的第一个月，此处指方位。玉衡星已经指向孟冬亥宫之方向——西北方，时已过夜半。\n历历：逐个的意思，众星行列分明的样子。\n忽：本义为不重视、忽略，这里用引申义，急速、突然的意思。易：变换。\n玄鸟：燕子。安适：往什么地方去？燕子是候鸟，春天北来，秋时南飞。这句是说天凉了，燕子又要飞往什么地方去了？\n同门友：同在师门受学的朋友。\n翮（hé）：本义为羽毛中间的硬管，指禽鸟的尾羽或翼羽中那些大而硬的角质空心的羽轴。据说善飞的鸟有六根健劲的羽茎。这里泛指鸟的翅膀。据说善飞的鸟有六根健劲的羽茎，故曰“六翮”。\n携手好：指共患难的友谊。\n“弃我“句：就像行人遗弃脚印一样抛弃了我。\n南箕（jī）：星名，形似簸箕。北有斗：即北斗，星名，形似斗（酌酒器）。\n牵牛：指牵牛星。轭：车辕前横木，牛拉车则负轭。“不负轭”是说不拉车。\n良：的确。盘石：同“磐石”，特大石，用以象征坚定不移的感情。', poem_appreciation = '此诗开篇写道：“明月皎夜光，促织鸣东壁。”在皎洁的月色光下，蟋蟀在低吟，并交织成一曲无比清切的夜之旋律。在此，诗人从视角和听觉两方面描写了环境，不但表现出环境的幽静，心境的凄然，而且也暗示了时间是很晚了，也就是下半夜时间。再看夜空，“玉衡指孟冬，众星何历历。”北斗横转，那由“玉衡”“开阳”“摇光”三星组成的斗柄（杓），正指向天象十二方位中的“孟冬”，闪烁的星辰，更如镶嵌天幕的明珠，把夜空辉映得一片璀璨。一切似乎都很美好，包括那披着一身月光漫步的诗人。在中国古代，人们都是根据斗星所指方位的变换来辨别节令的推移。据金克木先生解说，“孟冬”在这里指的不是初冬节令（因为下文明说还有“秋蝉”），而是指仲秋后半夜的某个时刻。此时此刻诗人还在月下踽踽步，说明诗人心神不宁，胸中缠绕着忧愁。\n\n　　诗人默默无语，在月光下徘徊。“白露沾野草，时节忽复易。”野草上已沾满晶莹的露珠，在月光下显得那样晶莹，寒气逼人，明显感觉到时节已经转换。诗人已经感觉到，深秋已在不知不觉中到来，时光之流驶，又是一年秋天到来了。当然，这里写了时间的快速流逝，也是在暗示时间不饶人，人也在一天天老去。怪不得往日的燕子（玄鸟）都不见了，原来已是秋雁南归的时节。这些燕子又将飞往哪里去呢？——“秋蝉鸣树间，玄鸟逝安适”？这就是诗人在月下所发出的怅然问叹。这问叹似乎只对“玄鸟”而发，实际上，它又是诗人那充满失意的怅然自问。从下文可知，诗人之游宦京华已几经寒暑。而今草露蝉鸣、又经一秋，它们在诗人心上所勾起的，是流离客中的无限惆怅和凄怆。\n\n　　以上八句从描述秋夜之景入笔，抒写诗人月下徘徊的哀伤之情。适应着秋夜的清寂和诗人怅惘、失意之感，笔触运得轻轻的，色彩也一片渗白；没有大的音响，只有蟋蟀、秋蝉交鸣中偶发的、诗人那悠悠的叹息之声。当诗人一触及自身的伤痛时，情感便不兔愤愤起来。诗人久滞客中，在夜半如此焦灼难眠，那是因为他曾经希望过、期待过，而今这希望和期待全破灭了。\n\n　　理想破灭，心烦意乱，夜不能寐。于是，诗人写道：“昔我同门友，高举振六翮。”这句是以鸟的展翅高飞比喻同门友的飞黄腾达。这在当初，无疑如一道灿烂的阳光，把诗人的前路照耀得五彩缓纷。他相信，“同门”好友将会从青云间垂下手来，提携自己一把；总有一天，他将能与友人一起比翼齐飞、邀游碧空。但事实却大大出乎诗人预料，昔日的同门之友，而今却成了相见不相认的陌路之人。他竟然在平步青云之际，把自己当作走路时的脚迹一样，留置身后而不屑一顾了。“不念携手好，弃我如遗迹”，这毫不经意中运用的妙喻，不仅入木三分地刻画了同门好友“一阔脸就变”的卑劣之态，同时又表露了诗人那不谙世态炎凉的无比惊讶、悲愤和不平。\n\n　　至此全诗的主旨方才揭开，那在月光下徘徊的诗人，原来就是这样一位被同门好友所欺骗、所抛弃的落魄者。在他的背后，月光印出了静静的身影；而在头顶上空，依然是明珠般闪烁的“历历”众星。当诗人带着被抛弃的余愤怒仰望星空时，偏偏又瞥见了那名为“箕星”、“斗星”和“牵牛”的星座。诗人顿时生出一股无名的怨气，指点着这些星座大声责问起来：“南箕北有斗，牵牛不负扼！”这里语出《小雅·大东》：“维南有箕，不可以颠扬；维北有斗，不可以挹酒浆”“皖彼牵牛，不以服箱（车）”。诗人在此借用“南箕”“北斗”“牵牛”等星宿表现出了有虚名无实用，借此比喻朋友的有虚名无实用。失意落魄的诗人心中很是痛苦，夜不能寐，走出房间，仰望天空，看见星星，由此而想到“同门友”的淡漠，心中忧愤不已，苦闷无处发泄，就借此问问星星。其实，这里也暗示了诗人没有什么朋友，即使有，也是十分功利的、无情意的人。\n\n　　诗歌最后写道：“良无盘石固，虚名复何益？”想到当年友人怎样信誓旦旦，声称同门之谊的“坚如盘石”，可而今“同门”虚名犹存，“盘石”一样的友情也再没有了。诗人终于仰天长叹，以悲愤的感慨收束了全诗。这叹息和感溉，包含了诗人那被炎凉世态所欺骗、所愚弄的无比伤痛和悲哀。\n\n　　抒写这样的伤痛和悲哀，本来只用数语即可说尽。此诗却偏从秋夜之景写起，初看似与词旨全无关涉，其实均与后文的情感抒发脉络相连：月光笼盖悲情，为全诗敷上了凄清的底色；促织鸣于东壁，给幽寂增添了几多哀音；“玉衡指孟”点明夜半不眠之时辰，“众星何历历”暗伏箕、斗、牵牛之奇思；然后从草露、蝉鸣中，引出时光流驶之感，触动同门相弃之痛；眼看到了愤极“直落”、难以控驭的地步。这就是《明月皎夜光》写景抒愤上的妙处，那感叹、愤激、伤痛和悲哀，始终交织在一片星光、月色、螺蜂、蝉鸣之中。', poem_tags = '古诗十九首,秋天,月光,写景,抒情' WHERE poem_title = '明月皎夜光' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '流水为什么去得这样匆匆，深宫里却整日如此的清闲。\n我殷勤地辞别这一片红叶，离开这好去到自由的人家。', poem_notes = '题注：卢偓应举时，偶临御沟，得一红叶，上有绝句，置于巾箱。及出宫人，偓得韩氏，睹红叶，吁嗟久之，曰：“当时偶题，不谓郎君得之。”\n深宫：宫禁之中，帝王居住处。尽日：整天，天天如此。\n谢：告，嘱咐。一说意为辞别。\n好去：送别之词。犹言好走。', poem_appreciation = '这一故事在辗转流传中，当然不免有被人添枝加叶之处，但也不会完全出于杜撰。从诗的内容看，很象宫人口吻。它写的是一个失去自由、失去幸福的人对自由、对幸福的向往。诗的前两句“流水何太急，深宫尽日闲”，诗的后两句“殷勤谢红叶，好去到人间”，尽在不言之中，可以不言而喻了。俞陛云在《诗境浅说续编》中评李白的《玉阶怨》说：“其写怨意，不在表面，而在空际。”这话也可以移作对这首《题红叶》诗的赞语。\n\n　　除这首《题红叶》外，在唐代还流传有一个梧叶题诗的故事。据《云溪友议》、《本事诗》等书记述，天宝年间，一位洛阳宫苑中的宫女在梧叶上写了一首诗，随御沟流出，诗云：“一入深宫里，年年不见春。聊题一片叶，寄与有情人。”诗在民间遂得传播。诗人顾况得诗后曾和诗一首：“愁见莺啼柳絮飞，上阳宫女断肠时。君恩不闭东流水，叶上题诗寄与谁？”过了十几天，又在御沟流出的梧叶上见诗一首，诗云：“一叶题诗出禁城，谁人酬和独含情。自嗟不及波中叶，荡漾乘春取次行。”这后一首诗在《全唐诗》中题作《又题洛苑梧叶上》，也不失为一首好诗。从诗的首句“一叶题诗出禁城”，可以想见题诗人目送叶去、心与俱远的情景。这片小小的梧叶，成了她的化身，既负荷着她的巨大的苦痛，又浮载着她的缥缈的希冀。句中的“出禁城”三字，与《题红叶》诗中的“到人间”三字一样，含有极其复杂的感情。这里，人生的要求、祝愿、遐想、幻梦是溶合在一起的。下句“谁人酬和独含情”，是进而游翔她的诗思。这位得不到爱情的少女，把她对爱情的想象随着梧叶也送出了禁城。她题诗的一片心意原是“寄与有情人”，但“寄与谁”，“谁人酬和”，这片梧叶出禁城后又会有什么样的遭遇呢？这些，纵然渺茫难知，也足以令她浮想翩翩，含情脉脉；可是，句中一个“独”字却又透露了她的现实处境之可哀。下面两句“自嗟不及波中叶，荡漾乘春取次行”，正是回到现实后的绝望和嗟叹。这时，随波荡漾的梧叶已经乘春而逝，而回顾自身，仍然在“年年不见春”的禁城之内。如果说诗的前半首是身在痛苦环境中产生的美好幻想；那么，这后半首就是走出幻想世界后感到的加倍痛苦了。总的看来，这首《又题》写得较实，较直，以真挚动人。但不如《题红叶》诗之空灵酝藉，言简意长，给人以更多的玩索余地。\n\n　　唐代出现了大量宫怨诗，但几乎全都出自宫外人手笔，至多只能做到设身处地，代抒怨情，有的还是借题发挥，另有寄托。这首《题红叶》诗以及另两首题梧叶诗之可贵，就在于让我们直接从宫人之口听到了宫人的心声。', poem_tags = '女子,向往,自由' WHERE poem_title = '题红叶' AND poem_author = '宣宗宫人';
UPDATE edu_poem SET poem_translation = '不管是世俗中的还是超然世外的，都在期待中秋月明。\n一年中只有这一次，所以唯恐这天有云遮月。\n露水洗净了尘埃，月光照亮了万物。\n正适合高声吟诵诗篇，可惜月亮又西沉，只给人们留下满腹惆怅。', poem_notes = '尘里尘外：尘世内外。\n咸：都、全。\n濡：沾湿，沾染。\n朗吟：高声吟诵。', poem_tags = '中秋,节日,抒情' WHERE poem_title = '中秋' AND poem_author = '刘得仁';
UPDATE edu_poem SET poem_translation = '如青天之顶裂开一个豁口，万丈清泉从中泻下来；\n又如剪裁一条素绢，在丽日朗照下，从秋高气爽的蓝天上飘然下悬。', poem_notes = '豁（huō攉)裂开。\n青冥，青色的天空。\n颠：顶。\n素：白色的生绢。', poem_tags = '写景,山水' WHERE poem_title = '瀑布' AND poem_author = '施肩吾';
UPDATE edu_poem SET poem_translation = '被千万层山水阻隔使书信来往间断，今日忽接到你寄来的诗，难得你爱怜我在梦中还打听我。\n我现在有病心神错乱，只梦见些不相干的人却没有梦见你。', poem_notes = '乐天：白居易的字。\n微之：元稹的字。\n书：信件。\n念：思念。\n病：诗人在通州得过一样严重的疟疾，病后身体一直很差，记忆衰退，同时也包含内心的苦闷。\n闲人：不相干的人。', poem_appreciation = '元稹的这首酬答小诗构思相当奇巧，感情极其诚挚。虽然全诗只有四句，却把诗人对好友的无限感念之情和内心世界的凄苦心境描写得漓淋尽致。\n\n　　元稹贬通州，白居易谪江州，两地迢迢数千里，通信十分困难。因此，诗一开始就说“山水万重书断绝”。此时好不容易收到白居易寄来的一首诗，诗中告诉元稹，前一天晚上又梦见了他。老朋友感情这样深挚，使他深深感动。诗的前两句，诗人首先感叹于由于“山水万重”的阻隔，常常会使人的通讯断绝，因此能得到好友的寄诗是不容易的，而从好友的诗中又得知好友连梦中都在关切着他的境遇，这种人世间珍贵的深挚友情，使诗人感深肺腑。这两句直叙贬谪之后处境的艰难与郁闷的心情。这种艰难，不光是反映在山水万重上，更体现在由此导致的音书断绝上。这种郁闷，不仅仅是因为身处荒僻之地的无聊穷困，更多的是因为很难得到好友的消息。\n\n　　“念君怜我梦相闻”一句，表面经这千难万险，诗人终于收到好友的来信，知悉还有远在异地思念入梦的情景，不禁感慨万千，夜不能寐。后两句，诗人紧扣好友寄诗中的急切询问，向还有作了深情的回答。两诗都没有直接叙述自己对好友的苦苦思念挂牵，而是用写梦来抒难尽之情，但写法又各辟蹊径：白居易的寄诗主要以反问的语气用如梦后的苦思来表示对还有境遇的关切；而元稹的诗，虽是从正面回答，但构思也同样精巧，他回答好友自己因病魔缠身又梦到一些闲人而感到痛苦。前者“梦见君”，后者“不梦君”，这一唱一和，表面看去是如此截然不同，可是形成了感情基础，都是来自两人彼此苦思相念之情。这既符合酬答诗在内容上要彼此相应的基本要求，又在构思上独处机杼，使人于同中见异。酬答诗在形式上也有严格的要求，它要求和诗与原诗必须题材主题相同、诗体相同、用韵相同，有的甚至连韵脚字词都相同。而元稹这首诗能在如此短小的篇幅中，依照酬答诗的形式要求，写得如此深沉蕴藉、形神俱肖、富有包孕，为历代诗评家视为酬答诗中的佳作。\n\n　　全诗纯用白描，几乎没有一点设色布景之处，也丝毫没有生涩拗口之语，而且人物形象生动隽永，情调境界感人肺腑。特别是作为一首次韵和诗，在押韵韵脚受到严格限制的情况下，能匠心独运，别出心裁地写出这首诗，更其难能可贵。', poem_tags = '友情' WHERE poem_title = '酬乐天频梦微之' AND poem_author = '元稹';
UPDATE edu_poem SET poem_translation = '山石峥嵘险峭，山路狭窄像羊肠，蝙蝠穿飞的黄昏，来到这座庙堂。\n登上庙堂坐台阶，刚下透雨一场，经雨芭蕉枝粗叶大，山栀更肥壮。\n僧人告诉我说，古壁佛画真堂皇，用火把照看，迷迷糊糊看不清爽。\n为我铺好床席，又准备米饭菜汤，饭菜虽粗糙，却够填饱我的饥肠。\n夜深清静好睡觉，百虫停止吵嚷，明月爬上了山头，清辉泻入门窗。\n天明我独自离去，无法辨清路向，出入雾霭之中，我上下摸索踉跄。\n山花鲜红涧水碧绿，光泽又艳繁，时见松栎粗大十围，郁郁又苍苍。\n遇到涧流当道，光着脚板踏石淌，水声激激风飘飘，掀起我的衣裳。\n人生在世能如此，也应自得其乐，何必受到约束，宛若被套上马缰？\n唉呀，我那几个情投意合的伙伴，怎么能到年老，还不再返回故乡？', poem_notes = '山石：这是取诗的首句开头三字为 题，乃旧诗标题的常见用法，它与诗的内容无关。\n荦确（luòquè洛却）：指山石险峻不平的样子。行径：行下次的路径。微：狭窄。\n蝙蝠：哺 乳动物，夜间在空中飞翔，捕食蚊、蛾等。这是写山寺黄昏的景象并点明到寺的时间。\n升堂：进入寺中厅堂。阶：厅堂前的台阶。新雨：刚下过的雨。\n栀子：常绿灌水，夏季开白花，香气浓郁。这两句说，进入厅堂后坐在台阶上，这刚下过的一场雨水该有多么充足；那吸饱了雨水的芭蕉叶子更加硕大，而挺立枝头 的栀子花苞也显得特别肥壮。诗人热情地赞美了这山野生机勃勃的动人景象。\n佛画：画的佛画像。\n稀：依稀，模糊，看不清楚。一作“稀少”解。所见 稀：即少见的好画。这两句说，和尚告诉我说，古壁上面的佛像很好，并拿来灯火观看，尚能依稀可见。\n置：供。羹（gēng耕）：菜汤。这里是泛指菜 蔬。\n疏粝（lì历）：糙米饭。这里是指简单的饭食。饱我饥：给我充饥。\n百虫绝：一切虫鸣声都没有了。\n清月：清朗的月光。出岭：指清 月从山岭那边升上来。夜深月出，说明这是下弦月。扉（fei非）：门。光入扉：指月光穿过门户，照时室内。\n无道路：指因晨雾迷茫，不辨道路，随意 步行的意思。\n出入高下：指进进出出于高高低低的山谷径路意思。霏：氛雾。穷烟霏：空尽云雾，即走遍了云遮雾绕的山径。\n山红涧：即山花红 艳、涧水清碧。纷：繁盛。烂漫：光彩四射的样子。\n枥（lì历）：同“栎”，落叶乔木。木围：形容树干非常粗大。两手合抱一周称一围。\n当 流：对着流水。赤足踏涧石：是说对着流水就打起赤脚，踏着涧中石头淌水而过。\n人生如此；指上面所说的山中赏心乐事。\n局束：拘束，不自由的意思。靰（jī基）：马的缰绳。这里作动词用，即牢笼、控制的意思。\n吾党二三子：指和自己志趣相合的几个朋友。\n安得：怎能。不更归：不再回去了，表示对官场的厌弃。', poem_appreciation = '题目“山石”不是本要专门抒发的内容，而是取首句的头两个字而已。这是一首记游诗，按时间地点依次写来，全诗可分四个部分。\n\n　　第一部分从开头至“芭蕉叶大栀子肥”，写黄昏到寺所见景色。“山石荦确行径微，黄昏到寺蝙蝠飞”，首句写寺外山石的错杂不平，道路的狭窄崎岖；次句写古寺的荒凉陈旧，到黄昏时众多的蝙蝠窜上飞下，纷纷攘攘。仅此两句，就把整个深山古寺的景色特征突现出来，使人如临其境。以下两句是入寺坐定后所见阶下景物：芭蕉叶子阔大，栀子果实肥硕，是新雨“足”后的特有景致，读之令人顿觉精神爽快。\n\n　　第二部分从“僧言古壁佛画好”至“清月出岭光入扉”，写入寺后一夜的情景。这里一部分先写僧人的热情招待，先是主动地向客人介绍古壁佛画，兴致勃勃地擎着蜡烛引着客人前去观看。“稀”字既道出壁画的珍贵，也生动地显露出诗人的惊喜之情。接着写僧人的殷勤铺床置饭，“疏粝亦足饱我饥”，一见僧人生活的简朴，二见诗人对僧家招待的满意之情。后两句写夜深入睡，“百虫绝”从反面衬托出深山古庙虫鸣之盛，直到夜深之后才鸣声渐息。“清月出岭光入扉”，很有李白“床前明月光”诗句的意境，使人有无限静寂之感。\n\n　　第三部分从“天明独去无道路”至“水声激激风吹衣”，写晨去的路上所见所感。雨后的深山，晨雾缭绕，曲径萦回，以至分不清道路，高低难行。一个“穷”字，写出诗人奔出雾区的喜悦。接下去描绘脱离雾区，在一片晴朗中所见到的秀丽山景：峭崖上红花一片，山涧下碧水清清，更有那挺拔粗壮的松、枥树时时跃入眼帘。“时见”二字看似平常，实有精确的含意，它表明这些松、枥树不是长在一处的，而是诗人在行进中时时见到的。如此便把景色拉开，使读者的意念像跟着诗人行走似的一路领略山中风情。下两句写新雨后的山涧，水流横溢，激溅奔泻，致使诗人脱去鞋子，提起裤管，小心翼翼地在溪流中移进。山风阵阵，牵衣动裳，使人有赏不尽的山、水、风、石的乐趣。这里景色丰富，境地清幽。所以诗写到此，很自然地引出最后一段。\n\n　　第四部分从“人生如此自可乐”到最后，是抒写情怀。韩愈在长期的官场生活中，陟黜升沉，身不由己，满腔的愤懑不平，郁积难抒。故对眼前这种自由自在，不受人挟制的山水生活感到十分快乐和满足。从而希望和自己同道的“二三子”能一起来过这种清心适意的生活。这种痛恨官场、追求自由的思想在当时是有积极意义的。\n\n　　这首诗看似平凡，实际有较高的艺术成就。突出的特点是巧妙地运用了赋体中“铺采摛文”的手法。所谓赋体的“铺采摛文”，就不是一般地叙事状物，而是在记叙的过程中兴会淋漓地、铺扬蹈厉地状写事物，绘景抒情，使之物相尽形，达到辗转生发的艺术效果。《山石》诗便是如此。无论是开头部分的黄昏到寺，还是其后的歇寺、离寺，先后按时间推移，把在这一段时间中的所做所为、所见所闻、交待得清清楚楚。而这些事都是日常的平凡之事（像入寺、坐阶、看画、铺床、睡觉、晨起登程等）；客观之景（像大石、蝙蝠、芭蕉、栀子、月光、晨雾、山花、涧水、松枥等）就像一篇记事的日记一般，没什么奇特之处。然而诗人却在这些无甚奇特的事物中，洋溢着真挚之情，状写出美妙之景，从而生发出无限的诗意。如“黄昏到寺蝙蝠飞”，虽是一个很普通的现象，也无雕饰的词语，但却十分有力地烘托出深山古寺在黄昏中的气氛，使人如见古寺之荒凉，环境之沉寂。如身临其境地感受到一种美妙的诗意。再如“当流赤足踏涧石，水声激激风吹衣”又是一幅多么优美的图画。水声激激，风扯衣衫，一位赤足的人在溪流中上下小心踏石过流，其神其态，其情其趣，使人对这幅充满诗意的“山涧行”的图画，产生无限生趣。这就是诗人“铺采摛文”笔法所升华出的功力。\n\n　　这首诗为传统的纪游诗开拓了新领域，它汲取了山水游记的特点，按照行程的顺序逐层叙写游踪。然而却不像记流水账那样呆板乏味，其表现手法是巧妙的。此诗虽说是逐层叙写，仍经过严格的选择和经心的提炼。如从“黄昏到寺”到就寝之前，实际上的所经所见所闻所感当然很多，但摄入镜头的，却只有“蝙蝠飞”、“芭蕉叶大栀子肥”、寺僧陪看壁画和“铺床拂席置羹饭”等殷勤款待的情景，因为这体现了山中的自然美和人情美，跟“为人靰”的幕僚生活相对照，使诗人萌发了归耕或归隐的念头，是结尾“主题歌”所以形成的重要根据。关于夜宿和早行，所摄者也只是最能体现山野的自然美和自由生活的那些镜头，同样是结尾的主题歌所以形成的重要根据。\n\n　　再说，按行程顺序叙写，也就是按时间顺序叙写，时间不同，天气的阴晴和光线的强弱也不同。这篇诗的突出特点，就在于诗人善于捕捉不同景物在特定时间、特定天气里所呈现的不同光感、不同湿度和不同色调。如用“新雨足”表明大地的一切刚经过雨水的滋润和洗涤；这才写主人公于苍茫暮色中赞赏“芭蕉叶大栀子肥”，而那芭蕉叶和栀子花也就带着它们在雨后日暮之时所特有的光感、湿度和色调呈现出来。写月而冠以“清”字，表明那是“新雨”之后的月儿。写朝景，新奇而多变。因为他不是写一般的朝景，而是写山中雨后的朝景。他先以“天明独去无道路”一句，总括了山中雨霁，地面潮湿，黎明之时，浓雾弥漫的特点，然后用“出入高下穷烟霏”一句，画出了雾中早行图。“烟霏”既“穷”，阳光普照，就看见涧水经雨而更深更碧，山花经雨而更红更亮。于是用“山红涧碧”加以概括。山红而涧碧，红碧相辉映，色彩已很明丽。但由于诗人敏锐地把握了雨后天晴，秋阳照耀下的山花、涧水所特有的光感、湿度和色调，因而感到光用“红”、“碧”还很不够，又用“纷烂漫”加以渲染，才把那“山红涧碧”的美景表现得鲜艳夺目。', poem_tags = '唐诗三百首,纪游,写景,抒情' WHERE poem_title = '山石' AND poem_author = '韩愈';
UPDATE edu_poem SET poem_translation = '其一\n悲伤凄凉的离开家乡，来到遥远的交河城。\n衙门有规定的路程期限，否则就得设法逃离触犯法律的责难。\n您拥有广阔的疆域领土，为什么还要再争夺无度？\n辜负父母的养育之恩，暗自悲泣却不敢言，背起兵器踏上征程。\n\n其六\n拉弓要拉最坚硬的，射箭要射最长的。\n射人先要射马，擒贼先要擒住他们的首领。\n杀人要有限制，各个国家都有边界。\n只要能够制止敌人的侵犯就可以了，难道打仗就是为了多杀人吗？\n\n其九\n我从军十多年了，难道没有一点点的功劳？\n一般将士看重争功贪赏，我想说一下自己的功劳但羞于与他们同调。\n中原尚且有斗争，何况边疆地区呢？大丈夫志在四方，又哪能怕吃苦？', poem_notes = '戚戚，愁苦貌。因被迫应往，故心怀戚戚。\n悠悠，犹漫漫，遥远貌。交河在新疆维吾尔自治区吐鲁番县，是唐王朝防吐蕃处。\n公宗，犹官家。有程期，是说赴交河有一定期限。\n是说如果逃命，又难逃法网。唐行“府兵制”，天宝末，还未全废，士兵有户籍，逃则连 累父母妻子。\n这两句点出赴交河之故，是全诗的主脑，是人民的抗议，也是壮甫的斥责。\n离家日久，一切习惯了，熟习了，放下再受伙伴们的戏弄和取笑。按《通典》卷一百四十九：“诸将上不得倚作主帅，及恃己力强，欺傲火（伙）人，全无长幼，兼笞挞懦弱，减削粮食衣资，并军器火具，恣意令擎，劳逸不等。”则知当时军中实有欺负人的现象。\n“死无时”是说时时都有死的可能，不一定在战场。正因为死活毫无把握，所以也就顾不 得什么骨肉之恩，说得极深刻。\n走马，即跑马。辔头，当泛指马的络头。脱是去掉不用。\n青丝，即马缰。挑是信手的挑着。\n捷下是飞驰而下。\n搴，拔取。是说从马上俯下身去练习拨旗。 《通典》（卷同上）：“搴旗斩将，陷阵摧锋，上赏。”所以要“试搴旗”。吴昌祺说：“走马四句，捷自负，而意乃在 ‘死无时’也。” 这说法很对。\n呜咽水，指陇头水。《三秦记》：“陇山顶有泉，清水四注，俗歌：陇头流水，呜声呜咽。遥望秦川，肝肠断绝。”这以下四句即化用陇头歌。\n轻是轻忽，只当没听见。肠断声指呜咽的水声。\n这句是上句的否定。心绪久乱，而水声触耳，想不愁也不行。心不在焉，因而伤手。初 尚不知，见水赤才发觉。刻划人微。\n丈夫，犹言“男儿”、“健儿”或“壮士”，是征夫自谓。誓许国，是说决心把生命献给国家。这以下四句征夫的心理有了转变，但是出于无可奈何的，所以语似壮而情实悲，口里说的和心里想的仍有矛盾。\n这句承上句。既以身许国，此外还有什么值得悲愤和留念的呢？\n西汉宣帝曾图画霍光、苏武等功臣一十八人于麒麟阁。\n当字很有意思，好像甘心如此，其实是不甘心。末两句也是反话。所以有此矛盾现象，是由于这个战争不是正义的战争，人民也是被强制去作战的。\n送徒有长，是指率领（其实是押解）征夫的头子，刘邦、陈胜都曾做过。\n远戍，指人说，是征夫自谓。“亦有身”是说我们也有一条命，也是一个人。是反抗和愤恨的话。仇注：“远戍句，此被徒长呵斥而作自怜语。”不对头。\n这两句是说，死活我们都向前去，决不作孬种，用不着你们吹胡子瞪眼，也是汪性使气 的话。仇注：“吏即送徒之长。”\n附书即捎信儿。六亲是父母兄弟妻子。\n这两句概括书中的大意。决绝，是永别。仿佛是说：“妈呀！爸爸呀！妻呀！儿呀！…… 我们再也不能见面了！我们苦也不能苦在一起了！”吴瞻泰云：“不言不同欢乐，而言不同苦辛，并苦辛亦不能同，怨之甚也。”\n“迢迢”，远貌。\n异苦乐是说苦乐不均。在剥削阶级的部队中，官兵总是对立的。\n隔河的河即交河。“骑”字照以前的习惯读法，应读作去声，因为这是名词，指骑兵。\n倏忽，一会儿工夫。\n《通鉴》说当时“戍边者多为边将苦使，利其死而没其财”（卷二百一十六）。可见“为奴仆”确是实际情形。\n树，立也。\n这四句极象谣谚，可能是当时军中流行的作战歌诀。马目标大易射，马倒则人非死即伤，故先射马，蛇无头而不行，王擒则贼自溃散，故先擒王。擒王句乃主意所在，下四句便是引伸这一句的。\n亦有限，是说也有个限度，有个主从。正承上句意。沈德潜 《杜诗偶评》：“诸本杀人亦有限，惟文待诏（文徵明）作杀人亦无限，以开合语出之，较有味。”不确。\n自有疆，是说总归有个疆界，饶你再开边。和第一首“开边一何多”照应。\n这两句是说如果能抵制外来侵略的话，那末只要擒其渠魁就行了，又哪在多杀人呢？张远《杜诗会粹》：“大经济语，借戍卒口中说出。”在这里我们相当明显的看到杜甫的政治观点。\n雨作动词用，读去声。雨雪即下雪。\n山高所以径危。因筑城，故须抱石。\n指落是手指被冻落。\n汉月，指祖国。\n祖国在南方，所以见浮云南去便想攀住它。“暮”字含情。\n单音禅。汉时匈奴称其君长曰单于，这里泛指边疆少数民族君长。\n古宝剑有雌雄，这里只是取其字面。四五动，是说没费多大气力。\n奔是奔北，即吃了败仗。\n名王，如匈奴的左贤王、右贤王。这里泛指贵人。正是所谓“擒贼先擒王”。\n辕门即军门。\n这两句主要写有功不居的高尚风格，是第三章“大夫誓许国”的具体表现，也是下章“丈夫四方志”的一个过渡。\n能无，犹“岂无”、“宁无”，但含有估计的意味，分寸功，极谦言功小。观从军十年 馀，可知“府兵制”这时已完全破坏。\n众人，指一般将士。苟得，指争功贪赏。\n“欲语”二字一顿。想说说自己的功，又不屑跟他们同调，干脆不说也罢。《礼记：由礼》：“毋剿说，毋雷同。”雷一发声，四下同应，故以比人云亦云。\n这两句过去解说不一。大意是说：中原尚且有斗争，何况边疆地区？应前“单于寇我垒”。\n这两句是将自己再提高一步，丈夫志在四方，又哪能怕吃苦？ 《论语》“君子固穷”。', poem_tags = '讽刺,边塞,战争,组诗' WHERE poem_title = '前出塞九首' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_tags = '叙事,抒情,愤懑' WHERE poem_title = '自洛之越' AND poem_author = '孟浩然';
UPDATE edu_poem SET poem_tags = '秋天,送别,写景,抒情,组诗' WHERE poem_title = '江亭夜月送别二首' AND poem_author = '王勃';
UPDATE edu_poem SET poem_translation = '大车行走声槛槛，青色毛衣像嫩菼。难道是我不像你？相爱就怕你不敢。\n大车前行声啍啍，红色毛衣色如璊。难道是我不像你？怕你不跟我私奔。\n活着不能在一室，死后同埋一个坑。我说的话你不信，就让太阳来作证。', poem_notes = '大车：古代用牛拉货的车，一说古代贵族乘坐的车子。\n槛（kǎn）槛：车轮的响声。\n毳（cuì）衣：毡子。本指兽类细毛，可织成布匹，制衣或缝制车上的帐篷。此处从闻一多说。菼（tǎn）：初生的芦苇，也叫荻，茎较细而中间充实，颜色青绿。此处以之比喻毳衣的青白色。\n尔：你。\n子：；指其所爱的男子。\n啍（tūn）啍：重滞徐缓的样子，犹“槛槛”。\n璊（mén）：红色美玉，此处喻红色车篷。一说赤苗的谷。\n奔：私奔。\n榖（gǔ）：生，活着。异室：两地分居。\n同穴：合葬同一个墓穴。\n予：我。\n有如皦（jiǎo）日：有此白日。如，此。皦，同“皎”，白，光明，明亮。', poem_tags = '诗经,爱情,故事' WHERE poem_title = '大车' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '钓鱼竹竿细又长，曾经垂钓淇水上。难道不把旧地想，路远无法归故乡。\n泉源汩汩流左边，淇水荡荡流右边。姑娘长大要出嫁，父母兄弟离得远。\n淇水荡荡流右边，泉源汩汩流左边。嫣然一笑皓齿露，身佩美玉赛天仙。\n淇水悠悠日夜流，桧木桨儿柏木舟。驾车出游四处逛，以解心里思乡愁。', poem_notes = '籊（tì）籊：长而尖削貌。\n尔思：想念你。尔，你。\n致：到。\n泉源：一说水名。即百泉，在卫之西北，而东南流入淇水。\n行：远嫁。\n瑳（cuō）：玉色洁白，这里指露齿巧笑状。\n傩（nuó）：通“娜”，婀娜。一说行动有节奏的样子。\n滺（yōu）：河水荡漾之状。\n楫（jí）：船桨。桧、松：木名。桧（guì），柏叶松身。\n驾言：本意是驾车，这里是操舟。言，语助词，相当“而”字。\n写（xiè）：通“泻”，宣泄，排解.', poem_appreciation = '此诗写一位远嫁的女子思乡怀亲的感情。全诗四章，内容都是远嫁女儿脑海中的形象活动。全诗从回忆与推想两个角度来写，可分两大部分，前后各两章，分别成一层意思。\n\n　　开头两章，是远嫁姑娘的回忆，都是关于婚前家乡与亲人的事。首章回忆当姑娘家时在淇水钓鱼的乐事：“籊籊竹竿，以钓于淇”，和伙伴们一起到淇水钓鱼游玩，这是多么惬意的事，不可能忘记。可惜眼下身在异乡，再也不能回淇水去钓鱼了，“岂不尔思，远莫致之”。次章回忆离别父母兄弟远嫁时的情形。泉水、淇水，逐渐远去；父母兄弟，逐渐远离。离别的场面和离别的情怀，最使人难忘。远嫁的女儿回忆起这个场景，思念之情不可抑止。第一章、第二章共八句，重点在回忆，强调的是思乡怀亲之情。\n\n　　第三、四两章是进一层意思：希企。眼下远嫁女儿已是人家的媳妇，故乡亲人都见不到。回忆激起的情怀，化作热情的企望：希望能有一天重归故乡。三四两章，便是想像回乡时的情景。淇水、泉水依然如故，“淇水在右，泉源在左”，与第二章两句一样，只是句子位置变化一下，实际上是用复沓的手法，表示重来旧地的意思。这时候，出嫁女已不再是姑娘家时持竹竿钓鱼那样天真了，而是“巧笑之瑳，佩玉之傩”，一副成熟少妇从容而喜悦的样子：故乡，我终于回来了！仿佛为了重新找回少女时代的感觉，这位少妇又到淇水。不过，这次不是钓鱼了，而是“桧楫松舟”，乘船游赏。不过，旧地重游，也不能排解远嫁多时的离愁。三四两章想像回乡的场景，正是远嫁归不得的少妇幻想的场景。想像得越真切越具体，现实中远离故乡不得归的思念之情就越强烈。所以，驾船游赏故乡的想像，根本不能解决思乡怀亲的愁思。', poem_tags = '诗经,思乡' WHERE poem_title = '竹竿' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '楚王派子虚出使齐国，齐王调遣境内所有的士卒，准备了众多的车马，与使者一同出外打猎。打猎完毕，子虚前去拜访乌有先生，并向他夸耀此事，恰巧无是公也在场。大家落座后，乌有先生向子虚问道：“今天打猎快乐吗？”子虚说：“快乐。”“猎物很多吧？”子虚回答道：“很少。”“既然如此，那么乐从何来？”子虚回答说：“我高兴的是齐王本想向我夸耀他的车马众多，而我却用楚王在云梦泽打猎的盛况来回答他。”乌有先生说道：“可以说出来听听吗？”\n\n　　子虚说：“可以。齐王指挥千辆兵车，选拔上万名骑手，到东海之滨打猎。士卒排满草泽，捕兽的罗网布满山岗，兽网罩住野兔，车轮辗死大鹿，射中麋鹿，抓住麟的小腿。车骑驰骋在海边的盐滩，宰杀禽兽的鲜血染红车轮。射中禽兽，猎获物很多，齐王便骄傲地夸耀自己的功劳。他回头看着我说：‘楚国也有供游玩打猎的平原广泽，可以使人这样富于乐趣吗？楚王游猎与我相比，谁更壮观？’我下车回答说：‘小臣我只不过是楚国一个见识鄙陋的人，但侥幸在楚宫中担任了十余年的侍卫，常随楚王出猎，猎场就在王宫的后苑，可以顺便观赏周围的景色，但还不能遍览全部盛况，又哪有足够的条件谈论远离王都的大泽盛景呢？’齐王说：‘虽然如此，还是请大略地谈谈你的所见所闻吧！’\n\n　　“我回答说：‘是，是。臣听说楚国有七个大泽，我曾经见过一个，其余的没见过。我所看到的这个，只是七个大泽中最小的一个，名叫云梦。云梦方圆九百里，其中有山。山势盘旋，迂回曲折，高耸险要，山峰峭拔，参差不齐；日月或被完全遮蔽，或者遮掩一半；群山错落，重叠无序，直上青云；山坡倾斜连绵，下连江河。那土壤里有朱砂、石青、赤土、白垩、雌黄、石灰、锡矿、碧玉、黄金、白银、种种色彩，光辉夺目，像龙鳞般地灿烂照耀。那里的石料有赤色的玉石、玫瑰宝石、琳、珉、琨珸、瑊玏、磨刀的黑石、半白半赤的石头、红地白文的石头。东面有蕙草的花圃，其中生长着杜衡、兰草、白芷、杜若、射干、芎䓖、菖蒲、茳蓠、蘼芜、甘蔗、芭蕉。南面有平原大泽，地势高低不平，倾斜绵延，低洼的土地，广阔平坦，沿着大江延伸，直到巫山为界。那高峻干燥的地方，生长着马蓝、形似燕麦的草、还有苞草、荔草、艾蒿、莎草及青薠。那低湿之地，生长着狗尾巴草、芦苇、东蔷、菰米、莲花、荷藕、葫芦、菴闾、莸草，众多麦木，生长在这里，数不胜数。西面则有奔涌的泉水、清澈的水池、水波激荡，后浪冲击前浪，滚滚向前；水面上开放着荷花与菱花，水面下隐伏着巨石和白沙。水中有神龟、蛟蛇、猪婆龙、玳瑁、鳖和鼋。北面则有山北的森林和巨大的树木：黄楩树、楠木、樟木、桂树、花椒树、木兰、黄蘖树、山梨树、赤茎柳、山楂树、黑枣树、桔树、柚子树、芳香远溢。那些树上有赤猿、猕猴、鹓鶵、孔雀、鸾鸟、善跳的猴子和射干。树下则有白虎、黑豹、蟃蜒、貙、豻、雌犀牛、大象、野犀牛、穷奇、獌狿。\n\n　　‘于是就派专诸之类的勇士，空手击杀这些野兽。楚王就驾御起被驯服的杂毛之马，乘坐着美玉雕饰的车，挥动着用鱼须作旒穗的曲柄旌旗，摇动缀着明月珍珠的旗帜。高举锋利的三刃戟，左手拿着雕有花纹的乌嗥名弓，右手拿着夏箙中的强劲之箭。伯乐做骖乘，纤阿当御者。车马缓慢行驶，尚未尽情驰骋时，就已踏倒了强健的猛兽。车轮辗压邛邛、践踏距虚，突击野马，轴头撞死騊駼，乘着千里马，箭射游荡之骐。楚王的车骑迅疾异常，有如惊雷滚动，好似狂飙袭来，像流星飞坠，若雷霆撞击。弓不虚发，箭箭都射裂禽兽的眼眶，或贯穿胸膛，直达腋下，使连着心脏的血管断裂。猎获的野兽，像雨点飞降般纷纷而落，覆盖了野草，遮蔽了大地。于是，楚王就停鞭徘徊，自由自在地缓步而行，浏览山北的森林，观赏壮士的暴怒，以及野兽的恐惧。拦截那疲倦的野兽，捕捉那精疲力竭的野兽，遍观群兽各种不同的姿态。\n\n　　‘于是，郑国漂亮的姑娘，肤色细嫩的美女，披着细缯细布制成的上衣，穿着麻布和白娟制做的裙子，装点着纤细的罗绮，身上垂挂着轻雾般的柔纱。裙幅褶绉重叠，纹理细密，线条婉曲多姿，好似深幽的溪谷。美女们穿着修长的衣服，裙幅飘扬，裙缘整齐美观；衣上的飘带，随风飞舞，燕尾形的衣端垂挂身间。体态婀娜多姿，走路时衣裙相磨，发出噏呷萃蔡的响声。飘动的衣裙饰带，摩磨着下边的兰花蕙草，拂拭着上面的羽饰车盖。头发上杂缀着翡翠的羽毛做为饰物，颌下缠绕着用玉装饰的帽缨。隐约缥缈，恍恍忽忽，就像神仙般的若有若无。\n\n　　‘于是楚王就和众多美女一起在蕙圃夜猎，从容而缓慢地走上坚固的水堤。用网捕取翡翠鸟，用箭射取锦鸡。射出带丝线的短小之箭，发射系着细丝绳的箭。射落了白天鹅，击中了野鹅。中箭的鸧鸹双双从天落，黑鹤身上被箭射穿。打猎疲倦之后，拨动游船，泛舟清池之中。划着画有鹢鸟的龙船，扬起桂木的船浆。张挂起画有翡翠鸟的帷幔，树起鸟毛装饰的伞盖。用网捞取玳瑁，钓取紫贝。敲打金鼓，吹起排箫。船夫唱起歌来，声调悲楚嘶哑，悦耳动听。鱼鳖为此惊骇，洪波因而沸腾。泉水涌起，与浪涛汇聚。众石相互撞击，发出硠硠礚礚的响声，就像雷霆轰鸣，声传几百里之外。\n\n　　‘夜猎将停，敲起灵鼓，点起火把。战车按行列行走，骑兵归队而行。队伍接续不断，整整齐齐，缓慢前进。于是，楚王就登上阳云之台，显示出泰然自若安然无事的神态，保持着安静怡适的心境。待用芍药调和的食物备齐之后，就献给楚王品尝。不像大王终日奔驰，不离车身，甚至切割肉块，也在轮间烤炙而吃，而自以为乐。我以为齐国恐怕不如楚国吧。’于是，齐王默默无言，无话回答我。”\n\n　　乌有先生说：“这话为什么说得如此过分呢？您不远千里前来赐惠齐国，齐王调遣境内的全部士卒，准备了众多的车马，同您外出打猎，是想同心协力猎获禽兽，使您感到快乐，怎能称作夸耀呢！询问楚国有无游猎的平原广泽，是希望听听楚国的政治教化与光辉的功业，以及先生的美言高论。现在先生不称颂楚王丰厚的德政，却畅谈云梦泽以为高论，大谈淫游纵乐之事，而且炫耀奢侈靡费，我私下以为您不应当这样做。如果真像您所说的那样，那本来算不上是楚国的美好之事。楚国若是有这些事，您把它说出来，这就是张扬国君的丑恶；如果楚国没有这些事，您却说有，这就有损于您的声誉，张扬国君的丑恶，损害自己的信誉，这两件事没有一样是可做的，而您却做了。这必将被齐国所轻视，而楚国的声誉也会受到牵累。况且齐国东临大海，南有琅琊山，在成山观赏美景，在之罘山狩猎，在渤海泛舟，在孟诸泽中游猎。东北与肃慎为邻，左边以汤谷为界限；秋天在青丘打猎，自由漫步在海外。像云梦这样的大泽，纵然吞下八九个，胸中也丝毫没有梗塞之感。至于那超凡卓异之物，各地特产，珍奇怪异的鸟兽，万物聚集，好像鱼鳞荟萃，充满其中，不可胜记，就是大禹也辨不清它们的名字，契也不能计算它们的数目。但是，齐王处在诸侯的地位，不敢陈说游猎和嬉戏的欢乐，苑囿的广大。先生又是被以贵宾之礼接待的客人，所以齐王没有回答您任何言辞，怎能说他无言以对呢！”', poem_notes = '1.子虚：与乌有先生都是赋中虚构的人物。《子虚赋》不同传本文字出入较大，这里是依李善注《文选》卷七。\n2.悉：全，皆。士：兵。备：齐全。田：通“畋”，打猎。\n3.过：拜访。奼：通“托“，夸耀。\n4.罘（fú）：捕兔的网。罔：捕鱼的网。弥（mí）：满。\n5.掩：覆盖、罩住。辚：用车轮辗压。\n6.麇：麇鹿。脚：本指动物的小腿，此用为动词，捉住小腿之意。麟：雄鹿，非指古人作为祥瑞之物的麟。\n7.骛：纵横奔驰。盐浦：海边盐滩。\n8.鲜：指鸟兽的生肉。染轮：血染车轮。此句言猎获之物甚多。\n9.矜：骄矜、夸耀。自功：自我夸功。\n10.何与：何如，比起来怎么样。\n11.鄙人：见识浅陋的人。\n12.唯唯：应答的声音。\n13.特：只。\n14.盘纡：迂回曲折。茀郁：山势曲折的样子。\n15.隆崇：高耸之状。嵂萃（lǜzú）：山势高峻险要的样子。\n16.岑崟（yín）：《方言》释为“峻貌”，即山势高峻的样子。参差：形容山岭高低不齐的样子。\n17.蔽：全遮住。亏：半缺。\n18.交错纠纷：形容山岭交错重叠，杂乱无序。\n19.干：接触。按：《文选》李善注引孔安国《尚书传》曰：“干，犯也。”\n20.罢（pí）池：山坡倾斜的样子。下文“陂陀”亦此意。\n21.属：连接。\n22.丹：朱砂。青：石青，可制染料。赭（zhě）：赤土。垩（è）：白土。\n23.雌黄：一种矿物名，即石黄，可制橙黄色染料。白坿：石灰。\n24.碧：青色的玉石。\n25.众色：指各种矿石闪现出的不同光彩。炫耀：光辉夺目的样子。\n26.照：照耀。烂：灿烂。这句说各种矿石光彩照耀，有如龙鳞般的灿烂辉煌。\n27.赤玉：赤色的玉石。玫瑰：一种紫色的宝石。\n28.琳瑉：一种比玉稍次的石。琨吾：同“琨珸”，即“琨”，《说文》：“琨，石之美者。”\n29.瑊玏（jiānlè）：次于玉的一种石名。玄厉：一种黑色的石头，可以磨刀。\n30.碝（ruǎn）石：一种次于玉的石头，“白者如冰，半有赤色”（见《文选》李善注）。娬玞：一种次于玉的美石，质地赤色而有白色斑纹。\n31.蕙圃：蕙草之园。蕙与兰皆为香草，外貌相似。蕙：比兰高，叶狭长，一茎可开花数朵；兰：一茎一花。\n32.衡：杜衡，香草名，“其状若葵，其臭如蘼芜。”（见《文选》李善注）兰：兰草。芷：白芷，或称“药”，香草名。若：杜若，香草名。\n33.芎藭：今通常叫作“川芎”，香草名，其根可以入药，有活血等作用。昌蒲：水草名，根可入药，气香。\n34.茳蓠（lí）：水生香草名。蘪（mí）芜：水生香草名，《文选》李善注引张揖曰：“似蛇床而香。”按：蛇床，其子入药，名蛇床子，可壮阳。\n35.诸柘：即甘蔗。巴苴（jū）：即芭蕉。\n36.登降：此言地势高低不平，或登上或降下。陁靡：山坡倾斜绵延的样子。\n37.案衍：地势低下。坛曼：地势平坦。\n38.缘：沿、循。大江：指长江。\n39.限：界限。巫山：指云梦泽中的阳台山，在今湖北境内，非为今四川巫山。\n40.高燥：高而干燥之地。葴：马蓝，草名。菥：一种像燕麦的草。苞：草名。按：即《左传》讲到的楚国的特产苞茅，可湑酒、编席织鞋等。荔：草名，其根可制刷。\n41.薛：蒿的一种。莎（suō）：一种蒿类植物名。青薠：一种形似莎而比莎大的植物名。\n42.卑：低。藏莨（zāngláng）：即狗尾巴草，也称狼尾草。\n43.东蔷：草名，状如蓬草，结实如葵子，可以吃。雕胡：即蒋，或称菰，俗称茭白。\n44.觚（gū）卢：《文选》李善注引张晏说即葫芦。\n45.菴（ān）闾：蒿类植物名，子可入药。轩于：即莸（yóu）草，一种生于水中或湿地里的草。\n46.众物：指众多的草木。居：此指生长。\n47.图：计算。\n48.涌泉：奔涌的泉水。推移：浪涛翻滚向前。\n49.外：指池水表面之上。发：开放。芙蓉：即荷花。菱华：即菱花，开小白花。\n50.内：指池水下面。隐：藏。\n51.中：指池水中。蛟：古代传说中能发水的一种龙。鼍（tuó）：即今之扬子鳄，俗名猪婆龙。\n52.瑇瑁：玳瑁，龟类动物，其有花纹的甲壳可做装饰品。鼋：大鳖。\n53.阴林：背阳面的树林。\n54.楩（pián）：树名，即黄楩木。柟（nán）：树名，即楠木，树质甚佳。豫章：树名，即樟木。\n55.椒：花椒树。木兰：树名，高大乔木，开白花。\n56.蘖（bò）：即黄蘖树。其高数丈，其皮外白里黄，入药清热燥湿。离：通“樆（lí）”，即山梨树。朱杨：生于水边的树名，即赤茎柳。\n57.樝（zhā）梨：即山楂。梬（yǐng）栗：梬枣，似柿而小。\n58.橘柚：芸香科植物，俗称橘子、柚子。\n59.鹓雏（yuānchú）：凤凰。孔：孔雀。鸾：鸾鸟，传说中似凤凰的鸟名。\n60.腾远：疑为“腾猿”之误字，猿善腾跃。射（yè）干：似狐而小的动物，能上树。\n61.蟃蜒：应作“獌狿”，一种似狸的大兽。貙豻（qūhàn）：一种似狸而大的猛兽。\n62.剸诸：即专诸，春秋时代的吴国勇士，曾替吴公子光刺杀吴王僚。此指像剸诸一样的勇士。伦：类。\n63.格：击杀。\n64.驯：被驯服。驳：毛色不纯的马。驷（sì）：古代四匹马驾一车称驷，此泛指马。\n65.雕玉之舆：用雕刻的玉石装饰的车，言车之高贵。\n66.靡：通“麾”，挥动。鱼须：海中大鱼之须，用来做旗子的穗饰。桡旃（náozhān）：曲柄的旗。\n67.曳：摇动。明月之珠旗：画有明月装饰有珠子的旗。\n68.建：举起。干将：本为春秋时代吴国的著名制剑工匠，此指利刃。雄戟：有刃的戟。\n69.乌号：古代良弓名，相传为黄帝所用。雕弓：雕刻花纹的弓。\n70.夏服：通“夏箙（fú）”，盛箭的袋子。相传善射的夏后羿有良弓繁弱，还有良箭，装在箭袋之中，此箭袋即称夏服。\n71.阳子：即孙阳，字伯乐，秦穆公之臣，以善相马著称。骖乘：陪乘的人。古时乘车，驾车者居中，尊者居左，右边一人陪乘，以御意外，称骖乘。\n72.纤阿（ē）：传说是为月神驾车的仙女，后人泛称善驾车者为纤阿。\n73.案节：马走得缓慢而有节奏。此言马未急行。未舒：指马足尚未尽情奔驰。\n74.陵：侵凌，此指践踏。狡兽：强健的猛兽。按《广雅》：“狡，健也。”\n75.蹴：践踏。蛩蛩（qióng）：传说中的怪兽，其状如马，善奔驰。\n76.辚：用车轮辗压。距虚：一种善于奔走的野兽名，其状如驴。\n77.轶：超过。轊（wèi）：车轴顶端。这里是以 撞击之意。騊駼（táotú）：北方野马名；一说即野马。\n78.遗风：千里马名。骐：野兽名，似马。\n79.倏眒（shūshēn）：迅速的样子。倏，通“跾（shū）”，疾速。倩浰（lì）：迅疾的样子。\n80.雷动：像惊雷那样震动。猋（biāo）：即飙风，迅疾的大风。\n81.星流：流星飞坠。霆：疾雷。\n82.决：射裂。眦（zì）：眼眶。\n83.洞：洞穿。掖：同“腋”。\n84.绝：断裂。心系：连接心脏的组织。\n85.雨（yù）：下雨。这里指把猎物丢下来像落雨一样，夸耀多。揜（yǎn）：掩盖。\n86.弭节：停鞭缓行。\n87.徼（jiǎo）：拦截。郄（jù）：极度疲倦。诎：穷尽，指精疲力竭。\n88.殚（dān）：尽。\n89.郑女：古代郑国多美女。曼姬：美女。曼，皮肤细腻柔美。\n90.被：通“披”。此指穿衣。阿：轻细的丝织品。緆（xì）：细布。\n91.揄：牵曳。紵：麻布。缟：白绸布。\n92.纤罗：纤细的有花纹的丝绸。按：凡言纤言细都是指的丝绸质量好，质量好才做得到轻薄。\n93.雾縠（hú）：轻柔的细纱。\n94.襞bì积：形容女子腰间裙褶重重叠叠。褰（qiān）绉：褶皱。\n95.郁桡：深曲的样子。\n96.衯（fēn）衯裶（fēi）裶：衣服长长的样子。\n97.扬：抬起。袘（yì）：裙子下端边缘。戌削：形容裙缘整齐的样子。\n98.蜚：通“飞”。纤：妇女上衣上的飘带。髾（shāo）：本指妇女燕尾形的发髻，此指衣服的燕尾形的下端。\n99.扶与猗靡：形容衣服合身，体态婀娜的样子。\n100.噏呷（xīxiá）、萃蔡：皆为人走路时衣服摩擦所发出的响声的象声词。\n101.摩：摩擦。\n102.拂：拂拭。羽盖：插饰羽毛的车盖。\n103.错：间杂。翡、翠：皆为鸟名，前者羽毛红色，后者羽毛绿色。威蕤（ruí）：指作装饰的羽毛发亮。按：威蕤，同“葳（wēi）蕤”，也作“萎蕤”，就是植物玉竹，玉竹因为叶面有光泽，晶莹可爱，所以也用来指有光泽的东西。\n104.缪绕：缭绕。玉绥：用玉装饰的帽带。\n105.眇眇：缥缈。忽忽：飘忽不定的样子。\n106.仿佛：似有似无。\n107.獠：夜间打猎。\n108.媻姗：同“蹒跚”，走路缓慢的样子。郣窣（bósū）：缓缓前行的样子。金堤：堤名，堤同“堤”。\n109.鵕鸃（jùnyí）：锦鸡，野鸡一类。\n110.孅：同“纤”。缴（zhuó）：系在射鸟的箭上的绳线。施：射出。\n111.弋（yì）：用带丝线的箭射飞禽。白鹄：白天鹅。连：牵连。此指用带丝线的箭射中驾鹅。鴐（jiā）鹅：野鹅。\n112.鸧（cāng）：鸟名，即鸧鸹（guā），形似雁，黑色。玄鹤：黑鹅。加：箭加其身，即射中之意。\n113.怠：疲倦。发：指开船。游：泛舟。清池：指云梦西边的涌泉清池。\n114.浮：漂浮。文：花纹。鹢（yì）：水鸟名，此指船头绘有鹢的图案的画船。扬：举起。旌：旗。栧（yì）：船浆。\n115.张：挂起。翠帷：画有翡翠鸟图案的帷帐。建：树起。羽盖：用鸟毛装饰的伞盖。\n116.罔：通“网”，用网捕取。\n117.摐（chuāng）：撞击。金鼓：形如铜锣的古乐器，即钲。籁：管乐器，即排箫。\n118.榜人：划船的人。按：“榜人”即“舫人”，《说文》：“舫人，习水者。”流喝：声音悲凉嘶哑。\n119.水虫：指水中的鱼虾之类。鸿：洪大。沸：指波涛翻滚。\n120.奔扬：指波涛。会：汇合。\n121.礧（léi）：通“磊”。\n122.硠（láng）硠、礚（kē）礚：皆为水石相撞击的声音。\n123.灵鼓：神鼓。\n124.起：点燃。烽燧：烽火。\n125.行：行列。就队：归队。\n126.纚（xǐ）：接续不断的样子。淫淫：渐进的样子。指队伍缓缓前行。\n127.班（pán）乎：犹“班然”，依次相连的样子。裔裔：络绎不绝地向前行进的样子。\n128.云阳之台：楚国台榭之名，在云梦南部的巫山下。\n129.怕：通“泊”，安静无为的样子。按：《文选》李善注引《说文》：“怕，无为也。”说明《子虚赋》用的是怕的本义。\n130.澹乎：憺泊，安静无为的样子。\n131.勺药：即芍药。和：调和。具：通“俱”，齐备。御：用。\n132.脟（luán）：通“脔”，把肉切成小块。焠（cùi）：用火烤。按：轮焠，转着烤。\n133.殆：恐怕。\n134.贶：惠赐。\n135.勠力：齐心合力。致获：获得禽兽。\n136.风：风范。烈：功业。\n137.显：彰显。\n138.害：损害，减少。信：诚信。\n139.轻：受人轻视。累：受人牵累。\n140.陼（zhǔ）：水边，此处用作动词。钜：巨。\n141.琅邪（yé）：或写作“琅琊”，山名，在今山东诸城东南海边。\n142.成山：山名，在今山东荣城东北。\n143.之罘：也作“芝罘”，在今山东烟台市。\n144.浮：行船。勃澥：也作“渤澥”，即今之渤海。\n145.孟诸：古代大泽名，在今河南商丘市东北，已淤塞消失。\n146.邪：同“斜”，指侧翼方向。肃慎：古代国名，在今东北三省境内。\n147.右：《文选》李善注以为此“右”字当是“左”字之误。按：李善注应是正确的，今出土汉代地图，好几种都是上南下北，自然也就是左东右西了；《子虚赋》的姊妹篇《上林赋》也说“左苍梧，右西极”，明左东右西。汤谷：或写作“晹谷”，神话传说中太阳升起的地方。\n148.青丘：国名，相传在大海之东三百里。\n149.曾：竟。蒂芥：指极小的东西。\n150.俶傥：通“倜傥”，卓越非凡。瑰伟：奇伟，卓异。\n151.异方：不同地区。殊类：别样物类。\n152.鳞崒：像鱼鳞般地聚集在一起。崒：同“萃”，会聚。牣：满。充牣：充满。\n153.名：叫出名字来。\n154.卨（xiè）：古“契（xiè）”字，应是指的商代的始祖契，传说做过舜臣，时代上正好在禹之后。\n155.见客：被当做客人对待。\n156.王辞不复：齐王没有回话。这两句的意思是齐王没有回话，不是没有话回。', poem_appreciation = '《子虚赋》八个自然段，可分为三部分。前三段写云梦泽的地理风貌和自然富有，中间四段写楚王游猎云梦之乐，最后一段写乌有先生对子虚的批判，归结讽谏主题。前两个部分列述奢侈淫游的种种表现，后一部分揭示淫逸奢侈的危害。\n\n　　此赋对人物的设定及所表现的感情的特质方面，同此前的作品相比，有明显的不同。在屈原的《离骚》和《九章》中，作者都是直接抒情，贾谊的《吊屈原赋》也基本如此。宋玉的《高唐赋》和《神女赋》通过假设问对的方式展开，作品中出现楚王和宋玉两个人物。枚乘的《七发》假托于楚太子与吴客，作品所要表达的思想感情通过假设的人物实现，而其情感特征仍属于个体的性质，即作品中的“宋玉”、“吴客”个人的认识或感受。子虚、乌有的对话则不然。这里固然是两个单体的人在谈话，但这两个人物所承载的身份、意义却已不同。子虚以使臣的角色出现，其所陈述的内容，所表达的感受，既是他个人的，同时也与他使臣的身份、使命有直接的关系。他的荣辱之感已同楚国的荣辱紧密联系在一起。作品中的乌有先生是齐人。虽然他没有维护齐或代表齐之利益的使命、职责，但谈话间却无不为齐争辩。他在夸耀齐之广大以后说：“然齐在诸侯之位，不敢言游戏之乐，苑囿之大，先生又见客，是以王辞不复。何为无以应哉？”这就不是以朋友的或个人的口吻谈话，而是在批评子虚的同时，也于言谈间维护齐的威望。作品中的人物已不是单体的个人，他们承载起了群体的感受与意识。这一变化对《两都赋》和《二京赋》的人物设定都有深刻的影响。\n\n　　同时，作品内容的展开和人物对话中的冲突，更深刻地展现出不同时代、不同人群间的思想冲突，通过子虚、乌有二人的对话，表现出两种不同的使命意识。\n\n　　作品开篇便揭示子虚的身份：他是楚的使臣，出使于齐，受到齐王的热情接待：“悉发境内之士，备车骑之众，与使者出田。”畋猎毕，子虚“过诧乌有先生”。二人思想观念的差异也随之展开。《史记集解》引郭璞曰：“诧，夸也。”子虚拜访乌有先生，本出于炫耀的动机，此后，其所谈的内容与这一动机正相合。\n\n　　在诸侯分立的时代，诸侯交际、聘问的历史上确实存在各式各样的明争暗斗，使臣与出使国君臣彬彬有礼的交往中存在着对荣誉、利益的挑战和维护。同时，使臣是否受到尊重及在何等程度上的尊重，则是两个诸侯国间关系的直接表现。晋赵孟出聘郑，受到特殊的礼遇，不取决于晋郑的友好，而在于郑对晋的依附，在于赵孟执掌晋之政柄，加之以他个人的君子风范和人格魅力。\n\n　　与之相反的，则是诸侯与使臣交往中一些隐藏在温文尔雅外衣下的明争暗斗。\n\n　　前代诸侯间的争斗与不快，正是子虚在出使中显得极为敏感的原因。在《子虚赋》中，大国诸侯恃强凌弱，妄自尊大的强国心理，对使臣的使命意识构成威胁。使于四方，不辱君命，这是古代使臣普遍遵循的基本原则。而不辱君命可以有各种不同的情况和形式，特别是大国之间，既要完成出使任务，还要在应对间，宣扬国之长或优势，显示其国力，扬威诸侯。这是贯穿于子虚滔滔宏论中的潜台词，也是构成《子虚赋》中第一个波澜的主色调。\n\n　　乌有先生对子虚的回答中不免有为尊者讳，有维护齐之威望的嫌疑。他认为，齐王“悉发境内之士”的畋猎，完全是出于对使臣的热情，“以娱左右也，何名为夸哉！”否定齐王有炫耀之意。至于说询问楚的情况，在他看来，也是极其友好的表示：“问楚地之有无者，愿闻大国之风烈，先生之余论也。”都是出于好意。反倒是子虚过于敏感，将友好的接待误解为比权量力的明争暗斗。乌有先生进而指出，子虚的谈话使自己陷入两难的境地：“有而言之，是章君之恶；无而言之，是害足下之信。章君恶而伤私义，二者无一可。”如果他所说属实，那就玷污了使臣的使命，不仅没能张显楚王的德，反而暴露了楚王贪图淫乐奢侈的缺点。如果他仅仅出于虚荣心而说了谎话，则表明他缺乏诚信，人品操守有亏，作为使臣来说，也是不称职的。\n\n　　孔子云：“行己有耻，使于四方，不辱君命，可谓士矣。”乌有的言论中不曾涉及前代文献记载，然而，在作者运用的文学语言中已经浸透了前代思想滋养。他们二人之间的言论中表现出两种不同的使臣意识，表现出对国家之美的两种不同理解。他们的言论中也表现出两个文学人物间的差异：子虚是一个徒逞一时之快的思想浅薄的人。乌有先生则是诸侯对立时期的贤士的形象。两个形象的差异和他们言论的交锋构成了《子虚赋》中文脉的波澜。', poem_tags = '讽谏' WHERE poem_title = '子虚赋' AND poem_author = '司马相如';
UPDATE edu_poem SET poem_translation = '冰雪融尽，入侵的胡兵已经悄然返还。月光皎洁，悠扬的笛声回荡在戍楼间。\n试问饱含离情的《梅花曲》飘向何处？它仿佛像梅花一样随风落满了关山。', poem_notes = '塞上：指凉州（今甘肃武威）一带边塞。此诗题一作《塞上闻笛》，又作《和王七玉门关听吹笛》。\n雪净：冰雪消融。\n胡天：指西北边塞地区。胡是古代对西北部民族的称呼。\n牧马：放马。西北部民族以放牧为生。牧马还：牧马归来。一说指敌人被击退。\n羌（qiāng）笛：羌族管乐器。\n戍楼：报警的烽火楼。\n梅花何处落：此句一语双关，既指想象中的梅花，又指笛曲《梅花落》。《梅花落》属于汉乐府横吹曲，善述离情，这里将曲调《梅花落》拆用，嵌入“何处”两字，从而构思成一种虚景。\n关山：这里泛指关隘山岭。', poem_tags = '边塞,生活' WHERE poem_title = '塞上听吹笛' AND poem_author = '高适';
UPDATE edu_poem SET poem_translation = '（背景接前面的《寺人披见文公》）晋文公赏赐跟着他逃亡的人们，介之推不去要求禄赏，而（晋文公）赐禄赏时也没有考虑到他。\n　　介之推说：“献公的儿子有九个，现在惟独国君还在（人世）。惠公、怀公没有亲信，（国）内外都抛弃他们。天没有（打算）灭绝晋，（所以）必定会有君主。主持晋国祭祀的人，不是君王又是谁呢？上天实际已经安排好了的，而跟随文公逃亡的人却认为是自己的贡献，（这）不是欺骗吗？偷窃别人的钱财，都说是盗窃。更何况贪图天的功劳，将其作为自己的贡献呢？下面的（臣子）将罪当做道义，上面的（国君）对（这）奸诈（的人）给予赏赐。上下互相欺瞒，难以和他们相处啊。”\n　　他的母亲说：“你为什么不也去要求赏赐呢？（否则）这样（贫穷地）死去（又能去）埋怨谁呢？”\n　　回答说：“（既然）斥责这种行为是罪过而又效仿它，罪更重啊！况且说出埋怨的话了，（以后）不应吃他的俸禄了。”\n　　他的母亲说：“也让国君知道这事，好吗？”\n　　回答说：“言语，是身体的装饰。身体将要隐居了，还要装饰它吗？这样是乞求显贵啊。”\n　　他的母亲说：“（你）能够这样做吗？（那么我）和你一起隐居。”便（一直）隐居到死去。\n　　晋文公没有找到他，便用绵上作为他的祭田。说：“用它来记下我的过失，并且表彰善良的人。”', poem_notes = '晋侯：指晋文公，即重耳。他逃亡在外，在秦国的帮助下回晋继承君位。\n赏：赐有功也。\n从亡者：从文公出亡在外之臣，如狐偃、赵衰之属。\n介之推：亦从亡之臣。晋文公臣子，曾割自己腿上的肉以食文公。\n献公：重耳之父晋献公。\n惠、怀：惠公，怀公。惠公是文公重耳的弟弟，是怀公的父亲。\n置：立。\n二三子：相当于“那几个人”，指跟随文公逃亡诸臣。子是对人的美称。\n诬：欺骗。\n下义其罪：义，善也。言贪天之功，在人为犯法，而下反以为善也。\n上赏其奸：奸，伪也。言贪天之功在国为伪，而上反以此赐也。\n蒙：欺骗。\n盍：何不。\n怼（duì）：怨恨。\n尤：罪过。\n文：花纹，装饰。言人之有言，所以文饰其身。\n绵上：地名，在今山西介休县南、沁源县西北的介山之下。\n田：祭田。\n志：记载。\n旌：表彰。', poem_appreciation = '点评 　　介之推偕母归隐的动机和心理是通过对话来表现的。介之推认为晋文公能够重登九五之位，是天命的体现，“二三子”据天功为己有，是贪的表现，无异于犯罪。而晋文公不以此为“奸”，还理所当然地给予赏赐，这就成了上下蒙蔽，他是不屑于效仿的。母亲和介之推有两次对话。第一次是试探性的建议：“何不自己也去求得赏赐呢？否则，就这样默默地死去又能怨谁？”遭到介之推的拒绝，认为自己已经知道“二三子”所做的不正确还去效仿，罪过更大。而且已经说了晋文公的坏话，就不能再领取他的俸禄。母亲再问说：就算不要赏赐，那么让他知道你有功怎么样呢？介之推又拒绝说，既然都要隐居了，又何必还要这样的名声呢？母亲明白了介之推的意志是坚定的，就表示要和儿子一起隐居。这一段对话写得十分巧妙，既细致入微地剖析了介之推的心理，又不流于枯燥说理：介之推藐视富贵、正气凛然和母亲不动声色、旁敲侧击，都一一跃然纸上。 ▲', poem_tags = '古文观止,写人,历史,故事' WHERE poem_title = '介之推不言禄' AND poem_author = '左丘明';
UPDATE edu_poem SET poem_translation = '有一匹胡马，被远放在燕支山下。它在沙地上、雪地上来回地用蹄子刨，独自嘶鸣着，它停下来东张张，西望望，发现自己迷路了。而此刻，辽阔的大草原茫茫无边，天色将晚。', poem_notes = '胡：古代对北方和西方各族的泛称。\n燕支山：在今甘肃省张掖市山丹县境内。\n跑：同“刨”。 \n嘶：马叫声。', poem_appreciation = '这首小令运用象征的手法，表现离乡远戍的士卒的孤独和惆怅。作者以清晰的线条，单纯的色调，描绘了边地辽阔的草原风光，和徬徨在这奇异雄壮的大自然中的胡马的形象。语言浅直而意蕴深曲。燕支山，即焉支山，位于甘肃省永昌县西，古长城附近。唐代此地与东突厥接壤，是边境。这是此词所涉及的地理环境。从词中首先可看到燕支山下的四季风光。春，风沙扑面；冬，大雪盖地；夏，绿草如茵；秋，天高云淡。胡马就活动在这样的背景中。作者描写了一天中马的生活，它是在与风雪搏斗和期望中度过的。词的末句摄下的是，在桔黄的浑圆的落日渐渐沉没到地平线下，暮蔼笼罩大地那最易引起乡思离愁的时刻，胡马在天边的草原上的孤寂形象。仿佛它在为岁月有限与草原无限的对比而怅惘。在对景物的描写中处处交织着胡马的情绪。\n\n　　词作写了边地风光而并非主旨。在对马的拟人化的描写中，揭示了它的象征意义。“远放燕支山下”，“放”字已说明胡马非野马。“放”前着一“远”字，令人遐想。“远放”既给人以辽远的空间感，又使人见出“胡马”并非胡地之马，而是被远远地放到接近胡地的马。这时已使人感到马的象征性。但从进一步的描写中，象征意义就明显得不容置疑了。一般说来，放马时间是在夏天水草肥美，没有战事或农闲的时候，目的是节省草料，并使马吃到鲜草而肥壮。而“跑沙跑雪独嘶，东望西望路迷”，又写这匹马在风沙中、在大雪中迷失道路，不停地奔波，孤独地嘶鸣，惶惑不安地四处张望，寻找着、呼唤着伴侣。仔细揣摩，就会发现其中有两点矛盾：一，“放”马不会在风雪中；二，既然“放”马，马必有主人，不会迷路。产生这些矛盾不能归结于艺术高于生活，是因为作者把马当作人来写。如果将马看作是戍卒的象征，就合情合理了。“迷路”是戍卒的感觉，与“何处是归程？长亭更短亭”意近，而春秋代序，年复一年，在塞外无边风沙中长期戍守正是戍边战士的生活。\n\n　　此词用准确精炼的词语，含蓄曲折地表现了马的情绪，即戍边战士的情思。“远放”、“独嘶”、“无穷”这三个词都有一定的相对性，远对近，独对偶，无穷对有尽。正是这种相对性的张力表现了戍卒在此种情境中对彼种情境的向往。即戍卒从内地被遣放到边疆的感受、征戍生活的艰苦和思亲盼归的心绪。轻松的笔调表现深刻的主题，平浅的语言有着丰富的内涵，淡笔勾勒的画面浸润着浓郁的感情。', poem_tags = '豪放,写马,寓人,孤独' WHERE poem_title = '调笑令·胡马' AND poem_author = '韦应物';
UPDATE edu_poem SET poem_translation = '腰上佩带的羽箭已长期凋零，只叹未到燕然山刻石记功名。\n想老夫我尚能横越那大沙漠，诸位何至于新亭落泪空悲鸣。\n我虽有万死不辞的报国之志，却无奈双鬓斑白不能再转青。\n应牢牢记住常年江湖泊船处，卧闻寒州上新雁到来的叫声。', poem_notes = '1.夜泊水村：夜间把船停泊在临水的村庄旁。\n2.羽箭：箭尾插羽毛，称羽箭。\n3.太息：叹气。燕然：山名，在今蒙古人民共和国境内。勒铭：刻上铭文。东汉和帝永元元年（公元89年），车骑将军窦宪大败匈奴，追击单于至燕然山，班固写了一篇铭文，把铭文刻写在巨石上，记载这次成功。此句作者借喻自己未能建立战功。\n4.老子：陆游自称，犹言老夫。《晋书》：“老子于此处兴复不浅。”大漠：古瀚海，亦称大碛。在蒙古国与我国内蒙古之间，西接新疆，四月间狂飙屡起，沙砾飞扬，故号为流沙。绝大漠：横度大沙漠。绝，横度，跨越。\n5.新亭：又名劳劳亭，在今南京市南。东晋时中原沦陷，王室南渡，有一些过江的士大夫在新亭宴饮，席间众人闷闷不乐，相对涕泣。独有王导不以为然，说：“当共戮力王室，克复神州，何至作楚囚相对耶？“见《晋书·王导传》。\n6.“一身“句：意谓自己有不怕死万次的报国决心。\n7.青：黑色。再：第二次。\n8.记取：记住，记着。\n9.新雁：刚从北方飞来的雁。汀：水边平地，小洲。', poem_appreciation = '此诗写出作者虽怀报国壮志而白发催人的悲愤。古今诗人感叹岁月不居、人生易老者颇多，但大都从个人遭际出发，境界不高。陆游则不同。他感叹双鬓斑白、不能再青为的是报国之志未酬。因而其悲哀就含有深广的内容，具有崇高壮烈的色彩。此联为“流水对”但其后关连，不是互为因果，而是形成矛盾。读者正是从强烈的矛盾中感到内容的深刻，产生对诗人的崇敬。陆游类似的诗句尚有“塞上长城空自许，镜中衰鬓已先斑”等。\n\n　　这是一首七言律诗，作于山阴奉祠，时作者已家居九年。 山阴是江南水乡，作者常乘小舟出游近村的山水，夜泊水村为即景之作。首联写退居乡野、久离疆场、无缘抗敌的落寞怅惘。“羽箭久凋零”，足见其闲居的郁闷。“燕然未勒铭”，典出《后汉书·窦宪传》：窦宪北伐匈奴，追逐单于，登燕然山（即今蒙古杭爱山），刻石纪功而还。燕然未勒，意谓虏敌未灭，大功未成。这一联用层递手法，“久凋零”，乃言被弃置已久，本就失落、抑郁；“未勒名”，是说壮志难酬，则更愤懑不平。起首就奠定了一种失意、悲愁的感情基调。\n\n　　颔联抒发了“烈士暮年，壮心不已”的志愿，表达了对那些面临外寇侵凌却不抵抗、无作为的达官贵人的指斥。上句是说大丈夫在神州陆沉之际，本应“捐躯赴国难，誓死忽如归”才对，怎么可以安然老死呢？一个“犹”字道出他不甘示弱的心态。“绝大漠”，典出《汉书·卫将军骠骑列传》，是汉武帝表彰霍去病之语。两鬓萧萧，仍然豪气干云，朝思梦想着驰骋大漠、浴血沙场；这就反照出朝廷中的那些面对强虏只知俯首称臣割地求和而不思奋起抵争的文官武将的奴相。（另一说是取老子（李耳）骑青牛出关，绝于大漠之中而悟道的传说）“诸君何至泣新亭”，典出《世说新语·言语》：“过江诸人，每至美日，辄相邀新亭，藉卉饮宴。周侯中坐而叹：‘风景不殊，正有山河之异！’皆相视流泪。唯王丞相愀然变色曰：‘当共同戮力王室，克服神州，何至作楚囚相对！’作者借此典，表达了他对那些高居庙堂的衮衮诸公在国家山河破碎之际要么醉生梦死，要么束手垂泪的懦弱昏庸的精神面貌的不满。\n\n　　颈联以工稳的对仗，揭示了岁月蹉跎与夙愿难偿的矛盾。“一身报国有万死”，尽管个人的力量是渺小的，尽管生命是短暂的，但是为了拯救国难，“我”却甘愿死一万次。“一”与“万”的强烈的对比，鲜明地表达了自己的拳拳爱国心与殷殷报国情，诚可谓掷地有声。“双鬓向人无再青”，这一句是说，岁月不饶人，满鬓飞霜，无法重获青黑之色，抒发了对华年空掷、青春难再的感伤与悲愤。即便我抱定了“为国牺牲敢惜身”的志向，可是又谁能了解我的苦心我的喟叹呢？这两句直抒胸臆，是全诗之眼。\n\n　　尾联点破诗歌题面，回笔写眼前自己闲泊水村的寂寥景象。你想，一个老翁，处江湖之远，眼看着干戈寥落了，铁马逝去了，战鼓静灭了，大宋江山是任人宰割了，他的心怎不会如刀割一般的苦痛！“夜阑卧听风吹雨，铁马冰河入梦来”，可是梦醒之后呢，所看到的是荒寒的汀州上寻寻觅觅的新雁，哪里有可以安栖的居所！这怎不教人潸然落泪呢？这两句是借象表意，间接抒情。\n\n　　全诗以夜泊水村所见的景象而写怀遣闷，而落笔却跳转到报国之志上，寄慨遥深。“壮士凄凉闲处老”（陆游《病起》），有心报国却无路请缨，理想与现实的深刻矛盾，这是这首诗慷慨悲歌的一个根本原因。用典贴切，出语自然，感情充沛，“浑灏流转”（赵翼 语），使本诗在悲歌中又显出沉雄的气象。', poem_tags = '爱国,壮志,感叹,岁月' WHERE poem_title = '夜泊水村' AND poem_author = '陆游';
UPDATE edu_poem SET poem_tags = '悼亡,怀念,感伤' WHERE poem_title = '南乡子·为亡妇题照' AND poem_author = '纳兰性德';
UPDATE edu_poem SET poem_translation = '人生是活不到百岁的，就算活到又如何？\n古往今来的英雄壮士，现在都化为尘土洒落在江河之中。', poem_notes = '①复：又。\n②山河：山曲。指坟墓所在。', poem_tags = '人生,感慨' WHERE poem_title = '绝句·人生无百岁' AND poem_author = '刘基';
UPDATE edu_poem SET poem_translation = '重峦叠嶂向西奔驰，像千万匹马回旋一般，这许多的山要掉头向东而去。恰好湍急的水流直直地落下，进跳的水珠四处溅下；小桥横架在急流之上，像不圆的月亮和刚拉开的弓。人老了应当过闲散的日子，可老天给我多事，来掌管十万棵高大的松树。我的房舍小，但在松树盘曲的枝干影子的外边，在风风雨雨的声音中间。\n雨雾消散，重峦叠嶂露出面容，争着和人见面。看早晨清新凉爽的空气从一座座山峰扑面而来。座座山峰好像谢家子弟，衣着潇洒，长相英俊；又好像司马相如的车骑一般雍容华贵。我感觉这其中，有的如司马迁的文章一样，雄浑深沉，典雅劲健。在刚刚修好的偃湖堤的路上，问偃湖哪一天能够展现烟水的美好景色？', poem_notes = '大约作于庆元二年（1196），时稼轩罢居带湖。灵山：位于江西上饶境内。古人有“九华五老虚揽胜，不及灵山秀色多”之说，足见其雄伟秀美之姿。齐庵：当在灵山，疑即词中之“吾庐”，为稼轩游山小憩之处。偃湖：新筑之湖，时未竣工。\n惊湍（tuān）：急流，此指山上的飞泉瀑布。\n跳珠：飞泉直泻时溅起的水珠。\n缺月初弓：形容横截水面的小桥像一弯弓形的新月。\n合：应该。\n投闲：指离开官场，过闲散的生活。\n检校：巡查、管理。长身：高大。\n龙蛇影：松树影。\n爽气朝来：朝来群峰送爽，沁人心脾。\n磊落：仪态俊伟而落落大方。\n雄深雅健：指雄放、深邃、高雅、刚健的文章风格。\n太史公：司马迁，字子长，西汉著名的史学家和文学家，曾继父职，任太史令，自称太史公。', poem_appreciation = '读辛弃疾这位大词人的山水词，就会发现他多么热爱祖国的山山水水，有时似乎已经进入一种“神与物游”的境界，他笔下的山水似乎和人一样，有思想，有个性，有灵气，流连其间，言感身受，别有新的天地。这首《沁园春》便有这种特色。\n\n　　头三句写灵山群峰，是远景。再写近景：“正惊湍直下，跳珠倒溅；小桥横截，缺月初弓。”这里有飞瀑直泻而下，倒溅起晶莹的水珠，如万斛明珠弹跳反射。还有一弯新月般的小桥，横跨在那清澈湍急的溪流上。词人犹如一位高明的画师，在莽莽苍苍丛山叠嶂的壮阔画面上，重抹了几笔韶秀温馨的情韵。\n\n　　连绵不断的茂密森林，是这里的又一景色。辛弃疾在一首《归朝欢》词序中说：“灵山齐庵菖蒲港，皆长松茂林。”所以词人接着写道：“老合投闲，天教多事，检校长身十万松。”辛弃疾面对这无边无垠的高大、葱郁的松树林，不由浮想联翩：这些长得高峻的松树，多么像英勇善战，所向无敌的战士。想自己“壮岁旌旗拥万夫”，何等英雄，而今人老了，该当过闲散的生活，可是老天爷不放他闲着，又要他来统率这支十万长松大军呢！诙谐的笑语抑或是乐？抑或是苦？抑或是自我解嘲？有一种说不出的滋味儿。内心深处确实隐隐有一份报国无门的孤愤在。\n\n　　在这种地方，词人轻轻点到即止，顺势落到自己山中结庐的事上来。齐庵，是辛弃疾在灵山修建的一所茅庐。他说，这房子选的地点还是不错的，“在龙蛇影外，风雨声中。”每当皓月当空，可以看到状如龙蛇般盘屈的松影，又可以听到声如风雨的万壑松涛，别有一番情趣啊！\n\n　　上片写灵山总体环境之美，下片则是词人抒写自己处于大自然中的感受了。辛弃疾处于这占尽风光的齐庵中，举目四望，无边的青山千姿百态。拂晓，在清新的空气中迎接曙光，东方的几座山峰，像天真活泼的孩子，一个接着一个从晓雾中探出头来，争相同他见面，向他问好。红日升起了，山色清明，更是气象万千。看那边一座山峰拔地而起，峻拔而潇洒，充满灵秀之气。它那美少年的翩翩风度，不就像芝兰玉树般的东晋谢家子弟吗？再看那座巍峨壮观的大山，苍松掩映，奇石峥嵘，它那高贵亮丽的仪态，不就像司马相如赴临邛时那种车骑相随、华贵雍容的气派么！词人惊叹：大自然的美是掬之不尽的，置身于这千峰竞秀的大地，仿佛觉得此中给人的是雄浑、深厚、高雅、刚健等诸种美的感受，好像在读一篇篇太史公的好文章，给人以丰富的精神享受。此中乐，乐无穷啊！在作者心目中，灵山结庐，美妙无穷，于是他关切地打听修筑偃湖的计划，并油然而生一种在此长居的感觉。\n\n　　这首词通篇都是描写灵山的雄伟景色，在写景上颇有值得注意之处，它不同于一般描写山水之作，它极少实写山水的具体形态，而是用虚笔传神写意。如写山似奔马，松似战士，写得龙腾虎跃，生气勃勃，实是词人永不衰息的斗争性格的写照，即他词所说青山与我“情与貌，略相似”也。显然，作者写此词，力图透过山峰的外形写出其内在的精神；力图把自己所感受到的大自然的内在的美写出来。要传山水之神，光用一般写实的方法不行，于是辛弃疾借助于用典，出人意料地以古代人物倜傥儒雅的风采来比拟山峰健拔秀润的意态，又用太史公文章雄深雅健的风格，来刻画灵山深邃宏伟的气度。表面上看来，这两两相比的东西，似乎不伦不类，风马牛不相及，而它们在精神上却有某些相似之点，可以使人生发联想。这种独特的比喻，真可说是出神入化了！当然，为山水传神写照，是纯粹写观赏风景之人的主观感受，这种感受实际上与作者的胸襟、与作者的思想境界是密切相关的。这种你中有我，我中有你的精神境界，正像辛弃疾自己说的：“我见青山多妩媚，料青山见我应如是”。词作者这种传山水之神的写意笔法，在山水文学上开创了一代先河，值得后人仿效。\n\n　　词通常上片写景，下片抒情。本词上片写景由远至近，由大至小，景已写足。不想转入下片不仅仍写景，而且仍写山，但一反上片的写山之“形”而转写山之“神”，连用三个立意新颖、构思别致的比喻：“似谢家子弟，衣冠磊落：相如庭户，车骑雍容。我觉其间，雄深雅健，如对文章太史公。”可见稼轩的磊落胸怀，用典取事驱遣自然，语既超旷，意又平和，新奇健雅，韵味无穷。最后，以景结情：“新堤路，问偃湖何日，烟水漾漾?”似问非问，姿态、情韵已完全具备了。', poem_tags = '豪放,山水,抒情' WHERE poem_title = '沁园春·灵山斋庵赋时筑偃湖未成' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '已经有些年迈，有心爱惜花，可心已懒散，却独喜欢那江村边围绕的梅花。一枝花点破玉溪的春天。梅花没有一般的春花鲜艳娇嫩的样子，呈现在人们面前的全是傲雪耐寒的神韵。奈何只剩下青山欣赏这样的秀丽景色，为它（梅花）写些清新的诗句。水从竹根流过，溪水缠绵似云。陶醉于眼前的美景，浑然忘记了时间，归家时已是月上柳梢，时已黄昏了。', poem_notes = '此闲居带湖之作。　咏梅而扣住一个“探”字。惜花心懒而独爱梅者，梅花先于众芳，更冰姿玉肌，独立不阿。此咏梅而写人，讥嘲世俗而自抒怀抱。下片因爱梅而赋清新之诗，由“流水带溪云”，至“归路月黄昏”，足见探梅之时久，爱梅之情深。\n心已懒：情意已减退。\n“一枝”三句：一枝江梅报春，带着傲霜耐雪的神韵。玉溪：谓溪水似玉般的洁白晶莹。\n剩向：尽向。餐秀色：秀色可餐，极赞妇女容色之美，也可用以形容山川秀丽，此取后义。着句：写诗句。渠：他（方言），此即指梅。\n“竹根”三句：贪赏梅花，醉中不觉时已向晚，月迷归路。浑：全。', poem_tags = '梅花,惜花' WHERE poem_title = '临江仙·探梅' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '问候这湖中的春水，岸上的春花，林间的春鸟，你们太美了，这次的到来距前次已是三年了。东风顺吹，我驾船驶过湖面，杨柳丝丝拂面，似对我的到来表示欢迎。\n人生道路上的曲折、沉浮我已习惯，无论到哪里，我的心一片悠然。寒光亭下，湖水映照天空，真是天水一色，水面上飞起一群沙鸥。', poem_notes = '西江月：词牌名，原唐教坊曲。又名《白苹香》、《步虚词》、《晚香时候》、《玉炉三涧雪》、《江月令》。双调，五十字，上下片各两平韵，结句各叶一仄韵。\n题溧阳三塔寺：溧阳，今江苏省溧阳县。三塔寺，溧阳境内寺名。这首词原无题，南宋周密《绝妙好词》本增补为“丹阳湖”，而厉鹗笺注则作“题溧阳三塔寺”。宋王象之《舆地纪胜》谓丹阳湖在当涂县东南六十九里。当时为建康和宣城之间内河交通的必经航道。黄异《花庵词选》题作“洞庭”，显系疏误。按岳珂《玉楮集》有诗题《三塔寒光亭张于湖书词寺柱吴毅夫命名后轩》，所云“张于湖书词”，当指此篇。\n问讯：问候。湖：指三塔湖。\n重来又是三年：相隔三年重游旧地。\n过湖船：驶过湖面的船。\n杨柳丝丝：形容杨柳新枝柔嫩如丝。拂面：轻轻地掠过面孔。\n世路：世俗生活的道路。\n寒光亭：亭名。在江苏省溧阳县西三塔寺内。\n沙鸥：沙洲上的鸥鸟。', poem_tags = '宋词三百首,婉约,怀恋,山水' WHERE poem_title = '西江月·问讯湖边春色' AND poem_author = '张孝祥';
UPDATE edu_poem SET poem_tags = '宋词精选,女子,思念' WHERE poem_title = '减字木兰花·天涯旧恨' AND poem_author = '秦观';
UPDATE edu_poem SET poem_translation = '荷花落尽天连着水，暮色苍茫烟波随风起。分飞的双燕紧贴着寒云，我独上小楼东边倚栏观看。\n短暂浮生在醉酒中衰老，转眼间大雪盖满京城道。远方友人也定会登台凝望，寄给我一枝江南春梅。', poem_notes = '芙蓉：指荷花。\n涵：包含，包容。\n沧：暗绿色（指水）。\n背飞双燕：双燕相背而飞。此处有劳燕分飞、朋友离别的意思。\n阑：栏杆。\n合：应该。\n尊：同“樽”，酒杯。\n故人二句：用陆觊赠梅与范晔事。', poem_appreciation = '“芙蓉落尽天涵水，日暮沧波起。”两句写日暮登台所见，境界宏大。“芙蓉”三句寥寥几笔便勾勒出一幅苍茫的画卷，由下及上，先由细处着笔。“芙蓉落尽”点明时节，暗示衰败孤寂之意。“天涵水”是登高眺望所见之景，暮色将至，水面上腾起浓浓的雾气，远远望去，水天一色，苍茫一片。“沧波起”点出寒意，冬季傍晚时分，波涛涌动，带来阵阵寒气。这两旬重在写天地之广，暗含人世沧桑的慨叹。\n\n　　“背飞双燕贴云寒”，视角由平远而移向高远；正当独立苍茫、黯然凝望之际，却又见一对燕子，相背向云边飞去。 “背飞双燕”尤言“劳燕分飞”。《玉台新咏》卷九《东飞伯劳歌》云： “东飞伯劳西飞燕，黄姑（牵牛）织女时相见。”后即用来称朋友离别。“贴云寒”，状飞行之高；高处生寒，由联想而得。着一“寒”字，又从视感而转化为一种心理感受，暗示着离别的悲凉况味。“独向小楼东畔倚栏看”是补叙之笔，交代前面所写，都是小楼东畔倚栏所见。把宏阔高远的视线收聚到一点，对准楼中倚栏怅望之人。“独”字轻轻点出，既写倚栏眺景者为独自一人，又透露出触景而生的孤独惆怅之感。\n\n　　“浮生只合尊前老，雪满长安道。”两句是说光阴荏苒，转眼又是岁暮，雪满京城，寂寥寡欢，唯有借酒遣日而已。“雪满长安”既点时地，又渲染出一派冷寂的气氛，雪夜把盏，却少对酌之人，岁暮怀人的孤凄心境可想而知。\n\n　　“故人早晚上高台，赠我江南春色一枝梅。”故人，老朋友，指公度。早晚，多义词，这里为随时、每日之意。这两句从对方着笔，心有同感，友情的思念彼此相似，我之思彼，亦如彼海内存知己之思我，想象老朋友也天天登高望远，思念着我；即使道远雪阻，他也一定会给我寄赠一枝江南报春的早梅。这是用南朝宋陆凯折梅题诗以寄范晔的故事。这一枝明艳的“江南春色”，定会给“雪满长安”的友人带来亲切的问候和友情的温暖。这是用典，却又切合作者当年与友人置酒相别的一段情事。折梅相赠这一典故，在这里具有普遍与特殊的双层含义，用典如此，可谓表里俱化了。\n\n　　全词构思精巧，首尾呼应，善于借景传情。', poem_tags = '宋词精选,孤独,思念,写景' WHERE poem_title = '虞美人·寄公度' AND poem_author = '舒亶';
UPDATE edu_poem SET poem_translation = '从楼阁归来，才发现今年的春天又迟到了。燕子双双齐飞，垂柳低软，桃花已经凋零残败。落花像撩人的细雨洒满了半空，和风习习充满了庭院。独自皱眉，满怀的愁苦没有人能感受。\n一个人孤独地靠着栏杆，心思如麻又烦乱。芳草萋萋，回忆了一番江南岸。清风明月没有感情，暗将人的模样改变，昔日的游览如梦一样，哪里经受得起重提？我这里白白地极度悲痛。', poem_notes = '蝶恋花：唐教坊曲名。本名《鹊踏枝》。晏殊词改今名。调名取梁简文帝萧纲诗句“翻阶蛱蝶恋花情”中的三字。双调，六十字，十句，上下片各五句四仄韵。一般用来填写多愁善感和缠绵悱恻的内容。\n画阁：华美的楼阁。\n桃花浅：是说春晚桃花开残，树上的花朵显得稀薄了。\n细雨：小雨。\n愁眉：发愁时皱着的眉头。唐白居易《晚春沽酒》：“不如贫贱日，随分开愁眉。”敛尽：收拾、整理干净。\n心绪：心思，心情。\n芊（qiān）绵：草木茂密繁盛。刘禹锡《省试风光草际浮》：“乍疑芊绵里，稍动丰茸际。”\n暗换：不知不觉地更换。\n旧游：昔日的游览。', poem_appreciation = '上片侧重描写女主人公从画阁归来所见的晚春景象。首句一声“春又晚”的叹息，惜春之情溢于言表。“燕子双飞，柳软桃花浅。”从这两句可见归者是独归，所以用此景反衬孤独。“细雨满天风满院”此句既是写景，又衬托出女主人公哀婉绵密的情感。“柳软”、“细雨”两句，具体描写晚春时节令人伤心的风雨落花景象。“愁眉敛尽无人见”将女主人公的形象画进了这幅残春风景图中，人景交融，凸显了他的忧愁孤独之状。此片情景交融，将人的哀婉之情融进残春风雨中。\n\n　　下片主要写主人公的伤离怨别之情。“独”字描绘出女主人公的孤独寂寞，“乱”字则写出她内心的悲凉愁思，表现其形单影只，心烦意乱的心境。“芳草芊绵，尚忆江南岸。”二句描绘她此时目之所及、心之所想，道出愁思的原因，点出离别相思之愁。“人暗换”不仅惋叹当年志同道合之友风流云散，或死或老，也暗寓对朝政日非的愤慨，诅咒岁月“无情”，也暗含对朝廷的贬刺。末两句点出伤春怨别的主题，一直抒胸臆结束全篇。此片主要是由景及情，直接抒发伤春怨别之情。\n\n　　此词由景及情，情景交融，以凄婉缠绵的笔调，曲折尽意地抒写了伤春女子的满怀离思和一腔哀愁。', poem_tags = '伤春,女子,回忆,孤寂' WHERE poem_title = '蝶恋花·画阁归来春又晚' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '南陵的江水，满满地、慢悠悠地流荡，西风紧吹，轻云掠过，秋天即将来到身旁。\n正当客居他乡，心情孤寂凄清的时候，忽见哪家的女子独倚在临江的楼窗？', poem_notes = '南陵：唐县名，在今安徽省繁昌县西。\n客：作者自指。孤迥：指孤单。', poem_tags = '写景,抒情,孤独' WHERE poem_title = '南陵道中 / 寄远' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_tags = '时间,抒怀,感慨,愁苦' WHERE poem_title = '短歌行' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '春风骀荡，景色宜人，我来辞别往日最喜爱的湖上亭。微风中，亭边柳条、藤蔓轻盈招展，仿佛是伸出无数多情的手臂牵扯我的衣襟，不让我离去。\n这情景真叫人意惹情牵，不胜留恋；住了这么久了，亭边柳树枝头的黄莺，也跟我是老相识了。在这即将分离的时刻，别情依依，鸣声悠悠，动人心弦，使人久久难于平静。', poem_notes = '移家：搬家。\n浑：全。\n频啼：连续鸣叫。', poem_tags = '湖水,春光' WHERE poem_title = '移家别湖上亭' AND poem_author = '戎昱';
UPDATE edu_poem SET poem_translation = '我青少年的时候，对事理的认识不是特别通达，呼朋唤友，都是些热血豪迈人士。\n不为报酬而助人，并不把解人之难看作是多么了不起的功劳。\n为朋友曾经不惜两肋插刀，红尘滚滚处也曾经手刃歹徒。\n哥们肝胆意气天下闻名，官民同赏。\n当然，这些都是小节，不足言道，现在回到偏僻之处隐居。\n回家后是四壁空空，没有任何产业，为衣腹之累而忙个不休。\n身穿的狐裘破烂，腰里曾经的万贯黄金也用个精光（主要还是接济落魄文人）。\n也曾经去王公门前干谒，推荐自己，但是没有什么效果，悲日暮途穷。老兄你可是官运通达，青云直上，一诺千金，名噪公卿。\n所以来与你告个急，你懂其中的意思就行了，贵在灵犀一点通。\n如果你也不顾兄弟情谊，不愿意帮助我，我也不说更多的话了，我准备像秋草蓬稞一样随风飘散吧。', poem_notes = '却秦：使秦退兵。\n春陵：在今湖北枣阳县。\n生事：生计。\n“一朝”二句：用苏秦事。\n青云士：品格高尚的人。\n然诺：应许，许诺。\n闻诸公：因重然诺而为诸公所知。\n陈片言：陈述简短的话。\n棣（dì）华：喻兄弟。', poem_tags = '友情' WHERE poem_title = '赠从兄襄阳少府皓' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '悲叹昔日还在园林里游玩的情景，今年春天花开鸟鸣更引发我在边疆的哀愁。\n独自怜惜从京城里出来的人往南逃，真羡慕湘江的水呀，你却往北流去！', poem_notes = '迟日：春日。《诗经·七月》：“春日迟迟，采繁祁祁。”\n悲昔游：作者旧游之地，因放逐再次经过感到悲伤。\n边愁：流放边远地区产生的愁绪。\n京国：指长安。', poem_appreciation = '诗的首句“迟日园林悲昔游”，是因眼前的春光回忆起往昔的春游。当年，春日迟迟，园林如绣，游目骋怀，该是心旷神怡的。而这里追叙“昔游”时却用了一个“悲”字。这个悲，是今天的悲，是从今天的悲追溯昔日的乐；而反过来，也可以说，正因为想起当时的游乐，就更觉得当前处境之可悲。吴乔在《围炉诗话》中说：“情能移境，境亦能移情。”这一句诗是用现在的情移过去的境，为昔日的欢乐景物注入了此时的悲伤心情。\n\n　　诗的第二句“今春花鸟作边愁”，是从昔游的回忆写到今春的边愁。一般说来，鸟语花香是令人欢乐的景物；可是，这些景物却使诗人更想起自己正在流放去边疆的途中。鸟语也好，花香也好，在诗人心目中只构成了远去边疆的哀愁。这一句诗是以心中的情移眼前的境。诗人缘情写景，因而景随情迁。如果就艺术手法来说，以“花鸟”与“边愁”形成对比，是从反面来衬托边愁。与杜审言的这句诗有些近似的有杜甫《春望》诗中的“感时花溅泪，恨别鸟惊心”一联，司马光的《续诗话》评这一联诗说：“花鸟平时可娱之物，见之而泣，闻之而悲，则时可知矣。”这里，以花鸟可娱之物来写“感时”、“恨别”之情，采用的也是反衬法。杜审言是杜甫的祖父，对杜甫有直接影响。“花溅泪”、“鸟惊心”一联，可能就是从“花鸟作边愁”这一句化出的。\n\n　　诗的第三句“独怜京国人南窜”，是整首诗的中心，起承上启下作用。上两句，忆昔游而悲，见花鸟成愁，以及下一句为江水北流而感叹，都因为诗人远离京国，正在南窜途中。上下三句都是围绕着这一句，从这一句生发的。但这一句还没有点到《渡湘江》这个题目。最后一句“不似湘江水北流”，才提到湘江，点破诗题，而以“水北流”来烘托“人南窜”，也是用反衬手法来加强诗的中心内容。\n\n　　杜审言渡湘江时，正值春光明媚，绿水映青山，秀丽的异乡风光撩人意绪，使被贬迁异地的诗人缅怀过去，遐想未来，心中怅惘、失落。因此诗的起句感情深沉地直诉：“迟日园林悲昔游”。他触景生情，回忆起从前在这春光晴丽的大好时光里，尽情游赏园林景色的乐趣，间或还有朋友与他一同饮酒赋诗，赏春惜春，好不痛快。如今只身南迁，心中之悲不难想象。“迟日园林”与“昔游”之间加一“悲”字，使句意曲折而丰富，语势跌宕而劲健。对句：“今春花鸟作边愁”。“今春”指出渡江的时间。“花鸟”概括春景，虽没有直接描绘声色，而鸟语花香的境界已在眼前。“作边愁”，是说今春的花和鸟不同往年，它们也含愁带恨。这里用了移情入景的手法，以比兴表达诗人的愁思。一个“作”字，语意双关。既象说花鸟，又是说人，亦可理解为人与花鸟同说，婉曲而有机趣。\n\n　　这句诗色彩清淡，情意浓挚，七个字，淋漓尽致地抒发了诗人远游伤春的情怀。“独怜京国人南窜”，是这首诗的中心所在，从前两句的忆春、伤春转入叙事抒情，感慨自己从京都流贬到荒僻的南地。“独”字下得有力，使全句生神，激活全篇。“不似湘江水北流”，紧承第三句点题作结，出语自然。管世铭《读雪山房唐诗序例》说：“初唐七绝，味在酸咸之外，‘人情已厌南中苦，鸿雁那从北地来 ’，‘独怜京国人南窜，不似湘江水北流’，‘即今河畔冰开日，正是长安花落时 ’，读之初似常语，久而自知其妙。”所谓“味在酸咸之外”，即指诗中蕴含的情感复杂丰富余味无穷。这些诗句的妙处，不仅在于融情于景，而且还通过时间、空间、景物的不同对比，形成一种杳邈迷茫的意境，仿佛有万般的游丝争惹人的离愁，读者细细体味就能感受其巨大的感染力。“独怜京国人南窜，不似湘江水北流”，初读似常语，并无警策之处，仔细品味，就可看到诗人怅惘的形象。他独立舟头，思悠悠，无限离愁，正如一江春水向北流。杜审言性格爽朗轩豁，喜直抒胸臆，这自是其诗的特色之一。《载酒园诗话》说他“即作磊砢语，亦犹苏子瞻坐桄榔树下食芋饮水，略无攒眉蹙额之态。”这段形象的评语，可帮助我们从多方面去感受欣赏杜审言诗的风格。\n\n　　胡应麟对这首诗的评价很高，他说：“唐初五言绝，子安诸作已入妙境。七言初变梁陈，音律未谐，韵度尚乏。惟杜审言《渡湘江》、《赠苏绾》二首，结皆作对，而工致天然，风味可掬。”这首诗以押韵对起，又以对作结，俱有整齐美、和谐美以及反复咏叹的韵味。初唐时期是七绝初创的阶段，杜审言这首《渡湘江》是有相当影响的，说它“具有开启诗坛新风的作用”，也不为过誉。', poem_tags = '春天,怅惘,即景抒情' WHERE poem_title = '渡湘江' AND poem_author = '杜审言';
UPDATE edu_poem SET poem_translation = '登上赏心亭，看到江山依旧，而文物已非，想起七个朝代都在这里兴国、繁荣和灭亡，忧心忡忡。尽管江水浩瀚、水天一色，却不忍凭阑远眺了。身在江南，心恋长安，坐罪遭贬，想要过问国事却又不能。秦淮月亮格外明朗，照人无眠，听到水上传来音乐声，更是感慨万千。\n这怎能不让我中年鬓发斑白？脸上已失去笑容，回忆起当年琵琶弹奏着动听的乐曲，似乎娓娓地诉说自己政治上的顺利，那是何等地美好啊！期待有朝一日，朝廷重用，再回京师，使自己的仕途如断弦重续。此地与友人别后，何时又能重别呢？', poem_notes = '江神子：词牌名，又名《江城子》《水晶帘》等。唐五代词多为单调，自三十五字至三十七字不等，平韵。至宋人始作双调七十字，有平韵、仄韵两体。 \n陈和叔：名陈睦，嘉祐六年（1061年）进士，累迁史馆修撰。赏心亭：在金陵（今南京）城西下水门城上，下临秦淮，为观赏胜地。\n七朝：六朝指东吴、东晋、宋、齐、梁、陈。此处说“七朝”系指包括南唐在内的七个朝代。\n旧曲：南朝后主陈叔宝所制《玉树后庭花》，被视为亡国之音。\n潘鬓：晋人潘岳富文才，美仪容，三十岁开始有白发，后世即以“潘鬓”指中年鬓发斑白。\n抹幺弦：抹，弹琵琶的一种手法。幺弦，指弹琵琶的第四弦。\n子细：即仔细。因缘：佛家语，指产生结果的直接原因及造成这种结果的条件。因此相契谓之有缘，相乖谓之无缘。\n鸾胶：据《武帝外传》：“西海献鸾胶，武帝弦断，以胶续之，弦两头遂相著，终日射不断，武帝大悦，名续弦胶。”', poem_tags = '咏史怀古' WHERE poem_title = '江神子·癸亥陈和叔会于赏心亭' AND poem_author = '张舜民';
UPDATE edu_poem SET poem_tags = '送别,侠客' WHERE poem_title = '送郑少府入辽共赋侠客远从戎' AND poem_author = '骆宾王';
UPDATE edu_poem SET poem_translation = '落日将没于岘山之西，我戴着山公的白帽子在花下饮得醉态可掬。\n襄阳的小儿一起拍着手在街上拦着我高唱《白铜鞮》。\n路旁之人问他们所笑何事？他们原来是笑我像山公一样烂醉如泥。\n提起鸬鹚杓把酒添得满满的，高举起鹦鹉杯开怀畅饮。百年共有三万六干日，我要每天都畅饮它三百杯。\n遥看汉水像鸭头的颜色一样绿，好像是刚刚酿好还未曾滤过的绿葡萄酒。\n此江之水若能变为一江春酒，就在江边筑上一个舜山和酒糟台；学\n着历史上的曹彰，来一个骏马换妾的风流之举，笑坐在马上，口唱着《落梅花》；\n车旁再挂上一壶美酒，在一派凤笙龙管中出游行乐。\n那咸阳市中行将腰斩徒叹黄犬的李斯，何如我在月下自由自在地倾酒行乐？\n您不是见过在岘山上晋朝羊公的那块堕泪碑玛？驮碑的石龟头部剥落，长满了青苔。\n看了它我既不为之流泪，也不为之悲哀。\n这山间的清风朗月，不用花钱就可任意地享用，既然喝就喝个大醉倒，如玉山自己倾倒不是人推。\n端起那舒州杓，擎起那力士铛，李白要与你们同死生。\n楚襄王的云雨之梦哪里去了？在这静静的夜晚所能见到只有月下的江水，所听到的只有夜猿的悲啼之声。', poem_notes = '襄阳歌：为李白创辞，属杂歌谣辞。襄阳：唐县名，今属湖北。\n岘山：一名岘首山，在今湖北襄樊市南。\n倒著接蓠：用山简事。山简 （253～312年），字季伦，河内怀人，山涛第五子。生于曹魏齐王曹芳嘉平五年，卒于晋怀帝永嘉六年，终年六十岁。山简性温雅，有父风。山涛起初不知其山简的才华，山简叹道：“吾年几三十，而不为家公所知！”与嵇绍、刘谟、杨淮齐名。初为太子舍人。永嘉中，累迁至尚书左仆射，领吏部，疏广得才之路。不久出为镇南将军，镇襄阳。嗜酒，每游习家园，置酒池上便醉，名之曰高阳池。当时有儿童作歌以嘲之。洛阳陷落后（311年），迁于夏口，招纳流亡，江汉归附。卒于镇，追赠征南大将军。山简作有文集二卷，（《唐书·经籍志》）传于世，今佚。\n山翁：即山简。\n鸬鹚杓（sháo）：形如鸬鹚颈的长柄酒杓。鹦鹉杯：用鹦鹉螺制成的酒杯。\n鸭头绿：当时染色业的术语，指一种像鸭头上的绿毛一般的颜色。\n酸醅：重酿而没有滤过的酒。\n垒：堆积。魏：俗称酒母，即酿酒时所用的发酵糖化剂。糟丘台：酒糟堆成的山丘高台。纣王沉湎于酒，以糟为丘。见《论衡·语增》。\n“千金”句：《独异志》卷中：“后魏曹彰性倜傥，偶逢骏马爱之，其主所惜也。彰曰：‘予有美妾可换，惟君所选。’马主因指一妓，彰遂换之。”\n落梅：即《梅花落》，乐府横吹曲名。\n凤笙：笙形似凤，古人常称为凤笙。龙管：指笛，相传笛声如龙鸣，故称笛为龙管。\n“咸阳”句：用秦相李斯被杀事。\n罍：酒器。\n羊公：指羊祜。一片石：指堕泪碑。\n龟：古时碑石下的石刻动物，形状似龟。\n舒州杓：舒州（今安徽潜山县一带）出产的杓。唐时舒州以产酒器著名。力士铛（chēng）：一种温酒的器具，唐代豫章（今江西南昌一带）所产。', poem_appreciation = '此诗是李白的醉歌，诗中以醉汉的心理和眼光看周围世界，实际上是以带有诗意的眼光来看待一切，思索一切。诗一开始用了晋朝山简的典故。山简镇守襄阳时，喜欢去习家花园喝酒，常常大醉骑马而回。当时的歌谣说他：“日暮倒载归，酩酊无所知。复能骑骏马，倒着白接篱。”接篱，一种白色帽子。李白在这里是说自己像当年的山简一样，日暮归来，烂醉如泥，被儿童拦住拍手唱歌，引起满街的喧笑。\n\n　　但狂放不羁的诗人毫不在意，说什么人生百年，一共三万六千日，每天都应该往肚里倒上三百杯酒。此时，他酒意正浓，醉眼朦胧地朝四方看，远远看见襄阳城外碧绿的汉水，幻觉中就好像刚酿好的葡萄酒一样。啊，这汉江若能变作春酒，那么单是用来酿酒的酒曲，便能垒成一座糟丘台了。诗人醉骑在骏马雕鞍上，唱着《梅花落》的曲调，后面还跟着车子，车上挂着酒壶，载着乐队，奏着劝酒的乐曲。他洋洋自得，忽然觉得自己的纵酒生活，连历史上的王侯也莫能相比呢。秦丞相李斯也被秦二世杀掉了，临刑时对他儿子说：“吾欲与若（你）复牵黄犬，俱出上蔡（李斯的故乡）东门，逐狡兔，岂可得乎！”还有晋朝的羊祜，镇守襄阳时常游岘山，曾对人说：“由来贤达胜士登此远望，如我与卿者多矣，皆湮没无闻，使人悲伤。”祜死后，襄阳人在岘山立碑纪念。见到碑的人往往流泪，名为“堕泪碑”。但这碑到了此时已没有什么意义了。如今碑也已剥落，再无人为之堕泪了。一个生前即未得善终，一个身后虽有人为之立碑，但也难免逐渐湮没，不能有“月下倾金罍”这般快乐而现实。那清风朗月可以不花一钱尽情享用，酒醉之后，像玉山一样倒在风月中，显示出无比潇洒和适意。\n\n　　诗的尾声，诗人再次宣扬纵酒行乐，强调即使尊贵到能与巫山神女相接的楚襄王，亦早已化为子虚乌有，不及与伴自己喝酒的舒州杓、力士铛同生共死更有乐趣。\n\n　　这首诗为人们所爱读。因为诗人表现的生活作风虽然很放诞，但并不颓废，支配全诗的，是对他自己所过的浪漫生活的自我欣赏和陶醉。诗人用直率的笔调，给自己勾勒出一个天真烂漫的醉汉形象。诗里生活场景的描写非常生动而富有强烈戏剧色彩，达到了绘声绘影的程度，反映了盛唐社会生活中生动活泼的一面。', poem_tags = '典故,饮酒,生活' WHERE poem_title = '襄阳歌' AND poem_author = '李白';
UPDATE edu_poem SET poem_tags = '春天,女子,怀远' WHERE poem_title = '酒泉子·花映柳条' AND poem_author = '温庭筠';
UPDATE edu_poem SET poem_translation = '细雨斜风天气微寒。淡淡的烟雾，滩边稀疏的柳树似乎在向刚放晴后的沙滩献媚。眼前入淮清洛，亦仿佛渐流渐见广远无际。\n乳色鲜白的好茶伴着新鲜的野菜。人间真正有味道的还是清淡的欢愉。', poem_notes = '浣溪沙：本唐教坊曲名，后用作词牌。一作《浣溪纱》，又名《浣沙溪》、《小庭花》等。双调四十二字，平韵。南唐李煜有仄韵之作。此调音节明快，句式整齐，易于上口。为婉约、豪放两派词人所常用。\n刘倩叔：名士彦，泗州人，生平不详。\n南山：在泗州东南，景色清旷，宋米芾称为淮北第一山。\n媚：美好。此处是使动用法。滩：十里滩，在南山附近。\n洛：洛河，源出安徽定远西北，北至怀远入淮河。\n漫漫：水势浩大。\n“雪沫”句：谓午间喝茶。雪沫乳花：形容煎茶时上浮的白泡。午盏：午茶。\n蓼（liǎo）茸：蓼菜嫩芽。\n春盘：旧俗，立春时用蔬菜水果、糕饼等装盘馈赠亲友。', poem_appreciation = '词的上片写早春景象，下片写作者与同游者游山时以清茶野餐的风味。作品充满春天的气息，洋溢着生命的活力，反映了作者对现实生活的热爱和健胜进取的精神。\n\n　　词的上片写沿途景观。第一句写清晨，风斜雨细，瑟瑟寒侵，这残冬腊月是很难耐的，可是东坡却只以“作晓寒”三字出之，表现了一种不大在乎的态度。\n\n　　第二句写向午的景物：雨脚渐收，烟云淡荡，河滩疏柳，尽沐晴晖。一个“媚”字，极富动感地传出作者喜悦的心声。作者从曳于淡云晴日中的疏柳，觉察到萌发中的春潮。于残冬岁暮之中把握住物象的新机，这正是东坡逸怀浩气的表现，是他精神境界上度越恒流之处。“入淮”句寄兴遥深，一结甚远。句中的“清洛”，即“洛涧”，发源于合肥，北流至怀远合于淮水，地距泗州（宋治临淮）不近，非目力能及。词中提到清洛，是以虚摹的笔法，眼前的淮水联想到上游的清碧的洛涧，当它汇入浊淮以后，就变得浑浑沌沌一片浩茫了。\n\n　　下片转写作者游览时的清茶野餐及欢快心情。一起两句，作者抓住了两件有特征性的事物来描写：乳白色的香茶一盏和翡翠般的春蔬一盘。两相映托，便有浓郁的节日气氛和诱人的力量。“雪沫”乳花，状煎茶时上浮的白泡。以雪、乳形容茶色之白，既是比喻，又是夸张，形象鲜明。午盏，指午茶。此句可说是对宋人茶道的形象描绘。“蓼茸蒿笋”，即蓼芽与蒿茎，这是立春的应时节物。旧俗立春时馈送亲友以鲜嫩春菜和水果、饼铒等，称“春盘”。\n\n　　此二句绘声绘色、活灵活现地写出了茶叶和鲜菜的鲜美色泽，使读者从中体味到词人品茗尝鲜时的喜悦和畅适。这种将生活形象铸成艺术形象的手法，显示出词人高雅的审美意趣和旷达的人生态度。“人间有味是清欢”，这是一个具有哲理性的命题，用词的结尾，却自然浑成，有照彻全篇之妙趣，为全篇增添了欢乐情调和诗味、理趣。\n\n　　这首词，色彩清丽而境界开阔的生动画面中，寄寓着作者清旷、闲雅的审美趣味和生活态度，给人以美的享受和无尽的遐思。', poem_tags = '婉约,纪游,写景' WHERE poem_title = '浣溪沙·细雨斜风作晓寒' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '我骑着高大健壮的良马踏步行走在落花上，手中的马鞭故意掠过华美的车驾。\n车中美人笑着撩起珠帘，遥遥指向前方红楼说那是我的家。', poem_notes = '骄：指马高大健壮。\n直：特地，故意。\n拂：掠过。\n五云车：传说中神仙的座驾。这里指代华美的车驾。\n褰：提起，撩起。\n遥指：有邀至其家之意。\n红楼：一作青楼。', poem_tags = '女子,少年,爱情' WHERE poem_title = '陌上赠美人' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '注释 ⑴蹙（cù促）——收缩，这里指折叠后出现了皱纹。 ⑵裛（yì邑）——沾湿，浸染之意。 ⑶韶颜——年轻美丽的容颜。 ⑷恁（nèn嫩）——这样。', poem_tags = '女子,追忆,思念' WHERE poem_title = '贺明朝·忆昔花间相见后' AND poem_author = '欧阳炯';
UPDATE edu_poem SET poem_tags = '端午,写景,抒情,爱国' WHERE poem_title = '少年游·端午赠黄守徐君猷' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_translation = '庭院深深，不知有多深？杨柳依依，飞扬起片片烟雾，一重重帘幕不知有多少层。豪华的车马停在贵族公子寻欢作乐的地方，她登楼向远处望去，却看不见那通向章台的大路。 \n春已至暮，三月的雨伴随着狂风大作，再是重门将黄昏景色掩闭，也无法留住春意。泪眼汪汪问落花可知道我的心意，落花默默不语，纷乱的，零零落落一点一点飞到秋千外。', poem_notes = '几许：多少。许，估计数量之词。\n堆烟：形容杨柳浓密。\n玉勒：玉制的马衔。\n雕鞍：精雕的马鞍。\n游冶处：指歌楼妓院。\n章台：汉长安街名。《汉书·张敞传》有“走马章台街”语。唐许尧佐《章台柳传》，记妓女柳氏事。后因以章台为歌妓聚居之地。\n乱红：凌乱的落花。', poem_appreciation = '这首词亦见于冯延巳的《阳春集》。清人刘熙载说：“冯延巳词，晏同叔得其俊，欧阳永叔得其深。”（《艺概·词曲概》）在词的发展史上，宋初词风承南唐，没有太大的变化，而欧与冯俱仕至宰执，政治地位与文化素养基本相似。因此他们两人的词风大同小异，有些作品，往往混淆在一起。此词据李清照《临江仙》词序云：“欧阳公作《蝶恋花》，有‘深深深几许’之句，予酷爱之，用其语作‘庭院深深’数阕。”李清照去欧阳修未远，所云当不误。\n\n　　此词写闺怨。词风深稳妙雅。所谓深者，就是含蓄蕴藉，婉曲幽深，耐人寻味。此词首句“深深深”三字，前人尝叹其用叠字之工；兹特拈出，用以说明全词特色之所在。不妨说这首词的景写得深，情写得深，意境也写得深。\n\n　　先说景深。词人像一位舞台美术设计大师一样，首先对女主人公的居处作了精心的安排。读着“杨柳堆烟，帘幕无重数”这两句，似乎在眼前出现了一组电影摇镜头，由远而近，逐步推移，逐步深入。随着镜头所指，读者先是看到一丛丛杨柳从眼前移过。“杨柳堆烟”，说的是早晨杨柳笼上层层雾气的景象。着一“堆”字，则杨柳之密，雾气之浓，宛如一幅水墨画。随着这一丛丛杨柳过去，词人又把镜头摇向庭院，摇向帘幕。这帘幕不是一重，而是过了一重又是一重。究竟多少重，他不作琐屑的交代，一言以蔽之日“无重数”。“无重数”，即无数重。秦观《踏莎行》“驿寄梅花，鱼传尺素，砌成此恨无重数”，与此同义。一句“无重数”，令人感到这座庭院简直是无比幽深。可是词人还没有让你立刻看到人物所在的地点。他先说一句“玉勒雕鞍游冶处”，宕开一笔，把读者的视线引向她丈夫那里；然后折过笔来写道：“楼高不见章台路”。原来这词中女子正独处高楼，她的目光正透过重重帘幕，堆堆柳烟，向丈夫经常游冶的地方凝神远望。这种写法叫做欲扬先抑，做尽铺排，造足悬念，然后让人物出场，如此便能予人以深刻的印象。\n\n　　再说情深。词中写情，通常是和景结合，即景中有情，情中有景，但也有所侧重。此词将女主人公的感情层次挖得很深，并用工笔将抽象的感情作了细致入微的刻画。词的上片着重写景，但“一切景语，皆情语也”（王国维《人间词话》），在深深庭院中，人们仿佛看到一颗被禁锢的与世隔绝的心灵。词的下片着重写情，雨横风狂，催送着残春，也催送女主人公的芳年。她想挽留住春天，但风雨无情，留春不住。于是她感到无奈，只好把感情寄托到命运同她一样的花上：“泪眼问花花不语，乱红飞过秋千去。”这两句包含着无限的伤春之感。清人毛先舒评曰：“词家意欲层深，语欲浑成。作词者大抵意层深者，语便刻画；语浑成者，意便肤浅，两难兼也。或欲举其似，偶拈永叔词云：‘泪眼问花花不语，乱红飞过秋千去。’此可谓层深而浑成。”（王又华《古今词论》引）他的意思是说语言浑成与情意层深往往是难以兼具的，但欧词这两句却把它统一起来。所谓“意欲层深”，就是人物的思想感情要层层深入，步步开掘。且看这两句是怎样进行层层开掘的。第一层写女主人公因花而有泪。见花落泪，对月伤情，是古代女子常有的感触。此刻女子正在忆念走马章台（汉长安章台街，后世借以指游冶之处）的丈夫，可是望而不可见，眼中惟有在狂风暴雨中横遭摧残的花儿，由此联想到自己的命运，不禁伤心泪下。第二层是写因泪而问花。泪因愁苦而致，势必要找个发泄的对象。这个对象此刻已幻化为花，或者说花已幻化为人。于是女主人公向着花儿痴情地发问。第三层是花儿竟一旁缄默，无言以对。是不理解她的意思呢，还是不肯给予同情，殊令人纳闷。紧接着词人写第四层，花儿不但不语，反而像故意抛舍她似的纷纷飞过秋千而去。人儿走马章台，花儿飞过秋千，有情之人，无情之物对她都报以冷漠，她不可能不伤心。这种借客观景物的反应来烘托、反衬人物主观感情的写法，正是为了深化感情。词人一层一层深挖感情，并非刻意雕琢，而是像竹笋有苞有节一样，自然生成，逐次展开。在自然浑成、浅显易晓的语言中，蕴藏着深挚真切的感情，这是此篇一大特色。\n\n　　最后是意境深。词中写了景，写了情，而景与情又是那样的融合无间，浑然天成，构成了一个完整的意境。读此词，总的印象便是意境幽深，不徒名言警句而已。词人刻画意境也是有层次的。从环境来说，它是由外景到内景，以深邃的居室烘托深邃的感情，以灰暗凄惨的色彩渲染孤独伤感的心情。从时间来说，上片是写浓雾弥漫的早晨，下片是写风狂雨暴的黄昏，由早及晚，逐次打开人物的心扉。过片三句，近人俞平伯评日：“‘三月暮’点季节，‘风雨，点气候，‘黄昏’点时刻，三层渲染，才逼出‘无计’句来。”（《唐宋词选释》）暮春时节，风雨黄昏；闭门深坐，情尤怛恻。个中意境，仿佛是诗，但诗不能写其貌；是画，但画不能传其神；惟有通过这种婉曲的词笔才能恰到好处地勾画出来。尤其是结句，更臻于妙境：“一若关情，一若不关情，而情思举荡漾无边。”（沈际飞《草堂诗余正集》）王国维认为这是一种“有我之境”。所谓“有我之境”，便是“以我观物，故物皆著我之色彩”（《人间词话》）。也就是说，花儿含悲不语，反映了词中女子难言的苦痛；乱红飞过秋千，烘托了女子终鲜同情之侣、怅然若失的神态。而情思之绵邈，意境之深远，尤令人神往。', poem_tags = '宋词三百首,宋词精选,婉约,孤独,闺怨' WHERE poem_title = '蝶恋花·庭院深深深几许' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '这节令风物有哪一点使人不称心？可不知怎的，我面对这满眼秋色，却禁不住黯然神伤。\n西风猎猎，市上的酒旗迎风招展；细雨濛濛，到处有金色的菊花怒放。\n想到国事家事，愁得我双鬓灰白；白白地耗费朝廷俸禄，我心中感到羞耻难当。\n什么时候能满足我的愿望——挽着鹿车，回到颍东，耕田植桑。', poem_notes = '秋怀：秋日的思绪情怀。\n节物：节令风物。\n酒旗：酒店悬挂于路边用与招揽生意的锦旗。\n包羞：对所做事感到耻辱不安。\n鹿车：用人力推挽的小车。《风俗通义》说因其窄小，仅载得下一鹿，故名。\n颍东：指颍州（今安徽阜阳）。欧阳修在皇祐元年（1049）知颍州，乐西湖之胜，将卜居，不久内迁。翌年，约梅圣俞买田于颍。', poem_tags = '秋天,写景,抒怀,思归' WHERE poem_title = '秋怀' AND poem_author = '欧阳修';
UPDATE edu_poem SET poem_translation = '秦地有位罗敷女，曾在绿水边采桑。\n素手在青条上采来采去，在阳光下其红妆显得特别鲜艳。\n她宛转地拒绝了太守的纠缠，说：蚕儿已饥，我该赶快回去了，太守大人，且莫在此耽搁您宝斑的时间了。', poem_notes = '子夜吴歌：《子夜歌》属乐府的吴声曲辞，又名《子夜四时歌》，分为“春歌”、“夏歌”、“秋歌”、“冬歌”。《唐书·乐志》说：“《子夜歌》者，晋曲也。晋有女子名子夜，造此声，声过哀苦。”因起于吴地，所以又名《子夜吴歌》。\n“秦地”句：秦地，指今陕西省关中地区。罗敷女，乐府诗《陌上桑》有“日出东南隅，归我秦氏楼。秦氏有好女，自名为罗敷。罗敷善蚕桑，采桑城南隅”的诗句。\n素：白色。\n“红妆”句：指女子盛妆后非常艳丽。\n妾：古代女子自称的谦词。\n“五马”句：意思是，贵人莫要在此留连。五马，《汉官仪》记载：“四马载车，此常礼也，惟太守出，则增一马。”故称五马。这里指达官贵人。', poem_tags = '唐诗三百首,乐府,春天,赞美,女子' WHERE poem_title = '子夜吴歌·春歌' AND poem_author = '李白';
UPDATE edu_poem SET poem_tags = '励志' WHERE poem_title = '定风波·次高左藏使君韵' AND poem_author = '黄庭坚';
UPDATE edu_poem SET poem_tags = '写景,怀古,抒情' WHERE poem_title = '如梦令·题淮山楼' AND poem_author = '苏轼';
UPDATE edu_poem SET poem_tags = '古诗三百首' WHERE poem_title = '蜀道难·其一' AND poem_author = '萧纲';
UPDATE edu_poem SET poem_translation = '注释 铁甲长戈：比喻蟹壳蟹脚。宋代陈郁为皇帝拟进蟹的批答说：“内则黄中通理，外则戈甲森然。此卿出将入相，文在中而横行之象也。”见《陈随隐漫录》。 色相：佛家语，指一切有形之物。借用来说蟹煮熟后颜色好看。 “多肉”句：即“更怜卿八足多肉”。上一联已说螯满、膏香，故这句用“更”字说蟹脚多肉。怜，爱。卿，原本是昵称，这里指蟹。 “助情”句：意即“谁劝我饮千觞以助情”。觞，酒杯。助情，助吃蟹之兴。 兹：此。佳品：指蟹。酬：报答。这里是不辜负、不虚度的意思。佳节：指重阳。 桂拂清风：即“清风拂桂”。', poem_tags = '咏物,议论,讽刺' WHERE poem_title = '螃蟹咏' AND poem_author = '曹雪芹';
UPDATE edu_poem SET poem_translation = '黑姓蕃王身穿貂鼠皮袭，酒醉起舞得来彩缎锦绸。\n关西老将惯于辛苦征战，年已老大仍然转战不休！', poem_notes = '黑姓蕃王：指统辖一方的少数民族王侯或高级将领。黑姓，是西突厥的一个部族，唐开元、天宝时代，西突厥分为黄姓、黑姓两部。这里未必是确指，当泛指某少数民族将领。貂鼠裘：即韶皮袍子。\n葡萄宫锦：绣有葡萄图案的丝织品。宫锦，王宫中所用的名贵丝织品。醉缠头：唐人宴会时，常酒酣起舞，赠舞者以缠头。缠头，古时歌舞的人把锦帛缠在头上作妆饰，称为“缠头”。\n关西：指函谷关以西地区。汉代有“关西出将，关东出相”的说法。\n行兵：统兵作战。', poem_appreciation = '诗的前两句写边镇少数民族将领的逸乐。从三个方面写黑姓蕃王的生活：一是穿着：貂鼠裘以示名贵；二是宴饮：写纵荡不羁；三是玩物：葡萄宫锦以示器物的奢侈。写边镇蕃王，不去写他的军事生活，而是选择一些细节写他的享乐生活，可以看出他们的地位，他们的骄纵。\n\n　　诗的后两句写关西老将长期征战之苦。“能”，主要不是说具有能力，而是说其不得已。一个“苦”字，是关西老将全部征战生活的写照。“七十”，写出了老将年迈而非确指。“仍”概括了老将过去，现在和将来的征战生活，“苦”字自在其中。写“关西老将”专写其征战生活，与“黑姓蕃王”适成鲜明对照。“黑姓蕃王”逸乐如彼，“关西老将”苦战如此，诗人因而感慨。诗中仅把两种鲜明对照的现象作客观罗列，而写的实际是诗人所感。\n\n　　岑参这篇作品以自己边地所见把“黑姓蕃王”与“关西老将”作鲜明对照，表现了汉、蕃两族将领的苦乐不均，这样，这首诗就上升到了政治层面，使诗歌境界得到了提升。', poem_tags = '边塞,战士' WHERE poem_title = '胡歌' AND poem_author = '岑参';
UPDATE edu_poem SET poem_translation = '丈夫死于战乱她独守茅屋受煎熬，身穿苎麻布衣衫鬓发干涩又枯焦。\n桑树柘树全废毁还要交纳蚕丝税，田园耕地已荒芜仍然征税叫青苗。\n时常外出挖野菜连着根须一起煮，随即四处砍生柴带着叶子一起烧。\n任凭你住在比深山更深的偏僻处，也没办法逃脱官府的赋税和兵徭。', poem_notes = '蓬茅：茅草盖的房子。\n麻苎（zhù）：即苎麻。鬓发焦：因吃不饱，身体缺乏营养而头发变成枯黄色。\n柘：树木名，叶子可以喂蚕。征苗：征收农业税。\n后：一作“尽”。\n和：带着，连。\n旋：同“现”。斫：砍。生柴：刚从树上砍下来的湿柴。\n征徭：赋税和徭役。', poem_appreciation = '此诗的“夫因兵死守蓬茅”，就从这兵荒马乱的时代着笔，概括地写出了这位农家妇女的不幸遭遇：战乱夺走了她的丈夫，迫使她孤苦一人，逃入深山破茅屋中栖身。\n\n　　“麻苎衣衫鬓发焦”一句，抓住“衣衫”、“鬓发”这些最能揭示人物本质的细节特征，简洁而生动地刻画出寡妇那贫困痛苦的形象：身着粗糙的麻布衣服，鬓发枯黄，面容憔悴，肖其貌而传其神。从下文“时挑野菜”、“旋斫生柴”的描写来看，山中寡妇应该还是青壮年妇女，照说她的鬓发色泽该是好看的，但由于苦难的熬，使她鬓发早已焦黄枯槁，显得苍老了。简洁的肖像描写，衬托出人物的内心痛苦，写出了她那饱经忧患的身世。\n\n　　然而，对这样一个孤苦可怜的寡妇，统治阶级也并不放过对她的榨取，而且手段是那样残忍：“桑柘废来犹纳税，田园荒后尚征苗。”此处的“纳税”，指缴纳丝税；“征苗”，指征收青苗税，这是代宗广德二年开始增设的田赋附加税，因在粮食未成熟前征收，故称。古时以农桑为本，由于战争的破坏，桑林伐尽了，田园荒芜了，而官府却不顾人民的死活，照旧逼税和“征苗”。残酷的赋税剥削，使这位孤苦贫穷的寡妇无以为生。\n\n　　“时挑野菜和根煮，旋斫生柴带叶烧”，只见她不时地挖来野菜，连菜根一起煮了吃；平时烧柴也很困难，燃生柴还要“带叶烧”。这两句是采用一种加倍强调的说法，通过这种艺术强调，渲染了山中寡妇那难以想象的困苦状况。最后，诗人面对民不聊生的黑暗现实，发出深沉的感慨：“任是深山更深处，也应无计避征徭”。深山有毒蛇猛兽，对人的威胁很大。寡妇不堪忍受苛敛重赋的压榨，迫不得已逃入深山。然而，剥削的魔爪是无孔不入的，即使逃到“深山更深处”，也难以逃脱赋税和徭役的罗网。“任是”、“也应”两个关联词用得极好。可以看出，诗人的笔触象匕首一样揭露了封建统治者的罪恶本质。\n\n　　诗歌是缘情而发，以感情来拨动读者心弦的。《山中寡妇》之所以感人，正在于它富有浓厚的感情色彩。但诗并不直接抒情，而是把感情诉诸对人物命运的刻画描写之中。诗人把寡妇的苦难写到了极至，造成一种浓厚的悲剧氛围，从而使人民的苦痛，诗人的情感，都通过生活场景的描写自然地流露出来，产生了感人的艺术力量。最后，诗又在形象描写的基础上引发感慨，把读者的视线引向一个更广阔的境界，不但使人看到了一个山中寡妇的苦难，而且使人想象到和寡妇同命运的更多人的苦难。这就从更大的范围、更深的程度上揭露了残酷的剥削，深化了主题，使诗的蕴意更加深厚。', poem_tags = '忧国忧民,妇女,生活' WHERE poem_title = '山中寡妇 / 时世行' AND poem_author = '杜荀鹤';
UPDATE edu_poem SET poem_tags = '言志' WHERE poem_title = '山坡羊·道情' AND poem_author = '宋方壶';
UPDATE edu_poem SET poem_tags = '写雨,退隐' WHERE poem_title = '汉宫春·会稽秋风亭观雨' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '当年肃宗即位灵武，收复关中，借阴山骄子回纥之兵收复两京，东胡安庆绪奔走河北死守邺城，史思明出兵相救安庆绪于邺城，既降又叛反复无常并复陷东京洛阳早是意料之中的事。肃宗整日诚惶诚恐多方讨好信任关中小人李辅国，宠惧后宫张良娣，致使纲纪坏而国政乱，以致今日代宗仍在劳心焦思肃清朝纲。\n当年我自己官为拾遗时。在皇帝左右，又拾遗职掌供奉扈从，代宗以广平王拜天下兵马元帅，先后收复两京势不可挡。代宗听信宦官程元振谗害，夺郭子仪兵柄，使岐雍一带兵力单薄，不能防敌于国门之外。致使吐蕃入侵两京沦陷，府库闾舍，焚掠一空，百官狼狈就道，鞋子都来不及穿跟随代宗逃往陕州。何时才能出现傅介子这样勇猛的人物来湔雪国耻啊，只要国家能灭寇中兴，我个人做不做尚书郎倒没关系。\n\n想当年开元盛世时，小城市就有万家人口，农业丰收，粮食储备充足，储藏米谷的仓库也装的满满的。社会秩序安定，天下太平没有寇盗横行，路无豺虎，旅途平安，随时可以出门远行，自然不必选什么好日子。当时手工业和商业的发达，到处是贸易往来的商贾的车辆，络绎不绝于道。男耕女桑，各安其业，各得其所。宫中天子奏响祭祀天地的乐曲，一派太平祥和。社会风气良好，人们互相友善，关系融洽，百馀年间，没有发生过大的灾祸。国家昌盛，政治清明。\n谁知安史乱后，田园荒芜，物价昂贵，一绢布匹要卖万贯钱。洛阳的宫殿被焚烧殆尽，吐蕃也攻陷长安，盘踞了半月，代宗不久之后收复两京。不敢跟年高望重的人絮叨旧事，怕他们又从安禄山陷两京说起，惹得彼此伤起心来。小臣我愚钝无所能，承蒙当初朝廷授检校工部员外郎官职给我。希望当代皇上能像周宣王恢复周代初期的政治，使周朝中兴那样恢复江山社稷，我在江汉流经的巴蜀地区也会激动涕零的。', poem_notes = '先皇巡朔方：指唐肃宗在灵武、凤翔时期。《晋书·郑冲传》：“翼亮先皇。至德元载，肃宗即位于灵武，下制曰：‘朕治兵朔方，须安兆姓之心，勉顺群臣之请。’赵曰：‘朔方乃灵武邻郡。’”\n入咸阳：指至德二年九月收复关中，十月肃宗还京。与汉灵帝末童谣相仿：“侯非侯，王非王，干乘万骑上北邙。”\n阴山骄子：指回纥。《史记·秦本纪》：“西北斥逐匈奴，自渝中并河以东属之阴山。”徐广曰：“阴山在五原北。”《通典》：“阴山，唐安北都护府也。”汗血马：大宛国有汗血马。\n“长驱”句：东胡，指安庆绪。肃宗借兵回纥，收复两京，安庆绪奔河北，保邺郡，所以说胡走藏。\n“邺城”句：邺城反覆，指史思明既降又叛，救安庆绪于邺城，复陷东京洛阳一事。思明被迫投降，反覆无常，乃意料中事，故云不足怪。\n“关中”句：关中小儿，指李辅国。《旧唐书·宦官传》：“李辅国，闲厩马家小儿，少为阉，貌陋，粗知书计，为仆事高力士。”《通鉴》注：“凡厩牧、五坊、禁苑给使者，皆渭之小儿。”晋泰始谣：“贾裴王，乱纪纲。”\n“张后”句：《旧唐书·后妃传》：“张后宠遇专房，与辅国持权禁中，干预政事。帝颇不悦，无如之何”。上，指肃宗。\n至令：一作“至今”。今上：当今皇上，此指代宗。\n“我昔”句：指诗人杜甫自己为拾遗时。在皇帝左右，故日近侍。又拾遗职掌供奉扈从，故日叨奉引。叨，忝也，自谦之词。\n“出兵”句：指代宗当时以广平王拜天下兵马元帅，先后收复两京。《新唐书》：“代宗为太子，时从狩灵武，拜天下兵马元帅。山涛启事：‘可以整肃朝廷，裁制时政。’陈琳檄文：‘天下不可当。’”\n“为留”句：猛士，指郭子仪。宝应元年（762年）代宗听信宦官程元振谗害，夺郭子仪兵柄，使居留长安。未央，汉宫名，在长安。翻用刘邦《大风歌》。“安得猛士兮守四方，感慨甚深。\n“致使”句：岐（qí）雍，唐凤翔关内地，边兵入卫，岐雍一带，兵力单薄，遂不能防敌于国门之外。《旧唐书·吐蕃传》：“乾元后数年，凤翔之西，邠州之北，尽为蕃戎境。”\n犬戎：古代族名，又叫猃狁，古代活跃于今陕、甘一带，猃、岐之间。此处指吐蕃，广德元年（763年）十月，吐蕃入侵，代宗逃到陕州，长安第二次沦陷，府库闾舍，焚掠一空。\n跣足：打赤足。写逃跑时的狼狈，鞋子都来不及穿。天王：指唐代宗。\n“愿见”句：傅介子，西汉时北地人，曾斩楼兰王头，悬之北阙。杜甫意在湔雪国耻，故愿见能有这种人物。\n尚书郎：作者自谓。《木兰行》：“欲与木兰赏，不用尚书郎。”\n开元：唐玄宗年号（718—741年）。开元盛世是中国历史上最有名的治世之一。孙洙曰：“开元间承平日久，四郊无虞，居人满野，桑麻如织，鸡犬之音相闻。时开远门外西行，亘地万余里，路不拾遗，行者不赍粮，丁壮之人不识兵器。”\n小邑：小城。藏：居住。万家室：言户口繁多。《资治通鉴》唐玄宗开元二十八年载：“是岁，天下县千五百七十三，户八百四十一万二千八百七十一，口四千八百一十四万三千六百九。\n“稻米”二句：写全盛时农业丰收，粮食储备充足。流脂，形容稻米颗粒饱满滑润。仓廪：储藏米谷的仓库。\n“九州”二句：写全盛时社会秩序安定，天下太平。豺虎：比喻寇盗。\n路无豺虎：旅途平安，出门自然不必选什么好日子，指随时可出行。《资治通鉴》开元二十八年载：“海内富安，行者虽万里不持寸兵。\n“齐纨”二句：写全盛时手工业和商业的发达。齐纨鲁缟：山东一带生产的精美丝织品。车班班：商贾的车辆络绎不绝。班班：形容繁密众多，言商贾不绝于道。\n桑：作动词用，指养蚕织布。不相失：各安其业，各得其所。《通典·食货七》载：开元十三年，“米斗至十三文，青、齐谷斗至五文。自后天下无贵物。两京米斗不至二十文，面三十二文，绢一匹二百一十文。东至宋汴，西至岐州，夹路列店肆待客，酒馔丰溢。每店皆有驴赁客乘，倏忽数十里，谓之驿驴。南诣荆、襄，北至太原、范阳，西至蜀川、凉府，皆有店肆以供商旅。远适数千里，不恃寸刃”。\n圣人：指天子。奏云门：演奏《云门》乐曲。云门，祭祀天地的乐曲。\n“天下”句：是说社会风气良好，人们互相友善，关系融洽。胶漆，比喻友情极深，亲密无问。\n百馀年间：指从唐王朝开国（618年）到开元末年（741年），有一百多年。未灾变：没有发生过大的灾祸。\n“叔孙”句：西汉初年，高祖命叔孙通制定礼乐，萧何制定律令。这是用汉初的盛世比喻开元时代的政治情况。\n“岂闻”二句：开始由忆昔转为说今，写安史乱后的情况：以前物价不高，生活安定，如今却是田园荒芜，物价昂贵。一绢，一匹绢。直，同“值”。\n“洛阳”句：用东汉末董卓烧洛阳宫殿事喻指两京破坏之严重。广德元年十月吐蕃陷长安。盘踞了半月，代宗于十二月复还长安，诗作于代宗还京不久之后，所以说“新除”。\n宗庙：指皇家祖庙。狐兔：指吐蕃。颜之推《古意二首》：“狐兔穴宗庙。”杜诗本此。\n“伤心”二句：写不堪回首的心情。耆旧们都经历过开元盛世和安史之乱，不忍问：是因为怕他们又从安禄山陷京说起，惹得彼此伤起心来。耆旧：年高望重的人。\n乱离：指天宝末年安史之乱。\n小臣：杜甫自谓。鲁钝：粗率，迟钝。\n记识：记得，记住。禄秩：俸禄。蒙禄秩：指召补京兆功曹，不赴。\n周宣：周宣王，厉王之子，即位后，整理乱政，励精图治，恢复周代初期的政治，使周朝中兴。我皇：指代宗。洒血：极言自己盼望中兴之迫切。\n江汉：指长江和嘉陵江。也指长江、嘉陵江流经的巴蜀地区。因为嘉陵江上源为西汉水，故亦称汉水。', poem_appreciation = '题目虽说是《忆昔》，其实是讽今之作。第一首回忆的是唐肃宗的信任宦官和惧怕老婆，目的作于警戒代宗不要走他父亲的老道；第二首回忆的是唐玄宗是开元盛世，目的在于鼓舞代宗恢复往日繁荣，并不是为忆昔而忆昔。\n\n　　第一首上段九句，下段八句。上段九句感伤肃宗之失德。当时肃宗起兵灵武，收复西京长安，率回纥兵讨安庆绪，凡是肃宗认为是有才能的都以任用，便任用了李辅国。但宠幸张良娣，对于政事自然就很少有时间去管了。所以中兴之业，是仍处于停滞阶段的。“后不乐”，状其骄傲放纵。“上为忙”，状其畏缩恐惧。这分明写出了惧内意。王洙曰：“拨乱，内平张后之难。补四方，外能经营河北也。”下段八句感伤代宗不能振起。代宗初为元帅，出兵整肃，到了程元振带兵时，使郭子仪束手留京，吐蕃入侵，而肃宗再次外逃，一时边境无法安定下来，所以愿能有像傅介子这样的人物，杜甫意在湔雪国耻。“老儒”句，作者自叹不能为国靖乱而尸位素餐。\n\n　　第二首上段十二句，下段十句。上段十二句追思开元盛世。当时国盛民富，盗乱息止人民安定，政治通和清明，民风淳厚，礼仪等方面也秩序井然，胜于贞观之治。这里便是惜唐明皇疏于政事，所以又极盛转至衰败。下段十句悲痛乱离而思盼兴复。自开元至作此诗，战火不断，民不聊生。“绢万钱，无复齐纨鲁缟矣。田流血，无复室家仓廪矣。东洛烧焚，西京狐兔，道路尽为豺狼，宫中不奏云门矣。”（仇兆鳌《杜诗详注》）乱后景象，是不忍直视的。所以作者在此概叹，中兴事业只能期望于后世之君了。\n\n　　虽然杜甫是从地主阶级的立场和理想来观察现实，但第二首诗中所描述的人丁兴旺、和平环境、丰衣足食，却也是劳动人民所祈望的。因而杜甫的政治理想对广大人民是有利的。诗人素来就有“位卑未敢忘忧国”的崇高理想、“大庇天下寒士俱欢颜”的精神境界，“小臣鲁钝无所能，朝廷记识蒙禄秩。周宣中兴望我皇，洒血江汉身衰疾。”身处乱世、颠沛流离，仍抱忧国忧民之心，“愿见北地傅介子，老儒不用尚书郎。”甘愿“洒血江汉”、再图中兴。', poem_tags = '组诗,忆昔,讽今' WHERE poem_title = '忆昔二首' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '注释 南湖：即今浙江绍兴的鉴湖。 槛（jiàn）：栏杆，此处似指湖边台榭上的栏杆，亦泛指台榭。 菱荇（xìng）：二者结为可食用的水生植物。 飞夕阳：即“夕阳飞”的倒装，意谓在夕阳下飞。 雾雨：蒙蒙细雨。 潇湘：今湖南湘江与潇水的并称。 篷艇：即篷船。 楚乡：指飞卿在吴地（吴被楚灭，故又称楚地）太湖附近的旧乡。', poem_tags = '湖水' WHERE poem_title = '南湖' AND poem_author = '温庭筠';
UPDATE edu_poem SET poem_translation = '白话译文\n江上来来往往的人只喜爱鲈鱼的味道鲜美。\n看看那些可怜的打鱼人吧，正驾着小船在大风大浪里上下颠簸，飘摇不定。\n\n英文译文\nTHE FISHERMAN ON THE STREAM\nYou go up and down stream;\nYou love to eat the bream.\nLo! The fishing boat braves\nPerilous wind and waves.', poem_notes = '①渔者：捕鱼的人。\n②但：只\n江上渔者\n江上渔者\n③爱：喜欢\n④鲈鱼：一种头大口大、体扁鳞细、背青腹白、 味道鲜美的鱼。 生长快，体大味美。\n⑤君：你。\n⑥一叶舟：像漂浮在水上的一片树叶似的小船。\n⑦出没：若隐若现。指一会儿看得见，一会儿看不见。\n⑧风波：波浪。', poem_appreciation = '这首语言朴实、形象生动、对比强烈、耐人寻味的小诗，反映了渔民劳作的艰辛，唤起人们对民生疾苦的注意。\n\n　　首句写江岸上人来人往，十分热闹。次句写岸上人的心态，揭示“往来’的原因。后二句牵过的视线，指示出风浪中忽隐忽现的捕鱼小船，注意捕鱼的情景。鲈鱼虽味美，捕捉却艰辛表达出诗人对渔人疾苦的同情，深含对“但爱鲈鱼美”的岸上人的规劝。“江上”和“风波”两种环境，“往来人”和“一叶舟”两种情态、“往来”和“出没”两种动态强烈对比，显示出全诗旨在所在。\n\n　　表现手法上，该诗无华丽词藻，无艰字僻典，无斧迹凿痕，以平常的语言，平常的人物、事物，表达不平常的思想、情感，产生不平常的艺术效果。', poem_tags = '渔人,生活,抒怀,同情' WHERE poem_title = '江上渔者' AND poem_author = '范仲淹';
UPDATE edu_poem SET poem_translation = '可怜我这三尺童，新遭父丧真悲痛，孤独无援忧忡忡。先父武王多英明，终身能够孝祖宗。念我先祖兴大业，任贤黜佞国运隆。我今年幼已即位，日夜勤政求成功。先王灵前发誓言，继承遗志铭心胸。', poem_notes = '闵：通“悯”，怜悯，郑笺说是“悼伤之言”。予小子：成王自称。小子，年少。对先祖也可自称“小字”。\n不造：不幸，不善。此指遭周武王之丧。\n嬛（qióng）嬛：同“茕茕”，孤独无所依靠貌。疚：忧伤。\n於（wū）乎：同“呜呼”，表感叹。皇考：指武王。\n永世：终身。克：能。\n兹：此。皇祖：对已故祖父的美称。此指周文王。\n陟（zhì）降：上下，升降。庭：直。止：语气词。\n夙（sù）夜：原意为早夜。此指朝夕，日夜，即天天、时时。敬：谨慎。止：语助词。\n皇王：这里指先代君主，兼指文王、武王。\n序：通“绪”，事业。思：语助词。忘：忘记。', poem_appreciation = '嗣王朝庙，通常是向祖先神灵祷告，表白心迹，祈求保佑，同时也有对臣民的宣导作用。鉴于周成王的特殊境遇，这篇告庙之辞应有特殊的设计。\n\n　　开头三句，将成王的艰难处境如实叙述，和盘托出，并强调其“嬛嬛在疚”，无依无靠。国君需要群臣，嗣王更需要群臣的支持，成王这样年幼的嗣王则尤其需要群臣的全力辅佐。强调成王的孤独无援，于示弱示困示艰难之中，隐含了驱使、鞭策群臣效力嗣王的底蕴，这一点在下面即逐步显示出来。\n\n　　第四句的“皇考”指周武王。武王一生业绩辉煌卓著，诗中却一字不提，只说他“永世克孝”。为人子当尽孝；为人臣则当尽忠，其理一致，为什么不直陈其言呢？盖因在危难、困窘之际寻求援助，明令不如感化，当时周王室群臣均为武王旧臣，点出武王克尽孝道，感化之效即生。\n\n　　第六句的“皇祖”指周文王，而“陟降”一语，当重在“陟”，因为成王嗣位时在朝的文王旧臣，都是文王擢拔的贤能之士，他们在文王去世之后，辅佐武王成就了灭商的伟业，此时又该辅佐成王来继业守成了。\n\n　　周公是经历文、武、成三世的老臣，“自文王在时，旦为子孝，笃仁，异于群子”，又“佐武王，作《牧誓》，破殷”（《史记·鲁周公世家》），一些三世老臣如姜尚等，都长期与他共事，上述对文王、武王赞颂之语，出自他口中，自有非同寻常的号召与约束力量，穆王时太仆正伯冏作《冏命》，所说“昔在文武，聪明齐圣，小大之臣，咸怀忠良”，正可见周公的威严。\n\n　　周公在其子伯禽受封于鲁后曾训戒伯禽要尊贤，说：“我，文王之子，武王之弟，成王之叔父，我于天下亦不贱矣。然我一沐三握发，一饭三吐哺，起以待士，犹恐失天下之贤人。”（《史记·鲁周公世家》）他知道自己的身份“不贱”，当然知道成王的身份更为高贵。成王为文王之孙，武王之子，血统至尊，这也几乎就是他继位时全部的政治资本，周公对此不能不充分地加以利用，以期对文王、武王感恩戴德的群臣对成王也俯首听命。因此“继序”一语出现于《周颂·闵予小子》的末句，绝非偶然，它强调成王继承的是文王、武王开创的大业，而“思不忘”对成王固然是必须兑现的誓言，对于文王、武王的旧臣，则是理所当然应尽的天职。\n\n　　《周颂·闵予小子》隐含着对文王、武王旧臣效忠嗣王的要求，而在这方面，周公又是以身作则、堪称楷模的。他并没有忘记对儿子伯禽的教育与指导，用今天的话说是公私兼顾的，可他的主要精力一直集中于辅佐成王，他的主要政治业绩也在于此。这方面，《诗经》《尚书》中的许多篇章留下了可信的记录，孔子也一再表示对他的尊崇与景仰。周公与成王虽然一为臣一为君，一为辅相一为天子，但是，要了解成王时政事，却往往先要了解周公。《六经》皆史，读此篇亦可窥周初政事之一斑。', poem_tags = '诗经' WHERE poem_title = '周颂·闵予小子' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '春社日刚刚过去，你们就在楼阁的帘幕中间穿飞，屋梁上落满了旧年的灰尘，冷冷清清。分开羽翼想停下来，再试着钻进旧巢双栖并宿。好奇地张望雕梁藻井，又呢喃软语商量个不停。倏然间飘然而起掠过花梢，如剪的翠尾划开了红色花影。\n芳香弥漫小径间，春雨将芹泥融融浸润。喜欢贴地争飞，好像要比比谁更俊俏轻盈。回到红楼时天色已晚，看够了昏暝中的柳枝花影。但只顾自己在巢安稳栖息，却忘了稍回天涯游子的书信。这可愁坏了闺中憔悴佳人，望穿双眼天天画栏独凭。', poem_notes = '春社：古代春天的社日，以祭祀土神。在立春后第五个戊日。\n度：穿过。帘幕：古时富贵人家多张挂于院宇。\n差（cī）池：燕子飞行时，有先有后，尾翼舒张貌。《诗经· 邶风·燕燕》：“燕燕于飞，差池其羽。”\n相（xiàng）：端看、仔细看。雕梁：雕有或绘有图案的屋梁。藻井：用彩色图案装饰的天花板，形状似井栏，故称藻井。\n软语：燕子的呢喃声。\n翠尾：翠色的燕尾。红影：花影。\n芳径：长着花草的小径。\n芹泥：水边长芹草的泥土。\n红楼：富贵人家所居处。\n柳昏花暝（míng）：柳色昏暗，花影迷蒙。暝：天色昏暗貌。\n栖香：栖息得很香甜，睡得很好。\n天涯芳信：给闺中人传递从远方带来的书信。古有双燕传书之说。\n翠黛双峨：指闺中少妇。黛蛾：螺子黛，乃女子涂眉之颜料，其色青黑，或以代眉毛。眉细如蛾须，乃谓蛾眉。更有以眉代指美人者。\n画阑：雕花的栏杆。凭：倚靠。', poem_appreciation = '燕子是古诗词中常用的意象，诗如杜甫，词如晏殊等，然古典诗词中全篇咏燕的妙词，则要首推史达祖的这首《双双燕》了。\n\n　　这首词对燕子的描写是极为精彩的。通篇不出“燕”字，而句句写燕，极妍尽态，神形毕肖。而又不觉繁复。“过春社了”，“春社”在春分前后，正是春暖花开的季节，相传燕子这时候由南方北归，词人只点明节候，让读者自然联想到燕子归来了。此处妙在暗示，有未雨绸缪的朦胧，既节省了文字，又使诗意含蓄蕴藉，调动读者的想象力。“度帘幕中间”，进一步暗示燕子的回归。“去年尘冷”暗示出是旧燕重归及新变化。在大自然一派美好春光里，北归的燕子飞入旧家帘幕，红楼华屋、雕梁藻井依旧，所不同的，空屋无人，满目尘封，不免使燕子感到有些冷落凄情。\n\n　　“差池欲住”四句，写双燕欲住而又犹豫的情景。由于燕子离开旧巢有些日子了，“去年尘冷”，好像有些变化，所以要先在帘幕之间“穿”来“度”去，仔细看一看似曾相识的环境。燕子毕竟恋旧巢，于是“差池欲住，试入旧巢相并”。因“欲住”而“试入”，犹豫未决，所以还把“雕梁藻井”仔细相视一番，又“软语商量不定”。小小情事，写得细腻而曲折，像一对小两口居家度日，颇有情趣。沈际飞评这几句词说：“‘欲’字、‘试’字、‘还’字、‘又’字入妙。”（《草堂诗馀正集》）妙就妙在这四个虚字一层又一层地把双燕的心理感情变化栩栩如生地传达出来。\n\n　　“软语商量不定”，形容燕语呢喃，传神入妙。“商量不定”，写出了双燕你一句、我一句，亲昵商量的情状。“软语”，其声音之轻细柔和、温情脉脉形象生动，把双燕描绘得就像一对充满柔情密意的情侣。人们常用燕子双栖，比喻夫妻，这种描写是很切合燕侣的特点的。恐正是从诗词的妙写中得到的启发吧！果然，“商量”的结果，这对燕侣决定在这里定居下来了。于是，它们“飘然快拂花销，翠尾分开红影”，在美好的春光中开始了繁忙紧张快活的新生活。\n\n　　“芳径，芹泥雨润”，紫燕常用芹泥来筑巢，正因为这里风调雨顺，芹泥也特别润湿，真是安家立业的好地方啊，燕子得其所哉，双双从天空中直冲下来，贴近地面飞着，你追我赶，好像比赛着谁飞得更轻盈漂亮。广阔丰饶的北方又远不止芹泥好，这里花啊柳啊，样样都好，风景是观赏不完的。燕子陶醉了，到处飞游观光，一直玩到天黑了才飞回来。\n\n　　“红楼归晚，看足柳昏花暝”，春光多美，而它们的生活又多么快乐、自由、美满。傍晚归来，双栖双息，其乐无穷。可是，这一高兴啊，“便忘了、天涯芳信”。在双燕回归前，一位天涯游子曾托它俩给家人捎一封书信回来，它们全给忘记了！这天外飞来的一笔，出人意料。随着这一转折，便出现了红楼思妇倚栏眺望的画面：“愁损翠黛双蛾，日日画栏独凭”。由于双燕的玩忽害得受书人愁损盼望。\n\n　　这结尾两句，似乎离开了通篇所咏的燕子，转而去写红楼思妇了。看似离题，其实不然，这正是词人匠心独到之处。试想词人为什么花了那么多的笔墨，描写燕子徘徊旧巢，欲住还休？对燕子来说，是有感于“去年尘冷”的新变化，实际上这是暗示人去境清，深闺寂寥的人事变化，只是一直没有道破。到了最后，将意思推开一层，融入闺情更有馀韵。\n\n　　原来词人描写这双双燕，是意在言先地放在红楼清冷、思妇伤春的环境中来写的，他是用双双燕子形影不离的美满生活，暗暗与思妇“画栏独凭”的寂寞生活相对照；接着他又极写双双燕子尽情游赏大自然的美好风光，暗暗与思妇“愁损翠黛双蛾”的命运相对照。显然，作者对燕子那种自由、愉快、美满的生活的描写，是隐含着某种人生的感慨与寄托的。这种写法，打破宋词题材结构以写人为主体的常规，而以写燕为主，写人为宾；写红楼思妇的愁苦，只是为了反衬双燕的美满生活，给人以耳目一新之感。读者自会从燕的幸福想到人的悲剧，不过作者有意留给读者自己去体会罢了。这种写法，因多一层曲折而饶有韵味，因而能更含蓄更深沉地反映人生，煞是别出心裁。但写燕子与人的对照互喻又粘连相接，不即不离，确是咏燕词的绝境。\n\n　　作为一首咏物词，《双双燕》获得了前人最高的评价。王士祯说：“咏物至此，人巧极天工错矣！”（《花草蒙拾》）这首词成功地刻画了燕子双栖双宿恩爱羡人的优美形象，把燕子拟人化的同时，描写它们的动态与神情，又处处力求符合燕子的特征，达到了形神俱似的地步，真的把燕子写活了。例如同是写燕子飞翔，就有几种不同姿态。“飘然快拂花梢，翠尾分开红影”，是写燕子在飞行中捕捉昆虫、从花木枝头一掠而过的情状。“飘然”，既写出燕子的轻，但又不是在空中漫无目的地悠然飞翔，而是在捕食，所以又说“快拂花销”。正因为燕子飞行轻捷，体形又小，飞起来那翠尾像一把张开的剪刀掠过“花梢”，就好似“分开红影”了。“爱贴地争飞”，是燕子又一种特有的飞翔姿态，天阴欲雨时，燕子飞得很低。由此可见词人对燕子观察异常细腻，用词非常精刻。词中写燕子衔泥筑巢的习性，写软语呢喃的声音，也无一不肖。“帘幕”、“雕梁藻井”、“芳径”、“芹泥雨润”等等，也都是诗词中常见的描写燕子的常典。“差池欲住”，“差池”二字本出《诗经·邶风·燕燕》：“燕燕于飞，差池其羽。”“芹泥雨润”，“芹泥”出杜甫《徐步》诗：“芹泥随燕嘴”。“便忘了天涯芳信”则是化用南朝梁代江淹《杂体诗·拟李都尉从军》“而我在万里，结发不相见；袖中有短愿寄双飞燕”诗意，反从双燕忘了寄书一面来写。\n\n　　这首词刻划双燕，有环奇警迈之长，不愧为咏物词之上品。至于求更深的托喻，则是没有的，有的论者认为，“红楼归晚”四句，有弦外之音隐喻韩侂胄之事，虽可备一说，但总不免穿凿太深，反而损害了这首词深广细致的韵致。', poem_tags = '宋词三百首,婉约,咏物,写鸟' WHERE poem_title = '双双燕·咏燕' AND poem_author = '史达祖';
UPDATE edu_poem SET poem_tags = '旅途,写景,抒情,孤寂' WHERE poem_title = '宿郑州' AND poem_author = '王维';
UPDATE edu_poem SET poem_appreciation = '（一）\n\n　　第一首先写草堂，举其四景：堂西的竹笋，堑北的行椒，园中的梅子，久七前的松树。诗人处在这远离闹市的幽静环境之中，因看到园中将熟的梅子，便想到待梅熟时邀朱老一同尝新；因看到堂前的松树，便希望和阮生在松荫下尽情地谈古论今。从中可以看出诗人对草堂的爱赏，以及他对生活的朴素的要求。他久经奔波，只要有一个安身之地就已经满足了。显然，这首诗虽属赋体却兼比兴，于平淡的写景叙事中寓含着诗人的淡泊心情，以作为组诗之纲。当时杜甫因好友严武再镇而重返草堂，足证严武在诗人心目中的重要地位，但这里他所想到的草堂的座上宾都不是严武，而是普普通通的朱老和阮生。这就可见诗人当时的心境和志趣了。\n\n　　（二）\n\n　　第二首诗写浣花溪，状其水势浩大，借“欲作鱼梁”而抒情，非真“欲作鱼梁”也。因为“作鱼梁，须劈竹沉石，横截中流，以为聚鱼之区，因溪有蛟龙，时兴云雨，故公不敢冒险以取利。”（《杜诗详注》卷十三引）对此解说，浦起龙《读杜心解》认为“是为公所愚也”。他说：“须知‘蛟龙，之想，只从‘云覆、‘雨寒，生出，值云雨而墩起文情也。”是有道理的。但浦氏以为这首诗“为作鱼梁而赋，而自况不凡”，则未免有点牵强。其实，这首诗并非什么“自况”，只是流露出诗人对能否在洗花溪畔的草堂安居下去的担心情绪。这才是“不敢安”三字的真实含意。诗人觉得自己在草堂尽管心境淡泊，无所奢求，但仍难保不测。诗中谓溪下有坟龙，时兴云雨，固是一种迷信的说法，却也十分形象化，隐隐可以显示出诗人身居草堂对成都局势的担心情状。这也正是诗人当时“三年奔走空皮骨”的心理状态。\n\n　　（三）\n\n　　这组诗一开始写草堂的春色，情绪是陶然的；而随着视线的游移、景物的转换、江船的出现，触动了他的乡情，四句景语完整表现了诗人这种复杂细致的内心思想活动。此诗两两对杖，写法非常精致考究，读起来却一点儿也不觉得雕琢，十分自然流畅。把读者由眼前景观引向广远的空间和悠长的时间之中，引入对历史和人生的哲思理趣之中。\n\n　　“两个黄鹂鸣翠柳，一行白鹭上青天。 窗含西岭千秋雪，门泊东吴万里船。”黄鹂、翠柳显出活泼的气氛，白鹭、青天给人以平静、安适的感觉。“鸣”字表现了鸟儿的怡然自得。“上”字表现出白鹭的悠然飘逸。黄、翠、白、青，色泽交错，展示了春天的明媚景色，也传达出诗人欢快自在的心情。诗句有声有色，意境优美，对仗工整。一个“含”字，表明诗人是凭窗远眺，此景仿佛是嵌在窗框中的一幅图画。这两句表现出诗人心情的舒畅和喜悦。“西岭”，即成都西南的岷山，其雪常年不化，故云“千秋雪”。“东吴”，三国时孙权在今江苏南京定都建国，国号为吴，也称东吴。这里借指长江下游的江南地区。“千秋雪”言时间之久，“万里船”言空间之广。诗人身在草堂，思接千载，视通万里，胸襟何等开阔！这两句也是全诗的点睛之笔，境界开阔，情志高远。在空间和时间两个方面拓宽了广度，使得全诗的立意一下子卓尔不群，既有杜诗一贯的深沉厚重，又舒畅开阔，实为千古名句。\n\n　　苏轼曾经说过：“少陵翰墨无形画”。此诗就像一幅绚丽生动的山水条幅：黄鹂、翠柳、白鹭、青天、江水、雪山，色调淡雅和谐，图象有动有静。画的中心是几棵翠绿的垂柳，黄莺儿在枝头婉转歌唱；画的上半部是青湛湛的天，一行白鹭映于碧空；远处高山明灭可睹，遥望峰巅犹是经年不化的积雪；近处露出半边茅屋，门前一条大河，水面停泊着远方来的船只。从颜色和线条看，作者把两笔鹅黄点染在一片翠绿之中，在青淡的空间斜勾出一条白线。点线面有机结合，色彩鲜明而又和谐。诗人身在草堂，思接千载，视通万里，胸次开阔，出语雄健。全诗对仗精工，着色鲜丽，动静结合，声形兼俱，每句诗都是一幅画，又宛然组成一幅咫尺万里的壮阔山水画卷。\n\n　　（四）\n\n　　第四首诗为药圃而赋。王嗣爽《杜臆》说：“公常多病，所至必种药，故有‘种药扶衰病，之句。”（《杜诗详注》卷十三引）。今影印本《杜臆》元，仇氏（仇兆鳌）当另有所据。”前两句写药圃景色，种药在两亭之间，青色叠映，临窗望去，油然而喜。后两句虽也是写药物的生长情状，与前两句写药物出土，发苗及枝柯的生长过程相连，对一药物生长于隙地的根部的形状作了描绘，足见诗人对药用植物形态学的认识；但就药寄慨，与首章淡泊之意略同，却不是一般的咏物诗，更绝非某些赏花玩月的作品可比。仇兆鳌注：“彼苗长荒山者，不能遍识其名，此隙地所栽者，又恐日浅术及成形身。”浦起龙亦说：“空山隙地，萧间寂寞之滨也，亦无取于见知矣。”可以参看，以见杜甫虽因严武再镇而重返草堂，但仍担心着“不测风云”，总是把自己同国家的命运联系在一起的。他毕竟不是那种忘乎一切的趋炎附势之人。', poem_tags = '抒情,组诗' WHERE poem_title = '绝句四首' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_translation = '注释 ①秋晚登城北楼：一题作“秋晚登城北门”。 ②幅巾：用一幅丝巾束发。', poem_tags = '秋天,登楼,抒怀,爱国,壮志' WHERE poem_title = '秋晚登城北楼' AND poem_author = '陆游';
UPDATE edu_poem SET poem_translation = '登上山中采蘼芜，下山偶遇前时夫。\n故人长跪问故夫：“你的新妻怎么样？”\n夫说：“新妻虽不错，却比不上你的好。\n美貌虽然也相近，纺织技巧差得多。\n新人从门娶回家，你从小门离开我。\n新人很会织黄绢，你却能够织白素。\n黄绢日织只一匹，白素五丈更有余。\n黄绢白素来相比，我的新人不如你。”', poem_notes = '蘼芜（míwú）：一种香草，叶子风干可以做香料。古人相信蘼芜可使妇人多子。\n姝：好。不仅指容貌。当“新人从门入”的时候，故人是丈夫憎厌的对象，但新人入门之后，丈夫久而生厌，转又觉得故人比新人好了。这里把男子喜新厌旧的心理写得更深一层。\n手爪：指纺织等技巧。\n閤（gé）：旁门，小门。新妇从正面大门被迎进来，故妻从旁边小门被送出去。一荣一辱，一喜一悲，尖锐对照。这两句是弃妇的话，当故夫对她流露出一些念旧之情的时候，她忍不注重提旧事，诉一诉当时所受委屈。\n缣（jiān）、素：都是绢。素色洁白，缣色带黄，素贵缣贱。\n一匹：长四丈，宽二尺二寸。', poem_tags = '弃妇,叙事,怀念' WHERE poem_title = '上山采蘼芜' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '少年时期人生不得意，落魄流徙不曾安居。\n胸有大志一心追随任公子，大钩巨缁钓那吞舟大鱼。\n无奈之间经常痛饮逐景而游，壮心不存、功名不就，都疏远而去。\n兰生谷底人不识人不锄，云在高山空翻卷空舒展。\n突然有名，天子派驰马来迎，如同赤车骋蜀道去接司马相如。\n迈步朝廷走进九重高门谒见见圣上，龙颜笑开令我顿觉四海如春。\n宫中彤庭四下里高呼万岁，拜贺圣明主上收揽沉沦不显的英才。\n我在翰林院挥笔引来皇上的目光，峥嵘的麒麟阁上谁能见到我呢！\n蒙承圣恩举步进入银台门，持笔著书独自待在金銮殿。\n乘龙驹雕蹬跨上白玉鞍，享受象床绮食面对黄金盘。\n以前讥笑我微贱的那些人，现在都来拜见请求交友同欢。\n可我一旦以病辞京漫游江海，往昔那些人谁还与我相识相好？\n前门作揖软绝，后门索性硬拒，结交之人一一变了面孔。\n最喜欢您心如山岳终不改变，真想随您不管去作什么。\n我亦想借您梦得“池塘生春草”的佳句，使我登楼之诗身价百倍。\n相别之后我要像灵运遥寄惠连诗作一般寄诗给您，还有些人也会有和作的。\n\n东平相阮籍与南平太守的您，古今都可郁喜爱饮酒的步兵校尉。\n您和阮籍都是从心眼里爱好美酒才去作那个官，并不是看重恋眷职务啊。\n如今因酒而谪官去到武陵桃源，寻花寻竹行了几处地方？\n桃花源中的秦人有如旧识，定会出门笑脸相迎。', poem_notes = '南平：郡名，即渝州，今四川重庆。之遥：即李之遥，李白的堂弟。\n落拓：即落魄。此用《史记》郦生的典故：郦生家贫落魄，无以为衣食业。\n吞舟鱼：形容鱼大。此指心有大志。\n龙颜：借指帝王。\n彤庭：汉皇宫以朱色漆中庭，故称。\n沉沦：沦落之人。\n翰林：《石林燕语》卷七载：唐翰林院，本内供奉艺能技术杂居之所，以词臣侍书诏其间，乃艺能之一尔。开元以前，犹未有学士之称，或曰翰林待诏，或曰翰林供奉，如李白犹称供奉。自张均为学士，始别建学士院于翰林院之南，则与翰林院分而为二，然犹冒翰林之名。此李白自指翰林供奉的经历。英眄（miǎn）：皇帝的顾望。\n麟阁：汉宣帝时有麒麟阁，为图绘功臣之所。\n银台门：据《旧唐书·职官志》：翰林院天子在大明宫，其院在右银台门内。此句一作“承恩侍从甘泉宫”。\n金銮殿：大明宫紫宸殿北曰蓬莱殿，其西曰还周殿，还周西北曰金銮殿。蓬莱殿西龙首山支陇起平地，上有殿名金銮殿，殿旁坡名金銮坡。\n绮食：一作“绮席”，盛美的筵席。\n畴（chóu）昔：往日，从前。\n“梦得”二句：此以灵运与惠连喻己与之遥。\n“别后”二句：谢灵运有《登临海峤初发疆中作与从弟惠连可见羊何共和之》诗，此用其意。临海，即今台州。羊、何：即泰山羊璿之、东海何长瑜，与谢灵运、谢惠连文章赏会，共为山泽之游。\n“东平”二句：此以阮籍比李之遥。李之遥为南平太守；阮籍曾任东平相，称阮步兵。\n专城：指任主宰一城的州牧、太守等地方长官。\n桃源：在武陵，陶渊明曾作《桃花源记》。\n秦人：《桃花源记》载，内中之人自称是秦时人，避秦末之乱才进入桃花源中。', poem_appreciation = '《赠从弟南平太守之遥二首》共同主题是赞美从弟李之遥，而讽刺势利小人，从而反映出世道交恶，贤者被弃，佞臣得势，道德友情沦丧，一切均以势利为轴心和转移。李白身受其害，故借赠诗抒感概。第一首诗写完之后，犹未尽意，故又以第二首补足之。两首诗呈现出不同的描写重点，然而又是相互补充，相得益彰的完整艺术整体。\n\n　　第一首基本是以七言为主的古体诗，全诗三十二句，可分三个大段落。\n\n　　第一段共八句，又可分为两个层次。诗开端的五言四句为第一个层次，直叙少年不得意，潦倒而无安居生活之业。愿意追随古代任公子之后，投钓东海，钓得能吞进舟船的巨鱼，以饱天下之人，而不作追逐功名利禄之徒。任公子是《芪子》一书中所引用的寓言人物：任公子作大钩巨缁，五十辖以为饵，蹉乎会稽，投竿东海，旦旦而钓，期年不得鱼。已而大鱼食之，牵巨钩陷没而下骛，扬而奋鬐，白波若山，海水震荡，声侔鬼神、惮赫千里。任公子得若鱼，离而腊之，自制河以东，苍梧已北，莫不厌（饱）若鱼者。这四句五字句，一气贯下，借用郦生与任公子的两个典，说明自己志在济世任侠，然而却失意落魄。因而欲步任公子后尘，鄙弃名利，听任自然，相信自己会得到预想的结果。创主唐代的任氏之风俗。这就使李白少年时的形象与精神，活脱脱地展现在人们面前，同时也暗含着理想与志向同社会现实的矛盾，坚持理想志向，而绝不作势利小人，保持淳美的人性本色。体现着世不容己，己也弃世。他在《古风》（其十三）诗中也表现了与此相似思想：“君平既弃世，世亦弃君平。”暗示出失意落魄的主客观的原因，矛盾的双向性。接着诗人运用七言四句，由前面五言句式的音节短促与凝重，而转为音节舒缓与和平，抒写失意后的生活和行为。经常是饮酒抒忧，追逐徜徉，名山胜水，追求天真的人性美。从此逐渐使壮心与功名相分疏。这正像美好的兰花生在山谷中而不会遭人锄掉一样，保持着它的自然美；又正如围绕高山上端的白云，自由地翻卷与铺张。这四句是写入长安前的生活，暗示出以隐求仕，而不汲汲于功名。追求的是人性自由、适意生活的清真美，从名胜山水风景中吸取美的力量。兰生谷底是反用《三国志·蜀志·周群传》中“芳兰生门，不得不锄”的典故，暗示出在朝廷，权贵是容不得贤人君子的。兰花是比况贤人君子的。例如屈原《离骚》中香草美人的描写，比托贤人君子。贤人君子只有在山乡水国才有自己生存的天地，自由的王国。总之这八句诗是李白的自画像，自抒心志，真率自然，发自肺腑。为少年以后与入长安之前的李白作了评介，形神欲出。\n\n　　全诗的第二段是从“汉家天子驰驷马”至“象床绮席黄金盘”，共十二句，每六句分为一小节，又为一层意思。这段诗的前六句是写李白被征召入京与谒见唐玄宗的隆重盛况。汉家天子是代指唐家天子唐玄宗，派御用的高车四马，像当年汉武帝迎接从蜀地来的司马相如一样，迎接李白。李白进入九重宫门，于金殿上拜谒当今圣君皇帝。皇帝龙颜笑逐颜开，天下人就像沐浴春风一样，受到皇恩的抚育。金殿里左右站班的大臣都高呼万岁，叩拜皇帝、祝贺皇帝征召了一位隐逸失意的贤材。这六句诗是铺陈叙述，但又重点突出，突出皇帝的重视。以赤车驷马相迎，龙颜高兴，群臣高呼万岁等细节，渲染气氛，烘托自己的形象的高贵，超卓拔群，荣耀至极。然而这仅是谒见初的情景。接着诗人又用六句，描绘自己供奉翰林的情景，皇帝垂青，自己大展英才。自己供奉宫内翰林院，执笔草拟皇帝的诏书，受到皇帝的不时注目，焕发出赏识的眼光。宫内藏书的麒麟秘阁威严高峻，自己在这皇帝秘阁中读书，接受皇帝询问，没有谁可以得到这种荣誉，恐怕连看到这高峻的麒麟阁都难。回忆当初承受皇帝恩惠时，进入了右银台门内的翰林院供奉，又独自在金銮殿上草拟皇帝文件。出宫门随侍皇帝，乘有雕饰精美的马蹬与镶白玉的马鞍的御马，在宫中坐的是皇家椅子，用的是皇家御用黄金盘。这六句诗是说明自己志大才高，得到皇帝的信任，满面春风。荣极一时，盛极一时，享受到人臣的极誉。这六句诗采用间接描写，从皇帝眼睛垂顾到环境的烘托，传神地状出自己内心活动和心境昂奋。这与第一段落魄失意的心境构成了鲜明对比，然而这又是不慕名利，以高尚节行与大智大才，自然得到的荣誉。这无疑地是诗意发展、诗情的延伸。\n\n　　全诗第三段是从“当时笑我微贱者”至“可见羊何共和之”也是十二句，每六句为一小节，为一层意思。前六句是写被逐出长安，饱尝世态炎凉冷暖之苦。诗人说：回想我在朝廷时，原来笑话我出身卑贱而白眼看我的人，现在却一反常态请求我接见，与我交朋友，欢聚在一起。可是当一个早晨我上表章，托病请求还山时，旧日与我交欢相知心的人，没有几个人了。门前送我以礼，随后即关紧门。这些人就是有势就交，无势就改，反复无常。这六句表面上是写自己失势前后的人情关系的变化，透视出势利小人的丑态与趋炎附势的卑鄙灵魂。反映出民族的传统淳朴美德，正被势利小人所践踏，世风浇薄，孕育着社会危机。鄙视、悲愤，感叹之情与探求人生的传统美德等交识在一起，很能感发人意。“当时”，“畴昔”，“今日”相钩连、六句诗意脉一贯，曲折相续，对比鲜明，个性突出。后六句扣题，赞美从弟李之遥始终如一的交情。诗人对他说：对比之下，你的友情如山岳一样始终如一而心不改变，如云雾随着高山一样迷失掉它的所作所为，你不为邪恶云雾所动。云雾是象征着社会炎凉世态，邪恶势力。你与我之间情谊，如当年谢灵运与谢惠连兄弟间关系，才情相用。由此我更深刻地认识到“梦得‘池塘生春草’”这首诗的价值。随着社会阅历之深，而不断地增长它的价值。别后，希望你看到这从遥远地传递去的我的诗篇，也能像谢灵运登临海峤赋诗寄给他的族弟谢惠连一样，和像羊璿之，何长瑜一样的诗友相互唱和。前两句用比喻象征，描绘友情淳真。后四句用典故，谢灵运赏识他从弟惠连之才，相互切磋切琢。当他写《登池上楼》诗时，于梦中见到谢惠连而忽然得到“池塘生春草”这一名句。羊璿之、何长瑜是谢灵运的诗友，谢灵运又作《登临海峤初发疆中作与从弟惠连可见羊何共和之》一诗。李白用典比况自己与李之遥兄弟情谊，知音友情。预想李之遥接到此诗，诗友共唱和，又颇感欣慰。第二段所引爆出的悲叹之情迅速转化为平和愉悦，为世上有知音的兄弟而自豪!于此结束全篇，余音绕梁，不绝如缕。\n\n　　全诗看似平常，无动人的描写，又乏雕饰词句。章法自然，以情运思，构成了失意——得意——失意——自慰的意脉，于平易中数见曲折，自然天成。\n\n　　全诗如数家珍，娓娓道来，看似竹筒倒豆，事无巨细，倾泄而出；实则匠心独运，以客观环境与人物描写，兼巧用典故，从今昔对比中，以刻画自己的心象，从两种对立的人格中，歌颂淳朴清真的人格美，以自己与从弟之遥当之。反衬与贬抑势利小人的丑恶人格及其卑鄙的灵魂。进而透视出世风浇薄，贤者被弃的社会悲剧，表现盛唐社会由盛转衰的征兆。这种平易自然，亲切感人，于不见技法中，悟出社会人生的道理，非常深刻。\n\n　　其二诗则转笔重点写李之遥。宋本《李太白文集》在此诗题自注：“时因饮酒过度贬武陵，后诗故赠。”全诗由此生发，刻画李之遥的性格与形象，及其被贬的原因和诗人评价。在组诗结构上是对前诗作重要的补叙，使李之遥形象光彩照人，与李白正好如一对玉人，相映相衬，天真淳美，然而却都不容于世。\n\n　　全诗八句，前四句为一个层次，后四句又为一个层次，意脉绵密，严整无痕。\n\n　　前四句写李之遥思想与性格，作者并不直接述出，而是采用以古托今的笔法，在古今人相映衬中，托出南平太守李之遥如魏晋初的大诗人阮籍，不满意朝臣的倾轧与司马氏诛杀异己，而以酒浇愁，冷眼注视现实，佯狂处世。淳美人性，托之于美酒，而无意于功名利禄，不以专城的郡守职务为重。这与魏晋时的阮籍是十分相似的，故诗人说今古两步兵。阮籍拜东平相，不以政事为务，沉醉日多。听说步兵厨人善酿，有贮酒三百斛，乃求为步兵校尉。人称阮步兵。这四句以古今对比手法，既刻画李之遥的形象与性格，也暗喻伤酒而被贬。伤酒又如阮籍不满意现实，而又无力挽狂澜，以酒消忧。开端两句平平叙出，但却拓展时空，今古相接，比之单写李之遥却有较丰富的意蕴，赞美之情是今亦是古，今古相重，凝重浓厚。\n\n　　后四句一转，写李之遥因不顾专城，只爱酒，而被贬武陵。使诗人联想陶潜所写的《桃花记源并诗》，于是就化用这一典故，铸成后四句的美好诗意。诗人说：你去的武陵，就是晋大诗人陶潜所写的桃花源，不知你今后要到这里多少地方寻找桃花源世界。那里的避世乱的秦人，像故旧的相识，出门笑脸相迎你。这四句诗再用陶潜理想与人格托喻李之遥，再次渲染他的人格美，追求理想社会境界。这一用典使李之遥形象增加了光辉。更可贵的是使典故内容与诗意融合无间，塑造一个优美的社会环境。自然美、人情美异于冷峻的现实。注入了诗人的浪漫理想，然而它又植根于现实，并非空中楼阁，虚无飘渺，可望不可即。\n\n　　这首诗热情洋溢，气贯全诗，逐层蓄积，赞美，回护，预测，构成感情的流程，心潮逐浪高。古今未来时空相续，关心体贴挚爱之情，无以附加。然而这一切又是那么自然，不深思就体味不到这种深邃的情思。\n\n　　这两首诗一长一短，看似不相称，实则各自得体，各尽所职，言近旨远，相得益彰，俱为精品。可参读《经乱离后天恩流夜郎忆旧游书怀赠江夏韦太守良宰》等诗，以对此诗有更深刻的理解。', poem_tags = '叙事,友谊,劝诫' WHERE poem_title = '赠从弟南平太守之遥二首' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '要想升天飞仙，千万不要骑龙，要想游历河川，千万不能骑着老虎。朋友相交应不分贵贱，就像东汉的严陵和光武帝一样。可惜周公执政时是如此的贤明，管叔和蔡叔为什么还苦苦相逼，不能相容呢？汉代歌谣中说“一尺布，尚可缝；一斗粟，尚可舂。”汉文帝却容不下淮南王，将他流放。骨肉兄弟尚且如同路人，我要结交的知己哪里会有呀？朋友虽然表面上亲密无间，可是心却如同隔着千重山、千重海。和他们相交时，就像面对着九疑山一样，让人分不清真假，茫然找不到边际。许多花长在一个树枝上，必然会早早凋谢，桃李开花虽然很美丽，但不如松柏能四季常青，朋友也是一样。管仲和鲍叔牙这样彼此信任的朋友早已死去，不知道后世还有没有人像他们一样，结交朋友能够贵贱不相移。', poem_notes = '严陵：严光，字子陵，东汉余姚人。\n周公：周文王姬昌第四子。因封地在周（今陕西岐山北），故称周公或周公旦。是西周初期杰出的政治家、军事家和思想家。\n管蔡：管叔和蔡叔，是周武王的弟弟。\n“汉谣”两句：语出自《史记·淮南衡山列传》：“民有作歌歌淮南厉王曰：一尺布，尚可缝；一斗粟，尚可舂。兄弟二人不能相容。”讲的是汉文帝与淮南王之间的兄弟恩怨故事。\n九疑峰：山名。在湖南宁远县南。其山九谷皆相似，故称“九疑”。\n管鲍：春秋时期的政治家管仲和鲍叔牙。', poem_tags = '友情,哲理' WHERE poem_title = '箜篌谣' AND poem_author = '李白';
UPDATE edu_poem SET poem_tags = '写景,抒情' WHERE poem_title = '浣溪沙·百亩中庭半是苔' AND poem_author = '王安石';
UPDATE edu_poem SET poem_tags = '写景,西湖,喜悦' WHERE poem_title = '朝天子·西湖' AND poem_author = '徐再思';
UPDATE edu_poem SET poem_tags = '初中文言文,寓理,教育,故事' WHERE poem_title = '墨子怒耕柱子' AND poem_author = '墨子及弟子 撰';
UPDATE edu_poem SET poem_translation = '红叶片片沉醉于动人的秋色，碧溪潺潺在夜里弹奏起琴弦。\n美好的日子逝去不可能再来，凄风苦雨无限让人度日如年。', poem_notes = '叶：一作“树”。\n碧溪：绿色的溪流。\n佳期：美好的时光。\n杳（yǎo）：昏暗、遥远，没有尽头。', poem_tags = '写景,抒情,愁苦' WHERE poem_title = '题玉泉溪' AND poem_author = '湘驿女子';
UPDATE edu_poem SET poem_tags = '古诗里的十二个月' WHERE poem_title = '冬至宿杨梅馆' AND poem_author = '白居易';
UPDATE edu_poem SET poem_translation = '龙吐出的气形成云，云本来不比龙灵异。但是龙乘着这股云气，可以在茫茫的太空中四处遨游，接近日月，遮蔽它的光芒，震撼起雷电，变化神奇莫测，雨水降落在大地，使得山谷沉沦。这云也是很神奇灵异的呢！\n　　云，是龙的能力使它有灵异的。至于龙的灵异，却不是云的能力使它这样子的。但是龙没有云，就不能显示出它的灵异。失去它所凭借的云，实在是不行的啊。\n　　多么奇妙啊，龙所凭借依靠的，正是它自己造成的云。《周易》说：“云跟随着龙。那么既然叫做龙，就应该有云跟随着它啊！”', poem_notes = '龙说：选自《杂说》，为其首篇，题目为编者加。\n嘘：喷吐。龙吹气成云是古代的一种传说。\n固：本来、当然。\n景：通“影”。\n神变化：语出《管子·水地篇》“龙生于水，被五色而游，故神。欲小则化为蚕（虫蜀）[说明，此为一个字zh ]，欲大则藏于天下，欲上则凌于云气，欲下则入于深泉，变化无日，上下无时，谓之神。”\n水：名词用作动词，下雨。\n汩：淹没\n云从龙：语出《易·乾·文言》“云从龙，风从虎，圣人作而万物睹。”从：随，跟随。\n伏：遮蔽。\n无以：没有可以用来。\n信：确实、的确。', poem_tags = '古文观止,议论,寓理' WHERE poem_title = '杂说一·龙说' AND poem_author = '韩愈';
UPDATE edu_poem SET poem_tags = '爱情,思念' WHERE poem_title = '如果' AND poem_author = '席慕容';
UPDATE edu_poem SET poem_translation = '一个人深居简出过着清幽的日子，俯瞰夹城，春天已去，夏季清朗。\n小草饱受雨水的浸淹，终于得到上天的怜爱，雨过天晴了。\n登上高阁，凭栏远眺，天高地迥，夕阳冉冉的余晖透过窗棂。\n越鸟的窝巢已被晒干，它们的体态也恢复轻盈了。', poem_notes = '夹城：城门外的曲城。\n幽草：幽暗地方的小草。\n并：更。高阁：指诗人居处的楼阁。迥：高远。\n微注：因是晚景斜晖，光线显得微弱和柔和，故说“微注”。\n越鸟：南方的鸟。', poem_appreciation = '首联说自己居处幽僻，俯临夹城，时令正值清和的初夏。乍读似不涉题，上下两句也不相属，其实“俯夹城”的“深居”即是览眺晚晴的立足点，而清和的初夏又进而点明了晚晴的特定时令，不妨说是从时、地两方面把诗题一体化了——初夏凭高览眺所见的晚晴。\n\n　　初夏多雨，岭南尤然。久雨转晴，傍晚云开日霁，万物顿觉增彩生辉，人的精神也为之一爽。这种景象与感受，本为一般人所习见、所共有。诗人的独特处，在于既不泛泛写晚晴景象，也不作琐细刻画，而是独取生长在幽暗处不被人注意的小草，虚处用笔，暗寓晚晴，并进而写出他对晚晴别有会心的感受。久遭雨潦之苦的幽草，忽遇晚晴，得以沾沐余辉而平添生意，诗人触景兴感，忽生“天意怜幽草”的奇想。这就使作为自然物的“幽草”无形中人格化了，给人以丰富的联想。诗人自己就有着类似的命运，故而很自然地从幽草身上发现自己。这里托寓着诗人的身世之感。他在为目前的幸遇欣慰的同时不期然地流露出对往昔厄运的伤感，或者说正由于有已往的厄运而倍感目前幸遇的可慰。这就自然引出“人间重晚晴”，而且赋予“晚晴”以特殊的人生含义。晚晴美丽，然而短暂，人们常在赞赏流连的同时对它的匆匆即逝感到惋惜与怅惘。然而诗人并不顾它的短暂，而只强调“重晚晴”。从这里，可以体味到一种分外珍重美好而短暂的事物的感情，一种积极、乐观的人生态度。\n\n　　颔联写得浑融概括，深有托寓，颈联则转而对晚晴作工致的描画。这样虚实疏密相间，诗便显得弛张有致，不平板，不单调。雨后晚晴，云收雾散，凭高览眺，视线更为遥远，所以说“并添高阁迥”（这高阁即诗人居处的楼阁）。这一句从侧面写晚晴，写景角度由内及外，下句从正面写，角度由外及内。夕阳的余晖流注在小窗上，带来了一线光明。因为是晚景斜晖，光线显得微弱而柔和，故说“微注”。尽管如此，这一脉斜晖还是给人带来喜悦和安慰。这一联通过对晚景的具体描绘，写出了一片明朗欣喜的心境，把“重”字具体化了。\n\n　　尾联写飞鸟归巢，体态轻捷，仍是登高览眺所见。“巢乾”、“体轻”切“晴”，“归飞”切“晚”。宿鸟归飞，通常是触动旅人羁愁的，这里却成为喜晴情绪的烘托。古诗有“越鸟巢南枝”之句，这里写越鸟归巢，带有自况意味。如果说“幽草”是诗人“沦贱艰虞”身世的象征，那么，“越鸟”似乎是眼前托身有所、精神振作的诗人的化身。\n\n　　作为一首有寓托的诗，《晚晴》的写法更接近于“在有意无意之间”的“兴”。诗人也许本无托物喻志的明确意图，只是在登高览眺之际，适与物接而触发联想，情与境谐，从而将一刹那间别有会心的感受融化在对晚晴景物的描写之中，所以显得特别自然浑成，不着痕迹。', poem_tags = '夏天,登高,写景,抒情' WHERE poem_title = '晚晴' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_tags = '宋词三百首,元宵节,抒情' WHERE poem_title = '解语花·上元' AND poem_author = '周邦彦';
UPDATE edu_poem SET poem_tags = '初中文言文,寓理,故事' WHERE poem_title = '陶侃惜谷' AND poem_author = '司马光';
UPDATE edu_poem SET poem_translation = '往西前行已经很远了，仍然没有穷尽之时，回首东望又不知何时才能返回家乡。\n成天面对的都是狂风和暴雪，放眼望去直达天际的是连绵重叠的沙漠和山丘。\n我从事公职已历两年，曾两度经过阳关。\n想念你却见不得你，分别之后，我的头发都已经斑白了。', poem_notes = '⑴殊：很，极。\n⑵阳关：古关名，西汉置，在今甘肃省敦煌县西南古董滩附近。\n⑶斑：斑白。', poem_tags = '抒情,思乡,愁苦' WHERE poem_title = '寄宇文判官' AND poem_author = '岑参';
UPDATE edu_poem SET poem_translation = '殷王武丁神勇英武，是他兴师讨伐荆楚。王师深入敌方险阻，众多楚兵全被俘虏。扫荡荆楚统治领土，成汤子孙功业建树。\n你这偏僻之地荆楚，长久居住中国南方。从前成汤建立殷商，那些远方民族氐羌，没人胆敢不来献享，没人胆敢不来朝王。殷王实为天下之长。\n上天命令诸侯注意，建都大禹治水之地。每年按时来朝来祭，不受责备不受鄙夷，好好去把农业管理。\n上天命令殷王监视，下方人民恭谨从事。赏不越级罚不滥施，人人不敢怠慢度日。君王命令下达诸侯，四方封国有福享受。\n殷商都城富丽堂皇，它是天下四方榜样。武丁有着赫赫声名，他的威灵光辉鲜明。既享长寿又得康宁，是他保佑我们后人。\n登上那座景山山巅，松树柏树挺拔参天。把它砍断把它远搬，削枝刨皮加工完善。长长松木制成方椽，楹柱排列粗壮溜圆。寝庙落成神灵安恬。', poem_notes = '挞（tà）：勇武貌。殷武：即殷高宗武丁，殷朝的一位中兴之主，曾任用贤人傅说（yuè）为相，并不断对西北的贡方、土方、鬼方、羌、周族等用兵，在位五十九年。\n荆楚：即荆州之楚国。《史记·楚世家》：“吴回生陆终。陆终生子六人，其长曰昆吾；二曰参胡；三曰彭祖；四曰会人；五曰曹姓；六曰季连，芈姓，楚其后也。昆吾氏，夏之时尝为侯伯，桀之时汤灭之。彭祖氏，殷之时尝为侯伯，殷之末世灭彭祖氏。…周文王之时，季连之苗裔曰鬻熊。鬻熊子事文王，蚤（早）卒。其子曰熊丽。熊丽生熊狂，熊狂生熊绎。熊绎当周成王之时，举文、武勤劳之后嗣，而封熊绎于楚蛮，封以子男之田，姓芈氏，居丹阳。”\n罙（shēn）：同“深”。古深字本作“突”，隶变作“罙”。\n裒（póu）：“捊”之别体，通“俘”，俘获。\n汤孙：指商汤的后代武丁。绪：功业。\n女（rǔ）：同“汝”，你。\n乡（xiàng）：通“向”。\n自彼氐羌：自，犹“虽”；氐、羌，散居在今西北狭西、甘肃、青海一带的边远民族。\n常：长。“常”是“尚声”字，与“长”字古音同部，故可释为“长”。\n多辟（bì）：众多诸侯国君。\n绩：通“迹”。\n来辟：犹言“来王”、“来朝”。\n祸适：读同“过谪”，义为谴责。\n解（xiè）：同“懈”。\n严（yǎn）：同“俨”，敬谨。\n不僭（jiàn）不滥：毛传：“赏不僭、刑不滥也。”\n封：毛传：“大也。”\n商邑：指商朝的国都西亳。《史记·殷本纪》正义：“汤自南亳迁西亳，仲丁迁隞，河亶甲居相，祖乙居耿，盘庚渡河，南居西亳，是五迁也。”殷高宗武丁是盘庚之后的中兴之主，其时建都西亳，在今河南偃师。翼翼：都城盛大貌。\n极：准则。\n濯（zhuó）濯：形容威灵光辉鲜明。\n后生：犹言后代子孙。\n景山：陈奂《诗毛氏传疏》：“考今河南偃师县有缑氏城，县南二十里有景山，即此诗之景山也。”\n丸丸：形容松柏条直挺拔。\n方：是，乃。斲（zhuó）：同“斫”，砍。虔：马瑞辰《毛诗传笺通释》以为“削”。此指用刀削木。\n桷（jué）：方形的椽子。梃（chān）：木长貌。\n旅：当依毛传释为“陈列”。有闲：闲闲，大貌。\n寝：此指为殷高宗所建的寝庙。古时的寝庙分两部分，后面停放牌位和先人遗物的地方叫“寝”，前面祭祀的地方叫“庙”。孔：很。', poem_appreciation = '《商颂·殷武》这首诗的主旨，是通过高宗寝庙落成举行的祭典，极力颂扬殷高宗继承成汤的事业所建树的中兴业绩。\n\n　　全诗共六章，一、四、五章每章六句，二、六章每章七句，三章五句。前五章写殷高宗武丁中兴之事，最后一章写高宗寝庙落成的情景。\n\n　　这首诗歌在艺术表现上的突出特色，是各章都有它描写的侧重点。第一章言武丁伐楚之功。“挞彼殷武，奋伐荆楚”二句，表现了武丁对楚用兵的勇猛神速。“罙（深）入其阻，裒荆之旅”，写出武丁的军队是在突破险阻中取得节节胜利。“有截其所，汤孙之绪”，特别点明武丁之所以能征服荆楚之地，那是因为他是成汤的后世子孙，理应有所作为。第二章写武丁对荆楚的训诫。“维女（汝）荆楚，居国南乡（向）”二句，从荆楚所处的地理位置，指出它理应俯首听命。“昔有成汤，自彼氐羌。莫敢不来享，莫敢不来王，曰商是常。”这是以成汤征服氐、羌的先例来告诫荆楚归服，可谓是“刚柔并举”。第三章只有五句，可能有脱文，是写四方诸侯来朝。说殷武丁秉承“天命”统治诸侯，因之诸侯入国朝见天子、在封地勤治农事，都是他们应尽的职守。第四章，进一步申述武丁是受“天命”的中兴之主，人民百姓只能安分守己，按商朝的政令行动。第五章，写商朝的国都西亳地处中心地带的盛况，这里曾是中兴之主殷武丁运筹帷幄、决胜千里的地方，故特别用“商邑翼翼，四方之极”两句诗来渲染它，而武丁在位长达五十九年，说他“赫赫厥声，濯濯厥灵”，并不过分。末章描写修建高宗寝庙的情景，用“陟彼景山，松柏丸丸”两句诗作比兴，不但形象生动，而且有象征意义，象征殷武丁的中兴业绩垂之不朽。\n\n　　这首诗在用韵上也有其特色。第一章句句用韵，“武”“楚”“阻”“旅”“所”“绪”同叶鱼部韵；第二章除“维女荆楚”一句不用韵，其余句句用韵，“乡”“汤”“羌”“享”“王”“常”同叶阳部韵；第三章句句用韵，“辟”“绩”“辟”“适（谪）”“解（懈）”是锡支通韵；第四章句句用韵，前后换韵，“监”“严”“滥”“遑”是谈阳合韵，“国”“福”叶职部韵；第五章句句用韵，前后换韵，“翼”“极”叶职部韵，“声”“灵”“宁”“生”叶耕部韵；最后一章句句用韵，“山”“丸”“迁”“虔”“梃”“闲”“安”叶元部韵。由于末章用元韵一韵到底，颇能渲染出宗庙落成的喜庆气氛。', poem_tags = '诗经,祭祀,颂歌' WHERE poem_title = '商颂·殷武' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '玉真公主真是真人啊，时时来往于华山太华峰修道。\n一清早就起来叩齿鸣天鼓，练气时双龙迅速腾起。\n不断将全身元气聚集，如电如虹，行踪如白云来去飘忽。\n何时去少室山？在那里一定可以与王母娘娘相逢。', poem_notes = '玉真仙人：玉真公主。\n太华：华山。\n鸣天鼓：道家的一种法术。\n飚欻（biāoxū）：迅疾貌。腾龙，犹驾龙，乘龙。\n弄电：《太平御览》卷一三引《汉武内传》：“西王母曰：东方朔为太山仙官，太仙使至方丈，助三天司命，朔但务山水游戏，擅弄雷电，激波扬风，风雨失时。”\n少室：在河南省登封县北，主峰玉寨山为篙山最高峰。\n王母：即西王母。', poem_tags = '写人,赞美' WHERE poem_title = '玉真仙人词' AND poem_author = '李白';
UPDATE edu_poem SET poem_translation = '我那些旧日的朋友都音信杳然，居官卑微，空度了几多年华。你的节操直追先贤，你雄浑的诗文的当世最好的。\n你的厅堂之中坐满了食客，对外还欠着许多酒债。你从不言及财产积累之事，与朋友共衣，即使穿破了也毫不在意。\n你供职幕府，随军转徙，出入于关隘山峰之间。苦战之时不以所谓豪情壮志为意，瞬息间并能拿出安定边塞的妙计。\n云雾、沙尘在风中回旋、聚散，天穹空旷高远。月盛星高，战斗十分频繁，当此之时唐军将领却十分骄纵，而胡人军队锐气正盛。\n沙漠渊深阻断冷陉，雪天里天光暗淡，辽阳城门紧闭。本来说要消弭兵患，却突然惊讶地发现自己已深陷敌阵。\n先期归来的军队回来时说是打了胜仗，而逃回的骑兵却传来战败的实况。军中远远地传来求援的文书，而主帅已在长安城中建起了自己的私第。\n朝廷徒有好士之名，受到朝廷恩宠的败军将领反而先行返回了长安。将领不要争抢部署的功劳，部署不应凭借将军的威势。\n我们的冬季之月相遇，惆怅地望着远方的海边。解下长剑送给你，你将整肃衣裳踏上远行之路。\n我离开家时就已充满了忧虑，到了这里又长期遭受阻绊。我虽没有周济当代的谋略，却还算兢兢业业。\n随着波浪或清或浊，和物体一样或丑或美。闭着眼睛想着那栖居于青岩之间，忘却那追逐功名之事。\n我一直都希望能与贤良清廉之人为伍，与品德高尚的贤者相伴。为何我与志行高远之人相伴，却仍然才质平平。\n我一直十分谨慎于义利的取舍，哪里敢怠慢平素做人的原则？此时我热情地招待你，可惜又要痛苦地和你分别。\n我虽遇上好时候，惭愧的是不能树立美好的名誉和节操。到了赵国却不是去排忧解难，到了燕国也没有达到游说的目的。\n浩大的歌声正回荡在天空，遒劲的鸟儿正想着凌空飞翔。你将如奇异的大鹏鸟那样，忽然间展翅高翔，我且学习那蝉蜕去外壳一般隐居去吧。', poem_notes = '⑴王十七：即幽州节度使张守珪的管记王悔。管记：掌管文牍的官员。\n⑵薄宦：居官低微。\n⑶曩：过去，以往。\n⑷产业：财产。\n⑸飘飖：即飘摇。\n⑹立谈：指时间短促之间。\n⑺月盛：月满之时。\n⑻冷陉：山脉名称，在今辽宁开原。\n⑼欃枪：彗星的别名。\n⑽已筑长安第：意指边将不关心国家边防，只关注自己的私产。\n⑾宠鹤：语见《左传·闵公二年》：“卫懿公好鹤，鹤有乘轩者。”\n⑿海裔：海边。\n⒀缅：思虑的样子。\n⒁临深：面临深渊。\n⒂褐衣拜：以平民的身份入拜朝中。\n⒃水石：清水、白石，比喻贤良清廉之人。兰蕙：两种香草，比喻品质高尚者。\n⒄薄：接近。松筠：松树和竹子，比喻志行高洁之人。\n⒅款曲：衷情。\n⒆适赵：反用鲁仲连为赵国排忧解难的典故。游燕：反用苏秦到燕国游说的典故。\n⒇鹏抟：大鹏展翅高飞，典出《庄子·逍遥游》。蝉蜕：喻指远离尘俗。', poem_tags = '送别,抒怀,怀才不遇' WHERE poem_title = '赠别王十七管记' AND poem_author = '高适';
UPDATE edu_poem SET poem_tags = '抒怀,隐居' WHERE poem_title = '同王昌龄裴迪游青龙寺昙壁上人兄院集和兄维' AND poem_author = '王缙';
UPDATE edu_poem SET poem_translation = '黄莺的啼声惊扰了诗人的美梦，醒来之后眼泪冲淡了昨晚刚化的淡妆。\n夜晚时分，竹林熙熙，月亮也显得那么的渺小。江边是那么寂静，夜晚的烟雾也显得格外浓重。\n门外的燕子衔着泥土筑巢，蜜蜂在采花培养着蜂蜜。\n只有诗人一个人无限愁思，一个人低语压低了枝松。', poem_notes = '轻妆：淡妆。\n薄：即淡薄之意。\n烟：指雾气。觜：即嘴。\n蕊：即花蕊。\n亚：通“压”，枝松呈低垂状态。', poem_tags = '写景,抒情,孤寂' WHERE poem_title = '暮春有感寄友人' AND poem_author = '鱼玄机';
UPDATE edu_poem SET poem_tags = '植物' WHERE poem_title = '植灵寿木' AND poem_author = '柳宗元';
UPDATE edu_poem SET poem_translation = '离开家乡后客宿在并州这个地方已经有十年，我回归的心日日夜夜在思念着故乡咸阳。\n当初为了博取功名图谋出路，千里迢迢渡过桑乾河，现在并州已经成了我的第二家乡。', poem_notes = '旅：旅行。次：临时住宿。朔方：古都名，自西汉始建，至唐代，辖区多变，治所不一。桑干河以北，属朔方地区。\n舍：居住。并州：即今太原一带。十霜：一年一霜，故称十年为“十霜”。\n咸阳：陕西咸阳是作者故乡。\n无端：没有缘由，不知为什么。桑乾水：即桑干河，源出西北部管涔山，向东北流入河北官厅水库。相传，在每年桑椹成熟时干涸，故有此名。', poem_appreciation = '在许多诗集中，这首诗都归在贾岛名下，其实是错误的。因为贾岛是范阳（今北京市大兴县）人，不是咸阳（今陕西省咸阳市）人，而在贾岛自己的作品以及有关这位诗人生平的文献中，从无他在并州作客十年的记载。又此诗风格沉郁，与贾诗之以清奇僻苦见长者很不相类。《元和御览诗集》认为它出于贞元间诗人刘皂之手。虽然今天对刘皂的生平也不详知，但元和与贞元时代相接，《元和御览诗集》的记载应当是可信的。因此定其为刘作。\n\n　　此诗题目，或作《渡桑乾》，或作《旅次朔方》。前者无须说明，后者却要解释一下。朔方始见《尚书·尧典》，即北方。但同时又是一个地名，始见《诗经。小雅。出车》。西汉置朔方刺史部（当今内蒙古自治区及陕西省的一部分，所辖有朔方郡），与并州刺史部（当今山西省）相邻。桑乾河并不流经朔方刺史部或朔方郡，所以和朔方之地无关。并州在唐时是河东道，桑乾河由东北而西南，流经河东道北部，横贯蔚州北部，云、朔等州南部。这些州，当今雁北地区。由此可见，诗题朔方，乃系泛称，用法和曹植《送应氏》“我友之朔方，亲昵并集送”一样。而刘皂客舍十年之并州，具体地说，乃是并州北部桑乾河以北之地。\n\n　　诗的前半写久客并州的思乡之情。十年是一个很久的时间，十年积累起的乡愁，对于旅人来说，显然是一个沉重的负担。所以每天每夜，无时无刻不想回去。无名氏《杂诗》云：“浙江轻浪去悠悠，望海楼吹望海愁。莫怪乡心随魄断，十年为客在他州。”虽地理上有西北与东南之异，但情绪相同，可以互证。后半写久客回乡的中途所感。诗人由山西北部（并州、朔方）返回咸阳，取道桑乾流域。无端，即没来由。更渡，即再渡。这“无端更渡”四字，乃是关键，要细细体会。十年以前，初渡桑乾，远赴并州，是为的什么呢？诗中没有说。而十年以后，更渡桑乾，回到家乡，又是为的什么呢？诗中说了，说是没来由，也就是自己也弄不清楚是怎么一回事。果真如此吗？不过是极其含蓄地流露出当初为了博取功名，图谋出路，只好千里迢迢，跑到并州作客，而十年过去，一事无成，终于仍然不得不返回咸阳家乡这种极其抑郁难堪之情罢了。但是，出乎诗人意外的是，过去只感到十年的怀乡之情，对于自己来说，是一个沉重的负担，而万万没有想到，由于在并州住了十年，在这久客之中，又不知不觉地对并州也同样有了感情。事实上，它已经成为诗人心中第二故乡，所以当再渡桑乾，而回头望着东边愈去愈远的并州的时候，另外一种思乡情绪，即怀念并州的情绪，竟然出人意外地、强烈地涌上心头，从而形成了另外一个沉重的负担。前一矛盾本来似乎是惟一的，而“无端更渡”以后，后一矛盾就突了出来。这时，作者和读者才同样感到，“忆咸阳”不仅不是唯一的矛盾，而且“忆咸阳”和“望并州”在作者心里，究竟哪一边更有分量，也难于断言了。以空间上的并州与咸阳，和时间上的过去与将来交织在一处，而又以现在桑乾河畔中途所感穿插其中，互相映衬，宛转关情，表达了诗人心中对故乡的怀念。', poem_tags = '思乡' WHERE poem_title = '旅次朔方 / 渡桑干' AND poem_author = '刘皂';
UPDATE edu_poem SET poem_tags = '生活,闲适,抒情' WHERE poem_title = '满江红·无利无名' AND poem_author = '张昪';
UPDATE edu_poem SET poem_translation = '往西前行已经很远了，仍然没有穷尽之时，回首东望又不知何时才能返回家乡。\n成天面对的都是狂风和暴雪，放眼望去直达天际的是连绵重叠的沙漠和山丘。\n我从事公职已历两年，曾两度经过阳关。\n想念你却见不得你，分别之后，我的头发都已经斑白了。', poem_notes = '⑴殊：很，极。\n⑵阳关：古关名，西汉置，在今甘肃省敦煌县西南古董滩附近。\n⑶斑：斑白。', poem_tags = '抒情,思乡,愁苦' WHERE poem_title = '寄宇文判官' AND poem_author = '岑参';
UPDATE edu_poem SET poem_translation = '注释 翠眉：即翠黛。古代女子用螺黛（一种青黑色矿物颜料）画眉，故称眉为“翠黛”。', poem_tags = '婉约,妇女,春愁,相思' WHERE poem_title = '阮郎归·杏花疏雨洒香堤' AND poem_author = '佟世南';
UPDATE edu_poem SET poem_translation = '远方客人来造访，驾车白马真健壮。随从人员众且多，个个品德都贤良。客人已经住两天，多住几天增感情。给他拿条绊马索，斑竹马儿不让行。客人走时远远送，左右热情慰劳他。既用大德来待客，上天降福多又大。', poem_notes = '客：指宋微子。周既灭商，封微子于宋，以祀其先王，微子来朝祖庙，周以客礼待之，故称为客。\n亦白其马：亦，语助词。白为纯洁之色，殷商尚白，以白马为美，故来朝作客也乘白马。一说白马是客人带来的礼物。\n有萋有且（jū）：即“萋萋且且”，形容随从众多的样子。\n敦琢：意为雕琢，有选择美好之意。雕琢本为治玉之名，这里形容其随从众臣都是贤者。旅：通“侣”，指伴随微子的宋国大夫。\n宿宿：住一夜谓之“宿”，宿而又宿，则是两夜。\n信信：住两夜（再宿）谓之“信”。或谓宿宿为再宿，信信为再信，亦可通。\n言：语助词。授之絷（zhí）：给他绳索。絷，绳索。\n絷：本义为绳索，用作动词。此处是说给他绳索，绊住马足，表示要留住客人。\n薄言：发语词。追：意为饯行，也可以解为追送。\n左右：指天子之左右群臣。绥之：安抚客人。\n淫：盛，大。威：德。淫威，意谓大德，含厚待之义。\n孔：甚，很。夷：大。', poem_tags = '诗经,宴会,乐歌' WHERE poem_title = '周颂·有客' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '首词的上片写女主人及其扇的特点。下片写扇上的水月梅图画。本词是咏女主人的扇，但女主人是谁？杨铁夫《吴梦窗词笺释》认为是去姬，他说：“此扇必去姬所遗物，为陈藏一所绘者。”俞陛云《唐五代两宋词选释》认为此词“为道女题扇而作”。吴文英词中是有为道女题扇之作的，如《朝中措·题阑室道女扇》。从本词内容来看，这是题陈藏一所藏或所绘的道女扇的一首词。\n\n　　这首词的主旨是题扇，主要是歌咏扇上的“水月梅”图画。全词在描写扇的主人、扇的质料以及扇的图画时，都强调了它的清白、纯洁的特点。陈廷焯《白雨斋词话》说：“梦窗精于造句，超逸处，则仙骨珊珊，洗脱凡艳。”这首词正是具备这种超逸风格，词', poem_tags = '咏物' WHERE poem_title = '极相思·题陈藏一水月梅扇' AND poem_author = '吴文英';
UPDATE edu_poem SET poem_tags = '柳树,写景,愿望' WHERE poem_title = '原隰荑绿柳' AND poem_author = '温庭筠';
UPDATE edu_poem SET poem_translation = '注释 雊，读如够，野鸡叫。 转薄，回旋停泊。薄，通“ 泊 ”。', poem_appreciation = '此诗写军旅生活的艰辛。薇，野菜，即野豌豆苗。白天我们到山上去采野豌豆苗，因为到黄昏的时候会很饿。溪谷中风很大，又有霜露打湿大家的衣裳，真是非常寒冷。野鸡的叫声遍布山野，猿猴在相互追逐。\n\n　　在这样的荒郊野外，不免使人回望故乡，然而，故乡又在哪里？忧郁如石头一般垒积胸中。每座山都有山崖，每棵树都有树枝，可我内心的忧愁又是从哪里来的呢？没有人知道。\n\n　　人生不过是暂时寄托于人世，何必如此忧愁呢？我现在不快乐，时光也照样流逝。就像河里的那一只小舟，随着水波流转，也不知道会停在哪里，这就好比是我们的人生啊，谁也不知道自己会在哪里停泊。\n\n　　还是披上我的皮裘，骑着良马，在飞驰中暂时地忘却这人生的烦恼吧。\n\n　　从此诗我们可以看到，曹丕也是一个颇有诗意的人。在远离故土的荒郊野外，不免会产生莫名的忧愁，但这忧愁从何而来、到何而止，我们谁也不知道。而这人生，似乎也正如这忧愁一般，不知从何而来，也不知到何而止。因而，还是暂时地忘却吧，不要去想它。', poem_tags = '乐府,军旅,生活' WHERE poem_title = '善哉行·其一' AND poem_author = '曹丕';
UPDATE edu_poem SET poem_tags = '写景,抒情,怀人,友人' WHERE poem_title = '齐天乐·吴山望隔江霁雪' AND poem_author = '厉鹗';
UPDATE edu_poem SET poem_tags = '咏物,写雪,羁旅,抒怀' WHERE poem_title = '上林春令·十一月三十日见雪' AND poem_author = '毛滂';
UPDATE edu_poem SET poem_translation = '注释 涌金门：西湖地名。 小瀛州：西湖中小岛。 红船：彩饰游船，即“画舸”。', poem_tags = '寒食节,西湖,写景' WHERE poem_title = '诉衷情·寒食' AND poem_author = '仲殊';
UPDATE edu_poem SET poem_tags = '忧虑,感叹,嘲讽' WHERE poem_title = '忆昔' AND poem_author = '韦庄';
UPDATE edu_poem SET poem_translation = '节令风物不断递换，变化常新；痴心儿女，你们为什么要苦苦地挽留春天？\n那五彩缤纷的花朵凋谢又有什么可恨？夏天的树木，浓密葱绿，不也一样使你合意欢心！', poem_notes = '晦日：农历每月最后的一天。\n节物：各个季节的风物景色。\n儿女：这里泛指男女。\n芳菲：香花芳草。\n何须：何必，何用。\n可人：称人心意。', poem_appreciation = '文人伤春，似乎是永恒的主题，春风春雨，落花垂柳，引起过多少诗人感叹。三月晦日，是春天的最后一天，更难免激起诗人无计留春住的愁思。唐诗人贾岛有首著名的《三月晦日赠刘评事》诗云：“三月正当三十日，风光别我苦吟身。共君今夜不须睡，未到晓钟犹是春。”表现的就是浓重的惜春情绪。秦观这首绝句，与贾岛诗一样，也是通过议论，表达春将逝去时的感想。但秦诗一反旧例，没有悲伤的情调，却是顺其自然，豁达通变。\n\n　　诗富有哲理，蕴含“理趣”。“三月晦日”，即暮春三月的最后一天，过了这天，意味着时令进入夏季。春去的伤感，对于情感敏锐的人而言，不言而喻。春去的伤感，对于情感敏锐的人而言，不言而喻。但这首诗，却反其道而行之，写出了新意。“节物相催”，是自然规律，非人力所能为。因为新陈代谢，是自然运行的铁的规律！但那些“痴心儿女”却想“挽留春”，不欲让春归去。这样写足了人们对春将逝去时的怅惘之感。为诗的后两句翻出新意，做了充分的铺垫。后两句，反振一笔，如异峰突起，醒人耳目。繁华似锦（“芳菲”）的春天归去，没有什么值得留恋的。那“阴阴”的“夏木”同样“可人”，诗人的乐观、豪放、豁达，跃然纸上！\n\n　　诗是说理，指出了对春天的逝去的两种不同看法，强调应该顺其自然。推而广之，诗人也是在阐述自己的处世观：人生是处在不断地转换之中，好的可以变坏，祸福相倚。因此，当你失去了什么时，不要过分抱憾，要正视现实，知足常乐。春天有春天令人留恋的地方，夏天也有夏天使人 合意的所在；顺境有顺境的快乐，逆境何尝不可磨炼人，使人步入顺境。通过这诗，我们充分理解到诗人宽广的胸怀，并从中得到勉励。宋人的说理诗，虽然常常有陈腐惹人生厌的地方，但也不乏像这首诗一样有积极意义的作品。', poem_tags = '春天,伤春' WHERE poem_title = '三月晦日偶题' AND poem_author = '秦观';
UPDATE edu_poem SET poem_translation = '里秦宫入：《后汉书·梁冀传》：“冀爱监奴秦宫，官至太仓令，得出入寿（梁冀妻孙寿）所。寿见宫，辄屏御者，托以言事，因与私焉。”\n③宓妃愁坐芝田馆：曹植《洛神赋》：“秣驷乎芝田。”宓妃，指曹丕妃甄后，芝田馆指她所住的馆舍。\n用尽陈王八斗才：《释常谈》：“文章多，谓之八斗之才。谢灵运尝曰：天下才共一石，曹子建独占八斗。”陈王：指曹植。', poem_tags = '感叹,感伤,爱情' WHERE poem_title = '可叹' AND poem_author = '李商隐';
UPDATE edu_poem SET poem_translation = '注释 虞美人草：《梦溪笔谈》：“高邮桑景舒性知音，旧传有虞美人草，闻人作虞美人曲则枝叶皆动，他曲不然。” 玉帐：军帐之美称。 匆匆：急急忙忙的样子，指项羽四面楚歌，自刎乌江。 湘娥句：舜帝死后，二湘妃泣泪落翠竹，在竹上留下斑迹，人谓之斑竹。张泌《临江仙》：“翠竹暗留珠泪怨，闲调宝瑟波中。”刘禹锡《潇湘神》：“斑竹枝，斑竹枝，泪痕点点寄相思。”', poem_tags = '宋词精选,咏物,托志' WHERE poem_title = '浪淘沙·赋虞美人草' AND poem_author = '辛弃疾';
UPDATE edu_poem SET poem_translation = '入蜀途中。大散:古关名，又称散关，故址在今陕西宝鸡市西南大散岭上，为川陕间交通要道。瞪道:登山石径。黄牛岭:按之舆图，当在古黄牛堡附近。《大清一统志》卷二三八:“黄牛堡，在凤县(今属陕西)东北一百一十五里......。五代周显德二年，王景攻蜀入散关，拔黄牛砦”。\n②三休:多次休息。\n③“静言”二句:陆机《猛虎行》:“静言幽谷底，长啸高山岑”。\n④南山:终南山，也即秦岭。\n⑤日:全诗原作“露”，据静嘉堂本等改。霭:形容远。悠悠:远貌。\n⑥蒙密:谓草木繁茂，掩蔽甚深。', poem_tags = '写景,抒情' WHERE poem_title = '自大散以往深林密竹磴道盘曲四五十里至黄牛岭见黄花川' AND poem_author = '王维';
UPDATE edu_poem SET poem_translation = '春风和往年一样，十分关心隋堤上的杨柳；清明时节温暖时分，它把柳枝儿揉搓成鹅儿黄的颜色。\n去年春天，我与你在京城的大道上，在城门外的隋堤上，一起流连；今夜，我却只能在梦中和你化为云雨的魂魄相见。我如此的悲痛，只需要几个夜晚，就会令我的一生憔悴不堪。', poem_notes = '著意：著，显露；显著。意，情景。\n隋堤柳：指隋炀帝时在运河堤岸所植的杨柳。\n“搓得鹅儿黄欲就”：搓，用手掌来回揉摩，此处喻谓给柳树染色；鹅儿黄，即鹅黄色‘就，成。\n紫陌：指京师郊外的路。\n青门：长安城的东南门系青色，俗称青门。此指京城的城门。\n雨魄云魂：比喻作者的行踪像雨中的魄、云中的魂一样飘泊无定。', poem_tags = '春景,抒情,忆旧,怀今' WHERE poem_title = '清平乐·春风依旧' AND poem_author = '赵令畤';
UPDATE edu_poem SET poem_translation = '问候这湖中的春水，岸上的春花，林间的春鸟，你们太美了，这次的到来距前次已是三年了。东风顺吹，我驾船驶过湖面，杨柳丝丝拂面，似对我的到来表示欢迎。\n人生道路上的曲折、沉浮我已习惯，无论到哪里，我的心一片悠然。寒光亭下，湖水映照天空，真是天水一色，水面上飞起一群沙鸥。', poem_notes = '西江月：词牌名，原唐教坊曲。又名《白苹香》、《步虚词》、《晚香时候》、《玉炉三涧雪》、《江月令》。双调，五十字，上下片各两平韵，结句各叶一仄韵。\n题溧阳三塔寺：溧阳，今江苏省溧阳县。三塔寺，溧阳境内寺名。这首词原无题，南宋周密《绝妙好词》本增补为“丹阳湖”，而厉鹗笺注则作“题溧阳三塔寺”。宋王象之《舆地纪胜》谓丹阳湖在当涂县东南六十九里。当时为建康和宣城之间内河交通的必经航道。黄异《花庵词选》题作“洞庭”，显系疏误。按岳珂《玉楮集》有诗题《三塔寒光亭张于湖书词寺柱吴毅夫命名后轩》，所云“张于湖书词”，当指此篇。\n问讯：问候。湖：指三塔湖。\n重来又是三年：相隔三年重游旧地。\n过湖船：驶过湖面的船。\n杨柳丝丝：形容杨柳新枝柔嫩如丝。拂面：轻轻地掠过面孔。\n世路：世俗生活的道路。\n寒光亭：亭名。在江苏省溧阳县西三塔寺内。\n沙鸥：沙洲上的鸥鸟。', poem_tags = '宋词三百首,婉约,怀恋,山水' WHERE poem_title = '西江月·问讯湖边春色' AND poem_author = '张孝祥';
UPDATE edu_poem SET poem_tags = '写人,女子,闺情' WHERE poem_title = '虞美人·宝檀金缕鸳鸯枕' AND poem_author = '毛文锡';
UPDATE edu_poem SET poem_translation = '赏析 　　武则天当了皇帝以后，在一个寒冷的冬天，看见宫庭中的腊梅盛开，突然花兴大发，写了一首催花诗：“明朝游上苑，火速报春知，花须连夜发，莫待晓风吹”，命令百花次日一齐开放。次日，果然各种花果都承旨遵命。武则天到御花园赏花时，气候似乎变得特别暖和，池中冰块都已融化，陡然变成初春光景。武则天见林苑青翠，花开满园，万紫千红，十分高兴，立即命令宫人给这些花木挂以红绸并悬以金牌表示奖励。在百花丛中，唯有牡丹花迟迟未曾开放。武后震怒，命宫人燃炭火烧炙枝梗，牡丹方才怒开。然武则天气愤不息，下令将御花园中几千株牡丹逐出长安，移植东都洛阳，以示惩罚。洛阳因此成为牡丹之乡。百花生日，春花盛开，群芳争艳，南方许多地方常 展开阅读全文 ∨', poem_appreciation = '赏析 　　武则天当了皇帝以后，在一个寒冷的冬天，看见宫庭中的腊梅盛开，突然花兴大发，写了一首催花诗：“明朝游上苑，火速报春知，花须连夜发，莫待晓风吹”，命令百花次日一齐开放。次日，果然各种花果都承旨遵命。武则天到御花园赏花时，气候似乎变得特别暖和，池中冰块都已融化，陡然变成初春光景。武则天见林苑青翠，花开满园，万紫千红，十分高兴，立即命令宫人给这些花木挂以红绸并悬以金牌表示奖励。在百花丛中，唯有牡丹花迟迟未曾开放。武后震怒，命宫人燃炭火烧炙枝梗，牡丹方才怒开。然武则天气愤不息，下令将御花园中几千株牡丹逐出长安，移植东都洛阳，以示惩罚。洛阳因此成为牡丹之乡。百花生日，春花盛开，群芳争艳，南方许多地方常于此间举办花节、花市，供人观赏。繁花似锦的成都“蓉城”，每年二月十五日开始举行花会，届时将奇花异卉置于会场展览交流，是典型的花朝节的遗风。有的地区在花朝节尚有母亲用五彩线给女儿穿耳孔的习俗，盼女儿长大成人如花枝招展。也有一些地方于此日成群结队去郊外春游娱乐，欣赏大自然的美好时光。浙江省湖州一带，人们在花朝节这天，在花盆中插三角小彩旗，以祝贺花的生日。当地人认为此日种花、嫁接，最容易成活。二月二日过花朝节的地方，男女青年有在此日吃露天饭的习俗。 ▲', poem_tags = '冬天,写花' WHERE poem_title = '腊日宣诏幸上苑 / 催花诗' AND poem_author = '武则天';
UPDATE edu_poem SET poem_translation = '词抒写作者与客湖上饮归的情怀。词之片写宴集既散，余兴未尽，下片写湖上归来后的心情。全词风格于简淡中见含蓄。\n\n　　上片起首两句写词人于宴集结束后，兴致犹浓，特地绕道来到湖边，原想看看湖边港湾水草茂密之处那些翻跳出水、闪着白光的鱼儿，但夜色朦胧，湖水平静，只听得雨声稀朗，打落随风翻乱的荷叶上。\n\n　　这首两句是倒装句，表现出作者的体物入微。“却傍水边行，叶底跳鱼浪自惊。”（《南乡子》）观看鱼儿从水中跳起又落下本是他的乐趣，但眼前天暗波平，只有晚风疏雨翻乱荷叶的萧萧之声。忽然，风过处，云散去，一片凉月，影入湖中。这里不说是月影，而要说月堕平波，乃是由于作', poem_tags = '饮酒,孤独' WHERE poem_title = '临江仙·与客湖上饮归' AND poem_author = '叶梦得';
UPDATE edu_poem SET poem_translation = '节令风物不断递换，变化常新；痴心儿女，你们为什么要苦苦地挽留春天？\n那五彩缤纷的花朵凋谢又有什么可恨？夏天的树木，浓密葱绿，不也一样使你合意欢心！', poem_notes = '晦日：农历每月最后的一天。\n节物：各个季节的风物景色。\n儿女：这里泛指男女。\n芳菲：香花芳草。\n何须：何必，何用。\n可人：称人心意。', poem_appreciation = '文人伤春，似乎是永恒的主题，春风春雨，落花垂柳，引起过多少诗人感叹。三月晦日，是春天的最后一天，更难免激起诗人无计留春住的愁思。唐诗人贾岛有首著名的《三月晦日赠刘评事》诗云：“三月正当三十日，风光别我苦吟身。共君今夜不须睡，未到晓钟犹是春。”表现的就是浓重的惜春情绪。秦观这首绝句，与贾岛诗一样，也是通过议论，表达春将逝去时的感想。但秦诗一反旧例，没有悲伤的情调，却是顺其自然，豁达通变。\n\n　　诗富有哲理，蕴含“理趣”。“三月晦日”，即暮春三月的最后一天，过了这天，意味着时令进入夏季。春去的伤感，对于情感敏锐的人而言，不言而喻。春去的伤感，对于情感敏锐的人而言，不言而喻。但这首诗，却反其道而行之，写出了新意。“节物相催”，是自然规律，非人力所能为。因为新陈代谢，是自然运行的铁的规律！但那些“痴心儿女”却想“挽留春”，不欲让春归去。这样写足了人们对春将逝去时的怅惘之感。为诗的后两句翻出新意，做了充分的铺垫。后两句，反振一笔，如异峰突起，醒人耳目。繁华似锦（“芳菲”）的春天归去，没有什么值得留恋的。那“阴阴”的“夏木”同样“可人”，诗人的乐观、豪放、豁达，跃然纸上！\n\n　　诗是说理，指出了对春天的逝去的两种不同看法，强调应该顺其自然。推而广之，诗人也是在阐述自己的处世观：人生是处在不断地转换之中，好的可以变坏，祸福相倚。因此，当你失去了什么时，不要过分抱憾，要正视现实，知足常乐。春天有春天令人留恋的地方，夏天也有夏天使人 合意的所在；顺境有顺境的快乐，逆境何尝不可磨炼人，使人步入顺境。通过这诗，我们充分理解到诗人宽广的胸怀，并从中得到勉励。宋人的说理诗，虽然常常有陈腐惹人生厌的地方，但也不乏像这首诗一样有积极意义的作品。', poem_tags = '春天,伤春' WHERE poem_title = '三月晦日偶题' AND poem_author = '秦观';
UPDATE edu_poem SET poem_translation = '无数的春笋生满竹林，不仅封住了柴门还堵住了道路，那些踏着新竹来欣赏竹林的人，来到我这我都怒而不欢迎他们。', poem_notes = '上番：乃川语。《猗觉寮杂记》：杜诗：“会须上番看成竹。”元诗：“飞舞先春雪，因依上番梅。”俱用上番字，则上番不独为竹也。韩退之《笋》诗：“且叹高无数，庸知上几番。”又作平声押。斩新、上番，皆唐人方言。独孤及待：“旧日霜毛一番新。”亦读去声。杨慎《丹铅录》番作筤引《易》苍筤竹为证。', poem_tags = '咏物' WHERE poem_title = '咏春笋' AND poem_author = '杜甫';
UPDATE edu_poem SET poem_tags = '重阳节,典故,思念' WHERE poem_title = '扫花游·九日怀归' AND poem_author = '周密';
UPDATE edu_poem SET poem_translation = '风凄凄呀雨凄凄，窗外鸡鸣声声急。风雨之时见到你，怎不心旷又神怡。\n风潇潇呀雨潇潇，窗外鸡鸣声声绕。风雨之时见到你，心病怎会不全消。\n风雨交加昏天地，窗外鸡鸣声不息。风雨之时见到你，心里怎能不欢喜。', poem_notes = '喈（jiē 皆）喈：鸡鸣声。\n云：语助词。胡：何。夷：平，指心中平静。\n胶胶：或作“嘐嘐”，鸡鸣声。\n瘳（chōu 抽）：病愈，此指愁思萦怀的心病消除。\n晦：黑夜。', poem_appreciation = '蕴涵性的顷刻，包前启后。在情境的选择上，诗篇不写未见之前绵绵无尽的相思之苦，也不写相见之后载笑载言的欢聚之乐，而是重章渲染“既见”之时的喜出望外之情。而这一顷刻，正是最富于蕴涵性的顷刻。读者透过这位女子难以形容的望外之喜，既能想见她在“既见”之前，白日的“愿言思伯，甘心首疾”、和夜间的“耿耿不寐，如有隐忧”之情；也能想见在“既见”之后，夫妇间的“既见复关，载笑载言”和“维士与女，伊其相谑”的融融之乐。以少许胜多许，以顷刻蕴过程，这是构思的巧妙。\n\n　　哀景写乐，倍增其情。每章首二句，都以风雨、鸡鸣起兴，这些兼有赋景意味的兴句，重笔描绘出一幅寒冷阴暗、鸡声四起的背景。当此之时，最易勾起离情别绪。赋景之句，也确成写情之语。风雨交加和夜不能寐之无聊；群鸡阵啼和怀人动荡之思；鸡守时而鸣与所期之人盼而不至，可谓契合无间，层层映衬。然而，正在这几乎绝望的凄风苦雨之时，怀人的女子竟意外地“既见”了久别的情郎；骤见之喜，欢欣之情，自可想见。而此时凄风苦雨中的群鸡乱鸣，也似成了煦风春雨时的群鸡欢唱了。这种情景反衬之法，恰如王夫之所说，“以乐景写哀，以哀景写乐，一倍增其哀乐”（《董斋诗话》）。这一手法，确实不唯见诸《小雅·采薇》，而是《诗经》中诗人的常用之法。\n\n　　炼词申意，循序有进。诗篇的结构是单纯的，三章叠咏；诗人的易词写景却是讲究的，它细腻地表现出了人的不同感受。凄凄，是女子对风雨寒凉的感觉；潇潇，则从听觉见出夜雨骤急；如夜的晦冥，又从视觉展现眼前景象。易词写景的这种微妙性，姚际恒《诗经通论》曾有精到的分析：“‘如晦’正写其明也。惟其明，故曰‘如晦’。惟其如晦，‘凄凄’、‘潇潇’时尚晦可知。”诗篇在易词申意的同时，对时态的运动和情态的发展，又有循序渐进的微妙表现。关于时态的渐进，姚氏说，“‘喈喈’为众声和，初鸣声尚微，但觉其众和耳。‘胶胶’，同声高大也。三号以后，天将晓，相续不已矣。”民间尚有“鸡鸣三遍天将明”之说；《风雨》的三章相叠，或许正是以此习惯规律为基础的。随着时态的发展，怀人女子“既见君子”时的心态也渐次有进。“云胡不夷”，以反诘句式，语气热烈，言其心情大悦；“云胡不瘳”，言积思之病，至此而愈，语气至深；末章“云胡不喜”，则喜悦之情，难以掩饰，以至大声疾呼了。天气由夜晦而至晨晦，鸡鸣由声微而至声高，情感的变化则由乍见惊疑而至确信高呼。方玉润说：“此诗人善于言情，又善于即景以抒怀，故为千秋绝调。”（《诗经原始》）实当此之谓。\n\n　　象征意象，一诗多解。《风雨》的诗旨，今人或主“夫妻重逢”，或主“喜见情人”；联系诗境，前说更合情理。然而，汉代经生的“乱世思君”说，却在后世产生了积极的影响。《毛诗序》曰：“《风雨》，思君子也。乱世则思君子不改其度焉。”郑笺申发之曰：“兴者，喻君子虽居乱世，不变改其节度。……鸡不为如晦而止不鸣。”这样，“风雨”便象征乱世，“鸡鸣”便象征君子不改其度，“君子”则由“夫君”之君变成为德高节贞之君子了。这虽属附会，却也有其文本依据。因为，“君子”，在《诗经》时代，可施诸可敬、可爱、可亲之人，含义不定。因此，把赋体的白描意象理解为比体的象征意象，就可能生发“乱世思君”的联想；而把“风雨如晦”的自然之景，理解为险恶的人生处境或动荡的社会环境，也符合审美规律。故后世许多士人君子，常以虽处“风雨如晦”之境，仍要“鸡鸣不已”自励。南朝梁简文帝《幽絷题壁自序》云：“梁正士兰陵萧纲，立身行己，终始如一。风雨如晦，鸡鸣不已。”郭沫若创作于五四运动退潮期的《星空·归来》中也写道：“游子归来了，在这风雨如晦之晨，游子归来了！”从现代接受美学看，这种立足文本的审美再创造是无可非议的；而《毛序》的这一“附会”，也可以说是一种“创造性的误读”。', poem_tags = '诗经,写雨,怀人,民谣' WHERE poem_title = '诗经·国风·郑风' AND poem_author = '佚名';
UPDATE edu_poem SET poem_translation = '时近年终冰霜渐渐减少，春回大地草木最先知晓。\n眼前只觉一片生机盎然，东风吹来水面绿波荡摇。', poem_notes = '立春：阳气回苏的开头，也是一年的最后月份。代表着春季的开始。偶成，即偶有所感而成。\n律回：即大地回春的意思。黄帝命伶伦断竹为筒（后人也用金属管），以定音和候十二月之气。阳六为律，即黄钟、太簇、姑洗、蕤宾、夷则、无射；阴六为吕，即大吕、夹钟、仲吕、林钟、南吕、应钟。农历十二月属吕，正月属律，立春往往在十二月与一月之交，所以曰“律回”。从节气上说，立春即是一年之始，但在历算上，立春之日可能赶在上一年的腊月下旬，即在上一年未尽之时，新一年的春天就已经来到了。古人认为律属阳气，吕属阴气，各代表一年的六个月，律回阴往即言立春。\n岁（suì）晚：年终。\n草木：泛指一切能受到季节变化影响的事物，如动植物、水、山等等。\n生意：生机、生气。\n满：遍布，充满。\n参（cēn）差（cī）：高低不齐。形容水面波纹起伏的样子。', poem_tags = '古诗三百首,春天' WHERE poem_title = '立春偶成' AND poem_author = '张栻';
UPDATE edu_poem SET poem_tags = '思乡' WHERE poem_title = '题齐安城楼' AND poem_author = '杜牧';
UPDATE edu_poem SET poem_translation = '梳洗完毕，独自一人登上望江楼，倚靠着楼柱凝望着滔滔江面。上千艘船过去了，所盼望的人都没有出现。太阳的余晖脉脉地洒在江面上，江水慢慢地流着，思念的柔肠萦绕在那片白蘋洲上。', poem_notes = '望江南：又名“梦江南”“忆江南”，原唐教坊曲名，后用为词牌名。段安节《乐府杂录》：“《望江南》始自朱崖李太尉（德裕）镇浙日，为亡妓谢秋娘所撰，本名“谢秋娘”，后改此名。”《金奁集》入“南吕宫”。小令，单调二十七字，三平韵。\n梳洗：梳头、洗脸、化妆等妇女的生活内容。\n独：独自，单一。望江楼：楼名，因临江而得名。\n千帆：上千只帆船。帆：船上使用风力的布蓬，又作船的代名词。皆：副词，都。\n斜晖：日落前的日光。晖：阳光。脉脉：本作“眽眽”，凝视貌。《古诗十九首》有“盈盈一水间，脉脉不得语”。后多用以示含情欲吐之意。\n肠断：形容极度悲伤愁苦。白蘋（pín）：水中浮草，色白。古时男女常采蘋花赠别。洲：水边陆地。', poem_appreciation = '此词写一女子登楼远眺、盼望归人的情景，表现了她从希望到失望以致最后的“肠断”的感情。\n\n　　这是一首小令，只有二十七个字。“词之难于令曲，如诗之难于绝句”，“一句一字闲不得”（《白香词谱笺》）。起句“梳洗罢”，看似平平，“语不惊人”。但这三个字内容丰富，给读者留了许多想像的余地。这不是一般人早晨起来的洗脸梳头，而是特定的人物（思妇），在特定条件（准备迎接久别的爱人归来）下，一种特定情绪（喜悦和激动）的反映。\n\n　　在中国古典诗歌中，常以“炉薰阖不用，镜匣上尘生。绮罗失常色，金翠暗无精”之类的描写来表现思妇孤寂痛苦的生活和心情。本篇用法有所不同，离别的痛苦，相思的寂寞，孤独的日子似乎就要过去，或者说她希望中的美好日子似乎就要来到，于是，临镜梳妆，顾影自怜，着意修饰一番。结果是热烈的希望之火遇到冰冷的现实，带来了深一层的失望和更大的精神痛苦，重新又要回到“明镜不治”“首如飞蓬”的苦境中去。这三个字，把这个女子独居的环境，深藏内心的感情变化和对美好生活的向往，不是生动地表现出来了吗？\n\n　　接着，出现了一幅广阔、多彩的艺术画面：“独倚望江楼。”江为背景，楼为主体，焦点是独倚的人。这时的女子，感情是复杂的；随着时间的推移，情绪是变化的。初登楼时的兴奋喜悦，久等不至的焦急，还有对往日的深沉追怀……这里，一个“独”字用得很传神。“独”字，既无色泽，又无音响，却意味深长。这不是恋人昵昵情语的“互倚”，也不是一群人叽叽喳喳的“共倚”，透过这无语独倚的画面，反映了人物的精神世界。一幅美人凭栏远眺图，却是“误几回天际识归舟”的“离情正苦”。把人、景、情联系起来，画面上就有了盛妆女子和美丽江景调和在一起的斑斓色彩，有了人物感情变化和江水流动的交融。\n\n　　“过尽千帆皆不是”，是全词感情上的大转折。这句和起句的欢快情绪形成对照，鲜明而强烈；又和“独倚望江楼”的空寂焦急相连结，承上而启下。船尽江空，人何以堪!希望落空，幻想破灭，这时映入她眼帘的是“斜晖脉脉水悠悠”，落日流水本是没有生命的无情物，但在此时此地的思妇眼里，成了多愁善感的有情者。这是她的痛苦心境移情于自然物而产生的一种联想类比。斜阳欲落未落，对失望女子含情脉脉，不忍离去，悄悄收着余晖；不尽江水似乎也懂得她的心情，悠悠无语流去。它像一组电影镜头：一位着意修饰的女子，倚楼凝眸烟波浩淼的江水，等待久别不归的爱人，从日出到日落，由希望变失望，把这个女子的不幸，表现得多么动人。\n\n　　至此，景物的描绘，感情的抒发，气氛的烘托，都已成熟，最后弹出了全曲的最强音：“肠断白苹洲。”“末句最当留意，有余不尽之意始佳。”和全词“不露痕迹”相较，末句点出主题似太直，但在感情的高潮中结句，仍有“有余不尽之意”。白苹洲在何处？俞平伯先生说，不要“过于落实，似泛说较好”，（俞平伯《唐宋词选释》），这是极为深刻的见解。但在本篇的艺术描写中，应该是江中确有白洲在的，不是比喻、想像，也不是泛指，而是实写。独倚望江楼，一眼就可看到此洲，但那时盼人心切，只顾看船而不见有洲了。千帆过尽，斜晖脉脉，江洲依旧，不见所思，能不肠断!\n\n　　词是注重作家主观抒情的艺术形式。这首小令，情真意切，生动自然，没有矫饰之态和违心之语。词中出现的楼头、船帆、斜晖、江水、小洲，这些互不相干的客观存在物，思妇的由盼郎归来的喜悦到“肠断白苹洲”的痛苦失望，这些人物感情神态的复杂变化，作家经过精巧的艺术构思，使之成为浑然一体的艺术形象。作家的思想感情像一座桥梁，把这些景物、人物联系了起来，而且渗透到了景物描绘和人物活动之中，成了有机的艺术整体，使冰冷的楼、帆、水、洲好像有了温度，有了血肉生命，变得含情脉脉；使分散孤立的风景点，融合成了具有内在逻辑联系的艺术画面；使人物的外在表现和内在的心理活动完美统一地显示出来。这正是现实生活中的思妇的怨和恨，血和泪，深深地感动了作家；在这些似乎平静的字句中，跳动着作家真挚热烈的心。\n\n　　这首小令，像一幅清丽的山水小轴，画面上的江水没有奔腾不息的波涛，发出的只是一种无可奈何的叹息，连落日的余晖，也缺乏峻刻的寓意，盘旋着一股无名的愁闷和难以排遣的怨恨。还有那临江的楼头，点点的船帆，悠悠的流水，远远的小洲，都惹人遐想和耐人寻味，有着一种美的情趣，一种情景交融的意境。这首小令，看似不动声色，轻描淡写中酝酿着炽热的感情，而且宛转起伏，顿挫有致，于不用力处看出“重笔”。\n\n　　思妇题材写的人很多，可说是个“热门题材”，但这首小令，不落俗套，很有特色。这也是个软题材，但这首小令不是软绵绵的，情调积极、健康、朴素。在有着绮靡侧艳“花间”气的温词中，这首小令可说是情真意切，清丽自然，别具一格的精品。', poem_tags = '宋词三百首,初中古诗,闺怨,无奈,思念' WHERE poem_title = '望江南·梳洗罢' AND poem_author = '温庭筠';
UPDATE edu_poem SET poem_tags = '抒情,思乡,孤寂' WHERE poem_title = '风入松·危楼古镜影犹寒' AND poem_author = '张炎';
UPDATE edu_poem SET poem_translation = '长江出了西陵峡,才进入平地，水势奔腾浩荡。南边与沅水、湘水合流，北边与汉水汇聚，水势显得更加壮阔。流到赤壁之下，波浪滚滚，如同大海一样。清河张梦得，被贬官后居住在齐安，于是他在房舍的西南方修建了一座亭子，用来观赏长江的胜景。我的哥哥子瞻给这座亭子起名叫“快哉亭”。\n　　在亭子里能看到长江南北上百里、东西三十里。波涛汹涌，风云变化不定。在白天，船只在亭前来往出没；在夜间，鱼龙在亭下的江水中悲声长啸。景物变化很快，令人惊心骇目，不能长久地欣赏。能够在几案旁边欣赏这些景色，抬起眼来就足够看了。向西眺望武昌的群山，（只见）山脉蜿蜒起伏，草木成行成列，烟消云散，阳光普照，捕鱼、打柴的村民的房舍，都可以一一数清。这就是把亭子称为“快哉”的原因。到了长江岸边古城的废墟，是曹操、孙权傲视群雄的地方，是周瑜、陆逊驰骋战场的地方，那些流传下来的风范和事迹，也足够让世俗之人称快。\n　　从前，楚襄王让宋玉、景差跟随着游兰台宫。一阵风吹来，飒飒作响，楚王敞开衣襟，迎着风，说：“这风多么畅快啊！这是我和百姓所共有的吧。”宋玉说：“这只是大王的雄风罢了，百姓怎么能和您共同享受它呢？”宋玉的话在这儿大概有讽喻的意味吧。风并没有雄雌的区别，而人有生得逢时，生不逢时的不同。楚王感到快乐的原因，而百姓感到忧愁的原因，正是由于人们的境遇不同，跟风又有什么关系呢?读书人生活在世上，假使心中不坦然，那么，到哪里没有忧愁？假使胸怀坦荡，不因为外物而伤害天性（本性），那么，在什么地方会不感到快乐呢？（读书人生活在世上，如果他的内心不能自得其乐，那么，他到什么地方去会不忧愁呢？如果他心情开朗，不因为环境的影响而伤害自己的情绪，那么，他到什么地方去会不整天愉快呢？）\n　　张梦得不把被贬官而作为忧愁，利用征收钱谷的公事之余，在大自然中释放自己的身心，这是他心中应该有超过常人的地方。即使是用蓬草编门，以破瓦罐做窗，都没有觉得不快乐，更何况在清澈的长江中洗涤，面对着西山的白云，尽享耳目的美景来自求安适呢？如果不是这样，连绵的峰峦，深陡的沟壑，辽阔的森林，参天的古木，清风拂摇，明月高照，这些都是伤感失意的文人士大夫感到悲伤憔悴而不能忍受的景色，哪里看得出这是畅快的呢！\n　　元丰六年十一月初一，赵郡苏辙记。', poem_notes = '【江出西陵】江，长江。出，流出。西陵，西陵峡，又名夷陵峡，长江三峡之一，在湖北宜昌西北。\n【始】才\n【奔放肆大】奔放，水势疾迅。肆大，水流阔大。肆，极，甚。\n【南合沅、湘，北合汉沔（miǎn）】沅，沅水（也称沅江）。湘，湘江。两水都在长江南岸，流入洞庭湖，注入长江。汉沔，就是汉水。汉水源出陕西宁羌，初名漾水，东流经沔县南，称沔水，又东经褒城，纳褒水，始称汉水。汉水在长江北岸。\n【益张】更加盛大。张，大。\n【赤壁】赤鼻矶，现湖北黄冈城外，苏辙误以为周瑜破曹操处。\n【浸（jìn）灌】浸，灌，意思都是“注”。此处指水势浩大。\n【清河张君梦得谪居齐安】清河，县名，现河北清河。张君梦得，张梦得，字怀民，苏轼友人。齐安，宋代黄冈为黄州齐按郡，因称。谪，贬官。居，居住。\n【即】就着，依着。\n【胜】胜景，美景。\n【亭之所见】在亭上能够看到的（范围）。所见，所看到的景象。\n【一舍（shè）】三十里。古代行军每天走三十里宿营，叫做“一舍”。\n【风云开阖（hé）】风云变化。意思是风云有时出现，有时消失。开，开启。阖，闭合。\n【倏忽】顷刻之间，一瞬间，指时间短。\n【动心骇目】犹言“惊心动魄”。这是指景色变化万端，能使见者心惊，并不是说景色可怕。这里动和骇是使动用法。解释为：使……惊动，使……惊骇\n【不可久视】这是说，以前没有亭子，无休息之地，不能长久地欣赏。\n【今乃得玩之几席之上】可以在亭中的几旁席上赏玩这些景色。几，小桌，茶几。\n【举目而足】抬起眼来就可以看个够。\n【草木行列】草木成行成列非常茂盛，形容草木繁荣。\n【指数】名词作状语，用手指清点。\n【长洲】江中长条形的沙洲或江岸。\n【故城之墟】旧日城郭的遗址。故城，指隋朝以前的黄州城（唐朝把县城迁移了）。墟，旧有的建筑物已被毁平而尚留有遗迹的空地。\n【曹孟德、孙仲谋之所睥睨】曹操（字孟德）、孙权（字仲谋）所傲视的地方。睥睨，斜视的样子，引申为傲视。赤壁之战时，曹操、孙权都有气吞对方的气概。\n【周瑜、陆逊之所骋骛（chěngwù）】周瑜、陆逊均为三国时东吴的重要将领。周瑜、陆逊活跃的地方。周瑜曾破曹操于赤壁，陆逊曾袭关羽于荆州，败刘备于夷陵，破魏将曹休于皖城。骋骛，犹言“驰马”，形容他们驰骋疆场。\n【称快世俗】使世俗之人称快。称快为使动用法，使……称快。\n【楚襄王从宋玉、景差于兰台之宫】宋玉有《风赋》，讽楚襄王之骄奢。楚襄王，即楚顷襄王，名横，楚怀王之子。宋玉、景差都是楚襄王之侍臣。兰台宫，遗址在湖北钟祥东。从，使……从。\n【快哉此风】特殊句式，主谓倒装，应为“此风快哉”，解释为这风多么让人感到畅快啊！\n【披】敞开\n【当】迎接\n【盖有讽焉】大概有讽谏的意味在里头。讽，讽喻。宋玉作《风赋》，讽楚襄王之骄奢。焉，兼词 于之，在那里。\n【人有遇不遇之变】人有遇时和不遇时的不同时候。遇，指机遇好，被重用。\n【与（yù）】参与，引申为有何关系。\n【使其中不自得】使，假使。中，内心，心中。自得，自己感到舒适、自在。\n【病】忧愁，怨恨。\n【以物伤性】因外物（指环境）而影响天性（本性）。\n【适】往，去。\n【患】忧愁。\n【窃会（kuài）计之余功】窃，偷得，这里即“利用”之意。会计，指征收钱谷、管理财务行政等事务。余功，公事之余。\n【自放】自适，放情。放，纵。\n【此其中宜有以过人者】其，代词，指心胸。\n【蓬户瓮牖】蓬户，用蓬草编门。瓮牖，用破瓮做窗。蓬、瓮，名词作状语。\n【濯】洗涤。\n【揖】拱手行礼。这里的意思是面对（西山白云）。\n【自适】自求安适。适，闲适。\n【此皆骚人思士之所以悲伤憔悴而不能胜者】此，指“连山绝壑，长林古木”等快哉亭上所见景物。骚人思士，指心中有忧思的人。胜，承受，禁（jīn）得起。\n【乌睹其为快也哉】哪里看得出这是畅快的呢！乌……哉，哪里……呢。乌，哪里。\n【赵郡】苏辙先世为赵郡栾城（今河北赵县）人\n【朔】夏历每月初一。\n【望】每月月圆时，即十五。\n【既望】夏历每月十六\n【晦】夏历每月最后一天。', poem_appreciation = '本文的文体是“记”。本文特点是因亭景而生意，借亭名而发论，结构严谨，条理清晰。文章在开头交代快哉亭的地理位置、命名由来、并为后文安排伏笔之后，在第二段着力描写快哉亭附近的足以令人快意的景物。在写景时，或就目之所见，或就思之所及，融时空于一体，变化多端，开阖自如。在第三段就“快哉”二字的来历发表议论，说明人生之快，既不在身边景物的优劣，也不在遇与不遇的不同，得出了“士生于世，使其中不自得，将何往而非病？使其中坦然，不以物伤性，将何适而非快”的结论，既赞扬了张梦得，也抒发了自己不以贬谪为怀、随遇而安的思想感情，使一篇写景文章有了更深刻的意义。文章委婉曲致，一波三折，充分体现了作者“汪洋澹泊，一唱三叹”的文章风格。\n\n　　宋神宗元丰年间(1078—1085)，张梦得、苏轼都被贬至黄州。张梦得在寓所西南筑亭，苏轼命名为“快哉亭”，苏辙作《黄州快哉亭记》。当时苏辙因反对王安石新法，被贬至筠州(今江西高安县)监巡盐酒税，政治上也是很不得意。但他不以贬谪为怀，惟适自安。这篇文章就表现了这种心情。', poem_tags = '古文观止,叙事,写景,抒情,议论,散文' WHERE poem_title = '黄州快哉亭记' AND poem_author = '苏辙';
UPDATE edu_poem SET poem_translation = '笔写“唱到阳关第四声”，即唱到“劝君更尽一杯酒”既没有写情，也没有写景，而情与景近在眼前：景是离别之景，情是伤离别之情。没有直接写出，却让人接下来就有一种“西出阳关无故人”的离愁别绪。“罗带”本指丝织的衣带，在此则指将要远行之人，“香带”指送行的女子。“香”字写出了女子衣衫的特点，也让人想到的女子温婉贤淑。二人即将分离，“轻”字写出了双方复杂的心理，仿佛不敢又不忍触碰别离这一话题，然而启程的时间却已经到了。“杏花时节雨纷纷”点明了时间为春天，天还下着淅淅沥沥的雨，让人想到那首“清明时节雨纷纷，路上行人欲断魂”现在同样的季节，同样的天气，游子也将成为那路上的行人，孤独，落寞，伤感。两', poem_tags = '离别,无奈' WHERE poem_title = '一剪梅·唱到阳关第四声' AND poem_author = '刘仙伦';
UPDATE edu_poem SET poem_translation = '注释 ①阳九：厄运。 ②薄蚀：日月相掩食。此指灾难......', poem_tags = '抒情' WHERE poem_title = '刘太尉琨伤乱' AND poem_author = '江淹';

