INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八阵图' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长相思·其一', '李白', '唐代', '长相思，在长安。\n络纬秋啼金井阑，微霜凄凄簟色寒。\n孤灯不明思欲绝，卷帷望月空长叹。\n美人如花隔云端！\n上有青冥之长天，下有渌水之波澜。\n天长路远魂飞苦，梦魂不到关山难。\n长相思，摧心肝！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长相思·其一' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望海潮·东南形胜', '柳永', '宋代', '东南形胜，三吴都会，钱塘自古繁华，烟柳画桥，风帘翠幕，参差十万人家。云树绕堤沙，怒涛卷霜雪，天堑无涯。市列珠玑，户盈罗绮，竞豪奢。\n重湖叠巘清嘉。有三秋桂子，十里荷花。羌管弄晴，菱歌泛夜，嬉嬉钓叟莲娃。千骑拥高牙。乘醉听箫鼓，吟赏烟霞。异日图将好景，归去凤池夸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望海潮·东南形胜' AND p.poem_author = '柳永';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('氓', '佚名', '先秦', '氓之蚩蚩，抱布贸丝。匪来贸丝，来即我谋。送子涉淇，至于顿丘。匪我愆期，子无良媒。将子无怒，秋以为期。\n乘彼垝垣，以望复关。不见复关，泣涕涟涟。既见复关，载笑载言。尔卜尔筮，体无咎言。以尔车来，以我贿迁。(尔 一作：尓)\n桑之未落，其叶沃若。于嗟鸠兮！无食桑葚。于嗟女兮！无与士耽。士之耽兮，犹可说也。女之耽兮，不可说也。\n桑之落矣，其黄而陨。自我徂尔，三岁食贫。淇水汤汤，渐车帷裳。女也不爽，士贰其行。士也罔极，二三其德。\n三岁为妇，靡室劳矣。夙兴夜寐，靡有朝矣。言既遂矣，至于暴矣。兄弟不知，咥其笑矣。静言思之，躬自悼矣。\n及尔偕老，老使我怨。淇则有岸，隰则有泮。总角之宴，言笑晏晏，信誓旦旦，不思其反。反是不思，亦已焉哉！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '氓' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('捕蛇者说', '柳宗元', '唐代', '永州之野产异蛇：黑质而白章，触草木尽死；以啮人，无御之者。然得而腊之以为饵，可以已大风、挛踠、瘘疠，去死肌，杀三虫。其始太医以王命聚之，岁赋其二。募有能捕之者，当其租入。永之人争奔走焉。\n\n　　有蒋氏者，专其利三世矣。问之，则曰：“吾祖死于是，吾父死于是，今吾嗣为之十二年，几死者数矣。”言之貌若甚戚者。余悲之，且曰：“若毒之乎？余将告于莅事者，更若役，复若赋，则何如？”蒋氏大戚，汪然出涕，曰：“君将哀而生之乎？则吾斯役之不幸，未若复吾赋不幸之甚也。向吾不为斯役，则久已病矣。自吾氏三世居是乡，积于今六十岁矣。而乡邻之生日蹙，殚其地之出，竭其庐之入。号呼而转徙，饥渴而顿踣。触风雨，犯寒暑，呼嘘毒疠，往往而死者，相藉也。曩与吾祖居者，今其室十无一焉。与吾父居者，今其室十无二三焉。与吾居十二年者，今其室十无四五焉。非死则徙尔，而吾以捕蛇独存。悍吏之来吾乡，叫嚣乎东西，隳突乎南北；哗然而骇者，虽鸡狗不得宁焉。吾恂恂而起，视其缶，而吾蛇尚存，则弛然而卧。谨食之，时而献焉。退而甘食其土之有，以尽吾齿。盖一岁之犯死者二焉，其余则熙熙而乐，岂若吾乡邻之旦旦有是哉。今虽死乎此，比吾乡邻之死则已后矣，又安敢毒耶？”\n\n　　余闻而愈悲，孔子曰：“苛政猛于虎也！”吾尝疑乎是，今以蒋氏观之，犹信。呜呼！孰知赋敛之毒有甚是蛇者乎！故为之说，以俟夫观人风者得焉。\n\n　　（饥渴而顿踣 一作：饿渴）', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '捕蛇者说' AND p.poem_author = '柳宗元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望月有感', '白居易', '唐代', '自河南经乱，关内阻饥，兄弟离散，各在一处。因望月有感，聊书所怀，寄上浮梁大兄、於潜七兄、乌江十五兄，兼示符离及下邽弟妹。\n\n时难年荒世业空，弟兄羁旅各西东。\n田园寥落干戈后，骨肉流离道路中。\n吊影分为千里雁，辞根散作九秋蓬。\n共看明月应垂泪，一夜乡心五处同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望月有感' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦游天姥吟留别 / 梦游天姥山别东鲁诸公', '李白', '唐代', '海客谈瀛洲，烟涛微茫信难求；\n越人语天姥，云霞明灭或可睹。\n天姥连天向天横，势拔五岳掩赤城。\n天台四万八千丈，对此欲倒东南倾。(四万 一作：一万)\n我欲因之梦吴越，一夜飞度镜湖月。(度 通：渡)\n湖月照我影，送我至剡溪。\n谢公宿处今尚在，渌水荡漾清猿啼。\n脚著谢公屐，身登青云梯。\n半壁见海日，空中闻天鸡。\n千岩万转路不定，迷花倚石忽已暝。\n熊咆龙吟殷岩泉，栗深林兮惊层巅。\n云青青兮欲雨，水澹澹兮生烟。\n列缺霹雳，丘峦崩摧。\n洞天石扉，訇然中开。\n青冥浩荡不见底，日月照耀金银台。 \n霓为衣兮风为马，云之君兮纷纷而来下。\n虎鼓瑟兮鸾回车，仙之人兮列如麻。\n忽魂悸以魄动，恍惊起而长嗟。\n惟觉时之枕席，失向来之烟霞。\n世间行乐亦如此，古来万事东流水。\n别君去兮何时还？且放白鹿青崖间，须行即骑访名山。\n安能摧眉折腰事权贵，使我不得开心颜!', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '梦游天姥吟留别 / 梦游天姥山别东鲁诸公' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('端午日', '殷尧藩', '唐代', '少年佳节倍多情，老去谁知感慨生；\n不效艾符趋习俗，但祈蒲酒话升平。\n鬓丝日日添白头，榴锦年年照眼明；\n千载贤愚同瞬息，几人湮没几垂名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '端午日' AND p.poem_author = '殷尧藩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送东阳马生序', '宋濂', '明代', '余幼时即嗜学。家贫，无从致书以观，每假借于藏书之家，手自笔录，计日以还。天大寒，砚冰坚，手指不可屈伸，弗之怠。录毕，走送之，不敢稍逾约。以是人多以书假余，余因得遍观群书。既加冠，益慕圣贤之道 ，又患无硕师、名人与游，尝趋百里外，从乡之先达执经叩问。先达德隆望尊，门人弟子填其室，未尝稍降辞色。余立侍左右，援疑质理，俯身倾耳以请；或遇其叱咄，色愈恭，礼愈至，不敢出一言以复；俟其欣悦，则又请焉。故余虽愚，卒获有所闻。\n\n　　当余之从师也，负箧曳屣，行深山巨谷中，穷冬烈风，大雪深数尺，足肤皲裂而不知。至舍，四支僵劲不能动，媵人持汤沃灌，以衾拥覆，久而乃和。寓逆旅，主人日再食，无鲜肥滋味之享。同舍生皆被绮绣，戴朱缨宝饰之帽，腰白玉之环，左佩刀，右备容臭，烨然若神人；余则缊袍敝衣处其间，略无慕艳意。以中有足乐者，不知口体之奉不若人也。盖余之勤且艰若此。\n\n　　今虽耄老，未有所成，犹幸预君子之列，而承天子之宠光，缀公卿之后，日侍坐备顾问，四海亦谬称其氏名，况才之过于余者乎？\n\n　　今诸生学于太学，县官日有廪稍之供，父母岁有裘葛之遗，无冻馁之患矣；坐大厦之下而诵《诗》《书》，无奔走之劳矣；有司业、博士为之师，未有问而不告，求而不得者也；凡所宜有之书，皆集于此，不必若余之手录，假诸人而后见也。其业有不精，德有不成者，非天质之卑，则心不若余之专耳，岂他人之过哉！\n\n　　东阳马生君则，在太学已二年，流辈甚称其贤。余朝京师，生以乡人子谒余，撰长书以为贽，辞甚畅达，与之论辩，言和而色夷。自谓少时用心于学甚劳，是可谓善学者矣！其将归见其亲也，余故道为学之难以告之。谓余勉乡人以学者，余之志也；诋我夸际遇之盛而骄乡人者，岂知余者哉！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送东阳马生序' AND p.poem_author = '宋濂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送李少府贬峡中王少府贬长沙', '高适', '唐代', '嗟君此别意何如，驻马衔杯问谪居。\n巫峡啼猿数行泪，衡阳归雁几封书。\n青枫江上秋帆远，白帝城边古木疏。\n圣代即今多雨露，暂时分手莫踌躇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送李少府贬峡中王少府贬长沙' AND p.poem_author = '高适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹枝词二首·其一', '刘禹锡', '唐代', '杨柳青青江水平，闻郎江上踏歌声。(踏歌声 一作：唱歌声)\n东边日出西边雨，道是无晴却有晴。(却有晴 一作：还有晴)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹枝词二首·其一' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李延年歌', '李延年', '两汉', '北方有佳人，绝世而独立。\n一顾倾人城，再顾倾人国。\n宁不知倾城与倾国？佳人难再得。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李延年歌' AND p.poem_author = '李延年';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('童趣', '沈复', '清代', '余忆童稚时，能张目对日，明察秋毫，见藐小之物必细察其纹理，故时有物外之趣。\n\n　　夏蚊成雷，私拟作群鹤舞于空中，心之所向，则或千或百，果然鹤也；昂首观之，项为之强。又留蚊于素帐中，徐喷以烟，使之冲烟而飞鸣，作青云白鹤观，果如鹤唳云端，为之怡然称快。\n\n　　余常于土墙凹凸处，花台小草丛杂处，蹲其身，使与台齐；定神细视，以丛草为林，以虫蚁为兽，以土砾凸者为丘，凹者为壑，神游其中，怡然自得。\n\n　　一日，见二虫斗草间，观之，兴正浓，忽有庞然大物，拔山倒树而来，盖一癞蛤蟆，舌一吐而二虫尽为所吞。余年幼，方出神，不觉呀然一惊。神定，捉虾蟆，鞭数十，驱之别院。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '童趣' AND p.poem_author = '沈复';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠花卿', '杜甫', '唐代', '锦城丝管日纷纷，半入江风半入云。 \n此曲只应天上有，人间能得几回闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠花卿' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过松源晨炊漆公店', '杨万里', '宋代', '莫言下岭便无难，赚得行人错喜欢。(错喜欢 一作：空喜欢)\n正入万山圈子里，一山放过一山拦。(放过 一作：放出)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过松源晨炊漆公店' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('悯农二首', '李绅', '唐代', '春种一粒粟，秋收万颗子。\n四海无闲田，农夫犹饿死。\n\n锄禾日当午，汗滴禾下土。\n谁知盘中餐，粒粒皆辛苦？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '悯农二首' AND p.poem_author = '李绅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寡人之于国也', '孟子弟子录', '先秦', '梁惠王曰：“寡人之于国也，尽心焉耳矣。河内凶，则移其民于河东，移其粟于河内；河东凶亦然。察邻国之政，无如寡人之用心者。邻国之民不加少，寡人之民不加多，何也？\n\n　　孟子对曰：“王好战，请以战喻。填然鼓之，兵刃既接，弃甲曳兵而走。或百步而后止，或五十步而后止。以五十步笑百步，则何如？”曰：“不可，直不百步耳，是亦走也。”曰：“王如知此，则无望民之多于邻国也。不违农时，谷不可胜食也；数罟不入洿池，鱼鳖不可胜食也；斧斤以时入山林，材木不可胜用也。谷与鱼鳖不可胜食，材木不可胜用，是使民养生丧死无憾也。养生丧死无憾，王道之始也。五亩之宅，树之以桑，五十者可以衣帛矣。鸡豚狗彘之畜，无失其时，七十者可以食肉矣。百亩之田，勿夺其时，数口之家，可以无饥矣；谨庠序之教，申之以孝悌之义，颁白者不负戴于道路矣。七十者衣帛食肉，黎民不饥不寒，然而不王者，未之有也。狗彘食人食而不知检，涂有饿莩而不知发，人死，则曰：‘非我也，岁也。’是何异于刺人而杀之，曰‘非我也，兵也’?王无罪岁，斯天下之民至焉。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '寡人之于国也' AND p.poem_author = '孟子弟子录';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三衢道中', '曾几', '宋代', '梅子黄时日日晴，小溪泛尽却山行。\n绿阴不减来时路，添得黄鹂四五声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三衢道中' AND p.poem_author = '曾几';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('田家元日', '孟浩然', '唐代', '昨夜斗回北，今朝岁起东。\n我年已强仕，无禄尚忧农。\n桑野就耕父，荷锄随牧童。\n田家占气候，共说此年丰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '田家元日' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('劝学诗 / 偶成', '朱熹', '宋代', '少年易老学难成，一寸光阴不可轻。\n未觉池塘春草梦，阶前梧叶已秋声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '劝学诗 / 偶成' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜算子·黄州定慧院寓居作', '苏轼', '宋代', '缺月挂疏桐，漏断人初静。时见幽人独往来，缥缈孤鸿影。(时见 一作：谁见)\n惊起却回头，有恨无人省。拣尽寒枝不肯栖，寂寞沙洲冷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜算子·黄州定慧院寓居作' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凉州词二首', '王之涣', '唐代', '黄河远上白云间，一片孤城万仞山。\n羌笛何须怨杨柳，春风不度玉门关。\n\n单于北望拂云堆，杀马登坛祭几回。\n汉家天子今神武，不肯和亲归去来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凉州词二首' AND p.poem_author = '王之涣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('端午', '李隆基', '唐代', '端午临中夏，时清日复长。\n盐梅已佐鼎，曲糵且传觞。\n事古人留迹，年深缕积长。\n当轩知槿茂，向水觉芦香。\n亿兆同归寿，群公共保昌。\n忠贞如不替，贻厥后昆芳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '端午' AND p.poem_author = '李隆基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('后出师表', '诸葛亮', '魏晋', '先帝深虑汉、贼不两立，王业不偏安，故托臣以讨贼也。以先帝之明，量臣之才，固知臣伐贼，才弱敌强也。然不伐贼，王业亦亡。惟坐而待亡，孰与伐之？是故托臣而弗疑也。\n\n　　臣受命之日，寝不安席，食不甘味。思惟北征。宜先入南。故五月渡泸，深入不毛，并日而食；臣非不自惜也，顾王业不可得偏安于蜀都，故冒危难，以奉先帝之遗意也，而议者谓为非计。今贼适疲于西，又务于东，兵法乘劳，此进趋之时也。谨陈其事如左：\n\n　　高帝明并日月，谋臣渊深，然涉险被创，危然后安。今陛下未及高帝，谋臣不如良、平，而欲以长策取胜，坐定天下，此臣之未解一也。\n\n　　刘繇、王朗各据州郡，论安言计，动引圣人，群疑满腹，众难塞胸，今岁不战，明年不征，使孙策坐大，遂并江东，此臣之未解二也。\n\n　　曹操智计，殊绝于人，其用兵也，仿佛孙、吴，然困于南阳，险于乌巢，危于祁连，逼于黎阳，几败北山，殆死潼关，然后伪定一时耳。况臣才弱，而欲以不危而定之，此臣之未解三也。\n\n　　曹操五攻昌霸不下，四越巢湖不成，任用李服而李服图之，委任夏侯而夏侯败亡，先帝每称操为能，犹有此失，况臣驽下，何能必胜？此臣之未解四也。\n\n　　自臣到汉中，中间期年耳，然丧赵云、阳群、马玉、阎芝、丁立、白寿、刘郃、邓铜等及曲长、屯将七十余人，突将、无前、賨叟、青羌、散骑、武骑一千余人。此皆数十年之内所纠合四方之精锐，非一州之所有；若复数年，则损三分之二也，当何以图敌？此臣之未解五也。\n\n　　今民穷兵疲，而事不可息；事不可息，则住与行劳费正等。而不及今图之，欲以一州之地，与贼持久，此臣之未解六也。\n\n　　夫难平者，事也。昔先帝败军于楚，当此时，曹操拊手，谓天下已定。然后先帝东连吴越，西取巴蜀，举兵北征，夏侯授首，此操之失计，而汉事将成也。然后吴更违盟，关羽毁败，秭归蹉跌，曹丕称帝。凡事如是，难可逆见。臣鞠躬尽瘁，死而后已。至于成败利钝，非臣之明所能逆睹也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '后出师表' AND p.poem_author = '诸葛亮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清明即事', '孟浩然', '唐代', '帝里重清明，人心自愁思。\n车声上路合，柳色东城翠。\n花落草齐生，莺飞蝶双戏。\n空堂坐相忆，酌茗聊代醉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清明即事' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('摸鱼儿·雁丘词 / 迈陂塘', '元好问', '金朝', '乙丑岁赴试并州，道逢捕雁者云：“今旦获一雁，杀之矣。其脱网者悲鸣不能去，竟自投于地而死。”予因买得之，葬之汾水之上，垒石为识，号曰“雁丘”。同行者多为赋诗，予亦有《雁丘词》。旧所作无宫商，今改定之。\n\n问世间，情为何物，直教生死相许？\n天南地北双飞客，老翅几回寒暑。\n欢乐趣，离别苦，就中更有痴儿女。\n君应有语：渺万里层云，千山暮雪，只影向谁去？\n横汾路，寂寞当年箫鼓，荒烟依旧平楚。\n招魂楚些何嗟及，山鬼暗啼风雨。\n天也妒，未信与，莺儿燕子俱黄土。\n千秋万古，为留待骚人，狂歌痛饮，来访雁丘处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '摸鱼儿·雁丘词 / 迈陂塘' AND p.poem_author = '元好问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采莲曲', '王昌龄', '唐代', '荷叶罗裙一色裁，芙蓉向脸两边开。\n乱入池中看不见，闻歌始觉有人来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采莲曲' AND p.poem_author = '王昌龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('击鼓', '佚名', '先秦', '击鼓其镗，踊跃用兵。土国城漕，我独南行。\n从孙子仲，平陈与宋。不我以归，忧心有忡。\n爰居爰处？爰丧其马？于以求之？于林之下。\n死生契阔，与子成说。执子之手，与子偕老。\n于嗟阔兮，不我活兮。于嗟洵兮，不我信兮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '击鼓' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('旅夜书怀', '杜甫', '唐代', '细草微风岸，危樯独夜舟。\n星垂平野阔，月涌大江流。\n名岂文章著，官应老病休。\n飘飘何所似，天地一沙鸥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '旅夜书怀' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八声甘州·对潇潇暮雨洒江天', '柳永', '宋代', '对潇潇暮雨洒江天，一番洗清秋。渐霜风凄紧，关河冷落，残照当楼。是处红衰翠减，苒苒物华休。唯有长江水，无语东流。 \n不忍登高临远，望故乡渺邈，归思难收。叹年来踪迹，何事苦淹留？想佳人妆楼颙望，误几回、天际识归舟。争知我，倚阑杆处，正恁凝愁！(阑 一作：栏)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '八声甘州·对潇潇暮雨洒江天' AND p.poem_author = '柳永';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望江南·超然台作', '苏轼', '宋代', '春未老，风细柳斜斜。试上超然台上看，半壕春水一城花。烟雨暗千家。\n寒食后，酒醒却咨嗟。休对故人思故国，且将新火试新茶。诗酒趁年华。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望江南·超然台作' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏鹅', '骆宾王', '唐代', '鹅，鹅，鹅，曲项向天歌。\n白毛浮绿水，红掌拨清波。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏鹅' AND p.poem_author = '骆宾王';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江畔独步寻花七绝句', '杜甫', '唐代', '江上被花恼不彻，无处告诉只颠狂。\n走觅南邻爱酒伴，经旬出饮独空床。\n\n稠花乱蕊畏江滨，行步欹危实怕春。(畏 一作：裹）\n诗酒尚堪驱使在，未须料理白头人。\n\n江深竹静两三家，多事红花映白花。\n报答春光知有处，应须美酒送生涯。\n\n东望少城花满烟，百花高楼更可怜。\n谁能载酒开金盏，唤取佳人舞绣筵。\n\n黄师塔前江水东，春光懒困倚微风。\n桃花一簇开无主，可爱深红爱浅红？\n\n黄四娘家花满蹊，千朵万朵压枝低。\n留连戏蝶时时舞，自在娇莺恰恰啼。\n\n不是爱花即欲死，只恐花尽老相催。\n繁枝容易纷纷落，嫩蕊商量细细开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江畔独步寻花七绝句' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陈元方候袁公', '刘义庆', '南北朝', '陈元方年十一时，候袁公。袁公问曰：“贤家君在太丘，远近称之，何所履行？”元方曰：“老父在太丘，强者绥之以德，弱者抚之以仁，恣其所安，久而益敬。”袁公曰：“孤往者尝为邺令，正行此事。不知卿家君法孤，孤法卿父？”元方曰：“周公、孔子异世而出，周旋动静，万里如一。周公不师孔子，孔子亦不师周公。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '陈元方候袁公' AND p.poem_author = '刘义庆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绝句二首·其二', '杜甫', '唐代', '江碧鸟逾白，山青花欲燃。\n今春看又过，何日是归年？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绝句二首·其二' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九月十日即事', '李白', '唐代', '昨日登高罢，今朝更举觞。\n菊花何太苦，遭此两重阳？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九月十日即事' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九歌·国殇', '屈原', '先秦', '操吴戈兮被犀甲，车错毂兮短兵接。\n旌蔽日兮敌若云，矢交坠兮士争先。\n凌余阵兮躐余行，左骖殪兮右刃伤。\n霾两轮兮絷四马，援玉枹兮击鸣鼓。\n天时怼兮威灵怒，严杀尽兮弃原野。\n出不入兮往不反，平原忽兮路超远。\n带长剑兮挟秦弓，首身离兮心不惩。\n诚既勇兮又以武，终刚强兮不可凌。\n身既死兮神以灵，魂魄毅兮为鬼雄。(魂魄毅兮 一作：子魂魄兮)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九歌·国殇' AND p.poem_author = '屈原';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('逍遥游(节选)', '庄周', '先秦', '北冥有鱼，其名为鲲。鲲之大，不知其几千里也。化而为鸟，其名为鹏。鹏之背，不知其几千里也，怒而飞，其翼若垂天之云。是鸟也，海运则将徙于南冥。南冥者，天池也。《齐谐》者，志怪者也。《谐》之言曰：“鹏之徙于南冥也，水击三千里，抟扶摇而上者九万里，去以六月息者也。”野马也，尘埃也，生物之以息相吹也。天之苍苍，其正色邪？其远而无所至极邪？其视下也，亦若是则已矣。且夫水之积也不厚，则其负大舟也无力。覆杯水于坳堂之上，则芥为之舟；置杯焉则胶，水浅而舟大也。风之积也不厚，则其负大翼也无力。故九万里，则风斯在下矣，而后乃今培风；背负青天而莫之夭阏者，而后乃今将图南。\n\n　　蜩与学鸠笑之曰：“我决起而飞，抢榆枋而止，时则不至，而控于地而已矣，奚以之九万里而南为？”适莽苍者，三餐而反，腹犹果然；适百里者宿舂粮，适千里者，三月聚粮。之二虫又何知？(抢榆枋 一作：枪榆枋)\n\n　　小知不及大知，小年不及大年。奚以知其然也？朝菌不知晦朔，蟪蛄不知春秋，此小年也。楚之南有冥灵者，以五百岁为春，五百岁为秋。上古有大椿者，以八千岁为春，八千岁为秋。此大年也。而彭祖乃今以久特闻，众人匹之。不亦悲乎！\n\n　　汤之问棘也是已：“穷发之北有冥海者，天池也。有鱼焉，其广数千里，未有知其修者，其名为鲲。有鸟焉，其名为鹏。背若泰山，翼若垂天之云。抟扶摇羊角而上者九万里，绝云气，负青天，然后图南，且适南冥也。斥鷃笑之曰：‘彼且奚适也？我腾跃而上，不过数仞而下，翱翔蓬蒿之间，此亦飞之至也。而彼且奚适也？’”此小大之辩也。\n\n　　故夫知效一官，行比一乡，德合一君，而征一国者，其自视也亦若此矣。而宋荣子犹然笑之。且举世誉之而不加劝，举世非之而不加沮，定乎内外之分，辩乎荣辱之境，斯已矣。彼其于世，未数数然也。虽然，犹有未树也。夫列子御风而行，泠然善也。旬有五日而后反。彼于致福者，未数数然也。此虽免乎行，犹有所待者也。若夫乘天地之正，而御六气之辩，以游无穷者，彼且恶乎待哉？故曰：至人无己，神人无功，圣人无名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '逍遥游(节选)' AND p.poem_author = '庄周';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水龙吟·次韵章质夫杨花词', '苏轼', '宋代', '似花还似非花，也无人惜从教坠。抛家傍路，思量却是，无情有思。萦损柔肠，困酣娇眼，欲开还闭。梦随风万里，寻郎去处，又还被、莺呼起。\n不恨此花飞尽，恨西园、落红难缀。晓来雨过，遗踪何在？一池萍碎。春色三分，二分尘土，一分流水。细看来，不是杨花，点点是离人泪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水龙吟·次韵章质夫杨花词' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('扬州慢·淮左名都', '姜夔', '宋代', '淳熙丙申至日，予过维扬。夜雪初霁，荠麦弥望。入其城，则四顾萧条，寒水自碧，暮色渐起，戍角悲吟。予怀怆然，感慨今昔，因自度此曲。千岩老人以为有“黍离”之悲也。\n\n淮左名都，竹西佳处，解鞍少驻初程。过春风十里。尽荠麦青青。自胡马窥江去后，废池乔木，犹厌言兵。渐黄昏，清角吹寒。都在空城。 \n杜郎俊赏，算而今、重到须惊。纵豆蔻词工，青楼梦好，难赋深情。二十四桥仍在，波心荡、冷月无声。念桥边红药，年年知为谁生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '扬州慢·淮左名都' AND p.poem_author = '姜夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月·世事一场大梦', '苏轼', '宋代', '世事一场大梦，人生几度秋凉？夜来风叶已鸣廊。看取眉头鬓上。(秋凉 一作：新凉)\n酒贱常愁客少，月明多被云妨。中秋谁与共孤光。把盏凄然北望。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月·世事一场大梦' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('除夜', '文天祥', '宋代', '乾坤空落落，岁月去堂堂；\n末路惊风雨，穷边饱雪霜。\n命随年欲尽，身与世俱忘；\n无复屠苏梦，挑灯夜未央。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '除夜' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('狼三则', '蒲松龄', '清代', '其一\n　　有屠人货肉归，日已暮，欻一狼来，瞰担上肉，似甚垂涎，随尾行数里。屠惧，示之以刃，少却；及走，又从之。屠无计，思狼所欲者肉，不如姑悬诸树而早取之。遂钩肉，翘足挂树间，示以空担。狼乃止。屠归。昧爽，往取肉，遥望树上悬巨物，似人缢死状。大骇，逡巡近视之，则死狼也。仰首细审，见狼口中含肉，钩刺狼腭，如鱼吞饵。时狼皮价昂，直十余金，屠小裕焉。缘木求鱼，狼则罹之，是可笑也。\n\n其二\n　　一屠晚归，担中肉尽，止有剩骨。途中两狼，缀行甚远。\n　　屠惧，投以骨。一狼得骨止，一狼仍从。复投之，后狼止而前狼又至。骨已尽矣，而两狼之并驱如故。\n　　屠大窘，恐前后受其敌。顾野有麦场，场主积薪其中，苫蔽成丘。屠乃奔倚其下，弛担持刀。狼不敢前，眈眈相向。\n　　少时，一狼径去，其一犬坐于前。久之，目似瞑，意暇甚。屠暴起，以刀劈狼首，又数刀毙之。方欲行，转视积薪后，一狼洞其中，意将隧入以攻其后也。身已半入，止露尻尾。屠自后断其股，亦毙之。乃悟前狼假寐，盖以诱敌。\n　　狼亦黠矣，而顷刻两毙，禽兽之变诈几何哉？止增笑耳。\n\n其三\n　　一屠暮行，为狼所逼。道旁有夜耕所遗行室，奔入伏焉。狼自苫中探爪入。屠急捉之，令不可去。但思无计可以死之。惟有小刀不盈寸，遂割破狼爪下皮，以吹豕之法吹之。极力吹移时，觉狼不甚动，方缚以带。出视，则狼胀如牛，股直不能屈，口张不得合。遂负之以归。\n　　非屠，乌能作此谋也！\n　　三事皆出于屠；则屠人之残爆，杀狼亦可用也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '狼三则' AND p.poem_author = '蒲松龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('燕歌行二首·其一', '曹丕', '魏晋', '秋风萧瑟天气凉，草木摇落露为霜，群燕辞归鹄南翔。(鹄南翔 一作 雁南翔）\n念君客游思断肠，慊慊思归恋故乡，君何淹留寄他方？\n贱妾茕茕守空房，忧来思君不敢忘，不觉泪下沾衣裳。\n援琴鸣弦发清商，短歌微吟不能长。\n明月皎皎照我床，星汉西流夜未央。\n牵牛织女遥相望，尔独何辜限河梁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '燕歌行二首·其一' AND p.poem_author = '曹丕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('叶公好龙', '刘向', '两汉', '叶公子高好龙，钩以写龙，凿以写龙，屋室雕文以写龙。于是天龙闻而下之，窥头于牖，施尾于堂。 叶公见之，弃而还走，失其魂魄，五色无主。是叶公非好龙也，好夫似龙而非龙者也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '叶公好龙' AND p.poem_author = '刘向';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('公输', '墨子及弟子', '先秦', '公输盘为楚造云梯之械，成，将以攻宋。子墨子闻之，起于鲁，行十日十夜，而至于郢，见公输盘。\n\n　　公输盘曰：“夫子何命焉为？”\n\n　　子墨子曰：“北方有侮臣者，愿借子杀之。”公输盘不说。\n\n　　子墨子曰：“请献十金。”\n\n　　公输盘曰：“吾义固不杀人。”\n\n　　子墨子起，再拜，曰：“请说之。吾从北方闻子为梯，将以攻宋。宋何罪之有？荆国有余于地，而不足于民，杀所不足而争所有余，不可谓智；宋无罪而攻之，不可谓仁；知而不争，不可谓忠。争而不得，不可谓强。义不杀少而杀众，不可谓知类。”\n\n　　公输盘服。\n\n　　子墨子曰：“然胡不已乎？”\n\n　　公输盘曰：“不可，吾既已言之王矣。”\n\n　　子墨子曰：“胡不见我于王？”\n\n　　公输盘曰：“诺。”\n\n　　子墨子见王，曰：“今有人于此，舍其文轩，邻有敝舆而欲窃之；舍其锦绣，邻有短褐而欲窃之；舍其粱肉，邻有糠糟而欲窃之——此为何若人？”\n\n　　王曰：“必为有窃疾矣。”\n\n　　子墨子曰：“荆之地方五千里，宋之地方五百里，此犹文轩之与敝舆也。荆有云梦，犀兕麋鹿满之，江汉之鱼鳖鼋鼍为天下富，宋所谓无雉兔鲋鱼者也，此犹粱肉之与糠糟也。荆有长松文梓楩楠豫章，宋无长木，此犹锦绣之与短褐也。臣以王吏之攻宋也，为与此同类。”\n\n　　王曰：“善哉！虽然，公输盘为我为云梯，必取宋。”\n\n　　于是见公输盘。子墨子解带为城，以牒为械，公输盘九设攻城之机变，子墨子九距之。公输盘之攻械尽，子墨子之守圉有余。\n\n　　公输盘诎，而曰：“吾知所以距子矣，吾不言。”\n\n　　子墨子亦曰：“吾知子之所以距我，吾不言。”\n\n　　楚王问其故。\n\n　　子墨子曰：“公输子之意不过欲杀臣。杀臣，宋莫能守，乃可攻也。然臣之弟子禽滑厘等三百人，已持臣守圉之器，在宋城上而待楚寇矣。虽杀臣，不能绝也。”\n\n　　楚王曰：“善哉。吾请无攻宋矣。”\n\n　　子墨子归，过宋。天雨，庇其闾中，守闾者不内也。故曰：治于神者，众人不知其功。争于明者，众人知之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '公输' AND p.poem_author = '墨子及弟子';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送别 / 山中送别', '王维', '唐代', '山中相送罢，日暮掩柴扉。\n春草明年绿，王孙归不归？(明年 一作：年年)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送别 / 山中送别' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('狱中题壁', '谭嗣同', '近代', '望门投止思张俭，忍死须臾待杜根。\n我自横刀向天笑，去留肝胆两昆仑。(版本一)\n\n望门投趾怜张俭，直谏陈书愧杜根。\n手掷欧刀仰天笑，留将公罪后人论。(版本二)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '狱中题壁' AND p.poem_author = '谭嗣同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·夜饮东坡醒复醉', '苏轼', '宋代', '夜饮东坡醒复醉，归来仿佛三更。家童鼻息已雷鸣。敲门都不应，倚杖听江声。 \n长恨此身非我有，何时忘却营营。夜阑风静縠纹平。小舟从此逝，江海寄余生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·夜饮东坡醒复醉' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白梅', '王冕', '元代', '冰雪林中著此身，不同桃李混芳尘。\n忽然一夜清香发，散作乾坤万里春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白梅' AND p.poem_author = '王冕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乞巧', '林杰', '唐代', '七夕今宵看碧霄，牵牛织女渡河桥。 \n家家乞巧望秋月，穿尽红丝几万条。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '乞巧' AND p.poem_author = '林杰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读书', '陆游', '宋代', '归志宁无五亩园，读书本意在元元。\n灯前目力虽非昔，犹课蝇头二万言。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读书' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '问刘十九' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新年作', '刘长卿', '唐代', '乡心新岁切，天畔独潸然。\n老至居人下，春归在客先。\n岭猿同旦暮，江柳共风烟。\n已似长沙傅，从今又几年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新年作' AND p.poem_author = '刘长卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书愤五首·其一', '陆游', '宋代', '早岁那知世事艰，中原北望气如山。\n楼船夜雪瓜洲渡，铁马秋风大散关。\n塞上长城空自许，镜中衰鬓已先斑。\n出师一表真名世，千载谁堪伯仲间！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书愤五首·其一' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寒食野望吟', '白居易', '唐代', '乌啼鹊噪昏乔木，清明寒食谁家哭。\n风吹旷野纸钱飞，古墓垒垒春草绿。\n棠梨花映白杨树，尽是死生别离处。\n冥冥重泉哭不闻，萧萧暮雨人归去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寒食野望吟' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜雪', '白居易', '唐代', '已讶衾枕冷，复见窗户明。\n夜深知雪重，时闻折竹声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜雪' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('画眉鸟', '欧阳修', '宋代', '百啭千声随意移，山花红紫树高低。\n始知锁向金笼听，不及林间自在啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '画眉鸟' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠从弟', '刘桢', '魏晋', '亭亭山上松，瑟瑟谷中风。\n风声一何盛，松枝一何劲。\n冰霜正惨凄，终岁常端正。\n岂不罹凝寒，松柏有本性。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠从弟' AND p.poem_author = '刘桢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝉', '虞世南', '唐代', '垂緌饮清露，流响出疏桐。\n居高声自远，非是藉秋风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝉' AND p.poem_author = '虞世南';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金缕衣', '佚名', '唐代', '劝君莫惜金缕衣，劝君惜取少年时。(惜取 一作：须取)\n花开堪折直须折，莫待无花空折枝。(花开 一作：有花)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金缕衣' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮·小山重叠金明灭', '温庭筠', '唐代', '小山重叠金明灭，鬓云欲度香腮雪。懒起画蛾眉，弄妆梳洗迟。\n照花前后镜，花面交相映。新帖绣罗襦，双双金鹧鸪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮·小山重叠金明灭' AND p.poem_author = '温庭筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荆轲刺秦王', '刘向 编', '两汉', '秦将王翦破赵，虏赵王，尽收其地，进兵北略地，至燕南界。\n\n　　太子丹恐惧，乃请荆卿曰：“秦兵旦暮渡易水，则虽欲长侍足下，岂可得哉？”荆卿曰：“微太子言，臣愿得谒之。今行而无信，则秦未可亲也。夫今樊将军，秦王购之金千斤，邑万家。诚能得樊将军首，与燕督亢之地图，献秦王，秦王必说见臣，臣乃得有以报太子。”太子曰：“樊将军以穷困来归丹，丹不忍以己之私，而伤长者之意，愿足下更虑之！”\n\n　　荆轲知太子不忍，乃遂私见樊於期，曰：“秦之遇将军，可谓深矣。父母宗族，皆为戮没。今闻购樊将军之首，金千斤，邑万家，将奈何？”樊将军仰天太息流涕曰：“吾每念，常痛于骨髓，顾计不知所出耳！”轲曰：“今有一言，可以解燕国之患，而报将军之仇者，何如？”於期乃前曰：“为之奈何？”荆轲曰：“愿得将军之首以献秦，秦王必喜而善见臣。臣左手把其袖，而右手揕其胸，然则将军之仇报，而燕国见陵之耻除矣。将军岂有意乎？”樊於期偏袒扼腕而进曰：“此臣之日夜切齿拊心也，乃今得闻教！”遂自刎。\n\n　　太子闻之，驰往，伏尸而哭，极哀。既已，不可奈何，乃遂盛樊於期之首，函封之。\n\n　　于是太子预求天下之利匕首，得赵人徐夫人之匕首，取之百金，使工以药 淬之。以试人，血濡缕,人无不立死者。乃为装遣荆轲。\n\n　　燕国有勇士秦武阳，年十二，杀人，人不敢与忤视。乃令秦武阳为副。(秦武阳 一作：秦舞阳)\n\n　　荆轲有所待，欲与俱，其人居远未来，而为留待。\n\n　　顷之未发，太子迟之。疑其有改悔，乃复请之曰：“日以尽矣，荆卿岂无意哉？丹请先遣秦武阳！”荆轲怒， 叱太子曰：“今日往而不反者，竖子也！今提一匕首入不测之强秦，仆所以留者，待吾客与俱。今太子迟之，请辞决矣！”遂发。\n\n　　太子及宾客知其事者，皆白衣冠以送之。至易水上，既祖，取道。高渐离击筑，荆轲和而歌，为变徵之声，士皆垂泪涕泣。又前而为歌曰：“风萧萧兮易水寒，壮士一去兮不复还！”复为慷慨羽声，士皆瞋目，发尽上指冠。于是荆轲遂就车而去，终已不顾。\n\n　　既至秦，持千金之资币物，厚遗wèi秦王宠臣中庶子蒙嘉。\n\n　　嘉为先言于秦王曰：“燕王诚振怖大王之威，不敢兴兵以拒大王，愿举国为内臣。比诸侯之列，给贡职如郡县，而得奉守先王之宗庙。恐惧不敢自陈，谨斩樊於期头，及献燕之督亢之地图，函封，燕王拜送于庭，使使以闻大王。唯大王命之。”\n\n　　秦王闻之，大喜。乃朝服，设九宾，见燕使者咸阳宫。\n\n　　荆轲奉樊於期头函，而秦武阳奉地图匣，以次进。至陛下，秦武阳色变振恐，群臣怪之，荆轲顾笑武阳，前为谢曰：“北蛮夷之鄙人，未尝见天子，故振慑，愿大王少假借之，使毕使于前。”秦王谓轲曰：“起，取武阳所持图！”\n\n　　轲既取图奉之， 发图，图穷而匕首见。因左手把秦王之袖，而右手持匕首揕之。未至身，秦王惊，自引而起，绝袖。拔剑，剑长，操其室。时恐急，剑坚，故不可立拔。\n\n　　荆轲逐秦王，秦王还柱而走。群臣惊愕，卒起不意，尽失其度。而秦法，群臣侍殿上者，不得持尺兵；诸郎中执兵，皆陈殿下，非有诏不得上。方急时，不及召下兵，以故荆轲逐秦王，而卒惶急无以击轲，而乃以手共搏之。\n\n　　是时，侍医夏无且以其所奉药囊提轲。秦王方还柱走，卒惶急不知所为。左右乃曰：“王负剑！王负剑！”遂拔以击荆轲，断其左股。荆轲废，乃引其匕首提秦王，不中，中柱。秦王复击轲，被八创。\n\n　　轲自知事不就，倚柱而笑，箕踞以骂曰：“事所以不成者，乃欲以生劫之，必得约契以报太子也。”\n\n　　左右既前，斩荆轲。秦王目眩良久。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '荆轲刺秦王' AND p.poem_author = '刘向 编';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行香子·秋与', '苏轼', '宋代', '昨夜霜风。先入梧桐。浑无处、回避衰容。问公何事，不语书空。但一回醉，一回病，一回慵；\n朝来庭下，光阴如箭，似无言、有意伤侬。都将万事，付与千钟。任酒花白，眼花乱，烛花红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行香子·秋与' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过秦论', '贾谊', '两汉', '上篇\n　　秦孝公据崤函之固，拥雍州之地，君臣固守以窥周室，有席卷天下，包举宇内，囊括四海之意，并吞八荒之心。当是时也，商君佐之，内立法度，务耕织，修守战之具；外连衡而斗诸侯。于是秦人拱手而取西河之外。\n　　孝公既没，惠文、武、昭襄蒙故业，因遗策，南取汉中，西举巴、蜀，东割膏腴之地，北收要害之郡。诸侯恐惧，会盟而谋弱秦，不爱珍器重宝肥饶之地，以致天下之士，合从缔交，相与为一。当此之时，齐有孟尝，赵有平原，楚有春申，魏有信陵。此四君者，皆明智而忠信，宽厚而爱人，尊贤而重士，约从离衡，兼韩、魏、燕、楚、齐、赵、宋、卫、中山之众。于是六国之士，有宁越、徐尚、苏秦、杜赫之属为之谋，齐明、周最、陈轸、召滑、楼缓、翟景、苏厉、乐毅之徒通其意，吴起、孙膑、带佗、倪良、王廖、田忌、廉颇、赵奢之伦制其兵。尝以十倍之地，百万之众，叩关而攻秦。秦人开关延敌，九国之师，逡巡而不敢进。秦无亡矢遗镞之费，而天下诸侯已困矣。于是从散约败，争割地而赂秦。秦有余力而制其弊，追亡逐北，伏尸百万，流血漂橹。因利乘便，宰割天下，分裂山河。强国请服，弱国入朝。延及孝文王、庄襄王，享国之日浅，国家无事。\n　　及至始皇，奋六世之余烈，振长策而御宇内，吞二周而亡诸侯，履至尊而制六合，执敲扑而鞭笞天下，威振四海。南取百越之地，以为桂林、象郡；百越之君，俯首系颈，委命下吏。乃使蒙恬北筑长城而守藩篱，却匈奴七百余里。胡人不敢南下而牧马，士不敢弯弓而报怨。于是废先王之道，焚百家之言，以愚黔首；隳名城，杀豪杰，收天下之兵，聚之咸阳，销锋镝，铸以为金人十二，以弱天下之民。然后践华为城，因河为池，据亿丈之城，临不测之渊，以为固。良将劲弩守要害之处，信臣精卒陈利兵而谁何。天下已定，始皇之心，自以为关中之固，金城千里，子孙帝王万世之业也。\n　　始皇既没，余威震于殊俗。然陈涉瓮牖绳枢之子，氓隶之人，而迁徙之徒也；才能不及中人，非有仲尼、墨翟之贤，陶朱、猗顿之富；蹑足行伍之间，而倔起阡陌之中，率疲弊之卒，将数百之众，转而攻秦，斩木为兵，揭竿为旗，天下云集响应，赢粮而景从。山东豪俊遂并起而亡秦族矣。\n　　且夫天下非小弱也，雍州之地，崤函之固，自若也。陈涉之位，非尊于齐、楚、燕、赵、韩、魏、宋、卫、中山之君也；锄耰棘矜，非铦于钩戟长铩也；谪戍之众，非抗于九国之师也；深谋远虑，行军用兵之道，非及向时之士也。然而成败异变，功业相反，何也?试使山东之国与陈涉度长絜大，比权量力，则不可同年而语矣。然秦以区区之地，致万乘之势，序八州而朝同列，百有余年矣；然后以六合为家，崤函为宫；一夫作难而七庙隳，身死人手，为天下笑者，何也？仁义不施而攻守之势异也。\n\n中篇\n　　秦灭周祀，并海内，兼诸侯，南面称帝，以养四海。天下之士，斐然向风。若是，何也？曰：近古之无王者久矣。周室卑微，五霸既灭，令不行于天下。是以诸侯力政，强凌弱，众暴寡，兵革不休，士民罢弊。今秦南面而王天下，是上有天子也。既元元之民冀得安其性命，莫不虚心而仰上。当此之时，专威定功，安危之本，在于此矣。\n　　秦王怀贪鄙之心，行自奋之智，不信功臣，不亲士民，废王道而立私爱，焚文书而酷刑法，先诈力而后仁义，以暴虐为天下始。夫兼并者高诈力，安危者贵顺权，此言取与守不同术也。秦离战国而王天下，其道不易，其政不改，是其所以取之守之者无异也。孤独而有之，故其亡可立而待也。借使秦王论上世之事，并殷、周之迹，以制御其政，后虽有淫骄之主，犹未有倾危之患也。故三王之建天下，名号显美，功业长久。\n　　今秦二世立，天下莫不引领而观其政。夫寒者利裋褐，而饥者甘糟糠。天下嚣嚣，新主之资也。此言劳民之易为仁也。向使二世有庸主之行而任忠贤，臣主一心而忧海内之患，缟素而正先帝之过；裂地分民以封功臣之后，建国立君以礼天下；虚囹圄而免刑戮，去收孥污秽之罪，使各反其乡里；发仓廪，散财币，以振孤独穷困之士；轻赋少事，以佐百姓之急；约法省刑，以持其后，使天下之人皆得自新，更节修行，各慎其身；塞万民之望，而以盛德与天下，天下息矣。即四海之内皆欢然各自安乐其处，惟恐有变。虽有狡害之民，无离上之心，则不轨之臣无以饰其智，而暴乱之奸弭矣。\n　　二世不行此术，而重以无道：坏宗庙与民，更始作阿房之宫；繁刑严诛，吏治刻深；赏罚不当，赋敛无度。天下多事，吏不能纪；百姓困穷，而主不收恤。然后奸伪并起，而上下相遁；蒙罪者众，刑戮相望于道，而天下苦之。自群卿以下至于众庶，人怀自危之心，亲处穷苦之实，咸不安其位，故易动也。是以陈涉不用汤、武之贤，不借公侯之尊，奋臂于大泽，而天下响应者，其民危也。\n　　故先王者，见终始不变，知存亡之由。是以牧民之道，务在安之而已矣。下虽有逆行之臣，必无响应之助。故曰：“安民可与为义，而危民易与为非”，此之谓也。贵为天子，富有四海，身在于戮者，正之非也。是二世之过也。\n\n下篇\n　　秦兼诸侯山东三十余郡，脩津关，据险塞，缮甲兵而守之。然陈涉率散乱之众数百，奋臂大呼，不用弓戟之兵，鉏耰白梃，望屋而食，横行天下。秦人阻险不守，关梁不闭，长戟不刺，强弩不射。楚师深入，战于鸿门，曾无藩篱之难。于是山东诸侯并起，豪俊相立。秦使章邯将而东征，章邯因其三军之众，要市于外，以谋其上。群臣之不相信，可见于此矣。子婴立，遂不悟。借使子婴有庸主之材而仅得中佐，山东虽乱，三秦之地可全而有，宗庙之祀宜未绝也。\n　　秦地被山带河以为固，四塞之国也。自缪公以来至于秦王二十余君，常为诸侯雄。此岂世贤哉？其势居然也。且天下尝同心并力攻秦矣，然困于险阻而不能进者，岂勇力智慧不足哉？形不利、势不便也。秦虽小邑，伐并大城，得阨塞而守之。诸侯起于匹夫，以利会，非有素王之行也。其交未亲，其民未附，名曰亡秦，其实利之也。彼见秦阻之难犯，必退师。案土息民以待其弊，收弱扶罢以令大国之君，不患不得意于海内。贵为天子，富有四海，而身为禽者，救败非也。\n　　秦王足己而不问，遂过而不变。二世受之，因而不改，暴虐以重祸。子婴孤立无亲，危弱无辅。三主之惑，终身不悟，亡不亦宜乎？当此时也，也非无深谋远虑知化之士也，然所以不敢尽忠指过者，秦俗多忌讳之禁也，——忠言未卒于口而身糜没矣。故使天下之士倾耳而听，重足而立，阖口而不言。是以三主失道，而忠臣不谏，智士不谋也。天下已乱，奸不上闻，岂不悲哉！先王知壅蔽之伤国也，故置公卿、大夫、士，以饰法设刑而天下治。其强也，禁暴诛乱而天下服；其弱也，王霸征而诸侯从；其削也，内守外附而社稷存。故秦之盛也，繁法严刑而天下震；及其衰也，百姓怨而海内叛矣。故周王序得其道，千余载不绝；秦本末并失，故不能长。由是观之，安危之统相去远矣。\n　　鄙谚曰：“前事之不忘，后事之师也。”是以君子为国，观之上古，验之当世，参之人事，察盛衰之理，审权势之宜，去就有序，变化因时，故旷日长久而社稷安矣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '过秦论' AND p.poem_author = '贾谊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·梦后楼台高锁', '晏几道', '宋代', '梦后楼台高锁，酒醒帘幕低垂。去年春恨却来时。落花人独立，微雨燕双飞。 \n记得小蘋初见，两重心字罗衣。琵琶弦上说相思。当时明月在，曾照彩云归。(蘋 通：苹)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·梦后楼台高锁' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陌上桑', '乐府诗集', '两汉', '日出东南隅，照我秦氏楼。秦氏有好女，自名为罗敷。罗敷喜蚕桑，采桑城南隅。青丝为笼系，桂枝为笼钩。头上倭堕髻，耳中明月珠。缃绮为下裙，紫绮为上襦。行者见罗敷，下担捋髭须。少年见罗敷，脱帽著帩头。耕者忘其犁，锄者忘其锄。来归相怨怒，但坐观罗敷。(喜蚕桑 一作：善蚕桑；相怨怒 一作：相怒怨)\n\n　　使君从南来，五马立踟蹰。使君遣吏往，问是谁家姝？“秦氏有好女，自名为罗敷。”“罗敷年几何？”“二十尚不足，十五颇有余”。使君谢罗敷：“宁可共载不？罗敷前致辞：“使君一何愚！使君自有妇，罗敷自有夫！”\n\n　　“东方千余骑，夫婿居上头。何用识夫婿？白马从骊驹，青丝系马尾，黄金络马头；腰中鹿卢剑，可值千万余。十五府小吏，二十朝大夫，三十侍中郎，四十专城居。为人洁白皙，鬑鬑颇有须。盈盈公府步，冉冉府中趋。坐中数千人，皆言夫婿殊。”(白晰 一作：白皙)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陌上桑' AND p.poem_author = '乐府诗集';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('终南别业', '王维', '唐代', '中岁颇好道，晚家南山陲。\n兴来每独往，胜事空自知。\n行到水穷处，坐看云起时。\n偶然值林叟，谈笑无还期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '终南别业' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登岳阳楼二首', '陈与义', '宋代', '洞庭之东江水西，帘旌不动夕阳迟。\n登临吴蜀横分地，徙倚湖山欲暮时。\n万里来游还望远，三年多难更凭危。\n白头吊古风霜里，老木沧波无限悲。\n\n天入平湖晴不风，夕帆和雁正浮空。\n楼头客子杪秋后，日落君山元气中。\n北望可堪回白首，南游聊得看丹枫。\n翰林物色分留少，诗到巴陵还未工。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登岳阳楼二首' AND p.poem_author = '陈与义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鲁山山行', '梅尧臣', '宋代', '适与野情惬，千山高复低。\n好峰随处改，幽径独行迷。\n霜落熊升树，林空鹿饮溪。\n人家在何许？云外一声鸡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鲁山山行' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('左迁至蓝关示侄孙湘', '韩愈', '唐代', '一封朝奏九重天，夕贬潮州路八千。\n欲为圣明除弊事，肯将衰朽惜残年！\n云横秦岭家何在？雪拥蓝关马不前。\n知汝远来应有意，好收吾骨瘴江边。（版本一）\n\n一封朝奏九重天，夕贬潮阳路八千。\n本为圣朝除弊政，敢将衰朽惜残年。\n云横秦岭家何在？雪拥蓝关马不前。\n知汝远来应有意，好收吾骨瘴江边。（版本二）', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '左迁至蓝关示侄孙湘' AND p.poem_author = '韩愈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平调·其一', '李白', '唐代', '云想衣裳花想容，春风拂槛露华浓。 \n若非群玉山头见，会向瑶台月下逢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平调·其一' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('折桂令·春情', '徐再思', '元代', '平生不会相思，才会相思，便害相思。\n身似浮云，心如飞絮，气若游丝。\n空一缕余香在此，盼千金游子何之。\n证候来时，正是何时？灯半昏时，月半明时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '折桂令·春情' AND p.poem_author = '徐再思';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寻隐者不遇 / 孙革访羊尊师诗', '贾岛', '唐代', '松下问童子，言师采药去。\n只在此山中，云深不知处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寻隐者不遇 / 孙革访羊尊师诗' AND p.poem_author = '贾岛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·樱桃落尽春归去', '李煜', '五代', '樱桃落尽春归去，蝶翻金粉双飞。子规啼月小楼西，玉钩罗幕，惆怅暮烟垂。\n别巷寂寥人散后，望残烟草低迷。炉香闲袅凤凰儿，空持罗带，回首恨依依。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·樱桃落尽春归去' AND p.poem_author = '李煜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐·别来春半', '李煜', '五代', '别来春半，触目柔肠断。砌下落梅如雪乱，拂了一身还满。(\n\'柔\'肠断 一作：愁肠断)\n雁来音信无凭，路遥归梦难成。离恨恰如春草，更行更远还生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐·别来春半' AND p.poem_author = '李煜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆秦娥·箫声咽', '李白', '唐代', '箫声咽，秦娥梦断秦楼月。秦楼月，年年柳色，灞陵伤别。\n乐游原上清秋节，咸阳古道音尘绝。音尘绝，西风残照，汉家陵阙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆秦娥·箫声咽' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('花非花', '白居易', '唐代', '花非花，雾非雾。\n夜半来，天明去。\n来如春梦几多时？\n去似朝云无觅处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '花非花' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('月夜', '杜甫', '唐代', '今夜鄜州月，闺中只独看。遥怜小儿女，未解忆长安。 \n香雾云鬟湿，清辉玉臂寒。何时倚虚幌，双照泪痕干。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '月夜' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('画堂春·一生一代一双人', '纳兰性德', '清代', '一生一代一双人，争教两处销魂。\n相思相望不相亲，天为谁春。\n浆向蓝桥易乞，药成碧海难奔。\n若容相访饮牛津，相对忘贫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '画堂春·一生一代一双人' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十五夜望月寄杜郎中', '王建', '唐代', '中庭地白树栖鸦，冷露无声湿桂花。\n今夜月明人尽望，不知秋思落谁家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十五夜望月寄杜郎中' AND p.poem_author = '王建';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人·风回小院庭芜绿', '李煜', '五代', '风回小院庭芜绿，柳眼春相续。凭阑半日独无言，依旧竹声新月似当年。\n笙歌未散尊罍在，池面冰初解。烛明香暗画堂深，满鬓青霜残雪思难任。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人·风回小院庭芜绿' AND p.poem_author = '李煜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卷耳', '佚名', '先秦', '采采卷耳，不盈顷筐。嗟我怀人，寘彼周行。(寘 通：置)\n陟彼崔嵬，我马虺隤。我姑酌彼金罍，维以不永怀。\n陟彼高冈，我马玄黄。我姑酌彼兕觥，维以不永伤。\n陟彼砠矣，我马瘏矣，我仆痡矣，云何吁矣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卷耳' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出塞二首', '王昌龄', '唐代', '秦时明月汉时关，万里长征人未还。\n但使龙城飞将在，不教胡马度阴山。\n\n骝马新跨白玉鞍，战罢沙场月色寒。\n城头铁鼓声犹振，匣里金刀血未干。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出塞二首' AND p.poem_author = '王昌龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('破阵子·四十年来家国', '李煜', '五代', '四十年来家国，三千里地山河。凤阁龙楼连霄汉，玉树琼枝作烟萝，几曾识干戈？\n一旦归为臣虏，沈腰潘鬓消磨。最是仓皇辞庙日，教坊犹奏别离歌，垂泪对宫娥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '破阵子·四十年来家国' AND p.poem_author = '李煜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临安春雨初霁', '陆游', '宋代', '世味年来薄似纱，谁令骑马客京华。\n小楼一夜听春雨，深巷明朝卖杏花。\n矮纸斜行闲作草，晴窗细乳戏分茶。\n素衣莫起风尘叹，犹及清明可到家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临安春雨初霁' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观猎', '王维', '唐代', '风劲角弓鸣，将军猎渭城。\n草枯鹰眼疾，雪尽马蹄轻。\n忽过新丰市，还归细柳营。\n回看射雕处，千里暮云平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观猎' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('点绛唇·蹴罢秋千', '李清照', '宋代', '蹴罢秋千，起来慵整纤纤手。露浓花瘦，薄汗轻衣透。\n见客入来，袜刬金钗溜。和羞走，倚门回首，却把青梅嗅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '点绛唇·蹴罢秋千' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八月十五日夜湓亭望月', '白居易', '唐代', '昔年八月十五夜，曲江池畔杏园边。\n今年八月十五夜，湓浦沙头水馆前。\n西北望乡何处是，东南见月几回圆。\n昨风一吹无人会，今夜清光似往年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八月十五日夜湓亭望月' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上元夜六首·其一', '崔液', '唐代', '玉漏银壶且莫催，铁关金锁彻明开。\n谁家见月能闲坐？何处闻灯不看来？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上元夜六首·其一' AND p.poem_author = '崔液';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜宿山寺', '李白', '唐代', '危楼高百尺，手可摘星辰。\n不敢高声语，恐惊天上人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜宿山寺' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登楼', '杜甫', '唐代', '花近高楼伤客心，万方多难此登临。\n锦江春色来天地，玉垒浮云变古今。\n北极朝廷终不改，西山寇盗莫相侵。\n可怜后主还祠庙，日暮聊为《梁甫吟》。(梁甫 一作：梁父)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登楼' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南歌子词二首 / 新添声杨柳枝词', '温庭筠', '唐代', '一尺深红胜曲尘，天生旧物不如新。(胜曲尘 一作：蒙曲尘)\n合欢桃核终堪恨，里许元来别有人。\n\n井底点灯深烛伊，共郎长行莫围棋。\n玲珑骰子安红豆，入骨相思知不知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南歌子词二首 / 新添声杨柳枝词' AND p.poem_author = '温庭筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏日田园杂兴·其七', '范成大', '宋代', '昼出耘田夜绩麻，村庄儿女各当家。\n童孙未解供耕织，也傍桑阴学种瓜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '夏日田园杂兴·其七' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('回乡偶书二首', '贺知章', '唐代', '少小离家老大回，乡音无改鬓毛衰。(无改 一作：未改/难改)\n儿童相见不相识，笑问客从何处来。\n\n离别家乡岁月多，近来人事半消磨。\n惟有门前镜湖水，春风不改旧时波。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '回乡偶书二首' AND p.poem_author = '贺知章';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渡汉江' AND p.poem_author = '宋之问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('孟母三迁', '刘向', '两汉', '邹孟轲母，号孟母。其舍近墓。孟子之少时，嬉游为墓间之事。孟母曰：“此非吾所以居处子。”乃去，舍市旁。其嬉游为贾人炫卖之事。孟母又曰：“此非吾所以处吾子也。”复徙居学宫之旁。其嬉游乃设俎豆，揖让进退。孟母曰：“真可以处居子矣。”遂居。及孟子长，学六艺，卒成大儒之名。君子谓孟母善以渐化。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '孟母三迁' AND p.poem_author = '刘向';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送灵澈上人' AND p.poem_author = '刘长卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('揠苗助长', '佚名', '先秦', '宋人有闵其苗之不长而揠之者，芒芒然归，谓其人曰：“今日病矣！予助苗长矣！”其子趋而往视之，苗则槁矣。天下之不助苗长者寡矣。以为无益而舍之者，不耘苗者也；助之长者，揠苗者也，非徒无益，而又害之。(闵 通：悯)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '揠苗助长' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('不第后赋菊', '黄巢', '唐代', '待到秋来九月八，我花开后百花杀。\n冲天香阵透长安，满城尽带黄金甲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '不第后赋菊' AND p.poem_author = '黄巢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('海棠', '苏轼', '宋代', '东风袅袅泛崇光，香雾空蒙月转廊。\n只恐夜深花睡去，故烧高烛照红妆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '海棠' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行行重行行', '佚名', '两汉', '行行重行行，与君生别离。\n相去万余里，各在天一涯。\n道路阻且长，会面安可知？\n胡马依北风，越鸟巢南枝。\n相去日已远，衣带日已缓。\n浮云蔽白日，游子不顾返。\n思君令人老，岁月忽已晚。\n弃捐勿复道，努力加餐饭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行行重行行' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('走马川行奉送出师西征 / 走马川行奉送封大夫出师西征', '岑参', '唐代', '君不见走马川行雪海边，平沙莽莽黄入天。 \n轮台九月风夜吼，一川碎石大如斗，随风满地石乱走。 \n匈奴草黄马正肥，金山西见烟尘飞，汉家大将西出师。 \n将军金甲夜不脱，半夜军行戈相拨，风头如刀面如割。 \n马毛带雪汗气蒸，五花连钱旋作冰，幕中草檄砚水凝。 \n虏骑闻之应胆慑，料知短兵不敢接，车师西门伫献捷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '走马川行奉送出师西征 / 走马川行奉送封大夫出师西征' AND p.poem_author = '岑参';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小重山·昨夜寒蛩不住鸣', '岳飞', '宋代', '昨夜寒蛩不住鸣。惊回千里梦，已三更。起来独自绕阶行。人悄悄，帘外月胧明。\n白首为功名。旧山松竹老，阻归程。欲将心事付瑶琴。知音少，弦断有谁听。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小重山·昨夜寒蛩不住鸣' AND p.poem_author = '岳飞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游褒禅山记', '王安石', '宋代', '褒禅山亦谓之华山，唐浮图慧褒始舍于其址，而卒葬之；以故其后名之曰“褒禅”。今所谓慧空禅院者，褒之庐冢也。距其院东五里，所谓华山洞者，以其乃华山之阳名之也。距洞百余步，有碑仆道，其文漫灭，独其为文犹可识曰“花山”。今言“华”如“华实”之“华”者，盖音谬也。\n\n　　其下平旷，有泉侧出，而记游者甚众，所谓前洞也。由山以上五六里，有穴窈然，入之甚寒，问其深，则其好游者不能穷也，谓之后洞。余与四人拥火以入，入之愈深，其进愈难，而其见愈奇。有怠而欲出者，曰：“不出，火且尽。”遂与之俱出。盖余所至，比好游者尚不能十一，然视其左右，来而记之者已少。盖其又深，则其至又加少矣。方是时，余之力尚足以入，火尚足以明也。既其出，则或咎其欲出者，而余亦悔其随之，而不得极夫游之乐也。\n\n　　于是余有叹焉。古人之观于天地、山川、草木、虫鱼、鸟兽，往往有得，以其求思之深而无不在也。夫夷以近，则游者众；险以远，则至者少。而世之奇伟、瑰怪，非常之观，常在于险远，而人之所罕至焉，故非有志者不能至也。有志矣，不随以止也，然力不足者，亦不能至也。有志与力，而又不随以怠，至于幽暗昏惑而无物以相之，亦不能至也。然力足以至焉，于人为可讥，而在己为有悔；尽吾志也而不能至者，可以无悔矣，其孰能讥之乎？此余之所得也！\n\n　　余于仆碑，又以悲夫古书之不存，后世之谬其传而莫能名者，何可胜道也哉！此所以学者不可以不深思而慎取之也。\n\n　　四人者：庐陵萧君圭君玉，长乐王回深父，余弟安国平父、安上纯父。\n\n　　至和元年七月某日，临川王某记。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '游褒禅山记' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早寒江上有怀 / 早寒有怀', '孟浩然', '唐代', '木落雁南度，北风江上寒。\n我家襄水曲，遥隔楚云端。\n乡泪客中尽，孤帆天际看。(孤帆 一作：归帆)\n迷津欲有问，平海夕漫漫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早寒江上有怀 / 早寒有怀' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('正月十五夜灯', '张祜', '唐代', '千门开锁万灯明，正月中旬动地京。\n三百内人连袖舞，一时天上著词声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '正月十五夜灯' AND p.poem_author = '张祜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠卫八处士', '杜甫', '唐代', '人生不相见，动如参与商。\n今夕复何夕，共此灯烛光。\n少壮能几时，鬓发各已苍。\n访旧半为鬼，惊呼热中肠。\n焉知二十载，重上君子堂。\n昔别君未婚，儿女忽成行。\n怡然敬父执，问我来何方。\n问答未及已，儿女罗酒浆。\n夜雨剪春韭，新炊间黄粱。\n主称会面难，一举累十觞。\n十觞亦不醉，感子故意长。\n明日隔山岳，世事两茫茫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠卫八处士' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卖油翁', '欧阳修', '宋代', '陈康肃公善射，当世无双 ，公亦以此自矜。尝射于家圃，有卖油翁释担而立，睨之，久而不去。见其发矢十中八九，但微颔之。\n\n　　康肃问曰：“汝亦知射乎？吾射不亦精乎？”翁曰：“无他， 但手熟尔。”康肃忿然曰：“尔安敢轻吾射！”翁曰：“以我酌油知之。”乃取一葫芦置于地，以钱覆其口，徐以杓酌油沥之，自钱孔入，而钱不湿。因曰：“我亦无他，惟手熟尔。”康肃笑而遣之。\n\n　　此与庄生所谓解牛斫轮者何异？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卖油翁' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('伯牙绝弦', '佚名', '未知', '伯牙善鼓琴，钟子期善听。伯牙鼓琴，志在高山，钟子期曰：“善哉，峨峨兮若泰山！”志在流水，钟子期曰：“善哉，洋洋兮若江河！”伯牙所念，钟子期必得之。子期死，伯牙谓世再无知音，乃破琴绝弦，终身不复鼓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '伯牙绝弦' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('静女', '佚名', '先秦', '静女其姝，俟我于城隅。爱而不见，搔首踟蹰。\n静女其娈，贻我彤管。彤管有炜，说怿女美。\n自牧归荑，洵美且异。匪女之为美，美人之贻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '静女' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山坡羊·骊山怀古', '张养浩', '元代', '骊山四顾，阿房一炬，当时奢侈今何处？只见草萧疏，水萦纡。至今遗恨迷烟树。列国周齐秦汉楚，赢，都变做了土；输，都变做了土。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山坡羊·骊山怀古' AND p.poem_author = '张养浩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·泪湿罗衣脂粉满', '李清照', '宋代', '泪湿罗衣脂粉满，四叠阳关，唱到千千遍。人道山长水又断，萧萧微雨闻孤馆。\n惜别伤离方寸乱，忘了临行，酒盏深和浅。好把音书凭过雁，东莱不似蓬莱远。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·泪湿罗衣脂粉满' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早梅', '张谓', '唐代', '一树寒梅白玉条，迥临村路傍溪桥。(村路 一作：林村)\n不知近水花先发，疑是经冬雪未销。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早梅' AND p.poem_author = '张谓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浪淘沙·把酒祝东风', '欧阳修', '宋代', '把酒祝东风，且共从容。垂杨紫陌洛城东。总是当时携手处，游遍芳丛。\n聚散苦匆匆，此恨无穷。今年花胜去年红。可惜明年花更好，知与谁同？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浪淘沙·把酒祝东风' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉楼春·尊前拟把归期说', '欧阳修', '宋代', '尊前拟把归期说，欲语春容先惨咽。人生自是有情痴，此恨不关风与月。\n离歌且莫翻新阕，一曲能教肠寸结。直须看尽洛城花，始共春风容易别。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉楼春·尊前拟把归期说' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蜀中九日 / 九日登高', '王勃', '唐代', '九月九日望乡台，他席他乡送客杯。 \n人情已厌南中苦，鸿雁那从北地来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蜀中九日 / 九日登高' AND p.poem_author = '王勃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山园小梅二首', '林逋', '宋代', '众芳摇落独暄妍，占尽风情向小园。\n疏影横斜水清浅，暗香浮动月黄昏。\n霜禽欲下先偷眼，粉蝶如知合断魂。\n幸有微吟可相狎，不须檀板共金樽。\n\n剪绡零碎点酥乾，向背稀稠画亦难。\n日薄从甘春至晚，霜深应怯夜来寒。\n澄鲜只共邻僧惜，冷落犹嫌俗客看。\n忆着江南旧行路，酒旗斜拂堕吟鞍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山园小梅二首' AND p.poem_author = '林逋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山市', '蒲松龄', '清代', '奂山山市，邑八景之一也，然数年恒不一见。孙公子禹年与同人饮楼上，忽见山头有孤塔耸起，高插青冥，相顾惊疑，念近中无此禅院。无何，见宫殿数十所，碧瓦飞甍，始悟为山市。未几，高垣睥睨，连亘六七里，居然城郭矣。中有楼若者，堂若者，坊若者，历历在目，以亿万计。忽大风起，尘气莽莽然，城市依稀而已。既而风定天清，一切乌有，惟危楼一座，直接霄汉。楼五架，窗扉皆洞开；一行有五点明处，楼外天也。\n\n　　层层指数，楼愈高，则明渐少。数至八层，裁如星点。又其上，则黯然缥缈，不可计其层次矣。而楼上人往来屑屑，或凭或立，不一状。逾时，楼渐低，可见其顶；又渐如常楼；又渐如高舍；倏忽如拳如豆，遂不可见。\n\n　　又闻有早行者，见山上人烟市肆，与世无别，故又名“鬼市”云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山市' AND p.poem_author = '蒲松龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·送人', '辛弃疾', '宋代', '唱彻《阳关》泪未干，功名馀事且加餐。浮天水送无穷树，带雨云埋一半山。\n今古恨，几千般，只应离合是悲欢？江头未是风波恶，别有人间行路难！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·送人' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·送钱穆父', '苏轼', '宋代', '一别都门三改火，天涯踏尽红尘。依然一笑作春温。无波真古井，有节是秋筠。\n惆怅孤帆连夜发，送行淡月微云。尊前不用翠眉颦。人生如逆旅，我亦是行人。(尊 通：樽)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·送钱穆父' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('屈原塔', '苏轼', '宋代', '楚人悲屈原，千载意未歇。\n精魂飘何处，父老空哽咽。\n至今沧江上，投饭救饥渴。\n遗风成竞渡，哀叫楚山裂。\n屈原古壮士，就死意甚烈。\n世俗安得知，眷眷不忍决。\n南宾旧属楚，山上有遗塔。\n应是奉佛人，恐子就沦灭。\n此事虽无凭，此意固已切。\n古人谁不死，何必较考折。\n名声实无穷，富贵亦暂热。\n大夫知此理，所以持死节。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '屈原塔' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行路难三首', '李白', '唐代', '金樽清酒斗十千，玉盘珍羞直万钱。\n停杯投箸不能食，拔剑四顾心茫然。\n欲渡黄河冰塞川，将登太行雪满山。\n闲来垂钓碧溪上，忽复乘舟梦日边。\n行路难！行路难！多歧路，今安在？\n长风破浪会有时，直挂云帆济沧海。\n\n大道如青天，我独不得出。 \n羞逐长安社中儿，赤鸡白雉赌梨栗。\n弹剑作歌奏苦声，曳裾王门不称情。\n淮阴市井笑韩信，汉朝公卿忌贾生。\n君不见昔时燕家重郭隗，拥篲折节无嫌猜。\n剧辛乐毅感恩分，输肝剖胆效英才。\n昭王白骨萦蔓草，谁人更扫黄金台？\n行路难，归去来！\n\n有耳莫洗颍川水，有口莫食首阳蕨。\n含光混世贵无名，何用孤高比云月？\n吾观自古贤达人，功成不退皆殒身。\n子胥既弃吴江上，屈原终投湘水滨。\n陆机雄才岂自保？李斯税驾苦不早。\n华亭鹤唳讵可闻？上蔡苍鹰何足道？\n君不见吴中张翰称达生，秋风忽忆江东行。\n且乐生前一杯酒，何须身后千载名？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行路难三首' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮·人人尽说江南好', '韦庄', '唐代', '人人尽说江南好，游人只合江南老。春水碧于天，画船听雨眠。\n垆边人似月，皓腕凝霜雪。未老莫还乡，还乡须断肠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮·人人尽说江南好' AND p.poem_author = '韦庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观书', '于谦', '明代', '书卷多情似故人，晨昏忧乐每相亲。\n眼前直下三千字，胸次全无一点尘。\n活水源流随处满，东风花柳逐时新。\n金鞍玉勒寻芳客，未信我庐别有春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观书' AND p.poem_author = '于谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹤冲天·黄金榜上', '柳永', '宋代', '黄金榜上，偶失龙头望。明代暂遗贤，如何向。未遂风云便，争不恣狂荡。何须论得丧？才子词人，自是白衣卿相。\n烟花巷陌，依约丹青屏障。幸有意中人，堪寻访。且恁偎红倚翠，风流事，平生畅。青春都一饷。忍把浮名，换了浅斟低唱！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹤冲天·黄金榜上' AND p.poem_author = '柳永';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春夜宴桃李园序 / 春夜宴从弟桃花园序', '李白', '唐代', '夫天地者，万物之逆旅也；光阴者，百代之过客也。而浮生若梦，为欢几何？古人秉烛夜游，良有以也。况阳春召我以烟景，大块假我以文章。会桃花之芳园，序天伦之乐事。群季俊秀，皆为惠连；吾人咏歌，独惭康乐。幽赏未已，高谈转清。开琼筵以坐花，飞羽觞而醉月。不有佳咏，何伸雅怀？如诗不成，罚依金谷酒数。(桃花 一作：桃李)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春夜宴桃李园序 / 春夜宴从弟桃花园序' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄扬州韩绰判官' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日偶成', '程颢', '宋代', '云淡风轻近午天，傍花随柳过前川。\n时人不识余心乐，将谓偷闲学少年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日偶成' AND p.poem_author = '程颢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秦风·无衣', '佚名', '先秦', '岂曰无衣？与子同袍。王于兴师，修我戈矛。与子同仇！\n岂曰无衣？与子同泽。王于兴师，修我矛戟。与子偕作！\n岂曰无衣？与子同裳。王于兴师，修我甲兵。与子偕行！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秦风·无衣' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩提偈', '惠能', '唐代', '菩提本无树，明镜亦非台。\n佛性常清净，何处有尘埃！\n\n心是菩提树，身为明镜台。\n明镜本清净，何处染尘埃！\n\n菩提本无树，明镜亦非台。\n本来无一物，何处惹尘埃！\n\n菩提只向心觅，何劳向外求玄？\n听说依此修行，西方只在目前！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩提偈' AND p.poem_author = '惠能';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('除夜太原寒甚', '于谦', '明代', '寄语天涯客，轻寒底用愁。\n春风来不远，只在屋东头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '除夜太原寒甚' AND p.poem_author = '于谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一剪梅·舟过吴江', '蒋捷', '宋代', '一片春愁待酒浇。江上舟摇，楼上帘招。秋娘渡与泰娘桥，风又飘飘，雨又萧萧。（渡 一作：度。桥 一作：娇）\n何日归家洗客袍？银字笙调，心字香烧。流光容易把人抛，红了樱桃，绿了芭蕉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '一剪梅·舟过吴江' AND p.poem_author = '蒋捷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋风辞', '刘彻', '两汉', '秋风起兮白云飞，草木黄落兮雁南归。\n兰有秀兮菊有芳，怀佳人兮不能忘。\n泛楼船兮济汾河，横中流兮扬素波。\n箫鼓鸣兮发棹歌，欢乐极兮哀情多。\n少壮几时兮奈老何！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋风辞' AND p.poem_author = '刘彻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆江南三首', '白居易', '唐代', '江南好，风景旧曾谙；日出江花红胜火，春来江水绿如蓝。能不忆江南？\n\n江南忆，最忆是杭州；山寺月中寻桂子，郡亭枕上看潮头。何日更重游！\n\n江南忆，其次忆吴宫；吴酒一杯春竹叶，吴娃双舞醉芙蓉。早晚复相逢！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆江南三首' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('木瓜', '佚名', '先秦', '投我以木瓜，报之以琼琚。匪报也，永以为好也！\n投我以木桃，报之以琼瑶。匪报也，永以为好也！\n投我以木李，报之以琼玖。匪报也，永以为好也！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '木瓜' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·桂花', '李清照', '宋代', '暗淡轻黄体性柔，情疏迹远只香留。何须浅碧深红色，自是花中第一流。(\n\'深\'红 一作：轻)\n梅定妒，菊应羞，画阑开处冠中秋。骚人可煞无情思，何事当年不见收。(阑 通：栏)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·桂花' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·彩袖殷勤捧玉钟', '晏几道', '宋代', '彩袖殷勤捧玉钟，当年拚却醉颜红。舞低杨柳楼心月，歌尽桃花扇底风。\n从别后，忆相逢，几回魂梦与君同。今宵剩把银釭照，犹恐相逢是梦中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·彩袖殷勤捧玉钟' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夸父逐日', '佚名', '先秦', '夸父与日逐走，入日；渴，欲得饮，饮于河、渭；河、渭不足，北饮大泽。未至，道渴而死。弃其杖，化为邓林。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夸父逐日' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和张仆射塞下曲·其三', '卢纶', '唐代', '月黑雁飞高，单于夜遁逃。\n欲将轻骑逐，大雪满弓刀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和张仆射塞下曲·其三' AND p.poem_author = '卢纶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('正月十五夜', '苏味道', '唐代', '火树银花合，星桥铁锁开。\n暗尘随马去，明月逐人来。\n游伎皆秾李，行歌尽落梅。\n金吾不禁夜，玉漏莫相催。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '正月十五夜' AND p.poem_author = '苏味道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('端午即事', '文天祥', '宋代', '五月五日午，赠我一枝艾。 故人不可见，新知万里外。\n丹心照夙昔，鬓发日已改。 我欲从灵均，三湘隔辽海。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '端午即事' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋浦歌十七首·其十四', '李白', '唐代', '炉火照天地，红星乱紫烟。\n赧郎明月夜，歌曲动寒川。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋浦歌十七首·其十四' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('马诗二十三首·其五', '李贺', '唐代', '大漠沙如雪，燕山月似钩。\n何当金络脑，快走踏清秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '马诗二十三首·其五' AND p.poem_author = '李贺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送别', '王之涣', '唐代', '杨柳东风树，青青夹御河。\n近来攀折苦，应为别离多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送别' AND p.poem_author = '王之涣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉楼春·春景', '宋祁', '宋代', '东城渐觉风光好。縠皱波纹迎客棹。绿杨烟外晓寒轻，红杏枝头春意闹。\n浮生长恨欢娱少。肯爱千金轻一笑。为君持酒劝斜阳，且向花间留晚照。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉楼春·春景' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('从军行七首', '王昌龄', '唐代', '烽火城西百尺楼，黄昏独上海风秋。(独上 一作：独坐)\n更吹羌笛关山月，无那金闺万里愁。\n\n琵琶起舞换新声，总是关山旧别情。\n撩乱边愁听不尽，高高秋月照长城。\n\n关城榆叶早疏黄，日暮云沙古战场。\n表请回军掩尘骨，莫教兵士哭龙荒。\n\n青海长云暗雪山，孤城遥望玉门关。\n黄沙百战穿金甲，不破楼兰终不还。\n\n大漠风尘日色昏，红旗半卷出辕门。\n前军夜战洮河北，已报生擒吐谷浑。\n\n胡瓶落膊紫薄汗，碎叶城西秋月团。\n明敕星驰封宝剑，辞君一夜取楼兰。\n\n玉门山嶂几千重，山北山南总是烽。\n人依远戍须看火，马踏深山不见踪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '从军行七首' AND p.poem_author = '王昌龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鸿门宴', '司马迁', '两汉', '沛公军霸上，未得与项羽相见。沛公左司马曹无伤使人言于项羽曰：“沛公欲王关中，使子婴为相，珍宝尽有之。”项羽大怒曰：“旦日飨士卒，为击破沛公军！”当是时，项羽兵四十万，在新丰鸿门；沛公兵十万，在霸上。范增说项羽曰：“沛公居山东时，贪于财货，好美姬。今入关，财物无所取，妇女无所幸，此其志不在小。吾令人望其气，皆为龙虎，成五彩，此天子气也。急击勿失！”\n\n　　楚左尹项伯者，项羽季父也，素善留侯张良。张良是时从沛公，项伯乃夜驰之沛公军，私见张良，具告以事，欲呼张良与俱去，曰：“毋从俱死也。”张良曰：“臣为韩王送沛公，沛公今事有急，亡去不义，不可不语。”\n\n　　良乃入，具告沛公。沛公大惊，曰：“为之奈何？”张良曰：“谁为大王为此计者？”曰：“鲰生说我曰：‘距关，毋内诸侯，秦地可尽王也。’故听之。”良曰：“料大王士卒足以当项王乎？”沛公默然，曰：“固不如也。且为之奈何？”张良曰：“请往谓项伯，言沛公不敢背项王也。”沛公曰：“君安与项伯有故？”张良曰：“秦时与臣游，项伯杀人，臣活之；今事有急，故幸来告良。”沛公曰：“孰与君少长？”良曰：“长于臣。”沛公曰：“君为我呼入，吾得兄事之。”张良出，要项伯。项伯即入见沛公。沛公奉卮酒为寿，约为婚姻，曰：“吾入关，秋毫不敢有所近，籍吏民封府库，而待将军。所以遣将守关者，备他盗之出入与非常也。日夜望将军至，岂敢反乎！愿伯具言臣之不敢倍德也。”项伯许诺，谓沛公曰：“旦日不可不蚤自来谢项王。”沛公曰：“诺。”于是项伯复夜去，至军中，具以沛公言报项王，因言曰：“沛公不先破关中，公岂敢入乎？今人有大功而击之，不义也。不如因善遇之。”项王许诺。\n\n　　沛公旦日从百余骑来见项王，至鸿门，谢曰：“臣与将军戮力而攻秦，将军战河北，臣战河南，然不自意能先入关破秦，得復见将军于此。今者有小人之言，令将军与臣有郤……”项王曰：“此沛公左司马曹无伤言之；不然，籍何以至此。”项王即日因留沛公与饮。项王、项伯东向坐，亚父南向坐。亚父者，范增也。沛公北向坐，张良西向侍。范增数目项王，举所佩玉玦以示之者三，项王默然不应。范增起，出召项庄，谓曰：“君王为人不忍。若入前为寿，寿毕，请以剑舞，因击沛公于坐，杀之。不者，若属皆且为所虏。”庄则入为寿。寿毕，曰：“君王与沛公饮，军中无以为乐，请以剑舞。”项王曰：“诺。”项庄拔剑起舞，项伯亦拔剑起舞，常以身翼蔽沛公，庄不得击。\n\n　　于是张良至军门见樊哙。樊哙曰：“今日之事何如？”良曰：“甚急！今者项庄拔剑舞，其意常在沛公也。”哙曰：“此迫矣！臣请入，与之同命。”哙即带剑拥盾入军门。交戟之卫士欲止不内，樊哙侧其盾以撞，卫士仆地，哙遂入，披帷西向立，瞋目视项王，头发上指，目眦尽裂。项王按剑而跽曰：“客何为者？”张良曰：“沛公之参乘樊哙者也。”项王曰：“壮士，赐之卮酒。”则与斗卮酒。哙拜谢，起，立而饮之。项王曰：“赐之彘肩。”则与一生彘肩。樊哙覆其盾于地，加彘肩上，拔剑切而啖之。项王曰：“壮士！能復饮乎？”樊哙曰：“臣死且不避，卮酒安足辞！夫秦王有虎狼之心，杀人如不能举，刑人如恐不胜，天下皆叛之。怀王与诸将约曰：‘先破秦入咸阳者王之。’今沛公先破秦入咸阳，毫毛不敢有所近，封闭宫室，还军霸上，以待大王来。故遣将守关者，备他盗出入与非常也。劳苦而功高如此，未有封侯之赏，而听细说，欲诛有功之人。此亡秦之续耳，窃为大王不取也！”项王未有以应，曰：“坐。”樊哙从良坐。\n\n　　坐须臾，沛公起如厕，因招樊哙出。沛公已出，项王使都尉陈平召沛公。沛公曰：“今者出，未辞也，为之奈何？”樊哙曰：“大行不顾细谨，大礼不辞小让。如今人方为刀俎，我为鱼肉，何辞为？”于是遂去。乃令张良留谢。良问曰：“大王来何操？”曰：“我持白璧一双，欲献项王，玉斗一双，欲与亚父。会其怒，不敢献。公为我献之。”张良曰：“谨诺。”当是时，项王军在鸿门下，沛公军在霸上，相去四十里。沛公则置车骑，脱身独骑，与樊哙、夏侯婴、靳强、纪信等四人持剑盾步走，从郦山下，道芷阳间行。沛公谓张良曰：“从此道至吾军，不过二十里耳。度我至军中，公乃入。”\n\n　　沛公已去，间至军中。张良入谢，曰：“沛公不胜桮杓，不能辞。谨使臣良奉白璧一双，再拜献大王足下，玉斗一双，再拜奉大将军足下。”项王曰：“沛公安在？”良曰：“闻大王有意督过之，脱身独去，已至军矣。”项王则受璧，置之坐上。亚父受玉斗，置之地，拔剑撞而破之，曰：“唉！竖子不足与谋。夺项王天下者，必沛公也。吾属今为之虏矣！”\n\n　　沛公至军，立诛杀曹无伤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '鸿门宴' AND p.poem_author = '司马迁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一毛不拔', '邯郸淳', '魏晋', '一猴死，见冥王，求转人身。王曰：“既欲做人，须将毛尽拔去。”即唤夜叉拔之。方拔一根，猴不胜痛叫。王笑曰：“看你一毛不拔，如何做人？”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '一毛不拔' AND p.poem_author = '邯郸淳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黔之驴', '柳宗元', '唐代', '黔无驴，有好事者船载以入。至则无可用，放之山下。虎见之，庞然大物也，以为神，蔽林间窥之。稍出近之，慭慭然，莫相知。\n\n　　他日，驴一鸣，虎大骇，远遁；以为且噬己也，甚恐。然往来视之，觉无异能者；益习其声，又近出前后，终不敢搏。稍近，益狎，荡倚冲冒。驴不胜怒，蹄之。虎因喜，计之曰：“技止此耳！”因跳踉大?，断其喉，尽其肉，乃去。\n\n　　噫！形之庞也类有德，声之宏也类有能。向不出其技，虎虽猛，疑畏，卒不敢取。今若是焉，悲夫！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黔之驴' AND p.poem_author = '柳宗元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苏幕遮·燎沉香', '周邦彦', '宋代', '燎沉香，消溽暑。鸟雀呼晴，侵晓窥檐语。叶上初阳干宿雨、水面清圆，一一风荷举。\n故乡遥，何日去。家住吴门，久作长安旅。五月渔郎相忆否。小楫轻舟，梦入芙蓉浦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '苏幕遮·燎沉香' AND p.poem_author = '周邦彦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('愚人食盐', '僧伽斯那', '南北朝', '昔有愚人，至于他家。主人与食，嫌淡无味。主人闻已，更为益盐。既得盐美，便自念言：“所以美者，缘有盐故。少有尚尔，况复多也？”愚人无智，便空食盐。食已口爽，反为其患。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '愚人食盐' AND p.poem_author = '僧伽斯那';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('兵车行', '杜甫', '唐代', '车辚辚，马萧萧，行人弓箭各在腰。\n耶娘妻子走相送，尘埃不见咸阳桥。(\n\'耶\'娘 一作：“爷”)\n牵衣顿足拦道哭，哭声直上干云霄。\n道旁过者问行人，行人但云点行频。\n或从十五北防河，便至四十西营田。\n去时里正与裹头，归来头白还戍边。\n边庭流血成海水，武皇开边意未已。\n君不闻汉家山东二百州，千村万落生荆杞。\n纵有健妇把锄犁，禾生陇亩无东西。\n况复秦兵耐苦战，被驱不异犬与鸡。\n长者虽有问，役夫敢申恨？\n且如今年冬，未休关西卒。\n县官急索租，租税从何出？\n信知生男恶，反是生女好。\n生女犹得嫁比邻，生男埋没随百草。\n君不见，青海头，古来白骨无人收。\n新鬼烦冤旧鬼哭，天阴雨湿声啾啾！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '兵车行' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('后赤壁赋', '苏轼', '宋代', '是岁十月之望，步自雪堂，将归于临皋。二客从予过黄泥之坂。霜露既降，木叶尽脱， 人影在地，仰见明月，顾而乐之，行歌相答。已而叹曰：“有客无酒，有酒无肴，月白风 清，如此良夜何！”客曰：“今者薄暮，举网得鱼，巨口细鳞，状如松江之鲈。顾安所得酒 乎？”归而谋诸妇。妇曰：“我有斗酒，藏之久矣，以待子不时之需。”于是携酒与鱼，复 游于赤壁之下。江流有声，断岸千尺；山高月小，水落石出。曾日月之几何，而江山不可复 识矣。予乃摄衣而上，履巉岩，披蒙茸，踞虎豹，登虬龙，攀栖鹘之危巢，俯冯夷之幽 宫。盖二客不能从焉。划然长啸，草木震动，山鸣谷应，风起水涌。予亦悄然而悲，肃然而 恐，凛乎其不可留也。反而登舟，放乎中流，听其所止而休焉。时夜将半，四顾寂寥。适有 孤鹤，横江东来。翅如车轮，玄裳缟衣，戛然长鸣，掠予舟而西也。\n\n　　须臾客去，予亦就睡。梦一道士，羽衣蹁跹，过临皋之下，揖予而言曰：“赤壁之游乐 乎？”问其姓名，俯而不答。“呜呼！噫嘻！我知之矣。畴昔之夜，飞鸣而过我者，非子也 邪？”道士顾笑，予亦惊寤。开户视之，不见其处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '后赤壁赋' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长相思·汴水流', '白居易', '唐代', '汴水流，泗水流，流到瓜州古渡头。吴山点点愁。\n思悠悠，恨悠悠，恨到归时方始休。月明人倚楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长相思·汴水流' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·春暮', '李煜', '五代', '遥夜亭皋闲信步。才过清明，渐觉伤春暮。数点雨声风约住。朦胧淡月云来去。\n桃杏依稀香暗渡。谁在秋千，笑里轻轻语。一寸相思千万绪。人间没个安排处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·春暮' AND p.poem_author = '李煜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清明夜', '白居易', '唐代', '好风胧月清明夜，碧砌红轩刺史家。 \n独绕回廊行复歇，遥听弦管暗看花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清明夜' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贾生' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠荷花', '李商隐', '唐代', '世间花叶不相伦，花入金盆叶作尘。\n惟有绿荷红菡萏，卷舒开合任天真。\n此花此叶常相映，翠减红衰愁杀人。(常相映 一作：长相映)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠荷花' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别云间', '夏完淳', '明代', '三年羁旅客，今日又南冠。\n无限山河泪，谁言天地宽！(山河 一作：河山)\n已知泉路近，欲别故乡难。\n毅魄归来日，灵旗空际看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别云间' AND p.poem_author = '夏完淳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凉州词二首', '王翰', '唐代', '葡萄美酒夜光杯，欲饮琵琶马上催。\n醉卧沙场君莫笑，古来征战几人回?\n\n秦中花鸟已应阑，塞外风沙犹自寒。\n夜听胡笳折杨柳，教人意气忆长安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凉州词二首' AND p.poem_author = '王翰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登科后', '孟郊', '唐代', '昔日龌龊不足夸，今朝放荡思无涯。 \n春风得意马蹄疾，一日看尽长安花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登科后' AND p.poem_author = '孟郊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗', '陶渊明', '魏晋', '人生无根蒂，飘如陌上尘。\n分散逐风转，此已非常身。\n落地为兄弟，何必骨肉亲！\n得欢当作乐，斗酒聚比邻。\n盛年不重来，一日难再晨。\n及时当勉励，岁月不待人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗' AND p.poem_author = '陶渊明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春思', '李白', '唐代', '燕草如碧丝，秦桑低绿枝。\n当君怀归日，是妾断肠时。 \n春风不相识，何事入罗帏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春思' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庄子与惠子游于濠梁', '佚名', '先秦', '庄子与惠子游于濠梁之上。庄子曰：“鯈鱼出游从容，是鱼之乐也。”惠子曰：“子非鱼，安知鱼之乐？”庄子曰：“子非我，安知我不知鱼之乐？”惠子曰：“我非子，固不知子矣；子固非鱼也，子之不知鱼之乐全矣！”庄子曰：“请循其本。子曰‘汝安知鱼乐’云者，既已知吾知之而问我。我知之濠上也。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庄子与惠子游于濠梁' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜上受降城闻笛' AND p.poem_author = '李益';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别老母', '黄景仁', '清代', '搴帷拜母河梁去，白发愁看泪眼枯。\n惨惨柴门风雪夜，此时有子不如无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别老母' AND p.poem_author = '黄景仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塞下曲六首·其一', '李白', '唐代', '五月天山雪，无花只有寒。\n笛中闻折柳，春色未曾看。\n晓战随金鼓，宵眠抱玉鞍。\n愿将腰下剑，直为斩楼兰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塞下曲六首·其一' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·寒柳', '纳兰性德', '清代', '飞絮飞花何处是，层冰积雪摧残，疏疏一树五更寒。爱他明月好，憔悴也相关。\n最是繁丝摇落后，转教人忆春山。湔裙梦断续应难。西风多少恨，吹不散眉弯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·寒柳' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('牧童', '吕岩', '唐代', '草铺横野六七里，笛弄晚风三四声。\n归来饱饭黄昏后，不脱蓑衣卧月明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '牧童' AND p.poem_author = '吕岩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春宵', '苏轼', '宋代', '春宵一刻值千金，花有清香月有阴。\n歌管楼台声细细，秋千院落夜沉沉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春宵' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋词二首', '刘禹锡', '唐代', '自古逢秋悲寂寥，我言秋日胜春朝。\n晴空一鹤排云上，便引诗情到碧霄。\n\n山明水净夜来霜，数树深红出浅黄。\n试上高楼清入骨，岂如春色嗾人狂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋词二首' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和端午', '张耒', '宋代', '竞渡深悲千载冤，忠魂一去讵能还。\n国亡身殒今何有，只留离骚在世间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和端午' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('刻舟求剑 / 楚人涉江', '佚名', '先秦', '楚人有涉江者，其剑自舟中坠于水。遽契其舟，曰：“是吾剑之所从坠。”舟止，从其所契者入水求之。舟已行矣，而剑不行，求剑若此，不亦惑乎！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '刻舟求剑 / 楚人涉江' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨过山村', '王建', '唐代', '雨里鸡鸣一两家，竹溪村路板桥斜。\n妇姑相唤浴蚕去，闲看中庭栀子花。(闲看 一作：闲着)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨过山村' AND p.poem_author = '王建';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十五夜观灯', '卢照邻', '唐代', '锦里开芳宴，兰缸艳早年。\n缛彩遥分地，繁光远缀天。 \n接汉疑星落，依楼似月悬。\n别有千金笑，来映九枝前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十五夜观灯' AND p.poem_author = '卢照邻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮·平林漠漠烟如织', '李白', '唐代', '平林漠漠烟如织，寒山一带伤心碧。暝色入高楼，有人楼上愁。\n玉阶空伫立，宿鸟归飞急。何处是归程？长亭连短亭。(连短亭 一作：更短亭)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮·平林漠漠烟如织' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚春二首·其一', '韩愈', '唐代', '草树知春不久归，百般红紫斗芳菲。(草树 一作：草木)\n杨花榆荚无才思，惟解漫天作雪飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚春二首·其一' AND p.poem_author = '韩愈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('河中石兽', '纪昀', '清代', '沧州南一寺临河干，山门圮于河，二石兽并沉焉。阅十余岁，僧募金重修，求石兽于水中，竟不可得。以为顺流下矣，棹数小舟，曳铁钯，寻十余里无迹。\n\n　　一讲学家设帐寺中，闻之笑曰：“尔辈不能究物理，是非木杮，岂能为暴涨携之去？乃石性坚重，沙性松浮，湮于沙上，渐沉渐深耳。沿河求之，不亦颠乎？”众服为确论。\n\n　　一老河兵闻之，又笑曰：“凡河中失石，当求之于上流。盖石性坚重，沙性松浮，水不能冲石，其反激之力，必于石下迎水处啮沙为坎穴，渐激渐深，至石之半，石必倒掷坎穴中。如是再啮，石又再转。转转不已，遂反溯流逆上矣。求之下流，固颠；求之地中，不更颠乎？”如其言，果得于数里外。然则天下之事，但知其一，不知其二者多矣，可据理臆断欤？(转转 一作：再转)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '河中石兽' AND p.poem_author = '纪昀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪梅·其二', '卢梅坡', '宋代', '有梅无雪不精神，有雪无诗俗了人。\n日暮诗成天又雪，与梅并作十分春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪梅·其二' AND p.poem_author = '卢梅坡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九日齐山登高 / 九日齐安登高', '杜牧', '唐代', '江涵秋影雁初飞，与客携壶上翠微。\n尘世难逢开口笑，菊花须插满头归。\n但将酩酊酬佳节，不用登临恨落晖。\n古往今来只如此，牛山何必独霑衣。(霑 同：沾)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九日齐山登高 / 九日齐安登高' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南陵别儿童入京', '李白', '唐代', '白酒新熟山中归，黄鸡啄黍秋正肥。\n呼童烹鸡酌白酒，儿女嬉笑牵人衣。\n高歌取醉欲自慰，起舞落日争光辉。\n游说万乘苦不早，著鞭跨马涉远道。\n会稽愚妇轻买臣，余亦辞家西入秦。\n仰天大笑出门去，我辈岂是蓬蒿人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南陵别儿童入京' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦李白二首·其二', '杜甫', '唐代', '浮云终日行，游子久不至。\n三夜频梦君，情亲见君意。\n告归常局促，苦道来不易。\n江湖多风波，舟楫恐失坠。\n出门搔白首，若负平生志。\n冠盖满京华，斯人独憔悴。\n孰云网恢恢，将老身反累。\n千秋万岁名，寂寞身后事。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梦李白二首·其二' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('滕王阁诗', '王勃', '唐代', '滕王高阁临江渚，佩玉鸣鸾罢歌舞。\n画栋朝飞南浦云，珠帘暮卷西山雨。\n闲云潭影日悠悠，物换星移几度秋。\n阁中帝子今何在？槛外长江空自流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '滕王阁诗' AND p.poem_author = '王勃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一剪梅·中秋元月', '辛弃疾', '宋代', '忆对中秋丹桂丛，花也杯中，月也杯中。今宵楼上一尊同，云湿纱窗，雨湿纱窗。(月也杯中 一作：月在杯中)\n浑欲乘风问化工，路也难通，信也难通。满堂唯有烛花红，歌且从容，杯且从容。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '一剪梅·中秋元月' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李凭箜篌引', '李贺', '唐代', '吴丝蜀桐张高秋，空山凝云颓不流。\n江娥啼竹素女愁，李凭中国弹箜篌。\n昆山玉碎凤凰叫，芙蓉泣露香兰笑。\n十二门前融冷光，二十三丝动紫皇。\n女娲炼石补天处，石破天惊逗秋雨。\n梦入神山教神妪，老鱼跳波瘦蛟舞。\n吴质不眠倚桂树，露脚斜飞湿寒兔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李凭箜篌引' AND p.poem_author = '李贺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红·登黄鹤楼有感', '岳飞', '宋代', '遥望中原，荒烟外、许多城郭。想当年、花遮柳护，凤楼龙阁。万岁山前珠翠绕，蓬壶殿里笙歌作。到而今、铁骑满郊畿，风尘恶。\n兵安在？膏锋锷。民安在？填沟壑。叹江山如故，千村寥落。何日请缨提锐旅，一鞭直渡清河洛。却归来、再续汉阳游，骑黄鹤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红·登黄鹤楼有感' AND p.poem_author = '岳飞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠别', '杜牧', '唐代', '多情却似总无情，唯觉樽前笑不成。\n蜡烛有心还惜别，替人垂泪到天明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠别' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙·闺情', '李清照', '宋代', '绣面芙蓉一笑开，斜飞宝鸭衬香腮。眼波才动被人猜。 \n一面风情深有韵，半笺娇恨寄幽怀。月移花影约重来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙·闺情' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('芙蓉楼送辛渐二首', '王昌龄', '唐代', '寒雨连江夜入吴，平明送客楚山孤。(连江 一作：连天)\n洛阳亲友如相问，一片冰心在玉壶。\n\n丹阳城南秋海阴，丹阳城北楚云深。\n高楼送客不能醉，寂寂寒江明月心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '芙蓉楼送辛渐二首' AND p.poem_author = '王昌龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('放言五首·其三', '白居易', '唐代', '赠君一法决狐疑，不用钻龟与祝蓍。\n试玉要烧三日满，辨材须待七年期。\n周公恐惧流言日，王莽谦恭未篡时。\n向使当初身便死，一生真伪复谁知？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '放言五首·其三' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹊踏枝·六曲阑干偎碧树', '冯延巳', '五代', '六曲阑干偎碧树，杨柳风轻，展尽黄金缕。谁把钿筝移玉柱，穿帘海燕双飞去。\n满眼游丝兼落絮，红杏开时，一霎清明雨。浓睡觉来莺乱语，惊残好梦无寻处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹊踏枝·六曲阑干偎碧树' AND p.poem_author = '冯延巳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题乌江亭', '杜牧', '唐代', '胜败兵家事不期，包羞忍耻是男儿。 \n江东子弟多才俊，卷土重来未可知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题乌江亭' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青松', '陈毅', '现代', '大雪压青松，青松挺且直。 \n要知松高洁，待到雪化时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青松' AND p.poem_author = '陈毅';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桃花溪' AND p.poem_author = '张旭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无题二首', '李商隐', '唐代', '昨夜星辰昨夜风，画楼西畔桂堂东。\n身无彩凤双飞翼，心有灵犀一点通。\n隔座送钩春酒暖，分曹射覆蜡灯红。\n嗟余听鼓应官去，走马兰台类转蓬。(转蓬 一作：断蓬)\n\n闻道阊门萼绿华，昔年相望抵天涯。\n岂知一夜秦楼客，偷看吴王苑内花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无题二首' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春夜', '王安石', '宋代', '金炉香烬漏声残，翦翦轻风阵阵寒。\n春色恼人眠不得，月移花影上栏杆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春夜' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('踏莎行·郴州旅舍', '秦观', '宋代', '雾失楼台，月迷津渡。桃源望断无寻处。可堪孤馆闭春寒，杜鹃声里斜阳暮。 \n驿寄梅花，鱼传尺素。砌成此恨无重数。郴江幸自绕郴山，为谁流下潇湘去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '踏莎行·郴州旅舍' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南园十三首·其五', '李贺', '唐代', '男儿何不带吴钩，收取关山五十州。\n请君暂上凌烟阁，若个书生万户侯？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南园十三首·其五' AND p.poem_author = '李贺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酒泉子·长忆观潮', '潘阆', '宋代', '长忆观潮，满郭人争江上望。来疑沧海尽成空。万面鼓声中。 \n弄潮儿向涛头立。手把红旗旗不湿。别来几向梦中看。梦觉尚心寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酒泉子·长忆观潮' AND p.poem_author = '潘阆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人·曲阑深处重相见', '纳兰性德', '清代', '曲阑深处重相见，匀泪偎人颤。凄凉别后两应同，最是不胜清怨月明中。\n半生已分孤眠过，山枕檀痕涴。忆来何事最销魂，第一折枝花样画罗裙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人·曲阑深处重相见' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花绝句·其一', '陆游', '宋代', '闻道梅花坼晓风，雪堆遍满四山中。\n何方可化身千亿，一树梅花一放翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花绝句·其一' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('画蛇添足', '刘向', '两汉', '楚有祠者，赐其舍人卮酒，舍人相谓曰：“数人饮之不足，一人饮之有余。请画地为蛇，先成者饮酒。”\n一人蛇先成，引酒且饮之，乃左手持卮，右手画蛇，曰：“吾能为之足。”未成，一人之蛇成，夺其卮曰：“蛇固无足，子安能为之足？”遂饮其酒。为蛇足者，终亡其酒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '画蛇添足' AND p.poem_author = '刘向';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新雷', '张维屏', '清代', '造物无言却有情，每于寒尽觉春生。\n千红万紫安排著，只待新雷第一声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新雷' AND p.poem_author = '张维屏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·魏风·硕鼠', '佚名', '先秦', '硕鼠硕鼠，无食我黍！三岁贯女，莫我肯顾。逝将去女，适彼乐土。乐土乐土，爰得我所。\n硕鼠硕鼠，无食我麦！三岁贯女，莫我肯德。逝将去女，适彼乐国。乐国乐国，爰得我直。\n硕鼠硕鼠，无食我苗！三岁贯女，莫我肯劳。逝将去女，适彼乐郊。乐郊乐郊，谁之永号？(女 通 汝)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·魏风·硕鼠' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('樛木', '佚名', '先秦', '南有樛木，葛藟累之。乐只君子，福履绥之。\n南有樛木，葛藟荒之。乐只君子，福履将之。\n南有樛木，葛藟萦之。乐只君子，福履成之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '樛木' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('涉江采芙蓉', '佚名', '两汉', '涉江采芙蓉，兰泽多芳草。\n采之欲遗谁，所思在远道。\n还顾望旧乡，长路漫浩浩。\n同心而离居，忧伤以终老。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '涉江采芙蓉' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青玉案·凌波不过横塘路', '贺铸', '宋代', '凌波不过横塘路，但目送、芳尘去。锦瑟华年谁与度？月桥花院，琐窗朱户，只有春知处。\n飞云冉冉蘅皋暮，彩笔新题断肠句。试问闲情都几许？一川烟草，满城风絮，梅子黄时雨。(版本一)\n\n凌波不过横塘路，但目送、芳尘去。锦瑟华年谁与度？月台花榭，琐窗朱户，只有春知处。\n碧云冉冉蘅皋暮，彩笔新题断肠句。试问闲愁都几许？一川烟草，满城风絮，梅子黄时雨。(版本二)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青玉案·凌波不过横塘路' AND p.poem_author = '贺铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蒿里行', '曹操', '两汉', '关东有义士，兴兵讨群凶。\n初期会盟津，乃心在咸阳。\n军合力不齐，踌躇而雁行。\n势利使人争，嗣还自相戕。\n淮南弟称号，刻玺于北方。\n铠甲生虮虱，万姓以死亡。\n白骨露於野，千里无鸡鸣。\n生民百遗一，念之断人肠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蒿里行' AND p.poem_author = '曹操';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采莲曲', '白居易', '唐代', '菱叶萦波荷飐风，荷花深处小船通。 \n逢郎欲语低头笑，碧玉搔头落水中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采莲曲' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('前出塞九首·其六', '杜甫', '唐代', '挽弓当挽强，用箭当用长。射人先射马，擒贼先擒王。\n杀人亦有限，列国自有疆。苟能制侵陵，岂在多杀伤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '前出塞九首·其六' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闲居初夏午睡起·其一', '杨万里', '宋代', '梅子留酸软齿牙，芭蕉分绿与窗纱。\n日长睡起无情思，闲看儿童捉柳花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闲居初夏午睡起·其一' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('文侯与虞人期猎', '刘向', '两汉', '魏文侯与虞人期猎。是日，饮酒乐，天雨。文侯将出，左右曰：“今日饮酒乐，天又雨，公将焉之？”文侯曰：“吾与虞人期猎，虽乐，岂可不一会期哉！”乃往，身自罢之。魏于是乎始强。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '文侯与虞人期猎' AND p.poem_author = '刘向';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('定风波·南海归赠王定国侍人寓娘', '苏轼', '宋代', '常羡人间琢玉郎，天应乞与点酥娘。尽道清歌传皓齿，风起，雪飞炎海变清凉。\n万里归来颜愈少，微笑，笑时犹带岭梅香。试问岭南应不好，却道：此心安处是吾乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '定风波·南海归赠王定国侍人寓娘' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头·安石在东海', '苏轼', '宋代', '余去岁在东武，作《水调歌头》以寄子由。今年子由相从彭门居百余日，过中秋而去，作此曲以别。余以其语过悲，乃为和之，其意以不早退为戒，以退而相从之乐为慰云耳\n\n安石在东海，从事鬓惊秋。中年亲友难别，丝竹缓离愁。一旦功成名遂，准拟东还海道，扶病入西州。雅志困轩冕，遗恨寄沧洲。\n岁云暮，须早计，要褐裘。故乡归去千里，佳处辄迟留。我醉歌时君和，醉倒须君扶我，惟酒可忘忧。一任刘玄德，相对卧高楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头·安石在东海' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('世无良猫', '乐钧', '清代', '某恶鼠，破家求良猫。厌以腥膏，眠以毡罽。猫既饱且安，率不食鼠，甚者与鼠游戏，鼠以故益暴。某恐，遂不复蓄猫，以为天下无良猫也。是无猫邪，是不会蓄猫也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '世无良猫' AND p.poem_author = '乐钧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采薇(节选)', '佚名', '先秦', '昔我往矣，杨柳依依。\n今我来思，雨雪霏霏。\n行道迟迟，载渴载饥。\n我心悲伤，莫知我哀！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '采薇(节选)' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日', '秦观', '宋代', '一夕轻雷落万丝，霁光浮瓦碧参差。\n有情芍药含春泪，无力蔷薇卧晓枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与史郎中钦听黄鹤楼上吹笛 / 题北榭碑', '李白', '唐代', '一为迁客去长沙，西望长安不见家。 \n黄鹤楼中吹玉笛，江城五月落梅花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与史郎中钦听黄鹤楼上吹笛 / 题北榭碑' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('襄邑道中', '陈与义', '宋代', '飞花两岸照船红，百里榆堤半日风。\n卧看满天云不动，不知云与我俱东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '襄邑道中' AND p.poem_author = '陈与义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋风引', '刘禹锡', '唐代', '何处秋风至？萧萧送雁群。\n朝来入庭树，孤客最先闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋风引' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黍离', '佚名', '先秦', '彼黍离离，彼稷之苗。行迈靡靡，中心摇摇。知我者，谓我心忧；不知我者，谓我何求。悠悠苍天，此何人哉？\n彼黍离离，彼稷之穗。行迈靡靡，中心如醉。知我者，谓我心忧；不知我者，谓我何求。悠悠苍天，此何人哉？\n彼黍离离，彼稷之实。行迈靡靡，中心如噎。知我者，谓我心忧；不知我者，谓我何求。悠悠苍天，此何人哉？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黍离' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('项脊轩志', '归有光', '明代', '项脊轩，旧南阁子也。室仅方丈，可容一人居。百年老屋，尘泥渗漉，雨泽下注；每移案，顾视，无可置者。又北向，不能得日，日过午已昏。余稍为修葺，使不上漏。前辟四窗，垣墙周庭，以当南日，日影反照，室始洞然。又杂植兰桂竹木于庭，旧时栏楯，亦遂增胜。借书满架，偃仰啸歌，冥然兀坐，万籁有声；而庭堦寂寂，小鸟时来啄食，人至不去。三五之夜，明月半墙，桂影斑驳，风移影动，珊珊可爱。(堦寂寂 一作：阶寂寂)\n\n　　然余居于此，多可喜，亦多可悲。先是庭中通南北为一。迨诸父异爨，内外多置小门，墙往往而是。东犬西吠，客逾庖而宴，鸡栖于厅。庭中始为篱，已为墙，凡再变矣。家有老妪，尝居于此。妪，先大母婢也，乳二世，先妣抚之甚厚。室西连于中闺，先妣尝一至。妪每谓余曰：”某所，而母立于兹。”妪又曰：”汝姊在吾怀，呱呱而泣；娘以指叩门扉曰：‘儿寒乎？欲食乎？’吾从板外相为应答。”语未毕，余泣，妪亦泣。余自束发，读书轩中，一日，大母过余曰：”吾儿，久不见若影，何竟日默默在此，大类女郎也？”比去，以手阖门，自语曰：”吾家读书久不效，儿之成，则可待乎！”顷之，持一象笏至，曰：”此吾祖太常公宣德间执此以朝，他日汝当用之！”瞻顾遗迹，如在昨日，令人长号不自禁。\n\n　　轩东，故尝为厨，人往，从轩前过。余扃牖而居，久之，能以足音辨人。轩凡四遭火，得不焚，殆有神护者。\n\n　　项脊生曰：“蜀清守丹穴，利甲天下，其后秦皇帝筑女怀清台；刘玄德与曹操争天下，诸葛孔明起陇中。方二人之昧昧于一隅也，世何足以知之，余区区处败屋中，方扬眉、瞬目，谓有奇景。人知之者，其谓与坎井之蛙何异？”（人教版《中国古代诗歌散文欣赏》中无此段文字；沪教版无此段。）\n\n　　余既为此志，后五年，吾妻来归，时至轩中，从余问古事，或凭几学书。吾妻归宁，述诸小妹语曰：”闻姊家有阁子，且何谓阁子也？”其后六年，吾妻死，室坏不修。其后二年，余久卧病无聊，乃使人复葺南阁子，其制稍异于前。然自后余多在外，不常居。\n\n　　庭有枇杷树，吾妻死之年所手植也，今已亭亭如盖矣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '项脊轩志' AND p.poem_author = '归有光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('掩耳盗铃', '吕不韦 撰', '先秦', '范氏之亡也，百姓有得钟者，欲负而走，则钟大不可负；以锤毁之，钟况然有声。恐人闻之而夺己也，遽掩其耳。恶人闻之，可也；恶己自闻之，悖也！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '掩耳盗铃' AND p.poem_author = '吕不韦 撰';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行宫' AND p.poem_author = '元稹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·出塞', '纳兰性德', '清代', '今古河山无定据。画角声中，牧马频来去。满目荒凉谁可语？西风吹老丹枫树。\n从前幽怨应无数。铁马金戈，青冢黄昏路。一往情深深几许？深山夕照深秋雨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·出塞' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('剑客 / 述剑', '贾岛', '唐代', '十年磨一剑，霜刃未曾试。\n今日把示君，谁有不平事？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '剑客 / 述剑' AND p.poem_author = '贾岛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('月下独酌四首', '李白', '唐代', '花间一壶酒，独酌无相亲。\n举杯邀明月，对影成三人。\n月既不解饮，影徒随我身。\n暂伴月将影，行乐须及春。\n我歌月徘徊，我舞影零乱。\n醒时相交欢，醉后各分散。（另版本“相”为“同”）\n永结无情游，相期邈云汉。\n\n天若不爱酒，酒星不在天。\n地若不爱酒，地应无酒泉。\n天地既爱酒，爱酒不愧天。\n已闻清比圣，复道浊如贤。\n贤圣既已饮，何必求神仙。\n三杯通大道，一斗合自然。\n但得酒中趣，勿为醒者传。\n\n三月咸阳城，千花昼如锦。\n谁能春独愁，对此径须饮。\n穷通与修短，造化夙所禀。\n一樽齐死生，万事固难审。\n醉後失天地，兀然就孤枕。\n不知有吾身，此乐最为甚。\n\n穷愁千万端，美酒三百杯。\n愁多酒虽少，酒倾愁不来。\n所以知酒圣，酒酣心自开。\n辞粟卧首阳，屡空饥颜回。\n当代不乐饮，虚名安用哉。\n蟹螯即金液，糟丘是蓬莱。\n且须饮美酒，乘月醉高台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '月下独酌四首' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('廉颇蔺相如列传(节选)', '司马迁', '两汉', '廉颇者，赵之良将也。赵惠文王十六年，廉颇为赵将，伐齐，大破之，取阳晋，拜为上卿，以勇气闻于诸侯。蔺相如者，赵人也，为赵宦者令缪贤舍人。\n\n　　赵惠文王时，得楚和氏璧。秦昭王闻之，使人遗赵王书，愿以十五城请易璧。赵王与大将军廉颇诸大臣谋：欲予秦，秦城恐不可得，徒见欺；欲勿予，即患秦兵之来。计未定，求人可使报秦者，未得。宦者令缪贤曰：“臣舍人蔺相如可使。”王问：“何以知之？”对曰：“臣尝有罪，窃计欲亡走燕，臣舍人相如止臣，曰：‘君何以知燕王？’臣语曰：‘臣尝从大王与燕王会境上，燕王私握臣手，曰“愿结友”。以此知之，故欲往。’相如谓臣曰：‘夫赵强而燕弱，而君幸于赵王，故燕王欲结于君。今君乃亡赵走燕，燕畏赵，其势必不敢留君，而束君归赵矣。君不如肉袒伏斧质请罪，则幸得脱矣。’臣从其计，大王亦幸赦臣。臣窃以为其人勇士，有智谋，宜可使。”于是王召见，问蔺相如曰：“秦王以十五城请易寡人之璧，可予不？”相如曰：“秦强而赵弱，不可不许。”王曰：“取吾璧，不予我城，奈何？”相如曰：“秦以城求璧而赵不许，曲在赵。赵予璧而秦不予赵城，曲在秦。均之二策，宁许以负秦曲。”王曰：“谁可使者？”相如曰：“王必无人，臣愿奉璧往使。城入赵而璧留秦；城不入，臣请完璧归赵。”赵王于是遂遣相如奉璧西入秦。\n\n　　秦王坐章台见相如，相如奉璧奏秦王。秦王大喜，传以示美人及左右，左右皆呼万岁。相如视秦王无意偿赵城，乃前曰：“璧有瑕，请指示王。”王授璧，相如因持璧却立，倚柱，怒发上冲冠，谓秦王曰：“大王欲得璧，使人发书至赵王，赵王悉召群臣议，皆曰‘秦贪，负其强，以空言求璧，偿城恐不可得’。议不欲予秦璧。臣以为布衣之交尚不相欺，况大国乎！且以一璧之故逆强秦之欢，不可。于是赵王乃斋戒五日，使臣奉璧，拜送书于庭。何者？严大国之威以修敬也。今臣至，大王见臣列观，礼节甚倨；得璧，传之美人，以戏弄臣。臣观大王无意偿赵王城邑，故臣复取璧。大王必欲急臣，臣头今与璧俱碎于柱矣！”相如持其璧睨柱，欲以击柱。秦王恐其破璧，乃辞谢固请，召有司案图，指从此以往十五都予赵。相如度秦王特以诈详为予赵城，实不可得，乃谓秦王曰：“和氏璧，天下所共传宝也，赵王恐，不敢不献。赵王送璧时，斋戒五日，今大王亦宜斋戒五日，设九宾于廷，臣乃敢上璧。”秦王度之，终不可强夺，遂许斋五日，舍相如广成传。相如度秦王虽斋，决负约不偿城，乃使其从者衣褐，怀其璧，从径道亡，归璧于赵。\n\n　　秦王斋五日后，乃设九宾礼于廷，引赵使者蔺相如。相如至，谓秦王曰：“秦自缪公以来二十馀君，未尝有坚明约束者也。臣诚恐见欺于王而负赵，故令人持璧归，间至赵矣。且秦强而赵弱，大王遣一介之使至赵，赵立奉璧来。今以秦之强而先割十五都予赵，赵岂敢留璧而得罪于大王乎？臣知欺大王之罪当诛，臣请就汤镬，唯大王与群臣孰计议之。”秦王与群臣相视而嘻。左右或欲引相如去，秦王因曰：“今杀相如，终不能得璧也，而绝秦赵之欢，不如因而厚遇之，使归赵，赵王岂以一璧之故欺秦邪！”卒廷见相如，毕礼而归之。\n\n　　相如既归，赵王以为贤大夫使不辱于诸侯，拜相如为上大夫。秦亦不以城予赵，赵亦终不予秦璧。\n\n　　其后秦伐赵，拔石城。明年，复攻赵，杀二万人。\n\n　　秦王使使者告赵王，欲与王为好会于西河外渑池。赵王畏秦，欲毋行。廉颇、蔺相如计曰：“王不行，示赵弱且怯也。”赵王遂行，相如从。廉颇送至境，与王诀曰：“王行，度道里会遇之礼毕，还，不过三十日。三十日不还，则请立太子为王，以绝秦望。”王许之，遂与秦王会渑池。秦王饮酒酣，曰：“寡人窃闻赵王好音，请奏瑟。”赵王鼓瑟。秦御史前书曰“某年月日，秦王与赵王会饮，令赵王鼓瑟”。蔺相如前曰：“赵王窃闻秦王善为秦声，请奏盆缻秦王，以相娱乐。”秦王怒，不许。于是相如前进缻，因跪请秦王。秦王不肯击缻。相如曰：“五步之内，相如请得以颈血溅大王矣！”左右欲刃相如，相如张目叱之，左右皆靡。于是秦王不怿，为一击缻。相如顾召赵御史书曰“某年月日，秦王为赵王击缻”。秦之群臣曰：“请以赵十五城为秦王寿。”蔺相如亦曰：“请以秦之咸阳为赵王寿。”秦王竟酒，终不能加胜于赵。赵亦盛设兵以待秦，秦不敢动。\n\n　　既罢归国，以相如功大，拜为上卿，位在廉颇之右。廉颇曰：“我为赵将，有攻城野战之大功，而蔺相如徒以口舌为劳，而位居我上，且相如素贱人，吾羞，不忍为之下。”宣言曰：“我见相如，必辱之。”相如闻，不肯与会。相如每朝时，常称病，不欲与廉颇争列。已而相如出，望见廉颇，相如引车避匿。于是舍人相与谏曰：“臣所以去亲戚而事君者，徒慕君之高义也。今君与廉颇同列，廉君宣恶言而君畏匿之，恐惧殊甚，且庸人尚羞之，况于将相乎！臣等不肖，请辞去。”蔺相如固止之，曰：“公之视廉将军孰与秦王？”曰：“不若也。”相如曰：“夫以秦王之威，而相如廷叱之，辱其群臣，相如虽驽，独畏廉将军哉？顾吾念之，强秦之所以不敢加兵于赵者，徒以吾两人在也。今两虎共斗，其势不俱生。吾所以为此者，以先国家之急而后私仇也。”廉颇闻之，肉袒负荆，因宾客至蔺相如门谢罪。曰：“鄙贱之人，不知将军宽之至此也。”卒相与欢，为刎颈之交。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '廉颇蔺相如列传(节选)' AND p.poem_author = '司马迁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病起书怀', '陆游', '宋代', '病骨支离纱帽宽，孤臣万里客江干。\n位卑未敢忘忧国，事定犹须待阖棺。\n天地神灵扶庙社，京华父老望和銮。\n出师一表通今古，夜半挑灯更细看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病起书怀' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('村夜', '白居易', '唐代', '霜草苍苍虫切切，村南村北行人绝。 \n独出门前望野田，月明荞麦花如雪。 (门前 一作：前门)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '村夜' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题菊花', '黄巢', '唐代', '飒飒西风满院栽，蕊寒香冷蝶难来。 \n他年我若为青帝，报与桃花一处开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题菊花' AND p.poem_author = '黄巢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七哀诗', '曹植', '魏晋', '明月照高楼，流光正徘徊。\n上有愁思妇，悲叹有余哀。\n借问叹者谁？言是宕子妻。\n君行逾十年，孤妾常独栖。\n君若清路尘，妾若浊水泥。\n浮沉各异势，会合何时谐？\n愿为西南风，长逝入君怀。\n君怀良不开，贱妾当何依？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七哀诗' AND p.poem_author = '曹植';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('惠子相梁', '佚名', '先秦', '惠子相梁，庄子往见之。或谓惠子曰：“庄子来，欲代子相。”于是惠子恐，搜于国中三日三夜。庄子往见之，曰：“南方有鸟，其名为鹓鶵，子知之乎？夫鹓鶵发于南海，而飞于北海；非梧桐不止，非练实不食，非醴泉不饮。于是鸱得腐鼠，鹓鶵过之，仰而视之曰：‘吓！’今子欲以子之梁国而吓我邪？”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '惠子相梁' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六国论', '苏洵', '宋代', '六国破灭，非兵不利 ，战不善，弊在赂秦。赂秦而力亏，破灭之道也。或曰：六国互丧，率赂秦耶？曰：不赂者以赂者丧，盖失强援，不能独完。故曰：弊在赂秦也。\n\n　　秦以攻取之外，小则获邑，大则得城。较秦之所得，与战胜而得者，其实百倍；诸侯之所亡，与战败而亡者，其实亦百倍。则秦之所大欲，诸侯之所大患，固不在战矣。思厥先祖父，暴霜露，斩荆棘，以有尺寸之地。子孙视之不甚惜，举以予人，如弃草芥。今日割五城，明日割十城，然后得一夕安寝。起视四境，而秦兵又至矣。然则诸侯之地有限，暴秦之欲无厌，奉之弥繁，侵之愈急。故不战而强弱胜负已判矣。至于颠覆，理固宜然。古人云：“以地事秦，犹抱薪救火，薪不尽，火不灭。”此言得之。\n\n　　齐人未尝赂秦，终继五国迁灭，何哉？与嬴而不助五国也。五国既丧，齐亦不免矣。燕赵之君，始有远略，能守其土，义不赂秦。是故燕虽小国而后亡，斯用兵之效也。至丹以荆卿为计，始速祸焉。赵尝五战于秦，二败而三胜。后秦击赵者再，李牧连却之。洎牧以谗诛，邯郸为郡，惜其用武而不终也。且燕赵处秦革灭殆尽之际，可谓智力孤危，战败而亡，诚不得已。向使三国各爱其地，齐人勿附于秦，刺客不行，良将犹在，则胜负之数，存亡之理，当与秦相较，或未易量。\n\n　　呜呼！以赂秦之地，封天下之谋臣，以事秦之心，礼天下之奇才，并力西向，则吾恐秦人食之不得下咽也。悲夫！有如此之势，而为秦人积威之所劫，日削月割，以趋于亡。为国者无使为积威之所劫哉！\n\n　　夫六国与秦皆诸侯，其势弱于秦，而犹有可以不赂而胜之之势。苟以天下之大，而从六国破亡之故事，是又在六国下矣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '六国论' AND p.poem_author = '苏洵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小雅·鹿鸣', '佚名', '先秦', '呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙。吹笙鼓簧，承筐是将。人之好我，示我周行。\n呦呦鹿鸣，食野之蒿。我有嘉宾，德音孔昭。视民不恌，君子是则是效。我有旨酒，嘉宾式燕以敖。\n呦呦鹿鸣，食野之芩。我有嘉宾，鼓瑟鼓琴。鼓瑟鼓琴，和乐且湛。我有旨酒，以燕乐嘉宾之心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小雅·鹿鸣' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑子·当时错', '纳兰性德', '清代', '而今才道当时错，心绪凄迷。红泪偷垂，满眼春风百事非。\n情知此后来无计，强说欢期。一别如斯，落尽梨花月又西。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑子·当时错' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上李邕', '李白', '唐代', '大鹏一日同风起，扶摇直上九万里。\n假令风歇时下来，犹能簸却沧溟水。\n世人见我恒殊调，闻余大言皆冷笑。\n宣父犹能畏后生，丈夫未可轻年少。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上李邕' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('摸鱼儿·更能消几番风雨', '辛弃疾', '宋代', '淳熙己亥，自湖北漕移湖南，同官王正之置酒小山亭，为赋。\n\n更能消、几番风雨，匆匆春又归去。惜春长怕花开早，何况落红无数。春且住，见说道、天涯芳草无归路。怨春不语。算只有殷勤，画檐蛛网，尽日惹飞絮。(怕 一作：恨) (无归路 一作：迷归路）\n长门事，准拟佳期又误。蛾眉曾有人妒。千金纵买相如赋，脉脉此情谁诉？君莫舞，君不见、玉环飞燕皆尘土！闲愁最苦！休去倚危栏，斜阳正在，烟柳断肠处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '摸鱼儿·更能消几番风雨' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('劝学', '孟郊', '唐代', '击石乃有火，不击元无烟。\n人学始知道，不学非自然。\n万事须己运，他得非我贤。\n青春须早为，岂能长少年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '劝学' AND p.poem_author = '孟郊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读书要三到', '朱熹', '宋代', '凡读书......须要读得字字响亮，不可误一字，不可少一字，不可多一字，不可倒一字，不可牵强暗记，只是要多诵数遍，自然上口，久远不忘。古人云，“读书百遍，其义自见”。谓读得熟，则不待解说，自晓其义也。余尝谓，读书有三到，谓心到，眼到，口到。心不在此，则眼不看仔细，心眼既不专一，却只漫浪诵读，决不能记，记亦不能久也。三到之中，心到最急。心既到矣，眼口岂不到乎？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '读书要三到' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('精卫填海', '佚名', '先秦', '又北二百里，曰发鸠之山，其上多柘木，有鸟焉，其状如乌，文首，白喙，赤足，名曰：“精卫”，其鸣自詨。是炎帝之少女，名曰女娃。女娃游于东海，溺而不返，故为精卫，常衔西山之木石，以堙于东海。漳水出焉，东流注于河。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '精卫填海' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·代人赋', '辛弃疾', '宋代', '晚日寒鸦一片愁。柳塘新绿却温柔。若教眼底无离恨，不信人间有白头。\n肠已断，泪难收。相思重上小红楼。情知已被山遮断，频倚阑干不自由。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·代人赋' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寻雍尊师隐居', '李白', '唐代', '群峭碧摩天，逍遥不记年。\n拨云寻古道，倚石听流泉。\n花暖青牛卧，松高白鹤眠。\n语来江色暮，独自下寒烟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寻雍尊师隐居' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠范晔诗', '陆凯', '南北朝', '折花逢驿使，寄与陇头人。(折花 一作：折梅)\n江南无所有，聊赠一枝春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠范晔诗' AND p.poem_author = '陆凯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙·小院闲窗春色深', '李清照', '宋代', '小院闲窗春已深，重帘未卷影沉沉。倚楼无语理瑶琴。(春已深 一作：春色深)\n远岫出云催薄暮，细风吹雨弄轻阴。梨花欲谢恐难禁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙·小院闲窗春色深' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长歌行', '李白', '唐代', '桃李待日开，荣华照当年。\n东风动百物，草木尽欲言。\n枯枝无丑叶，涸水吐清泉。\n大力运天地，羲和无停鞭。\n功名不早著，竹帛将何宣。\n桃李务青春，谁能贳白日。\n富贵与神仙，蹉跎成两失。\n金石犹销铄，风霜无久质。\n畏落日月后，强欢歌与酒。\n秋霜不惜人，倏忽侵蒲柳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长歌行' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新嫁娘词' AND p.poem_author = '王建';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('对酒', '秋瑾', '清代', '不惜千金买宝刀，貂裘换酒也堪豪。\n一腔热血勤珍重，洒去犹能化碧涛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '对酒' AND p.poem_author = '秋瑾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晏子使楚', '刘向', '两汉', '一\n晏子使楚。楚人以晏子短，楚人为小门于大门之侧而延晏子。晏子不入，曰：“使狗国者从狗门入，今臣使楚，不当从此门入。”傧者更道，从大门入。见楚王。王曰：“齐无人耶？”晏子对曰：“齐之临淄三百闾，张袂成阴，挥汗成雨，比肩继踵而在，何为无人？”王曰：“然则何为使予？”晏子对曰：“齐命使，各有所主：其贤者使使贤主，不肖者使使不肖主。婴最不肖，故宜使楚矣！”（张袂成阴 一作：张袂成帷）\n\n二\n晏子将使楚。楚王闻之，谓左右曰：“晏婴，齐之习辞者也。今方来，吾欲辱之，何以也？”左右对曰：“为其来也，臣请缚一人，过王而行，王曰：‘何为者也？’对曰：‘齐人也。’王曰：‘何坐？’曰：‘坐盗。’\n\n三\n晏子至，楚王赐晏子酒，酒酣，吏二缚一人诣王。王曰：“缚者曷为者也？”对曰：“齐人也，坐盗。”王视晏子曰：“齐人固善盗乎？”晏子避席对曰：“婴闻之，橘生淮南则为橘，生于淮北则为枳，叶徒相似，其实味不同。所以然者何？水土异也。今民生长于齐不盗，入楚则盗，得无楚之水土使民善盗耶？”王笑曰：“ 圣人非所与熙也，寡人反取病焉。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '晏子使楚' AND p.poem_author = '刘向';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('曲池荷', '卢照邻', '唐代', '浮香绕曲岸，圆影覆华池。\n常恐秋风早，飘零君不知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '曲池荷' AND p.poem_author = '卢照邻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋浦歌十七首', '李白', '唐代', '秋浦长似秋，萧条使人愁。\n客愁不可度，行上东大楼。\n正西望长安，下见江水流。\n寄言向江水，汝意忆侬不。\n遥传一掬泪，为我达扬州。\n\n秋浦猿夜愁，黄山堪白头。\n清溪非陇水，翻作断肠流。\n欲去不得去，薄游成久游。\n何年是归日，雨泪下孤舟。\n\n秋浦锦驼鸟，人间天上稀。\n山鸡羞渌水，不敢照毛衣。\n\n两鬓入秋浦，一朝飒已衰。\n猿声催白发，长短尽成丝。\n\n秋浦多白猿，超腾若飞雪。\n牵引条上儿，饮弄水中月。\n\n愁作秋浦客，强看秋浦花。\n山川如剡县，风日似长沙。\n\n醉上山公马，寒歌宁戚牛。\n空吟白石烂，泪满黑貂裘。\n\n秋浦千重岭，水车岭最奇。\n天倾欲堕石，水拂寄生枝。\n\n江祖一片石，青天扫画屏。\n题诗留万古，绿字锦苔生。\n\n千千石楠树，万万女贞林。\n山山白鹭满，涧涧白猿吟。\n君莫向秋浦，猿声碎客心。\n\n逻人横鸟道，江祖出鱼梁。\n水急客舟疾，山花拂面香。\n\n水如一匹练，此地即平天。\n耐可乘明月，看花上酒船。\n\n渌水净素月，月明白鹭飞。\n郎听采菱女，一道夜歌归。\n\n炉火照天地，红星乱紫烟。\n赧郎明月夜，歌曲动寒川。\n\n白发三千丈，缘愁似个长。\n不知明镜里，何处得秋霜。\n\n秋浦田舍翁，采鱼水中宿。\n妻子张白鹇，结罝映深竹。\n\n桃波一步地，了了语声闻。\n黯与山僧别，低头礼白云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋浦歌十七首' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('少年行四首', '王维', '唐代', '新丰美酒斗十千，咸阳游侠多少年。\n相逢意气为君饮，系马高楼垂柳边。\n\n出身仕汉羽林郎，初随骠骑战渔阳。\n孰知不向边庭苦，纵死犹闻侠骨香。\n\n一身能擘两雕弧，虏骑千重只似无。\n偏坐金鞍调白羽，纷纷射杀五单于。\n\n汉家君臣欢宴终，高议云台论战功。\n天子临轩赐侯印，将军佩出明光宫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '少年行四首' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('端午三首', '赵蕃', '宋代', '谩说投诗赠汨罗，身今且乐奈渠何。\n尝闻求福木居士，试向艾人成祝呵。\n\n忠言不用竟沉死，留得文章星斗罗。\n何意更觞昌歜酒，为君击节一长歌。\n\n年年端午风兼雨，似为屈原陈昔冤。\n我欲于谁论许事，舍南舍北鹁鸠喧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '端午三首' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送别', '王维', '唐代', '下马饮君酒，问君何所之？\n君言不得意，归卧南山陲。\n但去莫复问，白云无尽时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送别' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('入若耶溪', '王籍', '南北朝', '艅艎何泛泛，空水共悠悠。\n阴霞生远岫，阳景逐回流。\n蝉噪林逾静，鸟鸣山更幽。\n此地动归念，长年悲倦游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '入若耶溪' AND p.poem_author = '王籍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元日', '李世民', '唐代', '高轩暧春色，邃阁媚朝光。\n彤庭飞彩旆，翠幌曜明珰。\n恭己临四极，垂衣驭八荒。\n霜戟列丹陛，丝竹韵长廊。\n穆矣熏风茂，康哉帝道昌。\n继文遵后轨，循古鉴前王。\n草秀故春色，梅艳昔年妆。\n巨川思欲济，终以寄舟航。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元日' AND p.poem_author = '李世民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陇西行四首·其二', '陈陶', '唐代', '誓扫匈奴不顾身，五千貂锦丧胡尘。\n可怜无定河边骨，犹是春闺梦里人！(春闺 一作：深闺)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陇西行四首·其二' AND p.poem_author = '陈陶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一剪梅·雨打梨花深闭门', '唐寅', '明代', '红满苔阶绿满枝，杜宇声声，杜宇声悲！交欢未久又分离，彩凤孤飞，彩凤孤栖。\n别后相思是几时？后会难知？后会难期？此情何以表相思？一首情词，一首情诗。\n雨打梨花深闭门，忘了青春，误了青春。赏心乐事共谁论？花下销魂，月下销魂。\n愁聚眉峰尽日颦，千点啼痕，万点啼痕。晓看天色暮看云，行也思君，坐也思君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '一剪梅·雨打梨花深闭门' AND p.poem_author = '唐寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('客至', '杜甫', '唐代', '舍南舍北皆春水，但见群鸥日日来。\n花径不曾缘客扫，蓬门今始为君开。\n盘飧市远无兼味，樽酒家贫只旧醅。\n肯与邻翁相对饮，隔篱呼取尽馀杯。(馀 通：余)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '客至' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江上渔者', '范仲淹', '宋代', '江上往来人，但爱鲈鱼美。\n君看一叶舟，出没风波里。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江上渔者' AND p.poem_author = '范仲淹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南湖早春', '白居易', '唐代', '风回云断雨初晴，返照湖边暖复明。\n乱点碎红山杏发，平铺新绿水蘋生。\n翅低白雁飞仍重，舌涩黄鹂语未成。\n不道江南春不好，年年衰病减心情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南湖早春' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郑人买履', '韩非', '先秦', '郑人有欲买履者，先自度其足，而置之其坐。至之市，而忘操之。已得履，乃曰：“吾忘持度。”反归取之。及反，市罢，遂不得履。人曰：“何不试之以足? ”曰：“宁信度,无自信也。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '郑人买履' AND p.poem_author = '韩非';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无题·八岁偷照镜', '李商隐', '唐代', '八岁偷照镜，长眉已能画。\n十岁去踏青，芙蓉作裙衩。\n十二学弹筝，银甲不曾卸。\n十四藏六亲，悬知犹未嫁。\n十五泣春风，背面秋千下。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无题·八岁偷照镜' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谏太宗十思疏', '魏征', '唐代', '臣闻：求木之长者，必固其根本；欲流之远者，必浚其泉源；思国之安者，必积其德义。源不深而望流之远，根不固而求木之长，德不厚而思国之治，臣虽下愚，知其不可，而况于明哲乎？人君当神器之重，居域中之大，将崇极天之峻，永保无疆之休。不念居安思危，戒奢以俭，德不处其厚，情不胜其欲，斯亦伐根以求木茂，塞源而欲流长也。(望国 一作：思国)\n\n　　凡百元首，承天景命，莫不殷忧而道著，功成而德衰，有善始者实繁，能克终者盖寡。岂其取之易守之难乎？昔取之而有余，今守之而不足，何也？夫在殷忧必竭诚以待下，既得志则纵情以傲物；竭诚则吴、越为一体，傲物则骨肉为行路。虽董之以严刑，震之以威怒，终苟免而不怀仁，貌恭而不心服。怨不在大，可畏惟人；载舟覆舟，所宜深慎。奔车朽索，其可忽乎？\n\n　　君人者，诚能见可欲，则思知足以自戒；将有作，则思知止以安人；念高危，则思谦冲而自牧；惧满溢，则思江海下百川；乐盘游，则思三驱以为度；忧懈怠，则思慎始而敬终；虑壅蔽，则思虚心以纳下；惧谗邪，则思正身以黜恶；恩所加，则思无因喜以谬赏；罚所及，则思无以怒而滥刑。总此十思，宏兹九德，简能而任之，择善而从之，则智者尽其谋，勇者竭其力，仁者播其惠，信者效其忠；文武争驰，君臣无事，可以尽豫游之乐，可以养松乔之寿，鸣琴垂拱，不言而化。何必劳神苦思，代下司职，役聪明之耳目，亏无为之大道哉？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '谏太宗十思疏' AND p.poem_author = '魏征';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('房兵曹胡马诗', '杜甫', '唐代', '胡马大宛名，锋棱瘦骨成。\n竹批双耳峻，风入四蹄轻。\n所向无空阔，真堪托死生。\n骁腾有如此，万里可横行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '房兵曹胡马诗' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔翁', '柳宗元', '唐代', '渔翁夜傍西岩宿，晓汲清湘燃楚竹。\n烟销日出不见人，欸乃一声山水绿。\n回看天际下中流，岩上无心云相逐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔翁' AND p.poem_author = '柳宗元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('花影', '苏轼', '宋代', '重重叠叠上瑶台，几度呼童扫不开。\n刚被太阳收拾去，却教明月送将来。(却教 一作：又教)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '花影' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('把酒问月·故人贾淳令予问之', '李白', '唐代', '青天有月来几时？我今停杯一问之。\n人攀明月不可得，月行却与人相随。\n皎如飞镜临丹阙，绿烟灭尽清辉发。\n但见宵从海上来，宁知晓向云间没。\n白兔捣药秋复春，嫦娥孤栖与谁邻？\n今人不见古时月，今月曾经照古人。\n古人今人若流水，共看明月皆如此。\n唯愿当歌对酒时，月光长照金樽里。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '把酒问月·故人贾淳令予问之' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '终南望余雪' AND p.poem_author = '祖咏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·郑风·山有扶苏', '佚名', '先秦', '山有扶苏，隰有荷华。不见子都，乃见狂且。\n山有乔松，隰有游龙，不见子充，乃见狡童。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·郑风·山有扶苏' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怨情' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花落', '鲍照', '南北朝', '中庭多杂树，偏为梅咨嗟。问君何独然？念其霜中能作花，露中能作实。摇荡春风媚春日，念尔零落逐寒风，徒有霜华无霜质。(寒风 一作：风飚)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花落' AND p.poem_author = '鲍照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('思吴江歌', '张翰', '魏晋', '秋风起兮木叶飞，吴江水兮鲈正肥。\n三千里兮家未归，恨难禁兮仰天悲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '思吴江歌' AND p.poem_author = '张翰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('狂夫', '杜甫', '唐代', '万里桥西一草堂，百花潭水即沧浪。\n风含翠篠娟娟净，雨裛红蕖冉冉香。(篠 通：筱)\n厚禄故人书断绝，恒饥稚子色凄凉。\n欲填沟壑唯疏放，自笑狂夫老更狂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '狂夫' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('关山月', '徐陵', '南北朝', '关山三五月，客子忆秦川。\n思妇高楼上，当窗应未眠。\n星旗映疏勒，云阵上祁连。\n战气今如此，从军复几年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '关山月' AND p.poem_author = '徐陵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花', '崔道融', '唐代', '数萼初含雪，孤标画本难。\n香中别有韵，清极不知寒。\n横笛和愁听，斜枝倚病看。\n朔风如解意，容易莫摧残。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花' AND p.poem_author = '崔道融';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绮怀', '黄景仁', '清代', '几回花下坐吹箫，银汉红墙入望遥。\n似此星辰非昨夜，为谁风露立中宵。\n缠绵思尽抽残茧，宛转心伤剥后蕉。\n三五年时三五月，可怜杯酒不曾消。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绮怀' AND p.poem_author = '黄景仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乌夜啼·昨夜风兼雨', '李煜', '五代', '昨夜风兼雨，帘帏飒飒秋声。烛残漏断频欹枕，起坐不能平。　\n世事漫随流水，算来一梦浮生。醉乡路稳宜频到，此外不堪行。(一梦 一作：梦里)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乌夜啼·昨夜风兼雨' AND p.poem_author = '李煜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵酒肆留别', '李白', '唐代', '风吹柳花满店香，吴姬压酒唤客尝。(劝客 一作：唤客)\n金陵子弟来相送，欲行不行各尽觞。\n请君试问东流水，别意与之谁短长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵酒肆留别' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洞仙歌·泗州中秋作', '晁补之', '宋代', '青烟幂处，碧海飞金镜。永夜闲阶卧桂影。露凉时、零乱多少寒螀，神京远，惟有蓝桥路近。 \n水晶帘不下，云母屏开，冷浸佳人淡脂粉。待都将许多明，付与金尊，投晓共、流霞倾尽。更携取、胡床上南楼，看玉做人间，素秋千顷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洞仙歌·泗州中秋作' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶成', '朱熹', '宋代', '少年易学老难成，一寸光阴不可轻。(争议：少年易老学难成)\n未觉池塘春草梦，阶前梧叶已秋声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶成' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('论诗五首·其二', '赵翼', '清代', '李杜诗篇万口传，至今已觉不新鲜。\n江山代有才人出，各领风骚数百年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '论诗五首·其二' AND p.poem_author = '赵翼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑子·群芳过后西湖好', '欧阳修', '宋代', '群芳过后西湖好，狼籍残红，飞絮濛濛。垂柳阑干尽日风。\n笙歌散尽游人去，始觉春空。垂下帘栊，双燕归来细雨中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑子·群芳过后西湖好' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头·黄州快哉亭赠张偓佺', '苏轼', '宋代', '落日绣帘卷，亭下水连空。知君为我新作，窗户湿青红。长记平山堂上，欹枕江南烟雨，杳杳没孤鸿。认得醉翁语，山色有无中。\n一千顷，都镜净，倒碧峰。忽然浪起，掀舞一叶白头翁。堪笑兰台公子，未解庄生天籁，刚道有雌雄。一点浩然气，千里快哉风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头·黄州快哉亭赠张偓佺' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西洲曲', '佚名', '南北朝', '忆梅下西洲，折梅寄江北。\n单衫杏子红，双鬓鸦雏色。\n西洲在何处？两桨桥头渡。\n日暮伯劳飞，风吹乌臼树。\n树下即门前，门中露翠钿。\n开门郎不至，出门采红莲。\n采莲南塘秋，莲花过人头。\n低头弄莲子，莲子清如水。\n置莲怀袖中，莲心彻底红。\n忆郎郎不至，仰首望飞鸿。\n鸿飞满西洲，望郎上青楼。\n楼高望不见，尽日栏杆头。\n栏杆十二曲，垂手明如玉。\n卷帘天自高，海水摇空绿。\n海水梦悠悠，君愁我亦愁。\n南风知我意，吹梦到西洲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西洲曲' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沈园二首', '陆游', '宋代', '城上斜阳画角哀，沈园非复旧池台，\n伤心桥下春波绿，曾是惊鸿照影来。\n\n梦断香消四十年，沈园柳老不吹绵。\n此身行作稽山土，犹吊遗踪一泫然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沈园二首' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桃花庵歌', '唐寅', '明代', '桃花坞裏桃花庵，桃花庵裏桃花仙。\n桃花仙人种桃树，又折花枝当酒钱。\n酒醒只在花前坐，酒醉还须花下眠。\n花前花後日复日，酒醉酒醒年复年。\n不愿鞠躬车马前，但愿老死花酒间。\n车尘马足贵者趣，酒盏花枝贫者缘。\n若将富贵比贫贱，一在平地一在天。\n若将贫贱比车马，他得驱驰我得闲。\n世人笑我忒风颠，我咲世人看不穿。\n记得五陵豪杰墓，无酒无花锄作田。\n弘治乙丑三月桃花庵主人唐寅（原版）\n\n桃花坞里桃花庵，桃花庵里桃花仙。\n桃花仙人种桃树，又摘桃花换酒钱。\n酒醒只在花前坐，酒醉还来花下眠。\n半醒半醉日复日，花落花开年复年。\n但愿老死花酒间，不愿鞠躬车马前。\n车尘马足富者趣，酒盏花枝贫者缘。\n若将富贵比贫者，一在平地一在天。\n若将贫贱比车马，他得驱驰我得闲。\n别人笑我忒风颠，我笑他人看不穿。\n不见五陵豪杰墓，无花无酒锄作田。（版本一）\n\n桃花坞里桃花庵，桃花庵里桃花仙。\n桃花仙人种桃树，又摘桃花换酒钱。\n酒醒只来花下坐，酒醉还来花下眠。\n半醒半醉日复日，花落花开年复年。\n但愿老死花酒间，不愿鞠躬车马前。\n车尘马足富者趣，酒盏花枝贫者缘。\n若将富贵比贫贱，一在平地一在天。\n若将花酒比车马，他得驱驰我得闲。\n别人笑我忒风骚，我笑他人看不穿。\n不见五陵豪杰墓，无酒无花锄作田。（版本二）', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桃花庵歌' AND p.poem_author = '唐寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月·遣兴', '辛弃疾', '宋代', '醉里且贪欢笑，要愁那得工夫。\n近来始觉古人书。信著全无是处。(著 通：着)\n昨夜松边醉倒，问松我醉何如。\n只疑松动要来扶。以手推松曰去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月·遣兴' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史·郁郁涧底松', '左思', '魏晋', '郁郁涧底松，离离山上苗。\n以彼径寸茎，荫此百尺条。\n世胄蹑高位，英俊沉下僚。\n地势使之然，由来非一朝。\n金张藉旧业，七叶珥汉貂。\n冯公岂不伟，白首不见招。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史·郁郁涧底松' AND p.poem_author = '左思';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闺怨' AND p.poem_author = '王昌龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('村晚', '雷震', '宋代', '草满池塘水满陂，山衔落日浸寒漪。\n牧童归去横牛背，短笛无腔信口吹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '村晚' AND p.poem_author = '雷震';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠孟浩然', '李白', '唐代', '吾爱孟夫子，风流天下闻。\n红颜弃轩冕，白首卧松云。 \n醉月频中圣，迷花不事君。\n高山安可仰，徒此揖清芬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠孟浩然' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('北人食菱', '江盈科', '明代', '北人生而不识菱者，仕于南方，席上啖菱，并壳入口。或曰：“食菱须去壳。”其人自护所短，曰：“我非不知，并壳者，欲以去热也。”问者曰：“北土亦有此物否？”答曰：“前山后山，何地不有？”\n\n　　夫菱生于水而非土产，此坐强不知以为知也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '北人食菱' AND p.poem_author = '江盈科';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('莲叶', '郑谷', '唐代', '移舟水溅差差绿，倚槛风摆柄柄香。(风摆 一作：风摇)\n多谢浣纱人未折，雨中留得盖鸳鸯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '莲叶' AND p.poem_author = '郑谷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙·一向年光有限身', '晏殊', '宋代', '一向年光有限身，等闲离别易销魂，酒筵歌席莫辞频。\n满目山河空念远，落花风雨更伤春，不如怜取眼前人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙·一向年光有限身' AND p.poem_author = '晏殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('羌村三首·其三', '杜甫', '唐代', '群鸡正乱叫，客至鸡斗争。\n驱鸡上树木，始闻叩柴荆。\n父老四五人，问我久远行。\n手中各有携，倾榼浊复清。\n莫辞酒味薄，黍地无人耕。\n兵戈既未息，儿童尽东征。\n请为父老歌：艰难愧深情！\n歌罢仰天叹，四座泪纵横。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '羌村三首·其三' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('将进酒', '李贺', '唐代', '琉璃钟，琥珀浓，小槽酒滴真珠红。\n烹龙炮凤玉脂泣，罗帏绣幕围香风。\n吹龙笛，击鼍鼓；皓齿歌，细腰舞。\n况是青春日将暮，桃花乱落如红雨。\n劝君终日酩酊醉，酒不到刘伶坟上土。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将进酒' AND p.poem_author = '李贺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汉广', '佚名', '先秦', '南有乔木，不可休思。\n汉有游女，不可求思。\n汉之广矣，不可泳思。\n江之永矣，不可方思。\n\n翘翘错薪，言刈其楚。\n之子于归，言秣其马。\n汉之广矣，不可泳思。\n江之永矣，不可方思。\n\n翘翘错薪，言刈其蒌。\n之子于归，言秣其驹。\n汉之广矣，不可泳思。\n江之永矣，不可方思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汉广' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐·春归何处', '黄庭坚', '宋代', '春归何处。寂寞无行路。若有人知春去处。唤取归来同住。 \n春无踪迹谁知。除非问取黄鹂。百啭无人能解，因风飞过蔷薇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐·春归何处' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('念奴娇·中秋', '苏轼', '宋代', '凭高眺远，见长空万里，云无留迹。桂魄飞来，光射处，冷浸一天秋碧。玉宇琼楼，乘鸾来去，人在清凉国。江山如画，望中烟树历历。\n我醉拍手狂歌，举杯邀月，对影成三客。起舞徘徊风露下，今夕不知何夕？便欲乘风，翻然归去，何用骑鹏翼。水晶宫里，一声吹断横笛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '念奴娇·中秋' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('滥竽充数', '韩非', '先秦', '齐宣王使人吹竽，必三百人。南郭处士请为王吹竽，宣王说之，廪食以数百人。宣王死，湣王立，好一一听之，处士逃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '滥竽充数' AND p.poem_author = '韩非';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('得胜乐·夏', '白朴', '元代', '酷暑天，葵榴发，喷鼻香十里荷花。兰舟斜缆垂扬下，只宜辅枕簟向凉亭披襟散发。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '得胜乐·夏' AND p.poem_author = '白朴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('稚子弄冰', '杨万里', '宋代', '稚子金盆脱晓冰，彩丝穿取当银铮。(银铮 一作：银钲)\n敲成玉磬穿林响，忽作玻璃碎地声。(玻璃 一作：玻瓈)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '稚子弄冰' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('端午', '文秀', '唐代', '节分端午自谁言，万古传闻为屈原。\n堪笑楚江空渺渺，不能洗得直臣冤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '端午' AND p.poem_author = '文秀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('淮上与友人别', '郑谷', '唐代', '扬子江头杨柳春，杨花愁杀渡江人。 \n数声风笛离亭晚，君向潇湘我向秦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '淮上与友人别' AND p.poem_author = '郑谷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南乡子·和杨元素时移守密州', '苏轼', '宋代', '东武望余杭，云海天涯两渺茫。何日功成名遂了，还乡，醉笑陪公三万场。\n不用诉离觞，痛饮从来别有肠。今夜送归灯火冷，河塘，堕泪羊公却姓杨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南乡子·和杨元素时移守密州' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('兰溪棹歌', '戴叔伦', '唐代', '凉月如眉挂柳湾，越中山色镜中看。\n兰溪三日桃花雨，半夜鲤鱼来上滩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '兰溪棹歌' AND p.poem_author = '戴叔伦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('多丽·咏白菊', '李清照', '宋代', '小楼寒，夜长帘幕低垂。恨萧萧、无情风雨，夜来揉损琼肌。也不似、贵妃醉脸，也不似、孙寿愁眉。韩令偷香，徐娘傅粉，莫将比拟未新奇。细看取、屈平陶令，风韵正相宜。微风起，清芬酝藉，不减酴醿。 \n渐秋阑、雪清玉瘦，向人无限依依。似愁凝、汉皋解佩，似泪洒、纨扇题诗。朗月清风，浓烟暗雨，天教憔悴度芳姿。纵爱惜、不知从此，留得几多时。人情好，何须更忆，泽畔东篱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '多丽·咏白菊' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王孙游', '谢朓', '南北朝', '绿草蔓如丝，杂树红英发。\n无论君不归，君归芳已歇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王孙游' AND p.poem_author = '谢朓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋登宣城谢脁北楼', '李白', '唐代', '江城如画里，山晚望晴空。(山\'晚\', 一作：晓)\n两水夹明镜，双桥落彩虹。\n人烟寒橘柚，秋色老梧桐。\n谁念北楼上，临风怀谢公。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋登宣城谢脁北楼' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('人有亡斧者', '吕不韦 撰', '先秦', '人有亡斧者，意其邻人之子。视其行步，窃斧也；视其颜色，窃斧也；听其言语，窃斧也；动作态度，无为而不窃斧者也。俄而掘其沟而得其斧，他日，复见其邻之子，其行动、颜色、动作皆无似窃斧者也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '人有亡斧者' AND p.poem_author = '吕不韦 撰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('父善游', '吕不韦 撰', '先秦', '有过于江上者，见人方引婴儿而欲投之江中，婴儿啼。人问其故。曰：“此其父善游。”\n\n　　其父虽善游，其子岂遽善游哉？以此任物，亦必悖矣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '父善游' AND p.poem_author = '吕不韦 撰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('富人之子', '苏轼', '宋代', '齐有富人，家累千金。其二子甚愚，其父又不教之。\n一日，艾子谓其父曰：“君之子虽美，而不通世务，他日曷能克其家?”\n父怒曰：“吾之子敏而且恃多能，岂有不通世务者耶?”\n艾子曰：“不须试之他，但问君之子，所食者米，从何来？若知之，吾当妄言之罪。”\n父遂呼其子问之。其子嘻然笑曰：“吾岂不知此也？每以布囊取来。”\n其父愀然改容曰：“子之愚甚也!彼米不是田中来?”\n艾子曰：“非其父不生其子。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '富人之子' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('念奴娇·过洞庭', '张孝祥', '宋代', '洞庭青草，近中秋，更无一点风色。玉界琼田三万顷，着我扁舟一叶。素月分辉，明河共影，表里俱澄澈。悠然心会，妙处难与君说。(著 同：着；玉界 一作：玉鉴)\n应念岭表经年，孤光自照，肝胆皆冰雪。短发萧骚襟袖冷，稳泛沧浪空阔。尽挹西江，细斟北斗，万象为宾客。扣舷独啸，不知今夕何夕。(沧浪 一作：沧冥；岭表 一作：岭海)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '念奴娇·过洞庭' AND p.poem_author = '张孝祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆梅', '李商隐', '唐代', '定定住天涯，依依向物华。\n寒梅最堪恨，常作去年花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆梅' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乐羊子妻', '范晔', '南北朝', '河南乐羊子之妻者，不知何氏之女也。\n\n　　羊子尝行路，得遗金一饼，还以与妻。妻曰：“妾闻志士不饮‘ 盗泉’之水，廉者不受嗟来之食，况拾遗求利,以污其行乎！”羊子大惭，乃捐金于野，而远寻师学。\n\n　　一年来归，妻跪问其故，羊子曰：“久行怀思，无它异也。”妻乃引刀趋机而言曰：“此织生自蚕茧，成于机杼。一丝而累，以至于寸，累寸不已，遂成丈匹。今若断斯织也，则捐失成功，稽废时日。夫子积学，当‘日知其所亡’，以就懿德；若中道而归，何异断斯织乎？”羊子感其言，复还终业，遂七年不返。\n\n　　尝有它舍鸡谬入园中，姑盗杀而食之，妻对鸡不餐而泣。姑怪问其故。妻曰：“自伤居贫，使食有它肉。”姑竟弃之。后盗欲有犯妻者，乃先劫其姑。妻闻，操刀而出。盗人曰：“释汝刀从我者可全，不从我者，则杀汝姑。”妻仰天而叹，举刀刎颈而死。盗亦不杀其姑。太守闻之，即捕杀贼盗，而赐妻缣帛，以礼葬之，号曰“贞义”。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乐羊子妻' AND p.poem_author = '范晔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山中问答 / 山中答俗人问', '李白', '唐代', '问余何意栖碧山，笑而不答心自闲。\n桃花流水窅然去，别有天地非人间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山中问答 / 山中答俗人问' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('报任少卿书 / 报任安书', '司马迁', '两汉', '太史公牛马走司马迁，再拜言。\n\n　　少卿足下：曩者辱赐书，教以慎于接物，推贤进士为务，意气勤勤恳恳。若望仆不相师，而用流俗人之言，仆非敢如此也。仆虽罢驽，亦尝侧闻长者之遗风矣。顾自以为身残处秽，动而见尤，欲益反损，是以独郁悒而无谁语。谚曰：“谁为为之？孰令听之？”盖钟子期死，伯牙终身不复鼓琴。何则？士为知己者用，女为说己者容。若仆大质已亏缺矣，虽材怀随和，行若由夷，终不可以为荣，适足以发笑而自点耳。\n\n　　书辞宜答，会东从上来，又迫贱事，相见日浅，卒卒无须臾之间，得竭指意。今少卿抱不测之罪，涉旬月，迫季冬，仆又薄从上雍，恐卒然不可为讳，是仆终已不得舒愤懑以晓左右，则长逝者魂魄私恨无穷。请略陈固陋。阙然久不报，幸勿为过。\n\n　　仆闻之：修身者，智之符也；爱施者，仁之端也；取予者，义之表也；耻辱者，勇之决也；立名者，行之极也。士有此五者，然后可以托于世，列于君子之林矣。故祸莫憯于欲利，悲莫痛于伤心，行莫丑于辱先，诟莫大于宫刑。刑余之人，无所比数，非一世也，所从来远矣。昔卫灵公与雍渠同载，孔子适陈；商鞅因景监见，赵良寒心；同子参乘，袁丝变色：自古而耻之！夫以中材之人，事有关于宦竖，莫不伤气，而况于慷慨之士乎！如今朝廷虽乏人，奈何令刀锯之余，荐天下之豪俊哉！仆赖先人绪业，得待罪辇毂下，二十余年矣。所以自惟：上之，不能纳忠效信，有奇策材力之誉，自结明主；次之，又不能拾遗补阙，招贤进能，显岩穴之士；外之，不能备行伍，攻城野战，有斩将搴旗之功；下之，不能积日累劳，取尊官厚禄，以为宗族交游光宠。四者无一遂，苟合取容，无所短长之效，可见于此矣。乡者，仆亦尝厕下大夫之列，陪外廷末议。不以此时引维纲，尽思虑，今已亏形为扫除之隶，在阘茸之中，乃欲仰首伸眉，论列是非，不亦轻朝廷、羞当世之士邪？嗟乎！嗟乎！如仆尚何言哉！尚何言哉！\n\n　　且事本末未易明也。仆少负不羁之才，长无乡曲之誉，主上幸以先人之故，使得奉薄伎，出入周卫之中。仆以为戴盆何以望天，故绝宾客之知，忘室家之业，日夜思竭其不肖之材力，务一心营职，以求亲媚于主上。而事乃有大谬不然者！\n\n　　夫仆与李陵俱居门下，素非能相善也。趣舍异路，未尝衔杯酒，接殷勤之余欢。然仆观其为人，自守奇士，事亲孝，与士信，临财廉，取予义，分别有让，恭俭下人，常思奋不顾身，以徇国家之急。其素所蓄积也，仆以为有国士之风。夫人臣出万死不顾一生之计，赴公家之难，斯已奇矣。今举事一不当，而全躯保妻子之臣随而媒孽其短，仆诚私心痛之。且李陵提步卒不满五千，深践戎马之地，足历王庭，垂饵虎口，横挑强胡，仰亿万之师，与单于连战十有余日，所杀过当。虏救死扶伤不给，旃裘之君长咸震怖，乃悉征其左、右贤王，举引弓之民，一国共攻而围之。转斗千里，矢尽道穷，救兵不至，士卒死伤如积。然陵一呼劳军，士无不起，躬自流涕，沬血饮泣，更张空弮，冒白刃，北首争死敌者。陵未没时，使有来报，汉公卿王侯皆奉觞上寿。后数日，陵败书闻，主上为之食不甘味，听朝不怡。大臣忧惧，不知所出。仆窃不自料其卑贱，见主上惨凄怛悼，诚欲效其款款之愚，以为李陵素与士大夫绝甘分少，能得人之死力，虽古之名将，不能过也。身虽陷败，彼观其意，且欲得其当而报于汉。事已无可奈何，其所摧败，功亦足以暴于天下矣。仆怀欲陈之，而未有路，适会召问，即以此指，推言陵之功，欲以广主上之意，塞睚眦之辞。未能尽明，明主不晓，以为仆沮贰师，而为李陵游说，遂下于理。拳拳之忠，终不能自列。因为诬上，卒从吏议。家贫，货赂不足以自赎，交游莫救，左右亲近不为一言。身非木石，独与法吏为伍，深幽囹圄之中，谁可告愬者！此真少卿所亲见，仆行事岂不然乎？李陵既生降，隤其家声，而仆又佴之蚕室，重为天下观笑。悲夫！悲夫！事未易一二为俗人言也。\n\n　　仆之先非有剖符丹书之功，文史星历，近乎卜祝之间，固主上所戏弄，倡优所畜，流俗之所轻也。假令仆伏法受诛，若九牛亡一毛，与蝼蚁何以异？而世又不与能死节者比，特以为智穷罪极，不能自免，卒就死耳。何也？素所自树立使然也。人固有一死，或重于泰山，或轻于鸿毛，用之所趋异也。太上不辱先，其次不辱身，其次不辱理色，其次不辱辞令，其次诎体受辱，其次易服受辱，其次关木索、被箠楚受辱，其次剔毛发、婴金铁受辱，其次毁肌肤、断肢体受辱，最下腐刑极矣！传曰“刑不上大夫。”此言士节不可不勉厉也。猛虎在深山，百兽震恐，及在槛阱之中，摇尾而求食，积威约之渐也。故士有画地为牢，势不可入；削木为吏，议不可对，定计于鲜也。今交手足，受木索，暴肌肤，受榜箠，幽于圜墙之中。当此之时，见狱吏则头抢地，视徒隶则心惕息。何者？积威约之势也。及以至是，言不辱者，所谓强颜耳，曷足贵乎！且西伯，伯也，拘于羑里；李斯，相也，具于五刑；淮阴，王也，受械于陈；彭越、张敖，南面称孤，系狱抵罪；绛侯诛诸吕，权倾五伯，囚于请室；魏其，大将也，衣赭衣，关三木；季布为朱家钳奴；灌夫受辱于居室。此人皆身至王侯将相，声闻邻国，及罪至罔加，不能引决自裁，在尘埃之中。古今一体，安在其不辱也？由此言之，勇怯，势也；强弱，形也。审矣，何足怪乎？夫人不能早自裁绳墨之外，以稍陵迟，至于鞭箠之间，乃欲引节，斯不亦远乎！古人所以重施刑于大夫者，殆为此也。\n\n　　夫人情莫不贪生恶死，念父母，顾妻子，至激于义理者不然，乃有所不得已也。今仆不幸，早失父母，无兄弟之亲，独身孤立，少卿视仆于妻子何如哉？且勇者不必死节，怯夫慕义，何处不勉焉！仆虽怯懦，欲苟活，亦颇识去就之分矣，何至自沉溺缧绁之辱哉！且夫臧获婢妾，犹能引决，况仆之不得已乎？所以隐忍苟活，幽于粪土之中而不辞者，恨私心有所不尽，鄙陋没世，而文采不表于后也。\n\n　　古者富贵而名摩灭，不可胜记，唯倜傥非常之人称焉。盖文王拘而演《周易》；仲尼厄而作《春秋》；屈原放逐，乃赋《离骚》；左丘失明，厥有《国语》；孙子膑脚，《兵法》修列；不韦迁蜀，世传《吕览》；韩非囚秦，《说难》《孤愤》；《诗》三百篇，大底圣贤发愤之所为作也。此人皆意有所郁结，不得通其道，故述往事、思来者。乃如左丘无目，孙子断足，终不可用，退而论书策，以舒其愤，思垂空文以自见。\n\n　　仆窃不逊，近自托于无能之辞，网罗天下放失旧闻，略考其行事，综其终始，稽其成败兴坏之纪，上计轩辕，下至于兹，为十表，本纪十二，书八章，世家三十，列传七十，凡百三十篇。亦欲以究天人之际，通古今之变，成一家之言。草创未就，会遭此祸，惜其不成，是以就极刑而无愠色。仆诚以著此书，藏之名山，传之其人，通邑大都，则仆偿前辱之责，虽万被戮，岂有悔哉！然此可为智者道，难为俗人言也！\n\n　　且负下未易居，下流多谤议。仆以口语遇遭此祸，重为乡党所笑，以污辱先人，亦何面目复上父母之丘墓乎？虽累百世，垢弥甚耳！是以肠一日而九回，居则忽忽若有所亡，出则不知其所往。每念斯耻，汗未尝不发背沾衣也！身直为闺阁之臣，宁得自引深藏于岩穴邪？故且从俗浮沉，与时俯仰，以通其狂惑。今少卿乃教以推贤进士，无乃与仆私心剌谬乎？今虽欲自雕琢，曼辞以自饰，无益，于俗不信，适足取辱耳。要之，死日然后是非乃定。书不能悉意，故略陈固陋。谨再拜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '报任少卿书 / 报任安书' AND p.poem_author = '司马迁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟夜书所见', '查慎行', '清代', '月黑见渔灯，孤光一点萤。\n微微风簇浪，散作满河星。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟夜书所见' AND p.poem_author = '查慎行';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无题·重帏深下莫愁堂', '李商隐', '唐代', '重帏深下莫愁堂，卧后清宵细细长。\n神女生涯原是梦，小姑居处本无郎。\n风波不信菱枝弱，月露谁教桂叶香。\n直道相思了无益，未妨惆怅是清狂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无题·重帏深下莫愁堂' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头·徐州中秋', '苏辙', '宋代', '离别一何久，七度过中秋。去年东武今夕，明月不胜愁。岂意彭城山下，同泛清河古汴，船上载凉州。鼓吹助清赏，鸿雁起汀洲。\n坐中客，翠羽帔，紫绮裘。素娥无赖，西去曾不为人留。今夜清尊对客，明夜孤帆水驿，依旧照离忧。但恐同王粲，相对永登楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头·徐州中秋' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉楼春·春恨', '晏殊', '宋代', '绿杨芳草长亭路，年少抛人容易去。楼头残梦五更钟，花底离愁三月雨。\n无情不似多情苦，一寸还成千万缕。天涯地角有穷时，只有相思无尽处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉楼春·春恨' AND p.poem_author = '晏殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饮中八仙歌', '杜甫', '唐代', '知章骑马似乘船，眼花落井水底眠。\n汝阳三斗始朝天，道逢麴车口流涎，恨不移封向酒泉。\n左相日兴费万钱，饮如长鲸吸百川，衔杯乐圣称避贤。\n宗之潇洒美少年，举觞白眼望青天，皎如玉树临风前。\n苏晋长斋绣佛前，醉中往往爱逃禅。\n李白斗酒诗百篇，长安市上酒家眠，(斗酒 一作：一斗)\n天子呼来不上船，自称臣是酒中仙。\n张旭三杯草圣传，脱帽露顶王公前，挥毫落纸如云烟。\n焦遂五斗方卓然，高谈雄辩惊四筵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饮中八仙歌' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新柳', '杨万里', '宋代', '柳条百尺拂银塘，且莫深青只浅黄。\n未必柳条能蘸水，水中柳影引他长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新柳' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春怨' AND p.poem_author = '刘方平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小星', '佚名', '先秦', '嘒彼小星，三五在东。肃肃宵征，夙夜在公。寔命不同。\n嘒彼小星，维参与昴。肃肃宵征，抱衾与裯。寔命不犹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小星' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登快阁', '黄庭坚', '宋代', '痴儿了却公家事，快阁东西倚晚晴。\n落木千山天远大，澄江一道月分明。\n朱弦已为佳人绝，青眼聊因美酒横。\n万里归船弄长笛，此心吾与白鸥盟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '登快阁' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江上', '王安石', '宋代', '江水漾西风，江花脱晚红。\n离情被横笛，吹过乱山东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江上' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('经乱离后天恩流夜郎忆旧游书怀赠江夏韦太守良宰', '李白', '唐代', '天上白玉京，十二楼五城。仙人抚我顶，结发受长生。 \n误逐世间乐，颇穷理乱情。九十六圣君，浮云挂空名。 \n天地赌一掷，未能忘战争。试涉霸王略，将期轩冕荣。 \n时命乃大谬，弃之海上行。学剑翻自哂，为文竟何成。 \n剑非万人敌，文窃四海声。儿戏不足道，五噫出西京。 \n临当欲去时，慷慨泪沾缨。叹君倜傥才，标举冠群英。 \n开筵引祖帐，慰此远徂征。鞍马若浮云，送余骠骑亭。 \n歌钟不尽意，白日落昆明。十月到幽州，戈鋋若罗星。 \n君王弃北海，扫地借长鲸。呼吸走百川，燕然可摧倾。 \n心知不得语，却欲栖蓬瀛。弯弧惧天狼，挟矢不敢张。 \n揽涕黄金台，呼天哭昭王。无人贵骏骨，騄耳空腾骧。 \n乐毅倘再生，于今亦奔亡。蹉跎不得意，驱马还贵乡。 \n逢君听弦歌，肃穆坐华堂。百里独太古，陶然卧羲皇。 \n征乐昌乐馆，开筵列壶觞。贤豪间青娥，对烛俨成行。 \n醉舞纷绮席，清歌绕飞梁。欢娱未终朝，秩满归咸阳。 \n祖道拥万人，供帐遥相望。一别隔千里，荣枯异炎凉。 \n炎凉几度改，九土中横溃。汉甲连胡兵，沙尘暗云海。 \n草木摇杀气，星辰无光彩。白骨成丘山，苍生竟何罪。 \n函关壮帝居，国命悬哥舒。长戟三十万，开门纳凶渠。 \n公卿如犬羊，忠谠醢与菹。二圣出游豫，两京遂丘墟。 \n帝子许专征，秉旄控强楚。节制非桓文，军师拥熊虎。 \n人心失去就，贼势腾风雨。惟君固房陵，诚节冠终古。 \n仆卧香炉顶，餐霞漱瑶泉。门开九江转，枕下五湖连。 \n半夜水军来，浔阳满旌旃。空名适自误，迫胁上楼船。 \n徒赐五百金，弃之若浮烟。辞官不受赏，翻谪夜郎天。 \n夜郎万里道，西上令人老。扫荡六合清，仍为负霜草。 \n日月无偏照，何由诉苍昊。良牧称神明，深仁恤交道。 \n一忝青云客，三登黄鹤楼。顾惭祢处士，虚对鹦鹉洲。 \n樊山霸气尽，寥落天地秋。江带峨眉雪，川横三峡流。 \n万舸此中来，连帆过扬州。送此万里目，旷然散我愁。 \n纱窗倚天开，水树绿如发。窥日畏衔山，促酒喜得月。 \n吴娃与越艳，窈窕夸铅红。呼来上云梯，含笑出帘栊。 \n对客小垂手，罗衣舞春风。宾跪请休息，主人情未极。 \n览君荆山作，江鲍堪动色。清水出芙蓉，天然去雕饰。 \n逸兴横素襟，无时不招寻。朱门拥虎士，列戟何森森。 \n剪凿竹石开，萦流涨清深。登台坐水阁，吐论多英音。 \n片辞贵白璧，一诺轻黄金。谓我不愧君，青鸟明丹心。 \n五色云间鹊，飞鸣天上来。传闻赦书至，却放夜郎回。 \n暖气变寒谷，炎烟生死灰。君登凤池去，忽弃贾生才。 \n桀犬尚吠尧，匈奴笑千秋。中夜四五叹，常为大国忧。 \n旌旆夹两山，黄河当中流。连鸡不得进，饮马空夷犹。 \n安得羿善射，一箭落旄头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '经乱离后天恩流夜郎忆旧游书怀赠江夏韦太守良宰' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九歌', '屈原', '先秦', '东皇太一\n吉日兮辰良，穆将愉兮上皇；\n抚长剑兮玉珥，璆锵鸣兮琳琅；\n瑶席兮玉瑱，盍将把兮琼芳；\n蕙肴蒸兮兰藉，奠桂酒兮椒浆；\n扬枹兮拊鼓，疏缓节兮安歌；\n陈竽瑟兮浩倡；\n灵偃蹇兮姣服，芳菲菲兮满堂；\n五音纷兮繁会，君欣欣兮乐康。\n\n云中君\n浴兰汤兮沐芳，华采衣兮若英；\n灵连蜷兮既留，烂昭昭兮未央；\n謇将憺兮寿宫，与日月兮齐光；\n龙驾兮帝服，聊翱游兮周章；\n灵皇皇兮既降，猋远举兮云中；\n览冀洲兮有余，横四海兮焉穷；\n思夫君兮太息，极劳心兮忡忡；\n\n湘君\n君不行兮夷犹，蹇谁留兮中洲；\n美要眇兮宜修，沛吾乘兮桂舟；\n令沅湘兮无波，使江水兮安流；\n望夫君兮未来，吹参差兮谁思；\n驾飞龙兮北征，邅吾道兮洞庭；\n薜荔柏兮蕙绸，荪桡兮兰旌；\n望涔阳兮极浦，横大江兮扬灵；\n扬灵兮未极，女婵媛兮为余太息；\n横流涕兮潺湲，隐思君兮陫侧；\n桂棹兮兰枻，斵冰兮积雪；\n采薜荔兮水中，搴芙蓉兮木末；\n心不同兮媒劳，恩不甚兮轻绝；\n石濑兮浅浅，飞龙兮翩翩；\n交不忠兮怨长，期不信兮告余以不闲；\n朝骋骛兮江皋，夕弭节兮北渚；\n鸟次兮屋上，水周兮堂下；\n捐余玦兮江中，遗余佩兮醴浦；\n采芳洲兮杜若，将以遗兮下女；\n时不可兮再得，聊逍遥兮容与。\n\n湘夫人\n帝子降兮北渚，目眇眇兮愁予；\n袅袅兮秋风，洞庭波兮木叶下；\n登白薠兮骋望，与佳期兮夕张；\n鸟何萃兮苹中，罾何为兮木上？(苹 通：蘋)\n沅有茝兮醴有兰，思公子兮未敢言；\n荒忽兮远望，观流水兮潺湲；\n麋何食兮庭中，蛟何为兮水裔；\n朝驰余马兮江皋，夕济兮西澨；\n闻佳人兮召余，将腾驾兮偕逝；\n筑室兮水中，葺之兮荷盖；\n荪壁兮紫坛，播芳椒兮成堂；\n桂栋兮兰橑，辛夷楣兮药房；\n罔薜荔兮为帷，擗蕙櫋兮既张；\n白玉兮为镇，疏石兰兮为芳；\n芷葺兮荷屋，缭之兮杜衡；\n合百草兮实庭，建芳馨兮庑门；\n九嶷缤兮并迎，灵之来兮如云；\n捐余袂兮江中，遗余褋兮醴浦；\n搴汀洲兮杜若，将以遗兮远者；\n时不可兮骤得，聊逍遥兮容与！\n\n大司命\n广开兮天门，纷吾乘兮玄云；\n令飘风兮先驱，使涷雨兮洒尘；\n君回翔兮以下，逾空桑兮从女；\n纷总总兮九州，何寿夭兮在予；\n高飞兮安翔，乘清气兮御阴阳；\n吾与君兮齐速，导帝之兮九坑；\n灵衣兮被被，玉佩兮陆离；\n一阴兮一阳，众莫知兮余所为；\n折疏麻兮瑶华，将以遗兮离居；\n老冉冉兮既极，不寖近兮愈疏；\n乘龙兮辚辚，高驰兮冲天；\n结桂枝兮延伫，羌愈思兮愁人；\n愁人兮奈何，愿若今兮无亏；\n固人命兮有当，孰离合兮何为？\n\n少司命\n秋兰兮麋芜，罗生兮堂下；\n绿叶兮素华，芳菲菲兮袭予；\n夫人兮自有美子，荪何以兮愁苦；\n秋兰兮青青，绿叶兮紫茎；\n满堂兮美人，忽独与余兮目成；\n入不言兮出不辞，乘回风兮载云旗；\n悲莫悲兮生别离，乐莫乐兮新相知；\n荷衣兮蕙带，儵而来兮忽而逝；\n夕宿兮帝郊，君谁须兮云之际；\n与女沐兮咸池，曦女发兮阳之阿；\n望美人兮未来，临风怳兮浩歌；\n孔盖兮翠旌，登九天兮抚彗星；\n竦长剑兮拥幼艾，荪独宜兮为民正。\n\n东君\n暾将出兮东方，照吾槛兮扶桑；\n抚余马兮安驱，夜皎皎兮既明；\n驾龙輈兮乘雷，载云旗兮委蛇；\n长太息兮将上，心低徊兮顾怀；\n羌声色兮娱人，观者儋兮忘归；\n縆瑟兮交鼓，萧钟兮瑶簴；\n鸣篪兮吹竽，思灵保兮贤姱；\n翾飞兮翠曾，展诗兮会舞；\n应律兮合节，灵之来兮敝日；\n青云衣兮白霓裳，举长矢兮射天狼；\n操余弧兮反沦降，援北斗兮酌桂浆；\n撰余辔兮高驰翔，杳冥冥兮以东行。\n\n河伯\n与女游兮九河，冲风起兮水扬波；\n乘水车兮荷盖，驾两龙兮骖螭；\n登昆仑兮四望，心飞扬兮浩荡；\n日将暮兮怅忘归，惟极浦兮寤怀；\n鱼鳞屋兮龙堂，紫贝阙兮珠宫；\n灵何惟兮水中；\n乘白鼋兮逐文鱼，与女游兮河之渚；\n流澌纷兮将来下；\n子交手兮东行，送美人兮南浦；\n波滔滔兮来迎，鱼鳞鳞兮媵予。\n\n山鬼\n若有人兮山之阿，被薜荔兮带女萝；\n既含睇兮又宜笑，子慕予兮善窈窕；\n乘赤豹兮从文狸，辛夷车兮结桂旗；\n被石兰兮带杜衡，折芳馨兮遗所思；\n余处幽篁兮终不见天，路险难兮独后来；\n表独立兮山之上，云容容兮而在下；\n杳冥冥兮羌昼晦，东风飘兮神灵雨；\n留灵修兮憺忘归，岁既晏兮孰华予；\n采三秀兮于山间，石磊磊兮葛蔓蔓；\n怨公子兮怅忘归，君思我兮不得闲；\n山中人兮芳杜若，饮石泉兮荫松柏；\n君思我兮然疑作；\n雷填填兮雨冥冥，猿啾啾兮狖夜鸣；\n风飒飒兮木萧萧，思公子兮徒离忧。\n\n国殇\n操吴戈兮被犀甲，车错毂兮短兵接；\n旌蔽日兮敌若云，矢交坠兮士争先；\n凌余阵兮躐余行，左骖殪兮右刃伤；\n霾两轮兮絷四马，援玉枹兮击鸣鼓；\n天时怼兮威灵怒，严杀尽兮弃原野；\n出不入兮往不反，平原忽兮路超远；\n带长剑兮挟秦弓，首身离兮心不惩；\n诚既勇兮又以武，终刚强兮不可凌；\n身既死兮神以灵，魂魄毅兮为鬼雄。\n\n礼魂\n成礼兮会鼓，传芭兮代舞；\n姱女倡兮容与；\n春兰兮秋菊，长无绝兮终古。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九歌' AND p.poem_author = '屈原';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白鹿洞二首·其一', '王贞白', '唐代', '读书不觉已春深，一寸光阴一寸金。(已春深 一作：春已深)\n不是道人来引笑，周情孔思正追寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白鹿洞二首·其一' AND p.poem_author = '王贞白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋兴八首·其一', '杜甫', '唐代', '玉露凋伤枫树林，巫山巫峡气萧森。\n江间波浪兼天涌，塞上风云接地阴。\n丛菊两开他日泪，孤舟一系故园心。\n寒衣处处催刀尺，白帝城高急暮砧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋兴八首·其一' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('螽斯', '佚名', '先秦', '螽斯羽，诜诜兮。宜尔子孙，振振兮。\n螽斯羽，薨薨兮。宜尔子孙，绳绳兮。\n螽斯羽，揖揖兮。宜尔子孙，蛰蛰兮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '螽斯' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·暖雨晴风初破冻', '李清照', '宋代', '暖雨晴风初破冻，柳眼梅腮，已觉春心动。酒意诗情谁与共？泪融残粉花钿重。\n乍试夹衫金缕缝，山枕斜欹，枕损钗头凤。独抱浓愁无好梦，夜阑犹剪灯花弄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·暖雨晴风初破冻' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诗经·国风·郑风', '佚名', '先秦', '风雨凄凄，鸡鸣喈喈。既见君子，云胡不夷。\n风雨潇潇，鸡鸣胶胶。既见君子，云胡不瘳。\n风雨如晦，鸡鸣不已。既见君子，云胡不喜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诗经·国风·郑风' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·辛苦最怜天上月', '纳兰性德', '清代', '辛苦最怜天上月，一昔如环，昔昔都成玦。若似月轮终皎洁，不辞冰雪为卿热。\n无那尘缘容易绝，燕子依然，软踏帘钩说。唱罢秋坟愁未歇，春丛认取双栖蝶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·辛苦最怜天上月' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉和令公绿野堂种花', '白居易', '唐代', '绿野堂开占物华，路人指道令公家。\n令公桃李满天下，何用堂前更种花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉和令公绿野堂种花' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古从军行', '李颀', '唐代', '白日登山望烽火，黄昏饮马傍交河。\n行人刁斗风沙暗，公主琵琶幽怨多。\n野云万里无城郭，雨雪纷纷连大漠。\n胡雁哀鸣夜夜飞，胡儿眼泪双双落。\n闻道玉门犹被遮，应将性命逐轻车。\n年年战骨埋荒外，空见蒲桃入汉家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古从军行' AND p.poem_author = '李颀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新竹', '郑燮', '清代', '新竹高于旧竹枝，全凭老干为扶持。\n下年再有新生者，十丈龙孙绕凤池。(下年 一作：明年)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新竹' AND p.poem_author = '郑燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('节妇吟·寄东平李司空师道', '张籍', '唐代', '君知妾有夫，赠妾双明珠。\n感君缠绵意，系在红罗襦。\n妾家高楼连苑起，良人执戟明光里。\n知君用心如日月，事夫誓拟同生死。\n还君明珠双泪垂，恨不相逢未嫁时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '节妇吟·寄东平李司空师道' AND p.poem_author = '张籍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙·细雨斜风作晓寒', '苏轼', '宋代', '元丰七年十二月二十四日，从泗州刘倩叔游南山\n\n细雨斜风作晓寒，淡烟疏柳媚晴滩。入淮清洛渐漫漫。\n雪沫乳花浮午盏，蓼茸蒿笋试春盘。人间有味是清欢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙·细雨斜风作晓寒' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咸阳城东楼 / 咸阳城西楼晚眺', '许浑', '唐代', '一上高城万里愁，蒹葭杨柳似汀洲。\n溪云初起日沉阁，山雨欲来风满楼。(沉 通：沈)\n鸟下绿芜秦苑夕，蝉鸣黄叶汉宫秋。\n行人莫问当年事，故国东来渭水流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咸阳城东楼 / 咸阳城西楼晚眺' AND p.poem_author = '许浑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长安春望', '卢纶', '唐代', '东风吹雨过青山，却望千门草色闲。\n家在梦中何日到，春生江上几人还？(春生 一作：春来)\n川原缭绕浮云外，宫阙参差落照间。\n谁念为儒逢世难，独将衰鬓客秦关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长安春望' AND p.poem_author = '卢纶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采莲曲二首', '王昌龄', '唐代', '吴姬越艳楚王妃，争弄莲舟水湿衣。\n来时浦口花迎入，采罢江头月送归。\n\n荷叶罗裙一色裁，芙蓉向脸两边开。\n乱入池中看不见，闻歌始觉有人来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采莲曲二首' AND p.poem_author = '王昌龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('城东早春', '杨巨源', '唐代', '诗家清景在新春，绿柳才黄半未匀。 \n若待上林花似锦，出门俱是看花人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '城东早春' AND p.poem_author = '杨巨源';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吊古战场文', '李华', '唐代', '浩浩乎，平沙无垠，夐不见人。河水萦带，群山纠纷。黯兮惨悴，风悲日曛。蓬断草枯，凛若霜晨。鸟飞不下，兽铤亡群。亭长告余曰：“此古战场也，常覆三军。往往鬼哭，天阴则闻。”伤心哉！秦欤汉欤？将近代欤？\n\n　　吾闻夫齐魏徭戍，荆韩召募。万里奔走，连年暴露。沙草晨牧，河冰夜渡。地阔天长，不知归路。寄身锋刃，腷臆谁愬？秦汉而还，多事四夷，中州耗斁，无世无之。古称戎夏，不抗王师。文教失宣，武臣用奇。奇兵有异于仁义，王道迂阔而莫为。呜呼噫嘻！\n\n　　吾想夫北风振漠，胡兵伺便。主将骄敌，期门受战。野竖旌旗，川回组练。法重心骇，威尊命贱。利镞穿骨，惊沙入面，主客相搏，山川震眩。声析江河，势崩雷电。至若穷阴凝闭，凛冽海隅，积雪没胫，坚冰在须。鸷鸟休巢，征马踟蹰。缯纩无温，堕指裂肤。当此苦寒，天假强胡，凭陵杀气，以相剪屠。径截辎重，横攻士卒。都尉新降，将军复没。尸踣巨港之岸，血满长城之窟。无贵无贱，同为枯骨。可胜言哉！鼓衰兮力竭，矢尽兮弦绝，白刃交兮宝刀折，两军蹙兮生死决。降矣哉，终身夷狄；战矣哉，暴骨沙砾。鸟无声兮山寂寂，夜正长兮风淅淅。魂魄结兮天沉沉，鬼神聚兮云幂幂。日光寒兮草短，月色苦兮霜白。伤心惨目，有如是耶！\n\n　　吾闻之：牧用赵卒，大破林胡，开地千里，遁逃匈奴。汉倾天下，财殚力痡。任人而已，岂在多乎！周逐猃狁，北至太原。既城朔方，全师而还。饮至策勋，和乐且闲。穆穆棣棣，君臣之间。秦起长城，竟海为关。荼毒生民，万里朱殷。汉击匈奴，虽得阴山，枕骸徧野，功不补患。\n\n　　苍苍蒸民，谁无父母？提携捧负，畏其不寿。谁无兄弟？如足如手。谁无夫妇？如宾如友。生也何恩，杀之何咎？其存其没，家莫闻知。人或有言，将信将疑。悁悁心目，寤寐见之。布奠倾觞，哭望天涯。天地为愁，草木凄悲。吊祭不至，精魂无依。必有凶年，人其流离。呜呼噫嘻！时耶命耶？从古如斯！为之奈何？守在四夷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吊古战场文' AND p.poem_author = '李华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诉衷情·夜来沉醉卸妆迟', '李清照', '宋代', '夜来沉醉卸妆迟，梅萼插残枝。酒醒熏破春睡，梦远不成归。\n人悄悄，月依依，翠帘垂。更挼残蕊，更捻余香，更得些时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诉衷情·夜来沉醉卸妆迟' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('千秋岁·数声鶗鴂', '张先', '宋代', '数声鶗鴂，又报芳菲歇。惜春更把残红折。雨轻风色暴，梅子青时节。永丰柳，无人尽日花飞雪。\n莫把幺弦拨，怨极弦能说。天不老，情难绝。心似双丝网，中有千千结。夜过也，东窗未白凝残月。(凝残月 一作：孤灯灭)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '千秋岁·数声鶗鴂' AND p.poem_author = '张先';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三台·清明应制', '万俟咏', '宋代', '见梨花初带夜月，海棠半含朝雨。内苑春、不禁过青门，御沟涨、潜通南浦。东风静、细柳垂金缕。望凤阙、非烟非雾。好时代、朝野多欢，遍九陌、太平箫鼓。 \n乍莺儿百啭断续，燕子飞来飞去。近绿水、台榭映秋千，斗草聚、双双游女。饧香更、酒冷踏青路。会暗识、夭桃朱户。向晚骤、宝马雕鞍，醉襟惹、乱花飞絮。 \n正轻寒轻暖漏永，半阴半晴云暮。禁火天、已是试新妆，岁华到、三分佳处。清明看、汉宫传蜡炬。散翠烟、飞入槐府。敛兵卫、阊阖门开，住传宣、又还休务。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三台·清明应制' AND p.poem_author = '万俟咏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('曲江二首', '杜甫', '唐代', '一片花飞减却春，风飘万点正愁人。\n且看欲尽花经眼，莫厌伤多酒入唇。\n江上小堂巢翡翠，苑边高冢卧麒麟。\n细推物理须行乐，何用浮荣绊此身。\n\n朝回日日典春衣，每日江头尽醉归。\n酒债寻常行处有，人生七十古来稀。\n穿花蛱蝶深深见，点水蜻蜓款款飞。\n传语风光共流转，暂时相赏莫相违。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '曲江二首' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('代悲白头翁', '刘希夷', '唐代', '洛阳城东桃李花，飞来飞去落谁家？\n洛阳女儿惜颜色，坐见落花长叹息。\n今年花落颜色改，明年花开复谁在？\n已见松柏摧为薪，更闻桑田变成海。\n古人无复洛城东，今人还对落花风。\n年年岁岁花相似，岁岁年年人不同。\n寄言全盛红颜子，应怜半死白头翁。\n此翁白头真可怜，伊昔红颜美少年。\n公子王孙芳树下，清歌妙舞落花前。\n光禄池台文锦绣，将军楼阁画神仙。\n一朝卧病无相识，三春行乐在谁边？\n宛转蛾眉能几时？须臾鹤发乱如丝。\n但看古来歌舞地，唯有黄昏鸟雀悲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '代悲白头翁' AND p.poem_author = '刘希夷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆江南·多少恨', '李煜', '五代', '多少恨，昨夜梦魂中。还似旧时游上苑，车如流水马如龙。花月正春风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆江南·多少恨' AND p.poem_author = '李煜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄黄几复', '黄庭坚', '宋代', '我居北海君南海，寄雁传书谢不能。\n桃李春风一杯酒，江湖夜雨十年灯。\n持家但有四立壁，治病不蕲三折肱。\n想见读书头已白，隔溪猿哭瘴溪藤。(想见 一作：想得)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄黄几复' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('踏莎行·候馆梅残', '欧阳修', '宋代', '候馆梅残，溪桥柳细。草薰风暖摇征辔。离愁渐远渐无穷，迢迢不断如春水。 \n寸寸柔肠，盈盈粉泪。楼高莫近危阑倚。平芜尽处是春山，行人更在春山外。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '踏莎行·候馆梅残' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·雪照山城玉指寒', '刘著', '宋代', '雪照山城玉指寒，一声羌管怨楼间。江南几度梅花发，人在天涯鬓已斑。\n星点点，月团团。倒流河汉入杯盘。翰林风月三千首，寄与吴姬忍泪看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·雪照山城玉指寒' AND p.poem_author = '刘著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('扬子江', '文天祥', '宋代', '几日随风北海游，回从扬子大江头。\n臣心一片磁针石，不指南方不肯休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '扬子江' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·鄘风·相鼠', '佚名', '先秦', '相鼠有皮，人而无仪！人而无仪，不死何为？\n相鼠有齿，人而无止！人而无止，不死何俟？\n相鼠有体，人而无礼，人而无礼！胡不遄死？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·鄘风·相鼠' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('北风行', '李白', '唐代', '烛龙栖寒门，光曜犹旦开。\n日月照之何不及此？惟有北风号怒天上来。\n燕山雪花大如席，片片吹落轩辕台。\n幽州思妇十二月，停歌罢笑双蛾摧。\n倚门望行人，念君长城苦寒良可哀。\n别时提剑救边去，遗此虎文金鞞靫。\n中有一双白羽箭，蜘蛛结网生尘埃。\n箭空在，人今战死不复回。\n不忍见此物，焚之已成灰。\n黄河捧土尚可塞，北风雨雪恨难裁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '北风行' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山中与裴秀才迪书', '王维', '唐代', '近腊月下，景气和畅，故山殊可过。足下方温经，猥不敢相烦，辄便往山中，憩感配寺，与山僧饭讫而去。\n\n　　北涉玄灞，清月映郭。夜登华子冈，辋水沦涟，与月上下。寒山远火，明灭林外。深巷寒犬，吠声如豹。村墟夜舂，复与疏钟相间。此时独坐，僮仆静默，多思曩昔，携手赋诗，步仄径，临清流也。\n\n　　当待春中，草木蔓发，春山可望，轻鲦出水，白鸥矫翼，露湿青皋，麦陇朝雊，斯之不远，倘能从我游乎？非子天机清妙者，岂能以此不急之务相邀。然是中有深趣矣！无忽。因驮黄檗人往，不一，山中人王维白。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '山中与裴秀才迪书' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏怀古迹五首·其三', '杜甫', '唐代', '群山万壑赴荆门，生长明妃尚有村。\n一去紫台连朔漠，独留青冢向黄昏。\n画图省识春风面，环佩空归夜月魂。(夜月 一作：月夜; 环\'佩\', 一作：环\'珮\')\n千载琵琶作胡语，分明怨恨曲中论。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏怀古迹五首·其三' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('燕歌行', '高适', '唐代', '开元二十六年，客有从御史大夫张公出塞而还者；作《燕歌行》以示适，感征戍之事，因而和焉。\n\n汉家烟尘在东北，汉将辞家破残贼。\n男儿本自重横行，天子非常赐颜色。\n摐金伐鼓下榆关，旌旆逶迤碣石间。\n校尉羽书飞瀚海，单于猎火照狼山。\n山川萧条极边土，胡骑凭陵杂风雨。\n战士军前半死生，美人帐下犹歌舞。\n大漠穷秋塞草腓，孤城落日斗兵稀。\n身当恩遇常轻敌，力尽关山未解围。(常轻敌 一作：恒轻敌)\n铁衣远戍辛勤久，玉箸应啼别离后。\n少妇城南欲断肠，征人蓟北空回首。\n边庭飘飖那可度，绝域苍茫更何有。(飘飖 一作：飘飘)\n杀气三时作阵云，寒声一夜传刁斗。\n相看白刃血纷纷，死节从来岂顾勋。\n君不见沙场征战苦，至今犹忆李将军。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '燕歌行' AND p.poem_author = '高适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('除夜 / 巴山道中除夜书怀', '崔涂', '唐代', '迢递三巴路，羁危万里身。\n乱山残雪夜，孤烛异乡人。\n渐与骨肉远，转于僮仆亲。\n那堪正飘泊，明日岁华新。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '除夜 / 巴山道中除夜书怀' AND p.poem_author = '崔涂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉阶怨', '李白', '唐代', '玉阶生白露，夜久侵罗袜。\n却下水晶帘，玲珑望秋月。(水晶 一作 水精)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉阶怨' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题弟侄书堂', '杜荀鹤', '唐代', '何事居穷道不穷，乱时还与静时同。\n家山虽在干戈地，弟侄常修礼乐风。\n窗竹影摇书案上，野泉声入砚池中。\n少年辛苦终身事，莫向光阴惰寸功。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题弟侄书堂' AND p.poem_author = '杜荀鹤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桂枝香·金陵怀古', '王安石', '宋代', '登临送目，正故国晚秋，天气初肃。千里澄江似练，翠峰如簇。归帆去棹残阳里，背西风，酒旗斜矗。彩舟云淡，星河鹭起，画图难足。(归帆 一作：征帆)\n念往昔，繁华竞逐，叹门外楼头，悲恨相续。千古凭高对此，谩嗟荣辱。六朝旧事随流水，但寒烟衰草凝绿。至今商女，时时犹唱，后庭遗曲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桂枝香·金陵怀古' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和子由渑池怀旧', '苏轼', '宋代', '人生到处知何似，应似飞鸿踏雪泥。\n泥上偶然留指爪，鸿飞那复计东西。\n老僧已死成新塔，坏壁无由见旧题。\n往日崎岖还记否，路长人困蹇驴嘶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和子由渑池怀旧' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('太常引·建康中秋夜为吕叔潜赋', '辛弃疾', '宋代', '一轮秋影转金波，飞镜又重磨。把酒问姮娥：被白发、欺人奈何？\n乘风好去，长空万里，直下看山河。斫去桂婆娑，人道是、清光更多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '太常引·建康中秋夜为吕叔潜赋' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郑伯克段于鄢', '左丘明', '先秦', '初，郑武公娶于申，曰武姜，生庄公及共叔段。庄公寤生，惊姜氏，故名曰寤生，遂恶之。爱共叔段，欲立之。亟请于武公，公弗许。\n\n　　及庄公即位，为之请制。公曰：“制，岩邑也，虢叔死焉。佗邑唯命。”请京，使居之，谓之京城大叔。祭仲曰：“都城过百雉，国之害也。先王之制：大都不过参国之一，中五之一，小九之一。今京不度，非制也，君将不堪。”公曰：“姜氏欲之，焉辟害？”对曰：“姜氏何厌之有！不如早为之所，无使滋蔓，蔓难图也。蔓草犹不可除，况君之宠弟乎！”公曰：“多行不义，必自毙，子姑待之。”\n\n　　既而大叔命西鄙北鄙贰于己。公子吕曰：“国不堪贰，君将若之何？欲与大叔，臣请事之；若弗与，则请除之。无生民心。”公曰：“无庸，将自及。”大叔又收贰以为己邑，至于廪延。子封曰：“可矣，厚将得众。”公曰：“不义，不暱，厚将崩。”\n\n　　大叔完聚，缮甲兵，具卒乘，将袭郑。夫人将启之。公闻其期，曰：“可矣！”命子封帅车二百乘以伐京。京叛大叔段，段入于鄢，公伐诸鄢。五月辛丑，大叔出奔共。\n\n　　书曰：“郑伯克段于鄢。”段不弟，故不言弟；如二君，故曰克；称郑伯，讥失教也；谓之郑志。不言出奔，难之也。\n\n　　遂寘姜氏于城颍，而誓之曰：“不及黄泉，无相见也。”既而悔之。颍考叔为颍谷封人，闻之，有献于公，公赐之食，食舍肉。公问之，对曰：“小人有母，皆尝小人之食矣，未尝君之羹，请以遗之。”公曰：“尔有母遗，繄我独无！”颍考叔曰：“敢问何谓也？”公语之故，且告之悔。对曰：“君何患焉？若阙地及泉，隧而相见，其谁曰不然？”公从之。公入而赋：“大隧之中，其乐也融融！”姜出而赋：“大隧之外，其乐也洩洩。”遂为母子如初。\n\n　　君子曰：“颍考叔，纯孝也，爱其母，施及庄公。《诗》曰：‘孝子不匮，永锡尔类。’其是之谓乎！”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郑伯克段于鄢' AND p.poem_author = '左丘明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·邶风·绿衣', '佚名', '先秦', '绿兮衣兮，绿衣黄里。心之忧矣，曷维其已？(黄里 一作：黄裹)\n绿兮衣兮，绿衣黄裳。心之忧矣，曷维其亡？\n绿兮丝兮，女所治兮。我思古人，俾无訧兮。\n絺兮绤兮，凄其以风。我思古人，实获我心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·邶风·绿衣' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('铁杵磨针', '郑之珍', '明代', '磨针溪，在眉州象耳山下。世传李太白读书山中，未成，弃去。过小溪，逢老媪方磨铁杵，问之，曰：“欲作针。”太白感其意，还卒业。媪自言姓武。今溪旁有武氏岩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '铁杵磨针' AND p.poem_author = '郑之珍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋', '司空图', '唐代', '闲吟秋景外，万事觉悠悠。\n此夜若无月，一年虚过秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋' AND p.poem_author = '司空图';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('扁鹊见蔡桓公', '韩非', '先秦', '扁鹊见蔡桓公，立有间，扁鹊曰：“君有疾在腠理，不治将恐深。”桓侯曰：“寡人无疾。”扁鹊出，桓侯曰：“医之好治不病以为功！”\n\n　　居十日，扁鹊复见，曰：“君之病在肌肤，不治将益深。”桓侯不应。扁鹊出，桓侯又不悦。\n\n　　居十日，扁鹊复见，曰：“君之病在肠胃，不治将益深。”桓侯又不应。扁鹊出，桓侯又不悦。\n\n　　居十日，扁鹊望桓侯而还走。桓侯故使人问之，扁鹊曰：“疾在腠理，汤熨之所及也；在肌肤，针石之所及也；在肠胃，火齐之所及也；在骨髓，司命之所属，无奈何也。今在骨髓，臣是以无请也。”\n\n　　居五日，桓侯体痛，使人索扁鹊，已逃秦矣。桓侯遂死。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '扁鹊见蔡桓公' AND p.poem_author = '韩非';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('灞上秋居', '马戴', '唐代', '灞原风雨定，晚见雁行频。\n落叶他乡树，寒灯独夜人。\n空园白露滴，孤壁野僧邻。\n寄卧郊扉久，何年致此身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '灞上秋居' AND p.poem_author = '马戴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('硕人', '佚名', '先秦', '硕人其颀，衣锦褧衣。齐侯之子，卫侯之妻。东宫之妹，邢侯之姨，谭公维私。\n手如柔荑，肤如凝脂，领如蝤蛴，齿如瓠犀，螓首蛾眉，巧笑倩兮，美目盼兮。\n硕人敖敖，说于农郊。四牡有骄，朱幩镳镳。翟茀以朝。大夫夙退，无使君劳。\n河水洋洋，北流活活。施罛濊濊，鳣鲔发发。葭菼揭揭，庶姜孽孽，庶士有朅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '硕人' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西塞山怀古', '刘禹锡', '唐代', '王濬楼船下益州，金陵王气黯然收。\n千寻铁锁沉江底，一片降幡出石头。\n人世几回伤往事，山形依旧枕寒流。\n今逢四海为家日，故垒萧萧芦荻秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西塞山怀古' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晏子谏杀烛邹', '刘向 编', '先秦', '齐景公好弋，使烛邹主鸟而亡之。公怒，诏吏欲杀之。晏子曰： “烛邹有罪三，请数之以其罪杀之。”公曰：“可。”于是召而数之公前，曰：“烛邹，汝为吾君主鸟而亡之，是罪一也；使吾君以鸟之故杀人，是罪二也；使诸侯闻之以吾君重鸟而轻士 ，是罪三也。数烛邹罪已毕，请杀之 。”公曰：“勿杀！寡人闻命矣。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '晏子谏杀烛邹' AND p.poem_author = '刘向 编';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游子吟', '李益', '唐代', '女羞夫婿薄，客耻主人贱。\n遭遇同众流，低回愧相见。\n君非青铜镜，何事空照面。\n莫以衣上尘，不谓心如练。\n人生当荣盛，待士勿言倦。\n君看白日驰，何异弦上箭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游子吟' AND p.poem_author = '李益';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金错刀行', '陆游', '宋代', '黄金错刀白玉装，夜穿窗扉出光芒。\n丈夫五十功未立，提刀独立顾八荒。\n京华结交尽奇士，意气相期共生死。\n千年史册耻无名，一片丹心报天子。\n尔来从军天汉滨，南山晓雪玉嶙峋。\n呜呼！楚虽三户能亡秦，岂有堂堂中国空无人！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金错刀行' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小松', '杜荀鹤', '唐代', '自小刺头深草里，而今渐觉出蓬蒿。 \n时人不识凌云木，直待凌云始道高。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小松' AND p.poem_author = '杜荀鹤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('少年游·离多最是', '晏几道', '宋代', '离多最是，东西流水，终解两相逢。\n浅情终似，行云无定，犹到梦魂中。\n可怜人意，薄于云水，佳会更难重。\n细想从来，断肠多处，不与今番同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '少年游·离多最是' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·邶风·柏舟', '佚名', '先秦', '泛彼柏舟，亦泛其流。耿耿不寐，如有隐忧。微我无酒，以敖以游。\n我心匪鉴，不可以茹。亦有兄弟，不可以据。薄言往愬，逢彼之怒。\n我心匪石，不可转也。我心匪席，不可卷也。威仪棣棣，不可选也。\n忧心悄悄，愠于群小。觏闵既多，受侮不少。静言思之，寤辟有摽。\n日居月诸，胡迭而微？心之忧矣，如匪浣衣。静言思之，不能奋飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·邶风·柏舟' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐·红笺小字', '晏殊', '宋代', '红笺小字。说尽平生意。鸿雁在云鱼在水。惆怅此情难寄。 \n斜阳独倚西楼。遥山恰对帘钩。人面不知何处，绿波依旧东流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐·红笺小字' AND p.poem_author = '晏殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('离思五首', '元稹', '唐代', '自爱残妆晓镜中，环钗漫篸绿丝丛。\n须臾日射胭脂颊，一朵红苏旋欲融。\n\n山泉散漫绕阶流，万树桃花映小楼。\n闲读道书慵未起，水晶帘下看梳头。\n\n红罗著压逐时新，吉了花纱嫩麴尘。\n第一莫嫌材地弱，些些纰缦最宜人。\n\n曾经沧海难为水，除却巫山不是云。\n取次花丛懒回顾，半缘修道半缘君。\n\n寻常百种花齐发，偏摘梨花与白人。\n今日江头两三树，可怜和叶度残春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '离思五首' AND p.poem_author = '元稹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日忆李白', '杜甫', '唐代', '白也诗无敌，飘然思不群。\n清新庾开府，俊逸鲍参军。\n渭北春天树，江东日暮云。\n何时一樽酒，重与细论文。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日忆李白' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋声赋', '欧阳修', '宋代', '欧阳子方夜读书，闻有声自西南来者，悚然而听之，曰：“异哉！”初淅沥以萧飒，忽奔腾而砰湃，如波涛夜惊，风雨骤至。其触于物也，鏦鏦铮铮，金铁皆鸣；又如赴敌之兵，衔枚疾走，不闻号令，但闻人马之行声。予谓童子：“此何声也？汝出视之。”童子曰：“星月皎洁，明河在天，四无人声，声在树间。”\n\n　　余曰：“噫嘻悲哉！此秋声也，胡为而来哉？盖夫秋之为状也：其色惨淡，烟霏云敛；其容清明，天高日晶；其气栗冽，砭人肌骨；其意萧条，山川寂寥。故其为声也，凄凄切切，呼号愤发。丰草绿缛而争茂，佳木葱茏而可悦；草拂之而色变，木遭之而叶脱。其所以摧败零落者，乃其一气之余烈。夫秋，刑官也，于时为阴；又兵象也，于行用金，是谓天地之义气，常以肃杀而为心。天之于物，春生秋实，故其在乐也，商声主西方之音，夷则为七月之律。商，伤也，物既老而悲伤；夷，戮也，物过盛而当杀。” (余曰 一作：予曰)\n\n　　“嗟乎！草木无情，有时飘零。人为动物，惟物之灵；百忧感其心，万事劳其形；有动于中，必摇其精。而况思其力之所不及，忧其智之所不能；宜其渥然丹者为槁木，黟然黑者为星星。奈何以非金石之质，欲与草木而争荣？念谁为之戕贼，亦何恨乎秋声！”\n\n　　童子莫对，垂头而睡。但闻四壁虫声唧唧，如助予之叹息。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋声赋' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自嘲', '鲁迅', '近代', '运交华盖欲何求，未敢翻身已碰头。\n破帽遮颜过闹市，漏船载酒泛中流。\n横眉冷对千夫指，俯首甘为孺子牛。\n躲进小楼成一统，管他冬夏与春秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自嘲' AND p.poem_author = '鲁迅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('为学一首示子侄', '彭端淑', '清代', '天下事有难易乎？为之，则难者亦易矣；不为，则易者亦难矣。人之为学有难易乎？学之，则难者亦易矣；不学，则易者亦难矣。\n\n　　吾资之昏，不逮人也，吾材之庸，不逮人也；旦旦而学之，久而不怠焉，迄乎成，而亦不知其昏与庸也。吾资之聪，倍人也，吾材之敏，倍人也；屏弃而不用，其与昏与庸无以异也。圣人之道，卒于鲁也传之。然则昏庸聪敏之用，岂有常哉？\n\n　　蜀之鄙有二僧：其一贫，其一富。贫者语于富者曰：“吾欲之南海，何如？”富者曰：“子何恃而往？”曰：“吾一瓶一钵足矣。”富者曰：“吾数年来欲买舟而下，犹未能也。子何恃而往！”越明年，贫者自南海还，以告富者，富者有惭色。\n\n　　西蜀之去南海，不知几千里也，僧富者不能至而贫者至焉。人之立志，顾不如蜀鄙之僧哉?是故聪与敏，可恃而不可恃也；自恃其聪与敏而不学者，自败者也。昏与庸，可限而不可限也；不自限其昏与庸，而力学不倦者，自力者也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '为学一首示子侄' AND p.poem_author = '彭端淑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蚕妇', '张俞', '宋代', '昨日入城市，归来泪满巾。\n遍身罗绮者，不是养蚕人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蚕妇' AND p.poem_author = '张俞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和董传留别', '苏轼', '宋代', '粗缯大布裹生涯，腹有诗书气自华。\n厌伴老儒烹瓠叶，强随举子踏槐花。\n囊空不办寻春马，眼乱行看择婿车。\n得意犹堪夸世俗，诏黄新湿字如鸦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和董传留别' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·郑风·野有蔓草', '佚名', '先秦', '野有蔓草，零露漙兮。有美一人，清扬婉兮。邂逅相遇，适我愿兮。\n野有蔓草，零露瀼瀼。有美一人，婉如清扬。邂逅相遇，与子偕臧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·郑风·野有蔓草' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汴京元夕', '李梦阳', '明代', '中山孺子倚新妆，郑女燕姬独擅场。\n齐唱宪王春乐府，金梁桥外月如霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汴京元夕' AND p.poem_author = '李梦阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('共工怒触不周山', '佚名', '未知', '昔者，共工与颛顼争为帝，怒而触不周之山，天柱折，地维绝。天倾西北，故日月星辰移焉；地不满东南，故水潦尘埃归焉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '共工怒触不周山' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湘春夜月·近清明', '黄孝迈', '宋代', '近清明。翠禽枝上消魂。可惜一片清歌，都付与黄昏。欲共柳花低诉，怕柳花轻薄，不解伤春。念楚乡旅宿，柔情别绪，谁与温存。 \n空樽夜泣，青山不语，残月当门。翠玉楼前，惟是有、一波湘水，摇荡湘云。天长梦短，问甚时、重见桃根。这次第，算人间没个并刀，剪断心上愁痕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湘春夜月·近清明' AND p.poem_author = '黄孝迈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九歌·湘夫人', '屈原', '先秦', '帝子降兮北渚，目眇眇兮愁予。\n袅袅兮秋风，洞庭波兮木叶下。(袅袅 一作：渺渺)\n登白薠兮骋望，与佳期兮夕张。\n鸟何萃兮苹中，罾何为兮木上。\n沅有芷兮澧有兰，思公子兮未敢言。\n荒忽兮远望，观流水兮潺湲。\n麋何食兮庭中？蛟何为兮水裔？\n朝驰余马兮江皋，夕济兮西澨。\n闻佳人兮召予，将腾驾兮偕逝。\n筑室兮水中，葺之兮荷盖；\n荪壁兮紫坛，播芳椒兮成堂；\n桂栋兮兰橑，辛夷楣兮药房；\n罔薜荔兮为帷，擗蕙櫋兮既张；\n白玉兮为镇，疏石兰兮为芳；\n芷葺兮荷屋，缭之兮杜衡。\n合百草兮实庭，建芳馨兮庑门。\n九嶷缤兮并迎，灵之来兮如云。\n捐余袂兮江中，遗余褋兮澧浦。\n搴汀洲兮杜若，将以遗兮远者；\n时不可兮骤得，聊逍遥兮容与！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九歌·湘夫人' AND p.poem_author = '屈原';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题诗后', '贾岛', '唐代', '两句三年得，一吟双泪流。\n知音如不赏，归卧故山秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题诗后' AND p.poem_author = '贾岛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('破阵子·掷地刘郎玉斗', '辛弃疾', '宋代', '为范南伯寿。时南伯为张南轩辟宰泸溪，南伯迟迟未行。因作此词以勉之。\n\n掷地刘郎玉斗，挂帆西子扁舟。千古风流今在此，万里功名莫放休。君王三百州。\n燕雀岂知鸿鹄，貂蝉元出兜鍪。却笑泸溪如斗大，肯把牛刀试手不？寿君双玉瓯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '破阵子·掷地刘郎玉斗' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('画鸡', '唐寅', '明代', '头上红冠不用裁，满身雪白走将来。\n平生不敢轻言语，一叫千门万户开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '画鸡' AND p.poem_author = '唐寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贺新郎·甚矣吾衰矣', '辛弃疾', '宋代', '邑中园亭，仆皆为赋此词。一日，独坐停云，水声山色，竞来相娱。意溪山欲援例者，遂作数语，庶几仿佛渊明思亲友之意云。\n\n甚矣吾衰矣。怅平生、交游零落，只今馀几！白发空垂三千丈，一笑人间万事。问何物、能令公喜？我见青山多妩媚，料青山见我应如是。情与貌，略相似。\n一尊搔首东窗里。想渊明《停云》诗就，此时风味。江左沉酣求名者，岂识浊醪妙理。回首叫、云飞风起。不恨古人吾不见，恨古人不见吾狂耳。知我者，二三子。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贺新郎·甚矣吾衰矣' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读山海经·其十', '陶渊明', '魏晋', '精卫衔微木，将以填沧海。\n刑天舞干戚，猛志固常在。\n同物既无虑，化去不复悔。\n徒设在昔心，良辰讵可待。(辰 一作：晨)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读山海经·其十' AND p.poem_author = '陶渊明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('对雪', '杜甫', '唐代', '战哭多新鬼，愁吟独老翁。\n乱云低薄暮，急雪舞回风。\n瓢弃尊无绿，炉存火似红。\n数州消息断，愁坐正书空。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '对雪' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过华清宫绝句三首', '杜牧', '唐代', '长安回望绣成堆，山顶千门次第开。\n一骑红尘妃子笑，无人知是荔枝来。\n\n新丰绿树起黄埃，数骑渔阳探使回。\n霓裳一曲千峰上，舞破中原始下来。\n\n万国笙歌醉太平，倚天楼殿月分明。\n云中乱拍禄山舞，风过重峦下笑声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过华清宫绝句三首' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦微之', '白居易', '唐代', '夜来携手梦同游，晨起盈巾泪莫收。\n漳浦老身三度病，咸阳宿草八回秋。\n君埋泉下泥销骨，我寄人间雪满头。\n阿卫韩郎相次去，夜台茫昧得知不？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梦微之' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赏牡丹', '刘禹锡', '唐代', '庭前芍药妖无格，池上芙蕖净少情。\n唯有牡丹真国色，花开时节动京城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赏牡丹' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辋川闲居赠裴秀才迪', '王维', '唐代', '寒山转苍翠，秋水日潺湲。\n倚杖柴门外，临风听暮蝉。\n渡头馀落日，墟里上孤烟。(馀 一作 余)\n复值接舆醉，狂歌五柳前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辋川闲居赠裴秀才迪' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('邯郸冬至夜思家', '白居易', '唐代', '邯郸驿里逢冬至，抱膝灯前影伴身。 \n想得家中夜深坐，还应说着远行人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '邯郸冬至夜思家' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水仙子·夜雨', '徐再思', '元代', '一声梧叶一声秋，一点芭蕉一点愁，三更归梦三更后。落灯花，棋未收，叹新丰逆旅淹留。枕上十年事，江南二老忧，都到心头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水仙子·夜雨' AND p.poem_author = '徐再思';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜算子·不是爱风尘', '严蕊', '宋代', '不是爱风尘，似被前缘误。花落花开自有时，总赖东君主。\n去也终须去，住也如何住！若得山花插满头，莫问奴归处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜算子·不是爱风尘' AND p.poem_author = '严蕊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏蝉 / 在狱咏蝉', '骆宾王', '唐代', '西陆蝉声唱，南冠客思深。(客思深 一作：客思侵)\n不堪玄鬓影，来对白头吟。(不堪 一作：那堪)\n露重飞难进，风多响易沉。\n无人信高洁，谁为表予心？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏蝉 / 在狱咏蝉' AND p.poem_author = '骆宾王';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·周南·芣苢', '佚名', '先秦', '采采芣苢，薄言采之。\n采采芣苢，薄言有之。\n采采芣苢，薄言掇之。\n采采芣苢，薄言捋之。\n采采芣苢，薄言袺之。\n采采芣苢，薄言襭之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·周南·芣苢' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卖柑者言', '刘基', '明代', '杭有卖果者，善藏柑，涉寒暑不溃。出之烨然，玉质而金色。置于市，贾十倍，人争鬻之。\n\n　　予贸得其一，剖之，如有烟扑口鼻，视其中，则干若败絮。予怪而问之曰：“若所市于人者，将以实笾豆，奉祭祀，供宾客乎？将炫外以惑愚瞽也？甚矣哉，为欺也！”\n\n　　卖者笑曰：“吾业是有年矣，吾赖是以食吾躯。吾售之，人取之，未尝有言，而独不足子所乎？世之为欺者不寡矣，而独我也乎？吾子未之思也。\n\n　　今夫佩虎符、坐皋比者，洸洸乎干城之具也，果能授孙、吴之略耶？ 峨大冠、 拖长绅者，昂昂乎庙堂之器也，果能建伊、皋之业耶？盗起而不知御，民困而不知救，吏奸而不知禁，法斁而不知理，坐糜廪粟而不知耻。观其坐高堂，骑大马，醉醇醴而饫肥鲜者，孰不巍巍乎可畏，赫赫乎可象也？又何往而不金玉其外，败絮其中也哉？今子是之不察，而以察吾柑！”\n\n　　予默默无以应。退而思其言，类东方生滑稽之流。岂其愤世疾邪者耶？而托于柑以讽耶？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卖柑者言' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无题·飒飒东风细雨来', '李商隐', '唐代', '飒飒东风细雨来，芙蓉塘外有轻雷。\n金蟾啮锁烧香入，玉虎牵丝汲井回。\n贾氏窥帘韩掾少，宓妃留枕魏王才。\n春心莫共花争发，一寸相思一寸灰！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无题·飒飒东风细雨来' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠别二首', '杜牧', '唐代', '娉娉袅袅十三余，豆蔻梢头二月初。\n春风十里扬州路，卷上珠帘总不如。\n\n多情却似总无情，唯觉樽前笑不成。\n蜡烛有心还惜别，替人垂泪到天明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠别二首' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·邶风·式微', '佚名', '先秦', '式微，式微，胡不归？微君之故，胡为乎中露！\n式微，式微，胡不归？微君之躬，胡为乎泥中！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·邶风·式微' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诉衷情·永夜抛人何处去', '顾夐', '唐代', '永夜抛人何处去？绝来音。香阁掩，眉敛，月将沉。\n争忍不相寻？怨孤衾。换我心，为你心，始知相忆深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诉衷情·永夜抛人何处去' AND p.poem_author = '顾夐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读孟尝君传', '王安石', '宋代', '世皆称孟尝君能得士，士以故归之，而卒赖其力以脱于虎豹之秦。嗟乎！孟尝君特鸡鸣狗盗之雄耳，岂足以言得士？不然，擅齐之强，得一士焉，宜可以南面而制秦，尚何取鸡鸣狗盗之力哉？夫鸡鸣狗盗之出其门，此士之所以不至也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读孟尝君传' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归园田居·其二', '陶渊明', '魏晋', '野外罕人事，穷巷寡轮鞅。\n白日掩荆扉，虚室绝尘想。\n时复墟曲中，披草共来往。(墟曲中 一作：墟曲人)\n相见无杂言，但道桑麻长。\n桑麻日已长，我土日已广。\n常恐霜霰至，零落同草莽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归园田居·其二' AND p.poem_author = '陶渊明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪', '郑谷', '唐代', '暖戏烟芜锦翼齐，品流应得近山鸡。\n雨昏青草湖边过，花落黄陵庙里啼。\n游子乍闻征袖湿，佳人才唱翠眉低。\n相呼相应湘江阔，苦竹丛深日向西。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪' AND p.poem_author = '郑谷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望驿台', '白居易', '唐代', '靖安宅里当窗柳，望驿台前扑地花。(扑地花 一作：铺地花)\n两处春光同日尽，居人思客客思家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望驿台' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋思', '陆游', '宋代', '利欲驱人万火牛，江湖浪迹一沙鸥。\n日长似岁闲方觉，事大如天醉亦休。\n砧杵敲残深巷月，井梧摇落故园秋。\n欲舒老眼无高处，安得元龙百尺楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋思' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庐山谣寄卢侍御虚舟', '李白', '唐代', '我本楚狂人，凤歌笑孔丘。\n手持绿玉杖，朝别黄鹤楼。\n五岳寻仙不辞远，一生好入名山游。\n庐山秀出南斗傍，屏风九叠云锦张。\n影落明湖青黛光，金阙前开二峰长，银河倒挂三石梁。\n香炉瀑布遥相望，回崖沓嶂凌苍苍。\n翠影红霞映朝日，鸟飞不到吴天长。\n登高壮观天地间，大江茫茫去不还。\n黄云万里动风色，白波九道流雪山。\n好为庐山谣，兴因庐山发。\n闲窥石镜清我心，谢公行处苍苔没。\n早服还丹无世情，琴心三叠道初成。\n遥见仙人彩云里，手把芙蓉朝玉京。\n先期汗漫九垓上，愿接卢敖游太清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庐山谣寄卢侍御虚舟' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三人成虎', '刘向', '两汉', '庞葱与太子质于邯郸，谓魏王曰：‘今一人言市有虎，王信之乎？’王曰：‘否。’‘二人言市有虎，王信之乎？’王曰：‘寡人疑之矣。’‘三人言市有虎，王信之乎？’王曰：‘寡人信之矣。’庞葱曰：‘夫市之无虎明矣，然而三人言而成虎。今邯郸去大梁也远于市，而议臣者过于三人，愿王察之。’王曰：‘寡人自为知。’于是辞行，而谗言先至。后太子罢质，果不得见。(庞葱 一作：庞恭)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '三人成虎' AND p.poem_author = '刘向';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹊踏枝·谁道闲情抛掷久', '冯延巳', '五代', '谁道闲情抛掷久？每到春来，惆怅还依旧。日日花前常病酒，敢辞镜里朱颜瘦。(敢辞 一作：不辞)\n河畔青芜堤上柳，为问新愁，何事年年有？独立小桥风满袖，平林新月人归后。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹊踏枝·谁道闲情抛掷久' AND p.poem_author = '冯延巳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('海棠春·已未清明对海棠有赋', '吴潜', '宋代', '海棠亭午沾疏雨。便一饷、胭脂尽吐。老去惜花心，相对花无语。 \n羽书万里飞来处。报扫荡、狐嗥兔舞。濯锦古江头，飞景还如许。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '海棠春·已未清明对海棠有赋' AND p.poem_author = '吴潜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('遣悲怀三首·其二', '元稹', '唐代', '昔日戏言身后意，今朝都到眼前来。(身后意 一作：身后事)\n衣裳已施行看尽，针线犹存未忍开。\n尚想旧情怜婢仆，也曾因梦送钱财。\n诚知此恨人人有，贫贱夫妻百事哀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '遣悲怀三首·其二' AND p.poem_author = '元稹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怨', '冯小青', '明代', '新妆竟与画图争，知是昭阳第几名？\n瘦影自临春水照，卿须怜我我怜卿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怨' AND p.poem_author = '冯小青';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('己亥岁二首·僖宗广明元年', '曹松', '唐代', '泽国江山入战图，生民何计乐樵苏。 \n凭君莫话封侯事，一将功成万骨枯。\n\n传闻一战百神愁，两岸强兵过未休。 \n谁道沧江总无事，近来长共血争流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '己亥岁二首·僖宗广明元年' AND p.poem_author = '曹松';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦江南·千万恨', '温庭筠', '唐代', '千万恨，恨极在天涯。山月不知心里事，水风空落眼前花，摇曳碧云斜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梦江南·千万恨' AND p.poem_author = '温庭筠';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '听弹琴' AND p.poem_author = '刘长卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨晴', '王驾', '唐代', '雨前初见花间蕊，雨后兼无叶里花。\n蛱蝶飞来过墙去，却疑春色在邻家。(版本一)\n\n雨前初见花间蕊，雨后全无叶底花。\n蜂蝶纷纷过墙去，却疑春色在邻家。(版本二)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨晴' AND p.poem_author = '王驾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早春呈水部张十八员外二首', '韩愈', '唐代', '天街小雨润如酥，草色遥看近却无。\n最是一年春好处，绝胜烟柳满皇都。\n\n莫道官忙身老大，即无年少逐春心。\n凭君先到江头看，柳色如今深未深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早春呈水部张十八员外二首' AND p.poem_author = '韩愈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏早梅 / 扬州法曹梅花盛开', '何逊', '南北朝', '兔园标物序，惊时最是梅。\n衔霜当路发，映雪拟寒开。\n枝横却月观，花绕凌风台。\n朝洒长门泣，夕驻临邛杯。\n应知早飘落，故逐上春来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏早梅 / 扬州法曹梅花盛开' AND p.poem_author = '何逊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天仙子·水调数声持酒听', '张先', '宋代', '水调数声持酒听，午醉醒来愁未醒。送春春去几时回？临晚镜，伤流景，往事后期空记省。\n沙上并禽池上暝，云破月来花弄影。重重帘幕密遮灯，风不定，人初静，明日落红应满径。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天仙子·水调数声持酒听' AND p.poem_author = '张先';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凉州词', '孟浩然', '唐代', '浑成紫檀金屑文，作得琵琶声入云。 \n胡地迢迢三万里，那堪马上送明君。 \n异方之乐令人悲，羌笛胡笳不用吹。 \n坐看今夜关山月，思杀边城游侠儿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凉州词' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('积雨辋川庄作 / 秋归辋川庄作', '王维', '唐代', '积雨空林烟火迟，蒸藜炊黍饷东菑。\n漠漠水田飞白鹭，阴阴夏木啭黄鹂。\n山中习静观朝槿，松下清斋折露葵。\n野老与人争席罢，海鸥何事更相疑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '积雨辋川庄作 / 秋归辋川庄作' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜算子·答施', '乐婉', '宋代', '相思似海深，旧事如天远。泪滴千千万万行，更使人、愁肠断。\n要见无因见，拚了终难拚。若是前生未有缘，待重结、来生愿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜算子·答施' AND p.poem_author = '乐婉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('点绛唇·闺思', '李清照', '宋代', '寂寞深闺，柔肠一寸愁千缕。惜春春去。几点催花雨。\n倚遍阑干，只是无情绪。人何处。连天衰草，望断归来路。(\n\'衰\'草, 一作：芳)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '点绛唇·闺思' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·夜登小阁忆洛中旧游', '陈与义', '宋代', '忆昔午桥桥上饮，坐中多是豪英。长沟流月去无声。杏花疏影里，吹笛到天明。 \n二十余年如一梦，此身虽在堪惊。闲登小阁看新晴。古今多少事，渔唱起三更。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·夜登小阁忆洛中旧游' AND p.poem_author = '陈与义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郊行即事', '程颢', '宋代', '芳原绿野恣行事，春入遥山碧四围。\n兴逐乱红穿柳巷，困临流水坐苔矶。\n莫辞盏酒十分劝，只恐风花一片飞。\n况是清明好天气，不妨游衍莫忘归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郊行即事' AND p.poem_author = '程颢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宋定伯捉鬼', '干宝', '魏晋', '南阳宋定伯,年少时，夜行逢鬼。问之，鬼言：“我是鬼。”鬼问：“汝复谁？”定伯诳之，言：“我亦鬼。”鬼问：“欲至何所？”答曰：“欲至宛市。”鬼言：“我亦欲至宛市。”遂行。\n\n　　数里，鬼言：“步行太亟，可共递相担，何如？”定伯曰：“大善。”鬼便先担定伯数里。鬼言：“卿太重，将非鬼也？”定伯言：“我新鬼，故身重耳。”定伯因复担鬼，鬼略无重。如是再三。定伯复言：“我新鬼，不知有何所畏忌？”鬼答言：“惟不喜人唾。”于是共行。道遇水，定伯令鬼先渡，听之，了然无声音。定伯自渡，漕漼作声。鬼复言：“何以作声？”定伯曰：“新死，不习渡水故耳，勿怪吾也。”\n\n　　行欲至宛市，定伯便担鬼著肩上，急持之。鬼大呼，声咋咋然，索下，不复听之。径至宛市中下著地，化为一羊，便卖之恐其变化，唾之。得钱千五百，乃去。于时石崇言：“定伯卖鬼,得钱千五百文。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宋定伯捉鬼' AND p.poem_author = '干宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('墨梅', '张嵲', '宋代', '山边幽谷水边村，曾被疏花断客魂。\n犹恨东风无意思，更吹烟雨暗黄昏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '墨梅' AND p.poem_author = '张嵲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蒹葭', '杜甫', '唐代', '摧折不自守，秋风吹若何。\n暂时花戴雪，几处叶沉波。\n体弱春风早，丛长夜露多。\n江湖后摇落，亦恐岁蹉跎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蒹葭' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岁暮到家 / 岁末到家', '蒋士铨', '清代', '爱子心无尽，归家喜及辰。\n寒衣针线密，家信墨痕新。\n见面怜清瘦，呼儿问苦辛。\n低徊愧人子，不敢叹风尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岁暮到家 / 岁末到家' AND p.poem_author = '蒋士铨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('终南山', '王维', '唐代', '太乙近天都，连山接海隅。\n白云回望合，青霭入看无。\n分野中峰变，阴晴众壑殊。\n欲投人处宿，隔水问樵夫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '终南山' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏夜追凉', '杨万里', '宋代', '夜热依然午热同，开门小立月明中。\n竹深树密虫鸣处，时有微凉不是风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏夜追凉' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏柳', '曾巩', '宋代', '乱条犹未变初黄，倚得东风势便狂。\n解把飞花蒙日月，不知天地有清霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏柳' AND p.poem_author = '曾巩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送别诗', '佚名', '隋代', '杨柳青青著地垂，杨花漫漫搅天飞。\n柳条折尽花飞尽，借问行人归不归？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送别诗' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东栏梨花', '苏轼', '宋代', '梨花淡白柳深青，柳絮飞时花满城。\n惆怅东栏一株雪，人生看得几清明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东栏梨花' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('醉赠刘二十八使君', '白居易', '唐代', '为我引杯添酒饮，与君把箸击盘歌。\n诗称国手徒为尔，命压人头不奈何。\n举眼风光长寂寞，满朝官职独蹉跎。\n亦知合被才名折，二十三年折太多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '醉赠刘二十八使君' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·卫风·淇奥', '佚名', '先秦', '瞻彼淇奥，绿竹猗猗。有匪君子，如切如磋，如琢如磨。瑟兮僩兮，赫兮咺兮。有匪君子，终不可谖兮。\n瞻彼淇奥，绿竹青青。有匪君子，充耳琇莹，会弁如星。瑟兮僩兮，赫兮咺兮。有匪君子，终不可谖兮。\n瞻彼淇奥，绿竹如箦。有匪君子，如金如锡，如圭如璧。宽兮绰兮，猗重较兮。善戏谑兮，不为虐兮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·卫风·淇奥' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚晴', '李商隐', '唐代', '深居俯夹城，春去夏犹清。天意怜幽草，人间重晚晴。 \n并添高阁迥，微注小窗明。越鸟巢干后，归飞体更轻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚晴' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头·送章德茂大卿使虏', '陈亮', '宋代', '不见南师久，漫说北群空。当场只手，毕竟还我万夫雄。自笑堂堂汉使，得似洋洋河水，依旧只流东？且复穹庐拜，会向藁街逢！\n尧之都，舜之壤，禹之封。于中应有，一个半个耻臣戎！万里腥膻如许，千古英灵安在，磅礴几时通？胡运何须问，赫日自当中！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头·送章德茂大卿使虏' AND p.poem_author = '陈亮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满庭芳·山抹微云', '秦观', '宋代', '山抹微云，天连衰草，画角声断谯门。暂停征棹，聊共引离尊。多少蓬莱旧事，空回首、烟霭纷纷。斜阳外，寒鸦万点，流水绕孤村。(万点 一作：数点)\n销魂。当此际，香囊暗解，罗带轻分。谩赢得、青楼薄幸名存。此去何时见也，襟袖上、空惹啼痕。伤情处，高城望断，灯火已黄昏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满庭芳·山抹微云' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汉江临泛 / 汉江临眺', '王维', '唐代', '楚塞三湘接，荆门九派通。\n江流天地外，山色有无中。\n郡邑浮前浦，波澜动远空。\n襄阳好风日，留醉与山翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汉江临泛 / 汉江临眺' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹枝词·山桃红花满上头', '刘禹锡', '唐代', '山桃红花满上头，蜀江春水拍山流。\n花红易衰似郎意，水流无限似侬愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹枝词·山桃红花满上头' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丰乐亭游春·其三', '欧阳修', '宋代', '红树青山日欲斜，长郊草色绿无涯。\n游人不管春将老，来往亭前踏落花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丰乐亭游春·其三' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·梅', '李清照', '宋代', '庭院深深深几许，云窗雾阁春迟。为谁憔悴损芳姿。夜来清梦好，应是发南枝。 \n玉瘦檀轻无限恨，南楼羌管休吹。浓香吹尽有谁知。暖风迟日也，别到杏花肥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·梅' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李白墓', '白居易', '唐代', '采石江边李白坟，绕田无限草连云。\n可怜荒垄穷泉骨，曾有惊天动地文。\n但是诗人多薄命，就中沦落不过君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李白墓' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春兴', '武元衡', '唐代', '杨柳阴阴细雨晴，残花落尽见流莺。\n春风一夜吹乡梦，又逐春风到洛城。(乡 一作：香)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春兴' AND p.poem_author = '武元衡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('永遇乐·落日熔金', '李清照', '宋代', '落日熔金，暮云合璧，人在何处。染柳烟浓，吹梅笛怨，春意知几许。元宵佳节，融和天气，次第岂无风雨。来相召、香车宝马，谢他酒朋诗侣。(熔金 一作：镕金)\n中州盛日，闺门多暇，记得偏重三五。铺翠冠儿，捻金雪柳，簇带争济楚。如今憔悴，风鬟霜鬓，怕见夜间出去。不如向、帘儿底下，听人笑语。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '永遇乐·落日熔金' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长安秋望', '杜牧', '唐代', '楼倚霜树外，镜天无一毫。\n南山与秋色，气势两相高。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长安秋望' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·召南·鹊巢', '佚名', '先秦', '维鹊有巢，维鸠居之。之子于归，百两御之。\n维鹊有巢，维鸠方之。之子于归，百两将之。\n维鹊有巢，维鸠盈之。之子于归，百两成之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·召南·鹊巢' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙·淡荡春光寒食天', '李清照', '宋代', '淡荡春光寒食天，玉炉沉水袅残烟。梦回山枕隐花钿。 \n海燕未来人斗草，江梅已过柳生绵。黄昏疏雨湿秋千。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙·淡荡春光寒食天' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('于易水送人 / 于易水送别', '骆宾王', '唐代', '此地别燕丹，壮士发冲冠。\n昔时人已没，今日水犹寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '于易水送人 / 于易水送别' AND p.poem_author = '骆宾王';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月·顷在黄州', '苏轼', '宋代', '顷在黄州，春夜行蕲水中，过酒家饮，酒醉，乘月至一溪桥上，解鞍，由肱醉卧少休。及觉已晓，乱山攒拥，流水锵然，疑非尘世也。书此语桥柱上。(由肱 一作：曲肱)\n\n照野弥弥浅浪，横空隐隐层霄。障泥未解玉骢骄，我欲醉眠芳草。\n可惜一溪风月，莫教踏碎琼瑶。解鞍欹枕绿杨桥，杜宇一声春晓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月·顷在黄州' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题龙阳县青草湖', '唐珙', '元代', '西风吹老洞庭波，一夜湘君白发多。\n醉后不知天在水，满船清梦压星河。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题龙阳县青草湖' AND p.poem_author = '唐珙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('伐檀', '佚名', '先秦', '坎坎伐檀兮，置之河之干兮。河水清且涟猗。不稼不穑，胡取禾三百廛兮？不狩不猎，胡瞻尔庭有县貆兮？彼君子兮，不素餐兮！\n坎坎伐辐兮，置之河之侧兮。河水清且直猗。不稼不穑，胡取禾三百亿兮？不狩不猎，胡瞻尔庭有县特兮？彼君子兮，不素食兮！\n坎坎伐轮兮，置之河之漘兮。河水清且沦猗。不稼不穑，胡取禾三百囷兮？不狩不猎，胡瞻尔庭有县鹑兮？彼君子兮，不素飧兮！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '伐檀' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('邴原泣学', '礼赞', '明代', '邴原少孤，数岁时，过书舍而泣。师曰：“童子何泣？”原曰：“孤者易伤，贫者易感。夫书者，凡得学者，有亲也。一则愿其不孤，二则羡其得学，中心伤感，故泣耳。”师恻然曰：“欲书可耳!”原曰：“无钱资。”师曰：“童子苟有志,吾徒相教,不求资也。”于是遂就书。一冬之间，诵《孝经》《论语》。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '邴原泣学' AND p.poem_author = '礼赞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·周南·兔罝', '佚名', '先秦', '肃肃兔罝，椓之丁丁。赳赳武夫，公侯干城。\n肃肃兔罝，施于中逵。赳赳武夫，公侯好仇。\n肃肃兔罝，施于中林。赳赳武夫，公侯腹心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·周南·兔罝' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·阅尽天涯离别苦', '王国维', '清代', '阅尽天涯离别苦，不道归来，零落花如许。花底相看无一语，绿窗春与天俱莫。(俱莫 一作：俱暮)\n待把相思灯下诉，一缕新欢，旧恨千千缕。最是人间留不住，朱颜辞镜花辞树。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·阅尽天涯离别苦' AND p.poem_author = '王国维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赴戍登程口占示家人二首', '林则徐', '清代', '出门一笑莫心哀，浩荡襟怀到处开。\n时事难从无过立，达官非自有生来。\n风涛回首空三岛，尘壤从头数九垓。\n休信儿童轻薄语，嗤他赵老送灯台。\n\n力微任重久神疲，再竭衰庸定不支。\n苟利国家生死以，岂因祸福避趋之。\n谪居正是君恩厚，养拙刚于戍卒宜。\n戏与山妻谈故事，试吟断送老头皮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赴戍登程口占示家人二首' AND p.poem_author = '林则徐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辛夷坞', '王维', '唐代', '木末芙蓉花，山中发红萼。\n涧户寂无人，纷纷开且落。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辛夷坞' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行军九日思长安故园', '岑参', '唐代', '强欲登高去，无人送酒来。\n遥怜故园菊，应傍战场开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行军九日思长安故园' AND p.poem_author = '岑参';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江夜行', '张九龄', '唐代', '遥夜人何在，澄潭月里行。\n悠悠天宇旷，切切故乡情。\n外物寂无扰，中流澹自清。\n念归林叶换，愁坐露华生。\n犹有汀洲鹤，宵分乍一鸣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江夜行' AND p.poem_author = '张九龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小石城山记', '柳宗元', '唐代', '自西山道口径北，逾黄茅岭而下，有二道：其一西出，寻之无所得；其一少北而东，不过四十丈，土断而川分，有积石横当其垠。其上为睥睨、梁欐之形，其旁出堡坞，有若门焉。窥之正黑，投以小石，洞然有水声，其响之激越，良久乃已。环之可上，望甚远，无土壤而生嘉树美箭，益奇而坚，其疏数偃仰，类智者所施设也。\n\n　　噫！吾疑造物者之有无久矣。及是，愈以为诚有。又怪其不为之中州，而列是夷狄，更千百年不得一售其伎，是固劳而无用。神者傥不宜如是，则其果无乎？或曰：“以慰夫贤而辱于此者。”或曰：“其气之灵，不为伟人,而独为是物，故楚之南少人而多石。”是二者，余未信之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小石城山记' AND p.poem_author = '柳宗元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('马上作', '戚继光', '明代', '南北驱驰报主情，江花边草笑平生。(边草 一作：边月)\n一年三百六十日，多是横戈马上行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '马上作' AND p.poem_author = '戚继光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行路难·其二', '李白', '唐代', '大道如青天，我独不得出。\n羞逐长安社中儿，赤鸡白雉赌梨栗。\n弹剑作歌奏苦声，曳裾王门不称情。\n淮阴市井笑韩信，汉朝公卿忌贾生。\n君不见昔时燕家重郭隗，拥篲折节无嫌猜。\n剧辛乐毅感恩分，输肝剖胆效英才。\n昭王白骨萦蔓草，谁人更扫黄金台？\n行路难，归去来！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行路难·其二' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('从军行', '卢思道', '隋代', '朔方烽火照甘泉，长安飞将出祁连。\n犀渠玉剑良家子，白马金羁侠少年。\n平明偃月屯右地，薄暮鱼丽逐左贤。\n谷中石虎经衔箭，山上金人曾祭天。\n天涯一去无穷已，蓟门迢递三千里。\n朝见马岭黄沙合，夕望龙城阵云起。\n庭中奇树已堪攀，塞外征人殊未还。\n白云初下天山外，浮云直向五原间。\n关山万里不可越，谁能坐对芳菲月。\n流水本自断人肠，坚冰旧来伤马骨。\n边庭节物与华异，冬霰秋霜春不歇。\n长风萧萧渡水来，归雁连连映天没。\n从军行，军行万里出龙庭，单于渭桥今已拜，将军何处觅功名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '从军行' AND p.poem_author = '卢思道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('短歌行', '李白', '唐代', '白日何短短，百年苦易满。\n苍穹浩茫茫，万劫太极长。\n麻姑垂两鬓，一半已成霜。\n天公见玉女，大笑亿千场。\n吾欲揽六龙，回车挂扶桑。\n北斗酌美酒，劝龙各一觞。\n富贵非所愿，与人驻颜光。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '短歌行' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('人日思归', '薛道衡', '隋代', '入春才七日，离家已二年。\n人归落雁后，思发在花前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '人日思归' AND p.poem_author = '薛道衡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浪淘沙·借问江潮与海水', '白居易', '唐代', '借问江潮与海水，何似君情与妾心？\n相恨不如潮有信，相思始觉海非深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浪淘沙·借问江潮与海水' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送春 / 春晚', '王令', '宋代', '三月残花落更开，小檐日日燕飞来。\n子规夜半犹啼血，不信东风唤不回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送春 / 春晚' AND p.poem_author = '王令';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·有客慨然谈功名因追念少年时事戏作', '辛弃疾', '宋代', '壮岁旌旗拥万夫，锦襜突骑渡江初。燕兵夜娖银胡觮，汉箭朝飞金仆姑。\n追往事，叹今吾，春风不染白髭须。却将万字平戎策，换得东家种树书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·有客慨然谈功名因追念少年时事戏作' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏问花门酒家翁', '岑参', '唐代', '老人七十仍沽酒，千壶百瓮花门口。 \n道傍榆荚巧似钱，摘来沽酒君肯否。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏问花门酒家翁' AND p.poem_author = '岑参';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('关山月', '陆游', '宋代', '和戎诏下十五年，将军不战空临边。\n朱门沉沉按歌舞，厩马肥死弓断弦。\n戍楼刁斗催落月，三十从军今白发。\n笛里谁知壮士心，沙头空照征人骨。\n中原干戈古亦闻，岂有逆胡传子孙！\n遗民忍死望恢复，几处今宵垂泪痕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '关山月' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('台城', '韦庄', '唐代', '江雨霏霏江草齐，六朝如梦鸟空啼。 \n无情最是台城柳，依旧烟笼十里堤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '台城' AND p.poem_author = '韦庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金铜仙人辞汉歌', '李贺', '唐代', '魏明帝青龙元年八月，诏宫官牵车西取汉孝武捧露盘仙人，欲立置前殿。宫官既拆盘，仙人临载，乃潸然泪下。唐诸王孙李长吉遂作《金铜仙人辞汉歌》。\n\n茂陵刘郎秋风客，夜闻马嘶晓无迹。\n画栏桂树悬秋香，三十六宫土花碧。\n魏官牵车指千里，东关酸风射眸子。\n空将汉月出宫门，忆君清泪如铅水。\n衰兰送客咸阳道，天若有情天亦老。\n携盘独出月荒凉，渭城已远波声小。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金铜仙人辞汉歌' AND p.poem_author = '李贺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵陆佥宪元日春晴', '王守仁', '明代', '城里夕阳城外雪，相将十里异阴晴。\n也知造物曾何意，底事人心苦未平。\n柏府楼台衔倒影，茅茨松竹泻寒声。\n布衾莫谩愁僵卧，积素还多达曙明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵陆佥宪元日春晴' AND p.poem_author = '王守仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江城子·西城杨柳弄春柔', '秦观', '宋代', '西城杨柳弄春柔，动离忧，泪难收。犹记多情、曾为系归舟。碧野朱桥当日事，人不见，水空流。\n韶华不为少年留，恨悠悠，几时休？飞絮落花时候、一登楼。便作春江都是泪，流不尽，许多愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江城子·西城杨柳弄春柔' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九日', '李白', '唐代', '今日云景好，水绿秋山明。\n携壶酌流霞，搴菊泛寒荣。\n地远松石古，风扬弦管清。\n窥觞照欢颜，独笑还自倾。\n落帽醉山月，空歌怀友生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九日' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('葬花吟', '曹雪芹', '清代', '花谢花飞花满天，红消香断有谁怜？\n游丝软系飘春榭，落絮轻沾扑绣帘。\n闺中女儿惜春暮，愁绪满怀无释处。\n手把花锄出绣帘，忍踏落花来复去。\n柳丝榆荚自芳菲，不管桃飘与李飞；\n桃李明年能再发，明年闺中知有谁？\n三月香巢已垒成，梁间燕子太无情！\n明年花发虽可啄，却不道人去梁空巢也倾。\n一年三百六十日，风刀霜剑严相逼；\n明媚鲜妍能几时，一朝漂泊难寻觅。\n花开易见落难寻，阶前愁杀葬花人，\n独倚花锄泪暗洒，洒上空枝见血痕。\n杜鹃无语正黄昏，荷锄归去掩重门；\n青灯照壁人初睡，冷雨敲窗被未温。\n怪奴底事倍伤神？半为怜春半恼春。\n怜春忽至恼忽去，至又无言去未闻。\n昨宵庭外悲歌发，知是花魂与鸟魂？\n花魂鸟魂总难留，鸟自无言花自羞；\n愿侬此日生双翼，随花飞到天尽头。\n天尽头，何处有香丘？\n未若锦囊收艳骨，一抔净土掩风流。\n质本洁来还洁去，强于污淖陷渠沟。\n尔今死去侬收葬，未卜侬身何日丧？\n侬今葬花人笑痴，他年葬侬知是谁？\n试看春残花渐落，便是红颜老死时；\n一朝春尽红颜老，花落人亡两不知！——程高通行本\n\n花谢花飞飞满天，红消香断有谁怜？\n游丝软系飘春榭，落絮轻沾扑绣帘。\n闺中女儿惜春暮，愁绪满怀无释处。\n手把花锄出绣帘，忍踏落花来复去？\n柳丝榆荚自芳菲，不管桃飘与李飞。\n桃李明年能再发，明年闺中知有谁？\n三月香巢已垒成，梁间燕子太无情！\n明年花发虽可啄，却不道人去梁空巢也倾。\n一年三百六十日，风刀霜剑严相逼。\n明媚鲜妍能几时？一朝漂泊难寻觅。\n花开易见落难寻，阶前闷死葬花人。\n独倚花锄泪暗洒，洒上空枝见血痕。\n杜鹃无语正黄昏，荷锄归去掩重门。\n青灯照壁人初睡，冷雨敲窗被未温。\n怪奴底事倍伤神？半为怜春半恼春。\n怜春忽至恼忽去，至又无言去不闻。\n昨宵庭外悲歌发，知是花魂与鸟魂。\n花魂鸟魂总难留，鸟自无言花自羞。\n愿奴胁下生双翼，随花飞到天尽头。\n天尽头，何处有香丘？\n未若锦囊收艳骨，一抷净土掩风流！\n质本洁来还洁去，强于污淖陷渠沟。\n尔今死去侬收葬，未卜侬身何日丧？\n侬今葬花人笑痴，他年葬侬知有谁？\n试看春残花渐落，便是红颜老死时。\n一朝春尽红颜老，花落人亡两不知！——甲戌本\n\n花谢花飞花满天，红消香断有谁怜？\n游丝软系飘春榭，落絮轻沾扑绣帘。\n帘中女儿惜春莫，愁绪满怀无处诉。\n手把花锄出绣帘，忍踏落花来复去？\n柳丝榆荚自芳菲，不管桃飘与柳飞。\n桃李明年能再发，明岁闺中知有谁？\n三月香巢已垒成，梁间燕子太无情！\n明年花发虽可啄，却不道人去梁空巢也倾。\n一年三百六十日，风刀霜剑严相逼。\n明媚鲜妍能几时？一朝漂泊难寻觅。\n花开易见落难寻，阶前闷杀葬花人。\n独把香锄泪暗洒，洒上花枝见血痕。\n杜鹃无语正黄昏，荷锄归去掩重门。\n青灯照壁人初睡，冷雨敲窗被未温。\n怪奴底事倍伤神？半为怜春半恼春。\n怜春忽至恼忽去，至又无言去不闻。\n昨宵庭外悲歌发，知是花魂与鸟魂。\n花魂鸟魂总难留，鸟自无言花自羞。\n愿奴胁下生双翼，随花飞落天尽头。\n天尽头，何处有香丘？\n未若锦囊收艳骨，一抔冷土掩风流。\n质本洁来还洁去，强于污淖陷渠沟。\n尔今死去奴收葬，未卜奴身何日亡？\n奴今葬花人笑痴，他年葬奴知是谁？\n试看春残花渐落，便是红颜老死时！\n一朝春尽红颜老，花落人亡两不知。——周汝昌校本', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '葬花吟' AND p.poem_author = '曹雪芹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行香子·天与秋光', '李清照', '宋代', '天与秋光，转转情伤，探金英知近重阳。薄衣初试，绿蚁新尝，渐一番风，一番雨，一番凉。\n黄昏院落，凄凄惶惶，酒醒时往事愁肠。那堪永夜，明月空床。闻砧声捣，蛩声细，漏声长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行香子·天与秋光' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五人墓碑记', '张溥', '明代', '五人者，盖当蓼洲周公之被逮，激于义而死焉者也。至于今，郡之贤士大夫请于当道，即除魏阉废祠之址以葬之；且立石于其墓之门，以旌其所为。呜呼，亦盛矣哉！\n\n　　夫五人之死，去今之墓而葬焉，其为时止十有一月耳。夫十有一月之中，凡富贵之子，慷慨得志之徒，其疾病而死，死而湮没不足道者，亦已众矣；况草野之无闻者欤？独五人之皦皦，何也？\n\n　　予犹记周公之被逮，在丙寅三月之望。吾社之行为士先者，为之声义，敛赀财以送其行，哭声震动天地。缇骑按剑而前，问：“谁为哀者？”众不能堪，抶而仆之。是时以大中丞抚吴者为魏之私人毛一鹭，公之逮所由使也；吴之民方痛心焉，于是乘其厉声以呵，则噪而相逐。中丞匿于溷藩以免。既而以吴民之乱请于朝，按诛五人，曰颜佩韦、杨念如、马杰、沈扬、周文元，即今之傫然在墓者也。\n\n　　然五人之当刑也，意气扬扬，呼中丞之名而詈之，谈笑以死。断头置城上，颜色不少变。有贤士大夫发五十金，买五人之头而函之，卒与尸合。故今之墓中全乎为五人也。\n\n　　嗟乎！大阉之乱，缙绅而能不易其志者，四海之大，有几人欤？而五人生于编伍之间，素不闻诗书之训，激昂大义，蹈死不顾，亦曷故哉？且矫诏纷出，钩党之捕遍于天下，卒以吾郡之发愤一击，不敢复有株治；大阉亦逡巡畏义，非常之谋难于猝发，待圣人之出而投缳道路，不可谓非五人之力也。\n\n　　由是观之，则今之高爵显位，一旦抵罪，或脱身以逃，不能容于远近，而又有剪发杜门，佯狂不知所之者，其辱人贱行，视五人之死，轻重固何如哉？是以蓼洲周公忠义暴于朝廷，赠谥褒美，显荣于身后；而五人亦得以加其土封，列其姓名于大堤之上，凡四方之士无不有过而拜且泣者，斯固百世之遇也。不然，令五人者保其首领，以老于户牖之下，则尽其天年，人皆得以隶使之，安能屈豪杰之流，扼腕墓道，发其志士之悲哉？故余与同社诸君子，哀斯墓之徒有其石也，而为之记，亦以明死生之大，匹夫之有重于社稷也。\n\n　　贤士大夫者，冏卿因之吴公，太史文起文公、孟长姚公也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '五人墓碑记' AND p.poem_author = '张溥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山花子·风絮飘残已化萍', '纳兰性德', '清代', '风絮飘残已化萍，泥莲刚倩藕丝萦。珍重别拈香一瓣，记前生。\n人到情多情转薄，而今真个不多情。又到断肠回首处，泪偷零。(不多情 一作：悔多情)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山花子·风絮飘残已化萍' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塞下曲', '许浑', '唐代', '夜战桑乾北，秦兵半不归。\n朝来有乡信，犹自寄寒衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塞下曲' AND p.poem_author = '许浑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐·独宿博山王氏庵', '辛弃疾', '宋代', '绕床饥鼠，蝙蝠翻灯舞。屋上松风吹急雨，破纸窗间自语。\n平生塞北江南，归来华发苍颜。布被秋宵梦觉，眼前万里江山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐·独宿博山王氏庵' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉蝴蝶·望处雨收云断', '柳永', '宋代', '望处雨收云断，凭阑悄悄，目送秋光。晚景萧疏，堪动宋玉悲凉。水风轻，蘋花渐老，月露冷、梧叶飘黄。遣情伤。故人何在，烟水茫茫。 \n难忘，文期酒会，几孤风月，屡变星霜。海阔山遥，未知何处是潇湘。念双燕、难凭远信，指暮天、空识归航。黯相望。断鸿声里，立尽斜阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉蝴蝶·望处雨收云断' AND p.poem_author = '柳永';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同儿辈赋未开海棠', '元好问', '金朝', '枝间新绿一重重， 小蕾深藏数点红。\n爱惜芳心莫轻吐， 且教桃李闹春风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同儿辈赋未开海棠' AND p.poem_author = '元好问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风入松·危楼古镜影犹寒', '张炎', '宋代', '危楼古镜影犹寒。倒景忽相看。桃花不识东西晋，想如今、也梦邯郸。缥缈神仙海上，飘零图画人间。\n宝光丹气共回环。水弱小舟闲。秋风难老三珠树，尚依依、脆管清弹。说与霓裳莫舞，银桥不到深山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风入松·危楼古镜影犹寒' AND p.poem_author = '张炎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送梓州李使君', '王维', '唐代', '万壑树参天，千山响杜鹃。\n山中一夜雨，树杪百重泉。\n汉女输橦布，巴人讼芋田。\n文翁翻教授，不敢倚先贤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送梓州李使君' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴起守信', '宋濂', '明代', '昔吴起出，遇故人,而止之食。故人曰：“诺，期返而食。”起曰：“待公而食。”故人至暮不来，起不食待之。明日早，令人求故人，故人来，方与之食。起之不食以俟者，恐其自食其言也。其为信若此，宜其能服三军欤？欲服三军，非信不可也！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '吴起守信' AND p.poem_author = '宋濂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桑茶坑道中', '杨万里', '宋代', '晴明风日雨干时，草满花堤水满溪。\n童子柳阴眠正着，一牛吃过柳阴西。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桑茶坑道中' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('牧童词', '李涉', '唐代', '朝牧牛，牧牛下江曲。\n夜牧牛，牧牛度村谷。\n荷蓑出林春雨细，芦管卧吹莎草绿。\n乱插蓬蒿箭满腰，不怕猛虎欺黄犊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '牧童词' AND p.poem_author = '李涉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('截竿入城', '邯郸淳 撰', '魏晋', '鲁有执长竿入城门者，初竖执之，不可入；横执之，亦不可入。计无所出。俄有老父至，曰：“吾非圣人，但见事多矣！何不以锯中截而入？"遂依而截之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '截竿入城' AND p.poem_author = '邯郸淳 撰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏日南亭怀辛大', '孟浩然', '唐代', '山光忽西落，池月渐东上。\n散发乘夕凉，开轩卧闲敞。\n荷风送香气，竹露滴清响。\n欲取鸣琴弹，恨无知音赏。\n感此怀故人，中宵劳梦想。(\n\'中\'宵, 一作：终)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏日南亭怀辛大' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头·中秋', '米芾', '宋代', '砧声送风急，蟠蟀思高秋。我来对景，不学宋玉解悲愁。收拾凄凉兴况，分付尊中醽醁，倍觉不胜幽。自有多情处，明月挂南楼。\n怅襟怀，横玉笛，韵悠悠。清时良夜，借我此地倒金瓯。可爱一天风物，遍倚阑干十二，宇宙若萍浮。醉困不知醒，欹枕卧江流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头·中秋' AND p.poem_author = '米芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('征人怨 / 征怨', '柳中庸', '唐代', '岁岁金河复玉关，朝朝马策与刀环。 \n三春白雪归青冢，万里黄河绕黑山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '征人怨 / 征怨' AND p.poem_author = '柳中庸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏华山', '寇准', '宋代', '只有天在上，更无山与齐。\n举头红日近，回首白云低。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏华山' AND p.poem_author = '寇准';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诗经·陈风·月出', '佚名', '先秦', '月出皎兮，佼人僚兮。舒窈纠兮，劳心悄兮。\n月出皓兮，佼人懰兮。舒忧受兮，劳心慅兮。\n月出照兮，佼人燎兮。舒夭绍兮，劳心惨兮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诗经·陈风·月出' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·周南·汝坟', '佚名', '先秦', '遵彼汝坟，伐其条枚。未见君子，惄如调饥。\n遵彼汝坟，伐其条肄。既见君子，不我遐弃。\n鲂鱼赪尾，王室如毁。虽则如毁，父母孔迩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·周南·汝坟' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('定风波·两两轻红半晕腮', '苏轼', '宋代', '十月九日，孟亨之置酒秋香亭。有双拒霜，独向君猷而开，坐客喜笑，以为非使君莫可当此花，故作是篇。\n\n两两轻红半晕腮，依依独为使君回。若道使君无此意，何为，双花不向别人开。\n但看低昂烟雨里，不已。劝君休诉十分杯。更问尊前狂副使。来岁。花开时节与谁来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '定风波·两两轻红半晕腮' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔父', '佚名', '先秦', '屈原既放，游于江潭，行吟泽畔，颜色憔悴，形容枯槁。渔父见而问之曰：“子非三闾大夫与？何故至于斯？”屈原曰：“举世皆浊我独清，众人皆醉我独醒，是以见放。”\n\n　　渔父曰：“圣人不凝滞于物，而能与世推移。世人皆浊，何不淈其泥而扬其波？众人皆醉，何不餔其糟而歠其醨？何故深思高举，自令放为？”\n\n　　屈原曰：“吾闻之，新沐者必弹冠，新浴者必振衣；安能以身之察察，受物之汶汶者乎？宁赴湘流，葬于江鱼之腹中。安能以皓皓之白，而蒙世俗之尘埃乎?”\n\n　　渔父莞尔而笑，鼓枻而去，乃歌曰：“沧浪之水清兮，可以濯吾缨；沧浪之水浊兮，可以濯吾足。”遂去，不复与言。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔父' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长命女·春日宴', '冯延巳', '五代', '春日宴，绿酒一杯歌一遍。再拜陈三愿：一愿郎君千岁，二愿妾身常健，三愿如同梁上燕，岁岁长相见。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长命女·春日宴' AND p.poem_author = '冯延巳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻乐天授江州司马', '元稹', '唐代', '残灯无焰影幢幢，此夕闻君谪九江。 \n垂死病中惊坐起，暗风吹雨入寒窗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻乐天授江州司马' AND p.poem_author = '元稹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('祭十二郎文', '韩愈', '唐代', '年、月、日，季父愈闻汝丧之七日，乃能衔哀致诚，使建中远具时羞之奠，告汝十二郎之灵：\n\n　　呜呼！吾少孤，及长，不省所怙，惟兄嫂是依。中年，兄殁南方，吾与汝俱幼，从嫂归葬河阳。既又与汝就食江南。零丁孤苦，未尝一日相离也。吾上有三兄，皆不幸早世。承先人后者，在孙惟汝，在子惟吾。两世一身，形单影只。嫂尝抚汝指吾而言曰：“韩氏两世，惟此而已！”汝时尤小，当不复记忆。吾时虽能记忆，亦未知其言之悲也。\n\n　　吾年十九，始来京城。其后四年，而归视汝。又四年，吾往河阳省坟墓，遇汝从嫂丧来葬。又二年，吾佐董丞相于汴州，汝来省吾。止一岁，请归取其孥。明年，丞相薨。吾去汴州，汝不果来。是年，吾佐戎徐州，使取汝者始行，吾又罢去，汝又不果来。吾念汝从于东，东亦客也，不可以久；图久远者，莫如西归，将成家而致汝。呜呼！孰谓汝遽去吾而殁乎！吾与汝俱少年，以为虽暂相别，终当久相与处。故舍汝而旅食京师，以求斗斛之禄。诚知其如此，虽万乘之公相，吾不以一日辍汝而就也。\n\n　　去年，孟东野往。吾书与汝曰：“吾年未四十，而视茫茫，而发苍苍，而齿牙动摇。念诸父与诸兄，皆康强而早世。如吾之衰者，其能久存乎？吾不可去，汝不肯来，恐旦暮死，而汝抱无涯之戚也！”孰谓少者殁而长者存，强者夭而病者全乎！\n\n　　呜呼！其信然邪？其梦邪？其传之非其真邪？信也，吾兄之盛德而夭其嗣乎？汝之纯明而不克蒙其泽乎？少者、强者而夭殁，长者、衰者而存全乎？未可以为信也。梦也，传之非其真也，东野之书，耿兰之报，何为而在吾侧也？呜呼！其信然矣！吾兄之盛德而夭其嗣矣！汝之纯明宜业其家者，不克蒙其泽矣！所谓天者诚难测，而神者诚难明矣！所谓理者不可推，而寿者不可知矣！\n\n　　虽然，吾自今年来，苍苍者或化而为白矣，动摇者或脱而落矣。毛血日益衰，志气日益微，几何不从汝而死也。死而有知，其几何离；其无知，悲不几时，而不悲者无穷期矣。\n\n　　汝之子始十岁，吾之子始五岁。少而强者不可保，如此孩提者，又可冀其成立邪?呜呼哀哉！呜呼哀哉！\n\n　　汝去年书云：“比得软脚病，往往而剧。”吾曰：“是疾也，江南之人，常常有之。”未始以为忧也。呜呼！ 其竟以此而殒其生乎？抑别有疾而至斯极乎？\n\n　　汝之书，六月十七日也。东野云，汝殁以六月二日；耿兰之报无月日。盖东野之使者，不知问家人以月日；如耿兰之报，不知当言月日。东野与吾书，乃问使者，使者妄称以应之乎。其然乎？其不然乎？\n\n　　今吾使建中祭汝，吊汝之孤与汝之乳母。彼有食，可守以待终丧，则待终丧而取以来；如不能守以终丧，则遂取以来。其余奴婢，并令守汝丧。吾力能改葬，终葬汝于先人之兆，然后惟其所愿。\n\n　　呜呼！汝病吾不知时，汝殁吾不知日，生不能相养以共居，殁不能抚汝以尽哀，敛不凭其棺，窆不临其穴。吾行负神明，而使汝夭；不孝不慈，而不能与汝相养以生，相守以死。一在天之涯，一在地之角，生而影不与吾形相依，死而魂不与吾梦相接。吾实为之，其又何尤！彼苍者天，曷其有极！自今已往，吾其无意于人世矣！当求数顷之田于伊颍之上，以待余年，教吾子与汝子，幸其成；长吾女与汝女，待其嫁，如此而已。\n\n　　呜呼，言有穷而情不可终，汝其知也邪？其不知也邪？呜呼哀哉！尚飨！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '祭十二郎文' AND p.poem_author = '韩愈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与诸子登岘山', '孟浩然', '唐代', '人事有代谢，往来成古今。江山留胜迹，我辈复登临。\n水落鱼梁浅，天寒梦泽深。羊公碑尚在，读罢泪沾襟。(尚在 一作：字在)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与诸子登岘山' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏日田园杂兴', '范成大', '宋代', '梅子金黄杏子肥，麦花雪白菜花稀。日长篱落无人过，惟有蜻蜓蛱蝶飞。\n五月江吴麦秀寒，移秧披絮尚衣单。稻根科斗行如块，田水今年一尺宽。\n二麦俱秋斗百钱，田家唤作小丰年。饼炉饭甑无饥色，接到西风熟稻天。\n百沸缲汤雪涌波，缲车嘈囋雨鸣蓑。桑姑盆手交相贺，绵茧无多丝茧多。\n小妇连宵上绢机，大耆催税急於飞。今年幸甚蚕桑熟，留得黄丝织夏衣。\n下田戽水出江流，高垄翻江逆上沟；地势不齐人力尽，丁男长在踏车头。\n昼出耘田夜绩麻，村庄儿女各当家。童孙未解供耕织，也傍桑阴学种瓜。\n槐叶初匀日气凉，葱葱鼠耳翠成双。三公只得三株看，闲客清阴满北窗。\n黄尘行客汗如浆，少住侬家漱井香；借与门前磐石坐，柳阴亭午正风凉。\n千顷芙蕖放棹嬉，花深迷路晚忘归。家人暗识船行处，时有惊忙小鸭飞。\n采菱辛苦废犁鉏，血指流丹鬼质枯。无力买田聊种水，近来湖面亦收租。\n蜩螗千万沸斜阳，蛙黾无边聒夜长。不把痴聋相对治，梦魂争得到藜床？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏日田园杂兴' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('活水亭观书有感二首·其二', '朱熹', '宋代', '昨夜江边春水生，艨艟巨舰一毛轻。\n向来枉费推移力，此日中流自在行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '活水亭观书有感二首·其二' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出塞', '徐锡麟', '清代', '军歌应唱大刀环，誓灭胡奴出玉关。\n只解沙场为国死，何须马革裹尸还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出塞' AND p.poem_author = '徐锡麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('人间词话七则', '王国维', '清代', '有有我之境，有无我之境。“泪眼问花花不语，乱红飞过秋千去。”“可堪孤馆闭春寒，杜鹃声里斜阳暮。”有我之境也。“采菊东篱下，悠然见南山。”“寒波澹澹起，白鸟悠悠下。”无我之境也。有我之境，以我观物，故物我皆著我之色彩。无我之境，以物观物，故不知何者为我，何者为物。古人为词，写有我之境者为多，然未始不能写无我之境，此在豪杰之士能自树立耳。\n　　境非独谓景物也。喜怒哀乐，亦人心中之一境界。故能写真景物，真感情者，谓之有境界。否则谓之无境界。\n　　境界有大小，不以是而分优劣。“细雨鱼儿出，微风燕子斜”何遽不若“落日照大旗，马鸣风萧萧”。“宝帘闲挂小银钩”何遽不若“雾失楼台，月迷津渡”也。\n　　词至李后主而眼界始大，感慨遂深，遂变伶工之词而为士大夫之词。周介存置诸温韦之下，可为颠倒黑白矣。“自是人生长恨水长东”、“流水落花春去也，天上人间”，《金荃》《浣花》，能有此气象耶？\n　　古今之成大事业、大学问者，罔不经过三种之境界：“昨夜西风凋碧树。独上高楼，望尽天涯路。”此第一境界也。“衣带渐宽终不悔，为伊消得人憔悴。”此第二境界也。“众里寻他千百度，蓦然回首，那人却在，灯火阑珊处。”此第三境界也。此等语皆非大词人不能道。然遽以此意解释诸词，恐为晏欧诸公所不许也。\n　　大家之作，其言情也必沁人心脾，其写景也必豁人耳目。其辞脱口而出，无矫揉妆束之态。以其所见者真，所知者深也。诗词皆然。持此以衡古今之作者，可无大误也。\n　　诗人对宇宙人生，须入乎其内，又须出乎其外。入乎其内，故能写之。出乎其外，故能观之。入乎其内，故有生气。出乎其外，故有高致。美成能入而不出。白石以降，于此二事皆未梦见。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '人间词话七则' AND p.poem_author = '王国维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('琵琶行', '牛殳', '唐代', '何人劚得一片木，三尺春冰五音足。\n一弹决破真珠囊，迸落金盘声断续。\n飘飘飖飖寒丁丁，虫豸出蛰神鬼惊。\n秋鸿叫侣代云黑，猩猩夜啼蛮月明。\n潏潏汩汩声不定，胡雏学汉语未正。\n若似长安月蚀时，满城敲鼓声噒噒。\n青山飞起不压物，野水流来欲湿人。\n伤心忆得陈后主，春殿半酣细腰舞。\n黄莺百舌正相呼，玉树后庭花带雨。\n二妃哭处山重重，二妃没后云溶溶。\n夜深霜露锁空庙，零落一丛斑竹风。\n金谷园中草初绿，石崇一弄思归曲。\n当时二十四友人，手把金杯听不足。\n又似贾客蜀道间，千铎万磬鸣空山。\n未若此调呦呦兮啁啁，嘈嘈兮啾啾。\n引之于山，兽不能走。吹之于水，鱼不能游。\n方知此艺不可有，人间万事凭双手。\n若何为我再三弹，送却花前一尊酒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '琵琶行' AND p.poem_author = '牛殳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋宵月下有怀', '孟浩然', '唐代', '秋空明月悬，光彩露沾湿。\n惊鹊栖未定，飞萤卷帘入。\n庭槐寒影疏，邻杵夜声急。\n佳期旷何许，望望空伫立。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋宵月下有怀' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杨布打狗', '列御寇', '先秦', '杨朱之弟曰布，衣素衣而出。天雨，解素衣，衣缁衣而返。其狗不知，迎而吠之。杨布怒，将扑之。杨朱曰：“子无扑矣，子亦犹是也。向者使汝狗白而往黑而来，岂能无怪哉？”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杨布打狗' AND p.poem_author = '列御寇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谒金门·风乍起', '冯延巳', '五代', '风乍起，吹皱一池春水。闲引鸳鸯香径里，手挼红杏蕊。\n斗鸭阑干独倚，碧玉搔头斜坠。终日望君君不至，举头闻鹊喜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谒金门·风乍起' AND p.poem_author = '冯延巳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病牛', '李纲', '宋代', '耕犁千亩实千箱，力尽筋疲谁复伤？\n但得众生皆得饱，不辞羸病卧残阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病牛' AND p.poem_author = '李纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉赠韦左丞丈二十二韵', '杜甫', '唐代', '纨绔不饿死，儒冠多误身。丈人试静听，贱子请具陈。\n甫昔少年日，早充观国宾。读书破万卷，下笔如有神。(读书破万卷 一作：读破万卷书)\n赋料扬雄敌，诗看子建亲。李邕求识面，王翰愿卜邻。\n自谓颇挺出，立登要路津。致君尧舜上，再使风俗淳。\n此意竟萧条，行歌非隐沦。骑驴十三载，旅食京华春。\n朝扣富儿门，暮随肥马尘。残杯与冷炙，到处潜悲辛。\n主上顷见征，欻然欲求伸。青冥却垂翅，蹭蹬无纵鳞。\n甚愧丈人厚，甚知丈人真。每于百僚上，猥颂佳句新。\n窃效贡公喜，难甘原宪贫。焉能心怏怏，只是走踆踆。\n今欲东入海，即将西去秦。尚怜终南山，回首清渭滨。\n常拟报一饭，况怀辞大臣。白鸥没浩荡，万里谁能驯？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉赠韦左丞丈二十二韵' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('访戴天山道士不遇', '李白', '唐代', '犬吠水声中，桃花带露浓。(露浓 一作：雨浓)\n树深时见鹿，溪午不闻钟。\n野竹分青霭，飞泉挂碧峰。\n无人知所去，愁倚两三松。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '访戴天山道士不遇' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菊花', '唐寅', '明代', '故园三径吐幽丛，一夜玄霜坠碧空。\n多少天涯未归客，尽借篱落看秋风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菊花' AND p.poem_author = '唐寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('琴诗', '苏轼', '宋代', '若言琴上有琴声，放在匣中何不鸣？\n若言声在指头上，何不于君指上听？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '琴诗' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和张仆射塞下曲·其二', '卢纶', '唐代', '林暗草惊风，将军夜引弓。\n平明寻白羽，没在石棱中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和张仆射塞下曲·其二' AND p.poem_author = '卢纶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉楼春·别后不知君远近', '欧阳修', '宋代', '别后不知君远近。触目凄凉多少闷。渐行渐远渐无书，水阔鱼沉何处问。\n夜深风竹敲秋韵。万叶千声皆是恨。故欹单枕梦中寻，梦又不成灯又烬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉楼春·别后不知君远近' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·邶风·日月', '佚名', '先秦', '日居月诸，照临下土。乃如之人兮，逝不古处？胡能有定？宁不我顾。\n日居月诸，下土是冒。乃如之人兮，逝不相好。胡能有定？宁不我报。\n日居月诸，出自东方。乃如之人兮，德音无良。胡能有定？俾也可忘。\n日居月诸，东方自出。父兮母兮，畜我不卒。胡能有定？报我不述。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·邶风·日月' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归园田居·其五', '陶渊明', '魏晋', '怅恨独策还，崎岖历榛曲。\n山涧清且浅，可以濯吾足。\n漉我新熟酒，只鸡招近局。\n日入室中暗，荆薪代明烛。\n欢来苦夕短，已复至天旭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归园田居·其五' AND p.poem_author = '陶渊明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头·昵昵儿女语', '苏轼', '宋代', '欧阳文忠公尝问余：“琴诗何者最善？答以退之听颖师琴诗最善。公曰：此诗最奇丽，然非听琴，乃听琵琶也。余深然之。建安章质夫家善琵琶者，乞为歌词。余久不作，特取退之词，稍加隐括，使就声律，以遗之云。\n\n昵昵儿女语，灯火夜微明。恩怨尔汝来去，弹指泪和声。忽变轩昂勇士，一鼓填然作气，千里不留行。回首暮云远，飞絮搅青冥。\n众禽里，真彩凤，独不鸣。跻攀寸步千险，一落百寻轻。烦子指间风雨，置我肠中冰炭，起坐不能平。推手从归去，无泪与君倾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头·昵昵儿女语' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菊花', '李商隐', '唐代', '暗暗淡淡紫，融融冶冶黄。\n陶令篱边色，罗含宅里香。\n几时禁重露，实是怯残阳。\n愿泛金鹦鹉，升君白玉堂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菊花' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无衣', '佚名', '先秦', '岂曰无衣？七兮。不如子之衣，安且吉兮。\n岂曰无衣？六兮。不如子之衣，安且燠兮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无衣' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·召南·草虫', '佚名', '先秦', '喓喓草虫，趯趯阜螽。未见君子，忧心忡忡。亦既见止，亦既觏止，我心则降。\n陟彼南山，言采其蕨。未见君子，忧心惙惙。亦既见止，亦既觏止，我心则说。\n陟彼南山，言采其薇。未见君子，我心伤悲。亦既见止，亦既觏止，我心则夷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·召南·草虫' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('曾子杀彘 / 曾子烹彘', '韩非', '先秦', '曾子之妻之市，其子随之而泣。其母曰：“汝还，顾反为女杀彘。”妻适市来，曾子欲捕彘杀之。妻止之曰：“特与婴儿戏耳。”曾子曰：“婴儿非与戏也。婴儿非有知也，待父母而学者也，听父母之教。今子欺之，是教子欺也。母欺子，子而不信其母，非所以成教也。”遂烹彘也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '曾子杀彘 / 曾子烹彘' AND p.poem_author = '韩非';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('朝三暮四', '佚名', '先秦', '宋有狙公者，爱狙，养之成群，能解狙之意；狙亦得公之心。损其家口，充狙之欲。俄而匮焉，将限其食，恐众狙之不训于己也。先诳之曰：“与若芧，朝三而暮四，足乎？”众狙皆起怒。俄而曰：“与若芧，朝四而暮三，足乎？”众狙皆伏而喜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '朝三暮四' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庖丁解牛', '庄周', '先秦', '吾生也有涯，而知也无涯 。以有涯随无涯，殆已！已而为知者，殆而已矣！为善无近名，为恶无近刑。缘督以为经，可以保身，可以全生，可以养亲，可以尽年。\n\n　　庖丁为文惠君解牛，手之所触，肩之所倚，足之所履，膝之所踦，砉然向然，奏刀騞然，莫不中音。合于《桑林》之舞，乃中《经首》之会。\n\n　　文惠君曰：“嘻，善哉！技盖至此乎？”\n\n　　庖丁释刀对曰：“臣之所好者，道也，进乎技矣。始臣之解牛之时，所见无非牛者。三年之后，未尝见全牛也。方今之时，臣以神遇而不以目视，官知止而神欲行。依乎天理，批大郤，导大窾，因其固然，技经肯綮之未尝，而况大軱乎！良庖岁更刀，割也；族庖月更刀，折也。今臣之刀十九年矣，所解数千牛矣，而刀刃若新发于硎。彼节者有间，而刀刃者无厚；以无厚入有间，恢恢乎其于游刃必有余地矣，是以十九年而刀刃若新发于硎。虽然，每至于族，吾见其难为，怵然为戒，视为止，行为迟。动刀甚微，謋然已解，如土委地。提刀而立，为之四顾，为之踌躇满志，善刀而藏之。”\n\n　　文惠君曰：“善哉！吾闻庖丁之言，得养生焉。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庖丁解牛' AND p.poem_author = '庄周';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('兰陵王·柳', '周邦彦', '宋代', '柳阴直，烟里丝丝弄碧。隋堤上、曾见几番，拂水飘绵送行色。登临望故国，谁识京华倦客？长亭路，年去岁来，应折柔条过千尺。\n闲寻旧踪迹，又酒趁哀弦，灯照离席。梨花榆火催寒食。愁一箭风快，半篙波暖，回头迢递便数驿，望人在天北。\n凄恻，恨堆积！渐别浦萦回，津堠岑寂，斜阳冉冉春无极。念月榭携手，露桥闻笛。沉思前事，似梦里，泪暗滴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '兰陵王·柳' AND p.poem_author = '周邦彦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠李白', '杜甫', '唐代', '秋来相顾尚飘蓬，未就丹砂愧葛洪。 \n痛饮狂歌空度日，飞扬跋扈为谁雄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠李白' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天净沙·秋', '朱庭玉', '元代', '庭前落尽梧桐，水边开彻芙蓉。\n解与诗人意同。\n辞柯霜叶，飞来就我题红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天净沙·秋' AND p.poem_author = '朱庭玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过分水岭', '温庭筠', '唐代', '溪水无情似有情，入山三日得同行。\n岭头便是分头处，惜别潺湲一夜声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过分水岭' AND p.poem_author = '温庭筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('客中初夏', '司马光', '宋代', '四月清和雨乍晴，南山当户转分明。\n更无柳絮因风起，惟有葵花向日倾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '客中初夏' AND p.poem_author = '司马光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙·雪颔霜髯不自惊', '苏轼', '宋代', '伽花彩甚奇，谓有初春之兴。因作二首，寄袁公济\n\n雪颔霜髯不自惊。更将翦彩发春荣。羞颜未醉已先赪。 \n莫唱黄鸡并白发，且呼张丈唤殷兄。有人归去欲卿卿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙·雪颔霜髯不自惊' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('短歌行', '王建', '唐代', '人初生，日初出。上山迟，下山疾。百年三万六千朝， \n夜里分将强半日。有歌有舞须早为，昨日健于今日时。 \n人家见生男女好，不知男女催人老。短歌行，无乐声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '短歌行' AND p.poem_author = '王建';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵晚望', '高蟾', '唐代', '曾伴浮云归晚翠，犹陪落日泛秋声。\n世间无限丹青手，一片伤心画不成。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵晚望' AND p.poem_author = '高蟾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水龙吟·春恨', '陈亮', '宋代', '闹花深处层楼，画帘半卷东风软。春归翠陌，平莎茸嫩，垂杨金浅。迟日催花，淡云阁雨，轻寒轻暖。恨芳菲世界，游人未赏，都付与、莺和燕。 \n寂寞凭高念远。向南楼、一声归雁。金钗斗草，青丝勒马，风流云散。罗绶分香，翠绡对泪，几多幽怨。正销魂，又是疏烟淡月，子规声断。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水龙吟·春恨' AND p.poem_author = '陈亮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('孤雁 / 后飞雁', '杜甫', '唐代', '孤雁不饮啄，飞鸣声念群。\n谁怜一片影，相失万重云？\n望尽似犹见，哀多如更闻。\n野鸦无意绪，鸣噪自纷纷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '孤雁 / 后飞雁' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿骆氏亭寄怀崔雍崔衮', '李商隐', '唐代', '竹坞无尘水槛清，相思迢递隔重城。 \n秋阴不散霜飞晚，留得枯荷听雨声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿骆氏亭寄怀崔雍崔衮' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('下终南山过斛斯山人宿置酒', '李白', '唐代', '暮从碧山下，山月随人归。\n却顾所来径，苍苍横翠微。\n相携及田家，童稚开荆扉。\n绿竹入幽径，青萝拂行衣。\n欢言得所憩，美酒聊共挥。\n长歌吟松风，曲尽河星稀。\n我醉君复乐，陶然共忘机。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '下终南山过斛斯山人宿置酒' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花引·荆溪阻雪', '蒋捷', '宋代', '白鸥问我泊孤舟，是身留，是心留？心若留时，何事锁眉头？风拍小帘灯晕舞，对闲影，冷清清，忆旧游。\n旧游旧游今在否？花外楼，柳下舟。梦也梦也，梦不到，寒水空流。漠漠黄云，湿透木棉裘。都道无人愁似我，今夜雪，有梅花，似我愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花引·荆溪阻雪' AND p.poem_author = '蒋捷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏荆轲', '陶渊明', '魏晋', '燕丹善养士，志在报强嬴。\n招集百夫良，岁暮得荆卿。\n君子死知己，提剑出燕京；\n素骥鸣广陌，慷慨送我行。\n雄发指危冠，猛气冲长缨。\n饮饯易水上，四座列群英。\n渐离击悲筑，宋意唱高声。\n萧萧哀风逝，淡淡寒波生。\n商音更流涕，羽奏壮士惊。\n心知去不归，且有后世名。\n登车何时顾，飞盖入秦庭。\n凌厉越万里，逶迤过千城。\n图穷事自至，豪主正怔营。\n惜哉剑术疏，奇功遂不成。\n其人虽已没，千载有馀情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏荆轲' AND p.poem_author = '陶渊明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·邶风·燕燕', '佚名', '先秦', '燕燕于飞，差池其羽。之子于归，远送于野。瞻望弗及，泣涕如雨。\n燕燕于飞，颉之颃之。之子于归，远于将之。瞻望弗及，伫立以泣。\n燕燕于飞，下上其音。之子于归，远送于南。瞻望弗及，实劳我心。\n仲氏任只，其心塞渊。终温且惠，淑慎其身。先君之思，以勖寡人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·邶风·燕燕' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过华清宫绝句三首·其一', '杜牧', '唐代', '长安回望绣成堆，山顶千门次第开。\n一骑红尘妃子笑，无人知是荔枝来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '过华清宫绝句三首·其一' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乡思', '李觏', '宋代', '人言落日是天涯，望极天涯不见家。\n已恨碧山相阻隔，碧山还被暮云遮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乡思' AND p.poem_author = '李觏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行香子·七夕', '李清照', '宋代', '草际鸣蛩。惊落梧桐。正人间、天上愁浓。云阶月地，关锁千重。纵浮槎来，浮槎去，不相逢。 \n星桥鹊驾，经年才见，想离情、别恨难穷。牵牛织女，莫是离中。甚霎儿晴，霎儿雨，霎儿风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行香子·七夕' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别赋', '江淹', '南北朝', '黯然销魂者，唯别而已矣！况秦吴兮绝国，复燕宋兮千里。或春苔兮始生，乍秋风兮暂起。是以行子肠断，百感凄恻。风萧萧而异响，云漫漫而奇色。舟凝滞于水滨，车逶迟于山侧。棹容与而讵前，马寒鸣而不息。掩金觞而谁御，横玉柱而沾轼。居人愁卧，怳若有亡。日下壁而沉彩，月上轩而飞光。见红兰之受露，望青楸之离霜。巡层楹而空掩，抚锦幕而虚凉。知离梦之踯躅，意别魂之飞扬。故别虽一绪，事乃万族。\n\n　　至若龙马银鞍，朱轩绣轴，帐饮东都，送客金谷。琴羽张兮箫鼓陈，燕、赵歌兮伤美人，珠与玉兮艳暮秋，罗与绮兮娇上春。惊驷马之仰秣，耸渊鱼之赤鳞。造分手而衔涕，感寂寞而伤神。\n\n　　乃有剑客惭恩，少年报士，韩国赵厕，吴宫燕市。割慈忍爱，离邦去里，沥泣共诀，抆血相视。驱征马而不顾，见行尘之时起。方衔感于一剑，非买价于泉里。金石震而色变，骨肉悲而心死。\n\n　　或乃边郡未和，负羽从军。辽水无极，雁山参云。闺中风暖，陌上草薰。日出天而曜景，露下地而腾文。镜朱尘之照烂，袭青气之烟煴，攀桃李兮不忍别，送爱子兮沾罗裙。\n\n　　至如一赴绝国，讵相见期？视乔木兮故里，决北梁兮永辞，左右兮魄动，亲朋兮泪滋。可班荆兮憎恨，惟樽酒兮叙悲。值秋雁兮飞日，当白露兮下时，怨复怨兮远山曲，去复去兮长河湄。\n\n　　又若君居淄右，妾家河阳，同琼珮之晨照，共金炉之夕香。君结绶兮千里，惜瑶草之徒芳。惭幽闺之琴瑟，晦高台之流黄。春宫閟此青苔色，秋帐含此明月光，夏簟清兮昼不暮，冬釭凝兮夜何长！织锦曲兮泣已尽，回文诗兮影独伤。\n\n　　傥有华阴上士，服食还仙。术既妙而犹学，道已寂而未传。守丹灶而不顾，炼金鼎而方坚。驾鹤上汉，骖鸾腾天。暂游万里，少别千年。惟世间兮重别，谢主人兮依然。\n\n　　下有芍药之诗，佳人之歌，桑中卫女，上宫陈娥。春草碧色，春水渌波，送君南浦，伤如之何！至乃秋露如珠，秋月如圭，明月白露，光阴往来，与子之别，思心徘徊。\n\n　　是以别方不定，别理千名，有别必怨，有怨必盈。使人意夺神骇，心折骨惊，虽渊、云之墨妙，严、乐之笔精，金闺之诸彦，兰台之群英，赋有凌云之称，辨有雕龙之声，谁能摹暂离之状，写永诀之情着乎？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别赋' AND p.poem_author = '江淹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饮马长城窟行', '佚名', '两汉', '青青河畔草，绵绵思远道。\n远道不可思，宿昔梦见之。(宿昔 一作：夙昔)\n梦见在我傍，忽觉在他乡。\n他乡各异县，辗转不相见。\n枯桑知天风，海水知天寒。\n入门各自媚，谁肯相为言。\n客从远方来，遗我双鲤鱼。\n呼儿烹鲤鱼，中有尺素书。\n长跪读素书，书中竟何如。\n上言加餐食，下言长相忆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饮马长城窟行' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄生借书说', '袁枚', '清代', '黄生允修借书。随园主人授以书，而告之曰：\n\n　　书非借不能读也。子不闻藏书者乎？七略、四库，天子之书，然天子读书者有几？汗牛塞屋，富贵家之书，然富贵人读书者有几？其他祖父积，子孙弃者无论焉。非独书为然，天下物皆然。非夫人之物而强假焉，必虑人逼取，而惴惴焉摩玩之不已，曰：“今日存，明日去，吾不得而见之矣。”若业为吾所有，必高束焉，庋藏焉，曰“姑俟异日观”云尔。\n\n　　余幼好书，家贫难致。有张氏藏书甚富。往借，不与，归而形诸梦。其切如是。故有所览辄省记。通籍后，俸去书来，落落大满，素蟫灰丝时蒙卷轴。然后叹借者之用心专，而少时之岁月为可惜也！\n\n　　今黄生贫类予，其借书亦类予；惟予之公书与张氏之吝书若不相类。然则予固不幸而遇张乎，生固幸而遇予乎？知幸与不幸，则其读书也必专，而其归书也必速。\n\n　　为一说，使与书俱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄生借书说' AND p.poem_author = '袁枚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('御街行·秋日怀旧', '范仲淹', '宋代', '纷纷坠叶飘香砌。夜寂静，寒声碎。真珠帘卷玉楼空，天淡银河垂地。年年今夜，月华如练，长是人千里。\n愁肠已断无由醉，酒未到，先成泪。残灯明灭枕头欹，谙尽孤眠滋味。都来此事，眉间心上，无计相回避。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '御街行·秋日怀旧' AND p.poem_author = '范仲淹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('紫薇花', '杜牧', '唐代', '晓迎秋露一枝新，不占园中最上春。\n桃李无言又何在，向风偏笑艳阳人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '紫薇花' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上元竹枝词', '符曾', '清代', '桂花香馅裹胡桃，江米如珠井水淘。\n见说马家滴粉好，试灯风里卖元宵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上元竹枝词' AND p.poem_author = '符曾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荀巨伯探病友 / 荀巨伯探友', '刘义庆', '南北朝', '荀巨伯远看友人疾值胡贼攻郡，友人语巨伯曰：“吾今死矣，子可去。”巨伯曰：“远来相视，子令吾去，败义以求生，岂荀巨伯所行邪？”贼既至，谓巨伯曰：“大军至，一郡尽空，汝何男子，而敢独止？“巨伯曰：“友人有疾，不忍委之，宁以我身代友人命。”贼相谓曰：“我辈无义之人，而入有义之国。”遂班军而还，一郡并获全。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '荀巨伯探病友 / 荀巨伯探友' AND p.poem_author = '刘义庆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山中雪后', '郑燮', '清代', '晨起开门雪满山，雪晴云淡日光寒。\n檐流未滴梅花冻，一种清孤不等闲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山中雪后' AND p.poem_author = '郑燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感遇十二首·其一', '张九龄', '唐代', '兰叶春葳蕤，桂华秋皎洁。\n欣欣此生意，自尔为佳节。\n谁知林栖者，闻风坐相悦。\n草木有本心，何求美人折！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感遇十二首·其一' AND p.poem_author = '张九龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗七首·其一', '曹植', '魏晋', '高台多悲风，朝日照北林。\n之子在万里，江湖迥且深。\n方舟安可极，离思故难任！\n孤雁飞南游，过庭长哀吟。\n翘思慕远人，愿欲托遗音。\n形影忽不见，翩翩伤我心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗七首·其一' AND p.poem_author = '曹植';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬十月', '曹操', '魏晋', '孟冬十月，北风徘徊，天气肃清，繁霜霏霏。\n鵾鸡晨鸣，鸿雁南飞，鸷鸟潜藏，熊罴窟栖。\n钱镈停置，农收积场，逆旅整设，以通贾商。\n幸甚至哉！歌以咏志。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬十月' AND p.poem_author = '曹操';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暮秋独游曲江', '李商隐', '唐代', '荷叶生时春恨生，荷叶枯时秋恨成。 \n深知身在情长在，怅望江头江水声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暮秋独游曲江' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('子夜吴歌·夏歌', '李白', '唐代', '镜湖三百里，菡萏发荷花。\n五月西施采，人看隘若耶。\n回舟不待月，归去越王家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '子夜吴歌·夏歌' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('终身误', '曹雪芹', '清代', '都道是金玉良姻，俺只念木石前盟。\n空对着，山中高士晶莹雪；终不忘，世外仙姝寂寞林。\n叹人间，美中不足今方信：纵然是齐眉举案，到底意难平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '终身误' AND p.poem_author = '曹雪芹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿阳曲·江天暮雪', '马致远', '元代', '天将暮，雪乱舞，半梅花半飘柳絮。\n江上晚来堪画处，钓鱼人一蓑归去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿阳曲·江天暮雪' AND p.poem_author = '马致远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春游湖', '徐俯', '宋代', '双飞燕子几时回？夹岸桃花蘸水开。\n春雨断桥人不渡，小舟撑出柳阴来。(渡 一作：度)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春游湖' AND p.poem_author = '徐俯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贺新郎·同父见和再用韵答之', '辛弃疾', '宋代', '老大那堪说。似而今、元龙臭味，孟公瓜葛。我病君来高歌饮，惊散楼头飞雪。笑富贵千钧如发。硬语盘空谁来听？记当时、只有西窗月。重进酒，换鸣瑟。 \n事无两样人心别。问渠侬：神州毕竟，几番离合？汗血盐车无人顾，千里空收骏骨。正目断关河路绝。我最怜君中宵舞，道“男儿到死心如铁”。看试手，补天裂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贺新郎·同父见和再用韵答之' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月·世事短如春梦', '朱敦儒', '宋代', '世事短如春梦，人情薄似秋云。不须计较苦劳心，万事原来有命。\n幸遇三杯酒好，况逢一朵花新。片时欢笑且相亲，明日阴晴未定。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月·世事短如春梦' AND p.poem_author = '朱敦儒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·西都作', '朱敦儒', '宋代', '我是清都山水郎，天教分付与疏狂。曾批给雨支风券，累上留云借月章。\n诗万首，酒千觞。几曾着眼看侯王？玉楼金阙慵归去，且插梅花醉洛阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·西都作' AND p.poem_author = '朱敦儒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与浩初上人同看山寄京华亲故', '柳宗元', '唐代', '海畔尖山似剑铓，秋来处处割愁肠。 \n若为化得身千亿，散上峰头望故乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与浩初上人同看山寄京华亲故' AND p.poem_author = '柳宗元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白莲', '陆龟蒙', '唐代', '素蘤多蒙别艳欺，此花真合在瑶池。(真合 一作：端合)\n无情有恨何人觉？月晓风清欲堕时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白莲' AND p.poem_author = '陆龟蒙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清明二首', '杜甫', '唐代', '朝来新火起新烟，湖色春光净客船。\n绣羽衔花他自得，红颜骑竹我无缘。\n胡童结束还难有，楚女腰肢亦可怜。\n不见定王城旧处，长怀贾傅井依然。\n虚沾焦举为寒食，实藉严君卖卜钱。\n钟鼎山林各天性，浊醪粗饭任吾年。\n\n此身飘泊苦西东，右臂偏枯半耳聋。\n寂寂系舟双下泪，悠悠伏枕左书空。\n十年蹴踘将雏远，万里秋千习俗同。\n旅雁上云归紫塞，家人钻火用青枫。\n秦城楼阁烟花里，汉主山河锦绣中。\n春去春来洞庭阔，白苹愁杀白头翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清明二首' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('石钟山记', '苏轼', '宋代', '《水经》云：“彭蠡之口有石钟山焉。”郦元以为下临深潭，微风鼓浪，水石相搏，声如洪钟。是说也，人常疑之。今以钟磬置水中，虽大风浪不能鸣也，而况石乎！至唐李渤始访其遗踪，得双石于潭上，扣而聆之，南声函胡，北音清越，桴止响腾，余韵徐歇。自以为得之矣。然是说也，余尤疑之。石之铿然有声者，所在皆是也，而此独以钟名，何哉？\n\n　　元丰七年六月丁丑，余自齐安舟行适临汝，而长子迈将赴饶之德兴尉，送之至湖口，因得观所谓石钟者。寺僧使小童持斧，于乱石间择其一二扣之，硿硿焉。余固笑而不信也。至莫夜月明，独与迈乘小舟，至绝壁下。大石侧立千尺，如猛兽奇鬼，森然欲搏人；而山上栖鹘，闻人声亦惊起，磔磔云霄间；又有若老人咳且笑于山谷中者，或曰此鹳鹤也。余方心动欲还，而大声发于水上，噌吰如钟鼓不绝。舟人大恐。徐而察之，则山下皆石穴罅，不知其浅深，微波入焉，涵淡澎湃而为此也。舟回至两山间，将入港口，有大石当中流，可坐百人，空中而多窍，与风水相吞吐，有窾坎镗鞳之声，与向之噌吰者相应，如乐作焉。因笑谓迈曰：“汝识之乎？噌吰者，周景王之无射也；窾坎镗鞳者，魏庄子之歌钟也。古之人不余欺也！”\n\n　　事不目见耳闻，而臆断其有无，可乎？郦元之所见闻，殆与余同，而言之不详；士大夫终不肯以小舟夜泊绝壁之下，故莫能知；而渔工水师虽知而不能言。此世所以不传也。而陋者乃以斧斤考击而求之，自以为得其实。余是以记之，盖叹郦元之简，而笑李渤之陋也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '石钟山记' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('唐多令·芦叶满汀洲', '刘过', '宋代', '安远楼小集，侑觞歌板之姬黄其姓者，乞词于龙洲道人，为赋此《唐多令》。同柳阜之、刘去非、石民瞻、周嘉仲、陈孟参、孟容。时八月五日也。\n\n芦叶满汀洲，寒沙带浅流。二十年重过南楼。柳下系船犹未稳，能几日，又中秋。\n黄鹤断矶头，故人今在否？旧江山浑是新愁。欲买桂花同载酒，终不似，少年游。(在否 一作：在不)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '唐多令·芦叶满汀洲' AND p.poem_author = '刘过';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑子·恨君不似江楼月', '吕本中', '宋代', '恨君不似江楼月，南北东西，南北东西，只有相随无别离。\n恨君却似江楼月，暂满还亏，暂满还亏，待得团圆是几时？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑子·恨君不似江楼月' AND p.poem_author = '吕本中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六州歌头·少年侠气', '贺铸', '宋代', '少年侠气，交结五都雄。肝胆洞。毛发耸。立谈中。死生同。一诺千金重。推翘勇。矜豪纵。轻盖拥。联飞鞚。斗城东。轰饮酒垆，春色浮寒瓮。吸海垂虹。闲呼鹰嗾犬，白羽摘雕弓。狡穴俄空。乐匆匆。(闲呼 一作：间呼)\n似黄粱梦。辞丹凤。明月共。漾孤篷。官冗從。怀倥偬。落尘笼。簿书丛。鹖弁如云众。供粗用。忽奇功。笳鼓动。渔阳弄。思悲翁。不请长缨，系取天骄种。剑吼西风。恨登山临水，手寄七弦桐。目送归鸿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六州歌头·少年侠气' AND p.poem_author = '贺铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长相思·花似伊', '欧阳修', '宋代', '花似伊，柳似伊。花柳青春人别离。低头双泪垂。\n长江东，长江西。两岸鸳鸯两处飞。相逢知几时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长相思·花似伊' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寒食', '孟云卿', '唐代', '二月江南花满枝，他乡寒食远堪悲。\n贫居往往无烟火，不独明朝为子推。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寒食' AND p.poem_author = '孟云卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·周南·麟之趾', '佚名', '先秦', '麟之趾，振振公子，于嗟麟兮。\n麟之定，振振公姓，于嗟麟兮。\n麟之角，振振公族，于嗟麟兮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·周南·麟之趾' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('剑门道中遇微雨', '陆游', '宋代', '衣上征尘杂酒痕，远游无处不消魂。\n此身合是诗人未？细雨骑驴入剑门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '剑门道中遇微雨' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自遣', '罗隐', '唐代', '得即高歌失即休，多愁多恨亦悠悠。\n今朝有酒今朝醉，明日愁来明日愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自遣' AND p.poem_author = '罗隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜晴', '范成大', '宋代', '窗间梅熟落蒂，墙下笋成出林。\n连雨不知春去，一晴方觉夏深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜晴' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江村', '杜甫', '唐代', '清江一曲抱村流，长夏江村事事幽。\n自去自来堂上燕，相亲相近水中鸥。(堂上 一作：梁上)\n老妻画纸为棋局，稚子敲针作钓钩。\n但有故人供禄米，微躯此外更何求？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江村' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('从军行二首·其一', '王昌龄', '唐代', '大将军出战，白日暗榆关。\n三面黄金甲，单于破胆还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '从军行二首·其一' AND p.poem_author = '王昌龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·卫风·河广', '佚名', '先秦', '谁谓河广？一苇杭之。谁谓宋远？跂予望之。\n谁谓河广？曾不容刀。谁谓宋远？曾不崇朝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·卫风·河广' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·鄘风·君子偕老', '佚名', '先秦', '君子偕老，副笄六珈。委委佗佗，如山如河，象服是宜。子之不淑，云如之何？\n玼兮玼兮，其之翟也。鬒发如云，不屑髢也；玉之瑱也，象之揥也，扬且之皙也。胡然而天也？胡然而帝也？\n瑳兮瑳兮，其之展也。蒙彼绉絺，是绁袢也。子之清扬，扬且之颜也。展如之人兮，邦之媛也！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·鄘风·君子偕老' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新年', '无可', '唐代', '燃灯朝复夕，渐作长年身。\n紫阁未归日，青门又见春。\n掩关寒过尽，开定草生新。\n自有林中趣，谁惊岁去频。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新年' AND p.poem_author = '无可';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('君子于役', '佚名', '先秦', '君子于役，不知其期，曷至哉？鸡栖于埘，日之夕矣，羊牛下来。君子于役，如之何勿思！\n君子于役，不日不月，曷其有佸？鸡栖于桀，日之夕矣，羊牛下括。君子于役，苟无饥渴！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '君子于役' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔家傲·雪里已知春信至', '李清照', '宋代', '雪里已知春信至，寒梅点缀琼枝腻。香脸半开娇旖旎，当庭际，玉人浴出新妆洗。\n造化可能偏有意，故教明月玲珑地。共赏金尊沈绿蚁，莫辞醉，此花不与群花比。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔家傲·雪里已知春信至' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('母别子', '白居易', '唐代', '母别子，子别母，白日无光哭声苦。\n关西骠骑大将军，去年破虏新策勋。\n敕赐金钱二百万，洛阳迎得如花人。\n新人迎来旧人弃，掌上莲花眼中刺。\n迎新弃旧未足悲，悲在君家留两儿。\n一始扶行一初坐，坐啼行哭牵人衣。\n以汝夫妇新燕婉，使我母子生别离。\n不如林中乌与鹊，母不失雏雄伴雌。\n应似园中桃李树，花落随风子在枝。\n新人新人听我语，洛阳无限红楼女。\n但愿将军重立功，更有新人胜于汝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '母别子' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饮酒·其四', '陶渊明', '魏晋', '秋菊有佳色，裛露掇其英。\n泛此忘忧物，远我遗世情。\n一觞虽独尽，杯尽壶自倾。\n日入群动息，归鸟趋林鸣。\n啸傲东轩下，聊复得此生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饮酒·其四' AND p.poem_author = '陶渊明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十五从军行 / 十五从军征', '佚名', '两汉', '十五从军征，八十始得归。\n道逢乡里人，家中有阿谁？\n遥看是君家，松柏冢累累。\n兔从狗窦入，雉从梁上飞。\n中庭生旅谷，井上生旅葵。\n舂谷持作饭，采葵持作羹。\n羹饭一时熟，不知贻阿谁？\n出门东向望，泪落沾我衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十五从军行 / 十五从军征' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湖上', '徐元杰', '宋代', '花开红树乱莺啼，草长平湖白鹭飞。\n风日晴和人意好，夕阳箫鼓几船归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湖上' AND p.poem_author = '徐元杰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙·端午', '苏轼', '宋代', '轻汗微微透碧纨，明朝端午浴芳兰。流香涨腻满晴川。\n彩线轻缠红玉臂，小符斜挂绿云鬟。佳人相见一千年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙·端午' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙·浅画香膏拂紫绵', '陈克', '宋代', '浅画香膏拂紫绵。牡丹花重翠云偏。手挼梅子并郎肩。\n病起心情终是怯，困来模样不禁怜。旋移针线小窗前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙·浅画香膏拂紫绵' AND p.poem_author = '陈克';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('思帝乡·春日游', '韦庄', '唐代', '春日游，杏花吹满头。陌上谁家年少足风流？\n妾拟将身嫁与一生休。纵被无情弃，不能羞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '思帝乡·春日游' AND p.poem_author = '韦庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄人', '张泌', '唐代', '别梦依依到谢家，小廊回合曲阑斜。\n多情只有春庭月，犹为离人照落花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄人' AND p.poem_author = '张泌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春·恨', '郑燮', '清代', '花亦无知，月亦无聊，酒亦无灵。把夭桃斫断，煞他风景；鹦哥煮熟，佐我杯羹。焚砚烧书，椎琴裂画，毁尽文章抹尽名。荥阳郑，有慕歌家世，乞食风情。\n单寒骨相难更，笑席帽青衫太瘦生。看蓬门秋草，年年破巷，疏窗细雨，夜夜孤灯。难道天公，还箝恨口，不许长吁一两声？癫狂甚，取乌丝百幅，细写凄清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春·恨' AND p.poem_author = '郑燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('少年游·长安古道马迟迟', '柳永', '宋代', '长安古道马迟迟，高柳乱蝉嘶。夕阳岛外，秋风原上，目断四天垂。(岛 一作：鸟)\n归云一去无踪迹，何处是前期？狎兴生疏，酒徒萧索，不似少年时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '少年游·长安古道马迟迟' AND p.poem_author = '柳永';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苔', '袁枚', '清代', '白日不到处，青春恰自来。\n苔花如米小，也学牡丹开。(\'也\'学, 一作：亦)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苔' AND p.poem_author = '袁枚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红·翠幕深庭', '吴文英', '宋代', '翠幕深庭，露红晚、闲花自发。春不断、亭台成趣，翠阴蒙密。紫燕雏飞帘额静，金鳞影转池心阔。有花香、竹色赋闲情，供吟笔。 \n闲问字，评风月。时载酒，调冰雪。似初秋入夜，浅凉欺葛。人境不教车马近，醉乡莫放笙歌歇。倩双成、一曲紫云回，红莲折。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红·翠幕深庭' AND p.poem_author = '吴文英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留侯论', '苏轼', '宋代', '古之所谓豪杰之士者，必有过人之节。人情有所不能忍者，匹夫见辱，拔剑而起，挺身而斗，此不足为勇也。天下有大勇者，卒然临之而不惊，无故加之而不怒。此其所挟持者甚大，而其志甚远也。\n\n　　夫子房受书于圯上之老人也，其事甚怪；然亦安知其非秦之世，有隐君子者出而试之。观其所以微见其意者，皆圣贤相与警戒之义；而世不察，以为鬼物，亦已过矣。且其意不在书。\n\n　　当韩之亡，秦之方盛也，以刀锯鼎镬待天下之士。其平居无罪夷灭者，不可胜数。虽有贲、育，无所复施。夫持法太急者，其锋不可犯，而其势未可乘。子房不忍忿忿之心，以匹夫之力而逞于一击之间；当此之时，子房之不死者，其间不能容发，盖亦已危矣。\n\n　　千金之子，不死于盗贼，何者？其身之可爱，而盗贼之不足以死也。子房以盖世之才，不为伊尹、太公之谋，而特出于荆轲、聂政之计，以侥幸于不死，此圯上老人所为深惜者也。是故倨傲鲜腆而深折之。彼其能有所忍也，然后可以就大事，故曰：“孺子可教也。”\n\n　　楚庄王伐郑，郑伯肉袒牵羊以逆；庄王曰：“其君能下人，必能信用其民矣。”遂舍之。勾践之困于会稽，而归臣妾于吴者，三年而不倦。且夫有报人之志，而不能下人者，是匹夫之刚也。夫老人者，以为子房才有余，而忧其度量之不足，故深折其少年刚锐之气，使之忍小忿而就大谋。何则？非有生平之素，卒然相遇于草野之间，而命以仆妾之役，油然而不怪者，此固秦皇之所不能惊，而项籍之所不能怒也。\n\n　　观夫高祖之所以胜，而项籍之所以败者，在能忍与不能忍之间而已矣。项籍唯不能忍，是以百战百胜而轻用其锋；高祖忍之，养其全锋而待其弊，此子房教之也。当淮阴破齐而欲自王，高祖发怒，见于词色。由此观之，犹有刚强不忍之气，非子房其谁全之？\n\n　　太史公疑子房以为魁梧奇伟，而其状貌乃如妇人女子，不称其志气。呜呼！此其所以为子房欤！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留侯论' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('如梦令·春景', '秦观', '宋代', '莺嘴啄花红溜，燕尾点波绿皱。\n指冷玉笙寒，吹彻小梅春透。\n依旧，依旧，人与绿杨俱瘦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '如梦令·春景' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('野望', '杜甫', '唐代', '西山白雪三城戍，南浦清江万里桥。\n海内风尘诸弟隔，天涯涕泪一身遥。\n惟将迟暮供多病，未有涓埃答圣朝。(惟 通：唯)\n跨马出郊时极目，不堪人事日萧条。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '野望' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平调·其二', '李白', '唐代', '一枝红艳露凝香，云雨巫山枉断肠。\n借问汉宫谁得似，可怜飞燕倚新妆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平调·其二' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('妾薄命', '李白', '唐代', '汉帝重阿娇，贮之黄金屋。\n咳唾落九天，随风生珠玉。\n宠极爱还歇，妒深情却疏。\n长门一步地，不肯暂回车。\n雨落不上天，水覆难再收。\n君情与妾意，各自东西流。\n昔日芙蓉花，今成断根草。\n以色事他人，能得几时好。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '妾薄命' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙·残雪凝辉冷画屏', '纳兰性德', '清代', '残雪凝辉冷画屏，落梅横笛已三更，更无人处月胧明。\n我是人间惆怅客，知君何事泪纵横，断肠声里忆平生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙·残雪凝辉冷画屏' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诫外甥书', '诸葛亮', '魏晋', '夫志当存高远，慕先贤，绝情欲，弃凝滞，使庶几之志，揭然有所存，恻然有所感；忍屈伸，去细碎，广咨问，除嫌吝，虽有淹留，何损于美趣，何患于不济。若志不强毅，意不慷慨，徒碌碌滞于俗，默默束于情，永窜伏于凡庸，不免于下流矣！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诫外甥书' AND p.poem_author = '诸葛亮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清明日对酒', '高翥', '宋代', '南北山头多墓田，清明祭扫各纷然。\n纸灰飞作白蝴蝶，泪血染成红杜鹃。\n日落狐狸眠冢上，夜归儿女笑灯前。\n人生有酒须当醉，一滴何曾到九泉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清明日对酒' AND p.poem_author = '高翥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词·故国三千里', '张祜', '唐代', '故国三千里，深宫二十年。\n一声何满子，双泪落君前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词·故国三千里' AND p.poem_author = '张祜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早梅', '齐己', '唐代', '万木冻欲折，孤根暖独回。\n前村深雪里，昨夜一枝开。\n风递幽香出，禽窥素艳来。\n明年如应律，先发望春台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早梅' AND p.poem_author = '齐己';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白云泉', '白居易', '唐代', '天平山上白云泉，云自无心水自闲。\n何必奔冲山下去，更添波浪向人间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白云泉' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绝句' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贺新郎·别茂嘉十二弟', '辛弃疾', '宋代', '别茂嘉十二弟。鹈鴂、杜鹃实两种，见《离骚补注》\n绿树听鹈鴂。更那堪、鹧鸪声住，杜鹃声切。啼到春归无寻处，苦恨芳菲都歇。算未抵、人间离别。马上琵琶关塞黑，更长门、翠辇辞金阙。看燕燕，送归妾。 \n将军百战身名裂。向河梁、回头万里，故人长绝。易水萧萧西风冷，满座衣冠似雪。正壮士、悲歌未彻。啼鸟还知如许恨，料不啼清泪长啼血。谁共我，醉明月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贺新郎·别茂嘉十二弟' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵五题·石头城', '刘禹锡', '唐代', '山围故国周遭在，潮打空城寂寞回。\n淮水东边旧时月，夜深还过女墙来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵五题·石头城' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古艳歌', '佚名', '两汉', '茕茕白兔，东走西顾。\n衣不如新，人不如故。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古艳歌' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏意', '苏舜钦', '宋代', '别院深深夏席清，石榴开遍透帘明。(夏席清 一作：夏簟清)\n树阴满地日当午，梦觉流莺时一声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏意' AND p.poem_author = '苏舜钦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('佳人', '杜甫', '唐代', '绝代有佳人，幽居在空谷。\n自云良家子，零落依草木。\n关中昔丧乱，兄弟遭杀戮。\n官高何足论，不得收骨肉。\n世情恶衰歇，万事随转烛。\n夫婿轻薄儿，新人美如玉。\n合昏尚知时，鸳鸯不独宿。\n但见新人笑，那闻旧人哭。\n在山泉水清，出山泉水浊。\n侍婢卖珠回，牵萝补茅屋。\n摘花不插发，采柏动盈掬。\n天寒翠袖薄，日暮倚修竹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '佳人' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏牡丹', '陈与义', '宋代', '一自胡尘入汉关，十年伊洛路漫漫。\n青墩溪畔龙钟客，独立东风看牡丹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏牡丹' AND p.poem_author = '陈与义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寒夜', '杜耒', '宋代', '寒夜客来茶当酒，竹炉汤沸火初红。\n寻常一样窗前月，才有梅花便不同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寒夜' AND p.poem_author = '杜耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟行路难·其四', '鲍照', '南北朝', '泻水置平地，各自东西南北流。\n人生亦有命，安能行叹复坐愁？\n酌酒以自宽，举杯断绝歌路难。\n心非木石岂无感？吞声踯躅不敢言。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟行路难·其四' AND p.poem_author = '鲍照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋夜寄邱员外 / 秋夜寄丘二十二员外', '韦应物', '唐代', '怀君属秋夜，散步咏凉天。\n空山松子落，幽人应未眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋夜寄邱员外 / 秋夜寄丘二十二员外' AND p.poem_author = '韦应物';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长干行·其一', '李白', '唐代', '妾发初覆额，折花门前剧。\n郎骑竹马来，绕床弄青梅。\n同居长干里，两小无嫌猜，\n十四为君妇，羞颜未尝开。\n低头向暗壁，千唤不一回。\n十五始展眉，愿同尘与灰。\n常存抱柱信，岂上望夫台。\n十六君远行，瞿塘滟滪堆。\n五月不可触，猿声天上哀。(猿\'声\',一作：鸣)\n门前迟行迹，一一生绿苔。\n苔深不能扫，落叶秋风早。\n八月蝴蝶来，双飞西园草。\n感此伤妾心，坐愁红颜老。\n早晚下三巴，预将书报家。\n相迎不道远，直至长风沙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长干行·其一' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月·阻风山峰下', '张孝祥', '宋代', '满载一船秋色，平铺十里湖光。波神留我看斜阳，放起鳞鳞细浪。\n明日风回更好，今宵露宿何妨？水晶宫里奏霓裳，准拟岳阳楼上。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月·阻风山峰下' AND p.poem_author = '张孝祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凤凰台上忆吹箫·香冷金猊', '李清照', '宋代', '香冷金猊，被翻红浪，起来慵自梳头。任宝奁尘满，日上帘钩。生怕离怀别苦，多少事、欲说还休。新来瘦，非干病酒，不是悲秋。\n休休，这回去也，千万遍《阳关》，也则难留。念武陵人远，烟锁秦楼。惟有楼前流水，应念我、终日凝眸。凝眸处，从今又添，一段新愁。(版本一)\n\n香冷金猊，被翻红浪，起来人未梳头。任宝奁闲掩，日上帘钩。生怕闲愁暗恨，多少事、欲说还休。今年瘦，非干病酒，不是悲秋。\n明朝，者回去也，千万遍阳关，也即难留。念武陵春晚，云锁重楼。记取楼前绿水，应念我、终日凝眸。凝眸处，从今更数，几段新愁。(版本二)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凤凰台上忆吹箫·香冷金猊' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏为六绝句·其二', '杜甫', '唐代', '王杨卢骆当时体，轻薄为文哂未休。\n尔曹身与名俱灭，不废江河万古流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏为六绝句·其二' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('马嵬·其二', '李商隐', '唐代', '海外徒闻更九州，他生未卜此生休。\n空闻虎旅传宵柝，无复鸡人报晓筹。\n此日六军同驻马，当时七夕笑牵牛。\n如何四纪为天子，不及卢家有莫愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '马嵬·其二' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐·雨晴烟晚', '冯延巳', '五代', '雨晴烟晚。绿水新池满。双燕飞来垂柳院，小阁画帘高卷。\n黄昏独倚朱阑。西南新月眉弯。砌下落花风起，罗衣特地春寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐·雨晴烟晚' AND p.poem_author = '冯延巳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('端居', '李商隐', '唐代', '远书归梦两悠悠，只有空床敌素秋。 \n阶下青苔与红树，雨中寥落月中愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '端居' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谏逐客书', '李斯', '先秦', '臣闻吏议逐客，窃以为过矣。昔穆公求士，西取由余于戎，东得百里奚于宛，迎蹇叔于宋，来邳豹、公孙支于晋。此五子者，不产于秦，而穆公用之，并国二十，遂霸西戎。孝公用商鞅之法，移风易俗，民以殷盛，国以富强，百姓乐用，诸侯亲服，获楚、魏之师，举地千里，至今治强。惠王用张仪之计，拔三川之地，西并巴、蜀，北收上郡，南取汉中，包九夷，制鄢、郢，东据成皋之险，割膏腴之壤，遂散六国之纵，使之西面事秦，功施到今。昭王得范雎，废穰侯，逐华阳，强公室，杜私门，蚕食诸侯，使秦成帝业。此四君者，皆以客之功。由此观之，客何负于秦哉！向使四君却客而不内，疏士而不用，是使国无富利之实，而秦无强大之名也。\n　　今陛下致昆山之玉，有随和之宝，垂明月之珠，服太阿之剑，乘纤离之马，建翠凤之旗，树灵鼍之鼓。此数宝者，秦不生一焉，而陛下说之，何也？必秦国之所生然后可，则是夜光之璧，不饰朝廷；犀象之器，不为玩好；郑、卫之女不充后宫，而骏良駃騠不实外厩，江南金锡不为用，西蜀丹青不为采。所以饰后宫，充下陈，娱心意，说耳目者，必出于秦然后可，则是宛珠之簪，傅玑之珥，阿缟之衣，锦绣之饰不进于前，而随俗雅化，佳冶窈窕，赵女不立于侧也。夫击瓮叩缶弹筝搏髀，而歌呼呜呜快耳者，真秦之声也；《郑》、《卫》、《桑间》，《韶》、《虞》、《武》、《象》者，异国之乐也。今弃击瓮叩缶而就《郑》、《卫》，退弹筝而取《昭》、《虞》，若是者何也？快意当前，适观而已矣。今取人则不然。不问可否，不论曲直，非秦者去，为客者逐。然则是所重者在乎色乐珠玉，而所轻者在乎人民也。此非所以跨海内、制诸侯之术也。\n　　臣闻地广者粟多，国大者人众，兵强则士勇。是以泰山不让土壤，故能成其大；河海不择细流，故能就其深；王者不却众庶，故能明其德。是以地无四方，民无异国，四时充美，鬼神降福，此五帝三王之所以无敌也。今乃弃黔首以资敌国，却宾客以业诸侯，使天下之士退而不敢西向，裹足不入秦，此所谓“借寇兵而赍盗粮”者也。夫物不产于秦，可宝者多；士不产于秦，而愿忠者众。今逐客以资敌国，损民以益雠，内自虚而外树怨于诸侯，求国无危，不可得也。(泰山 一作：太山)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谏逐客书' AND p.poem_author = '李斯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春寒', '陈与义', '宋代', '二月巴陵日日风，春寒未了怯园公。\n海棠不惜胭脂色，独立蒙蒙细雨中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春寒' AND p.poem_author = '陈与义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻武均州报已复西京', '陆游', '宋代', '白发将军亦壮哉，西京昨夜捷书来。\n胡儿敢作千年计，天意宁知一日回。\n列圣仁恩深雨露，中兴赦令疾风雷。\n悬知寒食朝陵使，驿路梨花处处开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻武均州报已复西京' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金缕曲二首', '顾贞观', '清代', '寄吴汉槎宁古塔，以词代书，丙辰冬，寓京师千佛寺，冰雪中作。\n\n季子平安否？便归来，平生万事，那堪回首！行路悠悠谁慰藉，母老家贫子幼。记不起，从前杯酒。魑魅搏人应见惯，总输他，覆雨翻云手，冰与雪，周旋久。\n泪痕莫滴牛衣透，数天涯，依然骨肉，几家能够？比似红颜多命薄，更不如今还有。只绝塞，苦寒难受。廿载包胥承一诺，盼乌头马角终相救。置此札，君怀袖。\n\n我亦飘零久！十年来，深恩负尽，死生师友。宿昔齐名非忝窃，只看杜陵消瘦，曾不减，夜郎僝僽，薄命长辞知己别，问人生到此凄凉否？千万恨，为君剖。(只看 一作：试看)\n兄生辛未吾丁丑，共此时，冰霜摧折，早衰蒲柳。诗赋从今须少作，留取心魂相守。但愿得，河清人寿！归日急翻行戍稿，把空名料理传身后。言不尽，观顿首。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金缕曲二首' AND p.poem_author = '顾贞观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑子·荷花开后西湖好', '欧阳修', '宋代', '荷花开后西湖好，载酒来时。不用旌旗，前后红幢绿盖随。\n画船撑入花深处，香泛金卮。烟雨微微，一片笙歌醉里归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑子·荷花开后西湖好' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江城子', '秦观', '宋代', '清明天气醉游郎。莺儿狂。燕儿狂。翠盖红缨，道上往来忙。记得相逢垂柳下，雕玉珮，缕金裳。 \n春光还是旧春光。桃花香。李花香。浅白深红，一一斗新妆。惆怅惜花人不见，歌一阕，泪千行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江城子' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('墨萱图·其一', '王冕', '元代', '灿灿萱草花，罗生北堂下。\n南风吹其心，摇摇为谁吐？\n慈母倚门情，游子行路苦。\n甘旨日以疏，音问日以阻。\n举头望云林，愧听慧鸟语。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '墨萱图·其一' AND p.poem_author = '王冕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留别妻', '苏武', '两汉', '结发为夫妻，恩爱两不疑。\n欢娱在今夕，嬿婉及良时。\n征夫怀远路，起视夜何其？\n参辰皆已没，去去从此辞。\n行役在战场，相见未有期。\n握手一长叹，泪为生别滋。\n努力爱春华，莫忘欢乐时。\n生当复来归，死当长相思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留别妻' AND p.poem_author = '苏武';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('池州翠微亭', '岳飞', '宋代', '经年尘土满征衣，特特寻芳上翠微。\n好水好山看不足，马蹄催趁月明归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '池州翠微亭' AND p.poem_author = '岳飞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·林断山明竹隐墙', '苏轼', '宋代', '林断山明竹隐墙。乱蝉衰草小池塘。翻空白鸟时时见，照水红蕖细细香。\n村舍外，古城旁。杖藜徐步转斜阳。殷勤昨夜三更雨，又得浮生一日凉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·林断山明竹隐墙' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长安清明', '韦庄', '唐代', '蚤是伤春梦雨天，可堪芳草更芊芊。\n内官初赐清明火，上相闲分白打钱。\n紫陌乱嘶红叱拨，绿杨高映画秋千。\n游人记得承平事，暗喜风光似昔年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长安清明' AND p.poem_author = '韦庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早梅', '柳宗元', '唐代', '早梅发高树，迥映楚天碧。\n朔吹飘夜香，繁霜滋晓白。\n欲为万里赠，杳杳山水隔。\n寒英坐销落，何用慰远客。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早梅' AND p.poem_author = '柳宗元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春中喜王九相寻 / 晚春', '孟浩然', '唐代', '二月湖水清，家家春鸟鸣。林花扫更落，径草踏还生。 \n酒伴来相命，开尊共解酲。当杯已入手，歌妓莫停声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春中喜王九相寻 / 晚春' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('红梅', '王十朋', '宋代', '桃李莫相妒，夭姿元不同。\n犹余雪霜态，未肯十分红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '红梅' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('城南', '曾巩', '宋代', '雨过横塘水满堤，乱山高下路东西。\n一番桃李花开尽，惟有青青草色齐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '城南' AND p.poem_author = '曾巩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑子·九日', '纳兰性德', '清代', '深秋绝塞谁相忆，木叶萧萧。乡路迢迢。六曲屏山和梦遥。 佳时倍惜风光别，不为登高。只觉魂销。南雁归时更寂寥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑子·九日' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新年', '贾岛', '唐代', '嗟以龙钟身，如何岁复新。\n石门思隐久，铜镜强窥频。\n花发新移树，心知故国春。\n谁能平此恨，岂是北宗人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新年' AND p.poem_author = '贾岛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('种树郭橐驼传', '柳宗元', '唐代', '郭橐驼，不知始何名。病偻，隆然伏行，有类橐驼者，故乡人号之“驼”。驼闻之，曰：“甚善。名我固当。”因舍其名，亦自谓橐驼云。\n\n　　其乡曰丰乐乡，在长安西。驼业种树，凡长安豪富人为观游及卖果者，皆争迎取养。视驼所种树，或移徙，无不活，且硕茂，早实以蕃。他植者虽窥伺效慕，莫能如也。\n\n　　有问之，对曰：“橐驼非能使木寿且孳也，能顺木之天，以致其性焉尔。凡植木之性，其本欲舒，其培欲平，其土欲故，其筑欲密。既然已，勿动勿虑，去不复顾。其莳也若子，其置也若弃，则其天者全而其性得矣。故吾不害其长而已，非有能硕茂之也；不抑耗其实而已，非有能早而蕃之也。他植者则不然，根拳而土易，其培之也，若不过焉则不及。苟有能反是者，则又爱之太恩，忧之太勤，旦视而暮抚，已去而复顾，甚者爪其肤以验其生枯，摇其本以观其疏密，而木之性日以离矣。虽曰爱之，其实害之；虽曰忧之，其实仇之，故不我若也。吾又何能为哉！”\n\n　　问者曰：“以子之道，移之官理，可乎？”驼曰：“我知种树而已，官理，非吾业也。然吾居乡，见长人者好烦其令，若甚怜焉，而卒以祸。旦暮吏来而呼曰：‘官命促尔耕，勖尔植，督尔获，早缫而绪，早织而缕，字而幼孩，遂而鸡豚。’鸣鼓而聚之，击木而召之。吾小人辍飧饔以劳吏者，且不得暇，又何以蕃吾生而安吾性耶？故病且怠。若是，则与吾业者其亦有类乎？”\n\n　　问者曰：“嘻，不亦善夫！吾问养树，得养人术。”传其事以为官戒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '种树郭橐驼传' AND p.poem_author = '柳宗元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阁夜', '杜甫', '唐代', '岁暮阴阳催短景，天涯霜雪霁寒宵。\n五更鼓角声悲壮，三峡星河影动摇。\n野哭几家闻战伐，夷歌数处起渔樵。\n卧龙跃马终黄土，人事依依漫寂寥。(版本一)\n\n岁暮阴阳催短景，天涯霜雪霁寒宵。\n五更鼓角声悲壮，三峡星河影动摇。\n野哭千家闻战伐，夷歌数处起渔樵。\n卧龙跃马终黄土，人事音书漫寂寥。(版本二)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阁夜' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早冬', '白居易', '唐代', '十月江南天气好，可怜冬景似春华。\n霜轻未杀萋萋草，日暖初干漠漠沙。\n老柘叶黄如嫩树，寒樱枝白是狂花。\n此时却羡闲人醉，五马无由入酒家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早冬' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜居', '屈原', '先秦', '屈原既放，三年不得复见。竭知尽忠而蔽障于谗。心烦虑乱，不知所从。乃往见太卜郑詹尹曰：“余有所疑，愿因先生决之。”詹尹乃端策拂龟，曰：“君将何以教之？”\n\n　　屈原曰：“吾宁悃悃款款，朴以忠乎，将送往劳来，斯无穷乎？\n\n　　“宁诛锄草茅以力耕乎，将游大人以成名乎？宁正言不讳以危身乎，将从俗富贵以偷生乎？宁超然高举以保真乎，将哫訾栗斯，喔咿儒儿，以事妇人乎？宁廉洁正直以自清乎，将突梯滑稽，如脂如韦，以洁楹乎？\n\n　　“宁昂昂若千里之驹乎，将泛泛若水中之凫，与波上下，偷以全吾躯乎？宁与骐骥亢轭乎，将随驽马之迹乎？宁与黄鹄比翼乎，将与鸡鹜争食乎？\n\n　　“此孰吉孰凶？何去何从？\n\n　　“世溷浊而不清：蝉翼为重，千钧为轻；黄钟毁弃，瓦釜雷鸣；谗人高张，贤士无名。吁嗟默默兮，谁知吾之廉贞！”\n\n　　詹尹乃释策而谢曰：“夫尺有所短，寸有所长；物有所不足，智有所不明；数有所不逮，神有所不通。用君之心，行君之意。龟策诚不能知此事。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜居' AND p.poem_author = '屈原';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('潍县署中画竹呈年伯包大丞括 / 墨竹图题诗', '郑燮', '清代', '衙斋卧听萧萧竹，疑是民间疾苦声。\n些小吾曹州县吏，一枝一叶总关情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '潍县署中画竹呈年伯包大丞括 / 墨竹图题诗' AND p.poem_author = '郑燮';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '听筝' AND p.poem_author = '李端';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('始得西山宴游记', '柳宗元', '唐代', '自余为僇人，居是州，恒惴栗。其隟也，则施施而行，漫漫而游。日与其徒上高山，入深林，穷回溪，幽泉怪石，无远不到。到则披草而坐，倾壶而醉。醉则更相枕以卧，卧而梦。意有所极，梦亦同趣。觉而起，起而归；以为凡是州之山水有异态者，皆我有也，而未始知西山之怪特。\n\n　　今年九月二十八日，因坐法华西亭，望西山，始指异之。遂命仆人过湘江，缘染溪，斫榛莽，焚茅茷，穷山之高而止。攀援而登，箕踞而遨，则凡数州之土壤，皆在衽席之下。其高下之势，岈然洼然，若垤若穴，尺寸千里，攒蹙累积，莫得遁隐。萦青缭白，外与天际，四望如一。然后知是山之特立，不与培塿为类。悠悠乎与颢气俱，而莫得其涯；洋洋乎与造物者游，而不知其所穷。引觞满酌，颓然就醉，不知日之入。苍然暮色，自远而至，至无所见，而犹不欲归。心凝形释，与万化冥合。然后知吾向之未始游，游于是乎始。故为之文以志。是岁，元和四年也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '始得西山宴游记' AND p.poem_author = '柳宗元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('嫦娥奔月 / 嫦娥飞天', '刘安 撰', '两汉', '昔者，羿狩猎山中，遇姮娥于月桂树下。遂以月桂为证，成天作之合。\n\n　　逮至尧之时，十日并出。焦禾稼，杀草木，而民无所食。猰貐、凿齿、九婴、大风、封豖希、修蛇皆为民害。尧乃使羿诛凿齿于畴华之野，杀九婴于凶水之上，缴大风于青丘之泽，上射十日而下杀猰貐，断修蛇于洞庭，擒封豨于桑林。万民皆喜，置尧以为天子。\n\n　　羿请不死之药于西王母，托与姮娥。逢蒙往而窃之，窃之不成，欲加害姮娥。娥无以为计，吞不死药以升天。然不忍离羿而去，滞留月宫。广寒寂寥，怅然有丧，无以继之，遂催吴刚伐桂，玉兔捣药，欲配飞升之药，重回人间焉。\n\n　　羿闻娥奔月而去，痛不欲生。月母感念其诚，允娥于月圆之日与羿会于月桂之下。民间有闻其窃窃私语者众焉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '嫦娥奔月 / 嫦娥飞天' AND p.poem_author = '刘安 撰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑子·时光只解催人老', '晏殊', '宋代', '时光只解催人老，不信多情，长恨离亭，泪滴春衫酒易醒。\n梧桐昨夜西风急，淡月胧明，好梦频惊，何处高楼雁一声？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑子·时光只解催人老' AND p.poem_author = '晏殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢亭送别', '许浑', '唐代', '劳歌一曲解行舟，红叶青山水急流。 \n日暮酒醒人已远，满天风雨下西楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢亭送别' AND p.poem_author = '许浑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦江南·兰烬落', '皇甫松', '唐代', '兰烬落，屏上暗红蕉。闲梦江南梅熟日，夜船吹笛雨萧萧。人语驿边桥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梦江南·兰烬落' AND p.poem_author = '皇甫松';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('念奴娇·春情', '李清照', '宋代', '萧条庭院，又斜风细雨，重门须闭。宠柳娇花寒食近，种种恼人天气。险韵诗成，扶头酒醒，别是闲滋味。征鸿过尽，万千心事难寄。 \n楼上几日春寒，帘垂四面，玉阑干慵倚。被冷香消新梦觉，不许愁人不起。清露晨流，新桐初引，多少游春意。日高烟敛，更看今日晴未。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '念奴娇·春情' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题张十一旅舍三咏榴花 / 题榴花', '韩愈', '唐代', '五月榴花照眼明，枝间时见子初成。 \n可怜此地无车马，颠倒青苔落绛英。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题张十一旅舍三咏榴花 / 题榴花' AND p.poem_author = '韩愈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜夜曲', '沈约', '南北朝', '河汉纵且横，北斗横复直。\n星汉空如此，宁知心有忆？\n孤灯暧不明，寒机晓犹织。\n零泪向谁道，鸡鸣徒叹息。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜夜曲' AND p.poem_author = '沈约';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('明月何皎皎', '佚名', '两汉', '明月何皎皎，照我罗床帏。\n忧愁不能寐，揽衣起徘徊。\n客行虽云乐，不如早旋归。\n出户独彷徨，愁思当告谁！\n引领还入房，泪下沾裳衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '明月何皎皎' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('商颂·玄鸟', '佚名', '先秦', '天命玄鸟，降而生商，宅殷土芒芒。古帝命武汤，正域彼四方。\n\n方命厥后，奄有九有。商之先后，受命不殆，在武丁孙子。武丁孙子，武王靡不胜。\n\n龙旂十乘，大糦是承。邦畿千里，维民所止，肇域彼四海。\n\n四海来假，来假祁祁。景员维河。殷受命咸宜，百禄是何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '商颂·玄鸟' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绝句·书当快意读易尽', '陈师道', '宋代', '书当快意读易尽，客有可人期不来。\n世事相违每如此，好怀百岁几回开？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绝句·书当快意读易尽' AND p.poem_author = '陈师道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('师旷撞晋平公', '韩非', '先秦', '晋平公与群臣饮，饮酣，乃喟然叹曰：“莫乐为人君！惟其言而莫之违。”师旷侍坐于前，援琴撞之。公被衽而避，琴坏于壁。公曰：“太师谁撞？”师旷曰：“今者有小人言于侧者，故撞之。”公曰：“寡人也。”师旷曰：“哑！是非君人者之言也。”左右请除之。公曰：“释之，以为寡人戒。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '师旷撞晋平公' AND p.poem_author = '韩非';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杀驼破瓮', '伽腽肭', '南北朝', '昔有一人，于瓮中盛谷。骆驼入瓮食谷，首不得出。主人以为忧，无计可施。有一老人来语之，曰：“汝莫忧，吾有以教汝出。”主人亟问：“法何？”老人曰：“汝当斩驼头，自当出之。”主人以为妙，即依其语，以刀斩驼头。既杀驼，而复破瓮，如此痴人，为世人所笑。\n\n　　昔有一人，先瓮中盛谷。骆驼入头瓮中食谷，首不得出。既不得出，其人以为忧。有一老人来语之曰：“汝莫愁，吾教汝出，女当斩头，自能出之。”即用其语，以刀斩头。既杀驼，而复破瓮，如此痴人，世人所笑。\n\n　　曩有一人，先瓮中盛谷。骆驼入头瓮中食谷，首不得出。既不得出，其人患之。有一老父来语之曰：“女莫愁，吾教女出，女当斩头，自能出之。”即用其语，以刀斩头。既杀驼，复破瓮，如此痴人，世人所笑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '杀驼破瓮' AND p.poem_author = '伽腽肭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('牧童诗', '黄庭坚', '宋代', '骑牛远远过前村，短笛横吹隔陇闻。\n多少长安名利客，机关用尽不如君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '牧童诗' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·陌上柔桑破嫩芽', '辛弃疾', '宋代', '陌上柔桑破嫩芽，东邻蚕种已生些。平冈细草鸣黄犊，斜日寒林点暮鸦。\n山远近，路横斜，青旗沽酒有人家。城中桃李愁风雨，春在溪头荠菜花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·陌上柔桑破嫩芽' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病梅馆记', '龚自珍', '清代', '江宁之龙蟠，苏州之邓尉，杭州之西溪，皆产梅。或曰：“梅以曲为美，直则无姿；以欹为美，正则无景；以疏为美，密则无态。”固也。此文人画士，心知其意，未可明诏大号以绳天下之梅也；又不可以使天下之民斫直，删密，锄正，以夭梅病梅为业以求钱也。梅之欹之疏之曲，又非蠢蠢求钱之民能以其智力为也。有以文人画士孤癖之隐明告鬻梅者，斫其正，养其旁条，删其密，夭其稚枝，锄其直，遏其生气，以求重价，而江浙之梅皆病。文人画士之祸之烈至此哉！\n\n　　予购三百盆，皆病者，无一完者。既泣之三日，乃誓疗之：纵之顺之，毁其盆，悉埋于地，解其棕缚；以五年为期，必复之全之。予本非文人画士，甘受诟厉，辟病梅之馆以贮之。\n\n　　呜呼！安得使予多暇日，又多闲田，以广贮江宁、杭州、苏州之病梅，穷予生之光阴以疗梅也哉！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '病梅馆记' AND p.poem_author = '龚自珍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苦寒行', '曹操', '魏晋', '北上太行山，艰哉何巍巍！\n羊肠坂诘屈，车轮为之摧。\n树木何萧瑟，北风声正悲。\n熊罴对我蹲，虎豹夹路啼。\n溪谷少人民，雪落何霏霏！\n延颈长叹息，远行多所怀。\n我心何怫郁，思欲一东归。\n水深桥梁绝，中路正徘徊。\n迷惑失故路，薄暮无宿栖。\n行行日已远，人马同时饥。\n担囊行取薪，斧冰持作糜。\n悲彼《东山》诗，悠悠使我哀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苦寒行' AND p.poem_author = '曹操';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('遗爱寺', '白居易', '唐代', '弄石临溪坐，寻花绕寺行。\n时时闻鸟语，处处是泉声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '遗爱寺' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春宫曲' AND p.poem_author = '王昌龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天问', '屈原', '先秦', '曰：遂古之初，谁传道之？\n上下未形，何由考之？\n冥昭瞢暗，谁能极之？\n冯翼惟象，何以识之？\n明明暗暗，惟时何为？\n阴阳三合，何本何化？\n圜则九重，孰营度之？\n惟兹何功，孰初作之？\n斡维焉系，天极焉加？\n八柱何当，东南何亏？\n九天之际，安放安属？\n隅隈多有，谁知其数？\n天何所沓？十二焉分？\n日月安属？列星安陈？\n出自汤谷，次于蒙汜。\n自明及晦，所行几里？\n夜光何德，死则又育？\n厥利维何，而顾菟在腹？\n女岐无合，夫焉取九子？\n伯强何处？惠气安在？\n何阖而晦？何开而明？\n角宿未旦，曜灵安藏？\n不任汩鸿，师何以尚之？\n佥曰“何忧，何不课而行之？”\n鸱龟曳衔，鲧何听焉？\n顺欲成功，帝何刑焉？\n永遏在羽山，夫何三年不施？\n伯禹愎鲧，夫何以变化？\n纂就前绪，遂成考功。\n何续初继业，而厥谋不同？\n洪泉极深，何以窴之？\n地方九则，何以坟之？\n河海应龙？何尽何历？\n鲧何所营？禹何所成？\n康回冯怒，墬何故以东南倾？\n九州安错？川谷何洿？\n东流不溢，孰知其故？\n东西南北，其修孰多？\n南北顺椭，其衍几何？\n昆仑悬圃，其尻安在？\n增城九重，其高几里？\n四方之门，其谁从焉？\n西北辟启，何气通焉？\n日安不到？烛龙何照？\n羲和之未扬，若华何光？\n何所冬暖？何所夏寒？\n焉有石林？何兽能言？\n焉有虬龙，负熊以游？\n雄虺九首，鯈忽焉在？\n何所不死？长人何守？\n靡蓱九衢，枲华安居？\n灵蛇吞象，厥大何如？\n黑水玄趾，三危安在？\n延年不死，寿何所止？\n鲮鱼何所？鬿堆焉处？\n羿焉彃日？乌焉解羽？\n禹之力献功，降省下土四方。\n焉得彼嵞山女，而通之於台桑？\n闵妃匹合，厥身是继。\n胡维嗜不同味，而快鼌饱？\n启代益作后，卒然离蠥。\n何启惟忧，而能拘是达？\n皆归射鞫，而无害厥躬。\n何后益作革，而禹播降？\n启棘宾商，《九辨》《九歌》。\n何勤子屠母，而死分竟地？\n帝降夷羿，革孽夏民。\n胡射夫河伯，而妻彼雒嫔？\n冯珧利决，封豨是射。\n何献蒸肉之膏，而后帝不若？\n浞娶纯狐，眩妻爰谋。\n何羿之射革，而交吞揆之？\n阻穷西征，岩何越焉？\n化而为黄熊，巫何活焉？\n咸播秬黍，莆雚是营。\n何由并投，而鲧疾修盈？\n白蜺婴茀，胡为此堂？\n安得夫良药，不能固臧？\n天式从横，阳离爰死。\n大鸟何鸣，夫焉丧厥体？\n蓱号起雨，何以兴之？\n撰体协胁，鹿何膺之？\n鳌戴山抃，何以安之？\n释舟陵行，何之迁之？\n惟浇在户，何求于嫂？\n何少康逐犬，而颠陨厥首？\n女歧缝裳，而馆同爰止。\n何颠易厥首，而亲以逢殆？\n汤谋易旅，何以厚之？\n覆舟斟寻，何道取之？\n桀伐蒙山，何所得焉？\n妺嬉何肆，汤何殛焉？\n舜闵在家，父何以鳏？\n尧不姚告，二女何亲？\n厥萌在初，何所亿焉？\n璜台十成，谁所极焉？\n登立为帝，孰道尚之？\n女娲有体，孰制匠之？\n舜服厥弟，终然为害。\n何肆犬豕，而厥身不危败？\n吴获迄古，南岳是止。\n孰期去斯，得两男子？\n缘鹄饰玉，后帝是飨。\n何承谋夏桀，终以灭丧？\n帝乃降观，下逢伊挚。\n何条放致罚，而黎服大说？\n简狄在台，喾何宜？\n玄鸟致贻，女何喜？\n该秉季德，厥父是臧。\n胡终弊于有扈，牧夫牛羊？\n干协时舞，何以怀之？\n平胁曼肤，何以肥之？\n有扈牧竖，云何而逢？\n击床先出，其命何从？\n恒秉季德，焉得夫朴牛？\n何往营班禄，不但还来？\n昏微循迹，有狄不宁。\n何繁鸟萃棘，负子肆情？\n眩弟并淫，危害厥兄。\n何变化以作诈，而后嗣逢长？\n成汤东巡，有莘爰极。\n何乞彼小臣，而吉妃是得？\n水滨之木，得彼小子。\n夫何恶之，媵有莘之妇？\n汤出重泉，夫何辠尤？\n不胜心伐帝，夫谁使挑之？\n会朝争盟，何践吾期？\n苍鸟群飞，孰使萃之？\n列击纣躬，叔旦不嘉。\n何亲揆发足，周之命以咨嗟？\n授殷天下，其位安施？\n反成乃亡，其罪伊何？\n争遣伐器，何以行之？\n并驱击翼，何以将之？\n昭后成游，南土爰底。\n厥利惟何，逢彼白雉？\n穆王巧梅，夫何为周流？\n环理天下，夫何索求？\n妖夫曳炫，何号于市？\n周幽谁诛？焉得夫褒姒？\n天命反侧，何罚何佑？\n齐桓九会，卒然身杀。\n彼王纣之躬，孰使乱惑？\n何恶辅弼，谗谄是服？\n比干何逆，而抑沈之？\n雷开阿顺，而赐封之？\n何圣人之一德，卒其异方？\n梅伯受醢，箕子详狂？\n稷维元子，帝何竺之？\n投之于冰上，鸟何燠之？\n何冯弓挟矢，殊能将之？\n既惊帝切激，何逢长之？\n伯昌号衰，秉鞭作牧。\n何令彻彼岐社，命有殷国？\n迁藏就岐，何能依？\n殷有惑妇，何所讥？\n受赐兹醢，西伯上告。\n何亲就上帝罚，殷之命以不救？\n师望在肆，昌何识？\n鼓刀扬声，后何喜？\n武发杀殷，何所悒？\n载尸集战，何所急？\n伯林雉经，维其何故？\n何感天抑墬，夫谁畏惧？\n皇天集命，惟何戒之？\n受礼天下，又使至代之？\n初汤臣挚，后兹承辅。\n何卒官汤，尊食宗绪？\n勋阖梦生，少离散亡。\n何壮武历，能流厥严？\n彭铿斟雉，帝何飨？\n受寿永多，夫何久长？\n中央共牧，后何怒？\n蜂蛾微命，力何固？\n惊女采薇，鹿何佑？\n北至回水，萃何喜？\n兄有噬犬，弟何欲？\n易之以百两，卒无禄？\n薄暮雷电，归何忧？\n厥严不奉，帝何求？\n伏匿穴处，爰何云？\n荆勋作师，夫何长？\n悟过改更，我又何言？\n吴光争国，久余是胜。\n何环穿自闾社丘陵，爰出子文？\n吾告堵敖以不长。\n何试上自予，忠名弥彰？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天问' AND p.poem_author = '屈原';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行香子·述怀', '苏轼', '宋代', '清夜无尘。月色如银。酒斟时、须满十分。浮名浮利，虚苦劳神。叹隙中驹，石中火，梦中身。\n虽抱文章，开口谁亲。且陶陶、乐尽天真。几时归去，作个闲人。对一张琴，一壶酒，一溪云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行香子·述怀' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐·留人不住', '晏几道', '宋代', '留人不住，醉解兰舟去。一棹碧涛春水路，过尽晓莺啼处。\n渡头杨柳青青，枝枝叶叶离情。此后锦书休寄，画楼云雨无凭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐·留人不住' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金谷园' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苏溪亭', '戴叔伦', '唐代', '苏溪亭上草漫漫，谁倚东风十二阑。 \n燕子不归春事晚，一汀烟雨杏花寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苏溪亭' AND p.poem_author = '戴叔伦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又呈吴郎', '杜甫', '唐代', '堂前扑枣任西邻，无食无儿一妇人。\n不为困穷宁有此？只缘恐惧转须亲。\n即防远客虽多事，便插疏篱却甚真。\n已诉征求贫到骨，正思戎马泪盈巾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又呈吴郎' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长相思·其二', '李白', '唐代', '日色欲尽花含烟，月明欲素愁不眠。(欲素 一作：如素)\n赵瑟初停凤凰柱，蜀琴欲奏鸳鸯弦。\n此曲有意无人传，愿随春风寄燕然。\n忆君迢迢隔青天，昔日横波目，今作流泪泉。\n不信妾断肠，归来看取明镜前。(断肠 一作：肠断)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长相思·其二' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春愁', '丘逢甲', '清代', '春愁难遣强看山，往事惊心泪欲潸。\n四百万人同一哭，去年今日割台湾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春愁' AND p.poem_author = '丘逢甲';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '遣怀' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一七令·茶', '元稹', '唐代', '茶。\n香叶，嫩芽。\n慕诗客，爱僧家。\n碾雕白玉，罗织红纱。\n铫煎黄蕊色，碗转曲尘花。\n夜后邀陪明月，晨前独对朝霞。\n洗尽古今人不倦，将知醉后岂堪夸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '一七令·茶' AND p.poem_author = '元稹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绝句四首', '杜甫', '唐代', '堂西长笋别开门，堑北行椒却背村。\n梅熟许同朱老吃，松高拟对阮生论。\n\n欲作鱼梁云复湍，因惊四月雨声寒。\n青溪先有蛟龙窟，竹石如山不敢安。\n\n两个黄鹂鸣翠柳，一行白鹭上青天。\n窗含西岭千秋雪，门泊东吴万里船。\n\n药条药甲润青青，色过棕亭入草亭。\n苗满空山惭取誉，根居隙地怯成形。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绝句四首' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丰乐亭记', '欧阳修', '宋代', '修既治滁之明年，夏，始饮滁水而甘。问诸滁人，得于州南百步之远。其上则丰山，耸然而特立；下则幽谷，窈然而深藏；中有清泉，滃然而仰出。俯仰左右，顾而乐之。于是疏泉凿石，辟地以为亭，而与滁人往游其间。\n\n　　滁于五代干戈之际，用武之地也。昔太祖皇帝，尝以周师破李景兵十五万于清流山下，生擒其皇甫辉、姚凤于滁东门之外，遂以平滁。修尝考其山川，按其图记，升高以望清流之关，欲求辉、凤就擒之所。而故老皆无在也，盖天下之平久矣。自唐失其政，海内分裂，豪杰并起而争，所在为敌国者，何可胜数？及宋受天命，圣人出而四海一。向之凭恃险阻，铲削消磨，百年之间，漠然徒见山高而水清。欲问其事，而遗老尽矣！\n\n　　今滁介江淮之间，舟车商贾、四方宾客之所不至，民生不见外事，而安于畎亩衣食，以乐生送死。而孰知上之功德，休养生息，涵煦于百年之深也。\n\n　　修之来此，乐其地僻而事简，又爱其俗之安闲。既得斯泉于山谷之间，乃日与滁人仰而望山，俯而听泉。掇幽芳而荫乔木，风霜冰雪，刻露清秀，四时之景，无不可爱。又幸其民乐其岁物之丰成，而喜与予游也。因为本其山川，道其风俗之美，使民知所以安此丰年之乐者，幸生无事之时也。\n\n　　夫宣上恩德，以与民共乐，刺史之事也。遂书以名其亭焉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丰乐亭记' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('地震', '蒲松龄', '清代', '康熙七年六月十七日戌刻，地大震。余适客稷下，方与表兄李笃之对烛饮。忽闻有声如雷，自东南来，向西北去。众骇异，不解其故。俄而几案摆簸，酒杯倾覆；屋梁椽柱，错折有声。相顾失色。久之，方知地震，各疾趋出。见楼阁房舍，仆而复起；墙倾屋塌之声，与儿啼女号，喧如鼎沸。\n\n　　人眩晕不能立，坐地上，随地转侧。河水倾泼丈余，鸡鸣犬吠满城中。逾一时许，始稍定。视街上，则男女裸聚，竞相告语，并忘其未衣也。后闻某处井倾仄，不可汲；某家楼台南北易向；栖霞山裂；沂水陷穴，广数亩。此真非常之奇变也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '地震' AND p.poem_author = '蒲松龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登徒子好色赋', '宋玉', '先秦', '大夫登徒子侍于楚王，短宋玉曰："玉为人体貌闲丽，口多微辞，又性好色。愿王勿与出入后宫。"　\n　　王以登徒子之言问宋玉。玉曰："体貌闲丽，所受于天也；口多微辞，所学于师也；至于好色，臣无有也。"王曰："子不好色，亦有说乎？有说则止，无说则退。"玉曰："天下之佳人莫若楚国，楚国之丽者莫若臣里，臣里之美者莫若臣东家之子。东家之子，增之一分则太长，减之一分则太短 ；著粉则太白，施朱则太赤；眉如翠羽，肌如白雪；腰如束素，齿如含贝；嫣然一笑，惑阳城，迷下蔡。然此女登墙窥臣三年，至今未许也。登徒子则不然：其妻蓬头挛耳，齞唇历齿，旁行踽偻，又疥且痔。登徒子悦之，使有五子。王孰察之，谁为好色者矣。"\n　　是时，秦章华大夫在侧，因进而称曰："今夫宋玉盛称邻之女，以为美色，愚乱之邪；臣自以为守德，谓不如彼矣。且夫南楚穷巷之妾，焉足为大王言乎?若臣之陋，目所曾睹者，未敢云也。"王曰："试为寡人说之。"大夫曰："唯唯。臣少曾远游，周览九土，足历五都。出咸阳、熙邯郸，从容郑、卫、溱 、洧之间 。是时向春之末 ，迎夏之阳，鸧鹒喈喈，群女出桑。此郊之姝，华色含光，体美容冶，不待饰装。臣观其丽者，因称诗曰：\'遵大路兮揽子祛\'。赠以芳华辞甚妙。于是处子怳若有望而不来，忽若有来而不见。意密体疏，俯仰异观；含喜微笑，窃视流眄。复称诗曰：\'寐春风兮发鲜荣，洁斋俟兮惠音声，赠我如此兮不如无生。\'因迁延而辞避。盖徒以微辞相感动。精神相依凭；目欲其颜，心顾其义，扬《诗》守礼，终不过差，故足称也。"\n　　于是楚王称善，宋玉遂不退。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登徒子好色赋' AND p.poem_author = '宋玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七哀诗三首·其一', '王粲', '魏晋', '西京乱无象，豺虎方遘患。\n复弃中国去，委身适荆蛮。\n亲戚对我悲，朋友相追攀。\n出门无所见，白骨蔽平原。\n路有饥妇人，抱子弃草间。\n顾闻号泣声，挥涕独不还。\n“未知身死处，何能两相完？”\n驱马弃之去，不忍听此言。\n南登霸陵岸，回首望长安，\n悟彼下泉人，喟然伤心肝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七哀诗三首·其一' AND p.poem_author = '王粲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行路难·其三', '李白', '唐代', '有耳莫洗颍川水，有口莫食首阳蕨。\n含光混世贵无名，何用孤高比云月？\n吾观自古贤达人，功成不退皆殒身。\n子胥既弃吴江上，屈原终投湘水滨。\n陆机雄才岂自保？李斯税驾苦不早。\n华亭鹤唳讵可闻？上蔡苍鹰何足道？\n君不见吴中张翰称达生，秋风忽忆江东行。\n且乐生前一杯酒，何须身后千载名？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行路难·其三' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('村行', '王禹偁', '宋代', '马穿山径菊初黄，信马悠悠野兴长。\n万壑有声含晚籁，数峰无语立斜阳。\n棠梨叶落胭脂色，荞麦花开白雪香。\n何事吟余忽惆怅，村桥原树似吾乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '村行' AND p.poem_author = '王禹偁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·豳风·七月', '佚名', '先秦', '七月流火，九月授衣。一之日觱发，二之日栗烈。无衣无褐，何以卒岁。三之日于耜，四之日举趾。同我妇子，馌彼南亩，田畯至喜。\n\n　　七月流火，九月授衣。春日载阳，有鸣仓庚。女执懿筐，遵彼微行，爰求柔桑。春日迟迟，采蘩祁祁。女心伤悲，殆及公子同归。\n\n　　七月流火，八月萑苇。蚕月条桑，取彼斧斨，以伐远扬，猗彼女桑。七月鸣鵙，八月载绩。载玄载黄，我朱孔阳，为公子裳。\n\n　　四月秀葽，五月鸣蜩。八月其获，十月陨箨。一之日于貉，取彼狐狸，为公子裘。二之日其同，载缵武功，言私其豵，献豜于公。\n\n　　五月斯螽动股，六月莎鸡振羽，七月在野，八月在宇，九月在户，十月蟋蟀入我床下。穹窒熏鼠，塞向墐户。嗟我妇子，曰为改岁，入此室处。\n\n　　六月食郁及薁，七月亨葵及菽，八月剥枣，十月获稻，为此春酒，以介眉寿。七月食瓜，八月断壶，九月叔苴，采荼薪樗，食我农夫。\n\n　　九月筑场圃，十月纳禾稼。黍稷重穋，禾麻菽麦。嗟我农夫，我稼既同，上入执宫功。昼尔于茅，宵尔索綯。亟其乘屋，其始播百谷。\n\n　　二之日凿冰冲冲，三之日纳于凌阴。四之日其蚤，献羔祭韭。九月肃霜，十月涤场。朋酒斯飨，曰杀羔羊。跻彼公堂，称彼兕觥，万寿无疆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·豳风·七月' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('捣练子令·深院静', '李煜', '五代', '深院静，小庭空，断续寒砧断续风。\n无奈夜长人不寐，数声和月到帘栊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '捣练子令·深院静' AND p.poem_author = '李煜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗七首·其四', '曹植', '魏晋', '南国有佳人，容华若桃李。\n朝游江北岸，夕宿潇湘沚。\n时俗薄朱颜，谁为发皓齿？\n俯仰岁将暮，荣耀难久恃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗七首·其四' AND p.poem_author = '曹植';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('于长安归还扬州九月九日行薇山亭赋韵 / 长安九日诗', '江总', '南北朝', '心逐南云逝，形随北雁来。\n故乡篱下菊，今日几花开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '于长安归还扬州九月九日行薇山亭赋韵 / 长安九日诗' AND p.poem_author = '江总';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('生年不满百', '佚名', '两汉', '生年不满百，常怀千岁忧。\n昼短苦夜长，何不秉烛游！\n为乐当及时，何能待来兹？\n愚者爱惜费，但为後世嗤。\n仙人王子乔，难可与等期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '生年不满百' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古怨别', '孟郊', '唐代', '飒飒秋风生，愁人怨离别。\n含情两相向，欲语气先咽。\n心曲千万端，悲来却难说。\n别后唯所思，天涯共明月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古怨别' AND p.poem_author = '孟郊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('孔子世家赞', '司马迁', '两汉', '太史公曰：《诗》有之：“高山仰止，景行行止。”虽不能至，然心乡往之。余读孔氏书，想见其为人。适鲁，观仲尼庙堂车服礼器，诸生以时习礼其家，余祗回留之不能去云。天下君王至于贤人众矣，当时则荣，没则已焉。孔子布衣，传十余世，学者宗之。自天子王侯，中国言《六艺》者折中于夫子，可谓至圣矣！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '孔子世家赞' AND p.poem_author = '司马迁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头·金山观月', '张孝祥', '宋代', '江山自雄丽，风露与高寒。寄声月姊，借我玉鉴此中看。幽壑鱼龙悲啸，倒影星辰摇动，海气夜漫漫。涌起白银阙，危驻紫金山。 \n表独立，飞霞佩，切云冠。漱冰濯雪，眇视万里一毫端。回首三山何处，闻道群仙笑我，要我欲俱还。挥手从此去，翳凤更骖鸾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头·金山观月' AND p.poem_author = '张孝祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观游鱼', '白居易', '唐代', '绕池闲步看鱼游，正值儿童弄钓舟。 \n一种爱鱼心各异，我来施食尔垂钩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观游鱼' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苦昼短', '李贺', '唐代', '飞光飞光，劝尔一杯酒。\n吾不识青天高，黄地厚。\n唯见月寒日暖，来煎人寿。\n食熊则肥，食蛙则瘦。\n神君何在？太一安有？\n天东有若木，下置衔烛龙。\n吾将斩龙足，嚼龙肉，使之朝不得回，夜不得伏。\n自然老者不死，少者不哭。\n何为服黄金、吞白玉？\n谁似任公子，云中骑碧驴？\n刘彻茂陵多滞骨，嬴政梓棺费鲍鱼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苦昼短' AND p.poem_author = '李贺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝉', '李商隐', '唐代', '本以高难饱，徒劳恨费声。\n五更疏欲断，一树碧无情。\n薄宦梗犹泛，故园芜已平。\n烦君最相警，我亦举家清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝉' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荷花', '石涛', '清代', '荷叶五寸荷花娇，贴波不碍画船摇；\n相到薰风四五月，也能遮却美人腰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荷花' AND p.poem_author = '石涛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平调·名花倾国两相欢', '李白', '唐代', '名花倾国两相欢，常得君王带笑看。\n解释春风无限恨，沉香亭北倚栏杆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平调·名花倾国两相欢' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满庭芳·蜗角虚名', '苏轼', '宋代', '蜗角虚名，蝇头微利，算来著甚干忙。事皆前定，谁弱又谁强。且趁闲身未老，尽放我、些子疏狂。百年里，浑教是醉，三万六千场。(尽放我 一作：须放我) \n思量。能几许，忧愁风雨，一半相妨，又何须，抵死说短论长。幸对清风皓月，苔茵展、云幕高张。江南好，千钟美酒，一曲满庭芳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满庭芳·蜗角虚名' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('社日', '王驾', '唐代', '鹅湖山下稻粱肥，豚栅鸡栖半掩扉。 \n桑柘影斜春社散，家家扶得醉人归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '社日' AND p.poem_author = '王驾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春雨', '李商隐', '唐代', '怅卧新春白袷衣，白门寥落意多违。\n红楼隔雨相望冷，珠箔飘灯独自归。\n远路应悲春晼晚，残霄犹得梦依稀。\n玉珰缄札何由达，万里云罗一雁飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春雨' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('进学解', '韩愈', '唐代', '国子先生晨入太学，招诸生立馆下，诲之曰：“业精于勤，荒于嬉；行成于思，毁于随。方今圣贤相逢，治具毕张。拔去凶邪，登崇畯良。占小善者率以录，名一艺者无不庸。爬罗剔抉，刮垢磨光。盖有幸而获选，孰云多而不扬？诸生业患不能精，无患有司之不明；行患不能成，无患有司之不公。”\n\n　　言未既，有笑于列者曰：“先生欺余哉！弟子事先生，于兹有年矣。先生口不绝吟于六艺之文，手不停披于百家之编。纪事者必提其要，纂言者必钩其玄。贪多务得，细大不捐。焚膏油以继晷，恒兀兀以穷年。先生之业，可谓勤矣。\n\n　　觝排异端，攘斥佛老。补苴罅漏，张皇幽眇。寻坠绪之茫茫，独旁搜而远绍。障百川而东之，回狂澜于既倒。先生之于儒，可谓有劳矣。\n\n　　沉浸醲郁，含英咀华，作为文章，其书满家。上规姚姒，浑浑无涯；周诰、殷《盘》，佶屈聱牙；《春秋》谨严，《左氏》浮夸；《易》奇而法，《诗》正而葩；下逮《庄》、《骚》，太史所录；子云，相如，同工异曲。先生之于文，可谓闳其中而肆其外矣。\n\n　　少始知学，勇于敢为；长通于方，左右具宜。先生之于为人，可谓成矣。\n\n　　然而公不见信于人，私不见助于友。跋前踬后，动辄得咎。暂为御史，遂窜南夷。三年博士，冗不见治。命与仇谋，取败几时。冬暖而儿号寒，年丰而妻啼饥。头童齿豁，竟死何裨。不知虑此，而反教人为？”\n\n　　先生曰：“吁，子来前！夫大木为杗，细木为桷，欂栌、侏儒，椳、闑、扂、楔，各得其宜，施以成室者，匠氏之工也。玉札、丹砂，赤箭、青芝，牛溲、马勃，败鼓之皮，俱收并蓄，待用无遗者，医师之良也。登明选公，杂进巧拙，纡馀为妍，卓荦为杰，校短量长，惟器是适者，宰相之方也。昔者孟轲好辩，孔道以明，辙环天下，卒老于行。荀卿守正，大论是弘，逃谗于楚，废死兰陵。是二儒者，吐辞为经，举足为法，绝类离伦，优入圣域，其遇于世何如也？今先生学虽勤而不繇其统，言虽多而不要其中，文虽奇而不济于用，行虽修而不显于众。犹且月费俸钱，岁靡廪粟；子不知耕，妇不知织；乘马从徒，安坐而食。踵常途之役役，窥陈编以盗窃。然而圣主不加诛，宰臣不见斥，兹非其幸欤？动而得谤，名亦随之。投闲置散，乃分之宜。若夫商财贿之有亡，计班资之崇庳，忘己量之所称，指前人之瑕疵，是所谓诘匠氏之不以杙为楹，而訾医师以昌阳引年，欲进其豨苓也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '进学解' AND p.poem_author = '韩愈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('富春至严陵山水甚佳', '纪昀', '清代', '浓似春云淡似烟，参差绿到大江边。\n斜阳流水推篷坐，翠色随人欲上船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '富春至严陵山水甚佳' AND p.poem_author = '纪昀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿山寺', '贾岛', '唐代', '众岫耸寒色，精庐向此分。\n流星透疏木，走月逆行云。(疏木 一作：疏水)\n绝顶人来少，高松鹤不群。\n一僧年八十，世事未曾闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿山寺' AND p.poem_author = '贾岛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山中与幽人对酌', '李白', '唐代', '两人对酌山花开，一杯一杯复一杯。\n我醉欲眠卿且去，明朝有意抱琴来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山中与幽人对酌' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('摽有梅', '佚名', '先秦', '摽有梅，其实七兮。求我庶士，迨其吉兮。\n摽有梅，其实三兮。求我庶士，迨其今兮。\n摽有梅，顷筐塈之。求我庶士，迨其谓之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '摽有梅' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑子·明月多情应笑我', '纳兰性德', '清代', '明月多情应笑我，笑我如今。辜负春心，独自闲行独自吟。\n近来怕说当时事，结遍兰襟。月浅灯深，梦里云归何处寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑子·明月多情应笑我' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('断句', '苏麟', '宋代', '近水楼台先得月，向阳花木易为春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '断句' AND p.poem_author = '苏麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天末怀李白', '杜甫', '唐代', '凉风起天末，君子意如何。\n鸿雁几时到，江湖秋水多。\n文章憎命达，魑魅喜人过。\n应共冤魂语，投诗赠汨罗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天末怀李白' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头·游览', '黄庭坚', '宋代', '瑶草一何碧，春入武陵溪。溪上桃花无数，枝上有黄鹂。我欲穿花寻路，直入白云深处，浩气展虹霓。只恐花深里，红露湿人衣。\n坐玉石，倚玉枕，拂金徽。谪仙何处？无人伴我白螺杯。我为灵芝仙草，不为朱唇丹脸，长啸亦何为？醉舞下山去，明月逐人归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头·游览' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再游玄都观', '刘禹锡', '唐代', '百亩庭中半是苔，桃花净尽菜花开。\n种桃道士归何处，前度刘郎今又来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再游玄都观' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酌贪泉', '吴隐之', '魏晋', '古人云此水，一歃怀千金。\n试使夷齐饮，终当不易心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酌贪泉' AND p.poem_author = '吴隐之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小雅·白驹', '佚名', '先秦', '皎皎白驹，食我场苗。絷之维之，以永今朝。所谓伊人，于焉逍遥？\n皎皎白驹，食我场藿。絷之维之，以永今夕。所谓伊人，于焉嘉客？\n皎皎白驹，贲然来思。尔公尔侯，逸豫无期？慎尔优游，勉尔遁思。\n皎皎白驹，在彼空谷。生刍一束，其人如玉。毋金玉尔音，而有遐心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小雅·白驹' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上堂开示颂', '黄蘖禅师', '唐代', '尘劳迥脱事非常，紧把绳头做一场。\n不经一番寒彻骨，怎得梅花扑鼻香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上堂开示颂' AND p.poem_author = '黄蘖禅师';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('摊破浣溪沙·菡萏香销翠叶残', '李璟', '五代', '菡萏香销翠叶残，西风愁起绿波间。还与韶光共憔悴，不堪看。\n细雨梦回鸡塞远，小楼吹彻玉笙寒。多少泪珠何限恨，倚栏干。(栏 通：阑) (何限恨 一作：无限恨)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '摊破浣溪沙·菡萏香销翠叶残' AND p.poem_author = '李璟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('对雪', '高骈', '唐代', '六出飞花入户时，坐看青竹变琼枝。\n如今好上高楼望，盖尽人间恶路岐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '对雪' AND p.poem_author = '高骈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('落花', '朱淑真', '宋代', '连理枝头花正开，妒花风雨便相催。\n愿教青帝常为主，莫遣纷纷点翠苔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '落花' AND p.poem_author = '朱淑真';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汉宫春·梅', '晁冲之', '宋代', '潇洒江梅，向竹梢疏处，横两三枝。东君也不爱惜，雪压霜欺。无情燕子，怕春寒、轻失花期。却是有，年年塞雁，归来曾见开时。 \n清浅小溪如练，问玉堂何似，茅舍疏篱。伤心故人去后，冷落新诗。微云淡月，对江天、分付他谁。空自忆，清香未减，风流不在人知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汉宫春·梅' AND p.poem_author = '晁冲之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春题湖上', '白居易', '唐代', '湖上春来似画图，乱峰围绕水平铺。\n松排山面千重翠，月点波心一颗珠。\n碧毯线头抽早稻，青罗裙带展新蒲。\n未能抛得杭州去，一半勾留是此湖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春题湖上' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋兴八首', '杜甫', '唐代', '玉露凋伤枫树林，巫山巫峡气萧森。\n江间波浪兼天涌，塞上风云接地阴。\n丛菊两开他日泪，孤舟一系故园心。\n寒衣处处催刀尺，白帝城高急暮砧。\n\n夔府孤城落日斜，每依北斗望京华。\n听猿实下三声泪，奉使虚随八月槎。\n画省香炉违伏枕，山楼粉堞隐悲笳。\n请看石上藤萝月，已映洲前芦荻花。\n\n千家山郭静朝晖，日日江楼坐翠微。\n信宿渔人还泛泛，清秋燕子故飞飞。\n匡衡抗疏功名薄，刘向传经心事违。\n同学少年多不贱，五陵衣马自轻肥。\n\n闻道长安似弈棋，百年世事不胜悲。\n王侯第宅皆新主，文武衣冠异昔时。\n直北关山金鼓振，征西车马羽书驰。\n鱼龙寂寞秋江冷，故国平居有所思。\n\n蓬莱宫阙对南山，承露金茎霄汉间。\n西望瑶池降王母，东来紫气满函关。\n云移雉尾开宫扇，日绕龙鳞识圣颜。\n一卧沧江惊岁晚，几回青琐点朝班。\n\n瞿塘峡口曲江头，万里风烟接素秋。\n花萼夹城通御气，芙蓉小苑入边愁。\n珠帘绣柱围黄鹄，锦缆牙樯起白鸥。\n回首可怜歌舞地，秦中自古帝王州。\n\n昆明池水汉时功，武帝旌旗在眼中。\n织女机丝虚夜月，石鲸鳞甲动秋风。\n波漂菰米沉云黑，露冷莲房坠粉红。\n关塞极天惟鸟道，江湖满地一渔翁。\n\n昆吾御宿自逶迤，紫阁峰阴入渼陂。\n香稻啄馀鹦鹉粒，碧梧栖老凤凰枝。\n佳人拾翠春相问，仙侣同舟晚更移。\n彩笔昔曾干气象，白头吟望苦低垂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋兴八首' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归园田居·其四', '陶渊明', '魏晋', '久去山泽游，浪莽林野娱。\n试携子侄辈，披榛步荒墟。\n徘徊丘垄间，依依昔人居。\n井灶有遗处，桑竹残朽株。\n借问采薪者，此人皆焉如？\n薪者向我言，死没无复余。\n一世异朝市，此语真不虚。\n人生似幻化，终当归空无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归园田居·其四' AND p.poem_author = '陶渊明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('相思令·吴山青', '林逋', '宋代', '吴山青，越山青，两岸青山相送迎，争忍有离情？\n君泪盈，妾泪盈，罗带同心结未成，江边潮已平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '相思令·吴山青' AND p.poem_author = '林逋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·送春', '朱淑真', '宋代', '楼外垂杨千万缕。欲系青春，少住春还去。犹自风前飘柳絮。随春且看归何处。 \n绿满山川闻杜宇。便做无情，莫也愁人苦。把酒送春春不语。黄昏却下潇潇雨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·送春' AND p.poem_author = '朱淑真';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陇西行', '王维', '唐代', '十里一走马，五里一扬鞭。\n都护军书至，匈奴围酒泉。\n关山正飞雪，烽火断无烟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陇西行' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻雁', '韦应物', '唐代', '故园渺何处，归思方悠哉。\n淮南秋雨夜，高斋闻雁来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻雁' AND p.poem_author = '韦应物';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长歌行', '王昌龄', '唐代', '旷野饶悲风，飕飕黄蒿草。\n系马倚白杨，谁知我怀抱。 \n所是同袍者，相逢尽衰老。\n北登汉家陵，南望长安道。 \n下有枯树根，上有鼯鼠窠。\n高皇子孙尽，千载无人过。 \n宝玉频发掘，精灵其奈何。\n人生须达命，有酒且长歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长歌行' AND p.poem_author = '王昌龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山中留客', '张旭', '唐代', '山光物态弄春晖，莫为轻阴便拟归。\n纵使晴明无雨色，入云深处亦沾衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山中留客' AND p.poem_author = '张旭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜算子·芍药打团红', '洪咨夔', '宋代', '芍药打团红，萱草成窝绿。帘卷疏风燕子归，依旧卢仝屋。\n贫放麹生疏，闲到青奴熟。扫地焚香伴老仙，人胜连环玉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜算子·芍药打团红' AND p.poem_author = '洪咨夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('如梦令·水垢何曾相受', '苏轼', '宋代', '水垢何曾相受。细看两俱无有。寄语揩背人，尽日劳君挥肘。轻手，轻手，居士本来无垢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '如梦令·水垢何曾相受' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庭中有奇树', '佚名', '两汉', '庭中有奇树，绿叶发华滋。\n攀条折其荣，将以遗所思。\n馨香盈怀袖，路远莫致之。\n此物何足贵，但感别经时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庭中有奇树' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无题·来是空言去绝踪', '李商隐', '唐代', '来是空言去绝踪，月斜楼上五更钟。\n梦为远别啼难唤，书被催成墨未浓。\n蜡照半笼金翡翠，麝熏微度绣芙蓉。\n刘郎已恨蓬山远，更隔蓬山一万重！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无题·来是空言去绝踪' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塞上', '柳开', '宋代', '鸣骹直上一千尺，天静无风声更干。\n碧眼胡儿三百骑，尽提金勒向云看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塞上' AND p.poem_author = '柳开';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('半死桐·重过阊门万事非', '贺铸', '宋代', '重过阊门万事非。同来何事不同归。梧桐半死清霜后，头白鸳鸯失伴飞。 \n原上草，露初晞。旧栖新垅两依依。空床卧听南窗雨，谁复挑灯夜补衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '半死桐·重过阊门万事非' AND p.poem_author = '贺铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西施', '罗隐', '唐代', '家国兴亡自有时，吴人何苦怨西施。\n西施若解倾吴国，越国亡来又是谁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西施' AND p.poem_author = '罗隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦李白二首·其一', '杜甫', '唐代', '死别已吞声，生别常恻恻。江南瘴疠地，逐客无消息。\n故人入我梦，明我长相忆。恐非平生魂，路远不可测。\n魂来枫林青，魂返关塞黑。君今在罗网，何以有羽翼。\n落月满屋梁，犹疑照颜色。水深波浪阔，无使蛟龙得。(版本一)\n\n死别已吞声，生别常恻恻。江南瘴疠地，逐客无消息。\n故人入我梦，明我长相忆。君今在罗网，何以有羽翼。\n恐非平生魂，路远不可测。魂来枫林青，魂返关塞黑。\n落月满屋梁，犹疑照颜色。水深波浪阔，无使蛟龙得。(版本二)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梦李白二首·其一' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('司马光好学', '朱熹', '宋代', '司马温公幼时，患记问不若人。群居讲习，众兄弟既成诵，游息矣；独下帷绝编，迨能倍诵乃止。用力多者收功远，其所精诵，乃终身不忘也。温公尝言：“书不可不成诵。或在马上，或中夜不寝时，咏其文，思其义，所得多矣。”（选自朱熹编辑的《三朝名臣言行录》）', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '司马光好学' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月·梅花', '苏轼', '宋代', '玉骨那愁瘴雾，冰姿自有仙风。海仙时遣探芳丛。倒挂绿毛么凤。(么 同：幺)\n素面翻嫌粉涴，洗妆不褪唇红。高情已逐晓云空。不与梨花同梦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月·梅花' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水龙吟·黄州梦过栖霞楼', '苏轼', '宋代', '闾丘大夫孝终公显尝守黄州，作栖霞楼，为郡中胜绝。元丰五年，余谪居黄。正月十七日，梦扁舟渡江，中流回望，楼中歌乐杂作。舟中人言：公显方会客也。觉而异之，乃作此词，盖越调鼓笛慢。公显时已致仕在苏州。\n\n小舟横截春江，卧看翠壁红楼起。云间笑语，使君高会，佳人半醉。危柱哀弦，艳歌余响，绕云萦水。念故人老大，风流未减，独回首、烟波里。\n推枕惘然不见，但空江、月明千里。五湖闻道，扁舟归去，仍携西子。云梦南州，武昌东岸，昔游应记。料多情梦里，端来见我，也参差是。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水龙吟·黄州梦过栖霞楼' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浪淘沙令·伊吕两衰翁', '王安石', '宋代', '伊吕两衰翁，历遍穷通。一为钓叟一耕佣。若使当时身不遇，老了英雄。\n汤武偶相逢，风虎云龙。兴王只在谈笑中。直至如今千载后，谁与争功！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浪淘沙令·伊吕两衰翁' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦天', '李贺', '唐代', '老兔寒蟾泣天色，云楼半开壁斜白。\n玉轮轧露湿团光，鸾珮相逢桂香陌。\n黄尘清水三山下，更变千年如走马。\n遥望齐州九点烟，一泓海水杯中泻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梦天' AND p.poem_author = '李贺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金缕曲·亡妇忌日有感', '纳兰性德', '清代', '此恨何时已。滴空阶、寒更雨歇，葬花天气。三载悠悠魂梦杳，是梦久应醒矣。料也觉、人间无味。不及夜台尘土隔，冷清清、一片埋愁地。钗钿约，竟抛弃。\n重泉若有双鱼寄。好知他、年来苦乐，与谁相倚。我自中宵成转侧，忍听湘弦重理。待结个、他生知已。还怕两人俱薄命，再缘悭、剩月零风里。清泪尽，纸灰起。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金缕曲·亡妇忌日有感' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('张衡传', '范晔', '南北朝', '张衡字平子，南阳西鄂人也。衡少善属文，游于三辅，因入京师，观太学，遂通五经，贯六艺。虽才高于世，而无骄尚之情。常从容淡静，不好交接俗人。永元中，举孝廉不行，连辟公府不就。时天下承平日久，自王侯以下，莫不逾侈。衡乃拟班固《两都》作《二京赋》，因以讽谏。精思傅会，十年乃成。大将军邓骘奇其才，累召不应。\n\n　　衡善机巧，尤致思于天文、阴阳、历算。安帝雅闻衡善术学，公车特征拜郎中，再迁为太史令。遂乃研核阴阳，妙尽璇玑之正，作浑天仪，著《灵宪》、《算罔论》，言甚详明。\n\n　　顺帝初，再转，复为太史令。衡不慕当世，所居之官辄积年不徙。自去史职，五载复还。\n\n　　阳嘉元年，复造候风地动仪。以精铜铸成，员径八尺，合盖隆起，形似酒尊，饰以篆文山龟鸟兽之形。中有都柱，傍行八道，施关发机。外有八龙，首衔铜丸，下有蟾蜍，张口承之。其牙机巧制，皆隐在尊中，覆盖周密无际。如有地动，尊则振龙，机发吐丸，而蟾蜍衔之。振声激扬，伺者因此觉知。虽一龙发机，而七首不动，寻其方面，乃知震之所在。验之以事，合契若神。自书典所记，未之有也。尝一龙机发而地不觉动，京师学者咸怪其无征。后数日驿至，果地震陇西，于是皆服其妙。自此以后，乃令史官记地动所从方起。\n\n　　时政事渐损，权移于下，衡因上疏陈事。后迁侍中，帝引在帷幄，讽议左右。尝问天下所疾恶者。宦官惧其毁己，皆共目之，衡乃诡对而出。阉竖恐终为其患，遂共谗之。衡常思图身之事，以为吉凶倚仗，幽微难明。乃作《思玄赋》以宣寄情志。\n\n　　永和初，出为河间相。时国王骄奢，不遵典宪；又多豪右，共为不轨。衡下车，治威严，整法度，阴知奸党名姓，一时收禽，上下肃然，称为政理。视事三年，上书乞骸骨，征拜尚书。年六十二，永和四年卒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '张衡传' AND p.poem_author = '范晔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绝句', '王庭筠', '元代', '竹影和诗瘦，梅花入梦香。\n可怜今夜月，不肯下西厢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绝句' AND p.poem_author = '王庭筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塞上曲二首·其二', '戴叔伦', '唐代', '汉家旌帜满阴山，不遣胡儿匹马还。\n愿得此身长报国，何须生入玉门关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塞上曲二首·其二' AND p.poem_author = '戴叔伦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('今日歌', '文嘉', '明代', '今日复今日，今日何其少！\n今日又不为，此事何时了？\n人生百年几今日，今日不为真可惜！\n若言姑待明朝至，明朝又有明朝事。\n为君聊赋今日诗，努力请从今日始。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '今日歌' AND p.poem_author = '文嘉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('屈原列传', '司马迁', '两汉', '屈原者，名平，楚之同姓也。为楚怀王左徒。博闻强志，明于治乱，娴于辞令。入则与王图议国事，以出号令；出则接遇宾客，应对诸侯。王甚任之。\n\n　　上官大夫与之同列，争宠而心害其能。怀王使屈原造为宪令，屈平属草稿未定。上官大夫见而欲夺之，屈平不与，因谗之曰：“王使屈平为令，众莫不知。每一令出，平伐其功，曰以为‘非我莫能为也。’”王怒而疏屈平。\n\n　　屈平疾王听之不聪也，谗谄之蔽明也，邪曲之害公也，方正之不容也，故忧愁幽思而作《离骚》。“离骚”者，犹离忧也。夫天者，人之始也；父母者，人之本也。人穷则反本，故劳苦倦极，未尝不呼天也；疾痛惨怛，未尝不呼父母也。屈平正道直行，竭忠尽智，以事其君，谗人间之，可谓穷矣。信而见疑，忠而被谤，能无怨乎？屈平之作《离骚》，盖自怨生也。《国风》好色而不淫，《小雅》怨诽而不乱。若《离骚》者，可谓兼之矣。上称帝喾，下道齐桓，中述汤、武，以刺世事。明道德之广崇，治乱之条贯，靡不毕见。其文约，其辞微，其志洁，其行廉。其称文小而其指极大，举类迩而见义远。其志洁，故其称物芳；其行廉，故死而不容。自疏濯淖污泥之中，蝉蜕于浊秽，以浮游尘埃之外，不获世之滋垢，皭然泥而不滓者也。推此志也，虽与日月争光可也。\n\n　　屈原既绌。其后秦欲伐齐，齐与楚从亲，惠王患之。乃令张仪佯去秦，厚币委质事楚，曰：“秦甚憎齐，齐与楚从亲，楚诚能绝齐，秦愿献商、於之地六百里。”楚怀王贪而信张仪，遂绝齐，使使如秦受地。张仪诈之曰：“仪与王约六里，不闻六百里。”楚使怒去，归告怀王。怀王怒，大兴师伐秦。秦发兵击之，大破楚师于丹、淅，斩首八万，虏楚将屈匄，遂取楚之汉中地。怀王乃悉发国中兵，以深入击秦，战于蓝田。魏闻之，袭楚至邓。楚兵惧，自秦归。而齐竟怒，不救楚，楚大困。明年，秦割汉中地与楚以和。楚王曰：“不愿得地，愿得张仪而甘心焉。”张仪闻，乃曰：“以一仪而当汉中地，臣请往如楚。”如楚，又因厚币用事者臣靳尚，而设诡辩于怀王之宠姬郑袖。怀王竟听郑袖，复释去张仪。是时屈原既疏，不复在位，使于齐，顾反，谏怀王曰：“何不杀张仪？”怀王悔，追张仪，不及。\n\n　　其后，诸侯共击楚，大破之，杀其将唐眜。时秦昭王与楚婚，欲与怀王会。怀王欲行，屈平曰：“秦，虎狼之国，不可信，不如毋行。”怀王稚子子兰劝王行：“奈何绝秦欢！”怀王卒行。入武关，秦伏兵绝其后，因留怀王，以求割地。怀王怒，不听。亡走赵，赵不内。复之秦，竟死于秦而归葬。\n\n　　长子顷襄王立，以其弟子兰为令尹。楚人既咎子兰以劝怀王入秦而不反也。屈平既嫉之，虽放流，眷顾楚国，系心怀王，不忘欲反。冀幸君之一悟，俗之一改也。其存君兴国，而欲反复之，一篇之中，三致志焉。然终无可奈何，故不可以反。卒以此见怀王之终不悟也。\n\n　　人君无愚智贤不肖，莫不欲求忠以自为，举贤以自佐。然亡国破家相随属，而圣君治国累世而不见者，其所谓忠者不忠，而所谓贤者不贤也。怀王以不知忠臣之分，故内惑于郑袖，外欺于张仪，疏屈平而信上官大夫、令尹子兰，兵挫地削，亡其六郡，身客死于秦，为天下笑，此不知人之祸也。《易》曰：“井渫不食，为我心恻，可以汲。王明，并受其福。”王之不明，岂足福哉！令尹子兰闻之，大怒。卒使上官大夫短屈原于顷襄王。顷襄王怒而迁之。屈原至于江滨，被发行吟泽畔，颜色憔悴，形容枯槁。渔父见而问之曰：“子非三闾大夫欤？何故而至此？”屈原曰：“举世皆浊而我独清，众人皆醉而我独醒，是以见放。”渔父曰：“夫圣人者，不凝滞于物，而能与世推移。举世皆浊，何不随其流而扬其波？众人皆醉，何不哺其糟而啜其醨？何故怀瑾握瑜，而自令见放为？”屈原曰：“吾闻之，新沐者必弹冠，新浴者必振衣。人又谁能以身之察察，受物之汶汶者乎？宁赴常流而葬乎江鱼腹中耳。又安能以皓皓之白，而蒙世之温蠖乎？”乃作《怀沙》之赋。于是怀石，遂自投汨罗以死。\n\n　　屈原既死之后，楚有宋玉、唐勒、景差之徒者，皆好辞而以赋见称。然皆祖屈原之从容辞令，终莫敢直谏。其后楚日以削，数十年竟为秦所灭。自屈原沉汨罗后百有馀年，汉有贾生，为长沙王太傅。过湘水，投书以吊屈原。\n\n　　太史公曰：“余读《离骚》、《天问》、《招魂》、《哀郢》，悲其志。适长沙，过屈原所自沉渊，未尝不垂涕，想见其为人。及见贾生吊之，又怪屈原以彼其材游诸侯，何国不容，而自令若是！读《鵩鸟赋》，同死生，轻去就，又爽然自失矣。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '屈原列传' AND p.poem_author = '司马迁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水仙子·咏江南', '张养浩', '元代', '一江烟水照晴岚，两岸人家接画檐，芰荷丛一段秋光淡。看沙鸥舞再三，卷香风十里珠帘。画船儿天边至，酒旗儿风外飐。爱杀江南！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水仙子·咏江南' AND p.poem_author = '张养浩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游子吟', '陈陶', '唐代', '栖乌喜林曙，惊蓬伤岁阑。\n关河三尺雪，何处是天山。\n朔风无重衣，仆马饥且寒。\n惨戚别妻子，迟回出门难。\n男儿值休明，岂是长泥蟠。\n何者为木偶，何人侍金銮。\n郁郁守贫贱，悠悠亦无端。\n进不图功名，退不处岩峦。\n穷通在何日，光景如跳丸。\n富贵苦不早，令人摧心肝。\n誓期春之阳，一振摩霄翰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游子吟' AND p.poem_author = '陈陶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋', '郑谷', '唐代', '清香闻晓莲，水国雨馀天。\n天气正得所，客心刚悄然。\n乱兵何日息，故老几人全。\n此际难消遣，从来未学禅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋' AND p.poem_author = '郑谷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('触龙说赵太后', '刘向', '先秦', '赵太后新用事，秦急攻之。赵氏求救于齐，齐曰：“必以长安君为质，兵乃出。”太后不肯，大臣强谏。太后明谓左右：“有复言令长安君为质者，老妇必唾其面。”\n\n　　左师触龙言愿见太后。太后盛气而揖之。入而徐趋，至而自谢，曰：“老臣病足，曾不能疾走，不得见久矣。窃自恕，而恐太后玉体之有所郄也，故愿望见太后。”太后曰：“老妇恃辇而行。”曰：“日食饮得无衰乎？”曰：“恃粥耳。”曰：“老臣今者殊不欲食，乃自强步，日三四里，少益耆食，和于身。”太后曰：“老妇不能。”太后之色少解。\n\n　　左师公曰：“老臣贱息舒祺，最少，不肖；而臣衰，窃爱怜之。愿令得补黑衣之数，以卫王宫。没死以闻。”太后曰：“敬诺。年几何矣？”对曰：“十五岁矣。虽少，愿及未填沟壑而托之。”太后曰：“丈夫亦爱怜其少子乎？”对曰：“甚于妇人。”太后笑曰：“妇人异甚。”对曰：“老臣窃以为媪之爱燕后贤于长安君。”曰：“君过矣！不若长安君之甚。”左师公曰：“父母之爱子，则为之计深远。媪之送燕后也，持其踵，为之泣，念悲其远也，亦哀之矣。已行，非弗思也，祭祀必祝之，祝曰：‘必勿使反。’岂非计久长，有子孙相继为王也哉？”太后曰：“然。”\n\n　　左师公曰：“今三世以前，至于赵之为赵，赵王之子孙侯者，其继有在者乎？”曰：“无有。”曰：“微独赵，诸侯有在者乎？”曰：“老妇不闻也。”“此其近者祸及身，远者及其子孙。岂人主之子孙则必不善哉？位尊而无功，奉厚而无劳，而挟重器多也。今媪尊长安君之位，而封之以膏腴之地，多予之重器，而不及今令有功于国，—旦山陵崩，长安君何以自托于赵？老臣以媪为长安君计短也，故以为其爱不若燕后。”太后曰：“诺，恣君之所使之。”\n\n　　于是为长安君约车百乘，质于齐，齐兵乃出。\n\n　　子义闻之曰：“人主之子也、骨肉之亲也，犹不能恃无功之尊、无劳之奉，已守金玉之重也，而况人臣乎。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '触龙说赵太后' AND p.poem_author = '刘向';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陶者', '梅尧臣', '宋代', '陶尽门前土，屋上无片瓦。\n十指不沾泥，鳞鳞居大厦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陶者' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('少年游·并刀如水', '周邦彦', '宋代', '并刀如水，吴盐胜雪，纤手破新橙。锦幄初温，兽烟不断，相对坐调笙。 \n低声问向谁行宿，城上已三更。马滑霜浓，不如休去，直是少人行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '少年游·并刀如水' AND p.poem_author = '周邦彦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮·回文夏闺怨', '苏轼', '宋代', '柳庭风静人眠昼，昼眠人静风庭柳。香汗薄衫凉，凉衫薄汗香。\n手红冰碗藕，藕碗冰红手。郎笑藕丝长，长丝藕笑郎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮·回文夏闺怨' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶作寄朗之', '白居易', '唐代', '历想为官日，无如刺史时。\n欢娱接宾客，饱暖及妻儿。\n自到东都后，安闲更得宜。\n分司胜刺史，致仕胜分司。\n何况园林下，欣然得朗之。\n仰名同旧识，为乐即新知。\n有雪先相访，无花不作期。\n斗醲干酿酒，夸妙细吟诗。\n里巷千来往，都门五别离。\n岐分两回首，书到一开眉。\n叶落槐亭院，冰生竹阁池。\n雀罗谁问讯，鹤氅罢追随。\n身与心俱病，容将力共衰。\n老来多健忘，唯不忘相思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶作寄朗之' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('永遇乐·彭城夜宿燕子楼', '苏轼', '宋代', '彭城夜宿燕子楼，梦盼盼，因作此词。\n\n明月如霜，好风如水，清景无限。曲港跳鱼，圆荷泻露，寂寞无人见。紞如三鼓，铿然一叶，黯黯梦云惊断。夜茫茫，重寻无处，觉来小园行遍。 \n天涯倦客，山中归路，望断故园心眼。燕子楼空，佳人何在，空锁楼中燕。古今如梦，何曾梦觉，但有旧欢新怨。异时对，黄楼夜景，为余浩叹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '永遇乐·彭城夜宿燕子楼' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙·玉碗冰寒滴露华', '晏殊', '宋代', '玉碗冰寒滴露华，粉融香雪透轻纱。晚来妆面胜荷花。\n鬓亸欲迎眉际月，酒红初上脸边霞。一场春梦日西斜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙·玉碗冰寒滴露华' AND p.poem_author = '晏殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蜉蝣', '佚名', '先秦', '蜉蝣之羽，衣裳楚楚。心之忧矣，於我归处。\n蜉蝣之翼，采采衣服。心之忧矣，於我归息。\n蜉蝣掘阅，麻衣如雪。心之忧矣，於我归说。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蜉蝣' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋登楼望月', '米芾', '宋代', '目穷淮海满如银，万道虹光育蚌珍。\n天上若无修月户，桂枝撑损向西轮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋登楼望月' AND p.poem_author = '米芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自京赴奉先县咏怀五百字 / 自京赴奉先咏怀五百字', '杜甫', '唐代', '杜陵有布衣，老大意转拙。\n许身一何愚，窃比稷与契。\n居然成濩落，白首甘契阔。\n盖棺事则已，此志常觊豁。\n穷年忧黎元，叹息肠内热。\n取笑同学翁，浩歌弥激烈。\n非无江海志，潇洒送日月。\n生逢尧舜君，不忍便永诀。\n当今廊庙具，构厦岂云缺。\n葵藿倾太阳，物性固莫夺。\n顾惟蝼蚁辈，但自求其穴。\n胡为慕大鲸，辄拟偃溟渤。\n以兹误生理，独耻事干谒。\n兀兀遂至今，忍为尘埃没。\n终愧巢与由，未能易其节。\n沉饮聊自遣，放歌破愁绝。\n岁暮百草零，疾风高冈裂。\n天衢阴峥嵘，客子中夜发。\n霜严衣带断，指直不得结。\n凌晨过骊山，御榻在嵽嵲。\n蚩尤塞寒空，蹴蹋崖谷滑。\n瑶池气郁律，羽林相摩戛。\n君臣留欢娱，乐动殷樛嶱。\n赐浴皆长缨，与宴非短褐。\n彤庭所分帛，本自寒女出。\n鞭挞其夫家，聚敛贡城阙。\n圣人筐篚恩，实欲邦国活。\n臣如忽至理，君岂弃此物。\n多士盈朝廷，仁者宜战栗。\n况闻内金盘，尽在卫霍室。\n中堂舞神仙，烟雾散玉质。\n煖客貂鼠裘，悲管逐清瑟。\n劝客驼蹄羹，霜橙压香橘。\n朱门酒肉臭，路有冻死骨。\n荣枯咫尺异，惆怅难再述。\n北辕就泾渭，官渡又改辙。\n群冰从西下，极目高崒兀。\n疑是崆峒来，恐触天柱折。\n河梁幸未坼，枝撑声窸窣。\n行旅相攀援，川广不可越。\n老妻寄异县，十口隔风雪。\n谁能久不顾，庶往共饥渴。\n入门闻号啕，幼子饥已卒。\n吾宁舍一哀，里巷亦呜咽。\n所愧为人父，无食致夭折。\n岂知秋禾登，贫窭有仓卒。\n生常免租税，名不隶征伐。\n抚迹犹酸辛，平人固骚屑。\n默思失业徒，因念远戍卒。\n忧端齐终南，澒洞不可掇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自京赴奉先县咏怀五百字 / 自京赴奉先咏怀五百字' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行露', '佚名', '先秦', '厌浥行露，岂不夙夜，谓行多露。\n谁谓雀无角？何以穿我屋？谁谓女无家？何以速我狱？虽速我狱，室家不足！\n谁谓鼠无牙？何以穿我墉？谁谓女无家？何以速我讼？虽速我讼，亦不女从！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行露' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阴雨', '白居易', '唐代', '岚雾今朝重，江山此地深。\n滩声秋更急，峡气晓多阴。\n望阙云遮眼，思乡雨滴心。\n将何慰幽独，赖此北窗琴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阴雨' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沙丘城下寄杜甫', '李白', '唐代', '我来竟何事，高卧沙丘城。\n城边有古树，日夕连秋声。\n鲁酒不可醉，齐歌空复情。\n思君若汶水，浩荡寄南征。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沙丘城下寄杜甫' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('子夜吴歌·冬歌', '李白', '唐代', '明朝驿使发，一夜絮征袍。\n素手抽针冷，那堪把剪刀。\n裁缝寄远道，几日到临洮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '子夜吴歌·冬歌' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜归鹿门山歌 / 夜归鹿门歌', '孟浩然', '唐代', '山寺钟鸣昼已昏，渔梁渡头争渡喧。\n人随沙岸向江村，余亦乘舟归鹿门。\n鹿门月照开烟树，忽到庞公栖隐处。\n岩扉松径长寂寥，惟有幽人自来去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜归鹿门山歌 / 夜归鹿门歌' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋凉晚步', '杨万里', '宋代', '秋气堪悲未必然，轻寒正是可人天。\n绿池落尽红蕖却，荷叶犹开最小钱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋凉晚步' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('移居二首', '陶渊明', '魏晋', '昔欲居南村，非为卜其宅。\n闻多素心人，乐与数晨夕。\n怀此颇有年，今日从兹役。\n敝庐何必广，取足蔽床席。\n邻曲时时来，抗言谈在昔。\n奇文共欣赏，疑义相与析。\n\n春秋多佳日，登高赋新诗。\n过门更相呼，有酒斟酌之。\n农务各自归，闲暇辄相思。\n相思则披衣，言笑无厌时。\n此理将不胜？无为忽去兹。\n衣食当须纪，力耕不吾欺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '移居二首' AND p.poem_author = '陶渊明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春怨 / 伊州歌', '金昌绪', '唐代', '打起黄莺儿，莫教枝上啼。\n啼时惊妾梦，不得到辽西。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春怨 / 伊州歌' AND p.poem_author = '金昌绪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('官仓鼠', '曹邺', '唐代', '官仓老鼠大如斗，见人开仓亦不走。 \n健儿无粮百姓饥，谁遣朝朝入君口。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '官仓鼠' AND p.poem_author = '曹邺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('越中览古', '李白', '唐代', '越王勾践破吴归，义士还乡尽锦衣。 \n宫女如花满春殿，只今惟有鹧鸪飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '越中览古' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮·花明月暗笼轻雾', '李煜', '五代', '花明月暗笼轻雾，今宵好向郎边去。刬袜步香阶，手提金缕鞋。画堂南畔见，一向偎人颤。奴为出来难，教君恣意怜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮·花明月暗笼轻雾' AND p.poem_author = '李煜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头·细数十年事', '范成大', '宋代', '细数十年事，十处过中秋。今年新梦，忽到黄鹤旧山头。老子个中不浅，此会天教重见，今古一南楼。星汉淡无色，玉镜独空浮。\n敛秦烟，收楚雾，熨江流。关河离合，南北依旧照清愁。想见姮娥冷眼，应笑归来霜鬓，空敝黑貂裘。酾酒问蟾兔，肯去伴沧洲？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头·细数十年事' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·郑风·女曰鸡鸣', '佚名', '先秦', '女曰鸡鸣，士曰昧旦。子兴视夜，明星有烂。将翱将翔，弋凫与雁。\n弋言加之，与子宜之。宜言饮酒，与子偕老。琴瑟在御，莫不静好。\n知子之来之，杂佩以赠之。知子之顺之，杂佩以问之。知子之好之，杂佩以报之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·郑风·女曰鸡鸣' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赵威后问齐使', '佚名', '先秦', '齐王使使者问赵威后。书未发，威后问使者曰：“岁亦无恙邪？民亦无恙邪？王亦无恙邪？”使者不说，曰：“臣奉使使威后，今不问王而先问岁与民，岂先贱而后尊贵者乎？”威后曰：“不然，苟无岁，何以有民？苟无民， 何以有君？故有舍本而问末者耶？”\n\n　　乃进而问之曰：“齐有处士曰锺离子，无恙耶？是其为人也，有粮者亦食，无粮者亦食；有衣者亦衣，无衣者亦衣。是助王养其民也，何以至今不业也？叶阳子无恙乎？是其为人，哀鳏寡，恤孤独，振困穷，补不足。是助王息其民者也，何以至今不业也？北宫之女婴儿子无恙耶？彻其环瑱，至老不嫁，以养父母。是皆率民而出于孝情者也，胡为至今不朝也?此二士弗业，一女不朝，何以王齐国，子万民乎？於陵子仲尚存乎？是其为人也，上不臣于王，下不治其家，中不索交诸侯。此率民而出于无用者，何为至今不杀乎？”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '赵威后问齐使' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑子·塞上咏雪花', '纳兰性德', '清代', '非关癖爱轻模样，冷处偏佳。别有根芽，不是人间富贵花。\n谢娘别后谁能惜，飘泊天涯。寒月悲笳，万里西风瀚海沙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑子·塞上咏雪花' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏怀八十二首·其一', '阮籍', '魏晋', '夜中不能寐，起坐弹鸣琴。\n薄帷鉴明月，清风吹我襟。\n孤鸿号外野，翔鸟鸣北林。\n徘徊将何见？忧思独伤心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏怀八十二首·其一' AND p.poem_author = '阮籍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('羔羊', '佚名', '先秦', '羔羊之皮，素丝五紽。退食自公，委蛇委蛇。\n羔羊之革，素丝五緎。委蛇委蛇，自公退食。\n羔羊之缝，素丝五总。委蛇委蛇，退食自公。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '羔羊' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春风', '袁枚', '清代', '春风如贵客，一到便繁华。\n来扫千山雪，归留万国花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春风' AND p.poem_author = '袁枚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('百忧集行', '杜甫', '唐代', '忆年十五心尚孩，健如黄犊走复来。\n庭前八月梨枣熟，一日上树能千回。\n即今倏忽已五十，坐卧只多少行立。\n强将笑语供主人，悲见生涯百忧集。\n入门依旧四壁空，老妻睹我颜色同。\n痴儿不知父子礼，叫怒索饭啼门东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '百忧集行' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塞鸿秋·春情', '张可久', '元代', '疏星淡月秋千院，愁云恨雨芙蓉面。\n伤情燕足留红线，恼人鸾影闲团扇。\n兽炉沉水烟，翠沼残花片。\n一行写入相思传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塞鸿秋·春情' AND p.poem_author = '张可久';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桃花', '元稹', '唐代', '桃花浅深处，似匀深浅妆。\n春风助肠断，吹落白衣裳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桃花' AND p.poem_author = '元稹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬乐天咏老见示', '刘禹锡', '唐代', '人谁不顾老，老去有谁怜。\n身瘦带频减，发稀冠自偏。\n废书缘惜眼，多灸为随年。\n经事还谙事，阅人如阅川。\n细思皆幸矣，下此便翛然。\n莫道桑榆晚，为霞尚满天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬乐天咏老见示' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨后池上', '刘攽', '宋代', '一雨池塘水面平，淡磨明镜照檐楹。\n东风忽起垂杨舞，更作荷心万点声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨后池上' AND p.poem_author = '刘攽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江上值水如海势聊短述', '杜甫', '唐代', '为人性僻耽佳句，语不惊人死不休。\n老去诗篇浑漫与，春来花鸟莫深愁。(漫与 一作：漫兴)\n新添水槛供垂钓，故着浮槎替入舟。\n焉得思如陶谢手，令渠述作与同游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江上值水如海势聊短述' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·禹庙兰亭今古路', '陆游', '宋代', '禹庙兰亭今古路。一夜清霜，染尽湖边树。鹦鹉杯深君莫诉。他时相遇知何处。\n冉冉年华留不住。镜里朱颜，毕竟消磨去。一句丁宁君记取。神仙须是闲人做。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·禹庙兰亭今古路' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送方外上人 / 送上人', '刘长卿', '唐代', '孤云将野鹤，岂向人间住。\n莫买沃洲山，时人已知处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送方外上人 / 送上人' AND p.poem_author = '刘长卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渭川田家', '王维', '唐代', '斜阳照墟落，穷巷牛羊归。(斜阳 一作：斜光)\n野老念牧童，倚杖候荆扉。\n雉雊麦苗秀，蚕眠桑叶稀。\n田夫荷锄至，相见语依依。\n即此羡闲逸，怅然吟式微。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渭川田家' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('柳枝词', '郑文宝', '宋代', '亭亭画舸系春潭，直到行人酒半酣。\n不管烟波与风雨，载将离恨过江南。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '柳枝词' AND p.poem_author = '郑文宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月·宝髻松松挽就', '司马光', '宋代', '宝髻松松挽就，铅华淡淡妆成。青烟翠雾罩轻盈，飞絮游丝无定。\n相见争如不见，有情何似无情。笙歌散后酒初醒，深院月斜人静。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月·宝髻松松挽就' AND p.poem_author = '司马光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南歌子·天上星河转', '李清照', '宋代', '天上星河转，人间帘幕垂。凉生枕簟泪痕滋。起解罗衣聊问、夜何其。\n翠贴莲蓬小，金销藕叶稀。旧时天气旧时衣。只有情怀不似、旧家时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南歌子·天上星河转' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行香子·树绕村庄', '秦观', '宋代', '树绕村庄，水满陂塘。倚东风、豪兴徜徉。小园几许，收尽春光。有桃花红，李花白，菜花黄。\n远远围墙，隐隐茅堂。飏青旗、流水桥旁。偶然乘兴、步过东冈。正莺儿啼，燕儿舞，蝶儿忙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行香子·树绕村庄' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜雨', '白居易', '唐代', '我有所念人，隔在远远乡。\n我有所感事，结在深深肠。\n乡远去不得，无日不瞻望。\n肠深解不得，无夕不思量。\n况此残灯夜，独宿在空堂。\n秋天殊未晓，风雨正苍苍。\n不学头陀法，前心安可忘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜雨' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游子吟', '顾况', '唐代', '故枥思疲马，故窠思迷禽。\n浮云蔽我乡，踯躅游子吟。 \n游子悲久滞，浮云郁东岑。\n客堂无丝桐，落叶如秋霖。 \n艰哉远游子，所以悲滞淫。\n一为浮云词，愤塞谁能禁。 \n驰归百年内，唯愿展所钦。\n胡为不归欤，坐使年病侵。 \n未老霜绕鬓，非狂火烧心。\n太行何难哉，北斗不可斟。 \n夜静星河出，耿耿辰与参。\n佳人夐青天，尺素重于金。 \n泬寥群动异，眇默诸境森。\n苔衣上闲阶，蟋蟀催寒砧。 \n立身计几误，道险无容针。\n三年不还家，万里遗锦衾。 \n梦魂无重阻，离忧罔古今。\n胡为不归欤，辜负匣中琴。 \n腰下是何物，牵缠旷登寻。\n朝与名山期，夕宿楚水阴。 \n楚水殊演漾，名山窅岖嶔。\n客从洞庭来，婉娈潇湘深。 \n橘柚在南国，鸿雁遗秋音。\n下有碧草洲，上有青橘林。 \n引烛窥洞穴，凌波睥天琛。\n蒲荷影参差，凫鹤雏淋涔。 \n浩歌惜芳杜，散发轻华簪。\n胡为不归欤，泪下沾衣襟。 \n鸢飞戾霄汉，蝼蚁制鳣鱏。\n赫赫大圣朝，日月光照临。 \n圣主虽启迪，奇人分湮沈。\n层城登云韶，王府锵球琳。 \n鹿鸣志丰草，况复虞人箴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游子吟' AND p.poem_author = '顾况';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新婚别', '杜甫', '唐代', '兔丝附蓬麻，引蔓故不长。\n嫁女与征夫，不如弃路旁。\n结发为君妻，席不暖君床。\n暮婚晨告别，无乃太匆忙。\n君行虽不远，守边赴河阳。\n妾身未分明，何以拜姑嫜？\n父母养我时，日夜令我藏。\n生女有所归，鸡狗亦得将。\n君今往死地，沉痛迫中肠。\n誓欲随君去，形势反苍黄。\n勿为新婚念，努力事戎行。\n妇人在军中，兵气恐不扬。\n自嗟贫家女，久致罗襦裳。\n罗襦不复施，对君洗红妆。\n仰视百鸟飞，大小必双翔。\n人事多错迕，与君永相望。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新婚别' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬张少府', '王维', '唐代', '晚年唯好静，万事不关心。自顾无长策，空知返旧林。 \n松风吹解带，山月照弹琴。君问穷通理，渔歌入浦深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬张少府' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阮郎归·初夏', '苏轼', '宋代', '绿槐高柳咽新蝉。薰风初入弦。碧纱窗下水沈烟。棋声惊昼眠。(水沈 一作 水沉） \n微雨过，小荷翻。榴花开欲然。玉盆纤手弄清泉。琼珠碎却圆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阮郎归·初夏' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('如意娘', '武则天', '唐代', '看朱成碧思纷纷，憔悴支离为忆君。\n不信比来长下泪，开箱验取石榴裙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '如意娘' AND p.poem_author = '武则天';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('甘棠', '佚名', '先秦', '蔽芾甘棠，勿翦勿伐，召伯所茇。\n蔽芾甘棠，勿翦勿败，召伯所憩。\n蔽芾甘棠，勿翦勿拜，召伯所说。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '甘棠' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙·堤上游人逐画船', '欧阳修', '宋代', '堤上游人逐画船，拍堤春水四垂天。绿杨楼外出秋千。\n白发戴花君莫笑，六幺催拍盏频传。人生何处似尊前！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙·堤上游人逐画船' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('潼关吏', '杜甫', '唐代', '士卒何草草，筑城潼关道。\n大城铁不如，小城万丈余。\n借问潼关吏：修关还备胡？\n要我下马行，为我指山隅：\n连云列战格，飞鸟不能逾。\n胡来但自守，岂复忧西都。\n丈人视要处，窄狭容单车。\n艰难奋长戟，万古用一夫。\n哀哉桃林战，百万化为鱼。\n请嘱防关将，慎勿学哥舒！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '潼关吏' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浪淘沙·其三', '刘禹锡', '唐代', '汴水东流虎眼文，清淮晓色鸭头春。\n君看渡口淘沙处，渡却人间多少人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浪淘沙·其三' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和晋陵陆丞早春游望', '杜审言', '唐代', '独有宦游人，偏惊物候新。\n云霞出海曙，梅柳渡江春。\n淑气催黄鸟，晴光转绿蘋。\n忽闻歌古调，归思欲沾巾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和晋陵陆丞早春游望' AND p.poem_author = '杜审言';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山村咏怀', '邵雍', '宋代', '一去二三里，烟村四五家。\n亭台六七座，八九十枝花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山村咏怀' AND p.poem_author = '邵雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八六子·倚危亭', '秦观', '宋代', '倚危亭。恨如芳草，萋萋刬尽还生。念柳外青骢别后，水边红袂分时，怆然暗惊。\n无端天与娉婷。夜月一帘幽梦，春风十里柔情。怎奈向、欢娱渐随流水，素弦声断，翠绡香减，那堪片片飞花弄晚，蒙蒙残雨笼晴。正销凝。黄鹂又啼数声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八六子·倚危亭' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('悲歌', '佚名', '两汉', '悲歌可以当泣，远望可以当归。\n思念故乡，郁郁累累。\n欲归家无人，欲渡河无船。\n心思不能言，肠中车轮转。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '悲歌' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西施滩', '崔道融', '唐代', '宰嚭亡吴国，西施陷恶名。\n浣纱春水急，似有不平声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西施滩' AND p.poem_author = '崔道融';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏夜叹', '杜甫', '唐代', '永日不可暮，炎蒸毒我肠。\n安得万里风，飘飖吹我裳。\n昊天出华月，茂林延疏光。\n仲夏苦夜短，开轩纳微凉。\n虚明见纤毫，羽虫亦飞扬。\n物情无巨细，自适固其常。\n念彼荷戈士，穷年守边疆。\n何由一洗濯，执热互相望。\n竟夕击刁斗，喧声连万方。\n青紫虽被体，不如早还乡。\n北城悲笳发，鹳鹤号且翔。\n况复烦促倦，激烈思时康。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏夜叹' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和项王歌', '虞姬', '两汉', '汉兵已略地，四方楚歌声。\n大王意气尽，贱妾何聊生！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和项王歌' AND p.poem_author = '虞姬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('将进酒', '陈陶', '唐代', '金尊莫倚青春健，龌龊浮生如走电。\n琴瑟盘倾从世珠，黄泥局泻流年箭。\n麻姑爪秃瞳子昏，东皇肉角生鱼鳞。\n灵鳌柱骨半枯朽，骊龙德悔愁耕人。\n周孔蓍龟久沦没，黄蒿谁认贤愚骨。\n兔苑词才去不还，兰亭水石空明月。\n姮娥弄箫香雨收，江滨迸瑟鱼龙愁。\n灵芝九折楚莲醉，翾风一叹梁庭秋。\n醁亚蛮觥奉君寿，玉山三献春红透。\n银鸭金鹅言待谁，隋家岳渎皇家有。\n珊瑚座上凌香云，凤炰龙炙猩猩唇。\n芝兰此日不倾倒，南山白石皆贤人。\n文康调笑麒麟起，一曲飞龙寿天地。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将进酒' AND p.poem_author = '陈陶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与夏十二登岳阳楼', '李白', '唐代', '楼观岳阳尽，川迥洞庭开。\n雁引愁心去，山衔好月来。\n云间连下榻，天上接行杯。\n醉后凉风起，吹人舞袖回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与夏十二登岳阳楼' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绸缪', '佚名', '先秦', '绸缪束薪，三星在天。今夕何夕，见此良人？子兮子兮，如此良人何？\n绸缪束刍，三星在隅。今夕何夕，见此邂逅？子兮子兮，如此邂逅何？\n绸缪束楚，三星在户。今夕何夕，见此粲者？子兮子兮，如此粲者何？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绸缪' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('胡笳十八拍', '蔡文姬', '两汉', '我生之初尚无为，我生之后汉祚衰。天不仁兮降乱离，地不仁兮使我逢此时。干戈日寻兮道路危，民卒流亡兮共哀悲。烟尘蔽野兮胡虏盛，志意乖兮节义亏。对殊俗兮非我宜，遭忍辱兮当告谁？笳一会兮琴一拍，心愤怨兮无人知。\n\n　　戎羯逼我兮为室家，将我行兮向天涯。云山万重兮归路遐，疾风千里兮扬尘沙。人多暴猛兮如虺蛇，控弦被甲兮为骄奢。两拍张弦兮弦欲绝，志摧心折兮自悲嗟。\n\n　　越汉国兮入胡城，亡家失身兮不如无生。毡裘为裳兮骨肉震惊，羯羶为味兮枉遏我情。鼙鼓喧兮从夜达明，胡风浩浩兮暗塞营。伤今感晋兮三拍成，衔悲畜恨兮何时平。\n\n　　无日无夜兮不思我乡土，禀气合生兮莫过我最苦。天灾国乱兮人无主，唯我薄命兮没戎虏。殊俗心异兮身难处，嗜欲不同兮谁可与语！寻思涉历兮多艰阻，四拍成兮益凄楚。\n\n　　雁南征兮欲寄边声，雁北归兮为得汉青。雁飞高兮邈难寻，空断肠兮思愔愔。攒眉向月兮抚雅琴，五拍泠泠兮意弥深。\n\n　　冰霜凛凛兮身苦寒，饥对肉酪兮不能餐。夜间陇水兮声呜咽，朝见长城兮路杳漫。追思往日兮行李难，六拍悲来兮欲罢弹。\n\n　　日暮风悲兮边声四起，不知愁心兮说向谁是！原野萧条兮烽戍万里，俗贱老弱兮少壮为美。逐有水草兮安家葺垒，牛羊满野兮聚如蜂蚁。草尽水竭兮羊马皆徙，七拍流恨兮恶居于此。\n\n　　为天有眼兮何不见我独漂流？为神有灵兮何事处我天南海北头？我不负天兮天何配我殊匹？我不负神兮神何殛我越荒州？制兹八拍兮拟排忧，何知曲成兮心转愁。\n\n　　天无涯兮地无边，我心愁兮亦复然。人生倏忽兮如白驹之过隙，然不得欢乐兮当我之盛年。怨兮欲问天，天苍苍兮上无缘。举头仰望兮空云烟，九拍怀情兮谁与传？\n\n　　城头烽火不曾灭，疆场征战何时歇？杀气朝朝冲塞门，胡风夜夜吹边月。故乡隔兮音生绝，哭无声兮气将咽。一生辛苦兮缘别离，十拍悲深兮泪成血。\n\n　　我非食生而恶死，不能捐身兮心有以。生仍冀得兮归桑梓，死当埋骨兮长已矣。日居月诸兮在戎垒，胡人宠我兮有二子。鞠之育之兮不羞耻，憋之念之兮生长边鄙。十有一拍兮因兹起，哀响缠绵兮彻心髓。\n\n　　东风应律兮暖气多，知是汉家天子兮布阳和。羌胡蹈舞兮共讴歌，两国交欢兮罢兵戈。忽遇汉使兮称近诏，遗千金兮赎妾身。喜得生还兮逢圣君，嗟别稚子兮会无因。十有二拍兮哀乐均，去住两情兮难具陈。\n\n　　不谓残生兮却得旋归，抚抱胡儿兮注下沾衣。汉使迎我兮四牡騑騑，胡儿号兮谁得知？与我生死兮逢此时，愁为子兮日无光辉，焉得羽翼兮将汝归。一步一远兮足难移，魂消影绝兮恩爱遗。十有三拍兮弦急调悲，肝肠搅刺兮人莫我知。\n\n　　身归国兮儿莫之随，心悬悬兮长如饥。四时万物兮有盛衰，唯我愁苦兮不暂移。山高地阔兮见汝无期，更深夜阑兮梦汝来斯。梦中执手兮一喜一悲，觉后痛吾心兮无休歇时。十有四拍兮涕泪交垂，河水东流兮心是思。\n\n　　十五拍兮节调促，气填胸兮谁识曲？处穹庐兮偶殊俗。愿得归来兮天从欲，再还汉国兮欢心足。心有怀兮愁转深，日月无私兮曾不照临。子母分离兮意难怪，同天隔越兮如商参，生死不相知兮何处寻！\n\n　　十六拍兮思茫茫，我与儿兮各一方。日东月西兮徒相望，不得相随兮空断肠。对萱草兮忧不忘，弹鸣琴兮情何伤！今别子兮归故乡，旧怨平兮新怨长！泣血仰头兮诉苍苍，胡为生兮独罹此殃！\n\n　　十七拍兮心鼻酸，关山阻修兮行路难。去时怀土兮心无绪，来时别儿兮思漫漫。塞上黄蒿兮枝枯叶干，沙场白骨兮刀痕箭瘢。风霜凛凛兮春夏寒，人马饥豗兮筋力单。岂知重得兮入长安，叹息欲绝兮泪阑干。\n\n　　胡笳本自出胡中，缘琴翻出音律同。十八拍兮曲虽终，响有余兮思无穷。是知丝竹微妙兮均造化之功，哀乐各随人心兮有变则通。胡与汉兮异域殊风，天与地隔兮子西母东。苦我怨气兮浩于长空，六合虽广兮受之应不容！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '胡笳十八拍' AND p.poem_author = '蔡文姬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜雨亭记', '苏轼', '宋代', '亭以雨名，志喜也。古者有喜，则以名物，示不忘也。周公得禾，以名其书；汉武得鼎，以名其年；叔孙胜敌，以名其子。其喜之大小不齐，其示不忘一也。\n\n　　予至扶风之明年，始治官舍。为亭于堂之北，而凿池其南，引流种木，以为休息之所。是岁之春，雨麦于岐山之阳，其占为有年。既而弥月不雨，民方以为忧。越三月，乙卯乃雨，甲子又雨，民以为未足。丁卯大雨，三日乃止。官吏相与庆于庭，商贾相与歌于市，农夫相与忭于野，忧者以喜，病者以愈，而吾亭适成。\n\n　　于是举酒于亭上，以属客而告之，曰：“五日不雨可乎？”曰：“五日不雨则无麦。”“十日不雨可乎？”曰：“十日不雨则无禾。”“无麦无禾，岁且荐饥，狱讼繁兴，而盗贼滋炽。则吾与二三子，虽欲优游以乐于此亭，其可得耶？今天不遗斯民，始旱而赐之以雨。使吾与二三子得相与优游以乐于此亭者，皆雨之赐也。其又可忘耶？”\n\n　　既以名亭，又从而歌之，曰：“使天而雨珠，寒者不得以为襦；使天而雨玉，饥者不得以为粟。一雨三日，伊谁之力？民曰太守。太守不有，归之天子。天子曰不然，归之造物。造物不自以为功，归之太空。太空冥冥，不可得而名。吾以名吾亭。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜雨亭记' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏煤炭', '于谦', '明代', '凿开混沌得乌金，藏蓄阳和意最深。\n爝火燃回春浩浩，洪炉照破夜沉沉。\n鼎彝元赖生成力，铁石犹存死后心。\n但愿苍生俱饱暖，不辞辛苦出山林。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏煤炭' AND p.poem_author = '于谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('永州八记', '柳宗元', '唐代', '始得西山宴游记\n\n　　自余为僇人，居是州。恒惴慄。时隙也，则施施而行，漫漫而游。日与其徒上高山，入深林，穷回溪，幽泉怪石，无远不到。到则披草而坐，倾壶而醉。醉则更相枕以卧，卧而梦。意有所极，梦亦同趣。觉而起，起而归。以为凡是州之山水有异态者，皆我有也，而未始知西山之怪特。\n\n　　今年九月二十八日，因坐法华西亭，望西山，始指异之。遂命仆人过湘江，缘染溪，斫榛莽，焚茅茷，穷山之高而上。攀援而登，箕踞而遨，则凡数州之土壤，皆在衽席之下。其高下之势，岈然洼然，若垤若穴，尺寸千里，攒蹙累积，莫得遁隐。萦青缭白，外与天际，四望如一。然后知是山之特立，不与培塿为类，悠悠乎与颢气俱，而莫得其涯；洋洋乎与造物者游，而不知其所穷。引觞满酌，颓然就醉，不知日之入。苍然暮色，自远而至，至无所见，而犹不欲归。心凝形释，与万化冥合。然后知吾向之未始游，游于是乎始，故为之文以志。是岁，元和四年也。\n\n\n钻鉧潭记\n\n　　钻鉧潭，在西山西。其始盖冉水自南奔注，抵山石，屈折东流；其颠委势峻，荡击益暴，啮其涯，故旁广而中深，毕至石乃止；流沫成轮，然后徐行。其清而平者，且十亩。有树环焉，有泉悬焉。\n\n　　其上有居者，以予之亟游也，一旦款门来告曰：“不胜官租、私券之委积，既芟山而更居，愿以潭上田贸财以缓祸。”\n\n　　予乐而如其言。则崇其台，延其槛，行其泉于高者而坠之潭，有声潀然。尤与中秋观月为宜，于以见天之高，气之迥。孰使予乐居夷而忘故土者，非兹潭也欤？\n\n\n钻鉧潭西小丘记\n\n　　得西山后八日，寻山口西北道二百步，有得钻鉧潭。潭西二十五步，当湍而浚者为鱼梁。梁之上有丘焉，生竹树。其石之突怒偃蹇，负土而出，争为奇状者，殆不可数。其嵚然相累而下者，若牛马之饮于溪；其冲然角列而上者，若熊罴之登于山。丘之小不能一亩，可以笼而有之。问其主，曰：“唐氏之弃地，货而不售。”问其价，曰：“止四百。”余怜而售之。李深源、元克已时同游，皆大喜，出自意外。即更取器用，铲刈秽草，伐去恶木，烈火而焚之。嘉木立，美竹露。奇石显。由其中以望，则山之高，云之浮，溪之流，鸟兽之遨游，举熙熙然回巧献技，以效兹丘之下。枕席而卧，则清冷冷状与目谋，瀯瀯之声与耳谋，悠然而虚者与神谋，渊然而静者与心谋。不匝旬而得异地者二，虽古好古之士，或未能至焉。\n\n　　噫！以兹丘之胜，致之沣、镐、、杜，则贵游之士争买者，日增千金而愈不可得。今弃是州也，农夫渔父过而陋之，贾四百，连岁不能售。而我与深源、克已独喜得之，是其果有遭乎！书于石，所以贺兹丘之遭也。\n\n\n至小丘西小石潭记\n\n　　从小丘西行百二十步，隔篁竹，闻水声，如鸣佩环，心乐之。伐竹取道，下见小潭，水尤清冽。全石以为底，近岸，卷石底以出，为坻，为屿，为嵁，为岩。青树翠蔓，蒙络摇缀，参差披拂。\n\n　　潭中鱼可百许头，皆若空游无所依。日光下澈，影布石上，佁然不动;俶尔远逝，往来翕忽，似与游者相乐。\n\n　　潭西南而望，斗折蛇行，明灭可见。其岸势犬牙差互，不可知其源。\n\n　　坐潭上，四面竹树环合，寂寥无人，凄神寒骨，悄怆幽邃。以其境过清，不可久居，乃记之而去。\n\n　　同游者：吴武陵，龚古，余弟宗玄。隶而从者，崔氏二小生：曰恕己，曰奉壹。\n\n\n袁家渴记\n\n　　由冉溪西南水行十里，山水之可取者五，莫若钻鉧潭。由溪口而西，陆行，可取者八九，莫若西山。由朝阳岩东南水行，至芜江，可取者三，莫若袁家渴。皆永中幽丽奇处也。\n\n　　楚越之间方言，谓水之反流为“渴”。渴上与南馆高嶂合，下与百家濑合。其中重洲小溪，澄潭浅渚，间厕曲折，平者深墨，峻者沸白。舟行若穷，忽而无际。\n\n　　有小山出水中，皆美石，上生青丛，冬夏常蔚然。其旁多岩词，其下多白砾，其树多枫柟石楠，樟柚，草则兰芷。又有奇卉，类合欢而蔓生，轇轕水石。\n\n　　每风自四山而下，振动大木，掩苒众草，纷红骇绿，蓊葧香气，冲涛旋濑，退贮溪谷，摇飃葳蕤，与时推移。其大都如此，余无以穷其状。\n\n　　永之人未尝游焉，余得之不敢专焉，出而传于世。其地主袁氏。故以名焉。\n\n\n石渠记\n\n　　自渴西南行不能百步，得石渠，民桥其上。有泉幽幽然，其鸣乍大乍细。渠之广或咫尺，或倍尺，其长可十许步。其流抵大石，伏出其下。踰石而往，有石泓，昌蒲被之，青鲜环周。又折西行，旁陷岩石下，北堕小潭。潭幅员减百尺，清深多倏鱼。又北曲行纡余，睨若无穷，然卒入于渴。其侧皆诡石、怪木、奇卉、美箭，可列坐而庥焉。风摇其巅，韵动崖谷。视之既静，其听始远。\n\n　　予从州牧得之。揽去翳朽，决疏土石，既崇而焚，既釃釃而盈。惜其未始有传焉者，故累记其所属，遗之其人，书之其阳，俾后好事者求之得以易。\n\n　　元和七年正月八日，鷁渠至大石。十月十九日，踰石得石泓小潭，渠之美于是始穷也。\n\n\n石涧记\n\n　　石渠之事既穷，上由桥西北下土山之阴，民又桥焉。其水之大，倍石渠三之一，亘石为底，达于两涯。若床若堂，若陈筳席，若限阃奥。水平布其上，流若织文，响若操琴。揭跣而往，折竹扫陈叶，排腐木，可罗胡床十八九居之。交络之流，触激之音，皆在床下；翠羽之水，龙鳞之石，均荫其上。古之人其有乐乎此耶？后之来者有能追予之践履耶？得之日，与石渠同。\n\n　　由渴而来者，先石渠，后石涧；由百家濑上而来者，先石涧，后石渠。涧之可穷者，皆出石城村东南，其间可乐者数焉。其上深山幽林逾峭险，道狭不可穷也。\n\n\n小石城山记\n\n　　自西山道口径北踰黄茅岭而下，有二道：其一西出，寻之无所得；其一少北而东，不过四十丈，土断二川分，有积石横当其垠。其上为睥睨梁欐之形；其旁出堡坞，有若门焉，窥之正黑，投以小石，洞然有水声，其响之激越，良久乃已。环之可上，望甚远。无土壤而生嘉树美箭，益奇而坚，奇疏数偃仰，类智者所施也。\n\n　　噫！吾疑造物者之有无久矣，及是，愈以为诚有。又怪其不为之中州而列是夷狄，更千百年不得一售其伎，是固劳而无用，神者倘不宜如是，则其果无乎？或曰：以慰夫贤而辱于此者。或曰：其气之灵，不为伟人而独为是物，故楚之南少人而多石。是二者余未信之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '永州八记' AND p.poem_author = '柳宗元';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哥舒歌' AND p.poem_author = '西鄙人';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔父·浪花有意千里雪', '李煜', '五代', '浪花有意千里雪，桃花无言一队春。一壶酒，一竿身，快活如侬有几人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔父·浪花有意千里雪' AND p.poem_author = '李煜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元日', '司空图', '唐代', '甲子今重数，生涯只自怜。\n殷勤元日日，欹午又明年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元日' AND p.poem_author = '司空图';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采蘩', '佚名', '先秦', '于以采蘩？于沼于沚。于以用之？公侯之事。\n于以采蘩？于涧之中。于以用之？公侯之宫。\n被之僮僮，夙夜在公。被之祁祁，薄言还归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采蘩' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望庐山瀑布水二首', '李白', '唐代', '西登香炉峰，南见瀑布水。挂流三百丈，喷壑数十里。 \n欻如飞电来，隐若白虹起。初惊河汉落，半洒云天里。 \n仰观势转雄，壮哉造化功。海风吹不断，江月照还空。 \n空中乱潈射，左右洗青壁。飞珠散轻霞，流沫沸穹石。 \n而我乐名山，对之心益闲。无论漱琼液，还得洗尘颜。 \n且谐宿所好，永愿辞人间。 \n日照香炉生紫烟，遥看瀑布挂前川。 \n飞流直下三千尺，疑是银河落九天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '望庐山瀑布水二首' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('更漏子·玉炉香', '温庭筠', '唐代', '玉炉香，红蜡泪，偏照画堂秋思。眉翠薄，鬓云残，夜长衾枕寒。\n梧桐树，三更雨，不道离情正苦。一叶叶，一声声，空阶滴到明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '更漏子·玉炉香' AND p.poem_author = '温庭筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('淮上喜会梁川故人 / 淮上喜会梁州故人', '韦应物', '唐代', '江汉曾为客，相逢每醉还。\n浮云一别后，流水十年间。\n欢笑情如旧，萧疏鬓已斑。\n何因不归去？淮上有秋山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '淮上喜会梁川故人 / 淮上喜会梁州故人' AND p.poem_author = '韦应物';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归嵩山作', '王维', '唐代', '清川带长薄，车马去闲闲。\n流水如有意，暮禽相与还。\n荒城临古渡，落日满秋山。\n迢递嵩高下，归来且闭关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归嵩山作' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿阳曲·远浦帆归', '马致远', '元代', '夕阳下，酒旆闲，两三航未曾着岸。落花水香茅舍晚，断桥头卖鱼人散。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '寿阳曲·远浦帆归' AND p.poem_author = '马致远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('把酒对月歌', '唐寅', '明代', '李白前时原有月，惟有李白诗能说。\n李白如今已仙去，月在青天几圆缺？\n今人犹歌李白诗，明月还如李白时。\n我学李白对明月，白与明月安能知！\n李白能诗复能酒，我今百杯复千首。\n我愧虽无李白才，料应月不嫌我丑。\n我也不登天子船，我也不上长安眠。\n姑苏城外一茅屋，万树梅花月满天。(梅花 一作：桃花)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '把酒对月歌' AND p.poem_author = '唐寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('神女赋', '宋玉', '先秦', '楚襄王与宋玉游于云梦之浦，使玉赋高唐之事。其夜玉寝，果梦与神女遇，其状甚丽，玉异之。明日，以白王。王曰：“其梦若何？”玉对曰：“晡夕之后，精神恍忽，若有所喜，纷纷扰扰，未知何意？目色仿佛，乍若有记：见一妇人，状甚奇异。寐而梦之，寤不自识；罔兮不乐，怅然失志。于是抚心定气，复见所梦。”王曰：“状何如也？”玉曰：“茂矣美矣，诸好备矣。盛矣丽矣，难测究矣。上古既无，世所未见，瑰姿玮态，不可胜赞。其始来也，耀乎若白日初出照屋梁；其少进也，皎若明月舒其光。须臾之间，美貌横生：晔兮如华，温乎如莹。五色并驰，不可殚形。详而视之，夺人目精。其盛饰也，则罗纨绮绩盛文章，极服妙采照万方。振绣衣，被袿裳，秾不短，纤不长，步裔裔兮曜殿堂，忽兮改容，婉若游龙乘云翔。嫷披服，侻薄装，沐兰泽，含若芳。性合适，宜侍旁，顺序卑，调心肠。”王曰：“若此盛矣，试为寡人赋之。”玉曰：“唯唯。”\n　　夫何神女之姣丽兮，含阴阳之渥饰。披华藻之可好兮，若翡翠之奋翼。其象无双，其美无极；毛嫱鄣袂，不足程式；西施掩面，比之无色。近之既妖，远之有望，骨法多奇，应君之相，视之盈目，孰者克尚。私心独悦，乐之无量；交希恩疏，不可尽畅。他人莫睹，王览其状。其状峨峨，何可极言。貌丰盈以庄姝兮，苞温润之玉颜。眸子炯其精朗兮，瞭多美而可视。眉联娟以蛾扬兮，朱唇地其若丹。素质干之实兮，志解泰而体闲。既姽婳于幽静兮，又婆娑乎人间。宜高殿以广意兮，翼故纵而绰宽。动雾以徐步兮，拂声之珊珊。望余帷而延视兮，若流波之将澜。奋长袖以正衽兮，立踯躅而不安。澹清静其兮，性沉详而不烦。时容与以微动兮，志未可乎得原。意似近而既远兮，若将来而复旋。褰余而请御兮，愿尽心之。怀贞亮之清兮，卒与我兮相难。陈嘉辞而云对兮，吐芬芳其若兰。精交接以来往兮，心凯康以乐欢。神独亨而未结兮，魂茕茕以无端。含然诺其不分兮，扬音而哀叹！薄怒以自持兮，曾不可乎犯干。\n　　于是摇佩饰，鸣玉鸾；奁衣服，敛容颜；顾女师，命太傅。欢情未接，将辞而去；迁延引身，不可亲附。似逝未行，中若相首；目略微眄，精采相授。志态横出，不可胜记。意离未绝，神心怖覆；礼不遑讫，辞不及究；愿假须臾，神女称遽。徊肠伤气，颠倒失据，黯然而暝，忽不知处。情独私怀，谁者可语？惆怅垂涕，求之至曙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '神女赋' AND p.poem_author = '宋玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阙题', '刘昚虚', '唐代', '道由白云尽，春与青溪长。\n时有落花至，远随流水香。\n闲门向山路，深柳读书堂。\n幽映每白日，清辉照衣裳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阙题' AND p.poem_author = '刘昚虚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宴词', '王之涣', '唐代', '长堤春水绿悠悠，畎入漳河一道流。\n莫听声声催去棹，桃溪浅处不胜舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宴词' AND p.poem_author = '王之涣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渡江云三犯·西湖清明', '吴文英', '宋代', '羞红颦浅恨，晚风未落，片绣点重茵。旧堤分燕尾，桂棹轻鸥，宝勒倚残云。千丝怨碧，渐路入、仙坞迷津。肠漫回，隔花时见，背面楚腰身。 \n逡巡。题门惆怅，堕履牵萦，数幽期难准。还始觉、留情缘眼，宽带因春。明朝事与孤烟冷，做满湖、风雨愁人。山黛暝，尘波澹绿无痕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渡江云三犯·西湖清明' AND p.poem_author = '吴文英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('少年游·草', '高观国', '宋代', '春风吹碧，春云映绿，晓梦入芳裀。软衬飞花，远连流水，一望隔香尘。 \n萋萋多少江南恨，翻忆翠罗裙。冷落闲门，凄迷古道，烟雨正愁人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '少年游·草' AND p.poem_author = '高观国';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔家傲·平岸小桥千嶂抱', '王安石', '宋代', '平岸小桥千嶂抱。柔蓝一水萦花草。茅屋数间窗窈窕。尘不到。时时自有春风扫。\n午枕觉来闻语鸟。欹眠似听朝鸡早。忽忆故人今总老。贪梦好。茫然忘了邯郸道。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔家傲·平岸小桥千嶂抱' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('调笑令·边草', '戴叔伦', '唐代', '边草，边草，边草尽来兵老。山南山北雪晴， \n千里万里月明。明月，明月，胡笳一声愁绝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '调笑令·边草' AND p.poem_author = '戴叔伦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饮酒', '柳宗元', '唐代', '今夕少愉乐，起坐开清尊。举觞酹先酒，为我驱忧烦。\n须臾心自殊，顿觉天地暄。连山变幽晦，绿水函晏温。\n蔼蔼南郭门，树木一何繁。清阴可自庇，竟夕闻佳言。\n尽醉无复辞，偃卧有芳荪。彼哉晋楚富，此道未必存。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饮酒' AND p.poem_author = '柳宗元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋夜曲', '王维', '唐代', '桂魄初生秋露微，轻罗已薄未更衣。\n银筝夜久殷勤弄，心怯空房不忍归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋夜曲' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('点绛唇·桃源', '秦观', '宋代', '醉漾轻舟，信流引到花深处。尘缘相误，无计花间住。 \n烟水茫茫，千里斜阳暮。山无数，乱红如雨。不记来时路。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '点绛唇·桃源' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怨郎诗', '卓文君', '两汉', '一朝别后，二地相悬。\n只说是三四月，又谁知五六年？\n七弦琴无心弹，八行书无可传。\n九连环从中折断，十里长亭望眼欲穿。\n百思想，千系念，万般无奈把郎怨。\n万语千言说不完，百无聊赖，十依栏杆。\n重九登高看孤雁，八月仲秋月圆人不圆。\n七月半，秉烛烧香问苍天，\n六月三伏天，人人摇扇我心寒。\n五月石榴红似火，偏遇阵阵冷雨浇花端。\n四月枇杷未黄，我欲对镜心意乱。\n忽匆匆，三月桃花随水转。\n飘零零，二月风筝线儿断。\n噫，郎呀郎，巴不得下一世，你为女来我做男。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怨郎诗' AND p.poem_author = '卓文君';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白马篇', '李白', '唐代', '龙马花雪毛，金鞍五陵豪。\n秋霜切玉剑，落日明珠袍。\n斗鸡事万乘，轩盖一何高。\n弓摧南山虎，手接太行猱。\n酒后竞风采，三杯弄宝刀。\n杀人如剪草，剧孟同游遨。\n发愤去函谷，从军向临洮。\n叱咤经百战，匈奴尽奔逃。\n归来使酒气，未肯拜萧曹。\n羞入原宪室，荒淫隐蓬蒿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白马篇' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('淮中晚泊犊头', '苏舜钦', '宋代', '春阴垂野草青青，时有幽花一树明。\n晚泊孤舟古祠下，满川风雨看潮生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '淮中晚泊犊头' AND p.poem_author = '苏舜钦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋夕', '白居易', '唐代', '叶声落如雨，月色白似霜。\n夜深方独卧，谁为拂尘床。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋夕' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹枝词二首·其二', '刘禹锡', '唐代', '楚水巴山江雨多，巴人能唱本乡歌。\n今朝北客思归去，回入纥那披绿罗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹枝词二首·其二' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('马嵬', '袁枚', '清代', '莫唱当年长恨歌，人间亦自有银河。\n石壕村里夫妻别，泪比长生殿上多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '马嵬' AND p.poem_author = '袁枚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('遣悲怀三首·其三', '元稹', '唐代', '闲坐悲君亦自悲，百年都是几多时。\n邓攸无子寻知命，潘岳悼亡犹费词。\n同穴窅冥何所望，他生缘会更难期。\n惟将终夜常开眼，报答平生未展眉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '遣悲怀三首·其三' AND p.poem_author = '元稹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙·缥缈红妆照浅溪', '苏轼', '宋代', '缥缈红妆照浅溪。薄云疏雨不成泥。送君何处古台西。\n废沼夜来秋水满，茂林深处晚莺啼。行人肠断草凄迷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙·缥缈红妆照浅溪' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆秦娥·情脉脉', '程垓', '宋代', '情脉脉。半黄橙子和香擘。和香擘。分明记得，袖香熏窄。 \n别来人远关山隔。见梅不忍和花摘。和花摘。有书无雁，寄谁归得。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆秦娥·情脉脉' AND p.poem_author = '程垓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('减字木兰花·卖花担上', '李清照', '宋代', '卖花担上。买得一枝春欲放。泪染轻匀。犹带彤霞晓露痕。 \n怕郎猜道。奴面不如花面好。云鬓斜簪。徒要教郎比并看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '减字木兰花·卖花担上' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青门柳', '白居易', '唐代', '青青一树伤心色，曾入几人离恨中。 \n为近都门多送别，长条折尽减春风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青门柳' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江汉', '杜甫', '唐代', '江汉思归客，乾坤一腐儒。\n片云天共远，永夜月同孤。\n落日心犹壮，秋风病欲疏。(病欲\'疏\', 一作：苏)\n古来存老马，不必取长途。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江汉' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送董邵南游河北序', '韩愈', '唐代', '燕赵古称多感慨悲歌之士。董生举进士，屡不得志于有司，怀抱利器，郁郁适兹土。吾知其必有合也。董生勉乎哉！\n\n　　夫以子之不遇时，苟慕义强仁者皆爱惜焉。矧燕赵之士出乎其性者哉！然吾尝闻风俗与化移易，吾恶知其今不异于古所云邪?聊以吾子之行卜之也。董生勉乎哉！\n\n　　吾因子有所感矣。为我吊望诸君之墓，而观于其市，复有昔时屠狗者乎？为我谢曰：“明天子在上，可以出而仕矣。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送董邵南游河北序' AND p.poem_author = '韩愈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·寒日萧萧上琐窗', '李清照', '宋代', '寒日萧萧上琐窗，梧桐应恨夜来霜。酒阑更喜团茶苦，梦断偏宜瑞脑香。\n秋已尽，日犹长，仲宣怀远更凄凉。不如随分尊前醉，莫负东篱菊蕊黄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·寒日萧萧上琐窗' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('垂老别', '杜甫', '唐代', '四郊未宁静，垂老不得安。子孙阵亡尽，焉用身独完。 \n投杖出门去，同行为辛酸。幸有牙齿存，所悲骨髓干。 \n男儿既介胄，长揖别上官。老妻卧路啼，岁暮衣裳单。 \n孰知是死别，且复伤其寒。此去必不归，还闻劝加餐。 \n土门壁甚坚，杏园度亦难。势异邺城下，纵死时犹宽。 \n人生有离合，岂择衰老端。忆昔少壮日，迟回竟长叹。 \n万国尽征戍，烽火被冈峦。积尸草木腥，流血川原丹。 \n何乡为乐土，安敢尚盘桓。弃绝蓬室居，塌然摧肺肝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '垂老别' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南乡子·冬夜', '黄升', '宋代', '万籁寂无声。衾铁稜稜近五更。香断灯昏吟未稳，凄清。只有霜华伴月明。\n应是夜寒凝。恼得梅花睡不成。我念梅花花念我，关情。起看清冰满玉瓶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南乡子·冬夜' AND p.poem_author = '黄升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读书', '皮日休', '唐代', '家资是何物，积帙列梁梠。\n高斋晓开卷，独共圣人语。\n英贤虽异世，自古心相许。\n案头见蠹鱼，犹胜凡俦侣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读书' AND p.poem_author = '皮日休';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诉衷情·眉意', '欧阳修', '宋代', '清晨帘幕卷轻霜。呵手试梅妆。都缘自有离恨，故画作远山长。\n思往事，惜流芳。易成伤。拟歌先敛，欲笑还颦，最断人肠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诉衷情·眉意' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('离骚', '陆龟蒙', '唐代', '天问复招魂，无因彻帝阍。\n岂知千丽句，不敌一谗言。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '离骚' AND p.poem_author = '陆龟蒙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('方山子传', '苏轼', '宋代', '方山子，光、黄间隐人也。少时慕朱家、郭解为人，闾里之侠皆宗之。稍壮，折节读书，欲以此驰骋当世，然终不遇。晚乃遁于光、黄间，曰岐亭。庵居蔬食，不与世相闻。弃车马，毁冠服，徒步往来山中，人莫识也。见其所著帽，方耸而高，曰：“此岂古方山冠之遗象乎？”因谓之方山子。\n\n　　余谪居于黄，过岐亭，适见焉。曰：“呜呼！此吾故人陈慥季常也。何为而在此？”方山子亦矍然，问余所以至此者。余告之故。俯而不答，仰而笑，呼余宿其家。环堵萧然，而妻子奴婢皆有自得之意。余既耸然异之。\n\n　　独念方山子少时，使酒好剑，用财如粪土。前十九年，余在岐山，见方山子从两骑，挟二矢，游西山。鹊起于前，使骑逐而射之，不获。方山子怒马独出，一发得之。因与余马上论用兵及古今成败，自谓一世豪士。今几日耳，精悍之色犹见于眉间，而岂山中之人哉？\n\n　　然方山子世有勋阀，当得官，使从事于其间，今已显闻。而其家在洛阳，园宅壮丽与公侯等。河北有田，岁得帛千匹，亦足以富乐。皆弃不取，独来穷山中，此岂无得而然哉？\n\n　　余闻光、黄间多异人，往往阳狂垢污，不可得而见。方山子倘见之欤？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '方山子传' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('枭逢鸠 / 枭将东徙', '刘向', '两汉', '鸠曰：“子将安之？”\n枭曰：“我将东徙。”\n鸠曰：“何故？”\n枭曰：“乡人皆恶我鸣。以故东徙。”\n鸠曰：“子能更鸣，可矣；不能更鸣，东徙，犹恶子之声。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '枭逢鸠 / 枭将东徙' AND p.poem_author = '刘向';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送朱大入秦', '孟浩然', '唐代', '游人五陵去，宝剑值千金。\n分手脱相赠，平生一片心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送朱大入秦' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('美女篇', '曹植', '魏晋', '美女妖且闲，采桑歧路间。\n柔条纷冉冉，叶落何翩翩。\n攘袖见素手，皓腕约金环。\n头上金爵钗，腰佩翠琅玕。\n明珠交玉体，珊瑚间木难。\n罗衣何飘飘，轻裾随风还。\n顾盼遗光彩，长啸气若兰。\n行徒用息驾，休者以忘餐。\n借问女安居，乃在城南端。\n青楼临大路，高门结重关。\n容华耀朝日，谁不希令颜？\n媒氏何所营？玉帛不时安。\n佳人慕高义，求贤良独难。\n众人徒嗷嗷，安知彼所观？\n盛年处房室，中夜起长叹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '美女篇' AND p.poem_author = '曹植';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元日', '成彦雄', '唐代', '戴星先捧祝尧觞，镜里堪惊两鬓霜。 \n好是灯前偷失笑，屠苏应不得先尝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元日' AND p.poem_author = '成彦雄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('溪居即事', '崔道融', '唐代', '篱外谁家不系船，春风吹入钓鱼湾。 \n小童疑是有村客，急向柴门去却关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '溪居即事' AND p.poem_author = '崔道融';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('柳', '李商隐', '唐代', '曾逐东风拂舞筵，乐游春苑断肠天。 \n如何肯到清秋日，已带斜阳又带蝉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '柳' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('垂钓', '白居易', '唐代', '临水一长啸，忽思十年初。三登甲乙第，一入承明庐。 \n浮生多变化，外事有盈虚。今来伴江叟，沙头坐钓鱼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '垂钓' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('写情', '李益', '唐代', '水纹珍簟思悠悠，千里佳期一夕休。\n从此无心爱良夜，任他明月下西楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '写情' AND p.poem_author = '李益';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('项羽之死', '司马迁', '两汉', '项王军壁垓下，兵少食尽，汉军及诸侯兵围之数重。夜闻汉军四面皆楚歌，项王乃大惊曰：“汉皆已得楚乎？是何楚人之多也！”项王则夜起，饮帐中。有美人名虞，常幸从；骏马名骓，常骑之。于是项王乃悲歌慷慨，自为诗曰：“力拔山兮气盖世，时不利兮骓不逝。骓不逝兮可奈何，虞兮虞兮奈若何！”歌数阕，美人和之。项王泣数行下，左右皆泣，莫能仰视。\n\n　　于是项王乃上马骑，麾下壮士骑从者八百余人，直夜溃围南出，驰走。平明，汉军乃觉之，令骑将灌婴以五千骑追之。项王渡淮，骑能属者百余人耳。项王至阴陵，迷失道，问一田父，田父绐曰“左”。左，乃陷大泽中。以故汉追及之。项王乃复引兵而东，至东城，乃有二十八骑。汉骑追者数千人。项王自度不得脱。谓其骑曰：“吾起兵至今八岁矣，身七十余战，所当者破，所击者服，未尝败北，遂霸有天下。然今卒困于此，此天之亡我，非战之罪也。今日固决死，愿为诸君快战，必三胜之，为诸君溃围，斩将，刈旗，令诸君知天亡我，非战之罪也。”\n\n　　乃分其骑以为四队，四向。汉军围之数重。项王谓其骑曰：“吾为公取彼一将。”令四面骑驰下，期山东为三处。于是项王大呼驰下，汉军皆披靡，遂斩汉一将。是时，赤泉侯为骑将，追项王，项王瞋目而叱之，赤泉侯人马俱惊，辟易数里。与其骑会为三处。汉军不知项王所在，乃分军为三，复围之。项王乃驰，复斩汉一都尉，杀数十百人，复聚其骑，亡其两骑耳。乃谓其骑曰：“何如？”骑皆伏曰：“如大王言。”\n\n　　于是项王乃欲东渡乌江。乌江亭长檥船待，谓项王曰：“江东虽小，地方千里，众数十万人，亦足王也。愿大王急渡。今独臣有船，汉军至，无以渡。”项王笑曰：“天之亡我，我何渡为！且籍与江东子弟八千人渡江而西，今无一人还，纵江东父兄怜而王我，我何面目见之？纵彼不言，籍独不愧于心乎？”乃谓亭长曰：“吾知公长者。吾骑此马五岁，所当无敌，尝一日行千里，不忍杀之，以赐公。”乃令骑皆下马步行，持短兵接战。独籍所杀汉军数百人。项王身亦被十余创。顾见汉骑司马吕马童，曰：“若非吾故人乎？”马童面之，指王翳曰：“此项王也。”项王乃曰：“吾闻汉购我头千金，邑万户，吾为若德。”乃自刎而死。王翳取其头，余骑相蹂践争项王，相杀者数十人。最其后，郎中骑杨喜，骑司马吕马童，郎中吕胜、杨武各得其一体。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '项羽之死' AND p.poem_author = '司马迁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('初秋行圃', '杨万里', '宋代', '落日无情最有情，遍催万树暮蝉鸣。\n听来咫尺无寻处，寻到旁边却不声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '初秋行圃' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('纳凉', '秦观', '宋代', '携扙来追柳外凉，画桥南畔倚胡床。\n月明船笛参差起，风定池莲自在香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '纳凉' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('好事近·梦中作', '秦观', '宋代', '春路雨添花，花动一山春色。行到小溪深处，有黄鹂千百。 \n飞云当面化龙蛇，夭矫转空碧。醉卧古藤阴下，了不知南北。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '好事近·梦中作' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨霖铃·孜孜矻矻', '王安石', '宋代', '孜孜矻矻。向无明里、强作窠窟。浮名浮利何济，堪留恋处，轮回仓猝。幸有明空妙觉，可弹指超出。缘底事、抛了全潮，认一浮沤作瀛渤。本源自性天真佛。只些些、妄想中埋没。贪他眼花阳艳，谁信道、本来无物。一旦茫然，终被阎罗老子相屈。便纵有、千种机筹，怎免伊唐突。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨霖铃·孜孜矻矻' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('北青萝', '李商隐', '唐代', '残阳西入崦，茅屋访孤僧。落叶人何在，寒云路几层。 \n独敲初夜磬，闲倚一枝藤。世界微尘里，吾宁爱与憎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '北青萝' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠去婢', '崔郊', '唐代', '公子王孙逐后尘，绿珠垂泪滴罗巾。\n侯门一入深如海，从此萧郎是路人。(如海 一作：似海)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠去婢' AND p.poem_author = '崔郊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送人游岭南', '司空曙', '唐代', '万里南游客，交州见柳条。\n逢迎人易合，时日酒能消。\n浪晓浮青雀，风温解黑貂。\n囊金如未足，莫恨故乡遥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送人游岭南' AND p.poem_author = '司空曙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长安古意', '卢照邻', '唐代', '长安大道连狭斜，青牛白马七香车。\n玉辇纵横过主第，金鞭络绎向侯家。\n龙衔宝盖承朝日，凤吐流苏带晚霞。\n百尺游丝争绕树，一群娇鸟共啼花。(百尺 一作：百丈）\n游蜂戏蝶千门侧，碧树银台万种色。\n复道交窗作合欢，双阙连甍垂凤翼。\n梁家画阁中天起，汉帝金茎云外直。\n楼前相望不相知，陌上相逢讵相识。\n借问吹箫向紫烟，曾经学舞度芳年。\n得成比目何辞死，愿作鸳鸯不羡仙。\n比目鸳鸯真可羡，双去双来君不见。\n生憎帐额绣孤鸾，好取门帘帖双燕。\n双燕双飞绕画梁，罗帷翠被郁金香。\n片片行云着蝉鬓，纤纤初月上鸦黄。\n鸦黄粉白车中出，含娇含态情非一。\n妖童宝马铁连钱，娼妇盘龙金屈膝。\n御史府中乌夜啼，廷尉门前雀欲栖。\n隐隐朱城临玉道，遥遥翠幰没金堤。\n挟弹飞鹰杜陵北，探丸借客渭桥西。\n俱邀侠客芙蓉剑，共宿娼家桃李蹊。\n娼家日暮紫罗裙，清歌一啭口氛氲。\n北堂夜夜人如月，南陌朝朝骑似云。\n南陌北堂连北里，五剧三条控三市。\n弱柳青槐拂地垂，佳气红尘暗天起。\n汉代金吾千骑来，翡翠屠苏鹦鹉杯。\n罗襦宝带为君解，燕歌赵舞为君开。\n别有豪华称将相，转日回天不相让。\n意气由来排灌夫，专权判不容萧相。\n专权意气本豪雄，青虬紫燕坐春风。\n自言歌舞长千载，自谓骄奢凌五公。\n节物风光不相待，桑田碧海须臾改。\n昔时金阶白玉堂，即今惟见青松在。(惟见 一作：唯见)\n寂寂寥寥扬子居，年年岁岁一床书。\n独有南山桂花发，飞来飞去袭人裾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长安古意' AND p.poem_author = '卢照邻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采蘋', '佚名', '先秦', '于以采蘋？南涧之滨。于以采藻？于彼行潦。\n于以盛之？维筐及筥。于以湘之？维锜及釜。\n于以奠之？宗室牖下。谁其尸之？有齐季女。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采蘋' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沉醉东风·七夕', '卢挚', '元代', '银烛冷秋光画屏，碧天晴夜静闲亭。蛛丝度绣针，龙麝焚金鼎。庆人间七夕佳令。卧看牵牛织女星，月转过梧桐树影。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沉醉东风·七夕' AND p.poem_author = '卢挚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元夕二首', '王守仁', '明代', '故园今夕是元宵，独向蛮村坐寂寥。\n赖有遗经堪作伴，喜无车马过相邀。\n春还草阁梅先动，月满虚庭雪未消。\n堂上花灯诸第集，重闱应念一身遥。\n\n去年今日卧燕台，铜鼓中宵隐地雷。\n月傍苑楼灯影暗，风传阁道马蹄回。\n炎荒万里频回首，羌笛三更谩自哀。\n尚忆先朝多乐事，孝皇曾为两宫开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元夕二首' AND p.poem_author = '王守仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·昨夜秋风来万里', '苏轼', '宋代', '昨夜秋风来万里。月上屏帏，冷透人衣袂。有客抱衾愁不寐。那堪玉漏长如岁。\n羁舍留连归计未。梦断魂销，一枕相思泪。衣带渐宽无别意。新书报我添憔悴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·昨夜秋风来万里' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贫女', '秦韬玉', '唐代', '蓬门未识绮罗香，拟托良媒益自伤。\n谁爱风流高格调，共怜时世俭梳妆。\n敢将十指夸针巧，不把双眉斗画长。\n苦恨年年压金线，为他人作嫁衣裳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贫女' AND p.poem_author = '秦韬玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('近试上张籍水部 / 近试上张水部 / 闺意献张水部', '朱庆馀', '唐代', '洞房昨夜停红烛，待晓堂前拜舅姑。 \n妆罢低声问夫婿，画眉深浅入时无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '近试上张籍水部 / 近试上张水部 / 闺意献张水部' AND p.poem_author = '朱庆馀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蓼莪', '佚名', '先秦', '蓼蓼者莪，匪莪伊蒿。哀哀父母，生我劬劳。\n\n蓼蓼者莪，匪莪伊蔚。哀哀父母，生我劳瘁。\n\n瓶之罄矣，维罍之耻。鲜民之生，不如死之久矣。无父何怙？无母何恃？出则衔恤，入则靡至。\n\n父兮生我，母兮鞠我。抚我畜我，长我育我，顾我复我，出入腹我。欲报之德。昊天罔极！\n\n南山烈烈，飘风发发。民莫不穀，我独何害！南山律律，飘风弗弗。民莫不穀，我独不卒！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蓼莪' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄州快哉亭记', '苏辙', '宋代', '江出西陵，始得平地，其流奔放肆大。南合沅、湘 ，北合汉沔，其势益张。至于赤壁之下，波流浸灌，与海相若。清河张君梦得谪居齐安，即其庐之西南为亭，以览观江流之胜，而余兄子瞻名之曰“快哉”。\n\n　　盖亭之所见，南北百里，东西一舍。涛澜汹涌，风云开阖。昼则舟楫出没于其前，夜则鱼龙悲啸于其下。变化倏忽，动心骇目，不可久视。今乃得玩之几席之上，举目而足。西望武昌诸山，冈陵起伏，草木行列，烟消日出。渔夫樵父之舍，皆可指数。此其所以为“快哉”者也。至于长洲之滨，故城之墟。曹孟德、孙仲谋之所睥睨，周瑜、陆逊之所骋骛。其流风遗迹，亦足以称快世俗。\n\n　　昔楚襄王从宋玉、景差于兰台之宫，有风飒然至者，王披襟当之，曰：“快哉此风！寡人所与庶人共者耶？”宋玉曰：“此独大王之雄风耳，庶人安得共之！”玉之言盖有讽焉。夫风无雌雄之异，而人有遇，不遇之变；楚王之所以为乐，与庶人之所以为忧，此则人之变也，而风何与焉？士生于世，使其中不自得，将何往而非病？使其中坦然，不以物伤性，将何适而非快？今张君不以谪为患，窃会计之余功，而自放山水之间，此其中宜有以过人者。将蓬户瓮牖无所不快；而况乎濯长江之清流，揖西山之白云 ，穷耳目之胜以自适也哉！不然，连山绝壑，长林古木，振之以清风，照之以明月，此皆骚人思士之所以悲伤憔悴而不能胜者，乌睹其为快也哉！\n\n　　元丰六年十一月朔日，赵郡苏辙记。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄州快哉亭记' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿甘露寺僧舍', '曾公亮', '宋代', '枕中云气千峰近，床底松声万壑哀。\n要看银山拍天浪，开窗放入大江来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿甘露寺僧舍' AND p.poem_author = '曾公亮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送友人', '薛涛', '唐代', '水国蒹葭夜有霜，月寒山色共苍苍。 \n谁言千里自今夕，离梦杳如关塞长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送友人' AND p.poem_author = '薛涛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七夕', '徐凝', '唐代', '一道鹊桥横渺渺，千声玉佩过玲玲。\n别离还有经年客，怅望不如河鼓星。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七夕' AND p.poem_author = '徐凝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无家别', '杜甫', '唐代', '寂寞天宝后，园庐但蒿藜。我里百余家，世乱各东西。\n存者无消息，死者为尘泥。贱子因阵败，归来寻旧蹊。\n久行见空巷，日瘦气惨凄，但对狐与狸，竖毛怒我啼。\n四邻何所有，一二老寡妻。宿鸟恋本枝，安辞且穷栖。\n方春独荷锄，日暮还灌畦。县吏知我至，召令习鼓鞞。\n虽从本州役，内顾无所携。近行止一身，远去终转迷。\n家乡既荡尽，远近理亦齐。永痛长病母，五年委沟溪。\n生我不得力，终身两酸嘶。人生无家别，何以为蒸黎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无家别' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('碛中作', '岑参', '唐代', '走马西来欲到天，辞家见月两回圆。\n今夜不知何处宿，平沙万里绝人烟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '碛中作' AND p.poem_author = '岑参';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄李儋元锡', '韦应物', '唐代', '去年花里逢君别，今日花开又一年。\n世事茫茫难自料，春愁黯黯独成眠。\n身多疾病思田里，邑有流亡愧俸钱。\n闻道欲来相问讯，西楼望月几回圆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄李儋元锡' AND p.poem_author = '韦应物';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长相思三首', '李白', '唐代', '长相思，在长安。\n络纬秋啼金井阑，微霜凄凄簟色寒。\n孤灯不明思欲绝，卷帷望月空长叹。\n美人如花隔云端。\n上有青冥之高天，下有渌水之波澜。\n天长路远魂飞苦，梦魂不到关山难。\n长相思，摧心肝。\n\n日色欲尽花含烟，月明欲素愁不眠。\n赵瑟初停凤凰柱，蜀琴欲奏鸳鸯弦。\n此曲有意无人传，愿随春风寄燕然。\n忆君迢迢隔青天。\n昔时横波目，今作流泪泉。\n不信妾肠断，归来看取明镜前。\n\n美人在时花满堂，美人去后花馀床。\n床中绣被卷不寝，至今三载闻余香。\n香亦竟不灭，人亦竟不来。\n相思黄叶落，白露湿青苔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长相思三首' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('铜雀台赋', '曹植', '魏晋', '从明后而嬉游兮，登层台以娱情。\n见太府之广开兮，观圣德之所营。\n建高门之嵯峨兮，浮双阙乎太清。\n立中天之华观兮，连飞阁乎西城。\n临漳水之长流兮，望园果之滋荣。\n仰春风之和穆兮，听百鸟之悲鸣。\n天云垣其既立兮，家愿得而获逞。\n扬仁化于宇内兮，尽肃恭于上京。\n惟桓文之为盛兮，岂足方乎圣明！\n休矣美矣！惠泽远扬。\n翼佐我皇家兮，宁彼四方。\n同天地之规量兮，齐日月之晖光。\n永贵尊而无极兮，等年寿于东王。《三国志》版\n\n从明后以嬉游兮，登层台以娱情。\n见太府之广开兮，观圣德之所营。\n建高门之嵯峨兮，浮双阙乎太清。\n立中天之华观兮，连飞阁乎西城。\n临漳水之长流兮，望园果之滋荣。\n立双台于左右兮，有玉龙与金凤。\n揽二乔于东南兮，乐朝夕之与共。\n俯皇都之宏丽兮，瞰云霞之浮动。\n欣群才之来萃兮，协飞熊之吉梦。\n仰春风之和穆兮，听百鸟之悲鸣。\n云天亘其既立兮，家愿得乎双逞。\n扬仁化于宇宙兮，尽肃恭于上京。\n惟桓文之为盛兮，岂足方乎圣明？\n休矣美矣！惠泽远扬。\n翼佐我皇家兮，宁彼四方。\n同天地之规量兮，齐日月之辉光。\n永贵尊而无极兮，等君寿于东皇。\n御龙旗以遨游兮，回鸾驾而周章。\n恩化及乎四海兮，嘉物阜而民康。\n愿斯台之永固兮，乐终古而未央！《三国演义》版', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '铜雀台赋' AND p.poem_author = '曹植';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('昼夜乐·洞房记得初相遇', '柳永', '宋代', '洞房记得初相遇。便只合、长相聚。何期小会幽欢，变作离情别绪。况值阑珊春色暮，对满目、乱花狂絮。直恐好风光，尽随伊归去。 \n一场寂寞凭谁诉。算前言、总轻负。早知恁地难拚，悔不当时留住。其奈风流端正外，更别有，系人心处。一日不思量，也攒眉千度。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '昼夜乐·洞房记得初相遇' AND p.poem_author = '柳永';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采葛', '佚名', '先秦', '彼采葛兮，一日不见，如三月兮！\n彼采萧兮，一日不见，如三秋兮！\n彼采艾兮！一日不见，如三岁兮！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采葛' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二子乘舟', '佚名', '先秦', '二子乘舟，泛泛其景。愿言思子，中心养养！\n二子乘舟，泛泛其逝。愿言思子，不瑕有害！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二子乘舟' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('念奴娇·梅', '辛弃疾', '宋代', '疏疏淡淡，问阿谁、堪比天真颜色。笑杀东君虚占断，多少朱朱白白。雪里温柔，水边明秀，不借春工力。骨清香嫩，迥然天与奇绝。 \n尝记宝篽寒轻，琐窗人睡起，玉纤轻摘。漂泊天涯空瘦损，犹有当年标格。万里风烟，一溪霜月，未怕欺他得。不如归去，阆苑有个人忆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '念奴娇·梅' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('人有负盐负薪者', '李延寿', '唐代', '人有负盐负薪者，同释重担息树阴。少时，且行，争一羊皮，各言藉背之物。久未果，遂讼于官。惠遣争者出，顾州纪纲曰：“以此羊皮可拷知主乎?”群下咸无答者。惠令人置羊皮席上，以杖击之，见少盐屑，曰：“得其实矣。”使争者视之，负薪者乃伏而就罪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '人有负盐负薪者' AND p.poem_author = '李延寿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('村居', '张舜民', '宋代', '水绕陂田竹绕篱，榆钱落尽槿花稀。\n夕阳牛背无人卧，带得寒鸦两两归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '村居' AND p.poem_author = '张舜民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('减字木兰花·莺初解语', '苏轼', '宋代', '莺初解语，最是一年春好处。微雨如酥，草色遥看近却无。\n休辞醉倒，花不看开人易老。莫待春回，颠倒红英间绿苔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '减字木兰花·莺初解语' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贺新郎·夏景', '苏轼', '宋代', '乳燕飞华屋。悄无人、桐阴转午，晚凉新浴。手弄生绡白团扇，扇手一时似玉。渐困倚、孤眠清熟。帘外谁来推绣户，枉教人、梦断瑶台曲。又却是，风敲竹。 \n石榴半吐红巾蹙。待浮花、浪蕊都尽，伴君幽独。秾艳一枝细看取，芳心千重似束。又恐被、秋风惊绿。若待得君来向此，花前对酒不忍触。共粉泪，两簌簌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贺新郎·夏景' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和乐天春词', '刘禹锡', '唐代', '新妆宜面下朱楼，深锁春光一院愁。 \n行到中庭数花朵，蜻蜓飞上玉搔头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和乐天春词' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('子鱼论战', '左丘明', '先秦', '二十有二年春，公伐邾，取须句。夏，宋公、卫侯、许男、滕子伐郑。秋，八月丁未，及邾人战于升陉。冬，十有一月己巳朔，宋公及楚人战于泓，宋师败绩。\n\n　　楚人伐宋以救郑。宋公将战。大司马固谏曰：“天之弃商久矣，君将兴之，弗可赦也已。”弗听。冬十一月己巳朔，宋公及楚人战于泓。宋人既成列，楚人未既济。司马曰：“彼众我寡，及其未既济也，请击之。”公曰：“不可。”既济而未成列，又以告。公曰：“未可。”既陈而后击之，宋师败绩。公伤股，门官歼焉。\n\n　　国人皆咎公。公曰：“君子不重伤，不禽二毛。古之为军也，不以阻隘也。寡人虽亡国之余，不鼓不成列。”子鱼曰：“君未知战。勍敌之人，隘而不列，天赞我也。阻而鼓之，不亦可乎？犹有惧焉！且今之勍者，皆我敌也。虽及胡耇，获则取之，何有于二毛？明耻教战，求杀敌也。伤未及死，如何勿重？若爱重伤，则如勿伤；爱其二毛，则如服焉。三军以利用也，金鼓以声气也。利而用之，阻隘可也；声盛致志，鼓儳可也。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '子鱼论战' AND p.poem_author = '左丘明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·梦入江南烟水路', '晏几道', '宋代', '梦入江南烟水路，行尽江南，不与离人遇。睡里消魂无说处，觉来惆怅消魂误。\n欲尽此情书尺素，浮雁沉鱼，终了无凭据。却倚缓弦歌别绪，断肠移破秦筝柱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·梦入江南烟水路' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('问说', '刘开', '清代', '君子之学必好问。问与学，相辅而行者也。非学无以致疑，非问无以广识；好学而不勤问，非真能好学者也。理明矣，而或不达于事；识其大矣，而或不知其细，舍问，其奚决焉？\n\n　　贤于己者，问焉以破其疑，所谓“就有道而正”也。不如己者，问焉以求一得，所谓“以能问于不能，以多问于寡”也。等于己者，问焉以资切磋，所谓交相问难(nàn)，审问而明辨之也。《书》不云乎？“好问则裕。”孟子论：“求放心”，而并称曰“学问之道”，学即继以问也。子思言“尊德性”，而归于“道问学”，问且先于学也。\n\n　　古之人虚中乐善，不择事而问焉，不择人而问焉，取其有益于身而已。是故狂夫之言，圣人择之，刍荛(ráo)之微，先民询之，舜以天子而询于匹夫，以大知而察及迩言，非苟为谦，诚取善之弘也。三代而下，有学而无问，朋友之交，至于劝善规过足矣，其以义理相咨访，孜孜焉唯进修是急，未之多见也，况流俗乎？\n\n　　是己而非人，俗之同病。学有未达，强以为知；理有未安，妄以臆度。如是，则终身几无可问之事。贤于己者，忌之而不愿问焉；不如己者，轻之而不屑问焉；等于己者，狎xiá之而不甘问焉，如是，则天下几无可问之人。人不足服矣，事无可疑矣，此唯师心自用耳。夫自用，其小者也；自知其陋而谨护其失，宁使学终不进，不欲虚以下人，此为害于心术者大，而蹈之者常十之八九。\n\n　　不然，则所问非所学焉：询天下之异文鄙事以快言论；甚且心之所已明者，问之人以试其能，事之至难解者，问之人以穷其短。而非是者，虽有切于身心性命之事，可以收取善之益，求一屈己焉而不可得也。嗟乎！学之所以不能几(jī)于古者，非此之由乎？\n\n　　且夫不好问者，由心不能虚也；心之不虚，由好学之不诚也。亦非不潜心专力之敌，其学非古人之学，其好亦非古人之好也，不能问宜也。\n\n　　智者千虑，必有一失。圣人所不知，未必不为愚人之所知也；愚人之所能，未必非圣人之所不能也。理无专在，而学无止境也，然则问可少耶？《周礼》，外朝以询万民，国之政事尚问及庶人，是故贵可以问贱，贤可以问不肖，而老可以问幼，唯道之所成而已矣。\n\n　　孔文子不耻下问，夫子贤之。古人以问为美德，而并不见其有可耻也，后之君子反争以问为耻，然则古人所深耻者，后世且行之而不以为耻者多矣，悲夫！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '问说' AND p.poem_author = '刘开';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('悲愤诗', '蔡琰', '两汉', '汉季失权柄，董卓乱天常。志欲图篡弑，先害诸贤良。逼迫迁旧邦，拥主以自疆。\n海内兴义师，欲共讨不祥。卓众来东下，金甲耀日光。平土人脆弱，来兵皆胡羌。\n猎野围城邑，所向悉破亡。斩截无孑遗，尸骸相撑拒。马边悬男头，马后载妇女。\n长驱西入关，迥路险且阻。还顾邈冥冥，肝脾为烂腐。所略有万计，不得令屯聚。\n或有骨肉俱，欲言不敢语。失意机徵间，辄言毙降虏。要当以亭刃，我曹不活汝。\n岂复惜性命，不堪其詈骂。或便加棰杖，毒痛参并下。旦则号泣行，夜则悲吟坐。\n欲死不能得，欲生无一可。彼苍者何辜，乃遭此厄祸。边荒与华异，人俗少义理。\n处所多霜雪，胡风春夏起。翩翩吹我衣，肃肃入我耳。感时念父母，哀叹无穷已。\n有客从外来，闻之常欢喜。迎问其消息，辄复非乡里。邂逅徼时愿，骨肉来迎己。\n己得自解免，当复弃儿子。天属缀人心，念别无会期。存亡永乖隔，不忍与之辞。\n儿前抱我颈，问母欲何之。人言母当去，岂复有还时。阿母常仁恻，今何更不慈。\n我尚未成人，奈何不顾思。见此崩五内，恍惚生狂痴。号泣手抚摩，当发复回疑。\n兼有同时辈，相送告离别。慕我独得归，哀叫声摧裂。马为立踟蹰，车为不转辙。\n观者皆嘘唏，行路亦呜咽。去去割情恋，遄征日遐迈。悠悠三千里，何时复交会。\n念我出腹子，匈臆为摧败。既至家人尽，又复无中外。城廓为山林，庭宇生荆艾。\n白骨不知谁，纵横莫覆盖。出门无人声，豺狼号且吠。茕茕对孤景，怛咤糜肝肺。\n登高远眺望，魂神忽飞逝。奄若寿命尽，旁人相宽大。为复强视息，虽生何聊赖。\n托命于新人，竭心自勖励。流离成鄙贱，常恐复捐废。人生几何时，怀忧终年岁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '悲愤诗' AND p.poem_author = '蔡琰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清明日', '温庭筠', '唐代', '清娥画扇中，春树郁金红。出犯繁花露，归穿弱柳风。 \n马骄偏避幰，鸡骇乍开笼。柘弹何人发，黄鹂隔故宫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清明日' AND p.poem_author = '温庭筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小雅·鹤鸣', '佚名', '先秦', '鹤鸣于九皋，声闻于野。鱼潜在渊，或在于渚。乐彼之园，爰有树檀，其下维萚。它山之石，可以为错。\n鹤鸣于九皋，声闻于天。鱼在于渚，或潜在渊。乐彼之园，爰有树檀，其下维榖。它山之石，可以攻玉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小雅·鹤鸣' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('外科医生', '江盈科', '明代', '有医者， 自称善外科。一裨将阵回，中流矢，深入膜，延使治。乃持并州剪，剪去矢官，跪而请酬。裨将曰：“镞在膜内须亟治。”医曰：“此内科之事，不意并责我。”裨将曰：“呜呼，世直有如是欺诈之徒。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '外科医生' AND p.poem_author = '江盈科';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜算子·十载仰高明', '赵长卿', '宋代', '十载仰高明，一见心相许。来日孤舟西水门，风饱征帆腹。 \n后夜起相思，明月清江曲。若见秋风寒雁来，能寄音书否。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜算子·十载仰高明' AND p.poem_author = '赵长卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凉州馆中与诸判官夜集', '岑参', '唐代', '弯弯月出挂城头，城头月出照凉州。\n凉州七里十万家，胡人半解弹琵琶。\n琵琶一曲肠堪断，风萧萧兮夜漫漫。\n河西幕中多故人，故人别来三五春。\n花门楼前见秋草，岂能贫贱相看老。\n一生大笑能几回，斗酒相逢须醉倒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凉州馆中与诸判官夜集' AND p.poem_author = '岑参';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凉州词三首·其三', '张籍', '唐代', '凤林关里水东流，白草黄榆六十秋。\n边将皆承主恩泽，无人解道取凉州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凉州词三首·其三' AND p.poem_author = '张籍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('守岁', '苏轼', '宋代', '欲知垂尽岁，有似赴壑蛇。\n修鳞半已没，去意谁能遮。\n况欲系其尾，虽勤知奈何。\n儿童强不睡，相守夜欢哗。\n晨鸡且勿唱，更鼓畏添挝。\n坐久灯烬落，起看北斗斜。\n明年岂无年，心事恐蹉跎。\n努力尽今夕，少年犹可夸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '守岁' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头·隐括杜牧之齐山诗', '朱熹', '宋代', '江水浸云影，鸿雁欲南飞。携壶结客何处？空翠渺烟霏。尘世难逢一笑，况有紫萸黄菊，堪插满头归。风景今朝是，身世昔人非。\n酬佳节，须酩酊，莫相违。人生如寄，何事辛苦怨斜晖。无尽今来古往，多少春花秋月，那更有危机。与问牛山客，何必独沾衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头·隐括杜牧之齐山诗' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐·金风细细', '晏殊', '宋代', '金风细细。叶叶梧桐坠。绿酒初尝人易醉。一枕小窗浓睡。 \n紫薇朱槿花残。斜阳却照阑干。双燕欲归时节，银屏昨夜微寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐·金风细细' AND p.poem_author = '晏殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三都赋', '左思', '魏晋', '总序\n　　盖诗有六义焉，其二曰赋。杨雄曰：“诗人之赋丽以则。”班固曰：“赋者，古诗之流也。”。先王采焉，以观土风。见“绿竹猗猗”于宜，则知卫地淇澳之产；见“在其版屋”，则知秦野西戎之宅。故能居然而辨八方。\n　　然相如赋上林而引“卢橘夏熟”，杨雄赋甘泉而陈“玉树青葱”，班固赋西都而叹以出比目，张衡赋西京而述以游海若。假称珍怪，以为润色，若斯之类，匪啻于兹。考之果木，则生非其壤；校之神物，则出非其所。于辞则易为藻饰，于义则虚而无徵。且夫玉卮无当，虽宝非用；侈言无验，虽丽非经。而论者莫不诋讦其研精，作者大氐举为宪章。积习生常，有自来矣。\n　　余既思摹二京而赋三都，其山川城邑则稽之地图，其鸟兽草木则验之方志。风谣歌舞，各附其俗；魁梧长者，莫非其旧。何则？发言为诗者，咏其所志也；美物者贵依其本，赞事者宜本其实。匪本匪实，览者奚信？且夫任土作贡，虞书所著；辩物居方，周易所慎。聊举其一隅，摄其体统，归诸诂训焉。\n\n魏都赋\n　　魏国先生有睟其容，乃盱衡而诰曰：“异乎交益之士，盖音有楚夏者，土风之乖也；情有险易者，习俗之殊也。虽则生常，固非自得之谓也。昔市南宜僚弄丸，而两家之难解。聊为吾子复玩德音，以释二客竞于辩囿者也。 \n　　夫泰极剖判，造化权舆。体兼昼夜，理包清浊。流而为江海，结而为山岳。列宿分其野，荒裔带其隅。岩冈潭渊，限蛮隔夷，峻危之窍也。蛮陬夷落，译导而通，鸟兽之氓也。正位居体者，以中夏为喉，不以边垂为襟也。长世字甿者，以道德为藩，不以袭险为屏也。而子大夫之贤者，尚弗曾庶翼等威，附丽皇极。思禀正朔，乐率贡职。而徒务於诡随匪人，宴安於绝域。荣其文身，骄其险棘。缪默语之常伦，牵胶言而逾侈。饰华离以矜然，假倔彊而攘臂。非醇粹之方壮，谋踳驳於王义。孰愈寻靡{艹汧}於中逵，造沐猴於棘刺。剑阁虽嶚(嶚 一作：险)，凭之者蹶，非所以深根固蒂也。洞庭虽濬，负之者北，非所以爱人治国也。彼桑榆之末光，逾长庚之初辉。况河冀之爽垲，与江介之湫湄。故将语子以神州之略，赤县之畿。魏都之卓荦，六合之枢机。 \n　　于时运距阳九，汉网绝维。奸回内赑，兵缠紫微。翼翼京室，眈眈帝宇，巢焚原燎，变为煨烬，故荆棘旅庭也。殷殷寰内，绳绳八区，锋镝纵横，化为战场，故麋鹿寓城也。伊洛榛旷，崤函荒芜。临菑牢落，鄢郢丘墟。而是有魏开国之日，缔构之初。万邑譬焉，亦独焠麋之与子都。培塿之与方壶也。 \n　　且魏地者，毕昴之所应，虞夏之馀人。先王之桑梓，列圣之遗尘。考之四隈，则八埏之中；测之寒暑，则霜露所均。卜偃前识而赏其隆，吴札听歌而美其风。虽则衰世，而盛德形於管弦；虽逾千祀，而怀旧蕴於遐年。尔其疆域，则旁极齐秦，结凑冀道。开胸殷卫，跨蹑燕赵。山林幽岟，川泽回缭。恒碣碪?於青霄，河汾浩涆而皓溔。南瞻淇澳，则绿竹纯茂；北临漳滏，则冬夏异沼。神钲迢递於高峦，灵响时惊於四表。温泉毖涌而自浪，华清荡邪而难老。墨井盐池，玄滋素液。厥田惟中，厥壤惟白。原隰畇畇，坟衍斥斥。或嵬罍而衤复陆，或黋朗而拓落。乾坤交泰而絪缊，嘉祥徽显而豫作。是以兆朕振古，萌柢畴昔。藏气谶纬，閟象竹帛。迥时世而渊默，应期运而光赫。暨圣武之龙飞，肇受命而光宅。 \n　　爰初自臻，言占其良。谋龟谋筮，亦既允臧。修其郛郭，缮其城隍。经始之制，牢笼百田。画雍豫之居，写八都之宇。鉴茅茨於陶唐，察卑宫於夏禹。古公草创，而高门有闶；宣王中兴，而筑室百堵。兼圣哲之轨，并文质之状。商丰约而折中，准当年而为量。思重爻，摹大壮。览荀卿，采萧相。拱木於林衡，授全模於梓匠。遐迩悦豫而子来，工徒拟议而骋巧。阐钩绳之筌绪，承二分之正要。揆日晷，考星耀。建社稷，作清庙。筑曾宫以回匝，比冈隒而无陂。造文昌之广殿，极栋宇之弘规。崶若崇山嚬起以崔嵬，髧若玄云舒蜺以高垂。瑰材巨世，参差。枌橑衤复结，栾栌叠施。丹梁虹申以并亘，朱桷森布而支离。绮井列疏以悬蒂，华莲重葩而倒披。齐龙首而涌霤，时梗概於滮池。旅楹闲列，晖鉴抰振。榱题黮&lt;黑逮&gt;，阶盾嶙峋。长庭砥平，锺虡夹陈。风无纤埃，雨无微津。岩岩北阙，南端逌遵。竦峭双碣，方驾比轮。西辟延秋，东启长春。用觐群后，观享颐宾。 \n　　左则中朝有赩，听政作寝。匪朴匪，去泰去甚。木无雕锼，土无绨锦。玄化所甄，国风所禀。於前则宣明显阳，顺德崇礼。重闱洞出，锵锵济济。珍树猗猗，奇卉萋萋。蕙风如薰，甘露如醴。禁台省中，连闼对廊。直事所繇，典刑所藏。蔼蔼列侍，金蜩齐光。诘朝陪幄，纳言有章。亚以柱後，执法内侍。符节谒者，典玺储吏。膳夫有官，药剂有司。肴醳顺时，腠理则治。於後则椒鹤文石，永巷壸术。楸梓木兰，次舍甲乙。西南其户，成之匪日。丹青焕炳，特有温室。仪形宇宙，历像贤圣。图以百瑞，綷以藻咏。芒芒终古，此焉则镜。有虞作绘，兹亦等竞。 \n　　右则疏圃曲池，下畹高堂。兰渚莓莓，石濑汤汤。弱葼系实，轻叶振芳。奔龟跃鱼，有祭吕梁。驰道周屈於果下，延阁胤宇以经营。飞陛方辇而径西，三台列峙以峥嵘。亢阳台於阴基，拟华山之削成。上累栋而重霤，下冰室而沍冥。周轩中天，丹墀临猋。增构瓘瓘，清尘彯彯。云雀踶甍而矫首，壮翼摛镂於青霄。雷雨窈冥而未半，皦日笼光於绮寮。习步顿以升降，御春服而逍遥。八极可围於寸眸，万物可齐於一朝。长涂牟首，豪徼互经。晷漏肃唱，明宵有程。附以兰锜，宿以禁兵。司卫闲邪，钩陈罔惊。於是崇墉濬洫，婴堞带涘。四门，隆厦重起。凭太清以混成，越埃壒而资始。藐藐标危，亭亭峻趾。临焦原而不怳，谁劲捷而无犭思？与冈岑而永固，非有期乎世祀。阳灵停曜於其表，阴祇蒙雾於其里。菀以玄武，陪以幽林。缭垣开囿，观宇相临。硕果灌丛，围木竦寻。篁筱怀风，蒲陶结阴。回渊漼，积水深。蒹葭，雚蒻森。丹藕凌波而的皪，绿芰泛涛而浸潭。羽翮颉颃，鳞介浮沈。栖者择木，雊者择音。若咆渤澥与姑馀，常鸣鹤而在阴。表清籞，勒虞箴。思国恤，忘从禽。樵苏往而无忌，即鹿纵而匪禁。腜腜坰野，奕奕菑亩。甘荼伊蠢，芒种斯阜。西门溉其前，史起灌其後。墱流十二，同源异口。畜为屯云，泄为行雨。水澍粳稌，陆莳稷黍。黝黝桑柘，油油麻纻。均田画畴，蕃庐错列姜芋充茂，桃李荫翳家安其所，而服美自悦。邑屋相望，而隔逾奕世。 \n　　内则街冲辐辏，朱阙结隅。石杠飞梁，出控漳渠。疏通沟以滨路，罗青槐以荫涂。比沧浪而可濯，方步朓而有逾。习习冠盖，莘莘蒸徒。斑白不提，行旅让衢。设官分职，营处署居。夹之以府寺，班之以里闾。其府寺则位副三事，官逾六卿。奉常之号，大理之名。厦屋一揆，华屏齐荣。肃肃阶，重门再扃。师尹爰止。毗代作桢。其闾阎则长寿吉阳，永平思忠。亦有戚里，寘宫之东。闬出长者，巷苞诸公。都护之堂，殿居绮窗。舆骑朝猥，蹀危攵其中。营客馆以周坊，&lt;食芳&gt;宾侣之所集。玮丰楼之闬闳，起建安而首立。葺墙幂室，房庑杂袭。剞劂罔掇，匠积习。广成之传无以畴，街之邸不能及。廓三市而开廛，籍平逵而九达。班列肆以兼罗，设阛阓以襟带。济有无之常偏，距日中而毕会。抗旗亭之峣薛，侈所&lt;兆见&gt;之博大。百隧毂击，连轸万贯，凭轼捶马，袖幕纷半。壹八方而混同，极风采之异观。质剂平而交易，刀布贸而无算。财以工化，贿以商通。难得之货，此则弗容。器周用而长务，物背窳而就攻。不鬻邪而豫贾，著驯风之醇醲。白藏之藏，富有无堤。同赈大内，控引世资，賨幏积墆，琛币充牣。关石之所和钧，财赋之所厎慎。燕弧盈库而委劲，冀马填厩而驵骏。 \n　　至乎勍敌纠纷，庶土罔宁。圣武兴言，将曜威灵。介胄重袭，旍旗跃茎。弓珧解檠，矛鋋飘英。三属之甲，缦胡之缨。控弦简发，妙拟更嬴。齐被练而銛戈，袭偏裻以讠贵列。毕出征而中律，执奇正以四伐。硕画精通，目无匪制。推锋积纪，铓气弥锐。三接三捷，既昼亦月。克翦方命，吞灭咆烋。云撤叛换，席卷虔刘。祲威八纮，荒阻率由。洗兵海岛，刷马江洲。振旅甸甸，反旆悠悠。凯归同饮，疏爵普畴。朝无刓印，国无费留。 \n　　丧乱既弭而能宴，武人归兽而去战。萧斧戢柯以柙刃，虹旍摄麾以就卷。斟洪范，酌典宪。观所恒，通其变。上垂拱而司契，下缘督而自劝。道来斯贵，利往则贱。囹圄寂寥，京庾流衍。於时东鳀即序，西倾顺轨。荆南怀憓，朔北思韪。绵绵迥涂，骤山骤水。襁负赆贽，重译贡篚。髽首之豪，鐻耳之杰。服其荒服。敛衽魏阙。置酒文昌，高张宿设。其夜未遽，庭燎晢々。有客祁祁，载华载裔。岌岌冠縰，累累辫发。清酤如济，浊醪如河。冻醴流澌，温酎跃波。丰肴衍衍，行庖皤皤。愔愔醧宴，酣湑无哗延广乐，奏九成。冠韶夏，冒六茎。傮响起，疑震霆。天宇骇，地庐惊。亿若大帝之所兴作，二嬴之所曾聆。金石丝竹之恒韵，匏土革木之常调。干戚羽旄之饰好，清讴微吟之要妙。世业之所日用，耳目之所闻觉。杂糅纷错，兼该泛博。鞮鞻所掌之音，韎昧任禁之曲。以娱四夷之君，以睦八荒之俗。 \n　　既苗既狩，爰游爰豫。藉田以礼动，大阅以义举。备法驾，理秋御。显文武之壮观，迈梁驺之所著。林不槎枿，泽不伐夭。斧斨以时，罾以道。德连木理，仁挺芝草。皓兽为之育薮，丹鱼为之生沼。矞云翔龙，泽马亍阜。山图其石，川形其宝。莫黑匪乌，三趾而来仪。莫赤匪狐，九尾而自扰。嘉颖离合以汤汤，醴泉涌流而浩浩。显祯祥以曲成，固触物而兼造。盖亦明灵之所酬酢，休徵之所伟兆。 \n　　旼々率土，迁善罔匮。沐浴福应，宅心醰粹。馀粮栖亩而弗收，颂声载路而洋溢。河洛开奥，符命用出。翩翩黄鸟，衔书来讯人谋所尊，鬼谋所秩。刘宗委驭，巽其神器。闚玉策於金縢，案图於石室。考历数之所在，察五德之所莅。量寸旬，涓吉日。陟中坛，即帝位。改正朔，易服色。继绝世，脩废职。徽帜以变，器械以革。显仁翌明，藏用玄默。菲言厚行，陶化染学。雠校篆籀，篇章毕觌。优贤著於扬历，匪孽形於亲戚。本枝别干，蕃屏皇家。勇若任城，才若东阿。抗旍则威噞秋霜，摛翰则华纵春葩。英喆雄豪，佐命帝室。相兼二八，将猛四七。赫赫震震，开务有谧。故令斯民睹泰阶之平，可比屋而为一。 \n　　算祀有纪，天禄有终。传业禅祚，高谢万邦。皇恩绰矣，帝德冲矣。让其天下，臣至公矣。荣操行之独得，超百王之庸庸。追亘卷领与结绳，睠留重华而比踪。尊卢赫胥，羲农有熊。虽自以为道，洪化以为隆。世笃玄同，奚遽不能与之踵武而齐其风？是故料其建国，析其法度。谘其考室，议其举厝。复之而无斁，申之而有裕。非疏粝之士所能精，非鄙俚之言所能具。“至於山川之倬诡，物产之魁殊。或名奇而见称，或实异而可书。生生之所常厚，洵美之所不渝。其中则有鸳鸯交谷，虎涧龙山。掘鲤之淀，盖节之渊。嬛嬛精卫，衔木偿怨。常山平干，钜鹿河间。列真非一，往往出焉。昌容练色，犊配眉连。玄俗无影，木羽偶仙。琴高沈水而不濡，时乘赤鲤而周旋。师门使火以验术，故将去而林燔。易阳壮容，卫之稚质。邯郸鵕步，赵之鸣瑟。真定之梨，故安之栗。醇酎中山，流湎千日。淇洹之笋，信都之枣。雍丘之粱，清流之稻。锦绣襄邑，罗绮朝歌。绵纩房子，缣裛清河。若此之属，繁富夥够。可单究，是以抑而未罄也。盖比物以错辞，述清都之闲丽。虽选言以简章，徒九复而遗旨。览大易与春秋，判殊隐而一致。末上林之隤墙，本前脩以作系。 \n　　其军容弗犯，信其果毅。纠华绥戎，以戴公室。元勋配管敬之绩，歌锺析邦君之肆。则魏绛之贤有令闻也。闲居隘巷，室迩心遐。富仁宠义，职竞弗罗。千乘为之轼庐，诸侯为之止戈。则干木之德自解纷也。贵非吾尊，重士逾山。亲御监门，嗛嗛同轩。搦秦起赵。威振八蕃。则信陵之名若兰芬也。英辩荣枯，能济其厄。位加将相，窒隙之策。四海齐锋，一口所敌，张仪、张禄亦足云也。 \n　　搉惟庸蜀与鸲鹊同窠，句吴与黾同穴。一自以为禽鸟，一自以为鱼鳖。山阜猥积而踦　区，泉流迸集而咉咽。隰壤瀸漏而沮洳，林薮石留而芜秽。穷岫泄云，日月恒翳。宅土熇暑，封疆障疠。蔡莽螫剌，昆虫毒噬。汉罪流御，秦馀徙&lt;列巾&gt;。宵貌蕞陋，禀质脆。巷无杼首，里罕耆耋。或魋髻而左言，或镂肤而钻发。或明发而嬥歌，或浮泳而卒岁。风俗以果为婳，人物以戕害为艺。威仪所不摄，宪章所不缀。由重山之束厄，因长川之裾势。距远关以闚，时高樔而陛制。薄戍绵幂，无异蛛蝥之网；弱卒琐甲，无异螳螂之卫。 \n　　与先世而常然，虽信险而剿绝。揆既往之前迹，即将来之後辙。成都迄已倾覆，建邺则亦颠沛。顾非累卵於叠釭，焉至观形而怀怛！权假日以馀荣，比朝华而菴蔼。览麦秀与黍离，可作谣於吴会。” \n　　先生之言未卒，吴蜀二客，矍焉相顾，倏焉失所。有靦瞢容，神形茹。气离坐，倏墨而谢。曰：“仆党清狂，怵迫闽濮。习蓼虫之忘辛，玩进退之惟谷。非常寐而无觉，不睹皇舆之轨躅。过以亻凡剽之单慧，历执古之醇听。兼重以崒缪，偭辰光而罔定。先生玄识，深颂靡测。得闻上德之至盛，匪同忧於有圣。抑若春霆发响，而惊蛰飞竞。潜龙浮景，而幽泉高镜。虽星有风雨之好，人有异同之性。庶觌蔀家与剥庐，非苏世而居正。且夫寒谷丰黍，吹律暖之也。昬情爽曙，箴规显之也。虽明珠兼寸，尺璧有盈。曜车二六，三倾五城，未若申锡典章之为远也。”亮曰：“日不双丽，世不两帝。天经地纬，理有大归。安得齐给守其小辩也。”\n\n\n\n吴都赋\n　　东吴王孙冁然而咍，曰：“夫上图景宿，辨於天文者也。下料物土，析於地理者也。古先帝代，曾览八纮之洪绪。一六合而光宅，翔集遐宇。鸟策篆素，玉牒石记。乌闻梁岷有陟方之馆、行宫之基欤？而吾子言蜀都之富，禺同之有。玮其区域，美其林薮。矜巴汉之阻，则以为袭险之右。徇蹲鸱之沃，则以为世济阳九。龌龊而算，顾亦曲士之所叹也。旁魄而论都，抑非大人之壮观也。何则？土壤不足以摄生，山川不足以周卫。公孙国之而破，诸葛家之而灭。兹乃丧乱之丘墟，颠覆之轨辙。安可以俪王公而著风烈也？玩其碛砾而不窥玉渊者，未知骊龙之所蟠也。习其弊邑而不睹上邦者，未知英雄之所躔也。 \n　　“子独未闻大吴之巨丽乎？且有吴之开国也，造自太伯，宣於延陵。盖端委之所彰，高节之所兴。建至德以创洪业，世无得而显称。由克让以立风俗，轻脱鵕於千乘。若率土而论都，则非列国之所觖望也。故其经略，上当星纪。拓土画疆，卓荦兼并。包括干越，跨蹑蛮荆。婺女寄其曜，翼轸寓其精。指衡岳以镇野，目龙川而带坰。 \n　　“尔其山泽，则嵬嶷峣屼，?婴冥郁岪。溃渱泮汗，滇氵眄淼漫。或涌川而开渎，或吞江而纳汉。磈々，滮々涆々。?钦碒乎数州之间，灌注乎天下之半。百川派别，归海而会。控清引浊，混涛并濑。濆薄沸腾，寂寥长迈。濞焉汹汹，隐焉潏潏。出乎大荒之中，行乎东极之外。经扶桑之中林，包汤谷之滂沛。潮波汨起，回复万里。歊雾漨浡，云蒸昏昧。泓澄?#91;，澒溶沆漾。莫测其深，莫究其广。澶湉漠而无涯，牜怱有流而为长。朅异之所丛育，鳞甲之所集往。 \n　　“於是乎长鲸吞航，修鲵吐浪。跃龙腾蛇，鲛鲻琵琶。王鲔鯸鲐，鮣龟鱕?昔。乌贼拥剑，鼊鲭鳄。涵泳乎其中。葺鳞镂甲，诡类舛错。溯洄顺流，噞喁沈浮。鸟则鹍鸡鸀鳿<a>\\\\\\</a>，鹴鹄鹭鸿。鶢鶋避风，候雁造江。鸂敕?鷛渠?，　鹤鹙鸧。鹳鸥鹢鸬，氾滥乎其上。湛淡羽仪，随波参差。理翮整翰，容与自玩。雕啄蔓藻，刷荡漪澜。鱼鸟聱耴，万物蠢生。芒芒黖々，慌罔奄欻，神化翕忽，函幽育明。穷性极形，盈虚自然。蚌蛤珠胎，与月亏全。巨鳌赑屃，首冠灵山。大鹏缤翻，翼若垂天。振荡汪流，雷抃重渊。殷动宇宙，胡可胜原！ \n　　“岛屿绵邈，洲渚冯隆。旷瞻迢递，迥眺冥蒙。珍怪丽，奇隙充。径路绝，风云通。洪桃屈盘，丹桂灌丛。琼枝抗茎而敷蕊，珊瑚幽茂而玲珑。增冈重阻，列真之宇。玉堂对溜，石室相距。蔼蔼翠幄，?弱?弱素女。江斐於是往来，海童於是宴语。斯实神妙之响象，嗟难得而覙缕！ \n　　“尔乃地势坱圠，卉木镺蔓。遭薮为圃，值林为苑。异荂蓲，夏晔冬蒨。方志所辨，中州所羡。草则藿蒳豆蔻，姜汇非一。江蓠之属，海苔之类。纶组紫绛，食葛香茅。石帆水松，东风扶留。布濩皋泽，蝉联陵丘。夤缘山岳之岊，幂历江海之流。扤白蒂，衔朱蕤。郁兮?茂，晔兮菲菲。光色炫晃，芬馥肸蚃。职贡纳其包匦，离骚咏其宿莽。木则枫柙櫲樟，栟榈枸桹。绵杬杶栌，文欀桢橿。平仲桾櫏，松梓古度。楠榴之木，相思之树。宗生高冈，族茂幽阜。擢本千寻，垂荫万亩。攒柯挐茎，重葩殗叶。轮囷蚪蟠，鳞接。荣色杂糅，绸缪缛绣。宵露霮感，旭日晻孛。与风飖飏，&lt;风幼&gt;浏飕飗。鸣条律畅，飞音响亮。盖象琴筑并奏，笙竽俱唱。其上则猿父哀吟，犭军子长啸。狖鼯猓然，腾趠飞超。争接县垂，竞游远枝。惊透沸乱，牢落翚散。其下则有枭羊麡狼，猰?犭区象。乌菟之族，犀兕之党。钩爪锯牙，自成锋颖。精若燿星，声若云霆。名载於山经，形镂於夏鼎。 \n　　“其竹则筼筜箖箊，桂箭射筒。柚梧有篁，篻簩有丛。苞笋抽节，往往萦结。绿叶翠茎，冒霜停雪。橚矗森萃，蓊茸萧瑟。檀栾蝉蜎，玉润碧鲜。梢云无以逾，嶰谷弗能连。鸑鷟食其实，鹓雏扰其间。其果则丹橘馀甘，荔枝之林。槟榔无柯，椰叶无阴。龙眼橄榄，榴御霜。结根比景之阴，列挺衡山之阳。素华斐，丹秀芳。临青壁，系紫房。鹧鸪南翥而中留，孔雀綷羽以翱翔。山鸡归飞而来栖，翡翠列巢以重行。其琛赂则琨瑶之阜，铜锴之垠。火齐之宝，骇鸡之珍。赪丹明玑，金华银朴。紫贝流黄，缥碧素玉。隐赈崴，杂插幽屏。精曜潜颖，硩陊山谷。碕岸为之不枯，林木为之润黩。隋侯於是鄙其夜光，宋王於是陋其结绿。“其荒陬谲诡，则有龙穴内蒸，云雨所储。陵鲤若兽，浮石若桴。双则比目，片则王馀。穷陆饮木，极沈水居。泉室潜织而卷绡，渊客慷慨而泣珠。开北户以向日，齐南冥於幽都。其四野，则畛畷无数，膏腴兼倍。原隰殊品，窊隆异等。象耕鸟耘，此之自与。穱秀菰穗，於是乎在。煮海为盐，采山铸钱。国税再熟之稻，乡贡八蚕之绵。 \n　　“徒观其郊隧之内奥，都邑之纲纪。霸王之所根柢，开国之所基趾。郛郭周匝，重城结隅。通门二八，水道陆衢。所以经始，用累千祀。宪紫宫以营室，廓广庭之漫漫。寒暑隔阂於邃宇，虹霓回带於云馆。所以跨跱焕炳万里也。造姑苏之高台，临四远而特建，带朝夕之浚池，佩长洲之茂苑。窥东山之府，则环宝溢目；海陵之仓，则红粟流衍。起寝庙於武昌，作离宫於建业。阐阖闾之所营，采夫差之遗法。抗神龙之华殿，施荣楯而捷猎。崇临海之崔巍，饰赤乌之韡晔。东西胶葛，南北峥嵘。房栊对櫎，连阁相经。阍闼谲诡，异出奇名。左称弯碕，右号临硎。雕栾镂楶，青琐丹楹。图以云气，画以仙灵。虽兹宅之夸丽，曾未足以少宁。思比屋於倾宫，毕结瑶而构琼。高闱有闶，洞门方轨。朱阙双立，驰道如砥。树以青槐，亘以绿水。玄荫眈眈，清流亹亹。列寺七里，侠栋阳路。屯营栉比，解署釭布。横塘查下，邑屋隆夸。长干延属，飞甍舛互。 \n　　“其居则高门鼎贵，魁岸豪杰。虞魏之昆，顾陆之裔。歧嶷继体，老成弈世。跃马叠迹，朱轮累辙。陈兵而归，兰锜内设。冠盖云荫，闾阎阗噎。其邻则有任侠之靡，轻訬之客。缔交翩翩，亻宝从弈弈。出蹑珠履，动以千百。里宴巷饮，飞觞举白。翘关扛鼎。拚射壶博。鄱阳暴谑，中酒而作。 \n　　“於是乐只衎而欢饫无匮，都辇殷而四奥来暨。水浮陆行，方舟结驷。唱棹转毂，昧旦永日。开市朝而并纳，横阛阓而流溢。混品物而同廛，并都鄙而为一。士女伫眙，商贾骈{比土}。纻衣絺服，杂沓傱萃。轻舆按辔以经隧，楼船举颿而过肆。果布辐凑而常然，致远流离与珂。纟集贿纷纭，器用万端。金镒磊砢，珠琲阑干。桃笙象簟，韬於筒中；蕉葛升越，弱於罗纨。泶犭翏，交贸相竞。喧哗喤呷，芬葩荫映。挥袖风飘而红尘昼昬；流汗霡霂而中逵泥泞。 “富中之甿，货殖之选。乘时射利，财丰巨万。竞其区宇，则并疆兼巷；矜其宴居，则珠服玉馔。趫材悍壮，此焉比庐。捷若庆忌，勇若专诸。危冠而出，竦剑而趋。扈带鲛函，扶揄属镂藏鍦於人，去&lt;盾戈&gt;自闾。家有鹤膝，户有犀渠。军容蓄用，器械兼储。吴钩越棘，纯钧湛卢。戎车盈於石城，戈船掩乎江湖。 \n　　“露往霜来，日月其除。草木节解，鸟兽腯肤。观鹰隼，诫征夫。坐组甲，建祀姑。命官帅而拥铎，将校猎乎具区。乌浒狼荒，夫南西屠。儋耳黑齿之酋，金邻象郡之渠。戊矞，靸霅警捷，先驱前涂。俞骑骋路，指南司方。出车槛槛，被练锵锵。吴王乃巾玉辂，轺骕骦。旗鱼须，常重光。摄乌号，佩干将。羽旄扬蕤，雄戟耀芒。贝胄象弭，织文鸟章。六军袀服，四骐龙骧。峭格周施，罿罻普张。罼鶒琐结，罠氾连纲。阹以九疑，御以沅湘。輶轩蓼扰，彀骑炜煌。袒裼徒搏，拔距投石之部。猿臂骿胁，狂趭犷猤。鹰瞵鹗视，じす翊。若离若合者，相与腾跃乎莽　之野。干卤殳鋋，旸夷勃卢之旅。长&lt;矛殳&gt;短兵，直发驰骋。儇佻坌并，衔枚无声。悠悠旆旌者，相与聊浪乎昧莫之坰。钲鼓叠山，火烈熛林。飞爓浮烟，载霞载阴。菈擸雷硠，崩峦弛岑。鸟不择木，兽不择音。&lt;虎武&gt;甝，&lt;系页&gt;麋麖。蓦六驳，追飞生。弹鸶鶁，射猱犭廷。白雉落，黑鸩零。陵绝???嶕，聿越巉险。跇逾竹柏，猭杞柟。封豨，神螭掩。刚镞润，霜刃染。 \n　　“於是弭节顿辔，齐镳驻跸。徘徊倘佯，寓目幽蔚。览将帅之拳勇，与士卒之抑扬。羽族以觜距为刀铍，毛群以齿角为矛铗，皆体著而应卒。所以挂扢而为创痏，冲踤而断筋骨。莫不衄锐挫芒，拉捭摧藏。虽有石林之岝崿，请攘臂而靡之；虽有雄虺之九首，将抗足而跐之。颠覆巢居，剖破窟宅。仰攀鵕鸃，俯蹴豺敠。刦剞熊罴之室，剽掠虎豹之落。猩猩啼而就禽，笑而被格。屠巴蛇，出象骼。斩鹏翼，掩广泽。轻禽狡兽，周章夷犹。狼跋乎中，忘其所以睒睗，失其所以去就。魂褫气慑而自踢　伏者，应弦饮羽，形偾景僵者，累积而增益，杂袭错缪。倾薮薄，倒岬岫。岩穴无豜豵，翳荟无{鹿需}鹨。思假道於丰隆，披重霄而高狩。笼乌兔於日月，穷飞走之栖宿。“嶰涧閴，冈岵童。罾罘满，效获众。回靶乎行邪，睨观鱼乎三江。泛舟航於彭蠡，浑万艘而既同。弘舸连舳，巨槛接舻。飞云盖海，制非常模。叠华楼而岛跱，时仿於方壶。比鹢首而有裕，迈馀皇於往初。张组帏，构流苏。开轩幌，镜水区。槁工楫师，选自闽禺。习御长风，狎玩灵胥。责千里於寸阴，聊先期而须臾。棹讴唱，箫籁鸣。洪流响，渚禽惊。弋磻放，稽鹪明?。虞机发，留　。钩铒纵横，网罟接绪。术兼詹公，巧倾任父。筌?亘亸，鲡鲿魦。罩两魪，罺鰝虾。乘鲎鼋鼍，同罛共罗。沈虎潜鹿，馽龓僒束。鲸辈中於群犗，搀抢暴出而相属。虽复鲤，无临河而钓异射鲋於井谷。 “结轻舟而竞逐，迎潮水而振缗。想萍实之复形，访灵夔於鲛人。精卫衔石而遇缴，文鳐夜飞而触纶。北山亡其翔翼，西海失其游鳞。雕题之士，镂身之卒。比饰虬龙，蛟螭与对。简其华质，则费锦缋。料其虓勇，则雕悍狼戾。相与昧潜险，搜环奇。摸蝳蝐，扪觜?隽。剖巨蚌於回渊，濯明月於涟漪。 \n　　“毕天下之至异，讫无索而不臻。溪壑为之一罄，川渎为之中贫。哂澹台之见谋，聊袭海而徇珍。载汉女於后舟，追晋贾而同尘。汨乘流以砰宕，翼飔风之&lt;风刘&gt;々。直冲涛而上濑，常沛沛以悠悠。汔可休而凯归，揖天吴与阳侯。指包山而为期，集洞庭而淹留。数军实乎桂林之苑，飨戎旅乎落星之楼。置酒若淮泗，积肴若山丘。飞轻轩而酌绿酃，方双辔而赋珍羞。饮烽起，釂鼓震。士遗倦，众怀欣。幸乎馆娃之宫，张女乐而娱群臣。罗金石与丝竹，若钧天之下陈。登东歌，操南音。胤阳阿，咏韎任。荆艳楚舞，吴愉越吟。翕习容裔，靡靡愔愔。 \n　　“若此者，与夫唱和之隆响，动锺鼓之铿耾。有殷坻颓於前，曲度难胜。皆与谣俗汁协，律吕相应。其奏乐也，则木石润色；其吐哀也，则凄风暴兴。或超延露而驾辩，或逾绿水而采菱。军马弭髦而仰秣，渊鱼竦鳞而上升。酣湑半，八音并。欢情留，良辰征。鲁阳挥戈而高麾，回曜灵於太清。将转西日而再中，齐既往之精诚。 \n　　“昔者夏后氏朝群臣於兹土，而执玉帛者以万国。盖亦先生之所高会，而四方之所轨则。春秋之际，要盟之主。阖闾信其威，夫差穷其武。内果伍员之谋，外骋孙子之奇。胜强楚於柏举，栖劲越於会稽。阙沟乎商鲁，争长於黄池。徒以江湖嶮陂，物产殷充。绕溜未足言其固，郑白未足语其丰。士有陷坚之锐，俗有节概之风。睚眦则挺剑，喑呜则弯弓。拥之者龙腾，据之者虎视。麾城若振槁，搴旗若顾指。虽带甲一朝，而元功远致。虽累叶百叠，而富强相继。乐湑衎其方域，列仙集其土地。桂父练形而易色，赤须蝉蜕而附丽。中夏比焉，毕世而罕见，丹青图其珍玮，贵其宝利也。舜禹游焉，没齿而忘归，精灵留其山阿，玩其奇丽也。剖判庶士，商搉万俗。国有郁鞅而显敞，邦有湫厄而踡跼。伊兹都之函弘，倾神州而韫椟。仰南斗以斟酌，兼二仪之优渥。 \n　　“繇此而揆之，西蜀之於东吴，小大之相绝也，亦犹棘林萤燿，而与夫木龙烛也。否泰之相背也，亦犹帝之悬解，而与桎梏疏属也。庸可共世而论巨细，同年而议丰确乎？暨其幽遐独邃，寥廓闲奥。耳目之所不该，足趾之所不蹈。倜傥之极异，誳诡之殊事，藏理於终古，而未寤於前觉也。若吾子之所传，孟浪之遗言，略举其梗概，而未得其要妙也。”\n\n\n\n蜀都赋\n　　有西蜀公子者，言于东吴王孙，曰：盖闻天以日月为纲，地以四海为纪。九土星分，万国错跱。崤函有帝皇之宅，河洛为王者之里。吾子岂亦曾闻蜀都之事欤？请为左右扬搉而陈之。 \n　　夫蜀都者，盖兆基于上世，开国于中古。廓灵关以为门，包玉垒而为宇。带二江之双流，抗峨眉之重阻。水陆所凑，兼六合而交会焉；丰蔚所盛，茂八区而庵蔼焉。 \n　　于前则跨蹑犍牂，枕倚交趾。经途所亘，五千余里。山阜相属，含溪怀谷。岗峦纠纷，触石吐云。郁葐蒕以翠微，崛巍巍以峨峨。干青霄而秀出，舒丹气而为霞。龙池瀑濆其隈，漏江伏流溃其阿。汩若汤谷之扬涛，沛若蒙汜之涌波。于是乎邛竹缘岭，菌桂临崖。旁挺龙目，侧生荔枝。布绿叶之萋萋，结朱实之离离。迎隆冬而不凋，常晔晔以猗猗。孔翠群翔，犀象竞驰。白雉朝雊，猩猩夜啼。金马骋光而绝景，碧鸡儵忽而曜仪。火井沈荧于幽泉，高爓飞煽于天垂。其间则有虎珀丹青，江珠瑕英。金沙银砾，符采彪炳，晖丽灼烁。 \n　　于后则却背华容，北指昆仑。缘以剑阁，阻以石门。流汉汤汤，惊浪雷奔。望之天回，即之云昏。水物殊品，鳞介异族。或藏蛟螭，或隐碧玉。嘉鱼出于丙穴，良木攒于褒谷。其树则有木兰梫桂，杞櫹椅桐，椶枒楔枞。楩柟幽蔼于谷底，松柏蓊郁于山峰。擢修干，竦长条。扇飞云，拂轻霄。羲和假道于峻歧，阳乌回翼乎高标。巢居栖翔，聿兼邓林。穴宅奇兽，窠宿异禽。熊罴咆其阳，雕鹗鴥其阴。猿狖腾希而竞捷，虎豹长啸而永吟。 \n　　于东则左绵巴中，百濮所充。外负铜梁于宕渠，内函要害于膏腴。其中则有巴菽巴戟，灵寿桃枝。樊以蒩圃，滨以盐池。蟞蛦山栖，鼋龟水处。潜龙蟠于沮泽，应鸣鼓而兴雨。丹沙赩炽出其阪，蜜房郁毓被其阜。山图采而得道，赤斧服而不朽。若乃刚悍生其方，风谣尚其武。奋之则賨旅，玩之则渝舞。锐气剽于中叶，蹻容世于乐府。 \n　　于西则右挟岷山，涌渎发川。陪以白狼，夷歌成章。坰野草昧，林麓黝儵。交让所植，蹲鸱所伏。百药灌丛，寒卉冬馥。异类众伙，于何不育？其中则有青珠黄环，碧砮芒消。或丰绿荑，或蕃丹椒。麋芜布濩于中阿，风连莚蔓于兰皋。红葩紫饰，柯叶渐苞。敷橤葳蕤，落英飘飖。神农是尝，卢跗是料。芳追气邪，味蠲疠痟。 \n　　其封域之内，则有原隰坟衍，通望弥博。演以潜沬，浸以绵雒。沟洫脉散，疆里绮错。黍稷油油，稻莫莫。指渠口以为云门，洒滮池而为陆泽。虽星毕之滂遝，尚未齐其膏液。 \n　　尔乃邑居隐赈，夹江傍山。栋宇相望，桑梓接连。家有盐泉之井，户有橘柚之园。其园则林檎枇杷，橙柿梬楟。榹桃函列，梅李罗生。百果甲宅，异色同荣。朱樱春熟，素柰夏成。若乃大火流，凉风厉。白露凝，微霜结。紫梨津润，樼栗罅发。蒲陶乱溃，若榴竞裂。甘至自零，芬芬酷烈。其园则有蒟蒻茱萸，瓜畴芋区。甘蔗辛姜，阳蓲阴敷。日往菲薇，月来扶疏。任土所丽，众献而储。 \n　　其沃瀛则有攒蒋丛蒲，绿菱红莲。杂以蕴藻，糅以苹蘩。总茎柅柅，裛叶蓁蓁。蕡实时味，王公羞焉。其中则有鸿俦鹄侣，振鹭鹈鹕。晨凫旦至，候雁衔芦。木落南翔，冰泮北徂。云飞水宿，哢吭清渠。其深则有白鼋命鳖，玄獭上祭。鳣鲔鳟鲂，鮷鳢鲨鲿。差鳞次色，锦质报章。跃涛戏濑，中流相忘。于是乎金城石郭，兼帀中区。既丽且崇，实号成都。辟二九之通门，画方轨之广涂。营新宫于爽垲，拟承明而起庐。结阳城之延阁，飞观榭乎云中。开高轩以临山，列绮窗而瞰江。内则议殿爵堂，武义虎威。宣化之闼，崇礼之闱。华阙双邈，重门洞开。金铺交映，玉题相晖。外则轨躅八达，里闬对出。比屋连甍，千庑万室。亦有甲第，当衢向术。坛宇显敞，高门纳驷。庭扣钟磬，堂抚琴瑟。匪葛匪姜，畴能是恤？ \n　　亚以少城，接乎其西。市廛所会，万商之渊。列隧百重，罗肆巨千。贿货山积，纤丽星繁。都人士女，袨服靓妆。贾贸墆鬻，舛错纵横。异物崛诡，奇于八方。布有橦华，麫有桄榔。邛杖传节于大夏之邑，蒟酱流味于番禺之乡。舆辇杂沓，冠带混并。累毂叠迹，叛衍相倾。喧哗鼎沸，则哤聒宇宙；嚣尘张天，则埃壒曜灵。阛阓之里，伎巧之家。百室离房，机杼相和。贝锦斐成，濯色江波。黄润比筒，籯金所过。 \n　　侈侈隆富，卓郑埒名。公擅山川，货殖私庭。藏镪巨万，鈲摫兼呈。亦以财雄，翕习边城。三蜀之豪，时来时往。养交都邑，结俦附党。剧谈戏论，扼腕抵掌。出则连骑，归从百两。若其旧俗，终冬始春。吉日良辰，置酒高堂，以御嘉宾。金罍中坐，肴烟四陈。觞以清醥，鲜以紫鳞。羽爵执竞，丝竹乃发。巴姬弹弦，汉女击节。起西音于促柱，歌江上之飉厉。纡长袖而屡舞，翩跹跹以裔裔。合樽促席，引满相罚。乐饮今夕，一醉累月。 \n　　若夫王孙之属，郤公之伦。从禽于外，巷无居人。并乘骥子，俱服鱼文。玄黄异校，结驷缤纷。西逾金堤，东越玉津。朔别期晦，匪日匪旬。蹴蹈蒙笼，涉寥廓。鹰犬倏眒，罻罗络幕。毛群陆离，羽族纷泊。翕响挥霍，中网林薄。屠麖麋，翦旄麈。带文蛇，跨雕虎。志未骋，时欲晚。追轻翼，赴绝远。出彭门之阙，驰九折之阪。经三峡之峥嵘，蹑五屼之蹇浐。戟食铁之兽，射噬毒之鹿。皛貙氓于葽草，弹言鸟于森木。拔象齿，戾犀角。鸟铩翮，兽废足。 \n　　殆而朅来相与，第如滇池，集于江洲。试水客，舣轻舟。娉江婓，与神游。罨翡翠，钓鰋鮋。下高鹄，出潜虬。吹洞箫，发棹讴。感鱘鱼，动阳侯。腾波沸涌，珠贝汜浮。若云汉含星，而光耀洪流。将飨獠者，张帟幕，会平原。酌清酤，割芳鲜。饮御酣，宾旅旋。车马雷骇，轰轰阗阗。若风流雨散，漫乎数百里间。斯盖宅土之所安乐，观听之所踊跃也。焉独三川，为世朝市？ \n　　若乃卓荦奇谲，倜傥罔已。一经神怪，一纬人理。远则岷山之精，上为井络。天帝运期而会昌，景福肸飨而兴作。碧出苌弘之血，鸟生杜宇之魄。妄变化而非常，羌见伟于畴昔。近则江汉炳灵，世载其英。蔚若相如，皭若君平。王褒韡晔而秀发，杨雄含章而挺生。幽思绚道德，摛藻掞天庭。考四海而为儁，当中叶而擅名。是故游谈者以为誉，造作者以为程也。至乎临谷为塞，因山为障。峻岨塍埒长城，豁险吞若巨防。一人守隘，万夫莫向。公孙跃马而称帝，刘宗下辇而自王。由此言之，天下孰尚？故虽兼诸夏之富有，犹未若兹都之无量也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三都赋' AND p.poem_author = '左思';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春雨', '徐凝', '唐代', '花时闷见联绵雨，云入人家水毁堤。 \n昨日春风源上路，可怜红锦枉抛泥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春雨' AND p.poem_author = '徐凝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋下荆门', '李白', '唐代', '霜落荆门江树空，布帆无恙挂秋风。\n此行不为鲈鱼鲙，自爱名山入剡中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋下荆门' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春江花月夜二首', '张子容', '唐代', '林花发岸口，气色动江新。\n此夜江中月，流光花上春。 \n分明石潭里，宜照浣纱人。\n\n交甫怜瑶珮，仙妃难重期。\n沉沉绿江晚，惆怅碧云姿。 \n初逢花上月，言是弄珠时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春江花月夜二首' AND p.poem_author = '张子容';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·邶风·凯风', '佚名', '先秦', '凯风自南，吹彼棘心。棘心夭夭，母氏劬劳。\n凯风自南，吹彼棘薪。母氏圣善，我无令人。\n爰有寒泉？在浚之下。有子七人，母氏劳苦。\n睍睆黄鸟，载好其音。有子七人，莫慰母心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·邶风·凯风' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂说一·龙说', '韩愈', '唐代', '龙嘘气成云，云固弗灵于龙也。然龙乘是气，茫洋穷乎玄间，薄日月，伏光景，感震电，神变化，水下土，汩陵谷，云亦灵怪矣哉!\n\n　　云，龙之所能使为灵也；若龙之灵，则非云之所能使为灵也。然龙弗得云，无以神其灵矣。失其所凭依，信不可欤 ！\n\n　　异哉！其所凭依，乃其所自为也。《易》曰：“云从龙。”既曰：龙，云从之矣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂说一·龙说' AND p.poem_author = '韩愈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋玩月', '佚名', '明代', '团团离海角，渐渐入云衢。\n此夜一轮满，清光何处无！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋玩月' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无题·油壁香车不再逢', '晏殊', '宋代', '油壁香车不再逢，峡云无迹任西东。\n梨花院落溶溶月，柳絮池塘淡淡风。\n几日寂寥伤酒后，一番萧索禁烟中。\n鱼书欲寄何由达，水远山长处处同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无题·油壁香车不再逢' AND p.poem_author = '晏殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花', '罗邺', '唐代', '繁如瑞雪压枝开，越岭吴溪免用栽。\n却是五侯家未识，春风不放过江来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花' AND p.poem_author = '罗邺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('莲花', '温庭筠', '唐代', '绿塘摇滟接星津，轧轧兰桡入白蘋。\n应为洛神波上袜，至今莲蕊有香尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '莲花' AND p.poem_author = '温庭筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水槛遣心二首', '杜甫', '唐代', '去郭轩楹敞，无村眺望赊。\n澄江平少岸，幽树晚多花。\n细雨鱼儿出，微风燕子斜。\n城中十万户，此地两三家。\n\n蜀天常夜雨，江槛已朝晴。\n叶润林塘密，衣干枕席清。\n不堪祗老病，何得尚浮名。\n浅把涓涓酒，深凭送此生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水槛遣心二首' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('太原早秋', '李白', '唐代', '岁落众芳歇，时当大火流。\n霜威出塞早，云色渡河秋。\n梦绕边城月，心飞故国楼。\n思归若汾水，无日不悠悠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '太原早秋' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渌水曲', '李白', '唐代', '渌水明秋月，南湖采白蘋。\n荷花娇欲语，愁杀荡舟人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渌水曲' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自题小像', '鲁迅', '近代', '灵台无计逃神矢，风雨如磐暗故园。\n寄意寒星荃不察，我以我血荐轩辕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自题小像' AND p.poem_author = '鲁迅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('芳心苦·杨柳回塘', '贺铸', '宋代', '杨柳回塘，鸳鸯别浦。绿萍涨断莲舟路。断无蜂蝶慕幽香，红衣脱尽芳心苦。 \n返照迎潮，行云带雨。依依似与骚人语。当年不肯嫁春风，无端却被秋风误。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '芳心苦·杨柳回塘' AND p.poem_author = '贺铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登柳州城楼寄漳汀封连四州', '柳宗元', '唐代', '城上高楼接大荒，海天愁思正茫茫。\n惊风乱飐芙蓉水，密雨斜侵薜荔墙。\n岭树重遮千里目，江流曲似九回肠。\n共来百越文身地，犹自音书滞一乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登柳州城楼寄漳汀封连四州' AND p.poem_author = '柳宗元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塞下曲六首', '李白', '唐代', '五月天山雪，无花只有寒。\n笛中闻折柳，春色未曾看。\n晓战随金鼓，宵眠抱玉鞍。\n愿将腰下剑，直为斩楼兰。\n\n天兵下北荒，胡马欲南饮。\n横戈从百战，直为衔恩甚。\n握雪海上餐，拂沙陇头寝。\n何当破月氏，然后方高枕。\n\n骏马似风飙，鸣鞭出渭桥。\n弯弓辞汉月，插羽破天骄。\n阵解星芒尽，营空海雾消。\n功成画麟阁，独有霍嫖姚。\n\n白马黄金塞，云砂绕梦思。\n那堪愁苦节，远忆边城儿。\n萤飞秋窗满，月度霜闺迟。\n摧残梧桐叶，萧飒沙棠枝。\n无时独不见，流泪空自知。\n\n塞虏乘秋下，天兵出汉家。\n将军分虎竹，战士卧龙沙。\n边月随弓影，胡霜拂剑花。\n玉关殊未入，少妇莫长嗟。\n\n烽火动沙漠，连照甘泉云。\n汉皇按剑起，还召李将军。\n兵气天上合，鼓声陇底闻。\n横行负勇气，一战净妖氛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塞下曲六首' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('献钱尚父', '贯休', '唐代', '贵逼人来不自由，龙骧凤翥势难收。\n满堂花醉三千客，一剑霜寒十四州。\n鼓角揭天嘉气冷，风涛动地海山秋。\n东南永作金天柱，谁羡当时万户侯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '献钱尚父' AND p.poem_author = '贯休';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过香积寺', '王维', '唐代', '不知香积寺，数里入云峰。\n古木无人径，深山何处钟。\n泉声咽危石，日色冷青松。\n薄暮空潭曲，安禅制毒龙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过香积寺' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卖痴呆词', '范成大', '宋代', '除夕更阑人不睡，厌禳钝滞迎新岁；\n小儿呼叫走长街，云有痴呆召人买。\n二物于人谁独无？就中吴侬仍有余；\n巷南巷北卖不得，相逢大笑相揶揄。\n栎翁块坐重帘下，独要买添令问价。\n儿云翁买不须钱，奉赊痴呆千百年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卖痴呆词' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('论诗五首', '赵翼', '清代', '满眼生机转化钧，天工人巧日争新。\n预支五百年新意，到了千年又觉陈。\n\n李杜诗篇万口传，至今已觉不新鲜。\n江山代有才人出，各领风骚数百年。\n\n只眼须凭自主张，纷纷艺苑漫雌黄。\n矮人看戏何曾见，都是随人说短长。\n\n少时学语苦难圆，只道工夫半未全。\n到老始知非力取，三分人事七分天。\n\n诗解穷人我未空，想因诗尚不曾工。\n熊鱼自笑贪心甚，既要工诗又怕穷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '论诗五首' AND p.poem_author = '赵翼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('唐多令·惜别', '吴文英', '宋代', '何处合成愁。离人心上秋。纵芭蕉、不雨也飕飕。都道晚凉天气好，有明月、怕登楼。 \n年事梦中休。花空烟水流。燕辞归、客尚淹留。垂柳不萦裙带住。漫长是、系行舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '唐多令·惜别' AND p.poem_author = '吴文英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹊桥仙·华灯纵博', '陆游', '宋代', '华灯纵博，雕鞍驰射，谁记当年豪举。酒徒一半取封侯，独去作、江边渔父。\n轻舟八尺，低篷三扇，占断苹洲烟雨。镜湖元自属闲人，又何必、君恩赐与。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹊桥仙·华灯纵博' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮·绿芜墙绕青苔院', '陈克', '宋代', '绿芜墙绕青苔院，中庭日淡芭蕉卷。蝴蝶上阶飞，烘帘自在垂。\n玉钩双语燕，宝甃杨花转。几处簸钱声，绿窗春睡轻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮·绿芜墙绕青苔院' AND p.poem_author = '陈克';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江城子·前瞻马耳九仙山', '苏轼', '宋代', '前瞻马耳九仙山。碧连天。晚云间。城上高台，真个是超然。莫使匆匆云雨散，今夜里，月婵娟。\n小溪鸥鹭静联拳。去翩翩。点轻烟。人事凄凉，回首便他年。莫忘使君歌笑处，垂柳下，矮槐前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江城子·前瞻马耳九仙山' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春·孤馆灯青', '苏轼', '宋代', '孤馆灯青，野店鸡号，旅枕梦残。渐月华收练，晨霜耿耿；云山摛锦，朝露漙漙。世路无穷，劳生有限，似此区区长鲜欢。微吟罢，凭征鞍无语，往事千端。\n当时共客长安，似二陆初来俱少年。有笔头千字，胸中万卷；致君尧舜，此事何难？用舍由时，行藏在我，袖手何妨闲处看。身长健，但优游卒岁，且斗尊前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春·孤馆灯青' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('劳劳亭', '李白', '唐代', '天下伤心处，劳劳送客亭。\n春风知别苦，不遣柳条青。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '劳劳亭' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('周亚夫军细柳', '司马迁', '两汉', '文帝之后六年，匈奴大入边。乃以宗正刘礼为将军，军霸上；祝兹侯徐厉为将军，军棘门；以河内守亚夫为将军，军细柳，以备胡。\n\n　　上自劳军。至霸上及棘门军，直驰入，将以下骑送迎。已而之细柳军，军士吏被甲，锐兵刃，彀弓弩，持满。天子先驱至，不得入。先驱曰：“天子且至！”军门都尉曰：“将军令曰：‘军中闻将军令，不闻天子之诏。’”居无何，上至，又不得入。于是上乃使使持节诏将军：“吾欲入劳军。”亚夫乃传言开壁门。壁门士吏谓从属车骑曰：“将军约，军中不得驱驰。”于是天子乃按辔徐行。至营，将军亚夫持兵揖曰：“介胄之士不拜，请以军礼见。”天子为动，改容式车，使人称谢：“皇帝敬劳将军。”成礼而去。\n\n　　既出军门，群臣皆惊。文帝曰：“嗟呼，此真将军矣！曩者霸上、棘门军，若儿戏耳，其将固可袭而虏也。至于亚夫，可得而犯邪？”称善者久之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '周亚夫军细柳' AND p.poem_author = '司马迁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('京都元夕', '元好问', '金朝', '袨服华妆着处逢，六街灯火闹儿童。\n长衫我亦何为者，也在游人笑语中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '京都元夕' AND p.poem_author = '元好问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八至', '李冶', '唐代', '至近至远东西，至深至浅清溪。\n至高至明日月，至亲至疏夫妻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八至' AND p.poem_author = '李冶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江村即事', '司空曙', '唐代', '钓罢归来不系船，江村月落正堪眠。 \n纵然一夜风吹去，只在芦花浅水边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江村即事' AND p.poem_author = '司空曙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浪淘沙·往事只堪哀', '李煜', '五代', '往事只堪哀，对景难排。秋风庭院藓侵阶。一任珠帘闲不卷，终日谁来。\n金锁已沉埋，壮气蒿莱。晚凉天净月华开。想得玉楼瑶殿影，空照秦淮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浪淘沙·往事只堪哀' AND p.poem_author = '李煜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠秀才入军·其十四', '嵇康', '魏晋', '息徒兰圃，秣马华山。\n流磻平皋，垂纶长川。\n目送归鸿，手挥五弦。\n俯仰自得，游心太玄。\n嘉彼钓叟，得鱼忘筌。\n郢人逝矣，谁与尽言？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠秀才入军·其十四' AND p.poem_author = '嵇康';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆秦娥·咏桐', '李清照', '宋代', '临高阁，乱山平野烟光薄。烟光薄，栖鸦归后，暮天闻角。\n断香残酒情怀恶，西风催衬梧桐落。梧桐落，又还秋色，又还寂寞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆秦娥·咏桐' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙·湖上西风急暮蝉', '晏殊', '宋代', '湖上西风急暮蝉。夜来清露湿红莲。少留归骑促歌筵。 \n为别莫辞金盏酒。入朝须近玉炉烟。不知重会是何年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙·湖上西风急暮蝉' AND p.poem_author = '晏殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑子·何人解赏西湖好', '欧阳修', '宋代', '何人解赏西湖好，佳景无时。飞盖相追。贪向花间醉玉卮。\n谁知闲凭阑干处，芳草斜晖。水远烟微。一点沧洲白鹭飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑子·何人解赏西湖好' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '后宫词' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花', '李煜', '唐代', '殷勤移植地，曲槛小栏边。共约重芳日，还忧不盛妍。 \n阻风开步障，乘月溉寒泉。谁料花前后，蛾眉却不全。 \n失却烟花主，东君自不知。清香更何用，犹发去年枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花' AND p.poem_author = '李煜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮·劝君今夜须沉醉', '韦庄', '唐代', '劝君今夜须沉醉，尊前莫话明朝事。珍重主人心，酒深情亦深。\n须愁春漏短，莫诉金杯满。遇酒且呵呵，人生能几何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮·劝君今夜须沉醉' AND p.poem_author = '韦庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('就义诗', '杨继盛', '明代', '浩气还太虚，丹心照千古。\n生平未报国，留作忠魂补。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '就义诗' AND p.poem_author = '杨继盛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日', '晁冲之', '宋代', '阴阴溪曲绿交加，小雨翻萍上浅沙。\n鹅鸭不知春去尽，争随流水趁桃花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日' AND p.poem_author = '晁冲之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆王孙·春词', '李重元', '宋代', '萋萋芳草忆王孙。柳外楼高空断魂。杜宇声声不忍闻。欲黄昏。雨打梨花深闭门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆王孙·春词' AND p.poem_author = '李重元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花', '晏殊', '宋代', '梨叶疏红蝉韵歇。银汉风高，玉管声凄切。枕簟乍凉铜漏咽。谁教社燕轻离别。 \n 草际蛩吟珠露结。宿酒醒来，不记归时节。多少衷肠犹未说。朱帘一夜朦胧月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花' AND p.poem_author = '晏殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('致酒行', '李贺', '唐代', '零落栖迟一杯酒，主人奉觞客长寿。\n主父西游困不归，家人折断门前柳。\n吾闻马周昔作新丰客，天荒地老无人识。\n空将笺上两行书，直犯龙颜请恩泽。\n我有迷魂招不得，雄鸡一声天下白。\n少年心事当拿云，谁念幽寒坐呜呃。(拿云 一作：拂云 / 擎云)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '致酒行' AND p.poem_author = '李贺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山房春事二首', '岑参', '唐代', '风恬日暖荡春光，戏蝶游蜂乱入房。\n数枝门柳低衣桁，一片山花落笔床。\n\n梁园日暮乱飞鸦，极目萧条三两家。\n庭树不知人去尽，春来还发旧时花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山房春事二首' AND p.poem_author = '岑参';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元夕无月', '丘逢甲', '清代', '满城灯市荡春烟，宝月沉沉隔海天。\n看到六鳌仙有泪，神山沦没已三年！\n\n三年此夕月无光，明月多应在故乡。\n欲向海天寻月去，五更飞梦渡鲲洋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元夕无月' AND p.poem_author = '丘逢甲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江陵愁望寄子安 / 江陵愁望有寄', '鱼玄机', '唐代', '枫叶千枝复万枝，江桥掩映暮帆迟。 \n忆君心似西江水，日夜东流无歇时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江陵愁望寄子安 / 江陵愁望有寄' AND p.poem_author = '鱼玄机';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书', '李峤', '唐代', '削简龙文见，临池鸟迹舒。\n河图八卦出，洛范九畴初。\n垂露春光满，崩云骨气馀。\n请君看入木，一寸乃非虚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书' AND p.poem_author = '李峤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('放言五首·其一', '白居易', '唐代', '朝真暮伪何人辨，古往今来底事无。\n但爱臧生能诈圣，可知宁子解佯愚。\n草萤有耀终非火，荷露虽团岂是珠。\n不取燔柴兼照乘，可怜光彩亦何殊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '放言五首·其一' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄海舟中日人索句并见日俄战争地图', '秋瑾', '清代', '万里乘风去复来，只身东海挟春雷。\n忍看图画移颜色，肯使江山付劫灰。\n浊酒不销忧国泪，救时应仗出群才。\n拼将十万头颅血，须把乾坤力挽回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄海舟中日人索句并见日俄战争地图' AND p.poem_author = '秋瑾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江神子·恨别', '苏轼', '宋代', '天涯流落思无穷。既相逢。却匆匆。摧手佳人，和泪折残红。为问东风余几许，春纵在，与谁同。\n隋堤三月水溶溶。背归鸿。去吴中。回首彭城，清泗与淮通。寄我相思千点泪，流不到，楚江东。(版本一)\n\n天涯流落思无穷！既相逢，却匆匆。携手佳人，和泪折残红。为问东风余几许？春纵在，与谁同！\n隋堤三月水溶溶。背归鸿，去吴中。回首彭城，清泗与淮通。欲寄相思千点泪，流不到，楚江东。(版本二)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江神子·恨别' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('草书屏风', '韩偓', '唐代', '何处一屏风，分明怀素踪。虽多尘色染，犹见墨痕浓。 \n怪石奔秋涧，寒藤挂古松。若教临水畔，字字恐成龙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '草书屏风' AND p.poem_author = '韩偓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日', '程颢', '宋代', '闲来无事不从容，睡觉东窗日已红。\n万物静观皆自得，四时佳兴与人同。\n道通天地有形外，思入风云变态中。\n富贵不淫贫贱乐，男儿到此是豪雄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日' AND p.poem_author = '程颢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('生查子·重叶梅', '辛弃疾', '宋代', '百花头上开，冰雪寒中见。霜月定相知，先识春风面。 \n主人情意深，不管江妃怨。折我最繁枝，还许冰壶荐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '生查子·重叶梅' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乐游原', '李商隐', '唐代', '万树鸣蝉隔岸虹，乐游原上有西风。 \n羲和自趁虞泉宿，不放斜阳更向东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乐游原' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杨柳枝词', '白居易', '唐代', '一树春风千万枝，嫩于金色软于丝。 \n永丰西角荒园里，尽日无人属阿谁？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杨柳枝词' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新安吏', '杜甫', '唐代', '客行新安道，喧呼闻点兵。\n借问新安吏：“县小更无丁？”\n“府帖昨夜下，次选中男行。”\n“中男绝短小，何以守王城？”\n肥男有母送，瘦男独伶俜。\n白水暮东流，青山犹哭声。\n“莫自使眼枯，收汝泪纵横。\n眼枯即见骨，天地终无情！\n我军取相州，日夕望其平。\n岂意贼难料，归军星散营。\n就粮近故垒，练卒依旧京。\n掘壕不到水，牧马役亦轻。\n况乃王师顺，抚养甚分明。\n送行勿泣血，仆射如父兄。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新安吏' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('简卢陟', '韦应物', '唐代', '可怜白雪曲，未遇知音人。\n恓惶戎旅下，蹉跎淮海滨。\n涧树含朝雨，山鸟哢馀春。\n我有一瓢酒，可以慰风尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '简卢陟' AND p.poem_author = '韦应物';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('女冠子·四月十七', '韦庄', '唐代', '四月十七，正是去年今日，别君时。忍泪佯低面，含羞半敛眉。\n不知魂已断，空有梦相随。除却天边月，没人知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '女冠子·四月十七' AND p.poem_author = '韦庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江楼旧感 / 江楼感旧', '赵嘏', '唐代', '独上江楼思渺然，月光如水水如天。\n同来望月人何处？风景依稀似去年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江楼旧感 / 江楼感旧' AND p.poem_author = '赵嘏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赤壁歌送别', '李白', '唐代', '二龙争战决雌雄，赤壁楼船扫地空。\n烈火张天照云海，周瑜于此破曹公。\n君去沧江望澄碧，鲸鲵唐突留馀迹。\n一一书来报故人，我欲因之壮心魄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赤壁歌送别' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('田园乐七首·其六 / 闲居', '王维', '唐代', '桃红复含宿雨，柳绿更带朝烟。\n花落家童未扫，莺啼山客犹眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '田园乐七首·其六 / 闲居' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('承宫樵薪苦学', '佚名', '先秦', '承宫，琅邪姑幕人。少孤，年八岁，为人牧猪。乡里徐子盛明《春秋》经，授诸生数百人。宫过其庐下，见诸生讲诵，好之，因忘其猪而听经。猪主怪其不还，寻之。见而欲笞之。门下生共禁，乃止，因留宫门下。樵薪执苦，数十年间，遂通其经。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '承宫樵薪苦学' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('点绛唇·丁未冬过吴松作', '姜夔', '宋代', '燕雁无心，太湖西畔随云去。数峰清苦。商略黄昏雨。 \n第四桥边，拟共天随住。今何许。凭阑怀古。残柳参差舞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '点绛唇·丁未冬过吴松作' AND p.poem_author = '姜夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·上巳召亲族', '李清照', '宋代', '永夜恹恹欢意少。空梦长安，认取长安道。为报今年春色好，花光月影宜相照。\n随意杯盘虽草草。酒美梅酸，恰称人怀抱。醉里插花花莫笑，可怜春似人将老。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·上巳召亲族' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临湖亭', '王维', '唐代', '轻舸迎上客，悠悠湖上来。\n当轩对尊酒，四面芙蓉开。(一作 对樽酒)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临湖亭' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('有狐', '佚名', '先秦', '有狐绥绥，在彼淇梁。心之忧矣，之子无裳。\n有狐绥绥，在彼淇厉。心之忧矣，之子无带。\n有狐绥绥，在彼淇侧。心之忧矣，之子无服。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '有狐' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南乡子·细雨湿流光', '冯延巳', '五代', '细雨湿流光，芳草年年与恨长。烟锁凤楼无限事，茫茫。鸾镜鸳衾两断肠。\n魂梦任悠扬，睡起杨花满绣床。薄悻不来门半掩，斜阳。负你残春泪几行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南乡子·细雨湿流光' AND p.poem_author = '冯延巳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卖花声·怀古', '张可久', '元代', '阿房舞殿翻罗袖，金谷名园起玉楼，隋堤古柳缆龙舟。不堪回首，东风还又，野花开暮春时候。\n美人自刎乌江岸，战火曾烧赤壁山，将军空老玉门关。伤心秦汉，生民涂炭，读书人一声长叹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卖花声·怀古' AND p.poem_author = '张可久';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六月二十日夜渡海', '苏轼', '宋代', '参横斗转欲三更，苦雨终风也解晴。\n云散月明谁点缀？天容海色本澄清。\n空余鲁叟乘桴意，粗识轩辕奏乐声。\n九死南荒吾不恨，兹游奇绝冠平生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六月二十日夜渡海' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洞仙歌·冰肌玉骨', '苏轼', '宋代', '仆七岁时，见眉州老尼，姓朱，忘其名，年九十岁。自言尝随其师入蜀主孟昶宫中，一日大热，蜀主与花蕊夫人夜纳凉摩诃池上，作一词，朱具能记之。今四十年，朱已死久矣，人无知此词者，但记其首两句，暇日寻味，岂《洞仙歌》令乎？乃为足之云。\n\n冰肌玉骨，自清凉无汗。水殿风来暗香满。绣帘开，一点明月窥人，人未寝，欹枕钗横鬓乱。\n起来携素手，庭户无声，时见疏星渡河汉。试问夜如何？夜已三更，金波淡，玉绳低转。但屈指西风几时来，又不道流年暗中偷换。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洞仙歌·冰肌玉骨' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('北陂杏花', '王安石', '宋代', '一陂春水绕花身，花影妖娆各占春。\n纵被春风吹作雪，绝胜南陌碾成尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '北陂杏花' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('州桥', '范成大', '宋代', '南望朱雀门，北望宣德楼，皆旧御路也。\n\n州桥南北是天街，父老年年等驾回。\n忍泪失声询使者，"几时真有六军来？"', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '州桥' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('溪居', '柳宗元', '唐代', '久为簪组累，幸此南夷谪。闲依农圃邻，偶似山林客。 \n晓耕翻露草，夜榜响溪石。来往不逢人，长歌楚天碧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '溪居' AND p.poem_author = '柳宗元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春望', '羊士谔', '唐代', '莫问华簪发已斑，归心满目是青山。 \n 独上层城倚危槛，柳营春尽马嘶闲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春望' AND p.poem_author = '羊士谔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('子夜吴歌·春歌', '李白', '唐代', '秦地罗敷女，采桑绿水边。\n素手青条上，红妆白日鲜。\n蚕饥妾欲去，五马莫留连。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '子夜吴歌·春歌' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送柴侍御', '王昌龄', '唐代', '沅水通波接武冈，送君不觉有离伤。\n青山一道同云雨，明月何曾是两乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送柴侍御' AND p.poem_author = '王昌龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏雨', '李世民', '唐代', '罩云飘远岫，喷雨泛长河。\n低飞昏岭腹，斜足洒岩阿。\n泫丛珠缔叶，起溜镜图波。\n濛柳添丝密，含吹织空罗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏雨' AND p.poem_author = '李世民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('简兮', '佚名', '先秦', '简兮简兮，方将万舞。日之方中，在前上处。\n硕人俣俣，公庭万舞。有力如虎，执辔如组。\n左手执龠，右手秉翟。赫如渥赭，公言锡爵。\n山有榛，隰有苓。云谁之思？西方美人。彼美人兮，西方之人兮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '简兮' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书愤二首', '陆游', '宋代', '白发萧萧卧泽中，只凭天地鉴孤忠。\n厄穷苏武餐毡久，忧愤张巡嚼齿空。\n细雨春芜上林苑，颓垣夜月洛阳宫。\n壮心未与年俱老，死去犹能作鬼雄。\n\n镜里流年两鬓残，寸心自许尚如丹。\n衰迟罢试戎衣窄，悲愤犹争宝剑寒。\n远戍十年临的博，壮图万里战皋兰。\n关河自古无穷事，谁料如今袖手看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书愤二首' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜算子', '程垓', '宋代', '枕簟暑风消，帘幕秋风动。月到夜来愁处明，只照团衾凤。 \n 去意杳无凭，别语愁难送。一纸鱼笺枕底香，且做新来梦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜算子' AND p.poem_author = '程垓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一剪梅·堆枕乌云堕翠翘', '蔡伸', '宋代', '堆枕乌云堕翠翘。午梦惊回，满眼春娇。嬛嬛一袅楚宫腰。那更春来，玉减香消。\n柳下朱门傍小桥。几度红窗，误认鸣镳。断肠风月可怜宵。忍使恹恹，两处无聊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '一剪梅·堆枕乌云堕翠翘' AND p.poem_author = '蔡伸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行路难', '释宝月', '南北朝', '君不见孤雁关外发，酸嘶度扬越。\n空城客子心肠断，幽闺思妇气欲绝。\n凝霜夜下拂罗衣，浮云中断开明月。\n夜夜遥遥徒相思，年年望望情不歇。\n寄我匣中青铜镜，倩人为君除白发。\n行路难，行路难，夜闻南城汉使度，使我流泪忆长安！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行路难' AND p.poem_author = '释宝月';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('途中见杏花', '吴融', '唐代', '一枝红杏出墙头，墙外行人正独愁。\n长得看来犹有恨，可堪逢处更难留！\n林空色暝莺先到，春浅香寒蝶未游。\n更忆帝乡千万树，澹烟笼日暗神州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '途中见杏花' AND p.poem_author = '吴融';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('为薛台悼亡', '白居易', '唐代', '半死梧桐老病身，重泉一念一伤神。 \n手携稚子夜归院，月冷空房不见人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '为薛台悼亡' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('从军行', '陈羽', '唐代', '海畔风吹冻泥裂，枯桐叶落枝梢折。 \n横笛闻声不见人，红旗直上天山雪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '从军行' AND p.poem_author = '陈羽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·邶风·泉水', '佚名', '先秦', '毖彼泉水，亦流于淇。有怀于卫，靡日不思。娈彼诸姬，聊与之谋。\n出宿于泲，饮饯于祢，女子有行，远父母兄弟。问我诸姑，遂及伯姊。\n出宿于干，饮饯于言。载脂载舝，还车言迈。遄臻于卫，不瑕有害？\n我思肥泉，兹之永叹。思须与漕，我心悠悠。驾言出游，以写我忧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·邶风·泉水' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饮湖上初晴后雨二首·其一', '苏轼', '宋代', '朝曦迎客艳重冈，晚雨留人入醉乡。\n此意自佳君不会，一杯当属水仙王。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饮湖上初晴后雨二首·其一' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('漫感', '龚自珍', '清代', '绝域从军计惘然，东南幽恨满词笺。\n一箫一剑平生意，负尽狂名十五年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '漫感' AND p.poem_author = '龚自珍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·满地霜华浓似雪', '王国维', '清代', '满地霜华浓似雪。人语西风，瘦马嘶残月。一曲阳关浑未彻。车声渐共歌声咽。\n换尽天涯芳草色。陌上深深，依旧年时辙。自是浮生无可说。人间第一耽离别。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·满地霜华浓似雪' AND p.poem_author = '王国维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('破阵子·燕子欲归时节', '晏殊', '宋代', '燕子欲归时节，高楼昨夜西风。求得人间成小会，试把金尊傍菊丛。歌长粉面红。\n斜日更穿帘幕，微凉渐入梧桐。多少襟情言不尽，写向蛮笺曲调中。此情千万重。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '破阵子·燕子欲归时节' AND p.poem_author = '晏殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长城', '朱庆馀', '唐代', '秦帝防胡虏，关心倍可嗟。一人如有德，四海尽为家。 \n 往事乾坤在，荒基草木遮。至今徒者骨，犹自哭风沙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长城' AND p.poem_author = '朱庆馀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('墨子怒耕柱子', '墨子及弟子 撰', '先秦', '墨子怒耕柱子。耕柱子曰：“我无愈于人乎？”墨子曰：“我将上太行，以骥与牛驾，子将谁策？”耕柱子曰：“将策骥也。”墨子曰：“何故策骥也？”耕柱子曰 ：“骥足以策。” 墨子曰：“我亦以子为足以策，故怒之。”耕柱子悟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '墨子怒耕柱子' AND p.poem_author = '墨子及弟子 撰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('摊破浣溪沙·手卷真珠上玉钩', '李璟', '五代', '手卷真珠上玉钩，依前春恨锁重楼。风里落花谁是主？思悠悠。\n青鸟不传云外信，丁香空结雨中愁。回首绿波三楚暮，接天流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '摊破浣溪沙·手卷真珠上玉钩' AND p.poem_author = '李璟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟行路难·其六', '鲍照', '南北朝', '对案不能食，拔剑击柱长叹息。\n丈夫生世会几时？安能蹀躞垂羽翼！\n弃置罢官去，还家自休息。\n朝出与亲辞，暮还在亲侧。\n弄儿床前戏，看妇机中织。\n自古圣贤尽贫贱，何况我辈孤且直！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟行路难·其六' AND p.poem_author = '鲍照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人·玉楼缥缈孤烟际', '欧阳澈', '宋代', '玉楼缥缈孤烟际。徒倚愁如醉。雁来人远暗消魂。帘卷一钩新月、怯黄昏。\n那人音信全无个。幽恨谁凭破。扑花蝴蝶若知人。为我一场清梦、去相亲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人·玉楼缥缈孤烟际' AND p.poem_author = '欧阳澈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·早行', '周邦彦', '宋代', '月皎惊乌栖不定，更漏将残，辘轳牵金井。唤起两眸清炯炯。泪花落枕红绵冷。\n执手霜风吹鬓影。去意徊徨，别语愁难听。楼上阑干横斗柄，露寒人远鸡相应。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·早行' AND p.poem_author = '周邦彦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('定风波·自春来', '柳永', '宋代', '自春来、惨绿愁红，芳心是事可可。日上花梢，莺穿柳带，犹压香衾卧。暖酥消、腻云亸，终日厌厌倦梳裹。无那。恨薄情一去，音书无个。\n早知恁么，悔当初、不把雕鞍锁。向鸡窗，只与蛮笺象管，拘束教吟课。镇相随、莫抛躲，针线闲拈伴伊坐。和我，免使年少，光阴虚过。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '定风波·自春来' AND p.poem_author = '柳永';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读书', '柳宗元', '唐代', '幽沉谢世事，俯默窥唐虞。上下观古今，起伏千万途。 \n 遇欣或自笑，感戚亦以吁。缥帙各舒散，前后互相逾。 \n 瘴痾扰灵府，日与往昔殊。临文乍了了，彻卷兀若无。 \n 竟夕谁与言，但与竹素俱。倦极便倒卧，熟寐乃一苏。 \n 欠伸展肢体，吟咏心自愉。得意适其适，非愿为世儒。 \n 道尽即闭口，萧散捐囚拘。巧者为我拙，智者为我愚。 \n 书史足自悦，安用勤与劬。贵尔六尺躯，勿为名所驱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读书' AND p.poem_author = '柳宗元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采莲曲', '李白', '唐代', '若耶溪傍采莲女，笑隔荷花共人语。\n日照新妆水底明，风飘香袂空中举。\n岸上谁家游冶郎，三三五五映垂杨。\n紫骝嘶入落花去，见此踟蹰空断肠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采莲曲' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四时', '陶渊明', '魏晋', '春水满四泽，夏云多奇峰。\n秋月扬明晖，冬岭秀寒松。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四时' AND p.poem_author = '陶渊明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登鹳雀楼', '畅当', '唐代', '迥临飞鸟上，高出世尘间。\n天势围平野，河流入断山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登鹳雀楼' AND p.poem_author = '畅当';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹里馆', '卢象', '唐代', '江南冰不闭，山泽气潜通。腊月闻山鸟，寒崖见蛰熊。 \n 柳林春半合，荻笋乱无丛。回首金陵岸，依依向北风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹里馆' AND p.poem_author = '卢象';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苛政猛于虎', '佚名', '先秦', '孔子过泰山侧 ，有妇人哭于墓者而哀，夫子式而听之，使子路问之，曰：“子之哭也，壹似重有忧者。”而曰：“然。昔者吾舅死于虎，吾夫又死焉，今吾子又死焉。”夫子曰：“何为不去也？”曰：“无苛政。”夫子曰：“小子识之：苛政猛于虎也。”\n\n　　出自《十三经注疏》本《礼记·檀弓下》。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苛政猛于虎' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('木兰花慢·可怜今夕月', '辛弃疾', '宋代', '中秋饮酒将旦，客谓前人诗词有赋待月无送月者，因用《天问》体赋。\n\n可怜今夕月，向何处，去悠悠？是别有人间，那边才见，光影东头？是天外。空汗漫，但长风浩浩送中秋？飞镜无根谁系？姮娥不嫁谁留？\n谓经海底问无由，恍惚使人愁。怕万里长鲸，纵横触破，玉殿琼楼。虾蟆故堪浴水，问云何玉兔解沉浮？若道都齐无恙，云何渐渐如钩？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '木兰花慢·可怜今夕月' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆江南·春去也', '刘禹锡', '唐代', '春去也，多谢洛城人。弱柳从风疑举袂，丛兰裛露似沾巾。独坐亦含嚬。\n春去也，共惜艳阳年。犹有桃花流水上，无辞竹叶醉尊前。惟待见青天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆江南·春去也' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('叹花 / 怅诗', '杜牧', '唐代', '自是寻春去校迟，不须惆怅怨芳时。 \n狂风落尽深红色，绿叶成阴子满枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '叹花 / 怅诗' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋登兰山寄张五 / 九月九日岘山寄张子容', '孟浩然', '唐代', '北山白云里，隐者自怡悦。\n相望试登高，心随雁飞灭。(试 一作 始)\n愁因薄暮起，兴是清秋发。\n时见归村人，沙行渡头歇。\n天边树若荠，江畔洲如月。\n何当载酒来，共醉重阳节。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋登兰山寄张五 / 九月九日岘山寄张子容' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长干行二首', '李白', '唐代', '妾发初覆额，折花门前剧。\n郎骑竹马来，绕床弄青梅。\n同居长干里，两小无嫌猜，\n十四为君妇，羞颜未尝开。\n低头向暗壁，千唤不一回。\n十五始展眉，愿同尘与灰。\n常存抱柱信，岂上望夫台。\n十六君远行，瞿塘滟滪堆。\n五月不可触，猿声天上哀。\n门前迟行迹，一一生绿苔。\n苔深不能扫，落叶秋风早。\n八月胡蝶来，双飞西园草。\n感此伤妾心，坐愁红颜老。\n早晚下三巴，预将书报家。\n相迎不道远，直至长风沙。\n\n忆妾深闺里，烟尘不曾识。\n嫁与长干人，沙头候风色。\n五月南风兴，思君下巴陵。\n八月西风起，想君发扬子。\n去来悲如何，见少离别多。\n湘潭几日到，妾梦越风波。\n昨夜狂风度，吹折江头树。\n淼淼暗无边，行人在何处。\n好乘浮云骢，佳期兰渚东。\n鸳鸯绿蒲上，翡翠锦屏中。\n自怜十五余，颜色桃花红。\n那作商人妇，愁水复愁风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长干行二首' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塞鸿秋·浔阳即景', '周德清', '元代', '长江万里白如练，淮山数点青如淀。\n江帆几片疾如箭，山泉千尺飞如电。\n晚云都变露，新月初学扇。\n塞鸿一字来如线。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塞鸿秋·浔阳即景' AND p.poem_author = '周德清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('惜牡丹花二首', '白居易', '唐代', '翰林院北厅花下作\n惆怅阶前红牡丹，晚来唯有两枝残。\n明朝风起应吹尽，夜惜衰红把火看。\n\n新昌窦给事宅南亭花下作\n寂寞萎红低向雨，离披破艳散随风。\n晴明落地犹惆怅，何况飘零泥土中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '惜牡丹花二首' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春雪', '刘方平', '唐代', '飞雪带春风，徘徊乱绕空。\n君看似花处，偏在洛城中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春雪' AND p.poem_author = '刘方平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春远 / 春运', '杜甫', '唐代', '肃肃花絮晚，菲菲红素轻。日长唯鸟雀，春远独柴荆。 \n数有关中乱，何曾剑外清。故乡归不得，地入亚夫营。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春远 / 春运' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('马诗二十三首·其四', '李贺', '唐代', '此马非凡马，房星本是星。\n向前敲瘦骨，犹自带铜声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '马诗二十三首·其四' AND p.poem_author = '李贺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('有所思', '佚名', '两汉', '有所思，乃在大海南。\n何用问遗君，双珠玳瑁簪。\n用玉绍缭之。\n闻君有他心，拉杂摧烧之。\n摧烧之，当风扬其灰！\n从今以往，勿复相思，相思与君绝！\n鸡鸣狗吠，兄嫂当知之。\n妃呼狶！\n秋风肃肃晨风飔，东方须臾高知之！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '有所思' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瑶池' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('示儿', '韩愈', '唐代', '始我来京师，止携一束书。\n辛勤三十年，以有此屋庐。\n此屋岂为华，于我自有余。\n中堂高且新，四时登牢蔬。\n前荣馔宾亲，冠婚之所于。\n庭内无所有，高树八九株。\n有藤娄络之，春华夏阴敷。\n东堂坐见山，云风相吹嘘。\n松果连南亭，外有瓜芋区。\n西偏屋不多，槐榆翳空虚。\n山鸟旦夕鸣，有类涧谷居。\n主妇治北堂，膳服适戚疏。\n恩封高平君，子孙从朝裾。\n开门问谁来，无非卿大夫。\n不知官高卑，玉带悬金鱼。\n问客之所为，峨冠讲唐虞。\n酒食罢无为，棋槊以相娱。\n凡此座中人，十九持钧枢。\n又问谁与频，莫与张樊如。\n来过亦无事，考评道精粗。\n跹跹媚学子，墙屏日有徒。\n以能问不能，其蔽岂可祛。\n嗟我不修饰，事与庸人俱。\n安能坐如此，比肩于朝儒。\n诗以示儿曹，其无迷厥初。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '示儿' AND p.poem_author = '韩愈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉树后庭花', '陈叔宝', '南北朝', '丽宇芳林对高阁，新装艳质本倾城。\n映户凝娇乍不进，出帷含态笑相迎。\n妖姬脸似花含露，玉树流光照后庭。\n花开花落不长久，落红满地归寂中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉树后庭花' AND p.poem_author = '陈叔宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('墨池记', '曾巩', '宋代', '临川之城东，有地隐然而高，以临于溪，曰新城。新城之上，有池洼然而方以长，曰王羲之之墨池者，荀伯子《临川记》云也。羲之尝慕张芝，临池学书，池水尽黑，此为其故迹，岂信然邪？\n\n　　方羲之之不可强以仕，而尝极东方，出沧海，以娱其意于山水之间；岂其徜徉肆恣，而又尝自休于此邪？羲之之书晚乃善，则其所能，盖亦以精力自致者，非天成也。然后世未有能及者，岂其学不如彼邪？则学固岂可以少哉，况欲深造道德者邪？\n\n　　墨池之上，今为州学舍。教授王君盛恐其不章也，书‘晋王右军墨池’之六字于楹间以揭之。又告于巩曰：“愿有记”。推王君之心，岂爱人之善，虽一能不以废，而因以及乎其迹邪？其亦欲推其事以勉其学者邪？夫人之有一能而使后人尚之如此，况仁人庄士之遗风余思被于来世者何如哉！\n\n　　庆历八年九月十二日，曾巩记。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '墨池记' AND p.poem_author = '曾巩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凉州词三首', '张籍', '唐代', '边城暮雨雁飞低，芦笋初生渐欲齐。\n无数铃声遥过碛，应驮白练到安西。\n\n古镇城门白碛开，胡兵往往傍沙堆。\n巡边使客行应早，欲问平安无使来。\n\n风林关里水东流，白草黄榆六十秋。\n边将皆承主恩泽，无人解道取凉州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凉州词三首' AND p.poem_author = '张籍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宣城见杜鹃花 / 子规', '李白', '唐代', '蜀国曾闻子规鸟，宣城还见杜鹃花。 \n一叫一回肠一断，三春三月忆三巴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宣城见杜鹃花 / 子规' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江南春·波渺渺', '寇准', '宋代', '波渺渺，柳依依。孤村芳草远，斜日杏花飞。江南春尽离肠断，苹满汀洲人未归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江南春·波渺渺' AND p.poem_author = '寇准';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感遇·江南有丹橘', '张九龄', '唐代', '江南有丹橘，经冬犹绿林。\n岂伊地气暖？自有岁寒心。\n可以荐嘉客，奈何阻重深。\n运命惟所遇，循环不可寻。\n徒言树桃李，此木岂无阴？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感遇·江南有丹橘' AND p.poem_author = '张九龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏答元珍', '欧阳修', '宋代', '春风疑不到天涯，二月山城未见花。\n残雪压枝犹有桔，冻雷惊笋欲抽芽。\n夜闻归雁生乡思，病入新年感物华。\n曾是洛阳花下客，野芳虽晚不须嗟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏答元珍' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红·赤壁怀古', '戴复古', '宋代', '赤壁矶头，一番过、一番怀古。想当时，周郎年少，气吞区宇。万骑临江貔虎噪，千艘列炬鱼龙怒。卷长波、一鼓困曹瞒，今如许？\n江上渡，江边路。形胜地，兴亡处。览遗踪，胜读史书言语。几度东风吹世换，千年往事随潮去。问道傍、杨柳为谁春，摇金缕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红·赤壁怀古' AND p.poem_author = '戴复古';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐·题上卢桥', '辛弃疾', '宋代', '清溪奔快。不管青山碍。千里盘盘平世界。更著溪山襟带。 \n古今陵谷茫茫。市朝往往耕桑。此地居然形胜，似曾小小兴亡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐·题上卢桥' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水龙吟·过南剑双溪楼', '辛弃疾', '宋代', '举头西北浮云，倚天万里须长剑。人言此地，夜深长见，斗牛光焰。我觉山高，潭空水冷，月明星淡。待燃犀下看，凭栏却怕，风雷怒，鱼龙惨。\n峡束苍江对起，过危楼，欲飞还敛。元龙老矣！不妨高卧，冰壶凉簟。千古兴亡，百年悲笑，一时登览。问何人又卸，片帆沙岸，系斜阳缆？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水龙吟·过南剑双溪楼' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('述国亡诗', '花蕊夫人', '五代', '君王城上竖降旗，妾在深宫那得知？\n十四万人齐解甲，更无一个是男儿！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '述国亡诗' AND p.poem_author = '花蕊夫人';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('落花', '李商隐', '唐代', '高阁客竟去，小园花乱飞。参差连曲陌，迢递送斜晖。 \n肠断未忍扫，眼穿仍欲归。芳心向春尽，所得是沾衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '落花' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('燕诗示刘叟', '白居易', '唐代', '梁上有双燕，翩翩雄与雌。\n衔泥两椽间，一巢生四儿。\n四儿日夜长，索食声孜孜。\n青虫不易捕，黄口无饱期。\n觜爪虽欲敝，心力不知疲。\n须臾十来往，犹恐巢中饥。\n辛勤三十日，母瘦雏渐肥。\n喃喃教言语，一一刷毛衣。\n一旦羽翼成，引上庭树枝。\n举翅不回顾，随风四散飞。\n雌雄空中鸣，声尽呼不归。\n却入空巢里，啁啾终夜悲。\n燕燕尔勿悲，尔当返自思。\n思尔为雏日，高飞背母时。\n当时父母念，今日尔应知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '燕诗示刘叟' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赐萧瑀', '李世民', '唐代', '疾风知劲草，板荡识诚臣。\n勇夫安识义，智者必怀仁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赐萧瑀' AND p.poem_author = '李世民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏同心芙蓉', '杜公瞻', '隋代', '灼灼荷花瑞，亭亭出水中。\n一茎孤引绿，双影共分红。\n色夺歌人脸，香乱舞衣风。\n名莲自可念，况复两心同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏同心芙蓉' AND p.poem_author = '杜公瞻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('老将行', '王维', '唐代', '少年十五二十时，步行夺得胡马骑。\n射杀山中白额虎，肯数邺下黄须儿！\n一身转战三千里，一剑曾当百万师。\n汉兵奋迅如霹雳，虏骑崩腾畏蒺藜。\n卫青不败由天幸，李广无功缘数奇。\n自从弃置便衰朽，世事蹉跎成白首。\n昔时飞箭无全目，今日垂杨生左肘。\n路旁时卖故侯瓜，门前学种先生柳。\n苍茫古木连穷巷，寥落寒山对虚牖。\n誓令疏勒出飞泉，不似颍川空使酒。\n贺兰山下阵如云，羽檄交驰日夕闻。\n节使三河募年少，诏书五道出将军。\n试拂铁衣如雪色，聊持宝剑动星文。\n愿得燕弓射大将，耻令越甲鸣吾君。\n莫嫌旧日云中守，犹堪一战取功勋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '老将行' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('思母', '与恭', '宋代', '霜殒芦花泪湿衣，白头无复倚柴扉。\n去年五月黄梅雨，曾典袈裟籴米归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '思母' AND p.poem_author = '与恭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·小令尊前见玉箫', '晏几道', '宋代', '小令尊前见玉箫。银灯一曲太妖娆。歌中醉倒谁能恨，唱罢归来酒未消。 \n春悄悄，夜迢迢。碧云天共楚宫遥。梦魂惯得无拘检，又踏杨花过谢桥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·小令尊前见玉箫' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('对雪二首', '李商隐', '唐代', '寒气先侵玉女扉，清光旋透省郎闱。\n梅花大庾岭头发，柳絮章台街里飞。\n欲舞定随曹植马，有情应湿谢庄衣。\n龙山万里无多远，留待行人二月归。\n\n旋扑珠帘过粉墙，轻于柳絮重于霜。\n已随江令夸琼树，又入卢家妒玉堂。\n侵夜可能争桂魄，忍寒应欲试梅妆。\n关河冻合东西路，肠断斑骓送陆郎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '对雪二首' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('听蜀僧濬弹琴 / 听蜀僧浚弹琴', '李白', '唐代', '蜀僧抱绿绮，西下峨眉峰。\n为我一挥手，如听万壑松。 \n客心洗流水，余响入霜钟。\n不觉碧山暮，秋云暗几重。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '听蜀僧濬弹琴 / 听蜀僧浚弹琴' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('琵琶仙·中秋', '纳兰性德', '清代', '碧海年年，试问取、冰轮为谁圆缺？吹到一片秋香，清辉了如雪。愁中看、好天良夜，知道尽成悲咽。只影而今，那堪重对，旧时明月。\n花径里、戏捉迷藏，曾惹下萧萧井梧叶。记否轻纨小扇，又几番凉热.。只落得，填膺百感，总茫茫、不关离别。一任紫玉无情，夜寒吹裂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '琵琶仙·中秋' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诉衷情·青衫初入九重城', '陆游', '宋代', '青衫初入九重城，结友尽豪英。蜡封夜半传檄，驰骑谕幽并。\n时易失，志难城，鬓丝生。平章风月，弹压江山，别是功名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诉衷情·青衫初入九重城' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人·宜州见梅作', '黄庭坚', '宋代', '天涯也有江南信。梅破知春近。夜阑风细得香迟。不道晓来开遍、向南枝。 \n玉台弄粉花应妒。飘到眉心住。平生个里愿杯深。去国十年老尽、少年心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人·宜州见梅作' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('木兰歌', '韦元甫', '唐代', '木兰抱杼嗟，借问复为谁。 欲闻所戚戚，感激强起颜。\n老父隶兵籍，气力日衰耗。岂足万里行，有子复尚少！\n胡沙没马足，朔风裂人肤。老父旧羸病，何以强自扶？\n木兰代父去，秣马备戎行。易却纨绮裳，洗却铅粉妆。\n驰马赴军幕，慷慨携干将。朝屯雪山下，暮宿青海旁。\n夜袭燕支虏，更携于阗羌。将军得胜归，士卒还故乡。\n父母见木兰，喜极成悲伤。木兰能承父母颜，却卸巾帼理丝黄。\n昔为烈士雄，今复娇子容。\n亲戚持酒贺，父母始知生女与男同。\n门前旧军都，十年共崎岖。本结兄弟交，死战誓不渝。\n今者见木兰，言声虽是颜貌殊。\n惊愕不敢前，叹重徒嘻吁。世有臣子心，能如木兰节，忠孝两不渝，千古之名焉可灭！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '木兰歌' AND p.poem_author = '韦元甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·召南·野有死麕', '佚名', '先秦', '野有死麕，白茅包之。有女怀春，吉士诱之。\n林有朴樕，野有死鹿。白茅纯束，有女如玉。\n舒而脱脱兮！无感我帨兮！无使尨也吠！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·召南·野有死麕' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人·小梅枝上东君信', '晏几道', '宋代', '小梅枝上东君信。雪后花期近。南枝开尽北枝开。长被陇头游子、寄春来。\n年年衣袖年年泪。总为今朝意。问谁同是忆花人。赚得小鸿眉黛、也低颦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人·小梅枝上东君信' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春风', '白居易', '唐代', '春风先发苑中梅，樱杏桃梨次第开。 \n荠花榆荚深村里，亦道春风为我来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春风' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清明', '孙昌胤', '唐代', '清明暮春里，怅望北山陲。\n燧火开新焰，桐花发故枝。\n沈冥惭岁物，欢宴阻朋知。\n不及林间鸟，迁乔并羽仪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清明' AND p.poem_author = '孙昌胤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菁菁者莪', '佚名', '先秦', '菁菁者莪，在彼中阿。既见君子，乐且有仪。\n菁菁者莪，在彼中沚。既见君子，我心则喜。\n菁菁者莪，在彼中陵。既见君子，锡我百朋。\n泛泛杨舟，载沉载浮。既见君子，我心则休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菁菁者莪' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江有汜', '佚名', '先秦', '江有汜，之子归，不我以。不我以，其后也悔。\n江有渚，之子归，不我与。不我与，其后也处。\n江有沱，之子归，不我过。不我过，其啸也歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江有汜' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏菊', '白居易', '唐代', '一夜新霜著瓦轻，芭蕉新折败荷倾。\n耐寒唯有东篱菊，金粟初开晓更清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏菊' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹊桥仙·七夕', '苏轼', '宋代', '缑山仙子，高清云渺，不学痴牛騃女。凤箫声断月明中，举手谢时人欲去。\n客槎曾犯，银河波浪，尚带天风海雨。相逢一醉是前缘，风雨散、飘然何处？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹊桥仙·七夕' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新晴', '刘攽', '宋代', '青苔满地初晴后，绿树无人昼梦余。\n唯有南风旧相识，偷开门户又翻书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新晴' AND p.poem_author = '刘攽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜算子·苕霅水能清', '吴潜', '宋代', '苕霅水能清，更有人如水。秋水横边簇远山，相对盈盈里。 \n溪上有鸳鸯，艇子频惊起。何似收归碧玉池。长在阑干底。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜算子·苕霅水能清' AND p.poem_author = '吴潜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暗香·旧时月色', '姜夔', '宋代', '辛亥之冬，余载雪诣石湖。止既月，授简索句，且征新声，作此两曲，石湖把玩不已，使二妓肆习之，音节谐婉，乃名之曰《暗香》、《疏影》。\n\n旧时月色，算几番照我，梅边吹笛？唤起玉人，不管清寒与攀摘。何逊而今渐老，都忘却春风词笔。但怪得竹外疏花，香冷入瑶席。\n江国，正寂寂，叹寄与路遥，夜雪初积。翠尊易泣，红萼无言耿相忆。长记曾携手处，千树压、西湖寒碧。又片片、吹尽也，几时见得？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暗香·旧时月色' AND p.poem_author = '姜夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元和十年自朗州至京戏赠看花诸君子 / 玄都观桃花', '刘禹锡', '唐代', '紫陌红尘拂面来，无人不道看花回。\n玄都观里桃千树，尽是刘郎去后栽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元和十年自朗州至京戏赠看花诸君子 / 玄都观桃花' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清明', '杜甫', '唐代', '著处繁花务是日，长沙千人万人出。渡头翠柳艳明眉， \n 争道朱蹄骄啮膝。此都好游湘西寺，诸将亦自军中至。 \n 马援征行在眼前，葛强亲近同心事。金镫下山红粉晚， \n 牙樯捩柁青楼远。古时丧乱皆可知，人世悲欢暂相遣。 \n 弟侄虽存不得书，干戈未息苦离居。逢迎少壮非吾道， \n 况乃今朝更祓除。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清明' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送魏二', '王昌龄', '唐代', '醉别江楼橘柚香，江风引雨入舟凉。 \n忆君遥在潇湘月，愁听清猿梦里长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送魏二' AND p.poem_author = '王昌龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哀溺文序', '柳宗元', '唐代', '永之氓咸善游。一日，水暴甚，有五、六氓乘小船绝湘水。中济，船破，皆游。其一氓尽力而不能寻常。其侣曰：“汝善游最也，今何后为？”曰：“吾腰千钱，重，是以后。”曰：“何不去之？”不应，摇其首。有顷，益怠。已济者立岸上呼且号曰：“汝愚之甚，蔽之甚，身且死，何以货为？”又摇其首。遂溺死。吾哀之。且若是，得不有大货之溺大氓者乎？于是作《哀溺》。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哀溺文序' AND p.poem_author = '柳宗元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋月二首·其二', '李峤', '唐代', '圆魄上寒空，皆言四海同。\n安知千里外，不有雨兼风？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋月二首·其二' AND p.poem_author = '李峤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荷叶杯·记得那年花下', '韦庄', '唐代', '记得那年花下，深夜，初识谢娘时。水堂西面画帘垂，携手暗相期。\n惆怅晓莺残月，相别，从此隔音尘。如今俱是异乡人，相见更无因。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荷叶杯·记得那年花下' AND p.poem_author = '韦庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行香子·过七里濑', '苏轼', '宋代', '一叶舟轻，双桨鸿惊。水天清、影湛波平。鱼翻藻鉴，鹭点烟汀。过沙溪急，霜溪冷，月溪明。\n重重似画，曲曲如屏。算当年、虚老严陵。君臣一梦，今古空名。但远山长，云山乱，晓山青。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行香子·过七里濑' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠邻女 / 寄李亿员外', '鱼玄机', '唐代', '羞日遮罗袖，愁春懒起妆。\n易求无价宝，难得有心郎。\n枕上潜垂泪，花间暗断肠。\n自能窥宋玉，何必恨王昌？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠邻女 / 寄李亿员外' AND p.poem_author = '鱼玄机';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早春', '白居易', '唐代', '雪散因和气，冰开得暖光。\n春销不得处，唯有鬓边霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早春' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春山夜月', '于良史', '唐代', '春山多胜事，赏玩夜忘归。\n掬水月在手，弄花香满衣。\n兴来无远近，欲去惜芳菲。\n南望鸣钟处，楼台深翠微。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春山夜月' AND p.poem_author = '于良史';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酌酒与裴迪', '王维', '唐代', '酌酒与君君自宽，人情翻覆似波澜。\n白首相知犹按剑，朱门先达笑弹冠。\n草色全经细雨湿，花枝欲动春风寒。\n世事浮云何足问，不如高卧且加餐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酌酒与裴迪' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题秋江独钓图', '王士祯', '清代', '一蓑一笠一扁舟，一丈丝纶一寸钩。\n一曲高歌一樽酒，一人独钓一江秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题秋江独钓图' AND p.poem_author = '王士祯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九章', '屈原', '先秦', '惜诵\n\n　　惜诵以致愍兮，发愤以抒情。\n　　所作忠而言之兮，指苍天以为正。\n　　令五帝使折中兮，戒六神与向服。\n　　俾山川以备御兮，命咎繇使听直。\n　　竭忠诚而事君兮，反离群而赘肬。\n　　忘儇媚以背众兮，待明君其知之。\n　　言与行其可迹兮，情与貌其不变。\n　　故相臣莫若君兮，所以证之不远。\n　　吾谊先君而后身兮，羌众人之所仇也。\n　　专惟君而无他兮，又众兆之所雠也。\n　　壹心而不豫兮，羌无可保也。\n　　疾亲君而无他兮，有招祸之道也。\n　　思君其莫我忠兮，忽忘身之贱贫。\n　　事君而不贰兮，迷不知宠之门。\n　　患何罪以遇罚兮，亦非余之所志也。\n　　行不群以巅越兮，又众兆之所咍也。\n　　纷逢尤以离谤兮，謇不可释也。\n　　情沉抑而不达兮，又蔽而莫之白也。\n　　心郁邑余侘傺兮，又莫察余之中情。\n　　固烦言不可结而诒兮，愿陈志而无路。\n　　退静默而莫余知兮，进号呼又莫吾闻。\n　　申侘傺之烦惑兮，中闷瞀之忳忳。\n　　昔余梦登天兮，魂中道而无杭。\n　　吾使厉神占之兮，曰有志极而无旁。\n　　终危独以离异兮，曰君可思而不可恃。\n　　故众口其铄金兮，初若是而逢殆。\n　　惩于羹者而吹齑兮，何不变此志也？\n　　欲释阶而登天兮，犹有曩之态也。\n　　众骇遽以离心兮，又何以为此伴也？\n　　同极而异路兮，又何以为此援也？\n　　晋申生之孝子兮，父信谗而不好。\n　　行婞直而不豫兮，鲧功用而不就。\n　　吾闻作忠以造怨兮，忽谓之过言。\n　　九折臂而成医兮，吾至今而知其信然。\n　　矰弋机而在上兮，罻罗张而在下。\n　　设张辟以娱君兮，愿侧身而无所。\n　　欲儃徊以干傺兮，恐重患而离尤。\n　　欲高飞而远集兮，君罔谓汝何之？\n　　欲横奔而失路兮，盖志坚而不忍。\n　　背膺牉以交痛兮，心郁结而纡轸。\n　　擣木兰以矫蕙兮，糳申椒以为粮。\n　　播江离与滋菊兮，愿春日以为糗芳。\n　　恐情质之不信兮，故重著以自明。\n　　矫兹媚以私处兮，愿曾思而远身。\n\n\n涉江\n　　余幼好此奇服兮，年既老而不衰。\n　　带长铗之陆离兮，冠切云之崔嵬，\n　　被明月兮佩宝璐。\n　　世混浊而莫余知兮，吾方高驰而不顾。\n　　驾青虬兮骖白螭，吾与重华游兮瑶之圃。\n　　登昆仑兮食玉英，与天地兮同寿，\n　　与日月兮同光。\n　　哀南夷之莫吾知兮，旦余济乎江湘。\n　　乘鄂渚而反顾兮，欸秋冬之绪风。\n　　步余马兮山皋，邸余车兮方林。\n　　乘舲船余上沅兮，齐吴榜以击汰。\n　　船容与而不进兮，淹回水而疑滞。\n　　朝发枉渚兮，夕宿辰阳。\n　　苟余心其端直兮，虽僻远之何伤。\n　　入溆浦余儃徊兮，迷不知吾所如。\n　　深林杳以冥冥兮，乃猿狖之所居。\n　　山峻高以蔽日兮，下幽晦以多雨。\n　　霰雪纷其无垠兮，云霏霏而承宇。\n　　哀吾生之无乐兮，幽独处乎山中。\n　　吾不能变心而从俗兮，固将愁苦而终穷。\n　　接舆髡首兮，桑扈臝行。\n　　忠不必用兮，贤不必以。\n　　伍子逢殃兮，比干菹醢。\n　　与前世而皆然兮，吾又何怨乎今之人！\n　　余将董道而不豫兮，固将重昏而终身！\n　　乱曰：鸾鸟凤皇，日以远兮。\n　　燕雀乌鹊，巢堂坛兮。\n　　露申辛夷，死林薄兮。\n　　腥臊并御，芳不得薄兮。\n　　阴阳易位，时不当兮。\n　　怀信佗傺，忽乎吾将行兮！\n\n\n哀郢\n\n　　皇天之不纯命兮，何百姓之震愆？\n　　民离散而相失兮，方仲春而东迁。\n　　去故乡而就远兮，遵江夏以流亡。\n　　出国门而轸怀兮，甲之鼂吾以行。\n　　发郢都而去闾兮，怊荒忽其焉极？\n　　楫齐扬以容与兮，哀见君而不再得。\n　　望长楸而太息兮，涕淫淫其若霰。\n　　过夏首而西浮兮，顾龙门而不见。\n　　心婵媛而伤怀兮，眇不知其所蹠。\n　　顺风波以从流兮，焉洋洋而为客。\n　　凌阳侯之汜滥兮，忽翱翔之焉薄。\n　　心絓结而不解兮，思蹇产而不释。\n　　将运舟而下浮兮，上洞庭而下江。\n　　去终古之所居兮，今逍遥而来东。\n　　羌灵魂之欲归兮，何须臾而忘反。\n　　背夏浦而西思兮，哀故都之日远。\n　　登大坟以远望兮，聊以舒吾忧心。\n　　哀州土之平乐兮，悲江介之遗风。\n　　当陵阳之焉至兮，淼南渡之焉如？\n　　曾不知夏之为丘兮，孰两东门之可芜？\n　　心不怡之长久兮，忧与愁其相接。\n　　惟郢路之辽远兮，江与夏之不可涉。\n　　忽若不信兮，至今九年而不复。\n　　惨郁郁而不通兮，蹇侘傺而含慼。\n　　外承欢之汋约兮，谌荏弱而难持。\n　　忠湛湛而愿进兮，妒被离而鄣之。\n　　尧舜之抗行兮，瞭杳杳而薄天。\n　　众谗人之嫉妒兮，被以不慈之伪名。\n　　憎愠惀之修美兮，好夫人之慷慨。\n　　众踥蹀而日进兮，美超远而逾迈。\n　　乱曰：\n　　曼余目以流观兮，冀一反之何时？\n　　鸟飞反故乡兮，狐死必首丘。\n　　信非吾罪而弃逐兮，何日夜而忘之？\n\n\n抽思\n　　心郁郁之忧思兮，独永叹乎增伤。\n　　思蹇产之不释兮，曼遭夜之方长。\n　　悲秋风之动容兮，何回极之浮浮。\n　　数惟荪之多怒兮，伤余心之忧忧。\n　　愿摇起而横奔兮，览民尤以自镇。\n　　结微情以陈词兮，矫以遗夫美人。\n　　昔君与我诚言兮，曰黄昏以为期。\n　　羌中道而回畔兮，反既有此他志。\n　　憍吾以其美好兮，览余以其修姱。\n　　与余言而不信兮，盖为余而造怒。\n　　愿承閒而自察兮，心震悼而不敢。\n　　悲夷犹而冀进兮，心怛伤之憺憺。\n　　兹历情以陈辞兮，荪详聋而不闻。\n　　固切人之不媚兮，众果以我为患。\n　　初吾所陈之耿著兮，岂至今其庸亡？\n　　何独乐斯之謇謇兮？愿荪美之可光。\n　　望三王以为像兮，指彭咸以为仪。\n　　夫何极而不至兮，故远闻而难亏。\n　　善不由外来兮，名不可以虚作。\n　　孰无施而有报兮，孰不实而有获？\n　　少歌曰：\n　　与美人抽思兮，并日夜而无正。\n　　憍吾以其美好兮，敖朕辞而不听。\n　　倡曰：有鸟自南兮，来集汉北。\n　　好姱佳丽兮，牉独处此异域。\n　　惸茕独而不群兮，又无良媒在其侧。\n　　道卓远而日忘兮，愿自申而不得。\n　　望北山而流涕兮，临流水而太息。\n　　望孟夏之短夜兮，何晦明之若岁？\n　　惟郢路之辽远兮，魂一夕而九逝。\n　　曾不知路之曲直兮，南指月与列星。\n　　愿径逝而未得兮，魂识路之营营。\n　　何灵魂之信直兮，人之心不与吾心同！\n　　理弱而媒不通兮，尚不知余之从容。\n　　乱曰：\n　　长濑湍流，溯江潭兮。\n　　狂顾南行，聊以娱心兮。\n　　轸石崴嵬，蹇吾愿兮。\n　　超回志度，行隐进兮。\n　　低徊夷犹，宿北姑兮。\n　　烦冤瞀容，实沛徂兮。\n　　愁叹苦神，灵遥思兮。\n　　路远处幽，又无行媒兮。\n　　道思作颂，聊以自救兮。\n　　忧心不遂，斯言谁告兮。\n\n\n怀沙\n　　滔滔孟夏兮，草木莽莽。\n　　伤怀永哀兮，汩徂南土。\n　　眴兮杳杳，孔静幽默。\n　　郁结纡轸兮，离慜而长鞠。\n　　抚情效志兮，冤屈而自抑。\n　　刓方以为圜兮，常度未替。\n　　易初本迪兮，君子所鄙。\n　　章画志墨兮，前图未改。\n　　内厚质正兮，大人所盛。\n　　巧倕不斲兮，孰察其拨正。\n　　玄文处幽兮，矇瞍谓之不章；\n　　离娄微睇兮，瞽以为无明。\n　　变白以为黑兮，倒上以为下。\n　　凤皇在笯兮，鸡鹜翔舞。\n　　同糅玉石兮，一概而相量。\n　　夫惟党人之鄙固兮，羌不知余之所臧。\n　　任重载盛兮，陷滞而不济。\n　　怀瑾握瑜兮，穷不知所示。\n　　邑犬之群吠兮，吠所怪也。\n　　非俊疑杰兮，固庸态也。\n　　文质疏内兮，众不知余之异采。\n　　材朴委积兮，莫知余之所有。\n　　重仁袭义兮，谨厚以为丰。\n　　重华不可遌兮，孰知余之从容！\n　　古固有不并兮，岂知其何故也？\n　　汤禹久远兮，邈而不可慕也？\n　　惩违改忿兮，抑心而自强。\n　　离慜而不迁兮，愿志之有像。\n　　进路北次兮，日昧昧其将暮。\n　　舒忧娱哀兮，限之以大故。\n　　乱曰：\n　　浩浩沅湘，分流汩兮。\n　　修路幽蔽，道远忽兮。\n　　怀质抱情，独无匹兮。\n　　伯乐既没，骥焉程兮。\n　　民生禀命，各有所错兮。\n　　定心广志，余何所畏惧兮？\n　　曾伤爰哀，永叹喟兮。\n　　世浑浊莫吾知，人心不可谓兮。\n　　知死不可让，愿勿爱兮。\n　　明告君子，吾将以为类兮。\n\n\n思美人\n　　思美人兮，揽涕而竚眙。\n　　媒绝路阻兮，言不可结而诒。\n　　蹇蹇之烦冤兮，陷滞而不发。\n　　申旦以舒中情兮，志沉菀而莫达。\n　　愿寄言于浮云兮，遇丰隆而不将。\n　　因归鸟而致辞兮，羌迅高而难当。\n　　高辛之灵盛兮，遭玄鸟而致诒。\n　　欲变节以从俗兮，媿易初而屈志。\n　　独历年而离愍兮，羌凭心犹未化。\n　　宁隐闵而寿考兮，何变易之可为！\n　　知前辙之不遂兮，未改此度。\n　　车既覆而马颠兮，蹇独怀此异路。\n　　勒骐骥而更驾兮，造父为我操之，\n　　迁逡次而勿驱兮，聊假日以须是时。\n　　指嶓冢之西隈兮，与纁黄以为期。\n　　开春发岁兮，白日出之悠悠。\n　　吾将荡志而愉乐兮，遵江夏以娱忧。\n　　揽大薄之芳茝兮，搴长洲之宿莽。\n　　惜吾不及古人兮，吾谁与玩此芳草？\n　　解萹薄与杂菜兮，备以为交佩。\n　　佩缤纷以缭转兮，遂萎绝而离异。\n　　吾且儃徊以娱忧兮，观南人之变态。\n　　窃快在中心兮，扬厥凭而不竢。\n　　芳与泽其杂糅兮，羌芳华自中出。\n　　纷郁郁其远蒸兮，满内而外扬。\n　　情与质信可保兮，羌居蔽而闻章。\n　　令薜荔以为理兮，惮举趾而缘木。\n　　因芙蓉而为媒兮，惮褰裳而濡足。\n　　登高吾不说兮，入下吾不能。\n　　固朕形之不服兮，然容与而狐疑。\n　　广遂前画兮，未改此度也。\n　　命则处幽吾将罢兮，愿及白日之未暮也。\n　　独茕茕而南行兮，思彭咸之故也。\n\n\n惜往日\n　　惜往日之曾信兮，受命诏以昭时。\n　　奉先功以照下兮，明法度之嫌疑。\n　　国富强而法立兮，属贞臣而日竢。\n　　秘密事之载心兮，虽过失犹弗治。\n　　心纯庞而不泄兮，遭谗人而嫉之。\n　　君含怒而待臣兮，不清澈其然否。\n　　蔽晦君之聪明兮，虚惑误又以欺。\n　　弗参验以考实兮，远迁臣而弗思。\n　　信谗谀之浑浊兮，盛气志而过之。\n　　何贞臣之无罪兮，被离谤而见尤。\n　　惭光景之诚信兮，身幽隐而备之。\n　　临沅湘之玄渊兮，遂自忍而沉流。\n　　卒没身而绝名兮，惜壅君之不昭。\n　　君无度而弗察兮，使芳草为薮幽。\n　　焉舒情而抽信兮，恬死亡而不聊。\n　　独障壅而弊隐兮，使贞臣为无由。\n　　闻百里之为虏兮，伊尹烹于庖厨。\n　　吕望屠于朝歌兮，宁戚歌而饭牛。\n　　不逢汤武与桓缪兮，世孰云而知之。\n　　吴信谗而弗味兮，子胥死而后忧。\n　　介子忠而立枯兮，文君寤而追求。\n　　封介山而为之禁兮，报大德之优游。\n　　思久故之亲身兮，因缟素而哭之。\n　　或忠信而死节兮，或訑谩而不疑。\n　　弗省察而按实兮，听谗人之虚辞。\n　　芳与泽其杂糅兮，孰申旦而别之？\n　　何芳草之早殀兮，微霜降而下戒。\n　　谅聪不明而蔽壅兮，使谗谀而日得。\n　　自前世之嫉贤兮，谓蕙若其不可佩。\n　　妒佳冶之芬芳兮，嫫母姣而自好。\n　　虽有西施之美容兮，谗妒入以自代。\n　　愿陈情以白行兮，得罪过之不意。\n　　情冤见之日明兮，如列宿之错置。\n　　乘骐骥而驰骋兮，无辔衔而自载；\n　　乘泛泭以下流兮，无舟楫而自备。\n　　背法度而心治兮，辟与此其无异。\n　　宁溘死而流亡兮，恐祸殃之有再。\n　　不毕辞而赴渊兮，惜壅君之不识。\n\n\n橘颂\n　　后皇嘉树，橘徕服兮。\n　　受命不迁，生南国兮。\n　　深固难徙，更壹志兮。\n　　绿叶素荣，纷其可喜兮。\n　　曾枝剡棘，圆果抟兮。\n　　青黄杂糅，文章烂兮。\n　　精色内白，类任道兮。\n　　纷緼宜修，姱而不丑兮。\n　　嗟尔幼志，有以异兮。\n　　独立不迁，岂不可喜兮？\n　　深固难徙，廓其无求兮。\n　　苏世独立，横而不流兮。\n　　闭心自慎，终不失过兮。\n　　秉德无私，参天地兮。\n　　愿岁并谢，与长友兮。\n　　淑离不淫，梗其有理兮。\n　　年岁虽少，可师长兮。\n　　行比伯夷，置以为像兮。\n\n\n悲回风\n　　悲回风之摇蕙兮，心冤结而内伤。\n　　物有微而陨性兮，声有隐而先倡。\n　　夫何彭咸之造思兮，暨志介而不忘！\n　　万变其情岂可盖兮，孰虚伪之可长？\n　　鸟兽鸣以号群兮，草苴比而不芳。\n　　鱼葺鳞以自别兮，蛟龙隐其文章。\n　　故荼荠不同亩兮，兰茝幽而独芳。\n　　惟佳人之永都兮，更统世以自贶。\n　　眇远志之所及兮，怜浮云之相羊。\n　　介眇志之所惑兮，窃赋诗之所明。\n　　惟佳人之独怀兮，折若椒以自处。\n　　曾歔欷之嗟嗟兮，独隐伏而思虑。\n　　涕泣交而凄凄兮，思不眠以至曙。\n　　终长夜之曼曼兮，掩此哀而不去。\n　　寤从容以周流兮，聊逍遥以自恃。\n　　伤太息之愍怜兮，气于邑而不可止。\n　　糺思心以为纕兮，编愁苦以为膺。\n　　折若木以弊光兮，随飘风之所仍。\n　　存彷佛而不见兮，心踊跃其若汤。\n　　抚珮衽以案志兮，超惘惘而遂行。\n　　岁曶曶其若颓兮，时亦冉冉而将至。\n　　薠蘅槁而节离兮，芳以歇而不比。\n　　怜思心之不可惩兮，证此言之不可聊。\n　　宁溘死而流亡兮，不忍此心之常愁。\n　　孤子吟而抆泪兮，放子出而不还。\n　　孰能思而不隐兮，照彭咸之所闻。\n　　登石峦以远望兮，路眇眇之默默。\n　　入景响之无应兮，闻省想而不可得。\n　　愁郁郁之无快兮，居戚戚而不可解。\n　　心鞿羁而不开兮，气缭转而自缔。\n　　穆眇眇之无垠兮，莽芒芒之无仪。\n　　声有隐而相感兮，物有纯而不可为。\n　　邈漫漫之不可量兮，缥绵绵之不可纡。\n　　愁悄悄之常悲兮，翩冥冥之不可娱。\n　　凌大波而流风兮，讬彭咸之所居。\n　　上高岩之峭岸兮，处雌蜺之标颠。\n　　据青冥而摅虹兮，遂儵忽而扪天。\n　　吸湛露之浮源兮，漱凝霜之雰雰。\n　　依风穴以自息兮，忽倾寤以婵媛。\n　　冯昆仑以澂雾兮，隐渂山以清江。\n　　惮涌湍之礚礚兮，听波声之汹汹。\n　　纷容容之无经兮，罔芒芒之无纪。\n　　轧洋洋之无从兮，驰委移之焉止？\n　　漂翻翻其上下兮，翼遥遥其左右。\n　　氾潏潏其前后兮，伴张驰之信期。\n　　观炎气之相仍兮，窥烟液之所积。\n　　悲霜雪之俱下兮，听潮水之相击。\n　　借光景以往来兮，施黄棘之枉策。\n　　求介子之所存兮，见伯夷之放迹。\n　　心调度而弗去兮，刻著志之无适。\n　　曰吾怨往昔之所冀兮，悼来者之悐悐。\n　　浮江淮而入海兮，从子胥而自适。\n　　望大河之洲渚兮，悲申徒之抗迹。\n　　骤谏君而不听兮，重任石之何益？\n　　心絓结而不解兮，思蹇产而不释。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九章' AND p.poem_author = '屈原';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题画兰', '郑燮', '清代', '身在千山顶上头，突岩深缝妙香稠。\n非无脚下浮云闹，来不相知去不留。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题画兰' AND p.poem_author = '郑燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('召公谏厉王弭谤', '佚名', '先秦', '厉王虐，国人谤王。召公告曰：“民不堪命矣！”王怒，得卫巫，使监谤者。以告，则杀之。国人莫敢言，道路以目。\n　　王喜，告召公曰：“吾能弭谤矣，乃不敢言。”召公曰：“是鄣之也。防民之口，甚于防川；川雍而溃，伤人必多。民亦如之。是故为川者，决之使导；为民者，宣之使言。故天子听政，使公卿至于列士献诗，瞽献曲，史献书，师箴，瞍赋，朦诵，百工谏，庶人传语，近臣尽规，亲戚补察，瞽、史教诲，耆艾修之，而后王斟酌焉。是以事行而不悖。民之有口也，犹土之有山川也，财用于是乎出；犹其有原隰衍沃也，衣食于是乎生。口之宣言也，善败于是乎兴。行善而备败，所以阜财用衣食者也。夫民虑之于心，而宣之于口，成而行之，胡可壅也？若壅其口，其与能几何？”\n　　王弗听，于是国人莫敢出言。三年，乃流王于彘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '召公谏厉王弭谤' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉楼春·己卯岁元日', '毛滂', '宋代', '一年滴尽莲花漏。碧井酴酥沉冻酒。晓寒料峭尚欺人，春态苗条先到柳。 \n佳人重劝千长寿。柏叶椒花芬翠袖。醉乡深处少相知，只与东君偏故旧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉楼春·己卯岁元日' AND p.poem_author = '毛滂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄河', '罗隐', '唐代', '莫把阿胶向此倾，此中天意固难明。\n解通银汉应须曲，才出昆仑便不清。\n高祖誓功衣带小，仙人占斗客槎轻。\n三千年后知谁在？何必劳君报太平！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄河' AND p.poem_author = '罗隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄李十二白二十韵', '杜甫', '唐代', '昔年有狂客，号尔谪仙人。\n笔落惊风雨，诗成泣鬼神。\n声名从此大，汩没一朝伸。\n文采承殊渥，流传必绝伦。\n龙舟移棹晚，兽锦夺袍新。\n白日来深殿，青云满后尘。\n乞归优诏许，遇我宿心亲。\n未负幽栖志，兼全宠辱身。\n剧谈怜野逸，嗜酒见天真。\n醉舞梁园夜，行歌泗水春。\n才高心不展，道屈善无邻。\n处士祢衡俊，诸生原宪贫。\n稻粱求未足，薏苡谤何频。\n五岭炎蒸地，三危放逐臣。\n几年遭鵩鸟，独泣向麒麟。\n苏武先还汉，黄公岂事秦。\n楚筵辞醴日，梁狱上书辰。\n已用当时法，谁将此义陈。\n老吟秋月下，病起暮江滨。\n莫怪恩波隔，乘槎与问津。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄李十二白二十韵' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送杜十四之江南 / 送杜晃进士之东吴', '孟浩然', '唐代', '荆吴相接水为乡，君去春江正淼茫。(\n\'淼\'茫 同：渺)\n日暮征帆何处泊，天涯一望断人肠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送杜十四之江南 / 送杜晃进士之东吴' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饯别王十一南游', '刘长卿', '唐代', '望君烟水阔，挥手泪沾巾。\n飞鸟没何处，青山空向人。\n长江一帆远，落日五湖春。\n谁见汀洲上，相思愁白蘋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饯别王十一南游' AND p.poem_author = '刘长卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('月儿弯弯照九州', '佚名', '宋代', '月儿弯弯照九州，几家欢乐几家愁。\n几家夫妇同罗帐，几个飘零在外头？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '月儿弯弯照九州' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('叠题乌江亭', '王安石', '宋代', '百战疲劳壮士哀，中原一败势难回。\n江东子弟今虽在，肯与君王卷土来？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '叠题乌江亭' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南歌子·荷盖倾新绿', '程垓', '宋代', '荷盖倾新绿，榴巾蹙旧红。水亭烟榭晚凉中。又是一钩新月、静方栊。 \n丝藕清如雪，橱纱薄似空。好维今夜与谁同。唤取玉人来共、一帘风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南歌子·荷盖倾新绿' AND p.poem_author = '程垓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水龙吟·甲辰岁寿韩南涧尚书', '辛弃疾', '宋代', '渡江天马南来，几人真是经纶手。长安父老，新亭风景，可怜依旧。夷甫诸人，神州沉陆，几曾回首。算平戎万里，功名本是，真儒事、君知否。(君知否 一作：公知否) \n况有文章山斗。对桐阴、满庭清昼。当年堕地，而今试看，风云奔走。绿野风烟，平泉草木，东山歌酒。待他年，整顿乾坤事了，为先生寿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水龙吟·甲辰岁寿韩南涧尚书' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('孤雁儿·藤床纸帐朝眠起', '李清照', '宋代', '世人作梅词，下笔便俗。予试作一篇，乃知前言不妄耳。\n\n藤床纸帐朝眠起，说不尽无佳思。沈香断续玉炉寒，伴我情怀如水。笛声三弄，梅心惊破，多少春情意。 \n小风疏雨萧萧地，又催下千行泪。吹箫人去玉楼空，肠断与谁同倚。一枝折得，人间天上，没个人堪寄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '孤雁儿·藤床纸帐朝眠起' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('摸鱼儿·东皋寓居', '晁补之', '宋代', '买陂塘、旋栽杨柳，依稀淮岸江浦。东皋嘉雨新痕涨，沙觜鹭来鸥聚。堪爱处最好是、一川夜月光流渚。无人独舞。任翠幄张天，柔茵藉地，酒尽未能去。 \n青绫被，莫忆金闺故步。儒冠曾把身误。弓刀千骑成何事，荒了邵平瓜圃。君试觑。满青镜、星星鬓影今如许。功名浪语。便似得班超，封侯万里，归计恐迟暮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '摸鱼儿·东皋寓居' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春草', '唐彦谦', '唐代', '天北天南绕路边，托根无处不延绵。\n萋萋总是无情物，吹绿东风又一年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春草' AND p.poem_author = '唐彦谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蜀先主庙', '刘禹锡', '唐代', '天地英雄气，千秋尚凛然。势分三足鼎，业复五铢钱。 \n得相能开国，生儿不象贤。凄凉蜀故妓，来舞魏宫前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蜀先主庙' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饮马长城窟行', '李世民', '唐代', '塞外悲风切，交河冰已结。瀚海百重波，阴山千里雪。 \n迥戍危烽火，层峦引高节。悠悠卷旆旌，饮马出长城。 \n寒沙连骑迹，朔吹断边声。胡尘清玉塞，羌笛韵金钲。 \n绝漠干戈戢，车徒振原隰。都尉反龙堆，将军旋马邑。 \n扬麾氛雾静，纪石功名立。荒裔一戎衣，灵台凯歌入。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饮马长城窟行' AND p.poem_author = '李世民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋波媚·七月十六日晚登高兴亭望长安南山', '陆游', '宋代', '秋到边城角声哀，烽火照高台。悲歌击筑，凭高酹酒，此兴悠哉。\n多情谁似南山月，特地暮云开。灞桥烟柳，曲江池馆，应待人来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋波媚·七月十六日晚登高兴亭望长安南山' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青门引·春思', '张先', '宋代', '乍暖还轻冷。风雨晚来方定。庭轩寂寞近清明，残花中酒，又是去年病。 \n楼头画角风吹醒。入夜重门静。那堪更被明月，隔墙送过秋千影。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青门引·春思' AND p.poem_author = '张先';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵图' AND p.poem_author = '韦庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠妓云英 / 嘲钟陵妓云英', '罗隐', '唐代', '钟陵醉别十余春，重见云英掌上身。\n我未成名卿未嫁，可能俱是不如人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠妓云英 / 嘲钟陵妓云英' AND p.poem_author = '罗隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('矛与盾', '韩非', '先秦', '楚人有鬻盾与矛者，誉之曰：“ 吾盾之坚 ， 物莫能陷也 。”又誉其矛曰：“ 吾矛之利 ， 于物无不陷也 。”或曰：“以子之矛，陷子之盾，何如 ？” 其人弗能应也 。夫不可陷之盾与无不陷之矛，不可同世而立。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '矛与盾' AND p.poem_author = '韩非';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王冕好学', '宋濂', '明代', '王冕者，诸暨人。七八岁时，父命牧牛陇上，窃入学舍，听诸生诵书；听已，辄默记。暮归，忘其牛。或牵牛来责蹊田者。父怒，挞之，已而复如初。母曰：“儿痴如此，曷不听其所为？”冕因去，依僧寺以居。夜潜出，坐佛膝上，执策映长明灯读之，琅琅达旦。佛像多土偶，狞恶可怖；冕小儿，恬若不见。\n\n　　安阳韩性闻而异之,录为弟子,学遂为通儒。 性卒，门人事冕如事性。时冕父已卒，即迎母入越城就养。久之，母思还故里，冕买白牛驾母车，自被古冠服随车后。乡里儿竞遮道讪笑，冕亦笑。选自《元史·王冕传》', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王冕好学' AND p.poem_author = '宋濂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·醉拍春衫惜旧香', '晏几道', '宋代', '醉拍春衫惜旧香。天将离恨恼疏狂。年年陌上生秋草，日日楼中到夕阳。 \n云渺渺，水茫茫。征人归路许多长。相思本是无凭语，莫向花笺费泪行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·醉拍春衫惜旧香' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青青河畔草', '佚名', '两汉', '青青河畔草，郁郁园中柳。\n盈盈楼上女，皎皎当窗牖。\n娥娥红粉妆，纤纤出素手。\n昔为倡家女，今为荡子妇。\n荡子行不归，空床难独守。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青青河畔草' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏为六绝句', '杜甫', '唐代', '庾信文章老更成，凌云健笔意纵横。\n今人嗤点流传赋，不觉前贤畏后生。\n\n王杨卢骆当时体，轻薄为文哂未休。\n尔曹身与名俱灭，不废江河万古流。\n\n纵使卢王操翰墨，劣于汉魏近风骚。\n龙文虎脊皆君驭，历块过都见尔曹。\n\n才力应难夸数公，凡今谁是出群雄。\n或看翡翠兰苕上，未掣鲸鱼碧海中。\n\n不薄今人爱古人，清词丽句必为邻。\n窃攀屈宋宜方驾，恐与齐梁作后尘。\n\n未及前贤更勿疑，递相祖述复先谁。\n别裁伪体亲风雅，转益多师是汝师。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏为六绝句' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晁错论', '苏轼', '宋代', '天下之患，最不可为者，名为治平无事，而其实有不测之忧。坐观其变，而不为之所，则恐至於不可救；起而强为之，则天下狃於治平之安而不吾信。惟仁人君子豪杰之士，为能出身为天下犯大难，以求成大功；此固非勉强期月之间，而苟以求名之所能也。\n\n　　天下治平，无故而发大难之端；吾发之，吾能收之，然后有辞於天下。事至而循循焉欲去之，使他人任其责，则天下之祸，必集於我。\n\n　　昔者晁错尽忠为汉，谋弱山东之诸侯，山东诸侯并起，以诛错为名；而天子不以察，以错为之说。天下悲错之以忠而受祸，不知错有以取之也。\n\n　　古之立大事者，不惟有超世之才，亦必有坚忍不拔之志。昔禹之治水，凿龙门，决大河而放之海。方其功之未成也，盖亦有溃冒冲突可畏之患；惟能前知其当然，事至不惧，而徐为之图，是以得至於成功。\n\n　　夫以七国之强，而骤削之，其为变，岂足怪哉？错不於此时捐其身，为天下当大难之冲，而制吴楚之命，乃为自全之计，欲使天子自将而己居守。且夫发七国之难者，谁乎？己欲求其名，安所逃其患。以自将之至危，与居守至安；己为难首，择其至安，而遣天子以其至危，此忠臣义士所以愤怨而不平者也。\n\n　　当此之时，虽无袁盎，错亦未免於祸。何者？己欲居守，而使人主自将。以情而言，天子固已难之矣，而重违其议。是以袁盎之说，得行於其间。使吴楚反，错已身任其危，日夜淬砺，东向而待之，使不至於累其君，则天子将恃之以为无恐，虽有百盎，可得而间哉？\n\n　　嗟夫！世之君子，欲求非常之功，则无务为自全之计。使错自将而讨吴楚，未必无功，惟其欲自固其身，而天子不悦。奸臣得以乘其隙，错之所以自全者，乃其所以自祸欤！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晁错论' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('周郑交质', '左丘明', '先秦', '郑武公、庄公为平王卿士。王贰于虢，郑伯怨王。王曰：“无之。”故周郑交质。王子狐为质于郑，郑公子忽为质于周。\n\n　　王崩，周人将畀虢公政。四月，郑祭足帅师取温之麦。秋，又取成周之禾。周郑交恶。\n\n　　君子曰：“信不由中，质无益也。明恕而行，要之以礼，虽无有质，谁能间之？苟有明信，涧溪沼沚之毛，苹蘩蕴藻之菜，筐筥錡釜之器，潢污行潦之水，可荐於鬼神，可羞於王公，而况君子结二国之信，行之以礼，又焉用质？《风》有《采蘩》、《采苹》，《雅》有《行苇》、《泂酌》，昭忠信也。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '周郑交质' AND p.poem_author = '左丘明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望阙台', '戚继光', '明代', '十年驱驰海色寒，孤臣于此望宸銮。\n繁霜尽是心头血，洒向千峰秋叶丹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望阙台' AND p.poem_author = '戚继光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('摸鱼儿·问莲根有丝多少', '元好问', '金朝', '泰和中，大名民家小儿女，有以私情不如意赴水者，官为踪迹之，无见也。其后踏藕者得二尸水中，衣服仍可验，其事乃白。是岁此陂荷花开，无不并蒂者。沁水梁国用，时为录事判官，为李用章内翰言如此。此曲以乐府《双蕖怨》命篇。“咀五色之灵芝，香生九窍；咽三危之瑞露，春动七情”，韩偓《香奁集》中自序语。\n\n　　问莲根、有丝多少，莲心知为谁苦？双花脉脉娇相向，只是旧家儿女。天已许。甚不教、白头生死鸳鸯浦？夕阳无语。算谢客烟中，湘妃江上，未是断肠处。\n\n　　香奁梦，好在灵芝瑞露。人间俯仰今古。海枯石烂情缘在，幽恨不埋黄土。相思树，流年度，无端又被西风误。兰舟少住。怕载酒重来，红衣半落，狼藉卧风雨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '摸鱼儿·问莲根有丝多少' AND p.poem_author = '元好问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·元夕有所梦', '姜夔', '宋代', '肥水东流无尽期。当初不合种相思。梦中未比丹青见，暗里忽惊山鸟啼。\n春未绿，鬓先丝。人间别久不成悲。谁教岁岁红莲夜，两处沉吟各自知。(沉 通：沈)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·元夕有所梦' AND p.poem_author = '姜夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红·中秋寄远', '辛弃疾', '宋代', '快上西楼，怕天放、浮云遮月。但唤取、玉纤横管，一声吹裂。谁做冰壶凉世界，最怜玉斧修时节。问嫦娥、孤令有愁无？应华发。\n云液满，琼杯滑。长袖起，清歌咽。叹十常八九，欲磨还缺。但愿长圆如此夜，人情未必看承别。把从前、离恨总成欢，归时说。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红·中秋寄远' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登池上楼', '谢灵运', '南北朝', '潜虬媚幽姿，飞鸿响远音。 \n薄霄愧云浮，栖川怍渊沉。\n进德智所拙，退耕力不任。\n徇禄反穷海，卧疴对空林。\n衾枕昧节候，褰开暂窥临。\n倾耳聆波澜，举目眺岖嵚。\n初景革绪风，新阳改故阴。\n池塘生春草，园柳变鸣禽。\n祁祁伤豳歌，萋萋感楚吟。\n索居易永久，离群难处心。\n持操岂独古，无闷征在今。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登池上楼' AND p.poem_author = '谢灵运';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鵩鸟赋', '贾谊', '两汉', '谊为长沙王傅三年，有鵩飞入谊舍。鵩似鸮，不祥鸟也。谊即以谪居长沙，长沙卑湿，谊自伤悼，以为寿不得长，乃为赋以自广也。其辞曰：\n\n　　单阏之岁兮，四月孟夏，庚子日斜兮，鵩集予舍。止于坐隅兮，貌甚闲暇。异物来萃兮，私怪其故。发书占之兮，谶言其度，曰：“野鸟入室兮，主人将去。”请问于鵩兮：“予去何之？吉乎告我，凶言其灾。淹速之度兮，语予其期。”鵩乃叹息，举首奋翼；口不能言，请对以臆：\n\n　　“万物变化兮，固无休息。斡流而迁兮，或推而还。形气转续兮，变化而蟺。沕穆无穷兮，胡可胜言！祸兮福所依，福兮祸所伏；忧喜聚门兮，吉凶同域。彼吴强大兮，夫差以败；越栖会稽兮，勾践霸世。斯游遂成兮，卒被五刑；傅说胥靡兮，乃相武丁。夫祸之与福兮，何异纠纆；命不可说兮，孰知其极！水激则旱兮，矢激则远；万物回薄兮，振荡相转。云蒸雨降兮，纠错相纷；大钧播物兮，坱圠无垠。天不可预虑兮，道不可预谋；迟速有命兮，焉识其时。\n\n　　且夫天地为炉兮，造化为工；阴阳为炭兮，万物为铜。合散消息兮，安有常则？千变万化兮，未始有极，忽然为人兮，何足控抟；化为异物兮，又何足患！小智自私兮，贱彼贵我；达人大观兮，物无不可。贪夫殉财兮，烈士殉名。夸者死权兮，品庶每生。怵迫之徒兮，或趋西东；大人不曲兮，意变齐同。愚士系俗兮，窘若囚拘；至人遗物兮，独与道俱。众人惑惑兮，好恶积亿；真人恬漠兮，独与道息。释智遗形兮，超然自丧；寥廓忽荒兮，与道翱翔。乘流则逝兮，得坻则止；纵躯委命兮，不私与己。其生兮若浮，其死兮若休；澹乎若深渊止之静，泛乎若不系之舟。不以生故自宝兮，养空而浮；德人无累兮，知命不忧。细故蒂芥兮，何足以疑！”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鵩鸟赋' AND p.poem_author = '贾谊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭李商隐', '崔珏', '唐代', '成纪星郎字义山，适归高壤抱长叹。\n词林枝叶三春尽，学海波澜一夜干。\n风雨已吹灯烛灭，姓名长在齿牙寒。\n只应物外攀琪树，便著霓裳上绛坛。\n\n虚负凌云万丈才，一生襟抱未曾开。\n鸟啼花落人何在，竹死桐枯凤不来。\n良马足因无主踠，旧交心为绝弦哀。\n九泉莫叹三光隔，又送文星入夜台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭李商隐' AND p.poem_author = '崔珏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('如梦令·正是辘轳金井', '纳兰性德', '清代', '正是辘轳金井，满砌落花红冷。蓦地一相逢，心事眼波难定。谁省，谁省。从此簟纹灯影。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '如梦令·正是辘轳金井' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风赋', '宋玉', '先秦', '楚襄王游于兰台之宫，宋玉景差侍。有风飒然而至，王乃披襟而当之，曰：“快哉此风！寡人所与庶人共者邪？”宋玉对曰：“此独大王之风耳，庶人安得而共之！”\n\n　　王曰：“夫风者，天地之气，溥畅而至，不择贵贱高下而加焉。今子独以为寡人之风，岂有说乎？”宋玉对曰：“臣闻于师：枳句来巢，空穴来风。其所托者然，则风气殊焉。”\n\n　　王曰：“夫风始安生哉？”宋玉对曰：“夫风生于地，起于青苹之末。侵淫溪谷，盛怒于土囊之口。缘太山之阿，舞于松柏之下，飘忽淜滂，激飏熛怒。耾耾雷声，回穴错迕。蹶石伐木，梢杀林莽。至其将衰也，被丽披离，冲孔动楗，眴焕粲烂，离散转移。故其清凉雄风，则飘举升降。乘凌高城，入于深宫。抵华叶而振气，徘徊于桂椒之间，翱翔于激水之上。将击芙蓉之精。猎蕙草，离秦衡，概新夷，被荑杨，回穴冲陵，萧条众芳。然后徜徉中庭，北上玉堂，跻于罗帏，经于洞房，乃得为大王之风也。故其风中人状，直惨凄惏栗，清凉增欷。清清泠泠，愈病析酲，发明耳目，宁体便人。此所谓大王之雄风也。”\n\n　　王曰：“善哉论事！夫庶人之风，岂可闻乎？”宋玉对曰：“夫庶人之风，塕然起于穷巷之间，堀堁扬尘，勃郁烦冤，冲孔袭门。动沙堁，吹死灰，骇溷浊，扬腐余，邪薄入瓮牖，至于室庐。故其风中人状，直憞溷郁邑，殴温致湿，中心惨怛，生病造热。中唇为胗，得目为篾，啖齰嗽获，死生不卒。此所谓庶人之雌风也。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风赋' AND p.poem_author = '宋玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凉州词', '薛逢', '唐代', '昨夜蕃兵报国仇，沙州都护破凉州。\n黄河九曲今归汉，塞外纵横战血流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凉州词' AND p.poem_author = '薛逢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('微雨夜行', '白居易', '唐代', '漠漠秋云起，稍稍夜寒生。\n但觉衣裳湿，无点亦无声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '微雨夜行' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归雁', '杜甫', '唐代', '东来万里客，乱定几年归？\n肠断江城雁，高高向北飞！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归雁' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('应诏赋得除夜', '史青', '唐代', '今岁今宵尽，明年明日催。\n寒随一夜去，春逐五更来。\n气色空中改，容颜暗里回。\n风光人不觉，已著后园梅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '应诏赋得除夜' AND p.poem_author = '史青';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('论语七则', '佚名', '先秦', '子曰:“吾十有五而志于学，三十而立，四十而不惑，五十而知天命，六十而耳顺，七十而从心所欲，不踰矩。”(踰 同：逾)\n\n　　子曰：“君子食无求饱，居无求安，敏于事而慎于言，就有道而正焉，可谓好学也已。”\n\n　　子曰：“饭疏食，饮水，曲肱而枕之，乐亦在其中矣。不义而富且贵，于我如浮云。”\n\n　　子曰：“衣敝緼袍，与衣狐貉者立，而不耻者，其由也与!”“不忮不求，何用不臧?”子路终身诵之。子曰：“是道也，何足以臧?”\n\n　　子貢問為仁。子曰：“工欲善其事，必先利其器。居是邦也，事其大夫之賢者，友其士之仁者。”《論語?衛靈公》\n\n　　子贡问曰：“乡人皆好之，何如？”子曰：“未可也。”“乡人皆恶之，何如？”子曰：“未可也。不如乡人之善者好之，其不善者恶之。”\n\n　　子谓子贡曰，“女与回也孰愈？”对曰，“赐也何敢望回？回也闻一以知十，赐也闻一以知二。”子曰，“弗如也，吾与女弗如也。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '论语七则' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读山海经·其一', '陶渊明', '魏晋', '孟夏草木长，绕屋树扶疏。 \n众鸟欣有托，吾亦爱吾庐。 \n既耕亦已种，时还读我书。 \n穷巷隔深辙，颇回故人车。 \n欢言酌春酒，摘我园中蔬。 \n微雨从东来，好风与之俱。 \n泛览《周王传》，流观《山海》图。 \n俯仰终宇宙，不乐复何如？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读山海经·其一' AND p.poem_author = '陶渊明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('圆圆曲', '吴伟业', '清代', '鼎湖当日弃人间，破敌收京下玉关。恸哭六军俱缟素，冲冠一怒为红颜。红颜流落非吾恋，逆贼天亡自荒宴。电扫黄巾定黑山，哭罢君亲再相见。\n\n　　相见初经田窦家，侯门歌舞出如花。许将戚里箜篌伎，等取将军油壁车。家本姑苏浣花里，圆圆小字娇罗绮。梦向夫差苑里游，宫娥拥入君王起。前身合是采莲人，门前一片横塘水。横塘双桨去如飞，何处豪家强载归。此际岂知非薄命，此时唯有泪沾衣。薰天意气连宫掖，明眸皓齿无人惜。夺归永巷闭良家，教就新声倾坐客。坐客飞觞红日暮，一曲哀弦向谁诉？白晳通侯最少年，拣取花枝屡回顾。早携娇鸟出樊笼，待得银河几时渡？恨杀军书抵死催，苦留后约将人误。相约恩深相见难，一朝蚁贼满长安。可怜思妇楼头柳，认作天边粉絮看。遍索绿珠围内第，强呼绛树出雕阑。若非壮士全师胜，争得蛾眉匹马还？\n\n　　蛾眉马上传呼进，云鬟不整惊魂定。蜡炬迎来在战场，啼妆满面残红印。专征萧鼓向秦川，金牛道上车千乘。斜谷云深起画楼，散关月落开妆镜。传来消息满江乡，乌桕红经十度霜。教曲伎师怜尚在，浣纱女伴忆同行。旧巢共是衔泥燕，飞上枝头变凤凰。长向尊前悲老大，有人夫婿擅侯王。当时只受声名累，贵戚名豪竞延致。一斛明珠万斛愁，关山漂泊腰肢细。错怨狂风飏落花，无边春色来天地。\n\n　　尝闻倾国与倾城，翻使周郎受重名。妻子岂应关大计，英雄无奈是多情。全家白骨成灰土，一代红妆照汗青。君不见，馆娃初起鸳鸯宿，越女如花看不足。香径尘生乌自啼，屧廊人去苔空绿。换羽移宫万里愁，珠歌翠舞古梁州。为君别唱吴宫曲，汉水东南日夜流！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '圆圆曲' AND p.poem_author = '吴伟业';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('念奴娇·登多景楼', '陈亮', '宋代', '危楼还望，叹此意、今古几人曾会？鬼设神施，浑认作、天限南疆北界。一水横陈，连岗三面，做出争雄势。六朝何事，只成门户私计？\n因笑王谢诸人，登高怀远，也学英雄涕。凭却长江，管不到，河洛腥膻无际。正好长驱，不须反顾，寻取中流誓。小儿破贼，势成宁问强对！(强对 一作：疆场)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '念奴娇·登多景楼' AND p.poem_author = '陈亮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春晓', '陆龟蒙', '唐代', '春庭晓景别，清露花逦迤。\n黄蜂一过慵，夜夜栖香蕊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春晓' AND p.poem_author = '陆龟蒙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋思', '李白', '唐代', '燕支黄叶落，妾望自登台。海上碧云断，单于秋色来。\n胡兵沙塞合，汉使玉关回。征客无归日，空悲蕙草摧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋思' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长歌行', '李泌', '唐代', '天覆吾，地载吾，天地生吾有意无。\n不然绝粒升天衢，不然鸣珂游帝都。\n焉能不贵复不去，空作昂藏一丈夫。\n一丈夫兮一丈夫，千生气志是良图。\n请君看取百年事，业就扁舟泛五湖', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长歌行' AND p.poem_author = '李泌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('曾国藩诫子书', '曾国藩', '清代', '余通籍三十余年，官至极品，而学业一无所成，德行一无许可，老大徒伤，不胜悚惶惭赧。今将永别，特将四条教汝兄弟。\n\n　　一曰慎独而心安。自修之道，莫难于养心；养心之难，又在慎独。能慎独，册内省不疚，可以对天地质鬼神。人无一内愧之事，则天君泰然。此心常快足宽平，是人生第一自强之道，第一寻乐之方，守身之先务也。\n\n　　二曰主敬则身强。内而专静纯一，外而整齐严肃。敬之工夫也；出门如见大宾，使民如承大祭，敬之气象也；修己以安百姓，笃恭而天下平，敬之效验也。聪明睿智，皆由此出。庄敬日强，安肆日偷。若人无众寡，事无大小，一一恭敬，不敢怠慢。则身强之强健，又何疑乎？\n\n　　三曰求仁则人悦。凡人之生，皆得天地之理以成性，得天地之气以成形，我与民物，其大本乃同出一源。若但知私己而不知仁民爱物，是于大本一源之道已悖而失之矣。至于尊官厚禄，高居人上，则有拯民溺救民饥之责。读书学古，粗知大义，既有觉后知觉后觉之责。孔门教人，莫大于求仁，而其最切者，莫要于欲立立人、欲达达人数语。立人达人之人，人有不悦而归之者乎？\n\n　　四曰习劳则神钦。人一日所着之衣所进之食，与日所行之事所用之力相称，则旁人韪之，鬼神许之，以为彼自食其力也。若农夫织妇终岁勤动，以成数石之粟数尺之布，而富贵之家终岁逸乐，不营一业，而食必珍馐，衣必锦绣，酣豢高眠，一呼百诺，此天下最不平之事，神鬼所不许也，其能久乎？古之圣君贤相，盖无时不以勤劳自励。为一身计，则必操习技艺，磨练筋骨，困知勉行，操心危虑，而后可以增智慧而长见识。为天下计，则必已饥已溺，一夫不获，引为余辜。大禹、墨子皆极俭以奉身而极勤以救民。勤则寿，逸则夭，勤则有材而见用，逸则无劳而见弃，勤则博济斯民而神祇钦仰，逸则无补于人而神鬼不歆。\n\n　　此四条为余数十年人世之得，汝兄弟记之行之，并传之于子子孙孙，则余曾家可长盛不衰，代有人才。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '曾国藩诫子书' AND p.poem_author = '曾国藩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苏堤清明即事', '吴惟信', '宋代', '梨花风起正清明，游子寻春半出城。\n日暮笙歌收拾去，万株杨柳属流莺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苏堤清明即事' AND p.poem_author = '吴惟信';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月·平山堂', '苏轼', '宋代', '三过平山堂下，半生弹指声中。十年不见老仙翁，壁上龙蛇飞动。\n欲吊文章太守，仍歌杨柳春风。休言万事转头空，未转头时皆梦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月·平山堂' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏柳', '韩偓', '唐代', '褭雨拖风不自持，全身无力向人垂。\n玉纤折得遥相赠，便似观音手里时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏柳' AND p.poem_author = '韩偓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三江小渡', '杨万里', '宋代', '溪水将桥不复回，小舟犹倚短篙开。\n交情得似山溪渡，不管风波去又来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三江小渡' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春望', '林滋', '唐代', '春海镜长天，青郊丽上年。林光虚霁晓，山翠薄晴烟。 \n 气暖禽声变，风恬草色鲜。散襟披石磴，韶景自深怜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春望' AND p.poem_author = '林滋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送沈子归江东 / 送沈子福之江东', '王维', '唐代', '杨柳渡头行客稀，罟师荡桨向临圻。 \n唯有相思似春色，江南江北送君归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送沈子归江东 / 送沈子福之江东' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋夜曲', '张仲素', '唐代', '丁丁漏水夜何长，漫漫轻云露月光。\n秋逼暗虫通夕响，征衣未寄莫飞霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋夜曲' AND p.poem_author = '张仲素';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蔺相如完璧归赵论', '王世贞', '明代', '蔺相如之完璧，人皆称之。予未敢以为信也。\n\n　　夫秦以十五城之空名，诈赵而胁其璧。是时言取璧者，情也，非欲以窥赵也。赵得其情则弗予，不得其情则予；得其情而畏之则予，得其情而弗畏之则弗予。此两言决耳，奈之何既畏而复挑其怒也！\n\n　　且夫秦欲璧，赵弗予璧，两无所曲直也。入璧而秦弗予城，曲在秦；秦出城而璧归，曲在赵。欲使曲在秦，则莫如弃璧；畏弃璧，则莫如弗予。夫秦王既按图以予城，又设九宾，斋而受璧，其势不得不予城。璧入而城弗予，相如则前请曰：“臣固知大王之弗予城也。夫璧非赵璧乎？而十五城秦宝也。今使大王以璧故，而亡其十五城，十五城之子弟，皆厚怨大王以弃我如草芥也。大王弗与城，而绐赵璧，以一璧故，而失信于天下，臣请就死于国，以明大王之失信！”秦王未必不返璧也。今奈何使舍人怀而逃之，而归直于秦？\n\n　　是时秦意未欲与赵绝耳。令秦王怒而僇相如于市，武安君十万众压邯郸，而责璧与信，一胜而相如族，再胜而璧终入秦矣。\n\n　　吾故曰：蔺相如之获全于璧也，天也。若其劲渑池，柔廉颇，则愈出而愈妙于用。所以能完赵者，天固曲全之哉！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蔺相如完璧归赵论' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东城高且长', '佚名', '两汉', '东城高且长，逶迤自相属。\n回风动地起，秋草萋已绿。\n四时更变化，岁暮一何速！\n晨风怀苦心，蟋蟀伤局促。\n荡涤放情志，何为自结束？\n燕赵多佳人，美者颜如玉。\n被服罗裳衣，当户理清曲。\n音响一何悲！弦急知柱促。\n驰情整巾带，沉吟聊踯躅。\n思为双飞燕，衔泥巢君屋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东城高且长' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题金陵渡' AND p.poem_author = '张祜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('军城早秋', '严武', '唐代', '昨夜秋风入汉关，朔云边月满西山。 \n更催飞将追骄虏，莫遣沙场匹马还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '军城早秋' AND p.poem_author = '严武';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贫交行', '杜甫', '唐代', '翻手作云覆手雨，纷纷轻薄何须数。(翻手\'作\'云 一作：为)\n君不见管鲍贫时交，此道今人弃如土。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贫交行' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏菊', '曹雪芹', '清代', '无赖诗魔昏晓侵，绕篱欹石自沉音。\n毫端蕴秀临霜写，口齿噙香对月吟。\n满纸自怜题素怨，片言谁解诉秋心？\n一从陶令评章后，千古高风说到今。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏菊' AND p.poem_author = '曹雪芹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('画地学书', '欧阳修', '宋代', '欧阳修，字永叔，庐陵人。四岁而孤，母郑，守节自誓，亲诲之学。家贫，至以荻画地学书。幼敏悟过人，读书辄成诵。及冠，嶷然有声。\n修始在滁州，号醉翁，晚更号六一居士。天资刚劲，见义勇为，虽机阱在前，触发之不顾。放逐流离，至于再三，志气自若也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '画地学书' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('点绛唇·感兴', '王禹偁', '宋代', '雨恨云愁，江南依旧称佳丽。水村渔市。一缕孤烟细。\n天际征鸿，遥认行如缀。平生事。此时凝睇。谁会凭栏意。(栏 通：阑)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '点绛唇·感兴' AND p.poem_author = '王禹偁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贺新郎·送胡邦衡待制赴新州', '张元干', '宋代', '梦绕神州路。怅秋风、连营画角，故宫离黍。底事昆仑倾砥柱，九地黄流乱注。聚万落千村狐兔。天意从来高难问，况人情老易悲难诉。更南浦，送君去。\n凉生岸柳催残暑。耿斜河，疏星残月，断云微度。万里江山知何处？回首对床夜语。雁不到，书成谁与？目尽青天怀今古，肯儿曹恩怨相尔汝！举大白，听《金缕》。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贺新郎·送胡邦衡待制赴新州' AND p.poem_author = '张元干';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行路难·缚虎手', '贺铸', '宋代', '缚虎手，悬河口，车如鸡栖马如狗。白纶巾，扑黄尘，不知我辈可是蓬蒿人？衰兰送客咸阳道，天若有情天亦老。作雷颠，不论钱，谁问旗亭美酒斗十千？\n酌大斗，更为寿，青鬓长青古无有。笑嫣然，舞翩然，当垆秦女十五语如弦。遗音能记秋风曲，事去千年犹恨促。揽流光，系扶桑，争奈愁来一日却为长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行路难·缚虎手' AND p.poem_author = '贺铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江外思乡', '韦庄', '唐代', '年年春日异乡悲，杜曲黄莺可得知。 \n更被夕阳江岸上，断肠烟柳一丝丝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江外思乡' AND p.poem_author = '韦庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风雨', '李商隐', '唐代', '凄凉宝剑篇，羁泊欲穷年。\n黄叶仍风雨，青楼自管弦。\n新知遭薄俗，旧好隔良缘。\n心断新丰酒，销愁斗几千。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风雨' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春别曲', '张籍', '唐代', '长江春水绿堪染，莲叶出水大如钱。 \n江头橘树君自种，那不长系木兰船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春别曲' AND p.poem_author = '张籍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古意', '李白', '唐代', '君为女萝草，妾作菟丝花。\n轻条不自引，为逐春风斜。\n百丈托远松，缠绵成一家。\n谁言会面易，各在青山崖。\n女萝发馨香，菟丝断人肠。\n枝枝相纠结，叶叶竞飘扬。\n生子不知根，因谁共芬芳。\n中巢双翡翠，上宿紫鸳鸯。\n若识二草心，海潮亦可量。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古意' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春行即兴', '李华', '唐代', '宜阳城下草萋萋，涧水东流复向西。 \n芳树无人花自落，春山一路鸟空啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春行即兴' AND p.poem_author = '李华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏风', '王勃', '唐代', '肃肃凉风生，加我林壑清。\n驱烟寻涧户，卷雾出山楹。\n去来固无迹，动息如有情。\n日落山水静，为君起松声。(版本一)\n\n肃肃凉景生，加我林壑清。\n驱烟寻涧户，卷雾出山楹。\n去来固无迹，动息如有情。\n日落山水静，为君起松声。(版本二)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏风' AND p.poem_author = '王勃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('将仲子', '佚名', '先秦', '将仲子兮，无逾我里，无折我树杞。岂敢爱之？畏我父母。仲可怀也，父母之言亦可畏也。\n将仲子兮，无逾我墙，无折我树桑。岂敢爱之？畏我诸兄。仲可怀也，诸兄之言亦可畏也。\n将仲子兮，无逾我园，无折我树檀。岂敢爱之？畏人之多言。仲可怀也，人之多言亦可畏也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将仲子' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('工之侨献琴', '刘基', '明代', '工之侨得良桐焉，斫而为琴，弦而鼓之，金声而玉应。自以为天下之美也，献之太常。使国工视之，曰：“弗古。”还之。\n\n　　工之侨以归，谋诸漆工，作断纹焉；又谋诸篆工，作古窾焉。匣而埋诸土，期年出之，抱以适市。贵人过而见之，易之以百金，献诸朝。乐官传视，皆曰：“希世之珍也。”\n\n　　工之侨闻之，叹曰：“悲哉世也！岂独一琴哉？莫不然矣!而不早图之，其与亡矣。”遂去，入于宕之山，不知其所终。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '工之侨献琴' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与韩荆州书', '李白', '唐代', '白闻天下谈士相聚而言曰：“生不用封万户侯，但愿一识韩荆州。”何令人之景慕，一至于此耶！岂不以有周公之风，躬吐握之事，使海内豪俊，奔走而归之，一登龙门，则声价十倍！所以龙蟠凤逸之士，皆欲收名定价于君侯。愿君侯不以富贵而骄之、寒贱而忽之，则三千之中有毛遂，使白得颖脱而出，即其人焉。\n\n　　白，陇西布衣，流落楚、汉。十五好剑术，遍干诸侯。三十成文章，历抵卿相。虽长不满七尺，而心雄万夫。皆王公大人许与气义。此畴曩心迹，安敢不尽于君侯哉！\n\n　　君侯制作侔神明，德行动天地，笔参造化，学究天人。幸愿开张心颜，不以长揖见拒。必若接之以高宴，纵之以清谈，请日试万言，倚马可待。今天下以君侯为文章之司命，人物之权衡，一经品题，便作佳士。而君侯何惜阶前盈尺之地，不使白扬眉吐气，激昂青云耶？\n\n　　昔王子师为豫州，未下车，即辟荀慈明，既下车，又辟孔文举；山涛作冀州，甄拔三十余人，或为侍中、尚书，先代所美。而君侯亦荐一严协律，入为秘书郎，中间崔宗之、房习祖、黎昕、许莹之徒，或以才名见知，或以清白见赏。白每观其衔恩抚躬，忠义奋发，以此感激，知君侯推赤心于诸贤腹中，所以不归他人，而愿委身国士。傥急难有用，敢效微躯。\n\n　　且人非尧舜，谁能尽善？白谟猷筹画，安能自矜？至于制作，积成卷轴，则欲尘秽视听。恐雕虫小技，不合大人。若赐观刍荛，请给纸墨，兼之书人，然后退扫闲轩，缮写呈上。庶青萍、结绿，长价于薛、卞之门。幸惟下流，大开奖饰，惟君侯图之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与韩荆州书' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怨王孙·湖上风来波浩渺', '李清照', '宋代', '湖上风来波浩渺。秋已暮、红稀香少。水光山色与人亲，说不尽、无穷好。 \n莲子已成荷叶老。青露洗、萍花汀草。眠沙鸥鹭不回头，似也恨、人归早。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怨王孙·湖上风来波浩渺' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八声甘州·寄参寥子', '苏轼', '宋代', '有情风、万里卷潮来，无情送潮归。问钱塘江上，西兴浦口，几度斜晖。不用思量今古，俯仰昔人非。谁似东坡老，白首忘机。 \n记取西湖西畔，正暮山好处，空翠烟霏。算诗人相得，如我与君稀。约他年、东还海道，愿谢公、雅志莫相违。西州路，不应回首，为我沾衣。(正暮 一作：正春)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八声甘州·寄参寥子' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚出新亭', '阴铿', '南北朝', '大江一浩荡，离悲足几重。\n潮落犹如盖，云昏不作峰。\n远戍唯闻鼓，寒山但见松。\n九十方称半，归途讵有踪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚出新亭' AND p.poem_author = '阴铿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('薤露', '曹操', '魏晋', '惟汉廿二世，所任诚不良。\n沐猴而冠带，知小而谋强。\n犹豫不敢断，因狩执君王。\n白虹为贯日，己亦先受殃。\n贼臣持国柄，杀主灭宇京。\n荡覆帝基业，宗庙以燔丧。\n播越西迁移，号泣而且行。\n瞻彼洛城郭，微子为哀伤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '薤露' AND p.poem_author = '曹操';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诫兄子严敦书', '马援', '两汉', '援兄子严、敦，并喜讥议，而通轻侠客。援前在交趾，还书诫之曰：“吾欲汝曹闻人过失，如闻父母之名：耳可得闻，口不可得言也。好议论人长短，妄是非正法，此吾所大恶也：宁死，不愿闻子孙有此行也。汝曹知吾恶之甚矣，所以复言者，施衿结缡，申父母之戒，欲使汝曹不忘之耳！\n\n　　“龙伯高敦厚周慎，口无择言，谦约节俭，廉公有威。吾爱之重之，愿汝曹效之。杜季良豪侠好义，忧人之忧，乐人之乐，清浊无所失。父丧致客，数郡毕至。吾爱之重之，不愿汝曹效也。效伯高不得，犹为谨敕之士，所谓‘刻鹄不成尚类鹜’者也。效季良不得，陷为天下轻薄子，所谓‘画虎不成反类狗’者也。讫今季良尚未可知，郡将下车辄切齿，州郡以为言，吾常为寒心，是以不愿子孙效也。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诫兄子严敦书' AND p.poem_author = '马援';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一枝花·不伏老', '关汉卿', '元代', '〔一枝花〕\n\n　　攀出墙朵朵花，折临路枝枝柳。花攀红蕊嫩，柳折翠条柔，浪子风流。凭着我折柳攀花手，直煞得花残柳败休。半生来折柳攀花，一世里眠花卧柳。\n\n　　〔梁州〕\n\n　　我是个普天下郎君领袖，盖世界浪子班头。愿朱颜不改常依旧，花中消遣，酒内忘忧。分茶攧竹，打马藏阄；通五音六律滑熟，甚闲愁到我心头？伴的是银筝女银台前理银筝笑倚银屏，伴的是玉天仙携玉手并玉肩同登玉楼，伴的是金钗客歌金缕捧金樽满泛金瓯。你道我老也，暂休。占排场风月功名首，更玲珑又剔透。我是个锦阵花营都帅头，曾玩府游州。\n\n　　〔隔尾〕\n\n　　子弟每是个茅草冈、沙土窝初生的兔羔儿乍向围场上走，我是个经笼罩、受索网苍翎毛老野鸡蹅踏的阵马儿熟。经了些窝弓冷箭鑞枪头，不曾落人后。恰不道“人到中年万事休”，我怎肯虚度了春秋。\n\n　　〔尾〕\n\n　　我是个蒸不烂、煮不熟、捶不匾、炒不爆、响珰珰一粒铜豌豆，恁子弟每谁教你钻入他锄不断、斫不下、解不开、顿不脱、慢腾腾千层锦套头？我玩的是梁园月，饮的是东京酒，赏的是洛阳花，攀的是章台柳。我也会围棋、会蹴踘、会打围、会插科、会歌舞、会吹弹、会咽作、会吟诗、会双陆。你便是落了我牙、歪了我嘴、瘸了我腿、折了我手，天赐与我这几般儿歹症候，尚兀自不肯休！则除是阎王亲自唤，神鬼自来勾。三魂归地府，七魄丧冥幽。天哪！那其间才不向烟花路儿上走！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '一枝花·不伏老' AND p.poem_author = '关汉卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西北有高楼', '佚名', '两汉', '西北有高楼，上与浮云齐。\n交疏结绮窗，阿阁三重阶。\n上有弦歌声，音响一何悲！\n谁能为此曲，无乃杞梁妻。\n清商随风发，中曲正徘徊。\n一弹再三叹，慷慨有余哀。\n不惜歌者苦，但伤知音稀。\n愿为双鸿鹄，奋翅起高飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西北有高楼' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鸿雁', '佚名', '先秦', '鸿雁于飞，肃肃其羽。之子于征，劬劳于野。爰及矜人，哀此鳏寡。\n鸿雁于飞，集于中泽。之子于垣，百堵皆作。虽则劬劳，其究安宅？\n鸿雁于飞，哀鸣嗷嗷。维此哲人，谓我劬劳。维彼愚人，谓我宣骄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鸿雁' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·邶风·谷风', '佚名', '先秦', '习习谷风，以阴以雨。黾勉同心，不宜有怒。采葑采菲，无以下体？德音莫违，及尔同死。\n行道迟迟，中心有违。不远伊迩，薄送我畿。谁谓荼苦，其甘如荠。宴尔新婚，如兄如弟。\n泾以渭浊，湜湜其沚。宴尔新婚，不我屑以。毋逝我梁，毋发我笱。我躬不阅，遑恤我后。\n就其深矣，方之舟之。就其浅矣，泳之游之。何有何亡，黾勉求之。凡民有丧，匍匐救之。\n不我能慉，反以我为仇。既阻我德，贾用不售。昔育恐育鞫，及尔颠覆。既生既育，比予于毒。\n我有旨蓄，亦以御冬。宴尔新婚，以我御穷。有洸有溃，既诒我肄。不念昔者，伊余来塈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·邶风·谷风' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('殷其雷', '佚名', '先秦', '殷其雷，在南山之阳。何斯违斯，莫敢或遑？振振君子，归哉归哉！\n殷其雷，在南山之侧。何斯违斯，莫敢遑息？振振君子，归哉归哉！\n殷其雷，在南山之下。何斯违斯，莫或遑处？振振君子，归哉归哉！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '殷其雷' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('劝学诗', '赵恒', '宋代', '富家不用买良田，书中自有千锺粟。\n安居不用架高堂，书中自有黄金屋。\n出门莫恨无人随，书中车马多如簇。\n娶妻莫恨无良媒，书中自有颜如玉。\n男儿若遂平生志，六经勤向窗前读。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '劝学诗' AND p.poem_author = '赵恒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头·平生太湖上', '佚名', '宋代', '平生太湖上，短棹几经过。如今重到何事？愁比水云多。拟把匣中长剑，换取扁舟一叶，归去老渔蓑。银艾非吾事，丘壑已蹉跎。脍新鲈，斟美酒，起悲歌。太平生长，岂谓今日识兵戈？欲泻三江雪浪，净洗胡尘千里，不用挽天河！回首望霄汉，双泪堕清波。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头·平生太湖上' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜游宫·记梦寄师伯浑', '陆游', '宋代', '雪晓清笳乱起。梦游处、不知何地。铁骑无声望似水。想关河，雁门西，青海际。\n睡觉寒灯里。漏声断、月斜窗纸。自许封侯在万里。有谁知，鬓虽残，心未死。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜游宫·记梦寄师伯浑' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆帝京·薄衾小枕凉天气', '柳永', '宋代', '薄衾小枕凉天气，乍觉别离滋味。展转数寒更，起了还重睡。毕竟不成眠，一夜长如岁。 \n也拟待、却回征辔；又争奈、已成行计。万种思量，多方开解，只恁寂寞厌厌地。系我一生心，负你千行泪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆帝京·薄衾小枕凉天气' AND p.poem_author = '柳永';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春夕', '崔涂', '唐代', '水流花谢两无情，送尽东风过楚城。\n胡蝶梦中家万里，子规枝上月三更。\n故园书动经年绝，华发春唯满镜生。\n自是不归归便得，五湖烟景有谁争。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春夕' AND p.poem_author = '崔涂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题鹤林寺僧舍', '李涉', '唐代', '终日昏昏醉梦间，忽闻春尽强登山。\n因过竹院逢僧话，偷得浮生半日闲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题鹤林寺僧舍' AND p.poem_author = '李涉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青溪 / 过青溪水作', '王维', '唐代', '言入黄花川，每逐清溪水。\n随山将万转，趣途无百里。\n声喧乱石中，色静深松里。\n漾漾泛菱荇，澄澄映葭苇。\n我心素已闲，清川澹如此。\n请留磐石上，垂钓将已矣。(磐石 一作：盘石)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青溪 / 过青溪水作' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('商颂·殷武', '佚名', '先秦', '挞彼殷武，奋伐荆楚。深入其阻，裒荆之旅。有截其所，汤孙之绪。\n维女荆楚，居国南乡。昔有成汤，自彼氐羌，莫敢不来享，莫敢不来王。曰商是常。\n天命多辟，设都于禹之绩。岁事来辟，勿予祸适，稼穑匪解。\n天命降监，下民有严。不僭不滥，不敢怠遑。命于下国，封建厥福。\n商邑翼翼，四方之极。赫赫厥声，濯濯厥灵。寿考且宁，以保我后生。\n陟彼景山，松伯丸丸。是断是迁，方斫是虔。松桷有梴，旅楹有闲，寝成孔安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '商颂·殷武' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鸳鸯', '佚名', '先秦', '鸳鸯于飞，毕之罗之。君子万年，福禄宜之。\n鸳鸯在梁，戢其左翼。君子万年，宜其遐福。\n乘马在厩，摧之秣之。君子万年，福禄艾之。\n乘马在厩，秣之摧之。君子万年，福禄绥之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鸳鸯' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九辩', '宋玉', '先秦', '悲哉，秋之为气也！\n萧瑟兮草木摇落而变衰。\n憭栗兮若在远行，登山临水兮送将归。\n泬漻兮天高而气清，寂寥兮收潦而水清。\n憯悽增欷兮，薄寒之中人，\n怆怳懭悢兮，去故而就新。\n坎廪兮贫士失职而志不平，\n廓落兮羁旅而无友生，\n惆怅兮而私自怜！\n燕翩翩其辞归兮，蝉寂漠而无声。\n雁廱廱而南游兮，鹍鸡啁哳而悲鸣。\n独申旦而不寐兮，哀蟋蟀之宵征。\n时亹亹而过中兮，蹇淹留而无成。\n悲忧穷戚兮独处廓，有美一人兮心不绎。\n去乡离家兮来远客，超逍遥兮今焉薄！\n专思君兮不可化，君不知兮可奈何！\n蓄怨兮积思，心烦憺兮忘食事。\n原一见兮道余意，君之心兮与余异。\n车既驾兮朅而归，不得见兮心伤悲。\n倚结軨兮长太息，涕潺湲兮下霑轼。\n忼慨绝兮不得，中瞀乱兮迷惑。\n私自怜兮何极？心怦怦兮谅直。\n皇天平分四时兮，窃独悲此凛秋。\n白露既下百草兮，奄离披此梧楸。\n去白日之昭昭兮，袭长夜之悠悠。\n离芳蔼之方壮兮，余萎约而悲愁。\n秋既先戒以白露兮，冬又申之以严霜。\n收恢台之孟夏兮，然欿傺而沉藏。\n叶菸邑而无色兮，枝烦挐而交横。\n颜淫溢而将罢兮，柯仿佛而萎黄。\n萷櫹椮之可哀兮，形销铄而瘀伤。\n惟其纷糅而将落兮，恨其失时而无当。\n揽騑辔而下节兮，聊逍遥以相佯。\n岁忽忽而遒尽兮，恐余寿之弗将。\n悼余生之不时兮，逢此世之俇攘。\n澹容与而独倚兮，蟋蟀鸣此西堂。\n心怵惕而震荡兮，何所忧之多方。\n卬明月而太息兮，步列星而极明。\n窃悲夫蕙华之曾敷兮，纷旖旎乎都房。\n何曾华之无实兮，从风雨而飞飏！\n以为君独服此蕙兮，羌无以异于众芳。\n闵奇思之不通兮，将去君而高翔。\n心闵怜之惨悽兮，愿一见而有明。\n重无怨而生离兮，中结轸而增伤。\n岂不郁陶而思君兮？君之门以九重！\n猛犬狺狺而迎吠兮，关梁闭而不通。\n皇天淫溢而秋霖兮，后土何时而得漧？\n塊独守此无泽兮，仰浮云而永叹！\n何时俗之工巧兮？背绳墨而改错！\n\n郤骐骥而不乘兮，策驽骀而取路。\n当世岂无骐骥兮，诚莫之能善御。\n见执辔者非其人兮，故駶跳而远去。\n凫雁皆唼夫梁藻兮，凤愈飘翔而高举。\n圜凿而方枘兮，吾固知其鉏铻而难入。\n众鸟皆有所登棲兮，凤独遑遑而无所集。\n原衔枚而无言兮，尝被君之渥洽。\n太公九十乃显荣兮，诚未遇其匹合。\n谓骐骥兮安归？谓凤皇兮安棲？\n变古易俗兮世衰，今之相者兮举肥。\n骐骥伏匿而不见兮，凤皇高飞而不下。\n鸟兽犹知怀德兮，何云贤士之不处？\n骥不骤进而求服兮，凤亦不贪餧而妄食。\n君弃远而不察兮，虽原忠其焉得？\n欲寂漠而绝端兮，窃不敢忘初之厚德。\n独悲愁其伤人兮，冯郁郁其何极？\n霜露惨悽而交下兮，心尚幸其弗济。\n霰雪雰糅其增加兮，乃知遭命之将至。\n原徼幸而有待兮，泊莽莽与野草同死。\n原自往而径游兮，路壅绝而不通。\n欲循道而平驱兮，又未知其所从。\n然中路而迷惑兮，自压桉而学诵。\n性愚陋以褊浅兮，信未达乎从容。\n窃美申包胥之气盛兮，恐时世之不固。\n何时俗之工巧兮？灭规矩而改凿！\n独耿介而不随兮，原慕先圣之遗教。\n处浊世而显荣兮，非余心之所乐。\n与其无义而有名兮，宁穷处而守高。\n食不媮而为饱兮，衣不苟而为温。\n窃慕诗人之遗风兮，原讬志乎素餐。\n蹇充倔而无端兮，泊莽莽而无垠。\n无衣裘以御冬兮，恐溘死不得见乎阳春。\n靓杪秋之遥夜兮，心缭悷而有哀。\n春秋逴逴而日高兮，然惆怅而自悲。\n四时递来而卒岁兮，阴阳不可与俪偕。\n白日晼晚其将入兮，明月销铄而减毁。\n岁忽忽而遒尽兮，老冉冉而愈弛。\n心摇悦而日幸兮，然怊怅而无冀。\n中憯恻之悽怆兮，长太息而增欷。\n年洋洋以日往兮，老嵺廓而无处。\n事亹亹而觊进兮，蹇淹留而踌躇。\n何氾滥之浮云兮？猋壅蔽此明月。\n忠昭昭而原见兮，然霠曀而莫达。\n原皓日之显行兮，云蒙蒙而蔽之。\n窃不自聊而原忠兮，或黕点而汙之。\n尧舜之抗行兮，瞭冥冥而薄天。\n何险巇之嫉妒兮？被以不慈之伪名。\n彼日月之照明兮，尚黯黮而有瑕。\n何况一国之事兮，亦多端而胶加。\n被荷裯之晏晏兮，然潢洋而不可带。\n\n既骄美而伐武兮，负左右之耿介。\n憎愠惀之修美兮，好夫人之慷慨。\n众踥蹀而日进兮，美超远而逾迈。\n农夫辍耕而容与兮，恐田野之芜秽。\n事緜緜而多私兮，窃悼後之危败。\n世雷同而炫曜兮，何毁誉之昧昧！\n今修饰而窥镜兮，後尚可以竄藏。\n愿寄言夫流星兮，羌倏忽而难当。\n卒壅蔽此浮云，下暗漠而无光。\n尧舜皆有所举任兮，故高枕而自适。\n谅无怨于天下兮，心焉取此怵惕？\n乘骐骥之浏浏兮，驭安用夫强策？\n谅城郭之不足恃兮，虽重介之何益？\n邅翼翼而无终兮，忳惛惛而愁约。\n生天地之若过兮，功不成而无嶜。\n原沉滞而不见兮，尚欲布名乎天下。\n然潢洋而不遇兮，直怐愗而自苦。\n莽洋洋而无极兮，忽翱翔之焉薄？\n国有骥而不知乘兮，焉皇皇而更索？\n宁戚讴于车下兮，桓公闻而知之。\n无伯乐之相善兮，今谁使乎誉之？\n罔流涕以聊虑兮，惟著意而得之。\n纷纯纯之愿忠兮，妒被离而鄣之。\n原赐不肖之躯而别离兮，放游志乎云中。\n乘精气之抟抟兮，骛诸神之湛湛。\n骖白霓之習習兮，历群灵之丰丰。\n左硃雀之茇茇兮，右苍龙之躣躣。\n属雷师之阗阗兮，通飞廉之衙衙。\n前轻辌之锵锵兮，后辎乘之从从。\n载云旗之委蛇兮，扈屯骑之容容。\n计专专之不可化兮，原遂推而为臧。\n赖皇天之厚德兮，还及君之无恙！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九辩' AND p.poem_author = '宋玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苏武传(节选)', '班固', '两汉', '武字子卿，少以父任，兄弟并为郎，稍迁至栘中厩监。时汉连伐胡，数通使相窥观。匈奴留汉使郭吉、路充国等前后十余辈，匈奴使来，汉亦留之以相当。天汉元年，且鞮侯单于初立，恐汉袭之，乃曰：「汉天子我丈人行也。」尽归汉使路充国等。武帝嘉其义，乃遣武以中郎将使持节送匈奴使留在汉者，因厚赂单于，答其善意。\n\n　　武与副中郎将张胜及假吏常惠等募士斥候百余人俱。既至匈奴，置币遗单于；单于益骄，非汉所望也。方欲发使送武等，会缑王与长水虞常等谋反匈奴中。缑王者，昆邪王姊子也，与昆邪王俱降汉，后随浞野侯没胡中，及卫律所将降者，阴相与谋，劫单于母阏氏归汉。会武等至匈奴。虞常在汉时，素与副张胜相知，私候胜曰：「闻汉天子甚怨卫律，常能为汉伏弩射杀之，吾母与弟在汉，幸蒙其赏赐。」张胜许之，以货物与常。后月余，单于出猎，独阏氏子弟在。虞常等七十余人欲发，其一人夜亡告之。单于子弟发兵与战，缑王等皆死，虞常生得。\n\n　　单于使卫律治其事。张胜闻之，恐前语发，以状语武。武曰：「事如此，此必及我，见犯乃死，重负国！」欲自杀，胜惠共止之。虞常果引张胜。单于怒，召诸贵人议，欲杀汉使者。左伊秩訾曰：「即谋单于，何以复加？宜皆降之。」单于使卫律召武受辞。武谓惠等：「屈节辱命，虽生何面目以归汉？」引佩刀自刺。卫律惊，自抱持武。驰召医，凿地为坎，置煴火，覆武其上，蹈其背，以出血。武气绝，半日复息。惠等哭，舆归营。单于壮其节，朝夕遣人候问武，而收系张胜。\n\n　　武益愈。单于使使晓武，会论虞常，欲因此时降武。剑斩虞常已，律曰：「汉使张胜谋杀单于近臣，当死；单于募降者，赦罪。」举剑欲击之，胜请降。律谓武曰：「副有罪，当相坐。」武曰：「本无谋，又非亲属，何谓相坐？」复举剑拟之，武不动。律曰：「苏君，律前负汉归匈奴，幸蒙大恩，赐号称王，拥众数万，马畜弥山，富贵如此。苏君今日降，明日复然。空以身膏草野，谁复知之？」武不应。律曰：「君因我降，与君为兄弟；今不听吾计，后虽复欲见我，尚可得乎？」武骂律曰：「汝为人臣子，不顾恩义，畔主背亲，为降虏于蛮夷，何以女为见？且单于信女，使决人死生，不平心持正，反欲斗两主观祸败。南越杀汉使者，屠为九郡；宛王杀汉使者，头县北阙；朝鲜杀汉使者，即时诛灭。独匈奴未耳。若知我不降明，欲令两国相攻，匈奴之祸，从我始矣！」律知武终不可胁，白单于。单于愈益欲降之。乃幽武置大窖中，绝不饮食。天雨雪。武卧，啮雪与旃毛并咽之，数日不死。匈奴以为神，乃徙武北海上无人处，使牧羝。羝乳，乃得归。别其官属常惠等，各置他所。\n\n　　武既至海上，廪食不至，掘野鼠去屮实而食之。杖汉节牧羊，卧起操持，节旄尽落。积五、六年，单于弟于靬王弋射海上。武能网纺缴，檠弓弩，于靬王爱之，给其衣食。三岁余，王病，赐武马畜、服匿、穹庐。王死后，人众徙去。其冬，丁令盗武牛羊，武复穷厄。\n\n　　初，武与李陵俱为侍中。武使匈奴明年，陵降，不敢求武。久之，单于使陵至海上，为武置酒设乐。因谓武曰：「单于闻陵与子卿素厚，故使陵来说足下，虚心欲相待。终不得归汉，空自苦亡人之地，信义安所见乎？前长君为奉车，从至雍棫阳宫，扶辇下除，触柱，折辕，劾大不敬，伏剑自刎，赐钱二百万以葬。孺卿从祠河东後土，宦骑与黄门驸马争船，推堕驸马河中，溺死，宦骑亡。诏使孺卿逐捕。不得，惶恐饮药而死。来时太夫人已不幸，陵送葬至阳陵。子卿妇年少，闻已更嫁矣。独有女弟二人，两女一男，今复十余年，存亡不可知。人生如朝露，何久自苦如此？陵始降时，忽忽如狂，自痛负汉；加以老母系保宫。子卿不欲降，何以过陵？且陛下春秋高，法令亡常，大臣亡罪夷灭者数十家，安危不可知。子卿尚复谁为乎？愿听陵计，勿复有云！」\n\n　　武曰：「武父子亡功德，皆为陛下所成就，位列将，爵通侯，兄弟亲近，常愿肝脑涂地。今得杀身自效，虽蒙斧钺汤镬，诚甘乐之。臣事君，犹子事父也。子为父死，亡所恨，愿无复再言。」陵与武饮数日，复曰：「子卿，壹听陵言。」武曰：「自分已死久矣！王必欲降武，请毕今日之欢，效死于前！」陵见其至诚，喟然叹曰：「嗟呼！义士！陵与卫律之罪上通于天！」因泣下沾衿，与武决去。\n\n　　陵恶自赐武，使其妻赐武牛羊数十头。后陵复至北海上，语武：「区脱捕得云中生口，言太守以下吏民皆白服，曰：『上崩。』」武闻之，南乡号哭，欧血，旦夕临。数月，昭帝即位。数年，匈奴与汉和亲。汉求武等。匈奴诡言武死。后汉使复至匈奴。常惠请其守者与俱，得夜见汉使，具自陈道。教使者谓单于言：「天子射上林中，得雁足有系帛书，言武等在某泽中。」使者大喜，如惠语以让单于。单于视左右而惊，谢汉使曰：「武等实在。」于是李陵置酒贺武曰：「今足下还归，扬名于匈奴，功显于汉室，虽古竹帛所载，丹青所画，何以过子卿！陵虽驽怯，令汉且贳陵罪，全其老母，使得奋大辱之积志，庶几乎曹柯之盟。此陵宿昔之所不忘也！收族陵家，为世大戮，陵尚复何顾乎？已矣！令子卿知吾心耳！异域之人，壹别长绝！」陵起舞，歌曰：「径万里兮度沙幕，为君将兮奋匈奴。路穷绝兮矢刃摧，士众灭兮名已隤，老母已死，虽欲报恩将安归？」\n\n　　陵泣下数行，因与武决。单于召会武官属，前以降及物故，凡随武还者九人。武以始元六年春至京师，诏武奉一太牢谒武帝园庙，拜为典属国，秩中二千石，赐钱二百万，公田二顷，宅一区。常惠徐圣赵终根皆拜为中郎，赐帛各二百匹。其余六人，老归家，赐钱人十万，复终身。常惠后至右将军，封列侯，自有传。武留匈奴凡十九岁，始以强壮出，及还，须发尽白。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '苏武传(节选)' AND p.poem_author = '班固';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('眼儿媚·杨柳丝丝弄轻柔', '王雱', '宋代', '杨柳丝丝弄轻柔，烟缕织成愁。海棠未雨，梨花先雪，一半春休。\n而今往事难重省，归梦绕秦楼。相思只在：丁香枝上，豆蔻梢头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '眼儿媚·杨柳丝丝弄轻柔' AND p.poem_author = '王雱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('立春偶成', '张栻', '宋代', '律回岁晚冰霜少，春到人间草木知。\n便觉眼前生意满，东风吹水绿参差。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '立春偶成' AND p.poem_author = '张栻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('醉花阴·黄花谩说年年好', '辛弃疾', '宋代', '黄花谩说年年好。也趁秋光老。绿鬓不惊秋，若斗尊前，人好花堪笑。\n蟠桃结子知多少。家住三山岛。何日跨归鸾，沧海飞尘，人世因缘了。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '醉花阴·黄花谩说年年好' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('生查子·新月曲如眉', '牛希济', '五代', '新月曲如眉，未有团圞意。红豆不堪看，满眼相思泪。\n终日劈桃穰，人在心儿里。两朵隔墙花，早晚成连理。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '生查子·新月曲如眉' AND p.poem_author = '牛希济';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '隋宫' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·卫风·伯兮', '佚名', '先秦', '伯兮朅兮，邦之桀兮。伯也执殳，为王前驱。\n自伯之东，首如飞蓬。岂无膏沐？谁适为容！\n其雨其雨，杲杲出日。愿言思伯，甘心首疾。\n焉得谖草？言树之背。愿言思伯。使我心痗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·卫风·伯兮' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自题金山画像', '苏轼', '宋代', '心似已灰之木，身如不系之舟。\n问汝平生功业，黄州惠州儋州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自题金山画像' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('生查子·独游雨岩', '辛弃疾', '宋代', '溪边照影行，天在清溪底。天上有行云，人在行云里。 \n高歌谁和余，空谷清音起。非鬼亦非仙，一曲桃花水。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '生查子·独游雨岩' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜算子·竹里一枝梅', '向子諲', '宋代', '岁见梅追和一首，终恨有儿女子态耳 \n竹里一枝梅，雨洗娟娟静。疑是佳人日暮来，绰约风前影。\n新恨有谁知，往事何堪省。梦绕阳台寂寞回，沾袖余香冷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜算子·竹里一枝梅' AND p.poem_author = '向子諲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·雨霰疏疏经泼火', '苏轼', '宋代', '雨霰疏疏经泼火。巷陌秋千，犹未清明过。杏子梢头香蕾破。淡红褪白胭脂涴。 \n苦被多情相折挫。病绪厌厌，浑似年时个。绕遍回廊还独坐。月笼云暗重门锁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·雨霰疏疏经泼火' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高唐赋', '宋玉', '先秦', '昔者楚襄王与宋玉游于云梦之台，望高之观，其上独有云气，崪兮直上，忽兮改容，须臾之间，变化无穷。王问玉曰：“此何气也？”玉对曰：“所谓朝云者也。”王曰：“何谓朝云？”玉曰：“昔者先王尝游高唐，怠而昼寝，梦见一妇人曰：‘妾，巫山之女也。为高唐之客。闻君游高唐，愿荐枕席。’王因幸之。去而辞曰：‘妾在巫山之阳，高丘之阻，旦为朝云，暮为行雨。朝朝暮暮，阳台之下。’旦朝视之，如言。故为立庙，号曰朝云。”王曰：“朝云始楚，状若何也？”玉对曰：“其始楚也，榯兮若松榯；其少进也，晰兮若姣姬，扬衭鄣日，而望所思。忽兮改容，偈兮若驾驷马，建羽旗。湫兮如风，凄兮如雨。风止雨霁，云无所处。”王曰：“寡人方今可以游乎？”玉曰：“可。”王曰：“其何如矣？”玉曰：“高矣显矣，临望远矣。广矣普矣，万物祖矣。上属于天，下见于渊，珍怪奇伟，不可称论。”王曰：“试为寡人赋之！”玉曰：“唯唯！”\n\n　　惟高唐之大体兮，殊无物类之可仪比。巫山赫其无畴兮，道互折而曾累。登巉巗而下望兮，临大阺之稸水。遇天雨之新霁兮，观百谷之俱集。濞汹汹其无声兮，溃淡淡而并入。滂洋洋而四施兮，蓊湛湛而弗上。长风至而波起兮，若丽山之孤亩。势薄岸而相击兮，隘交引而却会。崪中怒而特高兮，若浮海而望碣石。砾磥磥而相摩兮，巆震天之礚礚。巨石溺溺之瀺灂兮，沫潼潼而高厉，水澹澹而盘纡兮，洪波淫淫之溶。奔扬踊而相击兮，云兴声之霈霈。猛兽惊而跳骇兮，妄奔走而驰迈。虎豹豺兕，失气恐喙；雕鹗鹰鹞，飞扬伏窜。股战胁息，安敢妄挚。于是水虫尽暴，乘渚之阳，鼋鼍鱣鮪，交积纵横。振鳞奋翼，蜲蜲蜿蜿。\n\n　　中阪遥望，玄木冬荣，煌煌荧荧，夺人目精。爛兮若列星，曾不可殚形。榛林郁盛，葩华覆盖；双椅垂房，纠枝还会。徙靡澹淡，随波闇蔼；东西施翼，猗狔丰沛。绿叶紫裹，丹茎白蒂。纤条悲鸣；声似竽籁；清浊相和，五变四会。感心动耳，回肠伤气；孤子寡妇，寒心酸鼻。长吏隳官，贤士失志；愁思无已，叹息垂泪。\n\n　　登高远望，使人心瘁；盘岸巑，裖陈皑皑。磐石险峻，倾崎崖。巌岖参差，纵横相追。陬互横啎，背穴偃蹠。交加累积，重叠增益。状若砾柱，杂巫山下；仰视山巅，肃何千千。炫燿虹蜺，俯视峥嵘，窐寥窈冥，不见其底，虚闻松声。倾岸洋洋，立而熊经，久而不去，足尽汗出。悠悠忽忽，怊怅自失。使人心动，无故自恐。賁育之断，不能为勇。卒愕异物，不知所出。纵纵莘莘，若生于鬼，若出于神。状似走兽，或象飞禽。谲诡奇伟，不可究陈。上至观侧，地盖底平。箕踵漫衍，芳草罗生。秋兰茝蕙，江离载青。青荃射干，揭车苞并。薄草靡靡，聮延夭夭，越香掩掩；众雀嗷嗷，雌雄相失，哀鸣相号。王鴡鸝黄，正冥楚鸠。秭归思妇，垂鸡高巢。其鸣喈喈，当年遨游。更唱迭和，赴曲随流。\n\n　　有方之士，羡门高谿。上成郁林，公乐聚榖。进纯牺，祷琁室。醮诸神，礼太一。传祝已具，言辞已毕。王乃乘玉舆，驷仓螭，垂旒旌；旆合谐。紬大絃而雅声流，冽风过而增悲哀。于是调讴，令人惏悽，胁息曾。于是乃纵猎者，基趾如星，传言羽猎；衔枚无声，弓弩不发，罘不倾。涉莽莽，驰苹苹。飞鸟未及起，走兽未及发。何节奄忽，蹄足灑血。举功先得，获车已实。王将欲往见，必先斋戒。差时择日，简舆玄服。建云旆，蜺为旌，翠为盖。风起云止，千里而逝。盖发蒙，往自会，思万方，忧国害，开贤圣，辅不逮，九窍通郁，精神察滞。延年益寿千万岁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高唐赋' AND p.poem_author = '宋玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望岳三首·其三', '杜甫', '唐代', '南岳配朱鸟，秩礼自百王。\n欻吸领地灵，鸿洞半炎方。\n邦家用祀典，在德非馨香。\n巡守何寂寥，有虞今则亡。\n洎吾隘世网，行迈越潇湘。\n渴日绝壁出，漾舟清光旁。\n祝融五峰尊，峰峰次低昂。\n紫盖独不朝，争长嶪相望。\n恭闻魏夫人，群仙夹翱翔。\n有时五峰气，散风如飞霜。\n牵迫限修途，未暇杖崇冈。\n归来觊命驾，沐浴休玉堂。\n三叹问府主，曷以赞我皇。\n牲璧忍衰俗，神其思降祥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望岳三首·其三' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('终风', '佚名', '先秦', '终风且暴，顾我则笑，谑浪笑敖，中心是悼。\n终风且霾，惠然肯来，莫往莫来，悠悠我思。\n终风且曀，不日有曀，寤言不寐，愿言则嚏。\n曀曀其阴，虺虺其雷，寤言不寐，愿言则怀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '终风' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏怀古迹五首·其二', '杜甫', '唐代', '摇落深知宋玉悲，风流儒雅亦吾师。\n怅望千秋一洒泪，萧条异代不同时。\n江山故宅空文藻，云雨荒台岂梦思。\n最是楚宫俱泯灭，舟人指点到今疑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏怀古迹五首·其二' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满庭芳·小阁藏春', '李清照', '宋代', '小阁藏春，闲窗锁昼，画堂无限深幽。篆香烧尽，日影下帘钩。手种江梅渐好，又何必、临水登楼。无人到，寂寥浑似，何逊在扬州。\n从来，知韵胜，难堪雨藉，不耐风揉。更谁家横笛，吹动浓愁。莫恨香消雪减，须信道、扫迹情留。难言处，良宵淡月，疏影尚风流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满庭芳·小阁藏春' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜迁莺·晓月坠', '李煜', '五代', '晓月坠，宿云微，无语枕频欹。梦回芳草思依依，天远雁声稀。\n啼莺散，馀花乱，寂寞画堂深院。片红休埽尽从伊，留待舞人归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜迁莺·晓月坠' AND p.poem_author = '李煜';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将赴吴兴登乐游原一绝' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('除夜宿石头驿', '戴叔伦', '唐代', '旅馆谁相问，寒灯独可亲。\n一年将尽夜，万里未归人。\n寥落悲前事，支离笑此身。\n愁颜与衰鬓，明日又逢春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '除夜宿石头驿' AND p.poem_author = '戴叔伦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题长安壁主人', '张谓', '唐代', '世人结交须黄金，黄金不多交不深。 \n纵令然诺暂相许，终是悠悠行路心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题长安壁主人' AND p.poem_author = '张谓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采莲曲', '贺知章', '唐代', '稽山罢雾郁嵯峨，镜水无风也自波。\n莫言春度芳菲尽，别有中流采芰荷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采莲曲' AND p.poem_author = '贺知章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九月九日登玄武山 / 九月九日玄武山旅眺', '卢照邻', '唐代', '九月九日眺山川，归心归望积风烟。\n他乡共酌金花酒，万里同悲鸿雁天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九月九日登玄武山 / 九月九日玄武山旅眺' AND p.poem_author = '卢照邻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('河满子·秋怨', '孙洙', '宋代', '怅望浮生急景，凄凉宝瑟馀音。楚客多情偏怨别，碧山远水登临。目送连天衰草，夜阑几处疏砧。\n黄叶无风自落，秋云不雨长阴。天若有情天亦老，摇摇幽恨难禁。惆怅旧欢如梦，觉来无处追寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '河满子·秋怨' AND p.poem_author = '孙洙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉楼春·风前欲劝春光住', '辛弃疾', '宋代', '风前欲劝春光住。春在城南芳草路。未随流落水边花，且作飘零泥上絮。 \n镜中已觉星星误。人不负春春自负。梦回人远许多愁，只在梨花风雨处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉楼春·风前欲劝春光住' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹊踏枝·几日行云何处去', '冯延巳', '五代', '几日行云何处去？忘却归来，不道春将暮。百草千花寒食路，香车系在谁家树？\n泪眼倚楼频独语。双燕来时，陌上相逢否？撩乱春愁如柳絮，依依梦里无寻处。(依依 一作：悠悠)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹊踏枝·几日行云何处去' AND p.poem_author = '冯延巳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('落日忆山中', '李白', '唐代', '雨后烟景绿，晴天散馀霞。东风随春归，发我枝上花。 \n花落时欲暮，见此令人嗟。愿游名山去，学道飞丹砂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '落日忆山中' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜泊牛渚怀古', '李白', '唐代', '牛渚西江夜，青天无片云。\n登舟望秋月，空忆谢将军。\n余亦能高咏，斯人不可闻。\n明朝挂帆席，枫叶落纷纷。(挂帆\'席\', 一作：去)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜泊牛渚怀古' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('人月圆·山中书事', '张可久', '元代', '兴亡千古繁华梦，诗眼倦天涯。孔林乔木，吴宫蔓草，楚庙寒鸦。\n数间茅舍，藏书万卷，投老村家。山中何事？松花酿酒，春水煎茶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '人月圆·山中书事' AND p.poem_author = '张可久';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹬蚌相争', '刘向', '两汉', '赵且伐燕，苏代为燕谓惠王曰：“今者臣来，过易水。蚌方出曝，而鹬啄其肉，蚌合而箝其喙。鹬曰：‘今日不雨，明日不雨，即有死蚌！’蚌亦谓鹬曰：‘今日不出，明日不出，即有死鹬！’两者不肯相舍，渔者得而并禽之。今赵且伐燕，燕赵久相支，以弊大众，臣恐强秦之为渔夫也。故愿王之熟计之也！”惠王曰：“善。”乃止。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '鹬蚌相争' AND p.poem_author = '刘向';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('幽居初夏', '陆游', '宋代', '湖山胜处放翁家，槐柳阴中野径斜。\n水满有时观下鹭，草深无处不鸣蛙。\n箨龙已过头番笋，木笔犹开第一花。\n叹息老来交旧尽，睡来谁共午瓯茶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '幽居初夏' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('多歧亡羊', '列御寇', '先秦', '杨子之邻人亡羊，既率其党，又请杨子之竖追之。杨子曰：“嘻！亡一羊何 追者之众？”邻人曰：“多歧路。”既反，问：“获羊乎？”曰：“亡之矣。” 曰：“奚亡之？”曰：“歧路之中又有歧焉。吾不知所之，所以反也。”杨子戚 然变容，不言者移时，不笑者竟日。门人怪之，请曰：“羊贱畜，又非夫子之有， 而损言笑者何哉？”杨子不答。(追者之众 一作：追之者众)\n\n　　心都子曰：“大道以多歧亡羊，学者以多方丧生。学 非本不同，非本不一，而末异若是。唯归同反一，为亡得丧。子长先生之门，习 先生之道，而不达先生之况也，哀哉！”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '多歧亡羊' AND p.poem_author = '列御寇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('北风行', '刘基', '明代', '城外萧萧北风起，城上健儿吹落耳。\n将军玉帐貂鼠衣，手持酒杯看雪飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '北风行' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无题四首', '李商隐', '唐代', '来是空言去绝踪，月斜楼上五更钟。\n梦为远别啼难唤，书被催成墨未浓。\n蜡照半笼金翡翠，麝熏微度绣芙蓉。\n刘郎已恨蓬山远，更隔蓬山一万重。\n\n飒飒东风细雨来，芙蓉塘外有轻雷。\n金蟾啮锁烧香入，玉虎牵丝汲井回。\n贾氏窥帘韩掾少，宓妃留枕魏王才。\n春心莫共花争发，一寸相思一寸灰。\n\n含情春晼晚，暂见夜阑干。\n楼响将登怯，帘烘欲过难。\n多羞钗上燕，真愧镜中鸾。\n归去横塘晓，华星送宝鞍。\n\n何处哀筝随急管，樱花永巷垂杨岸。\n东家老女嫁不售，白日当天三月半。\n溧阳公主年十四，清明暖后同墙看。\n归来展转到五更，梁间燕子闻长叹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无题四首' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苏小小墓', '李贺', '唐代', '幽兰露，如啼眼。\n无物结同心，烟花不堪剪。\n草如茵，松如盖。\n风为裳，水为佩。\n油壁车，夕相待。\n冷翠烛，劳光彩。\n西陵下，风吹雨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苏小小墓' AND p.poem_author = '李贺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南园十三首', '李贺', '唐代', '花枝草蔓眼中开，小白长红越女腮。\n可怜日暮嫣香落，嫁与春风不用媒。(其一)\n\n宫北田塍晓气酣，黄桑饮露窣宫帘。\n长腰健妇偷攀折，将喂吴王八茧蚕。(其二)\n\n竹里缲丝挑网车，青蝉独噪日光斜。\n桃胶迎夏香琥珀，自课越佣能种瓜。(其三)\n\n三十未有二十余，白日长饥小甲蔬。\n桥头长老相哀念，因遗戎韬一卷书。(其四)\n\n男儿何不带吴钩，收取关山五十州。\n请君暂上凌烟阁，若个书生万户侯？(其五)\n\n寻章摘句老雕虫，晓月当帘挂玉弓。\n不见年年辽海上，文章何处哭秋风？(其六)\n\n长卿牢落悲空舍，曼倩诙谐取自容。\n见买若耶溪水剑，明朝归去事猿公。(其七)\n\n春水初生乳燕飞，黄蜂小尾扑花归。\n窗含远色通书幌，鱼拥香钩近石矶。(其八)\n\n泉沙软卧鸳鸯暖，曲岸回篙舴艋迟。\n泻酒木栏椒叶盖，病容扶起种菱丝。(其九)\n\n边让今朝忆蔡邕，无心裁曲卧春风。\n舍南有竹堪书字，老去溪头作钓翁。(其十)\n\n长峦谷口倚嵇家，白昼千峰老翠华。\n自履藤鞋收石蜜，手牵苔絮长莼花。(其十一)\n\n松溪黑水新龙卵，桂洞生硝旧马牙。\n谁遣虞卿裁道帔，轻绡一匹染朝霞。(其十二)\n\n小树开朝径，长茸湿夜烟。\n柳花惊雪浦，麦雨涨溪田。\n古刹疏钟度，遥岚破月悬。\n沙头敲石火，烧竹照渔船。(其十三)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南园十三首' AND p.poem_author = '李贺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿桐庐江寄广陵旧游', '孟浩然', '唐代', '山暝闻猿愁，沧江急夜流。(闻 一作：听)\n风鸣两岸叶，月照一孤舟。\n建德非吾土，维扬忆旧游。\n还将两行泪，遥寄海西头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿桐庐江寄广陵旧游' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('子夜歌·人生愁恨何能免', '李煜', '五代', '人生愁恨何能免，销魂独我情何限！故国梦重归，觉来双泪垂。\n高楼谁与上？长记秋晴望。往事已成空，还如一梦中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '子夜歌·人生愁恨何能免' AND p.poem_author = '李煜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('立春日感怀', '于谦', '明代', '年去年来白发新，匆匆马上又逢春。\n关河底事空留客？岁月无情不贷人。\n一寸丹心图报国，两行清泪为思亲。\n孤怀激烈难消遣，漫把金盘簇五辛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '立春日感怀' AND p.poem_author = '于谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙·伏雨朝寒愁不胜', '纳兰性德', '清代', '伏雨朝寒愁不胜，那能还傍杏花行。去年高摘斗轻盈。\n漫惹炉烟双袖紫，空将酒晕一衫青。人间何处问多情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙·伏雨朝寒愁不胜' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆江南·衔泥燕', '牛峤', '唐代', '衔泥燕，飞到画堂前。占得杏梁安稳处，体轻唯有主人怜，堪羡好因缘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆江南·衔泥燕' AND p.poem_author = '牛峤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新凉', '徐玑', '宋代', '水满田畴稻叶齐，日光穿树晓烟低。\n黄莺也爱新凉好，飞过青山影里啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新凉' AND p.poem_author = '徐玑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塞下曲', '王昌龄', '唐代', '饮马渡秋水，水寒风似刀。\n平沙日未没，黯黯见临洮。\n昔日长城战，咸言意气高。\n黄尘足今古，白骨乱蓬蒿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塞下曲' AND p.poem_author = '王昌龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('离亭燕·一带江山如画', '张昪', '宋代', '一带江山如画，风物向秋潇洒。水浸碧天何处断？霁色冷光相射。蓼屿荻花洲，掩映竹篱茅舍。\n云际客帆高挂，烟外酒旗低亚。多少六朝兴废事，尽入渔樵闲话。怅望倚层楼，寒日无言西下。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '离亭燕·一带江山如画' AND p.poem_author = '张昪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆秦娥', '张元干', '宋代', '桃花萼。雨肥红绽东风恶。东风恶。长亭无寐，短书难托。 \n 征衫辜负深闺约。禁烟时候春罗薄。春罗薄。多应消瘦，可堪梳掠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆秦娥' AND p.poem_author = '张元干';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('摊破浣溪沙·病起萧萧两鬓华', '李清照', '宋代', '病起萧萧两鬓华，卧看残月上窗纱。豆蔻连梢煎熟水，莫分茶。\n枕上诗书闲处好，门前风景雨来佳。终日向人多酝藉，木犀花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '摊破浣溪沙·病起萧萧两鬓华' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元日', '温庭筠', '唐代', '神耀破氛昏，新阳入晏温。绪风调玉吹，端日应铜浑。 \n 威凤跄瑶簴，升龙护璧门。雨旸春令煦，裘冕晬容尊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元日' AND p.poem_author = '温庭筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词 / 宫中词', '朱庆馀', '唐代', '寂寂花时闭院门，美人相并立琼轩。 \n含情欲说宫中事，鹦鹉前头不敢言。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词 / 宫中词' AND p.poem_author = '朱庆馀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('钓鱼湾', '储光羲', '唐代', '垂钓绿湾春，春深杏花乱。\n潭清疑水浅，荷动知鱼散。\n日暮待情人，维舟绿杨岸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '钓鱼湾' AND p.poem_author = '储光羲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·唐风·羔裘', '佚名', '先秦', '羔裘豹祛，自我人居居。岂无他人？维子之故。\n羔裘豹褎，自我人究究。岂无他人？维子之好。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·唐风·羔裘' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金缕曲·赠梁汾', '纳兰性德', '清代', '德也狂生耳！偶然间、淄尘京国，乌衣门第。有酒惟浇赵州土，谁会成生此意？不信道、遂成知己。青眼高歌俱未老，向尊前、拭尽英雄泪。君不见，月如水。\n共君此夜须沉醉。且由他、娥眉谣诼，古今同忌。身世悠悠何足问，冷笑置之而已！寻思起、从头翻悔。一日心期千劫在，后身缘、恐结他生里。然诺重，君须记。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金缕曲·赠梁汾' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('遣悲怀三首·其一', '元稹', '唐代', '谢公最小偏怜女，自嫁黔娄百事乖。\n顾我无衣搜荩箧，泥他沽酒拔金钗。(荩箧 一作：画箧)\n野蔬充膳甘长藿，落叶添薪仰古槐。\n今日俸钱过十万，与君营奠复营斋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '遣悲怀三首·其一' AND p.poem_author = '元稹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和张仆射塞下曲六首', '卢纶', '唐代', '鹫翎金仆姑，燕尾绣蝥弧。\n独立扬新令，千营共一呼。\n\n林暗草惊风，将军夜引弓。\n平明寻白羽，没在石棱中。\n\n月黑雁飞高，单于夜遁逃。\n欲将轻骑逐，大雪满弓刀。\n\n野幕敞琼筵，羌戎贺劳旋。\n醉和金甲舞，雷鼓动山川。\n\n调箭又呼鹰，俱闻出世能。\n奔狐将迸雉，扫尽古丘陵。\n\n亭亭七叶贵，荡荡一隅清。\n他日题麟阁，唯应独不名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和张仆射塞下曲六首' AND p.poem_author = '卢纶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('燕歌行二首·其二', '曹丕', '魏晋', '别日何易会日难，山川悠远路漫漫。\n郁陶思君未敢言，寄声浮云往不还。\n涕零雨面毁形颜，谁能怀忧独不叹。\n展诗清歌仰自宽，乐往哀来摧肺肝。\n耿耿伏枕不能眠，披衣出户步东西。\n仰看星月观云间，飞鸽晨鸣声可怜，留连顾怀不能存。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '燕歌行二首·其二' AND p.poem_author = '曹丕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('唐多令·柳絮', '曹雪芹', '清代', '粉堕百花洲，香残燕子楼。一团团、逐队成球。飘泊亦如人命薄，空缱绻，说风流。\n草木也知愁，韶华竟白头。叹今生、谁舍谁收！嫁与东风春不管，凭尔去，忍淹留！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '唐多令·柳絮' AND p.poem_author = '曹雪芹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·醉别西楼醒不记', '晏几道', '宋代', '醉别西楼醒不记。春梦秋云，聚散真容易。斜月半窗还少睡。画屏闲展吴山翠。 \n衣上酒痕诗里字。点点行行，总是凄凉意。红烛自怜无好计。夜寒空替人垂泪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·醉别西楼醒不记' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚登三山还望京邑', '谢朓', '南北朝', '灞涘望长安，河阳视京县。\n白日丽飞甍，参差皆可见。\n余霞散成绮，澄江静如练。\n喧鸟覆春洲，杂英满芳甸。\n去矣方滞淫，怀哉罢欢宴。\n佳期怅何许，泪下如流霰。\n有情知望乡，谁能鬒不变？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚登三山还望京邑' AND p.poem_author = '谢朓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七夕', '罗隐', '唐代', '络角星河菡萏天，一家欢笑设红筵。\n应倾谢女珠玑箧，尽写檀郎锦绣篇。\n香帐簇成排窈窕，金针穿罢拜婵娟。\n铜壶漏报天将晓，惆怅佳期又一年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七夕' AND p.poem_author = '罗隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄外征衣', '陈玉兰', '唐代', '夫戍边关妾在吴，西风吹妾妾忧夫。\n一行书信千行泪，寒到君边衣到无？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄外征衣' AND p.poem_author = '陈玉兰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风入松·听风听雨过清明', '吴文英', '宋代', '听风听雨过清明。愁草瘗花铭。楼前绿暗分携路，一丝柳、一寸柔情。料峭春寒中酒，交加晓梦啼莺。 \n西园日日扫林亭。依旧赏新晴。黄蜂频扑秋千索，有当时、纤手香凝。惆怅双鸳不到，幽阶一夜苔生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风入松·听风听雨过清明' AND p.poem_author = '吴文英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青青陵上柏', '佚名', '两汉', '青青陵上柏，磊磊涧中石。\n人生天地间，忽如远行客。\n斗酒相娱乐，聊厚不为薄。\n驱车策驽马，游戏宛与洛。\n洛中何郁郁，冠带自相索。\n长衢罗夹巷，王侯多第宅。\n两宫遥相望，双阙百余尺。\n极宴娱心意，戚戚何所迫？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青青陵上柏' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆江南·多少泪', '李煜', '五代', '多少泪，沾袖复横颐。心事莫将和泪滴，凤笙休向月明吹，肠断更无疑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆江南·多少泪' AND p.poem_author = '李煜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吊白居易', '李忱', '唐代', '缀玉联珠六十年，谁教冥路作诗仙。\n浮云不系名居易，造化无为字乐天。\n童子解吟长恨曲，胡儿能唱琵琶篇。\n文章已满行人耳，一度思卿一怆然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吊白居易' AND p.poem_author = '李忱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('破窑赋 / 寒窑赋 / 劝世章', '吕蒙正', '宋代', '版本一\n\n　　天有不测风云，人有旦夕祸福。蜈蚣百足，行不及蛇；雄鸡两翼，飞不过鸦。马有千里之程，无骑不能自往；人有冲天之志，非运不能自通。\n\n　　盖闻：人生在世，富贵不能淫，贫贱不能移。文章盖世，孔子厄于陈邦；武略超群，太公钓于渭水。颜渊命短，殊非凶恶之徒；盗跖年长，岂是善良之辈。尧帝明圣，却生不肖之儿；瞽叟愚顽，反生大孝之子。张良原是布衣，萧何称谓县吏。晏子身无五尺，封作齐国宰相；孔明卧居草庐，能作蜀汉军师。楚霸虽雄，败于乌江自刎；汉王虽弱，竟有万里江山。李广有射虎之威，到老无封；冯唐有乘龙之才，一生不遇。韩信未遇之时，无一日三餐，及至遇行，腰悬三尺玉印，一旦时衰，死于阴人之手。\n\n　　有先贫而后富，有老壮而少衰。满腹文章，白发竟然不中；才疏学浅，少年及第登科。深院宫娥，运退反为妓妾；风流妓女，时来配作夫人。\n\n　　青春美女，却招愚蠢之夫；俊秀郎君，反配粗丑之妇。蛟龙未遇，潜水于鱼鳖之间；君子失时，拱手于小人之下。衣服虽破，常存仪礼之容；面带忧愁，每抱怀安之量。时遭不遇，只宜安贫守份；心若不欺，必然扬眉吐气。初贫君子，天然骨骼生成；乍富小人，不脱贫寒肌体。\n\n　　天不得时，日月无光；地不得时，草木不生；水不得时，风浪不平；人不得时，利运不通。注福注禄，命里已安排定，富贵谁不欲？人若不依根基八字，岂能为卿为相？\n\n　　吾昔寓居洛阳，朝求僧餐，暮宿破窖，思衣不可遮其体，思食不可济其饥，上人憎，下人厌，人道我贱，非我不弃也。今居朝堂，官至极品，位置三公，身虽鞠躬于一人之下，而列职于千万人之上，有挞百僚之杖，有斩鄙吝之剑，思衣而有罗锦千箱，思食而有珍馐百味，出则壮士执鞭，入则佳人捧觞，上人宠，下人拥。人道我贵，非我之能也，此乃时也、运也、命也。\n\n　　嗟呼！人生在世，富贵不可尽用，贫贱不可自欺，听由天地循环，周而复始焉。\n\n\n版本二\n\n　　天地有常用，日月有常明，四时有常序，鬼神有常灵。天有宝，日月星辰。地有宝，五谷金银。家有宝，孝子贤孙。国有宝，正直忠良。合天道，则天府鉴临。合地道，则地府消愆。合人道，则民用和睦。三道既合，祸去福来。天地和，则万物生。地道和，则万物兴。父子和，而家有济。夫妇和，而义不分。\n\n　　时势不可尽倚，贫穷不可尽欺，世事翻来覆去，须当周而复始。\n\n　　余者，居洛阳之时，朝投僧寺，夜宿破窑。布衣不能遮其体，饘粥不能充其饥。上人嫌，下人憎，皆言余之贱也，余曰：非贱也，乃时也，运也，命也。余后登高及第，入中书，官至极品，位列三公，思衣则有绮罗千箱，思食则有百味珍馐，有挞百僚之杖，有斩佞臣之剑，出则壮士执鞭，入则佳人扶袂，廪有余粟，库有余财，人皆言余之贵也，余曰：非贵也，乃时也，运也，命也。\n\n　　蛟龙未遇，暂居云雾之间。君子失时，屈守小人之下。命运未通，被愚人之轻弃。时运未到，被小人之欺凌。初贫君子，自怨骨格风流。乍富小人，不脱俗人体态。生平结交惟结心，莫论富贵贫贱。深得千金，而不为贵，得人一语，而胜千金。吾皆悼追无恨人，富贵须当长保守，\n\n　　苏秦未遇，归家时，父母憎，兄弟恶，嫂不下玑，妻不愿炊，然衣锦归故里，马壮人强，萤光彩布，兄弟含笑出户迎，妻嫂下阶倾己顾，苏秦本是旧苏秦，昔日何陈今何亲。自家骨肉尚如此，何况区区陌路人，抑犹未也。\n\n　　文章冠世，孔子尚厄于陈邦。武略超群，太公曾钓于渭水。颜回命短，岂是凶暴之徒。盗柘年长，自非贤良之辈。帝尧天圣，却养不肖之男。瞽叟顽嚣，反生大孝之子。甘罗十二为宰相，买臣五十作公卿。晏婴身长五尺，封为齐国宰相。韩信力无缚鸡，立为汉朝贤臣，未遇之时，口无一日瓮飧，及至兴通，身受齐王将印，吓燕取赵，统百万雄兵，一旦时休，卒于阴人之毒手。李广有射虎之威，到老无封。冯唐有安邦之志，一世无遇。\n\n　　上古圣贤，不掌阴阳之数。今日儒士，岂离否泰之中。腰金衣紫，都生贫贱之家。草履毛鞋，都是富豪之裔。有贫贱，而后有富贵。有小壮，而后有老衰。人能学积善，家有余庆。青春美女，反招愚独之夫。俊秀才郎，竟配丑貌之妇。五男二女，老来一身全无。万贯千金，死后离乡别井。才疏学浅，少年及第登科。满腹文章，到老终身不第。或富贵，或贫贱，皆由命理注定。\n\n　　若天不得时，则日月无光。地不得时，则草木不生。水不得时，则波浪不静。人不得时，则命运不通。若无根本八字，岂能为卿为相。一生皆由命，半点不由人。\n\n　　蜈蚣多足，不及蛇灵。雄鸡有翼，飞不及鸦。马有千里之驰，非人不能自往。人有千般巧计，无运不能自达。\n\n　　吾敬为此劝世文也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '破窑赋 / 寒窑赋 / 劝世章' AND p.poem_author = '吕蒙正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('言志', '唐寅', '明代', '不炼金丹不坐禅，不为商贾不耕田。\n闲来写就青山卖，不使人间造孽钱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '言志' AND p.poem_author = '唐寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('如梦令·道是梨花不是', '严蕊', '宋代', '道是梨花不是。\n道是杏花不是。\n白白与红红，别是东风情味。\n曾记，曾记，人在武陵微醉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '如梦令·道是梨花不是' AND p.poem_author = '严蕊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔家傲·小雨纤纤风细细', '朱服', '宋代', '小雨纤纤风细细，万家杨柳青烟里。恋树湿花飞不起，愁无比，和春付与东流水。\n九十光阴能有几？金龟解尽留无计。寄语东阳沽酒市，拼一醉，而今乐事他年泪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔家傲·小雨纤纤风细细' AND p.poem_author = '朱服';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('燕山亭·北行见杏花', '赵佶', '宋代', '裁剪冰绡，轻叠数重，淡著胭脂匀注。新样靓妆，艳溢香融，羞杀蕊珠宫女。易得凋零，更多少、无情风雨。愁苦。闲院落凄凉，几番春暮。（闲院 一作：问院)\n凭寄离恨重重，者双燕，何曾会人言语。天遥地远，万水千山，知他故宫何处。怎不思量，除梦里、有时曾去。无据，和梦也新来不做。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '燕山亭·北行见杏花' AND p.poem_author = '赵佶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('踏莎行·小径红稀', '晏殊', '宋代', '小径红稀，芳郊绿遍。高台树色阴阴见。春风不解禁杨花，蒙蒙乱扑行人面。(蒙 通：濛)\n翠叶藏莺，朱帘隔燕。炉香静逐游丝转。一场愁梦酒醒时，斜阳却照深深院。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '踏莎行·小径红稀' AND p.poem_author = '晏殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别离', '陆龟蒙', '唐代', '丈夫非无泪，不洒离别间。\n杖剑对尊酒，耻为游子颜。\n蝮蛇一螫手，壮士即解腕。\n所志在功名，离别何足叹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别离' AND p.poem_author = '陆龟蒙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无题·凤尾香罗薄几重', '李商隐', '唐代', '凤尾香罗薄几重，碧文圆顶夜深缝。\n扇裁月魄羞难掩，车走雷声语未通。\n曾是寂寥金烬暗，断无消息石榴红。\n斑骓只系垂杨岸，何处西南任好风。(任 一作：待)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无题·凤尾香罗薄几重' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('旅宿', '杜牧', '唐代', '旅馆无良伴，凝情自悄然。\n寒灯思旧事，断雁警愁眠。\n远梦归侵晓，家书到隔年。\n沧江好烟月，门系钓鱼船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '旅宿' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('嘲王历阳不肯饮酒', '李白', '唐代', '地白风色寒，雪花大如手。笑杀陶渊明，不饮杯中酒。 \n浪抚一张琴，虚栽五株柳。空负头上巾，吾于尔何有。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '嘲王历阳不肯饮酒' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('初入淮河四绝句·其三', '杨万里', '宋代', '两岸舟船各背驰，波痕交涉亦难为。\n只余鸥鹭无拘管，北去南来自在飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '初入淮河四绝句·其三' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('相见欢·金陵城上西楼', '朱敦儒', '宋代', '金陵城上西楼，倚清秋。万里夕阳垂地，大江流。\n中原乱，簪缨散，几时收？试倩悲风吹泪，过扬州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '相见欢·金陵城上西楼' AND p.poem_author = '朱敦儒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('更漏子·柳丝长', '晏几道', '宋代', '柳丝长，桃叶小。深院断无人到。红日淡，绿烟晴。流莺三两声。 \n雪香浓，檀晕少。枕上卧枝花好。春思重，晓妆迟。寻思残梦时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '更漏子·柳丝长' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠白马王彪·并序', '曹植', '魏晋', '黄初四年五月，白马王、任城王与余俱朝京师、会节气。到洛阳，任城王薨。至七月，与白马王还国。后有司以二王归藩，道路宜异宿止，意毒恨之。盖以大别在数日，是用自剖，与王辞焉，愤而成篇。\n\n　　谒帝承明庐，逝将归旧疆。清晨发皇邑，日夕过首阳。伊洛广且深，欲济川无梁。泛舟越洪涛，怨彼东路长。顾瞻恋城阙，引领情内伤。\n\n　　太谷何寥廓，山树郁苍苍。霖雨泥我涂，流潦浩纵横。中逵绝无轨，改辙登高岗。修坂造云日，我马玄以黄。\n\n　　玄黄犹能进，我思郁以纡。郁纡将何念，亲爱在离居。本图相与偕，中更不克俱。鸱枭鸣衡轭，豺狼当路衢。苍蝇间白黑，谗巧令亲疏。欲还绝无蹊，揽辔止踟蹰。(衡轭 通：衡扼)\n\n　　踟蹰亦何留？相思无终极。秋风发微凉，寒蝉鸣我侧。原野何萧条，白日忽西匿。归鸟赴乔林，翩翩厉羽翼。孤兽走索群，衔草不遑食。感物伤我怀，抚心长太息。\n\n　　太息将何为，天命与我违。奈何念同生，一往形不归。孤魂翔故域，灵柩寄京师。存者忽复过，亡殁身自衰。人生处一世，去若朝露晞。年在桑榆间，影响不能追。自顾非金石，咄唶令心悲。\n\n　　心悲动我神，弃置莫复陈。丈夫志四海，万里犹比邻。恩爱苟不亏，在远分日亲。何必同衾帱，然后展慇懃。忧思成疾疢，无乃儿女仁。仓卒骨肉情，能不怀苦辛？\n\n　　苦辛何虑思，天命信可疑。虚无求列仙，松子久吾欺。变故在斯须，百年谁能持？离别永无会，执手将何时？王其爱玉体，俱享黄髪期。收泪即长路，援笔从此辞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠白马王彪·并序' AND p.poem_author = '曹植';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登楼赋', '王粲', '两汉', '登兹楼以四望兮，聊暇日以销忧。览斯宇之所处兮，实显敞而寡仇。挟清漳之通浦兮， 倚曲沮之长洲。背坟衍之广陆兮，临皋隰之沃流。北弥陶牧，西接昭邱。华实蔽野，黍稷盈 畴。虽信美而非吾土兮，曾何足以少留！\n\n　　遭纷浊而迁逝兮，漫逾纪以迄今。情眷眷而怀归兮，孰忧思之可任？凭轩槛以遥望兮， 向北风而开襟。平原远而极目兮，蔽荆山之高岑。路逶迤而修迥兮，川既漾而济深。悲旧乡 之壅隔兮，涕横坠而弗禁。昔尼父之在陈兮，有归欤之叹音。钟仪幽而楚奏兮，庄舄显而越 吟。人情同于怀土兮，岂穷达而异心！\n\n　　惟日月之逾迈兮，俟河清其未极。冀王道之一平兮，假高衢而骋力。惧匏瓜之徒悬兮， 畏井渫之莫食。步栖迟以徙倚兮，白日忽其将匿。风萧瑟而并兴兮，天惨惨而无色。兽狂顾 以求群兮，鸟相鸣而举翼，原野阒其无人兮，征夫行而未息。心凄怆以感发兮，意忉怛而惨恻。循阶除而下降兮，气交愤于胸臆。夜参半而不寐兮，怅盘桓以反侧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登楼赋' AND p.poem_author = '王粲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重阳席上赋白菊', '白居易', '唐代', '满园花菊郁金黄，中有孤丛色似霜。 \n还似今朝歌酒席，白头翁入少年场。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重阳席上赋白菊' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洛桥晚望', '孟郊', '唐代', '天津桥下冰初结，洛阳陌上人行绝。 \n榆柳萧疏楼阁闲，月明直见嵩山雪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洛桥晚望' AND p.poem_author = '孟郊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('端午日赐衣', '杜甫', '唐代', '宫衣亦有名，端午被恩荣。细葛含风软，香罗叠雪轻。 \n自天题处湿，当暑著来清。意内称长短，终身荷圣情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '端午日赐衣' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵望汉江', '李白', '唐代', '汉江回万里，派作九龙盘。\n横溃豁中国，崔嵬飞迅湍。\n六帝沦亡后，三吴不足观。\n我君混区宇，垂拱众流安。\n今日任公子，沧浪罢钓竿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵望汉江' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雄雉', '佚名', '先秦', '雄雉于飞，泄泄其羽。我之怀矣，自诒伊阻。\n雄雉于飞，下上其音。展矣君子，实劳我心。\n瞻彼日月，悠悠我思。道之云远，曷云能来？\n百尔君子，不知德行。不忮不求，何用不臧？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雄雉' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头·题西山秋爽图', '纳兰性德', '清代', '空山梵呗静，水月影俱沉。悠然一境人外，都不许尘侵。岁晚忆曾游处，犹记半竿斜照，一抹界疏林。绝顶茅庵里，老衲正孤吟。\n云中锡，溪头钓，涧边琴。此生著几两屐，谁识卧游心？准拟乘风归去，错向槐安回首，何日得投簪。布袜青鞋约，但向画图寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头·题西山秋爽图' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王勃故事', '宋祁', '宋代', '九月九日都督大宴滕王阁，宿命其婿作序以夸客，因出纸笔遍请客，莫敢当，至勃，泛然不辞。都督怒，起更衣，遣吏伺其文辄报。一再报，语益奇，乃矍然曰：“天才也!”请遂成文，极欢罢。勃属文，初不精思，先磨墨数升，则酣饮，引被覆面卧，及寤，援笔成篇，不易一字，时人谓勃为腹稿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '王勃故事' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('潇湘神·斑竹枝', '刘禹锡', '唐代', '斑竹枝，斑竹枝，泪痕点点寄相思。楚客欲听瑶瑟怨，潇湘深夜月明时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '潇湘神·斑竹枝' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出郊', '杨慎', '明代', '高田如楼梯，平田如棋局。\n白鹭忽飞来，点破秧针绿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出郊' AND p.poem_author = '杨慎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('骤雨打新荷', '元好问', '金朝', '绿叶阴浓，遍池亭水阁，偏趁凉多。\n海榴初绽，朵朵簇红罗。\n老燕携雏弄语，有高柳鸣蝉相和。\n骤雨过，珍珠乱撒，打遍新荷。\n人生百年有几，念良辰美景，休放虚过。\n穷通前定，何用苦张罗。\n命友邀宾玩赏，对芳樽浅酌低歌。\n且酩酊，任他两轮日月，来往如梭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '骤雨打新荷' AND p.poem_author = '元好问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十二月十五夜', '袁枚', '清代', '沉沉更鼓急，渐渐人声绝。\n吹灯窗更明，月照一天雪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十二月十五夜' AND p.poem_author = '袁枚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('少年游·润州作', '苏轼', '宋代', '去年相送，余杭门外，飞雪似杨花。今年春尽，杨花似雪，犹不见还家。\n对酒卷帘邀明月，风露透窗纱。恰似姮娥怜双燕，分明照、画梁斜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '少年游·润州作' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平调·其三', '李白', '唐代', '名花倾国两相欢，长得君王带笑看。\n解释春风无限恨，沉香亭北倚阑干。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平调·其三' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留别王侍御维 / 留别王维', '孟浩然', '唐代', '寂寂竟何待，朝朝空自归。欲寻芳草去，惜与故人违。\n当路谁相假，知音世所稀。只应守寂寞，还掩故园扉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留别王侍御维 / 留别王维' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·庭院深深深几许', '李清照', '宋代', '欧阳公作《蝶恋花》，有“深深深几许”之句，予酷爱之。用其语作“庭院深深”数阕，其声即旧《临江仙》也。\n\n庭院深深深几许？云窗雾阁常扃。柳梢梅萼渐分明。春归秣陵树，人老建康城。\n感月吟风多少事，如今老去无成。谁怜憔悴更凋零。试灯无意思，踏雪没心情。(试灯无意思，踏雪没心情 一作：灯花空结蕊，离别共伤情)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·庭院深深深几许' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('神童诗', '汪洙', '宋代', '天子重英豪，文章教尔曹；\n万般皆下品，惟有读书高。\n少小须勤学，文章可立身；\n满朝朱紫贵，尽是读书人。\n学问勤中得，萤窗万卷书；\n三冬今足用，谁笑腹空虚。\n自小多才学，平生志气高；\n别人怀宝剑，我有笔如刀。\n朝为田舍郎，暮登天子堂；\n将相本无种，男儿当自强。\n学乃身之宝，儒为席上珍；\n君看为宰相，必用读书人。\n莫道儒冠误，诗书不负人；\n达而相天下，穷则善其身。\n遗子满赢金，何如教一经；\n姓名书锦轴，朱紫佐朝廷。\n古有千文义，须知学后通；\n圣贤俱间出，以此发蒙童。\n神童衫子短．袖大惹春风；\n未去朝天子，先来谒相公。\n年纪虽然小，文章日渐多；\n待看十五六，一举便登科。\n大比因时举，乡书以类升；\n名题仙桂籍，天府快先登。\n喜中青钱选，才高压俊英；\n萤窗新脱迹，雁塔早题名。\n年小初登第，皇都得意回；\n禹门三级浪，平地一声雷。\n一举登科目，双亲未老时；\n锦衣归故里，端的是男儿。\n玉殿传金榜，君恩赐状头；\n英雄三百辈，附我步瀛洲。\n慷慨丈夫志，生当忠孝门；\n为官须作相，及第必争先。\n宫殿召绕耸，街衢竞物华；\n风云今际会，千古帝王家。\n日月光天德，山河壮帝居；\n太平无以报，愿上万年书。\n久旱逢甘雨，他乡遇故知；\n洞房花烛夜，金榜题名时。\n土脉阳和动，韶华满眼新；\n一支梅破腊，万象渐回春。\n柳色浸衣绿，桃花映酒红；\n长安游冶子，日日醉春风。\n淑景余三月，莺花已半稀；\n浴沂谁氏子，三叹咏而归。\n数点雨余雨，一番寒食寒；\n杜鹃花发处，血泪染成丹。\n春到清明好，晴天锦绣纹；\n年年当此节，底事雨纷纷。\n风阁黄昏夜，开轩内晚凉；\n月华在户白，何处递荷香？\n一雨初收霁，金风特送凉；\n书窗应自爽，灯火夜偏长。\n庭下陈瓜果，云端闻彩车；\n争如郝隆子，只晒腹中书。\n九日龙山饮，黄花笑逐臣；\n醉看风落帽，舞爱月留人。\n昨日登高罢，今朝再举觞；\n菊荷何太苦，遭此两重阳。\n北帝方行令，天晴爱日和；\n农工新筑土，天庆纳嘉禾。\n檐外三竿日，新添一线长；\n登台观气象，云物喜呈祥。\n冬天更筹尽，春附斗柄回；\n寒暄一夜隔，客鬓两年催。\n解落三秋叶，能开二月花；\n过江千尺浪，入竹万杆斜。\n人在艳阳中，桃花映面红；\n年年二三月，底事笑春风。\n院落沉沉晓，花开白雪香；\n一枝轻带雨，泪湿贵妃妆。\n枝缀霜葩白，无言笑晓凤；\n清芳谁是侣，色间小桃红。\n倾国姿容别，多开富贵家；\n临轩一赏后，轻薄万千花。\n墙角一枝梅，凌寒独自开；\n遥知不是雪，为有暗香来。\n柯干如金石，心坚耐岁寒；\n平生谁结友，宜共竹松看。\n居可无君子，交情耐岁寒；\n春风频动处，日日报平安。\n春水满泗泽，夏云多奇峰；\n秋月扬明辉，冬岭秀孤松。\n诗酒琴棋客，风花雪月天；\n有名闲富贵，无事散神仙。\n道院迎仙客，书道隐相儒；\n庭裁栖凤竹，池养化龙鱼。\n春游芳草地，夏赏绿荷池；\n秋饮黄花酒，冬吟白雪诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '神童诗' AND p.poem_author = '汪洙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('对楚王问', '宋玉', '先秦', '楚襄王问于宋玉曰：“先生其有遗行与？何士民众庶不誉之甚也！”\n\n　　宋玉对曰：“唯，然，有之！愿大王宽其罪，使得毕其辞。客有歌于郢中者，其始曰《下里》、《巴人》，国中属而和者数千人。其为《阳阿》、《薤露》，国中属而和者数百人。其为《阳春》、《白雪》，国中有属而和者，不过数十人。引商刻羽，杂以流徵，国中属而和者，不过数人而已。是其曲弥高，其和弥寡。\n\n　　故鸟有凤而鱼有鲲。凤皇上击九千里，绝云霓，负苍天，足乱浮云，翱翔乎杳冥之上。夫蕃篱之鷃，岂能与之料天地之高哉？鲲鱼朝发昆仑之墟，暴鬐于碣石，暮宿于孟诸。夫尺泽之鲵，岂能与之量江海之大哉？故非独鸟有凤而鱼有鲲，士亦有之。夫圣人瑰意琦行，超然独处，世俗之民，又安知臣之所为哉？”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '对楚王问' AND p.poem_author = '宋玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('木兰花·城上风光莺语乱', '钱惟演', '宋代', '城上风光莺语乱，城下烟波春拍岸。绿杨芳草几时休，泪眼愁肠先已断。\n情怀渐觉成衰晚，鸾镜朱颜惊暗换。昔年多病厌芳尊，今日芳尊惟恐浅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '木兰花·城上风光莺语乱' AND p.poem_author = '钱惟演';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐·采芳人杳', '张炎', '宋代', '采芳人杳，顿觉游情少。客里看春多草草，总被诗愁分了。\n去年燕子天涯，今年燕子谁家？ 三月休听夜雨，如今不是催花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐·采芳人杳' AND p.poem_author = '张炎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢池春·壮岁从戎', '陆游', '宋代', '壮岁从戎，曾是气吞残虏。阵云高、狼烽夜举。朱颜青鬓，拥雕戈西戍。笑儒冠、自来多误。 \n功名梦断，却泛扁舟吴楚。漫悲歌、伤怀吊古。烟波无际，望秦关何处。叹流年、又成虚度。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢池春·壮岁从戎' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长安晚秋 / 秋望 / 秋夕', '赵嘏', '唐代', '云雾凄凉拂曙流，汉家宫阙动高秋。\n残星几点雁横塞，长笛一声人倚楼。\n紫艳半开篱菊静，红衣落尽渚莲愁。\n鲈鱼正美不归去，空戴南冠学楚囚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长安晚秋 / 秋望 / 秋夕' AND p.poem_author = '赵嘏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山行留客', '张旭', '唐代', '山光物态弄春辉，莫为轻阴便拟归。 \n纵使晴明无雨色，入云深处亦沾衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山行留客' AND p.poem_author = '张旭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出其东门', '佚名', '先秦', '出其东门，有女如云。虽则如云，匪我思存。缟衣綦巾，聊乐我员。\n出其闉闍，有女如荼。虽则如荼，匪我思且。缟衣茹藘，聊可与娱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出其东门' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('伶官传序', '欧阳修', '宋代', '呜呼！盛衰之理，虽曰天命，岂非人事哉！原庄宗之所以得天下，与其所以失之者，可以知之矣。\n\n　　世言晋王之将终也，以三矢赐庄宗而告之曰：“梁，吾仇也；燕王，吾所立，契丹与吾约为兄弟，而皆背晋以归梁。此三者，吾遗恨也。与尔三矢，尔其无忘乃父之志！”庄宗受而藏之于庙。其后用兵，则遣从事以一少牢告庙，请其矢，盛以锦囊，负而前驱，及凯旋而纳之。\n\n　　方其系燕父子以组，函梁君臣之首，入于太庙，还矢先王，而告以成功，其意气之盛，可谓壮哉！及仇雠已灭，天下已定，一夫夜呼，乱者四应，仓皇东出，未及见贼而士卒离散，君臣相顾，不知所归，至于誓天断发，泣下沾襟，何其衰也！岂得之难而失之易欤？抑本其成败之迹， 而皆自于人欤？《书》曰：“满招损，谦受益。” 忧劳可以兴国，逸豫可以亡身，自然之理也。\n\n　　故方其盛也，举天下豪杰，莫能与之争；及其衰也，数十伶人困之，而身死国灭，为天下笑。夫祸患常积于忽微，而智勇多困于所溺，岂独伶人也哉！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '伶官传序' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哀郢', '屈原', '先秦', '皇天之不纯命兮，何百姓之震愆。\n民离散而相失兮，方仲春而东迁。\n去故乡而就远兮，遵江夏以流亡。\n出国门而轸怀兮，甲之朝吾以行。\n发郢都而去闾兮，怊荒忽之焉极。\n楫齐杨以容与兮，哀见君而不再得。\n望长楸而太息兮，涕淫淫其若霰。\n过夏首而西浮兮，顾龙门而不见。\n心婵媛而伤怀兮，眇不知其所蹠。\n顺风波以从流兮，焉洋洋而为客。\n凌阳侯之泛滥兮，忽翱翔之焉薄。\n心絓结而不解兮，思蹇产而不释。\n将运舟而下浮兮，上洞庭而下江。\n去终古之所居兮，今逍遥而来东。\n羌灵魂之欲归兮，何须臾而忘反。\n背夏浦而西思兮，哀故都之日远。\n登大坟以远望兮，聊以舒吾忧心。\n哀州土之平乐兮，悲江介之遗风。\n当陵阳之焉至兮，淼南渡之焉如。\n曾不知夏之为丘兮，孰两东门之可芜。\n心不怡之长久兮，忧与愁其相接。\n惟郢路之辽远兮，江与夏之不可涉。\n忽若去不信兮，至今九年而不复。\n惨郁郁而不通兮，蹇侘傺而含戚。\n外承欢之汋约兮，谌荏弱而难持。\n忠湛湛而愿进兮，妒被离而障之。\n尧舜之抗行兮，瞭杳杳而薄天。\n众谗人之嫉妒兮，被以不慈之伪名。\n憎愠惀之修美兮，好夫人之慷慨。\n众踥蹀而日进兮，美超远而逾迈。\n乱曰：曼余目以流观兮，冀一反之何时。\n鸟飞反故乡兮，狐死必首丘。\n信非吾罪而弃逐兮，何日夜而忘之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哀郢' AND p.poem_author = '屈原';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('朝中措·平山堂', '欧阳修', '宋代', '平山栏槛倚晴空，山色有无中。\n手种堂前垂柳，别来几度春风？\n文章太守，挥毫万字，一饮千钟。\n行乐直须年少，尊前看取衰翁。(\n\'尊\'前, 通：樽)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '朝中措·平山堂' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('声声慢', '王沂孙', '宋代', '高寒户牖，虚白尊罍，千山尽入孤光。玉影如空，天葩暗落清香。平生此兴不浅，记当年、独据胡床。怎知道，是岁华换却，处处堪伤。 \n 已是南楼曲断，纵疏花淡月，也只凄凉。冷雨斜风，何况独掩西窗。天涯故人总老，谩相思、永夜相望。断梦远，趁秋声、一片渡江。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '声声慢' AND p.poem_author = '王沂孙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('不见', '杜甫', '唐代', '不见李生久，佯狂真可哀。\n世人皆欲杀，吾意独怜才。\n敏捷诗千首，飘零酒一杯。\n匡山读书处，头白好归来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '不见' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿业师山房期丁大不至 / 宿业师山房待丁大不至', '孟浩然', '唐代', '夕阳度西岭，群壑倏已暝。\n松月生夜凉，风泉满清听。\n樵人归欲尽，烟鸟栖初定。\n之子期宿来，孤琴候萝径。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿业师山房期丁大不至 / 宿业师山房待丁大不至' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·郑风·有女同车', '佚名', '先秦', '有女同车，颜如舜华。将翱将翔，佩玉琼琚。彼美孟姜，洵美且都。\n有女同行，颜如舜英。将翱将翔，佩玉将将。彼美孟姜，德音不忘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·郑风·有女同车' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('唐雎说信陵君', '佚名', '先秦', '信陵君杀晋鄙，救邯郸，破秦人，存赵国，赵王自郊迎。\n\n　　唐雎谓信陵君曰：“臣闻之曰：事有不可知者，有不可不知者；有不可忘者，有不可不忘者。”信陵君曰：“何谓也？”对曰：“人之憎我也，不可不知也；吾憎人也，不可得而知也。人之有德于我也，不可忘也；吾有德于人也，不可不忘也。今君杀晋鄙，救邯郸，破秦人，存赵国，此大德也。今赵王自郊迎，卒然见赵王，愿君之忘之也。”信陵君曰：“无忌谨受教。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '唐雎说信陵君' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('己亥杂诗（三百十五首选四）', '龚自珍', '清代', '其八\n太行一脉走蝹蜿，莽莽畿西虎气蹲。\n送我摇鞭竟东去，此山不语看中原。\n\n其八十三\n只筹一缆十夫多，细算千艘渡此河。\n我亦曾穈太仓粟，夜闻邪许泪滂沱！\n（五月十二日抵淮埔作）\n\n其八十七\n故人横海拜将军，侧立南天未蕆勋。\n我有阴符三百字，蜡丸难寄惜雄文。\n\n其一百三十\n陶潜酷似卧龙豪，万古浔阳松菊高；\n莫信诗人竟平淡，二分梁甫一分骚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '己亥杂诗（三百十五首选四）' AND p.poem_author = '龚自珍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('踏莎行·自沔东来丁未元日至金陵江上感梦而作', '姜夔', '宋代', '燕燕轻盈，莺莺娇软，分明又向华胥见。夜长争得薄情知？春初早被相思染。\n别后书辞，别时针线，离魂暗逐郎行远。淮南皓月冷千山，冥冥归去无人管。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '踏莎行·自沔东来丁未元日至金陵江上感梦而作' AND p.poem_author = '姜夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('思远人·红叶黄花秋意晚', '晏几道', '宋代', '红叶黄花秋意晚，千里念行客。飞云过尽，归鸿无信，何处寄书得。 \n泪弹不尽临窗滴。就砚旋研墨。渐写到别来，此情深处，红笺为无色。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '思远人·红叶黄花秋意晚' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·海燕双来归画栋', '欧阳修', '宋代', '海燕双来归画栋。帘影无风，花影频移动。半醉腾腾春睡重。绿鬟堆枕香云拥。 \n翠被双盘金缕凤。忆得前春，有个人人共。花里黄莺时一弄。日斜惊起相思梦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·海燕双来归画栋' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怨歌行', '班婕妤', '两汉', '新裂齐纨素，皎洁如霜雪。\n裁为合欢扇，团团似明月。\n出入君怀袖，动摇微风发。\n常恐秋节至，凉飙夺炎热。\n弃捐箧笥中，恩情中道绝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怨歌行' AND p.poem_author = '班婕妤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史二首·其二', '李商隐', '唐代', '历览前贤国与家，成由勤俭破由奢。\n何须琥珀方为枕，岂得真珠始是车。\n远去不逢青海马，力穷难拔蜀山蛇。\n几人曾预南薰曲，终古苍梧哭翠华。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史二首·其二' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('马诗二十三首', '李贺', '唐代', '龙脊贴连钱，银蹄白踏烟。\n无人织锦韂，谁为铸金鞭。\n\n腊月草根甜，天街雪似盐。\n未知口硬软，先拟蒺藜衔。\n\n忽忆周天子，驱车上玉山。\n鸣驺辞凤苑，赤骥最承恩。\n\n此马非凡马，房星本是星。\n向前敲瘦骨，犹自带铜声。\n\n大漠沙如雪，燕山月似钩。\n何当金络脑，快走踏清秋。\n\n饥卧骨查牙，粗毛刺破花。\n鬣焦珠色落，发断锯长麻。\n\n西母酒将阑，东王饭已干。\n君王若燕去，谁为曳车辕？\n\n赤兔无人用，当须吕布骑。\n吾闻果下马，羁策任蛮儿。\n\n飂叔去匆匆，如今不豢龙。\n夜来霜压栈，骏骨折西风。\n\n催榜渡乌江，神骓泣向风。\n君王今解剑，何处逐英雄？\n\n内马赐宫人，银鞯刺麒麟。\n午时盐坂上，蹭蹬溘风尘。\n\n批竹初攒耳，桃花未上身。\n他时须搅阵，牵去借将军。\n\n宝玦谁家子，长闻侠骨香。\n堆金买骏骨，将送楚襄王。\n\n香幞赭罗新，盘龙蹙蹬鳞。\n回看南陌上，谁道不逢春？\n\n不从桓公猎，何能伏虎威？\n一朝沟陇出，看取拂云飞。\n\n唐剑斩隋公，拳毛属太宗。\n莫嫌金甲重，且去捉飘风。\n\n白铁锉青禾，砧间落细莎。\n世人怜小颈，金埒畏长牙。\n\n伯乐向前看，旋毛在腹间。\n只今掊白草，何日蓦青山？\n\n萧寺驮经马，元从竺国来。\n空知有善相，不解走章台。\n\n重围如燕尾，宝剑似鱼肠。\n欲求千里脚，先采眼中光。\n\n暂系腾黄马，仙人上彩楼。\n须鞭玉勒吏，何事谪高州？\n\n汉血到王家，随鸾撼玉珂。\n少君骑海上，人见是青骡。\n\n武帝爱神仙，烧金得紫烟。\n厩中皆肉马，不解上青天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '马诗二十三首' AND p.poem_author = '李贺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('北风', '佚名', '先秦', '北风其凉，雨雪其雱。惠而好我，携手同行。其虚其邪？既亟只且！\n北风其喈，雨雪其霏。惠而好我，携手同归。其虚其邪？既亟只且！\n莫赤匪狐，莫黑匪乌。惠而好我，携手同车。其虚其邪？既亟只且！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '北风' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上枢密韩太尉书', '苏辙', '宋代', '太尉执事：辙生好为文，思之至深。以为文者气之所形，然文不可以学而能，气可以养而致。孟子曰：“我善养吾浩然之气。”今观其文章，宽厚宏博，充乎天地之间，称其气之小大。太史公行天下，周览四海名山大川，与燕、赵间豪俊交游，故其文疏荡，颇有奇气。此二子者，岂尝执笔学为如此之文哉？其气充乎其中而溢乎其貌，动乎其言而见乎其文，而不自知也。\n　　辙生十有九年矣。其居家所与游者，不过其邻里乡党之人；所见不过数百里之间，无高山大野可登览以自广；百氏之书，虽无所不读，然皆古人之陈迹，不足以激发其志气。恐遂汩没，故决然舍去，求天下奇闻壮观，以知天地之广大。过秦、汉之故都，恣观终南、嵩、华之高，北顾黄河之奔流，慨然想见古之豪杰。至京师，仰观天子宫阙之壮，与仓廪、府库、城池、苑囿之富且大也，而后知天下之巨丽。见翰林欧阳公，听其议论之宏辩，观其容貌之秀伟，与其门人贤士大夫游，而后知天下之文章聚乎此也。太尉以才略冠天下，天下之所恃以无忧，四夷之所惮以不敢发，入则周公、召公，出则方叔、召虎。而辙也未之见焉。\n　　且夫人之学也，不志其大，虽多而何为？辙之来也，于山见终南、嵩、华之高，于水见黄河之大且深，于人见欧阳公，而犹以为未见太尉也。故愿得观贤人之光耀，闻一言以自壮，然后可以尽天下之大观而无憾者矣。\n　　辙年少，未能通习吏事。向之来，非有取于斗升之禄，偶然得之，非其所乐。然幸得赐归待选，使得优游数年之间，将以益治其文，且学为政。太尉苟以为可教而辱教之，又幸矣！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上枢密韩太尉书' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春雁', '王恭', '明代', '春风一夜到衡阳，楚水燕山万里长。\n莫道春来便归去，江南虽好是他乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春雁' AND p.poem_author = '王恭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虎求百兽', '刘向', '两汉', '荆宣王问群臣曰：“吾闻北方之畏昭奚恤也，果诚何如？”群臣莫对。\n江乙对曰：“虎求百兽而食之，得狐。狐曰：‘子无敢食我也！天帝使我长百兽。今子食我，是逆天帝命也！子以我为不信，吾为子先行，子随我后，观百兽之见我而敢不走乎？”虎以为然，故遂与之行。兽见之，皆走。虎不知兽畏己而走也，以为畏狐也。\n今王之地五千里，带甲百万，而专属之于昭奚恤，故北方之畏奚恤也，其实畏王之甲兵也！犹百兽之畏虎也！”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '虎求百兽' AND p.poem_author = '刘向';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐·春晚', '王安国', '宋代', '留春不住，费尽莺儿语。满地残红宫锦污，昨夜南园风雨。\n小怜初上琵琶，晓来思绕天涯。不肯画堂朱户，春风自在杨花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐·春晚' AND p.poem_author = '王安国';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑子·清明上巳西湖好', '欧阳修', '宋代', '清明上巳西湖好，满目繁华。争道谁家。绿柳朱轮走钿车。 \n游人日暮相将去，醒醉喧哗。路转堤斜。直到城头总是花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑子·清明上巳西湖好' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('安定城楼', '李商隐', '唐代', '迢递高城百尺楼，绿杨枝外尽汀洲。\n贾生年少虚垂泪，王粲春来更远游。\n永忆江湖归白发，欲回天地入扁舟。\n不知腐鼠成滋味，猜意鹓雏竟未休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '安定城楼' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荷花', '李商隐', '唐代', '都无色可并，不奈此香何。瑶席乘凉设，金羁落晚过。 \n回衾灯照绮，渡袜水沾罗。预想前秋别，离居梦棹歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荷花' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄令狐郎中' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岁暮', '杜甫', '唐代', '岁暮远为客，边隅还用兵。\n烟尘犯雪岭，鼓角动江城。\n天地日流血，朝廷谁请缨？\n济时敢爱死？寂寞壮心惊！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岁暮' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小雅·谷风', '佚名', '先秦', '习习谷风，维风及雨。将恐将惧，维予与女。将安将乐，女转弃予。\n习习谷风，维风及颓。将恐将惧，置予于怀。将安将乐，弃予如遗。\n习习谷风，维山崔嵬。无草不死，无木不萎。忘我大德，思我小怨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小雅·谷风' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('北门', '佚名', '先秦', '出自北门，忧心殷殷。终窭且贫，莫知我艰。已焉哉！天实为之，谓之何哉！\n王事适我，政事一埤益我。我入自外，室人交徧谪我。已焉哉！天实为之，谓之何哉！\n王事敦我，政事一埤遗我。我入自外，室人交徧摧我。已焉哉！天实为之，谓之何哉！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '北门' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大德歌·春', '关汉卿', '元代', '子规啼，不如归，道是春归人未归。几日添憔悴，虚飘飘柳絮飞。一春鱼雁无消息，则见双燕斗衔泥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大德歌·春' AND p.poem_author = '关汉卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋月·中秋月', '徐有贞', '明代', '中秋月。月到中秋偏皎洁。偏皎洁，知他多少，阴晴圆缺。\n阴晴圆缺都休说，且喜人间好时节。好时节，愿得年年，常见中秋月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋月·中秋月' AND p.poem_author = '徐有贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨中登岳阳楼望君山', '黄庭坚', '宋代', '投荒万死鬓毛斑，生出瞿塘滟滪关。\n未到江南先一笑，岳阳楼上对君山。\n\n满川风雨独凭栏，绾结湘娥十二鬟。\n可惜不当湖水面，银山堆里看青山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨中登岳阳楼望君山' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酹江月·和友驿中言别', '文天祥', '宋代', '乾坤能大，算蛟龙元不是池中物。风雨牢愁无著处，那更寒蛩四壁。横槊题诗，登楼作赋，万事空中雪。江流如此，方来还有英杰。(寒蛩 一作：寒虫)\n堪笑一叶漂零，重来淮水，正凉风新发。镜里朱颜都变尽，只有丹心难灭。去去龙沙，江山回首，一线青如发。故人应念，杜鹃枝上残月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酹江月·和友驿中言别' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('声声慢·秋声', '蒋捷', '宋代', '黄花深巷，红叶低窗，凄凉一片秋声。豆雨声来，中间夹带风声。疏疏二十五点，丽谯门、不锁更声。故人远，问谁摇玉佩，檐底铃声？\n彩角声吹月堕，渐连营马动，四起笳声。闪烁邻灯，灯前尚有砧声。知他诉愁到晓，碎哝哝、多少蛩声！诉未了，把一半、分与雁声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '声声慢·秋声' AND p.poem_author = '蒋捷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·斗草阶前初见', '晏几道', '宋代', '斗草阶前初见，穿针楼上曾逢。罗裙香露玉钗风。靓妆眉沁绿，羞脸粉生红。 \n流水便随春远，行云终与谁同。酒醒长恨锦屏空。相寻梦里路，飞雨落花中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·斗草阶前初见' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('客从远方来', '佚名', '两汉', '客从远方来，遗我一端绮。\n相去万余里，故人心尚尔。\n文采双鸳鸯，裁为合欢被。\n著以长相思，缘以结不解。\n以胶投漆中，谁能别离此？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '客从远方来' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('口号', '贾岛', '唐代', '中夜忽自起，汲此百尺泉。林木含白露，星斗在青天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '口号' AND p.poem_author = '贾岛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长安夜雨', '薛逢', '唐代', '滞雨通宵又彻明，百忧如草雨中生。\n心关桂玉天难晓，运落风波梦亦惊。\n压树早鸦飞不散，到窗寒鼓湿无声。\n当年志气俱消尽，白发新添四五茎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长安夜雨' AND p.poem_author = '薛逢';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '为有' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·别情', '聂胜琼', '宋代', '玉惨花愁出凤城，莲花楼下柳青青。尊前一唱阳关曲，别个人人第五程。\n寻好梦，梦难成。有谁知我此时情，枕前泪共阶前雨，隔个窗儿滴到明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·别情' AND p.poem_author = '聂胜琼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('添字丑奴儿·窗前谁种芭蕉树', '李清照', '宋代', '窗前谁种芭蕉树，阴满中庭。阴满中庭。叶叶心心，舒卷有馀清。(馀\'清\', 一作：情)\n伤心枕上三更雨，点滴霖霪。点滴霖霪。愁损北人，不惯起来听。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '添字丑奴儿·窗前谁种芭蕉树' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮·回文秋闺怨', '苏轼', '宋代', '井桐双照新妆冷，冷妆新照双桐井。羞对井花愁，愁花井对羞。\n影孤怜夜永，永夜怜孤影。楼上不宜秋，秋宜不上楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮·回文秋闺怨' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗二首', '曹丕', '魏晋', '漫漫秋夜长，烈烈北风凉。\n展转不能寐，披衣起彷徨。\n彷徨忽已久，白露沾我裳。\n俯视清水波，仰看明月光。\n天汉回西流，三五正纵横。\n草虫鸣何悲，孤雁独南翔。\n郁郁多悲思，绵绵思故乡。\n愿飞安得翼，欲济河无梁。\n向风长叹息，断绝我中肠。\n\n西北有浮云，亭亭如车盖。\n惜我时不遇，适与飘风会。\n吹我东南行，行行至吴会。\n吴会非吾乡，安能久留滞。\n弃置勿复陈，客子常畏人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗二首' AND p.poem_author = '曹丕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏田家 / 伤田家', '聂夷中', '唐代', '二月卖新丝，五月粜新谷。\n医得眼前疮，剜却心头肉。\n我愿君王心，化作光明烛。\n不照绮罗筵，只照逃亡屋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏田家 / 伤田家' AND p.poem_author = '聂夷中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绝句', '贾岛', '唐代', '海底有明月，圆于天上轮。得之一寸光，可买千里春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绝句' AND p.poem_author = '贾岛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('葛生', '佚名', '先秦', '葛生蒙楚，蔹蔓于野。予美亡此，谁与？独处？\n葛生蒙棘，蔹蔓于域。予美亡此，谁与？独息？\n角枕粲兮，锦衾烂兮。予美亡此，谁与？独旦？\n夏之日，冬之夜。百岁之后，归于其居。\n冬之夜，夏之日。百岁之后，归于其室。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '葛生' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·郑风·褰裳', '佚名', '先秦', '子惠思我，褰裳涉溱。子不我思，岂无他人？狂童之狂也且！\n子惠思我，褰裳涉洧。子不我思，岂无他士？狂童之狂也且！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·郑风·褰裳' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别滁', '欧阳修', '宋代', '花光浓烂柳轻明，酌酒花前送我行。\n我亦且如常日醉，莫教弦管作离声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别滁' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂感', '黄景仁', '清代', '仙佛茫茫两未成，只知独夜不平鸣。\n风蓬飘尽悲歌气，泥絮沾来薄幸名。\n十有九人堪白眼，百无—用是书生。\n莫因诗卷愁成谶，春鸟秋虫自作声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂感' AND p.poem_author = '黄景仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('念奴娇·天南地北', '施耐庵', '元代', '天南地北，问乾坤，何处可容狂客？借得山东烟水寨，来买凤城春色。翠袖围香，绛绡笼雪，一笑千金值。神仙体态，薄幸如何消得？\n想芦叶滩头，蓼花汀畔，皓月空凝碧。六六雁行连八九，只待金鸡消息。义胆包天，忠肝盖地，四海无人识。离愁万种，醉乡一夜头白。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '念奴娇·天南地北' AND p.poem_author = '施耐庵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('木兰花慢·滁州送范倅', '辛弃疾', '宋代', '老来情味减，对别酒，怯流年。况屈指中秋，十分好月，不照人圆。无情水都不管；共西风、只管送归船。秋晚莼鲈江上，夜深儿女灯前。\n征衫，便好去朝天，玉殿正思贤。想夜半承明，留教视草，却遣筹边。长安故人问我，道愁肠殢酒只依然。目断秋霄落雁，醉来时响空弦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '木兰花慢·滁州送范倅' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙·送梅庭老赴上党学官', '苏轼', '宋代', '门外东风雪洒裾，山头回首望三吴。不应弹铗为无鱼。\n上党从来天下脊，先生元是古之儒。时平不用鲁连书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙·送梅庭老赴上党学官' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠头陀师', '刘商', '唐代', '少壮从戎马上飞，雪山童子未缁衣。 \n秋山年长头陀处，说我军前射虎归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠头陀师' AND p.poem_author = '刘商';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塞下曲', '李益', '唐代', '伏波惟愿裹尸还，定远何须生入关。 \n莫遣只轮归海窟，仍留一箭射天山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塞下曲' AND p.poem_author = '李益';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归雁', '钱起', '唐代', '潇湘何事等闲回，水碧沙明两岸苔。 \n二十五弦弹夜月，不胜清怨却飞来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归雁' AND p.poem_author = '钱起';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送友人入蜀', '李白', '唐代', '见说蚕丛路，崎岖不易行。\n山从人面起，云傍马头生。\n芳树笼秦栈，春流绕蜀城。\n升沉应已定，不必问君平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送友人入蜀' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('万山潭作', '孟浩然', '唐代', '垂钓坐磐石，水清心亦闲。\n鱼行潭树下，猿挂岛藤间。\n游女昔解佩，传闻于此山。\n求之不可得，沿月棹歌还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '万山潭作' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春中田园作', '王维', '唐代', '屋上春鸠鸣，村边杏花白。持斧伐远扬，荷锄觇泉脉。 \n归燕识故巢，旧人看新历。临觞忽不御，惆怅远行客。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春中田园作' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('守岁', '李世民', '唐代', '暮景斜芳殿，年华丽绮宫。\n寒辞去冬雪，暖带入春风。\n阶馥舒梅素，盘花卷烛红。\n共欢新故岁，迎送一宵中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '守岁' AND p.poem_author = '李世民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上林赋', '司马相如', '两汉', '亡是公听然而笑曰：“楚则失矣，而齐亦未为得也。夫使诸侯纳贡者，非为财币，所以述职也。封疆画界者，非为守御，所以禁淫也。今齐列为东藩，而外私肃慎，捐国逾限，越海而田，其于义固未可也。且二君之论，不务明君臣之义，正诸侯之礼，徒事争于游戏之乐，苑囿之大，欲以奢侈相胜，荒淫相越，此不可以扬名发誉，而适足以贬君自损也。\n\n　　“且夫齐楚之事，又乌足道乎！君未睹夫巨丽也，独不闻天子之上林乎？左苍梧，右西极。丹水更其南，紫渊径其北。终始灞浐，出入泾渭；酆镐潦潏，纡馀委蛇，经营乎其内。荡荡乎八川分流，相背而异态。东西南北，驰骛往来，出乎椒丘之阙，行乎洲淤之浦，经乎桂林之中，过乎泱漭之野。汩乎混流，顺阿而下，赴隘狭之口，触穹石，激堆埼，沸乎暴怒，汹涌澎湃。滭弗宓汩，逼侧泌瀄。横流逆折，转腾潎冽，滂濞沆溉。穹隆云桡，宛潬胶戾。逾波趋浥，涖涖下濑。批岩冲拥，奔扬滞沛。临坻注壑，瀺灂霣坠，沈沈隐隐，砰磅訇礚，潏潏淈淈，湁潗鼎沸。驰波跳沫，汩濦漂疾。悠远长怀，寂漻无声，肆乎永归。然后灏溔潢漾，安翔徐回，翯乎滈滈，东注太湖，衍溢陂池。于是乎鲛龙赤螭，??渐离，鰅鰫鳍鮀，禺禺魼鳎，揵鳍掉尾，振鳞奋翼，潜处乎深岩，鱼鳖讙声，万物众伙。明月珠子，的砾江靡。蜀石黄碝，水玉磊砢，磷磷烂烂，采色澔汗，藂积乎其中。鸿鹔鹄鸨，鴐 鹅属玉，交精旋目，烦鹜庸渠，箴疵?卢，群浮乎其上，泛淫泛滥，随风澹淡，与波摇荡，奄薄水渚，唼喋菁藻，咀嚼菱藕。\n\n　　“于是乎崇山矗矗，巃嵷崔巍，深林巨木，崭岩参嵳，九嵕嶻嶭。南山峨峨，岩陁甗崎，摧崣崛崎。振溪通谷，蹇产沟渎，谽呀豁閕。阜陵别岛，崴磈葨廆，丘虚堀礨，隐辚郁垒，登降施靡，陂池貏豸，沇溶淫鬻，散涣夷陆，亭皋千里，靡不被筑。揜以绿蕙，被以江蓠，糅以蘪芜，杂以留夷。布结缕，攒戾莎，揭车衡兰，槀本射干，茈姜蘘荷，葴持若荪，鲜支黄砾，蒋苎青薠，布濩闳泽，延曼太原。离靡广衍，应风披靡，吐芳扬烈，郁郁菲菲，众香发越，肸蚃布写，晻薆咇茀。\n\n　　“于是乎周览泛观，缜纷轧芴，芒芒恍忽。视之无端，察之无涯，日出东沼，入乎西陂。其南则隆冬生长，涌水跃波。其兽则?旄貘嫠，沈牛麈麋，赤首圜题，穷奇象犀。其北则盛夏含冻裂地，涉冰揭河。其兽则麒麟角端，騊駼橐驼，蛩蛩驒騱，駃騠驴骡六庵注。\n\n　　“于是乎离宫别馆，弥山跨谷，高廊四注，重坐曲阁，华榱璧珰，辇道纚属，步櫩周流，长途中宿。夷嵕筑堂，累台增成，岩窔洞房，頫杳眇而无见，仰攀橑而扪天，奔星更于闺闼，宛虹扦于楯轩，青龙蚴蟉于东箱，象舆婉僤于西清，灵圄燕于闲馆，偓佺之伦，暴于南荣。醴泉涌于清室，通川过于中庭。盘石振崖，嵚岩倚倾。嵯峨磼礏，刻削峥嵘。玫瑰碧琳，珊瑚丛生，琘玉旁唐，玢豳文鳞，赤瑕驳荦，杂臿其间，晁采琬琰，和氏出焉。\n\n　　“于是乎卢橘夏熟，黄甘橙楱，枇杷橪柿，亭奈厚朴，梬枣杨梅，樱桃蒲陶，隐夫薁棣，答沓离支，罗乎后宫，列乎北园。崒丘陵，下平原，扬翠叶，扤紫茎，发红华，垂朱荣，煌煌扈扈，照曜钜野。沙棠栎槠，华枫枰栌，留落胥邪，仁频并闾，欃檀木兰，豫章女贞，长千仞，大连抱，夸条直畅，实叶葰楙，攒立丛倚，连卷欐佹，崔错癹骫，坑衡閜砢，垂条扶疏，落英幡纚，纷溶箾蔘，猗狔从风，藰莅卉歙，盖象金石之声，管籥之音。偨池茈虒，旋还乎后宫，杂袭絫辑，被山缘谷，循阪下隰，视之无端，究之无穷。\n\n　　“于是乎玄猨素雌，蜼玃飞鸓，蛭蜩蠼猱，獑胡豰蛫，栖息乎其间。长啸哀鸣，翩幡互经。夭蟜枝格，偃蹇杪颠。隃绝梁，腾殊榛，捷垂条，掉希间，牢落陆离，烂漫远迁。若此者数百千处。娱游往来，宫宿馆舍，庖厨不徙，后宫不移，百官备具。\n\n　　“于是乎背秋涉冬，天子校猎。乘镂象，六玉虬，拖蜺旌，靡云旗，前皮轩，后道游。孙叔奉辔，卫公参乘，扈从横行，出乎四校之中。鼓严簿，纵猎者，河江为阹，泰山为橹，车骑雷起，殷天动地，先后陆离，离散别追。淫淫裔裔，缘陵流泽，云布雨施。生貔豹，搏豺狼，手熊罴，足壄羊，蒙鹖苏，绔白虎，被班文，跨壄马，凌三嵕之危，下碛历之坻。径峻赴险，越壑厉水。椎蜚廉，弄獬豸，格虾蛤，鋋猛氏，羂騕褭，射封豕。箭不苟害，解脰陷脑，弓不虚发，应声而倒。于是乘舆弭节徘徊，翱翔往来，睨部曲之进退，览将帅之变态。然后侵淫促节，儵夐远去，流离轻禽，蹴履狡兽。轊白鹿，捷狡兔，轶赤电，遗光耀。追怪物，出宇宙，弯蕃弱，满白羽，射游枭，栎蜚遽。择肉而后发，先中而命处，弦矢分，艺殪仆。然后扬节而上浮，凌惊风，历骇猋，乘虚无，与神俱。躏玄鹤，乱昆鸡，遒孔鸾，促鵔鸃，拂翳鸟，捎凤凰，捷鹓鶵，揜焦明。道尽途殚，回车而还。消遥乎襄羊，降集乎北纮，率乎直指，晻乎反乡。蹷石阙，历封峦，过鳷鹊，望露寒，下棠梨，息宜春，西驰宣曲，濯鹢牛首，登龙台，掩细柳。观士大夫之勤略，均猎者之所得获，徒车之所轥轹，步骑之所蹂若，人臣之所蹈籍，与其穷极倦谻，惊惮詟伏，不被创刃而死者，他他籍籍，填坑满谷，掩平弥泽。\n\n　　“于是乎游戏懈怠，置酒乎颢天之台，张乐乎轇輵之宇。撞千石之钟，立万石之虡，建翠华之旗，树灵鼍之鼓，奏陶唐氏之舞，听葛天氏之歌，千人唱，万人和，山陵为之震动，川谷为之荡波。巴渝宋蔡，淮南干遮，文成颠歌，族居递奏，金鼓迭起，铿鎗闛鞈，洞心骇耳。荆吴郑卫之声，韶濩武象之乐，阴淫案衍之音，鄢郢缤纷，激楚结风。俳优侏儒，狄鞮之倡，所以娱耳目乐心意者，丽靡烂漫于前，靡曼美色于后。若夫青琴、宓妃之徒，绝殊离俗，妖冶娴都，靓妆刻饰，便嬛绰约，柔桡嫚嫚，妩媚孅弱。曳独茧之褕绁，眇阎易以恤削，便姗嫳屑，与俗殊服，芬芳沤郁，酷烈淑郁；皓齿粲烂，宜笑的皪；长眉连娟，微睇绵藐，色授魂与，心愉于侧。\n\n　　“于是酒中乐酣，天子芒然而思，似若有亡，曰：‘嗟乎！此大奢侈。朕以览听馀闲，无事弃日，顺天道以杀伐，时休息于此。恐后叶靡丽，遂往而不返，非所以为继嗣创业垂统也。’于是乎乃解酒罢猎，而命有司曰：‘地可垦辟，悉为农郊，以赡萌隶，隤墙填堑，使山泽之人得至焉。实陂池而勿禁，虚宫馆而勿仞，发仓廪以救贫穷，补不足，恤鳏寡，存孤独，出德号，省刑罚，改制度，易服色，革正朔，与天下为更始。’\n\n　　“于是历吉日以斋戒，袭朝服，乘法驾，建华旗，鸣玉鸾，游于六艺之囿，驰骛乎仁义之涂，览观《春秋》之林，射《狸首》，兼《驺虞》，弋玄鹤，舞干戚，载云?，揜群雅，悲《伐檀》，乐乐胥，修容乎礼园，翱翔乎书圃，述《易》道，放怪兽，登明堂，坐清庙，次群臣，奏得失，四海之内，靡不受获。于斯之时，天下大说，乡风而听，随流而化，芔然兴道而迁义，刑错而不用，德隆于三王，而功羡于五帝。若此故猎，乃可喜也。若夫终日驰骋，劳神苦形，罢车马之用，抏士卒之精，费府库之财，而无德厚之恩，务在独乐，不顾众庶，亡国家之政，贪雉兔之获，则仁者不繇也。从此观之，齐楚之事，岂不哀哉！地方不过千里，而囿居九百，是草木不得垦辟，而人无所食也。夫以诸侯之细，而乐万乘之侈，仆恐百姓被其尤也。”\n\n　　于是二子愀然改容，超若自失，逡巡避席，曰：“鄙人固陋，不知忌讳，乃今日见教，谨受命矣。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上林赋' AND p.poem_author = '司马相如';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送紫岩张先生北伐', '岳飞', '宋代', '号令风霆迅，天声动北陬。\n长驱渡河洛，直捣向燕幽。\n马蹀阏氏血，旗袅可汗头。\n归来报明主，恢复旧神州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送紫岩张先生北伐' AND p.poem_author = '岳飞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绝句', '吴涛', '宋代', '游子春衫已试单，桃花飞尽野梅酸。\n怪来一夜蛙声歇，又作东风十日寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绝句' AND p.poem_author = '吴涛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六州歌头·长淮望断', '张孝祥', '宋代', '长淮望断，关塞莽然平。征尘暗，霜风劲，悄边声。黯销凝。追想当年事，殆天数，非人力，洙泗上，弦歌地，亦膻腥。隔水毡乡，落日牛羊下，区脱纵横。看名王宵猎，骑火一川明。笳鼓悲鸣。遣人惊。 \n念腰间箭，匣中剑，空埃蠹，竟何成。时易失，心徒壮，岁将零。渺神京。干羽方怀远，静烽燧，且休兵。冠盖使，纷驰骛，若为情。闻道中原遗老，常南望、翠葆霓旌。使行人到此，忠愤气填膺。有泪如倾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六州歌头·长淮望断' AND p.poem_author = '张孝祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望海潮·洛阳怀古', '秦观', '宋代', '梅英疏淡，冰澌溶泄，东风暗换年华。金谷俊游，铜驼巷陌，新晴细履平沙。长记误随车。正絮翻蝶舞，芳思交加。柳下桃蹊，乱分春色到人家。\n西园夜饮鸣笳。有华灯碍月，飞盖妨花。兰苑未空，行人渐老，重来是事堪嗟。烟暝酒旗斜。但倚楼极目，时见栖鸦。无奈归心，暗随流水到天涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望海潮·洛阳怀古' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长相思·长相思', '晏几道', '宋代', '长相思，长相思。若问相思甚了期，除非相见时。\n长相思，长相思。欲把相思说似谁，浅情人不知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长相思·长相思' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重别周尚书', '庾信', '南北朝', '阳关万里道，不见一人归。\n惟有河边雁，秋来南向飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重别周尚书' AND p.poem_author = '庾信';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('车遥遥篇', '傅玄', '魏晋', '车遥遥兮马洋洋，追思君兮不可忘。\n君安游兮西入秦，愿为影兮随君身。\n君在阴兮影不见，君依光兮妾所愿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '车遥遥篇' AND p.poem_author = '傅玄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元日·晨鸡两遍报', '方干', '唐代', '晨鸡两遍报更阑，刁斗无声晓漏干。\n暖日映山调正气，东风入树舞残寒。\n轩车欲识人间感，献岁须来帝里看。\n才酌屠苏定年齿，坐中惟笑鬓毛斑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元日·晨鸡两遍报' AND p.poem_author = '方干';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长城', '罗邺', '唐代', '当时无德御乾坤，广筑徒劳万古存。\n谩役生民防极塞，不知血刃起中原。\n珠玑旋见陪陵寝，社稷何曾保子孙。 \n降虏至今犹自说，冤声夜夜傍城根。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长城' AND p.poem_author = '罗邺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬日归旧山', '李白', '唐代', '未洗染尘缨，归来芳草平。一条藤径绿，万点雪峰晴。 \n地冷叶先尽，谷寒云不行。嫩篁侵舍密，古树倒江横。 \n白犬离村吠，苍苔壁上生。穿厨孤雉过，临屋旧猿鸣。 \n木落禽巢在，篱疏兽路成。拂床苍鼠走，倒箧素鱼惊。 \n洗砚修良策，敲松拟素贞。此时重一去，去合到三清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬日归旧山' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠裴十四', '李白', '唐代', '朝见裴叔则，朗如行玉山。\n黄河落天走东海，万里写入胸怀间。\n身骑白鼋不敢度，金高南山买君顾。\n徘徊六合无相知，飘若浮云且西去！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠裴十四' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑子·谁翻乐府凄凉曲', '纳兰性德', '清代', '谁翻乐府凄凉曲？风也萧萧，雨也萧萧，瘦尽灯花又一宵。\n不知何事萦怀抱，醒也无聊，醉也无聊，梦也何曾到谢桥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑子·谁翻乐府凄凉曲' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八月十五夜桃源玩月', '刘禹锡', '唐代', '尘中见月心亦闲，况是清秋仙府间。\n凝光悠悠寒露坠，此时立在最高山。\n碧虚无云风不起，山上长松山下水。\n群动悠然一顾中，天高地平千万里。\n少君引我升玉坛，礼空遥请真仙官。\n云拼欲下星斗动，天乐一声肌骨寒。\n金霞昕昕渐东上，轮欹影促犹频望。\n绝景良时难再并，他年此日应惆怅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八月十五夜桃源玩月' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绝句漫兴九首·其五', '杜甫', '唐代', '肠断春江欲尽头，杖藜徐步立芳洲。(春江 一作：江春)\n颠狂柳絮随风去，轻薄桃花逐水流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绝句漫兴九首·其五' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏日杂诗', '陈文述', '清代', '水窗低傍画栏开，枕簟萧疏玉漏催。\n一夜雨声凉到梦，万荷叶上送秋来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏日杂诗' AND p.poem_author = '陈文述';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桓灵时童谣', '佚名', '两汉', '举秀才，不知书。\n举孝廉，父别居。\n寒素清白浊如泥，\n高第良将怯如鸡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桓灵时童谣' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长相思', '陈允平', '宋代', '风萧萧。雨骚骚。风雨萧骚梧叶飘。潇湘江畔楼。 \n 云迢迢。水遥遥。云水迢遥天尽头。相思心上秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长相思' AND p.poem_author = '陈允平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('踏莎行·雪似梅花', '吕本中', '宋代', '雪似梅花，梅花似雪。似和不似都奇绝。恼人风味阿谁知？请君问取南楼月。\n记得去年，探梅时节。老来旧事无人说。为谁醉倒为谁醒？到今犹恨轻离别。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '踏莎行·雪似梅花' AND p.poem_author = '吕本中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·记得金銮同唱第', '欧阳修', '宋代', '记得金銮同唱第，春风上国繁华。如今薄宦老天涯。十年岐路，空负曲江花。\n闻说阆山通阆苑，楼高不见君家。孤城寒日等闲斜。离愁难尽，红树远连霞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·记得金銮同唱第' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登江中孤屿', '谢灵运', '南北朝', '江南倦历览，江北旷周旋。\n怀新道转迥，寻异景不延。\n乱流趋正绝，孤屿媚中川。\n云日相晖映，空水共澄鲜。\n表灵物莫赏，蕴真谁为传。\n想象昆山姿，缅邈区中缘。\n始信安期术，得尽养生年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登江中孤屿' AND p.poem_author = '谢灵运';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送人东游', '温庭筠', '唐代', '荒戍落黄叶，浩然离故关。\n高风汉阳渡，初日郢门山。\n江上几人在，天涯孤棹还。\n何当重相见，樽酒慰离颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送人东游' AND p.poem_author = '温庭筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗三首 / 杂咏三首', '王维', '唐代', '家住孟津河，门对孟津口。\n常有江南船，寄书家中否。\n\n君自故乡来，应知故乡事。\n来日绮窗前，寒梅著花未。\n\n已见寒梅发，复闻啼鸟声。\n心心视春草，畏向阶前生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗三首 / 杂咏三首' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('少年行四首·其三', '令狐楚', '唐代', '弓背霞明剑照霜，秋风走马出咸阳。\n未收天子河湟地，不拟回头望故乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '少年行四首·其三' AND p.poem_author = '令狐楚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮·枕前发尽千般愿', '佚名', '五代', '枕前发尽千般愿，要休且待青山烂。水面上秤锤浮，直待黄河彻底枯。\n白日参辰现，北斗回南面。休即未能休，且待三更见日头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮·枕前发尽千般愿' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜算子', '蔡伸', '宋代', '春事付莺花，曾是莺花主。醉拍春衫金缕衣，只向花间住。 \n 密意君听取。莫逐风来去。若是真心待于飞，云里千条路。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜算子' AND p.poem_author = '蔡伸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('点绛唇·花信来时', '晏几道', '宋代', '花信来时，恨无人似花依旧。又成春瘦，折断门前柳。\n天与多情，不与长相守。分飞后，泪痕和酒，占了双罗袖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '点绛唇·花信来时' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观公孙大娘弟子舞剑器行', '杜甫', '唐代', '大历二年十月十九日，夔府别驾元持宅，见临颍李十二娘 舞剑器，壮其蔚跂，问其所师，曰：“余公孙大娘弟子也。” 开元三载，余尚童稚，记于郾城观公孙氏，舞剑器浑脱， 浏漓顿挫，独出冠时，自高头宜春梨园二伎坊内人洎外供奉， 晓是舞者，圣文神武皇帝初，公孙一人而已。 玉貌锦衣，况余白首，今兹弟子，亦非盛颜。 既辨其由来，知波澜莫二，抚事慷慨，聊为《剑器行》。 昔者吴人张旭，善草书帖，数常于邺县见公孙大娘舞西河剑器，自此草书长进，豪荡感激，即公孙可知矣。\n\n昔有佳人公孙氏，一舞剑器动四方。\n观者如山色沮丧，天地为之久低昂。\n霍如羿射九日落，矫如群帝骖龙翔。\n来如雷霆收震怒，罢如江海凝清光。\n绛唇珠袖两寂寞，晚有弟子传芬芳。\n临颍美人在白帝，妙舞此曲神扬扬。\n与余问答既有以，感时抚事增惋伤。\n先帝侍女八千人，公孙剑器初第一。\n五十年间似反掌，风尘倾动昏王室。\n梨园弟子散如烟，女乐余姿映寒日。\n金粟堆前木已拱，瞿唐石城草萧瑟。\n玳筵急管曲复终，乐极哀来月东出。\n老夫不知其所往，足茧荒山转愁疾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观公孙大娘弟子舞剑器行' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送魏万之京', '李颀', '唐代', '朝闻游子唱离歌，昨夜微霜初渡河。\n鸿雁不堪愁里听，云山况是客中过。\n关城树色催寒近，御苑砧声向晚多。(\'树\'色,一作：曙)\n莫见长安行乐处，空令岁月易蹉跎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送魏万之京' AND p.poem_author = '李颀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送陈秀才还沙上省墓', '高启', '明代', '满衣血泪与尘埃，乱后还乡亦可哀。\n风雨梨花寒食过，几家坟上子孙来？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送陈秀才还沙上省墓' AND p.poem_author = '高启';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪望', '洪升', '清代', '寒色孤村幕，悲风四野闻。\n溪深难受雪，山冻不流云。\n鸥鹭飞难辨，沙汀望莫分。\n野桥梅几树，并是白纷纷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪望' AND p.poem_author = '洪升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天净沙·宁可少活十年', '严忠济', '元代', '宁可少活十年，休得一日无权，大丈夫时乖命蹇。有朝一日天随人愿，赛田文养客三千。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天净沙·宁可少活十年' AND p.poem_author = '严忠济';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五月十九日大雨', '刘基', '明代', '风驱急雨洒高城，云压轻雷殷地声。\n雨过不知龙去处，一池草色万蛙鸣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五月十九日大雨' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长相思·游西湖', '康与之', '宋代', '南高峰，北高峰，一片湖光烟霭中。春来愁杀侬。\n郎意浓，妾意浓。油壁车轻郎马骢，相逢九里松。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长相思·游西湖' AND p.poem_author = '康与之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春·题潮阳张许二公庙', '文天祥', '宋代', '为子死孝，为臣死忠，死又何妨。\n自光岳气分，士无全节；君臣义缺，谁负刚肠。\n骂贼睢阳，爱君许远，留取声名万古香。\n后来者，无二公之操，百炼之钢。\n人生翕歘云亡。\n好烈烈轰轰做一场。\n使当时卖国，甘心降虏，受人唾骂，安得流芳。\n古庙幽沉，仪容俨雅，枯木寒鸦几夕阳。\n邮亭下，有奸雄过此，仔细思量。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春·题潮阳张许二公庙' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南柯子·十里青山远', '仲殊', '宋代', '十里青山远，潮平路带沙。数声啼鸟怨年华。又是凄凉时候，在天涯。\n白露收残月，清风散晓霞。绿杨堤畔问荷花：记得年时沽酒，那人家？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南柯子·十里青山远' AND p.poem_author = '仲殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜算子·感旧', '苏轼', '宋代', '蜀客到江南，长忆吴山好。吴蜀风流自古同，归去应须早。\n还与去年人，共藉西湖草。莫惜尊前仔细看，应是容颜老。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜算子·感旧' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗', '佚名', '唐代', '劝君莫惜金缕衣，劝君须惜少年时。\n有花堪折直须折，莫待无花空折枝。\n\n青天无云月如烛，露泣梨花白如玉。\n子规一夜啼到明，美人独在空房宿。\n\n空赐罗衣不赐恩，一薰香后一销魂。\n虽然舞袖何曾舞，常对春风裛泪痕。\n\n不洗残妆凭绣床，也同女伴绣鸳鸯。\n回针刺到双飞处，忆著征夫泪数行。\n\n眼想心思梦里惊，无人知我此时情。\n不如池上鸳鸯鸟，双宿双飞过一生。\n\n一去辽阳系梦魂，忽传征骑到中门。\n纱窗不肯施红粉，徒遣萧郎问泪痕。\n\n莺啼露冷酒初醒，罨画楼西晓角鸣。\n翠羽帐中人梦觉，宝钗斜坠枕函声。\n\n行人南北分征路，流水东西接御沟。\n终日坡前怨离别，谩名长乐是长愁。\n\n偏倚绣床愁不起，双垂玉箸翠鬟低。\n卷帘相待无消息，夜合花前日又西。\n\n悔将泪眼向东开，特地愁从望里来。\n三十六峰犹不见，况伊如燕这身材。\n\n满目笙歌一段空，万般离恨总随风。\n多情为谢残阳意，与展晴霞片片红。\n\n两心不语暗知情，灯下裁缝月下行。\n行到阶前知未睡，夜深闻放剪刀声。\n\n近寒食雨草萋萋，著麦苗风柳映堤。\n早是有家归未得，杜鹃休向耳边啼。\n\n水纹珍簟思悠悠，千里佳期一夕休。\n从此无心爱良夜，任他明月下西楼。\n\n数日相随两不忘，郎心如妾妾如郎。\n出门便是东西路，把取红笺各断肠。\n\n无定河边暮角声，赫连台畔旅人情。\n函关归路千馀里，一夕秋风白发生。\n\n花落长川草色青，暮山重叠两冥冥。\n逢春便觉飘蓬苦，今日分飞一涕零。\n\n洛阳才子邻箫恨，湘水佳人锦瑟愁。\n今昔两成惆怅事，临邛春尽暮江流。\n\n浙江轻浪去悠悠，望海楼吹望海愁。\n莫怪乡心随魄断，十年为客在他州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('焚书坑', '章碣', '唐代', '竹帛烟销帝业虚，关河空锁祖龙居。\n坑灰未冷山东乱，刘项原来不读书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '焚书坑' AND p.poem_author = '章碣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('月', '杜甫', '唐代', '天上秋期近，人间月影清。入河蟾不没，捣药兔长生。 \n 只益丹心苦，能添白发明。干戈知满地，休照国西营。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '月' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游洞庭湖五首·其二', '李白', '唐代', '南湖秋水夜无烟，耐可乘流直上天。\n且就洞庭赊月色，将船买酒白云边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游洞庭湖五首·其二' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('折荷有赠', '李白', '唐代', '涉江玩秋水，爱此红蕖鲜。\n攀荷弄其珠，荡漾不成圆。\n佳人彩云里，欲赠隔远天。\n相思无因见，怅望凉风前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '折荷有赠' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凤箫吟·锁离愁', '韩缜', '宋代', '锁离愁，连绵无际，来时陌上初熏。绣帏人念远，暗垂珠泪，泣送征轮。长亭长在眼，更重重、远水孤云。但望极楼高，尽日目断王孙。 \n消魂。池塘别后，曾行处、绿妒轻裙。恁时携素手，乱花飞絮里，缓步香茵。朱颜空自改，向年年、芳意长新。遍绿野，嬉游醉眠，莫负青春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凤箫吟·锁离愁' AND p.poem_author = '韩缜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·京口得乡书', '苏轼', '宋代', '雨后春容清更丽。只有离人，幽恨终难洗。北固山前三面水。碧琼梳拥青螺髻。\n一纸乡书来万里。问我何年，真个成归计。白首送春拚一醉。东风吹破千行泪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·京口得乡书' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·夜到扬州席上作', '苏轼', '宋代', '尊酒何人怀李白，草堂遥指江东。珠帘十里卷香风。花开又花谢，离恨几千重。\n轻舸渡江连夜到，一时惊笑衰容。语音犹自带吴侬。夜阑对酒处，依旧梦魂中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·夜到扬州席上作' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菊', '郑谷', '唐代', '王孙莫把比蓬蒿，九日枝枝近鬓毛。\n露湿秋香满池岸，由来不羡瓦松高。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菊' AND p.poem_author = '郑谷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冯谖客孟尝君', '佚名', '先秦', '齐人有冯谖者，贫乏不能自存，使人属孟尝君，愿寄食门下。孟尝君曰：“客何好？”曰：“客无好也。”曰：“客何能？”曰：“客无能也。”孟尝君笑而受之曰：“诺。”\n\n　　左右以君贱之也，食以草具。居有顷，倚柱弹其剑，歌曰：“长铗归来乎！食无鱼。”左右以告。孟尝君曰：“食之，比门下之客。”居有顷，复弹其铗，歌曰：“长铗归来乎！出无车。”左右皆笑之，以告。孟尝君曰：“为之驾，比门下之车客。”于是乘其车，揭其剑，过其友曰：“孟尝君客我。”后有顷，复弹其剑铗，歌曰：“长铗归来乎！无以为家。”左右皆恶之，以为贪而不知足。孟尝君问：“冯公有亲乎？”对曰，“有老母。”孟尝君使人给其食用，无使乏。于是冯谖不复歌。\n\n　　后孟尝君出记，问门下诸客：“谁习计会，能为文收责于薛者乎？”冯谖署曰：“能。”孟尝君怪之，曰：“此谁也？”左右曰：“乃歌夫长铗归来者也。”孟尝君笑曰：“客果有能也，吾负之，未尝见也。”请而见之，谢曰：“文倦于事，愦于忧，而性懧愚，沉于国家之事，开罪于先生。先生不羞，乃有意欲为收责于薛乎？”冯谖曰：“愿之。”于是约车治装，载券契而行，辞曰：“责毕收，以何市而反？”孟尝君曰：“视吾家所寡有者。”\n\n　　驱而之薛，使吏召诸民当偿者，悉来合券。券遍合，起，矫命，以责赐诸民。因烧其券。民称万岁。\n\n　　长驱到齐，晨而求见。孟尝君怪其疾也，衣冠而见之，曰：“责毕收乎？来何疾也！”曰：“收毕矣。”“以何市而反？”冯谖曰；“君之‘视吾家所寡有者’。臣窃计，君宫中积珍宝，狗马实外厩，美人充下陈。君家所寡有者，以义耳！窃以为君市义。”孟尝君曰：“市义奈何？”曰：“今君有区区之薛，不拊爱子其民，因而贾利之。臣窃矫君命，以责赐诸民，因烧其券，民称万岁。乃臣所以为君市义也。”孟尝君不悦，曰：“诺，先生休矣！”\n\n　　后期年，齐王谓孟尝君曰：“寡人不敢以先王之臣为臣。”孟尝君就国于薛，未至百里，民扶老携幼，迎君道中。孟尝君顾谓冯谖：“先生所为文市义者，乃今日见之。”\n\n　　冯谖曰：“狡兔有三窟，仅得免其死耳；今君有一窟，未得高枕而卧也。请为君复凿二窟。”孟尝君予车五十乘，金五百斤，西游于梁，谓惠王曰：“齐放其大臣孟尝君于诸侯，诸侯先迎之者，富而兵强。”于是梁王虚上位，以故相为上将军，遣使者黄金千斤，车百乘，往聘孟尝君。冯谖先驱，诫孟尝君曰：“千金，重币也；百乘，显使也。齐其闻之矣。”梁使三反，孟尝君固辞不往也。\n\n　　齐王闻之，君臣恐惧，遣太傅赍黄金千斤、文车二驷，服剑一，封书，谢孟尝君曰：“寡人不祥，被于宗庙之祟，沉于谄谀之臣，开罪于君。寡人不足为也；愿君顾先王之宗庙，姑反国统万人乎！”冯谖诫孟尝君曰：“愿请先王之祭器，立宗庙于薛。”庙成，还报孟尝君曰：“三窟已就，君姑高枕为乐矣。”\n\n　　孟尝君为相数十年，无纤介之祸者，冯谖之计也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冯谖客孟尝君' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清江引·秋怀', '张可久', '元代', '西风信来家万里，问我归期未？\n雁啼红叶天，人醉黄花地，芭蕉雨声秋梦里。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清江引·秋怀' AND p.poem_author = '张可久';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山坡羊·道情', '宋方壶', '元代', '青山相待，白云相爱，梦不到紫罗袍共黄金带。一茅斋，野花开。管甚谁家兴废谁成败，陋巷箪瓢亦乐哉。贫，气不改；达，志不改。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山坡羊·道情' AND p.poem_author = '宋方壶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('柳', '寇准', '宋代', '晓带轻烟间杏花，晚凝深翠拂平沙。\n长条别有风流处，密映钱塘苏小家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '柳' AND p.poem_author = '寇准';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长相思·雨', '万俟咏', '宋代', '一声声，一更更。窗外芭蕉窗里灯，此时无限情。\n梦难成，恨难平。不道愁人不喜听，空阶滴到明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长相思·雨' AND p.poem_author = '万俟咏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹊桥仙·七夕', '范成大', '宋代', '双星良夜，耕慵织懒，应被群仙相妒。娟娟月姊满眉颦，更无奈、风姨吹雨。 \n相逢草草，争如休见，重搅别离心绪。新欢不抵旧愁多，倒添了、新愁归去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹊桥仙·七夕' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南乡子·重九涵辉楼呈徐君猷', '苏轼', '宋代', '霜降水痕收。浅碧鳞鳞露远洲。酒力渐消风力软，飕飕。破帽多情却恋头。\n佳节若为酬。但把清尊断送秋。万事到头都是梦，休休。明日黄花蝶也愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南乡子·重九涵辉楼呈徐君猷' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('筹笔驿', '罗隐', '唐代', '抛掷南阳为主忧，北征东讨尽良筹。\n时来天地皆同力，运去英雄不自由。\n千里山河轻孺子，两朝冠剑恨谯周。\n唯余岩下多情水，犹解年年傍驿流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '筹笔驿' AND p.poem_author = '罗隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暮过山村', '贾岛', '唐代', '数里闻寒水，山家少四邻。\n怪禽啼旷野，落日恐行人。\n初月未终夕，边烽不过秦。\n萧条桑柘处，烟火渐相亲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暮过山村' AND p.poem_author = '贾岛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日', '李商隐', '唐代', '欲入卢家白玉堂，新春催破舞衣裳。 \n 蝶衔红蕊蜂衔粉，共助青楼一日忙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同李十一醉忆元九', '白居易', '唐代', '花时同醉破春愁，醉折花枝作酒筹。\n忽忆故人天际去，计程今日到梁州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同李十一醉忆元九' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('有所思', '卢仝', '唐代', '当时我醉美人家，美人颜色娇如花。\n今日美人弃我去，青楼珠箔天之涯。\n天涯娟娟姮娥月，三五二八盈又缺。\n翠眉蝉鬓生别离，一望不见心断绝。\n心断绝，几千里？\n梦中醉卧巫山云，觉来泪滴湘江水。\n湘江两岸花木深，美人不见愁人心。\n含愁更奏绿绮琴，调高弦绝无知音。\n美人兮美人，不知为暮雨兮为朝云。\n相思一夜梅花发，忽到窗前疑是君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '有所思' AND p.poem_author = '卢仝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('视刀环歌', '刘禹锡', '唐代', '常恨言语浅，不如人意深。\n今朝两相视，脉脉万重心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '视刀环歌' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早春寄王汉阳', '李白', '唐代', '闻道春还未相识，走傍寒梅访消息。\n昨夜东风入武阳，陌头杨柳黄金色。\n碧水浩浩云茫茫，美人不来空断肠。\n预拂青山一片石，与君连日醉壶觞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早春寄王汉阳' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江上吟', '李白', '唐代', '木兰之枻沙棠舟，玉箫金管坐两头。\n美酒樽中置千斛，载妓随波任去留。\n仙人有待乘黄鹤，海客无心随白鸥。\n屈平辞赋悬日月，楚王台榭空山丘。\n兴酣落笔摇五岳，诗成笑傲凌沧洲。\n功名富贵若长在，汉水亦应西北流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江上吟' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('惠州一绝 / 食荔枝', '苏轼', '宋代', '罗浮山下四时春，卢橘杨梅次第新。\n日啖荔枝三百颗，不辞长作岭南人。（不辞 一作：不妨）', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '惠州一绝 / 食荔枝' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('弈秋', '孟子及弟子', '先秦', '孟子曰：“无或乎王之不智也。虽有天下易生之物也，一日暴之，十日寒之，未有能生者也。吾见亦罕矣，吾退而寒之者至矣，吾如有萌焉何哉？今夫弈之为数，小数也；不专心致志。则不得也。弈秋，通国之善奕者也。使弈秋诲二人弈，其一人专心致志，惟弈秋之为听。一人虽听之，一心以为有鸿鹄将至，思援弓缴而射之，虽与之俱学，弗若之矣，为是其智弗若与？曰：非然也。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '高中', NULL FROM edu_poem p WHERE p.poem_title = '弈秋' AND p.poem_author = '孟子及弟子';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('钴鉧潭西小丘记', '柳宗元', '唐代', '得西山后八日，寻山口西北道二百步，又得钴鉧潭。西二十五步，当湍而浚者为鱼梁。梁之上有丘焉，生竹树。其石之突怒偃蹇，负土而出，争为奇状者，殆不可数。其嵚然相累而下者，若牛马之饮于溪；其冲然角列而上者，若熊罴之登于山。\n\n　　丘之小不能一亩，可以笼而有之。问其主，曰：“唐氏之弃地，货而不售。”问其价，曰：“止四百。”余怜而售之。李深源、元克己时同游，皆大喜，出自意外。即更取器用，铲刈秽草，伐去恶木，烈火而焚之。嘉木立，美竹露，奇石显。由其中以望，则山之高，云之浮，溪之流，鸟兽之遨游，举熙熙然回巧献技，以效兹丘之下。枕席而卧，则清泠之状与目谋，瀯瀯之声与耳谋，悠然而虚者与神谋，渊然而静者与心谋。不匝旬而得异地者二，虽古好事之士，或未能至焉。\n\n　　噫！以兹丘之胜，致之沣、镐、鄠、杜，则贵游之士争买者，日增千金而愈不可得。今弃是州也，农夫渔父，过而陋之，贾四百，连岁不能售。而我与深源、克己独喜得之，是其果有遭乎！书于石，所以贺兹丘之遭也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '钴鉧潭西小丘记' AND p.poem_author = '柳宗元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('代别离·秋窗风雨夕', '曹雪芹', '清代', '秋花惨淡秋草黄，耿耿秋灯秋夜长。\n已觉秋窗秋不尽，那堪风雨助凄凉！\n助秋风雨来何速？惊破秋窗秋梦绿。\n抱得秋情不忍眠，自向秋屏移泪烛。\n泪烛摇摇爇短檠，牵愁照恨动离情。\n谁家秋院无风入？何处秋窗无雨声？\n罗衾不奈秋风力，残漏声催秋雨急。\n连宵霢霢复飕飕，灯前似伴离人泣。\n寒烟小院转萧条，疏竹虚窗时滴沥。\n不知风雨几时休，已教泪洒窗纱湿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '代别离·秋窗风雨夕' AND p.poem_author = '曹雪芹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鄂州南楼书事', '黄庭坚', '宋代', '四顾山光接水光，凭栏十里芰荷香。\n清风明月无人管，并作南楼一味凉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鄂州南楼书事' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春·丁巳重阳前', '纳兰性德', '清代', '丁巳重阳前三日，梦亡妇淡妆素服，执手哽咽，语多不复能记。但临别有云：“衔恨愿为天上月，年年犹得向郎圆。”妇素未工诗，不知何以得此也，觉后感赋。\n\n瞬息浮生，薄命如斯，低徊怎忘。记绣榻闲时，并吹红雨；雕阑曲处，同倚斜阳。梦好难留，诗残莫续，赢得更深哭一场。遗容在，只灵飙一转，未许端详。重寻碧落茫茫。料短发、朝来定有霜。便人间天上，尘缘未断，春花秋叶，触绪还伤。欲结绸缪，翻惊摇落，减尽荀衣昨日香。真无奈，倩声声邻笛，谱出回肠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春·丁巳重阳前' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆秦娥·烧灯节', '刘辰翁', '宋代', '中斋上元客散感旧，赋《忆秦娥》见属，一读凄然。随韵寄情，不觉悲甚。\n\n烧灯节，朝京道上风和雪。风和雪，江山如旧，朝京人绝。\n百年短短兴亡别，与君犹对当时月。当时月，照人烛泪，照人梅发。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆秦娥·烧灯节' AND p.poem_author = '刘辰翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春·梦孚若', '刘克庄', '宋代', '何处相逢，登宝钗楼，访铜雀台。唤厨人斫就，东溟鲸脍，圉人呈罢，西极龙媒。天下英雄，使君与操，余子谁堪共酒杯。车千乘，载燕南赵北，剑客奇才。\n饮酣画鼓如雷。谁信被晨鸡轻唤回。叹年光过尽，功名未立，书生老去，机会方来。使李将军，遇高皇帝，万户侯何足道哉。披衣起，但凄凉感旧，慷慨生哀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春·梦孚若' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水龙吟·老来曾识渊明', '辛弃疾', '宋代', '老来曾识渊明，梦中一见参差是。觉来幽恨，停觞不御，欲歌还止。白发西风，折腰五斗，不应堪此。问北窗高卧，东篱自醉，应别有，归来意。\n须信此翁未死，到如今凛然生气。吾侪心事，古今长在，高山流水。富贵他年，直饶未免，也应无味。甚东山何事，当时也道，为苍生起。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水龙吟·老来曾识渊明' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('念奴娇·书东流村壁', '辛弃疾', '宋代', '野棠花落，又匆匆过了，清明时节。刬地东风欺客梦，一枕云屏寒怯。曲岸持觞，垂杨系马，此地曾经别。楼空人去，旧游飞燕能说。\n闻道绮陌东头，行人长见，帘底纤纤月。旧恨春江流不断，新恨云山千叠。料得明朝，尊前重见，镜里花难折。也应惊问：近来多少华发？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '念奴娇·书东流村壁' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('木兰花·晚妆初了明肌雪', '李煜', '五代', '晚妆初了明肌雪，春殿嫔娥鱼贯列。\n笙箫吹断水云间，重按霓裳歌遍彻。\n临春谁更飘香屑？醉拍阑干情味切。\n归时休放烛光红，待踏马蹄清夜月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '木兰花·晚妆初了明肌雪' AND p.poem_author = '李煜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('流莺', '李商隐', '唐代', '流莺漂荡复参差，度陌临流不自持。\n巧啭岂能无本意？良辰未必有佳期。\n风朝露夜阴晴里，万户千门开闭时。\n曾苦伤春不忍听，凤城何处有花枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '流莺' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风', '李商隐', '唐代', '撩钗盘孔雀，恼带拂鸳鸯。罗荐谁教近，斋时锁洞房。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('成都曲', '张籍', '唐代', '锦江近西烟水绿，新雨山头荔枝熟。\n万里桥边多酒家，游人爱向谁家宿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '成都曲' AND p.poem_author = '张籍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·秦风·黄鸟', '佚名', '先秦', '交交黄鸟，止于棘。谁从穆公？子车奄息。维此奄息，百夫之特。临其穴，惴惴其栗。彼苍者天，歼我良人！如可赎兮，人百其身！\n交交黄鸟，止于桑。谁从穆公？子车仲行。维此仲行，百夫之防。临其穴，惴惴其栗。彼苍者天，歼我良人！如可赎兮，人百其身！\n交交黄鸟，止于楚。谁从穆公？子车针虎。维此针虎，百夫之御。临其穴，惴惴其栗。彼苍者天，歼我良人！如可赎兮，人百其身！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·秦风·黄鸟' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('匏有苦叶', '佚名', '先秦', '匏有苦叶，济有深涉。深则厉，浅则揭。\n有瀰济盈，有鷕雉鸣。济盈不濡轨，雉鸣求其牡。\n雍雍鸣雁，旭日始旦。士如归妻，迨冰未泮。\n招招舟子，人涉卬否。人涉卬否，卬须我友。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '匏有苦叶' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('万里瞿塘月', '杜甫', '唐代', '万里瞿唐月，春来六上弦。\n时时开暗室，故故满青天。\n爽合风襟静，高当泪脸悬。\n南飞有乌鹊，夜久落江边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '万里瞿塘月' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹枝词九首·其九', '刘禹锡', '唐代', '山上层层桃李花，云间烟火是人家。\n银钏金钗来负水，长刀短笠去烧畲。(烧畲 同 烧\n<a name="pmbazfqp">畬</a>）', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹枝词九首·其九' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·家住苍烟落照间', '陆游', '宋代', '家住苍烟落照间，丝毫尘事不相关。斟残玉瀣行穿竹，卷罢《黄庭》卧看山。\n贪啸傲，任衰残，不妨随处一开颜。元知造物心肠别，老却英雄似等闲！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·家住苍烟落照间' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜算子·兰', '曹组', '宋代', '松竹翠萝寒，迟日江山暮。幽径无人独自芳，此恨凭谁诉。似共梅花语。尚有寻芳侣。着意闻时不肯香，香在无心处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜算子·兰' AND p.poem_author = '曹组';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一丛花令·伤高怀远几时穷', '张先', '宋代', '伤高怀远几时穷？无物似情浓。离愁正引千丝乱，更东陌、飞絮蒙蒙。嘶骑渐遥，征尘不断，何处认郎踪！\n双鸳池沼水溶溶，南北小桡通。梯横画阁黄昏后，又还是、斜月帘栊。沉恨细思，不如桃杏，犹解嫁东风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '一丛花令·伤高怀远几时穷' AND p.poem_author = '张先';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日赴阙题潼关驿楼 / 行次潼关逢魏扶东归', '许浑', '唐代', '红叶晚萧萧，长亭酒一瓢。\n残云归太华，疏雨过中条。\n树色随山迥，河声入海遥。\n帝乡明日到，犹自梦渔樵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日赴阙题潼关驿楼 / 行次潼关逢魏扶东归' AND p.poem_author = '许浑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('月', '杜牧', '唐代', '三十六宫秋夜深，昭阳歌断信沉沉。\n唯应独伴陈皇后，照见长门望幸心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '月' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小至', '杜甫', '唐代', '天时人事日相催，冬至阳生春又来。\n刺绣五纹添弱线，吹葭六琯动浮灰。\n岸容待腊将舒柳，山意冲寒欲放梅。\n云物不殊乡国异，教儿且覆掌中杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小至' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桃源行', '王维', '唐代', '渔舟逐水爱山春，两岸桃花夹古津。\n坐看红树不知远，行尽青溪不见人。\n山口潜行始隈隩，山开旷望旋平陆。\n遥看一处攒云树，近入千家散花竹。\n樵客初传汉姓名，居人未改秦衣服。\n居人共住武陵源，还从物外起田园。\n月明松下房栊静，日出云中鸡犬喧。\n惊闻俗客争来集，竞引还家问都邑。\n平明闾巷扫花开，薄暮渔樵乘水入。\n初因避地去人间，及至成仙遂不还。\n峡里谁知有人事，世中遥望空云山。\n不疑灵境难闻见，尘心未尽思乡县。\n出洞无论隔山水，辞家终拟长游衍。\n自谓经过旧不迷，安知峰壑今来变。\n当时只记入山深，青溪几度到云林。\n春来遍是桃花水，不辨仙源何处寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桃源行' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西施咏', '王维', '唐代', '艳色天下重，西施宁久微。\n朝为越溪女，暮作吴宫妃。\n贱日岂殊众，贵来方悟稀。\n邀人傅香粉，不自著罗衣。\n君宠益娇态，君怜无是非。\n当时浣纱伴，莫得同车归。\n持谢邻家子，效颦安可希。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西施咏' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题大庾岭北驿', '宋之问', '唐代', '阳月南飞雁，传闻至此回。\n我行殊未已，何日复归来。\n江静潮初落，林昏瘴不开。\n明朝望乡处，应见陇头梅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题大庾岭北驿' AND p.poem_author = '宋之问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秦妇吟', '韦庄', '唐代', '中和癸卯春三月，洛阳城外花如雪。东西南北路人绝，绿杨悄悄香尘灭。路旁忽见如花人，独向绿杨阴下歇。凤侧鸾欹鬓脚斜，红攒黛敛眉心折。借问女郎何处来？含颦欲语声先咽。回头敛袂谢行人，丧乱漂沦何堪说！三年陷贼留秦地，依稀记得秦中事。君能为妾解金鞍，妾亦与君停玉趾。\n　　前年庚子腊月五，正闭金笼教鹦鹉。斜开鸾镜懒梳头，闲凭雕栏慵不语。忽看门外起红尘，已见街中擂金鼓。居人走出半仓惶，朝士归来尚疑误。是时西面官军入，拟向潼关为警急。皆言博野自相持，尽道贼军来未及。须臾主父乘奔至，下马入门痴似醉。适逢紫盖去蒙尘，已见白旗来匝地。\n　　扶羸携幼竞相呼，上屋缘墙不知次。南邻走入北邻藏，东邻走向西邻避。北邻诸妇咸相凑，户外崩腾如走兽。轰轰混混乾坤动，万马雷声从地涌。火迸金星上九天，十二官街烟烘烔。日轮西下寒光白，上帝无言空脉脉。阴云晕气若重围，宦者流星如血色。紫气潜随帝座移，妖光暗射台星拆。家家流血如泉沸，处处冤声声动地。舞伎歌姬尽暗捐，婴儿稚女皆生弃。\n　　东邻有女眉新画，倾国倾城不知价。长戈拥得上戎车，回首香闺泪盈把。旋抽金线学缝旗，才上雕鞍教走马。有时马上见良人，不敢回眸空泪下；西邻有女真仙子，一寸横波剪秋水。妆成只对镜中春，年幼不知门外事。一夫跳跃上金阶，斜袒半肩欲相耻。牵衣不肯出朱门，红粉香脂刀下死。南邻有女不记姓，昨日良媒新纳聘。琉璃阶上不闻行，翡翠帘间空见影。忽看庭际刀刃鸣，身首支离在俄顷。仰天掩面哭一声，女弟女兄同入井；北邻少妇行相促，旋拆云鬟拭眉绿。已闻击托坏高门，不觉攀缘上重屋。须臾四面火光来，欲下回梯梯又摧。烟中大叫犹求救，梁上悬尸已作灰。\n　　妾身幸得全刀锯，不敢踟蹰久回顾。旋梳蝉鬓逐军行，强展蛾眉出门去。旧里从兹不得归，六亲自此无寻处。一从陷贼经三载，终日惊忧心胆碎。夜卧千重剑戟围，朝餐一味人肝脍。鸳帏纵入岂成欢？宝货虽多非所爱。蓬头垢面眉犹赤，几转横波看不得。衣裳颠倒语言异，面上夸功雕作字。柏台多半是狐精，兰省诸郎皆鼠魅。还将短发戴华簪，不脱朝衣缠绣被。翻持象笏作三公，倒佩金鱼为两史。朝闻奏对入朝堂，暮见喧呼来酒市。\n　　一朝五鼓人惊起，叫啸喧呼如窃语。夜来探马入皇城，昨日官军收赤水。赤水去城一百里，朝若来兮暮应至。凶徒马上暗吞声，女伴闺中潜生喜。皆言冤愤此时销，必谓妖徒今日死。逡巡走马传声急，又道官军全阵入。大彭小彭相顾忧，二郎四郎抱鞍泣。沉沉数日无消息，必谓军前已衔璧。簸旗掉剑却来归，又道官军悉败绩。\n　　四面从兹多厄束，一斗黄金一斗粟。尚让厨中食木皮，黄巢机上刲人肉。东南断绝无粮道，沟壑渐平人渐少。六军门外倚僵尸，七架{寨}营中填饿殍。长安寂寂今何有？废市荒街麦苗秀。采樵斫尽杏园花，修寨诛残御沟柳。华轩绣毂皆销散，甲第朱门无一半。含元殿上狐兔行，花萼楼前荆棘满。昔时繁盛皆埋没，举目凄凉无故物。内库烧为锦绣灰，天街踏尽公卿骨！\n　　来时晓出城东陌，城外风烟如塞色。路旁时见游奕军，坡下寂无迎送客。霸陵东望人烟绝，树锁骊山金翠灭。大道俱成棘子林，行人夜宿墙匡月。明朝晓至三峰路，百万人家无一户。破落田园但有蒿，摧残竹树皆无主。路旁试问金天神，金天无语愁于人。庙前古柏有残枿，殿上金炉生暗尘。一从狂寇陷中国，天地晦冥风雨黑。案前神水咒不成，壁上阴兵驱不得。闲日徒歆奠飨恩，危时不助神通力。我今愧恧拙为神，且向山中深避匿。寰中箫管不曾闻，筵上牺牲无处觅。旋教魔鬼傍乡村，诛剥生灵过朝夕。妾闻此语愁更愁，天遣时灾非自由。神在山中犹避难，何须责望东诸侯！\n　　前年又出扬震关，举头云际见荆山。如从地府到人间，顿觉时清天地闲。陕州主帅忠且贞，不动干戈唯守城。蒲津主帅能戢兵，千里晏然无犬声。朝携宝货无人问，暮插金钗唯独行。明朝又过新安东，路上乞浆逢一翁。苍苍面带苔藓色，隐隐身藏蓬荻中。问翁本是何乡曲？底事寒天霜露宿？老翁暂起欲陈辞，却坐支颐仰天哭。乡园本贯东畿县，岁岁耕桑临近甸。岁种良田二百廛，年输户税三千万。小姑惯织褐絁袍，中妇能炊红黍饭。千间仓兮万丝箱，黄巢过后犹残半。自从洛下屯师旅，日夜巡兵入村坞。匣中秋水拔青蛇，旗上高风吹白虎。入门下马若旋风，罄室倾囊如卷土。家财既尽骨肉离，今日垂年一身苦。一身苦兮何足嗟，山中更有千万家，朝饥山上寻蓬子，夜宿霜中卧荻花！\n　　妾闻此老伤心语，竟日阑干泪如雨。出门惟见乱枭鸣，更欲东奔何处所？仍闻汴路舟车绝，又道彭门自相杀。野宿徒销战士魂，河津半是冤人血。适闻有客金陵至，见说江南风景异。自从大寇犯中原，戎马不曾生四鄙。诛锄窃盗若神功，惠爱生灵如赤子。城壕固护教{斆、敩、效}金汤，赋税如云送军垒。奈何四海尽滔滔，湛然一境平如砥。避难徒为阙下人，怀安却羡江南鬼。愿君举棹东复东，咏此长歌献相公。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秦妇吟' AND p.poem_author = '韦庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蹇叔哭师', '左丘明', '先秦', '冬，晋文公卒。庚辰，将殡于曲沃。出绛，柩有声如牛。卜偃使大夫拜，曰：“君命大事将有西师过轶我，击之，必大捷焉。”\n\n　　杞子自郑使告于秦曰：“郑人使我掌其北门之管，若潜师以来，国可得也。”穆公访诸蹇叔。蹇叔曰：“劳师以袭远，非所闻也。师劳力竭，远主备之，无乃不可乎？师之所为，郑必知之。 勤而无所，必有悖心。且行千里，其谁不知？”公辞焉。召孟明、 西乞、白乙使出师于东门之外。蹇叔哭之曰：“孟子！吾见师之出而不见其入也。”公使谓之曰：“尔何知！中寿，尔墓之木拱矣！”\n\n　　蹇叔之子与师，哭而送之，曰：“晋人御师必于崤，有二陵焉。 其南陵，夏后皋之墓地；其北陵，文王之所辟风雨也，必死是间，余收尔骨焉?秦师遂东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蹇叔哭师' AND p.poem_author = '左丘明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹊桥仙·夜闻杜鹃', '陆游', '宋代', '茅檐人静，蓬窗灯暗，春晚连江风雨。林莺巢燕总无声，但月夜、常啼杜宇。\n催成清泪，惊残孤梦，又拣深枝飞去。故山犹自不堪听，况半世、飘然羁旅！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹊桥仙·夜闻杜鹃' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('好事近·风定落花深', '李清照', '宋代', '风定落花深，帘外拥红堆雪。长记海棠开后，正伤春时节。\n酒阑歌罢玉尊空，青缸暗明灭。魂梦不堪幽怨，更一声啼鴂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '好事近·风定落花深' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮·风柔日薄春犹早', '李清照', '宋代', '风柔日薄春犹早，夹衫乍著心情好。睡起觉微寒，梅花鬓上残。\n故乡何处是，忘了除非醉。沉水卧时烧，香消酒未消。\n&nbsp;', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮·风柔日薄春犹早' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人·有美堂赠述古', '苏轼', '宋代', '湖山信是东南美，一望弥千里。使君能得几回来？便使樽前醉倒更徘徊。\n沙河塘里灯初上，水调谁家唱？夜阑风静欲归时，惟有一江明月碧琉璃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人·有美堂赠述古' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红·忧喜相寻', '苏轼', '宋代', '董毅夫名钺，自梓漕得罪，罢官东川，归鄱阳，过东坡于齐安。怪其丰暇自得，余问之。曰：“吾再娶柳氏，三日而去官。吾固不戚戚，而优柳氏不能忘怀于进退也。已而欣然，同忧共若处富贵，吾是以益安焉。”命其侍儿歌其所作《满江红》。嗟叹之不足，乃次其韵。\n\n忧喜相寻，风雨过、一江春绿。巫峡梦、至今空有，乱山屏簇。何似伯鸾携德耀，箪瓢未足清欢足。渐粲然、光彩照阶庭，生兰玉。\n幽梦里，传心曲。肠断处，凭他续。文君婿知否，笑君卑辱。君不见周南歌汉广，天教夫子休乔木。便相将、左手抱琴书，云间宿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红·忧喜相寻' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望江南·江南柳', '欧阳修', '宋代', '江南柳，叶小未成阴。人为丝轻那忍折，莺嫌枝嫩不胜吟。留著待春深。\n十四五，闲抱琵琶寻。阶上簸钱阶下走，恁时相见早留心。何况到如今。(莺嫌 一作：莺怜；留著 一作：留取)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望江南·江南柳' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春残', '翁宏', '唐代', '又是春残也，如何出翠帏？\n落花人独立，微雨燕双飞。\n寓目魂将断，经年梦亦非。\n那堪向愁夕，萧飒暮蝉辉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春残' AND p.poem_author = '翁宏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岁暮归南山 / 归故园作 / 归终南山', '孟浩然', '唐代', '北阙休上书，南山归敝庐。不才明主弃，多病故人疏。 \n白发催年老，青阳逼岁除。永怀愁不寐，松月夜窗虚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岁暮归南山 / 归故园作 / 归终南山' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('踏歌词四首·其一', '刘禹锡', '唐代', '春江月出大堤平，堤上女郎连袂行。\n唱尽新词欢不见，红霞映树鹧鸪鸣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '踏歌词四首·其一' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五代史伶官传序', '欧阳修', '宋代', '呜呼！盛衰之理，虽曰天命，岂非人事哉！原庄宗之所以得天下，与其所以失之者，可以知之矣。\n\n　　世言晋王之将终也，以三矢赐庄宗而告之曰：“梁，吾仇也；燕王，吾所立；契丹与吾约为兄弟；而皆背晋以归梁。此三者，吾遗恨也。与尔三矢，尔其无忘乃父之志！”庄宗受而藏之于庙。其后用兵，则遣从事以一少牢告庙，请其矢，盛以锦囊，负而前驱，及凯旋而纳之。\n\n　　方其系燕父子以组，函梁君臣之首，入于太庙，还矢先王，而告以成功，其意气之盛，可谓壮哉！及仇雠已灭，天下已定，一夫夜呼，乱者四应，仓皇东出，未及见贼而士卒离散，君臣相顾，不知所归。至于誓天断发，泣下沾襟，何其衰也！岂得之难而失之易欤？抑本其成败之迹，而皆自于人欤？\n\n　　《书》曰：“满招损，谦得益。”忧劳可以兴国，逸豫可以亡身，自然之理也。故方其盛也，举天下之豪杰，莫能与之争；及其衰也，数十伶人困之，而身死国灭，为天下笑。夫祸患常积于忽微，而智勇多困于所溺，岂独伶人也哉！作《伶官传》。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五代史伶官传序' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮·红楼别夜堪惆怅', '韦庄', '唐代', '红楼别夜堪惆怅，香灯半卷流苏帐。\n残月出门时，美人和泪辞。\n琵琶金翠羽，弦上黄莺语。\n劝我早还家，绿窗人似花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮·红楼别夜堪惆怅' AND p.poem_author = '韦庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('京师得家书', '袁凯', '明代', '江水三千里，家书十五行。\n行行无别语，只道早还乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '京师得家书' AND p.poem_author = '袁凯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜算子·片片蝶衣轻', '刘克庄', '宋代', '片片蝶衣轻，点点猩红小。道是天公不惜花，百种千般巧。 \n朝见树头繁，暮见枝头少。道是天公果惜花，雨洗风吹了。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜算子·片片蝶衣轻' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('千秋岁·水边沙外', '秦观', '宋代', '水边沙外。城郭春寒退。花影乱，莺声碎。飘零疏酒盏，离别宽衣带。人不见，碧云暮合空相对。 \n忆昔西池会。鹓鹭同飞盖。携手处，今谁在。日边清梦断，镜里朱颜改。春去也，飞红万点愁如海。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '千秋岁·水边沙外' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南乡子·自古帝王州', '王安石', '宋代', '自古帝王州，郁郁葱葱佳气浮。四百年来成一梦，堪愁。晋代衣冠成古丘。 \n绕水恣行游。上尽层城更上楼。往事悠悠君莫问，回头。槛外长江空自流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南乡子·自古帝王州' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('少年游·参差烟树灞陵桥', '柳永', '宋代', '参差烟树灞陵桥，风物尽前朝。衰杨古柳，几经攀折，憔悴楚宫腰。 \n夕阳闲淡秋光老，离思满蘅皋。一曲阳关，断肠声尽，独自凭兰桡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '少年游·参差烟树灞陵桥' AND p.poem_author = '柳永';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吊屈原赋', '贾谊', '两汉', '谊为长沙王太傅，既以谪去，意不自得；及度湘水，为赋以吊屈原。屈原，楚贤臣也。被谗放逐，作《离骚》赋，其终篇曰：“已矣哉！国无人兮，莫我知也。”遂自投汨罗而死。谊追伤之，因自喻，其辞曰：\n\n　　恭承嘉惠兮，俟罪长沙；侧闻屈原兮，自沉汨罗。造讬湘流兮，敬吊先生；遭世罔极兮，乃殒厥身。呜呼哀哉！逢时不祥。鸾凤伏竄兮，鸱枭翱翔。闒茸尊显兮，谗谀得志；贤圣逆曳兮，方正倒植。世谓随、夷为溷兮，谓跖、蹻为廉；莫邪为钝兮，铅刀为銛。吁嗟默默，生之无故兮；斡弃周鼎，宝康瓠兮。腾驾罷牛，骖蹇驴兮；骥垂两耳，服盐车兮。章甫荐履，渐不可久兮；嗟苦先生，独离此咎兮。\n\n　　讯曰：已矣！国其莫我知兮，独壹郁其谁语？凤漂漂其高逝兮，固自引而远去。袭九渊之神龙兮，沕深潜以自珍；偭蟂獭以隐处兮，夫岂从虾与蛭蟥？所贵圣人之神德兮，远浊世而自藏；使骐骥可得系而羁兮，岂云异夫犬羊？般纷纷其离此尤兮，亦夫子之故也。历九州而其君兮，何必怀此都也？凤凰翔于千仞兮，览德辉而下之；见细德之险徵兮，遥曾击而去之。彼寻常之污渎兮，岂能容夫吞舟之巨鱼？横江湖之鳣鲸兮，固将制于蝼蚁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吊屈原赋' AND p.poem_author = '贾谊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八月十五夜玩月', '栖白', '唐代', '寻常三五夜，不是不婵娟。\n及至中秋满，还胜别夜圆。\n清光凝有露，皓魄爽无烟。\n自古人皆望，年来又一年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八月十五夜玩月' AND p.poem_author = '栖白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('稻田', '韦庄', '唐代', '绿波春浪满前陂，极目连云稏肥。\n更被鹭鹚千点雪，破烟来入画屏飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '稻田' AND p.poem_author = '韦庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('营州歌', '高适', '唐代', '营州少年厌原野，狐裘蒙茸猎城下。\n虏酒千钟不醉人，胡儿十岁能骑马。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '营州歌' AND p.poem_author = '高适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答陆澧', '张九龄', '唐代', '松叶堪为酒，春来酿几多。\n不辞山路远，踏雪也相过。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答陆澧' AND p.poem_author = '张九龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小儿不畏虎', '苏轼', '宋代', '有妇人昼日置小儿沙上而浣衣于水者。虎自山上驰来，妇人仓皇沉水避之。二小儿戏沙上自若。虎熟视久之，至以首抵触，庶几其一就惧；而儿痴，竟不知。虎亦寻卒去。噫，虎之食人，先被之以威，而不惧之人，威亦无所施欤！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小儿不畏虎' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏怀古迹五首·其五', '杜甫', '唐代', '诸葛大名垂宇宙，宗臣遗像肃清高。\n三分割据纡筹策，万古云霄一羽毛。\n伯仲之间见伊吕，指挥若定失萧曹。\n运移汉祚终难复，志决身歼军务劳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏怀古迹五首·其五' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·未遇行藏谁肯信', '侯蒙', '宋代', '未遇行藏谁肯信，如今方表名踪。无端良匠画形容。当风轻借力，一举入高空。 \n才得吹嘘身渐稳，只疑远赴蟾宫。雨馀时候夕阳红。几人平地上，看我碧霄中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·未遇行藏谁肯信' AND p.poem_author = '侯蒙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·鹅湖归病起作', '辛弃疾', '宋代', '枕簟溪堂冷欲秋。断云依水晚来收。红莲相倚浑如醉，白鸟无言定自愁。 \n书咄咄，且休休。一丘一壑也风流。不知筋力衰多少，但觉新来懒上楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·鹅湖归病起作' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('昭君怨·咏荷上雨', '杨万里', '宋代', '午梦扁舟花底，香满西湖烟水。急雨打篷声，梦初惊。\n却是池荷跳雨，散了真珠还聚。聚作水银窝，泻清波。 (泻清波 一作：泛清波)', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '昭君怨·咏荷上雨' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浪淘沙·一叶忽惊秋', '贺铸', '宋代', '一叶忽惊秋。分付东流。殷勤为过白苹洲。洲上小楼帘半卷，应认归舟。 \n回首恋朋游。迹去心留。歌尘萧散梦云收。惟有尊前曾见月，相伴人愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浪淘沙·一叶忽惊秋' AND p.poem_author = '贺铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('破阵子', '晏殊', '宋代', '湖上西风斜日，荷花落尽红英。金菊满丛珠颗细，海燕辞巢翅羽轻。年年岁岁情。 \n 美酒一杯新熟，高歌数阕堪听。不向尊前同一醉，可奈光阴似水声。迢迢去未停。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '破阵子' AND p.poem_author = '晏殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('断句', '刘昶', '南北朝', '白云满鄣来，黄尘暗天起。\n关山四面绝，故乡几千里。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '断句' AND p.poem_author = '刘昶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别诗二首·其一', '范云', '南北朝', '洛阳城东西，长作经时别。\n昔去雪如花，今来花似雪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别诗二首·其一' AND p.poem_author = '范云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与小女', '韦庄', '唐代', '见人初解语呕哑，不肯归眠恋小车。 \n一夜娇啼缘底事，为嫌衣少缕金华。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与小女' AND p.poem_author = '韦庄';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瑶瑟怨' AND p.poem_author = '温庭筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('胡无人', '李白', '唐代', '严风吹霜海草凋，筋干精坚胡马骄。\n汉家战士三十万，将军兼领霍嫖姚。\n流星白羽腰间插，剑花秋莲光出匣。\n天兵照雪下玉关，虏箭如沙射金甲。\n云龙风虎尽交回，太白入月敌可摧。\n敌可摧，旄头灭，履胡之肠涉胡血。\n悬胡青天上，埋胡紫塞傍。\n胡无人，汉道昌。\n陛下之寿三千霜。但歌大风云飞扬，安得猛士兮守四方。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '胡无人' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('崔九欲往南山马上口号与别 / 留别王维 / 送崔九', '裴迪', '唐代', '归山深浅去，须尽丘壑美。\n莫学武陵人，暂游桃源里。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '崔九欲往南山马上口号与别 / 留别王维 / 送崔九' AND p.poem_author = '裴迪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('代答闺梦还', '张若虚', '唐代', '关塞年华早，楼台别望违。\n试衫著暖气，开镜觅春晖。\n燕入窥罗幕，蜂来上画衣。\n情催桃李艳，心寄管弦飞。\n妆洗朝相待，风花暝不归。\n梦魂何处入，寂寂掩重扉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '代答闺梦还' AND p.poem_author = '张若虚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('终南', '佚名', '先秦', '终南何有？有条有梅。君子至止，锦衣狐裘。颜如渥丹，其君也哉！\n终南何有？有纪有堂。君子至止，黻衣绣裳。佩玉将将，寿考不忘！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '终南' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·自洛阳往孟津道中作', '元好问', '金朝', '今古北邙山下路，黄尘老尽英雄。人生长恨水长东。幽怀谁共语，远目送归鸿。\n盖世功名将底用，从前错怨天公。浩歌一曲酒千钟。男儿行处是，未要论穷通。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·自洛阳往孟津道中作' AND p.poem_author = '元好问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋雁', '揭傒斯', '元代', '寒向江南暖，饥向江南饱。\n莫道江南恶，须道江南好。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋雁' AND p.poem_author = '揭傒斯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二翁登泰山', '佚名', '未知', '昔有二翁，同邑(里）而居。甲翁之妻子去乡，唯叟一人而已。一日，叟携酒至乙翁第，二人对酌，不亦乐乎！乙翁曰：“向吾远游冀﹑雍，然（但）未尝登泰山，君有意同行乎？”甲翁曰：“是山余亦未登，然老矣，恐力不胜。”乙翁曰：“差矣，汝之言！曩者愚公年且九十而移山，今吾辈方逾六旬，何老之有！”甲翁曰：“甚善！”翌日，二翁偕往，越钱塘，绝长江，而至泰阴。夜宿，凌晨上山。乙翁欲扶之，甲翁曰：“吾力尚可，无需相扶。”自日出至薄暮，已至半山矣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '小学', NULL FROM edu_poem p WHERE p.poem_title = '二翁登泰山' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫中调笑·团扇', '王建', '唐代', '团扇，团扇，美人病来遮面。\n玉颜憔悴三年，谁复商量管弦。\n弦管，弦管，春草昭阳路断。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫中调笑·团扇' AND p.poem_author = '王建';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江村晚眺', '戴复古', '宋代', '江头落日照平沙，潮退渔船阁岸斜。\n白鸟一双临水立，见人惊起入芦花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江村晚眺' AND p.poem_author = '戴复古';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('回车驾言迈', '佚名', '两汉', '回车驾言迈，悠悠涉长道。\n四顾何茫茫，东风摇百草。\n所遇无故物，焉得不速老。\n盛衰各有时，立身苦不早。\n人生非金石，岂能长寿考？\n奄忽随物化，荣名以为宝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '回车驾言迈' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丹阳送韦参军', '严维', '唐代', '丹阳郭里送行舟，一别心知两地秋。 \n日晚江南望江北，寒鸦飞尽水悠悠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丹阳送韦参军' AND p.poem_author = '严维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬至', '杜甫', '唐代', '年年至日长为客，忽忽穷愁泥杀人。\n江上形容吾独老，天边风俗自相亲。\n杖藜雪后临丹壑，鸣玉朝来散紫宸。\n心折此时无一寸，路迷何处见三秦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬至' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('折杨柳', '李白', '唐代', '垂杨拂绿水，摇艳东风年。\n花明玉关雪，叶暖金窗烟。\n美人结长想，对此心凄然。\n攀条折春色，远寄龙庭前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '折杨柳' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小雅·伐木', '佚名', '先秦', '伐木丁丁，鸟鸣嘤嘤。出自幽谷，迁于乔木。嘤其鸣矣，求其友声。\n相彼鸟矣，犹求友声。矧伊人矣，不求友生？神之听之，终和且平。\n伐木许许，酾酒有藇！既有肥羜，以速诸父。宁适不来，微我弗顾。\n於粲洒扫，陈馈八簋。既有肥牡，以速诸舅。宁适不来，微我有咎。\n伐木于阪，酾酒有衍。笾豆有践，兄弟无远。民之失德，乾餱以愆。\n有酒湑我，无酒酤我。坎坎鼓我，蹲蹲舞我。迨我暇矣，饮此湑矣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小雅·伐木' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登泰山记', '姚鼐', '清代', '泰山之阳，汶水西流；其阴，济水东流。阳谷皆入汶，阴谷皆入济。当其南北分者，古长城也。最高日观峰，在长城南十五里。\n\n　　余以乾隆三十九年十二月，自京师乘风雪，历齐河、长清，穿泰山西北谷，越长城之限，至于泰安。是月丁未，与知府朱孝纯子颍由南麓登。四十五里，道皆砌石为磴，其级七千有余。\n\n　　泰山正南面有三谷。中谷绕泰安城下，郦道元所谓环水也。余始循以入，道少半，越中岭，复循西谷，遂至其巅。古时登山，循东谷入，道有天门。东谷者，古谓之天门溪水，余所不至也。今所经中岭及山巅崖限当道者，世皆谓之天门云。道中迷雾冰滑，磴几不可登。及既上，苍山负雪，明烛天南；望晚日照城郭，汶水、徂徕如画，而半山居雾若带然。\n\n　　戊申晦，五鼓，与子颖坐日观亭，待日出。大风扬积雪击面。亭东自足下皆云漫。稍见云中白若摴蒱数十立者，山也。极天云一线异色，须臾成五彩。日上，正赤如丹，下有红光，动摇承之。或曰，此东海也。回视日观以西峰，或得日，或否，绛皓驳色，而皆若偻。\n\n　　亭西有岱祠，又有碧霞元君祠；皇帝行宫在碧霞元君祠东。是日，观道中石刻，自唐显庆以来，其远古刻尽漫失。僻不当道者，皆不及往。\n\n　　山多石，少土；石苍黑色，多平方，少圜。少杂树，多松，生石罅，皆平顶。冰雪，无瀑水，无鸟兽音迹。至日观数里内无树，而雪与人膝齐。\n\n　　桐城姚鼐记。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登泰山记' AND p.poem_author = '姚鼐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('初夏即事', '王安石', '宋代', '石梁茅屋有弯碕，流水溅溅度两陂。(度两陂 一作：度西陂)\n晴日暖风生麦气，绿阴幽草胜花时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '初夏即事' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉台体' AND p.poem_author = '权德舆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渡易水', '陈子龙', '明代', '并刀昨夜匣中鸣，燕赵悲歌最不平；\n易水潺湲云草碧，可怜无处送荆卿！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渡易水' AND p.poem_author = '陈子龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春晓', '元稹', '唐代', '半欲天明半未明，醉闻花气睡闻莺。 \n猧儿撼起钟声动，二十年前晓寺情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春晓' AND p.poem_author = '元稹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄全椒山中道士', '韦应物', '唐代', '今朝郡斋冷，忽念山中客。\n涧底束荆薪，归来煮白石。\n欲持一瓢酒，远慰风雨夕。\n落叶满空山，何处寻行迹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄全椒山中道士' AND p.poem_author = '韦应物';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·秦风·晨风', '佚名', '先秦', '鴥彼晨风，郁彼北林。未见君子，忧心钦钦。如何如何，忘我实多！\n山有苞栎，隰有六驳。未见君子，忧心靡乐。如何如何，忘我实多！\n山有苞棣，隰有树檖。未见君子，忧心如醉。如何如何，忘我实多！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·秦风·晨风' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闲情赋', '陶渊明', '魏晋', '初，张衡作《定情赋》，蔡邕作《静情赋》，检逸辞而宗澹泊，始则荡以思虑，而终归闲正。将以抑流宕之邪心，谅有助于讽谏。缀文之士，奕代继作；因并触类，广其辞义。余园闾多暇，复染翰为之；虽文妙不足，庶不谬作者之意乎。\n\n　　夫何瑰逸之令姿，独旷世以秀群。表倾城之艳色，期有德于传闻。佩鸣玉以比洁，齐幽兰以争芬。淡柔情于俗内，负雅志于高云。悲晨曦之易夕，感人生之长勤；同一尽于百年，何欢寡而愁殷！褰朱帏而正坐，泛清瑟以自欣。送纤指之余好，攮皓袖之缤纷。瞬美目以流眄，含言笑而不分。曲调将半，景落西轩。悲商叩林，白云依山。仰睇天路，俯促鸣弦。神仪妩媚，举止详妍。\n\n　　激清音以感余，愿接膝以交言。欲自往以结誓，惧冒礼之为愆；待凤鸟以致辞，恐他人之我先。意惶惑而靡宁，魂须臾而九迁：愿在衣而为领，承华首之余芳；悲罗襟之宵离，怨秋夜之未央！愿在裳而为带，束窈窕之纤身；嗟温凉之异气，或脱故而服新！愿在发而为泽，刷玄鬓于颓肩；悲佳人之屡沐，从白水而枯煎！愿在眉而为黛，随瞻视以闲扬；悲脂粉之尚鲜，或取毁于华妆！愿在莞而为席，安弱体于三秋；悲文茵之代御，方经年而见求！愿在丝而为履，附素足以周旋；悲行止之有节，空委弃于床前！愿在昼而为影，常依形而西东；悲高树之多荫，慨有时而不同！愿在夜而为烛，照玉容于两楹；悲扶桑之舒光，奄灭景而藏明！愿在竹而为扇，含凄飙于柔握；悲白露之晨零，顾襟袖以缅邈！愿在木而为桐，作膝上之鸣琴；悲乐极以哀来，终推我而辍音！\n\n　　考所愿而必违，徒契契以苦心。拥劳情而罔诉，步容与于南林。栖木兰之遗露，翳青松之余阴。傥行行之有觌，交欣惧于中襟；竟寂寞而无见，独悁想以空寻。敛轻裾以复路，瞻夕阳而流叹。步徙倚以忘趣，色凄惨而矜颜。叶燮燮以去条，气凄凄而就寒，日负影以偕没，月媚景于云端。鸟凄声以孤归，兽索偶而不还。悼当年之晚暮，恨兹岁之欲殚。思宵梦以从之，神飘飘而不安；若凭舟之失棹，譬缘崖而无攀。于时毕昴盈轩，北风凄凄，炯炯不寐，众念徘徊。起摄带以侍晨，繁霜粲于素阶。鸡敛翅而未鸣，笛流远以清哀；始妙密以闲和，终寥亮而藏摧。意夫人之在兹，托行云以送怀；行云逝而无语，时奄冉而就过。徒勤思而自悲，终阻山而滞河。迎清风以怯累，寄弱志于归波。尤《蔓草》之为会，诵《召南》之余歌。坦万虑以存诚，憩遥情于八遐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闲情赋' AND p.poem_author = '陶渊明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑子·花前失却游春侣', '冯延巳', '五代', '花前失却游春侣，独自寻芳。满目悲凉。纵有笙歌亦断肠。\n林间戏蝶帘间燕，各自双双。忍②更思量，绿树青苔半夕阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑子·花前失却游春侣' AND p.poem_author = '冯延巳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪后晚晴四山皆青惟东山全白赋最爱东山晴后雪二绝句', '杨万里', '宋代', '只知逐胜忽忘寒，小立春风夕照间。\n最爱东山晴后雪，软红光里涌银山。\n\n群山雪不到新晴，多作泥融少作冰。\n最爱东山晴后雪，却愁宜看不宜登。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪后晚晴四山皆青惟东山全白赋最爱东山晴后雪二绝句' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('明妃曲二首', '王安石', '宋代', '明妃初出汉宫时，泪湿春风鬓脚垂。\n低徊顾影无颜色，尚得君王不自持。\n归来却怪丹青手，入眼平生几曾有；\n意态由来画不成，当时枉杀毛延寿。\n一去心知更不归，可怜着尽汉宫衣；\n寄声欲问塞南事，只有年年鸿雁飞。\n家人万里传消息，好在毡城莫相忆；\n君不见咫尺长门闭阿娇，人生失意无南北。\n\n明妃初嫁与胡儿，毡车百两皆胡姬。\n含情欲语独无处，传与琵琶心自知。\n黄金杆拨春风手，弹看飞鸿劝胡酒。\n汉宫侍女暗垂泪，沙上行人却回首。\n汉恩自浅胡恩深，人生乐在相知心。\n可怜青冢已芜没，尚有哀弦留至今。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '明妃曲二首' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贺新郎·寄辛幼安和见怀韵', '陈亮', '宋代', '老去凭谁说。看几番、神奇臭腐，夏裘冬葛。父老长安今余几，后死无仇可雪。犹未燥、当时生发。二十五弦多少恨，算世间、那有平分月。胡妇弄，汉宫瑟。 \n树犹如此堪重别。只使君、从来与我，话头多合。行矣置之无足问，谁换妍皮痴骨。但莫使、伯牙弦绝。九转丹砂牢拾取，管精金、只是寻常铁。龙共虎，应声裂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贺新郎·寄辛幼安和见怀韵' AND p.poem_author = '陈亮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冉冉孤生竹', '佚名', '两汉', '冉冉孤生竹，结根泰山阿。\n与君为新婚，菟丝附女萝。\n菟丝生有时，夫妇会有宜。\n千里远结婚，悠悠隔山陂。\n思君令人老，轩车来何迟！\n伤彼蕙兰花，含英扬光辉。\n过时而不采，将随秋草萎。\n君亮执高节，贱妾亦何为！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冉冉孤生竹' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('文赋', '陆机', '魏晋', '余每观才士之所作，窃有以得其用心。夫放言谴辞，良多变矣，妍蚩好恶，可得而言。每自属文，尤见其情。恒患意不称物，文不逮意。盖非知之难，能之难也。故作《文赋》，以述先士之盛藻，因论作文之利害所由，它日殆可谓曲尽其妙。至于操斧伐柯，虽取则不远，若夫随手之变，良难以辞逮。盖所能言者具于此云。\n\n　　佇中区以玄览，颐情志于典坟。遵四时以叹逝，瞻万物而思纷。悲落叶于劲秋，喜柔条于芳春。心懔懔以怀霜，志眇眇而临云。詠世德之骏烈，诵先人之清芬。游文章之林府，嘉丽藻之彬彬。慨投篇而援笔，聊宣之乎斯文。\n\n　　其始也，皆收视反听，耽思傍讯。精骛八极，心游万仞。其致也，情曈曨而弥鲜，物昭晰而互进。倾群言之沥液、漱六艺之芳润。浮天渊以安流，濯下泉而潜浸。于是沉辞怫悦，若游鱼衔钩，而出重渊之深；浮藻联翩，若翰鸟婴缴，而坠曾云之峻。收百世之阙文，採千载之遗韻。谢朝华于已披，启夕秀于未振。观古今于须臾，抚四海于一瞬。然后选义按部，考辞就班。抱景者咸叩，怀响者毕弹。或因枝以振叶，或沿波而讨源。或本隐以之显，或求易而得难。或虎变而兽扰，或龙见而鸟澜。或妥帖而易施，或岨峿而不安。罄澄心以凝思，眇众虑而为言。笼天地于形内，挫万物于笔端。始躑躅于燥吻，终流离于濡翰。理扶质以立干，文垂条而结繁。信情貌之不差，故每变而在颜。思涉乐其必笑，方言哀而已叹。或操觚以率尔，或含毫而邈然。\n\n　　伊兹事之可乐，固圣贤之可钦。课虚无以责有，叩寂寞而求音。函绵邈于尺素，吐滂沛乎寸心。言恢之而弥广，思按之而逾深。播芳蕤之馥馥，发青条之森森。粲风飞而猋竖，郁云起乎翰林。\n\n　　体有万殊，物无一量。纷纭挥霍，形难为状。辞程才以效伎，意司契而为匠。在有无而僶俛，当浅深而不让。虽离方而遯圆，期穷形而尽相。故夫夸目者尚奢，惬心者贵当。言穷者无隘，论达者唯旷。\n\n　　诗缘情而绮靡，赋体物而浏亮。碑披文以相质，诔缠绵而悽怆。铭博约而温润，箴顿挫而清壮。颂优游以彬蔚，论精微而朗畅。奏平徹以闲雅，说炜晔而谲诳。虽区分之在兹，亦禁邪而制放。要辞达而理举，故无取乎冗长。\n\n　　其为物也多姿，其为体也屡迁；其会意也尚巧，其遣言也贵妍。暨音声之迭代，若五色之相宣。虽逝止之无常，故崎錡而难便。苟达变而相次，犹开流以纳泉；如失机而后会，恒操末以续颠。谬玄黄之秩叙，故淟涊而不鲜。\n\n　　或仰逼于先条，或俯侵于后章；或辞害而理比，或言顺而意妨。离之则双美，合之则两伤。考殿最于锱铢，定去留于毫芒；苟铨衡之所裁，固应绳其必当。\n\n　　或文繁理富，而意不指适。极无两致，尽不可益。立片言而居要，乃一篇之警策；虽众辞之有条，必待兹而效绩。亮功多而累寡，故取足而不易。\n\n　　或藻思綺合，清丽千眠。炳若缛绣，悽若繁絃。必所拟之不殊，乃闇合乎曩篇。虽杼轴于予怀，忧他人之我先。苟伤廉而愆义，亦虽爱而必捐。\n\n　　或苕发颖竖，离众绝致；形不可逐，响难为系。块孤立而特峙，非常音之所纬。心牢落而无偶，意徘徊而不能揥。石韫玉而山辉，水怀珠而川媚。彼榛楛之勿翦，亦蒙荣于集翠。缀《下里》于《白雪》，吾亦济夫所伟。\n\n　　或讬言于短韻，对穷迹而孤兴，俯寂寞而无友，仰寥廓而莫承；譬偏絃之独张，含清唱而靡应。或寄辞于瘁音，徒靡言而弗华，混妍蚩而成体，累良质而为瑕；象下管之偏疾，故虽应而不和。或遗理以存异，徒寻虚以逐微，言寡情而鲜爱，辞浮漂而不归；犹絃么而徽急，故虽和而不悲。或奔放以谐和，务嘈囋而妖冶，徒悦目而偶俗，故高声而曲下；寤《防露》与桑间，又虽悲而不雅。或清虚以婉约，每除烦而去滥，阙大羹之遗味，同朱絃之清氾；虽一唱而三叹，固既雅而不艳。\n\n　　若夫丰约之裁，俯仰之形，因宜适变，曲有微情。或言拙而喻巧，或理朴而辞轻；或袭故而弥新，或沿浊而更清；或览之而必察，或研之而后精。譬犹舞者赴节以投袂，歌者应絃而遣声。是盖轮扁所不得言，故亦非华说之所能精。\n\n　　普辞条与文律，良余膺之所服。练世情之常尤，识前脩之所淑。虽发于巧心，或受蚩于拙目。彼琼敷与玉藻，若中原之有菽。同橐籥之罔穷，与天地乎并育。虽纷蔼于此世，嗟不盈于予掬。患挈缾之屡空，病昌言之难属。故踸踔于短垣，放庸音以足曲。恒遗恨以终篇，岂怀盈而自足？惧蒙尘于叩缶，顾取笑乎鸣玉。\n\n　　若夫应感之会，通塞之纪，来不可遏，去不可止，藏若景灭，行犹响起。方天机之骏利，夫何纷而不理？思风发于胸臆，言泉流于唇齿；纷葳蕤以馺遝，唯豪素之所拟；文徽徽以溢目，音冷冷而盈耳。及其六情底滞，志往神留，兀若枯木，豁若涸流；揽营魂以探赜，顿精爽而自求；理翳翳而愈伏，思轧轧其若抽。是以或竭情而多悔，或率意而寡尤。虽兹物之在我，非余力之所戮。故时抚空怀而自惋，吾未识夫开塞之所由。\n\n　　伊兹文之为用，固众理之所因。恢万里而无阂，通亿载而为津。俯殆则于来叶，仰观象乎古人。济文武于将坠，宣风声于不泯。塗无远而不弥，理无微而弗纶。配霑润于云雨，象变化乎鬼神。被金石而德广，流管絃而日新。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '文赋' AND p.poem_author = '陆机';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('幼女词', '施肩吾', '唐代', '幼女才六岁，未知巧与拙。\n向夜在堂前，学人拜新月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '幼女词' AND p.poem_author = '施肩吾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九日龙山饮', '李白', '唐代', '九日龙山饮，黄花笑逐臣。\n醉看风落帽，舞爱月留人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九日龙山饮' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送人之军', '贺知章', '唐代', '常经绝脉塞，复见断肠流。送子成今别，令人起昔愁。 \n 陇云晴半雨，边草夏先秋。万里长城寄，无贻汉国忧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送人之军' AND p.poem_author = '贺知章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春思', '方岳', '宋代', '春风多可太忙生，长共花边柳外行。\n与燕作泥蜂酿蜜，才吹小雨又须晴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春思' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读书有所见作', '萧抡谓', '清代', '人心如良苗，得养乃滋长；\n苗以泉水灌，心以理义养。\n一日不读书，胸臆无佳想。\n一月不读书，耳目失精爽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读书有所见作' AND p.poem_author = '萧抡谓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长相思·折花枝', '俞彦', '明代', '折花枝，恨花枝，准拟花开人共卮，开时人去时。\n怕相思，已相思，轮到相思没处辞，眉间露一丝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长相思·折花枝' AND p.poem_author = '俞彦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闾门即事', '张继', '唐代', '耕夫召募爱楼船，春草青青万项田；\n试上吴门窥郡郭，清明几处有新烟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闾门即事' AND p.poem_author = '张继';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书河上亭壁', '寇准', '宋代', '岸阔樯稀波渺茫，独凭危槛思何长。\n萧萧远树疏林外，一半秋山带夕阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书河上亭壁' AND p.poem_author = '寇准';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苏幕遮·草', '梅尧臣', '宋代', '露堤平，烟墅杳。乱碧萋萋，雨后江天晓。独有庾郎年最少。窣地春袍，嫩色宜相照。\n接长亭，迷远道。堪怨王孙，不记归期早。落尽梨花春又了。满地残阳，翠色和烟老。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苏幕遮·草' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头·壬子三山被召陈端仁给事饮饯席上作', '辛弃疾', '宋代', '长恨复长恨，裁作短歌行。何人为我楚舞，听我楚狂声？余既滋兰九畹，又树蕙之百亩，秋菊更餐英。门外沧浪水，可以濯吾缨。\n一杯酒，问何似，身后名？人间万事，毫发常重泰山轻。悲莫悲生离别，乐莫乐新相识，儿女古今情。富贵非吾事，归与白鸥盟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头·壬子三山被召陈端仁给事饮饯席上作' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春晓', '李中', '唐代', '残烛犹存月尚明，几家帏幌梦魂惊。 \n 星河渐没行人动，历历林梢百舌声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春晓' AND p.poem_author = '李中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南轩松', '李白', '唐代', '南轩有孤松，柯叶自绵幂。\n清风无闲时，潇洒终日夕。\n阴生古苔绿，色染秋烟碧。\n何当凌云霄，直上数千尺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南轩松' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送李判官之润州行营', '刘长卿', '唐代', '万里辞家事鼓鼙，金陵驿路楚云西。\n江春不肯留行客，草色青青送马蹄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送李判官之润州行营' AND p.poem_author = '刘长卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春光好·蘋叶软', '和凝', '五代', '蘋叶软，杏花明，画船轻。双浴鸳鸯出绿汀，棹歌声。\n春水无风无浪，春天半雨半晴。红粉相随南浦晚，几含情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春光好·蘋叶软' AND p.poem_author = '和凝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('巫山一段云·古庙依青嶂', '李珣', '唐代', '古庙依青嶂，行宫枕碧流。水声山色锁妆楼。往事思悠悠。\n云雨朝还暮，烟花春复秋。啼猿何必近孤舟。行客自多愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '巫山一段云·古庙依青嶂' AND p.poem_author = '李珣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜坐', '张耒', '宋代', '庭户无人秋月明，夜霜欲落气先清。\n梧桐真不甘衰谢，数叶迎风尚有声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜坐' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹊桥仙·一竿风月', '陆游', '宋代', '一竿风月，一蓑烟雨，家在钓台西住。卖鱼生怕近城门，况肯到红尘深处？\n潮生理棹，潮平系缆，潮落浩歌归去。时人错把比严光，我自是无名渔父。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹊桥仙·一竿风月' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙·咏橘', '苏轼', '宋代', '菊暗荷枯一夜霜。新苞绿叶照林光。竹篱茅舍出青黄。 \n香雾噀人惊半破，清泉流齿怯初尝。吴姬三日手犹香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙·咏橘' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汴河怀古二首', '皮日休', '唐代', '万艘龙舸绿丝间，载到扬州尽不还。\n应是天教开汴水，一千余里地无山。\n\n尽道隋亡为此河，至今千里赖通波。\n若无水殿龙舟事，共禹论功不较多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汴河怀古二首' AND p.poem_author = '皮日休';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出塞词', '马戴', '唐代', '金带连环束战袍，马头冲雪度临洮。\n卷旗夜劫单于帐，乱斫胡兵缺宝刀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出塞词' AND p.poem_author = '马戴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('听颖师弹琴', '韩愈', '唐代', '昵昵儿女语，恩怨相尔汝。\n划然变轩昂，勇士赴敌场。\n浮云柳絮无根蒂，天地阔远随飞扬。\n喧啾百鸟群，忽见孤凤皇。(凤皇 一作 凤凰）\n跻攀分寸不可上，失势一落千丈强。\n嗟余有两耳，未省听丝篁。\n自闻颖师弹，起坐在一旁。\n推手遽止之，湿衣泪滂滂。\n颖乎尔诚能，无以冰炭置我肠！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '听颖师弹琴' AND p.poem_author = '韩愈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望岳三首·其二', '杜甫', '唐代', '西岳崚嶒竦处尊，诸峰罗立似儿孙。\n安得仙人九节杖，拄到玉女洗头盆。\n车箱入谷无归路，箭栝通天有一门。\n稍待秋风凉冷后，高寻白帝问真源。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望岳三首·其二' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('武威送刘判官赴碛西行军', '岑参', '唐代', '火山五月行人少，看君马去疾如鸟。 \n都护行营太白西，角声一动胡天晓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '武威送刘判官赴碛西行军' AND p.poem_author = '岑参';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('园有桃', '佚名', '先秦', '园有桃，其实之肴。心之忧矣，我歌且谣。不知我者，谓我士也骄。彼人是哉，子曰何其？心之忧矣，其谁知之？其谁知之，盖亦勿思！\n园有棘，其实之食。心之忧矣，聊以行国。不知我者，谓我士也罔极。彼人是哉，子曰何其？心之忧矣，其谁知之？其谁知之，盖亦勿思！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '园有桃' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东坡', '苏轼', '宋代', '雨洗东坡月色清，市人行尽野人行。\n莫嫌荦确坡头路，自爱铿然曳杖声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东坡' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('论诗三十首·其四', '元好问', '金朝', '一语天然万古新，豪华落尽见真淳。\n南窗白日羲皇上，未害渊明是晋人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '论诗三十首·其四' AND p.poem_author = '元好问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('臧僖伯谏观鱼', '左丘明', '先秦', '春，公将如棠观鱼者。臧僖伯谏曰：“凡物不足以讲大事，其材不足以备器用，则君不举焉。君将纳民于轨物者也。故讲事以度轨量，谓之‘轨’；取材以章物采，谓之‘物’。不轨不物，谓之乱政。乱政亟行，所以败也。故春蒐、夏苗、秋狝、冬狩，皆于农隙以讲事也。三年而治兵，入而振旅，归而饮至，以数军实。昭文章，明贵贱，辨等列，顺少长，习威仪也。鸟兽之肉不登于俎，皮革、齿牙、骨角、毛羽不登于器，则君不射，古之制也。若夫山林川泽之实，器用之资，皂隶之事，官司之守，非君所及也。”\n\n　　公曰：“吾将略地焉。”遂往，陈鱼而观之。僖伯称疾不从。\n\n　　书曰：“公矢鱼与棠。”非礼也，且言远地也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '臧僖伯谏观鱼' AND p.poem_author = '左丘明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('放言五首·其五', '白居易', '唐代', '泰山不要欺毫末，颜子无心羡老彭。\n松树千年终是朽，槿花一日自为荣。\n何须恋世常忧死，亦莫嫌身漫厌生。\n生去死来都是幻，幻人哀乐系何情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '放言五首·其五' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠梁任父母同年 / 题梁任父同年', '黄遵宪', '清代', '寸寸山河寸寸金，侉离分裂力谁任。\n杜鹃再拜忧天泪，精卫无穷填海心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠梁任父母同年 / 题梁任父同年' AND p.poem_author = '黄遵宪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南乡子·秋暮村居', '纳兰性德', '清代', '红叶满寒溪，一路空山万木齐。试上小楼极目望，高低。一片烟笼十里陂。\n吠犬杂鸣鸡，灯火荧荧归路迷。乍逐横山时近远，东西。家在寒林独掩扉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南乡子·秋暮村居' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('落花', '宋祁', '宋代', '坠素翻红各自伤，青楼烟雨忍相忘。\n将飞更作回风舞，已落犹成半面妆。\n沧海客归珠有泪，章台人去骨遗香。\n可能无意传双蝶，尽付芳心与蜜房。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '落花' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·饮散离亭西去', '徐昌图', '五代', '饮散离亭西去，浮生长恨飘蓬。回头烟柳渐重重。淡云孤雁远，寒日暮天红。\n今夜画船何处？潮平淮月朦胧。酒醒人静奈愁浓。残灯孤枕梦，轻浪五更风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·饮散离亭西去' AND p.poem_author = '徐昌图';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梁甫吟', '李白', '唐代', '长啸梁甫吟，何时见阳春？\n君不见，朝歌屠叟辞棘津，八十西来钓渭滨。\n宁羞白发照清水，逢时壮气思经纶。\n广张三千六百钓，风期暗与文王亲。\n大贤虎变愚不测，当年颇似寻常人。\n君不见，高阳酒徒起草中，长揖山东隆准公。\n入门不拜逞雄辩，两女辍洗来趋风。\n东下齐城七十二，指挥楚汉如旋蓬。\n狂客落魄尚如此，何况壮士当群雄！\n我欲攀龙见明主，雷公砰訇震天鼓。\n帝旁投壶多玉女，三时大笑开电光，倏烁晦冥起风雨。\n阊阖九门不可通，以额扣关阍者怒。\n白日不照我精诚，杞国无事忧天倾。\n猰貐磨牙竞人肉，驺虞不折生草茎。\n手接飞猱搏雕虎，侧足焦原未言苦。\n智者可卷愚者豪，世人见我轻鸿毛。\n力排南山三壮士，齐相杀之费二桃。\n吴楚弄兵无剧孟，亚夫咍尔为徒劳。\n梁甫吟，声正悲。\n张公两龙剑，神物合有时。\n风云感会起屠钓，大人臲屼当安之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梁甫吟' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金明池·咏寒柳', '柳如是', '明代', '有怅寒潮，无情残照，正是萧萧南浦。更吹起，霜条孤影，还记得，旧时飞絮。况晚来，烟浪斜阳，见行客，特地瘦腰如舞。总一种凄凉，十分憔悴，尚有燕台佳句。\n春日酿成秋日雨。念畴昔风流，暗伤如许。纵饶有，绕堤画舸，冷落尽，水云犹故。忆从前，一点东风，几隔着重帘，眉儿愁苦。待约个梅魂，黄昏月淡，与伊深怜低语。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金明池·咏寒柳' AND p.poem_author = '柳如是';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大德歌·冬景', '关汉卿', '元代', '雪粉华，舞梨花，再不见烟村四五家。密洒堪图画，看疏林噪晚鸦。黄芦掩映清江下，斜缆着钓鱼艖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大德歌·冬景' AND p.poem_author = '关汉卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寒食上冢', '杨万里', '宋代', '迳直夫何细！桥危可免扶？\n远山枫外淡，破屋麦边孤。\n宿草春风又，新阡去岁无。\n梨花自寒食，进节只愁余。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寒食上冢' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('踏莎行·春暮', '寇准', '宋代', '春色将阑，莺声渐老，红英落尽青梅小。画堂人静雨蒙蒙，屏山半掩余香袅。\n密约沉沉，离情杳杳，菱花尘满慵将照。倚楼无语欲销魂，长空黯淡连芳草。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '踏莎行·春暮' AND p.poem_author = '寇准';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江南', '罗隐', '唐代', '玉树歌声泽国春，累累辎重忆亡陈。 \n 垂衣端拱浑闲事，忍把江山乞与人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江南' AND p.poem_author = '罗隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹枝词九首', '刘禹锡', '唐代', '白帝城头春草生，白盐山下蜀江清。\n南人上来歌一曲，北人莫上动乡情。\n\n山桃红花满上头，蜀江春水拍山流。\n花红易衰似郎意，水流无限似侬愁。\n\n江上朱楼新雨晴，瀼西春水縠文生。\n桥东桥西好杨柳，人来人去唱歌行。\n\n日出三竿春雾消，江头蜀客驻兰桡。\n凭寄狂夫书一纸，信在成都万里桥。\n\n两岸山花似雪开，家家春酒满银杯。\n昭君坊中多女伴，永安宫外踏青来。\n\n城西门前滟滪堆，年年波浪不能摧。\n懊恼人心不如石，少时东去复西来。\n\n瞿塘嘈嘈十二滩，此中道路古来难。\n长恨人心不如水，等闲平地起波澜。\n\n巫峡苍苍烟雨时，清猿啼在最高枝。\n个里愁人肠自断，由来不是此声悲。\n\n山上层层桃李花，云间烟火是人家。\n银钏金钗来负水，长刀短笠去烧畲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹枝词九首' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢赐珍珠', '江采萍', '唐代', '桂叶双眉久不描，残妆和泪污红绡。\n长门尽日无梳洗，何必珍珠慰寂寥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢赐珍珠' AND p.poem_author = '江采萍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·鄘风·墙有茨', '佚名', '先秦', '墙有茨，不可扫也。中冓之言，不可道也。所可道也，言之丑也。\n墙有茨，不可襄也。中冓之言，不可详也。所可详也，言之长也。\n墙有茨，不可束也。中冓之言，不可读也。所可读也，言之辱也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·鄘风·墙有茨' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('心术', '苏洵', '宋代', '为将之道，当先治心。泰山崩于前而色不变，麋鹿兴于左而目不瞬，然后可以制利害，可以待敌。\n\n　　凡兵上义；不义，虽利勿动。非一动之为利害，而他日将有所不可措手足也。夫惟义可以怒士，士以义怒，可与百战。\n\n　　凡战之道，未战养其财，将战养其力，既战养其气，既胜养其心。谨烽燧，严斥堠，使耕者无所顾忌，所以养其财；丰犒而优游之，所以养其力；小胜益急，小挫益厉，所以养其气；用人不尽其所欲为，所以养其心。故士常蓄其怒、怀其欲而不尽。怒不尽则有馀勇，欲不尽则有馀贪。故虽并天下，而士不厌兵，此黄帝之所以七十战而兵不殆也。不养其心，一战而胜，不可用矣。\n\n　　凡将欲智而严，凡士欲愚。智则不可测，严则不可犯，故士皆委己而听命，夫安得不愚？夫惟士愚，而后可与之皆死。\n\n　　凡兵之动，知敌之主，知敌之将，而后可以动于险。邓艾缒兵于蜀中，非刘禅之庸，则百万之师可以坐缚，彼固有所侮而动也。故古之贤将，能以兵尝敌，而又以敌自尝，故去就可以决。\n\n　　凡主将之道，知理而后可以举兵，知势而后可以加兵，知节而后可以用兵。知理则不屈，知势则不沮，知节则不穷。见小利不动，见小患不避，小利小患，不足以辱吾技也，夫然后有以支大利大患。夫惟养技而自爱者，无敌于天下。故一忍可以支百勇，一静可以制百动。\n\n　　兵有长短，敌我一也。敢问：“吾之所长，吾出而用之，彼将不与吾校；吾之所短，吾蔽而置之，彼将强与吾角，奈何？”曰：“吾之所短，吾抗而暴之，使之疑而却；吾之所长，吾阴而养之，使之狎而堕其中。此用长短之术也。”\n\n　　善用兵者，使之无所顾，有所恃。无所顾，则知死之不足惜；有所恃，则知不至于必败。尺箠当猛虎，奋呼而操击；徒手遇蜥蜴，变色而却步，人之情也。知此者，可以将矣。袒裼而案剑，则乌获不敢逼；冠胄衣甲，据兵而寝，则童子弯弓杀之矣。故善用兵者以形固。夫能以形固，则力有馀矣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '心术' AND p.poem_author = '苏洵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔歌子·荻花秋', '李珣', '五代', '荻花秋，潇湘夜，橘洲佳景如屏画。碧烟中，明月下，小艇垂纶初罢。\n水为乡，篷作舍，鱼羹稻饭常餐也。酒盈杯，书满架，名利不将心挂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔歌子·荻花秋' AND p.poem_author = '李珣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日', '汪藻', '宋代', '一春略无十日晴，处处浮云将雨行。\n野田春水碧于镜，人影渡傍鸥不惊。\n桃花嫣然出篱笑，似开未开最有情。\n茅茨烟暝客衣湿，破梦午鸡啼一声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日' AND p.poem_author = '汪藻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贺圣朝·留别', '叶清臣', '宋代', '满斟绿醑留君住。莫匆匆归去。三分春色二分愁，更一分风雨。\n花开花谢、都来几许。且高歌休诉。不知来岁牡丹时，再相逢何处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贺圣朝·留别' AND p.poem_author = '叶清臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉楼春·红酥肯放琼苞碎', '李清照', '宋代', '红酥肯放琼苞碎。探著南枝开遍未。不知酝藉几多香，但见包藏无限意。 \n道人憔悴春窗底。闷损阑干愁不倚。要来小酌便来休，未必明朝风不起。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉楼春·红酥肯放琼苞碎' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人·碧桃天上栽和露', '秦观', '宋代', '碧桃天上栽和露，不是凡花数。乱山深处水萦回，可惜一枝如画为谁开？\n轻寒细雨情何限！不道春难管。为君沉醉又何妨，只怕酒醒时候断人肠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人·碧桃天上栽和露' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红·怀子由作', '苏轼', '宋代', '清颍东流，愁目断，孤帆明灭。宦游处，青山白浪，万重千叠。孤负当年林下意，对床夜雨听萧瑟。恨此生，长向别离中，生华发。\n一尊酒，黄河侧。无限事，从头说。相看恍如昨，许多年月。衣上旧痕余苦泪，眉间喜气占黄色。便与君，池上觅残春，花如雪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红·怀子由作' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('远师', '白居易', '唐代', '东宫白庶子，南寺远禅师。\n何处遥相见，心无一事时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '远师' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬问师', '刘商', '唐代', '虚空无处所，仿佛似琉璃。诗境何人到，禅心又过诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬问师' AND p.poem_author = '刘商';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丽人行', '杜甫', '唐代', '三月三日天气新，长安水边多丽人。\n态浓意远淑且真，肌理细腻骨肉匀。\n绣罗衣裳照暮春，蹙金孔雀银麒麟。\n头上何所有？翠微盍叶垂鬓唇。\n背后何所见？珠压腰衱稳称身。\n就中云幕椒房亲，赐名大国虢与秦。\n紫驼之峰出翠釜，水精之盘行素鳞。\n犀箸厌饫久未下，鸾刀缕切空纷纶。\n黄门飞鞚不动尘，御厨络绎送八珍。\n箫鼓哀吟感鬼神，宾从杂遝实要津。\n后来鞍马何逡巡，当轩下马入锦茵。\n杨花雪落覆白苹，青鸟飞去衔红巾。\n炙手可热势绝伦，慎莫近前丞相嗔！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丽人行' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('听张立本女吟', '高适', '唐代', '危冠广袖楚宫妆，独步闲庭逐夜凉。 \n自把玉钗敲砌竹，清歌一曲月如霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '听张立本女吟' AND p.poem_author = '高适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('从军行二首', '王昌龄', '唐代', '向夕临大荒，朔风轸归虑。\n平沙万里馀，飞鸟宿何处。\n虏骑猎长原，翩翩傍河去。\n边声摇白草，海气生黄雾。\n百战苦风尘，十年履霜露。\n虽投定远笔，未坐将军树。\n早知行路难，悔不理章句。\n\n秋草马蹄轻，角弓持弦急。\n去为龙城战，正值胡兵袭。\n军气横大荒，战酣日将入。\n长风金鼓动，白露铁衣湿。\n四起愁边声，南庭时伫立。\n断蓬孤自转，寒雁飞相及。\n万里云沙涨，平原冰霰涩。\n惟闻汉使还，独向刀环泣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '从军行二首' AND p.poem_author = '王昌龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七夕', '杨朴', '宋代', '未会牵牛意若何，须邀织女弄金梭。\n年年乞与人间巧，不道人间巧已多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七夕' AND p.poem_author = '杨朴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('愚溪诗序', '柳宗元', '唐代', '灌水之阳有溪焉，东流入于潇水。或曰：冉氏尝居也，故姓是溪为冉溪。或曰：可以染也，名之以其能，故谓之染溪。予以愚触罪，谪潇水上。爱是溪，入二三里，得其尤绝者家焉。古有愚公谷，今予家是溪，而名莫能定，士之居者，犹龂龂然，不可以不更也，故更之为愚溪。\n\n　　愚溪之上，买小丘，为愚丘。自愚丘东北行六十步，得泉焉，又买居之，为愚泉。愚泉凡六穴，皆出山下平地，盖上出也。合流屈曲而南，为愚沟。遂负土累石，塞其隘，为愚池。愚池之东为愚堂。其南为愚亭。池之中为愚岛。嘉木异石错置，皆山水之奇者，以予故，咸以愚辱焉。\n\n　　夫水，智者乐也。今是溪独见辱于愚，何哉？盖其流甚下，不可以溉灌。又峻急多坻石，大舟不可入也。幽邃浅狭，蛟龙不屑，不能兴云雨，无以利世，而适类于予，然则虽辱而愚之，可也。\n\n　　宁武子“邦无道则愚”，智而为愚者也；颜子“终日不违如愚”，睿而为愚者也。皆不得为真愚。今予遭有道而违于理，悖于事，故凡为愚者，莫我若也。夫然，则天下莫能争是溪，予得专而名焉。\n\n　　溪虽莫利于世，而善鉴万类，清莹秀澈，锵鸣金石，能使愚者喜笑眷慕，乐而不能去也。予虽不合于俗，亦颇以文墨自慰，漱涤万物，牢笼百态，而无所避之。以愚辞歌愚溪，则茫然而不违，昏然而同归，超鸿蒙，混希夷，寂寥而莫我知也。于是作《八愚诗》，纪于溪石上。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '愚溪诗序' AND p.poem_author = '柳宗元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏牡丹', '王溥', '宋代', '枣花至小能成实，桑叶虽柔解吐丝。\n堪笑牡丹如斗大，不成一事又空枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏牡丹' AND p.poem_author = '王溥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望江南·天上月', '佚名', '五代', '天上月，遥望似一团银。夜久更阑风渐紧。与奴吹散月边云。照见负心人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望江南·天上月' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔家傲·五月榴花妖艳烘', '欧阳修', '宋代', '五月榴花妖艳烘。绿杨带雨垂垂重。五色新丝缠角粽。金盘送。生绡画扇盘双凤。\n正是浴兰时节动。菖蒲酒美清尊共。叶里黄鹂时一弄。犹瞢忪。等闲惊破纱窗梦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔家傲·五月榴花妖艳烘' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夕阳楼', '李商隐', '唐代', '花明柳暗绕天愁，上尽重城更上楼。\n欲问孤鸿向何处，不知身世自悠悠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夕阳楼' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚春二首·其二', '韩愈', '唐代', '谁收春色将归去，慢绿妖红半不存。\n榆荚只能随柳絮，等闲撩乱走空园。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚春二首·其二' AND p.poem_author = '韩愈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八月十五夜月二首', '杜甫', '唐代', '满月飞明镜，归心折大刀。\n转蓬行地远，攀桂仰天高。\n水路疑霜雪，林栖见羽毛。\n此时瞻白兔，直欲数秋毫。\n\n稍下巫山峡，犹衔白帝城。\n气沈全浦暗，轮仄半楼明。\n刁斗皆催晓，蟾蜍且自倾。\n张弓倚残魄，不独汉家营。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八月十五夜月二首' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春思', '皇甫冉', '唐代', '莺啼燕语报新年，马邑龙堆路几千。\n家住层城临汉苑，心随明月到胡天。(层城 一作：秦城)\n机中锦字论长恨，楼上花枝笑独眠。\n为问元戎窦车骑，何时返旆勒燕然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春思' AND p.poem_author = '皇甫冉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春江晚景', '张九龄', '唐代', '江林多秀发，云日复相鲜。\n征路那逢此，春心益渺然。\n兴来只自得，佳处莫能传。\n薄暮津亭下，余花满客船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春江晚景' AND p.poem_author = '张九龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·鄘风·柏舟', '佚名', '先秦', '泛彼柏舟，在彼中河。髧彼两髦，实维我仪。之死矢靡它。母也天只！不谅人只！\n泛彼柏舟，在彼河侧。髧彼两髦，实维我特。之死矢靡慝。母也天只！不谅人只！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·鄘风·柏舟' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长干行·君家何处住', '崔颢', '唐代', '君家何处住，妾住在横塘。\n停船暂借问，或恐是同乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长干行·君家何处住' AND p.poem_author = '崔颢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阮郎归·天边金掌露成霜', '晏几道', '宋代', '天边金掌露成霜。云随雁字长。绿杯红袖趁重阳。人情似故乡。\n兰佩紫，菊簪黄。殷勤理旧狂。欲将沉醉换悲凉。清歌莫断肠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阮郎归·天边金掌露成霜' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·十里楼台倚翠微', '晏几道', '宋代', '十里楼台倚翠微。百花深处杜鹃啼。殷勤自与行人语，不似流莺取次飞。 \n惊梦觉，弄晴时。声声只道不如归。天涯岂是无归意，争奈归期未可期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·十里楼台倚翠微' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咸阳值雨', '温庭筠', '唐代', '咸阳桥上雨如悬，万点空濛隔钓船。\n还似洞庭春水色，晓云将入岳阳天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咸阳值雨' AND p.poem_author = '温庭筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江楼夕望招客', '白居易', '唐代', '海天东望夕茫茫，山势川形阔复长。\n灯火万家城四畔，星河一道水中央。\n风吹古木晴天雨，月照平沙夏夜霜。\n能就江楼消暑否？比君茅舍较清凉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江楼夕望招客' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('云阳馆与韩绅宿别', '司空曙', '唐代', '故人江海别，几度隔山川。\n乍见翻疑梦，相悲各问年。\n孤灯寒照雨，深竹暗浮烟。\n更有明朝恨，离杯惜共传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '云阳馆与韩绅宿别' AND p.poem_author = '司空曙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重送裴郎中贬吉州', '刘长卿', '唐代', '猿啼客散暮江头，人自伤心水自流。 \n同作逐臣君更远，青山万里一孤舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重送裴郎中贬吉州' AND p.poem_author = '刘长卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国风·王风·兔爰', '佚名', '先秦', '有兔爰爰，雉离于罗。我生之初，尚无为；我生之后，逢此百罹。尚寐无吪！\n有兔爰爰，雉离于罦。我生之初，尚无造；我生之后，逢此百忧。尚寐无觉！\n有兔爰爰，雉离于罿。我生之初，尚无庸；我生之后，逢此百凶。尚寐无聪！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国风·王风·兔爰' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('君子阳阳', '佚名', '先秦', '君子阳阳，左执簧，右招我由房，其乐只且！\n君子陶陶，左执翿，右招我由敖，其乐只且！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '君子阳阳' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆秦娥·娄山关', '毛泽东', '现代', '西风烈，长空雁叫霜晨月。霜晨月，马蹄声碎，喇叭声咽。\n雄关漫道真如铁，而今迈步从头越。从头越，苍山如海，残阳如血。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆秦娥·娄山关' AND p.poem_author = '毛泽东';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·柳絮', '曹雪芹', '清代', '白玉堂前春解舞，东风卷得均匀。蜂围蝶阵乱纷纷。几曾随逝水？岂必委芳尘？\n万缕千丝终不改，任他随聚随分。韶华休笑本无根。好风凭借力，送我上青云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·柳絮' AND p.poem_author = '曹雪芹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凤凰台上忆吹箫·寸寸微云', '贺双卿', '清代', '寸寸微云，丝丝残照，有无明灭难消。正断魂魂断，闪闪摇摇。望望山山水水，人去去，隐隐迢迢。从今后，酸酸楚楚，只似今宵。\n青遥。问天不应，看小小双卿，袅袅无聊。更见谁谁见，谁痛花娇？谁望欢欢喜喜，偷素粉，写写描描？谁还管，生生世世，夜夜朝朝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凤凰台上忆吹箫·寸寸微云' AND p.poem_author = '贺双卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春夜别友人二首·其一', '陈子昂', '唐代', '银烛吐青烟，金樽对绮筵。\n离堂思琴瑟，别路绕山川。\n明月隐高树，长河没晓天。\n悠悠洛阳道，此会在何年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春夜别友人二首·其一' AND p.poem_author = '陈子昂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无俗念·灵虚宫梨花词', '丘处机', '宋代', '春游浩荡，是年年、寒食梨花时节。白锦无纹香烂漫，玉树琼葩堆雪。静夜沉沉，浮光霭霭，冷浸溶溶月。人间天上，烂银霞照通彻。\n浑似姑射真人，天姿灵秀，意气舒高洁。万化参差谁信道，不与群芳同列。浩气清英，仙材卓荦，下土难分别。瑶台归去，洞天方看清绝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无俗念·灵虚宫梨花词' AND p.poem_author = '丘处机';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塞下曲·其一', '李益', '唐代', '蕃州部落能结束，朝暮驰猎黄河曲。\n燕歌未断塞鸿飞，牧马群嘶边草绿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塞下曲·其一' AND p.poem_author = '李益';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江上', '王士祯', '清代', '吴头楚尾路如何？烟雨秋深暗自波。\n晚趁寒潮渡江去，满林黄叶雁声多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江上' AND p.poem_author = '王士祯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·浅浅余寒春半', '晏几道', '宋代', '浅浅余寒春半，雪消蕙草初长。烟迷柳岸旧池塘。风吹梅蕊闹，雨细杏花香。\n月堕枝头欢意，从前虚梦高唐，觉来何处放思量。如今不是梦，真个到伊行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·浅浅余寒春半' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆扬州', '徐凝', '唐代', '萧娘脸薄难胜泪，桃叶眉尖易觉愁。\n天下三分明月夜，二分无赖是扬州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆扬州' AND p.poem_author = '徐凝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小池二首', '白居易', '唐代', '昼倦前斋热，晚爱小池清。映林馀景没，近水微凉生。 \n 坐把蒲葵扇，闲吟三两声。 \n 有意不在大，湛湛方丈馀。荷侧泻清露，萍开见游鱼。 \n 每一临此坐，忆归青溪居。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小池二首' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏怀古迹五首·其一', '杜甫', '唐代', '支离东北风尘际，漂泊西南天地间。\n三峡楼台淹日月，五溪衣服共云山。\n羯胡事主终无赖，词客哀时且未还。\n庾信平生最萧瑟，暮年诗赋动江关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏怀古迹五首·其一' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寻南溪常山道人隐居 / 寻南溪常道士', '刘长卿', '唐代', '一路经行处，莓苔见履痕。\n白云依静渚，春草闭闲门。\n过雨看松色，随山到水源。\n溪花与禅意，相对亦忘言。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寻南溪常山道人隐居 / 寻南溪常道士' AND p.poem_author = '刘长卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赋得自君之出矣', '张九龄', '唐代', '自君之出矣，不复理残机。\n思君如满月，夜夜减清辉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赋得自君之出矣' AND p.poem_author = '张九龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('纪辽东二首', '杨广', '隋代', '辽东海北翦长鲸，风云万里清。\n方当销锋散马牛，旋师宴镐京。\n前歌后舞振军威，饮至解戎衣。\n判不徒行万里去，空道五原归。\n\n秉旄仗节定辽东，俘馘变夷风。\n清歌凯捷九都水，归宴洛阳宫。\n策功行赏不淹留，全军藉智谋。\n讵似南宫复道上，先封雍齿侯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '纪辽东二首' AND p.poem_author = '杨广';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄冈竹楼记', '王禹偁', '宋代', '黄冈之地多竹，大者如椽。竹工破之，刳去其节，用代陶瓦。比屋皆然，以其价廉而工省也。\n\n　　子城西北隅，雉堞圮毁，蓁莽荒秽，因作小楼二间，与月波楼通。远吞山光，平挹江濑，幽阒辽夐，不可具状。夏宜急雨，有瀑布声；冬宜密雪，有碎玉声。宜鼓琴，琴调虚畅；宜咏诗，诗韵清绝；宜围棋，子声丁丁然；宜投壶，矢声铮铮然；皆竹楼之所助也。\n\n　　公退之暇，被鹤氅衣，戴华阳巾，手执《周易》一卷，焚香默坐，消遣世虑。江山之外，第见风帆沙鸟，烟云竹树而已。待其酒力醒，茶烟歇，送夕阳，迎素月，亦谪居之胜概也。彼齐云、落星，高则高矣；井干、丽谯，华则华矣；止于贮妓女，藏歌舞，非骚人之事，吾所不取。\n\n　　吾闻竹工云：“竹之为瓦，仅十稔；若重覆之，得二十稔。”噫！吾以至道乙未岁，自翰林出滁上，丙申，移广陵；丁酉又入西掖；戊戌岁除日，新旧岁之交，即除夕。有齐安之命；己亥闰三月到郡。四年之间，奔走不暇；未知明年又在何处，岂惧竹楼之易朽乎！幸后之人与我同志，嗣而葺之，庶斯楼之不朽也！\n\n　　咸平二年八月十五日记。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄冈竹楼记' AND p.poem_author = '王禹偁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏芭蕉', '郑燮', '清代', '芭蕉叶叶为多情，一叶才舒一叶生。\n自是相思抽不尽，却教风雨怨秋声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏芭蕉' AND p.poem_author = '郑燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮·朔风吹散三更雪', '纳兰性德', '清代', '朔风吹散三更雪，倩魂犹恋桃花月。梦好莫催醒，由他好处行。\n无端听画角，枕畔红冰薄。塞马一声嘶，残星拂大旗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮·朔风吹散三更雪' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阮郎归·南园春半踏青时', '欧阳修', '宋代', '南园春半踏青时，风和闻马嘶。青梅如豆柳如眉，日长蝴蝶飞。\n花露重，草烟低，人家帘幕垂。秋千慵困解罗衣，画堂双燕归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阮郎归·南园春半踏青时' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('韩冬郎即席为诗相送一座尽惊他日余方追吟连宵侍坐裴回久之句有老成之风因成二绝寄酬兼呈畏之员外·其一', '李商隐', '唐代', '十岁裁诗走马成，冷灰残烛动离情。\n桐花万里丹山路，雏凤清于老凤声。\n\n剑栈风樯各苦辛，别时冰雪到时春。\n为凭何逊休联句，瘦尽东阳姓沈人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '韩冬郎即席为诗相送一座尽惊他日余方追吟连宵侍坐裴回久之句有老成之风因成二绝寄酬兼呈畏之员外·其一' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('月', '李商隐', '唐代', '池上与桥边，难忘复可怜。\n帘开最明夜，簟卷已凉天。\n流处水花急，吐时云叶鲜。\n姮娥无粉黛，只是逞婵娟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '月' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('武侯庙', '杜甫', '唐代', '遗庙丹青落，空山草木长。\n犹闻辞后主，不复卧南阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '武侯庙' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望木瓜山', '李白', '唐代', '早起见日出，暮见栖鸟还。\n客心自酸楚，况对木瓜山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望木瓜山' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沧浪歌', '佚名', '先秦', '沧浪之水清兮，可以濯我缨；\n沧浪之水浊兮，可以濯我足。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沧浪歌' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青玉案·年年社日停针线', '黄公绍', '宋代', '年年社日停针线。怎忍见、双飞燕。今日江城春已半。一身犹在，乱山深处，寂寞溪桥畔。\n春衫著破谁针线。点点行行泪痕满。落日解鞍芳草岸。花无人戴，酒无人劝，醉也无人管。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青玉案·年年社日停针线' AND p.poem_author = '黄公绍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汉宫春·立春日', '辛弃疾', '宋代', '春已归来，看美人头上，袅袅春幡。无端风雨，未肯收尽余寒。年时燕子，料今宵梦到西园。浑未辨，黄柑荐酒，更传青韭堆盘？\n却笑东风，从此便薰梅染柳，更没些闲。闲时又来镜里，转变朱颜。清愁不断，问何人会解连环？生怕见花开花落，朝来塞雁先还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汉宫春·立春日' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('念奴娇·登建康赏心亭呈史致道留守', '辛弃疾', '宋代', '我来吊古，上危楼、赢得闲愁千斛。虎踞龙蟠何处是，只有兴亡满目。柳外斜阳，水边归鸟，陇上吹乔木。片帆西去，一声谁喷霜竹。 \n却忆安石风流，东山岁晚，泪落哀筝曲。儿辈功名都付与，长日惟消棋局。宝镜难寻，碧云将暮，谁劝杯中绿。江头风怒，朝来波浪翻屋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '念奴娇·登建康赏心亭呈史致道留守' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·蝶懒莺慵春过半', '苏轼', '宋代', '蝶懒莺慵春过半。花落狂风，小院残红满。午醉未醒红日晚，黄昏帘幕无人卷。\n云鬓鬅松眉黛浅。总是愁媒，欲诉谁消遣。未信此情难系绊，杨花犹有东风管。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·蝶懒莺慵春过半' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔家傲', '欧阳修', '宋代', '对酒当歌劳客劝。惜花只惜年华晚。寒艳冷香秋不管。情眷眷。凭栏尽日愁无限。 \n 思抱芳期随寒雁。悔无深意传双燕。怅望一枝难寄远。人不见。楼头望断相思眼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔家傲' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·越女采莲秋水畔', '欧阳修', '宋代', '越女采莲秋水畔。窄袖轻罗，暗露双金钏。照影摘花花似面。芳心只共丝争乱。\n鸂鶒滩头风浪晚。雾重烟轻，不见来时伴。隐隐歌声归棹远。离愁引著江南岸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·越女采莲秋水畔' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·凤栖梧', '柳永', '宋代', '蜀锦地衣丝步障。屈曲回廊，静夜闲寻访。玉砌雕阑新月上。朱扉半掩人相望。 \n旋暖熏炉温斗帐。玉树琼枝，迤逦相偎傍。酒力渐浓春思荡。鸳鸯绣被翻红浪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·凤栖梧' AND p.poem_author = '柳永';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪梅香·景萧索', '柳永', '宋代', '景萧索，危楼独立面晴空。动悲秋情绪，当时宋玉应同。渔市孤烟袅寒碧，水村残叶舞愁红。楚天阔，浪浸斜阳，千里溶溶。 \n临风。想佳丽，别后愁颜，镇敛眉峰。可惜当年，顿乖雨迹云踪。雅态妍姿正欢洽，落花流水忽西东。无憀恨、相思意，尽分付征鸿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪梅香·景萧索' AND p.poem_author = '柳永';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沧浪亭记', '苏舜钦', '宋代', '予以罪废，无所归。扁舟吴中，始僦舍以处。时盛夏蒸燠，土居皆褊狭，不能出气，思得高爽虚辟之地，以舒所怀，不可得也。\n\n　　一日过郡学，东顾草树郁然，崇阜广水，不类乎城中。并水得微径于杂花修竹之间。东趋数百步，有弃地，纵广合五六十寻，三向皆水也。杠之南，其地益阔，旁无民居，左右皆林木相亏蔽。访诸旧老，云钱氏有国，近戚孙承右之池馆也。坳隆胜势，遗意尚存。予爱而徘徊，遂以钱四万得之，构亭北碕，号‘沧浪’焉。前竹后水，水之阳又竹，无穷极。澄川翠干，光影会合于轩户之间，尤与风月为相宜。予时榜小舟，幅巾以往，至则洒然忘其归。觞而浩歌，踞而仰啸，野老不至，鱼鸟共乐。形骸既适则神不烦，观听无邪则道以明；返思向之汩汩荣辱之场，日与锱铢利害相磨戛，隔此真趣，不亦鄙哉！\n\n　　噫！人固动物耳。情横于内而性伏，必外寓于物而后遣。寓久则溺，以为当然；非胜是而易之，则悲而不开。惟仕宦溺人为至深。古之才哲君子，有一失而至于死者多矣，是未知所以自胜之道。予既废而获斯境，安于冲旷，不与众驱，因之复能乎内外失得之原，沃然有得，笑闵万古。尚未能忘其所寓目，用是以为胜焉！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沧浪亭记' AND p.poem_author = '苏舜钦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青春', '韩偓', '唐代', '眼意心期卒未休，暗中终拟约秦楼。\n光阴负我难相遇，情绪牵人不自由。\n遥夜定嫌香蔽膝，闷时应弄玉搔头。\n樱桃花谢梨花发，肠断青春两处愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青春' AND p.poem_author = '韩偓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵新亭', '李白', '唐代', '金陵风景好，豪士集新亭。\n举目山河异，偏伤周顗情。\n四坐楚囚悲，不忧社稷倾。\n王公何慷慨，千载仰雄名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵新亭' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('车遥遥篇', '范成大', '宋代', '车遥遥，马憧憧。\n君游东山东复东，安得奋飞逐西风。\n愿我如星君如月，夜夜流光相皎洁。\n月暂晦，星常明。\n留明待月复，三五共盈盈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '车遥遥篇' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('迎燕', '葛天民', '宋代', '咫尺春三月， 寻常百姓家。\n为迎新燕入， 不下旧帘遮。\n翅湿沾微雨， 泥香带落花。\n巢成雏长大， 相伴过年华。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '迎燕' AND p.poem_author = '葛天民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花绝句·其二', '陆游', '宋代', '幽谷那堪更北枝，年年自分着花迟。\n高标逸韵君知否，正是层冰积雪时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花绝句·其二' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫之奇谏假道', '左丘明', '先秦', '晋侯复假道于虞以伐虢。\n\n　　宫之奇谏曰：“虢，虞之表也。虢亡，虞必从之。晋不可启，寇不可翫。一之谓甚，其可再乎？谚所谓‘辅车相依，唇亡齿寒’者，其虞、虢之谓也。”\n\n　　公曰：“晋，吾宗也，岂害我哉？”\n\n　　对曰：“大伯、虞仲，大王之昭也 。大伯不从，是以不嗣。虢仲、虢叔，王季之穆也，为文王卿士，勋在王室，藏于盟府。将虢是灭，何爱于虞！且虞能亲于桓、庄乎？其爱之也，桓、庄之族何罪？而以为戮，不唯逼乎？亲以宠逼，犹尚害之，况以国乎？”\n\n　　公曰：“吾享祀丰洁，神必据我。”\n\n　　对曰：“臣闻之，鬼神非人实亲，惟德是依。故《周书》曰：‘皇天无亲，惟德是辅。’又曰：‘黍稷非馨，明德惟馨。’又曰：‘民不易物，惟德繄物。’如是，则非德，民不和，神不享矣。神所冯依，将在德矣。若晋取虞，而明德以荐馨香，神其吐之乎？”\n\n　　弗听，许晋使。\n\n　　宫之奇以其族行，曰：“虞不腊矣。在此行也，晋不更举矣。”\n\n　　八月甲午，晋侯围上阳，问于卜偃曰：“吾其济乎？”\n\n　　对曰：“克之。”\n\n　　公曰：“何时？”\n\n　　对曰：“童谣曰：‘丙之晨，龙尾伏辰，均服振振，取虢之旂。鹑之贲贲，天策炖炖，火中成军，虢公其奔。’其九月、十月之交乎！丙子旦，日在尾，月在策，鹑火中，必是时也。”\n\n　　冬，十二月丙子朔，晋灭虢，虢公丑奔京师。师还，馆于虞，遂袭虞，灭之,执虞公.及其大夫井伯，从媵秦穆姬。而修虞祀，且归其职贡于王，故书曰：“晋人执虞公。”罪虞公，言易也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫之奇谏假道' AND p.poem_author = '左丘明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('石碏谏宠州吁', '左丘明', '先秦', '卫庄公娶于齐东宫得臣之妹，曰庄姜。美而无子，卫人所为赋《硕人》也。又娶于陈，曰厉妫。生孝伯，蚤死。其娣戴妫生桓公，庄姜以为己子。\n\n　　公子州吁，嬖人之子也。有宠而好兵，公弗禁，庄姜恶之。\n\n　　石碏谏曰：“臣闻爱子，教之以义方，弗纳于邪。骄奢淫佚，所自邪也。四者之来，宠禄过也。将立州吁，乃定之矣；若犹未也，阶之为祸。夫宠而不骄，骄而能降，降而不憾，憾而能眕者，鲜矣。且夫贱妨贵，少陵长，远间亲，新间旧，小加大，淫破义，所谓六逆也。君义，臣行，父慈，子孝，兄爱，弟敬，所谓六顺也。去顺效逆，所以速祸也。君人者，将祸是[通“事”]务去，而速之，无乃不可乎？”弗听。\n\n　　其子厚与州吁游，禁之，不可。桓公立，乃老。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '石碏谏宠州吁' AND p.poem_author = '左丘明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早梅', '道源', '明代', '万树寒无色，南枝独有花。\n香闻流水处，影落野人家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早梅' AND p.poem_author = '道源';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杨柳枝词九首·其一', '刘禹锡', '唐代', '塞北梅花羌笛吹，淮南桂树小山词。\n请君莫奏前朝曲，听唱新翻杨柳枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杨柳枝词九首·其一' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('眼儿媚·迟迟春日弄轻柔', '朱淑真', '宋代', '迟迟春日弄轻柔，花径暗香流。清明过了，不堪回首，云锁朱楼。\n午窗睡起莺声巧，何处唤春愁？绿杨影里，海棠亭畔，红杏梢头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '眼儿媚·迟迟春日弄轻柔' AND p.poem_author = '朱淑真';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九日送别', '王之涣', '唐代', '蓟庭萧瑟故人稀，何处登高且送归。 \n今日暂同芳菊酒，明朝应作断蓬飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九日送别' AND p.poem_author = '王之涣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绝句六首', '杜甫', '唐代', '日出篱东水，云生舍北泥。竹高鸣翡翠，沙僻舞鹍鸡。 \n 蔼蔼花蕊乱，飞飞蜂蝶多。幽栖身懒动，客至欲如何。 \n 凿井交棕叶，开渠断竹根。扁舟轻褭缆，小径曲通村。 \n 急雨捎溪足，斜晖转树腰。隔巢黄鸟并，翻藻白鱼跳。 \n 舍下笋穿壁，庭中藤刺檐。地晴丝冉冉，江白草纤纤。 \n 江动月移石，溪虚云傍花。鸟栖知故道，帆过宿谁家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绝句六首' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('落花落', '王勃', '唐代', '落花落，落花纷漠漠。\n绿叶青跗映丹萼，与君裴回上金阁。\n影拂妆阶玳瑁筵，香飘舞馆茱萸幕。\n落花飞，燎乱入中帷。\n落花春正满，春人归不归。\n落花度，氛氲绕高树。\n落花春已繁，春人春不顾。\n绮阁青台静且闲，罗袂红巾复往还。\n盛年不再得，高枝难重攀。\n试复旦游落花里，暮宿落花间。\n与君落花院，台上起双鬟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '落花落' AND p.poem_author = '王勃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长信怨', '王昌龄', '唐代', '金井梧桐秋叶黄，珠帘不卷夜来霜。\n熏笼玉枕无颜色，卧听南宫清漏长。\n\n高殿秋砧响夜阑，霜深犹忆御衣寒。\n银灯青琐裁缝歇，还向金城明主看。\n\n奉帚平明金殿开，暂将团扇共徘徊。\n玉颜不及寒鸦色，犹带昭阳日影来。\n\n真成薄命久寻思，梦见君王觉后疑。\n火照西宫知夜饮，分明复道奉恩时。\n\n长信宫中秋月明，昭阳殿下捣衣声。\n白露堂中细草迹，红罗帐里不胜情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长信怨' AND p.poem_author = '王昌龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清人', '佚名', '先秦', '清人在彭，驷介旁旁。二矛重英，河上乎翱翔。\n清人在消，驷介麃麃。二矛重乔，河上乎逍遥。\n清人在轴，驷介陶陶。左旋右抽，中军作好。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清人' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('右溪记', '元结', '唐代', '道州城西百余步，有小溪。南流数十步，合营溪。水抵两岸，悉皆怪石，欹嵌盘曲，不可名状。清流触石，洄悬激注；佳木异竹，垂阴相荫。\n\n　　此溪若在山野之上，则宜逸民退士之所游处；在人间，则可为都邑之胜境，静者之林亭。而置州以来，无人赏爱；徘徊溪上，为之怅然。乃疏凿芜秽，俾为亭宇；植松与桂，兼之香草，以裨形胜。为溪在州右，遂命之曰右溪。刻铭石上，彰示来者。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '右溪记' AND p.poem_author = '元结';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苏秦以连横说秦', '佚名', '先秦', '苏秦始将连横说秦惠王曰：“大王之国，西有巴、蜀、汉中之利，北有胡貉、代马之用，南有巫山、黔中之限，东有肴、函之固。田肥美，民殷富，战车万乘，奋击百万，沃野千里，蓄积饶多，地势形便，此所谓天府，天下之雄国也。以大王之贤，士民之众，车骑之用，兵法之教，可以并诸侯，吞天下，称帝而治。愿大王少留意，臣请奏其效。”\n\n　　秦王曰：“寡人闻之：毛羽不丰满者，不可以高飞，文章不成者不可以诛罚，道德不厚者不可以使民，政教不顺者不可以烦大臣。今先生俨然不远千里而庭教之，愿以异日。”\n\n　　苏秦曰：“臣固疑大王之不能用也。昔者神农伐补遂，黄帝伐涿鹿而禽蚩尤，尧伐驩兜，舜伐三苗，禹伐共工，汤伐有夏，文王伐崇，武王伐纣，齐桓任战而伯天下。由此观之，恶有不战者乎？古者使车毂击驰，言语相结，天下为一，约从连横，兵革不藏。文士并饬，诸侯乱惑，万端俱起，不可胜理。科条既备，民多伪态，书策稠浊，百姓不足。上下相愁，民无所聊，明言章理，兵甲愈起。辩言伟服，战攻不息，繁称文辞，天下不治。舌弊耳聋，不见成功，行义约信，天下不亲。于是乃废文任武，厚养死士，缀甲厉兵，效胜于战场。夫徒处而致利，安坐而广地，虽古五帝三王五伯，明主贤君，常欲坐而致之，其势不能。故以战续之，宽则两军相攻，迫则杖戟相橦，然后可建大功。是故兵胜于外，义强于内，威立于上，民服于下。今欲并天下，凌万乘，诎敌国，制海内，子元元，臣诸侯，非兵不可。今不嗣主，忽于至道，皆惛于教，乱于治，迷于言，惑于语，沈于辩，溺于辞。以此论之，王固不能行也。”\n\n　　说秦王书十上而说不行，黑貂之裘弊，黄金百斤尽，资用乏绝，去秦而归，羸縢履蹻，负书担橐，形容枯槁，面目犁黑，状有愧色。归至家，妻不下紝，嫂不为炊。父母不与言。苏秦喟叹曰：“妻不以我为夫，嫂不以我为叔，父母不以我为子，是皆秦之罪也。”乃夜发书，陈箧数十，得太公阴符之谋，伏而诵之，简练以为揣摩。读书欲睡，引锥自刺其股，血流至足，曰：“安有说人主，不能出其金玉锦绣，取卿相之尊者乎？”期年，揣摩成，曰：“此真可以说当世之君矣。”\n\n　　于是乃摩燕乌集阙，见说赵王于华屋之下，抵掌而谈，赵王大悦，封为武安君。受相印，革车百乘，锦绣千纯，白璧百双，黄金万溢，以随其后，约从散横以抑强秦，故苏秦相于赵而关不通。\n\n　　当此之时，天下之大，万民之众，王侯之威，谋臣之权，皆欲决苏秦之策。不费斗粮，未烦一兵，未战一士，未绝一弦，未折一矢，诸侯相亲，贤于兄弟。夫贤人在而天下服，一人用而天下从，故曰：式于政不式于勇；式于廊庙之内，不式于四境之外。当秦之隆，黄金万溢为用，转毂连骑，炫熿于道，山东之国从风而服，使赵大重。且夫苏秦，特穷巷掘门桑户棬枢之士耳，伏轼撙衔，横历天下，廷说诸侯之王，杜左右之口，天下莫之能伉。\n\n　　将说楚王，路过洛阳，父母闻之，清宫除道，张乐设饮，郊迎三十里。妻侧目而视，倾耳而听。嫂蛇行匍伏，四拜自跪而谢。苏秦曰：“嫂何前倨而后卑也？”嫂曰：“以季子之位尊而多金。”苏秦曰：“嗟乎！贫穷则父母不子，富贵则亲戚畏惧。人生世上，势位富厚，盖可忽乎哉？”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苏秦以连横说秦' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四块玉·别情', '关汉卿', '元代', '自送别，心难舍，一点相思几时绝？凭阑袖拂杨花雪。溪又斜，山又遮，人去也！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四块玉·别情' AND p.poem_author = '关汉卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆秦娥·伤离别', '何梦桂', '宋代', '伤离别。江南雁断音书绝。音书绝。两行珠泪，寸肠千结。 \n伤心长记中秋节。今年还似前年月。前年月。那知今夜，月圆人缺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆秦娥·伤离别' AND p.poem_author = '何梦桂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红·汉水东流', '辛弃疾', '宋代', '汉水东流，都洗尽，髭胡膏血。人尽说，君家飞将，旧时英烈。破敌金城雷过耳，谈兵玉帐冰生颊。想王郎，结发赋从戎，传遗业。\n腰间剑，聊弹铗。尊中酒，堪为别。况故人新拥，汉坛旌节。马革裹尸当自誓，蛾眉伐性休重说。但从今，记取楚楼风，庾台月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红·汉水东流' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头·秋色渐将晚', '叶梦得', '宋代', '秋色渐将晚，霜信报黄花。小窗低户深映，微路绕欹斜。为问山翁何事，坐看流年轻度，拚却鬓双华。徙倚望沧海，天净水明霞。 \n念平昔，空飘荡，遍天涯。归来三径重扫，松竹本吾家。却恨悲风时起，冉冉云间新雁，边马怨胡笳。谁似东山老，谈笑静胡沙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头·秋色渐将晚' AND p.poem_author = '叶梦得';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('点绛唇·醉漾轻舟', '秦观', '宋代', '醉漾轻舟，信流引到花深处。尘缘相误，无计花间住。\n烟水茫茫，千里斜阳暮。山无数，乱红如雨。不记来时路。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '点绛唇·醉漾轻舟' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江城子·孤山竹阁送述古', '苏轼', '宋代', '翠蛾羞黛怯人看。掩霜纨，泪偷弹。且尽一尊，收泪唱《阳关》。漫道帝城天样远，天易见，见君难。\n画堂新构近孤山。曲栏干，为谁安？飞絮落花，春色属明年。欲棹小舟寻旧事，无处问，水连天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江城子·孤山竹阁送述古' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('代出自蓟北门行', '鲍照', '南北朝', '羽檄起边亭，烽火入咸阳。\n征师屯广武，分兵救朔方。(征师 一作：征骑)\n严秋筋竿劲，虏阵精且强。\n天子按剑怒，使者遥相望。\n雁行缘石径，鱼贯度飞梁。\n箫鼓流汉思，旌甲被胡霜。\n疾风冲塞起，沙砾自飘扬。\n马毛缩如蝟，角弓不可张。\n时危见臣节，世乱识忠良。\n投躯报明主，身死为国殇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '代出自蓟北门行' AND p.poem_author = '鲍照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长歌行', '李咸用', '唐代', '要衣须破束，欲炙须解牛。当年不快意，徒为他人留。 \n 百岁之约何悠悠，华发星星稀满头。峨眉螓首聊我仇， \n 圆红阙白令人愁。何不夕引清奏，朝登翠楼，逢花便折， \n 闻胜即游？鼓腕腾棍晴雷收，舞腰困褭垂杨柔。 \n 象箸击折歌勿休，玉山未到非风流。眼前有物俱是梦， \n 莫将身作黄金仇。死生同域不用惧，富贵在天何足忧！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长歌行' AND p.poem_author = '李咸用';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('代春怨', '刘方平', '唐代', '朝日残莺伴妾啼，开帘只见草萋萋。 \n庭前时有东风入，杨柳千条尽向西。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '代春怨' AND p.poem_author = '刘方平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长沙过贾谊宅', '刘长卿', '唐代', '三年谪宦此栖迟，万古惟留楚客悲。\n秋草独寻人去后，寒林空见日斜时。\n汉文有道恩犹薄，湘水无情吊岂知。\n寂寂江山摇落处，怜君何事到天涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长沙过贾谊宅' AND p.poem_author = '刘长卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卢令', '佚名', '先秦', '卢令令，其人美且仁。\n卢重环，其人美且鬈。\n卢重鋂，其人美且偲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卢令' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('载驰', '佚名', '先秦', '载驰载驱，归唁卫侯。驱马悠悠，言至于漕。大夫跋涉，我心则忧。\n既不我嘉，不能旋反。视尔不臧，我思不远。\n既不我嘉，不能旋济？视尔不臧，我思不閟。\n陟彼阿丘，言采其蝱。女子善怀，亦各有行。许人尤之，众稚且狂。\n我行其野，芃芃其麦。控于大邦，谁因谁极？大夫君子，无我有尤。百尔所思，不如我所之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '载驰' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乙卯重五诗', '陆游', '宋代', '重五山村好，榴花忽已繁。\n粽包分两髻，艾束著危冠。\n旧俗方储药，羸躯亦点丹。\n日斜吾事毕，一笑向杯盘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乙卯重五诗' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐·风鬟雨鬓', '纳兰性德', '清代', '风鬟雨鬓，偏是来无准。倦倚玉兰看月晕，容易语低香近。\n软风吹遍窗纱，心期便隔天涯。从此伤春伤别，黄昏只对梨花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐·风鬟雨鬓' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜春来·泰定三年丙寅岁除夜玉山舟中赋', '张雨', '元代', '江梅的的依茅舍，石漱溅溅漱玉沙。\n瓦瓯篷底送年华。问暮鸦：何处阿戎家？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜春来·泰定三年丙寅岁除夜玉山舟中赋' AND p.poem_author = '张雨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·座中有眉山隐客史应之和前韵即席答之', '黄庭坚', '宋代', '黄菊枝头生晓寒。人生莫放酒杯干。风前横笛斜吹雨，醉里簪花倒著冠。 \n身健在，且加餐。舞裙歌板尽清欢。黄花白发相牵挽，付与时人冷眼看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·座中有眉山隐客史应之和前韵即席答之' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏柳二首', '顾云', '唐代', '带露含烟处处垂，绽黄摇绿嫩参差。长堤未见风飘絮， \n 广陌初怜日映丝。斜傍画筵偷舞态，低临妆阁学愁眉。 \n 离亭不放到春暮，折尽拂檐千万枝。 \n 闲花野草总争新，眉皱丝干独不匀。 \n 乞取东风残气力，莫教虚度一年春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏柳二首' AND p.poem_author = '顾云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题扬州禅智寺', '杜牧', '唐代', '雨过一蝉噪，飘萧松桂秋。\n青苔满阶砌，白鸟故迟留。\n暮霭生深树，斜阳下小楼。\n谁知竹西路，歌吹是扬州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题扬州禅智寺' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望蓟门', '祖咏', '唐代', '燕台一望客心惊，笳鼓喧喧汉将营。(笳鼓 一作：箫鼓)\n万里寒光生积雪，三边曙色动危旌。\n沙场烽火侵胡月，海畔云山拥蓟城。\n少小虽非投笔吏，论功还欲请长缨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望蓟门' AND p.poem_author = '祖咏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新晴野望', '王维', '唐代', '新晴原野旷，极目无氛垢。\n郭门临渡头，村树连溪口。 \n白水明田外，碧峰出山后。\n农月无闲人，倾家事南亩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新晴野望' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('招魂', '屈原', '先秦', '朕幼清以廉洁兮，身服义而未沫。\n主此盛德兮，牵于俗而芜秽。\n上无所考此盛德兮，长离殃而愁苦。\n帝告巫阳曰：“有人在下，我欲辅之。\n魂魄离散，汝筮予之。”\n巫阳对曰：“掌梦！\n上帝其难从；若必筮予之，\n恐后之谢，不能复用。”\n巫阳焉乃下招曰：\n\n魂兮归来！去君之恒干，\n何为四方些？舍君之乐处，\n而离彼不祥些！\n\n魂兮归来！东方不可以讬些。\n长人千仞，惟魂是索些。\n十日代出，流金铄石些。\n彼皆习之，魂往必释些。\n归来兮！不可以讬些。\n\n魂兮归来！南方不可以止些。\n雕题黑齿，得人肉以祀，以其骨为醢些。\n蝮蛇蓁蓁，封狐千里些。\n雄虺九首，往来倏忽，吞人以益其心些。\n归来兮！不可久淫些。\n\n魂兮归来！西方之害，流沙千里些。\n旋入雷渊，爢散而不可止些。\n幸而得脱，其外旷宇些。\n赤蚁若象，玄蜂若壶些。\n五谷不生，丛菅是食些。\n其土烂人，求水无所得些。\n彷徉无所倚，广大无所极些。\n归来兮！恐自遗贼些。\n\n魂兮归来！北方不可以止些。\n增冰峨峨，飞雪千里些。\n归来兮！不可以久些。\n\n魂兮归来！君无上天些。\n虎豹九关，啄害下人些。\n一夫九首，拔木九千些。\n豺狼从目，往来侁侁些。\n悬人以嬉，投之深渊些。\n致命于帝，然后得瞑些。\n归来！往恐危身些。\n\n魂兮归来！君无下此幽都些。\n土伯九约，其角觺觺些。\n敦脄血拇，逐人伂駓駓些。\n参目虎首，其身若牛些。\n此皆甘人，归来！恐自遗灾些。\n\n魂兮归来！入修门些。\n工祝招君，背行先些。\n秦篝齐缕，郑绵络些。\n招具该备，永啸呼些。\n\n魂兮归来！反故居些。\n天地四方，多贼奸些。\n像设君室，静闲安些。\n高堂邃宇，槛层轩些。\n层台累榭，临高山些。\n网户朱缀，刻方连些。\n冬有穾厦，夏室寒些。\n川谷径复，流潺湲些。\n光风转蕙，氾崇兰些。\n经堂入奥，朱尘筵些。\n砥室翠翘，挂曲琼些。\n翡翠珠被，烂齐光些。\n蒻阿拂壁，罗帱张些。\n纂组绮缟，结琦璜些。\n室中之观，多珍怪些。\n兰膏明烛，华容备些。\n二八侍宿，射递代些。\n九侯淑女，多迅众些。\n盛鬋不同制，实满宫些。\n容态好比，顺弥代些。\n弱颜固植，謇其有意些。\n姱容修态，絚洞房些。\n蛾眉曼睩，目腾光些。\n靡颜腻理，遗视矊些。\n离榭修幕，侍君之闲些。\n悲帷翠帐，饰高堂些。\n红壁沙版，玄玉梁些。\n仰观刻桷，画龙蛇些。\n坐堂伏槛，临曲池些。\n芙蓉始发，杂芰荷些。\n紫茎屏风，文缘波些。\n文异豹饰，侍陂陁些。\n轩辌既低，步骑罗些。\n兰薄户树，琼木篱些。\n魂兮归来！何远为些？\n\n室家遂宗，食多方些。\n稻粢穱麦，挐黄梁些。\n大苦醎酸，辛甘行些。\n肥牛之腱，臑若芳些。\n和酸若苦，陈吴羹些。\n胹鳖炮羔，有柘浆些。\n鹄酸臇凫，煎鸿鸧些。\n露鸡臛蠵，厉而不爽些。\n粔籹蜜饵，有餦餭些。\n瑶浆蜜勺，实羽觞些。\n挫糟冻饮，酎清凉些。\n华酌既陈，有琼浆些。\n归来反故室，敬而无妨些。\n肴羞未通，女乐罗些。\n敶钟按鼓，造新歌些。\n《涉江》《采菱》，发《扬荷》些。\n美人既醉，朱颜酡些。\n嬉光眇视，目曾波些。\n被文服纤，丽而不奇些。\n长发曼鬋，艳陆离些。\n二八齐容，起郑舞些。\n衽若交竿，抚案下些。\n竽瑟狂会，搷鸣鼓些。\n宫庭震惊，发&lt;激楚&gt;些。\n吴歈蔡讴，奏大吕些。\n士女杂坐，乱而不分些。\n放敶组缨，班其相纷些。\n郑卫妖玩，来杂陈些。\n《激楚》之结，独秀先些。\n菎蔽象棋，有六簙些。\n分曹并进，遒相迫些。\n成枭而牟，呼五白些。\n晋制犀比，费白日些。\n铿钟摇簴，揳梓瑟些。\n娱酒不废，沈日夜些。\n兰膏明烛，华灯错些。\n结撰至思，兰芳假些。\n人有所极，同心赋些。\n酎饮尽欢，乐先故些。\n魂兮归来！反故居些。\n\n乱曰：\n献岁发春兮，汨吾南征。\n菉蘋齐叶兮，白芷生。\n路贯庐江兮，左长薄。\n倚沼畦瀛兮，遥望博。\n青骊结驷兮，齐千乘。\n悬火延起兮，玄颜烝。\n步及骤处兮，诱骋先。\n抑骛若通兮，引车右还。\n与王趋梦兮，课后先。\n君王亲发兮，惮青兕。\n朱明承夜兮，时不可以淹。\n皋兰被径兮，斯路渐。\n湛湛江水兮，上有枫。\n目极千里兮，伤春心。\n魂兮归来，哀江南！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '招魂' AND p.poem_author = '屈原';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同学一首别子固', '王安石', '宋代', '江之南有贤人焉，字子固，非今所谓贤人者，予慕而友之。淮之南有贤人焉，字正之，非今所谓贤人者，予慕而友之。二贤人者，足未尝相过也，口未尝相语也，辞币未尝相接也。其师若友，岂尽同哉？予考其言行，其不相似者，何其少也！曰：学圣人而已矣。”学圣人，则其师若友，必学圣人者。圣人之言行，岂有二哉？其相似也适然。\n\n　　予在淮南，为正之道子固，正之不予疑也。还江南，为子固道正之，子固亦以为然。予又知所谓贤人者，既相似，又相信不疑也。\n\n　　子固作《怀友》一首遗予，其大略欲相扳以至乎中庸而后已。正之盖亦常云尔。夫安驱徐行，轥中庸之庭，而造于其堂，舍二贤人者而谁哉？予昔非敢自必其有至也，亦愿从事于左右焉尔。辅而进之，其可也。\n\n　　噫！官有守，私有系，会合不可以常也，作《同学一首别子固》以相警，且相慰云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同学一首别子固' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浪淘沙·帘外五更风', '李清照', '宋代', '帘外五更风，吹梦无踪。画楼重上与谁同？记得玉钗斜拨火，宝篆成空。\n回首紫金峰，雨润烟浓。一江春浪醉醒中。留得罗襟前日泪，弹与征鸿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浪淘沙·帘外五更风' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东溪', '梅尧臣', '宋代', '行到东溪看水时，坐临孤屿发船迟。\n野凫眠岸有闲意，老树着花无丑枝。\n短短蒲茸齐似剪，平平沙石净于筛。\n情虽不厌住不得，薄暮归来车马疲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东溪' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐·候蛩凄断', '张炎', '宋代', '候蛩凄断，人语西风岸。月落沙平江似练，望尽芦花无雁。\n暗教愁损兰成，可怜夜夜关情。只有一枝梧叶，不知多少秋声！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐·候蛩凄断' AND p.poem_author = '张炎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·一点残红欲尽时', '周紫芝', '宋代', '一点残红欲尽时。乍凉秋气满屏帏。梧桐叶上三更雨，叶叶声声是别离。 \n调宝瑟，拨金猊。那时同唱鹧鸪词。如今风雨西楼夜，不听清歌也泪垂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·一点残红欲尽时' AND p.poem_author = '周紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戚氏·晚秋天', '柳永', '宋代', '晚秋天，一霎微雨洒庭轩。槛菊萧疏，井梧零乱，惹残烟。凄然，望江关，飞云黯淡夕阳间。当时宋玉悲感，向此临水与登山。远道迢递，行人凄楚，倦听陇水潺湲。正蝉吟败叶，蛩响衰草，相应喧喧。\n\n　　孤馆，度日如年。风露渐变，悄悄至更阑。长天净，绛河清浅，皓月婵娟。思绵绵。夜永对景，那堪屈指暗想从前。未名未禄，绮陌红楼，往往经岁迁延。\n\n　　帝里风光好，当年少日，暮宴朝欢。况有狂朋怪侣，遇当歌对酒竞留连。别来迅景如梭，旧游似梦，烟水程何限。念名利，憔悴长萦绊。追往事、空惨愁颜。漏箭移，稍觉轻寒。渐呜咽，画角数声残。对闲窗畔，停灯向晓，抱影无眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戚氏·晚秋天' AND p.poem_author = '柳永';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('善哉行·其一', '曹丕', '魏晋', '上山采薇，薄暮苦饥。\n溪谷多风，霜露沾衣。\n野雉群雊，猿猴相追。\n还望故乡，郁何垒垒！\n高山有崖，林木有枝。\n忧来无方，人莫之知。\n人生如寄，多忧何为？\n今我不乐，岁月如驰。\n汤汤川流，中有行舟。\n随波转薄，有似客游。\n策我良马，被我轻裘。\n载驰载驱，聊以忘忧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '善哉行·其一' AND p.poem_author = '曹丕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('明月皎夜光', '佚名', '两汉', '明月皎夜光，促织鸣东壁。\n玉衡指孟冬，众星何历历。\n白露沾野草，时节忽复易。\n秋蝉鸣树间，玄鸟逝安适。\n昔我同门友，高举振六翮。\n不念携手好，弃我如遗迹。\n南箕北有斗，牵牛不负轭。\n良无盘石固，虚名复何益？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '明月皎夜光' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春望词四首', '薛涛', '唐代', '花开不同赏，花落不同悲。欲问相思处，花开花落时。 \n 揽草结同心，将以遗知音。春愁正断绝，春鸟复哀吟。 \n 风花日将老，佳期犹渺渺。不结同心人，空结同心草。 \n 那堪花满枝，翻作两相思。玉箸垂朝镜，春风知不知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春望词四首' AND p.poem_author = '薛涛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题红叶', '宣宗宫人', '唐代', '流水何太急，深宫尽日闲。\n殷勤谢红叶，好去到人间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题红叶' AND p.poem_author = '宣宗宫人';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋', '刘得仁', '唐代', '尘里兼尘外，咸期此夕明。\n一年惟一度，长恐有云生。\n露洗微埃尽，光濡是物清。\n朗吟看正好，惆怅又西倾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋' AND p.poem_author = '刘得仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('瀑布', '施肩吾', '唐代', '豁开青冥颠，泻出万丈泉。\n如裁一条素，白日悬秋天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瀑布' AND p.poem_author = '施肩吾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬乐天频梦微之', '元稹', '唐代', '山水万重书断绝，念君怜我梦相闻。\n我今因病魂颠倒，唯梦闲人不梦君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬乐天频梦微之' AND p.poem_author = '元稹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山石', '韩愈', '唐代', '山石荦确行径微，黄昏到寺蝙蝠飞。\n升堂坐阶新雨足，芭蕉叶大栀子肥。\n僧言古壁佛画好，以火来照所见稀。\n铺床拂席置羹饭，疏粝亦足饱我饥。\n夜深静卧百虫绝，清月出岭光入扉。\n天明独去无道路，出入高下穷烟霏。\n山红涧碧纷烂漫，时见松枥皆十围。\n当流赤足踏涧石，水声激激风吹衣。\n人生如此自可乐，岂必局束为人鞿？(鞿 一作：靰)\n嗟哉吾党二三子，安得至老不更归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山石' AND p.poem_author = '韩愈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('前出塞九首', '杜甫', '唐代', '戚戚去故里，悠悠赴交河。\n公家有程期，亡命婴祸罗。\n君已富土境，开边一何多。\n弃绝父母恩，吞声行负戈。\n\n出门日已远，不受徒旅欺。\n骨肉恩岂断，男儿死无时。\n走马脱辔头，手中挑青丝。\n捷下万仞冈，俯身试搴旗。\n\n磨刀呜咽水，水赤刃伤手。\n欲轻肠断声，心绪乱已久。\n丈夫誓许国，愤惋复何有！\n功名图麒麟，战骨当速朽。\n\n送徒既有长，远戍亦有身。\n生死向前去，不劳吏怒嗔。\n路逢相识人，附书与六亲。\n哀哉两决绝，不复同苦辛。\n\n迢迢万里余，领我赴三军。\n军中异苦乐，主将宁尽闻。\n隔河见胡骑，倏忽数百群。\n我始为奴仆，几时树功勋。\n\n挽弓当挽强，用箭当用长。\n射人先射马，擒贼先擒王。\n杀人亦有限，列国自有疆。\n苟能制侵陵，岂在多杀伤。\n\n驱马天雨雪，军行入高山。\n径危抱寒石，指落层冰间。\n已去汉月远，何时筑城还。\n浮云暮南征，可望不可攀。\n\n单于寇我垒，百里风尘昏。\n雄剑四五动，彼军为我奔。\n掳其名王归，系颈授辕门。\n潜身备行列，一胜何足论。\n\n从军十年余，能无分寸功。\n众人贵苟得，欲语羞雷同。\n中原有斗争，况在狄与戎。\n丈夫四方志，安可辞固穷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '前出塞九首' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自洛之越', '孟浩然', '唐代', '遑遑三十载，书剑两无成。\n山水寻吴越，风尘厌洛京。\n扁舟泛湖海，长揖谢公卿。\n且乐杯中物，谁论世上名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自洛之越' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江亭夜月送别二首', '王勃', '唐代', '江送巴南水，山横塞北云。\n津亭秋月夜，谁见泣离群？\n\n乱烟笼碧砌，飞月向南端。\n寂寞离亭掩，江山此夜寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江亭夜月送别二首' AND p.poem_author = '王勃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大车', '佚名', '先秦', '大车槛槛，毳衣如菼。岂不尔思？畏子不敢。\n大车啍啍，毳衣如璊。岂不尔思？畏子不奔。\n榖则异室，死则同穴。谓予不信，有如皎日。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大车' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹竿', '佚名', '先秦', '籊籊竹竿，以钓于淇。岂不尔思？远莫致之。\n泉源在左，淇水在右。女子有行，远兄弟父母。\n淇水在右，泉源在左。巧笑之瑳，佩玉之傩。\n淇水滺滺，桧楫松舟。驾言出游，以写我忧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹竿' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('子虚赋', '司马相如', '两汉', '楚使子虚使于齐，王悉发车骑，与使者出田。田罢，子虚过奼乌有先生，亡是公在焉。坐定，乌有先生问曰：“今日田乐乎？”子虚曰：“乐。”“获多乎？”曰：“少。”“然则何乐？”对曰：“仆乐齐王之欲夸仆以车骑之众，而仆对以云梦之事也。”曰：“可得闻乎？”\n\n　　子虚曰：“可。王车驾千乘，选徒万骑，田于海滨。列卒满泽，罘罔弥山，掩兔辚鹿，射麇脚麟。骛于盐浦，割鲜染轮。射中获多，矜而自功。顾谓仆曰：‘楚亦有平原广泽游猎之地饶乐若此者乎？楚王之猎孰与寡人乎？’仆下车对曰：‘臣，楚国之鄙人也，幸得宿卫十有余年，时从出游，游于后园，览于有无，然犹未能遍睹也，又焉足以言其外泽者乎！’齐王曰：‘虽然，略以子之所闻见而言之。’\n\n　　“仆对曰：‘唯唯。臣闻楚有七泽，尝见其一，未睹其余也。臣之所见，盖特其小小耳者，名曰云梦。云梦者，方九百里，其中有山焉。其山则盘纡茀郁，隆崇嵂崒；岑崟参差，日月蔽亏；交错纠纷，上干青云；罢池陂陀，下属江河。其土则丹青赭垩，雌黄白坿，锡碧金银，众色炫耀，照烂龙鳞。其石则赤玉玫瑰，琳瑉琨吾，瑊玏玄厉，碝石碔玞。其东则有蕙圃：衡兰芷若，芎藭昌蒲，茳蓠麋芜，诸柘巴苴。其南则有平原广泽，登降陁靡，案衍坛曼。缘以大江，限以巫山。其高燥则生葴菥苞荔，薛莎青薠。其卑湿则生藏莨蒹葭，东蔷雕胡，莲藕觚卢、菴闾轩于，众物居之，不可胜图。其西则有涌泉清池，激水推移，外发芙蓉菱华，内隐钜石白沙。其中则有神龟蛟鼍，瑇瑁鳖鼋。其北则有阴林：其树楩柟豫章，桂椒木兰，蘖离朱杨，樝梨梬栗，橘柚芬芳；其上则有鹓雏孔鸾，腾远射干；其下则有白虎玄豹，蟃蜒貙犴。\n\n　　‘于是乃使剸诸之伦，手格此兽。楚王乃驾驯驳之驷，乘雕玉之舆。靡鱼须之桡旃，曳明月之珠旗。建干将之雄戟，左乌号之雕弓，右夏服之劲箭。阳子骖乘，纤阿为御，案节未舒，即陵狡兽。蹴蛩蛩，辚距虚，轶野马，轊陶駼，乘遗风，射游骐。倏眒倩浰，雷动猋至，星流霆击。弓不虚发，中必决眦，洞胸达腋，绝乎心系。获若雨兽，揜草蔽地。于是楚王乃弭节俳徊，翱翔容与。览乎阴林，观壮士之暴怒，与猛兽之恐惧。徼郄受诎，殚睹众物之变态。\n\n　　‘于是郑女曼姬，被阿緆，揄紵缟，杂纤罗，垂雾縠。襞积褰绉，郁桡溪谷。衯衯裶裶，扬袘戌削，蜚纤垂髾。扶与猗靡，噏呷萃蔡。下摩兰蕙，上拂羽盖。错翡翠之威蕤，缪绕玉绥。眇眇忽忽，若神仙之仿佛。\n\n　　‘于是乃相与獠于蕙圃，媻珊郣窣，上乎金堤。揜翡翠，射鵕鸃。微矰出，孅缴施。弋白鹄，连鴐鹅。双鸧下，玄鹤加。怠而后发，游于清池。浮文鹢，扬旌栧。张翠帷，建羽盖。罔瑇瑁，钩紫贝。摐金鼓，吹鸣籁。榜人歌，声流喝。水虫骇，波鸿沸。涌泉起，奔扬会。礧石相击，硠硠礚礚，若雷霆之声，闻乎数百里之外。将息獠者，击灵鼓，起烽燧。车按行，骑就队。纚乎淫淫，般乎裔裔。\n\n　　‘于是楚王乃登云阳之台，怕乎无为，澹乎自持，勺药之和，具而后御之。不若大王终日驰骋，曾不下舆，脟割轮焠，自以为娱。臣窃观之，齐殆不如。’于是齐王默然无以应仆也。”\n\n　　乌有先生曰：“是何言之过也！足下不远千里，来贶齐国，王悉发境内之士，而备车骑之众，与使者出畋，乃欲勠力致获，以娱左右，何名为夸哉！问楚地之有无者，愿闻大国之风烈，先生之余论也。今足下不称楚王之德厚，而盛推云梦以为高，奢言淫乐而显侈靡，窃为足下不取也。必若所言，固非楚国之美也。无而言之，是害足下之信也。章君恶、伤私义，二者无一可，而先生行之，必且轻于齐而累于楚矣。且齐东陼钜海，南有琅邪；观乎成山，射乎之罘；浮勃澥，游孟诸；邪与肃慎为邻，右以汤谷为界。秋田乎青丘，彷徨乎海外。吞若云梦者八九于其胸中曾不蒂芥。若乃俶傥瑰伟，异方殊类，珍怪鸟兽，万端鳞崪充牣其中，不可胜记。禹不能名，卨不能计。然在诸侯之位，不敢言游戏之乐，苑囿之大；先生又见客，是以王辞不复，何为无以应哉！”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '子虚赋' AND p.poem_author = '司马相如';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塞上听吹笛', '高适', '唐代', '雪净胡天牧马还，月明羌笛戍楼间。\n借问梅花何处落，风吹一夜满关山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塞上听吹笛' AND p.poem_author = '高适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('介之推不言禄', '左丘明', '先秦', '晋侯赏从亡者，介之推不言禄，禄亦弗及。\n\n　　推曰：“献公之子九人，唯君在矣。惠、怀无亲，外内弃之。天未绝晋，必将有主。主晋祀者，非君而谁？天实置之，而二三子以为己力，不亦诬乎？窃人之财，犹谓之盗。况贪天之功，以为己力乎？下义其罪，上赏其奸。上下相蒙，难与处矣。”\n\n　　其母曰：“盍亦求之？以死谁怼？”\n\n　　对曰：“尤而效之，罪又甚焉！且出怨言，不食其食。”\n\n　　其母曰：“亦使知之，若何？”\n\n　　对曰：“言，身之文也。身将隐，焉用文之？是求显也。”\n\n　　其母曰：“能如是乎？与汝偕隐。”遂隐而死。\n\n　　晋侯求之，不获，以绵上（地名）为之田。曰：“以志吾过，且旌善人。”', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '介之推不言禄' AND p.poem_author = '左丘明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('调笑令·胡马', '韦应物', '唐代', '胡马，胡马，远放燕支山下。跑沙跑雪独嘶，东望西望路迷。迷路，迷路，边草无穷日暮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '调笑令·胡马' AND p.poem_author = '韦应物';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜泊水村', '陆游', '宋代', '腰间羽箭久凋零，太息燕然未勒铭。\n老子犹堪绝大漠，诸君何至泣新亭。\n一身报国有万死，双鬓向人无再青。\n记取江湖泊船处，卧闻新雁落寒汀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜泊水村' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南乡子·为亡妇题照', '纳兰性德', '清代', '泪咽却无声，只向从前悔薄情。凭仗丹青重省识，盈盈，一片伤心画不成。\n别语忒分明，午夜鹣鹣梦早醒。卿自早醒侬自梦，更更，泣尽风檐夜雨铃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南乡子·为亡妇题照' AND p.poem_author = '纳兰性德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绝句·人生无百岁', '刘基', '明代', '人生无百岁，百岁复如何？\n古来英雄士，各已归山河。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绝句·人生无百岁' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春·灵山斋庵赋时筑偃湖未成', '辛弃疾', '宋代', '叠嶂西驰，万马回旋，众山欲东。正惊湍直下，跳珠倒溅；小桥横截，缺月初弓。老合投闲，天教多事，检校长身十万松。吾庐小，在龙蛇影外，风雨声中。\n争先见面重重，看爽气朝来三数峰。似谢家子弟，衣冠磊落；相如庭户，车骑雍容。我觉其间，雄深雅健，如对文章太史公。新堤路，问偃湖何日，烟水蒙蒙？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春·灵山斋庵赋时筑偃湖未成' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·探梅', '辛弃疾', '宋代', '老去惜花心已懒，爱梅犹绕江村。一枝先破玉溪春。更无花态度，全有雪精神。 \n剩向空山餐秀色，为渠著句清新。竹根流水带溪云。醉中浑不记，归路月黄昏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·探梅' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月·问讯湖边春色', '张孝祥', '宋代', '问讯湖边春色，重来又是三年。东风吹我过湖船，杨柳丝丝拂面。\n世路如今已惯，此心到处悠然。寒光亭下水如天，飞起沙鸥一片。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月·问讯湖边春色' AND p.poem_author = '张孝祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('减字木兰花·天涯旧恨', '秦观', '宋代', '天涯旧恨，独自凄凉人不问。欲见回肠，断尽金炉小篆香。\n黛蛾长敛，任是春风吹不展。困倚危楼，过尽飞鸿字字愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '减字木兰花·天涯旧恨' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人·寄公度', '舒亶', '宋代', '芙蓉落尽天涵水，日暮沧波起。背飞双燕贴云寒，独向小楼东畔、倚阑看。 \n浮生只合尊前老，雪满长安道。故人早晚上高台，赠我江南春色、一枝梅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人·寄公度' AND p.poem_author = '舒亶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·画阁归来春又晚', '欧阳修', '宋代', '画阁归来春又晚。燕子双飞，柳软桃花浅。细雨满天风满院，愁眉敛尽无人见。\n独倚阑干心绪乱。芳草芊绵，尚忆江南岸。风月无情人暗换，旧游如梦空肠断。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·画阁归来春又晚' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南陵道中 / 寄远', '杜牧', '唐代', '南陵水面漫悠悠，风紧云轻欲变秋。\n正是客心孤迥处，谁家红袖凭江楼？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南陵道中 / 寄远' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('短歌行', '白居易', '唐代', '曈曈太阳如火色，上行千里下一刻。\n出为白昼入为夜，圆转如珠住不得。\n住不得，可奈何，为君举酒歌短歌。 \n歌声苦，词亦苦，四座少年君听取。\n今夕未竟明夕催，秋风才往春风回。\n人无根蒂时不驻，朱颜白日相隳颓。 \n劝君且强笑一面，劝君且强饮一杯。\n人生不得长欢乐，年少须臾老到来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '短歌行' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('移家别湖上亭', '戎昱', '唐代', '好是春风湖上亭，柳条藤蔓系离情。\n黄莺久住浑相识，欲别频啼四五声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '移家别湖上亭' AND p.poem_author = '戎昱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠从兄襄阳少府皓', '李白', '唐代', '结发未识事，所交尽豪雄。\n却秦不受赏，击晋宁为功。\n托身白刃里，杀人红尘中。\n当朝揖高义，举世称英雄。\n小节岂足言，退耕舂陵东。\n归来无产业，生事如转蓬。\n一朝乌裘敝，百镒黄金空。\n弹剑徒激昂，出门悲路穷。\n吾兄青云士，然诺闻诸公。\n所以陈片言，片言贵情通。\n棣华倘不接，甘与秋草同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠从兄襄阳少府皓' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渡湘江', '杜审言', '唐代', '迟日园林悲昔游，今春花鸟作边愁。\n独怜京国人南窜，不似湘江水北流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渡湘江' AND p.poem_author = '杜审言';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金刚随机无尽颂·法界通花分第十九', '释印肃', '宋代', '福德元无实，本光常湛寂。\n圆明法界内，杳廓无穷极。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金刚随机无尽颂·法界通花分第十九' AND p.poem_author = '释印肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠楚公', '唐求', '唐代', '曾闻半偈雪山中，贝叶翻时理尽通。般若恒添持戒力， \n 落叉谁算念经功。云间晓月应难染，海上虚舟自信风。 \n 长说满庭花色好，一枝红是一枝空。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠楚公' AND p.poem_author = '唐求';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('疏斋晚步', '叶颙', '元代', '荷老难擎露，水清偏见鱼。好磨青玉觜，一饱更何如。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '疏斋晚步' AND p.poem_author = '叶颙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('呈审知并简伯元', '赵蕃', '宋代', '溪流渴雨今几日，夜夜月明翻我室。江西回首安在哉，南北故怜无定食。\n\n君居未尽乔木西，旧识邻墙解作诗。如闻过语必更仆，饭寒麈秃忘其饥。\n\n我思从之不可得，书疏空云间何阔。秋风吹我逐转蓬，何自翩然堕君侧。\n\n君诗比昔更大好，谁谓文章技非道。暗中摸索未易窥，众里卒逢分眊瞭。\n\n我昔少小嗜读书，老类贾胡空识珠。潜珍怀宝衣蓝缕，见之每辄惊成呿。\n\n郑君况是余所长，君得结交真迈往。如我何取亦与游，听呼殷兄唤张丈。\n\n两君抱才终有为，丰年未厌甘雨迟。我无良田莳嘉谷，取譬但可同蹲鸱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '呈审知并简伯元' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('消夏四章 其三 有饮', '卢青山', '当代', '身名俱未老，结屋在山隅。一酌泥家酒，五车竹简书。\n\n避人遂如此，得月相友于。乃问行游子，何如掉臂娱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '消夏四章 其三 有饮' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阴平车中大风', '姚燮', '清代', '急水下沙堑，斜月明戍楼。东星灿房氐，西岭森栝楸。\n\n冥焉寡佳眄，郁尔生古愁。龙气倏以变，虎迹行相侔。\n\n大海互唇齿，其背黄河流。并声合一鬨，激籁同九秋。\n\n摩天极悍厉，蹑地无停留。去烟千里平，夕色苍浮浮。\n\n高雁响潜远，隐隐下徐州。野火散燐碧，若在龟山陬。\n\n我马自驰突，去去知安投？夙闻齐东民，斥土鲜穰收。\n\n但冀夏牟熟，或补秋荒忧。非期相荡潏，农癈民何筹？\n\n委以告籴计，谓可移粟谋。斯时万瓦屋，老稚啼嘤嚘。\n\n繄予行迈人，怅望心徒悠。凭轼赋此诗，守土谁贤侯？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阴平车中大风' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵萧同年古意', '方岳', '宋代', '猗猗者芳兰，翳翳彼幽麓。\n不烦汉阴人，抱瓮相灌沐。\n春风自桃李，急管乱繁曲。\n纷纷众醉间，美此一醒独。\n造化本何心，亦因材以笃。\n所以古之人，身外无不足。\n客有古琴瑟，得之自龙门。\n於今几何代，庚庚裂奇纹。\n携持过齐王，自意当骇观。\n何如适献笑，弃置笙竽间。\n时世我不遭，归其老丘园。\n锺期今安之，谁与俗士论。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵萧同年古意' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('社西村（四首）', '陈宪章', '明代', '结茅依里社，村以社西名。\n客至惟谈稼，年衰不入城。\n邻鸡上树宿，水鹤傍人鸣。\n向晚寻牛去，前冈笛又轰。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '社西村（四首）' AND p.poem_author = '陈宪章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '刘正夫', '宋代', '紫宸朝罢衮衣闲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '刘正夫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠俞虚江参将三首', '唐顺之', '明代', '将军意气敻无伦，感激宁辞血战频。\n手搏鬼夷尝百种，身悬鲸海历三春。\n扫空巢穴多深夜，夺得艅艎数人。\n此日渠魁当授首，策勋早见上麒麟。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠俞虚江参将三首' AND p.poem_author = '唐顺之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆黄观复', '苏泂', '宋代', '地远过从少，天多眼界宽。\n晓书繙卷白，秋桂绕亭丹。\n小雨妨相觅，幽花孰与看。\n平生杜陵老，到此赋诗难。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆黄观复' AND p.poem_author = '苏泂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居杂体药名', '王夫之', '明代', '白日及闲年，寻常山色妍。古松香满径，修竹叶参天。\n\n紫菀朝霞雨，黄连夕照烟。柴桑寄生理，不受督邮怜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居杂体药名' AND p.poem_author = '王夫之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寒亭', '范成大', '宋代', '沟塍与涧合，陇亩抱山转。\n向来六月旱，此地免焦卷。\n早穗已垂垂，晚苗犹剪剪。\n一川丰年意，比屋闹鸡犬。\n老农霜须鬓，矍铄黄犊健。\n自云足踏地，常赋何能免。\n刈熟倩人输，不识长官面。\n康年无复事，但恐社酒浅。\n我亦有二顷，收拾尚可茧。\n怀哉笠泽路，归铲犁头藓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寒亭' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉和宫使内翰佳什', '郭仲荀', '宋代', '老来乞得奉祠宫，退食何妨不自公。\n任使世情分冷暖，无劳品秩论穹崇。\n功名至此休看镜，战伐于今喜挂弓。\n梨枣具陈呼稚子，笙歌閒作乐衰翁。\n芳菲莫负三春赏，聚散难逢一笑同。\n小圃栽培粗伦理，频须把酒殢东风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉和宫使内翰佳什' AND p.poem_author = '郭仲荀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题马文璧秋山图为卢仲章赋', '鲁渊', '明代', '野馆空山里，林泉象外幽。\n淡云初霁雨，红叶早惊秋。\n路转山藏屋，桥危岸倚舟。\n直疑人境异，便欲问丹丘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题马文璧秋山图为卢仲章赋' AND p.poem_author = '鲁渊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阑干万里心', '易顺鼎', '清代', '吹箫载酒少年游。曾倚江南苏小楼。憔悴天涯不自由。\n\n怕凝眸。送尽征鸿字字愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阑干万里心' AND p.poem_author = '易顺鼎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('灵岩感怀', '卢刚', '宋代', '摩挲石刻拜方兴，误国从初恨老秦。\n十六州归仍遗虏，百馀年事语谁人。\n出师表在今如始，堕泪碑存旧似新。\n江水江花岂终极，风光一任转青春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '灵岩感怀' AND p.poem_author = '卢刚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送程给事知越州', '石麟之', '宋代', '鹿轓龙节上恩华，衣绣先归士论嘉。\n琐闼暂虚元老席，蓬莱还属侍臣家。\n旌旗天上浮文鹢，鼓角江头拥将牙。\n东越又新南越治，到时歌咏已喧哗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送程给事知越州' AND p.poem_author = '石麟之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登五华寺戒上人楼', '童轩', '明代', '乘闲时倚远公楼，一段风烟豁醉眸。山色遥连梁岳晚，潮声初涌海门秋。\n\n酒旗城郭西风急，禾黍人家夕照收。莫怪吟馀重回首，五云东北是神州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登五华寺戒上人楼' AND p.poem_author = '童轩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('将近许市望见虎丘', '杨万里', '宋代', '许市人家远树前，虎丘山色夕阳边。\n石桥分水入别港，茅屋垂杨仍钓船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将近许市望见虎丘' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和李巽伯春怀', '刘子翚', '宋代', '山寒古寺清，断续春朝雨。\n遥怜远客情，寂寞谁晤语。\n平生气轩昂，失意今易与。\n有酒即佳晨，无兵皆乐土。\n微吟对节物，林静幽花吐，\n悠悠念乡邑，耿耿悲豺虎。\n知有济时才，从横在谈尘。\n功名恐未迟，老翮期更举。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和李巽伯春怀' AND p.poem_author = '刘子翚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九日江桥揽胜', '聂绀弩', '近代', '双江桥上遇重阳，蓝涧玉峰忆草堂。水冷鱼龙艰出没，风回云日乱低昂。\n\n横流顾影千寻远，敧帽酹波万里长。插菊满头吾老矣，南来乌鹊怯严霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九日江桥揽胜' AND p.poem_author = '聂绀弩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和主司王起（一作和主司酬周侍郎）', '孟守', '唐代', '科文又主守初时，光显门生济会期。美擅东堂登甲乙， \n 荣同内署侍恩私。群莺共喜新迁木，双凤皆当即入池。 \n 别有倍深知感士，曾经两度得芳枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和主司王起（一作和主司酬周侍郎）' AND p.poem_author = '孟守';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病', '王宠', '明代', '长卿复何望，祗守茂陵田。玉历梅花外，春心药裹边。\n\n声华浑似梦，水月欲窥禅。鼎鼎百年内，千金诚可怜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病' AND p.poem_author = '王宠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和许仲涂郎中游山', '钱公辅', '宋代', '每同南郭先生到，今伴东牟太守来。\n自顾拙疏聊自乐，白云径里踏荒苔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和许仲涂郎中游山' AND p.poem_author = '钱公辅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闲居对雨诗', '阴铿', '南北朝', '蘋藻降灵祗，聪明谅在斯。触石朝云起，从星夜月离。\n\n八川奔巨壑，万顷溢澄陂。绿野含膏润，青山带濯枝。\n\n嘉禾方合颖，秀麦已分歧。寄语纷纶学，持笔讵必知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闲居对雨诗' AND p.poem_author = '阴铿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬武蕴之，乙丑之岁始见华发余自悲遂成继和', '张祜', '唐代', '贾生年尚少，华发近相侵。不是流光促，因缘别恨深。 \n 怜君成苦调，感我独长吟。岂料清秋日，星星共映簪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬武蕴之，乙丑之岁始见华发余自悲遂成继和' AND p.poem_author = '张祜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('彩震碧浪居留题', '李之世', '明代', '耽幽此结斋，一径草深霾。树阴疑压阁，日影不移阶。\n\n竹密成行次，篱蔓没安排。坐来清露重，花气逗人怀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '彩震碧浪居留题' AND p.poem_author = '李之世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闲中富贵', '陆游', '宋代', '天为疏慵剩与闲，一庵青嶂白云间。\n衲僧过别归庐阜，羽客来寻说华山。\n冬笋生林龙（左角右戢），寒泉落涧佩珊珊。\n俗人自是无因到，虽设柴门不上关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闲中富贵' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠浩子二首 其二', '聂绀弩', '近代', '昔人访戴曾千里，今我家居戴自来。南口风沙苹果树，北京鱼肉牡丹牌。\n\n棉衣棉裤三天跑，小女小儿一见才。最后晚餐须烂醉，明朝赤膊石头抬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠浩子二首 其二' AND p.poem_author = '聂绀弩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏题指纹斗牛图', '谢举廉', '宋代', '左者前其角，右者后其足，\n浼君双指螺，战此两觳觫。\n草长水远日悠悠，不向桑间自在休。\n蜗头尚可屠蛮触，壁上从今斗二牛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏题指纹斗牛图' AND p.poem_author = '谢举廉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧', '喻蘅', '近代', '深夜昏茫惑曙鸡。背人清泪亦孤凄。南州丝管迷狐步，北国沙虫倦马蹄。\n\n夕照外，暮云低。迢迢春在短长堤。桃花稍解迎人意，那更无言自有蹊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧' AND p.poem_author = '喻蘅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('好事近·洪武本高青邱姑苏杂咏，为傅沅叔题', '吴昌绶', '清代', '少小住吴中，故事依稀能说。回想泰娘桥畔，负莺晨蟾夕。\n\n亲栽弱柳早飞棉，丝鬓更谁惜。未到绿阴吟望，又沧桑一瞥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '好事近·洪武本高青邱姑苏杂咏，为傅沅叔题' AND p.poem_author = '吴昌绶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杨柳枝 其二十四', '周岸登', '清代', '麝作流尘犀作株。莺邻燕户亦蘧庐。舆儓国嫒皆颜色，谁见当年卫子夫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杨柳枝 其二十四' AND p.poem_author = '周岸登';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归宗山籁一百四首 其八十', '释函是', '明代', '空谷归人少，高峰落日寒。望云惭老大，深夜绕栏杆。\n\n万事省心力，六时惟内观。浮生岂容易，休作少年看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归宗山籁一百四首 其八十' AND p.poem_author = '释函是';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('滇中词三首 其一', '范汭', '明代', '秀海海边葭菼秋，滇池池上云悠悠。人心恰似此中水，一道南流一北流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '滇中词三首 其一' AND p.poem_author = '范汭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('朝登北山头二首 其二', '郭祥正', '宋代', '朝登北山头，悠悠望江水。水流无还期，人老行已矣。\n\n劝君把一樽，聊用置悲喜。生无死何有，原终乃知始。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '朝登北山头二首 其二' AND p.poem_author = '郭祥正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('显上人送茶题扇荅之', '邵宝', '明代', '祛暑方静坐，茶来清我心。铜槃小泉石，绿树一堂深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '显上人送茶题扇荅之' AND p.poem_author = '邵宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪晴同吕舍人顾汝所南郊閒步', '文彭', '明代', '京华春色好，最是雪晴时。树冻初含润，沟冰欲动澌。\n\n风生尘冉冉，日下景迟迟。携手南郊去，仙家剩酒卮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪晴同吕舍人顾汝所南郊閒步' AND p.poem_author = '文彭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('海气', '陆游', '宋代', '浴罢来水浒，适有渔舟横。\n浩然纵棹去，漫漫菰蒲声。\n海祲乃尔奇，万象空际生；骖驔牧龙马，夭矫腾蛟鲸，或如搴大旗，或如执长兵。\n我欲记其变，忽已天宇清。\n成坏须臾间，使我叹且惊。\n世事正如此，何者非强名？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '海气' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('富春', '吴融', '唐代', '天下有水亦有山，富春山水非人寰。 \n 长川不是春来绿，千峰倒影落其间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '富春' AND p.poem_author = '吴融';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同闻上人作', '程嘉燧', '明代', '旬月拟来此，同游亦偶然。\n经行适多暇，喧寂自俱禅。\n出寺半峰雨，归房终夜泉。\n独惭心住著，仍是爱幽偏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同闻上人作' AND p.poem_author = '程嘉燧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史二十二首 其四 商汤', '赵戣', '宋代', '罪己桑林六，仁心祝网三。只应宽代虐，何事德怀惭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史二十二首 其四 商汤' AND p.poem_author = '赵戣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('逍遥堂会宿二首 其二', '苏辙', '宋代', '秋来东阁凉如水，客去山公醉似泥。困卧北窗呼不起，风吹松竹雨凄凄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '逍遥堂会宿二首 其二' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('徐州道中', '文天祥', '宋代', '彭城古官道，日中十马驰。\n咫尺不见人，扑面黄尘飞。\n白头汉王缟素师，美人燕罢项羽啼。\n一时混战四十万，天昏地黑睢水湄。\n乃知大风扬沙失白昼，自是地利非天时。\n汉王仓皇问道西，一儿一女嘻其危。\n太公吕后去不归，俎上宁有生还时。\n未央称寿太上皇，巍然女娲帝中闱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '徐州道中' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题宋怀豫饮光台', '孙奇逢', '明代', '台敞元无暑，翛然万虑捐。月沾衣带冷，花促酒杯乾。\n\n意气悲歌里，风云指顾前。夜深迷去径，独为主人贤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题宋怀豫饮光台' AND p.poem_author = '孙奇逢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无题和徐茂吴司理 其四', '徐熥', '明代', '劈开金锁出重门，学得文君半夜奔。但爱风流人似玉，不知年少是梨园。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无题和徐茂吴司理 其四' AND p.poem_author = '徐熥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('柳烟二首 其二', '徐庭翼', '清代', '只为春来阴雨绵，烹茶常怕湿柴煎。晴窗忽见溪边柳，犹讶邻炊起暮烟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '柳烟二首 其二' AND p.poem_author = '徐庭翼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题茶禅一品', '张伯元', '当代', '太姥产白茶，采制多辛苦。慕茗劳主人，瀹起山中雾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题茶禅一品' AND p.poem_author = '张伯元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵田将仕年八十八岁作诗自喜三首 其二', '项安世', '宋代', '铜驼陌上少年时，走马驱车远四畿。又见伏符明汉道，曾伤小雅咏周微。\n\n一生世路高和下，何恨人情瘠与肥。老矣胸怀百无著，自梳朝夕鬓毛稀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵田将仕年八十八岁作诗自喜三首 其二' AND p.poem_author = '项安世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪纱 其十 题余氏女子绣浣纱图', '王士禛', '清代', '何处青山是若耶。苧萝村畔认西家。满溪花瓣浣春纱。\n\n未入吴宫犹淡漠，一辞乌喙便夭斜。针神十五鬓堆鸦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪纱 其十 题余氏女子绣浣纱图' AND p.poem_author = '王士禛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病起窥园十绝 其六', '刘克庄', '宋代', '久匣菱花懒一窥，都忘挟弹洛阳时。若非病起临池水，白尽须眉不自知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病起窥园十绝 其六' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花 客中感春', '徐釚', '清代', '侬似浮萍漂泊里。不道留侬，到便侬留住。柳絮随风花落处。\n\n为侬又惹閒情绪。\n\n红泪抛残无一语。滚滚难描，最是伤春句。试问荼蘼开似许。\n\n如何春又将归去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花 客中感春' AND p.poem_author = '徐釚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再用前韵', '袁甫', '宋代', '小时所学老何如，自诧西河不记洙。\n曾子斯言讥背本，祗今犹足警吾徒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再用前韵' AND p.poem_author = '袁甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南纪楼', '夏倪', '宋代', '江发岷山如瓮口，汉从嶓冢又东流。滔滔江汉为南纪，我忆禹功时倚楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南纪楼' AND p.poem_author = '夏倪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暮春 其二', '周文', '明代', '鸟声泣暮雨，蝶梦绕东风。花落不堪问，春光半已空。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暮春 其二' AND p.poem_author = '周文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭瘿公 其三', '黄浚', '近代', '苍天厄文人，世乱遇尤酷。每翻孝标序，深念步兵哭。\n\n君身颀而温，妇子并如玉。异时张长沙，好士屡推毂。\n\n庶几彯天衢，乃有狼龁足。夷然亦无忤，果蓏例剥辱。\n\n造物意犹欿，长年贫为梏。虽梏不自哀，舂容托歌曲。\n\n极贫又予病，心肾重劙斸。将身代鼠肝，亦不赦汝毒。\n\n文章故憎命，何独盛博逐。颇疑身非身，其魄早升屋。\n\n伤哉病狂妇，焉识君鬼箓。人间无乐土，决去傥自福。\n\n魂兮归閒安，寺门粲秋菊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭瘿公 其三' AND p.poem_author = '黄浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅鋗 其三', '屈大均', '明代', '蠢尔龙川令，乘时窃一州。徒能欺二世，不解助诸侯。\n\n冠带迟南越，车书阻上游。将军句践裔，智勇著春秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅鋗 其三' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('隐梅福处', '黄庭坚', '宋代', '吴门不作南昌尉，上疏归来朝市空。笑拂岩花问尘世，故人子是国师公。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '隐梅福处' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('斋居杂咏二十首 其十五', '张元凯', '明代', '清樽泛流霞，一室生虚白。鹓雏栖高梧，空以腐鼠嚇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '斋居杂咏二十首 其十五' AND p.poem_author = '张元凯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('扇面山水次东陵韵', '江源', '明代', '细雨空濛津树合，小桥迢递水烟通。春风杖屦寻诗客，不在孤山定剡中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '扇面山水次东陵韵' AND p.poem_author = '江源';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('琵琶仙 答巽观', '卢前', '近代', '何事残鹃，不能忘、锦片江南风月。春到多少花开，花前旧人别。\n\n愁损了、楼阴柳叶。更谁惜、几枝啼血。望帝魂归，巫云梦冷，莺燕消息。\n\n又还听吹角空城，去迢递、东风渐无力。收拾一窗春雨，付伤心词笔。\n\n偷减声里，移宫换羽，第四弦、激荡凄切。指顾咫尺山河，竟成吴越。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '琵琶仙 答巽观' AND p.poem_author = '卢前';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('珍珠帘 灯约阻雨', '陈洵', '清代', '东风漂荡灯如水。红楼望、倦枕恹恹慵起。衾麝惜余熏，熨旧寒醒未。\n\n染柳妆梅箫意懒，奈嫩约、黄昏犹记。愁理。问凌波庭户，深深能几。\n\n顽老著甚情怀，便良宵花月，多时无味。楚梦总关人，教看春何计。\n\n绛蜡流尘轻换尽，况更说、承平歌吹。闲里。恁过眼年光，空余清泪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '珍珠帘 灯约阻雨' AND p.poem_author = '陈洵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鼓笛令', '朱敦儒', '宋代', '纸帐绸衾忒暖。尽自由、横翻倒转。睡觉西窗灯一笺。恰听打、三更三点。 \n 残梦不须深念。这些个、光阴煞短。解散缰绳休系绊。把从前、一笔句断。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鼓笛令' AND p.poem_author = '朱敦儒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月', '傅熊湘', '清代', '万树梅花绕屋，千头橘婢当山。一邱一壑任吾閒。\n\n休较谁长谁短。\n\n蒲扇风堪却暑，糠皮火好消寒。柴门无事日常关。\n\n那识人间冷暖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月' AND p.poem_author = '傅熊湘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别诗二首', '吕岩', '唐代', '无心独坐转黄庭，不逐时流入利名。救老只存真一气， \n 修生长遣百神灵。朝朝炼液归琼垄，夜夜朝元养玉英。 \n 莫笑老人贫里乐，十年功满上三清。 \n 时人受气禀阴阳，均体乾坤寿命长。为重本宗能寿永， \n 因轻元祖遂沦亡。三宫自有回流法，万物那无运用方。 \n 咫尺昆仑山上玉，几人知是药中王。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别诗二首' AND p.poem_author = '吕岩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽溪园周知郡 其二', '王义山', '宋代', '记得年时试别头，得君引我上瀛洲。当场独步眇馀子，好手先拈第一筹。\n\n锦水曾寻香戟梦，洪崖去伴赤松游。瓣香遥致生刍敬，渺渺螺川涕泗流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽溪园周知郡 其二' AND p.poem_author = '王义山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送暨阳同知', '王冕', '元代', '我生山野毛发古，不是多时旧巢许。\n松根坐卧忘岁年，足迹何曾入官府？雨晴忽觉草添肥，春来春去都不知。\n耕田凿井亦足乐，短歌长啸随所之。\n溪谷无尘人事少，纵有饥寒能自保。\n花村月夜犬不惊，可是太平风俗好。\n昨日柳花如雪飞，今日作诗何所思？我诗似质朴，君政从可推。\n锦衣翩翩马如练，拜恩应到黄金殿。\n他年皂盖下蓬莱，更与君侯作佳传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送暨阳同知' AND p.poem_author = '王冕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杨柳歌', '庾信', '南北朝', '河边杨柳百丈枝，别有长条踠地垂。 \n河水冲激根株危，倏忽河中风浪吹。\n可怜巢里凤凰儿，无故当年生别离。\n流槎一去上天池，织女支机当见随。\n谁言从来荫数国，直用东南一小枝。\n昔日公子出南皮，何处相寻玄武陂。\n骏马翩翩西北驰，左右弯弧仰月支。\n连钱障泥渡水骑，白玉手板落盘螭。\n君言丈夫无意气，试问燕山那得碑。\n凤凰新管萧史吹，朱鸟春窗玉女窥。\n衔云酒杯赤玛瑙，照日食螺紫琉璃。\n百年霜露奄离披，一旦功名不可为。\n定是怀王作计误，无事翻复用张仪。\n不如饮酒高阳池，日暮归时倒接离。\n武昌城下谁见移，官渡营前那可知。\n独忆飞絮鹅毛下，非复青丝马尾垂。\n欲与梅花留一曲，共将长笛管中吹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杨柳歌' AND p.poem_author = '庾信';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('胡人醉归图', '钱逊', '明代', '貂帽锦靴明绣衣，调鹰射虎捷如飞。\n紫髯寒作猬毛磔，碧眼夜看霜月辉。\n筚篥声中传汉曲，琵琶帐底醉明妃。\n更深宴罢穷庐雪，乱拥旌旄马上归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '胡人醉归图' AND p.poem_author = '钱逊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('将抵江口', '徐震堮', '近代', '亭午赫炎曦，溪回路愈窄。小舟数十人，行李相填塞。\n\n崖仄树欹根，湍分沙露脊。篙师立水中，推挽不能尺。\n\n村店隔疏林，市桥逗行客。饥雷方殷肠，汗雨已淋额。\n\n或驰逐担夫，或下争箪筏。宿昔轮蹄间，焉知道路剧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将抵江口' AND p.poem_author = '徐震堮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春景 春风花草香', '刘辰翁', '宋代', '高下花成谷，烟绵草际空。以香为世界，布馥是春风。\n\n骀荡蛛丝外，颠狂蝶梦中。汀洲仙药市，天地锦薰笼。\n\n澧浦遗余绿，昌州绝世红。馀芳犹可藉，应恨耿匆匆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春景 春风花草香' AND p.poem_author = '刘辰翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('张若澄秋岭横云小幅', '弘历', '清代', '参得王蒙皴法，写将杜甫诗情。秋色一窗静对，足忘人世浮名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '张若澄秋岭横云小幅' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绍熙庚戌十月偕赵仲宗舜和潘谦之曾鲁仲游九峰芙蓉寿山纪行十首 其五 早观龙湫', '黄干', '宋代', '夜宿群峰里，朝游大石湫。寒潭飞薄雾，叠障泻洪流。\n\n侧径苍苔滑，丛祠古木幽。神龙好高卧，云雨不胜愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绍熙庚戌十月偕赵仲宗舜和潘谦之曾鲁仲游九峰芙蓉寿山纪行十首 其五 早观龙湫' AND p.poem_author = '黄干';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头 其二十三 题临江驿和徐意一韵', '李曾伯', '宋代', '君莫厌行役，易尔此非难。人情无已，久阴忧潦霁忧乾。\n\n借得庭轩一榻，忘却征涂炎暑，小驻瀹龙团。世路任渠险，襟抱五湖宽。\n\n叹平生，环辙迹，已苍颜。梅花雪片万里，奚又絷南冠。\n\n应是江山好处，犹待推排老眼，天未许休官。莫忆故园竹，日日报平安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头 其二十三 题临江驿和徐意一韵' AND p.poem_author = '李曾伯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书事十首', '刘克庄', '宋代', '晋士材疏辩舌优，俗虽虚诞尚清修。\n可容卿等灵百辈，亦过江来第一流。\n元老纵然挥玉麈，七贤已有执牙筹。\n后来灵宝真儿态，书画惟凭夺与偷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书事十首' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游阳河岸', '姚合', '唐代', '终日游山困，今朝始傍河。寻芳愁路尽，逢景畏人多。 \n 鸟语催沽酒，鱼来似听歌。醉时眠石上，肢体自婆娑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游阳河岸' AND p.poem_author = '姚合';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('令狐学士金莲图', '许有壬', '元代', '九天光彩动金闺，辇路风香树影齐。却笑汉家恩数薄，只教天禄待青藜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '令狐学士金莲图' AND p.poem_author = '许有壬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重游鼎湖山短吟八首 其八', '许南英', '清代', '在山泉水清，可以濯我足。何日再来游，梦绕鼎湖曲？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重游鼎湖山短吟八首 其八' AND p.poem_author = '许南英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同张石磐侍御游沈氏山庄三首 其三', '孙承恩', '明代', '海上移来小朵云，清虚不着世间氛。何当少借三年住，洞里吹箫日共君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同张石磐侍御游沈氏山庄三首 其三' AND p.poem_author = '孙承恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄鲁直书简帖赞', '岳珂', '宋代', '诗至江西，始别宗派。\n字岂无祖，人其有待。\n鹤瘠鸾铩，松寒石怪。\n彼有发僧，尚闻謦欬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄鲁直书简帖赞' AND p.poem_author = '岳珂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浪淘沙 题芙蓉绣球', '叶璧华', '清代', '几日雨帘纤。倦绣恹恹。浅红轻白爱天然。寂寞美人残梦悄，懒布秋千。\n\n芳事画栏边。蜂蝶翩翩。妆成七宝致缠绵。恍惚玉环诸姊妹，连袂朝天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浪淘沙 题芙蓉绣球' AND p.poem_author = '叶璧华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('端午帖子 其二', '赵彦若', '宋代', '扬子江中百炼金，宝奁疑是月华沉。争如圣后无私鉴，明照人间万善心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '端午帖子 其二' AND p.poem_author = '赵彦若';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠方干处士歌', '吴融', '唐代', '把笔尽为诗，何人敌夫子？句满天下口，名聒天下耳。 \n 不识朝，不识市，旷逍遥，闲徙倚。一杯酒，无万事； \n 一叶舟，无千里。衣裳白云，坐卧流水。霜落风高忽相忆， \n 惠然见过留一夕。一夕听吟十数篇，水榭林萝为岑寂。 \n 拂旦舍我亦不辞，携筇径去随所适。随所适，无处觅。 \n 云半片，鹤一只。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠方干处士歌' AND p.poem_author = '吴融';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江神子·癸亥陈和叔会于赏心亭', '张舜民', '宋代', '七朝文物旧江山。水如天。莫凭阑。千古斜阳，无处问长安。更隔秦淮闻旧曲，秋已半，夜将阑。\n争教潘鬓不生斑？敛芳颜。抹幺弦。须记琵琶，子细说因缘。待得鸾胶肠已断，重别日，是何年？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江神子·癸亥陈和叔会于赏心亭' AND p.poem_author = '张舜民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花 以纸花清供戏赋', '饶宗颐', '近代', '人间无复埋花处。为怕花残、莫买真花去。静对琼枝相尔汝。胆瓶觑面成宾主。\n\n词客生生花里住。裁剪冰绡、留写伤春句。紫蝶黄蜂浑不与。任他日日闲风雨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花 以纸花清供戏赋' AND p.poem_author = '饶宗颐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵潘德鄜山行', '史浩', '宋代', '学佛以佛魔，学儒为儒缚。胡不朝隐几，㗳焉似南郭。\n\n是非风过耳，名利束高阁。回视平生心，无乃亦大错。\n\n便当息万缘，摆去如斧削。神游八极表，笑傲有馀乐。\n\n山水得胜处，一揽襟量廓。杖锡群峰颠，宫殿浮碧落。\n\n下瞰徐符岩，居然在山脚。众水会一涧，颓波泻珠箔。\n\n奔放出中涂，隐潭钟万壑。轰如破蛰雷，急似晴空雹。\n\n或复地中行，鸢飞鱼自跃。跻攀至飞电，乳窦知谁凿。\n\n向来因风絮，句法诚软弱。六花倾万仓，千古无锁钥。\n\n濛润遍寰海，何止洒林薄。凭栏眼欲眩，顿洗眵昏浊。\n\n翻身上妙高，愈觉吟魂矍。凿齿对弥天，相视两无怍。\n\n祇恐星轺登，蕙帐闻怨鹤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵潘德鄜山行' AND p.poem_author = '史浩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('扬子江晓望', '缪徵甲', '清代', '五更残梦雁声催，草阁临江眼界开。收尽春寒红日涌，隔江柔橹带潮来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '扬子江晓望' AND p.poem_author = '缪徵甲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('月夜', '刘鹗', '元代', '中宵月娟娟，睡起得孤快。树影在流水，天地有真态。\n\n洒然心镜空，如或饮沆瀣。妙趣苟得之，著意成蒂芥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '月夜' AND p.poem_author = '刘鹗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄诸弟', '李纲', '宋代', '自取飘零不复云，索居终日念离群。送书未见来黄耳，陟岵惟知望白云。\n\n素发偏亲乌鸟急，青春诸季棣华分。天涯只有思家切，须使音声不辍闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄诸弟' AND p.poem_author = '李纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宣州杂诗二十首', '梅尧臣', '宋代', '昭亭万仞山，古庙半山间。\n赛雨使君去，钓潭渔父闲。\n蕨肥岩向日，竹暗垅连关。\n北望高楼上，南飞鸟自还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宣州杂诗二十首' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('追挽王宪副先生', '潘希曾', '明代', '拟赋招魂欲断肠，曾于髫丱挹威光。乘骢尚忆同先子，附骥偏怜得季方。\n\n翰苑才名元独步，柏台风度更流芳。高坟宿草年华去，怅望空惭一瓣香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '追挽王宪副先生' AND p.poem_author = '潘希曾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题水村图', '罗志仁', '元代', '长爱秦郎绝妙词，荒寒暗合辋川诗。斜阳万点寒鸦处，流水孤村又一奇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题水村图' AND p.poem_author = '罗志仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杏湾', '屈大均', '明代', '慈峨水落满双溪，文杏花开二月齐。无限红颜随马足，雨来俱作锦障泥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杏湾' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '王随', '宋代', '照池莲艳红疑菜，入户山光翠可枯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '王随';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送友人', '石宝', '明代', '明时豪俊客，眼不著长檠。贤圣开书夜，江湖纵酒情。\n\n虞卿能赴急，徐稚本躬耕。易水城西畔，时来一濯缨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送友人' AND p.poem_author = '石宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杨花篇', '王廷相', '明代', '广陵三月可怜春，青青杨柳蘸湖新。\n长条不绾思归客，散作飞花愁杀人。\n浣沙艳艳吴江女，拾取香球连袂举。\n花点轻狂只欲飞，徒欲多情乱心绪。\n吴宫隋苑烟袅袅，别有豪华竞春早。\n飞琼流雪洒行旌，日莫迷却长杨道。\n江头一树白离离，打阵随风趁落晖。\n漫天扑地何时住，困入沧波却怨谁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杨花篇' AND p.poem_author = '王廷相';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('祠紫盖山经玉泉山寺', '张九龄', '唐代', '指途跻楚望，策马傍荆岑。稍稍松篁入，泠泠涧谷深。 \n 观奇逐幽映，历险忘岖嶔。上界投佛影，中天扬梵音。 \n 焚香忏在昔，礼足誓来今。灵异若有对，神仙真可寻。 \n 高僧闻逝者，远俗是初心。藓驳经行处，猿啼燕坐林。 \n 归真已寂灭，留迹岂湮沉。法地自兹广，何云千万金。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '祠紫盖山经玉泉山寺' AND p.poem_author = '张九龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题禹庙二首', '张镃', '宋代', '为人心切屡忘家，力量方知有等差。\n莫信空山葬冠剑，且吟古屋画龙蛇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题禹庙二首' AND p.poem_author = '张镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈', '张浚', '宋代', '教外单传佛祖机，本来无悟亦无迷。\n浮云散尽青天在，日出东方夜落西。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈' AND p.poem_author = '张浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岩下放言五首 其五 灵椿台', '黄庭坚', '宋代', '苍苔古木，相依涧壑之滨。黄葛女萝，自致风云之上。\n\n人就阴而息迹，鸟投暮而来归。水影林光，常相助发。\n\n溪声斧响，直下称提。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岩下放言五首 其五 灵椿台' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六安枕铭', '崔骃', '两汉', '枕有规矩，恭一其德。承元宁躬，终始不忒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六安枕铭' AND p.poem_author = '崔骃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('波罗河屯行宫作', '弘历', '清代', '秋日散清辉，秋空澄碧落。我意与之然，去来何执著。\n\n寒花步今径，阴树褰昔幕。会心足希夷，容膝且宽绰。\n\n是处有缥缃，无妨读书乐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '波罗河屯行宫作' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金雀花', '翁元广', '宋代', '管领东风知几春，也将俗态染香尘。有人不具看花眼，恼杀飘蓬老病身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金雀花' AND p.poem_author = '翁元广';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晴', '弘历', '清代', '塞雨滋秋野，金风助快晴。翠峦新沐濯，红日越晶明。\n\n草色犹含馥，溪流乍咽声。底须虑泥滑，牧法马蹄轻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晴' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('首春同枌友携樽过野渡访梅即席 其一', '卫宗武', '宋代', '枌朋载酒子云居，何必孤山远访逋。癯影参差浓复淡，古香传送有还无。\n\n朋龟剩喜如云集，汎蚁何妨过日晡。索笑却嫌来较晚，一林芳意太纷敷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '首春同枌友携樽过野渡访梅即席 其一' AND p.poem_author = '卫宗武';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晒衣', '杨万里', '宋代', '亭午晒衣脯褶衣，柳箱布襆自携归。\n妻孥相笑还相问，赤脚苍头更阿谁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晒衣' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日郊游和友人韵', '梁栋', '宋代', '已昔东风御柳斜，枯肠一日万周车。\n壮心难起泥中絮，老眼羞看雾裹花。\n巷柏几家无主燕，池塘一种为官蛙。\n江南寒食无烟火，白书沈沈似月华。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日郊游和友人韵' AND p.poem_author = '梁栋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('橘斋为张良医赋', '陈琏', '明代', '种得苏耽橘，斋前绿满行。树深苔石古，花落井泉香。\n\n药笼参苓富，芸窗岁月长。传家阴骘厚，著效有奇方。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '橘斋为张良医赋' AND p.poem_author = '陈琏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '李焘', '宋代', '断碑唐日寺，遗像晋时僧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '李焘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上巳', '李若水', '宋代', '小桃脱萼柳梢柔，春色无边破客愁。\n好与永和修故事，一时人物尽风流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上巳' AND p.poem_author = '李若水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望池州山', '贡奎', '元代', '少年江上一官閒，老去重来似梦间。欲觅故人行乐处，白云遮尽九华山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望池州山' AND p.poem_author = '贡奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六经阁', '韩漪', '宋代', '小楼灯火夜青荧，风撼梧桐客梦惊。\n谁家更理琴乌曲，误听壁间丝竹声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六经阁' AND p.poem_author = '韩漪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('巴黎圣母祠Notre-Dame夜步 用七里濑韵', '饶宗颐', '近代', '游目久踌躇，古意生临眺。夜树带馀清，高阙耸双峭。\n\n浅水鱼吻足，华灯月分曜。千载此祈褫，神风助舒啸。\n\n虽乏上皇心，终会灵台妙。惭为掣鲸手，屡倚天涯钓。\n\n息意休辨宗，厝辞增物诮。讴歌归去来，欲谱穿云调。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '巴黎圣母祠Notre-Dame夜步 用七里濑韵' AND p.poem_author = '饶宗颐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('听沈二弹北曲', '王伯稠', '明代', '燕歌撩乱夜弦鸣，诉尽青楼恨别情。\n四十年前明月夜，梦回曾听断肠声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '听沈二弹北曲' AND p.poem_author = '王伯稠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('相和歌辞。怨诗', '孟郊', '唐代', '试妾与君泪，两处滴池水。看取芙蓉花，今年为谁死。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '相和歌辞。怨诗' AND p.poem_author = '孟郊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('追和杨眉庵次韵李义山无题诗五首 其一', '沈愚', '明代', '兰桨双欹倚桂舟，隔花临水思夷犹。香囊玉佩劳相赠，绣幄银屏惜共留。\n\n愁绕凤台秦树暝，梦回巫峡楚云秋。多才苦被春情恼，镜里潘郎雪满头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '追和杨眉庵次韵李义山无题诗五首 其一' AND p.poem_author = '沈愚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古 其四十五', '释道颜', '宋代', '网中跳出便飞腾，好个天然俊衲僧。何似当初未入网，悟来方始是知音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古 其四十五' AND p.poem_author = '释道颜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题画', '黎贞', '明代', '秋岩有高士，扫石松下坐。忽忆圭峰樵，抱琴欲相过。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题画' AND p.poem_author = '黎贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('红毛城', '陈廷瑜', '清代', '苍莽海天秋，孤城兀自留。乱舂鲲屿浪，独镇鹿门洲。\n\n渡皆三篙水，潮平一叶舟。数声清角起，人在枕江楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '红毛城' AND p.poem_author = '陈廷瑜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆与刘伯温章三益叶景渊三君子同上江表五六年间人事离合不齐而景渊已作土中人矣慨然有赋', '宋濂', '元代', '我歌何太苦，触事增百忧。忆离溪上舍，久客城东楼。\n\n钩经语衮衮，舞剑光油油。五穷作奇祟，六凿为深仇。\n\n昏眸眩翳镜，秋骨束算筹。取憎鬼亦唾，出谒人谁谋。\n\n有美济时彦，来自处士州。金茎擎白液，玉瓒含黄流。\n\n长山同蹑楼，严濑仍维舟。雨花掠篷走，风蒲向人愁。\n\n冒险前至歙，计程几经邮。盘涡结唇穴，欹石排蛇矛。\n\n暗陵走魑魅，灌木啼鸺禋。川尽青逗晓，城新白凝秋。\n\n贤躅访阙里，仙踪索浮丘。乌聊就神卜，绮席征童讴。\n\n颍滨所谪宦，绩溪倚荒陬。丛祠尚赑屃，苔碣犹蛟虬。\n\n摩挲未及读，行迈焉能留。随山转荦确，满目只梧楸。\n\n淳原当日盛，杰观连云稠。兵馀有遗构，星分如碎裘。\n\n徘徊望泾邑，迤逦驱晨裛。狭径横黑辗，荒茅飞白球。\n\n聚落耿寒磷，原田巢秃鹙。百里一庐舍，平沙千髑髅。\n\n穴塍支爨鼎，掬溪咽乾糇。天才或吊白，诗衲还逢休。\n\n感慨每东望，盘回且西游。层楼眺叠嶂，汇水寻宛句。\n\n红线毯方软，木瓜酝新篘。风流忆江谢，文藻胜枚邹。\n\n落日惨平楚，悲风吟古湫。三湖渺空阔，一棹成穷搜。\n\n苍茫日月浴，震荡乾坤浮。水落近成浦，沙屯远为洲。\n\n网师出文鳜，墨客嘲轻鸥。涂经华林岸，地接秦淮沟。\n\n穷塔屹天秀，列廛布城周。河山互联络，龙虎相雄遒。\n\n郁葱金焰发，潋滟虹光抽。烟霞压台殿，剑舄集公侯。\n\n泮宫共一榻，江树闻鸣鸠。钟阜足游衍，龙湾更夷犹。\n\n谈锋述王霸，政柄分嬴刘。淬文砺戈戟，博古陈罍卣。\n\n合庖集鱼雁，响屐锵琅球。桂窗足每跣，花日首多囚。\n\n赌棋或握算，斗酒恒投钩。下关避沉酗，抵掌争嘲咻。\n\n一旦分客袂，三年感灯篝。剖符洪都郡，瞻云苍岭头。\n\n晨星遂落落，宵梦长悠悠。怀生悯契阔，悼死隔明幽。\n\n恶怀不可抑，衰涕何能收。牛鼎伤折足，羽旌恨无斿。\n\n此生几冠屦，两间寄蜉蝣。宣尼嗟逝水，漆园叹悬疣。\n\n天德在所务，人役将焉酬。矧当肃秋气，正值酣商飕。\n\n紫螫饱丹液，黄鞠苞金瓯。得酒且自喜，锢情欲谁仇。\n\n床头有《周易》，归去推刚柔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆与刘伯温章三益叶景渊三君子同上江表五六年间人事离合不齐而景渊已作土中人矣慨然有赋' AND p.poem_author = '宋濂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题东坡戴笠图', '贝琼', '明代', '两屐新泥蒻笠攲，满村风雨独归时。玉堂天上神仙客，妇女儿童总未知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题东坡戴笠图' AND p.poem_author = '贝琼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂剧·郑孔目风雪酷寒亭', '杨显之', '元代', '第二折\n\n(搽旦同俫儿上，云)我把你两个小弟子孩儿，你老子在家骂我。我如今洗剥了，慢慢的打你。待我关上门，省的有人来打搅。(正末上，云)自家赵用，跟着哥哥攒造文书上京师去。行到半途，遗剩了一纸文书，只得重回家中，取那文书走一遭去也可。(唱)\n\n【越调】【斗鹌鹑】俺家里少东无西，可着我走南嘹北。俺哥哥才娶的偏房，新亡了正室。撇了个幼女娇男，可又没甚的远亲近戚。我这里仔细的寻思起：他则待卧柳眠花，怎知道迷妖着鬼。\n\n【紫花儿序】想着他亲娘在日，见这般打骂凌辱，不由的感叹伤悲。我一心似箭两脚如飞，走的我气喘狼藉，恨不得一步奔来城市里。早行至哥哥门内，则听的大叫高呼。元来又打得他女哭儿啼。(搽旦云)如今酒又不醉，饭又不饱，我慢慢的打你这两个小弟子孩儿。(正末云)兀的不打孩儿哩。(唱)\n\n【小桃红】则问你赛娘、僧住为何的，他可也有甚么闲炒刺？(云)嫂嫂开门来(搽旦云)这个是赵用的声音。你两个且起去揩了泪眼，我买馍馍你吃。我开了这门(见末科云)小叔叔，你怎的回来？有甚么勾当(正末见俫儿科，云)嫂嫂，你为甚么打这孩儿？(搽旦云)阿弥陀佛，头上有天。我为甚么打他？(正末云)嫂嫂，我试猜咱。(唱)莫不是少柴无米苦央及？(搽旦云)柴米都有，一个不肯上学，一个不肯做生活，我逗他耍来。(正末唱)便休题伶牙俐齿相支对，想着我亲娘在日，看承似神珠宝贝。(搽旦云)天也，我爱的是这一双儿女。(正末唱)怎禁他佯孝顺假慈悲。\n\n(搽旦云)你为什么回家来？(正末云)哥哥遗剩了一纸文书，说在背阁板上。(搽旦云)你自家取去。(正末取科，云)有了文书，我去也。(俫儿哭扯末科，云)叔叔，我跟将你去罢。你去了呵，他又打我也。(正末云)嫂嫂，看着哥哥面皮，休打孩儿。(唱)\n\n【天净沙】我急忙忙取得文移，趱程途不敢耽迟。怎禁他这孩儿倒疾，紧拽住咱家衣袂，则待要步步追随。\n\n【调笑令】这孩儿，便顽痴，有十分不是伤触着你，可怜他亲娘不幸先辞世，则抛下一双的业种无知。你也则看觑他爷这面皮，再休打的他哭哭啼啼。(搽旦云)哎哟，小叔你放心去，我怎肯打孩儿？(正末云)谢了嫂嫂，我去也。(俫儿扯住未科，云)叔叔，我则是跟了你去。(正末云)嫂嫂，你道是不曾打呵。(唱)\n\n【秃厮儿】为甚么适才间吖天叫地，都一般汪汪的泪眼愁眉。他和你又没甚杀爷娘的仇共隙，怎这般苦死的，怕相依，也波堪悲。\n\n(俫儿哭科，云)叔叔，我则是跟着你去。(正末唱)\n\n【圣药王】俺只见儿又啼，女又啼，哭的俺是铁人石意也酸嘶。他待要来也随，去也随，恰便似蚂蝗钉了鹭鸶屯，寸步不教离。\n\n(云)嫂嫂，你是必看哥哥面上，休打这孩儿者。(搽旦云)有你，我便不敢打，两次三番聒气。(做推末出门科，云)你去。我关上这门，打这小弟子孩儿。(正末云)这妇人推出我来，关上门。我待去了，出不的这口恶气。街坊邻舍听者：(词云)劝君休要求娼妓，便是丧门逢太岁。送的他人离财散家业破，郑孔目便是傍州例。这妇人生的通草般身躯，灯心样手脚。闲骑蝴蝶傍花枝，被风吹在妆梳阁。蜘蛛网内打筋斗，鹅毛船上邀朋友。海马儿驮行，藉丝儿牵走。有时蘸水在秤头秤，定盘星上何曾有？这妇人搽的青处青，紫处紫，白处白，黑处黑，恰便似成精的五色花花鬼。他生的兔儿头，老鼠嘴，打街坊，骂邻里。则你是个腌腌臜臜泼婆娘，少不得瓦罐儿打翻在井水底。(唱)\n\n【寨儿令】我骂你这歪刺骨，我骂你这泼东西。你生的来兔儿头老鼠嘴，长则待吵是寻非，叫骂过日，怎做的好人妻？\n\n【幺篇】这都是俺哥哥命运低微，带累你两个孩儿受尽禁持。我本待好心肠苦劝你，你倒恶狠狠把咱推。来来来，我便死也拚得和你做头敌。\n\n【收尾】我如今一脱气直走向京都地，一句句向哥哥说知。有一日郑孔目到来时，不道肯轻轻的素放了你。(下)\n\n(搽旦云)好也，着赵用这村弟子孩儿，骂我这一场去了。我如今且不打你，等我吃的酒醉饭饱了，慢慢的打你。(俫儿哭随下)\n\n\n第三折\n\n(丑扮店小二上，诗云)曲律竿头悬草稕，绿杨影里拨琵琶。高阳公子休空过，不比寻常卖酒家。自家是店小二，在这郑州城外，开着个小酒店。今早起来挂了酒望子，烧的镟锅儿热着，看有甚么人来？(孔目上云)自家郑孔目，攒造文书己回。我一路上来多听人说，我那浑家有奸夫，折倒我那一双儿女，未审虚实。远远的是一个酒店。这城里人家事务，他都知道。我试问他一声：卖酒的有么？(小二云)有。官人要打多少酒？(孔目云)你这厮不爽利。张保在那里？你叫他来。(小二云)官人请坐，我叫他去。张保，有人寻你哩。(正末扮张保上，云)来也！买卖归来汗未消，上床犹自想来朝。为甚当家头先白，晓夜思量计万条。小人江西人氏，姓张名保，因为兵马嚷乱，遭驱被掳，来到回回马合麻沙宣差衙里，往常时在侍长行为奴作婢。他家里吃的是大蒜臭韭，水答饼。秃秃茶食。我那里吃的？我江南吃的都是海鲜，曾有四句诗道来：(诗云)江南景致实堪夸，煎肉豆腐炒东瓜。一领布衫二丈五，桶子头巾三尺八。他屋里一个头领，骂我蛮子前，蛮子后。我也有一爷二娘，三兄四弟，五子六孙。偏是你爷生娘长，我是石头缝里进出来的？谢俺那侍长见我生受多年，与了我一张从良文书。本待回乡，又无盘缠，如今在这郑州城外开着一个小酒店儿，招接往来客人。昨日有个官人买了我酒吃，不还酒钱。我赶上扯住道：还我酒钱来。他道你是甚么人？我道也不是回回人，也不是达达人，也不是汉儿人。我说与你听者，(唱)\n\n【南吕】【一枝花】我是个从良自在人，卖酒饶供过。务生资本少，醖酿利钱多。谢天地买卖和合，凭老实把衣食掇。俺生活不重浊，不住的运水提浆，炊荡时烧柴拨火。\n\n【梁州第七】也强如提关列窖，也强如斡担挑箩。满城中酒店有三十座，他将那醉仙高挂，酒器张罗。我则是茅庵草舍，瓦瓮瓷钵。老实酒不比其他，论清闲压尽鸣珂。又无那胖高丽去往来迎，又无那小扒头浓妆艳里，又无那大行首妙舞清歌。也不是我奖誉，太过，这黄汤强如醇醪糯，则为我酾酒浆水刺破，面米相停无添和，那说起玉液金波。\n\n(做见科)(孔目云)张保，你在那里来？这早晚才来？你打二百钱的酒来。(正末云)打二百钱的酒，筛的热着，孔目自己吃。(孔目云)酒且慢慢的吃，你这里有甚么新事？(正末云)有新事，一贯钞买一个大烧饼，别的我不知道。(孔目云)不是这个。这里有个郑孔目，娶了一个小妇，折倒他前家一双儿女。(正末云)官人这个我知道，你听我说，(唱)\n\n【贺新郎】前家儿招了个后尧婆，小媳妇近日成亲，大浑家新来亡过。题名儿骂了孜孜的唾，骂那无正事颓唆，则待折损杀业种活撮。(孔目云)那妇人折倒他一双儿女，他那街坊可骂郑孔目么。(正末唱)这厮掌刑法做令史，觅钱来养娇娥，送的他人离财散家缘破。那贱人也不是鲁义姑，这厮也不足汉萧何。(孔目云)我听的说：那小妇人不与他两个孩儿饭吃，那两个孩儿只在长街上讨吃。有这话么？(正末唱)\n\n【红芍药】道偷了米面把瓮封合，掬的些冷饭儿，又被尧婆擘手把碗来夺。孩儿每雨泪如梭，黄甘甘面皮如蜡埚。前街后巷叫化些波，那孩儿灵便口喽啰，且是会打悲阿。\n\n【菩萨梁州】汤水儿或少或多，干粮儿一个两个，米面儿一撮半撮，舍贫的姐姐哥哥。他娘在谁敢把气儿呵？糖堆里养的偌来大，如今风雪街忍着十分饿。他不爱惜倒折挫，常言道：灰不如火热。多敢怕我信口开合。\n\n(孔目云)张保，听的人说：那尧婆有奸夫，作践了郑孔目的家私。你可常去他家送酒，这等勾当，却是有也无？(正末云)当日那尧婆来问张保买酒。张保送去，进入后门。我张保在那里等出家火。那尧婆教那两个孩儿烧着火，那婆娘和了面，可做那水答饼。煎一个，吃一个。那两个孩儿在灶前烧着火，看着那婆娘吃，孩儿便道：奶奶，肚里饿了。那婆娘将一把刀子去盘子上一划，把一个水答饼划做两块，一个孩儿与了半个。那孩儿欢喜，接在手里，番采番去，吊在地下。那婆娘说两个争嘴。官人，他只是怕热。(唱)\n\n【骂玉郎】把孩儿风流罪犯寻些个，吊着脚腕又不敢将脚尖那。当日纷纷雪片席来大，衣服向身上剥，井水向阶下泼，肐膝儿精砖上过。\n\n【感皇恩】他将那门户关合。怎生结磨？颤钦钦跪在阶基，可丕丕心惊惧，扑簌簌泪滂沱。当日个天时凛冽，怎能勾身上温和？孩儿每缩着脖项，拄着下颏，耸着肩窝。\n\n【采茶歌】僧住将手心儿搓，赛娘把指尖儿呵，冻的他战笃速打颏歌。他可也性子利害母阎罗，(孔目云)他可唤做甚么。(正末唱)则他是上厅行首唤做烧鹅。(孔目云)敢是萧娥？(正末云)哦，是萧娥。(孔目云)张保，那郑孔目的孩儿，也常到你这里来么？(正末云)他早晚便来也。(孔目云)等他来时，你引来见我。(俫儿上，云)我是郑孔目的孩儿，沿门叫化了，回张保店里去。(做见末科)(正末云)两个孩儿，这里有个官人，你见他去。(俫儿见孔目科)(哭云)兀的不是俺爹爹？(孔目云)兀的不是我两个孩儿？则被你痛杀我也。(正末唱)\n\n【哭皇天】我与你打闹处先赸过，拿笠儿忙盖合。心惊的我面没罗。(孔目云)张保(正末云)你是张保？(孔目云)我唤你哩。(正末云)我唤你哩。(孔目云)你看这厮波，你如何这等答应我？(正末唱)小人几曾离了镟锅。我是王留一般弟兄两个，(带云)官人也，(唱)你莫不是眼摩挲，错认了你这亲眷，你却是姓甚么？\n\n(孔目云)张保，我便是郑孔目。(正末唱)\n\n【乌夜啼】谢天地小人刚道的这淫邪货，并不曾道甚孔目哥哥。(孔目云)你也骂的我勾了。你说他有奸夫，是那一个(正末唱)要奸夫略数与你三十个，尽都是把手为活，对酒当歌。郑州浪汉委实多。(云)那奸夫姓高，(孔目云)高甚么？(正末唱)高阳公子休空过。凭着我在口言是亡身祸，言多语少，小人有些九伯风魔。\n\n(孔目云)既然那妇人有奸夫，把我这一双儿女寄在你这店中。我今夜晚间越墙而过，把奸夫淫妇都杀了罢。(正末唱)\n\n【黄钟尾】润纸窗把两个都瞧破，拽后门将三簧锁纳合。捕巡军快拿捉，急开门走不脱。到官司问甚么？取了招带枷锁，建法场把市郭，上木驴着刀剁，万剐了尧婆。兀的不痛快杀我。(下)\n\n(孔目云)天色晚了，我杀那奸夫淫妇去来。(下)(搽旦同高成上，云)高成，我老公不在家，我和你永远做夫妻，可不受用？(高成云)难得你这好心，我买条糖儿请你吃。(孔目云)天色晚了，我来到这后园墙下，攀着这柳枝，跳过这墙，来到卧房门首。我试听咱。(高成云)我怎么有些心跳？把这吊窗开着，有人来时我好走。(孔目云)可知有奸夫。我蹅开这门进去。(高成慌科，云)不中，有人来了，走走走！(下)(孔目云)兀的不是奸夫也？(搽旦云)奸夫在那里？(孔目云)这等妇人要做甚么？不如杀了罢。(搽旦云)救人也。(孔目杀科)(搽旦下)(孔目云)我待走了，可不带累邻舍？我索官司中出首去来。(下)\n\n\n第四折\n\n(李尹引张千上，云)小官李公弼，见任郑州府尹。今日升厅，坐起早衙。张千，喝撺厢。(张千云)在衙人马平安。抬书案。(孔目上跪科)(李尹云)兀的不是孔目郑嵩？你告甚么？(孔目云)小人去京师攒造文书回来，撞见奸夫在妻子房内。我蹅门进去，奸夫走脱，小人将妻子杀了，今来出首。(李尹云)郑嵩，你怎做的执法人？拿奸要双，拿贼要脏。走了奸夫，你可杀了媳妇，做的个无故杀妻妾。该杖八十，迭配远恶军州。张千，拿下去打着者。(张千云)小人行杖。(高成云)今日该我当日，我行杖。(高成打科，云)六十，七十，八十。(孔目云)那行杖的可是高成，则被他打杀我也。(李尹云)与他脸上刺了字，迭配沙门岛。张千，着一个能行快走的解子，便解将去。(高成云)小人解去。(李尹云)只今日就行。(高成押出门科)(孔目云)我和你有什么冤仇？你打的我这般狠？(高成云)你今日这井可也落在吊桶里么？(孔目云)天那，有谁人救我也？(同下)(李尹云)今日无事且转厅。(诗云)非我不怜他，他罪原非小。姑免赴云阳，且配沙门岛。(下)(正末扮宋彬引偻儸上，诗云)虎着痛箭难舒爪，鱼遭密网怎翻身。运去剑诛无义汉，时来金赠有恩人。自家护桥龙宋彬。自从解出郑州，到的半路，被我扭开枷锁，打死了解子，就在这山中落草为寇。好是快活也可。(唱)\n\n【双调】【新水令】我如今向槽房连瓮掇将来，偿还了我弟兄每口债。酒斟着醇糯醅，脍切着鲤鱼胎。今口开怀，直吃的沉醉出山寨。\n\n(云)小偻儸斟酒来。(偻儸进酒科，云)哥哥满饮一杯。(正未唱)\n\n【沉醉东风】兄弟每满满的休推莫侧，直吃的醉醺醺东倒西歪。把猪肉来烧，羊羔来宰。你可便莫得迟捱，直吃到梨花月上来。酒少呵，您哥哥再买。(云)嗨！我几乎忘了。我当初犯罪之时，若不是郑孔目哥哥救我性命，岂有今日？近来闻得俺哥哥也犯了罪，迭配沙门岛去。我想这等远恶军州，莫说到得那里，只在路上少不得是死的。古人有言：有恩不报，非丈夫也。小偻儸，撤了酒者。(唱)\n\n【落梅风】只管里贪恋着酒如泉，可顿忘了他恩似海。万一个在中途被人谋害，可不乾着了当初救命来。则问你护桥龙宋彬安在？\n\n(云)我如今点起五百名偻儸。直到郑州地面。若是俺哥哥解在中途，正好迎着，一同回还山寨。若是未经解出，拚的劫牢，定要救俺哥哥者。(做上路科)(儸儿上云)俺两个僧住、赛娘便是。俺父亲迭配沙门岛，如今在酷寒亭上，俺叫化些残羹剩饭，与他充饥去。(做见偻儸拿住科)(正末云)这两个叫化小孩儿是谁家的？(儸儿跪科，云)俺是郑孔目的孩儿赛娘、僧住。将军可怜见波。(正末唱)\n\n【乔牌儿】俺这里见孩儿添惊怪，破衣服怎遮盖？冻的他两只手似冬凌块，谁救你爹爹脱杻械。(俫儿云)我叫化些残茶剩饭，与俺父亲吃。(正末云)你父亲在那里？(俫儿云)俺父亲因拿奸夫，杀了淫妇，被官司问遣迭配沙门岛去，如今在酷寒亭上哩。(正末云)小偻儸跟了我，就到酷寒亭上，救俺哥哥走一遭去。(同下)(高成押孔目上科)(孔目云)哥哥且慢行者，我两个孩儿寻觅些茶饭去了。我在那酷寒亭上等一等，避过这雪，慢慢的再行将去。(高成云)你这两个小业种，少不得先结果了他，方才慢慢的处置你。既是雪大，且避过了这雪再走。(正未引偻儸同俫儿上)(唱)\n\n【川拨棹】这两个小婴孩，引三军何处来？赤紧的云锁冰崖，风敛阴霾，雪洒尘埃。则半合儿早粉画楼台，玉砌衢街。俺军中也做了银妆甲铠，俺哥哥在酷寒亭怕不活冻煞。\n\n(云)兀的不是俺哥哥！小偻儸，休教走了解子，且打开哥哥的枷锁者。(做解科)(唱)\n\n【七弟兄】莫猜，快来，把枷锁疾忙开。将哥哥左右相扶策，在鬼门关夺转得这冻形骸，向酷寒亭展脚输腰拜。\n\n(孔目云)兀的不吓杀我也。壮士，你是谁？(正末云)哥哥，则我就是护桥龙宋彬。(唱)\n\n【梅花酒】咱两个自间隔，为杀了裙钗，揽下非灾，不得明白。沙门岛程途怎地捱？酷寒亭风雪如何奈？从别离三二载，睡梦里记心怀，天对付巧安排。(孔目云)兄弟，是我当日救你命来，今日你却做我的大恩人也。(正末唱)\n\n【收江南】呀！谁承望月明千里故人来，则被这泼烟花送了你犯由牌，狠公人又待活烧埋。到今日救解，早收恰了那一点泪沾腮。\n\n(孔目云)兄弟，你救我咱，则这解子高成，便是奸夫。(高成云)我死也。(正末云)小偻儸，将这奸夫与我绑了，替哥哥报仇。(高成云)不干我事。我吃长斋的，肯做这勾当？(孔目云)兄弟，教我怎生是好？(正末云)哥哥休谎，同两个孩儿权到山寨上住几日，再作计较。(唱)\n\n【鸳鸯煞】从今后深仇积恨都消解，且到我荒山草寨权停待。畅道是本姓难移，三更不改，做一场白日胸襟，轰雷气概。将这厮吃剑乔材，任逃走向天涯外，我也少不得手到拿来，则做死羊儿般吊着宰。(云)小偻儸，把那厮先绑上山去，就安排果卓，请哥哥到寨中做庆喜筵席，将那厮万剐凌迟，以报冤恨者。(词云)今天下事势方多，四下里竞起干戈。其大者攻城略地，小可的各有巢窠。非是我甘心为盗，故意来啜赚哥哥。眼见得这场做作，官司里怎好兜罗？且共我同归草寨，徐观看事势如何？肯容他高成走脱，早拿来绑缚山坡。先下手挑筋剔骨，慢慢的再剖胸窝。也等他现报在眼，才把你仇恨消磨。待几时风尘宁静，我和你招安去未是蹉跎。\n\n题目后尧婆淫乱辱门庭\n\n泼奸夫狙诈占风情\n\n正名护桥龙邂逅荒山道\n\n郑孔目风雪酷寒亭', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂剧·郑孔目风雪酷寒亭' AND p.poem_author = '杨显之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临桂尉杨渭夫以诗来因次其韵兼简同僚', '陈傅良', '宋代', '万物各美恶，一室有面背。\n去来故无恒，欣厌惟所会。\n有能悟兹理，何必著幽邃。\n后圃并山麓，修竹积空翠。\n斧寻自何年，樊养特过计。\n陈根独遭时，沃壤亦借势。\n居然成独清，可以掩众媚。\n亭院起中{上不下几}，湖潦粲前际。\n於时吾岂敢，谓此天作对。\n新诗忽盛谈，俗状良内惭。\n子方及归期，客复搅离思。\n尚当封殖之，去日如始至。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临桂尉杨渭夫以诗来因次其韵兼简同僚' AND p.poem_author = '陈傅良';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和咏老除夕书怀七律两首 其一', '王益初', '近代', '苍狗白云急景驰，那堪两鬓已成丝。鸡虫得食何劳计，身世荣枯欲问谁。\n\n情绪千般萦夙梦，悲欢一例付新词。衔杯欲剪西窗烛，又是邻机晚放时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和咏老除夕书怀七律两首 其一' AND p.poem_author = '王益初';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闺思', '温纯', '明代', '对月默默语，清光应照君。记得别时约，相思但望云。\n\n月亦有圆缺，云亦有聚散。散与缺犹可，离愁尚减半。\n\n忽见云间月，低头忆远人。相思不相见，空有泪沾巾。\n\n君如失凰侣，妾如寄生草。桑末犹堪依，谁念君怀抱。\n\n孤栖霜露丛，忽遇花落期。花落无人扫，凄凉两地知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闺思' AND p.poem_author = '温纯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寒食清明十首', '刘克庄', '宋代', '当年传画烛，帝遣快行□。\n□□山斋卧，□目自结□。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寒食清明十首' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('曲林歌赠曹君时范十首 其七', '顾璘', '明代', '凋尽山中宰相松，长风无地吼蛟龙。曹公种子苍髯老，更引寒涛响后峰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '曲林歌赠曹君时范十首 其七' AND p.poem_author = '顾璘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江夜', '溥儒', '近代', '雨过春潮急，柴扉掩浪痕。无鱼星在罶，送酒月临门。\n\n乱水鸣云际，寒梅枕石根。几家闻夜织，寥落不成村。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江夜' AND p.poem_author = '溥儒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠耿郡伯', '刘麟', '明代', '晚岁河梁别，惊尘失雁行。宦游多慨感，君至有辉光。\n\n物润班班雨，天晴夜夜霜。汉廷还汲黯，犹自重淮阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠耿郡伯' AND p.poem_author = '刘麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀鸣禽', '周密', '宋代', '竹树环幽栖，积翠何森森。鸣禽不知数，日夕传好音。\n\n居然谢嚣𡏖，宛若居山林。哢清孤枕晓，声碎花房深。\n\n笙竽杂天籁，鼓吹无哇淫。物我自两忘，彼此无机心。\n\n髽奴不解事，探鷇稍见侵。忽动择木志，一去不可寻。\n\n鸥鸟骇海翁，智莫欺鱼禽。何以慰寂寥，静对空愔愔。\n\n风篁落纤月，谁伴清宵吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀鸣禽' AND p.poem_author = '周密';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送郑少府入辽共赋侠客远从戎', '骆宾王', '唐代', '边烽警榆塞，侠客度桑乾。\n柳叶开银镝，桃花照玉鞍。\n满月临弓影，连星入剑端。\n不学燕丹客，徒歌易水寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送郑少府入辽共赋侠客远从戎' AND p.poem_author = '骆宾王';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋答尹宪副先生 其三', '罗钦顺', '明代', '十年一曲采芝歌，高挂朝冠保太和。风采至今传蜀土，文章从昔重贤科。\n\n情萦藻句能多寄，光照寒门辱再过。休怪报章成怠缓，两曹重叠簿书磨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋答尹宪副先生 其三' AND p.poem_author = '罗钦顺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('记梦', '陆游', '宋代', '黄河衮衮抱潼关，苍翠中条接华山。\n城郭丘垆人尽老，药炉依旧白云间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '记梦' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬俞秀老', '王安石', '宋代', '洒扫东庵置一床，於君独觉故情长。\n有言未必输摩诘，无法何曾泥饮光。\n天壤此身知共弊，江湖他日要相忘。\n犹贪半偈归思索，却恐提桓妄揣量。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬俞秀老' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀吴野人先生', '吴麟', '清代', '伯鸾居庑下，元亮老篱边。隐矣吴夫子，高风齐二贤。\n\n赁舂常作客，采菊始归田。想见行吟处，溪流绕数椽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀吴野人先生' AND p.poem_author = '吴麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('周宗庙歌十二首 其六 皇夏', '庾信', '南北朝', '雄图属天造，宏略遇群飞。风云犹听命，龙跃遂乘机。\n\n百二当天险，三分拒乐推。函谷风尘散，河阳氛雾晞。\n\n济弱沦风起，扶危颓运归。地纽崩还正，天枢落更追。\n\n原祠乍超忽，毕陇或绵微。终封三尺剑，长卷一戎衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '周宗庙歌十二首 其六 皇夏' AND p.poem_author = '庾信';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('柳', '添雪斋', '当代', '望中青青柳，飞絮送残阳。古道替人语，何堪又断肠。\n\n向人梦魂渡，是夜风雨旁。心寒袭翠袖，烟冷映白裳。\n\n远水著萍迹，余英落沧桑。千山飘不去，万里忆回翔。\n\n故园春何在，如丝泪数行。东君莫托付，散花更苍茫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '柳' AND p.poem_author = '添雪斋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('孙生康祖从予海陵予荐之滁守赵叔明之门送以古诗', '孙应时', '宋代', '洙泗诸公游，参实少且鲁。谁知一贯学，其进乃甚武。\n\n儒生多山野，此事亦已古。儇儇细儿黠，往往车上舞。\n\n后生识取舍，百不能四五。子兮何为者，独行事踽踽。\n\n嗟我离师友，岁月渐莽卤。子辱从之游，未必免聋瞽。\n\n淮丞少官事，吏散日亭午。藜羹共脱粟，本不计客主。\n\n亲年当喜惧，药裹属覼缕。劳子辞我去，天寒无乃苦。\n\n滁阳贤太守，岂弟民父母。青山照城郭，广厦庇风雨。\n\n子往事佔毕，可但费樽俎。窗明棐几净，坚坐勿窥户。\n\n交情贵胆肝，师道在规矩。何妨坐椎钝，未可习媚妩。\n\n万里须坚车，百步要彊弩。书来说新功，吾其俟飞羽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '孙生康祖从予海陵予荐之滁守赵叔明之门送以古诗' AND p.poem_author = '孙应时';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜晴', '吴与弼', '明代', '风雨怯途穷，疲躯归兴浓。寒衾孤梦觉，旭日满窗红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜晴' AND p.poem_author = '吴与弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('北城门沙门', '庾肩吾', '南北朝', '俗茧厌缠丝，因由抽善縠。长披忍辱铠，去此纤罗服。\n\n愿引三涂众，俱令十使伏。珠月犹沈首，金錍未挑目。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '北城门沙门' AND p.poem_author = '庾肩吾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹊踏枝·漠漠春芜春不祝', '龚自珍', '清代', '漠漠春芜春不祝\n藤刺牵衣，碍却行人路。\n偏是无情偏解舞，\n蒙蒙扑面皆飞絮。\n\n绣院深沉谁是主？\n一朵孤花，墙角明如许！\n莫怨无人来折取，\n花开不合阳春暮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹊踏枝·漠漠春芜春不祝' AND p.poem_author = '龚自珍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('遂宁府境内火池', '袁说友', '宋代', '泽中有火犹为革，焰出方池更异常。\n气烈群山酣土赤，阳潜深地液硫黄。\n书生考订言虽确，造化工夫理甚彰。\n君看舆薪一杯水，物因偏胜故为强。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '遂宁府境内火池' AND p.poem_author = '袁说友';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次南京尚宝泰和杨公述职诗韵 其一', '程敏政', '明代', '忧国长思策治安，迩来微觉鬓毛残。牙绯当殿初书最，清白传家久耐寒。\n\n正论几闻倾四望，高眠犹说计三餐。老成终近君王侧，双佩追随应八銮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次南京尚宝泰和杨公述职诗韵 其一' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题云湖庆安院', '舒亶', '宋代', '门前屏障绕潺湲，付与林僧夜定还。松盖作云连十里，竹龙行雨出千山。\n\n白公香火莲红后，谢氏池塘草碧间。我亦凤凰台上客，图閒却笑未能閒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题云湖庆安院' AND p.poem_author = '舒亶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵昌甫所寄 其二', '韩淲', '宋代', '飞舞醯鸡只瓮天，何知老壮与穷坚。于今之世宜咸若，从古之贤定复然。\n\n荷尽菊残非一日，草深地僻几多年。吟窗明暗霜须雪，苟亦无言岂舍旃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵昌甫所寄 其二' AND p.poem_author = '韩淲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和黄门相公诏还题石门洞（黄门，武元衡也）', '郑馀庆', '唐代', '紫氛随马处，黄阁驻车情。嵌壑惊山势，周滩恋水声。 \n 地分三蜀限，关志百牢名。琬琰攀酬郢，微言鼎饪情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和黄门相公诏还题石门洞（黄门，武元衡也）' AND p.poem_author = '郑馀庆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('动星隐钓西南沙', '梁可基', '明代', '蓝川流水杏花初，城市心尘肯到无。箬笠蓑衣烟雨去，老翁依旧一狂奴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '动星隐钓西南沙' AND p.poem_author = '梁可基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨后看月', '李之世', '明代', '雨霁凉秋气自佳，悠悠新月逗人怀。凄凉客梦人千里，澹宕孤光水一涯。\n\n素影渐移刚到榻，明河欲落尚横街。聊将欢笑舒童仆，共把乡愁取次排。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨后看月' AND p.poem_author = '李之世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送毛检讨起贬云南幕僚', '王世贞', '明代', '乾坤惨淡干戈里，封事终军拭泪题。苑道夜乘中贵马，关头朝听逐臣鸡。\n\n盘江瘴暖桐花发，黔岭云深鹎鵊迷。魑魅如逢休代答，赐环应有汉宫泥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送毛检讨起贬云南幕僚' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠毛彦谟二首', '傅察', '宋代', '相逢晚岁莫情疏，径欲连墙卜并居。\n若学羡君诗有味，固穷怜我食无馀。\n从容杯酒频挥尘，斗薮尘埃喜振裾。\n闻道谈言过辅嗣，故应回首万浮虚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠毛彦谟二首' AND p.poem_author = '傅察';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送顾仪宾赴石城王府花烛 其一', '史鉴', '明代', '银河星度月流辉，来傍天孙织锦机。不道九霄风露冷，夜深催换紫绡衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送顾仪宾赴石城王府花烛 其一' AND p.poem_author = '史鉴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('景德镇客中余兄招偕刘陈二子茶楼夜坐分韵得水字适闻次日大幅降温', '陈忠平', '当代', '昌江夜谧适吾子，一角楼台閒照水。几上清茶款款添，窗前新月姗姗起。\n\n世情叹喟颇无端，诗道论争俱有理。闻说寒从别后生，转怜寒处多知己。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '景德镇客中余兄招偕刘陈二子茶楼夜坐分韵得水字适闻次日大幅降温' AND p.poem_author = '陈忠平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('度梅岭 其一', '戚继光', '明代', '溪流百折绕青山，短发秋风夕照间。身入玉门犹是梦，复从天末出梅关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '度梅岭 其一' AND p.poem_author = '戚继光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶题', '崔澄', '明代', '行舟少住更听歌，江上东风吹绿波。折桃华，赠离别，却怜春色已无多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶题' AND p.poem_author = '崔澄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('信士画真请赞', '释印肃', '宋代', '此法身，无变坏，\n鼻孔裹许藏三界。水月空花点不成，\n非相光中常自在。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '信士画真请赞' AND p.poem_author = '释印肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次刘观澜为题群玉山房韵', '邓雅', '明代', '自笑鄙夫耽野趣，结茆相对白云岑。苍苔古木门前路，明月清风世外心。\n\n倚剑秋高看鹤舞，吹箫夜半作龙吟。故人若许来相访，祗向栖霞谷口寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次刘观澜为题群玉山房韵' AND p.poem_author = '邓雅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('閒兴 其一', '林占梅', '清代', '万轴牙签一亩居，嚣尘远隔爱吾庐。煨茶为备醒时歠，聚墨因防兴到书。\n\n画架彩笼歌巧鸟，青盆碧藻漾文鱼。当前生意争春长，地窄何嫌趣有馀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '閒兴 其一' AND p.poem_author = '林占梅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贻白绵州', '李流谦', '宋代', '曾陪芍药醉春风，转首三年似梦中。谁使冲泥千里去，又欣剪烛一樽同。\n\n名章越好供妍唱，旧学全疏愧近功。莫怪分符少留滞，此邦曾客少陵翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贻白绵州' AND p.poem_author = '李流谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('巫山一段云•雨窗与程村夜话', '彭孙遹', '清代', '岁月闲中老，容华暗里消。清槐好为系征舠。浓绿染长桥。\n\n听雨僧庐静，寻诗竹院遥。烛花落尽又频挑。不寝费兰膏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '巫山一段云•雨窗与程村夜话' AND p.poem_author = '彭孙遹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽韩忠定公 其四', '林俊', '明代', '宝瑟元同调，山炉此瓣香。时寻参分野，遥望晋平阳。\n\n老泪回澜月，悲风绿野堂。皋村吊遗迹，何处是公乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽韩忠定公 其四' AND p.poem_author = '林俊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('后窗崖中孤树为薪者斫去', '卢青山', '当代', '芙子立崖半，十年共朝夕。始见尚幼株，婀娜不及膝。\n\n渐长生意成，数叶逢春碧。秋风飒遝来，糁玉纷叠积。\n\n横躯将入窗，举手抚可及。我坐萧窗前，相对恒闵默。\n\n中心交有语，岂待口舌力？浮世繁尘嚣，落落惘中臆；\n\n知天特生子，以慰我岑寂。岁华翻循转，少年忽三十。\n\n壮怀日益删，朋亲日以失。唯子契素心，百变愈莫逆。\n\n将与子谐老，共作尘寰客；岂意中道分，一旦遭斧劈。\n\n遗骸堕淤泥，青枝就朽灭。摧裂我肠肝，寸寸不可拾。\n\n天既予我欢，何故更夺扼？岂天好播弄，戏我如簸箦？\n\n转视苍苔间，遗根尚在石；或者阳春回，新枝重茁立。\n\n从此日千回，为子浇泉液。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '后窗崖中孤树为薪者斫去' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答李侍御问', '皎然', '唐代', '入道曾经离乱前，长干古寺住多年。爱贫唯制莲花足， \n 取性闲书树叶篇。自笑不归看石榜，谁高无事弄苔泉。 \n 身外空名何足问，吾心已出第三禅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答李侍御问' AND p.poem_author = '皎然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月（灯花）', '曹希蕴', '宋代', '零落不因春雨，吹嘘何假东风。纱窗一点自然红。费尽工夫怎种。 \n 有艳难寻腻粉，无香不惹游蜂。更阑人静画堂中。相伴玉人春梦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月（灯花）' AND p.poem_author = '曹希蕴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽刘都事父', '罗亨信', '明代', '禄养方期乐寿康，俄惊幻化掩玄堂。溪山风月遗吟稿，幕府才华羡令郎。\n\n夜鹤悲时云冉冉，晓猿啼处树苍苍。遥瞻独秀峰千尺，挂剑何时到墓傍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽刘都事父' AND p.poem_author = '罗亨信';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送强甫赴漳粹二首', '刘克庄', '宋代', '囝罢各华颠，临分倍黯然。\n吾惛如隔雾，汝孝可通天。\n郡古多文献，厅寒少事权。\n东冈今召父，犹在乃翁前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送强甫赴漳粹二首' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('木兰花慢', '黄侃', '近代', '忆湘皋旧佩，漫回蕊，绕屏边。纵解玩孤芳，移根上国，消息谁传。\n\n飘然。杜兰香去，问玉郎重遇是何年。休把幽心展尽，可知秋冷南天。\n\n相怜。别泪涓涓。情未歇、态犹妍。欢羁泊天涯，倡条冶叶，怎抵婵娟。\n\n离烟。洗愁痕净，伴蘼芜堂下记前缘。便拟招魂绿畹，小歌一曲游仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '木兰花慢' AND p.poem_author = '黄侃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中都', '欧大任', '明代', '钟离山绕鼎门东，此地曾橐万里弓。王气远浮珠树外，帝乡犹在白云中。\n\n衣冠几夜游原庙，父老千秋拜沛宫。笔札小臣思奏赋，自怜摛藻愧杨雄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中都' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉和御製中和', '杨亿', '宋代', '佳节更春晦，长标令甲名。\n天渊摇绿浪，仙杏吐丹荣。\n连皷将惊蛰，高枝已变莺。\n云谣传下土，汉曲被新声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉和御製中和' AND p.poem_author = '杨亿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄汇征惠石菖蒲既赋古风复成四韵', '郑刚中', '宋代', '附石菖蒲谁手种，形模姿色妙难如。\n黄蜂变去惟窠在，绿玉抽来祗寸馀。\n夜为露华离几案，晓添灶井向阶除。\n如何便得生秋意，更俗中间置小鱼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄汇征惠石菖蒲既赋古风复成四韵' AND p.poem_author = '郑刚中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次胡秋芦叔《杂诗》韵作《十术诗》，始得其七，为事弃去，遂未续作 其六 杀鸡取卵术', '卢青山', '当代', '各业投资皆灼热，居然学校独清寒。敢言教育真鸦噪，若数文盲是桂冠。\n\n种木成阴安可待，杀鸡取卵即为餐。人生识字忧患始，百载之期必大安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次胡秋芦叔《杂诗》韵作《十术诗》，始得其七，为事弃去，遂未续作 其六 杀鸡取卵术' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登姑苏台', '李啸轩', '宋代', '规模高敞俯城池，未必斯台是故基。\n风月只招人感慨，江山不管国兴衰。\n几年勾践仇思复，终日吴王醉不知。\n却使五湖烟浪里，扁舟一叶载西施。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登姑苏台' AND p.poem_author = '李啸轩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠石崇诗', '曹嘉', '魏晋', '文武应时用，兼才在明哲。嗟嗟我石生，为国之俊杰。\n\n入侍于皇闼，出则登九列。威检肃青徐，风发宣吴裔。\n\n畴昔谬同位，情至过鲁卫。分离逾十载，思远心增结。\n\n愿子鉴斯诚，寒暑不逾契。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠石崇诗' AND p.poem_author = '曹嘉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('锁窗寒（春思）', '王沂孙', '宋代', '趁酒梨花，催诗柳絮，一窗春怨。疏疏过雨，洗尽满阶芳片。数东风、二十四番，几番误了西园宴。认小帘朱户，不如飞去，旧巢双燕。 \n 曾见。双蛾浅。自别后，多应黛痕不展。扑蝶花阴，怕看题诗团扇。试凭他、流水寄情，溯红不到春更远。但无聊、病酒厌厌，夜月荼コ院。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '锁窗寒（春思）' AND p.poem_author = '王沂孙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏梅三十首 其三 江梅', '冯子振', '元代', '若有人兮湘水濆，冷香和月浸黄昏。自怜不入离骚谱，待把芳心吊楚魂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏梅三十首 其三 江梅' AND p.poem_author = '冯子振';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送客水路归陕', '韩翃', '唐代', '相风竿影晓来斜，渭水东流去不赊。枕上未醒秦地酒， \n 舟前已见陕人家。春桥杨柳应齐叶，古县棠梨也作花。 \n 好是吾贤佳赏地，行逢三月会连沙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送客水路归陕' AND p.poem_author = '韩翃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南城', '弘历', '清代', '道旁古南城，城废存土阜。云米拒契丹，筑此夹河守。\n\n和金计灭辽，唇齿患互受。外夷尚知此，小利目前取。\n\n讵惟失河北，汴亦不能有。国势成积弱，况复政多咎。\n\n方士及权奸，岂堪偻指数。虚内乃贪外，屋丰阒家蔀。\n\n五国固其宜，炯戒传不朽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南城' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('广遣兴五十八首 其五十一', '王夫之', '明代', '栎火垆边缩猬毛，犹贤击楫唱离骚。头风莫与陈琳檄，腹疾无庸叔展号。\n\n春梦半醒逐妇鸟，岳云抔土抱娘蒿。杀机夜半衾前动，扪虱思援斩佞刀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '广遣兴五十八首 其五十一' AND p.poem_author = '王夫之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春感十二首次王础尘 其五', '陈恭尹', '明代', '桑榆回首望朝晖，隙驷光阴迅若飞。一世有言同结舌，百年无日不开扉。\n\n每愁酒尽莺花满，预喜春生笋蕨肥。击壤自今歌帝力，杖藜还著住山衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春感十二首次王础尘 其五' AND p.poem_author = '陈恭尹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉和李如愚见寄', '邓雅', '明代', '老鹤千年寿，閒云一片心。乾坤今古事，风月短长吟。\n\n宦族西平远，仙家玉笥深。何当骑白鹿，閒暇一相寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉和李如愚见寄' AND p.poem_author = '邓雅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('反感愤', '陆游', '宋代', '膊膊庭树鸡初鸣，嗈嗈天衢雁南征。\n百年朝露岂长久，万事浮云常变更。\n出处有心终有愧，圣贤无命亦无成。\n西畴虽薄可自力，双犊且当乘雨耕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '反感愤' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登高丘而望远海赠梁岳', '欧大任', '明代', '登高丘，望远海，冥冥海风生白波，十丈汹涌冰嵯峨。\n\n有似瞿唐下三峡，篙工舟子不敢过。是时严冬十一月，雨霜吹作燕山雪。\n\n四野苍茫鸿雁饥，枯树半死木叶脱。嗟君萧飒风沙颜，冒寒苦欲趣入关。\n\n云涛不见西洲渡，咫尺那分北郭山。君不见披发之翁狂渡河，其妻止之徒咨嗟。\n\n家中餔麋尚可住，君今欲渡将如何。请君登高丘，与君望远海，一曲箜篌至今在。\n\n长风破浪岂无时，万斛之舟且须待。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登高丘而望远海赠梁岳' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春园雨后二首 其二', '林大钦', '明代', '人事有代谢，风光无改时。今日花开落，他年烟雨思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春园雨后二首 其二' AND p.poem_author = '林大钦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东园', '陆游', '宋代', '晨起东园去，消磨夏日长。\n随锄泉眼出，上爪药苗香。\n琴挂山斋壁，龟搘道室床。\n始知彭泽令，真足傲羲皇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东园' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('槜李别张子明 其二', '佘翔', '明代', '异地怜同病，君归不可留。弟兄俱白首，风月正清秋。\n\n失路悲寒雁，忘机愧野鸥。一杯聊惜别，不为答吴钩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '槜李别张子明 其二' AND p.poem_author = '佘翔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读沈石友七虞诗感而和之七首 其五', '谢元汴', '明代', '一亭孤兀峙，有客冷焉癯。菽水礼书易，砚田坟壤墟。\n\n稀星悲在罶，止屋叹瞻乌。漆室贫人女，肠中百折纡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读沈石友七虞诗感而和之七首 其五' AND p.poem_author = '谢元汴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长相思（闺怨）', '周邦彦', '宋代', '马如飞。归未归。谁在河桥见别离。修杨委地垂。 \n 掩面啼。人怎知。桃李成阴莺哺儿。闲行春尽时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长相思（闺怨）' AND p.poem_author = '周邦彦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('惜花', '寇准', '宋代', '深谢暖风传馥郁，长忧夜雨暗摧残。\n黄昏欲放笙歌散，更绕未栏子细看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '惜花' AND p.poem_author = '寇准';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('妾薄命', '郭钰', '元代', '孤鸾窥镜剪情缘，泪血沾襟十五年。谁信旧时歌舞伴，相逢犹自妒婵娟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '妾薄命' AND p.poem_author = '郭钰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蒙仲以二画寿予生朝各题一诗', '刘克庄', '宋代', '人彘昔擅宠，夺嫡谋甚工。\n留侯莫容喙，何况短后雄。\n挽回龙准帝，全赖皓首翁。\n昔去避嬴世，今来安刘宗。\n吕妪及新君，略未闻褒崇。\n岂非羽翼成，翩然返橘中。\n奈何一代史，不载四叟终。\n商山有遗庙，郭谓太古风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蒙仲以二画寿予生朝各题一诗' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿鼓山寺方丈 其一', '徐熥', '明代', '维摩丈室绝尘氛，坐对珠龛演梵文。松际窥人孤嶂月，山中留客半床云。\n\n疏钟出寺过林隐，怪鸟啼春彻夜闻。真性由来爱空寂，名香亲向殿前焚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿鼓山寺方丈 其一' AND p.poem_author = '徐熥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜吉老甥见过', '张耒', '宋代', '西风吹藜藿，秋色满环堵。\n悲虫语窗月，阴蕊开夕露。\n门闲宾客少，鸟雀任散聚。\n杨甥时过我，论诗朝达暮。\n新茶磨细雪，甘井漱清乳。\n匆匆贫家饭，藜藿不满俎。\n颇言行有日，征艎下洛渚。\n喜汝将凤归，惊余发加素。\n老慵愁应接，儿女较口语。\n乐逢亲骨肉，情话到尔汝。\n先君外孙子，惟尔冠俣俣。\n平生女◇兄，宜尔有风矩。\n长安木叶落，雨送万家暑。\n凉风当沽酒，为我醉起舞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜吉老甥见过' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('破阵子', '梁寅', '元代', '黯黯凄凄草色，狼狼藉藉花枝。江上烟波天共远，树外云山路更迷。\n\n故人音信稀。\n\n因病纵教废酒，非愁自懒题诗。芍药荼蘼开渐近，蹴鞠秋千乐有谁。\n\n雨僝风僽时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '破阵子' AND p.poem_author = '梁寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和琴坞耶溪渔唱绝句即题王椒畦图后 其一', '许乃普', '清代', '秋风一棹水云迟，日日船头理钓丝。间煞浣纱人未去，为君临水立多时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和琴坞耶溪渔唱绝句即题王椒畦图后 其一' AND p.poem_author = '许乃普';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('糖多令', '刘辰翁', '宋代', '日落紫霞洲。兰舟稳放流。玉虹仙、如在黄楼。何必锦袍吹玉笛，听欸乃、数声秋。 \n 赤壁舞涛头。周郎还到不。倚西风、袅袅余愁。唤起横江飞道士，来伴我、月中游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '糖多令' AND p.poem_author = '刘辰翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游四皓庙', '王禹偁', '宋代', '修篁瑟瑟石磷磷，去谒荒祠不厌频。\n四皓古来无事客，贰车今世最闲人。\n紫芝欲采非仙骨，红药曾题是近臣。\n一奠村醪还独酌，满轩松雪照吟身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游四皓庙' AND p.poem_author = '王禹偁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谒金门', '薛时雨', '清代', '春乍到。先被林莺知道。百啭声中天渐晓。喜争灵鹊报。\n\n梦里不知梦好。醒后却嫌醒早。门外落花呼婢扫。怕看春色老。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谒金门' AND p.poem_author = '薛时雨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岁暮怀梁园三子 其一 吴明卿', '黎民表', '明代', '瑶林挺荆楚，吴公秀无双。鸿逵振英响，鸡舌备周行。\n\n沈思运圆象，补衮回七襄。犹龙不可絷，歌凤仍猖狂。\n\n见客屡白眼，何人得升堂。再召异宣室，憔悴同浮湘。\n\n宇宙岂不廓，斯人日摧藏。梁园啜古泪，萧条洒烟霜。\n\n寤言觌璚树，怨彼河曲长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岁暮怀梁园三子 其一 吴明卿' AND p.poem_author = '黎民表';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感寓（二十首）', '王偁', '未知', '商君挟三术，西游诧秦君。\n上陈帝王略，邈矣宁见珍。\n《阳春》信寡和，《下俚》乃得亲。\n孔辙七十周，信哉无停轮。\n我有萦纡思，区区向谁陈？。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感寓（二十首）' AND p.poem_author = '王偁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('训蒙绝句 唤醒', '朱熹', '宋代', '为学常思唤此心，唤之能熟物难昏。才昏自觉中如失，猛省猛求明则存。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '训蒙绝句 唤醒' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('首春舟过采石', '释今严', '明代', '大江东向峙层峰，久向青莲觅旧踪。捉月亭空新绿草，骑鲸石在老青松。\n\n沙间唼喋将归雁，云际悠扬欲暮钟。心爱迟回身不得，唯期归路好从容。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '首春舟过采石' AND p.poem_author = '释今严';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵古梅', '苏泂', '宋代', '独立枝南万事非，岁寒引去合知几。\n伯夷自信西山饿，公望何须东海归。\n笛外数声空入梦，江头一树忽斜晖。\n相看有愧垂垂老，莫遣无端片片飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵古梅' AND p.poem_author = '苏泂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢司路钤遗菊花塔', '喻良能', '宋代', '夫君遗我菊浮屠，分得清香供读书。\n突兀便高三数尺，层层画影绿扶疏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢司路钤遗菊花塔' AND p.poem_author = '喻良能';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏慎火诗', '范筠', '南北朝', '兹卉信丛丛，微荣未足奇。何期糅香草，遂得绕花池。\n\n忘忧虽无用，止焰或有施。早得建章立，幸爇柏梁垂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏慎火诗' AND p.poem_author = '范筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日与诸文士息园宴集各赋一首', '顾璘', '明代', '上客东吴彦，芳樽脩竹林。飞觞催染翰，列炬耀华簪。\n\n蕉叶暮阴合，薇花秋序深。清言蔼群玉，雅义重兼金。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日与诸文士息园宴集各赋一首' AND p.poem_author = '顾璘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题万年妙莲阁', '王钦臣', '宋代', '石桥飞锡断遗踪，挥麈谈禅想旧丛。万萼莲新青嶂外，十围松老白云中。\n\n他年宴坐开华构，当日咨承拟顺风。岁晚丹丘如可约，杖藜相引欲烦公。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题万年妙莲阁' AND p.poem_author = '王钦臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九月二十六日同朝宗泽民游洞宫用刘使君韵二', '吴芾', '宋代', '云藏仙窟几何年，一旦来游岂偶然。\n造物应怜林下客，故令一睹洞中天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九月二十六日同朝宗泽民游洞宫用刘使君韵二' AND p.poem_author = '吴芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻范秀才自蜀游江湖', '杜牧', '唐代', '蜀道下湘渚，客帆应不迷。江分三峡响，山并九华齐。 \n 秋泊雁初宿，夜吟猿乍啼。归时慎行李，莫到石城西。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻范秀才自蜀游江湖' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('升仙桥', '汪遵', '唐代', '汉朝卿相尽风云，司马题桥众又闻。 \n 何事不如杨得意，解搜贤哲荐明君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '升仙桥' AND p.poem_author = '汪遵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辰阳待岳祠之命舟发武陵回寄从游诸公', '赵蕃', '宋代', '叔父同流元佑支，清贫远自相国时。\n旧闻河朔人伟奇，元衡笔力犹可窥。\n佳哉伯玉贤埙篪，小阮亦与竹林期。\n兆民虽云非旧知，知之正自梅花诗。\n伯寿憔悴儒冠衣，十年不调长苦饥。\n经明行修后所归，非吾光远其谁推。\n洪文学问方筑基，基成可保无倾欹。\n嗟我误落东南陲，疏者乃亲亲异宜。\n念我流转终年疲，去章已上归俟之。\n或持酒肴或赠辞，亦或眷眷江之湄。\n数面成亲还语离，前日之乐今日悲。\n秋风飒飒衣披披，山长水远属玉飞。\n高城望断日已西，望不可见令人思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辰阳待岳祠之命舟发武陵回寄从游诸公' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '车若水', '宋代', '江右文章今四叶，水心气脉近三台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '车若水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游石公山东连云障入剑楼', '王世贞', '明代', '地是排云上，天从破涧通。乍看双剑豁，不数五丁雄。\n\n一转成开辟，千寻接混融。竦身争鸟道，侧足瞰龙宫。\n\n鼍拥高低石，鲸嘘断续虹。张空帝子乐，叠浪大王风。\n\n响答歌增壮，尊扶力未穷。欲寻前相迹，明灭古苔中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游石公山东连云障入剑楼' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青玉案 其二 题王丹麓听松图', '徐釚', '清代', '谡谡涛声耳畔过。好梦北窗吹破。弄笛弹琴惟一个。\n\n枕流漱齿，科头濯足，片石堪趺坐。\n\n高披鹤氅烟霞堕。濯濯王恭还似么。手种龙鳞今已大。\n\n拂衣元亮，挂冠弘景，招与松间卧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青玉案 其二 题王丹麓听松图' AND p.poem_author = '徐釚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('慈恩寺东楼', '曹松', '唐代', '寺楼凉出竹，非与曲江赊。野火流穿苑，秦山叠入巴。 \n 风梢离众叶，岸角积虚沙。此地钟声近，令人思未涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '慈恩寺东楼' AND p.poem_author = '曹松';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵答应德茂雪后远寄', '戴表元', '宋代', '山中不来久，何处度残年。\n人闷如中酒，村荒似禁烟。\n将茶冰箸煮，移枕雪蓬眠。\n更肯狂歌否，春风双玉船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵答应德茂雪后远寄' AND p.poem_author = '戴表元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('骕骦骏', '杜牧', '唐代', '瑶池罢游宴，良乐委尘沙。遭遇不遭遇，盐车与鼓车。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '骕骦骏' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泛颍', '苏轼', '宋代', '我性喜临水，得颍意甚奇。\n到官十日来，九日河之湄。\n吏民笑相语，使君老而痴。\n使君实不痴，流水有令姿。\n绕郡十余里，不驶亦不迟。\n上流直而清，下流曲而漪。\n画船俯明镜，笑问汝为谁。\n忽然生鳞甲，乱我须与眉。\n散为百东坡，顷刻复在兹。\n此岂水薄相，与我相娱嬉。\n声色与臭味，颠倒眩小儿。\n等是儿戏物，水中少磷淄。\n赵陈两欧阳，同参天人师。\n观妙各有得，共赋泛颍诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泛颍' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('慈仁寺古松歌', '邵长蘅', '清代', '前年屡憩慈仁寺，古松苍翠流云气。高枝偃盖撑晴空。\n\n低枝攫拿捎厚地。青天忽诧蛟龙蟠，赤日只疑风雨至。\n\n今年重到慈仁来，苍皮惨裂枯干摧。一株已遭斤斧伐，一株仅存神郁屈。\n\n倔强尚与夔𩵅争，爱惜或愁雷雨拔。其余四株稍葱茜，青青翻是寻常质。\n\n我闻此松植自金元年，胡为摧折荒寒烟。摩挲三叹泪如缕，嗟尔托根原失所。\n\n慈仁寺中大作集，寺门日日飞尘土。珠玉锦绣走黄埃，日炙风霾气凄苦。\n\n孤根不免虫蚁穴，劲骨宁能驵侩伍。君不见庐山简寂观，高松千尺飘霜霰。\n\n白鹤两两巢其巅，仙人羽客时相见。又不见天台桥畔松，作鳞之而苍虬龙。\n\n银河倒挂玉淙淙，樵斤猎火何由篷。吁嗟乎！人生位置有如此，上马出门暮山紫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '慈仁寺古松歌' AND p.poem_author = '邵长蘅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('钓矶', '赵蕃', '宋代', '乐是烟波好，宁须竿线劳。\n功高殊钓渭，意适似游濠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '钓矶' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙 其二', '赵可', '金朝', '火冷薰炉香渐消。更阑拨火更重烧。愁心心字两俱焦。\n\n半世清狂无限事，一窗风月可怜宵。灯残花落梦无聊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙 其二' AND p.poem_author = '赵可';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('约圆机不至将出游鸡头山作二绝句', '晁说之', '宋代', '君知我亦有柴关，我岂输君独自闲。\n把笔何人凤尾诺，杖藜望我鸡头山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '约圆机不至将出游鸡头山作二绝句' AND p.poem_author = '晁说之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('甲子初春即事六首', '杨万里', '宋代', '骤暖如初复，通身退裌衣。\n只言寒已去，却等五更归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '甲子初春即事六首' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送僧之金陵', '释重顯', '宋代', '胜游生末迹，杳自狎时群。\n卷衲消寒木，扬帆寄断云。\n曙瓶花外汲，午磬浪边闻。\n别后石城月，依依远共分。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送僧之金陵' AND p.poem_author = '释重顯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('疏影 秋莲词人诣孤山观梅，词以纪之，予不得同游，次韵寄意', '陈衡恪', '近代', '西泠旧碧。引澹影缥缈，扶上双屐。十里疏花，天末遥看，眉边暗惹香泽。\n\n春风欲透琼肌软，似未惜、波寒江国。想夜来、雪意凄然，梦入水沉亭北。\n\n还问逋仙甚处，冷虹细蘸水，愁荡歌力。玉佩无声，鹤语盘空，那管飞鸥来历。\n\n苍茫目断扁舟路，恨不共、石湖吟笔。倚半床、斜月黄昏，起初满怀云阔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '疏影 秋莲词人诣孤山观梅，词以纪之，予不得同游，次韵寄意' AND p.poem_author = '陈衡恪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陶斋属题欧人水画册子', '郑孝胥', '清代', '峰能射日涧能幽，云自行空海自流。见画众宾心惊倒，樽前敢请话前游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陶斋属题欧人水画册子' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九月一日戴时可', '陈著', '宋代', '老夫不是不知时，黄菊芙蓉正要诗。谁信多魔儿女病，催租风雨又攒眉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九月一日戴时可' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史', '陈普', '宋代', '东宫无德倚仪刑，又似当年傅建成。可笑郑公如百舌，春前夏后两般声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史' AND p.poem_author = '陈普';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('去秋承王希颜自赣归舟经白沙祠有诗相忆比会延真约以卜邻江上兹春寻往闻又复西上矣赋诗一首奉寄并答往怀', '刘崧', '明代', '承闻初出赣滩时，千里风波有所思。卜宅重寻流水坂，舣舟还访白沙祠。\n\n鹿门隐去柴车在，秦谷归来木镵随。海内故人零落尽，白头相见不胜悲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '去秋承王希颜自赣归舟经白沙祠有诗相忆比会延真约以卜邻江上兹春寻往闻又复西上矣赋诗一首奉寄并答往怀' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感遇诗三十八首 其八', '陈子昂', '唐代', '吾观昆崙化，日月沦洞冥。精魄相交会，天壤以罗生。\n\n仲尼推太极，老聃贵窈冥。西方金仙子，崇义乃无明。\n\n空色皆寂灭，缘业定何成。名教信纷藉，死生俱未停。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感遇诗三十八首 其八' AND p.poem_author = '陈子昂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春霁', '高翥', '宋代', '积雪才收云尽归，长空一色碧琉璃。\n日移帘影临书案，风飐瓶花落研池。\n巢燕学飞犹恋母，笼鸡得食旋呼儿。\n眼看景物关情甚，喜为新晴赋此诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春霁' AND p.poem_author = '高翥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('幽居感怀寄满子权', '王令', '宋代', '卜得幽居四绝邻，寻常庭巷断蹄输。\n门前犬豕卧横道，城上牛羊下视人。\n满眼夕阳闲草树，回头归路正埃尘。\n思君未有东来计，何日双眉对面伸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '幽居感怀寄满子权' AND p.poem_author = '王令';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·夜久笙箫吹彻', '赵长卿', '宋代', '夜久笙箫吹彻，更深星斗还稀。醉拈裙带写新诗。锁窗风露，烛灺月明时。水调悠扬声美，幽情彼此心知。古香烟断彩云归。满倾蕉叶，齐唱传花枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·夜久笙箫吹彻' AND p.poem_author = '赵长卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('理安寺', '弘历', '清代', '路尽九溪十八涧，境奇三竺两高峰。香台听讲来驯鸽，静室安禅制毒龙。\n\n法雨淙常空色相，岩花放不论春冬。归鞭却恐留清恋，倩取白云一片封。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '理安寺' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泛舟城南二首 其二', '刘攽', '宋代', '风逆湍声急，云酣雨气豪。川蜺垂饮近，江鹤去飞高。\n\n洗藕还馀味，操舟未觉劳。蒹葭弥极望，秋意晚骚骚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泛舟城南二首 其二' AND p.poem_author = '刘攽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送悟大师重造金刚', '释慧空', '宋代', '八大金刚常住世，护佛正法令久住。精蓝金刚相先坏，欲令正法住为难。\n\n悟禅致力扶正法，故先成此金刚王。老僧嘉悟善用心，说偈赞其令速办。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送悟大师重造金刚' AND p.poem_author = '释慧空';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望云庵为林提学题用素翁韵 其一', '邵宝', '明代', '白石山前云气深，有时飞起有时沈。太行顶上南回首，千里慈闱隔岁心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望云庵为林提学题用素翁韵 其一' AND p.poem_author = '邵宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('呈辛稼轩 其四', '刘过', '宋代', '卧庐人昔如龙起，鼎足魏吴如等閒。若结梅花为保社，林逋只合住孤山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '呈辛稼轩 其四' AND p.poem_author = '刘过';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送王学士赴两浙转运', '欧阳修', '宋代', '汉家财利析秋毫，暂屈清才岂足劳。\n邑屋连云盈万井，舳舻衔尾列千艘。\n春寒欲尽黄梅雨，海浪高翻白鹭涛。\n平昔壮心今在否，江山犹得助诗豪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送王学士赴两浙转运' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('家居自戒', '陆游', '宋代', '饥寒陷侵暴，其实可怜伤。\n一事百自反，忿心冷如霜。\n恕物学者心，省事虑亦长。\n吾过固多矣，责彼何暇详！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '家居自戒' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('随□家大人过净公吉林兰若', '杨宾', '清代', '南极开初地，西方变吉林。山围祇树密，江到寺门深。\n\n雪白支公马，沙黄长者金。冰崖仙梵响，土室雨花侵。\n\n学礼陪游从，闻香度碧岑。赞公甘放逐，惠远爱招寻。\n\n茶椀忘天目，清谈见道心。金篦如不惜，敢复叹升沈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '随□家大人过净公吉林兰若' AND p.poem_author = '杨宾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏赠陆兄', '王世贞', '明代', '见汝佳公子，俄然双鬓华。有家不解问，欲问已无家。\n\n鞭巷一壶酒，弇园千树花。应门如不却，老去足生涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏赠陆兄' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过扬州忆昔四首 其四', '袁桷', '元代', '四城赋拟张衡丽，十鉴书同贾谊哀。腹里春秋纳云梦，案头今古起风雷。\n\n青山不受折腰辱，白眼岂知徒步回。舟泊城南更回首，寒风吹泪下天台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过扬州忆昔四首 其四' AND p.poem_author = '袁桷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('内题赋得巫山雨（一作沈佺期诗。题云巫山高）', '宋之问', '唐代', '神女向高唐，巫山下夕阳。裴回作行雨，婉恋逐荆王。 \n 电影江前落，雷声峡外长。霁云无处所，台馆晓苍苍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '内题赋得巫山雨（一作沈佺期诗。题云巫山高）' AND p.poem_author = '宋之问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('效阮公咏怀 其二十三', '薛蕙', '明代', '昔闻黄灵乐，乃在洞庭傍。一奏鱼愁入，再奏鸟悲翔。\n\n大声岂不妙，细物焉能当。独有双玄鹤，延颈遥相望。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '效阮公咏怀 其二十三' AND p.poem_author = '薛蕙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂十八首', '释如净', '宋代', '者个是百尺竿头，进一步则有象，\n退一步则无踪。进退全机变，\n从衡振祖风。都在南山掌握中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂十八首' AND p.poem_author = '释如净';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('布袋赞', '释子益', '宋代', '布袋横拖，肚皮捺下。\n行货有些，没人酬价。\n拊背觅钱真奉化。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '布袋赞' AND p.poem_author = '释子益';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蒋别驾芝冈招同费使怀谷载孝廉闇成上舍光林游陆氏水木明瑟园二首 其一', '严遂成', '清代', '十亩无多地，到来如许宽。池深鱼气静，树密鸟声欢。\n\n浅碧浸琴荐，轻阴护药栏。小长庐去后，山翠至今寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蒋别驾芝冈招同费使怀谷载孝廉闇成上舍光林游陆氏水木明瑟园二首 其一' AND p.poem_author = '严遂成';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵雪寒郡中粜米食源有赋', '高斯得', '宋代', '父兮儿饥母兮寒，瓶中无粟囊无钱。\n天公何不知人苦，狞风裂肤雪塞户。\n我来日月虽未多，舛令已干天谴呵。\n医疮眼下尚无药，更有妙诀瘳沉疴。\n拔贫为富非不窘，坐视沟瘠吾何忍。\n长民要识天之天，此事前人固加谨。\n我仓我庾虽甚枵，且须倾空苏瘵凋。\n惭无大德与汝曹，聊以小惠为宽条。\n何时公私俱露积，慰我片片心事赤。\n圩丰食可接青黄，盗弭丸无探赤白。\n老夫藉手得归田，免讥取禾三百廛。\n君诗太夸不可传，吾恐闻者讥贪天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵雪寒郡中粜米食源有赋' AND p.poem_author = '高斯得';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏古 其三', '屈大均', '明代', '皋氏春边客，曾无赠妇篇。风流惟举案，留与后人传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏古 其三' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新寺和张仲举兼次韵', '丁复', '元代', '天宫兜率下崔嵬，结绮交疏面面开。地势周围龙虎国，钟声疏应凤凰台。\n\n鼎湖仙去秋遗剑，笠泽僧归夜渡杯。千骑巡街群乐动，五云深处御香来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新寺和张仲举兼次韵' AND p.poem_author = '丁复';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('独坐', '胡云飞', '当代', '造化感我真，遗我以孤寂。万籁俱歇后，悄然来胸臆。\n\n如雪花飐水，如轻尘触石。宛然百骸脱，忽复当时忆。\n\n闲过长安道，扶碑寻残碧。扬沙及垂云，茫茫动八极。\n\n风从天上来，使我无处匿。悲欣遽未名，中肠结不息。\n\n斯感如重生，此际犹夙昔。起视月泠泠，亘古照空壁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '独坐' AND p.poem_author = '胡云飞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自题东园诗草', '徐汉倬', '清代', '微风北窗来，羲皇对床席。陶公有凉音，饥寒实驱迫。\n\n作者代有人，东皋起王绩。醉乡日高枕，逸气出秋壁。\n\n岂惟屏淫哇，亦复黜嘄噭。征事多滞响，写景饶秀色。\n\n蒸蔚为云霞，郁勃走霹雳。声诗与乐通，由瑟圣所饬。\n\n盛唐李杜兴，万象尽开辟。可怜千载下，何处弄笔墨。\n\n吾生竟何事，弱毫叹孤植。如游空山阿，寒溜冻幽石。\n\n腊尽春渐苏，冰雪滴余沥。遂成一脉水，中涵小天碧。\n\n遥见鲸鱼归，复何能为役。远海生波澜，蛟龙有窟宅。\n\n风涛中澒洞，乃万怪惶惑。落日收钓纶，回舟傍芦荻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自题东园诗草' AND p.poem_author = '徐汉倬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿邵阳唐倅二首 其一', '廖行之', '宋代', '君不见大士化身兜率天，地涌两足双金莲。光明照耀十方界，至今犹记周昭年。\n\n当年刹利西王国，才见薰风入炎日。菩提广转大法轮，普现宝身千百亿。\n\n即今应感湘江涯，一念甫为群生迷。诞弥犹是旧来日，尘世已觉心南移。\n\n宰官未向朝端去，暂作资阳大慈父。惟将四谛妙真来，一洗含灵愁叹苦。\n\n海沂岂久淹王祥，沙堤指日催鸣珰。心华定力莫思议，福利四海为津梁。\n\n斯民正赖觉空觉，应世因缘讵能度。椿龄永劫未渠央，会看优昙几开落。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿邵阳唐倅二首 其一' AND p.poem_author = '廖行之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('巾子峰', '杨蟠', '宋代', '首出群山内，晴窗几处看。\n不因风雨折，开槛满溪寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '巾子峰' AND p.poem_author = '杨蟠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('捲帘', '张耒', '宋代', '捲帘新月上，林影散微茫。庭草鸣虫近，风灯秋幌凉。\n\n长年惟有病，晚岁苦多伤。身世竟何就，吾将问蜀庄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '捲帘' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自题竹石栖禽图二首', '金鉴才', '当代', '枝间微雨做新春，讶道深山沸俗尘。流水无声飞鸟绝，更从何处著吟身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自题竹石栖禽图二首' AND p.poem_author = '金鉴才';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('城南新堂燕集饯送江明府先生', '符锡', '明代', '西风江渚罢鸣琴，报政难留去客心。乡士何困逢盛饯，宰君其敢望重临。\n\n□堂尊俎明秋月，嘉会衣冠侈上林。为向南云早鸿道，春明还许嗣徽音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '城南新堂燕集饯送江明府先生' AND p.poem_author = '符锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游九锁 其二', '刘应子', '宋代', '忆昔梦中游，高怀怅冥邈。箯舆入山来，精爽欲飞跃。\n\n九锁相回环，群峰俱卓荦。地胜幻蓬莱，天低眇嵩岳。\n\n古道矗危亭，断涧横略彴。流泉翠蛟舞，怪石紫鳞错。\n\n坡仙不可见，墨香俨犹昨。迤逦跨五洞，解衣小盘礴。\n\n烟萝蔓千树，风松鼓万壑。元放时往来，仙家有真乐。\n\n石鼓叩即鸣，乳泉甘比酪。对此黄花秋，风景良不恶。\n\n更欲穷绝顶，不惮疲两脚。谢屐随纵横，嘉帽任落魄。\n\n回首日已晡，空山唳猿鹤。羽衣坐玄石，呼茗待佳客。\n\n拂弦写秋声，洗盏营晚酌。诗成走风雨，鬼神亦惊愕。\n\n何时了功名，来寻赤松约。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游九锁 其二' AND p.poem_author = '刘应子';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杨花', '华岳', '宋代', '一丝不染湖光白，万点能回山色青。\n三月金明池上水，与予同是一浮萍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杨花' AND p.poem_author = '华岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('马生辞予至广常厄而归再此赠别', '王弘诲', '明代', '风波世路尽堪惊，去矣重回百感萦。空有绨袍怜范叔，谁将白璧赠虞卿。\n\n艰危历试犹存舌，去往相关不尽情。世事茫茫那可料，匣中风雨自悲鸣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '马生辞予至广常厄而归再此赠别' AND p.poem_author = '王弘诲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江行无题一百首 其一○○', '钱珝', '唐代', '远谪岁时晏，暮江风雨寒。仍愁系舟处，惊梦近长滩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江行无题一百首 其一○○' AND p.poem_author = '钱珝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐', '吴山', '明代', '秋光如许，雁字排空去。十二阑干凝眺处，帘卷西山暮雨。\n\n白沙翠竹柴门，落霞孤鹜江村。况是亭皋叶下，萧萧最怆吟魂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐' AND p.poem_author = '吴山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟李白古风 其四', '李坚（贞夫）', '明代', '志士怀当世，众人谋一身。志士惧来日，众人惜今晨。\n\n讵知当世安，未为一身贫。盖棺苟遗臭，生前奚足珍。\n\n所以首阳薇，万古扶彝伦。不见上蔡吠，瞥眼成烟尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟李白古风 其四' AND p.poem_author = '李坚（贞夫）';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长安旅宿', '钱起', '唐代', '九秋旅夜长，万感何时歇。蕙花渐寒暮，心事犹楚越。 \n 直躬邅世道，咫步隔天阙。每闻长乐钟，载泣灵台月。 \n 明旦北门外，归途堪白发。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长安旅宿' AND p.poem_author = '钱起';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('石头城', '丁裔沆', '清代', '君不见龙骧将军意气豪，连帆战舰明珠袍。雄师八万挂席进，角声吹断黄云高。\n\n鸾旗半卷青山里，鱼龙悲咽秋江水。自将玉篆付官家，不遣将军折一矢。\n\n赤乌事业不崇朝，尽逐东风散怒涛。横江振旅铙歌发，白发将军看宝刀。\n\n寄语横行且复休，孙郎战骨随蒿丘。当年割据山河壮，谁道降帆下石头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '石头城' AND p.poem_author = '丁裔沆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟古宫词一百首 其七十九', '邓云霄', '明代', '御堤南望草萋萋，一半花香落燕泥。玉辇不来春又暮，谁云桃李易成蹊？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟古宫词一百首 其七十九' AND p.poem_author = '邓云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('海上凯歌九首赠汤将军 其二', '唐顺之', '明代', '纷纷盗窃尔何知，岸上斫人水上嬉。自咤一身都是胆，欲将巨海作潢池。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '海上凯歌九首赠汤将军 其二' AND p.poem_author = '唐顺之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨中闻吴外翰解任因赋赠别', '陶益', '明代', '梦残鼓角雨濛濛，何事青衿怨别同。罢卜三鳣一相送，春风回首绿阴丛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨中闻吴外翰解任因赋赠别' AND p.poem_author = '陶益';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绵州巴歌', '佚名', '魏晋', '豆子山，打瓦鼓。扬平山，撒白雨。\n下白雨，取龙女。织得绢，二丈五。\n一半属罗江，一半属玄武。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绵州巴歌' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('落花篇', '林应亮', '明代', '东邻昨夜飞红雨，落花如霰随风举。\n千丛缀绮谢繁枝，九陌垂青隐芳树。\n忆昨芳妍乍放时，含娟凝艳骋容姿。\n盈盈绛帻承曦暖，烨烨瑶英泛露滋。\n地拟昆溟霞作幄，门连阊阖玉雕题。\n昆溟阊阖非人境，喜得繁华荐清景。\n共讶同心照日开，坐怜并蒂临风整。\n鸣弦伐鼓斗春菲，列彩飞觞延昼永。\n为君催晓下朱楼，为君欢燕淹华省。\n华省朱楼春昼迟，雕栏色色自称奇。\n蝶翅轻穿翡翠筠，龙柯误触秋千丝。\n名园岂辨烟和树，名卉难分菌与芝。\n名园名卉色非一，夺目瑶华纷转日。\n总多富贵卫张门，不让风流王谢室。\n风流富贵擅谁家，照耀纵横本自夸。\n别有仙葩吐仙种，疑从琼岛泛琼华。\n绿畹斜攒珠蕊树，玉盘遥挂赤城花。\n万斛香中贮甘露，五云芝上护流霞。\n霞飞露染春光暮，东邻远客西邻戍。\n鸾镜佳人愁里看，雁门征客暗中度。\n此情难语北征人，此情偏入东家妇。\n百啭莺呼作怨声，一叶花飞减妆素。\n莺花岁暗可重新，节物朝来已非故。\n簇陌游丝逐飙空，垂堤空梗向流东。\n含香故弄妆台上，袭暖偏留舞袖中。\n含香袭暖竟何处，乍入东墙复西署。\n悠扬未识飘零归，寂历如随风雨去。\n乍惊叶萼忽辞丛，何况飘廊兼委路。\n随蓬不恋故根春，冲燕宁知托巢羽。\n梧桐井畔映光寒，桃李蹊阴暮色阑。\n蟋蟀机残催锦字，凤凰楼迥乏青鸾。\n青鸾锦字总迢绝，见此令人心欲折。\n败叶逢君可赠题，孤条感妾能生檗。\n掇叶攀条聊自持，回簪转黛顾容仪。\n茱萸锦上红尘恨，杨柳声中玉笛悲。\n三千图画怜芳迹，十二阑干凋翠眉。\n青苔忍诵蘼芜调，红树曾题芍药诗。\n题诗欲寄远行客，春风相忆故园陌。\n瑶池千岁始重看，锦瑟三春勿轻掷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '落花篇' AND p.poem_author = '林应亮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西湖竹枝词四首 其三', '钱惟善', '元代', '日暮天寒野水滨，孤山愁绝四无邻。谁家处子如冰雪，行傍梅花不见人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西湖竹枝词四首 其三' AND p.poem_author = '钱惟善';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游罗氏园池', '黎民表', '明代', '芳园穷落日，山水有馀欢。早岁知怀橘，清秋共握兰。\n\n风烟向浦尽，花木隔池看。为恋幽岩桂，尘冠且未弹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游罗氏园池' AND p.poem_author = '黎民表';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('盘谷寺恭依皇祖圣祖仁皇帝元韵', '弘历', '清代', '时巡行夏令，秋稔赖天恩。式阅田盘处，言瞻法海门。\n\n璇题今尚焕，钗脚古称尊。敬识当年意，丰碑镇厚坤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '盘谷寺恭依皇祖圣祖仁皇帝元韵' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('续𢅸 其二 习舞', '杨维桢', '元代', '《十六天魔》教已成，背反莲掌苦嫌生。夜深不管排场歇，尚向灯前踏影行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '续𢅸 其二 习舞' AND p.poem_author = '杨维桢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿雷峰天然禅师', '陈恭尹', '明代', '孤高如月万方看，至道无言仰颂难。垂老尚闻勤梵行，太平先已薄儒官。\n\n身为硕果时方剥，书满名山墨未乾。曾住朱明洞天上，仙人不敢爱还丹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿雷峰天然禅师' AND p.poem_author = '陈恭尹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辰玉应试留都赋此赠之兼赠孟孺 其二', '王世贞', '明代', '棘日垂没际，秋榜将放时。要须觅真我，勿述未波驰。\n\n一番煅炼过，大道将庶几。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辰玉应试留都赋此赠之兼赠孟孺 其二' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄旷知事伯逵四首 其三', '刘崧', '明代', '闻说移居地，还依孺子亭。对门湖共白，一路柳长青。\n\n仕已沾恩露，庭应聚德星。谁能远车马，况不异郊坰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄旷知事伯逵四首 其三' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送安头陀还兰阴作同少傅公四首 其二', '胡应麟', '明代', '百丈金身照绿苔，青莲璎珞护瑶台。天龙一指犹堪竖，莫诧西方大士来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送安头陀还兰阴作同少傅公四首 其二' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和进之壬戌雪中作', '顾清', '明代', '冰柱谁家长万尺，世人未见神仙宅。昆崙五城楼十二，一一银山半天白。\n\n天河倒挂楹栋间，下视蓬婆等卷石。东方有士古袁安，平生自信干人难。\n\n闭门僵卧三日雪，早起翻念神仙寒。书生未试多濩落，此事几为流俗叹。\n\n草堂相对一尊酒，龙公水妃互奔走。须臾瀰漫天地变，崖堑区区复何有。\n\n瓦沟何恨太飘忽，桧顶何亲独淹久。从来幸不分町畦，此日宁须问容受。\n\n晚来笔冻可柰何，满庭落叶寒风多。嫦娥矫立碧云里，似欲斗彩撩清哦。\n\n我今有诗亦不作，此雪讵堪还更落。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和进之壬戌雪中作' AND p.poem_author = '顾清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵和江子我道中绝句七首', '程俱', '宋代', '云关深掩裂荷衣，却著青衫扈六飞。雁荡峰前瞻使节，一星还旁紫垣归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵和江子我道中绝句七首' AND p.poem_author = '程俱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送尹兵曹擢河间守', '皇甫汸', '明代', '闻君初解尚书郎，出守雄邦迩帝乡。命下不殊冯翊诏，腰间争似会稽章。\n\n食前借箸筹多中，地上成图料已长。莫道宛王将献马，防秋日夜念遥疆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送尹兵曹擢河间守' AND p.poem_author = '皇甫汸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏作次药名十首 其六', '胡俨', '明代', '蚯蚓结来成百合，海羊斗处即蜗牛。莫认夏枯为益母，须知萱草解忘忧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏作次药名十首 其六' AND p.poem_author = '胡俨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杜少陵', '程滨', '当代', '诗胆悬天地，春心返澒蒙。杖藜回首白，泣血迸空红。\n\n鲸落银潢底，星沉碧海中。残膏真不朽，千载丐吾宗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杜少陵' AND p.poem_author = '程滨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春暮思平泉杂咏二十首。西园', '李德裕', '唐代', '西园最多趣，永日自忘归。石濑流清浅，风岑澹翠微。 \n 晓翻红药艳，晴袅碧潭辉。独望娟娟月，宵分半掩扉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春暮思平泉杂咏二十首。西园' AND p.poem_author = '李德裕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜马参军相遇醉歌', '陈子昂', '唐代', '独幽默以三月兮，深林潜居。时岁忽兮，孤愤遐吟。 \n 谁知我心？孺子孺子，其可与理分。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜马参军相遇醉歌' AND p.poem_author = '陈子昂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('彭城河复', '弘历', '清代', '苏公河复昔非复，彭城河复今仍河。仍河何以谓之复，解嘲聊尔为斯歌。\n\n汉唐以来通钜野，烧草不属无如何。侵淫吕沛渐多事，川狭涛怒腾盘涡。\n\n然惟宜合不宜散，合资刷沙离渟波。斯流虽古有成语，徒见其害利则那。\n\n去岁夺溜孙家集，中泓力缓沙淤多。堤旁水志度分寸，泥停五尺高益加。\n\n桃汛汤汤已拍岸，伏秋转眼难延俄。用是切切愁弗置，纡程历览亲研摩。\n\n下策仍惟事脩筑，易石巩固周遮罗。水工喜称渐复旧，数日顿尔形迁讹。\n\n三尺沙刷馀二尺，志在敢饰虚言詑。此亦偶然慢过颂，灵实昭矣感不磨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '彭城河复' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题《牡丹亭记》二首 其二', '胡雪抱', '近代', '刹刹尘尘百劫遒，他生福倩此生修。花原偶现悲留影，石未全顽冀点头。\n\n碧落寒空何事雨，红灯小穗若为愁。鲜妍一种伤心事，付与云鬟次第讴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题《牡丹亭记》二首 其二' AND p.poem_author = '胡雪抱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆江南', '释函可', '明代', '江南高座寺，前对雨花台。台上春风拂面来，参差杨柳花竞开。\n\n黄莺百啭我心哀，忽忆故山村底梅。今年绝漠冰雪堆，发白面皱骨欲摧。\n\n村底无梅不归去，却忆高座听莺语。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆江南' AND p.poem_author = '释函可';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饮颜质卿斋头限韵赋同潘去华 其二', '袁宗道', '明代', '震旦同参少，长安雅聚难。因君道眼别，令我酒怀宽。\n\n匡坐藤蒲静，幽谈水月寒。好将瞿氏说，留付子庸看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饮颜质卿斋头限韵赋同潘去华 其二' AND p.poem_author = '袁宗道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('踏莎行 干友打斧', '王哲', '元代', '片釜如求，那由选拣。良工欲造无钱换。今朝专礼我华宗，慈悲为首诸公办。若得坚钢，劈开道眼。灵台＊耀持金简。腰间柯烂决忘归，白云', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '踏莎行 干友打斧' AND p.poem_author = '王哲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('莺鸣十章寄戚伯瑞', '彭龟年', '宋代', '日升于东，月生于西。\n惟神之驰，曾莫知所之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '莺鸣十章寄戚伯瑞' AND p.poem_author = '彭龟年';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('邹滕道中喜连日密云细雨', '郭之奇', '明代', '始见青山色，依依向远人。炎光能稍逊，景物倍堪亲。\n\n悦性开蝉籁，披襟动客神。堤花垂晓露，归色尚疑春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '邹滕道中喜连日密云细雨' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和乘雪游山韵', '王柏', '宋代', '肃然穷巷冻堆堆，高卧袁生梦正回。\n拥鼻微吟烧榾柮，茅柴也荐两三杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和乘雪游山韵' AND p.poem_author = '王柏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病怀', '丁元照', '清代', '寒虫秋不死，牖下作悲吟。戚极宵难寐，愁多病易深。\n\n残灯孤枕泪，长夜百年心。欲侍双亲去，重泉何处寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病怀' AND p.poem_author = '丁元照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵元功才友道中见贶因以解嘲', '张元干', '宋代', '当时勇决径归休，更有人愚似我不。何许置锥宁免累，直须毕娶始无忧。\n\n频遭白眼伤流俗，谁向青门念故侯。客里题诗相慰藉，羡君椽笔合螭头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵元功才友道中见贶因以解嘲' AND p.poem_author = '张元干';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('曲游春', '熊盛元', '当代', '梦断桃源渡，怅小舟仍系，烟外荒驿。冷月疏星，问何人重与，醉边吹笛？\n\n四野音尘寂。自徙倚、旧时岩隙。甚草根、屐印都消，惟见泪痕凝碧？\n\n暗忆，三生行迹。任花雨轻飘，襟底香湿。杯酒孤斟，向虹桥弄影，蜃楼摇楫。\n\n空际谁弹瑟？恨惝恍、湘灵难觅。但水云、浩渺无垠，古愁乱织。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '曲游春' AND p.poem_author = '熊盛元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汴水呈祖道', '彭汝砺', '宋代', '万事无庸轻是非，扁舟吾与子同归。不知心逐征云远，安得身先去鸟飞。\n\n月入江湖生夜色，风吹花木长春晖。鬓毛每笑多新雪，衣带频惊缓旧围。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汴水呈祖道' AND p.poem_author = '彭汝砺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('复用迟字韵呈元亮', '李彭', '宋代', '去日关河雪打围，缝裳密密恐归迟。忽看高笋成筠处，始见残樽下马时。\n\n暮雨萧萧聊洗恨，东园物物总宜诗。莫言心赏随年薄，勤赴幽人林下期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '复用迟字韵呈元亮' AND p.poem_author = '李彭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别何古林八首 其七', '王渐逵', '明代', '四郊风景自村家，春入林塘净晚霞。月落尊空人醉后，几多离思付桃花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别何古林八首 其七' AND p.poem_author = '王渐逵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('代柬辞友人召 其一', '区元晋', '明代', '霏霏霭翠竹琅玕，一味新凉协肺肝。试问剥芋烹茗碗，何如江上弄渔竿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '代柬辞友人召 其一' AND p.poem_author = '区元晋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('富仙', '徐积', '宋代', '碧霞楼上常先晓，白玉宫中爱早寒。乱玉甃成池浴凤，浑金削就栋栖鸾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '富仙' AND p.poem_author = '徐积';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('移竹诗伯封垂和且闻兄弟皆欲作因用元韵奉寄 其二', '李洪', '宋代', '密密脩篁入槛寒，君来移取出檐竿。结根久近幽人屋，解箨宜为壮士冠。\n\n曾共马兰同请客，不忧苜蓿但堆盘。从今莫羡萧郎画，风月良宵仔细看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '移竹诗伯封垂和且闻兄弟皆欲作因用元韵奉寄 其二' AND p.poem_author = '李洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书叹四首 其三', '林占梅', '清代', '雌黄轻肆祸之根，守口如瓶舌且扪。雅量面甘师德唾，恃才命不祢衡存。\n\n欲舒积懑唯长啸，纵有微词敢大言。棒喝从兹知猛省，幽□日日闭柴门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书叹四首 其三' AND p.poem_author = '林占梅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出京', '皇甫汸', '明代', '晓叩天关别禁墀，秋深江路是归期。谈经王式重来误，薄宦潘生屡出宜。\n\n汉室朱颜翻见嫉，梁园白首未相知。此身去就何曾系，一似浮云任所之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出京' AND p.poem_author = '皇甫汸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送周学士归永嘉', '胡宿', '宋代', '三最初承予告恩，一双青翰出都门。关繻旧弃人多识，桥柱前题墨未昏。\n\n南国归云聊送目，河梁新月暂消魂。玉山丹府重来日，好拾风谣奏帝阍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送周学士归永嘉' AND p.poem_author = '胡宿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('当安台新福歌一首', '黄省曾', '明代', '诛胡灭汉，雪耻除凶。作乐兮赫赫扬奇功。左秉戚，右执龙。\n\n发以扬，在宫中。黄金束，气何雄。万载常雍雍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '当安台新福歌一首' AND p.poem_author = '黄省曾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绝句', '欧阳鈇', '宋代', '桑麻得雨更青葱，芍药留春结晚红。\n怪得鸟声如许好，此身还在乱山中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绝句' AND p.poem_author = '欧阳鈇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与从弟瑾同下第后出关言别', '卢纶', '唐代', '同作金门献赋人，二年悲见故园春。 \n 到阙不沾新雨露，还家空带旧风尘。 \n 杂花飞尽柳阴阴，官路逶迤绿草深。 \n 对酒已成千里客，望山空寄两乡心。 \n 出关愁暮一沾裳，满野蓬生古战场。 \n 孤村树色昏残雨，远寺钟声带夕阳。 \n 谁怜苦志已三冬，却欲躬耕学老农。 \n 流水白云寻不尽，期君何处得相逢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与从弟瑾同下第后出关言别' AND p.poem_author = '卢纶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐二首 其一', '王时翔', '清代', '盈头花草。又见双文了。说道今朝天气好。斜倚画阑浓笑。\n\n多情谁似东风。飘然直度帘栊。吹出几重衫影，淡黄轻绿殷红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐二首 其一' AND p.poem_author = '王时翔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵卢监', '方岳', '宋代', '兰亭人寂几何年，着我糟丘亦冗员。\n寻访雪溪无酒债，主张禊帖有诗权。\n千岩秀处书如堵，五月凉时藕似船。\n只麽折浮真足矣，底须妄想到花边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵卢监' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟中和子翼雪茶', '林光', '明代', '玉碗閒挥拨玉尘，梅花烹就腊前春。龙团点化元无滓，沆瀣餐来更迫真。\n\n铁鼎青烟回别鹤，瓦瓯元酒劝何人。云山傥入周南梦，更话云山未了湮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟中和子翼雪茶' AND p.poem_author = '林光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绍兴祀岳镇海渎四十三首', '佚名', '隋代', '维吴崇崇，于汧之西。\n瞻彼有龙，赫赫不迷。\n克裨于岳，我酌俶齐。\n于凡有旅，眡公维跻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绍兴祀岳镇海渎四十三首' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感事', '郭钰', '元代', '荆徐千里混干戈，日日君王候凯歌。上相出师三月罢，南人待援六年过。\n\n未休练卒诛求尽，暂脱归囚反侧多。独拜将坛须国士，抡材谁似汉萧何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感事' AND p.poem_author = '郭钰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('海上题南社雅集写真', '柳亚子', '近代', '鸡鸣风雨故人稀，几、复风流事已非。\n回首天涯唯汝在，相逢朱、沈倍依依。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '海上题南社雅集写真' AND p.poem_author = '柳亚子';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('旅兴（四十首）', '刘基', '明代', '秋高潦水涸，旻天亦凄清。\n枯箨响悲音，羁虫振余声。\n曀曀落日晖，惨惨游子情。\n风林无定枝，驰车鲜安旌。\n自愧匪贤达，默默嗟其生。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '旅兴（四十首）' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赞历代天师·第二十八代讳敦复字延之', '白玉蟾', '宋代', '棘围战罢笑归来，一寸功名心已灰。\n白鹤何年归洞府，夕阳影里野猿哀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赞历代天师·第二十八代讳敦复字延之' AND p.poem_author = '白玉蟾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百零三首 其八', '释月涧', '宋代', '即心即佛，狐狸恋窟。非心非佛，当机放出辽天鹘。\n\n马大师等闲向虚空里抛个题目，经今五七百年，更无一人描写得著。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百零三首 其八' AND p.poem_author = '释月涧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奏事入都出西湖上成四绝 其一 西湖', '王炎', '宋代', '呼舟特地度西湖，欲访山中幽子居。山色湖光浑似旧，人间万事有乘除。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奏事入都出西湖上成四绝 其一 西湖' AND p.poem_author = '王炎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乙未春尽日始见白发一茎感赋', '夏孙桐', '清代', '索居风雨送流光，揽镜惊看鬓上霜。自笑春婆迟梦醒，浪从漆室说心长。\n\n生涯蟫蠹当随分，吾道龙蛇亦有方。今日落花禅榻畔，罪言焚尽减清狂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乙未春尽日始见白发一茎感赋' AND p.poem_author = '夏孙桐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴兴寄庞镇卿京兆', '李时行', '明代', '燕郊斗酒忆论文，白下音书久未闻。海色暗浮吴苑树，星光虚映霅川云。\n\n心随北极瞻龙驭，目断西风数雁群。一自山中丛桂发，秋来无日不思君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴兴寄庞镇卿京兆' AND p.poem_author = '李时行';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七言诗', '繁钦', '魏晋', '阴云起兮白雪飘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七言诗' AND p.poem_author = '繁钦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送姜彦英还钱塘二首 其一', '郭奎', '明代', '浮云敛沉晦，白日扬光晖。条风扇首岁，念子行将归。\n\n山水淡馀霭，草木含清晖。谁谓道路远，去矣趋庭闱。\n\n伯氏既吹埙，仲氏和以篪。譬彼棠棣花，枝叶相因依。\n\n愿言崇孝友，百岁恒不违。安得黄鹤羽，及尔俱南飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送姜彦英还钱塘二首 其一' AND p.poem_author = '郭奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('延庆寺', '王岩叟', '宋代', '龙影函潭寺已空，惟馀翠竹混青松。路穷西北无他景。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '延庆寺' AND p.poem_author = '王岩叟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泛舟至东村', '陆游', '宋代', '野水如天远，渔舟似叶轻。\n飕飕风渐冷，淡淡月初生。\n沙际樵苏路，篱间语笑声。\n还家已薄暮，灯火照柴荆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泛舟至东村' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青溪 其二', '屈大均', '明代', '胭脂井里殉君王，花作陈宫二女香。谁道小姑人不识，美人张孔两鸳鸯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青溪 其二' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和周次玉除夕', '柯潜', '明代', '鸭炉香烬酒微消，笑引诗魔伴寂寥。漏滴寒声催五夜，天回和气入三朝。\n\n玉堂冷署閒烹雪，水部高才醉颂椒。明发趋朝陪御宴，同歌湛露听云韶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和周次玉除夕' AND p.poem_author = '柯潜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('溪隐', '徐夤', '唐代', '将名将利已无缘，深隐清溪拟学仙。绝却腥膻胜服药， \n 断除杯酒合延年。蜗牛壳漏宁同舍，榆荚花开不是钱。 \n 鸾鹤久从笼槛闭，春风却放纸为鸢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '溪隐' AND p.poem_author = '徐夤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('于礼部后堂同诸公会宴衍圣公得宾字', '湛若水', '明代', '兹会曷为乐，所乐在嘉宾。素王有哲裔，蔼蔼温恭人。\n\n南宫荫芳树，宛若杏坛春。斯文本同家，十哲集如云。\n\n共闻宣圣训，气义即同门。我尝见羹墙，况接其贤孙。\n\n圣皇重师道，俎豆临成均。百工骏奔奏，三氏翕然臻。\n\n御宴昭殊锡，初筵亦继陈。幸逢五百会，文物为一新。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '于礼部后堂同诸公会宴衍圣公得宾字' AND p.poem_author = '湛若水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('台疆杂感', '张景祁', '清代', '虎符龙章镇全洋，帐下儿曹似将狼。未见寇锋临战垒，忽惊刃血溅公堂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '台疆杂感' AND p.poem_author = '张景祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('妾薄命', '孙绪', '明代', '妾命薄，薄如纸。君意陌上尘，妾意江边水。陌尘易飞扬，江水绝清泚。\n\n京兆多倾城，永别从今始。京兆犹自可，莫入临邛市。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '妾薄命' AND p.poem_author = '孙绪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠接泥渡下李巡检', '董嗣杲', '宋代', '一官坐渡头，事简多是閒。\n口口说庙灵，祭赛纷强顽。\n逐日享餕馀，赢得酡客颜。\n江风吹不散，借此资身孱。\n俸钱给不多，悔离禁卫班。\n妻子号寒饥，语下嗟间关。\n俊代尚迩遥，掷珓卜善还。\n随时了应酬，惟恨得酒悭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠接泥渡下李巡检' AND p.poem_author = '董嗣杲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南歌子 其一 闺绣', '董元恺', '清代', '螺笔描新样，金针倚绣床。深情却悔绣鸳鸯。绣出无情蛱蝶，又成双。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南歌子 其一 闺绣' AND p.poem_author = '董元恺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('平野堂重送江茂宗', '贺铸', '宋代', '东风南浦雨潇潇，欲去行人不自聊。\n谁道垂杨攀折苦，过春犹有最长条。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '平野堂重送江茂宗' AND p.poem_author = '贺铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('耆英会诗', '张焘', '宋代', '洛城今昔衣冠盛，韩国园林景物全。功在三朝尊二相，数逾九老萃群贤。\n\n当时乡社为高会，此日居留许款延。多幸不才陪履舄，更惭七十是新年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '耆英会诗' AND p.poem_author = '张焘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋夜坐', '谢晋', '明代', '白昼雨如注，黄昏云渐开。冰轮时露影，金气净无埃。\n\n栖泊从萍梗，情怀付酒杯。故山丛桂发，应待远人回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋夜坐' AND p.poem_author = '谢晋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送简寿玉主簿之官临桂二首 其一', '杨万里', '宋代', '兰溪倾盖杏风残，桂岭离裾菊露寒。听子新诗过夜半，吹侬秋思入云端。\n\n往吟平地千苍玉，还忆孤舟一钓竿。四海如今习凿齿，大官莫作小官看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送简寿玉主簿之官临桂二首 其一' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和云洞即事', '庞嵩', '明代', '舞雩多夙伴，半月共云林。远眺天空眼，长吟月在襟。\n\n百年真此乐，千里祇同心。不有知音者，谁为浪鼓琴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和云洞即事' AND p.poem_author = '庞嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈七首 其二', '释继成', '宋代', '昆崙奴著铁裤，打一棒行一步。争似火中钓鳖，日里藏冰。\n\n阴影间翻魍魉，虚空缚杀麻绳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈七首 其二' AND p.poem_author = '释继成';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送张寺丞', '李觏', '宋代', '三载居邻县，得闻金玉音。路遥相见少，道合受知深。\n\n已矣瓜时戍，悠哉魏阙心。归舟望不及，白日隐寒林。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送张寺丞' AND p.poem_author = '李觏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五月十三日从罗山堂分得黄金间碧玉竹栽植小园戏作', '徐熥', '明代', '栽竹须乘醉日栽，移将奇种出香台。贫家莫道无珍玩，多少黄金碧玉来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五月十三日从罗山堂分得黄金间碧玉竹栽植小园戏作' AND p.poem_author = '徐熥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋宵', '史恩培', '清代', '秋宵静坐冷于僧，参澈诗禅悟未能。也是置身图画里，菊花深处一书镫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋宵' AND p.poem_author = '史恩培';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荷 其六', '徐渭', '明代', '花垂叶倒露难擎，颈折鹅飞咽不鸣。渐看湖光平似掌，秋来无处立蜻蜓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荷 其六' AND p.poem_author = '徐渭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄伯氏篈', '许妹氏', '明代', '晴窗银烛低，流萤度高阁。\n悄悄深夜寒，萧萧秋叶落。\n关河音信稀，沉忧不可释。\n遥想青莲宫，山空萝月白。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄伯氏篈' AND p.poem_author = '许妹氏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈一百二十首 其六十四', '释怀深', '宋代', '住亦随缘去是常，山林城市两无妨。白云本是无心物，一任风吹入帝乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈一百二十首 其六十四' AND p.poem_author = '释怀深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('野望', '李锴', '清代', '燕赵悲凉俗，唐虞揖让风。古怀缘酒热，老眼得秋空。\n\n易水销神剑，尧山泯故宫。几多凭吊意，徙倚落晖中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '野望' AND p.poem_author = '李锴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('试院中', '王安石', '宋代', '萧萧疏雨吹檐角，噎噎暝蛩啼草根。\n闲却荒庭归未得，一灯明灭照黄昏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '试院中' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟白香山暮江吟二首 其二', '曹家达', '清代', '水云低压柳𣯶𣯶，一片凉阴浸绿潭。如此秋光收不住，几人惆怅望江南。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟白香山暮江吟二首 其二' AND p.poem_author = '曹家达';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('还家', '刘攽', '宋代', '久客常念归，还家自深愿。虽非湖海游，早已时节变。\n\n果裸施于宇，蟏蛸巧相衒。墙根思哀蛩，危栋辞归燕。\n\n贫加乡闾慕，病益儿女恋。栖迟免路旁，未厌茅屋贱。\n\n衡门过凉雨，秋草盈芳甸。耕耘傥及时，筋力自此劝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '还家' AND p.poem_author = '刘攽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行香子·不爱娇奢', '明本', '元代', '不爱娇奢。不喜繁华。身穿着、百衲袈裟。行中乞化，坐演三车。却怕人知，怕人问，怕人夸。雪竹交加。玉树槎牙。一枝开、五叶梅花。东村檀越，西市恩家。但去时斋，闲时讲，坐时茶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行香子·不爱娇奢' AND p.poem_author = '明本';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望蜀亭', '薛能', '唐代', '树簇烟迷蜀国深，岭头分界恋登临。 \n 前轩一望无他处，从此西川只在心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望蜀亭' AND p.poem_author = '薛能';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('述字回文偈七首 其三', '赵炅', '宋代', '比旧前忧依，述最亨知休。以祐然留希，绅背生推求。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '述字回文偈七首 其三' AND p.poem_author = '赵炅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('棋', '李孝光', '元代', '国手功名满世间，几多奇思上眉端。人心险处千机变，局面危时一著安。\n\n陈入乌江迷项羽，势穷赤壁走曹瞒。近来黑白无分晓，输与樵翁冷眼看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '棋' AND p.poem_author = '李孝光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('友人惠蒲草寄谢二首 其二', '何吾驺', '明代', '尧世天初韭，周文爰作菹。碧滋环砚石，灵异八图书。\n\n密养知心细，勤披与俗疏。未论逢大药，得意并观鱼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '友人惠蒲草寄谢二首 其二' AND p.poem_author = '何吾驺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('房太尉管', '张晋', '清代', '仓卒难当曳落河，高谈因果奈君何。更堪琴客能招贿，岂有文人解荷戈。\n\n士盗虚声成事少，战遵古法误人多。义军血变陈涛水，千载伤心杜老歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '房太尉管' AND p.poem_author = '张晋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大涤洞天留题', '倪允文', '宋代', '巢父滩头甫着鞭，名山入眼驿程边。\n迂回仅费商於地，领袖宁烦一介先。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大涤洞天留题' AND p.poem_author = '倪允文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汀州哭崔惟正', '张宁', '明代', '别来三月叹蹉跎，落日惊看逝水波。清泪欲乾还自落，羁愁未遣又添多。\n\n英雄有死嗟谁在，欢会无期奈老何。十五年前旧游事，不胜哀戚动邻歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汀州哭崔惟正' AND p.poem_author = '张宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送沅州通判', '徐积', '宋代', '过湘江时君且听，但恐水中有冤声。当时无地容屈平，众人皆醉嫌独醒。\n\n烦君须吊独醒翁，以酒注之鱼腹中。不须以物缠米筒，但投诗去责蛟龙。\n\n为君质直有古风，能高其义哀其忠。投诗已罢吊已终，寄声急报南城翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送沅州通判' AND p.poem_author = '徐积';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望湖亭四首 其二', '郑学醇', '明代', '苍茫烟水一凭阑，白苧絺衣五月寒。风熨翠纹如可御，霞蒸丹片若为餐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望湖亭四首 其二' AND p.poem_author = '郑学醇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('养心殿古干梅', '弘历', '清代', '为报阳和到九重，一枝红绽暗香浓。亚盆漫忆辞东峤，作友何须倩老松。\n\n鼻观恭来谙断续，心机忘处对舂容。林椿妙笔林逋句，却喜今朝次第逢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '养心殿古干梅' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('故宫燕 其一', '邢昉', '清代', '君不见故宫燕，春雨秋风几回转。宫中风雨长蓬蒿，飞入宫墙绕虚殿。\n\n穿帘度阁羽差池，尽日呢喃人未知。柳绿乍衔千尺絮，花开仍拂万年枝。\n\n玉阶寂寞罘罳冷，画栋差池春燕影。岁岁营巢竟不成，春来秋去谁曾省。\n\n可怜此度秋风早，整顿毛衣犹自好。裴徊欲别未央宫，万户千门忽如扫。\n\n钟虡何年去洛阳，仙人辞汉泪成行。最苦西飞双燕子，回头不见旧宫墙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '故宫燕 其一' AND p.poem_author = '邢昉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百三十六首 其四十八', '释惟一', '宋代', '踞此室，坐此座。佛来祖来，一一按过。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百三十六首 其四十八' AND p.poem_author = '释惟一';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三月十日牡丹盛开将约诸宾客共赏九日夜忽风雨大作黎明园丁走报花已半离披矣感而赋此', '朱诚泳', '明代', '自恨开尊约已迟，晓来风雨半离披。不知犹有春多少，为报东君好护持。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三月十日牡丹盛开将约诸宾客共赏九日夜忽风雨大作黎明园丁走报花已半离披矣感而赋此' AND p.poem_author = '朱诚泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵陈维寅苏杭怀古各三首 其三', '谢应芳', '元代', '奕奕让王宫，遥遥延陵墓。吴侬奉烝尝，春秋几霜露。\n\n胡为后之人，无复继高步。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵陈维寅苏杭怀古各三首 其三' AND p.poem_author = '谢应芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('摸鱼儿 答王迈人六叠前韵', '曹溶', '明代', '曳青藜、笋舆休禦，炎光常带寒思。钱神脉脉无消息，何计挽迟为驶。\n\n堪隐矣。有作队鸥凫，栖向当年水。五噫声里。更罝网高张，麟枯凤老，相泣反前袂。\n\n天壤内，空阔仍同梓里。齐名敢觑苏米。书生习气难镵削，汉柳多情三起。\n\n些子事。莫近舍樽前，追忆黄垆醉。有家似寄。要缩取方壶，天风海屋，长剑辘轳繫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '摸鱼儿 答王迈人六叠前韵' AND p.poem_author = '曹溶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵杂咏 其三', '朱谋㬜', '明代', '古寺门当雉堞横，老僧犹指是台城。寒云夜傍缭垣宿，野草春从辇路生。\n\n往事尚留残碣字，流年虚送暮钟声。可怜张绪当年柳，万缕烟姿画不成。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵杂咏 其三' AND p.poem_author = '朱谋㬜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('薛卿教长行歌（时量移湖州别驾）', '皎然', '唐代', '桂阳仙柳道家说，昔传苏君今是薛。聊将握槊偶时人， \n 便被人间称冠绝。黄杨文局龟螭蟠，琢成骰子双琅玕. \n 初疑月破云中堕，复怪星移指下攒。谁识兵奇势可保， \n 坐看将军上一道。有时彩王非所希，笑击单于出重围。 \n 凫惊隼击疾若飞，左顾右盻生光辉。家本联姻汉戚里， \n 身是长安贵公子。名高艺绝何翩翩，几回决胜君王前。 \n 扈游长乐与祈年，人望青云白日边。谪宦江南岁阴晚， \n 还将此道聊自遣。由来君子行最长，予亦知君寄心远。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '薛卿教长行歌（时量移湖州别驾）' AND p.poem_author = '皎然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('公馆即事', '罗钦顺', '明代', '庭前高树欲凌云，扰扰昏鸦漫作群。明月满天人已静，数声犹向梦中闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '公馆即事' AND p.poem_author = '罗钦顺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二月二日登楼作', '刘基', '明代', '薄寒疏雨集春愁，愁极难禁独上楼。\n何处山中堪采药，几时湖上好乘舟。\n衔泥客燕聊想傍，泛水浮萍可自由。\n见说兰亭依旧在，于今王谢少风流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二月二日登楼作' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿胡心斋先生七十五岁', '叶云峰', '近代', '香山馀韵乐优游，松柏贞身几世修。老树著花光冉冉，长春逢润境悠悠。\n\n函关甫渡紫霞袭，蓬岛在望玉液浮。兰桂联芳多瑞气，云边遥颂一登楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿胡心斋先生七十五岁' AND p.poem_author = '叶云峰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('路闻鹧鸪', '胡奎', '明代', '苦竹冈头一两声，钩辀格磔为谁鸣。纵行不得须行去，莫道离人不耐听。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '路闻鹧鸪' AND p.poem_author = '胡奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('简怀姬人四章 其四', '姚燮', '清代', '罗敷桑陌已无莺，老屋临江但竹檠。采得芙蓉知古怨，邀来明月得新晴。\n\n乱山独梦愁莲步，涩指中宵试笛声。好熨薰笼消寂夜，将诗咒与雪衣鹦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '简怀姬人四章 其四' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭北谷罗先生', '艾性夫', '宋代', '死到先生世道衰，忍弹双泪看铭碑。动随天去心无愧，视得官轻事敢为。\n\n他日史书廉太守，四方人哭老宗师。不知精爽归何处，定在梅花自在时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭北谷罗先生' AND p.poem_author = '艾性夫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汤晋卿善谈命求诗纪实', '许及之', '宋代', '已近无闻半百年，枉烦明镜照华颠。湴河驿马妨乘鄣，氐宿苍龙分委天。\n\n告我三阳闻好语，验君三命有真传。预愁一字终无补，何日归欤阿对泉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汤晋卿善谈命求诗纪实' AND p.poem_author = '许及之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('论语绝句一百首', '张九成', '宋代', '君子何尝去小人，小人如草去还生。\n但令鼓舞心归化，不必区区务力争。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '论语绝句一百首' AND p.poem_author = '张九成';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桐城青山裴山人枉步见寻兴尽遽归', '郭祥正', '宋代', '门外青山是我山，手携筇杖只今还。岩花落尽莺啼懒，纸帐孤灯梦亦閒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桐城青山裴山人枉步见寻兴尽遽归' AND p.poem_author = '郭祥正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('少微峰', '陈岩', '宋代', '隐居不惠不夷间，拜爵山中驿使还。\n身远觚稜几千里，少微星影堕空山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '少微峰' AND p.poem_author = '陈岩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送丘宗卿帅蜀三首', '杨万里', '宋代', '谕蜀宣威百万兵，不须号令自精明。\n酒挥勃律天西碗，鼓卧蓬婆雪外城。\n二月海棠倾国色，五更杜宇说乡情。\n少陵山谷千年恨，不遇丘迟眼为青。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送丘宗卿帅蜀三首' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谩成', '王安石', '宋代', '清时无路取封侯，病卧牛衣已数秋。\n日月不胶时易失，感今怀昔使人愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谩成' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('【双调】沉醉东风_听不厌鸾笙', '钟嗣成', '元代', '听不厌鸾笙象板，看不足凤髻蝉鬟。按不住刺史狂，学不得司空惯，常不教粉吝红悭。若不把群花恣意看，饱不了平生饿眼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '【双调】沉醉东风_听不厌鸾笙' AND p.poem_author = '钟嗣成';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏日小酌', '史弥宁', '宋代', '拓窗一粲俯晴川，尽放薰风到酒边。\n小待夜深清月上，藕花影里榜渔船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏日小酌' AND p.poem_author = '史弥宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('平湖乐', '王恽', '元代', '安仁双鬓已惊秋。更甚眉头皱。一笑相逢且开口。\n\n玉为舟。\n\n新词淡似鹅黄酒。醉扶归路，竹西歌吹，人道是扬州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '平湖乐' AND p.poem_author = '王恽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠卢次楩 其二', '谢榛', '明代', '谁识丰城剑，天空紫气高。老来悲道路，醉后益风骚。\n\n物议冰霜过，才名岁月劳。一寒今范叔，谁复赠绨袍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠卢次楩 其二' AND p.poem_author = '谢榛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汉上遇钟参政', '李梦阳', '明代', '长安一为别，十载但书传。我自河南至，君来自沔川。\n\n偶逢知万事，重会是何年。馆静风依马，江鸣雨濯船。\n\n情多看转默，酒后惜分眠。明发孤帆疾，愁经大别边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汉上遇钟参政' AND p.poem_author = '李梦阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李长者入祀典歌', '周瑛', '明代', '仙溪诘曲如回肠，东流赴海何茫茫。凭谁截断天地纪，灌我万顷桑麻场。\n\n钱氏四娘长乐女，黄金如斗提不起。将军岩下自经营，陂溃直随此陂死。\n\n伟哉同县林制科，缗钱十万腰下驮。温泉隘口重累趾，倏忽顾盼成沧波。\n\n熙宁天子重农事，下诏募人急营治。当时阖郡多富家，坐视诏书无一至。\n\n候官长者真仁贤，轻财好施闽人传。有僧踪迹颇诡秘，日日贳酒不还钱。\n\n木兰山前溪面阔，僧为插竹记颠末。溪流缓处可立基，缓处立基基不拔。\n\n入海伐石海为空，上山伐石山为童。三十二门细分布，无云无雨卧长虹。\n\n昔日溪流皆赴海，今日溪流得灌溉。鸡鸣犬吠万家村，隐隐桑麻相映带。\n\n我谓有莆须有陂，有莆无陂莆亦隳。惟莆与陂相终始，莆人思公何尽期。\n\n昨日恩诏下闾里，春秋二祭入新议。借问建言者伊谁，太平郡守周氏子。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李长者入祀典歌' AND p.poem_author = '周瑛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读史', '朱淑真', '宋代', '笔头去取万千端，后世遭它恣意瞒。王霸谩分心与迹，到成功处一般难。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读史' AND p.poem_author = '朱淑真';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭崔二十四常侍', '白居易', '唐代', '貂冠初别九重门，马鬣新封四尺坟。薤露歌词非白雪， \n 旌铭官爵是浮云。伯伦每置随身锸，元亮先为自祭文。 \n 莫道高风无继者，一千年内有崔君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭崔二十四常侍' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('越上九日感怀七首呈韩明善先生 其三', '张仲深', '元代', '登高旷玄览，寓目销我愁。峰峦滴朝润，萧条气含秋。\n\n客边得佳节，虑静境亦幽。况乃岁稔登，遗禾弥道周。\n\n糟床注新酿，已免沽挈忧。幸此足斟酌，好景庶可酬。\n\n岂知故园月，今夕在兹楼。一笑欲忘言，岁月何悠悠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '越上九日感怀七首呈韩明善先生 其三' AND p.poem_author = '张仲深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送汝弼赴潭倅 其一', '徐积', '宋代', '莫说江南行路长，山苍苍兮水茫茫。莫问长沙城远近，洞庭湖口是潇湘。\n\n去时先上岳阳城，夜宿巴陵探阴晴。泛洞庭时四五更，出湖口处曈昽明。\n\n平生闻说潭与衡，今来吏隐驻箳篂。四时所见皆所经，湖青草兮庙黄陵。\n\n眼看君山别洞庭，笑谈却作江南行。巴陵渡口转船头，一帆风过岳阳楼。\n\n行尽江山到真州，画船旗鼓入扬州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送汝弼赴潭倅 其一' AND p.poem_author = '徐积';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄赵德庄以过去生中作弟兄为韵七首 其二', '韩元吉', '宋代', '忆昨钟山来，君亦湓浦去。今年赴湓浦，钟山复君住。\n\n出处每相似，屡触众狙怒。毁誉久自定，子贤吾亦庶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄赵德庄以过去生中作弟兄为韵七首 其二' AND p.poem_author = '韩元吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留题融州老君岩 其二', '刘谊', '宋代', '凿成岩穴鬼工难，中有神仙自往还。不见桃花开落处，祇随流水到人间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留题融州老君岩 其二' AND p.poem_author = '刘谊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题太常寺丞吕仲善寄弟仲铉双雀图', '唐文凤', '明代', '啾啾双雀晓风寒，花到酴醾春事阑。应似鸰原急难意，萧条不是纥干山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题太常寺丞吕仲善寄弟仲铉双雀图' AND p.poem_author = '唐文凤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辞众偈', '释道初', '宋代', '昨日离城市，白云空往还。\n松风清耳目，端的胜人间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辞众偈' AND p.poem_author = '释道初';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贾村三首 其二', '许景衡', '宋代', '芦苇萧疏倚断垣，贾家犹有两三村。锄犁蓑笠纷纷去，知是先生几代孙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贾村三首 其二' AND p.poem_author = '许景衡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玲珑峰', '弘历', '清代', '朝催行骑缘谷东，新程逐处咨民风。沿冈度涧凡几重，路右遥见凌霄峰。\n\n巍乎气象迥不同，群山拱伏孰与京。倚天拔地超哉雄，嵌空洞穴宛转通。\n\n嶊崣巀嶭森巃葱，奇葩真树那可名。幻以云气郁丰隆，石户俨开守玉童。\n\n丹灶碧火其燄红，垂垂铁锁悬长空。凡骨怅望难寻踪，在昔下风访崆峒。\n\n塞垣荒略传何从，欣兹始遇名玲珑。飞来奚事艳吴中，至今吟咏纷莫穷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玲珑峰' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('姑苏览古杂兴 其三', '弘历', '清代', '司徒构别墅，舍作化人园。想像林泉概，依稀松菊存。\n\n石经开士悟，屐带谢公痕。槃郢秦王索，荒唐说虎蹲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '姑苏览古杂兴 其三' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('太皇太后挽词二首 其二', '范祖禹', '宋代', '授几咨元老，垂帷揽众贤。舜功成二十，周士得三千。\n\n德泽流终古，规摹遗亿年。宁唯照彤史，石室烂青编。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '太皇太后挽词二首 其二' AND p.poem_author = '范祖禹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赋赠黄介子先生', '吴芳植', '明代', '自古文章厄数奇，惜公磨砺度年时。淩云枉自誇三赋，避世何堪发五噫。\n\n绕陌昏烟人去远，隔山皓月梦来迟。秋期海上鲸鱼至，更觅长竿理钓丝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赋赠黄介子先生' AND p.poem_author = '吴芳植';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古意（二首）', '王弼', '明代', '莫作河中水，愿为水上舟。\n舟行有返棹，水去无回流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古意（二首）' AND p.poem_author = '王弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('除夕有感', '王慎中', '明代', '岁去江城人未归，寥寥心事掩寒扉。明朝一岁知何似，三十年中已尽非。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '除夕有感' AND p.poem_author = '王慎中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('御沟水', '王贞白', '唐代', '一带御沟水，绿槐相荫清。此中涵帝泽，无处濯尘缨。 \n 鸟道来虽险，龙池到自平。朝宗本心切，愿向急流倾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '御沟水' AND p.poem_author = '王贞白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王母歌寿黎母太夫人', '欧大任', '明代', '峨峨天上三珠宫，琳庭贝阙交玲珑，扶桑若木生西东。\n\n朱光反射银汉侧，青雀翻飞明月中。椷书咫尺报蓬莱，王母西从瑶水来。\n\n戴胜之冠切云笄，珣玗双佩秋兰裁。青娥三千不可以约略，后先婀娜纷趋陪。\n\n烟軿电毂一时集，手翳琼枝胡至哉。斯时琪花散空碧，绿幢卒葆忽生色，枣熟如瓜宴瑶席。\n\n吸沆瀣兮食紫虹，左流霞兮右金液。双成指顾三千娥，迭歌侑酌觞不息。\n\n须臾又转绛节朝，天津两旗河鼓遥。湘妃和神起阳瑟，秦女按节来吹箫。\n\n鸾匏鹤笛合九奏，电裳舞袖回风飘。南岳夫人笑相邀，麻姑赴会不待招，武夷曾孙歌且谣。\n\n罗浮仙峰四百三十二，青玉为坛铁为桥，王母来往常逍遥。\n\n飞云我忆蓬莱阁，儿时迎拜骖黄鹤。玉箱欲纪王母年，金门且问东方朔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王母歌寿黎母太夫人' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题素尚斋', '弘历', '清代', '数间朴屋万山中，鹿豕为游溪壑丛。造物由来敦素尚，书生未足诩家风。\n\n霁空色朗依峰白，雨叶声繁点砌红。近岁遥年频捡挍，几番静悟不同同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题素尚斋' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢诸寓贵载酒', '刘克庄', '宋代', '景迫桑榆欢意少，相依药碗与茶杯。\n忽闻有客载醪过，谁道无人裹饭来。\n家在恍惊如鹤化，岁丰未可罪龙乖。\n闲吟不与君争巧，自作村田乐散怀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢诸寓贵载酒' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再宿京口禅院', '栖蟾', '唐代', '滩声依旧水溶溶，岸影参差对梵宫。楚树七回凋旧叶， \n 江人两至宿秋风。蟾蜍竹老摇疏白，菡萏池干落碎红。 \n 多病支郎念行止，晚年生计转如蓬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再宿京口禅院' AND p.poem_author = '栖蟾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔家傲', '洪皓', '宋代', '圃蕙庭桐雕大半。西风不借行人便。不用留题明月观。西园宴。颜酡浪说觞无算。 \n 万斛羁愁推不远。千杯鲁酒何曾见。却羡南宾凫与雁。行不乱。哀鸣直到翻江岸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔家傲' AND p.poem_author = '洪皓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋帖子词七叠前韵 其二', '弘历', '清代', '世界三千放大光，桂宵摛藻字应香。应潮为忆吴江浦，二釜能不足筥匡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋帖子词七叠前韵 其二' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题美人汲井养花图', '袁华', '明代', '茝石莺啼琐窗静，御柳条长拂金井。美人初试薄罗裳，翠袖双擎玉壶冷。\n\n璚树花开璧月圆，一枝折得浸红泉。莫教野鹿偷衔去，狼籍香囊蜀道边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题美人汲井养花图' AND p.poem_author = '袁华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶成二首 其一', '王安石', '宋代', '渐老偏谙世上情，已知吾事独难行。脱身负米将求志，勠力求田岂为名。\n\n高论颇随衰俗废，壮怀难值故人倾。相逢始觉宽愁病，搔首还添白发生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶成二首 其一' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十月廿二日园西樱桃数花便有蝶至 其二', '徐渭', '明代', '夏实每看当鸟尽，冬花何事向人妍。不堪憔悴行吟后，故弄阳春欲雪前。\n\n正苦白头愁兀兀，谁家黄蝶过娟娟。杖藜立断斜阳影，泪尽西风送菊天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十月廿二日园西樱桃数花便有蝶至 其二' AND p.poem_author = '徐渭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗 其二', '郑孝胥', '清代', '亚字阑干凿石成，砖廊缛腻复宽平。年年祇望松身长，待听风涛入座声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗 其二' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('时人为张氏语', '佚名', '隋代', '宋称敷演，梁则卷充。清虚学尚，种有其风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '时人为张氏语' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游雪窦杖锡七首·妙高台', '陈著', '宋代', '不到兹台四十年，临风独立意悠然。\n胸中多少难言事，便欲凭高叩九天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游雪窦杖锡七首·妙高台' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('散花之室六言', '邓深', '宋代', '本有献花佛事，何妨乞食歌姬。\n若了悟不住相，斯参透无言师。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '散花之室六言' AND p.poem_author = '邓深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽齐安郡夫人', '李正民', '宋代', '懿范闺房秀，齐姜素望优。广川名益盛，内壸德弥修。\n\n寿量方难老，生涯遽若浮。延平双剑逝，遗恨在营丘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽齐安郡夫人' AND p.poem_author = '李正民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哀鞠四绝 其一', '郭之奇', '明代', '离悯初闻百绪倾，凄其苫次但魂营。当年陟屺嗟无死，今日哀莪恨有生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哀鞠四绝 其一' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渡淮', '钟芳', '明代', '春判发京浦，及淮春已徂。君家淮水上，望望足欢娱。\n\n宾朋挈榼来，酬倡忘而吾。麦风环宇凉，槐阴沁窗疏。\n\n清时不易遇，岁月催霜颅。毋为久耽乐，焦萎待昭苏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渡淮' AND p.poem_author = '钟芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春 将之成都', '李齐贤', '元代', '堪笑书生，谬算狂谋，所就几何。谓一朝遭遇，云龙风虎，五湖归去，月艇烟蓑。人事多乖，君恩难报，争柰光阴随逝波。缘何事，背乡关万里，又向岷峨。幸今天下如家，顾去日无多来日多。好轻裘快马，穷探壮观，驰山走海，总入清哦。安用平生，突黔席暖，空使毛群欺卧驼。休肠断，听阳关第四，倒卷金荷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春 将之成都' AND p.poem_author = '李齐贤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻蝉五绝句奉呈诸幕友', '曾丰', '宋代', '语那似默得便宜，蝉谩三叹复五噫。\n养气何妨为孟子，知音不必要钟期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻蝉五绝句奉呈诸幕友' AND p.poem_author = '曾丰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答许主簿', '张元凯', '明代', '马曹一主簿，七十尚栖迟。簪笔推先辈，悬车怅后期。\n\n倾交霍去病，仰给郑当时。年少余官薄，何然动尔思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答许主簿' AND p.poem_author = '张元凯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵二首 其二', '胡粹中', '明代', '昨夜霜初重，他方叶又黄。蛩声悲月冷，客意怯风凉。\n\n孤屿渔村外，荒邮野戍傍。因思旧游处，鱼稻满江乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵二首 其二' AND p.poem_author = '胡粹中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十四夜对月柬子彦有怀子中兄', '刘崧', '明代', '月出白杨端，乌啼清夜阑。絺衣初淅淅，草露已漙漙。\n\n共喜灯花密，宁辞酒盏乾。有兄怀二弟，应自倚楼看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十四夜对月柬子彦有怀子中兄' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('證道歌 其二三六', '释印肃', '宋代', '早时成佛于今在，瓶倾不出周沙界。妙音遐畅广宣扬，念者念兮拜者拜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '證道歌 其二三六' AND p.poem_author = '释印肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('顾家宅公园夜坐四首 其四', '林庚白', '近代', '凉飔吹落隔林黄，几叶飘零几郁苍。悄爱归程携月色，閒随去路蹋橙光。\n\n残宵粉黛能为魅，淑世衣冠是不祥。破哓东方应有待，要冯朝气变沧桑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '顾家宅公园夜坐四首 其四' AND p.poem_author = '林庚白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行路难', '黎贞', '明代', '君不见天上浮云任舒卷，白衣苍狗须臾变。又不见瞿塘嘈嘈水倒流，奔湍激石能覆舟。\n\n人情有时亦如此，纷纷轻薄何足比。平常意气同死生，急难何堪托终始。\n\n岭南狂客孤且贫，常将青眼待时人。岂知此道不足贵，翻使皋鹤俦鸡群。\n\n不如托身与鹪鹩，蓬蒿之下同逍遥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行路难' AND p.poem_author = '黎贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('为方仲敏题白云深处', '凌云翰', '元代', '千山万水入登临，犬吠鸡鸣杳莫寻。试问白云深几许，仙家更在白云深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '为方仲敏题白云深处' AND p.poem_author = '凌云翰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔家傲', '晏殊', '宋代', '楚国细腰元自瘦。文君腻脸谁描就。日夜声声催箭漏。昏复昼。红颜岂得长如旧。 \n 醉折嫩房和蕊嗅。天丝不断清香透。欲傍小阑凝坐久。风满袖。西池月上人归后。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔家傲' AND p.poem_author = '晏殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵刚父即事绝句 其一', '赵孟頫', '元代', '玉树凋伤众草黄，夜虫时语怨流光。美人望望隔秋水，不寄相思书一行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵刚父即事绝句 其一' AND p.poem_author = '赵孟頫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('襄阳歌', '李白', '唐代', '落日欲没岘山西，倒著接蓠花下迷。\n襄阳小儿齐拍手，拦街争唱《白铜鞮》。\n旁人借问笑何事，笑杀山公醉似泥。\n鸬鹚杓，鹦鹉杯。\n百年三万六千日， 一日须倾三百杯。\n遥看汉水鸭头绿，恰似葡萄初酦醅。\n此江若变作春酒，垒曲便筑糟丘台。\n千金骏马换小妾，醉坐雕鞍歌《落梅》。\n车旁侧挂一壶酒，凤笙龙管行相催。\n咸阳市中叹黄犬，何如月下倾金罍？\n君不见晋朝羊公一片石，龟头剥落生莓苔。\n泪亦不能为之堕，心亦不能为之哀。\n清风朗月不用一钱买，玉山自倒非人推。\n舒州杓，力士铛，李白与尔同死生。\n襄王云雨今安在？江水东流猿夜声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '襄阳歌' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古桧行', '洪亮吉', '清代', '城头古树记以百，非宋非元李唐植。森森古桧蟠空苍，奇气矫作百夫特。\n\n黄昏过树雷雨青，白昼拿人爪牙黑。眼经百岁若飞电，身阅四朝犹过客。\n\n霜磨雨洗遗迹尽，剩有创瘢余径尺。子城峨峨树历历，建炎年中恶氛逼。\n\n一呼落日兵四登，百战孤云气逾直。将军白马当树立，砍剑剑摧砍刀涩。\n\n风云此日总削平，穴腹犹容怪蛇蛰。主人爱树识树性，不遣虬枝两相击。\n\n南枝使南北使北，以松归松柏归柏。树老枝柯总有神，时清冰雪皆生色。\n\n余生好奇奇不屈，陡然见之意亦嚇。摩挲抚树三叹息，此树心空寿金石。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古桧行' AND p.poem_author = '洪亮吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('步虚词二十三章 其五', '沈鍊', '明代', '大言惊宇宙，小隐适山林。观世壶中静，知机象外深。\n\n洞文开万卷，绛岭历千寻。雄心沉白水，锐气炼黄金。\n\n谒圣玄宫里，寻仙苍木阴。未能挥宝剑，聊用抚瑶琴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '步虚词二十三章 其五' AND p.poem_author = '沈鍊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠蒲察元帅七首 其二', '耶律楚材', '元代', '积年飘泊困边尘，闲过西隅谒故人。忙唤贤姬寻器皿，便呼辽客奏筝𥱧。\n\n葡萄架底葡萄酒，杷榄花前杷榄仁。酒酽花繁正如许，莫教辜负锦城春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠蒲察元帅七首 其二' AND p.poem_author = '耶律楚材';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('艾至堂北度雁门图', '孙衣言', '清代', '雁飞不度橐驼愁，青山千仞截马头。儒衣七尺北风疾，白日欲落关山秋。\n\n单于台高陵白楼，长城故鬼鸣啾啾。阴山小儿汗血马，关弓欲射南幽州。\n\n武灵结怨几千载，边头战血腥髑髅。圣人飞龙起东极，手挽扶桑拓西北。\n\n阴方侍子知诗书，燕支妇女好颜色。齐纨鲁缟推小车，客行饮酒餐羊酥。\n\n出门万里不持刃，三关比户悲危途。仲宣从军自愁思，班超投笔徒区区。\n\n书生来游壮士卧，题诗石壁蛟龙纡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '艾至堂北度雁门图' AND p.poem_author = '孙衣言';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鼓角楼初成 其二', '黄裳', '宋代', '云中人作四星看，十二光阴一箭寒。吉事有祥戎事静，溪山赢得倚栏干。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鼓角楼初成 其二' AND p.poem_author = '黄裳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('轮台歌', '施补华', '清代', '胡麻叶大麦穗黄，百株垂柳干株杨。东村西村通桥梁，鸡鸣犬吠流水长。\n\n养蚕作茧家满筐，种豆绕篱瓜绕墙。趁墟日出驱马羊，秧哥杂沓携巴郎，怀中饼铒牛酥香。\n\n巴郎汉语音琅琅，中庸论语吟篇章。阿浑伯克衙前忙，分水雇役兼征粮。\n\n衣冠大半仍胡俗，郡县从新隶职方。轮台之悔思汉皇，穷兵西域晚自伤。\n\n后来岑著作，歌词尤慨慷。城头吹角雪茫茫，边风夜吼不可当。\n\n一川碎石挟之舞，误惊群燕翻空翔，至今诵之心悲凉。\n\n荒微忽变丰乐乡，天时地气应蓄昌。轮台之歌我继作，人间何处无沧桑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '轮台歌' AND p.poem_author = '施补华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('惺惺石', '释绍昙', '宋代', '主人翁已强安名，何待区区唤一声。\n坐得石头穿透底，依然打个不惺惺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '惺惺石' AND p.poem_author = '释绍昙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和张总管菊', '李复', '宋代', '云里霓裳闲俨雅，霜前黄鹄独轩昂。\n不从春意装褫巧，却被秋风漏泄香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和张总管菊' AND p.poem_author = '李复';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹岙扫墓三首 其一', '王季思', '近代', '昔我从兄姊，读书前间屋。雪蕉斋集诗，童稚耳已熟。\n\n十三学韵语，陶集亲课读。高韵何所知，呤讽意自足。\n\n十五授杜诗，忠爱致谆嘱。中年丁世变，山海横翻覆。\n\n艰难百战余，风雨千家哭。何期孑尔身，不死亦未辱。\n\n苦吟习仍在，祖武嗟难续。三复课儿篇，悲风动林谷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹岙扫墓三首 其一' AND p.poem_author = '王季思';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汪倅生日二首 其一', '周孚', '宋代', '寄语溪头赤鲩公，只今为计莫匆匆。直须整顿乾坤了，却驾飙轮迓此翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汪倅生日二首 其一' AND p.poem_author = '周孚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谩题', '杨弘道', '元代', '都门几度见秋风，枫柘连山树树红。江海此时回首望，黄花满地酒尊空。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谩题' AND p.poem_author = '杨弘道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐·日寒风细', '李莱老', '宋代', '日寒风细。庭馆浮花气。白发潘郎吟欲醉。绿暗芜千里。西园南浦东城。一春多少闲情。日暮采苹歌远，梦回唤得愁生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐·日寒风细' AND p.poem_author = '李莱老';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送吴宗师南祀归二首 其一', '邓文原', '元代', '国老分茅社，祠官从使星。鹤书来涧谷，羽节动仙灵。\n\n寸草春逾碧，黄花晚独馨。真人犹五采，归受《蕊珠经》。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送吴宗师南祀归二首 其一' AND p.poem_author = '邓文原';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西园探梅三首 其一', '王庭圭', '宋代', '俯窥溪影忽横斜，仰看寒梅已放花。未觉东风吹水面，早惊春色到天涯。\n\n年时肌骨瘦如许，日暮烟云薄不遮。折得一枝归静院，夜深玉颊照窗纱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西园探梅三首 其一' AND p.poem_author = '王庭圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送黄元章秘书还馀杭待次荆门', '许及之', '宋代', '蓬莱云色正飞浮，猛乞分符向玉州。抵鹊信嫌三献辱，如虹肯要万金酬。\n\n勋名不朽山为砺，轩冕随缘芥作舟。却憾渥洼求汗血，不如天厩出骅骝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送黄元章秘书还馀杭待次荆门' AND p.poem_author = '许及之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻砧有感', '吕温', '唐代', '千门俨云端，此地富罗纨。秋月三五夜，砧声满长安。 \n 幽人感中怀，静听泪汍澜。所恨捣衣者，不知天下寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻砧有感' AND p.poem_author = '吕温';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日寄怀晚香山人', '罗天阊', '清代', '雁书潦草不可识，目断天涯长叹息。术士今无缩地功，春山愁煞芝兰色。\n\n梦魂昨夜坐君旁，花里寻诗字字香。邻鸡不合声三喔，只剩幽辉冷半床。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日寄怀晚香山人' AND p.poem_author = '罗天阊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山庄月夜作', '萧颖士', '唐代', '献书嗟弃置，疲拙归田园。且事计然策，将符公冶言。 \n 桑榆清暮景，鸡犬应遥村。蚕罢里闾晏，麦秋田野喧。 \n 涧声连枕簟，峰势入阶轩。未奏东山妓，先倾北海尊。 \n 陇瓜香早熟，庭果落初繁。更惬野人意，农谈朝竟昏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山庄月夜作' AND p.poem_author = '萧颖士';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满庭芳 其五', '毛奇龄', '清代', '石氏悬楼，王朗开阁，伤心睹此芒芒。上宫碧玉，本是旧名倡。\n\n穗帐空悬日暮，西陵下、几曲沧浪。如何地，漳台望久，回首见空王。\n\n双双。寻侣伴，幽吟梵磬，仿佛伊凉。把杨枝滴露，暗洗朝妆。\n\n满目天花散尽，云床冷、梦断高唐。褰帘坐，水田衫子，不叠旧衣箱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满庭芳 其五' AND p.poem_author = '毛奇龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟古诗二十首 其九', '杨起元', '明代', '南海有珠树，颗颗日月光。攀条采其珠，盛以云锦囊。\n\n散满天地閒，何况同一乡。此物取不竭，复宜久韬藏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟古诗二十首 其九' AND p.poem_author = '杨起元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('刘逊子架阁饷江茶 其二', '方岳', '宋代', '醉眠彭泽几何日，只与吟诗办秫田。灵草独醒山雨外，可曾持到漉巾前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '刘逊子架阁饷江茶 其二' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('巢山', '陆游', '宋代', '短发巢山客，人知姓字谁？穿林双不借，取水一军持。\n渴鹿群窥涧，惊猿独袅枝。\n何曾畜笔砚，景物自成诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '巢山' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红 其四 醉饮史远公斋中有感，四用回韵', '董元恺', '清代', '天地茫茫，愁无尽、销愁无术。应只有、浇愁惟酒，不烦蔘术。\n\n花下频招松下鹤，盘中又检山中栗。料吾身、烂醉是生涯，须千日。\n\n梦欲醒，庄周漆。心常醉，刘伶匹。任挥毫草檄，请缨投笔。\n\n薄劣自甘糟粕劳，不才且入山林密。抚长锥、终岁处囊中，何由出。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红 其四 醉饮史远公斋中有感，四用回韵' AND p.poem_author = '董元恺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南柯子 与背道者', '刘志渊', '元代', '久静还思动，情甘爱海迷。仙凡两路似云泥。从此相分，不顾上天梯。莫学鹪鹩志，营营恋小枝。北溟鲲量愿君为。咫尺成鹏，准拟奋天池。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南柯子 与背道者' AND p.poem_author = '刘志渊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭稚女雁 其十六', '屈大均', '明代', '无端母子来烟瘴，送却浮生数月中。无母不应还有子，芙蓉蒂断易随风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭稚女雁 其十六' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬盘隐总饷园中之什', '释居简', '宋代', '总饷园中赋咏佳，可曾误指玉钩斜。烟鬟闯户青浮玉，羽盖亭云绿护花。\n\n瘦竹引风留客旆，长江流月去谁家。暮天漾漾随潮展，彷佛西兴渡口沙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬盘隐总饷园中之什' AND p.poem_author = '释居简';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('居庸关', '楚石梵琦', '明代', '天畔浮云云表峰，北游奇险见居庸。\n力排剑戟三千士，门掩山河百万重。\n渠答自今收战马，兜铃无复置边烽。\n上都避暑频来往，飞鸟犹能识衮龙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '居庸关' AND p.poem_author = '楚石梵琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('投赠王湘绮先生 其一', '吴广霈', '清代', '到处青山好杖藜，沧洲小住即关西。非因赋鵩思辞楚，宁感蜚鸿佐霸齐。\n\n风息神鹏图海运，春归杜宇背花啼。愿从五斗乡闾醉，付与龙门传滑稽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '投赠王湘绮先生 其一' AND p.poem_author = '吴广霈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和水南方恒侄见寄 其一', '黄公辅', '明代', '几年湖海历岖欹，每忆园林是坦夷。陇上白云寻旧友，岩头绿树结新知。\n\n忘机野老时过访，得趣幽怀喜共披。况有骚人南北阮，可无促膝睹芳仪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和水南方恒侄见寄 其一' AND p.poem_author = '黄公辅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('迁江道中', '蓝智', '元代', '渺渺川云白，萧萧木叶黄。羸骖秋日短，倦鸟暮天长。\n\n不学疏儒术，无才愧宪纲。清风肃蛮徼，千古想虞唐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '迁江道中' AND p.poem_author = '蓝智';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九龙观', '黄希旦', '宋代', '峨峨古仙宫，楼殿荫松柏。昔在贞观年，天皇御区域。\n\n九龙出池中，遗下灵踪迹。嘉祐辛丑岁，郡侯得召伯。\n\n是时夏六月，云日红翕赩。殿北古龙堂，窗户久不辟。\n\n俄然灵蛇见，宛转真像侧。鳞甲锦绣文，灿烂辉五色。\n\n视之颇驯扰，狎之不惊惕。邯侯率群僚，朋来拥旌戟。\n\n迟留夜未午，风雨满天黑。迅电瞥四起，狂雷随一击。\n\n须臾风雨收，形影谁能觅。斯盖龙之灵，变化固难测。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九龙观' AND p.poem_author = '黄希旦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五石斋听雨', '韩上桂', '明代', '雨声滴沥转淋铃，久旱枯条尽欲青。五石恍攒云外出，半池疑杂涧中听。\n\n间支藤枕聊高卧，静掩柴扉且密扃。世事纷纭都不管，床头止有太玄经。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五石斋听雨' AND p.poem_author = '韩上桂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虎丘怀古', '朱朴', '明代', '行尽山塘是虎丘，题诗曾记昔年游。千人石在云长护，洗剑池空水自流。\n\n衰柳故宫阊阖晚，远峰斜日洞庭秋。江山不尽东归兴，千顷云边更倚楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虎丘怀古' AND p.poem_author = '朱朴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酒泉子·花映柳条', '温庭筠', '唐代', '花映柳条，闲向绿萍池上。凭阑干，窥细浪，雨萧萧。\n近来音信两疏索，洞房空寂寞。掩银屏，垂翠箔，度春宵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酒泉子·花映柳条' AND p.poem_author = '温庭筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('醉太平 赐学士沈度', '李忱', '明代', '浓云散雨收，花苑内鸣鸠。晓来喜见日光浮，暖融融永昼。\n\n麦苗润泽怀清秀，榴花湿映红光溜。田家歌舞尽歌讴，是处庆丰年醉酒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '醉太平 赐学士沈度' AND p.poem_author = '李忱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜行船', '孙浩然', '宋代', '何处采菱归暮。隔宵烟、菱歌轻举。白苹风起月华寒，影朦胧、半和梅雨。脉脉相逢心似许。扶兰棹、黯然凝伫。遥指前村，隐隐烟树，含情背人归去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜行船' AND p.poem_author = '孙浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('买陂塘 重游烟雨楼', '高燮', '清代', '二年前、鸳湖曾到，斜阳来问烟雨。那时犹记春归后，满地落花如絮。\n\n怀往古。便解得凄凉，解得伤心赋。沉吟不语。听衰柳鸣蝉，声声细碎，似识悲秋苦。\n\n休重数。更惹今番酸楚。此游兼乏俦侣。无心久向空庭玩，独倚阑干容与。\n\n君看取。剩有这、枯荷数梗临风舞。不成情绪。去败壁颓垣，几回寻觅，尚写旧诗句。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '买陂塘 重游烟雨楼' AND p.poem_author = '高燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('府酒五绝。招客', '白居易', '唐代', '日午微风且暮寒，春风冷峭雪乾残。 \n 碧毡帐下红炉畔，试为来尝一醆看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '府酒五绝。招客' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵上文潜丈', '蔡肇', '宋代', '张侯胸中包覆釜，百里奔流无寸土。\n玄蛟白鼍有时作，一洗乾坤三日雨。\n诗雄变怪有如引，震动犹能止啼乳。\n已倾太白酒船空，更压少陵饭山苦。\n昨朝东门同拜勅，玉齿犹残道中语。\n闭门十日无一事，坐对空庭秋叶舞。\n何时御史出霜台，便假前驺辞棘户。\n城南邀我倒余尊，紫栗黄橙已登俎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵上文潜丈' AND p.poem_author = '蔡肇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('瑞鹧鸪（除夜，依逆旅主人，寒雨不止，夜酌）', '卢炳', '宋代', '客里惊嗟又岁除。萧萧寒雨滴茅庐。山深溪转泉声碎，夜永风摇烛影孤。 \n 冷甚只多烧木叶，诗成无处写桃符。强酬节物聊清酌，今岁屠苏自取疏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瑞鹧鸪（除夜，依逆旅主人，寒雨不止，夜酌）' AND p.poem_author = '卢炳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西湖春日壮游即事 其一', '马臻', '元代', '绕湖无处避芳尘，叠鼓红旗彩鹢新。冉冉春云来不断，涌金门外踏青人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西湖春日壮游即事 其一' AND p.poem_author = '马臻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('亲郊恭纪三十首 其二十八 赐榼酒', '林熙春', '明代', '攒膳擎来自建章，银瓶复尔侑琼浆。恩波甚事频繁至，何怪中书求太常。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '亲郊恭纪三十首 其二十八 赐榼酒' AND p.poem_author = '林熙春';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天游许惠佛指柑以诗促之', '黄衷', '明代', '野客曾遗种树方，楚梅淮枳散林塘。仙根可结融泥润，新叶应分净土芳。\n\n寒碧有人同气味，青黄宁自秘文章。定知不是樊篱物，待看横秋万颗霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天游许惠佛指柑以诗促之' AND p.poem_author = '黄衷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜观昆剧', '宋词', '近代', '东南盛会百花开，雅部名班散复回。一代昆伶皆绝艺，群星捧出月轮来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜观昆剧' AND p.poem_author = '宋词';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雷峰', '董嗣杲', '宋代', '五级浮屠透泬寥，黄皮园上梵坊遥。当时雷就家曾弃，前代皇妃迹已销。\n\n铃带水风传古衕，灯分山月照长桥。根基自广云层减，拥肿难供画笔描。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雷峰' AND p.poem_author = '董嗣杲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白龙洞', '王世贞', '明代', '春雷地底发，匹练空中飞。毋劳久行雨，解旱便应归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白龙洞' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谚', '佚名', '唐代', '枣子塞鼻孔，悬栖阁却种。 \n 蝉鸣蛁蟟唤，黍种糕糜断。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谚' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登西山阁限韵', '李之世', '明代', '秋色来何处，空亭夕景衔。山情恬鸟雀，霜意宿松杉。\n\n寺近时闻钟，林疏忽辨帆。平芜踏歌遍，岚重湿衣衫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登西山阁限韵' AND p.poem_author = '李之世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('姚国秀十咏·信芳亭', '陈普', '宋代', '德馨何酷烈，同心皆与知。\n灵根在何许，暗室毋自欺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '姚国秀十咏·信芳亭' AND p.poem_author = '陈普';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暮春', '沈说', '宋代', '燕翼初乾渌满池，桑阴收尽麦黄时。\n一年春事又成梦，几日愁怀欲废诗。\n料理病身尝药遍，揩摩睡眼看书迟。\n悠然独倚阑干立，花下狸奴卧弄儿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暮春' AND p.poem_author = '沈说';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('定风波慢', '佚名', '宋代', '漏新春、消息前村，数枝楚梅轻绽。□雪艳精神，冰肤淡伫，姑射依稀见。冷香凝，金蕊浅。青女饶伊妒无限。堪羡。似寿阳妆阁，初匀粉面。纤条绿染。异群葩、不似和风扇。向深冬、免使游蜂舞蝶，撩拨春心乱。水亭边，山驿畔。立马行人暗肠断。吟恋。又忍随羌管，飘零千片。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '定风波慢' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('唐子两司锡学前后八年矣迁教授岳州以行锡诸生碑之以志去思', '王世贞', '明代', '聊携杏坛席，去上洞庭船。碑洒阳城泪，官深夏禹年。\n\n名缘却贽重，诗为解颐传。一问君山酒，何如第二泉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '唐子两司锡学前后八年矣迁教授岳州以行锡诸生碑之以志去思' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('周履道征赋梧桐月', '周翼', '明代', '云卷清秋画角悲，梧桐满地月明时。\n斜穿翠叶通银井，化作金波落砚池。\n青女喜惊乌鹊梦，素娥偏惜凤皇枝。\n故人有约来何暮，独立云阶影渐移。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '周履道征赋梧桐月' AND p.poem_author = '周翼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('熙宁蜡祭十三首', '佚名', '隋代', '皇皇灵德，经纽万方。\n承诏揶事，陟降以庄。\n高冠岌峨，长俩锵洋。\n嘉承神贶，令闻不忘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '熙宁蜡祭十三首' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七夕雨席上次陈平冈太史韵为 其一', '黄廷用', '明代', '仙人不易会，异岁一同盟。銮幄七香度，机丝五色成。\n\n云间惊节换，雨下映空明。欲别犹闻调，铿铿玉佩声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七夕雨席上次陈平冈太史韵为 其一' AND p.poem_author = '黄廷用';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬杜使君见寄', '贯休', '唐代', '轧轧复轧轧，更深门未关。心疼无所得，诗债若为还。 \n 露洒一鹤睡，钟馀万象闲。惭将此时意，明日寄东山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬杜使君见寄' AND p.poem_author = '贯休';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂曲歌辞。古离别', '王適', '唐代', '昔岁惊杨柳，高楼悲独守。今年芳树枝，孤栖怨别离。 \n 珠帘昼不卷，罗幔晓长垂。苦调琴先觉，愁容镜独知。 \n 频来雁度无消息，罢去鸳文何用织。夜还罗帐空有情， \n 春著裙腰自无力。青轩桃李落纷纷，紫庭兰蕙日氛氲。 \n 已能憔悴今如此，更复含情一待君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂曲歌辞。古离别' AND p.poem_author = '王適';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚秋閒步', '释文珦', '宋代', '晚来閒步阅秋光，田上人家尺涤场。\n远浦寒波浮雁鹜，荒山落日下牛羊。\n客鬓已非当日黑。菊花空似去年黄。\n因听翁媪言音异，又复令人忆故乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚秋閒步' AND p.poem_author = '释文珦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吊法空', '王质', '宋代', '鹤不胜癯汝更癯，平沙独立未为孤。雨花台上方知有，明月堂中竟省无。\n\n此夜吟风凭北固，何时乘月叩西湖。出头已解挑包走，试路西江问老夫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吊法空' AND p.poem_author = '王质';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄赵云溪', '朱谏', '明代', '今日若耶溪，不见采莲女。但见荡舟人，独坐孤篷底。\n\n放歌趁长风，馀音逐流水。一曲歌未终，白日落西海。\n\n红颜不再妍，青春岂长在。莲花空自开，溪声终不改。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄赵云溪' AND p.poem_author = '朱谏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵朱秀才二首 其二', '陈造', '宋代', '儒冠林立更鸿生，经倚菑畬道可耕。便合摘髭书桂籍，未须拥鼻避时名。\n\n似闻眕梦成三耳，会见惊人取一鸣。讲易露门谁第一，伫君重席振家声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵朱秀才二首 其二' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春·帐', '杨葆光', '清代', '天地为庐，网括洪荒，岂不快哉。灿红珠如斗，幽居小筑，白缣为里，复壁重开。\n\n殿指三云，图装五日，富丽风华点缀才。疑明月，拥生绡独坐，聚雪皑皑。\n\n安排。新样重裁。问若个销金醉饮来。想樱桃酣后，色萦缯线，芙蓉深处，清绝纤埃。\n\n玳瑁相兼，琉璃互映，贵主连珠早孕胎。同心结，有鱼龙鸾凤，七宝楼台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春·帐' AND p.poem_author = '杨葆光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('后庭花 咏燕', '王士禄', '清代', '浥尘小雨清明近。几番花信。重来玉剪双双趁。玳梁堪认。\n\n故巢新补芹泥润。落红相衬。流黄机畔人回瞬。陡添娇晕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '后庭花 咏燕' AND p.poem_author = '王士禄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自题望云图', '吴绍诗', '清代', '六十春光弹指过，百年心事半蹉跎。白云亭畔巢痕旧，天水楼边鸿印多。\n\n回首惊涛成幻影，仰天旭日曝寒柯。临崖暂倚华峰石，叆叇遥连北海波。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自题望云图' AND p.poem_author = '吴绍诗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉荅白岩诸公见怀联句', '边贡', '明代', '瞑鸟催归出寺门，长安风色已黄昏。林塘只隔水西渡，溪径故妨花外尊。\n\n星列𤨏垣占聚榻，月斜银浦怯回辕。清宵咫尺怀人地，海北天南未可论。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉荅白岩诸公见怀联句' AND p.poem_author = '边贡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题画', '王绂', '明代', '繁露陨黄叶，西风起白蘋。一声新雁过，惊却未归人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题画' AND p.poem_author = '王绂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自净土寺步至功臣寺', '苏轼', '宋代', '落日岸葛巾，晚风吹羽扇。松间野步稳，竹外飞桥转。\n\n神功凿横岭，岩石得巨片。直渡千人沟，下有微流泫。\n\n冈峦蔚回合，金碧烂明绚。缅怀异姓王，负担此乡县。\n\n长逢胯下辱，屡乞桑间饭。谁谓山石顽，识此希世彦。\n\n凛然英气逼，屹起犹耸战。他年万骑归，父老恣欢宴。\n\n锦绣被原野，金珠散贫贱。窦融既入朝，吴芮空记面。\n\n荣华坐销歇，阅世如邮传。惟有长明灯，依然照深殿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自净土寺步至功臣寺' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('澶州行', '刘炳', '明代', '澶州城头河水浑，南城北城如虎蹲。当年敌人犯畿甸，烽火照夜惊边尘。\n\n庙堂大臣惟肉食，幸南幸蜀俱身利。臣琼历练老知兵，臣准忠肝陈谠议。\n\n九关半夜一鸡鸣，大驾南征诏书出。虎臣武将争骏奔，龙旋豹尾如星屯。\n\n六军野宿犯霜雪，万乘路次昭风云。金节翠支先六辔，黄盖城头压妖彗。\n\n天戈晓渡国威张，神箭星驰敌将殪。重瞳一顾转乾坤，万岁山呼震天地。\n\n敌人气慑不敢当，稽首俯伏称诚惶。三边清宁海波霁，四野桑麦纷牛羊。\n\n至今惟有莱公庙，箫鼓年年歌岁康。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '澶州行' AND p.poem_author = '刘炳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题倪云林为薛鹤斋画竹', '虞堪', '明代', '云林写竹如琅玕，我昔爱之尝相看。凤凰去矣秋影独，白鹤归来辽海寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题倪云林为薛鹤斋画竹' AND p.poem_author = '虞堪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟中纳凉', '胤禛', '清代', '开遍芙渠水为香，疏槐鸦影乱昏黄。停舟待月寻佳句，卷幔吟风纳晚凉。\n\n渔笛数声飘远岸，茶烟一缕扬修篁。畅舒心志逢清夏，寂寂花阴漏正长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟中纳凉' AND p.poem_author = '胤禛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('【中吕】普天乐_酒谪仙强，', '滕斌', '元代', '酒\n\n谪仙强，刘伶缪。笑豪来鲸吸，有甚风流？聊复尔，无何有。酝酿潮红春风透，兴来时付与觥筹。频频到口，轻轻咂啖，少过咽喉。\n\n色\n\n百年身，千年债。叹愚夫痴绝，云雨阳台。人易老，心犹在。独倚阑干春风外，算人间少甚花开。春光过也，风僝雨僽，一叶秋来。\n\n财\n\n一瓢贫，千种富，是天生分定，何必枉图？锦步障，黄金坞。狗苟蝇营贪不足，为妻儿口体区区。君家饱暖，他人冻馁，于汝安乎？\n\n气\n\n少年时，风云志。记篇诗杯酒，颠倒群儿。吾善养，今方是。唾面来时休教拭，看英雄自古如痴。前程万里，饶人一步，却是便宜。\n\n柳丝柔，莎茵细。数枝红杏，闹出墙围。院宇深，秋千系。好雨初晴东郊媚，看儿孙月下扶犁。黄尘意外，青山眼里，归去来兮。\n\n昼偏长，人贪睡。新蝉高树，乳燕低飞。荷荡中，湖光内。款棹兰舟闲游戏，任无情日月东西。钓头锦鲤，杯中美酝，归去来兮。\n\n翠荷残，苍梧坠。千山应瘦，万木皆稀。蜗角名，蝇头利。输与渊明陶陶醉，尽黄菊围绕东篱。良田数顷，黄牛二只，归去来兮。\n\n朔风寒，彤去密。雪花飞处，落尽江梅。快意杯，蒙头被。一枕无何安然睡，叹邙山坏墓折碑。狐狼满眼，英雄袖手，归去来兮。\n\n日迟迟，江山丽。秋千影里，手握肩依。闹管弦，纷罗绮。我爱青山共流水，游一和困在苔矶。落花啼鸟，一般春意，归去来兮。\n\n晚天凉，薰风细。浮云黯淡，远水茫微。江水清，遥山碧。喜驾孤舟潇湘内，伴纶竿箬笠蓑衣。垂杨树底，芦花影里，归去来兮。\n\n淡烟迷，遥山翠。秋天雁唳，夜月猿啼。小径幽，茅檐僻。秋色南山独相对，傲西风菊绽东篱。疏林鸟栖，残霞散绮，归去来兮。\n\n暮霞收，彤云密。朔风凛冽，瑞雪纷飞。酒力微，茶烟湿。暖炕明窗绵绸被，尽前村开彻江梅。日高未起，黑甜睡足，归去来兮。\n\n叹光阴，如流水。区区终日，枉用心机。辞是非，绝名利。笔砚诗书为活计，乐虀盐稚子山妻。茅舍数间，田园二顷，归去来兮。\n\n仗权豪，施威势。倚强压弱，乱作胡为。我劝你，休窒闲。此等痴愚儿曹辈，利名场多少便宜。寻饥得饥，凭实得实，归去来兮。\n\n生乐涯，抛活计。麻绦草履，淡饭黄虀。遇酒歌，逢场戏。落落魄魄无萦系，那里管闲是闲非。游山玩水，埋名隐迹，归去来兮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '【中吕】普天乐_酒谪仙强，' AND p.poem_author = '滕斌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('点绛唇三月晦日于常熟虞山赋此送春', '张力夫', '当代', '石上淙淙，晚来泉壑飞花少。碧峰盘绕，松竹知归鸟。\n\n闲话维摩，闲对茶烟袅。春悄悄，梦痕鸿爪，一并消磨了。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '点绛唇三月晦日于常熟虞山赋此送春' AND p.poem_author = '张力夫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春尽有感', '卢儒', '明代', '浮云去住水西东，一度韶华又复空。\n多少春风归嫩柳，更无颜色向残红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春尽有感' AND p.poem_author = '卢儒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('迈陂塘/摸鱼儿·水车', '姚燮', '清代', '遇黄姑、微微社雨，霉时偏遇龙蛰。拘泥驾板分帘苇，费尽愁农周折。\n\n愁水竭。且愁绿成黄，辗转关心切。钩辀格磔。共笕竹横莎，戽绳挂柳，忙过稻花节。\n\n平畴错，谁画瓜南豆北。参差斜照明笠。却怜缫妇绹儿苦，支倦相偕助力。\n\n归犊叱。待晚饷粗完，未便贪凉息。一棚旱月，听缓约烟蝉，稳搀风蟪，疏唱更迢接。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '迈陂塘/摸鱼儿·水车' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题山居图卷', '钱选', '宋代', '山居惟爱静，白日掩柴门。\n寡合人多忌，无求道自尊。\n鷃鹏俱有意，兰艾不同根。\n安得蒙庄叟，相逢与细论。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题山居图卷' AND p.poem_author = '钱选';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晓晴 其一', '白玉蟾', '宋代', '昨夜天成雨，今朝水满池。睡酣浑不觉，想见竹声奇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晓晴 其一' AND p.poem_author = '白玉蟾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词', '朱权', '明代', '旋研花露试新妆，惹得游蜂上下狂。\n羞把香纨扑蝴蝶，对人佯整薄罗裳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词' AND p.poem_author = '朱权';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过建封寺下连鱼滩二首 其一', '杨万里', '宋代', '江收众水赴单槽，石壁当流斗雪涛。将取危舟飞过去，黄头郎只两三篙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过建封寺下连鱼滩二首 其一' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜蒲汀少宰卜邻', '边贡', '明代', '紫宸西畔白门东，鸡犬相闻巷陌同。家远正须君作侣，病多无奈我成翁。\n\n池光向月虚含冻，柳意归春弱袅风。珍重雪泥鸿爪迹，翻飞回首五云中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜蒲汀少宰卜邻' AND p.poem_author = '边贡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题杨补之梅花三叠图即用其韵 其一', '弘历', '清代', '一叠忆我三友轩，盆梅清供冬前早。修枝借得吴质能，剪綵宁逊隋宫巧。\n\n古香𧤏𧤏生面證，新月溶溶夜珠照。情知指日到江南，递来春信先觉好。\n\n旡咎此枝写其神，拂拂香风扑清晓。太璞上人何许人，相投自是诗禅老。\n\n隐名今乃盛传名，毕钵岩前刹竿倒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题杨补之梅花三叠图即用其韵 其一' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻孔氏女至', '李东阳', '明代', '南风吹送北河舟，有女东来慰白头。\n病里心情无那老，别来风景又经秋。\n鹊声报日书先到，雨脚干时泪始收。\n预想离程还在眼，难将一笑解千忧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻孔氏女至' AND p.poem_author = '李东阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪夜访戴图', '欧阳玄', '元代', '雪夜操舟童仆劳，偶然归去便称豪。若为返棹成佳趣，转忆当时不出高。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪夜访戴图' AND p.poem_author = '欧阳玄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('知州厅杏花昨日烂漫录事院今日零落唯副使公署未开戏题二韵', '王禹称', '宋代', '知州宅畔繁如雪，录事厅前落似梅。副使官闲花亦冷，至今未有一枝开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '知州厅杏花昨日烂漫录事院今日零落唯副使公署未开戏题二韵' AND p.poem_author = '王禹称';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉井亭观莲', '姚勉', '宋代', '几队红妆拥盖青，凌波仙子立娉婷。\n晚凉孤坐香风里，如在西湖四望亭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉井亭观莲' AND p.poem_author = '姚勉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('檐马', '缪鉴', '宋代', '铮铮金铁夜交锋，酷敌秋声杀气雄。战退晓天尘不动，依然横槊待西风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '檐马' AND p.poem_author = '缪鉴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登金台', '胡俨', '明代', '登高丘兮骋望，耿余怀兮太息。昔人兮眇绵，嘅千古兮一日。\n\n彼七雄兮虎斗。肆游谈兮辐凑。捭阖兮纵横，嗟仁义兮莫救。\n\n列馆兮筑宫。有来兮充充。诒谋兮未远，哀望诸兮不终。\n\n苟士修兮信美。岂千金兮能致。戋戋兮贲丘，何衒玉兮求贳。\n\n曦亭亭兮野苍。风萧萧兮落木黄。鸟群飞兮争栖，鸿冥冥兮高翔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登金台' AND p.poem_author = '胡俨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('史供奉群鹤', '梅尧臣', '宋代', '出珥银貂侍太清，回看双鹤舞中庭。\n翩翩曾是仙人骥，两两尚仪君子形。\n静夜欲还缑岭月，终朝思啑太湖萍。\n莫将树上鸡相并，会待归飞向杳冥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '史供奉群鹤' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过故翰林李慨之天心水面亭遗址', '汪广洋', '明代', '供奉归来已浪游，大明湖上贮清秋。十千美酒倾山雨，半百閒身对海鸥。\n\n水面风生杨柳岸，天心月过藕花洲。自从烂醉吹箫去，谁解临亭汎夕流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过故翰林李慨之天心水面亭遗址' AND p.poem_author = '汪广洋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜坐', '汪若楫', '宋代', '炉煨榾柮烟容冷，酒泻茅柴春色轻。\n夜坐不眠人悄悄，每梢随月绕窗行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜坐' AND p.poem_author = '汪若楫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一萼红　牡丹、水仙、君子兰、百合、康乃馨杂咏，用柳蓍卿韵', '刘斯翰', '当代', '晓成阴。更潺潺冻雨，年色正骎骎。高厦云簇，连街花绚，春意先动江浔。\n\n分素手、丛芳绣束，弄娇娆、偏惹护花心。百合水仙，乃馨君子，众美初临。\n\n玉盏薄摇香露，倚猩红细靥，默默情深。媚眼惺忪，洛姬湘女，一笑对舞开襟。\n\n几曾想、大唐妃子，矜国色、素面亚瑶簪？但止清芬在室，全胜兼金。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '一萼红　牡丹、水仙、君子兰、百合、康乃馨杂咏，用柳蓍卿韵' AND p.poem_author = '刘斯翰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('匏瓜道人，为徐子贞赋', '张昱', '元代', '吾岂匏瓜系此生，道人玩世以为名。百年雨露司荣悴，一日江湖见老成。\n\n濩落情怀庄子瓠，浮沉踪迹楚王萍。壶公借与龙为杖，抛著青鞋到处行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '匏瓜道人，为徐子贞赋' AND p.poem_author = '张昱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游光孝寺', '全祖望', '清代', '仲翔负直节，垂老乃投荒。饥啖荔支实，渴饮诃子汤。\n\n未知粤后进，阿谁为登堂。至今寓寮畔，书带尚成行。\n\n我亦肮脏人，南来漫鼓箧。浮屠不知儒，但礼六祖塔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游光孝寺' AND p.poem_author = '全祖望';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚望', '杨万里', '宋代', '天随楸枰作稻畦，啼乌振鹭当枯棋。不论胜负端何似，黑子终多白子稀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚望' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('为简敬画梅率题二绝 其一', '曹家达', '清代', '光明何处著纤埃，湖树湖烟落酒杯。好和晋陵游望咏，柳边风信渡江来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '为简敬画梅率题二绝 其一' AND p.poem_author = '曹家达';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和颜长官百咏·客路', '朱继芳', '宋代', '屈指秋风与雁期，阳关西去到何时。\n侧身一望肠堪断，天似穹庐碧四垂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和颜长官百咏·客路' AND p.poem_author = '朱继芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岁晚四首 其一', '李彭', '宋代', '天长候雁作行远，沙晚浴凫相对眠。松醪朝醉复暮醉，江月下弦仍上弦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岁晚四首 其一' AND p.poem_author = '李彭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('徐珍伯招游惠州西湖得西字', '徐勃', '明代', '十里湖山碧树齐，遥闻钟磬出招提。\n万家暮霭鹅城北，一抹残阳鹫岭西。\n菱叶风浮浅水，蓼花吹浪过长堤。\n苏公此地曾游咏，自愧诗成不敢题。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '徐珍伯招游惠州西湖得西字' AND p.poem_author = '徐勃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('韵和胡心斋先生陪“游沧浪亭赋记”二首 其二', '杨民仁', '近代', '黄花山石两玲珑，石转花香一路东。留得墙碑名士笔，拨开茅塞拓心胸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '韵和胡心斋先生陪“游沧浪亭赋记”二首 其二' AND p.poem_author = '杨民仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送上竺隐箕山法师', '胡奎', '明代', '五天竺国前朝寺，八十三年出世僧。月下眼能看细字，云中手不拄枯藤。\n\n天厨甘露朝朝饭，丈室生花夜夜镫。鹿苑證成无上觉，牛车说破最初乘。\n\n春深又送花间鸟，湖水都消雪后冰。明日远山遥在望，上方台殿翠层层。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送上竺隐箕山法师' AND p.poem_author = '胡奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送王宇斋还安福四首 其二', '王渐逵', '明代', '士有旷世而相感，况复三接羊城间。峰头载酒不得对，江水江花生怅颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送王宇斋还安福四首 其二' AND p.poem_author = '王渐逵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜晴', '弘历', '清代', '膏泽既沾渥，望晴人所同。况值西成候，尤需阊阖风。\n\n树杪习习来，天宇徐徐空。絮云忽尽敛，暅阳悬当中。\n\n郁陶千虑涤，晶光万里融。乃知雨旸时，统维大造功。\n\n我非蚩蚩氓，敢云憾彼穹。过望或有诸，卒岁心焉穷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜晴' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送顾观察之蓟中二首 其二', '胡应麟', '明代', '铜柱威名播粤都，楼船勋业遍江湖。行边首定周王策，出塞新分汉使符。\n\n倚剑苍龙鸣涿鹿，扬鞭白马照飞狐。从知幕下多词客，彩笔班生定有无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送顾观察之蓟中二首 其二' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('淳熙乙未登科是夏再中教官得绍兴府教授秋末还家待阙时杨枢密为帅送程先生赴省八绝句 其三', '项安世', '宋代', '向来多士首何方，此学巍然道有光。付与能言子程子，莫教章蔡更专场。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '淳熙乙未登科是夏再中教官得绍兴府教授秋末还家待阙时杨枢密为帅送程先生赴省八绝句 其三' AND p.poem_author = '项安世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望江南六十四阕 其三十七', '高燮', '清代', '山庐好，无物不忘机。洗砚招鱼吞墨饱，曝书遇蠹食仙肥。\n\n他日或能飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望江南六十四阕 其三十七' AND p.poem_author = '高燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次易实甫观察即席韵', '丘逢甲', '清代', '丝竹当筵酒复醇，兹游未负岭南春。落花风雨逢今日，香草沅湘见美人。\n\n门第乌衣笑王谢，文章蝉噪薄梁陈。平生雅忆横江楫，愧向江东作寄民。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次易实甫观察即席韵' AND p.poem_author = '丘逢甲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('到梅山次韵弟茝', '陈著', '宋代', '相对两衰翁，此心无复童。\n幸叨无事坐，贫欠有钱通。\n菜粥琴书画，梅花雪月风。\n黄尘在门外，劳隐是英雄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '到梅山次韵弟茝' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贤者之孝二百四十首 其一七八 袁君正', '林同', '宋代', '家人劝我睡，共说不眠难。官既未得差，眠时自不安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贤者之孝二百四十首 其一七八 袁君正' AND p.poem_author = '林同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('幽斋清兴二首 其二', '叶颙', '元代', '岚光浮户牖，竹色上栏干。吹笛惊秋老，弹琴生夜寒。\n\n唤猿来月下，放鹤出云端。长负江湖兴，西风一钓竿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '幽斋清兴二首 其二' AND p.poem_author = '叶颙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('予顷从穰下移涖河阳洎出中书复领分陕惟兹二', '寇准', '宋代', '岸阔樯稀浪渺茫，独凭危槛思何长。\n萧萧远树疏林外，一半秋山带夕阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '予顷从穰下移涖河阳洎出中书复领分陕惟兹二' AND p.poem_author = '寇准';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浩歌行十章 其八', '姚燮', '清代', '海天六月秋风早，倒影空城水云皂。城根江色接荒苇，城上斜阳照黄草。\n\n流鸿盘阵向平陌，乱点纷随落叶扫。觅食不得声嘷嘷，夕树霜重栖无巢。\n\n雁门万里西北高，健儿臂矢腰悬刀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浩歌行十章 其八' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('建昌渡暝吟', '韦庄', '唐代', '月照临官渡，乡情独浩然。鸟栖彭蠡树，月上建昌船。 \n 市散渔翁醉，楼深贾客眠。隔江何处笛，吹断绿杨烟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '建昌渡暝吟' AND p.poem_author = '韦庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百零二首 其二十八', '释绍昙', '宋代', '鈯斧埋藏岁月深，岩居日与白云邻。业风无奈重飘鼓，又作担柴卖筊人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百零二首 其二十八' AND p.poem_author = '释绍昙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游钟山诗应西阳王教', '沈约', '南北朝', '发地多奇岭。\n干云非一状。\n合沓共隐天。\n参差互相望。\n郁律构丹巘。\n崚嶒起青嶂。\n势随九疑高。\n气与三山壮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游钟山诗应西阳王教' AND p.poem_author = '沈约';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('琅琊溪', '满执中', '宋代', '岩下桃花红，溪流碧如玉。逋翁隔云歌，不是人间曲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '琅琊溪' AND p.poem_author = '满执中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和李蓝溪梅花韵', '黄庚', '宋代', '南枝开遍北枝开，祗恐飞香落砌苔。\n踏雪诗人应癖好，杖藜日日为诗来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和李蓝溪梅花韵' AND p.poem_author = '黄庚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿太师 其二', '吴顺之', '宋代', '南北通和自古无，如今万里混车书。传闻每遣皇华使，外国人争问起居。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿太师 其二' AND p.poem_author = '吴顺之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('关陇平 其五', '叶方霭', '清代', '海涉河泾，言腾灞浐。秦山矗突，嵚崎陇坂。逾邠越凉，飞旓扬旆。\n\n扶舆猗靡，云罕綷䌨。雍部阻长，敢惮痡瘏。式遏寇虐，以宁尔室家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '关陇平 其五' AND p.poem_author = '叶方霭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陪道先兄游麻源辄赋二小诗 其一', '吕南公', '宋代', '借得篮舆便出城，山光门外望西行。昨宵偶雨路尘少，今日好风林霭轻。\n\n有竹人家庭院秀，避驺樵客面颜生。溪田桥北驼鞍岭，犹记当年志未平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陪道先兄游麻源辄赋二小诗 其一' AND p.poem_author = '吕南公';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵怀古', '释保暹', '宋代', '石城秋月满，烟水冷萧萧。\n战气悲千古，歌声散六朝。\n萤飞宫草暗，霜白井桐凋。\n竟日秦淮上，思贤莫可招。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵怀古' AND p.poem_author = '释保暹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题王声甫松坡樵苦唱后', '文天祥', '宋代', '倚柯睨苍髯，短簑挟风雨。\n谈道谁我知，对弈者其侣。\n狂吟发悲调，谷鸣相律吕。\n扊扅岂不怨，宁售大夫股。\n长镵斸仙苓，获薪为吾煮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题王声甫松坡樵苦唱后' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元宵菊', '张应渭', '清代', '百卉争妍岁已新，秋容点缀最宜人。飧英绛县颜如赭，载酒柴桑日正新。\n\n好与炎时同炙手，故将冷艳压寒津。灯宵无限衔杯兴，篱畔黄花也醉春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元宵菊' AND p.poem_author = '张应渭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湖上晚归', '钱龙惕', '清代', '肠断湖山列画屏，断桥残日半湖明。逋仙祠畔销残暑，鄂国坟边恨晚程。\n\n娅姹佳人红芰湿，风标公子白鸥轻。篮舆渐逐高峰远，惆怅银钩月乍生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湖上晚归' AND p.poem_author = '钱龙惕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游赤松观', '范浚', '宋代', '灵祠丹井馀真迹，祠下老松森百尺。仙子骑鲸去不归，痴人犹问山中石。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游赤松观' AND p.poem_author = '范浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹色', '屈大均', '明代', '竹色楼前满，松声屋后多。风吹山影去，云拂水痕过。\n\n秋使神明爽，春将笑语和。醇醪君不饮，当奈好莺何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹色' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙', '谷海鹰', '当代', '柳絮黏春飏绮梦，撩红半圃蔷薇。斜阳心事彩云知。\n\n归禽啼落蕊，新翠浴金辉。\n\n忙处情閒閒处闷，小窗探出柔荑。轻绒堕手又扇飞。\n\n无端成聚散，久伫一低眉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙' AND p.poem_author = '谷海鹰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('罗汉阁煎茶应供', '葛闳', '宋代', '山泉飞出白云寒，来献灵芽秉烛看。\n俄頃有花过数百，三瓯如吸玉腴乾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '罗汉阁煎茶应供' AND p.poem_author = '葛闳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿巩华城王将军宅', '区大相', '明代', '将军躩跞翁，壮岁事从戎。枥敝闲嘶骑，尘韬久挂弓。\n\n笳声来远塞，树影过离宫。只为时平久，农谈终夕同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿巩华城王将军宅' AND p.poem_author = '区大相';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白云歌寄陆中丞使君长源', '皎然', '唐代', '一见西山云，使人情意远。凭高发咏何超遥， \n 道妙如君有舒卷。萦空叠景多丽容，众峰峰上自为峰。 \n 洁白不由阴雨积，高明肯共杂烟重。万物有形皆有著， \n 白云有形无系缚。黄金被烁玉亦瑕，一片飘然污不著。 \n 或逢天上或人间，人自营营云自闲。忽尔飞来暂为侣， \n 忽然飞去莫能攀。逸民对云效高致，禅子逢云增道意。 \n 白云遇物无偏颇，自是人心见同异。阊阖天门宜曙看， \n 为缨作盖拥千官。从龙合沓临清暑，就日逶迤绕露寒。 \n 谁怜西山云，亭亭处幽绝。坐石长看非我羁， \n 手中欲揽待君说。贞白先生那得知，只向空山自怡悦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白云歌寄陆中丞使君长源' AND p.poem_author = '皎然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('欲明', '韩偓', '唐代', '欲明篱被风吹倒，过午门因客到开。忍苦可能遭鬼笑， \n 息机应免致鸥猜。岳僧互乞新诗去，酒保频征旧债来。 \n 唯有狂吟与沈饮，时时犹自触灵台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '欲明' AND p.poem_author = '韩偓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吕清夷过宿东山寓楼拈韵得秋字', '李洸', '近代', '在树群鸦聒未休，片云梳洗日西流。重来城郭非邪是，照梦江潮忧不秋。\n\n一雨谢安犹系望，九天屈子竟离忧。开门纵有孤行想，忍见斯人独倚楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吕清夷过宿东山寓楼拈韵得秋字' AND p.poem_author = '李洸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江上', '赵崇鉘', '宋代', '清露初生红蓼秋，爽风先到木兰舟。\n钓丝不捲波痕稳，梦入芦花数白鸥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江上' AND p.poem_author = '赵崇鉘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('骊山感事', '张咏', '宋代', '古来仁圣最忧多，合倚承平纵逸么。\n行幸未停歌未阕，羯胡兵已渡黄河。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '骊山感事' AND p.poem_author = '张咏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东廓先生贻连山书屋落成诗次韵奉赠', '罗洪先', '明代', '忆从石屋访行窝，几共云关掩薜萝。一见自惭违道远，无言更觉饮人和。\n\n六经同异多新语，万物逍遥有浩歌。窃比舞雩吾所志，年年将奈暮春何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东廓先生贻连山书屋落成诗次韵奉赠' AND p.poem_author = '罗洪先';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四月三日与家小人酌转官球花因花八句略为花', '陈著', '宋代', '红芳销歇后，天质最分明。\n剪衬青云薄，团成白雪轻。\n官途荣进取，时样妄推评。\n本色相看处，幽窗不世情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四月三日与家小人酌转官球花因花八句略为花' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自赣上南安川路甚曲未至南康县已有三十六湾舟人称为湘江湾云 其三', '屈大均', '明代', '曲似湘江色不如，湘江空翠映芙蕖。衡山九面皆临镜，清绝尤宜烟雨馀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自赣上南安川路甚曲未至南康县已有三十六湾舟人称为湘江湾云 其三' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠赵签', '张孝祥', '宋代', '赵侯富贵种，自有岩壑姿。同姓古所敦，早晚踏天墀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠赵签' AND p.poem_author = '张孝祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠城南观音院庵主广师', '文同', '宋代', '簿领日婴薄，纷然汩幽襟。\n驾言出城南，聊欲清此心。\n平冈见净刹，石通郁以深。\n中有苦空人，峭健奇骨森。\n十年一庵下，形迹了莫寻。\n兀如拥败褐，口吐众妙音。\n时下寂照堂，声绝响亦沈。\n默矣盖自得，其谁知少林。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠城南观音院庵主广师' AND p.poem_author = '文同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('远将归', '胡仲弓', '宋代', '不勘图经认地名，亦知此去近桐城。\n行人未至心先至，羞胜离家第一程。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '远将归' AND p.poem_author = '胡仲弓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏剑限巢郊胶坳抛韵', '许传霈', '清代', '本同冠佩宝书巢，利试昆吾莫易抛。一剑勋名留汉楚，三贤宠赐重庠胶。\n\n干将神物藏山谷，河曲金人出水坳。何日销为农父器，田功有事向东郊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏剑限巢郊胶坳抛韵' AND p.poem_author = '许传霈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三多谣 其一', '弘历', '清代', '天下多富者，宜莫过为君。夕惕复朝乾，畏天而畏民。\n\n讵惟多事忧，其忧难悉陈。恣欲满而溢，斯乃致祸根。\n\n人言予无乐，吾谓良苦辛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三多谣 其一' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔家傲 次韵答李蒲汀四阕 其二', '夏言', '明代', '宝泽楼前日初雾。鹤鸣惊起高斋睡。酌酒听歌金缕细。\n\n醒还醉。无人解得山翁意。\n\n闲弄渔舟烟水际。茅亭小结依岩桧。竹影月明金琐碎。\n\n清梦寐。诗成语带烟霞丽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔家傲 次韵答李蒲汀四阕 其二' AND p.poem_author = '夏言';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望江南 同嫂氏过绿雪山房感赋二首 其一', '高縏', '清代', '山房里，往事足追寻。晓阁校书同问字，午窗斗茗罢拈针。\n\n一局向花阴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望江南 同嫂氏过绿雪山房感赋二首 其一' AND p.poem_author = '高縏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('史应之赞', '黄庭坚', '宋代', '眉山史应之，爱酒而滑稽。\n对鄙不肖，醉眼一笑。\n司马德操，万事但好。\n东方戏嘲，惊动汉朝。\n穷则德操，达则方朔。\n天地一壼，不胶者卓。\n应之老矣，似愚不愚。\n江安食不足，江阳酒有余。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '史应之赞' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵谢人惠诗', '晁说之', '宋代', '东郊久不开，春风宜断绝。\n梅信岂得芳，何处香芬烈。\n徒令湖海士，借论古人杰。\n奈我贫病何，萧寺多积雪。\n终天不出门，图史欣罗列。\n欲上皇帝书，庙堂谁稷契。\n游鱼清且直，飞鹭远更洁。\n顾彼四轮车，御侮难结辙。\n一朝叩旅舍，问我来何说。\n再拜谢之子，我正如自拙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵谢人惠诗' AND p.poem_author = '晁说之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七月六日夜对月口占甲申', '常燕生', '近代', '雨过天晴世界凉，冰盘净洗出光芒。何须更待中秋月，从古嫦娥爱夏妆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七月六日夜对月口占甲申' AND p.poem_author = '常燕生';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿山中寺', '李中', '唐代', '寄宿深山寺，惟逢老病僧。风吹几世树，云暗暮秋灯。 \n 瞑目忘尘虑，谈空入上乘。明晨返名路，何计恋南能。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿山中寺' AND p.poem_author = '李中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闺怨一百二十首 其六十五', '孙蕡', '明代', '画笼鹦鹉日啁啾，自与离人替说愁。戏掷枇杷打金羽，儿夫去后忆奴否。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闺怨一百二十首 其六十五' AND p.poem_author = '孙蕡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西苑宫词二十四首有序 其八', '张元凯', '明代', '夕烽千里照甘泉，一纸降魔敕已传。急遣六丁乘羽驾，火轮金甲净幽燕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西苑宫词二十四首有序 其八' AND p.poem_author = '张元凯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郊行感事', '王又旦', '清代', '酒入愁肠恰半升，东郊林下杖枯藤。心随夜半移枝鹊，身似门前饭粥僧。\n\n绿树饱酣山径雨，东风初泮大河冰。独怜亭尉今皆醉，不敢寻春过灞陵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郊行感事' AND p.poem_author = '王又旦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暨阳克复渡江纪事八首 其七', '陈式金', '清代', '顽民恃乱益鸱张，醉饱呼卢四载忙。农具尽焚人被掳，田芜屋毁叹洪荒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暨阳克复渡江纪事八首 其七' AND p.poem_author = '陈式金';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日次前辈新年韵', '陆游', '宋代', '残年垂九十，云鬓不胜繁。\n卖屦籴炊米，典衣租废园。\n山深云满屋，夜静月当门。\n邻曲时相过，扶行赖稚孙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日次前辈新年韵' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('醉公子•挑棋', '董以宁', '明代', '小姑敛衽拜。嫂嫂妆台下。乞早整莲衣，花间去赌棋。\n\n杏钗多戴个，停会来输我。若倩小哥帮。输时拔一双。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '醉公子•挑棋' AND p.poem_author = '董以宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗', '姚范', '清代', '逾淮植南橘，北土夸所奇。经时感物化，枳枸肖拳枝。\n\n橘枳虽有异，颇来众禽栖。当春发婀娜，纷溶从风披。\n\n鸣嘒协丝簧，毛羽矜缡褷。树下一徘徊，主人颜为怡。\n\n区区草木疏，讵足分高卑。养之至合抱，慎勿召工师。\n\n苟用充梁柱，不觉酒味醨，酒醨何足惜，将令众宾嗤。\n\n何如植中庭，啾啾群鸟嬉。吾怜夏仲御，散发希黄虞。\n\n苟充螊𧑅养，何羡青紫纡。一朝入京洛，名动贾公闾。\n\n宛转飞鹢首，跌荡引鯆䱐。河水诧清激，小海徒欷歔。\n\n嗟哉面目旋，白汗竟何如。灵谈与鬼笑，奚以喻丹珠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗' AND p.poem_author = '姚范';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('村居', '薛瑄', '明代', '乔木荒村古，归来遂所居。人情安瓦落，机事识舟虚。\n\n岁晚霜横野，宵长月照书。心田恐芜没，不敢废耘锄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '村居' AND p.poem_author = '薛瑄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('莲社图', '陈琏', '明代', '义熙人物总英贤，道契机缘岂偶然。五老峰前同结社，三生石上共谈禅。\n\n雨馀瀑布飞晴雪，日出香炉生紫烟。千载高风无觅处，空将仪像画图传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '莲社图' AND p.poem_author = '陈琏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荆州新秋病起杂题一十五首·病起见庭石', '齐己', '唐代', '病起见庭石，岂知经夏眠。不能资药价，空自作苔钱。\n翠忆蓝光底，青思瀑影边。岩僧应笑我，细碎种阶前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荆州新秋病起杂题一十五首·病起见庭石' AND p.poem_author = '齐己';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西华道中', '张耒', '宋代', '我行陈许郊，千里平若掌。\n居民杂荆榛，耕少地多旷。\n野兔乍跳奔，惊鸢或高扬。\n乔林多疾风，寒涧有余涨。\n棘篱蔽茅屋，鸡犬入村巷。\n主人扫土榻，秣马具朝饷。\n童儿汲土井，败饭堆瓦盎。\n忽悲为生陋，自足无他望。\n嗟予走薄宦，奔走年将壮。\n长抱羁旅愁，何时税归鞅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西华道中' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湖口守风作 其六', '屈大均', '明代', '鹧鸪元有志，岂畏朔天寒。日是罗浮早，花惟涨海丹。\n\n将归儿女喜，未到水风难。清绝高堂月，犹从梦里看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湖口守风作 其六' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('立春帖子 其四 太上皇帝阁', '周必大', '宋代', '青阳布治周三纪，黄屋非心正九年。圣子有为今出震，天公不宰旧乘乾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '立春帖子 其四 太上皇帝阁' AND p.poem_author = '周必大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句容县茅山观道官东白能文章且长于诗予无以为寿集杜子美诗二十句以赠', '解缙', '明代', '冰壶玉衡悬清秋，神仙中人不易得。往时文采动人主，自怪一日声辉赫。\n\n忆昨逍遥供奉班，风雨不动安如山。词源倒流三峡水，时闻杂佩声珊珊。\n\n先生早赋归去来，鲸鱼跋浪沧溟开。致身福地何萧爽，石田茅屋荒苍苔。\n\n绣衣春当霄汉立，云近蓬莱常五色。池上于今有凤毛，秋水为神玉为骨。\n\n百花潭水即沧浪，星宫之君醉琼浆。西望瑶池降王母，南极老人应寿昌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句容县茅山观道官东白能文章且长于诗予无以为寿集杜子美诗二十句以赠' AND p.poem_author = '解缙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('有僧欲礼清凉而未决来索予诗戏书四绝句 其二', '李流芳', '明代', '闻道边风最苦寒，风头起处欲行难。中台积雪深无路，处处封门不出看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '有僧欲礼清凉而未决来索予诗戏书四绝句 其二' AND p.poem_author = '李流芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('好事近', '魏元戴', '清代', '三泖五湖中，失却澄鲜空碧。惆怅惊涛靡定，更层冰澌结。\n\n天容惨澹俯扁舟，圆影暗孤笠。向晚叩舷歌罢，有沙鸥相识。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '好事近' AND p.poem_author = '魏元戴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送文澜开馆清江用芝山舍弟韵席上 其二', '霍与瑕', '明代', '夏夜飞萤火，空山乱趁人。收拾书囊里，三更供苦辛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送文澜开馆清江用芝山舍弟韵席上 其二' AND p.poem_author = '霍与瑕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东皋杂兴 其二', '释妙声', '明代', '茅斋政在溪水西，水边杨柳拂人低。溪童荡漾唱歌过，惊起月中乌夜啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东皋杂兴 其二' AND p.poem_author = '释妙声';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和王弱翁白沙道中', '范纯仁', '宋代', '共驱羸马蹑寒芜，景色鲜明近洛都。出谷流泉春更绿，隔林幽鸟暮相呼。\n\n伊川旧赏疑朝梦，少室重看胜画图。从此便穷山水乐，相从应不厌崎岖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和王弱翁白沙道中' AND p.poem_author = '范纯仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题广雅书院', '黄节', '清代', '绝业催人过壮年，再来林木亦参天。棠梨半落春将晚，祠屋长虚草漫沿。\n\n曾见讲堂屯马队，坐闻幽鸟语寒烟。闲闲且了区中事，池上黄淤已种莲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题广雅书院' AND p.poem_author = '黄节';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百三十三首 其六十四', '释法薰', '宋代', '一径直，二周遮。擒虎兕，辨龙蛇。白玉无瑕却有瑕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百三十三首 其六十四' AND p.poem_author = '释法薰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('少年行', '姚宽', '宋代', '少年白鼻騧，玉勒锦连韉。\n径就胡姬饮，熟醉当垆眠。\n剥丝入蚕茧，郎意在缠绵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '少年行' AND p.poem_author = '姚宽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西户', '许及之', '宋代', '勋业镜成斑，光阴箭能疾。明时贳此翁，不须绳系日。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西户' AND p.poem_author = '许及之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古一百首', '释智愚', '宋代', '万仞岩头拚得去，不知何处觅全尸。\n业风吹起再甦醒，却问如今是甚时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古一百首' AND p.poem_author = '释智愚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('迎春曲', '刘炳', '明代', '燕梁綵飘金凤喧，翠襟小儿双髻悬。珊瑚鞭拆金锁掣，九地神牛飞上天。\n\n东郊辘轳鸣紫犊，绿芜一片玻璃縠。柳眉桃脸红菲菲，东园蝴蝶西园飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '迎春曲' AND p.poem_author = '刘炳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴江赠顾茂伦 其一', '屈大均', '明代', '月出采香洲，吴娘唱柂楼。垂虹杨柳暗，莺脰白蘋秋。\n\n故国苍茫别，美人迟暮愁。夫君若萱草，一见即忘忧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴江赠顾茂伦 其一' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('永遇乐 病中', '徐灿', '清代', '翠帐春寒，玉炉香细，病怀如许。永昼恹恹，黄昏悄悄，金博添愁炷。\n\n薄幸杨花，多情燕子，时向琐窗细语。怨东风、一夕无端，狼藉几番红雨。\n\n曲曲阑干，沉沉帘幕，嫩草王孙归路。短梦飞云，冷香侵佩，别有伤心处。\n\n半暖微寒，欲晴还雨，消得许多愁否。春来也、愁随春长，肯放春归去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '永遇乐 病中' AND p.poem_author = '徐灿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送詹少游之平江', '王炎', '宋代', '溪上相逢把盏时，回头今是一年余。\n闻君有喜驱都骑，顾我无聊守敝庐。\n信道此行骑凤背，未知何日寄鱼书。\n月明千里关山隔，莫为新情忘故居。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送詹少游之平江' AND p.poem_author = '王炎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('废屋', '何景明', '明代', '废屋空山里，风沙不见人。坏墙惟有径，独树更无邻。\n\n寇盗三关逼，徵求万国频。江湖暮摇落，回首一沾巾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '废屋' AND p.poem_author = '何景明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六十年的变迁', '聂绀弩', '近代', '辛亥之前清已危，武昌十日以为期。千年古国除君主，一夜新军举义旗。\n\n半世纪来无此作，中山死后有余悲。军机误在孱儿手，痛哭元戎刘复基。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六十年的变迁' AND p.poem_author = '聂绀弩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('巴夷', '潘希曾', '明代', '巴夷依洞险，茶漆足营生。不解通名字，粗知听使令。\n\n狼心终叵测，鸟语自相惊。未暇图王会，编诗记远行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '巴夷' AND p.poem_author = '潘希曾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送九江潘同知赴任', '倪岳', '明代', '水部潘翁老圣朝，却看雏凤起冲霄。一官高占人中选，二守尊居郡上僚。\n\n地接江东民最朴，水通湖口路非遥。荣亲志遂堪迎养，百斛方舟稳趁潮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送九江潘同知赴任' AND p.poem_author = '倪岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赋得揽察草木犹未得示诸子五首 其五', '谢元汴', '明代', '鞭石驱山九日燀，文人何用强谈天。黄星靡聘河图出，枉矢西流金虎迁。\n\n郑客璧知龙死岁，南州鹤语尧崩年。蚪蝌化烬微言绝，星拜缥簪北斗前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赋得揽察草木犹未得示诸子五首 其五' AND p.poem_author = '谢元汴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄越中诸友', '孙一元', '明代', '自别西湖上，逃名人不闻。饭甘黄独味，身在野鸥群。\n\n俗病难相恼，静居已策勋。何时还一笑，采秀入閒云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄越中诸友' AND p.poem_author = '孙一元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆亲 其二', '石宝', '明代', '鹤发童颜会面难，况将歌酒奉深欢。南风已入高秋树，才得归鸿一问安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆亲 其二' AND p.poem_author = '石宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与孟依依约赋戒台寺牡丹时方暮春花谢殆尽先成三章以寄 其三', '李梦唐', '当代', '何事看花到佛前，春风有力破禅关。江郎词笔今萧瑟，尚可从君赋牡丹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与孟依依约赋戒台寺牡丹时方暮春花谢殆尽先成三章以寄 其三' AND p.poem_author = '李梦唐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄蒋道林 其三', '王渐逵', '明代', '秋月秋风动远思，衡阳归雁暗相期。何当鼓柁湘江上，岣嵝峰头读禹碑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄蒋道林 其三' AND p.poem_author = '王渐逵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('靠袋睡赞', '释绍昙', '宋代', '自与尘劳交辊，肚里千机万变。\n虽然靠布被头，疑你睡得未稳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '靠袋睡赞' AND p.poem_author = '释绍昙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('用韵酬侯居甫', '许及之', '宋代', '玉树风前映玉峰，吾家安得此乘龙。书林未照青藜杖，甥馆肯陪高节筇。\n\n归棹喜闻明月载，哦诗想带夕阳钟。从今社里添光宠，咳唾珠玑有仲容。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '用韵酬侯居甫' AND p.poem_author = '许及之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南浦 蔡冰吾大愚别廿五年矣，闻其在汉皋，以水龙韵寄之，冰吾依此调见答，用韵酬之', '周岸登', '清代', '怀冰抱蜀，廿年来、豪士惜分张。君也驰驱关陇，沙碛阵云黄。\n\n我亦壮游三管，伴飞鸢、跕跕下蛮江。叹市朝都换，旧人谁在，留眼看沧桑。\n\n漫比退飞宋鹢，好江山、乘兴莫凄凉。玉笛楼中吹起，声彻鹤家乡。\n\n怕问故山猿鸟，共虫沙、一例话兴亡。效楚累哀怨，国魂招复应天长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南浦 蔡冰吾大愚别廿五年矣，闻其在汉皋，以水龙韵寄之，冰吾依此调见答，用韵酬之' AND p.poem_author = '周岸登';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登高分得叠嶂', '丁复', '元代', '远近不可数，澹浓浑自成。人烟诸崦隔，鸟道半空横。\n\n日夕黄微映，江寒碧倒生。凭高共临眺，忆得在宣城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登高分得叠嶂' AND p.poem_author = '丁复';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('用元韵答徐幼文', '王炎', '宋代', '身行宦路固多虞，梦到清都厌积苏。\n欲返初心观易老，懒开辨口学岩吾。\n有怀拟作西征赋，无策堪陈北伐图。\n才具如公宜颍脱，不应空谷老唐衢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '用元韵答徐幼文' AND p.poem_author = '王炎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观文殿大学士刑部尚书赠左仆射兼侍中刘公挽辞三首 其二', '苏颂', '宋代', '星坠寝门夕，鵩来州舍辰。人悲丧遗爱，帝梦失良臣。\n\n勋业经纶远，文章气燄新。殁犹荣故里，宸笔镂坚珉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观文殿大学士刑部尚书赠左仆射兼侍中刘公挽辞三首 其二' AND p.poem_author = '苏颂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江晚泛因怀邓梁二山人', '李之世', '明代', '西江何清浅，回合卓冈岑。虽自非吾土，依然生远心。\n\n予徒牵物役，尔辈足山林。倘许从初服，薜萝春正深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江晚泛因怀邓梁二山人' AND p.poem_author = '李之世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('猗欤诗', '宋濂', '元代', '猗欤君子，在括之阳。餐然其章，有玉其相。厥声孔扬，声之伊何。\n\n如岩之峨峨，不刿不颇，屹立而弗阿。塞庭远而，其势绵如。\n\n酣如连如，贪噬我中区。君子扬扬，为天子使。诞敷皇灵，以詟其类。\n\n彼何人斯，是絷是维，不虞其无知。彼何人斯，是维是絷，不恤其无拂。\n\n我金其躬，我赤其衷。我节之崇，以迄于终。皦尔之行，孰能尤之。\n\n真尔之刚，孰能柔之。㳺麟之冲冲兮。鸣凤之嗈嗈兮。\n\n我思君子，维邦之容兮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '猗欤诗' AND p.poem_author = '宋濂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('道过徐山玉吴仲退来会宿别后作寄', '黎廷瑞', '宋代', '扶舆蹋残照，怀人度青林。\n一笑得二妙，坐看西月沉。\n短烛摇古碧，华樽湛芳斟。\n高歌击唾壶，琅琅出商音。\n东风行空山，和以苍松吟。\n飘飖洞庭乐，要渺南薰琴。\n天地空阔远，岁晚谁知心。\n相对成浩叹，忘言拥单衾。\n东方忽已白，握别西山阴。\n违离未云远，怀思一何深。\n常恐蕙帐空，此乐难重寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '道过徐山玉吴仲退来会宿别后作寄' AND p.poem_author = '黎廷瑞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和赵叔清登殷仲堪读书台二首 其一', '王庭圭', '宋代', '晋朝人物渡江初，为郡风流只载书。临水重开数间屋，宿兵仍富九年储。\n\n英豪系出三公后，磊落胸蟠万卷馀。东观诸郎未堪比，登车不落问何如。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和赵叔清登殷仲堪读书台二首 其一' AND p.poem_author = '王庭圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赵州接赵王', '释了惠', '宋代', '跏趺迎上客，曲录对旌幢。\n不是家风别，他居礼乐邦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赵州接赵王' AND p.poem_author = '释了惠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送张公仪宰安丰', '王安石', '宋代', '楚客来时雁为伴，归期只待春冰泮。\n雁飞南北三两回，回首湖山空梦乱。\n秘书一官聊自慰，安丰百里谁复叹。\n扬鞭去去及芳时，寿酒千觞花烂熳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送张公仪宰安丰' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送顾尚书惟贤之南都', '谢榛', '明代', '灵气钟吴会，全才际圣明。管生知数早，顾凯赋诗清。\n\n大策闻标柱，雄谈见用兵。功高海上战，威重日南声。\n\n听履犹霄汉，移官岂帝情。中原愁里断，北斗望边横。\n\n月白三江水，山青六代城。矶看燕子在，台忆凤凰鸣。\n\n杂佩兼兰芷，孤怀寄杜蘅。酬恩心转切，飞梦到燕京。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送顾尚书惟贤之南都' AND p.poem_author = '谢榛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南徐买舟将归', '卫宗武', '宋代', '风雨连朝思黯然，山迷宿霭水迷烟。\n一年春事少閒日，半月客程逢漏天。\n喜涉鲸波返江国，便思鹤唳买河船。\n修途往复成何事，姑了余生未了缘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南徐买舟将归' AND p.poem_author = '卫宗武';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('校李从一台阁集因效其体 其一', '周紫芝', '宋代', '细诵台州句，湖边草舍幽。好山来竞秀，清濑与争流。\n\n吏可供书札，儿能伴校雠。小窗谁共此，唯有夕阳留。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '校李从一台阁集因效其体 其一' AND p.poem_author = '周紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丑奴儿（大石梅花）', '周邦彦', '宋代', '肌肤绰约真仙子，来伴冰霜。洗尽铅黄。素面初无一点妆。 \n 寻花不用持银烛，暗里闻香。零落池塘。分付余妍与寿阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丑奴儿（大石梅花）' AND p.poem_author = '周邦彦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题叶熙时空香阁', '李流芳', '明代', '我昔名斋以六香，其中空香亦居一。香本着物非从空，以空名香非其质。\n\n曰空无相诸尘生，谓空无香义亦失。香尘之体本来空，空中诸尘炽然出。\n\n叶子构空阁，独爱闻空香。岂徒屏除沉水与檀麝，奇茶妙墨皆无当。\n\n酒亦不能馨，花亦不能芳。凡彼有相皆有坏，此香乃始名真常。\n\n虽然更有说，此义非究竟。空香若为闻，为复有闻性。\n\n闻性若不空，香尘岂能净。空无驻香体，香不与空缘。\n\n鼻非往空处，空非来鼻边。空香阁中人，谓此然不然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题叶熙时空香阁' AND p.poem_author = '李流芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('弇园杂咏四十三首 其十二 小龙湫', '王世贞', '明代', '澄澄一泓水，那得吐光怪。山人七寸钵，尚有神龙在。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '弇园杂咏四十三首 其十二 小龙湫' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六月廿九日作', '弘历', '清代', '夏蓂数叶落三周，节未行秋月逮秋。赤帝送来婪尾热，绿云兆出称心收。\n\n从占德暑何须避，转惜分阴拟且留。一日平分消半岁，象台欲报火西流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六月廿九日作' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和伍崧申江楼', '岐元', '清代', '时雨时晴画本开，风光不厌酒徒来。岳阳楼上梅花笛，习子池边鹦鹉杯。\n\n声重晚钟闻远寺，夜深凉雨长新苔。临江好看东来客，移取芭蕉别院栽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和伍崧申江楼' AND p.poem_author = '岐元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('幷州羊肠坂诗', '江总', '隋代', '三春别帝乡。\n五月度羊肠。\n本畏车轮折。\n翻嗟马骨伤。\n惊风起朔鴈。\n落照尽胡桑。\n关山定何许。\n徒御惨悲凉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '幷州羊肠坂诗' AND p.poem_author = '江总';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜算子 其二', '黄绮', '当代', '独子也抽丁，夜半敲门至。踢打拖拉类罪囚，一月军中死。\n\n十日九空锅，搜索犹无已。剩有女儿灶里藏，抢去抵租米。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜算子 其二' AND p.poem_author = '黄绮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽方倅岩仲二首 其一', '刘克庄', '宋代', '上世师朱氏，慈闱祖艾轩。惓惓纂遗绪，历历识前言。\n\n柳记多先友，迁书赖外孙。悲哉此奇士，寂寞向寒原。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽方倅岩仲二首 其一' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠历阳褚司马 时此公为稚子舞故作是诗', '李白', '唐代', '北堂千万寿，侍奉有光辉。先同稚子舞，更著老莱衣。\n因为小儿啼，醉倒月下归。人间无此乐，此乐世中稀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠历阳褚司马 时此公为稚子舞故作是诗' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠开先悟老悟老述情三颂自持淡泊不事化缘夜坐举枯木话二首 其二', '王洋', '宋代', '身如枯木了生涯，那更迎春竞物华。金粟病中犹示众，如来到处不须誇。\n\n毗卢法藏无心供，兜率陀天自散花。比似出门千万事，何如丰俭且随家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠开先悟老悟老述情三颂自持淡泊不事化缘夜坐举枯木话二首 其二' AND p.poem_author = '王洋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('访黄山人希旦留饮得杯字', '李英', '明代', '十月莼鲈美，盘餐许我陪。当门聊系艇，密坐一衔杯。\n\n夕照归鸦促，天寒过雁哀。敝貂无所适，閒傍竹林隈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '访黄山人希旦留饮得杯字' AND p.poem_author = '李英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('遣怀', '曹家达', '清代', '幽意忽不惬，时衰无奈何。乾坤古尘积，沧海早寒多。\n\n江统徙戎论，文山正气歌。只今无壮士，谁与挽天河。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '遣怀' AND p.poem_author = '曹家达';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清明偕晓因随侍外舅访东四明二首 其一', '吴妍因', '清代', '佳节无虚度，扁舟溯碧溪。老孱情倍洽，童稚笑相携。\n\n滩浅拔船过，坡平信步跻。行经山僻处，驻足听莺啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清明偕晓因随侍外舅访东四明二首 其一' AND p.poem_author = '吴妍因';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归宗山籁一百四首 其一○四', '释函是', '明代', '晚年宜好静，日日数生涯。候种畏寒早，为园及暖乖。\n\n临风多远思，明月易生怀。不作馀龄计，忙来亦自佳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归宗山籁一百四首 其一○四' AND p.poem_author = '释函是';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风入松 买菊', '顾太清', '清代', '满城风雨近重阳。昨夜见微霜。含苞细认玲珑叶，问佳名、色色端相。\n\n出水芙蓉玉扇，落红万点霓裳。\n\n萧条古寺积寒芳。不论价低昂。买归自向疏篱种，伴园蔬、平占秋光。\n\n或有白衣送酒，且拼一醉花傍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风入松 买菊' AND p.poem_author = '顾太清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('骢马', '沈佺期', '唐代', '西北五花骢，来时道向东。四蹄碧玉片，双眼黄金瞳。 \n 鞍上留明月，嘶间动朔风。借君驰沛艾，一战取云中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '骢马' AND p.poem_author = '沈佺期';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卞巡检重建蘋节堂', '苏颂', '宋代', '栋宇更新构，亭名即旧规。和容君子志，歌阕大夫仪。\n\n官政搜兵暇，宾贤命席时。弦开秋月满，矢落晓星驰。\n\n叠中朋筹胜，交酬饮树移。连鼙呈画的，急管送金卮。\n\n更得萧斋榜，重看沈壁诗。恩勤主人意，雅志最相宜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卞巡检重建蘋节堂' AND p.poem_author = '苏颂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄浦门解缆有怀川无竭', '方回', '宋代', '旧守烦人送酒钱，江边五夜泊归船。\n就中最忆南山好，一老癯僧伴醉颠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄浦门解缆有怀川无竭' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('槐', '苏轼', '宋代', '忆我初来时，草木向衰歇。\n高槐虽经秋，晚蝉犹抱叶。\n淹留未云几，离离见疏荚。\n栖鸦寒不去，哀叫饱啄雪。\n破巢带空枝，疏影挂残月。\n岂无两翅羽，伴我此愁绝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '槐' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('尘', '朱诚泳', '明代', '漠漠旋空起，花前柳外扬。长途随马去，近市逐人忙。\n\n雨浥天街净，春生辇路香。元规何处避，唯有水云乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '尘' AND p.poem_author = '朱诚泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('惜花', '胡奎', '明代', '一片花辞旧日枝，随风飞去竟何之。莫教狼籍凝蛛网，愿托馀甘在蜜脾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '惜花' AND p.poem_author = '胡奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陌上赠美人', '李白', '唐代', '骏马骄行踏落花，垂鞭直拂五云车。 \n美人一笑褰珠箔，遥指红楼是妾家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陌上赠美人' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏樵子', '汪石青', '近代', '我爱樵苏者，清闲到十分。山歌行烧野，林斧响斜曛。\n\n松桧自今古，鸟猿为见闻。青山双蒉路，红叶一肩云。\n\n世外有何泪，图中或是君。近来人眼白，莫卖担头文。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏樵子' AND p.poem_author = '汪石青';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('侯官陈省斋编修自辽左入都率尔投赠', '赵俞', '清代', '才名弱岁冠群贤，岂料遭逢坎壈缠。陷贼曾修衣带表，投荒竟谪夜郎天。\n\n君恩衰白全要领，物论雌黄待简编。苏李于今皆返国，细将心迹诉当年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '侯官陈省斋编修自辽左入都率尔投赠' AND p.poem_author = '赵俞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆江南 其二 忆姑叔', '金启孮', '近代', '江南忆，路遥信难传。吴越山峦迷战雾，秣陵城畔起烽烟。\n\n牵挂自年年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆江南 其二 忆姑叔' AND p.poem_author = '金启孮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('灵岩寺', '高启', '明代', '闲上香台望下方，渔村樵坞尽苍苍。倾城人远苔生径，归寺僧稀叶满廊。\n\n云散池边留塔影，雨来阁外失湖光。废兴皆幻何须问，独自吟诗送夕阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '灵岩寺' AND p.poem_author = '高启';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病中写怀寄李九渊', '陈献章', '明代', '出门见斋颜，十日不一逢。以我腹中满，忆君头上风。\n\n头风尚可炙，腹满何由通。受气我亦薄，况乃疾病攻。\n\n五十去始衰，三四谢春冬。鬓颜忽已彫，血气少复充。\n\n客来索我书，颖秃不能供。茅君稍用事，入手称神工。\n\n以兹日衮衮，永负全生功。长揖谢茅君，安静以待终。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病中写怀寄李九渊' AND p.poem_author = '陈献章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('萧含誉自楚中来访留集二首 其一', '胡应麟', '明代', '下榻仍松桧，移尊更薜萝。星当雄剑聚，云傍彩毫多。\n\n客计留天目，乡书问汨罗。五游他日遂，相逐老岩阿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '萧含誉自楚中来访留集二首 其一' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿黄龙洞早起出坐流杯石', '李孙宸', '明代', '山眠披雾起，选石出林邱。玉乳千秋漱，云光镇日浮。\n\n放歌来独鹤，争席狎群鸥。顿觉尘心洗，丹砂不待求。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿黄龙洞早起出坐流杯石' AND p.poem_author = '李孙宸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('祈雨', '陈襄', '宋代', '庆历甲申岁，旱极忧民田。\n农夫不得耕，相顾愁凶年。\n帝心恐民忧，诏遣诉山川。\n郡国举祀典，斋戒陈豆笾。\n望祭复雩龙，祷之必精虔。\n经旬杳无报，旱气增于前。\n菑田扬飞尘，井谷无寸泉。\n炎炎天地中，草木皆欲烯。\n俗云有鳗鱼，灵异古所传。\n太守顺民心，命驾而迎焉。\n乐以钟鼓音，薰以沈檀烟。\n儵惊西郊寒，霭霭离山巅。\n急雨下滂沱，迅雷亦填填。\n须臾畎亩盈，一境皆欣然。\n始为穴中鱼，窃弄阴阳权。\n山川岂无神，不能通于天。\n蛟龙岂无灵，不能兴于渊。\n有若赏罚柄，反使奸臣专。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '祈雨' AND p.poem_author = '陈襄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早春', '陆游', '宋代', '具牛将犊行，野雉挟雌鸣。\n农事不可缓，闲人亦劝耕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早春' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '李拱', '宋代', '琴弹终日得古调，印锁经秋带藓痕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '李拱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送张都水', '吴宽', '明代', '幽燕建都邑，九鼎从而迁。\n八政一日食，仰此东南偏。\n岁漕四百万，舳舻相后先。\n云帆罢转海，江淮达且沿。\n迤逦经齐鲁，有渠昔人穿。\n噫此寻丈耳，譬若沟浍然。\n置闸以启闭，相时为节宣。\n岩岩鲁山下，平地多流泉。\n泉流入漕渠，其始才涓涓。\n奫沦惟自足，安知可浮船。\n疏导非人力，济世嗟何缘。\n张君官水部，治水思昔年。\n往来相度之，涤源同九川。\n功成既归朝，大臣慕其贤。\n封章始朝荐，行李仍夕旋。\n维此百泉眼，利博人争传。\n入渠有余沥，可溉万顷田。\n只今东方民，老幼咸颠连。\n槁项与黄馘，嗷嗷口流涎。\n潴泄倘有策，旱涝何须怜。\n漕粟国用足，种粟民生全。\n他年司马氏，载入《河渠》篇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送张都水' AND p.poem_author = '吴宽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜汤伯纪登第', '刘克庄', '宋代', '老觉人间无一忻，怪来乾鹊耳边闻。\n休嗔穷鬼揶揄我，绝喜春官摸索君。\n畴昔先生有高第，即今后死与斯文。\n不应也跃看花马，忘却江天树与云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜汤伯纪登第' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂七十二首', '释祖钦', '宋代', '树头金果铁团栾，千圣犹难著眼看。\n莫谓临机曾掇退，当阳托出已和盘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂七十二首' AND p.poem_author = '释祖钦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百二十三首 其六十九', '释崇岳', '宋代', '入门一句，宾主历然。不劳弹指，天宽地宽。壶中消息异人间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百二十三首 其六十九' AND p.poem_author = '释崇岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('禅人并化主写真求赞 其二二一', '释正觉', '宋代', '岩壑之骨洼而隆，烟霞之气温而融。其默而通，其应而冲。\n\n流云出谷，霁月行空。十方三世兮，南北西东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '禅人并化主写真求赞 其二二一' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江城子·开尊拟对菊花黄', '郭应祥', '宋代', '开尊拟对菊花黄。舞伊凉。掺渔阳。更有风流，妓女胜徐娘。只道难逢开口笑，争驰逐，利名场。玉山蓝水两茫茫。采幽香。泛清觞。橙橘堆盘，犹恨未经霜。底事□□堪喜处，丰年最，冠江乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江城子·开尊拟对菊花黄' AND p.poem_author = '郭应祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日江次', '姚合', '唐代', '野步出茆斋，闲行坐石台。久悲乡路远，犹喜杏花开。 \n 鸥鹭皆飞去，帆樯何处来。因凝千里目，落日尚徘徊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日江次' AND p.poem_author = '姚合';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉送吕若谷县丞任蒲东归五首 其五', '赵鼎', '宋代', '忽忽岁华暮，悠悠心事违。此行元自懒，前计颇知非。\n\n公有酒堪隐，我无田可归。月明枝未稳，谁念鹊孤飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉送吕若谷县丞任蒲东归五首 其五' AND p.poem_author = '赵鼎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽黄德远堂长二首 其一', '刘克庄', '宋代', '虽与长君友，居常敬少君。何曾锦袄子，竟老布襦群。\n\n申白无殊礼，程朱有旧闻。谁为复斋传，应许附青云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽黄德远堂长二首 其一' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('盘谷八咏 其四 西冈稼浪', '刘璟', '明代', '开轩临西野，禾稼盈我眸。西冈度微风，高浪涌崇丘。\n\n扬扬翠云起，滚滚清澜浮。虽无乘槎事，恍若睹瀛洲。\n\n大哉化育功，沛然和泽周。黍稌两穫宜，岁工期有秋。\n\n含哺颂帝德，长年乐无忧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '盘谷八咏 其四 西冈稼浪' AND p.poem_author = '刘璟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('立斋游山不能偕次遁泽韵二首 其二', '王柏', '宋代', '山人真漫浪，随处得清游。雪瀑方争势，风雷不肯柔。\n\n诗光浮玉板，酒滟泻琼舟。一枕斜阳里，清欢各自酬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '立斋游山不能偕次遁泽韵二首 其二' AND p.poem_author = '王柏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次萨天锡登石头城', '李孝光', '元代', '西州门外石头寺，共说英雄绿鬓凋。王气黄旗千岁尽，水声广乐六时朝。\n\n白鼯裘坏埋珠柙，玉燕钗飞坠藻翘。重到谢家携妓处，维舟寂寞听春潮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次萨天锡登石头城' AND p.poem_author = '李孝光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青玉案', '王炎', '宋代', '深红数点吹花絮。又燕子、飞来语。远水平芜春欲暮。年年长是，清明时候，故遣人憔悴。 \n 竹鸡啼罢山村雨。正寥落、无情绪。猛省从前多少事。绿杨堤上，楼台如画，此景今何处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青玉案' AND p.poem_author = '王炎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿翠山', '郑清之', '宋代', '箯舆十里见青崭，行尽松阴得翠岩。\n万壑声中清磬出，一峰高处白云缄。\n茶新煮鼎作鱼沫，僧有可人能尘谈。\n自觉灵山缘境熟，佛禅重问后三三。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿翠山' AND p.poem_author = '郑清之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满庭芳 咏腊梅和京少韵', '陈维崧', '清代', '仙泪流铜，蜂脾酿蜜，圣檀初傅新妆。冰檐雪甃，带暝乱斜阳。\n\n自是罗浮别种，依稀剩、金粟馀香。王孙弹，枝头万颗，偏惹画帘长。\n\n绕廊。应错认，宛如梅子，熟后轻飏。想宫人入道，絁帔都黄。\n\n一段冷魂幽绪，扶疏态、谁与擎将。春来也，红红白白，让尔冠群芳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满庭芳 咏腊梅和京少韵' AND p.poem_author = '陈维崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴提干之官浙东', '释居简', '宋代', '叔季振华裾，晶晶照上都。对床风送雨，隔岸越分吴。\n\n池草冰澌煖，庭萱玉色腴。綵帆飞晓镜，拂拭贺家湖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴提干之官浙东' AND p.poem_author = '释居简';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵陈帐管秋思', '方岳', '宋代', '秋风吹裂旧荷衣，自读离骚倚落晖。\n已觉芦花洲渚冷，水天归雁着行飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵陈帐管秋思' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹枝歌', '孙嵩', '宋代', '黄牛庙前鸦鹳栖，黄魔宫外枭鹏啼。\n估客酹神巫妪醉，青林日转风凄凄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹枝歌' AND p.poem_author = '孙嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('严教授画临济请赞', '释昙华', '宋代', '喝下忽雷惊，声前休领略。\n当锋啮镞时，蹉过第一著。\n不在壁立处，岂向平地泊。\n野水白连天，秋空飞一鹗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '严教授画临济请赞' AND p.poem_author = '释昙华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岁暮山村二首', '居节', '明代', '清霜红日满高林，烟火萧疏灌莽深。\n欲和楚吟无《白雪》，能生壮色少黄金。\n尝饥俊鹘呼风过，不雨寒云起夕阴。\n何事悲欢却成疾，如灰已冷少年心。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岁暮山村二首' AND p.poem_author = '居节';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('恭睹宸制花落尤艳之句自古诗人未有形容及此者使落花不与草木俱委可见天地大德之心小臣不量芜颣仰赓宸韵', '曹勋', '宋代', '春事匆匆绿渐秾，林花铺绣晓烟中。如何捲上黄金阙，许作华裀舞阆风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '恭睹宸制花落尤艳之句自古诗人未有形容及此者使落花不与草木俱委可见天地大德之心小臣不量芜颣仰赓宸韵' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杨修', '徐钧', '宋代', '料事通神自一奇，奸雄如操已深疑。\n多言屡中真何补，一死由来自不知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杨修' AND p.poem_author = '徐钧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('福州杂诗 其十九', '黄浚', '近代', '万瓦浮空月堕烟，徘徊八十一阶前。丛祠朔骑还吹角，不许南人媚九仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '福州杂诗 其十九' AND p.poem_author = '黄浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送李宓瑶明府令宝安', '张萱', '明代', '独持银艾蜃楼边，片片黄云照锦鞯。鼍鼓不諠濒海戍，马人尽种隔江田。\n\n囊携綵笔官能傲，邑傍青山吏亦仙。到日政馀秋正好，刺桐花下坐鸣弦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送李宓瑶明府令宝安' AND p.poem_author = '张萱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和雪林访二山', '释宝昙', '宋代', '平生阅世剑一吷，老去卜邻吾二人。\n亦评白云来著宿，未妨青袜去寻春。\n泉鸣石濑听逾好，雨浥岩花笑转新。\n更欲买田招鹤住，问渠谁是自由身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和雪林访二山' AND p.poem_author = '释宝昙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵五首 其五', '释德洪', '宋代', '措置已落古人后，猛省令人愧衲裙。庐山好处轩窗在，留眼归看五老云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵五首 其五' AND p.poem_author = '释德洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬和二章拜呈慈云大师伏惟采览·和桂子', '胡则', '宋代', '孤峰耸高桂，千载同一日。\n秋气正飞霜，天风落丹实。\n纷纷宝砌傍，颗颗露珠密。\n始自月中来，又从骊颔出。\n香浮古佛刹，光照高僧室。\n吴越饶珍异，金玉非俦匹。\n尝咏贤人诗，未载史臣笔。\n至矣天竺山，山灵诞奇物。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬和二章拜呈慈云大师伏惟采览·和桂子' AND p.poem_author = '胡则';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九日诸人集于资福阁次高季应韵三首 其二', '林季仲', '宋代', '隔竹通晖月自妍，樽前宝炬不须然。毫飞阁上千林湿，句落云间万井传。\n\n佳节敢辞通夕醉，宿酲还傍小窗眠。鬓边黄菊应相笑，白发较多似去年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九日诸人集于资福阁次高季应韵三首 其二' AND p.poem_author = '林季仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日晤失之堂主人王亚丁', '程滨', '当代', '人到中年始觉酸，当年何事不寻欢。素心文字年年少，大地山河日日寒。\n\n宿命结成莲子味，浮生开到菊花团。诗情洒满人间世，只是无缘上笔端。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日晤失之堂主人王亚丁' AND p.poem_author = '程滨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风入松 林花欲谢，和兰姐韵', '汤国梨', '当代', '等闲负了好时光。空惜缕金裳。花明月满春如许，禁几番、雨横风狂。\n\n绮陌望穷烟草，长亭舞老垂杨。\n\n教人辛苦恋余芳。婉转系回肠。零脂剩粉劳相忆，奈残红、抵死无香。\n\n漫说花灵憔悴，终怜月魄荒唐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风入松 林花欲谢，和兰姐韵' AND p.poem_author = '汤国梨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('昔昔盐二十首 花飞桃李蹊', '赵嘏', '唐代', '远期难可托，桃李自依依。花径无容迹，戎裘未下机。\n\n随风开又落，度日扫还飞。欲折枝枝赠，那知归不归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '昔昔盐二十首 花飞桃李蹊' AND p.poem_author = '赵嘏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿陆义斋', '陆文圭', '宋代', '归棹石门江水长，肯留一片广州香。\n不须人祝千年寿，但顾公流百世芳。\n长侍潘兴游故里，胜持汉节落南荒。\n芙蓉金菊秋风迳，好和陶醉引玉触。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿陆义斋' AND p.poem_author = '陆文圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('随想随作 其三十六', '胡云飞', '当代', '曰杀曰杀云亦云，中间真相有谁分？八万万众呼万岁，妾敢视之为夫君？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '随想随作 其三十六' AND p.poem_author = '胡云飞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和子安兄夜坐感秋', '皇甫汸', '明代', '北户鸣螀集，西堂落叶过。自惊秋兴发，并入夜情多。\n\n芳草萋零露，青溪急逝波。此时劳忆处，万里见明河。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和子安兄夜坐感秋' AND p.poem_author = '皇甫汸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('呈泽萌和尚 其四', '成鹫', '明代', '林光亭午日当中，定出无心笑懒融。片石似云争远近，双松连影失雷同。\n\n南车直指千峰北，西水长流万派东。从此丹霞无别客，不妨识得主人翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '呈泽萌和尚 其四' AND p.poem_author = '成鹫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史上·武帝', '陈普', '宋代', '狄山不能居一障，公孙请专事朔方。\n尊荣卫霍家山岳，冷淡申辕头雪霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史上·武帝' AND p.poem_author = '陈普';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桂殿秋 其二', '陈祖绶', '清代', '秋色好，在河干。渔家簖蟹点灯看。晓霜染遍丹枫叶，枝上拳鸦恋树寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桂殿秋 其二' AND p.poem_author = '陈祖绶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('刘员外寄移菊', '李山甫', '唐代', '秋来缘树复缘墙，怕共平芜一例荒。颜色不能随地变， \n 风流唯解逐人香。烟含细叶交加碧，露拆寒英次第黄。 \n 深谢栽培与知赏，但惭终岁待重阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '刘员外寄移菊' AND p.poem_author = '李山甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('客中春晚', '柴随亨', '宋代', '依依官柳暗关情，况复听人唱渭城。\n半夜客楼闻杜宇，一年春事又清明。\n帆开别浦潮如雪，花落东风雨又晴。\n光景不留人老去，浮生空自叹云萍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '客中春晚' AND p.poem_author = '柴随亨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('恭进理宗皇帝挽词 其四', '马廷鸾', '宋代', '神册方增授，龙髯遽莫攀。千秋思沛邑，七月葬稽山。\n\n春暗觚棱影，星回羽卫班。寝门如昨日，无复侍威颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '恭进理宗皇帝挽词 其四' AND p.poem_author = '马廷鸾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('画唐马三首录一', '张天赋', '明代', '驰骋来归我自镐，致身敢怨北山劳。华山此去多芳草，收拾将军旧战袍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '画唐马三首录一' AND p.poem_author = '张天赋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂七十六首', '释师范', '宋代', '一见便见，更不再见。\n张颠草书，李广神箭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂七十六首' AND p.poem_author = '释师范';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题渊明五柳图诗', '袁敬所', '明代', '藜杖芒鞋白布裘，山中甲子自春秋。\n呼儿点门前柳，莫遣飞花过石头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题渊明五柳图诗' AND p.poem_author = '袁敬所';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅竹双清卷歌题所藏王冕元章吴镇仲画也', '王世贞', '明代', '野夫策杖村南复村北，处处东君吝消息。瞥然缟素一枝横，又见琳琅数竿碧。\n\n一枝春之先，数竿冬之后。俯仰天地间，与尔成三友。\n\n衡门掩卧不一旬，淇园大庾无精神。樵青已侵翠凤尾，𩗗母吹散玉龙鳞。\n\n赖得吴镇及王冕，前与二友传其真。虚堂展看仅盈尺，二友居然侍吾侧。\n\n问之不言对以臆，眉宇萧萧吐佳色。吾不能学范詹事，西遣关中使，却寄江南春，消芳悴粉何足论。\n\n吾不能学家骑曹，不可一日无，所至植此君，封篱护箨何纷纭。\n\n二友寓我簏，俨若洛下东西两头屋。一头剪得潇湘云，一头小贮罗浮玉。\n\n镇也九咽吐吸天浆腴，冕亦磊砢节目非凡夫。扶舆清气合此图，快矣乎快矣乎，此图此友吾不孤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅竹双清卷歌题所藏王冕元章吴镇仲画也' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送崔全被放归都觐省', '岑参', '唐代', '夫子不自炫，世人知者稀。来倾阮氏酒，去著老莱衣。\n渭北草新出，关东花欲飞。楚王犹自惑，宋玉且将归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送崔全被放归都觐省' AND p.poem_author = '岑参';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜梦亡友何梅士觉而赋此', '陈独秀', '近代', '故人一别流水东，我悲朝露齐翁童。理为万劫不复值，胡意梦中忽一蓬。\n\n谈笑颜色一如昨，我亦知尔为鬼雄。自言回航为迹西方之彼美，相援忽堕沧海中。\n\n舟师大呼急相救，已果鱼腹难为功。感君悲念特一致，告以友谊自此终。\n\n我闻尔死死于东京脚气病，警疑欲问词复穷。此时相见不忍别，坐对唯有明双瞳。\n\n促膝犹在东大陆书局之楼上，撒手刹那千界空。\n\n迩今书局已迁徙，我亦长辞故地毋乃与尔同。神州事变日益急，方以病亡为尔惜。\n\n今知拯弱横葬沧海东，男儿壮举何悲泣。况复捐躯从知己，同种同心此爱一。\n\n我惊此梦百感来，灯火不温人语寂。吁嗟呼，众生九道相轮移，动植沙石流转何离奇。\n\n与尔有缘得再随，不知尔为何物，我为何物在何时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜梦亡友何梅士觉而赋此' AND p.poem_author = '陈独秀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('芍药', '王十朋', '宋代', '千叶扬州种，春深霸众芳。无言诮君子，窈窕有温香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '芍药' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凝翠 其四', '李纲', '宋代', '林中轻素起寒烟，两两飞鸥傍钓船。心在江湖归未得，晚来幽独更悽然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凝翠 其四' AND p.poem_author = '李纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送内弟黄秀卿', '杨慎', '明代', '素舸涛江来，白马崤关去。荻岸屡沿洄，芜皋几容与。\n\n寒日照行觞，朔吹飘离绪。超远望平原，悁脰空延伫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送内弟黄秀卿' AND p.poem_author = '杨慎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大司成颜几圣率同舍招游裴园，泛舟绕孤山赏', '杨万里', '宋代', '游尽西湖赏尽莲，玉壶落日泊楼船。\n莫嫌当处荷花少，剩展湖光几镜天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大司成颜几圣率同舍招游裴园，泛舟绕孤山赏' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('简吴若清', '王谌', '宋代', '丝桐挂壁户常扃，雅弄深防俗耳听。\n滴露研朱重点易，焚香炷火细翻经。\n山含晚色千峰紫，松傲新霜一派青。\n独向岩扉抱高隐，有谁能识少微星。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '简吴若清' AND p.poem_author = '王谌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送王仲矜倅兴元', '楼钥', '宋代', '蜀道难，难於上青天。\n蜀道易，易於履平地。\n蜀山天险固自若，视难为易在人尔。\n王尊真有四方志，叱驭径行了无累。\n早登岷峨仕阴城，谈笑动行千万里。\n汉中由来说鸡肋，意谓弃之为可惜。\n君今此去良似之，更欲远游寻故迹。\n汉都南郑启炎图，秦置石牛山径闢。\n淮阴拜将余高台，武侯葬处空松柏，\n大笑出门何慨慷，天涯离愁各尽觞。\n荷君走马却笑我，李侯参语夜未央。\n君方往蹈功名机，何止别驾歌王祥。\n先正九年遗爱在，更携故笏访甘棠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送王仲矜倅兴元' AND p.poem_author = '楼钥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庆宣和八首 其八 淡了', '崔荣江', '当代', '走遍江湖返本真，淡了离分。爱恨情仇作浮云，一瞬，一瞬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庆宣和八首 其八 淡了' AND p.poem_author = '崔荣江';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('啜茶示儿辈', '陆游', '宋代', '围坐团栾且勿哗，饭余共举此瓯茶。\n麤知道义死无憾，已迫耄期生有涯。\n小圃花光还满眼，高城漏鼓不停挝。\n闲人一笑真当勉，小榼何妨问酒家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '啜茶示儿辈' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过祖堂', '谢宗鍹', '明代', '讲席临轩爽，苍山四面围。草香游鹿涧，云触定僧扉。\n\n悟法无真幻，劳生有是非。逢幽良可住，心事尚多违。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过祖堂' AND p.poem_author = '谢宗鍹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出真州', '文天祥', '宋代', '天地沉沉夜泝舟，鬼神未觉走何州。\n明朝遣间应无是，莫恐元戎逐客不。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出真州' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('溪桥纳凉晚归小景', '朱松', '宋代', '谁共溪边沆瀣杯，惊鱼不睡棹歌来。风生蘋末无多子，更待冰轮作伴回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '溪桥纳凉晚归小景' AND p.poem_author = '朱松';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送胡教授秩满东归', '韩淲', '宋代', '烟尘暗江淮，风雪到溪涧。交游人复去，荏苒岁云晏。\n\n山空归飞鸦，洲静起宿雁。浮生贵壮图，流俗厌末宦。\n\n相期岂轻肥，自笑祇藜苋。三年疏数中，一旦远近间。\n\n老身要长健，他事诚易办。升沉由遇合，出处付讥讪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送胡教授秩满东归' AND p.poem_author = '韩淲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂兴 其一', '许南英', '清代', '天气初长日困人，近来诗稿懒誊真。偶思静作蝇头楷，用尽秋毫未入神。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂兴 其一' AND p.poem_author = '许南英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贵溪夜泊寄赵昌甫', '赵师秀', '宋代', '蓍草占秋动，蓬秋早得归。\n本非为事迫，不欲兴心违。\n波净孤萤度，宵凉数叶飞。\n远怀高卧者，微月闭松扉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贵溪夜泊寄赵昌甫' AND p.poem_author = '赵师秀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答成都侍其纯父用其韵', '李之仪', '宋代', '鹿头关下花深处，竹马曾寻綵衣路。虽知梨栗是生涯，人道风烟如鄠杜。\n\n四十年来若断桥，问津无计冷潇潇。一闻此语心先醉，似向江边笋自烧。\n\n羡君材器森诸有，宝带垂腰今一叟。未说常开坛上旗，且须再遣云中守。\n\n从来别驾不谋身，欲作蛾眉会里人。本是文殊亲接引，定应见处必逢君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答成都侍其纯父用其韵' AND p.poem_author = '李之仪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂六十首 其三十五', '释昙华', '宋代', '云门不负者僧来问，未免落在陷阱中。是你诸人若向者里会得，许你高步毗卢顶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂六十首 其三十五' AND p.poem_author = '释昙华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洞庭秋三十首 其四', '王夫之', '明代', '洞䆗虚无净一规，惊涛相即不相疑。精金大冶鍊幽蚃，俊鹘老鼍愁倾危。\n\n炎心已改何洗涤，高旻受荡还清嬉。妙香浮动非蘋芷，水雾上摄开轻吹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洞庭秋三十首 其四' AND p.poem_author = '王夫之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄州二首', '孔武仲', '宋代', '客路深秋一转蓬，淮天牢落此将穷。\n城开云水苍茫处，人在茅篁掩映中。\n对岸武昌风月近，千年赤壁是非空。\n悠悠陈迹慵开口，谩把筠竿伴钓翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄州二首' AND p.poem_author = '孔武仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('周元孚过访见赠奉答时元孚方有南都司马之擢', '胡应麟', '明代', '翩翩词客气凌虚，朗润周郎玉不如。佐郡蚤持三尺剑，安边频著万言书。\n\n霞飘鸡舌黄金殿，雾拥螭头白玉除。四百楼台春雨后，看花何处不停车。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '周元孚过访见赠奉答时元孚方有南都司马之擢' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('缄口翁', '范成大', '宋代', '君子取中道，常在语默间。\n多言固自费，不语良独难。\n此翁身如郑文渊，辨如悬河思如泉。\n迩来缄口欲挂壁，嗫嚅畏客翻可怜！\n君不见东家玉壶本弟兄，叩之犹解语分明。\n愿闻胚浑甚深义，定自能令一座倾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '缄口翁' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留二季父二首 其一', '葛胜仲', '宋代', '敢向明时叹滞淹，得官迎养富鱼盐。百年永抱双亲恨，五斗犹欣二父沾。\n\n寿耋名应书绿字，康宁药不待青黏。虚堂梧竹饶幽趣，正好端居养智恬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留二季父二首 其一' AND p.poem_author = '葛胜仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('旅况', '释文珦', '宋代', '日暮投村馆，凄然逆旅情。\n地荒频有盗，城远不闻更。\n度岁无多日，思乡是几程。\n听鸡还束被，霜月伴晨征。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '旅况' AND p.poem_author = '释文珦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题李尊师松树障子歌', '杜甫', '唐代', '老夫清晨梳白头，玄都道士来相访。握发呼儿延入户， \n 手提新画青松障。障子松林静杳冥，凭轩忽若无丹青。 \n 阴崖却承霜雪干，偃盖反走虬龙形。老夫平生好奇古， \n 对此兴与精灵聚。已知仙客意相亲，更觉良工心独苦。 \n 松下丈人巾屦同，偶坐似是商山翁。怅望聊歌紫芝曲， \n 时危惨澹来悲风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题李尊师松树障子歌' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆秦娥', '顾宪融', '近代', '心香爇。心田种出情花叶。情花叶。些儿红上，美人双靥。\n\n团圞月子重新缺。相逢已晚还离别。还离别。梦中欢笑，醒来呜咽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆秦娥' AND p.poem_author = '顾宪融';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游仙词八首 其七', '郭翼', '元代', '麟洲宫殿五云高，夜赴瑶池宴碧桃。借得仙人红尾凤，月中飞影拂波涛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游仙词八首 其七' AND p.poem_author = '郭翼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送吴容之进士还歙', '程敏政', '明代', '二月莺花满帝城，手扳黄柳送君行。传家旧熟麟经笔，中选新题雁塔名。\n\n画舫摇春新旅况，綵衣称寿足亲情。还乡不久应趋召，重簉鹓行玉佩声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送吴容之进士还歙' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('甲辰元日', '陈纪', '宋代', '屋角鸡声一岁分，起搔吟鬓惜芳辰。江山有恨英雄老，天地无私草木春。\n\n柏叶又倾新岁酒，梅花同是隔年人。东风著物能多少，写入清诗句句新。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '甲辰元日' AND p.poem_author = '陈纪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题翠云堂', '弘历', '清代', '四株松树四时翠，一坐书堂一赏云。何必山岚将谷霭，怒涛细浪总氤氲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题翠云堂' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('少年行（一作汉宫少年行）', '雍陶', '唐代', '不倚军功有侠名，可怜球猎少年情。戴铃健鹘随声下， \n 撼珮骄骢弄影行。觅匠重装燕客剑，对人新按越姬筝。 \n 岂知儒者心偏苦，吟向秋风白发生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '少年行（一作汉宫少年行）' AND p.poem_author = '雍陶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜泛', '苏泂', '宋代', '澄波湛湛接新秋，月子波心印一钩。\n荷叶乱花看不见，夜深时有小龙游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜泛' AND p.poem_author = '苏泂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山中何所有 其三', '于石', '宋代', '卫人将授甲，鹤有乘轩宠。爱人不如禽，士固不为用。\n\n唐人竞朝梁，怒杀孙供奉。兽犹知有君，人胡不愧悚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山中何所有 其三' AND p.poem_author = '于石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉漏迟 明湖白莲', '林修竹', '当代', '荷香飘水上，明湖胜地，辄为神往。绿柳垂杨，花绰约波心荡。\n\n一望婷婷十里，琼玉姿、高华堪赏。清溪漾。出水不滓，芳洁无两。\n\n年年红袖青衫，尽湖上纳凉，花间荡桨。水榭亭台，风景令人怀想。\n\n十顷白莲碧荷，送凉味、微风轻飏。静无浪。到处笙歌画舫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉漏迟 明湖白莲' AND p.poem_author = '林修竹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长安寓居寄赠贾岛', '马戴', '唐代', '岁暮见华发，平生志半空。\n孤云不我弃，归隐与谁同。\n枉道紫宸谒，妨栽丹桂丛。\n何如随野鹿，栖止石岩中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长安寓居寄赠贾岛' AND p.poem_author = '马戴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬日得冯少宰用韫书问寄谢一首', '于慎行', '明代', '北风一以厉，雨雪何漫漫。江湖莽浩淼，周道阻且艰。\n\n故人在千里，寄我双罗纨。织成不惜远，为念衣裳单。\n\n感兹平生意，提挈再三叹。别离未觉久，年光忽欲阑。\n\n幸有裘与褐，可以禦岁寒。七章匪不丽，所适燠且安。\n\n卷衣置箧笥，怊怅不能谖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬日得冯少宰用韫书问寄谢一首' AND p.poem_author = '于慎行';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过安南西贡有感 其四', '黄遵宪', '清代', '九真象郡吾南土，秦汉以前既版图。一自三杨倡议后，珠崖永弃不还珠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过安南西贡有感 其四' AND p.poem_author = '黄遵宪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古 其十四', '释慧空', '宋代', '盲人端的有眼，铁牛通身无骨。不信问取桃花，便见灵云败阙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古 其十四' AND p.poem_author = '释慧空';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('逍遥咏', '宋太宗', '宋代', '含元得一本真宗，误者平论总是空。\n万象都来皆备数，千言譬谕了然通。\n才高俊彦优堪赏，窃禄偷安有异同。\n唯愿他心如似我，不教陷恶罪身中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '逍遥咏' AND p.poem_author = '宋太宗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚望东村', '张昱', '元代', '开门见东村，晨光尚蒙昧。白云何处来，适与予心会。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚望东村' AND p.poem_author = '张昱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天目狮子岩', '徐渭', '明代', '我昔闻真人，言修不死身。选地满天下，与鬼争青城。\n\n一岫插天日，宛尔怒猊狞。老释据其口，黄冠复来争。\n\n黄冠匪他人，云是真人孙。聃昙本上圣，高道超沈冥。\n\n说教虽异轨，俱以退让名。区区百尺铁，青红抺秋荣。\n\n龙女买色线，一夕绣可成。胡为两龙象，角吻同苍蝇。\n\n赋此觉蚩蚩，鉴之慎勿听。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天目狮子岩' AND p.poem_author = '徐渭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送云客赴春官 其一', '王彦泓', '明代', '吟坛饮社共髫年，互语闲情登几联。我已荷衫卸拘束，君今芸阁伫摩编。\n\n才华淡写宫眉妩，标格平趋国步妍。预想捷书春夜到，玉人喧笑画屏前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送云客赴春官 其一' AND p.poem_author = '王彦泓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('端午贴子词 皇帝阁六首 其四', '真德秀', '宋代', '当宁求贤轸虑长，每因佳节忆沉湘。不须五色纫成线，自有忠言补舜裳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '端午贴子词 皇帝阁六首 其四' AND p.poem_author = '真德秀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠陈子仪中翰奉使南归', '郭之奇', '明代', '皇华使者束轻装，谁奏骊歌四牡旁。二载相依同舍客，漳潮咫尺未殊乡。\n\n不谓离群今日意，忽因黯淡暮春肠。春肠百结难相赠，春色犹堪问一方。\n\n此去湖西春未尽，扁舟宛在湖中央。千条弱柳垂朝碧，十里娇荷动午光。\n\n游人但撷诗人料，西湖仍为西子妆。千杯渌酒应时有，一曲清歌何可当。\n\n我亦思归魂梦逐，愿随烟景继途长。凭君留取春湖色，莫令秋葭结露霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠陈子仪中翰奉使南归' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七月十六日赐九十一岁老和尚', '玄烨', '清代', '暑退全消陌上尘，盂兰大喜见姚秦。临风洗钵龙池雨，凝露舒莲鹫岭春。\n\n送节双轮同梦幻，持心半偈见深淳。循环已识盈虚理，不向山僧更问津。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七月十六日赐九十一岁老和尚' AND p.poem_author = '玄烨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('仝赵献武林洁甫饮仲仁宅', '佘翔', '明代', '谁道元龙傲，相逢意转亲。但教千日醉，莫笑百年贫。\n\n风雨能留客，烟花不负人。夜来占太史，星已聚荀陈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '仝赵献武林洁甫饮仲仁宅' AND p.poem_author = '佘翔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和靖江府钟纪善韵 其二', '程通', '明代', '辽东望江左，荡荡是天衢。日侍亲王驾，云从长者车。\n\n歌曾誇白雪，酒不羡黄垆。归向朝端说，今吾非故吾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和靖江府钟纪善韵 其二' AND p.poem_author = '程通';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早春豫斋先生招饮寿乐亭即席八韵', '李梦阳', '明代', '每当和煦日，径造赏春台。为与岁华约，非因歌舞来。\n\n乾坤从白发，节序且红梅。转径寻花发，凭轩数雁回。\n\n日斜云故拥，地煖气仍催。彭泽羲皇意，河间礼乐才。\n\n激昂还玉笛，烂熳有金杯。坐待中天月，长风雾巳开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早春豫斋先生招饮寿乐亭即席八韵' AND p.poem_author = '李梦阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天 山居忆老仆及麾下竹鼠有寄', '熊东遨', '当代', '堪羡虫王耐得闲，终朝坐对好湖山。念千百遍成何用，有二三人足抱团。\n\n多少事，古今寒，孤峰且看众贤攀。茅檐新结清溪畔，东倒西歪一两间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天 山居忆老仆及麾下竹鼠有寄' AND p.poem_author = '熊东遨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨後绝凉偶作', '陆游', '宋代', '槐阴日色薄，桐叶雨声长。\n林下有余适，城中无此凉。\n浮瓜寒水碧，斸药小鉏香。\n未许陶潜达，华簪何足忘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨後绝凉偶作' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴刺史祠', '梁以壮', '明代', '昨夜江边梦寐劳，晋朝人物此清操。贪泉化水千寻洁，廉吏如峰四百高。\n\n返照石厓开古镜，到风春树长新涛。亦将行野为君诵，驷马齐宫久草蒿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴刺史祠' AND p.poem_author = '梁以壮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乐府十二首', '皇甫汸', '明代', '典礼成，四海谧。享祀禋，九庙翼。考明堂，筵太室。献皇跻，烈祖匹。\n\n故鬼小，幽灵假。咏孝思，歆明德。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乐府十二首' AND p.poem_author = '皇甫汸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('括浙江潮候', '释赞宁', '宋代', '午未未未申，申卯卯辰辰。\n巳巳巳午午，朔望一般轮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '括浙江潮候' AND p.poem_author = '释赞宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诸公载酒贺余休致水村农卿有诗次韵 其三', '刘克庄', '宋代', '别无穴隙可钻窥，常恐冥行践骇机。恰则赐环烦内引，俄然只履已西归。\n\n都忘紫禁烟花绕，绝喜青山笋蕨肥。应被水村翁冷笑，争墩未了又争矶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诸公载酒贺余休致水村农卿有诗次韵 其三' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人', '顾夐', '唐代', '晓莺啼破相思梦，帘卷金泥凤。宿妆犹在酒初醒， \n 翠翘慵整倚云屏，转娉婷¤ \n 香檀细画侵桃脸，罗袂轻轻敛。佳期堪恨再难寻， \n 绿芜满院柳成阴，负春心。 \n 触帘风送景阳钟，鸳被绣花重。晓帏初卷冷烟浓， \n 翠匀粉黛好仪容，思娇慵¤ \n 起来无语理朝妆，宝匣镜凝光。绿荷相倚满池塘， \n 露清枕簟藕花香，恨悠扬。 \n 翠屏闲掩垂珠箔，丝雨笼池阁。露粘红藕咽清香， \n 谢娘娇极不成狂，罢朝妆¤ \n 小金鸂鶒沈烟细，腻枕堆云髻。浅眉微敛注檀轻， \n 旧欢时有梦魂惊，悔多情。 \n 碧梧桐映纱窗晚，花谢莺声懒。小屏屈曲掩青山， \n 翠帏香粉玉炉寒，两蛾攒¤ \n 颠狂年少轻离别，孤负春时节。画罗红袂有啼痕， \n 魂销无语倚闺门，欲黄昏。 \n 深闺春色劳思想，恨共春芜长。黄鹂娇转泥芳妍， \n 杏枝如画倚轻烟，锁窗前¤ \n 凭阑愁立双蛾细，柳影斜摇砌。玉郎还是不还家， \n 教人魂梦逐杨花，绕天涯。 \n 少年艳质胜琼英，早晚别三清。莲冠稳篸钿篦横， \n 飘飘罗袖碧云轻，画难成¤ \n 迟迟少转腰身袅，翠靥眉心小。醮坛风急杏枝香， \n 此时恨不驾鸾皇，访刘郎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人' AND p.poem_author = '顾夐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵孔舍人曝书', '张耒', '宋代', '图书陈秘奥，樽俎肆雍容。\n玉殿朝回答，蓬山深处峰。\n探囊图轴旧，题壁姓名重。\n盛世年年事，新篇莫厌供。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵孔舍人曝书' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙 清晨某站', '汪洋', '当代', '抹轨冲暝蝶梦收，野灯三两洞新愁，天涯人物本天囚。\n\n衫薄但输风露满，病深尤羡竹篱幽，人言不久过徐州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙 清晨某站' AND p.poem_author = '汪洋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('壬申春，国难有感 其七', '薛昂若', '清代', '钱财日日付东风，弄到民贫国亦穷。矮鬼连朝烧更杀，频挥老泪哭英雄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '壬申春，国难有感 其七' AND p.poem_author = '薛昂若';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杨周二子墓下作寄怀王山人', '严可均', '清代', '侵晨携斗酒，流眺城南隅。碧波带长麓，寒光清有余。\n\n群鸦一以噪，累累多丘墟。念彼地下人，生前良我徒。\n\n杨子雕龙手，周生野鹤如。飘飘两词客，长伴孙太初。\n\n流行随大化，一去无贤愚。寥寥四五子，后死尔与余。\n\n感此一相酹，沈吟立斯须。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杨周二子墓下作寄怀王山人' AND p.poem_author = '严可均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('齐天乐 万寿节', '俞彦', '明代', '荣光亿道长春节，流虹又逢绕电。万国梯航，八方蹈舞，干羽两阶呈遍。\n\n云祥舜旦。更日丽尧年，风清禹甸。紫玉班中，五明宫里仙人现。\n\n遥遥西望长安。把南山乐只，一杯期献。再展芹私，萦怀曝爱，惟有升平堪愿。\n\n边尘净扫。尽世界熙熙，太平重见。漫道齐天，后天勤未倦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '齐天乐 万寿节' AND p.poem_author = '俞彦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和颜长官百咏 其七 山居', '朱继芳', '宋代', '宿世仙家十二楼，误婴时网未深愁。浮丘辈行如相觅，骑却紫云归去休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和颜长官百咏 其七 山居' AND p.poem_author = '朱继芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('甲申二月二十三日问马坰野寓宝坻公署有感时令君曹公将内召', '申佳允', '明代', '山映崆峒带远晖，晴楼沙树昔年非。地经烽火寒烟乱，鸟积斜阳塞草肥。\n\n古梵疏钟声绕梦，孤城细雨泪沾衣。春风信宿神明宰，又复搴惟傍紫薇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '甲申二月二十三日问马坰野寓宝坻公署有感时令君曹公将内召' AND p.poem_author = '申佳允';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送平阴杨令迁晋府审理二十二韵', '于慎行', '明代', '藉甚神明宰，循良踵二京。关西绵世胄，梁苑茂家声。\n\n玉季雄霜府，兰昆比月卿。谈经推上第，緤组试专城。\n\n濊泽同春育，孤操共水清。莱芜尘甑满，单父玉琴鸣。\n\n纪政驯田雉，忧时愤海鲸。悬金亲教射，握槊自观兵。\n\n月禀挥将尽，云徒练已成。不甘驰羽檄，直欲请长缨。\n\n庙画方蒐俊，藩僚亦采英。会闻公府辟，先假士师名。\n\n彭泽归陶令，长沙召贾生。儿童啼拥路，父老泣沾纮。\n\n花树存遗爱，棠阴郁别情。幽居门久杜，过访盖频倾。\n\n听雨山坳醉，冲寒渡口迎。谈玄词要妙，举白气纵横。\n\n自觉交情洽，谁堪远思盈。寒冰结去水，飞雪绕前旌。\n\n鼓吹声何急，骊驹赋载赓。壮心应未已，斗畔倚青萍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送平阴杨令迁晋府审理二十二韵' AND p.poem_author = '于慎行';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感寓', '刘弇', '宋代', '岁月忽其除，飒焉悲凛秋。商飙号晨林，脱叶舞梧楸。\n\n鸟边下白道，木末扬寒流。闺人促幽杼，客子怅远游。\n\n云阔眇天半，俯景独迟留。阴霾扫不得，千古空沧洲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感寓' AND p.poem_author = '刘弇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('文宣王及其弟子赞 其二', '赵构', '宋代', '德行首科，显冠学徒。不迁不贰，乐道以居。食埃甚忠，在陋自如。\n\n宜称贤哉，岂止不愚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '文宣王及其弟子赞 其二' AND p.poem_author = '赵构';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨晴访芸生归而有作，因赠并寄寰尘', '沈尹默', '清代', '坐爱微凉一散襟，酒杯还与澹相寻。闲身可饫风尘味，末俗难知道路心。\n\n劫急一枰终扰攘，雨鸣连日暗销沉。前头已试风波险，要与先生放浪吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨晴访芸生归而有作，因赠并寄寰尘' AND p.poem_author = '沈尹默';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('景辰张先生校文福建归林公崇高画闽溪放棹图赋诗其上以饯因次韵就题', '陶宗仪', '元代', '一棹闽溪下濑船，千岩万壑路勾连。榕阴处处浮岚外，杜宇声声落照边。\n\n考试来临多士上，宦游向在十年前。故人分手难为别，写得云山上蜀笺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '景辰张先生校文福建归林公崇高画闽溪放棹图赋诗其上以饯因次韵就题' AND p.poem_author = '陶宗仪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答刘泾书 其二', '米芾', '宋代', '巨舰横江稳不摇，顺浮溟涨午时潮。江南晴色山无翳，乞与閒人取次描。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答刘泾书 其二' AND p.poem_author = '米芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答刘仲贞', '欧大任', '明代', '山中注易不须删，稷下谁知有鹖冠。我自最怜嵩少色，白云披褐几回看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答刘仲贞' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梁尘诗', '萧纲', '南北朝', '依帷濛重翠，带日聚轻红。定为歌声起，非关团扇风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梁尘诗' AND p.poem_author = '萧纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又和元可二篇 其一', '薛季宣', '宋代', '阳春倡者谁，欲和心已阑。故乡渺千里，念之一辛酸。\n\n人生足离合，岂在共盘餐。胡然儿女情，苛留太无端。\n\n焉得不系舟，使我怀抱宽。信美非吾家，会且即所安。\n\n后园桃李秋，芜径草木繁。酒来辄竟醉，歌强难为欢。\n\n风雨打寒食，枯河尽瀰漫。故乏猜嫌累，谁能整其冠。\n\n惟当适意尔，曷贵吕极官。晋贤泣楚囚，卫女赋竹竿。\n\n愿君悯羁思，所友路何曼。归哉昔在陈，孔圣乏体胖。\n\n幸非艰棘徒，亦复谢栾栾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又和元可二篇 其一' AND p.poem_author = '薛季宣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红 其二 都中戏答人问', '周之琦', '清代', '万古云霄，问一羽、何人当得。但随分、南州承乏，油幢画戟。\n\n假节文从炎汉仿，借绯句亦香山觅。尽翩翩、斜压帽檐攲，螭坳立。\n\n曾待漏，金门夕。曾视草，銮坡侧。却翻疑定远，功成投笔。\n\n麋鹿方惭簪绂系，貂婵那自兜鍪出。是虎贲、还是蔡中郎，君须识。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红 其二 都中戏答人问' AND p.poem_author = '周之琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('悼山谷五首 其五', '释德洪', '宋代', '平昔驭风骑气，如今夜雨荒丘。欲动西州华屋，空馀南浦渔舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '悼山谷五首 其五' AND p.poem_author = '释德洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('延平得雪', '陈宓', '宋代', '衍山先自无尘土，更着飞琼细糁看。\n可笑一生缘好事，却将衰鬓敌隆寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '延平得雪' AND p.poem_author = '陈宓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬日', '利登', '宋代', '藤果累累熟，山晴自绕檐。\n断薪经雨湿，野菜着霜甜。\n诗秒客相笑，家贫鹤不嫌。\n谁能更惆怅，痴坐卷疎帘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬日' AND p.poem_author = '利登';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('閒云馆为张洪老作', '杨起元', '明代', '从君起版筑，论学圣人前。四海仰高风，亹亹二十年。\n\n一念慰慈颜，屡疏辞细旃。孝动皇情允，多子徒留连。\n\n浩浩江汉流，苍苍匡卢烟。行行望城阙，悠悠归园田。\n\n慈亲在高堂，稚子绕膝边。已悟静者心，不复窥陈编。\n\n室中地不扫，壁上琴无弦。请问唐虞理，浮云同漠然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '閒云馆为张洪老作' AND p.poem_author = '杨起元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠文二', '庄昶', '明代', '一灯何处写相知，对坐寒窗暮雨时。诗本平生非杜甫，琴才临老遇钟期。\n\n尽堪出手名家早，但觉忘年得友迟。肯许无言真妙处，欲将千古慰深思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠文二' AND p.poem_author = '庄昶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庭竹', '释智圆', '宋代', '移去群花种此君，满庭寒翠更无尘。\n暑天闲绕烦襟尽，犹有清风借四邻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庭竹' AND p.poem_author = '释智圆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋岸芦花歌', '邓云霄', '明代', '芦花两岸堆成雪，旅客怀归心欲绝。轻棹如浮剡曲舟，开尊似坐瑶池月。\n\n年华随水向东流，芦荻无心亦白头。正苦征鸿偏怨夜，翻憎络纬竞吟秋。\n\n芦花飞去如蓬转，乡路微茫水深浅。村童莫更□笳吹，恐惹边风入柳枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋岸芦花歌' AND p.poem_author = '邓云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('胡文昌和东坡子由彭城月诗并绿澹庵新州以所', '陈元晋', '宋代', '澹庵眼似坡仙高，眇视轩冕如秋毫。\n忠臣要作社稷计，那知平陆生风涛。\n当时盖亦轻余子，富贵转头真逝水。\n汗青不朽姓字香，百世闻风尚兴起。\n函关正要封泥丸，金陵王气开龙蟠。\n一书乞借尚方剑，缙绅环睨心为寒。\n要扶銮驾还都汴，鼎镬在前颜不变。\n低头辨了着南冠，敛手笑还丞相板。\n飞鸢跕跕古锦山，气老益壮穷益坚。\n银河流空月照地，肺肝洞作冰玉看。\n缅怀坡仙亦大好，诗比离骚兴香草。\n持杯满满贺素娥，岭海百年逢二老。\n闻孙趾美德不贫，清文高节犹前人。\n何当佳话重拈出，只惭授简梁园客。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '胡文昌和东坡子由彭城月诗并绿澹庵新州以所' AND p.poem_author = '陈元晋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二月九日瞻望大驾渡江作', '王绂', '明代', '风送龙舟正落潮，山形盘踞郁岧峣。帝图久已超三代，王气何曾数六朝。\n\n樯橹中流江路迥，旌旗夹岸海天遥。只今万国歌游豫，不独康衢稚子谣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二月九日瞻望大驾渡江作' AND p.poem_author = '王绂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('友芳园杂咏为吕心文作二十五首 其十四 大雅山居', '欧大任', '明代', '有待觉为烦，委休已堪老。雅音未寥寥，书带千年草。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '友芳园杂咏为吕心文作二十五首 其十四 大雅山居' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宛在堂中即事 其十四', '郭之奇', '明代', '雨过忽变芳草，潮退时翻落花。清景当前屡易，浮生此际何涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宛在堂中即事 其十四' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽张春卿尚书', '陈傅良', '宋代', '论建回天力，生平与众同。\n居常焚谏草，人自避乘骢。\n朝誉多张仲，家声近鲁公。\n挽辞吾不愧，收入汗青中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽张春卿尚书' AND p.poem_author = '陈傅良';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('除夕', '文徵明', '明代', '白发婆娑夜不眠，孙曾绕膝更翩跹。已知明旦非今日，不觉残龄又一年。\n\n旧事悲欢灯影里，春风消息酒杯前。更阑人静鸡声起，却对梅花一灿然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '除夕' AND p.poem_author = '文徵明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江北纪行十六绝 其十五 桐城赠方与义同年', '张吉', '明代', '鬓根花影帽檐风，闪闪风花百醉中。欲蹑芒鞋寻别墅，今吾恐与故吾同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江北纪行十六绝 其十五 桐城赠方与义同年' AND p.poem_author = '张吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔歌子 其四', '黄公渚', '近代', '绛色裲裆双髻丫。踏歌连臂唱村娃。红姤婐，绿槎枒。\n\n一树山茶若个家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔歌子 其四' AND p.poem_author = '黄公渚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古五十三首 其四十九', '释文礼', '宋代', '天地广无边，何云藏北斗。跛脚老云门，未明三八九。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古五十三首 其四十九' AND p.poem_author = '释文礼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵章兄雨中 其五', '黄溍', '元代', '草长故山怀独往，苔生今雨叹离居。谁能共饮桃源酒，一醉千年不愿馀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵章兄雨中 其五' AND p.poem_author = '黄溍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寓言十首 其六', '胡奎', '明代', '世无钟子期，孰知悲与喜。闻昔有韩娥，歌声绕梁起。\n\n一歌令人悲，再歌令人喜。同为齐中音，忧乐如转指。\n\n我有太古弦，泠泠泻秋水。所愿感人心，不愿感人耳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寓言十首 其六' AND p.poem_author = '胡奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('翁踏孤舟立 其二', '林希逸', '宋代', '一叶孤舟小，生涯在钓筒。群飞看雁阵，独立是渔翁。\n\n浪与头俱白，颜因酒暂红。片帆烟渚外，瘦影夕阳中。\n\n蓬鬓千茎雪，芦花两岸风。烹鲈吹荻火，隔岸呼儿童。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '翁踏孤舟立 其二' AND p.poem_author = '林希逸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('将谒延庐州行至板桥忽病而止复还建康以五诗', '赵蕃', '宋代', '甑倒悬知解死饥，故殊道路永为嗤。\n我今恃有彭州牧，二柄宁当复误疑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将谒延庐州行至板桥忽病而止复还建康以五诗' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('憩颜子予海山别业', '释绍嵩', '宋代', '群峰当户晓岚晴，杨柳风和日听莺。\n郭外春山明锦绣，门前弱水即蓬瀛。\n期登野阁闲应甚，来惯幽禽近不惊。\n独凭栏干意难写，绿桑疏处哺牛鸣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '憩颜子予海山别业' AND p.poem_author = '释绍嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('故少师张魏公挽词三章三章', '杨万里', '宋代', '读昜堂边路，曾闻赤舄声。\n心从画前到，身在昜中行。\n忧国何缘寿，思亲岂欲生。\n不应永州月，犹傍雨窗明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '故少师张魏公挽词三章三章' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('声声慢', '王陈常', '当代', '生而好古，老未知生，诗书误了平生。自有生来，操持不善谋生。\n\n虚生五十七载，叹今生、只作先生。养生主，尚閒无半日，寄嘅浮生。\n\n窃信前生是蠹，任群生扰扰，笑我狂生。生子生孙，犹堪不负吾生。\n\n明知此生休矣，愿他生、不作儒生。得生趣，正不识、修到几生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '声声慢' AND p.poem_author = '王陈常';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答王百谷见寄', '欧大任', '明代', '长安携手问游梁，曾忆同时谒建章。开阁尔为丞相客，过江吾愧尚书郎。\n\n遥知羔币辞莲府，老向驺车负草堂。明日东归变名姓，傥逢梅福在吴阊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答王百谷见寄' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('补瓢 其一', '宗林', '明代', '足迹寻常懒过桥，栖栖今日又明朝。诗情冷淡霜中菊，服色离披雪后蕉。\n\n贫里有谁分米送，禁山无处觅柴烧。老来自笑贪心在，还对清泉补破瓢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '补瓢 其一' AND p.poem_author = '宗林';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日游青山访太白墓二首 其二', '李之仪', '宋代', '淹时苦炎暑，此日遇初秋。旧籍存千亩，彝伦咏九畴。\n\n但能寻旷荡，何必事深幽。未愧辽东笑，真成知北游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日游青山访太白墓二首 其二' AND p.poem_author = '李之仪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再送华泉', '周伦', '明代', '驱车出长干，放船溯江潮。归云薄东鲁，转柁凭南飙。\n\n朱夏火旗帜，烈日燔征旄。系缆遵广原，周行谢波涛。\n\n回首世途隘，步屧云山高。山中产芝草，猿鹤元相招。\n\n时窥南华篇，白日从逍遥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再送华泉' AND p.poem_author = '周伦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题临川李子经文藁', '杨万里', '宋代', '圣经贤传紧关津，骚客诗家妙斧斤。总被先生漏消息，不令后辈隔知闻。\n\n都城一日纸增价，天下几人贫似君。不要绨袍却归去，平生笑杀送穷文。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题临川李子经文藁' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江阴晓行', '邹本荃', '清代', '百里澄江路，衣侵晓雾轻。潮乘风势涌，露共日华明。\n\n岸隔荒村犬，声移绿树莺。归期拟此际，问寝待鸡鸣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江阴晓行' AND p.poem_author = '邹本荃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('祭岳回重赠孟都督', '韩翃', '唐代', '封作天齐王，清祠太山下。鲁公秋赛毕，晓日回高驾。 \n 从骑尽幽并，同人皆沈谢。自矜文武足，一醉寒溪夜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '祭岳回重赠孟都督' AND p.poem_author = '韩翃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙（和张文伯海棠）', '王之道', '宋代', '过雨花容杂笑啼。淡妆深注半开时。娇娆情态自天姿。 \n 新浴太真增艳丽，微风新燕斗清奇。绿窗朱户雅相宜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙（和张文伯海棠）' AND p.poem_author = '王之道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日早起', '陈曾寿', '清代', '晓日朦胧闻竹鸡，杂花写影石栏西。竹苞才吐青青节，穿径杨花踏作泥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日早起' AND p.poem_author = '陈曾寿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄永堂', '沈说', '宋代', '落日照江东，思君讯便风。\n栖迟定何处，约莫过残冬。\n小隐时曾到，安书久未通。\n处怜心易老，盘屈似寒松。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄永堂' AND p.poem_author = '沈说';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游天池山', '谢孟安', '明代', '夙性爱丘壑，不惮穷跻攀。兹峰特神秀，上抗浮云端。\n\n幽寻叹奇绝，俯瞰何其宽。同游六七辈，一一皆儒冠。\n\n岚翠袭衣袂，风泉听潺湲。绝顶有巨石，平铺势团团。\n\n天成几洼窟，奚用斤斧钻。冬夏水不竭，可以怡心颜。\n\n泓澄映星象，风云常往还。古人善取譬，名曰天池山。\n\n东望大瀛海，万里生波澜。中流屹孤岛，袤延若连环。\n\n在昔富乔木，今见馀榛菅。我昔家上头，凝睇生悲酸。\n\n马鬣委草蔓，岁久恐灭漫。春秋缺拜扫，于心曷能安。\n\n繁华感畴昔，岁月如惊湍。人去山已空，野鸟鸣间关。\n\n有时动归念，恨无双飞翰。叹息川路遥，跋涉诚艰难。\n\n而我今白首，梦寐空盘桓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游天池山' AND p.poem_author = '谢孟安';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又和前韵二首 其二', '释德洪', '宋代', '篇篇俊逸间清新，老阅群才始见真。秀却采莲溪畔态，豪吞指壁柱边瞋。\n\n肺肠旧信能缠锦，文字今知解斗春。笔力肯低容我和，诗成无惜寄来频。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又和前韵二首 其二' AND p.poem_author = '释德洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与马天常留别', '邵宝', '明代', '汪伦送我不如君，君到严州路亦分。莫道桃花潭水浅，回头还薄富春云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与马天常留别' AND p.poem_author = '邵宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('试笔偶书二首 其二', '曹勋', '宋代', '道友山间四散居，忽然相会亦旬馀。直须把盏如村醉，醉后歌欢更自如。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '试笔偶书二首 其二' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南山一株松', '郑善夫', '明代', '南山一株松，衣被何婵嫣。上焉绝云气，下者抵流泉。\n\n季秋零露冱，百草乃弃捐。修条抗回风，况结霜霰缘。\n\n附托一得所，斤斧那得前。所以保容华，阅岁及百千。\n\n纷纷蜉居子，岂知有大年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南山一株松' AND p.poem_author = '郑善夫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题卷子会', '程公许', '宋代', '龙飞景运诏宾兴，将相之阶自此升。\n毛颖铦锋须快战，楮生衷甲作先登。\n精思可使文加点，抄写能令价倍增。\n努力杀青男子事，功名未尽剡溪藤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题卷子会' AND p.poem_author = '程公许';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙', '汪东', '清代', '电毂风轮夹道驰。巍巍杰构与天齐。长安丽日正春时。\n\n一笑相逢哗白发，千言在口说红旗。信知此会古来稀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙' AND p.poem_author = '汪东';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送丁大卿知庐州', '姜特立', '宋代', '寄迹双溪喜盍簪，剖符庐子遽分襟。\n伏波威著羌夷界，叔子恩怀江汉心。\n万里烟尘入长筭，二边风月待清吟。\n促归早晚飞丹诏，新雁回时有好音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送丁大卿知庐州' AND p.poem_author = '姜特立';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绝句九首 其三', '刘基', '元代', '雨馀烟柳约青丝，风过芹塘澹碧漪。正是愁来无著处，绿阴庭馆暮寒时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绝句九首 其三' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴门旅兴', '陈子升', '明代', '浪迹吴门且暂休，几多抛掷几多收。百金未买不龟手，一石尚看能点头。\n\n断简故开眢井匣，寒梅新照面山楼。木人独入丛花国，誇尽王孙春草游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴门旅兴' AND p.poem_author = '陈子升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('示侄休四首 其一', '杨爵', '明代', '旅舍空时家又空，秦关燕塞路难通。吾儿莫道饥寒苦，君子原来亦固穷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '示侄休四首 其一' AND p.poem_author = '杨爵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('用夹谷子括吴山晚眺韵十首', '方回', '宋代', '泰伯封疆四望宽，胜将吴越旧书观。\n苧罗山下春才到，麋鹿台边沼已寒。\n不有采香专怙宠，可能尝胆便除残。\n今年木德临心宿，重见家家衽席安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '用夹谷子括吴山晚眺韵十首' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('詹仲信出示卜居诗佳甚作二绝句谢之', '陆游', '宋代', '年来阻阔动经时，忽见新篇乃尔奇。\n安得齐纨翦团扇，为君小草卜居诗？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '詹仲信出示卜居诗佳甚作二绝句谢之' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆汉月', '陆求可', '清代', '夜被姮娥相恼。今夜方才圆了。清光大地不能遮，多向花间树杪。\n\n停杯喧笑处，便对影、岂知衰老。新磨明镜在当中，权且将来一照。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆汉月' AND p.poem_author = '陆求可';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虚舟二首', '郭印', '宋代', '野航一逍遥，湖海意自足。\n翩翩犯斗牛，谁谓推平陆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虚舟二首' AND p.poem_author = '郭印';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('张氏别业八首 其五 小若耶', '徐渭', '明代', '别沼分湖水，因名小若耶。水流有大小，却一样荷花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '张氏别业八首 其五 小若耶' AND p.poem_author = '徐渭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚春', '刘希夷', '唐代', '佳人眠洞房，回首见垂杨。寒尽鸳鸯被，春生玳瑁床。 \n 庭阴幕青霭，帘影散红芳。寄语同心伴，迎春且薄妆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚春' AND p.poem_author = '刘希夷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谷日大雪口号二首', '徐渭', '明代', '谷日之雪一何大，一尺一半自昨夜。望中飞絮已迷天，安得犹窥凤城瓦。\n\n横街十丈滑如油，短驴难踏转生愁。江边总有梅花发，诗客应无一个游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谷日大雪口号二首' AND p.poem_author = '徐渭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('习彦威', '宋庠', '宋代', '四海习彦威，英英出江汉。\n高韵凌风翔，雕文夺星烂。\n感激阳秋辞，奸雄非所惮。\n蜀弱自为正，曹强乃名乱。\n阴忤柄臣意，飘然去恩馆。\n驱车自北门，四頋兴长饮。\n终焉谢病免，犹得为人半。\n缅矣身后名，临风寄悽惋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '习彦威' AND p.poem_author = '宋庠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与王永锡廖敷锡同游三洲岩', '张吉', '明代', '仙岩渺何许，宛在碧岑间。我来不惮远，鼓枻湘水湾。\n\n亦有同舟客，荧荧俱妙颜。舍舟入岩际，岩溜方潺潺。\n\n探幽动野癖，窥罅讶天悭。云深隐白日，薄寒侵蒯菅。\n\n时见空洞表，悠悠鸾鹤还。安知峡山里，吏隐非真閒。\n\n芳筵湛清酤，代舞秉长蕳。苍壁多往躅，跻陵忘险艰。\n\n更闻有仙客，炼形依此山。去来骑苍鹿，飘忽难追攀。\n\n我欲见此客，敢辞捐佩环。再拜问至诀，永超生死关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与王永锡廖敷锡同游三洲岩' AND p.poem_author = '张吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天', '林英男', '当代', '万里冥冥呼雁嘹，去年人面自夭夭。梦醒还忆泪珠滴，明灭尚随曦露消。\n\n枉种玉，未抽苗。月寒何处觅鲛绡？山空犹被鹧鸪恼，风雪杨花吞谢桥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天' AND p.poem_author = '林英男';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('论俗十二首', '刘子翚', '宋代', '野人厌羹藜，家有庖丁刀。\n徒夸批导手，肯念耕稼劳。\n隐然肉山雄，畏彼尺箠操。\n春泥卧寒野，夜月犁东皋。\n辛勤力已尽，觳觫祸岂逃。\n谁无恻隐心，鲜能胜贪饕。\n盖惧犹示恩，况异犬马曹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '论俗十二首' AND p.poem_author = '刘子翚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉楼春', '茅于美', '近代', '人间欢爱须深会，为有相亲无限意。自从结识到而今，三十一年心不易。\n\n世情洞彻谁似子，历尽险夷多少事。形神与共景常新，即此蓬瀛方外地。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉楼春' AND p.poem_author = '茅于美';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄归余舅 其一', '黄公辅', '明代', '轻舫逐江流，天涯慷慨游。寒风透客衽，月下忆同俦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄归余舅 其一' AND p.poem_author = '黄公辅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白莲花', '释善月', '宋代', '天开地闢讵云赊，异草灵苗特一家。\n不有冈头三女粲，争敷处子六郎花。\n英雄有种凛生气，白玉微根不受瑕。\n他时若补芬陀传，端与优昙定等差。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白莲花' AND p.poem_author = '释善月';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('可恨辞八首 其二', '孙原湘', '清代', '垂帘作节雨萧萧，苦隔相思又两朝。弱线定随情绪乱，寒灯应带泪痕抛。\n\n坐来自分身难近，别后无如骨暗销。记否去年飞雪夜，鸭炉心字共香烧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '可恨辞八首 其二' AND p.poem_author = '孙原湘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠聪上人 其一', '王弘诲', '明代', '定中观自性，趺坐已多年。为了斋僧愿，来寻结众缘。\n\n心空涵水月，境寂见人天。若问西来意，忘言得妙诠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠聪上人 其一' AND p.poem_author = '王弘诲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('此君室 其八', '方岳', '宋代', '一径自明月，谁能此婆娑。床头易未了，如此良夜何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '此君室 其八' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('第五泉', '弘历', '清代', '有冽蜀冈上，春来玉乳新。可识品泉者，非关姓陆人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '第五泉' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苏武慢', '虞集', '元代', '云淡风轻，傍花随柳，将谓少年行乐。高阁林间，小车城里，千古太平西洛。\n\n瞻彼泱泱，言思君子，流水俨然如昨。但清游、天际轻阴，未便暮愁离索。\n\n长记得、童冠相随，浴沂归去，吟咏鸢飞鱼跃。逝者如斯，吾衰甚矣，调理自存斟酌。\n\n清庙朱弦，旧堂金石，隐几似闻更作。农人告我事西畴，窈窕挂书牛角。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苏武慢' AND p.poem_author = '虞集';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日杂兴 其五', '韩淲', '宋代', '四时景自足，何必写以诗。诗成句读间，不过我自知。\n\n但恐两眼昏，心识如乱丝。血气一耗散，逐物之所之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日杂兴 其五' AND p.poem_author = '韩淲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬曹户', '赵汝鐩', '宋代', '奔走尘埃久，还山每叹迟。\n岁华惊雁到，心事独鸥知。\n夜对樽前月，昼寻花下棋。\n闲中滋味好，但欠子论诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬曹户' AND p.poem_author = '赵汝鐩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶题 其三', '辛弃疾', '宋代', '闲花浪蕊不知名，又是一番春草生。病起小园无一事，杖藜看得绿阴成。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶题 其三' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('盛德篇赠伍侍御', '方献夫', '明代', '在昔唐虞称盛德，一心危微慎精一。予违汝弼臣且都，淫乐逸游君弗咈。\n\n夏禹孜孜施鼓鼗，殷汤从谏亦如尧。武王下车勤访道，皇皇召公忧旅獒。\n\n猗与成康号至治，六典敷陈百官备。瞽矇献诵工进规，左史书言右书事。\n\n自从监谤降秦威，汉帝庶几除族诽。那知言路归台谏，非位不言言者稀。\n\n爰使后王多失德，轮台虽悔夫何益。城狐社鼠世复纷，仗马一鸣恒见斥。\n\n轫首乘舆能几人，寥寥青史说埋轮。皂雕独鹘亦何有，补阙拾遗犹仅闻。\n\n伍君才隽名江右，早入乌台纡豸绣。巡行两广志澄清，察察籍书为所后。\n\n风采如兹今古难，未几入奏侍天颜。六飞在道豺狼满，危言伫看回丘山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '盛德篇赠伍侍御' AND p.poem_author = '方献夫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂七十六首 其五十三', '释师范', '宋代', '达磨西来，添盐减酱。后代儿孙，千般万样。谁信棋盘石，元在凌霄上。\n\n山僧恁么道，已是龟毛长数丈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂七十六首 其五十三' AND p.poem_author = '释师范';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆又儒弟', '圆能', '清代', '野水新添曲槛多，无端世事怅蹉跎。西风万里归人少，明月遥天一雁过。\n\n祇为壮游羁瘴海，不堪老眼盼山河。心情已逐秋容减，何日相期话薜萝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆又儒弟' AND p.poem_author = '圆能';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵答克修', '邓深', '宋代', '懒慢相成拙似初，亲朋莫问近何如。\n居然野性成孤鹤，聊尔尘编扑蠹鱼。\n才比刘墙犹自短，诗如陶粟了无储。\n骊珠相畀知君厚，燕石轻酬笑疏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵答克修' AND p.poem_author = '邓深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题四景山水 其一', '邓林', '明代', '春山无伴独相寻，欲觅知音听鼓琴。翠壁苍崖千万仞，人龙虽见白云深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题四景山水 其一' AND p.poem_author = '邓林';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重游七星岩', '伯昏子', '当代', '星岩数历未曾攀，螺髻犹青鬓已残。急雨无凭飞岫窟，浮舟何日不波澜。\n\n老榕伏水根衔石，紫瓣委风心著丹。萧瑟诗情怅题处，王侯满壁字蹒跚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重游七星岩' AND p.poem_author = '伯昏子';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('涵空阁', '潘牥', '宋代', '危栏贪倚眺，薄暮不能休。\n直下疑无地，满前都是秋。\n晚山平入画，新月侧当楼。\n莫说兴亡事，吟人本白头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '涵空阁' AND p.poem_author = '潘牥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠友侄林贻燕兄弟', '屈大均', '明代', '林屋怀君好父兄，重来莞水不胜情。龙媒竞蹀风云起，稚子齐斑锦绣成。\n\n花到炎天无月令，莺当大雪已春声。文章莫但高吾党，乃祖先朝最有名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠友侄林贻燕兄弟' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵刘无言游法云寺', '饶节', '宋代', '磨蚁迭左右，铁炭互俯仰。岁月如牧马，快骤脱羁鞅。\n\n方希草玄雄，未羡画眉敞。刘侯启予者，险韵写胜赏。\n\n读之令人醒，居然见图像。我昔曾此游，僧梵荐肸蚃。\n\n撞钟鸣木鲤，破我颠倒想。百年能几许，万事苦鞅掌。\n\n丧身声利场，齿角伐犀象。前辈晓云散，后生春水长。\n\n君看门外辙，盛气日来往。道人初不省，禅寂异到壤。\n\n乃知雨花地，可以透迷网。君侯此嘉集，尘迹已相荡。\n\n援琴写我叹，中夜发哀响。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵刘无言游法云寺' AND p.poem_author = '饶节';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金兰为华德题', '倪谦', '明代', '蕙兰被幽谷，绿叶何纷披。紫茎擢芳蕤，英芬吐清奇。\n\n岂同凡草伍，自与修筠宜。终岁抱贞独，不求人见知。\n\n所以君子心，对之情自怡。谁将丘壑容，涅以黄金泥。\n\n光辉烛人目，粲粲生华滋。外貌虽可夺，至性终不移。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金兰为华德题' AND p.poem_author = '倪谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乞菊，次周恒甫韵', '陈肇兴', '清代', '幽斋秋老遍苍苔，只有寒英数朵开。自是黄金难买得，一诗才换一枝来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乞菊，次周恒甫韵' AND p.poem_author = '陈肇兴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陇头歌五首 其四', '胡应麟', '明代', '欲寄征人信，难禁玉箸啼。惟应纸上泪，点滴到辽西。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陇头歌五首 其四' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('遣兴', '周文璞', '宋代', '山中雨更愁，不是弃吾州。\n怀母未能去，诉邻谁肯留。\n茶人穷似虱，药户狭于舟。\n一磵多深碧，嘲吟尚自由。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '遣兴' AND p.poem_author = '周文璞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凉', '弘历', '清代', '半夜西风晓骤寒，数声霜信度云端。前朝跋马看山稼，逮熟无妨意为宽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凉' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('《永沂集联》自序诗五首 其三', '何永沂', '当代', '浇吾块垒清溪水，借尔飘零浊酒杯。天造句缘成对对，来吟肺腑走风雷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '《永沂集联》自序诗五首 其三' AND p.poem_author = '何永沂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饶阳杂诗十首 其六 高坡道中', '郑学醇', '明代', '至后寒山纷落木，夕阳茅屋几炊烟。天涯容易愁孤客，莫更西风送断猿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饶阳杂诗十首 其六 高坡道中' AND p.poem_author = '郑学醇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鄂归寄占憨上人', '吴寿平', '清代', '不见融公久，尘氛扫未开。秋风辞鄂渚，落月梦苍苔。\n\n何日经岩下，重来谒辨才。云笺先此寄，不待折寒梅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鄂归寄占憨上人' AND p.poem_author = '吴寿平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登华山三首 其二', '高孝本', '清代', '谁开千尺峡，断处若相连。岂有丹梯接，惟凭铁绠悬。\n\n猿攀岩倒上，鼠伏穴傍穿。自度车箱谷，飞升傲列仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登华山三首 其二' AND p.poem_author = '高孝本';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春草曲', '薛季宣', '宋代', '霰雪枝头寒已老，平芜一夜铺春草。江梅著子怯东风，花落满庭浑不埽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春草曲' AND p.poem_author = '薛季宣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('呈茅一霁先生', '黄庚', '宋代', '前辈凋零尽，如公尚典型。\n为僧眉独白，见客眼长青。\n教子成三俊，传家有六经。\n我来问奇字，应许扣柴扃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '呈茅一霁先生' AND p.poem_author = '黄庚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金盏倒垂莲', '佚名', '宋代', '依约疏林，见盈盈春意，几点霜蕤。应是东君，试手作芳菲。粉面倚、天风微笑，是日暖、雪已晴时。人静么凤翩翩，踏碎残枝。幽香浑无著处，甚一般雨露，独占清奇。淡月疏云，何处不相宜。陌上报春来也，但绿暗、青子离离。桃杏应仗先容，次第追随。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金盏倒垂莲' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟过湖州', '贡奎', '元代', '楼台金碧照嵯峨，故国诸公奈乐何。辽鹤归来城郭在，海鸥飞处水云多。\n\n春回废苑花新发，愁满空船客自过。回首蒹葭三十里，天风落日断渔歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟过湖州' AND p.poem_author = '贡奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七言 其九', '吕岩', '唐代', '谁信华池路最深，非遐非迩奥难寻。九年采炼如红玉，一日圆成似紫金。\n\n得了永袪寒暑逼，服之应免死生侵。劝君门外修身者，端念思惟此道心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七言 其九' AND p.poem_author = '吕岩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戒事魔十诗 其五', '李兼', '宋代', '生儿只遣事犁锄，有智宜令早读书。莫被胡辉相引诱，此人决脊尚囚拘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戒事魔十诗 其五' AND p.poem_author = '李兼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('翠羽辞', '梅尧臣', '宋代', '秦女乘鸾遗翠羽，落在人间与风舞。\n风休不归谁作主，此郎拾取装金缕。\n郎家主妇爱且怜，系向裙腰同出处。\n朝来邻里偶经过，方朔邹枚争欲睹。\n主人重客苦留连，急走钿车令去取。\n酒巡未匝掩合扉，忽已闻归报鹦鹉。\n重匀朱粉临镜台，促息不停催出户。\n正抱琵琶稳系条，辊作轻雷拢作雨。\n自解弹成啄木声，岂唯能写胡人语。\n醉眼流波入鬓时，弦慢遨郎紧弦柱。\n身柔柱涩郎力微，欲倩傍人频顾主。\n主何磊落风味多，就请上宾无不许。\n相疏情远谁称渠，画拨当胸客当去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '翠羽辞' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('都城正阳门西大士祠予向尝游乌近乃知为故明洪督师祠也 其一', '全祖望', '清代', '当年谕祭十三坛，东向招魂泪未乾。岁晚辽阳讶归鹤，须眉犹是发肤残。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '都城正阳门西大士祠予向尝游乌近乃知为故明洪督师祠也 其一' AND p.poem_author = '全祖望';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬夜醉宿龙门，觉起言志', '李白', '唐代', '醉来脱宝剑，旅憩高堂眠。中夜忽惊觉，起立明灯前。 \n 开轩聊直望，晓雪河冰壮。哀哀歌苦寒，郁郁独惆怅。 \n 傅说版筑臣，李斯鹰犬人。欻起匡社稷，宁复长艰辛。 \n 而我胡为者，叹息龙门下。富贵未可期，殷忧向谁写。 \n 去去泪满襟，举声梁甫吟。青云当自致，何必求知音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬夜醉宿龙门，觉起言志' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三阁词（二首）', '杨慎', '明代', '桃根桃叶斗春葩，《水调》河传穆护砂。\n无限江南新乐府，君王独赏《后庭花》。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三阁词（二首）' AND p.poem_author = '杨慎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游潘园感赋', '黄遵宪', '清代', '神山左股割蓬莱，惘惘游仙梦一回。海水已乾田亦卖，主人久易我才来。\n\n楼梁燕子巢林去，对镜荷花向壁开。弹指须臾千载后，几人起灭好楼台！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游潘园感赋' AND p.poem_author = '黄遵宪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵周畏知问讯城东梅坞七首', '张栻', '宋代', '人情自尔变迁，此道不渝燥湿。\n未妨静处闲观，要知二五即十。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵周畏知问讯城东梅坞七首' AND p.poem_author = '张栻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('河南巡抚陈宏谋奏报得雨', '弘历', '清代', '麦收三月雨，农谣向所传。中州土脉厚，更以麦为天。\n\n去岁河堤溃，数郡遭迍𨗍。瓠子幸成功，颇有涸出田。\n\n麦芽遍陇青，农父冀逢年。迩日春霖时，南顾心旌悬。\n\n朝来览章疏，一雨千里连。饼饵略可期，吾民救眉燃。\n\n元气岂易复，虔望秋成全。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '河南巡抚陈宏谋奏报得雨' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小金山寺', '区元晋', '明代', '珠林寻胜迹，閒忆十年前。野藾借僧鼎，山茶瀹涧泉。\n\n碑文残异代，花影寂禅天。却羡云边鹭，飞飞傍水田。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小金山寺' AND p.poem_author = '区元晋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小儿初度', '吴与弼', '明代', '家幸平康为乐天，世遵清白矢心坚。园林百果春如海，几阁群书日似年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小儿初度' AND p.poem_author = '吴与弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('齐天乐·春望', '陈家庆', '清代', '青皇偶向人间驻，芳菲便添如许。曲岸沙平，长堤草润，才过一犁疏雨。\n\n时闻笑语。正十里芳塍，春锄处处。几日迟来，东风绿尽涧边树。\n\n鸣禽渐抽绮绪。乱莺声不断，歌送金缕。竹外花开，江头水暖，绝忆坡仙佳句。\n\n幽怀漫吐。试写入丹青，难传毫素。祗恐流光，霎时来又去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '齐天乐·春望' AND p.poem_author = '陈家庆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('盛夏东轩偶成五首 其一', '曾几', '宋代', '一堂既虚闲，一室可息偃。松篁度风清，窗户去日远。\n\n幽禅过亭午，凉气生薄晚。阃内即妻孥，更深遂忘返。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '盛夏东轩偶成五首 其一' AND p.poem_author = '曾几';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春郊即事', '宋登春', '明代', '春风袅袅夕阳西，芳草菲菲杨柳堤。\n行尽溪山有茅屋，青林深处一鸠啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春郊即事' AND p.poem_author = '宋登春';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('韩翃舍人即事', '李商隐', '唐代', '萱草含丹粉，荷花抱绿房。鸟应悲蜀帝，蝉是怨齐王。 \n 通内藏珠府，应官解玉坊。桥南荀令过，十里送衣香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '韩翃舍人即事' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和直指答方仲姚', '释慧空', '宋代', '海燕坐间谈实相，泥人梦里获真如。空中种黍长年饱，陆地栽莲永不枯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和直指答方仲姚' AND p.poem_author = '释慧空';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('用前韵', '张纲', '宋代', '雪残春信近，山迥客愁新。兴极樽无酒，诗成笔有神。\n\n玩心云物变，惊梦雨声频。坐对华严海，忘言意自亲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '用前韵' AND p.poem_author = '张纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('旅怀', '姜特立', '宋代', '寄迹双溪上，秋声动远林。\n断云流影薄，过雁云痕深。\n旧馆生离思，新愁阙寄音。\n到头俱梦事，俯默一长吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '旅怀' AND p.poem_author = '姜特立';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山林小队春卧', '俞律', '近代', '茆屋临歧路，栖迟物外身。槛低新草入，雨过午风驯。\n\n多睡厌春梦，能真畏古人。不知今月日，隔水问东邻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山林小队春卧' AND p.poem_author = '俞律';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渡澜沧江', '田榕', '清代', '长虹一跨并槎浮，博望真夸万里游。要隘地矜三齿险，承平人散八关愁。\n\n江于上下疑无底，天到西南欲尽头。黑水穷源何处是，哀牢郡县古梁州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渡澜沧江' AND p.poem_author = '田榕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('缘识 其五十二', '赵炅', '宋代', '般若须将法相宗，四生九类化归空。离然应物随缘境，自是凡夫道不通。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '缘识 其五十二' AND p.poem_author = '赵炅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('田无秋兴', '蒲寿宬', '宋代', '草屋柴门风露凉，寒瓜收蔓力锄荒。\n新栽莙薘恰逢雨，欲剪芹蓝犹待霜。\n牧竖归来煨芋熟，田翁相就泼醅香。\n里胥偶报徵苗急，自辟閒畦早築场。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '田无秋兴' AND p.poem_author = '蒲寿宬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙 其一 仿饮水词只求貌似却无题目也', '梁鼎芬', '清代', '才说当时泪暗倾。宵宵寒雨绿阴成。有人帘外盼天晴。\n\n独自空庭花细落，那堪今夜月微明。药烟茶梦断平生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙 其一 仿饮水词只求貌似却无题目也' AND p.poem_author = '梁鼎芬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闺怨一百首次孙西庵原韵 其九十一', '郭辅畿', '明代', '清画深深枫叶红，轻纨力薄未成风。人情偏似风情变，每到秋来不肯东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闺怨一百首次孙西庵原韵 其九十一' AND p.poem_author = '郭辅畿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('项山人季舆过访赋赠二首 其二', '胡应麟', '明代', '总为寻诗过，难将问字留。万峰阳羡色，双艇石湖秋。\n\n雾拥王孙佩，星随客子裘。归来定何日，长倚碧云楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '项山人季舆过访赋赠二首 其二' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('抵里后寄留都诸同志', '金朝觐', '清代', '微雨莺声御柳新，飞花流水曲江春。君王许作归田计，文字难为造福神。\n\n东国怀思空近日，北堂称寿慰慈亲。大罗天上分明在，一觉游仙梦未真。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '抵里后寄留都诸同志' AND p.poem_author = '金朝觐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湟川', '陆节', '宋代', '从来瑰异产天涯，土物人风分外嘉。\n愿写湟川川上景，与君传入凤池夸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湟川' AND p.poem_author = '陆节';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和叶某留别原韵 其七', '戴亨', '清代', '和光蛇虎亦须亲，避世襟期别有春。大地蜉蝣悲浩劫，先天消息迓文茵。\n\n晤言顿醒浮生梦，把臂还惊顷刻身。是否请君回首看，新人争逐旧人驯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和叶某留别原韵 其七' AND p.poem_author = '戴亨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渡汶河 其一', '弘历', '清代', '湛湛复沄沄，长虹亘两濆。山川千里互，齐鲁一渠分。\n\n济运常资是，成盟旧所闻。道元称博览，已见数名纷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渡汶河 其一' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和同府李祭酒休沐田居', '李峤', '唐代', '列位簪缨序，隐居林野躅。徇物爽全直，栖真昧均俗。 \n 若人兼吏隐，率性夷荣辱。地藉朱邸基，家在青山足。 \n 暂弭西园盖，言事东皋粟。筑室俯涧滨，开扉面岩曲。 \n 庭幽引夕雾，檐迥通晨旭。迎秋谷黍黄，含露园葵绿。 \n 胜情狎兰杜，雅韵锵金玉。伊我怀丘园，愿心从所欲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和同府李祭酒休沐田居' AND p.poem_author = '李峤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花', '仲殊', '宋代', '北固山前波浪远。铁瓮城头，画角残声短。促酒溅金催小宴。灯摇蜡焰香风软。落日烟霞晴满眼。欲仗丹青，巧笔彤牙管。解写伊川山色浅。谁能画得江天晚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花' AND p.poem_author = '仲殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诗偈 其一一八', '庞蕴', '唐代', '苦痛役身心，劳神觅官职。暂得色毛披，拍按作瞋色。\n\n口口打奴兵，声声遣拔肋。闻道送王老，曲亦变成直。\n\n纵令有理道，分疏亦不得。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诗偈 其一一八' AND p.poem_author = '庞蕴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠奚举人', '庄昶', '明代', '归去云霞费几藤，家山容有未曾登。一灯须了相传意，莫作人间应付僧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠奚举人' AND p.poem_author = '庄昶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和诸庵花光十梅颂 其三', '王柏', '宋代', '空里翻身透出，风前玉立精神。百草头边未觉，还他独占先春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和诸庵花光十梅颂 其三' AND p.poem_author = '王柏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丹霞诗十二首 其二 法堂', '释函是', '明代', '紫玉屏临翠石栏，万山林立一峰寒。琼楼金殿空中幻，宝几华巾云外安。\n\n穷子衣珠终自得，仙人罗扇不须看。一铺直接庾关上，香水潺潺到此间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丹霞诗十二首 其二 法堂' AND p.poem_author = '释函是';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日平定候代次韵詶任苗二子', '杨巍', '明代', '如何已解绶，犹此客天涯。为有求羊过，频开早晚衙。\n\n诗人情自好，尘世事堪嗟。遥忆岭园里，春深树树花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日平定候代次韵詶任苗二子' AND p.poem_author = '杨巍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('途中寄君时弟 其二', '彭汝砺', '宋代', '天晴日驭去迟迟，恰是春风中半时。柳色笑花须似锦，雨声欺雪故如丝。\n\n迁乔他日吾求友，发药明朝汝得师。乐事信知人不及，异乡同有拜亲期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '途中寄君时弟 其二' AND p.poem_author = '彭汝砺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绝句', '宋庠', '宋代', '波环颍曲持竿石，云拥嵩岩鍊药炉。\n尽是他年归隐计，更凭猿鹤作前驱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绝句' AND p.poem_author = '宋庠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小饮西湖，怀欧阳叔弼兄弟，赠赵景贶、陈履', '苏轼', '宋代', '岁暮自急景，我闲方缓觞。\n欢饮西湖晚，步转北渚长。\n地坐略少长，意行无涧冈。\n久知荠麦青，稍喜榆柳黄。\n盎盎春欲动，潋潋夜未央。\n水天鸥鹭静，月露松桧香。\n抚景方晼晚，怀人重凄凉。\n岂无一老兵，坐念两欧阳。\n我意正麋鹿，君材亦珪璋。\n此会不可再，此叹不可忘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小饮西湖，怀欧阳叔弼兄弟，赠赵景贶、陈履' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('食茯苓粥', '马治', '明代', '颇闻学士防风粥，曾吃诗人锦带羹。岂谓茯苓宜岁晚，已收粳稻得霜晴。\n\n腥膻习漫从教洗，禽鸟形残不忌烹。饱食未须论月给，石杉偕坐听松声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '食茯苓粥' AND p.poem_author = '马治';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题长江霁雪图', '钱宰', '元代', '昔年壮游下江汉，霁雪千峰排两岸。今年看画忆旧游，万里江山入清玩。\n\n岷峨冈脊来蜿蜒，青城一峰高插天。东驰衡山走千里，匡庐五老与石城、北固遥相连。\n\n冰峦雪壑互起伏，照见日华破初旭。神光混茫元气浮，奋如巨鳌簸坤轴。\n\n烂如秋空云，浩如沧海涛。又如瑶台银阙天上头，皎皎白月空秋毫。\n\n回光下照中流水，风吹河汉银云起。中流空阔不胜寒，一洗丹碧秋漫漫。\n\n山川历历真伟观，来往十年游未半。不如云瀛楼上来倚阑，一日看遍江南山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题长江霁雪图' AND p.poem_author = '钱宰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东平路中遇大水', '高适', '唐代', '天灾自古有，昏垫弥今秋。霖霪溢川原，澒洞涵田畴。 \n 指途适汶阳，挂席经芦洲。永望齐鲁郊，白云何悠悠。 \n 傍沿钜野泽，大水纵横流。虫蛇拥独树，麋鹿奔行舟。 \n 稼穑随波澜，西成不可求。室居相枕藉，蛙黾声啾啾。 \n 仍怜穴蚁漂，益羡云禽游。农夫无倚著，野老生殷忧。 \n 圣主当深仁，庙堂运良筹。仓廪终尔给，田租应罢收。 \n 我心胡郁陶，征旅亦悲愁。纵怀济时策，谁肯论吾谋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东平路中遇大水' AND p.poem_author = '高适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('魏仲礼金笔院景四首 其二', '张宁', '明代', '罘罳玉馆未垂络，水殿玲珑澄碧落。綵扇翻香蛱蝶轻，绡衣簇翅蜻蜓薄。\n\n钓天画永无纤埃，水晶帘动南薰来。三千粉黛放将尽，十二楼台閒自开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '魏仲礼金笔院景四首 其二' AND p.poem_author = '张宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('伯父挽诗二首 其一', '刘攽', '宋代', '遂有终焉志，才成智者居。户庭连水竹，几杖接舟舆。\n\n爱客樽中酒，传家箧里书。疏公知足计，不益旧田庐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '伯父挽诗二首 其一' AND p.poem_author = '刘攽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三月九日复同陆先生及子侄泛湖至后州买樱桃', '黄侃', '近代', '小门北出即船滨，落日微风水一泓。移棹有时妨翠荇，满笼无意得朱樱。\n\n岚光澹沱低依树，烟缕霏微静绕甍。惬意幽寻殊未极，忽闻同泰暮钟铿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三月九日复同陆先生及子侄泛湖至后州买樱桃' AND p.poem_author = '黄侃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶成', '陈永正', '当代', '谁人晞发向阳阿，满眼楼台夕照多。入世渐深诗渐浅，不知沧海有惊波。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶成' AND p.poem_author = '陈永正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乾明节祝圣寿 其十一', '田锡', '宋代', '日上扶桑第一枝，东方楼阁曙光时。万邦将启乾明宴，两制应宣御制诗。\n\n乐感羽毛皆率舞，神和福禄自来宜。谏垣班列天颜近，暂乞归朝侍玉墀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乾明节祝圣寿 其十一' AND p.poem_author = '田锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('依韵奉和（四首）', '祝允明', '明代', '风情拟我杜樊川，惭愧秋娘拥两边。\n俗眼从渠浪开合，生来粘在十三弦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '依韵奉和（四首）' AND p.poem_author = '祝允明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('成性吟', '邵雍', '宋代', '成性存存，用志不分。\n又何患乎，不到古人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '成性吟' AND p.poem_author = '邵雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宁守杜君过扬来询里社近状 其四', '全祖望', '清代', '元气胡为耗，潜消市舶中。频年添客户，百货酿淫风。\n\n物以通商贵，民因逐末穷。更堪加税吏，悉索茧丝空。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宁守杜君过扬来询里社近状 其四' AND p.poem_author = '全祖望';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏赠玉卿', '韩上桂', '明代', '美人金屋自舒徐，何事忙乘广柳车。义重绿珠宁怕死，奔随红拂未安居。\n\n罗衣典尽惟沽酒，玉珥捐残但买鱼。却笑堂前豪侠客，报仇谁得似专诸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏赠玉卿' AND p.poem_author = '韩上桂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏咏参悟诗三十四首 其三十三', '陈振家', '当代', '日打青蝇夜打蚊，业多未敢望法门。待除天下害虫尽，再拟赎罪访世尊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏咏参悟诗三十四首 其三十三' AND p.poem_author = '陈振家';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('知宗赠驴肉以膰肉酬之', '王十朋', '宋代', '不骏于乘合见烹，铃斋指动荷分羹。区区膰肉非相报，正恐公为孔子行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '知宗赠驴肉以膰肉酬之' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('服仙灵脾酒', '张耒', '宋代', '冷气侵吾髀，趋拜剧苦艰。\n仁哉神农氏，遗药驱恫瘝。\n持钱取之市，易得如茆芫。\n繁枝与芳叶，尽取无可删。\n贮之白缣囊，清以壶酒宽。\n七日以供饮，跛曳皆翩跹。\n呼儿谨盖藏，用此九转丹。\n平生误信书，安坐得老邅。\n方书岂尽信，柳子固无言。\n事固有然者，岂容尽欺谩。\n疾走非吾愿，且复补羸残。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '服仙灵脾酒' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽方中立同舍', '何梦桂', '宋代', '回首炉亭梦已非，英雄老尽壮心违。钧天云散苍龙堕，华表风寒白鹤归。\n\n往事悠悠川水逝，故人落落曙星稀。乐天无子留孙在，多少龙门客泪挥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽方中立同舍' AND p.poem_author = '何梦桂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九月十九辱德进招饮时适邀黄将军为改次日德进惠以二绝次韵奉答', '林熙春', '明代', '九日龙山游未罢，平原萸酒有余香。将军趣驾迟君约，却负东篱自向阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九月十九辱德进招饮时适邀黄将军为改次日德进惠以二绝次韵奉答' AND p.poem_author = '林熙春';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观风台', '杨雍建', '清代', '城上高台接混茫，天都风物郁苍苍。云封雉堞千村绕，地并乌聊六水长。\n\n见说春溪仍乐土，安知歙浦一残疆。黄峰极目徒相望，赢得愁思满客囊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观风台' AND p.poem_author = '杨雍建';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饮于梅山弟家醉书八首', '陈著', '宋代', '老我衰颜百念煎，梅山少我十三年。\n人生不问寿长短，得一日宽皆是仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饮于梅山弟家醉书八首' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏夜', '陈与义', '宋代', '闲弄玉如意，天河白练横。\n时无李供奉，谁识谢宣城。\n两鹤翻明月，孤松立快晴。\n南阳半年客，此夜满怀清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏夜' AND p.poem_author = '陈与义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江西官氏二烈女次雪湖韵', '谢迁', '明代', '节义真大闲，浮生仅朝露。谁谓捐生仁，乃出两荆布。\n\n济济冠佩徒，讲习亦有数。临难辄易心，宁愧所学负。\n\n忆昨大江西，凶逆啸而聚。皎皎双白璧，不受纤尘污。\n\n一死等鸿毛，裕若身为度。颇闻官氏宗，自昔遵王路。\n\n世德贻范谟，奕叶昌𦙍祚。丈夫槩可知，大节况童孺。\n\n诏旨揭门闾，褒旌岂虚誉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江西官氏二烈女次雪湖韵' AND p.poem_author = '谢迁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂八十五首 其六十', '释妙伦', '宋代', '心心，拙妇穿穴针。智智，巫师骂土地。道道，矮子肩栲栳。\n\n佛佛，乌鸦啖腐骨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂八十五首 其六十' AND p.poem_author = '释妙伦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送任逵度支监嵩山崇福宫', '曾巩', '宋代', '汉阳门下士，车骑幕中宾。\n志节初皆壮，风流久更新。\n枢庭承远派，郎位袭清尘。\n雅淡琴声古，温纯玉性真。\n诗书来射策，慈惠起临人。\n淮海褰帷久，褒斜叱驭频。\n政平无横史，刑省绝冤民。\n汴路扬旌出，吴门拥节巡。\n持权心似水，待物气如春。\n懋德垂承诏，遗荣遽乞身。\n行高宁系俗，道胜不忧贫。\n北绝分琳馆，西归近紫宸。\n鸿飞开羽翼，骥逸圳精神。\n却理烟霞宅，重寻水石禽。\n青嵩销鹤怨，碧洛见鸥驯。\n故友欣联璧，诸儒慕垫巾。\n学兼鸿宝异，兴与赤松亲。\n激劝留方册，惊传动缙绅。\n浮云虽抗意，仄席正逢辰。\n只恐尊廉退，丁宁致软轮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送任逵度支监嵩山崇福宫' AND p.poem_author = '曾巩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八声甘州二首 其二 哀济南', '顾随', '近代', '便将来重复到明湖，胜游总成空。任三更渔唱，数声柔橹。\n\n半夜荷风。只怕双擎泪眼，觅不到残红。点点青磷火，芦苇丛中。\n\n眼看春光又老，谩酿成春色，费尽春工。上九重天上，细问碧翁翁。\n\n甚年年、伤春不了，却一春、不与一春同。春归去、已匆匆了，莫再匆匆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八声甘州二首 其二 哀济南' AND p.poem_author = '顾随';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陈留书事', '杨时', '宋代', '乌樯风缆欲飞翾，拍岸惊涛挽不前。\n曲浦涨沙仍积冻，疏林余日自生烟。\n崎嵚道路真堪笑，放浪江湖已判年。\n一枕昼眠无好梦，空惭边老腹便便。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陈留书事' AND p.poem_author = '杨时';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游城北李氏园池', '孔武仲', '宋代', '池塘春色归，波水已极目。\n凫雁稍下来，垂杨舞新绿。\n登临不惮远，枉径入重复。\n已见数种花，参差隔修竹。\n非特野兴长，彩翠动华屋。\n沁园天下名，鲁馆当年筑。\n百年犹盛丽，风景冠辇毂。\n当时手种植，仰视皆乔木。\n主人况仁贤。客至初不速。\n跻攀脚力尽，更酌以醽渌。\n左右列图书，南北置淆蔌。\n夕阳整归骖，尚谓夜可卜。\n明日忆胜游，长歌寄金谷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游城北李氏园池' AND p.poem_author = '孔武仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十二月二十七日病起行花下闻春禽有感', '舒岳祥', '宋代', '昨日立春节，今晨春鸟鸣。\n前峰宿苍霭，风声和且平。\n南翁病来久，起绕花枝行。\n花枝向人笑，\n婉娈感幽情。摩挲朂小男，\n何时看汝成。童稚引我前，\n老至不觉惊。艰难亦已极，\n须汝见休明。望望替官役，\n不顾日月征。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十二月二十七日病起行花下闻春禽有感' AND p.poem_author = '舒岳祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('项羽庙', '曾棨', '明代', '百战休论盖世功，鸿门宴罢霸图空。\n虞歌慷慨孤灯下，楚业消沉一炬中。\n露湿古墙秋藓碧，霜含老树夕阳红。\n英魂若到彭城路，忍听高台唱《大风》。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '项羽庙' AND p.poem_author = '曾棨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题扇 其四 郎景韦', '仇远', '宋代', '红紫委尘土，绿窗清昼长。安知两三竹，风已作秋凉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题扇 其四 郎景韦' AND p.poem_author = '仇远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和杨郎中贺杨仆射致仕后杨侍郎门生合宴席上作', '白居易', '唐代', '业重关西继大名，恩深阙下遂高情。祥鳣降伴趋庭鲤， \n 贺燕飞和出谷莺。范蠡舟中无子弟，疏家席上欠门生。 \n 可怜玉树连桃李，从古无如此会荣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和杨郎中贺杨仆射致仕后杨侍郎门生合宴席上作' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪拟苏轼聚星堂体兼用其韵', '弘历', '清代', '苏辞遭遇多枝叶，倒绷禁体先犯雪。起舞浮白意匠殊，纵横驱用堪叫绝。\n\n元冥恰喜交初节，过水真如遇方折。平原羃䍥寒飔逼，长空晻霭暮光灭。\n\n旌门铙吹云璈奏，幔城漏响金鱼掣。徘徊中夜听拉瑟，行檠熻赩莲花缬。\n\n天窗取气揭薄纱，地炉生火燃枯屑。\n\n遥想林岫已婆娑，却爱郊坰正飘瞥。即景朅咏都官句，占年夙记农家说。\n\n醉翁髯老垂号令，会取陈言能点铁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪拟苏轼聚星堂体兼用其韵' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花', '仇远', '宋代', '燕燕楼空帘意静。露叶如啼，红沁胭脂井。浅约深盟期未定。木犀风里鸳鸯径。 \n 楚岫秦眉相入映。私倚云阑，淡月笼花顶。今夕兰釭空吊影。绣衾罗荐余香冷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花' AND p.poem_author = '仇远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送相里秀才自京至却回', '齐己', '唐代', '夷门诗客至，楚寺闭萧骚。老病语言涩，少年风韵高。 \n 难于寻阆岛，险甚涉云涛。珍重西归去，无忘役思劳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送相里秀才自京至却回' AND p.poem_author = '齐己';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别后歌丽制不觉引满大醉醉中成四绝句奉纳', '梦苏道人', '明代', '人言元白再来身，我道奎中降下神。\n谁遣玲珑唱新曲，江南添得十分春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别后歌丽制不觉引满大醉醉中成四绝句奉纳' AND p.poem_author = '梦苏道人';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题八士图', '方岳', '宋代', '雅闻八士春俱秀，未觉三贤迹已陈。\n投分不论曾识面，此图到手便情亲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题八士图' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬归繁台别业漫兴', '李梦阳', '明代', '莽圹孤城此卜居，宋台梁苑独行予。虚名马愧千金后，白首萤怜万卷馀。\n\n踏麦遽堪寒叶翠，看梅无那腊花舒。相逢莫漫滇吾放，野醉郊吟尽可书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬归繁台别业漫兴' AND p.poem_author = '李梦阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过净名院触目都似曾到问讯乃非也戏题绝句 其二', '李薰', '宋代', '世间形似巧迷人，总是安排底处真。纵复非真犹足喜，得来聊寄梦中身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过净名院触目都似曾到问讯乃非也戏题绝句 其二' AND p.poem_author = '李薰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉使至申州伤经陷没', '刘长卿', '唐代', '举目伤芜没，何年此战争。归人失旧里，老将守孤城。\n\n废戍山烟出，荒田野火行。独怜浉水上，时乱亦能清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉使至申州伤经陷没' AND p.poem_author = '刘长卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送昙昱侄礼拜净慈愚极老叔', '释月涧', '宋代', '汝今别我去行脚，听我殷勤重告汝。人身难得今已得，直须著意明自己。\n\n只今丛林未寂寥，四海一翁老愚叔。惠日峰前九拜时，照顾粗拳当面筑。\n\n白发盈颠七十翁，期汝有成志超越。为报江海几故人，晚年富贵一矶雪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送昙昱侄礼拜净慈愚极老叔' AND p.poem_author = '释月涧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('淳熙四年二月既望静江守臣张某奉诏劝农于郊', '张栻', '宋代', '嗟尔父老，其训其诫。\n俾务於本，惟土物爱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '淳熙四年二月既望静江守臣张某奉诏劝农于郊' AND p.poem_author = '张栻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观吴孟周司训真草书谱', '方行', '元代', '古来书学宗史籀，竹简遗文象科斗。钟张真草更入神，片楮至今藏不朽。\n\n先生下笔绝代无，鸣玉绾结青珊瑚。况闻篆隶太倔强，百金一字传东吴。\n\n墨池浸没玄兔颖，魑魅反走空堂静。金戟交撑日月轮，银钩倒画龙蛇影。\n\n欧虞褚薛真出群，精妙只数王右军。英姿老气欲飞动，悬珠快剑相纷纭。\n\n呜呼百世谁复识，我今作歌重刻石。莫同茧纸旧兰亭，閟入昭陵永难得。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观吴孟周司训真草书谱' AND p.poem_author = '方行';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬夕小斋联句寄梅圣俞', '陆经', '宋代', '寒窗明夜月，散帙耿灯火。\n破见裂冰澌，败席荐霜笴。\n废书浩长吟，想子实劳我。\n清篇追曹刘，苦语侔岛可。\n酣饮每颓山，谈笑工炙輠。\n驾言当有期，岁晚何未果。\n幽梦辞如云，别愁牢若锁。\n雪水渐涟漪，春枝将婀娜。\n客心莫迟留，苑葩即纷堕。\n何当迎{上竹下ナ下乂}前，相逢嘲饭颗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬夕小斋联句寄梅圣俞' AND p.poem_author = '陆经';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戴生在吾语感秋思归诗以慰留之二首 其一', '何景明', '明代', '到日中元节，淹留岁渐微。而翁在异县，知汝苦思归。\n\n旅馆空弹铗，秋风未授衣。敝床还可宿，暂住莫相违。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戴生在吾语感秋思归诗以慰留之二首 其一' AND p.poem_author = '何景明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('糟蟛蚏送葺芷', '郑清之', '宋代', '月腹一寸能郭索，黄流在中自濡壳。蝤蛑可是丈人行，螃蟹视之师长伯。\n\n二眸挺出胜怒蛙，八跪前驱非屈蠖。笑令樊哙自横行，何用吕布须急缚。\n\n餔糟啜醨乃吾味，嚼齿穿龈未渠恶。属厌祗觉一解胜，效美不辞双距落。\n\n蔡谟但记尊足存，孙卿不悟铁成错。谩誇右手亦持螯，水中之怒无乃虐。\n\n梁王菹醢犹至今，千古吁嗟汉恩薄。玉柱江𧎼酒半酣，银丝鲫鱼脍新斫。\n\n此非不足君所邪，斶顾居贫未能学。虫鱼琐碎熟尔雅，曲生逢之三距跃。\n\n太真小物自足佳，葺芷一笑为飞白。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '糟蟛蚏送葺芷' AND p.poem_author = '郑清之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同家兄题渭南王公别业', '蔡希寂', '唐代', '好闲知在家，退迹何必深。不出人境外，萧条江海心。 \n 轩车自来往，空名对清阴。川涘将钓玉，乡亭期散金。 \n 素晖射流濑，翠色绵森林。曾为诗书癖，宁惟耕稼任。 \n 吾兄许微尚，枉道来相寻。朝庆老莱服，夕闲安道琴。 \n 文章遥颂美，寤寐增所钦。既郁苍生望，明时岂陆沉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同家兄题渭南王公别业' AND p.poem_author = '蔡希寂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古四十五首 其十五', '释如珙', '宋代', '洞水无缘会逆流，见他苦切故相酬。西来祖意实无意，妄想狂心歇便休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古四十五首 其十五' AND p.poem_author = '释如珙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天', '程滨', '当代', '醉客邀侬入帝乡，从今著意掇行囊。太白一声将进酒，酡颜三万六千场。\n\n魂大觉，梦微茫。起来随意绕低墙。蓦地行人呼野叟，春风独许看花郎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天' AND p.poem_author = '程滨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题胥大夫欣欣堂', '释德洪', '宋代', '议郎粹和色无求，绕屋江山秀气浮。弱柳娇眠禽唤起，异花含笑草忘忧。\n\n闭门不放青春去，解榻长令佳客留。摹写高情无好句，谩横诗眼付冥搜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题胥大夫欣欣堂' AND p.poem_author = '释德洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其四', '苏庠', '宋代', '惭无安世书三箧，滥得扬雄酒一鸱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其四' AND p.poem_author = '苏庠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('安总领生日', '魏了翁', '宋代', '祝化不作语啾啾，陛下凭公释雇忧。\n往误叵堪成铁错，后图犹可保金瓯。\n饮江共喜无胡马，屯渭悬知有木牛。\n虎也肤公康是似，原歌江汉美宗周。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '安总领生日' AND p.poem_author = '魏了翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九章赠别 其一', '湛若水', '明代', '窈窕者谁子，绝代亮无双。不谙小姑性，以直终见伤。\n\n虽则终见伤，中情容何妨。谁为别鹄吟，此曲多慨慷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九章赠别 其一' AND p.poem_author = '湛若水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送河中司马待制', '宋祁', '宋代', '从祀天坛歇翠薰，西门征軷怆离群。\n暂违册府三重阁，先过楼船一曲汾。\n賨炙击鱼开左席，戏壶争马宴中军。\n鸛楼西北怀都思，尽日凭高不碍云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送河中司马待制' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('龙门山二首 其一', '范纯仁', '宋代', '云拥楼台雪拥川，亲朋行望举吟鞭。烟龛万叠凌花霰，坐见金人变玉仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '龙门山二首 其一' AND p.poem_author = '范纯仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送夏璪下第还江阴', '王鏊', '明代', '家声戚里流传久，才气科场挺出殊。自昔昆山誇片玉，一朝沧海得双珠。\n\n市中定价谁高下，暗里朱衣信有无。归去江头养神骏，春风历块看过都。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送夏璪下第还江阴' AND p.poem_author = '王鏊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早超煮药', '方回', '宋代', '五更钟已动，起步望中庭。\n东壁忽闻雨，西窗犹见星。\n□□燃小灶，汲水净空瓶。\n儿子归来好，年来乏使令。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早超煮药' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨过', '苏辙', '宋代', '东南流注已鸣涧，西北霏微仅敛尘。\n人意共怀艰食病，天公那有不仁人。\n云移已分贫无福，雩应方知社有神。\n田里相望无一舍，终年苦乐会须匀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨过' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史上·光武', '陈普', '宋代', '经邦论道职何卑，又是前朝卖饼儿。\n十乱五臣无煖席，三王四代是何时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史上·光武' AND p.poem_author = '陈普';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('简化字 次义山韵', '程滨', '当代', '怕有愚蒙识字难，半为潦草半为残。薪传百代余温尽，鬼哭千年血泪乾。\n\n若个含毫文思涌，几人呵笔砚冰寒。先贤手泽今如在，只作天书符箓看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '简化字 次义山韵' AND p.poem_author = '程滨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过通州浮桥即景杂咏 其三', '弘历', '清代', '郡城塔影落波尖，生齿休和日日添。才命农官出红朽，顿教米贱乐穷阎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过通州浮桥即景杂咏 其三' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再题避暑山庄三十六景诗 其十一 静好堂', '弘历', '清代', '翠屏遮户静无尘，𧤏𧤏阶前长绿筠。琴荐笔床都恰当，想因翰墨缅风人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再题避暑山庄三十六景诗 其十一 静好堂' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和章伯镇', '刘敞', '宋代', '南上湘潭谁记初，北还宣室受釐馀。共怜贾傅才无敌，真作扬雄老著书。\n\n调笑群驺饥欲死，去来千骑乐何如。洞庭木下鲈鱼熟，三叹新诗重起予。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和章伯镇' AND p.poem_author = '刘敞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五妃庙题壁四首 其四', '连横', '近代', '田横岛上有奇人，孤愤延平志未伸。巾帼也知亡国恨，英雄儿女各千春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五妃庙题壁四首 其四' AND p.poem_author = '连横';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋月下怀高进之', '陆深', '明代', '浦溆虚堂欲暮秋，故人青眼夜深留。微风明灭渔舟火，四壁凄清戌角楼。\n\n身世浑疑非幻境，心期千载有神游。庭前忽报中秋月，踏碎花阴未肯休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋月下怀高进之' AND p.poem_author = '陆深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留馀堂诗', '尹台', '明代', '留馀堂在碧川浔，绮构高开紫桂林。一自烟霞辞凤隐，几惊风雨动龙吟。\n\n窦公教擅庭贤盛，荀氏家承世德深。共羡石涓遗嗣矩，犹传宋语作心箴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留馀堂诗' AND p.poem_author = '尹台';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠刘希尹', '薛蕙', '明代', '曰余田野人，胜冠弄文墨。自顾在泥涂，敢言生羽翼。\n\n仪封误眄睐，汝南虚奖饰。朅来长安道，复与君相识。\n\n伊君本卓跞，声华光岱岳。气高稷下辩，文当淹中学。\n\n礼闱同贡荐，宰府联登擢。何意他山石，滥厕荆岑璞。\n\n当代论交地，如君真寡二。周旋幸嘉会，提携辱高义。\n\n仙曹多暇日，帝京饶乐事。朝随紫陌游，夜集华堂醉。\n\n清时信难偶，世故俄纷纠。我方释诏狱，君已遭谗口。\n\n金虎正纵横，玉马空奔走。悯默各伤心，苍皇一分手。\n\n升沉难预计，往复更迁逝。失势兰化刍，乘时堇为帝。\n\n愚士故系俗，达人解其契。宠辱安足惊，脱略人间世。\n\n征涂积冰雪，游子辞京阙。惆怅北风诗，眷恋河梁别。\n\n昔为金石交，今为云雨绝。扰扰离筵散，暧暧行尘灭。\n\n亲交日以稀，心绪重多违。同人既远谪，孤客亦怀归。\n\n云霄惮投足，风尘思振衣。愿言乞骸骨，从君俱奋飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠刘希尹' AND p.poem_author = '薛蕙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬日杂诗十四章 其一', '姚燮', '清代', '启窗坐陈砚，冻墨留宿滋。忍饿惟苦吟，妇颇憎我痴。\n\n瓮粱虽不多，勉可三日持。肯以琐屑谋，役使心腑疲。\n\n仰看云无心，弄晓天生姿。降雨或有凭，顺化泯争机。\n\n未闻贲育强，力能邱山移。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬日杂诗十四章 其一' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送戴仲鹖谪岭南和侯明府', '邵宝', '明代', '清江浦口驰词地，左顺门前待报时。\n远道谪官何日到，小臣忧国有天知。\n镜看白发朝还掩，棹指青山晚更移。\n老我闲居复多病，秋来愁和送君诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送戴仲鹖谪岭南和侯明府' AND p.poem_author = '邵宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢公定和二范秋怀', '林之奇', '宋代', '西风一叶脱，迹已不可扫。\n巷有白马生，朝回焚谏草。\n谁云事君难，是亦父子间。\n所要功补衮，不言能犯颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢公定和二范秋怀' AND p.poem_author = '林之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅', '陆游', '宋代', '若耶溪头春意悭，梅花独秀愁空山。\n逢时决非桃李辈，得道自保冰雪颜。\n僊去要令天下惜，折来聊伴放翁闲。\n人中商略谁堪比，千载夷齐伯仲间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高阳台 其一 汉茂陵', '周之琦', '清代', '宛马吟愁，粤鸡啼恨，流虹休问猗兰。丹鼎龙归，一丘空指苍烟。\n\n蒲轮正好贤良聚，奈褰裳、海上仙山。甚蓬莱，误了阿房，重误甘泉。\n\n神君帐里知何语，但返魂香烬，枉赋哀蝉。五柞鹃声，负他桃熟千年。\n\n谁论朱鸟窗中事，剩初明、泪洒通天。最难禁，玉椀凄凉，宛在人间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高阳台 其一 汉茂陵' AND p.poem_author = '周之琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('垂竿', '张采庵', '近代', '拣得矶头万绿中，閒身只合侣渔童。钓竿一样名心寂，好让蜻蜓立野风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '垂竿' AND p.poem_author = '张采庵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄巽中三首 其一', '释德洪', '宋代', '屋角早梅开遍，墙阴残雪消迟。帘卷一场春梦，窗含满眼新诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄巽中三首 其一' AND p.poem_author = '释德洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽刘监丞二首', '杜范', '宋代', '诸老凋零尽，公胡不少留。\n尘谈裁后进，山立俨前修。\n逸馆休黄发，为邦付黑头。\n瓯闽看蔽芾，有泪正难收。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽刘监丞二首' AND p.poem_author = '杜范';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天台书事十三首', '曹勋', '宋代', '小圃都无花木名，只栽松竹养余清。\n时时风向边头过，喜听松声又竹声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天台书事十三首' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归家山行', '项斯', '唐代', '献赋才何拙，经时不耻归。能知此意是，甘取众人非。 \n 遍陇耕无圃，缘溪钓有矶。此怀难自遣，期在振儒衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归家山行' AND p.poem_author = '项斯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('为证无得赋竹山', '陈郁', '宋代', '好山虽可爱，懒入翠重重。\n静睦千竿玉，清如五老峰。\n径阴禅履润，林密佛香浓。\n灵运知师意，无劳屐踪基。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '为证无得赋竹山' AND p.poem_author = '陈郁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南湖有鸥成群里闾间云数十年未尝见也实尘中奇事因筑亭洲上榜曰鸥渚仍放言六绝 其二', '张镃', '宋代', '旋开斜港放船出，更著小亭临水看。软红尘里江山景，便著丹青画亦难。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南湖有鸥成群里闾间云数十年未尝见也实尘中奇事因筑亭洲上榜曰鸥渚仍放言六绝 其二' AND p.poem_author = '张镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无题三首 其三', '马廷鸾', '宋代', '闻说江边起柁楼，欲将吾道付沧洲。三年恶瞰卢仝屋，一日轻装范蠡舟。\n\n蹈海高怀欣独往，济川好手蹇难留。樯阴舸下能容我，雨笠烟蓑傲白鸥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无题三首 其三' AND p.poem_author = '马廷鸾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九月六日今上登极礼成听诏次韵', '程敏政', '明代', '大蠲逋税彻圜扉，一诏丁宁感缀衣。仗马新从轩陛立，宫鸦时绕殿檐飞。\n\n九重圣孝推恩博，十载皇心探道微。求治便应今日始，鹓行谁守愧甘肥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九月六日今上登极礼成听诏次韵' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵通明叟晚春二十七首 其二', '释德洪', '宋代', '绿遍西园春正残，青梅小摘嗅仍看。单衣初试殊清爽，更爱凉风掠面寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵通明叟晚春二十七首 其二' AND p.poem_author = '释德洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('嘉禾百咏·何城', '张尧同', '宋代', '报越心何壮，贪齐计已轻。\n忠言殊不听，何用筑斯城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '嘉禾百咏·何城' AND p.poem_author = '张尧同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白河篇送李南阳', '李梦阳', '明代', '白河日赤沙吐云，人喧吏閧迎神君。三月万花拥车入，满城竹马儿童出。\n\n君昔坐郡襄汉东，气势三楚生雄风。擿奸无论汉张敞，秉义直到唐梁公。\n\n霜飙偶折奋翅鹗，日月竟照凌云松。铁干久拟作隆栋，剑翮即暑追飞龙。\n\n空同老儒不君识，倾盖逢之喜动色。论文开口夜尝旦，愤事扼腕昼遽黑。\n\n南阳虽迩路终隔，音书易通见难得。我欲扳君数日住，南民望之馁待食。\n\n君心透彻皓如玉，壶之清冰君材磊。落岿如万仞之立壁，高议足以排山岳，伟文足以华人国。\n\n只恐兹邦难久留，汉庭来徵郭细侯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白河篇送李南阳' AND p.poem_author = '李梦阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶成题画', '王绂', '明代', '玉署坐凉思，野人忝簪缨。谬以染翰职，遂得陪群英。\n\n疏雨澹东旭，嘉树荫西清。乐兹馆阁静，悠然抱閒情。\n\n于焉弄豪素，涧谷纷纵横。幽径遵曲岸，鸣泉绕孤亭。\n\n同游固未暇，寓目犹可并。菲才惜何补，生幸承休明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶成题画' AND p.poem_author = '王绂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春归', '刘过', '宋代', '百花开尽到荼縻，一片春心又欲归。\n可恨东风留不得，漫教啼鸟怨斜辉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春归' AND p.poem_author = '刘过';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂二十五首 其十八', '释如净', '宋代', '去那边去，来者里来，中间绝壑断崖。依稀金磴阔，彷佛彩虹弯，人从桥上过。\n\n松萝影里开天巧，汗黑光中入画看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂二十五首 其十八' AND p.poem_author = '释如净';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冉泾书院十二咏 其一 曾侍亭', '邵宝', '明代', '归养荷天恩，孔训闻自少。不敏请事斯，如闻提耳诏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冉泾书院十二咏 其一 曾侍亭' AND p.poem_author = '邵宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵朋元、正夫夜饮', '范成大', '宋代', '歌豪仍作家，弈胜岂徼幸。\n莫嗤老非少，乃尚可以逞。\n玉瓶引杯长，政尔寒漏永。\n二三文章公，共此银烛影。\n陈卿得秀句，刘郎一笑领。\n羸骖兀残梦，乘坠恍难省。\n晓枕讧更潮，俱堕无何境。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵朋元、正夫夜饮' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王县尉挽词', '楼钥', '宋代', '干蛊恢才刃，谁能货殖私。\n人皆竞毫发，我独破藩篱。\n风雨空残梦，池台怆昔时。\n板舆临穴处，行道亦兴悲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王县尉挽词' AND p.poem_author = '楼钥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题清芬阁', '令狐勤', '宋代', '远叩玄英旧隐扉，清风今日尚依依。\n云山自许老龙卧，霄汉不妨双凤飞。\n欲访骚人考槃地，但寻汉叟钓鱼矶。\n年来踏尽红尘路，赖有溪流濯客衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题清芬阁' AND p.poem_author = '令狐勤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江行', '丘浚', '明代', '翠竹白沙村径，落霞飞鹜江天。倚杖夕阳影里，闲看江上归船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江行' AND p.poem_author = '丘浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小轩有菊一本盛开两花大如酒杯饶介之见而爱之连赋诗二首因次其韵 其二', '成廷圭', '元代', '满径香风吹客袍，却胜秋野醉攒蒿。东篱隐者世不泯，南阳老人年最高。\n\n大白杯中多趣味，中黄□内几钧陶。莫令雨后荒三径，更趁霜前斫两螯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小轩有菊一本盛开两花大如酒杯饶介之见而爱之连赋诗二首因次其韵 其二' AND p.poem_author = '成廷圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天 乘公交车组词', '启功', '近代', '铁打车箱肉做身，上班散会最艰辛。有穷弹力无穷挤，一寸空间一寸金。\n\n头屡动，手频伸，可怜无补费精神。当时我是孙行者，变个驴皮影戏人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天 乘公交车组词' AND p.poem_author = '启功';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('閒居杂诗 其二', '许有壬', '元代', '半山云树接修篁，镇日无尘到草堂。瓮牖风来书叶乱，胆瓶花落砚池香。\n\n壶觞自酌教微醉，松菊犹存及未荒。护果灌园常不暇，谁知閒里更多忙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '閒居杂诗 其二' AND p.poem_author = '许有壬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和参寥见寄?一作：奉和参寥离彭门至淮上见', '苏轼', '宋代', '黄楼南畔马台宫，云月娟娟正点空。\n欲共幽人洗笔砚，要传流水入丝桐。\n且随侍者寻西谷，莫学山僧老祝融。\n待我西湖借君去，一杯汤饼泼油葱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和参寥见寄?一作：奉和参寥离彭门至淮上见' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂兴', '黄衷', '明代', '我家南山下，种豆觊逢年。沉冥亦晏坐，长咏南山篇。\n\n郁郁两佳木，广樾阴已便。飞鸟出其下，中有静者天。\n\n驱鸡护蔬甲，促婢饭西田。壶浆聊自劳，濯发蒲涧泉。\n\n手把竹如意，高话羲皇前。千古亦旦夕，传者皆英贤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂兴' AND p.poem_author = '黄衷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和退斋先生顺德较士喜晴', '区越', '明代', '冰壶皎皎湛元精，万类浑浑一镜明。陆氏当年排具眼，昌黎何处表元英。\n\n空濛有日回天意，肤寸无云点太清。久雨忽晴非偶尔，乾坤从此妙施生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和退斋先生顺德较士喜晴' AND p.poem_author = '区越';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽南塘赵尚书二首', '刘克庄', '宋代', '自从水心死，麈柄独归公。\n于易疑程氏，惟诗取晦翁。\n二箴家有本，孤论世无同。\n不复重商榷，骑鲸浩渺中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽南塘赵尚书二首' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月 夜雨', '吴尚憙', '清代', '乱打芭蕉似恨，檐前视若奔涛。阴寒天气已无聊。\n\n何况雨声喧瀑。\n\n玉漏更筹夜转，绣窗帘幕风飘。待将一帚碧云高。\n\n推出红轮报晓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月 夜雨' AND p.poem_author = '吴尚憙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与景晦', '陈藻', '宋代', '乡闾好事喜人传，闻说当初赋断弦。得暇灌花花造化，有方种药药神仙。\n\n忽看脚下相随处，又是人间别样天。数亩南园谁更管，任他荒草欲平肩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与景晦' AND p.poem_author = '陈藻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和张正仲朝散', '曹勋', '宋代', '万里关河雪正霜，自怜跣履苦奔忙。\n宦情久欲休言责，世态何能学坐忘。\n赖有新诗排困踬，未忘浊酒发清狂。\n得公韵语祛烦甚，亟揖筠风续报章。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和张正仲朝散' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('温口泊', '徐荣', '清代', '画里青山伴客眠，刁骚篷背散寒烟。夜来领略诗人味，凉雨孤舟入楚天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '温口泊' AND p.poem_author = '徐荣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('劝学歌', '陈普', '宋代', '太极肇判两仪生，其中人为万物灵。\n人亦天地一物耳，独以道义超众形。\n立为三才中宇宙，发挥天地经人伦。\n兹事初非外烁伐，毫发皆奋七尺身。\n后生可畏如日出，千金之躯岂可轻。\n寸阴可惜莫虚掷，百年安得长青春。\n有力如虎当猛省，何况责望深父兄。\n不通六籍不是学，未了三才未是人。\n希圣必须志尧舜，希贤必有为颜曾。\n义理彝伦精讲究，礼乐制度须详明。\n体用源流务透彻，血脉文理仍流行。\n会通两尽始无碍，范围未始离曲成。\n无尘胸次贮万卷，拔出笔力找千钧。\n不用高枕卧丘壑，用之家齐国治天下平。\n不但匹无匹妇皆获所，草木鱼鳖咸清宁。\n此皆后进本分事，不为干利与求名。\n更须扫除谑浪傲惰熊，打并嗜欲声色情。\n一物一则同一敬，牢守孔孟张朱程。\n吃紧工夫决有效，令闻广誉垂千龄。\n英雄气概为则是，一变至道非难能。\n君不见四十五十无闻不足观，总是惰而不学昏昏贸贸枉生天地间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '劝学歌' AND p.poem_author = '陈普';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀人亭 其一 并序', '郑孝胥', '清代', '孤亭云海渺相思，独上惟吟忆我诗。从此故人感天末，不妨来此立移时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀人亭 其一 并序' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病中六首 其一', '陈师道', '宋代', '旧岁连新岁，凉床又暖床。山川屏里画，时刻篆中香。\n\n畏垒安吾土，支离饱太仓。若教身再健，鹤背入维扬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病中六首 其一' AND p.poem_author = '陈师道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵秦少游王仲至元日立春三首 其二', '苏轼', '宋代', '己卯嘉辰寿阿同，愿渠无过亦无功。明年春日江湖上，回首觚棱一梦中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵秦少游王仲至元日立春三首 其二' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏侯彦济武陟尉', '欧阳修', '宋代', '风烟地接怀，井邑富田垓。\n河近闻冰坼，山高见雨来。\n官闲同小隐，酒美足衔杯。\n好去东篱菊，迎霜正欲开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏侯彦济武陟尉' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪中投宿栖隐寺寺去大冶五千里在乱山中 其一', '袁宏道', '明代', '下马历巑屼，晶晶四壁寒。山门云占断，佛舍雨浇残。\n\n茶好临泉试，松宜带雪看。轩窗无一可，孤负此峰峦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪中投宿栖隐寺寺去大冶五千里在乱山中 其一' AND p.poem_author = '袁宏道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词 其七十二', '宋白', '宋代', '外国人来献宝珠，琉璃双眼赤金须。奇形不欲宫中见，诏遣滕王进画图。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词 其七十二' AND p.poem_author = '宋白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清暑', '张九成', '宋代', '碧纱灯照素屏风，满院凉生秋意浓。\n谁信人间五六月，清寒如在玉壶中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清暑' AND p.poem_author = '张九成';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题画', '林俊', '明代', '鬓发沧浪老病翁，小山时对桂花丛。白沙翠竹逃名外，一棹江烟水月中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题画' AND p.poem_author = '林俊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游丝曲', '孙蕡', '明代', '游丝映户春风荡，雕檐雨挹踟蛛网。春花亦笑绮帐空，故遣飞红入虚幌。\n\n青楼夫婿醉忘归，魂梦相寻意转迷。恍似妾心怀旧爱，还如君意恋新栖。\n\n绮疏鹦鹉通人语，戏把枇杷掷金羽。含情暗卜无心负，今夜渠侬到家否。\n\n游丝罥花风叶叶，吴罗袷薄新寒怯。蜂游亦解钻绮疏，不独房栊出蝴蝶。\n\n怀人不为青春过，别有閒愁幽思多。君情妾意俱肠断，旧爱新怜奈尔何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游丝曲' AND p.poem_author = '孙蕡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寂寞三首 其一', '崔荣江', '当代', '欲理愁丝绪更多，谁赊一计转平和。无人枕入荻花梦，寒柝声中将夜磨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寂寞三首 其一' AND p.poem_author = '崔荣江';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('村居五首 其三', '马定国', '金朝', '五月南风化蟪蛄，野塘晚笋未成蒲。柽花落尽红英细，沙渚鸳鸯半引雏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '村居五首 其三' AND p.poem_author = '马定国';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉田道中得诗二句因足之', '韩淲', '宋代', '秋晚晴原上玉田，水边林下过金仙。寺钟欲动黄昏月，野鸟时横碧落天。\n\n萸糁人家皆取醉，菊花篱槛亦争妍。三叉路入孤村去，九日閒投物外缘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉田道中得诗二句因足之' AND p.poem_author = '韩淲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵卢致远见示', '陈著', '宋代', '新春欲洗旧氛埃，并竹寻溪试一来。\n冻雨忽交疏霰下，严风不放寸云开。\n主人雅量诗相住，老客归心梦亦催。\n滑道何妨徐著步，袖中金薤不虚回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵卢致远见示' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄宋潜溪 其一', '戴良', '元代', '孤鸿失俦侣，连翩洲渚湄。自知羽翮短，不与同奋飞。\n\n寄声奋飞者，当慎子所之。烟波渺无从，云路迥难依。\n\n云路多鹰隼，烟波有虞机。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄宋潜溪 其一' AND p.poem_author = '戴良';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二月十六日将赴台留别樊都事仲郛黄理问元徽', '刘崧', '明代', '本从老圃学携锄，幸际明时出曳裾。滥食祇惭公禄厚，按行常恨吏才疏。\n\n天寒羸马嘶长枥，日晏慈乌下广除。浅薄将何供补报，萧萧华发不胜梳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二月十六日将赴台留别樊都事仲郛黄理问元徽' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠王处士', '许浑', '唐代', '归卧养天真，鹿裘乌角巾。茂陵闲久病，彭泽醉长贫。 \n 冠盖西园夜，笙歌北里春。谁怜清渭曲，又老钓鱼人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠王处士' AND p.poem_author = '许浑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('葛居士诗', '张方平', '宋代', '三峰顶上五经秋，妙法白莲清净脩。无数天花常自散，真空性水不停流。\n\n病痴谁问维摩诘，俗眼徒嗟冉伯牛。别有妙身诸相具，金刚坚固异浮沤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '葛居士诗' AND p.poem_author = '张方平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九日宴杜氏庄', '饶相', '明代', '客里逢佳节，登高集野亭。帽欹须用□，杯倒不教停。\n\n细雨滋黄菊，孤云掩翠屏。此回开口笑，何日又重经。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九日宴杜氏庄' AND p.poem_author = '饶相';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋晚山居', '黄滔', '唐代', '爽气遍搜空，难堪倚望中。孤烟愁落日，高木病西风。 \n 山寂樵声出，露凉蝉思穷。此时尘外事，幽默几人同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋晚山居' AND p.poem_author = '黄滔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送房孙重奴行', '耶律楚材', '元代', '汝亦东丹十世孙，家亡国破一身存。而今正好行仁义，勿学轻薄辱我门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送房孙重奴行' AND p.poem_author = '耶律楚材';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游天平山十六韵', '弘历', '清代', '吴会众山镇，天平万笏朝。飞来峰拔地，林立石干霄。\n\n茶坞西邻近，支硎北户招。势连高景秀，气接太湖潮。\n\n是日春方仲，行时兴倍饶。灵岩盘岭路，功德访云寮。\n\n芳玉溪梅绽，柔金陌柳摇。行行见别墅，缓缓度横桥。\n\n宛到前游处，閒看旧咏标。名园实潇洒，古迹半荒寥。\n\n文正风犹在，梓桑泽未遥。小停憩閒馆，更进步层椒。\n\n翠樾茈虒密，苍岩突兀峤。庵传远公法，泉溯白翁谣。\n\n绝顶高无匹，三吴望里要。未称元气复，用是一心焦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游天平山十六韵' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居', '陈高', '元代', '避喧林下居，抱病山中卧。家贫酒屡空，性懒诗慵课。\n\n禽声隔树啼，云影当窗过。独有采樵人，时来慰衰惰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居' AND p.poem_author = '陈高';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庐山寺', '蒋彝', '近代', '风枝摇曳似相招，雨经清幽意转绕。\n陶令远公今岂是，共君闯过虎溪桥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庐山寺' AND p.poem_author = '蒋彝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('艮岳百咏 清斯亭', '李质', '宋代', '天波万斛泻镕银，跨水横桥丽构新。但取真堪濯缨意，玉阶金阙本无尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '艮岳百咏 清斯亭' AND p.poem_author = '李质';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿苏筑', '释函可', '明代', '不厌人间水半卮，独将枯杖问须眉。鸡窗冷淡存馀雪，鹿野荒沉出别枝。\n\n歌满关河聊当哭，食残铁石好支饥。旧时閒梦应频见，却恨残年叹未衰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿苏筑' AND p.poem_author = '释函可';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行香子 偕卫中亚明兄游云居寺旧址并石经山', '张力夫', '当代', '苔径残墙，古殿凋梁。柏参天、柿子摇黄。人来此地，欲受灵光。\n\n怅佛无头、寺无主、世无常。\n\n陶潜深隐，阮籍疏狂。信当时、费尽思量。但呼知己，畅饮琼浆。\n\n在白云间、青山上、紫霞旁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行香子 偕卫中亚明兄游云居寺旧址并石经山' AND p.poem_author = '张力夫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天仙子 立夏', '陈世祥', '清代', '酒恶更嗔花气袅。起把落花和露扫。黄鹂一个上枝头，来报道。\n\n添烦恼。今日五更春去了。\n\n倦眼舒将烟渺渺。是处溪山今绿绕。却拈短棹问桃源，非故道。\n\n人间杳。繁阴如雨无啼鸟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天仙子 立夏' AND p.poem_author = '陈世祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('永叔自南阳至余郊迓焉', '梅尧臣', '宋代', '郭门临汝水，镜色入高衢。鞍马过其上，尘襟荡已无。\n\n及郊逢故友，出涕各沾襦。神物丧头角，空存尾与躯。\n\n沟木失匠斲，谁施蓝与朱。并辔不能语，斯文其已夫。\n\n归来授予馆，自为炊彫胡。且勿厌兹会，日月易以徂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '永叔自南阳至余郊迓焉' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重华宫曲宴于阗回长漠咱帕尔', '弘历', '清代', '朝天兼值预朝正，曲宴宜教沐宠荣。尔父诚为识时务，王臣讵有限禆瀛。\n\n旧宫小会轻齐史，新域来宾愿武成。入律东风方凑达，春台乐与物咸亨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重华宫曲宴于阗回长漠咱帕尔' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('视田五首赠八弟无斁 其一', '晁补之', '宋代', '河流之所濡，一斛泥数斗。我庄当水穷，乃比石田瘦。\n\n尚无东陵瓜，况有南山豆。天雨不可期，且复鞭牛后。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '视田五首赠八弟无斁 其一' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋兴八首追和杜老 其三', '王之道', '宋代', '云影曚昽日洒晖，金湖西畔晚阴微。渔舟缭绕青山去，枫叶追随白鸟飞。\n\n摩诘家风非世有，渊明心性与时违。近来病瘠连诗瘦，翻爱西台字样肥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋兴八首追和杜老 其三' AND p.poem_author = '王之道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谒灵泽夫人庙 其二', '汪石青', '近代', '一锁深宫望翠华，巫云梦断哭天涯。徒劳上将安刘室，终见阿兄负汉家。\n\n此事已成千古恨，长江犹抱数峰斜。水天岑寂松楸冷，惆怅垂杨宿暮鸦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谒灵泽夫人庙 其二' AND p.poem_author = '汪石青';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同贾岛宿无可上人院', '雍陶', '唐代', '何处销愁宿，携囊就远僧。中宵吟有雪，空屋语无灯。 \n 静境唯闻铎，寒床但枕肱。还因爱闲客，始得见南能。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同贾岛宿无可上人院' AND p.poem_author = '雍陶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别王彦举', '孙蕡', '明代', '东风吹赴龙头选，又别王郎听雨轩。既拥青绫吟北牖，更张红烛醉南园。\n\n秋还芸草书香秘，夜久芙蓉漏滴繁。后夜玉堂追往梦，一簪华发共谁言。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别王彦举' AND p.poem_author = '孙蕡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶成三首 其二', '王鏊', '明代', '漠漠斜晖转树腰，花前柳下步逍遥。忽思右掖门前侣，隐几无言候早朝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶成三首 其二' AND p.poem_author = '王鏊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('复州十咏 其三', '多隆阿', '清代', '随缘寓目尽怡情，缓缓扬鞭计路行。衰柳经秋全绕郭，寒溪如带半围城。\n\n乡人淡泊差无竞，古迹流传尚有名。默想今宵天上月，知他还自照西平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '复州十咏 其三' AND p.poem_author = '多隆阿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('曾渊子第四十四', '文天祥', '宋代', '子负经济才，郁陶抱长策。\n安得万里风，南图回羽翮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '曾渊子第四十四' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赏茶', '戴炳', '宋代', '自汲香泉带落花，漫烧石鼎试新茶。绿阴天气闲庭院，卧听黄蜂报晚衙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赏茶' AND p.poem_author = '戴炳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日投钱塘元帅尚父二首', '罗隐', '唐代', '正忧衰老辱金台，敢望昭王顾问来。门外旌旗屯虎豹， \n 壁闲章句动风雷。三都节已联翩降，两地花应次第开。 \n 若比紫髯分鼎足，未闻馀力有琼瑰。 \n 征东幕府十三州，敢望非才忝上游。官秩已叨吴品职， \n 姓名兼显鲁春秋。盐车顾后声方重，火井窥来焰始浮。 \n 一句黄河千载事，麦城王粲谩登楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日投钱塘元帅尚父二首' AND p.poem_author = '罗隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('展墓次杨景昌韵', '江源', '明代', '薄宦羁人不自由，十年湖海负松楸。幸叨五鼎惭终养，三复蓼莪空泪流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '展墓次杨景昌韵' AND p.poem_author = '江源';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋次蘖庵韵二首 其二', '黄淮', '明代', '读书何幸际昌期，廊庙良材子所宜。职典铨曹才数日，身淹丛棘已多时。\n\n伤心空负题桥志，对景愁吟陟圮诗。试看徂徕松与柏，霜枝雪干晚离离。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋次蘖庵韵二首 其二' AND p.poem_author = '黄淮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和张倅湖上十绝 其八', '姜特立', '宋代', '尽将丘壑捲胸中，醉帽归时御晚风。明日府公催吏牍，可堪骑马踏香红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和张倅湖上十绝 其八' AND p.poem_author = '姜特立';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('牛车', '张湄', '清代', '短靷高箱服两牛，柴车挽运健于舟。五更残月梦初醒，角韵呜呜生客愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '牛车' AND p.poem_author = '张湄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重过何氏北涧', '刘永之', '元代', '北堂宴罢倚微醺，竹几灯花坐夜分。再酌兰樽浮绿醑，重拈綵笔写清文。\n\n山寒岚气朝成雨，地湿松阴暮起云。休讶野人留恋久，十年江海厌离群。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重过何氏北涧' AND p.poem_author = '刘永之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('道上口占', '李寄', '清代', '暂憩征鞍道路中，世閒公道是春风。破垣废井苍苔合，无主桃花分外红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '道上口占' AND p.poem_author = '李寄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('瓦庙', '李廌', '宋代', '柱侧檐攲瓦欲飘，断垣苔涩树萧萧。满庭荒草无香火，惟有禽声伴寂寥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瓦庙' AND p.poem_author = '李廌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('溪居', '郭忠谟', '宋代', '凿破青山骨，初营数亩丘。\n泉分幽窦乳，峡束大江流。\n渔唱来花径，山光落钓舟。\n沙鸥惊笑语，片片起沧洲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '溪居' AND p.poem_author = '郭忠谟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('扈从御宿池', '祖咏', '唐代', '君王既巡狩，辇道入秦京。远树低枪垒，孤峰入幔城。 \n 寒疏清禁漏，夜警羽林兵。谁念迷方客，长怀魏阙情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '扈从御宿池' AND p.poem_author = '祖咏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登舟一夕对酒偶成时从阅云梯关归清江浦丁亥十月 其三', '曾广钧', '清代', '雁下平芜秋气深，要从湖海试雄心。玉龙灰尽难成烛，彩凤归来不听琴。\n\n正月繁霜伤小雅，斜飙细雨冻号禽。阻风中酒兼朝夕，转毂光阴思不禁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登舟一夕对酒偶成时从阅云梯关归清江浦丁亥十月 其三' AND p.poem_author = '曾广钧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上安晚节丞相三首', '释道璨', '宋代', '日食何曾费万钱，只将苜蓿荐春盘。\n俸余不用肥奴马，留买青山取性看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上安晚节丞相三首' AND p.poem_author = '释道璨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五塔寺', '金朝觐', '清代', '五岳真形具，崔巍踞法台。石门时启闭，磴道喑纡回。\n\n风铎层层系，金身面面开。遥知官路外，瞻仰万人来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五塔寺' AND p.poem_author = '金朝觐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉题常君殉节录后 其一', '陈桂森', '清代', '昔岭寒风落照殷，英魂千古炳人间。屯粮绩著三军幕，陷阵躯捐一剑镮。\n\n死尚握拳如卞壸，生能噀血亦常山。不徒循吏称遗爱，父老西川泪共潸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉题常君殉节录后 其一' AND p.poem_author = '陈桂森';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('旅中', '蔡槃', '宋代', '梧叶响荒塘，秋宵不耐长。\n猿啼千嶂外，人在一灯旁。\n雁影溪桥月，钟声野寺霜。\n明朝又何处，烟水正茫茫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '旅中' AND p.poem_author = '蔡槃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别韩参知叔捷十年已偶游罗浮过访赠以诗', '欧必元', '明代', '蜀锦寄江头，翻思已十秋。谁言方岳贵，犹念布衣游。\n\n白社招陶令，青门忆邵侯。东山高卧处，今乃在罗浮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别韩参知叔捷十年已偶游罗浮过访赠以诗' AND p.poem_author = '欧必元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五和二首 其二', '刘克庄', '宋代', '颓然一榻懒巾靴，二月东风尚未和。雀闯屋檐来作宿，蜂衔窗纸去为窝。\n\n牢愁余发五分白，健思君才十倍多。欲访东皋贤鼻祖，几回路与醉乡蹉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五和二首 其二' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九月四日钱少司寇舟抵维扬同年卢都转雅雨放艇真州邀余往会至即同饮官斋更期九日平山堂登高二首 其一', '戴亨', '清代', '旌节来长水，扁舟发夜分。官斋同宴饮，天象动星文。\n\n深涧流甘乳，高松养白云。久邀贤地主，相待共清氛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九月四日钱少司寇舟抵维扬同年卢都转雅雨放艇真州邀余往会至即同饮官斋更期九日平山堂登高二首 其一' AND p.poem_author = '戴亨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八月十七日扁舟渡钱塘江 其一', '沈与求', '宋代', '一言初欲寤明君，去矣终缘丞相嗔。凫雁江湖真我辈，龙蛇山泽定何人。\n\n市中未识冯延寿，门外已呼祁孔宾。尚有忧时心未歇，西风吹泪湿纶巾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八月十七日扁舟渡钱塘江 其一' AND p.poem_author = '沈与求';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('步虚词十首 其五', '吴筠', '唐代', '扶桑诞初景，羽盖凌晨霞。倏歘造西域，嬉游金母家。\n\n碧津湛洪源，灼烁敷荷花。煌煌青琳宫，粲粲列玉华。\n\n真气溢绛府，自然思无邪。俯矜区中士，夭浊良可嗟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '步虚词十首 其五' AND p.poem_author = '吴筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('边思', '释文珦', '宋代', '胡雁南翔已尽回，闺中不见寄书来。\n穷荒二月无青草，长对东风赋七哀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '边思' AND p.poem_author = '释文珦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送李侍御', '贾至', '唐代', '我年四十馀，已叹前路短。羁离洞庭上，安得不引满。 \n 李侯忘情者，与我同疏懒。孤帆泣潇湘，望远心欲断。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送李侍御' AND p.poem_author = '贾至';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('兰陵王 午诒赋此调寄宝生，奉同一首，后阕为薛四发也', '樊增祥', '清代', '海天碧。春雨江南送客。离筵畔，红杏满枝，转盼新烟过寒食。\n\n衡阳雁向北，不带湘人尺帛。春申浦，波嫩草香，犹认骄骢旧行迹。\n\n高斋未寥寂，纵不见韦三，犹见秦七。碧桃花下黄藤席。\n\n还睥睨当世，酌商千古，西窗残烛一剪蜜，替垂泪何益。\n\n今夕是何夕。且近倚吴歌，遥和湘瑟，吹笙露下双鬟湿。\n\n自薄倖归去，懒亲钗泽。明珠为泪，共夜雨，枕畔滴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '兰陵王 午诒赋此调寄宝生，奉同一首，后阕为薛四发也' AND p.poem_author = '樊增祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送黄邦瑞还广', '蔡清', '明代', '抱病日茕茕，君今又远行。斯文谅有味，分手能无情。\n\n柳色才沾白，稍头又转青。百年真转毂，何以慰平生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送黄邦瑞还广' AND p.poem_author = '蔡清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水围六首 其五', '弘历', '清代', '春气乍暄还乍冷，羽禽时去亦时来。空行正复何妨也，南史奚称褚炫才。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水围六首 其五' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诗三首 其三', '徐守信', '宋代', '南庄北宅眼前花，好儿好女莫缦誇。我若一朝身死后，又属张三李四家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诗三首 其三' AND p.poem_author = '徐守信';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('从征诗', '傅亮', '南北朝', '息徒西楚，伫楫旧乡。止犹岳立，动则云翔。烈烈群师，星言启行。\n\n泛舟掩河，秣马登芒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '从征诗' AND p.poem_author = '傅亮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和紫阳先生韵八首 其一', '杨爵', '明代', '省愆终未敢尤人，报国焉知己道真。肯向遭时存外慕，但须临难致吾身。\n\n拙猷未可轻寒士，迂恤曾何间小臣。莫谓幽圜同永夜，天王明鉴说如神。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和紫阳先生韵八首 其一' AND p.poem_author = '杨爵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('威烈王', '徐钧', '宋代', '大柄潛移势可忧，朝网未正况诸侯。\n时人只咎轻分晋，不道东西已剖周。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '威烈王' AND p.poem_author = '徐钧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('减兰　见月作二首 其二', '卢青山', '当代', '山中老衲，石尽趋门知听法。一发犹存，为惜丝毫父母身。\n\n凄凉不必，死有青蝇为吊客。何况身强，十斗能餐酒万觞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '减兰　见月作二首 其二' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹰', '齐璜', '近代', '振羽何曾猎一围，无穷搏击只私肥。如今四面全开网，浅草平原一线飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹰' AND p.poem_author = '齐璜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行者智江归庐山乞颂', '释心月', '宋代', '庭前荒草正萋萋，却忆丹霞划去时。\n莲社峰高相见了，回来却把圣僧骑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行者智江归庐山乞颂' AND p.poem_author = '释心月';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二郎神 饮李氏康乐园展重阳作，用汤恢韵', '杨玉衔', '清代', '翠微径仄，怯鬓白、被风飘影。念橘柚新阴，枌榆旧社，门掩裙裾客冷。\n\n比似侯爪将军树，勿误认、文园秋病。喜百果缀星，千花扶路，如临天镜。\n\n重省。衔杯笑语，云浓液凝。识棨戟门庭，邯郸客枕，先被流莺唤醒。\n\n松菊三休，茱萸再醉，犹是龙山风景。人解道，檀锁雕笼鹇放，一帘尘静。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二郎神 饮李氏康乐园展重阳作，用汤恢韵' AND p.poem_author = '杨玉衔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠高峰', '袁宏道', '明代', '捉得松为柄，粘来纸作衾。山云娇老态，溪水有无心。\n\n挂锡沉香树，安禅天竹林。西来闲会取，空迹寄飞禽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠高峰' AND p.poem_author = '袁宏道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杉木长涧四首 其四', '朱熹', '宋代', '阡陌纵横不可寻，死伤狼籍正悲吟。若知赤子元无罪，合有人间父母心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杉木长涧四首 其四' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀天竺磵梅', '葛天民', '宋代', '根在岩边结，枝从水际横。\n此花殊近道，凡木欠修行。\n密雪笼幽片，疏篁倚瘦茎。\n那时香不浅，忆我话无生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀天竺磵梅' AND p.poem_author = '葛天民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和交代韩公绛端明别后见寄', '赵抃', '宋代', '关山晴晓过绵州，两蜀人思惠爱稠。去路旌麾朝日下，驾空桥栈接云头。\n\n初观妙句离怀释，似酌清泉渴恙瘳。孤绪摇摇更东望，西楼千尺止三休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和交代韩公绛端明别后见寄' AND p.poem_author = '赵抃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('深居杂兴六首', '林逋', '宋代', '松竹封侯尚未尊，石为公辅亦云云。\n清华自合论闲客，玄默何妨事静君。\n鹤料免惭尸厚禄，茶功兼擬策元勋。\n幽人不作山中相，且拥图书卧白云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '深居杂兴六首' AND p.poem_author = '林逋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书斋漫咏', '安鉴培', '清代', '茅檐鸡犬静无哗，吟罢长篇兴倍赊。雨过萧萧凉似水，凭栏闲看海棠花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书斋漫咏' AND p.poem_author = '安鉴培';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自郧阳回舟再过重滩', '陈浩', '清代', '送客桃花水，迎人乱石滩。船从千丈落，春到九分残。\n\n风幔且高卷，云山须再看。去时新绿柳，飞絮已成团。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自郧阳回舟再过重滩' AND p.poem_author = '陈浩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青石阻雨', '李新', '宋代', '茅屋阴多麦化蛾，西山云重雨流禾。\n未闻因也改其乐，解道虞兮奈若何。\n身与前村孤堠远，泪随流水一溪多。\n文章生世元无力，半岁边城伴枕戈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青石阻雨' AND p.poem_author = '李新';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('罗浮山过访值予远游留诗而去既归复来出荷锄图索题用韵赋赠 其一', '成鹫', '明代', '昨日别东林，客来烟雨深。主人不可见，谁见主人心。\n\n独鹤云中语，枯桐弦外音。遥情当良觌，秋水碧千寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '罗浮山过访值予远游留诗而去既归复来出荷锄图索题用韵赋赠 其一' AND p.poem_author = '成鹫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日登鸡鸣寺五道选一', '林散之', '近代', '结绮犹歌宴，隋师已入关。可怜陈叔宝，谁谓有心肝。\n\n湖水波仍碧，枫林叶正丹。迟回秋不尽，微雨过钟山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日登鸡鸣寺五道选一' AND p.poem_author = '林散之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送焦君实之采石学官', '陆文圭', '宋代', '江水日以远，山花日又新。\n先吾不复少，后我皆成人。\n之子如良金，出矿以精纯。\n又如出中木，始遇雪发春。\n送子启长途，跋子升华津。\n青云题柱客，白发倚闾亲。\n有志皆腾逸，非才独隐沦。\n山林双鬓古，井臼一生贫。\n宇宙无穷事，行藏各自身。\n因风傅短句，望月吊词臣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送焦君实之采石学官' AND p.poem_author = '陆文圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高宗郊前朝献景灵宫二十一首 其八 奉馔用《吉安》。', '郊庙朝会歌辞', '宋代', '百职骏奔，来相于庭。奉盛以告，登兹芳馨。际天蟠地，默运三灵。\n\n神兮来歆，祚我休平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高宗郊前朝献景灵宫二十一首 其八 奉馔用《吉安》。' AND p.poem_author = '郊庙朝会歌辞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荔子', '刘子翚', '宋代', '挺秀穷荒叹未遭，昔贤吟赏著风骚。\n纵班卢橘材非偶，不近长安价愈高。\n烟雨万株遥若画，尘埃一骑笑徒劳。\n琱盘此日无遗远，品格妍媸敢自逃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荔子' AND p.poem_author = '刘子翚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('弈棋绝句二首 其一', '洪炎', '宋代', '新秋遣闷只围棋，病不衔杯亦废诗。对局萧然两无语，个中君子有争时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '弈棋绝句二首 其一' AND p.poem_author = '洪炎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔家傲', '欧阳玄', '元代', '三月都城游赏竞。宫墙官柳青相映。十一门头车马迸。\n\n清明近。豪家寒具金盘饤。\n\n墦祭流连芳草径。归来风送梨花信。向晚轻寒添酒病。\n\n春烟暝。深深院落秋千迥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔家傲' AND p.poem_author = '欧阳玄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金缕曲 感旧，赠余氏兄弟二首，附致云卿丈书后 其一', '易顺鼎', '清代', '记向郧阳道。有伤心、荒原一带，高楼斜照。差幸当年无意绪，马上征人太小。\n\n省多少闲凭闲吊。数遍古来飘泊者，到天涯、毕竟输侬早。\n\n算已是，倦游了。\n\n君家阁上滩声闹。共商量竹弓射鸭，花绷捕蚤。水远山重知几叠，着个儿时游钓。\n\n回首觉乱离都好。莫话十年兄弟感，怕江湖、一半垂垂老。\n\n写不出，旧时稿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金缕曲 感旧，赠余氏兄弟二首，附致云卿丈书后 其一' AND p.poem_author = '易顺鼎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上泸州杨尚书四十韵', '程公许', '宋代', '清莹玻璃水，巉岩石笋峰。孕才供世用，有道致时雍。\n\n阀阅宋清节，源流唐靖恭。异时先太史，司匦事光宗。\n\n忠愤排黄闼，忧危溢皂封。扶颠重立极，涉笔但司农。\n\n馀地勤菑穫，连城荐璧琮。羽毛参薛凤，头角半荀龙。\n\n赫奕誇分鼎，铿鍧响大镛。云霄才直上，时运快遭逢。\n\n袖馥麋丸赐，芸翻蠹简重。亨衢无龃龉，按辔独从容。\n\n监寺虽平进，班行叹乏供。赐茶经幄暝，濡笔殿坳彤。\n\n晓陛荷囊拥，春墀革履跫。时来如邂逅，虑远妙弥缝。\n\n霖雨睿思渴，云山归兴浓。入辞亲黼座，宣劝滟金钟。\n\n可使安耕稼，无劳访枸筇。锦衣华故里，茸纛拂遐冲。\n\n龙驾攀无及，乌号涕莫从。嗣皇初访落，达孝极思庸。\n\n故老尤纡眷，庭臣孰比踪。威名震滇僰，治体嗣黄龚。\n\n白羽閒春燕，黄埃敛夕烽。官刑惩纵暴，民气化醇醲。\n\n北定风檐敞，西来雪浪舂。凭栏聊放目，忧国若为悰。\n\n褒诏烦因任，真祠未许慵。定知频侧席，胡不趣追锋。\n\n念昔联瓜葛，游谈及菲葑。驽骀劳剪拂，矿质费陶镕。\n\n冰谷窘寒冻，石田加蕴爞。摄斋时缓缓，衔感志忪忪。\n\n世论方胶柱，人情谨护痈。迟公归燮理，为国扫蒙茸。\n\n溯日孤忠炯，飞霜两鬓松。欲酬青玉案，何有色丝胸。\n\n自笑疏顽甚，犹须砭剂攻。兔丝虽小草，千丈托长松。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上泸州杨尚书四十韵' AND p.poem_author = '程公许';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诰赠中宪大夫常公殉节诗 其二', '马维驭', '清代', '国士慨然报国忠，风高昔岭泣英雄。绩传理饷邀荣擢，勇奋捐生契圣衷。\n\n日落花溪祠宇黯，云移木果塞烟空。西充漫说千秋祀，午夜清魂到海东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诰赠中宪大夫常公殉节诗 其二' AND p.poem_author = '马维驭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百六十九首 其二十三', '释智朋', '宋代', '提折脚铛，各出只手。释迦不先，弥勒不后。妙用临机，如盘珠走。\n\n鼓腹笑复歌，面南看北斗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百六十九首 其二十三' AND p.poem_author = '释智朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和刘卿材十咏 其九 龙潭', '黄庶', '宋代', '寂寞真龙去，雩坛血不乾。世情多冷暖，对此鼻辛酸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和刘卿材十咏 其九 龙潭' AND p.poem_author = '黄庶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽胡茂老枢密 其三', '李正民', '宋代', '昔日蓬山会，平居笑语亲。薄材陪贾马，高义继雷陈。\n\n南国居方卜，东山道益振。遽嗟埋玉恨，清泪洒衣巾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽胡茂老枢密 其三' AND p.poem_author = '李正民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游武夷二绝', '李洪', '宋代', '野水溶溶易满堤，十分强半麦成畦。\n我来宴坐久无语，日蟆昃深莺乱啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游武夷二绝' AND p.poem_author = '李洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('静宜园二十八景诗 其十 栖云楼', '弘历', '清代', '过去心难得，未来亦复然。以此例现在，毕竟谁火传。\n\n高楼号栖云，题句忆昔年。阶畔碎琼声，报我无留迁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '静宜园二十八景诗 其十 栖云楼' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和阳念三自武昌至京师', '张耒', '宋代', '三年别我客荆州，一日长安从我游。\n爱君诗有春草句，使我神游黄鹤楼。\n江山望尔欲穿眼，见我惊嗟秋鬓短。\n扁舟可办吾欲东，年年五湖魂梦中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和阳念三自武昌至京师' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过南荡三首 其一', '杨万里', '宋代', '秧才束发幼相依，麦已掀髯喜可知。笑杀槿篱能耐事，东扶西倒野酴醾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过南荡三首 其一' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏儒释道三教总赠程洁庵：释教十三首 其十一 朝阳补破衲', '李道纯', '元代', '朝阳补衲假妆么，补了肩头又补腰。补了破时重又补，到头争似赤条条。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏儒释道三教总赠程洁庵：释教十三首 其十一 朝阳补破衲' AND p.poem_author = '李道纯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('点绛唇（瑞香）', '王十朋', '宋代', '阑槛阴沉，紫云呈端馀寒凛。卷帘欹枕。香逼幽人寝。 \n 入梦何年，庐阜闻名稔。风流甚。阿谁题品。唤作熏龙锦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '点绛唇（瑞香）' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫辞三绝送黄虞部北上 其三', '林大春', '明代', '夜度箫笙入紫霄，晨飘仙佩杂琼瑶。如今老却纤纤手，肯向人间学舞腰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫辞三绝送黄虞部北上 其三' AND p.poem_author = '林大春';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄泥坂词', '苏轼', '宋代', '出临皋而东骛兮，并丛祠而北转。\n走雪堂之陂陀兮，历黄泥之长坂。\n大江汹以左缭兮，渺云涛之舒卷。\n草木层累而右附兮，蔚柯丘之囱蒨。\n余旦往而夕还兮，步徙倚而盘桓。\n虽信美而不可居兮，苟娱余于一眄。\n余幼好此奇服兮，袭前人之诡幻。\n老更变而自哂兮，悟惊俗之来患。\n释宝璐而被缯絮兮，杂市人而无辨。\n路悠悠其莫往来兮，守一席而穷年。\n时游步而远览兮，路穷尽而旋反。\n朝嬉黄泥之白云兮，暮宿雪堂之青烟。\n喜鱼鸟之莫余惊兮，幸樵苏之我嫚。\n初被酒以行歌兮，忽放杖而醉偃。\n草为茵而块为枕兮，穆华堂之清宴。\n纷坠露之湿衣兮，升素月之团团。\n感父老之呼觉兮，恐牛羊之予践。\n于是蹶然而起，起而歌曰月明兮星稀，\n迎余往兮饯余归。岁既宴兮草木腓，\n归来归来兮，黄泥不可以久嬉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄泥坂词' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('半闲堂', '梁季子', '近代', '半闲堂，浪子宰相贾平章。湖山风月原无主，付与平章仔细量。\n\n朝登多宝阁，夜宴西湖中。指挥铁如意，经纶蟋蟀笼。\n\n衣香毾㲪暖，席地氍毹红。江南无复一寸乾净赵家土，平章堂上生春风。\n\n鄂州城破江淮阻，天子诏开都督府。荔子黄柑献伯颜，单舸遁走扬州坞。\n\n肩舆烈日出循潭，南州之歌尔何堪。箫鼓华堂兴未酣，伤心又见木棉庵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '半闲堂' AND p.poem_author = '梁季子';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行年七十二', '陈谟', '元代', '行年七十二，白发向人羞。肯羡梁江总，空怀齐楚丘。\n\n绣衣题姓字，皂盖验春秋。一自周原猎，难为渭水叟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行年七十二' AND p.poem_author = '陈谟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('扫蜜', '方岳', '宋代', '须蜜之人去其国，尽以族行无敢逸。缀如垂瘤大如囊，低压山墙于我室。\n\n秦人逐客真少恩，客来须看春正酣。咄嗟已办四山壁，正对桃李开茅庵。\n\n苍头奴解与之语，拥彗招邀聿来宇。相攸新邑经始忙，先作高台奉盟主。\n\n沈沈夥涉之为王，独无摇毒之虿芒。熙熙登台坐垂拱，花底退衙春昼长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '扫蜜' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('画马题 其二', '张穆', '明代', '濡毫流电绝商量，幻出毛龙白玉光。共爱青丝挽垂柳，莫教容易献昭王。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '画马题 其二' AND p.poem_author = '张穆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九叹九首 其三', '刘基', '元代', '天有田兮不可以耕。山有龟兮不可以知咎徵。剡蒿以为梁兮削菌以居楹。匠石却走兮工垂拊膺。\n\n登高望远兮观四瀛。水东流兮日西倾。般纷纷兮各有营。我独展转兮从夜达明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九叹九首 其三' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('交傍晚凝子华见寄', '陈著', '宋代', '老矣息林邱，平生不径由。\n知心时一见，安分别无求。\n寒卧死中活，荣华乐处忧。\n世閒何限事，曾看过云不。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '交傍晚凝子华见寄' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三河县', '弘历', '清代', '近山风转严，当秋树如绮。策渡过三河，马足怯寒水。\n\n秉穗堆圃场，老幼趁墟市。稍免冻与饥，忧馀亦生喜。\n\n寻思赤县广，安得皆似此。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三河县' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花 其二十二', '赵尊岳', '近代', '乍暖还寒春意早。载榼寻芳，香径啼莺小。万一流光轻负了。\n\n少年能否年年少。\n\n不解酬春应自笑。飞絮飞花，犹有晴丝绕。未必蓬山无梦到。\n\n逢花且拌新刍倒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花 其二十二' AND p.poem_author = '赵尊岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别后寄赵宾旸并杨华父二首', '方回', '宋代', '虚翁眼暗鲁翁聋，聚散匆匆老病踪。\n近已有人传我死，何期此地与君逢。\n两穷未必时流识，一笑犹为造物容。\n自觉平生豪故在，能挥万字饮千钟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别后寄赵宾旸并杨华父二首' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('垂丝海棠', '瞿佑', '明代', '袅袅春风拂苑墙，天机呈巧织仙裳。玉栏斜搭酣春睡，银烛高烧照晚妆。\n\n华屋雨寒愁绪乱，绮窗日暖唾茸香。诗成倘有纤毫补，愿醉佳人锦瑟傍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '垂丝海棠' AND p.poem_author = '瞿佑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送闵寿卿隐武夷', '徐熥', '明代', '世人游武夷，往往思卜宅。一出清溪谢白云，山灵无计留双屐。\n\n始信人间事可哀，幔亭佳宴不重开。浮生只爱红尘老，人世难逃白发催。\n\n怜君弃家经几载，服食还丹颜未改。已识仙都注有名，尚疑遗蜕函犹在。\n\n自入闽天誓不还，因缘合在武夷山。独携一杖千峰里，閒放孤舟九曲间。\n\n此山元是神仙窟，接笋天游双崒嵂。玉女妆残峰顶霞，金鸡叫落滩头月。\n\n君今筑室此中居，永绝尘缘与世疏。回视形骸同粪土，能将神气返空虚。\n\n我也行年三十几，半生踪迹多城市。入药空烧九转红，著书枉识关门紫。\n\n海外徒闻更九州，此身期伴赤松游。何时重预曾孙宴，同醉仙人十二楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送闵寿卿隐武夷' AND p.poem_author = '徐熥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读黄泰泉陈白沙两集 其四', '李洸', '近代', '困眠饥食滞芳时，往事凄迷恋酒卮。倘许焚香趋静境，无思无虑对枯棋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读黄泰泉陈白沙两集 其四' AND p.poem_author = '李洸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题邵益斋白云诗卷二绝 其二', '唐桂芳', '元代', '黄山我号白云翁，云涨千山与画同。试问云山何所似，故人未老一丝风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题邵益斋白云诗卷二绝 其二' AND p.poem_author = '唐桂芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('种松二首 其一', '张嵲', '宋代', '寿张种漆将为器，假用终能及里闾。我植青松期偃盖，苍然相对雪霜馀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '种松二首 其一' AND p.poem_author = '张嵲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游宝林招李簿梅尉', '杨杰', '宋代', '东郭乞求闻晓鸡，篮舆乘兴过泾溪。冰开波面白玉碎，雪压竹梢青凤低。\n\n仙去空留鍊丹井，境清疑有辟尘犀。子真太白曾孙在，飞棹何妨到水西。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游宝林招李簿梅尉' AND p.poem_author = '杨杰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题小景', '刘基', '明代', '江头日日起西风，江树惊寒叶变红。\n天澹云低何处雁，一行飞下荻花中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题小景' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('用前韵酬陈判官', '曹勋', '宋代', '刺桐花发照人明，三看薰风舞绛英。\n海近鱼肥随米贱，山高溪净照人清。\n久闻射策先黄甲，何意栖鸾尚赤城。\n顾我婆娑老林下，看君事业映簪缨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '用前韵酬陈判官' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红 清江风帆甚快，作此，与客剧饮歌之', '范成大', '宋代', '千古东流，声卷地、云涛如屋。横浩渺、樯竿十丈，不胜帆腹。\n\n夜雨翻江春浦涨，船头鼓急风初熟。似当年、呼禹乱黄川，飞梭速。\n\n击楫誓，空惊俗。休拊髀，都生肉。任炎天冰海，一杯相属。\n\n荻笋蒌芽新入馔，鹍弦凤吹能翻曲。笑人间、何处似尊前，添银烛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红 清江风帆甚快，作此，与客剧饮歌之' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('己亥中元陪祀山陵道中奉和杨学士先生韵（四', '李东阳', '明代', '十年三赴四陵朝，又逐诸公一举镳。\n龙尾道瞻回辇近，马蹄尘送入山遥。\n天开野色川原净，日出城头雾雨消。\n无数晚花秋树里，未须风物向春饶。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '己亥中元陪祀山陵道中奉和杨学士先生韵（四' AND p.poem_author = '李东阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病减枕上五首 其五', '陈渊', '宋代', '三釜承亲计已疏，万钟行道竟何如。安贫未赴阇黎饭，信命宁裁宰相书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病减枕上五首 其五' AND p.poem_author = '陈渊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('将往琼南口占别司香者 其五', '屈大均', '明代', '多栽香子傍芙蓉，家有香田即素封。欲向东官金桔岭，尽将妻子作香农。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将往琼南口占别司香者 其五' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三月廿六日夜同侄端臣端杲观异书效李长吉体', '范浚', '宋代', '杨花乱落青春暮，燕拂帘旌傍人语。缥壶买酒洗春愁，回风落日檐花舞。\n\n赫蹄断烂千载书，青灯照字惊蟫鱼。冬烘老生时自哂，安用盘盂学田鼢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三月廿六日夜同侄端臣端杲观异书效李长吉体' AND p.poem_author = '范浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李简夫知易用其父韵见贻且示和陶一编并和二章答之 其二', '孙应时', '宋代', '閒中笔墨故相宜，遣兴由来不厌诗。日仰慈颜长自爱，年方强仕莫言衰。\n\n新来定得安心法，此事还胜未病时。肯共切磋须我辈，独无琼玖报先施。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李简夫知易用其父韵见贻且示和陶一编并和二章答之 其二' AND p.poem_author = '孙应时';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏中庭幽兰寄曾日彰练声伯', '王汝玉', '明代', '中庭有幽兰，贞独信为美。移根自泽阴，托荫近堂趾。\n\n敷叶恒披绿，抽茎复攒紫。桃李讵能方，荇茝或可比。\n\n纫之佩服间，足以赠君子。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏中庭幽兰寄曾日彰练声伯' AND p.poem_author = '王汝玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('遐方怨 其四', '周岸登', '清代', '麟髓簏，獭脂筒。剪发涂眉，脱簪非关秋扇风。却怜金井坠芳桐。\n\n绕阑悲露草，两心红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '遐方怨 其四' AND p.poem_author = '周岸登';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('管解元欲见巽伯', '韩淲', '宋代', '春秋经世志，问取大愚家。盘折入举文，唾手为国华。\n\n从容试讲评，三传宁浮誇。南渡今百年，中外义非赊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '管解元欲见巽伯' AND p.poem_author = '韩淲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋夜月速儿曹赴任洪西', '区越', '明代', '直辗冰轮上碧天，了无云物翳光圆。南楼兴动不知老，白酒香腾正满筵。\n\n丹桂拂天真影见，霓裳炙口竟谁传。痴儿未了公家事，明日沧江送画船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋夜月速儿曹赴任洪西' AND p.poem_author = '区越';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄酬曹伯玉因以招之', '王安石', '宋代', '寒鸦对立西风树，幽草环生白露庭。\n清坐苦无公事扰，高谈时有故人经。\n思君异日投朱绂，过我何时载渌醽。\n及此江湖气萧爽，最宜相值倒吾瓶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄酬曹伯玉因以招之' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('门有车马客行', '史鉴', '明代', '翩翩南回雁，哀鸣向秦飞。\n道路非不远，乘时安可违。\n门有车马客，驾言归故庐。\n关中天下险，山河尽城池。\n云胡失保障，匈奴忽来兹。\n传闻入北地，民物多伤夷。\n岂无霍去病，能不以家为。\n胡来闭城守，胡去扬兵追。\n如何秦陇间，到处成疮痍。\n凭君谢诸将，全躯岂男儿。\n努力事扫除，勿令蔓且滋。\n请看麒麟阁，功臣亦人为。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '门有车马客行' AND p.poem_author = '史鉴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('道无情 秋阳观作，答宣德州道友请', '尹志平', '元代', '深谢将书来请。才到西岩春令。百鸟正喧呼。乐无余。道众满川和气。醮罢更看天意。缘契合虚谷。任西东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '道无情 秋阳观作，答宣德州道友请' AND p.poem_author = '尹志平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大雪同杨景韩程子敬登寺楼', '程公许', '宋代', '雪中佳士集，同倚寺楼看。\n晁荡迷沧海。空明迫广寒。\n重城和气浃，万井语声欢。\n瑞接三冬白，忧宽一寸丹。\n渔船寻剡曲，战马渡桑乾。\n天意俱悭与，无氈分冷官。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大雪同杨景韩程子敬登寺楼' AND p.poem_author = '程公许';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和张秘丞灯夕韵四首 其二', '刘克庄', '宋代', '牧守二期方奉计，末期君已得民和。不愁米送官仓少，但怪莲开陆地多。\n\n座客共沾眉寿酒，厩人预戒早朝珂。诸公若问龙钟叟，为说腰镰自刈禾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和张秘丞灯夕韵四首 其二' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饮酒二十首同苏翰林先生次韵追和陶渊明 其三', '晁补之', '宋代', '陶公群于人，而无人之情。诗岂世外语，世语不可名。\n\n东坡怜此翁，同调但隔生。形光来户屦，真处人不惊。\n\n得酒自醒醉，放意无亏成。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饮酒二十首同苏翰林先生次韵追和陶渊明 其三' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题壁', '崇圣寺鬼', '唐代', '禁烟佳节同游此，正值酴醿夹岸香。 \n 缅首十年前往事，强吟风景乱愁肠。 \n 策马暂寻原上路，落花芳草尚依然。 \n 家亡国破一场梦，惆怅又逢寒食天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题壁' AND p.poem_author = '崇圣寺鬼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题刘伯山蕃殖图二首画禾黍稌菽麦 其一', '杨万里', '宋代', '老子平生只荷锄，误携破砚到清都。归来荒尽西畴却，愧见刘家蕃殖图。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题刘伯山蕃殖图二首画禾黍稌菽麦 其一' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留题绩溪', '程敏政', '明代', '绩溪东南来，遥望古仁里。中有程氏居，隐隐入桑梓。\n\n缅怀道轩翁，吾宗百世士。眼中聚爱楼，遗训耿在耳。\n\n三男如鼎足，等是克家子。崇坊瞰村巷，华构照山址。\n\n春霖久初晴，一榻为予启。登堂父兄乐，拥户儿童喜。\n\n开奁扣宗牒，张燕出肴醴。夜下灯火明，语笑未能已。\n\n忆当百年前，同饮相湖水。今夕乃何夕，会晤复自此。\n\n聚散安可常，保族在崇礼。丁宁愿同人，契谊笃终始。\n\n明发川途长，思情两难拟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留题绩溪' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('捉搦歌四首 其三', '欧必元', '明代', '铜青衫子衬杏黄，阿姑二八同烧香。供俸世尊礼佛王，愿得勿嫁如兄郎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '捉搦歌四首 其三' AND p.poem_author = '欧必元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渡开都河', '易寿松', '清代', '高城绿柳接清波，破晓停车唤渡河。牧野帐分平野阔，沙痕岸剩隔年多。\n\n此生东去乘槎近，稳坐中流击楫歌。西域兵看银汉洗，海门戍鼓又鸣鼍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渡开都河' AND p.poem_author = '易寿松';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阅丁知县传', '陈献章', '明代', '模样从看拙，丹青只写真。乾坤如许大，具眼岂无人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阅丁知县传' AND p.poem_author = '陈献章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汤时仲小林居', '南洲法师', '明代', '昔年曾过小林居，门下萧萧古木疏。\n床雨独看先世笏，帐烟还读外家书。\n杏花红褪春犹在，菜甲青稀晓自锄。\n回首长洲多茂草，几时清啸落樵渔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汤时仲小林居' AND p.poem_author = '南洲法师';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('义舟', '徐庸', '明代', '巨舟平压水中天，一挂风帆稳济川。沧海自深入自渡，不教来往费青钱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '义舟' AND p.poem_author = '徐庸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('翟簿示似中秋高作命意着语殆与商素争清读至', '史弥宁', '宋代', '歌子秋风叠，诵子明月篇。\n信有习鉴齿，胜读书十年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '翟簿示似中秋高作命意着语殆与商素争清读至' AND p.poem_author = '史弥宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('明发西馆晨炊蔼冈四首', '杨万里', '宋代', '何须名苑看春风，一路山花不负侬。\n日日锦江呈锦檨，清溪倒照映山红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '明发西馆晨炊蔼冈四首' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('淮阳公署遣怀二首 其一', '王世贞', '明代', '空馆云常合，荒阶叶易平。风霜私俗吏，天地狭狂生。\n\n啸引双长铗，愁依一短檠。惜眠晨鼓罢，散食午禽鸣。\n\n刀笔难违世，文章肯近名。翛然竟何语，奇思独能惊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '淮阳公署遣怀二首 其一' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('客中四时词 其三', '黄仲昭', '明代', '荷落一池风，菊开三径雨。无穷离别怀，况听寒虫语。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '客中四时词 其三' AND p.poem_author = '黄仲昭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('写昆崙万松图寿一昆老人八十', '张萱', '明代', '我闻昆崙在西极，天地之脐神仙国。三城五级十二门，鹤驭鸾骖千万亿。\n\n握契仙人好远游，一朝掉臂黄林陬。开明奔命陆吾遁，却插孤根闽海头。\n\n冯夷昼立天吴语，巨鳌欲戴昆崙去。老人玉杖试一挥，昆崙永作闽天柱。\n\n万岁山前紫气浓，老人高卧昆崙峰。偓佺拊背授真诀，独种云间十八公。\n\n万斛明珠千岁实，忆昔馈尧尧不食。春风日长虬龙枝，擎霄接汉皆千尺。\n\n兄为栋兮弟为梁，丹青矩矱充明堂。葱峦锦柏亦琐屑，寒河星柘徒夸张。\n\n明堂孔阳圣人喜，为问老人身姓李。三锡龙章爵大中，地上神仙郁华子。\n\n杖履烟霞八十春，少微夜夜烛昆崙。不往人间役徐甲，不从柱下作周臣。\n\n一日餐一松，一松巢一岁。天地为等期，青青长不改。\n\n弧悬正值小春阳，木公金女纷翱翔。金銮乍祝齐天寿，锦里还飞爱已觞。\n\n罗浮山下金门隐，遥向南天称子姓。欲随青鸟献珍图，且吮綵毫开异境。\n\n何日堂前问大还，侧身怅望昆崙山。万头青犊留闽海，李耳原来未出关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '写昆崙万松图寿一昆老人八十' AND p.poem_author = '张萱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丑奴儿令 其一 两大人之黔中，鼎以试事留湘，赋感', '易顺鼎', '清代', '膝前长跪魂如醉，感上心头。悲上心头。泪到湘天日夜流。\n\n照人一样关山月，亲在黔州。儿在潭州。祝汝团圞万古秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丑奴儿令 其一 两大人之黔中，鼎以试事留湘，赋感' AND p.poem_author = '易顺鼎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('松芝图', '了亮', '清代', '悬厓一株松，经霜复经雪。倚涧五茎芝，日月精华结。\n\n生成栋梁材，品格自高洁。异草本灵丹，服之增颜色。\n\n援笔入丹青，足称两奇绝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '松芝图' AND p.poem_author = '了亮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陶祠', '韩锡胙', '清代', '层叠山难画，渊明却赋归。兴因新秫酒，家有旧柴扉。\n\n祠瓦藤穿漏，碑书斧砺稀。滔滔江水阔，谁觉折腰非。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陶祠' AND p.poem_author = '韩锡胙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苏度支挽诗 其一', '刘攽', '宋代', '翰墨兼能事，功名自壮图。云霄曾几许，意气即通衢。\n\n埋玉情何已，修文理不诬。敢忘徐稚礼，絮酒望江湖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苏度支挽诗 其一' AND p.poem_author = '刘攽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晓经潘葑', '杨万里', '宋代', '油窗著雨光不湿，东风忽转西风急。\n蓬声萧萧河水涩，牵船不行人却立。\n雨中蒿师风堕笠，潘葑未到眼先入。\n岸柳垂头向人揖，一时唤入诚斋集。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晓经潘葑' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗绝句十七首 其十七', '梅尧臣', '宋代', '河畔有钓翁，团泥为瓮缶。坐想秦人声，思倾杜陵酒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗绝句十七首 其十七' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乾宁八景 其五 丰台夕照', '张缙', '明代', '寂寞荒台夕照边，居人犹自说丰年。太平气象何曾减，禾黍芃芃满大田。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乾宁八景 其五 丰台夕照' AND p.poem_author = '张缙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暗香 延平王祠古梅，相传王时物也', '梁启超', '清代', '东风正恶。算几回吹老，南枝残萼。水浅月黄，长是先春自开落。\n\n二百年前旧梦，早冷却栖香罗幕。但剩得片片倩魂，和雪渡溪彴。\n\n依约。共瘦削。便撩乱乡愁，驿使难托，鸾笺罢写。闲杀何郎旧池阁。\n\n休摘苔枝碎玉，怕中有归来辽鹤。万一向寒夜里，伴人寂寞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暗香 延平王祠古梅，相传王时物也' AND p.poem_author = '梁启超';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('英德道中', '文天祥', '宋代', '海近山如沃，杼深屋半芜。\n乾坤正风雨，轩冕总泥途。\n自叹鸢肩薄，谁怜鹤影孤。\n少年狂不醒，夜夜梦伊吾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '英德道中' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('莺啼序', '宋词', '近代', '端阳匆匆过了，正满城风雨。佳期近，此时情绪，都在眉头心底。\n\n真如梦，那堪回首，悲欢十二年间里。算而今尝尽，人间辛酸滋味。\n\n浦口斜辉，石城春晚，家门何处是。梧桐旧院依然在，楼上灯窗笑语。\n\n人去也，莫敲绣户，料空锁房中燕子。念此间，几度欢歌，几番悲泪。\n\n拭乾泪眼，暂抛离愁，后约为君许。因不肯，低头忍辱，蜗居淮海，风雷激起，中年意气。\n\n功过莫测，投阁未成，囚车示众金陵市。生和死，已作等闲视。\n\n偏偏难舍君情，未了枕边虚誓。春恩当日，宠柳娇花，记舞筵歌席。\n\n今相见，洗净铅华，衰颜残鬓，囚窗买粥，蓬头挑水。\n\n隔楼遥望，咫尺天涯，南农真是伤心地。料从此，团聚无期矣。\n\n茫茫来日方长，人还不老，心犹未死。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '莺啼序' AND p.poem_author = '宋词';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天（同前）', '向子諲', '宋代', '说著分飞百种猜。泥人细数几时回。风流可惯曾孤冷，怀抱如何得好开。 \n 垂玉箸，下香阶。凭肩小语更兜鞋。再三莫遣归期误，第一频教入梦来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天（同前）' AND p.poem_author = '向子諲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大田道中怀孟担', '佘翔', '明代', '几湾流水咽涓涓，五虎山青马首悬。欲访故人过峡口，南鸿犹自带风烟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大田道中怀孟担' AND p.poem_author = '佘翔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感咏二首 其一', '单人耘', '近代', '茑萝绿蒙茸，垂曳书窗外。清晨微雨来，飘洒云如黛。\n\n纤尘湿不起，寸心稍无碍。天地一浮沤，何由生嗔爱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感咏二首 其一' AND p.poem_author = '单人耘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送高炳如倅天台', '喻良能', '宋代', '高侯吾所畏，学问觑壶奥。秋水莹精神，春华丽词藻。\n\n三馆朅来游，两鬓青未皓。何心玩岁月，刻意事探讨。\n\n二志既崇成，八书可偕考。乌台伫风采，纶闱须典诰。\n\n引疾遽有祈，勇退一何早。丹丘非大名，泥轼仅小好。\n\n会看有诏追，岂必俟身到。行矣即轻安，恺悌神所劳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送高炳如倅天台' AND p.poem_author = '喻良能';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵别施平叔秋官', '李时行', '明代', '知己难为别，相携白下门。斜阳江上树，野水驿边村。\n\n旧业归心在，清时直道存。凄凄霜月夜，尊酒共谁论。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵别施平叔秋官' AND p.poem_author = '李时行';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题三峡堂', '张演', '宋代', '群山危立接云天，一水东朝会百川。泱漭堪舆无此壮，崔嵬疏凿定何年。\n\n千秋跃马兴亡梦，一点飞凫上下船。时有刚风来浩渺，起予高兴九秋边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题三峡堂' AND p.poem_author = '张演';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丰干赞', '释绍昙', '宋代', '加纱挂头何规矩，眼要看经不识字。\n差般差样制风颠，硬作斑猫骑作虎。\n道是弥陀，有何本据。\n闾丘太守，似苏州子。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丰干赞' AND p.poem_author = '释绍昙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次徐监簿韵贺吴侍郎新第落成 其一', '释善珍', '宋代', '碧落仙人上界还，手携奎壁下天关。百年第宅复金盏，万卷图书围玉山。\n\n霜压老槐龙卧壑，春催红药凤衔环。时危报主诗人志，好爱苍生莫爱闲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次徐监簿韵贺吴侍郎新第落成 其一' AND p.poem_author = '释善珍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小重山令 与保庵话扬州湖上旧游', '杜文澜', '清代', '十载虹桥买醉时。携尊梅树下，说相思。三生杜牧恨来迟。\n\n红楼外，莺老绿杨枝。\n\n愁弄玉参差。销魂春去也，鬓丝丝。惜花心事已全非。\n\n西风怨，惟有白鸥知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小重山令 与保庵话扬州湖上旧游' AND p.poem_author = '杜文澜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('京师九日城南黑窑厂登高', '周远', '清代', '愁思天涯九日晴，凭高闲望夕阳明。天清万丈秋潭影，风急三关落木声。\n\n双阙参差连御苑，乱山合沓入边城。悬军绝幕思飞将，闻道河西已厌兵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '京师九日城南黑窑厂登高' AND p.poem_author = '周远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春早二首 其一', '段继昌', '金朝', '鱼儿水汎鸭头绿，野马尘飞羊角风。西崦山家篱落背，杏梢初见一分红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春早二首 其一' AND p.poem_author = '段继昌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暇日同郑以孝游定光庵坐志喜亭上以池清龟出曝松暝鹤飞回为韵各赋十首用纪一时之清兴云 其九', '唐文凤', '明代', '倚阑兴未尽，坐久心忘归。树远碍云出，鸦回背日飞。\n\n地接市喧近，境留尘迹稀。朗吟下山去，松风凉葛衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暇日同郑以孝游定光庵坐志喜亭上以池清龟出曝松暝鹤飞回为韵各赋十首用纪一时之清兴云 其九' AND p.poem_author = '唐文凤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵濮十太尉咏知宗牡丹七绝 其二', '王十朋', '宋代', '月陂春色满花枝，国色天香照雪肌。当日栽陪恐无地，如今谁保旧园池。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵濮十太尉咏知宗牡丹七绝 其二' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冯大参汝言出饯临汾驿留别', '谢榛', '明代', '归鸿不失洞庭群，樽酒天涯此别君。残岁冰霜仍道路，早春书剑又河汾。\n\n驿亭驻马淹行色，官柳啼鸦送落曛。二十年来频聚散，那堪白首叹浮云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冯大参汝言出饯临汾驿留别' AND p.poem_author = '谢榛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和前人重九日寄', '赵抃', '宋代', '丁字溪流甚箭奔，忍看行色夕阳村。三吴望远迷烟棹，九日登高泥酒樽。\n\n诗得琼瑶今有意，感充怀抱更无言。归欤一曲桐江好，西北通宵欲梦魂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和前人重九日寄' AND p.poem_author = '赵抃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题峻极下院列岫亭诗 其二', '李廌', '宋代', '山色满亭亭倚空，与君俱在画图中。解道龙腾青壁断，令人却忆漫浪翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题峻极下院列岫亭诗 其二' AND p.poem_author = '李廌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过麻山寺', '李达', '当代', '逐人山月暮云端，乔木村墟萤火寒。野寺心香桂丛发，步檐天乐鸟声阑。\n\n藜床卧病何须药？蓬鬓随风莫正冠。已过斋时仍乞饭，摘蔬蒸栗尽清欢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过麻山寺' AND p.poem_author = '李达';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('续催送日鼓谣（邓侍郎崖山作催送日鼓谣文丞', '汪德钧', '明代', '冬冬晨鼓催，目注东方白。\n日华欲动月无辉，杀气冲天云血色。\n坎坎暮鼓击，日没崦嵫黑。\n朔风吹海毒波翻，旄头错落光芒出。\n日复夜，夜复日，日夜相催鼓声急。\n枕戈不寐食忘餐，力不能支仰天泣。\n主辱臣死古义存，弟妹瓢零敢遑恤。\n整旗收队决雌雄，黄龙孰遣横江中。\n风雷昼晦天地变，君臣不见崖山空。\n至今涛声吼朝夕，半为猿鹤半沙虫。\n当时豪杰能几子，千载不泯惟孤忠。\n催日鼓，送日鼓，调短意长歌愈苦。\n鲛人闻得泪成珠，踯躅白鹇惊堕浦。\n侍郎丞相家国同，当时戮力无尔汝。\n补天炼石竟无功，空余五色神光吐。\n斯人斯作世岂多，合入青编照今古。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '续催送日鼓谣（邓侍郎崖山作催送日鼓谣文丞' AND p.poem_author = '汪德钧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '蒋瑎', '宋代', '谁知清淡者，冬月亦登临。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '蒋瑎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('缪燧为令得御书', '沙曾达', '近代', '居官定海廿馀年，泽遍黎民惠政编。宠锡御书珍翰墨，入祠名宦媲前贤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '缪燧为令得御书' AND p.poem_author = '沙曾达';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花引 和赵平原催梅 天下同文', '卢挚', '元代', '绿华缥缈玉无痕。托清尘。拟招魂。放著篮与，懒倦到前村。笑抚高斋新树子，晚妆未，悠悠学梦云。竟日含情何所似，似佳人。望夫君。寒香细月空江上，会有春温。羞涩冰蕤，寂寞掩重门。交下横枝消息动，肯虚负，风流竹外尊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花引 和赵平原催梅 天下同文' AND p.poem_author = '卢挚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('罗汉洞', '程公许', '宋代', '中岩洞透牛头洞，后洞门从此处开。\n刹刹尘尘皆住处，胜游何必限天台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '罗汉洞' AND p.poem_author = '程公许';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送江陵刘县丞得多字 其一', '项安世', '宋代', '一语动愁思，良朋能几多。相持看鬓发，容易隔山河。\n\n旧学纷疑信，新功废琢磨。因君戒行李，令我悟蹉跎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送江陵刘县丞得多字 其一' AND p.poem_author = '项安世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('瓠岱里索题龙舟辞得十二绝 其二', '王坤', '清代', '居人夙好叶公龙，更与涛头写幻踪。钲鼓喧阗铙吹亲，短歌剧喜问吴侬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瓠岱里索题龙舟辞得十二绝 其二' AND p.poem_author = '王坤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书酒家壁', '范仲淹', '宋代', '当垆一曲竹枝歌，肠断江南奈尔何。游子未归春又老，夜来风雨落花多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书酒家壁' AND p.poem_author = '范仲淹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陈氏园亭', '李光', '宋代', '花径微通竹径幽，暮年清赏在林丘。登临未觉三山隔，俯仰常随万壑流。\n\n乐土自应多乐事，闲身居此得闲游。酒杯棋局平生事，莫把枯肠数搅搜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陈氏园亭' AND p.poem_author = '李光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次纲官王簿韵兼简伯潜二首 其一', '廖行之', '宋代', '江上晴光照眼浓，十分春色满城东。客怀何限湘波绿，漕事方殷汉粟红。\n\n雅有诗情添兴远，可无酒力破愁攻。舳舻早晚蒲帆稳，长啸东南万里风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次纲官王簿韵兼简伯潜二首 其一' AND p.poem_author = '廖行之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行路难 其五十一', '钱澄之', '清代', '老僧多病苦修偏，课诵行禅夜不眠。更荷慈悲留过客，为怜单被自装绵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行路难 其五十一' AND p.poem_author = '钱澄之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南唐后主画竹引', '郑善夫', '明代', '君不见彭城彭奴元姓李，早入徐家称帝子。又不见九华山下齐丘生，晚入南唐作谋士。\n\n同时契合风尘里，草昧君臣若鱼水。淮北初收格斗尘，宫中漫得丹青理。\n\n升元阁上写墨竹，翠葆萧森凤毛起。手书珍重表恩殊，御墨淋漓湿桑梓。\n\n世代相催犹梦幻，金陵画饼宁复尔。帝王从古多好手，人物绚素无不有。\n\n前有殷武丁，物色惟传傅岩叟。后有宋道君，鹰犬骅骝歘飞走。\n\n丹青意气稍或别，治乱兴亡一回首。彭奴彭奴听我歌，淇水才贤本众多。\n\n但惜九华山，不似傅岩阿。吁嗟乎竹花零乱岁蹉跎，凤凰不来将柰何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南唐后主画竹引' AND p.poem_author = '郑善夫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('破虏凯歌二十四首', '周麟之', '宋代', '虏饿曾无一月粮，煮弦烧箭莫弃肠。\n南来本恃清河粟，不意偏师夜绝纲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '破虏凯歌二十四首' AND p.poem_author = '周麟之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黑漆弩 其二 谢熊南沙跋帖', '杨慎', '明代', '月仪蠹简留君住。索靖是右军师父。笑藏真、酗酒狂僧，说甚龙蛇风雨。\n\n戏鱼堂、响榻重镌，莫道影留形去。熊朋来，鼎韵钟铭，鉴赏到、西台妙处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黑漆弩 其二 谢熊南沙跋帖' AND p.poem_author = '杨慎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵赵积中慈湖即事', '王之道', '宋代', '干戈九载予心哀，乱离谁复歌南陔。\n喜君父母老相守，调官仍逐金陵来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵赵积中慈湖即事' AND p.poem_author = '王之道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('百字令 登莫干山，夜黑风狂，清寒砭骨，率成此调', '吕碧城', '清代', '万峰泼墨，漾红灯一点，径穿幽筱。翠袖单寒临日暮，来御天风浩浩。\n\n湍瀑惊雷，筼筜戛玉，仙籁生云表。飞琼前世，旧游疑是曾到。\n\n昨日绮阁香温，宿酲犹殢，谁换炎凉早。争道才华多鬼气，占尽人间幽悄。\n\n侵入灵犀，冻馀冰茧，芳绪抽难了。驿程倦影，微茫愁入秋晓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '百字令 登莫干山，夜黑风狂，清寒砭骨，率成此调' AND p.poem_author = '吕碧城';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂三十二首 其二', '释宗演', '宋代', '空病有为药，有病空为药。空有两俱非，药病何处著。\n\n无处著，万里秋风飞一鹗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂三十二首 其二' AND p.poem_author = '释宗演';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦臣惠潘谷墨 其二', '邹浩', '宋代', '潘谷卖墨时，吕翁尝过之。指授长生诀，举世那能窥。\n\n但称众墨中，谷墨最珍奇。一旦内药成，解去逃喧卑。\n\n忽忽期月后，来与丹元期。夜饮晓分手，丹元初不知。\n\n仍留墨数片，属元付其儿。有儿旋其门，顶白元惊疑。\n\n细诘所以然，始知谷如斯。谷仙今几年，谷墨今在兹。\n\n静言人间世，舟壑常密移。朱颜兀槁木，绿发垂素丝。\n\n借令富贵极，毕竟将奚为。谷乎真可人，得墨吾得师。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梦臣惠潘谷墨 其二' AND p.poem_author = '邹浩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄懒庵', '刘子翚', '宋代', '山暝雨连夕，今晨天气清。\n遥怀懒庵人，高卧掩柴荆。\n幽寂性所嗜，萧然寄平生。\n惟应田叟来，对床话躬耕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄懒庵' AND p.poem_author = '刘子翚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜话', '沈琮宝', '清代', '竹篱西畔豆棚东，竟夕盘桓兴自同。为爱清言时娓娓，翻疑夜漏太匆匆。\n\n几人留恋三更后，千古兴亡一席中。月落参横催曙色，闲谈水乳喜交融。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜话' AND p.poem_author = '沈琮宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('疏影 秋柳', '李良年', '清代', '旗亭陇首。正新霜乍点，斜日风骤。一片秋声，几树萧疏，惊心十里津堠。\n\n行人欲折还教住，为记得、别离时候。洒渭城、朝雨如烟，曾向画桥分手。\n\n何处无情玉笛，忍教一夜里，吹堕江口。系马无人，认取寒枝，惟有晚鸦依旧。\n\n相思最是鸳鸯渡，应渐冷、碧纱窗牖。纵待得、来岁春还，只恐那人腰瘦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '疏影 秋柳' AND p.poem_author = '李良年';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登轮感赋', '李叔同', '近代', '感慨沧桑变，天边极目时。晚帆轻似箭，落日大如箕。\n\n风倦旌旗走，野平车马驰。河山悲故国，不禁泪双垂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登轮感赋' AND p.poem_author = '李叔同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白云上人精舍寻杼山禅师兼示崔子向何山道上人', '皎然', '唐代', '望远涉寒水，怀人在幽境。为高皎皎姿，及爱苍苍岭。 \n 果见栖禅子，潺湲灌真顶。积疑一念破，澄息万缘静。 \n 世事花上尘，惠心空中境。清闲诱我性，遂使肠虑屏。 \n 许共林客游，欲从山王请。木栖无名树，水汲忘机井。 \n 持此一日高，未肯谢箕颍。夕霁山态好，空月生俄顷。 \n 识妙聆细泉，悟深涤清茗。此心谁得失，笑向西林永。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白云上人精舍寻杼山禅师兼示崔子向何山道上人' AND p.poem_author = '皎然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大雪', '孔武仲', '宋代', '穷年阙雨谩悲歌，喜见凌晨雪意多。\n天上乱花初剪玉，楼头密影已翻波。\n轮蹄著路织尘断，庭宇无风凛气和。\n寄语云师勤覆护，莫令光景漏银河。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大雪' AND p.poem_author = '孔武仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('栽松', '行端', '元代', '钝钁横肩雪未消，不辞艰步上岧峣。等閒种得灵根活，会看春风长绿条。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '栽松' AND p.poem_author = '行端';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('将别故居迁小山堂之西偏感赋 其一', '庄宇逵', '清代', '庭花晻薆树扶疏，惆怅西风别故居。一宿三如留客舍，此行犹自爱吾庐。\n\n嬉游少日情无限，歌哭中年泪有余。易衍克家书肯构，孤儿心事痛何如。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将别故居迁小山堂之西偏感赋 其一' AND p.poem_author = '庄宇逵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('木兰花慢 武邑县王楫善居室，母俎氏出隆平', '王恽', '元代', '精彩如五六十人。教授马君向予方以善俗任责楫之孝养致乐，实有关於风化者，故作是词以付，俾来者庶有所劝焉烂云衢彩婺，和晓月，满庭闱。正梅粉香飘，林梢紫动，淑景初迟。观津盛传王氏，道孝心、重见老莱衣。和气一家瑞霭，慈颜九十柔仪。香烧静院趁朝晖。未省杖扶持。纵德厚流长，遐龄能健，此事应稀。婆娑绿萱堂背，爱一竿、苍竹六孙枝。照映西山秀色，年年翠点修眉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '木兰花慢 武邑县王楫善居室，母俎氏出隆平' AND p.poem_author = '王恽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('放歌行答从弟墨卿', '李颀', '唐代', '小来好文耻学武，世上功名不解取。虽沾寸禄已后时， \n 徒欲出身事明主。柏梁赋诗不及宴，长楸走马谁相数。 \n 敛迹俯眉心自甘，高歌击节声半苦。由是蹉跎一老夫， \n 养鸡牧豕东城隅。空歌汉代萧相国，肯事霍家冯子都。 \n 徒尔当年声籍籍，滥作词林两京客。故人斗酒安陵桥， \n 黄鸟春风洛阳陌。吾家令弟才不羁，五言破的人共推。 \n 兴来逸气如涛涌，千里长江归海时。别离短景何萧索， \n 佳句相思能间作。举头遥望鲁阳山，木叶纷纷向人落。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '放歌行答从弟墨卿' AND p.poem_author = '李颀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('豪彘赞', '郭璞', '魏晋', '刚鬣之族，号曰豪彘。毛如攒锥，中有激矢。厥体兼资，自为牝牡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '豪彘赞' AND p.poem_author = '郭璞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟古', '苏泂', '宋代', '汉光昔未遇，颇为兄嫂欺。\n谁知韩王信，本是屠沽儿。\n他时筑将坛，意气帝者师。\n中兴屏新莽，长剑诛赤眉。\n皇天生一物，大小随其资。\n倒令饥与寒，何以生育为。\n永言观厥成，圆璧殊方圭。\n天意定不尔，变化应须时。\n少小弄文翰，把笔能哦诗。\n十五学缀文，如茧中抽丝。\n青云付达官，十九名新知。\n南辕异燕路，鄙笑无挈提。\n甘心穷阎中，疏食黄瓜虀区区蠹鱼习。\n槁死不可医。闲斋秉微尚，\n高视圣者师。谩言苦如荼，\n谁信甘如饴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟古' AND p.poem_author = '苏泂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('成都试飞', '魏新河', '当代', '身共浮云作意飘，江山巴蜀望中遥。横江半寸如毛发，知是成都万里桥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '成都试飞' AND p.poem_author = '魏新河';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与契兄', '赵蕃', '宋代', '因怀碧云友，发兴青林端。\n要尽深幽趣，浑忘下上难。\n泉声流咽绝，松韵响高寒。\n久作庐山别，疑从梦境看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与契兄' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('用寄璧上人韵寄范元实赵才仲及从叔知止兼率山伯同赋', '吕本中', '宋代', '故人瓶锡各西东，吾道从来冀北空。病去渐于文字懒，南来犹觉岁时公。\n\n江回夜雨千岩黑，霜着高林万叶红。政好还家君未肯，莫教惭愧北窗风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '用寄璧上人韵寄范元实赵才仲及从叔知止兼率山伯同赋' AND p.poem_author = '吕本中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望罗浮柬王李二君二首 其一', '林大春', '明代', '高标出岭外，特地起金莲。岱岳连沧海，峨眉入洞天。\n\n俯看朝日出，侧听夜河悬。倚棹时凝望，玉京飞曙烟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望罗浮柬王李二君二首 其一' AND p.poem_author = '林大春';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日咏刀', '玄烨', '清代', '七宝刀光耀斗牛，建章佩带向初秋。清流越砥方知力，截兕剸鲸断不愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日咏刀' AND p.poem_author = '玄烨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和薛田察院咏雪三首', '魏野', '宋代', '七字空吟六出花，与君无酒祇烹茶。\n门前俱绝行踪迹，还似袁安卧在家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和薛田察院咏雪三首' AND p.poem_author = '魏野';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天（母侯置酒南教场赏芙蓉）', '陈耆卿', '宋代', '莫惜花前泥酒壶。沙场千步锦平铺。将军闲试临边手，按出吴宫小阵图。 \n 清露里，晓霜馀。娇红淡白更怜渠。人间落木萧萧下，独倚秋江画不如。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天（母侯置酒南教场赏芙蓉）' AND p.poem_author = '陈耆卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉制文武诗 其六', '徐溥', '明代', '覆载中存报主身，庙堂须用读书人。民胞物与皆吾分，一视应同万里仁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉制文武诗 其六' AND p.poem_author = '徐溥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('步云鞋 本名软翻鞋赠玄真观单姑等献履鞋', '王丹桂', '元代', '幸遇教风开。和气洽吾怀。玄真清众总仙才。志谦和、恭顺垂慈惠，殷勤献，步云鞋。\n\n妙手巧剜裁。珠宝砌双腮。一回朝礼蹑坛台。待他年、真行真功满，超尘世，赴蓬莱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '步云鞋 本名软翻鞋赠玄真观单姑等献履鞋' AND p.poem_author = '王丹桂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春 小斋开同心兰一枝，为赋此解', '易顺鼎', '清代', '草红心耶，花素心耶，同心此兰。正倚篁幽泣，邀回露眼，窥萝靓笑，对亸风鬟。\n\n何处神君，旧家儿女，一碧湘魂欲化烟。东皇力，让灵均今日，清艳能兼。\n\n紫钗敲韵珊珊。漫分付、笼鹦说晓寒。尽捧当怨雨，矉原非效，印来香月，梦不成单。\n\n秋士年华，春人影事，从古双修福慧难。真开也，算相思北渚，称意西天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春 小斋开同心兰一枝，为赋此解' AND p.poem_author = '易顺鼎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杭州探梅历游超山西泠烟霞洞灵峰以中有万斛江南愁为韵 其二', '黄浚', '近代', '空山晚吹香，松竹导清黝。思当如旸台，绣谷奄群有。\n\n寺门两亩花，宋树以石守。喧寂趣终殊，梅杏非夷丑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杭州探梅历游超山西泠烟霞洞灵峰以中有万斛江南愁为韵 其二' AND p.poem_author = '黄浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵高缙之二首 其一', '陈造', '宋代', '能事馀千牍，幽期自一丘。向来书襞积，不疗客漂流。\n\n小挹苏耽鹤，同歌宁戚牛。几时诗酒社，相属话天游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵高缙之二首 其一' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南归寄乡旧 其九', '陈献章', '明代', '出处有分付，将非人所能。君看飞鸟辈，谁不顾高腾。\n\n放意三杯酒，留情半夜灯。韦丹非俗吏，灵澈自高僧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南归寄乡旧 其九' AND p.poem_author = '陈献章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉题少保张公曲阿别墅二首 其二', '王寂', '金朝', '钟湖亭下水淙淙，绿野平泉未易双。十里藕花红步障，一轩松荫碧油幢。\n\n洛中独乐有司马，天下不名知曲江。纸尾欲烦贤宅相，雨蓑添我坐篷窗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉题少保张公曲阿别墅二首 其二' AND p.poem_author = '王寂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('揭天谣九首 其一', '周玄', '明代', '巨灵吹空南斗死，鬼哭如云学流水。桂阑天影白鹤秋，兔光斜坠三泉里。\n\n泉宫暗虫寒草根，土灯燃露絓黄昏。铁心九回滴秋血，三十六帝闻俱吞。\n\n帝遣双童去不返，楸梧参差牧马苑。青烟一点吹六龙，芙蓉吐光海波浅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '揭天谣九首 其一' AND p.poem_author = '周玄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂兴三十九首 其二十九', '张镃', '宋代', '圣狂霄壤分，其端在一念。去恶向忠义，如病用良砭。\n\n方贻害于人，蛟虎并凶燄。及其惩艾馀，大节秉无欠。\n\n卓绝补过功，炳炳照铅椠。乃知春秋意，恶恶待终厌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂兴三十九首 其二十九' AND p.poem_author = '张镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('燕居', '张元凯', '明代', '衡门聊偃息，泌水可忘餐。黄鸟林中听，青山江上看。\n\n云流石几净，花落竹房寒。短发偏宜散，何须制箨冠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '燕居' AND p.poem_author = '张元凯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送秦炼师归岑公山', '李群玉', '唐代', '紫泥飞诏下金銮，列象分明世仰观。北省谏书藏旧草， \n 南宫郎署握新兰。春归凤沼恩波暖，晓入鸳行瑞气寒。 \n 偏是此生栖息者，满衣零泪一时干。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送秦炼师归岑公山' AND p.poem_author = '李群玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送韩一初赴马万户府参议', '周霆震', '元代', '才俊宜从幕府升，四郊何日保安宁。连营未报休传箭，策马何嫌出戴星。\n\n苦战城壕霜月白，屡残村落野烟青。军民甚有关心处，佐政行看刃发硎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送韩一初赴马万户府参议' AND p.poem_author = '周霆震';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题九马图', '倪岳', '明代', '穆王八骏名天下，此马雄瑰岂其亚。渥洼夜堕房星精，神物应随牝龙化。\n\n纤离騄駬少为贵，三十六蹄更堪诧。想当阊阖辟清晓，霓旌队引銮和驾。\n\n朝回初遣脱金羁，呈了曾看覆黄帕。天厩深严日正长，奚官出牧乘閒暇。\n\n晴堤水满柳阴森，芳草蒙茸犹可藉。长嘶深浴各有适，俊骨奇姿本无价。\n\n祇今承平息边燧，戎垒征鞍不须跨。长嗟健步何由骋，骐骥驽骀等衰谢。\n\n王良伯乐会有合，足下风云生叱咤。追电终轻万里程，直历蓬瀛蹴嵩华。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题九马图' AND p.poem_author = '倪岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题唐十八学士图二首 其二', '赵佶', '宋代', '儒林华国古今同，吟咏飞毫醒醉中。多士作新知入彀，画图犹喜见文雄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题唐十八学士图二首 其二' AND p.poem_author = '赵佶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('复次漫兴前韵八首（录四）', '钱谦贞', '明代', '全袪滓秽长清虚，闻道神仙似我臞。\n颦丑谩劳西子笑，力绵休学北公愚。\n携锄鏚石栽松子，乞竹编笼养鹤雏。\n容膝易安能自审，有人蓬户与桑枢。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '复次漫兴前韵八首（录四）' AND p.poem_author = '钱谦贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和昙颖师四明十题 其二 龙隐潭', '梅尧臣', '宋代', '老龙恋潭窟，不雨亦不云。吐涎出溪滑，吹腥隔林闻。\n\n疾雷驱未去，鱼鳖竞纷纷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和昙颖师四明十题 其二 龙隐潭' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂咏 其二', '罗公升', '宋代', '胡羯宁知分，中原欲并驱。设兵生建武，堪与赤眉俱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂咏 其二' AND p.poem_author = '罗公升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古意 其一', '申佳允', '明代', '纤纤弄玉盆，月挂垂杨树。盆中影似郎，几回捉不住。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古意 其一' AND p.poem_author = '申佳允';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花 冬日得国内友人书，道时事甚悉，怅然赋此', '汪精卫', '近代', '雨横风狂朝复暮。入夜清光，耿耿还如故。抱得月明无可语，念他憔悴风和雨。\n\n天际游丝无定处。几度飞来，几度仍飞去。底事情深愁亦妒，愁丝永绊情丝住。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花 冬日得国内友人书，道时事甚悉，怅然赋此' AND p.poem_author = '汪精卫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其二', '韩缜', '宋代', '唐蒙谕巴蜀，通道至邛僰。列郡徼西南，夷居半岩壁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其二' AND p.poem_author = '韩缜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早寒', '曹锡宝', '清代', '策蹇凌霜坂，风高木叶乾。空山秋易老，绝塞气先寒。\n\n肃肃车徒静，迢迢鼓角残。幸依仙仗近，行路敢云难。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早寒' AND p.poem_author = '曹锡宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阅韩芬男为李九倩书少年行', '苏景熙', '明代', '写字须写意，运笔须运神。韩生乍疑腕有鬼，岂知振动往往恒逼真。\n\n右军内擪故森严，大令外拓故疏朗。兰亭变转搆别体，洛神遒劲信真赏。\n\n遗迹至今几千载，六义八法依然在。谁能研精拨镫理，直与点画增光彩。\n\n宁为凌冬枯树，毋为重台使者。状如算子岂是书，宜先筋骨藏锋下。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阅韩芬男为李九倩书少年行' AND p.poem_author = '苏景熙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('禅人并化主写真求赞', '释正觉', '宋代', '山林眉目，水月身心。\n雪何早而古岩棱，秋似先而寒潭深。\n机头绵绪，线尾金针。\n谁云道大兮自有知音。神静气清，\n心空眼明。诸尘中豁落，\n万像里峥嵘。去而随，\n来而迎。三世竖，\n十方横。风吹便倒须相信，\n恰恰谁曾与物争。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '禅人并化主写真求赞' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同外孙文九新春五绝句', '苏辙', '宋代', '雪覆西山三顷麦，一犁春雨祝天工。\n麦秋幸与人同饱，昔日黄门今老农。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同外孙文九新春五绝句' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哈密送长节帅', '方希孟', '清代', '茫茫大碛四边秋，山满寒城雪满楼。一帜元戎千骑捧，月明笳吹下伊州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哈密送长节帅' AND p.poem_author = '方希孟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢薛省判寄惠鹤', '魏野', '宋代', '早辍仙禽寄逸民，年来亦似厌家贫。\n时时东望长鸣处，应忆朱门旧主人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢薛省判寄惠鹤' AND p.poem_author = '魏野';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新秋瀛台杂咏 其三', '弘历', '清代', '竹蹊诘曲如诗读，湖石玲珑当画看。屧步不妨过半里，心舒雨后晓秋寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新秋瀛台杂咏 其三' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送张令同年赴岭南', '杨杰', '宋代', '滕王阁上正持杯，候吏先期过岭来。泽国暂抛三径菊，春风须寄一枝梅。\n\n昔年身到仁宗殿，同日鳞惊禹穴雷。万里青云有前约，莫因蓝绶叹尘埃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送张令同年赴岭南' AND p.poem_author = '杨杰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉教和资中八景', '王绅', '明代', '雨馀山水放清辉，惊见轻岚上翠微。薄影渐因红日淡，馀氛犹逐白云迟。\n\n如绡漠漠笼僧寺，似雨霏霏护石池。底事往来岩壑上，欲随祥霭出明时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉教和资中八景' AND p.poem_author = '王绅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满庭芳', '何振岱', '清代', '尘境风烟，衰年情绪，消领怎遣人知。古愁今恨，休写向琴丝。\n\n挨得众喧小息，凡缘外、探点玄机。无须问，欢悲异趣，与世总相遗。\n\n栖迟。如我愿，孱躯蛰影，默自禁持。任飘零逝水，梦杳书稀。\n\n留取孤光内照，有寥寂、便是佳时。炉香好，余生寄托，冷暖足因依。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满庭芳' AND p.poem_author = '何振岱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('正绣球花', '顾逢', '宋代', '正是红稀绿暗时，花如圆玉莹无疵。\n何人团雪高抛去，冻在枝头春不知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '正绣球花' AND p.poem_author = '顾逢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('光孝寺铁塔', '陈子升', '明代', '霸国禅关问大雄，南朝钟梵袭遗风。曾然劫火藏沙界，似立金茎表汉宫。\n\n狮座何人高说法，貂珰皈佛漫论功。檐铃不动诸天寂，薄暮愁看海日红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '光孝寺铁塔' AND p.poem_author = '陈子升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('历城道中', '黄景仁', '清代', '北游忽不乐，东来揽齐岱。陆尽燕赵交，水送汶泗会。\n\n只有清济源，伏流隐支派。亦如古达人，心迹有时晦。\n\n群山尽朝岳，敢向不敢背。峨峨灵威丈，揖我青霞外。\n\n迓客遣片云，飞来若车盖。挥手暂相谢，冰雪迫徂岁。\n\n游倦思小休，胜济行未艾。寄语雪中花，石上劳相待。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '历城道中' AND p.poem_author = '黄景仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('太常引 寿高丽王', '程文海', '元代', '沁园岁岁菊留芳。待此日、庆真王。金鼎燮和元。造寿域、同开八荒。河山带砺，一传千岁，地久与天长。晴日上扶桑。便先照、琼阶玉觞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '太常引 寿高丽王' AND p.poem_author = '程文海';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送户部尚书贡泰甫开司闽中榷盐易米给京师 其二', '贝琼', '明代', '两隅未挣出师频，圣主经营伏老臣。天河转粟遥通蓟，腊月看花近到闽。\n\n道上豺狼应避马，山中猿马不惊人。公馀定有诗千首，好托边鸿寄蚤春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送户部尚书贡泰甫开司闽中榷盐易米给京师 其二' AND p.poem_author = '贝琼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻吕敬夫移居五首 其二', '郭翼', '元代', '詹尹何劳更决疑，衡门之下可栖迟。竹从少傅韦家觅，树向果园坊里移。\n\n翡翠小堂巢窄窄，鸥鶄近渚槛垂垂。主人一任悬徐榻，更拟风流醉习池。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻吕敬夫移居五首 其二' AND p.poem_author = '郭翼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三宿岩', '文徵明', '明代', '积石谁名达磨岩，花间古洞锁苍烟。何能桑下淹三宿，却探仇池自一天。\n\n古树腾蛟根束铁，春苔蚀雨翠连钱。只应曾见台城事，回首梁王又几年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三宿岩' AND p.poem_author = '文徵明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题步瀛阁', '邓肃', '宋代', '玲珑画阁入鸿冥，隐约鸿冥入太清。\n紫气氤氲随步去，青霞杳霭逐行旌。\n桃花浪透三山近，龟角屏高七朵横。\n解逐梅仙在尘世，谁知尘世有蓬瀛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题步瀛阁' AND p.poem_author = '邓肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('野店多买花木瓜', '杨万里', '宋代', '天下宣城花木瓜，日华露液绣成花。\n何须堠子强呈界，自有琼琚先报衙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '野店多买花木瓜' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九日登尧山书事', '夏竦', '宋代', '满头黄菊鬓毛斑，曾议皇王对尔颜。\n今日临风轻霸迹，尧山应合胜牛山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九日登尧山书事' AND p.poem_author = '夏竦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贺新凉 采石太白楼，用洪稚存、黄仲则两家集中太白墓原韵', '易顺鼎', '清代', '江月都愁老。何苦向南朝一带，照他凭吊。采石荒矶闲系艇，有客倚阑而眺。\n\n谁看见吴宫花草。楼影千年流不去，缓商量毕竟诗人好。\n\n须记取，醉中稿。\n\n狂吟那顾先生笑。为神州骚沉雅坏，特来相告。更问锦袍归水后，清气收还多少。\n\n可许我骑鲸三岛。如此江山浑寂寞，但风帆几点和沙鸟。\n\n怀古意，怎生了。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贺新凉 采石太白楼，用洪稚存、黄仲则两家集中太白墓原韵' AND p.poem_author = '易顺鼎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过金陵四首', '苏泂', '宋代', '老树前头柿叶红，又骑瘦马立西风。\n江山未必侬能认，却被江山认得侬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过金陵四首' AND p.poem_author = '苏泂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋兴九首 其三 拟韦应物', '秦观', '宋代', '坐投林下石，秋声出疏林。林间鸟惊栖，岂独伤客心。\n\n物亦有代谢，此理共古今。邻父缩新醅，林下邀同斟。\n\n痴儿踏吴歌，娅姹足讹音。日落相携手，凉风快虚襟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋兴九首 其三 拟韦应物' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读史 其四', '罗公升', '宋代', '德光起龙沙，忽拔汴水帜。赭袍拜千官，始识皇帝贵。\n\n饮冰一何愚，剖腹有馀秽。可怜无知石，犹纪会同岁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读史 其四' AND p.poem_author = '罗公升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('将别迪化登机口号', '秦鸿', '当代', '雪岭方传昔我来，青林红柳竞毰毸。天风又送蓬莱去，满注流霞溢此杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将别迪化登机口号' AND p.poem_author = '秦鸿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题屏间', '刘宰', '宋代', '野旷乾坤大，身閒日月迟。有生均自得，造物本无私。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题屏间' AND p.poem_author = '刘宰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('前后蜀杂事诗 其二', '张祥龄', '清代', '宦寺新颁建节符，天雄进得美人无。牙兵龙虎飞章到，为献秦州花木图。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '前后蜀杂事诗 其二' AND p.poem_author = '张祥龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵杂兴二百首 其三十七', '苏泂', '宋代', '龙虎江山未改形，临高一目但青青。春风岂是无才思，不洗从来战伐腥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵杂兴二百首 其三十七' AND p.poem_author = '苏泂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('被花恼 珍丛馆蔷薇', '苏穆', '清代', '小园竟日惜春归，芳意独留仙馆。万叶千条倚娇软。\n\n窗前最是，双双蛱蝶，衬舞和愁乱。康欲语，又斜晖，半庭纤影凌波卷。\n\n长记艳深时，曾赋香痕压檐绽。新娥谩绿，早怯东风，取次相吹散。\n\n问何人暗遣斗芳菲，欲作弄、柔红梦中幻。拌醉也、莫待飘零清泪盼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '被花恼 珍丛馆蔷薇' AND p.poem_author = '苏穆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅雨', '苏泂', '宋代', '双飞蛱蝶情何厚，百啭仓庚韵可听。\n肯为螳蜋看黄鹤，忍从燕子乞蜻蜓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅雨' AND p.poem_author = '苏泂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('文溯阁', '金朝觐', '清代', '星斗焕天章，熙朝制作光。文昭灵宝瑞，书启酉山藏。\n\n玉检涵蓬观，金题拥墨庄。沿洄宗圣海，条理总皇纲。\n\n考义详于度，垂谋典以常。是尊天一阁，能益智千囊。\n\n工轶碑摹篆，劳嗤石作仓。薪传寻坠绪，逸事极穷荒。\n\n勒鼎功同禹，铭盘志比汤。留都思溯始，方策示无忘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '文溯阁' AND p.poem_author = '金朝觐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('直夜二首 其一', '杨亿', '宋代', '月魄生宵晕，风乌送晚凉。飞蝇随镂管，浮蚁溢清觞。\n\n负郭春耕废，钧天晓梦长。玉签声未断，落宿半宫墙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '直夜二首 其一' AND p.poem_author = '杨亿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('纵笔', '陆游', '宋代', '未说无功爵位叨，昔人所畏在功高。\n印如斗大宁常保，剑拄颐长秪自劳。\n酒社极知身可隐，猎场犹得气差豪。\n世间见透浑无事，狐貉安能诧縕袍！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '纵笔' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再用前韵谢吴竹修', '陈著', '宋代', '秃髡归阳羡，仙髯卧古藤。前贤成昨梦，后辈嗣谁镫。\n\n倾盖欣如故，吟坛得共登。春风吹相聚，聊此寄韦冰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再用前韵谢吴竹修' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('觅蠹椽', '高登', '宋代', '顾影低徊祇自怜，怕寒时耸作诗肩。全家食粥已数月，坐客无毡今几年。\n\n君劈槽烧当止酒，我和琴爨况无弦。雪中送炭从来事，况尔羁躬觅蠹椽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '觅蠹椽' AND p.poem_author = '高登';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬至晚起枕上有怀晋陵杨使君 其一', '范成大', '宋代', '新衣儿女闹灯前，梦里庄周正栩然。骑马十年听晓鼓，人生元有日高眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬至晚起枕上有怀晋陵杨使君 其一' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早过午桥口占（二首）', '陆容', '明代', '下马金门步晓凉，海云开白看东方。\n君王自有兴居节，不遣微臣一倒裳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早过午桥口占（二首）' AND p.poem_author = '陆容';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉同尤延之提举庐山杂咏十四篇 其九 简寂观', '朱熹', '宋代', '高士昔遗世，筑室苍崖阴。朝真石坛峻，炼药古井深。\n\n结交五柳翁，屡赏无弦琴。相携白莲渚，一笑倾夙心。\n\n晚岁更市朝，故山锁云岑。柴车竟不返，鸾鹤空遗音。\n\n我来千载馀，旧事不可寻。四顾但绝壁，苦竹寒萧椮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉同尤延之提举庐山杂咏十四篇 其九 简寂观' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十三夕诸君重饯妓筵醉后再作长歌', '姚燮', '清代', '百年不争一筵短，心近何愁万山远。潮平帆挂人欲离，霜紧天高月将满。\n\n昨筵饯我城南家，女墙三更多悽鸦。含啼试袖蝶粉湿，剪烛开门萝叶斜。\n\n今夕高楼控溟渤，明峦如荷媚空阔。沙风笛底吹黄萚，云影樽前堕苍鹘。\n\n羁身在客难自豪，慨叹当歌那能遏？欢歌已使心不留，还作愁歌暗挑拨。\n\n诸君爱我如爱心，常恐过劳难自任。又恐一逸易驰逝，便欲置我腔中深。\n\n百回顾惜到今夕，我负诸君顿言别。明知兰约春可期，已使桃根泪同咽。\n\n泪亦不得止，歌亦未肯阑。北斗欲没霜柝残，樯乌哑哑催出关。\n\n寸腑茫茫复何有，为君更尽一杯酒。劳君拔赠插鬟花，算折旗亭可怜柳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十三夕诸君重饯妓筵醉后再作长歌' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙', '林少君', '清代', '麟篆知从九夜扪。诗王金诰佩随身。映梅争羡气氤氲。\n\n绣纸十番传虎仆，蒸云千首动龙宾。于今坛坫自推君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙' AND p.poem_author = '林少君';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泛舟作河灯戏', '胡雪抱', '近代', '秋病恹恹百虑煎，偶随菱棹弄平川。灵犀闪烁驯妖夜，玉兔高寒浴魄天。\n\n云縠翠深飘冷梵，锦漪香重幻新莲。凭虚欲听湘弦去，菱叶纷纶却碍船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泛舟作河灯戏' AND p.poem_author = '胡雪抱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答河中梅龙图', '刘敞', '宋代', '龙池柳色锁春烟，故国风光此地偏。高下楼台浑浸水，往来车马自随船。\n\n举杯醉舞时相属，倚瑟悲歌忽怆然。安敢为文敌金谷，误烦求友赋新篇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答河中梅龙图' AND p.poem_author = '刘敞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舂夫', '华岳', '宋代', '秕糠粒粒裹真珠，玉杵舂来白有余。\n待问姮娥借金鼎，等閒令汝作蟾蜍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舂夫' AND p.poem_author = '华岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏梅五十首呈史尚书', '释绍嵩', '宋代', '梅萼才开已乱飞，清香时被好风吹。\n苦无疏影横斜句，空作主人惆怅诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏梅五十首呈史尚书' AND p.poem_author = '释绍嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('龙游八景·村市晓烟', '郑得彝', '宋代', '微茫村市隐江湄，三两人家欲早炊。\n翠箔楼台烟半湿，不知红日上花枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '龙游八景·村市晓烟' AND p.poem_author = '郑得彝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史十五首 其十一 光弼', '陶安', '明代', '谋成后战战功成，持已庄严号令明。以少覆多称第一，凌烟阁上合图形。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史十五首 其十一 光弼' AND p.poem_author = '陶安';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('至正改元辛巳寒食日，示弟及诸子侄', '虞集', '元代', '江山信美非吾土，飘泊栖迟近百年。\n山舍墓田同水曲，不堪梦觉听啼鹃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '至正改元辛巳寒食日，示弟及诸子侄' AND p.poem_author = '虞集';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贺明朝·忆昔花间相见后', '欧阳炯', '五代', '忆昔花间相见后，只凭纤手，暗抛红豆。人前不解，巧传心事，别来依旧，辜负春昼。\n碧罗衣上蹙金绣，睹对对鸳鸯，空裛泪痕透。想韶颜非久，终是为伊，只恁偷瘦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贺明朝·忆昔花间相见后' AND p.poem_author = '欧阳炯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蔡州叶翰林寄示近诗次韵八首 其三', '程俱', '宋代', '往客霅溪上，舒娥几亏盈。深穷卞山境，胜概不可名。\n\n柴车逐公游，登皋复临清。夜投阿兰若，松窗待朝明。\n\n济胜剧许掾，评诗陋钟嵘。灵滋初可抔，龙箨忽已萌。\n\n斯游今几时，坐想飞泉鸣。尚应几杖间，隐隐金石声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蔡州叶翰林寄示近诗次韵八首 其三' AND p.poem_author = '程俱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('示儿', '赵蕃', '宋代', '我昔读书夜达晨，膏烛且尽继以薪。\n年来渐知得力处，箪瓢陋巷忘其贫。\n尔曹有身须自立，幸逃薪水共朝夕。\n不于文章自勤苦，长大始悔何益。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '示儿' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送王益谦之京二首 其一', '乌斯道', '明代', '笑看车马去堂堂，玩愒人间岁月长。文似健兵能力战，才如良贾只深藏。\n\n烟波一钓非无具，花柳孤村自有庄。沧海遗珠留不得，随龙飞起落清湘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送王益谦之京二首 其一' AND p.poem_author = '乌斯道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留题觉华岛龙宫寺', '王寂', '金朝', '传闻三山驾空虚，珠宫贝阙神仙都。茫茫弱水限舟楫，人迹不到如有无。\n\n平生点检江山好，秪有龙宫觉华岛。何年经创作者谁，兴圣帝师孤竹老。\n\n老人绝俗栖金沙，岁久喜舍来天家。悬崖架壑置佛屋，突兀殿阁凌烟霞。\n\n乃知造物开神异，故压祇园布金地。四顾鲸波翼宝岩，玻璃环拥青螺髻。\n\n我生自厌薰膻腥，坐觉两腋生清泠。夜凉海月耿不寐，几欲举手扪天星。\n\n明朝收帆落尘土，一梦回头散风雨。向令坡老此经行，想不愿为天竺主。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留题觉华岛龙宫寺' AND p.poem_author = '王寂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和景贤十一首 其八 读唐史有感', '耶律楚材', '元代', '林甫滔天圣不知，三郎深恨识卿迟。尘中妃子春罗袜，钱上开元指甲眉。\n\n七夕殿中祈巧夜，三秋原上摘瓜时。长天忽见飞来雁，垂泪空吟李峤诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和景贤十一首 其八 读唐史有感' AND p.poem_author = '耶律楚材';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红 其十四 寄呈荔裳', '尤侗', '明代', '北望卢龙，痛精卫、魂填溟涨。何幸得、南楼老子，下官无恙。\n\n千里相思风雨夕，十年重过江湖上。笑故人、只有一杯莼，为君饷。\n\n飞蝶梦，游丝漾。骑马地，朝鸡唱。算半生白发，星星愁酿。\n\n笠泽烟波宜载酒，泰山日观聊携杖。再休提、宋玉赋秋风，悲哉状。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红 其十四 寄呈荔裳' AND p.poem_author = '尤侗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('将为南行陪尚书崔公宴海榴堂', '许浑', '唐代', '朝宴华堂暮未休，几人偏得谢公留。风传鼓角霜侵戟， \n 云卷笙歌月上楼。宾馆尽开徐稚榻，客帆空恋李膺舟。 \n 谩夸书剑无知己，水远山长步步愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将为南行陪尚书崔公宴海榴堂' AND p.poem_author = '许浑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('平江颜侍郎', '周必大', '宋代', '吴门自古俊髦多，中外推公政事科。议礼不妨丰酒课，治繁犹暇讲禅那。\n\n榻前屡记宣除目，川上遥怜逐逝波。底用镌碑纪廉直，乡评正自不消磨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '平江颜侍郎' AND p.poem_author = '周必大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新城塔山对雨二首一', '晁补之', '宋代', '山外圆天一镜开，山头云起似浮埃。\n松吟竹舞水纹乱，坐见溪南风雨来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新城塔山对雨二首一' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽刘大监思恭', '度正', '宋代', '簪绂源流远，诗书气味香。\n啼莺翔涧谷，鸣凤瑞朝阳。\n壮志欣辰告，羸躯痛夕亡。\n万夫今失望，拟欲问苍苍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽刘大监思恭' AND p.poem_author = '度正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春暮郊游', '贺国华', '清代', '寂寂春光昼掩扉，不知春事正芳菲。双柑斗酒偶然出，柳絮梨花无数飞。\n\n清圳风柔鸠语静，野塘雨足鳜鱼肥。夕阳一路经行处，陌上人歌缓缓归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春暮郊游' AND p.poem_author = '贺国华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长溪建善寺四首 龙湫亭', '刘安上', '宋代', '亭下一杯水，澄泓如有容。不因求得雨，那信有神龙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长溪建善寺四首 龙湫亭' AND p.poem_author = '刘安上';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋怀', '李若水', '宋代', '西风响窗扉，炎火烦一扫。\n天清露华滋，妍碧谢庭草。\n旅怀良独难。缺月窥檐间。\n呼儿漉新酒，强俗朱衰颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋怀' AND p.poem_author = '李若水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('澎湖旅思 其四', '翟俦', '清代', '寒剑萧条天外游，蛮烟番雨几经秋。乾坤共识浮云幻，日月空随大海流。\n\n骨傲自惭难媚世，病馀那忍独登楼。愁来欲问愁何事，意绪茫茫似十洲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '澎湖旅思 其四' AND p.poem_author = '翟俦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜陈兄至', '白居易', '唐代', '黄鸟啼欲歇，青梅结半成。坐怜春物尽，起入东园行。 \n 携觞懒独酌，忽闻叩门声。闲人犹喜至，何况是陈兄。 \n 从容尽日语，稠叠长年情。勿轻一盏酒，可以话平生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜陈兄至' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登师山诸生有书二首 其二', '郑玉', '元代', '山前村落乱高低，云意模糊远近迷。万叠峰峦如画展，黄山正在小楼西。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登师山诸生有书二首 其二' AND p.poem_author = '郑玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('催会中诸老起钓台仙迹亭', '张天赋', '明代', '打约曾同洛下英，黄鸡白酒祭山灵。钓台不减灵台乐，试问何时起钓亭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '催会中诸老起钓台仙迹亭' AND p.poem_author = '张天赋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('种梅', '史文卿', '宋代', '素与梅花自有缘，又移几本种庭前。\n镜中一半閒风月，不属王郎载雪船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '种梅' AND p.poem_author = '史文卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('网坛岁杪漫怀', '熊东遨', '当代', '风雨年来习不惊，惟凭一网寄深情。夜阑忆及闲常事，顿觉潮从枕上生。\n\n一念初萌谁解我，寒江夜济知苇可。此中缘份是天成，莫更无端问因果。\n\n新酿梨花酒一坛，又因风雪忆天山。不知星汉云空里，邀得神仙几个还？\n\n瑶池八骏朝天帝，玉辔金镫添意气。山右狷狂马独来，行空不受丝缰系。\n\n长白山头雪浪奔，剪梅独许到俞门。人间世态知多少，一掬清泉自养根。\n\n自种松杉初及额，能从近处瞻高格。半梦长留一念真，足胜万古虚矫客。\n\n梅云梅雨孰为先，如水交情二十年。窗外晦明何必问，纤尘不染是心田。\n\n长河自古多姿彩，百折千回终不改。涛声日夜若奔雷，直挟泥沙泻东海。\n\n一剪烟波一叶舟，自由天地足淹留。当年靓丽渔家女，赢得名声也白头。\n\n孤月冷霜光自照，岁寒不改苍枝傲。丹田蓄得气如虹，耐寂轩中时一啸。\n\n陌上风光日日新，半随流水半浮尘。诗家自有奇招在，满插瓶花截住春。\n\n竹杖芒鞋风貌古，终朝乐与民为伍。偶踏杨花过谢桥，惊起沙鸥前后舞。\n\n紫金山畔竹梧青，有凤来仪展素翎。自向莲台宣佛号，清吟不许俗人听。\n\n贺兰山畔逢初雪，一派天声梨蕊裂。信手裁成大气诗，风华何用人称绝？\n\n宝瑟和谐璧影沉，绕梁三日有余音。把书深柳堂前读，如此风光最赏心。\n\n青山横断东西陌，酒量诗才俱不恶。几时碰破壁重重，露出全新天一角？\n\n少年才俊更何人，瓶里青梅瘦入神。点将骚坛风起浪，每从谐谑见天真。\n\n奇观每伴行舟走，神女峰边蓦回首。何处清光醉煞人，一团月落三江口。\n\n十里烟霞隔水村，杏帘遥望亦消魂。何时得与清风接，肝胆论文共酒樽？\n\n篁筠久作巢湖隐，遮莫根前初抱笋？何当再效石风堂，凭虚各把清觞引。\n\n我兽今朝食肉无，朔风吹雪片帆孤。尘封旧事休翻起，生怕凭空累酒壶。\n\n江南雨后山河丽，画到传神多写意。眉眼盈盈向我舒，霎时如坐春风里。\n\n吴郎妙手善调筝，源出潮州韵最清。自抱平常心一颗，也无风雨也无晴。\n\n吾家有子初擎斧，网上裁诗不辞苦。偶从天外试高飞，风光差似神舟五。\n\n桃李新开第几枝，圣贤之道有张弛。溪云自是怜风雅，笼住春光也未知。\n\n静玄老道音违久，或去陶门种杨柳？杨柳新垂万绺丝，丝丝都挽朋侪手。\n\n绝代箫韶有异音，旧三轮上发长吟。人间已不分清浊，独挽天河自沐心。\n\n寒山晓听吹清角，冷沁心脾殊未觉。真言尽向酒前倾，平日台词俱省却。\n\n有子新从塞上归，白衣犹带杏花飞。门墙不待重开启，先放春光到外围。\n\n一自仙翁乘去鹤，吟坛几度伤寥落。布衣捧剑楚山来，复起春风同乐乐。\n\n云外传声不惮劳，五更催客月轮高。如今正果修成也，脱尽鸡毛换凤毛。\n\n度尽洪荒人不识，寒林四顾烟如织。补天功就自安闲，长羡山中老顽石。\n\n山郭晴晖向晓开，莫教孤负十分才。朵云红白连环出，天放奇花不用栽。\n\n骚坛亦有杨家将，接力途中扛大棒。活法遥承乃祖来，入时能画新眉样。\n\n消息年来两未知，满山风露忆军持。夜阑置酒松窗下，细读先生不死诗。\n\n剪剪春风添烂漫，兰舟划出垂杨岸。凌波抖落隔年霜，依旧身心如菊淡。\n\n盐车高负日迟迟，古道西风瘦马嘶。伯乐至今犹醉卧，此声听到是何时？\n\n网坛博得人称许，惊世才华天赐与。不信神通孟老邪，居然有此玲珑女。\n\n坐对千年一局残，老僧应已破禅关。城南如月之秋夜，细听清风响佩环。\n\n岁寒枝上同摇曳，逊白输香真浪说。渺渺予怀几个知，算来只有梅关雪。\n\n扫径思迎二客临，天山约罢约闲吟。隔篱依旧邻翁健，浊酒犹能试一斟。\n\n长启西南轩一角，略分濠上游鱼乐。天下横流水几何，冠缨只用沧浪濯。\n\n笔下诗翻旧体新，庆霖豪气逼前人。春来信有于蓝出，先置樽罍到水滨。\n\n网游时与高人会，家酿长思谋一醉。又到江南欲雪天，不知阿二归来未？\n\n几年游屐遍东南，何幸新知有大凡。解道相逢便金石，天光云影一湖涵。\n\n吟坛旧雨连新雨，结个忘年天或许。乖巧林中曲曲溪，娱人只作和谐语。\n\n打从持棒到天堂，百事都由自主张。食尽蟠桃花又着，四时春色属猴王。\n\n凭栏四望皆芜草，浅褐深黄俱了了。蓦见松花一叶开，生机在眼休云少。\n\n雪与梅花次第临，村醪待客敢偏心？送伊归得天山去，一半为君醒后吟。\n\n赏罢银蟾秋已半，青山欲把衣衫换。古松留住涧边云，好续坐看缘一段。\n\n不是橱窗塑料花，溪头小草活生涯。若嫌官样文章累，无事多来听咂吧。\n\n何处莲花清若许，风吹仙袂飘飘举。双舟并桨出烟波，想是龙宫初嫁女。\n\n极天南北任穿梭，应是诗多偈也多。我愧学禅无一得，佛前初解念弥陀。\n\n风骚早与神仙各，万里晴空秋一鹤。不受人间宰相招，孤飞自得怡然乐。\n\n斗牛光焰若鸣雷，又向空山舞一回。如此锋芒如此气，几时交付与钟馗？\n\n柳叶舒眉娇正舞，桃花脸晕芳初吐。伊谁约得美人来，先是春风后春雨。\n\n网上谭诗万象和，闲中岁月漫消磨。不愁抗手无寻处，斋主清才个个多。\n\n自家摇曳凌虚绿，不管陈平分社肉。偶听风传一笛清，果然神韵超凡俗。\n\n神舟消息有花边：曾到银河觅胜缘。织女牛郎都不问，只同天马结忘年。\n\n剪剪清风独来往，柳村故旧年年访。溪边偶尔一回头，惹起杨花生异想。\n\n岂为交情掩异同，延陵犹见旧家风。不嫌广告词繁琐，也并英雄到局中。\n\n伊家屋傍松篁结，溪有游鳞山有蕨。锄罢梅花鸟不啼，当头一片秦时月。\n\n网上风光面目奇，千峰万壑转迷离。私家马甲知多少，谁似先生自在披？\n\n应是庐山缘未了，梦中犹作松边倒。陶家借得酒壶来，便向鄱湖寻野老。\n\n苏辛李杜不同来，分付园花省着开。天气渐寒心渐暖，菊斋留韵到梅斋。\n\n开过红桃开白李，家家都在春声里。衔泥燕子故飞飞，来慰高楼人独倚。\n\n漫道诗花水岸多，远寻荒漠又如何？黄沙万里添生趣，红柳丛中卧骆驼。\n\n守过千年情入骨，天河又见风吹筏。嫦娥有约不曾来，高卧云头遥梦月。\n\n高山流水不须琴，少悟因缘亦畅心。诗履正思随老杜，未期筇杖已先临。\n\n先生家住深山里，日踏青苍行不止。一个诗仙也未逢，还期遍发桃花水。\n\n柴门无事不常开，难得当年小杜来。早识白鸥湖上意，也应杨柳及时栽。\n\n写罢芜词还自笑：春迟娇懒凭谁报？小梅窗下月溶溶，疏影一天和梦到。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '网坛岁杪漫怀' AND p.poem_author = '熊东遨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('零口早行', '刘昂', '金朝', '马上兀残梦，沉沉天向晨。行云如妒月，古道不逢人。\n\n野旷耕声远，山高露气新。哦诗无好语，聊尔一吟呻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '零口早行' AND p.poem_author = '刘昂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭江进之 其六', '袁宏道', '明代', '好手经炉冶，匡时正老成。文通才未尽，元静职犹轻。\n\n妖作长沙鵩，帐空澧水萤。花源留迹处，莎草背阶生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭江进之 其六' AND p.poem_author = '袁宏道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('草堂落成漫志近况 其三', '李之世', '明代', '屋角平行亦碍眉，巡檐刚觉帽儿欹。童閒洗药晒书后，客韵香恬熟茗时。\n\n花瘦篱头酣不醒，竹荒墙角俗难医。何如刬却前阶草，一味清虚也亦宜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '草堂落成漫志近况 其三' AND p.poem_author = '李之世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寒食 其四', '吕本中', '宋代', '病夫只欲闭柴荆，客至从嗔不出迎。未恨家贫无历日，紫桐花发即清明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寒食 其四' AND p.poem_author = '吕本中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南粤辞 其五', '屈大均', '明代', '足下中国人，今乃反天性。皇帝与抗衡，祸且及真定。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南粤辞 其五' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送同年崔先辈', '许浑', '唐代', '西风帆势轻，南浦遍离情。菊艳含秋水，荷花递雨声。 \n 扣舷滩鸟没，移棹草虫鸣。更忆前年别，槐花满凤城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送同年崔先辈' AND p.poem_author = '许浑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄吴宪之侍御 其一', '庄昶', '明代', '玉节留诗老树滩，可能还忆钓鱼竿。相看云水无三舍，不寄梅花又两寒。\n\n醉枕柳根容我睡，谏书天下为公看。相思欲采芙蓉寄，只恐江深水冷难。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄吴宪之侍御 其一' AND p.poem_author = '庄昶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('云峰雅兴', '叶颙', '元代', '高卧碧云岑，清谈翠竹林。疏狂交牧圉，勋业谢冠簪。\n\n江月清吟腑，松风醒醉心。焦桐弦久绝，三弄发奇音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '云峰雅兴' AND p.poem_author = '叶颙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏黄门摄县以纂志见邀局中答梁彦国邓毓元二子', '欧大任', '明代', '偶来讲肆暂盘桓，祖谢同游自鹖冠。窗外竹声凭槛听，雨中山色隔城看。\n\n娇莺乍啭衣将换，新火初分食尚寒。自笑校书非寓直，花期犹阻故人欢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏黄门摄县以纂志见邀局中答梁彦国邓毓元二子' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('角', '黄衷', '明代', '哀角因风听，天东月晕生。遥闻鬼方寇，近合水西兵。\n\n缟练征人妇，青灯独夜情。此中多苦调，休弄早秋声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '角' AND p.poem_author = '黄衷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉京秋 湖上看桂', '阮恩滦', '清代', '烟水远。凉飙动群木，桂花初绽。低云密护，颓阳微渲。\n\n浅碧深香相半。最留人、风送香暖。凝眸看。几枝斜倚，小山亭畔。\n\n林外残霞催晚。喜馀芬、常留仙馆。瑶砌珠尘，画栏金粟，十分秋满。\n\n试问天台，料万树、应亦同时开遍。漫飘散。为惜芳华太短。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉京秋 湖上看桂' AND p.poem_author = '阮恩滦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('并蒂芙蓉 题蒋南沙相国画并蒂莲花', '顾太清', '清代', '水净风疏，照碧天倒影，花间无暑。清露洗红妆，爱金蕊交错。\n\n同心并头两朵，洛浦凌波笑相与。结成伴侣，惜双双、占断风流娇妩。\n\n渺渺曲塘落日，问何来小鸟，双栖双伫。不肯画鸳鸯，怕花里耽误。\n\n莲花自然洁净，那管根芽淤泥污。这般态度。愿生生、总开一处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '并蒂芙蓉 题蒋南沙相国画并蒂莲花' AND p.poem_author = '顾太清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渎流', '张问陶', '清代', '卧听海客说瀛洲，今日抽帆下渎流。浊水一湾村市冷，神鸦千点庙门秋。\n\n支离欲蓄三年艾，浩荡谁驯万里鸥。此去蓬山应不远，只愁风力引飞舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渎流' AND p.poem_author = '张问陶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('红楼梦曲', '曹雪芹', '清代', '一帆风雨路三千，\n把骨肉家园齐来抛闪。\n恐哭损残年，\n告爹娘，\n休把儿悬念。\n自古穷通皆有定，\n离合岂无缘？\n从今分两地，\n各自保平安。\n奴去也，莫牵连。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '红楼梦曲' AND p.poem_author = '曹雪芹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风云交作戏题', '陆游', '宋代', '霎脚如龙爪，空中挟雨来。\n何关风伯事，欲到却吹回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风云交作戏题' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('朱鹭', '王僧孺', '南北朝', '因风弄玉水，映日上金堤。犹持畏罗缴，未得异凫鹥。\n\n闻君爱白雉，兼因重碧鸡。未能声似凤，聊变色如圭。\n\n愿识昆明路，乘流饮复栖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '朱鹭' AND p.poem_author = '王僧孺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沪上逢几道有诗酬之', '陈宝琛', '清代', '桑田三变休龙斗，海上连宵重说诗。此事可怜成古调，馀生相对看枯棋。\n\n村夫食粟能无健？世路回车又有歧。岁晚卖文充市隐，水乡丹橘问归期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沪上逢几道有诗酬之' AND p.poem_author = '陈宝琛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十六夜祖董生北行', '黄甲', '宋代', '江南今夕月，清光犹似昨。\n君行背雁飞，明日堪谁酌。\n孤情月正中，照汝颜如削。\n愿君霜树年，遗风远摧薄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十六夜祖董生北行' AND p.poem_author = '黄甲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('承光殿三首 其三', '弘历', '清代', '遗迹金元一慨然，踞盘形胜揽全燕。空澄何似瀛池水，玉蝀秋风五百年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '承光殿三首 其三' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送友人南旋', '袁鹏图', '清代', '欻然声价出江东，力守经师继汉风。香国奇才如子少，天涯涕泪几人同。\n\n自惭待诏金门侧，常共深谈漆室中。朝野恬熙吾辈老，凭谁上策定和戎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送友人南旋' AND p.poem_author = '袁鹏图';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('景安和章来再次韵谢设醴四首', '陈造', '宋代', '拜赐清诗醒醉昏，恍如帝所听新翻。\n君才炙輠无穷尽，未敢先关月下门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '景安和章来再次韵谢设醴四首' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('唐彦猷谈奉得达二帖赞', '岳珂', '宋代', '公于国史，以好砚称。\n石焉取斯，盖协其能。\n遒媚之观，在此尺纸。\n善工利器，予鉴如此。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '唐彦猷谈奉得达二帖赞' AND p.poem_author = '岳珂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百六十首 其八十九', '释宗杲', '宋代', '善法堂前瑞气新，天书来自九重城。唯凭一句无私语，上祝吾皇亿万春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百六十首 其八十九' AND p.poem_author = '释宗杲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('云鬓', '王偁', '未知', '香鬟三尺绾芙蓉，翠耸巫山雨后峰。\n斜倚玉床春色去，鸦翎蝉翼半蓬松。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '云鬓' AND p.poem_author = '王偁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天长道中', '孔平仲', '宋代', '柔桑满野麦成川，晴色连陂雨在田。顾影寂寥谁与语，据鞍閒暇不妨眠。\n\n尘劳可厌非今日，老大无堪异昔年。此去聊为上都客，行当货马觅归船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天长道中' AND p.poem_author = '孔平仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元宵中都太守放灯作律诗五首 其三', '郑真', '明代', '北极中天正斗杓，风流人物共今宵。当楼绮彩丹心结，隔幔琉璃翠影摇。\n\n龙驾共瞻宸阙近，鳌山慢忆海天遥。凭谁记得云中曲，来向人间叶凤韶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元宵中都太守放灯作律诗五首 其三' AND p.poem_author = '郑真';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三月三日龙门舟次', '郭之奇', '明代', '三月三日春气足，春浮海外无拘束。千舻百苇载春流，春山春水为谁绿。\n\n自居涯角四经春，满怀春事畴堪属。清明上巳漫从时，洗旧淘新未免俗。\n\n无花无酒对烟风，远望高歌尽一曲。岂知歌尽出春愁，一寸柔肠春断续。\n\n春初春仲又春三，九十春光如转烛。春光于世独何求，久客依人多忤触。\n\n人生有情空自毒。春去春回那可赎。我亦欲东与春归，安能居此为春促。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三月三日龙门舟次' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮 其十七', '张孝祥', '宋代', '冥濛秋夕漙清露。玉绳耿耿银潢注。永夜滴铜壶。月华楼影孤。\n\n佳人纡绝唱。翠幕丛霄上。休劝玉东西。乌鸦枝上啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮 其十七' AND p.poem_author = '张孝祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和令狐仆射小饮听阮咸', '白居易', '唐代', '掩抑复凄清，非琴不是筝。还弹乐府曲，别占阮家名。 \n 古调何人识，初闻满座惊。落盘珠历历，摇珮玉琤琤. \n 似劝杯中物，如含林下情。时移音律改，岂是昔时声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和令狐仆射小饮听阮咸' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雁影', '盛镛', '明代', '似有疑无认未真，月明紫塞倍精神。三秋写照空中现，万里随行分外亲。\n\n荻渚烟销怜一片，湘江浪静印全身。穿云何处留痕迹，惆怅挥弦目送人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雁影' AND p.poem_author = '盛镛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与诸昆季言怀 其一', '孙元衡', '清代', '骐骥仰天鸣，朽索驭刚铁。一驱升崇山，焉知踬于垤。\n\n脂牵转回肠，孰与较优劣？才老力可尽，名成待九折。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与诸昆季言怀 其一' AND p.poem_author = '孙元衡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('武夷曲次晦翁棹歌（二首）', '郑善夫', '明代', '幔亭彩幄会仙灵，紫雾蒙蒙薄太清。\n奏罢人间可哀曲，凤笙龙管杳无声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '武夷曲次晦翁棹歌（二首）' AND p.poem_author = '郑善夫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登岳麓赫曦台联句', '朱熹', '宋代', '泛舟长沙渚，振策湘山岑。烟云眇变化，宇宙穷高深。\n\n怀古壮士志，忧时君子心。寄言尘中客，莽苍谁能寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登岳麓赫曦台联句' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨', '黄浚', '近代', '秋林渐绛病方残，一雨平添小榻寒。可惜更无閒客过，清诗吟与阿谁看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨' AND p.poem_author = '黄浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宋。羊玄保', '孙元晏', '唐代', '运命将来各有期，好官才阙即思之。 \n 就中堪爱羊玄保，偏受君王分外知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宋。羊玄保' AND p.poem_author = '孙元晏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饮建昌山亭寻先题亦潇洒楼遗址，敬次原韵', '许传霈', '清代', '山色盘苍郁，奔赴严子江。建昌勒其下，江涛气势降。\n\n独宏保障功，合住神仙宅。烟雨护林峦，蛟龙潜波泽。\n\n我来九秋节，萧瑟物尽搜。狂飙面疾割，小月斧初修。\n\n酌酒暮山头，山行何朗朗。吟啸当危栏，万山音环向。\n\n作赋悲王粲，落帽笑孟嘉。零落有时至，所惜在朝华。\n\n遗址寻岩阿，真情起林表。犹是好江山，那不乐鱼鸟。\n\n望云亲不见，卅载系我思。思之不可得，恐为猿鹤嗤。\n\n舟帆江水流，云雾峰头逐。时乎不再来，宝剑长鸣椟。\n\n会出造楼手，潇洒见旧胸。先贤与先泽，我自得所从。\n\n好句留性天，慎勿戕柳杞。把盏竹翠间，敲棋松阴里。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饮建昌山亭寻先题亦潇洒楼遗址，敬次原韵' AND p.poem_author = '许传霈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('法华院僧祖月写余真戏赞', '周必大', '宋代', '老子七十七，到处遮人壁。\n住世更十年，化身千百亿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '法华院僧祖月写余真戏赞' AND p.poem_author = '周必大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏金陵曲中遗事 其一', '屈大均', '明代', '国初南院首皇州，官妓居连十四楼。手帕结成多姊妹，春盘笑为赏灯留。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏金陵曲中遗事 其一' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题画送韩御史旸归省 其一', '杨士奇', '明代', '秦望山清近若耶，纷纷云树映溪沙。数椽茅屋无尘杂，知是安阳御史家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题画送韩御史旸归省 其一' AND p.poem_author = '杨士奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('萤二首', '罗邺', '唐代', '水殿清风玉户开，飞光千点去还来。 \n 无风无月长门夜，偏到阶前点绿苔。 \n 裴回无烛冷无烟，秋径莎庭入夜天。 \n 休向书窗来照字，近来红蜡满歌筵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '萤二首' AND p.poem_author = '罗邺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居 其六', '淳藏主', '宋代', '瓦炉爇处清烟霭，铁磬敲时晓韵寒。一穿数珠粗又重，拈来百八不相谩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居 其六' AND p.poem_author = '淳藏主';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王侍读挽辞二首 其一', '韩维', '宋代', '旧族人犹凤，清班署冠鳌。法书传隶古，才笔拟庄骚。\n\n赠印官称宠，题旌谥典高。无由攀葬绋，伫立望行艘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王侍读挽辞二首 其一' AND p.poem_author = '韩维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠永嘉高生', '郑元祐', '元代', '高生永嘉秀，秀也实南金。学启麟经秘，雏生凤穴深。\n\n浪花迎客棹，霜叶变枫林。异日巍科掇，秋期又盍簪？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠永嘉高生' AND p.poem_author = '郑元祐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送黄隐君南归', '谢榛', '明代', '黄生久不见，一见即言归。落叶世情薄，浮云生事微。\n\n潮声随晚棹，江色照寒衣。还醉莆中酒，春风自掩扉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送黄隐君南归' AND p.poem_author = '谢榛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郡斋水阁闲书', '文同', '宋代', '衰后常亲药饵，忧来颇忆林泉。身坐谢庄小阁，心游沈约东田。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郡斋水阁闲书' AND p.poem_author = '文同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长沙行送胡子', '皇甫汸', '明代', '贾生昔被长沙谪，湘水千年动颜色。吊古空劳忆芷兰，世途久已生荆棘。\n\n当今天子称圣君，论恩岂复如汉文。垂裳穆穆日南向，锐情稽古非谦让。\n\n直气常悬青琐间，愁云更郁乌台上。胡郎胸中书万言，夕方拜官朝叩阍。\n\n刘向况有五行传，挺身悟主争绳愆。即今亦有长沙行，此去应知圣主情。\n\n早晚定膺宣室召，肯使人徒说贾生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长沙行送胡子' AND p.poem_author = '皇甫汸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戊申春雨书寓所壁', '顾清', '明代', '去年秋旱深忧稼，今岁春霖复损苗。圣主不应天有谴，清时宁许物为妖。\n\n浸淫便恐鱼生釜，漂泊谁将蚁渡桥。江上舍前泥一尺，掩书终夕听飘萧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戊申春雨书寓所壁' AND p.poem_author = '顾清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古十九首', '释慧晖', '宋代', '故山岌岌锁寒烟，未肯将心轻授传。\n玉女夜寻无字印，石人遥指月明前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古十九首' AND p.poem_author = '释慧晖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄孙三庐江', '程嘉燧', '明代', '自从君去少经过，霖雨柴门有啸歌。\n怀袖尺书三岁在，江关萧瑟暮年多。\n过淮落木空明月，到海青山祇白波。\n闻道儿郎转聪慧，比来樽酒兴如何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄孙三庐江' AND p.poem_author = '程嘉燧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵陈使君咏霰雪三首 其一', '洪刍', '宋代', '天幕垂云合，山屏拥雪飞。杨公田种玉，渊客泪成玑。\n\n点缀添梅萼，飘零乱羽衣。清溪横一叶，并载月明归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵陈使君咏霰雪三首 其一' AND p.poem_author = '洪刍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日杂咏十首 其九', '李光', '宋代', '天南谁把尺书传，老眼经秋自不眠。鼓角声回窗未掩，可堪残月到床前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日杂咏十首 其九' AND p.poem_author = '李光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('彭琦初用坡翁纸帐韵惠建昌纸衾次韵一首为谢 其一', '刘诜', '元代', '雪绵揉碎密萦连，清卧梅花性更便。茸暖何须蛮客帐，座寒但少广文毡。\n\n窗升红日那知晓，梦压白云疑近天。但恐少陵茅屋漏，雨宵沾破不成眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '彭琦初用坡翁纸帐韵惠建昌纸衾次韵一首为谢 其一' AND p.poem_author = '刘诜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风瑟联句', '谢绛', '宋代', '窃竹漏天风，张弦拟峄桐。\n佳名從此得，妙响未曾穷。\n夜静危台上，人闲皎月中。\n依依听不足，秋露满兰丛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风瑟联句' AND p.poem_author = '谢绛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟中', '许邦才', '明代', '客子常明发，霜天正寂寥。\n移舟星在水，解缆月随潮。\n往事流波驶，归心帆影摇。\n更堪闻过雁，芦荻共萧萧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟中' AND p.poem_author = '许邦才';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('走笔戏赠张文鼎墨梅', '唐桂芳', '元代', '梅花不是人间白，画工休污琼粉色。淡墨疏疏浅著烟，一枝蘸出临溪月。\n\n张君好画本诗人，吟魂写影俱逼真。从此玉妃归不得，满纸占断罗浮云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '走笔戏赠张文鼎墨梅' AND p.poem_author = '唐桂芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岭外怀宣城旧游', '吕本中', '宋代', '中原未敢说归期，却忆宣城近别离。叠嶂雨来如画里，敬亭秋入胜花时。\n\n每憎卑湿尤多病，苦爱风光屡有诗。今日衰颓那可说，鬓须经瘴总成丝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岭外怀宣城旧游' AND p.poem_author = '吕本中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝙蝠洞', '倪梦龙', '宋代', '悬崖多蝙蝠，往往寿千年。\n自古人难到，如今尔得先。\n所餐崖上乳，不出翁中天。\n自有攀援者，曾看抱扑篇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝙蝠洞' AND p.poem_author = '倪梦龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('老去', '倪钅巨', '明代', '老去花能遣，愁来酒易亲。\n青苔生户牖，白石冷荆榛。\n总有生平好，谁怜旦暮人。\n樵苏聊自爨，稚子学供薪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '老去' AND p.poem_author = '倪钅巨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与赵道人', '王炎', '宋代', '欲上青云却垂翅，归来扫轨空山里。\n道人说相来叩关，酒半醺酣谈亹亹。\n我今布褐终余年，岂论燕颔并鸢肩。\n谓予形是朱顶鹤，两眼藏神高颊颧。\n彭殇寿夭谁无死，不将动目摇湛水。\n道人去后若复来，定应难相壶邱子。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与赵道人' AND p.poem_author = '王炎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('充叟九兄以书问鄱阳官况因亦问讯', '毛滂', '宋代', '信来频慰别离魂，苦问官情却懒言。\n多睡正随蝴蝶梦，相怜空愧鹡鴒原。\n幸无俗客干书户，遥想青山对县门。\n定是放衙能少事，悠哉岸帻步槐根。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '充叟九兄以书问鄱阳官况因亦问讯' AND p.poem_author = '毛滂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绍兴癸丑上巳日', '曹勋', '宋代', '连岁羌酋不荷戈，今年禊饮喜如何。中兴乐事虽无象，甲子先同晋永和。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绍兴癸丑上巳日' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏怀诗五首 其一', '支遁', '魏晋', '傲兀乘尸素，日往复月旋。弱丧困风波，流浪逐物迁。\n\n中路高韵益，窈窕钦重玄。重玄在何许，采真游理间。\n\n苟简为我养，逍遥使我闲。寥亮心神莹，含虚映自然。\n\n亹亹沈情去，彩彩冲怀鲜。踟蹰观象物，未始见牛全。\n\n毛鳞有所贵，所贵在忘筌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏怀诗五首 其一' AND p.poem_author = '支遁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杨六郎庙', '尹耕', '明代', '尚有杨郎庙，其如宋祚何。\n伤心空战伐，极目且山河。\n云鸟人能说，腥膻恨不磨。\n除凶昭代烈，应慰九原多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杨六郎庙' AND p.poem_author = '尹耕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮七首 其六', '丁宁', '近代', '芙蓉两两胭脂涴。西风一夕临青琐。和泪别瑶京。太华残月明。\n\n岭云三十六。日暮迷金屋。何处问飞鸾。蘅芜澈梦寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮七首 其六' AND p.poem_author = '丁宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('摸鱼儿', '龙榆生', '近代', '尽无言、暗香徐度，缘何清瘦如许。一枝萧洒春仍在，伴我几番朝暮。\n\n情自苦。但溉汝寒泉，灯影聊相煦。际天风露。便滋润无缘，伶俜长忍，意象自轩举。\n\n君试觑。点点丹诚倾注。孤怀脉脉谁语。荒山弃置寻常事，难忘移根前度。\n\n须记取。叹极意壅培，未是芳期误。流光好驻。爱丽日辉辉，奋飞生翼，重与展衷素。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '摸鱼儿' AND p.poem_author = '龙榆生';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洛阳道', '朱诚泳', '明代', '纵横洛阳道，来往觅行踪。宫车若流水，仗马似游龙。\n\n戚里传灯火，侯门闻鼓钟。何因人掷果，应为美姿容。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洛阳道' AND p.poem_author = '朱诚泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郑梦周死节诗 其一', '南衮', '明代', '丽季衰微泰运升，群贤攀附总飞腾。从容就死乌川子，启我朝鲜节义兴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郑梦周死节诗 其一' AND p.poem_author = '南衮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答董子元太学', '皇甫汸', '明代', '山居寂寞谁相问，海内交游半不通。双鲤将心传夜月，一帷垂老闭春风。\n\n新城闻鹤因兵后，往事看花若梦中。情忝通家生校晚，思君惜未见嵇公。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答董子元太学' AND p.poem_author = '皇甫汸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠郑少尹', '边贡', '明代', '我正雪中卧，君从天上还。节高元自苦，才大可能閒。\n\n淅沥听疏竹，苍茫对远山。夜深拚一醉，休当剡溪湾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠郑少尹' AND p.poem_author = '边贡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渡鄱阳', '严遂成', '清代', '烟与水无际，迷茫小洞庭。\n潮回三楚白，山压五湖青。\n苇折雁声苦，风多鱼气腥。\n扬舲一极目，何处吊湘灵？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渡鄱阳' AND p.poem_author = '严遂成';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('刘汉臣堂甫北归', '李俊民', '金朝', '哀哉同队鱼，尽在枯池里。纵免鼎中烹，将见渴欲死。\n\n造物何不仁，岂独困二子。我虽江湖心，恨无斗升水。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '刘汉臣堂甫北归' AND p.poem_author = '李俊民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登清凉寺后西塞山亭四首 其四', '顾璘', '明代', '剑化人亡有故城，东来海气带龙腥。烟花楼阁三千界，锦绣河山百二形。\n\n老托神京堪自隐，醉眠秋涧不知醒。长江只在朱阑外，莫遣哀歌动杳冥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登清凉寺后西塞山亭四首 其四' AND p.poem_author = '顾璘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三印颂示众', '释正觉', '宋代', '印泥印空印水，疾轩不及掩耳。\n豁然楼阁门开，消得轻轻弹指。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三印颂示众' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵和王巩六首', '苏轼', '宋代', '欲结千年实，先摧二月花。\n故教穷到骨，要使寿无涯。\n久已逃天网，何而服日华。\n宾州在何处，为子上栖霞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵和王巩六首' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五言', '朱敦儒', '宋代', '天寒犹著絮，雨湿欲蒸书。吴地人情薄，西人客计疏。\n\n无书堪著眼，有法可安心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五言' AND p.poem_author = '朱敦儒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蜡除诗', '张望', '魏晋', '玄灵告稔谢，青龙驾拂轸。鲜冰迎流结，凝留垂檐霣。\n\n人欣八蜡畅，讵知岁聿尽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蜡除诗' AND p.poem_author = '张望';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋懹', '陆游', '宋代', '昨者风雨过，浩然天地秋。\n年光双雪鬓，生计一渔舟。\n卖药来查浦，听猿到沃洲。\n平生畏暑毒，八月记初游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋懹' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦行西湖梅花下 其二', '周紫芝', '宋代', '春云收尽忽斜阳，梦里梅花带雨香。却上小舟谁是伴，回头只有棹船郎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梦行西湖梅花下 其二' AND p.poem_author = '周紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿黄兴岐', '成鹫', '明代', '先生先子之所畏，忆我为儿始七岁。大人抱我置左膝，隔坐与君论文字。\n\n我时仅识之与无，侧耳静听无欢呼。上客骐驎笑相许，岂知长大成蹇驴。\n\n蹇驴畏走三城道，踯躅秋风啮秋草。故人相见惊相识，我渐就衰君已老。\n\n我衰不足惜，君老头还黑。交游半作乘车人，诸生尽是文章伯。\n\n先生两眼大如箕，世上红尘污不得。一日读书能几回，山中甲子去复来。\n\n诗书之外何有哉，眼前穷达皆尘埃。青兕爵，丹砂杯，为君寿，酌君醅。\n\n饮此不得老，日月重皑皑。海水浅，河水清，美人更筑黄金台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿黄兴岐' AND p.poem_author = '成鹫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南歌子', '石孝友', '宋代', '畴昔飞鸾侣，而今断雁行。西风岭外下斜阳。无赖一钩新月、挂人肠。 \n 双泪沾襟袖，孤灯封客床。枕余衾剩只残香。别得娇痴不睡、也思量。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南歌子' AND p.poem_author = '石孝友';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚晴', '杜甫', '唐代', '高唐暮冬雪壮哉，旧瘴无复似尘埃。崖沉谷没白皑皑， \n 江石缺裂青枫摧。南天三旬苦雾开，赤日照耀从西来， \n 六龙寒急光裴回。照我衰颜忽落地，口虽吟咏心中哀。 \n 未怪及时少年子，扬眉结义黄金台。洎乎吾生何飘零， \n 支离委绝同死灰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚晴' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重游吴哥窟', '姚佳', '当代', '枯腾老树碧周遮，上座飞仙去路赊。神庙园林独角兽，梵天风雨七头蛇。\n\n桑香佛舍春犹远，红色高棉日又斜。安得大鹏金翅鸟，瀛涯胜览接星槎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重游吴哥窟' AND p.poem_author = '姚佳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过陈氏园亭', '郭廑', '明代', '高士园林好，岩扉昼不扃。绝胜陶令巷，犹是子云亭。\n\n幔卷飞泉白，窗含远岫青。何时出尘想，来此共谈经。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过陈氏园亭' AND p.poem_author = '郭廑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题赵漕小蓬莱 其二', '方岳', '宋代', '老夫曾到道家山，太乙青藜夜叩关。著作承明今付子，仙壶元不隔人间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题赵漕小蓬莱 其二' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题敦煌县署七年四至之堂', '苏履吉', '清代', '七年四至此名堂，坐对斯民信悚煌。不改书生真面目，犹怀慈母旧心肠。\n\n儿童渐忘春增长，父老相看岁健康。愧我去来踪靡定，漫言五载报循良。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题敦煌县署七年四至之堂' AND p.poem_author = '苏履吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜起对月', '田登', '明代', '良宵耿不寐，皓魄烂华埏。夜气湛以肃，良理复其天。\n\n神鱼戢比鳞，扬鬐逝故渊。倦鸟惜翮翎，瞻巢愤翩跹。\n\n物性岂凿意，生遂悉其然。饶饶千金子，堂垂灶突烟。\n\n狎客坐羽觞，鼓吹滋华年。一朝延比邻，捐崩更播迁。\n\n执守宜中人，况复非圣贤。如有汶上召，为我谢迂愆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜起对月' AND p.poem_author = '田登';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次郑好义见贻韵 其二', '方孝孺', '明代', '赤骥困皂枥，垂头避驽骀。王良振长辔，蹴踏风云开。\n\n古来功名际，何代无奇才。当其未遇时，谁免蒙尘埃。\n\n丈夫亮有命，勿使心颜颓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次郑好义见贻韵 其二' AND p.poem_author = '方孝孺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人 泊京口有寄', '曹溶', '明代', '故园寒食看花客，眠尽云帆窄。王郎难信不风流，惯学吹箫弄酒石城游。\n\n南朝一抹沈烟雾，唤作销魂路。别来相寄彩笺频，纵使春山无恙也愁人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人 泊京口有寄' AND p.poem_author = '曹溶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠萧兵曹先辈', '许浑', '唐代', '广陵堤上昔离居，帆转潇湘万里馀。楚客病时无鵩鸟， \n 越乡归处有鲈鱼。潮生水郭蒹葭响，雨过山城橘柚疏。 \n 闻说携琴兼载酒，邑人争识马相如。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠萧兵曹先辈' AND p.poem_author = '许浑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅岭 其二', '谢锡朋', '清代', '惯将双屐作生涯，浅水疏篱小住家。自笑得居香雪里，读书倦后便看花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅岭 其二' AND p.poem_author = '谢锡朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东坡三绝句', '苏籀', '宋代', '为文赤壁并黄坂，奇韵平生想像中。\n延目练江咨逝水，举头碧落看飞鸿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东坡三绝句' AND p.poem_author = '苏籀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄题石湖先生范至能参政石湖精舍二首 其一', '杨万里', '宋代', '万顷平湖石琢成，尚存越垒对吴城。如何豪杰干戈地，却入先生杖屦声。\n\n古往今来真一梦，湖光月色自双清。东风不解谈兴废，只有年年春草生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄题石湖先生范至能参政石湖精舍二首 其一' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜雪 其一', '许及之', '宋代', '静听微雨落乾声，晓见平檐粉似匀。去岁鸳鸯何苦热，今朝鸥鹭太无尘。\n\n眼空色界聊矜富，酒极诗豪自觉神。踏碎琼瑶无过棹，虚教新酿熟经旬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜雪 其一' AND p.poem_author = '许及之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏五黄元卿招同韩孟郁邓伯乔赵裕子饮渌水草堂', '韩日缵', '明代', '径辟炎氛隔，亭馀水木清。求羊宁我辈，浮蚁为君倾。\n\n倒景千林出，迎风一榻轻。须拚十日饮，才惬数年情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏五黄元卿招同韩孟郁邓伯乔赵裕子饮渌水草堂' AND p.poem_author = '韩日缵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感时', '白居易', '唐代', '朝见日上天，暮见日入地。不觉明镜中，忽年三十四。 \n 勿言身未老，冉冉行将至。白发虽未生，朱颜已先悴。 \n 人生讵几何，在世犹如寄。虽有七十期，十人无一二。 \n 今我犹未悟，往往不适意。胡为方寸间，不贮浩然气。 \n 贫贱非不恶，道在何足避。富贵非不爱，时来当自致。 \n 所以达人心，外物不能累。唯当饮美酒，终日陶陶醉。 \n 斯言胜金玉，佩服无失坠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感时' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词', '李衍', '唐代', '辉辉赫赫浮玉云，宣华池上月华新。 \n 月华如水浸宫殿，有酒不醉真痴人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词' AND p.poem_author = '李衍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄题江山叶氏翠香亭', '王柏', '宋代', '谁窃清香下广寒，霜风染就粟肤丹。\n须知叶叶苍圭色，花未开时自可观。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄题江山叶氏翠香亭' AND p.poem_author = '王柏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('减字木兰花 吴昌硕为祖谋画彊村校词图', '朱祖谋', '清代', '金风嫡派。一世词流甘下拜。馀事丹黄。远接虞山近半塘。\n\n故山浮玉。梦里消磨文字福。何日归篷。和尔樵歌一笛风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '减字木兰花 吴昌硕为祖谋画彊村校词图' AND p.poem_author = '朱祖谋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('醉落魄/一斛珠', '管鉴', '宋代', '碧云暮合。不教预赏中秋月。凉生楚观风初歇。山影沈沈，相对两奇绝。湘人怅望黄金节。只愁酒散仙舟发。凭谁为与姮娥说。明夜虽圆，空照人离别。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '醉落魄/一斛珠' AND p.poem_author = '管鉴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏西施', '华镇', '宋代', '浣纱溪上浣纱女，野服山花照寒水。含嚬惨淡不胜愁，犹使东邻骇西里。\n\n山鸟渊鱼无定识，俯见潜逃仰惊起。矜花眷月春复秋，长恐朱颜成暮齿。\n\n君王抡选入吴宫，吴宫寂寞无桃李。芙容一笑君意倾，宰嚭言行子胥死。\n\n姑苏台榭游麋鹿，阖闾城阙生荆杞。蛾眉倩盼应自成，筑宫教习胡能美。\n\n当时掩抑无人顾，今日为君除国耻。君莫怪騄骥盐车弭耳时，谁人不作驽骀比。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏西施' AND p.poem_author = '华镇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('追昔游', '元稹', '唐代', '谢傅堂前音乐和，狗儿吹笛胆娘歌。花园欲盛千场饮， \n 水阁初成百度过。醉摘樱桃投小玉，懒梳丛鬓舞曹婆。 \n 再来门馆唯相吊，风落秋池红叶多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '追昔游' AND p.poem_author = '元稹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('途次见西成有象喜而有作', '弘历', '清代', '暑雨祁寒苦怨咨，金风玉露届秋时。最欣比栉村村象，恰向征途历历知。\n\n场圃却听耞乱响，原田还看柄多遗。岁丰更切乾乾意，肯为从禽志少移。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '途次见西成有象喜而有作' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('用门牌日有好花迎客笑岁篘新酒奉亲叹为韵为', '陈文蔚', '宋代', '地僻广乾坤，身闲多月日。\n耕鉴太古民，天然自淳质。\n未怒泥神仙，阅世自长长。\n日用饮食馀，帝力我何有。\n修竹三径幽，青山四时好。\n何须万间厦，一廛可娱老。\n园柑结新实，篱菊开晚花。\n旋篘瓮头酒，不负老年华。\n田夫与野老，一笑相逢迎。\n只说桑麻事，安知市朝争。\n年年愿今日，有酒可留客。\n虽无珍饲馐，随宜具肴核。\n人言鹤发翁，翻作朱颜少。\n把酒更何辞，一对西风笑。\n环堵一亩宫，中有长生计。\n秋月与春花，今年又明岁。\n年高新可庆，家贫儿包羞。\n今年胜去年，粗有酒新篘。\n岁月绵绵永，福禄日日新。\n天开九龄数，眼见四世人。\n共乐堂上亲，旋约山中友。\n虽是盘无馔，未至樽无酒。\n积善虽人为，康宁荷天宠。\n但懈儒素风，日乏甘旨奉。\n子孙虽未贤，粗肯诗礼亲。\n愿言各努力，忠孝以立身。\n人间无事日，箪瓢亦清欢。\n但愿人今日，时时报平安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '用门牌日有好花迎客笑岁篘新酒奉亲叹为韵为' AND p.poem_author = '陈文蔚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史诗 黄河', '胡曾', '唐代', '博望沈埋不复旋，黄河依旧水茫然。沿流欲共牛郎语，只得灵槎送上天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史诗 黄河' AND p.poem_author = '胡曾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新疆纪事 其二', '刘炳青', '清代', '拼死沙场革裹尸，从军万里滞归期。春风杨柳关西路，秋月琵琶塞上诗。\n\n刁斗夜惊胡骑走，鼓鼙声动楚歌悲。可怜绝域乡音渺，纵博封侯奈别离。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新疆纪事 其二' AND p.poem_author = '刘炳青';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('素梅 四五', '王冕', '元代', '三月春风吹雪消，湖南山色翠如浇。\n一声羌管何人见？无数梅花落野桥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '素梅 四五' AND p.poem_author = '王冕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗九首 其八', '黄淮', '明代', '朋友以义合，在古理则然。信义苟不亏，宜同胶漆坚。\n\n良人与我违，斗杓屡西旋。辞色旷不接，中心常悁悁。\n\n如何反掌间，弃我如蹄筌。醇酒味不薄，春花色易妍。\n\n谁云一丝泪，能令金骨穿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗九首 其八' AND p.poem_author = '黄淮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('催雪', '周之琦', '清代', '帘罨重阴，灯晕半花，密坐贪依屏背。语冷宦心情，竹深门闭。\n\n客似寒鸦瘦影，惯倦羽、相偎银云底。琴边试问，清宵款语，冶游知未。\n\n燕市。十年矣。是几度分襟，几番搴袂。又朔雪，关山岁华如此。\n\n尽觅红螺换酒，酿不到、鳞鳞鸳鸯水。料只有、藤角吟笺，犹认月波题字。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '催雪' AND p.poem_author = '周之琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人·小山戢戢盆池浅', '陈克', '宋代', '小山戢戢盆池浅。芳树阴阴转。红阑干上刺蔷薇。蝴蝶飞来飞去、两三枝。绣裙斜立腰肢困。翠黛萦新恨。风流踪迹使人猜。过了斗鸡时节、合归来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人·小山戢戢盆池浅' AND p.poem_author = '陈克';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂述 其九', '林泳', '宋代', '唐士有非国语，汉人曾反离骚。依本定非笔杰，爱奇自是人豪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂述 其九' AND p.poem_author = '林泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('承知府待制诞生之辰辄广善怀', '陈与义', '宋代', '岁星欲吐芒不开，昴星避次光低佪。麒麟鸑鷟纷夹侍，善怀菩萨当重来。\n\n仙公风流今几岁，再托高门瑞当世。买香趁浴惊众聋，要识此僧今我是。\n\n金粟后身何足言，释迦亲送非虚传。稽首西来大菩萨，住世小劫须千年。\n\n宰官说法聊应会，馀事文章亦三昧。世间底物堪寿公，本自金刚无可坏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '承知府待制诞生之辰辄广善怀' AND p.poem_author = '陈与义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十年1947', '缪钺', '近代', '十年涉世惜知难，一札沈吟慨万端。敢说滋兰花易发，勿忘采药路常寒。\n\n风前拾蕊春犹昨，梦起推枰局已残。他日相逢蓬岛路，沧波回首尽漫漫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十年1947' AND p.poem_author = '缪钺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('敬和老人览镜', '洪咨夔', '宋代', '西谷柴车手自巾，风吹不到庾郎尘。\n回光返照千江月，复命归根一点春。\n永昼同窗陶处士，凉宵专席竹夫人。\n徐公好丑浑休问，认取青铜镜裹真。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '敬和老人览镜' AND p.poem_author = '洪咨夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风流子 倬盦邀集莂圃赏雨中芍药', '郭则沄', '清代', '盈盈红似滴，蝶魂醉、绕遍翠栏干。正玉妃舞歇，画裙慵整，梦欹罗荐，啼损晶盘。\n\n为问怨春春解否，无语亸香鬟。凭赏堕琼，小帘扶起，背怜搓锦，流水催残。\n\n年光梅黄近，钿车断芳事，绮陌阑珊。惆怅凤池曾见，铅泪偷弹。\n\n怕唾壶点碎，雕筵恨别，带围瘦减，珠箔留寒。消受雾边衰眼，重赋愁鸾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风流子 倬盦邀集莂圃赏雨中芍药' AND p.poem_author = '郭则沄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春 金陵凤凰台眺望', '白朴', '元代', '独上遗台，目断清秋，凤兮不还。怅吴宫幽径，埋深花草，晋时高冢，锁尽衣冠。横吹声沉，骑鲸人去，月满空江雁影寒。登临处，且摩挲石刻，徒倚阑干。青天半落三山。更白鹭洲横二水间。问谁能心叱，秋来水静，渐教身似，岭上云间。扰扰人生，纷纷世事，就里原无此二字，兹从丁本补何常不强颜。重回首、怕浮云蔽日，不见长安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春 金陵凤凰台眺望' AND p.poem_author = '白朴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辇下曲一百二首，有序 其八十三', '张昱', '元代', '高昌之神戴羖首，仗剑骑羊气猛烈。十月十三彼国人，萝卜面饼贺神节。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辇下曲一百二首，有序 其八十三' AND p.poem_author = '张昱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉和御制南郊七言六韵诗', '杨亿', '宋代', '洁斋恭己奉苍旻，报本圜坛备物陈。酒缩楚茅三献毕，灰飞嶰管一阳新。\n\n高空瑞气长随辇，永夕清霜暗湿巾。泰畤迎年严汉祀，六宗祈福盛虞禋。\n\n鸿恩涣汗沾穷发，睿藻昭回动紫宸。庶汇熙熙蒙帝力，徒知击壤效尧民。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉和御制南郊七言六韵诗' AND p.poem_author = '杨亿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九日', '翁甫', '宋代', '秋风两度身为客，已见重阳未到家。\n村酒不堪供节事，祗将青眼看黄花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九日' AND p.poem_author = '翁甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大风二首 其一', '赵蕃', '宋代', '杯水得风犹渺然，况兹章贡远连天。一穷坐我靡他问，下水宁闻劳挽牵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大风二首 其一' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('予元丰戊午岁自楚至宋由柘城至福昌年二十有五后十年当元祐二年再过宋都追感存殁怅然有怀', '张耒', '宋代', '宋玉台前官树林，十年孤客独沾襟。白头青鬓隔存殁，落日断霞无古今。\n\n暮云梁苑雁鹜暗，久泛吴船江海深。阅世悲欢嗟老眼，呼儿取酒十分斟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '予元丰戊午岁自楚至宋由柘城至福昌年二十有五后十年当元祐二年再过宋都追感存殁怅然有怀' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一落索', '陆游', '宋代', '识破浮生虚妄。从人讥谤。此身恰似弄潮儿，曾过了、千重浪。 \n 且喜归来无恙。一壶春酿。雨蓑烟笠傍渔矶，应不是、封侯相。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '一落索' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('觱发寒威淡远空两峰谁镂玉西东后凋颜色分明在便是当年黄绮翁 其五', '弘历', '清代', '花树烘霞送尾寒，太平鼓吹满长安。春光六月莲为火，九陌通宵燄是兰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '觱发寒威淡远空两峰谁镂玉西东后凋颜色分明在便是当年黄绮翁 其五' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('筑普济堂成述怀七首 其三', '过鸣冈', '清代', '感伤复感伤，糟糠不下堂。断机犹可续，破镜无圆光。\n\n孤儿在襁褓，枕块支空床。凉月窥我牖，饥鼠穿我梁。\n\n呱呱待成立，十指安得将。吁嗟兮少寡，血泪沾衣裳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '筑普济堂成述怀七首 其三' AND p.poem_author = '过鸣冈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郁庵藏兵之骆越王弓格剑 其四', '姚佳', '当代', '吾尝终日而思矣，曳尾涂中徙北溟。流水不言供激荡，春山如笑欲忘形。\n\n将无同也生何惧，身既死兮神以灵。龙战大荒漂杵血，昆池劫碎一天星。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郁庵藏兵之骆越王弓格剑 其四' AND p.poem_author = '姚佳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红三首 其一', '项鸿祚', '清代', '铁瓮城开，何处是，紫髯天下。流不尽，英雄遗恨，寒涛激射。\n\n双桨吴船轻似燕，千寻浊浪高千马。看危矶，径转妙高台，山如画。\n\n骤雨歇，长虹挂，风渐紧，云成赭。唤江妃，起舞鱼龙悲吒。\n\n瓜步洲边新月上，茱萸湾口孤帆卸。听寺楼，钟鼓落篷窗，无眠夜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红三首 其一' AND p.poem_author = '项鸿祚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('少年游·端午赠黄守徐君猷', '苏轼', '宋代', '银塘朱槛麹尘波，圆绿卷新荷。兰条荐浴，菖花酿酒，天气尚清和。\n好将沉醉酬佳节，十分酒、一分歌。狱草烟深，讼庭人悄，无吝宴游过。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '少年游·端午赠黄守徐君猷' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('近于小圃筑堂名曰秀野隔河插木芙蕖旧有诗云', '张侃', '宋代', '二十四番花信风，凝脂剪翠巧妆容。谁言桃李芳春后，不似沿流锦绣中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '近于小圃筑堂名曰秀野隔河插木芙蕖旧有诗云' AND p.poem_author = '张侃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('齐后图', '唐寅', '明代', '百二关河狼虎秦，连环难解献高臣。\n若非纤手抽刀斩，应笑山东后有人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '齐后图' AND p.poem_author = '唐寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长相思 其二', '李煜', '唐代', '云一緺，玉一梭。澹澹衫儿薄薄罗，轻颦双黛螺。\n\n秋风多，雨如和。帘外芭蕉三两窠，夜长人奈何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长相思 其二' AND p.poem_author = '李煜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又用胡尉韵', '方岳', '宋代', '便觉寻春负一筹，老怀无复少年游。\n茶桑天似鹅黄酒，杨柳花飞狐白裘。\n试问独醒观众醉，何如一笑失千忧。\n不知多少人间事，付与溪声自在流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又用胡尉韵' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十月九日初谒卫真太清宫二首 其一', '晁补之', '宋代', '虚庭下拜初形肃，秘殿瞻容更魄惊。何必囊函窥至妙，始知尘垢负平生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十月九日初谒卫真太清宫二首 其一' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次和尹世立过访', '李之世', '明代', '春在林芳雨霭间，聊将澹酌消春閒。盘空衲子挦蔬去，灶湿山童乞火还。\n\n角韵何人诗骨隽，飞筹偏我酒肠悭。茸茸细草沾游屐，踏破苍苔几径斑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次和尹世立过访' AND p.poem_author = '李之世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归雁', '章懋', '明代', '灵囿池台是旧游，西风万里思悠悠。阵横紫塞霜天晓，影落澄江水国秋。\n\n栖止更嫌芦荻浅，飞归不为稻粱谋。一封带得边城信，要把平羌报冕旒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归雁' AND p.poem_author = '章懋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送兄弟还都至长葛河上四首·双禽', '韩维', '宋代', '双双河洲禽，文彩披丹质。\n飞翔不离渚，鸣戏自终日。\n寒鱼伏冰池，岁暮饥尔匹。\n不欲远求林，投身避罗毕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送兄弟还都至长葛河上四首·双禽' AND p.poem_author = '韩维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丁亥暮春昭萍雅集次江湖小李兄韵', '熊盛元', '当代', '回春术与缓和齐，退食山房诵克岐。醇酒青横骚客眼，乱花红浥燕巢泥。\n\n袂分南浦肠应断，派衍西江责岂辞！问取昭萍今夜月，明年此会更谁题？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丁亥暮春昭萍雅集次江湖小李兄韵' AND p.poem_author = '熊盛元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病中答馈药二首 其一', '刘麟', '明代', '坐室延师易，登城取药难。感君传递至，蹴踏试寻山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病中答馈药二首 其一' AND p.poem_author = '刘麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元夕二首', '项安世', '宋代', '堕剑遗弓未乾，断蓬漂梗不知寒。\n月明正在行宫上，犹作瑶墀旧梦看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元夕二首' AND p.poem_author = '项安世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辛亥三月二十九日广州之役，余在北京狱中闻展堂死事，为诗哭之，才成三首，复闻展堂未死，遂辍作 其一', '汪精卫', '近代', '马革平生志，君今幸已酬。却怜二人血，不作一时流。\n\n忽忽馀生恨，茫茫死后忧。难禁十年事，潮上寸心头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辛亥三月二十九日广州之役，余在北京狱中闻展堂死事，为诗哭之，才成三首，复闻展堂未死，遂辍作 其一' AND p.poem_author = '汪精卫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别仙娥峰', '王禹称', '宋代', '商山留滞再经春，吟爱仙娥最出群。若有精灵念迁客，暂来河北作行云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别仙娥峰' AND p.poem_author = '王禹称';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和泾川观音岩韵', '罗玘', '明代', '此生此日此冯轩，惊见银山大浪翻。石窟定僧如鬼瘦，斗崖悬树与猿攀。\n\n风雷半夜鲸鲵吼，霜露满天鸳鹤喧。面面云中千岫出，若为龙象筑长垣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和泾川观音岩韵' AND p.poem_author = '罗玘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆铁机梵音更涉诸子', '释今严', '明代', '芝焚蕙谢自多情，情尽如何感又生。巨海已看摧劲楫，法门频复坏长城。\n\n六群但执中边议，五部惟争大小乘。宁似此时荒谬极，辩才高论惜群英。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆铁机梵音更涉诸子' AND p.poem_author = '释今严';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送邵州判官往南', '刘长卿', '唐代', '看君发原隰，驷牡志皇皇。始罢沧江令，还随粉署郎。\n\n海沂军未息，河兖岁仍荒。征税人全少，榛芜虏近亡。\n\n新知行宋远，相望隔淮长。早晚裁书寄，银钩伫八行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送邵州判官往南' AND p.poem_author = '刘长卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨中花 其一 江亭晚集', '丁澎', '清代', '望里江城如雾。柳外檐星初吐。婪尾争传，红牙乍拍，飘眇烟深处。\n\n樽前翠袖双眉妩。香入鹍弦半度。看野鹜多情，芰荷应笑，客且休归去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨中花 其一 江亭晚集' AND p.poem_author = '丁澎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过金山和人韵三绝 其一', '耶律楚材', '元代', '金山突兀翠霞高，清赏浑如享太牢。半夜穹庐伏枕卧，乱云深处野猿号。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过金山和人韵三绝 其一' AND p.poem_author = '耶律楚材';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('溪上', '顾况', '唐代', '采莲溪上女，舟小怯摇风。惊起鸳鸯宿，水云撩乱红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '溪上' AND p.poem_author = '顾况';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟过城门村清晓雨止日出 其五', '杨万里', '宋代', '地锦花铺地锦衣，碧茸上织紫花枝。垂杨舞罢莺停唱，不捲华絪待阿谁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟过城门村清晓雨止日出 其五' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早朝', '孙锐', '宋代', '烛光剑佩拥千官，载月临轩拜紫銮。\n仙掌禁寒承露稳，天颜霁晓傍云看。\n朝阳鸣凤谐宫律，沧海□鳌献羽翰。\n咫尺圣明三舞蹈，报恩岂敢负弹冠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早朝' AND p.poem_author = '孙锐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅', '戴复古', '宋代', '孤标粲粲压群葩，独占春风管岁华。\n几树参差江上路，数枝装点野人家。\n冰池照影何须月，雪岸闻香不见花。\n绝似林间隐君子，自从幽处作生涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅' AND p.poem_author = '戴复古';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山中小景', '全室宗泐', '明代', '四山一片秋色，野客独坐茅亭。\n渡头红叶如雨，石上长松自青。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山中小景' AND p.poem_author = '全室宗泐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('婢态', '万俟绍之', '宋代', '才入园中便折花，厨头坐语是生涯。\n不时掐数週年限，每事夸称旧主家。\n迁怒故将瓯碗掷，俲{左目右宾}刚借粉脂搽。\n隔屏窃听宾朋语，汲汲讹传又妄加。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '婢态' AND p.poem_author = '万俟绍之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋风 其二', '陈邦彦', '明代', '早稻才收晚稻黄，使船如马信帆樯。时因回合占师律，为辨雄雌识大王。\n\n何处征途歌葛屦，有人狎坐理霓裳。相思莫遣罗衣薄，河汉西流夜未央。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋风 其二' AND p.poem_author = '陈邦彦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('正月初四后十余日病嗽不能出杂书十首', '方回', '宋代', '僦居背古城，楼西耸乔木。\n两年见黄落，雪尽欲再绿。\n往时春鹊雏，理巢乳哺续。\n不归视吾儿，于此拜饥腹。\n穷山况味等，差胜客景独。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '正月初四后十余日病嗽不能出杂书十首' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('廖传道示旅中述怀借韵奉酬且相慰勉云', '廖刚', '宋代', '高轩惭愧远相过，道义谈馀旅琐多。灯底自怜干斗剑，壁间谁办化龙梭。\n\n时来会中青钱选，和寡空为白雪歌。好淬文锋迎紫诏，莫因贤梗叹蹉跎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '廖传道示旅中述怀借韵奉酬且相慰勉云' AND p.poem_author = '廖刚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五福降中天 丁未除夕示内', '吴绮', '清代', '牛衣夜半啼寒雪，犹记灞陵憔悴。司马鹴裘，少君鹿毂，岂意行歌黻佩。\n\n年华欲换，笑五十明朝，买臣非贵。夫婿东方莫羡，此际且相慰。\n\n绿水青山作吏。一家图画里，欢成队。蜡凤宵嬉，青箱付与天意，凭教儿辈。\n\n杯从幼起，暖向春归，况当良会。放却眉梢，陶然须共醉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五福降中天 丁未除夕示内' AND p.poem_author = '吴绮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送相里秀才赴举', '齐己', '唐代', '两上东堂不见春，文明重去有谁亲。曾逢少海尊前客， \n 旧是神仙会里人。已遂风云催化羽，却将雷电助烧鳞。 \n 明年自此登龙后，回首荆门一路尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送相里秀才赴举' AND p.poem_author = '齐己';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('瑞鹤仙·户庭浮瑞气', '佚名', '宋代', '户庭浮瑞气。八日馀寒，新春来至。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瑞鹤仙·户庭浮瑞气' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头', '郑元秀', '宋代', '园林夸富贵，红绿簇枝头。阳和毓秀，气劘屈贾压曹刘。翰墨场中独步，洒落胸中万卷，横截百川流。邈视青云侣，俯首看瀛洲。 \n 到如今，萦扃务，尚淹留。庙堂应得好语，早晚觐宸旒。从此立登要路，便可羽仪台阁，指日凤池游。岁岁蟠桃会，椿算八千秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头' AND p.poem_author = '郑元秀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵 其一', '于立', '元代', '过雨收残暑，西来水似天。秋风生柁尾，明月落尊前。\n\n惨澹依山寺，欹斜下濑船。清歌不成调，思尔枕书眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵 其一' AND p.poem_author = '于立';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谒中岳祠', '陈琏', '明代', '巍巍碧殿倚苍冥，玉节金幢拥百灵。乐石镌碑彰瑞应，斋廊画壁杂丹青。\n\n朝廷锡号恩尤重，使者函香意独精。维岳降神闻自昔，愿生申甫佐明廷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谒中岳祠' AND p.poem_author = '陈琏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀友', '止庵法师', '明代', '三五月明满，三五月明缺。\n行人去未远，忽若三年别。\n此时道路间，北风何猎猎。\n局促瘏马悲，萧条秋草歇。\n所遇非所欢，中怀安可说。\n不念故里闾，甘为苦霜雪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀友' AND p.poem_author = '止庵法师';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人（九月饮乘风亭故基）', '赵彦端', '宋代', '烟空磴尽长松语。佳处遗基古。道人乘月又乘风。未用秋衣沈水、换薰笼。 \n 两峰千涧依稀是。想像诗翁醉。莫惊青蕊后时开。笑倒江南陶令、未归来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人（九月饮乘风亭故基）' AND p.poem_author = '赵彦端';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏梅三十首 其十九 红梅', '冯子振', '元代', '春风昨夜入南枝，浃髓沦肌释冻威。和气晓来无著处，满空飘作綵云飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏梅三十首 其十九 红梅' AND p.poem_author = '冯子振';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('遣兴', '卢青山', '当代', '诗客语天真，还须刻玉心。山泉经百转，出瀑始天成。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '遣兴' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九月饯衍圣公于礼部次夏宗伯桂洲韵 其三', '钟芳', '明代', '堂焕丝纶锦障开，耆英仪度古尊罍。黄花爱客微含媚，意恐开残客倦来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九月饯衍圣公于礼部次夏宗伯桂洲韵 其三' AND p.poem_author = '钟芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('呈隆兴总管王都水友直 其二', '汪梦斗', '宋代', '当日凤台下，鹿鸣同著鞭。鱼龙既悬绝，鸡犬竟难仙。\n\n危叶愁霜病，寒花纷晚妍。幽窗论旧事，客抱固凄然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '呈隆兴总管王都水友直 其二' AND p.poem_author = '汪梦斗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次制帅所和前韵', '王之望', '宋代', '圣主忧勤躬万务，英豪宁许山林住。\n弓旌号召士无留，竹帛功名公所赴。\n天表对扬咨见晚，坤维镇抚歌来暮。\n雪山增生绝纷埃，蜀道非难履平路。\n分陕聊烦摅妙略，秉钧已叹迂高步。\n朱轓抚俗民怀，玉帐折冲荒服惧。\n羽檄不飞烽堠灭，骏骨多收边市互。\n孔明七纵讵非长，户牖六奇真不误。\n农狎其野无外忧，马腾於槽有余怒。\n三陲绝徼皆妥安，诸将雄师今尽护。\n九重益友思直谅，四蜀新声咏宣布。\n帅阃方观勋业成，庙堂行看精神聚。\n嗟我衰迟托末契，辱公敦笃倾殊顾。\n当年献赋诵凌云，上国承颜悦披雾。\n禹门亲睹跃风雷，尧陛初惊承雨露。\n龙颜下瞩顿生光，凤翼高翔从此附。\n称身朝服曳青云，满袖天香携宝炷。\n九霄变化冥鹏升，一纪光阴隙驹鹜。\n绨袍雅意念张禄，襦夸余波依叔度。\n他时入觐对金莲，伴直应随玉堂寓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次制帅所和前韵' AND p.poem_author = '王之望';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题四娱斋 其二', '耶律铸', '元代', '雪满兰窗雾满阶，恍疑身世在瑶台。琴馀细嚼陶潜句，书罢深倾李白杯。\n\n流水净拖飞练去，好山晴与翠屏开。百年乐事能多少，何必更歌归去来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题四娱斋 其二' AND p.poem_author = '耶律铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送为章', '许景衡', '宋代', '使君遗爱在甘棠，故老于今尚未忘。椎钝自嗟生太晚，风流犹及见诸郎。\n\n鸣琴暂肯留山县，飞舄还同指帝乡。回首楼前江上月，夜来无故照离觞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送为章' AND p.poem_author = '许景衡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('步蟾宫', '王哲', '元代', '缘重下手并安脚。顿得来、真真没错。金炉立起琼花作，烧炼出、这般丹药。\n\n三田九转明光烁。八脉上、四门开却。虚空一点成灼灼，无言说、自然邀约。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '步蟾宫' AND p.poem_author = '王哲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题扬子云草玄图', '谢榛', '明代', '蚕丛之国三秦西，千峰上与青天齐。栈道悬空历万险，巨竹脩藤当昼迷。\n\n瀑布砰訇响不绝，阴壑直下垂虹霓。班虎咆哮黑熊啼，飒沓风舞双鹍鸡。\n\n路出剑门沃野阔，锦江秋水明玻瓈。蜀中文物古来盛，两汉名士特标题。\n\n前有马卿后扬子，高才往往怀金闺。火德中衰世板荡，谁能皓首甘幽栖。\n\n枫树森森隐茅宇，荒凉门径无轮蹄。草玄拟易坐朝夕，冥心自得穷端倪。\n\n水有汀洲山有溪，居然此道在盐齑。龙蛇知时蛰深窟，男儿志气何乖睽。\n\n校书阁下独遗恨，首阳二子光蒿藜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题扬子云草玄图' AND p.poem_author = '谢榛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('淮阴杂诗六首 其五', '邹祖符', '清代', '天花菌子色如银，青玉红樱缀满林。几日濯枝新雨过，鹧鸪声里采林檎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '淮阴杂诗六首 其五' AND p.poem_author = '邹祖符';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('直宿广文舍下', '梅尧臣', '宋代', '前夜宿广文，叶响竹打雪。\n昨夜宿广文，窗影竹照月。\n赖此数竿竹，与我为暖热。\n上有寒鹊栖，拳足如瘦蕨。\n平明欲飞去，唶唶若告说。\n我无喜可报，烦尔弄觜舌。\n亦尝苦老鸦，鸣噪每切切。\n为学本为道，穷蹙令素发。\n但能得酒饮，终日自兀兀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '直宿广文舍下' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵公显见赠 其二', '张纲', '宋代', '年齐耆旧愧衰阳，懒性唯耽野趣长。了却官租更何事，君王约法已三章。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵公显见赠 其二' AND p.poem_author = '张纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('睡起', '陆游', '宋代', '风约飞花满曲廊，萧然无客共焚香。\n瓮醅力重初投枕，鼻鼾声豪已撼床。\n栩栩梦游心自适，昏昏起坐日方长。\n静凭一几吾何恨，笑杀穿帘燕子忙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '睡起' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦中赋秋望', '王铚', '宋代', '阁小寒宜远，林荒晚带风。\n遥山秋色外，独树雨声中。\n念起三生异，心伤万境同。\n此邦非我圣，随意作流通。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梦中赋秋望' AND p.poem_author = '王铚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送张士皋归闽中', '虞堪', '明代', '阖庐城外草芊芊，西子湖边客上船。二月水生春自泛，三山日落梦相牵。\n\n鸱夷竟去沧溟远，杜宇还啼锦树妍。我亦欲归愁剑阁，风尘消息在何年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送张士皋归闽中' AND p.poem_author = '虞堪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送张符禺吏部', '董其昌', '明代', '天门新辟日曈昽，茂宰先承湛露浓。巳见玺书褒卓傅，更将玉尺倚林宗。\n\n千秋良史看驯雉，九品何人鉴画龙。若向河梁听骊唱，鸣琴清响满花封。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送张符禺吏部' AND p.poem_author = '董其昌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('盘山驿', '庞尚鹏', '明代', '河东伐鼓急徵兵，河西鸣金催筑城。胡马南嘶无宁夕，良田万顷生荆棘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '盘山驿' AND p.poem_author = '庞尚鹏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('简斯远兼怀成父', '赵蕃', '宋代', '闻道篮舆出行田，归来药裹手亲煎。旱而不雨热尤剧，节且立秋凉未便。\n\n我亦南山成卧疾，弟犹北阙未回船。江南已自伤流落，何况湖南路渺然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '简斯远兼怀成父' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('孟夏十有一日时雨初霁晨登高阁极目四望烟锁日出气象一新复用前韵', '王十朋', '宋代', '蝶梦惊回听残雨，鸟声唤起欣初晴。梵宫烟火带馀湿，黉舍几席生微清。\n\n披衣登阁忽四顾，顿觉远目增双明。樵渔欸乃雾中出，舟楫荡漾田间行。\n\n清和节物满眼界，柳垂暗绿花含情。窗明几净日渐永，天开地廓阴不争。\n\n俯视沧浪堪濯足，遥看扶桑观日浴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '孟夏十有一日时雨初霁晨登高阁极目四望烟锁日出气象一新复用前韵' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暑夜玩月不寐', '杨浣芬', '清代', '皎皎晴天月，今宵喜又圆。无灯辉自满，有树影常穿。\n\n为爱频留盼，因炎愈怕眠。一轮如赤日，冷署也烘然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暑夜玩月不寐' AND p.poem_author = '杨浣芬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和李祭酒韵', '罗亨信', '明代', '几年载笔侍明光，盛有才名播四方。超擢荣看登璧水，归田未许老柴桑。\n\n诸生侍讲闻霏玉，六馆循规戒履霜。造就英才为世用，人思德教永难忘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和李祭酒韵' AND p.poem_author = '罗亨信';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('点绛唇 喜芍药发芽', '王恽', '元代', '红叶当＊，朝来拨土红芽秀。画阑晴书。凭暖佳人袖。一粒丹砂，谁点仙根透。从今后。为渠酿酒。去作花闲友。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '点绛唇 喜芍药发芽' AND p.poem_author = '王恽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送王孝廉归柳州兼寄刘司理', '卢龙云', '明代', '风尘漂泊始龙城，岁月长悬旧友生。拙宦积薪殊未达，故人怀璞晚初成。\n\n比年抚字能为政，阖郡循良并有声。问讯江头曾种柳，并州他日总多情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送王孝廉归柳州兼寄刘司理' AND p.poem_author = '卢龙云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人', '冒广生', '清代', '鸭炉兽炭销香篆。窣地帘慵卷。梨花寒食又黄昏。偏到黄昏唤起秭归魂。\n\n鸳屏鸾镜浑如旧。人影幢幢瘦。夜窗闲谱断肠词。剩有一镫如豆证相思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人' AND p.poem_author = '冒广生';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登崆峒山', '乃贤', '元代', '缘萝陟层巘，旷望浮云驰。飘风西北来，飒飒吹裳衣。\n\n气候倏迁变，中怀郁歔欷。路逢一道士，高结冠巍巍。\n\n恐是广成子，再拜欲问之。长歌入深林，弃我忽若遗。\n\n哀湍泻石磴，日落松风悲。灵踪邈难及，千载生遐思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登崆峒山' AND p.poem_author = '乃贤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('淳化乡饮酒三十三章', '佚名', '隋代', '喈喈黄鸟，载飞载止。\n我有旨酒，嘉宾式燕且喜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '淳化乡饮酒三十三章' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过西竺新庵', '何巩道', '明代', '阴阴林莽蔽西堂，树底停车巳自凉。游倦客皆青眼老，吟多僧亦白髭长。\n\n井窥天色沉秋日，城落帆痕曳夕阳。行到野塘花欲谢，曲栏空倚木樨香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过西竺新庵' AND p.poem_author = '何巩道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵谢范黄中运管二绝', '刘宰', '宋代', '刁坞春回花满枝，沈溪梦断水盈池。\n遥知吊古经行处，落纸云烟总是诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵谢范黄中运管二绝' AND p.poem_author = '刘宰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同惟敬思伯夜泊浦口', '欧大任', '明代', '浦口青枫夕照迟，天涯飘泊更何之。船迎张翰因同载，笛遇王猷更一吹。\n\n渔父每从醒客问，海翁今谢白鸥疑。十年已共江潭远，岂傍啼猿怨竹枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同惟敬思伯夜泊浦口' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂证道歌·证道歌', '释印肃', '宋代', '莫将管见谤苍苍，井底蛙牛逞巨江。\n乾坤大地一只眼，用来还似一毫芒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂证道歌·证道歌' AND p.poem_author = '释印肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫籍监 其四', '文天祥', '宋代', '军衙马足起黄埃，门掩西风梦正回。自入燕关人世隔，隔墙忽送市声来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫籍监 其四' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其十', '朱浚', '宋代', '米车已过尘迷路，渔网才收月满船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其十' AND p.poem_author = '朱浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔父歌二', '欧阳炯', '唐代', '摆脱尘机上钓船，免教荣辱有流年。无系绊，没愁煎，须信船中有散仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔父歌二' AND p.poem_author = '欧阳炯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花四首 其一', '谢薖', '宋代', '姑射神游阅九关，水精宫殿不胜寒。下窥人世生尘想，故作梅花与俗看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花四首 其一' AND p.poem_author = '谢薖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题《各家和＜万岁墙诗＞集录》', '何永沂', '当代', '山寨飘摇万岁墙，栏杆拍遍雨飞霜。今吾醉里挑灯看，几代诗人血泪藏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题《各家和＜万岁墙诗＞集录》' AND p.poem_author = '何永沂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠刘山人蔬具为供宾费时山人适招洪广文别', '林大春', '明代', '问道广文招，此物聊当肉。昨宵当座谈，讵敢然诺宿。\n\n况复邻家子，伏雌方在掬。墙头遇酒尊，新秋酝已熟。\n\n但愿天气凉，孤亭夜深酌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠刘山人蔬具为供宾费时山人适招洪广文别' AND p.poem_author = '林大春';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('有所叹二首 其二', '唐庚', '宋代', '耕田佩印两徒然，忆相平津只去年。怪底功名称地狱，谁将官府到天仙。\n\n是非已付渔樵判，疑信难凭党与传。杯酌岂能通大道，床头当得酒如泉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '有所叹二首 其二' AND p.poem_author = '唐庚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏日赴监察许君之宴同张监察', '李梦阳', '明代', '霜府池亭夏亦寒，捲帘河岳火云残。筵开冰动琅玕簟，酒伴瓜行白玉盘。\n\n蓦石寻花时径往，跃鱼投饵晚留欢。孰教逃暑陪骢马，自分清朝老钓竿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏日赴监察许君之宴同张监察' AND p.poem_author = '李梦阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('章靖冯公哀词', '宋祁', '宋代', '睆箦绵疴革，中楹奠梦还。\n蕝仪犹在野，书副即藏山。\n友酹生刍洁，君恩刻印颁。\n一朝交臂失，宁复易睎颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '章靖冯公哀词' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('柏堂对月和周升逸', '岑霁', '清代', '柏堂今夜月，云物不能侵。对此碧空净，闻君《白雪》吟。\n\n入帘明鹤发，绕树见禽心。坐觉清言久，疏钟报隔林。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '柏堂对月和周升逸' AND p.poem_author = '岑霁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重过拂水山居经宿遂撤新楼开竁域主人复申墓田耦耕之约有述', '程嘉燧', '明代', '隔岁寒梅压路横，过年风槛纸窗鸣。岩扉静掩涓涓户，山阁俄开郁郁城。\n\n新表伫归华鹤语，生刍与怅白驹行。松堂丙舍仍招隐，投老看君誓墓情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重过拂水山居经宿遂撤新楼开竁域主人复申墓田耦耕之约有述' AND p.poem_author = '程嘉燧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答胡苇杭', '仇远', '宋代', '久矣相期物外游，长风吹不断闲愁。\n两山翼翼青如舞，霜鬓颾颾白始休。\n蕉鹿梦回天地枕，莼鲈兴到水云舟。\n旧藏方镜明如月，看去看来又一秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答胡苇杭' AND p.poem_author = '仇远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日吴子雨过山居作', '王宠', '明代', '雨重烟浓山更深，半窗楼阁昼阴阴。道书一卷香凝榻，岩翠千层鸟堕林。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日吴子雨过山居作' AND p.poem_author = '王宠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桂', '弘历', '清代', '露重槛风凉，迎阶绿间黄。中秋先报节，隔岁入吟章。\n\n一例皋涂种，偏依楚畹芳。谁曾到蟾窟，此处满天香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桂' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('恭读理斋常太翁老先生殉节录 其一', '曹殿魁', '清代', '谩言明哲保生全，凡圣分途岂泛然。肘腋难防身外变，肝肠不改性中天。\n\n夕阳一片悲辽鹤，夜月三更泣蜀鹃。十六年来题旧恨，几行清泪笔头传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '恭读理斋常太翁老先生殉节录 其一' AND p.poem_author = '曹殿魁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行次淮安甘蔗因悼同门友被谴没于京', '王恭', '明代', '伤心不见旧同游，离思萧萧醉未休。暮雨门临青蔗圃，夕阳潮到白沙洲。\n\n几家烟火遗民在，千里江陵去国愁。莫怪行人倍惆怅，羊昙何事泣西州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行次淮安甘蔗因悼同门友被谴没于京' AND p.poem_author = '王恭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题骖鸾阁', '莫俦', '宋代', '群山带雨阴云重，沧海连天水气昏。遥想真人乘铁舸，往来三岛鬼神奔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题骖鸾阁' AND p.poem_author = '莫俦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹊桥仙·才临复日', '佚名', '宋代', '才临复日，便逢生旦，料想门阑多喜。好将何物寿冰翁，但有个、新词为礼。如今已办，一千馀阕，尽按宫商角徵。一年一阕祝椿龄，自今日、从头数起。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹊桥仙·才临复日' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵和文访，并示同社', '连横', '近代', '寥落存吾志，徬徨看众迷。危言惊市虎，不寐听晨鸡。\n\n木折风敲户，寒侵雨满蹊。讨春迟旧约，诗卷共提携。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵和文访，并示同社' AND p.poem_author = '连横';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('日暮游东涧 其一', '释重显', '宋代', '极目生晚照，溪云偶成朵。大朴曾未分，青山自唯我。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '日暮游东涧 其一' AND p.poem_author = '释重显';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('张郎中籍远寄长句开缄之日已及新秋因举目前仰酬高韵', '刘禹锡', '唐代', '南宫词客寄新篇，清似湘灵促柱弦。京邑旧游劳梦想， \n 历阳秋色正澄鲜。云衔日脚成山雨，风驾潮头入渚田。 \n 对此独吟还独酌，知音不见思怆然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '张郎中籍远寄长句开缄之日已及新秋因举目前仰酬高韵' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饱食卒岁因之自警四首 其三', '郭之奇', '明代', '日月将穷节，民神合聚时。鱼冰坚泽腹，蚕火照田丝。\n\n观蜡因人乐，退公或自私。作糜名口教，授粲岂徒期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饱食卒岁因之自警四首 其三' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('揖舜自爪哇来访，联吟竟夕，余有“得句花间夜报钟”，意未尽，别后再寄', '黄松鹤', '近代', '天外人怀旧偃松，堂无客到苦尘封。村斋初下清凉榻，野径曾留洒落踪。\n\n夜半引杯三尺剑，花间得句一声钟。行程险为耽诗误，此去云山又几重。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '揖舜自爪哇来访，联吟竟夕，余有“得句花间夜报钟”，意未尽，别后再寄' AND p.poem_author = '黄松鹤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('论诗次铁庐韵 其八', '丘逢甲', '清代', '四海横流未定居，千村万落废犁锄。荆州失后吟梁父，空忆南阳旧草庐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '论诗次铁庐韵 其八' AND p.poem_author = '丘逢甲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古意十四首 其十', '章云心', '宋代', '吉凶本由人，往事皆可覆。祸人还自祸，福人还自福。\n\n于公果传世，李斯竟夷族。豺狼不知寤，纷纷方择肉。\n\n达者识几微，为之先痛哭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古意十四首 其十' AND p.poem_author = '章云心';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晦窗半梦谢堂雪樵以酬和诗见示步韵为和', '吴金水', '当代', '云边逸兴接天浓，莫道明时有不容。每遇高朋邀白酒，常闻大吕应黄钟。\n\n奚囊已被烟霞足，鬓雪还蒙岁月供。他日谁招舞雩会，清风千里亦相从。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晦窗半梦谢堂雪樵以酬和诗见示步韵为和' AND p.poem_author = '吴金水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岁暮旅怀五章 其四', '姚燮', '清代', '非无御冬粮，思我苦萧瑟。结其思我心，照空作明月。\n\n明月人不见，我独见真切。此光无溢明，但照我心密。\n\n遂使异地身，如已在家室。吴山何幽深，越山何崷崒。\n\n倏此一寸心，磊磊与萦结。且复垂重帏，以我梦飞越。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岁暮旅怀五章 其四' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '张固', '宋代', '鹿石晓寒云漠漠，虎溪春浅水潺潺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '张固';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戴帅初九日无憀以满城风雨近重阳为韵七首袖', '陈著', '宋代', '年年好时节，雪月花与风。\n谁知百年内，忧乐元不同。\n方其少壮日，日日醉梦中。\n年年旋衰飒。有景谁复穷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戴帅初九日无憀以满城风雨近重阳为韵七首袖' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪中送舒文质归广信', '蓝智', '明代', '积雪千峰迥，空林一鸟归。\n客愁南浦树，乡梦北山薇。\n风雨荒茅屋，兵戈老布衣。\n饥寒兼盗贼，出处寸心违。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪中送舒文质归广信' AND p.poem_author = '蓝智';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丙午九月十二日新定仰辰台同周自正郑孔新谢振卿扳跻登望浩歌而归', '湛若水', '明代', '仰辰台上仰辰游，一曲歌声彻九州。感得圣恩深似海，外臣早许作巢由。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丙午九月十二日新定仰辰台同周自正郑孔新谢振卿扳跻登望浩歌而归' AND p.poem_author = '湛若水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('漫作', '王特起', '金朝', '有时幽鸟话心事，无限秋虫誇口才。北阙上书吾老矣，东篱把菊思悠哉。\n\n竹林留得巨源在，莲社招入渊明来。不然馀子败人意，怀抱耿耿胡为开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '漫作' AND p.poem_author = '王特起';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陶与权南园别业', '黄玠', '元代', '琼田无恶土，玉树多好枝。鼎角匿犀者，自是名家儿。\n\n应门有暇日，颇作佳园池。朝临二王书，暮吟三谢诗。\n\n花边迎小车，竹下理残棋。宾至可命觞，亲在志无违。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陶与权南园别业' AND p.poem_author = '黄玠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄谢左子方声寄沈均德笔二枝', '刘崧', '明代', '抱病归来卧一窗，思君安得酒盈缸。沈家好笔无钱买，多谢新来寄一双。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄谢左子方声寄沈均德笔二枝' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('双桂卷为河南吴进士升作', '吴宣', '明代', '云帘雾箔隔仙都，八月天河见玉肤。忆自二郎相别后，素娥无梦碧鸾孤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '双桂卷为河南吴进士升作' AND p.poem_author = '吴宣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花喜神谱 其七 大开一十四枝', '宋伯仁', '宋代', '举头见长安，志士欣有托。葵藿一生心，岂容天负却。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花喜神谱 其七 大开一十四枝' AND p.poem_author = '宋伯仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏木钵', '弘历', '清代', '拥肿乖绳墨，谁施月斧修。居然五石瓠，那数一株榴。\n\n虚满皆如愿，色空莫可求。堪因遗阐士，渡海不惊鸥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏木钵' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读朱晦庵注参同契', '陈献章', '明代', '神仙不注参同契，火候工夫那得知。千古晦庵拈一语，可怜无及魏君时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读朱晦庵注参同契' AND p.poem_author = '陈献章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过瑞龙观道士', '钱起', '唐代', '不知谁氏子，炼魄家洞天。鹤待成丹日，人寻种杏田。 \n 灵山含道气，物性皆自然。白鹿顾瑞草，骊龙蟠玉泉。 \n 得兹象外趣，便割区中缘。石窦采云母，霞堂陪列仙。 \n 主人善止客，柯烂忘归年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过瑞龙观道士' AND p.poem_author = '钱起';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄郑生二首 其一', '李梦阳', '明代', '故菊开谁对，新醪怅尔违。耳憎木叶下，心与塞鸿归。\n\n儿女催蓬鬓，家园滞綵衣。问君称庆暇，何处采山薇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄郑生二首 其一' AND p.poem_author = '李梦阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长安四时辞四首 其一', '胡应麟', '明代', '携手七香车，春风向狭斜。燕姬年二八，烂醉碧桃花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长安四时辞四首 其一' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗', '黄侃', '近代', '女萝何袅袅，松柏生崇岗。因缘自同体，欢悦诚难忘。\n\n常恐寒风至，弱身付严霜。相依虽不久，执节固有常。\n\n君身上青云，万岁何讵央。妾身委尘埃，还在深根旁。\n\n脩短自有命，焉能咎穹苍。良辰宜出游，相期得何许。\n\n或在上宫旁，或在浍之浒。见时舜婆娑，别时泪如雨。\n\n常恐华色衰，弃捐等尘土。视尔若朝霞，桃李非其侣。\n\n各保盛年欢，何为有愁苦。莫嫌昼作宵，缱绻常从汝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗' AND p.poem_author = '黄侃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岁暮宿锦岩偕邓粤仁兄弟', '甘学', '明代', '雪夜三人心，抱膝梅花林。梅香不见影，山谷衡门深。\n\n赓歌李太白，宁怯岩寒侵。豪气凌斗杓，孤兴千仞岑。\n\n举声叱山鬼，惊起眠枝禽。何如邓二仲，与我雄一襟。\n\n此事几千古，今作卧龙吟。明发各乃别，载阳复相寻。\n\n共期登大科，再弄天风琴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岁暮宿锦岩偕邓粤仁兄弟' AND p.poem_author = '甘学';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('御赐真赞师演成四偈 其四', '释宗杲', '宋代', '随物现处，廓清寰宇。不动神情，气吞项羽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '御赐真赞师演成四偈 其四' AND p.poem_author = '释宗杲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏怀二首 其二', '宋祁', '宋代', '尽信书奚信，难言命敢言。竟谁成简册，无客问乾坤。\n\n值狩麟犹泣，遭君鹤乃轩。滔滔千古事，惟有付芳樽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏怀二首 其二' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('香山即景杂咏 其一', '弘历', '清代', '好山岂虑秋光老，洗尽繁华越雅宜。兴会悠然重九近，底殊五柳得诗时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '香山即景杂咏 其一' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿良田草阁', '梁以壮', '明代', '停鞭只合沽村酒，野菜连根上一盘。邻妇夜舂吟外听，隔山残烧坐中看。\n\n松梢落月床全白，雪气冲裘影并寒。空有石波老巡吏，对人深解路行难。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿良田草阁' AND p.poem_author = '梁以壮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题徐氏溪亭二首', '王慎中', '明代', '浯水日悠悠，虚亭压水头。\n棹歌喧极浦，峰翠漾中流。\n每夜偏多月，长天只似秋。\n更添幽事并，系柳木兰舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题徐氏溪亭二首' AND p.poem_author = '王慎中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重阳后一日登石钟寺', '梁以壮', '明代', '渡水闻声见石钟，石钟之上见芙蓉。无多野客乘秋屐，有个僧人制毒龙。\n\n鸿影不期黄叶到，菊花那许白云封。一尊须补重阳醉，酌对匡山五老峰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重阳后一日登石钟寺' AND p.poem_author = '梁以壮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头 送李经历', '唐桂芳', '元代', '白头閒父老，都说幕中宾。杜门鹤立，风雨不遣客来频。\n\n果是清心苦节，能障狂澜砥柱，矻立势千钧。吹散浮云了，依旧月如轮。\n\n忆公馀，携印绶，出城闉。酒船醉舞，江月还似谪仙人。\n\n好理木天文字，便许玉堂标致，笔下信通神。离恨正无赖，杨柳不胜春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头 送李经历' AND p.poem_author = '唐桂芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬夜八首 其七', '黄文仪', '清代', '江星云外落，海日地中来。水碧浮天镜，霞红照玉台。\n\n几株枫树雪，数朵陇头梅。报晓钟初击，霜寒落叶豗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬夜八首 其七' AND p.poem_author = '黄文仪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('从军行', '屠滽', '明代', '马上黄沙拂面行，汉家何日不劳兵。匈奴久自忘甥舅，仆射今谁托父兄。\n\n云外旌旗婆勒渡，月中刁斗受降城。左贤早待长绳缚，莫遣论功白发生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '从军行' AND p.poem_author = '屠滽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小游仙七首 其五', '周密', '宋代', '一径松花满路香，琤琤玉杵捣玄霜。有时骑鹤月中去，流水白云生晚凉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小游仙七首 其五' AND p.poem_author = '周密';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古十一首', '释智鉴', '宋代', '云巢梦断月华秋，玉女翻身过斗牛。\n卸却花冠归旧隐，玄途鸟道未容收。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古十一首' AND p.poem_author = '释智鉴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('皇城曲', '袁桷', '元代', '堂堂瞿昙生王宫，幼年夙悟它心通。梵书未睹口已诵，底用城阙穷西东。\n\n净居老人幻境异，故作恐怖生愁容。世间习妄了莫喻，要以神化开盲聋。\n\n岁时相仍作游事，皇城集队喧憧憧。吹螺击鼓杂部伎，千优百戏群追从。\n\n宝车瑰奇耀晴日，舞马装辔摇玲珑。红衣飘裾火山耸，白伞撑空云叶丛。\n\n王官跪酒头叩地，朱轮独坐颜酡烘。蚩氓聚观汗挥雨，士女簇坐唇摇风。\n\n人生有身要有患，百岁会尽颜谁童。西方之国道里通，至今生老病死与世同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '皇城曲' AND p.poem_author = '袁桷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送毕文明之寿州', '郑真', '明代', '浮空鸾鹤影飘飘，肥水青春远见招。剩有周诗留翰墨，可无杜酒劝琼瑶。\n\n董生孝行今何在，霍叔流风尚未消。落日苍茫赋怀古，彩毫毋惜寄云轺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送毕文明之寿州' AND p.poem_author = '郑真';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送徐水部奉使荆关 其五', '倪元璐', '明代', '占天太史上星台，楚分媭星逼上台。召去君王如有问，须言红叶是良媒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送徐水部奉使荆关 其五' AND p.poem_author = '倪元璐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('至日过徐德章', '何景明', '明代', '竹门寒旭凤城隈，春气潜浮地底灰。世路十年长不定，客怀此日更难开。\n\n天边梅柳垂垂发，岁暮阴阳冉冉催。见说吴江酒船到，即𢬵留饮夜深回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '至日过徐德章' AND p.poem_author = '何景明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠别周别驾王司理入京十四首 其九', '顾璘', '明代', '行行及辰良，律转寒序毕。东风来几时，江草忽青出。\n\n幽鹭濯轻澌，疏梅耀迟日。兰棹从此逝，佳兴谅非一。\n\n倘赋清水篇，贻我慰萧瑟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠别周别驾王司理入京十四首 其九' AND p.poem_author = '顾璘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('命免天津府及顺天府所属积欠诗以志事', '弘历', '清代', '休助古有云，怀保今所勉。昨岁此地灾，赈赒期均遍。\n\n巡方兹目睹，幸逭沟壑转。然未经见多，加惠讵宜缓。\n\n两府界壤连，受沴苦弗浅。三州及八县，旧欠概与免。\n\n武清独无欠，岂不向隅叹。蠲供十之五，用意旌良善。\n\n麦收倘得半，庶少济屯蹇。是惟赖天恩，非吾力能办。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '命免天津府及顺天府所属积欠诗以志事' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿尼什哈站', '杨宾', '清代', '水经玄菟黑，山过混同青。漫道无城郭，相看有驿亭。\n\n糠镫劳梦寐，麦饭慰飘零。明发骑鞍马，萧萧逐使星。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿尼什哈站' AND p.poem_author = '杨宾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('象川林少参旅顾致谭二守瓶台故人消息', '区元晋', '明代', '烹鲜手易调商鼎，制锦才堪补舜裳。恰喜薇垣相邂逅，共谈棠泽见声光。\n\n兵馀败垒愁云黑，乱后遗墟宿草长。闻说海防成峻筑，已曾借手障濒方。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '象川林少参旅顾致谭二守瓶台故人消息' AND p.poem_author = '区元晋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赵城至洪洞道中口占', '张瑞玑', '近代', '飞絮飞花三月时，东风剪剪柳丝丝。\n断桥流水青山外，匹马寻碑纪信祠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赵城至洪洞道中口占' AND p.poem_author = '张瑞玑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出婺城', '苏泂', '宋代', '万顷平田雪，前村昨夜梅。\n梦还荆国旧，吟欠兔园才。\n只作寻诗去，何曾为酒来。\n兹行得奇事，夹道有琼瑰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出婺城' AND p.poem_author = '苏泂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八声甘州 上龈牙脱，仅存一枚，独力支唇，闷而有作', '吴重憙', '清代', '都呼朋引类，独伊人，情深尚坚牢。似霜高木落，观撑一柱，山峙单椒。\n\n想见灵岩钟乳，滴久宛垂条。障碍有时去，去更无聊。\n\n未吃红绫饼馅，笑残牙老口，难肆贪饕。效龙须拔去，逊太真豪。\n\n将无如、东山赌墅，罢残棋、屐折触嶕峣。莫学彼、衰年作戏，孺子牛嘲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八声甘州 上龈牙脱，仅存一枚，独力支唇，闷而有作' AND p.poem_author = '吴重憙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢飞卿饭', '耶律楚材', '元代', '一鞭羸马渡天山，偶到云川暂解鞍。独守空房方丈稳，更无薄酒一杯残。\n\n诗书半蠹绝来客，釜甑生尘笑冷官。赖有觉非怜野拙，长须为我馈盘餐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢飞卿饭' AND p.poem_author = '耶律楚材';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重阳后三日饮彦成宗侯宅', '苏升', '明代', '九日登台兴未阑，侯门犹得更追欢。秋涵桂树香风远，月入梁园夜色寒。\n\n白雁先霜何处度，黄花一径借相看。酣来作赋多公等，授简低头愧子安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重阳后三日饮彦成宗侯宅' AND p.poem_author = '苏升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮八首 其六', '余一鳌', '清代', '琵琶隔舫瓜州月，月明风静人离别。别意满侬怀，怀中豆蔻胎。\n\n郎如风漾絮，妾似花沾雨。雨细蝶飞迟，迟君杨柳枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮八首 其六' AND p.poem_author = '余一鳌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('烟浦', '沈说', '宋代', '烟浦残鸦舞夕阳，风枝病叶似初霜。\n眼中秋中十分净，沙外寒流一线长。\n溪女得鱼烹碎白，田家收谷曬新黄。\n偶寻野趣归来晚，草际萤飞点点光。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '烟浦' AND p.poem_author = '沈说';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再次韵二首 其一', '陈造', '宋代', '雪神不袖嘘枯手，嗣岁丰登预告成。泚笔径烦书上瑞，载涂况已沸欢声。\n\n骑驴有客搜新句，扶路何人趁晚晴。一笑与渠分乐事，的知琼露胜宜城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再次韵二首 其一' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋居杂咏十首', '李弥逊', '宋代', '穷秋杂花远，眷此霜下杰。\n明金委珞璎，宝璐缀环玦。\n依依风递兰，皓皓日穿雪。\n若无夭冶姿，不受众目悦。\n共杯泛其英，揽之肠为结。\n谁能踵高门，持以浣中热。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋居杂咏十首' AND p.poem_author = '李弥逊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('漳南十咏·圆山庙', '蔡襄', '宋代', '风雅遗芬岳有神，此山灵祀越千春。\n彩毫佳句言犹在，翠剡新词意未真。\n绝顶黑林长带雨，曲崖飞磴不留尘。\n瘴云收尽秋田熟，跋境肴浆再拜人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '漳南十咏·圆山庙' AND p.poem_author = '蔡襄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('齐天乐五十首 其十九', '端木埰', '清代', '几年同儤薇垣值，风流快从觞咏。潭水桃华，幽山桂树，那更深情逸性。\n\n离怀骤警。况取次东风，一麾先秉。怕是它时，不胜怊怅此情景。\n\n多君风义近古，有中台宝笈，招共删订。抉汉分章，承云奏雅，羊鹤还愁不竞。\n\n清言快领。趁明月犹圆，碧天澄镜。四印斋中，一尊相共请。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '齐天乐五十首 其十九' AND p.poem_author = '端木埰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和龚使君韵', '文天祥', '宋代', '淡和心事葛天民，回首归来清渭滨。\n长倩君宝孙子行，道原义仲辈流人。\n一生受用忘非是，万事升沉等故新。\n近日贞元朝士少，蒲轮有命出枫宸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和龚使君韵' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感物二首', '唐彦谦', '唐代', '騄骥初失群，亦自矜趫腾。俯仰岁时久，帖然困蚊蝇。 \n 豪鲸逸其穴，尺水成沧溟。岂无鱼鳖交，望望为所憎。 \n 物理有翕张，达人同废兴。幸无怵迫忧，聊复曲吾肱。 \n 鱼目出泥沙，空村百金珍。豫章值拥辏，细细供蒸薪。 \n 论材何必多，适用即能神。托交何必深，寡求永相亲。 \n 鲍叔拙羁鲁，张生穷厄陈。茫然扳援际，岂意出风尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感物二首' AND p.poem_author = '唐彦谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('净光松风阁', '叶适', '宋代', '城中云日如火催，净光行食声转雷。\n不知何处白蘋起，便有满坐清风来。\n莫言作楼非急务，翁当运斤儿执锯。\n待得三间着此风，病叟扶携上楼去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '净光松风阁' AND p.poem_author = '叶适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('任秋田明经读书祇园庵柯岩之游拟枉道过访骤雨不果诗以寄怀', '曹寿铭', '清代', '绝磴苍茫俯碧浔，烟萝寂寞此登临。已餐石气清诗骨，欲就禅花证佛心。\n\n隔岸云山无鹤导，满湖风雨作龙吟。归舟怅望江头路，杳杳疏钟度水深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '任秋田明经读书祇园庵柯岩之游拟枉道过访骤雨不果诗以寄怀' AND p.poem_author = '曹寿铭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古三十首 其十八', '释怀深', '宋代', '法身无相，法眼无瑕。因风吹火，借水献花。丝毫不立，万别千差。\n\n但看来年三二月，衔泥燕子入人家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古三十首 其十八' AND p.poem_author = '释怀深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿吴隐君希学七秩', '胡应麟', '明代', '君平曾寄蜀，尹喜尚留秦。杏植三千亩，桃偷七十春。\n\n壶中长宇宙，屐底半星辰。白日飞鸡犬，无劳颂大椿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿吴隐君希学七秩' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晋阳怀古 其六 怀阳谏议', '何乔新', '明代', '晴壑凝黛色，寒溪漾澄流。眷昔阳谏议，韬光此夷犹。\n\n贤声彻黼座，徵诏来林丘。遂辞鹿豕群，去与鹓鹭游。\n\n谓公当謇謇，而公但悠悠。青蝇忽止藩，贤相投荒陬。\n\n公乃叩阁争，累疏不自休。精忠贯皎日，劲气凌清秋。\n\n白麻不果降，憸佞恚且羞。公殁数百载，士风日以偷。\n\n旖旎荃与蕙，兹焉化为茅。朝阳无鸣凤，立仗多骅骝。\n\n思公不可见，怅然抱孤忧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晋阳怀古 其六 怀阳谏议' AND p.poem_author = '何乔新';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋华十咏次如山 其四 孩儿菊', '邵宝', '明代', '菊名非菊恨虚闻，中有幽香为解纷。采采秋风篱落畔，独嫌荒草欲教芸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋华十咏次如山 其四 孩儿菊' AND p.poem_author = '邵宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵秋兴八首次草堂韵 其七', '钱谦益', '明代', '铃索警传航海功，秋宵蜡炬井梧中。冯夷怒击前潮鼓，飓母谁催后鹢风？\n\n蛟吐阵烟掀浪黑，猩殷袍血射波红。秦淮卖酒唐时女，醉倒开元鹤发翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵秋兴八首次草堂韵 其七' AND p.poem_author = '钱谦益';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('薄倖 追悼沈姬', '薛时雨', '清代', '烟波江上。旧曾共、桃根打桨。记王粲、客游无绪，累尔伶仃相向。\n\n争兰桡、双载人来，经年不载人同往。叹逝水无情，罡风太恶，人与落花并葬。\n\n生就了、聪明性，应悟彻、尘因俗障。梦中傅幽怨，声声诉出，夜台多少凄凉况。\n\n一灵无恙。趁归舟、安稳玉箫，重侍韦皋帐。吟成楚些，付与秋坟鬼唱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '薄倖 追悼沈姬' AND p.poem_author = '薛时雨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐', '张尔田', '清代', '唾绒残线。界破红妆面。浓睡醒来莺语懒。又是斜阳小院。\n\n麝薰微度罗衣。雨余栀子添肥。贪画远山一角，不知蹙损双眉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐' AND p.poem_author = '张尔田';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('少年游 兰江吟眺', '姚燮', '清代', '四山眉爽入横漪。画色满江扉。夕日明来，水烟散去，风絮落微微。\n\n碧遥青远知何极，坐对息尘机。北溆鸥群，西湾渔桨，来往总相依。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '少年游 兰江吟眺' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟次邗江感怀', '戴研', '清代', '寒云萧瑟片帆收，江草江花动客愁。瓜步涛声常带雨，广陵山色易为秋。\n\n已拚湖海供多病，漫逐风尘故倦游。寂寞仲宣怀故里，不胜摇落赋《登楼》。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟次邗江感怀' AND p.poem_author = '戴研';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送于制干二首 其二', '释宝昙', '宋代', '一笑无烦论古今，就中首肯即吾真。君今正与司南合，直指何曾更问人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送于制干二首 其二' AND p.poem_author = '释宝昙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠三乡浮图智聪', '尹洙', '宋代', '伊昔相逢日，于今二十年。师随安乐住，我岂利名牵。\n\n自笑真徒尔，何如养浩然。西门女几路，未得赋归田。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠三乡浮图智聪' AND p.poem_author = '尹洙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('济宁逢春二首 其一', '潘希曾', '明代', '忽忽浮生已向衰，悠悠拙宦竟何裨。碧山笑我红尘久，青镜输谁白发迟。\n\n治水可能寻禹迹，转漕亦复托萧规。梦游不觉长安远，应被春风昨夜吹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '济宁逢春二首 其一' AND p.poem_author = '潘希曾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和陶渊明饮酒 其四', '戴良', '元代', '一鸟乘风起，逍遥天畔飞。一鸟堕泥涂，噭噭鸣声悲。\n\n升沉亦何常，时去两无依。我昔道力浅，磬折久忘归。\n\n迩来解其会，百念坐自衰。惟寻醉乡乐，一任壮心违。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和陶渊明饮酒 其四' AND p.poem_author = '戴良';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望江南 其十', '董元恺', '清代', '茶候静，帘卷日初长。片甲味分蝉翼薄，丹丘阴益簟纹凉。\n\n应唤醒羲皇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望江南 其十' AND p.poem_author = '董元恺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('罢徐州，往南京，马上走笔寄子由五首 其三', '苏轼', '宋代', '古汴从西来，迎我向南京。东流入淮泗，送我东南行。\n\n暂别复还见，依然有馀情。春雨涨微波，一夜到彭城。\n\n过我黄楼下，朱栏照飞甍。可怜洪上石，谁听月中声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '罢徐州，往南京，马上走笔寄子由五首 其三' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水曲纳凉', '何景明', '明代', '乘月玩清夜，漱流涤烦痾。竹柏夹脩水，微风扬泽荷。\n\n苔阴皓露溽，素鳞跃于波。柔条纷敛结，劲叶亦陨柯。\n\n优游荡情志，俯仰丘中阿。虽无朋侪和，兴言自成歌。\n\n娱乐当及时，千秋岂复多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水曲纳凉' AND p.poem_author = '何景明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('相见欢', '易顺鼎', '清代', '水亭残雪连空。月如弓。添个骑驴人在冻云中。\n\n吹玉笛。落瑶砌。又悤悤。只有梅花全不忆东风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '相见欢' AND p.poem_author = '易顺鼎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('为杨廷献题画六首 其五', '张宁', '明代', '路僻无忙步，林空有远情。幽寻行复坐，诗绪乱还清。\n\n水到荒矶绝，云依野树生。何时休世念，来与尔同盟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '为杨廷献题画六首 其五' AND p.poem_author = '张宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('念奴娇 咏玫瑰花', '陈维崧', '清代', '陡惊春去，算风光此际，又逢樱笋。拂晓谢娘帘阁畔，忽逗卖花声韵。\n\n篮底氤氲，担头狼籍，紫艳浓香喷。佳人竞撚，看来和露尤俊。\n\n最爱别样心情，天然梳掠，偏厌红英衬。揉得花魂魂尽碎，另作一番安顿。\n\n焙入衾窝，薰归裙缝，细细调红粉。玉郎不觉，错疑戴向云鬓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '念奴娇 咏玫瑰花' AND p.poem_author = '陈维崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次介叔韵', '刘跂', '宋代', '酒船定向江东去，知有风流贺季真。北岭南冈元自熟，短杨高柳迩来新。\n\n老吾官职浑无味，壮子文章最有神。知欲弦歌且三径，徵君莫自傍风尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次介叔韵' AND p.poem_author = '刘跂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('进帆石门怀古', '陈子升', '明代', '卢城伤飒沓，郁水引游衍。虽非千里驾，发棹自成远。\n\n郊原互盘纡，洲渚迭溶演。水波舷下割，日影帆上转。\n\n巀嶪开一门，澄鲜豁双眼。层阿蔓绿萝，阴石滋斑藓。\n\n坎流知所止，井汲当自选。怀金泉靡堙，不易心弥显。\n\n讵以朵颐龟，取笑饮河鼹。亮为江海人，独契蘧生卷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '进帆石门怀古' AND p.poem_author = '陈子升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其一', '梁周翰', '宋代', '谁似金华杨学士，十联诗在御屏间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其一' AND p.poem_author = '梁周翰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂二十四首', '释智遇', '宋代', '出山而见，入户而知。\n鸡棲凤巢，邻壁之辉，\n何必区区点缀伊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂二十四首' AND p.poem_author = '释智遇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病中雨夜寄悯茎上人二首 其二', '何吾驺', '明代', '永夜禅心寂似冰，未须善识为传灯。漏残无耐穿窗雨，拈韵题诗寄老僧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病中雨夜寄悯茎上人二首 其二' AND p.poem_author = '何吾驺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('跋希远细雨图', '曹勋', '宋代', '牵风藻荇舞清漪，浪板无声细雨时。\n小大自殊同队乐，密图劝学助韩诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '跋希远细雨图' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('崤函怀古', '刘东里', '清代', '两峰高矗郁苍苍，旧说山河百二强。天转星辰迎夏后，山排风雨扈周王。\n\n神皋东据《西都赋》，鬼哭今留古战场。欲吊兴亡千载事，淡烟衰草又斜阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '崤函怀古' AND p.poem_author = '刘东里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠卫武孟 其一', '殷奎', '明代', '桑海茫茫不可论，衣冠乡里几家存。咸阳渡口秋风里，惊见开禧执政孙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠卫武孟 其一' AND p.poem_author = '殷奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春尽同诸公游紫岩各赋六言', '吴芾', '宋代', '一径草深迷路，万点花飞到天。明日定知春去，祇今便是残年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春尽同诸公游紫岩各赋六言' AND p.poem_author = '吴芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋夜宿殊胜寺', '李时行', '明代', '看竹过山寺，开樽值素秋。风清众籁寂，水落寒岩幽。\n\n僧定月当户，鹤归云满楼。醉来卧松石，天地等浮沤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋夜宿殊胜寺' AND p.poem_author = '李时行';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送张黄门经载使云贵', '罗钦顺', '明代', '峥嵘双阙中霄起，谏垣近在红云里。元气潜随北斗移，龙司出内虞廷理。\n\n地分清切须英豪，遐想虞廷梦亦劳。簪缨于我诚何有，却恐言高位不高。\n\n同年磊落张经载，封事频投心欲惫。弘恭恻目惮更生，潞公敛衽钦唐介。\n\n世道明须我辈扶，当机缘底太模糊。轻裘骏马长安道，合有人间大丈夫。\n\n如君夙夜宜青琐，春风忽泛湖南舸。黯薄淮阳计不疏，褒求金马谋全左。\n\n也知今日重安边，边务惟应足食先。要令万灶貔貅饱，须杜千仓雀鼠穿。\n\n青袍拂曙辞金殿，出门步步频留恋。已料先声动五溪，即看行色摇芳甸。\n\n日暖官河柳絮飞，清尊欲尽思依依。往来万里多闻见，奏草能令在外稀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送张黄门经载使云贵' AND p.poem_author = '罗钦顺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书房', '戴炳', '宋代', '书房清晓焚香坐，转觉幽栖趣味真。怪石一根云态度，早梅半树雪精神。\n\n池鱼自乐谁知我，林鸟相忘不避人。得丧由来天自定，莫将闲虑恼闲身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书房' AND p.poem_author = '戴炳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史八首·黔娄妻', '蒲寿宬', '宋代', '明知正不足，不若斜有馀。\n破衾有何好，锦绣乃不如。\n卓哉归人言，贤于五车书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史八首·黔娄妻' AND p.poem_author = '蒲寿宬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('漫兴 其四', '林占梅', '清代', '饭馀聊息苦吟身，学罢熊经学鸟伸。晴日半窗花影碎，凉阴一院蝉声频。\n\n闭门但作仇书客，入座时为战茗人。漫道悠悠过岁月，閒中随处见天真。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '漫兴 其四' AND p.poem_author = '林占梅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('除夕和陈峰湖', '黄衷', '明代', '尘世都交等大傩，微名应未怨蹉跎。灯花夜色寻常动，榆荚春光积渐多。\n\n霜里乌啼天已白，眼前民瘼鬒先皤。丁宁莫作罗浮梦，惭愧山中看奕柯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '除夕和陈峰湖' AND p.poem_author = '黄衷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄菊二十首', '史铸', '宋代', '满地黄花得意秋，移来庭槛助清幽。\n自级禀性天生异，不与繁华混一流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄菊二十首' AND p.poem_author = '史铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清明诗', '赵鼎', '宋代', '乡书难附北归云，燕子犹寻旧主人。流水迢迢长念远，飞花糁糁又伤春。\n\n向来轩冕非吾意，何处园林托此身。只有长歌一樽酒，暮年风味最情亲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清明诗' AND p.poem_author = '赵鼎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·莺掷垂杨', '李久善', '宋代', '莺掷垂杨，一点黄金溜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·莺掷垂杨' AND p.poem_author = '李久善';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暇日寓怀寄朝中亲友', '薛能', '唐代', '命与才违岂自由，我身何负我身愁。临生白发方监郡， \n 遥耻青衣懒上楼。过客闷嫌疏妓乐，小儿憨爱□貔貅。 \n 闲吟一寄清朝侣，未必淮阴不拜侯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暇日寓怀寄朝中亲友' AND p.poem_author = '薛能';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('兰溪郊行', '曹伯启', '元代', '羸骖乘暇阅山乡，风景无边眼力强。千里稻云蒸大冶，一年梅澍积深塘。\n\n虎狼窜伏天刑近，鸡犬舒徐日驭长。微禄每惭无补报，欲将心事效平阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '兰溪郊行' AND p.poem_author = '曹伯启';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丙午乡试领荐乡人聚观于会江门外马上口占一绝', '邹智', '明代', '龙泉庵上苦书生，偶窃三巴第一名。天下许多难了事，乡人何用太相惊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丙午乡试领荐乡人聚观于会江门外马上口占一绝' AND p.poem_author = '邹智';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题烟波泛舟图', '刘基', '明代', '旧游忆鼓湘湖棹，日净风微江练平。\n小艇曲穿花底出，游鱼相伴镜中行。\n别来漫想心徒切，画里重看眼亦明。\n素石苍松是何处，愿从巢父濯冠缨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题烟波泛舟图' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('为超然道人作云卧庵 其一', '韩驹', '宋代', '窣堵西头屋数楹，知君卧占一溪云。老夫亦有缘云兴，应为情亲肯见分。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '为超然道人作云卧庵 其一' AND p.poem_author = '韩驹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('證道歌 其四十五', '释印肃', '宋代', '调古神清风自高，忘荣傲世性坚牢。示一往还无个事，见人摇手莫忉忉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '證道歌 其四十五' AND p.poem_author = '释印肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('村姑二首 其一', '宋伯仁', '宋代', '翠鬟双妥未梳头，纺纬车边坐欲羞。几度采桑归较晚，阿娘疑看落花愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '村姑二首 其一' AND p.poem_author = '宋伯仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐　四月十夜坐肖处作《语不得语歌》，十一夜追赋，其年韵', '卢青山', '当代', '棋茶都罢，几句家常话。最好相看千哑哑，一任腹中涛打。\n\n春窗月泻烟笼，零零碎碎时钟。忽尔一声长叹，索然处汝霜风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐　四月十夜坐肖处作《语不得语歌》，十一夜追赋，其年韵' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('减字木兰花 其二十二', '沈瀛', '宋代', '琴心和止。姹女与君相对喜。窗牖藏风。每唤其名应即通。\n\n玉英金酒。更唤黄婆同饮寿。莫讳人何。见说婴儿屋里多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '减字木兰花 其二十二' AND p.poem_author = '沈瀛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('首夏即事与丘与权同韵作', '苏颂', '宋代', '朱曦渐永烦暑添，薰风当昼飘前檐。\n庭幽门邃搴帷帘，景物轩豁欣窥觇。\n方池绿莹波文恬，两傍森森生苇蒹。\n新荷未展排青尖，上下交映开鉴奁。\n园林果实繁李棎，原野麦秀胜稻稴。\n群飞众走羽毛彡，求阴息影愁烹焰。\n江南郁蒸非类痁，时虽早热人心恹。\n忻忻笑语喧闾阎，言此丰岁将饫餍。\n正阳用事何太廉，乃使阴沴相陵詹。\n正当汗浃絺衣粘，凄风忽生增纩缣。\n淫霖旬日横流沾，市井郊郭皆渰淹。\n林实坠落谁撦挦，麻麦散乱如删鎌。\n斯民愁嗟言成谵，我时忧思坐间檐。\n方食不知味苦甜，整齐几案抽书签。\n发策一以天人占，少阴乘阳时最嫌。\n小人当此多欺憸，君子遇之难怀谦。\n天道虽远诚可瞻，上曰高明下沈潜。\n四时中分寒与炎，一气不可相并兼。\n推本事理知悉纤，灾害所起由渍渐。\n岂非奸孽当除歼，又非直道伤诐譣。\n孰居鼎鼐调梅盐，孰任阃闑怀韬吟。\n圣皇言动谋於佥，布为利泽濡苍黔。\n将消祲沴频深砭，感召冲气安危阽。\n嗟嗟直口不可钳，谁当一探龙颔髯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '首夏即事与丘与权同韵作' AND p.poem_author = '苏颂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('淮阴寄门人赖韦兼酬诸生', '魏禧', '清代', '闻说淮东形势地，三城万瓦夹江滨。小山赋后谁招隐，漂母祠前早闭门。\n\n日月苦消行路客，篮舆长忆执经人。深秋木叶知多少，扫径相迟薜荔村。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '淮阴寄门人赖韦兼酬诸生' AND p.poem_author = '魏禧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('柳条', '屈大均', '明代', '柳条长不已，总是欲牵肠。历乱还飞絮，氤氲更作香。\n\n无情化萍藻，有意拂鸳鸯。攀折那能去，依依此夕汤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '柳条' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和虞沧江赋梅 其五', '吴泳', '宋代', '吟成亟取夜钟敲，淡月笼窗昏晓交。真态莫将形色看，当如相马得蒲梢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和虞沧江赋梅 其五' AND p.poem_author = '吴泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('田家岁晚', '张侃', '宋代', '田家舂米盛土仓，祠灶新鲙鲤与鲂。粥分口数顾长健，不卖痴呆侬自当。\n\n爇火照天田蚕好，打灰如愿从所祷。一声竹爆阳春回，城里看灯归已晓。\n\n我生把笔作耕锄，年馀三十腹空虚。不如尔农随分足，只怕门前人催租。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '田家岁晚' AND p.poem_author = '张侃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和薛仲止渔村杂诗十首 其四', '刘黻', '宋代', '非远城中欲避尘，渔村邻里笑言真。自从范子扁舟后，肯著蓑衣有几人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和薛仲止渔村杂诗十首 其四' AND p.poem_author = '刘黻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山家', '陈毓秀', '清代', '陡绝忽夷旷，山农占几家。远峰青露髻，晚稻白开花。\n\n沙软牛羊卧，溪深鹅鸭哗。亭能宽著我，坐此揽烟霞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山家' AND p.poem_author = '陈毓秀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('疟起舍弟尚未已示道原', '王安石', '宋代', '侧足呻吟地，连甍瘴疟秋。\n穷乡医自绌，小市药难求。\n肝胆疑俱破，筋骸漫独瘳。\n惭君远从我，契阔每同忧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '疟起舍弟尚未已示道原' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗 其三', '李时勉', '明代', '麋鹿食田谷，自向田中聚。饱来山上眠，岂念耕者苦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗 其三' AND p.poem_author = '李时勉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游龙子祠', '董文涣', '清代', '清溪路尽只桃花，茅舍无多逐岸斜。偶趁樵风忘路远，眼随飞絮过邻家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游龙子祠' AND p.poem_author = '董文涣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶吟', '白居易', '唐代', '好官病免曾三度，散地归休已七年。老自退闲非世弃， \n 贫蒙强健是天怜。韦荆南去留春服，王侍中来乞酒钱。 \n 便得一年生计足，与君美食复甘眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶吟' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金缕曲', '金兆蕃', '清代', '谁谓无神助。谢封姨、回帆送到，行舟留住。纵目南楼年最少，便已头颅如许。\n\n又何况、当时琳瑀。屈指晨星犹有几，只尊前、磊落人三五。\n\n今昔恨，那堪诉。\n\n征袍今昔殊缁素。定难分、江头涕泪，洛中尘土。茗盏诗囊相料理，怕道须溪春去。\n\n更青兕、几番风雨。莫话年来经历事，枉茹冰、饮雪论辛苦。\n\n将进酒，为君舞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金缕曲' AND p.poem_author = '金兆蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄题宇文之邵公南止亭', '冯山', '宋代', '公南九亭名止止，亭不妄作名何为。群公赋咏得深趣，清绝正与斯人宜。\n\n铺张止义到无说，使我下笔先迟疑。圣贤出处无定辙，俯仰轻重争毫釐。\n\n云行非行止非止，由赐狂病渊骞痴。公南少年负才术，试仕吐出胸中奇。\n\n一言龃龉便投袂，自道岂欲求人知。公卿文章强且起，举手谢绝无还期。\n\n传家万卷书史乐，负郭五里松楸悲。岷峨嘉景照研席，事搅辄醉醒仍诗。\n\n有时日晏卧不动，郁郁经济埋如脾。\n\n太师竹洞枕温落，龙图药圃临清伊。二公止迹不止道，力与名教相扶持。\n\n今君所处近伊洛，道在不必分高卑。文章自可敌行事，荀孟皆我知为谁。\n\n亭非俗亭止非止，人物不到西南欺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄题宇文之邵公南止亭' AND p.poem_author = '冯山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('园景十二咏 其八 牡丹台', '胤禛', '清代', '叠云层石秀，曲水绕台斜。天下无双品，人间第一花。\n\n艳宜金谷赏，名重洛阳夸。国色谁堪并，仙裳锦作霞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '园景十二咏 其八 牡丹台' AND p.poem_author = '胤禛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山馆', '潘玙', '宋代', '山馆坐秋雨，风吹霁景开。\n夕阳明远水，落叶走空阶。\n白发人谁健，黄花节又催。\n看云动孤酌，聊以尉吟怀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山馆' AND p.poem_author = '潘玙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('刊名', '卢若腾', '明代', '我生大乱际，不幸兼两累；人识我姓名，我复识文字。\n\n虽无金石词，亦或动痂嗜；而皮裹阳秋，未免触猜忌。\n\n耿耿王烈妇，从容死就义；立碑表贞姱，叙述颇详备。\n\n巍巍太武山，孕毓多瑰异；警句颂山灵，标之山头寺。\n\n我名署其后，今皆遭劓刖。若笑文字劣，何不以名示？\n\n姓名果不祥，何不并人弃？阴阳避就间，毕竟同儿戏。\n\n木伐迹且削，大圣有斯事；似我今所遭，未须生忿恚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '刊名' AND p.poem_author = '卢若腾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送王嘉叟编修出佐南昌', '陆游', '宋代', '玉殿求衣早，鸾台退食迟。\n君看多故日，宁是弃言时。\n小作南州计，方观急诏追。\n归来上霄汉，莫遣此心移。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送王嘉叟编修出佐南昌' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠汕头工艺美术陈列馆', '老舍', '现代', '潮汕文化最风流，\n虹彩霞光映碧秋。\n品罢功夫茶几盏，\n欣看珠玉满琼楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠汕头工艺美术陈列馆' AND p.poem_author = '老舍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过洞庭', '张镛', '清代', '楚望无崖说洞庭，桃花春涨杳冥冥。巴陵地失波中白，彭蠡湖边天上青。\n\n不见帆樯惟北斗，即无风雨亦南溟。此身恍惚如春梦，愁绝君山渺一星。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过洞庭' AND p.poem_author = '张镛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('月中柳　湖上春行，同毛稚黄作', '沈谦', '明代', '少年曾共踏青游。酒满十三楼。香尘不断吼骅骝。\n\n芳草蓝深，夭桃红浅，白了人头。\n\n山如屏障周遭在，难抵住、一段闲愁。停杯无语思悠悠。\n\n飞絮蒙天，游丝著地，不要遮留。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '月中柳　湖上春行，同毛稚黄作' AND p.poem_author = '沈谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过长安车中口占', '秦鸿', '当代', '太华依稀迟曙色，长安仿佛负唐暄。班扬李杜千秋下，遥望车流尚武门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过长安车中口占' AND p.poem_author = '秦鸿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其六', '释延寿', '宋代', '绕绣屏飞花外蝶，隔金笼语柳中莺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其六' AND p.poem_author = '释延寿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送人', '释德洪', '宋代', '相送复相别，不异云间月。无心去复来，有魄圆还缺。\n\n此别兴何如，西风秋月初。暮鸿千里至，能寄八行书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送人' AND p.poem_author = '释德洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元丰己未三院东阁作·己未九月予赴鞫御史闻', '苏颂', '宋代', '早年相值浙江边，多见新诗到处传。\n楼上金蛇惊妙句，卷中腰鼓伏长篇。\n仳离岁月流如水，抑郁情怀积似烟。\n今日柏台相望处，隔垣音响莫由宣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元丰己未三院东阁作·己未九月予赴鞫御史闻' AND p.poem_author = '苏颂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留别安庆李太守', '储光羲', '唐代', '明牧念行子，又言悲解携。初筵方落日，醉止到鸣鸡。 \n 过客来自北，大军居在西。丘家如讨逆，敢以庶盘溪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留别安庆李太守' AND p.poem_author = '储光羲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游麻姑山', '李潜真', '宋代', '凌晨特跨赤龙车，御气乘风下九衢。\n金阙殿前朝玉帝，丹霞洞口谒麻姑。\n朱弦未达钟期耳，青鸟空传汉殿书。\n铁笛一声谁会得，独飞踪迹到仙都。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游麻姑山' AND p.poem_author = '李潜真';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郭山人游囊杂咏六首 其六 觚', '欧大任', '明代', '山都洗我觚，贮月饮涧下。风来吹有声，笑学昔人挂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郭山人游囊杂咏六首 其六 觚' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上方峰', '王履', '明代', '金仙不可觅，徙倚娑罗阴。\n壁底野情重，峰端烟树深。\n暗凭悬锁处，遥寄上云心。\n待念飞黄子，忘形却试寻。\n铁锁高悬直壁青，上方形胜杳冥冥。\n西玄空通隔世路，金仙已跨摩云翎。\n觱沸音中怅年晚，娑罗影里问谁经。\n爱河未上超然岸，只到峰根看画屏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上方峰' AND p.poem_author = '王履';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绝句', '罗元贞', '近代', '风狂雨暴肆摧残，百孔千疮共黯然！一举十年成浩劫，盖棺功罪果空前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绝句' AND p.poem_author = '罗元贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寓意', '郑崐', '明代', '锦衣公子意翩翩，下马人争接玉鞭。\n昔日青娥今白发，强操檀板向歌筵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寓意' AND p.poem_author = '郑崐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('食笋时方正月 其二', '袁宏道', '明代', '縠水温风解冻时，家家馔得雪玻璃。凭将野意酬君子，饱食西窗读楚辞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '食笋时方正月 其二' AND p.poem_author = '袁宏道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('复斋奚左藏挂冠 其二', '释居简', '宋代', '特操刚明与俗乖，溪山亦复外形骸。子狂正作岂矫世，我醉欲眠聊纵怀。\n\n勇赋一归尤果决，光寒千丈不沉埋。从来林下何曾见，仅有先生闼可排。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '复斋奚左藏挂冠 其二' AND p.poem_author = '释居简';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游峨岭遂至赵秋谷饴山旧园', '赵国华', '清代', '四山松影罨城庐，一路泉声曳笋舆。南郭堞横青黛里，北亭觞尽白头余。\n\n几人下马寻秋草，当日谭龙已索居。太息荆坡无恙在，未应竟自付樵渔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游峨岭遂至赵秋谷饴山旧园' AND p.poem_author = '赵国华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('除夕', '王铚', '宋代', '一岁尽今夕，既往那可追。\n疏梅吐幽艳，轻冰释寒澌。\n新陈自相代，长年万古悲。\n亦复强取醉，椒盘杂儿嬉。\n天回万象春，除尽群阴卑。\n地除众枯槁，从今作华滋。\n一除不可复，绿发成鬓丝。\n此是有尽处，那知无尽时。\n凡所未除者，所愿皆除之。\n晚景安分守，幻身绝思维。\n生死我所明，圣贤吾所师。\n优游观物变，翼戢仍鲜差。\n山岳惟尘尔，寸心不可移。\n浩歌自达晓，自信何用疑。\n楼头画角声，已逐东风吹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '除夕' AND p.poem_author = '王铚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和子瞻沿牒京口忆西湖寒食出游见寄二首', '陈襄', '宋代', '春阴漠漠燕飞飞，可惜春光与子违。\n半岭烟霞红旆入，满湖风月画船归。\n缑笙一阕人何在，辽鹤重来事已非。\n犹忆去年题别处，鸟啼花落客沾衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和子瞻沿牒京口忆西湖寒食出游见寄二首' AND p.poem_author = '陈襄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归途次韵', '黄彦平', '宋代', '寒食犹须数日间，楚亭才隔几重山。\n归时合有桃花否，试擘华笺问曲栏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归途次韵' AND p.poem_author = '黄彦平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('子夜歌十二首 其八', '于慎行', '明代', '谁令冰不寒，谁令火不热。雨霜涂前除，侬思底得绝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '子夜歌十二首 其八' AND p.poem_author = '于慎行';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望祀蓬莱', '林希逸', '宋代', '祀事非常典，君王望紫蓬。仗从天阙下，山在水云中。\n\n采药何时返，鸣鞘秩礼隆。灵无先沛雨，船有引回风。\n\n夷见燔柴去，仙难架海通。札书终不验，空翠锁祠宫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望祀蓬莱' AND p.poem_author = '林希逸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元宵中都太守放灯作律诗五首 其五', '郑真', '明代', '烛花暗结竹窗低，星月光寒思欲迷。深念老兄居海峤，更怜舍弟客青齐。\n\n云天杳杳王乔鹤，草屋栖栖祖逖鸡。想见孱然小儿女，凄凉慈母共中闺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元宵中都太守放灯作律诗五首 其五' AND p.poem_author = '郑真';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂十七首', '释师范', '宋代', '诸佛不出世，祖师不西来。\n颟顸一句子，南岳对天台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂十七首' AND p.poem_author = '释师范';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岁暮绝句四首', '晁说之', '宋代', '迟迟来日去何疾，六十五见此日除。\n明发束修能有几，太平田舍读残书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岁暮绝句四首' AND p.poem_author = '晁说之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽河东夫人', '龚鼎孳', '明代', '岂少完人传，如君论定稀。朱颜原独立，白首果同归。\n\n绝脰心方见，齐牢宠不非。可怜共命鸟，犹逐绛云飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽河东夫人' AND p.poem_author = '龚鼎孳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谩成三首 其三', '阮阅', '宋代', '太白仙人白玉篇，逸才清思两难全。如今貂尾容相续，只恐巴吟不足传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谩成三首 其三' AND p.poem_author = '阮阅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐 当湖秋泛', '黄燮清', '清代', '旧游在否。零落双红袖。水阁疏廊仍种柳。柳是十年前有。\n\n一枝枝舻横塘。一声声笛邻墙。一点点蘋秋意，一丝丝蓼斜阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐 当湖秋泛' AND p.poem_author = '黄燮清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丑奴儿慢二首 其一 见榴花作', '张惠言', '清代', '柳绵吹尽，楼外旧愁如梦。又镇日门随雨闭，帘借烟笼、却怕凭阑，相思无字问残红。\n\n新阴绿处，几时轻逗，芳意千重。玉勒俊游，从他幽独，不到山中。\n\n况满地、浮英浪药，还做春容。只有斜阳，年年识得换熏风。\n\n春余心事，凭将杜宇，深诉花工。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丑奴儿慢二首 其一 见榴花作' AND p.poem_author = '张惠言';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自安仁至豫章途中杂兴十九首 其二', '赵蕃', '宋代', '漠漠平芜远际天，青山若个暗霾烟。行人更说桥新断，试遣招呼与借船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自安仁至豫章途中杂兴十九首 其二' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢朱推梅栽', '胡寅', '宋代', '南国虽云有学堂，了无松菊径徒荒。\n瘴痕元爱冰花洗，衰鬓聊依玉树芳。\n便觉小池招秀影，更令寒月映新妆。\n从今剩醖萸香酒，指拟春风摘子尝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢朱推梅栽' AND p.poem_author = '胡寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('北游诗二十一首 其三 立秋', '张元凯', '明代', '蝉声呜咽柳阴残，节序惊心强自宽。把盏沧江忘日暮，湿衣清露动宵寒。\n\n凉风汉苑悲团扇，明月湘皋泣紫兰。最是关河摇落易，天涯无奈欲归难。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '北游诗二十一首 其三 立秋' AND p.poem_author = '张元凯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('刘明远会宿翁灵舒西斋', '徐照', '宋代', '秋色侵肌骨，还将鬓色侵。\n自来难会宿，安得废清吟。\n竹露滋丛菊，邻钟觉曙禽。\n城中同此月，不起故山心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '刘明远会宿翁灵舒西斋' AND p.poem_author = '徐照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('为《白鹤滩日记》杀青 其二', '张伯元', '当代', '我有一张琴，寻常不发音。每当秋水静，来印碧潭心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '为《白鹤滩日记》杀青 其二' AND p.poem_author = '张伯元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('彭蠡湖乡思', '谭以良', '明代', '肠断南天欲尽头，紫荆无语对高楼。还将病眼三更泪，滴破沧浪万里流。\n\n湖雁一声彭蠡月，梅花三度象城秋。倚门定有慈颜望，曾着斑衣此日否。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '彭蠡湖乡思' AND p.poem_author = '谭以良';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('严滩过子陵钓台', '慧霖', '清代', '自著羊裘老富春，画工辛苦绘功臣。先生到处堪高隐，天上宵来卧故人。\n\n七里江声终不断，四围水鸟亦相亲。利名淘尽尘中事，留得乾坤一钓纶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '严滩过子陵钓台' AND p.poem_author = '慧霖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆梅和韵', '毕慧', '清代', '记得孤山竹外阴，横斜水畔径深深。南枝梦断空明月，东阁诗成见素心。\n\n腊雪乍添新艳采，春风仍到故园林。冷香得句愁难和，合付金徽托远音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆梅和韵' AND p.poem_author = '毕慧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金刚随机无尽颂·叹仰流通', '释印肃', '宋代', '江上数峰青，露出卷心经。\n明明没个字，向道祗如今。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金刚随机无尽颂·叹仰流通' AND p.poem_author = '释印肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过武山览余襄公候潮处', '苏亦堪', '明代', '万派朝宗水直催，襄公曾此候潮来。乘风势涌翻鳌呿，映日光涵漾蚌胎。\n\n二气吹嘘穷睇眄，四贤勋业极崔嵬。临流慨想遗徽在，龙穴风生雪浪开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过武山览余襄公候潮处' AND p.poem_author = '苏亦堪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐', '朱雍', '宋代', '雪开瑶径。素蕊迎春影。楼上玉声三弄定。无奈幽香翻阵。 \n 凌晨不事铅华。化工却付春花。流水残阳江上，清随月色低斜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐' AND p.poem_author = '朱雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六十初度自寿四首 其二 阮郎归', '王鏊', '明代', '行年六十鬓斓斑。皇恩特放还。高堂设席对青山。\n\n秋来正未閒。\n\n阴忽霁，暑新寒。笙歌夜未阑。傍人莫笑老嗤顽。人生到此难。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六十初度自寿四首 其二 阮郎归' AND p.poem_author = '王鏊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋怀', '欧阳修', '宋代', '节物岂不好，秋怀何黯然！\n西风酒旗市，细雨菊花天。\n感事悲双鬓，包羞食万钱。\n鹿车何日驾，归去颍东田。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋怀' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('墨池', '宋京', '宋代', '君不见子云草玄西郭门，一径秋草间朝昏。何须笔冢高百尺，池墨黯黯今犹存。\n\n童乌侯巴竟零落，玄学无人终寂寞。汉家执戟知几年，垂老身没天禄阁。\n\n俗儿纷纷重刘向，思苦言艰动嘲谤。汉已中天雄亦亡，不较空文从覆酱。\n\n如今却作给孤园，吐凤亭前池水寒。安得斯人尚可作，会有奇字令君看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '墨池' AND p.poem_author = '宋京';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('马逸', '聂绀弩', '现代', '脱缰羸马也难追，赛跑浑如兔与龟。\n无噩无嘉无话喊，越追越远越心灰。\n苍茫暮色迷奔影，斑白老军叹逝骓。\n今夕塞翁真失马，倘非马会自行归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '马逸' AND p.poem_author = '聂绀弩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题何德儒所藏顾周道水石图', '谢肃', '明代', '沄沄石下波，郁郁波上林。过桥仙客忽长啸，一鹤来自蓬山岑。\n\n蓬山岑，不难至。聊栖瀛海内，自适沧洲意。恍如出硖石，群枫落影洪流碧。\n\n又似泊金山，回潮激树崩厓间。江淮风景真绝奇，来往扁舟荫清樾。\n\n鸟飞鱼泳醉吟中，回首兹游几秋月。虎头子，天机精，剪彼水石来轩楹。\n\n使我一见气峥嵘，龙蛇起陆雷霆惊。尔宜藏此画，慎莫时时挂。\n\n光气一冲天，超然便神化。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题何德儒所藏顾周道水石图' AND p.poem_author = '谢肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('飞来寺 其一', '郭棐', '明代', '扁舟又度飞来寺，惭见江鸥数往回。览胜沈卿原有赋，留题罗隐是仙才。\n\n层崖古树云同绽，绝壁悬流雪作堆。如此山川足行乐，几时高步钓鱼台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '飞来寺 其一' AND p.poem_author = '郭棐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送李经', '李纯甫', '金朝', '髯张元是人中雄，喜如俊鹘盘秋空。怒如怪兽拔古松，老我不敢婴其锋。\n\n更著短周时缓颊，智囊无底眼如月。斫头不屈面如铁，一说未穷复一说。\n\n勍敌相扼已铮铮，二豪同军又连衡。屏山直欲把降旌，不意人间有阿经。\n\n阿经瑰奇天下士，笔头风雨三千字。醉倒谪仙元不死，时借奇兵攻二子。\n\n纵饮高歌燕市中，相视一笑生春风。人憎鬼妒愁天公，径夺吾弟还辽东。\n\n短周醉别默无语，髯张亦作冲冠怒。阿经老泪如秋雨，只有屏山拔剑舞。\n\n拔剑舞，击剑歌，人非麋鹿将如何。秋天万里一明月，西风吹梦飞关河。\n\n此心耿耿轩辕镜，底用儿女肩相摩。有智无智三十里，眉睫之间见吾弟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送李经' AND p.poem_author = '李纯甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '谌祜', '宋代', '隔云烽火山河旧，列土旌旗雨露深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '谌祜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南朝', '石延年', '宋代', '南朝人物尽清贤，不是风流即放言。三百年间却堪笑，绝无人可定中原。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南朝' AND p.poem_author = '石延年';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('立春日胥江驿东方舟友人时丁未冬十二月二十一日也 其一', '张萱', '明代', '阔岸移青翰，荒邮滞碧幢。已知春信好，渐觉病魔降。\n\n土脉占微动，鸥群泛自双。一尊聊共适，落日尚牵江。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '立春日胥江驿东方舟友人时丁未冬十二月二十一日也 其一' AND p.poem_author = '张萱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('碧云即事', '刘宰', '宋代', '块坐经年不入山，山僮拍手笑衰颜。\n登高犹喜心期在，望远还惊目力悭。\n云气苍茫自羁旅，烟波飘荡几惸鳏。\n朝来旧雨添新雨，谁识安危指顾间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '碧云即事' AND p.poem_author = '刘宰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀翁宏', '王元', '唐代', '独夜思君切，无人知此情。沧州归未得，华发别来生。 \n 孤馆木初落，高空月正明。远书多隔岁，独念没前程。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀翁宏' AND p.poem_author = '王元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其二', '张致远', '宋代', '三寺楼台烟雾里，一川芦苇画图中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其二' AND p.poem_author = '张致远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜半闻雨声清甚', '韩淲', '宋代', '雨声催我梦华胥，清气于人便有馀。惟适之安非素隐，不容何病是閒居。\n\n茶烟未了归真觉，香雾初横切太虚。却忆华山陈处士，惘然推枕听阶除。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜半闻雨声清甚' AND p.poem_author = '韩淲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('村居杂兴六首 其六', '顾清', '明代', '灵均沈湘陶令死，篱下寒香久无主。江边一笑倚清秋，烂漫西风几今古。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '村居杂兴六首 其六' AND p.poem_author = '顾清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题高君宝绀泉', '文天祥', '宋代', '渟渟岩下泓，澄碧落梧影。\n寒瑶披清飙，残月照濎濙。\n俯渊测浮云，流日荡苕颖。\n向来沧浪歌，孺子不可诇。\n载沾衣上尘，怀古意深永。\n招招素心人，相期发深省。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题高君宝绀泉' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈四首 其三', '释思慧', '宋代', '一切法无差，云门胡饼赵州茶。黄鹤楼中吹玉笛，江城五月落梅花。\n\n惭愧太原孚上座，五更闻鼓角，天晓弄琵琶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈四首 其三' AND p.poem_author = '释思慧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送李运使学士赴阙十咏 其四', '赵抃', '宋代', '压境号民苏，连甍竞乐输。万桑丰岁计，一节赴朝趋。\n\n安稳舟无恙，雍容骑甚都。赠言聊纪盛，为颂愧非夫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送李运使学士赴阙十咏 其四' AND p.poem_author = '赵抃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('马上见卖白莲者三首 其一', '陈造', '宋代', '引息度奇暑，风日正交战。淮乡六月春，嫣然担头见。\n\n香凝素囊拆，湿馀清露泫。丰肤专正色，一忠百佞贱。\n\n祝融乃司花，慰我红尘面。买归一杯适，得共黄葵荐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '马上见卖白莲者三首 其一' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和张仁溥赋雪', '吴泳', '宋代', '北风声熄南山微，谁息风雅呼於时。\n歌黄三章未纯古，叙白一段空爱奇。\n台高皆羡雨花落，檐短独愁冰柱垂。\n墨客如林笔如冢，莫於诗上更题诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和张仁溥赋雪' AND p.poem_author = '吴泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过未央宫遗址', '程诰', '明代', '木落汉宫秋，寒虫苦悲咽。\n君看草色丹，犹染淮阴血。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过未央宫遗址' AND p.poem_author = '程诰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('少年游·庐山瑶草四时春', '晁补之', '宋代', '庐山瑶草四时春。烟锁上宫门。记得南游，偶寻飞涧，一洗庾公尘。 \n 香炉高咏君家事，文彩近前人。它日骑鲸，尚怜迷路，与问众仙真。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '少年游·庐山瑶草四时春' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丙申江右上巳年会适十周年雅集奉和熊社', '李映斌', '当代', '独抱骚心不可降，十年鸥影掠沧江。幽兰翠渚鱼吹浪，高阁朱华气溢窗。\n\n尚古歌吟遗劫烬，隔尘山水驻仙邦。弟兄远志酬何易，但有良宵潋滟缸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丙申江右上巳年会适十周年雅集奉和熊社' AND p.poem_author = '李映斌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉和袭美太湖诗二十首。孤园寺', '陆龟蒙', '唐代', '浮屠从西来，事者极梁武。岩幽与水曲，结构无遗土。 \n 穷山林干尽，竭海珠玑聚。况即侍从臣，敢爱烟波坞。 \n 幡条玉龙扣，殿角金虬舞。释子厌楼台，生人露风雨。 \n 今来四百载，像设藏云浦。轻鸽乱驯鸥，鸣钟和朝橹。 \n 庭蕉裂旗旆，野蔓差缨组。石上解空人，窗前听经虎。 \n 林虚叶如织，水净沙堪数。遍问得中天，归修释迦谱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉和袭美太湖诗二十首。孤园寺' AND p.poem_author = '陆龟蒙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('正月十八日甘棠院 其一', '蔡襄', '宋代', '上元才过去寻春，红白山花粲粲新。似喜使君初病起，隔栏相向笑迎人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '正月十八日甘棠院 其一' AND p.poem_author = '蔡襄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('京邸忆卿云洞作', '齐彦槐', '清代', '大道径其上，大川贯其中。洞门高十丈，跨水如长虹。\n\n绝壁柏倒垂，托根自鸿濛。岂有雨露到，万古常青葱。\n\n人经乱流间，小语铿洪钟。似掌一片石，宽可百余弓。\n\n名曰仙人田，阡陌横且纵。仙人犹力耕，我辈胡独慵。\n\n田尽得井穴，烛之光熊熊。深窈不可测，或是蛟龙宫。\n\n涉险生归心，西入出从东。夕阳照湍濑，炯若金在镕。\n\n钟乳类飞禽，影动群翻风。此景别来久，追写不能工。\n\n何当饮云光，一洗尘埃胸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '京邸忆卿云洞作' AND p.poem_author = '齐彦槐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新除广东常平之节感恩书怀', '杨万里', '宋代', '巳愧双旌古晋陵，更堪一节古羊城。\n偶逢旧治年频熟，忽署新衔手尚生。\n山与君恩谁是重？身如秋叶不胜轻。\n向来百链今绕指，一寸丹心白日明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新除广东常平之节感恩书怀' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凤凰台上忆吹箫 感怀', '袁思古', '当代', '怨蕴离骚，人怀楚泽，先朝事误纵横。对新亭挥泪，消息堪惊。\n\n依旧天涯烽火，疆场未肯早休兵。江山肚、古今一辙，供给纷争。\n\n苍生。频年憔悴，到处是哀鸿，一片商声。叹渔樵歌断，怅望升平。\n\n人世红尘如梦，所争者、半是虚名。试问英雄多少，千古谁荣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凤凰台上忆吹箫 感怀' AND p.poem_author = '袁思古';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史二十七首 其十四', '王夫之', '明代', '代契丹憎延广，为司马爱谯周。一线容头活计，二毛肉袒风流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史二十七首 其十四' AND p.poem_author = '王夫之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中夜', '纪炅', '清代', '老话侵中夜，微霜落半秋。黄花知月令，白发恋人头。\n\n丹粒应难熟，笙歌最易休。弦光浑未湿，桂影叠山楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中夜' AND p.poem_author = '纪炅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宪圣慈烈皇后挽诗二首', '程珌', '宋代', '西浒俱来日，乐朝极盛时。\n彫弓平黑海，彩笔照丹墀。\n垄起先裁费，丹成不用医。\n人间空怅望，风月宴瑶池。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宪圣慈烈皇后挽诗二首' AND p.poem_author = '程珌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题无学卷兼柬三怀上人时同寓匡庐 其二', '邹元标', '明代', '持经为母到西台，五两风轻一苇开。月照蒲团猿鹤静，好骑白鹿再归来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题无学卷兼柬三怀上人时同寓匡庐 其二' AND p.poem_author = '邹元标';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗', '陈瓘', '宋代', '床头史记千番纸，世上兴亡一窖尘。\n惟有炳然周孔道，至今余泽浸生民。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗' AND p.poem_author = '陈瓘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天', '姬翼', '元代', '贩骨来来几万生。煎熬窟里谩峥嵘。百年不觉消疣赘，千载无能息劓黥。\n\n翻欲浪，起心兵。迷绳自缚聚愁城。几将浊水浇胸臆，倒语颠言贺太平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天' AND p.poem_author = '姬翼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游春', '张玉娘', '元代', '护槛花浓梦欲攲，五更清露锁寒扉。明朝恐负寻芳约，拂晓平瞻霁影依。\n\n贴翠自怜羞舞镜，送春无奈听啼规。金莲破藓留芳迹，梨萼翻风作雪飞。\n\n沙上晴凫窥浅渚，松边黄蝶绕疏篱。催吟片雨云俱黑，狂絮欺人故点衣。\n\n心事肯随流水尽，新愁不与酒尊宜。青梅已结梢头实，驿使难传陇外枝。\n\n笑折野花轻插鬓，却嫌溪柳妒修眉。因过竹院参禅意，觅得云林旧日诗。\n\n听彻游郎歌古调，停看渔父下苔矶。紫山迢递行应好，苍磴萦回出每迟。\n\n罗袖翩翩香气满，绿阴冉冉鸟声微。等閒无限伤春思，芳草天涯肠断时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游春' AND p.poem_author = '张玉娘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('紫薇花', '张鹏翮', '清代', '绿阴深处夕阳斜，烂漫还开两树花。晴日午风偏觉媚，红霞一片落谁家？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '紫薇花' AND p.poem_author = '张鹏翮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄德让病后苦吟因赋诗以释之', '徐贲', '元代', '不废诗篇病后身，思花怀月亦劳神。凭君暂歇行吟兴，药具方书正可亲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄德让病后苦吟因赋诗以释之' AND p.poem_author = '徐贲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题宾虹山水障', '黄节', '清代', '旧忆淞江经岁别，春阴无俚叹宾虹。生平能事都如此，浦溆渔舟着意工。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题宾虹山水障' AND p.poem_author = '黄节';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('顺风过湖二首', '项安世', '宋代', '维舟六日傍明山，待得风来始破颜。\n一抹平湖三十里，听渠微横未须关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '顺风过湖二首' AND p.poem_author = '项安世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('逍遥咏 其十四', '赵炅', '宋代', '燕雀不生凤，阴阳一气全。无穷深可及，境象理推迁。\n\n奚益其形化，平章语默玄。终身何所役，道本岂私焉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '逍遥咏 其十四' AND p.poem_author = '赵炅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送司训王恭之任闽清', '陈琏', '明代', '新拜儒官出帝京，过家奉檄为亲荣。方辞北阙三千里，此去南闽几月程。\n\n菡菼滩声和雨响，武夷山色与云平。闽清学者从来盛，坐拥皋比称宦情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送司训王恭之任闽清' AND p.poem_author = '陈琏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次徐漕韵贺留守刘观文祷雪感应', '许及之', '宋代', '雪霜之忍有至慈，一片到地五谷滋。所以腊中重三白，史讥失时书直辞。\n\n我公卧护北门北，百姓爱公如爱日。及冬祷雪乃爱民，若有鬼神宜率职。\n\n要晴要雨天必从，玉山何独閟烛龙。一夜风师擘冰絮，坐使东国成雪宫。\n\n晓起清愁无复有，如在春风饮醇酒。欲歌零雨劳公归，正尔补天须妙手。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次徐漕韵贺留守刘观文祷雪感应' AND p.poem_author = '许及之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏题重台梅', '张镃', '宋代', '只将单萼缀层花，弱骨丰肌自一家。\n载朵折来谁可称，宝钗双燕绿云斜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏题重台梅' AND p.poem_author = '张镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠皖山道士', '宋无', '宋代', '世人曾不识，头带树皮冠。\n间种药来卖，醉将琴去弹。\n鹤术仙果下，猿穷玉书看。\n莫服丹砂好，恐师生羽翰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠皖山道士' AND p.poem_author = '宋无';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('路入剡中作', '方干', '唐代', '截湾冲濑片帆通，高枕微吟到剡中。掠草并飞怜燕子， \n 停桡独饮学渔翁。波涛漫撼长潭月，杨柳斜牵一岸风。 \n 便拟乘槎应去得，仙源直恐接星东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '路入剡中作' AND p.poem_author = '方干';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('遣怀兼怀姜凤阿内翰二首 其一', '王樵', '明代', '浅疏难应俗，忧喜只随人。到处身如寄，何时我是真。\n\n兴来还自败，老去欲谁亲。回首高阳里，荀家有二仁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '遣怀兼怀姜凤阿内翰二首 其一' AND p.poem_author = '王樵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻里中有买得扶桑花者 其四', '徐渭', '明代', '鹤林寺里别袈裟，又幻扶桑到若耶。溪女惜香还菡萏，海人浇醉歇枇杷。\n\n似闻此地春犹雪，悔上孤帆晓载霞。腊社少年貂帽上，簪红莫忘遍茶花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻里中有买得扶桑花者 其四' AND p.poem_author = '徐渭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题兴宁县东文岭瀑泉，在夜明场驿之东', '杨万里', '宋代', '笋舆路转崖欹倾，只闻满山泉水鸣。\n卷书急看已半失，眼不停注耳细听。\n石如铁色黑，壁立镜面平。\n水从镜面一飞下，蕲笛织簟风漪生。\n石知水力倦半壁，锺作天一泓水行。\n到此欲小憩，後水忽至前水惊。\n分清裂白两泒出，跳珠跃雪双龙争。\n不知落处深几许，千丈井底碎玉声。\n安得好事者，泉上作小亭。\n酿泉为酒不用麴，春风吹作蒲萄绿。\n醉写泉声入枯木，何处更寻响泉曲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题兴宁县东文岭瀑泉，在夜明场驿之东' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('封太常博士丁公挽诗', '陈琏', '明代', '一自声名达九重，祇承敕命见褒崇。冰衔方睹容台秩，墓域俄成马鬣封。\n\n宿草萧萧经暮雨，白杨飒飒动悲风。无由远致生刍奠，引睇天南意不穷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '封太常博士丁公挽诗' AND p.poem_author = '陈琏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题元人名绘集锦卷 其六 赵丹林陆羽烹茶图', '弘历', '清代', '古弁先生茅屋间，课僮煮茗霅云閒。前溪不教浮烟艇，衡泌栖迟绝往还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题元人名绘集锦卷 其六 赵丹林陆羽烹茶图' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题三沙', '郯韶', '元代', '三洲宛在碧波中，海色晴霞绚烂红。夜半鸡鸣先见日，天边月晕又生风。\n\n鲛女机丝花隔雾，龙君城阙水为宫。谁持玉节寻真去，直过扶桑弱水东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题三沙' AND p.poem_author = '郯韶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('漫兴', '惺伯民', '近代', '鼙鼓中原震不宁，杜鹃啼血晚风腥。老天欲丧斯文未，劫运翻从改步丁。\n\n榴火薰人头转白，柳丝系我眼谁青。黄钟毁弃寻常事，闭户陶然醉六经。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '漫兴' AND p.poem_author = '惺伯民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和文与可洋川园池三十首 其十一 二乐榭', '苏轼', '宋代', '此间真趣岂容谈，二乐并君已是三。仁智更烦诃妄见，坐令鲁叟作瞿昙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和文与可洋川园池三十首 其十一 二乐榭' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('萧宅二三子赠答诗二十首。井请客', '卢仝', '唐代', '我生天地间，颇是往还数。已效炊爨劳，我亦不愿住。 \n 君有造化力，在君一降顾。我愿拔黄泉，轻举随君去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '萧宅二三子赠答诗二十首。井请客' AND p.poem_author = '卢仝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('相思歌', '霍与瑕', '明代', '楫舟下香山，行行翠微里。春尽夏方初，万绿檠新洗。\n\n点点绿中红，如珠缀云绮。借问道傍翁，云是相思子。\n\n昔有一佳人，望夫大江沚。相思复相思，相思无时已。\n\n閒倚相思根，泪滴相思底。东风送郁陶，挂作相思蕊。\n\n散作相思花，结作相思子。莹润比珊瑚，红琛斗洵美。\n\n从此落人间，缘鬟仍充耳。化石亦成台，古来诚有此。\n\n茉莉与素馨，馨香何足恃。嗟嗟此相思，千年心不死。\n\n我亦相思人，昔涉相思涘。曾唱相思歌，细写相思指。\n\n无路寄相思，空结相思痞。徘徊相思下，相思聊复尔。\n\n岁岁更年年，丹心照流水。湘竹已全斑，重华何日起。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '相思歌' AND p.poem_author = '霍与瑕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆秦娥 其二', '郑元昭', '清代', '雨潇潇。琐窗默坐愁春宵。愁春宵。离人情绪，红杏花梢。\n\n鱼书烟水愁迢迢。黛眉深浅无心描。无心描。容光易减，镜里昏朝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆秦娥 其二' AND p.poem_author = '郑元昭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('仲春', '吴涛', '宋代', '雨馀寒气浅，园林作春媚。不知海棠花，新来著花未。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '仲春' AND p.poem_author = '吴涛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又次韵', '张雨', '元代', '别后惊心岁已驰，几回草梦绕春池。新诗远寄迢遥驿，旧约重看绝妙碑。\n\n鳌禁风清班缀玉，龟溪雪冷鬓垂丝。何时共执论文酒，坐对西窗待月迟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又次韵' AND p.poem_author = '张雨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('廓然得石门信叹其踵席非其人用韵酬之二首 其一', '释德洪', '宋代', '相对天涯岁月新，石门消息远难真。乘闲且觅几场笑，疾恶休生一念瞋。\n\n衬鹭芙蕖方破暖，藏鸦柳色又残春。光阴如此空搔首，行诵知归倦鸟频。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '廓然得石门信叹其踵席非其人用韵酬之二首 其一' AND p.poem_author = '释德洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('相如二首 其二', '陈造', '宋代', '逸德狂情赖补苴，文君端合婿相如。白头曲里殷勤意，不愧先生谏猎书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '相如二首 其二' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('回首', '洪存恕', '近代', '回首此神州，纷争岁月稠。绾符雄割据，秉秫困诛求。\n\n鸟死功成羿，龙兴德迈周。野人何企羡，一饱抵封侯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '回首' AND p.poem_author = '洪存恕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杨员外', '时太初', '明代', '群盗南奔日月昏，诸公臣节不须论。白头惟有杨员外，不负从来天子恩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杨员外' AND p.poem_author = '时太初';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和永叔春雪', '刘攽', '宋代', '陬筒吹灰变冥朔，生气萌泉天不觉。凝阴忽升气横厉，重云大同势绵邈。\n\n通衢漫漫走流沙，近甸稍稍堆乔岳。焚炉姹女姿飞扬，匝野神奸谁彫琢。\n\n刀圭不惜透墙隙，捷业俄然垂屋角。户斜尺剑未及收，窗缺连环如可握。\n\n鲜妆宫女喜深印，红手庠童斗坚搦。暝鸡误晓屡咿咿，饥雀冲人犹啄啄。\n\n虽怜林篁有摧折，却喜陇苗就优渥。贫庐败褐憎破牖，富屋珍裘转深幄。\n\n使君高义仍泛爱，颍士多文方力学。猎师得隽鲜弃薧，厨酿荐甘清间浊。\n\n气随阳春破凝烈，巧夺钧工畏名貌。吾知郢人不复歌，古声比今为拙朴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和永叔春雪' AND p.poem_author = '刘攽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('罔极篇十四章 其八', '林恭祖', '当代', '嗟乎予弗子，羁角泣呱呱。壮岁飞流影，乡心绕玉壶。\n\n未听慈母语，长作浪人徒。回首悲何恃，天涯阮籍途。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '罔极篇十四章 其八' AND p.poem_author = '林恭祖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮（和令狐公子）', '王灼', '宋代', '风柔日薄江村路。一鞭又逐春光去。胡蝶作团飞。竹间桃李枝。 \n 醉魂招不得。一半随春色。桃李□无多。其如风日何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮（和令狐公子）' AND p.poem_author = '王灼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜雪', '范纯仁', '宋代', '久旸逢腊雪，酌酒动欢诚。密势迷城郭，馀霏冒栋楹。\n\n河光平曳练，岳色远堆琼。已报丰年瑞，三登贺太平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜雪' AND p.poem_author = '范纯仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠刀镊王诚三首 其二', '徐元杰', '宋代', '汝家住近里仁坊，不恋妻儿恋侍旁。父子性天非可夺，亲亲仁也盍揄扬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠刀镊王诚三首 其二' AND p.poem_author = '徐元杰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丹井陈子白母挽词二首 其一', '林亦之', '宋代', '哀曲梧桐夜，何年苜蓿盘。敬夫前辈重，好客妇人难。\n\n十月明朝尽，孤坟落日寒。鹿门催作黍，此意竟长叹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丹井陈子白母挽词二首 其一' AND p.poem_author = '林亦之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月 简于右任', '章士钊', '当代', '谁把诗余漫要，却惊句子难工。文章底事信天翁。\n\n天与还须人动。\n\n活法全凭悟入，骚心疑有神通。自怜头脑太冬烘。\n\n烘似烟花着梦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月 简于右任' AND p.poem_author = '章士钊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秦淮晚眺', '张翥', '元代', '赤栏桥下暮潮空，远火疏舂晻霭中。新月半天分落照，断云千里附归鸿。\n\n严城鼓角秋声早，故国山川王气终。莫讶时来一长望，越吟荆赋思无穷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秦淮晚眺' AND p.poem_author = '张翥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鸡鸣山短歌', '杜堮', '清代', '饮马下白登，挥辔出开平。每有早行人，至此闻鸡鸣。\n\n岧岧飞狐岭，黯黯沙城戍。亦有投止客，夜听鸡鸣去。\n\n鸡鸣星始稀，寒霜拂人衣。关河不可极，游子常怀悲。\n\n鸡鸣天下晓，西风吹白草。行路古今难，人共沙场老。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鸡鸣山短歌' AND p.poem_author = '杜堮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('越十日陪使君汪内翰复来', '黄公度', '宋代', '雅制初仍旧，佳名留至今。\n城依刺桐古，亭入芰荷深。\n尊俎宾僚集，旌麾刺史临。\n自公多暇日，及此豁尘襟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '越十日陪使君汪内翰复来' AND p.poem_author = '黄公度';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚登净远亭二首', '杨万里', '宋代', '重阳才过便新寒，去岁如今暑尚残。\n云外鴈来元不觉，一声唤我举头看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚登净远亭二首' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五福降中天 代寿赵次丈八十', '奭良', '清代', '万家生佛红云矗，赢得家家欢跃。蒱酒刚斟，桂轮犹满，嵩岳乔松蔚茂。\n\n画堂深静，只鸿案雍和，凤雏娇小。那有宾筵，客履淡淡旧怀抱。\n\n仿佛托根仙李，百三旬、压倒香山老。潞国精神，汾阳富贵，漫数东都梁灏。\n\n天锡纯嘏，一片婆心，吉星缭绕。百拜深深，嫛倪常惠保。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五福降中天 代寿赵次丈八十' AND p.poem_author = '奭良';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('永和宫词廿七首 其九', '吴伟业', '明代', '奉使龙楼贾佩兰，往还偶失两宫欢。虽云樊昵能辞令，欲得昭仪喜怒难。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '永和宫词廿七首 其九' AND p.poem_author = '吴伟业';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感花 其四', '吴芾', '宋代', '纵令日日醉春风，已恨花无十日红。何事东君长作恶，不容春色丽晴空。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感花 其四' AND p.poem_author = '吴芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感兴二十七首 其二十五', '方一夔', '宋代', '雄蜂采花粉，雌蜂衔花汁。粉以作黄蜡，汁以蒸白蜜。\n\n不辞盗我廪，但规安我室。吾穷还可忍，岁岁看分出。\n\n不见岐周人，先世但积德。土地付獯狄，自爱豳沮漆。\n\n儿孙遍天下，鲁卫酆郇毕。勿言天未定，此理终可必。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感兴二十七首 其二十五' AND p.poem_author = '方一夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '释道臻', '宋代', '疑君魂梦在清都。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '释道臻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('曲江见杏花', '朱诚泳', '明代', '隔岸依稀见早霞，酒帘摇处两三家。马头駊騀行来近，始见前村有杏花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '曲江见杏花' AND p.poem_author = '朱诚泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('定风波·次高左藏使君韵', '黄庭坚', '宋代', '万里黔中一漏天，屋居终日似乘船。及至重阳天也霁，催醉，鬼门关外蜀江前。\n莫笑老翁犹气岸，君看，几人黄菊上华颠？戏马台南追两谢，驰射，风流犹拍古人肩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '定风波·次高左藏使君韵' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('族叔祖示四绝句次韵 其二', '张守', '宋代', '不乐从军学仲宣，那能辟谷慕飞仙。直缘衰病干明主，乞得南窗一觉眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '族叔祖示四绝句次韵 其二' AND p.poem_author = '张守';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庆寿寺', '陈琏', '明代', '暇日行经凤阁西，喜瞻佛刹与云齐。高僧屡致金襕赐，华扁曾承御墨题。\n\n烟满禅房香蔼蔼，雨荒鹤径草萋萋。偶来林下寻碑看，祇树阴中听鸟啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庆寿寺' AND p.poem_author = '陈琏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凭栏人 牧羊人', '黄绮', '当代', '芳草青青不辨天。云拥山羊白玉团。羊群胜似仙。\n\n笑回头，遗牧鞭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凭栏人 牧羊人' AND p.poem_author = '黄绮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鼓笛慢/水龙吟', '佚名', '宋代', '雪霏冰结霜凝，是谁透得春工意。南枝向暖，江边岭上，独先众卉。闲态幽姿，绿窗红蒂，粉英金蕊。念冰肤秀骨，人间要见，除非是、真仙子。羌管且休横吹。待佳人、新妆初试。鸾台晓鉴，人花相对，何须更比。疏影横斜，暗香浮动，月低风细。又岂知，渐结枝头翠玉，有和羹美。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鼓笛慢/水龙吟' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋答尹宪副先生 其一', '罗钦顺', '明代', '顿收佳什见情亲，一字都来不犯尘。秋院挥毫风正爽，晓窗开卷墨犹新。\n\n论心每忆同游处，矫首难忘奉别晨。门带清流山附屋，暮年新酒共谁频。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋答尹宪副先生 其一' AND p.poem_author = '罗钦顺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和刘后村梅花百咏 其六十六', '方蒙仲', '宋代', '生涯冷淡乐者少，声色希夷见若无。洛下只知海棠会，岭南竞作荔枝图。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和刘后村梅花百咏 其六十六' AND p.poem_author = '方蒙仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水龙吟 道运', '丘处机', '元代', '混元南岳初开，瑞云透出昆仑表。星移电转，阴升阳降，红光缥渺。鹤舞鸾翔，看乌龟共，赤龙蟠绕。尽鸿ㄨ一气，烹成造化，神仙道，片时了。云散十方三岛，洞天深、月明风袅。此时占得，长生门户，遐龄体调。吟咏从佗，海移山变，石枯松老。伴烟霞独向，非非境外，恨知音少。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水龙吟 道运' AND p.poem_author = '丘处机';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('止斋曲廊初成', '陈傅良', '宋代', '但酒胜如水，但花胜如草。\n小廊曲通幽，竹椽亦良好。\n止斋十数间，足以便衰老。\n檐低远风露，地窄易汛扫。\n浅溪浮薄觞，短屏糊旧稿。\n著书仅玄易，过客多韦缟。\n於中榜退思，谁其谅深抱。\n吾思亦已晚，吾退盍更早。\n怀哉彭泽令，仰止商山皓。\n维渊有潜龙，维岳有藏宝。\n煌煌暮春堂，三字落穹昊。\n昭回际南极，镇抚及东岛。\n胡然乃在斯，夙夜惧不保。\n鬼神无世情，呵护必有道。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '止斋曲廊初成' AND p.poem_author = '陈傅良';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辛巳除夕', '钱钟书', '当代', '不容灯火尽情明，禁绝千家爆竹声。\n几见世能随历换，都来岁尚赚人迎。\n老饥驱去无南北，永夜思存遍死生。\n好办杯盘歌拊缶，更知何日是升平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辛巳除夕' AND p.poem_author = '钱钟书';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈一首', '吴处厚', '宋代', '是身如泡幻，尽非真实相。况兹纸上影，妄外更生妄。\n\n到岸不须船，无风休起浪。唯当清静观，妙法了无象。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈一首' AND p.poem_author = '吴处厚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陇州神泉铺后池', '李复', '宋代', '山腰绿映女郎祠，祠下泉通竹下池。时有游鯈自来去，祗应曾见理钩丝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陇州神泉铺后池' AND p.poem_author = '李复';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题魏少府破屏风', '柳应芳', '明代', '依倚忘年岁，中伤冀尔容。\n乍通宵案烛，不掩午堂钟。\n射雀犹存影，弹蝇已失踪。\n勿言新可代，官冷若为供。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题魏少府破屏风' AND p.poem_author = '柳应芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金刚随机无尽颂·法会因由分第一', '释印肃', '宋代', '欲穷千里目，野干浑狐族。\n大家归去来，莫道盆光覆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金刚随机无尽颂·法会因由分第一' AND p.poem_author = '释印肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鞦韆', '李待问', '明代', '画架齐芳树，垂云拂夕阴。长安女儿戏，年少岁时心。\n\n燕掠风前舞，莺翻垣外音。小楼看不厌，惆怅落花深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鞦韆' AND p.poem_author = '李待问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大同路石佛谷过啼哭岭', '蓝仁', '元代', '云京石寺游，西北上丰州。山险为啼哭，路艰成阻脩。\n\n闻名心已碎，未见泪先流。万里江南客，那堪过岭头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大同路石佛谷过啼哭岭' AND p.poem_author = '蓝仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋日侍皇太后宴', '弘历', '清代', '月到今宵满，秋当此日中。佳筵开虎帐，皓魄丽璇空。\n\n欢赏陪王母，关山入桂宫。舒华泠坂露，弄影荡林风。\n\n午夜蟾应冷，千年镜早砻。持将对慈寿，辉映一般同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋日侍皇太后宴' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题涉江词寄千帆教授四首 其四', '周采泉', '近代', '奇光异彩豁吟眸，哀乐中年集百忧。七字便堪千载诵，有斜阳处有春愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题涉江词寄千帆教授四首 其四' AND p.poem_author = '周采泉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('癸未至节以病晚起走笔戏书纪事排闷十首', '方回', '宋代', '云无事书者，泥屦隔墙声。\n小市扃虚肆，荒庖绝美烹。\n流涎淮蟹紫，入梦海柑頳。\n莫殢闭关卦，兵戈商不行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '癸未至节以病晚起走笔戏书纪事排闷十首' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李氏孝义', '陶安', '明代', '鲁之为国多秀民，礼教遗俗醇乎醇。中有孝子全性真，务学唯先厚天伦。\n\n骨肉之爱始自亲，厚我能施睦宗姻。母氏派出虞公臣，秉节操心异于人。\n\n夫也竟终阃幕宾，江东客途孤怆神。归家奉舅颜和訚，舅兮不知儿陨身。\n\n不将脸照桃花春，柏舟为誓甘苦辛。灯窗课读勤绩纫，渐见四子英甡甡。\n\n重闱鹤发馀九旬，孙枝满眼皆儒珍。盈门弦诵延缙绅，簦笈远至咸循循。\n\n表厥宅里墨榜新，光映岱岳黄河津。良也孝义盖有因，积善有报祯祥频。\n\n后贤思齐世蹈仁，河岳久长能与钧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李氏孝义' AND p.poem_author = '陶安';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宬皇史', '皇甫汸', '明代', '宬皇史，函帝籍。金为匮，石为室。签汇绨缃部甲乙。\n\n迩文华，充武库。简鸿儒，雠豕误。于万斯年守之锢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宬皇史' AND p.poem_author = '皇甫汸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塘上杂诗四首 其二', '程汉', '明代', '少年卖畚事康卑，出入南陵郭外溪。自昔家空渔浦上，于今人老栅塘西。\n\n浮烟直港乘槎小，斜日疏篱晒网低。向夕烹鱼谁可问，山厨不见旧山妻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塘上杂诗四首 其二' AND p.poem_author = '程汉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古二十四首 其十七', '释胜', '宋代', '有喝端如探竿草，无师血脉通红线。当阳不识李将军，徒学穿杨一枝箭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古二十四首 其十七' AND p.poem_author = '释胜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送西秦张仲实游大涤洞天', '林昉', '宋代', '此时仙兴发，九锁访名峰。\n玉洞昼飞鼠，石池春浴龙。\n异人花外见，道士酒边逢。\n余欲采芳茗，白云何所从。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送西秦张仲实游大涤洞天' AND p.poem_author = '林昉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('种花', '苏仲', '明代', '偷得清閒半日光，薙荒除草接花忙。新怀蒋诩开幽景，老梦林逋逐暗香。\n\n雨过滑泥牢著屐，月临疏影近移床。东风许弄年光兴，拍掌儿歌可侑觞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '种花' AND p.poem_author = '苏仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('将赴江浙大府校进士试会疾止建安驿上后山东眺郡城作十二韵', '范梈', '元代', '青云建安郡，人物故钟秀。承旭开芳树，凌虚列遥岫。\n\n溪声涌夜长，石角吐秋瘦。渔沙府图谶，仙室川浸溜。\n\n征尘汩炎毒，服事弥奔奏。淡淡鸿鹄举，苍苍鹰隼候。\n\n山英茗在瀹，馆饭菰登豆。勤渠相国谊，忝窃大夫后。\n\n顾惟论贤能，奚取推寡陋。吾欲敕五丁，雷电激宇宙。\n\n疾飞移万壑，及此洗昏疚。起为梅子真，南厓扫丹臼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将赴江浙大府校进士试会疾止建安驿上后山东眺郡城作十二韵' AND p.poem_author = '范梈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上谷秋日杂书四首 其一', '程可中', '明代', '列壁风鸣汉帜摇，居庸天迥锁云标。雨余新爽澄金气，夜半残河插斗杓。\n\n嘉馔土人烹硕鼠，薄寒胡帽制丰貂。妖姬不解愁砧杵，马上琵琶手自调。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上谷秋日杂书四首 其一' AND p.poem_author = '程可中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次儿辈戏商卿设醴韵二首', '陈造', '宋代', '将命长须脚未移，联翩客马已来齐。\n菊花旋采浮云液，罗{贴莫}宽围护麝脐。\n醉里有诗皆虎凤，区中无物不虫鸡。\n主宾等是龙津客，未分金鳞卧瓮虀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次儿辈戏商卿设醴韵二首' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早春即事', '华岳', '宋代', '杨柳丝丝弄淡黄，怯寒燕子未归梁。\n晓迷芳草骓骏湿，夜宿閒花蝶翅香。\n得句自惭非子美，赏音犹恐误中郎。\n愿言相约花前醉，莫放春容过海棠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早春即事' AND p.poem_author = '华岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次张正卿平江伯见赠', '龚璛', '宋代', '车马匆匆不我过，诗书亹亹奈君何。邻墙烛影夜未艾，客路梅花春渐和。\n\n佳士逢时文苑传，小人有分力田科。支颐送远阳湖上，急雪回风生意多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次张正卿平江伯见赠' AND p.poem_author = '龚璛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿魝州次韵石沙侍御', '符锡', '明代', '一宿渔阳馆，新诗取次留。奚囊应渐满，民瘼荷兼□。\n\n日晏村烟薄，春深鸟韵柔。若为忧国虑，时共野人筹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿魝州次韵石沙侍御' AND p.poem_author = '符锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '释善昭', '宋代', '三头六臂擎天地，忿怒那吒扑帝钟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '释善昭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('止酒和陶靖节', '邝露', '明代', '止酒不可止，得酒性乃便。何世非大梦，何夜非长年。\n\n何天非梦梦，何帝非陶然。大饮盗海岳，醢龙酺麟肩。\n\n小饮盗沼沚，烹葵醊茎莲。嗒然既丧我，优哉复忘天。\n\n天岂与我违，太和同周旋。笑彼独清醒，怀沙甘湛渊。\n\n沐猴希万乘，封豕冠进贤。乘舆辱执盖，箕豆横相煎。\n\n手持一樽者，不受诸可怜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '止酒和陶靖节' AND p.poem_author = '邝露';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('如梦令·题淮山楼', '苏轼', '宋代', '城上层楼叠巘，城下清淮古汴。举手揖吴云，人与暮天俱远。魂断，魂断，后夜松江月满。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '如梦令·题淮山楼' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古十八首 其七', '释师一', '宋代', '孰云意在钁头边，一击圆通彻大千。大笑低头归去后，饥餐且莫与人传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古十八首 其七' AND p.poem_author = '释师一';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头·双阙步云尾', '邵元实', '宋代', '双阙步云尾，六阁上鳌头。侍臣冠底，英英人物是君侯。闻道东皇深意，回想西清往事，早晚启金瓯。丹扆伫宏略，黄阁待名流。九秋天，千岁日，一樽酬。策勋黄石，相期茅土更封侯。稳扈钩陈天仗，净扫搀抢氛祲，按辔入神州。收了卢龙塞，却访赤松游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头·双阙步云尾' AND p.poem_author = '邵元实';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('顺安辞呈赵使君二首', '刘著', '宋代', '六朝兴废渡河年，旧国归来更黯然。\n八月边城山未雪，芦花藉藉已漫天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '顺安辞呈赵使君二首' AND p.poem_author = '刘著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('茶瓶儿', '朱祖谋', '清代', '十载轻衫尘涴。逗乡心、玉梅疏朵。花魂谁与招清些，便料理、五湖单舸。\n\n雪窗月明愁卧。梦东风、灞桥春锁。熏笼偎夜培残火。\n\n尚暖得、数椒红破。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '茶瓶儿' AND p.poem_author = '朱祖谋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('试心石', '王世贞', '明代', '陡出三尺崖，下临千尺地。道人呼试心，无心可将试。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '试心石' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雁乙酉', '宗远崖', '近代', '群雁南飞日，孤舟北渡前。风波殊异路，会见待他年。\n\n尔自随阳去，吾宁向冷迁。颇闻菰米熟，矰缴满天边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雁乙酉' AND p.poem_author = '宗远崖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠别太常李博士兼寄两省旧游', '韩翃', '唐代', '两年戴武弁，趋侍明光殿。一朝簪惠文，客事信陵君。 \n 简异当朝执，香非寓直熏。差肩何记室，携手李将军。 \n 玉镫初回酸枣馆，金钿正舞石榴裙。忽惊万事随流水， \n 不见双旌逐塞云。感旧抚心多寂寂，与君相遇头初白。 \n 暂夸五首军中诗，还忆万年枝下客。昨日留欢今送归， \n 空披秋水映斜晖。闲吟佳句对孤鹤，惆怅寒霜落叶稀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠别太常李博士兼寄两省旧游' AND p.poem_author = '韩翃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('淳熙六年春帖子词·皇后合五首', '崔敦诗', '宋代', '风光天上倍常殊，花夺阑干昼影舒。\n虚几自临中令帖，明窗时展大家书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '淳熙六年春帖子词·皇后合五首' AND p.poem_author = '崔敦诗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('下皋杂咏 其二十三', '黄仲昭', '明代', '性癖情知与世殊，秪应归卧故山庐。山中亦有经纶事，朝课耕桑夕校书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '下皋杂咏 其二十三' AND p.poem_author = '黄仲昭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('佳人停板图', '唐寅', '明代', '仙娥记曲世无双，下直归来日满窗。\n随手托牙镂板在，低头不语暗寻腔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '佳人停板图' AND p.poem_author = '唐寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泛舟自西海至万寿寺 其三', '弘历', '清代', '招提门枕碧溪流，月相瞻依偶憩留。忆我当年题句处，假山松栝绿阴稠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泛舟自西海至万寿寺 其三' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('唐有怀以九疑之茶分赠二首 其一', '王慎中', '明代', '永州太守清于水，囊携芳茗担还轻。却分囊茗过闽岭，重儗千钧未比情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '唐有怀以九疑之茶分赠二首 其一' AND p.poem_author = '王慎中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和李峤杂咏诗百二十首韵 其七十四 帘', '弘历', '清代', '望处目疑水，垂来意满秋。碧珠文绣额，银蒜曲琼钩。\n\n暮雨西山卷，朝霞东户浮。君平开卦处，终日与天游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和李峤杂咏诗百二十首韵 其七十四 帘' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四明山中十绝·木兰', '戴表元', '宋代', '七里黄泥红树冈，西风果熟一村香。\n居人只道山深好，三百年来是战场。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四明山中十绝·木兰' AND p.poem_author = '戴表元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('磅大受赴选天官', '邹浩', '宋代', '元佑真人初御天，四门穆穆来忠言。\n阆风学士望朝野，即日赐环司谏垣。\n当时同列继登用，独先朝露归九原。\n位不酬身在孙子，嶷嶷诸子声名喧。\n叔也纵横五经内，娱目未始窥家园。\n苟闻某所有贤者，弊车趼仆从之奔。\n甘陵南北正分党，攘臂其间无怨恩。\n未见其止见其进，会须一反映收乾坤。\n素冠俛首琴复御，鹏飞九万方化鲲。\n于今怙恃只明主，肯与世俗均寒暄。\n旦年妙笔三千牍，矧已恸哭论元元。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '磅大受赴选天官' AND p.poem_author = '邹浩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('车中作愧诗谢潘克强潘乐乐贤父子并三江兄', '卢青山', '当代', '老人胸何广，豁豁横山川。碰壁夫何物，一蚊嗡其间。\n\n虎子亦刚烈，大眉如帚悬。得间秉其机，拯我危崖边。\n\n惭我醉如盲，所为不自观。复如梦游人，醒不记从前。\n\n苟非三江子，安复识所愆。作诗记其过，因以谢三贤。\n\n往者不可补，搁笔唯长叹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '车中作愧诗谢潘克强潘乐乐贤父子并三江兄' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('遣兴五首 其五', '杨爵', '明代', '幽囚罪是吐忠肝，日见逻人向北探。圣主无劳关虑切，微臣不以死为难。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '遣兴五首 其五' AND p.poem_author = '杨爵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿皇太子 其二', '赵彦端', '宋代', '子晋吹笙未是仙，阿丕横槊少全篇。小吟青著梅梢句，一日东风四海传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿皇太子 其二' AND p.poem_author = '赵彦端';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与林止庵叶半隐分赋郡中古迹得鲁公祠右军', '艾性夫', '宋代', '遗像犹能立懦夫，悬知生气摄萑苻。\n三郎阿堵知何用，只识营州阿荦奴。\n昏昏水气吐玄云，自是先生笔有神。\n不洗从来姿媚态，可怜北面卫夫人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与林止庵叶半隐分赋郡中古迹得鲁公祠右军' AND p.poem_author = '艾性夫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏日村居四十二首 其二十二', '于慎行', '明代', '开卷百年万里，连篇落日中原。一任骚坛定霸，争教学海穷源。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏日村居四十二首 其二十二' AND p.poem_author = '于慎行';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '释法言', '宋代', '林下闲看水牯牛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '释法言';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋怀三首', '周麟之', '宋代', '江远莼鲈晚，迳荒松菊寒。\n近知秋信好，更觉旅怀宽。\n远杵风催急，横琴夜向阑。\n飘零莫惆怅，吾道久艰难。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋怀三首' AND p.poem_author = '周麟之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出郊即事', '朱子恭', '宋代', '经行阡陌日迟迟，桑柘才方吐绿枝。\n只为峭寒交节晚，村家却是拂蚕时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出郊即事' AND p.poem_author = '朱子恭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵陆南宫晨起有感', '张镃', '宋代', '骂坐非真豪，挂冠岂实高。\n畸迹烟雨埋，客气利禄鏖。\n曷若大丈夫，本志轻旂旄。\n无择眼界平，共馨等膻臊。\n机息箭自空，谍复论弓橐。\n先生博达姿，阂世江河滔。\n器吞子贡琏，才夺东方袍。\n出处日两忘，居朝隐蓬蒿。\n一代能几人，称提付郎曹。\n饭熟菜亦香，但教齿牙牢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵陆南宫晨起有感' AND p.poem_author = '张镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔家傲 其一 夏日晓起', '杨慎', '明代', '鸡唱未圆天已旭。伯劳杜宇声相续。残月笼花风袅竹。\n\n眠未足。千金难买临明宿。\n\n叶上露华纷缀玉。青松雨后如膏沐。思爽神清来往独。\n\n幽径躅。休教踏破苔钱绿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔家傲 其一 夏日晓起' AND p.poem_author = '杨慎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蜀道难·其一', '萧纲', '南北朝', '建平督邮道，鱼复永安宫。\n若奏巴渝曲，时当君思中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蜀道难·其一' AND p.poem_author = '萧纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆得', '范梈', '元代', '忆得佳人《白纻》词，几将天外数归期。自从落尽庭前树，夜夜秋声总不知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆得' AND p.poem_author = '范梈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重经山店有感', '张鹏翮', '清代', '曾忆黄花过水滨，儿童惯见往来频。青山绕舍依然在，迎客门前少一人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重经山店有感' AND p.poem_author = '张鹏翮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和元少卿雪', '徐铉', '唐代', '朔风飞雪遍遥天，为瑞偏宜在腊前。有客棹舟将命友，何人高卧共称贤。\n\n瑶花散乱纷临席，玉树晶荧烂满川。閒想冰容比君子，始知姑射有神仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和元少卿雪' AND p.poem_author = '徐铉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋怀八首 其六', '李孙宸', '明代', '关河百二控神京，谁遣当关有横行。徒使至尊思猛士，不闻年少请长缨。\n\n纶扉上相仍敷阃，属国元戎未解兵。最是防秋宵旰急，可容官府釜镉成。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋怀八首 其六' AND p.poem_author = '李孙宸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄题挹山楼', '彭鹤濂', '近代', '猛忆留溪感又生，山楼曾宿未忘情。白穿虚槛云归寺，绿抱孤村树作城。\n\n消夏凿池成梦想，匝阴补竹待承平。料知秦望山头月，照到床前分外明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄题挹山楼' AND p.poem_author = '彭鹤濂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('史太师入觐赐带以不知官高卑玉带悬金鱼为韵', '释宝昙', '宋代', '弥明晚不逊，不解世俗书。\n邻翁十升水，公无察渊鱼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '史太师入觐赐带以不知官高卑玉带悬金鱼为韵' AND p.poem_author = '释宝昙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('知机吟用康节韵', '罗洪先', '明代', '先物谓之几，旁行且入微。有无未分处，主宰不移时。\n\n得者须忘意，知之莫泥词。虽从静里得，却向动中知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '知机吟用康节韵' AND p.poem_author = '罗洪先';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('积雨作寒五首 其三', '范成大', '宋代', '熨帖重寻毳衲，补苴尽护纸窗。馀生雪鬓禅榻，昨梦云帆涨江。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '积雨作寒五首 其三' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠朱静芳大姐', '聂绀弩', '近代', '急人之急女朱家，两度汾河走飞车。刀笔纵横光闪闪，化杨枝水洒枯花。\n\n劝君更尽一杯茶，千里万里亦中华。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠朱静芳大姐' AND p.poem_author = '聂绀弩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和徐子由题昼寂轩', '黄公度', '宋代', '木落孤城迥，苔封古寺深。\n结庐依近地，隐几惬幽心。\n细草秋仍绿，修篁晚更阴。\n红尘门外路，六辔漫如琴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和徐子由题昼寂轩' AND p.poem_author = '黄公度';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('友人惠芍药并青梅一枝偶成三绝 其三', '葛胜仲', '宋代', '香雪一林初著子，和枝分饷不吾悭。含酸但止文园渴，青琐无人蹙远山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '友人惠芍药并青梅一枝偶成三绝 其三' AND p.poem_author = '葛胜仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋兴 其三', '魏学洢', '明代', '天高着处可徜徉，日日优游日日忙。瘦菊倚风同客笑，短篁摇影共人长。\n\n旧疑西蜀诗无律，近信东皋醉有乡。薄暮凭阑清眺迥，水青云白淡秋妆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋兴 其三' AND p.poem_author = '魏学洢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('光宣杂咏 其二十六', '冒效鲁', '近代', '雅词略近汪容甫，博学差同顾涧蘋。月旦过庭天下喻，北王南李两文人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '光宣杂咏 其二十六' AND p.poem_author = '冒效鲁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百零二首', '释绍昙', '宋代', '山雨酿春寒，晓湿梅花重。\n结实较迟迟，且听香浮动。\n化工有意待重来。永为鼎鼐调羹用。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百零二首' AND p.poem_author = '释绍昙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('薛岭', '张翥', '宋代', '衣冠陈氏族，桃李薛公园。场老遗文古，岩僧旧迹存。\n\n苔矶荒碛岸，金榜勒瑶琨。已怜松特异，尤喜石能翻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '薛岭' AND p.poem_author = '张翥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('文昌醮灯牌', '阳枋', '宋代', '牡丹枝上先春蕊，翠杏坛边未雨虹。知有文章光万丈，钟成佳气满黔中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '文昌醮灯牌' AND p.poem_author = '阳枋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('享太庙乐章。大成舞', '魏徵', '唐代', '周穆王季，晋美帝文。明明盛德，穆穆齐芬。 \n 藏用四履，屈道参分。铿锵钟石，载纪鸿勋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '享太庙乐章。大成舞' AND p.poem_author = '魏徵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花 其二', '陈景沂', '宋代', '从来造化有何私，自是梅花南北枝。只为北枝太寒苦，东君消息故应迟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花 其二' AND p.poem_author = '陈景沂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄宋使君', '贯休', '唐代', '寺倚乌龙腹，窗中见碧棱。空廊人画祖，古殿鹤窥灯。 \n 风吼深松雪，炉寒一鼎冰。唯应谢内史，知此道心澄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄宋使君' AND p.poem_author = '贯休';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('即事', '郑刚中', '宋代', '竹舆晓出见湖山，小室焚香暂得闲。\n帘动东风入双蝶，清愁何处不用关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '即事' AND p.poem_author = '郑刚中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和益阳赵宰六首 其二', '廖行之', '宋代', '食黮从吾化，安舆本若情。有能奔晋盗，何用筑秦城。\n\n一邑诚天幸，三年赖政平。儒功固如许，仪舌漫纵横。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和益阳赵宰六首 其二' AND p.poem_author = '廖行之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桃源洞', '顾鉴', '清代', '路问桃花源，遥指白马渡。晻蔼云气深，秦人从此去。\n\n秦人去千载，白云长自护。何年灵境开，花源忽呈露。\n\n从此传人间，物外感生聚。我来已深冬，不见桃花雨。\n\n林深水无源，水绕山回互。草木净余芳，鱼鸟适幽趣。\n\n仿佛鸡犬声，远出云中树。奇踪托杳渺，欲觅曾无路。\n\n嗟彼武陵渔，津逮仍迷误。为问避世人，高举将焉赴。\n\n渊明结妙想，孤怀聊自寓。寓言非人间，惝恍何所慕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桃源洞' AND p.poem_author = '顾鉴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丁亥留节翁城，同诸公行长至礼', '张煌言', '明代', '几年卧节梦金銮，绵蕞犹班旧握兰。葭管初开周甲子，葱珩重见汉衣冠。\n\n嵩呼恍觉炉香近，海曙还疑扇影寒。惟有臣心冰雪净，誓将綵线续双丸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丁亥留节翁城，同诸公行长至礼' AND p.poem_author = '张煌言';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('生查子（梅）', '晁补之', '宋代', '青帝晓来风，偏傍梅梢紧。未放玉肌开，已觉龙香喷。 \n 此意比佳人，争奈非朱粉。惟有许飞琼，风味依稀近。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '生查子（梅）' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杜鹃鸟二首 其一', '卢青山', '当代', '凄鸣如不足，更傍吾身飞。我若能归去，安用子相催？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杜鹃鸟二首 其一' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冀馆春夕见月', '王圭', '宋代', '甚宠无如使牡行，曾同万里听秋声。黄金台下嘶宛马，木叶山前度汉旌。\n\n才到关南逢雁尽，重来海上见波平。故人临月应相望，一夕寒光特为明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冀馆春夕见月' AND p.poem_author = '王圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '汤思退', '宋代', '虞妃从梧野，启母祔稽山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '汤思退';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('昨夕不知有雪而晨起四望远峰皆已变色再用元韵作两绝句 其一', '朱熹', '宋代', '朔风吹尽暮云平，室暖炉红睡达明。但怪朝来满山白，不知昨夜打窗声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '昨夕不知有雪而晨起四望远峰皆已变色再用元韵作两绝句 其一' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('《女儿曲》脱稿即题其末', '卢青山', '当代', '偶尔相逢说古亭，为君长撰女儿行。一天荒月埋魂地，百代秋风捲梦人。\n\n但有平和能到死，更无歌哭可疗心。我而非主君非客，两坐闲看淡淡春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '《女儿曲》脱稿即题其末' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题画罗汉 其六', '戴梓', '清代', '偶逢一石，就之欲眠。岩草拥后，松风落前。西方东土，山隈海边。\n\n有此乐国，可以永年。如水出泉，清不费钱。梧桐一叶，临秋翩翩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题画罗汉 其六' AND p.poem_author = '戴梓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和柯狮山大参山中十二景 其六 群峰送青', '黄衷', '明代', '江上兹山与岳尊，腾猿回鹤谩纷纷。帘端矗矗群峰翠，一笑真同列戟分。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和柯狮山大参山中十二景 其六 群峰送青' AND p.poem_author = '黄衷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂兴十二首', '方回', '宋代', '生世六六载，始获玷末科。\n选官六六载，仕少閒日多。\n逆旅脱兵火，专城免干戈。\n中原久隔绝，忽焉得经过。\n水涸梁山泊，淮流受黄河。\n往者故已矣，方来将若何。\n开岁七十一，聊拟自挽歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂兴十二首' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('螃蟹咏', '曹雪芹', '清代', '铁甲长戈死未忘，堆盘色相喜先尝。\n螯封嫩玉双双满，壳凸红脂块块香。\n多肉更怜卿八足，助情谁劝我千觞。\n对兹佳品酬佳节，桂拂清风菊带霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '螃蟹咏' AND p.poem_author = '曹雪芹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶题', '王世贞', '明代', '许由能乞万乘身，归卧箕山天地新。过宿翻为窃屦客，饮流仍遇弃瓢人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶题' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庵中杂书四首 其二', '陆游', '宋代', '谋生安用苦区区，豆饭藜羹未遽无。若使天年犹合活，不妨自有谷于菟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庵中杂书四首 其二' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏菊三首 其一', '崔荣江', '当代', '总道春温叫骨羸，秋风邀约向身吹。平明雨冷濡青领，更晚霜清挑白眉。\n\n云淡花开堪仰月，世昏人倦罢吟诗。较来篱上黄花瘦，隐忍多输那一枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏菊三首 其一' AND p.poem_author = '崔荣江';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('览古五首 其二', '方回', '宋代', '读书以脩身，末惟利之渔。夏侯诧拾芥，桓荣陈其车。\n\n初学眯训诂，利心已炎如。为吏未识字，嗜贿不顾躯。\n\n青青陵陂麦，歌声何舒舒。金椎勿造次，恐伤口中珠。\n\n岂不事诗礼，所为乃凶渠。用世率此辈，生灵夫何辜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '览古五首 其二' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('林泉归隐图', '德祥', '明代', '居山岂为山，只爱此中闲。野菜何消种，柴门不要关。\n\n饭余听涧落，经罢看云还。恐有寒山句，多题藓石间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '林泉归隐图' AND p.poem_author = '德祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('初游黄山二首', '宛敏灏', '近代', '云谷松风送晚凉，披襟跣足话长廊。人生几得名山宿，梦里微闻百合香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '初游黄山二首' AND p.poem_author = '宛敏灏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠杜幼高', '叶适', '宋代', '杜子五兄弟，词林俱上头。\n规模古乐府，接续后春秋。\n奇崛令谁赏，羁栖浪自愁。\n故园如镜水，日日抱村流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠杜幼高' AND p.poem_author = '叶适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高生规当岁贡遇生日', '李延兴', '元代', '天风环佩响珊珊，瑶海秋高王母还。好著莱衣娱鹤发，要将董策觐龙颜。\n\n霞翻锦帜金鸾殿，日射丹墀玉笋班。待得瓦桥春雪霁，马嘶官路彩云间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高生规当岁贡遇生日' AND p.poem_author = '李延兴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏壁上尘', '敦敏', '清代', '软红何事傍闲居，入户穿帘费扫除。人去旗亭诗暗淡，烟昏古屋画萧疏。\n\n飞扬不受将军拜，依附偏宜贫士庐。识得庄生野马意，遥瞻环堵自如如。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏壁上尘' AND p.poem_author = '敦敏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('曾子固令咏齐州景物作二十一诗以献 其二十一 北渚亭', '孔平仲', '宋代', '高深极前临，苍莽接回眺。齐州景物多，于此领其要。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '曾子固令咏齐州景物作二十一诗以献 其二十一 北渚亭' AND p.poem_author = '孔平仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('示儿定孙二绝 其二', '陈淳', '宋代', '丈夫尚志志高明，勿效卑卑世俗情。从上一条平坦路，千贤万圣所通行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '示儿定孙二绝 其二' AND p.poem_author = '陈淳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽钱贞庵', '徐庸', '明代', '海虞山水古今清，人物生成属地灵。刘汉宗支曾按谱，相君事业早传经。\n\n应时润泽同甘雨，文节昭明拟列星。名向世间崇闻望，□于乡里作仪刑。\n\n惟将籴米资凶岁，不逐纶音入内廷。吟咏性情居宅第，逍遥□□在林□。\n\n花边曙墅开棋局，竹底藏钩醉绿□。争羡寸心恒坦荡，不堪双鬓渐凋零。\n\n黄金鼎在宜脩炼，白玉楼□赴杳冥。千里竟闲骐骥足，九苞还振凤凰翎。\n\n董狐有待今为传，郭养无惭旧述名。白鹤不归华表柱，漆灯光冷夜台扃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽钱贞庵' AND p.poem_author = '徐庸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋夕怀子厚二首 其一', '朱熹', '宋代', '雨歇林气爽，月华湛遥晖。斋居玩物变，廓落沧洲期。\n\n焚香散碧虚，抚节陈清诗。抗志属云端，非君谅谁知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋夕怀子厚二首 其一' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题社友诗稿', '邓允端', '宋代', '诗里玄机海样深，散于章句敛于心。\n会时要似庖丁刃，妙处应同靖节琴。\n韵胜想君言外得，字新令我意边寻。\n痴人说梦终难信，何日樽前取次吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题社友诗稿' AND p.poem_author = '邓允端';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书兴四首', '汪炎昶', '宋代', '兴逼不暇卧，蹑屐鸣难先。\n裛袂碧氛润，袭襟爽概繁。\n噫馁出故气，咽甘漱新泉。\n骨瘦易酸楚，骨虚觉轻便。\n樵子隔岭见，宁谓吾非仙。\n手持白羽扇，笑坐青崖巅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书兴四首' AND p.poem_author = '汪炎昶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八月十九日得董正翁寺丞书兵疫后城中故旧十', '舒岳祥', '宋代', '黄菊一瓶酒，青山四壁书。\n吾年余岁许，天意复何如。\n寒日沙禽并，风霜野果疏。\n山城询故旧，十九是丘墟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八月十九日得董正翁寺丞书兵疫后城中故旧十' AND p.poem_author = '舒岳祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('度岭', '吴鼎芳', '明代', '林僧言别去，自憩松下石。\n红泉界空翠，巢居叫霜笛。\n夕光淡西水，千顷成一碧。\n冷信雁传来，秋容枫点出。\n闲云满怀袖，邀我过山脊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '度岭' AND p.poem_author = '吴鼎芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送彦斌弟还侍', '郑潜', '明代', '我方避地贫尤甚，子独还乡岁又阑。浮世风尘妨孝节，平生事业负儒冠。\n\n空怀鹤禁陪移步，远愧鸰原救急难。千里畏途当自爱，北堂珍重慰加餐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送彦斌弟还侍' AND p.poem_author = '郑潜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('扈从谒陵十咏 其二 沙河驻跸', '倪谦', '明代', '晓驻旌旗遍野红，貔貅百里卫行宫。山连北极三千刃，身在中坚十二重。\n\n散骑徐牵金络马，将军齐带宝雕弓。八珍已进天厨膳，甲帐弹棋啜紫茸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '扈从谒陵十咏 其二 沙河驻跸' AND p.poem_author = '倪谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('平湖病中思南归六首 其三', '林光', '明代', '冬卧愁襟薄，跏趺付一卢。难将衰病骨，更听夜啼乌。\n\n地暖思南海，情真有旧徒。飘然决归策，争只为莼鲈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '平湖病中思南归六首 其三' AND p.poem_author = '林光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和吏部薜员外见寄', '王禹偁', '宋代', '枨也好刚多悔吝，唯凭忠信自书绅。\n严陵知退遗荣利，只拟沧浪把钓纶。\n老去趁朝慵待旦，病来求假动经旬。\n西垣兴味更谙尽，一片乌纱满马尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和吏部薜员外见寄' AND p.poem_author = '王禹偁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岩桂花', '郑仲熊', '宋代', '天公怜我太岑寂，每岁殷勤两度开。\n收拾落英将底用，博山香裹荐清杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岩桂花' AND p.poem_author = '郑仲熊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送沈琛笙归衡山 其四', '许南英', '清代', '清漳山水多生色，印住衡山老寓公。食不累官今闵贡，舂甘赁庑古梁鸿。\n\n秋高欲送伊人去，世乱应宜我辈穷！相士半生今有几，昂头欲捣碎虚空。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送沈琛笙归衡山 其四' AND p.poem_author = '许南英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋兴亭', '韩扬', '宋代', '贾载尝为郡，名亭建此邦。\n近山连大别，远水接长江。\n待月凭东槛，来薰起北窗。\n四时皆有兴，秋兴独难降。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋兴亭' AND p.poem_author = '韩扬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('微雨后风沙大作晚泊临清', '黄佐', '明代', '笑辞钟鼎向山林，去路尘沙苦见侵。万里舟航淹日月，九河风雨战晴阴。\n\n草堂花竹萦春梦，泽国鱼龙伴夜吟。心迹不教双寂寞，灯前呼酒漫开襟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '微雨后风沙大作晚泊临清' AND p.poem_author = '黄佐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('章几道将归小饮怀谢城父', '叶梦得', '宋代', '中年甚畏别交亲，况复云山旧结邻。涧谷何时同笑语，干戈已老更风尘。\n\n少留对榻聊分坐，多病持杯漫几巡。贾傅长沙知健否，洞庭波浪渺无津。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '章几道将归小饮怀谢城父' AND p.poem_author = '叶梦得';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和津喜雪二首 其二', '吴芾', '宋代', '我爱平湖绕碧山，山光倒碧到樽前。同云何事迷千嶂，飞雪俄然蔽一川。\n\n纵使玉楼从地涌，便教银阙与天连。到头幻化非真实，争似湖山耐岁年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和津喜雪二首 其二' AND p.poem_author = '吴芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和钱孙叔委心亭二绝 其一', '胡寅', '宋代', '交衢尘雾祗相煎，回首山林去未缘。安得委心无一事，陪公清话许忘年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和钱孙叔委心亭二绝 其一' AND p.poem_author = '胡寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('解佩令 江州讯吴松严令君', '丁澎', '清代', '城临小别，无多听事，近潇湘、弄雨疏帘静。束带公庭，苦相对、督邮清冷。\n\n漫争夸、故人为令。行云赋手，善描神女，早吹来、阳台艳影。\n\n瓮发彯清。可钓有、槎头缩颈。趁烟波、晚楼同凭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '解佩令 江州讯吴松严令君' AND p.poem_author = '丁澎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵王信州', '邓肃', '宋代', '煤炱飞上天，沉沉三日雾。\n银河一压摧，狂雨恣横骛。\n我恐铁骑来，疾驰不纳屦。\n气豪如项羽，势猛似黥布。\n瀰漫江海接高穹，石牛未洗血泥红。\n天吴八首真奇怪，咄嗟平地作银宫。\n我贫家火不星灶，赤脚灭没泥涂中。\n目断晓风生少女，又复茅檐飞白龙。\n惭愧北来王夫子，籍籍声名满都鄙。\n朝吟千赋暮千诗，松腴亦须枯海水。\n莫倚文章似孟坚，未用风流追乐天。\n且以光芒破阴晦，挽回日色到桑田。\n乐岁天公有严约，斥落旄头沉贯索。\n从公日醉三百杯，不怕西风动旗脚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵王信州' AND p.poem_author = '邓肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('故太原郡太夫人李氏挽歌诗二首 其一', '赵鼎臣', '宋代', '德配平原盛，家传相国亲。桂抽三笋茂，玉种两株成。\n\n化剑中秋冷，藏舟半夜惊。凯风从此去，忍听自南声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '故太原郡太夫人李氏挽歌诗二首 其一' AND p.poem_author = '赵鼎臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('将赴都门', '刘青藜', '清代', '十载长安道，风尘鬓欲皤。天宁哀志气，人尽笑蹉跎。\n\n日落汾丘垒，冰胶䩐勒河。又驱羸马去，惆怅意如何？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将赴都门' AND p.poem_author = '刘青藜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赋得江介多悲风用风字', '顾炎武', '清代', '素节乘云梦，清秋下渚宫。哀音生地籁，激楚入天风。\n\n落雁过山急，寒蝉抱树空。伤心干里目，愁绝百年中。\n\n郢路元依北，江关久向东。有人宗国泪，何地洒孤忠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赋得江介多悲风用风字' AND p.poem_author = '顾炎武';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山气', '黄钺', '清代', '山气夜沈郭，苍茫晓未收。寒风来绝塞，入夏尚重裘。\n\n盘马雪千里，射雕天尽头。平生极飞动，惜不壮时游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山气' AND p.poem_author = '黄钺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄怀沈君接 其一', '沈守正', '明代', '与君灵鹫十年身，我别君留百感新。千里同舟淮角酒，一樽小坐断桥莼。\n\n君家春酿碧于水，此处山茶赤似唇。两志栯情兼有恨，梅花西碛少谁人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄怀沈君接 其一' AND p.poem_author = '沈守正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南岳纪游 其四', '黄廷用', '明代', '斋心净献玉坛文，前殿歌钟后殿闻。杳霭若承云旆下，西来又礼魏元君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南岳纪游 其四' AND p.poem_author = '黄廷用';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次敖静之九日言怀韵', '马中锡', '明代', '骑马闻鸡有底忙，一秋憔悴沈东阳。\n身随杖竹空存节，鬓比篱花不耐霜。\n帝载八年纷奏绩，王师六月苦周章。\n何须更落西风帽，黄叶填门独举觞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次敖静之九日言怀韵' AND p.poem_author = '马中锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('胡歌', '岑参', '唐代', '黑姓蕃王貂鼠裘，葡萄宫锦醉缠头。\n关西老将能苦战，七十行兵仍未休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '胡歌' AND p.poem_author = '岑参';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('崖山大忠祠 其二', '沈周', '明代', '二公至此不能为，力尽堂堂是死时。一块肉同今日丧，孤儿事属老天知。\n\n弱流万里难容楫，清酤三行欲动旗。一殉毅然酬所养，厓山堪壮不堪悲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '崖山大忠祠 其二' AND p.poem_author = '沈周';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题方坦庵太史𤾂山语石', '智豁', '清代', '撑云吸露貌奇峰，声借流泉色借松。昔日点头今日语，生公应让海门龙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题方坦庵太史𤾂山语石' AND p.poem_author = '智豁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹊踏花翻 西秦车中携鹦鹉南归，数日飞去', '董元恺', '清代', '陇树秋深，秦宫月落，携将鹦鹉随归骑。归来水驿山程，听慧堪论，新诗读向闺人记。\n\n朱帘初捲忽开笼，青云直上堪垂翅。惊视。千里高飞难致。\n\n空辜负、主人情意。怎似燕燕相依，年年频至。好把奇毛秘。\n\n思乡莫便入函关，且教历尽江南地。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹊踏花翻 西秦车中携鹦鹉南归，数日飞去' AND p.poem_author = '董元恺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('踏莎行 秋怀', '周兰秀', '清代', '叶落平沙，云迷远树。山色模糊人唤渡。芙蓉笑摘上兰桡，轻鸥惊入波心去。\n\n衰柳含烟，凉蝉咽露。年年重觅王孙路。可怜人静玉楼空，满庭芳草家何处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '踏莎行 秋怀' AND p.poem_author = '周兰秀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和陶答庞参军', '苏轼', '宋代', '留灯坐达晓，要与影晤言。下帷对古人，何暇复窥园。\n\n使君本学武，少诵《十三篇》。颇能口击贼，戈戟亦森然。\n\n才智谁不如，功名叹无缘。独来向我说，愤懑当奚宣。\n\n一见胜百闻，往鏖皋兰山。白衣挟三矢，趁此征辽年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和陶答庞参军' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('茶汤会乞颂', '释法薰', '宋代', '铺心无下亦无高，一等无心次第浇。\n便是口吞三世佛，沾化涓滴也难消。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '茶汤会乞颂' AND p.poem_author = '释法薰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过郑丞', '张元凯', '明代', '郑公门似水，杨柳绿如丝。自哂官阶小，那嫌堂构卑。\n\n飞花竟亡赖，归燕不愆期。投辖人皆醉，毋烦置驿为。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过郑丞' AND p.poem_author = '张元凯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪夕', '陆游', '宋代', '目视左（左目右荒）（左目右荒）耳聋，吾衰略与昔人同。\n移灯自看伶竮影，取酒时浇礧磈胸。\n东郭稍能师顺子，北山未敢笑愚公。\n空村雪虐风饕夜，袖手悠然政策功。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪夕' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望江南 秋夜', '薛斑', '清代', '更漏永，起坐自伤神。嘹呖雁鸿悲远迹，凄凉砧杵响寒村。\n\n入耳总销魂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望江南 秋夜' AND p.poem_author = '薛斑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠同年邵文敬', '江源', '明代', '忆别杏园时，南北各命驾。屈指将十年，偶得一慰籍。\n\n示我珠玉篇，一气无漏罅。胸中小溟渤，笔底夺造化。\n\n譬之桓文师，节制雄五霸。又如养由基，百中仰神射。\n\n纸价贵洛阳，谁能不脍炙。君才出天然，我辈风斯下。\n\n三复不释手，秉烛到深夜。细嚼有馀味，何啻倒餐蔗。\n\n愿言继三百，袖然陋鲍谢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠同年邵文敬' AND p.poem_author = '江源';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('横浦十咏·东坡祠', '刘黻', '宋代', '何年海上还，坐镇此山川。\n笔砚归京阙，衣冠带瘴烟。\n一生忠胆在，万古党名传。\n吾道多流落，西风问老天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '横浦十咏·东坡祠' AND p.poem_author = '刘黻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送袁季源之婺州因简范经历', '戴表元', '宋代', '为山不愿高，为水不原深。\n水深蛟龙集，山高虎豹蹲。\n我有避人法，终日衣冠林。\n煌煌钱塘城，游尘书为阴。\n岂无青云交，难在相天心。\n岂弟袁大夫，寒窗理闲琴。\n峻坂为牛力，炎天九秋襟。\n胶漆四十年。龆龀以至今。\n天欲饥饿我，使子无黄金。\n劝仕拙不谐，驱耕弱难任任。\n低回向谁门，后生气骎骎。\n今晨积潦霁，乌乌有好音。\n约我共行役，东平步嵌嵌。\n皎皎婺女精，瀰瀰双溪浔。\n台有白马生，风棱共萧森。\n文林惜妄动，动必向所钦。\n吾评古毛义，志行近骞参。\n参府许辟召，屈身非禄淫。\n斯人我知旧，长髯吴吟。\n穴蚁梦离合，风花命浮沉。\n往者纳千贽，终然遗一簪。\n欲行又不得，出门失前禽。\n子往再拜问，何由振聋暗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送袁季源之婺州因简范经历' AND p.poem_author = '戴表元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寓寺八首', '张耒', '宋代', '翠眉长好何曾损，寄语啼禽漫不闲。\n应为残春足愁恨，长疑蹙破镜中山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寓寺八首' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高丽炉一枚寄虎丘结', '曹勋', '宋代', '兹炉之先，鲸波空际。有国曰韩，以陶以器。奉之函丈，宝烟轻细。\n\n此一瓣香，用严报地。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高丽炉一枚寄虎丘结' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送明守黄子由尚书赴召', '孙应时', '宋代', '灯火笙歌别海壖，诏书归觐九重天。\n已将清净安齐国，不使声名减颍川。\n题品人才看赞赞，夫持皇极在平平。\n文星旧与文昌亚，今贯三台更炳然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送明守黄子由尚书赴召' AND p.poem_author = '孙应时';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋怀十首 其三', '陈师道', '宋代', '采薪墟墓间，行歌当归耕。向来轻薄子，怀谖以为荣。\n\n喘喘辕下犊，力尽官泥深。壮哉八百里，一割探其心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋怀十首 其三' AND p.poem_author = '陈师道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('富池江口夜泊（二首）〗', '郭奎', '明代', '草昧英雄望列侯，梦中三十六春秋。\n功名总被儒冠误，两岸啼猿一夜愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '富池江口夜泊（二首）〗' AND p.poem_author = '郭奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送李生南归寄戴笠王锡阐二高士', '顾炎武', '清代', '华山五粒松，寄向江东去。白云满江天，高士今何处。\n\n忆昔过湖滨，行吟两故人。潜龙犹在水，别鹤已来秦。\n\n江海多翻覆，林泉异栖宿。惊闻东市琴，涕陨堂前筑。\n\n去去逐征蓬，随风西复东。风吹兰蕙色，一夜落关中。\n\n五陵生蔓草，愁绝咸阳道。平生四海心，竟作终南老。\n\n送子出函关，南山望北山。洞庭多桂树，折取一枝还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送李生南归寄戴笠王锡阐二高士' AND p.poem_author = '顾炎武';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢袁子久观察赠马', '李嘉乐', '清代', '驴背寻诗味饱谙，拟将行李一囊担。驰名已觉输中驷，赠别偏劳释左骖。\n\n备位八驺君可致，起家五马我何堪。鞭丝遥指青州路，覂驾毋贻旧友惭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢袁子久观察赠马' AND p.poem_author = '李嘉乐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题曹怡轩樵笛吟稿四首 其三', '萧立之', '宋代', '吟到古人诗近道，洗空凡马画通神。浣花溪上惊人句，剪绿裁红不当春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题曹怡轩樵笛吟稿四首 其三' AND p.poem_author = '萧立之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观园丁除草', '孙承恩', '明代', '中园种嘉蔬，地瘠蔬叶稀。蔓草杂其间，复尔缠绵之。\n\n六月盛炎暑，亭午张赫曦。园工力芟锄，根株俾无遗。\n\n造化普发育，雨露无偏私。去恶佑善良，人事理则宜。\n\n兰蕙生当门，斩刈不得辞。矧尔恶类繁，不去将何为。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观园丁除草' AND p.poem_author = '孙承恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题飞霞图为江鍊师赋', '刘崧', '明代', '海上群峰映紫霞，五云楼观是仙家。谁吹玉笛春风起，千树碧桃都作花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题飞霞图为江鍊师赋' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐', '石孝友', '宋代', '山明水嫩。潇洒桐庐郡。极目风烟无限景。说也如何得尽。 \n 自怜俗状尘容。几年断梗飘蓬。借使严陵知道，只应笑问东风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐' AND p.poem_author = '石孝友';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵李似表县丞出示游西湖古风二首 其二', '李纲', '宋代', '李侯嗜学古，馀事皆远屏。昂昂鸾鹄姿，岂与凡禽并。\n\n捧檄来南州，初识浙江境。寻盟款吾庐，不待日中定。\n\n从容叩所得，响答如汲井。时方罗俊乂，宁久淹簿领。\n\n清秋雕鹗飞，大道骅骝骋。词章尤激昂，笔力可扛鼎。\n\n虚堂纵谈笑，霜月挂金饼。夜阑言愈微，至味嚼佳茗。\n\n古来会合难，岁月积俄顷。愿子谨所之，万里路方永。\n\n吾衰老閒旷，轩冕志已冷。栖迟丘壑间，此兴良自肯。\n\n他日来相遇，梁溪寻钓艇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵李似表县丞出示游西湖古风二首 其二' AND p.poem_author = '李纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题龙隐岩', '王迤祖', '宋代', '龙蟠此地不知年，飞去穿成万仞渊。\n霖雨四方今欲遍，后人空自想蜿蜓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题龙隐岩' AND p.poem_author = '王迤祖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题孟氏惠麓小隐', '秦夔', '明代', '饥后家何在，归来始定居。丹心三尺剑，白首五车书。\n\n戚畹名犹在，云台业未疏。结庐来小隐，岁晚足耕锄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题孟氏惠麓小隐' AND p.poem_author = '秦夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哀故文节公 其一', '宋祁', '宋代', '早传黄石系，未伴赤松游。暴疹惊床蚁，深恩赐养牛。\n\n溪璜俄碎玉，川楫遂藏舟。萧相今无嗣，夫人绍酂侯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哀故文节公 其一' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('定风波 无题', '许白凤', '当代', '薄薄春衫剪剪风。凋颜不媚杏花红。何处飞来双燕子。\n\n知是。隔墙人去画楼空。\n\n有约年时寻斗草。娇小。似曾相识唤聪聪。回首韶光都是恨。\n\n休问。落花无语水流东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '定风波 无题' AND p.poem_author = '许白凤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送安仪凤', '田锡', '宋代', '宣城相送思依依，正是红莲菡萏时。\n行色迎秋清似画，别情因景化为诗。\n人离湖水南边岸，蝉听槐花北向枝。\n天子文明是何地，丹霄岐路莫生疑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送安仪凤' AND p.poem_author = '田锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闺怨', '张博', '明代', '那年离别去，只道投京国。京国人不归，音书到塞北。\n\n少年夫妇不同欢，纵使封侯有何益。还家拜母心内伤，何不当时委道傍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闺怨' AND p.poem_author = '张博';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王承德四时花鸟图 其一', '王佐（汝学）', '明代', '杏花疏雨枌香深，朵朵迎风艳不任。老眼不谙花态度，从教春色付山禽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王承德四时花鸟图 其一' AND p.poem_author = '王佐（汝学）';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠梧窗先辈', '王渐逵', '明代', '亭亭青桐树，郁翠何森森。华滋荫朝露，丹葩耀阳林。\n\n孤根众所忌，摇落岁月侵。天涯有美人，窈窕盟素心。\n\n愿作清商操，为君膝上琴。出入两相随，自此双南金。\n\n固兹思与惠，永以助徽音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠梧窗先辈' AND p.poem_author = '王渐逵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('光宗皇帝挽诗二首 其二', '周必大', '宋代', '仁爱周华夏，英聪贯古今。知人符日照，裕物称天临。\n\n閒退亲传子，忧劳旧损心。景光昭百世，昧谷谩西沉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '光宗皇帝挽诗二首 其二' AND p.poem_author = '周必大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自青诗 其八', '王世贞', '明代', '小道可观，致远则非。从臾如流，狂张若驰。嶭彼乔山，蹇拟陟之。\n\n爚彼烈炎，徒思炙之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自青诗 其八' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('斑鸠', '陈玺', '明代', '香禽自何处，共立枝头语。唤起晓耕人，西畴足春雨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '斑鸠' AND p.poem_author = '陈玺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('献李提军奠原三首 其三', '陈恭尹', '明代', '画角风清静海涛，郊坰共喜见干旄。金方气肃崆峒壮，南斗功成日月高。\n\n姬旦吐哺元自贵，卫青揖客不言劳。天涯贱子能扪虱，怀剌空惭有二毛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '献李提军奠原三首 其三' AND p.poem_author = '陈恭尹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('琴曲四章', '曹雪芹', '清代', '风箫箫兮秋气深，\n美人千里兮独沉吟。\n望故乡兮何处？\n倚桂杆兮涕沾襟。\n山迢迢兮水长，\n照轩窗兮明月光。\n耿耿不寐兮银河渺茫，\n罗衫怯怯兮风露凉。\n子之遭兮不自由，\n予之遇兮多烦忧。\n之子与我兮心焉相投，\n思古人兮俾无尤。\n人生斯世兮如轻尘，\n天上人间兮感夙因。\n感夙因兮不可惙，\n素心如何天上月！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '琴曲四章' AND p.poem_author = '曹雪芹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('昨晚目录之句盖聊以为戏耳何分惠之甚速耶得非乞诸其邻乎', '虞俦', '宋代', '累累火齐忽堆盘，水里硫黄得饫餐。忆得旧时风味在，故人唯有一任安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '昨晚目录之句盖聊以为戏耳何分惠之甚速耶得非乞诸其邻乎' AND p.poem_author = '虞俦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春晚用对酒韵', '陆游', '宋代', '吾今归哉复归哉，草堂正对湖山开。座铭漆园养生主，屏列柴桑归去来。\n\n一闲可敌八珍美，骊驹在门端可起。不缘老病日日增，世味从来淡如水。\n\n故人谁非白头新，况复眼中无故人。但馀一恨未免叹，掩关睡过今年春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春晚用对酒韵' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('钱塘怀古', '王鸣雷', '明代', '越鸟偏从越客栖，哑哑飞过秣陵西。梦归杨柳多生水，心想芙蓉尽种堤。\n\n江色草侵吴地阔，月明帆隔楚天低。相招直向渔人问，棹入沧浪何处溪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '钱塘怀古' AND p.poem_author = '王鸣雷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉连环', '朱祖谋', '清代', '花翻歌扇衣香卸。梦云低亚。沙棠双桨绮罗尘，愁不耐、沧波泻。\n\n风定絮花凝榭。晚莺閒话。不辞高馆领春寒，坚坐看、斜阳下。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉连环' AND p.poem_author = '朱祖谋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再用前韵', '郭印', '宋代', '我生垂四十，两鬓抽素发。\n声色不挂眼，岂羡凌波袜。\n唯有学道心，了不见超越。\n何由插羽翰，往造金门谒。\n反观金水性，端似天边月。\n本从无中来，一物肇恍惚。\n玉兔吐寒光，琪树遥清樾。\n亭亭照八弦，圆影射沧渤。\n斯言世岂闻，轻泄恐天罚。\n吁嗟夸毗子，自分无仙骨。\n狥财析秋毫，嗜酒醉深窟。\n一迷不复返，长病如中暍。\n空存玄牝门，金枢已摧阙。\n犹为儿女计，白首恋簪笏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再用前韵' AND p.poem_author = '郭印';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九日与诸僚长登茱萸亭', '潘梅', '明代', '令节凭高引兴长，半天秋色落壶觞。茱萸亭畔濡凉露，砧杵人间捣夕阳。\n\n天碧纵横啼过雁，山青悲咽乱唫螀。不知此日龙山会，潦倒谁如落帽狂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九日与诸僚长登茱萸亭' AND p.poem_author = '潘梅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉饯高尊师如贵道士传道录毕归北海 【录竹', '李白', '唐代', '道隐不可见，灵书藏洞天。吾师四万劫，历世递相传。\n别杖留青竹，行歌蹑紫烟。离心无远近，长在玉京悬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉饯高尊师如贵道士传道录毕归北海 【录竹' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闲述', '王彦泓', '明代', '一径松声几菊丛，穷楼风味未全穷。买泉试点秋茶绿，僦骑停看晚树红。\n\n非睡即游铅椠少，吊归兼醉锦囊空。残编更把东轩烛，牛背斜阳读未终。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闲述' AND p.poem_author = '王彦泓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜雨十首 其六 雨舟', '弘历', '清代', '旱甚鱼遭竭泽忧，舟胶都类置杯舟。所欣大霈苏物命，讵为长川畅已游。\n\n桂棹筠篷方利济，明滩暗濑总增流。一帆书画襄阳似，风片烟丝卒未休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜雨十首 其六 雨舟' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄鹤谣寄吴季谦侍郎时季谦自德安入城予适以', '岳珂', '宋代', '卢山白鹤归来双，缟衣素袂玄为裳。\n翅如车轮夜横江，风声曾走淮淝羌。\n戛然长鸣下柴桑，芝田啄粒遥相望。\n何人纲罗倏高张，上决云汉旁八荒。\n一随鹏鹍惊远翔，低头不肯谋稻粱。\n一罹置弋沮泽旁，局身筠笼翅摧藏。\n鹦鹉洲畔葭苇乡，水云苍苍江茫茫。\n九皋欲闻声不扬，回雇鸥鹭羞颜行。\n忽闻缑笙度宫商，红尘俯视有底忙。\n矶头刷羽今正黄，欲捶此楼呼酒狂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄鹤谣寄吴季谦侍郎时季谦自德安入城予适以' AND p.poem_author = '岳珂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和俞几先喜雨二首 其二', '曾协', '宋代', '自嗤宦况局寒蝉，已觉归心决大川。勿使山灵长谢客，幸馀溪友旧忘年。\n\n无心欲羡千钟禄，有意初谋二顷田。雨足年丰无一事，春蚕将老只思眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和俞几先喜雨二首 其二' AND p.poem_author = '曾协';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('兰', '郑元祐', '元代', '恊以鼓琴，世谁知音？采苢纫佩，湘江水深。兰生棘中，如石轥玉。\n\n玉受不瑳，幽香满谷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '兰' AND p.poem_author = '郑元祐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('罟里瞿良士属题先德子雍先生柴门临水图蒋子延所绘二首 其一', '夏孙桐', '清代', '水边林屋清无尘，惟许访书来问津。通德高门世所仰，先生原是菇芦人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '罟里瞿良士属题先德子雍先生柴门临水图蒋子延所绘二首 其一' AND p.poem_author = '夏孙桐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('箜篌引', '胡应麟', '明代', '良时率已迈，蟋蟀鸣我床。眷言召亲友，旨酒罗中堂。\n\n东邻饰妖女，南陌招名娼。绡衣随风举，罗袜自飘扬。\n\n秦声被金石，楚曲流宫商。清谈蔚霞烂，妙舞若云翔。\n\n颓阳倏西落，明月出东方。飞轩历层囿，改席临洞房。\n\n华灯吐芳焰，列宿澄清光。齐心怀令德，四坐咸尽觞。\n\n芳辰谅难再，嘉会讵可常。人命一朝尽，奄速如秋霜。\n\n乐哉今日宴，百岁遥相望。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '箜篌引' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('表忠卷为宁德李太华死倭难次韵三首 其一', '庞嵩', '明代', '百里郎官正属贤，闽山漳浦遘烽烟。撄城厉剑思酬主，裹革旋缰誓死边。\n\n林木夜寒归宿燕，野郊春尽忍闻鹃。浮名敢拟垂身后，独秉丹心一寸全。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '表忠卷为宁德李太华死倭难次韵三首 其一' AND p.poem_author = '庞嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和二十二弟不相遇之作', '晁说之', '宋代', '秋云欲遘雨，恼此山河凉。柴门试一出，矫目叹林光。\n\n孔鸾势自远，鸿雁意亦长。先后日云间，俗眼安得常。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和二十二弟不相遇之作' AND p.poem_author = '晁说之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春·少工艺文', '刘克庄', '宋代', '少工艺文，朱丝练弦，黄流在璋。值虞廷戛击，箫韶之乐，周王寿考，追琢其章。汾水雁飞，鼎湖龙远，魂返今无异域香。浮生短，更两轮屋角，来去荒忙。人言八十鹰扬。笑千岁如何尺捶量。但负图龟马，藏之为宝，舐丹鸡犬，去不能将。友鲁申公，师浮丘伯，尚可教书村学堂。投老泪，瞻越山紫翠，陵树青苍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春·少工艺文' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('魏夫人与众真吟诗二首 其二 十二月一日夜南岳夫人作与许长史', '佚名', '魏晋', '灵谷秀兰荣，藏身栖岩京。被褐均衮龙，带索齐玉鸣。\n\n表盘幽辽里，掷神太霞庭。霄上有陛贤，空中有真声。\n\n抑我曲晨飞，案此绿轩軿。下观八度内，俯叹风尘萦。\n\n解脱遗波浪，登此眇眇清。扰竞三津渴，奔驰割尔龄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '魏夫人与众真吟诗二首 其二 十二月一日夜南岳夫人作与许长史' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('少年游 织锦声', '黄钧宰', '清代', '年来花样喜翻新，越锦复吴绫。镫晕摇风，波纹逗雨，此意有谁听。\n\n西楼娇女笼纤玉，寒重梦初惊。只有疏篱，吟秋络纬，相和到天明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '少年游 织锦声' AND p.poem_author = '黄钧宰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('客中逢乡人得家中消息', '邓雅', '明代', '去家不忍别，久客遂忘还。忽见故乡人，与语增戚颜。\n\n比邻害疵疠，群从亦凋残。所幸一室安，卫生良独艰。\n\n语终对斜日，一鸟鸣空山。意存恍惚际，心在悲喜间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '客中逢乡人得家中消息' AND p.poem_author = '邓雅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('眼儿媚 呈周斡臣', '王恽', '元代', '桑榆晚景日＊＊。莫厌数相寻。静怜幽境，闲谈情话，与涤烦襟。济时幸有诸公在，乡社好浮沉。闲云却恐，西风吹去，认做商霖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '眼儿媚 呈周斡臣' AND p.poem_author = '王恽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('京华元夕诗 其十', '邓云霄', '明代', '酒态同推阮步兵，谁论中圣浊和清。六街金界开黄道，一夜瑶京变赤城。\n\n朋辈连镳堪玩赏，风光转眼几阴晴。柏浮且尽杯中物，身后休誇百代名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '京华元夕诗 其十' AND p.poem_author = '邓云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('主•奴才•奴隶', '何永沂', '当代', '功成赖假大天才，先把河山夺过来。唱罢人民当作主，笑抛诚信在蒿莱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '主•奴才•奴隶' AND p.poem_author = '何永沂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('【双调】落梅风_太乙宫探梅', '赵善庆', '元代', '太乙宫探梅\n\n冰花艳，水月魂，斗诗坛醉翁笔阵。自南枝漏泄了湖上春，问东风几番花信？\n\n江楼晚眺\n\n枫枯叶，柳瘦丝，夕阳闲画阑十二。望晴空莹然如片纸，一行雁一行愁字。\n\n秋晴\n\n秋声定，微雨歇，透疏棂纸窗风裂。孤灯儿似知愁恨切，照离人半明半灭。\n\n暮春\n\n寻芳宴，拾翠游，杏花寒禁烟时候。叫春山杜鹃何太愁，直啼得绿肥红瘦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '【双调】落梅风_太乙宫探梅' AND p.poem_author = '赵善庆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('旅寓岑寂中园丁送花四品因赋五绝', '杨公远', '宋代', '西蜀名花别样芳，玉环睡起试新妆。\n化工还有无情处，只与胭脂不与香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '旅寓岑寂中园丁送花四品因赋五绝' AND p.poem_author = '杨公远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和张周玉访别', '吴泳', '宋代', '白露下百草，年光惊易徂。\n邮亭人折柳，别浦雁衔芦。\n社瓮应藏酒，秋盘好斫鲈。\n贤渠陶靖节，晚岁觉迷涂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和张周玉访别' AND p.poem_author = '吴泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('说谜三绝 其一 帘', '吴儆', '宋代', '满身珠翠间花钿，舞到梁州最可怜。一捻宫腰如束素，清风明月画堂前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '说谜三绝 其一 帘' AND p.poem_author = '吴儆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('木哀十首 其一', '李江', '明代', '蟠桃秋叶落风寒，叶落风寒鼻亦酸。阆苑云空仙梦断，瑶池月落酒杯乾。\n\n韶华已付随流水，好合何期隔远峦。恼杀春花长不住，蟠桃秋叶落风寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '木哀十首 其一' AND p.poem_author = '李江';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('癸卯元日晴继复雪亦不废出谷日复晴归乡涂宿上元观灯野庙随所赋得十绝 其三', '刘诜', '元代', '市门处处系冰花，灯影蛾云动绛纱。走马城中三日雪，不知春已入谁家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '癸卯元日晴继复雪亦不废出谷日复晴归乡涂宿上元观灯野庙随所赋得十绝 其三' AND p.poem_author = '刘诜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长相思 其一', '释函可', '明代', '长相思，来何迟。荆山鼎就紫清归，六宫粉黛化作泥。\n\n王母高居在瑶池，无数仙人进玉饴。千秋万岁以为期，何不驾六龙中天飞。\n\n青鸟衔书到海涯，杲杲出日，浮云蔽之。长相思，不可知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长相思 其一' AND p.poem_author = '释函可';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄南文德纯家', '邢宥', '明代', '山外平湖水接天，渔竿放下又耕田。相过暇日多贤达，诗酒优游忘岁年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄南文德纯家' AND p.poem_author = '邢宥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('台湾八景', '高拱乾', '清代', '海上看朝日，山间尚晓钟。天开无际色，人在最高峰。\n\n紫阁催妆镜，咸池骇浴龙。风流灵运句，灼灼照芙蓉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '台湾八景' AND p.poem_author = '高拱乾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏潭柘寺竹', '玄烨', '清代', '翠叶才抽碧玉枝，经旬清影上阶墀。凌霜抱节无人见，终日虚心与凤期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏潭柘寺竹' AND p.poem_author = '玄烨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄浮图慧海', '岳飞', '宋代', '湓浦庐山几度秋，长江万折向东流。\n男儿立志扶王室，圣主专师灭虏酋。\n功业要刊燕石上，归休终伴赤松游。\n丁宁寄语东林老，莲社从此著力修。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄浮图慧海' AND p.poem_author = '岳飞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蜀府遇夏时教谕次韵叙德言怀', '方孝孺', '明代', '周道昔沦丧，凤鸟收其声。纷纷徇世士，各以智术鸣。\n\n仲舒起西都，蜀汉有孔明。下帷谈正谊，濡走济群生。\n\n二子苟遇时，惠泽𬒳孤茕。惜其遭逢谬，不见礼乐兴。\n\n迩来一千年，文献鲜有徵。岂无辅相贵，未免利禄婴。\n\n鄙夫何所知，浪窃当世名。致君事莫及，好古心徒倾。\n\n身疲道路长，兴入江山清。偶随群臣后，获见百代英。\n\n神姿俨渊肃，雄论极醇精。德政尚宽和，西土臻治平。\n\n福善固天理，愿治本民情。昔叹贤豪稀，今见德位并。\n\n寄言同袍子，拭目王化行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蜀府遇夏时教谕次韵叙德言怀' AND p.poem_author = '方孝孺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('代李叔介挽杨参政', '王质', '宋代', '运泰风云合，名高泰华秋。杓衡方北指，江汉已东流。\n\n寡祐良臣死，钟情志士忧。惊心波浪里，不见济川舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '代李叔介挽杨参政' AND p.poem_author = '王质';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('月上海棠', '赵我佩', '清代', '曲屏移过斜阳影。怨黄昏、一霎林烟暝。小立苍苔，隔花阴、袜尘香凝。\n\n湘帘捲，深院月明人定。\n\n暮云春树诗怀冷。似天公、付我伤心病。梦里闲愁，怕思量、旧时风景。\n\n红楼笛，忍把离魂唤醒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '月上海棠' AND p.poem_author = '赵我佩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南乡子', '文徵明', '明代', '香暖透春肌，满眼新娇睡起迟。燕子不来三月尽，依依，手撚残花玉一枝。\n\n风袅鬓云垂，无限闲愁隐翠眉。好梦不成春自去，相思，只有青团扇子知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南乡子' AND p.poem_author = '文徵明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病剧就养城北玉清道院作三章 其三', '姚燮', '清代', '悔乃愤之几，何如慎诸后？自镜平生端，炯象毕呈丑。\n\n猛警同晨钟，尘去复奚帚？鬼神惕我危，相待益徵厚。\n\n坦掌偶失持，势遂邻械杻。命无侥倖存，正以顺为受。\n\n岂真石作罂，其坚逊陶缶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病剧就养城北玉清道院作三章 其三' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四和林卿槟榔韵一首', '刘克庄', '宋代', '似椰内贮杯中物，非曲谁篘瓮面春。百粤姻盟常主约，三彭谗舌竟无神。\n\n浪云软饱元枵腹，暂借酡颜戏写真。此遣两行红袖去，锦潮亭下草如茵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四和林卿槟榔韵一首' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄武冈宰宋雪岩', '张炜', '宋代', '柳下分攜须影苍，好风吹梦过都梁。\n诸蛮帖化花阴静，一骑飞尘荐墨香。\n书就几曾逢驿使，公余应不冷奚囊。\n云情鹤态元如旧，应倚株梅忆锦乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄武冈宰宋雪岩' AND p.poem_author = '张炜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大梁候吴明卿不得闻尚留里中赋此促之', '王世贞', '明代', '一往除书岁月深，怪来鸿信误追寻。三朝老共思家梦，万里归偏薄宦心。\n\n客笑元长宁寂寂，人窥夥涉莫□□。□□□□□□□，□□□□□□□。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大梁候吴明卿不得闻尚留里中赋此促之' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病中别沈子嘉则之扬州', '王世贞', '明代', '溽炎始见蠲，微痾俄相逐。故人弃我去，使我惊局促。\n\n杂绪难尽言，轻帆易辞目。惆怅离后思，广陵雨中绿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病中别沈子嘉则之扬州' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和闲来', '邵雍', '宋代', '以身观万物，万物理非遥。\n马为乘多瘦，龟因灼苦焦。\n能言谢鹦鹉，易饱过鹪鹩。\n伊洛好烟水，愿同渔与樵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和闲来' AND p.poem_author = '邵雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题历山舜祠', '杜荀鹤', '唐代', '昔舜曾耕地，遗风日寂寥。世人那肯祭，大圣不兴妖。\n\n殿宇秋霖坏，杉松野火烧。时讹竞淫祀，丝竹醉山魈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题历山舜祠' AND p.poem_author = '杜荀鹤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('田家', '周馨桂', '清代', '每当秋熟尚啼饥，况此河乾尘欲飞。买得前村钓溪水，归来典尽箧中衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '田家' AND p.poem_author = '周馨桂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暮春寄怀曹南通任寺丞', '林逋', '宋代', '跌荡情怀每事同，十年曹社醉春风。\n弹弓园圃阴森下，棋子厅堂寂静中。\n赤脚我犹无一婢，黑头君合作三公。\n江湖今日还劳结，目送归飞点点鸿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暮春寄怀曹南通任寺丞' AND p.poem_author = '林逋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六月廿七日诸君子会予草堂次前韵四首 其一', '孙承恩', '明代', '重订茅堂约，无嗔折简招。追游匪公等，意气向谁消。\n\n村酿分邻瓮，山蔬荐菊苗。安期如可访，欲去海门樵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六月廿七日诸君子会予草堂次前韵四首 其一' AND p.poem_author = '孙承恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送陈亨叔县丞', '刘克庄', '宋代', '已折仙桂到月宫，安知再转瘴烟中。\n坐看管□封孤□，却使崔丞对二松。\n此士鼻端何待垩，老生指血至今红。\n祝君努力鸣昭代，切勿呻吟学冻蛩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送陈亨叔县丞' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送彦立兄游太学以恩袍草色动为韵', '王之道', '宋代', '梅花破朝寒，似欲壮行色。\n骎骎小骊驹，回首便数驿。\n一鹗在云路，鸷鸟空累百。\n从令马宾王，不是新丰客。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送彦立兄游太学以恩袍草色动为韵' AND p.poem_author = '王之道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('熙宁五年归至旧山伤己感时作诗奉呈升卿黄丈 其二', '吕南公', '宋代', '彬树湖前流水远，石城街左乱山苍。滩深潭浅无由问，竹秀松枯不可常。\n\n物理自应随变动，道心聊欲寄存亡。唯君坐占忘言境，珍重诗编与酒觞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '熙宁五年归至旧山伤己感时作诗奉呈升卿黄丈 其二' AND p.poem_author = '吕南公';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送祖印忠师南归', '苏颂', '宋代', '扰扰京华客，营营不自间。\n胡为丘壑者，亦到市朝间。\n孤月无留影，归云靡定山。\n东南清胜处，羡子一舟还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送祖印忠师南归' AND p.poem_author = '苏颂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('刘孺人挽诗', '叶适', '宋代', '嗃嗃当年女手缝，一家从此更雍雍。\n性安於善行无迹，儿自为铭笔有踪。\n闻说湖清见龙首，还疑墓长羃云峰。\n哀情变化何级极，留泽凌霄绛绕松。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '刘孺人挽诗' AND p.poem_author = '叶适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '王中立', '宋代', '醉袖舞嫌天地窄，诗情狂压海山平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '王中立';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻周孟', '魏野', '宋代', '乙巳暮春天，端居忽怆然。一名伤圣祖，三榜作遗贤。\n\n我自空弹指，君谁可比肩。何由销此恨，独坐落花前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻周孟' AND p.poem_author = '魏野';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长相思二首 其二', '徐陵', '南北朝', '长相思。好春节。梦里恒啼悲不泄。帐中起。窗前髻。\n\n柳絮飞还聚。游丝断复结。欲见洛阳花。如君陇头雪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长相思二首 其二' AND p.poem_author = '徐陵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春波书屋为屠司寇赋', '王鏊', '明代', '平湖渺渺春波绿，榆柳低垂洲渚曲。洲旁茅屋是谁家，言是屠公旧书屋。\n\n屠公致身廊庙里，犹有读书心未已。牙签缥轴置两头，充栋多还比邺侯。\n\n湖水平，春日晴，船头置书蓬底读，吾伊声和沧浪曲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春波书屋为屠司寇赋' AND p.poem_author = '王鏊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉泉双柏行', '幻庐', '当代', '西来何意碧眼胡，静照以心独跏趺。满驮经卷任撕破，庭前唯指双柏株。\n\n一株叶细供瀹茗，一株枝茂藏栖乌。时非乌去销爪迹，清茗年年说空无。\n\n月地潜聆堕子实，悟开当下逋斯须。佛元在心心即佛，渠定是我我逢渠。\n\n法门微妙弃文字，拈花默会花同殊。青莲冉冉萦篆冷，沈水名香爇宣炉。\n\n营卫遐龄之丹灶，洗伐毛髓之醍醐。枯蕊春泥掌中示，尘虑宁将一日疏。\n\n桓侯剑门翠云蔽，将军汉武嵩阳初。合与少陵重梁栋，兴感毋用久踟蹰。\n\n凛然夭矫戴霜雪，千尺黛色淩斗枢。不涸不盈到池定，护持八部神龙居。\n\n异代衣履几曾识，甘泉长浸波心珠。苦茶心清心化苦，古者为师今为徒。\n\n柏林座中三让毕，真笔再著形传摹。急扫风雨焦墨透，世间清奇古怪图。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉泉双柏行' AND p.poem_author = '幻庐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送人游天台', '邓文原', '元代', '此去兰亭修禊后，平明驱马试征衣。海边山尽天无尽，花底春归人未归。\n\n一雨潮生鱼入市，远岩月上鹤投扉。旧游二十年前路，孤负东风赋《采薇》。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送人游天台' AND p.poem_author = '邓文原';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('好事近（雪中携酒过元长）', '赵鼎', '宋代', '春色遍天涯，寒谷未知消息。且共一尊芳酒，看东风飞雪。 \n 太平遗老洞霄翁，相对两华发。一任醉魂飞去，访琼瑶宫阙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '好事近（雪中携酒过元长）' AND p.poem_author = '赵鼎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠王将军贞伯二章 其一', '胡应麟', '明代', '镇北威名著，安东将略长。援枹肝胆赤，仗钺鬓毛苍。\n\n置阵分鹅鹳，连镳控骕骦。旌旗萦析木，樯橹散扶桑。\n\n草檄屯兵地，分题结客场。荀吴元破敌，段颎旧平羌。\n\n巨碣祁连外，高牙敕勒傍。煌煌麟阁燕，兽锦出明光。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠王将军贞伯二章 其一' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送叶成夫还闽中', '许天锡', '明代', '南征白雁叫秋旻，送尔归骖忆故人。月旦有评惭许劭，婚姻不断羡朱陈。\n\n山间松叶他时醉，洞口榴花几度新。怀梓况逢多病后，梦中鱼鸟递相亲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送叶成夫还闽中' AND p.poem_author = '许天锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二月二十三日犹在仪真馆二首 其二', '郝经', '元代', '二月还如夏，炎蒸郁震惊。迅霆侵骨冷，飞电透心明。\n\n海气沾衾湿，江声拍枕平。从今休禁火，一雨万家生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二月二十三日犹在仪真馆二首 其二' AND p.poem_author = '郝经';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读赤壁赋前后二首 其一', '文天祥', '宋代', '昔年仙子谪黄州，赤壁矶头汗漫游。今古兴亡真过影，乾坤俯仰一虚舟。\n\n人间忧患何曾少，天上风流更有不。我亦洞箫吹一曲，不知身世是蜉蝣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读赤壁赋前后二首 其一' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望柳', '崔荣江', '当代', '柳丝如我思，春始便垂长。千缕为君发，一心缘别伤。\n\n风泠酸望眼，雨细淡红妆。有燕何持剪，双飞绞断肠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望柳' AND p.poem_author = '崔荣江';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('仲春宜八里国道中', '释宗泐', '明代', '芭蕉叶开大如席，石榴花发红满枝。子规何似苦啼血，正是行客东还时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '仲春宜八里国道中' AND p.poem_author = '释宗泐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水龙吟 挽吕小薇先生', '傅义', '当代', '忽惊噩耗飞来，西江痛失吾元老。无多硕果，君何竟去，玉楼幽渺。\n\n千里频飘，一灯独守，冰心雪抱。叹半生侘傺，昊天不吊。\n\n薤歌彻，奎星杳。\n\n忆昔初窥隽藻，便深钦易安才调。韶华方茂，遽临衰迈，始瞻芝貌。\n\n卧疾频年，体羸神旷，尚相言笑。又凝情北望，倚篁衔泪，抚千秋稿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水龙吟 挽吕小薇先生' AND p.poem_author = '傅义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮·包中香黍分边角', '陈义', '未知', '包中香黍分边角。彩丝剪就交绒索。樽俎泛菖蒲。年年五月初。主人恩义重。对景承欢宠。何日玩山家。葵蒿三四花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮·包中香黍分边角' AND p.poem_author = '陈义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('用之相访忽忆汉孙不得一脉以死用前韵', '李石', '宋代', '叩门剥啄涕沾襟，忽忆僧孙病骨侵。\n壁上卧龙香线断，柱间题凤墨痕深。\n仓皇不瞑思君眼，辗转犹希住世心。\n真意自天渠信否，赠篇聊当阁中箴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '用之相访忽忆汉孙不得一脉以死用前韵' AND p.poem_author = '李石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和沈演公夜坐韵', '李洸', '近代', '一例肠如九曲盘，谁教愁绪入毫端。好春已觉寻游懒，恶抱争知湔韨难。\n\n楼外车声同雨闹，客中酒味胜梅酸。年时踪迹还相似，短烛残书坐夜阑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和沈演公夜坐韵' AND p.poem_author = '李洸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('征粮至浮河宿詹氏书斋次壁间韵', '孔毓玑', '清代', '雨过青山翠万重，浮河新水浸芙蓉。入门先拭题诗壁，裁句时闻隔院钟。\n\n只愿康衢酬帝力，敢期褒德启侯封。明年幸免催科累，载酒携筐劳尔农。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '征粮至浮河宿詹氏书斋次壁间韵' AND p.poem_author = '孔毓玑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红 其二 勖受军训诸生', '卢前', '近代', '一息尚存，应未忘、匹夫之责。天下事、危如累卵，万千苦厄。\n\n患难迫人当大任，鞠躬尽瘁吾何惜。看中吴、当日小周郎，匡时策。\n\n尽汝力，完天职。心不死，血终热。念江山信美，旧时踪迹。\n\n尝胆卧薪师勾践，冲天奋翼怜萧特。补金瓯、誓我十年期，书诸褶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红 其二 勖受军训诸生' AND p.poem_author = '卢前';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和韵 其二', '韩淲', '宋代', '酴醾一架煖争开，投老看花得几回。兴以芳时寻醉去，诗从永日送香来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和韵 其二' AND p.poem_author = '韩淲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('得吕山人报', '陈迁', '明代', '忽闻消息百忧攒，书到飞邮不忍看。蛮土岂终埋侠骨，白头何事泣南冠。\n\n呼朋问酒心先醉，垂死怜君胆未寒。莫向词林赋鹦鹉，妒人风雪易凋残。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '得吕山人报' AND p.poem_author = '陈迁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江头绝句 其十二', '程本立', '明代', '孰知中国外，民俗乃驺虞。舞意存千羽，歌情在裤襦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江头绝句 其十二' AND p.poem_author = '程本立';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('安稳道中', '江源', '明代', '戒晓星轺度翠微，不堪野雾湿征衣。长桥跨涧水千尺，古庙依山树四围。\n\n愁我岖崎坡上路，爱他潇洒竹间扉。前程去去知何许，啼鸟声中又落晖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '安稳道中' AND p.poem_author = '江源';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵朱新仲省宿十首 其九', '刘才邵', '宋代', '与作先秋蒲，岂若经霜竹。坚脆随所养，古人戒多欲。\n\n年来铅汞鼎，丹火犹未伏。更须形中神，各各司其局。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵朱新仲省宿十首 其九' AND p.poem_author = '刘才邵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻王子房中丞死寇志感', '黎遂球', '明代', '都城鹫峰寺，忆尔隔垣看。生死七年易，勋劳千古难。\n\n忠魂应自吊，社稷信谁安。涕泪遥堪寄，秋墟汴水寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻王子房中丞死寇志感' AND p.poem_author = '黎遂球';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('富春舟中', '佘翔', '明代', '寒云落木晚萧萧，人与孤舟对寂寥。忽见西风吹五两，月明还趁浙江潮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '富春舟中' AND p.poem_author = '佘翔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜过谢池小酌戏继前韵示诸友', '欧阳澈', '宋代', '为忆莲娃夜叩门，恐缘芳草怨王孙。眉弯海峤初生月，鬓亸巫峰欲坠云。\n\n金粟花残将委烬，香丝篆破不成文。朦胧月映人如玉，尔汝忘形共一樽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜过谢池小酌戏继前韵示诸友' AND p.poem_author = '欧阳澈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和西湖竹枝词', '朱庸', '元代', '小姑疑郎去不归，为郎打瓦复钻龟。青山尚有飞来日，不信人无相见时。\n\n阿奴采莲湖上舟，阿郎贩豆辽东州。一心愿逐东流水，流送辽东古渡头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和西湖竹枝词' AND p.poem_author = '朱庸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出塞二首 其二', '王世贞', '明代', '不断穹庐色，檀槽压酪浆。俄闻五校至，去逐六骡亡。\n\n蒲类天如赭，燕支月似霜。前军又铙吹，生得左贤王。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出塞二首 其二' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浯亭望横山', '游九功', '宋代', '峨峨岸东山，躣来势奔虬。\n横约一溪水，抱邑止复流。\n近郭看逾好，向望此其尤。\n翠展曲屏宽，一目千里收。\n此山此水水，我歌我来游。\n知不市声杂，亦忘溪上幽。\n方将解其缚，于焉我何求。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浯亭望横山' AND p.poem_author = '游九功';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七月十六日晚雨已而月出', '周紫芝', '宋代', '将雨日已晏，既晴天亦曛。风从莽苍来，云向西南奔。\n\n忽于苍玉玦，拥此黄金盆。我居在山顶，升沉阅冰轮。\n\n三年东冈头，入我圭窦门。平生金兰友，老去无一存。\n\n愿言结神交，相与论素心。素心不可说，月亦终无言。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七月十六日晚雨已而月出' AND p.poem_author = '周紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴中友人惠蟹', '宋祁', '宋代', '秋水江南紫蟹生，寄来千里佐吴羹。\n楚人欲使衷留甲，齐客何妨死愿烹。\n下筯未休资快嚼，持螫有味散朝酲。\n定知不作蟛蜞悮，曾厕西都博士名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴中友人惠蟹' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵前人贵籴', '陈著', '宋代', '麦甑凄凉稻尚青，粒珠乘急价掀腾。\n市平本易无千斛，仓籴良艰且五升。\n长是信天还自活，未能送鬼任多憎。\n回头钟鼓群峰寺，饱饭高眠独有僧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵前人贵籴' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五更枕上', '黄虚舟', '宋代', '睡觉愁无奈，难禁冬夜长。\n才听晓钟动，又是世人忙。\n入市船撑月，朝天马踏霜。\n布衾绵杲软，切莫笑寻常。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五更枕上' AND p.poem_author = '黄虚舟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('恭承宗伯陈秋涛师移惠双桐树子当春深畅生赋诗奉谢', '黎遂球', '明代', '惭愧劳薪入爨声，长安犹问破琴名。新栖又长双桐子，珍重南枝慰月明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '恭承宗伯陈秋涛师移惠双桐树子当春深畅生赋诗奉谢' AND p.poem_author = '黎遂球';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('姑苏绝句五首 其四', '李映斌', '当代', '浓荫重檐只碍天，閒将吟绪绿成烟。深庭窄巷春归晚，微雨落花人并肩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '姑苏绝句五首 其四' AND p.poem_author = '李映斌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卢沟桥抗战纪事 其十一', '王冷斋', '近代', '谲计俱穷出遁辞，强论旧贯益支离。三年纵得墙东立，堂奥何曾许一窥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卢沟桥抗战纪事 其十一' AND p.poem_author = '王冷斋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菖蒲歌', '释宗泐', '明代', '蒲生山泽间，水石长为徒。超然尘土外，秀色清而腴。\n\n印公爱之如寂公，当轩盆植数十丛。虽无仙人鸾凤状，好事剪拂还相同。\n\n叶如虬须直不卷，根穿石罅连苍藓。昔闻张生十二节，苏子九花今宛宛。\n\n眼中清气端可掬，此处焉知有尘俗。去年赠我小石盆，几上团团青一簇。\n\n知君定出聊自怡，此心岂为物所移。色空都忘心境寂，寥寥独坐轩中时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菖蒲歌' AND p.poem_author = '释宗泐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('北山之高寿北山何先生', '金履祥', '宋代', '夫子曰道，惟帝之蹈。\n臣何容力，亦聿既耄。\n天子曰吁。鸿飞冥冥，\n罔终弃予。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '北山之高寿北山何先生' AND p.poem_author = '金履祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('碧城三首（其一）', '李商隐', '唐代', '碧城十二曲阑干，\n犀辟尘埃玉辟寒。\n阆苑有书多附鹤，\n女床无树不栖鸾。\n星沉海底当窗见，\n雨过河源隔座看。\n若是晓珠明又定。\n一生长树水精盘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '碧城三首（其一）' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('锦鸡', '周权', '元代', '巴山灵鸟初离群，葳蕤丽组云锦文。羽翎新刷爪距利，采色胜似沙头鸳。\n\n晴暾入户烂相射，嗉中有物垂红碧。绶光若若花盘绦，出示山童有矜色。\n\n文章固足媒尔身，雕笼拘絷还悲辛。区区啄饮岂不厚，情深野树溪云春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '锦鸡' AND p.poem_author = '周权';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春 读《龙胆紫集》后赠李锐同志', '胡遐之', '当代', '用药棉签，蘸龙胆紫，写血泪词。奈诗魂剑魄，能穿铁壁；\n\n忠心赤胆，徒唤秋思。祸国城狐，跳梁社鼠，举足能教天意随。\n\n君休问，那庐山真面，何处晴霓？\n\n缅怀先烈崔巍，任百折千磨志未灰。有通禅妙句，了除魔障；\n\n等闲白发，又著青丝。大别香兰，君山翠竹，万里喜迎辕驾归。\n\n长安道，看凌霄华表，处处堪题。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春 读《龙胆紫集》后赠李锐同志' AND p.poem_author = '胡遐之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山中寡妇 / 时世行', '杜荀鹤', '唐代', '夫因兵死守蓬茅，麻苎衣衫鬓发焦。\n桑柘废来犹纳税，田园荒后尚征苗。\n时挑野菜和根煮，旋斫生柴带叶烧。\n任是深山更深处，也应无计避征徭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山中寡妇 / 时世行' AND p.poem_author = '杜荀鹤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄题道吾山闻禅师竹院', '丁复', '元代', '道吾竹院芙蓉下，老子藤床翡翠深。过雨雷霆龙拥闼，满天风露鹤当林。\n\n此君静对了不厌，诸老清谈亦许寻。他山祭酒闻还出，何人载歌金玉音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄题道吾山闻禅师竹院' AND p.poem_author = '丁复';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观陈希夷先生真及墨迹', '邵雍', '宋代', '未见希夷真，未见希夷蹟。\n止闻希夷名，希夷心未识。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观陈希夷先生真及墨迹' AND p.poem_author = '邵雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('钓鱼操', '虞堪', '明代', '瞰沧浪而盘礴，阅浮云之卷舒。物悠悠其永逝，吾何心而钓鱼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '钓鱼操' AND p.poem_author = '虞堪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉送岭西王公参政湖南 其三', '叶春及', '明代', '蒲柳空嗟犬马年，祇应松柏晚犹妍。漫劳一郡推麟笔，岂有三长过马迁。\n\n藻井夜登穿海月，桂林秋泛澹江烟。论文后会知何地，遥望清光北斗边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉送岭西王公参政湖南 其三' AND p.poem_author = '叶春及';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浪淘沙 春怨', '沈谦', '明代', '河流尽含颦。也学愁人。隔窗莺语泥斜曛。满眼落花多似泪，终日纷纷。\n\n宽带小腰身。怕杀黄昏。月来还共影寒温。最是今年情兴好，睡过三春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浪淘沙 春怨' AND p.poem_author = '沈谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汉玉松石图', '弘历', '清代', '一株与一拳，古玉成新制。虽乏圭璋材，不渝贞白意。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汉玉松石图' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('田舍', '胡宿', '宋代', '农家秋物成，腰镰刈新谷。得食鸡豚肥，饱霜梨栗熟。\n\n牧童唱田歌，孺子宰社肉。野老醉亦讴，爱此羲皇俗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '田舍' AND p.poem_author = '胡宿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('摆绣鸡 其二', '韦骧', '宋代', '一片垂丹臆，鲜明锦不如。殷红间深翠，半敛又全舒。\n\n未遇夺真画，犹虚博物书。虽非孔鸾比，傥可诧其馀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '摆绣鸡 其二' AND p.poem_author = '韦骧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('代公庆上郭帅', '王灼', '宋代', '昔年先庙谒汾阳，提笔从公写短墙。\n再别巴江油戟下，七逢天竺桂枝香。\n宦途自许安仁拙，浮俗谁怜处士狂。\n客舍无烟饥欲死，尚惭知已问行藏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '代公庆上郭帅' AND p.poem_author = '王灼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄徐滁州埻立', '韩元吉', '宋代', '青琐金鸾迹未容，寘公犹在昔贤中。\n著书定已追迂叟，得郡何妨号醉翁。\n丰乐桥边鱼动镜，清流关下马嘶风。\n独怜湛辈犹奔走，不得登临一笑同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄徐滁州埻立' AND p.poem_author = '韩元吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('瓜', '弘历', '清代', '桃笙潋碧漪，冰盘荐绿玉。熨齿凛浆寒，沁怀消暑酷。\n\n四序不相代，万物各生育。至今种瓜人，道是青门族。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瓜' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄题程氏菊庄 其二 陶令', '马廷鸾', '宋代', '一觞浥露餐英美，八表同昏履运艰。芳节不随篱下老，悠悠嘉气眼中山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄题程氏菊庄 其二 陶令' AND p.poem_author = '马廷鸾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居偶成（四首）', '憨山大师', '明代', '滚滚红尘世路长，不知何事走他乡。\n回头日望家山远，满目空云带夕阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居偶成（四首）' AND p.poem_author = '憨山大师';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青玉案', '龚自珍', '清代', '钱塘词伯春怀动。正献罢，长杨颂。门外缁尘飞玉鞚。\n\n长条冶叶，明窗画出，西子湖边梦。\n\n三生清怨凭谁送。悔向灵和殿前种。头白沈郎官供奉。\n\n要添几笔，濛濛飞絮，漠漠春芜重。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青玉案' AND p.poem_author = '龚自珍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归墅', '李商隐', '唐代', '行李逾南极，旬时到旧乡。楚芝应遍紫，邓橘未全黄。 \n 渠浊村舂急，旗高社酒香。故山归梦喜，先入读书堂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归墅' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东山', '丁逢', '宋代', '水绕山围夏木苍，旧时贤相读书堂。\n窗间远岫供吟遍，来倚阑干半月凉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东山' AND p.poem_author = '丁逢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题孙典伏可居轩', '孙蕡', '明代', '吾宗孙子云鹤仙，荷衣蕙带神飘然。朝吟屈子远游赋，夜诵庄生秋水篇。\n\n五湖风月穷清赏，青雀为舻桂为舫。二女祠前听凤箫，小孤舟北闻渔榜。\n\n归来匹马逐嫖姚，环佩锵锵近九霄。承恩日侍金銮殿，卜筑还依朱雀桥。\n\n桥头流水清如玉，杨柳青青映书屋。照座虽无鄂渚花，当庭亦种沅湘竹。\n\n沅湘竹色报春迟，文玉疏疏只数枝。客去每凭诗作伴，朝回偏与静相宜。\n\n卜筑不雕亦不画，厅事门前仅旋马。高题汉篆名可居，君作其中可居者。\n\n人生出处本无端，坎止流行信可安。君不见长安甲第连云起，赢得人间图画里。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题孙典伏可居轩' AND p.poem_author = '孙蕡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆文正公尝欲卜居宜兴', '邵宝', '明代', '几年卜筑欲江东，阳羡溪山罨画中。\n千里有情春草遍，一樽无地暮云空。\n相州未得归韩老，汝颍犹堪葬长公。\n曾说近游须馆我，吾亭今合号涯翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆文正公尝欲卜居宜兴' AND p.poem_author = '邵宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('燕馆日膳得四雁笼之以归', '洪适', '宋代', '提携乘雁脱庖丁，等待他年羽翼成。唳月摩云须有便，莫教更作不能鸣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '燕馆日膳得四雁笼之以归' AND p.poem_author = '洪适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢新恩', '李煜', '唐代', '樱花落尽阶前月，象床愁倚薰笼。远似去年今日，恨还同。\n\n双鬟不整云憔悴，泪沾红抹胸。何处相思苦，纱窗醉梦中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢新恩' AND p.poem_author = '李煜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('笠泽渔父词四首 其三', '文彭', '明代', '钓得鲈鱼不卖钱，船头吹火趁新鲜。樽有酒，月将圆，落得今宵一醉眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '笠泽渔父词四首 其三' AND p.poem_author = '文彭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观物吟二首', '邵雍', '宋代', '柳性至柔软，一年长丈余。\n虽然易得荣，奈何易得枯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观物吟二首' AND p.poem_author = '邵雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山阳泊舟', '尹廷高', '元代', '南枕湖光北枕淮，百年形势画图开。黄昏鼓角孤城闭，尚记秋风万马来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山阳泊舟' AND p.poem_author = '尹廷高';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暴雨', '韦庄', '唐代', '江村入夏多雷雨，晓作狂霖晚又晴。 \n 波浪不知深几许，南湖今与北湖平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暴雨' AND p.poem_author = '韦庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹枝词 其一', '李洸', '近代', '出郭车轻飏雨丝，春人委结及芳时。回头百媚堤边树，似搅柔肠踠地垂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹枝词 其一' AND p.poem_author = '李洸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花 秋日游公园', '芍印', '近代', '秋淡红销人意恼。裙履联吟，缓步园林好。浅碧粼粼鱼影杳。\n\n萧条风物寒烟绕。\n\n僻境深藏三径草。小作勾留，喜把风尘扫。随意芒鞋凌缥渺。\n\n凭他秋暮和春晓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花 秋日游公园' AND p.poem_author = '芍印';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('为许氏赠妾', '皇甫汸', '明代', '窈窕一佳人，铅华世绝伦。花因解语艳，山入画眉颦。\n\n宝髻随时广，罗衣逐态新。坐令幽谷里，无夜不生春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '为许氏赠妾' AND p.poem_author = '皇甫汸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵十绝·病起', '楼钥', '宋代', '老去情怀百不宜，上楼腰腰觉舒迟。\n适斋异禀人难及，病起精神略不衰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵十绝·病起' AND p.poem_author = '楼钥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄山中友人 其二', '释文珦', '宋代', '清修二师持远徒，麻衣草座深山居。心如莲花不著水，身似孤云行太虚。\n\n记得茅堂明月夕，同汲寒泉煮白石。多年不见拟相寻，秋风落叶迷行迹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄山中友人 其二' AND p.poem_author = '释文珦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送丁直谅赴西涧山长 其一', '王义山', '宋代', '西涧元来只是刘，叶公争取过台州。退斋赤手来兴复，上水篙撑急向流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送丁直谅赴西涧山长 其一' AND p.poem_author = '王义山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九日', '清濋', '明代', '头白眼昏无住著，大都客里过重阳。人生便满一百岁，消得黄花几度香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九日' AND p.poem_author = '清濋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄西峰道士七首 其五', '刘永之', '元代', '夜礼珠衡佩玉锵，庆云低绕郁金章。空中鹤语神君至，睡鸭频添百和香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄西峰道士七首 其五' AND p.poem_author = '刘永之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('磊园舍作禅林招予主社感而留题', '释函是', '明代', '四十年来事转新，此时泉石昔时人。右军第宅今犹在，晋室山河久已湮。\n\n拄杖尚能观布地，栽松真欲论前因。深堂雁影何由度，莫话寒山春信频。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '磊园舍作禅林招予主社感而留题' AND p.poem_author = '释函是';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题红梅', '梁兰', '明代', '贞态由来白，轻红故恼人。莫将桃李比，别是一枝春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题红梅' AND p.poem_author = '梁兰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归国谣 嫦娥', '曾廉', '清代', '真失措。月宫巧把嫦娥锢。行人不见眼前路。\n\n嫦娥常在广寒府。清光吐。只消收得吴刚斧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归国谣 嫦娥' AND p.poem_author = '曾廉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东园幽步见东山四首 其四', '杨万里', '宋代', '天赐东园食实封，东山加赐在园东。东山山色浑无定，阴处青苍晒处红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东园幽步见东山四首 其四' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十六字令 其二', '王夫之', '明代', '落花影，风飐小桥西。掠素袷，疑是染香泥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十六字令 其二' AND p.poem_author = '王夫之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日即事二首 其一', '饶节', '宋代', '人言春事经桃李，我欲要之病未任。昨日强随年少去，看花那复故时心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日即事二首 其一' AND p.poem_author = '饶节';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('予久客思归以秋光都似宦情薄山色不如归意浓为韵言志约金溧诸友共赋寄钱唐亲旧 其九', '仇远', '宋代', '乔木足秋声，红叶表秋色。因之念湖山，恨不生羽翼。\n\n形留神已驰，游倦交渐息。西邻夜砧发，东邻晓机织。\n\n我亦有敝庐，松菊暗荆棘。北山百年墓，苔竹手所植。\n\n今长尺若干，霜雪颇自力。西风龙蛇蛰，暗雨山林黑。\n\n东望会言归，免我长相忆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '予久客思归以秋光都似宦情薄山色不如归意浓为韵言志约金溧诸友共赋寄钱唐亲旧 其九' AND p.poem_author = '仇远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阮郎归（远德殿作和赵志忠）', '赵眘', '宋代', '留连春意晚花稠。云疏雨未收。新荷池面叶齐抽。凉天醉碧楼。能达理，有何愁。心宽万事休。人生还似水中沤。金樽尽更酬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阮郎归（远德殿作和赵志忠）' AND p.poem_author = '赵眘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西县道中有短亭，岩穴飞泉隔江洒至，因成二首', '薛能', '唐代', '风凉津湿共微微，隔岸泉冲石窍飞。 \n 争得巨灵从野性，旧乡无此擘将归。 \n 一瀑三峰赤日天，路人才见便翛然。 \n 谁能夜向山根宿，凉月初生的有仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西县道中有短亭，岩穴飞泉隔江洒至，因成二首' AND p.poem_author = '薛能';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('村人日以道士作佛事感叹有作', '郭之奇', '明代', '黄老微言那可磨，沙门精道复如何。南方亦有伊蒲塞，北地休悲曳落河。\n\n安得诸天挥玉麈，先从尘世止金戈。未烦苦海求津渡，长使禅幡映薜萝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '村人日以道士作佛事感叹有作' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和李觏《送春绝句二首寄呈龙学》 其一', '祖无择', '宋代', '忆昔相逢甲午年，与君同赋送春篇。等闲又见春风老，更捧新吟一惘然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和李觏《送春绝句二首寄呈龙学》 其一' AND p.poem_author = '祖无择';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居二首 其一', '元好问', '金朝', '斜阳高树挂晴虹，肃肃微凉雨气中。一道鹭鸶花不断，密香吹满马头风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居二首 其一' AND p.poem_author = '元好问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜坐', '陆游', '宋代', '老知世事谩纷纷，纸帐蒲团自策勋。\n一夜北风吹裂屋，石楼无耳不曾闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜坐' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢仲川雪中见过时予未起', '谢榛', '明代', '高枕奚童报，知君冒雪来。阴晴门外变，骚雅卧中裁。\n\n寒色侵衣湿，冰花著树开。于今谁有赋，方见谢家才。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢仲川雪中见过时予未起' AND p.poem_author = '谢榛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·明尼亚波利斯城秋感', '刘永平', '近代', '短袖纱衫别玉京。机场郁热气蒸腾。频添冷饮杯中满，自有凉风膝下生。\n\n航万里，莅双城。山花朵朵露华凝。小楼逭暑迎新月，盛夏时光秋意浓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·明尼亚波利斯城秋感' AND p.poem_author = '刘永平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中书耶律公挽词', '曹之谦', '元代', '虎啸龙兴际，乘时自有人。风云开惨淡，天地入经纶。\n\n忽报台星坼，仍传薤露新。斯民感无极，洒泪叫苍旻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中书耶律公挽词' AND p.poem_author = '曹之谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秦州杂诗二十首 其三', '杜甫', '唐代', '州图领同谷，驿道出流沙。降虏兼千帐，居人有万家。\n\n马骄珠汗落，胡舞白蹄斜。年少临洮子，西来亦自誇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秦州杂诗二十首 其三' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江行杂诗七首 其一', '李梦阳', '明代', '十八滩都尽，舟人惯不劳。可言滩石险，难测是平涛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江行杂诗七首 其一' AND p.poem_author = '李梦阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元旦 其六', '李孙宸', '明代', '近得封章报，能容恋五湖。久归人事变，多病主恩孤。\n\n春似还家客，年同过隙驹。总无欢赏事，惟有醉模糊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元旦 其六' AND p.poem_author = '李孙宸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠杨云时望', '陆深', '明代', '扬雄与世渐无缘，谁作侯芭守太玄。今上好文先帝武，白头空自感流年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠杨云时望' AND p.poem_author = '陆深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秦淮竹枝词 其一', '杜绍凯', '清代', '垂柳庄前夕照寒，早潮落尽暮潮宽。春宫小说红毡上，侬爱钟山雨后看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秦淮竹枝词 其一' AND p.poem_author = '杜绍凯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登慈恩绝顶有感', '许月卿', '宋代', '为学平生不究源，未妨绝顶上慈恩。\n塔高俯视群山小，江阔能容巨浪喧。\n人每中登难脚力，谁於高处领天根。\n须信平生为基址，基址牢时德业尊', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登慈恩绝顶有感' AND p.poem_author = '许月卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春晓太平公主小楼闻吟双管', '沈佺期', '唐代', '主家天上凤楼人，传得仙音到客新。未省落梅和折柳，风吹散作万家春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春晓太平公主小楼闻吟双管' AND p.poem_author = '沈佺期';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽京口使君丰郎中十首', '刘宰', '宋代', '妙年意气已横秋，不为身谋为国谋。\n斥去佞臣谈笑里，英名高压汉朱存。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽京口使君丰郎中十首' AND p.poem_author = '刘宰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('滕王阁三首 其二', '吴芾', '宋代', '高阁秋登第一回，顿令心目豁然开。山腾翠霭浮空去，水引清风入座来。\n\n九夏炎光今已矣，一时佳兴更悠哉。和君妙句如冰雪，想见胸中绝点埃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '滕王阁三首 其二' AND p.poem_author = '吴芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题八景 其二 古寺寒泉', '张天赋', '明代', '兜率浑閒事，天然显地灵。一泓冰解冻，千古圣同清。\n\n磨墨题新句，辞官濯旧缨。我曾三载读，对此学惺惺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题八景 其二 古寺寒泉' AND p.poem_author = '张天赋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏无核红柿', '孔平仲', '宋代', '林中有丹果，压枝一何稠。为柿已软美，嗟尔骨亦柔。\n\n风霜变颜色，雨露加膏油。大哉造化心，于尔何绸缪。\n\n荆筐载趋市，价贱良易求。剖心无所有，入口颇相投。\n\n为栗外屈强，老者所不收。为枣中亦刚，饲儿戟其喉。\n\n众言咀嚼快，惟尔无所忧。排罗置前列，圆熟当高秋。\n\n且以悦一时，长久岂暇谋。咄哉溃烂速，弃掷将谁尤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏无核红柿' AND p.poem_author = '孔平仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鼾睡 其一', '王夫之', '明代', '拂拭南窗小榻空，绿阴鏬里纸光红。昨朝狼籍今朝在，花自轻飞柳自浓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鼾睡 其一' AND p.poem_author = '王夫之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂六十七首 其十二', '释原妙', '宋代', '师子窟，师子吼。师子儿，无前后。蓦然直下翻身，便解人前开口。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂六十七首 其十二' AND p.poem_author = '释原妙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('月底修箫谱二首 其二', '史承谦', '清代', '趁新晴，闲命屐，偶把竹扉叩。满目荒凉，蟏网蔽虚牖。\n\n可怜琴几无存，画屏空掩，谁复更、招呼携酒。\n\n步苔甃。一任树古池平，苍鼠避人走。班驳屈梅，几点冷香逗。\n\n应须九九寒消，三三径暖，怕还有、花枝红透。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '月底修箫谱二首 其二' AND p.poem_author = '史承谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄思老宅集社分得丝字', '孙继皋', '明代', '春城社散已经时，夏日寻盟对雨宜。似洒山阳思旧泪，未知河朔纳凉期。\n\n层阴欲堕侵单袷，重午才过恋五丝。光景易流人易老，相逢沉饮不须辞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄思老宅集社分得丝字' AND p.poem_author = '孙继皋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居杂咏五首 其一', '李锴', '清代', '双坞人烟外，萧萧松雪翻。老农今日事，古色数家村。\n\n鹅鸭通前浦，豺狼到小园。何须不来往，邻里数相存。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居杂咏五首 其一' AND p.poem_author = '李锴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵通明叟晚春二十七首 其十', '释德洪', '宋代', '桃李无言暗浅深，晓云惭愧不成霖。化工胜却耶溪女，绣遍园林不犯针。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵通明叟晚春二十七首 其十' AND p.poem_author = '释德洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和杨公济钱塘西湖百题 其九十六 南屏山', '郭祥正', '宋代', '真山返如假，叠径入云屏。不借湖光洗，朝朝泼黛青。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和杨公济钱塘西湖百题 其九十六 南屏山' AND p.poem_author = '郭祥正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春 追次文丞相，题张巡许远两忠臣庙', '沈禧', '元代', '临死不惧，临危不惊，何碍何妨。纵刀锯在前，鼎锅居后，当斯之际，观作寻常。天汉桥头，睢阳城上，两处成名一样香。精忠操，何堪与比，出冶坚钢。江山几见兴亡。□野草平原总战场。慨区区忍死，偷生恃宠，欺孤虐寡，敢并遗芳。庙食从今，纲常不弛，功烈何如郭汾阳。千秋下，论二公节义，天地难量。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春 追次文丞相，题张巡许远两忠臣庙' AND p.poem_author = '沈禧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江上', '冯去非', '宋代', '清秋不可奈，先自懒登楼。\n一雁叫寒水，数峰生远愁。\n乾坤消剑气，江海笑诗流。\n不解人间事，眠鸥尽自由。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江上' AND p.poem_author = '冯去非';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吕氏心文友园亭杂咏十二首 其十二 山矾障', '黎民表', '明代', '芳心自凌乱，翠带常绾结。日暮望佳人，璚蕤不堪折。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吕氏心文友园亭杂咏十二首 其十二 山矾障' AND p.poem_author = '黎民表';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陪夏广文先生饮夜归偶成', '郑潜', '明代', '梅所一尊酒，归来池馆幽。含风凉饮雪，对月醉梳头。\n\n爽入枯肠润，光分白发秋。明朝追往事，还忆在杭州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陪夏广文先生饮夜归偶成' AND p.poem_author = '郑潜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别友人', '长孙佐辅', '唐代', '愁多不忍醒时别，想极还寻静处行。 \n 谁遣同衾又分手，不如行路本无情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别友人' AND p.poem_author = '长孙佐辅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上翁岭', '曾巩', '宋代', '放车秋崖望，所得过旧闻。\n初疑古轴画，山水秋毫分。\n时见崖下雨，多从衣上云。\n濯足行尚侧，心忧踏天文。\n八荒正摇落，独余草木薰。\n但觉耳目胜，未知筋力勤。\n颠毛已种种，世患方纷纷。\n何当啸吟此，日与樵苏群。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上翁岭' AND p.poem_author = '曾巩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题松阳项氏瑞芝诗卷', '陈镒', '元代', '和气致祥瑞，在草惟灵芝。造化之所钟，人力讵可为。\n\n松阳有隐者，结庐马湖湄。德润日已广，枯朽生神奇。\n\n三秀同英华，五色耀陆离。眷兹生意深，见者但嗟咨。\n\n惟昔商颜翁，采之以疗饥。宜尔孙与子，食德无休期。\n\n松山翠绵邈，松水清逶迤。流芳暨千载，永言著声诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题松阳项氏瑞芝诗卷' AND p.poem_author = '陈镒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('麻姑山诗', '吕南公', '宋代', '腾腾六尺碣，标置羽客坟。龟螭尚坚完，字画稍破分。\n\n道士惜故物，编扶使长存。前已三百年，后当几何春。\n\n昔诵八哀咏，颇推李邕文。披襟喜此逢，再读目愈昏。\n\n道固难洞达，辞犹不雄浑。岂殊沸鸣蛙，见谓鼓吹繁。\n\n惜哉开元盛，乃乏史笔人。复疑少陵翁，赏识或失真。\n\n凡例竟何有，占招仅成言。当时干谒儿，误听一走门。\n\n富贵世所擅，文章我知论。忼慨韩柳思，不返撰述魂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '麻姑山诗' AND p.poem_author = '吕南公';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题钱舜举凌波仙子图', '刘崧', '明代', '若有人兮美而鬈，冠切云兮衣翩翾。粲然独立青山前，褰裳流盼凝娟娟。\n\n乘云而行兮从风而旋，态庄色正合自然。矫如翔鸾凌紫烟，朗如明月行青天。\n\n山之石兮骈阗，山之松兮连蜷。下有瑶草纷交连，素华绿叶何芊芊。\n\n不言不笑意已宣，风骨乃是凌波仙。金华老人惜㛹嬛，友于联属成三妍。\n\n其来无方往无边，世人不见将千年。谁其画者钱塘钱，我歌欲继湘江篇。\n\n张君好古宜宝旃，此画此歌毋浪传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题钱舜举凌波仙子图' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题束季博山园二十首 其十二 石桥', '牟巘', '宋代', '神仙好狡狯，空飞万里行。石桥小如许，铁杖响彭铿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题束季博山园二十首 其十二 石桥' AND p.poem_author = '牟巘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和韦开州盛山十二首 茶岭', '张籍', '唐代', '紫芽连白蕊，初向岭头生。自看家人摘，寻常触露行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和韦开州盛山十二首 茶岭' AND p.poem_author = '张籍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游石仙分韵得观字', '吴汝弌', '宋代', '闲拢两袖秋，步入冲寂观。\n古树老云中，仙成毁岩半。\n是时零雨高，叶脱凄风乱。\n怪禽走何忙。涩不流不漫。\n那知张郎仙，谲幻敢悬断。\n雷书贮红崖，愚下浪传赞。\n符碑傥长灵，鬼物岂歌唤。\n尚云剑埋山，安得急推断。\n冷肥亦张徒，精气不知散。\n死坐豫樟空。凿窍竞窥看。\n何不葬山原，不然弃江沜。\n乌鸢与蝼蚁，岂食吾一贯。\n独流天地间，万古亘光灿。\n神仙固渺茫，此事良可惋，\n忍哉偷儿狂，更捣泥腹烂。\n我来拟少休，亭压不敢玩。\n黄冠四三人，拙野只俗窜。\n延坐无好言，令我信凉馆。\n饭余且纵观，逸兴薄霄汉。\n琴鸣着高弹，弈胜出奇算。\n歗咏壶隐楼。抚事发长叹。\n大书同人名，聊欲记游玩。\n阴霾{左氵右念}轻寒，日色倏昏晏。\n倩人买村醪，煮芋叠肴桉。\n清坐二更深，一睡各鼻鼾。\n晓来登岩头，棘路解羁绊。\n划开天盖宽，远景过飞翰。\n幽藂摘新查，窥险身发汗。\n居然束归装，重下四岩畔。\n我思古之人，岂只局穷闬。\n观海登泰山，深高世间冠。\n斯岩虽荒榛，乐事实昭焕。\n人心本然同，今古未容判。\n终当驾云风，高蹈无畔岸。\n作诗示儿童，兹游吾岂但。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游石仙分韵得观字' AND p.poem_author = '吴汝弌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题邹忠公墓', '陈肃', '元代', '凤凰戾朝阳，和鸣太平瑞。百鸟从喧啾，葳蕤赤霄逝。\n\n昔者邹忠公，天质蕴纯粹。苕华玉树春，秀映层城丽。\n\n融贯河南学，会要慎独际。出身职俎豆，淮颍风流思。\n\n臧否谥法解，謇谔补衮议。君王正年少，恩爱竞陈卫。\n\n长门生秋草，寂寞金屋闭。时闻昭阳间，车音杂歌吹。\n\n朝方降鸿册，暮已奏封事。宛转陈正始，社稷宗庙计。\n\n权臣肆谗毒，抵罪窜荒裔。芦箫送铜鼓，笑语见魑魅。\n\n秦陵嘶石马，明堂更宝位。徘徊趋魏阙，感激俯宸陛。\n\n至尊重叹奖，再俾司献替。简严起居作，弘雅丝纶制。\n\n戎曹羽书静，铨部瑰材萃。嵯峨蓬莱阁，日月近清秘。\n\n一麾出江左，慷慨怀古意。长啸新亭赏，爽挹龙虎气。\n\n菱香藕花净，画舫西湖舣。遂为禹穴游，复上越台憩。\n\n安知向焚稿，兹乃致奸伪。湘流湛凝碧，衡岳郁积翠。\n\n岂无酃酒美，忧国不成醉。南过苍梧野，陈祠有虞帝。\n\n回首九疑云，潸然为悲涕。及承内迁命，沉痾困炎疠。\n\n首丘竟落落，褒赠中兴惠。唯馀孤坟在，岁久尽颓废。\n\n黄棘何榛榛，白杨亦翳翳。卓哉谢君子，衰俗振高谊。\n\n言诸两郡守，率众共营置。周垣龟甲齐，修表螭头伟。\n\n银榜倒薤题，琰刻逸藻记。庶几永终古，凯式于后世。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题邹忠公墓' AND p.poem_author = '陈肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长安春兴 其四', '李良柱', '明代', '十年通藉侍神尧，汉署怀香几赐貂。银鹘不传清朔漠，金泥屡出宠嫖姚。\n\n御沟流水销残冻，禁柳迁莺啭弱条。正说大官初尚膳，忽闻仙乐下云霄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长安春兴 其四' AND p.poem_author = '李良柱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄容贯圭峰 其一', '陈献章', '明代', '西风扶策上，病骨快新凉。乞米分僧饭，闻香过梵堂。\n\n闭门秋竹静，语鸟暮钟藏。浩浩蒲团上，还同在醉乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄容贯圭峰 其一' AND p.poem_author = '陈献章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀从弟', '吕本中', '宋代', '折柳长亭今几年，一行作吏楚江边。音书顿逐归鸿断，消息时因过客传。\n\n五岭风温吹瘴雨，九疑云湿卷愁烟。每吟春草池塘句，尚想诗成梦惠连。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀从弟' AND p.poem_author = '吕本中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月', '苏琼', '宋代', '韩愈文章盖世，谢安情性风流。良辰美景在西楼。敢劝一卮芳酒。 \n 记得南宫高第，弟兄争占鳌头。金炉玉殿瑞烟浮。高占甲科第九。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月' AND p.poem_author = '苏琼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九月一日清溪道中', '曹文晦', '元代', '老树依沙岸，柴门上下邻。\n断桥归郭路，细雨过溪人。\n白鹭双飞去，黄花数点新。\n惜无遗世友，联句坐苔茵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九月一日清溪道中' AND p.poem_author = '曹文晦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七夕后一夜月中露坐二首 其二', '杨万里', '宋代', '今古诗人爱月圆，未堪商略玉婵娟。脩眉半璧各自好，团镜磨镰俱可怜。\n\n一夜一般新样出，几回几换为人妍。教渠也学金鸦扇，未必清光直一钱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七夕后一夜月中露坐二首 其二' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二月二日宴中贻同年封先辈渭', '黄滔', '唐代', '帝尧城里日衔杯，每倚嵇康到玉颓。桂苑五更听榜后， \n 蓬山二月看花开。垂名入甲成龙去，列姓如丁作鹤来。 \n 同戴大恩何处报，永言交道契陈雷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二月二日宴中贻同年封先辈渭' AND p.poem_author = '黄滔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('司徒俞公挽歌 其二', '黎民表', '明代', '台中俄解印，海上托求仙。枢筦逢明主，金貂起暮年。\n\n途长孤剑在，恩重一身捐。不藉麒麟画，千秋月旦传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '司徒俞公挽歌 其二' AND p.poem_author = '黎民表';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵朱通判寄示盘龙山观瀑诗', '项安世', '宋代', '百尺山头下玉龙，吾人到此得参同。\n河来积石崑崙顶，日出蓬莱碧海东。\n直自阴阳随处有，强分泉火本来空。\n君看击石还呵砚，燥湿先生一性中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵朱通判寄示盘龙山观瀑诗' AND p.poem_author = '项安世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('花狮', '洪咨夔', '宋代', '雪氄吾家虥，知亲翰墨妍。渴来趋研饮，饱去枕书眠。\n\n弄影窥清镜，收声听素弦。最能持大体，鼠辈任便儇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '花狮' AND p.poem_author = '洪咨夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('呈邢叔三首 其二', '赵蕃', '宋代', '浏浏晴檐响，愔愔兰斛香。时于簿书暇，乐是话言长。\n\n政可昼连夕，兴怀参与商。平生事贤志，烱烱未尝忘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '呈邢叔三首 其二' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('余北征行囊萧然读老杜万里须十金妻孥未相保之句限韵成十绝聊以破愁耳 其四', '邓云霄', '明代', '锦瑟待佳人，冰弦弹五十。但作相思声，不作穷途泣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '余北征行囊萧然读老杜万里须十金妻孥未相保之句限韵成十绝聊以破愁耳 其四' AND p.poem_author = '邓云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宣政同知燕京闾报国哀时文皇晏驾 其二', '萨都剌', '元代', '天柱倾，天不晴，白髯使者东南行。东南山水失颜色，一夕秋风来上京。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宣政同知燕京闾报国哀时文皇晏驾 其二' AND p.poem_author = '萨都剌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岁暮怀人诗 其六', '黄遵宪', '清代', '要使天骄识凤麟，传闻星使出词臣。毡裘大长惊相问，李揆中朝第一人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岁暮怀人诗 其六' AND p.poem_author = '黄遵宪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆仙姿（九之二）', '贺铸', '宋代', '日日春风楼上。不见石城双桨。鸳枕梦回时，烛泪屏山相向。流荡。流荡。门外白苹溪涨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆仙姿（九之二）' AND p.poem_author = '贺铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('龙井山主送蜡梅', '张镃', '宋代', '凤落松钗满磵桥，野蜂移蜜上枯条。\n道人参得山中语，不是涂黄一样娇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '龙井山主送蜡梅' AND p.poem_author = '张镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('【仙吕】翠裙腰_闺怨晓来雨', '关汉卿', '元代', '闺怨\n\n晓来雨过山横秀，野水涨汀洲。阑干倚遍空回首。下危楼，一天风物暮伤秋。\n\n【六幺遍】乍凉时候，西风透。碧梧脱叶，余暑才收。香生凤口，帘垂玉钩，小院深闲清昼。清幽，听声声蝉噪柳梢头。\n\n【寄生草】为甚忧，为甚愁？为萧郎一去经今久。玉台宝鉴生尘垢，绿窗冷落闲针锈。岂知人玉腕钏儿松，岂知人两叶眉儿皱！\n\n【上京马】他何处，共谁人携手，小阁银瓶殢歌酒。早忘了咒，不记得，低低耨。\n\n【后庭花煞】掩袖暗含羞，开樽越酿愁。闷把苔墙画，慵将锦字修。最风流，真真恩爱，等闲分付等闲休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '【仙吕】翠裙腰_闺怨晓来雨' AND p.poem_author = '关汉卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('恒阳饯乔白岩二首 其二', '刘麟', '明代', '雨昏书剑对秋看，衢路冥冥生昼寒。时羡叔孙终制礼，人荣疏傅早辞官。\n\n交深不谓离群易，才大惟忧用世难。一笑浮图高处别，此中犹可望长安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '恒阳饯乔白岩二首 其二' AND p.poem_author = '刘麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('即事 其三', '虞俦', '宋代', '归来世事任浮沉，车马萧条门巷深。一榻容身无妄想，两餐度日少关心。\n\n园收佳实随时荐，瓮有新篘待月斟。老觉閒居浑有味，不须荣宦说骎骎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '即事 其三' AND p.poem_author = '虞俦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赵云石赠诗，即步原韵二首 其二', '许南英', '清代', '竹溪溪傍旧诗坛，十八年来指一弹。末路谨防随俗转，浮生尚悔了人难。\n\n令威化鹤寻华表，子美闻鹃拜石阑。垂老重游桑梓地，未妨惆怅强为欢！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赵云石赠诗，即步原韵二首 其二' AND p.poem_author = '许南英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日宴江山楼', '曹伯启', '元代', '浙江东注接天隅，吴越青山入画图。平日胜游今日最，世间烦暑此间无。\n\n万家楼阁苍烟覆，几处园陵白草枯。痛饮狂歌有真趣，主人休惜酒钱粗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日宴江山楼' AND p.poem_author = '曹伯启';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三笋吟', '陈旅', '元代', '蜀妓椎茧如截肪，鲛工夜织青犀裳。翰林待诏擅花竹，砚屏春透宫云香。\n\n镵根蔫鲜玉生汗，南风入林翠胎绽。牙根冤血点点红，三凤声沉九秋晏。\n\n太官金锜陈淳熬，看图未必菹尔曹。馋夫煮箦政未熟，见此豪夺君其韬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三笋吟' AND p.poem_author = '陈旅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同黄参军登巾子山二首 其二', '顾璘', '明代', '一上高亭野兴幽，坐凭松顶瞰江流。海中楼阁三山霁，天畔风烟六月秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同黄参军登巾子山二首 其二' AND p.poem_author = '顾璘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登凤凰台二首', '萨都剌', '元代', '凤凰台上望长安，五色宫袍照水寒。綵笔十年留翰墨，银河一夜卧阑干。\n\n三山飞鸟江天暮，六代离宫草树残。始信人生如一梦，壮怀莫使酒杯乾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登凤凰台二首' AND p.poem_author = '萨都剌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('人爱九日多以靖节之故仆以邠老七字为可以益其爱者且连日不雨即风尤觉此句妙处赋诗八韵', '赵蕃', '宋代', '东篱满把菊，柯山一句诗。四时皆有节，九日独如斯。\n\n潘子夙所尚，陶翁何敢师。是故逢此日，爱慕仍凄悲。\n\n所愿学渊明，归去了不疑。松菊傥犹存，田园随事为。\n\n亦愿如邠老，白首丘壑期。人穷与诗长，得失其在兹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '人爱九日多以靖节之故仆以邠老七字为可以益其爱者且连日不雨即风尤觉此句妙处赋诗八韵' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('池上居 其二', '弘历', '清代', '乍见锦绷包，旋听绿玉敲。有堂如白傅，不雨度西郊。\n\n啭树莺求友，衔莎雀补巢。一泓相对处，无虑置杯胶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '池上居 其二' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('利', '方翥', '宋代', '江上柴门照夕阳，牧童蓑笠下牛羊。\n明朝依旧山前路，溪北溪南花草香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '利' AND p.poem_author = '方翥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢惠红桃二首', '张明中', '宋代', '报我勤渠有木桃，肤腴密洒茜花膏。\n枯肠消得三十颗，只恐儿曹赋老饕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢惠红桃二首' AND p.poem_author = '张明中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王敏节欢喜帖赞', '岳珂', '宋代', '秦火燎原，衣冠涂炭。\n绕指之柔，出乎百锻。\n如公之刚，犹死忧患。\n时欤命欤，一览三叹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王敏节欢喜帖赞' AND p.poem_author = '岳珂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('保塞教授同年丁仲勤广寄示和少逸十诗某辄寄之更不理彭意无复次第 其四', '王安中', '宋代', '旧闻千岁辽东鹤，塞上翩翩忽见过。我有云间化凫舄，追随不用着人多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '保塞教授同年丁仲勤广寄示和少逸十诗某辄寄之更不理彭意无复次第 其四' AND p.poem_author = '王安中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过大冶县', '郑刚中', '宋代', '吏民俱因市廛小，鸥雁相呼湖海宽。\n蕃息谁能力耕鉴，弦歌依旧好为官。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过大冶县' AND p.poem_author = '郑刚中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('原韵酬传君洁秋端阳见寄', '刘家传', '近代', '此身安处便为家，不近浮名免世哗。结习已空三宿恋，新诗犹有故人誇。\n\n经霜渐变星星发，绕膝优生朵朵花。更爱江山归一统，灵均何用赋怀沙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '原韵酬传君洁秋端阳见寄' AND p.poem_author = '刘家传';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('顺老寄菜花乾戏作长句', '韩驹', '宋代', '道人禅馀自锄菜，小摘黄花日中晒。峨嵋㮕脯久不来，曲糁姜丝典型在。\n\n封题寄我纸作囊，中有巴蜀斋厨香。起炊晓甑八月白，配此春盘一掬黄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '顺老寄菜花乾戏作长句' AND p.poem_author = '韩驹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感兴临蕃驯雁', '佚名', '唐代', '感兹驯雁色苍苍，徘徊顾步貌昂昂。不见衔芦避缯缴，空闻落翮困堤塘。\n\n差池为失衡阳伴，邂逅飘零虏塞傍。引颈长鸣望云路，何时刷羽接归行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感兴临蕃驯雁' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('己亥杂诗 其一七七', '龚自珍', '清代', '藏书藏帖两高人，目录流传四十年。师友凋徂心力倦，羽陵一记亦荆榛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '己亥杂诗 其一七七' AND p.poem_author = '龚自珍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('问龚深之疾往复 其二', '彭汝砺', '宋代', '居士如泡如焰身，目前应接亦非神。枝辞自已知吾拙，饱学谁能笑子贫。\n\n午饮频来同鲙鲤，朝齑漫说欲羹莼。黄昏急雨秋风湿，想见青灯一幅巾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '问龚深之疾往复 其二' AND p.poem_author = '彭汝砺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('邸中种竹十二首 其十二', '何吾驺', '明代', '长羡空空如，虚空生冷籁。扫尽万顷烟，盈盈不下带。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '邸中种竹十二首 其十二' AND p.poem_author = '何吾驺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('听琵琶妓弹略略', '白居易', '唐代', '腕软拨头轻，新教略略成。四弦千遍语，一曲万重情。 \n 法向师边得，能从意上生。莫欺江外手，别是一家声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '听琵琶妓弹略略' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('易十六淑南许为我作萝村图诗以识之', '李锴', '清代', '淑南许作萝村图，满纸为我扫古翠。秋林护石溪入云，一尺一寸期有味。\n\n凿空构虚固以变，不妨古拙兼狂肆。沈冥黯淡妙入神，逼迫山鬼幽阴至。\n\n用通大钧造物理，飞笔走墨臣行意。我有青藤杖，尝之山之垂。\n\n我有乌角巾，尝临水之湄。盘阴傥遇息阴者，此卷卢胡笑所为。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '易十六淑南许为我作萝村图诗以识之' AND p.poem_author = '李锴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋村', '艾性夫', '宋代', '稻黄雁入蔗境，水落鹭过屠门。\n一片寒烟晚景，数声牧笛秋村。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋村' AND p.poem_author = '艾性夫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('约得梅花一处开七绝辘轳 其三', '崔荣江', '当代', '半世磨砻不自哀，岂循走马醉章台。眼横梁苑红皆俗，约得梅花一处开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '约得梅花一处开七绝辘轳 其三' AND p.poem_author = '崔荣江';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送珣禅还乡', '释昙华', '宋代', '极目澄澄水照空，白苹红蓼战西风。\n三千里外深深意，铁券谁将累祖翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送珣禅还乡' AND p.poem_author = '释昙华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄龙溪老人乞西岩香', '耶律楚材', '元代', '寄语龙溪老古锥，西岩风韵我长思。香钱缓发鸣琴后，瓦鼎浓薰入定时。\n\n比拟梅魂祗独步，品量龙脑可同驰。湛然鼻孔撩天大，穿过多时不自知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄龙溪老人乞西岩香' AND p.poem_author = '耶律楚材';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贪泉', '古成之', '宋代', '贤良知足辱，为尔戎贪名。\n一酌不能惑，千年依旧清。\n深涵秋汉色，冷浸古松声。\n珍重荒碑在，何人曾泪倾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贪泉' AND p.poem_author = '古成之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚春寄友人二首 其一', '唐庚', '宋代', '眼底春愁恼杀侬，扬州往事旋成空。风流只合称狂客，衰飒何堪作病翁。\n\n水国春深梅子雨，江天日暮鲤鱼风。何时执手同樽酒，收拾清欢笑语中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚春寄友人二首 其一' AND p.poem_author = '唐庚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送中', '洪迈', '宋代', '骄阳久自杀，一雨荡龟坼。\n田夫梦亦好，翻陇已幽咽。\n朝来喜相语，一饱心已决。\n翻翻风叶乱，嫋嫋露芒出。\n去年禾欲秀，积潦满秋泽。\n今年岂堪旱，束手就沟壑。\n我生拙谋口，藜藿甘如蜜。\n向来真过计，忧民岂吾职。\n赤子天可怜，嗟人独何力。\n何须事儿戏，合沓来贺客。\n稍欣新稻熟，社酒行可觅。\n当同扶路翁，醉归舞南陌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送中' AND p.poem_author = '洪迈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('瓶中花', '赵完璧', '明代', '清秋红翠浸冰壶，浪遣人誇绝世无。壮志肯教摧寸草，长松古柏拟身图。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瓶中花' AND p.poem_author = '赵完璧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('参观海丰红宫二首 其二', '胡绳', '当代', '农运风开第一声，红旗漫卷海丰城。蚍蜉撼树谈何易，彭湃千秋不朽名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '参观海丰红宫二首 其二' AND p.poem_author = '胡绳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂剧·关大王独赴单刀会', '关汉卿', '元代', '第一折\n\n（冲末鲁肃上，云）三尺龙泉万卷书，皇天生我意何如？山东宰相山西将，彼丈夫兮我丈夫。小官姓鲁，名肃，字子敬。见在吴王麾下为中大夫之职。想当日俺主公孙仲谋占了江东，魏王曹操占了中原，蜀王刘备占了西川。有我荆州，乃四冲用武之地，保守无虞，分天下为鼎足之形。想当日周瑜死于江陵，小官为保，劝主公以荆州借与刘备，共拒曹操。主公又以妹妻刘备。不料此人外亲内疏，挟诈而取益州，遂并汉中，有霸业兴隆之志。我今欲索取荆州，料关公在那里镇守，必不肯还我。今差守将黄文，先设下三计，启过主公，说：关公韬略过人，有兼并之心，且居国之上游，不如索取荆州。今据长江形势，第一计：趁今日孙、刘结亲，已为唇齿，就江下排宴设乐，修一书以贺近退曹兵，玄德称主于汉中，赞其功美，邀请关公江下赴会为庆，此人必无所疑；若渡江赴宴，就于饮酒席中间，以礼索取荆州。如还，此为万全之计；倘若不还，第二计：将江上应有战船，尽行拘收，不放关公渡江回去。淹留日久。自知中计，默然有悔，诚心献还；更不与呵，第三计：壁衣内暗藏甲士！酒酣之际，击金钟为号，伏兵尽举，擒住关公，囚于江下。此人是刘备股肱之臣，若将荆州复还江东，则放关公还益州；如其不然，主将既失，孤兵必乱，乘势大举，觑荆州一鼓而下，有何难哉！虽则三计已定，先交黄文请的乔公来商议则个。（正未乔公上，云）老夫乔公是也。想三分鼎足已定：曹操占了中原；孙仲谋占了江东；刘玄德占了西蜀。想玄德未济时，曾问俺东吴家借荆州为本，至今未还。鲁子敬常有索取之心，沉疑未发；今日令人来请老夫，不知有甚事，须索走一遭去。我想汉家天下，谁想变乱到此也呵！（唱）\n\n【仙吕】【点绛唇】俺本是汉国臣僚。汉皇软弱；兴心闹，惹起那五处兵刀，并董卓，诛袁绍。\n\n【混江龙】止留下孙、刘、曹操，平分一国作三朝。不付能河清海晏，雨顺风调；兵器改为农器用，征旗不动酒旗摇；军罢战，马添膘；杀气散，阵云消；为将帅，作臣僚；脱金甲，着罗袍；则他这帐前旗卷虎潜竿，腰间剑插龙归鞘。人强马壮，将老兵骄。（云）可早来到也。左右报复去，道乔公来了也。（卒子报云）报的大夫得知：有乔公来到了也。（鲁云）道有请。（卒云）老相公，有请！（末见鲁，云）大夫，今日请老夫来，有何事干？（鲁云）今日请老相公，别无甚事，商量索取荆州之事。（末云）这荆州断然不可取！想关云长好生勇猛，你索荆州呵，他弟兄怎肯和你甘罢？（鲁云）他弟兄虽多，兵微将寡。（末唱）\n\n【油葫芦】你道"他弟兄虽多兵将少"，（云）大夫、你知博望烧屯那一事么？（鲁云）小官不知，老相公试说则。(末唱)赤紧的将夏侯惇先困了。（云）这隔江斗智你知么？（鲁云）隔江斗智，小官知便知道，不得详细，老相公试说则。（末唱）则他那周瑜、蒋干是布衣交，那一个股肱臣诸葛施韬略，亏杀那苦肉计黄盖添粮草。(云)赤壁鏖兵，那场好厮杀也！（鲁云）小官知道。老相公再说一遍者。（末云）烧折弓驽如残苇，燎尽旗幡似乱柴。半明半暗花腔鼓，横着扑着伏兽牌。带鞍带辔烧死马，有袍有铠死尸骸。哀哉百万曹军败，个个难逃水火灾！（唱）那军多半向火内烧，三停在水上漂。若不是天交有道伐无道，这其间吴国尽属曹。\n\n（鲁云）曹操英雄智略高，削平僭窃篡刘朝。永安宫里擒刘备，铜雀春深锁二乔。（唱）\n\n【天下乐】你道是"铜雀春深锁二乔"，这三朝、恰定交，不争咱一日错便是一世错……（鲁云）俺这里有雄兵百万，战将千员，量他到的那里！（末唱）你则待要行霸道，你待要起战讨。（鲁云）我料关云长年迈，虽勇无能。（末唱）你休欺负关云长年纪老。\n\n（云）收西川一事，我说与你听。（鲁云）收西川一事，我不得知。你试说一遍。（末唱）\n\n【那吒令】收西川白帝城，将周瑜来送了。汉江边张翼德，将尸骸来当着。船头上鲁大夫，几乎间唬倒。你待将荆州地面来争，关云长听的闹，他可便乱下风雹。\n\n（鲁云）他便有甚本事？（末唱）\n\n【鹊踏枝】他诛文丑逞粗躁，刺颜良显英豪。他去那百万军中，他将那首级轻枭。（鲁云）想赤壁之战，我与刘备有恩来。（末唱）那时间相看的是好，他可便喜孜孜笑里藏刀。\n\n（鲁云）他若与我荆州，万事罢论；若不与荆州呵，我将他一鼓而下。（末云）不争你举兵呵，（唱）\n\n【寄生草】幸然是天无祸，是咱这人自招。全不肯施恩布德行王道，怎比那多谋足智雄曹操？你须知南阳诸葛应难料！（鲁云）他若不与呵，我大势军马，好歹夺了荆州。（末唱）你则待千军万马恶相持，全不想生灵百万遭残暴！\n\n（鲁云）小官不曾与此人相会；老相公，你细说关公威猛如何？（末云）想关云长但上阵处，凭着他坐下马、手中刀、鞍上将，有万夫不当之勇。（唱）\n\n【金盏儿】他上阵处赤力力三绺美髯飘，雄赳赳一丈虎躯摇，恰便似六了神簇捧定一个活神道。那敌军若是见了，唬的他七魄散、五魂消。（云）你若和他厮杀呵。（唱）你则索多披上几副甲，剩穿上几层袍。便有百万军，挡不住他不刺刺千里追风骑；你便有千员将，闪不过明明偃月三停刀。\n\n（鲁云）老相公不知，我有三条妙计索取荆州。（末云）是那三条妙计？（鲁云）第一计：趁今日孙、刘结亲，以为唇齿，就于江下排宴设乐，作书一封，以贺近退曹兵，玄德称主于汉中，赞其功美，邀请关公江下赴会为庆，此人必无所疑；若渡江赴宴，就于饮酒中间，以礼索取荆州。如还，此为万全之计；如不还，第二计：将江上应有战船，尽行拘收，不放关公回还。淹留日久，自知中计，默然有悔，诚心献还；更不与呵，第三条计：壁衣内暗藏甲士，酒酣之际，击金钟为号，伏兵尽举，擒住关公，囚于江下。此人乃是刘备股肱之臣，若将荆州复还江东，则放关公归益州；如其不然，主将既失，孤兵必乱，领兵大举，乘机而行，觑荆州一鼓而下，有何难哉！这三条计决难逃。（末云）休道是三条计，就是千条计，亦近不的他。（唱）\n\n【金盏儿】你道是"三条计决难逃"；一句话不相饶，使不的武官粗懆文官狡。（鲁云）关公酒性如何？（末唱）那汉酒中劣性显英豪，圪塔的揪住宝带，没揣的举起钢刀。(鲁云）我把岸边战船拘了。（末唱）你道是岸边厢拘了战船，（云）他若要回去呵，（唱）你则索水面上搭座浮桥！\n\n（鲁云）老相公不必转转议论，小官自有妙策神机。乘此机会，荆州不可不取也。（末云）大夫，你这三条计，比当日曹公在灞陵桥上三条计如何？到了出不的关云长之手。（鲁云）小官不知。老相公试说一遍我听咱。（末唱）\n\n【尾声】曹丞相将送路酒手中擎，饯行礼盘中托，没乱煞侄儿和嫂嫂。曹孟德心多能做小，关云长善与人交。早来到灞陵桥，险唬杀许褚、张辽；他勒着追风骑，轻轮动偃月刀。曹操有千般计较，则落的一场谈笑。（云）关云长道："丞相勿罪！某不下马了也。"（唱）他把那刀尖儿斜挑锦征袍。（下）（鲁云）黄文，你见乔公说关公如此威风，未可深信。俺这江下，有一贤士，复姓司马，名徽，字德操。此人与关公有一面之交，就请司马先生为伴客，就问关公平昔智勇谋略，酒中德性如何。黄文，就跟着我去司马庵中相访一遭去。（下）\n\n\n第二折\n\n（正末扮司马徽领道童上，未云）贫道复姓司马，名徽，字德操，道号水鉴先生。想汉家天下，鼎足三分。贫道自刘皇叔相别之后，又是数载。贫道在此江下结一草庵，修行办道，是好悠哉也呵！（唱）\n\n【正宫】【端正好】本是个钓鳌人，到做了扶犁叟；笑英布、彭越、韩侯。我如今紧抄定两只拿云手，再不出麻袍袖。\n\n【滚绣球】我则待要聚村叟，会诗友，受用的活鱼新酒，问甚么瓦钵瓷瓯。推台不换盏，高歌自掴手；任从他阴晴昏昼，醉时节衲被蒙头。我向这矮窗睡彻三竿日，端的是傲煞人间万户侯，自在优游。（云）道童，门首觑者，看有甚么人来。（道童云）理会的。（鲁肃上，云）可早来到也，接了马者。（见道童科，鲁云）道童，先生有么？（童云）俺师父有。（鲁云）你去说：鲁子敬特来相访。（童云）你是紫荆？你和那松木在一搭里。我报师父去。（见末，云）师父弟子孩儿……（末云）这厮怎么骂我！（童云）不是骂；师父是师父，弟子是徒弟，就是孩儿一般。师父弟子孩儿……（末云）这厮泼说？有谁在门首？（童云）有鲁子敬特来相访。(末云）道有请。（童云）理会的。（童出见鲁，云）有请！（鲁见末科）（末云）稽首。（鲁云）区区俗冗，久不听教。（末云）数年不见，今日何往？（鲁云）小官无事不来，特请先生江下一会。（末云）贫道在此江下修行，方外之士，有何德能，敢劳大夫置酒张筵？（唱）\n\n【倘秀才】我又不曾垂钓在磻溪岸口，大夫也，我可也无福吃你那堂食玉酒；我则待溪山学许由。（云）大人请我呵，再有何人？（鲁云）别无他客，止有先生故友寿亭侯关云长一人。（末唱）你道是旧相识寿亭侯，和咱是故友。\n\n（云）若有关公，贫道风疾举发，去不的！去不的！（鲁云）先生初闻鲁肃相邀，慨然许诺；今知有关公，力辞不往，是何故也？想先生与关公有一面之交，则是筵间劝几杯酒。（末唱）\n\n【滚绣球】大夫，你着我筵前劝几瓯，那汉劣性怎肯道折了半筹？（鲁云）将酒央人，终无恶意。（末唱）你便休题安排着酒肉，他怒时节目前见鲜血交流。你为汉上九座州，我为筵前一醉酒，（云）大夫，你和贫道，（唱）咱两个都落不的完全尸首。（鲁云）先生是客，怕做甚么？（末唱）我做伴客的少不的和你同病同忧。（鲁云）我有三条计索取荆州。（末唱）只为你千年勋业三条计，我可甚"一醉能消万古愁"，提起来魂魄悠悠。\n\n（鲁云）既是先生故友，同席饮酒何妨？（末云）大夫既坚意要请云长，若依的贫道两三桩儿，你便请他；若依不得，便休请他。（鲁云）你说来，小官听者。（末云）依着贫道说，云长下的马时节，（唱）\n\n【倘秀才】你与我躬着身将他来问候。（云）你依的么？（鲁云）关云长下的马来，我躬着身问候。不打紧，也依的。（未唱）大夫，你与我跪着膝连忙的劝酒；饮则饮、吃则吃、受则受。道东呵随着东去，说西呵随着西流。（云）这一桩儿最要紧也！（唱）他醉了呵你索与我便走。\n\n（鲁云）先生，关公酒后德性如何？（末唱）\n\n【滚绣球】他尊前有一句言，筵前带二分酒，他酒性躁不中撩斗，你则绽口儿休提着索取荆州。（鲁云）我便索荆州有何妨？（末云）他听的你索取荆州，（唱）他圆睁开丹凤眸，轻舒出捉将手；他将那卧蚕眉紧皱，五蕴山烈火难收。他若是玉山低趄，你安排着走；他若是宝剑离匣，你则准备着头。枉送了你那八十一座军州！\n\n（鲁云）先生不须多虑，鲁肃料关公勇有余而智不足。到来日我壁间暗藏甲士，擒住关公，便插翅也飞不过大江去。我待要先下手为强。（末云）大夫，量你怎生近的那关云长？（唱）\n\n【倘秀才】比及你东吴国鲁大夫仁兄下手，则消得西蜀国诸葛亮先生举口，奏与那有德行仁慈汉皇叔。那先生抚琴霜雪降，弹剑鬼神愁，则怕你急难措手。\n\n（鲁云）我观诸葛亮也小可。除他一人，也再无用武之人。\n\n（末云）关云长他弟兄五个，他若是知道呵，怎肯和你甘罢！\n\n（鲁云）可是那五个？（末唱）\n\n【滚绣球】有一个黄汉升猛似彪；有一个赵子龙胆大如斗；有一个马孟起，他是个杀人的领袖；有一个莽张飞，虎牢关力战了十八路诸侯，骑一匹毕月乌，使一条丈八矛，他在那当阳坂有如雷吼，喝退了曹丞相一百万铁甲貔貅，他瞅一瞅漫天尘土桥先断，喝一声拍岸惊涛水逆流。那一伙怎肯干休！（鲁云）先生若肯赴席呵，就与关公一会何妨？（末云）大夫，不中，不中！休说贫道不曾劝你。（唱）\n\n【尾声】我则怕刀尖儿触抹着轻犛了你手，树叶儿提防打破我头。关云长千里独行觅二友，匹马单刀镇九州；人似巴山越岭彪。马跨翻江混海兽。轻举龙泉杀车胄，怒扯昆吾坏文丑；麾盖下颜良剑标了首，蔡阳英雄立取头。这一个躲是非的先生决应了口，那一个杀人的云长，（云）稽首。（唱）我更怕他下不的手！（末下）\n\n（道童云）鲁子敬，你愚眉肉眼，不识贫道。你要索取荆州，不来问我？关云长是我酒肉朋友，我交他两只手送与你那荆州来。（鲁云）道童，你师父不去，你去走一遭去罢。（童云）我下山赴会走一遭去，我着老关两手送你那荆州、（唱）\n\n【隔尾】我则待拖条藜杖家家走，着对麻鞋处处游。（云）我这一去，（唱）恼犯云长歹事头，周仓哥哥快争斗，轮起刀来劈破了头，唬的我恰便似缩了头的乌龟则向那汴河里走。（下）\n\n（鲁云）我听那先生说了这一会，交我也怕上来了。我想三条计已定了，怕他怎的？黄文，你与我持这一封请书，直至荆州，请关公去来。着我知道，疾去早来者。（下）\n\n\n第三折\n\n（正末扮关公领关平、关兴、周仓上，云）某姓关，名羽，字云长。蒲州解良人也。见随刘玄德，为其上将。自天下三分，形如鼎足：曹操占了中原；孙策占了江东；我哥哥玄德公占了西蜀。着某镇守荆州，久镇无虞。我想当初楚汉争锋，我汉皇仁义用三杰，霸主英雄凭一勇。三杰者，乃萧何、韩信、张良；一勇者，暗呜叱咤，举鼎拔山、大小七十余战，逼霸主自刎乌江。后来高祖登基，传到如今，国步艰难，一至于此！（唱）\n\n【中吕】【粉蝶儿】那时节天下荒荒，恰周、秦早属了刘、项，分君臣先到咸阳。一个力拔山，一个量容海，他两个一时开创。想当日黄阁乌江，一个用了三杰，一个诛了八将。\n\n【醉春风】一个短剑下一身亡，一个静鞭三下响。祖宗传授与儿孙，到今日享、享。献帝又无靠无依，董卓又不仁不义，吕布又一冲一撞。\n\n（云）某想当日，掩弟兄三人，在桃园中结义，宰白马祭天，宰乌牛祭地，不求同日生，只愿同日死。（唱）\n\n【十二月】那时节兄弟在范阳，兄长在楼桑，关某在蒲州解良，更有诸葛在南阳；一时出英雄四方，结义了皇叔、关、张。\n\n【尧民歌】一年三谒卧龙网，却又早鼎分三足汉家邦。俺哥哥称孤道寡世无双，我关某匹马单刀镇荆襄。长江，今经几战场，却正是后浪催前浪。（云）孩儿，门首觑者，看甚么人来。（关平云）理会的。（黄文上，云）某乃黄文是也。将着这一封请书，来到荆州，请关公赴会。早来到也。左右，报复去：有江下鲁子敬，差上将拖地胆黄文，持请书在此。（平云）你则在这里者，等我报复去。（平见正末，云）报的父亲得知：今有江东鲁子敬，差一员首将，持请书来见。（正末云）着他过来。（平云）着你过去哩。（黄文见科）（正末云）兀那厮甚么人？（黄慌云）小将黄文。江东鲁子敬，差我下请书在此。（正末云）你先回去，我随后便来也。（黄文云）我出的这门来。看了关公英雄一个神道相。鲁子敬，我替你愁哩！小将是黄文，特来请关公。髯长一尺八，面如挣枣红。青龙偃月刀，九九八十斤。脖子里着一下，那里寻黄文？来便吃筵席，不来豆腐酒吃三钟。（下）（正末云）孩儿，鲁子敬请我赴单刀会，走一遭去。（平云）父亲，他那里筵无好会，则怕不中么？（正末云）不妨事。（唱）\n\n【石榴花】两朝相隔汉阳江，上写着道"鲁肃请云长"。安排筵宴不寻常，休想道"画堂别是风光"。那里有凤凰杯满捧琼花酿，他安排着巴豆、砒霜！玳筵前摆列着英雄将，休想肯"开宴出红妆"。\n\n【斗鹌鹑】安排下打凤牢龙，准备着天罗地网；也不是待客筵席，则是个杀人、杀人的战场。若说那重意诚心更休想，全不怕后人讲。既然谨谨相邀，我则索亲身便往。\n\n（平云）那鲁子敬是个足智多谋的人；他又兵多将广，人强马壮。则怕父亲去呵，落在他彀中。（正末唱）\n\n【上小楼】你道他"兵多将广，人强马壮"；大丈夫敢勇当先，一人拚命，万夫难当。（平云）许来大江面，俺接应的人，可怎生接应？（正末唱）你道是隔着江，起战场，急难亲傍；我着那厮鞠躬、鞠躬送我到船上。\n\n（平云）你孩儿到那江东，旱路里摆着马军，水路里摆着战船，直杀一个血胡同。我想来，先下手的为强。（正末唱）\n\n【幺篇】你道是先下手强，后下手殃。我一只手揪住宝带，臂展猿揉，剑掣秋霜。（平云）父亲，则怕他那里有埋伏。（正末唱）他那里暗暗的藏，我须索紧紧的防。都是些狐朋狗党！（云）单刀会不去呵，（唱）小可如千里独行，五关斩将。\n\n（云）孩儿，量他到的那里？（平云）想父亲私出许昌一事，您孩儿不知，父亲慢慢说一遍。（正末唱）\n\n【快活三】小可如我携亲侄访冀王，引阿嫂觅刘皇，灞陵桥上气昂昂，侧坐在雕鞍上。\n\n【鲍老儿】俺也曾挝鼓三冬斩蔡阳，血溅在沙场上。刀挑征袍出许昌，险唬杀曹丞相。向单刀会上，对两班文武，小可如三月襄阳。\n\n（平云）父亲，他那里雄赳赳排着战场。（正末唱）\n\n【剔银灯】遮莫他雄赳赳排着战场，威凛凛兵屯虎帐，大将军智在孙、吴上。马如龙，人似金刚；不是我十分强，硬主张，但提起厮杀呵磨拳擦掌。\n\n【蔓菁菜】他便有快对付能征将，排戈戟，列旗枪，对仗，我是三国英雄汉云长，端的是豪气有三千丈。\n\n（云）孩儿，与我准备下船只，领周仓赴单刀会走一遭去。（平云）父亲去呵，小心在意者！（正末唱）\n\n【尾声】须无那临潼会秦穆公，又无那鸿门会楚霸王，遮莫他满筵人列着先锋将，小可如百万军刺颜良时那一场嚷。（下）\n\n（周仓云）关公赴单刀会，我也走一遭去。志气凌云贯九霄，周仓今日逞英豪。个个开弓并蹬驽，人人贯甲与披袍。旌旗闪闪龙蛇动，恶战英雄胆气高。假饶鲁肃千条计，怎胜关公这口刀！赴单刀会走一遭去也。（下）（关兴云）哥哥，父亲赴单刀会去了，我和你接应一遭去。大小三军，跟着我接应父亲去。到那里古剌剌彩磨征旗，扑冬冬画鼓凯征鼙，齐臻臻枪刀如流水，密匝匝人似朔风疾。直杀的苦淹淹尸骸遍郊野，哭啼啼父子两分离。恁时节喜孜孜鞭敲金镫响，笑吟吟齐和凯歌回。（下）（关平云）父亲兄弟都去也，我随后接应走一遭去。大小三军，听吾将令；甲马不许驰骤，金鼓不许乱鸣，不许交头接耳，不许语笑喧哗；弓驽上弦，刀剑出鞘，人人敢勇，个个威风。我到那里：一刃刀，两刃剑，齐排雁翅；三股叉，四楞锏，耀日争光；五方旗，六沉枪，遮天映日；七稍弓，八楞棒，打碎天灵；九股索，红绵套，漫头便起；十分战，十分杀，显耀高强。俺这里雄兵浩浩渡长江，汉阳两岸列刀枪。水军不怕江心浪，旱军岂惧铁衣郎！关公杀入单刀会，显耀英雄战一场。匹马横枪诛鲁肃，胜如亲父刺颜良。大小三军，跟着我接应父亲走一遭去。（下）\n\n\n第四折\n\n（鲁肃上，云）欢来不似今朝，喜来那逢今日？小官鲁子敬是也。我使黄文持书去请关公，欣喜许今日赴会，荆襄地合归还俺江东。英雄甲士已暗藏壁衣之后，令人江上相候，见船到便来报我知道。（正末关公引周仓上，云）周仓，将到那里也？（周云）来到大江中流也。（正末云）看了这大江，是一派好水呵！（唱）\n\n【双调】【新水令】大江东去浪千叠，引着这数十人驾着这小舟一叶。又不比九重龙凤阙，可正是千丈虎狼穴。大丈夫心别，我觑这单刀会似赛村社。（云）好一派江景也呵！（唱）\n\n【驻马听】水涌山叠，年少周郎何处也？不觉的灰飞烟灭，可怜黄盖转伤嗟。破曹的樯橹一时绝，鏖兵的江水犹然热，好教我情惨切！（带云）这也不是江水，（唱）二十年流不尽的英雄血！\n\n（云）却早来到也，报复去。（年报科）（做相见科）（鲁云）江下小会，酒非洞里之长春，乐乃尘中之菲艺，猥劳君侯屈高就下，降尊临卑，实乃鲁肃之万幸也！（正末云）量某有何德能，着大夫置酒张筵？既请必至。（鲁云）黄文，将酒来。二公子满饮一杯。（正末云）大夫饮此杯。（把盏科）（正末云）想古今咱这人过日月好疾也呵！（鲁云）过日月是好疾也。光阴似骏马加鞭，浮世似落花流水。（正末唱）\n\n【胡十八】想古今立勋业，那里也舜五人、汉三杰？两朝相隔数年别，不付能见者，却又早老也。开怀的饮数杯，（云）将酒来。（唱）尽心儿待醉一夜。（把盏科）（正末云）你知"以德报德，以直报怨"么？（鲁云）既然将军言"以德报德，以直报怨"，借物不还者谓之怨。想君侯文武全材，通练兵书，习《春秋》、《左传》，济拔颠危，匡扶社稷，可不谓之仁乎？待玄德如骨肉，觑曹操若仇雦，可不谓之义乎？辞曹归汉，弃印封金，可不谓之礼乎？坐服于禁，水淹七军，可不谓之智乎？且将军仁义礼智俱足，惜乎止少个"信"字，欠缺未完。再若得全个"信"字，无出君侯之右也。（正末云）我怎生失信？（鲁云）非将军失信，皆因令兄玄德公失信。（正末云）我哥哥怎生失信来？（鲁云）想昔日玄德公败于当阳之上，身无所归，因鲁肃之故，屯军三江夏口。鲁肃又与孔明同见我主公，即日兴师拜将，破曹兵于赤壁之间。江东所费巨万，又折了首将黄盖。因将军贤昆玉无尺寸地，暂借荆州以为养军之资；数年不还。今日鲁肃低情曲意，暂取荆州，以为救民之急；待仓廪丰盈，然后再献与将军掌领。鲁肃不敢自专、君侯台鉴不错。（正末云）你请我吃筵席来那，是索荆州来？（鲁云）没、没、没，我则这般道。孙、刘结亲，以为唇齿，两国正好和谐。（正末唱）\n\n【庆东原】你把我真心儿待，将筵宴设，你这般攀今览古，分甚枝叶？我根前使不着你"之乎者也"、"诗云子曰"，早该豁口截舌！有意说孙、刘，你休目下番成吴、越！\n\n（鲁云）将军原来傲物轻信！（正末云）我怎傲物轻信？（鲁云）当日孔明亲言：破曹之后，荆州即还江东。鲁肃亲为代保。不思旧日之恩，今日恩变为仇，犹自说"以德报德，以直报怨"！圣人道："信近于义，言可复也"。"去食去兵，不可去信"。"大车无輗，小车无軏，其何以行之哉"？今将军全无仁义之心，枉作英雄之辈。荆州久借不还，却不道"人无信不立"！（正末云）鲁子敬，你听的这剑戒么？（鲁云）剑戒怎么？（正末云）我这剑戒，头一遭诛了文丑，第二遭斩了蔡阳，鲁肃呵，莫不第三遭到你也？（鲁云）没、没，我则这般道来。（正末云）这荆州是谁的？（鲁云）这荆州是俺的。（正末云）你不知，听我说。（唱）\n\n【沉醉东风】想着俺汉高皇图王霸业，汉光武秉正除邪，汉王允将董卓诛，汉皇叔把温侯灭，俺哥哥合情受汉家基业。则你这东吴国的孙权，和俺刘家却是甚枝叶？请你个不克己先生自说！\n\n（鲁云）那里甚么响？（正末云）这剑戒二次也。（鲁云）却怎么说？（正末云）这剑按天地之灵，金火之精，阴阳之气，日月之形；藏之则鬼神遁迹，出之则魑魅潜踪；喜则恋鞘沉沉而不动，怒则跃匣铮铮而有声。今朝席上，倘有争锋，恐君不信，拔剑施呈。吾当摄到，鲁肃休惊。这剑果有神威不可当，庙堂之器岂寻常。今朝索取荆州事，一剑先交鲁肃亡。（唱）\n\n【雁儿落】则为你三寸不烂舌，恼犯我三尺无情铁。这剑饥餐上将头，渴饮仇人血。\n\n【得胜令】则是条龙向鞘中蛰，唬得人向座间躲。今日故友每才相见，休着俺弟兄每相间别。鲁子敬听者，你内心休乔怯，畅好是随邪，休怪我十分酒醉也。\n\n（鲁云）臧宫动乐。（臧宫上，云）天有五星，地攒五岳。人有五德，乐按五音。五星者：金、木、水、火、土。五岳者；常、恒、泰、华、嵩。五德者：温、良、恭、俭、让。五音者：宫、商、角、徵、羽。（甲士拥上科）（鲁云）埋伏了者。（正未击案，怒云）有埋伏也无埋伏？（鲁云）并无埋伏。（正末云）若有埋伏，一剑挥之两段！（做击案科）（鲁云）你击碎菱花。（正末云）我特来破镜！（唱）\n\n【搅筝琶】却怎生闹炒炒军兵列，上来的休遮当，莫拦截。（云）当着我的，呵呵！（唱）我着他剑下身亡，目前流血！便有那张仪口，蒯通舌，休那里躲闪藏遮。好生的送我到船上者，我和你慢慢的相别。（鲁云）你去了倒是一场伶俐。（黄文云）将军，有埋伏哩。（鲁云）迟了我的也。（关平领众将上，云）请父亲上船，孩儿每来迎接哩。（正末云）鲁肃，休惜殿后。（唱）\n\n【离亭宴带歇指煞】我则见紫袍银带公人列，晚天凉风冷芦花谢，我心中喜悦。昏惨惨晚霞收，冷飕飕江风起，急飐飐云帆扯。承管待、承管待，多承谢、多承谢。唤梢公慢者，缆解开岸边龙，船分开波中浪，棹搅碎江心月。正欢娱有甚进退，且谈笑不分明夜。说与你两件事先生记者：百忙里称不了老兄心，急切里倒不了俺汉家节。（下）\n\n题目孙仲谋独占江东地\n\n请乔公言定三条计\n\n正名鲁子敬设宴索荆州\n\n关大王独赴单刀会', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂剧·关大王独赴单刀会' AND p.poem_author = '关汉卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卢沟晓月', '李东阳', '明代', '霜落桑乾水未枯，晓空云尽月轮孤。\n一林灯影稀还见，十里川光澹欲无。\n不断邻鸡催短梦，频来征马识长途。\n石栏桥上时翘首，应傍清虚忆帝都。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卢沟晓月' AND p.poem_author = '李东阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('熊约生令子四人并饶才致各以二诗祝贱辰依韵荅之 其二', '王应斗', '明代', '梧垣丰采夙推尊，厚泽垂芳拟大门。孤愤未销风雨夜，旷怀时寄水烟村。\n\n庭前特立东山树，座上频开北海樽。更喜鸿章温世谊，远寻幽石破云根。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '熊约生令子四人并饶才致各以二诗祝贱辰依韵荅之 其二' AND p.poem_author = '王应斗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('灯', '穆修', '宋代', '杳杳有时当永恨，依依何处照闲眠。\n静临客枕愁寒雨，远逐鱼篷秋暝烟。\n纤影乍欹还复立，冷花时结不成圆。\n销魂犹忆江楼夜，曾对离觞赋短篇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '灯' AND p.poem_author = '穆修';
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郊庙歌辞 享太庙乐章 大顺舞' AND p.poem_author = '郑絪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋思 秋夜同慧素窗丛碧山房不寐起吟用梦窗韵', '张伯驹', '近代', '推枕银床侧。掩画屏、还透一庭凉色。风动树声，露侵兰气，秋宽愁窄。\n\n伴吟苦幽窗乱虫，如助诉怨抑。爇细香，烟篆碧。念旧日情怀，好花时候，邂逅解征鞍处，暗魂长忆。\n\n寒夕，更残漏滴。看那人、早卸容饰。韵停瑶瑟，昏灯明灭。\n\n坠蟾犹白。弄绿影、蕉阴印纱，摇翠旗凤翼。叹久客，谁省识，便过眼悲欢，重寻无梦记得，况隔天南水北。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋思 秋夜同慧素窗丛碧山房不寐起吟用梦窗韵' AND p.poem_author = '张伯驹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄新安宋同知', '庄昶', '明代', '把臂华亭县，匆匆一语间。㩳身频要路，回首独空山。\n\n人与何年别，书曾几字还。题诗无限意，分付菊花斑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄新安宋同知' AND p.poem_author = '庄昶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汪进之通判重庆堂次李西涯韵', '谢迁', '明代', '乡评推世德，家庆擅华名。桂籍方钟秀，兰阶剩茁萌。\n\n禄分三釜足，官喜一身轻。犹忆班衣后，趋随进寿觥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汪进之通判重庆堂次李西涯韵' AND p.poem_author = '谢迁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('投赠福建桂常侍二首', '陈陶', '唐代', '后来台席更何人，都护朝天拜近臣。 \n 长笑当时汉卿士，等闲恩泽画麒麟。 \n 匝地歌钟镇海隅，城池鞅掌旧名都。 \n 不知珠履三千外，更许侯嬴寄食无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '投赠福建桂常侍二首' AND p.poem_author = '陈陶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('河西务阻风适王冬官以和赵秋曹杂诗见示遂用韵纪怀九首 其五', '林光', '明代', '挠乱诗怀几许清，浮云遮隔日微明。东君转盻回辕去，满耳池蛙草自生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '河西务阻风适王冬官以和赵秋曹杂诗见示遂用韵纪怀九首 其五' AND p.poem_author = '林光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贺陈以光老师重返教职', '叶云峰', '近代', '正值藕花暗送香，颜开笑逐读华章。七年西席负桃李，十载南冠淩雪霜。\n\n璧玉千循成大器，精金百炼益辉皇。春风重过伊川户，旧学新知自奋扬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贺陈以光老师重返教职' AND p.poem_author = '叶云峰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登金山寺四首 其二', '张萱', '明代', '水国开金界，江天耸玉台。中流双砥柱，一水两蓬莱。\n\n古刹临无地，毫光接上台。凭高最箫瑟，风雨隔江来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登金山寺四首 其二' AND p.poem_author = '张萱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送张无梦归天台', '曹谷', '宋代', '几载仙山下，无机世莫分。\n因为天市客，方识帝乡云。\n炼气壶中见，还元海内闻。\n名高赤城洞，歌赐紫皇君。\n步逐飚轮健，香随斗极焚。\n何当挹蓬阆，鸾鹤自成群。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送张无梦归天台' AND p.poem_author = '曹谷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('烧香曲', '孙原湘', '清代', '红窗十二扇明纱，喜鹊催成两鬓鸦。背影玲珑俱绝世，才情宛转总宜家。\n\n工诗惯削檀郎草，解语亲擎绣佛花。手爇水沉香一缕，月轮心事镜年华。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '烧香曲' AND p.poem_author = '孙原湘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('万侍郎母夫人挽诗', '虞俦', '宋代', '闺壸高风在，乡闾美事传。宁须伯仁长，更觉寿昌贤。\n\n禄养酬初志，恩封慰暮年。侍郎官已贵，遽返阆昆仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '万侍郎母夫人挽诗' AND p.poem_author = '虞俦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('简黄仲芳大参三首 其二', '薛瑄', '明代', '雅量每期黄淑度，正人应愧薛居州。斯文四海知同调，且喜京华并辔游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '简黄仲芳大参三首 其二' AND p.poem_author = '薛瑄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郡斋偶赋', '王祎', '明代', '宦况真萧索，虚斋足昼眠。\n思亲怀爱日，阅史记疑年。\n白发生愁里，黄花立醉边。\n风流陶靖节，输尔早归田。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郡斋偶赋' AND p.poem_author = '王祎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南华书事诗', '朱翌', '宋代', '万木杉从一寸栽，参天次第可推排。\n他年空翠桥边路，来选承天八柱材。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南华书事诗' AND p.poem_author = '朱翌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('落叶二首', '吴之英', '近代', '旧是东皇爱养臣，又惊风气逐时新。未应骨格高前辈，已把文章托后尘。\n\n多谢斧斤宽法律，频蒙雨露减精神。百年护得黄云厚，且听庖人话积薪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '落叶二首' AND p.poem_author = '吴之英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('射虎行赠射虎人', '郭钰', '元代', '昨日射虎南山颠，悲风萧萧眼力穿。今日射虎北山下，虎血溅衣山路夜。\n\n朝朝射虎无空归，家人望断孤云飞。度岭踰山弓力健，虎肉共分不辞远。\n\n府司帖下问虎皮，高枕髑髅醉不知。虎昔咆哮百兽走，一死宁知在君手。\n\n鼻端出火耳生风，拔剑起舞气如虹。昨夜空村见渔火，牛羊不牧犬长卧。\n\n作诗赠君毛发寒，烦君为我谢上官。君不见昔日刘昆称长者，虎北渡河不须射。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '射虎行赠射虎人' AND p.poem_author = '郭钰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山水友别辞 芭蕉脯', '王质', '宋代', '不愁风槭槭，不愁雨萧萧。为人张秋本，为我解春牢。\n\n脯它脯，总弗许，山鬼且往凭山树，繁阴相倍享风露。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山水友别辞 芭蕉脯' AND p.poem_author = '王质';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿黄侍郎', '度正', '宋代', '玉井之泉其源深，渊涵停蓄包千寻。\n风行于上渺河汉，诸子浅陋其蹄涔。\n茫无畔岸容鼍鳖，富有磊落潜球琳。\n大原自出号学海，馀波散及蕃儒林。\n有如霁月当空照，罗列万象中森森。\n恭惟王明可用汲，一勺沃我思贤心。\n推之四海泽焦槁，元戎十乘来骎骎。\n铜梁玉垒日澄净，夜气晨光焕井参。\n区区贱子愚且鲁，非曰能之学鼓琴。\n殷勤三弄众掩耳，莞然一笑遭知音。\n推琴而作喜欲舞，慨我得此逾兼金。\n上方穆穆回元化，舍尔其谁扶当今。\n传闻丹诏九霄下，衮舄未至虚宸襟。\n请书国纪开皇极，雍容调燮阳与阴。\n愿公自爱毋久外，天下苍生思作霖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿黄侍郎' AND p.poem_author = '度正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题金陵杂兴诗后 其七', '李琏', '宋代', '孙帝陵傍水最悲，蒋侯庙下月来迟。夜深客子心惊恐，猿挂南朝枫树枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题金陵杂兴诗后 其七' AND p.poem_author = '李琏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('旅中秋月有怀', '朱庆馀', '唐代', '久客未还乡，中秋倍可伤。暮天飞旅雁，故国在衡阳。 \n 岛外归云迥，林间坠叶黄。数宵千里梦，时见旧书堂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '旅中秋月有怀' AND p.poem_author = '朱庆馀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('木兰花慢 饯佟伯起赴江西参政任', '张野', '元代', '算青云人物，名已着，绣衣时。见湖海襟期，诗书气味，鸾鹤丰姿。十年五居廉省，便衣官、拜相复何疑。早岁曾同几砚，至今亲若埙＊。相逢未久遽相辞。忍写饯行诗。早隐隐征帆，湖光潋滟，山翠参差。雄藩笑谈余事，倘兰舟、开宴举金卮。寄语桥边鸥鹭，刘郎尘鬓如丝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '木兰花慢 饯佟伯起赴江西参政任' AND p.poem_author = '张野';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百零二首 其五十九', '释慧远', '宋代', '金地岭胸中丘壑，赤城山皮里阳秋。华顶峰脑门著地，桐柏观稽首叩头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百零二首 其五十九' AND p.poem_author = '释慧远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和谢友人惠范君用笔', '范梈', '元代', '毛君好伯仲，枉驾及东堂。尽缚曾无笇，同行倍有光。\n\n欲飞随燕上，未化学龙藏。盛赐怀全璧，斯文托一芒。\n\n姓名浑偶合，润色奈何当！且效峨眉老，题诗西上阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和谢友人惠范君用笔' AND p.poem_author = '范梈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题曹氏春江云舍', '高启', '明代', '遥波霭微云，禽寒少相语。\n君家在空阔，欲往迷洲渚。\n纷纷树离雾，稍稍花滴雨。\n日暮坐相思，江东渺何许。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题曹氏春江云舍' AND p.poem_author = '高启';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西归七首次韵和泗州十五叔父四', '晁补之', '宋代', '浮云如游尘，倏忽蔽白日，\n登高念摇落，岁暮一何疾，\n东陵种瓜事，富贵宁可必，\n人生无南北，行乐时易失，', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西归七首次韵和泗州十五叔父四' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬节忤 其四', '郑清之', '宋代', '牡丹骄春醉无力，艳紫妖红锦新织。鹿解衔花空误唐，楚以姬归竟亡息。\n\n何如野外挺孤操，照水渊然有深识。昂昂雪鬓颜真卿，何物女子称国色。\n\n主张繁华勿复言，如对雁门二千石。语君欲识梅花面，好向云岩访拾得。\n\n语君欲作梅花诗，磨尽莲经大千墨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬节忤 其四' AND p.poem_author = '郑清之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮·春风未放花心吐', '晏几道', '宋代', '春风未放花心吐，\n尊前不拟分明语。\n酒色上来迟，\n绿须红杏枝。\n\n今朝眉黛浅，\n暗恨归时远。\n前夜月当楼，\n相逢南陌头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮·春风未放花心吐' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水纹二首', '杨万里', '宋代', '初作眉头皱，还成簟面班。\n小风来不住，织遍一池间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水纹二首' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('随想随作 其六', '胡云飞', '当代', '此去经年行迹异，长歌痛哭皆随意。归来竹叶如识侬，非相非空第一义。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '随想随作 其六' AND p.poem_author = '胡云飞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自巴陵略平江临湘入通城无日不雨至黄龙奉谒', '黄庭坚', '宋代', '山行十日雨沾衣，幕阜峰前对落晖。\n野水自添田水满，晴鸠却唤雨鸠归。\n灵源大士人天眼，双塔老师诸佛机。\n白发苍颜重到此，问君还是昔人非。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自巴陵略平江临湘入通城无日不雨至黄龙奉谒' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉和颜使君真卿与陆处士羽登妙喜寺三癸亭', '皎然', '唐代', '秋意西山多，列岑萦左次。缮亭历三癸，疏趾邻什寺。 \n 元化隐灵踪，始君启高诔。诛榛养翘楚，鞭草理芳穗。 \n 俯砌披水容，逼天扫峰翠。境新耳目换，物远风烟异。 \n 倚石忘世情，援云得真意。嘉林幸勿剪，禅侣欣可庇。 \n 卫法大臣过，佐游群英萃。龙池护清澈，虎节到深邃。 \n 徒想嵊顶期，于今没遗记。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉和颜使君真卿与陆处士羽登妙喜寺三癸亭' AND p.poem_author = '皎然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈一百二十首 其三十三', '释怀深', '宋代', '时人皆拜岁，山僧也贺年。光明一点在，从听二轮迁。\n\n顺俗高叉手，和光小说禅。个中如会得，佛祖本无传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈一百二十首 其三十三' AND p.poem_author = '释怀深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂', '释真慈', '宋代', '拨尘见佛，佛亦是尘。\n问了答了，直下翻身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂' AND p.poem_author = '释真慈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄王士贵', '华岳', '宋代', '画桥相送百花春，转眼孤鸿逐断云。\n别后有谁能顾我，客中无日不思君。\n风前花影尝兴念，月下桐声久不闻。\n见说近来多好况，一书无惜寄云云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄王士贵' AND p.poem_author = '华岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('孙及归吴兴', '杨亿', '宋代', '家在霅溪傍，汀蘋绕舍香。\n草玄偏寂寞，为客苦凄惶。\n泽国聊倾盖，春闱早擅场。\n陔兰行可採，月桂自应芳。\n税驾临沧海，回辕指大梁。\n裂裳趋远道，负米及高堂。\n季子裘虽敝，安仁鬓未苍。\n明年杏园裹，辄莫负春光。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '孙及归吴兴' AND p.poem_author = '杨亿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江皋图', '李延兴', '元代', '江晚月未上，白烟满芳洲。雨止山气佳，衡扉在岩幽。\n\n浦迥沙漫漫，松深露浮浮。水田早稻熟，稍欣获有秋。\n\n旷爽来清风，朱夏炎歊收。野人乐江居，垂轮水西头。\n\n得鱼送邻家，酒好仍见留。童丱喜相随，浩歌送蜚鸥。\n\n古时放达人，傲睨轻王侯。焉能繫尘鞅，憧憧为身谋。\n\n我家汉水上，田园雅绸缪。谷苗含惠泽，井洫交新流。\n\n收穫赒族党，矢心良不媮。一自来京都，星霜倏十周。\n\n寄食仰俸粟，曷免生事忧。药物縻病身，旷望增夷犹。\n\n翩彼南飞鸿，肯寄音信否。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江皋图' AND p.poem_author = '李延兴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('慧麟侄出痘新愈于元旦日索诗因而赋此', '金朝觐', '清代', '履端嘉气至，綵笔写新春。淑鸟喧阳候，高楣启后人。\n\n远将绵嗣绪，上可慰慈亲。呼仆添炉火，题诗赐慧麟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '慧麟侄出痘新愈于元旦日索诗因而赋此' AND p.poem_author = '金朝觐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西峡行', '张元干', '宋代', '西峡门东晚潮上，涛头驾风高数丈。\n绝江艇子更扬帆，风水相吞两岸壮。\n中流荡潏思虑深，欲济未意愁夕阴。\n贾客胡商数航海，忍死射利诚何尽。\n不如遵陆困舆皂，九折羊肠复相恼。\n下临湍濑千仞渊，胥靡轻生履危道。\n我曹过计常私忧，垂堂之戒宁自尤。\n经营一饱亦细事，世乱畏涂归罢休。\n少年新进真儿剧，浪喜功名不量力。\n杀身无补误朝廷，天下英雄古难得。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西峡行' AND p.poem_author = '张元干';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八月二十日晓起', '方回', '宋代', '夜阑不能寐，鸡鸣垂欲三。\n起步秋月影，寒发何毵毵。\n斗柄落山北，参旗挂庭南。\n三五忽四五，蛙蚓众喙缄。\n独有络纬声，催织何喃喃。\n禄仕心已息，愧未任桑蚕。\n昨暮缺薪米，质以衾及缣。\n七年为此郡，忍人所难堪。\n焉知窘至此，不给石与甔。\n独坐老树下，暗捻霜须髯。\n墙外行人动，丧事很小鼓酣。\n生之必有死，如岁代凉炎。\n但颇讶薄俗，不复甄廉贪。\n鄙诮采芝馁，歆羡脍肝馋。\n想见攫夺子，枥马已就衔。\n岂识有幽人，茹苦如饴甘。\n念虽乏智计，识度终不凡。\n儿女亦可割，深山建茅庵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八月二十日晓起' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('用前韵谢野水郎君招饮', '朱继芳', '宋代', '为有台池无限娇，游人歌舞尚朝朝。\n清漪浴日开金面，晴哢调风衮绿腰。\n骚客五花唐殿马，主家七叶汉庭貂。\n丁宁红紫休开遍，约住春风待见邀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '用前韵谢野水郎君招饮' AND p.poem_author = '朱继芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人·魏家品是君王后', '刘辰翁', '宋代', '魏家品是君王后。岂比昭容袖。\n 风吹满院绣囊香。谁赐大师师号、退昭阳。 \n 飞霞一落无根蒂。空堕重华泪。\n 离披正午盛时休。闲为思王重赋、洛神愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人·魏家品是君王后' AND p.poem_author = '刘辰翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠别元初', '陈曾寿', '清代', '缱绻师门谊最隆，无如坡老说欧公。与君共事梁夫子，感遇何殊六一翁。\n\n并坐春风馀几在，追随寒日复谁同。十年趋走伤心地，剩有孤吟望断鸿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠别元初' AND p.poem_author = '陈曾寿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和宣州钱判官使院厅前石楠树', '孟郊', '唐代', '大朴既一剖，众材争万殊。懿兹南海华，来与北壤俱。 \n 生长如自惜，雪霜无凋渝。笼笼抱灵秀，簇簇抽芳肤。 \n 寒日吐丹艳，赪子流细珠。鸳鸯花数重，翡翠叶四铺。 \n 雨洗新妆色，一枝如一姝。耸异敷庭际，倾妍来坐隅。 \n 散彩饰机案，馀辉盈盘盂。高意因造化，常情逐荣枯。 \n 主公方寸中，陶植在须臾。养此奉君子，赏觌日为娱。 \n 始觉石楠咏，价倾赋两都。棠颂庶可比，桂词难以逾。 \n 因谢丘墟木，空采落泥涂。时来开佳姿，道去卧枯株。 \n 争芳无由缘，受气如郁纡。抽肝在郢匠，叹息何踟蹰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和宣州钱判官使院厅前石楠树' AND p.poem_author = '孟郊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('祝英台近 其四 烧香词', '李符', '清代', '镜中人，花外影。乍见眼波凝。书屋妆楼，同对碧梧井。\n\n三年窥宋登垣，何曾私语，真不料、相逢山径。\n\n雀离顶。凭仗金粟如来，行坐许教并。酥手偷携，暗解玉彄赠。\n\n小姑只是随身，牵衣又去，恨密约、依然难订。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '祝英台近 其四 烧香词' AND p.poem_author = '李符';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('瑞迹山', '陈自新', '宋代', '雨过山溪生虎迹，云归岩洞长龙威。\n烟钟古寺敲残日，樵笛一声江鸟飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瑞迹山' AND p.poem_author = '陈自新';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵江行四首 其一', '杨载', '元代', '潮头终岁白，沙腹有时皤。利涉他州柁，终更古戍戈。\n\n天依临海树，风作满江波。亦有投竿意，还听《孺子歌》。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵江行四首 其一' AND p.poem_author = '杨载';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东亭月夜宴集，分韵得“宵”字', '李宪噩', '清代', '东亭竹间月，好是雪晴宵。有客共来集，吟诗孤兴遥。\n\n夜华分远甸，春霭罩寒条。更爱清徽冷，临流一雨挑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东亭月夜宴集，分韵得“宵”字' AND p.poem_author = '李宪噩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题牡丹', '徐溥', '明代', '琼楼高起彩云端，愁绝东风十二阑。眼底看春春欲暮，玉人消息凤笙寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题牡丹' AND p.poem_author = '徐溥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山阁', '许相卿', '明代', '衫浥岚光先雨润，树酣江气未秋丹。飞流千尺凭阑外，并作萧萧六月寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山阁' AND p.poem_author = '许相卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送虞城刘明府谒魏郡苗太守', '高适', '唐代', '天官苍生望，出入承明庐。肃肃领旧藩，皇皇降玺书。 \n 茂宰多感激，良将复吹嘘。永怀一言合，谁谓千里疏。 \n 对酒忽命驾，兹情何起予。炎天昼如火，极目无行车。 \n 长路出雷泽，浮云归孟诸。魏郡十万家，歌钟喧里闾。 \n 传道贤君至，闭关常晏如。君将挹高论，定是问樵渔。 \n 今日逢明圣，吾为陶隐居。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送虞城刘明府谒魏郡苗太守' AND p.poem_author = '高适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题道士林希深祷雨卷', '黄镇成', '元代', '羽人曾领玉宸曹，身衣朝天白鹤袍。铁檄召雷秋雨足，瑶坛谒帝夜云高。\n\n穿林紫气频烧药，满洞丹英自种桃。若挽银河洗兵甲，应翻马鬣作波涛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题道士林希深祷雨卷' AND p.poem_author = '黄镇成';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋过济南与舍弟子校同游大明湖越五日而别 其一', '吴衡照', '清代', '秋柳题痕二百年，祇今湖水碧于烟。诗人一代斜阳外，间煞亭西弄笛船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋过济南与舍弟子校同游大明湖越五日而别 其一' AND p.poem_author = '吴衡照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜算子 和水云', '杨玉衔', '清代', '泪眼不曾晴，化作宵来雨。六曲屏山万里程，有梦无寻处。\n\n羞学倚墙花，分等沾泥絮。愿屑香尘逐马蹄，长傍郎边去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜算子 和水云' AND p.poem_author = '杨玉衔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('瀛台侍直七月至九月得十六首 其三', '陈宝琛', '清代', '书屋纯皇旧补桐，龙潜已裕十全功。神州渴望中兴主，早晚垂灵牖圣聪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瀛台侍直七月至九月得十六首 其三' AND p.poem_author = '陈宝琛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪朝乘兴欲诣李司徒留守，先以五韵戏之', '白居易', '唐代', '夜寒生酒思，晓雪引诗情。热饮一两盏，冷吟三五声。 \n 铺花怜地冻，销玉畏天晴。好拂乌巾出，宜披鹤氅行。 \n 梁园应有兴，何不召邹生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪朝乘兴欲诣李司徒留守，先以五韵戏之' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('明良诗 其六', '吴当', '元代', '侃侃开府，尚德象贤。承厥父祖，佛时仔肩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '明良诗 其六' AND p.poem_author = '吴当';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('北耗', '刘克庄', '宋代', '京师渠敢泄边机，北耗传讹果是非。不见红旗加露布，颇传黄屋尚宵衣。\n\n南风不竞师将老，春水方生虏必归。何日灵台真偃伯，更无一点战尘飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '北耗' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('许克大分教桐城道过余家留诗见柬赋以谢之', '史鉴', '明代', '翰墨论交岁月赊，朱颜今已鬓成华。两回经见曾因客，三度相过不在家。\n\n芳草伴人吟道上，乱云随鹤渺天涯。归来读罢留题句，搔首无言对落花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '许克大分教桐城道过余家留诗见柬赋以谢之' AND p.poem_author = '史鉴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('永乐殷尧藩明府县池嘉莲咏', '雍陶', '唐代', '青蘋白石匝莲塘，水里莲开带瑞光。露湿红芳双朵重， \n 风飘绿蒂一枝长。同心栀子徒夸艳，合穗嘉禾岂解香。 \n 不独丰祥先有应，更宜花县对潘郎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '永乐殷尧藩明府县池嘉莲咏' AND p.poem_author = '雍陶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '王仲敏', '宋代', '诨语销忠骨鲠亡，此中空奏忒郎当。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '王仲敏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荣庆堂为大理作', '庄昶', '明代', '万古明良分付定，早从尧禹到如今。小臣肝胆天堪照，圣世恩波海未深。\n\n紫极逶迤春荡荡，天风寥廓路骎骎。沧江回首多迂病，愧尽贤人用世心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荣庆堂为大理作' AND p.poem_author = '庄昶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乌鲁木齐', '褚廷璋', '清代', '额鲁公孙此建瓴，天戈万里下风霆。山围蒲类分西谷，云护沙陀拱北庭。\n\n不断角声横月白，无边草色入天青。辑怀城上舒雄眺，尽把耕畴换牧坰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乌鲁木齐' AND p.poem_author = '褚廷璋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('以渔洋精华录寄琥唐山春榆侍郎有诗见述率赋奉答', '严复', '清代', '九陌风鸣尘堀堁，南郭隐几今丧我。长安作梦垂十年，梦想阳崎山一逻。\n\n文书引睡睡复醒，万事不理任懒惰。河阳宗伯今词宗，赠我新诗堪已瘅。\n\n为言昭代录诗人，疑让新城居上座。士林沾丐三百年，蒋袁杭厉皆细琐。\n\n平生结习觑文字，扬榷新诗吾亦颇。文章派别几人存，大抵修辞禁淫诐。\n\n李杜光芒万丈长，坡谷九天纷咳唾。如星五纬流四渎，议论欲到吾知叵。\n\n请言在昔明中叶，群公模拟或太过。虽然法上几得中，要于风雅未为左。\n\n何来东涧恣抨击，一钱不值同骂座。渔洋崛起应新运，如麟独角推一个。\n\n譬彼射者得正鹄，稍嫌力薄愁官笴。文人相轻自古然，又被赵纪加切磋。\n\n降兹谈艺遍湖海，若个解衣旁薄赢。西昆靡靡江西粗，公安竟陵更幺么。\n\n小子何莫学夫诗，敢问师资谁则可。吾云要在士卓识，一任纷挐众口哆。\n\n斯文如女有正色，岂事涂泽徒为大。横空盘硬亦非难，欲为排奡在贴妥。\n\n取径爱好似未害，他日湘帆随转柁。清新俊逸殆天授，著眼沈郁兼顿挫。\n\n双丸头上忽忽过，风轮谁挽蚁旋磨。勿云衰叔少和声，《三百篇》皆发愤作。\n\n能收一物寄孤赏，横流亦足娱寒饿。高歌青眼望后生，比似螟蛉祝果蠃。\n\n忽蒙佳什誉过庭，语重情深谁敢荷。君家自有谢超宗，池上凤毛众所贺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '以渔洋精华录寄琥唐山春榆侍郎有诗见述率赋奉答' AND p.poem_author = '严复';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿县大夫薛宝臣', '段克己', '金朝', '薛姓婵嫣自古分，君侯苗裔粹其门。已闻佳绩多前古，更溢馀波及后昆。\n\n久屈祥鸾栖恶枳，稔推利器遇蟠根。徵书未至身閒暇，且看尊前舞袖翻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿县大夫薛宝臣' AND p.poem_author = '段克己';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金塔', '饶宗颐', '近代', '竟以蒿丘浪得名，孙吴宣化到堂明。即今举目山川异，愁听江流日夜声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金塔' AND p.poem_author = '饶宗颐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百五十首 其一四○', '释心月', '宋代', '月五日亦五，那堪时正午。采药药最灵，问疾疾即愈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百五十首 其一四○' AND p.poem_author = '释心月';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨夜', '何孟伦', '明代', '凉风入窗户，翻我读残书。叶落苔阶寂，春閒木榻虚。\n\n阴晴看异局，伎俩笑迂儒。搔首独长啸，幡怀太古初。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨夜' AND p.poem_author = '何孟伦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其三十九', '高似孙', '宋代', '蟹才逢毕卓，酒不了刘伶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其三十九' AND p.poem_author = '高似孙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题墨梅写怀', '罗亨信', '明代', '玉骨冰肌铁石肠，相逢几度月昏黄。别来京国无知己，独抱孤贞傲雪霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题墨梅写怀' AND p.poem_author = '罗亨信';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早春杂兴八首 其一', '李孙宸', '明代', '短发经霜后，春来不那梳。药囊閒自检，瓜地与僮锄。\n\n嗜酒还忧病，逋诗为懒书。晚天归网集，随意市江鱼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早春杂兴八首 其一' AND p.poem_author = '李孙宸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('将至襄陵二首 其一', '葛胜仲', '宋代', '西风寥栗不须悲，云日轻明政自奇。远岸绿飘梧槭槭，疏林红露枣离离。\n\n味回新醑愁眉破，凉入单纨病骨知。试问夜窗灯火读，何知蚊蚋扑缘时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将至襄陵二首 其一' AND p.poem_author = '葛胜仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郊居', '温宪', '唐代', '村前村后树，寓赏有馀情。青麦路初断，紫花田未耕。 \n 雉声闻不到，山势望犹横。寂寞春风里，吟酣信马行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郊居' AND p.poem_author = '温宪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄晁恭道郑德成二漕', '吕本中', '宋代', '二年住闽中，不识建溪茶。处处得残杯，顾未惬齿牙。\n\n饥肠拥滞气，病眼增昏花。故人持节来，怜我病有加。\n\n会当饷绝品，不但分新芽。苍壁月堕晓，宝胯金披沙。\n\n一洗肝肺净，兀坐如还家。阴雨又不解，天气复未佳。\n\n持诗寄两公，请为交旧时。便续北苑谱，即日定等差。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄晁恭道郑德成二漕' AND p.poem_author = '吕本中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮', '许淑慧', '清代', '斜辉漠漠东风骤。绿阴影里雏莺瘦。罗袖薄如烟。江南三月天。\n\n庭阶闲伫立。好句犹难觅。何处按笙歌。听来愁转多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮' AND p.poem_author = '许淑慧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿桂阳道中石燕馆次沈仲律韵三首 其二', '王缜', '明代', '客梦三更醒，吟怀一味清。鸡声连晓散，月色傍人明。\n\n野寺闲云占，危桥古木撑。瘴烟须避舍，秋气正侵淩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿桂阳道中石燕馆次沈仲律韵三首 其二' AND p.poem_author = '王缜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶成', '胤禛', '清代', '晴空瞬息片云生，风卷千堆雪浪惊。石虎泥龙争斗罢，澄潭涌出月轮明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶成' AND p.poem_author = '胤禛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('滑中赠崔高士瑾', '王季友1', '唐代', '夫子保药命，外身得无咎。日月不能老，化肠为筋否。 \n 十年前见君，甲子过我寿。于何今相逢，华发在我后。 \n 近而知其远，少见今白首。遥信蓬莱宫，不死世世有。 \n 玄石采盈担，神方秘其肘。问家惟指云，爱气常言酒。 \n 摄生固如此，履道当不朽。未能太玄同，愿亦天地久。 \n 实腹以芝朮，贱形乃刍狗。自勉将勉余，良药在苦口。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '滑中赠崔高士瑾' AND p.poem_author = '王季友1';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐 其一', '吴重憙', '清代', '蛮腰素口。娇小思珍偶。误杀徐娘成老丑。应得红灯绿酒。\n\n当年花月欢场，梦中妆泪千行。试问麻姑记否，而今又几沧桑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐 其一' AND p.poem_author = '吴重憙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('百字歌/自度曲', '佚名', '宋代', '蓂飞十荚，觉九分秋色，六分将极。桂子风高时更好，天产英贤同日。桥梓齐芳，一慈一孝，夺建真奇特。称觞华旦，但将老少分别。且看戏彩堂前，酒须双献，饮侍严君侧。清赏阿戎防跨灶，大小欧□相敌。疏曰贤哉，古云有是，作个家家声烈。无先无後，寿齐延应□翼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '百字歌/自度曲' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过龙里次璧间韵', '王缜', '明代', '隐隐奇峰玉笋纤，修途尝遍苦酸甜。了知世事无休日，闲看溪头春水添。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过龙里次璧间韵' AND p.poem_author = '王缜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次宫教六斋庆成韵 其二', '徐鹿卿', '宋代', '邪倾枝柱费三年，革故图新有待然。凌雨千间骈紫佩，濂溪一派宝青毡。\n\n韶鸣已觉俱忘味，鼎养何妨更击鲜。师帅作成真有道，诜诜弟子信皆贤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次宫教六斋庆成韵 其二' AND p.poem_author = '徐鹿卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('度大庾岭', '吕定', '宋代', '凿破鸿蒙一窍通，至今传说九龄功。\n天垂瘴雨蛮烟外，路入炎荒火树中。\n万里关河瞻北极，两行旌旆过南雄。\n鹧鸪声里端阳近，榕树青青荔子红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '度大庾岭' AND p.poem_author = '吕定';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汉宫春·会稽秋风亭观雨', '辛弃疾', '宋代', '亭上秋风，记去年袅袅，曾到吾庐。山河举目虽异，风景非殊。功成者去，觉团扇、便与人疏。吹不断，斜阳依旧，茫茫禹迹都无。\n千古茂陵词在，甚风流章句，解拟相如。只今木落江冷，眇眇愁余。故人书报，莫因循、忘却蓴鲈。谁念我，新凉灯火，一编太史公书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汉宫春·会稽秋风亭观雨' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古三十一首 其十八', '释如本', '宋代', '面门出入每相见，日月由来不识真。海岳惯游知己少，反身归卧岭头云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古三十一首 其十八' AND p.poem_author = '释如本';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中庭步月', '蒲寿宬', '宋代', '月光被中庭，竹影弄幽色。\n潇潇一幅素，洒洒数茎墨。\n忽然风动处，惟有月写得。\n此画应入神，无言自心识。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中庭步月' AND p.poem_author = '蒲寿宬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又赠上人 其一', '周南', '宋代', '八十诗僧岁莫閒，又随白浪上包山。青霜四面橙栾熟，独步三门独自还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又赠上人 其一' AND p.poem_author = '周南';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('姨母李夫人墨竹二首 其二', '黄庭坚', '宋代', '小竹扶疏大竹枯，笔端真有造化炉。人间俗气一点无，健妇果胜大丈夫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '姨母李夫人墨竹二首 其二' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送史寺丞赴真州六合县', '王圭', '宋代', '南国江山好，仍闻聚六峰。归心急春浪，别梦怅晨钟。\n\n手泽存遗爱，民歌接旧封。凉秋鼓予楫，文酒待相从。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送史寺丞赴真州六合县' AND p.poem_author = '王圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东邻筑舍与儿辈访之为小留', '陆游', '宋代', '甲第潭潭莫羡渠，穷人从昔爱吾庐。\n茆茨新洁嗟何欠，邻里追随故不疏。\n瓮酱芬香盘早兔，臼齑珍酽脍寒鱼。\n年丰日有携尊兴，家乘从今不一书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东邻筑舍与儿辈访之为小留' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史 其一 伏生', '陈普', '宋代', '撑肠拄肚总聱牙，汉室龙兴发乍华。掌故不来光景暮，尚书再火伏生家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史 其一 伏生' AND p.poem_author = '陈普';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题泾县水西', '吕本中', '宋代', '江东住已厌，又却过江西。急雨投泾县，穷秋渡赏溪。\n\n稻田犹少水，山路已多泥。珍重高僧意，求诗索自题。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题泾县水西' AND p.poem_author = '吕本中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐（二之一）', '陈师道', '宋代', '休休莫莫。更莫思量著。记著不如浑忘著。百种寻思枉却。 \n 绣囊锦帐吹香。雄蜂雌蝶难双。眉上放开春色，眼前怜取新郎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐（二之一）' AND p.poem_author = '陈师道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠写真刘敏叔秀才二首', '杨万里', '宋代', '冰监传神苦未工，传来恰恰五秋风。\n又将老丑形骸子，般入刘家画苑中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠写真刘敏叔秀才二首' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('罗敷媚 其一', '高旭', '清代', '连宵无梦春寒悄，雨也添愁。月也添愁。消瘦腰肢不自由。\n\n披衣重把离骚读，怨在眉头。恨在心头。楼外风光似旧不。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '罗敷媚 其一' AND p.poem_author = '高旭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青玉案', '胡汀鹭', '近代', '几春风雨韶光瘦，问耐得轻寒否。上巳清明都过后，红丝千缕。\n\n相思系就，朵朵皆低首。\n\n高烧银烛明如昼，正妆卸、疏慵后。月转回廊相见骤，睡情依旧。\n\n香含檀口，春梦浓于酒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青玉案' AND p.poem_author = '胡汀鹭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送宗器张方伯之浙江兼柬崇善刘方伯年况意见乎词', '韩雍', '明代', '瘴云初收残雨歇，张君别我游江浙。平生壮志轻别离，为惜君才心郁结。\n\n君昔作官守四明，我来浙省闻君名。紫薇堂上一相见，识君真是人中英。\n\n踰时我拜南征命，君亦来参广藩政。师行日费藉君多，我得迅扫蛮烟净。\n\n广人被泽方歌讴，浙人望治思未休。一视同仁徇民愿，进官移地君知不。\n\n君才本是庙堂具，历试想应图倚注。海内犹多事可为，好竭精忠荅知遇。\n\n同寅方伯我同年，十载不见心茫然。丈夫志定会有合，相期话旧五云边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送宗器张方伯之浙江兼柬崇善刘方伯年况意见乎词' AND p.poem_author = '韩雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦中', '刘敞', '宋代', '谁谓夏夜短，一夕梦九逝。梦中如平生，欢笑随母氏。\n\n觉来拊形躯，独在人间世。上呼声连天，洒泣血满地。\n\n何忍留我生，哀哀抱微志。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梦中' AND p.poem_author = '刘敞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清海军楼', '方信孺', '宋代', '睥睨旁围百尺楼，翚飞缥缈接云浮。\n鲸波不动海山碧，弹压东南十四州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清海军楼' AND p.poem_author = '方信孺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉和御制六韵', '吴融', '唐代', '天晓密云开，亭亭翠葆来。芰荷笼水殿，杨柳蔽风台。 \n 恩洽三时雨，欢腾万岁雷。日华偏照御，星彩迥分台。 \n 苇岸萦仙棹，莲峰倒玉杯。独惭歌圣德，不是侍臣才。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉和御制六韵' AND p.poem_author = '吴融';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长相思 其二', '王夫之', '明代', '待寻芳。懒寻芳。褪粉梨花背夕阳。清明未断霜。\n\n游丝长。柳丝长。欲绾春光春又忙。辛夷早绽香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长相思 其二' AND p.poem_author = '王夫之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辽海舟中 其二', '释今无', '明代', '落日孤舟晚，临风四望穷。鹤飞低近浪，云起远浮空。\n\n水怒人心善，霞明世界红。去年行碛雪，不与此情同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辽海舟中 其二' AND p.poem_author = '释今无';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乙巳冬十月随幼男赴海陵丞中途遇交代有开正', '孙介', '宋代', '整棹姚江到海陵，稽徊四十月行程。\n相逢既诺交承约，少待何妨信义明。\n戚戚已无终岁虑，琅琅先有诵书声。\n夫妻白首皆天幸，三乐无惭好弟兄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乙巳冬十月随幼男赴海陵丞中途遇交代有开正' AND p.poem_author = '孙介';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乙亥东坡生日距景祐丙子凡九百岁同人集于社园水榭分韵得逢字', '夏孙桐', '清代', '公生丙子诗频纪，周甲于今十五逢。元气文章长炳曜，心香樽俎尚从容。\n\n南飞更奏黄州曲，北辙遥思定武踪。九百年来同一慨，燕云终古念尧封。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乙亥东坡生日距景祐丙子凡九百岁同人集于社园水榭分韵得逢字' AND p.poem_author = '夏孙桐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿王君明', '陆文圭', '宋代', '去年中秋月色高，吴山痛饮推文豪。\n今年依旧故乡月，纷纷青紫夸儿曹。\n世间儿曹何足数，芙蓉仙人在江浦。\n握荃怀弄遗世纷，黄卷日与圣贤伍。\n曾攀月桂儿边枝，素娥夜半睡不知。\n觉来薄怒赫自持，与仙重约三秋期。\n一朝功成九宵去，小黠肯顾偷桃见。\n城东白发龙钟叟，行香来祝仙人寿。\n长生辟过未要学，千载与君期不朽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿王君明' AND p.poem_author = '陆文圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('散愁四首', '宋伯仁', '宋代', '著意功名四十年，柳花空满鬓丝边。\n男儿无补朝廷事，有愧饥餐困即眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '散愁四首' AND p.poem_author = '宋伯仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戊申三十目忏六首 其三', '杨寿杓', '近代', '风雨鸡鸣不可寻，焦桐清响感消沉。浮云薄薄人间意，流水汤汤海上心。\n\n后日最难酬一饭，当年何苦散千金。阮郎莫作穷途哭，世路多歧自古今。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戊申三十目忏六首 其三' AND p.poem_author = '杨寿杓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李氏种德斋诗', '赵孟頫', '元代', '一年之计种谷，十年之计种木。百年种德知何事，插架鳞鳞书满屋。\n\n世人责报嗟何速，我自无心徼后福。日中为市百贾闹，竞逐锥刀蛾赴烛。\n\n鬻书之利虽云薄，要令举世沾膏馥。为贤为智皆由此，耕也未必能干禄。\n\n他年种德看成功，远在子孙应可卜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李氏种德斋诗' AND p.poem_author = '赵孟頫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送白少府送兵陇右', '林鸿', '明代', '冠冕中朝贵，风尘陇路赊。三军随虎竹，万里度龙沙。\n\n古戍冰成垒，春湟雪作华。天骄犹未静，行矣莫思家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送白少府送兵陇右' AND p.poem_author = '林鸿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('日暮', '明秀', '明代', '西阁日将夕，川原生暮烟。远林归倦鸟，枯叶抱寒蝉。\n\n野岸渔罾外，秋风戍垒前。故人应念我，定有尺书传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '日暮' AND p.poem_author = '明秀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湖西九岩为一峰题 其九 月岩', '陈献章', '明代', '闇闇月堕地，忽在天中央。堕地人不觉，中天照四方。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湖西九岩为一峰题 其九 月岩' AND p.poem_author = '陈献章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂记八首 其六', '李云龙', '明代', '水帘千尺挂晴空，沸日冲云半带风。五月严霜吹不散，却疑身在水晶宫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂记八首 其六' AND p.poem_author = '李云龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏钱五首 其四', '沈周', '明代', '存亡未了复亡存，欲火难烧此利根。生化有涯真子母，圆方为象小乾坤。\n\n指挥悉听何须耳，患难能排岂藉言。自笑白头穷措大，不妨明月夜开门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏钱五首 其四' AND p.poem_author = '沈周';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂六十首', '释昙华', '宋代', '金锡罢游留靠壁，草鞋乾晒待秋风。\n且那长夏深思省，看是平生有底功。\n真实行藏宜保惜，虚头伎俩疾销溶。\n老僧岂是多饶舌，要与诸人气味同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂六十首' AND p.poem_author = '释昙华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南还别陈翼所总戎', '袁崇焕', '明代', '慷慨同雠日，间关百战时。功高明主眷，心苦后人知。\n\n麋鹿还山便，麒麟绘阁宜。去留都莫讶，秋草正离离。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南还别陈翼所总戎' AND p.poem_author = '袁崇焕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二十九日 其一', '方孝孺', '明代', '挥泪劬劳日，持觞孝义门。敢承千古托，恐负二亲恩。\n\n善颂惭诸彦，伤怀望九原。寂寥生意尽，空愧此身存。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二十九日 其一' AND p.poem_author = '方孝孺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怜愚诗四十二首 其十', '宋应星', '明代', '流火商金静晓云，伏残馀暑未清熏。孀荆不记秋风冷，日浣轻纱制练裙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怜愚诗四十二首 其十' AND p.poem_author = '宋应星';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('首尾吟二十首 其十二', '陶安', '明代', '达观万象付评量，轗轲由天莫可禳。文士有才多薄命，忠臣仗节或罹殃。\n\n鳄鱼遁迹潮民喜，蜃气凌寒海市张。造物还能爱瑰杰，达观万象付评量。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '首尾吟二十首 其十二' AND p.poem_author = '陶安';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('经师朱教谕先生八十寿言', '王世贞', '明代', '仍栖故垒学庚桑，书带沿阶薜荔墙。老去朱颜犹自王，少来青眼或能方。\n\n西河旧忆经生业，北面谁当弟子行。偶为敲针一垂钓，不将余日向文王。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '经师朱教谕先生八十寿言' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重过石城埭', '汤显祖', '明代', '石城二十四花楼，江南置酒飞花愁。\n在处胭脂久零落，不知冠盖能风流。\n拾翠江边犹记否，含笑含颦送君酒。\n满目秋光无尽时，自折莲塘花下藕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重过石城埭' AND p.poem_author = '汤显祖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('太阳 其三', '丘葵', '宋代', '太阳一入地，照月还生光。老学傥能勉，缮性岂不臧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '太阳 其三' AND p.poem_author = '丘葵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戊子汶川地震歌', '邱登成', '当代', '辰月腥尘黯玄黄，乾元坤道转洪荒，诸般异象示灾祥。\n\n皎日忽然掣寒光，奇声陡起贯屋梁，同仁惊逃步踉蹡，我亦夺门走仓皇。\n\n骇彼地母逞侜张，馆舍震荡发雷硠，目瞠魂定脊犹凉。\n\n旋知地震出汶江，震波千里及东洋，西川州县皆夷伤，甚者街市无完墙，生民十万罹祸殃。\n\n孓遗老少相扶将，翻山越岭事流亡，无饮无食啼饥肠，生死艰难向何方。\n\n或有悲号颓垣旁，血手刨掘瓦砾场，寻妻觅子唤爷娘。\n\n赈灾令谕出庙堂，麾下三军同慨慷，履险犯危救生忙。\n\n国人纷纷为解囊，输资输物输米粮，拯困救苦费周章。\n\n覆者生机半渺茫，百千学子早夭殇，墟里出尸列成行，对此谁不泪眼汪？\n\n我欲仰首叩穹苍，放声一恸何凄惶，果然天意高难量，从此后死愈彷徨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戊子汶川地震歌' AND p.poem_author = '邱登成';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄许黄门启衷', '郑鹏', '明代', '一别年华又两更，望中云树总愁生。激昂未信终无地，慰藉常怀最有情。\n\n给舍长闻新谏草，客窗还对旧书檠。祝君万里身长健，乡国衣冠仗主盟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄许黄门启衷' AND p.poem_author = '郑鹏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('淮河舟中四首 其四', '孙承恩', '明代', '寄声淮水去，归思共滔滔。吾家何所认，门前双石桥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '淮河舟中四首 其四' AND p.poem_author = '孙承恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('代江南水灾谣', '祝允明', '明代', '天皇耄不事，地后虐不仁。尽卷天河水，淋灌九州人。\n\n九州人，食多在江南。江南灌没，柰何堪之柰之何。\n\n人死无万数，薪绝灶冷无菜煮。更那得、菽与黍。遽如许，推龙号，挽龙语。\n\n汝不应吾，吾请天公，来解谪汝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '代江南水灾谣' AND p.poem_author = '祝允明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('柳梢青 书宋本梅花喜神谱后', '吴湖帆', '清代', '花占春先。香飞雪后，一样情牵。往事风流，美人林下，明月窗前。\n\n几番清梦缠绵。又何如、罗浮醉仙。心系词工，眉舒黛妩，额点妆妍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '柳梢青 书宋本梅花喜神谱后' AND p.poem_author = '吴湖帆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('北峨驿道中口占四首 其一', '湛若水', '明代', '南风不满旗，新晴日初暖。草木生光辉，得意流莺啭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '北峨驿道中口占四首 其一' AND p.poem_author = '湛若水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('即事 其一', '朱同', '明代', '菊自离披蝶自愁，道人无事懒悲秋。多情昨夜三更雨，洗出青山著屋头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '即事 其一' AND p.poem_author = '朱同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵梅花两绝句 其一', '朱槔', '宋代', '一月尤溪烟雨浓，玉梅浑作玉人逢。江南他日摘香处，莫忘云间双髻峰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵梅花两绝句 其一' AND p.poem_author = '朱槔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送防秋将', '张籍', '唐代', '白首征西将，犹能射戟支。元戎选部曲，军吏换旌旗。 \n 逐虏招降远，开边旧垒移。重收陇外地，应似汉家时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送防秋将' AND p.poem_author = '张籍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('为清渭滨作雪深室歌', '释文珦', '宋代', '积雪兮深深，万卉兮消沈，\n梅独花兮之水阴。容斯静兮暗暗，\n香斯清兮不淫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '为清渭滨作雪深室歌' AND p.poem_author = '释文珦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆昔二首', '杜甫', '唐代', '忆昔先皇巡朔方，千乘万骑入咸阳。\n阴山骄子汗血马，长驱东胡胡走藏。\n邺城反覆不足怪，关中小儿坏纪纲。\n张后不乐上为忙，至令今上犹拨乱，劳心焦思补四方。\n我昔近侍叨奉引，出兵整肃不可当。\n为留猛士守未央，致使岐雍防西羌。\n犬戎直来坐御床，百官跣足随天王。\n愿见北地傅介子，老儒不用尚书郎。\n\n忆昔开元全盛日，小邑犹藏万家室。\n稻米流脂粟米白，公私仓廪俱丰实。\n九州道路无豺虎，远行不劳吉日出。\n齐纨鲁缟车班班，男耕女桑不相失。\n宫中圣人奏云门，天下朋友皆胶漆。\n百馀年间未灾变，叔孙礼乐萧何律。\n岂闻一绢直万钱，有田种谷今流血。\n洛阳宫殿烧焚尽，宗庙新除狐兔穴。\n伤心不忍问耆旧，复恐初从乱离说。\n小臣鲁钝无所能，朝廷记识蒙禄秩。\n周宣中兴望我皇，洒泪江汉身衰疾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆昔二首' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居七咏 其四 丹桂轩', '方岳', '宋代', '何年进入玉华宫，香到君王紫禁枫。月府归来衫袖冷，蟾蜍滴露洗秋红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居七咏 其四 丹桂轩' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送僧住灵岩', '王汝玉', '明代', '百花深处寺，犹指旧吴宫。事往人何在，香消径已空。\n\n今朝送师去，兹地阐宗风。别意兼乡思，依依云树东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送僧住灵岩' AND p.poem_author = '王汝玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赞木庵和尚', '释咸杰', '宋代', '面目森严，语言希差。\n不出飞猿岭，道声蔼天下。\n活懒庵不传之宗，死衲僧虚头话霸。\n五坐道场，丛林增价。\n稽首拜手，虚空贴卦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赞木庵和尚' AND p.poem_author = '释咸杰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送张大尹', '吴俨', '明代', '青山重叠护城楼，城下人家瞰碧流。地尽耕桑民尚困，境多盗贼吏多愁。\n\n分符未报三年政，捧檄先怀百里忧。为问袁公何德化，至今血食未曾休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送张大尹' AND p.poem_author = '吴俨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵尧卿兄诗酒中兴三首 其二', '葛胜仲', '宋代', '舟行诗酒两相牵，岂暇观书理废笺。金榼兴阑多半醉，锦囊才乱罕终篇。\n\n吟哦有味增閒适，酩酊忘形谢曲拳。年大此乡疑可老，宦涂羞鬻贾人鞭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵尧卿兄诗酒中兴三首 其二' AND p.poem_author = '葛胜仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄怀故园诸兄兼柬社中诸友', '陈恩', '明代', '不是逢人懒折梅，宦情牢落不堪裁。十年饥渴看花眼，千里凄凉问月杯。\n\n吟对西风怜我瘦，梦怀阴雨竟谁来。横空片片晴云影，青眼曾无白昼开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄怀故园诸兄兼柬社中诸友' AND p.poem_author = '陈恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七月二日大风作一昼夜方止土人去此风潮信也', '张嵲', '宋代', '风潮初见土人云，始愧鲰生泥昔言。\n却以所经疑柱史，著书应只为中原。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七月二日大风作一昼夜方止土人去此风潮信也' AND p.poem_author = '张嵲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南湖', '温庭筠', '唐代', '湖上微风入槛凉，翻翻菱荇满回塘。\n野船著岸偎春草，水鸟带波飞夕阳。\n芦叶有声疑雾雨，浪花无际似潇湘。\n飘然篷艇东归客，尽日相看忆楚乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南湖' AND p.poem_author = '温庭筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('信安怀故人', '尹廷高', '元代', '昔年避地此飘蓬，访旧重来事不同。苍狗浮云春梦里，寒鸦古木夕阳中。\n\n死生契阔交情在，离合悲欢转眼空。野寺赓酬无复再，兔葵燕麦自摇风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '信安怀故人' AND p.poem_author = '尹廷高';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题文休承萱花', '欧大任', '明代', '树萱灿庭花，风日当清昼。衣以斑斓来，持献北堂寿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题文休承萱花' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晦之江楼小饮辱诗怀寄谨答来贶因以奉招', '强至', '宋代', '遥知相忆处，相忆对秋江。\n涉有波涛阔，飞无羽翼双。\n端居君故里，薄宦我他乡。\n交臂经时失，忧心曷日降。\n此稀人迹到，惟听足音跫。\n愿命朋游驾，来吟吏隐窗。\n倦谈须掷麈，剧饮定空缸。\n论契何如重，千钧不可扛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晦之江楼小饮辱诗怀寄谨答来贶因以奉招' AND p.poem_author = '强至';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水龙吟', '赵长卿', '宋代', '事为之词 \n 危楼横枕清江上，两岸碧山如画。夕烟幂幂，晚灯点点，楼台新夜。明月当天，白沙流水，冷光连野。浸栏干万顷，琉璃软皱，打渔艇、相高下。 \n 何处一声羌管，是谁家、倚楼人也。多情对景，无言有恨，欲歌还罢。把酒临筵，阿谁知我，此怀难写。忍思量后夜，芳容不似，暗尘随马。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水龙吟' AND p.poem_author = '赵长卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题应玚三入承明图', '刘鹗', '元代', '安车三度入承明，七子诗应让老成。好是衣冠遗泽远，诸孙犹自负廉声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题应玚三入承明图' AND p.poem_author = '刘鹗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜晴', '张九成', '宋代', '今夕何清快，风光胜去年。\n水南无宿霭，天末有孤烟。\n老矣休荷橐，归欤挂锦鞯。\n西湖多乐事，感慨旧山川。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜晴' AND p.poem_author = '张九成';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('巢南书来，谓将刊长兴伯吴公遗集，先期', '柳亚子', '近代', '吾乡陈季子，磊落复英奇。\n不远关河阻，殷勤尺素驰。\n遗闻珍义侠，喜气溢门楣。\n扬讫千秋事，如君信可师。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '巢南书来，谓将刊长兴伯吴公遗集，先期' AND p.poem_author = '柳亚子';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('午日同于鳞子与集公实时值雷雨', '宗臣', '明代', '蓟门芳草逐人来，午日新蒲对酒开。沉陆揔为方朔侣，怀沙独惜楚臣才。\n\n人间魍魉雷堪走，海上蛟龙雨不回。夜半浮云难去女，更堪孤角凤城哀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '午日同于鳞子与集公实时值雷雨' AND p.poem_author = '宗臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙 其二', '赵尊岳', '近代', '鹃血斑斑点玉簪。帕罗封泪剩哀吟。纵无风雨亦春深。\n\n万劫沾泥终不悔，千秋密誓待重寻。昨宵圆月照街心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙 其二' AND p.poem_author = '赵尊岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮 寄江西米理问信父 天下同文', '卢挚', '元代', '市桥烟柳春如画。小楼明月吴山下。把酒听君歌。可人良夜何。旧游新梦断。月落西江远。江上数峰青。寄声徐孺亭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮 寄江西米理问信父 天下同文' AND p.poem_author = '卢挚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阴阳吟', '邵雍', '宋代', '阳行一，阴行二。\n一主天，二主地。\n天行六，地行四。\n四主形，六主气。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阴阳吟' AND p.poem_author = '邵雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠乐閒居士', '方凤', '宋代', '市远尘嚣隔，神閒幽事并。埽花怜竹影，煮茗讶松声。\n\n月与诗如约，琴将鹤互赓。冷香生碧落，秋梦不胜清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠乐閒居士' AND p.poem_author = '方凤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('百字令 为徐桐老题九老图，戏仿竹垞例用徐氏故事', '许宝蘅', '近代', '神情气爽，认青衫白发，南州高士。滚滚公侯原积善，故是人间骐骥。\n\n蹈道依仁，有功怀文抱，畴昔推佳吏。游梁才调，邹严同著名字。\n\n飘然不受牢笼，美容毁誉，何处寻真际。采药神仙中圣酒，风月清谈而已。\n\n家有八龙，世称四皓，图尽江南比。将军八十，五经犹诵千纸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '百字令 为徐桐老题九老图，戏仿竹垞例用徐氏故事' AND p.poem_author = '许宝蘅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新晴西园散步四首', '杨万里', '宋代', '池水初生盖玉沙，雨余碧草卧堤斜。\n日摇波影缠桥柱，绣出栾枝遍地花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新晴西园散步四首' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苏幕遮', '李良年', '清代', '水初生，天更远。愁绪无根，早蔓斜阳岸。挑菜湔裙都不见。\n\n一派溪光，付与梅花占。月依依，雪剪剪。记得花间，衣上香难辨。\n\n诉前游，寻语燕，可奈新雏，未省春风面。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苏幕遮' AND p.poem_author = '李良年';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('灞桥骑驴', '何梦桂', '宋代', '小骊买得最便宜，好是河梁古柳涯。风急吹沙长耳峻，雪深没板蹇蹄迟。\n\n据鞍吟透肩双耸，敲镫歌狂帽半攲。道上莫教逢大尹，推敲句里不曾知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '灞桥骑驴' AND p.poem_author = '何梦桂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('巫山高', '杨士奇', '明代', '巫山高高十二峰，连崖叠褵如游龙。\n当时阳台下神女，翠敛红销空处所。\n朝朝峡里望氛氲，可怜犹似作行云。\n相思已下沾裳泪，况复猿声不可闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '巫山高' AND p.poem_author = '杨士奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('车中杂言十首 其四', '顾璘', '明代', '耕莘起三聘，钓渭载后车。遇合非汤文，终然老农渔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '车中杂言十首 其四' AND p.poem_author = '顾璘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄李微之秘监三首', '岳珂', '宋代', '引领蓬莱唐谪仙，湓江一别又经年。\n麟台高蹑三神路，狐笔方持千载权。\n炉袅新烟招我隐，驿催逸事仗谁传。\n校旗犹识临淮略，更等凉台亲简编。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄李微之秘监三首' AND p.poem_author = '岳珂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读陈石老诗感赋', '杨民仁', '近代', '为留史迹感徘徊，文物千年未化灰。不是天翻与地覆，人间那得马王堆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读陈石老诗感赋' AND p.poem_author = '杨民仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和丁大声登皆山楼之作依韵', '王炘', '清代', '山色侵楼重，竹阴傍涧清。绿峰群寂寂，黄鸟独声声。\n\n雾聚松枝合，樵稀石面生。云收余峭壁，日影北林更。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和丁大声登皆山楼之作依韵' AND p.poem_author = '王炘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('代怨别曲 其一', '屈大均', '明代', '绣被初覆时，恩情两颠倒。山木爱女萝，缠绵愿终老。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '代怨别曲 其一' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题胡氏南园精舍', '黎廷瑞', '宋代', '平泉竹石堕荒芜，金谷池台莽废墟。\n今古茫茫竟谁屋，乾坤呐呐有吾庐。\n溪山围座醉留客，灯火隔林闻读书。\n此乐输君先一著，故园吾已赋归与。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题胡氏南园精舍' AND p.poem_author = '黎廷瑞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春柳十咏 其一 隋堤', '敦敏', '清代', '御河河畔问垂杨，飞絮飞花尽可伤。遗恨绿烟犹夕照，旧游金穗锁横塘。\n\n龙舟南幸人安在，汴水东流路正长。莫向春来寻故迹，鸦啼别苑总回肠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春柳十咏 其一 隋堤' AND p.poem_author = '敦敏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('生查子', '魏承班', '唐代', '烟雨晚晴天，零落花无语。难话此时心，梁燕双来去¤ \n 琴韵对薰风，有恨和情抚。肠断断弦频，泪滴黄金缕。 \n 寂寞画堂空，深夜垂罗幕。灯暗锦屏欹，月冷珠帘薄¤ \n 愁恨梦难成，何处贪欢乐。看看又春来，还是长萧索。 \n 离别又经年，独对芳菲景。嫁得薄情夫，长抱相思病¤ \n 花红柳绿间晴空，蝶舞双双影。羞看绣罗衣，为有金鸾并。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '生查子' AND p.poem_author = '魏承班';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送陈景明尚书赴召四首', '黄公度', '宋代', '物望唐姚宋，才名汉董晁。\n力阵治安策，亲际圣明朝。\n谠议裨宸极，高文灿斗杓。\n鹏程九万里，一举接扶摇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送陈景明尚书赴召四首' AND p.poem_author = '黄公度';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('真珠亭', '金君卿', '宋代', '新寺回廊入翠微，亭前珠树斗芳菲。\n寄言游者休披采，还似人怀薏苡归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '真珠亭' AND p.poem_author = '金君卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽蔡祭酒', '程珌', '宋代', '孝友尊前哲，词章裕后生。\n析台真御史，槐市大司哉。\n骐骥风方力，艅艎浪忽倾。\n山寒丹旐急，识者为沾缨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽蔡祭酒' AND p.poem_author = '程珌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶作秋英八种各题以诗 其七 石竹', '弘历', '清代', '周阿迥出群，蜂蝶任纷纷。不与蘼芜伍，终因近此君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶作秋英八种各题以诗 其七 石竹' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠丘文学', '王世贞', '明代', '尔信丘迟子，吾几失后生。清冰知外氏，白雪是家声。\n\n偶作依刘计，因成御李名。齐安好三径，秋菊未辞英。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠丘文学' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('姑苏曲', '刘崧', '明代', '姑苏城头乌夜啼，姑苏台上风凄凄。芙蓉露冷秋香死，美人夜泣双蛾低。\n\n铜龙咽寒更漏促，手拨繁弦转红玉。鸳鸯飞去屧廊空，犹唱吴宫旧时曲。\n\n吴山青青吴殿荒，麋鹿来游春草长。阖闾门户东风起，年年花落愁西子。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '姑苏曲' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观潮同钝轩', '全祖望', '清代', '扬波相国伍，重水大夫文。白马新来者，遥知顾令君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观潮同钝轩' AND p.poem_author = '全祖望';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('有感', '郑用锡', '清代', '缃帙何曾富五车，稍能吟咏足豪华。无多远识辽东豕，自笑拘墟井里蛙。\n\n嘈杂声音惟和蚓，编排字句欲涂鸦。詅痴符己人人画，覆瓿文章莫漫誇！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '有感' AND p.poem_author = '郑用锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送赴省诸友 林少嘉', '刘克庄', '宋代', '此君词翰逼晁秦，万鹄袍中少拟伦。色笔探怀如有助，朱衣点首岂能神。\n\n长安市素多游侠，天子廷曹怀士人。玉座临轩亲发策，可无鲠论披龙鳞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送赴省诸友 林少嘉' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('惠崇芦雁', '元好问', '金朝', '寒沙折苇静相依，故国春风早晚归。意外羁栖谁画得？羽毛单薄稻粱微。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '惠崇芦雁' AND p.poem_author = '元好问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送二兄三兄赴廷对', '魏了翁', '宋代', '吾家令兄弟，异氏而同气。雅知义利分，不作温饱计。\n\n天子龙飞春，了翁对轩陛。柄臣方擅朝，党论如鼎沸。\n\n轧轧不能休，一挥三千字。植治贵和平，用人戒偏陂。\n\n天子擢第一，期以风有位。寻寘之三人，仍诏恩礼视。\n\n后此者三年，东瞻复联第。天子方谅闇，有言不得试。\n\n岁行在协洽，文翁陈谠议。惟知守家学，宁顾触时忌。\n\n虽不第甲乙，自谓傥无愧。古人为己学，何有于富贵。\n\n穷则独善身，仕将以行义。两兄西南彦，九牧将倒指。\n\n平生刚直胸，毋以科举累。矧逢主听宽，宁复怀顾畏。\n\n厥今果何事，请略陈一二。内无王文正，谁与理家事。\n\n外无韩忠献，谁与饬戎备。荧惑守羽林，震雷诧冬瑞。\n\n天象已云然，人事犹尔耳。劈析为上言，卓哉朝阳喙。\n\n却携令名归，为亲一启齿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送二兄三兄赴廷对' AND p.poem_author = '魏了翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和答诸兄弟四首 其三', '张守', '宋代', '门对芙渠碧沼清，萧萧五柳似渊明。远听林壑风鸣籁，戏看儿童草鼓筝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和答诸兄弟四首 其三' AND p.poem_author = '张守';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('华岩洞有耶律楚材故桓夏公石刻', '黎民表', '明代', '深壑因谁造，挥斤亦有神。江山留王气，题咏待词人。\n\n泉作窗间雨，苔生石上尘。碧纱笼底墨，萧索竟千春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '华岩洞有耶律楚材故桓夏公石刻' AND p.poem_author = '黎民表';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凤仙图', '张宁', '明代', '华月中天一凤过，五铢衣薄夜凉多。彩云未断箫声远，回首秦台路几何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凤仙图' AND p.poem_author = '张宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汝宁徐使君 其四', '李攀龙', '明代', '鸿陂东注汝阳城，太守乘春出劝耕。童子但须骑竹马，夹车休唱芋魁羹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汝宁徐使君 其四' AND p.poem_author = '李攀龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又答斌老病愈遣闷二首 其二', '黄庭坚', '宋代', '风生高竹凉，雨送新荷气。鱼游悟世网，鸟语入禅味。\n\n一挥四百病，智刃有馀地。病来每厌客，今乃思客至。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又答斌老病愈遣闷二首 其二' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('始皇', '于石', '宋代', '万世纲常具六经，天应未遽丧斯文。\n焚书欲灭先王道，道在人心不可焚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '始皇' AND p.poem_author = '于石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('石城寺', '滕宗谅', '宋代', '山势如城绕楚宫，几人登赏我心同。\n溪云去作人间雨，涧水来生坐上风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '石城寺' AND p.poem_author = '滕宗谅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('都梁十景诗 杏花园春昼', '米芾', '宋代', '风轻云淡午天春，花外游人载酒樽。不是山屏遮隔断，牧童错指是孤村。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '都梁十景诗 杏花园春昼' AND p.poem_author = '米芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋潭为吴仲益赋', '陈郁', '宋代', '不留一叶山骨瘦，祗浸几星波影寒。\n中有高人倚空阔，绝疑不随水晶盘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋潭为吴仲益赋' AND p.poem_author = '陈郁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题顾升瘗琴铭及其妻庄宁书多心经', '郑孝胥', '清代', '遣词掩抑《瘗琴铭》，下笔沉吟资福经。毕竟乞灵文字好，生天成佛总无灵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题顾升瘗琴铭及其妻庄宁书多心经' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵世美简别乘喜雨', '邹浩', '宋代', '一勺龙泉甫到城，滂沱疑是泻南溟。枣心正为斯民赤，菜色宁忧异日青。\n\n击壤田家方自得，掷金诗轴已交形。病来无复高阳兴，宴喜空烦置醁醽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵世美简别乘喜雨' AND p.poem_author = '邹浩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('台湾竹枝词 其十一', '薛约', '清代', '积薪煨芋饱晨昏，人说山中傀儡番。果腹不须分甲乙，淳风偏让野人敦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '台湾竹枝词 其十一' AND p.poem_author = '薛约';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('霜寒舟中', '刘过', '宋代', '展转牛衣冷不禁，著人无奈晓寒侵。由来十月清霜重，况乃荒村白露深。\n\n有客分金来橘社，何人涂血染枫林。不堪青女来料理，折尽衰翁一片心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '霜寒舟中' AND p.poem_author = '刘过';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绍兴以后时享二十五首 僖祖室酌献用《基命》。', '郊庙朝会歌辞', '宋代', '于穆文献，自天发祥。肇基明命，锡羡无疆。子孙千亿，宗社灵长。\n\n神之格思，如在洋洋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绍兴以后时享二十五首 僖祖室酌献用《基命》。' AND p.poem_author = '郊庙朝会歌辞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桐川儒学杂咏十七首 其十二 蟠龙窟', '周瑛', '明代', '山坳最深处，游人慎莫入。晓来云气腥，中有神龙蛰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桐川儒学杂咏十七首 其十二 蟠龙窟' AND p.poem_author = '周瑛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('离镡津', '刘志行', '宋代', '公事无多早散衙，蜀中宁有寄来茶。\n龙光下照三江水，燕子重寻百姓家。\n畴昔买浆曾得玉，只今作饭类蒸沙。\n寄言道士玄都客，好种刘郎去后花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '离镡津' AND p.poem_author = '刘志行';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('广陵二首 其二', '王慎中', '明代', '前王闻失国，游客欲陈风。楼观飞云里，旌旗耀海中。\n\n一时歌舞散，千载市朝空。独有青天月，曾经照旧宫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '广陵二首 其二' AND p.poem_author = '王慎中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('客中岁尽寓怀', '谢晋', '明代', '江边摇落景萧疏，客里愁惊岁暗除。寒沼有冰胶破砚，晚窗无雪照残书。\n\n青窥柳眼迎春笑，粉妒梅容待腊舒。自叹新年归未得，故园桃李复何如。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '客中岁尽寓怀' AND p.poem_author = '谢晋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杨待制挽词', '楼钥', '宋代', '蜀道名天险，驰驱敢惮劳。\n剑头悬六印，梦里益三刀。\n汉殿联簪橐，燕山拥节旄。\n惜哉觇国意，不得试龙韬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杨待制挽词' AND p.poem_author = '楼钥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山中杂兴二十首 其三', '王冕', '元代', '居山还有趣，斸地本无谋。相顾谁青眼？同盟尽白头。\n\n豺狼迷道路，猿鸟傍林丘。休问巢由乐，吾心自可求。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山中杂兴二十首 其三' AND p.poem_author = '王冕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桂湖五首', '曾国藩', '清代', '遂刘华阳国，归程始此赊。\n翻然名境访，来及夕阳斜。\n翠竹偎寒蝶，丹枫噪幕鸦。\n词人云异代，临水一咨嗟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桂湖五首' AND p.poem_author = '曾国藩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新月', '弘历', '清代', '生轮当首度，散彩历天垣。来去只如此，盈虚略可论。\n\n榆街宵尚永，灯市晚争喧。底事光明甚，姮娥眄上元。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新月' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('道先游仙都至李尊师故居见余早岁题赠拙句存于屋', '吕南公', '宋代', '仙李枝条万国分，陇西旧望道家孙。曾经二十载还往，忽过七千馀晓昏。\n\n人落九泉无可奈，诗存古壁更休论。困穷辞气君偏爱，太息南征返北辕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '道先游仙都至李尊师故居见余早岁题赠拙句存于屋' AND p.poem_author = '吕南公';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苏台雨夜', '钱荣光', '清代', '夜阑灯灺近三更，枕上微闻滴溜声。多少缠绵繫丝雨，今宵无梦返江城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苏台雨夜' AND p.poem_author = '钱荣光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('成都府鹿鸣宴', '袁说友', '宋代', '大启文明会胜流，同升更合上西楼。\n三春得意桃花浪，八月乘槎桂子秋。\n结绶偏应登凤阙，拿云直欲钓鳌头。\n乘除但看今年好，六八名高五十州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '成都府鹿鸣宴' AND p.poem_author = '袁说友';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('正月初一归自临湘记青坡景', '卢青山', '当代', '吹面风来已不寒，太阳光暖似能燃。山阳雪尽山阴白，正得冬春两并看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '正月初一归自临湘记青坡景' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('分题得瘿林壶', '吕公著', '宋代', '天地产众材，任材谓之智。\n栋桷与楹杙，小大无有弃。\n方者以矩度，圆者中规制。\n嗟尔木之瘿，何异肉有赘。\n生成拥肿姿，赋象难取类。\n櫽括所不施，钩绳为尔废。\n大匠睨而往，恻然乃有意。\n孰非造化功，而终配不器。\n刳剔虚其中，朱漆为之伪。\n斟浆挹酒醴，施用惟其利。\n犠象非不珍，金罍岂不贵。\n设之于楹阶，十目肯注视。\n幸因左右容，反见为奇异。\n人之于才性，夫岂远于是。\n性虽有不善，在教之揉励。\n才亡不可用，由上所措置。\n饰陋就其长，皆得为良士。\n执一以废百，众功何由备。\n是惟圣人心，能通天下志。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '分题得瘿林壶' AND p.poem_author = '吕公著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('声声慢（赋红木犀·余儿时尝入京师禁中凝碧池，因书当时所见）', '辛弃疾', '宋代', '开元盛日，天上栽花，月殿桂影重重。十里芬芳，一枝金粟玲珑。管弦凝碧池上，记当时、风月愁侬。翠华远，但江南草木，烟锁深宫。 \n 只为天姿冷淡，被西风酝酿，彻骨香浓。枉学丹蕉，叶展偷染妖红。道人取次装束，是自家、香底家风。又怕是，为凄凉、长在醉中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '声声慢（赋红木犀·余儿时尝入京师禁中凝碧池，因书当时所见）' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蓬莱飞峰', '韩信同', '宋代', '海上神山名自昔，来去随潮无定迹。天人俯览念虚浮，六鳌顶戴穷神力。\n\n群仙贝阙蕊珠宫，多种瑶芝琼草碧。依然根著不坚牢，飞入石堂作南壁。\n\n螺纹蛎迹石龙存，云气随潮时雨湿。仙风飒爽生羽翰，招纳霓裳羽衣客。\n\n试登绝顶望五湖，高楼洞天才咫尺。药炉灰冷多登真，九转丹成人未识。\n\n云间鹤迹托来篇，王邓真人久相忆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蓬莱飞峰' AND p.poem_author = '韩信同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('螺山隐士歌', '梦观法师', '明代', '螺山有隐士，飘飘仙者徒。\n朝游螺之巅，暮息螺之隅。\n红尘拂落身外事，白首读尽人间书。\n不骑琴高鲤，不钓任公鱼。\n手披演雅篇，架列山海图。\n蛾司漫给五斗黛，蛤浦岂羡双明珠。\n槐台封侯笑蝼蚁，楚关脱网怜蜘蛛。\n人言大隐隐朝市，小隐螺山无乃是。\n何物老病香山翁，隐作流官良可鄙。\n酌螺之杯隐螺几，坐对螺山净如洗。\n钿屏矗矗镜边来，佛髻峨峨望中起。\n千林飞翠散晴空，半岛寒云浸秋水。\n我寻螺山居，遂识螺山路。\n一见螺山人，再诵螺山句。\n纷纷草堂文，悠悠遂初赋。\n丈夫无远谋，千载何足慕。\n我本逍遥人，亦有罝网虑。\n买山每寄沃州书，寥落江乡叹迟暮。\n江乡寥落不可留，便当卜尔山之幽。\n安得神鳌负山去，共踏青螺海上游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '螺山隐士歌' AND p.poem_author = '梦观法师';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('施云舫舍人士洁', '杨浚', '清代', '海东拥一砚，皋比亦足豪。时哉易白头，逝水看滔滔。\n\n春明强别后，九日思题糕。少年当努力，为底名山逃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '施云舫舍人士洁' AND p.poem_author = '杨浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉楼春', '刘敏中', '元代', '清官厨馔无兼味。饥待公庭人吏退。野人尊俎有余欢，明月可批风可脍。\n\n野人衰残清官贵。生死论交吾未愧。天开酒禁已多时，却甚不来同一醉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉楼春' AND p.poem_author = '刘敏中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('腊日与同官小集八阵台观武侯新祠', '王十朋', '宋代', '伏几何时腊又逢，天涯尊酒记游从。未于山下祠黄石，且向江濆谒卧龙。\n\n青眼共看官舍柳，白头相对雪天峰。虎符愿逐桃符换，万里归心一片浓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '腊日与同官小集八阵台观武侯新祠' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头 赠白兰谷', '李道纯', '元代', '三元秘秋水，微密实难量。米分清浊，天地人物一包藏。一乃太玄真水，二气由兹运化，三极理全彰。上下降升妙，根本在中黄。兔怀胎，牛喘月，蚌含光。人明此理，倒提斗柄戽银潢。绝断曹溪一派，掀倒蓬莱三岛，无处不仙乡。谁为白兰谷，安寝感羲皇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头 赠白兰谷' AND p.poem_author = '李道纯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郭文举祠', '释文珦', '宋代', '封禺山水国，曾是郭文游。\n列岫开新障，平川合众流。\n丹青遗像在，松竹古祠秋。\n虽不逢尧禅，高风似许由。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郭文举祠' AND p.poem_author = '释文珦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洛阳剑客歌为程景阳作', '赵汸', '元代', '洛阳古称豪杰窟，奇材剑客尤超忽。汉家三十六将军，剧孟归来如敌国。\n\n争夸玉贝高拄颐，曼胡短后供儿嬉。平生耻学一人敌，胸中耿耿谁能知。\n\n功名何必惭廉蔺，排难解纷声愈振。白头恨不当单于，误身竟坐封侯印。\n\n长安卿相真庸奴，鬼妾鬼马穷欢娱。一朝万事成瓦裂，金钱果为何人输。\n\n君不见洛阳剑客藏名久，好尽中山千石酒。精灵变化会有时，莫遣光芒射牛斗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洛阳剑客歌为程景阳作' AND p.poem_author = '赵汸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽吴夫人', '华岳', '宋代', '鸾骖不是厌尘凡，王母瑶池促驾还。\n家在两三千里外，人生一十六年间。\n好随神女游舒水，难伴文君归蜀山。\n试向仙源问消息，桃花零落水潺潺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽吴夫人' AND p.poem_author = '华岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登山', '曾琦', '近代', '为寻真面到庐山，漫似坡仙与谪仙。\n天下纷纷竞智巧，不知何处觅秋天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登山' AND p.poem_author = '曾琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('钧天曲', '朱诚泳', '明代', '飞游郁罗境，稽首东王公。开轩临法座，置酒燕灵宫。\n\n紫云歌玉女，琼浆酌金童。挥刀麟脯细，入箸鸾膏空。\n\n凤箫声袅袅，鼍鼓鸣逄逄。投壶起天笑，吹律回春融。\n\n燕罢百神散，乐阕万舞终。归来倚馀醉，凭虚驭刚风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '钧天曲' AND p.poem_author = '朱诚泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酷相思 春感', '高旭', '清代', '正值花开三日雨。恨春信，无凭据。只一缕痴魂何处去。\n\n踏遍是，天涯路。觅遍是，天涯路。\n\n燕去鸿来经几度。心事也，何从诉。况隔著红墙天又暮。\n\n不醉也，愁无数。便醉也，愁无数。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酷相思 春感' AND p.poem_author = '高旭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('废褒能寺', '圆印持', '明代', '枯松乱竹一丘陵，曾此开堂演上乘。\n瞰祭鸦如放生鸟，扫坟人似远归僧。\n刹竿倒处见翁仲，鬼火移时替佛灯。\n片碣欲书闲姓字，不知敕赐有褒能。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '废褒能寺' AND p.poem_author = '圆印持';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书斋小景', '多隆阿', '清代', '偷閒逐日理诗瓢，雅托名花慰寂寥。浓绿酣红我兼取，阶前补种美人蕉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书斋小景' AND p.poem_author = '多隆阿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵沈彦述官舍书事二绝 其二', '周紫芝', '宋代', '晚得休文一解颜，识君曾是画图间。阳春白雪何由和，句有雌霓诵亦难。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵沈彦述官舍书事二绝 其二' AND p.poem_author = '周紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('遣怀', '陆游', '宋代', '暮年世事转悠悠，揽涕凄然类楚囚。\n不道浑无排遣处，病观周易闷梳头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '遣怀' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨打牡丹花残二首 其二', '释函是', '明代', '试问枝头知未知，岂堪惆怅忆当时。洛阳箫管终难尽，只是人心有盛衰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨打牡丹花残二首 其二' AND p.poem_author = '释函是';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题也先帖木儿开府宅壁画山水歌', '赵孟頫', '元代', '大山崒嵂摩青天，小山平远通云烟。商侯胸中有丘壑，信手落笔分清妍。\n\n阆风玄圃元不远，粲烂金碧流潺湲。参差涧谷楼观起，萦纡石路朱桥连。\n\n松风飕飗响虚阁，棋声剥琢来群仙。渔歌樵唱渺何许，纶巾羽扇清溪边。\n\n高情自有泉石趣，凉意不受尘埃缠。世间书画亦岂少，谁能真赏如公贤。\n\n华堂风日不到处，绝胜绣幕空高悬。举觞酌酒为公寿，眼明对此三千年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题也先帖木儿开府宅壁画山水歌' AND p.poem_author = '赵孟頫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('周颂·闵予小子', '佚名', '先秦', '闵予小子，遭家不造，嬛嬛在疚。於乎皇考，永世克孝。念兹皇祖，陟降庭止。维予小子，夙夜敬止。于乎皇王，继序思不忘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '周颂·闵予小子' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('使君重过山楼分赋得空字', '李攀龙', '明代', '使君千骑入从东，此日登临作赋雄。树杪平湖元在地，檐前叠嶂半浮空。\n\n烟霞色借双轓动，牛斗光摇一剑通。自入鹿门常谢客，谁能浊酒过庞公。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '使君重过山楼分赋得空字' AND p.poem_author = '李攀龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄许玉林', '杨慎', '明代', '吾怜许玉林，道气夙龄深。悬车未华发，解佩晏清襟。\n\n山水归与兴，琴樽静者心。紫芳行可觌，丹灶拟同寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄许玉林' AND p.poem_author = '杨慎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江月图', '林之奇', '宋代', '冥冥一月轻，不知水与天。\n独於颢气中，仰见素璧圆。\n超然狂道士，起视清夜阑。\n自拈白玉笛，吹此江月寒。\n想当万籁息，逸响流空烟。\n我来江海来，形留意先还。\n何当买渔篷，追此水墨仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江月图' AND p.poem_author = '林之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶兴 其二', '韩淲', '宋代', '胶胶扰扰复悠悠，多少迷情不掉头。利者笑名名笑利，日前身后欲何谋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶兴 其二' AND p.poem_author = '韩淲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽内阁吕逢原学士', '韩雍', '明代', '赞化调元未尽才，哭亲声里动悲哀。九重深悼宣公逝，四海空期圣相来。\n\n华国有文藏玉署，捧天无梦起芸台。不堪泪眼频南望，几见红云掩上台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽内阁吕逢原学士' AND p.poem_author = '韩雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送徐都阃归宜兴', '顾清', '明代', '五色春衫拂地垂，东门高宴驻旌麾。旧来仲郢人知少，欲去玄成马上迟。\n\n红叶巧当官路坠，白云长傍禁垣移。鲤庭桃李春阴在，却愧杨生后赋诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送徐都阃归宜兴' AND p.poem_author = '顾清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('仲兄生日家大人作诗恭次元韵', '孙应时', '宋代', '恭承弧矢射芳晨，三纪风光又一春。深喜团圞娱父母，何当合沓燕宾亲。\n\n百年好共成门户，千万宁忧欠宅邻。满酌期兄增壮志，相携平步上星辰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '仲兄生日家大人作诗恭次元韵' AND p.poem_author = '孙应时';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬日谩成和郑希大八首 其一', '黄衷', '明代', '旭日晞玄发，名山秘硕肤。病鸱乘鬼气，凉月向人呼。\n\n达命还当合，长城正背孤。问予行住性，朝莫树头乌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬日谩成和郑希大八首 其一' AND p.poem_author = '黄衷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高士咏 其四十五 庞德公', '吴筠', '唐代', '庞公栖鹿门，绝迹远城市。超然风尘外，自得丘壑美。\n\n耕凿勤厥躬，耘锄课妻子。保兹永无患，轩冕何足纪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高士咏 其四十五 庞德公' AND p.poem_author = '吴筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题多稼轩', '弘历', '清代', '轩名多稼久留贻，结构年深稍葺治。栋宇从新适可耳，仓箱有庆恰逢之。\n\n应缘重穑天心示，益凛知艰圣训垂。宁即一园将一省，绥丰九㝢永祈斯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题多稼轩' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('章江忆故园四首 其二', '苏升', '明代', '亦有渔人出钓矶，江鱼得似海鱼肥。无端忽作张郎想，不到秋风也忆归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '章江忆故园四首 其二' AND p.poem_author = '苏升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄鹤洞仙', '王哲', '元代', '有个害风儿，海上寻良价。只为心头忒紧图，意马隘。\n\n惹出浑身疥。\n\n款款细搜求，日月年时赛。遂得中央四宝珠，禄马快。\n\n走入关西界。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄鹤洞仙' AND p.poem_author = '王哲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('看海南人过年', '陈振家', '当代', '纳新送旧各张罗，或杀阉鸡或大鹅。香饭能供诸路客，美醪可醉百颜酡。\n\n鲜衣贺岁妆儿女，爆竹迎春积笸箩。坐守元辰交正点，看谁燃放炮声多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '看海南人过年' AND p.poem_author = '陈振家';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('从军行八首 其一', '王世贞', '明代', '蹋臂归来六博场，城中白羽募征羌。相逢试解吴钩看，已是金河万里霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '从军行八首 其一' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄谢无逸', '汪革', '宋代', '问讯江南谢康乐，溪堂春木想扶疏。高谈何日看挥麈，安步从来可当车。\n\n但得丹霞访庞老，何须狗监荐相如。新年更励于陵节，妻子同锄五亩蔬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄谢无逸' AND p.poem_author = '汪革';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阳羡寒辞和张椒卿六首 其四', '孙原湘', '清代', '解画开元桂叶蛾，能酬主簿定情歌。寻常一朵红兰影，已胜粗桃俗李多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阳羡寒辞和张椒卿六首 其四' AND p.poem_author = '孙原湘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('明发鸭步', '杨万里', '宋代', '雨岁春船各一时，今年船快去年迟。\n青山面目何曾改，清晓看来别样奇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '明发鸭步' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苏台竹枝词 一十首', '杨维桢', '元代', '馆娃宫中麋鹿游，西施去泛五湖舟。\n香魂玉骨归何处，不及贞娘葬虎丘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苏台竹枝词 一十首' AND p.poem_author = '杨维桢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('马山杂咏三十韵 其一', '成鹫', '明代', '来牛去马任西东，云月溪山各异同。莲社久虚清论地，槐花多笑白头翁。\n\n前窗破梦三更雨，隔案翻书六月风。群动自喧吾自寂，时人休道是顽空。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '马山杂咏三十韵 其一' AND p.poem_author = '成鹫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜静', '胤禛', '清代', '星汉斜临避暑宫，石栏干曲绿阴笼。风回岩畔泉声咽，夜静人闲月镜空。\n\n绕砌兰薰香馥郁，满壶冰洁玉玲珑。隔帘漏断天如洗，新句吟成一枕中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜静' AND p.poem_author = '胤禛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢江东耿漕曼老寄书并与沈侍郎唱和诗谢诒书', '杨万里', '宋代', '碧落侍郎金作句，瀛州学士玉为章。\n两公唱和君知麽，个是安期却老方。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢江东耿漕曼老寄书并与沈侍郎唱和诗谢诒书' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大隐楼为妹夫罗宗信赋', '周巽', '元代', '卜居栖迹在城南，朝市纷纭不肯谈。树下鹤归唯见一，花前凤舞自成三。\n\n窗含远岫明如玉，槛俯长江秀似蓝。身在耆英图画里，酡颜日日带春酣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大隐楼为妹夫罗宗信赋' AND p.poem_author = '周巽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('醉石次韵', '邵宝', '明代', '太湖之南多秀峰，湖船偶载过莲蓉。何当移至三峰下，参我千年双古松。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '醉石次韵' AND p.poem_author = '邵宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('人情吟', '邵雍', '宋代', '人达人情，无寡无广。\n天下之事，如指诸掌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '人情吟' AND p.poem_author = '邵雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东屯溪山之胜似吾家左原', '王十朋', '宋代', '东屯别是一山川，水秀山青似左原。我待还家筑茅屋，作诗招取少陵魂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东屯溪山之胜似吾家左原' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('昭君怨', '刘氏（王淑英妻）', '南北朝', '一生竟何定，万事良难保。丹青失旧仪，匣玉成秋草。\n\n相接辞关泪，至今犹未燥。汉使汝南还，殷勤为人道。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '昭君怨' AND p.poem_author = '刘氏（王淑英妻）';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('论邻人', '陆游', '宋代', '邻曲有米当共舂，何至一旦不相容？为善何尝分士农，尧民皆当变时雍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '论邻人' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('军中行', '陈宗傅', '宋代', '胡马出幽燕，风尘起北陬。\n天兵偶不利，王气黯然收。\n六龙守沙漠，谁复为报仇。\n耿耿孤臣衷，长怀麦秀忧。\n回首望京阙，血泪相和流。\n安得众猛士，尽如穰苴俦。\n戳力共厮分，枭取可汗头。\n扫清犬羊群，釐复旧神州。\n奇功勒燕石，芳名播千秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '军中行' AND p.poem_author = '陈宗傅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('客自邵武来言王野使君平寇 其二', '戴复古', '宋代', '太守自监军，片胆大如身。立马斩数贼，犒军捐万缗。\n\n威行千里外，手活一城民。孰谓书生怯，书生中有人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '客自邵武来言王野使君平寇 其二' AND p.poem_author = '戴复古';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('觉报长老道谌写予兄弟真求赞次七兄韵', '周必大', '宋代', '身凡心圣古卢能，未着袈裟已是僧。\n冷暖自知师莫问，但看老色几分增。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '觉报长老道谌写予兄弟真求赞次七兄韵' AND p.poem_author = '周必大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感春十三首 其一', '张耒', '宋代', '春郊草木明，秀色如可揽。雨馀尘埃少，信马不知远。\n\n黄乱高柳轻，绿铺新麦短。南山逼人来，涨洛清漫漫。\n\n人家寒食近，桃李暖将绽。年丰妇子乐，日出牛羊散。\n\n携酒莫辞贫，东风花欲烂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感春十三首 其一' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹊桥仙十四首 其七', '添雪斋', '当代', '于无情处，吾无忧矣，俗世因何再返？五湖秋梦未如前，只看那、云舒又卷。\n\n观之往昔，知之来日，纵有清心也远。千年残月不堪眠，却照向、西风庭院。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹊桥仙十四首 其七' AND p.poem_author = '添雪斋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送吕宪帅维扬', '喻良能', '宋代', '读我宋实录，元丰治明昌。\n五年九月中，上特开天章。\n从容谓辅臣，边民疲可伤。\n吕独为腾言，他人终未尝。\n已乃命正献，由定帅维扬。\n学士加大称，庸以示宠光。\n移镇未去久，趣归总台纲。\n尔来九十年，谁其踵遗芳。\n我公嫡孙行，祖烈蔚载扬。\n持节古闽粤，摄事今福唐。\n仁风杂和气，盎盎如春阳。\n甿谣玉律响，圜扉春草长。\n英声飞九重，御屏书益详。\n广陵大都会，经理须才良。\n拥麾往镇之，非公廪谁当。\n延阁升宝书，恩纶湛洋洋。\n左符分淮海，西顾宽岩廊。\n想见入境初，快睹争星凰。\n折冲向樽俎，宣威谢金汤。\n行看有锋召，衮衣侍虞皇。\n贱子一何幸，窃庇逾两霜。\n误蒙剡荐牍，名彻凝旒傍。\n受恩未知报，肝胆徒激昂。\n唯祈转洪钧，复立弟子行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送吕宪帅维扬' AND p.poem_author = '喻良能';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('松石台', '潘纬', '唐代', '倚松踞磐石，无伴坐亦好。\n不信石无尘，松风与洒扫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '松石台' AND p.poem_author = '潘纬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水龙吟·人生何必求名', '萧元之', '宋代', '人生何必求名，身闲便是名高处。卧云衣袂，何因自染，修涂尘土。世路羊肠，人情狙赋，翻云覆雨。把从前旧梦，倚阑重省，休更错、添笺注。况是吾庐江上，也抵得、封侯千户。高眠闲听，邻舟渔唱，倚阑农语。休望当年，溪边俱载，隆中三顾。怕群鸥微觉，见人欲起，背人飞去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水龙吟·人生何必求名' AND p.poem_author = '萧元之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书隐', '梁兰', '明代', '深居罕尘杂，经史纷前陈。至道邈难闻，先民有遗言。\n\n贱贫素其行，贵富良在天。掩帙起长叹，逍遥盼庭前。\n\n以兹寡外慕，形役奚由牵。昭代等唐虞，宵衣亟徵贤。\n\n及时策芳名，讵云甘自捐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书隐' AND p.poem_author = '梁兰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚春郊外七首 其七', '李昌祺', '明代', '笔砚图书且暂停，寻芳聊傍水边行。禁烟巷陌偏伤雨，修禊天时不厌晴。\n\n堤柳折来怜色嫩，野棠开处爱香清。南朝旧日歌钟地，烟草萋迷晚照明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚春郊外七首 其七' AND p.poem_author = '李昌祺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自杨厍夜归华墅', '陆祖瀛', '清代', '西山日落已无痕，露湿罗衫渐减温。历碌驹轮走清夜，零星萤火照黄昏。\n\n月明松径僧归寺，云护溪林犬吠村。入室挑灯咸问讯，渔人空说武陵源。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自杨厍夜归华墅' AND p.poem_author = '陆祖瀛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菊花 其十一', '黄毓祺', '清代', '平远荒寒木叶稀，秋容不战自然肥。忽惊身在芦花岸，耳畔萧萧有雁飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菊花 其十一' AND p.poem_author = '黄毓祺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('双双燕·咏燕', '史达祖', '宋代', '过春社了，度帘幕中间，去年尘冷。差池欲住，试入旧巢相并。还相雕梁藻井。又软语、商量不定。飘然快拂花梢，翠尾分开红影。 \n芳径。芹泥雨润。爱贴地争飞，竞夸轻俊。红楼归晚，看足柳昏花暝。应自栖香正稳。便忘了、天涯芳信。愁损翠黛双蛾，日日画阑独凭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '双双燕·咏燕' AND p.poem_author = '史达祖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵江南感事', '苏颂', '宋代', '京洛倦游后，江南感慨多。\n壮怀伤岁月，醉眼小山河。\n无路通谈说，穷年谩揣摩。\n知音如有遇，终采击辕歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵江南感事' AND p.poem_author = '苏颂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游赤松宫二首 其一', '叶颙', '元代', '杖履策天风，桃源路万重。草藏羊化石，云护鹤巢松。\n\n药化留丹井，莲开老翠峰。初平与初起，吾亦愿相从。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游赤松宫二首 其一' AND p.poem_author = '叶颙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢氏祖孙创澧阳桥', '陈旅', '元代', '涔阳极目云气昏，冲风扬波鼍窟翻。湘妃抱琴望虞舜，日暮江竹多啼痕。\n\n木兰为舟不可渡，谁幻层渊作平路。天横夜静牛渚长，海市朝晴蜃楼吐。\n\n祖孙移山山可移，昔人不信今见之。千年犹有召伯埭，白面聚敛嗟何为。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢氏祖孙创澧阳桥' AND p.poem_author = '陈旅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春夜', '余菊庵', '当代', '卧听窗前飒飒风，怯寒衾薄过头蒙。宵深小阁四邻静，短梦惊回细雨中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春夜' AND p.poem_author = '余菊庵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西溪冬夜', '曾协', '宋代', '并埋松柏与云齐，月夜青山一望低。\n山鸟不惊人迹绝，步随流水到前溪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西溪冬夜' AND p.poem_author = '曾协';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送钱子虚抚干往洪州赴新任二首 其一', '吕本中', '宋代', '君不求时用，居然如病夫。经过阅岁月，相伴走江湖。\n\n白玉终无玷，寒松保不枯。同官多胜士，总为致区区。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送钱子虚抚干往洪州赴新任二首 其一' AND p.poem_author = '吕本中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送张师道', '俞德邻', '宋代', '七闽幕府藉词臣，一笑平反草木春。制下九重新涣汗，胸蟠千古旧经纶。\n\n生平耻不为伊傅，夜半何烦问鬼神。无限焦枯待霖雨，好将斯道觉斯民。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送张师道' AND p.poem_author = '俞德邻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古耶道中有怀', '陈宪章', '明代', '翠烟浮垅麦初齐，社树青青独鸟啼。\n何处相思不相见，木绵花下水门西。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古耶道中有怀' AND p.poem_author = '陈宪章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('太平瑞圣花', '范成大', '宋代', '雪外扪参岭，烟中濯锦洲。\n密攒文杏蕊，高结彩云球。\n百世嘉名重，三登瑞气浮。\n挽春同住夏，看到火西流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '太平瑞圣花' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠林赞虞侍郎', '郑孝胥', '清代', '我朝二百年，未尝用闽士。闽人入军机，有之自公始。\n\n公虽负清望，峭直素难比。特擢由圣明，此外更何恃。\n\n孤立固甚危，诡随亦吾耻。愿先收人心，以此立宗旨。\n\n用人与行政，切忌犯不韪。但令识轻重，缓急差可倚。\n\n亦莫太矫激，徐徐布条理。朋党兆已萌，勿使祸再起。\n\n时艰至此极，任重宁足喜。连宵语月下，含意深无底。\n\n惟将忧国涕，珍重付江水。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠林赞虞侍郎' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉陪郑驸马韦曲二首 其二', '杜甫', '唐代', '野寺垂杨里，春畦乱水间。美花多映竹，好鸟不归山。\n\n城郭终何事，风尘岂驻颜。谁能共公子，薄暮欲俱还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉陪郑驸马韦曲二首 其二' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白云峰', '杨蟠', '宋代', '万顷田间雨，多从顶上生。\n野人犹不足，常拟凿为平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白云峰' AND p.poem_author = '杨蟠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月', '王千秋', '宋代', '璀璨雕笼洒笔，联翩荐鹗飞书。翻阶红药试妆梳。管取不言温树。 \n 容我一杯为寿，看君九万鹏图。髻鬟人小串珠玑。岁岁绿窗朱户。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月' AND p.poem_author = '王千秋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('用韵答樗庵老兄兰室乡友二首 其二', '黄淮', '明代', '兰室生春万绿铺，乘閒相过每携壶。拔茅已喜曾连茹，失足殊怜久噬肤。\n\n爱子美如青玉案，嗟予老似白头乌。升沈此去应难定，莫使平生志愿孤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '用韵答樗庵老兄兰室乡友二首 其二' AND p.poem_author = '黄淮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洛阳诗帖 其二', '蔡襄', '宋代', '洛阳风景实堪珍，到此经今三纪春。无限欢娱荣乐事，一时回施少年人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洛阳诗帖 其二' AND p.poem_author = '蔡襄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晓过淮阴', '张羽', '明代', '军城铁锁晓开关，使节星驰未敢闲。\n淮水东流应到海，瓜洲北去少逢山。\n行人欲断寒烟外，远烧时明乱苇间。\n却忆帝城风物盛，礼成须及上春还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晓过淮阴' AND p.poem_author = '张羽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鬲溪梅令 题林岳威梅边读易图', '杨玉衔', '清代', '天机三十六宫春。幻梨云。香浸一尊，波绿欲生鳞。\n\n微吟醒醉魂。\n\n玉梅骨干雪精神。个中人。恍惚翠禽，声里唤真真。\n\n天花黏著身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鬲溪梅令 题林岳威梅边读易图' AND p.poem_author = '杨玉衔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('都督王公阅兵海上歌 其七', '李云龙', '明代', '雨过连营月满篷，一声清啸倚秋风。惊波不动江如练，东望扶桑欲挂弓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '都督王公阅兵海上歌 其七' AND p.poem_author = '李云龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答陈舜俞推官惠诗求全瓦古砚', '韩琦', '宋代', '邺宫废瓦埋荒草，取之为砚成坚好。求者如麻几百年，宜乎今日难搜讨。\n\n吾邦匠巧世其业，能辨环奇幼而老。随材就器固不遗，大则梁栋细棼橑。\n\n必须完者始称珍，何殊巨海寻三岛。荆人之璧尚有瑕，夏后之璜岂无考。\n\n况乎此物出坏陶，千耕万斸常翻搅。吾今所得不专全，秘若英瑶藉文缫。\n\n君诗苦择未如意，持赠只虞咍绝倒。君不见镇圭尺二瑁四寸，大小虽异皆君宝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答陈舜俞推官惠诗求全瓦古砚' AND p.poem_author = '韩琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游岘山次韵三首 其二', '陈与义', '宋代', '高人买山隐，百万犹恨少。客儿最省事，有屐一生了。\n\n东庄良不遥，十里望缥缈。萦纡并麦垄，翠浪四山绕。\n\n先生滞鹿车，去程通凤沼。暂来山泉上，思与飞云杳。\n\n云北接云南，一径绝纷扰。竹林怀风雨，目断极窈窈。\n\n从来无世尘，相对真不挠。龙儿争地出，头角已表表。\n\n先生嘱支郎，勿使斤斧夭。终当乞一杖，险路扶吾老。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游岘山次韵三首 其二' AND p.poem_author = '陈与义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早春阁下寓直萧九舍人亦直内署因寄书怀四韵', '杜牧', '唐代', '御水初消冻，宫花尚怯寒。\n千峰横紫翠，双阙凭栏干。\n玉漏轻风顺，金茎淡日残。\n王乔在何处，清汉正骖鸾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早春阁下寓直萧九舍人亦直内署因寄书怀四韵' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('歙砚', '林敏修', '宋代', '瑟瑟方池雾縠纹，麝烟初散墨花春。晴窗昼静桐阴转，笔下云生字入神。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '歙砚' AND p.poem_author = '林敏修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔家傲（赠鼎湖官妓）', '李石', '宋代', '西去征鸿东去水。几重别恨千山里。梦绕绿窗书半纸。何处是。桃花溪畔人千里。 \n 瘦玉倚香愁黛翠。劝人须要人先醉。问道明朝行也未。犹自记。灯前背立偷弹泪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔家傲（赠鼎湖官妓）' AND p.poem_author = '李石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和唐寿隆上元五首 其四', '胡寅', '宋代', '山褰云色暗阳台，俄复晨曦万里开。行雨忽随新梦断，春风还似故人来。\n\n精神总属陶潜柳，燮理须归傅说梅。已共此邦同乐岁，更须躬稼辟田莱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和唐寿隆上元五首 其四' AND p.poem_author = '胡寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('即席分赋得卖花声', '黄景仁', '清代', '摘向筠篮露未收，唤来深巷去还留。一堤杏雨寒初减，万枕梨云梦忽流。\n\n临镜不妨来更早，惜花无奈听成愁。怜他齿颊生香处，不在枝头在担头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '即席分赋得卖花声' AND p.poem_author = '黄景仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赋未见君子忧心靡乐八韵寄李载', '黄庭坚', '宋代', '古人有成言，岁暮于吾子。\n斧挥郢人鼻，琴即锺期耳。\n新诗凌建安，高论到正始。\n徒言参隔辰，未负石投水。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赋未见君子忧心靡乐八韵寄李载' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿福泉寺书与𥢗上人', '陈煇', '明代', '蜀僧出世在空门，心迹超然离垢氛。欲问安禅最幽处，一潭秋月半山云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿福泉寺书与𥢗上人' AND p.poem_author = '陈煇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李封君兄弟承恩图', '卢龙云', '明代', '余视世间人，岂无兄及弟。荣瘁间同根，具迩殊廉陛。\n\n式好任埙篪，名实不堪礼。宦达即齐名，参商逐旅邸。\n\n闽海多贤豪，二老表林皋。诗书敦夙尚，水石美游遨。\n\n友爱念弥笃，乡闾慕转高。辞荣乐丘贲，家声起誉髦。\n\n令德宜寿岂，锦衣炫庭綵。同时荷紫纶，皇恩深若海。\n\n锡服相辉鲜，素澹元无改。雏驹总凤龙，移忠未休怠。\n\n粤徼已澄清，屏翰出江城。观风过海岱，齐鲁遍诸生。\n\n风雨对床夜，池塘梦草情。教仕迭跻膴，黄发逮三旌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李封君兄弟承恩图' AND p.poem_author = '卢龙云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬薛员外谊见戏一首', '皎然', '唐代', '方知正始作，丽掩碧云诗。文彩盈怀袖，风规发咏思。 \n 遗弓逢大敌，摩垒怯偏师。频有移书让，多惭系组迟。 \n 浅才迂且拙，虚誉喜还疑。犹倚披沙鉴，长歌向子期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬薛员外谊见戏一首' AND p.poem_author = '皎然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('就藏上人乞花木栽草堂前戏效少陵体 其四', '李锴', '清代', '海棠更倚断坪西，带雨凌风一向低。莫止留连众香国，也应点染浣花溪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '就藏上人乞花木栽草堂前戏效少陵体 其四' AND p.poem_author = '李锴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戊辰长安感述七首 其六', '黎遂球', '明代', '燕市谁言侠烈多，绿杨桥畔只鸣珂。曾闻莽室群称颂，不见屠门醉和歌。\n\n所赖腐儒能赴鼎，即看神武立还阿。伤心莫叹先朝事，寂寂寒蝉意为何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戊辰长安感述七首 其六' AND p.poem_author = '黎遂球';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('隆兴书堂自警三十五首', '陈淳', '宋代', '今日一念差，不即伐以柯。\n明日又重生，心熟将如何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '隆兴书堂自警三十五首' AND p.poem_author = '陈淳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诗勉及门赴海棠之约', '吴芾', '宋代', '君与吾游积有年，未曾同醉海棠前。\n如今君乃先春到，似赴花朝岂偶然。\n已是诗中参造化，何妨花里见神仙。\n暂归莫负重来约，未及春风便着鞭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诗勉及门赴海棠之约' AND p.poem_author = '吴芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百二十三首 其十二', '释崇岳', '宋代', '妙用纵横，十方坐断。未谙此脉，举步犹难。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百二十三首 其十二' AND p.poem_author = '释崇岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('去通义按刑汉嘉至中岩师伯浑临别于此因成二', '晁公溯', '宋代', '惭愧居士屩，远来尊者岩。\n深知烦露宿，径为落风帆。\n潭净鱼堪唤，花残鹿罢衔。\n堂中有耆老，禅病说呢喃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '去通义按刑汉嘉至中岩师伯浑临别于此因成二' AND p.poem_author = '晁公溯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和吴伯玉九日同会', '刘弇', '宋代', '上林曾共见莺迁，五百英豪气戾天。斗在并存嗟白发，成空半已锁黄泉。\n\n菊花酩酊同今日，桂籍风流记旧年。愧辱新诗无以报，误烦褒笔比青钱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和吴伯玉九日同会' AND p.poem_author = '刘弇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绝句六十四首', '张伯端', '宋代', '四象会时玄体就，五行全处紫金明。\n脱胎入口通身圣，无限龙神尽失惊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绝句六十四首' AND p.poem_author = '张伯端';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('更乞百叶一种', '郭之奇', '明代', '珍重当年禁苑春，助娇消恨旧何人。风流争似潘郎得，付与河阳满县新。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '更乞百叶一种' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('台城路 感怀', '鲍之芬', '清代', '梦中冉冉韶华度，情怀迥非畴息。命也如何，时哉不与，底事十年为客。\n\n人情阅历。叹火暖冰寒，自怜心迹。莫怪东风，岭梅枝各向南北。\n\n真言不醒顽石。纵诗书千卷，何用今日。庸福如人，虚名老我，半世穷愁消得。\n\n青衫泪湿。恨瑟柱添胶，琴材被炙。厚薄前因，料难增寸尺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '台城路 感怀' AND p.poem_author = '鲍之芬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('疏影六首 其一', '蒋敦复', '清代', '黄花瘦矣。卷西风一桁，和梦吹起。庭院深深，挂在月明，谁家今夜秋思。\n\n明河不隔玲珑望，怕瞒了、双星密誓。曳缟衣、荡冷琉璃，滴碎凤绡清泪。\n\n疑向瑶台路入，把珍珠晓揭，尚带霞气。十二琼扉，瞥见横波，刚近日高梳洗。\n\n非烟非雾情无着，浑织就、鸳愁如水。待燕归、诉与相思，越恁翠沈沈地。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '疏影六首 其一' AND p.poem_author = '蒋敦复';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('武陵春·日醍醐长灌顶', '王哲', '元代', '日醍醐长灌顶，丙反相亲。有琼浆与玉津。火养精神。地醒来寅地醉，九按三巡。子於金得味＊。赏武陵春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '武陵春·日醍醐长灌顶' AND p.poem_author = '王哲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湖州天宁寺饮王生二首 其二', '孙觌', '宋代', '诸家迹便扫，得此一老兵。江东醉司马，酒中尚求名。\n\n哀哉南山萁，不平自号鸣。慎勿歌乌乌，作此老婢声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湖州天宁寺饮王生二首 其二' AND p.poem_author = '孙觌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄刘凝远丈二首 其二', '赵蕃', '宋代', '水云痛饮玉光诗，胜践那容俗子知。此乐祇今宁梦见，临风空尔费怀思。\n\n苏门长啸谁能和，赤壁成功顾已迟。当日唱酬谁复与，皆云骥子好男儿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄刘凝远丈二首 其二' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('投龙宝室洞天过延庆观方王卒共父剑峰精舍', '程公许', '宋代', '璧简荐宝室，襟裾馥旃檀。\n眷言石交旧，可惮脚力酸。\n层岩一剑裂，阴壑千古寒。\n数椽棲泬寥，小楼面赞元。\n风穴激虎啸，石洞掀龙蟠。\n是日朔吹惨，兵团空雪花漫。\n开尊聊暖热。毛苡劝加餐。\n心事喜我同，晤言蔼清欢。\n欲去有余恋，小驻搜奇观。\n评画过神品，誓死鬼犹故坛。\n君家丛城，甲第一亩宽。\n胡独嗜幽寂，而乐兹考盘。\n戍邱渐相迫，住山殊示安。\n春风动卒马，云霄插双翰。\n傥念猿鹤怨，无多贪热官。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '投龙宝室洞天过延庆观方王卒共父剑峰精舍' AND p.poem_author = '程公许';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古三十一首', '释原妙', '宋代', '无端平地起干戈，争似属牛人更多。\n满面惭惶无著处，低头依旧入烟萝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古三十一首' AND p.poem_author = '释原妙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('曾珣五真图诗 其一 第一图', '姚燮', '清代', '紫澜接春峤，霞蕤如玉鬈。珠童夙姣好，倚凤挥锦弦。\n\n香疏绿华昵，梦小青要怜。劫深遭绮罚，灵蜕投大千。\n\n凌风带飘荔，剪月巾侧莲。飞魂渡弱水，弹指沧桑迁。\n\n茫茫万蛟蜃，我与谁周旋？回睐白云杪，琼梯星钩连。\n\n才人堕尘壒，天上无神仙。勿因衣狗扰，殉智迷宿缘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '曾珣五真图诗 其一 第一图' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('休日留园中至暮乃归', '陆游', '宋代', '尽道官身属太仓，未妨寄傲向林塘。\n绿波春涨群鱼乐，清露晨流蔓草香。\n闲试名弓来射圃，醉盘骄马出球场。\n长城万里知谁许，看镜空悲两鬓霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '休日留园中至暮乃归' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和石邻闺情三首 其一', '缪鸿若', '近代', '明灯促坐话深宵，待我诗成拥翠翘。一事语郎须记取，不封侯去也魂销。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和石邻闺情三首 其一' AND p.poem_author = '缪鸿若';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙（次秀野酴醿韵）', '朱熹', '宋代', '压架年来雪作堆。珍丛也是近移栽。肯令容易放春回。却恐阴晴无定度，从教红白一时开。多情蜂蝶早飞来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙（次秀野酴醿韵）' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五月二十一日徙寓智门二首', '赵蕃', '宋代', '来归迨一载，借屋已三迁。\n易觉林间寺，难求郭外田。\n瓶储朝乏粟，市籴日增钱。\n屡起瞻云汉，今年甚去年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五月二十一日徙寓智门二首' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过梅岭', '冯绍京', '明代', '丞相遗祠倚岭岐，古松苍桧荫参差。千年灵淑钟光岳，一代勋名勒鼎彝。\n\n金鉴若悬龙扆照，玉环何至马嵬悲。开元旧事如追忆，羽扇清风是表仪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过梅岭' AND p.poem_author = '冯绍京';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('呈湖州赵再可舍人二首', '张嵲', '宋代', '五云螭陛旧仙翁，来往琉璃一色宫。\n未到行人已能说，使君清与霅溪同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '呈湖州赵再可舍人二首' AND p.poem_author = '张嵲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塞上杂歌赠赵总制 其八', '黄廷用', '明代', '古来天子重边愁，秦筑长城瀚海头。百二山河悬六镇，报恩不敢说封侯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塞上杂歌赠赵总制 其八' AND p.poem_author = '黄廷用';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送赵普', '赵炅', '宋代', '忠勤王室展宏谟，政事朝堂赖秉扶。解职暂酬卿所志，休教一念远皇都。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送赵普' AND p.poem_author = '赵炅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('览太素新编', '田锡', '宋代', '蜀国香笺似彩霞，装成近集入京华。\n千篇诗好精灵哭，百轴文雄侠少夸。\n繁富禹皇新职贡，妍明春帝晓莺花。\n彤庭何处安排好，李谪仙才称草麻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '览太素新编' AND p.poem_author = '田锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送王奏差调福州', '泰不华', '元代', '春水溶溶满鉴湖，兰舟长护锦屠苏。可怜走马闽山道，榕叶阴中听鹧鸪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送王奏差调福州' AND p.poem_author = '泰不华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('客里', '严粲', '宋代', '客里还来此，寒灯耿独吟。一官江国梦，十载草堂心。\n\n木落秋声小，蛩孤夜思深。驱驰空自许，冉冉鬓霜侵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '客里' AND p.poem_author = '严粲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('嘉祐寺', '张九成', '宋代', '曳屣出南郭，招提在高冈。谁言林樾中，乃有此宝坊。\n\n甘泉溢中庭，修桂荫层廊。三秋此花开，清香驻高堂。\n\n试问红尘中，那得六月凉。门外江声急，堂中松韵长。\n\n古殿俨像设，佛灯龛夜光。不见堂中人，斗觉心悲伤。\n\n人生本无定，乐处是吾乡。吟馀复何事，月落山苍苍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '嘉祐寺' AND p.poem_author = '张九成';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('追怀陈缄斋', '郑孝胥', '清代', '风味缄斋致最优，眼中何处著时流。逢场未减清狂概，带醉偏寻寂寞游。\n\n双鬓早衰缘骨肉，孤儿谁托指山邱。软尘丁郑还相见，宿草年年泪不收。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '追怀陈缄斋' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古十三首', '释德光', '宋代', '丧尽生涯卖笊篱，白拈火里讨便宜。\n看来枝节只如此，也道心空及第归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古十三首' AND p.poem_author = '释德光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴推官权永丰', '韩淲', '宋代', '乾封摇落西风起，忽忆故人何处诗。白发居头空自笑，青山到眼望都疑。\n\n寻常莲幕知难近，邂逅弦歌岂易为。若见赵舒烦问讯，晚禾方得雨垂垂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴推官权永丰' AND p.poem_author = '韩淲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅坡卷 其二', '符锡', '明代', '十里山亭一径回，小梅无恙绕亭开。巡檐猛可闻双喜，疑有探花人到来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅坡卷 其二' AND p.poem_author = '符锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贺道士阮太虚', '谢枋得', '宋代', '阮郎正好住天台，玉女多情忽放回。雨散云收一天碧，薰风吹梦到瑶台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贺道士阮太虚' AND p.poem_author = '谢枋得';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬至县中行庆贺礼', '程敏政', '明代', '圣诞才过至日来，礼成遥贺两叨陪。銮舆恍接清光近，谯鼓频催曙色开。\n\n万寿喜从天上祝，一阳初自地中回。云占乡国应多瑞，拟上城东百尺台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬至县中行庆贺礼' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沙渍道中', '耶律铸', '元代', '去年寒食在天涯，寒食今年又别家。天北天南人万里，春风开尽马莲花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沙渍道中' AND p.poem_author = '耶律铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阴阳书语', '佚名', '唐代', '乔木先枯，众子必孤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阴阳书语' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乌鹊吟', '释函是', '明代', '乌鹊声嘈嘈，飞上飞下不离树上巢。树杪畏风吹，风吹犹自可，低树蛇侵无处躲。\n\n去年逐一雏，今年吞卵巢几破。乌鹊那，人情物理一等招因果。\n\n勿贪沙边鱼，林间岸畔自死虫蛙随时过。养成毛翮健且长，旷大虚空一任东冲西突何曾奈得我。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乌鹊吟' AND p.poem_author = '释函是';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('残腊四首录二 其二', '佟绍弼', '近代', '阅世辜初愿，为家尚故乡。悠闲知苦味，忍死可佯狂。\n\n滴泪人频怪，诗怀时自伤。如何用幽意，引梦到羲皇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '残腊四首录二 其二' AND p.poem_author = '佟绍弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('槐野王太史原韵', '黄廷用', '明代', '由来卜筑避天街，此日幽栖意更谐。无客蓬蒿从满径，有时鸟雀自驯阶。\n\n云中歌鼓五侯第，塞上旌旗千里怀。闭户著书愁未得，傍人休拟草玄斋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '槐野王太史原韵' AND p.poem_author = '黄廷用';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('崇庆牧常公殉节诗 其二', '邓为纲', '清代', '昔岭当年事已非，蜀山蜀水不胜悲。后人凭吊忠魂处，共道持戈跃马时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '崇庆牧常公殉节诗 其二' AND p.poem_author = '邓为纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('来鹤诗赠周玄初', '徐良言', '明代', '九天执法大玄卿，稽首焚香礼玉京。\n借得魏君骐骥到，恰如萧史凤鸾鸣。\n翩翩绕树香烟近，历历横江夜气清。\n欲向群中留一只，相将过海到蓬瀛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '来鹤诗赠周玄初' AND p.poem_author = '徐良言';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书感', '林占梅', '清代', '钻纸纷纷笑冻蝇，年来兴趣冷于冰。广交已觉迎人苦，习静翻招傲物称。\n\n琴韵逸宜林下客，诗心苦似定中僧。且将白眼青天望，俗论悠悠任爱憎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书感' AND p.poem_author = '林占梅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('迈陂塘/摸鱼儿·天海移情图为周澹岩作', '姚燮', '清代', '指回澜、金乌弄彩，搏桑万里初晓。十年苦识琴三昧，赢却者回孤抱。\n\n中散老。恐一曲广陵，难媚人间好。刺船行早。等独鹤摩天，片云吹海，直得赏音少。\n\n龙门峻，何处丹壶青峤。弱流飞渡难到。玉鸾笙语云和叶，一霎环风迷渺。\n\n归去好。恁捻个鱼竿，要拂珊瑚钓。桐心未槁。但秋月春花，得闲消领，随地是蓬岛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '迈陂塘/摸鱼儿·天海移情图为周澹岩作' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寓龙虎山示张炼师', '王镃', '宋代', '莲盂送别万峰云，龙虎山前过小春。\n草履惯穿枯岭叶，布衣犹带旧京尘。\n毡寒不见游仙梦，路远谁怜倦客贫。\n东望海门归未得，北风吹雪满唐巾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寓龙虎山示张炼师' AND p.poem_author = '王镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('余家藏道复水墨牡丹纷披老笔而扇头折枝浅绛丰肌曼色嫣然袭人更题一绝于便面右', '胡应麟', '明代', '谁写天真第一枝，盈盈霞色照轩墀。多情错认杨妃醉，亭倚沉香日暮时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '余家藏道复水墨牡丹纷披老笔而扇头折枝浅绛丰肌曼色嫣然袭人更题一绝于便面右' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('光宣杂咏 其二十四', '冒效鲁', '近代', '闲坊夜夜倒春缸，晚翠才人气未降。三十倘酬公辅望，异才奇祸总无双。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '光宣杂咏 其二十四' AND p.poem_author = '冒效鲁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('武定女官凤索林领兵先至军容壮甚余喜之因成长句', '胡庭兰', '明代', '修戟真能不后期，佩刀还喜陆剸犀。貔貅步下风云壮，娘子军前号令齐。\n\n川涌惊雷原野动，山苞含雾塞天低。即看灭此方朝食，扫穴翻营日未西。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '武定女官凤索林领兵先至军容壮甚余喜之因成长句' AND p.poem_author = '胡庭兰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('欲归', '赵吉士', '清代', '暮角吹斜鬓，菰莼佐客饔。云移新雨月，霜敛近秋松。\n\n谷口清岚染，岩尖紫翠缝。欲归归未得，残照曳疏筇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '欲归' AND p.poem_author = '赵吉士';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和西湖竹枝词二首 其二', '陆仁', '元代', '郎别心绪乱如麻，孤山山角有梅花。折得梅花赠郎别，梅子熟时郎到家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和西湖竹枝词二首 其二' AND p.poem_author = '陆仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和诸君观画鬼拔河', '苏颂', '宋代', '关中古有拔河戏，传闻始盛隋唐世。长絙百尺人两朋，递以勇力相牵制。\n\n芳华乐府务誇大，黎园公卿谩轻肆。拔山扛鼎乌足矜，引绳排根非胜事。\n\n当时好尚人竞习，鬼物何为亦能是。展吴画格入神品，陆法尤长写灵异。\n\n蒲津古寺笔迹奇，世疑二子之𥿡置。旗门双立众鬼环，大石当中坐渠帅。\n\n蓬头圜目互奋踊，植鼓扬桴各凌厉。东西挽引力若停，赋彩自分倾夺势。\n\n画来已历数百年，墙壁岿然今不废。观风使者集贤翁，每游其下几忘味。\n\n因令拓手裂齐纨，横卷传看得形似。精神气韵信瑰诡，毫发轻浓皆彷佛。\n\n持来都下示朋僚，一见飘然动诗思。诸公诗豪固难敌，形容物象尤精致。\n\n气完语健隽众口，二子声名转增贵。予观昔之善画者，心手规模无不至。\n\n穷奇极怪千万端，特出一时之用意。鬼神冥漠不可诘，岂有便能人勇智。\n\n仙官佛像亦如斯，变态随时转奇丽。遂令来者信有说，塔庙从而增侈费。\n\n后贤虽欲究端倪，竟亦无由革颓弊。因知怪诞一崇长，渐靡成风滋巧伪。\n\n兹图他日遂流传，更使人心惑魑魅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和诸君观画鬼拔河' AND p.poem_author = '苏颂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游大涤 其二', '赵善䚮', '宋代', '云葩裛石侵衣润，岚翠笼山入眼明。何处如今有仙隐，愿寻药圃斸玄英。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游大涤 其二' AND p.poem_author = '赵善䚮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庸庵用游半淞园韵见怀次答 其二', '陈三立', '清代', '落魂风月坐，耆旧夜围瓯。灯火摇深念，帘栊锁断愁。\n\n叠吟坚壁垒，老味殉林邱。湖海同听雁，声声博掉头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庸庵用游半淞园韵见怀次答 其二' AND p.poem_author = '陈三立';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('至滇南次答陆进士震韵 其二 谒黔宁王祠', '王缜', '明代', '乘时起淮甸，幼子伴龙眠。单骑来开国，孤忠能补天。\n\n功高盟带砺，名重上淩烟。遗泽千年在，吴南共俨然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '至滇南次答陆进士震韵 其二 谒黔宁王祠' AND p.poem_author = '王缜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('瓶花影与仲诏同赋 其三', '范景文', '明代', '试参象外花，何若人中景。照壁宁非真，折枝仍作影。\n\n谁云嗅有香，意在浓时冷。但当影子观，个中犹未领。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瓶花影与仲诏同赋 其三' AND p.poem_author = '范景文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('公无渡河', '刘孝威', '南北朝', '请公无渡河，河广风威厉。樯偃落金乌，舟倾没犀枻。\n\n绀盖空严祠，白马徒生祭。衔石伤寡心，崩城掩孀袂。\n\n剑飞犹共水，魂沈理俱逝。君为川后臣，妾作江妃娣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '公无渡河' AND p.poem_author = '刘孝威';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('太常引·非僧非俗不求仙', '姬翼', '元代', '非僧非俗不求仙。茅屋两三椽。白石与清泉。更谁问、桃源洞天。一炉香火，一瓯春雪，浇灌净三田。闲想谷神篇。忽不觉、松梢月圆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '太常引·非僧非俗不求仙' AND p.poem_author = '姬翼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('施均父孝廉从军河陇追赠以诗', '董沛', '清代', '高秋匹马赋西征，万里关河壮此行。长揖军门称上客，乱题诗壁有边声。\n\n料量星海番戎界，变置天山郡县城。期尔凌烟书姓氏，他年谁识鲁诸生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '施均父孝廉从军河陇追赠以诗' AND p.poem_author = '董沛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送王覃', '王安石', '宋代', '分走人间十五年，尘沙吹鬓各苍然。山林渺渺长回首，儿女纷纷忽满前。\n\n知子有才思奋发，嗟余无地与回旋。相看一作秦吴别，身世何时两息肩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送王覃' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠赵簿景平二首 其二', '张耒', '宋代', '纷纷俗物久堪憎，爱子萧萧眉宇清。莫叹青衫掩事业，白头卿相死无名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠赵簿景平二首 其二' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('莪默绝句集译笺乙集 其九十五', '伯昏子', '当代', '伤良毁善酒须绝，圣旨监官传两列。既是敬虔之寇雠，天何不许吮其血。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '莪默绝句集译笺乙集 其九十五' AND p.poem_author = '伯昏子';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('閒', '郭之奇', '明代', '时晒渊明巾，日扪子瞻腹。忽从南郭嘘，嗒然形槁木。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '閒' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和刘后村梅花百咏', '方蒙仲', '宋代', '从来芳事无时歇，雨洒风飘且莫悲。\n收拾苍苔成艾紬，茶山后有放翁诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和刘后村梅花百咏' AND p.poem_author = '方蒙仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('从圣国实二茂才叙别', '陆文圭', '宋代', '龙门世爱史学祖，足涉淮湘到乡鲁。\n儿生坠地孤在左，妇闭车中为谁苦。\n二君雁荡游虎林，逆旋二笑论古心。\n地炉画灰事未竟，推窗看天雪意深。\n山寒约共梅花语，江水东流予北去。\n明年春风上石渠，道傍为我中望诸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '从圣国实二茂才叙别' AND p.poem_author = '陆文圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李商老自山北道中作诗见寄次韵', '释德洪', '宋代', '蹇驴醉颊兀红酣，眼艳秋波望翠岚。长向诗中见风度，爱君笔力似黔南。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李商老自山北道中作诗见寄次韵' AND p.poem_author = '释德洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江门舟夜', '何孟伦', '明代', '前村烟树落微茫，待月听潮夜未央。沽酒人家在何处，竹灯明灭隔沧浪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江门舟夜' AND p.poem_author = '何孟伦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('慕耕堂为翟司仪题', '程敏政', '明代', '华扁高堂揭慕耕，当时庭训尚分明。恼人黄犊真无赖，刻志青灯竟有成。\n\n湛露已分天上宠，春风还系陇头情。顾名不废诗书业，更遣遗芳及后生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '慕耕堂为翟司仪题' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿杨给舍宅', '黄衷', '明代', '禁城西畔子云窝，穷客驱羸过玉河。书閤暂来催扫榻，里门曾见号鸣珂。\n\n嬉谈不离文词外，抚事其如岁月何。肯为病容方却饮，南曹风味本无他。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿杨给舍宅' AND p.poem_author = '黄衷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙 江南秋暑特盛，冥想闽中山居景物，赋寄王筱婧明溪', '龙榆生', '近代', '龙眼累累倚夕曛。樵风乍起暮蝉闻。黄云绣垄待尝新。\n\n身健不愁张火伞，岩深徐看涌金盆。丛兰浥露泛奇芬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙 江南秋暑特盛，冥想闽中山居景物，赋寄王筱婧明溪' AND p.poem_author = '龙榆生';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桃源行四首 其一', '胡直', '明代', '断陇横冈苍雾屯，停骖为问古桃源。共言夜半传飞檄，正是当时花竹村。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桃源行四首 其一' AND p.poem_author = '胡直';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄寿宫保大司空潘公', '王世贞', '明代', '淮海仙帆指日悬，燕京优诏自天传。那知岳降生申地，已是河宗献瑞年。\n\n帝赉玄熊因拯世，人夸白马不沉渊。宣房信有如椽笔，能写虞家禹贡篇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄寿宫保大司空潘公' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和林梅臞西淙瀑布图韵', '胡仲参', '宋代', '瀑驶惊风雨，危悬峭壁前。\n临流清客耳，入夜搅幽眠。\n旁是龙为庙，高疑山有仙。\n一尘飞不到，长似九秋天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和林梅臞西淙瀑布图韵' AND p.poem_author = '胡仲参';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠雪山杲公 其一', '广润', '明代', '世有避喧者，往往买山匿。岂不远尘俗，缘心曾未息。\n\n当境即随流，于道竟何益。杲公居市廛，复近金阊陌。\n\n我欲造其庐，几返衡门侧。如何只数武，遍访无人识。\n\n心空世自遗，不在凡嚣隔。相对各忘言，如面少林壁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠雪山杲公 其一' AND p.poem_author = '广润';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵俞东村见示四首 其四 中秋对雨', '董纪', '明代', '今夜平分一半秋，可怜兄弟不同游。片云将雨非无意，天上姮娥亦为愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵俞东村见示四首 其四 中秋对雨' AND p.poem_author = '董纪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('明融', '杨简', '宋代', '妙妙融明乐未央，山川人物献文章。\n纵横组织无边巧，变化委蛇不可商。\n北麓林塘秋塘莹，南山景气晓苍茫。\n欲吟无句方徐步，忽报相从注早香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '明融' AND p.poem_author = '杨简';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和南安余宰题翠阴亭致爽轩二首 其二', '黄公度', '宋代', '面势揖孤峙，交柯藏伯劳。日临公馆寂，人与此轩高。\n\n对酒屡中圣，题诗应仆骚。乔林思旧隐，咫尺听风号。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和南安余宰题翠阴亭致爽轩二首 其二' AND p.poem_author = '黄公度';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风流子 其一', '易顺鼎', '清代', '脆弦调锦瑟，江南客、憔悴惜华年。甚藏秋不住，琴心太窄，逢春欲避，带眼先宽。\n\n更无奈、浮踪飘絮，雪浅梦逗芜烟。听雨旧盟，伴鸥萍海，堕风新劫，骑蝶花天。\n\n前欢浑无据，青衫泪，孤负多少婵娟。一箧红吟蠹尽，俊语都删。\n\n只绣佛量丝，心皈悟后，笺骚费纸，身坠愁边。赢得玉箫声里，吹瘦词仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风流子 其一' AND p.poem_author = '易顺鼎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('误佳期', '宁调元', '清代', '今夜月明如画。一点乡心不下。解衣欲睡复迟回，拟把相思写。\n\n分付与征鸿，又怕庭花谢。不如及早赋归来，万事休粘惹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '误佳期' AND p.poem_author = '宁调元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题新市酒家', '赵蕃', '宋代', '有鱼可漉酒可沽，尔更未知山水娱。\n今晨系缆才须臾，异日回头看画图。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题新市酒家' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿郑州', '王维', '唐代', '朝与周人辞，暮投郑人宿。\n他乡绝俦侣，孤客亲僮仆。\n宛洛望不见，秋霖晦平陆。\n田父草际归，村童雨中牧。\n主人东皋上，时稼绕茅屋。\n虫思机杼悲，雀喧禾黍熟。\n明当渡京水，昨晚犹金谷。\n此去欲何言，穷边徇微禄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿郑州' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('己亥秋日有寄 其一', '陈子升', '明代', '秋鸿翼阵起滇池，上相初隆剑履时。身奉至尊为手足，心惟不二有熊罴。\n\n长江北振灵鼍鼓，驰道西扬翠凤旗。会见收京求鼎实，峤梅辛苦一南枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '己亥秋日有寄 其一' AND p.poem_author = '陈子升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋山望月酬李骑曹', '李峤', '唐代', '愁客坐山隈，怀抱自悠哉。况复高秋夕，明月正裴回。 \n 亭亭出迥岫，皎皎映层台。色带银河满，光含玉露开。 \n 淡云笼影度，虚晕抱轮回。谷邃凉阴静，山空夜响哀。 \n 寒催数雁过，风送一萤来。独轸离居恨，遥想故人杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋山望月酬李骑曹' AND p.poem_author = '李峤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和邓慎思诗呈同院诸公三首 其一', '李公麟', '宋代', '苦学邓夫子，仁风良可依。颜回乐也内，曾点咏而归。\n\n盛德弥年劭，知音贵我稀。潇湘逢此地，咳唾得明玑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和邓慎思诗呈同院诸公三首 其一' AND p.poem_author = '李公麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送绶东归十一首 其八', '王祎', '元代', '客边别我觉惊心，遗汝囊无一寸金。归路迢迢吾颇熟，梦魂随汝到家林。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送绶东归十一首 其八' AND p.poem_author = '王祎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题卢坤峰案上盆兰', '金鉴才', '当代', '买得幽兰三五枝，案头日夕助清思。从来法外神来笔，却道天然是我师。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题卢坤峰案上盆兰' AND p.poem_author = '金鉴才';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠舒司马恭受四十韵', '姚燮', '清代', '公实死后生，未雪道路谤。据迹求是非，舆论几闻当？\n\n海甸今太平，东南扫烟瘴。握剑抒旧怀，苍茫集孤怆。\n\n惟吾素职公，辨品惬尊尚。杶心切露濡，骐首勇云向。\n\n十年官句甬，远鉴纳昭亮。克敏事无偾，鲜越治奚妨？\n\n迨遭兵火危，沿海警剽掠。滃州一弹丸，孤绝势难防？\n\n守土责在公，枕刃百裁量。咄嗟名位卑，计议未容创。\n\n但秉大帅符，遵循学檐傍。一朝决裂成，六日歾三将。\n\n巨澥身拟沈，烈火发先炀。读书明大端，忠义讵艰仗？\n\n群手咸痿痹，安能独扶障？痛眄左右林，鹰隼尽逃飏。\n\n城亡誓与亡，酖酒夙所酿。含笑如饮饴，羁魂听波荡。\n\n膏岂受辱涂，药殊轻死仰。精灵全所归，归骸亦非望。\n\n苦因一息留，拯救受民诳。转以相爱深，陷使公抱枉。\n\n维时民护公，胝趼走穷旷。尚从危命馀，保全万金饷。\n\n后来定功罪，爰书多孟浪。待戮囹圄中，泣拜圣明贶。\n\n益令无知民，猜度起辞让。积泥高过山，竟欲太山葬。\n\n鉴罪获宥生，敛雾出青嶂。拭顶重戴天，煦复挟绵纩。\n\n每抚齿发存，深恩泣未偿。敢于身外名，凛凛竞得丧。\n\n公年长我多，例居丈人行。夙蒙嘘拂加，冰怀匿春盎。\n\n惜公委曲情，于俗难遍状。作诗聊赠公，弗贬小子妄。\n\n诗成烧巨灯，置酒助神王。隔幔铜琶声，金飙挟悲壮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠舒司马恭受四十韵' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹊桥仙', '同恕', '元代', '香飞玉屑，光凝粉蝶。不比精神莹彻。春风一树倚东栏，还称道、仙肌胜雪。\n\n凭谁与说，容吾捡折。老去情缘未歇。□船一棹百分空，直吃到、花梢有月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹊桥仙' AND p.poem_author = '同恕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东溪', '张耒', '宋代', '东溪何潺潺，秋水清见底。\n纵横小石圆，一一静无滓。\n空山人不到，漍漍响环佩。\n我来每终日，漱濯弄清泚。\n山居时已久，不省有朝市。\n门阑人客少，跨马必至此。\n麋鹿见我熟，相对不复起。\n谁知寂寥趣，寄言同声子。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东溪' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('嵩山十二首·玉女捣衣石', '欧阳修', '宋代', '玉女捣仙衣，夜下青松岭。\n山深风霞寒，月杵遥相应。\n露踪杳可寻，片石秋光莹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '嵩山十二首·玉女捣衣石' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵继学途中竹枝词四首 其四', '袁桷', '元代', '阊阖云低接紫宫，水晶凉殿起薰风。侍臣一曲无怀操，能使八方歌会同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵继学途中竹枝词四首 其四' AND p.poem_author = '袁桷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('百志诗', '干宝', '魏晋', '壮士禀杰姿，气烈有自然。俯仰群众中，胡能救世艰。\n\n阙巩代缝掖，兜鍪易进贤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '百志诗' AND p.poem_author = '干宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟不如来饮酒八首 其三', '周宪王', '明代', '攫攘何因尔，终朝傀儡牵。望尘忙趁市，满贯苦多钱。\n\n造物商岩板，羲和穆骏鞭。不如来饮酒，一醉大家眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟不如来饮酒八首 其三' AND p.poem_author = '周宪王';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉和刘晓光先生“风雨重阳忆三公”七律两首 其二', '杨民仁', '近代', '满城风雨近重阳，谈笑江南共一堂。沧阁名园从寄迹，茅台美酒更欣尝。\n\n虞山未到空惆怅，吴地归来犹忆黄。能得明秋身体健，亲携马蟹拜刘郎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉和刘晓光先生“风雨重阳忆三公”七律两首 其二' AND p.poem_author = '杨民仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小春月晤周小山别后叠韵奉寄二首 其二', '徐汝烜', '清代', '气味相亲有几人，知交握手见天真。嗣宗才藻能超俗，叔度襟怀果绝伦。\n\n文阵声名推卓越，诗家格律著精纯。著鞭愧我难追步，辛苦还期共指陈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小春月晤周小山别后叠韵奉寄二首 其二' AND p.poem_author = '徐汝烜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴中迎春曲八首 其三', '王世贞', '明代', '弓鞋罗袜细温存，偏爱春泥印齿痕。看到阊门天欲暝，六街灯月照黄昏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴中迎春曲八首 其三' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汴之水三', '梅尧臣', '宋代', '汴之水，分于河，黄流浊浊激春波。昨日初观水东下，千人走喜兮万人歌。\n\n歌谓何，大船来兮小船过。百货将集玉都那，君则扬舲兮以糺刑科。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汴之水三' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('呈张功甫 其二', '许及之', '宋代', '插来杨柳已梳风，乞与渔师泊短篷。岁晚芦林总摇落，隔湖认得老邻翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '呈张功甫 其二' AND p.poem_author = '许及之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答人寄吴笺', '赵丽华', '明代', '感君寄吴笺，笺上双飞鹊。但效鹊双飞，不效吴笺薄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答人寄吴笺' AND p.poem_author = '赵丽华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏柬刘效忠兵宪', '余继登', '明代', '当年意气请长缨，笑领铜符徼外行。朔漠烽烟朝入塞，汉家都护夜谈兵。\n\n荒城日映旌旗色，古戍风传刁斗声。回首空闺人寂寞，流黄机上月华明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏柬刘效忠兵宪' AND p.poem_author = '余继登';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('嶰林', '刘敞', '宋代', '已看秀色动高林，会见翛翛满翠岑。不学渭川千亩富，欲闻嶰谷凤凰音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '嶰林' AND p.poem_author = '刘敞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('少湖见怀有诗用韵奉酬', '孙承恩', '明代', '江海蹉跎客，风尘蹇拙人。未辞簪绂累，终拟菊松邻。\n\n浅薄承嘉会，幽閒称病身。聊将慎出处，敢谓异群伦。\n\n有美词林彦，无瑕廊庙珍。明时徵凤鸟，绝代见麒麟。\n\n化雨覃江介，清风洒俗尘。文山人仰岱，学海士知津。\n\n远荷金声赠，常怀玉树亲。矢心期佩服，此志敢教沦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '少湖见怀有诗用韵奉酬' AND p.poem_author = '孙承恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('了斋自警六首 其一', '陈瓘', '宋代', '本无一字尧夫易，八十一篇扬子玄。今古是非那复辨，仲尼尤不废韦编。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '了斋自警六首 其一' AND p.poem_author = '陈瓘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('立可则礼思复雪中见过', '释居简', '宋代', '花翻云叶舞风回，新好缤缤带雨开。团破小龙寒未瀹，客如两鹤瘦飞来。\n\n白灰宿火虽同拥，黄独无苗各自煨。苕霅扁舟明日去，小须门外玉山颓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '立可则礼思复雪中见过' AND p.poem_author = '释居简';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题凤翔赵太守红梅图', '朱诚泳', '明代', '凤翔太守非凡夫，见我手执红梅图。猩红万点照人眼，恍疑击碎新珊瑚。\n\n乾坤佳丽江南好，染出一枝春信早。北人未识误呼名，梅格凭谁诘诗老。\n\n我园亦自有红梅，移根元自江南来。万花头上占春色，粗桃俗李徒嫌猜。\n\n太守长才足经济，郡斋坐对收清气。何当携取真盐梅，为我天家调鼎味。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题凤翔赵太守红梅图' AND p.poem_author = '朱诚泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吕老兆棠先生古稀荣庆成七律二章敬祝千秋 其二', '杨民仁', '近代', '景运重开盛世天，喜登耄耋舞蹁跹。风流跌宕真高士，巽退谦和是隐贤。\n\n江水东流长浩浩，福缘汇至自年年。会当快饮三杯酒，大好河山色更妍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吕老兆棠先生古稀荣庆成七律二章敬祝千秋 其二' AND p.poem_author = '杨民仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岁终呈一斋', '吴汝弌', '宋代', '磊砢千丈松，清阴荫林丘。\n岂无栋梁用，匠伯不见收。\n匠伯恐未良，栋梁终有求。\n天风叶偃盖，五云常为浮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岁终呈一斋' AND p.poem_author = '吴汝弌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大梁 其一', '范天烈', '近代', '倥偬风尘出大梁，曦轮翻苦夏初长。曾经坐卧拳双膝，孰说醇醪有别肠。\n\n牛马此生终汗血，诗书不火是灵光。归来愿种千章柳，时听黄莺闹夕阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大梁 其一' AND p.poem_author = '范天烈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵无极以道寄金山寺佛鉴五绝 其三', '晁补之', '宋代', '鹙子犹应昧此缘，室中那有久如天。饶师掷过三千界，浮玉西津故俨然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵无极以道寄金山寺佛鉴五绝 其三' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南邻伤逝二首 其二', '王益初', '近代', '月隐高城乌夜啼，那堪风雪忆街西。咚咚腊鼓又催岁，杯酒何从酹墓堤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南邻伤逝二首 其二' AND p.poem_author = '王益初';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('续梅花百咏 其六十四 茅舍梅', '陶德勋', '清代', '几树扶疏绕草堂，春来一路吐幽香。从兹玩赏敦乡俗，野老村翁并举觞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '续梅花百咏 其六十四 茅舍梅' AND p.poem_author = '陶德勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠天津吕昂挥使', '程敏政', '明代', '百雉高城虎豹屯，将军初识吕虔孙。帆樯影匝河边路，刁斗声连海上村。\n\n青镜年华应自惜，锦囊兵法共谁论。他时不忘相逢处，驿舍迎人柳拂门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠天津吕昂挥使' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('甲戌正月八日立春呈陆岱瞻令公', '张萱', '明代', '宜春宝字绤衔龙，苍帝初乘列子风。鳄渚棠阴歌召父，骊峰藜杖候莱公。\n\n花前綵胜开双篆，竹下云翘舞两同。仙令行春嘘黍谷，阳和先满两花封。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '甲戌正月八日立春呈陆岱瞻令公' AND p.poem_author = '张萱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乌栖曲应令三首 其二', '萧子显', '南北朝', '浓黛轻红点花色，还欲令人不相识。金壶夜水讵能多，莫持赊用比悬河。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乌栖曲应令三首 其二' AND p.poem_author = '萧子显';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('道傍杏花一树盛开', '杨士奇', '明代', '碧草初出地，杏花红满枝。粲粲耀晨旭，盈盈娇路岐。\n\n称我庭阶赏，植远不可移。玩之未忍别，念当长育时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '道傍杏花一树盛开' AND p.poem_author = '杨士奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙 湖干集香居小饮', '溥儒', '近代', '曲院荷风动晚香，寥花垂影照横塘。孤城一片暮苍苍。\n\n雁下芦洲云路远，鸥眠蒲叶故亭荒。登楼容易送斜阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙 湖干集香居小饮' AND p.poem_author = '溥儒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('红蓼', '宋祁', '宋代', '花穗迎秋结晚红，园林清淡更西风。\n织条尽日差差影，时落钓璜溪水中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '红蓼' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山顶晚霁', '胡直', '明代', '八万山河一掌宽，四天应合作回阑。独怜到此谁为耦，坐共羲和倚日看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山顶晚霁' AND p.poem_author = '胡直';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟复愁十二首 其十二', '周霆震', '元代', '未忍歌鸲鹆，犹能拜杜鹃。暮年心寸许，何日睹青天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟复愁十二首 其十二' AND p.poem_author = '周霆震';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢临川游山', '张之象', '明代', '客行旷登览，羁心展游陟。\n裹粮度瑶岑，振衣寻石室。\n源深洞屡迷，径险岩逾密。\n重林散轻雾，绝壁映初日。\n鸟鸣识节变，草绿知春及。\n夭桃始发溪，猗兰渐盈泽。\n采药遵灵丘，援萝入幽谷。\n缅邈隐士居，想像仙人宅。\n朝窥鸾鹤逝，夜听猩猿泣。\n水镜含清晖，松门带暝色。\n近涧虹文丹，远峰岚气黑。\n云归影难留，泉飞响易急。\n观奇道转远，探异情未毕。\n候月弄澄鲜，飡霞羡高逸。\n适己物自忘，达生赏无极。\n终然得所遣，傥值同怀客。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢临川游山' AND p.poem_author = '张之象';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('仿归去来辞', '晁迥', '宋代', '陶令曾言归去来，解印还家不回首。屏贵都遗身外名，忘忧酷嗜杯中酒。\n\n白傅曾言归去来，了知浮世非长久。独步逍遥自得场，饮食寝兴随所偶。\n\n罗隐曾言归去来，濩落生涯何所有。明日船中竹一竿，要学江湖钓鱼手。\n\n晁叟亦言归去来，抗表辞荣养衰朽。京洛红尘旧满衣，总脱临风都抖擞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '仿归去来辞' AND p.poem_author = '晁迥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古九十八首 其十二', '释印肃', '宋代', '经入藏，禅归海，普愿灵，正常在。除非道满月圆人，共话同知非向背。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古九十八首 其十二' AND p.poem_author = '释印肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('京城杂咏七首 其五', '欧阳玄', '元代', '鳌山宴罢月溶溶，太液池边湛露浓。不用金莲送归院，水晶宫出玉芙蓉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '京城杂咏七首 其五' AND p.poem_author = '欧阳玄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('信都公家白兔', '王安石', '宋代', '水精为宫玉为田，姮娥缟衣洗朱铅。\n宫中老兔非日浴，天使洁白宜婵娟。\n扬须弭足桂树间，桂花如霜乱後前。\n赤鸦相望窥不得，空疑两瞳射日丹。\n东西跳梁自长久，天毕横施亦何有。\n凭光下视罝网繁，衣褐纷纷漫回首。\n去年惊堕滁山云，出入虚莽犹无群。\n奇毛难藏果亦得，千里今以穷归君。\n空衢险幽不可返，食君庭除嗟亦窘。\n今序得为此兔谋，丰草长林且游衍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '信都公家白兔' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·皓月光同水泄', '顾随', '现代', '皓月光同水泄，银河澹与天长。\n眼前非复旧林塘。\n千陂荷叶露，四野藕花香。\n恍惚春宵幻梦，依稀翠羽明珰。\n见骑青鸟上穹苍。\n长眉山样碧，跣足白于霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·皓月光同水泄' AND p.poem_author = '顾随';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日纵游汤山翠微玉泉诸胜得诗十五首 其十', '黄浚', '近代', '独爱禅关偃盖松，松阴长著玉琤琮。寒潭龙气呼难起，摇暮聊迟一杵钟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日纵游汤山翠微玉泉诸胜得诗十五首 其十' AND p.poem_author = '黄浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('携具邀诸子重过东村别业六首', '马之骏', '明代', '分火疏篱外，闻鸡曲巷中。\n烟云如恋主，田舍得称翁。\n林止留槐绿，霜将酿柿红。\n前期俄匝月，惆怅岁时空。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '携具邀诸子重过东村别业六首' AND p.poem_author = '马之骏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('将赴京师，留题孙处士山居二首', '许浑', '唐代', '草堂近西郭，遥对敬亭开。枕腻海云起，簟凉山雨来。 \n 高歌怀地肺，远赋忆天台。应学相如志，终须驷马回。 \n 西岩有高兴，路僻几人知。松荫花开晚，山寒酒熟迟。 \n 游从随野鹤，休息遇灵龟。长见邻翁说，容华似旧时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将赴京师，留题孙处士山居二首' AND p.poem_author = '许浑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再见王进之于潭王即有岳鄂之行赠之四首', '赵蕃', '宋代', '别日故已久，愿言今则多。\n寒温一劳苦，身世两蹉跎。\n在己须当勉，其余莫问他。\n昔贤虽已矣，吾辈合如何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再见王进之于潭王即有岳鄂之行赠之四首' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上湖', '陈棣', '宋代', '舟车出阛阓，暂觉脱樊笼。松荫凄迷日，荷香澹沱风。\n\n凌晨争迅急，向晚却和融。貌取君诗句，方知物象同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上湖' AND p.poem_author = '陈棣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵王适上元夜二首 其二', '苏辙', '宋代', '宿雨初乾试火城，端居无计伴游行。厌看门外繁星动，想见僧窗一点明。\n\n老罢逢春无乐事，梦回孤枕有乡情。重因佳句思樊口，一纸家书百镒轻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵王适上元夜二首 其二' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('百字令 题清惠堂遗印', '张绉英', '清代', '鸾回凤翥，似连城返赵，珠还合浦。二百年来无恙在，旧事前朝细数。\n\n玉斧谁磨，金瓯易缺，此物犹如故。沉沙戟在，鬼神应为呵护。\n\n当日被黜归山，壮怀激烈，起逐鸣鸡舞。耿耿孤忠悬日月，百战雄心最苦。\n\n燕子窝边，凤凰山上，勋业嗟迟暮。专祠清惠，至今犹仰遗宇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '百字令 题清惠堂遗印' AND p.poem_author = '张绉英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同韵效欧苏体', '于石', '宋代', '草庐抱膝方卧龙，狞飙撼户云埋峰。冻鹊依依飞堕地，饥鹰侧翅低盘空。\n\n岂知水官夜鏖战，鞭虬笞凤驱前锋。茫茫万里混一色，远近高下俱迷踪。\n\n松标特立凛生气，竹腰不折凌高风。长江一派清不泯，浩浩独行天地中。\n\n小民祁寒易咨怨，君子守道惟固穷。有雪无雪两不问，仁耕义耨无歉丰。\n\n君不见闭门无人僵卧处，任渠门外深丈许。穷则当与凡民异，达则当为国之瑞。\n\n何当燮理司化钧，坐令寒谷回阳春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同韵效欧苏体' AND p.poem_author = '于石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('即席用苏世贤韵送郭子昭', '许谦', '元代', '揽辔春风入骏蹄，两堤烟柳护晴溪。黄莺自有留人意，相对残红不忍啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '即席用苏世贤韵送郭子昭' AND p.poem_author = '许谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('败荷', '王镃', '宋代', '叶无圆影柄无香，收尽莲歌冷碧塘。\n一片伤心云锦地，也曾遮月宿鸳鸯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '败荷' AND p.poem_author = '王镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青林渡', '张仲深', '元代', '青林渡头月影微，舍南鸦阵归提提。澄江入夜客唤渡，短艇剪烛閒裁诗。\n\n田园每为乐事废，鼓角又起残年悲。十年踪迹半江海，草草杯盘慰别离。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青林渡' AND p.poem_author = '张仲深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏怀三十首 其二十五', '沈鍊', '明代', '仙子悟长生，鍊元积真道。一气含太虚，宝鼎手能造。\n\n衣裳翳白云，鸡犬呜丹灶。玉帝校尺籍，紫书方命召。\n\n韩众携竹冠，卢敖奉金诰。济世有丹砂，冲举何足好。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏怀三十首 其二十五' AND p.poem_author = '沈鍊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄元均', '石介', '宋代', '君为儒者岂知兵，何事欣随璧马行。裴度樽前坐韩愈，赵成帐下立荀卿。\n\n御戎谁道全无策，对垒宁妨下一枰。须信乾坤养不肖，年三十七卧柴荆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄元均' AND p.poem_author = '石介';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日病肺二首 其二', '卢龙云', '明代', '节是中和候，人非卧病时。雨馀山转丽，寒歛树多姿。\n\n社赛宜春酒，池添梦草诗。不须传七发，强欲对花枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日病肺二首 其二' AND p.poem_author = '卢龙云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再和贾仲武游狼山', '刘弇', '宋代', '寻春古原头，林梢过朝霂。狼山连东南，擅美此其独。\n\n抟鹏岌骇势，泼黛森孤麓。宜樵叶堆松，供茹萌抽竹。\n\n区区介丘北，回视一何䠞。浑疑杳霭中，爽气每先蓄。\n\n掬泉弄幽清，渴肺初欣沃。嘘云出羽盖，入鸟洞胸腹。\n\n茫茫宇宙间，千里得寸目。照发射冷翠，袭裳来远馥。\n\n根株吐乾坤，要会控水陆。高跻顶初绝，却转道弥复。\n\n楩楠间桐槠，干霄非一木。覃覃辟宝构，殿阁辉丹绿。\n\n禅客稻饵珠，骚人楮留玉。游嫌后时追，赏贵前期卜。\n\n眷彼市井徒，乾没走丹毂。老死不一到，动辍取挛束。\n\n谁知吾辈游，趣尚非搐缩。拂衣便成往，握手不嫌黩。\n\n句外气争豪，禅中机斗速。无为苦役役，坐自绊驰足。\n\n纷纷簿领间，与物商直曲。会须摆红尘，更著轻鞭逐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再和贾仲武游狼山' AND p.poem_author = '刘弇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和孝仪看灯词十二首 其十二', '王彦泓', '明代', '丹诚默向紫姑陈，可得心期遂此春。陵谷沧桑终日事，不堪长作意中人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和孝仪看灯词十二首 其十二' AND p.poem_author = '王彦泓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('漫兴八首 其二', '王世贞', '明代', '冥搜碧海珊瑚老，细琢青春玉叶过。只自人间无白雪，不知天上有黄河。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '漫兴八首 其二' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('最高楼 即景', '吴嘉谟', '近代', '江漠漠，双塔露孤峰。倒射夕阳红。疏篷晚弄人争渡，远树烟生鸟唤风。\n\n这遥情，沙渚外，笛声中。\n\n切莫向、棂头辜负酒。切莫向、岸头辜负柳。浪掷了，总成功。\n\n闲话种桃寻道士，安排佣菜学英雄。近黄昏，钟初动，月如弓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '最高楼 即景' AND p.poem_author = '吴嘉谟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜泊宣城界（一题作旅行欲泊宣州界）', '孟浩然', '唐代', '西塞沿江岛，南陵问驿楼。湖平津济阔，风止客帆收。 \n 去去怀前浦，茫茫泛夕流。石逢罗刹碍，山泊敬亭幽。 \n 火识梅根冶，烟迷杨叶洲。离家复水宿，相伴赖沙鸥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜泊宣城界（一题作旅行欲泊宣州界）' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春寒', '文彭', '明代', '腊尽期春至，春来寒更隆。凝云初漏日，舞雪又旋空。\n\n惨惨阴生涧，重重箔护风。梅花消息近，应只在墙东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春寒' AND p.poem_author = '文彭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乙卯六月四日抵里志喜', '何栻', '清代', '一去乡关十七年，归来闾巷尚依然。欢声迎路如雷动，笑面生辉比月圆。\n\n牙节双持谁复羡，腰缠万贯我能捐。最难八十慈亲健，喜著朝衣舞膝前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乙卯六月四日抵里志喜' AND p.poem_author = '何栻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天饷行', '姚燮', '清代', '吴俗畏神逾畏官，恐益冥谴违神欢。天饷之制肇何自，遵为岁例长不刊。\n\n道人绛袍七叶冠，执符来自三茅坛。稽查口数造编册，量贫酌富求疵瘢。\n\n村坊有首巷有长，各司其地催纳完。楮皮市价同罗纨，金模银范高堆槃。\n\n分头齐赴社神庙，稽颡焚告欢声攒。灵车隐隐天门端，华旗五丈螭虬蟠。\n\n真皇撚须降颜色，空烟回舞双青鸾。歃牛庖鹿迎上銮，琢玉为俎珍珠箪。\n\n烛屏华茜交红珊，香毬百绺芙蓉抟。觋姑鸣蠡唤阴月，朝天狐髻新鬗鬗。\n\n咒辞秘密无谑谰，似为民白精力殚。锡之饱煖常平安，灾无焚溺无凶奸。\n\n或作狡狯藐科律，迟回抽减来触掸。火犀赤眼透九井，呼吸不得雷霆瞒。\n\n女青执笔驱獾犴，泥犁五狱刀巑岏。籍尔家室戮尔嗣，幽囚骨肉诛心肝。\n\n斯民乃惧乃惩戒，低声唯唯容凄寒。担筐挟镪恐人后，挤肩狭路争嚣欢。\n\n其匮乏者穷谋钻，典物鬻器忘衣餐。一传万鬨蔽城市，若狂若醉无从拦。\n\n道人丰颐垂两髋，弟子执拂童司鞶。巍峨紫馆压朱邸，洞庭八牖环明峦。\n\n暮拥勺药朝斟兰，醉骑铜虎摩琅玕。千箱百斛均匪难，罪章讵惜功曹弹？\n\n奈何当道瘖且眢，听其妖惑民受剜。化工大造纳群有，奚资琐细弥歉单。\n\n卓哉文正毁淫祀，整饬薄俗今所难。何当痛洗真宰辱，鞭龙远吸昆崙澜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天饷行' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赵季若染髭走笔简之', '蔡戡', '宋代', '赵子方五十，须鬓何斑斑。身老心未伏，揽镜嗟衰残。\n\n染髭学年少，整容向云鬟。世间有仙诀，坐使壮岁还。\n\n霜华喜顿改，霞脚惊先斓。乃知人力穷，欲夺造化难。\n\n黑白变朝暮，相对真面谩。眉目且作伪，而况方寸间。\n\n劝君循天理，颓然任苍颜。汉廷方贵老，白首尚握兰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赵季若染髭走笔简之' AND p.poem_author = '蔡戡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('马毙三首 其二', '仇远', '宋代', '苦无驰骤但加餐，马性由来不耐閒。官满马亡归去好，且骑白犊看青山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '马毙三首 其二' AND p.poem_author = '仇远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庆裴脩撰母八十', '杨荣', '明代', '人子愿亲寿，今古心所同。赋命本於天，所愿宁悉从。\n\n懿哉裴氏母，执德柔以恭。相夫务勤俭，训子亲和熊。\n\n妇道与母仪，二者备厥躬。所以获天祐，具此寿福隆。\n\n夫贵子亦显，乃荷鸾诰封。冠帔何煇煌，发白颜如童。\n\n年今届八帙，目明耳犹聪。华旦称寿觞，绮席生香风。\n\n翩跹五綵衣，拜舞春融融。冀母踰百岁，更祝繁禧崇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庆裴脩撰母八十' AND p.poem_author = '杨荣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赋新茶', '李曾伯', '宋代', '建岭人夸第一纲，湘中热后已先尝。\n虽然声价殊官焙，反觉山家气味长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赋新茶' AND p.poem_author = '李曾伯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟过陆州谢乡人余五郎送酒', '王寅', '明代', '新醪香艳石榴花，赠得双樽不用赊。\n为谢客愁消得尽，残年一路醉还家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟过陆州谢乡人余五郎送酒' AND p.poem_author = '王寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('种蜡梅喜成时欲暂往梁溪', '张镃', '宋代', '出得荆扉喜欲颠，园夫撑到蜡梅船。\n包封山土根微脱，束缚溪藤叶尚鲜。\n搬处侧从新迳里，种时围向旧台边。\n叮咛等待吾归看，切莫开花小至前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '种蜡梅喜成时欲暂往梁溪' AND p.poem_author = '张镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送龙孔绍上舍还乡', '罗钦顺', '明代', '浦树迎秋咽早蝉，江风吹雨润离筵。壮怀永结青云上，乡思遥驰白雁前。\n\n伴得同声深酒盏，行逢佳景费吟笺。已看头角峥嵘见，此去宁容久在渊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送龙孔绍上舍还乡' AND p.poem_author = '罗钦顺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王子英馆杨氏作诗自述以柬之 其三', '岑安卿', '元代', '蒲轮逆申公，感慨怀汉武。为治顾力行，所答惟一语。\n\n寥寥百世下，兹事谁复举。高松梁栋材，埋没同草莽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王子英馆杨氏作诗自述以柬之 其三' AND p.poem_author = '岑安卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词', '王仲修', '宋代', '宫槐御柳绕池亭，水殿中间暑气清。\n珠纲帘深尘不到，静闻燕子引雏声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词' AND p.poem_author = '王仲修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('除夕过任山甫不遇', '欧大任', '明代', '任昉诗谁似，风流大郡僚。贡金同九牧，鸣佩已三朝。\n\n岁暮家炊桂，天涯客颂椒。寻君不可见，羸马玉河桥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '除夕过任山甫不遇' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗 其七', '陶渊明', '魏晋', '日月不肯迟，四时相催迫。\n寒风拂枯条，落叶掩长陌。\n弱质与运颓，玄鬓早已白。\n素标插人头，前途渐就窄。\n家为逆旅舍，我如当去客。\n去去欲何之？南山有旧宅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗 其七' AND p.poem_author = '陶渊明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和渔具十绝 其七 灯', '牟巘', '宋代', '荧荧枯蚌中，急雪洒不灭。西风明日晴，双花为侬结。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和渔具十绝 其七 灯' AND p.poem_author = '牟巘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠陈明经', '徐渭', '明代', '青袍当夏剪，丹粟在秋芳。攀折一枝好，风雷八月凉。\n\n马疾道不短，鲤化角偏长。尚隔两三月，君先眉上黄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠陈明经' AND p.poem_author = '徐渭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新笋二首 其一', '卢龙云', '明代', '旧干依檐出，新芽拆藓来。清标霜里劲，生意地中回。\n\n何日能栖凤，先春解友梅。琴囊与诗卷，还并绿阴开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新笋二首 其一' AND p.poem_author = '卢龙云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('钓台二首', '缪瑜', '宋代', '桐庐江中秋水清，富春山中秋月明。\n钓竿千尺无恙在，持竿我欲从先生。\n先生岂是傲当世，鄙夫患失滔滔是。\n狂澜既倒挽之回，持报故人惟此尔。\n衮衣不博一羊裘，事往台空江自流。\n遂令千古重名节，於乎先生真汉杰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '钓台二首' AND p.poem_author = '缪瑜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同皇甫子循游横山二首 其二', '唐顺之', '明代', '常时思独往，坐为尘事撄。幸接金门客，相攀桂树荣。\n\n峰微片云度，谷静众禽鸣。何年将结社，与子共逃名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同皇甫子循游横山二首 其二' AND p.poem_author = '唐顺之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百零二首 其八十五', '释绍昙', '宋代', '结夏已十日了也，寒山子作么生。村诗吟落韵，竹管贮残羹。\n\n结夏已十日了也，水牯牛作么生。爱从荒草去，不向坦途行。\n\n精神陡顿，头角峥嵘。好把一坑埋瘗却，千峰云静月华明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百零二首 其八十五' AND p.poem_author = '释绍昙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('孙褒铜印歌', '桂馥', '清代', '张俭亡命谁投止，鲁国孔褒堪依恃。事觉俭捕褒亦收，一门老幼力争死。\n\n死者千年骨已灭，私印犹存肝胆血。友朋一诺重千金，何烦印信合符节。\n\n石碑出土成臼科，独留名字终不磨。一碑一印在人世，闇中当有神物呵。\n\n去年曾见窦武印，汉人气节如山峻。文举之碑不可寻，德让有碣字难认。\n\n我携此印归曲阜，陈于碑下拜稽首。家业授受《春秋经》，谁为《公羊》发墨守。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '孙褒铜印歌' AND p.poem_author = '桂馥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('牡丹下宴集 其五', '孙原湘', '清代', '席罢香舆散画阑，感卿花下独来看。比肩立尽斜阳影，相见非难别总难。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '牡丹下宴集 其五' AND p.poem_author = '孙原湘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('《东方诗风》创刊号面世龙生兄招饮南纪门诗以记之 其一', '陈仁德', '当代', '朗吟豪饮气纵横，一卷新编共点评。莫道诗人皆落寞，小姑隔座索签名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '《东方诗风》创刊号面世龙生兄招饮南纪门诗以记之 其一' AND p.poem_author = '陈仁德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('有怀周燕五', '程坚甫', '当代', '隔水偏能断羽鳞，文缘再续竟无因。那从末俗求知己，却为凉风忆故人。\n\n老我形骸犹放浪，知公才调最清新。山城风雨鸡鸣夜，剪烛论诗迹已陈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '有怀周燕五' AND p.poem_author = '程坚甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人', '陈方恪', '清代', '南朝几许伤心事。一枕苏春睡。猗兰青鸟返瑶天。不尽落花流水、恨年年。\n\n兴亡覆手翻云雨。谁抵钟情苦。瓣香千载盥清词。人是金戈铁马、渡江时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人' AND p.poem_author = '陈方恪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再次笋韵', '张扩', '宋代', '羽猎谁寻狐貉皮，空林失箭已千枝。遥聆春晚斧斤响，不到岁寒霜雪时。\n\n喜有斋熏延上座，愧无椽管付师宜。平生漫作汉宫妾，十指许长君未知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再次笋韵' AND p.poem_author = '张扩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题罗年能六友堂', '魏了翁', '宋代', '罗氏堂中六友图，要求纸尾数行书。\n若於此味真知得，着甚言词乞与渠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题罗年能六友堂' AND p.poem_author = '魏了翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重阳前一日约寓公饮于新开湖之西港有歌词者其乱曰会与州人饮公遗爱一江醇酎遂以此分韵赋诗某得一字', '魏了翁', '宋代', '吾州远景楼，为天下第一。下有千尺湖，长虹倚斜日。\n\n烟云纷蔽亏，草树互蒙密。人既位通显，湖犹困遗逸。\n\n一段云锦机，割截不成疋。我来划见之，慨然为拈出。\n\n凹者豁以舒，凸者疏而溢。乃取半山句，以榜湖阴室。\n\n晨舟乱平渺，日晏未云毕。客喜以问余，幻成子何术。\n\n余非袭而致，彼有是良质。牛山木尝美，茅径人自窒。\n\n一笑各会心，凉风送萧瑟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重阳前一日约寓公饮于新开湖之西港有歌词者其乱曰会与州人饮公遗爱一江醇酎遂以此分韵赋诗某得一字' AND p.poem_author = '魏了翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵和酬', '杨蟠', '宋代', '涧南一啸清风发，林下重来白日长。\n云远石深连鹫岭，水寒沙浅似鱼梁。\n漫因野老询前事，间伴幽人撷众芳。\n更欲穷源情未已，知君嗔我索归忙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵和酬' AND p.poem_author = '杨蟠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题陈道士处静轩 其三', '李昌祺', '明代', '虚室原生白，寥寥一榻清。石坛云影度，金掌露光凝。\n\n叩齿宫神集，斋心道气澄。三尸能斩却，铅汞自然成。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题陈道士处静轩 其三' AND p.poem_author = '李昌祺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('石田画庐山高', '吴廷桢', '清代', '石田老人笔有神，匡庐面目为写真。荦确高峰馲驼卧，蜿蜒悬瀑蛟龙蹲。\n\n更叱巨灵运神斧，削出坡陀似悬乳。哀猿下饮难攀条，寒鸟归飞愁堕羽。\n\n万古盘涡转轮毂，三叠水帘珠万斛。游人总向画图看，依稀认得康王谷。\n\n何年来游支短筇，笋舆芒屩相过从。会当洗耳万山顶，高揖五老看炉峰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '石田画庐山高' AND p.poem_author = '吴廷桢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重九', '姜特立', '宋代', '渊明颇爱重九名，我亦爱饮重九酒。已办黄菊与红萸，唤起陶公为四友。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重九' AND p.poem_author = '姜特立';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('悲哉行', '黎遂球', '明代', '江魂夜热鴊□露，田光俛叹荆卿怒。风吹白浪上昆崙，海水千年骑马渡。\n\n丈夫须眉但如此，敲彻肝肠不相视。买丝绣面难绣心，餐英贯蕊徒枯吟。\n\n黯黯浮云红日入，不如饮酒兼吞泣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '悲哉行' AND p.poem_author = '黎遂球';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜雨', '乾隆', '清代', '夜雨打船窗，恰值清梦醒。\n入耳适宜听，披衾不览冷。\n即南已增润，忆北牵怀永。\n须臾声渐稀，无眠以耿耿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜雨' AND p.poem_author = '乾隆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('村舍燕', '李昌祺', '明代', '垒破频频旋补泥，双飞双语更双栖。雕梁虽贵茅檐稳，暮去朝来莫怨低。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '村舍燕' AND p.poem_author = '李昌祺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('密纬兄侍姬名曰秋雪长斋事佛诗以纪之 其一', '王彦泓', '明代', '嫁得才人百自由，岂须佛力散闲愁。机锋夙世同灵照，福慧他年在阿侯。\n\n姑射仙人真似雪，京江好女故名秋。西方定与郎同去，只愿莲开是并头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '密纬兄侍姬名曰秋雪长斋事佛诗以纪之 其一' AND p.poem_author = '王彦泓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登云麓峰望南岳歌', '汤右曾', '清代', '我闻三神山，远在东海东。神仙恍惚路难到，世上五岳蟠胸中。\n\n忆临沧溟倚日观，九万曾踏扶摇风。昨辞蓬莱建羽节，阳景一翳迷高嵩。\n\n西南万里入罗鬼，似堕幽井窥圆穹。东还云梦吞八九，张乐已在轩辕宫。\n\n七十二峰青联属，苍梧天外云蒙蒙。清湘水流环九面，南岳神镇齐三公。\n\n灵妖物怪薮藏纳，彤蕤赤幕光曈昽。峰峰低昂宛相次，独有紫盖争祝融。\n\n雷泓风穴互开阖，玉书金简留穹窿。岣嵝山尖蝌蚪字，人迹欲到路已穷。\n\n使者虚亭花药绕，山人仙骨云霞通。似闻绿发有毛女，不少翠羽来青童。\n\n离宫福地入缥缈，目所眺瞩攀跻同。衡阳县前昔骋望，压阵𡾰嵼云排空。\n\n仙山咫尺俗缘误，况今百病中交讧。升高视远腰脚软，左右扶掖如衰翁。\n\n道人铁瓦缅遗构，拜岳之石高巃嵷。九疑清猿怨遥夜，洞庭落日浮孤篷。\n\n汉女幽兰冉冉翠，楚妃泪竹斑斑红。振衣周览穷上下，忽与意思增清雄。\n\n人间扰扰等蠛蠓，慎勿变化随沙虫。君不见回雁峰来八百里，挥手欲驾冥飞鸿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登云麓峰望南岳歌' AND p.poem_author = '汤右曾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟中有感', '翁煌南', '清代', '东都此去路漫漫，回首离情泪不乾。寞寂孤舟难写恨，家乡窃喜望中看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟中有感' AND p.poem_author = '翁煌南';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人 临翔老照片山水，以画意出之', '黄绮', '当代', '北来卅载还年少。此境谁能到。全凭笔墨养生功。毕竟古稀学画胜儿童。\n\n树平风缓山无刃。水似眼波润。借他照片一临之。博得大师微笑太愚痴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人 临翔老照片山水，以画意出之' AND p.poem_author = '黄绮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('迓帅夜渡广汉', '郭印', '宋代', '负弩迎使车，暮涂颇忽迫。\n篝火灭还明，羸驽费鞭策。\n行行汉江漘，月照沙水白。\n登舟越惊涛，未济忽欹侧。\n可怜为升斗，性命鸿毛掷。\n人生谁贵贱，同是蘧庐客。\n敢轻千户侯，愿丐五亩宅。\n归共老农游，饮酣歌帝泽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '迓帅夜渡广汉' AND p.poem_author = '郭印';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别妻家', '孟郊', '唐代', '芙蓉湿晓露，秋别南浦中。鸳鸯卷新赠，遥恋东床空。 \n 碧水不息浪，清溪易生风。参差坐成阻，飘飖去无穷。 \n 孤云目虽断，明月心相通。私情讵销铄，积芳在春丛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别妻家' AND p.poem_author = '孟郊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('毗陵道中', '陶安', '明代', '孤帆斜日领舟行，远道无山为送迎。沙店疏篱堪问酒，烟村高树不闻莺。\n\n一湾野水鸥波静，到处蘋香客思清。莫叹飞蓬类踪迹，成名自昔在书生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '毗陵道中' AND p.poem_author = '陶安';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古像赞二百零五首 其二十 泰伯', '孙承恩', '明代', '周室作兴，笃生圣嗣。子不难让，默识天意。去国之迹，泯于无形。\n\n可谓至德，民无得称。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古像赞二百零五首 其二十 泰伯' AND p.poem_author = '孙承恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏梅 其五', '区大相', '明代', '皎洁瑶台树，开花近东观。素影临玉阶，孤芳入幽幔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏梅 其五' AND p.poem_author = '区大相';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠眼医', '赵秉文', '金朝', '和扁不并世，世岂无良医。今代王彦若，恨无东坡诗。\n\n大弨卧壮士，积热下脑脂。神针运斤风，此妙人得知。\n\n君言吾有道，神视了不疑。擘山导河流，破壁取蛟螭。\n\n圣道如日月，浮云时翳之。谁为补天手，刮膜施金篦。\n\n韩孟不可作，此艺真吾师。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠眼医' AND p.poem_author = '赵秉文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东湖留题 赠周生', '黄裳', '宋代', '七峰山下无尘客，方寸有能人未识。风吹山水意飘飘，月照市廛机寂寂。\n\n将使居人闻此声，既澄世虑虚生白。英华满轴非春能，银钩更有千钧力。\n\n忽然欲运胸中奇，一挥时落云间壁。何当便跨图南鹏，声意相寻七峰侧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东湖留题 赠周生' AND p.poem_author = '黄裳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻槐庭东游，赋此寄赠 其四', '林朝崧', '清代', '一叶青莲出世间，小游仙乐几时还？锦囊画笔兼诗笔，好写三神海上山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻槐庭东游，赋此寄赠 其四' AND p.poem_author = '林朝崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次赵可大见赠二首 其二', '龚璛', '宋代', '美哉慈乌诗，倚歌鼻酸辛。矫矫寸草微，茫茫天地恩。\n\n人人有此乐，回看亲舍云。何如奉菽水，晼晚严晨昏。\n\n但云谷口耕，名为京师闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次赵可大见赠二首 其二' AND p.poem_author = '龚璛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洛阳城外望龙门作', '殷奎', '明代', '行至洛城下，豁然见龙门。连山亘千里，辟当南崖根。\n\n神功发玄造，面势驾厚坤。昔贤兹阐道，光烂搏桑暾。\n\n因之景益胜，后天镇长存。晴川一怅望，毕志誓穷源。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洛阳城外望龙门作' AND p.poem_author = '殷奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('初夏幽居杂赋', '陆游', '宋代', '篱落鱼池北，房栊道院东。\n水纹藤坐榻，山字素屏风。\n采药松冈近，投竿荻浦通。\n悠然搔短发，心事寄冥鸿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '初夏幽居杂赋' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('入都喜晤诸同人小集絮影轩分赋', '吴麟', '清代', '芳草残阳百里程，到来顿觉岁时更。敢言陶令还归社，笑说庞公又入城。\n\n小阁风花新意致，故人旗鼓旧纵横。酒阑惆怅瞻明月，落絮窗前雨乍晴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '入都喜晤诸同人小集絮影轩分赋' AND p.poem_author = '吴麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('腊月一日与文瑞访定庵于北山别后奉寄', '顾清', '明代', '平林回步草堂深，二十年前此日心。尘土自能迂俗驾，云山曾不碍幽寻。\n\n孤标共指中流镇，高咏犹闻正始音。珍重寒江夜深别，满衣星彩动华簪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '腊月一日与文瑞访定庵于北山别后奉寄' AND p.poem_author = '顾清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古像赞二百零五首 其四十六 汉武帝', '孙承恩', '明代', '盛气当阳，雄才御世。嘉乐唐虞，狭小汉制。振举百度，征伐四裔。\n\n烨烨明明，恢我王治。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古像赞二百零五首 其四十六 汉武帝' AND p.poem_author = '孙承恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感寓 其一', '王称', '明代', '吾闻上古初，浑灏本一气。羲皇肇人文，龙马飒已至。\n\n轩鸿垂衣绅，唐虞臻至治。有巢邈以远，黼黻日云贵。\n\n自从苍姬还，玄酒薄真味。凤衰其如何，寥落匪一世。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感寓 其一' AND p.poem_author = '王称';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题大痴山水', '杨维桢', '元代', '前山后山青不了，大树小树枝相樛。老痴胸中有丘壑，貌得江南一幅秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题大痴山水' AND p.poem_author = '杨维桢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('峡山寺', '白璿', '明代', '山郭推篷见，钟声出峡闻。岩扉晴拂雨，洞口晚留云。\n\n谷响传樵语，江空饮鹿群。归来看屐齿，犹带落花薰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '峡山寺' AND p.poem_author = '白璿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪夜杂诗 其一', '王翰', '元代', '闭门吟咏学饥鸢，孤兴高情自一天。清景惟诗收拾得，党家粗俗亦徒然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪夜杂诗 其一' AND p.poem_author = '王翰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与谬栓法同行口占分水岭诗', '骆罗宪', '宋代', '数声猿叫闽山月，千里思家欠羽翰。\n疑怪五更衾枕冷，霜壶凛凛逼人寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与谬栓法同行口占分水岭诗' AND p.poem_author = '骆罗宪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水龙吟·咏托云松，用坡公韵。松在德胜门内拈花寺', '章钰', '清代', '此生无分擎天，好云何事红尘坠。知还未果，向空垂尽，是何情思。\n\n争道为霖，翻同作雾，这般濛闭。佛穹青万里，无端隔断，果谁见，身起。\n\n仗有老龙潜跃。把香林、四周笼缀。金刚竖几，木义伸臂，自拚糜碎。\n\n何等神通，比蜺蟠础，如犀分水。要教涧底秦官，背地洒，泥犁泪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水龙吟·咏托云松，用坡公韵。松在德胜门内拈花寺' AND p.poem_author = '章钰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('澶守谏议韩璹祷雨有应', '晁补之', '宋代', '长蜺饮井井欲乾，白鼍鸣窟凄风寒。公马未驾阴漫漫，公归湿幕濡旌幡。\n\n霜刀不染鹅颈殷，涂龙安享雩舞闲。隰桑有沃柔可攀，小麦青青大麦攒。\n\n拜公起舞公颜欢，明日空阶响夜阑。屋漏不复愁衣单，帡幪广厦安如山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '澶守谏议韩璹祷雨有应' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闲居', '李远', '唐代', '尘事久相弃，沈浮皆不知。牛羊归古巷，燕雀绕疏篱。 \n 买药经年晒，留僧尽日棋。唯忧钓鱼伴，秋水隔波时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闲居' AND p.poem_author = '李远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春帖子 皇后閤', '王安中', '宋代', '蕊笈琅函受秘文，清虚道合玉晨君。瑶台夜静朝真久，金屋春寒阅箓勤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春帖子 皇后閤' AND p.poem_author = '王安中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题钱公辅众乐亭 其二', '邵必', '宋代', '城外千帆海舶风，城中居市苦憧憧。几生佳景为民老，一日贤侯与我同。\n\n道上槐阴连帟翠，水边人面照花红。寄言乐有时还尽，徒见甘棠忆召公。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题钱公辅众乐亭 其二' AND p.poem_author = '邵必';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送模归卞山并示僧宗义为余守西岩者三首 其二', '叶梦得', '宋代', '端居探幽奇，自谓略已遍。昨登西山巅，雄绝昔未见。\n\n溪湖莽吞吐，云物纷百变。乃知十年间，尚或遗胜践。\n\n巢成辄弃去，我岂秋社燕。为吾课童仆，开辟尽二面。\n\n莫言羊肠险，径小烦屡转。杖藜不用扶，吾脚犹尔健。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送模归卞山并示僧宗义为余守西岩者三首 其二' AND p.poem_author = '叶梦得';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪纱 题赵叔孺画马', '吴湖帆', '清代', '瘦马龚生不画肥。王孙画骨更神奇。秋郊沙卧夕阳低。\n\n千里玉华甘伏枥，一场云梦付长嘶。萧萧风露不胜悲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪纱 题赵叔孺画马' AND p.poem_author = '吴湖帆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春旱四首 其一', '刘克庄', '宋代', '一春闵雨动龙颜，晓殿权停贺雪班。林下散人看邸报，也疏把酒废游山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春旱四首 其一' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂言四首 其二', '贡奎', '元代', '楚冈产至宝，草木为华滋。一朝献君门，借问识者谁？\n\n居然刖其足，九死终不移。枯荣祗自辱，造物真有知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂言四首 其二' AND p.poem_author = '贡奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游王寿山', '蔡蒙吉', '宋代', '王寿山头石径斜，不知何处有仙家。烟霞踏遍芒鞋破，一路春鸠啼落花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游王寿山' AND p.poem_author = '蔡蒙吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏物体六十六首 其三十三 老少年', '王世贞', '明代', '秋色空庭媚眼明，嫣然衰叶转盈盈。虚怜夏女能倾族，恰比徐娘尚有情。\n\n裛露丹枫聊借润，拒霜黄菊肯同盟。春英三五曾涂抹，短蔓长条恨已生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏物体六十六首 其三十三 老少年' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠崔礼驸马', '王建', '唐代', '凤凰楼阁连宫树，天子崔郎自爱贫。金埒减添栽药地， \n 玉鞭平与卖书人。家中弦管听常少，分外诗篇看即新。 \n 一月一回陪内宴，马蹄犹厌踏香尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠崔礼驸马' AND p.poem_author = '王建';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('印香盘', '朱之蕃', '明代', '不听更漏向谯楼，自剖玄机贮案头。炉面匀铺香粉细，屏间时有篆烟浮。\n\n回环恍若周天象，节次同符五夜筹。清梦觉来知候改，褰帷星火照吟眸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '印香盘' AND p.poem_author = '朱之蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭内子王华姜 其十三', '屈大均', '明代', '清明节已届，雨露使心悲。外舅与外姑，野祭今同谁。\n\n汝生治酒食，汝死魂无衣。骸骨傍先公，安此南海湄。\n\n扶胥云惨惨，黄木风凄凄。万里归成妇，袝葬固其宜。\n\n大恩虽未卒，孝媛名已垂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭内子王华姜 其十三' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽钱仲耕运使 其二', '孙应时', '宋代', '濒海安盐筴，潢池息盗兵。上常高计画，公不谓功名。\n\n恻怛忧民志，驱驰报国情。双溪最遗爱，歌颂未收声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽钱仲耕运使 其二' AND p.poem_author = '孙应时';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宋进马哀词', '王维', '唐代', '背春涉夏兮，众木蔼以繁阴。连金华与玉堂兮， \n 宫阁郁其沈沈。百官并入兮，何语笑之哑哑， \n 君独静嘿以伤心。草王言兮不得辞，我悲减思兮少时。 \n 仆夫命驾兮，出阊阖，历通逵。陌上人兮如故， \n 识不识兮往来。眼中不见兮吾儿，骖紫骝兮从青骊。 \n 低光垂彩兮，怳不知其所之。辟朱户兮望华轩， \n 意斯子兮候门。忽思瘗兮城南，心瞀乱兮重昏。 \n 仰诉天之不仁兮，家唯一身，身止一子，何胤嗣之不繁， \n 就单鲜而又死。将清白兮遗谁，问诗礼兮已矣。 \n 哀从中兮不可胜，岂暇料馀年兮复几。日黯黯兮颓晔， \n 鸟翩翩兮疾飞。邈穷天兮不返，疑有日兮来归。 \n 静言思兮永绝，复惊叫兮沾衣。客有吊之者曰： \n 观未始兮有物，同委蜕兮胡悲？且延陵兮未至， \n 况西河兮不知。学无生兮庶可，幸能听于吾师。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宋进马哀词' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送郑见素游江东', '汤显祖', '明代', '艳艳春墀发花朵，寂寂春寒试灯火。\n人日何人清夜沈，玉茗堂前风月可。\n向昔登高平远间，满目沧浪无土山。\n就中有人郑君美，学富文清幽意闲。\n信美闲游动千里，如花揽结金陵子。\n但闻春草为春生，几见情人为情死。\n采葛成衣秋奈何，看朱成碧春又过。\n冉香亭下神姑酒，忽忽江皋离恨多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送郑见素游江东' AND p.poem_author = '汤显祖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和李光祖二首', '吴芾', '宋代', '漏残休更问铜壶，自视平生分已逾。\n每叹奔驰非得计，只知静退是良图。\n耽诗况味今虽在，爱酒情怀近已无。\n诏比二疏吾岂敢，或言出处亦相符。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和李光祖二首' AND p.poem_author = '吴芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠安成诗', '谢灵运', '南北朝', '明政敦化。\n矜恤载怀。\n用掇良彦。\n循我人黎。\n江既永矣。\n服亦南畿。\n解袂告离。\n云往风飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠安成诗' AND p.poem_author = '谢灵运';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次圭父游将军岩韵二首 其一', '朱熹', '宋代', '极目危岑杳霭间，谁将层栋压巑岏。瘦筇上上莫辞远，绝境行行得细观。\n\n眢井尚馀茅绖处，考槃无复硕人宽。倦来拂石支拳睡，万壑吟风午梦阑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次圭父游将军岩韵二首 其一' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寒食二绝 其一', '吕本中', '宋代', '梨花雪白柳深青，也似中原旧驿亭。犹记往来寒食下，客房无酒卧空瓶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寒食二绝 其一' AND p.poem_author = '吕本中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵费司法 其二', '方岳', '宋代', '山居未省佩弦韦，紧闭柴扉不问谁。自钓鳜鱼西塞雨，久盟猿鹤北山移。\n\n古今不遇岂惟我，宇宙无穷付与诗。直道背时宁敢尔，白云深处要耘芝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵费司法 其二' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('袁季海别驾以所藏灵壁石诗轴见示为此篇', '李流谦', '宋代', '诸天享备福，宫殿常随之。\n骄王擅雄富，钟鼓具不移。\n巨细无实相，一种生幻师。\n君家数尺峰，央处供娱嬉。\n衡嵩接几闼，岷峨入提携。\n只作如是解，天地绋目瑿。\n君言勿作剧，丐我琼琚词。\n援毫不能奇，永愧崭绝姿。\n烹茶炷炉薰，崷崒缭轻丝。\n如云出涧壑，顷暂万国滋。\n请以小喻大，人才亦如斯。\n我无适俗韵，梦想怀崯崎。\n借渠琳琅响，和我兰荃诗。\n明朝谢冠服，云根有茅莰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '袁季海别驾以所藏灵壁石诗轴见示为此篇' AND p.poem_author = '李流谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乱后得袁二丈书', '宗臣', '明代', '浮云望断沧海边，尺书西来谁与传。眼前盗贼至今日，赋里江山非昔年。\n\n清世何人洗兵马，孤城有客愁烽烟。紫芋黄菊漫消息，秋风欲上湖东船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乱后得袁二丈书' AND p.poem_author = '宗臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('避暑', '林大钦', '明代', '避暑仍兹地，薰风吹我襟。和光随鸟性，萧寂旷云林。\n\n道虑谢欣戚，达思齐古今。逍遥对萝薜，永矣解余簪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '避暑' AND p.poem_author = '林大钦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过赵庵感赋', '叶云峰', '近代', '清明扫墓过山陂，胜地重临不忍思。银杏参天风瑟瑟，竹林深处鸟叽叽。\n\n状元孝子成陈迹，道德文章已失时。断碣残碑卧夕照，荒烟蔓草使人悲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过赵庵感赋' AND p.poem_author = '叶云峰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新雁过妆楼 次吴梦窗韵', '吴湖帆', '清代', '镜水芙蓉。低鬟亸、娉婷槛曲池东。涴泥轻染，还认历历芳踪。\n\n醉颊三分添采艳，淡妆半倚透春浓。似相逢。汉灵鼓瑟，洛梦惊鸿。\n\n匆匆无言暗别，任露华泪落，粉褪尘空。断肠深院，清漏怨泣啼蛩。\n\n回思对花对月，认真色、真香娇印红。天涯远，正是绵绵，恨长忆心中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新雁过妆楼 次吴梦窗韵' AND p.poem_author = '吴湖帆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋不寐有感', '裴涛', '当代', '清霜黄叶碧云天，世事终难如月圆。自我生涯知进退，由人辞色辨愚贤。\n\n渐安槐国风流梦，久废灯窗秋水篇。露重沾衣同寂寞，此心归处似寒渊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋不寐有感' AND p.poem_author = '裴涛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵孙推官朴见寄二首 其一', '苏辙', '宋代', '蒙愠未能忧悄悄，得闲时复醉昏昏。知君亦学无言语，岂悟维摩不二门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵孙推官朴见寄二首 其一' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阳春曲十首', '陆深', '明代', '轻云微雨净风沙，门掩春寒飐碧纱。缥缈凤箫催羯鼓，前村实有预开花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阳春曲十首' AND p.poem_author = '陆深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和双岩雪月赏菊之什', '孙承恩', '明代', '寒夜大雪霰，冰山郁嵯峨。登堂欣有会，对菊可无歌。\n\n狎恰三人共，联翩五字哦。差池胥会少，感慨系时多。\n\n韩孟才非敌，曹刘兴不过。高城闻击柝，深巷息鸣珂。\n\n放浪予诚罪，撝谦公谓何。疏弦馀古调，劲质靡柔柯。\n\n雕鹗横霄汉，骅骝蓦涧坡。岂惟抒悃素，直用发天和。\n\n纵语言无择，论心谊不颇。焉能甘龊龊，秪是守波波。\n\n共拟心扶日，难教手障河。襟期忝同趣，才力竟殊科。\n\n病骨思丹换，衰颜得酒酡。莫教夸父日，空忆鲁阳戈。\n\n魏老非妩媚，陶翁且婆娑。但令樽有醑，莫计雀堪罗。\n\n要使常披豁，而谁事唯阿。相期崇令德，永诵白圭磨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和双岩雪月赏菊之什' AND p.poem_author = '孙承恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冰上人至自中宿以诗为贽病中下榻赋以赠之 其一', '张萱', '明代', '蓬蒿初辟径，薝卜已全花。阅世唯高枕，为僧未出家。\n\n何来持半偈，刚说演三车。能使泥犁客，超然识聚沙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冰上人至自中宿以诗为贽病中下榻赋以赠之 其一' AND p.poem_author = '张萱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和单君范古意六首 其三 樵', '陈著', '宋代', '枯者既就拾，湿者亦既束。空此一谷薪，载之可折轴。\n\n下山售市价，得粮不能宿。谁知此时心，气塞口自嘿。\n\n安得如买臣，卖薪有时足。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和单君范古意六首 其三 樵' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游僊', '陆游', '宋代', '初珥金貂谒紫皇，僊班最近玉炉香。\n为怜未惯层霄冷，独赐流霞九酝觞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游僊' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过汉州留房公湖一日戏和少陵韵二首', '李壁', '宋代', '西湖天下胜，贤相古来稀。\n汛扫邀明月，徜徉逗落晖。\n蒲深鸂鶒响，林静鹧鸪飞。\n脚力应难遍，雕栏幸可依。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过汉州留房公湖一日戏和少陵韵二首' AND p.poem_author = '李壁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晋正德大豫舞歌二首 其二 大豫舞歌', '傅玄', '魏晋', '于铄皇晋，配天受命。熙帝之光，世德惟圣。嘉乐大豫，保佑万姓。\n\n渊兮不竭，冲而用之。先帝弗违，虔奉天时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晋正德大豫舞歌二首 其二 大豫舞歌' AND p.poem_author = '傅玄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('度居庸关 其二', '王世贞', '明代', '七陵佳气郁葱哉，睥睨寒烽北极开。车转天门通箭括，水排坤轴建瓴来。\n\n书生绝质无中策，大将犁庭有异才。边马莫移青海帐，汉家曾记白登台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '度居庸关 其二' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨中李惟寅宋忠甫邀集冯虚阁同吴公择方子及诸君得游字 其二', '欧大任', '明代', '千雉鸡山侧，丹梯到上头。石能萦细蔓，阁自俯长楸。\n\n净土高僧社，清时大雅游。雨深春草绿，犹自足淹留。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨中李惟寅宋忠甫邀集冯虚阁同吴公择方子及诸君得游字 其二' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('子夜歌四十二首 其二十一', '佚名', '魏晋', '别后涕流连，相思情悲满。忆子腹糜烂，肝肠尺寸断。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '子夜歌四十二首 其二十一' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出为豫章郡途次庐山东岩下', '张九龄', '唐代', '兹山镇何所，乃在澄湖阴。下有蛟螭伏，上与虹蜺寻。 \n 灵仙未始旷，窟宅何其深。双阙出云峙，三宫入烟沉。 \n 攀崖犹昔境，种杏非旧林。想像终古迹，惆怅独往心。 \n 纷吾婴世网，数载忝朝簪。孤根自靡托，量力况不任。 \n 多谢周身防，常恐横议侵。岂匪鹓鸿列，惕如泉壑临。 \n 迨兹刺江郡，来此涤尘襟。有趣逢樵客，忘怀狎野禽。 \n 栖闲义未果，用拙欢在今。愿言答休命，归事丘中琴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出为豫章郡途次庐山东岩下' AND p.poem_author = '张九龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗三十二首 其五', '李梦阳', '明代', '命驾将何之，意欲快我心。蛮方乱如麻，匈奴寇榆林。\n\n挥剑誓俱亡，彼军忽如沉。岂为尺寸勋，国仇怒至今。\n\n昆崙贡织皮，鸱鸮怀好音。功高固不赏，谗妒来相寻。\n\n哀哉险侧子，倾词谁见钦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗三十二首 其五' AND p.poem_author = '李梦阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送张掌教致仕归临江', '祝允明', '明代', '青眼摩挲醉袂分，那堪客里别夫君。风情好似陶彭泽，官职常如郑广文。\n\n渝水晚沙眠宿鹭，蒙山老树映归云。虚堂索句昏钟静，宦海潺湲想未闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送张掌教致仕归临江' AND p.poem_author = '祝允明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人·为张君华题其华月簃消夏图', '叶恭绰', '清代', '莲华世界环空碧。浑似鸥波宅。调冰杀粉助清吟。不信人间犹有俗尘侵。\n\n家山咫尺今何处。离合惊风雨。劫灰平地几楼台。愁见秾花偏傍战场开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人·为张君华题其华月簃消夏图' AND p.poem_author = '叶恭绰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凤凰墩对雨', '弘历', '清代', '雨来西山西，凉送北窗北。佳矣妙烟容，时哉识秋德。\n\n珠玑有馀光，绮縠无定色。既以利稼穑，因之悦游陟。\n\n湖心敞高楼，娱睎停半刻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凤凰墩对雨' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答景裴', '洪适', '宋代', '春来剥啄少登门，涩雨悭风笑我村。桥上垂纶装好梦，花边倚杖记前言。\n\n长杨美竹虽当户，语燕流莺不到园。此会明年千里隔，诗筒犹有置邮存。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答景裴' AND p.poem_author = '洪适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日行近山 其二', '黄镇成', '元代', '门外山童扫落霞，问师还只在山家。推窗引客云边坐，自扇风炉煮雪花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日行近山 其二' AND p.poem_author = '黄镇成';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百四十一首 其一二九', '释师范', '宋代', '前月只此月，后月亦此月。何得尘世人，竞赏中秋节。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百四十一首 其一二九' AND p.poem_author = '释师范';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和罗习之见寄因柬刘渊二首 其二', '郭钰', '元代', '中年离别倍依依，何事欢娱与愿违。日落群鸦烟外急，山空独鹤月中归。\n\n干戈满地荒瓜圃，蓑笠残年拥钓矶。问讯刘郎风雪冷，谁将金缕织成衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和罗习之见寄因柬刘渊二首 其二' AND p.poem_author = '郭钰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上黄参政寿七首 其二', '许及之', '宋代', '谁识金仙抱送时，年年惟有早梅知。只今不负调羹信，造化工深物自私。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上黄参政寿七首 其二' AND p.poem_author = '许及之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('涂侍御同年邀饮观海楼 其二', '王渐逵', '明代', '绮闼散朝暾，芳原没晓痕。越天青不断，溟海势相吞。\n\n经济看遗迹，栖迟且素餐。凭高时遣兴，聊尔解空尊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '涂侍御同年邀饮观海楼 其二' AND p.poem_author = '王渐逵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荣昭德妃挽歌 其四', '黎民表', '明代', '祖道鸣笳引，行尘叠鼓声。椒涂非昔日，象服俨平生。\n\n诔册陈金印，灵輀饰翠旌。婉仪将旧德，青史尚垂名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荣昭德妃挽歌 其四' AND p.poem_author = '黎民表';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵寄史彦明', '牟巘五', '宋代', '等閒看尽弁衡毗，旁郡聊从捧檄驰。\n候管乍披新定志，邮筒忽见故人诗。\n君方清绝行明镜，我正摧颓据槁枝。\n为喜彩衣还膝下，椒柈趁得颂花时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵寄史彦明' AND p.poem_author = '牟巘五';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('关中杂诗 其一', '顾炎武', '清代', '文史生涯拙，关河岁月劳。幽情便水竹，逸韵老蓬蒿。\n\n独雁飞常迅，寒鸡宿愈高。一窥西华顶，天下小秋毫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '关中杂诗 其一' AND p.poem_author = '顾炎武';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('明妃词 其一', '吴俨', '明代', '西风冽冽塞云愁，冻合长河水不流。只恐妾颜明日改，单于轻易犯边州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '明妃词 其一' AND p.poem_author = '吴俨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦与尤木石论史感旧七绝句', '刘克庄', '宋代', '径畈山栖谢宦情，竹溪巷处闭柴荆。\n然藜曾伴刘中垒，起蕝谁招鲁两生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梦与尤木石论史感旧七绝句' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酴醿', '张九成', '宋代', '昨夜姮娥到万山，更携青女散山间。\n天明欲去归不得，化作此花来破颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酴醿' AND p.poem_author = '张九成';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠姜邦杰 其二', '丁逢', '宋代', '鹰扬家世尚精神，授钺宣麻命数新。眷重先帝传禅日，恩除今上继承辰。\n\n谋猷合去陪诸老，眉宇重来看万人。约我登楼共秋月，少留不负百年身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠姜邦杰 其二' AND p.poem_author = '丁逢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('慈节为朱彦明乃堂作', '谢迁', '明代', '苦节良独难，慈训尤不易。有儿归义方，庶矣柏舟誓。\n\n百年未亡身，祗为家门讣。于今幸两全，辛苦遂初志。\n\n他年泉台路，良人见无愧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '慈节为朱彦明乃堂作' AND p.poem_author = '谢迁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('人日次韵高寒贺杨公启宇华诞', '刘雄', '当代', '归卧林泉濩落身，鲁连原不齿苏秦。已辜鬼谷安邦术，来作神州袖手人。\n\n说部沧桑留野史，诗坛旗鼓见云鳞。且凭觞咏永今夕，日月双丸从转轮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '人日次韵高寒贺杨公启宇华诞' AND p.poem_author = '刘雄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湖湄閒适二首 其一', '孙锐', '宋代', '荻花塘外老渔家，夜夜湖边倚钓槎。打起秋风鱼数尾，调羹尽可荐胡麻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湖湄閒适二首 其一' AND p.poem_author = '孙锐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晓行', '弘旿', '清代', '晓行及远道，秋风吹我衣。疏星散平夜，寒溜流前溪。\n\n初日升东山，晨光忽熹微。景在未曙佳，万象纷迷离。\n\n此际有真趣，心閒身亦宜。举目送飞鸿，飘然生远思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晓行' AND p.poem_author = '弘旿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题马文璧画', '贝琼', '明代', '小桥危跨壑，破屋幸依山。\n避地人相过，朝天客未还。\n麝眠春草外，猿挂古松间。\n寂寞南窗日，残书亦久闲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题马文璧画' AND p.poem_author = '贝琼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读史五首 其一', '何吾驺', '明代', '西汉文章尽剧秦，世风到此又安论。中兴满绘功臣像，谁为严陵写钓纶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读史五首 其一' AND p.poem_author = '何吾驺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽林希哲', '吴希贤', '明代', '此日湖山路，霜风玉树枝。顿成千古别，不尽百年悲。\n\n丹桂秋香早，青灯夜影迟。严翁双涕泪，便是忆君时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽林希哲' AND p.poem_author = '吴希贤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西夏凯歌四首', '王稚登', '明代', '诏赐田租墨未干，诛夷顿失主恩宽。\n一朝罢却军兴费，四海疮痍动地欢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西夏凯歌四首' AND p.poem_author = '王稚登';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和韩子文五首', '曾协', '宋代', '寒浅定知春已至，意闲仍觉日初长。\n已谙荣谢如空幻，一室萧然且坐忘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和韩子文五首' AND p.poem_author = '曾协';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('摄事十三首', '佚名', '隋代', '思文圣祖，长发其祥。\n锡义蕃衍，德厚流光。\n眷命自天，卜世聿昌。\n祗肃孝享，降福无疆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '摄事十三首' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('追和东坡梅花十绝 其九', '王之道', '宋代', '步入芳丛脚自轻，看来群卉眼偏明。和羹有实休疑晚，况是东君旧着情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '追和东坡梅花十绝 其九' AND p.poem_author = '王之道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('温飞卿体', '章以荣', '近代', '愁多一倍惜华年，顾影春风只是怜。凤吹初分秦苑里，花光欲透董帷前。\n\n月明笼绣双栖翼，雨暗重衾独自眠。想得秋期天上迩，玉绳犹隔绛河边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '温飞卿体' AND p.poem_author = '章以荣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('摸鱼儿·便披蓑', '刘克庄', '宋代', '便披蓑、荷锄归去，何须身著宫锦。与谁共话桑麻事，朱老阮生尤稔。筛样饼。瓮样茧，长须赤脚供樵饪。清流浊品。尽扫去胸中，置诸膜外，对酒莫辞饮。华胥梦，怕杀人惊晓枕。疏窗惟月来闯。一生常被弓旌误，且告朝家追寝。愁个甚。君管取，有薇堪采松堪荫。茅山再任。幸不是谋臣，又非世将，免犯道家禁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '摸鱼儿·便披蓑' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿田舍遇雨', '廖行之', '宋代', '奔走尘埃日几西，又从舟楫问津涯。\n官身底事多羁束，世路由来足嶮巇。\n甘雨也知苏{左禾右罢}稏，轻风祗管舞涟漪。\n夕阳又傍田村宿，无限蜩螗噪晚颸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿田舍遇雨' AND p.poem_author = '廖行之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('药洲四首 其三', '刘克庄', '宋代', '怪怪奇奇石，谁能辨丑妍。莫教赞皇见，定辇入平泉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '药洲四首 其三' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和士特栽果十首 其四 橘', '刘子翚', '宋代', '南北由来地气偏，凌寒松柏但苍然。逾淮种橘今为枳，岂比中人性易迁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和士特栽果十首 其四 橘' AND p.poem_author = '刘子翚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古二十首 其五', '释道颜', '宋代', '根尘缚脱本同源，一处休复六用捐。手把一条红断贯，娘生鼻孔一时穿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古二十首 其五' AND p.poem_author = '释道颜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('子夜歌十八首 其十三', '晁采', '唐代', '花池多芳水，玉杯挹赠郎。避人藏袖里，湿却素罗裳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '子夜歌十八首 其十三' AND p.poem_author = '晁采';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('皇后庙十五首', '真宗', '宋代', '曾孙袭庆，柔祗育德。\n正位居见，其备不忒。\n教被宫台，化行邦国。\n祝史正辞，垂裕无极。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '皇后庙十五首' AND p.poem_author = '真宗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高宗祀明堂前朝享太庙二十一首', '真宗', '宋代', '歆我斋明，威行如存。\n牲牲是享，圭玉其温。\n群公执事，变既骏奔。\n礼成告入，咸福黎元。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高宗祀明堂前朝享太庙二十一首' AND p.poem_author = '真宗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月', '胡士莹', '近代', '花落香痕不灭，絮飞春影还休。画桥西畔水东头，如梦思量都够。\n\n楼外斜阳正好，黄昏也只难留。薄寒翠袖领春愁，坐尽鹊炉烟瘦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月' AND p.poem_author = '胡士莹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('招讼者归', '陈献章', '明代', '越王城里尘随马，刺史衙前吏喝人。此日王孙不归去，旧游芳草可怜春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '招讼者归' AND p.poem_author = '陈献章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('粤大饥', '欧主遇', '明代', '濯濯山上木，重重甑上尘。不虞垂暮节，见此大灾辰。\n\n岭海久縻烂，今疚更酸辛。肥遗谬云龙，饥兆天下沦。\n\n天刺神不富，曷丧号如焚。周周与蛩蛩，异俗各相因。\n\n胡乃同血气，秦越视所亲。救荒罕长策，望雨先作云。\n\n乞物思裴令，捐益欲周贫。庶几有秋获，比闾庆食新。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '粤大饥' AND p.poem_author = '欧主遇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赵次珊馆长重逢乡举之年同人各以诗纪奉呈二律 其二', '夏孙桐', '清代', '涑水庐陵宿望隆，仍于载笔见公忠。斯文维繫千秋责，晚节艰难一篑功。\n\n先正有灵方策在，鲰生报国此心同。汗青终得桑榆慰，莫为嗟麟虑道穷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赵次珊馆长重逢乡举之年同人各以诗纪奉呈二律 其二' AND p.poem_author = '夏孙桐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东风第一枝 十二月廿一日立春，时快雪三日矣', '周之琦', '清代', '帖剪宜春，诗吟饯腊，重阴偏滞檐角。篆烟企鸭仍含，艳情翠禽未觉。\n\n韶华唤醒，似梦里、东君曾约。甚晓来、赏柳评花，还是冻云迷著。\n\n风乍起、彩幡易落。寒更峭、麝篝漫却。俊游拟拂银鞯，倩魂尚偎绣幕。\n\n天边絮粉，且休问、阳梢红萼。待画鼓、敲出双声，听取试灯妆阁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东风第一枝 十二月廿一日立春，时快雪三日矣' AND p.poem_author = '周之琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春帖子词·皇帝阁十二首', '宋祁', '宋代', '日华初丽上林天，殿里春花百种鲜。\n驱出馀寒还故腊，收回和气作新年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春帖子词·皇帝阁十二首' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('问白发用髭韵', '李东阳', '明代', '我生汝本黑，汝白从何时。汝长亦已白，何得短彼髭。\n\n髭白汝岂黑，嗟我独不思。三年不对镜，纵白安得知。\n\n讦言信有之，髭岂诳我为。髭白汝亦白，黑者尚有谁。\n\n岂我弗汝养，静言观我颐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '问白发用髭韵' AND p.poem_author = '李东阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('先天吟示邢和叔', '邵雍', '宋代', '一片先天号太虚，当其无事见真腴。\n胸中美笺肯自衒，天下英才敢厚诬。\n理顺是言皆可放，义安何地不能居。\n直从宇泰收功后，始信人间有丈夫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '先天吟示邢和叔' AND p.poem_author = '邵雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青阳度', '王世贞', '明代', '堂前女萝草，缠绵依松柏。虽怀千秋契，亮无齐年质。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青阳度' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史十一首 其八', '李华', '唐代', '日照昆崙上，羽人披羽衣。乘龙驾云雾，欲往心无违。\n\n此山在西北，乃是神仙国。灵气皆自然，求之不可得。\n\n何为汉武帝，精思遍群山。糜费巨万计，宫车终不还。\n\n苍苍茂陵树，足以戒人间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史十一首 其八' AND p.poem_author = '李华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('落花四首 其三', '徐渭', '明代', '西园蝴蝶恋芳辰，南陌骅骝蹀绮尘。态比惊鸿还让色，妆如坠马不同新。\n\n非关塞外吹羌笛，巳觉寰中逝早春。寄语堤边游冶客，明朝还得藉青裀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '落花四首 其三' AND p.poem_author = '徐渭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和建王春晚园中赏玩', '史浩', '宋代', '静院朝回静鼓琴，浴沂新咏间清音。燕閒未省忘稽古，始信贤王宝寸阴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和建王春晚园中赏玩' AND p.poem_author = '史浩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春 恭谒阙里', '俞士彪', '清代', '东鲁名区，昌平旧里，恭谒素王。看云生古柱，蛟龙欲舞，苔封危碣，蝌蚪成行。\n\n日月仪容，尧汤宇度，有六艺群贤列座傍。谁窥见，这百王礼乐，千仞官墙。\n\n我来亦敢升堂。但仰止、高山愧未遑。羡彤墀尘净，玉麟宵卧，雕檐日暖，紫凤朝翔。\n\n俎豆陈筵，弦歌在耳，想天地，才能共久长。年年也有，杏花春雨，桧叶秋霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春 恭谒阙里' AND p.poem_author = '俞士彪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('嘉兴道中怀昨游有作先寄文瑞仍约访宗孝御史', '顾清', '明代', '楼船徐度鼓逄逄，忆别追游俯碧窗。几日壶觞并残岁，连宵风雨卧空江。\n\n云边暗数青山九，竹里谁怜白鹤双。明日城东访曹植，锦袍嬴得醉春釭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '嘉兴道中怀昨游有作先寄文瑞仍约访宗孝御史' AND p.poem_author = '顾清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送李令如堤上部夫', '刘弇', '宋代', '东风日作催花计，减去年来大半春。未省春归向何许，真成等閒愁杀人。\n\n我欲揖君空酒樽，君刺野航朝涉津。翩然挥手谢春去，我欲留之良苦辛。\n\n沙堤漫漫失故处，下有清海涛头奔。涛头奔，可奈何，江淮由来水事多。\n\n田家遣丁才取具，吴歈行劝不烦诃。蜗牛小庐乱云锸，梓土把草夷陂陀。\n\n我闻神禹乂九土，息壤能蛰千丈波。独坐败堤去民吏，翻笑王尊禦浊河。\n\n李侯方精强，程督宜有科。民事不可缓，田畴久滂沱。\n\n嗷嗷老将稚，意在却蛟鼍。无为坐叹息，劳事非蹉跎。\n\n山肤杂水豢，强饭时吟哦。暮归泊烦促，不厌玉颜酡。\n\n他时解看官门北，千里长虹卧软莎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送李令如堤上部夫' AND p.poem_author = '刘弇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早梅', '杨则之', '宋代', '数萼初含雪，孤清画本难。有香终是别，虽瘦亦胜寒。\n\n横笛和愁听，斜枝倚病看。朔风如解意，容易莫吹残。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早梅' AND p.poem_author = '杨则之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白石砚', '邓雅', '明代', '一片太古雪，窗间犹未融。坚凝端石比，莹彻水精同。\n\n颇怪胚腪异，堪誇制作工。琢磨经几世，挥洒对清风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白石砚' AND p.poem_author = '邓雅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔家傲', '侯置', '宋代', '过尽百花芳草满。柳丝舞困阑干暖。柳外秋千裙影乱。人逐伴。旧家心性如今懒。 \n 斗帐宝香凝不散。黄昏院落莺声晚。红叶不来音信断。疏酒盏。东阳瘦损无人管。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔家傲' AND p.poem_author = '侯置';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('边月', '曹必进', '清代', '夜色偏宜绕玉门，白云缥缈接昆仑。边鸿孤警低残魄，胡马群嘶落大盆。\n\n北塞刘琨常独啸，南楼庾亮与谁论。只贪满地山河影，不鉴征夫积泪痕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '边月' AND p.poem_author = '曹必进';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠致远 其四', '周孚', '宋代', '畋也颇丰下，本期渠克家。才令配晨月，又复摘秋瓜。\n\n寒泊堪秧稻，荒池足沤麻。熊儿幸无恙，聊伴老生涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠致远 其四' AND p.poem_author = '周孚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠黄山人说仲二首 其二', '胡应麟', '明代', '幕府翩翩旧孟嘉，居然长揖傍高牙。携将江夏波千顷，共汎山阴雪万家。\n\n记室雄词飞彩翰，营门高啸和清笳。荒台百尺斜阳里，惨淡黄金宿暮鸦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠黄山人说仲二首 其二' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('枕上', '陆游', '宋代', '夜雨一再作，灯前独咏诗。\n影看孤鹤瘦，吟答断蛩悲。\n幽梦悠然觉，清笳何足吹。\n残年犹几日，已矣媿明时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '枕上' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('燕谋以余罕作诗寄什督诱如数奉报二首 其一', '钱钟书', '近代', '六情底滞力阑单，上水船经八节滩。识字果为忧患始，作人奚止笑啼难。\n\n举头鹊噪频闻喜，盈耳蛙鸣尽属官。耆旧纷传新语好，偏惭燥吻未濡翰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '燕谋以余罕作诗寄什督诱如数奉报二首 其一' AND p.poem_author = '钱钟书';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('石室游', '郭祥正', '宋代', '端城之北，径五六里。有石室兮洞开，其上则七山建斗司天之喉舌，其下则渊泉不流渟碧一杯。\n\n窥之则肌发冰，酌之则烦心灰。四傍则石乳玲珑，中敞圆盖。\n\n窈窈万丈，莫穷其厓。孰纳忠兮，嗟肺肝之已露。孰止戈兮，束兵仗而相挨。\n\n俨卫士之行列，肃庭臣之序排。纷披披兮蒂萼，粲枞枞兮条枚。\n\n安而不可动者为梁为栋，奔而不可止者为虎为豺。\n\n龟闯首兮屏息，虬奋鳞兮抟雷。怪怪奇奇兮，千变万态。\n\n愈视愈久兮，惚恍惊猜。何人境之俯近而仙宇之秘异如此者哉。\n\n萝卷风兮窈窕，春渍芳兮不回。或命佳客，或寓幽怀。\n\n考二李之劲笔，皆一时之遗材。援玉琴以写咏，怅夕阳之易颓。\n\n方谢事以言返，眷兹室而徘徊。云愀容兮泱漭，鸟送音兮悲哀。\n\n况百年之将尽，邈夫万里奚复来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '石室游' AND p.poem_author = '郭祥正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湖上杂诗 其十', '郑孝胥', '清代', '渐与诸峰熟，又怜湖水妍。湖山岂识我，欲去莫流连。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湖上杂诗 其十' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬李景章先辈', '马戴', '唐代', '平生诗句忝多同，不得陪君奉至公。金镝自宜先中鹄， \n 铅刀甘且学雕虫。莺啼细柳临关路，燕接飞花绕汉宫。 \n 九陌芳菲人竞赏，此时心在别离中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬李景章先辈' AND p.poem_author = '马戴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('林伯仪自金陵还莆过访话别', '徐熥', '明代', '为客经淮楚，归途访索居。云山一骑远，烟柳六朝疏。\n\n问路知乡近，还家及岁除。陆生装薄甚，惟有一囊书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '林伯仪自金陵还莆过访话别' AND p.poem_author = '徐熥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南湖有鸥成群里闾间云数十年未尝见也实尘中奇事因筑亭洲上榜曰鸥渚仍放言六绝 其六', '张镃', '宋代', '不因他处食无鱼，来慰先生索寞居。走笔赠诗君莫笑，从游此是最相于。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南湖有鸥成群里闾间云数十年未尝见也实尘中奇事因筑亭洲上榜曰鸥渚仍放言六绝 其六' AND p.poem_author = '张镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂五十一首 其三十四', '释大观', '宋代', '闹浩浩，静悄悄。古策风高，玉壶春晓。左顾无瑕，右盼已老。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂五十一首 其三十四' AND p.poem_author = '释大观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古诗 其二', '佘翔', '明代', '盈盈三五月，流辉入我帷。中夜起徬徨，忧心当告谁。\n\n白露涂中庭，寒螀夕鸣悲。岂无心所欢，千里邈音徽。\n\n仰视雁南翔，俯盻庭柯飞。漫漫兹长夜，涕泪沾裳衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古诗 其二' AND p.poem_author = '佘翔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杨尉三和篇补其二以为答不敢虚盛意', '李石', '宋代', '湖亭饮酒对新鹅，金错杯中卷白波。\n村鼓冬冬更堪忆，画船照水采菱歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杨尉三和篇补其二以为答不敢虚盛意' AND p.poem_author = '李石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('扬州即事四首 其二', '金武祥', '清代', '炉香茗椀称清游，稳泛轻航狎鹭鸥。一片残荷两行柳，虹桥西去好寻秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '扬州即事四首 其二' AND p.poem_author = '金武祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('文徵明曲港归舟图用画间题者韵', '弘历', '清代', '野艇不须收，烟波任拍浮。得诗缘即景，适性且随流。\n\n山泉雨后生，飞下白云横。留得匡庐意，青莲策杖行。\n\n凭栏聊极目，灌木绿阴稠。寄语披蓑者，源中可放舟。\n\n山势倏断续，云容镇滃浮。漫嫌沙水浅，且自泊孤舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '文徵明曲港归舟图用画间题者韵' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('章衡阳省丈赴谪罗定州道文江宿小斋 其一', '邹元标', '明代', '十载知名久，初看是梦中。坐来人似玉，谭去气成虹。\n\n百粤风烟壮，千山道路穷。愿言频爱护，朝论倚山公。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '章衡阳省丈赴谪罗定州道文江宿小斋 其一' AND p.poem_author = '邹元标';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('除夜侍酒呈诸兄示舍弟', '欧阳詹', '唐代', '莫叹明朝又一春，相看堪共贵兹身。 \n 悠悠寰宇同今夜，膝下传杯有几人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '除夜侍酒呈诸兄示舍弟' AND p.poem_author = '欧阳詹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('引子獐', '文同', '宋代', '苍獐引黄麑，双耳谁惊立。\n高原想新霁，町疃见行迹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '引子獐' AND p.poem_author = '文同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿吕思斋七十', '王立道', '明代', '北望心犹壮，东风发已华。客盈文举座，春属老莱家。\n\n对酒新乌帽，传经旧绛纱。非熊行自卜，十载未论赊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿吕思斋七十' AND p.poem_author = '王立道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春初送王新侯归宜兴王叔琬归宝坻', '陈恭尹', '明代', '并辔非为汗漫游，燕吴万里一归舟。大江中路分南北，五岭重来定夏秋。\n\n冰下跃鳞桃浪细，岸边闻鸟柳风柔。诗家能事春唯甚，箧里新添是唱酬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春初送王新侯归宜兴王叔琬归宝坻' AND p.poem_author = '陈恭尹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('余石月挽词 其二', '周必大', '宋代', '自我居洪府，从公父子游。至言今在耳，往事忍回头。\n\n风急唐山垄，云埋石月楼。生刍无路奠，洒泪寄东流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '余石月挽词 其二' AND p.poem_author = '周必大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贾思协引河西语', '佚名', '隋代', '贷我东墙。偿我田粱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贾思协引河西语' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('平定州', '玄烨', '清代', '劳农岂惮元英节，寒景风沙透体来。志有鹊山无觅处，目前常见冻云回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '平定州' AND p.poem_author = '玄烨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上达奚舍人', '孟郊', '唐代', '北山少日月，草木苦风霜。贫士在重坎，食梅有酸肠。 \n 万俗皆走圆，一身犹学方。常恐众毁至，春叶成秋黄。 \n 大贤秉高鉴，公烛无私光。暗室晓未及，幽行涕空行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上达奚舍人' AND p.poem_author = '孟郊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和裴司空酬满城杨少尹', '张籍', '唐代', '圣朝偏重大司空，人咏元和第一功。拥节高临汉水上， \n 题诗远入舜城中。共惊向老多年别，更忆登科旧日同。 \n 谁不望归丞相府，江边杨柳又秋风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和裴司空酬满城杨少尹' AND p.poem_author = '张籍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归自萧氏园作', '高叔嗣', '明代', '到来日已暮，归去恋柴门。\n空自山当舍，其如酒满尊。\n心知柳叶长，愁见桃花繁。\n立马一回首，令人思故园。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归自萧氏园作' AND p.poem_author = '高叔嗣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游黄山', '恽代英', '近代', '久闻人说黄山好，今日欣登始信峰；列嶂有心争峻秀，古松无语兀龙钟；置身霄汉星辰近，俯首尘寰烟雾封；到此方知是云海，下藏幽壑几千重。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游黄山' AND p.poem_author = '恽代英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('姑苏即事', '宋褧', '元代', '娃儿十五瘦腰肢，眼角红妆浅淡施。闻道阿娘将典却，揭帘催唤买燕支。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '姑苏即事' AND p.poem_author = '宋褧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东湖', '李覯', '宋代', '古郡城池已瞰江，重湖更在郡东方。\n水仙坐下鱼鳞赤，龙女门前橘树香。\n路绝尘埃非洒扫，地无风雨亦清凉。\n使君待客多娱乐，只有醒时觉异乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东湖' AND p.poem_author = '李覯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('院中葵', '庞尚鹏', '明代', '苍颜本非杨柳质，幽香不似芝兰室。年年空有岁寒心，万绿丛中长捧日。\n\n公馀坐对满枝红，岂羡江陵千树橘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '院中葵' AND p.poem_author = '庞尚鹏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻警 其四', '王世贞', '明代', '闻道黄金募，新屯海上兵。败亡谁后殿，剽掠敢横行。\n\n战血鼋鼍集，愁魂鸟雀惊。欲归无寸土，何敢论浮生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻警 其四' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('往德安过东林寺读始祖唐御史公诗韵六首 其六', '黄仲昭', '明代', '未了公家事，匆匆少暇时。偶因逢老衲，聊共话心期。\n\n倦骥悲尘皂，痴鸠忆故枝。君恩犹未报，行路敢差池。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '往德安过东林寺读始祖唐御史公诗韵六首 其六' AND p.poem_author = '黄仲昭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽赵止善 其二', '牟巘', '宋代', '昔日三株树，彫容顿可惊。一癯危独坐，多难失孤撑。\n\n官舍煎茶梦，天涯裹饭情。无由送车后，抆泪愧平生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽赵止善 其二' AND p.poem_author = '牟巘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('筑墙谣 其二', '连佳樗', '清代', '县吏下马，挥鞭戟手。虎咆雷殷，儿啼妇走。老翁指墙，噤若无口。\n\n土在身，木在首。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '筑墙谣 其二' AND p.poem_author = '连佳樗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻雁 其一', '王弘诲', '明代', '萧瑟燕山一叶秋，征鸿声断暮云流。不知今夜长门月，多少班姬梦里愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻雁 其一' AND p.poem_author = '王弘诲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送别秦明府 其三', '金科豫', '清代', '迢递三川水，应嗟行路难。丹山牛肺峡，白浪虎须滩。\n\n怪石兼天涌，阴云匝地寒。吟髭霜几许，休对镜中看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送别秦明府 其三' AND p.poem_author = '金科豫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('官满寓济川馆得叶嘉仲和朱宰梅花诗次韵云作', '戴栩', '宋代', '旷野多风雪，阳和一点通。\n不应歌兕虎，吾道岂其穷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '官满寓济川馆得叶嘉仲和朱宰梅花诗次韵云作' AND p.poem_author = '戴栩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青海卧疾之作 其二', '佚名', '唐代', '邂逅遇迍蒙，人情讵见通？昔时曾虎步，即日似禽笼。\n\n有命如朝露，天依类断蓬。缅怀知我者，荣辱杳难同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青海卧疾之作 其二' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二月', '陈永正', '当代', '二月风如吻，温存到野塘。溶溶开笑靥，草草著情妆。\n\n山色远摇梦，水花时度香。也知临步口，曾几欲褰裳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二月' AND p.poem_author = '陈永正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('遣怀二首 其二', '陈镒', '元代', '不出门庭腰脚顽，幅巾短褐称萧闲。墨浓砚石迷雊眼，香暖炉烟起博山。\n\n睡美黑甜便老懒，饮酣白堕息机关。今秋已负登高兴，空想重岩细菊斑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '遣怀二首 其二' AND p.poem_author = '陈镒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苑外至龙兴院作', '储光羲', '唐代', '朝游天苑外，忽见法筵开。山势当空出，云阴满地来。 \n 疏钟清月殿，幽梵静花台。日暮香林下，飘飘仙步回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苑外至龙兴院作' AND p.poem_author = '储光羲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送文仲子应举', '温纯', '明代', '交游三世似金兰，此日箕裘数二难。衣钵承家仍旧武，鹡鸰比翼向长安。\n\n逢时桃李花呈实，奔月嫦娥桂遇丹。上苑醉馀齐许国，老夫不复梦邯郸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送文仲子应举' AND p.poem_author = '温纯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题李公麟山庄图', '苏辙', '宋代', '山开稍有路，水放亦成川。游人得所息，真意方澹然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题李公麟山庄图' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿云际寺赠深上人', '李端', '唐代', '暂别青蓝寺，今来发欲斑。独眠孤烛下，风雨在前山。 \n 坏宅终须去，空门不易还。支公有方便，一愿启玄关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿云际寺赠深上人' AND p.poem_author = '李端';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杨柳枝', '袁思亮', '近代', '莫向吴宫怨绮罗。屧廊无复旧人过。平明一阵骑秋雨，惟有髡枝得泪多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杨柳枝' AND p.poem_author = '袁思亮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('属疾', '晃逈', '宋代', '精惊成勤瘁，颐贞俟有瘳。\n吟生南越思，慈结北堂忧。\n粲忱甘为蝶，丰厨厌炙牛。\n玄元知寡欲，平子尚多愁。\n夕鸟侵阶啄，宵萤入树流。\n玉书能静览，柱史倦闲投。\n忽赋行云什，堪听击壤讴。\n期君整朝佩，仙置在瀛洲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '属疾' AND p.poem_author = '晃逈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽汪元明', '吴景奎', '元代', '幽贞甘苦节，力学欲名家。齐户怜孤子，遗书尚五车。\n\n鸰原人泣血，鸾镜发为髽。新冢谁题墓，青山日易斜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽汪元明' AND p.poem_author = '吴景奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('首春九日寿溪三绝', '刘克庄', '宋代', '陶子经丘又寻壑，庞公上塚亦携家。\n可怜春事今年早，落尽桃花落杏花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '首春九日寿溪三绝' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日有感因诵王元之送文元公诗云追思元白在江东不似晁丞今独步之句戏作', '晁说之', '宋代', '三吴山水喜秋风，白蟹青虾甬水东。独步晁丞孙子到，谁怜憔悴众人中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日有感因诵王元之送文元公诗云追思元白在江东不似晁丞今独步之句戏作' AND p.poem_author = '晁说之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠樊夫人诗', '裴航', '唐代', '向为胡越犹怀想，况遇天仙隔锦屏。 \n 傥若玉京朝会去，愿随鸾鹤入青冥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠樊夫人诗' AND p.poem_author = '裴航';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('总使生日乐语', '王子俊', '宋代', '丹青步武是家传，夜泛灵槎下九天。\n才看收驹霜满节，旋观董饷地流钱。\n初天有谱行归辅，阅世无疆不计年。\n馏支锋车趣东去，座中舐亦俱仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '总使生日乐语' AND p.poem_author = '王子俊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄叶道亨', '杨慎', '明代', '欲截珊瑚作钓槎，旋随鸥鸟狎云沙。美人不隔他乡月，迁客何妨著处家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄叶道亨' AND p.poem_author = '杨慎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('禫后述哀用祥韵四首 其三', '李东阳', '明代', '百身难赎两年悲，转觉悲来病力微。月落空堂惊梦短，草青深院识春归。\n\n浮生迹在云俱变，客泪痕多雨似稀。应谢西涯旧时柳，泣风愁雨共依依。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '禫后述哀用祥韵四首 其三' AND p.poem_author = '李东阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵陈季邻户部旦过庵', '范成大', '宋代', '宦游触处似悬匏，北岳南山想献嘲。\n拍手百年休铸铁，盖头一把暂诛茅。\n玉京岁晚梧桐落，水国霜清橘柚包。\n飞锡已随归梦去，何人项上鹊成巢？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵陈季邻户部旦过庵' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('方量牧地次韵工曹王亚叟', '傅察', '宋代', '朝廷遮事备成康，郡邑承风底事忙。\n要使幅员无旷土，始知冀北有留良。\n疏狂似我徒劳耳，术业如君讵易量。\n奔走幸容陪笑语，每观醉墨屡琳琅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '方量牧地次韵工曹王亚叟' AND p.poem_author = '傅察';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('海藏楼杂诗 其二十二', '郑孝胥', '清代', '蛰仙将入觐，忠愤不可当。我于三薰之，少安莫怒张。\n\n事君信乃谏，未信必两伤。百伤亦不惜，知子抱烈肠。\n\n天下事之大，气平臂奚攘。睹子朴直姿，当使群疑亡。\n\n多言定何益，无欲谁则刚。朝廷患多欲，孰知我非狂？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '海藏楼杂诗 其二十二' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吾琴所为曹令所坏寓居赋秋风破屋歌', '叶颙', '元代', '君不见南山叟，一室容身小如斗。闭门僵卧学袁安，雪打风吹懒开口。\n\n又不见牛马走，短布单衣寒露肘。长途汨没笑李斯，咸阳市上牵黄狗。\n\n男儿壮志要似渭川云梦竹，不染尘埃出林麓。又似苍颜劲节松，偃蹇孤高立岩谷。\n\n雪中矫矫舞游龙，霜里涓涓濯寒玉。春和长有拂云青，岁寒岂减昂霄绿。\n\n野人旷荡无所归，居无华屋膳无肉。胸涵胆气欲食牛，世乏才能耻干禄。\n\n高眼不复梦功名，信步何曾限南北。行藏无碍独纵横，动静随缘少拘束。\n\n从来任运合天真，坦率人皆笑粗俗。儒生性僻不入时，身老乾坤忘宠辱。\n\n囊虚买誉百两金，日籴充饥五升粟。顽然空洞腰十围，唯贮文章满斯腹。\n\n谩开电目烛五行，徒援霜毫写千幅。祗闻张奉贱毛生，未见夷吾怜鲍叔。\n\n短琴一弄固有馀，长铗三弹常不足。噫戏安得乐天都盖洛阳城里万丈之白裘，杜陵大庇天下寒士万间之广屋。\n\n尊贤重道贻今羞，大厦宽袍遂吾欲。床头更有酒新熟，绿蚁濡唇斟百斛。\n\n此时不愿万户侯，何心更作九州牧。山中宰相乐馀年，管领丘园慰幽独。\n\n云边吟咏足逍遥，月下壶觞倍清淑。闲铺棋局伴炉薰，满吸湖光饮山渌。\n\n含烟细草叠芳茵，过雨馀花呈绣褥。王侯卿相非我俦，牧圉樵渔是予属。\n\n四时佳景尽来归，泉石烟霞皆素蓄。笑拖长袖醉春风，寄傲轩窗百斯福。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吾琴所为曹令所坏寓居赋秋风破屋歌' AND p.poem_author = '叶颙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高宗建炎初祀昊天上帝', '佚名', '隋代', '治极发闻，不瑕有芬。\n嘉玉陈幣，神国欣欣。\n诚心昭著，钦恭无文。\n以妥以侑，笃祜何垠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高宗建炎初祀昊天上帝' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送潘雪松柱史建言谪闽三首 其二', '袁宗道', '明代', '片帆南下碧江湄，秋月芦花绾别离。此去莫惊潘鬓改，止缘忧国半成丝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送潘雪松柱史建言谪闽三首 其二' AND p.poem_author = '袁宗道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('君王画阵看', '林希逸', '宋代', '圣世忧边切，骚骚羽檄忙。凯歌来幕府，画阵奏君王。\n\n宸陛千官庆，军书一卷长。捲舒从御榻，想像到沙场。\n\n此日丹青笔，当时赤白囊。会看麟阁上，图写更辉煌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '君王画阵看' AND p.poem_author = '林希逸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠刘讽', '苏涣', '宋代', '林下人归少，君归不待年。\n能令两蜀士，叹甚二疏贤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠刘讽' AND p.poem_author = '苏涣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高宗皇帝挽词 其一', '黄谦', '宋代', '火德兴王统，天威詟犷夷。重恢周境土，复振汉威仪。\n\n显号崇瑶册，耆年庆玉卮。鼎成龙去远，扳慕不胜悲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高宗皇帝挽词 其一' AND p.poem_author = '黄谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高邮陈直躬处士画雁二首', '苏轼', '宋代', '野雁见人时，未起意先改。\n君従何处看，得此无人态。\n无乃槁木形，人禽两自在。\n北风振枯苇，微雪落璀璀。\n惨淡云水昏，晶荧沙砾碎。\n弋人怅何慕，一举渺江海。\n众禽事纷争，野雁独闲洁。\n徐行意自得，俯仰苦有节。\n我衰寄江湖，老伴杂鹅鸭。\n作书问陈子，晓景画苕霅。\n依依聚圆沙，稍稍动斜月。\n先鸣独鼓翅，吹乱芦花雪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高邮陈直躬处士画雁二首' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿黄运使', '度正', '宋代', '南海之中三神山，高出天宇超人寰。\n上有神仙百万宅，琼栏瑶楯相回还。\n四方鳞鳞中杰观，不知谁氏当中间。\n或云黄帝之后已百世，云仍诜诜褒衣博带千官班。\n向来山泽癯，晦伏潜深湾。\n是家老仙伯，下顾目所瞷。\n中夜舞鸾凤，明朝排天关。\n自从放出一头地，长江大河声潺湲。\n东皇回跸鼓万象，和气袭人春初颁。\n云裾霞佩来何所，巍峨步趋貌则闲。\n生香馥郁浮四座，得未曾有天非悭。\n至人之子饫芳味，欲揭北斗高莫攀。\n丹霄争看来驿骑，衮衣直上承天颜。\n上论唐虞开稷契，下及草野兼庸孱。\n嗣德之继发馀响，未必政尔诗书删。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿黄运使' AND p.poem_author = '度正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酦醅', '吾丘衍', '元代', '银河泻液迎春风，摇光泛影琉璃钟。芙蓉泣霜腻香薄，石髓滴花浮玉虫。\n\n氍毹红深五云热，漏壶水尽蟾蜍渴。欲借金茎一寸冰，满堂笑看妲娥月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酦醅' AND p.poem_author = '吾丘衍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归兴诗 其十四', '张萱', '明代', '家信来前日，客游能几时。县官新税急，乡里旧人稀。\n\n更忆含饴母，遥嗔失学儿。回言寄驿使，八月是归期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归兴诗 其十四' AND p.poem_author = '张萱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('集句', '章以荣', '近代', '若为趋竞怆离忧，得即高歌失即休。看取汉家何事业，故国东来渭水流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '集句' AND p.poem_author = '章以荣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同黎惟敬询韩子成病 其二', '欧大任', '明代', '同谢鹓鸿侣，而私丘壑身。赐衣沽酒尽，积俸买山贫。\n\n梦蝶閒园吏，怀荃托楚臣。因君上书早，偏忆岭南春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同黎惟敬询韩子成病 其二' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阅战国策有感而言十首 其八 司马子期怒羊羹', '郭之奇', '明代', '当厄休言少，伤心不在深。一杯相怨毒，司马甚羊斟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阅战国策有感而言十首 其八 司马子期怒羊羹' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('婺源邑中', '方回', '宋代', '天地初开孰结融，一溪千折万山重。\n县城似绕流觞水，郡路多由对镜峰。\n祠庙骏奔乾竺会，乡邦鸿硕兗邹封。\n版图三万东南有，二事无能可比踪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '婺源邑中' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('层翠楼', '吴龙翰', '宋代', '结楼书屋傍，独占林塘幽。\n飞檐瞰寒碧，照影虹霓浮。\n层峦万苍翠，峭屼生戈予。\n黛眉与螺髻，故故含娇羞。\n此时楼中人，片心随白鸥。\n风吹乌纱帽，露滴紫绮裘。\n白云入我望，逸兴何悠悠。\n沆瀣供晨餐，酌以碧玉瓯。\n朝暾散朱景，嚥约十二楼。\n愿言追黄鹤，致身八极游。\n慷慨笛声发，满楼明月秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '层翠楼' AND p.poem_author = '吴龙翰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和钱未斋所寄续赋榴子诗', '徐庸', '明代', '大钧生物有奇功，润泽吹嘘雨又风。榴子桂花今古事，一枝要比五枝红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和钱未斋所寄续赋榴子诗' AND p.poem_author = '徐庸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋夜吟', '詹同', '明代', '桂树丛丛月如雾，山中故人读书处，白露湿衣不可去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋夜吟' AND p.poem_author = '詹同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜发龙潭二首 其一', '萨都剌', '元代', '孤舟一夜发龙湫，水逆风回上石头。暂泊沙洲过夜半，卧听钟鼓是升州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜发龙潭二首 其一' AND p.poem_author = '萨都剌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋晚登城北楼', '陆游', '宋代', '幅巾藜杖北城头，卷地西风满眼愁。\n一点烽传散关信，两行雁带杜陵秋。\n山河兴废供搔首，身世安危入倚楼。\n横槊赋诗非复昔，梦魂犹绕古梁州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋晚登城北楼' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其三', '方士繇', '宋代', '不复云軿去自留，却凭飞鹊集中流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其三' AND p.poem_author = '方士繇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('密谷行', '耶律铸', '元代', '命骁锐，为声援，选步骑，发畿甸。号称一百万，一一皆精鍊。\n\n旌旗虹乱渡桑乾，绚野如花陈组练。移围布陈密谷口，吞敌出奇将伺便。\n\n前拒避贾勇，中坚已受战。天兵震天威，不异弄雷电。\n\n先驱游击队，势若风云变。雕鹗横秋空，奋翼鸷鸡犬。\n\n斯须跆藉尽八九，终了不曾还一箭。永安宫，大安殿，方待凯旋回赐宴。\n\n唯有孤臣鬓成雪，缘底眉头殊不展。智谋士见未然事，窃叹终皆非所辩。\n\n堪怜当日金源氏，谁编良将忠臣传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '密谷行' AND p.poem_author = '耶律铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('河汉篇', '张昱', '元代', '河汉亘天几万里，鹑火西行入箕尾。金气浮空漾白波，任是雄风吹不起。\n\n一河之水皆空青，往还惟此乌鹊翎。太史不识汉使者，却奏张骞为客星。\n\n载回织女支机石，牵牛隔河来不及。二十八宿有常经，七夕胡能会灵匹？\n\n西牛东女长相望，女则织纴牛服箱。人间儿女谩愁思，河影不灭秋夜长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '河汉篇' AND p.poem_author = '张昱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('司马公既命片云矣更谓余命一字忆公高唐记神女小字瑶姬请遂辍以字之公笑曰可并为赋一绝句', '胡应麟', '明代', '仙姬环佩下瑶台，握手桃花万树开。日暮巫山行雨去，莫教人拟片云来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '司马公既命片云矣更谓余命一字忆公高唐记神女小字瑶姬请遂辍以字之公笑曰可并为赋一绝句' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六州歌头 壶口观瀑', '吴金水', '当代', '沉沉九曲，唯此一咆哮。烟雨暗，雷霆走，撼岧峣。动青霄。\n\n惊看涛摧处，飞湍激，喷沫溅，重岩裂，平地陷，出龙漕。\n\n浪涌波翻，应舞重渊下，百丈鼍蛟。骇层林尽脱，乱叶卷商飙。\n\n岭际飘萧。接云高。\n\n叹中原下，流常断，膏腴境，几枯焦。时易改，沧桑幻，抚霜毛。\n\n意迢遥。追想炎黄迹，尧舜梦，禹功劳。今日里，何处更，听箫韶。\n\n独上河干徙倚，杯空把、块垒难浇。问洪流安得，万里尽滔滔。\n\n大海同潮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六州歌头 壶口观瀑' AND p.poem_author = '吴金水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('利仁北街作', '白居易', '唐代', '草色斑斑春雨晴，利仁坊北面西行。 \n 踟蹰立马缘何事，认得张家歌吹声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '利仁北街作' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词 其九十六', '王圭', '宋代', '翡翠盘龙装绣额，真珠双凤蹙花球。时闻玉女牵帘笑，箭跃铜壶不算筹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词 其九十六' AND p.poem_author = '王圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('嘉定二年册皇太子四首 其四', '郊庙朝会歌辞', '宋代', '震荐体象，我储明兮。涣扬显册，我礼成兮。大驾言旋，警跸鸣兮。\n\n燕祉无疆，邦之荣兮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '嘉定二年册皇太子四首 其四' AND p.poem_author = '郊庙朝会歌辞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上山采蘼芜', '佚名', '两汉', '上山采蘼芜，下山逢故夫。\n长跪问故夫，新人复何如？\n新人虽言好，未若故人姝。\n颜色类相似，手爪不相如。\n新人从门入，故人从閤去。\n新人工织缣，故人工织素。\n织缣日一匹，织素五丈余。\n将缣来比素，新人不如故。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上山采蘼芜' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过上海寨昔人于此潴水以限北方', '项安世', '宋代', '原田漫漫不知津，春寨清明思杀人。\n雨后烧痕无润泽，烟中日色少精神。\n吨城南池沟隍古，海寨东西径遂新。\n谁见当时经画意，只今高浪化征尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过上海寨昔人于此潴水以限北方' AND p.poem_author = '项安世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('草虫杂图四十二首为伍佥宪题 其二十五', '张宁', '明代', '文蛾好明死，乌鲗以蔽彰。争如草上飞，无用亦无防。\n\n渴饮零露华，逝借晨风扬。何如蜉蝣群，朝生夕云亡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '草虫杂图四十二首为伍佥宪题 其二十五' AND p.poem_author = '张宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虎丘饯别', '皇甫汸', '明代', '解道禅机色是空，犹将别怨恼休公。当筵一掬伤心泪，洒向天花并作红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虎丘饯别' AND p.poem_author = '皇甫汸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '谢举廉', '宋代', '万时一时开骥足，百年今始破天荒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '谢举廉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('柳梢青·申白苛留', '刘克庄', '宋代', '申白苛留。绮园浪出，老不知羞。输与先生，一枝鹤膝，一领羊裘。便教赐履营丘。争似把、渔竿到头。冷落磻溪，张皇牧野，著甚来由。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '柳梢青·申白苛留' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂六十五首 其三十一', '释咸杰', '宋代', '方脱钟山阶级难，却来遮里养残躯。那知踪迹难遮掩，又见驱驰走使符。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂六十五首 其三十一' AND p.poem_author = '释咸杰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟夜', '倪伟人', '清代', '寒月挂危樯，惊波下大荒。秋风千里雁，砧杵万家霜。\n\n独夜看长剑，疏镫倚隐囊。何人吹玉笛，愁思乱江乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟夜' AND p.poem_author = '倪伟人';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋怀二首寄圣俞 其二', '欧阳修', '宋代', '群木落空原，南山高巃嵷。巉岩想诗老，瘦骨寒愈耸。\n\n诗老类秋虫，吟秋声百种。披霜掇孤英，泣古吊荒冢。\n\n琅玕叩金石，清响听生悚。何由幸见之，使我涤烦冗。\n\n飞鸟下东南，音书无日捧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋怀二首寄圣俞 其二' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑子　多一句', '卢青山', '当代', '堤边想又生春草，满目凄迷。满目凄迷，偶落红钗，犹在竹边篱？\n\n杨枝欲住风难住，旧事谁提？旧事谁提，不奈萦魂，又到小桥西。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑子　多一句' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂二百零五首 其二○二', '释正觉', '宋代', '演出一大藏，明明超过诸缘上。随曲随直也流水转山，随高随下也虚舟驾浪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂二百零五首 其二○二' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠吴子野道人', '苏辙', '宋代', '食无酒肉腹亦饱，室无妻妾身自好。\n世间深重未肯回，达士清虚辄先了。\n眼看鸿鹄薄云汉，长笑驽骀安栈皂。\n腹中夜气何郁郁，海底朝阳常杲杲。\n一廛不顾旧山深，万里来看故人老。\n空车独载王阳橐，远游屡食安期枣。\n东州相逢真邂逅，南国思归又惊矫。\n道成若见王方平，背疗莫念麻姑爪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠吴子野道人' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和武公望从人觅酒二首 其一', '廖行之', '宋代', '野店醪香尚带烟，中山酝久漫经年。公营恶草安吾分，太白高吟羡子先。\n\n好办一尊常对月，谁能百斛更浮川。正须浇我谈天口，富贵浮云且任缘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和武公望从人觅酒二首 其一' AND p.poem_author = '廖行之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望湖楼', '陈上庸', '明代', '清迥凭湖侧，高轩枕水湄。望收青草阔，閒与白云期。\n\n落日凝寒雾，衰藤挂短枝。亭从天外赏，山许镜中窥。\n\n棹舫堤桥过，攀崖拥露跻。笛残知牧返，歌歇识渔疲。\n\n鸥尽忘机日，花多解语时。芄兰公子佩，秋水美人思。\n\n信有庾公酒，能无王粲词。下临虽不极，上出岂如斯。\n\n睇目神将远，濯缨吾在兹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望湖楼' AND p.poem_author = '陈上庸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题吴参议达观斋', '袁燮', '宋代', '朱公胸次清绝尘，吴公当日心相亲。\n风流蕴藉接前辈，寥寥斯世能几人。\n达观名斋深有意，欲把前修相警厉。\n只今吴公德弥劭，始信磨砻成伟器。\n古人心广体亦胖，纷纷世俗争豪端。\n已私未克欲求道，窥见一二皆童观。\n达人大观观底事，天地为物原不贰。\n痒疴疾痛皆吾身，彼我胡为分贱贵。\n达观主人心地明，分符赞幕无亏成。\n每言此身非我有，年来直欲非死生。\n白发红颜难老态，福禄方隆殊未艾。\n愿君善保千金躯，归觐紫宸锵剑佩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题吴参议达观斋' AND p.poem_author = '袁燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠苗员外', '耿湋', '唐代', '为郎日赋诗，小谢少年时。业继儒门后，心多道者期。 \n 晚回长乐殿，新出夜明祠。行乐西园暮，春风动柳丝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠苗员外' AND p.poem_author = '耿湋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送友人还广州 其二', '王藻', '清代', '闻道天南路，山川秀且清。花田刘鋹墓，珠海赵佗城。\n\n汉月蟾蜍满，秦桥螮蝀横。无由能缩地，天末远舍情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送友人还广州 其二' AND p.poem_author = '王藻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题宣上人栖碧轩', '朱同', '明代', '谪仙不答俗人问，此是西来第一禅。究竟本无文字教，品题犹有短长篇。\n\n轩开净几云生座，栏瞰清溪水涨川。忽忆门前车马事，故知宣老即青莲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题宣上人栖碧轩' AND p.poem_author = '朱同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵刘贡父和韩康公忆其弟持国二首', '苏辙', '宋代', '霜风瑟瑟卷梧蕉，燕处超然夜寂寥。\n羽客信来丹鼎具，石淙梦断水声遥。\n赤松作伴谁当见，黄鹄高飞未易招。\n剑履终身定何益，勤劳付与沛中萧。\n爱君忧世老弥深，特操要须得失临。\n晚岁飞腾推有德，故乡安稳信无心。\n小邦近似西山隐，元气终当北斗斟。\n圣主方求三世旧，老臣何止一遗簪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵刘贡父和韩康公忆其弟持国二首' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和刘后村杂兴 其八', '胡仲弓', '宋代', '近学时妆越样新，空遗畎亩处忠臣。烛之武老未为老，刘伯龙贫可是贫。\n\n造物不应推若辈，江山亦合助诗人。挂冠神武当年事，明哲从来要保身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和刘后村杂兴 其八' AND p.poem_author = '胡仲弓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('碧桐清暑图', '钱蘅生', '清代', '微风起处落桐花，为爱清凉坐碧纱。静听蝉声声远近，曲栏面面绿阴遮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '碧桐清暑图' AND p.poem_author = '钱蘅生';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乌江望霸王庙', '黄淳耀', '明代', '英雄垓下尽，尺土占江濆。虎失关中势，龙嘘霸上云。\n\n人怜公百战，鬼阅汉三分。薄暮风涛恶，疑崩钜鹿军。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乌江望霸王庙' AND p.poem_author = '黄淳耀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑子 秋风，和痴萍韵', '傅熊湘', '清代', '秋风无力吹侬起，病怯登楼。况是多愁。一夜相思天尽头。\n\n欢悰别后那堪说，泪似泉流。心自人留。争道今生死便休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑子 秋风，和痴萍韵' AND p.poem_author = '傅熊湘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵即席', '范成大', '宋代', '留连银烛照金荷，肠断华年一掷梭。\n月姊有情难独夜，天孙无赖早斜河。\n晶晶霜瓦寒生粟，衮衮风帏细涌波。\n鸹鶡晓啼鸣鹊散，许多佳景奈愁何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵即席' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五言今体诗二十五首 其七', '朱谋㬜', '明代', '城郭归来远，山斋闭晚烟。窗虫浮研水，壁鼠败琴弦。\n\n旧社书堪借，寒宵烛可然。布裘霜气入，未叠木花绵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五言今体诗二十五首 其七' AND p.poem_author = '朱谋㬜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诗偈 其一一四', '庞蕴', '唐代', '莫求佛兮莫求人，但自心里莫贪瞋。贪瞋痴病前顿尽，便是如来的的亲。\n\n内无垢兮外无尘，中间豁达无关津。神无障碍居三界，恰是琉璃处日轮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诗偈 其一一四' AND p.poem_author = '庞蕴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('去春达善分碧桃移植篆畦今春已作蕊达善前有见过之约偶立花下口占寄之 其二', '舒岳祥', '宋代', '前年花在玉堂日，偶和成编竞出奇。今日篆畦同寂寞，碧桃无语我无诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '去春达善分碧桃移植篆畦今春已作蕊达善前有见过之约偶立花下口占寄之 其二' AND p.poem_author = '舒岳祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('牡丹', '马氏', '明代', '翠雾红云护短墙，豪华端称作花王。洛阳宫里杨妃醉，吴国台前西子妆。\n\n芳露淡匀腮粉腻，暖风轻度口脂香。开时亦自知珍重，静镇东风白昼长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '牡丹' AND p.poem_author = '马氏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红 和豁轩「对月有怀」韵', '林朝崧', '清代', '梦断西楼，又还对旧时凉月。凭栏久，满襟香露，木犀熏彻。\n\n曾笑蟾蜍偷药误，青天碧海无期别。甚而今，人也隔星河，愁难说。\n\n香奁镜，菱花缺。瑶琴匣，朱弦绝。剩秋风团扇，为谁重设？\n\n追悔芙蓉塘外路，归来轻步凌波袜。向西窗剪烛写难成，相思札。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红 和豁轩「对月有怀」韵' AND p.poem_author = '林朝崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('马上闲吟七首 其二', '施补华', '清代', '白布缠头两辫斜，布回风俗妇持家。密藏马乳旋成酒，细醮牛酥待点茶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '马上闲吟七首 其二' AND p.poem_author = '施补华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题三山天庆观三首', '白玉蟾', '宋代', '渺渺神霄天，玉京何岧峣。\n琼花露泣蕊，琪树风鸣条。\n瑶妃侍云笈，羽童舞金翘。\n嗟彼世间人，红尘徒朝朝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题三山天庆观三首' AND p.poem_author = '白玉蟾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红 工读', '黄绮', '当代', '欲觅何之，笑懦钝、居然乞食。不轻举、身躯七尺，寸肠枯逼。\n\n一代诗狂嗟不见，千群儒竖知何益。喜形如、饥鹄待乘风，舒长翼。\n\n天与海，均寒碧。怃然觉，非孤支。对吾徒版筑，敢羞佣役。\n\n老去家园堪牧豕，年多生产仍亲客。忽披襟、仰视且噫嘻，边云黑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红 工读' AND p.poem_author = '黄绮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再叠前韵答明崖见和', '孙承恩', '明代', '夙有诗魔癖，今叨文会筵。无闻惭往岁，垂老悯流年。\n\n忧世悬微悃，匡时合让贤。媕婀谁则是，意气竟何宣。\n\n自分疏慵废，其如质性偏。玄机难测识，世故浩云烟。\n\n都宪经纶密，明时翊戴全。怜予多老病，下榻称高眠。\n\n消长推天道，欢娱顺自然。寸心徵白日，拙守托苍天。\n\n乔木需时用，丹葵向日妍。撝谦形迹外，放浪酒樽前。\n\n爱士勤三接，劬书览百编。保釐心独至，丹墨手亲研。\n\n高步兹为盛，衰庸愧率先。风流雅传播，事业划回旋。\n\n繫遁吾何敢，含章子自专。讴歌今日事，钟鼎后人镌。\n\n野老歌黄鹄，诗人咏碧涟。雅情真挹损，鄙志亦勤虔。\n\n启助良多矣，才情实歉焉。无能攀逸翮，翘首仰高骞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再叠前韵答明崖见和' AND p.poem_author = '孙承恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其三', '吕惠卿', '宋代', '虚心清暑殿，预戒一阴生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其三' AND p.poem_author = '吕惠卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('踏莎行 秋日偕冯又令过米山堂，时子新痛亡，侄又令复伤仲子，感赋', '钱凤纶', '清代', '罗幕长垂，愁城难破。岑岑病怯慵梳裹。贫居曲径悄无人，篱门一带秋烟锁。\n\n邻女传来，香车初过。眉峰轻拂云鬟亸。相邀花圃共谈心，临流斜倚寒山坐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '踏莎行 秋日偕冯又令过米山堂，时子新痛亡，侄又令复伤仲子，感赋' AND p.poem_author = '钱凤纶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('将归黄山留别诸同学', '孙默', '清代', '伯皋应下谢朝春，回首淮南遍夕烽。客到空城余蔓草，身随孤剑冷芙蓉。\n\n秋深始买江边棹，古寺还听天外钟。黄海只愁迷旧路，仙人丹灶白云封。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将归黄山留别诸同学' AND p.poem_author = '孙默';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('步瑶京族弟「书感」元韵', '王松', '清代', '登高宋玉独悲秋，世事徒烦作杞忧！自昔安危频北望，于今治乱付东流！\n\n问天屈子难埋恨，斫地王郎且寄愁。争奈姓名收不得，近来无计避公侯！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '步瑶京族弟「书感」元韵' AND p.poem_author = '王松';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小金山', '弘历', '清代', '每到小金山，心神顿旷閒。秋深逾觉好，塞上薄言还。\n\n霜叶缤纷落，烟萝取次攀。石桥凌碧汉，拟欲叩仙关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小金山' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天（新春）', '葛胜仲', '宋代', '玉琯还飞换岁灰。定山新棹酒船回。年时梁燕双双在，肯为人愁便不来。 \n 衰意绪，病情怀。玉山今夜为谁颓。年时梅蕊垂垂破，肯为人愁便不开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天（新春）' AND p.poem_author = '葛胜仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其七', '赵炅', '宋代', '君臣千载遇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其七' AND p.poem_author = '赵炅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢小嫏环主惠蚝油', '余菊庵', '当代', '此物原宜侑炙豚，承君厚意赐盈尊。屈才深为蚝油惜，小碟盛来点菜根。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢小嫏环主惠蚝油' AND p.poem_author = '余菊庵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送人赴仓台', '许应龙', '宋代', '帝念畿甸民，财力俱有限。\n俗吏肆贪残，侵渔荡赀产。\n致治在得贤，刺史尤当拣。\n明公如范滂，清节迈杨绾。\n疏宠畀仓台，一道俱刮眼。\n籴贵望公平，敛苛冀公划。\n察吏贵精明，临民当敬简。\n高才固优为，伫见鸠功僝。\n将令愁叹民，喜至笑声莞。\n绣节暂驰驱，玉堂资著譔。\n行矣促公归，饯行聊兴盏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送人赴仓台' AND p.poem_author = '许应龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无题诗次刘虞部韵二首 其二', '汤胤绩', '明代', '杏花枝上晓风寒，镜里愁容不耐看。千里云涛迷下若，五城烟火接长干。\n\n当时偶作来仪凤，此日翻成吊影鸾。恐负远山双黛曲，烛煤轻扫落金盘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无题诗次刘虞部韵二首 其二' AND p.poem_author = '汤胤绩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨行梅关二首 其一', '李昴英', '宋代', '浓岚四合冻云痴，水墨连屏斗崛奇。冲雨此行风景别，满山翠滴水帘垂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨行梅关二首 其一' AND p.poem_author = '李昴英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('野风', '边贡', '明代', '野风吹荻苇，寂寂楚江秋。水气寒侵幌，涛声夜撼舟。\n\n古今双社鸟，天地一沙鸥。欲作怀湘赋，官程不可留。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '野风' AND p.poem_author = '边贡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和都运龙图二首 其一', '曹勋', '宋代', '一时耆旧尽英游，玉节迎銮暂少休。不以秦人视越瘠，载驰楚尾与吴头。\n\n两淮浓被钟离政，一水聊萦杜若洲。行见锋车还禁橐，已看仁化浃鱼鸥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和都运龙图二首 其一' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题翠蛟亭', '胡矩', '宋代', '山英藏水巧能欺，动地雷声发骇机。惊看玉渊千浪耸，挽回银浦一支飞。\n\n流霞未引松花酒，湔雪先沾槲叶衣。坐觉群仙生起色，倒倾蛟室泻珠玑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题翠蛟亭' AND p.poem_author = '胡矩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠从弟南平太守之遥二首', '李白', '唐代', '少年不得意，落拓无安居。\n愿随任公子，欲钓吞舟鱼。\n常时饮酒逐风景，壮心遂与功名疏。\n兰生谷底人不锄，云在高山空卷舒。\n汉家天子驰驷马，赤军蜀道迎相如。\n天门九重谒圣人，龙颜一解四海春。\n彤庭左右呼万岁，拜贺明主收沉沦。\n翰林秉笔回英眄，麟阁峥嵘谁可见？\n承恩初入银台门，著书独在金銮殿。\n龙驹雕镫白玉鞍，象床绮食黄金盘。\n当时笑我微贱者，却来请谒为交欢。\n一朝谢病游江海，畴昔相知几人在？\n前门长揖后门关，今日结交明日改。\n爱君山岳心不移，随君云雾迷所为。\n梦得池塘生春草，使我长价登楼诗。\n别后遥传临海作，可见羊何共和之。\n\n东平与南平，今古两步兵。\n素心爱美酒，不是顾专城。\n谪官桃源去，寻花几处行？\n秦人如旧识，出户笑相迎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠从弟南平太守之遥二首' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('路逢徽州送牡丹入都', '洪咨夔', '宋代', '飞絮游弄霁中华，出门芳草渺天涯。\n太平莫道全无象，脱绣鸣铃传送花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '路逢徽州送牡丹入都' AND p.poem_author = '洪咨夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送章季亨', '赵蕃', '宋代', '随檄常怀舍旧庐，值公作邑数旬余。\n摄官敢道为僚契，投迹仍容借屋居。\n诗社三的陪唱属，交情一意保终初。\n莫嗟了事真良苦，去读人间未见书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送章季亨' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('箜篌谣', '李白', '唐代', '攀天莫登龙，走山莫骑虎。\n贵贱结交心不移，唯有严陵及光武。\n周公称大圣，管蔡宁相容。\n汉谣一斗粟，不与淮南舂。\n兄弟尚路人，吾心安所从。\n他人方寸间，山海几千重。\n轻言托朋友，对面九疑峰。\n开花必早落，桃李不如松。\n管鲍久已死，何人继其踪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '箜篌谣' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('田侍郎 其三', '王建', '唐代', '踏著家乡马脚轻，暮山秋色眼前明。老人上酒齐头拜，得侍中来尽再生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '田侍郎 其三' AND p.poem_author = '王建';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小重山', '元好问', '金朝', '醉尽春风意未阑。缠头双凤锦、觅端端。多情胡蝶送归鞍。\n\n扬州梦，芍药荐金盘。\n\n罗幌酒醒寒。灯前朱麝浅、翠螺残。一春心事苎衣宽。\n\n青鸾客，楼外日三竿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小重山' AND p.poem_author = '元好问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('朱大司空挽歌八首 其六', '于慎行', '明代', '真宅归丹府，蓬壶第几城。化龙应是剑，跨鹤不闻笙。\n\n旧戟朱门列，新阡紫气萦。元公车服在，馀庆属玄成。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '朱大司空挽歌八首 其六' AND p.poem_author = '于慎行';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂感五首以不爱入州府为韵 其五', '陆游', '宋代', '我年甫三十，出身事明主。狂愚斥不用，晚辟征西府。\n\n蹭蹬过锦城，邂逅客严武。十年醉郫筒，阳狂颇自许。\n\n青城访隐翁，西市买幽圃。如何复不遂，归听镜湖雨。\n\n结庐三间茅，泛宅一枝橹。天真傥可全，吾其老烟浦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂感五首以不爱入州府为韵 其五' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵杂兴二百首', '苏泂', '宋代', '赏心亭前白鹭洲，淮水东畔水东流。\n只知览古生许恨，不知身世自悠悠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵杂兴二百首' AND p.poem_author = '苏泂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('效赵学士体成口号十章献开府太师', '司马光', '宋代', '首夏清和新雨晴，绿莎细软不妨行。\n园夫遮道白何事，栀子花开斑笋行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '效赵学士体成口号十章献开府太师' AND p.poem_author = '司马光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞姬歌', '屈大均', '明代', '中宵汉兵满，四面楚歌哀。大王多意气，为妾一徘徊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞姬歌' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送汤公子应荐之京', '柳君', '明代', '高冠长剑并嵯峨，许国筹边感慨多。少拟过秦追贾谊，老思用赵忆廉颇。\n\n封侯万里宁非命，募士千金岂论科。执手离亭饶酒伴，飞扬跋扈奈君何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送汤公子应荐之京' AND p.poem_author = '柳君';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('道遇郑莲卿共饮酒楼醉中赠以长歌', '姚燮', '清代', '与人以心不知受，媚人以色那能久？花落堕地为尘埃，旧巷杨枝多老丑。\n\n驱车过珠市，市上逢郑生。停车招我车共停，下车握手奚为情？\n\n别来胸臆不可竟，登楼且作千觞倾。朱轮粼粼过楼下，新坊子弟如名马。\n\n连钱贴尻沫流赭，其气峥嵘猝难惹。数载不踏京华尘，奈何桃李非昔春？\n\n郑生当时冠三曲，热场万口称天人。贵豪侧目承喜嗔，骄宠直欲无虢秦。\n\n深帏剩烛黯已灺，露边孤蝶飞何邻？生言近事愁难语，旧部飘零少完羽。\n\n不虞九市风沙中，短席清樽尚吾汝。狂吟振籁欲回云，苦泪沾衣不成雨。\n\n吁嗟乎，黄金食尽馀宝刀，歌喉久涩徒能箫。回思西邸竞华宴，玉屏列黛敷兰椒。\n\n五年一瞬主三易，门垣乱棘齐马腰。青天鸿鹄各关塞，江河不作西流潮。\n\n何戡老大感犹许，安仁之鬓宜其彫。相依形影转岑索，起看碧汉星寥寥。\n\n谁家公子七叶貂，隔座挥霍矜雄豪。两行红粉烟中苕，流光曼睩生百娇。\n\n颜衰势尽各相弃，明日避面同避獒。惟吾与子具冷眼，阅非一事非一朝。\n\n共斯沦落复谁顾，及早轻装约归去。文纨玉食蛊已深，告退何妨着穷裤？\n\n江南风月不用钱，莫使韶光重贻误。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '道遇郑莲卿共饮酒楼醉中赠以长歌' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵黄斌老晚游池亭二首', '黄庭坚', '宋代', '路入东园无俗驾，忽逢佳士喜同游。\n绿荷菡萏稍觉晚，黄菊拒霜殊未秋。\n客位正须悬榻下，主人自爱小塘幽。\n老夫多病蛮江上，颇忆平生马少游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵黄斌老晚游池亭二首' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏梅', '吴居仁', '宋代', '岭南十月春渐回，妍暖先到前村梅。\n问君何处识此妙，一枝冷艳随霜开。\n长江凛凛欲崩岸，乃见好事多墙隈。\n初疑渗漉入瘴雾，更恐寂寞埋烟煤。\n微风不动暗香远，淡月入户空徘徊。\n坐看粉黛化膻恶，岂但桃李成舆台。\n我行万里厌穷独，疾病未已心先灰。\n对此不觉三叹息，恐是转侧同南来。\n异乡久处少意绪，破壁相对无根荄。\n古来寒士每如此，一世埋没随蒿莱。\n遁光藏德老不耀，肯与世俗相追陪。\n轮囷离奇多见用，牺尊青黄木为灾。\n含毫吮墨去颜色，况自不必须穿裁。\n岁穷路远莫惆怅，此去保无蜂蝶猜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏梅' AND p.poem_author = '吴居仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日即事九首 其七', '李廌', '宋代', '怅望白铜鞮，醉听金缕衣。花间愁落日，老更惜春归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日即事九首 其七' AND p.poem_author = '李廌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西山诗', '陈旅', '元代', '蓐食出西郭，初日明远川。联镳走山麓，山树尽含烟。\n\n紫石拥驰道，绿水侵弄田。高人湖上来，邂逅野涧边。\n\n茂柳垂密幄，层莎布柔毡。回风飒幽爽，有鸟声清圆。\n\n采荷荐珍胏，洗盏行芳泉。芙蓉濯新雨，迥立方婵娟。\n\n晤言摅素抱，逸思慕遐骞。窈窕绀园夕，珠林映璇渊。\n\n黄金作台殿，缥缈集诸天。顾惭凡躅污，亟去不敢邅。\n\n适意无先期，重寻有中悁。华月忽易改，赏心与时迁。\n\n晨兴望云物，皓雪满层巅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西山诗' AND p.poem_author = '陈旅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('钟', '张继先', '宋代', '金晶铸就斗星悬，挂向玉楼知几年。\n好是五更残梦里，一声敲透白云天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '钟' AND p.poem_author = '张继先';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病起', '吴琏', '明代', '一歃歃尽沧溟水，一跳跳上昆崙颠。千钧万钧手提弄，狂夫始觉心悠然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病起' AND p.poem_author = '吴琏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('复闻京师得雨志喜', '弘历', '清代', '二月三寸雨，北地曾希闻。谁谓未十日，尺泽重沾均。\n\n江国作霖易，绿野润春巡。繫思每北望，正待甘膏辰。\n\n何时不重农，何地非吾民。欣慰以为惕，额手鸿钧仁。\n\n畿南将齐郑，因之萦念频。曾否亦溥被，伫待大吏陈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '复闻京师得雨志喜' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白纻歌七首 其四', '何景明', '明代', '吴娥白纻为舞衣，镂花缀叶纷葳蕤。青春烂熳白日辉，轻带一举长袖施。\n\n皎如流霰随风飞，游龙宛转翔鹄回，倾城绝代人共希。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白纻歌七首 其四' AND p.poem_author = '何景明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日居法云兰若 其三', '徐熥', '明代', '古路苍苍入鹫峰，烟霞隔断往来踪。时将真诀灯前课，每与游僧竹下逢。\n\n满架瑶函藏贝叶，远林山色绚芙蓉。闭门晏坐尘缘息，又听云堂起暮钟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日居法云兰若 其三' AND p.poem_author = '徐熥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('漫成二首 其二', '段成己', '金朝', '时序惊何速，形骸强自持。整冠毛屡脱，束带孔频移。\n\n蹭蹬成空老，吟哦不救饥。百年行已久，一笑欲何之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '漫成二首 其二' AND p.poem_author = '段成己';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('齐天乐', '刘永济', '清代', '西风偷换鸣蝉树，綀襟嫩凉先怯。淡霭沉山，稀星堕水，秋阔天容如抹。\n\n瑶宫片月，映深碧层霄，洞然莹彻。万景昏冥，世间惟此最高洁。\n\n今宵谁共胜赏，露萤低自照，如伴凄切。雾冷南楼，波荒北渚，千古风流都歇。\n\n江山俊杰，算一例成尘，浩歌空发。伫久红桥，境清鸥梦接。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '齐天乐' AND p.poem_author = '刘永济';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('点绛唇（紫阳寒食）', '陈与义', '宋代', '寒食今年，紫阳山下蛮江左。竹篱烟锁。何处求新火。 \n 不解乡音，只怕人嫌我。愁无那。短歌谁和。风动梨花朵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '点绛唇（紫阳寒食）' AND p.poem_author = '陈与义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂兴三十九首 其三十三', '张镃', '宋代', '抡才如百药，治效各不同。傥能区别性，当聚和扁功。\n\n武德定乱后，诸公悉登庸。帝久知所长，未欲任巳聪。\n\n品题资确论，毫发无蔽蒙。三杰隆汉业，六英夹唐宗。\n\n无人可能国，我欲振古风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂兴三十九首 其三十三' AND p.poem_author = '张镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜梦故人诗', '何逊', '南北朝', '客心惊夜魂。\n言与故人同。\n开帘觉水动。\n映竹见床空。\n浦口望斜月。\n洲外闻长风。\n九秋时未晚。\n千里路难穷。\n已如臃肿木。\n复似飘飖蓬。\n相思不可寄。\n直在寸心中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜梦故人诗' AND p.poem_author = '何逊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('邦彦饮湖上暮归过保叔大呼求见因赍酒出寺饮', '史鉴', '明代', '半山遥听故人歌，枉驾能为晚寺过。\n饮酒莫辞还秉烛，重来花事恐无多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '邦彦饮湖上暮归过保叔大呼求见因赍酒出寺饮' AND p.poem_author = '史鉴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈', '都贶', '宋代', '不可思议，是大火聚。便恁么去，不离当处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈' AND p.poem_author = '都贶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赤壁', '岳珂', '宋代', '周郎二十四年少，盖世功名随一燎。\n亲提三万走曹瞒，不以敌勍恨兵少。\n豫州失匕已胆折，一日目明惊二妙。\n最怜黄盖不知名，吏士相从倚营啸。\n阿奴火攻本无策，破竹自繇人不料。\n贪降纳侮理固宜，泥淖华容几尽剿。\n西来行师有绝地，毋乃重诒千古笑。\n镞湛纵是差可认，鼎峙讵关谋所召。\n二乔春锁何足言，从此天光遂分耀。\n我闻汉贼久染指，奋毒摇牙噬江表。\n八荒囊括岂复遗，一蹙吴宫已为沼。\n当时乘胜下部骑，考地当居楚南徼。\n蒙冲逆斗须上流，揖寇那容越津要。\n武昌霸基跬步耳，肯使国畿纷戟旐。\n坡仙访古特寓意，横槊雄姿谁与吊。\n故将异地眩疑辞，政恐因讹启讥诮。\n沧浪六月卷晴雪，历历江山人物眇。\n崩空乱石今几存，仿佛栖巢尚惊鸟。\n夜深刁斗声四发，星斗满空群籁悄。\n便须唤起紫绮裘，孤鹤南天楚江晓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赤壁' AND p.poem_author = '岳珂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('罗稚川善画作此赠之', '赵文', '宋代', '吾观天地间，一一皆是画与诗。\n渝川有二罗，画得天地之英奇。\n大罗诗名撼湖海，小罗天机勃郁不得已而水墨之。\n摇毫造化已破碎，洒墨元气为淋漓。\n嗟余老眼得一见，以手扪摸心然疑。\n问君自古画有几，君今此画师者谁。\n君言我以眼为手，天地万物皆吾师。\n吾能得其意与理，貌取色相特其皮。\n画成正未知似否，人人有眼谁可欺。\n譬之禅宗要透脱，恋恋祖佛宁非痴。\n作诗点出未来眼，一扫徐熙与郭熙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '罗稚川善画作此赠之' AND p.poem_author = '赵文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('点头石', '何绛', '明代', '獦獠幡非动，生公石点头。一时捏怪者，流毒在千秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '点头石' AND p.poem_author = '何绛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('还过章江徐巨源邀住榆溪草堂留题四首 其三', '黎遂球', '明代', '江树连云到远峰，不知湖外有城封。龙吟每和摊书幌，鸟下频窥捣墨舂。\n\n遁世祇应师孺子，傍人遥认对林宗。秋花晚实餐无尽，白饭青蔬也累供。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '还过章江徐巨源邀住榆溪草堂留题四首 其三' AND p.poem_author = '黎遂球';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玛瑙坡四咏 其二', '释智圆', '宋代', '玛瑙坡前水，泠泠夏亦寒。夜深明月上，珠颗落冰盘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玛瑙坡四咏 其二' AND p.poem_author = '释智圆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鸳鸯 其二', '许南英', '清代', '一池绿水秀兰苕，争似文禽顾影娇。柳絮飞时毛羽满，荷花深处梦魂摇。\n\n并生合注双双谱，列队分飞六六桥。肠断莫愁湖畔路，小姑居处独无聊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鸳鸯 其二' AND p.poem_author = '许南英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀归', '皇甫汸', '明代', '故园献寿亲能健，春夜开筵兴不违。两地离怀人惜别，暂时欢赏客忘归。\n\n醉听锦瑟歌犹度，仰视银河落渐微。今夕月明江上路，烟波回首泪沾衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀归' AND p.poem_author = '皇甫汸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赞历代天师 第二十六代讳嗣宗', '白玉蟾', '宋代', '朱砂鼎里炼金晶，默祷天皇入紫冥。月落半山丹井水，猿声惊断满天星。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赞历代天师 第二十六代讳嗣宗' AND p.poem_author = '白玉蟾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大行人沈子高赍敕并镪币到太平府赐缜因赠', '王缜', '明代', '云间沈才子，英英脱尘俗。衔命来太平，长揖谦以牧。\n\n势利浮云轻，瞥尔不挂目。清瑟声正稀，骊珠光可掬。\n\n乃知斯人妙，挠之终不浊。所以气味同，倾盖宛如宿。\n\n淡淡春风微，滔滔江水绿。而我欲何为，浩歌倚修竹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大行人沈子高赍敕并镪币到太平府赐缜因赠' AND p.poem_author = '王缜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题计郎中汝和墨菊曹汝学家藏', '顾清', '明代', '郎中画菊真是菊，蒙泉蒲萄太常竹。\n一时能事并驰声，岂直文章难继续。\n狂挥急扫皆称意，不特品高机亦熟。\n西涯坐间生色障，一见当时已心服。\n不知何日到君家，净洗朱铅斗清淑。\n疏篁古木交映带，深浅生枯俱入态。\n欹风一枝惊欲折，倚竹数丛如有待。\n飞鸾坠羽时自压，老蛟蜕骨令人骸。\n张颠草圣久寂寞，何意兹晨忽倾盖。\n郎中郎中今有无，后来尚远眼中疏。\n柔肌脆骨争媚妩，不然蔓草纷黄垆。\n颓波一去谁与返，把卷抚玩增长吁。\n君不见近时淮海上，亦有菊花一派往往传京都。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题计郎中汝和墨菊曹汝学家藏' AND p.poem_author = '顾清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('花犯 萧寺小除夕', '陈洵', '清代', '小林亭，疏灯凝水，年华笑相问。市风吹近。听饯腊家家，人语轻趁。\n\n倦游梦枕萧斋稳。清波闲处引。又藓迹、雪融香径，行行销意尽。\n\n天边雁声送愁多，寒空峭、坐想迟回芳信。吟思短，清尊共，故欢随分。\n\n依稀记、艳阳禊赏，人散后、楼台霏麝粉。漫唤起、阑干私倚，盟春心事准。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '花犯 萧寺小除夕' AND p.poem_author = '陈洵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('于香草圆圈二章，语意隽妙。俞荫甫和作夹杂不伦，恐是酒间呓语，未可以名诗也，因和二章 其一', '曹家达', '清代', '露气涵秋晕夕烟，桂花香发嫩凉天。故山好月难为赠，记取西楼照梦圆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '于香草圆圈二章，语意隽妙。俞荫甫和作夹杂不伦，恐是酒间呓语，未可以名诗也，因和二章 其一' AND p.poem_author = '曹家达';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题隐者', '朱元璋', '明代', '固洁精魂欲上天，幽居深处水云边。烟封远浦沙鸥尽，树锁前山草鹿眠。\n\n书假管城应复路，楮生墨客未回川。逢人更祝坚清志，必日云衢足蹑前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题隐者' AND p.poem_author = '朱元璋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游晓觉寺', '陈睍', '宋代', '肩舆行到竹边村，竹里僧房尽闭门。\n小洞颇闻三里近，残僧今有一人存。\n旋沽薄酒欺寒力，未怯春泥踏雨痕。\n笑觅梅花伴归去，断桥流水月黄昏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游晓觉寺' AND p.poem_author = '陈睍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南歌子', '苏轼', '宋代', '云鬓裁新绿，霞衣曳晓红。待歌凝立翠筵中。一朵彩云何事、下巫峰。 \n 趁拍鸾飞镜，回身燕漾空。莫翻红袖过帘栊。怕被杨花句引、嫁东风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南歌子' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和吴鼎昌达铨', '江庸', '近代', '春到郊西景物妍，海棠庭院举家迁。百年故宅移乔木，十里青山接玉泉。\n\n地熟不知身是客，花开宜与酒为缘。凭栏我也忘归去，莫怪蜂狂蝶更颠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和吴鼎昌达铨' AND p.poem_author = '江庸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辟何休《公羊传》注', '刘慎荣', '清代', '河洛崎崛玉步留，黜周王曾有何休。司空相已炎精夺，掾属覃思十数秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辟何休《公羊传》注' AND p.poem_author = '刘慎荣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暮春即事', '孙元衡', '清代', '枉羡青云切太虚，无端飞堕海东隅。风花露草春绵邈，瘴雨蛮烟梦有无。\n\n肉食纵横清兴少，簿书填委道心孤。缘何倔强羞言老，对镜偷閒镊白须。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暮春即事' AND p.poem_author = '孙元衡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄习豫南太史闽中二首 其二', '于慎行', '明代', '日夕登高台，悠悠望南海。南海不可从，万里阴云霭。\n\n念我同心人，留滞方何在。一出咸阳门，岁事数已改。\n\n眇眇睇空江，晔晔生兰𦶜。日晏江水寒，美人殊不采。\n\n如何桃李颜，含笑扬光彩。保尔岁寒心，芳华自晻霭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄习豫南太史闽中二首 其二' AND p.poem_author = '于慎行';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪中过分水岭六首 其四', '李纲', '宋代', '一夜同云凝不开，晓寒整辔马虺尵。千岩万壑萦纡处，密雪回风散漫来。\n\n愁里溪声琴的历，望中山色玉崔嵬。溪山得雪尤奇绝，模写无工恨不才。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪中过分水岭六首 其四' AND p.poem_author = '李纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长亭怨 为俞廙仙题卧游图', '王闿运', '清代', '记曾探、山阴春晓。思发花前，兴先云到。王谢风流，远情都说宦游好。\n\n玉骢珠舫，刚一洗、酸寒稿。况鹤畔琴边，自指点、年时游钓。\n\n吟啸。正汾阴听雁，又是洞庭秋早。渔蓑豸绣，总不负、江山文藻。\n\n更到处、胜侣高朋，闲添入奚囊诗料。但展卷看题，空想图中三妙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长亭怨 为俞廙仙题卧游图' AND p.poem_author = '王闿运';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头 寿𠙆社吴退翁三首 其一', '聂树楷', '清代', '三度夺标手，家学旧渊源。蓬莱一水清浅，精究法家言。\n\n归载孝廉舱稳，荣绾外台绶紫，美誉四腾喧。吏以空言告，民少复盆冤。\n\n巡绣虎，分节钺，固篱藩。五州流转防御，风掣画旗翻。\n\n喜见消氛西檄，大可澹忧西顾，高宴敞西园。一对太常蝶，阶下舞轩轩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头 寿𠙆社吴退翁三首 其一' AND p.poem_author = '聂树楷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天 丙午沪滨除夜', '朱祖谋', '清代', '莫厌屠苏酒入唇。雪馀帘户转奇温。接天镫色流连夜，照海花光著莫春。\n\n吟鬓短，彩符新。五湖犹是未归人。明年好办扶犁去，为报苕山一㡧云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天 丙午沪滨除夜' AND p.poem_author = '朱祖谋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阿那曲', '黄咏雩', '近代', '强欲过河呼不起。英雄祗合闲中死。骑驴归去又何人，一枕清凉春睡美。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阿那曲' AND p.poem_author = '黄咏雩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次巴克实彦卿雪中见示韵六首 其一', '许有壬', '元代', '曚昽晓雾勒晨光，一样隆寒两月强。欲和阳春呵冻砚，老夫持酒手犹僵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次巴克实彦卿雪中见示韵六首 其一' AND p.poem_author = '许有壬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天 雨中看牡丹用稼轩韵', '熊盛元', '当代', '艳压唐宫独此株，马嵬坡下泪流初。绛罗卷处芳魂返，红晕生时浅梦苏。\n\n慵自卧，醉难扶。三郎还惜旧情无？霏微细雨胭脂湿，谁画霓裳罢舞图？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天 雨中看牡丹用稼轩韵' AND p.poem_author = '熊盛元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四时白纻歌二首 其一 东宫春', '杨广', '隋代', '洛阳城边朝日晖，天渊池前春燕归。含露桃花开未飞，临风杨柳自依依。\n\n小苑花红洛水绿，清歌宛转繁弦促。长袖逶迤动珠玉，千年万岁阳春曲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四时白纻歌二首 其一 东宫春' AND p.poem_author = '杨广';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留题玉泉山堂', '张伯玉', '宋代', '动非缘境静非祥，物物前尘现四天。\n此地筌蹄求妙论，有时璎络献诸仙。\n欲梅泉石多秋思，过夏松篁聒昼眠。\n一个攒眉招不至，劳师香火漏沈莲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留题玉泉山堂' AND p.poem_author = '张伯玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菱湾', '许及之', '宋代', '根随波共蔓，花更水相亲。鱼跃翻成出，微光解照人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菱湾' AND p.poem_author = '许及之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登头陀寺峰顶庵', '贺铸', '宋代', '磴道淩虚挂白虹，头陀上方黄鹄东。\n沧溟五夜浴新日，老木三伏来凄风。\n北梦南云展张阔，纵江横汉并吞雄。\n楚乡绝境此其一，付与微吟多病翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登头陀寺峰顶庵' AND p.poem_author = '贺铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又次居厚韵一首', '刘克庄', '宋代', '衰迟已迫挂冠年，三黜皆因恋九迁。\n且傍雁行游福地，免陪豹尾幸甘泉。\n早知丹汞方难验，晚悟□□□不然。\n闻说青云梯磴捷，老无肩力可攀缘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又次居厚韵一首' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又前韵 其四', '项安世', '宋代', '庭前黄耳卧花栏，瘦胁长腰骏尾团。壁上朱弓双鹊面，寂寥终日两相看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又前韵 其四' AND p.poem_author = '项安世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小楼 其八', '陈曾寿', '清代', '室小还容膝，时艰岂负人。盗驱佳客至，闷与故书亲。\n\n未假龟山斧，长污相柳尘。沧田留眼在，坚坐且逡巡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小楼 其八' AND p.poem_author = '陈曾寿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('减字木兰花 其十八 彼岸花', '崔荣江', '当代', '别君彼岸，便隔忘川教梦断。相见何期，泣血啼红百叠衣。\n\n生缘已矣，敢赴黄泉先一死。尚记君恩，不许轮回换此身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '减字木兰花 其十八 彼岸花' AND p.poem_author = '崔荣江';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('豫章舟中夜坐自遣', '曾丰', '宋代', '初月多情出，西山故意遮。\n更遭风激水，而乱客吹笳。\n梦入翩翩蝶，惊闻阁阁蛙。\n违多谐偶少，物理固然邪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '豫章舟中夜坐自遣' AND p.poem_author = '曾丰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('为章生成之题新城遗照三首 其一', '曹家达', '清代', '瞻拜遗容思渺然，明湖衰柳尚吹绵。问谁续赋青旸道，寥落行踪三百年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '为章生成之题新城遗照三首 其一' AND p.poem_author = '曹家达';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('见新月思家有作 其二', '胡奎', '明代', '初三初四月钩弯，郎在船头望远山。月似蛾眉山似黛，如何不念镜中鬟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '见新月思家有作 其二' AND p.poem_author = '胡奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寓言二首 其一', '吕诚', '元代', '苦瓠若悬瘿，宜瓢亦宜笙。笙将用合雅，瓢以供酌烹。\n\n吾为苦瓢谋，任力不任声。荐劳铏鼎间，自足资养生。\n\n物贱终反贵，吹万岂其情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寓言二首 其一' AND p.poem_author = '吕诚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('仿昭代诸家体三十八首 四 贝助教琼 感乱', '王夫之', '明代', '正作越来溪上梦，潮声夜打浙东城。春花春柳皆他日，羽檄羽书悲此生。\n\n戍火摇烟低片月，归鸿掠浦警三更。堂堂岁月相欺得，明镜新添雪几茎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '仿昭代诸家体三十八首 四 贝助教琼 感乱' AND p.poem_author = '王夫之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洞庭', '邝露', '明代', '人归洞庭水，心远百蛮天。虹饮吴山雨，蝉嘶楚岫烟。\n\n挂帆明月树，沽酒白云船。来雁纷南向，衡阳何处边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洞庭' AND p.poem_author = '邝露';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春雪', '谢铎', '明代', '二月东风翻作冻，两年春意腊前归。越中儿女燕中长，不识今朝是雪飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春雪' AND p.poem_author = '谢铎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽朱倅周卿 其一', '赵善括', '宋代', '戚畹芝兰秀，儒宗金玉相。解牛无肯綮，驰骥阻康庄。\n\n政术今犹诵，家风久益彰。蕴藏初未试，盛德付诸郎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽朱倅周卿 其一' AND p.poem_author = '赵善括';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读书效朱子体', '弘历', '清代', '古人曾有言，力学如行路。设不进一步，即为退一步。\n\n高秋驻行宫，清暇鲜几务。耽书有宿缘，娱此深山暮。\n\n即景自体验，未觉胜前度。踟蹰生愧惭，空复寻章句。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读书效朱子体' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饮石洞酒戏作', '陆游', '宋代', '酣酣霞晕力通神，澹澹鹅雏色可人。\n一笑破除垂老日，满怀摇荡隔年春。\n梅花的的吹初破，杨柳纤纤染未匀。\n醉倒桥边人不怪，西曹免护相君茵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饮石洞酒戏作' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乞墦词', '杨维桢', '元代', '獬豸不击邪，化为兽中狐。\n屈轶不指佞，化作蒿中刍。\n黄金躯，高盖车，千夫百喏在一呼。\n归来牛马惊里闾，低眉仰面承妻孥。\n奉溲尝恶卑自奴，墦间比来奴不如。\n君不见衡阳有客方诧妇，须髯似戟称人夫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乞墦词' AND p.poem_author = '杨维桢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻归雁感赋', '李锴', '清代', '毕竟家何处，而云北是归。高城残照下，万里一行飞。\n\n风急毋相乱，沙寒定有依。畸人方失序，缘汝泪沾衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻归雁感赋' AND p.poem_author = '李锴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('廿一兄以手和四清香见饷用心清闻妙香为韵成', '曾几', '宋代', '微雨久逾润，禅房低复深。\n下帷香一缕，收尽向来心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '廿一兄以手和四清香见饷用心清闻妙香为韵成' AND p.poem_author = '曾几';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('永嘉卢仲脩永年袖文见访酬以短句', '王十朋', '宋代', '地僻原名左，天寒岁欲徂。遥遥屈佳客，得得访潜夫。\n\n一第且慁子，八篇真起予。蜚声参四杰，谁复敢前卢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '永嘉卢仲脩永年袖文见访酬以短句' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百三十三首 其四十七', '释法薰', '宋代', '田地稳密，关窍玲珑。识得无寒暑处，任他寒暑相攻，个里同途辙不同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百三十三首 其四十七' AND p.poem_author = '释法薰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题四景画 其四 苏武冬牧', '程敏政', '明代', '天山雪花大如席，瀚海东头绝人迹。群羊散落沙碛间，齧尽寒毡岁云夕。\n\n塞垣孤月十九冬，手持旄节归汉封。不知麟阁丹青手，曾写当时憔悴容。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题四景画 其四 苏武冬牧' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日西兴道中', '张栻', '宋代', '江梅已过杏花初，尚怯馀寒著萼疏。待得重来几枝在，半随蝶翅半蜂须。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日西兴道中' AND p.poem_author = '张栻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('京江晚泊', '史济庄', '清代', '舟系垂杨岸，金焦正夕阳。客心秋水远，村树暮烟苍。\n\n山带鱼龙气，江涵日月光。吴歈犹在耳，明日更殊方。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '京江晚泊' AND p.poem_author = '史济庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读史有感十二首 其四', '王世贞', '明代', '长卿赋上林，将以明得意。及乎谏猎书，凛然垂堂示。\n\n驰骋私所便，能无忽神器。众知乘船危，污轮诤何厉。\n\n为谢张大夫，晓人当如是。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读史有感十二首 其四' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄裴校书', '羊士谔', '唐代', '登高何处见琼枝，白露黄花自绕篱。 \n 惟有楼中好山色，稻畦残水入秋池。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄裴校书' AND p.poem_author = '羊士谔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('跋正法眼藏', '楼钥', '宋代', '正法眼藏当时灭却，那得许多落落索索。\n问著则差，答著则错。\n喝也喝不住，棒也打不著。\n妙喜更得工夫，时与下个注脚。\n休休休，莫莫莫。\n若要拈花微笑底事，不二法门也低一著。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '跋正法眼藏' AND p.poem_author = '楼钥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水龙吟 杨花，和东坡', '龙榆生', '近代', '怨春悭驻芳踪，欲留无计从伊坠。盈盈倦舞，濛濛乱扑，几多沈思。\n\n错怪狂风，惊回绮梦，閒庭深闭。禁连朝苦雨，啼痕乍揾，知何意，漫空起。\n\n纵自飘零增感，肯随尘、浪沾轻缀。尽拚憔悴，依然冰雪，未辞身碎。\n\n薄命三生，浓愁万种，任漂荒水。化青萍争奈，残阳悽照，引行人泪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水龙吟 杨花，和东坡' AND p.poem_author = '龙榆生';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苏文忠潘墨诗帖赞', '岳珂', '宋代', '怀绝世之清音，叹媸妍之难谌。\n慨丸墨之未改，挹古人而寄心。\n褐黯黯以如漆，笏琅琅而抵金。\n贮冰壶其自如，渺一尘这弗侵。\n彼远臭以何归，谩花柳之繁阴。\n姓昧昧以污人，虽千年而亦喑。\n予得此诗，跫然长吟。\n想先生之清标，契谪仙于同襟。\n凌九垓而神会，岂入海之可寻。\n方将抱月乘风，携壶命琴。\n短墨帝于玄圃，挟客卿于翰林。\n快骑鲸而翳凤，遂登高而俯深。\n执此卷而撰杖，筮得朋于盍簪。\n秋露其滴，玉蜍自斟。\n捧诗砚之如箕，淬词锋之发镡。\n付张李于一吷，视沧溟于蹄{左足右岑}。\n逸兴天游，浩无古今。\n斗杓回光，曦车发晨。\n承謦欬于绪言，犹足以投微机于芥针也。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苏文忠潘墨诗帖赞' AND p.poem_author = '岳珂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送乾康禅师入山过夏', '齐己', '唐代', '由来喧滑境，难驻寂寥踪。逼夏摇孤锡，离城入乱峰。 \n 云门应近寺，石路或穿松。知在栖禅外，题诗寄北宗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送乾康禅师入山过夏' AND p.poem_author = '齐己';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月 其三 有见', '吴绮', '清代', '小玉梳成闹扫，善师教就琵琶。恼人春着杏儿纱，绣带临风一把。\n\n红阁画桨萱草，青墙映出梨花。斗鸡坊下认儿家，拣取垂杨系马。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月 其三 有见' AND p.poem_author = '吴绮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送王季山赴龙溪', '朱熹', '宋代', '故人千石令，便道此之官。契阔三秋永，逢迎一笑欢。\n\n田园知不远，谣俗问非难。已想躬玄默，鸣弦亦罢弹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送王季山赴龙溪' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人', '杨圻', '清代', '前生种下相思种，转眼都如梦。此心如水只长流，如许潇湘能放几多愁。\n\n楼台惆怅还犹昨，往事思量著。应知青鸟有时通，同去桃源深洞路重重。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人' AND p.poem_author = '杨圻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书崇庆牧恤赠观察常理斋先生殉节录后', '马启泰', '清代', '男儿血性本天成，报答君恩一死轻。固是疏防由大将，还欣骂贼有书生。\n\n诗篇末散精灵在，竹帛常垂姓宇荣。料得忠魂多慰藉，故人何用泪纵横。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书崇庆牧恤赠观察常理斋先生殉节录后' AND p.poem_author = '马启泰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南巡回銮驻跸圆明园之作', '弘历', '清代', '麦登秋穰黍全耕，喜气迎銮达帝京。又此南巡成北返，恰看夜雨值朝晴。\n\n康功灾壤怜群赤，勤政明廷接九卿。懿旨身遵心膝下，所欣旬日近归程。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南巡回銮驻跸圆明园之作' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('按行分宜', '蒋之奇', '宋代', '分得宜春地，东偏一画屏。洪阳仙洞古，龙姥旧祠灵。\n\n雨过溪痕长，春回草径青。道傍聊下马，揩藓读碑铭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '按行分宜' AND p.poem_author = '蒋之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('隐趣园八咏 其三 蜀锦屏', '胡助', '元代', '濯锦为屏障，红妆拥万妃。试看春睡足，何羡买臣归？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '隐趣园八咏 其三 蜀锦屏' AND p.poem_author = '胡助';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同水心吊薛子舒墓', '戴栩', '宋代', '自斸青云去，长途坠玉镳。有名天所吝，无病药为妖。\n\n月斧千家寂，霓梭五色销。梦灵虚吐凤，数短实如鸮。\n\n筦库嗟常调，弓旌欠特招。贵儿嫌苦淡，盛叶不萧条。\n\n往忆京华旅，相随柳外桥。行藏今止此，岁月忽同飘。\n\n留札宽亲抱，缄文付稚髫。敬亭花自发，族陇木仍乔。\n\n稍待刊铭志，从知慰泬寥。友朋如昨日，来往未辞遥。\n\n酹散窗生雾，吟寒斗挂杓。百年齐一尽，终誉在山椒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同水心吊薛子舒墓' AND p.poem_author = '戴栩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答酒家王君惠酒 其三', '屈大均', '明代', '玉馈清如镜，无乾复一樽。忘忧凭此物，难老不须言。\n\n花气春初暖，莺声日已喧。酒泉君挹注，自此更源源。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答酒家王君惠酒 其三' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题烹茶鹤避烟图', '蔡廷兰', '清代', '涤尽烦襟野趣生，閒来扫榻品茶经。烟腾石鼎松风发，水沸铜瓶桧雨晴。\n\n笑我酪奴恣饱酌，惊他羽客作长鸣。此仙不受人间气，分付樵青细火烹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题烹茶鹤避烟图' AND p.poem_author = '蔡廷兰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四月癸已发浔阳馆过濂溪饭于杏溪愒清虚庵宿', '魏了翁', '宋代', '又过前溪访梵宫，人言此与老庄同。\n是同是异谁知得，拟问山前无极翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四月癸已发浔阳馆过濂溪饭于杏溪愒清虚庵宿' AND p.poem_author = '魏了翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄云门僧若邪溪兼题其松风阁二首 其一', '张翥', '元代', '闻道邪溪叟，高年出寺迟。眉毫长几许，布衲破多时。\n\n挂锡鹤移树，翻经花满池。相望一江水，岁晚赴幽期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄云门僧若邪溪兼题其松风阁二首 其一' AND p.poem_author = '张翥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五月十三日过东冈看新竹时杨梅正熟红绿掩映甚可观也诗因及之', '王鏊', '明代', '新竹娟娟旧竹斑，东西俨立万琅玕。彊鞭迸占青松地，清荫浓添白石坛。\n\n羽扇动摇香粉堕，杨梅点缀绛星攒。我来避暑年年事，锦箨无烦为制冠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五月十三日过东冈看新竹时杨梅正熟红绿掩映甚可观也诗因及之' AND p.poem_author = '王鏊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('华幼圜以古隶见贻赋此报谢仍乞书国风', '王世贞', '明代', '鸟翮山头王次仲，鸿都门下蔡中郎。似分晋季鹅池墨，流作梁清练水香。\n\n柿叶过霜红满地，芭蕉含雨碧堆床。二南须为纵横写，老去风人有面墙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '华幼圜以古隶见贻赋此报谢仍乞书国风' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('循资赵宰有贺诗次韵三首 其二', '陈造', '宋代', '蒿帛入门无几润，妻孥食粥有馀清。轻肥腾趠非吾愿，矻矻雌黄且课程。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '循资赵宰有贺诗次韵三首 其二' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨后十小绝以一雨洗残暑万家生早凉为韵 其六', '章甫', '宋代', '长安卿相家，一食费几万。有功享固宜，我辈且蔬饭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨后十小绝以一雨洗残暑万家生早凉为韵 其六' AND p.poem_author = '章甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题汪氏孝节堂', '方回', '宋代', '三从分定付之天，捧案曾无月再圆。\n莱子方同彩衣舞，鄘风忽赋柏舟篇。\n频年兵革经多难，奕世门闾喜独全。\n孝节从来足阴相，儿孙袞袞寿眉前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题汪氏孝节堂' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南归途中杂诗二十二首 其二十', '黄佐', '明代', '薰风拂拂吹野花，石濑涓涓明早霞。天边未辨龙泉气，江上徒乘牛斗槎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南归途中杂诗二十二首 其二十' AND p.poem_author = '黄佐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书派河徐希秀才别业', '释保暹', '宋代', '渺渺渡头路，客心难解携。\n半空山远近，寒日水东西。\n漾浦渔罾小，飞沙雁阵低。\n霜风起深夜，只是欠猿啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书派河徐希秀才别业' AND p.poem_author = '释保暹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('滁山道中杂题 其二', '唐之淳', '明代', '麦陇丛丛绿，梅香树树香。山禽惊客梦，村酒割人肠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '滁山道中杂题 其二' AND p.poem_author = '唐之淳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠曹以宁', '张弼', '明代', '著书只欲明忠义，垂橐何曾计有无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠曹以宁' AND p.poem_author = '张弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二零零一年十二月三十一夜 其三', '卢青山', '当代', '太常一日醉，我有一日醒。兀兀不能安，自不知其病。\n\n忽然伸眉笑，盖以今未饮。冬风如春风，著体无稍冷；\n\n明日即明年，奔来不用请。孤坐玩空杯，聊应守岁景。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二零零一年十二月三十一夜 其三' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('失调名', '佚名', '宋代', '夜深青女湿微妆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '失调名' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送妻兄任以道赴房州竹山尉四首', '项安世', '宋代', '古来王谢家，生长習见闻。\n人言不学问，楚楚自超群。\n君侯妙质廪，博学而多文。\n如玉作璠玙，可以奉明君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送妻兄任以道赴房州竹山尉四首' AND p.poem_author = '项安世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题李将军四时行乐图 其三 秋郊挟弹', '丘浚', '明代', '霜梁枫林秋气肃，潦水收痕山露骨。苍鸠一夜化为鹰，百鸟含羞傍林麓。\n\n将军小队出西郊，金环压辔青骢骄。霹雳一声军吏贺，半空云外落双雕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题李将军四时行乐图 其三 秋郊挟弹' AND p.poem_author = '丘浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春悲行', '胡皓', '唐代', '夜鹊南飞倦，鸣鸡屡送晨。忽闻芳岁到，今日故园春。\n\n试上亭台望，氛氲江树新。的的韶阳萼，迢迢佳丽人。\n\n音容旷不接，景物徒相因。别怨如流水，移恩念积薪。\n\n垂泪三危露，心断二京尘。远役鸿为伴，荒亭鬼作邻。\n\n吾生殊卉木，憔悴此江滨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春悲行' AND p.poem_author = '胡皓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四园竹 秋怨', '高濂', '明代', '雨扶黄叶，夜半打空窗。罗衾较冷，鹤焰知寒，蟋蟀依床。\n\n萧瑟西风摇落，树枯山瘦，朝来减却秋光。\n\n断人肠。有约梦迷巫峡，空怜雁出潇湘。无那枕边醒耳，听彻沉沉玉漏长。\n\n一宵难过，何况是，无日不思量。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四园竹 秋怨' AND p.poem_author = '高濂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李参政生日', '魏了翁', '宋代', '历尽玄枵十二辰，饱看三十六宫春。\n才喷一霎挂龙雨，又卷云霓还翠旻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李参政生日' AND p.poem_author = '魏了翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湖上众禽尽以俗呼为题·提葫芦', '文同', '宋代', '花开已堪镜，半绿卷如杯。\n谁为回风力，清香满面来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湖上众禽尽以俗呼为题·提葫芦' AND p.poem_author = '文同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百二十三首', '释普度', '宋代', '双双把手上高楼，唱拍相从各应酬。\n歌鼓散时人尽醉，也无欢喜也无愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百二十三首' AND p.poem_author = '释普度';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春江', '沈周', '明代', '爱杀春江日夜流，有人结屋住江头。门前钓石临黄鹤，床下鱼波洗白鸥。\n\n未识何年变春酒，且将吾道付沧洲。天光月色溶溶地，更好凭虚著小楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春江' AND p.poem_author = '沈周';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠范道人', '卫宗武', '宋代', '黄纸差符不肯留，飘然愿逐云水游。\n纡朱拖紫不肯慕，甘著草衣披布素。\n金珠斗量佩鸣珂，所得懽华能几何。\n形气日随情欲蠹。曾不百岁同臭腐。\n学仙岂必便函成仙，人世且结清净缘。\n弘景宁为轩冕锢，子平未免婚嫁累。\n有田有庐誓弗归，有子有女弃若遗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠范道人' AND p.poem_author = '卫宗武';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题张生写鹰树图', '韩上桂', '明代', '画鹰须画神，写树须写根。张生画鹰鹰欲动，恍惚两翼淩苍旻。\n\n一石点缀太磊落，槎枒古树攒江滨。江滨树亦得，水底明朝日。\n\n急添粉练细作韝，恐其听秋风而自失。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题张生写鹰树图' AND p.poem_author = '韩上桂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('人日游碛', '王十朋', '宋代', '好遨蜀风俗，夔人贫亦遨。今日日为人，倾城出江皋。\n\n遨头老病守，呼宾酌春醪。归来及初鼓，繁灯照霜毛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '人日游碛' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早秋过郭涯书堂（一作郭劲书斋）', '周贺', '唐代', '暑消冈舍清，闲语有馀情。涧水生茶味，松风灭扇声。 \n 远分临海雨，静觉掩山城。此地秋吟苦，时来绕菊行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早秋过郭涯书堂（一作郭劲书斋）' AND p.poem_author = '周贺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('立春 其二', '李石', '宋代', '青菜青丝白玉盘，西湖回首忆临安。竹篱茅舍逢春日，乐得梅花带雪看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '立春 其二' AND p.poem_author = '李石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('霜 其二', '屈大均', '明代', '炎方天气变，腊月未春阳。不雨难成雪，无风但作霜。\n\n寒生冬至后，白满越王乡。日出为烟雾，濛濛接海长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '霜 其二' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('海榴', '符锡', '明代', '种药林园兴未涯，蔷薇开后海榴花。红香带露■唇湿，翠萼含风玉轸斜。\n\n路子莫教轻折取，山灵应为惜妍华。未妨近□侵篱槿，且喜新条让木瓜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '海榴' AND p.poem_author = '符锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六言二首 其一', '汪炎昶', '宋代', '撼竹露喧馀滴，度荷风挟微香。醉袂拂开云影，钓丝牵动潭光。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六言二首 其一' AND p.poem_author = '汪炎昶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塞上谣 其二', '顾清', '明代', '千顷膏腴紫塞秋，健儿耕作贵人收。金城遗迹犹堪按，只在忠良与国谋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塞上谣 其二' AND p.poem_author = '顾清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感事六首', '顾梦圭', '明代', '柏梁新营建章起，武帝雄心殊未已。\n金楹玉磶千万重，骀荡春光侔太紫。\n海东鞭石血横流，燕雀徜徉彩云里。\n君不见天庖椎牛犒大匠，荷锸丁夫谁馈饷。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感事六首' AND p.poem_author = '顾梦圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('月岩', '曾丰', '宋代', '岩腹刳为半月形，全功天且不能成。\n勿嗟圆处便生缺，犹幸晦中堪养明。\n更朔还多终有望，受亏已久得无盈。\n愿言链石补教足，使我众生眼界平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '月岩' AND p.poem_author = '曾丰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉答内兄希叔诗 其五', '陆厥', '南北朝', '平原十日饮，中散千里游。渤海方淫滞，宜城谁献酬。\n\n屏居南山下，临此岁方秋。惜哉时不与，日暮无轻舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉答内兄希叔诗 其五' AND p.poem_author = '陆厥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉楼春', '楼采', '宋代', '东风破晓寒成阵。曲锁沈香簧语嫩。凤钗敲枕玉声圆，罗袖拂屏金缕褪。 \n 云头雁影占来信。歌底眉尖萦浅晕。淡烟疏柳一帘春，细雨遥山千叠恨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉楼春' AND p.poem_author = '楼采';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荷桥暮坐三首 其一', '杨万里', '宋代', '桥剪荷花两段开，荷花留我不容回。不胜好处荷桥坐，政是凉时蚊子来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荷桥暮坐三首 其一' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('烛影摇红 寒食，舟中作', '吴尚憙', '清代', '桃李催人，禁烟时候春寒浅。佳节好况逼清明，暖柳垂金线。\n\n何处留人顾盼。听枝头、流莺啼遍。关山满目，绿水新波，壮游未倦。\n\n如此春风，重阴叠翠斜阳岸。新红一片水迢迢。望处如银汉。\n\n雨过平沙凌乱。更犹疑、画屏深远。鹃啼芳草，鹭宿前滩，轻帆几转。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '烛影摇红 寒食，舟中作' AND p.poem_author = '吴尚憙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('温泉宫', '徐熥', '明代', '羯鼓声中酒未醒，华清浴罢转娉婷。可怜万古温泉水，难洗渔阳战血腥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '温泉宫' AND p.poem_author = '徐熥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠宪有之', '郑孝胥', '清代', '忠贤久赍志，哲肆各超特。吁嗟此何时，为国当尽力。\n\n少康初在虞，羽山犹未殛。见君窃叹异，风骨果遗直。\n\n老夫颇相士，深浅稍能测。热中必怼上，室怒市于色。\n\n一笑契吾言，士固先器识。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠宪有之' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送程给事过越不及口占以寄', '赵抃', '宋代', '立马江头一黯销，晓光浮动十分潮。西陵送目仙舟去，铙鼓旌麾迤逦遥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送程给事过越不及口占以寄' AND p.poem_author = '赵抃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('京都', '周权', '元代', '水入金河滟玉虹，填街车马拥尘红。九重天近风云壮，万雉城高鼓角雄。\n\n花底催朝冠佩列，酒边听曲绮罗丛。太平光景春台乐，物物薰陶圣化中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '京都' AND p.poem_author = '周权';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('刘生', '弘执恭', '隋代', '英名振关右，雄气逸江东。游侠五都内，去来三秦中。\n\n剑照七星影，马控千金骢。纵横方未息，因兹定武功。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '刘生' AND p.poem_author = '弘执恭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红 其二', '奭良', '清代', '正气凌云，遥下拜、歌声未歇。想昔日、背嵬军盛，如火烈烈。\n\n一旅倘挥天外剑，九州共奉王正月。奈生来、偏值小朝庭，空翘切。\n\n许都郡，组练雪。洞庭寇，烟灰灭。正壮心未已，唾壶都缺。\n\n儒将自宜教礼乐，纯臣岂敢私毛血。看画图、玉貌甚雍容，疑朝阙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红 其二' AND p.poem_author = '奭良';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('永遇乐（和钱处和上元）', '王之望', '宋代', '元夜风光，上都灯火，辉映春色。鳌冠仙山，龙衔瑞烛，银阙凌空碧。紫烟深拥，黄云孤起，人喜乍瞻天日。□云里，□□□□，侍臣□□鹄立。 \n 雾收霞卷，珠帘开遍，翠暮娉婷争出。倾国丛中，钧天合处，忽听鸣清跸。貂裘小帽，随车信马，犹忆少年豪逸。如今对，山城皓月，但余叹息。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '永遇乐（和钱处和上元）' AND p.poem_author = '王之望';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百一十七首 其七十八', '释绍昙', '宋代', '十二峰前傀儡棚，尽由行主线抽牵。编排科段无新旧，歌舞秋风乐管筵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百一十七首 其七十八' AND p.poem_author = '释绍昙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蚕', '谢枋得', '宋代', '养口资身赖以桑，终成王道泽流长。\n吐丝不羡蜘蛛巧，饲叶频催织女忙。\n三起三眠时化运，一生一死命天常。\n待看献茧盆缫后，先与吾皇织衮裳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蚕' AND p.poem_author = '谢枋得';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和伯氏包山观桃花韵', '胡仲参', '宋代', '因访桃花到岑根，御林春色此平分。\n千株示数栽唐观，一幅犹堪画晋源。\n仙在云间无处觅，人行风外有香闻。\n笙箫隐隐宫城隔，立尽黄昏更断魂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和伯氏包山观桃花韵' AND p.poem_author = '胡仲参';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日在梧桐', '王安石', '宋代', '秋日在梧桐，转阴如急毂。\n冥冥蔽中庭，下视今可暴。\n高蝉不复嘒，稍得寒鸦宿。\n百绕有衰翁，行歌待春绿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日在梧桐' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病中口占', '舒邦佐', '宋代', '拂枕投床鼻息鸣，邻鸡报午梦还惊。一春已过半春了，十日曾无五日晴。\n\n唤客难同藉草饮，隔墙虚认卖花声。十年前忆西湖上，柳荫苏堤取次行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病中口占' AND p.poem_author = '舒邦佐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏至夜宿海幢僧阁', '梁以壮', '明代', '隔江灯火坐中看，四面潮声欲上栏。山月鹿归双角解，寺钟龙听一珠蟠。\n\n河南书屋人何在，岭上松风石自寒。无限幽怀不能写，抱琴清绝水云端。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏至夜宿海幢僧阁' AND p.poem_author = '梁以壮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴门秋怀八首 其三', '邓云霄', '明代', '宦薄能令侠骨尊，西风客思满秋原。久居泽国谙吴语，每向江枫吊楚魂。\n\n暗里含沙犹射影，时来孤鹤忽乘轩。少年日逐专诸巷，袖有鱼肠未报恩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴门秋怀八首 其三' AND p.poem_author = '邓云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('野人', '陈忠平', '当代', '野人疏大志，端居一水浔。青眸谁顾惜，明月自升沈。\n\n鸥点秋沙白，烟笼春梦深。有时无所事，万籁共长吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '野人' AND p.poem_author = '陈忠平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('入冬半月馀二麦未种忽然一雨', '丘葵', '宋代', '村庄三日雨，清晓怯凭栏。洒地纷纷白，随风阵阵寒。\n\n不愁客衣薄，且为老农欢。已有芃芃意，来春岁计宽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '入冬半月馀二麦未种忽然一雨' AND p.poem_author = '丘葵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('叠前韵悼物理学家兼诗人黄克孙先生三首 其三', '伯昏子', '当代', '今剩蔷薇插玉壶，从兹挥手白云孤。他年若遇青藤下，但执天钧问有无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '叠前韵悼物理学家兼诗人黄克孙先生三首 其三' AND p.poem_author = '伯昏子';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游独孤城下作', '张嵲', '宋代', '利成山百丈，直下独孤城。\n事往岁月积，长江依旧清。\n昔人经过地，我辈复此行。\n但见竹树稠，石崖如削成。\n乔木晚未凋，青青发余荣。\n天寒远峰澹，日晏长川明。\n时危怀古意，岁暮羁旅情。\n一室寄绝岸，全家托柴荆。\n晨炊饭脱粟，似此田涧氓。\n群盗正猖獗，深居且偷生。\n反念故园日，默默何由平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游独孤城下作' AND p.poem_author = '张嵲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泊临清州二首 其二', '夏孙桐', '清代', '秋潦残堤水势宽，城闉隐起暮烟寒。一行远雁连霜树，数点昏鸦立电竿。\n\n行旅方知关吏贵，灾区还念赈需难。嗷嗷中泽严冬迫，谁向监门画里看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泊临清州二首 其二' AND p.poem_author = '夏孙桐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浪淘沙', '冒广生', '清代', '梦雨了无痕。零落琴樽。一春情绪怕黄昏。还要凄凉心上影，添个销魂。\n\n何处莫愁村。旧曲桃根。思量谁与共温存。闲煞月明花满地，独自关门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浪淘沙' AND p.poem_author = '冒广生';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('随缘吟', '邵雍', '宋代', '得路青霄正好冲，休贪粮稻恋深笼。\n要无为后须还朴，好自由时莫厌穷。\n百计用心终上错，一场大梦到头空。\n生涯澹澹随缘过，未肯将身入彀中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '随缘吟' AND p.poem_author = '邵雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题安成刘伯深爵瑞里报德堂上白爵图', '杨万里', '宋代', '君不见书台之北爵瑞里，\n安成令君旌孝子。报德堂前松造天，\n卜宅浩然老居士。居士元无一物遗，\n子孙只有牙签三万存。郎君饭此三万轴，\n落纸云烟动埸屋。雪中负土成先茔，\n感得路人双涕零。更傅雪爵云上随，\n天表孝子蹈雪行。即看黄告来告弟，\n是时雪爵应再至。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题安成刘伯深爵瑞里报德堂上白爵图' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苏幕遮·玉炉中', '高道宽', '元代', '玉炉中，烧丹药。锻炼三成，最上真个妙。海底龟蛇勤收捉。纳在壶中，炼就圆明觉。照无边，光灼灼。顺手拈来，直下长生勺。功行十分凭戒约。一对芒鞋，穿上踏云脚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苏幕遮·玉炉中' AND p.poem_author = '高道宽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送春', '陆游', '宋代', '新叶张翠幄，落花作红茵。\n山蔬旨且柔，家酿清而淳。\n以我垂老境，送此将归春。\n我固惜流年，春亦记陈人。\n江山处处佳，风月日日新。\n蹇驴度松冈，短楫横烟津。\n兰亭人已远，遗韵犹清真。\n却下木栅市，天风吹角巾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送春' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重阳日次荆南路经武宁驿', '崔橹', '唐代', '茱萸冷吹溪口香，菊花倒绕山脚黄。家山去此强百里， \n 弟妹待我醉重阳。风健早鸿高晓景，露清圆碧照秋光。 \n 莫看时节年年好，暗送搔头逐手霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重阳日次荆南路经武宁驿' AND p.poem_author = '崔橹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶题', '李流谦', '宋代', '小沟溶漾可涉，彩舫夷犹不惊。\n晚酌忽逢名酒，当时打破愁城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶题' AND p.poem_author = '李流谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('全上人之仰山', '释子益', '宋代', '集云峰下四藤条，千载谁知恨未销。\n去去全身担荷得，石龙依旧碧岧嶢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '全上人之仰山' AND p.poem_author = '释子益';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('回望峡山二首', '杨万里', '宋代', '浪喜出峡来，峡亦何曾出。\n两岸只无山，依旧江刻屈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '回望峡山二首' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('事白后再上疏乞骸承伯玉司马以二诗慰问有感问答 其二', '王世贞', '明代', '飞章万里叩天阍，乞得闲身是主恩。已荷圣朝宽毁骨，可烦词客为招魂。\n\n行逢车马心先折，语到渔樵道便尊。依约十年栖隐处，软莎新竹护柴门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '事白后再上疏乞骸承伯玉司马以二诗慰问有感问答 其二' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史下·梁武帝', '陈普', '宋代', '戒舍工夫老未员，百双鸡子送残年。\n一生般若成何事，赢得江头载荻船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史下·梁武帝' AND p.poem_author = '陈普';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闺怨一百二十首 其三十九', '孙蕡', '明代', '月斜风细梦初回，日掩重门夜却开。花影乱中人影过，失惊原是小琼来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闺怨一百二十首 其三十九' AND p.poem_author = '孙蕡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水乐洞', '弘历', '清代', '水乐探幽洞，鍧铿果异常。尽消诸虑处，繁会八音场。\n\n非竹还非革，中宫亦中商。妙张洞庭趣，何必问东阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水乐洞' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('北山别业三十八咏 其二十七 水亭', '陈樵', '元代', '少凤穿花照水盟，水禽冲浪动轩楹。云从薜荔衣中起，雨向玕琪树上生。\n\n曲水傍人流白羽，娇花无语荅黄莺。涧中日与山中日，同上晴窗各自行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '北山别业三十八咏 其二十七 水亭' AND p.poem_author = '陈樵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨中溪行杂诗 其一', '顾璘', '明代', '十日溪中舟，格格响溪石。孤篷过鸣雨，忽失沙上脊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨中溪行杂诗 其一' AND p.poem_author = '顾璘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('草', '丁谓', '宋代', '葭茁迎春早，山芮得地高。\n堪书同细带，入咏似青袍。\n弱力绵绵葛，微香蓼蓼莪。\n王孙何处在，楚思遍江皋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '草' AND p.poem_author = '丁谓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和紫虚丹房二十首 其五', '程通', '明代', '退朝行殿侍吟坛，剪烛吟诗到夜残。一胆信知如斗大，寸心还欲似天宽。\n\n文章李杜齐名易，勋业伊周接踵难。深荷国恩无以报，几回兴念几忘餐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和紫虚丹房二十首 其五' AND p.poem_author = '程通';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读书', '吕本中', '宋代', '老去有馀业，读书空作劳。时闻夜虫响，每伴午鸡号。\n\n久静能忘病，因行得出遨。胡为良自苦，膏火自煎熬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读书' AND p.poem_author = '吕本中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('邢侍郎居敬挽章', '程敏政', '明代', '楚节随恩侍紫清，棹歌声里独魂惊。空馀易学传三辅，无复官名署两京。\n\n清白已堪书太史，经纶应未了平生。相如老去人争羡，分赐无缘及露茎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '邢侍郎居敬挽章' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登天柱峰次路北村院长旧韵', '顾璘', '明代', '天柱峰高白日晴，华嵩相对最分明。扶桑倒射东溟影，银汉平流上界声。\n\n空里金宫陈帝座，云边铁锁度人行。不缘旌节巡方岳，孤负尘埃过此生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登天柱峰次路北村院长旧韵' AND p.poem_author = '顾璘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('楞伽山诗', '周龙藻', '清代', '先王定秩祀，赫赫祭义悬。岂容淫昏鬼，得以非族干。\n\n世衰道始丧，恢诡滋神奸。咄哉楞伽山，蒙诟数百年。\n\n冈峦非不美，有孽凭于巅。其事俚且诞，意出妖巫传。\n\n公然饰屋宇，金碧穷芳妍。木偶杂男女，佩玉而纡鬟。\n\n部卒侍两帝，肖象青红填。遂令无知辈，瞽聋自欺谩。\n\n石湖水清驶，什五排画船。牲牢必脩洁，箫鼓仍喧阗。\n\n虽值风雨夕，奔走惧少延。妇人尤噂𠴲，语恶不忍宣。\n\n心邪乘隙入，梦寐生狂颠。动云神所致，祷赛宜加虔。\n\n妖巫既得志，吠声益狺狺。鼓舞数邑民，真如蝇慕膻。\n\n每当婚礼成，先期陈几筵。乡村真可笑，立庙溪谷边。\n\n高广仅盈尺，尊奉同帝天。屈指百里中，日费千金钱。\n\n岂惟膏脂竭，风俗因之迁。阴霾蔽白日，沈痼无由痊。\n\n自昔守土吏，往往多名贤。逡巡惮摘发，半为祸福牵。\n\n汤公中州起，绝学今伊川。仗节抚吴下，变俗以身先。\n\n痛兹淫祀炽，能使民德愆。上章罗罪状，正气回两间。\n\n一朝纶綍降，尽取投深渊。震雷忽破蛰，荒秽快洗湔。\n\n山灵亦生色，草木增葱芊。政成甫期月，玺书徵何遄。\n\n一老天不遗，骑箕归星躔。我闻公去后，群小复煽言。\n\n望祭伺昏夜，稍稍酒食骈。死灰偶不戒，虐焰恐再然。\n\n我愿献此诗，片石山头镌。庶几百怪息，公德永不刊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '楞伽山诗' AND p.poem_author = '周龙藻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观物', '李贤（原德）', '明代', '闲来观物到园东，天理流行在在同。方沼雨晴看跃鲤，层霄云净见飞鸿。\n\n春畦苗长随宜绿，晓树花开任意红。并育宣明情固适，还将此道细研穷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观物' AND p.poem_author = '李贤（原德）';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五君咏 其二 萧君云门', '方仁渊', '清代', '一尉山西去，为贫去不回。呕心吟秀句，作意写寒梅。\n\n儿女随芳草，田园转劫灰。宁知萧寺酒，竟作别离杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五君咏 其二 萧君云门' AND p.poem_author = '方仁渊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆扬州天宁寺竹', '玄烨', '清代', '久别金焦十一年，依稀寒暑递推迁。此君有意虚心待，叹我徒劳幽思牵。\n\n雁逐西风何处问，云回北地竟谁传。翠筠晚节饶苍箨，远寄宸章梵宇前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆扬州天宁寺竹' AND p.poem_author = '玄烨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄郑谷', '王贞白', '唐代', '五百首新诗，缄封寄去时。只凭夫子鉴，不要俗人知。 \n 火鼠重收布，冰蚕乍吐丝。直须天上手，裁作领巾披。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄郑谷' AND p.poem_author = '王贞白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和傅山父喜雨韵二首', '李曾伯', '宋代', '柔金老火苦相鏖，千里骎骎地不毛。\n忽遂所祈欣欲舞，举蒙其利润於膏。\n昭苏田畯禾千顷，饱满舟人水一篙。\n我老发挥无好句，须拈健笔付诗豪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和傅山父喜雨韵二首' AND p.poem_author = '李曾伯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三学山盘陀石上刻诗', '佚名', '唐代', '拔地山峦秀，排空殿阁斜。云供数州雨，树献九天花。 \n 夜月摩峰顶，秋钟彻海涯。长松拂星汉，一一是仙槎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三学山盘陀石上刻诗' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次徐谢韵还江公诗卷', '朱松', '宋代', '大条祠官闲日月，绝知圣处着功深。\n荣枯举世争卢白，枉直何人较尺寻。\n身比香山差得计，诗看正始有遗音。\n应容下客游东阁，要话朱游夙昔心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次徐谢韵还江公诗卷' AND p.poem_author = '朱松';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('投曾秀州逢四首 其一', '赵蕃', '宋代', '我向茶山得屡行，至今人说老先生。九原不作吾安仰，宗武宗文贤弟兄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '投曾秀州逢四首 其一' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆秦娥·三月时', '翁元龙', '宋代', '三月时。杨花飞尽无花飞。无花飞。不教春去，争得春归。高楼望断黄金羁。绿窗眉黛伤新离。伤新离。好将别後，长做归时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆秦娥·三月时' AND p.poem_author = '翁元龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宁退耕岩维石隆湖隐皆尝有德於余图报未能而', '释文珦', '宋代', '吾生素无宠禄愿，自向空林灰百念。\n但存心地如砥平，不道人间有崖堑。\n皇天幸能念无辜，脱我险难归夷涂。\n天定胜人乃其证，纷纷谮舌胡为乎。\n四方交朋盈什百，反眼如同不相识。\n岂唯袖手不能援，多若苍蝇变白黑。\n独有空门三老人，或未褒面非交亲。\n奋身为余直其枉，恻隐如此宜称仁。\n思欲报之苦无力，但有此心匪石席。\n今日为异世人，俛仰存亡三太息。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宁退耕岩维石隆湖隐皆尝有德於余图报未能而' AND p.poem_author = '释文珦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿毛村', '吴与弼', '明代', '扁舟旅泊暂天涯，一夜归心又梦家。行李但教西路稳，东篱计日咏黄花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿毛村' AND p.poem_author = '吴与弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏日南湖汎舟因过琼华园六首 其一', '张镃', '宋代', '淡日轻阴晒麦天，水边閒唤木兰船。不游东港西陂熟，争得人知是散仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏日南湖汎舟因过琼华园六首 其一' AND p.poem_author = '张镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('灯花', '陶安', '明代', '卷然铁如意，红粟结葳蕤。十瓣团葩出，孤根密缕垂。\n\n寒风吹不动，光燄照书帷。黄昏至夜半，有喜报人知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '灯花' AND p.poem_author = '陶安';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出御史台', '郑侠', '宋代', '万险千艰六出身，如今刀得避嚣尘。\n须知从此寒原上。有个行歌拾穗人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出御史台' AND p.poem_author = '郑侠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠翰古清', '郑元祐', '元代', '虞公借榻宗镜堂，四众乡仰不暂忘。古清上人独见取，赠以金薤之琳琅。\n\n公时目眚视贸贸，文成欲写难成行。殒星著纸废属读，风襟露带斜低昂。\n\n中言上人善幻化，神龙千丈一钵藏。蜿蜒委蛇各有态，擘云掣电金蛇光。\n\n海涛翻山霹雳碎，怒捲河汉如壶浆。世人蒿目不敢觑，师独摩抚如驯羊。\n\n神膏点鳞翠鬣舞，金篦刮瘼星芒张。珊瑚千树宫室秘，献以耆婆未睹之药方。\n\n师哀其诚为摹写，风旗雷车雨脚霶。点睛未了便飞去，砚坳有墨空淋浪。\n\n愿师骑之上帝都，为问苍生谁短长？凫眠鹤翥且莫辨，伽那定里松花香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠翰古清' AND p.poem_author = '郑元祐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂二百零五首 其一一九', '释正觉', '宋代', '一人之父，百王之师。道机有馀兮，动若四时。寿域无疆兮，量同二仪。\n\n大功不宰，至化无为。妙兮虽喻，智也不知。权挂垢衣云是佛，却装珍御复名谁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂二百零五首 其一一九' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次苏平仲编修北山记游韵二十四首 其三', '童冀', '明代', '丞相祠堂一径深，百年宰木尚阴阴。朝端又见新黄阁，天上长悬旧羽林。\n\n祖逖中原应有恨，孔明梁父谩长吟。神州在望空回首，落日青山澹暮岑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次苏平仲编修北山记游韵二十四首 其三' AND p.poem_author = '童冀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜雨口号九首呈潘侯', '刘克庄', '宋代', '虽拥朱幡只泽臞，孕鱼丹荔免苞苴。\n未应旱魃无分别，更把秋阳懊恼渠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜雨口号九首呈潘侯' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('仙门洞次苏大禹参君韵', '佘翔', '明代', '共有寻真兴，林峦望里微。朝乘青雀舫，暮叩白云扉。\n\n涧水寒侵榻，岩花香扑衣。僧来分乞食，信宿欲忘归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '仙门洞次苏大禹参君韵' AND p.poem_author = '佘翔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙·百亩中庭半是苔', '王安石', '宋代', '百亩中庭半是苔。门前白道水萦回。爱闲能有几人来。\n小院回廊春寂寂，山桃溪杏两三栽。为谁零落为谁开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙·百亩中庭半是苔' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('广陵岸送北使诗', '阴铿', '南北朝', '行人引去节。\n送客{舟羲}归舻。\n即是观涛处。\n仍为郊赠衢。\n汀洲浪已息。\n邗江路不纡。\n亭嘶背枥马。\n樯啭向风乌。\n海上春云杂。\n天际晚帆孤。\n离舟对零雨。\n别渚望飞凫。\n定知能下泪。\n非但一杨朱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '广陵岸送北使诗' AND p.poem_author = '阴铿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮 灯夕次韵', '善住', '元代', '当年老子逢佳节。万户华灯连皓月。和气满江城。喧喧队子行。掩关聊共坐。静对沉香火。一笑尽君欢。闲心无两般。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮 灯夕次韵' AND p.poem_author = '善住';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮 偃师道中', '宋＊', '元代', '北芒古冢纷无数。崔嵬罗列成山阜。何处断碑横。无人知姓名。今坟如蚁垤。回首成磨灭。今古两堪哀。停骖酹绿苔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮 偃师道中' AND p.poem_author = '宋＊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('右山茶 其四 水仙', '胡应麟', '明代', '泠泠冰玉姿，独立潇湘岸。恍似薛家娘，寒涛披素练。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '右山茶 其四 水仙' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟泊岳州城下登岳阳楼晚眺', '唐群英', '近代', '君山突起水萦回，山色湖光照眼开。不访纯阳大仙吕，何当共我醉三回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟泊岳州城下登岳阳楼晚眺' AND p.poem_author = '唐群英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵乐著作天庆观醮', '苏轼', '宋代', '浊世纷纷肯下临，梦寻飞步五云深。\n无因上到通明殿，只许微闻玉佩音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵乐著作天庆观醮' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怜愚诗四十二首 其三十九', '宋应星', '明代', '人到无能始贷金，子钱生发向何寻？厉词追索弥年后，生计萧条起绿林。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怜愚诗四十二首 其三十九' AND p.poem_author = '宋应星';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送春拟韩致光', '林旭', '清代', '循例作诗三月尽，眼遭飘落太惊心。拆成片片思全盛，缀得疏疏祝久禁。\n\n肯记帽檐曾竞戴，无情屐齿便相侵。冬郎谩把伤春酒，早日池塘已绿阴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送春拟韩致光' AND p.poem_author = '林旭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苦脾泄在告因饮白酒一杯小愈魏倅有诗已而病', '王炎', '宋代', '羸老畏风湿，河鱼将奈何。\n玉友岂不佳，终难护天和。\n数息谩吐纳，链形空按摩。\n自笑来日短，残漏鸣铜荷。\n吏事如衣垢，濯之费挼挲。\n养痾谅非宜，山林归兴多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苦脾泄在告因饮白酒一杯小愈魏倅有诗已而病' AND p.poem_author = '王炎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('连日灌畦莳菜废作诗', '葛立方', '宋代', '莫问新来额插犀，了无魂梦到金闺。\n平头上尾慵搜句，重后轻前且灌畦。\n正自无人尝鼎脔，不如有客办萍虀。\n庾郎三九同刍豢，野荠从教施五溪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '连日灌畦莳菜废作诗' AND p.poem_author = '葛立方';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偕少云观永乐班女伶四首 其四', '连横', '近代', '玉楼春帐可怜宵，剑影箫声慰寂寥。一种倾城倾国恨，桃花扇底话南朝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偕少云观永乐班女伶四首 其四' AND p.poem_author = '连横';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水口感事', '符兆纶', '清代', '依旧春山叫画眉，小楼无语卷帘时。五更寒雨酴醾梦，三月东风杨柳枝。\n\n早已伤心到金粉，忽惊满眼是旌旗。再来门巷知何似，莫问飘零沈亚之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水口感事' AND p.poem_author = '符兆纶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游丁次翁筼筜园期次翁不至', '陈傅良', '宋代', '径蹊曲折屋参差，半是天成半自治。修竹万竿人独立，我来搔首菊花期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游丁次翁筼筜园期次翁不至' AND p.poem_author = '陈傅良';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏日郊行', '玄烨', '清代', '节变春方去，清和助麦秋。蔚林乘早夏，茂草接新流。\n\n柳絮堤边起，荷钱水上浮。风光殊旧日，此意未曾休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏日郊行' AND p.poem_author = '玄烨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('文太仆之京过定山言别诗以赠之 其二', '庄昶', '明代', '一笑曾蒙旧雨知，相留今果得吾师。平生邵学心徒切，老去凡庸拜悔迟。\n\n灯火定山聊我榻，草鞋天目更何时。白头但恐还相弃，写在溪云赠别诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '文太仆之京过定山言别诗以赠之 其二' AND p.poem_author = '庄昶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荷花', '江万里', '宋代', '结亭临水似舟中，夜雨潇潇乱打篷。\n荷叶晓看元不湿，却疑误听五更风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荷花' AND p.poem_author = '江万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('马上口占二首 其二', '秦观', '宋代', '霜风棱棱万木枯，梅花破萼犹含须。田家往往事游猎，追逐狐兔相号呼。\n\n微茫山中起狂烧，隐约林梢低日车。马头渐觉有佳趣，勿厌阡陌多萦纡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '马上口占二首 其二' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('零卉集百首 其九十七', '陈永正', '当代', '一梦何堪醒夕曛，馀情眷眷复成云。风凄卷幔香何在，啼笑而今渐不分。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '零卉集百首 其九十七' AND p.poem_author = '陈永正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和徐季功墨梅 其一', '王之道', '宋代', '閒想窥池倒影，戏成落笔斜枝。纵涅难淄玉质，细看何似当时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和徐季功墨梅 其一' AND p.poem_author = '王之道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凤岫春雨', '陈廷璧', '清代', '膏雨油然洒，名山淑景新。浮青凌碧落，含翠媚芳春。\n\n岫霭云根湿，天和巘影真。锦屏怜竹后，万卉净无尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凤岫春雨' AND p.poem_author = '陈廷璧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留守相公移镇汉东', '欧阳修', '宋代', '周郊彻楚坰，旧相拥新旌。路识青山在，人今白首行。\n\n问农穿稻野，候节见梅英。腰组人稀识，偏应邸吏惊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留守相公移镇汉东' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小游仙词 其六', '张翥', '元代', '五岳真官立帐前，露芜香霭落琼筵。夜深醮罢各归去，一一马声嘶上天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小游仙词 其六' AND p.poem_author = '张翥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠林倅', '许应龙', '宋代', '元是清都紫府仙，出为名世应半千。发矢两科俱中的，英名烜赫斗横天。\n\n鄞水富沙典芹泮，黜浮崇雅文风焕。沙阳之政宽而明，吏不忍欺民不玩。\n\n双飞凫舄造皇州，三台八座俱挽留。辞荣避宠姑别驾，恬退高节前无俦。\n\n千里提封勤赞理，恕以待人严律己。一轮秋月照无私，百尺春潭清见底。\n\n须知作善天降祥，俾耆而艾寿而臧。萱闱朱颜映苍鬓，诜诜兰玉如鸾翔。\n\n匪伊丹诏日边至，策足乌台陟端揆。年年衮绣舞莱衣，瑶池屡献蟠桃瑞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠林倅' AND p.poem_author = '许应龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚望', '张栻', '宋代', '独上荒亭数过帆，横林疎处见苍湾。\n固知不入豪华眼，送与凫鸥自在看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚望' AND p.poem_author = '张栻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天 乙未农历闰重三作', '龙榆生', '近代', '宿雨初乾雀语檐。历头喜见闰重三。回黄老树阴逾密，绣地馀花色转严。\n\n春昼永，午风恬。情知蔗味老来甜。颊间偎著狸奴暖，隐几攲眠懒下帘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天 乙未农历闰重三作' AND p.poem_author = '龙榆生';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠王介甫', '段缝', '宋代', '溪桥久废湮，竹树半攲侧。梦寻六代尘，老构一椽宅。\n\n谁知江令门，犹倒山公舄。霸气消旧朝，歌声慨陈迹。\n\n鼎族昔繁华，荒径今岑寂。愿言辟榛芜，重与开景色。\n\n石叠云自生，渠凿流不息。我幸卜公邻，望衡步咫尺。\n\n晨夕惬素心，把臂共悦怿。西崦带烟樵，南埭钓水食。\n\n底事忧怦怦，相将爱惕惕。或筑吟诗坛，或设谈经席。\n\n焉知才不才，聊各适其适。岸帻豁眼界，挥麈吐胸臆。\n\n陇晴许扶鸠，水涨可𣏾鹢。嗒然得丧忘，往事莫凄恻。\n\n佳会不可常，岁月岂抛掷。蒙庄赖妻贤，渊明空子责。\n\n弱木手自栽，勿徒嗟立壁。滋培待其成，斧削工师职。\n\n更为广轩亭，左右支图籍。钟山挹爽来，烟鸟纷若织。\n\n绿菘篱下采，金尊池上涤。此盟更岁寒，一笑星发白。\n\n箸力如未尽，尚能越阡陌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠王介甫' AND p.poem_author = '段缝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丰乐楼', '李符', '清代', '霜天正排字雁，恋樵林钓渚。典裘醉、孙楚楼头，华夫吟屐曾住。\n\n忆同溯、冰潮挂席，君归四百烟峰去。为寒梅，琼萼东风，乱零无主。\n\n我亦西游，鸟道束马，满青袍瘴雨。点苍客、才整蛮装，洞庭红照烽橹。\n\n纵题书、禽衔不到，黯凝睇、珊瑚洲树。著秋衣，香叠芙蓉，采兰何处。\n\n凌波军散，便拨荪桡，秣陵寄倦旅。画船有、比肩人载，月姊应是，笔格梳函，锦鲛绡护。\n\n东田翠麓，松扉堪结，漫伤前度吹箫偶。更闲寻、细草钿车路。\n\n离箱乍启，且翻叶叶银钩，几卷岭外新语。\n\n凫花一盏，蜜炬双条，话别情最苦。对寂寞、山川如此，忍听空江，拍浪声中，又催津鼓。\n\n残星浦口，藤鞭茸帽，诗腰鞍背人影瘦，觅金门、饥朔神仙侣。\n\n重来还约明年，柳碧卢沟，那时记否。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丰乐楼' AND p.poem_author = '李符';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('活死人窝，为番阳胡道玄赋', '郑元祐', '元代', '我尝梦登天，身乘帝青云。下视六合大，死人何纷纷！\n\n尸行鬼走不知丑，天跳鬼踔无由分。首戴髑髅蒿两目，肠悬题凑空孤坟。\n\n自谓策神智，可以干明君。自谓雕纂组，可以成华文。\n\n自谓昭旗常，可以铭前勋。形如枯株心强活，气如湿灰耳强闻。\n\n哀哉腥腐窟，何以能超群？天孙为余言，此皆不足云。\n\n累累白骨成飞尘，安知中有不死人？眉厖喉结目如电，挥呵风雨走百神。\n\n塌额玉陛下，自称小兆臣。臣之形骸与众等，久断荤血腐肉皴。\n\n言臣不死诚谬妄，固有不死丹元君。丹元君，在何处，泥丸真人且延驻。\n\n一曲鸾笙五百年，死人窝里翻身去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '活死人窝，为番阳胡道玄赋' AND p.poem_author = '郑元祐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望雨', '卢龙云', '明代', '入夏愁多雨，无端旱亦随。阴阳时未若，调燮事堪疑。\n\n蒿目忧田畯，斋心问雨师。恒旸当有尽，甘澍应无私。\n\n实颖将盈亩，蕃滋可后时。泽由天地泰，功薄桔槔施。\n\n待取禾三百，还看穗两岐。风云即欲合，草木已先知。\n\n幸及如时化，何言靡孑遗。题诗催雨至，却异雨催诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望雨' AND p.poem_author = '卢龙云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水月宫', '朱学熙', '明代', '为探灵嚣迹，先寻水月宫。慧香连斗极，花雨漫瑶空。\n\n犬吠白云外，僧禅翠霭中。十年迷下界，聊此息微躬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水月宫' AND p.poem_author = '朱学熙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵朋元久雨', '范成大', '宋代', '谁酿愁霠玉宇间，都缘梅子要斓斑。\n腾腾困思午犹梦，扰扰奔云风未还。\n休问满城骑马滑，不妨长日闭门闲。\n今朝晴色熹微似，乾鹊飞来语屋山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵朋元久雨' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂咏一百首·投梭女', '刘克庄', '宋代', '琴挑何曾动，梭投未免惭。\n女郎循古礼，元不解清谈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂咏一百首·投梭女' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头 其二 红梅', '曹冠', '宋代', '造物巧钟赋，新腊报花期。江梅清瘦，只是洁白逞芳姿。\n\n我欲超群绝类，故学仙家繁杏，秾艳映横枝。朱粉腻香脸，酒晕著冰肌。\n\n玉堂里，山驿畔，最希奇。谁将绛蜡笼玉，香雪染胭脂。\n\n好向歌台舞榭，斗取红妆娇面，偎倚韵偏宜。羌管莫吹动，风月正相知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头 其二 红梅' AND p.poem_author = '曹冠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和游金山', '秦观', '宋代', '江流会扬子，汹汹东南骛。\n海门划前开，金山屹中据。\n鼓锺食万指，金雘栖千柱。\n夜庭游月波，晓观抟香雾。\n天清猿鸟哀，风暗鱼龙怒。\n云物横古今，涛波阅晨暮。\n三州气色来，上下端倪露。\n伟哉元气间，此胜知谁聚。\n念昔憩精庐，登临辄忘去。\n汲新试团月，饭素羹魁芋。\n妙兴入芳藤，真境在芒屦。\n别来景暑换，寤寐经从处。\n忽蒙珠璧投，了与云峦遇。\n幽光炯肝肺，爽气森庭户。\n区中多滞念，方外饶奇趣。\n寄语山阿人，泠然行复御。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和游金山' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别饰道二十弟', '晃冲之', '宋代', '少传傅三朝气老，文章壮九州。\n赋诗资政殿，赐字太清楼。\n拔烛辞轩陛，簪花近冕旒。\n庆门吾老矣，华国汝能不。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别饰道二十弟' AND p.poem_author = '晃冲之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦中歌 其二 为白面少年歌', '张生妻', '唐代', '劝君酒，君莫辞。落花徒绕枝，流水无返期。莫恃少年时，少年能几时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梦中歌 其二 为白面少年歌' AND p.poem_author = '张生妻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古冈八景和叶六桐明府韵 其一 黄云樵笛', '李之世', '明代', '閒听风林笛一声，飞花片片递林轻。樵人指点云生处，石齿参差路未平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古冈八景和叶六桐明府韵 其一 黄云樵笛' AND p.poem_author = '李之世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂七十一首 其七十', '释了惠', '宋代', '生于秽土，不受点污。目顾四方，周行七步。看来步步讨便宜，落水也要占乾处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂七十一首 其七十' AND p.poem_author = '释了惠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题高寺丞竹', '吴宣', '明代', '虚怀延伫半生心，寥廓相逢恨转深。云合洞庭鱼鸟散，弦鸣清庙管鼗沉。\n\n吴刚月殿鸾空舞，丁令辽阳鹤错寻。馀慨欲论犹未得，天涯别后听遐音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题高寺丞竹' AND p.poem_author = '吴宣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暗香 壬子寄巢云', '陈曾寿', '清代', '旧痕凄断，是年时携手，虎坊桥畔。愁护暮鸦，芳树阴阴后堂见。\n\n还踏天街月影，乍忘了、西风冰簟。谁管他、如叶青衫，弦底玉龙怨。\n\n争羡，御香染。尽夜夜露痕，襟袖难浣。几时清浅，赢得铜仙泪空满。\n\n重觅剪灯心事，除付与、梦中庭院。却又怕、寻去也，梦中都换。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暗香 壬子寄巢云' AND p.poem_author = '陈曾寿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('柴关', '陈肇兴', '清代', '清泉白石锁柴关，豪气销残梦寐间。屈指百年惊渐老，回头万事不如閒。\n\n悠悠落日牛羊下，策策空林倦鸟还。唯有丹心依旧在，浮云望断海中山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '柴关' AND p.poem_author = '陈肇兴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南川别墅四首 其四', '林光', '明代', '勒马斜阳渡汉川，风波回首信天缘。身随蜀相躬耕后，心出羲爻未画前。\n\n玉粒香粳添日膳，草茵松榻饱宵眠。儿曹更祝公强健，尽道今年胜旧年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南川别墅四首 其四' AND p.poem_author = '林光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八月十五夜月有五色华晕二首 其二', '黄省曾', '明代', '满月漾昭回，澄辉穆气催。望宫华缀幕，飞镜彩妆台。\n\n作晕龙文杂，为图凤色开。凉风寒殿早，天锦定应裁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八月十五夜月有五色华晕二首 其二' AND p.poem_author = '黄省曾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('姑苏馆上元前一夕陪使客观灯之集', '杨万里', '宋代', '节物催人又一年，银花莲炬照金尊。\n麝鎚官样陪公讌，粉茧卿风忆故园。\n何似儿孙谈草草，不妨灯火半昏昏。\n人生行止谁能料，今夕苏州看上元。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '姑苏馆上元前一夕陪使客观灯之集' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和南质张学士敏之见赠七首 其七', '耶律楚材', '元代', '衣龙钟，鬓飘萧，穹庐停烛坐寒宵。翰林遣介赠佳句，虿芒鸟迹书生绡。\n\n既倒狂澜再扶起，昔有谪仙原姓李。今日龙庭忽见君，谁道当年太白死。\n\n文章气象难形容，腾龙翥凤游秋空。笔力万钧神鬼泣，雷轰电掣驱疾风。\n\n馀裕喜君能绰绰，鼓舞为君予矍铄。解读奇字笑扬雄，识厌张华能物博。\n\n与君握手天山边，举觞相嘱望青天。他年雅社结白莲，林泉杖屦冲云烟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和南质张学士敏之见赠七首 其七' AND p.poem_author = '耶律楚材';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄人', '胡楚', '宋代', '不见当年丁令威，\n年来处处是相思。\n若将此恨同芳草，\n犹恐青青有尽时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄人' AND p.poem_author = '胡楚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢张提学惠薏苡仁', '邵宝', '明代', '辟湿初闻薏苡仁，涯翁诗里见来真。东风吹送台端贶，活火山泉共作春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢张提学惠薏苡仁' AND p.poem_author = '邵宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('恭次家大人初抵季弟海陵官舍之韵', '孙应求', '宋代', '食贫宁问肉如陵，且喜官曹简事程。\n千里平淮随地阔，一江远水照水明。\n几我怀古登临意，时作搔头讽咏声。\n酬唱敢希朱树秀，粗分菽麦异周兄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '恭次家大人初抵季弟海陵官舍之韵' AND p.poem_author = '孙应求';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晨兴', '黄假我', '近代', '已成诗句墨痕干，肠热终难压胆寒。马足车尘由世路，鸡声灯火误儒冠。\n\n却无可却三年艾，精益求精百尺竿。一笑开轩迎杲杲，万枫叶老竞舒丹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晨兴' AND p.poem_author = '黄假我';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凭栏人', '张可久', '元代', '小玉栏杆月半掐，嫩绿池塘春几家。鸟啼芳树丫，燕衔黄柳花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凭栏人' AND p.poem_author = '张可久';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题徐庆超春波洗砚图 其一', '梁章钜', '清代', '楼船横海纪殊勋，缓带轻裘又见君。一片绿波朝涤砚，满堂红烛夜论文。\n\n传来去病真无敌，写入丹青更不群。燕颔虎头奇相在，凌烟褒鄂漫风云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题徐庆超春波洗砚图 其一' AND p.poem_author = '梁章钜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读曹明贤君蜀鹃诗稿二首 其一', '张秉衡', '近代', '炉灭灯残不寐时，枕旁一卷晓陶诗。老夫也是悲观派，爱听蜀鹃入夜啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读曹明贤君蜀鹃诗稿二首 其一' AND p.poem_author = '张秉衡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庚戌九月自吴返越嘉禾道中 其二', '王拯', '清代', '犹有残蝉挂别枝，纺车声乱豆花篱。蘋乡又听新蛩语，寒女功裘待上机。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庚戌九月自吴返越嘉禾道中 其二' AND p.poem_author = '王拯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自题国朝诗正气集', '张应昌', '清代', '忠孝节义事，史传志乘详。咏叹兴感易，重此歌诗章。\n\n所以载笔者，联珠标群芳。英辞鼓正气，岂惟阐幽光。\n\n往古难尽数，断自今虞唐。醇化二百载，盛碑碣祠坊。\n\n但计歌诗篇，万首罗琳琅。所见择尤雅，阙者待补亡。\n\n一读一击节，其气至大刚。比日星河岳，如芝兰鸾皇。\n\n教痒塾妇孺，播管弦宫商。油然孝弟生，幡然顽懦良。\n\n胜彼志传文，长吟沁肝肠。愿传万本读，振世扶纲常。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自题国朝诗正气集' AND p.poem_author = '张应昌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闲游', '李建勋', '唐代', '携酒复携觞，朝朝一似忙。马谙频到路，僧借旧眠床。 \n 道胜他图薄，身闲白日长。扁舟动归思，高处见沧浪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闲游' AND p.poem_author = '李建勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙 元夕', '黄淮', '明代', '忆昔帝城三五夜，簪缨曾侍宸游。山移鳌背对龙楼。\n\n一天星斗下，万文瑞光浮。\n\n箫鼓声中催赐饮，归来月在帘钩。而今白发叹淹留。\n\n寒窗灯影里，飞梦绕瀛洲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙 元夕' AND p.poem_author = '黄淮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和所盘风字韵', '丘葵', '宋代', '二十四番花信风，到头谁白又谁红。\n寻春不用苦我感，有酒且须时一中。\n吾辈於人长落落，浮生虽梦亦匆匆。\n未知今岁沧浯上，握手论心几度同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和所盘风字韵' AND p.poem_author = '丘葵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('壬子仲冬上京族中弟侄送过石门而别 其二', '祁顺', '明代', '南北舟中两渺茫，相思情与海天长。隔篷侵晓闻人语，犹讶诸君在耳傍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '壬子仲冬上京族中弟侄送过石门而别 其二' AND p.poem_author = '祁顺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题南国风光画册十六首 其六 停织暴衣', '吴妍因', '清代', '贱卖番麻贵买纱，鸳机不解织云霞。衣成且喜能勤浣，挈出清波无点瑕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题南国风光画册十六首 其六 停织暴衣' AND p.poem_author = '吴妍因';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('至正戊子下第南归与同贡黄章仲珍雷燧景阳同', '陶安', '明代', '凤城酒美燕姬歌，禁花红飘金水河。\n雨香翠岛春昼暖，鱼龙陆海扬风波。\n天门咫尺到不得，奈此飙摧云翼何。\n时乎未至应有待，壮年不必伤蹉跎。\n君看松柏成大材，历岁雪霜谁见过。\n拂衣南出指归路，回首京阙山嵯峨。\n日高原头红雾散，潮平沽口青铜磨。\n牵船溯流狂吹逆，登车避闸飞尘多。\n黄楼凭河远眺望，身如冥鸿超网罗。\n客涂笑语浣羁思，词锋捷出如挥戈。\n天生人才必用世，岂无文藻宣金科。\n鸾台凤阁总华要，不然玉署聊鸣珂。\n丈夫小挫未为辱，正气耿耿非有它。\n匣中古砚助神变，铜蟾饱水手屡摩。\n随身亦有勋业镜，依然照我颜色酡。\n与君今日动高兴，买酒共酌浇天和。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '至正戊子下第南归与同贡黄章仲珍雷燧景阳同' AND p.poem_author = '陶安';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送郑尚书守建安十首 其八', '彭龟年', '宋代', '从此褰帷去帝乡，闾阎辛苦足平章。皂囊若有新丰奏，才过龙团第一纲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送郑尚书守建安十首 其八' AND p.poem_author = '彭龟年';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湖州 其一', '戴表元', '宋代', '山从天目成群出，水傍太湖分港流。行遍江南清丽地，人生只合住湖州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湖州 其一' AND p.poem_author = '戴表元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('涵碧亭', '葛洪', '宋代', '雨歇留蒸湿，明来得翳凉。\n双嬉鱼欲动，万个竹添长。\n景到烦诗答，叹多厄日忙。\n兹游端胜绝，不是学高阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '涵碧亭' AND p.poem_author = '葛洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('嗅梅', '范成大', '宋代', '雪意勒花愁未解，背阴一朵寒先退。\n东风还是去年香，不比人心容易改。\n宿酒瞢腾正耐春，花枝人面两时新。\n相看好作风流伴，只恐花枝却妒人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '嗅梅' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桂林岁晚忆钟尚书', '乐雷发', '宋代', '尘满湘翁薜荔衣，江湖岁晚鬓成丝。桂州杨五今何处，雪片梅花枉费诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桂林岁晚忆钟尚书' AND p.poem_author = '乐雷发';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居诗 其一', '明河', '明代', '东溪信非遥，咫尺篱门外。桥头看落花，昨日莺声在。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居诗 其一' AND p.poem_author = '明河';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '释惠崇', '宋代', '寒灯催臘尽，晓角唤春归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '释惠崇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其五', '曾纡', '宋代', '苔侵垂磴蔓，竹隐断岩花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其五' AND p.poem_author = '曾纡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和刘工部钦谟无题韵 其二', '童轩', '明代', '金殿萤流月半沈，谩思当日宠恩深。风清香箧捐秋扇，露冷空闺急暮砧。\n\n别院频翻鹅管玉，长门深锁兽环金。可怜碧海青天外，谁识姮娥夜夜心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和刘工部钦谟无题韵 其二' AND p.poem_author = '童轩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浪淘沙·宿华清宫次日又续前调寄怀', '吴禄贞', '当代', '征马歇临潼。唐代离宫。贵妃几度浴春风。遥忆沉香秋夜月，花影朦胧。\n\n皓月照庭中。睡梦溟濛。悲鸣寒夜怨秋鸿。想到美人离别恨，身世飞蓬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浪淘沙·宿华清宫次日又续前调寄怀' AND p.poem_author = '吴禄贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('胡伯玉隐趣图四咏 其一 蜀锦屏', '陈樵', '元代', '朝看花中仙，颜色媚且鲜。暮看花中仙，颜色忽己蔫。\n\n红芳不足恃，青春政堪怜。人生宇宙中，寿无金石坚。\n\n百岁等瞬息，业火徒熬煎。何如鍊金液，返本得长年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '胡伯玉隐趣图四咏 其一 蜀锦屏' AND p.poem_author = '陈樵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题鬼趣图十五首 其十五', '寇梦碧', '近代', '逐鹿将焉托蕉叶，战龙旋复入槐根。此中安得王延寿，为我挥刀斩梦魂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题鬼趣图十五首 其十五' AND p.poem_author = '寇梦碧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行香子·五鼓才成', '王哲', '元代', '五鼓才成，土德行香。偏能将、四象包藏。如今尽显，聚在中央。没白归青，红归黑，不归黄。已证空虚，便出昆冈。金童来、秘语宣扬。天皇赐韶，授与风狂。永处清闲，常清静，得清凉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行香子·五鼓才成' AND p.poem_author = '王哲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('木兰花慢', '王丹桂', '元代', '叹滔滔苦海，任群迷，恣漂游。被有限形躯，无涯爱欲，一向拘囚。\n\n空生万千计较，况百年、短景不常留。贪为名深利切，岂期水远山悠。\n\n如流。岁月相催，宜省悟，觅抽头。向太一峰前，双林树下，早把心收。\n\n从来既知是错，待番番、放下便休休。撒手纵横无碍，状同不系之舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '木兰花慢' AND p.poem_author = '王丹桂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百一十七首 其三十九', '释绍昙', '宋代', '独坐大雄峰，临机多弄险。遭虎口杀活不分，脱狐身真假难辨。\n\n那堪创立清规，平地深深坑堑。结成不共戴天雠，烧炷枫香解释休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百一十七首 其三十九' AND p.poem_author = '释绍昙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过田中有感', '朱诚泳', '明代', '小人不可用，用则妨善良。稂莠不可容，容则嘉谷伤。\n\n所以田家父，耘锄日皇皇。四体苦胼胝，仅得充饥肠。\n\n奈何治家国，而不谨其防。悠悠感前史，披书徒自伤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过田中有感' AND p.poem_author = '朱诚泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辟疆书然弟病中语览之泫然', '王易', '清代', '檐霜檽雨放秋回，短景难消蚁磨催。袖手江湖天更迥，惊心骨肉梦成灰。\n\n似随飞鸟去无迹，欲上高山呼不来。坏壁应多旧题在，劳君偏写喘丝哀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辟疆书然弟病中语览之泫然' AND p.poem_author = '王易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题项处士山堂二首 其二', '陈造', '宋代', '久安楚俗眠云屋，又向吴侬倒药囊。出处无心俱乐地，世间何处不山堂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题项处士山堂二首 其二' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('疏影 梅景书屋', '吴湖帆', '清代', '春温绣幄。有暗香冉冉，霏雾轻扑。莫道珍禽，明月来时，于中消收清福。\n\n绿窗却展横斜影，任合指、癯仙铃索。纵一枝、觅取幽芳，不似喜神浓馥。\n\n休羡牙签万轴，凭肩且笑语，孤本双读。午梦初回，额上花痕，依旧翻新妆束。\n\n冰姿绰约苕川谱，映雪里、可人如玉。问几生、修到同心，好贮阿娇金屋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '疏影 梅景书屋' AND p.poem_author = '吴湖帆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汪扶晨六十有赠 其二', '屈大均', '明代', '老友稀江左，年龄尽与君。无才真大药，有道总浮云。\n\n得草麑相命，逢花鹤不分。未知潜口路，多少桂丛薰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汪扶晨六十有赠 其二' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵杨柳枝词', '杭济', '明代', '东风袅袅拂朱阑，万树千条露未干。\n玉涘声中人不见，倚楼烟雨正春寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵杨柳枝词' AND p.poem_author = '杭济';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙（梅菁山遇雪）', '李洪', '宋代', '矢矫翔鸾谿上峰。飘萧雪霰打船篷。天花凌乱水晶宫。 \n 飞透纸窗斜取势，吹回谿面舞因风。身游水墨画图中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙（梅菁山遇雪）' AND p.poem_author = '李洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮 其十七', '黄绮', '当代', '晓来微雨藤花紫。黄莺不语东风起。独立思江天。岸平多草烟。\n\n闲云无定貌。乡思巢枝鸟。云水是天涯。未应伤物华。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮 其十七' AND p.poem_author = '黄绮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋蕊香', '佚名', '宋代', '眼也生应哭破。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋蕊香' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('衡永之间山路艰涩薄晚吏卒鬨云渐近祁阳路已平夷皆有津津之色', '范成大', '宋代', '朝登赤土岭，暮入黄泥谷。春江弄花月，归梦恍在目。\n\n觉来行路难，杜宇叫高木。凹中泥没踝，凸处石齧足。\n\n坐舆我尚病，想见肩舆仆。衡阳复祁阳，可暂不可宿。\n\n晚来出前冈，路坦亭堠促。将士走相贺，喜色如膏沐。\n\n人生本无闷，逆境要先熟。不从忧患来，安识平为福。\n\n夷涂不常遇，历险始知足。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '衡永之间山路艰涩薄晚吏卒鬨云渐近祁阳路已平夷皆有津津之色' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('朝天子·西湖', '徐再思', '元代', '里湖，外湖，无处是无春处。真山真水真画图，一片玲珑玉。宜酒宜诗，宜晴宜雨，销金锅锦绣窟。老苏，老逋，杨柳堤梅开墓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '朝天子·西湖' AND p.poem_author = '徐再思';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苍龙吟', '周巽', '元代', '江潭月冷流清音。紫竹吹作苍龙吟。含商引徵曲意深。\n\n曲意深，泪沾襟。关山远，何处寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苍龙吟' AND p.poem_author = '周巽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('翠凉', '胡仲弓', '宋代', '各章古木影萧森，未必山林如许深。\n才见眼前成绿暗，一年又负种花心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '翠凉' AND p.poem_author = '胡仲弓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送殷孝章之咸阳教谕', '秦约', '明代', '西上长安跋涉劳，三千里外朔风号。地连渭水秦川近，山接终南泰华高。\n\n故国总消龙虎气，断碑犹打骆驼膏。一官莫笑儒林选，曾捧琅函觐赭袍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送殷孝章之咸阳教谕' AND p.poem_author = '秦约';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿悦斋李先生', '程公许', '宋代', '君不见温公崇福十五年，上下千载书法岩。\n又不见蜀公静退不待耄，钟律制成天一笑。\n乐则行之忧则远，出处无非圣之时。\n一朝都人拥马首，留相天子不得辞。\n颍昌胡为几不动，各以就去揭榘仪。\n悦斋先生天下士，琬琰琮璜国镇瑞。\n盛名姱节耀古今年内，岁晚松阶犹候对。\n时台剧谈锯蜚屑，志堂析疑{上竹下氐}启钥。\n夜归风雨一龛灯，目电窥书光烁烁。\n禹贡山川如指掌，漆园之解无郭象。\n更将次五订箕畴，不妨后觉勤鑽仰。\n年来岷峨殊怆悽，公与洁斋名德齐。\n长康磊配晓月，士有司命国蔡蓍。\n卧架诗书差足乐，凭高忍见楚氛恶。\n岂不望公勇拂衣，正恐百姓须公活。\n愿公相业追无佑，以一至诚服雄狡。\n愿公眉寿如东轩，黄发皤皤国元老。\n云蒸雨族沛作霖，贤以类聚治乃兴。\n卷舒在公亦何心，四海矫首四山岑。\n薰风自南一披襟，起舞称寿千黄金。\n洗耳五弦虞氏琴，为公缓轸歌嗣音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿悦斋李先生' AND p.poem_author = '程公许';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('莫宪使补官楚臬继参梁岳奉赠', '皇甫汸', '明代', '闻道除书下紫宸，沧江猿鹤恋征轮。共怜潘令閒居久，可讶山公荐启频。\n\n湘浦兰芳违赠远，河阳花色待行春。汉廷典礼须君草，讵作梁园授简人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '莫宪使补官楚臬继参梁岳奉赠' AND p.poem_author = '皇甫汸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('适得滷颇佳遣饷菊坡因记曾作蛤子诗有文身吴', '郑清之', '宋代', '文身太伯甘斥卤，缄口铜人舌微吐。\n借资墨客富濡沫，骨醉唇香登燕俎。\n半熟含酒老饕赋，此翁仅可闯堂户。\n班班隽永带神液，入室真味翁未睹。\n菊坡风裁黄豫章，如食蝤蛑江{摇扌换虫}柱。\n盘餐尽废太瘦生，格远调高自清苦。\n子蛤遣汝到眉案，努力去为酒中虎。\n末下鹹豉有何好，犹侣莼羹傲伧父。\n海之介夫此小儿，鸡肋见笑杨德祖。\n前身曾作水解仙，飞入珠宫饮甘露。\n能令齿吻策余烈，一鼎松风漱寒乳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '适得滷颇佳遣饷菊坡因记曾作蛤子诗有文身吴' AND p.poem_author = '郑清之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暮春苦雨即事', '德日', '清代', '年来惟有感伤多，九十春光总浪过。镜里容颜空自老，梦中诗句为谁哦。\n\n飞花满院销银蜡，细雨空帘锁黛蛾。可惜繁华零落尽，香残酒冷奈愁何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暮春苦雨即事' AND p.poem_author = '德日';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('癸酉除夜呈邻舍刘秀才', '郭祥正', '宋代', '六十明朝是，今年此夜除。劳生一樽酒，陈事数行书。\n\n腊逐灯缸尽，春回律管初。不愁家信断，安稳藉邻居。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '癸酉除夜呈邻舍刘秀才' AND p.poem_author = '郭祥正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪中寄令狐相公，兼呈梦得', '白居易', '唐代', '兔园春雪梁王会，想对金罍咏玉尘。 \n 今日相如身在此，不知客右坐何人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪中寄令狐相公，兼呈梦得' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送卢章侯年丈罗定应试', '张嗣纲', '明代', '弯孤策杖耀威风，名冠时流自不同。幕府定应虚左席，诸曹何敢望前戎。\n\n拟将长技穿杨绿，况复精忠贯日红。此去纪昌知遇早，看君千骑即飞雄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送卢章侯年丈罗定应试' AND p.poem_author = '张嗣纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洞仙歌', '卢青山', '当代', '少年意气，只爱登楼阅。何事悲凉为飘叶？趁悠閒、先生不欲孤行，正无奈、随挽人间秋色。\n\n拈诗如吐纳，留亦奚为？散与西风争扯拽。此心到处悠然，醉卧东篱，问谁识、庄生蝴蝶？\n\n到醒处一身露如淋，又懒整青衫，浩歌带月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洞仙歌' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('灵芝寺避暑因携茶具汎湖共成十绝', '张镃', '宋代', '城里今年热异常，出城肃寺未全凉。\n发毛吹尽人间暑，除是芙蕖十里香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '灵芝寺避暑因携茶具汎湖共成十绝' AND p.poem_author = '张镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('膝汝载先生卜筑武夷邀余过访余以家慈卧床褥尚孤此约感念今昔不胜怅惘敬赋小诗奉寄凡八章 其八', '胡应麟', '明代', '九折王阳道，千秋大隐庐。云山容负笈，宇宙碍驱车。\n\n业岂门人尽，名犹国士馀。凭将一掬泪，遍洒越山隅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '膝汝载先生卜筑武夷邀余过访余以家慈卧床褥尚孤此约感念今昔不胜怅惘敬赋小诗奉寄凡八章 其八' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐', '刘翰', '宋代', '萋萋芳草。怨得王孙老。瘦损腰围罗带小。长是锦书来少。 \n 玉箫吹落梅花。晓寒犹透轻纱。惊起半屏幽梦，小窗淡月啼鸦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐' AND p.poem_author = '刘翰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('午睡', '舒邦佐', '宋代', '博山烟断懒重添，屋角无声雀去檐。午梦欲成鸡唤醒，卧看修竹映疏帘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '午睡' AND p.poem_author = '舒邦佐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饮振之馆限韵', '顾璘', '明代', '高馆临槐柏，清筵引桂觞。淮南秋望迥，江左故欢长。\n\n气色琼枝映，词华翰墨香。只应今夕会，星聚比陈乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饮振之馆限韵' AND p.poem_author = '顾璘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('静观楼成众山忽见', '王鏊', '明代', '山居尽日不见山，楼上山来自何处。中峰独立群峰随，头角森森出林树。\n\n澄湖万顷从中来，浪捲三山欲飞去。得非奋迅从地出，无乃飞腾自天下。\n\n我来楼上何所为，长日观山与山语。东风吹醉还吹醒，山自为宾我为主。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '静观楼成众山忽见' AND p.poem_author = '王鏊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('越王楼送高梓州入朝', '薛逢', '唐代', '乘递初登建外州，倾心喜事富人侯。让当游艺依仁日， \n 便到攀辕卧辙秋。容听巴歌消子夜，许陪仙躅上危楼。 \n 欲知恨恋情深处，听取长江旦暮流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '越王楼送高梓州入朝' AND p.poem_author = '薛逢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春 眉', '孙云凤', '清代', '纤似蛾儿，翠分螺子，柳叶半弯。忆锦屏娇倚，月横秋水，绣衾慵起，雾锁春山。\n\n翻谱鲜新，入时深浅，女伴端详可否间。消魂处、向碧纱窗下，画了重看。\n\n含情醉拨幺弦。觉红泛桃腮黛更妍。但倾城一笑，舒来堪爱，捧心无语，颦亦增怜。\n\n秀衬风鬟，长侵云鬓，昔日文君欲比肩。风流甚，怕脂凝粉污，淡扫朝天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春 眉' AND p.poem_author = '孙云凤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谒郭道冲唐师德登台偶作', '朱长文', '唐代', '冲寒步郊原，烟水照林薄。\n雪余山色佳，浦浚湖波落。\n静可钓纶垂，清欲尘缨濯。\n相逢两俊友，辞义富金臒。\n携手登高台，谈笑有真乐。\n寸眸周远近，幽思腾寥廓。\n逝将飞片帆，直泛洞庭脚。\n絷维阻并游。搔首向城郭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谒郭道冲唐师德登台偶作' AND p.poem_author = '朱长文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗', '吕陶', '宋代', '夕阴敛层空，素月出西海。寥寥俯仰间，杳不见纤霭。\n\n清光信可掬，璀璨掌握内。虚庭纵远目，中夜如有待。\n\n念我金石交，轻别己十载。德音响球琳，道味芬兰茝。\n\n悠然阻声容，况复接言诲。幽怀愿一写，四顾多泛爱。\n\n回头自珍惜，欲显不如晦。赖此秋蟾魄，千里共光彩。\n\n思贤摇去意，对景慕良会。此夕虽圆明，清赏君何在。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗' AND p.poem_author = '吕陶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('昼寒亭', '韩元吉', '宋代', '月里琼宫不禁寒，谁令白昼堕人间。\n阴风淅淅来深谷，晴雪霏霏溅雨山。\n静爱飞流聊洗耳，坐看绝磴可怡颜。\n红尘势客那知此，赤脚青松意自閒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '昼寒亭' AND p.poem_author = '韩元吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('家园卧疾毕太祝曜见寻①', '孟浩然', '唐代', '伏枕旧游旷，笙歌劳梦思。②\n平生重交结，迨此令人疑。\n冰室无暖气，炎云空赫曦。③\n隙驹不暂驻，日听凉禅悲。\n壮图哀未立，斑白恨吾衰。④\n夫子自南楚，缅怀嵩汝期。⑤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '家园卧疾毕太祝曜见寻①' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题画', '庄昶', '明代', '远山青两峰，老树红一叶。我怀不可羁，空江下明月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题画' AND p.poem_author = '庄昶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九日诸季散处长乐外邑怅然有怀二首 其一', '李纲', '宋代', '去岁初从海上回，重阳相与醉高台。那因寇盗迁南土，阻插茱萸共一杯。\n\n老矣但思情话切，跫然更望足音来。黄花也解知人意，故向篱边未肯开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九日诸季散处长乐外邑怅然有怀二首 其一' AND p.poem_author = '李纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂咏遣怀六首 其四', '苏葵', '明代', '怀中明月何曾暗，意里阳春不□寒。三十六宫天地迥，自家来往自家看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂咏遣怀六首 其四' AND p.poem_author = '苏葵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赋得吴王送女潮歌，送李判官之河中府', '皎然', '唐代', '见说吴王送女时，行宫直到荆溪口。溪上千年送女潮， \n 为感吴王至今有。乃知昔人由志诚，流水无情翻有情。 \n 平波忽起二三尺，此上疑与神仙宅。今人犹望荆之湄， \n 长令望者增所思。吴王已殁女不返，潮水无情那有期。 \n 溪草何草号帝女，溪竹何竹号湘妃。灵涛旦暮自堪伤， \n 的烁婵娟又争发。客归千里自兹始，览古高歌感行子。 \n 不知别后相见期，君意何如此潮水。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赋得吴王送女潮歌，送李判官之河中府' AND p.poem_author = '皎然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高骈、薛涛', '佚名', '唐代', '口，有似没量斗。（高骈） \n 川，有似三条椽。（薛涛）', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高骈、薛涛' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('普缘塔', '何景明', '明代', '石盖凌空起，丹梯出翠微。云从珠顶覆，灯转镜中辉。\n\n雁沼波涛涌，龙宫日月围。何能攀绝顶，一览汉邦畿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '普缘塔' AND p.poem_author = '何景明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('客珠崖怀罗浮寄山中诸子三十韵 其六', '成鹫', '明代', '溪山非舌亦非身，久去重来见益亲。四百峰中开别院，三千里外结芳邻。\n\n苔生碧砌青如染，镜锁明窗净不尘。为报诸方参学者，罗浮深处近无人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '客珠崖怀罗浮寄山中诸子三十韵 其六' AND p.poem_author = '成鹫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆秦娥 其一 梅', '俞彦', '明代', '春寒熟。溪梅已绽枝头玉。枝头玉。照人明媚，殢人芬馥。\n\n东皇为我怜幽独。小楼细雨眠初足。眠初足。一番花信，一番裀褥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆秦娥 其一 梅' AND p.poem_author = '俞彦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题西湖亭子寄徐复初简校', '乌贝勒图', '元代', '芙蓉花开一万顷，钱塘最好是湖边。晓风得酒更留月，春水到门还放船。\n\n笙引凤凰天上曲，赋裁鹦鹉座中贤。令人却忆徐公子，深阁焚香日晏眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题西湖亭子寄徐复初简校' AND p.poem_author = '乌贝勒图';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江上', '释文珦', '宋代', '无柰春芳损客心，每於江上独行吟。\n朝朝莫莫寒潮水，不似归愁一度深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江上' AND p.poem_author = '释文珦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荔枝', '张舜民', '宋代', '柳江六月水如汤，江边荔枝红且黄。\n摘时须是带枝叶，满盘璀璨堆琳瑯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荔枝' AND p.poem_author = '张舜民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('相见欢', '濮文绮', '清代', '匆匆又过清明。月黄昏。那处绿杨庭院、落花深。\n\n已别去。总无计。苦叮咛。可是六朝春梦、未醒人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '相见欢' AND p.poem_author = '濮文绮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岁残风雨满腹牢骚，拈笔长吟藉舒沈闷二首 其一', '王德爵', '清代', '西风残柝满城哀，挑尽青镫百感来。绿柳何堪经雨雪，紫云深悔出蓬莱。\n\n此生事业惟酬梦，来世天公莫派才。自愿无知如草木，和烟和雨老黄埃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岁残风雨满腹牢骚，拈笔长吟藉舒沈闷二首 其一' AND p.poem_author = '王德爵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪消', '陶望龄', '明代', '柔姿能耐几时消，况是春来腊后飘。\n晓幕薄寒飞旋湿，夜窗多恨滴无憀。\n风前赵女愁堪诉，老去郎颜鬓易凋。\n惟有山梅解相惜，深崖铁干锁冰条。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪消' AND p.poem_author = '陶望龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山园示游人', '王世贞', '明代', '携酒看花不碍频，唯求酒后护残春。\n不辞树树凭攀折，孤却明朝花下人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山园示游人' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('铅山道中', '李纲', '宋代', '行李踰江峤，风烟接武夷。地灵嘉木秀，天阔暝云垂。\n\n泉石日相乐，雪霜寒自迟。寄声山下士，扫壁待题诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '铅山道中' AND p.poem_author = '李纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('屈指归来日效白体七首 其六', '毕自严', '明代', '屈指归来日，荒园满绿苔。夷犹堪得句，放浪可衔杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '屈指归来日效白体七首 其六' AND p.poem_author = '毕自严';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('对瀑', '弘历', '清代', '昨夜秋雨飞千山，湢湱飒沓喧冈峦。隔窗檐溜已落瀑，真瀑翻在想像间。\n\n今朝快霁澄浮烟，是声皆寂惟瀑悬。乃知幻者有作歇，何如真者恒当前。\n\n我每对瀑率得句，欣兹会心有别趣。四柱虚亭百尺崖，让他常住无来去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '对瀑' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('定林院昭文斋', '王安石', '宋代', '定林斋后鸣禽散，只有提壶守屋檐。苦劝道人沽美酒，不应无意引陶潜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '定林院昭文斋' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题清风岭王氏烈女祠', '李昱', '明代', '犹闻虎旅下天戈，庙宇经年长薜萝。玳瑁簪斜蛛网密，石榴裙短燕泥多。\n\n即于白刃全吾操，为至清风奈尔何。赖有篇诗畹血迹，清名不废逐江波。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题清风岭王氏烈女祠' AND p.poem_author = '李昱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诸虫名呼被于人事因据为义者凡八物各赋一章 其二 猾', '倪元璐', '明代', '从无肉离骨，可信是甘柔。蝮子贻蛇患，桃虫通鸟谋。\n\n智囊瘿是毒，警枕梦如流。想见李林甫，蜂脂铸镯镂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诸虫名呼被于人事因据为义者凡八物各赋一章 其二 猾' AND p.poem_author = '倪元璐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('明月池', '敖启潜', '清代', '尔雅台前月，流光到墨池。苔痕相映碧，犹忆注经时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '明月池' AND p.poem_author = '敖启潜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙 其二', '周燕婷', '当代', '羞向人前说脊令，惊风吹散旧时情。当时有月透窗棂。\n\n落尽梨花怜寂寞，难为枫叶耐飘零。圆圆晴月又当庭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙 其二' AND p.poem_author = '周燕婷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟夜不寐怀直夫', '唐树义', '清代', '几年踪迹赋江蓠，四海论交说共谁。别后更无诗可读，近来惟有月相随。\n\n曾游五岳君真健，不负千秋我所思。记取长安风雨夜，一樽清对数吟髭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟夜不寐怀直夫' AND p.poem_author = '唐树义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮　 其五 回文', '丁澎', '清代', '数重花幔穿金缕。缕金穿幔花重数。愁处是高楼。楼高是处愁。\n\n凤钗横压梦。梦压横钗凤。通梦两心同。同心两梦通。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮　 其五 回文' AND p.poem_author = '丁澎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('邢州别于鳞 其一', '王世贞', '明代', '西来天地坼，无恙太行城。二子狂歌发，千山秋思生。\n\n世人殊黯淡，何物与纵横。不独文章在，兼齐拙宦名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '邢州别于鳞 其一' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湖村八景 其二 绮岫云来', '徐搢珊', '清代', '先人卜筑意何深，常与南山共古今。翠嶂遥观时独坐，白云相对寄长吟。\n\n从龙变化非无志，护鹤勾留恰有心。更喜游行情似我，不嫌日日到西林。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湖村八景 其二 绮岫云来' AND p.poem_author = '徐搢珊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洪参戎和平大捷喜而有赠 其二', '叶春及', '明代', '飞将分符出，提戈奏凯回。裹尸真国士，推毂岂时才。\n\n列队蛇矛动，前驱鹭鼓催。汉庭多宠渥，陆贾是功魁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洪参戎和平大捷喜而有赠 其二' AND p.poem_author = '叶春及';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长亭怨', '谭献', '清代', '看春老、飞花飞絮。燕子来时，绿窗朱户。不浣闲愁，漫煎离恨奈何许。\n\n妾魂销矣，最恨是、沙头树。相送客舟行，却不道、天涯从此。\n\n欲暮。想征衫乍解，双袖泪痕无数。玉环锦带，是纤手、背人亲付。\n\n算此后、步步关情，似花发、空阶无主。更不遣、分明凄断，柔肠一缕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长亭怨' AND p.poem_author = '谭献';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('孟夏雨后寄黍谷弟园居 其一', '钱陆灿', '清代', '缅想前贤咏五君，同堂能不感离群。礼无大树留三宿，诗有长城张一军。\n\n独夜完完心上月，相思袅袅望中云。传言二子非凡鸟，我马玄黄日易曛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '孟夏雨后寄黍谷弟园居 其一' AND p.poem_author = '钱陆灿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔家傲 其二 闲居', '梁清标', '明代', '朝霁窥窗三径晓。草堂昼静闻啼鸟。插懂编篱随意好。\n\n云自到。落英一任西风扫。\n\n啜茗摊书尘事少。开残黄菊寒催早。蚁战蜂围何日了。\n\n青门道。回头不满山人笑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔家傲 其二 闲居' AND p.poem_author = '梁清标';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜行溪谷间梅花迎路香影离离可爱', '柳贯', '元代', '暝投村径绕羊肠，离立江梅似雁行。冷蕊微开初的皪，繁枝乱插更凄凉。\n\n苍烟挂树多疑梦，淡月窥林稍觉香。正为先生行役苦，故留皴玉荐奚囊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜行溪谷间梅花迎路香影离离可爱' AND p.poem_author = '柳贯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九日闲居并序', '陶潜', '魏晋', '世短意恒多，斯人乐久生。日月依辰至，举俗爱其名。\n\n露凄暄风息，气澈天象明。往燕无遗影，来雁有馀声。\n\n酒能祛百虑，菊解制颓龄。如何蓬庐士，空视时运倾！\n\n尘爵耻虚罍，寒华徒自荣。敛襟独闲谣，缅焉起深情。\n\n栖迟固多娱，淹留岂无成？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九日闲居并序' AND p.poem_author = '陶潜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乌鲁木齐杂诗之风土 其二', '纪昀', '清代', '万家烟火暖云蒸，销尽天山太古冰。腊雪清晨题牍背，红丝砚水不曾凝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乌鲁木齐杂诗之风土 其二' AND p.poem_author = '纪昀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠拆字嗅衣相士', '文天祥', '宋代', '水水坎离紫阳怪，滑波皮骨长坡骇。\n解州得解解中胶，费家封铺同一解。\n唫字从金诗反穷，贝何为分田何同。\n黄绢幼妇我自乐，竹犬多事鸦鹤翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠拆字嗅衣相士' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏海棠', '于倞', '宋代', '和风春满园，草木皆芳薰。\n君看十八叶，具与凡卉群。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏海棠' AND p.poem_author = '于倞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('张助甫席上同吴峻伯白伯伦再饯朱主客南还赋得江飞兢渡日草见踏青心十韵 其三', '宗臣', '明代', '夜夜歌阳春，青皇失其柄。君携瑶草归，蘼芜孰敢兢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '张助甫席上同吴峻伯白伯伦再饯朱主客南还赋得江飞兢渡日草见踏青心十韵 其三' AND p.poem_author = '宗臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望宸阁雪后', '韩琦', '宋代', '重阴初释六花残，试倚危栏一望看。魂爽顿如居物外，句新难得上毫端。\n\n酒收豪席珊瑚碎，风刮仙盘沆瀣乾。化就兜罗绵世界，鹫宫高插白云寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望宸阁雪后' AND p.poem_author = '韩琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乐隐为尹克俊赋', '萧镃', '明代', '行爱溪中水，坐爱溪上山。富贵非所愿，悠然心自闲。\n\n地偏轮鞅稀，蓬门昼常关。清风天外来，入我窗牖间。\n\n岂无一尊酒，可以销忧颜。叶落惊秋徂，鸟啼知春还。\n\n既忘是与非，宁复虞险艰。雅志固如此，高踪可安攀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乐隐为尹克俊赋' AND p.poem_author = '萧镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('罗浮何君祐夫相访惠诗又出所作水墨鱼戏题卷末', '李昴英', '宋代', '山头钓引千钧鱼，铁桥曾逢稚川奴。风波平地误点额，戏取墨汁翻模糊。\n\n纵观濠上契妙趣，浩浩胸次涵江湖。墨云忽从砚池起，拨剌跳出形模殊。\n\n大鱼腾骧撼风雨，小鱼琐碎游荇蒲。技如元放几许奇，金盘一个松江鲈。\n\n试张亭前涨波影，舂锄飞下傍睢盱。世间画史少活笔，描写终类鲋肆枯。\n\n文溪一湾浮钓徒，欠得龙眠为严濑羊裘图。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '罗浮何君祐夫相访惠诗又出所作水墨鱼戏题卷末' AND p.poem_author = '李昴英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哀淮人', '严允肇', '清代', '驱车适海岱，日暮行人愁。饿夫相枕藉，老弱罗道周。\n\n挥涕前致词，淮楚是吾州。渠穿广陵道，水纳黄河流。\n\n舳舻来吴会，东北通咽喉。一朝河岸决，漫衍东南陬。\n\n百万为鱼鳖，何论田与畴！窜身来此方，苟活同蜉蝣。\n\n此方又荒旱，赤地谁锄耰？官吏责富户，朘削如仇雠。\n\n财赋一以空，猗顿皆黔娄。两地总困厄，一死夫何尤。\n\n听此肠寸结，泪下不可收。寄语当路子，闭籴非良谋。\n\n嗷嗷累千万，生理真可忧。昔闻富郑公，劝民贮乾糇。\n\n所在发廪给，去往俱自由。公私虽两困，危急庶有瘳。\n\n万邦苦饥溺，安饱亦足羞。何时灾沴息，躬耕乐行休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哀淮人' AND p.poem_author = '严允肇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('斋居偶作', '白居易', '唐代', '童子装炉火，行添一炷香。老翁持麈尾，坐拂半张床。 \n 卷缦看天色，移斋近日阳。甘鲜新饼果，稳暖旧衣裳。 \n 止足安生理，悠闲乐性场。是非一以遣，动静百无妨。 \n 岂有物相累，兼无情可忘。不须忧老病，心是自医王。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '斋居偶作' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题画四首 其二 新水', '王寂', '金朝', '徐郎生别一酸辛，破镜还将泪粉匀。纵使三年不言笑，祇应学得息夫人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题画四首 其二 新水' AND p.poem_author = '王寂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和子瞻濠州七绝 浮山洞', '苏辙', '宋代', '洞府元依水面开，秋潮每到洞门回。幽人燕坐门前石，长看长淮船去来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和子瞻濠州七绝 浮山洞' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泉州北藏院见初荷华', '蔡襄', '宋代', '初华才过小荷身，晓露沾红点点匀。\n莫为愁心偏倚望，清江元有未归人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泉州北藏院见初荷华' AND p.poem_author = '蔡襄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白鹭鹚', '李白', '唐代', '白鹭下秋水，孤飞如坠霜。心闲且未去，独立沙洲傍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白鹭鹚' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秦楼月（咏睡香）', '赵彦端', '宋代', '香蔌蔌。小山丛桂烘温玉。烘温玉。酒愁花暗，沈腰如束。 \n 烦君剩与阳春曲。为君细拂衾罗馥。衾罗馥。一春幽梦，与君相续。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秦楼月（咏睡香）' AND p.poem_author = '赵彦端';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大人筑室将毕道祖亦作宅基治园作四诗示道祖 其三', '葛立方', '宋代', '两第屹相向，幽园卑辟彊。君方林上坞，吾亦沼横洋。\n\n凿翠辟窗户，入天栖栋梁。东屯寒月夜，老杜只茅堂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大人筑室将毕道祖亦作宅基治园作四诗示道祖 其三' AND p.poem_author = '葛立方';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('田侍郎 其七', '王建', '唐代', '笳声万里动燕山，草白天清塞马闲。触处不如别处乐，可怜秋月照江关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '田侍郎 其七' AND p.poem_author = '王建';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贫居自述 其八十四', '李孔修', '明代', '欲从何处避风波，倚竹依松结草窝。两字利名羁不得，一生贫窭奈无何。\n\n酒当欢处忘资少，诗到难吟逸兴多。烟水云山从我乐，渔歌唱罢唱樵歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贫居自述 其八十四' AND p.poem_author = '李孔修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂七十六首', '释师观', '宋代', '蓦然平地一声雷，惊得蟭螟眼豁开。\n是圣是凡俱不立，何妨随处舞三台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂七十六首' AND p.poem_author = '释师观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜坐因观杨伯虎和春字韵诗偶成五绝再寄 其二', '张镃', '宋代', '案上因翻简铁堆，亲朋何日和诗回。高怀剩得清閒力，满纸溪山秀色开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜坐因观杨伯虎和春字韵诗偶成五绝再寄 其二' AND p.poem_author = '张镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送士昂蒋主事', '陈琏', '明代', '九载稽勋政已成，缙绅祖饯出都城。钟山雨过云无迹，沧海潮来江有声。\n\n行见庙堂膺重寄，要期竹帛著芳名。久知献纳才华盛，伫听朝阳有凤鸣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送士昂蒋主事' AND p.poem_author = '陈琏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠王韬庵二首 其二', '杨寿杓', '近代', '昨夜高轩过，今朝李贺诗。论文知己少，怀刺谒君迟。\n\n词赋哀中岁，千戈累昔时。风尘一掬泪，挥洒莫相疑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠王韬庵二首 其二' AND p.poem_author = '杨寿杓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送傅越石都官归越州待阙', '梅尧臣', '宋代', '越客舟从真定至，夜夜镜湖生梦寐。\n晓度吴江百尺船，洗眼重看会稽翠。\n买臣负薪樵径荒，伯鸾赁舂苔臼弃。\n绿橘黄柑带叶收，白粳紫蟹侵霜馈。\n食蟹易美粳易饱，绿橘佐酒柑佐醉。\n莫论仕宦远与近，布袍练袍何所利。\n君恬不忍乞丐为，且返故庐聊以迟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送傅越石都官归越州待阙' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠范子', '皇甫汸', '明代', '在昔纪高士，遐哉举逸民。始知弓旌代，乃有岩壑人。\n\n范子秉兹尚，非病自云贫。结庐灵山曲，垂竿胥水滨。\n\n绪年习道论，游方狎隐沦。披裘忽过夏，采药已载春。\n\n雨漂庭下麦，风落甑中尘。为颂幽贞吉，庶宣皇化淳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠范子' AND p.poem_author = '皇甫汸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庚辰春沪上行赠温泽远师弟', '张海鸥', '当代', '温公廊庙具，气宇最轩昂。辽海青春好，申城岁月忙。\n\n小白长红女，飘作澳洲香。青浦年年柳，长亭岁岁霜。\n\n浩荡孤鸿志，江畔独彷徨。幸有数编书，夜夜慰衷肠。\n\n南园旦复旦，师友觞复觞。论道常写意，清歌总绕梁。\n\n苏州觅书苦，饥渴坐路旁。大言今古事，小店乞清汤。\n\n心富乾坤大，囊羞雅趣长。沧桑惜日月，我辈重文章。\n\n人间忽如梦，樽酒细细尝。且将千种意，聊寄小白杨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庚辰春沪上行赠温泽远师弟' AND p.poem_author = '张海鸥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋草四首 其四', '杨味云', '近代', '霜风吹到寸心枯，一碧如烟淡欲无。逋客北山羞薜荔，骚人南国怨蘼芜。\n\n荒陵冷落虾蟆鼓，旧院飘零蛱蝶图。昔日繁华都阅尽，青袍颜色也模糊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋草四首 其四' AND p.poem_author = '杨味云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陪徐渊子使君登白雪楼约各赋一诗必以宋玉石', '戴复古', '宋代', '楼名白雪因词胜，千古江山春雨馀。\n宋玉遗踪两苍石，莫愁居处一荒墟。\n风横烟艇客呼渡，水落沙洲人网鱼。\n借问风流贤太守，孟亭添得野夫无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陪徐渊子使君登白雪楼约各赋一诗必以宋玉石' AND p.poem_author = '戴复古';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乌夜啼', '王时翔', '清代', '斜月斜风庭院，轻寒轻暖时光。闲行踏遍空阶藓，暗忆杜秋娘。\n\n一霎吹兰低语，柳金梨雪花房。乳莺啼破东阑，梦尽勾换凄凉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乌夜啼' AND p.poem_author = '王时翔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与同馆戏续前韵 其七', '吴当', '元代', '尘眼争看楚俗傩，书灯独对汉时驼。歌声无复渔家傲，处处金章换绿蓑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与同馆戏续前韵 其七' AND p.poem_author = '吴当';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴子珍登仕避地大宁示诗赓韵以谢', '何文季', '宋代', '雁行声价压朋俦，凛凛词锋炯二矛。宝剑神光埋不住，夜冲星斗落旄头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴子珍登仕避地大宁示诗赓韵以谢' AND p.poem_author = '何文季';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送王孟箕明府之留都水部次日逢重九同曾时甫凤栖岩登高四首 其四', '林熙春', '明代', '圣世乘槎客，凭陵作赋才。人间九月节，天上一封来。\n\n舄履寒霜湿，登临曙色开。青山陪去棹，长啸且徘徊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送王孟箕明府之留都水部次日逢重九同曾时甫凤栖岩登高四首 其四' AND p.poem_author = '林熙春';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答清源林生', '卢龙云', '明代', '凤凰鸣昆丘，太液奋鸿鹄。鸒斯蒿下飞，羽翼何局促。\n\n人生各有志，小大随所欲。古来贤达流，振响遗空谷。\n\n昔余在弱龄，抗志薄时俗。旅游二十春，蹉跎守雌伏。\n\n南北万里遥，风尘徒仆仆。燕赵齐鲁墟，周行至海曲。\n\n政简讼还稀，幸不迷按牍。公暇寡所营，游神辄汗竹。\n\n探讨多会心，俯仰意恒触。微吟但自舒，何知炫群玉。\n\n羡子志不凡，千古慕芳躅。匪我平生亲，声气特相属。\n\n持论迥时流，摛文复纷郁。倾盖义已投，稽疑念弥笃。\n\n寡陋愧前闻，于尔何能淑。淡交惟若斯，相期善自勖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答清源林生' AND p.poem_author = '卢龙云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('住芨芨台，大风雪，呈乐彦亭将军', '杨炳坤', '清代', '大雪满弓衣，劳人塞上归。朔风号万窍，冷月晕重围。\n\n白首神偏旺，丹心愿讵违。龙泉犹在匣，破壁几时飞？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '住芨芨台，大风雪，呈乐彦亭将军' AND p.poem_author = '杨炳坤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀亦好园钓矶寄仲文季直二弟', '喻良能', '宋代', '磬湖雨过漾清波，古岸秋来长薜萝。\n问讯石君无恙否，试烦著手为摩挲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀亦好园钓矶寄仲文季直二弟' AND p.poem_author = '喻良能';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蕃女怨 其二', '毛奇龄', '清代', '胡腾起作石国语。愁杀番女。罽靴尖，铜带软。蹴踏宛转。\n\n回头忽忆旧安西。两眉低。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蕃女怨 其二' AND p.poem_author = '毛奇龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又次徐仲宗通判韵', '楼钥', '宋代', '老龙破蛰斩幽关，乱滴天飘不复悭。\n可但甘霖驱旱魃，自然凉气满人寰。\n民心徒切焦熬甚，神力毋劳指顾间。\n遥想清都应表贺，紫宸轩陛晓催班。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又次徐仲宗通判韵' AND p.poem_author = '楼钥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别岁', '释德洪', '宋代', '新岁压已至，旧岁去不迟。我尚留不住，石火那能追。\n\n不知岁所在，凫雏喧水涯。父老相邀迓，年年知此时。\n\n梅花只落尽，又见春水肥。我本无欣喜，何尝有戚悲。\n\n想见君饮酣，一举时一辞。春容尚能老，此身那不衰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别岁' AND p.poem_author = '释德洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东武怀古 其四', '周亮工', '明代', '嵯峨岩壑苦跻攀，大海南遵第几湾。客况驼头东莞郡，归心雁背穆陵关。\n\n琅玡赤映方升日，泰岱青分未了山。老鬓羞惭霜雪满，长淮路近不知还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东武怀古 其四' AND p.poem_author = '周亮工';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('樱花花下作 其四', '郑孝胥', '清代', '看到繁枝处处开，韶光骀荡锦成堆。春归沧海刚三月，骨醉东风又一回。\n\n花气连云收暮雨，涛声催昼送轻雷。道人摩眼空吟望，无复当年侧艳才。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '樱花花下作 其四' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大风连夜起七首 其七', '吴妍因', '清代', '大风连夜起，草阁欲鹏飞。盍展垂天翼，逍遥复北归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大风连夜起七首 其七' AND p.poem_author = '吴妍因';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('欲再过子进昆仲舟人绐以迷路既远不能复也怅然怀之', '赵蕃', '宋代', '数亩湖边宅，千篇海内诗。机心谢鸥鸟，乐事付埙篪。\n\n艇子思重过，流行竟莫知。吾侪俱老矣，怅望复来期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '欲再过子进昆仲舟人绐以迷路既远不能复也怅然怀之' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏蛱蝶', '释今沼', '明代', '春色日芳菲，逍遥邻院归。扑竹添新粉，飞花点素衣。\n\n随风过别浦，曝日向南枝。暗惜双飞处，芳华今未稀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏蛱蝶' AND p.poem_author = '释今沼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆故园 其八', '苏升', '明代', '玉河桥畔柳条析，翠色依稀欲染人。安得竹林行乐者，暂时相赏一相亲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆故园 其八' AND p.poem_author = '苏升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望湘人 二十八岁生日', '汪岳尊', '当代', '指碧阴庭角，又坠桐花，年芳匆匆如许。短墨闲磨，长萧懒和，怕触隔年悲绪。\n\n树静惊风，楼高泣月，问天无语。把幽忧、消向愁吟，青剩鬓丝几缕。\n\n休话良辰欣度。愧悬弧壮志，而今都负。念猿鸟心情，只合林泉容与。\n\n一樽浅醉，双扉低掩，坐对孟光荆布。倚修竹、自谱清词，忘却忍见溽暑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望湘人 二十八岁生日' AND p.poem_author = '汪岳尊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南都妙峰亭', '苏轼', '宋代', '千寻挂云阙，十顷含风湾。\n开门弄清泚，照见双铜钚。\n池台半禾黍，桃李余榛菅。\n无人肯回首，日暮车班班。\n史君非世人，心与古佛闲。\n时邀声利客，来洗尘埃颜。\n新亭在东阜，飞宇临通阛。\n古甃磨翠壁，霜林散烟鬟。\n孤云抱商丘，芳草连杏山。\n俯仰尽法界，逍遥寄人寰。\n亭亭妙高峰，了了蓬艾间。\n五老压彭蠡，三峰照潼关。\n均为拳石小，配此一掬悭。\n烦公为标指，免使勤跻攀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南都妙峰亭' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书感', '杨再十一', '宋代', '枫江渡口草凄凄，桃浦桥边夕照低。\n惟有旧家双燕子，年年飞绕绿杨隄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书感' AND p.poem_author = '杨再十一';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵和周大书事绝句', '晁说之', '宋代', '终日寒斋咏小招，故人轩槛俯溪桥。\n可怜不得宣城郡，白日消来恨未消。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵和周大书事绝句' AND p.poem_author = '晁说之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江南春·雨后江上绿', '陈与义', '宋代', '雨后江上绿，客悉随眼新。\n桃花十里影，摇荡一江春。\n朝风迎船波浪恶，暮风送船无处泊。\n江南虽好不如归，老蔼绕墙人得肥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江南春·雨后江上绿' AND p.poem_author = '陈与义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自金山泛舟至焦山饮吸江亭', '赵文昌', '宋代', '金山据上流，怒挟汀声东。焦山护海门，坐折千里冲。\n\n两山势欲合，盛气薄苍穹。解纷谁巨擘，赖有疏凿功。\n\n至今买馀勇，角立相长雄。两皋汗漫游，目击大块中。\n\n手持一杯酒，浇尔磊块胸。鱼龙出鼓舞，摩荡青莲宫。\n\n山灵自不凡，感激欣相从。因笑魏与吴，乾坤两鸡虫。\n\n悠然一带水，往事寻无踪。夜深何处笛，呜呜起西风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自金山泛舟至焦山饮吸江亭' AND p.poem_author = '赵文昌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苏幕遮 秋闺', '束蘅', '清代', '绿窗闲，人已静。玉兔初升，银烛光摇冷。倦倚画楼栏自凭。\n\n庭院深深，墙角花枝映。小池新水明如镜，霜打残荷，几点无多剩。\n\n瘦减腰肢力不胜。无奈伤秋，愁绝鸳鸯病。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苏幕遮 秋闺' AND p.poem_author = '束蘅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春夏之交风雨弥间耳目所触即事十绝', '汪莘', '宋代', '野水平桥细浪生，柴门草长断人行。\n园林霁后春如在，燕雀鸣时夏正清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春夏之交风雨弥间耳目所触即事十绝' AND p.poem_author = '汪莘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('相和歌辞。拔蒲歌', '张祜', '唐代', '拔蒲来，领郎镜湖边。郎心在何处，莫趁新莲去。 \n 拔得无心蒲，问郎看好无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '相和歌辞。拔蒲歌' AND p.poem_author = '张祜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题董邦达山水十二幅 其十一 云泉涧阁', '弘历', '清代', '溪头架阁倚层椒，水态山光入绮寮。只可相携漆园吏，此间促膝注逍遥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题董邦达山水十二幅 其十一 云泉涧阁' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('近榆亭 其六', '陈造', '宋代', '摭华复食实，果部谁称伯。兄桃柰其弟，无若此眉白。\n\n三玄信殊禀，五沃擅嘉殖。藏核待东归，分供橘奴帛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '近榆亭 其六' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自武宁舍舟度岭投宿南山寺', '李彭', '宋代', '水落晚滩涩，云生寒岭昏。舍舟步崎峰，郁萝陟松门。\n\n孤烟望墟落，浮林自一源。野杓方屡渡，槿篱时扣阍。\n\n弄孙何许翁，夷面复鸟言。问津了不解，路穷斜谷分。\n\n暝投古兰若，钟磬清尘根。犹疑武陵客，误宿桃花村。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自武宁舍舟度岭投宿南山寺' AND p.poem_author = '李彭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题灵岩各景·碧云洞', '元勋', '宋代', '踏流逆风寒，危径仅可伛。\n中空遂闳深，翠润欲垂雨。\n人间知何时，石乳观万古。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题灵岩各景·碧云洞' AND p.poem_author = '元勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春雷 其一', '姚佳', '当代', '嘉澍因风分外清，霆霓似剑匣中鸣。酒犹可醉荼蘼色，春不能眠鶗鴃声。\n\n事到眼前天注定，名于身后日生成。何妨步武闻连鼓，无碍摊书拥百城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春雷 其一' AND p.poem_author = '姚佳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白伯伦仪部移居夜阶助甫司封访之席上赋得卜居赤甲迁居新两见巫山楚水春十四韵 其四', '宗臣', '明代', '龙剑削芙蓉，十载闭其匣。壮士为尔开，满地走鳞甲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白伯伦仪部移居夜阶助甫司封访之席上赋得卜居赤甲迁居新两见巫山楚水春十四韵 其四' AND p.poem_author = '宗臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('松二首', '石延年', '宋代', '菌生枝上雨，龙起穴中雷。\n怪影漫溪侧，寒根缠石回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '松二首' AND p.poem_author = '石延年';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答董天隐推官', '李复', '宋代', '日月沄沄不可追，神奇腐臭略无遗。\n一丘一壑能谁过，相煦相濡莫我知。\n强聒睢盱何所补，雄夸凌厉亦奚为。\n秋来春去寻常事，安得乾坤独尔私。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答董天隐推官' AND p.poem_author = '李复';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('跋山谷书范滂传帖', '柴中守', '宋代', '小春昼日如春晚，饮罢披图清兴远。夜光照屋四座惊，金薤银钩真墨本。\n\n当年太史谪宜州，肠断梅花栖戍楼。拾遗不逢东道主，翰林长作夜郎囚。\n\n蛮烟瘴雨森鈇钺，更值韩卢搜兔窟。老色上面欢去心，惟有忠肝悬日月。\n\n郡丞嗜好殊世人，投笺乞字传儿孙。平生孟博是知己，笔下写出精神骞。\n\n兴亡万古同一辙，党论到头不堪说。刊章下郡汉道微，清流入河唐祚绝。\n\n先朝白昼狐亦鸣，正气消尽邪气生。殿门断碑仆未起，中原戎马来纵横。\n\n生蛟入手不敢玩，往事凄凉重三叹。兰亭瘗鹤徒尔为，好刻此书裨庙算。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '跋山谷书范滂传帖' AND p.poem_author = '柴中守';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岁暮还家杂诗 其二', '洪存恕', '近代', '腊尽远还乡，亲朋情话长。深杯嫌日短，缓步看人忙。\n\n纸马家迎灶，泥牛邻筑墙。乞儿歌竹版，细雨立昏黄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岁暮还家杂诗 其二' AND p.poem_author = '洪存恕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('官舍小池有鸂鶒遗二小雏二首 其二', '苏辙', '宋代', '清池定谁至，鸂鶒自来驯。知我无伤意，怜渠解托身。\n\n桥阴栖息稳，岛外往来频。勿食游鱼子，从交长细鳞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '官舍小池有鸂鶒遗二小雏二首 其二' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日闲作 其七', '卢青山', '当代', '荡荡天宇清，觉夜如静日。嫦娥骑玉车，缓鞭天牛力。\n\n烂齑天孙锦，飞光撒太极。河水深几何？其深不可测。\n\n潜鲸莫能波，虞渊未可及。我欲结纸舟，长为河中客。\n\n向旭与河沉，向暮戏河液。七夕久已过，中秋望在即。\n\n吴刚善桂醑，玉兔勤捣汁。将攀桂花树，一与嫦娥识。\n\n饮此香酣酒，食彼不老粒。长共天人居，永谢红尘国。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日闲作 其七' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春阴应秦王令（时在山西）', '徐贲', '明代', '云花鳞鳞山漠漠，重城平障芳阴薄。\n腻雨轻吹飞复停，勾引东风到帘幕。\n草滋微湿沾芳尘，陇头不见寻花人。\n桃英梅萼同懊恼，水纹满涨金河春。\n柳丝暝蒙烟不醒，辘轳暂辍银瓶绠。\n新莺未换谷中声，游蜂竟失阑前影。\n丁香百结蕉有心，绡屏六曲春沉沉。\n香抽翠缕火长续，余寒扑锦笼朱琴。\n江南春好多芳树，林园半是看花处。\n明朝重整小红车，风光满路行春去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春阴应秦王令（时在山西）' AND p.poem_author = '徐贲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天章精舍释奠礼成示诸生 其二', '全祖望', '清代', '瑰奇多学数琼台，底事三原忽见猜。力毁石翁尤可诧，瓣香姑舍莫相推。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天章精舍释奠礼成示诸生 其二' AND p.poem_author = '全祖望';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同家德清侍尚书杨宝学山行先过上岩访家谐季', '程公许', '宋代', '鹤书杳杳上岩云，锦里安车忽暮曛。二陆久当为世瑞，一夔留与护香芸。\n\n中春涧壑晴如暝，亭午松萝气自薰。倚槛欲歌招隐赋，客尘痼我不成文。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同家德清侍尚书杨宝学山行先过上岩访家谐季' AND p.poem_author = '程公许';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('章丘张虞部子发考绩便道归寿其父母为成古体应之', '王世贞', '明代', '我昔游阳丘，其土秀而丰。近有女郎山，远有丈人峰。\n\n蒸为芝与兰，扬芬于帝宫。凤皇从北来，口衔紫泥封。\n\n云霞光照耀，山峰对巃嵷。堂上双和鸣，音声何雍雍。\n\n制锦为彩衣，割禄充朝饔。俱称千金寿，行乐浩无终。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '章丘张虞部子发考绩便道归寿其父母为成古体应之' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('好事近 拟东泽', '周岸登', '清代', '愁眼送东风，泪点溅花红湿。指顾河山残照，幻暮云金碧。\n\n麴尘如幂卷高城，城下醉春色。折尽丝丝烟柳，听露桥吹篴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '好事近 拟东泽' AND p.poem_author = '周岸登';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史乐府十二章·观镫谏', '程盛修', '清代', '乾元楼，瞩神京，乐熙攘，庆太平。太平有象张镫宴，君乐须教民乐遍。\n\n焉得绮罗筵前千万镫，照见九州蔀屋鹄鸠形。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史乐府十二章·观镫谏' AND p.poem_author = '程盛修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙·四叠图字韵，和丽子令长子小剑在世时曾为予摄影', '汪岳尊', '当代', '谁幻先生笠屐图。南归早幸例髯苏。吉祥天遣护文殊。\n\n熙甫记亭翁悼子，谪仙爱月女名奴。古今人倘许相如。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙·四叠图字韵，和丽子令长子小剑在世时曾为予摄影' AND p.poem_author = '汪岳尊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十八滩 其五', '顾文渊', '清代', '烟中捩舵水倒冲，千篙争力怖杀侬，森森石齿排剑锋。\n\n人言险滩最天柱，水底白日蟠蛟龙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十八滩 其五' AND p.poem_author = '顾文渊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病中惊雨起作二首 其一', '卢青山', '当代', '枕头残卷拄床龟，病卧犹持竹节杯。梦似奇虹辉夜立，雨驱瀚海泼天飞。\n\n起看世界沉都没，随抚灵台有亦微。他处犹存他客否，茫茫如我坐摧颓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病中惊雨起作二首 其一' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('初冬快晴陪宣卿叔夏游石头庵过三生藏穷深极', '胡寅', '宋代', '茂樾初无一鸟鸣，晴曦参错昼阴清。\n枫林霜后未全赤，岩菊冬来主自荣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '初冬快晴陪宣卿叔夏游石头庵过三生藏穷深极' AND p.poem_author = '胡寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮 其十四', '陈步墀', '清代', '菱花簇照盘龙髻。朝来无限钿窗媚。一笑语仙郎。钗添金凤凰。\n\n为郎閒理发。背影浓香亵。不分鬓如银。双夸镜里春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮 其十四' AND p.poem_author = '陈步墀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('席间和向辟之元夜 其二', '韦骧', '宋代', '无愧涂人即可欢，□□□□□□□。月华莹澈通春夕，民气融和却暮寒。\n\n捃摭肴蔬成曲会，扶携老稚任环观。邑侬他日逢今日，往往应能话旧官。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '席间和向辟之元夜 其二' AND p.poem_author = '韦骧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元日有感', '洪皓', '宋代', '不见朝正秖自愁，展亲弗逮兖州囚。席重摇忆谈经会，酒噀宁知救火谋。\n\n内热空持白羽扇，峭寒且著黑羔裘。履端醽醁何时赐，落笔高歌洒泪休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元日有感' AND p.poem_author = '洪皓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉和添酒中六咏。酒杯', '皮日休', '唐代', '昔有嵇氏子，龙章而凤姿。手挥五弦罢，聊复一樽持。 \n 但取性淡泊，不知味醇醨.兹器不复见，家家唯玉卮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉和添酒中六咏。酒杯' AND p.poem_author = '皮日休';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('定风波', '欧阳修', '宋代', '把酒花前欲问伊。问伊还记那回时。黯淡梨花笼月影。人静。画堂东畔药阑西。 \n 及至如今都不认。难问。有情谁道不相思。何事碧窗春睡觉。偷照。粉痕匀却湿胭脂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '定风波' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('达奚司空像', '释今沼', '明代', '树老庭荒不记春，天朝裳服俨遗身。空悲乡国生翰鸟，似立朝门待舌人。\n\n灯火青荧通晦夜，廊龛寂历罥丝尘。从今断却当年恨，海舶无因过此津。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '达奚司空像' AND p.poem_author = '释今沼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('劝酒', '白居易', '唐代', '劝君一盏君莫辞，劝君两盏君莫疑，劝君三盏君始知。\n\n面上今日老昨日，心中醉时胜醒时。天地迢遥自长久，白兔赤乌相趁走。\n\n身后堆金拄北斗，不如生前一樽酒。君不见春明门外天欲明，喧喧歌哭半死生。\n\n游人驻马出不得，白舆素车争路行。归去来，头已白，典钱将用买酒吃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '劝酒' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('莲池潭', '张湄', '清代', '莲瓣芹丝一气香，天然泮水绕宫墙。林端不许飞鸮集，山势高骞拱凤皇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '莲池潭' AND p.poem_author = '张湄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登五层楼', '张家珍', '明代', '缥缈层楼连碧汉，白云积翠入空微。东回古寺钟初动，南绕长江水一围。\n\n返照半含沧海日，远帆斜没钓鱼矶。登临一笑成今古，怪底王生便赋归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登五层楼' AND p.poem_author = '张家珍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日皇甫司勋见过余出小鬟以筝琶侑觞司勋为赋三绝句率尔奉答 其二', '何良俊', '明代', '歌珠历落本清圆，更遣流泉乱拂弦。好取使君留一顾，故将误曲唱当筵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日皇甫司勋见过余出小鬟以筝琶侑觞司勋为赋三绝句率尔奉答 其二' AND p.poem_author = '何良俊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感寓 其六', '朱诚泳', '明代', '吾闻帝王世，人文日以宣。间尝读其书，抚卷思茫然。\n\n三王莫之尚，五帝不可前。征伐与禅让，仁义岂偏全。\n\n光明烛幽远，心法垂简编。群生乐熙皞，九州无倒悬。\n\n帝王日以远，明哲徒拳拳。恭惟我皇祖，绳武三千年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感寓 其六' AND p.poem_author = '朱诚泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('叶审言张子长同游北山智者寺既归复与子长至赤松由小桃源登炼子山谒二皇君祠回宿宝积观赋绝句十首 其六', '黄溍', '元代', '双鹤冲天岁月多，至今香火压嵯峨。刘郎不是无兄弟，奈此丹鸡白犬何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '叶审言张子长同游北山智者寺既归复与子长至赤松由小桃源登炼子山谒二皇君祠回宿宝积观赋绝句十首 其六' AND p.poem_author = '黄溍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山村夜坐', '梁颀', '清代', '俯仰空庭四宇清，浮云扫尽晚烟轻。梨花皓月原同色，风竹流泉不辨声。\n\n深谷人閒春亦寂，短墙水近冷先生。却思城市喧阗处，箫鼓楼头听二更。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山村夜坐' AND p.poem_author = '梁颀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('邓尉山中', '华士芳', '清代', '不是探梅日，空山气更清。上方寻古寺，下界听钟声。\n\n野鸟自呼侣，闲花不问名。诸天稍昏黑，回看暮云平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '邓尉山中' AND p.poem_author = '华士芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('瞿塘两崖', '杜甫', '唐代', '三峡传何处，双崖壮此门。入天犹石色，穿水忽云根。 \n 猱玃须髯古，蛟龙窟宅尊。羲和冬驭近，愁畏日车翻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瞿塘两崖' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送谢从义知杭州分题岳王坟', '陈汝言', '明代', '荒坟秋树影萧萧，只有孤僧伴寂寥。\n二帝游魂归不得，百年枯骨恨难消。\n山空永夜愁寒雨，江阔悲风起暮潮。\n若到钱塘逢故老，伤心切莫问前朝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送谢从义知杭州分题岳王坟' AND p.poem_author = '陈汝言';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉檄赴古北口军次祀軷有期书示同志 其四', '蒋曰豫', '清代', '绝塞风云接大荒，谁敲铜斗韵伊凉。鸡声夜醒千门月，虎迹秋盘万岭霜。\n\n客惯渐忘尘梦换，官卑也要国恩偿。镫前独抱龙渊啸，影烂芙蓉忍善藏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉檄赴古北口军次祀軷有期书示同志 其四' AND p.poem_author = '蒋曰豫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送何令归江右', '陶安', '明代', '故山猿鹤正相招，非是渊明懒折腰。想见章江门外柳，待君归系木兰桡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送何令归江右' AND p.poem_author = '陶安';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉和陈教授庆煌博士龟山朝日二绝句元玉 其二', '林恭祖', '当代', '万古蓬莱镇海东，朝暾浴罢碧波红。群贤此日兰阳会，吟到龟山句更工。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉和陈教授庆煌博士龟山朝日二绝句元玉 其二' AND p.poem_author = '林恭祖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杜鹃花', '屈大均', '明代', '子鹃魂所变，朵朵似燕支。血点留双瓣，啼痕渍万枝。\n\n开当寒食后，人正断肠时。望帝春心在，花含万古悲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杜鹃花' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮·君家玉雪花如屋', '辛弃疾', '宋代', '君家玉雪花如屋。未应山下成三宿。啼鸟几曾催。西风犹未来。山房连石径。云卧衣裳冷。倩得李延年。清歌送上天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮·君家玉雪花如屋' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四圣赞', '释师体', '宋代', '稽首普贤，不可思议。\n出头露面，开言吐气。\n拍盲担板，忘恩断义。\n事无寸长，熏天炙地。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四圣赞' AND p.poem_author = '释师体';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐　题金纤纤砚拓小像', '寇梦碧', '近代', '春星小谪，瘦影和愁拓。帘外素馨花欲落，今日东风犹恶。\n\n清吟曾伴兰闺，研螺写上红梅。惆怅水天梦断，通词拟托㛙妃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐　题金纤纤砚拓小像' AND p.poem_author = '寇梦碧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('明皇贵妃上马图', '张璨', '明代', '七宝妆鞍蜀锦堆，黄门扶控踏红埃。\n君王只顾蛾眉笑，末路谁知到马嵬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '明皇贵妃上马图' AND p.poem_author = '张璨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贺新郎·天远星飘渺', '顾随', '现代', '天远星飘渺。\n漏声残、月轮高挂，尘寰静悄。\n南北东西都何处，着我情怀懊恼。\n况岁暮、天寒路杳。\n欲织回文长万丈，问愁丝恨缕长多少。\n空自苦，赚人笑。\n半生真似墙头草。\n侭随风、纷披摇荡，东斜西倒。\n万岁千秋徒虚语，眼看此身将老。\n且点检、残篇断稿。\n说到文章还气馁，算个中事业词人小。\n清泪滴，到清晓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贺新郎·天远星飘渺' AND p.poem_author = '顾随';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绝命诗 其一', '黄玹', '清代', '乱离滚到白头年，几合捐生却未然。今日真成无可奈，辉辉风烛照苍天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绝命诗 其一' AND p.poem_author = '黄玹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游仙都观五首 其二', '吴芾', '宋代', '策杖行行入翠微，步虚山下久忘归。幽栖宜有中林士，何事斯人近世稀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游仙都观五首 其二' AND p.poem_author = '吴芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈六十九首 其三十五', '释道宁', '宋代', '焚香提起经来读，便是拈华付嘱心。此外别求玄妙解，悠悠千古少知音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈六十九首 其三十五' AND p.poem_author = '释道宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感鹤', '何吾驺', '明代', '一往穿云入汉游，长风吹断送沧洲。谁传华表千年恨，鳷鹊无情不共愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感鹤' AND p.poem_author = '何吾驺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜坐即事', '胡仲参', '宋代', '午夜空庭寂，心闲坐亦忘。\n竹间风动静，云里月行藏。\n惊鹊出幽树，寒螀语废廊。\n瓯茶聊当酒，清气入诗肠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜坐即事' AND p.poem_author = '胡仲参';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜月怀明卿二首 其一', '宗臣', '明代', '逐客音书久不闻，天风吹断楚江云。相思惟有长安月，拾得婵娟难寄君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜月怀明卿二首 其一' AND p.poem_author = '宗臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏日怀陈洛南尚书', '庞尚鹏', '明代', '艳阳池馆夏生寒，偏喜清时共挂冠。夜雨高吟频遣寄，稻田新熟愿加餐。\n\n交游转觉蓬山远，魂梦犹惊蜀道难。最是故园风景好，满天明月似长安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏日怀陈洛南尚书' AND p.poem_author = '庞尚鹏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('到四安', '陈著', '宋代', '雨中行数日，今日得新晴。\n山到浙閒秀，船从海上行。\n市腥逢海错，人语带京声。\n此去总佳景，坡仙曾细评。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '到四安' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和李端叔大夫从参寥子游许昌 其八', '李廌', '宋代', '梦为蝴蝶恣飞飞，飞入花丛处处迷。不是提壶强呼起，尚应栩栩展江西。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和李端叔大夫从参寥子游许昌 其八' AND p.poem_author = '李廌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春末夏初闲游江郭二首', '白居易', '唐代', '闲出乘轻屐，徐行蹋软沙。观鱼傍湓浦，看竹入杨家。 \n 林迸穿篱笋，藤飘落水花。雨埋钓舟小，风飏酒旗斜。 \n 嫩剥青菱角，浓煎白茗芽。淹留不知夕，城树欲栖鸦。 \n 柳影繁初合，莺声涩渐稀。早梅迎夏结，残絮送春飞。 \n 西日韶光尽，南风暑气微。展张新小簟，熨帖旧生衣。 \n 绿蚁杯香嫩，红丝脍缕肥。故园无此味，何必苦思归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春末夏初闲游江郭二首' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('淳化中朝会二十三首 其二 群臣初举酒毕作《化成天下》。', '郊庙朝会歌辞', '宋代', '圣德比陶唐，千年祚运昌。茂功虽不宰，鸿业自无疆。\n\n极塞成清谧，齐民益阜康。文明同日月，遐迩仰辉光。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '淳化中朝会二十三首 其二 群臣初举酒毕作《化成天下》。' AND p.poem_author = '郊庙朝会歌辞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('至和杂书五首·八月一日', '蔡襄', '宋代', '淮天过尽入吴渠，兰亭晚日光疏疏。\n金桃傅粉好颜色，绿醽泛滟深车渠。\n觥巡屡卷明星出，花翘零落随衣裾。\n幺弦不动凝古意，春容浅破长眉舒。\n庭院帘帷一齐下，红蜡阴沈霜满瓦。\n鸡头软热七月终，举手分传玉盈把。\n席前碧瓮覆瑶浆，一秋愁泪风前洒。\n云中宝晕万重高，付与轻绡藏冰麝。\n孤城寒柝夜迢遥，谁道刘郎有天马。\n归来却问东海桑，海浪漫漫彩虹挂。\n红丝萦脍晓刀鸣，双龙笑断梦中惊。\n莫将团扇掩尘匣，曾障清歌十数声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '至和杂书五首·八月一日' AND p.poem_author = '蔡襄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('云溪山人歌', '卢青山', '当代', '天下至穷云溪谷，中有至穷天下屋。云溪山人非世居，随风飘至相狎熟。\n\n熟即为家家本寄，山人安辨其华朴。相倚觳觫书橱四，二案一椅供卧伏。\n\n白壁森森如白眼，五年睨我背弓矗。杂纸堂皇相推挽，屋如旷野纸蒿簇。\n\n有时寻人人不见，开茅剔草蚿而缩。亦有似屋冬来时，风为主人人客宿。\n\n隐几神游不可惊，为客为家两难卜。绕屋之山趋奔驰，脉浪如海之雕塑。\n\n千秋固是此中人，穷隅秃岭味如肉。披岚冲霭飞寒霖，耸肩屈颈如峰麓。\n\n当春绚烂仍踽踽，万花丛中一粪曝。山不嫌余粲其颜，峨冠者来其美蹙。\n\n留余驱人何为也，山其与余为心腹。云溪山人之所有，有此山屋两穷物；\n\n山屋之穷何所状，唯有一月相照覆。流泽于林林无声，修眉如画画窗幅。\n\n洞牖趺坐四围趋，万人来拥生公肃。行则髫童逐我影，立则粲者偎颔淑。\n\n山人至此安求哉，中宵独乐常哧卟。山屋月成三皮匠，相聚岂非诸葛属？\n\n胸如丘壑月如心，屋贮二者并山人，岂非天下至富足？\n\n谁使可人扣门来，相与口舌卧游读？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '云溪山人歌' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和董伯玉不向东山久韵', '吴芾', '宋代', '我暂出山去，常忧蕙帐空。\n闻君东山乐，爱君古人风。\n日暮君不来，碧云蔽高穹。\n凌晨戒僮仆，驾言将租东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和董伯玉不向东山久韵' AND p.poem_author = '吴芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十六日开船值北风大作复泊北门', '陈基', '元代', '风急江难渡，天寒雪更飘。济川虽有楫，跨海恨无桥。\n\n使节辞吴近，官军去楚遥。北门仍系缆，山雨夜萧萧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十六日开船值北风大作复泊北门' AND p.poem_author = '陈基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题玉泉溪', '湘驿女子', '唐代', '红叶醉秋色，碧溪弹夜弦。\n佳期不可再，风雨杳如年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题玉泉溪' AND p.poem_author = '湘驿女子';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东坝以里沿岸人家皆对门植苇于小屿不晓其旨漫成四绝 其三', '岳珂', '宋代', '北都旧产无淇竹，见说园池芦苇多。涨绿不妨夜来雨，更须别浦听鸣荷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东坝以里沿岸人家皆对门植苇于小屿不晓其旨漫成四绝 其三' AND p.poem_author = '岳珂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈六十九首 其五十一', '释道宁', '宋代', '有利无利，不离行市。师子嚬呻，象王游戏。洎乎检点将来，未是衲僧巴鼻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈六十九首 其五十一' AND p.poem_author = '释道宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杨花曲', '孔凡章', '近代', '荔枝湾上波声急，瑽琤似鼓湘灵瑟。月涌澄潭镜影清，星临平野珠光出。\n\n闻道江山数百年，不拘一格降婵娟。书窗隐约杨花影，吟稿商量柳叶笺。\n\n南冥有女凌波立，万卉凝香扑裙叶。小字呼来却唤鱼，新妆理就能羞蝶。\n\n羊城巾帼擅雄风，水国生涯巧笑中。玉树修名双美具，珠江灵气一身钟。\n\n豆蔻芳华刚十六，生逢蜗角争蛮触。剑舞难消意气豪，弦歌不觉光阴倏。\n\n神京新起妙高台，羽檄星驰选俊才。未解功名将脱颖，剧怜成败尚猜枚。\n\n澄澜划破明珠溅，彩云一线驰如箭。大地风雷决死心，中天日月开生面。\n\n华清池水漾芳温，鲛女销残帝子魂。风里落花春有梦，雨中飞燕水无痕。\n\n嫣红上颊匀轻晕，闲人浪惹失颜愠。妩媚犹存虢国风，温柔莫向杨家问。\n\n银杯镂字赠双成，十里天衢揽辔行。江左枣梨镌姓字，岭南桑梓羡恩荣。\n\n神州隔海春雷震，又报邻邦开远运。黄种图强肯后人，红颜崛起争先奋！\n\n岛国风情漫惹愁，此行宁为事芳游？请缨小试沧浪水，抽剑思裁日夜流。\n\n驰道频催金勒马，英雄未许淆真假。战火燃眉黯日星，狂澜攘臂惊夷夏。\n\n飞塔鸣钟日未曛，旗开万国鼎三分。雪骢蹴笛凝香雾，风鸽牵罗化锦云。\n\n碧波无复清澄底，鱼龙溷迹风涛里。破阵兰陵仗女兵，先驱柳浪同儿戏。\n\n红妆禹甸迥无伦，番女蛮娃尽后尘。九州讴咏归名下，一代丹青照海滨。\n\n百战归来名字重，万人空巷春城动。红缨耀日剑光寒，翠帜摇风花气拥。\n\n凤鼓龙箫殷若雷，游人都是看花来。日边弄影输红杏，雪里清标识素梅。\n\n急流勇退谈何易，忽听笙歌喧北地。铁骑遥颁露布来，玉人更把云裳理。\n\n江城南翼拱京师，十万明灯夜不知。全胜萧墙方北定，窥边胡马又东驰。\n\n莫道女郎殊吉士，读书喜断兴亡事。霄汉常存木铎心，云泥不懈长缨志。\n\n涉世才知万事非，难凭肉食仗安危。东林有石天方醉，北阙无书梦已灰！\n\n歌声夜彻浔阳岸，江头蹀躞空肠断。此役惟遗画虎讥，官场那敢燃犀看。\n\n先是：重瀛奏凯初，芳声遍播海东隅。已借鲤鱼通贡水，更随鸿雁上匡庐。\n\n后来邺下流言起，流言竟中云英姊。浇俗相传未必真，采风纪事翻成史。\n\n庐山高处接云烟，开府洪都尚少年。百诺传呼新富贵，万方多难此留连。\n\n偶际春人来逆旅，羽衣如雪飘飘举。紫塞烟尘警寇氛，兰桥谣诼谐仙侣。\n\n侠骨柔肠未解羞，从来家国重恩仇。八驺只擅谋身计，百炼何劳绕指柔。\n\n还君一束梅花结，九州铸错真成铁！小妹犹虚玉镜盟，使君自有金钗列。\n\n春池吹皱漫相干，蜚语飞来涤污难。防川自写陈情表，拜月谁诬乞巧盘？\n\n骓欲逝兮时正利，涛笺暗托飞鸿寄。春花秋月岂君凡，白石青松知妾意。\n\n含嗔江上泛轻航，一夜鸣筝沸建章。眉黛不描时式样，口碑偏满少年扬。\n\n寂寞昭陵陵下路，一朝车骑喧如堵。宝瑟新调静女诗，瑶池正看天魔舞。\n\n蝶拥莺围意不禁止，几人修竹进曹箴。执鞭孰遣樊迟御，行路犹知司马心。\n\n播音直使诸公愧，蛾眉解滴新亭泪。髫龄爱诵木兰诗，长大心萦荀灌骑。\n\n肯俯幽兰就草莱，可怜鹓鹭枉追陪！朱门棨戟心无睹，钿盒隋珠意不回。\n\n结束铅华归去好，东风让与闲花草。翠袖轻辞白下门，香旌遥指春申道。\n\n春申仕女本多情，雷走香车夹路迎。舞榭花酣银管酽，歌筵珠啭玉杯莹。\n\n画舫连桡东去久，高桥堤上千人走。横海英风逐鹿姿，伏波妙技降龙手。\n\n皓腕纷飞星眼融，青丝斜挽浪花浓。情深绿水身难主，力尽清波泪欲融。\n\n春江水冷罗衣薄，故园待践归来约。惊鸿掠影入潇湘，小凤留芳重京洛。\n\n春申江上水悠悠，泛起人间万斛愁！青鬟岭外音书杳，黄耳夭涯道路遒。\n\n风华自昔终尘土，花开花谢无人主！何似新词付五弦，倘留佳话传千古。\n\n枉抛心力军名姝，二十华年此故吾。才愧江东名士鲫，诗成南国美人鱼。\n\n村讴呕哑难为读，韩潮苏海惭枵腹。唱彻诗坛下里声，可怜腾笑杨花曲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杨花曲' AND p.poem_author = '孔凡章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('漳河疑冢', '京镗', '宋代', '疑冢多留七十馀，谋身自谓永无虞。不知三马同槽梦，曾为儿童远虑无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '漳河疑冢' AND p.poem_author = '京镗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('祷雨宿九曲池上三首', '晁补之', '宋代', '同辇笙歌地，荒池风露天。\n无心更怀古，凉夜正甘眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '祷雨宿九曲池上三首' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('希之小扇', '韩淲', '宋代', '野水寒烟洗岸沙，萧萧风苇净霜华。无人独立飞来鹭，冷落心情一倍加。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '希之小扇' AND p.poem_author = '韩淲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题陈举善山水图小景四首为蒋志明赋 其四', '刘崧', '明代', '山暝啼猿外，江平落雁中。几时将小艇，来问钓鱼翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题陈举善山水图小景四首为蒋志明赋 其四' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵回叔经', '陈藻', '宋代', '从来剽窃为场屋，直是无繇识古书。\n屈指罕能官显达，到头剩得腹空虚。\n君今身计非谋禄，地有人耕免荷锄。\n高适学诗看更晚，才名何患不相如。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵回叔经' AND p.poem_author = '陈藻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苕上', '徐永宣', '清代', '青山澹澹水茫茫，半面蒹葭半面桑。都有绿阴维钓艇，断云微漏夕阳黄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苕上' AND p.poem_author = '徐永宣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病中寄武公望二首 其一', '廖行之', '宋代', '四十馀年尚转蓬，渠论南北与西东。但知爱子三迁教，不办谋生一亩宫。\n\n北海可怜真意广，步兵良苦漫途穷。人生择术须循分，鹏鴳逍遥自不同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病中寄武公望二首 其一' AND p.poem_author = '廖行之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('代乐府三首 其三 双桐生空井', '萧纲', '南北朝', '季月双桐井，新枝杂旧株。晚叶藏栖凤，朝花拂曙乌。\n\n还看西子照，银床系辘轳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '代乐府三首 其三 双桐生空井' AND p.poem_author = '萧纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('悲老宫人', '刘得仁', '唐代', '白发宫娃不解悲，满头犹自插花枝。 \n 曾缘玉貌君王宠，准拟人看似旧时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '悲老宫人' AND p.poem_author = '刘得仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重午王文辅送米食张云卿送新酒来因成绝句', '邹浩', '宋代', '水团粽子恰登门，白酒持来更满樽。节物人情总堪醉，况归田里已承恩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重午王文辅送米食张云卿送新酒来因成绝句' AND p.poem_author = '邹浩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塞下曲 其二', '顾炎武', '清代', '一从都尉生降去，夜夜魂随塞雁芦。陛下宽仁多不杀，可能生入玉门无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塞下曲 其二' AND p.poem_author = '顾炎武';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('钱舜举捕鱼图', '董纪', '明代', '脱蓑挂船尾，鼓枻坐船头。得鱼既换酒，欸乃扬中流。\n\n妻儿冒短篷，喜无风雨忧。日暮向何处，白鹭古时洲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '钱舜举捕鱼图' AND p.poem_author = '董纪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题富贵祥宜侯砖砚', '姜军', '当代', '砚出江东透古芒，墨池窥牖等天苍。从今视古人鹏异，重向西湖觅晏方。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题富贵祥宜侯砖砚' AND p.poem_author = '姜军';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆秦娥（初冬）', '赵长卿', '宋代', '寒萧索。征鸿过尽离怀恶。离怀恶。江空天迥，夜寒枫落。 \n 有人应误刀头约。情深翻恨郎情薄。郎情薄。梦回长是，半床闲却。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆秦娥（初冬）' AND p.poem_author = '赵长卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二十三日使风', '赵蕃', '宋代', '江行已属北风权，此去宁忧上水船。\n卧听招呼帆转脚，起看飞溅水平舷。\n鸥乘逸气沿仍溯，雁怯惊吹断复连。\n玄妙未穷天籁说，雄豪诗读快哉篇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二十三日使风' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题画 其一 垂钓图', '缪公恩', '清代', '门对空江水接天，翠屏倒影浸云烟。一竿风月无人管，閒数沙鸥倚钓船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题画 其一 垂钓图' AND p.poem_author = '缪公恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登万寿阁望华山', '王熊伯', '清代', '巍峨西岳镇西京，杰阁朝凭爽气清。五里雾披三辅晓，半空云卷万峰晴。\n\n芙蓉彩翠窗前落，海日光华掌上生。见说玉姜犹不死，御风何处正吹笙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登万寿阁望华山' AND p.poem_author = '王熊伯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和荆公何处难忘酒诗', '郑侠', '宋代', '何处难缄口，熙宁政失中。\n四方三面战，十室九家空。\n见佞眸如水，闻忠耳似聋。\n君门深万里，安得此言通。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和荆公何处难忘酒诗' AND p.poem_author = '郑侠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送周德涵', '陈恭尹', '明代', '便作天涯别，重逢未可期。快闻经世论，兼读过庭诗。\n\n骐骥宜千里，鹪鹩且一枝。野人头已白，不复问当时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送周德涵' AND p.poem_author = '陈恭尹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('更漏子', '孙云鹤', '清代', '绿阴浓，红雨乱。无奈春归人远。梁燕去，塞鸿来。闲阶生暗苔。\n\n长亭路。分襟处。惆怅画屏烟树。流水远，夕阳沉。倚栏千里心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '更漏子' AND p.poem_author = '孙云鹤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐 二阕 其一', '姚燮', '清代', '更无佳鸟。但有鸣蛩扰。莫怨秋风催鬓早。心已春风催老。\n\n楼前淡月疏星。楼中淡月疏檠。要睡不能多睡，隔墙送过鸡声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐 二阕 其一' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答季仲宜', '王十朋', '宋代', '我昔从君伯氏游，短素长笺日唱酬。凌云健笔驱山丘，欲追李杜参曹刘。\n\n子今又复振风流，可人一气真吾俦。明珠白璧蒙暗投，自揣无堪但增羞。\n\n君家棠棣才俱优，吾知徐公百不忧。更能勉力追前修，俯舍青紫何须求。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答季仲宜' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和知府右丞秋贡燕士席上所赋', '吕陶', '宋代', '应书群彦称旁求，劝驾贤公礼数优。名出士林当赫赫，诗歌鹿野自呦呦。\n\n云霄去路程皆远，杞梓良材干尽脩。登却龙门须变化，夺标人已在船头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和知府右丞秋贡燕士席上所赋' AND p.poem_author = '吕陶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('慈恩寺九日应制', '薛稷', '唐代', '宝宫星宿劫，香塔鬼神功。王游盛尘外，睿览出区中。 \n 日宇开初景，天词掩大风。微臣谢时菊，薄采入芳丛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '慈恩寺九日应制' AND p.poem_author = '薛稷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登北固山游甘露寺', '金武祥', '清代', '危峰独立迥淩虚，万里苍茫眼界舒。第一江山推北固，千秋形势壮南徐。\n\n孤亭直欲超云表，铁塔犹存历劫馀。说到沧桑增感慨，寺门凭眺意何如。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登北固山游甘露寺' AND p.poem_author = '金武祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答潘文叔见寄予十月尝访文叔许来而犹未也', '孙应时', '宋代', '别离一何久，迢递阻音形。\n重上君子堂，相见眼终青。\n君颜尚冰玉，我鬓已星星。\n借问十载间，风波两蓬萍。\n岭剑各万埯，心目多所经。\n归来且强健，怳然真梦醒。\n可怜万修竹，清音玉珑玲。\n萧条媚寒日，约略环翠屏。\n相携复一笑，芝兰有余馨。\n孤云自舒卷，野鹤来青冥。\n平生阅群彦，十八九凋零。\n吾徒亦何愿，毕景依林坰。\n种秫令可酿，储粟常满瓶。\n琴书奉娱玩，足以陶性灵。\n千载伐木篇，此意神所听。\n往来亦奚惮，江浦堪扬舲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答潘文叔见寄予十月尝访文叔许来而犹未也' AND p.poem_author = '孙应时';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郊行见有陆上舟居者口占二绝 其一', '许家惺', '近代', '浮家半世苦迁流，从此风波永不愁。一样闾阎尘扑地，任他西北有高楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郊行见有陆上舟居者口占二绝 其一' AND p.poem_author = '许家惺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵彭青老咏雪三绝句 其二', '王庭圭', '宋代', '天公剪水散花林，试比江梅色浅深。梁苑词人能赋咏，终篇不作苦寒吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵彭青老咏雪三绝句 其二' AND p.poem_author = '王庭圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诗偈 其一八○', '庞蕴', '唐代', '惭愧好意根，无自亦无他。无自身无垢，无他尘不加。\n\n常居清静地，知有不能过。旧时恶知识，总见阿弥陀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诗偈 其一八○' AND p.poem_author = '庞蕴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚晴独酌二首', '杨万里', '宋代', '冷落杯盘下箸稀，今年淮白较来迟。\n异乡黄雀真无价，稍暖琼酥不得时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚晴独酌二首' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('听鹤亭和韵 其一', '霍与瑕', '明代', '小山曾见省南东，寓远翛翛倚碧空。岂谓微垣施巧匠，亦移蓬岛入新丰。\n\n双凫晓浥花间露，独鹤时鸣竹外风。最是仙郎无一事，洗心高坐玉壶中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '听鹤亭和韵 其一' AND p.poem_author = '霍与瑕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其三', '释祖可', '宋代', '怀人更作梦千里，归思欲迷云一滩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其三' AND p.poem_author = '释祖可';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金山岭', '范成大', '宋代', '阪峻身频偃，崖深首屡回。\n云浮平地出，路拂半天来。\n但阅关山过，都忘岁月催。\n湘南初上马，犹插早春梅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金山岭' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄家菽园孝廉', '丘逢甲', '清代', '韩苏笔力不到处，石破天惊自著书。未悔居夷从凤鸟，真看横海掣鲸鱼。\n\n河山烟点齐州外，文字雷屯草昧初。闻说鸡林争购集，百蛮齐拜孝廉车。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄家菽园孝廉' AND p.poem_author = '丘逢甲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送曹倅岩山官满归里', '文天祥', '宋代', '春陵光霁落苍苔，葛水神仙立翠槐。\n万里云霞麒骥路，三年风月凤凰台。\n兴同老子复不浅，歌曰先生归去来。\n庾岭梅花开渐遍，一枝就与寄蓬莱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送曹倅岩山官满归里' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('歌者十二首 其九', '司空图', '唐代', '白云深处寄生涯，岁暮生情赖此花。蜂蝶绕来忙绕袖，似知教折送邻家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '歌者十二首 其九' AND p.poem_author = '司空图';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谒夏忠靖周文襄新祠', '沈周', '明代', '水利克脩财赋举，二公戮力惠吴民。祀行今日欣成典，爱寓斯邦合妥神。\n\n肖貌堂堂快星凤，功名在在认麒麟。山川悠久贵同德，蕉荔殷勤系后人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谒夏忠靖周文襄新祠' AND p.poem_author = '沈周';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感事', '祁敕', '明代', '五亩溪园锁绿阴，红尘何事恰相侵。人生安得尽如意，世事但求无愧心。\n\n却喜他山真有石，休言同舍误持金。重裘著罢春寒退，静掩书斋抱膝吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感事' AND p.poem_author = '祁敕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('潇湘八景诗 其一 潇湘夜雨', '张经', '宋代', '终夜雨潇潇，闷杀孤舟客。滴滴打蓬声，错讶灵妃瑟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '潇湘八景诗 其一 潇湘夜雨' AND p.poem_author = '张经';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和粹伯七夕韵 其一', '曾协', '宋代', '常时泪雨久涟洳，准拟晴窗叫勃姑。报答月华思善画，便和风露入新图。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和粹伯七夕韵 其一' AND p.poem_author = '曾协';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀靳师道', '欧大任', '明代', '铁瓮城边路，怀人径寸心。夕鸿前浦远，春雨大江深。\n\n笔札留东观，风云在上林。游閒知爱客，飞盖日相寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀靳师道' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙 夏夜偶成用宋词韵', '杨芸', '清代', '袅袅轻风吹竹树，依稀天际闻笙。未秋先已送秋声。\n\n愁人偏易感，无语怨深更。\n\n捲起疏帘看夜色，一钩残月空庭。银河淡淡断云横。\n\n蕉衫烟漾碧，凉影闪流萤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙 夏夜偶成用宋词韵' AND p.poem_author = '杨芸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('嘉定己巳立秋得膈上疾近寒露乃小愈十二首 其八', '陆游', '宋代', '小诗闲淡如秋水，病后殊胜未病时。自剪矮笺誊断稿，不嫌墨浅字倾攲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '嘉定己巳立秋得膈上疾近寒露乃小愈十二首 其八' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('即事', '楼钥', '宋代', '十日阴寒雪不成，腊残春近更霜晴。\n深山高卧如春暖，绕鬓飞蚊自在鸣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '即事' AND p.poem_author = '楼钥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('扇子诗 其七十九', '李石', '宋代', '爱他国色艳倾城，老衲心城百万兵。便使有情何足动，幻花况是本无情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '扇子诗 其七十九' AND p.poem_author = '李石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归自南华诗', '朱翌', '宋代', '众绿扬新楚，初晴中薄寒。\n行山无阔步，陟巘有遐观。\n蕨紫拳犹小，松黄粉渐乾。\n无嫌一马瘦，径度两重滩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归自南华诗' AND p.poem_author = '朱翌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送刘善长归北安省亲', '洪皓', '宋代', '九龄颖悟已惊人，乃父分茅善抚民。\n郑忽身为周室质，贾生议屈汉庭臣。\n行攀郄桂荣三斧，暂著莱衣省二亲。\n勿讶班荆歌陟屺，小人有母在江宾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送刘善长归北安省亲' AND p.poem_author = '洪皓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('见赵章泉', '姚镛', '宋代', '秉芳独向章泉老，四海儿童以字传。特诏难更高士服，好诗多入贾人船。\n\n行窝冷落熙宁后，放鹤风流景祐前。一代典刑能几见，愿从几杖阅耆年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '见赵章泉' AND p.poem_author = '姚镛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王岱麓李三洲携酒过访诗以谢之三首 其二', '王渐逵', '明代', '古人重倾盖，那惜相知新。去者日以隔，来者日以亲。\n\n何意白首交，乃作行路人。远迹爱丛莽，养痾越台滨。\n\n曲肱阅尘鞅，于今得见君。庭荫列嘉树，日夕谛玄文。\n\n粗疏多谬误，所愿在率真。四海皆兄弟，何必比与邻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王岱麓李三洲携酒过访诗以谢之三首 其二' AND p.poem_author = '王渐逵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('午日江上', '区怀年', '明代', '笙歌十里酿闲愁，水郭凉风五月秋。双桨玉壶供野酌，六衢香粉翳中流。\n\n搴芳日丽芙蓉浦，听技云生翡翠舟。幽况早同渔父适，钓竿无恙狎沙鸥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '午日江上' AND p.poem_author = '区怀年';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过隐者庄', '田登', '明代', '幽轩停白昼，心古万缘轻。春壑花争放，澄潭浪不生。\n\n云山当近户，风雨望高城。归去渊明社，欣欣木正荣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过隐者庄' AND p.poem_author = '田登';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望江南', '顾贞观', '清代', '江南好，秋水晚平桥。千顷绿沉菱叶雨，十分香散藕花潮。\n\n人倚木兰桡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望江南' AND p.poem_author = '顾贞观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('真止堂', '吴芾', '宋代', '我有虚堂号真止，坐来万虑清如水。\n君今更以止名堂，想见了无尘念起。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '真止堂' AND p.poem_author = '吴芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('至普安察院合溪道长复留一诗见候次韵', '张羽（凤举）', '明代', '归路依微取次寻，前山日日厌登临。寒经索岭霜林静，瘴入盘江昼雾深。\n\n古驿荒凉惊岁晚，野云容易结秋阴。驱车纵猎输谁子，蔓草斜坡羡获禽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '至普安察院合溪道长复留一诗见候次韵' AND p.poem_author = '张羽（凤举）';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赵縠阳太史东归赠寄', '霍与瑕', '明代', '春风春日送仙槎，珠海芳尊共物华。帝里九重同恋阙，师门八十讲通家。\n\n玩馀樵岭清秋月，冲碎罗浮古洞霞。此去不妨呤弄在，蓬莱仍有万年花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赵縠阳太史东归赠寄' AND p.poem_author = '霍与瑕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次陈平甫提干晚春韵', '释元肇', '宋代', '莫云岂特看江东，朋旧如今四海中。花落不禁三日雨，颜衰消得几春风。\n\n檐前雏竹娟娟粉，阶下樱桃滴滴红。辛苦广骚将底用，弋人何处慕冥鸿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次陈平甫提干晚春韵' AND p.poem_author = '释元肇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与薛十二过寿宁精舍得歌字', '李延兴', '元代', '鸣雨过青嶂，飞烟绕碧萝。庭空留鹤迹，江静听渔歌。\n\n长夏迎人少，高年礼佛多。飘飘飞锡处，千里又相过。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与薛十二过寿宁精舍得歌字' AND p.poem_author = '李延兴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和友人游仙杂诗 其一', '戴亨', '清代', '年来踪迹但支离，世味人情老渐知。材与不材堪自处，道非常道觅吾师。\n\n鸾音鸿爪同消息，老屋荒江阅岁时。笑看蚍蜉尘垢里，熙熙攘攘欲奚为。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和友人游仙杂诗 其一' AND p.poem_author = '戴亨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荆州公馈酒 其一', '宋登春', '明代', '菱叶青青水荇齐，绕篱黄蝶菜苗肥。夕阳谁送山人醉，坐看儿童跨犊归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荆州公馈酒 其一' AND p.poem_author = '宋登春';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('滴滴金', '晁端礼', '宋代', '庞儿周正心儿得。眼儿单、鼻儿直。口儿香、发儿黑。脚儿一折。 \n 从来薄命多阻隔。未曾有恁相识。除非烧香做功德。且图消得。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '滴滴金' AND p.poem_author = '晁端礼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('禅坐四首 其四', '郭之奇', '明代', '净极明通处，慈云妙覆时。浮生如幻化，真地果琉璃。\n\n弹指销荣悴，冥心出险夷。何年依锡止，笑尔鹤飞迟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '禅坐四首 其四' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居午睡起弄花三首 其二', '杨万里', '宋代', '数片荷花漾水盆，忽然相聚忽然分。从教压捺沉盆底，依旧浮来无水痕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居午睡起弄花三首 其二' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('斋宿和韵 其一', '庄昶', '明代', '老隔垂帘病亦侵，梦回西阁漏沈沈。报酬主上平生分，对越青天此寸心。\n\n布絮不温粗被冷，朝衣端坐烛花深。相应郊祀寒仍在，昨夜圜丘雪尚阴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '斋宿和韵 其一' AND p.poem_author = '庄昶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('孤吟', '程滨', '当代', '吾诗谁读取，昔有失之堂。评品斯人倦，行吟独自狂。\n\n愁云笼缜密，哀玉叩清扬。更觅销魂句，愔愔入锦囊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '孤吟' AND p.poem_author = '程滨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚过邻曲', '陆游', '宋代', '阳狂跌宕送年华，信步来寻野老家。\n浅濑水清逢立鹭，横林叶尽数栖鸦。\n书生一饱依耕耒，壮士孤愁入戍笳。\n王绩但思酣美酝，葛洪不复问丹砂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚过邻曲' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄题水月 其二', '苏舜钦', '宋代', '积翠湖心迤逦长，洞台萧寺两交光。鸟行黑点波涛白，枫叶红连橘柚黄。\n\n人我绝时隈树石，是非来处接帆樯。如何遂得追游性，摆却营营不急忙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄题水月 其二' AND p.poem_author = '苏舜钦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送杭州使君苏内相先生某用先生旧诗方丈仙人出渺茫高情犹爱水云乡为韵作古诗十四首 其七', '李廌', '宋代', '周公非汲汲，仲尼岂皇皇。吾道无若人，孰能相维纲。\n\n古今异伦轨，英风自相望。下民今喁喁，造物太茫茫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送杭州使君苏内相先生某用先生旧诗方丈仙人出渺茫高情犹爱水云乡为韵作古诗十四首 其七' AND p.poem_author = '李廌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽范丞相忠宣公六首 其六', '毕仲游', '宋代', '挥泪西原上，晴云为我阴。谁知如望岁，竟不复为霖。\n\n主圣空撝己，民思未绝吟。已休还一恸，非但哭知音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽范丞相忠宣公六首 其六' AND p.poem_author = '毕仲游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('追和王常侍登郡楼望山', '邵雍', '宋代', '四贤当日此盘恒，千百年人尚寻颜。\n天下有名难避世，胸中无物漫居山。\n事观今古兴亡后，道在君臣进退间。\n若蕴奇才必奇用，不然须负一生闲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '追和王常侍登郡楼望山' AND p.poem_author = '邵雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题徐训导廷献魁山旧隐', '王绂', '明代', '人品如瞻斗，山名合应魁。地灵知孕秀，天赋肯淹才。\n\n笔阵惊同列，文光烛上台。高攀蟾窟桂，勇跃禹门雷。\n\n已作鹍鹏化，空令猿鹤猜。经横芹泮静，琴弄杏花开。\n\n宦志云霄待，乡心岁月催。黄残松径菊，绿遍石田苔。\n\n若便寻归驾，移文恐劝回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题徐训导廷献魁山旧隐' AND p.poem_author = '王绂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水头', '孔平仲', '宋代', '荒湾斗转河如束，千古痴龙卧空谷。公然收水入毫芒，万里昆崙倾不足。\n\n春妍睡醒鳞甲开，顷刻已放波头来。冲梢掠操何迅速，喷云溅雪争崔嵬。\n\n舟人传呼隘两岸，骇若百蛰逢惊雷。连桩系缆犹恐脱，不尔船碇俱倾颓。\n\n须臾水面如平掌，客子棹歌船下上。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水头' AND p.poem_author = '孔平仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观鹤舞', '永珹', '清代', '幽人惯调鹤，散步临前墀。兴来观其舞，开笼无常期。\n\n胎仙若解意，小立修容仪。徐焉顿修趾，双翮俄参差。\n\n暂离芳春地，不上乔松枝。徘徊弄逸态，宛转矜殊姿。\n\n惊鸿方振迅，翔凤偏威垂。烟雾隐芝圃，风雨生瑶池。\n\n讵嫌心目眩，祇觉精神移。轩翥亦已久，敛翼还自持。\n\n横空骋天步，华表忘归时。顾念驯养恩，云外凭招之。\n\n低徊同戏彩，不愧林家儿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观鹤舞' AND p.poem_author = '永珹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泊苍梧', '何绛', '明代', '重过苍梧客，扁舟一夜心。山川犹昨日，难对在高深。\n\n芳草绿新恨，春风吹旧林。岂无同旅泊，谁识此宵吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泊苍梧' AND p.poem_author = '何绛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与生公游石窟山', '张九龄', '唐代', '探秘孰云远，忘怀复尔同。日寻高深意，宛是神仙中。 \n 跻险构灵室，诡制非人功。潜洞黝无底，殊庭忽似梦。 \n 岂如武安凿，自若茅山通。造物良有寄，嬉游乃惬衷。 \n 犹希咽玉液，从此升云空。咄咄共携手，泠然且驭风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与生公游石窟山' AND p.poem_author = '张九龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('皇帝阁春帖子', '许应龙', '宋代', '东风昨夜扫氛埃，四表咸欣寿域开。\n都护已飞三捷奏，凌烟同上万年杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '皇帝阁春帖子' AND p.poem_author = '许应龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百六十首', '释宗杲', '宋代', '夜来兔子赶大虫，天明走入无何有。\n月下珊瑚长数枝，万象森罗齐稽首。\n拄杖子，不唧{左口右留}，\n渠侬却善分妍丑。李公烂醉绝倒时，\n元是张公吃村酒。报诸人，\n急回首，切忌疾狂外边走。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百六十首' AND p.poem_author = '释宗杲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('残冬展假病榻消寒聊当呻吟语无伦次录存十六章 其三', '查慎行', '清代', '茫茫大地托根孤，只道烟霄是坦途。短袖曾陪如意舞，长眉难画入时图。\n\n移镫见蝎宁防毒，误笔成蝇肯被污。窃喜退飞犹有路，的应决计莫踌蹰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '残冬展假病榻消寒聊当呻吟语无伦次录存十六章 其三' AND p.poem_author = '查慎行';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('食鲙', '刘挚', '宋代', '知几张季鹰，归怀托江鲙。鲈鱼今不数，未若鲂鲫最。\n\n橙齑捣椒兰，芦菔碎珠贝。盈盘玉叶铺，千缕红云碎。\n\n佐以晚菘羹，玉饭香蔼蔼。饱行惭素餐，扪腹放衣带。\n\n昨来溪夏乾，市空无可奈。徒有弹铗吟，何能饱幼艾。\n\n安得东海鲸，不惮生物害。挥刀满金盘，对列酒池外。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '食鲙' AND p.poem_author = '刘挚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵李子建怀归', '李若水', '宋代', '寸心已老自宜休，误别云山岁几周。\n疏远骤依双凤阙，清贫仅剩一貂裘。\n与人不偶缘方凿，於世无求类直钩。\n何日张帆旋故国，坐呼明月醉江头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵李子建怀归' AND p.poem_author = '李若水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和泽民二首', '吴芾', '宋代', '欲绍家声每自鞭，肯同流俗饮贪泉。\n已将止足安心地，更把吟哦乐性天。\n笑日桃花将献媚，先春梅蕊欲争妍。\n人生会合真难遇，幸有杯觞且共传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和泽民二首' AND p.poem_author = '吴芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢惠笋', '刘黻', '宋代', '饥肠数日吼，往往茄苋争。\n幽人盼寂寥，饷我慈竹萌。\n斑斑未离绷，白下莫与京。\n寒泉煮青茆，手调玉版羹。\n招僧招不来，贳洒乃独烹。\n茄苋避三舍，纸帐午梦宁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢惠笋' AND p.poem_author = '刘黻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('道傍丛祠榜云老人庙', '张镃', '宋代', '里俗崇祠想报功，袍鞾包裹雪髯翁。\n休嗟事始无人识，纵有丰碑亦是空。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '道傍丛祠榜云老人庙' AND p.poem_author = '张镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('先生自费城寄书有吾其左衽矣之叹占此奉告', '傅子馀', '近代', '老向天涯作幸民，一书投我感常新。国危但保东迁地，礼失同为左衽人。\n\n倘许衡山重拄杖，何如香海共垂纶。莺飞草长当三月，梦断江南草木春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '先生自费城寄书有吾其左衽矣之叹占此奉告' AND p.poem_author = '傅子馀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题苏武牧羝图', '戴亨', '清代', '苏卿奇节古所无，丹青为写当年图。手持汉节节旄落，驱羝就牧阴山枯。\n\n朔风如刀砭肌骨，瀰漫浩雪埋穹庐。蚩尤愁惨作妖雾，老狐叫啸群邪趋，孤臣万里将何如。\n\n鸾凤罹笯龙受缚，久𢬵肝脑涂沙漠。阴阳为炭天为炉，险阻巅危笃攻错。\n\n陶铸伟器撑乾坤，讵比凡材任销铄。终教皓首复归来，千秋万祀声隆赫。\n\n君不见李陵歌送褰行裾，仰天泣血空欷歔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题苏武牧羝图' AND p.poem_author = '戴亨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题也休庵 其二', '释怀深', '宋代', '唱歌楼上语风流，你既无心我也休。打著郎君心里事，从前恩爱冷啾啾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题也休庵 其二' AND p.poem_author = '释怀深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东归歌送郑子经', '陈旅', '元代', '北风吹山蕉叶黄，长亭野日寒荒荒。驱车送子归故乡，人生此处堪断肠。\n\n旧游回首秋山下，醉帽簪花同走马。欢娱如此离别何，华月芳年不堪把。\n\n子今去矣来何时？翠壶云深那可知。向来亦有燕山期，子今去矣来何时！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东归歌送郑子经' AND p.poem_author = '陈旅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('香山', '沙曾达', '近代', '报道山花次第开，美人曾许采香来。吴王韵事留幽径，喜拥蛾眉醉绿醅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '香山' AND p.poem_author = '沙曾达';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十一月朔与钱国辅江门观涨', '陆深', '明代', '水槛漂垂钓，江门不掩风。望穷东海若，身拟烂银宫。\n\n浴日中流急，浮天一苇通。鱼龙吾得免，消息任虚空。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十一月朔与钱国辅江门观涨' AND p.poem_author = '陆深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜z6公自武陵至', '齐己', '唐代', '已尽沧浪兴，还思相楚行。鬓全无旧黑，诗别有新清。 \n 暂憩临寒水，时来扣静荆。囊中有灵药，终不献公卿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜z6公自武陵至' AND p.poem_author = '齐己';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赞三宝', '释印肃', '宋代', '直指人心亲见佛，何劳打瓦作龟爻。\n一片白云横谷口，几多归鸟尽迷巢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赞三宝' AND p.poem_author = '释印肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('芙蓉', '释居简', '宋代', '溪痕寒不肥，岸容晚益退。其谁怜婆娑，明霞剪零碎。\n\n烂烂饱泠露，酣酣俯清濑。宛然古铜碧，嫣然靘妆对。\n\n又若翠袖薄，瘦立烟渚外。西风仅如许，晚节尚可待。\n\n遂拜拒霜号，不受断肠浼。亦岂无老成，试请推行辈。\n\n桂腾小山馥，菊耀东篱采。裳衬芰荷衣，服称陆离佩。\n\n芳芷雅相乡，宿莽安敢背。花城隔仙凡，俗说信茫昧。\n\n独有离骚经，名氏得先载。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '芙蓉' AND p.poem_author = '释居简';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早秋二绝', '寇准', '宋代', '一听早蝉响，坐悲芳岁阑。\n新秋空索寞，前事但心酸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早秋二绝' AND p.poem_author = '寇准';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬日', '费墨娟', '清代', '寒风扑面冷难支，百感营心岁暮时。欲破愁城无别计，围炉煮雪漫敲诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬日' AND p.poem_author = '费墨娟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六丑 和天琴', '沈曾植', '清代', '倚银屏数梦，袅万种春愁如发。三峰夜游，青天通箭筈。\n\n嘉平仙腊。谁织扶桑瓮，投壶玉女，亸烟鬟月押。东南孔雀楼西北。\n\n云外惊鸿，阑前斗鸭，长亭柳稊都茁。恨春风婀娜，不到天末。\n\n青霓谁达，闷琼宫瑶闼。珠箔飘灯夜，双泪蜡。当时照见灵札。\n\n恁素书沈鲤，玉床眠獭。海霞热，小桃丹靥。总误了春人十载，望春眉睫。\n\n红心草绿灰飞蝶。向玉京，魂抱离忧诉，碧翁醉煞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六丑 和天琴' AND p.poem_author = '沈曾植';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙', '陈伟强', '当代', '一缕春痕浓又淡，水窗渐渐黄昏。缟衣重著对兰熏。\n\n月华都化雾，海气欲成尘。\n\n梦入桐花深树里，有人浅笑轻颦。落英万点付朝云。\n\n玉颜终忘了，难忘旧星辰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙' AND p.poem_author = '陈伟强';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜期友生不至', '姚合', '唐代', '忍寒停酒待君来，酒作凌澌火作灰。 \n 半夜出门重立望，月明先自下高台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜期友生不至' AND p.poem_author = '姚合';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('树头鸦舅鸣', '谢应芳', '元代', '树头鸦舅鸣，农人起耘苗。问之何尔忙，良田莠骄骄。\n\n去年耘较迟，草蔓全力寡。稂莠非不除，卒以害吾稼。\n\n吾闻农人语，猛省天下事。养虎当害人，玩寇亦如此。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '树头鸦舅鸣' AND p.poem_author = '谢应芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄婺州周知录', '林季仲', '宋代', '不到东阳六七年，干戈身世两依然。\n每思三虑堂中退，径向双溪楼上眠。\n空翠霏微浮酒斝，林烟杳霭没渔船。\n有人问我今何似，头秃昏昏瘴海边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄婺州周知录' AND p.poem_author = '林季仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠沈稚咸', '徐熥', '明代', '爱君蓬荜绿萝閒，住近枫桥第几湾。短屐一春游茂苑，疏钟半夜听寒山。\n\n门多词客寻诗至，寺有高僧乞画还。数顷烟波满船月，歌声来往水云间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠沈稚咸' AND p.poem_author = '徐熥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怨辞（二首）', '景翩翩', '明代', '妾作溪中水，水流不离石。\n君心杨柳花，随风无定迹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怨辞（二首）' AND p.poem_author = '景翩翩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜梦一道人见访相与语甚久颇及宗乘中事因戏之曰仙家亦学佛耶其人笑曰仙佛岂有二哉觉而异之作诗纪其事', '刘才邵', '宋代', '北风吹云肃天宇，蕙帐寒生月当户。颓然就枕睡思浓，魂梦悠悠迷处所。\n\n仙宫胜士肯见临，促席从容陪软语。自言本事清虚君，学佛求仙两无阻。\n\n云軿白日降遥空，天衣飘飘袖轻举。方诸宫深云海阔，金碧禅房隔烟雨。\n\n与君粗有香火缘，聊复东来相劳苦。方游昆阆还无期，君住世间须善为。\n\n尘劳足厌不须厌，等是实相夫何疑。前身自是尘外人，端为世缘縻此身。\n\n重闻妙语发深省，若更离尘佛亦尘。方平羽节何时来，道宫佛庙随烟埃。\n\n未须苦说扬尘事，东海波声正似雷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜梦一道人见访相与语甚久颇及宗乘中事因戏之曰仙家亦学佛耶其人笑曰仙佛岂有二哉觉而异之作诗纪其事' AND p.poem_author = '刘才邵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书座自警四首 其二', '王渐逵', '明代', '勿尔苗稚，其舒则扬。勿谓暗室，其居则明。淑慎尔正，谑浪匪臧。\n\n先民有言，贾用是臧。毋弃其庸，维德不爽。维德不爽，神式其享。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书座自警四首 其二' AND p.poem_author = '王渐逵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清泉兄将赴营口高就葆国兄为其饯行予与士海先生作陪限押京字', '吴金水', '当代', '别后烟波接北冥，年年六月海潮生。扶摇九万知他日，潋滟千杯尽此情。\n\n天外长云春浩荡，胸中爽气势纵横。丈夫四海为家惯，何必流连向帝京。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清泉兄将赴营口高就葆国兄为其饯行予与士海先生作陪限押京字' AND p.poem_author = '吴金水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酌别张子元二首', '李昴英', '宋代', '去冬初去国，逆旅等顺境。\n祸机众危之，沙蜮伺人影。\n拂衣肯同归，荒驿灯夜永。\n幸脱妖蟆口，黑月重磨镜。\n勤君再行役，我愧心耿耿。\n陛下皇明穹，贤聚纤邪屏。\n石渠盛此士，岂复松厅冷。\n胸中贮奇策，可以靖边警。\n平生羞辕驹，看取囊露颖。\n堂堂曲江翁，芳躅在梅岭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酌别张子元二首' AND p.poem_author = '李昴英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送儿沆再之婺', '陈著', '宋代', '父母生汝期望汝，地阔天宽从著步。\n霜叶飞红橙橘黄，一笠西风正宜路。\n送汝出门不肯行，低头进前出苦语。\n双亲虽安身已高，菽水为欢盍朝暮。\n夏初奉命见两山，往还恨不身生羽。\n如今又为千里行，直是恋慕难轻去。\n有不忍听手抚背，至哉天理人伦处。\n我岂欲汝寸步难，事有乘机恐差误。\n晚年正欲汝有成，此行倘与心相副。\n皱皮瘦骨便精神，当为汝喜非汝惧。\n不妨安稳趁前程，但及梅花时归学莱舞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送儿沆再之婺' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题百官步', '李光', '宋代', '晓雨微茫水接天，隔江茅店有炊烟。杖藜独上沙头路，犹记当时赶渡船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题百官步' AND p.poem_author = '李光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又和松碧轩三绝 其三', '胡寅', '宋代', '新陂剩水沃良苗，想见当时相杵谣。尚有荒馀须快犊，何须塌具更悬腰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又和松碧轩三绝 其三' AND p.poem_author = '胡寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赋得太湖春水送华以及岁贡', '谢晋', '明代', '浩浩来天日，溶溶接汉津。光随征棹远，绿染客袍新。\n\n瑞气初销腊，恩波总是春。明朝禹门外，一跃有谁论。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赋得太湖春水送华以及岁贡' AND p.poem_author = '谢晋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉楼春 夜坐', '丁宁', '近代', '青灯如死繁音息，意海恬流时起灭。微茫炉火曙天星，寥落门庭秋树叶。\n\n昏鸦不识中宵月，绕遍空枝还喋喋。几回忍泪嗅残梅，绰约孤芳寒似雪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉楼春 夜坐' AND p.poem_author = '丁宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高邮别子相', '王世贞', '明代', '回轸出君方，脩途意弥恻。浮云莽互驰，奄然羲轮匿。\n\n中夜理夙炊，惋恋不能食。往遘岂乏欢，念若遗行迹。\n\n姣服谐奇慕，安能顾掩抑。举世各自矜，娟情无终极。\n\n脉脉睹何言，察此眉间色。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高邮别子相' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('百字令', '顾随', '近代', '屋山起伏，正沈沈无际，黯淡如铅。向晚阴云低压处，横空几道苍烟。\n\n冻解长河，冰流春水。减得几分寒。绕廊徐步，隔窗闻弄哀弦。\n\n见说山水清音，楼台胜境，自古让神仙。争奈自家尘福浅，谁教偏住人间。\n\n四载明湖，三年东海，二月杏花天。眼前何物，雪花飞上阑干。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '百字令' AND p.poem_author = '顾随';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('伯量同二弟欲见访湖庄以诗告至褒拂过情辄次其韵 其三', '曹彦约', '宋代', '年来夺锦马群空，而况君家有八龙。传与乡人经济策，问焉何惜少舂容。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '伯量同二弟欲见访湖庄以诗告至褒拂过情辄次其韵 其三' AND p.poem_author = '曹彦约';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题桃叶渡江图', '王丹林', '清代', '细雨横塘记昔过，画图开处奈愁何？桃花一簇红无主，春水三篙绿始波。\n\n解佩清狂馀仿佛，溅裙宿约竟蹉跎。由来兰桨无情物，锦瑟华年送已多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题桃叶渡江图' AND p.poem_author = '王丹林';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('甘州•舍弟仲由于役幽燕，道经上海，信宿而别', '陈匪石', '清代', '正潇潇、暮雨作新秋，西风动江城。对当窗明烛，匡床碎语，浊醑深擎。\n\n别绪丝丝未理，津鼓促征程。帘外飞鸿过，寒阵初惊。\n\n姜被当年重认，渺故园一角，梦委荒荆。问天涯投老，踪迹几回并。\n\n望长安、浮云千态，幻海波、愁蔽晚山青。伤高泪，劝须臾忍，休洒新亭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '甘州•舍弟仲由于役幽燕，道经上海，信宿而别' AND p.poem_author = '陈匪石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('仙人隐迹 其二', '吴洞明', '宋代', '长生玄牝门，目击而道存。班班实可考，老涧生云根。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '仙人隐迹 其二' AND p.poem_author = '吴洞明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('□李文昭不遇', '张弼', '明代', '桃径参差曲到门，半湾流水欲成村。主人何处空诗案，花扑晴帘护暖云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '□李文昭不遇' AND p.poem_author = '张弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀旧三首 其三', '杨赓笙', '近代', '记得蒲青艾绿时，故交先识顺昌旗。果然入境称张禄，未及成功作范蠡。\n\n筠岭饱看千个竹，梅关空塞一丸泥。要知军阀倾颓处，全局先输此著棋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀旧三首 其三' AND p.poem_author = '杨赓笙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大堤曲', '李裕', '明代', '大堤堤上多杨柳，大堤人家都市酒。纷纷女儿秾艳妆，唱拨琵琶露纤手。\n\n舟子收帆夜泊堤，少年估客心恋迷。折花酣酒醉不醒，黄金掷尽不能归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大堤曲' AND p.poem_author = '李裕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水龙吟 其三 落叶', '王沂孙', '宋代', '晓霜初著青林，望中故国凄凉早。萧萧渐积，纷纷犹坠，门荒径悄。\n\n渭水风生，洞庭波起，几番秋杪。想重涯半没，千峰尽出，山中路、无人到。\n\n前度题红杳杳。溯宫沟、暗流空绕。啼螀未歇，飞鸿欲过，此时怀抱。\n\n乱影翻窗，碎声敲砌，愁人多少。望吾庐甚处，只应今夜，满庭谁扫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水龙吟 其三 落叶' AND p.poem_author = '王沂孙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵何符山人二首', '陈造', '宋代', '门下轩裳不转头，何人皮底著阳秋。\n独烦客子冲泥屐，屡到衰翁听雨楼。\n从昔诗声追正始，即今宾友验宣州。\n清篇快读强人意，未觉京尘厌薄游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵何符山人二首' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('济尔哈朗图行宫作 其二', '弘历', '清代', '纳稼田馀柄穗多，富秋历阅喜无过。一溪流水村前绕，四面晴山户外罗。\n\n便犒诸藩歌湛露，兼宣翰苑咏卷阿。苏门审势差相似，不约而同安乐窝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '济尔哈朗图行宫作 其二' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('毗陵郡斋追忆卿味', '杨万里', '宋代', '坐无黄雀牛尾狸，荆溪日日思江西。\n若无鹅梨与海错，江西却恐思荆溪。\n旧居江西不自惜，到得荆溪却追忆。\n明年官满归江西，却忆荆溪难再得。\n江珍海错各自奇，冬裘何曾羡夏絺。\n鹅梨黄雀无不可，荆溪江西不关我。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '毗陵郡斋追忆卿味' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('省躬诗 其十六', '曹于汴', '明代', '孟子善养气，此气即此理。禀气人人知，理则远言取。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '省躬诗 其十六' AND p.poem_author = '曹于汴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿谖为辰州李贡士民望作', '符锡', '明代', '萱草树北堂，谓能忘远忧。如何念慈母，不置天西头。\n\n楚山高高楚水长，西风晨夕雁南翔。帛书不事慰脩阻，忘忧愿祝寿且康。\n\n他日拜官来故里，门户光生母心喜。九溪会变作春酒，白发青袍放歌起，何如更向天涯咨陟𡵆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿谖为辰州李贡士民望作' AND p.poem_author = '符锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂兴四首', '于石', '宋代', '屋上青山屋下云，清泉为镜石为屏。\n客来问我谋生计，一卷家传相鹤经。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂兴四首' AND p.poem_author = '于石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赵总戎见惠巨鳊酬之以诗', '韩雍', '明代', '缩项鳊鱼味最珍，长江六月尤难得。波涛汹涌风力劲，渔人举网空费力。\n\n元戎统师百万行，秋毫无犯严戒饬。庖厨空虚河伯知，故遣嘉鱼助鲜食。\n\n我曹忝陪旌旆行，此味从来不曾识。元戎驰赐捧玉盘，烹来大嚼深感激。\n\n吁嗟此物成百头，真乃神灵来效职。威声从此收南邦，蜂屯蚁聚休言贼。\n\n草草题诗谢来意，纸短情长苦相逼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赵总戎见惠巨鳊酬之以诗' AND p.poem_author = '韩雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和景仁七十一偶成', '司马光', '宋代', '心地长闲为己物，年华不驻是天时。\n当时海上乘槎客，维楫都无行所之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和景仁七十一偶成' AND p.poem_author = '司马光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游上野博览会二首 其二', '蔡寅', '近代', '可怜风月太平年，只许今生海外缘。不忍池边春潋滟，通天桥上客翩跹。\n\n三千弱水曾经眼，十二琼楼笑拍肩。的的明灯真不夜，万花丛里赛婵娟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游上野博览会二首 其二' AND p.poem_author = '蔡寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬至宿杨梅馆', '白居易', '唐代', '十一月中长至夜，三千里外远行人。\n若为独宿杨梅馆，冷枕单床一病身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬至宿杨梅馆' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('快亭', '释德洪', '宋代', '太丘作邑付弦歌，剩得清闲可奈何。满地棠阴惊昼永，小亭诗眼觉天多。\n\n佳眠夏簟便光滑，醉耳松风喜再过。想见句成书棐几，侍儿浓笑出微涡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '快亭' AND p.poem_author = '释德洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次友人张孟善承赠以诗韵', '丁鹤年', '元代', '去去成长往，悠悠事远游。蹑云双短屐，载月一虚舟。\n\n江海鱼龙夜，山林鹤鹤秋。诵君佳丽句，慰我别离忧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次友人张孟善承赠以诗韵' AND p.poem_author = '丁鹤年';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋夜', '王邦畿', '明代', '未得平情学，年来积感深。静中知肺病，夜半喜秋霖。\n\n竹响摇清梦，兰香披素襟。明朝拉朋好，高蹑北山岑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋夜' AND p.poem_author = '王邦畿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('明堂侍祠十绝 其五', '杨简', '宋代', '玉佩珊珊出禁扉，金莲分炬散芳菲。祠班咫尺临黄道，惹得天香满袖归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '明堂侍祠十绝 其五' AND p.poem_author = '杨简';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阮郎归', '刘子寰', '宋代', '长条袅袅串红绡。无风时自摇。十分娇艳更苗条。殢春情态娇。 \n 风影舞，露痕潮。买来和蝶饶。故园愁绝楚宫腰。相逢恨怎销。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阮郎归' AND p.poem_author = '刘子寰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄家书', '王庭诏', '清代', '一函游子泪痕封，寄去云山几万重。君到鹤洲江上望，数椽茅屋几株松。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄家书' AND p.poem_author = '王庭诏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送僧怀善', '刘摰', '宋代', '独鹤翩无累，孤云晚倦飞。群山带江处，一锡背尘归。\n\n妙学穷神秘，高怀熟世机。漳滨多病客，空此望岩扉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送僧怀善' AND p.poem_author = '刘摰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同心结三章送林德敷赴齐东 其一', '郑善夫', '明代', '文旗出郭门，念子赴齐东。揽衣起踯躅，叹息不得同。\n\n凤麟久增逝，爰居亦避风。冥运方险艰，去去随短蓬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同心结三章送林德敷赴齐东 其一' AND p.poem_author = '郑善夫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠小儿医', '洪咨夔', '宋代', '忍饥觅句孟东野，守叔草玄杨子云。\n囊有遗收无与读，两家恨不早逢君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠小儿医' AND p.poem_author = '洪咨夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('为郭元德题和靖探梅图', '俞德邻', '宋代', '祥符真人调玉烛，四海八荒春意足。孤山山小不容春，十月梅花破寒玉。\n\n风流诗老癖爱梅，拂晓骑驴度山曲。呼童忍冻折南枝，香满吟窗伴幽独。\n\n到今写入画图中，骨冷神清炯双目。荡荡巍巍尧舜天，外臣巢许谁羁束。\n\n前年我亦访湖山，山色湖光竟尘俗。荒坟三尺走狐狸，那复寒泉荐秋菊。\n\n真祠并入梵王家，香月亭前马牛牿。水边篱落忽横枝，遥睇犹艰况斤斸。\n\n鸡园释子皆鹰腾，挟弹扬鞭骤平陆。仓皇走避尚遭嗔，蹇卫何堪共驰逐。\n\n三百年间一梦同，人与梅花几荣辱。拊图三叹复何言，天外飞来两黄鹄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '为郭元德题和靖探梅图' AND p.poem_author = '俞德邻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹊桥仙（为人庆八十席间戏作）', '辛弃疾', '宋代', '朱颜晕酒，方瞳点漆，闲傍松边倚杖。不须更展画图看，自是个、寿星模样。 \n 今朝盛事，一杯深劝，更把新词齐唱。人间八十最风流，长帖在、儿儿额上。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹊桥仙（为人庆八十席间戏作）' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('为秦伯未之济画梅繫以截句四首 其一', '曹家达', '清代', '休将往迹问林逋，老鹤归来觅旧株。除是孤山一卷石，不随春涨过西湖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '为秦伯未之济画梅繫以截句四首 其一' AND p.poem_author = '曹家达';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('折槛行送沈纯父北上', '胡应麟', '明代', '北风动地捲霜雪，沈子严装候明发。白马银鞍走燕市，天子召见黄金阙。\n\n忆昔丁丑年中事，呜呼已往难陈说。纲常万古忽如线，沈子旁观眦双裂。\n\n三年忍蔑父母爱，七尺自与妻儿诀。飞书一夜上明主，百辟苍皇胆俱慑。\n\n宫闱动色问忠悃，乞得残躯傍南粤。茫茫大海天欲尽，野魅山魈共生活。\n\n铜柱频更伏波戍，铁衣乱洒羁臣血。桄榔叶底托馀荫，豆蔻枝前赋鶗鴂。\n\n鬓毛五载凋欲尽，意气千钧莽难折。离骚熟读引斗酒，怒击青萍唾壶缺。\n\n云雾朝披博罗顶，星斗夜摸空同峡。归来笑拥绿衣女，卢橘杨梅照红颊。\n\n朝云已去学士还，瘴雨蛮烟护荒碣。精忠大节岂重睹，文藻风流颇颃颉。\n\n乾纲一振壬午岁，地辟天开走狐孽。徵书九道发燕邸，尽起龙干布朝列。\n\n是时沈郎奉明诏，长啸扁舟返西浙。逡巡故国拜丘垄，问寝高堂痛离阔。\n\n县官日夜戒行李，驿使交驰讯车辙。男儿肯作里中老，直臣更树台端节。\n\n同时吴赵艾与邹，騄駬飞黄并腾踏，沈郎讵得终岩穴。\n\n天上仙查溯河汉，腰下刀环耀明月。扬鞭再过五陵豪，击筑重招蓟门侠。\n\n蓟门楼殿花三千，尚记公车抱长铗。对策明光亦草草，敝履短衣行䠥𨇨。\n\n中原邂逅吾共尔，白眼红颜寸衷合。诵余连璧心已醉，示我郊居思横发。\n\n苍茫大雪华阳街，拂袖徐生馆中别。风尘倾盖古则有，宇宙论心近谁洽。\n\n即今汝燕余复越，抗手胡能不悲咽。沈伯子，酌汝蒲萄之美酒，系汝珊瑚之宝玦。\n\n一言赠汝中自知，此去中外望掀揭。儿童走卒尽道汝，凛凛刚肠石与铁。\n\n腰金拖玉宁汝事，义胆忠肝岂虚设。三公九列贵易保，万姓千秋口难辍。\n\n重华尚纳大禹戒，仲甫亦补周王阙。朝多善政禄可飧，事有当言槛仍折。\n\n风云况遇大行日，努力群龙树勋业。竹帛旂常两光绝，一旦抽身蚤林樾。\n\n丈夫出处须伟烈，呜呼丈夫出处须伟烈，异日儒生秉鈇钺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '折槛行送沈纯父北上' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵胡彦明同年羇旅京师寄李子飞三章一章道', '黄庭坚', '宋代', '看除日月坐中铨，一岁应无官九迁。\n葱韭盈盘市门食，诗书满枕客床毡。\n留连节物孤朋酒，恼乱邻翁谒子钱。\n谁料丹徒布衣得，困穷且忍试新年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵胡彦明同年羇旅京师寄李子飞三章一章道' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('摊破丑奴儿 纪艳', '陈维崧', '清代', '隔帘挼碎相思苣，斜著乌云。漾著红巾。袅袅亭亭一段春。\n\n是耶，难道是、昨宵人。\n\n戟门阖却葳蕤锁，花气氤氲，月色缤纷。墙角猧儿吠夜分。\n\n非耶，谁道是、昨宵人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '摊破丑奴儿 纪艳' AND p.poem_author = '陈维崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('先忠端公祠堂落成王明府蒿伊命广文沈令辰摄二月丁祭 其三', '黄宗羲', '清代', '黄竹浦间几劫灰，祠门正对舜江开。土人不识忠魂返，但讶天边雪浪来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '先忠端公祠堂落成王明府蒿伊命广文沈令辰摄二月丁祭 其三' AND p.poem_author = '黄宗羲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题周鲲仿唐寅终南十景图 其八 涤烦矶', '弘历', '清代', '万木郁蜚云，众泉泌鸣玉。拂轸试一写，不作招隐曲。\n\n境寂夫何妨，高人乐事足。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题周鲲仿唐寅终南十景图 其八 涤烦矶' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙　横铺泳归作', '卢青山', '当代', '日暮清流泳始还，河中剩有一痕山，岸边随手摘荷玩。\n\n谁要苍烟浮稻陇？渐无夕照下鱼湾，蜻蜓独自过桥栏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙　横铺泳归作' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送刘玉桥北上', '文嘉', '明代', '岁晚江空岸草枯，故人舟楫向皇都。相逢不尽相违意，写得天寒欲雪图。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送刘玉桥北上' AND p.poem_author = '文嘉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟曹子建赠白马王彪六首 其四', '缪祐孙', '清代', '明哲本犹人，涕泪对昊天。幸赖人命长，豫顺久则然。\n\n洒泪伤子弟，雕零蒲柳先。戕责属伊谁，未免徒自怜。\n\n魂魄返旧居，应识路绵绵。大海汇百川，乃有精卫填。\n\n高岸虽崔嵬，为谷伤他年。逝者不复追，此恨畴能捐。\n\n懿德良不渝，努力志圣贤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟曹子建赠白马王彪六首 其四' AND p.poem_author = '缪祐孙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其九', '魏了翁', '宋代', '一位肴羞酒一卮，祠官熏灌祝陈词。降升六拜焚词罢，六日精神用一时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八月七日被命上会稽沿途所历拙于省记为韵语以记之舟中马上随得随书不复叙次 其九' AND p.poem_author = '魏了翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('茅山书屋为项德懋题', '罗玘', '明代', '满山生白茅，茅白山亦白。维翁养默惯，分与尘世隔。\n\n拔茅覆山椒，牵萝缉茅壁。面壁梦周孔，冥心契羲画。\n\n茅疏壁缭多，缺月瞰深夕。百年翁骨寒，山鬼夜敲石。\n\n鼻耳真贯穿，诛茅掘遗磶。见磶如见翁，护磶如护璧。\n\n一磶复一柱，吾当陋晋籍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '茅山书屋为项德懋题' AND p.poem_author = '罗玘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读史三首 其二', '何中', '元代', '嬴法四海热，震荡昏三光。云飞大风起，赤子沐清凉。\n\n当时周旋人，一瞰罹身殃。悠悠赤松子，不识为何祥。\n\n千年有崔浩，前修持自彰。岂知愧所事，乃是元家王。\n\n恐非凤衔图，但见雁求梁。伊尔山中人，勿弃兰蕙芳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读史三首 其二' AND p.poem_author = '何中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉泉山杂咏十六首 其四 观音洞', '弘历', '清代', '何处飞来此落伽，默然不更转三车。设云义谛无馀转，者个非忘见转差。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉泉山杂咏十六首 其四 观音洞' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题月夜鸣琴图为庄知州赋', '倪谦', '明代', '空山无人秋夜凉，银河荧荧流月光。苍龙百尺落松影，松梢露滴沾衣裳。\n\n幽人中夜耿不寐，起抱丝桐幽思长。坐据苔石不知泠，横膝对月调宫商。\n\n山高水深趣未已，谁其知者同徜徉。七弦不尽太古意，下听独有仙娥嫦。\n\n调高馀响振山谷，啼鸟惊起争飞翔。夜深欲鼓广陵散，斜月半落山苍苍。\n\n呼童抱琴且归去，净扫白云眠石床。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题月夜鸣琴图为庄知州赋' AND p.poem_author = '倪谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归至镇远次祁石阡荅家人相慰藉韵', '周瑛', '明代', '一官飘泊共遐荒，文事驱人偏自忙。藜杖远分天禄火，梅诗旋入镇阳装。\n\n形骸莫逆怜同道，萍水相逢忘异乡。为语家人莫惊讶，鬓毛原带去时霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归至镇远次祁石阡荅家人相慰藉韵' AND p.poem_author = '周瑛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游雪窦杖锡七首·锦镜池', '陈著', '宋代', '万仞崖擎碧玉台，中閒一镜帖天开。\n四时自与幽花对，一点时妆不照来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游雪窦杖锡七首·锦镜池' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题资福院平绿轩', '曾揆', '宋代', '终日劳劳雁鹜行，偶然来访赞公房。\n扶疏草木四围合，萦绕溪流一带长。\n倚槛岂能成杰句，把杯多是说名方。\n问师乞取安心法，宴坐蒲团对佛香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题资福院平绿轩' AND p.poem_author = '曾揆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿土坊驿寄孔世长', '王安石', '宋代', '烧夜郊原百草荒，弊裘朝去犯严霜。\n残年意象偏多感，回首风烟更异乡。\n往返自非名利役，辛勤应见友朋伤。\n章江犹得同游处，最爱梅花蘸水香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿土坊驿寄孔世长' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('如果', '席慕容', '近代', '四季可以安排得极为暗淡 \n如果太阳愿意\n\n人生可以安排得极为寂寞 \n如果爱情愿意\n\n我可以永不再出现 \n如果你愿意\n\n除了对你的思念 \n亲人和朋友 \n我一无长物\n\n然而 \n如果你愿意 \n我将立即使思念枯萎 \n断落\n\n如果你愿意 \n我将 \n把每一个河流都切断 \n让荒芜干涸延伸到无穷远 \n今生今世 \n永不再将你想起\n\n除了 \n除了在有些个 \n因落泪而湿润的夜里\n\n如果 \n如果你愿意', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '如果' AND p.poem_author = '席慕容';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('驿骑传诗图为黄太守丈题', '姚燮', '清代', '潮阳多悍民，蚁斗恣愚蠢。刑法藐官吏，有司策惶窘。\n\n丁年闰五月，野啸动荒巘。一鬨蹈危刃，老稚半墨膑。\n\n太守率虎旅，峨冠驻罘䍐。名熟军中韩，胆已慑强忍。\n\n斯时霉伏交，苦瘴郁蛮蜒。烟箐坐蛇穴，日炙气凄紧。\n\n军书间旁午，陟冈揽牛纼。揭阳指烟郭，瓦屋故人近。\n\n大风啸林薄，长歌振颓坋。纵笔草龙蛇，擘笺束如笋。\n\n急羽授铃骑，空匆走羊坂。一瞬四十里，云天落飞隼。\n\n丛溪虎贴尾，北斗照䉋箘。霜声奏传鼓，城马忽传返。\n\n屯兵镇沈肃，文光耀焱焜。雅歌谁投壶，草檄几磨盾？\n\n不意驰突中，华辞出警敏。披图相其势，岩栈互嶾嶙。\n\n佳话后谁继，壮怀去无尽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '驿骑传诗图为黄太守丈题' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感怀', '于豹文', '清代', '四十年来事，凄然暮雨中。飞腾惭去鸟，萧瑟近衰翁。\n\n敢谓诗书误，羞云篆刻工。寥寥千载上，此意竟谁同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感怀' AND p.poem_author = '于豹文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('閒居', '王宠', '明代', '绕舍扶疏千树林，古台莺语昼沉沉。山童佐舞调双鹤，病客閒居戏五禽。\n\n阮籍猖狂雠礼法，仲长乐志薄朝簪。凭高更觉青冥远，弋者徒闻黄鹄音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '閒居' AND p.poem_author = '王宠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洞仙歌 去冬无雪，新岁乃稍稍见，正月二十', '袁易', '元代', '与勉夫对坐萧齐，即景漫赋江枫汀树，挂寒云零乱。天阔谁填莫愁满。散玉尘千斛，装□柴门，堪笑处、天女多情恨晚。灞桥丝样柳，恰试鹅黄，笛里东风便吹断。莫话剡溪船，乘兴归来，早闲了落梅庭院。爱搀占西园做飞花，又不道春光，', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洞仙歌 去冬无雪，新岁乃稍稍见，正月二十' AND p.poem_author = '袁易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题沈启南赠尹孟容画', '史鉴', '明代', '天水吴兴两地悬，椷诗遥作买山钱。峰峦满纸新题遍，乔木依然在涧边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题沈启南赠尹孟容画' AND p.poem_author = '史鉴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵湖山居士见过', '释德洪', '宋代', '平昔云岑在怀抱，而今怀抱在云岑。闻泉偶尔成诗句，班草相看坐木阴。\n\n古鼎自然无俗韵，朱弦真是有遗音。羊欣不肯踏城市，背郭江村独见寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵湖山居士见过' AND p.poem_author = '释德洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金丹诗四十八首', '张继先', '宋代', '不觉年年撚指过，急如催浪转长河。\n鼎中日月知人少，世上阴阳识者多。\n尽为资财损真性，皆因女色逐流波。\n□□半有归泉路，忍把真元乱鬼魔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金丹诗四十八首' AND p.poem_author = '张继先';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('某顷知黄州墨卿为州司录今八年矣邂逅临川送别二首 其二', '韩驹', '宋代', '盗贼犹如此，苍生困未苏。今年起安石，不用哭包胥。\n\n子去朝行在，人应问老夫。髭须衰白尽，瘦地日携锄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '某顷知黄州墨卿为州司录今八年矣邂逅临川送别二首 其二' AND p.poem_author = '韩驹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('时雨三首 其一', '张侃', '宋代', '旬日风消雨，今朝山出云。柳深开润色，荷靓匝清芬。\n\n江燕新调语，沙鸥自引群。农人相贺语，田亩可耕耘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '时雨三首 其一' AND p.poem_author = '张侃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('下元节后省试进奏院吏', '洪咨夔', '宋代', '推云不动雨声苦，醖雪未成风力乾。\n瘖鹜一庭淘墨汁，也烦老子坐深寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '下元节后省试进奏院吏' AND p.poem_author = '洪咨夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李遵道海岳图', '郑元祐', '元代', '李黄岩，疏眉瘦体满臆秋崭崭。似厌分符涧谷底，折腰督邮面皱须毵毵。\n\n竟骑鲸鱼上天去，帝悯人间留不住，乃令笔底飞墨如云雾。\n\n王维郑虔本有素，早年临摹米颠海岳图。黄岩非有颠非无，庵空月落山木拥，是中疑有穷猿呼。\n\n二子风流俱不泯，宝月夜夜生珊瑚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李遵道海岳图' AND p.poem_author = '郑元祐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居志感（二首）', '石林瑛公', '明代', '嘉蔬值我园，好鸟巢我树。\n树枯鸟惊栖，园荒蔬委路。\n寒气肃山林，新芳飒然故。\n物理有固然，于何起欣恶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居志感（二首）' AND p.poem_author = '石林瑛公';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵赵明叔喜雨不寐', '周紫芝', '宋代', '云忽油然雨沛然，黄童白叟尽成颠。唤晴鸠妇鸣屋角，饱水秧孙明稻田。\n\n御史平冤魂亦喜，弘羊言利死谁怜。草玄窗下子扬子，凉入孤灯夜不眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵赵明叔喜雨不寐' AND p.poem_author = '周紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏日闲居作四声诗寄袭美。平声', '陆龟蒙', '唐代', '荒池菰蒲深，闲阶莓苔平。江边松篁多，人家帘栊清。 \n 为书凌遗编，调弦夸新声。求欢虽殊途，探幽聊怡情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏日闲居作四声诗寄袭美。平声' AND p.poem_author = '陆龟蒙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居杂兴五首 其五', '郑潜', '明代', '读书岂在多，适用一编足。君听刍荛言，可备太史录。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居杂兴五首 其五' AND p.poem_author = '郑潜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游长安诸寺联句。崇义坊招福院。赠诸上人联句', '段成式', '唐代', '翻了西天偈，烧馀梵宇香。撚眉愁俗客，支颊背残阳。 ——段成式 \n 洲号惟思沃，山名只记匡。辨中摧世智，定里破魔强。 ——张希复 \n 许睿禅心彻，汤休诗思长。朗吟疏磬断，久语贯珠妨。 ——段成式 \n 乘兴书芭叶，闲来入豆房。漫题存古壁，怪画匝长廊。 ——张希复', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游长安诸寺联句。崇义坊招福院。赠诸上人联句' AND p.poem_author = '段成式';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和邠老郎官湖怀古五首', '贺铸', '宋代', '昔人泯黄壤，陈迹变沧波。\n劫火洞然坏，无如嘉句何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和邠老郎官湖怀古五首' AND p.poem_author = '贺铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄曹参军 其二', '佘翔', '明代', '结客谈兵幕府才，蹉跎宦迹转堪猜。独醒总为风尘忌，湖上兰桡醉几回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄曹参军 其二' AND p.poem_author = '佘翔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠鹤林上人', '刘崧', '明代', '日日涧边寻茯苓，岩扉长掩凤山青。归来挂衲高林下，自剪芭蕉写佛经。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠鹤林上人' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无题次邱工部韵八首 其三', '林朝崧', '清代', '品在环肥燕瘦间，三千粉黛料难攀。梦中几度经沧海，镜里何由保蕣颜。\n\n乌鹊无依空绕树，蘼芜欲采懒登山。平生待字深闺日，肯信丹青尔许閒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无题次邱工部韵八首 其三' AND p.poem_author = '林朝崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送谢祭酒之任南雍', '王鏊', '明代', '峻节高怀自可亲，两年史馆况为邻。久甘静退元非病，稛载诗篇亦未贫。\n\n台右人才多近古，当今师道复何人。看详学制伊川在，士子东南要一新。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送谢祭酒之任南雍' AND p.poem_author = '王鏊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自槜李至毗陵道中', '杨冠卿', '宋代', '满目江山无限情，夫差城郭暮云平。\n当时不竞黄池长，一再何由致越兵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自槜李至毗陵道中' AND p.poem_author = '杨冠卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('人有为石梁谣者录成 其十五', '郑真', '明代', '别来三月不见郎，夜灯明灭泪成行。妾身许得单衣愿，不怕穷冬有雪霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '人有为石梁谣者录成 其十五' AND p.poem_author = '郑真';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词一百首', '岳珂', '宋代', '洛京韫椟起儒珍，地讲忠规德日新。\n禁苑金丝舞垂柳，万方已被发生仁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词一百首' AND p.poem_author = '岳珂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('如梦令', '濮文绮', '清代', '昨夜晓窗寒甚。紫燕弄巢不定。何处觅东风，梦过月塘烟径。\n\n休问。休问。耽误梅花春病。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '如梦令' AND p.poem_author = '濮文绮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('惜寒梅', '汪东', '清代', '万卉凋零，有江梅、独许雪霜盟约。粉艳天真，苒苒香浮绣幕。\n\n满樽芳酒共谁酌。望天际、轻阴旋作。家园无恙，忘了归来，细看红萼。\n\n相思未是断却。柰江关赋愁，不堪落寞。花下前欢，此景羞人问著。\n\n拟凭鳞羽诉离索。怕纸尽、越添意恶。十分清瘦，南枝渐坼，莫近高阁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '惜寒梅' AND p.poem_author = '汪东';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桃源忆故人（春愁）', '郑域', '宋代', '东风料峭寒吹面。低下绣帘休卷。憔悴怕他春见。一任莺花怨。 \n 新愁不受诗排遣。尘满玉毫金砚。若问此愁深浅。天阔浮云远。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桃源忆故人（春愁）' AND p.poem_author = '郑域';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '曹纬', '宋代', '日依平野没。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '曹纬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题林宗鲁校书所藏宣和御画', '楼钥', '宋代', '周公多艺孔多能，徽庙才高更倍增。\n除却万机都不会，至今遗老话昭陵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题林宗鲁校书所藏宣和御画' AND p.poem_author = '楼钥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('明卿自楚驰信相问云秋后当访我金陵以一诗贺儿骐豋第以六诗苦旱答之', '王世贞', '明代', '楚波如黛泻潺湲，美有双鱼尾更殷。中散已申秋后驾，巨卿从破别时颜。\n\n乍悲云汉黎民咏，忽羡星辰父子班。解道起然无物念，人间忧乐也相关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '明卿自楚驰信相问云秋后当访我金陵以一诗贺儿骐豋第以六诗苦旱答之' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和西湖竹枝词', '张简', '元代', '鸳鸯蝴蝶尽双飞，杨柳青青郎未归。第六桥边寒食雨，催郎白苧作春衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和西湖竹枝词' AND p.poem_author = '张简';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠吴煦', '顾璘', '明代', '绿树凉生十亩阴，柴门永日少相寻。纨衫不碍跏趺坐，石砚聊随散诞唫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠吴煦' AND p.poem_author = '顾璘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登苏门山泛舟百泉 其一', '袁宏道', '明代', '食罢共成饭，来观泌水泉。废桥穿竹屿，小舫载茶烟。\n\n方外清溪寺，人间好畤田。那能营二项，风雨啸台眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登苏门山泛舟百泉 其一' AND p.poem_author = '袁宏道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冷泉亭', '周权', '元代', '昔人来自天竺国，缥缈孤云伴飞锡。天风吹落凝不去，化作奇峰耸空碧。\n\n至今裂峡馀云髓，桂冷松香流未已。翠光围住玉壶秋，不放晴雷度山趾。\n\n道人宴坐无生灭，炯炯层胸照冰雪。夜深出定汲清泠，寒猿啼断西岩月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冷泉亭' AND p.poem_author = '周权';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('壬申见沪报载吴佩孚蛰居故乡，触景生情，感伤时局，咏诗八章，足徵英雄末路之胸怀。余步原韵藉以消遣 其三', '薛昂若', '清代', '无事隐居山水隈，渔樵耕读任徘徊。不知弹雨枪林下，怕看江边劫后灰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '壬申见沪报载吴佩孚蛰居故乡，触景生情，感伤时局，咏诗八章，足徵英雄末路之胸怀。余步原韵藉以消遣 其三' AND p.poem_author = '薛昂若';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和陶彭泽归田园居 其三', '童轩', '明代', '偶影自成酌，知音相与稀。山深日将夕，坐看孤云归。\n\n疏柳荫前除，凉风吹我衣。衣单亦何恤，所恨愿多违。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和陶彭泽归田园居 其三' AND p.poem_author = '童轩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春寒', '朱槔', '宋代', '人道春寒早系舟，楚山一夜雨浏浏。\n此生削迹江边路，嫩绿纷红只自愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春寒' AND p.poem_author = '朱槔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('平谷杂诗十八首 其十八', '曾习经', '清代', '楚泽哀时命，田园归去来。室庐无定处，风雨犹深怀。\n\n短策支颐久，单衣至骭裁。比邻逢李叟，还讯菊花开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '平谷杂诗十八首 其十八' AND p.poem_author = '曾习经';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('仙兴', '吴惟信', '宋代', '宫殿高高在五云，鹤摇松露滴行人。洞门不放东风过，留得桃花一院春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '仙兴' AND p.poem_author = '吴惟信';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观澜亭', '许将', '宋代', '危亭高处倚岩隈，西望蒲菖海浪回。\n山戴鳌头天外出，水浮鳅穴地中来。\n千重侧崦扶摇没，万里分流混沌开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观澜亭' AND p.poem_author = '许将';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('北上留别泾皋同志', '夏孙桐', '清代', '断送秋光又一年，芙蓉寂寞冷江烟。登山临水将归客，破浪乘风未了缘。\n\n对酒歌成宜楚调，载书装重笑吴船。牢愁别绪何须诉，日日孤云落照边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '北上留别泾皋同志' AND p.poem_author = '夏孙桐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('端午帖子·皇帝阁', '周必大', '宋代', '令月初登黍，嘉辰旧沐兰。\n宸心思解愠，时取舜琴弹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '端午帖子·皇帝阁' AND p.poem_author = '周必大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄太守元授挽词二首 其二', '杨万里', '宋代', '我忝通家子，公如父行亲。一书虽不欠，半面遂无因。\n\n旅榇千江远，铭旌两竹新。庆门宁有此，造物岂其仁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄太守元授挽词二首 其二' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('念昔游四首 其二', '胡仲弓', '宋代', '昔游金山寺，一苇破沧溟。怒涛正拍天，风雨歘晦冥。\n\n江豚急吹浪，水面轰雷霆。满船失颜色，莫辨死与生。\n\n此时娄师德，高卧看长鲸。过午忽开霁，济岸犹登瀛。\n\n清风泛我衣，阳光射檐楹。舟人相慰劳，山僧笑出迎。\n\n行行金鳌背，月鉴浮空明。波平濛天影，潮静闻经声。\n\n殿阁耀金碧，守护真龙形。系缆少沉吟，红轮江西倾。\n\n炬火烁江面，直使潜鳞惊。因成一宿觉，问津维扬城。\n\n重来知几时，未计岁月成。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '念昔游四首 其二' AND p.poem_author = '胡仲弓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('到南昌呈宋愿父伯仲黄子鲁诸丈', '戴复古', '宋代', '一秋无便寄平安，新雁声声报早寒。\n昨夜检衣开故箧，去年家信把来看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '到南昌呈宋愿父伯仲黄子鲁诸丈' AND p.poem_author = '戴复古';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吾家', '姜特立', '宋代', '吾家何处住，一嶂独成围。\n莫遣通樵斧，应嫌减翠微。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吾家' AND p.poem_author = '姜特立';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑曲', '曹勋', '宋代', '鸣鸠初拂羽，桑叶破新萌。\n采采不盈菊，攀多力未生。\n春服浥朝露，晓日映妆明。\n语学流莺巧，身同飞燕轻。\n使君劳借问，夫婿自专城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑曲' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居 其二', '王邦畿', '明代', '高居若天外，茅屋不劳扃。避石松形古，当泉竹脚青。\n\n虫声秋入户，山色晚宜亭。更自闻寒籁，林僧夜教经。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居 其二' AND p.poem_author = '王邦畿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢马程先', '林逋', '宋代', '数幅丹霞夹白云，封题何事寄幽人。亏君视草禁中客，乞我浣花溪上春。\n\n且与巾箱为玩好，更无篇什写清新。我来卧病还多感，一笔蛛丝满砚尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢马程先' AND p.poem_author = '林逋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('客有为予言笋不可食食之令人瘦者戏作二绝为解嘲 其一', '周紫芝', '宋代', '庾郎三韭坐清贫，眼看将军肉十斤。会遣胸中有千亩，不妨人似沈休文。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '客有为予言笋不可食食之令人瘦者戏作二绝为解嘲 其一' AND p.poem_author = '周紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('华容十咏为毛同府赋 其五 南山远翠', '史鉴', '明代', '湖水流无际，山形荡欲漂。云生齐北斗，脉衍自南条。\n\n朱凤高飞尽，苍梧别望遥。禹功垂万古，祠宇亦萧萧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '华容十咏为毛同府赋 其五 南山远翠' AND p.poem_author = '史鉴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿新升圩港', '陈熙治', '清代', '欲宿投何处，驱车任所之。野花村女鬓，红杏酒家旗。\n\n犬吠寒云外，人归暮雨时。凄凉谁共诉，倚枕泪如丝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿新升圩港' AND p.poem_author = '陈熙治';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戚氏（此词始终指意，言周穆王宾于西王母事）', '苏轼', '宋代', '玉龟山。东皇灵媲统群山。绛阙岧峣，翠房深迥，倚霏烟。幽闲。志萧然。金城千里锁婵娟。当时穆满巡狩，翠华曾到海西边。风露明霁，鲸波极目，势浮舆盖方圆。正迢迢丽日，玄圃清寂，琼草芊绵。争解绣勒香鞯。鸾辂驻跸，八马戏芝田。瑶池近、画楼隐隐，翠鸟翩翩。肆华筵。间作脆管鸣弦。宛若帝所钧天。稚颜皓齿，绿发方瞳，圆极恬淡高妍。 \n 尽倒琼壶酒，献金鼎药，固大椿年。缥缈飞琼妙舞，命双成、奏曲醉留连。云璈韵响泻寒泉。浩歌畅饮，斜月低河汉。渐渐绮霞、天际红深浅。动归思、回首尘寰。烂漫游、玉辇东还。杏花风、数里响鸣鞭。望长安路，依稀柳色，翠点春妍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戚氏（此词始终指意，言周穆王宾于西王母事）' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过束河同和书香、木秀元龙潭小酌即事', '牛焘', '清代', '携酒壕梁上，班荆野趣饶。鸟枝花自落，蛇蔓叶初□。\n\n□□□□水，灵山秋药苗。年来深契阔，于此共逍遥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过束河同和书香、木秀元龙潭小酌即事' AND p.poem_author = '牛焘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('摸鱼儿 寿留仙', '严绳孙', '清代', '似仙源、桃花零乱，武陵一棹重驻。玉堂铃索花砖日，旧是先生游处。\n\n愁如絮。消受尽、五湖烟月三湘雨。君恩再许。教领袖词流，双椽烛底，洒翰继迁固。\n\n喜不改，张绪当年风度。柳弧依旧悬户。交疏月转传筹饮，坠遍玉河红露。\n\n支机浦。早看取、七香车上山眉妩。离情休诉。只此恨重偿，双纹簟展，肯放早朝去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '摸鱼儿 寿留仙' AND p.poem_author = '严绳孙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送朱大使朝京回迎父往福建任所', '程通', '明代', '三载官南闽，寸心恋北阙。玉佩朝龙颜，斑衣迎鹤发。\n\n山青云自閒，梅黄雨初歇。别后天一方，相思共明月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送朱大使朝京回迎父往福建任所' AND p.poem_author = '程通';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉和滁州九咏九首·归云洞', '曾巩', '宋代', '野草山花夹乱流，桥边旌旆影悠悠。\n即应要地无人见，可忍开时不出游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉和滁州九咏九首·归云洞' AND p.poem_author = '曾巩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书事', '陆游', '宋代', '北征谈笑取关河，盟府何人策战多？扫尽烟麈归铁马，剪空荆棘出铜驼。\n史臣历纪平戎策，壮士遥传入塞歌。\n自笑书生无寸效，十年枉是枕琱戈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书事' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小画 其二', '丁鹤年', '元代', '翠黛浮晴汉，虬枝立暝烟。回舟不用楫，江上水吞天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小画 其二' AND p.poem_author = '丁鹤年';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二月十一日晓发龙山风顺', '方回', '宋代', '繁华销歇市朝空，此地何堪着固穷。\n久似坎蛙居井底，忽如野鹤出笼中。\n宿酲夜解催花雨，归棹春乘上水风。\n及得清明到家否，新芽茶绿牡丹红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二月十一日晓发龙山风顺' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽陈县尉歌词', '戴栩', '宋代', '欲裁薤曲问耆贤，见说声华四十年。\n六馆已推天下士，一官向羡吏中仙。\n白砂旧事渔樵老，缥轴新铭蜡墨鲜。\n便觅当今徐穉笔，榜知如玉在松阡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽陈县尉歌词' AND p.poem_author = '戴栩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('落花流水篇', '弘历', '清代', '荏苒韶华过百六，羲轮电迅谁能逐。试探幻影绕花堤，还缀芳痕在溪澳。\n\n溪流宛转曲复斜，刺舟追赏幽兴遐。谁家亭榭无流水，何处风光不落花。\n\n落花流水春无赖，锦脂千片环一带。武陵见说引渔人，天台几度刘郎会。\n\n刘郎去后无消息，渔人再寻寻不得。残英依旧恋回波，辞枝恰借封姨力。\n\n封姨非是妒艳春，桑田海水迁移频。乍令琼姿沦碧沼，不教玉质埋黄尘。\n\n蜂衙蝶阵喧嘈甚，清流暂托参无眹。红紫都来做一团，李桃何必分两品。\n\n西子湖边纱独浣，天孙机上云方满。亦有佳人欲黯魂，漫誇词客纷撩眼。\n\n愁人万点曲江头，乘波绿珠初坠楼。尽道女夷嫁河若，不须解佩通蹇脩。\n\n铅华洗尽芳芬调，忘言默契无形妙。恍忆耆阇窟会时，如来拈起迦叶笑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '落花流水篇' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴中柳枝（四首）', '陈秀民', '元代', '长洲宫苑草离离，中有吴王旧沼池。\n至今二八吴中女，为人歌舞学西施。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴中柳枝（四首）' AND p.poem_author = '陈秀民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('明月亭下作', '孔武仲', '宋代', '杳杳芜城起暮钟，亭亭华月照秋容。\n便疑碧海依墙堑，云水情知隔万重。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '明月亭下作' AND p.poem_author = '孔武仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题真娘墓', '徐照', '宋代', '骨成泉下土，何物是游魂。\n一代颜容尽，千年名姓存。\n善缘依佛地，巧咏任人言。\n几听钱塘曲，风松静似喧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题真娘墓' AND p.poem_author = '徐照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无题', '吴鼎芳', '明代', '绮疏微透晓光寒，欲贴鸦黄展镜鸾。\n错怪桃花似侬面，一番风雨便春残。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无题' AND p.poem_author = '吴鼎芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送木宗院', '徐照', '宋代', '此职司天派，员分南与西。\n事稀从吏懒，诗好笑人低。\n丹荔开屏画，青榕盖鹤栖。\n必思随侍日，曾有旧留题。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送木宗院' AND p.poem_author = '徐照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '李庆孙', '宋代', '四夷妙赋无人诵，三酌酸文举世传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '李庆孙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和史樵云春兴三首 其三', '乌斯道', '明代', '山深路僻少人过，早晚惟凭七字哦。归思不随流水急，閒情浑似白云多。\n\n花开踯躅红千树，笋长筼筜绿数窠。想得此时如杜甫，池亭对酒爱新鹅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和史樵云春兴三首 其三' AND p.poem_author = '乌斯道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('双髻岭', '胡文路', '明代', '谁把芙蓉海上栽，一枝两枝何日开。青苍今古不摇落，岩岈天地空崔嵬。\n\n圭璋削玉齐云立，银管冲霄碇斗极。根盘五指南溟深，花放四时娇欲滴。\n\n团团日月磨巑岏，飘飘风雨净婵媛。欲从蓬岛看正萼，直须鳌极探真源。\n\n汉武好奇闻自昔，开疆辟土寻端的。安期海上竟贪看，遂使君王长叹息。\n\n我家住在此花东，日日看花得正宗。最爱晴奇雨亦好，偏于夜月更情浓。\n\n逆从浩劫数分至，几见伸葩泄灵异。有时放出五色云，有时腾起丹霞气。\n\n我昨乘风九华游，烟云袅娜似瀛洲。匡庐五老藏彭蠡，何如渤海浮天球。\n\n乡人不识花模样，双髻马鞍名孟浪。从今援笔写花神，看花祇在青霄上。\n\n青霄头角何昂藏，笑向川原眉眼张。气吞鲸海凌风举，三年一度献君王。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '双髻岭' AND p.poem_author = '胡文路';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送周天叙出使于闽顺道省亲', '江源', '明代', '我爱君家鬓未华，可人文采际亨嘉。八千里外新持节，三百人中旧探花。\n\n征旆远飞闽海月，綵衣仍过越南家。平生却叹乘槎客，肯把蒲萄载使车。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送周天叙出使于闽顺道省亲' AND p.poem_author = '江源';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答唐济武太史用来韵', '袁藩', '清代', '夜凉静听秋声起，篱外草虫鸣不止。挑镫坐对松影寒，明月乍出疏林里。\n\n少年华发惊时节，便欲学仙归贝阙。十载劳心思探珠，半生失计空磨铁。\n\n神仙何必厌妻子，秦楼弄玉随箫史。织女黄姑会有时，别床异被徒为尔。\n\n先生闻道何其早，红尘莫惜知音少。须从火底现莲花，肯向秋原同腐草。\n\n与君试访殷七七，至道不烦惟守一。天台有路度石桥，水流定泛桃花出。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答唐济武太史用来韵' AND p.poem_author = '袁藩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感怀 其三', '王冕', '元代', '写字不适俗，读书难疗饥。\n蘧蘧尘网中，遑遑欲可之？仁风霜原隰，草树发幽姿。\n群动正翕集，游云未来归。\n怀哉鹤上人，徘徊感良时。\n无以慰蹇劣，樽酒聊自怡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感怀 其三' AND p.poem_author = '王冕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄子将诗及拟骚见贻酬赠二首 其二', '王世贞', '明代', '天末空长剑，人间自曲钩。啖名殊代事，吞恨大江流。\n\n妙手斲轮得，雄心伏枥收。君看扬马后，馀子尽悠悠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄子将诗及拟骚见贻酬赠二首 其二' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('失题', '杨巨源', '唐代', '何事慰朝夕，不逾诗酒情。山河空道路，蕃汉共刀兵。 \n 礼乐新朝市，园林旧弟兄。向风一点泪，塞晚暮江平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '失题' AND p.poem_author = '杨巨源';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('牡丹四首 其二', '薛能', '唐代', '万朵照初筵，狂游忆少年。晓光如曲水，颜色似西川。\n\n白向庚辛受，朱从造化研。众开成伴侣，相笑极神仙。\n\n见焰宁劳火，闻香不带烟。自高轻月桂，非偶贱池莲。\n\n影接彫盘动，丛遭恶草偏。招欢忧事阻，就卧觉情牵。\n\n四面宜绨锦，当头称管弦。泊来莺定忆，粉扰蝶何颠。\n\n苏息承朝露，滋荣仰霁天。压栏多尽好，敌国贵宜然。\n\n未落须迷醉，因兹任病缠。人谁知极物，空负感麟篇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '牡丹四首 其二' AND p.poem_author = '薛能';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('用韵答何大镛朱学渊', '邓雅', '明代', '才俊纷纷总入朝，此生祗合老渔樵。春秋未解穷三传，大学徒能究八条。\n\n物外无心超世网，閒中有味酌山瓢。故人亦肯怜幽独，寻访频能过石桥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '用韵答何大镛朱学渊' AND p.poem_author = '邓雅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苦热行 其二', '黎民表', '明代', '云里楼台白玉京，龙绡飘动引飞琼。凉风更奏哀蝉曲，十里荷花碧浪生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苦热行 其二' AND p.poem_author = '黎民表';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('云亭萧氏园池杂兴次韵四首 其三', '刘崧', '明代', '小小窗轩溪水头，石门古路转斜丘。野林丹碧风初起，山橘青黄露未收。\n\n鸟下平原飞雨夕，猿啼孤嶂断云秋。读书台近招提境，思见当年隐者流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '云亭萧氏园池杂兴次韵四首 其三' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题鸂𪅍竹雀萱堂图', '陶安', '明代', '珍禽文采明金沙，相顾似怜毛羽嘉。托邻喜傍君子竹，忘忧更有宜男花。\n\n良工笔意何处好，林雀哺雏心使饱。北堂留得此图看，依旧春晖照幽草。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题鸂𪅍竹雀萱堂图' AND p.poem_author = '陶安';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乙未元夕坐上用东坡上元韵二首 其一', '胡铨', '宋代', '胜游宝箓记吾曾，五十年来一衲僧。昼短莫吟千岁烛，年丰聊看九华灯。\n\n一毬未放寒星坠，万炬浑惊烈日升。诗酒虽堪驱使在，照愁佳句愧坡能。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乙未元夕坐上用东坡上元韵二首 其一' AND p.poem_author = '胡铨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('初春邀诸固寅集小桃源', '陈迪祥', '明代', '帝城佳丽自畴昔，余生似带烟萝薜。不羡搴芳逐冶游，偏喜寻幽来野僻。\n\n白门桥西一径斜，中衍山林与阡陌。引著胜地兴不禁，等閒试理游春屐。\n\n侧身恍入武陵源，百道香光迷所适。玉树堂前兰蕊新，慈航堤畔柳芽碧。\n\n千树梅花绕径开，红白相错如绣襞。立望幽芬欲断魂，坐对落英屡沾帻。\n\n脩竹摇青似翠帏，方沼凝寒浸幽石。遥遥塔影出空林，隐隐梵音动深夕。\n\n我来静对已忘言，况复开樽引群益。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '初春邀诸固寅集小桃源' AND p.poem_author = '陈迪祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送尹给谏君润册封秦世子', '欧大任', '明代', '关城百二汉咸阳，捧册亲藩重夕郎。桐叶剪圭河水白，莲花开阁岳云苍。\n\n铜驼一别茏葱色，金马重来剑舄行。归日正逢停辇待，可无封事奏明光。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送尹给谏君润册封秦世子' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题黄初平叱石图', '胡应麟', '明代', '古木苍藤挂风雨，白石峨峨洞门倚。黄家儿曹不解事，叱作群羊遍空起。\n\n胡生较汝差长年，俯窥五岳石五拳。他时一叱五羊起，白云飞尽罗浮巅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题黄初平叱石图' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和张少卿丈再到洛阳', '邵雍', '宋代', '当年曾任青春客，今日重来白雪翁。\n今日当年已一世，几多兴替在其中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和张少卿丈再到洛阳' AND p.poem_author = '邵雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('正月初十日恭奉皇太后幸圆明园', '弘历', '清代', '银海光摇界道斜，乘时茂对乐昭华。物标太皞青旗旆，气转苍寅玉斗车。\n\n一道垂虹朝贝阙，万年春酒进仙家。输他羯鼓传佳话，俄顷瑶林尽发花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '正月初十日恭奉皇太后幸圆明园' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('分寄方广避乱诸缁侣八首', '王夫之', '明代', '麋晨鹘夜昼鸺鹠，足覆寒蓑听未休。此自答恩还圣代，山僧莫只话惊鸥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '分寄方广避乱诸缁侣八首' AND p.poem_author = '王夫之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春·冰壑平生', '佚名', '宋代', '冰壑平生，如伯伦狂，似希乐豪。喜观书不用、菊茶明眼，登山不倩、藜杖扶腰。豆粥萍齑，脍羹鳞脯，湖海人常折简招。谁云老，有满怀风月，藏在诗瓢。凌晨向鹄冲霄。道昴宿于今又应萧。记垂弧令节，恰当後日，下元好景，正属前朝。冷胆如天，刚肠如剑，须把千杯寿酒浇。那堪更，是梅花时月，烂熳溪桥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春·冰壑平生' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('商子引语', '佚名', '先秦', '愚者暗于成事。智者见于未萌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '商子引语' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜宿永古寺与孤峰上人谈诗', '刘崧', '明代', '莲花池上月如霜，金地无尘夕景凉。海藏暗浮龙影动，露盘微注鹤声长。\n\n云栖梵钵留僧共，风隐铢衣护佛香。一夜不眠听说法，雨花撩乱满禅床。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜宿永古寺与孤峰上人谈诗' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('直指叶公枉顾赋谢四章 其二', '胡应麟', '明代', '灿烂西台白玉珂，频年直指向关河。丰城剑抱双龙出，瀫水桥乘驷马过。\n\n作赋风云回缥缈，飞章山岳动嵯峨。宁知一代苍生寄，几向清溪问绿蓑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '直指叶公枉顾赋谢四章 其二' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头（和赵景明知县韵）', '辛弃疾', '宋代', '官事未易了，且向酒边来。君如无我，问君怀抱向谁开。但放平生丘壑，莫管旁人嘲骂，深蛰要惊雷。白发还自笑，何地置衰颓。 \n 五车书，千石饮，百遍才。新词未到，琼瑰先梦满吾怀。已过西风重九，且要黄花入手，诗兴未关梅。君要花满县，桃李趁时栽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头（和赵景明知县韵）' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观宗室伯山司户诗卷', '释道潜', '宋代', '参军暂辍簿书忙，为我聊开古锦囊。玉骨已能含秀气，珠玑那解不辉光。\n\n王孙挟策真难事，妙质如君岂易量。它日雠书天禄阁，声名端可继刘郎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观宗室伯山司户诗卷' AND p.poem_author = '释道潜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('《绮疏遗恨》之绣床', '唐寅', '明代', '月沈花谢事堪伤，春树红颜梦短长；\n只有绣床针线在，残绒留得口脂香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '《绮疏遗恨》之绣床' AND p.poem_author = '唐寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八声甘州 其四 眠', '易顺鼎', '清代', '忆眠时凤帐掩娇颦，脸印枕痕新。任金钗压扁，罗衫摺蹙，休唤真真。\n\n只恐和人和梦，都化作梨云。梦里何滋味？犹咽香津。\n\n那日迥廊中酒，有猩红万点，铺作重茵。被檀奴欺负，偷解茜纱裙。\n\n甚东风相扶不起，被春愁困了柳腰身。凭仗着三生恩眷，消受横陈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八声甘州 其四 眠' AND p.poem_author = '易顺鼎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('万法寺喜书', '谢应芳', '元代', '客来喜得平安信，萧洒楼居日掩扃。\n潮近浪摇窗影白，地偏苔没履痕青。\n群贤方结莲花社，小楷尤抄贝叶经。\n岁晚归舟经甫里，好寻渔父过寒汀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '万法寺喜书' AND p.poem_author = '谢应芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('朝阳穿破衲赞', '释慧开', '宋代', '冷时急用之物，趁暖著些针线。\n忽然腊月到来，免致脚忙手乱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '朝阳穿破衲赞' AND p.poem_author = '释慧开';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('花时遍游诸家园', '陆游', '宋代', '枝上猩猩血未曦，尊前红袖醉成围。\n应须直到三更看，画烛如椽为发辉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '花时遍游诸家园' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('孙季章无愧郑季奕徐斯远以仆留智门载酒见过坐中雪作三诗 其一', '赵蕃', '宋代', '出山已与晓寒冲，下马频欣束缊逢。已见南山行更钝，到时山寺已昏钟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '孙季章无愧郑季奕徐斯远以仆留智门载酒见过坐中雪作三诗 其一' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵陈侍郎李察院潇湘八景图 江天暮雪', '喻良能', '宋代', '群山总入玉壶中，只有沧波映远空。独钓寒江晚来雪，凭谁画我作渔翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵陈侍郎李察院潇湘八景图 江天暮雪' AND p.poem_author = '喻良能';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东城马上', '贺铸', '宋代', '綵虹桥下水关东，接畛园林狭径通。繁杏半开随半落，短墙无计碍春风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东城马上' AND p.poem_author = '贺铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寒食', '释居简', '宋代', '才见茅檐插柳条，便知寒食是今朝。春应不恨相寻晚，应恨常阴一半消。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寒食' AND p.poem_author = '释居简';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('胡宗肃世德堂', '倪谦', '明代', '肇迹由妫汭，传家自越州。万支原共本，一派转分流。\n\n瑗族今承宋，陈封远绍周。邓林多杞梓，卞椟剩琳璆。\n\n兰茁阶庭秀，麟从薮泽游。宦门足诗礼，儒业守弓裘。\n\n省解名方显，师资望更优。阿翁荣荐秀，夫子乐林丘。\n\n方伯难兄贵，科名令器收。青云联济美，懿德允垂休。\n\n循理全中得，为仁岂外求。学皆敦古训，行总肖前修。\n\n厚泽何能斩，芳声孰与侔。绵绵若瓜瓞，翼翼著谋猷。\n\n乔木光闾里，恩波下冕旒。子孙钦厥世，复始见公侯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '胡宗肃世德堂' AND p.poem_author = '倪谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清明日同学士李惟中赵子期及国学官携酒东岳宫后园看杏花 其二', '吴当', '元代', '祠庙出东城，风云拱百灵。神光通御阙，天影抱彤庭。\n\n隙地多幽事，芳辰聚德星。道人偏爱客，更许制茅亭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清明日同学士李惟中赵子期及国学官携酒东岳宫后园看杏花 其二' AND p.poem_author = '吴当';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('依韵和正老自叹之什二首 其二', '强至', '宋代', '我无尺地可耕锄，君有高田占具区。若论生涯犹厚薄，独于宦意等分铢。\n\n壮年未建鸿毛利，寸禄聊甘稚齿孥。不学庸庸自持者，高冠空食上农夫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '依韵和正老自叹之什二首 其二' AND p.poem_author = '强至';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('将雪有怀', '何景明', '明代', '长安十万户，骑马欲何之。已动寻梅兴，空成采葛诗。\n\n雪心知霰集，云意怯风吹。今夜西堂烛，萧然有所思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将雪有怀' AND p.poem_author = '何景明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀古', '王冕', '元代', '会稽岩壑今犹古，王谢经行何所之？感慨传人有余思，风流异代不同时。\n春来野水生蒲柳，雨过空山长蒺藜。\n异代无人知禹穴，游人来往到今疑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀古' AND p.poem_author = '王冕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽郑淑人', '刘克庄', '宋代', '忆生军中为记室，谢公门馆事皆知。\n谦卑若妇初嫔日，检素犹夫未贵时。\n病了死生惟点首，晚忧家国每颦眉。\n旧人独有任安在，揽涕西风献些词。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽郑淑人' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李氏爱山楼', '薛嵎', '宋代', '境自吾心会，於焉识所存。\n鸟声喧后寂，树色郭中付。\n静寿备仁理，乾坤悟易门。\n白云同此意，相对亦无言。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李氏爱山楼' AND p.poem_author = '薛嵎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('招隐操 反招隐', '朱熹', '宋代', '南山之中桂树秋，风云冥濛。下有寒栖老翁，木食涧饮迷春冬。\n\n此间此乐，优游渺何穷。我爱阳林，春葩昼红。我爱阴崖，寒泉夜淙。\n\n竹柏含烟悄青葱。徐行发清商，安坐抚枯桐。不问箪瓢屡空，但抱明月甘长终。\n\n人间虽乐，此心与谁同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '招隐操 反招隐' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登九江长江决口处新堤', '傅义', '当代', '谁使狂蛟舞爪牙，生灵巨万倏倾家。而今纵是金汤固，莫忘曾为豆腐渣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登九江长江决口处新堤' AND p.poem_author = '傅义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送孙山长谒皮参政', '许月卿', '宋代', '授銊天教锦故乡，公心泉石不旂常。\n沙堤正自恐不免，野渡安能久退藏。\n羡子白刘从绿野，顾予鸡犬愧旌阳。\n衮衣会趁春风入，野服犹堪谒道傍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送孙山长谒皮参政' AND p.poem_author = '许月卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别驾刘景华甫下车即署海阳篆不三月以入觐行漫赋五绝为赠 其五', '林熙春', '明代', '二月垂杨满地花，东人翘首望回槎。赐金一橐归来解，料得儿童拥道誇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别驾刘景华甫下车即署海阳篆不三月以入觐行漫赋五绝为赠 其五' AND p.poem_author = '林熙春';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('减租诗', '朱瞻基', '明代', '官租颇繁重，在昔盖有因。\n而此服田者，本皆贫下民。\n耕作既劳勤，输纳亦苦辛。\n遂令衣食微，曷以赡其身。\n殷念恻予怀，故迹安得循。\n下诏减十三，行之四方均。\n先王亲万姓，有若父子亲。\n兹惟重邦本，岂曰矜斯人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '减租诗' AND p.poem_author = '朱瞻基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉麈尾', '谢翱', '宋代', '客持麈尾柄，色夺环与玦。尘心随影袪，一片若行雪。\n\n神兽潜空山，何年探灵穴。忽失落人手，遂为谈者悦。\n\n阴崖起白气，篆古踰轩颉。一拂沉藓文，再拂字不灭。\n\n三拂蛟螭腾，世眼不能别。投尔阴崖颠，惊怪吐其舌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉麈尾' AND p.poem_author = '谢翱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏鲁仲连诗', '阮卓', '南北朝', '鲁连有高趣，意气本相求。笑罢秦军却，书成燕将愁。\n\n聊弃南金赏，方从沧海游。寄言人世客，非君能见留。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏鲁仲连诗' AND p.poem_author = '阮卓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄醇民先生', '钱廷文', '清代', '茂树有高枝，清弦无细响。素交见生平，曾不为标榜。\n\n自我与夫子，幽巷通来往。散发坐茅亭，信宿得心赏。\n\n清梵激松风，禅寺邻书幌。主客共藜羹，闵子过周党。\n\n尺素隔层城，烟月劳梦想。嗟我倦游人，十年在草莽。\n\n书剑局高天，壮躯空慨慷。何处豁尘心，溪流晒渔网。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄醇民先生' AND p.poem_author = '钱廷文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感怀二首 其一', '刘基', '元代', '新晴杨柳散春丝，长路行人有所思。愁上容颜青镜识，寒生亭馆落花知。\n\n高云送雨来无定，独鸟惊风去自迟。闷对亭前紫荆树，同根那得却相离。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感怀二首 其一' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赵芷生提学投诗即行次韵答和', '李稷勋', '清代', '朝事惊心累叹欷，君胡掉首向岩扉。朝辞帝女过巫峡，夜唤湘累下秭归。\n\n归后江潭几秋树，山中日月尽春晖。彝陵郭畔匆匆语，目极神州涕满衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赵芷生提学投诗即行次韵答和' AND p.poem_author = '李稷勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄旧同游', '李复', '宋代', '去乡甲子四十二，归路山川九百三。\n长河无鲤来东北，远梦随月转西南。\n檐花雨落春独酌，窗竹灯寒夜对谈。\n石上精魂能阅世，欲寻前事兴方酣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄旧同游' AND p.poem_author = '李复';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送仁山主兼寄西堂园澄禅师', '陈师道', '宋代', '未仕宁论马少游，虚名非复韩潮州。\n祖师若问西来信，为说苍头与白头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送仁山主兼寄西堂园澄禅师' AND p.poem_author = '陈师道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('解语花·上元', '周邦彦', '宋代', '风消绛蜡，露浥红莲，灯市光相射。桂华流瓦。纤云散，耿耿素娥欲下。衣裳淡雅。看楚女纤腰一把。箫鼓喧，人影参差，满路飘香麝。\n因念都城放夜。望千门如昼，嬉笑游冶。钿车罗帕。相逢处，自有暗尘随马。年光是也。唯只见、旧情衰谢。清漏移，飞盖归来，从舞休歌罢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '解语花·上元' AND p.poem_author = '周邦彦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九月十一日疾小间夜赋二首 其一', '陆游', '宋代', '清夜房栊灯火微，此心病起更依依。空惊床下莎虫语，不见梁间巢燕归。\n\n苍砚有池残墨在，白头不栉乱书围。可怜未遽忘风月，犹梦华觞插羽飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九月十一日疾小间夜赋二首 其一' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题福清八景寿叶师相', '李云龙', '明代', '青鸾东归阿母老，三山飞入七闽道。瀛洲仙客骑云还，长啸山头拾瑶草。\n\n南极光芒接上台，帝师应谢赤松回。凭将池上黄金液，先上君王万寿杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题福清八景寿叶师相' AND p.poem_author = '李云龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('芙蓉五绝呈景仁 其二', '韩维', '宋代', '小沾清露细摇风，养得新花次第红。客至莫教樽酒燥，朝吟夕赏未知穷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '芙蓉五绝呈景仁 其二' AND p.poem_author = '韩维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('石屏歌为商丘先生作', '吴士玉', '清代', '群峰奔云涌座隅，下有烟艇浮江湖。是何淋漓足元气，得非米家海岳图。\n\n细看乃是浑成一片石，天然妙迹非人摹。昔闻巧匠斫山骨，未闻山水粉绘生石肤。\n\n若云造物作狡狯，却愁混沌凿死将何如。万里烟云藏咫尺，壁开天地超寰区。\n\n渔舟个个齐荡桨，烟波云岫聊相娱。我思米颠工画兼嗜石，整冠再拜以丈呼。\n\n石之嶙峋足以壮笔势，画之奔峭与石争盘纡。石癖画巧两不灭，画留石上永永成形模。\n\n君不见欧公当年石月屏，子美放歌穷虚无。又不见孤松溟濛石屏上，子瞻长句搜根株。\n\n今公兹屏亦奇绝，愧无大手如两苏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '石屏歌为商丘先生作' AND p.poem_author = '吴士玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('点绛唇·冰雪神人', '元好问', '元代', '冰雪神人，岁寒时节争初诞。照溪梅绽。秀岭孤松远。香雾氤氲，不放重帘卷。歌声缓。酒杯深劝。此会年年见。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '点绛唇·冰雪神人' AND p.poem_author = '元好问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟中杂咏二首 其一', '徐霖', '明代', '绿树坐黄鹂，青秧点白鹭。睡起倚船窗，知是江南路。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟中杂咏二首 其一' AND p.poem_author = '徐霖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读曲歌八十九首 其七十', '佚名', '隋代', '执手与欢别，欲去情不忍。馀光照已藩，坐见离日尽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读曲歌八十九首 其七十' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过涧歇 海棠', '曾廉', '清代', '天意。为海棠、尚肯两日留晴，不许风欺憔悴。倚苔砌。\n\n映得书窗更媚。是养花天气。约嘉客、比似红裙对酣醉。\n\n燕子疏帘隔断，怜香问谁替。风恣宜笑，思量贴云髻。\n\n何处红楼，三月春深，玉台妆罢，六幅云锦方垂地。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过涧歇 海棠' AND p.poem_author = '曾廉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归来二周岁', '白居易', '唐代', '归来二周岁，二岁似须臾。池藕重生叶，林鸦再引雏。 \n 时丰实仓廪，春暖葺庖厨。更作三年计，三年身健无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归来二周岁' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送戴生', '陶安', '明代', '姑孰亭前绿藻肥，会稽山上白云飞。四郊兵气频闻警，一榻灯光只梦归。\n\n舟子争潮喧熟路，海鱼修馔奉重闱。姚江在望浑非远，肯踏梭船访钓矶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送戴生' AND p.poem_author = '陶安';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题记事册', '范成大', '宋代', '划破虚空一剑闲，六根同转上头关。\n如今宴坐庵中事，政在凡夫道法间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题记事册' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋萍', '汪中', '清代', '寒流如镜碧烟和，贴贴青萍出涧阿。影动疏星秋欲曙，风回落木水生波。\n\n潜鱼坠散冲无数，古岸潮平聚更多。自是浮生易漂泊，不因霜露怨蹉跎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋萍' AND p.poem_author = '汪中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('弹广陵散', '耶律楚材', '元代', '居士闲弹止息时，胸中郁结了无遗。乐天若得嵇生意，未肯独吟秋思诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '弹广陵散' AND p.poem_author = '耶律楚材';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('记象入室事 其二', '严嵩', '明代', '猛象咆哮君合避，只须屏息坐帷中。汉舟几覆心无怖，记取程家主一翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '记象入室事 其二' AND p.poem_author = '严嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送刘长舆', '薛蕙', '明代', '刘子今年少，文章欻老成。青春动才调，总角已聪明。\n\n父党同交辈，前贤畏后生。翻然兼鲍照，不啻似阴铿。\n\n历代流传体，千秋著作名。词场予有托，他日尔横行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送刘长舆' AND p.poem_author = '薛蕙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凉风至', '陶益', '明代', '何处凉飙发，庭前落木知。初秋争淅沥，薄暮转凄其。\n\n感旧心千里，迎寒酒一卮。霜花摇未见，吹帽接疏篱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凉风至' AND p.poem_author = '陶益';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('安期岩', '苏学程', '明代', '花落猿啼削壁间，升真元迹渺难扳。白云封后无鸡犬，流水声中有佩环。\n\n草树不知蝉蜕去，烟霞长伴鹤胎间。飘飘玉舄知何处，且掇菖蒲学驻颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '安期岩' AND p.poem_author = '苏学程';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凝碧晚望', '李弥逊', '宋代', '秋来何必送将归，落日高台意自悲。\n一壑未容追法漫，三钟犹得饱支离。\n黄花对客如相笑，白发寻人似有期。\n时序不堪翻覆手，每逢佳处亦开眉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凝碧晚望' AND p.poem_author = '李弥逊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('回风波吊孔明先生', '萨都剌', '元代', '大江东流日夜白，已矣英雄不堪说。朔风挟雨过江来，犹向矶头溅腥血。\n\n汉家神气四海摇，奸雄贼子相贪饕。二龙雌雄尚未决，将军战骨如山高。\n\n先生谋略满怀抱，坐视狂尘不为扫。若非蜀主三顾贤，终只如龙卧南亩。\n\n仰天一出摧奸锋，纶巾羽扇生清风。许君义气肝胆裂，兵枢尽在掌握中。\n\n赤壁楼船满江夏，伏剑登坛唯叱咤。忠心耿耿天必从，烈火回风山亦赭。\n\n可怜一炬功未成，将星已坠西南营。力吹汉水灰未醒，呜呼天命何不平。\n\n伫立矶头盼吴越，感慨令人生白发。先生虽死遗表存，大义晶晶明日月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '回风波吊孔明先生' AND p.poem_author = '萨都剌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上林殿院次公 其九', '徐积', '宋代', '林氏家藏万帙书，五船便可当五车。别顾客舟施坐榻，更谋官舫作行厨。\n\n写时教子烘青竹，读处呼童捉蠹鱼。悔不早知都借取，终身挟策灌园蔬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上林殿院次公 其九' AND p.poem_author = '徐积';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('萤', '刘敞', '宋代', '翩翩岂自知，历历眩群飞。故作穿疏牖，时来鉴薄帷。\n\n助明清夜永，除害一身微。秋草隋宫路，茫茫旧赏非。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '萤' AND p.poem_author = '刘敞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏时事', '洪存恕', '近代', '到处横行闯将先，何图好古得灾偏。郑家带草无馀绿，邺架书芸尽化烟。\n\n谁为斯文忧扫地，居然大圣号齐天。腐儒章句知干禁，百卷丹黄自弃捐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏时事' AND p.poem_author = '洪存恕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西藏杂诗之将赴西藏宿成都', '王引', '当代', '舆图新入藏，驿路锦官城。山想岷峨外，湖连星宿平。\n\n有僧分显密，无肆卜阴晴。灯下观遗事，唐蕃本舅甥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西藏杂诗之将赴西藏宿成都' AND p.poem_author = '王引';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送神', '葛闳', '宋代', '丹霞飘渺海三峰，归去琼台第几重。\n仙骥一声风驭远，月明清露滴金松。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送神' AND p.poem_author = '葛闳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('茶公惠陋室吟忆旧，遂次其韵', '俞律', '近代', '杯空生尘久，室漏水浸膝。往事虽梦寐，记之可盈箧。\n\n人各有其天，天意有祸福。漫漫二十年，百哀不一乐。\n\n生死如草菅，思之肝肠裂。风雨江南归，文苑逢场入。\n\n春风偶一吹，秋雨常淅沥。青灯对残稿，旧事不堪述。\n\n倚枕不成眠，痛泪倾堤决。文章或不朽，老矣力难接。\n\n七十今有二，余生计无出。达者随世缘，闭目即安息。\n\n佛云四大空，神乎游八极。天上何所有，寒星与月日。\n\n知君正曲肱，病卧方力学。太息陋室吟，好诗称古拙。\n\n何当绍兴酒，与君长醉乐。南北东西天，日从何方出。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '茶公惠陋室吟忆旧，遂次其韵' AND p.poem_author = '俞律';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清明登胶山四首 其三', '安道', '清代', '莓苔称坐翠沾衣，对景无因问是非。幽谷藏春樵径没，古碑封藓字痕稀。\n\n人来绝顶双峰抱，云落平芜一鸟飞。咫尺家山游兴熟，那堪佳节更相违。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清明登胶山四首 其三' AND p.poem_author = '安道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜算子', '郭则沄', '清代', '眉萼月弯环，心絮云撩乱。误了前期又后期，筝柱参差雁。\n\n梅落子犹酸，莲拗丝难断。不是狂香入梦悭，夜夜秋心懒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜算子' AND p.poem_author = '郭则沄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('代送张仲明兵备宪副致政还楝庄二首 其二', '苏葵', '明代', '策马亨衢尽付天，冰清玉洁自家坚。邈从霄汉勾前业，刚与云霞结暮年。\n\n寄兴楝花看作始，盖身荷叶想依前。人间快意知谁在，七贵五侯徒管弦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '代送张仲明兵备宪副致政还楝庄二首 其二' AND p.poem_author = '苏葵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元日立春三绝', '秦观', '宋代', '此度春非草草回，美人休著剪刀催。\n直须残腊十分尽，始共新年一并来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元日立春三绝' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('招彦国仲登二子入社得欢字', '欧大任', '明代', '翩翩华盖啸双鸾，翠壁丹厓欲见难。社待陶公应肯入，坐无车胤不成欢。\n\n兰湖正拟同纫佩，蒲涧曾期共考槃。雪后东来一乘兴，扁舟无惜剡溪寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '招彦国仲登二子入社得欢字' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送别二首(1) 其二', '费墨娟', '清代', '日催槐影上帘旌，快整征衫趁晓晴。此去劝君休惜别，男儿所志在功名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送别二首(1) 其二' AND p.poem_author = '费墨娟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花 其五 倬盦得画扇，复叠韵书一词于金笺扇见诒。五叠前韵谢之', '姚华', '清代', '清韵连翩如集凤。笺称金华，似带琼楼冻。睡里呼婆春是梦。\n\n青芜又促东皇鞚。\n\n仙蝶何堪词意重。洒翰亲书，信使更番送。秉烛须游良夜共。\n\n晓钟渐裂群山缝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花 其五 倬盦得画扇，复叠韵书一词于金笺扇见诒。五叠前韵谢之' AND p.poem_author = '姚华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('缘识 其五', '赵炅', '宋代', '时流求法界，问取本真诠。了悟空皆寂，心明海月圆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '缘识 其五' AND p.poem_author = '赵炅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('罗隐宅', '许仲蔚', '宋代', '吟魂散何处，旧居荒可嗟。江山间白日，图籍落谁家。\n\n野烧寒煨■，春风暖自花。诗名蟠不得，埋没任桑麻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '罗隐宅' AND p.poem_author = '许仲蔚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庚戌下第就沈阳陈监掣洪绪聘出山海关用杜少陵秋兴八首韵 其八', '安吉', '清代', '奉天城廓自逶迤，荡荡平平远险陂。圣寿八旬调玉烛，欢呼万岁半金枝。\n\n怀人日下音书隔，去雁江南节序移。西望长安似乡国，茫茫海立复云垂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庚戌下第就沈阳陈监掣洪绪聘出山海关用杜少陵秋兴八首韵 其八' AND p.poem_author = '安吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏双白鹭（一作崔少府池鹭）', '雍陶', '唐代', '双鹭应怜水满池，风飘不动顶丝垂。立当青草人先见， \n 行榜白莲鱼未知。一足独拳寒雨里，数声相叫早秋时。 \n 林塘得尔须增价，况与诗家物色宜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏双白鹭（一作崔少府池鹭）' AND p.poem_author = '雍陶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('代书寄谈鍊师', '徐铉', '唐代', '朱山松桂翠边云，中有清虚小隐居。\n密养丹砂存正气，静披琼蕴育真文。\n埙篪金石心常在，圭组烟霞路自分。\n凭仗乡人传尺素，山前惊起白羊群。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '代书寄谈鍊师' AND p.poem_author = '徐铉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('武邑署中偶作舫屋诗以落之', '王元常', '清代', '屋也舟耶结此庐，得闲小憩在公余。志存作楫安天下，心拟乘槎入太虚。\n\n对雪欲移王子棹，焚香静玩米家书。亭轩小筑聊成趣，浮宅何妨且暂居。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '武邑署中偶作舫屋诗以落之' AND p.poem_author = '王元常';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('钱仲耕殿撰侍郎挽诗二首 其一', '杨万里', '宋代', '易髓三爻表，恩波九里强。贯珠程氏传，炊玉范家庄。\n\n荷橐中年紫，芸签到老香。不应踰耳顺，便返白云乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '钱仲耕殿撰侍郎挽诗二首 其一' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠张祜', '杜牧', '唐代', '诗韵一逢君，平生称所闻。粉毫唯画月，琼尺只裁云。 \n 黥阵人人慑，秋星历历分。数篇留别我，羞杀李将军。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠张祜' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陶侃惜谷', '司马光', '宋代', '陶侃尝出游，见人持一把未熟稻，侃问：“用此何为？”人云：“行道所见，聊取之耳。”侃大怒诘曰：“汝既不田，而戏贼人稻！”执而鞭之。是以百姓勤于农植，家给人足。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陶侃惜谷' AND p.poem_author = '司马光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('万年春·冬至阳生', '马钰', '元代', '冬至阳生，迎春拨雪黄芽好。人惊早。香如芝草。玉碾胜磨捣。神水烹煎，自是除阴耗。金童报。绝品珍宝。啜罢游蓬岛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '万年春·冬至阳生' AND p.poem_author = '马钰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雁媒', '郝经', '元代', '云衢眇飞鸿，往来解随阳。序当夜有所，次进朝有行。\n\n瀚海天山西，卵育岁为常。八月秋风高，雍雍共南翔。\n\n水国足汀洲，江湖多稻粱。晻霭带残芦，老岸青草长。\n\n哀鸣洞庭月，乱点潇湘霜。太和开冰天，北去颃穹苍。\n\n信禽法天运，断不为炎凉。偶为篝灯误，缚足离江乡。\n\n饮啄养为媒，朋俦总相忘。嗷嗷解愁人，乃反无愁肠。\n\n弋人见冥鸿，矰缴潜施张。置媒使号呼，投网来抢攘。\n\n奄忽一举尽，羽毛皆摧戕。厌然束缚去，又向云间望。\n\n嗟嗟罔民徒，诡计不可防。被获反为用，竭力如鬼伥。\n\n有信复无智，终自为身殃。误己更误人，不悟真可伤！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雁媒' AND p.poem_author = '郝经';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('分韵送孙从之司业使湖南得千字', '楼钥', '宋代', '夫君静而敏，人十已则千。\n读破万卷书，操笔思涌泉。\n古事与今事，一一探本源。\n蚤蜚场屋声，作吏志益坚。\n朅来上清班，汉庭谁在先。\n雍容行秘书，史馆躬椠铅。\n片言寤明主，立使登谏垣。\n拳拳忧国心，倾倒十三篇。\n司成天下选，归志已浩然。\n赤日送妻子，襆被寻谿船。\n诸生慕阳城，欲挽不得专。\n竟持湖南节，征袂何翩翩。\n忆昨忝同登，于今三十年。\n朝行喜相会，终恨非官联。\n请益殊未餍，匆匆启离筵。\n始以长官来，今以绣衣还。\n书生素安分，岂问却与前。\n第惟公辈流，自应留日边。\n德星聚南楚，予环当茹连。\n事体有关系，临岐欲无言。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '分韵送孙从之司业使湖南得千字' AND p.poem_author = '楼钥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王荆公', '罗大经', '宋代', '错认苍姬六典书，中原从此变萧疏。\n幅巾投老钟山日，辛苦区区活数鱼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王荆公' AND p.poem_author = '罗大经';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和沈进可检法秋夜饮客待月', '王之道', '宋代', '欲雨云容合，濒江水气浮。\n笑谈初入夜，灯火适逢秋。\n巧借三豪便，还成一醉谋。\n投琼酬木李，只使老夫羞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和沈进可检法秋夜饮客待月' AND p.poem_author = '王之道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜过吴江忆华终之', '吕寅伯', '宋代', '更深既尽烛，清气满山川。沙上风鸥聚，烟中霜草鲜。\n\n故人别何处，新月照孤眠。欲寄相思意，征鸿未可传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜过吴江忆华终之' AND p.poem_author = '吕寅伯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('老菊次时所性韵', '何基', '宋代', '独步东篱餐落菊，一幅乌纱漉浮玉。悠然谢客欲醉眠，懒拾枯枝炮脱粟。\n\n靖节先生骨已寒，回生何必须神丹。紫阳一字冠青史，名节恃此安如山。\n\n义熙一去知几变，金钿翠葆犹年年。我生因循颠已华，甚矣今年脱左车。\n\n嘲红弄绿少时态，岁晚相对惟寒花。雨荒深院黄金尽，谁谓颜色埋尘沙。\n\n高风雅致随遇见，帘外玉立横枝斜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '老菊次时所性韵' AND p.poem_author = '何基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄李忠定公', '郑昌龄', '宋代', '雅望三朝第一流，端如砥柱屹清秋。\n爱君炯炯无他志，许国堂堂不自谋。\n梦绕苍龙新阙角，凉生黄鹤旧楼头。\n中兴真主须真相，未雪双鸾耻未休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄李忠定公' AND p.poem_author = '郑昌龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜雨倏霁月色清朗起视天宇怅然有故人之想遂赋此奉呈娄君仲实为翌日游岩之约云', '邓雅', '明代', '向夕篝灯风雨声，中宵启户月华明。青天万里看无尽，旅馆三更睡不成。\n\n才薄岂堪明主用，交深长忆故人情。重岩细菊仙家酒，明日相期作伴行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜雨倏霁月色清朗起视天宇怅然有故人之想遂赋此奉呈娄君仲实为翌日游岩之约云' AND p.poem_author = '邓雅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('生张说', '洪亮吉', '清代', '才脱稿，已立碣，死姚崇算生张说。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '生张说' AND p.poem_author = '洪亮吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('履道书斋植竹甚茂用韵寄之十首 其七', '释德洪', '宋代', '虽住城隍寺，而无迎送烦。清风如有素，时复到南轩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '履道书斋植竹甚茂用韵寄之十首 其七' AND p.poem_author = '释德洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日寄舅弟贞宇', '张子翼', '明代', '历历秋旻隐翠屏，高轩何处隔江城。山斋寂寞天涵影，谷口清泠涧有声。\n\n听雨悬灯蛩自语，看云倚槛句还成。不嫌地僻回车马，肝鬲拚为信宿倾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日寄舅弟贞宇' AND p.poem_author = '张子翼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('濠梁杂咏六首 其三', '郭谏臣', '明代', '丰沛濠梁俱帝乡，尽凭三尺定封疆。本朝自用周官制，不似炎刘杂霸王。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '濠梁杂咏六首 其三' AND p.poem_author = '郭谏臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其七', '宋祁', '宋代', '再来戴公宅，客过孝王家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其七' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('强甫西上', '刘克庄', '宋代', '平进差贤似躁求，乃翁岂不为儿谋。\n今寒畯士难京秩，古子男邦亦小侯。\n翘馆讵宜频造请。孤山虽好勿淹留。\n谁言此老心如铁，临别无端作许愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '强甫西上' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宣城劝农', '吴泳', '宋代', '一分东作五分春，相汝耕夫更在勤。\n七月诗成种田法，庶人章作劝农文。\n祈蚕必使蚕如瓮，卜稼须观稼似云。\n老守别无新治行，只将丰岁答吾君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宣城劝农' AND p.poem_author = '吴泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三月十二日晚雨因取渊明诗微雨洗高林清飚矫', '滕岑', '宋代', '去岁所种竹，今岁望成林。\n竹萌犹未见，时节春已深。\n逮茲一雨润，犊角庶可寻。\n切勿轻剪馘，长养令萧森。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三月十二日晚雨因取渊明诗微雨洗高林清飚矫' AND p.poem_author = '滕岑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('端午贴子词 皇后阁五首 其五', '周麟之', '宋代', '剪就冰绡月影团，不须多羡女乘鸾。君王瑶札亲题处，一样蟾花点点丹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '端午贴子词 皇后阁五首 其五' AND p.poem_author = '周麟之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('见陈月观二首', '王奕', '宋代', '仲尼日月几曾昏，自古君师岂必存。\n水陆三千游圣域，风云万里望天阍。\n燕台接武何多隗，吴国孤骞未见云。\n观上又分明月影，漫漫长夜与谁论。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '见陈月观二首' AND p.poem_author = '王奕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢面', '谢枋得', '宋代', '丰年自古说来牟，四月麦熟胜秋收。天厨送食不待求，有面本饦吾何忧。\n\n安得化身为儿童，戏沙作面可报答。授记或为阿育王，请铸八万四千塔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢面' AND p.poem_author = '谢枋得';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('万太宜人七十寿诗', '尹台', '明代', '华发金钿映晚晖，自天纶诰下重闱。悬知赤绂牵新梦，不奈斑衣阻独归。\n\n七十宴开青雀至，八千路绕白云飞。题诗寄祝庭萱寿，瑞婺光芒动紫微。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '万太宜人七十寿诗' AND p.poem_author = '尹台';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风入松 次虞邵庵韵别友', '黄润玉', '明代', '先生和气似春酣，一见盍明簪。太平无讼霜台静，榕阴里、时与联骖。\n\n瓜代早装行李，兰熏重整朝衫。\n\n雨余山色净于蓝，秋燕更喃喃。凄凉风月阳关道，和离思、摹入诗缄。\n\n一曲骊歌人去，月明千里闽南。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风入松 次虞邵庵韵别友' AND p.poem_author = '黄润玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('幽居杂咏七十四首，自洪武十一年平原还家作也 其五十一', '孙蕡', '明代', '欲铸钟期未买金，断丝寒縆案头琴。虚堂月底弹清曲，别鹤离鸾自赏音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '幽居杂咏七十四首，自洪武十一年平原还家作也 其五十一' AND p.poem_author = '孙蕡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('会真诗四首 其二', '谢晋', '明代', '漙漙玉露湿庭莎，不觉凉侵袜底罗。自是夜深心胆怯，却嫌行处月明多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '会真诗四首 其二' AND p.poem_author = '谢晋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乱山乔木', '范天烈', '近代', '饱瞰春秋岁八千，参天老树自年年。风来干掩疑催雨，月白林空欲化烟。\n\n野鹤闲云踪不定，寒鸦古木色无边。谁为唤醒南柯梦，万壑森森一杜鹃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乱山乔木' AND p.poem_author = '范天烈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨中梦故山', '葛起耕', '宋代', '冥冥细雨湿江城，掩映书窗翳复明。\n倦客一中杯顿减，故乡千里初成。\n金华洞口羊惊起，石佛山头鹿伴行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨中梦故山' AND p.poem_author = '葛起耕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('邦瑞乞访亲因用其韵', '耶律楚材', '元代', '干戈扰扰战交侵，一纸安书值万金。凡子生还愁未解，萱堂仙去恨尤深。\n\n涕零倚木西风怨，肠断闻铃夜雨淋。养老送终真有憾，号天如割望云心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '邦瑞乞访亲因用其韵' AND p.poem_author = '耶律楚材';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('瑞鹧鸪 收家书', '马钰', '元代', '家书接得急开封。正值糊窗要避风。我愿难随你意去，道心不与俗心同。行功未满大千数，云水须游太一宫。传语儿孙并弟侄，后来书至＊墙', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瑞鹧鸪 收家书' AND p.poem_author = '马钰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饮许龙石学士园亭短述三首 其一', '孙承恩', '明代', '桂楫依沙渚，茅堂共酒卮。经年劳注想，此日慰深思。\n\n槛竹吟风细，流云渡苑迟。尘襟喜披豁，坐久欲忘辞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饮许龙石学士园亭短述三首 其一' AND p.poem_author = '孙承恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('芗林五十咏 其三十一 梨花原', '杨万里', '宋代', '禁火晓未暖，踏青昏恰归。何堪一原雪，将冷入春衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '芗林五十咏 其三十一 梨花原' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大将军宴会被命作诗', '陆云', '魏晋', '在昔奸臣。\n称乱紫微。\n神风潜骇。\n有赫兹威。\n灵旗树斾。\n如电斯挥。\n致天子届。\n于河之沂。\n有命冉集。\n皇舆凯归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大将军宴会被命作诗' AND p.poem_author = '陆云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('遇风出陆金陵道中次程及甫韵', '洪咨夔', '宋代', '留滞周南命使然，莫疑上水逆风船。乡山故故随人后，客月依依堕我前。\n\n半夜索樽同决计，五更回柂不成眠。笋舆吹面新凉入，须信封姨正自贤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '遇风出陆金陵道中次程及甫韵' AND p.poem_author = '洪咨夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戊辰春 其二', '倪元璐', '明代', '贵鹤贵其唳，厌蝉厌彼喧。喧经霜塞默，唳与天通言。\n\n贾传诚初学，留侯岂美媛。无将绛灌语，去与圮翁论。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戊辰春 其二' AND p.poem_author = '倪元璐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归去来集字十首，并引 其四', '苏轼', '宋代', '云岫不知远，巾车行复前。仆夫寻老木，童子引清泉。\n\n矫首独傲世，委心还乐天。农夫告春事，扶老向良田。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归去来集字十首，并引 其四' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵三首', '梅尧臣', '宋代', '恃险不能久，六朝今已亡。\n山形象龙虎，宫地牧牛羊。\n江上鸥无数，城中草自长。\n临流邀月饮，莫挂一毫芒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵三首' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄题沈逸人故居', '朱睦㮮', '明代', '修竹湘沅畔，会闻有避喧。叶香馀在户，翠影尚临轩。\n\n野日怅谁语，江云愁与繁。自君腾驾后，阒寂此丘樊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄题沈逸人故居' AND p.poem_author = '朱睦㮮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次绪山韵五首 其二', '杨爵', '明代', '双鹳飞来圜树梢，看他春到便衔巢。显庭常若俨宾际，幽世必须藉白茅。\n\n心果合天真浩浩，狂非作圣但嘐嘐。会教身世全无我，方寸才能免物交。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次绪山韵五首 其二' AND p.poem_author = '杨爵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送苏召叟秀才入蜀效宛陵先生体', '陆游', '宋代', '士勇赴知己，义重身固轻。\n尊公况有命，子得辞此行？结庐出门去，迢迢过蛮荆，泝江卜风色，入峡听猿声。\n万里一纸书，南寄孤雁征，山阴在何处？计子难为情。\n愿言早来归，邻曲当出迎。\n檥舟柯桥市，一榼手自倾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送苏召叟秀才入蜀效宛陵先生体' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨鬘', '易顺鼎', '清代', '玉{竹/氐}响动文窗锁。郎来故傍红鹦坐。贪看碧桃花。险些忘却他。\n\n梦嫌帘路窄。春影层层隔。侬自要销魂。嫩寒深闭门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨鬘' AND p.poem_author = '易顺鼎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李侍御墓', '殷奎', '明代', '李公读论语，探道悟渊微。政推守令最，名重谏诤司。\n\n生平信跌荡，之死气不衰。表树限樵牧，善政固在兹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李侍御墓' AND p.poem_author = '殷奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠林仰之迁南京国子监丞', '林光', '明代', '叉手东风月一更，我来君去最关情。天机转弼南都教，人事难逃月旦评。\n\n四海英豪频属望，八闽衣线念非轻。乡书首发他年解，谁道吾侪眼亦明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠林仰之迁南京国子监丞' AND p.poem_author = '林光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('海藏楼杂诗 其十二', '郑孝胥', '清代', '雨过云亦归，林气重不散。满月如帷灯，隐约出天半。\n\n须臾碧将合，粉彩发璀璨。银波渐流空，湿雾涨瀰漫。\n\n园林遂平沉，楼阁若隔岸。登台揽明镜，照胆不可玩。\n\n寒光来逼身，左右晃凌乱。凛然赴奔潮，露顶白虹贯。\n\n一凉遽至此，始有秋风叹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '海藏楼杂诗 其十二' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偕洪觉山登沙贝钓台次韵二首 其二', '庞嵩', '明代', '不见溪翁坐石年，钓台云暮眼空穿。持竿欲学任公子，志大无功漫费钱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偕洪觉山登沙贝钓台次韵二首 其二' AND p.poem_author = '庞嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郊庙歌辞。五郊乐章。肃和', '佚名', '唐代', '玄鸟司春，苍龙登岁。节物变柳，光风转蕙。 \n 瑶席降神，朱弦飨帝。诚备祝嘏，礼殚珪币。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郊庙歌辞。五郊乐章。肃和' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('牧牛昼睡图', '胡奎', '明代', '草软坡平午树凉，人牛此际两相忘。曾知亦有无眠者，马上鸡声满路霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '牧牛昼睡图' AND p.poem_author = '胡奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红九首 其七', '奕绘', '清代', '滚滚黄流，是禹迹、神功初奠。极远目、乱峰西北，潮头一线。\n\n燕赵河山多感慨，金元事业空交战。想平沙、毡帐竖黄旗，标行殿。\n\n七百载，风云变。古今事，波涛卷。剩长桥顽石，平拖如练。\n\n税局喧哗争过客，堤城嵲屼依村店。叹年时、骑马往来频，英雄倦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红九首 其七' AND p.poem_author = '奕绘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('慈云岭', '董嗣杲', '宋代', '叠叠流云步步苔，九霄紫气限蓬莱。\n后唐刻石初开路，南宋郊天别築台。\n慰眼江湖空岁月，伤心陵寝堕尘埃。\n桃花争趁春风老，又引游人一度来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '慈云岭' AND p.poem_author = '董嗣杲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重九偕衡甫少帆三游云巢', '许传霈', '清代', '满郭霜林唤野舲，芦花深处偶然停。无边木叶随时落，不断山光为我青。\n\n佳节何妨人淡菊，仙寰长许鸟听经。遨游三度忘知止，愿老前溪止止亭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重九偕衡甫少帆三游云巢' AND p.poem_author = '许传霈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题扇寄山西潘春谷子抑', '湛若水', '明代', '天南天北梦难通，春谷风同云谷风。舒卷乾坤一箑耳，莫教春信断来鸿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题扇寄山西潘春谷子抑' AND p.poem_author = '湛若水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹溪直院盛称起予草堂诗之善暇日览之多有可恨', '刘克庄', '宋代', '静院闭花时，沉沉昼漏移。偶然声出户，应是客围棋。\n\n夜寂推枰响，机深落子迟。恼禅天女去，入定老僧知。\n\n鹄至难传艺，莺啼许借枝。须臾分局势，何待烂柯为。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹溪直院盛称起予草堂诗之善暇日览之多有可恨' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('即事', '晁补之', '宋代', '半刺还为权刺史，朝衙不坐坐铃斋。\n按头通事通何事，昨夜东园芍药开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '即事' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄答曰庐诸子', '释函可', '明代', '书来知汝未曾离，竹杖麻鞋好护持。我罪已深衰更甚，不须翘足看松枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄答曰庐诸子' AND p.poem_author = '释函可';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('台阳八景', '谢家树', '清代', '上沃三春润，洋宽一望迷。风驯芳草浪，雨酿落花泥。\n\n司馌童携筥，忘机鸟集犁。西成先可庆，不辨地高低。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '台阳八景' AND p.poem_author = '谢家树';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚凉散策二首 其二', '杨万里', '宋代', '半点轻风泛柳丝，忽吹荷叶一时欹。芙蕖好处无人会，最是将开半落时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚凉散策二首 其二' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东楼落成二绝', '吴芾', '宋代', '荒郡城楼久已倾，我来聊复为经营。\n南楼已是增雄观，今日东楼又落成。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东楼落成二绝' AND p.poem_author = '吴芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七夕集何龙友宅', '李孙宸', '明代', '天阶坐七夕，银汉望虚无。雅会烦襟涤，新凉暑病苏。\n\n月斜蟾影澹，星返鹊桥孤。此夕相怜意，人间总未殊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七夕集何龙友宅' AND p.poem_author = '李孙宸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('放下庵即事三绝 其二', '范成大', '宋代', '病后天魔不战降，梦中千顷白鸥江。心空境寂声尘尽，却爱秋蝇扑纸窗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '放下庵即事三绝 其二' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('知宗送玉友酒', '王十朋', '宋代', '铃斋昼寝梦初醒，忽见双罂眼欲惊。谁送瓮头新玉友，人言天上老宗英。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '知宗送玉友酒' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵仲明举西郊别墅', '郭印', '宋代', '我闻修竹阴，清邃不受暑。\n安得十亩馀，其中创幽墅。\n日长惟鸟声，昼静无人语。\n习习来微风，萧萧堕寒雨。\n呼儿出柴扉，垂纶坐沙渚。\n斯志久未遂，世路今弥阻。\n新诗何起予，风味胜清醑。\n自怜拘一官，隐逸愧前古。\n好梦只林泉，覉踪犹粪土。\n岂能学贪夫，忘身徇圭组。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵仲明举西郊别墅' AND p.poem_author = '郭印';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('平谷秋兴六首 其一', '曾习经', '清代', '苌楚阿娜枝自摇，荒山无树著凌霄。惊风尽日吹骡铎，积雨连旬覆燕巢。\n\n此地旧馀边塞月，归心遥望海东潮。江南信美哀吾土，虚为羁旅赋大招。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '平谷秋兴六首 其一' AND p.poem_author = '曾习经';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋闺', '李孙宸', '明代', '金风披拂绣罗裳，吹我相思到异乡。不见铁衣辞雁塞，仍闻鼙鼓戍渔阳。\n\n合欢裛露开盈砌，促织惊寒鸣近床。最怪流黄机上月，秋来偏照瓦鸳鸯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋闺' AND p.poem_author = '李孙宸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('花朝二首 其二', '王季珠', '清代', '引我红愁却几株，放歌那说不关渠。花奴诗隶供闲遣，福分三生修到无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '花朝二首 其二' AND p.poem_author = '王季珠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵阎甥伯温池上八首 其二', '晁补之', '宋代', '昔吾卜城东，今吾卜城中。祇畏盗贼迫，安知廛市同。\n\n畚锸运渤海，操蛇应未穷。无乃遭此笑，君如北山翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵阎甥伯温池上八首 其二' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('定寨望洋', '陈玉衡', '清代', '三秋策杖卦山巅，一望重洋思渺然。作楫安澜如此日，乘风破浪是何年。\n\n氛消绝岛鱼游泳，气结全台象万千。门户而今开鹿港，依稀争看估人船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '定寨望洋' AND p.poem_author = '陈玉衡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蓟州', '白范', '明代', '西来山尽处，始见蓟州城。\n地拱三门峻，天回一面平。\n人烟多戍卒，市语杂番声。\n回首松亭道，秋风几日程。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蓟州' AND p.poem_author = '白范';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荡子从军', '欧必元', '明代', '飞扬出苏城，辛苦事幽并。拚尽英雄骨，输谁荡子名。\n\n但知谋国事，不复顾家声。藉甚图形阁，麒麟总未成。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荡子从军' AND p.poem_author = '欧必元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('伍长卿', '李孙宸', '明代', '长卿秉逸尚，妙龄事幽讨。灼彼春华姿，被服纨与缟。\n\n时援绿绮琴，一理清商操。中怀那可喻，含情欲谁告。\n\n申言属所欢，勖哉维此道。大音一以倡，颓风日以扫。\n\n人生易奄忽，长夜漫浩浩。千秋良在兹，胡宁但衰老。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '伍长卿' AND p.poem_author = '李孙宸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('近代杂歌 浔阳乐', '鲍令晖', '南北朝', '稽亭故人去。\n九里新人还。\n送一便迎两。\n无有暂时闲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '近代杂歌 浔阳乐' AND p.poem_author = '鲍令晖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠董明府迎侍四首 其二', '卢楠', '明代', '昊天列光景，清辉缅赤县。少微垂高云，婺彩明河甸。\n\n𦕈眇寰宇间，习习祥风煽。兹匪巨孝蒸，孰能拨灵变。\n\n回头语中州，大养非珍馔。持此金石开，会膺紫泥眷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠董明府迎侍四首 其二' AND p.poem_author = '卢楠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春晚五首', '曹勋', '宋代', '春过花飞不可寻，空余新叶翠光深。\n炉香袅袅轩窗静，时有珍禽啭好音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春晚五首' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题谢氏双溪阁', '郭祥正', '宋代', '谢家山下双溪阁，水远山深夏亦凉。霜练两条初合影，菱花一鉴泻馀光。\n\n樽罍日日邀宾客，仓廪年年富稻粱。更约诸孙勤问学，桂科将见绿衣郎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题谢氏双溪阁' AND p.poem_author = '郭祥正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('嘉州舟行至渝', '顾光旭', '清代', '纤月上青衣，迢迢春水肥。如何万里道，不借一帆归。\n\n夜静鱼龙卧，沙平雁惊飞。半江星斗外，疑是旧渔矶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '嘉州舟行至渝' AND p.poem_author = '顾光旭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '释简长', '宋代', '烟垒沉寒笛，霜空击怒雕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '释简长';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜寓舟中', '徐德辉', '宋代', '秋气清如水，推篷夜不眠。\n芦花新有雁，莎叶尚鸣蝉。\n断梦疑堪续，哀吟最可怜。\n渔童看月上，吹笛舵楼前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜寓舟中' AND p.poem_author = '徐德辉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('神泉海市居人谓重现日寇兵伍', '陈永正', '当代', '无尽时空驻此奇，云中广厦是耶非。不知沧海成田未，却幻金戈铁马驰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '神泉海市居人谓重现日寇兵伍' AND p.poem_author = '陈永正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐·题静仪张夫人百花卷子', '马叙伦', '近代', '璇闺罢咏。又写群芳影。染翠渲红生意迥。的是描生上乘。\n\n奇葩强半难名。劳他搜遍潮汀。偏少合欢一朵，为憎夫婿多情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐·题静仪张夫人百花卷子' AND p.poem_author = '马叙伦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过牛伏岭', '舒頔', '明代', '牛伏岭高高且远，崎岖羊肠路百转。\n仲冬跋涉汗流浆，每叹时危历艰险。\n阴厓惨惨生悲风，极目四顾山巃嵸。\n人生能着几两屐，踪迹不异无根蓬。\n我家居山南，别业寄山北。\n群凶势纵横，往返苦行役。\n山中天气温如春，绝壁遥见梅花新。\n梅花年年见春色，不见多少行路人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过牛伏岭' AND p.poem_author = '舒頔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂曲歌辞 其三 踏歌词', '谢偃', '唐代', '夜久星沈没，更深月影斜。裙轻才动佩，鬟薄不胜花。\n\n细风吹宝袂，轻露湿红纱。相看乐未已，兰灯照九华。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂曲歌辞 其三 踏歌词' AND p.poem_author = '谢偃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('定风波·宴李氏宅', '曾廉', '清代', '卷石为山斗水池。俨然湖上绿沦漪。昨夜吹箫声满院。\n\n相见。生绡如雪照花枝。\n\n荷叶苞羞持劝客。殽核。半红频果酒盈卮。雅会乘今宜笑乐。\n\n惊咢。西风又是授衣时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '定风波·宴李氏宅' AND p.poem_author = '曾廉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新菊', '陆游', '宋代', '老去流年不耐催，微霜又见菊花开。\n莫言冷落西风晚，也有飞飞小蝶来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新菊' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红 浣花草堂', '左锡嘉', '清代', '凭吊苍茫，衰草外、夕阳残堠。空留得、浣花诗老，草堂依旧。\n\n幕府十年栖息强，兵戈满地仓皇走。只乡愁、并入啼鹃，频骚首。\n\n花径外，春星瘦。茅屋底，秋风吼。叹词人漂泊，古今谁偶。\n\n忧国文章知己泪，倦游身世成都酒。甚而今、景仰说诗王，君知否。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红 浣花草堂' AND p.poem_author = '左锡嘉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('调笑令 白门雨夕有怀亚子', '林庚白', '近代', '无睡。无睡。又惹几多诗思。残钟一夜西楼。梦落吴淞晚秋。秋晚。\n\n秋晚。寒雨连江人远。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '调笑令 白门雨夕有怀亚子' AND p.poem_author = '林庚白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答何积中', '李流谦', '宋代', '先生古心寄玄漠，老松矫矫石凿凿。\n已欣净社得胜友，更枉高轩出奇作。\n山林轩冕无间然，造物从公意所便。\n决科纵未吞余子，著书亦足垂千年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答何积中' AND p.poem_author = '李流谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻邻家琵琶有感', '高启', '明代', '清唱合琵琶，当年碧玉家。\n弄残催酒急，抱重向灯斜。\n久别愁江树，重听隔院花。\n泪多思旧事，不是客天涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻邻家琵琶有感' AND p.poem_author = '高启';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄宇文判官', '岑参', '唐代', '西行殊未已，东望何时还。\n终日风与雪，连天沙复山。\n二年领公事，两度过阳关。\n相忆不可见，别来头已斑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄宇文判官' AND p.poem_author = '岑参';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高山寺', '憨山大师', '明代', '山城枕江流，梵刹云中起。\n钟鸣万户开，人在莲华里。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高山寺' AND p.poem_author = '憨山大师';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('漫书答唐观察四首 其二', '汤显祖', '明代', '县小河阳花遍开，金盘露冷醉人来。也知不厌山公启，解事长亏女秀才。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '漫书答唐观察四首 其二' AND p.poem_author = '汤显祖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄葛秋岩', '林景熙', '宋代', '吴地繁华半劫灰，故山秋远梦频回。\n琵琶亭老春风棹，桑落洲寒夜雨杯。\n岁月悠悠人几换，关河渺渺雁空来。\n酒酣欲寄登临眼，黄叶斜阳满废台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄葛秋岩' AND p.poem_author = '林景熙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浪淘沙 登阳明山有感', '陈逸云', '近代', '未觉雁鸣秋。已惹乡愁。斜风细雨过危楼。极目山川无限意，故国神游。\n\n壮志未曾休。事业何酬。笃行实践苦思筹。两鬓不辞添白发，誓复神州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浪淘沙 登阳明山有感' AND p.poem_author = '陈逸云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红·律转黄钟', '范飞', '宋代', '律转黄钟，尧蓂尚、零星一叶。人尽道、当年此日，诞生豪杰。我是君家门下士，三年屡献阳春雪。更此行、骑鹤上扬州，恩稠叠。君有子，文章伯。君有女，夸才色。更风流酝藉，东床佳客。婿祝长生儿祝寿，玉杯举罢金杯接。愿年年、长醉腊前梅，梅梢月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红·律转黄钟' AND p.poem_author = '范飞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金廷标秋英十二种 其九 金钱', '弘历', '清代', '买断三秋也足豪，不从四字不从刀。成诗已自闻卢肇，著论宁妨诮鲁褒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金廷标秋英十二种 其九 金钱' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洪州矮张歌', '杨维桢', '元代', '洪州矮张如矮瓠，大帛深衣没双屦。\n自言矮瓠不食酒，惟贮先天九宫数。\n早年侠气慕朱郭，轻财屡倒千金囊。\n得道人疑李士宁，滑稽时效东方朔。\n双瞳注射金蟆精，口如急雨倾建瓴。\n卒然一语中人隐，王公错愕面发赤。\n乌乎王谢误苍生，天下乌用尔宁馨。\n居中可乏汲长孺，使边甲用苏子卿。\n我本先皇赐进士，十年不调钱塘市。\n宦程那敢问雄飞，国法新蒙脱胥靡。\n西湖西，南山南，水华落日清而酣。\n画船载酒遁名姓，三尺长喙金人缄。\n嗟乎五鬼贼，三尸谗，矮瓠矮瓠无多谭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洪州矮张歌' AND p.poem_author = '杨维桢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书感', '陆游', '宋代', '老荷宽恩许退耕，丝毫无报亦何情。\n民贫乐岁尚艰食，道丧异端方肆行。\n党祸本从名辈出，弊端常向盛时生。\n古人骨冷青松下，谁起英魂与细评？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书感' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '李伯先', '宋代', '一门萃忠孝，竹锦写家声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '李伯先';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汴之水三章送淮南提刑李舍人', '梅尧臣', '宋代', '汴之水，入于泗，\n黄流清淮为一致。上牵下橹日夜来，\n千人同济兮万人利。利何谓，\n国之漕，商之货，\n实所寄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汴之水三章送淮南提刑李舍人' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元日书怀', '王炎', '宋代', '年光除日又元日，心事今吾非故吾。\n两板不须书郁垒，一杯亦强饮屠萝。\n添丁解事寻王母，内子伤时念老姑。\n欲报情深恩罔极，不终反哺愧林乌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元日书怀' AND p.poem_author = '王炎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四月三日初到临海县 其二', '李枝青', '清代', '前瞰灵江后枕屏，章安锁钥控东溟。楼台晴压蛮烟湿，城郭朝浮海气腥。\n\n潮上鱼虾罗市白，雨余笋蕨出林青。比邻吾土同风物，莫把华胥梦便醒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四月三日初到临海县 其二' AND p.poem_author = '李枝青';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄子戴京邑', '俞庆曾', '清代', '当时曾踏软红尘，茅店荒鸡送客轮。锦瑟年华东逝水，银釭风雨苦吟身。\n\n天涯杨柳初匀碧，江畔蘼芜已换春。不说相思深几许，平安聊慰远游人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄子戴京邑' AND p.poem_author = '俞庆曾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和寄问刘白　时梦得与乐天方舟西上。', '白居易', '唐代', '正与刘梦得，醉笑大开口。\n适值此诗来，欢喜君知否。\n遂令高卷幕，兼遣重添酒。\n起望会稽云，东南一回首。\n爱君金玉句，举世谁人有。\n功用随日新，资才本天授。\n吟哦不能散，自午将及酉。\n遂留梦得眠，匡床宿东牖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和寄问刘白　时梦得与乐天方舟西上。' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵答于谷山宗伯见怀四首 其四', '杨巍', '明代', '莫理城南汶水船，于今诸塞起狼烟。已知宵旰劳明主，不记仙曹侍从年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵答于谷山宗伯见怀四首 其四' AND p.poem_author = '杨巍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天二首 其二', '刘东父', '近代', '十载恩情怅别离，愁来怕写断肠诗。梦魂不到相思路，酒盏谁温絮语时。\n\n还劝我，与君期。来生鸳牒可相宜。春风吹遍蘼芜路，未抵愁心杀卷葹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天二首 其二' AND p.poem_author = '刘东父';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送汪进士以虚宰金华', '欧大任', '明代', '汪子少年才莫匹，奉对丹墀期第一。试令俄从通籍年，理人初遇分符日。\n\n浙西大邑瀫江涯，八咏楼前几万家。城临三洞山山雪，春过双溪树树花。\n\n子也蕲黄士，国宝荆州记。嘉鱼吴献臣，巴陵邓宗器。\n\n名世千秋表钜公，起家百里为循吏。何羡庞元蒋琬乎，召归可待锋车使。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送汪进士以虚宰金华' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和黄咏雩榄溪杂诗即用原韵 其三', '李洸', '近代', '忍读遗诗日几回，商声哀飒纸窗来。空降白刃输肝胆，荒冢黄花特地开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和黄咏雩榄溪杂诗即用原韵 其三' AND p.poem_author = '李洸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('对菊', '齐己', '唐代', '蝶醉风狂半折时，冷烟清露压离披。欲倾琥珀杯浮尔， \n 好把茱萸朵配伊。孔雀毛衣应者是，凤凰金翠更无之。 \n 何因栽向僧园里，门外重阳过不知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '对菊' AND p.poem_author = '齐己';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春晚书村落闲事', '陆游', '宋代', '千古会稽城，闾阎乐太平。\n丰年观米价，霁色听禽声。\n俗俭憎浮侈，民淳力钓耕。\n豳诗有七月，字字要躬行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春晚书村落闲事' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苏幕遮·莫端身', '王哲', '元代', '莫端身，休打坐。摆髓摇筋，嘘咽稠粘唾。外用修持无应和。赢得劳神，枉了空摧挫。要行行，如卧卧。只把心头，一点须猜破。返照回光亲看过。五色霞光，覆焘珠明颗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苏幕遮·莫端身' AND p.poem_author = '王哲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('幽趣十二首 其二', '郑刚中', '宋代', '幽趣无人会，闲居趣自成。孤舟横水静，宿鹭入烟明。\n\n风絮低还起，苔钱断复生。小门无客款，睡犬不闻声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '幽趣十二首 其二' AND p.poem_author = '郑刚中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏八仙 栉发', '韦骧', '宋代', '搔首意不满，聊凭象栉功。高情唯自适，岂恤鬓如蓬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏八仙 栉发' AND p.poem_author = '韦骧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大朝门同午楼复建百官朝贺二首 其二', '胡直', '明代', '轩阁看仪凤，尧阶俯濯龙。宸聪从此达，猎疏拟谁封。\n\n燎火光云汉，珂声接曙钟。定应门下省，承问独从容。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大朝门同午楼复建百官朝贺二首 其二' AND p.poem_author = '胡直';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同梁思伯讯陈贵吾卧病', '黎民表', '明代', '怪尔经旬卧，疏灯对影孤。药曾因病识，身岂为名拘。\n\n叹逝从星鬓，安贫任泽癯。莫愁过往绝，人自访潜夫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同梁思伯讯陈贵吾卧病' AND p.poem_author = '黎民表';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('用韵答廖梅南二守 其一', '区越', '明代', '春棹破江清，春山叠送迎。暮滩遗宿鹭，寒柳带迁莺。\n\n蓬鬓已含雪，尘冠未解缨。时和思赈贷，朝夕寸心萦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '用韵答廖梅南二守 其一' AND p.poem_author = '区越';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送别戴肩吾', '曹于汴', '明代', '七月凉风来，雨罢蔬苗广。戴子访吾庐，陇畔谈今曩。\n\n不道生计微，但询学问长。手持李翁言，作圣示吾往。\n\n珠玉挥四壁，坐玩襟期爽。送子远行游，归视吾禾穰。\n\n子行怀自佳，天宇秋正敞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送别戴肩吾' AND p.poem_author = '曹于汴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠天台老樊', '白玉蟾', '宋代', '别后俄经几许春，相逢一笑挹南薰。灰头土面无人识，木食草衣嫌俗纷。\n\n在浙之台今已久，姓樊名邴寂无闻。为君传此新诗去，寄与铅山赵翠云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠天台老樊' AND p.poem_author = '白玉蟾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('应尽须尽吟 其七', '顾允成', '明代', '应尽须尽，非尽亦尽。太极无极，何始何竟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '应尽须尽吟 其七' AND p.poem_author = '顾允成';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚步', '陆游', '宋代', '晚步清溪上，微阴忽快晴。\n鸦栖先小泊，鱼暖已群行。\n药饵扶垂老，耕桑乐太平。\n非关恋乡社。\n久客倦遐征。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚步' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山行晚归', '释善珍', '宋代', '药径入云林，晚晴扶杖吟。照泥星复雨，经朔月犹阴。\n\n树折怜巢覆，泉清见叶沈。爱闲自如此，不是学灰心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山行晚归' AND p.poem_author = '释善珍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('经历司暮春即事', '萨都剌', '元代', '霞飞海燕拂帘过，风卷鱼鳞剪绿波。閒倚石阑数春事，满池红雨落花多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '经历司暮春即事' AND p.poem_author = '萨都剌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大恒招集南屏分韵', '全祖望', '清代', '试看南山色，连朝倍老苍。青霜封曲磴，黄叶下空廊。\n\n旅客游方倦，寒虫蛰渐忙。昨闻开酒戒，来过远公房。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大恒招集南屏分韵' AND p.poem_author = '全祖望';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦大人', '张鹏翮', '清代', '亲老时萦念，身安不厌贫。青云长作客，白发未归人。\n\n夜雨和愁落，家山入梦频。故园归未得，西望正伤神。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梦大人' AND p.poem_author = '张鹏翮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉题付珠二首 其一', '刘克庄', '宋代', '象罔得来还失了，寒斋拾去閟藏之。临行此物犹难忍，不付他人付二儿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉题付珠二首 其一' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗六首 其五', '徐贲', '元代', '飞鸿渡衡湘，游戏寒江浔。携群复挈侣，浩荡同浮沉。\n\n一鸿忽失意，矰缴乃见侵。众鸿不忍去，徘徊发哀音。\n\n悲风何所恶，积水而又深。欲渡那不得，徒存恤鸿心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗六首 其五' AND p.poem_author = '徐贲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和沈述之赠权干诗', '王质', '宋代', '江枫不敌寸心丹，何待霜雄吏自寒。满眼空空无一佛，举头在在有三官。\n\n毛端解运三千界，脚底常飞九万抟。凫茈馀根挑欲尽，莫忧鲁巷有颜箪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和沈述之赠权干诗' AND p.poem_author = '王质';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬方司法一首', '释居简', '宋代', '五字堪呈佛，投珍颇惜哉。汤汤大雅后，衮衮建安来。\n\n逸思属万象，空庭步几回。海陵藕花幕，已为故人开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬方司法一首' AND p.poem_author = '释居简';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪次大涧', '郭祥正', '宋代', '连山接野冷光铺，望望村烟问道涂。不似在家蓬户闭，妻儿欢笑拥红炉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪次大涧' AND p.poem_author = '郭祥正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七夕感旧 其一', '僧果玲', '近代', '袈裟半袒坐层檐，仰看星桥香懒添。猛忆那年今夜月，如花人对读楞严。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七夕感旧 其一' AND p.poem_author = '僧果玲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八归 中秋', '陈永正', '当代', '当秋露重，横空河淡，堤外璧月低挂。茫茫水影愁空阔，还见乱乌惊树，雪浪连野。\n\n恰似暮潮拦海至，怯百幅、云帆都卸。怀故宇、冷泪如波，悄悄入怀泻。\n\n应念天涯鼓角，世间灯火，几日西风楼榭。隔帘难见，但闻微叹，那管容华轻谢。\n\n问年年此际，达曙谁同美清夜。还休倩、断翰零羽，再度关山，相思无处写。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八归 中秋' AND p.poem_author = '陈永正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('承坡山东郊之约借马日昃不至', '黄衷', '明代', '东郊雨后更芳华，出郭无过二里赊。石径尘收凡界远，绳枢星散野桥斜。\n\n闲情未少青林寺，并辔何曾白鼻騧。日夕有怀空徙倚，寂寥无奈瀼西家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '承坡山东郊之约借马日昃不至' AND p.poem_author = '黄衷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('经古战场', '徐熥', '明代', '萧条残垒不胜悲，此地曾经几乱离。恨血尚馀春草里，游魂多出夕阳时。\n\n潇潇寒雨闻刁斗，漠漠阴云见羽旗。满路干戈愁转战，胡笳休向马头吹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '经古战场' AND p.poem_author = '徐熥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满庭芳', '陈晔', '宋代', '翠竹阴团，绿荷乡嫩，朝来和气盈盈。薰风楼阁，玉燕梦初成。便有功名壮志，持符节，麟虎频。更归来后，挂冠神武，四海□高名。 \n 今年，方八十，莱衣舞处，岨拜霞觥。想笙歌递奏，鼎沸欢声。何用渠渠颂祝，自应合、福禄安荣。丹台上，玉清山籍，金字注长生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满庭芳' AND p.poem_author = '陈晔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送刘克柔尚宝祭告南行', '罗钦顺', '明代', '朱函分捧内廷香，旆指西南驿路长。将祀有诚宜受福，登高能赋更飞觞。\n\n鹤楼晚照熏残席，牛渚春潮接故乡。须忆明良千载遇，昼游虽乐未容荒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送刘克柔尚宝祭告南行' AND p.poem_author = '罗钦顺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('通州雨夜寄孙中叔', '郑獬', '宋代', '黑雨喷薄阴云驱，昏林号风秋声粗。海气熏煮怒不泄，彭彭十月推雷车。\n\n湿衣悯默瞠无睡，起对樽酒谁为娱。此心岂复有双羽，一夜飞去不可拘。\n\n昔与子同入京师，借屋共寄西城庐。爱我议论有可采，携草就我誇染濡。\n\n鍊出五色补天漏，拈笔蘸墨纵横涂。子云朋友当如是，脱然意快如狞驹。\n\n京师天子之所宅，楼殿堆叠骑天衢。瓦光流碧滑欲走，缋画颠倒横相舁。\n\n东风薰浓一千里，黄蜂蝴蝶飞蘧蘧。高楼张旗斗煮酒，沉香满榼金真珠。\n\n玉盆一饮醉不醒，落花满衫行相扶。未几子去游西洛，嗟我出门独骑驴。\n\n晚落尘埃两袖泪，望子不见风吹裾。三月殿前试不中，青冥失计游五湖。\n\n抚剑东南看沧海，大江正值秋风初。我疑海神怒天热，直欲上薄东日乌。\n\n乾坤顿撼壮人意，揭竿便欲寻狂奴。九月归来已霜蚤，肥膏紫蟹溶金酥。\n\n南窗灯火夜可喜，箧中卷册聊铺舒。读倦抱膝一吐气，契阔各在天一隅。\n\n相别于今二百日，飞雁南来无北书。游从欢喜似旧否，洛下为学安稳无。\n\n虽然贫窘少倚赖，空肠慎勿多悲吁。圣贤独立以待用，提出日月还唐虞。\n\n天地当中贯一柱，孟子所谓大丈夫。躁儿跳跃不足数，插翅强欲飞蟾蜍。\n\n纵子不遇乃至死，勉之学为荀杨徒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '通州雨夜寄孙中叔' AND p.poem_author = '郑獬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送王考功江东漕', '魏了翁', '宋代', '分部设将漕，黊旒寄聪明。\n直须撼山岳，亡但采畸赢。\n而况江以东，襟淮翼吴荆。\n民力九十空，所恃人为城。\n南宫辍望郎，方输饷连营。\n荧煌鹊锦袍，明日趋遐征。\n阳春脚未到，淑气先流莺。\n向来嵇中散，仅试薶九京。\n阿兄亦未究，有书今在楹。\n驱车踏前轨，若木以为程。\n千里隔香案，洗目观澄清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送王考功江东漕' AND p.poem_author = '魏了翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('探春慢 寓楼对雪，颇动羁愁。季刚次韵先成此解，邀余同赋', '汪东', '清代', '岁晚登楼，寒深拥几，羁怀零乱无序。风剪琼瑶，云昏天地，顿觉销沈平楚。\n\n南雁音书少，但梦趁、江乡归橹。最怜笠泽苍茫，樵青心事谁付。\n\n旧著烟蓑在否。甚锁却松筠，空闭柴户。庾信生涯，梁园宾客，愁动黄昏钟鼓。\n\n况只萧条极，似阴积、龙沙深处。赖有天工妆点，梨花千树。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '探春慢 寓楼对雪，颇动羁愁。季刚次韵先成此解，邀余同赋' AND p.poem_author = '汪东';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蔡玑先铉升携过东园看菊作 其二', '屈大均', '明代', '江左重来日，萧条益怆神。黄花犹有汝，白首更无人。\n\n意气期之子，文章托此身。溪流如有意，曲曲入西邻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蔡玑先铉升携过东园看菊作 其二' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西原晚望', '白居易', '唐代', '花菊引闲行，行上西原路。原上晚无人，因高聊四顾。 \n 南阡有烟火，北陌连墟墓。村邻何萧疏，近者犹百步。 \n 吾庐在其下，寂寞风日暮。门外转枯蓬，篱根伏寒兔。 \n 故园汴水上，离乱不堪去。近岁始移家，飘然此村住。 \n 新屋五六间，古槐八九树。便是衰病身，此生终老处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西原晚望' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('已亥杂诗 232', '龚自珍', '清代', '诗谶吾生信有之，预怜夜雨闭门时。\n三更忽轸哀鸿思，九月无襦淮水湄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '已亥杂诗 232' AND p.poem_author = '龚自珍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('龙泉李宗儒师儒兄弟槐阴书院', '周必大', '宋代', '君不见汉京辟雍载黄图，博士直舍三千区。\n分行数百曰槐市，下有诸生讲唐虞。\n又不见本朝肇启迩英阁，稽古隆儒号经幄。\n西清枝翠似交舞，日暖花黄时细落。\n君家欣慕名书斋，伯仲方将与计偕。\n桥门且陪亿万计，朝路终驰十二街。\n义郴文章妙天下，引喻牛行相君舍。\n勉君植德企前修，他日儿孙攀逸驾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '龙泉李宗儒师儒兄弟槐阴书院' AND p.poem_author = '周必大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题湘君图', '高启', '明代', '怅望南巡竟不还，泪和湘雨暮斑斑。\n须知竹死愁方尽，莫恨秦人鞭赭山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题湘君图' AND p.poem_author = '高启';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花 秋衾', '周贻繁', '清代', '红隐芙蓉香欲透。叠处层层，巧制夸金绣。薄薄吴棉轻里就。\n\n嫩寒恰称清秋候。\n\n小病连朝如殢酒。攲枕相依，蝶梦伶俜瘦。记得残春风雨后。\n\n惜花长是抛难骤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花 秋衾' AND p.poem_author = '周贻繁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阮朗归', '张辑', '宋代', '孤鸿遥下夕阳寒。秋清怀抱宽。篱根香满菊金团。\n\n客中邀客看。\n\n呼浊酒，共清欢。五弦随意弹。西窗仍见好溪山。几年谁倚栏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阮朗归' AND p.poem_author = '张辑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梁思伯过洲上', '欧大任', '明代', '三径蓬蒿长，谁寻仲蔚门。箪瓢忘晏设，文史入宵言。\n\n散帙或焚蒳，钓鱼时放䑳。问津人罕到，不必记桃源。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梁思伯过洲上' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题卧屏十八花 黄菊', '葛立方', '宋代', '秋入重阳气倍清，东篱采菊眼偏明。杯中要作茱萸伴，不是湘累餐落英。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题卧屏十八花 黄菊' AND p.poem_author = '葛立方';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庆郑敏善先生年八十应诏冠带', '黄仲昭', '明代', '年跻八秩未龙钟，又沐清时宠渥隆。华发谩添乌帽雪，酡颜不藉锦衣红。\n\n已看敬老循周典，还见优贤有汉风。况遇圣明弘治日，蒲轮早晚召申公。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庆郑敏善先生年八十应诏冠带' AND p.poem_author = '黄仲昭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古七十六首 其四十四', '释士圭', '宋代', '睦州只爱锥头利，这僧不见凿头方。直饶转得百千藏，这般供养也寻常。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古七十六首 其四十四' AND p.poem_author = '释士圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('广雅尚书招同姚园探梅', '郑孝胥', '清代', '看遍官梅爱野梅，自麾驺从踏莓苔。入春风色连林觉，过雨山园一半开。\n\n赏会未妨饶胜事，忧勤终是靳深杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '广雅尚书招同姚园探梅' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠天台郑道士', '韩淲', '宋代', '霞杯为奏阮咸曲，怅望十年湖水烟。闻过东嘉看雁荡，野云留宿话翛然。\n\n谭诗忽见蒋云出，今去洞庭衡岳前。能说鍊师神不老，识全元是赤城仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠天台郑道士' AND p.poem_author = '韩淲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登忠勤楼听久孚贺架阁弹琴', '汪广洋', '明代', '画栋栖朝霞，层檐宿秋雾。\n振衣坐前楹，援琴写中素。\n幽泉鸣涧深，落花荡春莫。\n油然闻至音，令人起遐慕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登忠勤楼听久孚贺架阁弹琴' AND p.poem_author = '汪广洋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('翠蛟亭', '金坚', '宋代', '怒猊抉石骥奔泉，谁挽河流下九天。\n倾泻琼珠三万斛，从师乞作买山钱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '翠蛟亭' AND p.poem_author = '金坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉真仙人词', '李白', '唐代', '玉真之仙人，时往太华峰。\n清晨鸣天鼓，飙欻腾双龙。\n弄电不辍手，行云本无踪。\n几时入少室，王母应相逢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉真仙人词' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('唐多令·人物盛乾淳', '魏了翁', '宋代', '人物盛乾淳，东嘉最得人。费江山、几许精神。我已后时犹遍识，君子子、又相亲。 \n 秋入塞垣新。风寒上醉痕。万百般、倚靠苍旻。只愿诸贤长寿健，容老我、看闲身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '唐多令·人物盛乾淳' AND p.poem_author = '魏了翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赵季茂通判惠诗走笔奉和十篇', '岳珂', '宋代', '天巧与天宜，雕锼焉用诗。\n冥鸿吾自爱，隐豹彼何知。\n牧笛方堪听，胡笳不奈吹。\n伤时烛之武，老矣不能为。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赵季茂通判惠诗走笔奉和十篇' AND p.poem_author = '岳珂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('己卯十月五日予入燕狱今三十有六旬感兴一首', '文天祥', '宋代', '石晋旧燕赵，钟仪新楚囚。\n山河千古痛，风雨一年周。\n过雁催人老，寒花送客愁。\n卷帘云满座，抱膝意悠悠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '己卯十月五日予入燕狱今三十有六旬感兴一首' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙', '蔡淑萍', '当代', '几许事儿忙了，悠闲好对孤灯。瓶中栀子送芳馨。\n\n旧书重捡读，字字有馀情。\n\n最喜旷怀高抱，还吟句丽词清。幽思远绪漫回萦。\n\n披衣推户牖，星朗夜天清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙' AND p.poem_author = '蔡淑萍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄陈县尹可斋', '郑真', '明代', '烂柯仙客思翩翩，献赋曾闻近御筵。鸾诰香浮朱印湿，鹓班光映赭袍鲜。\n\n生逢明圣焦劳日，寿介慈亲喜惧年。色养望遥千里道，忠心誓答九重天。\n\n化覃海邑声威肃，名动枢廷礼貌专。山市春深闻促仗，官衙昼静听鸣弦。\n\n东风柳影青丝扬，长日萱花锦绣妍。潘岳岂能长作县，陶潜未可赋归田。\n\n囊中诗帙寻常看，肘后医方次第编。尚想轩居新画幛，依依情动白云篇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄陈县尹可斋' AND p.poem_author = '郑真';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('经金绳废寺', '戴良', '明代', '寂寞唐朝寺，频年客到稀。\n空山孤殿在，荒径一僧归。\n苔色骄秋雨，松声振夕褷。\n惊乌初有托，近亦出林飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '经金绳废寺' AND p.poem_author = '戴良';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南湖二亭落成各书长句一首 其一 野芳', '张镃', '宋代', '望处阴云纵复横，落梅那更两关情。清愁入梦时飞蝶，远树和烟欲啭莺。\n\n多病半春诗债满，经旬无客酒缘轻。湖亭记取初成日，正是菖蒲斫水生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南湖二亭落成各书长句一首 其一 野芳' AND p.poem_author = '张镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('斗湖道人诗', '杨士奇', '明代', '家临斗湖滨，门对斗湖上。明镜影香台，文波绣仙氅。\n\n诵经无辍口，谭道若指掌。为霖从潜虬，飞符驱魍魉。\n\n止水涵湛然，可以喻心想。一谢湖边人，终年罢来往。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '斗湖道人诗' AND p.poem_author = '杨士奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠别王十七管记', '高适', '唐代', '故交吾未测，薄宦空年岁。晚节踪曩贤，雄词冠当世。 \n堂中皆食客，门外多酒债。产业曾未言，衣裘与人敝。 \n飘飖戎幕下，出入关山际。转战轻壮心，立谈有边计。 \n云沙自回合，天海空迢递。星高汉将骄，月盛胡兵锐。 \n沙深冷陉断，雪暗辽阳闭。亦谓扫欃枪，旋惊陷蜂虿。 \n归旌告东捷，斗骑传西败。遥飞绝汉书，已筑长安第。\n画龙俱在叶，宠鹤先居卫。勿辞部曲勋，不藉将军势。 \n相逢季冬月，怅望穷海裔。折剑留赠人，严装遂云迈。 \n我行将悠缅，及此还羁滞。曾非济代谋，且有临深诫。 \n随波混清浊，与物同丑丽。眇忆青岩栖，宁忘褐衣拜。 \n自言爱水石，本欲亲兰蕙。何意薄松筠，翻然重菅蒯。 \n恒深取与分，孰慢平生契。款曲鸡黍期，酸辛别离袂。 \n逢时愧名节，遇坎悲沦替。适赵非解纷，游燕往无说。 \n浩歌方振荡，逸翮思凌励。倏若异鹏抟，吾当学蝉蜕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠别王十七管记' AND p.poem_author = '高适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('走笔谢张功父送似酴醾', '杨万里', '宋代', '西湖野僧誇藏冰，半年化作真水精。南湖诗人笑渠拙，不如侬家解乾雪。\n\n藏冰窨子山之幽，镵透九地山鬼愁。侬家藏雪有妙手，分明晒在翡翠楼。\n\n向来巽二拉滕六，玉妃夜投玉川屋。剪水作花吹朔风，揉云为粉散寒空。\n\n醉挥两袖拂银汉，梢头万斛冷不融。琼田挈月拾翠羽，砌成重楼天半许。\n\n盘作青蛟吐绿雾，乱飘六出薰沉炷。人间雪脆那可藏，天上雪落何曾香。\n\n三月尽头四月首，南湖香雪今谁有，分似诚斋老诗叟。\n\n碎挼玉花泛春酒，一饮一石更五斗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '走笔谢张功父送似酴醾' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('社鼓', '毕仲游', '宋代', '社鼓鼕鼕南北村，老人相倚话柴门。自从嘉祐初年后，直至元丰有稻孙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '社鼓' AND p.poem_author = '毕仲游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日杂诗 其六', '温倩华', '近代', '柳烟分绿上眉头，水皱山颦不自由。已是閒愁愁未了，又因风雨替花愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日杂诗 其六' AND p.poem_author = '温倩华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('相如驷马桥', '王绂', '明代', '相如辞赋拟风骚，浪迹临邛逸气飘。犊鼻岂应亲涤器，驷车直欲预题桥。\n\n才名当世黄金重，志愿凌云碧汉遥。富贵如何才满意，白头吟里恨偏饶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '相如驷马桥' AND p.poem_author = '王绂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别绪', '韩偓', '唐代', '别绪静愔愔，牵愁暗入心。已回花渚棹，悔听酒垆琴。 \n 菊露凄罗幕，梨霜恻锦衾。此生终独宿，到死誓相寻。 \n 月好知何计，歌阑叹不禁。山巅更高处，忆上上头吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别绪' AND p.poem_author = '韩偓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪狮儿 本意', '陈维崧', '清代', '雕霜捏粉，作西域、万里狻猊，攫拿爪踞。侧脑平芜，猛气骁腾何怒。\n\n奔犀骇虎。更何论、田间狡兔。似鲍老、装成假面，筵前决赌。\n\n道上儿童戏汝。算冰澌雪尽，愁伊无据。恰遇狮王，微笑掷花而语。\n\n明驼洛下，费几许、铜山才铸。今何处。一样荒烟细雨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪狮儿 本意' AND p.poem_author = '陈维崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('用李廷琼寓中都口号韵三首 其二', '郑真', '明代', '锦绣河山绕帝京，南来为客最多情。芸编慢忆三千牍，桂籍空惭第一名。\n\n燕寝声传城柝近，魫窗凉透水云轻。知君正得青春乐，有约清樽对月倾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '用李廷琼寓中都口号韵三首 其二' AND p.poem_author = '郑真';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荆树分阴', '吴宣', '明代', '荆花竟谁授，解复人心初。如何七尺躯，翻令百行疏。\n\n气聚天始完，流深海不墟。于兹竟莫悟，泣下收吾书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荆树分阴' AND p.poem_author = '吴宣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次静凤中秋薄阴韵', '傅义', '当代', '岁岁今宵月，何为分外圆？岂关多粉饰，竟可胜天然？\n\n玉洁知谁及，环游可自便？高明羡骚裔，别有梦中天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次静凤中秋薄阴韵' AND p.poem_author = '傅义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游燕喜次韵', '李邦义', '明代', '湟川山水旧传名，暇日来游燕喜亭。细扪萝藤寻古刹，徐穿岩洞觅仙灵。\n\n卧龙故址云常白，梦得遗墟草漫青。千载风流人不见，惟闻山下水泠泠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游燕喜次韵' AND p.poem_author = '李邦义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('齐世家', '李觏', '宋代', '莫以荒淫便责君，大都危乱为无臣。若教管仲身长在，何患夫人更六人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '齐世家' AND p.poem_author = '李觏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏日感怀寄所知', '刘得仁', '唐代', '了了见岐路，欲行难负心。趋时不圆转，自古易湮沉。 \n 日正林方合，蜩鸣夏已深。中郎今远在，谁识爨桐音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏日感怀寄所知' AND p.poem_author = '刘得仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('君道篇', '胡奎', '明代', '君道天广大，王言出如纶。雨露及草木，万物皆阳春。\n\n九重坐南面，四海奉一人。禹稷犹已溺，唐虞视同仁。\n\n华盖当中天，列星环北辰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '君道篇' AND p.poem_author = '胡奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏玉韘', '弘历', '清代', '牙角徒传古，璆琳复见兹。虚中离象卦，圆外月盈规。\n\n讵止佩环用，兼成弓矢资。谁能连命中，差不愧瑰奇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏玉韘' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('演雅十章', '张至龙', '宋代', '蚕饱办丝课，蜂忙供蜜工。\n役役为人劳，衣食还自空。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '演雅十章' AND p.poem_author = '张至龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春闺八首 其五', '郭之奇', '明代', '飞蓬辞膏沐，无复向妆谋。卉木犹春好，妾鬓独惊秋。\n\n鬒云终何似，已当吟白头。谁怜拥髻泣，愁绝自登楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春闺八首 其五' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自题渔舟写真二首 其二', '袁世凯', '清代', '百年心事总悠悠，壮志当时苦未酬。野老胸中负兵甲，钓翁眼底小王侯。\n\n思量天下无磐石，叹息神州变缺瓯。散发天涯从此去，烟蓑雨笠一渔舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自题渔舟写真二首 其二' AND p.poem_author = '袁世凯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('唐磐石五世兄话别 其一', '黄公辅', '明代', '袂把天涯喜欲狂，且抛尘事共相将。子西遮莫前身是，彭蠡堪誇逸兴长。\n\n聒聒鸠声侵客坐，霏霏梅雨洒离肠。淡交不问弹冯铗，赖有南薰送远航。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '唐磐石五世兄话别 其一' AND p.poem_author = '黄公辅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乙老六十九岁生日祝词 其三', '陈曾寿', '清代', '敝帽欹徐整，深衣绝屡缝。外形从躐蹋，自哂托龙钟。\n\n雾豹深冥见，云龙合漠从。卿容晬书气，天语肖高宗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乙老六十九岁生日祝词 其三' AND p.poem_author = '陈曾寿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('用强甫蒙仲韵十首 其九', '刘克庄', '宋代', '已傍先庐敞便斋，善和万卷与君偕。少时岁月真驰隙，圣处工夫未涉涯。\n\n海浅蓬莱疑可近，云深阊阖不容排。信书至老成何事，有酒聊浇磊块怀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '用强甫蒙仲韵十首 其九' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('方日升杂画四首 其四 白雉', '边贡', '明代', '迢迢越裳国，万里献珍禽。不睹周王化，谁知姬旦心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '方日升杂画四首 其四 白雉' AND p.poem_author = '边贡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('云仙引 秋云', '王易', '清代', '旋出巫峰，乍收秦岭，秋来无限轻盈。遮溪白，傍山青。\n\n汀洲荻花如雪，隔水相看分外明。独有愁人，虚窗深院，相对愁生。\n\n天孙巧锦堪称，问多少、功夫织得成。蜀绮轻匀，吴绫细密，自费心情。\n\n天末怀人，江干惜别，望去应知泪暗倾。一夕风高，残鳞断羽，何处飘零。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '云仙引 秋云' AND p.poem_author = '王易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('得董汉苍北京信诗以答之', '杜关', '近代', '十年书恨寄柴扉，怅望天涯泪欲挥。一样流离之子在，等閒肝胆故人非。\n\n干戈送老行藏定，荆棘馀生去住违。见说官贫风雪厉，盼君病起不如归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '得董汉苍北京信诗以答之' AND p.poem_author = '杜关';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('甲辰闰月初伏快雨凉风昼眠初觉庭前小栏花木各有意气效柏梁体', '蔡襄', '宋代', '闰夏天地热焰烘，崇朝快雨随清风。昼轩梦觉开前栊，画栏花草意气雄。\n\n侧枕遥问数异同，如子微物烦化工。盍各言尔之所从，繁葩富艳生朱红。\n\n枯条大蕊千万重，修干点缀赤日中。蠲去忧忿谁与功，采摘烹煮祛烦胸。\n\n秋霜钜实垂如瓮，横柯远引交加丛。叶抽绿剑端黄茸，直立开拂泉货通。\n\n叠绕翠羽翻虬龙，误入畦町非余公。助涤渴肺思匪躬，物物自名词不穷。\n\n愿当我意乃汝容，负汝不饮惭衰翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '甲辰闰月初伏快雨凉风昼眠初觉庭前小栏花木各有意气效柏梁体' AND p.poem_author = '蔡襄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送方岩夫四首', '方回', '宋代', '同姓同年绾左符，岭南万里送孀孤。\n先君遗墨今犹在，为问封州有后无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送方岩夫四首' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江上值雪效欧阳体限不以盐玉鹤鹭絮蝶飞舞之', '苏轼', '宋代', '缩颈夜眠如冻龟，雪来惟有客先知。\n江边晓起浩无际，树杪风多寒更吹。\n青山有似少年子，一夕变尽沧浪髭。\n方知阳气在流水，沙上盈尺江无澌。\n随风颠倒纷不择，下满坑谷高陵危。\n江空野阔落不见，入户但觉轻丝丝。\n沾掌细看若刻镂，岂有一一天工为。\n霍然一挥遍九野，吁此权柄谁执持。\n世间苦乐知有几，今我幸免沾肤肌。\n山夫只见压樵担，岂知带酒飘歌儿。\n天王临轩喜有麦，宰相献寿嘉及时。\n冻吟书生笔欲折，夜织贫女寒无帏。\n高人著履踏冷冽，飘拂巾帽真仙姿。\n野僧斫路出门去，寒液满鼻清淋漓。\n洒袍入袖湿靴底，亦有执板趋阶墀。\n舟中行客何所爱，愿得猎骑当风披。\n草中咻咻有寒兔，孤隼下击千夫驰。\n敲冰煮鹿最可乐，我虽不饮强倒卮。\n楚人自古好弋猎，谁能往者我欲随。\n纷纭旋转従满面，马上操笔为赋之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江上值雪效欧阳体限不以盐玉鹤鹭絮蝶飞舞之' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄景逊', '文同', '宋代', '别后西城上，来须到日曛。\n目迎秦塞雁，心过陇山云。\n寡合无如我，高怀少似君。\n相思只相望，徒尔托云云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄景逊' AND p.poem_author = '文同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('客寄天台月桂子', '刘敞', '宋代', '天上仙人月里栽，无端飘逐海风来。可能种作千寻树，岁看高花烂漫开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '客寄天台月桂子' AND p.poem_author = '刘敞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题墨竹四首 其四 老', '唐文凤', '明代', '潜虬跃重渊，鳞甲半脱落。未愁风云生，只恐雷雨作。\n\n变化不可羁，虹光射天末。含情望三湘，翠袖侵寒薄。\n\n皇英久未归，苍梧烟漠漠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题墨竹四首 其四 老' AND p.poem_author = '唐文凤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闲居二首 其一', '鲁铎', '明代', '别墅仍书屋，闲居兴颇奇。野山争入座，田水暗通池。\n\n鸟语花深处，鱼游月上时。坐阑还散步，聊复有新诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闲居二首 其一' AND p.poem_author = '鲁铎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('耆英会 其一', '席汝言', '宋代', '系国安危唐上宰，功成身退汉留侯。二公闲暇开高宴，九老雍容奉胜流。\n\n共接雅欢恩意洽，不矜崇贵礼容优。赏心乐事人间盛，岂谓今稀古莫俦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '耆英会 其一' AND p.poem_author = '席汝言';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游庄严寺园', '贺铸', '宋代', '石楠花落小池清，独下平桥弄扉行。\n蔽日绿阴无觅处，不如归去两三声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游庄严寺园' AND p.poem_author = '贺铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贤者之孝二百四十首 其一○○ 郭基', '林同', '宋代', '岂伊东閤里，无似督邮贤。直把孝行荐，今人少孟坚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贤者之孝二百四十首 其一○○ 郭基' AND p.poem_author = '林同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉和族祖紫岩翁谩兴十首 其九', '汪炎昶', '宋代', '桃李贵以色，兰蕙贵以香。蚌胎秘奇彩，萤火耀寸光。\n\n中心固了了，竟莫辨否臧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉和族祖紫岩翁谩兴十首 其九' AND p.poem_author = '汪炎昶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('日来欢意顿减幸秋雨既足中秋定晴预约南坡小集观月且属耘老弟董其事', '虞俦', '宋代', '酒熟床头已圣清，吟诗窗下莫悲鸣。故人明月从来共，今岁中秋定好晴。\n\n雨脚已随荷盖尽，风头还逐桂花生。试谋一笑君须会，谁道尊前笑不成。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '日来欢意顿减幸秋雨既足中秋定晴预约南坡小集观月且属耘老弟董其事' AND p.poem_author = '虞俦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('芝兰章 其二', '韩上桂', '明代', '芝之生矣，维其荣矣。仙之游矣，维其灵矣。茹紫芝，乘云车。\n\n入参寥，历玄虚。上有太华之真经，元始之丹书。\n\n长相随，揽龙须。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '芝兰章 其二' AND p.poem_author = '韩上桂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟次唐行', '郭谏臣', '明代', '江乡逢暮春，一棹舣沙滨。客路看飞絮，行厨荐绿蘋。\n\n冠裳时暂远，鱼鸟渐相亲。长啸乾坤里，悠然著此身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟次唐行' AND p.poem_author = '郭谏臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古战场', '张蠙', '唐代', '荒骨潜销垒已平，汉家曾说此交兵。 \n 如何万古冤魂在，风雨时闻有战声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古战场' AND p.poem_author = '张蠙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·新月光寒昨夜霜', '佚名', '宋代', '新月光寒昨夜霜。三年不一奉瑶觞。朱颜大药知能驻，白日仙家岂计长。枫渐赤，橘初黄。五湖烟水动归航。且倾寿酒歌难老，便见除书出未央。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·新月光寒昨夜霜' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春云', '马祖常', '元代', '高云起城阙，流离度庭树。依风拂回塘，波缬光影注。\n\n荒林带疏烟，照日乱萦缕。婉娈连浮阳，空明映凄雾。\n\n岚翠含玉晖，景采满岩屿。逍遥幽赏谐，缅邈世娱阻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春云' AND p.poem_author = '马祖常';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('壬申元夜感赋二章 其二', '熊盛元', '当代', '半世飘零处处家，只从冷淡觅生涯。霜侵鬓发人千劫，诗写穷愁鬼一车。\n\n旧梦绿牵堤上柳，绮怀红幻镜中花。今宵酒酿他年泪，洒向心头绽苦芽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '壬申元夜感赋二章 其二' AND p.poem_author = '熊盛元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏物二十四首', '周凯', '清代', '肉角双双出蜗舍，壳纹细细似沈香。回环文理浑如木，性比蛼蚝分外凉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏物二十四首' AND p.poem_author = '周凯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题莫公台', '杜光庭', '唐代', '奇绝巍台峙浊流，古来人号小瀛洲。路通霄汉云迷晚， \n 洞隐鱼龙月浸秋。举首摘星河有浪，自天图画笔无钩。 \n 将军悟却希夷诀，赢得清名万古流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题莫公台' AND p.poem_author = '杜光庭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈二首 其一', '释清旦', '宋代', '三世诸佛不知有，一一面南看北斗。狸奴白牯却知有，云外金毛正哮吼。\n\n个中隐显现全身，头头透脱无前后。拨转机轮向上关，八角磨盘空里走。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈二首 其一' AND p.poem_author = '释清旦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湖山十景 其四 曲院风荷', '王洧', '宋代', '避暑人归自冷泉，步头云锦晚凉天。爱渠香阵随人远，行过高桥旋买船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湖山十景 其四 曲院风荷' AND p.poem_author = '王洧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('台中', '释函可', '明代', '无聊长寄一枝筇，悔不同君四百峰。旧榻尽容狞虎待，半铛常煮野云供。\n\n到家应共怜穷子，博饭无如学老农。从此入山惟稳睡，只愁僧打五更钟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '台中' AND p.poem_author = '释函可';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和慧知微雪韵', '释慧空', '宋代', '覆盖乾坤似有功，洞然明白却无踪。\n其如未识无踪意。屑玉霏霏落眼中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和慧知微雪韵' AND p.poem_author = '释慧空';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('前之十首次诗', '释行海', '宋代', '十五游方今五十，骎骎白尽少年头。\n看来造物真儿戏，忆著平生冷汗流。\n宇宙何须三兔窟，山川总是一菟裘。\n眼前不见江湖处，终是相忘欠白鸥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '前之十首次诗' AND p.poem_author = '释行海';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('从田桥石径赴拂水', '皇甫冲', '明代', '江光开初霁，山云未全敛。\n轻烟尚栖花，积雨犹在藓。\n携屐遵回麓，援萝上修岘。\n环林何透迤，磴道几回转。\n游心自忘罢，策足乃知蹇。\n含章乐丘园，耽隐易台铉。\n顿使昔念舒，乃得今抱展。\n将寻出世人，一往不复返。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '从田桥石径赴拂水' AND p.poem_author = '皇甫冲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再次还鹤韵三首 其二', '陈造', '宋代', '啅鹊却陪新饮啄，啼猿俨识旧容仪。可须辩士诳荆楚，似喜逐臣还秭归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再次还鹤韵三首 其二' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王至卿借骑入长安赋谢', '胡应麟', '明代', '未遘中涓访，犹勤上驷来。壮心悬伏枥，逸足借登台。\n\n䟤跋看龙种，飞腾羡骏才。天闲云五色，矫首见蓬莱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王至卿借骑入长安赋谢' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渡江云 寒食寄怀何磊任平', '邓桐芬', '近代', '初阳分远霭，晓寒渐薄，草色浸疏棂。数声啼鴂外，解事东风，布暖发深青。\n\n红香半砌，讶年光、寒食清明。春未阑，且留尊酒，重与话平生。\n\n消凝，茶瓯伴榻，药管施针，抱年年残病。空梦想、西江旧月，北国严城。\n\n故人咫尺天涯邈，枉目断、烟水迷冥。凭杖去，逡巡却恨伶俜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渡江云 寒食寄怀何磊任平' AND p.poem_author = '邓桐芬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长饥', '洪传经', '近代', '三春花未发，蜂蝶合长饥。排闷倾深盏，抒怀得小诗。\n\n蓬门罗雀久，尘榻赖龟支。苦忆东陵子，瓜田何处随。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长饥' AND p.poem_author = '洪传经';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('永昭陵挽词三首', '欧阳修', '宋代', '干戈不用臻无事，朝野多欢乐有年。\n便坐看挥飞白笔，侍臣新和◇梁篇。\n衣冠忽见藏原庙，箫鼓愁闻向洛川。\n寂寞秋风群玉殿，还同恍惚梦钧天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '永昭陵挽词三首' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔家傲 夏日', '钱启缯', '清代', '六月荷花香十里。三秋桂子醉难倚。风过新蝉声细细。\n\n听归雁，呼环莫把纱窗闭。\n\n帘捲落花疑蝶视。阶前络纬初鸣际。凭栏笑把轻纨启。\n\n看青天，■香一缕随风至。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔家傲 夏日' AND p.poem_author = '钱启缯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽张布政', '张宁', '明代', '万里云霄早致身，清时人物旧儒绅。四朝宠遇推良弼，一代勋名属老臣。\n\n青琐才高天上诏，紫薇花落梦中春。经纶未尽英雄死，海水东流夜月新。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽张布政' AND p.poem_author = '张宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和友人', '王之望', '宋代', '弟兄南渡各驰驱，向奉君王尺一除。\n黄耳音书寄怀抱，乌衣门巷惜丘墟。\n澄清孟博荣持节，雅量玄平静著书。\n五桂家风殊未艾，黄山佳气蔼如初。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和友人' AND p.poem_author = '王之望';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('社西村 其五', '陈献章', '明代', '社西逢酒伴，埭北有花枝。讵识愚公意，聊同牧竖嬉。\n\n围棋松崦久，度马板桥迟。袖有葳蕤草，还家不告饥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '社西村 其五' AND p.poem_author = '陈献章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('初秋夜同林太史过萧太史书斋', '区大相', '明代', '结庐虽傍市，种竹近成林。乍到安禅地，终谐大隐心。\n\n开轩迎苑月，隔牖度城砧。已惬山泉赏，何须云壑寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '初秋夜同林太史过萧太史书斋' AND p.poem_author = '区大相';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过琴溪', '杜伟', '唐代', '州府谪宦居，邑城摄官涖。悠悠泾川适，佳期此相迟。\n\n灵溪知几曲，曲曲各殊致。仙岭多巉颜，前峰特超类。\n\n穹崇势旁倒，山客下无地。洞穴盘龙蛇，空岩隐魑魅。\n\n蘋开秋水绿，竹动寒山翠。远嶂数瀑悬，疏林一猿坠。\n\n依然弹素弦，流我望乡泪。席上红泉飞，樽前白云至。\n\n中山是隐居，缅想故心醉。忽睹邢武辞，聆其金石备。\n\n神交十载得，良愿三人遂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过琴溪' AND p.poem_author = '杜伟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠赵山甫', '房皞', '元代', '寇盗连年剧猬毛，一身无处可奔逃。陈平自合西归汉，诸葛焉能北事曹。\n\n嗟我命兼才共薄，仰君名与德俱高。几时一笑沧浪畔，右手持杯左手螯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠赵山甫' AND p.poem_author = '房皞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大行皇帝挽歌辞三首 其二', '李东阳', '明代', '圣朝偃武修文日，共道王言似六经。宋史重施新衮钺，孔庭增饰旧笾铏。\n\n垂衣共仰升龙象，赐墨皆成翥凤形。回首茂陵松柏树，春来还向裕陵青。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大行皇帝挽歌辞三首 其二' AND p.poem_author = '李东阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同王昌龄裴迪游青龙寺昙壁上人兄院集和兄维', '王缙', '唐代', '林中空寂舍，阶下终南山。\n高卧一床上，回看六合间。\n浮云几处灭，飞鸟何时还。\n问义天人接，无心世界闲。\n谁知大隐者，兄弟自追攀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同王昌龄裴迪游青龙寺昙壁上人兄院集和兄维' AND p.poem_author = '王缙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('兰溪访吴圣与不遇', '李纲', '宋代', '夕次兰溪县，溪山照眼明。云端双塔耸，烟际一桥横。\n\n久旅易悽感，旧游如隔生。故人寻不值，飘泊若为情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '兰溪访吴圣与不遇' AND p.poem_author = '李纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寻梅三首 其一', '张镃', '宋代', '绀碧烘晴水照天，断槎荒葑牧羝田。数旬不踏苏堤路，专为梅花跨晓鞯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寻梅三首 其一' AND p.poem_author = '张镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('相国赵公邸中夜谈因留宿斋头作', '胡应麟', '明代', '剧语深杯兴未阑，平章西第傍金銮。高斋敢谓青绫薄，煖阁浑忘白苧寒。\n\n密筱飞霜流藻井，疏桐移月下雕栏。无劳夜望三台色，万仞晴光烛翠峦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '相国赵公邸中夜谈因留宿斋头作' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('薇山处过番石渡遭渡子无礼伤臂因韵', '陈著', '宋代', '卧如龙奋亮当贵，射可猿通广欲飞。谁料舟人为敌国，祇应山鸟怪儒衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '薇山处过番石渡遭渡子无礼伤臂因韵' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('木芙蓉', '邓深', '宋代', '露冷烟凄草树荒，木芙蓉好试平章。\n蒲萄晚叶尤宜日，芍药秋花正耐霜。\n蜀锦卷帏妆院落，秦宫开镜照池塘。\n写容安得剑南老，聊复殷勤酹一觞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '木芙蓉' AND p.poem_author = '邓深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('恭睹圣心勤劳颂扬不尽又成长句', '胤禛', '清代', '叨陪法驾阅新堤，夙夜辛勤悯庶黎。底定九河功媲美，时巡三辅典堪稽。\n\n烟村黯黯青帘扬，岸柳阴阴白马嘶。沉璧寘薪诚默契，神人应有绿图携。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '恭睹圣心勤劳颂扬不尽又成长句' AND p.poem_author = '胤禛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洞庭新建厅事柱下获一瓮中有钱曰太平喜而口占', '王鏊', '明代', '一钱清白承先哲，八柱高明应宰司。天赐不多良自贺，国家重建太平基。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洞庭新建厅事柱下获一瓮中有钱曰太平喜而口占' AND p.poem_author = '王鏊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送寿山人', '胡应麟', '明代', '飘然沧海客，曾事紫阳君。袖里黄庭字，囊中赤伏文。\n\n放舲三泖月，携杖九峰云。后夜华亭梦，应同鹤唳闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送寿山人' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庆元二年皇后册宝十三首 其四', '郊庙朝会歌辞', '宋代', '帟旒云舒，金秀充庭。璇卫銮华，茜佩垂𦀚。皇容熙备，柔仪顺承。\n\n三宫齐欢，万福昭膺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庆元二年皇后册宝十三首 其四' AND p.poem_author = '郊庙朝会歌辞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渡江云 十二月十三夜望月，和次香韵', '易顺鼎', '清代', '古愁流一发，冻华湿瓦，天影欲离青。婵娟初斗罢，密迩佳期，好事会圆成。\n\n微遮茜袖，想峭鬟窥树轻盈。须后夜瑶空雪意，补足二分明。\n\n吟声。花间暗度，唤起冰轮，悄催他端正。还只恐庞儿越瘦，不耐风棱。\n\n影娥池上无人到，管荒波半角枯菱。仙梦冷，寒簧被也霜凝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渡江云 十二月十三夜望月，和次香韵' AND p.poem_author = '易顺鼎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('武丘寺', '释兴肇', '宋代', '高僧危阁侵云际，尽日披襟濯好风。\n极目长川人不见，万株烟树接遥空。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '武丘寺' AND p.poem_author = '释兴肇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乙未正月初二大连客舍临孔子庙堂碑至解黻去佩书烬儒坑八字慨然有作', '程滨', '当代', '但有昏灯对一檠，当窗焰火动心兵。他乡临帖消长夜，末世裁诗了此生。\n\n华发皑皑天未雪，回肠隐隐剑初鸣。神州欲破千秋梦，秽史新书万岁名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乙未正月初二大连客舍临孔子庙堂碑至解黻去佩书烬儒坑八字慨然有作' AND p.poem_author = '程滨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元日', '刘旦', '宋代', '元日甘泉会，衣冠拜冕旒。\n图书一四海，玉帛万诸侯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元日' AND p.poem_author = '刘旦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('胡登仕送花', '方岳', '宋代', '一年春是牡丹时，不负花时只有诗。\n老去自知才思尽，枉分风月到山篱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '胡登仕送花' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨夜读书', '陆游', '宋代', '风雨澒洞吞孤村，读书拥褐不出门。\n历观忠邪见肝肺，直与治乱穷根原。\n博岩之野感帝梦，此事难以今人论。\n危冠长剑一见用，万里耕桑吾道尊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨夜读书' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('写扇寄刘升', '杨士奇', '明代', '不到珠林五六春，閒窗书卷故殷勤。别时看种庭前竹，远想长枝已拂云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '写扇寄刘升' AND p.poem_author = '杨士奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('世贸三歌 其二 飞机歌', '卢青山', '当代', '瞠彼西方兮，飞其机矣。以暴逗暴兮，自古之规矣。\n\n神农虞夏日自吹兮，世果安归矣。于嗟徂兮，文明之衰矣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '世贸三歌 其二 飞机歌' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('成帝时歌谣', '佚名', '魏晋', '邪径败良田，谗口乱善人。桂树华不实，黄爵巢其颠。\n\n故为人所羡，今为人所怜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '成帝时歌谣' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦横塘 简筜谷', '李符', '清代', '鸭头酥雨，雁背尖风，峭帆催别春市。几月秦淮，换细葛、芙蕖香里。\n\n秧珑耕蓑，柘村缲茧，顿牵乡思。上层楼试望，甚处家林，斜阳外、重重水。\n\n西邻旧筑渔矶。共棋灯笛月，今隔千里。银沫青笺，盼不到、一双花鲤。\n\n料只在、吴根越角，谁与衔杯伴吟袂。且待归来，约移秋艇，采菱红莼翠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梦横塘 简筜谷' AND p.poem_author = '李符';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古八首', '释道颜', '宋代', '椎锣擂鼓转船头，席卷波翻喊激流。\n洗脚上船乘快便，顺风相送下扬州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古八首' AND p.poem_author = '释道颜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('张见甫自新蔡来访得情字书字二首 其一', '欧大任', '明代', '竹林残暑摄衣迎，揖客西来坐尽倾。异代河山扶片语，中原渔猎傍时名。\n\n马嘶讲肆非官舍，鸾啸高天岂世情。囊有酒钱君莫问，金鞍还许过孤城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '张见甫自新蔡来访得情字书字二首 其一' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再次上京杂咏韵十首 其七', '袁桷', '元代', '土驿高低置，苍茫七日程。马通分熠耀，牛酪注深清。\n\n残雪明珠阙，繁星列火城。前山黄白处，草药不知名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再次上京杂咏韵十首 其七' AND p.poem_author = '袁桷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆潼关', '徐夤', '唐代', '洞壑双扉入到初，似从深阱睹高墟。天开白日临军国， \n 山夹黄河护帝居。隋炀远游宜不反，奉春长策竟何如。 \n 须知皇汉能扃鐍，延得年过四百馀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆潼关' AND p.poem_author = '徐夤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('就正斋九日赏菊', '胤禛', '清代', '重阳高会幔亭张，阶下寒英正吐芳。为羡霜丛矜晚节，同来香径领秋光。\n\n嘉宾落帽风流在，绮席征歌雅兴长。却笑当年彭泽叟，东篱寂寞独倾觞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '就正斋九日赏菊' AND p.poem_author = '胤禛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉和竟陵王经刘瓛墓下诗', '柳恽', '南北朝', '西河寂高业，北海望清尘。音徽谁与寄，尚德在伊人。\n\n遗文重昭晢，绝绪复纷纶。露华尚朝日，兰生无久春。\n\n芳猷动渊思，抚轼履高辰。山风起寒木，野雀乱秋榛。\n\n垄草时易宿，素轨邈难遵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉和竟陵王经刘瓛墓下诗' AND p.poem_author = '柳恽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送杨司谏之南京', '徐溥', '明代', '同云漫漫未成雪，故人握手都门别。马蹄蹴裂沙河冰，雁声叫落淮阴月。\n\n关西自古清白声，甲科早掇超群英。手持风裁下南国，谏草日日来承明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送杨司谏之南京' AND p.poem_author = '徐溥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陟东门 其二', '霍与瑕', '明代', '陟东门，望望白云。安期一去，今几千春。白云长在，视安期之迹若飞尘。\n\n猗硕人之寿兮，寿若白云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陟东门 其二' AND p.poem_author = '霍与瑕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古七十六首 其四十三', '释士圭', '宋代', '雷火光中休草草，剑轮锋上莫忉忉。等闲放却全身入，终不当头犯一毫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古七十六首 其四十三' AND p.poem_author = '释士圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('今我不乐三章章五句 其三', '张翥', '元代', '月白西南星宿稀，巷无行人蝙蝠飞。步檐萧萧露沾衣，目断天涯遍芳草，王孙不归春自归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '今我不乐三章章五句 其三' AND p.poem_author = '张翥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送黄义庵还闽', '林廷选', '明代', '半生宦辙接清游，前是苏州后越州。桃李满门閒即乐，江湖驰阙远还忧。\n\n别愁晚浦闻鸣雁，归趣晴沙对懒鸥。试问六平旧同馆，白头林下几人休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送黄义庵还闽' AND p.poem_author = '林廷选';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读邵康节击壤集二十首 其十一', '薛瑄', '明代', '排风御气复鞭霆，历览无边造化情。随分自能安至乐，玩心谁复识高明。\n\n先天图有年年运，皇极书为世世经。首尾诗成多寓兴，调高白雪少人听。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读邵康节击壤集二十首 其十一' AND p.poem_author = '薛瑄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('花心动 牵牛花，同子年韵', '郭则沄', '清代', '银汉分凉，误婵娟、仙衣五铢初试。露缀钿轻，风飐铃圆，扶上晚篱烟紫。\n\n锦棚一角秋来早，只閒伴、吟人无睡。蓦肠断、红墙浅梦，暗蛩啼碎。\n\n宛转愁丝自系。偏盼到星期，替人憔悴。妒煞汉宫夜月，鸳机虚伴，渚莲香坠。\n\n洗车消息前番雨，认绡碧、几痕残泪。数离绪年年，倩伊细记。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '花心动 牵牛花，同子年韵' AND p.poem_author = '郭则沄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('口号呈问庞二少府', '边贡', '明代', '黄鹤楼前夜泊舟，苇花枫叶似江州。乐天本是多情客，卧听歌声起别愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '口号呈问庞二少府' AND p.poem_author = '边贡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('萤火', '孙作', '明代', '雨中萤火看不灭，入户潜行欲近人。槐市书生经满案，微光待汝续鸡晨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '萤火' AND p.poem_author = '孙作';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百四十一首 其四十二', '释师范', '宋代', '正觉山前，双林树下。弄假像真，弄真像假。临风哮吼戴嵩牛，顾影嘶鸣韩干马。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百四十一首 其四十二' AND p.poem_author = '释师范';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送黄亮垣先生还朝', '李孙宸', '明代', '凉飔飒飒惊秋节，三城官柳鸣蝉咽。越王台倚越山云，王气千秋可揽结。\n\n传呼候馆抗前旌，夜来南斗避文星。津亭冠盖不知数，共言祖送黄先生。\n\n先生三朝旧名德，神庙贤良策第一。藉冠宫寮侍从班，身依子舍承欢日。\n\n年来冲圣御龙楼，讲幄文儒礼数优。金匮两朝徵实录，前席时虚待校雠。\n\n以此征车难久驻，谢传东山起别墅。行边烟雨五陵花，望里春云万家树。\n\n到日金銮凤翼开，如椽史笔总鸿裁。谟烈显承光琬琰，始信龙门一代才。\n\n圣明有道勤宵旰，夔龙勋业盈霄汉。宣麻早晚拜先生，伯仲之间见伊旦。\n\n蹇予夙昔托追游，归来一病狎沧洲。临岐自怅典型远，飞梦长随入帝州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送黄亮垣先生还朝' AND p.poem_author = '李孙宸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄刘秀才', '释重显', '宋代', '远远飞来一幅书，愈风诚重复何如。相逢相见未期日，目断千山插太虚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄刘秀才' AND p.poem_author = '释重显';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与小儿助子游江横作', '蒲寿宬', '宋代', '葺荷偶忆湘累句，築屋还寻杜若汀。\n孤树每留残日白，片帆徐度远山青。\n海鸥知我断机虑，渔父与谁分醉醒。\n何处扁舟横短笛，月明风袅不堪听。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与小儿助子游江横作' AND p.poem_author = '蒲寿宬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('以嗜酒爱风竹卜居此林泉为韵作十小诗 其五', '方岳', '宋代', '周有说爱莲，陶有诗爱菊。吾居则谁与，其诸子猷竹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '以嗜酒爱风竹卜居此林泉为韵作十小诗 其五' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和程德裕颂五首', '黄庭坚', '宋代', '石田耕种难成稻，荼蓼栽来只苦辛。\n万物一家真富贵，使君见後却清贫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和程德裕颂五首' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汉玉赤刀歌', '弘历', '清代', '出匣宝气腾葱郁，秋水一湾落霞拂。游刃恢恢岂少𠜾，疑有丁甲相呵㗵。\n\n蟠虬之而鼌采蔚，当年西序横陈物。介绍大训连朱芾，姬室文明此黼黻，遐思成康不可迄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汉玉赤刀歌' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红', '陈之贤', '宋代', '人物英雄，更独抱、无双才气。年正壮，文章武略，尽曾留意。破胆欲凭胸内甲，清原宴启舟中誓。笑区区、燕雀不能知，青云志。 \n 封侯貌，神人比。社下手，须荣试。况相门出将，君家常事。斗印垂金他日贵，寿杯浮玉今朝醉。看年年、南极倍明时，春明媚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红' AND p.poem_author = '陈之贤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜夜曲', '胡奎', '明代', '夜夜望明月，初若蛾眉弯。夜夜望明月，今如白玉盘。\n\n玉盘有时缺，蛾眉愁万结。月照闺中人，如何有离别。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜夜曲' AND p.poem_author = '胡奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贺郑枢齐 其五', '刘子寰', '宋代', '紫闼黄枢功已著，苍生黔首望逾深。公施政术施仁术，公得人心得士心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贺郑枢齐 其五' AND p.poem_author = '刘子寰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵李明府上事初谒登源庙用苏黄门韵见示', '汪晫', '宋代', '缓引前诃度岭巅，真祠犹镇旧山川。\n县知幽德如存日，更有孤忠合老天。\n双炷炉香祈一稔，两诗题咏播千年。\n民安善政神应喜，桑荫儿童犊背眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵李明府上事初谒登源庙用苏黄门韵见示' AND p.poem_author = '汪晫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古三十八首 其二十三', '释慧方', '宋代', '报客传言信已通，叉手低头便鞠躬。对面一双青白眼，当头蹉过住山翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古三十八首 其二十三' AND p.poem_author = '释慧方';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重宿九莲寺', '吴与弼', '明代', '曾寓禅房十日居，重来不见旧时书。閒窗一榻春宵梦，细忆流年二纪馀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重宿九莲寺' AND p.poem_author = '吴与弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郡城阴雨', '牛焘', '清代', '节过中秋雨骑月，残秋徂冬泥滑滑。郡城风急不胜寒，掉臂归来煨榾柮。\n\n菊残不见傲霜枝，梅花数点香满池。任尔霜前弄喉舌，暖回黍谷日迟迟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郡城阴雨' AND p.poem_author = '牛焘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('癸未元日和许奉常作', '欧大任', '明代', '旧京元会傍丹霄，雪照青山玉作桥。双阙风云随剑舄，十年江海梦渔樵。\n\n长生岂但思餐柏，上寿惟能学颂椒。郎署冯唐头已白，自怜何补圣明朝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '癸未元日和许奉常作' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水龙吟 夜雨，晨霁，过宋家埂南桥，作此以寄贵阳熊建中，八叠前韵', '单人耘', '近代', '陂塘新绿初稠，泡桐花落经行处。粉云朱日，楼台倒影，天光融聚。\n\n谁料昨宵，侵窗暗湿，千丝万缕。纵平生侘傺，虽禁白发，满臆是，清狂句。\n\n行吟未负晴朝，任凭他、连城风雨。青山欲渡，春波又暖，似闻莺语。\n\n诗可怡人，挞愁浇恨，云何无补。寄乡情一片，迢迢千里，慰天南侣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水龙吟 夜雨，晨霁，过宋家埂南桥，作此以寄贵阳熊建中，八叠前韵' AND p.poem_author = '单人耘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('口号', '舒岳祥', '宋代', '敏求善酿能好客，喜与老潘相往还。\n今日敏求泉下卧，老潘无酒客姜山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '口号' AND p.poem_author = '舒岳祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出门行', '皇甫汸', '明代', '君不见李生出门仰天笑，㐲剑直走长安道。又不见苏季还家人尽轻，敝裘再入咸阳城。\n\n丈夫义气横云海，局促宁为辕下态。白璧凋磨美益光，黄金百鍊精还在。\n\n身若藩羊触未安，心同塞马达能观。人情溪壑非云险，世路风尘本自难。\n\n魏尚朝闻起代门，夕看持节拥朱轩。解道圣明能使过，须知感激为衔恩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出门行' AND p.poem_author = '皇甫汸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆陜西 其一', '玄烨', '清代', '长安城阙昔曾游，黄水名山宛在眸。清渭东流流自在，阳关远去去何休。\n\n民稠地险人难化，谷贱年丰信有收。衰老无能再一览，缅怀西顾愈添愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆陜西 其一' AND p.poem_author = '玄烨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古四十四首', '释师范', '宋代', '大士错解注，志公错注解。\n臭肉积屠门，堪笑无人买。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古四十四首' AND p.poem_author = '释师范';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送王敦素', '邓深', '宋代', '龙蟠山色引衡庐，霜落江清影碧虚。\n鼓枻厌骑沙苑马，行厨饫食武昌鱼。\n缓歌玉树翻新曲，趣入金銮续旧书。\n官达故人稀会面，君来相见肯如初。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送王敦素' AND p.poem_author = '邓深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('如梦令', '叶俊杰', '清代', '篱畔红梅香透。又是赏春时候。不见咏诗人，辜负艳阳清昼。\n\n僝僽。僝僽。病骨畏寒花瘦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '如梦令' AND p.poem_author = '叶俊杰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再游寒山别墅', '弘历', '清代', '灵岩纡䍐跸，所为游寒山。春晓宿雨收，千嶂泮轻烟。\n\n遵磴下高峰，天平在目前。此则姑舍是，已悉率戒盘。\n\n过岭不五里，别墅爰至焉。巀嶭屏陡壁，逶迤枕平峦。\n\n渟为半亩池，激为千仞湍。随宜置亭阁，面势抱林泉。\n\n昨去落梅英，今来绽牡丹。今昨信幻耳，来去亦傥然。\n\n凡夫果不凡，即境知人仙。中心以藏之，句留苍岩间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再游寒山别墅' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('盆池', '欧阳修', '宋代', '西江之水何悠哉，经历灨石险且回。\n余波拗怒犹涵澹，奔涛击浪常喧豗。\n有时夜上滕王阁，月照净练无纤埃。\n杨阑左里在其北，无风浪起传古来。\n老蛟深处厌窟穴，蛇身微行见者猜。\n呼龙沥酒未及祝，五色粲烂高崔嵬。\n忽然远引千丈去，百里水面中分开。\n收踪灭迹莫知处，但有雨雹随风雷。\n千奇万变聊一戏，岂顾溺死为可哀。\n轻人之命若蝼螘，不止山岳将倾颓。\n此外鱼虾何足道，厌饫但觉腥盘杯。\n壮哉岂不快耳目，胡为守此空墙隈。\n陶盆斗水仍下漏，四岸久雨生莓苔。\n游鱼拨拨不盈寸，泥潜日炙愁暴鳃。\n鱼诚不幸此局促，我能决去反徘徊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '盆池' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饮汪氏庄', '王廷陈', '明代', '芜秽贫家产，悲伤过客魂。野翁谈废坞，邻竖入颓垣。\n\n石鼎烧松叶，瓷罂藉竹根。那堪对摇落，寒日下孤村。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饮汪氏庄' AND p.poem_author = '王廷陈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乐府变十九首 其十三 莫州谣', '王世贞', '明代', '兄何在，南伐吴。弟何在，北幽都。老父何在，呼役夫。\n\n少妇具晨餔，大妇行唤姑。行唤姑，姑不起。溺床下，波瀰瀰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乐府变十九首 其十三 莫州谣' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登岳阳楼 其二', '卢青山', '当代', '轻鸥追帆影，长雾横空蒙。苍茫天穷处，天穷水未穷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登岳阳楼 其二' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈二十七首 其七', '释守净', '宋代', '九夏炎炎火热，木人汗流不辍。夜来一雨便凉，莫道山僧不说。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈二十七首 其七' AND p.poem_author = '释守净';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再赋颂二首 其二', '韩维', '宋代', '阳景朝来释冻凘，水边林下好追随。灵山一会何曾散，莫学时人语别离。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再赋颂二首 其二' AND p.poem_author = '韩维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庚寅岁乡居立秋偶占', '刘凤梧', '近代', '柴门临水稻花香，垂穗盈畴日渐黄。漫怅粗糠难果腹，须知新谷快登场。\n\n饱经烽火三边赤，又试秋风一味凉。人隔蒹葭从未得，独扶藜杖看斜阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庚寅岁乡居立秋偶占' AND p.poem_author = '刘凤梧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠别望之兼寄诸相知十首 其九', '顾璘', '明代', '汶阳临大道，喜近赵东曹。窜地传书数，他乡念我劳。\n\n名高连泰岳，心远折江涛。拟共观周礼，无因接誉髦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠别望之兼寄诸相知十首 其九' AND p.poem_author = '顾璘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乌什', '曹麟开', '清代', '戍士无劳夜枕戈，永宁城外散鸣驼。东回姑墨千峰雪，南下于阗九折河。\n\n五翕侯仍招旧部，二昆弥已靖沙陀。吹鞭争唱天鹅曲，不数摩诃兜勒歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乌什' AND p.poem_author = '曹麟开';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再和送李大夫', '吕陶', '宋代', '莫听滩前涨水声，少迟樽酒话平生。堪嘉祁老初辞位，却笑樊须欲问耕。\n\n落日望君三舍远，西风惠我一襟清。江流自在悠哉兴，得得回船十里行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再和送李大夫' AND p.poem_author = '吕陶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天 儿童节应纤纤邀作', '吴金水', '当代', '皓齿明眸黛未描。屏前话语倍妖娆。玲珑锦字怜苏惠，要眇清诗感薛涛。\n\n吹玉笛，抚兰皋。何时携手共花朝。今宵閒看儿童乐，暂忘山长岁月遥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天 儿童节应纤纤邀作' AND p.poem_author = '吴金水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋江晚泊', '虔礼宝', '清代', '极浦青苍湿未收，晚风吹槛更悠悠。半村黄叶斜阳里，一片闲云古渡头。\n\n清景可怜皆入画，孤心易感不关秋。水天无事容高卧，此意萧然便十洲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋江晚泊' AND p.poem_author = '虔礼宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游仙诗十首 其五', '庾阐', '魏晋', '荧荧丹桂紫芝。结根云山九疑。鲜荣夏馥冬熙。谁与薄采松期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游仙诗十首 其五' AND p.poem_author = '庾阐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题水仙', '杨士奇', '明代', '汉广之滨，清洛之汭。留此娟好，邂逅谁遗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题水仙' AND p.poem_author = '杨士奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书事二首 其一', '刘克庄', '宋代', '空空都没一行书，行行徒矜九尺躯。面上带妖真可耻，脚中有鬼不容扶。\n\n末年铁拐传仙诀，他日金锥抉冢珠。泉下定为明允笑，果能看破半山无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书事二首 其一' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶成简任肃斋教论', '黄庚', '宋代', '贫病交攻久废诗，萧然一室独栖迟。\n酒钱已尽琴将典，瓶粟无储鹤亦饥。\n豪杰不多陈仲举，结交惟欠魏无知。\n箪瓢钟鼎都休计，毕竟穷通各有时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶成简任肃斋教论' AND p.poem_author = '黄庚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('旌德道中', '程可中', '明代', '底用嗟劳役，空山行自幽。\n晓云梳树出，清溜篆沙流。\n税毕收蚕市，场喧过麦秋。\n驿传东海信，政恐有征求。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '旌德道中' AND p.poem_author = '程可中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读书', '王樵', '明代', '我性难谐俗，诗书独与亲。一楼堪累月，万事付诸人。\n\n会意辄忘食，起思如有神。停杯待明月，下榻为嘉宾。\n\n永日三茅顶，寒江一钓缗。愿言长若此，已谓乐无伦。\n\n貌以缨冠改，人添识面新。今时崇意气，骨肉在胡秦。\n\n尝笑陶元亮，何如郑子真。祗因三径费，失却葛天民。\n\n局蹐邯郸步，惭惶西子矉。浪从双眼白，生取几人瞋。\n\n物物私其假，生生总是尘。鷾鸸犹有智，鸥鸟固难驯。\n\n快意醒前梦，回头迹已陈。停云閒对户，堪与洗心论。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读书' AND p.poem_author = '王樵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清夜', '施枢', '宋代', '客身随取止，一室冷如冰。\n景远吟何托，情疏梦不曾。\n雨粘初藓壁，风谢欲花灯。\n岂是无家者，甘为有发僧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清夜' AND p.poem_author = '施枢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六月二十一日夜起', '郑孝胥', '清代', '林暗幽光起，楼高碧落通。微风成独夜，凉月亦凌空。\n\n草草随残劫，纷纷谁长雄？死棋聊插手，吾道若为东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六月二十一日夜起' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上元前二日郑红泉钱百泉约斋汪云壑陈东川过集斋中', '王复', '清代', '淡宕试镫风，历乱催花鼓。盼春春已来，淑气盎亭午。\n\n南荣坐故人，清襟散蘅杜。瓶卉香细浮，幽禽屡窥户。\n\n对此景物和，欢言酌芳醑。笋韭愧粗供，厨乏络秀女。\n\n笑语粲烛花，暖意尊前煦。惟兹文字交，便拟醉乡侣。\n\n中覆暗自欣，战拇纷难数。百斛亦何辞，独醒真徒苦。\n\n婵娟月满帘，掩映色殊妩。工巷联臂歌，往来同织组。\n\n试教影吟三，未许更催五。狂思买良宵，那辨金如土。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上元前二日郑红泉钱百泉约斋汪云壑陈东川过集斋中' AND p.poem_author = '王复';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('船过芳茂和三山二首 其一', '刘济农', '近代', '芳茂三山峰又峰，苍松翠柏郁葱葱。长堤十里婆娑柳，一叶扁舟烟雨中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '船过芳茂和三山二首 其一' AND p.poem_author = '刘济农';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同诸公泛舟一首', '王渐逵', '明代', '春水生桃渚，扁舟遥自通。浦云低压岸，花雨细从风。\n\n鼓急疑牵濑，歌残欲罢钟。山人亦何幸，文会兴相同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同诸公泛舟一首' AND p.poem_author = '王渐逵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏贺长公枕溪新筑', '陶益', '明代', '数亩园中独乐身，别从青野结溪邻。榆枝折罢吹藜火，柿叶书残岸葛巾。\n\n避俗已拚人共弃，投閒还许鹭相亲。镜湖一曲能如否，解说风流老季真。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏贺长公枕溪新筑' AND p.poem_author = '陶益';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古塞下曲四首', '贯休', '唐代', '古塞腥膻地，胡兵聚如蝇。寒雕中髇石，落在黄河冰。 \n 苍茫逻逤城，枿枿贼气兴。铸金祷秋穹，还拟相凭陵。 \n 战骨践成尘，飞入征人目。黄云忽变黑，战鬼作阵哭。 \n 阴风吼大漠，火号出不得。谁为天子前，唱此边城曲。 \n 日向平沙出，还向平沙没。飞蓬落军营，惊雕去天末。 \n 帝乡青楼倚霄汉，歌吹掀天对花月。岂知塞上望乡人， \n 日日双眸滴清血。 \n 狼烟在阵云，匈奴爱轻敌。领兵不知数，牛羊复吞碛。 \n 严冬大河枯，嫖姚去深击。战血染黄沙，风吹映天赤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古塞下曲四首' AND p.poem_author = '贯休';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百四十一首 其二十六', '释师范', '宋代', '年年是好年，日日是好日。好事大家知，今朝正月一。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百四十一首 其二十六' AND p.poem_author = '释师范';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('穿杨亭', '刘摰', '宋代', '华构翚飞一望中，颜间篆墨飏秋风。休矜百步穿杨巧，未及当年射虎功。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '穿杨亭' AND p.poem_author = '刘摰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词十首', '张枢', '宋代', '回廊隔树帘帘卷，曲水穿桥路路通。\n禁漏滴斜花外日，御香薰暖柳边风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词十首' AND p.poem_author = '张枢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('墨竹', '白玉蟾', '宋代', '虚舟惠我一墨竹，纸上森森一枝玉。\n展向庭前与鹤看，今宵不许枝头宿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '墨竹' AND p.poem_author = '白玉蟾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三月一日道中偶成', '黄景仁', '清代', '马上年华似掷梭，雨颠风驶奈愁何。三分花事二分去，九十春光六十过。\n\n几阵箫声山店远，一鞭柳色酒旗多。压鞍诗思何能遣，半为怀人感逝波。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三月一日道中偶成' AND p.poem_author = '黄景仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戊午生朝和居厚弟五绝 其四', '刘克庄', '宋代', '灵龟曳尾防钻壳，老蚌潜光怕剖珠。史笔久无两龚传，画家曾有二疏图。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戊午生朝和居厚弟五绝 其四' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('韩煦仲过镜园泛舟玩月先已共赋六言十绝复投赠八律步元韵奉酬 其四', '邓云霄', '明代', '潮催月满共扬舲，棹倚花阴且暂停。玉屑纷随挥麈下，石潭疑有睡龙听。\n\n人间胜会宜投辖，天上佳期欲度星。闻道咸池堪沐发，乘槎吾拟向东溟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '韩煦仲过镜园泛舟玩月先已共赋六言十绝复投赠八律步元韵奉酬 其四' AND p.poem_author = '邓云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐', '白敦仁', '近代', '雨昏烟锁。飞絮帘前堕。一枕绿云初梦破。万缕千条愁裹。\n\n人前不理丝桐。新妆垂手临风。三十六园朱李，燕归何处相逢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐' AND p.poem_author = '白敦仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寓意十首次敬助韵 其七', '王冕', '元代', '蛮触杂奔竞，蝇蚋纷争喧。\n鸾凤巢枳棘，鸱鸮集琅轩。\n风雷久不作，野露生微寒。\n壮士万里怀，肯谢漂母餐。\n古来王佐才，多在耕钓间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寓意十首次敬助韵 其七' AND p.poem_author = '王冕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题证道寺', '唐彦谦', '唐代', '弯环青径斜，自是野僧家。满涧洗岩液，插天排石牙。 \n 炉寒馀柏子，架静落藤花。记得逃兵日，门多贵客车。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题证道寺' AND p.poem_author = '唐彦谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同行归急困倦不能诗', '陈藻', '宋代', '行李放迟迟，周遭好拾诗。\n归程催我急，脚力与神疲。\n来往成虚费，科名未有期。\n流传堪脍炙，造物不相亏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同行归急困倦不能诗' AND p.poem_author = '陈藻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过安仁县权令主簿同蔡尉见访二首 其一', '孙觌', '宋代', '莽莽缠兵气，蓬茅庇一邱。尚看蒙赤帻，不复卧黄紬。\n\n抱牍杭凫鹜，徵租聚沐猴。黄昏更萧瑟，风雨啸鸺鹠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过安仁县权令主簿同蔡尉见访二首 其一' AND p.poem_author = '孙觌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('朝房待命', '杨士奇', '明代', '正是临危处，深知负罪频。廷臣皆执法，天子尚垂仁。\n\n紫殿红云近，金河瑞彩新。恩波今浩荡，终忆借枯鳞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '朝房待命' AND p.poem_author = '杨士奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋霁·癸未，一九四三年。和慈博市桥候潮，用梅溪韵', '黄咏雩', '近代', '结梦桐阴，又叶瘁云寒，渐老秋色。苇折鸠移，柳枯蝉噤，薄寒中人犹力。\n\n故山倦翼。海天南尽伤心碧。渺讯息。谁念白头多病茂陵客。\n\n听说夜语，几度潮生，半江鱼龙，依旧岑寂。夜何其、鸡鸣未已。\n\n潇潇风雨此何夕。蕙怅芰裳应记得。说与猿鹤，遮莫为我惊疑，草堂归去，露驰烟驿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋霁·癸未，一九四三年。和慈博市桥候潮，用梅溪韵' AND p.poem_author = '黄咏雩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西峰访范复庵不值留赠', '屈大均', '明代', '横天一壁惊无路，频骑夹岭空中度。栈边万壑沉青冥，桥下千峰出烟雾。\n\n我从玉井得真源，明星玉女招不顾。直向西峰攀所思，楼压莲花花倒垂。\n\n三闾披发同山鬼，四皓疗饥有紫芝。咫尺白云寻不见，先朝耆旧君堪恋。\n\n无悲帝座隔层城，自有天门通一箭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西峰访范复庵不值留赠' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('香阴', '通润', '明代', '山中多药苗，往往发香气。不知采药人，曾嗅此香未。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '香阴' AND p.poem_author = '通润';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红', '佚名', '宋代', '雪共梅花，念动是、经年离拆。重会面、玉肌真态，一般标格。\n\n谁道无情应也妒，暗香埋没教谁识。却随风、偷入傍妆台，萦帘额。\n\n惊醉眼，朱成碧。随冷暖，分青白。叹朱弦冻折，高山音息。\n\n怅望关河无驿使，剡溪兴尽成陈迹。见似枝而喜对杨花，须相忆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('前雁字诗十九首 其十', '王夫之', '明代', '此字无人识，空劳历九州。分明扶日月，因革自春秋。\n\n鸩篆删妖步，莺歌耻佞喉。冥飞谁弋篡，不坠草元楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '前雁字诗十九首 其十' AND p.poem_author = '王夫之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('周漕泊舟寺前', '释居简', '宋代', '见说淮东使者归，耄鲵都作小儿啼。暂闲绿野停鸿鹄，小俟青冥骤駃騠。\n\n度外二三皆胜策，胸中十万未全提。浯溪尚有崭天石，颂德歌功尽可题。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '周漕泊舟寺前' AND p.poem_author = '释居简';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('政和戊戌孟夏补试文武遣兴一首', '李光', '宋代', '一帘疏雨锁牢愁，小阁幽轩得暂留。漫说金瓯能破睡，不如玉局解消忧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '政和戊戌孟夏补试文武遣兴一首' AND p.poem_author = '李光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暮春有感寄友人', '鱼玄机', '唐代', '莺语惊残梦，轻妆改泪容。\n竹阴初月薄，江静晚烟浓。 \n湿觜衔泥燕，香须采蕊蜂。\n独怜无限思，吟罢亚枝松。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暮春有感寄友人' AND p.poem_author = '鱼玄机';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏梅花', '庾信', '南北朝', '常年腊月半，已觉梅花阑。\n不信今春晚，俱来雪里看。\n树动悬冰落，枝高出手寒。\n早知觅不见，真悔著衣单。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏梅花' AND p.poem_author = '庾信';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('如梦令 离情四首 其一', '宋琬', '清代', '刚到凤凰台上。无那骊驹三唱。愿作博山炉，魂逐沈烟游飏。\n\n罗帐。罗帐。高筑愁城千丈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '如梦令 离情四首 其一' AND p.poem_author = '宋琬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('穷劫曲', '佚名', '先秦', '王耶王耶何乖劣。不顾宗庙听谗孽。\n任用无忌多所杀。诛夷白氏族几灭。\n二子东奔适吴越。吴王哀痛助忉怛。\n垂涕举兵将西伐。伍胥白喜孙武决。\n三战破郢王奔发。留兵纵骑虏京阙。\n楚荆骸骨遭掘发。鞭辱腐尸耻难雪。\n几危宗庙社稷灭。庄王何罪国几绝。\n卿士凄怆民恻悷。吴军虽去怖不歇。\n愿王更隐抚忠节。勿为谗口能谤亵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '穷劫曲' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄陶仲调', '陈子升', '明代', '九畹兰边五柳家，沅湘归去阻瑶华。名山太史传青简，濒海诸生想绛纱。\n\n怀古独寻洲畔树，悲秋还听月中笳。上林摇笔空云梦，肯向游畋逐后车。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄陶仲调' AND p.poem_author = '陈子升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上巳日赠都上人', '殷尧藩', '唐代', '三月初三日，千家与万家。蝶飞秦地草，莺入汉宫花。 \n 鞍马皆争丽，笙歌尽斗奢。吾师无所愿，惟愿老烟霞。 \n 曲水公卿宴，香尘尽满街。无心修禊事，独步到禅斋。 \n 细草萦愁目，繁花逆旅怀。绮罗人走马，遗落凤凰钗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上巳日赠都上人' AND p.poem_author = '殷尧藩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜收知旧书，复畏答，书二绝', '范成大', '宋代', '强裁尺互答相思，两目眵昏腕力疲。\n牵率老夫令至此，门前犹说报书迟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜收知旧书，复畏答，书二绝' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天 赠医士沈德诚', '张雨', '元代', '东老传家道气浓。榴皮壁上有仙踪。耳孙阴德如何限，都在参苓药笼中。\n\n无贵贱，有穷通。活人心事契苍穹。吾家昆弟能无恙，须藉全生一匕功。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天 赠医士沈德诚' AND p.poem_author = '张雨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花 其四 岁暮有咏', '徐树铮', '清代', '向晚风来天又雪。未是春归，已是春怀恶。百草千花愁寂寞。\n\n隔帘乍报梅英落。\n\n万种缠绵抛不却。便不思量，争不思量著。入夜霜钟敲更切。\n\n玉楼高梦浑惊觉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花 其四 岁暮有咏' AND p.poem_author = '徐树铮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵答留台春卿集贤侍郎见寄', '韩琦', '宋代', '十稔违谈燕，区区混浊流。经时无一信，度夕是三秋。\n\n友会此难约，君恩尚未酬。何人伴高兴，洛棹与嵩楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵答留台春卿集贤侍郎见寄' AND p.poem_author = '韩琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同杨计公谒刁蒙吉先生', '张念圣', '清代', '三年曾有约，今岁始能复。携我同心人，登龙展私淑。\n\n入门炙道儿，閒庭一何肃。先生抱道深，元气如可掬。\n\n正议回狂澜，耻与时贤逐。圣也戆而狂，意行无边幅。\n\n三日坐春风，句萌学草木。洗耳聆铎音，谈经继白鹿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同杨计公谒刁蒙吉先生' AND p.poem_author = '张念圣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题横披竹', '龚璛', '宋代', '竹影平寻月落时，小舟移岸半蒿迟。参差化作一匹练，我独寒篷亲见之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题横披竹' AND p.poem_author = '龚璛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东都望幸', '章碣', '唐代', '懒修珠翠上高台，眉月连娟恨不开。 \n 纵使东巡也无益，君王自领美人来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东都望幸' AND p.poem_author = '章碣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和郭从范二首 其二', '王质', '宋代', '萱草摇清风，榴英焰方午。新燕披紫茸，低昂子随母。\n\n暄寒换时节，浓疏变庭树。杜老痴不归，空怜小儿女。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和郭从范二首 其二' AND p.poem_author = '王质';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('禹庙 其二', '王铚', '宋代', '夏后东阶殡，遗踪照路隅。今观四山拱，犹似百神趋。\n\n功已百王冠，言尤万世谟。死生怀舜德，旧邑对姚虞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '禹庙 其二' AND p.poem_author = '王铚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('访朱仲开', '欧大任', '明代', '献岁灯初试，寻君正此时。尺书劳夙约，斗酒赴佳期。\n\n江上观涛色，淮南揽桂枝。自今能策马，闲过习家池。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '访朱仲开' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金钱花', '卢子发', '唐代', '轮廓休夸四字书，红窠写出对庭除。 \n 时时买得佳人笑，本色金钱却不如。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金钱花' AND p.poem_author = '卢子发';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('学书十绝 其四', '李之仪', '宋代', '闭门不语信深沉，岂可讥时作酒箴。料得门前无好事，解嘲聊复寄初心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '学书十绝 其四' AND p.poem_author = '李之仪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('臧郎中挽歌二首', '司马光', '宋代', '素履存诚厚，虚怀待物真。\n乡闾昔相接，朋友世弥亲。\n遗札蝇头强，长阡马鬣新。\n九原那可作，空复想音尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '臧郎中挽歌二首' AND p.poem_author = '司马光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠出塞客', '薛能', '唐代', '出郊征骑逐飞埃，此别惟愁春未回。 \n 寒叶夕阳投宿意，芦关门向远河开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠出塞客' AND p.poem_author = '薛能';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('减字木兰花九首 其六', '李慈铭', '清代', '记曾相见，帘里惊鸿留一盼。待得重逢，腰瘦眉浓两病中。\n\n恹恹春闷，带一分愁偏有韵。恁地聪明，假作无情更有情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '减字木兰花九首 其六' AND p.poem_author = '李慈铭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岑年伯见和步韵称谢并谢周莓厓都堂', '霍与瑕', '明代', '正月连阴三十朝，且喜今朝见日色。忽然仙老送歌来，照日读之光无极。\n\n既似明霞流玉宇，又如碧涧飘红雨。杏树枝枝漱露丹，桃花朵朵笼烟紫。\n\n笼烟漱露竞新妍，一度一看一可怜。学海翻波襄太华，词源滚浪拍天边。\n\n阳春古调徽音远，余欲和之风力软。惊看三峡斗狂澜，自笑江沱空婉转。\n\n东园花气隔帘闻，迢递柔风细雨匀。自是春光春思好，况逢诗句十分春。\n\n独怜碧眼看花早，昨日花开今已老。得高歌处且高歌，有旨酒无吾颇好。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岑年伯见和步韵称谢并谢周莓厓都堂' AND p.poem_author = '霍与瑕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春词二首', '张琰', '唐代', '垂柳鸣黄鹂，关关若求友。春情不可耐，愁杀闺中妇。 \n 日暮登高楼，谁怜小垂手。 \n 昨日桃花飞，今朝梨花吐。春色能几时，那堪此愁绪。 \n 荡子游不归，春来泪如雨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春词二首' AND p.poem_author = '张琰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('芙蓉花二首', '欧阳修', '宋代', '红芳晓露浓，绿树秋风冷。\n共喜巧回春，不妨闲弄影。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '芙蓉花二首' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉送戚都护归田四首', '陈第', '明代', '承平日久不知兵，南北征师浪结营。\n独有鸳鸯明节制，堂堂中国振先声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉送戚都护归田四首' AND p.poem_author = '陈第';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送侄合赴省试三首 其一', '张纲', '宋代', '破的雄乡国，担簦上帝京。路夷骧逸骥，天阔转飞鲸。\n\n学就千人敌，名归四海争。莫言年少在，岁月易峥嵘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送侄合赴省试三首 其一' AND p.poem_author = '张纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观莲', '胡天游', '元代', '清池莹人心，俯见荷叶背。南塘非不佳，无此青钱盖。\n\n沈沈古镜净，濯濯明妆对。凉风似留人，幽赏心独会。\n\n天公亦解事，一雨不破块。小呼巫阳云，浣此倾国态。\n\n高盘捧跳珠，错落无小大。恍疑逢二妃，迎笑争解佩。\n\n低昂巧簸弄，明月聚还碎。冯夷不相容，转盼何所在。\n\n人生总虚幻，伫立增叹慨。聊将一饷间，了我看花债。\n\n濂翁不我待，谁复同此爱。长啸归去来，馀芳满襟带。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观莲' AND p.poem_author = '胡天游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送杨辟同年', '刘敞', '宋代', '昔在谷子云，语妙气纵横。遨游五侯间，谈笑临公卿。\n\n丈夫伸知己，未必老一经。怀宝迷其邦，古人谁谓平。\n\n杨侯东州客，三岁不飞鸣。杂沓二府书，缤纷委弓旌。\n\n结靷西入关，长揖谢诸生。风霜岂不永，意气故自轻。\n\n伊昔惟一剑，蒯缑吐悲声。当令代舍长，见我珠履荣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送杨辟同年' AND p.poem_author = '刘敞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋风吟', '石宝', '明代', '惊飙振修麓，槁叶下乔林。怒号捲积霭，急转杨轻砧。\n\n翩翩孤凤雏，托身芳树阴。中夜感箫韶，激烈发清音。\n\n下有抱贞士，闻之援素琴。一弹南山高，再弹流水深。\n\n离鸾与别鹤，嘹唳声相寻。律吕转清切，壮怀伫萧森。\n\n谁言人生贵，无异巢中禽。得时应春鸣，遇寒亦哀吟。\n\n万动各有息，睹物悟人心。服我敝缊袍，安知辟寒金。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋风吟' AND p.poem_author = '石宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('牛首山夜饮', '吴金水', '当代', '豪筵未尽兴，乘夜上春山。径转松林下，樽开花影间。\n\n涧芳沾鬓重，月色上衣闲。可惜千杯罄，晓星相与还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '牛首山夜饮' AND p.poem_author = '吴金水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登乌石寺', '杨万里', '宋代', '回头身忽在树杪，一览千山万山小。\n怪崖不落欹欲摧，令人仰看怯眼开。\n小亭解事知侬倦，翼然飞出青山半。\n上头最上却镜平，百亩金碧千衲僧。\n高峰高寺更高阁，进步竿头若为脚。\n兹游胜绝庸非天，山下虚行二十年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登乌石寺' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('壶中天（客中寄友）', '张炎', '宋代', '西秦倦旅。是几年不听，西湖风雨。我托长镵垂短发，心事时看天语。吟箧空随，征衣休换，薜荔犹堪补。山能招隐，一瓢闲挂烟树。 \n 方叹旧国人稀，花间忽见，倾盖浑如故。客里不须谈世事，野老安知今古。海上盟鸥，门深款竹，风月平分取。陶然一醉，此时愁在何处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '壶中天（客中寄友）' AND p.poem_author = '张炎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吊柳司马祠二首 其一', '邓云霄', '明代', '长沙卑湿贾生悲，司马投荒远过之。万里瘴乡怜逐客，千秋风雅是吾师。\n\n愚溪草长无遗宅，钴鉧潭空有断碑。愁作招魂裁楚调，浅斟明水荐江蓠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吊柳司马祠二首 其一' AND p.poem_author = '邓云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿汤总领 其一', '郭印', '宋代', '春色平分又六宵，天生良弼佐皇朝。豸冠凛凛周行肃，虎节煌煌蜀地饶。\n\n已喜月卿还旧物，更看斗极转高标。仁人自合超诸数，鹤算龟龄未是遥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿汤总领 其一' AND p.poem_author = '郭印';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山中即事', '文天祥', '宋代', '携壶藉草醉斜阳，白鹤飞来月下双。\n芦叶西风惊别浦，芭蕉夜雨隔疏窗。\n千年帝子朱帘梦，一曲仙人铁笛腔。\n若问山翁还瘦否，手持渔竹下寒江。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山中即事' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题王仲序墨客诗卷', '胡奎', '明代', '王郎酒酣当墨池，五云飞落天孙机。河东美人织不得，仿佛八茧吴蚕丝。\n\n亲王召见蓬莱殿，天门白日飞龙见。中官传旨赐奚囊，王郎佩服生辉光。\n\n绛州陈玄最奇绝，落手麟胶三日香。梁园赋客邹枚老，爱尔尊前一倾倒。\n\n挥毫为写锦囊歌，愿尔千年赞王道。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题王仲序墨客诗卷' AND p.poem_author = '胡奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头 和张大经赋盆荷', '赵孟＊', '元代', '江湖渺何许，归兴浩无边。忽闻数声水调，令我意悠然。莫笑盆池咫尺，移得风烟万顷，来傍小窗前。稀疏淡红翠，特地向人妍。华峰头，花十丈，藕如船。那知此中佳趣，别是小壶天。倒挽碧筒酾酒，醉卧绿云深处，云影自田田。梦中呼一叶，散发看书眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头 和张大经赋盆荷' AND p.poem_author = '赵孟＊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汉玉秋蝉有雕檀木为蕉叶以承之者朅尔触兴率成是诗', '弘历', '清代', '谁制玉为蝉，谁刻木为叶。玉人与木工，本两不相涉。\n\n二物偶付托，讵是精神接。新蜩鸣绿阴，视此孰庄蝶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汉玉秋蝉有雕檀木为蕉叶以承之者朅尔触兴率成是诗' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答黄用砺明府', '卢龙云', '明代', '倦游敢道息图南，白社诗篇癖自耽。天地风尘元易厌，渔樵生计也曾谙。\n\n五湖新水供垂钓，三径閒云引盍簪。知尔玄言今既就，问奇谁复似桓谭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答黄用砺明府' AND p.poem_author = '卢龙云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋怀', '张自超', '清代', '大道自坦夷，于中生荆棘。扩清有古人，所贵无遗力。\n\n尧舜至今存，孔孟教不熄。世运或迁移，日月亦食昃。\n\n遁非圣贤心，剥犹天地德。霜风洗长林，群木涵新色。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋怀' AND p.poem_author = '张自超';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玲珑四犯', '陈允平', '宋代', '金屋春深，似灼灼娉婷，真真娇艳。洗净铅华，依旧曲眉丰脸。犹记舞歇凉州，渐缥缈、碧云缭乱。自玉环、宝镜偷换。别后甚时重见。 \n 鸾帏凤席鸳鸯荐。但空余、蕙芳兰蒨。天涯柳色青青恨，不入东风眼。惆账二十四桥，任落絮、飞花乱点。奈翠屏、一枕云雨梦，谁惊散。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玲珑四犯' AND p.poem_author = '陈允平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李沔阳自大梁经裕州因赠三首 其一', '王廷陈', '明代', '雪夜梁王宴，霜秋宋玉愁。回瞻嵩岳峙，去逐楚江流。\n\n少室三花树，沧浪一叶舟。南行正摇落，知尔忆林丘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李沔阳自大梁经裕州因赠三首 其一' AND p.poem_author = '王廷陈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪夜山行', '斯学', '明代', '孤舟疑入剡，夜绕乱山行。雪与月俱白，江因人更清。\n\n岚深寒气重，岸断冻痕平。况复人烟少，空闻落雁声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪夜山行' AND p.poem_author = '斯学';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戒事魔十诗 其四', '李兼', '宋代', '莫念双宗二会经，官中条令至分明。罪流更溢三千里，白佛安能救尔生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戒事魔十诗 其四' AND p.poem_author = '李兼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丙申元日五绝 其二', '方回', '宋代', '五更春雨细无声，石路溅泥齿屐鸣。后饮屠苏懒奔走，可能也喜鹁鸠晴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丙申元日五绝 其二' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答简夫', '孙应时', '宋代', '不怪年来万事非，聊须把酒赋新诗。\n乾坤正自无今昔，草木何妨有变衰。\n白发我甘投老去，红颜君惜卧春时。\n古人不朽终何事，此段工夫可浪施。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答简夫' AND p.poem_author = '孙应时';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和朱尉见招', '韦骧', '宋代', '作尉由来本仙局，况能投隙会僚朋。开怀自适人须美，治具虽疏客不憎。\n\n雨意初收天爽快，田工将毕岁丰登。高吟大饮无羞涩，祗恐秋风苦不胜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和朱尉见招' AND p.poem_author = '韦骧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大资政张公挽词四首 其四', '孙觌', '宋代', '辇路追高躅，联翩接两驺。犹蟠倚天剑，尚舣济川舟。\n\n元帅俄分阃，羁臣亦首邱。一抔相属地，回首涕交流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大资政张公挽词四首 其四' AND p.poem_author = '孙觌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('幽怀十二首 其六', '冯山', '宋代', '高架环四壁，古书浩万卷。腐儒坐相守，大义老不断。\n\n群言几可用，吾道一能贯。巨贤已经世，博士方浩叹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '幽怀十二首 其六' AND p.poem_author = '冯山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十三日夜山斋玩月', '舒岳祥', '宋代', '月傍细细水波云，绣撚金描孔翠纹。夜半冰轮悬净碧，太空不动扫魔群。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十三日夜山斋玩月' AND p.poem_author = '舒岳祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送诸乡人赴试南宫', '吴芾', '宋代', '闻道诸君上玉京，一杯聊复话离情。青钱既中三年选，黄鹄须看万里程。\n\n欲向他时成远器，要从今日立修名。吾君锐意图兴复，好把嘉言对集英。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送诸乡人赴试南宫' AND p.poem_author = '吴芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻命有感 其一', '王世贞', '明代', '还留上宰翊皇朝，天阔春风处处饶。自是清时宽去就，百年兄弟好渔樵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻命有感 其一' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王郎中妓席五咏。舞', '顾况', '唐代', '汗浥新装画不成，丝催急节舞衣轻。 \n 落花绕树疑无影，回雪从风暗有情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王郎中妓席五咏。舞' AND p.poem_author = '顾况';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荷叶杯·本意', '曾廉', '清代', '几幅珠帘翠箔，笙歌声拥白头翁。海霞色映一杯红。\n\n衰老发春容。无限荷花荷叶，池中百子已成空。只今曲岸已梧桐。\n\n叶叶向秋风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荷叶杯·本意' AND p.poem_author = '曾廉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('师子颂贺新住持', '成鹫', '明代', '大哉大法王，出为众生父。大哉大师王，生为百兽主。\n\n法王师子王，不隔毛头许。谛观法王法，请听师子语。\n\n师子初生时，周行方七步。师子学语时，嚬呻振威怒。\n\n师子转身时，返掷还超距。师子独行时，彳亍无伴侣。\n\n师子出山时，鬼神默诃护。狮子奋迅时，波旬生恐怖。\n\n师子踞座时，龙象如环堵。师子蹴踏时，野干神气沮。\n\n有耳闻未闻，有目睹未睹。咸聆师子吼，快观师子舞。\n\n师子舞若何，神力庄严具。一舞入法界，再舞净法土。\n\n三舞转法轮，四舞酬法乳。五舞吹法螺，六舞击法鼓。\n\n七舞布法云，八舞施法雨。九舞转法灯，十舞弘法绪。\n\n师子慧命长，师子法身固。宝山大好山，午天正亭午。\n\n徽猷振古今，威光耀寰宇。师子复师子，记莂生补处。\n\n千秋巩化城，天龙领八部。万古演法音，频伽及鹦鹉。\n\n顽牛老更顽，头角无所取。长歌寄法筵，灯笼触露柱。\n\n应作如是观，应作如是举。要识师子真，须明向上句。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '师子颂贺新住持' AND p.poem_author = '成鹫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题妙高峰', '冷士嵋', '明代', '天拔一峰起，波空四面开。江光浮岛屿，潭影浸楼台。\n\n折苇番僧渡，乘槎海客来。何须更壶峤，此地即蓬莱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题妙高峰' AND p.poem_author = '冷士嵋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('除夕李伯襄陈集生崔芝林过余守岁拈银烛朝天紫陌长用四平声 其一', '何吾驺', '明代', '河光寒影渐生新，更傍今宵酌故人。梦去还疑居木石，望来宁复辨金银。\n\n异时踪迹吾多懒，同调知交尔任真。约略敝衣堪卒岁，十千酤酒候明春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '除夕李伯襄陈集生崔芝林过余守岁拈银烛朝天紫陌长用四平声 其一' AND p.poem_author = '何吾驺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送太守李公', '陈天麟', '宋代', '乱花翻阵雨，飞絮转轻球。\n别思昏如醉，征鞍挽不留。\n职循今列郡，秩视古诸侯。\n当代人争仰，惟公政最优。\n洋川佳景物，胜迹旧经游。\n未定中原扰，犹怀傍塞忧。\n九重爰锡命，千里藉承流。\n德逐祥云偃，恩随瑞霭浮。\n带刀还陇亩，挟纩动貔貅。\n烽柝开边月，犁锄庆麦秋。\n二天舒士气，五裤沸民讴。\n虞氏三年考，河南第一州。\n霜台方荐墨，黼座想凝旒。\n早晚颁纶綍，东西走置邮。\n迟迟姑去鲁，几几定归周。\n明月湖光远，凌云气象幽。\n烟波浮画鷁，雪浪绕乌牛。\n好逐桃花涨，轻飞竹叶舟。\n径归调玉铉，莫待覆金瓯。\n贱吏伤萍梗，终年仰庇休。\n龙门曾御李，骥坂会依刘。\n不作痴儿女，孜孜话别愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送太守李公' AND p.poem_author = '陈天麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('踏莎行三首 其二', '程滨', '当代', '一地残花，满枝禁果。卅年踽踽吾将跛。黑貂裘敝夜风寒，人间岂有真天火。\n\n无可如何，如何不可。镜中万象无非我。自由无过我灵魂，灵魂长向微躯锁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '踏莎行三首 其二' AND p.poem_author = '程滨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苦旱 其三', '韩淲', '宋代', '孤坐焦心气不苏，炎风畏景逼头颅。涧流已断无萍实，园圃俱荒失芋区。\n\n絺绤纵施衣复汗，简编虽近墨难濡。人嘲褦襶交游绝，头白昏昏发懒梳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苦旱 其三' AND p.poem_author = '韩淲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄怀东林寺匡白监寺', '齐己', '唐代', '南岳别来无约后，东林归住有前缘。闲搜好句题红叶， \n 静敛霜眉对白莲。雁塔影分疏桧月，虎溪声合几峰泉。 \n 修心若似伊耶舍，传记须添十九贤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄怀东林寺匡白监寺' AND p.poem_author = '齐己';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('积素', '弘历', '清代', '积素龙楼晓景澄，霓鸾振迅月娥仍。练光破腊披鸿鹊，线晷回春映绢㲪。\n\n冻结钉头珠复密，霤垂瓦齿滴还凝。氤氲未肯全消日，为扣重檐玉几层。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '积素' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('葑门水亭观荷四章 其三', '姚燮', '清代', '一镜晴漪漾软罗，倾脂莫问旧时河。横桥断处沽帘出，画阁明边鬓影多。\n\n可惜鸳鸯无次第，尽渠杨柳自婆娑。罗裳窣窣谁家子，置簟蘋阴枕绿哦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '葑门水亭观荷四章 其三' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绿岛怀古', '张海鸥', '当代', '绿岛夜朦胧，寒鸦绕碧丛。徘徊思汉土，惆怅觅蓑翁。\n\n兴废千秋事，沧桑一令中。当时池畔月，仍照旧亭东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绿岛怀古' AND p.poem_author = '张海鸥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送太平路同知王庭珍', '陶安', '明代', '隔江尘起动边声，采石波涛夜不惊。台鼎调元延世赏，倅车佐守厚民生。\n\n近来壁垒添烽火，未见天河洗甲兵。月满空船归思切，望中桑梓是东平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送太平路同知王庭珍' AND p.poem_author = '陶安';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和陈允崇登定山', '庄昶', '明代', '万里风光散远林，晚峰羸马正千寻。手中日月丸天地，眼底风云变古今。\n\n几笔化工山水趣，五经尼父圣贤心。可堪白首犹多病，老凤西周意自深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和陈允崇登定山' AND p.poem_author = '庄昶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陪祀山陵二首 其一', '宗臣', '明代', '阊阖门重启，星辰地一隅。寂寥群籁动，惨淡百灵趋。\n\n剑佩当风乱，松楸上月孤。他年神武气，或恐未荒芜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陪祀山陵二首 其一' AND p.poem_author = '宗臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再送左辖吴公十绝句 其二', '胡应麟', '明代', '白头徒自新，倾盖俨如故。蔽芾越东西，棠阴十万户。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再送左辖吴公十绝句 其二' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('来青轩和玉溪韵', '陆深', '明代', '磴转峰回年复年，古藤乔木暗流泉。西天正在西窗外，一片青青落照前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '来青轩和玉溪韵' AND p.poem_author = '陆深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居 其二', '张家珍', '明代', '危峰削壁翠千寻，一啸遥传空谷音。天地正当戎马日，声名何与蕨薇心。\n\n溪桥曲折随山势，松树参差碍日阴。归去西林馀兴在，洞门萝月照弹琴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居 其二' AND p.poem_author = '张家珍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵和子思舅', '毕仲游', '宋代', '闻说幽居傍北溪，莫将归思作新诗。未为野客随翁去，应被山僧笑我痴。\n\n近日病中为酒敌，他年物外得禅师。林泉漫有花开约，借马相从能几时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵和子思舅' AND p.poem_author = '毕仲游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄郭筠仙浙江四首', '曾国藩', '清代', '向晚严需破屋寒，娟娟纤月倚檐端。\n自给行箧殷勤觅，苦索家书展转看。\n宦海情怀蝉翼薄，离人心绪茧丝团。\n更怜吴会飘零客，纸帐孤灯坐夜阑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄郭筠仙浙江四首' AND p.poem_author = '曾国藩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诫后学', '释智圆', '宋代', '对食须思稼穑劳，为僧安用事雄豪，\n剃头本意求成佛，不为齐筵坐位高。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诫后学' AND p.poem_author = '释智圆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('昭君', '崔荣江', '当代', '大漠关山隔一涯，肯教箫笛换胡笳。兹心犹系沧浪水，汉月明时许浣纱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '昭君' AND p.poem_author = '崔荣江';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('钟子建才美而文有怀高云白之作社中人为和章余亦步韵二律代高子赋答二首 其一', '何巩道', '明代', '芳树亭亭玉不如，思君何事久离居。岂怜蝴蝶迷庄子，难得蒹葭倚太初。\n\n对镜远山朝霭霭，入弦流水夜徐徐。不须帝子临湘渚，别有愁怀渺矣余。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '钟子建才美而文有怀高云白之作社中人为和章余亦步韵二律代高子赋答二首 其一' AND p.poem_author = '何巩道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈一百二十首 其三十九', '释怀深', '宋代', '十一月二十，唤做大冬日。张三贺郑婆，李四拜王七。\n\n早辰到夜，费尽平生力。唯有衲僧家，不打者鼓笛。\n\n铁额昆崙儿，通身黑如漆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈一百二十首 其三十九' AND p.poem_author = '释怀深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂咏 烛', '谢朓', '南北朝', '杏梁宾未散。\n桂宫明欲沉。\n暧色轻帏里。\n低光照宝琴。\n徘徊云髻影。\n的烁绮疏金。\n恨君秋月夜。\n遗我洞房阴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂咏 烛' AND p.poem_author = '谢朓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('茶磨山', '潘曾莹', '清代', '系缆行春桥，策杖茶磨岭。烟鬟浸湖渌，开奁晓妆靓。\n\n飞鸟没何处，了了见帆影。秀色接楞伽，窅然异尘境。\n\n杂花不知名，香气幽且静。微风淡疏襟，斜阳恋余景。\n\n徘徊松桂阴，翠泼秋衫冷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '茶磨山' AND p.poem_author = '潘曾莹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十六罗汉赞', '释心月', '宋代', '飞锡五天云冉冉，泛杯南海浪悠悠。\n一毫头上轻收拾，不是冤家不聚头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十六罗汉赞' AND p.poem_author = '释心月';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送陈天卿兄弟归豫章', '卢龙云', '明代', '千里冲寒访旧劳，片帆南望趁江涛。雌雄斗下皆龙气，颉颃云间总凤毛。\n\n归路不辞乡国远，德星重聚里门高。传家清白真无忝，赠尔谁方范叔袍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送陈天卿兄弟归豫章' AND p.poem_author = '卢龙云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵雨丝云鹤二首 其二', '黄庭坚', '宋代', '几片云如薛公鹤，精神态度不曾齐。安知陇鸟樊笼密，便觉南鹏羽翼低。\n\n风散又成千里去，夜寒应上九天栖。坐来改变如苍狗，试欲挥毫意自迷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵雨丝云鹤二首 其二' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('定风波 其一 潜山驿寄答佟艾生方伯', '周之琦', '清代', '飏鞭丝、几阵西风，人烟小市吹暝。古驿延秋，虚堂款客，暂得羁魂定。\n\n翠云深，玉沙净。恰好灊庐秀眉映。幽兴。负松乔旧约，携琴萝径。\n\n素襟漫整。任缁尘、黯澹残痕凝。向银笺，拂处寒香袖裛，岁晚心期订。\n\n倚清吟，背窗影。缥晕灯摇半花冷。还省。一声新雁、江南谁听。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '定风波 其一 潜山驿寄答佟艾生方伯' AND p.poem_author = '周之琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('明月入我牖', '李复', '宋代', '明月入我牖，娟娟满衣裳。\n惊风飘疏竹，凌乱舞清光。\n静坐不能眠，稍知秋夜长。\n却思古人书，探编开缥囊。\n一读三四反，人远心茫茫。\n投编出庭宇，回步影徜徉。\n长空散白露，暗落点青黄。\n肃肃晨气动，满地自为霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '明月入我牖' AND p.poem_author = '李复';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长干寺同刘宫苑浴 其一', '张舜民', '宋代', '人看浴出如枯木，我自无心类死灰。在处秋风吹鬓发，不堪更上雨花台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长干寺同刘宫苑浴 其一' AND p.poem_author = '张舜民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦中麓子', '康海', '明代', '积雨晦皋陆，我车不可前。徘徊望北墅，迤逦横云烟。\n\n退坐草堂下，篱菊灿且妍。节物忽将改，引杯吟太元。\n\n微醉体亦倦，梦谒九华天。仙人中麓子，揖予出素编。\n\n云是广成撰，孰能叩其筌。忆昔魏伯阳，谓我骨当仙。\n\n苦逐世人好，落魄武亭川。缘业殆将满，数命或有然。\n\n始思饮刀圭，却老觅长年。语既执我手，欢笑极周旋。\n\n振袖出两药，光如朝日鲜。挹彼松露下，同吞各一圆。\n\n五内倏清爽，神采非昔焉。我居太白下，君庐太山颠。\n\n采芝拾瑶草，餐玉茹井莲。欲会但瞬息，跨鹤何翩翩。\n\n赤松作参伍，玉女侍几筵。翛然万物表，世网安可牵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梦中麓子' AND p.poem_author = '康海';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜芾奎二侄延师教子', '沈周', '明代', '俗习务浅鄙，养子多昩教。且云粗识姓，便是学之要。\n\n学岂止识字，要在知人道。人道重纲常，文艺稍加膏。\n\n爱子若不教，护病不医疗。往往岁月后，历历见狠傲。\n\n孝悌莽无知，礼义蔑循蹈。辱父辱门第，至此徒悔懊。\n\n此过不在子，在父长其暴。能教始为爱，教成自有效。\n\n不可吝鞭挞，不可恕幼少。今年贺美事，二侄改俗调。\n\n令子从师儒，诗书发蒙冒。此举足高尚，先绪喜可绍。\n\n譬谷既历舂，白粲脱黄糙。又譬金溷沙，披汰金乃耀。\n\n愿言勿中画，进进有远到。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜芾奎二侄延师教子' AND p.poem_author = '沈周';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答无可', '马之瑛', '清代', '军府迎降先署状，仰视飞鸿剧惆怅。彦回名士寿偏多，子卿足下归无恙。\n\n故国千峰可寄家，兜鍪原不妒袈裟。金陵旧恨空沈锁，宰相新堤自筑沙。\n\n国成谁秉邦离析，党祸亦由君子激。林宗何必独仙舟，宾硕谁能共复壁。\n\n烽烟几载历江湖，万死全凭佛力扶。游子尚堪依母隐，仇人俱己伏天诛。\n\n素心自指井中水，任是波澜风不起。入社何妨有白衣，误人不信皆青史。\n\n我亦云林学驾车，风流翻令业因加。为语山灵休见拒，从君还一转莲花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答无可' AND p.poem_author = '马之瑛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小阑干 其一 国历除夕', '章士钊', '当代', '长安城里一家家。阑夜阒无哗。何氏山林，却来招惹，火树一园花。\n\n江南相识趁蜂衙。坐久不回车。堂上簸钱，房中度曲，年时劣堪夸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小阑干 其一 国历除夕' AND p.poem_author = '章士钊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('娟娟昨夜月今宵看已圆待得明宵见宿昔定殊观月明有圆𡙇世事杂悲欢良时那可掷徘徊清夜阑', '朱浙', '明代', '攀折河边柳，还渡柳边桥。短发不堪把，月明影潇潇。\n\n穷居远城市，残生付渔樵。翘首望八荒，天宇高寥寥。\n\n狂歌自成章，聊以娱今宵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '娟娟昨夜月今宵看已圆待得明宵见宿昔定殊观月明有圆𡙇世事杂悲欢良时那可掷徘徊清夜阑' AND p.poem_author = '朱浙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('野史口号碑四十四首 其十六', '刘鹗', '元代', '贼兵欲向翁源洞，纠合官陂来打韶。此策若行诚可虑，南雄唾手可能招。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '野史口号碑四十四首 其十六' AND p.poem_author = '刘鹗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('啮指题壁', '胡妙端', '元代', '弱质空怀漆室忧，搜山千骑入深幽。旌旗影乱天同惨，金鼓声淫鬼亦愁。\n\n父母劬劳何日报，夫妻恩爱此时休。九泉有路还归去，那个云边是越州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '啮指题壁' AND p.poem_author = '胡妙端';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送吴亚卿复致政归螺江', '陈炜', '明代', '五十馀年任畏途，尔来归兴逐莼鲈。风摇双佩辞三殿，云引孤帆入五湖。\n\n荔酒醉眠花下榻，茶烟吹起竹边厨。白头富贵人间少，况复身閒一事无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送吴亚卿复致政归螺江' AND p.poem_author = '陈炜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登姑苏台怀古', '张羽', '元代', '荒台独上故城西，辇路凄凉草树迷。废冢已无金虎踞，坏墙时有夜乌啼。\n\n采香径断来麋鹿，响屟廊空变蒺藜。欲吊伍员何处是，淡烟斜日不堪题。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登姑苏台怀古' AND p.poem_author = '张羽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白发', '白居易', '唐代', '雪发随梳落，霜毛绕鬓垂。加添老气味，改变旧容仪。 \n 不肯长如漆，无过总作丝。最憎明镜里，黑白半头时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白发' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上山', '刘崧', '明代', '上山望大河，旗帜十馀里。不知何处村，但见青烟起。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上山' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送朗公讲解还越', '皇甫汸', '明代', '开教逢鸠什，谈经得马鸣。坐中窥有相，言下了无生。\n\n法雨和香气，天花落梵声。归时多宝就，刊石为垂名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送朗公讲解还越' AND p.poem_author = '皇甫汸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏成白发二首', '张镃', '宋代', '怕见人言老，梳头夜二更。\n谁知灯烛夜，漏逗愈分明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏成白发二首' AND p.poem_author = '张镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('河津观龙门歌', '冯敏昌', '清代', '惊涛殷地声如雷，濒河路折听喧豗。连天烟雾不知数，西望一气连峰开。\n\n峰如连牛亦奇哉，岂谓河自峰腰来。骑危路转峰还回，地穷转石蹶斯下，天成巨闬高何嵬。\n\n仰看铁壁形如隤，俯积云气容如灰。想像昆仑万里导源至此偪拶不得出，丰隆列缺乃驱应龙画地鼓翼掉尾扬其颏。\n\n厓开巘豁奚迟回，山口一石门还阂。谁令千丈势忽断，真见当时指麾万众雷辊电激轰钳锤。\n\n河流怒喷风回埃，建瓴一泻无垠垓。长澜千里更东下，高掌万仞从西摧。\n\n吁嗟神功安可能，云雷合赖经纶才。试观千秋万古山童水不竭，于中禹迹令人慨想心徘徊。\n\n山前古庙临危台，降神拜奠倾云罍。云松绕屋鸣作籁，龙蛇满壁昏成煤。\n\n一从洒澹诸沈灾，何意逝水还相催。淇园竹竿下不尽，宣房瓠子空悲哀。\n\n我愿元气深滋培，权衡迭运兼公台。济川舟喜盛世见，清河颂许诗人裁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '河津观龙门歌' AND p.poem_author = '冯敏昌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('折花赠内并代答二首 其二', '杨基', '明代', '一朵折春风，花浓意更浓。而今映花面，不似向时红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '折花赠内并代答二首 其二' AND p.poem_author = '杨基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('我质本瑚琏，宗庙供频蘩。一朝婴祸难，失身', '韩希孟', '宋代', '宁当血刃死，不作衽席完。\n汉上有王猛，江南无谢安。\n长号赴洪水，激烈摧心肝。\n宋夫有天下，坚正臣礼秉。\n开国百战功，每阵惟雄整。\n及侍周幼主，臣主常炯炯。\n帝曰卿北伐，山戎今有警。\n死狗莫系尾，此行当系颈。\n即日辞陛下，尽敌心欲逞。\n陈桥忽兵变，不得守箕颍。\n禅让法尧舜，民物普安静。\n有国三百年，仁义道驰骋。\n未改祖宗法，天胡肆大眚。\n细思天地理，中有幸不幸。\n天果丧中原，大似裂冠衽。\n君诚不独活，臣实无魏丙。\n失人焉得人，垂戒尝耿耿。\n江南无谢安，塞北有王猛。\n所以戎马来，飞渡巴陵境。\n大江限南北，今此一舴艋。\n本期固封疆，谁谓如画饼。\n烈火燎昆冈，不辩金玉矿。\n妾本良家子，性僻守孤梗。\n嫁与尚书儿，衔署紫兰省。\n直以才德合，不弃宿瘤瘿。\n初结合欢带，誓比日月昺。\n鸳鸯会双飞，比目愿长并。\n岂期金石坚，化作桑榆景。\n旄头势正然，蚩尤气先屏。\n不意风马牛，复及此燕郢。\n一方遭劫虏，六族死俄顷。\n退鹢落迅风，孤鸾吊空影。\n簪坚折白玉，瓶沉断青绠。\n一死空冥府，忧心长炳炳。\n意坚志不移，改邑不改井。\n我本瑚琏器，安肯作溺皿。\n志节匪转石，气噎如吞鲠。\n不作爝火燃，愿为死灰冷。\n贪生念麹蛾，乞邻羞虎穽。\n借此清江水，葬我全首邻领。\n皇天如有知，定作血面请。\n愿魂化精卫，填海使成岭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '我质本瑚琏，宗庙供频蘩。一朝婴祸难，失身' AND p.poem_author = '韩希孟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乳燕飞（次徐斯远韵寄稼轩）', '黄机', '宋代', '兴泼元同宇。唤君来、浮君大白，为君起舞。满袖斑斑功名泪，百岁风吹急雨。愁与恨、凭谁分付。醉里狂歌空漫触，且休歌、只倩琵琶诉。人不语，弦自语。 \n 诗成更将君自赋。渺楼头、烟迷碧草，云连芳树。草树那能知人意，怅望关河梦阻。有心事、笺天天许。绣帽轻裘真男子，政何须、纸上分今古。未办得，赋归去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乳燕飞（次徐斯远韵寄稼轩）' AND p.poem_author = '黄机';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七歌效杜陵体 其一', '丘葵', '宋代', '景炎元年北人至，撒花初令豪家备。谁梯祸乱敷我民，敲朴日烦无处避。\n\n富者有银犹可苏，贫者无银卖田地。呜呼一歌兮歌已衰，天日不见惟阴霾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七歌效杜陵体 其一' AND p.poem_author = '丘葵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠故乡人', '沈括', '宋代', '我家已破出他乡，如连如卓方阜昌。岂料囊金随后散，一齐开铺鬻文章。\n\n我今滨死秪如许，二友犹堪望轩翥。从头借问向来谁，十室九人非旧主。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠故乡人' AND p.poem_author = '沈括';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵全希言学士', '董纪', '明代', '慎言玷可磨，学道坚可钻。垩尽鼻不伤，唇亡齿先寒。\n\n得丧本前定，居俟何后患。终南径虽捷，蜀道行转难。\n\n至理岂云远，在人方寸间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵全希言学士' AND p.poem_author = '董纪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鼓山颂法眼语在里即求出云大家合眼跳黄河戏成四韵奉答', '吕本中', '宋代', '合眼跳黄河，未有过得者。岂惟不得过，身亦须判舍。\n\n告君过河妙，止要具船筏。乘时等风去，过此无别法。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鼓山颂法眼语在里即求出云大家合眼跳黄河戏成四韵奉答' AND p.poem_author = '吕本中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春意渐深送客至山麓田舍来往道中复逢法上人', '释正觉', '宋代', '华蹊归来鸟啼幕，庖舍炊烟卧风缕。\n西窗旧有竹肋床，伸足曲肱成栩栩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春意渐深送客至山麓田舍来往道中复逢法上人' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽张正甫二首', '陈著', '宋代', '别来倏忽一周星，君住家林我泛萍。\n到处逢人问梅坦，有时见梦说兰亭。\n自怜倦翼归迟暮，已报清魂入杳冥。\n多少微言今已矣，义难辞处写为铭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽张正甫二首' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭黄后峰大理次伍松月韵四首 其二', '王缜', '明代', '希声高举似鸣岐，棘寺平反未几时。忽尔庄鹏成羽化，伤哉贾鵩促神思。\n\n衣冠寂寂魂归土，风雨萧萧旐引輀。恐是玉楼成得早，天公命召有程期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭黄后峰大理次伍松月韵四首 其二' AND p.poem_author = '王缜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古柏行', '傅义', '当代', '马祖寺中二株柏，祖师开山手亲植。人间风雨越千年，楼宇废兴几经历。\n\n今惟巨柱撑晴空，旧诚易破新难立。古柏巍然俯残棋，默无一语暗太息。\n\n菩提空羡了无踪，中华良种永犹龙。龙钟不改淩云势，神力不及造化功。\n\n伟干凝重如崇阜，高枝摇碧傲东风。三生因果思维外，八极风云指顾中。\n\n香叶久无鸾凤宿，古遗犹令人肃穆。一株中空沃泥浆，不许风霜侵大腹。\n\n一株鞠躬若朝参，钢架扶持添劲足。吾儒自昔爱甘棠，心向往之目未瞩。\n\n我向伟材三顶礼，庆幸崚嶒今犹矗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古柏行' AND p.poem_author = '傅义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与定华步行至学海书楼', '佟绍弼', '近代', '拾阶石磴前，强行不知倦。路从艰苦来，才得平易转。\n\n忽如置绝顶，胸次纳万变。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与定华步行至学海书楼' AND p.poem_author = '佟绍弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李侯新作秋水亭可望松萝诸山客有遗之沈石田画者正会此意', '程敏政', '明代', '蓦地萝山为写真，石田毫素妙通神。閒来秋水亭中坐，便是丹青个里人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李侯新作秋水亭可望松萝诸山客有遗之沈石田画者正会此意' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阿克苏', '王曾翼', '清代', '锁钥两城连，佳哉望郁然。岩疆望乌什，间道走和田。\n\n地扼襟喉要，人夸贸易便。商多三晋客，货溢百间廛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阿克苏' AND p.poem_author = '王曾翼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬夜閒吟', '弘历', '清代', '良夜渐添长，斗杓亦旋北。旌门笳吹奏，大野人声息。\n\n归辔辞沈阳，乘舆指京国。毡庐坐閒窗，可爱新月色。\n\n差无尘念萦，微觉轻寒逼。关山巡阅多，历历皆堪忆。\n\n扬鸾和铃中，玉律忽已易。悠悠今古人，趁此驹过隙。\n\n百年讵云久，寸阴实可惜。际兹清宵佳，况对寒蟾碧。\n\n金鸭已结篆，银檠半折堲。却似去冬夜，梅香递宣席。\n\n所志嗟无成，所学曾何得。惟馀此初心，时时自兢惕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬夜閒吟' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荷池夏雨', '吕渊', '明代', '新凿荷池引水通，雨深花满趣无穷。盘倾珠颗齐翻翠，衣露霞绡半折红。\n\n四座凉生风细细，一帘香沁雾濛濛。此中清景真堪赏，何必移家住瀼东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荷池夏雨' AND p.poem_author = '吕渊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春兴 其一', '朱诚泳', '明代', '满眼春云合又开，名园处处锦城堆。丁宁好为张油幕，恐有游人冒雨来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春兴 其一' AND p.poem_author = '朱诚泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿陈松师相公 其二', '王弘诲', '明代', '铜龙紫气浮朱绂，金阙祥光隐碧纱。笃行汉庭推石氏，雄文西蜀迈苏家。\n\n蟠桃露缀丹盘冷，玉树风垂彩袖斜。燮理万方同寿域，蓬壶冰月湛流霞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿陈松师相公 其二' AND p.poem_author = '王弘诲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郊庙歌辞。太清宫乐章。第二奏', '佚名', '唐代', '虚极仙宗本，希夷象帝先。百灵朝太上，万法祖重圆。 \n 善贷惟冲德，功成谓自然。云门达和气，思用合钧天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郊庙歌辞。太清宫乐章。第二奏' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('莆阳郡斋观物有感 其三', '岳正', '明代', '石泓近日小鱼游，云起风生水更幽。抛饭饲时争出没，胡僧过说是灵湫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '莆阳郡斋观物有感 其三' AND p.poem_author = '岳正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗·秋风何冽冽', '左思', '魏晋', '秋风何冽冽，白露为朝霜。\n柔条旦夕劲，绿叶日夜黄。\n明月出云崖，皦皦流素光。\n披轩临前庭，嗷嗷晨雁翔。\n高志局四海，块然守空堂。\n壮齿不恒居，岁暮常慨慷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗·秋风何冽冽' AND p.poem_author = '左思';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自咏十律 其五', '丁鹤年', '元代', '堂堂至正最多才，万国同文寿域开。漠北诸生登第去，越南计吏进贤来。\n\n凤《韶》九奏黄金殿，鹤驾三朝白玉台。回首黄尘扬碧海，五云无处觅蓬莱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自咏十律 其五' AND p.poem_author = '丁鹤年';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('隋书十首 其八 柳䛒', '郑学醇', '明代', '麟阁曾闻尽世臣，柳䛒恩宠更无伦。内庭夜宴虚明月，不见词人见偶人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '隋书十首 其八 柳䛒' AND p.poem_author = '郑学醇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('脩竹二首 其一', '晁公溯', '宋代', '虚窗倚脩竹，阴晴见佳景。雨隙落馀滋，风棂乱疏影。\n\n室幽境自閒，心远地愈静。丁宁护云根，留伴岁寒永。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '脩竹二首 其一' AND p.poem_author = '晁公溯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪夜思南山禅友', '德祥', '明代', '夕雪洒虚堂，禅身懒下床。楮衾清不暖，蜡烛冷无光。\n\n宿鸟争枝响，寒花上路香。南山有兄弟，岁晚不能忘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪夜思南山禅友' AND p.poem_author = '德祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('锦缠道 初度', '梁清标', '明代', '冰雪柴门，寂寞岁寒时候。跳双丸、悬弧今又。风尘澒洞人非旧。\n\n剩得闲身，浪逐烟波叟。叹种种颠毛，不堪回首。春酿熟、好烹羔剪韭。\n\n佳人翠袖殷勤，且主盟花月，漫说经纶手。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '锦缠道 初度' AND p.poem_author = '梁清标';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王倅成老挽诗二首', '王炎', '宋代', '珠玉山渊润，仁人久里居。\n低徊尝结绶，强健即垂车。\n长厚皆堪法，循良亦可书。\n惜哉怀远业，小试只题舆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王倅成老挽诗二首' AND p.poem_author = '王炎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('踏莎行 观昆曲牡丹亭', '程滨', '当代', '一地秋阳，满堂春醉。乱花深处飘长袂。多情挽住美人腰，芳心贮得书生泪。\n\n四百年前，梦中相对。今生邂逅偏无寐。人间又是一千年，可能重向花间睡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '踏莎行 观昆曲牡丹亭' AND p.poem_author = '程滨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过涧', '华镇', '宋代', '两山分处水横流，渡水登山趣更幽。却忆当年谢康乐，等閒羁束为封侯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过涧' AND p.poem_author = '华镇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('溪行', '韩淲', '宋代', '突兀荒荒漫挈瓶，泓澄窈窈且扬舲。隔山鸡犬三家聚，近水鱼虾一岸腥。\n\n说梦休誇巫峡赋，移文何愧草堂灵。交游少得亲相识，临眺多为旧所经。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '溪行' AND p.poem_author = '韩淲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赋得临池柳', '梁有誉', '明代', '拂岸青阴合，萦堤翠色稠。声从笛里听，影傍镜中浮。\n\n水与柔情漾，波将舞态留。腰肢怜楚细，眉黛学孙愁。\n\n濯濯恒笼雾，依依讵奈秋。堪怜张绪去，谁复拟风流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赋得临池柳' AND p.poem_author = '梁有誉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('表叔萧二尹诞日', '符锡', '明代', '采采东篱菊，时序忽巳遒。翳翳丹枫日，云屋蔽且幽。\n\n命盒道西家，振衣由东陬。丈人息虑久，兹晨聊共酬。\n\n壶悬动星彩，钥启祥光浮。中有绿发翁，烱烱方双眸。\n\n起酌为君寿，祝君寿千秋。千秋亦何有，造物终与游。\n\n猥予蓬室士，眷此难力求。逝将叩去虚，策驾迷丹丘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '表叔萧二尹诞日' AND p.poem_author = '符锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚步独至西三首', '李弥逊', '宋代', '我来点检春踪迹，山北山南绿暗丛。\n留与骚人做秋本，花根一点著泥红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚步独至西三首' AND p.poem_author = '李弥逊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送吕光禄', '刘敞', '宋代', '泛滥诚易挹，俊贤噬肯留。愧君殊邂逅，卒岁能优游。\n\n会心到稽吕，访古穷嬴刘。谁令春风来，翩翩动归舟。\n\n千里在明发，一樽成献酬。江湖望魏阙，离思空悠悠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送吕光禄' AND p.poem_author = '刘敞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风雨', '施枢', '宋代', '入夏惟忧旱，秋来却浸霪。\n风声连海响，山气与云深。\n望岁丹心切，忧时白发侵。\n旅中无别事，隐几自长吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风雨' AND p.poem_author = '施枢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '缪瑜', '宋代', '有客去游丞相阁，无人来问孝廉船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '缪瑜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('朱上舍自天读予悼耕岩未葬诗而蹙然请以明年任之喜而有作', '全祖望', '清代', '徵君未死日，破戒受兼金。为葬钟山骨，馀投濑水阴。\n\n清芬犹未泯，高谊更谁寻。一诸来孤凤，微生慰素心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '朱上舍自天读予悼耕岩未葬诗而蹙然请以明年任之喜而有作' AND p.poem_author = '全祖望';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('张家湾东遇王参政德华', '邵宝', '明代', '晋溪北上我南游，潞水东头半日留。何处可忘君父念，此行须为庙堂谋。\n\n百年雅颂知能夏，千里歌讴望有秋。指日王师收战绩，勿言江左旧风流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '张家湾东遇王参政德华' AND p.poem_author = '邵宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('𨹁山顶上度重阳节 其二', '吕师濂', '清代', '吴越如今霜桕肥，炎方且得缓寒衣。但违吾土登楼倦，欲笑参军落帽非。\n\n客重屠沽投臭味，秋谁瘦健向庭闱。东来一片伤心雁，恐有乡书莫即飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '𨹁山顶上度重阳节 其二' AND p.poem_author = '吕师濂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('即席赋得梨分韵无字', '王世贞', '明代', '汉广偶萍实，南中饶木奴。上林还见品，大谷未全无。\n\n高露屑金掌，寒冰飞玉壶。长卿故游倦，消渴暂应苏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '即席赋得梨分韵无字' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感遇 其三', '郑梦周', '明代', '淳风去已远，世道日幽昧。征伐降殷周，祥麟竟遇害。\n\n凤凰化鸡鹜，兰蕙为萧艾。嗟哉孔与孟，天意屡颠沛。\n\n时运既如此，生民复何赖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感遇 其三' AND p.poem_author = '郑梦周';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('楮衾用贯酸斋芦花被韵', '邓雅', '明代', '楮衾如雪绝纤尘，稳卧还须藉布茵。一片白云松下榻，五更明月梦中身。\n\n惟应纸帐堪同调，祗恐梅花亦笑贫。赢得素风含混沌，夜寒一煦便回春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '楮衾用贯酸斋芦花被韵' AND p.poem_author = '邓雅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('广宗寺', '孙传庭', '明代', '灵鹫峰南半麓高，护持曾此荷宸褒。残碑漫讶沈苔藓，功德元逾铜瓦牢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '广宗寺' AND p.poem_author = '孙传庭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寓兴十首 其九', '张至龙', '宋代', '夏月灌鞠根，见花在秋日。先时不施工，临花已何及。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寓兴十首 其九' AND p.poem_author = '张至龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再题避暑山庄三十六景诗 其一 丽正门', '弘历', '清代', '岩城埤堄固金汤，詄荡门开向午阳。两字新题标丽正，车书恒此会遐方。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再题避暑山庄三十六景诗 其一 丽正门' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日喜吴光卿孝廉至招同李伯襄太史曾元鲁比部黎有道山人小集 其三', '韩日缵', '明代', '木叶萧萧下，庭阶事事幽。自公多暇日，久客不禁秋。\n\n寂寞元吾分，过从得旧游。披襟谈夙昔，竟夕为淹留。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日喜吴光卿孝廉至招同李伯襄太史曾元鲁比部黎有道山人小集 其三' AND p.poem_author = '韩日缵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('扬州慢 萤苑怀古', '黄燮清', '清代', '疏柳摇愁，夕阳催暝，可怜梦里芜城。自琼花谢后，早粉黛飘零。\n\n叹当日、河边士女，断燐衰焰，都化流萤。问凄凉、谁吊黄昏，犹有箫声。\n\n翠桡暂倚，玉钩斜、荒草青青。算艳冢秋深，离宫夜老，留得残星。\n\n不照画眉帘子，无聊处、雨灭还明。诉兴亡遗恨，招凉人语疏灯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '扬州慢 萤苑怀古' AND p.poem_author = '黄燮清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('祷雨报恩因到翟园四首 其四', '杨万里', '宋代', '未必钱园似翟园，翟园窠木最宜看。茂松亭下偏明眼，矮桧平铺翡翠盘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '祷雨报恩因到翟园四首 其四' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('减字木兰花 题墨兰', '张崇光', '当代', '墨浓春暖。写布清芬人意远。下笔沉吟。花更随人展素心。\n\n同心吾与。索赠兰言花解语。萧艾方荣。为道怀香莫与争。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '减字木兰花 题墨兰' AND p.poem_author = '张崇光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('城中赴范纯甫酒有感', '陈著', '宋代', '杜鹃啼断洛阳桥，心与萍流絮与飘。\n风雨故都同死梦，山林晚景十年饶。\n相逢得醉有今日，万事忘言付落潮。\n见说隐居归我里，尚堪鸡黍狎招邀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '城中赴范纯甫酒有感' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('踏莎行', '袁克文', '清代', '小语轻圆，微嫣娇腻，珠帘玉烛深深地。嫩愁都趁柳丝飞，柔欢任被炉烟系。\n\n梦与云迟，眉教月坠，几回春色撩人醉。夜寒应遣酒长温，香浓知是花无睡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '踏莎行' AND p.poem_author = '袁克文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题吴仲圭墨竹 其一', '张萱', '明代', '梅花道人何太奇，墨戏往往秋淋漓。成竹胸中已十丈，萧萧只写两三枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题吴仲圭墨竹 其一' AND p.poem_author = '张萱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿华严寺', '陆游', '宋代', '夜宿华严寺，人扶到上方。\n唤僧同看画，避佛旋移床。\n小雨不成雪，烈风还作霜。\n锺残灯渐暗，趺坐默焚香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿华严寺' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日 其二', '蓝仁', '元代', '草木消冰雪，林园换岁时。病传方士剂，閒咏古人诗。\n\n兄弟飘零恨，儿孙懒钝姿。一杯春日酒，无奈醒愁悲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日 其二' AND p.poem_author = '蓝仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送文佶归庐岳', '释重显', '宋代', '春色未深，兴无迟早。瓶谢九江，峰寻五老。到日攀萝独上时，依依莫忘海山脑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送文佶归庐岳' AND p.poem_author = '释重显';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('锡杖歌送明楚上人归佛川', '权德舆', '唐代', '上人远自西天竺，头陀行遍国朝寺。口翻贝叶古字经， \n 手持金策声泠泠。护法护身唯振锡，石濑云溪深寂寂。 \n 乍来松径风更寒，遥映霜天月成魄。后夜空山禅诵时， \n 寥寥挂在枯树枝。真法常传心不住，东西南北随缘路。 \n 佛川此去何时回，应真莫便游天台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '锡杖歌送明楚上人归佛川' AND p.poem_author = '权德舆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('瑞洪', '霍与瑕', '明代', '鸣桡过瑞洪，微月下西岛。别有泛湖歌，歌声良自好。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瑞洪' AND p.poem_author = '霍与瑕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头 赠宝蟾子', '李道纯', '元代', '学佛学仙要，玄妙在中诚。真铅真汞无非，只是性和情。但得情来归性，便见铅来投汞，二物自交并。日用了无间，大药自然成。识抽添，明进退，要持盈。坤炉乾坤，阴符阳火慢调停。一穷玄关透了，八片顶门裂破，迸出宝蟾明。功行两圆备，谈笑谒三清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头 赠宝蟾子' AND p.poem_author = '李道纯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('话旧（亭中对兄姊话兰陵崇贤怀真已来故事，泫然而作）', '韦应物', '唐代', '存亡三十载，事过悉成空。不惜沾衣泪，并话一宵中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '话旧（亭中对兄姊话兰陵崇贤怀真已来故事，泫然而作）' AND p.poem_author = '韦应物';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夕次郫县和画壮', '顾光旭', '清代', '万马今归凯，前宵雨洗兵。花开石犀浦，月上杜鹃城。\n\n飞盖村笳动，疏林骑火明。艰难经五载，郫酒为君倾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夕次郫县和画壮' AND p.poem_author = '顾光旭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望云图为张掌科季升题', '潘希曾', '明代', '东华尘土红作堆，生绡咫尺青山开。山头秋气洗天碧，惟有白云閒往来。\n\n临风引领者谁子，思亲梁公无乃似。谏议平生忠孝心，依稀写出丹青里。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望云图为张掌科季升题' AND p.poem_author = '潘希曾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绝句', '佚名', '唐代', '绿杨阴转画桥斜，舟有笙歌岸有花。 \n 尽日会稽山色里，蓬莱清浅水仙家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绝句' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉酬卢端公饮后赠诸公见示之作', '戴叔伦', '唐代', '佐幕临戎旌旆间，五营无事万家闲。风吹杨柳渐拂地， \n 日映楼台欲下山。绮席昼开留上客，朱门半掩拟重关。 \n 当时不敢辞先醉，误逐群公倒载还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉酬卢端公饮后赠诸公见示之作' AND p.poem_author = '戴叔伦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('理故书二首', '刘克庄', '宋代', '轴犹插高架，檠已弃低墙。\n可惜亡三箧，安能读一箱。\n自惭伯仁退，不及阿宜长。\n但忆初强记，谁知晚健忘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '理故书二首' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏井诗', '范云', '南北朝', '乃鉴长林时。\n有浚广庭前。\n即源已为浪。\n因方自成圆。\n兼冬积温水。\n叠暑泌寒泉。\n不甘未应竭。\n既涸断来翾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏井诗' AND p.poem_author = '范云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('遣行十首 其二', '元稹', '唐代', '十五年前事，恓惶无限情。病僮更借出，羸马共驰声。\n\n射叶杨才破，闻弓雁已惊。小年辛苦学，求得苦辛行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '遣行十首 其二' AND p.poem_author = '元稹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卢岩上次韵二首 其一', '卢宁', '明代', '法门长不二，仙洞窈藏真。顾影依池洁，洗心期日新。\n\n云明虚阁午，林霁故山春。幽赏兼良会，清樽酌绿筠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卢岩上次韵二首 其一' AND p.poem_author = '卢宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题义门胡氏华林书院', '赵赴', '宋代', '家隐西山下，华林地绝尘。\n门旌千古义，学聚四方人。\n道致清云富，名随白日新。\n他年应许我，猿鹤一相亲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题义门胡氏华林书院' AND p.poem_author = '赵赴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('潭口寻仙洞 其一', '释今无', '明代', '亦是翛然地，停舟恰受风。水源黎母出，地脉扶桑穷。\n\n怪鸟藤花杂，嘉葩椰叶重。棋枰不可见，伫立上洪濛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '潭口寻仙洞 其一' AND p.poem_author = '释今无';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古风其五十一', '李白', '唐代', '殷後乱天纪。\n楚怀亦已昏。\n夷羊满中野。\n菉葹盈高门。\n比干谏而死。\n屈平窜湘源。\n虎口何婉娈。\n女媭空婵媛。\n彭咸久沦没。\n此意与谁论。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古风其五十一' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀临江寓居', '范梈', '元代', '石霜峰北淦西头，寄住林塘数亩幽。比及到家犹是客，对人强自说乡愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀临江寓居' AND p.poem_author = '范梈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早起', '李贤（原德）', '明代', '霜横玉宇旅怀清，候馆鸡鸣月四更。绿酒自供吟处兴，黄花偏动客中情。\n\n天边孤雁拖秋色，城上群鸦送晚声。莫道高人甘寂寞，尘寰富贵果然轻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早起' AND p.poem_author = '李贤（原德）';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('瑞鹤仙 其二', '葛长庚', '宋代', '赋情多懒率。每醉后疏狂，醒来飘忽。无心恋簪绂。\n\n漫才高子建，韵欺王勃。胸中绝物。所容者、诗兵酒卒。\n\n一两时，调发将来，扫尽闷妖愁孽。\n\n莫说。杀人一万，自损三千，到底臲亶。悬河口讷。非夙世，无灵骨。\n\n把湖山牌印，莺花权柄，牒过清风朗月。且束之、高阁休休，这回更不。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瑞鹤仙 其二' AND p.poem_author = '葛长庚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登庐山诗二首 其二', '鲍照', '南北朝', '访世失隐沦，从山异灵士。明发振云冠，升峤远栖趾。\n\n高岑隔半天，长崖断千里。氛雾承星辰，潭壑洞江汜。\n\n崭绝类虎牙，巑岏象熊耳。埋冰或百年，韬树必千祀。\n\n鸡鸣清涧中，猿啸白云里。瑶波逐穴开，霞石触峰起。\n\n回互非一形，参差悉相似。倾听凤管宾，缅望钓龙子。\n\n松桂盈膝前，如何秽城市。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登庐山诗二首 其二' AND p.poem_author = '鲍照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杏庄游春次前韵呈雪湖', '谢迁', '明代', '雨霁山庄趣不稀，阴森梧竹款重扉。峰凝宿霭千重秀，日射流光万丈辉。\n\n新涨接天舟稳坐，游丝惹地手频挥。柳塘曲处鱼歌动，惊起群凫出翠围。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杏庄游春次前韵呈雪湖' AND p.poem_author = '谢迁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄善画葛君', '徐渭', '明代', '展箑不尽规，墨色鲜于洗。细图万壑云，寄我青山里。\n\n感之不能忘，聊寄短篇耳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄善画葛君' AND p.poem_author = '徐渭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀文衡山待诏二首 其二', '卢宁', '明代', '自尔姑苏胤，机坊无锦章。人皆矜墨妙，吾独爱圭芳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀文衡山待诏二首 其二' AND p.poem_author = '卢宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('斋居感兴二十首 其十八', '林光', '明代', '炎蒸一似洗，商令肃金方。单衣理木棉，时易气自凉。\n\n闭门谢尘鞅，掩卷坐虚堂。大宾虽未接，安敢忘斋庄。\n\n铭盘启时省，千载怀殷汤。小学教事上，临下或未详。\n\n颓龄百无成，岁月去何忙。仰羡天边鸿，随阳又南翔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '斋居感兴二十首 其十八' AND p.poem_author = '林光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人·清尊黄菊红萸佩', '卢祖皋', '宋代', '清尊黄菊红萸佩。两度云岩醉。帽檐今日更清狂。冷雨疏风、著意过重阳。故宫历历遗烟树。往事知何处。漫山秋色好题诗。吟罢阑干、独自立多时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人·清尊黄菊红萸佩' AND p.poem_author = '卢祖皋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四时为农 其三', '吴未淳', '近代', '为农岂不好，卜筑水西涯。碧稻酣朝雨，红莲醉晚霞。\n\n傍堤养鸡鹜，掩径种葵麻。未止安生理，风光亦可夸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四时为农 其三' AND p.poem_author = '吴未淳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题金陵杂兴诗后八首 其二', '薛师董', '宋代', '刘郎之后更苏郎，不枉随人入建康。秦水钟山几相识，前年忽识好文章。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题金陵杂兴诗后八首 其二' AND p.poem_author = '薛师董';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早泊江城三首 其二', '董嗣杲', '宋代', '下江逢好春，入城赏新霁。千花春有机，四望天无际。\n\n老篙不语还，晦迹得少憩。登览且穷探，岂顾跋涉滞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早泊江城三首 其二' AND p.poem_author = '董嗣杲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大司徒毕堂翁老年伯蒙恩予告敬赋', '赵嗣芳', '明代', '勇退初衣遂，孤标夐绝尘。风云扶正气，海岱毓名臣。\n\n有念皆谋国，无营但致身。贤声蜚李郡，起草动枫宸。\n\n网释苏凋瘵，波宽纵涸鳞。豸绣关河遍，恩威电露匀。\n\n圣朝资弼亮，百辟藉陶甄。鹊印清戎索，鹓班领缙绅。\n\n津门擎一柱，社稷倚□□。喉舌阶愈峻，度支绩转新。\n\n中外抢多务，南北共忧贫。大都商铢两，岂有粟红陈。\n\n简括匠心计，节缩总眉颦。叫阍杜鼠雀，握算廪军民。\n\n何以念松菊，□□想鲈莼。引年非洛社，高卧巳沧滨。\n\n岩云生佩剑，海月伴垂纶。徙倚丹经在，行吟绿绮亲。\n\n紫芝餐作饵，黄绮结为邻。野水横舟舰，物望属松筠。\n\n愿言高赤舄，珍重待蒲轮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大司徒毕堂翁老年伯蒙恩予告敬赋' AND p.poem_author = '赵嗣芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寒宵叹', '贺铸', '宋代', '可怜明月光，委曲照空床。\n自是元无梦，更悲今夜长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寒宵叹' AND p.poem_author = '贺铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('嘉陵', '郑谷', '唐代', '细雨湿萋萋，人稀江日西。春愁肠已断，不在子规啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '嘉陵' AND p.poem_author = '郑谷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟唐人五言八韵 其四 诸葛丞相渡泸', '顾炎武', '清代', '火山横日幕，铜涧亘天徼。乱树云南国，交绳僰外桥。\n\n枕戈穿偪仄，带甲上岧峣。地汁生淫雾，流烟入斗杓。\n\n七擒依算略，一战定蛮苗。信洽炎荒永，恩宣益部遥。\n\n深思危大业，隆眷切先朝。更有亲贤表，宫廷告百僚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟唐人五言八韵 其四 诸葛丞相渡泸' AND p.poem_author = '顾炎武';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('田家', '赵崇嶓', '宋代', '鸡豚白酒乐丰年，饱即高眠不问天。\n少长有恩相尔汝，淳风应似伏羲前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '田家' AND p.poem_author = '赵崇嶓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六月十六日夜南溪望月', '杨万里', '宋代', '溪水留我住，溪月愁我皈。\n望後月更佳，昨宵未为奇。\n大都月色好，一岁能几时。\n人散长是早，月来长是迟。\n初出如大瓮，才露金半规。\n不知独何急，下如有人推。\n忽然脱岭尖，行空安不危。\n似爱溪水净，下浴青琉璃。\n明珠径余尺，沈在千顷陂。\n我欲剌双手，就溪取团晖。\n白小忽乱跳，碎作万金徽。\n须臾波痕定，化为水银池。\n夜久看未足，风露欺病肌。\n我能尚小留，瘦藤歌式微。\n一笑顾群从，来夕肯集兹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六月十六日夜南溪望月' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('真如庵', '沙曾达', '近代', '庵寻东外号真如，径曲门幽古佛居。数亩竹林尘不到，杨公文定喜攻书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '真如庵' AND p.poem_author = '沙曾达';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李商隐学仙', '张雨', '元代', '谁云有分不关情，沦谪千年为底名。消得权儿羊浣布，诗中唯数玉溪生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李商隐学仙' AND p.poem_author = '张雨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六月十四次韵樊武仲喜雨', '魏了翁', '宋代', '谁信夔夔解感神，嘤嘤赤子母心熏。\n为将一滴翻瓢水，散作千家举臿云。\n大化无端长寂寂，众形有欲自芸芸。\n更须尽挽天河水，亟与三边洗恶氛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六月十四次韵樊武仲喜雨' AND p.poem_author = '魏了翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('烛影摇红·老子婆娑', '刘辰翁', '宋代', '老子婆娑，那回也上南楼去。素娥有恨隐云屏，元是娇痴故。惊扇徘徊未许。耿多情、为谁堪诉。使君愁绝，独倚阑干，後期无据。有酒如船，片云扫尽霓裳露。他时与客更携鱼，犹记临皋路。因念南羁北旅。醉乌乌、凭君楚舞。问君不见，璧月词成，楼西沉处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '烛影摇红·老子婆娑' AND p.poem_author = '刘辰翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄修职雨中送芍药五枝', '陈与义', '宋代', '微雨湿清晓，老夫门未开。\n煌煌五仙子，并拥翠蕤来。\n烟脂洗尽不自惜，为雨归来更无力。\n老夫五十尚可痴，凭轩一赋会真诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄修职雨中送芍药五枝' AND p.poem_author = '陈与义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('兹蒙圣恩追录先德当赠诰涣颁之日适余生初度之辰悲喜交中辄形咏叹是用录呈同志共作荣观', '王绅', '明代', '弱龄志家学，黾勉事讨论。显扬恨无术，恻恻长抱辛。\n\n今岁倏四十，劬劳在兹辰。宠光适下贲，沛及没与存。\n\n易名锡美谥，赠诰颁紫宸。片言重山岳，卓彼云汉文。\n\n悲喜集中怀，庆慰来上宾。匪徒事夸耀，大节从此伸。\n\n鞠躬谢苍旻，何以酬明恩。君亲两毋忘，不负六尺身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '兹蒙圣恩追录先德当赠诰涣颁之日适余生初度之辰悲喜交中辄形咏叹是用录呈同志共作荣观' AND p.poem_author = '王绅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('海安所 其一', '许南英', '清代', '一城围一海安营，营外茅房半就倾。十丈红尘风起处，松声入耳杂车声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '海安所 其一' AND p.poem_author = '许南英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪晴野望', '张耒', '宋代', '萧萧空谷隐山云，渡水人归何处村。\n樵径雪迷唐苑路，鸟声寒集汉祠门。\n公堂吏散惟修竹，近岭林疏见饮猿。\n客坐无毡君莫笑，陶潜亦有酒盈樽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪晴野望' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('榆关', '张文胜', '当代', '三月榆关正寒苦，小梅窗下雪深深。瓶笙花影愔愔梦，翰海神京历历心。\n\n一种寂寥劳玉想，十分冷淡要清吟。江南春色浓如酒，瞻望斗杓谁与斟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '榆关' AND p.poem_author = '张文胜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百二十三首', '释崇岳', '宋代', '弥勒真弥勒，分身千百亿。\n时时示时人，时人皆不识。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百二十三首' AND p.poem_author = '释崇岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋蝉', '林以宁', '清代', '昨夜凉风届节初，园亭景物渐萧疏。高枝坠露堪承饮，深树微云可卜居。\n\n秦女支砧秋半急，卫娘小鬓夜来梳。遐情自足传霄汉，不逐金梧下玉除。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋蝉' AND p.poem_author = '林以宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闲中口占数绝 联', '郑清之', '宋代', '雨多愁麦又忧苗，不雨还忧旱火骄。忧国浪愁端自苦，老天那肯病汤尧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闲中口占数绝 联' AND p.poem_author = '郑清之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄越南王诗', '李鸿章', '清代', '河山表里本天成，寄语贤王建树宏。朝汉尉佗犹有志，帝秦新衍竟何名。\n\n雕题部落三关控，尝胆君臣奄虑生。垂老伏波犹矍铄，五溪南去不胜情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄越南王诗' AND p.poem_author = '李鸿章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽周侍郎二首 其二', '朱熹', '宋代', '忆昔趋丹阙，看公上玉除。民饥深献纳，主圣极欷歔。\n\n解手寒江阔，惊心夜壑虚。朅来空老泪，无地别輀车。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽周侍郎二首 其二' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵子封先生答山中僧', '善住', '元代', '名山不肯住，自欲老深云。凿翠通虚牖，锄荒出坏坟。\n\n花开留客醉，果熟与猿分。更莫逃幽隐，音书难重闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵子封先生答山中僧' AND p.poem_author = '善住';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留题鉴远楼 其三', '李弥逊', '宋代', '霜天晓日鉴中新，眼力由来未见真。万古茫茫一尘迹，碧山无际水无垠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留题鉴远楼 其三' AND p.poem_author = '李弥逊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭亡侄孙士铨', '汪嫈', '清代', '三岁抚汝大，十八弃我去。经年泪眼枯，魂魄归何处。\n\n汝母托我日，跪床泣告语。侄妇死如归，伤心惟稚孺。\n\n侄身当中年，妇死必再娶。悯子饥且寒，莫免芦花絮。\n\n成立岂易言，不肖尤堪惧。怆绝辞未终，双手亲交付。\n\n■我忍泪听，抱汝曲劝谕。一痛忽剪决，生死判急遽。\n\n抚汝从兹始，性命相依附。到今十五年，苦心向谁诉。\n\n冻馁固可虞，温饱益增虑。疴痒最关怀，焦劳夜复曙。\n\n曾记一医来，目我为乳妪。四岁教识字，解诵唐人句。\n\n送汝入塾中，督责不汝恕。恐汝德不修，恐汝学不裕。\n\n历择名师从，璞质勤磨铝。喜汝尚好学，光阴弗自误。\n\n学业渐可观，长者咸称誉。勉然品行修，立身得依据。\n\n爱敬根性天，事叔如事父。谓叔性豪侠，轻财略无度。\n\n负累日益深，积重病成痼。胡不归里闾，资斧从容措。\n\n侄善事大母，叔无忧内顾。门内百事宜，未可倚厕庶。\n\n万一值艰难，吾师堪借箸。汝叔闻汝言，意决任驰骛。\n\n去去倏两年，家书盈尺素。师教汝秉承，读书明世务。\n\n家事无钜纤，若马能驾驭。一一体我心，假手挥仆御。\n\n叔母爱汝挚，恩慈多煦煦。叔父寄书来，称汝有才具。\n\n云儿年卅六，得子望虚屡。侄辈幸得人，吾家本根固。\n\n我阅汝叔信，悚然增觉寤。慎重加汝餐，汝好希光祚。\n\n胡天不右汝，一病即物故。悲哉我何堪，惊怆瞥僵仆。\n\n祸及太无端，痛哭将天吁。我自究我心，何事干天怒。\n\n即论汝为人，亦应得天助。年少笃天伦，醇悫本畀赋。\n\n处事虽精明，浑厚随■寓。往往律己严，待人气和煦。\n\n古谊交朋侪，肝胆每倾吐。岂无富家子，膏粱与纨裤。\n\n媮薄无性情，汝心最深恶。天真汝未漓，见义力争赴。\n\n先达与乡贤，见汝翻忻慕。依依我膝前，相离未寸步。\n\n祷我寿而康，晨昏香一炷。偶逢我疾作，汝心辄惊怖。\n\n汤药汝亲尝，悉心为调护。侍奉竭欢娱，片言莫我忤。\n\n诣力进竿头，经史渐镕铸。指顾青云霄，毛丰卜腾翥。\n\n意此鑫席才，应到玉堂署。祖德扬清风，君恩承湛露。\n\n而我衰迈年，绵弱难吹呴。得见汝成名，我志聊堪足。\n\n今乃大不然，逆境来错愕。匪云天作孽，于事何抵捂。\n\n明知冥漠中，修短关定数。奈我心枯寂，兀坐若泥塑。\n\n往事一回首，默然神瞿瞿。汝父久赋閒，守株空待兔。\n\n更抱西河痛，岂复有生趣。汝叔犹远游，飘零悲客路。\n\n望汝心殷殷，那堪闻此讣。痛汝盼叔归，病中神远注。\n\n叔归汝长逝，一散遂难聚。日夕恸不忘，涕泪无所住。\n\n六洲三岛间，闻有返魂树。汝魂招不来，我目已如瞀。\n\n古寺风潇潇，灵輀且安厝。期汝送我死，今反展汝墓。\n\n问天天无言，此理终不悟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭亡侄孙士铨' AND p.poem_author = '汪嫈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古十七首 其十七', '释道行', '宋代', '江南江北勿同伦，疑了还疑笑杀人。谁信一盘油煠底，古今塞断是非门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古十七首 其十七' AND p.poem_author = '释道行';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山行', '方岳', '宋代', '住世间须出世间，世情何事苦牵攀。\n蟠胸自作三分国，觌面相悬两戒山。\n大好闭门赢得睡，不多识字煞妨閒。\n长须赤脚顽於我，未必淳风不再还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山行' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('淮阴叹', '李东阳', '明代', '营门昼开齐犬吠，蒯生相人先相背。\n古来鸟尽良弓藏，近时刎颈陈与张。\n功成四海身无地，归楚楚疑归汉忌。\n极知犹豫成祸胎，时乎时乎不再来。\n君王恩深辩士走，淮阴胸中血一斗。\n妇人手执生杀机，赤族不待君王归。\n君王归，神为恻。\n独不念秋毫皆信力，舍人一嗾彭王殂。\n淮阴之辞真有无？噫吁?！淮阴之辞真有无？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '淮阴叹' AND p.poem_author = '李东阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('【中吕】醉高歌过红绣鞋_看别人鞍马', '贯云石', '元代', '看别人鞍马上胡颜，叹自己如尘世污眼。英雄谁识男儿汉，岂肯向人行诉难？\n　　阳气盛冰消北岸，暮云遮日落西山，四时天气尚轮还。秦甘罗疾发禄，姜吕\n望晚登坛，迟和疾时运里趱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '【中吕】醉高歌过红绣鞋_看别人鞍马' AND p.poem_author = '贯云石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南乡子', '赵葵', '宋代', '束发颂西藩。百万雄掌握间，召到庙堂无一事，遭弹。昨日公卿今日间。 \n 拂晓出长安。莫待西风割面寒。羞见钱塘江上柳，何颜。瘦仆牵驴过远山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南乡子' AND p.poem_author = '赵葵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('公馀八景 其八 雪霁寒梅', '徐庸', '明代', '绛苇青枝□倚墙，六花□□早封香。共知结就累累实，鼎鼐调羹入庙廊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '公馀八景 其八 雪霁寒梅' AND p.poem_author = '徐庸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('朱华塔成三首', '卢宁', '明代', '竖塔障江涟，吾民种福田。孤高周石室，明远汉通天。\n\n金紫千家丽，仪章六代贤。平川成乐土，长世祝皇年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '朱华塔成三首' AND p.poem_author = '卢宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采石吊李太白', '张诩', '明代', '一江风雨浪纷披，鼓枻长过采石矶。千载斯人疑不死，一生豪气尚争辉。\n\n夜郎天阔冥鸿去，五老峰高白鹤飞。吟罢小诗天忽霁，醉呼明月满船归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采石吊李太白' AND p.poem_author = '张诩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无题', '吴金水', '当代', '渺渺溪村没野禽，嶙峋翠嶂起烟浔。青山菊酒红莲米，紫陌桃花绿绮琴。\n\n梦不由人难再续，楼堪纵目且重临。嚣尘十载情怀减，如许风光只一吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无题' AND p.poem_author = '吴金水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风雨中寻李十一，因题船上', '白居易', '唐代', '匹马来郊外，扁舟在水滨。可怜冲雨客，来访阻风人。 \n 小榼酤清醑，行厨煮白鳞。停杯看柳色，各忆故园春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风雨中寻李十一，因题船上' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古十首 其三', '释昙华', '宋代', '出得出不得，满面是埃尘。愁人莫向愁人说，说向愁人愁杀人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古十首 其三' AND p.poem_author = '释昙华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又题白鹭洲江鸥送陈君', '徐铉', '唐代', '白鹭洲边江路斜，轻鸥接翼满平沙。吾徒来送远行客， \n 停舟为尔长叹息。酒旗渔艇两无猜，月影芦花镇相得。 \n 离筵一曲怨复清，满座销魂鸟不惊。人生不及水禽乐， \n 安用虚名上麟阁。同心携手今如此，金鼎丹砂何寂寞。 \n 天涯后会眇难期，从此又应添白髭。愿君不忘分飞处， \n 长保翩翩洁白姿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又题白鹭洲江鸥送陈君' AND p.poem_author = '徐铉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郊庙歌辞。梁太庙乐舞辞。来仪舞', '佚名', '唐代', '於赫帝命，应天顺人。亭育品汇，宾礼百神。 \n 洪基永固，景命惟新。肃恭孝享，祚我生民。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郊庙歌辞。梁太庙乐舞辞。来仪舞' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暮年即事', '姜特立', '宋代', '八十衰翁如小儿，爱餐梨栗作儿嬉。\n有时淡饮三杯酒，无事閒吟两首诗。\n还丹却老吾不知，头童齿豁一听之。\n但愿造物相扶持，寿考或可登期赜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暮年即事' AND p.poem_author = '姜特立';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答杨教见和', '王质', '宋代', '饭鼓逢逢睡起时，先生弟子总关扉。不妨堂下轻骑马，切莫江头浪典衣。\n\n且对灯花随雨落，任从苜蓿列盘稀。杜陵郑老襟期在，今昨那能定是非。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答杨教见和' AND p.poem_author = '王质';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('复见官军诗', '楼钥', '宋代', '元帅平京邑，声声夹道闻。\n不图当此日，复得见官军。\n将钺来何莫，壶浆意已勤。\n重瞻貔虎士，尽扫犬羊群。\n王旅方驰电，民心极望云。\n长安十万户，拭目待吾君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '复见官军诗' AND p.poem_author = '楼钥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贺秀岩李工侍七首 其四', '程公许', '宋代', '封章三上意拳拳，却恨归无一壑专。商略浮生皆寄耳，直须勘破劫空前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贺秀岩李工侍七首 其四' AND p.poem_author = '程公许';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答四弟贺添仲孙之作', '张嗣纲', '明代', '蹠掌青云当户开，再逢维岳降祥来。莲峰翠耸金牛渡，珠海光投玉燕怀。\n\n但愿门前垂五柳，敢誇日后应三槐。积书幸得儿孙读，可有文章接上台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答四弟贺添仲孙之作' AND p.poem_author = '张嗣纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重九和韵', '费墨娟', '清代', '登高纵览蹑龙岗，到此开怀万虑忘。胜地清游嫌日短，芳辰雅会寄情长。\n\n千林红叶堪描画，三径黄花可泛觞。愧我才疏如袜线，强承佳韵报诗囊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重九和韵' AND p.poem_author = '费墨娟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送陇州使君刘仲仪左藏赴治', '强至', '宋代', '夹道浓香数里焚，随车和气一城薰。\n兵民如见古循吏，文武兼能今使君。\n冷射祠堂汧水月，晴飞郡阁陇山云。\n幕中知有才从事，樽俎清谈定喜闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送陇州使君刘仲仪左藏赴治' AND p.poem_author = '强至';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登大伊山望海慨然有作', '谢元淮', '清代', '童男帅女觅蓬壶，却笑秦皇作计粗。采药楼船何日返，登山筇屐此时俱。\n\n江河入海涵清浊，齐鲁连云望有无。谁信凫夷来地底，一挥长剑扫天吴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登大伊山望海慨然有作' AND p.poem_author = '谢元淮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送尹商衡都黄门出狱', '杨爵', '明代', '需极乘时起，文明及早开。经猷小自预，功业大期来。\n\n气运机方动，人谋预可回。两肩刚骨上，□□□三才。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送尹商衡都黄门出狱' AND p.poem_author = '杨爵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('写竹题寄华叔端', '王绂', '明代', '我昔寻君扣竹扉，醉中曾写竹间诗。别来几度空相忆，多在青灯听雨时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '写竹题寄华叔端' AND p.poem_author = '王绂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头', '俞律', '近代', '物我有深谛，六月梦花天。当年花国曾隐，一度学神仙。\n\n十万杨妃新浴，醉弄丰肌玉骨，拥我夕阳船。记得凌波步，尘外听珊珊。\n\n云是纸，风是笔，染田田。丹青难写，别后明月照无眠。\n\n依旧年华虚度，十载光阴何速，回首尽云烟。何日还归去，花里悟通圆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头' AND p.poem_author = '俞律';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆江南', '魏新河', '当代', '都太晚，风雨忍相催。问影问声寻片玉，隔云隔水惜残梅。\n\n谁说一生陪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆江南' AND p.poem_author = '魏新河';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词 其四十九', '江源', '明代', '心绪纷纭懒出门，出门何处望金根。鹍弦欲拨无愁曲，只恐愁多更断魂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词 其四十九' AND p.poem_author = '江源';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送袁景宗之荆渚宁觐', '魏野', '宋代', '荆渚北堂宁圣善，棠阴东阁别严君。\n雪村山馆思亲梦，二十馀宵两处分。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送袁景宗之荆渚宁觐' AND p.poem_author = '魏野';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('训士吟 其四', '戴亨', '清代', '猗嗟此一生，生难尽慧识。幸不堕顽蠢，造物岂我啬。\n\n况藉古初人，阐微先我力。得每不践机，失亦难伪饰。\n\n用转欺慊机，慎哉勿自贼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '训士吟 其四' AND p.poem_author = '戴亨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠余德甫奉使两浙四首 其一', '宗臣', '明代', '天风匹马向西湖，明月千家醉白榆。莫上钓台听夜笛，霜华吹破客星孤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠余德甫奉使两浙四首 其一' AND p.poem_author = '宗臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宜春再访芳公言公幽斋写怀叙事，因赋长言', '郑谷', '唐代', '入门长恐先师在，香印纱灯似昔年，涧路萦回斋处远， \n 松堂虚豁讲声圆。顷为弟子曾同社，今忝星郎更契缘。 \n 顾渚一瓯春有味，中林话旧亦潸然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宜春再访芳公言公幽斋写怀叙事，因赋长言' AND p.poem_author = '郑谷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晓', '弘历', '清代', '晓色侵罗幌，初晴景色和。轩墀饶润秀，书史足吟哦。\n\n竹里风兼爽，花间露渐多。畴咨勤问政，何以秩南讹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晓' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其一', '梁安世', '宋代', '更说此州异特事，寇公归后二苏来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其一' AND p.poem_author = '梁安世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古意', '李时行', '明代', '花落春愁暗，莺啼晓梦醒。柳丝长若许，难系别离情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古意' AND p.poem_author = '李时行';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('还过他里雾', '孙元衡', '清代', '林黑涧逾响，天青山更高。诸蕃能跽拜，前队肃弓刀。\n\n卧簟惟功狗，喧枝尽伯劳。不因程计日，待猎看风毛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '还过他里雾' AND p.poem_author = '孙元衡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九月五日具草酌同彦博审知成父集于普宁山半', '赵蕃', '宋代', '平生羞狗监，何啻失羊斟。\n与子风期尚，相要林壑深。\n分甘驹在谷，宁事鹤鸣阴。\n此日胡为乐，诗成改又吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九月五日具草酌同彦博审知成父集于普宁山半' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('献寿戏作', '苏轼', '宋代', '终须跨个玉麒麟，方丈蓬莱走一巡。\n敢献些儿长寿物，蟠桃核里有双仁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '献寿戏作' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '宋太宗', '宋代', '二三千客里成事，七十四人中少年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '宋太宗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小池观鱼', '姜特立', '宋代', '戏投饼饵方塘上，无限鱼儿翻翠浪。\n向来瓠瑟听遗音，今日梅山识清唱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小池观鱼' AND p.poem_author = '姜特立';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('草屦', '易士达', '宋代', '崎岖只惯识羁情，足下忙穿子更轻。\n近世宦途如纸薄，当知险处不须行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '草屦' AND p.poem_author = '易士达';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九月八日桐川道中二绝 其二', '岳珂', '宋代', '依稀九日明朝是，三径情知不到家。随分秋光关节物，桐川道上看黄花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九月八日桐川道中二绝 其二' AND p.poem_author = '岳珂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋', '陈忠平', '当代', '何独怜今夜，一年容易秋。雁都为过客，月只照离忧。\n\n珠露洗檐白，心潮到海休。清风扶薄醉，倚断小洋楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋' AND p.poem_author = '陈忠平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登封大酺歌四首', '卢照邻', '唐代', '明君封禅日重光，天子垂衣历数长。 \n 九州四海常无事，万岁千秋乐未央。 \n 日观仙云随凤辇，天门瑞雪照龙衣。 \n 繁弦绮席方终夜，妙舞清歌欢未归。 \n 翠凤逶迤登介丘，仙鹤裴回天上游。 \n 借问乾封何所乐，人皆寿命得千秋。 \n 千年圣主应昌期，万国淳风王化基。 \n 请比上古无为代，何如今日太平时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登封大酺歌四首' AND p.poem_author = '卢照邻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丁酉新正访疏影渝州并与喜英先生饮于楼船次无欲斋元玉', '邱登成', '当代', '筵开画船上，恰过月初三。杯酒催诗兴，江风助茗谈。\n\n水流山未醒，情转意微酣。灯火昨宵处，依稀见碧岚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丁酉新正访疏影渝州并与喜英先生饮于楼船次无欲斋元玉' AND p.poem_author = '邱登成';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中岳庙投龙简', '吴全节', '元代', '阳城天地中，坤灵奠神岳。积翠千层霄，元气远盘礴。\n\n降神生申甫，形势控伊洛。谽谺虎豹蹲，偃蹇蛟龙跃。\n\n猛士横戈矛，奇阵出帏幄。簇簇罗旌旗，巍巍耸台阁。\n\n玉镜为谁开，金匮为谁钥。远近列画图，周遭峙郛郭。\n\n万状不可名，起伏互连络。皇皇圣帝居，历代重封爵。\n\n老柏浮苍烟，古殿蚀丹雘。天朝混华夏，秩礼特优渥。\n\n皇庆二载春，宵旰轸民瘼。有旨醮长春，玉简命新琢。\n\n诏臣走登封，香币致虔恪。邃洞藏宝符，琼音降笙鹤。\n\n三呼今复闻，祥风度天乐。小臣奉明祀，三使陟云崿。\n\n箕山胜可家，颍水清可涿。遐想饮牛人，高风动寥廓。\n\n赐玦知何时，分我云半壑。歌诗勒嵩珉，用赞圣人作。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中岳庙投龙简' AND p.poem_author = '吴全节';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送王承恩侍讲参政四川', '文徵明', '明代', '鸟道巇㠊万里赊，从臣分省向三巴。中朝声望云山重，内史文章锦水华。\n\n烂熳新恩苍玉节，依然旧署紫薇花。只应未忘论思地，翘首金銮北斗斜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送王承恩侍讲参政四川' AND p.poem_author = '文徵明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('墨君十咏 其九 夜', '王铚', '宋代', '倚竹佳人生暮愁，那知情伴夜蝉幽。一山风月龙吟罢，声入江云袅袅秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '墨君十咏 其九 夜' AND p.poem_author = '王铚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天', '吴世昌', '近代', '暖日疏林照渌波，游人长见影婆娑。谁家种得痴情树，粒粒枝头醉欲酡。\n\n呼女伴，挽轻箩。相思共拾不嫌多。春风一夜吹红豆，遍地相思奈尔何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天' AND p.poem_author = '吴世昌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词三十三首', '曹勋', '宋代', '宽恤从来只陆沉，丁宁今始慰人心。\n圣情更欲民孚信，亲御云章下诏音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词三十三首' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('紫瑞香三首', '陈藻', '宋代', '无数枝头簇簇葩，大枝直上细枝斜。\n商量开尽商量落，全要前花见后花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '紫瑞香三首' AND p.poem_author = '陈藻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清源夫人赵氏挽词 其一', '王十朋', '宋代', '全节忠臣配，崇宁宰相家。哀能变国俗，贵不御铅华。\n\n学佛穷三昧，然松教五车。遗芳载彤管，名寿两俱遐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清源夫人赵氏挽词 其一' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春暮', '王诒寿', '清代', '野桃无力点晴波，寒食清明次第过。酒价渐低春酿熟，笋船初到市声多。\n\n东风芳草人盘马，小雨杨花客渡河。却忆江南好时节，画桡衫影水如罗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春暮' AND p.poem_author = '王诒寿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄何叔毗礼部', '文徵明', '明代', '为爱君家好弟兄，列官同在凤凰城。迟迟宫漏薇垣静，浥浥垆香画省清。\n\n风雨夜堂联榻处，池塘春草看诗成。相逢相别还相忆，白发江湖无限情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄何叔毗礼部' AND p.poem_author = '文徵明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵吕元钧给事嘉川驿来诗', '李复', '宋代', '相逢莫厌重留连，邂逅浮云只偶然。前日一樽穷乐事，今朝千里感流年。\n\n尘侵遗迹留漳水，风入高吟动蜀鞭。锦鲤往来出江浦，应传秀句满嘉川。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵吕元钧给事嘉川驿来诗' AND p.poem_author = '李复';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('季子守宅观音莲', '徐渭', '明代', '昔闻火里莲能长，今见莲从陆地栽。广叶祗冯圆性转，粗花全借法身开。\n\n丛摇宝鬘风中去，气绕梅檀雨后来。试问集观谁具眼，解将真见听飞埃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '季子守宅观音莲' AND p.poem_author = '徐渭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一字百题示商君祥 其八十二 舞', '李俊民', '金朝', '野鹤闻琴态，孤鸾对镜妍。为君小垂手，无地可回旋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '一字百题示商君祥 其八十二 舞' AND p.poem_author = '李俊民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行乞从化宿李某石峰堂因赠', '释今沼', '明代', '新堂筑几年，奇石复巍然。座客乐时满，架书经乱全。\n\n城阴篱落下，山色屋隅边。相对已如梦，况忆十年前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行乞从化宿李某石峰堂因赠' AND p.poem_author = '释今沼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('劳山纪游百咏选七十九首 其五十六', '黄公渚', '近代', '独立云端见似人，頫看沧海几扬尘。幕云崮与凌烟崮，争及金刚不坏身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '劳山纪游百咏选七十九首 其五十六' AND p.poem_author = '黄公渚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观张中乐书大字', '梅尧臣', '宋代', '芝旭驰名世有孙，大书如晓过秋原。\n长松怪柏皆成炭，豫氏观傍不解吞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观张中乐书大字' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与邵莫二子游七真诸洞一首', '黄省曾', '明代', '驻马翠微中，山萝漾夕风。言探七子躅，因蹑五城宫。\n\n洞草徒看绿，丹炉巳罢红。飙轮不可见，吾欲母禽通。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与邵莫二子游七真诸洞一首' AND p.poem_author = '黄省曾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏日直秘阁', '李至', '宋代', '蓬阁清虚称野情，华阳巾稳葛衣轻。\n垂帘不见喧嚣事，尽日唯闻禽鸟声。\n小桧影中铺砚席，矮槐阴下著茶铛。\n却愁穷巷晚归去，尘土满街冲热行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏日直秘阁' AND p.poem_author = '李至';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百零二首 其十七', '释绍昙', '宋代', '横该竖抹，古路封苔。圣凡情尽，马腹驴胎。不用闭门防俗客，爱闲能有几人来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百零二首 其十七' AND p.poem_author = '释绍昙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观物', '林希逸', '宋代', '天旋底背东西日，月正河平昼夜潮。空里华生空里灭，静中声起静中消。\n\n移舟远浦疑山走，汲水清溪觉岸摇。人世自迷颠倒见，达观何事不逍遥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观物' AND p.poem_author = '林希逸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢彭大夫惠寒山诗三首', '曹勋', '宋代', '平生为物役，年纪积渐老。\n不省这个意，老得越颠倒。\n自读二诗来，迷云扫空照。\n我为谢彭翁，且喜无烦恼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢彭大夫惠寒山诗三首' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题苏庄洞神观楼', '王翰', '元代', '万叠青山百尺楼，倚栏空翠泼双眸。波澄碧簟铺沙际，霜重红绡剪树头。\n\n玉洞月明丹火冷，宝坛风细剑光流。平生作客多秋兴，便拟登临赋远游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题苏庄洞神观楼' AND p.poem_author = '王翰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('石湖十二咏 其九 楞伽塔', '郑元祐', '元代', '危峰耸浮屠，七级雕阑曲。影落湖波心，鱼龙骇常伏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '石湖十二咏 其九 楞伽塔' AND p.poem_author = '郑元祐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古意', '詹同', '明代', '君家兰泽西，妾家兰泽东。兰泽多芳草，相去各春风。\n\n君今行陇右，妾思在闺中。天寒绣袂薄，泪下玉屏空。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古意' AND p.poem_author = '詹同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('禅人并化主写真求赞 其二三七', '释正觉', '宋代', '须发衰残，空山雪寒。眉目清淡，野水秋还。一念万年了尘劫，十方三世同正观。\n\n翡翠天晴而清虚廓彻，珊瑚海月而光焰波澜。现形说法应机感，笑指俱胝百草端。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '禅人并化主写真求赞 其二三七' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百一十七首 其七十七', '释绍昙', '宋代', '雨足龙闲，年丰民乐。袖出刈禾镰，大地全收却。归来十二峰前，别甑炊香，明玑满钵。\n\n喂饱活衲僧，曲肱酣睡著。佛法身心烂似泥，哑，医无药。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百一十七首 其七十七' AND p.poem_author = '释绍昙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别程女', '元好问', '元代', '芸斋淅淅掩霜寒，别酒青灯语夜阑。\n生女便知聊寄托，中年尤觉感悲欢。\n松间小草栽培稳，掌上明珠弃掷难。\n明日缑山东畔路，野夫怀抱若为宽？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别程女' AND p.poem_author = '元好问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄史君实 其一', '郑真', '明代', '月湖公子泮池深，老却平生富贵心。宝铗歌残星斗落，紫箫吹断凤鸾吟。\n\n秫香樽蚁杯频泛，烛剪钗虫夜向深。若幸广文归去早，午风花下定相寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄史君实 其一' AND p.poem_author = '郑真';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次王得淦韵', '陈著', '宋代', '浴出矮檐阴，披襟小雨侵。\n坐凉三鼓漏，和梦一镫吟。\n自分死中活，谁知升与沈。\n明朝书局事，奔走岂初心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次王得淦韵' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('悼具三', '释函是', '明代', '早年避乱投泉石，因病辞家渡海云。白社尚存居士笔，青山添作苾刍坟。\n\n泪泠松埠新霜露，梦绕萝龛旧见闻。借汝再来吾已老，不堪孤雁唳斜曛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '悼具三' AND p.poem_author = '释函是';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('居厚弟和七十四吟再赋', '刘克庄', '宋代', '占断溪山不纪年，俗开谤道是呆仙。\n马迟甘殿他人后，棋劣常输敌手先。\n饥咬菜根美熊掌，穷烧柏子当龙涎。\n可怜陈窦无精识，欲以绳维大厦颠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '居厚弟和七十四吟再赋' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆萝月（寓清平乐客盱江，秋夜鼓琴，思故山作）', '张辑', '宋代', '新凉窗户。闲对琴言语。弹到无人知得处。两袖五湖烟雨。 \n 坐中斗转参横。珠躔碎落瑶觥。忆著故山萝月，今宵应为谁明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆萝月（寓清平乐客盱江，秋夜鼓琴，思故山作）' AND p.poem_author = '张辑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('植灵寿木', '柳宗元', '唐代', '白华鉴寒水，怡我适野情。\n前趋问长老，重复欣嘉名。\n蹇连易衰朽，方刚谢经菅。\n敢期齿杖赐？聊且移孤茎。\n丛萼中竞秀，分房处舒英。\n柔条乍反植，劲节常对生。\n循玩足忘疲，稍觉步武轻。\n安能事翦伐，持用资徒行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '植灵寿木' AND p.poem_author = '柳宗元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('由弯崎至罗汉门杂咏 其四', '郑兼才', '清代', '海外青山入版图，红毛遗迹属模糊。峰头雨暗怨鸯岭，有客来寻打鹿埔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '由弯崎至罗汉门杂咏 其四' AND p.poem_author = '郑兼才';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('治宅诗', '谢朓', '南北朝', '结宇夕阴街，荒幽横九曲。迢递南川阳，迤逦西山足。\n\n辟馆临秋风，敞窗望寒旭。风碎池中荷，霜剪江南菉。\n\n既无东都金，且税东皋粟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '治宅诗' AND p.poem_author = '谢朓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答赵尉', '陈宓', '宋代', '亲友乡闾恨少逢，多因游宦得从容。\n他年傥过鸣珂里，只恐飞翰不许从。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答赵尉' AND p.poem_author = '陈宓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采采歌', '胡仲弓', '宋代', '朝采畹中兰，暮采篱下菊。\n采采复采采，终日不盈掬。\n为怜芳洁姿，忍受红尘触。\n采兰杀风味，采菊盈芬馥。\n落英固可飧，何发饮藜藿。\n秋香亦可纫，保如鸣佩玉。\n俾尔全其天，得志在岩谷。\n所以山中人，终身抱幽独。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采采歌' AND p.poem_author = '胡仲弓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('添春色', '秦观', '宋代', '唤起一声人悄。衾冷梦寒窗晓。瘴雨过，海棠晴，春色又添多少。社瓮酿成微笑。半缺癭瓢共舀。觉健倒，急投床，醉乡广大人间小。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '添春色' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同罗季能章成父张子直登樊城制胜楼', '李曾伯', '宋代', '避愁聊复上层楼，上到层楼转更愁。\n杳杳青烟榆夹塞，鳞鳞翠浪麦平畴。\n山连楚甸三千里，地隔中原四百州。\n立尽栏干夜领会，沧波渺处起沙鸥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同罗季能章成父张子直登樊城制胜楼' AND p.poem_author = '李曾伯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('纪事 其四', '文天祥', '宋代', '百色无厌不可支，甘心卖国问为谁。豺狼尚畏忠臣在，相戒勿令丞相知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '纪事 其四' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沙塞子（咏梅）', '葛立方', '宋代', '天生玉骨冰肌。瘦损也、知他为谁。□寒底、傲霜凌雪。 \n 不教春知。高楼横笛试轻吹。要一片、花飞酒卮。拚沈醉、帽帘斜插，折取南枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沙塞子（咏梅）' AND p.poem_author = '葛立方';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绍兴祀太社太稷十七首 太社位酌献用《嘉安》。春社太稷、土正、后稷通用。', '郊庙朝会歌辞', '宋代', '封土崇祀，有烈在民。千载不昧，福此人群。洗爵奠斝，有酒其芬。\n\n神具醉止，恺乐欣欣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绍兴祀太社太稷十七首 太社位酌献用《嘉安》。春社太稷、土正、后稷通用。' AND p.poem_author = '郊庙朝会歌辞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郊庙歌辞。享龙池乐章。第二章', '蔡孚', '唐代', '帝宅王家大道边，神马龙龟涌圣泉。昔日昔时经此地， \n 看来看去渐成川。歌台舞榭宜正月，柳岸梅洲胜往年。 \n 莫言波上春云少，只为从龙直上天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郊庙歌辞。享龙池乐章。第二章' AND p.poem_author = '蔡孚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书房杂书', '陆游', '宋代', '敛版一何久，悬车已後时。\n狂酲醒始悔，穷独老方知。\n世外乾坤大，林间日月迟。\n犹须采药去，不媿鹿门期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书房杂书' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题明秀楼 其二', '胡俨', '明代', '紫霞碧树绕沧洲，满目江山入画楼。想得楼中宾客散，携琴还载木兰舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题明秀楼 其二' AND p.poem_author = '胡俨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词 其十二', '赵佶', '宋代', '乐章依韵俯成编，欲听新词禁宇传。曲里字难相借问，随时切脚注花笺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词 其十二' AND p.poem_author = '赵佶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无题十月二作', '卢青山', '当代', '露老红鹃柳老烟。记曾两次过塘沿。而今应有啼衣鸟，自在风中向蟋眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无题十月二作' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('祠颜范二公', '王十朋', '宋代', '鄱江善政九贤人，文正文忠更绝伦。桃李旧邦千里爱，丹青遗像两朝臣。\n\n不同赤土祠刘阮，端胜睢阳庙远巡。安得神仙返魂药，九原唤起静边尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '祠颜范二公' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题洋菊四十四种 其二十八 海红莲', '弘历', '清代', '团毬簇稠叠，卷筒舒蓓蕾。韎韐殊赩然，原出大红海。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题洋菊四十四种 其二十八 海红莲' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('顷尝梦至善生院赋诗一联己丑七月十三日因游', '周必大', '宋代', '门外千竿竹绕墙，清风终日注回廊。\n五年未续梦中梦，得得来追三伏凉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '顷尝梦至善生院赋诗一联己丑七月十三日因游' AND p.poem_author = '周必大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大江东去 美人', '王寂', '元代', '破瓜年纪，黛螺垂、双髻珍珠罗抹。娅?吴音娇滴滴，风里啼莺声怯。飞燕精神，惊鸿标致，初按梁州彻。舞裙微褪，汗香融透春雪。少陵词客多情，当年曾烂赏，湖州风月。自恨寻春来已暮，子满芳枝空结。湘佩轻抛，韩香偷许，空想凌波袜。章台杨柳，可堪容易攀折。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大江东去 美人' AND p.poem_author = '王寂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长街', '胡云飞', '当代', '长街无背景，存在无烙记。街中千万人，纷其生老死。\n\n各怀一玉匣，投赠于彼此。斯匣如太古，浑圆不可启。\n\n斯匣如太古，暗黑不可视。但见主人替，往来无穷已。\n\n辗转复辗转，迢递复迢递。\n\n我居在长街，我思在匣中。匣中何所有，或者谓时钟。\n\n或者谓面孔，或者本来空。路人皆不问，衣冠自从容。\n\n投之复报之，往来两匆匆。长街无背景，演出无始终。\n\n长街我所居，玉匣思所托。我思如秋花，寂然开且落。\n\n我思如流星，一瞬光灼灼。何用斯匣为？弃之如敝屩。\n\n虽弃终相随，风中影绰约。安得仙之人，赐我以玉钥。\n\n仙人不可见，追思亦不禁。匣中竟何有，或者竟本心。\n\n辗转复辗转，谁心在我襟？迢递复迢递，我心何处寻？\n\n路人皆不知，往来各骎骎。长街无背景，存在自消沉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长街' AND p.poem_author = '胡云飞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('得覃韵', '李孙宸', '明代', '文酒经时事事谙，西山还共访名蓝。盟同泉石宁终负，歌到骊驹便不堪。\n\n谁以去天誇尺五，繇来赋芋总朝三。扶摇九万鹏程在，六月从君暂徙南。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '得覃韵' AND p.poem_author = '李孙宸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('生查子', '顾随', '现代', '身如入定僧，心似随风草。\n心自甚时愁，身比年时老。\n空悲眼界高，敢怨人间小。\n越不爱人间，越觉人间好。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '生查子' AND p.poem_author = '顾随';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湖上送家兄入都', '朱荃', '清代', '幽鸟唤春春又阑，六桥烟柳簇征鞍。客途再到悲欢异，樽酒相逢去住难。\n\n五夜鸡声惊昨梦，连朝花信破轻寒。停鞭不尽蝉联语，回首高城夕照残。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湖上送家兄入都' AND p.poem_author = '朱荃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙 其四 四时闺词', '顾太清', '清代', '六出花飞冬日寒。金炉拨火炷沉檀。一杯清茗啜龙团。\n\n梅蕊迎风香细细，竹稍压雪叶攒攒。阿谁忍冻卷帘看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙 其四 四时闺词' AND p.poem_author = '顾太清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题半月岩', '吴文震', '宋代', '□灵通一窍，如月未全盈。\n外□山河界，中涵蚌蛤精。\n银潢斜□断，玉斧半修成。\n莫讶平分破，难亏半体明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题半月岩' AND p.poem_author = '吴文震';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三峡闻猿', '贯休', '唐代', '历历数声猿，寥寥渡白烟。应栖多月树，况是下霜天。 \n 万里客危坐，千山境悄然。更深仍不住，使我欲移船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三峡闻猿' AND p.poem_author = '贯休';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送杨士宪之云南佥事', '杨士奇', '明代', '万里滇南候绣衣，炎州十月凛霜飞。丰城古剑神光动，一道澄清属有威。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送杨士宪之云南佥事' AND p.poem_author = '杨士奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自君之出矣八首 其八', '刘琏', '明代', '自君之出矣，芳香销玉体。思君如河冰，坚凝直到底。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自君之出矣八首 其八' AND p.poem_author = '刘琏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('除夕四首 其三', '谢元汴', '明代', '今夕家园宴，慈亲杖履轻。弟兄别后梦，儿女岁时情。\n\n念我高楼上，辛勤白发生。小亭方筑就，编竹待而成。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '除夕四首 其三' AND p.poem_author = '谢元汴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三山林教谕先生挽诗', '黄仲昭', '明代', '蚤际风云登月窟，旋承雨露下天除。棘闱多士推衡鉴，芹泮诸生仰范模。\n\n浮世功名归一梦，朝阳文彩见三雏。褒封况有双鸾诰，万丈龙光照故墟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三山林教谕先生挽诗' AND p.poem_author = '黄仲昭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶成三首 其二', '邓肃', '宋代', '梦破南窗袅水沉，卧看素壁挂瑶琴。丝丝细雨晚烟合，阁阁鸣蛙蔓草深。\n\n但得瓮边眠吏部，不妨跨下辱淮阴。何时楼上登晴景，一醉聊舒万里心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶成三首 其二' AND p.poem_author = '邓肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病题桐江', '彭汝砺', '宋代', '叹息医工拙，矜嗟旧疾牢。衰容虽冻雀，烈气尚惊涛。\n\n羁旅双尘鬓，尘埃一布袍。远乡滋味恶，空益梦魂劳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病题桐江' AND p.poem_author = '彭汝砺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('主簿陈元矩署中畜鹅', '赵公豫', '宋代', '素羽称修洁，苍音听不禁。田间宜养育，官舍莫栖侵。\n\n博爱儒生量，矜全物性心。从今传韵事，谁谓擅山阴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '主簿陈元矩署中畜鹅' AND p.poem_author = '赵公豫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('家舅和前韵示余因再用韵奉寄', '邓雅', '明代', '南郊庙前溪水流，紫盖峰下梧桐秋。片云相隔不可会，两屩未閒何所求。\n\n荒城厌见豺虎乱，深谷喜同麋鹿游。吾舅安居莫叹息，杜陵多难留鄜州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '家舅和前韵示余因再用韵奉寄' AND p.poem_author = '邓雅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('莲', '弘历', '清代', '承晖扬素质，冒沼弄幽馨。朅对怀今昔，坐令空色形。\n\n展新芳意足，依旧晚桡停。堪以方清淑，非关比尹邢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '莲' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三贞篇寄纳麟哈刺参政幕下僚友', '王逢', '元代', '梧西女陈氏，颜色绝胜玉。阿耶灯窗下，古传常暗读。\n\n义须嫁官人，麻枲心所足。兵麾忽东指，烽火蔓平陆。\n\n鱼鳖遭颠连，鸡狗同迫逐。猰貐哆其口，反噬机上肉。\n\n母子泣相誓，宁死不汝辱。春辉黯门楣，寒日照鬼录。\n\n皇天实鉴临，家庙为惨肃。髽妇亦在难，自判受命独。\n\n臂血溅贼衽，贼叹为敛缩。差差白刃间，伟节惊耳目。\n\n荒野云雪暮，缅想会深竹。水流风悲鸣，星迸万羽镞。\n\n回首陷没地，何限委沟渎。大参行当来，恤典具简椟。\n\n前湖百世祀，明妆俨车服。从以双素鸾，配享畴敢黩。\n\n孤蓬任漂转，馀齿寄草木。倡兹三贞篇，庶用矫浮俗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三贞篇寄纳麟哈刺参政幕下僚友' AND p.poem_author = '王逢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠林处士逋', '潘阆', '宋代', '云剪乌纱雾剪衣，存神养气语还稀。人人尽唤孙思邈，只恐身轻白日飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠林处士逋' AND p.poem_author = '潘阆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄杨高士', '释慧远', '宋代', '富有十年别，贫无一觉眠。\n好来同夜话，相共酌清泉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄杨高士' AND p.poem_author = '释慧远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游慈云分韵得是字', '陈著', '宋代', '僧关可人心，况此晴色美。\n蹈藓滑路多，访菊香处是。\n引饮吞山光，清啸落松子。\n我有即事诗，就扫石壁纪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游慈云分韵得是字' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('衡岳感怀二首 其二', '胡直', '明代', '恭闻夏后圣，秉志切元元。洪波荡中土，隐若裂肺肝。\n\n不辞排决力，宁论胼胝艰。去家七八载，三过不入门。\n\n诚精格玄昊，金书下层峦。禹拜受此书，治水识其端。\n\n鞭挞蛟与螭，疏凿江与汉。江汉故汤汤，河淮无溢湍。\n\n九州一以平，四隩罄欢颜。上启重华帝，巡狩驻瑶幡。\n\n玄冕照林阿，韶韵播江潭。爰以上公秩，望兹南维尊。\n\n秩秩虞夏文，郁郁夔龙班。缅思此盛际，千岁不可攀。\n\n测知圣哲心，匪恣一身安。顾予道未至，愿言归山樊。\n\n山樊有故侣，终焉击壤欢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '衡岳感怀二首 其二' AND p.poem_author = '胡直';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风入松', '张鎡', '宋代', '芳丛簇簇水滨生。勾起午风清。六花大似天边雪，又几时、雪有三层。明艳射回蜂翅，净香薰透蝉声。 \n 晚檐人共月同行。疏影动银屏。指尖轻捻都如玉，听画栏、高啭流莺。道是花枝比得，不成花也多情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风入松' AND p.poem_author = '张鎡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('河满子 闻雁', '易顺鼎', '清代', '太液何时雪尽，洞庭此日波荒。水碧沙明苔两岸，湖天古怨微茫。\n\n枫叶蓼花多处，勾留半在红乡。\n\n一路冲开雨密，数声拖得秋长。只有渔翁浑不管，中流自起鸣榔。\n\n几处高楼怕听，谁教错住潇湘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '河满子 闻雁' AND p.poem_author = '易顺鼎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄闾卫之同府二首 其二', '边贡', '明代', '江上逢君感昔年，往来相见陆陵前。那知宦迹如萍梗，犹得相依一水边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄闾卫之同府二首 其二' AND p.poem_author = '边贡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登多景楼分楼高天一握为韵得一字楼非旧址惟东面可眺三隅暗甚时方改作榜称米元章书盖伪也语寺僧当易之', '周孚', '宋代', '往时百仞山，丹楼丽朝日。江天富佳致，收揽不遗一。\n\n匆匆熙丰事，电往那可诘。故基谁为徙，胜槩从此失。\n\n如窥一面网，反随三凌室。幽怀郁尘雾，老眼暗髹漆。\n\n虽云一牛鸣，每至辄悔出。使君改筑意，正欲名称实。\n\n丁丁斤斧功，趁此玄月毕。扁榜照华榱，仍须此翁笔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登多景楼分楼高天一握为韵得一字楼非旧址惟东面可眺三隅暗甚时方改作榜称米元章书盖伪也语寺僧当易之' AND p.poem_author = '周孚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送李孝先之蕲州扶其先大夫相如先生旅榇归粤三首 其三', '陈恭尹', '明代', '惜汝风尘早，艰虞及弱龄。诵诗悲陟岵，闻礼梦趋庭。\n\n剥极终来复，蓝深或出青。蕲黄张楚地，早愿返松扃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送李孝先之蕲州扶其先大夫相如先生旅榇归粤三首 其三' AND p.poem_author = '陈恭尹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再赠月蓬道人六言二首 其一', '刘克庄', '宋代', '谢公早有远志，陶子晚知昨非。帝允我乞骸疏，汝见吾衡气机。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再赠月蓬道人六言二首 其一' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉蝴蝶', '夏完淳', '明代', '春日恼人花鸟，香车宝马，陌上成行。相思满地，芳草绿到西江。\n\n旧衣香。留他荀令，新曲误，顾了周郎。枉思量。金壶滴博，银箭丁当。\n\n茫茫。玉人何处，寻伊消息，瘦了容光。只剩些些，影儿作对梦儿双。\n\n恨多情、雁传银字，愁不语、花落纱窗。对斜阳。珠帘卷起，又是昏黄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉蝴蝶' AND p.poem_author = '夏完淳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('文徵仲画老子见赠旧寄观音像并此奉谢', '薛蕙', '明代', '本家楚濑乡，远师周柱史。流沙竟长往，谷神应不死。\n\n真源古县近西原，祠宇荒凉旧宅存。不见犹龙写生色，秪同摸象解空言。\n\n衡山先生今顾陆，赠我真人真一幅。天机渊默藏根柢，日角分明辨眉目。\n\n先生高士非画师，一纸千金难易之。四方求者苦不得，我未往求先见遗。\n\n往年曾寄圆通像，髣髴白衣来海上。今者挥毫图伯阳，恍惚青牛归故乡。\n\n老夫家居贫转剧，偶然富与公侯敌。箪瓢匮乏无斗储，箧椟缄縢有双璧。\n\n平生嗜好释与仙，幸遭同病还相怜。已将彩绘作佛事，更拟形似传灵筌。\n\n学通二氏我何有，画备六法谁能先。不惭俚调酬妙品，往来聊结三生缘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '文徵仲画老子见赠旧寄观音像并此奉谢' AND p.poem_author = '薛蕙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宝月台夜坐', '谭胜祖', '明代', '一楼岩畔月，竹石倚相将。天地真容懒，湖山恕酒狂。\n\n淡云随树影，薄露出花光。偶尔逢僧话，茶烟起竹房。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宝月台夜坐' AND p.poem_author = '谭胜祖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽龙图待制徐良能墓', '范端臣', '宋代', '少日蜚声竦白袍，暮年策足上青霄。\n功名略已追前辈，事业真堪托后凋。\n谏草半焚烟寂寂，琐窗一梦夜寥寥。\n古塘原上谁行路，只有哀笳引葬箫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽龙图待制徐良能墓' AND p.poem_author = '范端臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送危教谕之桐乡', '徐溥', '明代', '寒毡元不较勋阶，吾道东南育俊才。晏岁关河劳跋涉，春风桃李费栽培。\n\n五经洞彻文光夐，万骑纵横笔阵开。最是诸生承教益，短亭衰柳惜馀杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送危教谕之桐乡' AND p.poem_author = '徐溥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟古诗二十首 其十三 拟燕赵多佳人', '弘历', '清代', '燕姝宁台舞，赵女邯郸步。阎易美服饰，曼睩工盼顾。\n\n不丰亦不约，宜喜复宜怒。古来巳称绝，汉武寄馀慕。\n\n当户理瑶琴，能谱相如赋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟古诗二十首 其十三 拟燕赵多佳人' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送刘明远客和州', '徐玑', '宋代', '十载知心友，文才尔独兼。\n病谙孤寐乐，贫识茹蔬甜。\n冬暖梅花早，年丰酒价廉。\n不愁无远信，佳句日应添。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送刘明远客和州' AND p.poem_author = '徐玑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄友', '史鉴', '明代', '与君倾盖二毛初，别后无由数寄书。江上无人问消息，红庄随马射游鱼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄友' AND p.poem_author = '史鉴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重赴京师留别山中亲友', '李英', '明代', '结束事行役，扁舟欲问津。祇因游侠去，不为住山贫。\n\n飘泊凭孤剑，驱驰愧此身。别君多慷慨，相忆白纶巾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重赴京师留别山中亲友' AND p.poem_author = '李英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪叹二绝', '洪咨夔', '宋代', '唐时三月十八雪，况复今年多一旬。\n万紫千红浑过尽，荼蘼满架与争春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪叹二绝' AND p.poem_author = '洪咨夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次郭羲仲韵柬玉山人', '张师贤', '明代', '故人一隔红云岛，相见银屏七夕前。\n花近小山当鹤广，溪深嘉树覆书船。\n参差清吹流银汉，餮殄文彝散玉烟。\n更拟此君亭子上，醉欹纱帽会群贤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次郭羲仲韵柬玉山人' AND p.poem_author = '张师贤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('盛别驾还自叙州', '邵宝', '明代', '蜀道归与鬓未皤，叙州功比汉州多。金鱼初拜明廷赐，彤管还收野老歌。\n\n嘉客可人来只尺，大夫能赋兴如何。相逢且问东皋子，泽被横江尚有波。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '盛别驾还自叙州' AND p.poem_author = '邵宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一萼红五首 其四 桃花夫人庙', '史承谦', '清代', '楚江边。旧苔痕玉座，灵迹自何年？香冷虚坛，尘生宝靥，千秋难释烦冤。\n\n指芳丛、飘残清泪，为一生、颜色误蝉娟。恩怨前期，兴亡闲梦，回首凄然。\n\n似此伤心能几？叹诗人一例，轻薄流传。雨飒云昏，无言有恨，凭栏罢鼓神弦。\n\n更休题、章台何处，伴湘波、花木暗啼鹃。惆怅明珠翠羽，断础荒烟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '一萼红五首 其四 桃花夫人庙' AND p.poem_author = '史承谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('旅次朔方 / 渡桑干', '刘皂', '唐代', '客舍并州已十霜，归心日夜忆咸阳。\n无端更渡桑干水，却望并州是故乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '旅次朔方 / 渡桑干' AND p.poem_author = '刘皂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('响水关', '皇甫汸', '明代', '飞泉来断壑，声咽不堪流。何以函关客，遥心寄陇头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '响水关' AND p.poem_author = '皇甫汸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和赵季行用兰花韵三首 其一', '刘宰', '宋代', '破除百卉发孤芳，造化工夫有抑扬。平易堂中无个事，一枝相对吐清香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和赵季行用兰花韵三首 其一' AND p.poem_author = '刘宰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('胡元之提刑寺丞迂涂相过宠示二诗次韵为谢兼', '周必大', '宋代', '惠政郡州楷，清名万口传。\n南交需按察，北阙正详延。\n契分元重复，封疆互接连。\n劳归知有日，还伫楚江边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '胡元之提刑寺丞迂涂相过宠示二诗次韵为谢兼' AND p.poem_author = '周必大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜雨不寐', '杨万里', '宋代', '雨急点不疏，瓦乾声可数。\n滴破江湖梦，合眼无後补。\n更长酒力短，睡甜诗思苦。\n已自不成眠，如何更遭许。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜雨不寐' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感遇 其三', '佟绍弼', '近代', '死去馀何憾，生还各有思。固应离可念，未觉遇俱迟。\n\n回首空梁换，重澜古井悲。转怜来日永，不必怨当时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感遇 其三' AND p.poem_author = '佟绍弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('放夜', '方回', '宋代', '深夜楼前笑语哗，禁街钟鼓暂停挝。冶游谑浪非吾事，富足欢娱有几家。\n\n春酒可能融鬓雪，书灯独自照梅花。黄柑犹见升平物，四十年前客永嘉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '放夜' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄内弟赵叔平', '王绂', '明代', '别来不觉又秋风，历想君家在眼中。稚子情娇初学语，慈亲年老近加聋。\n\n新居每对千竿竹，先陇应添几尺松。世业喜闻能复旧，休将百万一枭空。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄内弟赵叔平' AND p.poem_author = '王绂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感事 其二', '陈顺彬', '近代', '去就机宜本未谙，操刀制锦又何惭。群中半是依阿态，局外偏持慷慨谈。\n\n莫笑驽骀誇冀北，也随鸡犬到淮南。翻空多少疑团事，解作黄粱梦正酣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感事 其二' AND p.poem_author = '陈顺彬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('紫阳真人歌', '卢象', '唐代', '君不见先生耳鼻有仙骨，自号狂生中有物。金华侍讲三十年，儿戏公卿与簪笏。\n\n青门抗行谢客儿，健笔连羁王献之。长安素绢书欲遍，主人爱惜常保持。\n\n每叹二疏不足道，复言四皓常枯槁。去年寝疾弥数旬，神鬼盈庭谋一老。\n\n长男泣血求司命，少女颦眉诵《灵宝》。还如简子复归来，更与洪崖同寿考。\n\n上书北阙言授箓。税驾东州愿修道。初闻行路犹未信，果达吾君谓之好。\n\n山阴旧宅作仙坛，湖上闲田种芝草。镜湖之水含杳冥，会稽仙洞多精灵。\n\n须乘赤鲤游沧海，当以群鹅写道经。皇恩赠诗四十字，明主赐金三十镒。\n\n供帐倾朝一送归，双童驷马从兹出。回看紫绶若轻尘，远别青门嗟故人。\n\n鸳鹭差池攀羽盖，虹霓夭矫翊车轮。田田列侍浮丘伯，曾子荣过朱买臣。\n\n余高若是有先觉，灭迹归根从大朴。千载悠悠等令威，十洲漫漫思方朔。\n\n归去来，青牛顿足少迟回。忽然云雾不相见，唯有飘飘香气来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '紫阳真人歌' AND p.poem_author = '卢象';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送严上舍并寄诸公十首·寄俞君任府判', '陈造', '宋代', '忆访俞夫子，频烦挽袖留。\n酒边无俗物，尘外有高楼。\n未醉催歌扇，言归听漏筹。\n此欢谁与继，怊帐岁时遒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送严上舍并寄诸公十首·寄俞君任府判' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桑乾岭', '陈孚', '元代', '昔闻桑乾名，今日登桑乾。桑乾是否不必问，但觉两耳天风寒。\n\n大峰小峰屹相向，空际谽谺一千丈。燕云回首夕阳间，长川历历平于掌。\n\n人家如蛎粘石壁，白土堆檐高半尺。门外毡车风雨来，平地轰轰惊霹雳。\n\n汉唐百战场，绿草今满碛。野夫耕田间，犹有旧铁戟。\n\n道傍谁欤三叹息，古袍古帽江南客。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桑乾岭' AND p.poem_author = '陈孚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古三十三首 其二十六', '释师观', '宋代', '堕落眉须不得塔，三文使尽见分疏。无端大岭重饶舌，数丈龟毛举世无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古三十三首 其二十六' AND p.poem_author = '释师观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('好事近 素描', '黄绮', '当代', '日暖奈何春，村外横山亦惰。阡陌往来都识，有亲朋几个。\n\n白鸥不起占池塘，打水儿童裸。正是肌肤如乳，惹柳丝缠裹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '好事近 素描' AND p.poem_author = '黄绮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('监郡吴殿丞惠以笔墨建茶各吟一绝谢之 茶', '林逋', '宋代', '石辗轻飞瑟瑟尘，乳花烹出建溪春。世间绝品人难识，閒对茶经忆古人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '监郡吴殿丞惠以笔墨建茶各吟一绝谢之 茶' AND p.poem_author = '林逋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忧阕诣台先寄献臣天休二学士', '宋庠', '宋代', '去国三年恨，还台九死馀。凄凉曾釜粟，感咽晏楹书。\n\n鲋勺怀穷辙，鸡栖整故车。惟当亲益友，叙阔费涟如。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忧阕诣台先寄献臣天休二学士' AND p.poem_author = '宋庠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天辰', '欧阳修', '宋代', '天形如车轮，昼夜常不息。\n三辰随出没，曾不差分刻。\n北辰居其所，帝座严尊极。\n众星拱而环，大小各有职。\n不动以临之，任德不任力。\n天辰主下土，万物由生殖。\n一动与一静，同功而异域。\n惟王知法此，所以治万国。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天辰' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('端石砚', '李纲', '宋代', '端溪出砚材，最贵下岩石。珍物乃卵生，孕此马肝色。\n\n世传鸲鹆眼，通透盖其脉。颇同阮步兵，见客作青白。\n\n我来岩中游，幽探偶有获。温然一片玉，秀润满书宅。\n\n断成蛟龙池，涩滑宜笔墨。当观管城翁，沐发散简策。\n\n嗟余好陶泓，收拾积圭璧。得此馀可忘，一生能几屐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '端石砚' AND p.poem_author = '李纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山庄杂兴十首 其四', '王廷陈', '明代', '计拙堪时弃，谋生托野人。莺花无约束，木石有比邻。\n\n溪上思龙蛰，林间学鸟伸。逢人无一面，语契即情亲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山庄杂兴十首 其四' AND p.poem_author = '王廷陈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿整庵罗太宰先生八十诗 其三', '尹台', '明代', '周道中陵夷，奇邪互哓诟。狭步窘周行，曲蹊争躏蹂。\n\n仲尼振微言，百家废荒谬。浸淫拂朱翟，轲书劳堤救。\n\n嬴秦溃土崩，汉氏承蚁漏。梵语译流沙，倏焉惑群瞀。\n\n净智启高禅，妄儒私牖窦。慧悟述心性，训言遭掩糅。\n\n伟欤困知辨，攘斥功何厚。谁哉挹北斗，酌公千龄寿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿整庵罗太宰先生八十诗 其三' AND p.poem_author = '尹台';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读史杂咏十首 其四', '王士元', '清代', '少岁读诗书，齿斤齿斤恣诋訾。续经颇怪文中子，论易颇轻王辅嗣。\n\n两人死时犹少年，著述煌煌已如是。男儿一事无成身已老，试问何者可人意。\n\n古之人，勿轻议。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读史杂咏十首 其四' AND p.poem_author = '王士元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('示张仲原秀才二首 其一', '晁补之', '宋代', '去年钜野张狂澜，黄河水不到鱼山。焦城有屋仲子筑，它日能来相往还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '示张仲原秀才二首 其一' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送张子公', '吕陶', '宋代', '康定用兵日，府谷尤孤危。属当治安久，多事尽废隳。\n\n三面枕贼境，平易如通逵。重城辄议葺，浮论多背驰。\n\n贤哉光禄公，定虑先本基。百堵大兴作，据险成藩篱。\n\n城完贼已至，善守莫敢窥。泉源众所汲，公为亲解围。\n\n兵势弱不振，公能屡张威。贼退城可处，生聚始有归。\n\n于今三十年，功勋书鼎彝。边人每记忆，言者感涕挥。\n\n近日羽书至，讨伐加羌夷。庙算出帷幄，王师整熊罴。\n\n壮夫思报国，志士窃忧时。寒日朝惨淡，凄风夜号悲。\n\n昔人何卓荦，往事可追维。夫君实贤嗣，仕宦图奋飞。\n\n家声贵不坠，儒学当有为。归欤自磨砺，门阀增光辉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送张子公' AND p.poem_author = '吕陶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别赵子（赵子名德，潮州人）', '韩愈', '唐代', '我迁于揭阳，君先揭阳居。揭阳去京华，其里万有馀。 \n 不谓小郭中，有子可与娱。心平而行高，两通诗与书。 \n 婆娑海水南，簸弄明月珠。及我迁宜春，意欲携以俱。 \n 摆头笑且言，我岂不足欤。又奚为于北，往来以纷如。 \n 海中诸山中，幽子颇不无。相期风涛观，已久不可渝。 \n 又尝疑龙虾，果谁雄牙须。蚌蠃鱼鳖虫，瞿瞿以狙狙。 \n 识一已忘十，大同细自殊。欲一穷究之，时岁屡谢除。 \n 今子南且北，岂非亦有图。人心未尝同，不可一理区。 \n 宜各从所务，未用相贤愚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别赵子（赵子名德，潮州人）' AND p.poem_author = '韩愈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('月当厅', '史达祖', '宋代', '白璧旧带秦城梦，因谁拜下，杨柳楼心。正是夜分，鱼钥不动香深。\n\n时有露萤自照，占风裳、可喜影麸金。坐来久，都将凉意，尽付沈吟。\n\n残云事绪无人舍，恨匆匆、药娥归去难寻。缀取雾窗，会唱几拍清音。\n\n犹有老来印愁处，冷光应念雪翻簪。空独对、西风紧，弄一片桐阴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '月当厅' AND p.poem_author = '史达祖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塞翁吟（黄园感事）', '赵文', '宋代', '又海棠开後，楼上倍觉春寒。绿叶润，雨初乾。爱远树团团。当时胜买名花种，那信付与谁看。十载事，土花漫。但青得阑干。 \n 悲欢。思人世、真如一梦，留不住、城头日残。看眼底、西湖过了，又还见、赵舞燕歌，抹粉涂丹。凭君更酌，後日重来，直是睛难。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塞翁吟（黄园感事）' AND p.poem_author = '赵文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和杜中书九日', '史浩', '宋代', '佳人通夕赏重阳，醉尽楼边白玉缸。莫遣飞霜到丛菊，恐惊宿蝶去双双。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和杜中书九日' AND p.poem_author = '史浩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寓宝相有作', '陆游', '宋代', '扫地镜面清，烧香云气润。\n道人敬爱客，危坐目不瞬。\n童子髡两髦，经襌亦精进。\n我来愿同龛，欢喜无少吝。\n临堂坐夜分，佛灯看堕烬。\n清晨爽如秋，摄衣相问讯。\n道在氛埃表，此语其殆信。\n永愧小阮高，超然弃须鬓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寓宝相有作' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和诸庵花光十梅颂', '王柏', '宋代', '推出突栾本相，雨肥叶底清黄。\n熟后何曾酸涩，舌根自不寻常。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和诸庵花光十梅颂' AND p.poem_author = '王柏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病起二首', '陈造', '宋代', '即病偷闲却自怡，坐凭竹几独多时。\n铜炉烟畔熏风度，药臼声中昼漏迟。\n政自腐肠严酒戒，不应了事悔儿痴。\n净名文惠谁优劣，为问沾沾造化儿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病起二首' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阎太守复任西安', '顾清', '明代', '好去西安守，还乘五马车。封疆参井旧，民物汉唐馀。\n\n会府人咸喜，铨曹最已书。儿童候公久，归驾莫纾徐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阎太守复任西安' AND p.poem_author = '顾清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈', '释景元', '宋代', '有时候，有时喜，\n有时观音面，有时夜叉觜。\n或现鼠尾龙头，或现鼠头龙尾。\n偏要检非，不要检是。\n是金不博金，是水不博水。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈' AND p.poem_author = '释景元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病起谩书', '翟德方', '明代', '平生愿望出流尘，一病奄奄困此身。三十始成从政事，两恩俱未报君亲。\n\n已知得失非由我，始信乾坤不负人。馈药时来拜康子，病根拔去满胸春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病起谩书' AND p.poem_author = '翟德方';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新晴行郪水上与涪江相近', '范成大', '宋代', '涂泥初乾雨不落，日色未出暑光薄。畏途得晴天复凉，真是腰钱更骑鹤。\n\n浑浑郪水流未平，悄悄涪江如镜清。过尽江沙穿麦垄，忽有青蜩扶叶鸣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新晴行郪水上与涪江相近' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏题江心寺僧房壁', '陆游', '宋代', '史君千骑驻霜天，主簿孤舟冷不眠。\n也与史君同快意，卧听鼓角大江边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏题江心寺僧房壁' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汝忠宅待月同望之', '何景明', '明代', '空堂浊酒三人醉，万里清光迥未开。深夜西邻还鼓吹，碧天东望有楼台。\n\n虚疑星汉城边照，实怕风云海上来。坐对孤灯各愁思，九关哀角更相催。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汝忠宅待月同望之' AND p.poem_author = '何景明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('壬午秋事六章 其三 窥天', '添雪斋', '当代', '暗色秋深由梦说，窥天之事我之拙。结风偃息或为哀，明日萍浮甚于决。\n\n四野从来阴曀盈，微光只向虚空缀。听然而笑处无言，憀栗千年韶乐彻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '壬午秋事六章 其三 窥天' AND p.poem_author = '添雪斋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和子厚弟九日登魏文振亭园七首', '王之道', '宋代', '雨余东北望银屏，一带寒山映骨清。\n谁道西风能换物，染红枫树亦多情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和子厚弟九日登魏文振亭园七首' AND p.poem_author = '王之道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花 贺友新婚', '沈家恒', '明代', '莫道好春无处讨，岭上琼花，开向金闺早。酒醒香浓天未晓，一丸璧月窥窗悄。\n\n初整晨妆眉样巧，笑问檀奴，秀色餐多少。更喜今年春色好，阶前渐绿宜男草。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花 贺友新婚' AND p.poem_author = '沈家恒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('立春寄梅坛梅逸老', '范太中', '宋代', '仕路蹉跎又见春，区区深厌走红尘。\n未能解脱无穷事，长忆逍遥自在人。\n瓦缶汲泉朝灌药，羽衣蒙露夜朝真。\n洒然物外清虚境，呼吸淳元养气神。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '立春寄梅坛梅逸老' AND p.poem_author = '范太中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('月季花', '董嗣杲', '宋代', '谢了还开肯悟空，一年三十六旬中。\n相看谁有长春艳，莫道花无百日红。\n酡脸倚娇承舞雪，瘦枝扶力借柔风。\n四时常吐芳姿媚，人老那能与此同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '月季花' AND p.poem_author = '董嗣杲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('兰蕙曲 其三', '屈大均', '明代', '为蕙不为兰，是侬甘自贱。祗恐花虽多，馨香有时变。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '兰蕙曲 其三' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('腊月十七夜月同峻伯助甫席上赋 其二 得上字', '宗臣', '明代', '西风裂天荒，银河翻巨浪。残月东海头，至今不敢上。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '腊月十七夜月同峻伯助甫席上赋 其二 得上字' AND p.poem_author = '宗臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅州喜晤梁辑五光禄 其三', '丘逢甲', '清代', '一笑全输此局棋，神州苍莽欲何之？虬髯红拂无消息，身愧三原李药师。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅州喜晤梁辑五光禄 其三' AND p.poem_author = '丘逢甲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过武昌', '李敬', '清代', '四时常不极，一棹况无涯。击汰天疑路，停桡水是家。\n\n危洲行处直，远郭望中斜。沙势衔山影，波光荡日华。\n\n芦明空岸雪，叶乱晚陂霞。稍辨武昌树，初飞梦泽鸦。\n\n客愁增湍驶，楚色满蒹葭。欲访河干叟，林端见古槎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过武昌' AND p.poem_author = '李敬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东湖', '陶弼', '宋代', '宁越佳山水，东湖带郡城。\n月天高寺影，春雨一桥声。\n石上青蒲合，沙中白鸟横。\n天涯睚寥落，独往若为情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东湖' AND p.poem_author = '陶弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九月二日登高', '王鏊', '明代', '重阳未到便登高，万里天风触锦袍。山色湖光兼雨暝，诗怀酒思入秋豪。\n\n丹砂漫贮千年药，白雪先尝九月糕。北雁联翩音信杳，怀人无语首频搔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九月二日登高' AND p.poem_author = '王鏊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鲍山', '缪沅', '清代', '鲍山山色如眉绿，螺黛挽烟青簇簇。洞中闻有丫髻童，手把铜盂挹银瀑。\n\n金仙真诰落荒厓，猛虎道旁时慑伏。五色肉芝供客啖，驻景无劳更辟谷。\n\n朅来山下悄无人，间凭一杖桃枝竹。不逢羽客佩方符，但见归农驾短犊。\n\n山中居人留我住，地垆火暖新篘熟。我懒寻仙思采隐，径来就汝山斋宿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鲍山' AND p.poem_author = '缪沅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('独游', '王昌龄', '唐代', '林卧情每閒，独游景常晏。时从灞陵下，垂钓往南涧。\n\n手携双鲤鱼，目送千里雁。悟彼飞有适，知此罹忧患。\n\n放之清冷泉，因得省疏慢。永怀青岑客，回首白云间。\n\n神超物无违，岂系名与宦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '独游' AND p.poem_author = '王昌龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄中书洪益中梦菊先生四首 其三', '曹义', '明代', '望入天台客路长，江云野树思茫茫。别来每叹光阴速，屈指于今巳十霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄中书洪益中梦菊先生四首 其三' AND p.poem_author = '曹义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同胡原仲吴公路游清湍亭赋诗得流字', '刘子翚', '宋代', '出山曾几时，桂露飒已秋。\n兴来任两屐，散此默默忧。\n岚光近仍灭，鸟语静忽流。\n新亭迥临危，急润循岩陬。\n上有独树荫，下有鸣湍幽。\n长飙一振荡，俯仰闻飕飕。\n平生尘累心，净尽迥此游。\n徘徊啸咏发，瞻眺穷林丘。\n天寒云已归，山好客自留，\n悠然百不知，日月过则休。\n人生乐在我，何必遂所求。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同胡原仲吴公路游清湍亭赋诗得流字' AND p.poem_author = '刘子翚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏徐氏竹溪之景八首 其七 石坞潭', '许有壬', '元代', '郿坞金多竟不存，清坚输与老云根。潭中鳣鲔知多少，已有飞腾过禹门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏徐氏竹溪之景八首 其七 石坞潭' AND p.poem_author = '许有壬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('余秋初离庭闱冬至犹未得归夜读宛丘先生秋日忆家诗辄次韵以述旅怀', '虞俦', '宋代', '屈指西风阅岁华，半年行役苦思家。綵衣归去亲闱好，画角吹残客梦赊。\n\n病里中秋慵见月，醉中九日强簪花。朅来又过书云候，节物催人一可嗟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '余秋初离庭闱冬至犹未得归夜读宛丘先生秋日忆家诗辄次韵以述旅怀' AND p.poem_author = '虞俦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('念奴娇 其二 题叶癯仙明府翠交阁二调', '曹尔堪', '清代', '百城民社，却等闲抛去，故园归早。旧识黄莺双白鹭，重赴主人林岛。\n\n活水拖蓝，修林染碧，托出银蟾皎。蛮姬捧砚，两弯眉如扫。\n\n频向槛外澄观，伍塘帆远，只比寒鸦小。麦浪交风闻雉雊，北郭青青未了。\n\n十万兵藏，五千轻授，丙夜凭搜讨。渔歌唱和，一场春梦方晓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '念奴娇 其二 题叶癯仙明府翠交阁二调' AND p.poem_author = '曹尔堪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再赋 其一', '李正民', '宋代', '寒威逗晓入帘栊，乱雨天花帝释宫。皓皓易污休拥彗，纷纷何似祗从风。\n\n能文谁复延枚叟，乘兴真宜访戴公。老去映书无眼力，夜阑惟喜月当空。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再赋 其一' AND p.poem_author = '李正民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花铺', '郭登', '明代', '绿树冬深不怕霜，怪来风上说南方。\n人经蛮寨愁蛇蛊，客聚盘江趁虎场。\n翠黛插云山似戟，潢流蒸气水如汤。\n王师到处沾恩泽，甘雨随车洗瘴乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花铺' AND p.poem_author = '郭登';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙', '王采', '宋代', '珠箔随檐一桁垂。绣屏遮枕四边移。春归人懒日迟迟。 \n 旧事只将云入梦，新欢重借月为期。晚来花动隔墙枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙' AND p.poem_author = '王采';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望大梅欲回雪窦路险而止口占示同行', '王铚', '宋代', '起晓寻幽意气豪，冥冥重雾溼征袍。\n天扶宝势千山拱，海助寒声万籁高。\n休数兴衰两蜗角，从来忧乐一鸿毛。\n了知终老林泉是，渡水穿云久亦劳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望大梅欲回雪窦路险而止口占示同行' AND p.poem_author = '王铚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('食鱠', '李处权', '宋代', '设网机关密，磨刀意气麄。\n令人思洛鲤，愧客问江鲈。\n豆麴偏相与，橙虀未可无。\n相从频莫厌，乘兴不烦呼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '食鱠' AND p.poem_author = '李处权';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郑德予同游桃花山次韵 其一', '朱槔', '宋代', '江村卜筑路斜斜，模写癯仙四壁家。闻道读书忘肉味，不缘避世宿桃花。\n\n青山自作千年调，白眼空惊一望赊。欲买鸡豚投近社，烟蓑雨笠寄生涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郑德予同游桃花山次韵 其一' AND p.poem_author = '朱槔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小剑山', '陈湋', '近代', '磨刀割云去，屏风张镜奁。砚头九华秀，剑外一峰尖。\n\n苦李龙飞耳，香枫鬼有髯。奇情画不到，只许达摩潜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小剑山' AND p.poem_author = '陈湋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('有感', '刘汝藻', '清代', '身世茫茫万事非，歌残黄鹄泪频挥。休题旧恨添眉皱，莫放新愁减带围。\n\n荒院小猧迎客吠，空仓饥雀避人飞。韶光瞥眼春如梦，怕检箱中金缕衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '有感' AND p.poem_author = '刘汝藻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋江', '释道潜', '宋代', '赤叶枫林落酒旗，白沙洲渚夕阳微。数声柔橹苍茫外，何处江村人夜归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋江' AND p.poem_author = '释道潜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('越州歌', '汪元量', '宋代', '师相平章误我朝，千秋万古恨难消。\n萧墙祸起非今日，不赏军功在断桥！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '越州歌' AND p.poem_author = '汪元量';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('端午帖子·太上皇后阁', '周必大', '宋代', '午节人传百药良，三千玉女斗群芳。\n销忧萱草名空美，长乐宫中乐更长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '端午帖子·太上皇后阁' AND p.poem_author = '周必大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留别友人吴春洲六首 其六', '孙承恩', '明代', '把臂相看惊白头，乡心日逐水东流。故园松竹闻无恙，迟子相归续旧游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留别友人吴春洲六首 其六' AND p.poem_author = '孙承恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和赵国兴访萧氏草堂', '陈文蔚', '宋代', '四野山围面面屏，何人结屋趣方成。\n好风吹过半湖碧，白鸟飞边一点明。\n乘举半春携酒约，隔山遥夜读书声。\n买邻为爱茅斋近，试倩诗人状此情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和赵国兴访萧氏草堂' AND p.poem_author = '陈文蔚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋帖子词十叠前韵 其一', '弘历', '清代', '创成帖子值几閒，九度吟情瞥眼删。今夕又逢清籞里，可孤宝月上屏山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋帖子词十叠前韵 其一' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('刘山驿', '贡师泰', '元代', '开窗坐看千峰顶，对酒还思万里程。飞雨远随松子落，湿云近向树头生。\n\n正愁绝壁乌鸢背，忽听半空鸡犬声。安得身骑辽海鹤，遍游八极醉吹笙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '刘山驿' AND p.poem_author = '贡师泰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汴中元夕五首 其二', '李梦阳', '明代', '玉馆朱城柳陌斜，宋京灯月散烟花。门外香车若流水，不知青鸟向谁家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汴中元夕五首 其二' AND p.poem_author = '李梦阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与道卿鸣阳辈同游法海寺循平岭涉杨家坞还饮偃月冈', '王鏊', '明代', '忽忽春归不可攀，且乘高兴看湖山。回旋翠壑丹厓里，小憩青松白石间。\n\n为爱韶华连日醉，历观宦海几人还。风尘楚蜀干戈地，举酒何缘一破颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与道卿鸣阳辈同游法海寺循平岭涉杨家坞还饮偃月冈' AND p.poem_author = '王鏊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏日杂题六首 其六', '陆游', '宋代', '一叶两叶病木霣，一点两点疏萤流。水底星河秋脉脉，发根风露夜飕飕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏日杂题六首 其六' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鸳鸯湖棹歌　之九十一', '朱彝尊', '清代', '江市鱼同海市鲜，南湖菱胜北湖偏。\n四更枕上歌声起，泊遍冬瓜堰外船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鸳鸯湖棹歌　之九十一' AND p.poem_author = '朱彝尊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('静老容安庵二首 其一', '孙觌', '宋代', '离离风中花，深落任所之。泛泛水中萍，流转复在兹。\n\n静公湖海士，世网那得縻。独有铁石心，不与燥湿移。\n\n巢肩统灵鹊，支床馀老龟。区区了官事，应解笑儿痴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '静老容安庵二首 其一' AND p.poem_author = '孙觌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五月十一日夜且半梦从大驾亲征尽复汉唐故地', '陆游', '宋代', '天宝胡兵陷两京，北庭安西无汉营。\n五百年间置不问，圣主下诏初亲征。\n熊罴百万从銮驾，故地不劳传檄下。\n筑城绝塞进新图，排仗行宫宣大赦。\n冈峦极目汉山川，文书初用淳熙年。\n驾前六军错锦锈，秋风鼓角声满天。\n苜蓿峰前尽亭障，平安火在交河上。\n凉州女儿满高楼，梳头已学京都样。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五月十一日夜且半梦从大驾亲征尽复汉唐故地' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('于报端读太夷先生壬戌重阳诗有叹其登高北望之意适炎造兄以新刊海藏楼诗本见赠作此并奉怀', '黄浚', '近代', '后山死后无重九，留句千年待郑公。南菊自知徵士意，北风犹想大王雄。\n\n公诗王道真难学，臣笔传人两未穷。我亦逢辰工感赋，恨无健气敌秋嵩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '于报端读太夷先生壬戌重阳诗有叹其登高北望之意适炎造兄以新刊海藏楼诗本见赠作此并奉怀' AND p.poem_author = '黄浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辰溪二首 其一', '薛瑄', '明代', '分司门外大江横，怪石参差岸不平。眼底秋山无限好，坐中凉吹有馀清。\n\n枣垂翠叶丹砂重，蜡满青林素练明。莫道蛮荒少题咏，龙标诗有五溪名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辰溪二首 其一' AND p.poem_author = '薛瑄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('襄阳二首 其一', '陈造', '宋代', '自怜薄宦走红尘，相见山灵厌俗氛。咫尺岘山无计到，祇应飞雨是移文。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '襄阳二首 其一' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('首春感怀', '高启', '明代', '初春风日自妍华，客意登临只感嗟。\n陌上惊尘随去马，城边遗柳断栖鸦。\n乱来未觅无兵地，愁在空思有酒家。\n咫尺苑西谁解问，早梅还发去年花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '首春感怀' AND p.poem_author = '高启';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁源山中', '王特起', '金朝', '野夫不识武城宰，问之无言色微改。但说今年秋雨多，黄芪满谷无人采。\n\n踏遍西城锦石盘，莫投佛屋解征鞍。隔林依约见灯火，山谷人家初夜寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁源山中' AND p.poem_author = '王特起';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古二十九首 其十二', '释师体', '宋代', '万里无云银汉横，大方玄路等闲行。阿爷智量世希有，女子圆光顶𩕳生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古二十九首 其十二' AND p.poem_author = '释师体';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵答东嵎云巢二宪伯七首 其五', '黄衷', '明代', '狂爱童儿画纸文，离离关眼暗相分。双奁若许当长日，合筑棋坛拜冠军。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵答东嵎云巢二宪伯七首 其五' AND p.poem_author = '黄衷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感怀', '张逢尧', '清代', '秋老霜飞夜奈何，乌衣旧燕痛无多。武陵花识秦渔父，曲水觞迷晋永和。\n\n声断蟪蛄窥上古，阵空蝼蚁闭南柯。昨宵宴罢麻姑酒，遥听蓬莱起棹歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感怀' AND p.poem_author = '张逢尧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竟夜示伯承弟', '何吾驺', '明代', '竟夜沾花雨，无言对伯承。扣门深似海，永夕坐如冰。\n\n鼠戏频窥阁，蛾狂屡拂灯。遥怀寒雪里，欲枕不胜肱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竟夜示伯承弟' AND p.poem_author = '何吾驺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮 其七', '黄绮', '当代', '红楼隔雨相望冷。青袍似草年年定。疑误有新知。帘疏燕误飞。\n\n柔情终不远。莫叹佳期晚。来去发春慵。仙衣尽带风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮 其七' AND p.poem_author = '黄绮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶题', '叶茵', '宋代', '曲肱玩味圣贤书，识破人间总畏途。\n盛欲对君言所以，又应诮我爱之乎。\n百年役役雁来去，一梦昏昏鹿有无。\n堪笑季鹰犹左计，求归何必待莼鲈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶题' AND p.poem_author = '叶茵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十八坊诗 介福', '王十朋', '宋代', '兹地有神宇，人人来荐羞。神虽能介福，福亦自须求。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十八坊诗 介福' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辋川钓者图', '练子宁', '明代', '家住黄溪上，金川似辋川。凉风垂钓坐，明月棹歌还。\n\n绿水雕胡饭，金鳞缩项鳊。鉴湖如可乞，相与诵尧天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辋川钓者图' AND p.poem_author = '练子宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宋中遇陈二', '高适', '唐代', '常忝鲍叔义，所期王佐才。如何守苦节，独此无良媒。 \n 离别十年外，飘飖千里来。安知罢官后，惟见柴门开。 \n 穷巷隐东郭，高堂咏南陔。篱根长花草，井上生莓苔。 \n 伊昔望霄汉，于今倦蒿莱。男儿命未达，且尽手中杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宋中遇陈二' AND p.poem_author = '高适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('集句拟刘文纲少参悼亡 其二十五', '朱诚泳', '明代', '隐几无言有所思，惨烟悽雨不胜悲。梧桐叶上偏萧索，始是思君肠断时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '集句拟刘文纲少参悼亡 其二十五' AND p.poem_author = '朱诚泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题张宗苍云栖图', '弘历', '清代', '心爱云栖未恝忘，为图佳概命宗苍。江边宛识山村路，竹下曾吟水月房。\n\n泉箔岩扉相掩映，笠檐笏地足徜徉。香光妙迹留题在，长共烟霞护法王。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题张宗苍云栖图' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郑敬常求题画像因用同姓八事赞之', '凌云翰', '元代', '清白传家古所难，门名通德又开端。履声未近星辰听，早带还经岁月看。\n\n五色云中知姓氏，七株松下具衣冠。毂推驿置非无意，谷口先须赋考槃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郑敬常求题画像因用同姓八事赞之' AND p.poem_author = '凌云翰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自睢宁至下邳道中杂诗六绝句 其三', '姚燮', '清代', '笋石当坡翠有棱，高丫四出罥风藤。萧疏一幅倪迂画，添个看云古衲僧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自睢宁至下邳道中杂诗六绝句 其三' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留别故城士民四首 其一', '夏诒垣', '清代', '甘陵古郡卫河滨，承乏匆匆两度春。新喻原为公仆职，旧箴还凛宰官身。\n\n此邦俗此唐风俭，作吏名惭汉代循。差喜萑苻今渐靖，寸心安慰别吾民。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留别故城士民四首 其一' AND p.poem_author = '夏诒垣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题草堂寺', '黄复圭', '元代', '草堂禅寺北山陲，想见鸣驺入谷时。猿鹤如怀海盐令，鱼龙犹护绍兴碑。\n\n排岩树老秋来早，上殿僧稀晓散迟。我亦于今抗尘土，临风惭读孔璋移。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题草堂寺' AND p.poem_author = '黄复圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('入道诗十九首 其九', '王庆升', '宋代', '时节因缘不偶然，既由人事亦关天。功深德厚天孚祐，玉籍标名骨自仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '入道诗十九首 其九' AND p.poem_author = '王庆升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('孝宗皇帝挽词二首', '叶适', '宋代', '伦德加文景，雄才自武宣。\n道终遗万乘，丧制尽三年。\n暂乞狂胡命，常持复汉权。\n全将一孝字，高谥百王前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '孝宗皇帝挽词二首' AND p.poem_author = '叶适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('入直左掖中贵乞诗有作', '屠隆', '明代', '两朝出入有辉光，五夜疏钟漏未央。\n万树宫花歌宝扇，千门御柳映明珰。\n心如碧草生金辇，身是红云近玉皇。\n一样人间明月色，惯于天上听《霓裳》。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '入直左掖中贵乞诗有作' AND p.poem_author = '屠隆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆西坡梅', '仇远', '宋代', '杖藜久不到西坡，苔上梅花积渐多。\n野屋荒凉谁管领，酒尊期会竟蹉跎。\n韶光二月已强半，乐事一生能几何。\n赖有邻园春可折，洗瓶斜插在行窝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆西坡梅' AND p.poem_author = '仇远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('从蜀后主幸秦川上梓潼山', '王仁裕', '唐代', '彩仗拂寒烟，鸣驺在半天。黄云生马足，白日下松巅。 \n 盛德安疲俗，仁风扇极边。前程问成纪，此去尚三千。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '从蜀后主幸秦川上梓潼山' AND p.poem_author = '王仁裕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄严州刘太守', '吴与弼', '明代', '我爱霜松托趣深，慇勤特表岁寒心。当年缟纻休相讶，遥寄新诗咏断金。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄严州刘太守' AND p.poem_author = '吴与弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再赋', '陈与义', '宋代', '堂堂李杜坛，谁敢蹑其址。\n先生坐坛上，持钺令余子。\n由来文字伯，不但表奏伟。\n高怀淡无嗜，寓兴或留此。\n平生上林手，避谤淹二始。\n登临意超然，笔落风雨似。\n事异柳司马，辛苦记山水。\n乐哉邦无事，那待猛政理。\n驾言慰吾民，不愧城门轨。\n看山笑邹湛，句外寄深旨。\n岩树阅几客，尚余尧时髓。\n抚板歌公诗，未暇知余事。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再赋' AND p.poem_author = '陈与义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('茅屋', '薛嵎', '宋代', '茅舍竹椽短，不劳朱恶施。\n高无神鬼瞰，贫与子孙宜。\n近古意全朴，当风势亦危。\n梅花有幽致，一树隔疎篱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '茅屋' AND p.poem_author = '薛嵎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('久不雨', '陈淳', '宋代', '草庐卧龙目未开。岩溪作霖手未抬。\n苍生望望亦劳尔，滂霈甘泽从何来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '久不雨' AND p.poem_author = '陈淳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再和 其六', '项安世', '宋代', '丰年官事无何，梅月诗情最多。白水暗添沤界，青苔乱长松科。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再和 其六' AND p.poem_author = '项安世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望京府赏红梅', '郝经', '元代', '汴梁宫中绛绡梅，移向汴河堤上栽。青条团掿杏花颗，琐细向阳才半开。\n\n张公小队呼我饮，风色偃髯寒气凛。玉衔径踏黄河冰，貂帽飒檐掀紫锦。\n\n金鞍细马歌舞人，雪压小桥不动尘。入门下马簇花宴，红莲旧府花正新。\n\n玉川金波碧香酒，折花遍插分素手。春透寒梢未全绽，风流正要胭脂瘦。\n\n赏梅不用歌落梅，缓歌却著银笙催。爱香细撷生霞蕊，浮动云腴嚼一杯。\n\n本是前村冷澹花，不称王侯将相家。明朝会散更向明月底，藉雪冻吟疏影里。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望京府赏红梅' AND p.poem_author = '郝经';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次啸云师韵感时', '汪茂荣', '当代', '金瓯新奠泰山安，盈耳纶音拨置难。挟纩殊怜三伏暖，吟诗尚怯五更寒。\n\n齐家无处室虚白，蠹国有人颜渥丹。领略牵丝游戏意，莫成轻命倚危栏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次啸云师韵感时' AND p.poem_author = '汪茂荣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢钖铭兄赠字', '陈振家', '当代', '故郡书家细琢磨，端庄妍秀见无多。而今恍得黄庭帖，不用山阴道士鹅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢钖铭兄赠字' AND p.poem_author = '陈振家';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄林大参允吉', '祁顺', '明代', '地署同官早见知，十年重会楚天涯。升沉宦迹怜今日，尔汝交情似昔时。\n\n问讯恍疑身是梦，相看都觉鬓如丝。无端又动停云思，谩拂焦桐候子期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄林大参允吉' AND p.poem_author = '祁顺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春 其二 寿淮东制置', '洪咨夔', '宋代', '饮马咸池，总辔昆崙，横骛九州。庆中兴机会，天生山甫，非常事业，天授留侯。\n\n左搏龙蛇，右驯虎兕，万里中原谈笑收。功名早，便貂蝉猎猎，飞出兜牟。\n\n新氓无限欢讴。尽卖剑卖刀归买牛。正麦摇熏吹，黄迷断垄，秧涵朝雨，绿遍平畴。\n\n眼底太平，不图再见，罗拜焚香青海头。从今去，愿君王万岁，元帅千秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春 其二 寿淮东制置' AND p.poem_author = '洪咨夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次华使张承宪公游汉江', '申光汉', '明代', '天上河源落五台，楼前澄影隔尘埃。\n杨花春尽帆归远，楮岛烟消雁影来。\n物色不随游子去，芳樽今为使君开。\n三韩胜地皆方丈，更借仙风倾一杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次华使张承宪公游汉江' AND p.poem_author = '申光汉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('食鱼', '穆修', '宋代', '南有嘉鱼异，常趋四月期。\n江天专伺至，烟网密争垂。\n乍戏汀苹末，初循水荇湄。\n竞摇轻舴艋，宽罩碧涟漪。\n占浦搜深藻，空波出素髭。\n数头馀赤质，二色类银姿。\n货鬻斯为切，鲜腴敢暇知。\n青钱邀价直，华屋市新奇。\n珠沫缘条煦，霜鳞逐刃堕。\n扣颅琼聚骨，剖腋锦分肌。\n味佐芳菘惬，香参苦笋宜。\n羹瓯融腻玉，脍助罥寒丝。\n湘鱓非吾偶，河鲂孰与夷。\n薦新奚尚鲔，稔毒即殊{左鱼右几}。\n鲈讶休官易，鲭嫌醒酒迟。\n自当频佐膳，所惜易过时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '食鱼' AND p.poem_author = '穆修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过桃川万寿宫二首', '王阮', '宋代', '翁子洞头魂黯黯，桃川山上目凄凄。\n自怜终失邯郸步，不是重来旧路迷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过桃川万寿宫二首' AND p.poem_author = '王阮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早春寄周致尧', '陈雷', '元代', '百年身世浑如寄，何处他乡是故乡。柳态正须春弄色，梅花自与雪生香。\n\n扬雄寂寞玄犹白，贺监风流醉亦狂。倘许胜缘同晚岁，梨林风致即柴桑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早春寄周致尧' AND p.poem_author = '陈雷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和孙端叟寺丞农具十五 其六 钱镈', '梅尧臣', '宋代', '诗称庤钱镈，南亩兴农作。宁唯务芟薙，岂不在刈穫。\n\n收功向嘉谷，托用随芒屩。太平兹所重，坐见销锋锷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和孙端叟寺丞农具十五 其六 钱镈' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赋得揽察草木犹未得示诸子五首 其三', '谢元汴', '明代', '勿将死玉匹生刍，义竹春深咒老梧。种得兔丘为媚草，化成婺女作桑弧。\n\n人才信已同蜍志，燕市今当访狗屠。龙比负尸徒往事，倚天长剑客星孤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赋得揽察草木犹未得示诸子五首 其三' AND p.poem_author = '谢元汴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题汪水云诗十首', '罗志仁', '宋代', '丰乐华楼已劫灰，涌金春色未尘埃。\n道人有道轩窗静，那处湖光不好来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题汪水云诗十首' AND p.poem_author = '罗志仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南山', '陈谠', '宋代', '天造其山，在贵之阳。二十四峰，拔地峭刚。其山维何，如彼玉苍。\n\n宅位于离，火德之祥。南山何有，有方其岩。若堂甚夷，若门者三。\n\n穹者圆盖，植者羽参。石像天成，匪凿匪劖。陟彼山巅，有洞益奇。\n\n南北户通，千里頫窥。伊晋之洪，采荣于斯。丹飞井霤，木润草滋。\n\n昔我太宗，云章下贲。于皇仁庙，奎文狎至。岩处有辉，神护孔閟。\n\n丕昭圣朝，声化远暨。南山不骞，天子万年。南山不朽，天子万寿。\n\n无量惟寿，与天齐久。小臣作诗，永飏于后。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南山' AND p.poem_author = '陈谠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赏牡丹', '王弘诲', '明代', '朱明开令节，邀赏对名花。潋滟欺秾李，纷披夺丽华。\n\n天香横席满，国色倚阑斜。绿叶舍朝露，红英缀晚霞。\n\n迷蜂娇吐蕊，戏蝶绽分葩。幻字留仙种，凝脂出帝家。\n\n醉妆妃子妒，敛态洛神誇。名入骚坛重，根当锦障赊。\n\n洛阳春有价，金谷净无瑕。芍药堪成侍，芙蓉似失嘉。\n\n自缘生富贵，偏许事豪奢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赏牡丹' AND p.poem_author = '王弘诲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和希颜', '冯璧', '金朝', '虎守天门未易通，庾尘无扇障西风。主人何负盗憎主，公论不明私害公。\n\n老伏固非千里骥，冥飞似是五噫鸿。纷纷往事渠知几，都付崧巅一笑中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和希颜' AND p.poem_author = '冯璧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南来好伴', '郭之奇', '明代', '四载依依几送迎，故山结色此能生。春情广覆千峰落，霞侣先开一壑盈。\n\n相过不移知我素，此中何有祇云清。南来好伴兹堪恋，去去江天日暮情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南来好伴' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七月望后寄寒碧上人', '徐波', '明代', '楚鬼微吟上峡谣，中元法食可相招。凭师为譬兴亡恨，雨打秋坟骨亦销。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七月望后寄寒碧上人' AND p.poem_author = '徐波';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再次韵二首 其二', '袁桷', '元代', '阁道新平旧石摧，望乡使客意嵬嵬。犀牛坐见降王去，杜宇声随望帝来。\n\n三卯录成魂有燐，五丁神泣劫扬灰。推酾欲作乡邻会，挥手先催弩矢回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再次韵二首 其二' AND p.poem_author = '袁桷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '释晓莹', '宋代', '清泉槛外流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '释晓莹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('摘园菊赠谢仆射举诗', '王筠', '南北朝', '灵茅挺三脊，神芝曜九明。菊花偏可憙，碧叶媚金英。\n\n重九惟嘉节，抱一应元贞。泛酌宜长主，聊荐野人诚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '摘园菊赠谢仆射举诗' AND p.poem_author = '王筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('为刘君符赋乐山诗', '陆文圭', '宋代', '山体本至静，仁体亦如之。\n乐者有深味，鲁论无费辞。\n目玩唯自得，心契若有期。\n逝川同一旨，妙理无容窥。\n刘公本好古，雅志非好奇。\n诸君为著语，殆类爱山诗。\n泉石涵清思，松柏媚幽姿。\n古来山中人，此道未必知。\n蜡屐张乃癖，拄笏殆成凝。\n独有首阳高，薇苦甘如饴。\n得仁即无怨，千载真吾师。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '为刘君符赋乐山诗' AND p.poem_author = '陆文圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('听百舌鸟', '王维', '唐代', '上兰门外草萋萋，未央宫中花里栖。亦有相随过御苑， \n 不知若个向金堤。入春解作千般语，拂曙能先百鸟啼。 \n 万户千门应觉晓，建章何必听鸣鸡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '听百舌鸟' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春残', '唐彦谦', '唐代', '景为春时短，愁随别夜长。暂棋宁号隐，轻醉不成乡。 \n 风雨曾通夕，莓苔有众芳。落花如便去，楼上即河梁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春残' AND p.poem_author = '唐彦谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留题常熟顶山僧居', '范仲淹', '宋代', '平湖数百里，隐然一山起。\n中有白龙泉，可洗人间耳。\n吾师仁智心，爱兹山水音。\n结茅三十年，不道日月深。\n笑我名未已，来问无端理。\n却指岭边云，斯焉赠君子。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留题常熟顶山僧居' AND p.poem_author = '范仲淹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送童子敬赴省', '姚勉', '宋代', '满望飞腾几许年，一闻充赋喜如颠。金经炉冶锋方锐，木饱风霜节始坚。\n\n此去稳登云里路，定知荣冠籍中仙。近闻上蔡鸬洲合，一似前年锦水连。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送童子敬赴省' AND p.poem_author = '姚勉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金缕曲·梅花岭瞻史公遗像', '魏元戴', '清代', '心共朝衫赤。岸乌纱、临淮空障，东南半壁。惨变先皇臣欲殉，眉宇久无人色。\n\n况肠断、高堂永诀。黯淡精神横泪眼，陡辛酸、动我心如铁。\n\n迟不去，日方昃。\n\n调停四镇真诚竭。枉整顿、朝廷小小，内奸牵掣。付与孤忠成结局，浩气沧溟应塞。\n\n又何必、钟山埋骨。精魄倘逢留后约，怅燕云、几洒忧时血。\n\n更莫问，扬州月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金缕曲·梅花岭瞻史公遗像' AND p.poem_author = '魏元戴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红·无利无名', '张昪', '宋代', '无利无名，无荣无辱，无烦无恼。夜灯前、独歌独酌，独吟独笑。况值群山初雪满，又兼明月交光好。便假饶百岁拟如何，从他老。\n知富贵，谁能保。知功业，何时了。算箪瓢金玉，所争多少。一瞬光阴何足道，便思行乐常不早。待春来携酒殢东风，眠芳草。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红·无利无名' AND p.poem_author = '张昪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('林和中家观画卷五首 其一 寒芦飞雁仍和子中修撰旧韵', '郭祥正', '宋代', '芦黄水落秋将暮，鼓翼各寻云外路。为问归飞归底处，我今亦向江南去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '林和中家观画卷五首 其一 寒芦飞雁仍和子中修撰旧韵' AND p.poem_author = '郭祥正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浪淘沙令 庐山即景', '林伯渠', '近代', '牯岭雨声喧，气象万千。爱听东谷水潺。日照香炉知何处？\n\n雾里云端。智慧何人先？卡尔开山。重峦叠嶂更新鲜。\n\n一二三四大手笔，宝藏兴焉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浪淘沙令 庐山即景' AND p.poem_author = '林伯渠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南史六首 其三 褚渊', '郑学醇', '明代', '翠屏金屋捲流苏，秉烛曾称伟丈夫。世族不更时事改，舅家宗祐倩谁扶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南史六首 其三 褚渊' AND p.poem_author = '郑学醇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('艳秋新婚并画并蒂莲花并题', '曾习经', '清代', '孔翠鸳雏略费评，楼前红烛笑相迎。偶然拾得青羊句，并蒂莲花愿往生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '艳秋新婚并画并蒂莲花并题' AND p.poem_author = '曾习经';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送严十五郎之长安', '戎昱', '唐代', '送客身为客，思家怆别家。暂收双眼泪，遥想五陵花。 \n 路远征车迥，山回剑阁斜。长安君到日，春色未应赊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送严十五郎之长安' AND p.poem_author = '戎昱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送李致美之任云中', '王寂', '金朝', '宸衷简在付陪京，摩拊疲氓藉老成。金阙共瞻卿月出，野人相庆福星明。\n\n先声雷殷妫州路，和气春回魏帝城。想见郊迎笳鼓竞，吏民惊叹綵衣荣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送李致美之任云中' AND p.poem_author = '王寂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄题六江桥', '庄昶', '明代', '礼乐乾坤已备任，江山底处许孤襟。六江老眼吾真到，惠爱何人此最深。\n\n欲济无梁须尔是，买田为井亦如今。深山惟有区区在，得尽裁成万古心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄题六江桥' AND p.poem_author = '庄昶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菊花', '潘牥', '宋代', '露叶霜枝矮作团，淡黄残绿故瓓珊。柴门尽日无人到，独自栽花独自看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菊花' AND p.poem_author = '潘牥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬和杜五弟晴朝独坐见赠', '李峤', '唐代', '平明坐虚馆，旷望几悠哉。宿雾分空尽，朝光度隙来。 \n 影低藤架密，香动药阑开。未展山阳会，空留池上杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬和杜五弟晴朝独坐见赠' AND p.poem_author = '李峤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('顺风放舟', '胤禛', '清代', '长河风力驶，千里片帆轻。桨歇村频转，桡停岸自迎。\n\n野凫冲荇起，归雁拂云鸣。试问邮亭吏，何如驷马行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '顺风放舟' AND p.poem_author = '胤禛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和陕州参军李通微首夏书怀呈同寮张裳段群二先辈', '姚鹄', '唐代', '公门何事更相牵，邵伯优贤任养闲。满院落花从覆地， \n 半檐初日未开关。寻仙郑谷烟霞里，避暑柯亭树石间。 \n 独为高怀谁和继，掾曹同处桂同攀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和陕州参军李通微首夏书怀呈同寮张裳段群二先辈' AND p.poem_author = '姚鹄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词 其二十三', '赵佶', '宋代', '集英亲殿策才豪，盈庑纷纷尽雪袍。礼乐问题人罕记，就纡黼座继兰膏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词 其二十三' AND p.poem_author = '赵佶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重登庐山感怀', '陈香梅', '未知', '四十年来烟雨多，国恨家仇奈若何；英雄抗日征战死，天涯游子唱离歌。\n牯岭东西谷尚在，郎人士旧风波；庐山别业怀往事，好汉坡前望银河。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重登庐山感怀' AND p.poem_author = '陈香梅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('依韵酬葛秋岩陶体四首', '释文珦', '宋代', '山林自多趣，况此晴和时。\n我友贲然来，相娱以琴诗。\n仓庚遗好音。薰风发清吹。\n悠然与心会，安能遽忘兹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '依韵酬葛秋岩陶体四首' AND p.poem_author = '释文珦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('初归同诸弟夜坐', '谢与思', '明代', '拂尘坐来久，轻飏生绤衣。半年几今夕，为客正东归。\n\n露裛竹梢润，萤穿书幌微。但愁城际月，清漏促光辉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '初归同诸弟夜坐' AND p.poem_author = '谢与思';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('箱根玉泉楼', '林朝崧', '清代', '山拥楼前后，水随山短长。水声疑急雨，日色易斜阳。\n\n入浴灵泉煖，踏歌瑶草芳。烟云足供养，吾欲住仙乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '箱根玉泉楼' AND p.poem_author = '林朝崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉和李令扈从温泉宫赐游骊山韦侍郎别业', '卢僎', '唐代', '风后轩皇佐，云峰谢客居。承恩来翠岭，缔赏出丹除。 \n 飞盖松溪寂，清笳玉洞虚。窥岩详雾豹，过水略泉鱼。 \n 乡入无何有，时还上古初。伊皋羞过狭，魏丙服粗疏。 \n 白雪缘情降，青霞落卷舒。多惭郎署在，辄继国风馀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉和李令扈从温泉宫赐游骊山韦侍郎别业' AND p.poem_author = '卢僎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄题四明张氏南园', '魏汝贤', '宋代', '修篁曲折绕墙东，风景辋川孰兴同。\n过雨凉生千树外，乱山青入一楼中。\n高人尔日联吟社，逐客当年作寓公。\n别后新诗又多少，双鱼应许寄邮筒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄题四明张氏南园' AND p.poem_author = '魏汝贤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其二', '方岳', '宋代', '一钱太守今贪吏，五柳先生歙富民。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其二' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观祝少林所藏画三首 其一 米元晖画', '赵蕃', '宋代', '萧寺相从三十日，知君有画未曾窥。烟云过眼还收去，恰似凭栏立久时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观祝少林所藏画三首 其一 米元晖画' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙 其一 感怀次颖庐韵', '熊盛元', '当代', '翠鸟啼时晓梦回，罗浮影事漫惊猜。悔耽诗酒误生涯。\n\n蓬鬓初飘残腊尽，冰澌乍坼锦鳞来。一襟幽素为谁开？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙 其一 感怀次颖庐韵' AND p.poem_author = '熊盛元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄题周功父溪园三咏·嫣然亭', '张栻', '宋代', '闻说亭花好，居然似蜀乡。\n色深姿不俗，香淡意能长。\n高烛留深夜，轻阴护晚芳。\n何心较桃李，只拟答春光。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄题周功父溪园三咏·嫣然亭' AND p.poem_author = '张栻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('溪桥散步', '秦奭', '明代', '老去观书兴易阑，绿阴清昼况多闲。杖藜扶我溪头步，看尽湖南十里山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '溪桥散步' AND p.poem_author = '秦奭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋思四首 其一', '林章', '明代', '不知秋何如，明月照人寝。上照凤凰琴，下照鸳鸯枕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋思四首 其一' AND p.poem_author = '林章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('效长吉体', '刘有庆', '宋代', '穷庐夜雪没驼脊，黄沙号风冰结石。\n燕姬二八髻垂漆，柔荑斜抱箜篌立。\n老羌踏歌歌勅勒，黄金流星酒杯窄。\n红氍毹暖春云湿。缕金团衣猩血滴，\n玉钗醉滑鹍弦急。角声满空霜裂骨，\n十万狞君掩襟泣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '效长吉体' AND p.poem_author = '刘有庆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('武担山感事 其三', '孙应时', '宋代', '身不入莲社，意非同漆园。閒来阅风物，归去老山村。\n\n气味故相许，渊源须细论。灯前秋夜永，未可付忘言。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '武担山感事 其三' AND p.poem_author = '孙应时';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('念奴娇·隆乾间事', '刘克庄', '宋代', '隆乾间事，两翁有、手泽遗编曾纪。余掌兰台修纂到，景定初开忠邸。坏起复麻，奋涂归笔，嚼碎张巡齿。德音犹在，非卿何足语此。 \n 老来兹事都休，问门前宾客，今朝来几。达汝空函，投伊大瓮内，谁曾提起。丹汞灰飞，黄粱炊熟，跳出槐宫里。儿童不识，秃翁定是谁子。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '念奴娇·隆乾间事' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('方思道送西峰', '王守仁', '明代', '西峰隐真境，微境临通衢。行役空屡屡，过眼被尘迷。\n\n青林外延望，中閟何由窥？方子岩廊器，兼已云霞姿。\n\n每逢泉石处，必刻棠陵诗。兹山秀常玉，之子囊中锥。\n\n群峰灏秋气，乔木含凉吹。此行非佳饯，谁为发幽奇？\n\n奈何眷清赏，局促牵至期。悠悠伤绝学，之子亦如斯。\n\n为君指周道，直往勿复疑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '方思道送西峰' AND p.poem_author = '王守仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七月十四日观虹', '赵完璧', '明代', '半天云雨半天晴，雌蜺连蜷斜照明。莫自巫阳归意倦，晚拖腰带背人横。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七月十四日观虹' AND p.poem_author = '赵完璧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋月 其二', '文同', '宋代', '望外物容澄似水，坐中秋力凛如刀。此身直愿乘双翼，飞上三峰第一高。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋月 其二' AND p.poem_author = '文同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大风起', '陶安', '明代', '大风起，大风起，扫荡烟尘净如洗。火龙吹燄成赤云，鼓铸乾坤又一新。\n\n鸾旗豹车过沛里，父老子弟争迎喜。向年离家才庶民，今日还乡是天子。\n\n酒酣情浓思故旧，慷慨悲嗟舞长袖。复除户户动欢声，千秋万岁君王寿。\n\n壮哉亲唱大风歌，金石铿轰奈乐何。君不见拔山盖世骨先朽，何在威加诧雄赳。\n\n又不见深室悬钟烹走狗，何用猛士为之守。大风起兮云飞扬，不如膏雨流滂滂。\n\n威加海内归故乡，不如帝德天下光。安得猛士守四方，不如王佐之才登庙堂，所以汉道不克承三王。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大风起' AND p.poem_author = '陶安';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采莲曲', '郭翼', '元代', '莲子复莲子，苦心郎不尝。为郎剥莲子，莲子忆空房。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采莲曲' AND p.poem_author = '郭翼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题湘灵鼓瑟', '马臻', '元代', '沅湘水阔风萧萧，水风敲佩天光摇。为弹宝瑟传幽愫，一点柔红泻香露。\n\n苍梧恨锁云欲流，湘花背日烘春愁。人间有梦到不得，仙山翠滑江浪黑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题湘灵鼓瑟' AND p.poem_author = '马臻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青溪曲 其四', '景翩翩', '明代', '与欢深夜归，小妹调筝歇。并坐结同心，引到楼头月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青溪曲 其四' AND p.poem_author = '景翩翩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('故仆射司马文正公挽词四首', '张耒', '宋代', '伊洛平生兴，园林独乐居。\n曾过郑公里，得御李膺车。\n华屋当年客，名山异代书。\n定知传不朽，埋玉自沾裾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '故仆射司马文正公挽词四首' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风月堂夜饮', '方岳', '宋代', '霜洗横枝月上初，春彝更可共谈无。\n玉杯一一寒於雪，贮以诗肠渺似湖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风月堂夜饮' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('落魄', '陆游', '宋代', '落魄东吴莫笑侬，今年要不负春风。\n闲愁掷向乾坤外，永日移来歌吹中。\n酒浪欲争湖水绿，花光却妒舞衫红。\n公卿忧责如山重，肯信人间有放翁！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '落魄' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梁阮研宰相帖赞', '岳珂', '宋代', '巨济取帖，断于李唐。\n而予何人，波及于梁。\n然而考硬黄之流别，辨缃素之古香。\n并之以淳化秘阁之迹，印之以绍兴御府之章。\n於戏斯文，不忝厥藏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梁阮研宰相帖赞' AND p.poem_author = '岳珂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('释奠诗', '王僧达', '南北朝', '时泰道畅，礼备乐修。启痒选俊，博教深求。民人鳞萃，淑美云浮。\n\n师尊训浃，嘉敬载柔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '释奠诗' AND p.poem_author = '王僧达';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵玉溪生春雨以应两圈诗会', '陈忠平', '当代', '春丝密密织纤衣，念汝衣单梦久违。偶尔帘开清影动，原来燕啄紫泥归。\n\n千山翠黛凝还叠，满院芳华落渐稀。庄蝶应怜双翅冷，窗前不见共于飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵玉溪生春雨以应两圈诗会' AND p.poem_author = '陈忠平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '徐寿仁', '宋代', '放怀追许谢，洗耳笑巢由。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '徐寿仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('村饮', '陆游', '宋代', '少年喜任侠，见酒气已吞，一饮但计日，斗斛何足论。\n绿草满雉场，红旗植球门，三叫落乌帻，倒泻黄金盆。\n银炉炽兽炭，狐兔纷炮燔。\n浩歌撼空云，壮志排帝阍。\n回首今几时，去日如车奔，朱颜辞晓镜，白发老孤村。\n邻翁劝黍酒，稚子供鱼飧。\n功名信已乎，万事付乾坤！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '村饮' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅影', '王柏', '宋代', '梅花已清绝，明月忽横窗。\n孤影知难并，群花已竖降。\n淡痕开画帐，皓色掩书缸。\n寂寞素娥冷，须臾拥去幢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅影' AND p.poem_author = '王柏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人', '谢薖', '宋代', '人间离合常相半。璧月宁长满。九秋风露又方阑。何日小窗相对、话悲欢。 \n 月华临夜宜人醉。老去嗟颜悴。君如玉树照清空。况有凝之道蕴、一尊同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人' AND p.poem_author = '谢薖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绝句五首 其二', '黎贞', '明代', '谁怜客里病厌厌，自觉乡思日日添。从此无心爱良夜，任教花影过疏帘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绝句五首 其二' AND p.poem_author = '黎贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天 其二 上巳日会饮卫生袭之家园', '段成己', '金朝', '殢酒偿春笑二豪。题诗品物愧时髦。心如幽鸟忘机静，身似虚舟到处漂。\n\n须富贵，是何朝。一杯聊慰楚人骚。逢花堪赏应须赏，座有嘉宾尊有醪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天 其二 上巳日会饮卫生袭之家园' AND p.poem_author = '段成己';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暮春张考功助甫邀游韦氏园时梁舍人思伯偕至 其四', '黎民表', '明代', '脱帽当松顶，移舟傍竹阴。岂知青琐客，还有绿萝心。\n\n思苦诗篇警，情忘酒盏深。寥寥山吏部，千载此知音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暮春张考功助甫邀游韦氏园时梁舍人思伯偕至 其四' AND p.poem_author = '黎民表';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清明日同朱君华亭、姚君岫章踏青就李氏杏林小酌', '刘清漳', '近代', '佳节寻芳傍运河，神沙庙侧又重过。黄金染遍千章柳，绿水吹来万叠波。\n\n大地含生负景气，皇天造化寓冲和。杏林小酌花盈盏，醉卧春风尽忘它。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清明日同朱君华亭、姚君岫章踏青就李氏杏林小酌' AND p.poem_author = '刘清漳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀昔吟八首 其二 张九云先生', '曹于汴', '明代', '清白信清白，日远扬辉光。片札世人珍，乞米帖同芳。\n\n堂堂八座尊，候俸制母裳。邻翁售以宅，昕夕为徬徨。\n\n流传聊彷佛，峙岳悬春旸。所叹文昭后，高丘柏已戕。\n\n天道不可问，人生惟允臧。孤凤鶱云汉，谁与之颉颃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀昔吟八首 其二 张九云先生' AND p.poem_author = '曹于汴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又答林镇江', '邵宝', '明代', '麻姑山下石矶边，舣棹逢君是此年。\n落月梦长千里外，归云心远九峰前。\n东曹史牍忙中事，南国诗筒病后缘。\n公暇漫从江郭眺，沧浪歌起白鸥天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又答林镇江' AND p.poem_author = '邵宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('有赠 其二 刘峻', '刘斯奋', '当代', '飞名廿载杂文场，埋剑归来草树香。割断苍凉中岁感，东山菊影倚刘郎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '有赠 其二 刘峻' AND p.poem_author = '刘斯奋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('点绛唇 谷雏为作瑶山行役图，因题其上', '饶宗颐', '近代', '刺眼奇峰，当年曾是经行处。朔风如虎。山上斜阳舞。\n\n又向天涯，蓬转惊如故。心无住。漫劳缣素。觅取归时路。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '点绛唇 谷雏为作瑶山行役图，因题其上' AND p.poem_author = '饶宗颐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题嘉州嘉望亭', '韩琦', '宋代', '欲知藩境得嘉名，试策筇枝上此亭。江色照城平似练，岚光堆槛活如屏。\n\n好遨民阜充衢乐，出品花奇袭坐馨。使驲暂来闲寓目，几多高意在鸿冥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题嘉州嘉望亭' AND p.poem_author = '韩琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟发长沙四首 其二', '薛瑄', '明代', '已觉长沙北，犹瞻岳麓西。天浮湘水阔，树入楚山低。\n\n岸芷馀香草，丛篁染旧啼。昔贤游览地，我亦为留题。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟发长沙四首 其二' AND p.poem_author = '薛瑄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('孔雀吟寄国学保存社', '胡雪抱', '近代', '孔雀栖珠崖，餐香出南海。修翎时一舒，金气横空霭。\n\n珍禽动遥和，奇服垂璎彩。乘时各有耀，离合目精骇。\n\n似彼深心人，芳誉私相采。惺惺惜惺惺，结爱不能解。\n\n岂无俊鹦哥，鲫溜学雏婢。传语生飞谣，诵经妄忏悔。\n\n宁知清浊异，狐媚徒滋败。志洁寡所营，沉浸养云采。\n\n十年丰其羽，偶露神潇洒。饮啄自有真，焉在饫虾蟹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '孔雀吟寄国学保存社' AND p.poem_author = '胡雪抱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题史督师墨迹', '郑孝胥', '清代', '鸷鸟翻飞自有时，图功布局不妨迟。驽骀四镇终俱败，太息扬州史宪之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题史督师墨迹' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头 为龚节孙题种橘图', '曹贞吉', '清代', '玉局昔年客，秃鬓老仙翁。思移林屋嘉树，饱啖洞庭红。\n\n疑作亭名楚颂，眷此素荣绿叶，惨淡比青枫。有志那能遂，遗迹大江东。\n\n仿瞻子，怀古意，画图中。雨蓑风笠，长镵白木苦匆匆。\n\n且自耕云半亩，转眼霜林千颗，一笑对山童。忘却生绡里，欲倩右军封。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头 为龚节孙题种橘图' AND p.poem_author = '曹贞吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂韵', '大宁', '清代', '峰顶屋三间，松边石一片。早晚云飞来，只有樵夫见。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂韵' AND p.poem_author = '大宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('信丰江口乘小舟入雩都访友人罗', '张天赋', '明代', '琴剑路迢迢，春风袭客袍。雾开山骨现，风起浪头高。\n\n草色连坡绿，莺声隔岸遥。雩都门户远，分付梦先敲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '信丰江口乘小舟入雩都访友人罗' AND p.poem_author = '张天赋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('台阳笔记题词 其一', '包礼', '清代', '要从沧海涉风波，才算人间阅历多。剿寇奇功同大树，论文雄辩等长河。\n\n台阳德政苍生福，山左清名白雪歌。一自归来无个事，行踪到处寄吟哦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '台阳笔记题词 其一' AND p.poem_author = '包礼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再登南楼怀元舆三首 其一', '郭祥正', '宋代', '欲上层楼足力微，世情尘事老方知。离骚一曲何人会，空使潇湘鬼物悲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再登南楼怀元舆三首 其一' AND p.poem_author = '郭祥正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上谷歌八首上楚中丞', '尹耕', '明代', '新河洗马晚苍苍，风急城孤古膳房。\n分道往年频失利，筑垣今日见周防。\n转输几实饥人腹，锋镝新扶战士疮。\n乳哺庙谋应不后，坐看穷徼系苞桑。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上谷歌八首上楚中丞' AND p.poem_author = '尹耕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春雨', '王缜', '明代', '黑云堆墨暗朝曦，甘澍当春正及时。细细蛛丝游碧落，森森银烛傍瑶池。\n\n太平有象三农乐，灌溉无私万物知。涸砚愿沾涓滴润，拟歌圣德被新诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春雨' AND p.poem_author = '王缜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵道中', '郑獬', '宋代', '六国相排一局棋，岸头百草野烟微。\n树深啼鸟自相失，山静晚云犹未归。\n濡口潮回残照满，石城春尽乱花飞。\n周郎屈指图天下，谁道江南玉鱠肥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵道中' AND p.poem_author = '郑獬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晓发辞夫矶时李泂溉之友先行', '何中', '元代', '荻暗鸡鸣村，平皋下残月。参差邻舫语，橹声带潮发。\n\n露华望中白，蓬阴散秋发。沙鸟知曙鸣，海云上空灭。\n\n念我前行友，青山已飞越。迟尔及相携，无嗟赏心歇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晓发辞夫矶时李泂溉之友先行' AND p.poem_author = '何中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟行即事七首 其一', '朱淑真', '宋代', '帆高风顺疾如飞，天阔波平远又低。山色水光随地改，共谁裁剪入新诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟行即事七首 其一' AND p.poem_author = '朱淑真';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一络索二首 其二', '王时翔', '清代', '双扇题诗愁别意。碧筠新制。几年风雨泣湘江，染尽了、斑斑泪。\n\n误纳佳人袖里。怕添憔悴。索还未许但须藏，慎莫展、相思字。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '一络索二首 其二' AND p.poem_author = '王时翔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉命视部篆岁除日履任奉呈桂翁少傅 其一', '严嵩', '明代', '亭玉张筵迥，袍绯拥绶新。丹霄通雨露，华省切星辰。\n\n拔擢惭非分，遭逢庆此身。所希阳道泰，明日万方春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉命视部篆岁除日履任奉呈桂翁少傅 其一' AND p.poem_author = '严嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登峨眉 其八', '毛澄', '清代', '澄碧古潭渺，落木号西崖。龙子三寸余，头角藏风雷。\n\n海水缩归钵，养此千岁孩。铁销南极垂，石扇中天开。\n\n琼楼十日出，花发金银台。玉女千余人，飘飖凌九垓。\n\n云璈辍灵响，贻我镂霞杯。蹑烟笑相语，汉武非仙才。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登峨眉 其八' AND p.poem_author = '毛澄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古三十六首 其十二', '释惟一', '宋代', '和尚尊位如何，突出日面月面。光艳烁破乾坤，五眼觑之不见。\n\n觑得见，何似寻常腊月扇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古三十六首 其十二' AND p.poem_author = '释惟一';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其五十四', '晏殊', '宋代', '遥想江南此时节，小梅黄熟子规啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其五十四' AND p.poem_author = '晏殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闺怨四首', '赵蕃', '宋代', '辞少不尽意，辞多还尽纸。\n纸尽意无穷，相思似流水。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闺怨四首' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送鹌鸭腊龚养正二首 其二', '陈造', '宋代', '骚人茹粥耐支离，过眼风光不到诗。乡味慇勤劝开肉，未妨新句解人颐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送鹌鸭腊龚养正二首 其二' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西园春兴因赠雪庭上人兼简张公讲师', '耶律铸', '元代', '万丈虹霓络紫烟，笙歌清沸雨馀天。满庭芳草翠如积，一洞碧桃明欲然。\n\n流水引来梅坞底，春风吹到酒垆边。散花唤起毗邪梦，从此无心号谪仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西园春兴因赠雪庭上人兼简张公讲师' AND p.poem_author = '耶律铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('初春', '释函是', '明代', '东风初拂月初弦，寂寞柴门送雁天。梦断梅花空见叶，望深杨柳未成烟。\n\n一声画角山城远，万里行人春树边。珍重白云啼鸟处，几回惆怅绿萝前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '初春' AND p.poem_author = '释函是';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('访子威都事不遇', '黄清老', '元代', '清晓抱绿绮，来就夫君弹。\n夫君久已出，野水流花间。\n石涧度微雨，秋生湖上山。\n松阴坐永日，心与云俱闲。\n人事有离合，白鸥聊共还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '访子威都事不遇' AND p.poem_author = '黄清老';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('缺门遇王三兄师文', '晁说之', '宋代', '生民本羁旅，何以娱今朝。风雨崤渑道，离别秋冬交。\n\n忽复有好怀，故人道旁招。如狂语错乱，疑梦情飘飘。\n\n君须何尽白，我志则全消。忧患君恐可，图书兴尚豪。\n\n玷圭宜委土，良骥乃系匏。但愿不再辱，敢慕无久劳。\n\n马蹄分异县，朔吹结同袍。三年以为期，嵩少理居巢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '缺门遇王三兄师文' AND p.poem_author = '晁说之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('折杨柳', '朱成泳', '明代', '灵州城下柳，多被官军窃。\n犹余拂地条，更苦行人折。\n无复眼窥春，不见花飞雪。\n今君赴玉关，将何赠离别。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '折杨柳' AND p.poem_author = '朱成泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五月六日先为马蹶而伤左足自清漳千里舆归闽宪是日之夜坐占长句', '谢肃', '明代', '何幸蒙恩不自酬，此心宁敢为身谋。塞翁得马未为福，乐子下堂方有忧。\n\n难把股肱裨帝力，欲冯耳目赞皇猷。驰驱未效先成跛，绛烛华轩坐泪流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五月六日先为马蹶而伤左足自清漳千里舆归闽宪是日之夜坐占长句' AND p.poem_author = '谢肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('建德溪涨大作感怀', '魏观', '明代', '久雨逢戊晴，戊日雨不止。羽气凄乘宫，土德沦不纪。\n\n晻晻阴晦凝，四野连蓄水。绝壁洄冲波，玄林渺中沚。\n\n下上鸥鹭驯，沈浮蜃蛟喜。田庐聚岑阿，渔艇系桑梓。\n\n官租欲谁徵，军乏且无已。爰𨋎昏垫情，罔究疏浚理。\n\n悠悠古圣人，惟日思复起。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '建德溪涨大作感怀' AND p.poem_author = '魏观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史上·成帝', '陈普', '宋代', '元帝斋宫纳弁儿，阿娇金屋篡歌姬。\n披香博士多才学，刘氏家传有未知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史上·成帝' AND p.poem_author = '陈普';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('朱鹭', '穆孔晖', '明代', '刷羽春塘寂，腾身碧落遥。碧鸡非我友，白雉任谁招。\n\n海僻丹霞满，嵓深绿树饶。沙岸曝朝日，蒲流戏晚潮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '朱鹭' AND p.poem_author = '穆孔晖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄留二君仪', '郭祥正', '宋代', '今岁看书眼觉昏，忆君待酒只销魂。临漳姑孰五千里，怀抱何时得再论。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄留二君仪' AND p.poem_author = '郭祥正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古梅', '程炎子', '宋代', '水边山脚友渔樵，梅欲窥人故故招。\n树剥龙鳞黏碧藓，枝翘鹤膝糁红椒。\n诗如老杜吟东阁，梦约逋仙过断桥。\n好待月窗清影瘦，传他神子上生绡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古梅' AND p.poem_author = '程炎子';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寒食行二首 其一', '胡奎', '明代', '江南三月梨花雨，寒食邻家哭儿女。阿爷战死长兄存，二十年来别乡土。\n\n存无信息死无归，胡蝶春风泪满衣。纸钱空挂枯杨树，存者不知埋骨处。\n\n一百五日年年来，天外游魂何不回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寒食行二首 其一' AND p.poem_author = '胡奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蒋中丞庭下芙蓉三首', '滕岑', '宋代', '菊与为朋竹与邻，闭门谁见晓妆新。\n不须多羡苏堤好，车马往来尘污人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蒋中丞庭下芙蓉三首' AND p.poem_author = '滕岑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天·和霜青韵', '王韶生', '近代', '往事萦回寸寸心。流光弹指去来今。浮名渐觉焦中鹿，密意仍珍叶底禽。\n\n鲜荔子，熟林檎。两般情味一般深。云罗万里无消息，怪底樽前事苦吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天·和霜青韵' AND p.poem_author = '王韶生';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠蔡内翰九逵', '金大车', '明代', '清朝散史鬓毛斑，江左词人数往还。彩笔调高追汉代，玉堂官冷压仙班。\n\n醉攀春柳晴看月，卧放晨衙早闭关。他日思君寻旧隐，荷衣冲雨洞庭山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠蔡内翰九逵' AND p.poem_author = '金大车';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送王衢之任德之推官', '魏野', '宋代', '从军重叠继家声，雅称风流旧信灵。\n功业即看辉圣日，科名先已应台星。\n丝蚕地说连河朔，戎马尘闻近虜庭。\n正是穷秋雨多际，水堪回首向郊坰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送王衢之任德之推官' AND p.poem_author = '魏野';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('河中八咏 其七 杨惠之维摩像', '赵秉文', '金朝', '一默传心已失机，更求形似转成痴。至今遗像兀不语，犹似当初问法时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '河中八咏 其七 杨惠之维摩像' AND p.poem_author = '赵秉文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('槐', '李之世', '明代', '空翠摇阶云影凉，秋来槐叶几飘黄。种时人尚高于树，今过墙头如许长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '槐' AND p.poem_author = '李之世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('双声子 其二', '薛建吾', '近代', '浦滨萧国，白门燕市，堪怜南北奔劳。频年羁旅，萧斋岑寂，素娥屡伴无聊。\n\n金兰协好，倾别绪，曾共良宵。欢难再，境全改，茫茫幽恨难消。\n\n看长空，星静云幕卷，桂轮拥出重霄。金波扬彩，银蟾横影，多情未把人抛。\n\n奈孤帏独守，消瘦了，旧日丰标。开窗邀取，婵娟可愁，碧落风高。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '双声子 其二' AND p.poem_author = '薛建吾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪纱 题王蓉珊女士海沤集二阕 其一', '程颂万', '清代', '淡影于人画着螺。瘦蟾延想未成歌。忍抛诗思奈才何。\n\n妙迹黄初临洛浦，双栖白下誓明河。家山破后尽风波。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪纱 题王蓉珊女士海沤集二阕 其一' AND p.poem_author = '程颂万';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上元后南溪泛舟联句', '韦骧', '宋代', '野渡半篙水，春风一苇航。柳梢舒嫩绿，梅萼泛幽香。\n\n绣羽惊波起，翠鳞跳日光。环城得佳趣，清思满高塘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上元后南溪泛舟联句' AND p.poem_author = '韦骧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('月夜闻雁', '任丽金', '清代', '独坐南窗下，初晴月倍明。云中新雁唳，却作故乡声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '月夜闻雁' AND p.poem_author = '任丽金';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('武夷山中四首', '蔡沈', '宋代', '余昔隐屏南，春风驻征骖。\n开门傍水面，结屋依山岚。\n千崖互纡郁，万象中浑涵。\n居然岁月深，寒花露毵毵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '武夷山中四首' AND p.poem_author = '蔡沈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山家春晓', '李时勉', '明代', '日高照见松窗里，照人春眠犹未起。家僮洒扫及中堂，唤起客来供盥洗。\n\n披衣随步小窗外，杨柳依微莺细语。皆言昨夜风雨恶，绿树披离花满地。\n\n老父庭前扫落花，扫开春径莫教遮。怕有客来寻旧术，不妨竹里引轻车。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山家春晓' AND p.poem_author = '李时勉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古墨篇寿韩大雅参议', '周伯琦', '元代', '苍松千岁姿，灵根伏琥珀。吐气结晴云，化作古玄璧。\n\n清芬㜶芝兰，坚质等金石。上进蓬莱宫，遂冠龙宾伯。\n\n磨研发春英，灿烂翻琼液。密传邹鲁心，仰写羲周画。\n\n风雷兴礼乐，日星耀方策。岂惟儒者功，实系斯文脉。\n\n君子坐庙堂，群臣赖滋泽。良辰持此寿，播誉永无斁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古墨篇寿韩大雅参议' AND p.poem_author = '周伯琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('灵洲醉中赋', '黄佐', '明代', '青林碧海环高台，孤根独立云之隈。神鳌跋浪远天动，老鹤警霜幽梦回。\n\n西川词翰出下土，南海衣冠朝上台。一尊如醉兀然坐，万里长风吹月来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '灵洲醉中赋' AND p.poem_author = '黄佐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋夜二首 其一', '欧大任', '明代', '秋风西北至，河汉横中天。他乡况久居，游子私自怜。\n\n蟪蛄鸣且凄，鸿雁何翩翩。叹息夜中起，揽衣白云前。\n\n故人一尺书，关山邈以绵。宁当如参商，别离多盛年。\n\n携手思行游，何时早归旋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋夜二首 其一' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂十四首 其一', '释印肃', '宋代', '雪人通身却吃骂，兔角拄杖三十下。龟毛索子钓虚空，道理本来非昼夜。\n\n元不借□□，宝所谁知价。一道常光即我心，逼塞虚空无缝罅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂十四首 其一' AND p.poem_author = '释印肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清华阁', '邹浩', '宋代', '泉石清华世岂知，萧然无是亦无非。二年于此陪鸥鹭，收得閒中勋业归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清华阁' AND p.poem_author = '邹浩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('村居即事', '晁补之', '宋代', '小麦青青大麦稀，蚕娘拾茧盈筐归。放牛薄暮古堤角，三四黄莺相趁飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '村居即事' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('莲花峰早起与印上人', '曹玘', '清代', '欲曙未曙候，空山无可名。但见鸟飞处，淡然秋云生。\n\n烟霞多变态，若与群峰争。涧响共趋壑，并作新泉声。\n\n即此旦暮气，将以移人情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '莲花峰早起与印上人' AND p.poem_author = '曹玘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二月二十日述怀', '刘崧', '明代', '别时曾赋落梅花，江上风寒燕子斜。过却清明三日雨，荼䕷亭上客思家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二月二十日述怀' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鄜台', '杜纯佑', '宋代', '两载低眉著小冠，一台高築地平宽。\n向阳花木齐教放，天下无春似此间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鄜台' AND p.poem_author = '杜纯佑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红 仙吕', '周邦彦', '宋代', '昼日移阴，揽衣起、春帷睡足。临宝鉴，绿云撩乱，未忺妆束。\n\n蝶粉蜂黄都褪了，枕痕一线红生肉。背画栏、脉脉悄无言，寻棋局。\n\n重会面，犹未卜。无限事，萦心曲。想秦筝依旧，尚鸣金屋。\n\n芳草连天迷远望，宝香熏被成孤宿。最苦是、蝴蝶满园飞，无人扑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红 仙吕' AND p.poem_author = '周邦彦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙 其五', '赵尊岳', '近代', '懊恨当楼一抹山。为谁空翠约轻寒。杜鹃声里日长闲。\n\n芳约总随幽梦远，倦云莫误锦书还。半灰心字惜香残。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙 其五' AND p.poem_author = '赵尊岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('即席点韵赋方砚', '赵必象', '宋代', '一片端溪云，至宝俗眼惊。\n体方而质刚，翰林叨宠荣。\n楮君同出处，松侯难弟兄。\n紫肝马肤润，绿晕鸲肯明。\n自笑谪仙狂，曾倩妃子擎。\n我爱清庙瑟，人吹高门笙。\n龙尾与凤咮，圆巧相逢迎。\n吾友管城公，奚假乎猩猩。\n留此镇山房，移文鸥鹭盟。\n好方已成癖，焉用圆为卿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '即席点韵赋方砚' AND p.poem_author = '赵必象';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄昭德兄弟', '晁说之', '宋代', '莫言无合亦何伤，旅雁卑飞怯稻梁。\n南亩荒芜嵩少远，却来楫口祭勾芒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄昭德兄弟' AND p.poem_author = '晁说之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和庞丞相', '宋祁', '宋代', '顾我支离甚，惟公念不才。\n朱颜为列郡，白发入中台。\n阁道通天禄，宫门拂斗魁。\n论班元后郑，作赋或延枚。\n病肘垂杨老，危心一橹摧。\n根愁江北变，叶喜洛阳来。\n自昔边州重，当年蜀驭催。\n烧烽看朔漠，扪井歷崔嵬。\n粗可繙前史，何能调禁财。\n流光成浩荡，孤宦易嫌猜。\n曲外悲絃剩，机头谤锦开。\n无功惭远志，有吏笑然灰。\n左辖真虚忝，仙曹复滥陪。\n门鶋愁眩转，轩鹤老毡毸。\n倾否知攸往，成章恧所裁。\n贾生空问卜，楚客但劳媒。\n特召依明主，生还揖上台。\n缇油观册府，巾履记翘材。\n长跪怀人句，徐传道旧杯。\n今兹宣父冶，终得铸颜回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和庞丞相' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('惜分飞 忆从二姑', '储慧', '清代', '欲别还期相聚首。记得叮咛时候。一去音沉久。病馀弱骨摧残否。\n\n匪石贞心终自守。荼毒怎生禁受。玉质应非旧。连宵梦见分明瘦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '惜分飞 忆从二姑' AND p.poem_author = '储慧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吊王勃用达此韵', '释函是', '明代', '高阁凌霄尚壮哉，何人风雨渡江来。影沈湖水秋烟冷，韵遏匡云碧嶂开。\n\n多艺如君应薄命，閒情似我亦怜才。遥知万古长天色，一度登临恨一回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吊王勃用达此韵' AND p.poem_author = '释函是';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上陈县尹二首', '刘应李', '宋代', '温公宅子富公池，并入尧夫户不知。\n百亩但添官里赋，一编惟说橐中诗。\n自怜老去无能役，正恐儿成不了痴。\n有口尚能夸尹在，莫教白发困行移。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上陈县尹二首' AND p.poem_author = '刘应李';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('随咏绝句一组 其十', '添雪斋', '当代', '曩日海风初起时，梦中心外两难支。非非是是既如幻，怎地相离悲复悲？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '随咏绝句一组 其十' AND p.poem_author = '添雪斋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄伯兄季质及诸弟 其三', '金幼孜', '明代', '金台为客动经年，北望乡山万里天。书札久无朋旧问，官居惟有老亲怜。\n\n白云渺渺西江外，归雁翩翩落日边。早晚淦头逢驿使，殷勤为我寄长篇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄伯兄季质及诸弟 其三' AND p.poem_author = '金幼孜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('相国清河王挽歌', '温子升', '南北朝', '高门讵改辙，曲沼尚馀波。何言吹楼下，翻成薤露歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '相国清河王挽歌' AND p.poem_author = '温子升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郡中上元灯减旧例三之二而又迎送使客七首 其五', '杨万里', '宋代', '不是东风巧剪裁，如何春夜碧莲开。江城寂寞无歌舞，唤得梅花劝一杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郡中上元灯减旧例三之二而又迎送使客七首 其五' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和渊明饮酒二十首 其十八', '赵秉文', '金朝', '汉儒传注学，未为无所得。秦火少完书，岂免乌焉惑。\n\n后儒补罅漏，圣道稍开塞。俗士喜操戈，又一秦相国。\n\n且共欢一觞，多言不如默。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和渊明饮酒二十首 其十八' AND p.poem_author = '赵秉文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('海棠四首 其三', '杨万里', '宋代', '竞艳争娇最是他，教人嫌少不嫌多。初酣晓日红千滴，晚笑东风淡一涡。\n\n自是花中无国色，非关格外占春窠。开时悭为渠侬醉，却恨飘零可若何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '海棠四首 其三' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄南浦谪官', '郑谷', '唐代', '多才翻得罪，天末抱穷忧。白首为迁客，青山绕万州。 \n 醉欹梅障晓，歌厌竹枝秋。望阙怀乡泪，荆江水共流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄南浦谪官' AND p.poem_author = '郑谷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹤', '张咏', '宋代', '共怜洁白本天姿，纵在泥尘性不卑。\n况是稻梁厌足日，好寻烟月却归时。\n迹参诗雅何年尽，名击仙经四海知。\n应到昆丘指来历，曾陪鸳鹭浴华池。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹤' AND p.poem_author = '张咏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('信士画真请赞 其一', '释印肃', '宋代', '非迷非悟，谁强名模。无相三昧，不受涂糊。越色超声无个事，连声不断念苏卢。\n\n眉芒动处千光含，自肯除非大丈夫。持心应不失，谋事便忘真。\n\n谁识元明宝，虚劳几度春。因见普庵老，示我体皆纯。\n\n但依无著性，性幻在逡巡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '信士画真请赞 其一' AND p.poem_author = '释印肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('以菊花饷恽薇孙学士诗来用渊明自拟作此答之 其七', '李希圣', '清代', '北伐经年走传车，刘生批答苦纷挐。閒情赋罢无馀事，来倚西风看菊花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '以菊花饷恽薇孙学士诗来用渊明自拟作此答之 其七' AND p.poem_author = '李希圣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小松', '章孝标', '唐代', '爪叶鳞条龙不盘，梳风幕翠一庭寒。 \n 莫言只是人长短，须作浮云向上看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小松' AND p.poem_author = '章孝标';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和张二十五春日见寄五首 其一', '范祖禹', '宋代', '绰约花无语，间关鸟自吟。及时须赏玩，风雨不能禁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和张二十五春日见寄五首 其一' AND p.poem_author = '范祖禹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湖西杂感诗 其十二', '释智圆', '宋代', '白犬宵行似有情，为防暴客到天明。近来守禦无功绩，不吠人形只吠声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湖西杂感诗 其十二' AND p.poem_author = '释智圆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阮郎归·杏花疏雨洒香堤', '佟世南', '清代', '杏花疏雨洒香堤，高楼帘幕垂。远山映水夕阳低，春愁压翠眉。\n芳草句，碧云辞，低徊闲自思。流莺枝上不曾啼，知君肠断时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阮郎归·杏花疏雨洒香堤' AND p.poem_author = '佟世南';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金花叶 赠徐安神', '马钰', '元代', '欲要灵明莹彻。向心上、速宜解结。便莫受、家缘火＊弃妻男产业。逞俊宁如养拙。引龙虎、休教急切。自然悟、神仙妙诀。本来真难灭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金花叶 赠徐安神' AND p.poem_author = '马钰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋宵吟', '蒋敦复', '清代', '夜漫漫，月皎皎。小阁湘帘深悄。银河影、乍转向疏桐，乱雅惊晓。\n\n瘦罗衣，冷翠葆。坠叶纷飞林表。秋声起、感一片清商，暗蛩衰草。\n\n莫是欧阳，恨作赋、年华渐老。低围银烛，懒展瑶编，绣幕篆烟绕。\n\n玉漏三更早。画角沈沈，天际雁杳。者吟怀、写入琴丝，阶下红鹤又睡了。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋宵吟' AND p.poem_author = '蒋敦复';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东观读未见书', '黄庭坚', '宋代', '汉规群玉府，东观近宸居。\n诏许无双士，来观未见书。\n皇文开万卷，家学陋三馀。\n竹帛森延阁，星辰绕直庐。\n诸生起孤贱，天子自吹嘘。\n愿以多闻力，论思补帝裾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东观读未见书' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '朴景绰', '宋代', '胜事年年传习久，盛观全属远方宾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '朴景绰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青原台', '洪刍', '宋代', '高台梯空上云烟，宴坐城郭窥山川。凫汀鹤渚江在前，青原入望山苍然，蓦波轻泛一叶船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青原台' AND p.poem_author = '洪刍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿栎堂前小山峰凌霄花盛开葱茜如画因名之曰凌霄峰 其二', '范成大', '宋代', '山容花意各翔空，题作凌霄第一峰。门外轮蹄尘扑地，呼来借与一枝筇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿栎堂前小山峰凌霄花盛开葱茜如画因名之曰凌霄峰 其二' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄长卿', '邹浩', '宋代', '乌衔霁色朝迎马，蟾吐澄辉夜照眠。日月于君已如此，不须星历问行年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄长卿' AND p.poem_author = '邹浩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('倅教授判官皆为东湖有赋次韵', '程公许', '宋代', '逶迤三径带重肖，心眼经营念厥初。\n问俗只须无事治，僝工适际有年书。\n雪融趁急栽花柳，春到随宜辦果蔬。\n最喜城隅便来往，不嫌左走费台舆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '倅教授判官皆为东湖有赋次韵' AND p.poem_author = '程公许';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居二首 其一', '行端', '元代', '山木交柯莎满庭，马蹄且不污岩扃。篝灯对雪坐吟偈，拥裓绕泉行课经。\n\n睡少每知茶有验，病多常怪药无灵。金园一岁一牢落，谁似孤松长自青。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居二首 其一' AND p.poem_author = '行端';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宴琼林（上元）', '黄裳', '宋代', '霜月和银灯，乍送目楼台，星汉高下。爱东风、已暖绮罗香，竞走去来车马。红莲万斛，开尽处、长安一夜。少年郎、两两桃花面，有馀光相借。因甚灵山在此，是何人、能运神化。对景便作神仙会，恐云轩且驾。思曾待、龙楼俯览，笑声远、洞天飞斝。向东来、尤幸时如故，群芳未开谢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宴琼林（上元）' AND p.poem_author = '黄裳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和元善郎中', '袁士元', '元代', '水馆春将晚，凭阑静自吟。蜂粘飞絮起，鱼噞落花沈。\n\n济世身无术，邻邦贼又侵。临风搔白首，空负读书心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和元善郎中' AND p.poem_author = '袁士元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬刘员外月下见寄', '章八元', '唐代', '夜凉河汉白，卷箔出南轩。过月鸿争远，辞枝叶暗翻。 \n 独谣闻丽曲，缓步接清言。宣室思前席，行看拜主恩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬刘员外月下见寄' AND p.poem_author = '章八元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶作', '吕本中', '宋代', '去年芳草又萋萋，休叹王孙犹未归。更见春深送春雁，三三两两傍云飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶作' AND p.poem_author = '吕本中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('失题十七首 其六', '张弼', '明代', '都门长啸拂尘衣，乡思迢迢宦况微。桃李门墙新进满，桑麻墟里旧交稀。\n\n霞城卧听金鸡唱，雨洞吟看玉蝠飞。只恐平生著书手，未容持钓老渔矶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '失题十七首 其六' AND p.poem_author = '张弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄鹄篇', '薛蕙', '明代', '飞飞者鹄，于彼苍天。大风阻斯，羽沉于渊。有松有柏，其枝嶟嶟。\n\n雨雪迨斯，化为枯薪。烈烈冬日，萧萧北风。虽有神龙，宛彼地中。\n\n天命有假，人谋有仍。嗟哉士人，曰予无能。舟利于川，弗利于陆。\n\n君子于行，维颠之速。相彼哲人，爰得我匹。且以啸歌，且以永日。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄鹄篇' AND p.poem_author = '薛蕙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李参政', '魏了翁', '宋代', '黄云冉冉晓苍苍，閒倚平湖只自香。较似寒枝虽未至，依然风韵挟冰霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李参政' AND p.poem_author = '魏了翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同闰师宿三门开化院二首 其一', '魏野', '宋代', '白莲社主碧溪人，同宿三门寺里云。四面涛声秋更怒，并床犹恐话难闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同闰师宿三门开化院二首 其一' AND p.poem_author = '魏野';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('皖江', '李先芳', '明代', '皖江阴乍晴，鳞鳞秋浪生。\n岸回村树隐，潮落海云平。\n鱼米舟中市，人烟水上城。\n不须遥问渡，前路是浮萍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '皖江' AND p.poem_author = '李先芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又五言', '徐铉', '唐代', '彩仗映花鞯，春庭散曙烟。\n毬飞皆应手，马骏不须鞭。\n仙乐飘云外，祥风近日边。\n筹多不虚发，制生在机先。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又五言' AND p.poem_author = '徐铉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('示医卜逢松崖', '朱继芳', '宋代', '我生八月十五夜，清浅斜河浸月华。顾兔捣残千岁药，牵牛引动半天槎。\n\n自抛蓬海传方处，曾过成都卖卜家。今日相逢圆昨梦，一杯松下醉流霞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '示医卜逢松崖' AND p.poem_author = '朱继芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青草湖', '蒋之奇', '宋代', '地无一勺水，安得有湖名。世事果如此，风波平地生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青草湖' AND p.poem_author = '蒋之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮 前题', '奭良', '清代', '春光明媚红窗晓。春风袅娜催啼鸟。灵鹊借填桥。一双金步摇。\n\n枣花帘子捲。云想衣裳暖。菱镜被人窥。翠螺深浅眉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮 前题' AND p.poem_author = '奭良';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新凉理故书有感二首 其二', '刘克庄', '宋代', '空花瞥过似浮荣，海水难湔是恶名。功比禹轲真学者，罪浮桀纣亦书生。\n\n国师族覆惭家训，太尉朝危悔宦情。束起陈编呼伯雅，胸中磊磈暂浇平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新凉理故书有感二首 其二' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶兴', '弘历', '清代', '埙篪兰茝自人伦，衅梗交尤叹葛巾。蜀道易难若反掌，达夫太白总痴人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶兴' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寒夜与家人坐语忆客中时', '高启', '明代', '茅屋夜灯青，竹庭寒雪白。\n不对室中人，依然去年客。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寒夜与家人坐语忆客中时' AND p.poem_author = '高启';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽国史侍读李公仁父', '喻良能', '宋代', '大名垂宇宙，秀气发岷峨。\n学比渊云赡，才方贾马过。\n九朝资直笔，二子振贤科。\n已矣流芳在，千秋保不磨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽国史侍读李公仁父' AND p.poem_author = '喻良能';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('周颂·有客', '佚名', '先秦', '有客有客，亦白其马。有萋有且，敦琢其旅。有客宿宿，有客信信。\n\n言授之絷，以絷其马。薄言追之，左右绥之。既有淫威，降福孔夷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '周颂·有客' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六一堂', '范令闻', '宋代', '□□□□法，□□□□□。\n□□□□□，□□□雪人。\n□□□□照，□□江汉炳。\n灵□□物□，生五色虎□。\n□山□长□，唁□□□□。\n□简三□秩。满□中□□。\n然囊衣度云，栈□□□与。\n七贤□襁负，中□□金产。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六一堂' AND p.poem_author = '范令闻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再游灵隐寺', '张宁', '明代', '三月春深日日晴，桃花未落柳阴清。素罗衣薄松风淡，斑竹兜轻石路平。\n\n盛世多才惭独往，客游无处写閒情。倦来更欲缘溪步，为借寒流一濯缨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再游灵隐寺' AND p.poem_author = '张宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词 其七十七', '赵佶', '宋代', '戎裘殊丽学弯弓，十指纤柔力未充。多被朋侪齐谑笑，强颜无奈脸莲红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词 其七十七' AND p.poem_author = '赵佶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过许金声瓢所', '周瑛', '明代', '绿树深中白日迟，小瓢收得许多诗。百年天地藏形器，万状风云入笑嗤。\n\n沈宋每思传正印，许姚会见树降旗。双旌偶上临川道，重倚阑干有所思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过许金声瓢所' AND p.poem_author = '周瑛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('听凯三首 其二', '陶益', '明代', '跃马阑街卸铁衣，屠牛倒酒耀兵威。凯歌莫踏城头月，犹有同仇逐梦归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '听凯三首 其二' AND p.poem_author = '陶益';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四时田园杂兴四首 其二', '曹家达', '清代', '散发当微凉，林木暧朝景。流连溪上花，忽见青山影。\n\n何处求黄虞，结念在庐井。邻翁日夕过，为言当习静。\n\n有田付孙子，租税出半顷。卧听水车声，俟此清昼永。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四时田园杂兴四首 其二' AND p.poem_author = '曹家达';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('官池即事', '赵蕃', '宋代', '偃薄虽兹驿，相羊赖此亭。鸟飞微破縠，鱼动暗冲萍。\n\n岂但忧怀惬，还能倦眼醒。独馀春草梦，才尽不能灵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '官池即事' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('百一诗 其二十四', '应璩', '魏晋', '小儿抚尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '百一诗 其二十四' AND p.poem_author = '应璩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙', '浦梦珠', '清代', '记得伤春经病起，日长慵下妆楼。慧因悔向隔生修。\n\n草偏栽独活，花未折忘忧。\n\n一幅生绡窗下展，亲将小影双钩。画成未肯寄牵牛。\n\n只缘描不出，心上一痕秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙' AND p.poem_author = '浦梦珠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同石元规讲鹍鹏偶书', '张继先', '宋代', '翱翱数仞间，何异九万里。\n大道荡无名，无彼亦无此。\n倬哉元规翁，斯言迨尽矣。\n一物自太极，志士摽高拎。\n鹏乎与蜩鸠，涉辩非至理。\n有形相变化，不出六合里。\n飞跃涉程途，底用嘲远迩。\n乃识逍遥游，潀远发玄旨。\n讲罢四窗闲，忘言空隐几。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同石元规讲鹍鹏偶书' AND p.poem_author = '张继先';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鸳鸯湖棹歌 其四十一', '朱彝尊', '清代', '秋灯无焰剪刀停，冷露浓浓桂树青。伯解罗衣种罂粟，月明如水浸中庭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鸳鸯湖棹歌 其四十一' AND p.poem_author = '朱彝尊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋', '李裕', '元代', '待月滦水上，天寒月无魄。重云委城隅，秋色连径白。\n\n北邻有嫠妇，南邻足愁客。昏灯照梦魂，风雨满沙碛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋' AND p.poem_author = '李裕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题朱四郊墅', '宋祁', '宋代', '菌阁平窥倚杵天，绮塍鳞隰逗春泉。\n谁将六国黄金印，拟换东周二顷田。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题朱四郊墅' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋夜思家', '杨自牧', '清代', '故园归计惜蹉跎，残暑初消白露过。清角孤城知夜寂，寒蛩四壁觉秋多。\n\n愁中短梦悲难就，客里流光奈促何。卧起张镫还独坐，空将《九辨》数吟哦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋夜思家' AND p.poem_author = '杨自牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('初夏湖山 其二', '张埴', '宋代', '今朝二供亦相宜，眼底忘忧粲是诗。有恨春风不相待，山林著在日长时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '初夏湖山 其二' AND p.poem_author = '张埴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('木瓜铺短歌', '陆游', '宋代', '鼓楼坡前木瓜铺，岁晚悲辛利州路。当车礧礧石如屋，百里夷途无十步。\n\n溪桥缺断水齧沙，崖腹崩颓风拔树。虎狼妥尾择肉食，狐狸竖毛啼日莫。\n\n冢丘短草声窸窣，往往精灵与人遇。我生胡为忽在此，正坐一饥忘百虑。\n\n五更出门寒裂面，半夜燎衣泥满裤。妻孥八月离夔州，寄书未到今何处。\n\n馀年有几百忧集，日夜朱颜不如故。即今台省盛诸贤，细思宁是儒冠误。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '木瓜铺短歌' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留别芜湖旧友', '黄辂', '清代', '于湖久住忽思家，胜侣分飞雁影斜。惜别一尊将进酒，含情两朵未开花。\n\n残年南陌无芳迹，旧迹东京有《梦华》。不待登程始惆怅，锦屏风外即天涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留别芜湖旧友' AND p.poem_author = '黄辂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五位颂 其一', '释慧晖', '宋代', '正中偏，混沌初分半夜天。转侧木人惊梦破，雪芦满眼不成眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五位颂 其一' AND p.poem_author = '释慧晖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋江八景 其四 落雁汀', '张宁', '明代', '云衢千里路漫漫，水碧沙明夜满滩。何事黄昏尚凝睇，伴人孤影隔江寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋江八景 其四 落雁汀' AND p.poem_author = '张宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过荒村四绝 其二', '张家玉', '明代', '缥缈前途路欲迷，黑云留雨四村低。山灵似笑征人马，何事劳劳不住蹄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过荒村四绝 其二' AND p.poem_author = '张家玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠王司谏文哲奉使北还兼柬吴世美司谏', '张诩', '明代', '李泌当年一献身，岂无高楫济长津。观风夷夏诗多采，补阙朝廷疏屡陈。\n\n阿阁九苞回彩凤，急风千丈挺霜筠。因君却忆吴司谏，曾以龙光射钓纶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠王司谏文哲奉使北还兼柬吴世美司谏' AND p.poem_author = '张诩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('松隐坐上寄钱大参', '曹勋', '宋代', '闲里光阴不记名，曲勤宏度访公荣。\n五云洒翰情文厚，九节浮香琖色轻。\n宝箑含风清致爽，彩丝萦臂眼增明。\n团栾每得佳时醉，却恐宣麻下帝城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '松隐坐上寄钱大参' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('有美一人行', '释文珦', '宋代', '有美一人闲且都，天然自与常人殊。\n奔逸绝尘遗步趋，宛在大海之东隅。\n珠宫贝阙非凡居，鲛绡被体云霞裾。\n朝乘一鹤暮双凫，往来圆峤仍方壶。\n所交皆古真仙徒，赤松羡门及麻姑。\n共论妙道得道枢，天地万物指马如。\n人间岁月良易徂，别来眼暗齿发疎。\n山可泐兮海可枯，相思之念无时无。\n示好亦有明月珠，藏之怀袖不敢沽。\n屡欲致之乏飞鱼，侧身东望空踌躇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '有美一人行' AND p.poem_author = '释文珦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('曹提举荣上', '释居简', '宋代', '乡也才聆謦咳声，暗中摸索认轮囷。故家大雅元戎老，词学清流使节新。\n\n直指大门标俗子，莫嫌高贾著山人。紫荷琳馆君诸父，说项斯贤不厌频。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '曹提举荣上' AND p.poem_author = '释居简';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏清闲自在', '王瑞甫', '近代', '七夕优游避世哗，琴棋书画酒诗花。有时知己闲来往，听唱好歌效谢茶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏清闲自在' AND p.poem_author = '王瑞甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿启宇兄花甲之庆', '陈仁德', '当代', '堂堂自是出群雄，独立苍茫唱大风。不尽波澜生笔底，无穷宇宙在胸中。\n\n壮图未已头颅白，噩梦曾经劫火红。蜀水巴山君共我，照人肝胆总相同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿启宇兄花甲之庆' AND p.poem_author = '陈仁德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出嘉峪关感赋', '林则徐', '清代', '严关百尺界天西，\n万里征人驻马蹄。\n飞阁遥连秦树直，\n缭垣斜压陇云低。\n天山巉[1]削摩肩立，\n瀚海苍茫入望迷。\n谁道崤函千古险？\n回看只见一丸泥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出嘉峪关感赋' AND p.poem_author = '林则徐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪', '弘历', '清代', '同云未肯放冬晴，冻雨均沾继瑞霙。著地消融无定态，随风飘舞可怜生。\n\n鸳楼有玉皆垂佩，鸡树非春率斗荣。卜麦慰馀饶韵事，竹垆文火煮三清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉和李相公早朝于中书候传点偶书所怀奉呈门下…郑相公', '吕温', '唐代', '禁门留骑吹，内省正衣冠。稍辨旂常色，尚闻钟漏残。 \n 九天炉气暖，六月玉声寒。宿雾开霞观，晨光泛露盘。 \n 致君期反朴，求友得如兰。政自同归理，言成共不刊。 \n 准绳临百度，领袖映千官。卧鼓流沙静，飞航涨海安。 \n 尽规酬主意，偕赋代交欢。雅韵人间满，多惭窃和难。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉和李相公早朝于中书候传点偶书所怀奉呈门下…郑相公' AND p.poem_author = '吕温';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南康元夕二首 其二', '李梦阳', '明代', '嘈嘈市鼓动，松月静吾门。灯火思今夜，风光满故园。\n\n天明淹舞袖，尘暗失游轩。老鬓江山异，愁看旌旆繁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南康元夕二首 其二' AND p.poem_author = '李梦阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百四十一首 其七十三', '释师范', '宋代', '克期取證，系缚盲驴。休夏自陈，且莫鬼语。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百四十一首 其七十三' AND p.poem_author = '释师范';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清明日余与诸友游招隐山寺酌酒宋氏园亭谒苏才翁墓而归', '周孚', '宋代', '小雨冥冥欲作泥，晨光不负老人期。绿阴苍藓初分坐，白石清泉共赋诗。\n\n酌醴焚鱼谩今日，卖刀买犊定何时。伤心紫阁飞杨老，千载茫茫只断碑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清明日余与诸友游招隐山寺酌酒宋氏园亭谒苏才翁墓而归' AND p.poem_author = '周孚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题海盐南馆', '张祜', '唐代', '故人营此地，台馆尚依依。黑夜山魈语，黄昏海燕归。 \n 旧阴杨叶在，残雨槿花稀。无复南亭赏，高檐红烛辉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题海盐南馆' AND p.poem_author = '张祜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('解嘲十绝呈浩西堂', '释绍嵩', '宋代', '江湖放浪未宁居，处世真同逐队鱼。\n但愿一生长若此，时清不问命何如。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '解嘲十绝呈浩西堂' AND p.poem_author = '释绍嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次甬川东阁书怀 其二', '霍韬', '明代', '云窦漏光锦碎铺，厂楼长夏寱鸿都。侧身左顾浅鹏窟，醒梦前柯笑蚁图。\n\n静水蒹葭闲豢鹤，趁时粱稻惯搂凫。秃翁握网支矶立，嫚问鱼多孰与湖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次甬川东阁书怀 其二' AND p.poem_author = '霍韬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('𨻧隍舟行纪事二十韵', '林熙春', '明代', '愧予之才匪济川，徒怀击楫发垂肩。一岁两移何忝窃，盟心欲报丹扆前。\n\n四月望日携琴剑，凤城三朝始发船。沿江狎客勤杯酒，迟迟始达𨻧隍滨。\n\n𨻧隍为别二方伯，孝廉亦多列肆筵。筵上飞蛾为兆雨，雨剧天与水相连。\n\n须臾摧裂山陵变，农人何处问桑田。牛羊比屋浮江下，沉灶产蛙突少烟。\n\n此时觅夫夫避水，邮吏犹且减夫钱。强觅数夫先眷属，眷属乘风似有缘。\n\n岂期敝舟犹留滞，相违两日不相联。稚儿稚女啼饥切，相对呼爷眼望穿。\n\n只得贾勇追前去，无奈登矶若登天。缘木攀藤声震地，游水牵绳苦万千。\n\n中流得寸犹失尺，一篙无计可周旋。舟中惊怖念菩萨，榜人失色詈长年。\n\n一朝雨歇风涛息，眷属聚首北溪边。北溪庄人具鸡黍，相与持醪并击鲜。\n\n自是呼童为刻烛，率尔长歌独扣舷。但愿修途长迪吉，五云指日丹心然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '𨻧隍舟行纪事二十韵' AND p.poem_author = '林熙春';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自勉', '陆游', '宋代', '归老宁常逸，时时学荷鉏。\n室蜼无长物，圃尚有余蔬。\n壮志诚衰矣，贫居亦晏如。\n为农当世业，安用筑门闾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自勉' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游海珠寺 其一', '伦以诜', '明代', '神人驱石立，涌出水晶宫。弱水无人到，蓬山有路通。\n\n潮声喧极浦，海色净遥空。解障颓澜势，江流一柱中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游海珠寺 其一' AND p.poem_author = '伦以诜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('灾怪', '晁说之', '宋代', '几岁庙堂生物怪，一朝胡虏应天灾。颇闻北斗光芒见，未见东京消息来。\n\n志士此时忧国泪，将军他日望乡台。世间如有严夫子，时命应须更可哀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '灾怪' AND p.poem_author = '晁说之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('独吟二首 其二', '胡俨', '明代', '樗栎材虚拱，桑榆景已残。天涯春色远，窗下雨声寒。\n\n独自空玄守，何人问字难。蔷薇花又发，却笑酒杯干。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '独吟二首 其二' AND p.poem_author = '胡俨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('昼夜乐', '袁克文', '清代', '弄花人在云飞处。扑香尘、英英舞。丹涡细透新霞，素睐轻横宿露。\n\n薄薄娇羞留不住。算分明、握云揉雨。红影落鲛绡，记鸳鸯帘幕。\n\n五更月褪纤纤树。断肠时、重凝伫。云天不见眉痕，绿蜡尽摇愁缕。\n\n无那微春随梦去，怨西风、未团欢聚。何计问星娥，占银河旧渡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '昼夜乐' AND p.poem_author = '袁克文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉和鲁望晓起回文', '皮日休', '唐代', '孤烟晓起初原曲，碎树微分半浪中。湖后钓筒移夜雨， \n 竹傍眠几侧晨风。图梅带润轻沾墨，画藓经蒸半失红。 \n 无事有杯持永日，共君惟好隐墙东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉和鲁望晓起回文' AND p.poem_author = '皮日休';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春光好 其六', '欧阳炯', '唐代', '芳丛绣，绿筵张，两心狂。空遣横波传意绪，对笙簧。\n\n虽似安仁掷果，未闻韩寿分香。流水桃花情不已，待刘郎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春光好 其六' AND p.poem_author = '欧阳炯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别林和卿 其一', '曾丰', '宋代', '夜榻无高枕，秋灯有短檠。嗜书如女色，敲赋若金声。\n\n岂是长贪者，何其太瘦生。功名犹欠子，子不欠功名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别林和卿 其一' AND p.poem_author = '曾丰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('百字令 和厚庄前辈灵峰摩岩石拓原韵', '夏承焘', '近代', '巨灵孤擘。问何年推出，撑空岩壁。劫火烧残山骨冷，丹篆犹摩拳石。\n\n云护精灵，天开图画，奇句江山辟。银笺重拓，墨花还绣苔碧。\n\n我羡老去刘晨，朅来丘壑，爱着寻幽屐。断碣残碑闲送日，何似岣嵝邹峄。\n\n胜地神游，故山春到，梦境迷仙迹。何时鸾背，和公云外吹笛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '百字令 和厚庄前辈灵峰摩岩石拓原韵' AND p.poem_author = '夏承焘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('妾薄命六首 其一', '林景熙', '宋代', '盈盈梁家姝，奕奕晋朝使。斛珠不论赀，得备巾栉侍。\n\n一笑金谷春，列屋俱敛避。岂知锦步温，巳复为愁地。\n\n念主惠妾深，缘妾为主累。楼头风雨深，残花抱春坠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '妾薄命六首 其一' AND p.poem_author = '林景熙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('经冶城忆亡友盛仲交', '欧大任', '明代', '苍润轩犹故，斯人不可招。如何西序客，老作大城樵。\n\n书带秋零落，床琴夜寂寥。一编封禅草，谁奏圣明朝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '经冶城忆亡友盛仲交' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秀州夜泊', '胡奎', '明代', '回舻泊晚渚，暂息嘉树阴。清飙散狂澜，纤月生远岑。\n\n悠悠归岫云，交交度水禽。同舟遂幽赏，玄谈惬素心。\n\n况兹水凉夕，觞至时一斟。道合理无忤，怡然澹冲襟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秀州夜泊' AND p.poem_author = '胡奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶', '葛天民', '宋代', '黛拂双粉衬毫，翅烘晴日伴相遭。\n戏勾穉子从花远，恐惹游丝莫斩高。\n栩栩倏来仍易散，深深交舞为谁劳。\n吴王花草腾王笔，千载风流敌楚骚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶' AND p.poem_author = '葛天民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('龙门', '袁桷', '元代', '瀚海双龙铁鳞甲，卷壑挐云蹲冀阙。千泉百道凑东南，急雨翻空迸晴雪。\n\n古言神禹功最多，导山凿石疏九河。幽都之地不复顾，乃使双龙下地成盘涡。\n\n阴风何飕飕，磅礴太古秋。崩崖落车炮，怪木森戈矛。\n\n碎沙晴日铺金麸，云是昔日当关挽劲之仆姑。寒泉组练结九曲，亭午赫日光模糊。\n\n车声何辚辚，昨宵急水迷无津。垂堂之言犹在耳，游子商人行不已。\n\n子规彻天呼我归，翠华北幸那得辞。龙门之石高不磨，泚笔书我龙门歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '龙门' AND p.poem_author = '袁桷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洗心亭', '罗伦', '明代', '一片灵台百染污，天将明月与君孤。源头活水依然在，洗得汤铭一字无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洗心亭' AND p.poem_author = '罗伦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('用前人韵招山行以春为期', '文天祥', '宋代', '扫残竹径随人坐，凿破苔矶到处棋。\n一水楼台开晓镜，万山花木领先春闱。\n雪中便有回舟兴，林下岂无烧笋时。\n莫待东风吹柳絮，眼穿笼鹤绕湖飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '用前人韵招山行以春为期' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵别王止仲 其二', '徐贲', '元代', '风风雨雨暗消春，杨柳官桥夜掩津。不是子规啼欲倦，扁舟知有未归人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵别王止仲 其二' AND p.poem_author = '徐贲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六十 其二', '聂绀弩', '近代', '缘何除夕作生日，定为迎春来世间。渴饮中苏千里雪，饱看南北两朝山。\n\n西风瘦马追前梦，明月梅花忆故寒。此六十年无限事，最难诗要自家删。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六十 其二' AND p.poem_author = '聂绀弩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵仇仁近暑中二首 其一', '方回', '宋代', '初减官河几许深，向来惟恐百城沈。晴阶近喜收檐滴，暑屋殊嫌乏树阴。\n\n妾妇齿牙工斗阋，比邻疟疠厌呻吟。悬知壮士无颜色，赖有同心可断金。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵仇仁近暑中二首 其一' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别张子言（四首）', '王廷陈', '明代', '我友驾言迈，去去之朔方。\n晨起趋中厨，为我具酒浆。\n长别在须臾，且愿尽杯觞。\n昔为骨肉亲，比翼云中翔。\n今当承乖违，邈若参与商。\n出门异乡县，居世如朝霜。\n世途转倾侧，良会安可常。\n羸马感人情，哀鸣衢路傍。\n悲风振乔林，瑟瑟伤肝肠。\n执手不能辞，泪下沾衣裳。\n恨无凌风翰，送子还故乡。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别张子言（四首）' AND p.poem_author = '王廷陈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出山逢耿湋', '卢纶', '唐代', '云雪离披山万里，别来曾住最高峰。 \n 暂到人间归不得，长安陌上又相逢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出山逢耿湋' AND p.poem_author = '卢纶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('有赠四首 其四', '王彦泓', '明代', '秋风长簟恨三年，续命曾闻唤小怜。已向绿珠称弟子，倘容张硕伴神仙。\n\n筵前笑顾樱桃掷，烛下偷分茉莉穿。端似悼亡唐后主，见伊枝叶又情牵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '有赠四首 其四' AND p.poem_author = '王彦泓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('己亥杂诗 其二六三', '龚自珍', '清代', '道韫谈锋不落诠，耳根何福受清圆？自知语乏烟霞气，枉负才名三十年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '己亥杂诗 其二六三' AND p.poem_author = '龚自珍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('避暑山庄三十六景诗 其十九 暖溜暄波', '弘历', '清代', '遥源苍峤中，暖溜早称功。涤荡蒸云似，灵奇仙药同。\n\n醴泉闻建武，温谷艳新丰。利物天然泽，无誇辟沼宫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '避暑山庄三十六景诗 其十九 暖溜暄波' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('永王东巡歌十一首 其八', '李白', '唐代', '长风挂席势难回，海动山倾古月摧。君看帝子浮江日，何似龙骧出峡来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '永王东巡歌十一首 其八' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和乐周弟寄韵 其七', '郭棐', '明代', '百粤山川第几层，重来有约漫追寻。满台花雨飘僧梵，两岸岚光拥翠岑。\n\n贝叶捲时猿献玉，老僧禅罢客弹琴。登临欲上和光洞，踏破苍苔发浩吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和乐周弟寄韵 其七' AND p.poem_author = '郭棐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('烟波即事', '陆游', '宋代', '落雁沙边艇子斜，分明清梦上三巴。\n眼明一点炊烟起，不是渔家即酒家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '烟波即事' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('度凤凰岭次董叔重韵', '程洵', '宋代', '连山翳寒云，孤松秀巍岭。松吟石漱水，山露髻撑顶。\n\n我行亦何事，岁晏苦凄冷。频有同心人，哦诗味隽永。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '度凤凰岭次董叔重韵' AND p.poem_author = '程洵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宝鼎现（上元上江西刘枢密）', '石孝友', '宋代', '雪梅清瘦，月桂圆冷，天街新霁。想帝辇、三朝薄暮，催促烛龙开扇雉。正拜舞、捧玉卮为寿，花满香铺凤髓。罄禹穴、胥涛万顷，春入南山声里。 \n 鼎轴元老诗书帅。体宸衷、双奉亲意。勤色养、行春惜花，夜欢宴、瑶池衣彩戏。鼓淑气、遍湖山千里。惊破慳红涩翠。笑那个痴儿无赖。 \n 打得金鱼坠地。休念太守当年，曾手把青藜照字。对珠帘云栋，收拾太平歌舞辍。庆母爱、小宽王事。余沥□肠，看不日、归步沙堤，又赞重华孝治。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宝鼎现（上元上江西刘枢密）' AND p.poem_author = '石孝友';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苦热', '穆孔晖', '明代', '赤日长天昼掩扉，冰纨碧簟起炎威。病馀未爱强加饭，客至还愁暂着衣。\n\n案上青蝇难寂寞，阶前瑶草失芳菲。拟从禦寇乘风去，却向山阴理棹归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苦热' AND p.poem_author = '穆孔晖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂兴 其二', '利登', '宋代', '我昔游蓬莱，道过昆崙山。青壁峭千仞，中分两径前。\n\n上径险且难，行可求神仙。下径极夷易，蛇虺交蜿蜒。\n\n毫釐一殊轨，安危异千年。弃之从上征，高步追飞鸾。\n\n勿谓下途易，下途前更艰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂兴 其二' AND p.poem_author = '利登';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南山罗汉赞十六首', '黄庭坚', '宋代', '四十九年大教主，波旬请故入涅盘。\n佛身常寻法界住，非其境界故不见。\n未法众生蒶福田，众魔染衣汗戒律。\n稽首那迦住世间，令我常生遇佛想。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南山罗汉赞十六首' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('除夕', '陈曾寿', '清代', '沉阴飞大雪，万里接龙庭。惨黩兼幽显，情怀兀醉醒。\n\n星光隐辰极，花影淡湘灵。欲说心中事，悲凉不可听。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '除夕' AND p.poem_author = '陈曾寿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题邹一桂写生卷九首 其八 秋葵', '弘历', '清代', '秋风閒砌发幽花，处士图珍驸马家。直笔不惭瓶史处，倾阳曾未逞春华。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题邹一桂写生卷九首 其八 秋葵' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('客怀六首 其四', '边贡', '明代', '鬓丝端为别兄皤，魂梦真如道路何。滇海万峰秋雁少，楚江千里月明多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '客怀六首 其四' AND p.poem_author = '边贡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和昌言官舍十题 其八 甘菊', '司马光', '宋代', '野菊细琐物，篱间私自全。徒因气味殊，不为庖人捐。\n\n采升白玉堂，荐以黄金盘。愿若南阳守，永扶君子年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和昌言官舍十题 其八 甘菊' AND p.poem_author = '司马光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨', '弘历', '清代', '宵旦阴云酝酿佳，沛然灵澍落辰牌。不徐不疾溜垂细，过午过申潦积皆。\n\n继泽还欣胜前此，流膏所喜达根荄。稻塍黍陇芃生意，慰矣惟饶敬畏怀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('端午词·御阁', '晏殊', '宋代', '献寿竞为长命缕，迎祥还佩赤灵符。\n端门漏永晨曦上，飒飒薰风绕帝梧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '端午词·御阁' AND p.poem_author = '晏殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽钱祖耄姑丈二首 其二', '孙保圻', '近代', '少日从姑分最亲，履綦泯绝隔音尘。神方未验陶宏景，占貌空怀杜子春。\n\n悲恋龙髯心上事，崚嶒犀角眼中人。年来旧德多凋丧，愧剩飘零不肖身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽钱祖耄姑丈二首 其二' AND p.poem_author = '孙保圻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王太博 其二', '林希逸', '宋代', '以赋鸣虽早，襟怀实似虚。出弹齐士铗，归读乐轩书。\n\n丹桂攀殊苦，黄粱梦不如。在时同手足，入念每沾衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王太博 其二' AND p.poem_author = '林希逸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟古', '钟芳', '明代', '志士委荣宠，抗节清霄岑。繁英掇零露，栖息谐素心。\n\n夷随有前期，遐风谅斯寻。何为风中絮，飘飘堕春阴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟古' AND p.poem_author = '钟芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻东轩讣 其二', '刘克庄', '宋代', '位逼将求说，书来欲铸颜。柰何化鹤去，不见珥貂还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻东轩讣 其二' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟权龙褒体赠鄠县李令及寄朝右（李令因之休官）', '郑愚', '唐代', '鄠县李长官，横琴膝上弄。不闻有政声，但见手子动。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟权龙褒体赠鄠县李令及寄朝右（李令因之休官）' AND p.poem_author = '郑愚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春 其二 再和韵', '方岳', '宋代', '客有谓予，野眺何如，予曰可哉。乃携酒怀鱼，共寻秋径，乘风化鹤，感慨荒台。\n\n能几重阳，已无老子，人世何妨笑口开。苍崖下，有二犁膏雨，十亩汗莱。\n\n掉头只么低回。彼轩冕时来自傥来。夜半饭牛，无心扣角，霜前擘蟹，有手持杯。\n\n野屋云深，帝城书断，坚卧三年一砚埃。赢得底是，唐诗晋帖，潜菊逋梅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春 其二 再和韵' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('记杂画 尝醋图', '刘克庄', '宋代', '酿者不沾唇，旁观吸者颦。翁真堪宰相，妪亦可夫人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '记杂画 尝醋图' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题墨桃', '程本立', '明代', '天台美人红雪肌，玉洞春深曾见之。今日风沙吹面黑，出山不似在山时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题墨桃' AND p.poem_author = '程本立';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鱼樵图', '孙绪', '明代', '抱膝余长吟，息肩君赏音。歌罢解携去，山高江水深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鱼樵图' AND p.poem_author = '孙绪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陶斋招为柬坡生日节庵新至信宿即归陶斋有诗索和', '陈宝琛', '清代', '谪仙非谪乃其游，坡公故是仙者流。谷神出世八百秋，禁网所脱声画留。\n\n陶斋好古苏斋侔，梁髯新来趣命俦。图书色香逾荐羞，陈以飨客餍客求。\n\n嗟公于世生何雠？死作奎宿谗始休。已灰之木不系舟，孰者龟鹤孰蜉蝣？\n\n往来人海髯如鸥，此会欻若风中沤。主人诗好难为酬，雪大能上西山不？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陶斋招为柬坡生日节庵新至信宿即归陶斋有诗索和' AND p.poem_author = '陈宝琛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈五首', '释弥光', '宋代', '一九与二九，相逢不出手。\n冻得鸱吻头，面南看北斗。\n诸禅人，晓不晓，\n地炉火冷莫嫌寒，更有樵夫赤脚走。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈五首' AND p.poem_author = '释弥光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '李寿朋', '宋代', '十日醉如何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '李寿朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自仙人岩至梓树坑', '姚燮', '清代', '玉女搴水帘，睨我过云峤。瘦石随吟肩，撑空竞苍峭。\n\n瑶林鹤振虚，兰门日衔照。山气清霏花，潭光静生缟。\n\n松梦猿独知，藓迹马谁到？旷象高溢秋，寂籁下缄妙。\n\n洞焉豁古天，森然伟灵造。自此千奇投，愿持一筇报。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自仙人岩至梓树坑' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登郁孤台 其二', '韦骧', '宋代', '去年秋宿洞庭湖，今日登临在郁孤。两处风流皆胜绝，一身奔走亦崎岖。\n\n光摇二水看云断，翠滴千山爱日晡。吏役不容清兴足，放船回首望城隅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登郁孤台 其二' AND p.poem_author = '韦骧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岁丁丑曾步韵寿一如王君七十，意有未尽，复成五古一首', '赵廷赓', '清代', '我续古稀吟，不尚谀词贡。先生松鹤姿，秉质尤厚重。\n\n肇锡鸿逵爻，爰居为粪巷。老宿仰经师，文史殊足用。\n\n桃李盈门墙，济济英才众。衣钵盛流传，群钦铸颜孔。\n\n清况谱茶经，旗枪分雅供。优游乐天真，知己日过从。\n\n忆昔小蓬莱，叨陪鲤对共。五十馀载间，仆未解尘鞚。\n\n羡君乐齐眉，更有谢家凤。兰玉森庭前，含饴孙载弄。\n\n天伦乐事多，颐养福天种。即此卜遐龄，聊代椒花颂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岁丁丑曾步韵寿一如王君七十，意有未尽，复成五古一首' AND p.poem_author = '赵廷赓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('头陀僧', '陆龟蒙', '唐代', '万峰围绕一峰深，向此长修苦行心。 \n 自扫雪中归鹿迹，天明恐被猎人寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '头陀僧' AND p.poem_author = '陆龟蒙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王守生辰七月十四日', '廖刚', '宋代', '月华浑似十分圆，玉露金风处暑天。虎节端光凌碧汉，龙台佳气满晴川。\n\n扬鞭省闼声名籍，拥旆侯籓福禄骈。会看黑头丹衮贵，伊周勋业老彭年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王守生辰七月十四日' AND p.poem_author = '廖刚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('示龟山平老 其二', '韩驹', '宋代', '水横绝浦曾争渡，浪打船头又少留。安得一舟淮上钓，水生水落任沉浮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '示龟山平老 其二' AND p.poem_author = '韩驹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('以螃蟹寄高紫微践约侑以雪醅时犹在黄冈', '岳珂', '宋代', '前朝无蟹惟有诗，亦复无酒供一郗。\n今朝有蟹仍有酒，极目征帆更搔首。\n古为乐事夸持螯，赤琼酿髓玄玉膏。\n菊花吹英好时节，况是九日钭登高。\n旌旗半江笳鼓发，不作诗人淡生活。\n待君净洗沙漠尘，归趁看灯更奇绝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '以螃蟹寄高紫微践约侑以雪醅时犹在黄冈' AND p.poem_author = '岳珂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠一上人', '吕本中', '宋代', '细褥纱幮卧软绫，岂知秋色到襄陵。饥乌乍定门门树，宝塔新晴夜夜灯。\n\n晚菜聊充肉一脔，残林才当饭三升。平生积懒成骄惰，惭愧空房独坐僧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠一上人' AND p.poem_author = '吕本中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('极相思·题陈藏一水月梅扇', '吴文英', '宋代', '玉纤风透秋痕。凉与素怀分。乘鸾归后，生绡净翦，一片冰云。 \n心事孤山春梦在，到思量、犹断诗魂。水清月冷，香消影瘦，人立黄昏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '极相思·题陈藏一水月梅扇' AND p.poem_author = '吴文英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆帝京', '顾随', '近代', '木绵袍子君休换。毕竟眷深春浅。听说杏花开，却在深深院。\n\n可惜太深深，开了无人见。\n\n一阵阵、风儿回旋。几点点、雨儿萧散。长怪当年，道君皇帝，见了红杏肝肠断。\n\n不怨杏花红，却怨双双燕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆帝京' AND p.poem_author = '顾随';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙 其五 过分水河，和王仔园韵', '董元恺', '清代', '终古灵奇恢禹绩，中流河渎平分。云沙浩浩水粼粼。\n\n黄牛如断岸，白马暗通痕。\n\n南北维舟争报赛，九州万派知遵。安澜直自到天津。\n\n河清应献颂，海若尽称臣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙 其五 过分水河，和王仔园韵' AND p.poem_author = '董元恺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送赵司空致政', '严嵩', '明代', '嶷然冠剑汉司空，出入三朝操履同。事忤贵人知节槩，心忧王室见清忠。\n\n俞章赐允皇仁大，荐剡留贤物论公。遥羡高踪去尘网，云霄万里一冥鸿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送赵司空致政' AND p.poem_author = '严嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄许伯玉', '陈恭尹', '明代', '文章先代是宗工，君有无双国士风。百战功多沧海外，一官身老岭云东。\n\n越庭诗礼皆能学，爱客壶觞不说穷。凤峤松阴石湖月，至今人想许中戎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄许伯玉' AND p.poem_author = '陈恭尹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郊外', '文同', '宋代', '城市压压土，高原聊振衣。\n晚云多浅碧，秋树半深绯。\n江气杂轻霭，山光明落晖。\n因成求好景，更就野桥归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郊外' AND p.poem_author = '文同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感遇诗三十八首 其四', '陈子昂', '唐代', '乐羊为魏将，食子殉军功。骨肉且相薄，他人安得忠。\n\n吾闻中山相，乃属放麑翁。孤兽犹不忍，况以奉君终。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感遇诗三十八首 其四' AND p.poem_author = '陈子昂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词 其二十五', '花蕊夫人徐氏', '唐代', '新秋女伴各相逢，罨画船飞别浦中。旋折荷花伴歌舞，夕阳斜照满衣红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词 其二十五' AND p.poem_author = '花蕊夫人徐氏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂咏十首 其六', '方凤', '宋代', '瑞世凤鸣阳，司晨鸡鸣丑。呶呶取人憎，乱蝉合缄口。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂咏十首 其六' AND p.poem_author = '方凤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('醉公子', '秦昙', '清代', '香囊垂绣凤。是妾儿时弄。微物何足珍。怜他伴妾身。\n\n红绵著在里。扣上同心缕。一缕一相思。数来千万丝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '醉公子' AND p.poem_author = '秦昙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('焦山寺', '陈琏', '明代', '江上焦山寺，匆匆未暇登。水环青一簇，树拥翠千层。\n\n两岸闻斋磬，中流见佛灯。昔人有遗迹，瘗鹤尚留铭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '焦山寺' AND p.poem_author = '陈琏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读史 其三', '吴当', '元代', '受命趋关定约时，鄛翁多算竟何为。可怜空碎鸿门玉，天下雄雌亦易知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读史 其三' AND p.poem_author = '吴当';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟古四十一首 其十四', '薛瑄', '明代', '木腐虫蠹出，气乖疣赘生。曜灵一薄蚀，阴曀郁然兴。\n\n道术裂周季，纵横乱秦嬴。青牛既夙驾，白马亦时征。\n\n汜滥自涓滴，熺赫兆星星。多谢宋诸老，万古开昏冥。\n\n如何阳光发，尚自爝火明。寄语行路人，勿迷棘与荆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟古四十一首 其十四' AND p.poem_author = '薛瑄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山中怀友 其五', '萨都剌', '元代', '卓荦恒山秀，相逢几抱琴。五年风雨别，四海弟兄心。\n\n岭外梅花远，山中桂叶深。定知嵇叔夜，高兴满云林。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山中怀友 其五' AND p.poem_author = '萨都剌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东皋十首', '晁补之', '宋代', '城市何妨亦隐沦，贾君无意向红尘。\n东皋瓜豆如云处，慊我幽栖不卜邻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东皋十首' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居五戒一戒讲学', '唐伯元', '明代', '我曰予贤，人曰予圣。果圣且贤，相悦而静。况汝之德，未满乡里。\n\n况汝之道，未行妻子。呶呶哓哓，盖不知耻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居五戒一戒讲学' AND p.poem_author = '唐伯元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄燕中友人六首 其一 岭南黎惟敬', '胡应麟', '明代', '谁向风尘问谪仙，相逢贺监自飘然。青春画省追游地，白首金门侍从年。\n\n柳色乍分燕塞底，梅花长忆岭云前。佳期惨淡琼瑶隔，愁对孤城落日悬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄燕中友人六首 其一 岭南黎惟敬' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南康邂逅江西吴运判 其二', '刘过', '宋代', '万里西征一叶舟，谁怜天地此生浮。初征秋浦雁飞处，又泊江南霜叶洲。\n\n贫困尽从归后见，雄豪半为病来休。十年心事閒搔首，荻雨芦风总是愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南康邂逅江西吴运判 其二' AND p.poem_author = '刘过';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '刘兴祖', '宋代', '谁能制长笛，当为玉龙吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '刘兴祖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠周山人 其一', '陈深', '宋代', '床头曾不置黄金，野褐纶巾善陆沉。七十康强疑有道，一毫荣辱不惊心。\n\n草根露冷沾芒屦，柏子烟清暖布衾。时启青囊看山水，行歌行入白云深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠周山人 其一' AND p.poem_author = '陈深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送王运同 其一', '郑真', '明代', '万里东流鲸海波，朝家盐赋有常科。草窝气湿苍烟暗，花𨢑光寒白雪多。\n\n已见神功回造化，还闻宽政蔼声歌。煌煌使阃看归骑，缥缈天风响佩珂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送王运同 其一' AND p.poem_author = '郑真';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('接家书', '赵佩湘', '清代', '家书未到频先盼，乍接家书怯细看。莫道纸长嫌话短，客乡幸喜报平安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '接家书' AND p.poem_author = '赵佩湘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('原隰荑绿柳', '温庭筠', '唐代', '迥野韶光早，晴川柳满堤。\n拂尘生嫩绿，披雪见柔荑。\n碧玉牙犹短，黄金缕未齐。\n腰肢弄寒吹，眉意入春闺。\n预恐狂夫折，迎牵逸客迷。\n新莺将出谷，应借一枝栖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '原隰荑绿柳' AND p.poem_author = '温庭筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏舞诗', '何敬容', '南北朝', '因风且一顾，扬袂隐双蛾。曲终情未已，含睇目增波。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏舞诗' AND p.poem_author = '何敬容';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹', '陈元晋', '宋代', '吾敬王子猷，傲俗独爱竹。行止必与俱，情义均骨肉。\n\n云龙求友心，上下亦相逐。彼哉绝彝伦，乃戒桑下宿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹' AND p.poem_author = '陈元晋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('简熊松云', '瞿智', '元代', '西冈无奈景纯何，陶写新诗日渐多。宜似兰苕飞翡翠，每嗟荆棘长铜驼。\n\n日曛山崦收黄雾，秋入江风动白波。复忆松云老文学，醉乘箫凤肯相过。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '简熊松云' AND p.poem_author = '瞿智';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄曹子方', '韦骧', '宋代', '度溪踰岭一何劳，霜鬓鬅鬙首屡搔。自愧晚年空碌碌，唯逢佳境且陶陶。\n\n会仙古观风流远，馆节新堂气象豪。不得与君同啸傲，强抽荒思引吟毫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄曹子方' AND p.poem_author = '韦骧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青县赠潘茂硕', '袁宏道', '明代', '竹叶遮人吏，公移只坐销。\n印床生木耳，廨含长蔬苗。\n贫邑多诗料，闲官有醉僚。\n一城不数武，容得几科条。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青县赠潘茂硕' AND p.poem_author = '袁宏道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵和李根香', '吴妍因', '清代', '江城玉笛董生笳，古调高吟属李家。睹物不胜怀故国，悲凉又咏刺桐花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵和李根香' AND p.poem_author = '吴妍因';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寒食访僧', '郑文宝', '宋代', '客舍愁经百五春，雨余溪寺绿无尘。\n金花开处鞦韆鼓，粉颊谁家斗草人。\n水上碧桃流片段，梁间新燕语逡巡。\n高僧不饮客携酒，来劝先朝放逐臣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寒食访僧' AND p.poem_author = '郑文宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('画 其二', '凌云翰', '元代', '扁舟与客共游遨，风月无边入彩毫。长为江山增感慨，后前两赋类庄骚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '画 其二' AND p.poem_author = '凌云翰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('介翁见示诞孙志喜之作次韵三首 其一', '王立道', '明代', '抱孙六十应非晚，裁得新诗续旧欢。宠埒金张开世胄，词高屈宋比衙官。\n\n宾筵胜拟金钱会，宫禁荣分襁褓完。台阁已传韦氏业，芝兰频向谢庭看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '介翁见示诞孙志喜之作次韵三首 其一' AND p.poem_author = '王立道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三月抵京二首 其二', '卢龙云', '明代', '尚及三春候，重来万里人。辞家方在远，观国屡为宾。\n\n宦业难书竹，时情任积薪。长安真似奕，往事不须颦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三月抵京二首 其二' AND p.poem_author = '卢龙云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟古七十首 其八 刘文学桢陪宴', '王世贞', '明代', '公子富令德，穷乐在清时。卜昼启初筵，丙夜犹未疲。\n\n丛篁夹文馆，碧萼缀丹梯。潜月青林端，万颖射金池。\n\n澄露滴华桐，薰风穆然吹。炮炙参差进，觞醴纵横飞。\n\n伎士慕新端，肉奋丝竹驰。渊鳞中踊跃，宿鸟无宁枝。\n\n冉冉东方曙，欢唱掩鸣鸡。冠盖散交衢，粉泽有馀施。\n\n畸客誇殊遇，叹息不可追。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟古七十首 其八 刘文学桢陪宴' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('踏莎行', '侯彭老', '宋代', '十二封章，三千里路。当年走遍东西府。时人莫讶出都忙，官家送我归乡去。 \n 三诏出山，一言悟主。古人料得皆虚语。太平朝野总多欢，江湖幸有宽闲处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '踏莎行' AND p.poem_author = '侯彭老';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('恽道生画山水歌', '朱景英', '清代', '毗陵恽氏工作画，正叔本在道生后。正叔写生妙入神，何似道生挥毫如运帚。\n\n胸中邱壑蟠几许，落手寻丈等粒黍。笔底已无高房山，眼边不数米家虎。\n\n由来大巧无纤辞，讵有大力肯事轻描淡写为。窠臼尽脱笔墨外，不施皴染艺更奇。\n\n多君论画兼论文，读书读画同所云。愚意读画仍自读书始，俗工院体徒纷纷。\n\n世人但爱南田子，花叶工为没骨体。边徐而后叹独绝，寸缣尺素珍莫比。\n\n我获此幅赏其大落墨，是用作歌表奇伟。噫嚱吁，读画录中传久矣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '恽道生画山水歌' AND p.poem_author = '朱景英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('【中吕】满庭芳_寄友香笼锦', '任昱', '元代', '寄友\n\n香笼锦帏，歌讴白苎，人比红梅。风流杜牧新诗意，字字珠玑。桑落酒朝开绮席，杜陵花夜宿春衣。陶然醉，金勒马嘶，归路柳边迷。\n\n春暮\n\n云扃睡起，香销宝鼎，暖试罗衣。甫能宴罢兰亭会，又见春归。花片片翻成燕泥，柳依依也锁蛾眉。重门闭，绿阴树底，怕听杜鹃啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '【中吕】满庭芳_寄友香笼锦' AND p.poem_author = '任昱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闽中郑君炎南仲两魁乡赋比自霅教为昌化簿', '方回', '宋代', '三山鹄袍十万众，两纪知名郑南仲。\n妙年官赋甲秋闱，一发辄中仍再中。\n岂知天地大变革，原夫八韵竟无用。\n虽然改尔亦得力，斗南斗北声价哄。\n黄金台降中书敕，水晶宫请博士俸。\n得人岂必泥古法，省场舍选同乡贡。\n儒风未尽弃端章，学徒尚多习弦诵。\n但苦官冷饭不足，三载诳腹虀百瓮。\n终更受代颇已久，始闻巨轴以诗送。\n定是弟子多贤才，吴兴先生实梁栋。\n即今佐邑号为簿，尹丞不殊权任重。\n况乃唐昌风俗淳，山深岁稔少争讼。\n丈夫讵皆作卿相，一命关系民疾痛。\n偏见私意勿力竞，潜转密移但微讽。\n方册频窥身尽贫，苞苴不纳心奚恐。\n崇卑有无置度外，时一极目天宇空。\n江东接壤异西浙，桑蚕春忙田晚种。\n樽俎盘馔极俭啬，无大牲脔及乳湩。\n吾闻易彖识时义，未妨枳棘栖鸾凤。\n聊复亦耳磨岁月，慎勿轻为棺粪梦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闽中郑君炎南仲两魁乡赋比自霅教为昌化簿' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百二十三首 其七十一', '释普度', '宋代', '老瞿昙，眼孔小。一星半星容不得，说迷说悟何时了。\n\n衲僧分上那有许多般，雪晴海阔千峰晓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百二十三首 其七十一' AND p.poem_author = '释普度';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东城', '滕塛', '宋代', '东城有高楼，峨峨冠城阙。\n我来属昏暮，见此初上月。\n遥天罗江山，极目如霁雪。\n江山秀如此，岂不生豪杰。\n临风一高歌，达曙何由歇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东城' AND p.poem_author = '滕塛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同刘朔斋洲蒲涧谒菊坡祠', '李昴英', '宋代', '晓随丝辔饭僧坊，丞相祠堂一瓣香。\n试问神仙蒲九节，何如名德菊孤芳。\n高山仰止堪模楷，百世闻之尚激昂。\n我辈此来深有意，岂专泉石癖膏肓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同刘朔斋洲蒲涧谒菊坡祠' AND p.poem_author = '李昴英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('隐潭', '楼钥', '宋代', '灵潭深入白云堆，带雨春云为我开。\n乳石半空浑欲堕，瀑泉千尺正中来。\n两军酣战鼓鼙急，一雨生寒霹雳催。\n中有卧龙君勿狎，有时平地起风雷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '隐潭' AND p.poem_author = '楼钥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岁暮雪中', '释函可', '明代', '四十风光一抹收，故乡望断岁如流。料因诃佛填冰狱，岂为修文上玉楼。\n\n雪尽埋时偏得句，天当崩后更无忧。当年六载行难满，殃及儿孙冷不休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岁暮雪中' AND p.poem_author = '释函可';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('素尚斋', '弘历', '清代', '太古山中室，高秋时节天。有怀惟淡泊，无物不神仙。\n\n候暖林犹翠，露繁花益鲜。却嗤芥蒂者，动说俗尘蠲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '素尚斋' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑子', '顾随', '近代', '水边点点光明灭，拾似春灯。恰似繁星。恰似游魂自在行。\n\n细思三十年间事，如此凄清。一个流萤。自放微光暗处明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑子' AND p.poem_author = '顾随';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病中吕从野水部邀不赴赋谢', '王慎中', '明代', '宫云晓度湿晴沙，退食烟齐省树鸦。燕阙春回催玉羽，凤墀日暖映金花。\n\n文园不起茂陵卧，朔雪虚回剡曲槎。绮席瑶觞违命赏，露兰风草惜年华。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病中吕从野水部邀不赴赋谢' AND p.poem_author = '王慎中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('熏蚊效宛陵先生体', '陆游', '宋代', '泽国故多蚊，乘夜吁可怪。\n举扇不能却，燔艾取一快。\n不如小忍之，驱逐吾已隘。\n宁闻大度士，变色为蜂虿？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '熏蚊效宛陵先生体' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈', '释怀祥', '宋代', '南山高，北出低，日出东方夜落西。\n白牛上树觅不得，鸟鸡入水大家知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈' AND p.poem_author = '释怀祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游胶山即赋长句', '安全', '清代', '胶山流览兴何如，曾访山中旧景无。料想纪游诗必富，敢掬胜迹效吴歈。\n\n两峰耸时恰相对，白云飞去黄云在。东湾萋萋草际天，西瞻磊磊石应拜。\n\n蜿蜒龙腿接凤凰，凤凰常伏龙亦藏。红叶满山飘不定，龙凤遍体呈文章。\n\n山行自北得幽胜，古木疏篁绕石蹬。桥锁香花供冶游，坞藏碎石足持赠。\n\n梵王宫殿忆当年，唐宋名流吟咏传。环翠上方两不见，一丛榛莽敛残烟。\n\n秋老青梧翠叶亸，黄菊欺霜野香播。金牛有迹牧童眠，石马无声樵叟坐。\n\n俯仰岩阿感古今，流连光景漫沉吟。侍郎废墓寒云聚，丞相荒祠夕照阴。\n\n窦乳涓涓注石罅，色清味美人争讶。宋时翁挺尝品之，九龙中泠乃其亚。\n\n枫叶芦花飘暮秋，幽崖潭水碧于油。当年砺剑人何在，今日临池石尚留。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游胶山即赋长句' AND p.poem_author = '安全';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戊寅八月送弟铣受室于笋峰宪长伍宋诸婿会于前溪里第菊节寿辰予以事先别敬赋此章', '符锡', '明代', '丈人才硕古人看，翻为明时爱惜难。豸历秋山澄月霁，舟横春雨酿溪寒。\n\n文章世济兰阶美，昼锦筵开菊露团。珍重百年才六□，乘鸾有客醉先拚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戊寅八月送弟铣受室于笋峰宪长伍宋诸婿会于前溪里第菊节寿辰予以事先别敬赋此章' AND p.poem_author = '符锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和靖州判官陈子从山水图十韵·雨后观瀑', '魏了翁', '宋代', '泽气蒸前山，起自肤寸微。\n竞看千丈瀑，不悟片云飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和靖州判官陈子从山水图十韵·雨后观瀑' AND p.poem_author = '魏了翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浩气吟 其三', '瞿式耜', '明代', '正襟危坐待天光，两鬓依然劲似霜。愿仰须臾阶下鬼，何愁慷慨殿中狂。\n\n须知榜辱神无变，旋与衣冠语益庄。莫笑老夫轻一死，汗青留取姓名香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浩气吟 其三' AND p.poem_author = '瞿式耜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('见月落秋空云敛波出悠然有感', '郭之奇', '明代', '从来不识汉江秋，湛湛枫林寄古愁。落日扁舟依绿屿，清宵万壑抱沧流。\n\n月方一见思其满，云自初生看及收。遂有波光迎夜色，因之凄绪发蘋洲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '见月落秋空云敛波出悠然有感' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹤林仙坛寺', '黄庚', '宋代', '古坛归鹤杳，野鹿自成群。\n岚气浮清晓，钟声出白云。\n树穿僧屋老，水到寺门分。\n人世无穷事，山中了不闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹤林仙坛寺' AND p.poem_author = '黄庚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('红梨', '弘历', '清代', '女夷侈神权，万卉争一日。娈彼红梨花，芳姿岂容閟。\n\n英英粲晓风，裳裳映书室。昨来珊网撑，今看银云栉。\n\n无香良已佳，侔色真难匹。静观悟梦华，兴会蜚吟笔。\n\n底须惜流阴，流阴不因厄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '红梨' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十二月二十七日大雪中过吉水小盘渡西归三首', '杨万里', '宋代', '雪吹醉面不知寒，信脚千山与万山。\n天甃琼街三十里，更飞柳絮与君看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十二月二十七日大雪中过吉水小盘渡西归三首' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('去年闻载扬在武林及余至而载扬', '周紫芝', '宋代', '与君一别几经秋，忽作脩文地下游。诗忆向来云态度，人今何在柳风流。\n\n西湖烟月生前恨，客路风霜晚岁愁。胜日交流半零落，数行老泪倩谁收。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '去年闻载扬在武林及余至而载扬' AND p.poem_author = '周紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金山', '张蕴', '宋代', '江身台殿切空云，夜月鱼龙影不分。\n八十老僧相引说，潮痕不上郭公坟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金山' AND p.poem_author = '张蕴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居杂诗九十首', '曹勋', '宋代', '下邑常寂寞，细履寒溪头。\n鱼鰕腥断岸，橘柚明晚秋。\n山色俨晴碧，溪光泛澄流。\n相思故人远，应过回雁洲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居杂诗九十首' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桃村寄题三首 其一', '钱时', '宋代', '春入桃村烂熳红，纷纷来觅武陵踪。武陵不在千山外，只在先生一笑中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桃村寄题三首 其一' AND p.poem_author = '钱时';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病中谢亲友四首 其四', '俞德邻', '宋代', '一病连三月，肥甘宁得知。医复戒食盐，盐食非所宜。\n\n素餐幸无刺，餐素将何疑。因思丧乱际，黎民多阻饥。\n\n朝餐乃木叶，暮食乃树皮。我今食无盐，早晚白玉炊。\n\n稽首谢苍天，揆分忱过之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病中谢亲友四首 其四' AND p.poem_author = '俞德邻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题扇示俞生', '胡奎', '明代', '荷叶圆时初见汝，木犀落后便相疏。秋声只在庭前树，分寸阴中好看书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题扇示俞生' AND p.poem_author = '胡奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄公望秋峰耸秀小幅', '弘历', '清代', '峰峻水潺湲，精蓝树欲殷。津涂银峡口，磴道白云间。\n\n四序原无住，山僧只自閒。香光正法眼，粉本认虞山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄公望秋峰耸秀小幅' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿卓水二首 其一', '许衡', '元代', '寒釭挑尽火重生，竹有清声月自明。一夜客窗眠不稳，却听山犬吠柴荆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿卓水二首 其一' AND p.poem_author = '许衡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望梅', '龚翔麟', '清代', '横斜孕蕊。过春竿候月，冷葩慵试。记年年、小白蔫红，斗点点星毬，綵棚檐底。\n\n听说寒轻，最好是、今年天气。步莎阶渐软，竹外旧枝，暗苔愁倚。\n\n东垞石门深闭。忆梨花砚雨，斋在山背。定半窗、横幅依然，奈千里槎程，香魂迢递。\n\n梦也都寻，醒便隔、重重烟水。想花风到迟，有约待招燕子。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望梅' AND p.poem_author = '龚翔麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月', '白朴', '元代', '天上灵椿未老，月中丹桂初花。充闾佳庆尽堪夸。\n\n圣善元来姓贾。\n\n广座平分玉果，绛颅剩拂丹砂。从今人说细侯家。\n\n自有青衫竹马。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月' AND p.poem_author = '白朴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄唐惟良', '黎民表', '明代', '莫道分符不暂閒，五更无吏唤追班。尊前岭树连宫阁，门外春涛喷雪山。\n\n万里身为迁播客，几人名在是非间。长杨羽猎还今日，应遣词臣入汉关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄唐惟良' AND p.poem_author = '黎民表';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次王安行韵', '卞思义', '元代', '杖策来寻隐者居，闭门重著绝交书。入城无事不骑马，临水有时看钓鱼。\n\n未羡渊明开菊径，拟从诸葛住茅庐。清时羽翼知多少，肯散黄金学二疏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次王安行韵' AND p.poem_author = '卞思义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天（西湖）', '林淳', '宋代', '天近祅知雨露浓。湖山无日不春风。闲花野草皆掀舞，曾在君王愿盼中。 \n 时易得，会难逢。朝为逆旅暮三公。蛟龙得雨飞无便，鸡犬腾云夙有功。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天（西湖）' AND p.poem_author = '林淳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗十首 其八', '王汝玉', '明代', '弱水不容涉，蓬莱焉得游。生时被珠玉，死后归山邱。\n\n一身非我有，此外定足求。君子顺时命，小人行险谋。\n\n荣华能取辱，贫贱可忘忧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗十首 其八' AND p.poem_author = '王汝玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('燕子图三首 其三', '赵秉文', '金朝', '交亲消息两何如，满眼兵戈不得书。为问南来新燕子，衔泥曾复到吾庐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '燕子图三首 其三' AND p.poem_author = '赵秉文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白莲寺次韵杜进士喜予见过话旧之作', '高启', '明代', '不辞鸣棹远相寻，欲向江斋伴旅吟。\n百事未成年已长，几时才别夏将深。\n萱留倦蝶连池绿，树带残莺满寺阴。\n恐被老僧嫌滞碍，旧游休说更伤心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白莲寺次韵杜进士喜予见过话旧之作' AND p.poem_author = '高启';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('承旨乐山唐公八月十二日宴于其第以诗奉呈', '陈孚', '元代', '圣代开皇极，恩波雨露沾。笃生嵩岳佐，载叶渭川占。\n\n社稷千龄会，衣冠五福兼。朱弦新律吕，黄石旧韬钤。\n\n德望三朝眷，仪刑四海瞻。摛词追贾马，励学探羲炎。\n\n宇宙归青照，风云奋紫髯。议如唐陆贽，诗似晋陶潜。\n\n践履刚而毅，精神智以恬。一区杨子宅，万轴邺侯签。\n\n山色秋凝璧，烟光昼捲帘。金銮辞秉烛，玉铉待调盐。\n\n大匠规模远，宗公号令严。王臣躬蹇蹇，君子德谦谦。\n\n此日鸣朝凤，清秋近夜蟾。瑶簪环杖履，宝墨出湘缣。\n\n北海宾长满，东山屐未厌。车声阗绣户，花影舞朱檐。\n\n乐幸追灵运，忧当后仲淹。愿施经济具，天下待针砭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '承旨乐山唐公八月十二日宴于其第以诗奉呈' AND p.poem_author = '陈孚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十一月十四日有感寄江州太守李子威 其一', '成廷圭', '元代', '清朝如此盛公卿，何以摅忠答圣明。数月未收蕲水贼，一时谁散武昌兵。\n\n朱门旧邸空文藻，黑夜归舟有哭声。独使状元贤太守，至今犹捍九江城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十一月十四日有感寄江州太守李子威 其一' AND p.poem_author = '成廷圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居杂诗 其二', '罗万杰', '明代', '灌畦日暮荷锄归，满目蓬蒿夕照微。黄叶乍冲鸟语落，白云时绕磬声飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居杂诗 其二' AND p.poem_author = '罗万杰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('述怀', '洪传经', '现代', '疏狂无意逐功名，舞舌川湘又楚秦。\n学汇中西空自许，言非理则不相因。\n那知以此遘忧患，竟为多言犯要津。\n甚矣书生无一用，未能权变且谋生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '述怀' AND p.poem_author = '洪传经';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('立春', '姚佳', '当代', '鱼陟负冰应不禁，蜇虫始振几消沉。东风解冻还依旧，上界无生直至今。\n\n宰臣以下皆称贺，咫尺之间可鉴临。万世梧桐存祖殿，漫从枝叶感春心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '立春' AND p.poem_author = '姚佳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送曹同椅', '司空曙', '唐代', '青春三十馀，众艺尽无如。中散诗传画，将军扇续书。 \n 楚田晴下雁，江日暖游鱼。惆怅空相送，欢游自此疏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送曹同椅' AND p.poem_author = '司空曙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('扈跸词三十二首 其二十一', '陆深', '明代', '板轿棕舆渡碧山，涧花岩树影龙颜。云中别有通陵路，䟎过前驱插大班。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '扈跸词三十二首 其二十一' AND p.poem_author = '陆深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晓妆', '孙原湘', '清代', '水晶帘射日曈昽，茜子裈裆八尺红。羞对熟人呈晕月，笑持雏婢作屏风。\n\n梳头惯学轻云立，靧面才将艳雪融。偷描珠兰笼袖底，觑人方便掷奁中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晓妆' AND p.poem_author = '孙原湘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅仙祠', '赵公豫', '宋代', '汉尉垂纶处，遗风事可传。林深飞鸟入，水隔小桥连。\n\n道室幽如许，山花晚倍妍。到来心志静，不复有尘缘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅仙祠' AND p.poem_author = '赵公豫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送森知客', '释普度', '宋代', '清远溪边劄寨时，春风簇簇露枪旗。\n谁知唤客吃茶处，万别千差一道归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送森知客' AND p.poem_author = '释普度';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('淮阳路', '李商隐', '唐代', '荒村倚废营，投宿旅魂惊。断雁高仍急，寒溪晓更清。 \n 昔年尝聚盗，此日颇分兵。猜贰谁先致，三朝事始平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '淮阳路' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乙丑孟秋下旬四日杨中丞绝命诏狱是夜初昏时有气如白练起尾箕间扫紫微掩天枢五星时在燕邸目睹感赋二首 其一', '顾大武', '明代', '满地苌弘血染衣，补天功业竟安归。犹余万丈长虹气，此夕骖箕叩紫微。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乙丑孟秋下旬四日杨中丞绝命诏狱是夜初昏时有气如白练起尾箕间扫紫微掩天枢五星时在燕邸目睹感赋二首 其一' AND p.poem_author = '顾大武';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二怀诗 其一 玄真子张志和', '胡应麟', '明代', '有唐迄元和，畸流尚不乏。翩翩玄真子，百代恣渔猎。\n\n雅志游松乔，奇踪轨庄列。嗒尔柱下言，超然谢津筏。\n\n富贵轻鸿毛，轩冕等澌沫。一辞世主聘，浮家老苕霅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二怀诗 其一 玄真子张志和' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜王巩承事北归', '苏辙', '宋代', '同罪南迁惊最远，乘流北下喜先归。\n谓言一笑秋风后，却顾千山驿路非。\n岭外云烟随梦远，江边鱼蟹为人肥。\n还家嫁女都无事，卧读诗书尽掩扉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜王巩承事北归' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠钟道士', '范仲淹', '宋代', '人间无复动机心，挂了儒冠岁已深。惟有诗家风味在，一坛松月伴秋吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠钟道士' AND p.poem_author = '范仲淹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南柯子 秋夜', '叶小鸾', '明代', '门掩瑶琴静，窗消画卷闲。半庭香雾绕阑干。一带澹烟红树、隔楼看。\n\n云散青天瘦，风来翠袖寒。嫦娥眉又小檀弯。照得满阶花影、只难攀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南柯子 秋夜' AND p.poem_author = '叶小鸾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花 其一', '庞俊', '近代', '蜜炬围春帘不卷。依旧东风，款款飞双燕。看煞羊车人婉娈，熟人却是初相见。\n\n入手翠尊休待劝。不道中年，争信春宵短。叠鼓垂灯新句练，落梅天气深深院。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花 其一' AND p.poem_author = '庞俊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小舟晚归', '陆游', '宋代', '扶病寻溪友，忘忧泛钓槎。\n渚寒无宿鹭，月白有啼鸦。\n败壁青灯暗，幽窗稚子哗。\n无生未暇说，且复议桑麻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小舟晚归' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诉衷情（濡溪悼旧）', '黎廷瑞', '宋代', '曲屏深院赴幽期。心事梦云知。佩环零乱何处，江上草离离。 \n 日平西，天似幕，月如眉。依稀还记，两岸杨花，送上船时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诉衷情（濡溪悼旧）' AND p.poem_author = '黎廷瑞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('将至桂林戒弗作诗饮酒', '李曾伯', '宋代', '误领元戎太乙旗，提封四履镇南篱。\n旄倪争向道涂看，名姓亦为蛮徼知。\n时务下地毋事酒，春光虽好莫言诗。\n经营都了家山去，此是从穷容觞咏时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将至桂林戒弗作诗饮酒' AND p.poem_author = '李曾伯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东坡赤壁图', '曹之谦', '元代', '先生矫矫人中龙，京尘千丈不可容。五年一梦落江海，翩然野鹤开囚笼。\n\n雪堂闭户读书史，兴来飘然弄云水。黄泥坂下醉三更，赤壁矶头航一苇。\n\n明月清风共一江，迈往之气无由降。酒酣作赋记清赏，袖有巨笔如长杠。\n\n一朝骑鲸寻李白，人间俯仰成今昔。续弦无处觅鸾胶，见画思公空叹息。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东坡赤壁图' AND p.poem_author = '曹之谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江夏寓兴二首之二', '贺铸', '宋代', '陂湖蹙坊市，江汉复纵横。\n沮洳莎城阽，晴阳竹瓦鸣。\n新文添鹏赋，异味识鼋羹。\n岂复悲流落，官粮寓此生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江夏寓兴二首之二' AND p.poem_author = '贺铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙', '赵长卿', '宋代', '远岫螺头湿翠，流霞赪尾疏明。断虹斜界雨新晴。烟村灯火晚，江浦画难成。 \n 我向其间泛叶，终朝露渚风汀。老来心事最关情。不堪三弄笛，吹作断肠声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙' AND p.poem_author = '赵长卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其一○三', '谌祜', '宋代', '地上有钱流，冥閒无半字。自作槁木看，静阅沧江流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其一○三' AND p.poem_author = '谌祜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢池春', '李石', '宋代', '烟雨池塘，绿野乍添春涨。凤楼高、珠帘卷上。金柔玉困，舞腰肢相向。似玉人、瘦时模样。 \n 离亭别后，试问阳关谁唱。对青春、翻成怅望。重门静院，度香风屏障。吐飞花、伴人来往。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢池春' AND p.poem_author = '李石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长安道三首 其一', '沈鍊', '明代', '来往都城道，探知朝士心。若闻身世事，定肯却黄金。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长安道三首 其一' AND p.poem_author = '沈鍊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('北山道人栽松', '王安石', '宋代', '阳坡风暖雪初融，度谷遥看积翠重。\n磊砢拂天吾所爱，他生来此听楼钟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '北山道人栽松' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九月初四日大风雨近重阳无酒夜成二首', '方回', '宋代', '秋霖欲洗庾公尘，不管楼头客恨新。\n塞雁又为江左客，菊花曾识晋时人。\n百年虚谷先生老，一纪严州太守贫。\n几向客右度重九。苦无佳句答良辰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九月初四日大风雨近重阳无酒夜成二首' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻征四处士', '贯休', '唐代', '一诏群公起，移山四海闻。因知丈夫事，须佐圣明君。 \n 白酒全倾瓮，蒲轮半载云。从兹居谏署，笔砚几人焚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻征四处士' AND p.poem_author = '贯休';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辰江杂兴 其二', '符锡', '明代', '有路沿云断，无人但鸟呼。半山御落日，始觉客怀孤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辰江杂兴 其二' AND p.poem_author = '符锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舍人崔公挽词 其一', '黄定', '宋代', '昭代培英俊，皇天独不仁。儒林埋鸑鷟，翰苑失麒麟。\n\n青史空遗字，黄麻半掩尘。惟馀忠荩语，分付义方人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舍人崔公挽词 其一' AND p.poem_author = '黄定';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('伯兄自山中来夜话山居之胜因忆去秋省兄未及十日而别诗以志感得二十韵', '吴敬梓', '清代', '地本烟霞窟，兄为巢许伦。百年歌帝力，十亩乐天真。\n\n抱阜宜营室，还汀许结邻。绿回芳草长，黛染远峰匀。\n\n社鼓乌江庙，灵旗牛渚津。山川馀质朴，习俗尚清淳。\n\n野老嬉游共，村翁来往频。藤萝阴漏月，桑柘影随身。\n\n美酒盈杯劝，良苗几棱新。饧箫花外市，牧笛雨中春。\n\n幸免家人谪，偏馀稚子亲。摊书消永夜，高枕卧清晨。\n\n自著潜夫论，宁辞原宪贫。昨秋过故里，留我住弥旬。\n\n薜荔依门巷，蒹葭变水滨。圆沙知雁聚，曲港见鸥驯。\n\n蟹簖缘溪富，鱼罾罥树均。嘉肴仍速舅，肥牡定娱宾。\n\n愿得长相倚，须完未了因。寄声劳扰客，此是武陵人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '伯兄自山中来夜话山居之胜因忆去秋省兄未及十日而别诗以志感得二十韵' AND p.poem_author = '吴敬梓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梓于鳞集有感八绝句 其四', '王世贞', '明代', '雪楼高傍㟙湖濆，消渴频年卧白云。问得儿驹留草在，教人翻恨卓文君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梓于鳞集有感八绝句 其四' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陪陶尚书宋太史夜宿斋宫分韵得万字', '刘崧', '明代', '鸣鸾莅阳郊，陪祀服明宪。旂常拥圆壝，幕帟蔽脩甸。\n\n天高风泠泠，露白星烂烂。尊罍秩斯举，簴业枞以建。\n\n凝神向澄肃，秉德方恪愿。调笙思肄三，振羽将舞万。\n\n张筵盛布设，陈币昭奠献。听漏促晨兴，严衣戒宵偃。\n\n骏奔尚齐遫，慎简惭硕曼。感孚岂殊徵，恭事式同劝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陪陶尚书宋太史夜宿斋宫分韵得万字' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沙河主人后园枣实甚繁感而有述', '顾清', '明代', '牡丹红径尺，一败即空枝。枣花大于米，结实反累累。\n\n世途争外骛，衒巧复矜奇。仪衍雄辩说，潘陆姱文辞。\n\n华藻炫缃素，声名倾一时。终然木强子，铭功汉鼎彝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沙河主人后园枣实甚繁感而有述' AND p.poem_author = '顾清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满庭芳 七首满庭芳藏头字句不一，疑有误', '王哲', '元代', '黄邑于公乞修行论修行，翁甚喜，津堪作琼浆。清火赫，颠倒吉还昌。显金乌甚朗。中现、玉兔精详。谈正，处暑气变成霜。当。内宝，珍珠璧，一一收藏。尤良善善，性烛施张。现灵明愈耀，中土、本有真光。冥点，烟散尽，堪庆满庭芳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满庭芳 七首满庭芳藏头字句不一，疑有误' AND p.poem_author = '王哲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('托吴僧乞石田画', '杭淮', '明代', '缅怀高人今白头，秋风未放沧江舸。叹息人间常见画，白水丹山无不可。\n\n有时更出双梧桐，柯如碧玉参青空。下有閒翁曳杖屦，萧然意气来清风。\n\n自是君身有仙骨，放笔尘寰看超忽。且知画者乃馀事，君有声名非汩没。\n\n吾亦平生颇好画，逢人不爱千金求。安得生绡出东壁，白云为我生沧洲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '托吴僧乞石田画' AND p.poem_author = '杭淮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湖上怀同少野', '释行海', '宋代', '衰柳残阳泊钓船，白鸥零落画桥边。\n咸平处士梅花树，不得同看又两年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湖上怀同少野' AND p.poem_author = '释行海';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归田乐', '蔡伸', '宋代', '风生苹末莲香细。新浴晚凉天气。犹自倚朱阑，波面双双彩鸳戏。鸾钗委坠云堆髻。谁会此时情意。冰簟玉琴横，还是月明人千里。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归田乐' AND p.poem_author = '蔡伸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('铙歌 其十五 上邪', '李攀龙', '明代', '上邪。我欲与君同心，乐以不可禁。相思绍缭，谗言罔极，大驾六龙处天侧。\n\n日月出入沧海中，妒人之子难为工。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '铙歌 其十五 上邪' AND p.poem_author = '李攀龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题画四首 其二 题扇', '梁兰', '明代', '钿合收残黛，香风吹绿衣。閒来消永昼，非是效班姬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题画四首 其二 题扇' AND p.poem_author = '梁兰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花一首', '刘克庄', '宋代', '造化生尤物，居然冠众芳。\n东家傅粉白，西域返魂香。\n真可婿芍药，未妨妃海棠。\n平生恨欧九，极口说姚黄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花一首' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('河中戏作绝句', '晁说之', '宋代', '人物英雄异姓王，山河生气尚光鋩。\n可怜只解夸佳丽，花落春空更断肠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '河中戏作绝句' AND p.poem_author = '晁说之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('避地寒食', '易翀', '明代', '插柳才惊寒食逢，弟兄奔走各西东。落花有恨随风舞，芳草无情泣露浓。\n\n白发暗添沦落里，青春已过乱离中。寥寥先陇南山外，谁为持觞一扫松。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '避地寒食' AND p.poem_author = '易翀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中环海旁道漫步', '伯昏子', '当代', '鳌池片屿挟云奔，蜃影蓬莱荡帝阍。蔽日楼摇鱼鸟出，排空浪鼓蚁车喧。\n\n依前古道名酋督，不复洋行树鬼幡。钟鼎嫌伤尘俗气，争趋山半筑华轩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中环海旁道漫步' AND p.poem_author = '伯昏子';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠傅与砺', '虞集', '元代', '水玉空青不易求，兰苕翡翠擅清秋。才情岂是人间少，不到高唐梦未休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠傅与砺' AND p.poem_author = '虞集';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过波罗二首 其二', '湛若水', '明代', '举手望飞云，鸣桡过黄木。舣舟江上亭，虚空观日浴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过波罗二首 其二' AND p.poem_author = '湛若水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五月十二日晚登平云亭得平字齐字', '郭印', '宋代', '磴道穿乔木，危亭喜杖藜。\n郊原春树暗，井邑暮烟低。\n日没牛羊下，山空鸟雀啼。\n超然尘世外，身与白云齐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五月十二日晚登平云亭得平字齐字' AND p.poem_author = '郭印';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六月雨十一首', '许月卿', '宋代', '今岁无时不御寇，每年此际去防秋。\n琴散广陵今叔夜，笳声出室古刘畴。\n启沃欣承霖雨楫，流离安乐雁鸿洲。\n我自清时幸民着，茅柴薄晚妇能篘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六月雨十一首' AND p.poem_author = '许月卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚晴落照', '弘历', '清代', '急雨驱殢云，晚晴辉落照。入波翻画楼，挂树明烟峤。\n\n助之西北风，寥寥鸣万窍。迟日方立秋，气机已先到。\n\n鸣蝉惜景光，嘒嘒枝头噪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚晴落照' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠童子久住侍父入京', '陈献章', '明代', '还著小坡随长公，天葩未吐孝经通。青襟谁不羡童子，白发我徒成老翁。\n\n曝日家声从此大，凌云气魄盖人雄。曲江清献乡先达，敢道后来无此风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠童子久住侍父入京' AND p.poem_author = '陈献章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('素琼表妹示和其师华西洲先生消夏十八首次韵和之 其五', '温倩华', '近代', '花外人来唱采莲，冰绡新染水痕鲜。一声欸乃幽篁里，惊起鸳鸯破碧烟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '素琼表妹示和其师华西洲先生消夏十八首次韵和之 其五' AND p.poem_author = '温倩华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和松石舍人秋夜不寐', '袁士元', '元代', '抛书欲卧意迟迟，坐听秋声思惨悽。萤火独飞侵幔小，星河斜落压城低。\n\n牙筹历历随更转，燐鬼啾啾隔水啼。更为挑灯移近榻，与僧相对话曹溪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和松石舍人秋夜不寐' AND p.poem_author = '袁士元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晓登沅州北山顶', '薛瑄', '明代', '岚霭氤氲重，溪行咫尺迷。渐登层巘上，始觉众山低。\n\n远近天无际，参差树不齐。川云平似海，石磴峻如梯。\n\n日出寒烟外，风生碧涧倪。异禽和露宿，快马度空嘶。\n\n远目回三蜀，高怀遍五溪。归朝誇胜槩，沅水有新题。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晓登沅州北山顶' AND p.poem_author = '薛瑄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('癸丑春闱试毕次韵知举倪侍郎先生二首 其二', '李东阳', '明代', '夜灯人静不成眠，亲听王褒颂得贤。圣代文章真盛矣，少时情兴转翻然。\n\n麟凰遍薮元多瑞，奎壁分宫亦并躔。南省东堂嘉话里，几人同事复同年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '癸丑春闱试毕次韵知举倪侍郎先生二首 其二' AND p.poem_author = '李东阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题山水图二首 其一', '萧镃', '明代', '青山何岧峣，下有嘉树林。高亭昼闲敞，窗户含层阴。\n\n前村夜来雨，石濑张素琴。好鸟鸣檐间，始知春意深。\n\n迥无外物累，嘿处抱冲襟。对此案上书，悠悠千载心。\n\n安得谢尘羁，扁舟谐远寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题山水图二首 其一' AND p.poem_author = '萧镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('于安城答灵运诗 其四', '谢瞻', '南北朝', '肇允虽同规，翻飞各异概。迢递封畿外，窈窕承明内。\n\n寻途之既暌，即理理已对。丝路有恒悲，矧乃在吾爱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '于安城答灵运诗 其四' AND p.poem_author = '谢瞻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送草伯镇知湖州', '司马光', '宋代', '江外饶佳郡，吴兴天下稀。\n蓴羹紫丝滑，鲈脍雪花以。\n星斗寒相照，烟波碧四围。\n柳侯还作牧，草树转清辉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送草伯镇知湖州' AND p.poem_author = '司马光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬暮村居杂咏，寄叔白七首 其七', '李宪噩', '清代', '孤吟知兴远，闲坐亦深更。僮睡呼不醒，镫昏挑暂明。\n\n夜寒如有悟，钟尽即无声。晓寄城中客，还能识此情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬暮村居杂咏，寄叔白七首 其七' AND p.poem_author = '李宪噩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十月十二日奉诏以玉德殿西室为宫学大宿卫官等二十五人行弟子礼作', '周伯琦', '元代', '学校尊崇盛典扬，诏迁玉德殿西廊。大官供帐调珍膳，内相传宣饮御觞。\n\n授业惭无师道立，明伦喜见国家昌。皇风即日还三代，杞梓楩楠尽栋梁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十月十二日奉诏以玉德殿西室为宫学大宿卫官等二十五人行弟子礼作' AND p.poem_author = '周伯琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('屏山老人诗用李宾之韵', '张泰', '明代', '岁晚开园傍玉屏，朝朝仙屿眼中青。九峰分秀来空翠，森木团烟隐鹤汀。\n\n东老自为仙隐地，南山宜作寿藏铭。有生期与人同乐，不饮常防客共醒。\n\n文屦长年盈我户，惠风迟日散邻扃。并荣华萼知春足，连秀芝兰觉地灵。\n\n雅望满乡称长者，德言康俗胜官刑。义声津口垂虹石，仁术囊中本草经。\n\n载悦凤毛晞杲杲，坐忘乌帽裹星星。屏山有叟增光价，千载应看似敬亭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '屏山老人诗用李宾之韵' AND p.poem_author = '张泰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜泊永乐有怀', '许浑', '唐代', '莲渚愁红荡碧波，吴娃齐唱采莲歌。 \n 横塘一别已千里，芦苇萧萧风雨多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜泊永乐有怀' AND p.poem_author = '许浑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新开小轩晁子西有诗以韵答之二首', '郭印', '宋代', '我无先世英，敢望燕台筑。\n譬如坎井蛙，拘虚徒窘束。\n又如鹪鹩巢，所寄一枝足。\n名不闻公卿，迹非侣樵牧。\n眼花鬓毛霜，黾勉作侯服。\n吏才固不高，民事亦稍熟。\n每欲思寡过，岂敢求多福。\n君公迟风云，行矣龙起陆。\n佳篇杂沓来，文绣被土木。\n坐令北窗下，不知有穷独。\n相逢一笑粲，语妙席自促。\n凭谁觅仙方，造酒逡巡速。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新开小轩晁子西有诗以韵答之二首' AND p.poem_author = '郭印';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('思母', '唐宙', '明代', '冷落莆阳掷却杯，梦魂频绕粤王台。身无著处官为累，事不如人口懒开。\n\n碧水丹山殊驿路，疏灯细雨各天台。慈亲跂望无虚日，拟卜明春拂袖回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '思母' AND p.poem_author = '唐宙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('肺病', '周行己', '宋代', '吾生与静侔，早无适俗器。失身挂尘网，道心日已替。\n\n今兹得肺病，自可绝人事。默观悟生理，是身同一蜕。\n\n代马无南蹄，越鸟无北翅。物各归其本，我何有于世。\n\n冠冕且罢休，养痾山水际。藉石看白云，临流鼓兰枻。\n\n百种绝念虑，优游聊卒岁。谁云病疾苦，邂逅即良计。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '肺病' AND p.poem_author = '周行己';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('得湖州崔十八使君书喜与杭越邻郡因成长句代贺兼寄微之', '白居易', '唐代', '三郡何因此结缘，贞元科第忝同年。故情欢喜开书后， \n 旧事思量在眼前。越国封疆吞碧海，杭城楼閤入青烟。 \n 吴兴卑小君应屈，为是蓬莱最后仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '得湖州崔十八使君书喜与杭越邻郡因成长句代贺兼寄微之' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋闺 其三', '谢榛', '明代', '寒蛩兼夜雨，并作枕边愁。天涯有苦乐，两地一般秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋闺 其三' AND p.poem_author = '谢榛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭金秀才', '郭谏臣', '明代', '月落江湖夜已阑，故人别后见应难。西风吹散清宵梦，肠断霜天雁影寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭金秀才' AND p.poem_author = '郭谏臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('今岁梅花春中犹未开因思三衢冬月之盛作长句', '李正民', '宋代', '前年柯山芳意早，肯使寒梅例枯槁。溪边几树发偏繁，墙角数枝看更好。\n\n玉颜冒雪不奈寒，香心怯雨尤相恼。南枝烂漫北枝催，空惜飘零缀芳草。\n\n朅来海角风景迟，经冬不见端可疑。红萼涉春才似染，青苞映日未全披。\n\n千山隔兮万山阻，想见瑶英讵如许。一枝谁与寄相思，回首旧游心独苦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '今岁梅花春中犹未开因思三衢冬月之盛作长句' AND p.poem_author = '李正民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜意', '陆游', '宋代', '幌外灯青见鼠行，林梢月黑有枭鸣。\n只言中夏夜偏短，万里梦回天未明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜意' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('樟树镇舟中作', '杨基', '明代', '侬是吴淞钓鱼叟，全家生长吴江口。\n迟钝长飞众鸟先，迂疏每落诸人后。\n城中父老少相知，乡里儿童亦见欺。\n几上细抄《高士传》，壁间大篆《考槃》诗。\n春风百草承膏沐，强掷渔蓑亲案牍。\n胥史犹嘲吏事疏，妻孥欲笑形容俗。\n羸马长途恐不堪，君恩何日许投簪。\n半篷秋雨烟笼水，数点寒星月满潭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '樟树镇舟中作' AND p.poem_author = '杨基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('昆山慧聚寺集句', '葛次仲', '宋代', '全吴临巨溟，青山天一隅。静境林麓好，胜槩凌方壶。\n\n泓泓野泉洁，暧暧烟谷虚。攀云造禅扃，跻险筑幽居。\n\n道人刺猛虎，复来薙榛芜。咄嗟檀施开，以有此屋庐。\n\n侧叠万古石，功就岂斯须。磥砢成广殿，鬼工不可图。\n\n有穷者孟郊，过此亦踌躇。赋诗留岩屏，词律响琼琚。\n\n我访岑寂境，幸与高士俱。时升翠微上，凉阁对红蕖。\n\n岸帻偃东斋，果药杂纷敷。上方风景清，华敞绰有馀。\n\n高窗瞰远郊，万壑明晴初。赏爱未能去，赪霞照桑榆。\n\n老僧道机熟，闲持贝叶书。秉心识本源，高谈出有无。\n\n茗酌待幽客，顿令烦抱舒。儒道虽异门，意合不为殊。\n\n抖擞垢秽衣，惟有牟尼珠。馀生愿休止，投策谢归涂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '昆山慧聚寺集句' AND p.poem_author = '葛次仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚泊石头城下明旦发龙江', '张以宁', '明代', '江口帆开五两飞，海门遥望树依微。若为得似千年鹤，东向三神岛上归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚泊石头城下明旦发龙江' AND p.poem_author = '张以宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史二十四首 其十三', '黄淳耀', '明代', '威兽未入汉，郅支方挽强。子公仗剑怒，一战殪其王。\n\n捷书才视草，劾奏已成章。大臣衡与显，摇笔侍岩廊。\n\n臂诎妨射虎，声颓坐贪狼。何人泣李广，永毒壮士肠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史二十四首 其十三' AND p.poem_author = '黄淳耀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高邮湖阻风时虽开夹湖未能行舟', '程敏政', '明代', '一阵狂飙入地垠，客舟如叶浪如轮。凭谁上诉由风伯，任尔抛香拜水神。\n\n阿岸稍卑思跃马，夹湖虽好未通人。南来北去皆行役，篷底从容莫漫嗔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高邮湖阻风时虽开夹湖未能行舟' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴中大水有负郭田在常州云已漂溃作一首示公仪', '刘敞', '宋代', '百谷驰东南，三江浇吴会。积阴漏云汉，涌水翻积块。\n\n斯民既昏垫，我稼堕颠沛。鱼鳖有馀粮，郊原靡遗穗。\n\n糊口窃自恕，矜寡将何赖。天道有盈虚，吾宁罪于岁。\n\n救饥苦谋拙，禹稷不可待。行矣帆长风，因之浮海外。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴中大水有负郭田在常州云已漂溃作一首示公仪' AND p.poem_author = '刘敞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上元前一夜童都督席上观灯 其二', '游朴', '明代', '严更柝静不闻喧，火队星车次第奔。杨柳无根莺并宿，梅花欲落蝶双翻。\n\n楼船飞鹢行平陆，卉服驯师舞戟门。熢燧时平无用处，化为银烛照金尊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上元前一夜童都督席上观灯 其二' AND p.poem_author = '游朴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吊邹汝愚谪石城 其二', '陈献章', '明代', '江月无光江水寒，角声杳杳夜漫漫。孤儿岁月初离乳，夫子风流尽盖棺。\n\n身后岂知名可贵，世间长苦路行难。鸱夷不乱当年计，还得云门枕上看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吊邹汝愚谪石城 其二' AND p.poem_author = '陈献章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄大司马王公度', '韩雍', '明代', '大才不易得，时艰良可忧。所以古圣贤，治世怀远猷。\n\n召公欲致政，周公勉相留。二公心德同，俪美匡成周。\n\n芳声播千古，人皆仰前修。堂堂王司马，当代第一流。\n\n以身徇国家，才气谁可俦。方兹任经济，整顿多事秋。\n\n如何在告中，遽尔得退休。不知诸同列，亦曾勉留不。\n\n昨简掌邦政，朝廷广询谋。黄门御史言，称职惟君优。\n\n上允即超拜，四方动欢讴。兹闻勇退归，物议皆啾啾。\n\n嗟予忝知己，痛惜不自由。所惜为天下，匪为君身谋。\n\n四方水旱多，贼盗方且稠。须起出群才，同心运良筹。\n\n渊衷必有在，士论终当收。君其善养年，予未歌四愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄大司马王公度' AND p.poem_author = '韩雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('莼二绝 其二', '张侃', '宋代', '达人胸次与天宽，到处浮家得细看。满盌莼丝浮碧色，不妨邀客话儒酸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '莼二绝 其二' AND p.poem_author = '张侃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('祥符寺', '聂致尧', '宋代', '诸峰回合处，古木抱松林。\n月占秋廊静，云侵昼殿阴。\n有泉通石眼，不火沸池心。\n洗净多生垢，天风更梵音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '祥符寺' AND p.poem_author = '聂致尧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('合宫歌（皇佑二年飨明堂）', '赵祯', '宋代', '缵重明。端拱保凝命。广大孝休德，永锡四海有庆。觚坛寓礼正典名。幔室雅奏，彩仗崇制定。五位仿古甚盛。蒿宫光符辰星。高秋嘉时款芎灵。交累圣。上下来顾，寅畏歆纯诚。三阶平。金气肃，转和景。翠葆御双观，异风兑泽布令。脂茶划荡墨索清。远迩响附，动植咸遂性。表里穆悦，庶政醇醲，熙然胥庭。唐舜华封祝，如南山寿永。愿今广怀宁延，昌基扃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '合宫歌（皇佑二年飨明堂）' AND p.poem_author = '赵祯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岳阳晚兴（四首）', '叶子奇', '明代', '长天秋水一色，落日青山半衔。\n雁浦烟波渔笛，龙阳风雨归帆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岳阳晚兴（四首）' AND p.poem_author = '叶子奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长夏无事避暑山园景事所会即成微吟得二十绝句 其十', '王世贞', '明代', '北风高枕便羲皇，佳景无多畏景长。争似侬家祗树苑，六时何处不清凉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长夏无事避暑山园景事所会即成微吟得二十绝句 其十' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂三十八首', '释如净', '宋代', '黄金殿上一转语，烜爀红轮照万方，\n草木丛林成正觉，砖头瓦砾放毫光。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂三十八首' AND p.poem_author = '释如净';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('莲花篇', '周馨桂', '清代', '莲花何灼灼，灼灼花莫比。淤泥中濯濯，濯濯出清水。\n\n把酒对莲花，莲花笑欲语。生憎荡舟人，允矣吾与汝。\n\n觅句对莲花，莲花宛可则。不见太白诗，天然去雕饰。\n\n每当初日际，起我先公思。先公爱莲花，高怀契清姿。\n\n清姿与高怀，千秋常若斯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '莲花篇' AND p.poem_author = '周馨桂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄题吴氏社仓', '项安世', '宋代', '淹剧无悰易怆神，社仓新记重关心。\n前朝诏在恩沦骨，遗老书存泪满襟。\n永念君仁多善稼，肯因师死下乔林。\n皇天老眼明于镜，勉植书楼万桂阴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄题吴氏社仓' AND p.poem_author = '项安世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋胡行四首 其四', '李孙宸', '明代', '毁誉何常，权势易为名。毁誉何常，权势易为名。乘风呼长，非疾其声。\n\n窈国侯门，仁义所并。兰生幽谷，孰扬其馨。歌以言之，权势易为名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋胡行四首 其四' AND p.poem_author = '李孙宸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('缘识', '宋太宗', '宋代', '群生宗法界，秘密十方尊。\n大教缘心识，周通一念存。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '缘识' AND p.poem_author = '宋太宗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('步西湖次韵徐南卿 其五', '陈造', '宋代', '徐子学诗苦，砚池宁暂临。课功初赑屃，著语遽精深。\n\n更积岁月力，傥陪英俊林。人生才业地，渠辈分平沈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '步西湖次韵徐南卿 其五' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('毛虞卿见过', '王十朋', '宋代', '故人访吾庐，况是清和节。高槐绿成阴，芳草碧未歇。\n\n携手山间行，清兴浩然发。呼童具鸡黍，浊酒醅初泼。\n\n贫居愧荒凉，野蔌草罗列。盘实饤梅豆，蔬餐荐薇蕨。\n\n主礼虽甚微，客色未尝觖。醉翁山水意，不为壶觞设。\n\n蟹眼煎新汲，雀舌烹春撷。浇君文字肠，掉我清谈舌。\n\n人生会面难，岁月易飘忽。君姑为我留，匆匆莫言别。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '毛虞卿见过' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和竹士晓游邓尉作', '金逸', '清代', '一声笛破晴空烟，欲明不明五更天。树头残月白堕水，湖上晓山青入船。\n\n风梵飘香落云外，波光拥棹来门前。四围皆雪失大地，徜徉绝顶疑游仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和竹士晓游邓尉作' AND p.poem_author = '金逸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('台湾竹枝词 其三十', '丘逢甲', '清代', '好吟应是太痴生，笔墨因缘记不清。谁把四弦弹夜月，新词唱遍赤嵌城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '台湾竹枝词 其三十' AND p.poem_author = '丘逢甲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书寄陈昼卿书尾', '陈寿祺', '清代', '欲归还小住，杯酒许重斟。信宿分离后，相思直到今。\n\n大江流远梦，小雅托哀音。记否中山夜，绳床听雨心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书寄陈昼卿书尾' AND p.poem_author = '陈寿祺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答吴献臣大尹 其四', '祁顺', '明代', '云霄未竟忠勤志，江海空怜濩落身。便欲乘风问真宰，赐环何日起孤臣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答吴献臣大尹 其四' AND p.poem_author = '祁顺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('度灵羊峡望崧台', '郭棐', '明代', '西江西峡郁嵯峨，南客南来几啸歌。旭日映空翻翠壁，飞云当岫袅青萝。\n\n能将华发逢秋色，欲把青竿侣钓蓑。野兴狂吟予不浅，崧台携手思如何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '度灵羊峡望崧台' AND p.poem_author = '郭棐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('妻为儿买龟种于瓦盆今携至护国寺放生戏题一首', '李达', '当代', '兰若放尔去，瓦盆曾久留。归池仍缩壳，顾我肯回头？\n\n莲净巢堪寄，饭香僧为投。小男犹不舍，欲捉更无由。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '妻为儿买龟种于瓦盆今携至护国寺放生戏题一首' AND p.poem_author = '李达';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('枕上偶成三首 其二', '杜范', '宋代', '春动边声虏计狂，淮流据断架浮梁。雨师怒烈风云阵，定报惊奔尽犬羊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '枕上偶成三首 其二' AND p.poem_author = '杜范';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和钟漕汝强四首', '胡寅', '宋代', '雾豹成文不厌深，喧卑何事竞翰音。\n为言墨客夸三赋，那似仙翁振八吟。\n欲继高踪其敢后，下看浮世岂须临。\n何时蜡屐携筇杖，来拨衡云一万寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和钟漕汝强四首' AND p.poem_author = '胡寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古兴', '李新', '宋代', '倮葬畏礼法，厚葬索衣衾。\n金缕与玉柙，五陵非不深。\n万宝埋幽光，苦为群盗寻。\n上古莫封植，弃之中野林。\n上以饱飞鸟，下从蝼蚁侵。\n人情远臭腐，焉知孝子心。\n死者或有知，自亦畏奢淫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古兴' AND p.poem_author = '李新';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('涵碧亭八咏 其二 石鼓浮岚', '程敏政', '明代', '小山本幽绝，晴岚湿衣裾。谁能琢崖藓，正作岐阳书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '涵碧亭八咏 其二 石鼓浮岚' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与陶生', '释妙声', '明代', '我有青山一片霞，倩君为我制加沙。明朝天上讲经去，吹落满身优钵华。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与陶生' AND p.poem_author = '释妙声';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和文与可洋川园池三十首 披锦亭', '苏轼', '宋代', '烟红露绿晓风香，燕舞莺啼春日长。\n谁道使君贫且老，绣屏锦帐咽笙簧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和文与可洋川园池三十首 披锦亭' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('柳梢青', '陆求可', '清代', '云外天香，月中桂子，又做中秋。一曲霓裳，三声玉笛，两度嬉游。\n\n披衣不用登楼。但花下、诗筒酒筹。恐似前番，金钱散落，醉里谁收。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '柳梢青' AND p.poem_author = '陆求可';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过秀野亭观赵昌花', '朱翌', '宋代', '牡丹酴醾送春归，南风亦复吹戎葵。\n青女不瘦芙蓉肌，雪中山茶火争辉。\n此开彼落相背驰，安得坐隅皆见之。\n剑南老人来解衣，好手不免如徐熙。\n萧然四幅十二枝，规模一出众史卑。\n妙处天授非人为，右军字画少陵诗。\n后来纵好难并驰，传观左右识者谁。\n爱画入骨一痴，惜哉不犹坡谷题。\n何妨扰扰俗眼疑，秀野前后花成帷，\n按图求之君自知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过秀野亭观赵昌花' AND p.poem_author = '朱翌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('邹一桂菊华秋实', '弘历', '清代', '都云秋实胜春华，畦径今看别一家。也祗金英方合称，兜罗绵手恰拈花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '邹一桂菊华秋实' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂述 其七', '林泳', '宋代', '一念重来如祖忍，三生尽见有图澄。虎虽化女心常在，鹰已为鸠眼可憎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂述 其七' AND p.poem_author = '林泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游武夷山二首 其一', '韦骧', '宋代', '一溪秋水碧溶溶，逆掉扁舟溯晚风。卧看峰峦耸奇势，心疑造化炫殊功。\n\n宾云曲断笙箫远，机石苔荒组织空。仙理冥冥难究诘，抽簪归隐羡刘公。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游武夷山二首 其一' AND p.poem_author = '韦骧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠真头陀', '胡应麟', '明代', '南州来赋客，北苑问高僧。佛土穷三界，人天度七陵。\n\n孤云晨拓钵，大雪夜传灯。便欲逃禅去，风幡證惠能。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠真头陀' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晓霁发顺河', '姚燮', '清代', '天光浩荡晨曦开，断云片片鱼鳞吹。好风习习东南来，拂人衣袂清无埃。\n\n高原郁润欲下滴，远山隐秀难平窥。新茭芽短水出没，晚麰花小烟萦回。\n\n蝉声乍停蛙语接，塘燕侧逐林鸠飞。夏中气候等春晚，天宇四溢皆灵机。\n\n适行八日达山左，凭辕蒿目增惨凄。赤阳槁土万生暍，村户荒落人烟稀。\n\n夜来云气汹西北，沛作甘澍连青徐。淮堤泗闸各流活，塍沟如绠通凫鹥。\n\n孳荣不虑禾有耳，大禳可卜秋无饥。茧足尘帽路行客，对此亦觉清心脾。\n\n桃源傥容移宅隐，吾将袯襫从扶犁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晓霁发顺河' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自吕堰趋襄阳', '傅应台', '清代', '望望章台道，遥遥岘首亭。云生三户白，日落万山青。\n\n远雁来衡岳，孤帆下洞庭。相思何处是，烟树夕冥冥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自吕堰趋襄阳' AND p.poem_author = '傅应台';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吸江亭下望烟霞洞口梅花', '黄浚', '近代', '梅花即烟霞，岁久心化铁。绛宵谢轩轩，寂寞见高节。\n\n斜看自然好，俯看更奇绝。此亭谁云稳，吸江才一瞥。\n\n林间缟衣人，笑我肠内热。仙云翩在下，令我天眼缬。\n\n十年两相见，万事那可说。细雨满关山，相逢忍攀折。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吸江亭下望烟霞洞口梅花' AND p.poem_author = '黄浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('生查子 其一 不贰适', '黄绮', '当代', '白纸有清真，以墨添图字。纸亦愿牺牲，代答人间意。\n\n烈火总燃烧，高热思吞水。水下就深渊，宁自身焚毁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '生查子 其一 不贰适' AND p.poem_author = '黄绮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('婆罗门六首 其一', '耶律铸', '元代', '热海气蒸为喜雨，冻城寒结就愁阴。中心甚欲期真宰，教使人知造物心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '婆罗门六首 其一' AND p.poem_author = '耶律铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('通鉴', '薛瑄', '明代', '千二年来治乱机，只从理欲辨安危。若将此鉴为心鉴，三五如何不并归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '通鉴' AND p.poem_author = '薛瑄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('漫兴二首', '邓渼', '明代', '花县常三仕，台乌偶一枝。\n不能执虎子，须效牧羊儿。\n兰摧终异艾，豆落仅存萁。\n共说长沙傅，生当盛汉时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '漫兴二首' AND p.poem_author = '邓渼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送盛孔赴淄川丞二首 其二', '贝琼', '明代', '魏有径寸珠，守境无檀子。照车十二乘，何如照千里。\n\n世乏威王贤，孰知天下士。所以饭牛儿，商歌中夜起。\n\n徒求南海产，半触蛟龙死。异才何代无，纠纷今可理。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送盛孔赴淄川丞二首 其二' AND p.poem_author = '贝琼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李昭象书堂', '释希坦', '宋代', '废兴生死妄安名，山水何曾改旧清。孰谓堂空人已往，溪声还作读书声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李昭象书堂' AND p.poem_author = '释希坦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏示邻友三章 其一', '姚燮', '清代', '终朝咄咄当讴歌，束手看君计奈何？灌釜甘浆烹大芋，蜷门病狗恋重蓑。\n\n大江日落潮未落，老屋风多湿更多。巢父掉头许由笑，兔毫秃尽换无鹅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏示邻友三章 其一' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和麟老韵五绝', '王炎', '宋代', '白雪蒙头卧佛庐，笔端亦解世间书。\n无情安用诗陶写，有病何须药破除。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和麟老韵五绝' AND p.poem_author = '王炎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次翰林都事拜住春日见寄韵', '张以宁', '明代', '日高睡起小窗明，飞絮游丝弄昼晴。\n忽忆金河年少梦，柳阴骑马听流莺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次翰林都事拜住春日见寄韵' AND p.poem_author = '张以宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和姜总管归途', '虞俦', '宋代', '城郭迎车骑，溪山展画图。\n归鸦翻落叶，宿雁集寒芜。\n酒里倾肝胆，吟边识步趋。\n佳人来底暮，心傒碧云苏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和姜总管归途' AND p.poem_author = '虞俦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和陈仲邦野步城西', '谢逸', '宋代', '寺近仙坛西复西，醉中信足路应迷。鸣条风劲凋蒲柳，掠岸云低乱鹄鹥。\n\n檐外檀栾森翠巘，门前略彴跨清溪。葛巾藜杖真潇散，何必狨鞍鞚月题。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和陈仲邦野步城西' AND p.poem_author = '谢逸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('用大名诸公唱和韵送别少逸 其四', '王安中', '宋代', '迩来走笔吟，别后随手散。收拾亦安用，半是谐谑间。\n\n不能所作工，要解风水涣。莫以人废言，遂忽博士谩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '用大名诸公唱和韵送别少逸 其四' AND p.poem_author = '王安中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游安乐山', '任伋', '宋代', '安乐溪上峰，万木森翠羽。\n孤撑切天心，横拓压刊股。\n气势西吞夷，光芒南定楚。\n云泉出石窦，淋漓洒玉宇。\n烟萝缠林梢，摇拽垂翠组。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游安乐山' AND p.poem_author = '任伋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('集禧观池上咏野鹅', '王安石', '宋代', '池上野鹅无数好，晴天镜里雪毰毸。\n似怜喧暖鸣相逐，疑恋宽闲去却回。\n京洛尘沙工点污，江湖矰弋饱惊猿。\n羽毛的的人难近，嗟此谋身或有才。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '集禧观池上咏野鹅' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赋得剑并送汤宪副', '童佩', '明代', '宝剑曾留此，千年尚有名。星辰片云识，风雨半江生。\n\n炼想古人迹，功知烈士成。张华在当路，宁使久延平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赋得剑并送汤宪副' AND p.poem_author = '童佩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨中花', '李雯', '清代', '漫说海榴开遍了，怎无缘、玉山一倒。写破狼毫，题残蚕纸，总为愁人道。\n\n庭院深深晴昼好，奈相思、梦儿不到。反插牙签，倾倒花里，只是闲烦恼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨中花' AND p.poem_author = '李雯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠王弇州先生 其七', '佘翔', '明代', '神如秋水映芙蓉，懒著朝衣听晓钟。笑问仙风谁得似，茅家兄弟跨双龙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠王弇州先生 其七' AND p.poem_author = '佘翔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('正月十四春寒招无为县友人宴集卧牛山麓，马春女史有诗相赠，次韵答之', '潘乐乐', '当代', '能招嵇阮嵚崎子，来坐溪山料峭春。槛外沙寒窥射蜮，樽前雨迸泣郊麟。\n\n滔滔自堕谁相惜，脉脉香微世欲新。吾道陵夷天未绝，残宵可待海扬尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '正月十四春寒招无为县友人宴集卧牛山麓，马春女史有诗相赠，次韵答之' AND p.poem_author = '潘乐乐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('儿子岷自维扬还至金陵得朱县尹仲文手书且云荷接引良厚二绝寄谢时仲文将调官京师假馆维扬 其一', '梁寅', '元代', '木犀香里设离筵，建业西风八月天。一骑仍留大江北，双凫何日五云边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '儿子岷自维扬还至金陵得朱县尹仲文手书且云荷接引良厚二绝寄谢时仲文将调官京师假馆维扬 其一' AND p.poem_author = '梁寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游烂柯山', '谢勮', '唐代', '独凌清景出，下视众山中。云日遥相对，川原无不通。 \n自致高标末，何心待驭风。 \n宛演横半规，穹崇翠微上。云扃掩苔石，千古无人赏。 \n宁知后贤心，登此共来往。 \n仙弈示樵夫，能言忘归路。因看斧柯烂，孙子发已素。 \n孰云遗迹久，举意如旦暮。 \n仙僧会真要，应物常渊默。惟将无住理，转与信人说。 \n月影清江中，可观不可得。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游烂柯山' AND p.poem_author = '谢勮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病中代书奉寄圣俞二十五兄', '欧阳修', '宋代', '忆君去年来自越，值我传车催去阙。\n是时新秋蟹正肥，恨不一醉与君别。\n今年得疾因酒作，一春不饮气弥劣。\n饥肠未惯饱甘脆，九虫寸白争为孽。\n一饱犹能致身患，宠禄岂无神所罚。\n乃知赋予分有涯，适分自然无夭阏。\n昔在洛阳年少时，春思每先花乱发。\n萌芽不待杨柳动，探春马蹄常踏雪。\n到今年才三十九，怕见新花羞白发。\n颜侵塞下风霜色，病过镇阳桃李月。\n兵闲事简居可乐，心意自衰非屑屑。\n日长天暖惟欲睡，睡美尤厌春鸠聒。\n北潭去城无百步，渌水冰销鱼拨刺。\n经时曾未著脚到，好景但听游人说。\n官荣虽厚世味薄，始信衣缨乃羁绁。\n故人有几独思君。安得见君忧暂豁。\n公厨酒美远莫致，念君贳饮衣屡脱。\n郭生书来犹未到，想见新诗甚饥汤。\n少年事事今已去，惟有爱诗心未歇。\n君闲可能为我作，莫辞自书藤纸滑。\n少低笔力容我和，无使难追韵高绝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病中代书奉寄圣俞二十五兄' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭辛霁', '钱起', '唐代', '流水辞山花别枝，随风一去绝还期。昨夜故人泉下宿， \n 今朝白发镜中垂。音徽寂寂空成梦，容范朝朝无见时。 \n 旦暮馀生几息在，不应存没未尝悲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭辛霁' AND p.poem_author = '钱起';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶有感 其五', '杨爵', '明代', '当年祗抱素餐羞，一日疏狂七载囚。安得此时廊庙上，有人聊为我皇忧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶有感 其五' AND p.poem_author = '杨爵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天津', '区大相', '明代', '御河三百里，南下作天津。堤似饮牛畔，船如驾鹊滨。\n\n荣光元瑞洛，德水故溁秦。赴海仙瀛接，经天帝泽新。\n\n水香花近苑，沙碧柳藏春。今夕乘槎使，谁知问渡人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天津' AND p.poem_author = '区大相';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吉祥寺旧名永寿初李昪为徐温养子徐知训不能容置酒欲杀之行酒吏刁彦能以手爪昪悟而逃伏此寺山谷作记无咎书', '李吕', '宋代', '招提一径入垂杨，翠竹千竿粉箨香。正要银丝好看客，不须雪乳苦搜肠。\n\n兴亡徐李一弹指，文字晁黄两擅场。八十老僧无个事，犹将经卷佞空王。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吉祥寺旧名永寿初李昪为徐温养子徐知训不能容置酒欲杀之行酒吏刁彦能以手爪昪悟而逃伏此寺山谷作记无咎书' AND p.poem_author = '李吕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高阳台·燕卷情丝', '蒋捷', '宋代', '燕卷情丝，蜂黏落絮，天教绾住闲愁。闲里清明，匆匆粉涩红羞。灯摇缥晕茸窗冷，语未阑、蛾影分收。好伤情，春也难留，人也难留。芳尘满目悠悠。问萦云佩响，还绕谁楼。别酒才斟，从前心事都休。飞莺纵有风吹转，奈旧家、苑已成秋。莫思量，杨柳湾西，且棹吟舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高阳台·燕卷情丝' AND p.poem_author = '蒋捷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('为志学聘君题惠麓秋晴图', '朱芾', '明代', '第二泉头坐晚晴，满林松籁杂溪声。涤烦老去卢鸿一，谢俗归来卫叔卿。\n\n未必《茶经》随火化，拟寻茅屋待春耕。卧游画里违清赏，裹茗它年石上烹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '为志学聘君题惠麓秋晴图' AND p.poem_author = '朱芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉使辞朝赐酒饭', '祁顺', '明代', '陛辞天咫尺，赐食励忠勤。翠釜仙庖具，黄封玉液分。\n\n深恩同湛露，高宴叶需云。使事惭迂拙，何由答圣君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉使辞朝赐酒饭' AND p.poem_author = '祁顺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠司徒兼侍中宋宣献挽词四首', '宋庠', '宋代', '一世文为伯，三階象有光。\n何言隆栋吉，忽叹夜舟藏。\n襚礼朝颁册，哀音路过丧。\n善人今不与，神理太茫茫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠司徒兼侍中宋宣献挽词四首' AND p.poem_author = '宋庠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游春十二首 其九', '姚合', '唐代', '朝朝看春色，春色似相怜。酒醒莺啼里，诗成蝶舞前。\n\n摘花盈手露，折竹满庭烟。亲故多相笑，疏狂似少年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游春十二首 其九' AND p.poem_author = '姚合';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵答李孟宣', '曾广钧', '清代', '三年踪迹太支离，水转花逢偶在斯。自古孙阳轻骏骨，不为混沌画蛾眉。\n\n南园新记吾知免，东阁前恩泪尚垂。自笑平生如意少，已曾孤负度辽师。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵答李孟宣' AND p.poem_author = '曾广钧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怕春归 秋山道中，中夜闻落叶声有作', '蔡松年', '金朝', '老去心情，乐在故园生处。客愁如隋堤乱絮。秋岚照水度黄衣，微雨。记篷窗、旧年吴楚。飘萧鬓绿，日日西风吹去。梦频频、萧闲风土。橙黄蟹紫醉琴书，容与。向他年、尚堪接武。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怕春归 秋山道中，中夜闻落叶声有作' AND p.poem_author = '蔡松年';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杨柳', '宋自适', '宋代', '丝丝烟雨弄轻柔，偏称黄鹂与白鸥。\n才著一蝉嘶晚日，西风容易便成秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杨柳' AND p.poem_author = '宋自适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鳌峰草堂歌十首 其七', '陆深', '明代', '新裁道服绿罗寒，别有乌霞制作冠。后夜相思长琐月，酒徒诗伴满长安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鳌峰草堂歌十首 其七' AND p.poem_author = '陆深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重阳太守招登东山以腹疾不能赴', '郑刚中', '宋代', '卧对佳辰两鬓斑，幽忧深闲屋三间。\n芎能去湿方摩腹，菊可延龄少慰颜。\n骨瘦免教先落帽，酒行无分作颓山。\n遥知太守登高处，座客诗成烛影闲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重阳太守招登东山以腹疾不能赴' AND p.poem_author = '郑刚中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆江南 其二', '王蛰堪', '当代', '湖山约，何日共兰舟。水面风荷人面似，梦边骚屑砚边收。\n\n能不忆龙湫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆江南 其二' AND p.poem_author = '王蛰堪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天命三首 其二', '吴未淳', '近代', '自乏驱穷术，谁传却老方。烦忧来故故，岁月去堂堂。\n\n贫觉亲朋远，衰令道业荒。无端身外事，未死讵能忘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天命三首 其二' AND p.poem_author = '吴未淳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('待月桥', '梅庚', '清代', '石梁横谷口，花片逐残春。风响应茶臼，岚光下葛巾。\n\n几时鹧鸪月，已照虎溪人。此是峰头路，潺湲好问津。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '待月桥' AND p.poem_author = '梅庚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又题卓锡泉', '留元崇', '宋代', '吾师知地脉，杖锡此间卓。\n分占神仙囿，敲出清泠玉。\n锡飞已乘龙，泉洁可饮鹤。\n林下几寒暑，池中不盈涸。\n木石常借润，瓶罂随量足。\n池无汲绠线，逗引走修竹。\n渴心生尘埃，对此惬所欲。\n洗耳听松音，漱齿汲山绿。\n更携一壶归，为浣众生浊。\n遥愧山中人，四时自斟酌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又题卓锡泉' AND p.poem_author = '留元崇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵徐子礼提举莺花亭 其六', '范成大', '宋代', '古藤阴下醉中休，谁与低眉唱此愁。团扇他年书好句，平生知已识儋州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵徐子礼提举莺花亭 其六' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('祝英台近 九秋望日访卞玉京墓，同人分咏得影字，墓在慧山祁陀寺锦树林', '杨抡', '清代', '碧云窝，黄叶径。古寺一声磬。秋满空山，愁绪暗相引。\n\n可堪蔓草凄迷，香魂何处，添多少、雨昏花暝。\n\n万千恨，只恨地老天荒，惊鸿杳无影。玉已成烟，春梦几曾醒。\n\n试看半壁斜阳，霜林似锦，怕凤子、归来难认。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '祝英台近 九秋望日访卞玉京墓，同人分咏得影字，墓在慧山祁陀寺锦树林' AND p.poem_author = '杨抡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和杨公济钱塘西湖百题 其三十七 九师堂', '郭祥正', '宋代', '尔学五古子，缘何绘九师。堂高秋月淡，日用少人知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和杨公济钱塘西湖百题 其三十七 九师堂' AND p.poem_author = '郭祥正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('幽居奉借遁庵尊兄严韵呈隐之润之二英弟一粲 其一', '段成己', '金朝', '解鞍借榻避风埃，净拂风轩待我开。诗句堕前还忘却，聊书岁月记曾来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '幽居奉借遁庵尊兄严韵呈隐之润之二英弟一粲 其一' AND p.poem_author = '段成己';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('某氏挽辞二首 其二', '李昭玘', '宋代', '主馈齐家道，羞蘩肃妇功。疏封秦大国，致养汉三公。\n\n世事哀荣极，人生梦幻空。慈颜不可望，彤史有遗风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '某氏挽辞二首 其二' AND p.poem_author = '李昭玘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('百花洲梅', '蒲寿宬', '宋代', '孤根宁不在栽培，枝北枝南春一回。\n尽道游鱼是佳谶，不知洲上有花魁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '百花洲梅' AND p.poem_author = '蒲寿宬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诉衷情令', '丘处机', '元代', '孤城寒角韵悠扬。风送入斜阳。池塘菡萏无色，兰畹有馀香。\n\n秋日短，暮天长。月华昌。空空寂照，荡荡虚心，一片清凉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诉衷情令' AND p.poem_author = '丘处机';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('壶中天 万顷堂', '凌学攽', '近代', '踏青随处，趁芳草香轮。耸身飞步。一步桑畦斜岭脚，梯接松坪杉圃。\n\n希隐杨园，寻春管社，但问渔樵侣。岑楼凌阁，几人猿鸟同住。\n\n袖携词稿狂吟，层波岸尾，花竹掩亭午。坐啸群峰横翠里，暂傲作湖山主。\n\n向背吟情，去来帆影，水柳依依舞。可能忘倦，群觅醉，徐巷去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '壶中天 万顷堂' AND p.poem_author = '凌学攽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('波斯短歌行译笺 其一○○', '钟锦', '当代', '明月寻人夜夜来，盈虚不改此追陪。凄凉知有谁相遇？只向空园照冷杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '波斯短歌行译笺 其一○○' AND p.poem_author = '钟锦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂书示陈国佐胡元茂四首 其四', '陈与义', '宋代', '昔吾同年友，壮志各南溟。十年风雨过，见此落落星。\n\n秀者吾元茂，众器见鼎铏。许身稷契间，不但醉六经。\n\n时逢下车揖，慰我两眼青。勿忧事不理，伯始在朝廷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂书示陈国佐胡元茂四首 其四' AND p.poem_author = '陈与义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鸳鸯湖棹歌　之十四', '朱彝尊', '清代', '堤外湖光堤内池，露荷珠缀夜凉时。\n阿谁月底修萧谱，更按《东堂》旧日词。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鸳鸯湖棹歌　之十四' AND p.poem_author = '朱彝尊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('声声慢 立秋日同诸生过城南荒园，予三十年前与碧琴栖息于此', '何振岱', '清代', '烟深林罅，路转城湾，暑天晴久苔黄。亭榭高低重来，换尽风光。\n\n当年招游佳境，剩蛙声、一水都荒。石坪上，有锦棚、横晒半桁斜阳。\n\n今日也偕吟侣，共卷帘、小坐领受茶香。旧曾吟处，寒云占断琴床。\n\n追想故人仙去，燕飞来、空话雕梁。倚栏久，剩松风吹过新凉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '声声慢 立秋日同诸生过城南荒园，予三十年前与碧琴栖息于此' AND p.poem_author = '何振岱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其十九', '丁谓', '宋代', '遥闻甘似醴，不特在金茎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其十九' AND p.poem_author = '丁谓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵盘隐陆别驾先贤堂下月夜见寄', '释居简', '宋代', '自与先贤分不生，酒船隙地鹤随行。桥阑架碧疑虹跨，葑畛围香拟岸横。\n\n凉度绿云花不寐，尽馀红泪烛须更。明朝秋思谁先得，笑听蘋花与蓼争。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵盘隐陆别驾先贤堂下月夜见寄' AND p.poem_author = '释居简';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋怀二首 其二', '卢龙云', '明代', '草木渐黄落，春华乃变衰。旅雁先霜至，寒蛩傍砌悲。\n\n栖栖怜在远，税驾渺难期。纡怀何所托，飞蓬愁鬓丝。\n\n恨无凌风羽，徘徊将安之。沉吟以朝夕，百感良在兹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋怀二首 其二' AND p.poem_author = '卢龙云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('飞云洞景十二首 其五 绿野耕云', '卢龙云', '明代', '春来日上课农亭，满壑云含雨气青。东作易成耕犊健，居閒能诵兔园经。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '飞云洞景十二首 其五 绿野耕云' AND p.poem_author = '卢龙云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六歌 其六', '文天祥', '宋代', '我生我生何不辰，孤根不识桃李春。天寒日短重愁人，北风随我铁马尘。\n\n初怜骨肉钟奇祸，而今骨肉相怜我。汝在北兮婴我怀，我死谁当收我骸。\n\n人生百年何丑好，黄粱得丧俱草草。呜呼六歌兮勿复道，出门一笑天地老。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六歌 其六' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('息耕草堂冬日即事杂诗五章与黄太守丈安涛 其三', '姚燮', '清代', '流水当门过客稀，独依古木看斜晖。大江云雁书应到，白发霜灯子未归。\n\n海雹夜来犹打屋，园蕉秋后已无衣。鹿卢在手生尘色，起唱朱驎泪一挥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '息耕草堂冬日即事杂诗五章与黄太守丈安涛 其三' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早起', '郑獬', '宋代', '头疼宿酒未能解，独怕晓寒帘捲迟。懊恨桃花爱飘荡，夜来压折海棠枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早起' AND p.poem_author = '郑獬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天', '汪玢', '近代', '不为多情解怆情，西风扬起暮云平。庙堂箫管金如土，饿莩兵戈道路横。\n\n趋枥食，傍垣行，可堪今日作书生。待将一骑冲尘去，踏碎关河古月明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天' AND p.poem_author = '汪玢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杏花十首为林子赋林子有美膢名杏者别嫁而懊思不已情见乎词而邓子和之 其三', '邓云霄', '明代', '珍重曾围七宝栏，犹张锦幄护春寒。天香已触花王妒，墙外遥从隔幕看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杏花十首为林子赋林子有美膢名杏者别嫁而懊思不已情见乎词而邓子和之 其三' AND p.poem_author = '邓云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('述怀五十三首 其二十六', '周是修', '明代', '昔人多爱酒，为会酒之真。不饮愁万结，饮之愁自伸。\n\n醉醒醒复醉，恍然忘此身。八仙本高士，七贤岂众伦。\n\n囊括经济术，觞咏日逡巡。穷通付天命，富贵等浮云。\n\n九原今可作，愿尔与为群。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '述怀五十三首 其二十六' AND p.poem_author = '周是修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晓起长安道中', '金孝槐', '清代', '野店杂声唱晓寒，一钩残月堕林端。红楼梦里何曾识，付与行人马上看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晓起长安道中' AND p.poem_author = '金孝槐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('权知文州刘公', '刘麟瑞', '元代', '江流移浚向南山，渴死全城胆亦寒。叛将踰城机尽泄，娇儿饮药泪空潸。\n\n封疆事去君臣在，忠孝名存父子难。五万军民同日尽，可怜巷战尚间关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '权知文州刘公' AND p.poem_author = '刘麟瑞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次山房韵古意四首', '何梦桂', '宋代', '夜舟不藏壑，川流无回波。\n百年逐忧乐，昼夜相戛摩。\n逝者不复来，皓首成蹉跎。\n谁欤伤凤衰，毋乃楚狂歌。\n兹世固难免，纵有朝与鮀。\n猗兰曲易弹，只恐听者讹。\n折杨杂黄荂，每与俚耳和。\n感此歌晨风，忘我将如何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次山房韵古意四首' AND p.poem_author = '何梦桂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留别折子明丈二首 其一', '赵蕃', '宋代', '久作湘中客，数从林下游。契繇先世叙，谊向古人求。\n\n我敢逃黄绶，公宁卧白头。庙堂有北客，人物想中州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留别折子明丈二首 其一' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('画眉笔', '刘献池', '清代', '卧蚕细扫浅深分，堪笑中书陋不文。新月鼠须描更巧，远山螺黛饰成纹。\n\n毛锥一管蛾添色，柳叶双弯麝有芬。最爱十眉图画肖，挥毫落纸墨缤纷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '画眉笔' AND p.poem_author = '刘献池';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄亨父（二首）', '陆容', '明代', '金马门深昼漏迟，石渠新草汉文辞。\n丝纶世掌多君在，竹帛名传为尔期。\n匏叶鋋墙风起处，土花生砌雨晴时。\n革除旧恨成新乐，木榻清樽颇费诗。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄亨父（二首）' AND p.poem_author = '陆容';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('榕城八景 其二 绕窖棉阴', '郭之奇', '明代', '玉川如带绕城阴，入眼丛青翠影侵。已淈污泥从水出，遥参碧汉倩云禁。\n\n连翩各有扶疏质，独立犹馀萧飒心。不信松寒非可并，多年海国挺孤森。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '榕城八景 其二 绕窖棉阴' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感寓 其四十五', '朱诚泳', '明代', '吁嗟兹世人，居官多老饕。孜孜慕名位，焉知奔竞劳。\n\n权门炙手热，冰山与天高。绥绥乞昏夜，白日矜所遭。\n\n相君喜松寿，凉州博葡萄。好官我自为，笑骂空嘲嘈。\n\n君看柄臣第，车马何滔滔。幽人方寂寞，闭门读离骚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感寓 其四十五' AND p.poem_author = '朱诚泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史三十一首 其九', '黄毓祺', '清代', '梅福弃妻子，吴市变姓名。逢萌客辽海，冠挂东都门。\n\n偃卧不出户，蒋诩暨郭钦。薛方慕巢由，笑却安车迎。\n\n陈咸用汉腊，不忍污先人。或远或近间，要归洁其身。\n\n自惭年老矣，无以报汉恩。谊岂事二姓，印绶徒纷纷。\n\n杜口十日馀，龚胜真死臣。嗟彼莽大夫，何颜对忠魂。\n\n附莽亦非一，吾尤恨刘歆。其父最先见，国祚移近亲。\n\n歆也官国师，进封曰嘉新。何以陈尚书，三子皆同心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史三十一首 其九' AND p.poem_author = '黄毓祺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早朝十绝', '赵子潚', '宋代', '廿载承恩侍九重，泰阶玉烛喜遭逢。\n嘉禾瑞协当年兆，伫看远夷贡献同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早朝十绝' AND p.poem_author = '赵子潚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和吴翁晋梅花诗十三首 其十', '邓云霄', '明代', '东阁栽来大几围，古今清梦眼中稀。应怜国色羞红粉，始信山人是白衣。\n\n旷野萧疏幽兴发，闲堂寂静宦情微。五陵年少如相问，不用披裘更策肥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和吴翁晋梅花诗十三首 其十' AND p.poem_author = '邓云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暑中北窗昼卧有作', '陆游', '宋代', '御疾如治河，但当导之东，下流既有归，自然行地中。\n养生如蓺木，培植要得宜，常使无夭伤，自有干云时。\n我少本多疾，屡亦频危殆，皇天实相之，警告意有在。\n中年弃嗜欲，晚岁节饮食，中坚却外慕，魔盛有定力。\n死生虽天命，人事常相参，茫茫九衢中，百祸起一贪。\n郊虚暑雨余，巾堕脚不袜。\n高卧北窗凉，超然寄疏豁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暑中北窗昼卧有作' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('醉落魄 其二 去邸', '丁澎', '清代', '子归可矣。十年不索长安米。掉头沧海成何事。屠狗从游，阅尽人间世。\n\n学成一敛胡为尔。酒酣不倚田鼢势。裂眦莫救荆卿死。\n\n挥手而来，浪迹于今始。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '醉落魄 其二 去邸' AND p.poem_author = '丁澎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和谭云翔送双桂韵', '王志道', '宋代', '双柱婆娑天上花，殷勤分送士元家。\n捷钤果副联鞯祝，谒谢当期谷旦差。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和谭云翔送双桂韵' AND p.poem_author = '王志道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郴江百咏并序·俯春亭', '阮阅', '宋代', '城上危亭可摘云，四边山色翠为邻。\n下窥城郭无余蕴，草色花光尽是春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郴江百咏并序·俯春亭' AND p.poem_author = '阮阅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄许澜伯', '张扆', '明代', '予与澜伯同客绮川，澜伯以禁烟先回扫墓，寓舍有怀，因\n诗以寄。\n水泊山栖分自甘，我留君去意何堪。\n几回雨雪三槎上，强半莺花五坞南。\n宰木空惭归远梦，扁舟犹忆载余酣。\n从今莫惜频相顾，灯火虚斋迟笑谈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄许澜伯' AND p.poem_author = '张扆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杪秋同右史南山眺望', '李攀龙', '明代', '南山有幽意，驾言此徘徊。湖波荡寒城，四座清光开。\n\n金天澄素景，秋气何悲哉。繁阴递白日，浮云间往来。\n\n落木飒中林，流飙激岩隈。朝昏上烟火，原隰被楼台。\n\n故乡无滞淫，世路多尘埃。念我平生欢，离思壮难裁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杪秋同右史南山眺望' AND p.poem_author = '李攀龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('百字令', '龚自珍', '清代', '龙华劫换，问何人料理，断金零粉。五万春花如梦过，难遣些些春恨。\n\n帐亸春宵，枕敧红玉，中有沧桑影。定山堂畔，白头可照明镜。\n\n记得肠断江南，花飞两岸，老去才还尽。何不绛云楼下去，同礼空王钟磬。\n\n青史闲看，红妆浅拜，回护吾宗肯。漳江一传，心头蓦地来省。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '百字令' AND p.poem_author = '龚自珍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('剑池', '谢肃', '明代', '巳闻神剑千年化，空俯灵池十丈宽。泉脉尚通江海润，龙光曾照斗牛寒。\n\n飞梁背负层楼重，老树根将堕石蟠。一啸苍崖回杀气，未容仙鬼咏悲酸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '剑池' AND p.poem_author = '谢肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人', '黄侃', '近代', '痴蚕作茧丝难绝。香烬炉灰热。如今相见已无缘。赢得一回追忆一悽然。\n\n惊风吹散琼楼梦。别恨伤鸾凤。彩云飞去更无踪。回首蓬山似隔几多重。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人' AND p.poem_author = '黄侃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送观可道郎中祠南镇使淮府还京（二首）', '王逢', '元代', '亲奉天香祀会稽，黄封玉检烂金泥。\n地同南岳临朱鸟，祠俯名藩异碧鸡。\n三秀乘春沾雨露，五云披晓见端倪。\n好祈神化资神武，缥渺前旌举白霓。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送观可道郎中祠南镇使淮府还京（二首）' AND p.poem_author = '王逢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('土番竹枝词 其七', '郁永河', '清代', '铝贝雕螺各尽功，陆离斑驳碧兼红。番儿项下重重绕，客至疑过绣领宫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '土番竹枝词 其七' AND p.poem_author = '郁永河';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('嵩山老人告行作六偈送之', '释正觉', '宋代', '应缘分影来池月，游世无心出岫云。\n适意归来尖屋底，蔬畦还与力鉏勤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '嵩山老人告行作六偈送之' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赴召留题英德驿', '汪广洋', '明代', '英德县前多好山，山峰拥翠出云间。人家星散盗贼少，官舍日长文字閒。\n\n江水舂容涵夕景，岸花红白带春殷。愧无宋璟匡时策，也自交州奉召还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赴召留题英德驿' AND p.poem_author = '汪广洋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('除日', '孟洋', '明代', '边城除日至，犹自备戎机。马上惊残岁，河边对落晖。\n\n逢人空问讯，逾节始言归。回首年来事，徘徊一振衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '除日' AND p.poem_author = '孟洋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('商子引谚', '佚名', '先秦', '蠹众而木折。\n隙大而墙坏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '商子引谚' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('石室', '陈洵直', '宋代', '琅玕蕊笈藏幽谷，唯见白云三五幅。\n昔日天师其姓吴，岩前遗下云中屋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '石室' AND p.poem_author = '陈洵直';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和此阳先生感兴诗二十首', '刘黻', '宋代', '仙佛各有门，托言深入山。\n一探寂灭宗，一透船汞关。\n菩提司非树，刀圭诧灵丹。\n槁形付尘幻，蜕骨冲飞翰。\n咄咄亦奇事，讵惮力到难。\n儒先著有训，整辔皇路安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和此阳先生感兴诗二十首' AND p.poem_author = '刘黻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('甲午端阳即事', '徐熥', '明代', '满市贫民尽噪呼，谁家尊酒汎菖蒲。汉廷久已饥方朔，楚泽何人吊左徒。\n\n残喘厌看长命缕，空囊安用辟兵符。愁来试上孤城望，几处炊烟几处无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '甲午端阳即事' AND p.poem_author = '徐熥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八月二十四日', '吴当', '元代', '丑夜城头烈炬红，数声笳起戍楼空。江山如旧豪华去，无食无衣一病翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八月二十四日' AND p.poem_author = '吴当';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三月八日百五节林敬舆携酒约盛元仁戴帅初方万里访赵仲实宣慰于西湖第五桥之曲港南山书院五首 其四', '方回', '宋代', '生长西湖死葬湖，兴言舟子与农夫。全家衣食凭摇橹，历世儿孙学荷锄。\n\n布衲劣兼蓑笠有，齑汤恐并酱醯无。金盘玉箸环歌舞，午鬨昏空一任渠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三月八日百五节林敬舆携酒约盛元仁戴帅初方万里访赵仲实宣慰于西湖第五桥之曲港南山书院五首 其四' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一岩', '郑清之', '宋代', '一岩洞空挂云山，巧印穹苍半璧环。\n只为广寒宫殿远，故留阙月在人间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '一岩' AND p.poem_author = '郑清之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一一二首 其四十四', '释清远', '宋代', '腊月扇子功勋绝，浩浩凉风动寥泬。岂止炎蒸六月天，暂时与君解烦热。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一一二首 其四十四' AND p.poem_author = '释清远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贺新郎二十首 其四', '李慈铭', '清代', '看尔扬鞭去。正愁人、东风满目，扰花狂絮。故国苍茫天万里，不辨越山何处。\n\n更碣海、波涛汹怒。䝟兕磨牙鲛舐腭，但只身、掉臂游行过。\n\n最怜少日伤孤露。耐荒寒苧灯齑粥，半生难苦。赢得科名酬母教，衣锦暂时团聚。\n\n讵转足、便迷归路。薄宦未成家陷贼，负高堂、总被微名误。\n\n穿垒走，涕如雨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贺新郎二十首 其四' AND p.poem_author = '李慈铭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次刘五原见寄韵 其四', '释今■（艹黾）', '明代', '渴想青莲甚，每承阆苑诗。相期缘有待，先遣梦通知。\n\n应念三生石，曾开双镜池。荷花昨夜放，怀抱益悽其。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次刘五原见寄韵 其四' AND p.poem_author = '释今■（艹黾）';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜王定国北归第五桥', '苏轼', '宋代', '白露凄风洗瘴烟，梦回相对两凄然。\n雀罗廷尉非当日，鸠杖先生愈少年。\n世事饱谙思缩手，主恩未报耻归田。\n谁怜第五桥东水，独照台州老郑虔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜王定国北归第五桥' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苦暑消夏二首 其一', '卢青山', '当代', '夏云如火扑晴栏，镇日尘埃养路蝉。可有清秋能到梦？常祈小病为疗闲。\n\n夜阑越觉山亲近，心澈才佳月淡寒。小屐单衫无定向，随萤踏尽百千湾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苦暑消夏二首 其一' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂咏下 野绿堂', '洪适', '宋代', '缘流排劲草，盈野鞠长芦。烟树高低见，如开平远图。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂咏下 野绿堂' AND p.poem_author = '洪适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚登广朗阁', '欧大任', '明代', '广朗坪前霁色鲜，丹梯一望总堪怜。云端曲接千重岭，阁上平开万里天。\n\n远树暝悬沧海日，空山秋卧鹿门烟。风泉细洒琅玕在，石上镌名不记年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚登广朗阁' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽张云庄宗礼三首 其二', '陶宗仪', '元代', '嫁殃遭太守，簿录降将军。短景灯馀燄，繁华水上云。\n\n贤愚谁复辨，玉石竟俱焚。次第修言行，他时表墓文。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽张云庄宗礼三首 其二' AND p.poem_author = '陶宗仪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬黄帝锡见和', '张埴', '宋代', '龙髯初一振，人尽息其机。\n池静朱华出，山凉白鸟归。\n洒能无已已，诗岂去非非。\n仰面楚天过，浮云似白衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬黄帝锡见和' AND p.poem_author = '张埴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('劝穑', '陈忠平', '当代', '麻鞭水响节时催，陌煖庆云团作堆。岸柳垂腰先好雨，池蛙鼓舌自春雷。\n\n新颁农政称咸善，旧凿山渠起积隤。劝穑原该专吏责，田家笑讶子胡来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '劝穑' AND p.poem_author = '陈忠平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('衡阳庞居士庵', '释智愚', '宋代', '居士当年错用心，浑家不睦到如今。\n摝篱柄短无人买，空自萧萧风满林。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '衡阳庞居士庵' AND p.poem_author = '释智愚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江楼秋望', '朱高炽', '明代', '远碧接天涯，登临景自佳。\n蘋洲晴亦雪，枫岸昼常霞。\n落雁过前浦，浮鸥傍浅沙。\n竹篱高晒网，茅屋是渔家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江楼秋望' AND p.poem_author = '朱高炽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('客邸书怀寄慈伽五羊 其三', '李洸', '近代', '一担黄卷一疲驱，两鬓飘萧酒一壶。为问乐天何所乐，出山还解在山无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '客邸书怀寄慈伽五羊 其三' AND p.poem_author = '李洸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题习编修梅坡卷', '金幼孜', '明代', '种得梅千树，盈盈雪满坡。捲帘疏影乱，拂席暗香多。\n\n东阁临风玩，西湖载酒过。高情政如许，赋罢一高歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题习编修梅坡卷' AND p.poem_author = '金幼孜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄沈大本', '谢晋', '明代', '幕府门西初见时，一言投分即相知。几年别去身多难，今日归来鬓有丝。\n\n茂苑江山皆旧恨，小齐卮酒总新期。何缘蠲了遐方戍，长共吟窗计较诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄沈大本' AND p.poem_author = '谢晋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽王柳州', '程珌', '宋代', '才华唐令君，名胜晋参军。\n善政流郴水，遗风袭缙云。\n宝钗当自合，神剑不中分。\n心折白岩路，猿吟日未曛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽王柳州' AND p.poem_author = '程珌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答李希淳屯田三首', '邵雍', '宋代', '竹间水际情怀好，月下风前意思多。\n洛社过从无事日，非吾数辈更谁何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答李希淳屯田三首' AND p.poem_author = '邵雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽方君政', '陶安', '明代', '大化何茫茫，生死等朝暮。见面未几何，幽明已殊路。\n\n人皆劝君仕，况未年迫暮。哀哉万里行，朝命惜虚付。\n\n虽有善教才，不得一远布。六旬命非促，岂不见晞露。\n\n知命俭亦乐，闻道死乃安。平生嗜欲薄，既逝魂气完。\n\n念昔久缔交，文饮意屡欢。握手龙墀上，天风飒高寒。\n\n归来忽永诀，不复其杯盘。盖棺事始定，长夜嗟漫漫。\n\n云间九华秀，君心岂能忘。亲朋亦别久，终不返故乡。\n\n诸孤泣诉我，我亦泪浪浪。东风三月暮，送柩出泮庠。\n\n归舟驾言发，佳城在青阳。所期贤子孙，勉嗣先业光。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽方君政' AND p.poem_author = '陶安';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谒金门·风雨後', '黄机', '宋代', '风雨後。枝上绿肥红瘦。乐事参差团不就。一春如病酒。楼外暖烟杨柳。忆得年时携手。燕子双双来未久。颇知人意否。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谒金门·风雨後' AND p.poem_author = '黄机';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂忆诗 其三', '凌义渠', '明代', '夏日初长最泥人，半瓯擎到强沾唇。年来守净诚何意，蔬笋无多引箸频。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂忆诗 其三' AND p.poem_author = '凌义渠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送刘信之分教云阳', '萧显', '明代', '宫漏催残欲曙天，儒官辞阙向西川。过家白发怜亲老，分教青衿得士贤。\n\n舟出九江春见雁，道经三峡晓闻鹃。吾乡自昔多才俊，师席声华到日边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送刘信之分教云阳' AND p.poem_author = '萧显';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('棠溪宴集赠使君', '严嵩', '明代', '佳游历松郡，雅集过棠溪。碧筱临池净，垂藤入径迷。\n\n林香花代发，庭曙鸟先啼。画省班赏接，沧洲影独栖。\n\n行春人吏惬，听雨客怀悽。野沃饶粳稻，时平撤鼓鼙。\n\n文叨下客会，尊喜使君携。稍学泉上钓，言留竹下题。\n\n兴幽忘去棹，烟景在林西。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '棠溪宴集赠使君' AND p.poem_author = '严嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词 其七十五', '张公庠', '宋代', '太皞祠坛数级红，青旂摇曳日朦胧。人间未觉东风至，先入宜春小院中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词 其七十五' AND p.poem_author = '张公庠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和潞公游天章楚谏议园宅', '司马光', '宋代', '名卿新治第，上宰旧连墙。\n槐荫青青叶，星邻两两光。\n林花裂锦狭，门路筑沙长。\n共引庭间水，交生壁外篁。\n鱼窥芦琴石，萤散读书床。\n玉帐方怀远，松斋欲就荒。\n旌幢今少憩，兰惠不徒芳。\n早晚平狼望，同来举寿觞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和潞公游天章楚谏议园宅' AND p.poem_author = '司马光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('平山堂杂言', '梅尧臣', '宋代', '芜城之北大明寺，辟堂高爽趣广而意厖。\n欧阳公经始曰平山，山之迤逦苍翠隔大江。\n天清日明了了见峰岭，已胜谢朓龊龊远视於一窗。\n亦笑炀帝造楼摘星放萤火，锦帆落樯旗建杠。\n我今乃来偶同二三友，得句欲霜锺撞。\n却思公之文字世莫双，举酒一使长咽慢肌高揭鼓笛腔，\n万古有作心胸降。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '平山堂杂言' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满庭芳·佑国雄才', '王丹桂', '元代', '佑国雄才，皇家贵戚，御恩守镇平山。一方安堵，何幸感怡颜。视众犹同赤子，宽刑宪、矜恤愚顽。无私曲，政声流美，应遍满人寰。公馀，重积德，投诚奉教，使保心闲。又远蒙见召，祗建灵坛。醮谢诸天圣众，仗青裙、开启阴关。从今后，高真降鉴，名系上仙班。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满庭芳·佑国雄才' AND p.poem_author = '王丹桂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('芍药图', '凌云翰', '元代', '十载杨州锦怅遮，红红白白斗繁华。人生总被春瞒却，元是山中药草花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '芍药图' AND p.poem_author = '凌云翰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('经故洛城', '王贞白', '唐代', '卜世何久远，由来仰圣明。山河徒自壮，周召不长生。 \n 几主任奸谄，诸侯各战争。但馀崩垒在，今古共伤情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '经故洛城' AND p.poem_author = '王贞白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饯台倅王司令几叔参釐天府', '林表民', '宋代', '黼坐颁泥检，黄图驾玉星。自应摅学业，端不藉门庭。\n\n冻日湖梅白，春风院柳青。从今亨路去，台岭记曾经。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饯台倅王司令几叔参釐天府' AND p.poem_author = '林表民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('任德广通判拉游长松以诗见贻次其韵 其三', '李流谦', '宋代', '已成倦鸟不知还，碌碌无奇合抱关。五斗未供鸡鹜饱，一身长占簿书间。\n\n何妨使我留东阁，久自从公仰泰山。佳句传来浑舍喜，亟将病目洗斓斑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '任德广通判拉游长松以诗见贻次其韵 其三' AND p.poem_author = '李流谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送仙游知县许延评', '李觏', '宋代', '策名曾未几，奋迅出埃尘。陋巷潜心久，亨衢得意新。\n\n君恩方责报，民业近多贫。莫学悠悠者，谋身不为人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送仙游知县许延评' AND p.poem_author = '李觏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏题山庵二首 其二', '刘克庄', '宋代', '封高四尺宁从险，穴锢三泉岂不愚。客过唐陵悲石马，盗穿秦冢得金凫。\n\n蛩吟不必人歌挽，鸡絮那无客吊孤。自作铭诗差实录，免教人谤退之谀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏题山庵二首 其二' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠黄比部玉阶二章 其二', '姚燮', '清代', '峤疋文章守瓣香，颇多清怨匿潇湘。立身为鹤玉同洁，得气先兰春自芳。\n\n颇愿还山谋种溉，最难入世等潜藏。客中吾有南携秫，留待君閒静试尝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠黄比部玉阶二章 其二' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉答吴殿丞见赠', '韩维', '宋代', '势利跃谄子，声名走夸儿。\n我于二无一，世固背以驰。\n君从江海来，面有潇洒姿。\n朝廷多旧游，绝迹不复追。\n足音三及门，乃得众所遗。\n长篇烂盈目，清远谬见推。\n将非乐间放，独与静者宜。\n何以谢嘉况，湖山有前期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉答吴殿丞见赠' AND p.poem_author = '韩维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过安陆州', '王缜', '明代', '片帆非汉川，北风迎秋景。烟澹石城高，记得古名郢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过安陆州' AND p.poem_author = '王缜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感兴其六', '李白', '唐代', '嘉谷隐丰草。\n草深苗且稀。\n农夫既不异。\n孤穗将安归。\n常恐委畴陇。\n忽与秋蓬飞。\n鸟得荐宗庙。\n为君生光辉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感兴其六' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送黎秘书惟敬得请致仕二首 其一', '欧大任', '明代', '贤声此去有辉光，万里桥西一草堂。殊锡曾为大司马，老儒不用尚书郎。\n\n青鞋布袜从此始，行酒赋诗殊未央。朱绂即当随綵鹢，青春作伴好还乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送黎秘书惟敬得请致仕二首 其一' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('萱草', '刘过', '宋代', '不尽人间万古愁，却评萱草解忘忧。\n开花若总关憔悴，谁信浮生更白头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '萱草' AND p.poem_author = '刘过';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔父词一十八首 玄用', '吕岩', '唐代', '日月交加晓夜奔，昆崙顶上定乾坤。真镜里，实堪论，叆叆红霞晓寂门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔父词一十八首 玄用' AND p.poem_author = '吕岩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨中湖上晚归书所见三绝句 其二', '周紫芝', '宋代', '谁家歌管载凉州，何处跳珠入柂楼。山雨忽随云渡岭，明眸还与水争愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨中湖上晚归书所见三绝句 其二' AND p.poem_author = '周紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陆子逸惠桃花戏赠', '韩元吉', '宋代', '故人招我千山里，也有仙葩巧送春。\n麝馥染衣金缕重，酒红生粉玉肌匀。\n洛城景物知谁纪，寒食风光独处新。\n莫把天香调行客，晓妆留与绿窗人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陆子逸惠桃花戏赠' AND p.poem_author = '韩元吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('依韵奉和司徒侍中安正堂观牡丹', '强至', '宋代', '独王花天晚自开，群芳臣妾漫争媒。\n金刀几度裁云叶，玉席多情向斗魁。\n檀口似迎迟日笑，香心肯逐疾风颓。\n相君造化春工手，写入新诗意更瑰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '依韵奉和司徒侍中安正堂观牡丹' AND p.poem_author = '强至';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢公定和二范秋怀五首邀予同作', '黄庭坚', '宋代', '四会有黄令，学古著勋多。\n白头对红叶，奈此摇落何。\n虽怀斲鼻巧，有斧且无柯。\n安得五十弦，奏此寒士歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢公定和二范秋怀五首邀予同作' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小重山 其二', '何振岱', '清代', '频岁家居多往还。晴窗常共饭，小盘桓。如何半月隔容颜。\n\n些儿路，远比几重山。\n\n且莫皱眉湾。朝朝询翠竹，报平安。千丝茧绪尽须删。\n\n萧清地，换了寸心闲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小重山 其二' AND p.poem_author = '何振岱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠通州守张聚徵', '孙继皋', '明代', '身都千骑领东方，海国行春满路光。人自楚材来郢上，名同汉吏起渔阳。\n\n重歌麦垄双岐似，旧憩棠阴百里强。共道下车偏得岁，却愁天阙去含香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠通州守张聚徵' AND p.poem_author = '孙继皋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('襄国王飞教千里岁一慰存野人无以仰酬惟祝麟趾之庆而已敬成四绝情见乎辞 其四', '王世贞', '明代', '老病蒙庄五亩阴，年年孤负楚王金。虽然曳尾泥涂乐，未少衔珠一片心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '襄国王飞教千里岁一慰存野人无以仰酬惟祝麟趾之庆而已敬成四绝情见乎辞 其四' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百一十七首', '释绍昙', '宋代', '拄杖子，黑粼皴。\n韬藏头角，枯槁身心。\n刚被业风飘鼓，忙忙入草寻人。\n奔驰鸟道，簸弄驴唇。\n湖海听闻齐掩耳，只宜藏拙古岩阴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百一十七首' AND p.poem_author = '释绍昙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答黄仲贞老先生见寄 其二', '郑真', '明代', '淮天久客思漫漫，风雪那禁二月寒。江海愁吟怜杜老，林山僵卧隐袁安。\n\n故园风物烦相问，上国光华许共看。桃李已传春蓓蕾，多情休惜蚁樽干。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答黄仲贞老先生见寄 其二' AND p.poem_author = '郑真';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春半', '薛嵎', '宋代', '春半数风雨，水村增晓寒。\n不辞蓑笠重，自觉起居安。\n隔雾山疑失，占晴礎未乾。\n可怜桃与李，无语受摧残。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春半' AND p.poem_author = '薛嵎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('效阮公诗', '江淹', '南北朝', '夕云映西山。\n蟋蟀吟桑梓。\n零露被百草。\n秋风吹桃李。\n君子怀苦心。\n感慨不能止。\n驾言远行游。\n驱马清河涘。\n寒暑更进退。\n金石有终始。\n光色俯仰间。\n英艳难久恃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '效阮公诗' AND p.poem_author = '江淹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梧叶儿·鸦鬓春云亸[1]', '徐再思', '元代', '鸦鬓春云亸[1]，\n象梳秋月欹，\n鸾镜晓妆迟。\n香渍青螺黛，\n盒开红水犀，\n钗点紫玻璃：\n只等待风流画眉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梧叶儿·鸦鬓春云亸[1]' AND p.poem_author = '徐再思';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('散郎亭', '苏轼', '宋代', '法花下有散郎亭，老树荒崖如有情。\n欢戚已随时事去，壁间只有古人名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '散郎亭' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雉子曲二章 其一', '孙一元', '明代', '花叶正田田，雉子行哺雏。锦翚覆满身，相顾还相呼。\n\n圣人在位民用和，只今四海无网罗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雉子曲二章 其一' AND p.poem_author = '孙一元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆瑶姬 吴湖帆', '吴梅', '近代', '金碧侯门，闭小冢，红心草满三弓。容光销镜月，纵瘗花铭在，弹指春风。\n\n玉儿幸死东昏，未籍青衣禁苑中。笑锦帆流落天涯，暮鸦枯树冷隋宫。\n\n石华乍启尘封，故纸千金，几番江汉传烽。河山馀艳影，对旧朝文物，细想惊鸿。\n\n秋魂莫怨杨花，一研南薰墨正融。伴海滨巾角临池，夜月环佩逢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆瑶姬 吴湖帆' AND p.poem_author = '吴梅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('燕京迁居城南次韵答张鸿与伦绍周见讯 其一', '欧大任', '明代', '碣石宫前偶卜居，都亭奏记未堪书。上林亦有相如赋，五色云中望玉舆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '燕京迁居城南次韵答张鸿与伦绍周见讯 其一' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闲游', '苏葵', '明代', '随柳傍花我，吟风弄月谁。眼赊图画迥，意远杖藜迟。\n\n雪重松明叶，云深竹没枝。忘言当此际，争敢强成诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闲游' AND p.poem_author = '苏葵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('【正宫】端正好　金钱问卜', '刘庭信', '元代', '香尘暗翠帏屏，花露冷鲛绡帐，闷恹恹画阁兰堂。愁云怨雨风流况，都蹙在\n眉尖上。\n　　【滚绣球】俏风流窈窕娘，俊庞儿浅淡妆，扫蛾眉远山新样，穿一套藕丝衣\n云锦仙裳，带一别珠珞索玉项牌。翠氍毹宝串香，打扮的一桩桩停当，步瑶阶环\n玎。溶溶月色浸朱户，寂寂花阴付粉墙，春色芬芳。\n　　【倘秀才】展玉腕把春纤合掌，恰便似白莲蕊初生在这藕上，高卷珠帘拜月\n光。碧梧摇碎影，红药吐狂香，正红稠绿穰。\n　　【滚绣球】启绿窗离了绣房，博山炉把香来拈上，办着片志诚心祷告穹苍，\n低低的念了一会，深深的拜了四方。转秋波又则怕外人偷望，则为咱正青春未配\n鸾凰。甚时得遇乘鸾客？何日相逢傅粉郎？审问个行藏。\n　　【倘秀才】磨着定乌龙墨向端溪砚傍，援着管玉兔笔写在罗纹纸上，恰便似\n破八卦桃花女计量。五行推造化，六甲定兴亡，沉吟了半响。\n　　【呆骨朵】厮琅琅的把金钱掷下观爻象，却怎生单单单拆拆拆阴阳？恰数着\n坤偶乾奇，摆列着天三地两。用神有天喜临，主令的财官旺，便做道是李淳风不\n顺情，那一个袁天罡肯调谎。\n　　【货郎儿】一见了神魂飘荡，不由我心劳意攘。我将这金钱仔细细推详，恰\n离了湖山侧，早来到会宾堂。\n　　【脱布衫】明滴溜月转西厢，锦模糊花暗东墙。何处也花烛洞房？那里也锦\n衾罗帐？\n　　【小梁州】昨日个孔雀屏开绛蜡光，花吐银。早间灵鹊噪回廊，蛛丝儿放，\n滴溜在宝钗傍。\n　　【幺篇】卦爻儿端的无虚诳，莫不是会双星日吉时良？这的是好事成从天降，\n佳期准望，何必再斟量？\n　　【醉太平】打叠起麻衣百章，《周易》《归藏》，下工夫想绣个锦香囊，则\n在这香盒儿里供养。准备着梨花月底双歌唱，杏花楼上同玩赏，再不支菱花镜里\n巧梳妆，眠思梦想。\n　　【煞尾】眠思梦想，悲楚凄凉，再不去花月亭前烧夜香。\n　　【南吕】一枝花　秋景怨别\n　　金风送晚凉，玉露消残暑，素蟾光皎洁，丹桂影扶疏。鬼病揶揄，空把光阴\n负，暮秋深天气肃，寒浸罗襦，一阵阵相思透骨。\n　　【梁州】凄凉境一遭儿摆布，相思阵十面埋伏。那些儿感起我这伤情处。乱\n纷纷残花病菊，滴溜溜败叶凋梧。疏刺刺风摇翠竹，淅零零雨洒荒芜。意痴痴感\n叹嗟吁，冷清清一弄儿萧疏。怕的是枯荷缺处添黄，衰柳凋时减绿，丹枫老也涂\n朱。对对，付付。支吾过白日离愁去，淹的早碧天暮。咚的黄昏一声鼓，好教我\n魂魄全无。\n　　【骂玉郎】愁来愁到无穷处，割不断愁肠肚。撇下这病身躯，割舍了魂灵向\n梦里寻他去。梦和魂休间阻，魂和梦却对付，天也与人一个囫囵的做。\n　　【感皇恩】呀，原来是梦境虽虚，暂时完聚。半成不就梦儿单，半明不灭灯\n儿暗，半死不活影儿孤。画檐间玎玎追魂的玉马，戍楼上点点滴滴索命铜壶。\n钟声罢，砧声切，雁声无。\n　　【采茶歌】雁儿，往常时趁程途，盼江湖，且是的悲悲切切语喧呼。今夜毛\n团为甚不言语，知他你那答儿里错下了断肠书。\n　　【尾声】惊回残梦添凄楚，无奈秋声最狠毒。风声忧，雨声怒，角声哀，鼓\n声助。一声听，一声数，一声愁，一声苦。投至的风声宁，雨声住，角声绝，鼓\n声足。又被这一声钟撞我一口长吁，则我这泪点儿更多如窗外雨。　咏别\n　　凤台宝鉴分，锦瑟冰弦断。丹青歌扇歇，金缕舞衣宽。娇凤雏鸾，愁与闷难\n思算，闷和愁几样般。百千张锦纸花笺，一万枝霜毫象管。\n　　【梁州】写不尽海来深闲愁荏苒，天来高离恨弥漫，眼交光景愁无乱。海棠\n红瘦，扬柳眉攒。丁香未结，梅子先酸。下香阶独立盘桓，怕黄昏鸦噪林峦。上\n上灯对影成双，下下帘和谁作伴？开开窗对月团。美满，旧欢。胸中锦绣三千\n段，心剔透，性和暖。比掷果知音不姓潘，表正容端。\n　　【骂玉郎】兰堂失却风流伴，倦刺绣懒描鸾，金钗不整乌云乱。情深似刀刃\n剜。愁来似乱箭攒，人去似风筝断。\n　　【感皇恩】口则说应举求官，多因是买笑追欢。从今后鸳梦儿再休完，鱼书\n儿都休寄，龟卦儿也休钻。离愁万般，心绪多端。芳草迷烟树，落花催雨点，香\n絮滚风团。\n　　【采茶歌】阳台上路盘桓，蓝桥下水弥漫。倚楼一倚一心酸，空忆当时花烂\n熳，可怜今夜月团。\n　　【尾声】蝇头风月如堆卵，鸡肋恩情似滚丸。枕上余香被窝中春暖，有人知\n无人管。往常时信音通直恁情欢，到如今鸾信少雁书稀鸳梦短。　春日送别\n　　丝丝杨柳风，点点梨花雨。寸随花瓣落，风趁柳条疏。春事成虚，无奈春归\n去。春归何太速？试问东君：谁肯与莺花做主？\n　　【梁州】锦机摇残红扑簌，翠屏开嫩绿模糊。茸茸芳草长亭路，乱纷纷花飞\n园圃。冷清清春老郊墟，恨绵绵伤春感叹，泪涟涟对景踌蹰。不由人不感叹嗟吁，\n三般儿巧笔堪图。你看那蜂与蝶趁趁逐逐，花共柳攒攒簇簇，燕和莺唤唤呼呼。\n鹧鸪，杜宇。替离人细把柔肠诉，愁和泪一时住。不由我相思泪如雨，怎教宁耐\n须臾？\n　　【骂玉郎】叫一声才郎身去心休去，不由我愁似铁、泪如珠，樽前无计留君\n住。魂飞在离恨途，身落在寂寞所，情递在相思铺。\n　　【感皇恩】呀，则愁你途路崎岖，鞍马上劳碌。柳呵都做了断肠枝，酒呵难\n道是忘忧物？人呵怎减的护身符？早知你抛掷咱应举，我不合惯纵的你读书。伤\n情处，我命薄，你心毒！\n　　【采茶歌】觑不的献勤的仆、势情的奴，声声催道误了程途。一个大厮把的\n忙牵金勒马，这一个悄声儿回转画轮车。\n　　【隔尾】江湖中须要寻一个新船儿渡，宿卧处多将些厚褥子儿铺。起时节迟\n些儿起，住时节早些儿住。茶饭上无人将你顾觑，睡卧处无人将你盖覆，你是必\n早寻一个着实店房里宿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '【正宫】端正好　金钱问卜' AND p.poem_author = '刘庭信';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵李久善近诗四首', '郭印', '宋代', '高人来折节，不免稻粱谋。\n排闷唯诗卷，消愁只茗瓯。\n此时同幕府，何日共仙舟。\n气味难相得，逢君写我忧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵李久善近诗四首' AND p.poem_author = '郭印';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆王庵旧游寄再生', '神一', '清代', '人生聚散本浮沤，回首苍茫感昔游。晓露未收花力重，午阴欲定鸟声幽。\n\n闻香小坐忘尘世，步月清言扫旧愁。梅影横斜应似画，残英满地有谁收。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆王庵旧游寄再生' AND p.poem_author = '神一';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夕次寿阳驿题吴郎中诗后', '韩愈', '唐代', '风光欲动别长安，春半城边特地寒。 \n 不见园花兼巷柳，马头惟有月团团。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夕次寿阳驿题吴郎中诗后' AND p.poem_author = '韩愈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别殷市隐 其二', '罗洪先', '明代', '结托意方勤，时变倏如驰。凉飙动庭户，游子有所思。\n\n浮云乘刚风，欲留不得迟。眷眷平生交，愿言常如兹。\n\n悠悠逆旅间，再晤须何时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别殷市隐 其二' AND p.poem_author = '罗洪先';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏题四老堂十首 其一', '张守', '宋代', '四老堂中四老人，饱经丧乱始收身。苍颜鹤发团栾坐，知是时平有幸民。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏题四老堂十首 其一' AND p.poem_author = '张守';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题马竹所画', '虞集', '元代', '霜清木落江海空，一棹归来何处翁。双松千岁如铁石，为尔回薄旋天风。\n\n忆昔神龙剑所化，夕卧沧波弄明月。望中冉冉云气生，直接银河上琼阙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题马竹所画' AND p.poem_author = '虞集';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('参政宣献楼公挽歌辞', '史弥宁', '宋代', '耆英续续必重泉，好在灵光独岿然。\n入侍已成鸿鹄羽，退休俄值白鸡年。\n伤心藏笈书无恙，盥手开缄墨尚鲜。\n刮目相期良不薄，可无斗酒奠桥玄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '参政宣献楼公挽歌辞' AND p.poem_author = '史弥宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂六十五首 其四', '释咸杰', '宋代', '久雨忽晴，天清地宁。寒山抚掌，拾得忻忻。恁么会得，旱地遭钉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂六十五首 其四' AND p.poem_author = '释咸杰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('唐李卫公庙', '宋祁', '宋代', '斯人天挺杰，贼胆畏膏肓。\n疾战江陵破，长驱颉利亡。\n成功在不伐，垂烈付无疆。\n血食雄京辅，于今异姓王。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '唐李卫公庙' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王屋山和颜侍御', '林大春', '明代', '孤标特立紫云中，千古名山隐华嵩。夜静风霜随宝剑，秋高星斗映珠宫。\n\n天坛日出沧溟小，太乙烟开河汉空。更有群仙齐献寿，依稀鸣佩月华东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王屋山和颜侍御' AND p.poem_author = '林大春';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('端午帖子九首 其三', '曹勋', '宋代', '辟兵龙印篆神经，系臂香萦绣色轻。自有微凉生玉宇，池光静照午阴清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '端午帖子九首 其三' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('相见欢 其二', '钱斐仲', '清代', '听莺听燕听蛩。听征鸿。听到落花时节、雨兼风。\n\n魂梦乱。春已半。未相逢。可是人生长在、别离中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '相见欢 其二' AND p.poem_author = '钱斐仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻谢阁老休致过苏遥寄', '沈周', '明代', '五十悬车事异常，符阶纶阁迥天光。千秋国是黄金鉴，一夜乡心绿野堂。\n\n漫赋祁招惟自止，旧图负扆敢云忘。拔风后起梧桐树，四海还瞻老凤凰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻谢阁老休致过苏遥寄' AND p.poem_author = '沈周';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('因览仰山小释迦语成唱道二首', '释正觉', '宋代', '一念全超旷劫初，玉人端坐白牛车。\n往来历尽傍参妙，回首途中物物渠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '因览仰山小释迦语成唱道二首' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自蓉赴滇访溪洛渡水电站夜宿三坪营地', '熊东遨', '当代', '载得蜀山青，联车向溪洛。生凉松月高，炫紫岭云薄。\n\n一水出西南，千秋感寥落。岂无璀璨心，但少光明脚。\n\n澹荡空余情，劣顽时见恶。恰逢皇禹招，便作苍冥跃。\n\n驭电行八荒，施霖润阡陌。已知黎庶艰，自守升平约。\n\n其奈世间人，临流只相索。翻思上古音，按谱多成错。\n\n开济尚能任，沉浮安可托？曾闻先哲言：万物主有各。\n\n顺取神或予，逆收鬼难诺。慎持天地衡，毋夺儿孙乐。\n\n秉此对沧江，分甘宜小勺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自蓉赴滇访溪洛渡水电站夜宿三坪营地' AND p.poem_author = '熊东遨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丛林三首 其一', '卢青山', '当代', '丛林深峻竹，远涧淡寒烟。屈草秋生凛，回霜路欲淹。\n\n鸦归衔细杪，雁去画长天。日暮嗟游子，荷囊问舍檐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丛林三首 其一' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏题钱守宋汉杰泉岩古刹', '程俱', '宋代', '广文斗酒邀同襟，胸中嵩衡郁千寻。醉来盘礴吐幽怪，惨澹崖谷森相临。\n\n向来三绝信珠璧，肯用抵鹊荆山岑。诗中有画画中句，两峰高并蓝田阴。\n\n祇应摩诘可方驾，老向海角嗟英沉。何人左手作右字，题此古刹藏烟林。\n\n不知眼力尚能尔，叠嶂巃嵷穷幽深。使君家世旧湖海，戏假尺素资讴吟。\n\n更登日观望八极，中有山水无穷音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏题钱守宋汉杰泉岩古刹' AND p.poem_author = '程俱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舞阳令祝乐天再任', '李廌', '宋代', '庚寅十月二十五，晓分黑帝临丹府。\n怒来鞭掠玉麒麟，下降英灵佐明主。\n庐江从此生奇贤，便是奇人祝乐天。\n鼎沸弦歌一百里，双凫舞水又三年。\n部民共献长生酒，鸾鹤庄椿只依旧。\n我咏蟠桃别有春，何须更祝人间寿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舞阳令祝乐天再任' AND p.poem_author = '李廌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天 悼亡', '周贻繁', '清代', '庭树声清秋意生。西风吹恨入银屏。十年行止如丝缚，三载情怀空泪倾。\n\n香未觅，赋难成。人间天上不分明。待看化鹤归来日，同奏楼头红玉笙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天 悼亡' AND p.poem_author = '周贻繁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绛都春 赋壶园雁来红', '郑文焯', '清代', '鹃魂一片。怪小墅绿阴，都被愁染。鸿阵悄来，凄紧西风黄昏院。\n\n茜裙残缕吹香远。却醉入、秋娘心眼。梦回沟水，红情自老，误他题怨。\n\n还见。披烟浣露，正灯暗绛屏，和泪妆点。霜信曼催，吴锦飘零无人剪。\n\n可怜生是江南晚。更解替、幽花肠断。几回立尽斜阳，故山冷艳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绛都春 赋壶园雁来红' AND p.poem_author = '郑文焯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偃王城', '张耒', '宋代', '蔓草悲风知几秋，黄桑晚叶野云愁。偃王城下樵苏尽，犹有耕人指旧丘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偃王城' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('稚桐', '张仲深', '元代', '分得灵根自峄阳，亭亭翠干及人长。莫辞拱把当风露，他日终经宿凤凰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '稚桐' AND p.poem_author = '张仲深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送章允明赴山西佥宪', '吴伯宗', '明代', '琪树分阴日已凉，之官万里趣行装。塞鸿南向风云迥，宛马西来道路长。\n\n水落石汧秋漠漠，山连秦陇树苍苍。远人互市心愉悦，共沐皇恩雨露香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送章允明赴山西佥宪' AND p.poem_author = '吴伯宗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏日', '寇准', '宋代', '离心杳杳思迟迟，深院无人柳自垂。\n日暮长廊闻燕语，轻寒微雨麦秋时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏日' AND p.poem_author = '寇准';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红', '卢青山', '当代', '莽雨如何？正难夺、万山老碧。况孤鸟、横空侧转，一声长唧。\n\n得似诗中须李白，陡然来去无寻迹。问渊明、识得此中云，破石立？\n\n攀崖树，摩天壁，雁摧回，猿愁白。使辛公见此，必为狂哑。\n\n唤剑囊中休寂寞，此时何不逞挥斥？尔见乎？振涧起长风，推山急。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄陈履吉', '沈野', '明代', '故人闽海结茅堂，海上相思更渺茫。\n地气未春先见草，山风迎腊不飞霜。\n林深采药窥猿啸，田熟开书觉稻香。\n我欲移家同避世，可能白发老沧浪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄陈履吉' AND p.poem_author = '沈野';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卢沟桥抗战纪事 其七', '王冷斋', '近代', '消息传来待折冲，当时尚冀息狼烽。谁知一勺扬波起，故道夷兵忽失踪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卢沟桥抗战纪事 其七' AND p.poem_author = '王冷斋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('景帝', '郭之奇', '明代', '君如汉景真残矣，幸承文绪资前美。吴楚深机谁故挑，晁周为国同诛死。\n\n赐几初销反侧心，争博翻教逆萌始。家令峭直而刻深，以刻逢君应自抵。\n\n刘氏未安晁氏危，智囊此日愚谁似。当年事急倚何人，坚壁轻骑夷叛垒。\n\n漫持侯约阻非功，岂知鞅鞅还相訾。可怜父子并殊勋，同相同侯同系累。\n\n安刘惟勃将惟夫，刘氏既安周氏毁。父得絮提缘主存，子终欧血因梁委。\n\n君不见传弟从容繇易言，疏婴刺盎几嚣烦。本谋何必尽羊孙，田叔烧辞乃坐飧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '景帝' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('连日寒甚强甫二首', '刘克庄', '宋代', '人生各有稻粱谋，暂去家庭作远游。\n年事但看翁齿发，天寒深念汝衣裘。\n履霜我独知琴操，立雪谁来问话头。\n但愿茅檐相保守，千书说不尽离愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '连日寒甚强甫二首' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('僧志月碧云轩改为景云轩因书二首 其一', '李觏', '宋代', '长见江淹杂体诗，碧云非是惠休词。试言日暮佳人怨，何事高僧却得知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '僧志月碧云轩改为景云轩因书二首 其一' AND p.poem_author = '李觏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '司马光', '宋代', '藏阄新度腊，习舞竞裁衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '司马光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九怀·浙水府', '高似孙', '宋代', '越山兮青青，江波兮喷薄。\n万里兮长风，引惊澜兮去之。\n夫君兮以渊为期，水何为兮劳苦。\n越山兮升云，江水兮未平。\n举酒兮讯君，将与余兮心倾。\n若有人兮飐云旗，舞神鱼兮踏文螭。\n奏水星兮叫冰夷，横壮气兮海为飞。\n麋台兮生草，言如毛兮人杲杲。\n夕宿兮江皋，越兵西兮如拉搞。\n一沐浴兮九江，水扬波兮淙淙。\n飞科桡兮雁渚，舍余珰兮渔缸。\n望美人兮未来，心不怡兮难降。\n有酒兮如冰，呼脍具兮鱼龙腥。\n浇大块兮海鲜磅礴，有老父兮愁偏醒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九怀·浙水府' AND p.poem_author = '高似孙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨中柬文玉 其一', '邵宝', '明代', '雨中闭阁自焚香，门外诗来故故忙。梦里风骚犹远在，却教白日破羲皇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨中柬文玉 其一' AND p.poem_author = '邵宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送顾伯刚令馀姚一首', '黄省曾', '明代', '新擢侍含香，还除花县郎。近霄分帝泽，成宿接天光。\n\n北出薇垣外，南移牛女傍。他时想凫舄，遥瞩海霞长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送顾伯刚令馀姚一首' AND p.poem_author = '黄省曾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹醉日', '晏殊', '宋代', '苒苒渭滨族，萧萧尘外姿。\n如能乐封殖，何必醉中移。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹醉日' AND p.poem_author = '晏殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金门歌送苏叔大入京', '欧大任', '明代', '君不见金马门，交疏结绮拱朱轩。云里天垂丹凤阙，星前霞映紫微垣。\n\n岧峣三殿当空起，日华东照明光里。双茎露掌直南山，片石虹桥临渭水。\n\n门开宦署只罘罳，摇佩鸣珰待诏时。白虎持经决同异，柏梁受简连歌诗。\n\n苏生珊瑚枝，少小芙蓉锷。刀布不肯赍，自谙太常学。\n\n蛾习春弦拥蕙帷，蠹窥冬简扃芸阁。千金狐裘五丝鞭，一朝大笑长安乐。\n\n于今西北是长安，驿楼官树向桑乾。骅骝蹀躞风鬃动，雕鹗凭淩雪羽搏。\n\n三千奏牍金门入，深山蒿庐更簪黻。大官梁肉频被赐，尚方笔札行当给。\n\n建章驺牙重栎新，混邪十万将来臣。汉庭莫哂酣歌客，也有东方谏猎人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金门歌送苏叔大入京' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('甘泉青霞书院用白沙韵', '王渐逵', '明代', '洞古飞霞迥，峰高万壑临。榛蒙嗟此道，开辟见吾心。\n\n蕙帐鹤长守，春堂花自深。山灵如听讲，故故簇幽岑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '甘泉青霞书院用白沙韵' AND p.poem_author = '王渐逵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂曲歌辞。桂花曲', '佚名', '唐代', '可怜天上桂花孤，试问姮娥更要无。 \n 月宫幸有闲田地，何不中央种两株。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂曲歌辞。桂花曲' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和沈交韩王觉民韵', '王之道', '宋代', '二公才致同清壮，顾我无能但蕲向。\n只今连璧复有谁，伯仲未可轻第行。\n小人老矣病且衰，目光近在牛背上。\n何当策蹇拟高谈，岁晚寒云连雪障。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和沈交韩王觉民韵' AND p.poem_author = '王之道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('《归来引》送王子立归筠州', '苏轼', '宋代', '归去来兮，世不汝求胡不归？汹北望之横流兮，渺西顾之尘霏。\n\n纷野马之决骤兮，幸余首之未鞿。出彭城而南骛兮，眷丘陇而增欷。\n\n乱清淮而俯鉴兮，惊昔容之是非。念东坡之遗老兮，轻千里而款余扉。\n\n共雪堂之清夜兮，揽明月之馀辉。曾鸡黍之未熟兮，叹空室之伊威。\n\n我挽袖而莫留兮，仆夫在门歌《式微》。归去来兮，路渺渺其何极。\n\n将税驾于何许兮，北江之南，南江之北。于此有人兮，俨峨峨其丰硕。\n\n孰居约而尔肥兮，非糠窍其何食。久抱一而不试兮，愈温温而自克。\n\n吾居世之荒浪兮，视昏昏而听默默。非之子莫振吾过兮，久不见恐自贼。\n\n吾欲往而道无由兮，子何畏而不即。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '《归来引》送王子立归筠州' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨后道间见红梅', '施枢', '宋代', '玄都境界玉堂身，轻袅湘裙步晓阻。\n昨夜雨肥添酒晕，红情染得十分深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨后道间见红梅' AND p.poem_author = '施枢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('老而健贫而诗自志其喜八首 其三', '方回', '宋代', '拙宦知今是，颓颜及古稀。寡言为暖药，微醉当寒衣。\n\n空腹蝉当饱，长身鹤肯肥。天容清更健，不省桔槔机。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '老而健贫而诗自志其喜八首 其三' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('田园幽兴六首 其二', '林大钦', '明代', '净心遗纷业，悠志在无为。坐爱窗间草，閒吟梁甫词。\n\n万事嗟牢落，一丘已定居。沧浪濯清足，在昔皆余师。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '田园幽兴六首 其二' AND p.poem_author = '林大钦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠何从之', '张江', '清代', '白驹苍狗两茫茫，吹笛沧洲六十霜。老去伏生双鬓短，饥来臣朔一身长。\n\n青镫尽夜偿文债，补被谁家稳睡乡。莫叹故园松菊冷，袁安曾耐雪中僵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠何从之' AND p.poem_author = '张江';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠别宋仲观', '郭钰', '元代', '梅花江上雪意残，独行远道何当还。大江风微五两静，虚馆日高双陆閒。\n\n十载论交倾意气，一朝送别凋容颜。坐歌激烈我何有，明日射虎归南山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠别宋仲观' AND p.poem_author = '郭钰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('幽兰咏', '王冕', '元代', '光风吹香洗游尘，兰花隐芳莸笑人。\n翠露沉沉玉环冷，忘言坐视空山春。\n几回清梦度荆楚，欲问三闾杳无所。\n空将幽意寄离骚，暮云凄堕湘皋雨。\n古怀潇洒千余年，忠义漫作虚语传。\n人间蜂蝶何翩翩？抚卷对花空自怜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '幽兰咏' AND p.poem_author = '王冕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('听琴篇', '王慎中', '明代', '昔传子春技，弹丝圣入耳。一曲作人情，七弦发妙理。\n\n美人携琴升我床，闲心敏手亦如此。弄奇赴会若有神，朱绳玉轸临风倚。\n\n始作怀沙纵九歌，却调哀郢伤千里。卑张应节发清商，促越更趋引流徵。\n\n楚水看流㩎指间，江风忽奏挥弦里。栖鸟知声中夜翔，潜鱼激响凌波起。\n\n四郊陨叶纷纷下，浮云辞天月在野。瑶徽半拂复中操，宫声少间羽声写。\n\n山鬼依微薜荔裳，宓妃窈窕螭蜺驾。旧闻骚些已潸潸，对此离忧遂不堪。\n\n本听幽音容易感，复兼放迹自曾谙。姱志千秋同夏沔，愁心一夕到湘潭。\n\n恨恨怀荃零泪雨，沾襟不为雍门谈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '听琴篇' AND p.poem_author = '王慎中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('唐介', '王令', '宋代', '以谏得罪者为谁，四海多作唐介诗。\n俗儿口狭文字碎，欲状介事语反卑。\n嗟嗟我亦介之徒，此恨不助掀目眉。\n三更灯死百虑息，四睫不交双目眵。\n推枕起坐壮介节，以手扪臆为介思。\n信乎介亦壮男子，直能金铁其肝脾。\n雷霆之怒万钧重，人主之威犹过之。\n一语所犯百死在，要领可断族可夷。\n堂堂介也人之难，不畏所畏将所持。\n奉书入奏伏文陛，身视赴死如食饴。\n面折庭诤语论险，直舌铁硬坚不移。\n天子怒叱大臣语，众笏交抵侔戈挥。\n如何面笑目不瞬，气不略讋颜怡怡。\n即日议下得远斥，中使临遣监妻儿。\n奈何左右口吻毒，只有死请无还辞。\n然今天子甚明圣，虽暂盛怒终复归。\n呜呼能对治乱监，介也能擦其瑕疵。\n语曰五谏吾从讽，仲尼逮有激而为。\n後世巽懦禄位徒，缘此粉饰尸素非。\n必也事有不得已，宜乎讫死争不回。\n伟哉介也已不朽，日月为字天为碑。\n寄语琐琐媒孽子，介纵蹈死吾何悲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '唐介' AND p.poem_author = '王令';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浪淘沙 其二', '毛奇龄', '清代', '杉木为箄竹作檐。江潮能苦雨能甜。连朝只饮檐头雨，翻道江潮错着盐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浪淘沙 其二' AND p.poem_author = '毛奇龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵怀古 其四', '金天羽', '近代', '鸡呜山顶塌浮屠，十庙功臣俎豆无。一自洪杨开劫运，再令湘楚建雄图。\n\n英雄力尽孤城在，竹帛勋留万骨枯。遗像不登麟阁去，须眉渊映莫愁湖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵怀古 其四' AND p.poem_author = '金天羽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中阁禅院', '留元崇', '宋代', '初来罗浮山，万变骇林壑。\n更作招提游，佳处在中阁。\n忽然天地间，一纵千里目。\n未论云顶上，此景占仍独。\n近闻泉涓涓，青眺山簇簇。\n檐压乔松低。槛有余霞落。\n长风东南来，皓月襟袖薄。\n境静僧幽閒，意远味淡泊。\n抱琴归去来，禅榻寄一宿。\n白云依古山，青霄起孤鹤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中阁禅院' AND p.poem_author = '留元崇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九日留彭泽', '董嗣杲', '宋代', '牢击扁舟在树根，依然风物晋时村。\n几年思采东篱菊，此际狂倾北海樽。\n野鹤离群翔碧落，江鸿排字入黄昏。\n有人若学渊明隐，五柳萧疏静掩门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九日留彭泽' AND p.poem_author = '董嗣杲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬夜读史有感二十首 其九', '连横', '近代', '金陵形势亦岐丰，明社初墟继有洪。半壁山河争逐鹿，八旂子弟化沙虫。\n\n可怜铸错终成铁，未遂铭功竟折铜。太息天亡非战罪，项王虽败总英雄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬夜读史有感二十首 其九' AND p.poem_author = '连横';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠东庵约老', '徐玑', '宋代', '一阁老自建，一庵居在东。\n既然头欲白，不用剃令空。\n门掩春山绿，檐依晓日红。\n玄微知有旨，混在话言中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠东庵约老' AND p.poem_author = '徐玑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠孙生', '李梦阳', '明代', '古人种桃李，不为搴其花。君子振英芬，岂在文与华。\n\n炎阳赫晴彩，百卉流丹霞。蕡彼东园实，累累一何嘉。\n\n采者自成蹊，举世徒咨嗟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠孙生' AND p.poem_author = '李梦阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('襄阳咏史 其三十 沧浪歌', '李俊民', '金朝', '江上扬扬一棹波，众中清浊笑怀沙。不知歌后沧浪曲，却入骚人屈宋衙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '襄阳咏史 其三十 沧浪歌' AND p.poem_author = '李俊民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵曾守立春席上七绝句 其二', '沈与求', '宋代', '晓冻穿流急，晨光照火新。四郊和气合，歌吹待班春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵曾守立春席上七绝句 其二' AND p.poem_author = '沈与求';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古九首', '释普信', '宋代', '寥寥风月卧烟霞，百鸟从兹不献花。\n人义尽从贫处断，世情偏向有钱家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古九首' AND p.poem_author = '释普信';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送胡仲雅南归三首 其二', '王翰', '元代', '郊园秋气薄，征骖方载路。送客上中条，执手话离素。\n\n摇摇千里心，竟以亲爱故。高亭多秋风，假道繁晓露。\n\n念子远行迈，空山日将暮。搔首望江南，高林起烟雾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送胡仲雅南归三首 其二' AND p.poem_author = '王翰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辅上人自京师还遂如海上省觐', '廖大圭', '元代', '万里黄金台上客，白云回首故山深。庭闱岁月催华发，包笠秋风折寸心。\n\n百福起居申定省，三年音信问浮沉。不从客路看明月，身在青青桑梓阴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辅上人自京师还遂如海上省觐' AND p.poem_author = '廖大圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题湛文禅师山水图四首 其一', '金鉴才', '当代', '自然归正道，妙悟出天真。不信蒲团上，修成佛样身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题湛文禅师山水图四首 其一' AND p.poem_author = '金鉴才';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送三六桥归浙江', '李希圣', '清代', '尚书邸第初相见，侧帽单衫中酒时。已分从容陈大计，居然意气感深知。\n\n故人海上多奇节，危局长安似弈棋。便欲挂冠乘兴去，与君先作鹿门期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送三六桥归浙江' AND p.poem_author = '李希圣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('牡丹', '周弼', '宋代', '江南牡丹凡有几，德安打头歙为二。\n金陵旧物间有之，池阳吴郡皆居次。\n地近京畿种偏好，鄂城栽接不草草。\n舂土筛泥绕画栏，石甃方坛净如扫。\n当头第一带鞓红，腻紫娇黄别作丛。\n盘盂擎出最迎日，碧玉万片藏春风。\n宝叶丝丝带缕金，锦斑酒晕问攒心。\n翻腾栀茜乱朱粉，样各数名分浅深。\n低树犹高五六尺，花重刚枝反无力。\n迥出层阴转耐看，始悟年深有真色。\n晚添细雪来相簇，露醒香魂冷方浴。\n倚柱黄昏眼倍明，顿觉夜阑须秉烛。\n洛水芳林应更多，不禁飞雨洗铜驼。\n酥煎送酒有人在，草没故园无柰何。\n莫对余春起叹嗟，最难保守是繁华。\n君看南渡百年内，看到子孙能几家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '牡丹' AND p.poem_author = '周弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和喜奉御札改元元丰口号', '韦骧', '宋代', '改号泥封下碧空，天光远烛郡城中。禁林旧德承宣重，预向偏州致岁丰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和喜奉御札改元元丰口号' AND p.poem_author = '韦骧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题友人听雨舟', '冯班', '清代', '篷窗偏称挂鱼蓑，\n荻叶声中爱雨过。\n莫道陆居原是屋，\n如今平地有风波。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题友人听雨舟' AND p.poem_author = '冯班';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渚宫莫问诗一十五首 其十', '齐己', '唐代', '莫问无机性，甘名百钝人。一床铺冷落，长日卧精神。\n\n分已疏知旧，诗还得意新。多才碧云客，时或此相亲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渚宫莫问诗一十五首 其十' AND p.poem_author = '齐己';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和蔡半洲司马中丞平黎韵二首 其二', '卢宁', '明代', '一岛周环四郡城，除凶赫怒下天兵。阵驱云鸟风霆迅，民乐村原烟火生。\n\n直使夷荒知纪度，重看海屿录澄清。自今文治应熙洽，龙钺非叨真将名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和蔡半洲司马中丞平黎韵二首 其二' AND p.poem_author = '卢宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其十', '刘敞', '宋代', '颂声骚客误，锡贡禹书迟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其十' AND p.poem_author = '刘敞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠温驸马汝阳王', '徐晶', '唐代', '畴昔承馀论，文章幸滥推。夜陪银汉赏，朝奉桂山词。 \n 梁邸调歌日，秦楼按舞时。登高频作赋，体物屡为诗。 \n 连骑长楸下，浮觞曲水湄。北堂留上客，南陌送佳期。 \n 忆昨陪临泛，于今阻宴私。再看冬雪满，三见夏花滋。 \n 都尉朝青阁，淮王侍紫墀。宁知倦游者，华发老京师。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠温驸马汝阳王' AND p.poem_author = '徐晶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湖心亭', '王鏊', '明代', '莫釐下瞰湖波水，周垣忽向湖心起。茫然万顷银涛中，幻出楼台信奇伟。\n\n坐疑阆苑与蓬莱，飞堕君家亭子里。长堤花柳青复红，曲阑直槛东西通。\n\n龟跳鱼泳鸥鹭集，相忘如在江湖中。石梁倒影卧水底，无乃下占冯夷宫。\n\n桑田沧海须臾变，高下帆樯墙外见。鸱夷一去那复来，五湖风月谁家擅。\n\n我今无事身自由，良辰佳节长来游。观鱼为谢臧僖伯，看竹时同王子猷。\n\n长风萧萧起天末，浪捲平湖半湖雪。归来还约中秋时，把酒青天看明月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湖心亭' AND p.poem_author = '王鏊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贫甚戏作绝句', '陆游', '宋代', '俸禄无余退即耕，市人指笑太清生。\n从今惜取青鞋底，祗向云边水际行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贫甚戏作绝句' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('恭奉皇太后祇谒盛京祖陵礼成回銮途次纪事用平声韵 其十七', '弘历', '清代', '缅想戎衣烽燧销，金瓯万祀九瀛朝。折冲赳赳嫖姚霍，指示堂堂主吏萧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '恭奉皇太后祇谒盛京祖陵礼成回銮途次纪事用平声韵 其十七' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('燕邸卧病口号 其二', '嵇永福', '清代', '王程既迫敢蹒跚，出处关头义命安。母过七旬应侍养，家无次子孰承欢。\n\n圣朝教孝沾恩易，人子离家入告难。一纸九门天荡荡，陈情空自泪汍澜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '燕邸卧病口号 其二' AND p.poem_author = '嵇永福';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与大舟并行遇风感兴', '黄玠', '元代', '大帆引縆去如飞，小帆翳翳行苦迟，谁其敢争风使之。\n\n少时风休帆力软，原头树高桅子短，前舟却输后舟远。\n\n吁嗟世事非一端，咫尺行路易复难，人生得意莫尽欢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与大舟并行遇风感兴' AND p.poem_author = '黄玠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('工部弟哀诗二首 其二', '刘克庄', '宋代', '去岁书来欲解麾，数行遗墨半倾攲。斑衣不遂娱亲志，白发因吟哭子诗。\n\n让枣犹如前日事，摘瓜空抱暮年悲。情知衰泪无堪滴，原上寒笳苦死吹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '工部弟哀诗二首 其二' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红　山居遣兴六首 其五', '卢青山', '当代', '对菊疏怀，两各是、羲皇之亚。且盘礴、灵狐拜遍，丹荑采罢。\n\n我觉苍山如莽海，山看老子犹龙也。要天公、更放薄云来，容驱咤。\n\n山上雨，伊人话；山上雪，伊人帕。问伊人竟在，谁家帘下？\n\n雾幕岚纱撩不尽，润林如靥合开乍。最难堪、旖旎小箫声，吹禅舍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红　山居遣兴六首 其五' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('栖云楼晏坐效寒山偈（六首。滁仆阳太扑官舍', '殷迈', '明代', '春阴蔽幽斋，朝来始和霁。\n春风悠然来，花雨满庭际。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '栖云楼晏坐效寒山偈（六首。滁仆阳太扑官舍' AND p.poem_author = '殷迈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二色莲 周练霞书示轧米诗', '沈轶刘', '近代', '梦坠南陌，风近寒食，春在帘底。过江雁足，云朵带来天际。\n\n破却重阴万匝，看盥手琅函初启。何用苦加餐饭，凭君且歌分米。\n\n吴淞岁时纪。一片哀鸿唳。曾拥阶下袂。布囊未敛，人影半衔鱼丽。\n\n负腹真成重累。怪孺子、朝舂无计。都付与，昌黎恨，西塘涕泪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二色莲 周练霞书示轧米诗' AND p.poem_author = '沈轶刘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉楼春 题柳洲待别图送刘跃如', '李日华', '明代', '轻暖轻寒无意绪，朝来几阵梨花雨。妆成独自倚阑干，暗数落红愁不语。\n\n杜宇一声人欲去，残云片片依沙渚。横塘十里柳烟浓，维舟正在烟深处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉楼春 题柳洲待别图送刘跃如' AND p.poem_author = '李日华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送玉泉师还匡庐', '成鹫', '明代', '玉泉不识面，识得玉泉心。暂作还乡客，终当返旧林。\n\n万杉寻路入，五老闭门深。我亦孤峰宿，无由共一岑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送玉泉师还匡庐' AND p.poem_author = '成鹫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答萧子仁', '蓝智', '明代', '每忆诗篇共讨论，更烦书札致殷勤。\n西风一夜萧萧雨，落日三山渺渺云。\n碧海鱼龙秋正蛰，空江鸿雁夜多闻。\n茅檐寂寞黄花晚，欲采寒香远寄君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答萧子仁' AND p.poem_author = '蓝智';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('即事 其一', '弘历', '清代', '次第封章毕指挥，青郊草浅试春围。设如蓦遇姚元景，咨事安能待猎归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '即事 其一' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶得红菊一本置之盆中遂成一首', '林庭桂', '明代', '十尺珊瑚到眼前，品题曾说是金蝉。风飘阶下香犹细，露湿盆中色更鲜。\n\n幽谷芝兰长作伴，东园桃李敢争妍。客窗对此真堪爱，笑摘娇枝入酒筵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶得红菊一本置之盆中遂成一首' AND p.poem_author = '林庭桂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题渔樵耕牧图四首 其一', '胡应麟', '明代', '持竿俯碧流，莫学蟠溪客。白首向岐周，抛纶事西伯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题渔樵耕牧图四首 其一' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游越', '张仲深', '元代', '抚迹悲生事，因循作远游。半生山水愿，满眼古今愁。\n\n木叶经霜减，山云遇雨稠。晚来清兴动，步屧到林幽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游越' AND p.poem_author = '张仲深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('佥判丈两赐新字韵诗因次韵兼简文显', '赵蕃', '宋代', '连朝枉诗句，俊逸且清新。\n叹我徒劳思，知公固绝人。\n林园能数驾，风雨未妨辰。\n作底周夫子，关门懒似真。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '佥判丈两赐新字韵诗因次韵兼简文显' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄感山二诗僧', '姚勉', '宋代', '读君桑苇疎篱句，知得犹存用世心。\n拄杖借将来解虎，不须深卧白云深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄感山二诗僧' AND p.poem_author = '姚勉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古三十一首', '释如本', '宋代', '小释迦，大文殊。\n闻名号，任称呼。\n藤条在握不能用，被他碧眼谩涂糊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古三十一首' AND p.poem_author = '释如本';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('耕图二十一首·簸扬', '楼璹', '宋代', '临风细扬簸，糠粃零风前。\n倾泻雨声碎，把翫玉粒圆。\n短裙箕帚妇，收拾亦已专。\n岂图较斗升，未敢忘凶年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '耕图二十一首·簸扬' AND p.poem_author = '楼璹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵王民瞻赠觉梵二首 其一', '刘才邵', '宋代', '腹稿欲成聊假卧，寒松疏磬仍相左。不容开府占清新，云里江梅萼初破。\n\n奇芬还似暗香浮，全胜光风泛兰些。玉川昔访长寿寺，石壁留题如此作。\n\n珊瑚炫转光夺目，含曦一读忘饥饿。便堪高蹑诗将坛，纷纷谁可克参佐。\n\n韦庄岂免赠巾帼，格嫩更遭脂粉涴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵王民瞻赠觉梵二首 其一' AND p.poem_author = '刘才邵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('程德基以所著易简方编见惠谢之', '陈恭尹', '明代', '黄山白岳足幽居，好学偏乘历骋车。千里借筹频决胜，一官搔首尚踟蹰。\n\n嵇含每状南中物，抱朴兼成肘后书。安得藉君调燮手，尽回元气到比闾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '程德基以所著易简方编见惠谢之' AND p.poem_author = '陈恭尹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('富春道中范宪副舟宴', '皇甫汸', '明代', '已谢尘中鞅，犹同使者舟。清尊聊卜夜，白发几悲秋。\n\n山色分苍霭，滩深递急流。独怜垂钓处，阅水自悠悠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '富春道中范宪副舟宴' AND p.poem_author = '皇甫汸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('红杏园叠前韵', '弘历', '清代', '西极奠鸿功，东山临凤辇。邮程经古邑，憩所驻閒馆。\n\n夜息奥室温，昼接明廷显。所凛身无逸，所喜书堪展。\n\n今古既因省，丝竹一以遣。五经赖谁明，遐思献王善。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '红杏园叠前韵' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('河传 赠歌童', '陈世祥', '清代', '听半。听半。个侬魂断。吐玉揉香。都来字字总成双。\n\n鸳鸯。不求凰。\n\n曲终生遣寒窗暖。春恨满。写恨嫌笺短。铸将金屋待卿藏。\n\n端相。温柔是此乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '河传 赠歌童' AND p.poem_author = '陈世祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜张子静见过诗送其归兼柬沈彦祥', '史鉴', '明代', '扰扰百年内，相逢能几回。\n折麻空有意，抱病强登台。\n苕水太湖接，故人今雨来。\n因风问东老，何日共深杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜张子静见过诗送其归兼柬沈彦祥' AND p.poem_author = '史鉴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过紫嵩菴', '宋庠', '宋代', '新结禅菴当小斋，见山何必上高台。\n嵩岩更似知音赏，雨罢先供翠色来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过紫嵩菴' AND p.poem_author = '宋庠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('《虔州八境图》八首', '苏轼', '宋代', '云烟缥缈郁孤台，积翠浮空雨半开。\n想见之罘观海市，绛宫明灭是蓬莱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '《虔州八境图》八首' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同褚生滔徐生大复夜过城濠水榭作二首 其二', '唐顺之', '明代', '祗堪成独往，讵意得同群。柳色秋将近，乌啼夜欲分。\n\n细吟西涧草，闲诵北山文。纵然逢醉尉，不是故将军。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同褚生滔徐生大复夜过城濠水榭作二首 其二' AND p.poem_author = '唐顺之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题宗侄孙文楷文模二便面 其二 花鸟', '程敏政', '明代', '绕阑花似雪，枝上立珍禽。入手炎光散，清风动竹林。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题宗侄孙文楷文模二便面 其二 花鸟' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('张若霭莲塘浴鸭图', '弘历', '清代', '擎杯徼露盖承暄，作对文凫漾藻痕。最是相关多乐意，休誇花底睡双鸳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '张若霭莲塘浴鸭图' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿邻水县', '袁说友', '宋代', '酒馀孤馆梦初回，渐觉茅檐淅淅来。夜半山前风荐雨，晓来崖底涧鸣雷。\n\n剩添岗翠三分色，呈出秧针一寸栽。恰得乌云天外少，莺花无数恼人怀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿邻水县' AND p.poem_author = '袁说友';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一萼红', '伯昏子', '当代', '横云阴，念新枝吐蕾，一夜尽冰簪。寒柳收青，枯荷戴白，湖鸥匝起浮沉。\n\n绕嘉木、灵芬暗赏，最恨见、明月照幽禽。逋叟茔孤，坡公台寂，伤极凭临。\n\n舫乐毂尘都暂，问红绡万树，怎托春心。喧市霓明，长堤火映，清凉意绪堪寻。\n\n似征雁、归程犹急，辔停处、悲艳总如金。但梦霞裾素冠，几度情深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '一萼红' AND p.poem_author = '伯昏子';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('定安四景为宗伯王公赋 其三 桥头碧水', '欧大任', '明代', '沧海烟深碧浪遥，鱼龙奋起上云霄。至今司马双题笔，犹在天涯万里桥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '定安四景为宗伯王公赋 其三 桥头碧水' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('景云轩', '杨杰', '宋代', '南城城外山崔嵬，景云轩上无尘埃。双溪水落逐年急，白发僧归何日来。\n\n画屏满目万瓦合，几人到此心如灰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '景云轩' AND p.poem_author = '杨杰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送张文元秀才下第归吴', '童轩', '明代', '功名两字古来难，又向西风抱玉还。点额自怜龙未化，泽文犹待豹成斑。\n\n黄芦浅水沙头雨，红树斜阳郭外山。他日重来应得意，一枝仙桂看高攀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送张文元秀才下第归吴' AND p.poem_author = '童轩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('砚池', '何巩道', '明代', '砚边点笔水涵清，宿墨留痕欲化冰。更有胆瓶花片落，残红飞上几多层。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '砚池' AND p.poem_author = '何巩道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湖上', '陆游', '宋代', '寒食初过谷雨前，轻衫短帽影翩翩。\n独辕碾破新堤路，双耜犁残古庙壖。\n万事不禁刘毅掷，诸人谁著祖生鞭？市垆处处夸新酿，且就花阴一醉眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湖上' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六月初雨中渡西湖因至道人庵烧佛香略憩灵隐与乡僧同啜茶乘晚以归 其一', '员兴宗', '宋代', '猎猎风攲袖，垂垂雨打船。最怜荷似屋，不障水如天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六月初雨中渡西湖因至道人庵烧佛香略憩灵隐与乡僧同啜茶乘晚以归 其一' AND p.poem_author = '员兴宗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('盂兰盆词十首 其三', '郑用锡', '清代', '馁魂窣窣逐良辰，犹是烟蓑雨笠身。甘露可能沾白骨，火坑暂许咽青唇。\n\n田园笋蕨谋孙子，邱陇牛羊属别人。寄语此间多菜色，饥驱难饱藿羹尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '盂兰盆词十首 其三' AND p.poem_author = '郑用锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('追和野亭八咏 其三 野堂', '黄衷', '明代', '日出半扉启，山空四壁光。金縢馀训诰，缃帙是归藏。\n\n客至蛛丝报，春回燕垒荒。何人开绿野，异代即同芳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '追和野亭八咏 其三 野堂' AND p.poem_author = '黄衷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题马当山鱼望亭四首右狄梁公', '黄庭坚', '宋代', '鲸波横流砥柱，虎口活国宗臣。\n小屈弦歌百里，不诬天下归仁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题马当山鱼望亭四首右狄梁公' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送周司寇廷玉献绩赴阙三首 其三', '倪谦', '明代', '几年宪部总刑章，此日朝天促去装。只以宽仁辅尧舜，肯为刻覈事申商。\n\n九重入觐当清晓，一叶惊秋送早凉。昨对紫垣瞻北极，泰阶两两正腾光。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送周司寇廷玉献绩赴阙三首 其三' AND p.poem_author = '倪谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和光祖诗韵一首', '耶律铸', '元代', '西风望断碧云深，万里关河入俯临。客思暗随愁共远，髯冰疑是老相侵。\n\n霜鸿傍月传佳信，寒雪漫天拥衲吟。十载因循归未得，飘零踪迹到如今。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和光祖诗韵一首' AND p.poem_author = '耶律铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('问月图', '刘崧', '明代', '月色如金波，揽之欲盈手。如何不解饮，空遣星名酒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '问月图' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('子夜吴歌 其三', '王世贞', '明代', '姊妹欺相命，星前闭洞房。携灯挑促织，罗袜下东廊。\n\n明日争邀赌，钗头金凤皇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '子夜吴歌 其三' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('即事寄孙世行吕玉绳二首 其一', '汤显祖', '明代', '平昌四见碧桐花，一睡三餐两放衙。也有云山开百里，都无城郭凑千家。\n\n长桥夜月歌携酒，僻坞春风唱采茶。即事便成彭泽里，何须归去说桑麻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '即事寄孙世行吕玉绳二首 其一' AND p.poem_author = '汤显祖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔父吟', '李琏', '明代', '烟波万顷利名轻，短笛吹残酒半醒。鼓枻自歌还自和，一溪风月有谁争。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔父吟' AND p.poem_author = '李琏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送子发赴江州司理', '吕南公', '宋代', '湓江湛湛照闉阇，庐岳蟠蟠荫郭郛。此地一官虽郁屈，异人当日亦踟蹰。\n\n元规楼下随红旆，居易祠前看白须。才调似君真不薄，有诗无吝寄云夫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送子发赴江州司理' AND p.poem_author = '吕南公';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花（劝酒致语）', '黄裳', '宋代', '适来已陈十二短章，辄歌三五盛景。累累清韵，尚渐梁上之飞尘；抑抑佳宾，须作乡中之醉客。同乐当勤于今夕，相从或系于他年。更赋幽情，再声佳咏。 \n 万籁无声天地静。清抱朱弦，不愧丹霄镜。照到林梢风有信。抬头疑是梅花领。 \n 万感只应闲对景。独倚危栏，扰扰人初定。吟不尽中愁不尽。溪山千古沈沈影。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花（劝酒致语）' AND p.poem_author = '黄裳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自居剡源少遇乐岁辛巳之秋山田可拟上熟吾贫庶几得少安乎乃和渊明贫士七首与邻人歌而乐之 其五', '戴表元', '宋代', '古人重畎亩，有禄不待干。德成禄自至，释耒列王官。\n\n不仕亦不贫，本自足饔餐。后世耻躬耕，号呼脱饥寒。\n\n我生千祀后，念此愧在颜。为农倘可饱，何用出柴关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自居剡源少遇乐岁辛巳之秋山田可拟上熟吾贫庶几得少安乎乃和渊明贫士七首与邻人歌而乐之 其五' AND p.poem_author = '戴表元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('墙下野菊', '沈周', '明代', '墙根野菊自烂漫，新黄琐碎无人怜。幽芳不扬抱隐德，僻地萧条宜养贤。\n\n聊因杯酒少慰藉，三嗅三叹秋风前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '墙下野菊' AND p.poem_author = '沈周';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五月十一日睡起', '陆游', '宋代', '病眼慵於世事开，虚堂高卧谢氛埃。\n帘栊无影觉云起，草树有声知雨来。\n茶碗嫩汤初得乳，香篝微火未成灰。\n翛然自适君知否？一枕清风又过梅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五月十一日睡起' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桃', '冯班', '清代', '风吹露湿一枝枝，带子垂阴是后期。已许成蹊通看路，纵饶无语是含辞。\n\n人间地薄载难得，井上根衰蠹不持。芳蕊堪怜落堪惜，闲人不管正开时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桃' AND p.poem_author = '冯班';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('唐多令 书感', '王易', '清代', '蝶梦几时醒，华胥千万程。恨多情、何似无情。为甚年来心绪恶，人静处、涕常零。\n\n窗外月华明，窗中长叹声，要知心、惟有孤灯。无限牢愁淘不尽，那更听、乱蛩鸣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '唐多令 书感' AND p.poem_author = '王易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和友人闲居之作', '范景文', '明代', '夜里删诗日看山，纵然忙杀也清闲。\n从教花落休开径，除却僧来即闭关。\n性好积书终是癖，身无小病怕成顽。\n幽栖未尽声闻累，鹤舞々鸟语蛮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和友人闲居之作' AND p.poem_author = '范景文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('政和二年余谪海外馆琼州开元寺俨师院遇其游行市井宴坐静室作务时恐缘差失念作日用偈八首 其一', '释德洪', '宋代', '一切境界，病眼倒见。但静意根，空慧自现。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '政和二年余谪海外馆琼州开元寺俨师院遇其游行市井宴坐静室作务时恐缘差失念作日用偈八首 其一' AND p.poem_author = '释德洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑子 其四', '欧阳修', '宋代', '群芳过后西湖好，狼藉残红，飞絮濛濛，垂柳阑干尽日风。\n\n笙歌散尽游人去，始觉春空。垂下帘栊，双燕归来细雨中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑子 其四' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头 将去星洲留别龚道运诸子', '饶宗颐', '近代', '百年只一霎，珍重在须臾。至人用两致一，寸寸即工夫。\n\n尝踏重关万里，又绕离亭千树。飞隼击平芜。苍山渺无际，平地总长途。\n\n古今事，争旦夕，费踌躇。藏天下于天下，莫笑愚公愚。\n\n定久便知慧出，霜重自然冰至，辛苦待春锄。栏外春如旧，一任子规呼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头 将去星洲留别龚道运诸子' AND p.poem_author = '饶宗颐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('得子自忻', '李江', '明代', '十年辛苦九年灯，三十春光四十零。兄弟情因添侄喜，椿萱心为得孙宁。\n\n肯愁家里无千顷，自感床头有一经。尊酒相逢须尽醉，眼中天地自分明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '得子自忻' AND p.poem_author = '李江';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('即事二首', '晁说之', '宋代', '药苗晚种已青青，应念尪羸与养形。\n肯为嵇生徒著论，便同玄晏剩翻经。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '即事二首' AND p.poem_author = '晁说之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂咏三十五首 其三十五', '添雪斋', '当代', '天末尽寒芜，荒云之暧暧。梦过又百年，随此严秋塞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂咏三十五首 其三十五' AND p.poem_author = '添雪斋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('听姜可玉弹琴用江叔载韵', '张仲深', '元代', '出门听松泉，尘心一以洗。入门闻丝桐，又欲洗尘耳。\n\n幽人在东斋，见之殊可喜。悠然太古心，静探玄精理。\n\n一弄风泠泠，再弄溪泚泚。但言少知音，振衣张拱起。\n\n孰知伯牙心，荡荡在流水。岂若齐王竽，仅谐东里鄙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '听姜可玉弹琴用江叔载韵' AND p.poem_author = '张仲深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送冯 其二', '周紫芝', '宋代', '君王慈俭不临戎，国好长因汉使通。遥想南归寒已尽，榆关草色正春风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送冯 其二' AND p.poem_author = '周紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('齐天乐', '庞俊', '近代', '青枫别岛新霜后，郎当怕闻铃语。金井多风，铜铺过月，怨曲哀蝉谁度。\n\n无人坠处，正太液波荒，洞庭山古。策策商声，夜阑开户在何许。\n\n长亭人去怨极，傍江潭总是，当年千树。转绿枝空，流红水断，客老瘴烟蛮雨。\n\n啼螀枉诉。怎恋得斜阳，眺来平楚。海水枯桑，翠眉吟更苦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '齐天乐' AND p.poem_author = '庞俊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('用韵答樊孟学 其二', '郑真', '明代', '金汤形胜睹中京，宫阙煌煌万雉城。司马自为题柱客，终军本是弃繻生。\n\n久闻鸡黍原同约，须信盐梅可作羹。矫首奕坛仙迹近，月明来听步虚声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '用韵答樊孟学 其二' AND p.poem_author = '郑真';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏梅', '吴文治', '近代', '数枝斜出竹篱边，不染尘埃似散仙。历尽风霜无限苦，春来独占百花先。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏梅' AND p.poem_author = '吴文治';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题湖山烟雨图 其二', '刘基', '元代', '若耶溪上雨声来，秦望山前雾不开。欲渡镜湖寻禹完，苍藤翠木断猿哀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题湖山烟雨图 其二' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('免归思母八首 其七', '张国维', '明代', '昨秋朝暮望归人，今日南鸿傍逐臣。愤切时艰遑偃仰，情于天听释邅迍。\n\n凊温迟暮犹无子，生死维持赖有亲。何事依云空伫立，双眸已入画溪春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '免归思母八首 其七' AND p.poem_author = '张国维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆秦娥', '缪珠荪', '清代', '春睡足，春深悄傍阑干曲。阑干曲，云裳楚楚，几分新绿。\n\n惺忪惯挽秋千索，羡它蝴蝶深枝宿。深枝宿，庭阴欲午，可怜腰束。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆秦娥' AND p.poem_author = '缪珠荪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南歌子（代张仲宗赋）', '向子諲', '宋代', '碧落飞明镜，晴烟幂远山。扁舟夜下广陵滩。照我白萍红蓼、一杯残。 \n 初望同盘饮，如何两处看。遥知香雾湿云鬟。凭暖琼楼十二、玉栏干。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南歌子（代张仲宗赋）' AND p.poem_author = '向子諲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉送尊师唐先生判金华', '韩雍', '明代', '驿亭清酒汎黄花，旧馆诸生满路遮。亲炙久期联玉笋，分违遥送判金华。\n\n从来儒术堪经世，此去乡心莫恋家。早使提封遂康济，趋朝终儗拜黄麻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉送尊师唐先生判金华' AND p.poem_author = '韩雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢关景仁送红梅栽二首 其二', '苏轼', '宋代', '为君栽向南堂下，记取他年著子时。酸酽不堪调众口，使君风味好攒眉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢关景仁送红梅栽二首 其二' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽张方伯父', '韩雍', '明代', '幕宾谪后随膺荐，循吏功成即引年。元亮归来三径在，韦贤老去一经传。\n\n重封极品龙章焕，载写遗容鹤绣鲜。早晚郎君还大拜，宠光定许贲幽泉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽张方伯父' AND p.poem_author = '韩雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送李季允赴召 其二', '魏了翁', '宋代', '一倾鼎否一番新，但见新人笑故人。元祐至今迭更化，崇宁以后几权臣。\n\n曾趋嘉定改元诏，又贺端平第一春。长把人才留一半，今年新是去年陈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送李季允赴召 其二' AND p.poem_author = '魏了翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再过赣江别同年徐宪副辱以楚游诗见示且索近作书此寄之二首 其一', '林大春', '明代', '复此虔台会，翻疑昨日逢。山留登眺处，水写别离踪。\n\n楚迹多乘兴，新诗得大宗。应怜倦游者，犹自问雕龙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再过赣江别同年徐宪副辱以楚游诗见示且索近作书此寄之二首 其一' AND p.poem_author = '林大春';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泮水荷香', '谢正华', '清代', '海国多奇卉，莲开待腊霜。池塘初梦草，菡萏已成房。\n\n藕带芹泥绿，叶翻泮水香。地灵佳气萃，浓艳岂寻常。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泮水荷香' AND p.poem_author = '谢正华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洞霄琳宫', '连久道', '宋代', '栖真已得寻西洞，神应谁能辨雨锺。\n水奏五音鸣玉凤，山回九锁踞苍龙。\n古杉疑复天台去，怪石时从福地供。\n它日重游应更好，拟登天柱最高峰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洞霄琳宫' AND p.poem_author = '连久道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('家藏旧画效前人论画绝句各系一诗 其十九', '陈式金', '清代', '浑厚峰峦具性情，能从密处见神清。宏开乌目云溪誉，领袖同时几后生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '家藏旧画效前人论画绝句各系一诗 其十九' AND p.poem_author = '陈式金';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('摸鱼儿（紫云山房拟赋莼）', '唐珏', '宋代', '渐沧浪、冻痕消尽。琼丝初漾明镜。鲛人夜翦龙髯滑，织就水晶帘冷。凫叶净。最好似、嫩荷半卷浮晴影。玉流翠凝。早枯豉融香，红盐和雪，醉齿嚼清莹。 \n功名梦，曾被秋风唤醒。故人应动高兴。悠然世味浑如水，千里旧怀谁省。空对影。奈回首、姑苏台畔愁波暝。烟寒夜静。但只有芳洲，苹花共老，何日泛归艇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '摸鱼儿（紫云山房拟赋莼）' AND p.poem_author = '唐珏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('横山有高竹楼别业留信宿始归', '许有壬', '元代', '酒香牲腯主人归，正是猿惊鹤怨时。梅影小池春入画，竹声虚阁夜催诗。\n\n世间真乐无多事，身外浮名只费辞。他日结茅容我隐，一章先当买山赀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '横山有高竹楼别业留信宿始归' AND p.poem_author = '许有壬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('换马行', '林徵韩', '清代', '马蹄落地滚尘埃，道是天使天上来。未许邮符先及见，直呼换马声连催。\n\n马到当换故不换，下马索取常例看。但须一贯就腰缠，无语饱饫邮亭饭。\n\n饭罢曾不少迁延，上马还须惜马钱。走马城边立马上，手折杨柳当马鞭。\n\n前跕前去不须臾，后到一起是行厨。朝廷供给有正项，额外别寻达刺苏。\n\n醉后向人口譊譊，是人遇之遭鞭敲。稍有不如需索意，拚死骑将驿马跑。\n\n天使后来无一语，只是颜色多骄倨。公然下马坐悬堂，换马从容上马去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '换马行' AND p.poem_author = '林徵韩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元日海幢寺拈香有寄', '熊东遨', '当代', '云外疏钟响，年光又一轮。也知魔劫重，不碍日华新。\n\n大庙供多佛，中流剩几人。狂车行渐远，孰与叩前因。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元日海幢寺拈香有寄' AND p.poem_author = '熊东遨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送李天生归养', '王顼龄', '清代', '廿年高隐为承欢，诏趣蒲轮却聘难。圣主爱才非强志，大儒报国岂须官。\n\n邹枚词赋清时重，黄绮风流异代看。遥想彩衣归拜舞，朝恩家庆话团栾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送李天生归养' AND p.poem_author = '王顼龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答庄思缄 其二', '郑孝胥', '清代', '茹蔬讽佛庄夫子，自忏平生十斗才。应念龙编旧归客，犹持残笔守书堆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答庄思缄 其二' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('横翠亭书怀', '释绍嵩', '宋代', '小葺茅茨紫翠间，门当宫道不曾关。\n剪裁风月聊堪醉，奔走尘寰出老颜。\n半局残棋消白昼，十年归梦满青山。\n江城今可徘徊处，莫怪频频此往还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '横翠亭书怀' AND p.poem_author = '释绍嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红 漫吟', '叶绍本', '清代', '峻坂双丸，隙驹过处全无影。乍帘外，雪云黯澹，霜风凄紧。\n\n草草年光行欲暮，迢迢尘梦呼难醒。算圆浑，著甚恁般忙，无凭准。\n\n今古事，闲中省。真幻想，空中领。只浮沤，起灭去来无定。\n\n小住十洲清净宅，安眠一觉华胥枕。问前身，何处托行踪，蓬莱顶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红 漫吟' AND p.poem_author = '叶绍本';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽李制干子诚', '林光朝', '宋代', '文字纷纷更问兵，秋灯束发尚青荧。\n便令三子成门户，却许诸孙说典型。\n隔水忽传朝露曲，行人长数夕阳亭。\n河东健笔惟诸薛，梅子岗边为勒铭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽李制干子诚' AND p.poem_author = '林光朝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古一百二十一首 其六十', '释宗杲', '宋代', '以平报不平，王法本无亲。临济虽明眼，也是黄龙精。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古一百二十一首 其六十' AND p.poem_author = '释宗杲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('花心动·偏忆江南', '刘焘', '宋代', '偏忆江南，有尘表丰神，世外标格。低傍小桥，斜山疏篱，似向陇头曾识。暗香孤韵冰雪里，初不怕、春寒要勒。问桃杏贤瞒，怎生向前争得。省共萧娘笑摘。玉纤映琼枝，照人一色。澹粉晕酥，多少工夫，到得寿阳宫额。再三留待东君看，管都将、别花不惜。但只恐、南楼又三弄笛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '花心动·偏忆江南' AND p.poem_author = '刘焘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庚午岁伯氏生朝作乐府一章为寿', '王洋', '宋代', '木公金母传瑶爵，九虎开门动鱼钥。瑶池曼倩别烟霞，海上安期降乔岳。\n\n东牟先生德弥大，静课虚无明寂寞。背连海峤三双鳌，手取西山一丸药。\n\n推先当户培芳兰，斗牛宝气摇光寒。光华章绶表奇格，照耀广陌驰花鞍。\n\n春风物色论长久，柳拂腰支梅劝酒。百篇聊复付西江，盛事会须传不朽。\n\n天上老骥禾充肠，一秣万里渎空苍。年年岁岁身长健，岁岁年年春草长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庚午岁伯氏生朝作乐府一章为寿' AND p.poem_author = '王洋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶成', '孙俊在', '近代', '揽镜自嗤两鬓丝，回头往事耐寻思。今看问字童孙辈，宛似当年总角时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶成' AND p.poem_author = '孙俊在';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗十首 其一', '朱诚泳', '明代', '南山有长松，独抱参天姿。岁晚愈苍翠，不受霜雪欺。\n\n一贞恒自守，四序焉能移。眷彼桃李花，灼灼迎春曦。\n\n明媚惊众目，秾华复几时。常恐风雨至，须臾变离披。\n\n物性本如此，造化谁尸之。嗟哉浮俗流，龊龊徒尔为。\n\n安得古贞操，偃仰慰吾思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗十首 其一' AND p.poem_author = '朱诚泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('燕', '许介轩', '宋代', '柳影芹香二月春，一巢才定即栖身。\n不应它处无华屋，自是难忘旧主人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '燕' AND p.poem_author = '许介轩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十日阴晦漫赋', '汤珍', '明代', '昨日重阳今日阴，眼前时事漫惊心。紫茱黄菊馀幽兴，白石青苔伴独吟。\n\n万里鸿冥聊下上，百年龙卧信浮沈。高情亦复如元亮，不见王弘送酒临。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十日阴晦漫赋' AND p.poem_author = '汤珍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十村绝句', '舒岳祥', '宋代', '朝朝腰斧采荆榛，博米求盐到海村。\n白虎当溪侬不畏，祗愁暴吏打人门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十村绝句' AND p.poem_author = '舒岳祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东梁山僧舍', '姚鼐', '清代', '津涛行复滞，峡嶂路还缘。石壁凌江阁，风林隔浦船。\n\n鹘盘崖树侧，㹠出浪花巅。往迹无俦伴，春阴弥悄然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东梁山僧舍' AND p.poem_author = '姚鼐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('腊梅', '尹廷高', '元代', '五出天然蜡缀成，诗人千载不知名。自从山谷推同姓，一日清香偏汴京。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '腊梅' AND p.poem_author = '尹廷高';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('麃子岭帐馆寄隐直', '刘敞', '宋代', '离肠易感岁华催，更席龙沙望紫台。持节不眠宵自永，听笳无事泪空摧。\n\n扁舟何处山阴雪，驿使他年岭上梅。欲寄一书愁已乱，天边应候客星回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '麃子岭帐馆寄隐直' AND p.poem_author = '刘敞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花落', '刘基', '元代', '种梅长江边，岁冕花始发。东风为爱桃与李，却使孤芳坐销歇。\n\n美人高楼深紫霞，捲帘一见长叹嗟。世间有荣即有悴，君不见海中碧树终无花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花落' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送胡竹村同年归绩溪', '祁寯藻', '清代', '古人著书不得已，书成身废良可叹。若使勋名照竹帛，何为雕琢愁肺肝。\n\n君尝为余述师授，斯语闻之汪文端。因言年少治经义，独于三礼心尤单。\n\n瓣香欲祝北海郑，苦读每笑南阳韩。中年通籍习吏事，回鴹凤阁迁农官。\n\n农官急务在心计，抉剔常恐遭欺谩。即不被议且归去，小谪总荷君恩宽。\n\n秋风莼鲈久相待，南国鸣雁何时安。还家一笑奉菽水，赖有文字娱酸寒。\n\n君看仕宦得意人，罢官忽若无余欢。人生得失未可较，海鸥奚事侪鹓鸾。\n\n因君致声问匡鼎，说《诗》之乐何般般。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送胡竹村同年归绩溪' AND p.poem_author = '祁寯藻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('人日遗章行严', '郑孝胥', '清代', '昔与几道论物理，初若不合终有取。行严理不减几道，文辞益达真其偶。\n\n滔天新说荡忘返，徒使学者失所守。山移海覆俄自败，始信吾道可长久。\n\n子于学术诚善变，非但心悟实身受。速宜著书道甘苦，后生循循得切诱。\n\n世人欲杀定何意，正坐名高博众诟。冲寒过我示新作，抑郁穷愁聊一呕。\n\n不妨独以文为诗，莫与时贤较升斗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '人日遗章行严' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晓渡瓜洲', '夏孙桐', '清代', '夜泊金山下，晓渡瓜洲口。枕边闻橹声，蒲牢尚遥吼。\n\n起望大江中，雾气亘八九。日出远溆明，水城见如斗。\n\n溯流舟忘迟，近港觉行久。渐看帆樯聚，舟人互呼友。\n\n风色招大旗，霜痕入江柳。回望金焦山，青青辨还否。\n\n行人喜踰险，鱼市趁沽酒。扬州咫尺间，舣舟亭午后。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晓渡瓜洲' AND p.poem_author = '夏孙桐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏物体六十六首 其五十一 白鹇', '王世贞', '明代', '绀趾霜毛亦太奇，亭亭孤立夕阳移。鸡群欲挽难为色，鸥侣虽盟不并姿。\n\n琪树寸红分历乱，碧潭双玉照参差。知卿久擅南州誉，曾记开元李白词。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏物体六十六首 其五十一 白鹇' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送阎中孚郎中知磁州', '梅尧臣', '宋代', '箫管梁王台，风雪邯郸道。\n君行守赵城，我向夷门老。\n持麾邦寄重，歌裤民欣早。\n重冈古猎场，惊兔离衰草。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送阎中孚郎中知磁州' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居秋思', '周贺', '唐代', '一从云水住，曾不下西岑。落木孤猿在，秋庭积雾深。 \n 泉流通井脉，虫响出墙阴。夜静溪声彻，寒灯尚独吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居秋思' AND p.poem_author = '周贺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过卢沟桥', '弘历', '清代', '石桥雁齿度卢沟，两岸来牟绿正稠。风里菰蒲飐远溆，春来鸥鹭满横洲。\n\n閒心无那悲欢绪，野水依然左右流。东去直教沧海达，谁能一叶放扁舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过卢沟桥' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('点绛唇 秋晓', '蒋纫兰', '清代', '雾敛云收，乱风拂拂生杨柳。鸟啼莺奏。帘幕寒重透。\n\n镜影棱棱，自觉新来瘦。双眉皱。颦残翠岫。玉颜难如旧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '点绛唇 秋晓' AND p.poem_author = '蒋纫兰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽方通判良翰', '林光朝', '宋代', '达者渊明自挽歌，新坟数尺奈愁何。\n鸡林贾客无从问，收拾篇章有几多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽方通判良翰' AND p.poem_author = '林光朝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诗一首', '员安舆', '宋代', '国初吾乡民，万户一逢掖。\n盖自咸平后，俊髦始接迹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诗一首' AND p.poem_author = '员安舆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('镇南邸报癸未四月作', '王安石', '宋代', '赐诏宽言路，登贤壮陛廉。\n相期正在治，素定不烦占。\n众喜夔龙盛，予虞终灌憸。\n太平谈可致，天意慎猜嫌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '镇南邸报癸未四月作' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂咏五首 其二', '苏仲', '明代', '僧徒慕大佛，诵经过千日。大佛在我心，不在传与习。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂咏五首 其二' AND p.poem_author = '苏仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠僧中海渊还阆', '范镇', '宋代', '旧乡山水绕禅扃，日日山光与水声。归去定贪山水乐，不教魂梦到神京。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠僧中海渊还阆' AND p.poem_author = '范镇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再次 其二', '严嵩', '明代', '夫君起西蜀，谒帝陈琅玕。妙龄赐上第，声名动朝端。\n\n遂令海内士，啧啧称才难。譬彼珊瑚枝，置之赤瑛盘。\n\n清辉映皎洁，修干凌巑岏。贱子忝官署，往往接英翰。\n\n珠玉富璀璨，觉我形寒单。开缄清风穆，入手垂露漙。\n\n耿耿苍水佩，峨峨切云冠。池看凤毛贵，庭忆彩衣欢。\n\n苍生望安石，才人羡子安。郗林应擢桂，谢砌总生兰。\n\n巨川须拯溺，广厦思庇寒。致身立津要，早愿勋猷殚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再次 其二' AND p.poem_author = '严嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂兴十五首 其八', '常纪', '清代', '午钟初罢午鸡啼，一榻清幽任我栖。篱豆花香新艾纳，墨池水染古玻瓈。\n\n小狸扑蝶还窥影，巧燕成巢不堕泥。阶草自生窗外绿，人非茂叔也萋萋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂兴十五首 其八' AND p.poem_author = '常纪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨后登吸江亭', '释绍嵩', '宋代', '吸江亭下雨初晴，中有樵夫跣足行。\n时作微吟清彻骨，兹游无乃太清生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨后登吸江亭' AND p.poem_author = '释绍嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三山次潘静之升书记韵', '朱槔', '宋代', '客路那知岁月长，掀眉一笑苾蒭房。\n且倾徐邈圣贤酒，不问陈登上下床。\n云影翻空迷海峤，秋声随梦到江乡。\n明朝各听船窗雨，犹忆枯棋战四郎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三山次潘静之升书记韵' AND p.poem_author = '朱槔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠刊图书萧文彬', '文天祥', '宋代', '苍籀书法祖，斯冰篆家豪。\n昔人锋在笔，今子锋在刀。\n收功棠豀金，不礼山中毛。\n囊锥脱颖出，镌崖齐天高。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠刊图书萧文彬' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏怀 其二十八', '孙元衡', '清代', '举头瞻碧落，与海混中边。朝光亦何满，夜色更澄鲜。\n\n两丸浮远界，列宿横飞烟。滔滔者奚适，苍苍兮无缘。\n\n理生一驹隙，所向恣缠绵。断我骨肉恩，南蛮共流年。\n\n娲鍊欲奚补，禽衔安可填。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏怀 其二十八' AND p.poem_author = '孙元衡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('叹花词', '施肩吾', '唐代', '前日满林红锦遍，今日绕林看不见。 \n 空馀古岸泥土中，零落胭脂两三片。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '叹花词' AND p.poem_author = '施肩吾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('余阙守城', '谢士元', '明代', '烟尘暗九关，王室势如燬。矫矫鲁诸生，擐甲守孤垒。\n\n援绝力难支，身亡心不死。至今清水塘，时复悲风起。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '余阙守城' AND p.poem_author = '谢士元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元日四首 其三', '沈周', '明代', '野俗誇占候，年芳比昨强。值人春立早，加闰岁行长。\n\n话绪及农切，杯巡次客忙。援时从少饮，独后感流光。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元日四首 其三' AND p.poem_author = '沈周';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('刘纯之以便亲请还蜀', '杨杰', '宋代', '通守临川郡，家山梦翠微。愿辞灵运史，欲着老莱衣。\n\n万事樽前尽，片心天外归。金乌伴征棹，日日向西飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '刘纯之以便亲请还蜀' AND p.poem_author = '杨杰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古一百二十一首 其五十九', '释宗杲', '宋代', '一气转一大藏教，顿渐偏圆权与实。无边妙义炳然彰，元来一字也不识。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古一百二十一首 其五十九' AND p.poem_author = '释宗杲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('太平圣德诗十章 其二 皇上奉圣母皇太后极天下之养爱敬之至深得欢心此圣人治道之本也为圣孝之诗第二', '杨士奇', '明代', '九重孝德超前古，日日承欢在宝慈。圣母圣皇天所祐，太平至乐万年期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '太平圣德诗十章 其二 皇上奉圣母皇太后极天下之养爱敬之至深得欢心此圣人治道之本也为圣孝之诗第二' AND p.poem_author = '杨士奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉酬睢阳路太守见赠之作', '高适', '唐代', '盛才膺命代，高价动良时。帝简登藩翰，人和发咏思。 \n 神仙去华省，鹓鹭忆丹墀。清净能无事，优游即赋诗。 \n 江山纷想像，云物共萎蕤。逸气刘公幹，玄言向子期。 \n 多惭汲引速，翻愧激昂迟。相马知何限，登龙反自疑。 \n 风尘吏道迫，行迈旅心悲。拙疾徒为尔，穷愁欲问谁。 \n 秋庭一片叶，朝镜数茎丝。州县甘无取，丘园悔莫追。 \n 琼瑶生箧笥，光景借茅茨。他日青霄里，犹应访所知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉酬睢阳路太守见赠之作' AND p.poem_author = '高适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜春来·金装宝剑藏龙口', '张弘范', '元代', '金装宝剑藏龙口，玉带红绒挂虎头。绿杨影里骤骅骝。得意秋，名满凤凰楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜春来·金装宝剑藏龙口' AND p.poem_author = '张弘范';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山门', '孙承恩', '明代', '山门落日望江干，云树微茫晚色寒。\n欲向东风歌一曲，鹧鸪声里豆花残。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山门' AND p.poem_author = '孙承恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过杨老哨有感', '陈洪谟', '明代', '春水溶溶绿满湾，征夫荷锸有馀闲。承平已喜兵戈静，犹忆前年夜破关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过杨老哨有感' AND p.poem_author = '陈洪谟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('柳枝词十三首', '司马光', '宋代', '长门宫晓未成妆，结雨萦风蔽琐窗。\n莫令透人华梁燕，那堪负汝更双双。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '柳枝词十三首' AND p.poem_author = '司马光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古一百则 其一', '释正觉', '宋代', '一段真风见也么，绵绵化母理机梭。织成古锦含春像，无奈东君漏泄何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古一百则 其一' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天竺山居', '释斯植', '宋代', '对雨吟方稳，西风忽晚晴。\n野花沿涧白，秋意入帘清。\n浅水藏鱼影，重林隔磬声。\n是非尘外事，谁可继高名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天竺山居' AND p.poem_author = '释斯植';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔歌子·霅溪湾里钓鱼翁', '张志和', '唐代', '霅溪湾里钓鱼翁，蚱艋为家西复东。江上雪，浦边风，笑着\n荷衣不叹穷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔歌子·霅溪湾里钓鱼翁' AND p.poem_author = '张志和';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('千仙谣', '吴龙翰', '宋代', '衣缥缈，佩丁东。\n金茎滴香露，玉树生凉风。\n冲破青冥跨黄鹤，身披星斗珍珠络。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '千仙谣' AND p.poem_author = '吴龙翰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('扬州道上思念沈九娘', '唐寅', '明代', '相思两地望迢迢，清泪临门落布袍。\n杨柳晓烟情绪乱，梨花暮雨梦魂销。\n云笼楚馆虚金屋，凤入巫山奏玉箫。\n明日河桥重回首，月明千里故人遥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '扬州道上思念沈九娘' AND p.poem_author = '唐寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('墩上遣兴', '陶益', '明代', '长吟依林樾，大隐不姓名。心远邻犹阔，性狂世亦轻。\n\n幽花故故作，好鸟关关鸣。苦思成诗癖，谁怜太瘦生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '墩上遣兴' AND p.poem_author = '陶益';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过桐陵杨公平别业不遇', '刘崧', '明代', '门掩梨花听犬声，更无童子出相迎。逢人谩说山居好，强半春晴却在城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过桐陵杨公平别业不遇' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('览镜七首', '陶望龄', '明代', '食柏生香事有征，吾生物化岂无凭。\n笋乡嗜久枯同竹，梵夹翻多瘦亦僧。\n荤血断来余紫蓼，衣冠抛尽只朱藤。\n荒芜田业关何事，已种南湖十亩菱。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '览镜七首' AND p.poem_author = '陶望龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('久雨 其二', '李弥逊', '宋代', '榕根败屋两三椽，客径无人老更便。地近东南多泽国，雨逢甲子少丰年。\n\n径须酣饮六十日，安用取禾三百廛。待得风头风力□，梅花如雪月初圆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '久雨 其二' AND p.poem_author = '李弥逊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送吴兴太守卢给事赴兵部侍郎召四首以邦家之光为韵 其四', '刘一止', '宋代', '西雍拜颜色，振鹭俱分行。绣衣浙江滨，再上君子堂。\n\n首尾二十载，持橐侍明光。厌看南朝山，易绾吴兴章。\n\n煌煌朱两轓，照我梓与桑。怪我衫始青，怜我鬓已苍。\n\n颇复见劳苦，感慨激中肠。向来官如泥，葡萄换西凉。\n\n剪翎但鸣悲，坐阅百鸟翔。公为世良师，医国有禁方。\n\n颇闻药笼中，臭味久已尝。小草存远志，未用出声妨。\n\n采掇公弗疑，结根稔风霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送吴兴太守卢给事赴兵部侍郎召四首以邦家之光为韵 其四' AND p.poem_author = '刘一止';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('正仲思归作篆畦今夜月十诗非篆畦月乃雁苍月盖杜子美鄜州月之意也予作十章乃篆畦月也 其八', '舒岳祥', '宋代', '篆畦今夜月，政自使人怜。久废登山屐，愁催下濑船。\n\n衰年免黄帽，旧习守青毡。东浙承平地，如今是近边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '正仲思归作篆畦今夜月十诗非篆畦月乃雁苍月盖杜子美鄜州月之意也予作十章乃篆畦月也 其八' AND p.poem_author = '舒岳祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蜀葵', '颜延之', '南北朝', '井维降精，岷络升灵。物微气丽，卉草之生。喻艳众葩，冠冕群英。\n\n类麻能直，方葵不倾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蜀葵' AND p.poem_author = '颜延之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('访进士何斯复于歙北黄荆渡不值时斯复方以养亲告归', '程敏政', '明代', '问路寻君径出城，过桥自得绕溪行。小翻翠柳东风软，返射青山夕照明。\n\n为就江鱼长供母，暂容沙鸟一寻盟。前村种药归应晚，欲话心期恐未成。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '访进士何斯复于歙北黄荆渡不值时斯复方以养亲告归' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卫州', '许及之', '宋代', '河决从来国隐忧，卫州那在水边头。伤心中土沦胥久，可但堪嗟一卫州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卫州' AND p.poem_author = '许及之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('豪士', '喻良能', '宋代', '东海一豪士，西山两逸民。\n涕唾弃周粟，谈笑无秦军。\n饿死骨仍香，辞封名益芬。\n至今千载下，不敢轻隐沦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '豪士' AND p.poem_author = '喻良能';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送刘半千平阳簿', '欧阳修', '宋代', '岭梅归驿路迢迢，越鸟巢倾木半乔。\n松径就荒聊应召，桂丛留隐定相招。\n家庭噪鹊争喧树，夜帐惊猿自拥条。\n何处秋风催客鬓，青丝恐逐物华凋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送刘半千平阳簿' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四民诗 其四 商', '范仲淹', '宋代', '尝闻商者云，转货赖斯民。远近日中合，有无天下均。\n\n上以利吾国，下以藩吾身。周官有常籍，岂云逐末人。\n\n天意亦何事，狼虎生贪秦。经界变阡陌，吾商苦悲辛。\n\n四民无常籍，茫茫伪与真。游者窃吾利，堕者乱吾伦。\n\n淳源一以荡，颓波浩无津。可堪贵与富，侈态日日新。\n\n万里奉绮罗，九陌资埃尘。穷山无遗宝，竭海无遗珍。\n\n鬼神为之劳，天地为之贫。此弊已千载，千载犹因循。\n\n桑柘不成林，荆棘有馀春。吾商则何罪，君子耻为邻。\n\n上有尧舜主，下有周召臣。琴瑟愿更张，使我歌良辰。\n\n何日用此言，皇天岂不仁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四民诗 其四 商' AND p.poem_author = '范仲淹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('木兰花 五月二十三日晨起口占', '龙榆生', '近代', '灯前促膝情难了。负了深期躬自悼。此时凝望祇惭魂，他日相逢终脱帽。\n\n绿阴满院宜清晓。煦我朝阳无限好。要同飞跃答芳时，丢却背心尚未老。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '木兰花 五月二十三日晨起口占' AND p.poem_author = '龙榆生';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵三绝句 其二 阅江楼', '傅义', '当代', '空记君臣庆此楼，却供众庶享千秋。成王败寇俱何在？唯见长江滚滚流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵三绝句 其二 阅江楼' AND p.poem_author = '傅义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵', '刘攽', '宋代', '落泉无时休，泄云常自还。居然万峰秀，共此亭户间。\n\n擘华力何壮，凿陇巧已艰。造幽非近规，会心宁愧颜。\n\n朝扉面苍苍，夜枕听潺潺。莳以松桂丛，葱翠皆可攀。\n\n长歌发真赏，锦绣先斓斑。座客齐起予，清玉联玦环。\n\n夙龄慕远游，未能遍人寰。学仙理茫昧，遁俗事间关。\n\n风波天一隅，不到三神山。终当振衣往，对境聊自閒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵' AND p.poem_author = '刘攽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次致政李大夫郊步之韵 其一', '黄裳', '宋代', '垂髫孙子侍閒行，只此閒中度此生。偏是杜鹃能惬意，不如归去两三声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次致政李大夫郊步之韵 其一' AND p.poem_author = '黄裳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉使契丹二十八首其二十二学士院端午帖子二', '苏辙', '宋代', '九门已散秦医药，百辟初颁凌室冰。\n饮食祈君千万寿，良辰更上辟兵缯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉使契丹二十八首其二十二学士院端午帖子二' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('轿中疲甚作绝句', '虞俦', '宋代', '谢雨还如祷雨时，篮舆顿撼不胜疲。两回往返千馀里，禄马交驰恐应之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '轿中疲甚作绝句' AND p.poem_author = '虞俦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七歌效杜陵体 其五', '丘葵', '宋代', '富儿谐了西园债，身著绿衣足誇诧。那知又有价高人，昨日新官今日罢。\n\n近来书满只月馀，白头老吏慵送迓。呜呼五歌兮歌未足，末世由来多反覆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七歌效杜陵体 其五' AND p.poem_author = '丘葵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春晚即事', '曹勋', '宋代', '化国舒长日正迟，漫天风柳绿成姿。\n高低蝴蝶尚春色，零落荼醾犹晚枝。\n倦思有余时种竹，老怀无著强赓诗。\n人人一觉是非梦，但得百年犹此时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春晚即事' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('壬子初春有感', '毕自严', '明代', '荏苒春光去不还，朝来白发镜中斑。簿书扰扰成何事，返我山中学驻颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '壬子初春有感' AND p.poem_author = '毕自严';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三月晦日作 其四', '弘历', '清代', '拨剌文鳞戏玉津，清和景物一番新。若无来者应无去，我亦何须苦惜春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三月晦日作 其四' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉饯外舅之襄阳', '邓雅', '明代', '外舅襄阳去，江南草绿时。夕阳沙上酒，旧雨卷中诗。\n\n云断吴天隔，舟行楚岸移。浩歌明月上，长啸远风吹。\n\n到想春将尽，居应地最宜。鹿门深草木，汉水净凫鹥。\n\n庞老神仙宅，羊公德政碑。览奇应有作，感旧莫生悲。\n\n六矢男儿事，千金贾客赀。此行虽特达，早发故园思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉饯外舅之襄阳' AND p.poem_author = '邓雅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏怀 其六', '屈大均', '明代', '鼷鼠潜神丘，鹓雏集高枝。区区保性命，二虫曾何知。\n\n哲人无死地，所至福履绥。以兹七尺身，为君作蓍龟。\n\n赴义不返顾，成仁无推移。天狼纷下食，中土为肉糜。\n\n予为民请命，大呼起疮痍。事成天地悦，事败鬼神悲。\n\n乘道而浮游，无须驾鸾螭。妻孥乃敝屣，已矣从此辞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏怀 其六' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨中过苏 其一', '袁宏道', '明代', '二年前事似前朝，记得朱颜个里销。雨雨风风新震泽，车车马马旧虹桥。\n\n尘来不上双行脚，病后犹存一捻腰。是我万般辛苦地，如今闲话尽逍遥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨中过苏 其一' AND p.poem_author = '袁宏道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其七', '钱昭度', '宋代', '西北高楼在，东南王气销。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其七' AND p.poem_author = '钱昭度';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杨谨仲和顷者三诗见贻复次韵六首 其六', '赵蕃', '宋代', '不减浣花头，仍兼事事幽。浑忘帝城札，好在竹林游。\n\n有意求如愿，无机防海鸥。秋凉入吾树，旧读定能搜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杨谨仲和顷者三诗见贻复次韵六首 其六' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵如岳醵饮西峰寺分韵成诗十四首见寄 其十', '陈著', '宋代', '老佛眉閒屋漏愁，残廊脚下草光浮。谁能饥坐芦穿膝，莫问神通石点头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵如岳醵饮西峰寺分韵成诗十四首见寄 其十' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂二十一首 其七', '释坚璧', '宋代', '玉象吞狮子，泥牛上绣鞍。御楼观射猎，不是刈茆田。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂二十一首 其七' AND p.poem_author = '释坚璧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('启至大寨闻擒鬼章捷书上奏喜而为诗', '王纯臣', '宋代', '黄城匹马捷音来，且喜洮东破虏回。\n纵使淮西功第一，未闻生缚七渠魁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '启至大寨闻擒鬼章捷书上奏喜而为诗' AND p.poem_author = '王纯臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其一', '张励', '宋代', '莫言伯道无儿嗣，看取千秋祀事存。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其一' AND p.poem_author = '张励';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('如梦令', '杨炎', '明代', '新绿酿成杨柳，帘卷和风微透。独坐抱云和，香篆暗消金兽。\n\n回首，回首，花事春光依旧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '如梦令' AND p.poem_author = '杨炎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绮罗香 玉兰', '沈皞日', '清代', '夹竹来禽，药苗戏蝶，梨院浓阴时候。晓起笼烟，开遍亭台非旧。\n\n擘纤手、琼雪搓成，倩玉斧、水晶裁就。记临春、大舍歌残，满宫凉月漾罗袖。\n\n小楼曾见白燕，飞去花间莫辨，飞来还又。连理交枝，片片光凝清昼。\n\n为迎风、欲障屏山，乍掩映、冰绡云母。认疏篱、几点梅花，暗香真是瘦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绮罗香 玉兰' AND p.poem_author = '沈皞日';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('生还四首 其三', '张煌言', '明代', '本以扬旌去，胡为弃甲旋！名城空绣错，故老尽株连。\n\n百折终何补，千秋倘复怜！亦知收烬易，萧索愧金钱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '生还四首 其三' AND p.poem_author = '张煌言';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵弟茂通晚晴', '范浚', '宋代', '浮云卷尽绮霞明，藜杖扶行得晚清。\n斜日水边鸂鶒影，孤烟林外鹁鸠声。\n且从乐处安心地，可向艰时触志兵。\n幽意欲言言不得，因君聊复动诗情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵弟茂通晚晴' AND p.poem_author = '范浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人 其三 石榴花', '尤侗', '明代', '李家妹子陶家姊。甘逐封姨死。石家房老剩翾风。好把小名醋醋换红红。\n\n艳妆底事心如火。生日逢重午。萧郎笑插玉人头。问道留侬侬去若为留。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人 其三 石榴花' AND p.poem_author = '尤侗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('不忍池晚游诗 其八', '黄遵宪', '清代', '鸦背斜阳闪闪红，桃红人面薄纱笼。银鞍并坐妮妮语，马不嘶风人食风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '不忍池晚游诗 其八' AND p.poem_author = '黄遵宪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('御君兄内子妆阁被火敬唁以诗八首 其八', '王彦泓', '明代', '戒律精持事法王，清心高出宝莲香。但存冰雪孤标在，火宅何妨是道场。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '御君兄内子妆阁被火敬唁以诗八首 其八' AND p.poem_author = '王彦泓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其七', '李清照', '宋代', '所以嵇中散，至死薄殷周。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其七' AND p.poem_author = '李清照';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和树筠先生种花诗 其一', '何金江', '近代', '冰雪襟情暑不侵，竹深地接百花深。凭栏细读牺经句，恰得勿疑朋盍簪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和树筠先生种花诗 其一' AND p.poem_author = '何金江';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('百字令 为彦弘母夫人寿 以上三首见淡生堂抄', '华幼武', '元代', '人生七十，都道是、自古世间稀有。今日华堂，阿弥初度，更绵绵增寿。花柳呈妍香云霭，正好暮春时候。江山如画，百年风景依旧。最喜兰玉森森，彩衣齐拜，舞埙＊迭奏。罗绮香中蟠桃熟，争献瑶池王母。愧忝姻联倚庄椿，琼树岁寒长久。歌词一阕，敬称千岁春酒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '百字令 为彦弘母夫人寿 以上三首见淡生堂抄' AND p.poem_author = '华幼武';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄袁二丈二首 其一', '宗臣', '明代', '孤鸿不到海门烟，别后音书动隔年。江上暮云空复好，湖南新月为谁圆。\n\n怀人竟负看梅曲，卧病长歌采蕨篇。咫尺山阴飞早雪，可能一上剡溪船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄袁二丈二首 其一' AND p.poem_author = '宗臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋闺梦戍诗 其四', '马氏女（虎关）', '明代', '仰窥北斗认辽阳，一夕西风引梦长。罗袜路生难问信，石城烟绕怯停装。\n\n草青自判身为冢，塞黑俄惊骨似芒。正好相关商别恨，晓鸦啼散一天霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋闺梦戍诗 其四' AND p.poem_author = '马氏女（虎关）';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荷钱', '林鸿', '明代', '田田翠盖点清漪，非范非模迥出奇。自是天工陶铸巧，一番清富属冯夷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荷钱' AND p.poem_author = '林鸿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和寇十一晚登白门', '陈师道', '宋代', '重楼杰观屹相望，表里河山自一方。\n小市张灯归意动，轻衫当户晚风长。\n孤臣白首逢新政，游子青春见故乡。\n富贵本非吾辈事，江湖安得便相忘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和寇十一晚登白门' AND p.poem_author = '陈师道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谒金门', '黄侃', '近代', '归不得。玉树歌阑云黑。唤作主人原是客。青芜迷旧国。\n\n望断高楼西北。一片夕阳颜色。鶗鴂无声春事寂。鹧鸪飞又急。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谒金门' AND p.poem_author = '黄侃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('河间献王墓', '薛瑄', '明代', '汉家宗室最称贤，遗事曾经阅简编。偶过河间寻往迹，空馀荒冢带寒烟。\n\n频求千古书连帙，独对三雍策几篇。雅乐未兴人已逝，雄歌惟有大风传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '河间献王墓' AND p.poem_author = '薛瑄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('唐明皇', '张之洞', '清代', '正本安边有大猷，空谈吏治兔园流。请看安史蕃回乱，枉费颜元典郡州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '唐明皇' AND p.poem_author = '张之洞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春晚即事，留游子明、王仲显', '范成大', '宋代', '绣地红千点，平桥绿一篙。\n楝花来石首，毂雨熟樱桃。\n笑我生尘甑，惭君有意袍。\n故人能少驻，门径久蓬蒿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春晚即事，留游子明、王仲显' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('朝玉阶 樱桃', '张伯驹', '近代', '三月樱桃乍熟时，网铃轻结系，怕莺知。珠圆霞晕缀枝枝，还疑红豆子，惹相思。\n\n筠笼偷看美人携，鲜妍凝指甲，凤仙泥。销魂筵上唱新词，小唇香唾吐，破胭脂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '朝玉阶 樱桃' AND p.poem_author = '张伯驹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出火祀大辰十二首 亚、终献用《文安》。', '郊庙朝会歌辞', '宋代', '潜之伏矣，柞槱既休。有俶其来，榆柳是求。灵驾纷羽，尚其安留。\n\n饮我三爵，言言油油。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出火祀大辰十二首 亚、终献用《文安》。' AND p.poem_author = '郊庙朝会歌辞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('光泽道中纪事', '王佐（汝学）', '明代', '西来一水白练白，界破两山立其侧。两侧之山草树平，北侧之山石崖逼。\n\n我爱崖面平如掌，驻马磨崖写遗响。苍苔磨尽见石骨，隐隐古字石崖上。\n\n蛇虫缺裂蛟鼍断，欲读不成心眼乱。细寻体制何代书？彷佛八分兼小篆。\n\n秦欤汉欤此荒服，何有此字在我目。无乃唐末五代人，学得李蔡步其躅。\n\n四百年来已如此，天地无穷会更纪。凄凉往事不胜悲，且抱戎籍去综理。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '光泽道中纪事' AND p.poem_author = '王佐（汝学）';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日二首 其二', '孙觌', '宋代', '云巘曾棱路远苍，井梧萧瑟陨疏黄。浪浪一枕芭蕉雨，端为幽人滴夜长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日二首 其二' AND p.poem_author = '孙觌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送杨秋江归羊城', '陈琏', '明代', '冥鸿响瑶渚，秋声满江干。严霜悴百草，萧条风景寒。\n\n人生在知己，远别良独难。岂无绿绮琴，不忍向君弹。\n\n岂无白纻歌，歌来转辛酸。聊持一尊酒，暂结半日欢。\n\n酒醒愁复在，何如赠琅玕。琅玕世所重，分刻两佩环。\n\n一作双蟠螭，一作双回鸾。上可献天府，下可慰慈颜。\n\n愿君永佩之，佩之当佩兰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送杨秋江归羊城' AND p.poem_author = '陈琏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄邵判司隐君', '吴惟信', '宋代', '隐君住处枕湖滨，正与逋仙是密邻。踏雪访梅千嶂晓，带烟看柳满楼春。\n\n发因累少茎茎绿，诗为工多字字新。闻说近来浑懒出，竹光花影锁闲身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄邵判司隐君' AND p.poem_author = '吴惟信';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('睡起', '释道璨', '宋代', '青青岸草绿於袍，雨后江流数尽高。\n庭院日长春睡足，幽兰花底读离骚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '睡起' AND p.poem_author = '释道璨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('榕台', '郑岳', '明代', '过眉方竹杖，扶醉上榕台。万木横空绕，群峰到海回。\n\n桑麻怀栗里，笙鹤隐蓬莱。结社谁同调，白莲花正开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '榕台' AND p.poem_author = '郑岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题德如海上人听松轩', '陶宗仪', '元代', '定起忽闻风雨生，危枝只恐鹤巢倾。苍虬鼓鬣嘘天籁，翠浪掀空送海声。\n\n一派笙簧秋淅沥，千官环佩玉琮琤。我家亦有閒庭院，不及山窗分外清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题德如海上人听松轩' AND p.poem_author = '陶宗仪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('种说山居', '李复', '宋代', '隐君栾叶为清门，诛茅卜筑岁已深。\n池影青苍山堕地，松枝夭矫龙出林。\n六月取冰自凿谷，百壶进酒不论金。\n阮生熟醉无臧否，今爱遗风杜曲阴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '种说山居' AND p.poem_author = '李复';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('樊榭有南屏烧笋之约曰虽雨无阻哲旦竟雨予弗能赴也', '全祖望', '清代', '及时烧笋正不俗，况有花猪恣大嚼。此乐固应天所妒，黑云沈沈来作恶。\n\n老人即次怅萧寥，呼童买笋且永朝。出山入市风格减，冒雨莫怪诸公劳。\n\n生平雅志慕幽讨，其奈阴晴称心少。山灵定笑人无勇，此间清供雨亦好。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '樊榭有南屏烧笋之约曰虽雨无阻哲旦竟雨予弗能赴也' AND p.poem_author = '全祖望';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('粤游回里晤金粟香丈和其冰井诗原韵二首 其二', '夏孙桐', '清代', '耳热题襟集，俊游良不虚。名山欣面识，旧雨惜缘疏。\n\n感慨登楼赋，商量负郭居。松陵能结侣，息壤问江渔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '粤游回里晤金粟香丈和其冰井诗原韵二首 其二' AND p.poem_author = '夏孙桐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送邵仲象如吴下', '晁公溯', '宋代', '乃翁昔为校书郎，汗简所载日月光。\n今看太史牛马走，往见中朝鸳鹭行。\n南公闻名定倾盖，西府念旧当外堂。\n傥思泰定山下路，肯来从我无相忘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送邵仲象如吴下' AND p.poem_author = '晁公溯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('败荷鹡鸰图', '唐寅', '明代', '飞唤行摇类急难，野田寒露欲成团。\n莫言四海皆兄长，骨肉而今冷眼看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '败荷鹡鸰图' AND p.poem_author = '唐寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('癸未新正写怀二首 其二', '谢迁', '明代', '荒陬残腊煖如春，共道春来万象新。入夜刚风仍作雪，崇朝寒气苦侵人。\n\n六花如兆丰年瑞，四海犹怜蔀屋贫。安得重阴都散尽，仰瞻旭日丽苍旻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '癸未新正写怀二首 其二' AND p.poem_author = '谢迁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同惟敬诸丈邀刘观察集李园', '胡应麟', '明代', '楼阁凄凄云雾残，幽盟河朔此盘桓。庭催黄叶风交响，席倚青萍月共寒。\n\n一径秋光摇碣石，千门晴色绕长安。题诗剩有邹枚侣，并拂朱丝兴未阑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同惟敬诸丈邀刘观察集李园' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送付藏主', '释月涧', '宋代', '老我无堪涉世艰，鬓毛新糁雪霜斑。有人来自庐山中，眼如点漆音如钟。\n\n衔袖出新卷，两眼惊且眩。方知亲自香溪哥室来，老婆心切言诙诙。\n\n三世诸佛一口吞，一大藏教彻底翻。丛林乡社有此俊迈之英才，我辈可老可死无馀怀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送付藏主' AND p.poem_author = '释月涧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('禅人写真求赞 其四十九', '释正觉', '宋代', '谁能目眴眉扬，每笑手乱脚忙。守鲁祖之简默，得南泉之平常。\n\n明心秋月，活物春阳。铸机器也模范大小，据丛林也规矩圆方。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '禅人写真求赞 其四十九' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('固镇驿阻滞感述', '郭之奇', '明代', '蹇蹇趋王日，騑騑周道朝。时危贤者贱，世乱仆夫骄。\n\n敢自悲迟滞，如何驾远遥。晨林风鹊乱，昏树月乌噍。\n\n未静烟尘色，谁怜羽翼焦。穷途西日暮，酷昼午云烧。\n\n长息思原隰，饥心望阙朝。嗟嗟行役者，徒尔复歌谣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '固镇驿阻滞感述' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雷南阳郡斋夜饮', '欧大任', '明代', '淯城趋府日，召堰听歌来。出牧千年后，称诗七子才。\n\n白云留下榻，银烛照衔杯。谈笑能忘夜，更阑一骑回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雷南阳郡斋夜饮' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('女乘务员女乘务员', '聂绀弩', '近代', '长身制服袖尤长，叫卖新刊北大荒。主席诗词歌宛转，人民日报诵铿锵。\n\n口中白字捎三二，头上黄毛辫一双。两颊通红愁冻破，厢中乘客浴春光。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '女乘务员女乘务员' AND p.poem_author = '聂绀弩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('馀姚江上作先寄城中亲友', '苏泂', '宋代', '开禧改岁复峥嵘，老我奔驰不少宁。\n雪花欺人入衣袂，前日杭州今四明。\n老来老来我何有，绿发黄须行白首。\n鱼鳞年纪今岁是，挽之不住去如走。\n挽君不住知奈何，叩篷击楫聊高歌。\n天风为拍雪为舞，寒水自酌金叵罗。\n脚根根城不作难，且喜看尽湖中山。\n明朝还舍托朋旧，尚有新诗三百首。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '馀姚江上作先寄城中亲友' AND p.poem_author = '苏泂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阳羡杂咏十九首。桃花谷', '陆希声', '唐代', '君阳山下足春风，满谷仙桃照水红。 \n 何必武陵源上去，涧边好过落花中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阳羡杂咏十九首。桃花谷' AND p.poem_author = '陆希声';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋夜宿定水寺天香阁有怀见心长老', '丁鹤年', '元代', '寂寂双峰映涧流，重来托宿敞云楼。窗涵虚白三更月，帘捲空青一色秋。\n\n颇有高情酬胜赏，可无奇句入冥搜。天风开遍岩前桂，谁为烝香寄澹游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋夜宿定水寺天香阁有怀见心长老' AND p.poem_author = '丁鹤年';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上巳郡宴即事', '喻良能', '宋代', '细雨轻阴修禊天，海棠睡足柳初眠。\n凝香帘幕东风暖，小醉清吟锦瑟边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上巳郡宴即事' AND p.poem_author = '喻良能';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人十首 其三 梅与人', '崔荣江', '当代', '浮檐霜月和灯豆，照影凭窗瘦。有梅多似眼前人，应去暗香生处认前身。\n\n侬心亦是群芳妒，到了缘无主。著来纨素不沾尘，何日东风迢递小楼春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人十首 其三 梅与人' AND p.poem_author = '崔荣江';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('双湖竹枝词 其三', '全祖望', '清代', '春晚洋山鱼计盈。满湖小种亦神清。郎船夜旁竹洲宿，天半天封塔火明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '双湖竹枝词 其三' AND p.poem_author = '全祖望';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出塞杂咏用上平声韵 其十', '弘历', '清代', '日射高峰紫雾开，骖驔羽骑蔽山来。鸾旗影飏云林外，清跸声声北狩回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出塞杂咏用上平声韵 其十' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋至 其一', '罗洪先', '明代', '君子悲行役，行役别父母。时运促人老，山川惊险阻。\n\n悠悠南浦云，落落西山雨。感此不能欢，独立向江渚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋至 其一' AND p.poem_author = '罗洪先';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵和抑之寒食 其二', '白子仪', '宋代', '馀花茂草引醺酣，礼节休言爵止三。芳岁现逢虽强笑，少年相对但多惭。\n\n尚驱俗驾终何适，不辟愁门却未甘。难把长绳系春日，若非觞斝更谁堪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵和抑之寒食 其二' AND p.poem_author = '白子仪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阅汪文冶始信峰草堂纪略率题六绝 其六', '屈大均', '明代', '黄帝衣裳作海云，浮丘几席落花纷。遗书续取先司马，便与山灵建大勋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阅汪文冶始信峰草堂纪略率题六绝 其六' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('也作屈原打油 其二', '卢青山', '当代', '拿先生作挡羞牌，都是先生后世才。死人地下如能见，地下还须死一回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '也作屈原打油 其二' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白马井', '许康民', '宋代', '矍铄平生善用兵，论他薏苡得贪名。不因渴骥遗踪在，谁识将军到底清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白马井' AND p.poem_author = '许康民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陇头歌辞 其二', '佚名', '隋代', '朝发欣城，暮宿陇头。寒不能语，舌卷入喉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陇头歌辞 其二' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凯歌赠参将戚公 其一', '徐渭', '明代', '战罢亲看海日晞，大酋流血湿龙衣。军中杀气横千丈，并作秋风一道归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凯歌赠参将戚公 其一' AND p.poem_author = '徐渭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('率饮亭二十绝 其十三', '王十朋', '宋代', '结交虽不泛，绝物亦何曾。莫问亲疏客，过门无不应。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '率饮亭二十绝 其十三' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送唐友梅', '缪公恩', '清代', '目断衰杨倚驿桥，天连晴雪正萧萧。万泉河上重携手，恰待春风碧柳条。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送唐友梅' AND p.poem_author = '缪公恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寒食游南湖三首', '苏辙', '宋代', '春睡午方觉，隔墙闻乐声。\n肩舆试扶病，画舫听徐行。\n适性逢樽酒，开怀挹友生。\n游人定相笑，白发近従横。\n绕郭春水满，被堤新柳黄。\n官池无禁约，野艇得飞扬。\n浪泛歌声远，花浮酒气香。\n晚风归棹急，细雨湿红妆。\n携手临池路，时逢卖酒垆。\n柳斜低系缆，草绿荐倾壶。\n波荡春心起，风吹酒力无。\n冠裳强包裹，半醉遣谁扶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寒食游南湖三首' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水龙吟 赠李元法', '刘志渊', '元代', '绵绵一气冲关节。熏蒸遍流百脉。聚归乾鼎，象成龙虎，性情感结。精变高超越，功七返、九还无阙。炼成大药，通神显用，觉香味，遍身泄。焕吐丹光皎洁。晃灵台、一点如雪。常清常净，无馀无欠，圆明莹彻。显出真心月，射宇宙、了无尘屑。耸太虚法相，无生神妙，镇千万劫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水龙吟 赠李元法' AND p.poem_author = '刘志渊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七月十三日为先妣九十七岁冥诞，赋此志痛 其一', '刘凤梧', '近代', '缅维九七年今日，正是慈亲寿诞辰。卮酒未能坟上奠，繁霜空向鬓边生。\n\n儿于晚岁多忧患，母在重泉独苦辛。病卧匡床难扫墓，松楸凝望泪频倾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七月十三日为先妣九十七岁冥诞，赋此志痛 其一' AND p.poem_author = '刘凤梧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送窦秀才', '欧阳修', '宋代', '晴原高下细如鳞，树转城回路欲分。\n望月西楼人共远，跃鞍南陌草初薰。\n短亭山翠偏多叠，送目鸿惊不及群。\n一驿赋成应援笔，好凭飞翼寄归云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送窦秀才' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晓入龙华访憨山上人不遇', '杨起元', '明代', '闻说憨公到宝林，朝来乘兴一相寻。田间雪积平如掌，寺里钟稀寂似心。\n\n炉爇旃檀香细细，园开祇树字沉沉。由来此法应无住，不见空归义更深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晓入龙华访憨山上人不遇' AND p.poem_author = '杨起元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '王宏', '宋代', '青女横霜夜，神炉盛冻天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '王宏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陈嘉言送双鹤以诗遣之次韵为谢', '邵宝', '明代', '病后身轻欲御风，羽人谁遣过墙东。乾坤有地云随驭，日月多情鸟出笼。\n\n诗社几人时野服，使君五马古侯封。天机动我鸣还舞，更爱新巢在老松。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陈嘉言送双鹤以诗遣之次韵为谢' AND p.poem_author = '邵宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('兰陵王 芦花，和麟楥', '朱祖谋', '清代', '竟头白。明镜秋霜共色。荒埼外、摇露荡烟，零乱春丛换凄碧。\n\n江湖味惯识。牢落低舷倦笛。黄昏后，无处顿愁，愁似潮来夜风急。\n\n伊人旧游历。在买醉鱼天，分社鸥席。凉花浅濑秋无极。\n\n自湿渍衫絮，怨沈笳管，离披天水断梦失。甚身世禁得。\n\n江国。待将息。怕如画烟波，皴破铅墨，沈阴断雁声中黑。\n\n黯雪片千顷，欲衔无力。菰蒲何处，岁暮约，但睡忆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '兰陵王 芦花，和麟楥' AND p.poem_author = '朱祖谋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('述怀五十三首 其五十二', '周是修', '明代', '登山采灵草，悠悠念长生。长生不可念，且遂探芳行。\n\n旷哉秦台子，双声调玉笙。清商汎穹昊，鸾凤感和鸣。\n\n倏尔凌空去，眇若秋云轻。徒令企望者，苍然热五情。\n\n世间荣辱梦，终古未应醒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '述怀五十三首 其五十二' AND p.poem_author = '周是修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题镇远何贰守东岩四咏用林见素韵 其一 南亩春耕', '周瑛', '明代', '鸡鸣桑树深，犬卧苔花湿。何处课春耕，独倚斜阳立。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题镇远何贰守东岩四咏用林见素韵 其一 南亩春耕' AND p.poem_author = '周瑛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('弇山园逢沈嘉则席上见赠漫赋长句为答用纪兹会之盛', '张元凯', '明代', '西园汇才彦，主人陈思王。式燕芙蓉池，言解翡翠裳。\n\n坐临秋水弄皎月，澄觞飞盖生明光。遂令花萼寄缃素，髣髴箫管遗琳琅。\n\n后来盛事谁则同，弇园开在娄水东。宾主曹刘日方驾，羽翼风雅何冲融。\n\n何来四明有狂客，亦与七子相争雄。萧然入林共把臂，便觉松下生清风。\n\n杯酒相逢即定交，袖中投我以琼瑶。漫试千言在倚马，独工五字能射雕。\n\n山云恍披鹔鹴锦，池水忽涨桃花潮。座有玉山多自欹，况复错落飞金卮。\n\n高柯惊动灵鹊起，长川澹荡天河移。后人艳说今日会，却如今视西园时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '弇山园逢沈嘉则席上见赠漫赋长句为答用纪兹会之盛' AND p.poem_author = '张元凯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乌夜啼 寿茹母七十词', '王立道', '明代', '二月春添富贵，千秋人对芳菲。朱颜绿发金尊里，笑道古来稀。\n\n柳外歌传金缕，花前舞衬斑衣。瑶池宴是承欢处，此日报春晖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乌夜啼 寿茹母七十词' AND p.poem_author = '王立道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春晓', '蒋主孝', '明代', '春阳未出海，春风已到楼。忽闻啼鸟唤，忙整玉搔头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春晓' AND p.poem_author = '蒋主孝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三峰嵓真寺重修法堂', '解缙', '明代', '嵓真之峰青插天，中有佛手盘之圆。佳花美竹秀以娟，艳艳嵓窟开金莲。\n\n大雄楼殿虬龙骞，禅伯歌笑云里眠。昔年曾此书石镌，当时宾客何骈阗。\n\n即今一十有七年，梵宇咸备施周垣。矧有馀力及福田，离相兴国危复存。\n\n两贤高谊古所敦，仁爱吾儒将赧然。天龙守护鬼神跧，坐看沧海思绵绵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三峰嵓真寺重修法堂' AND p.poem_author = '解缙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和沈休文双溪八咏 其四', '戴良', '元代', '寒来悲落桐，桐生在长林。积叶既阿那，攒条复萧森。\n\n排云正孤立，乘风忽哀吟。朽壤方有托，急霰非所任。\n\n轮囷龙门侧，憔悴峄山岑。不求削成圭，何待裁作琴。\n\n菲薄既非材，固无斤斧侵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和沈休文双溪八咏 其四' AND p.poem_author = '戴良';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽马章民年丈二首 其一', '张玉书', '清代', '东庐旧筑翠微间，望里烟霞日夕还。几度欲归归未得，空馀遗恨满青山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽马章民年丈二首 其一' AND p.poem_author = '张玉书';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙', '陈允平', '宋代', '十二珠帘绣带垂。柳烟迷暗楚江涯。自携玉笛凭丹梯。 \n 写恨鸾笺凝粉泪，踏青鸳袜溅金泥。落红深处乱莺啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙' AND p.poem_author = '陈允平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贵妃閤端午帖子 其一', '许应龙', '宋代', '撷秀斗群芳，兼收百药良。不因仁及物，庶草曷蕃昌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贵妃閤端午帖子 其一' AND p.poem_author = '许应龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月·卧化胜如坐化', '马钰', '元代', '卧化胜如坐化，修行所贵真常。假躯难以做馨香。何必临归著要。说破飞升一著，成仙只是神光。天宫无用臭皮囊。携去深山掉样。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月·卧化胜如坐化' AND p.poem_author = '马钰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('如梦令', '石声汉', '近代', '海上乍生圆月。舷底卷来霏雪。天半数秋星，惊起晚风幽咽。\n\n凄绝。凄绝。乡梦未成还灭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '如梦令' AND p.poem_author = '石声汉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('牛柴', '胡健', '清代', '漫云牛后逊鸡声，粪出呼柴亦令名。跨灶人惊烟缕缕，登山谁听斧丁丁。\n\n输他榾柮原无累，剩得扊扅更有情。虽不用燔郊上帝，力能调鼎著和羹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '牛柴' AND p.poem_author = '胡健';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('恒德斋为开府明良公作 其一', '吴当', '元代', '于穆天命，恒久不已。往禅来续，与道为体。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '恒德斋为开府明良公作 其一' AND p.poem_author = '吴当';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杪秋登太华山绝顶 其三', '李攀龙', '明代', '太华高临万里看，中原秋色更漫漫。振衣瀑布青云湿，倚剑明星白日寒。\n\n东走峰阴摇砥柱，西来紫气属长安。自怜綵笔惊人在，只尺天开谒帝难。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杪秋登太华山绝顶 其三' AND p.poem_author = '李攀龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('代简寄扬州杨孝子锜', '湛若水', '明代', '维扬过客已知名，孝子旧为族党称。便合首科逑闵冉，闭门闹市坐懵腾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '代简寄扬州杨孝子锜' AND p.poem_author = '湛若水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书事二首', '刘克庄', '宋代', '空空都没一行书，行行徒矜九尺躯。\n面上带妖真可耻，脚中有鬼不容扶。\n末年铁拐传仙诀，他日金锥抉冢珠。\n泉下定为明允笑，果能看破半山无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书事二首' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暮雨', '谢榛', '明代', '坐听萧萧急，无风池亦波。庭花秋几许，窗雨夜偏多。\n\n老矣乡关梦，悲哉燕赵歌。不须临晓镜，空自叹蹉跎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暮雨' AND p.poem_author = '谢榛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('招旧游', '陈子升', '明代', '游情向春鸟，鸟语在庭柯。我罢归欤叹，谁为劳者歌。\n\n青春将进酒，白日倩挥戈。何不还携手，高高藏绿萝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '招旧游' AND p.poem_author = '陈子升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('折县道中二首', '孔武仲', '宋代', '柳堤桃坞未怡融，浣濯新梢上浅红。\n一段春光来逼眼，枣骝嘶入柏林中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '折县道中二首' AND p.poem_author = '孔武仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蚕丛祠', '汪元量', '宋代', '西蜀风烟天一方，蚕丛古庙枕斜阳。\n茫然开国人天主，彷佛鸿荒盘古王。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蚕丛祠' AND p.poem_author = '汪元量';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水心即事六乎兼谢吴民表宣义', '叶适', '宋代', '吴翁肥遁逾七十，朮老芝荒手自锄。\n惠我篇章成锦字，西邻得伴亦堪书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水心即事六乎兼谢吴民表宣义' AND p.poem_author = '叶适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵校官', '韩淲', '宋代', '要底劳生醉即休，从他势利有包羞。秋高野外空环堵，月满城时定倚楼。\n\n平揖山光明绝巘，净摇溪影转沧洲。可怜儿辈知陶写，丝竹何如且茗瓯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵校官' AND p.poem_author = '韩淲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题可兰卷', '薛侃', '明代', '清者未必罄，罄者未必清。谁是清罄者，清罄自有情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题可兰卷' AND p.poem_author = '薛侃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阿那曲 舟中待友', '李明岳', '明代', '几回闲夜停机杼，支枕蓬窗风许许。吹尽苹香不见人，绕塘寒月痈癗语。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阿那曲 舟中待友' AND p.poem_author = '李明岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花 其八', '王之道', '宋代', '杏靥桃腮俱有腼。常避孤芳，独斗红深浅。犯雪凌霜芳意展。\n\n玉容似带春寒怨。\n\n分得数枝来小院。依倚铜瓶，标致能清远。淡月帘栊疏影转。\n\n骚人为尔柔肠断。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花 其八' AND p.poem_author = '王之道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题从叔述灵岩山壁', '孟郊', '唐代', '换却世上心，独起山中情。露衣凉且鲜，云策高复轻。 \n 喜见夏日来，变为松景清。每将逍遥听，不厌飕飗声。 \n 远念尘末宗，未疏俗间名。桂枝妄举手，萍路空劳生。 \n 仰谢开净弦，相招时一鸣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题从叔述灵岩山壁' AND p.poem_author = '孟郊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('师山即事', '陈式金', '清代', '海外新沙井字格，万条沟水万条陌。芦花满目太苍茫，百载桑田地初辟。\n\n水中筑屋类浮舟，芦壁茅堂环小沟。沟外锄田田护宅，星分棋布大荒陬。\n\n一日双餐麦糜食，高梁黍稷并相餩。莫嫌粗粝难下咽，力倍南人健脚力。\n\n奔腾掀播独轮车，愁煞相冲误堕渠。晴日骄阳忧太酷，阴云又虑湿尘袪。\n\n民心狉獉能知辱，士好廉隅多款曲。尚气每多成讼端，破家毁宅连亲属。\n\n吾家泛宅一逾年，初喜民情弱可怜。黑夜鸣锣阻捐产，温纯风俗亦移迁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '师山即事' AND p.poem_author = '陈式金';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又成父弟往馀干谒赵叔遂至池阳庐陵谒二周先生长句送行', '赵蕃', '宋代', '归我山中未一年，两回题子送行篇。况今客路飞红叶，不比春风啼杜鹃。\n\n东阁翘材嗟久阔，长沙夜席已喧传。子行历聘应兄问，并谢江东有二天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又成父弟往馀干谒赵叔遂至池阳庐陵谒二周先生长句送行' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日有感', '陈肇兴', '清代', '咄咄缘何事，伤心独倚栏。十年回首处，万感上眉端。\n\n燕雀巢虽稳，豺狼驭尚难。忧天空涕泣，无力障狂澜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日有感' AND p.poem_author = '陈肇兴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹊桥仙 蒙城舟中读云臣蝶庵词', '陈维崧', '清代', '满河伧楚，盈船蒜酪，郁郁吾其谁语。江东词客盛如云，别去伴、长淮盐估。\n\n红莲半绽，碧鲈正得，醉任无情今古。读完半卷蝶庵词，吹铁笛、洒然而去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹊桥仙 蒙城舟中读云臣蝶庵词' AND p.poem_author = '陈维崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日杂题 其三', '唐之淳', '明代', '一泓清水古时河，洗马归来饮橐驼。不信边州住多日，胡儿头唱汉儿歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日杂题 其三' AND p.poem_author = '唐之淳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('茶洋舟中', '佘翔', '明代', '溪烟飞漠漠，久客荡归舟。水落滩声急，天寒曙色浮。\n\n风尘孤剑暗，戎马十年愁。翻怪乡园近，伤心是旧游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '茶洋舟中' AND p.poem_author = '佘翔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十日早朝寒甚', '陆深', '明代', '寒重春犹勒，风回雪未消。旂常悬日月，殿阁迥云霄。\n\n卿相恭寅协，君王视早朝。天颜殊有喜，胪唱飏箫韶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十日早朝寒甚' AND p.poem_author = '陆深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一蝉', '陈振家', '当代', '炎风如炙火烧天，遍野无人噪一蝉。花木垂头犬伸舌，恁般吆喝欲谁怜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '一蝉' AND p.poem_author = '陈振家';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮', '李荃', '清代', '东风乍染青青柳，休教攀折离人手。嫩绿未成阴，几丝春意侵。\n\n黄鹂栖不住，毕竟还飞去。欲却不胜情，频啼三两声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮' AND p.poem_author = '李荃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百零一首 其十七', '释慧性', '宋代', '毒蛇头上能揩痒，正是吾家跳灶儿。窃得这些穷伎俩，白拈手里觅便宜。\n\n万仞崖头独足立，头长三尺知是谁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百零一首 其十七' AND p.poem_author = '释慧性';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉楼春', '李邴', '宋代', '一年适尽莲花漏，翠井屠苏沈冻酒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉楼春' AND p.poem_author = '李邴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李白问月图为巡按吴天弘侍御赋', '程敏政', '明代', '山东李白真王孙，天才逸若天马奔。醉中双眼俯八极，弄月似扣玻瓈盘。\n\n安得长江化春酒，诗成百篇供一斗。拔取蟾宫玉兔毫，为副金銮草麻手。\n\n江月空明山月高，停杯一问歌声豪。贺监归湖郭令远，寂寞当时宫锦袍。\n\n文章万古光不歇，过眼清光几圆缺。世间欲访谪仙人，煜煜长庚皎如月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李白问月图为巡按吴天弘侍御赋' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山中道士居', '释文珦', '宋代', '寂寂老仟家，苍山一迳斜。\n还丹延日月，洞府足烟霞。\n野鹤千年寿，灵桃风度花。\n岂知人世上，尘事乱如麻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山中道士居' AND p.poem_author = '释文珦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('畜蜂', '黄衷', '明代', '偶营蜂蜜庐，颇蒙嗜甘訾。孰知甚么质，厥赋浑至理。\n\n作则贻君臣，事述关尹子。臭味惟馨香，逐膻恶丛蚁。\n\n禦侵厉繁虿，鸣衙若刻晷。况闻古将旗，义法屯队起。\n\n我观采芳来，精白尤足纪。充腹凡花须，王供负荣蕊。\n\n分窠首夏间，千百一攸止。其王苟摧伤，狼藉群命委。\n\n西林莳药畦，幽色杂万蘤。纷披纵垂芒，鲜洁脾最美。\n\n嗟嗟饴贩夫，锥刀日中市。平生嚼蜡翁，道心谅如水。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '畜蜂' AND p.poem_author = '黄衷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拜谢霍松林教授赠书', '何永沂', '当代', '漫卷诗书喜欲狂，未知何以报琳琅。吾徒久羡名山业，不梦红楼白玉堂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拜谢霍松林教授赠书' AND p.poem_author = '何永沂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山中吟', '陈允平', '宋代', '平生独爱山，日日频跻攀。\n自得山中趣，结庐万山间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山中吟' AND p.poem_author = '陈允平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南海梁宗烈枉顾定山有诗和之 其一', '庄昶', '明代', '何处芒鞋步欲穿，几钱还上过江船。戴将笠影江门上，来照溪云活水边。\n\n古气看来元自别，新诗拈出尽堪传。青山可到南川外，更结斯人万古缘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南海梁宗烈枉顾定山有诗和之 其一' AND p.poem_author = '庄昶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹', '吴宽', '明代', '种处能招凤鸟来，月明清影拂书堆。\n笋鞭遇石犹斜出，花米逢春莫乱开。\n此物似贤今合荐，吾家医俗旧曾栽。\n若从后圃论高节，梨白桃红孰取材。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹' AND p.poem_author = '吴宽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀人绝句十六首 其七 小山先生', '严古津', '近代', '江头把酒细论文，师友相兼合是君。一样怀人并得句，陶潜卷里有停云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀人绝句十六首 其七 小山先生' AND p.poem_author = '严古津';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苦西北二江大水伤稼 其一', '霍与瑕', '明代', '清入西郊景色熙，无端新潦稻花稀。拍天巨浸兼潮涌，远浦归舟带雨飞。\n\n野水乱浮凫鸭阵，东风时洗鹭鹚衣。诘朝定有晴明日，且唱山歌掩晚扉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苦西北二江大水伤稼 其一' AND p.poem_author = '霍与瑕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梧桐影', '薛琼', '清代', '月欲斜，风偏冷。秋思邻家分得来，隔墙移过梧桐影。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梧桐影' AND p.poem_author = '薛琼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荷叶杯 帘外', '卢前', '近代', '帘外雾烟笼月。呜咽。最是暮潮生。浪花从此暗吞声。\n\n夜夜绕孤城。\n\n几个隔江商女。如许。犹唱后庭花。休将流水劝栖鸦。\n\n明日又天涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荷叶杯 帘外' AND p.poem_author = '卢前';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('池阳四咏', '周必大', '宋代', '天遣江山助牧之，谢材犹及杜筠儿。\n向来稍喜唐风集，今信樊川是父师。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '池阳四咏' AND p.poem_author = '周必大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('禅人并化主写真求赞 其三五三', '释正觉', '宋代', '明白无根，茫茫月魂。清虚不浑，苍苍秋痕。青天固可背负，诸佛等闲口吞。\n\n情空超物物，妙触应门门。了知初不由心念，金色头陀灭意根。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '禅人并化主写真求赞 其三五三' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋月', '祝允明', '明代', '铢衣犹是旧霓裳，带得清虚府里香。\n今日轻分三万斛，乞他人世绿衣郎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋月' AND p.poem_author = '祝允明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('尘上人出丐求颂', '释正觉', '宋代', '轻轻弹指便开门，百亿门前百亿身。\n妙应因缘通处处，圆明个事遍尘尘。\n华间蜂採黄须蜜，柳上莺传青眼春。\n归日相呼满钵饭，一时分付饱参人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '尘上人出丐求颂' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读听雨兄与人绝交书赋此以寄', '吴金水', '当代', '一石千重漾碧澜，雄文今夕动诗坛。瑰奇笔压嵇中散，磊落情高管幼安。\n\n麋鹿只同猿鹤伴，花林不耐雀鸦攒。何时把酒西山下，闲看杉松度岁寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读听雨兄与人绝交书赋此以寄' AND p.poem_author = '吴金水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('由妙庄严路至普济寺三章 其二', '姚燮', '清代', '不履中极高，安知下方窘？置我太始间，神驹气为靷。\n\n朝海群岫严，缠天万松紧。华虹骁将旗，璎云上台衮。\n\n山门作扇开，若恐曜灵隐。石乳多溽烟，蒸为五色菌。\n\n往结永寿缘，回顾玉堂近。汉代梅南昌，于何类潜蚓？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '由妙庄严路至普济寺三章 其二' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送别白楼先生次郭司业韵', '边贡', '明代', '晓骑传中旨，春曹陟上卿。乐推吴季札，经许郑康成。\n\n车马秋江出，乡邦昼锦行。论交袜始结，惜别盖初倾。\n\n拜手双龙阙，承恩五凤城。御阶听曳履，枢密待持衡。\n\n制作登三殿，声华振八瀛。新班岱岳重，旧寺雪山轻。\n\n古貌看常健，冰衔列自清。英英伯夷志，垂白转精明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送别白楼先生次郭司业韵' AND p.poem_author = '边贡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('袁伯长虞伯生约重赋次其韵', '贡奎', '元代', '长江西来生远洲，极目凝作人间秋。奇峰列笋拔地起，晴岚积翠凌空浮。\n\n当时怀抱真快事，笑拨短棹随凫鸥。乘清弄影歌窈窕，洗净万斛黄尘愁。\n\n风涛击岸石欲裂，日月出海云还收。别来閒身堕羁束，抚手叹惜年光流。\n\n高侯胸中蟠景概，落笔肯为仙翁留。神工超出八极表，下视海岳如浮沤。\n\n至人不遣魂作梦，咫尺已足穷追搜。我爱题诗招靖节，况有二子鸣相酬。\n\n便当开樽醉其下，髣髴领□为鳌头。苍烟历历辨庐屋，丹树烨烨明林丘。\n\n安得高侯数相见，添写一叶南归舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '袁伯长虞伯生约重赋次其韵' AND p.poem_author = '贡奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠申凤梅', '舒庆春', '近代', '东风骀荡百花开，越调重兴多俊才。香满春城梅不傲，更随桃李拜师来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠申凤梅' AND p.poem_author = '舒庆春';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('历下秋夕', '汪广洋', '明代', '掖垣嘉禾秀，秋实何其蕃。天迥月争彩，风凉露渐繁。\n\n疏蛩鸣唧唧，惊鹊去翻翻。坐久愈岑寂，幽怀谁共言。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '历下秋夕' AND p.poem_author = '汪广洋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜算子（咏梅）', '朱淑真', '宋代', '竹里一枝斜，映带林逾静。雨后清奇画不成，浅水横疏影。 \n 吹彻小单于，心事思重省。拂拂风前度暗香，月色侵花冷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜算子（咏梅）' AND p.poem_author = '朱淑真';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史下·刘琨', '陈普', '宋代', '刘琨忠孝君亲念，急切不似令狐泥。\n亡身自是缘声色，须把初心看匹磾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史下·刘琨' AND p.poem_author = '陈普';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同袁通判游越中三首·鸿禧观', '陈著', '宋代', '停舟过桥去，两岸绿垂杨。\n绕屋水为界，入门花满廊。\n如今为道观，闻昔是书堂。\n此意与谁说，春风湖渺茫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同袁通判游越中三首·鸿禧观' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游白水寺', '程敏政', '明代', '几曲晴纱不受尘，望中云近绿杨津。峰腰屏足疑无地，谷口闻声忽有人。\n\n静爱寺山青隐隐，圣传池水白粼粼。同来宗契兼乡契，病酒无妨更一巡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游白水寺' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四臣咏 其四 海忠介瑞', '陈子升', '明代', '刚峰实无欲，奚止金百鍊。开府肃钟山，正冠是铁面。\n\n渡海漱波涛，昭天彻雷电。权奸昔已惊，顽懦咸追羡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四臣咏 其四 海忠介瑞' AND p.poem_author = '陈子升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄陈使君抑之', '吴兆', '明代', '海南无雁亦无秋，万里何人寄远愁。\n寂寂孤眠淮上月，凭风吹梦到罗浮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄陈使君抑之' AND p.poem_author = '吴兆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月·醉透香浓斗帐', '李之仪', '宋代', '醉透香浓斗帐，\n灯深月浅回廊。\n当时背面两伥伥，\n何况临风怀想。\n\n舞柳经春只瘦，\n游丝到地能长。\n鸳鸯半调已无肠，\n忍把么弦再上。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月·醉透香浓斗帐' AND p.poem_author = '李之仪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('张饶州允抡山中弹琴', '顾炎武', '清代', '赵公化去时，一琴遗使君。五年作太守，却反东皋耘。\n\n有时意不惬，来蹑劳山云。临风发宫商，二气相絪缊。\n\n可怜成连意，空山无人闻。我欲从君栖，山厓与海濆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '张饶州允抡山中弹琴' AND p.poem_author = '顾炎武';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜雨不睡 其二', '郑清之', '宋代', '少日无欢老易愁，莺花过眼一春休。清虚未解穷聃释，情思谁能更孔周。\n\n白醉暂烦檐送暖，苍颜惟恐镜包羞。争知一点天然物，不共浮生作去留。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜雨不睡 其二' AND p.poem_author = '郑清之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('云间徐生故同年少司寇公之少子也挟其艺应试南都乞余诗赠之', '王世贞', '明代', '孺子南州彦，徐卿第几雏。家声仍雁塔，国艺向鸿都。\n\n西弄花堪摘，长干酒可沽。如过爽鸠署，能记履声无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '云间徐生故同年少司寇公之少子也挟其艺应试南都乞余诗赠之' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('惜红衣 送中央在港考选海军新生飞渝入学，和白石', '杨玉衔', '清代', '牢补亡余，牖营暇日。绸缪心力。树木十年，桐材挺新碧。\n\n横汾下濑，期有待、昆明池客。风寂。蛮海昼眠，让痴龙苏息。\n\n东沟旧陌。折戟沈沙，猿虫瓦尸藉。楼船一霎水国。\n\n殉溟北。屈指拜登君赐，讵等斗星扪历。要弄潮儿健，优狎近蓬风色。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '惜红衣 送中央在港考选海军新生飞渝入学，和白石' AND p.poem_author = '杨玉衔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日园居', '梁元柱', '明代', '移来树色刚馀亩，占得春光满十分。兴到邻酤能举白，诗成新柳足张军。\n\n三三径曲驯皋鹤，摺摺墙低度懒云。倩取东风频干当，一尊橘杏小蓝君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日园居' AND p.poem_author = '梁元柱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('招竹元珍赏江洲新茶', '孔武仲', '宋代', '我生世味薄，所好唯真茶。\n江南隔浮云，庐岳望苦赊。\n煎烹逐风士，白水和脂麻。\n有客自远至，开缄得新芽。\n乍见真邂逅，失喜成欢哗。\n掬视未及饮，清香破昏邪。\n堂堂京邑雄，万货来天涯。\n念此至灵草，崎岖亦随车。\n小磨元自携，莹白无纤瑕。\n玉尘渐委积，鹰嘴犹交加。\n汲泉方汙埃，上以密叶遮。\n蟹眼已鸣沸，君来何晚耶。\n相呼共一啜，如到神仙家。\n烦襟得浣濯，两目祛昏花。\n闲居无他乐，赖有此趣佳。\n煌煌金张门，酒肉争豪奢。\n冷淡不辄饮，千金赏筝琶。\n一醒又五斗，颜角如烘霞。\n蔗浆爽肺肝，金碗嗽齿牙。\n坐觇吾曹癖，往往笑以嗟。\n人生乐不同，未用相矜夸。\n吟罢腹饥吼，空庭噪昏鸦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '招竹元珍赏江洲新茶' AND p.poem_author = '孔武仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江亭夕望', '白居易', '唐代', '凭高望远思悠哉，晚上江亭夜未回。日欲没时红浪沸， \n 月初生处白烟开。辞枝雪蕊将春去，满镊霜毛送老来。 \n 争敢三年作归计，心知不及贾生才。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江亭夕望' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送罗养明还江右 其一', '陈献章', '明代', '长寄湖西梦里身，扁舟春早忽相寻。乾坤自古悲难合，伯仲而今契亦深。\n\n草色正催公子醉，花枝不称老年心。何须袖却鸳鸯手，更向沧溟问我针。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送罗养明还江右 其一' AND p.poem_author = '陈献章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻友人言林茂之先生尚未能葬', '王士禄', '清代', '多寿林那子，风尘道漫尊。暮年双眼暗，儿日一钱存。\n\n死阙黔娄谥，生悲杜甫魂。桐棺还地上，何处故人恩？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻友人言林茂之先生尚未能葬' AND p.poem_author = '王士禄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿东谿王屋李隐者', '岑参', '唐代', '山店不凿井，百家同一泉。晚来南村黑，雨色和人烟。 \n 霜畦吐寒菜，沙雁噪河田。隐者不可见，天坛飞鸟边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿东谿王屋李隐者' AND p.poem_author = '岑参';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送黄彦七告假归省', '符锡', '明代', '青袍远适非趋隐，明到南中忆帝乡。江海故人多慰籍，莫言衰病老逢唐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送黄彦七告假归省' AND p.poem_author = '符锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题扇', '唐际虞', '清代', '花雾冥冥动远思，春葱按遍玉参差。银河不隔红窗路，坐到东溟月上时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题扇' AND p.poem_author = '唐际虞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绍兴亲享明堂二十六首', '佚名', '隋代', '于穆帝临，至矣元造。\n克配其得，惟我文考。\n仁恩广罩，栾叶永保。\n宗祀惟初，以扬孝道。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绍兴亲享明堂二十六首' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('休暇东斋', '韦应物', '唐代', '由来束带士，请谒无朝暮。公暇及私身，何能独闲步。 \n 摘叶爱芳在，扪竹怜粉污。岸帻偃东斋，夏天清晓露。 \n 怀仙阅真诰，贻友题幽素。荣达颇知疏，恬然自成度。 \n 绿苔日已满，幽寂谁来顾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '休暇东斋' AND p.poem_author = '韦应物';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('还通上人卷', '王之道', '宋代', '格清词苦与谁论，攜绕钱塘给事坟。\n所得岂容人继和，朗吟应被鹤听闻。\n月轮冷照千岩雪，霞片轻装万叠云。\n投向吾庐卜知己，拟将诗草为师焚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '还通上人卷' AND p.poem_author = '王之道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('刺贾秋壑诗', '咸淳士人', '宋代', '深院无人草已荒，漆屏金字尚煇煌。\n只知事去身宜去，岂料人亡国亦亡。\n理考发身端自有，郑人应梦果何祥。\n卧龙不肯留渠住，空使晴光满画墙。\n事到穷时计亦穷，行此难倚鄂州功。\n木棉庵上千年恨，秋壑堂中一梦空。\n石砌苔稠猿步月，松庭叶落鸟呼风。\n客来未用多惆怅，试向吴山望故宫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '刺贾秋壑诗' AND p.poem_author = '咸淳士人';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('边城秋感九首 其四', '戴亨', '清代', '辽海西陵道路长，提封万里隔严疆。百年芳草迷归梦，几处寒砧动早霜。\n\n云压秦关山叠叠，风驱胡燕海茫茫。生还有愿何时遂，沈水西流昼夜忙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '边城秋感九首 其四' AND p.poem_author = '戴亨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('集唐六绝送骆见羲广文归延津 其四 李涉', '林熙春', '明代', '白首垂丝恨不违，玉壶春酒正堪携。离心日远如流水，泣向东风忆建溪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '集唐六绝送骆见羲广文归延津 其四 李涉' AND p.poem_author = '林熙春';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山谷诗集有题净因寺壁二绝句未知寺在何处甲', '曾丰', '宋代', '三向稚松争短长，西偏老竹绝炎凉。\n千寻以上有秋色，万亩之间无夕阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山谷诗集有题净因寺壁二绝句未知寺在何处甲' AND p.poem_author = '曾丰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂三十四首 其三十五', '释如净', '宋代', '秋风凉，岩桂香。未归客，思故乡。吾无隐乎尔，捉贼须捉赃，舞蝶游蜂过短墙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂三十四首 其三十五' AND p.poem_author = '释如净';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹰山', '陶锐', '清代', '连山姿飞腾，万状纷罗萃。其中踞苍鹰，森然欲离地。\n\n石骨露细筋，峰铓磨利翅。狐兔失窟穴，鸠鹊凛然退。\n\n我来及早春，飒飒高秋气。乱流走白沙，寒草少青翠。\n\n侧足不敢扪，摘绦疑可试。化工妙写生，肖物神奸备。\n\n舆图考未详，支筇聊适意。他时风雨来，毋令鞲脱臂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹰山' AND p.poem_author = '陶锐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠承天理上人方池', '文嘉', '明代', '高僧住畔有方池，片片慈云映碧漪。长日诵经临水坐，鸟啼花落不曾知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠承天理上人方池' AND p.poem_author = '文嘉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题管道升修竹幽兰图 其二', '弘历', '清代', '白石修篁间紫兰，传神何似佩珊珊。鸥波最是逃禅者，冷泪还教对画弹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题管道升修竹幽兰图 其二' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题严陵钓台 其一', '崔华', '清代', '功名莫后人，云台已㛹娟。生不能封侯，何当故人怜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题严陵钓台 其一' AND p.poem_author = '崔华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄隐岩', '王守仁', '明代', '每逢山水地，便有卜居心。终岁风尘里，何年沧海浔？\n\n洞寒泉滴细，花暝石房深。青壁须留姓，他时好共寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄隐岩' AND p.poem_author = '王守仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('马', '陈庆和', '当代', '历块闻风意已驰，铁蹄偶勒立燕支。英雄一顾轻生死，啸虎腾龙自有时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '马' AND p.poem_author = '陈庆和';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠黄化州归莆田', '陈献章', '明代', '有客来何处，多年守化州。白云秋自好，碧玉自相投。\n\n日月催人去，行藏怅此休。武夷洗足罢，回首望罗浮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠黄化州归莆田' AND p.poem_author = '陈献章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自蒙园醉归', '何巩道', '明代', '暮城挝鼓忽阗阗，飞上归鞍故失鞭。穿尽柳过官路口，吟成诗隔女墙边。\n\n花开只合连宵赏，月好何曾两夜圆。不信到家醒未得，酒痕犹在袖中笺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自蒙园醉归' AND p.poem_author = '何巩道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和酬张梅野', '刘黻', '宋代', '郭行载酒相挈提，蹑根探窟天津如。\n相逢何必皆亲知，天地许大犹吾庐。\n矫首梅涧迹若疏，舂容婉画妨清醵。\n诗如琴弦分疾徐，惊我一声聋聩初。\n萧萧白日金仙居，东西求仲时从之。\n静对夕阳搴红蕖，或听夜雨邻怜翠榈。\n国步孔棘须神医，纵有鹊醯谁信渠。\n风传西事方解围，愿君勿藏圯上书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和酬张梅野' AND p.poem_author = '刘黻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('缺题', '李东阳', '明代', '圣道通三极，王言似六经。\n面开天日表，书作虎龙形。\n杞国忧方剧，华胥梦不醒。\n万年金匮在，遣训炳丹青。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '缺题' AND p.poem_author = '李东阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿报恩寺水阁', '皮日休', '唐代', '寺锁双峰寂不开，幽人中夜独裴回。池文带月铺金簟， \n 莲朵含风动玉杯。往往竹梢摇翡翠，时时杉子掷莓苔。 \n 可怜此际谁曾见，唯有支公尽看来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿报恩寺水阁' AND p.poem_author = '皮日休';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闺情十绝次金诚之先生韵 其六', '江源', '明代', '天末凉生大火流，渚红庭绿不禁秋。十年宕子游何处，不念闺中人独愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闺情十绝次金诚之先生韵 其六' AND p.poem_author = '江源';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八声甘州•听唐韩如弹琴', '沈谦', '明代', '自钟期死后碎瑶琴，古调向人难。正张华石上，苏公泉侧，泪血斑斓。\n\n打叠移宫换羽，袖手且盘桓。谁在东江市，霹雳重弹。\n\n最苦长门秋怨，可为予改操，白雪幽兰。奈无端五岳，膈上心间闻。\n\n但从来、读骚饮酒，问傍人、此意不相关。祇博得万山俱响，风急云翻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八声甘州•听唐韩如弹琴' AND p.poem_author = '沈谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辛卯五月送丘宗卿太博出守秀州二首 其二', '杨万里', '宋代', '老矣渠怜我，超然我爱渠。论诗春雨夜，解手藕花初。\n\n梦只江湖去，情知伎俩疏。未应五马贵，不寄一行书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辛卯五月送丘宗卿太博出守秀州二首 其二' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和王觉民民松轩诗', '王之道', '宋代', '苍髯绿发三四椽，茅斋高下轻且轩。\n清风入夜可人意，来与夫子调朱弦。\n连日秋阴荡残暑，抖擞烦襟欲轻举。\n简编灯火置勿论，且快蛟龙得云雨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和王觉民民松轩诗' AND p.poem_author = '王之道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西施滩', '汪广洋', '明代', '东越国已泯，西施滩尚存。天垂芳草地，渔唱夕阳村。\n\n荇带牵舟楫，罗衣拂酒尊。杜鹃缘底事，只管下啼痕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西施滩' AND p.poem_author = '汪广洋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢张慵庵文焕见访', '方回', '宋代', '两年梦寐记冰姿，再挹丰标胜旧时。\n形秽自怜吾更老，味同乃幸独相知。\n幽花野竹频移座，薄酒清茶共说诗。\n晚色柴门挂新月，玉骢欲上步犹迟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢张慵庵文焕见访' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭张员外继', '刘长卿', '唐代', '恸哭钟陵下，东流与别离。二星来不返，双剑没相随。\n\n独继先贤传，谁刊有道碑。故园荒岘曲，旅榇寄天涯。\n\n白简曾连拜，沧洲每共思。抚孤怜齿稚，叹逝顾身衰。\n\n泉壤成终古，云山若在时。秋风邻笛发，寒日寝门悲。\n\n世难愁归路，家贫缓葬期。旧宾伤未散，夕临咽常迟。\n\n自此辞张邵，何由见戴逵。独闻山吏部，流涕访孤儿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭张员外继' AND p.poem_author = '刘长卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏狂虏', '陈必复', '宋代', '狂虏何时静，干戈卒未休。乾坤犹半拆，汴泗自东流。\n\n腥日鼪鼯野，悲风鸿雁秋。诸贤江左计，长为晋人羞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏狂虏' AND p.poem_author = '陈必复';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岁暮山居杂感 其二十六', '谢元汴', '明代', '犹使儿童识，凿山惧未深。不观高士传，能入酒人林。\n\n静兕眠清野，寒鸠笑木阴。天空月色正，零露肃孤砧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岁暮山居杂感 其二十六' AND p.poem_author = '谢元汴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄方帅 其二', '张孝祥', '宋代', '贱子如今休说穷，玉麟铜虎信频通。君今持橐甘泉里，我不投书苦海中。\n\n且愿耕桑依地主，长教温饱荷天公。回思三十三年事，一笑相逢两秃翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄方帅 其二' AND p.poem_author = '张孝祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七里店口占', '范成大', '宋代', '分手暮江寒，徘徊立马看。\n寻常相见易，倍觉别离难。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七里店口占' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别眉山余都宪陛辞回南京二首 其二', '黄镐', '明代', '晓日辞朝出禁垣，马前专敕奉明恩。经营王赋推良吏，斟酌民情达至尊。\n\n终岁贤劳缘体国，暮年离别倍消魂。寒风冻雨金陵路，松柏青青为扫门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别眉山余都宪陛辞回南京二首 其二' AND p.poem_author = '黄镐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其十五', '李缜', '宋代', '鶗鴂一声春事空。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其十五' AND p.poem_author = '李缜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题会稽溪口躬师上人房', '施昌言', '宋代', '溪口佳山水，高人住此中。\n生台下沙鸟，疏磐逐江风。\n倚槛千岩寂，焚香万法空。\n如何凭小笔，一为写衰翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题会稽溪口躬师上人房' AND p.poem_author = '施昌言';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶仿沈周写生散牛卷并题二绝句 其二', '弘历', '清代', '在腰传白绶，鸣窌应黄钟。腹果休教懒，东郊好力农。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶仿沈周写生散牛卷并题二绝句 其二' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('草堂村寻罗生不遇', '岑参', '唐代', '数株谿柳色依依，深巷斜阳暮鸟飞。 \n 门前雪满无人迹，应是先生出未归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '草堂村寻罗生不遇' AND p.poem_author = '岑参';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('内人治蚕一首', '黄省曾', '明代', '灵雨洒芳澍，柔桑低绿枝。煖闺看蚁候，晓閤把筐时。\n\n吴俗新开业，邠风旧咏诗。敝裘惭季子，赖吐玉蚕丝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '内人治蚕一首' AND p.poem_author = '黄省曾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泊舟富池乞灵祠下', '杨冠卿', '宋代', '大江东南来，冯夷此其宫。\n群山各献状，奔走如游龙。\n将军万人杰，智勇摧奸凶。\n草木知威名，旗常纪丰功。\n庙食填兹土，楼阁何穹窿。\n我来拜灵祠，红日方曈曨。\n神乌集飞樯，雪波捲晴空。\n椒桂荐芳馨，精诚冀感通。\n谓言身半百，扁舟吾欲东。\n羞作贾胡留，愿借一帆风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泊舟富池乞灵祠下' AND p.poem_author = '杨冠卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和卢叔才食蛹 其一', '葛立方', '宋代', '绿柘林中听晚缫，闻将煮蛹当持螯。何须有茧大如瓮，救得妻儿啼与号。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和卢叔才食蛹 其一' AND p.poem_author = '葛立方';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵次尹俊卿梅花绝句 其四 雪梅', '王灼', '宋代', '急霰争璀璨，仙摽不解寒。汉家赵飞燕，偏许雪中看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵次尹俊卿梅花绝句 其四 雪梅' AND p.poem_author = '王灼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('进修堂前荷池', '范成大', '宋代', '方池留水胜埋盆，露入莲腮沁粉痕。\n铃索无志人不到，小禽飞入闹荷根。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '进修堂前荷池' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郡圃寒食', '戴复古', '宋代', '与民同乐一开园，佳节何曾禁得烟。\n拍岸绿波浮舴艋，翻空红袖打秋千。\n眼看花柳心如醉，身在蓬瀛我亦仙。\n明日徐翁坟上约，欲求竹帚恐无缘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郡圃寒食' AND p.poem_author = '戴复古';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('买小舟来往湘上有作', '蒋本生', '清代', '油壁青帘在在家，垂杨曲曲带烟斜。未酬环海三山梦，先占闲鸥半席沙。\n\n忧患余生惟中酒，蹉跎晚岁只看花。从今不管浮沈事，坐送新虹断晚霞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '买小舟来往湘上有作' AND p.poem_author = '蒋本生';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('村居', '王恭', '明代', '枫林草屋半苍苔，寂寂柴扉映竹开。啼鸟数声春自好，五陵年少不曾来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '村居' AND p.poem_author = '王恭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小游仙诗九十八首 其八十九', '曹唐', '唐代', '东溟两度作尘飞，一万年来会面稀。千树梨花百壶酒，共君论饮莫论诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小游仙诗九十八首 其八十九' AND p.poem_author = '曹唐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('客西园赠陈东崖', '成鹫', '明代', '回首嬉游似断篷，可堪相见各成翁。童心掷向红尘外，壮志销归白业中。\n\n短榻夜禅陪病鹤，閒阶春望送孤鸿。西园宾从多新识，争羡先生有祖风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '客西园赠陈东崖' AND p.poem_author = '成鹫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠宁道士', '黄瑜', '明代', '刚风起鹏溟，梦结紫霞赏。白日生羽翰，玄珠失象罔。\n\n长离与矞皇，招我流铃响。耸身登郁罗，翛然蹑虚朗。\n\n玉娥拂我衣，谓我税尘鞅。何年同尔游，逍遥披鹤氅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠宁道士' AND p.poem_author = '黄瑜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病阿速（阿速，蒙古别号也）', '袁凯', '明代', '杭州阿速病可伤，况复四体多金创。\n口粮开除但乞丐，终日哀鸣行路傍。\n自言家在云中住，兄弟既死惟爹娘。\n往年江南妖贼反，圣旨差我随平章。\n同行二千五百辈，辈辈选用皆精强。\n孰知江南风土异，不比中原尽平地。\n中原地平好驰逐，一人腾骧万人废。\n江南地卑山林密，泥深马滑无由立。\n角弓着雨软如绵，咫尺相看不能射。\n九月十月岁云莫，贼兵突入观音渡。\n平章脱身向东去，太半尽死无人顾。\n我幸不死病已危，丞相被逐无依归。\n异乡此日谁相慰，只似天边孤雁飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病阿速（阿速，蒙古别号也）' AND p.poem_author = '袁凯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郧将军入对歌', '钱澄之', '清代', '将军趋朝求召见，天子传宣御水殿。将军廷辨声怒嗔，百官拱手颜色变。\n\n中使促对上龙舟，有事面奏香案头。舟中天子东面坐，将军俯伏汗交流。\n\n汗流浃背猛气沮，诏谓将军从容语。垆烟移近再三陈，但闻誓死报明主！\n\n叩头再拜出君门，忆起胸中未尽言。天威咫尺说不得，始信君王是至尊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郧将军入对歌' AND p.poem_author = '钱澄之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浪淘沙 正月廿七闻雁忆云姜', '顾太清', '清代', '别后数征邮。应到扬州。相思一日似三秋。恼煞雁行天上字，字字离愁。\n\n回首忆春游。花底句留。三分春又一分休。屈指海棠开日近，不见归舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浪淘沙 正月廿七闻雁忆云姜' AND p.poem_author = '顾太清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶题二首 其一', '来鹏', '唐代', '近来灵鹊语何疏，独凭栏干恨有殊。一夜绿荷霜剪破，赚他秋雨不成珠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶题二首 其一' AND p.poem_author = '来鹏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和刘郎浴观音予置酒见贻', '韩维', '宋代', '禅关严城侧，深靓辟华构。\n方吾挟书来，值子出杅后。\n欣然出浊酒，谈笑坐清昼。\n三四同来人，颇喜出邂逅。\n牵衣起相酌，曾不烦劝侑。\n纷披索潜逃，顾壁恨无窦。\n不谓一樽乐，有逾万金寿。\n瓶罍忽已竭，余兴不自收。\n走登故人堂，拜叙十年旧。\n夜深跃马归，不畏妾妇诟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和刘郎浴观音予置酒见贻' AND p.poem_author = '韩维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '刘师道', '宋代', '青帝翠华沈物外，素娥孀影吊云端。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '刘师道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('折花背立二美人图 其一', '徐贲', '元代', '女伴今朝出较迟，独来园里候多时。对花可是无言说，懊恨春风许自知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '折花背立二美人图 其一' AND p.poem_author = '徐贲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢通讲师五偈', '释正觉', '宋代', '一昨书来约见过，迟留行李未成那。\n梨黄枣赤秋如许，发白眉庞老奈何。\n相伴採薇云腻袜，不嫌伐木雨濡蓑。\n对床默默香摇篆，霁月夜窗悬女萝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢通讲师五偈' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水仙花效李长吉', '邹亮', '明代', '冯夷镂水驻花魄，奇芬染肌沁仙骨。\n天风吹梦落瑶台，家住江南水云窟。\n弄珠拾草潇湘渚，带月迷烟愁不语。\n小龙潜开水晶殿，玉杯凉露承华宴。\n青鸟衔书来阆苑，笑指蓬莱水清浅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水仙花效李长吉' AND p.poem_author = '邹亮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈', '释了元', '宋代', '赵州当日少谦光，不出三门见赵王。争似金山无量相，大千都是一禅床。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈' AND p.poem_author = '释了元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋风三叠辞 其二', '李龄', '明代', '秋风瑟瑟兮落叶飘，溪谷瀰漫兮水惊涛。棹兰舟以径渡兮，渊潜龙而腾蛟。\n\n兰蕙变以不香兮，江蓠化而为茅。顾金天之肃杀兮，忽坎壈以郁陶。\n\n诗戒素餐兮，厥咎焉逃。惧众口之铄金兮，愿处靓而守高。\n\n鸿鹄既举兮，孰与游遨。仰明月而独坐兮，聊徜徉以逍遥。\n\n惠思君兮，使我心劳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋风三叠辞 其二' AND p.poem_author = '李龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('有感', '黄庚', '宋代', '自叹文章不遇时，平生壮志与心违。\n十年湖海无家住，千里乡关有梦归。\n残夜月寒灯晕淡，高秋天阔雁声微。\n伤今思古愁无奈，老泪斑斑湿客衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '有感' AND p.poem_author = '黄庚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟渔洋读三国志小乐府 其三', '陈曾寿', '清代', '万事皆鸡肋，还悲去日多。芳樽荐野葛，风味妙如何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟渔洋读三国志小乐府 其三' AND p.poem_author = '陈曾寿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题天衣寺', '袁说友', '宋代', '稽山道上多名迹，万顷湖光衬山色。\n云蒸雾集累千年，屈指风流几人物。\n平生佳处身曾经，赖此泉石供余龄。\n爱山何惜买山费，明珠不博娉与婷。\n我闻天衣最奇绝，万顷清凉扫烦热。\n持经夜半鸟鼠听，忽睹金仙起还灭。\n把茅从此成开山，法华妙果僧中贤。\n当时十诏徵不起，神奇变化泥生莲。\n山神谨护泥封诏，独有遗风传内教。\n袈裟金缕照琉璃，时放祥光蔽云物。\n我来官守无时閒，著脚未历城南山。\n区区俗眼空自翳，耿耿此意如循环。\n我心岂是真如石，惭愧新诗与推激。\n自怜未到此山中，想见入山深未得。\n要令攻俗如攻城，兹游约与秋风迎。\n吾曹岂办痴儿事，为君一醉南湖清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题天衣寺' AND p.poem_author = '袁说友';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋怀十二首 其十一', '陆深', '明代', '团扇情多咏未休，井梧何事强知秋。霜华先上双蓬鬓，壮气空馀独倚楼。\n\n谁复常何工荐士，徒闻李广不封侯。千寻铁锁如堪借，借与人间锁断愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋怀十二首 其十一' AND p.poem_author = '陆深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('孤吟', '释函可', '明代', '空洞接混濛，其中有日月。古哲亲至前，万象森以列。\n\n草木共话言，死骨亦得活。明和春山晖，严凝洒冰雪。\n\n石池起层波，浩浩皆鲜血。鱼龙各生愁，方寸恣出没。\n\n点画入重玄，十指电光掣。星斗尽下来，八方不盈撮。\n\n倏忽天地冥，鬼神栖其穴。残魄静独抱，性光自相悦。\n\n此际吾不知，虽知不能说。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '孤吟' AND p.poem_author = '释函可';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄庄将军', '程嘉燧', '明代', '僧榻书廊卧夕曛，兴来吟啸每过君。\n梅残烛烬疏窗雨，雪沍香浓小閤云。\n茶作松风先破睡，墨添山气待微醺。\n自从一别莲花府，月下笳箫忆共闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄庄将军' AND p.poem_author = '程嘉燧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('顾钱塘德辉 其四', '严遂成', '清代', '枇杷雪罩桂天香，棋子丁丁落满堂。轧得凤头琴未了，蟠桃手夺紫丝囊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '顾钱塘德辉 其四' AND p.poem_author = '严遂成';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('月下口占二首 其二', '黄淳耀', '明代', '海上碧云尽，秋天开素屏。怀中馀綵笔，无处著丹青。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '月下口占二首 其二' AND p.poem_author = '黄淳耀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠刘相士', '许棐', '宋代', '满镜秋霜鬓影寒，此生堪笑复堪怜。烦君只相看书眼，更对青灯得几年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠刘相士' AND p.poem_author = '许棐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桃源洞 其三', '左纬', '宋代', '青山簇簇水湾湾，洞户应将玉锁关。饮罢出来红日晚，一声鸡犬悟人间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桃源洞 其三' AND p.poem_author = '左纬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天仙子 其九', '毛奇龄', '清代', '斑簟纹生双腕缬。梦中欲笑开娇靥。醒来记得许多情，檀兽爇。\n\n钗燕热。侍婢相看那能说。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天仙子 其九' AND p.poem_author = '毛奇龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('永和放舡二首', '杨万里', '宋代', '永和不到又经秋，淡日微风好放舟。\n最是可怜江上路，人来人去几时休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '永和放舡二首' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题倪元镇画二首 其一', '郯韶', '元代', '断霭生春树，微茫隔远汀。梁溪新月上，照见惠山青。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题倪元镇画二首 其一' AND p.poem_author = '郯韶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水浅舟滞解闷十绝 其七', '郑獬', '宋代', '酒徒不复少年时，白发狂歌亦未衰。更与春风酬一醉，好花犹有两三枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水浅舟滞解闷十绝 其七' AND p.poem_author = '郑獬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答吕老', '杨民仁', '近代', '海棠八句未留名，为有闲人慕俊英。此日江城欢聚后，不关情处总关情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答吕老' AND p.poem_author = '杨民仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和刘后村梅花绝句', '黄珩', '宋代', '丰钟逐散晓云遮，我欲伸冤玉帝家。\n青女一身都是胆，年年随下月偷花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和刘后村梅花绝句' AND p.poem_author = '黄珩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桃花菊', '李新', '宋代', '秋雨秋风夜，闲为桃菊吟。\n任香飘涧水，回翠入篱金。\n苦李自胡越，幽兰初腹心。\n故山千里外，回首暝烟深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桃花菊' AND p.poem_author = '李新';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与杨如愚四首 其一', '陈渊', '宋代', '文章初不计工拙，言语何常识重轻。不向故人齐物我，一生怀抱为谁倾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与杨如愚四首 其一' AND p.poem_author = '陈渊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送弟叔永如太仓次张叔亨韵', '梁储', '明代', '太仓何止万人家，民俗从来雅好华。盍向闾阎求吉士，莫令纯朴弃天涯。\n\n橙黄合擢高秋实，菊落仍餐最晚花。□□□□□□□，临岐重叠拜新嘉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送弟叔永如太仓次张叔亨韵' AND p.poem_author = '梁储';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('石壁泉', '熊禾', '宋代', '一滴流浆石骨穿，于今一掬扫炎氛。\n鹤仙业已成陈迹，瀑布声中隐剑痕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '石壁泉' AND p.poem_author = '熊禾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病中闻己儿游张公洞占寄', '皇甫汸', '明代', '名山探尽赋难成，卧病江淹减笔精。见说灵光将属草，童心亦自有高情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病中闻己儿游张公洞占寄' AND p.poem_author = '皇甫汸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南乡子 题陈莲汀疏香清影，是其亡姬吴氏照也', '钱斐仲', '清代', '往事付朝云。惹取愁霜染鬓新。最是画帘垂细雨，黄昏。\n\n翠羽啁啾独掩门。\n\n明月认前身。一段冰绡渍泪痕。只有真真呼不起，伤神。\n\n竹外疏花又返魂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南乡子 题陈莲汀疏香清影，是其亡姬吴氏照也' AND p.poem_author = '钱斐仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '李邴', '宋代', '柳老抛绵后，梅酸著骨时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '李邴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二月二十四夜长安母家听雨 其二', '卢青山', '当代', '茫茫春宿夜，切切雨来时。顾壁陈众杂，倒乱旧橱帷。\n\n雨既不可睹，唯以听成痴。缅知天远黑，万里绕四围。\n\n湘灵低有瑟，嘈嘈渐成吹。刀风当暗运，达旷复入微。\n\n众窍和仍稳，匀弱无稍颓。不能急如鼓，涓涓略如丝。\n\n玄音昧渺窈，莫识其所之。恍恍若有至，旋觉还自疑。\n\n容或悄入梦，梦实无可期。久坐抚衣冷，似丧似沉思。\n\n丧者吾丧我，思者不可知。四顾凄且寂，无语泪沾衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二月二十四夜长安母家听雨 其二' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('仙人词（三首）', '刘基', '明代', '上帝宸居俨肃森，九关虎豹立崟崟。\n群龙自有三珠树，不见扶桑水浅深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '仙人词（三首）' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('木兰花 趵突泉', '陈曾寿', '清代', '清泠一勺轻千里，倦客劳尘聊与洗。沉吟秋柳试春茶，桑苧风流难再拟。\n\n小瓯还瀹明窗底，何限林泉潇洒意。不妨风味似江南，但莫石头城下水。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '木兰花 趵突泉' AND p.poem_author = '陈曾寿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('除夕独游大观楼', '施蛰存', '近代', '楼外楼空游客稀，老夫策杖独依依。城中儿女喧分岁，日下倭夷正合围。\n\n入洛士衡非得计，去家元节总思归。萧寥一段残年意，伴取西山冷翠微。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '除夕独游大观楼' AND p.poem_author = '施蛰存';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送淡公 其十二', '孟郊', '唐代', '诗人苦为诗，不如脱空飞。一生空鷕气，非谏复非讥。\n\n脱枯挂寒枝，弃如一唾微。一步一步乞，半片半片衣。\n\n倚诗为活计，从古多无肥。诗饥老不怨，劳师泪霏霏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送淡公 其十二' AND p.poem_author = '孟郊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送邵安石及第归连州觐省', '曹松', '唐代', '及第兼归觐，宜忘涉驿劳。青云重庆少，白日一飞高。 \n 转楚闻啼狖，临湘见叠涛。海阳沈饮罢，何地佐旌旄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送邵安石及第归连州觐省' AND p.poem_author = '曹松';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丁酉重九日宿顺昌步云阁绝句七首呈味道明府', '刘克庄', '宋代', '老子痴顽耐远游，平生腹不贮闲愁。\n今年天赐登高地，身在云峰最上头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丁酉重九日宿顺昌步云阁绝句七首呈味道明府' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗 其一', '郑孝胥', '清代', '露气泠泠琐碎金，初阳到地又穿林。南趋新笋浑无数，不觉苍苔一径深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗 其一' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵方平见寄', '释道潜', '宋代', '黄花弄色近重阳，山果红梨迥得霜。节物撩人兴不浅，交情如子味何长。\n\n终期雾豹栖岩穴，且作宾鸿寄野塘。它日西湖能过我，胡麻供饭煮芹香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵方平见寄' AND p.poem_author = '释道潜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题徐幼文画次高季迪张来仪韵', '王汝玉', '明代', '云生疏林晚，花落空山春。裴佪林下路，惆怅山中人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题徐幼文画次高季迪张来仪韵' AND p.poem_author = '王汝玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('毛诗 小星', '陈普', '宋代', '名分存存不敢忘，衾裯来往几星光。尊卑高下虽天秩，小纪终须属大纲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '毛诗 小星' AND p.poem_author = '陈普';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('入纳溪二首 其一', '周瑛', '明代', '两岸青山合，一溪春水深。兰桡须慢拨，处处可娱心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '入纳溪二首 其一' AND p.poem_author = '周瑛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('嬉春曲和黄泰泉四首 其二', '黄衷', '明代', '飞觞流水泛春矶，清晓初回小猎旗。旭日有光迎落絮，东风无力控游丝。\n\n兴酣翠幔襟芗满，舞罢红筵步锦移。谁道云鬟萧瑟近，城中犹自远山眉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '嬉春曲和黄泰泉四首 其二' AND p.poem_author = '黄衷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('静宜园二十八景诗 其十八 玉乳泉', '弘历', '清代', '乍可微风拂，偏宜皎月涵。西湖不千里，当境即三潭。\n\n演漾冈峦影，卷舒晴雨岚。灵源何处是，一脉试寻探。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '静宜园二十八景诗 其十八 玉乳泉' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('昭台怨二首', '魏学礼', '明代', '别馆芙蓉暗，闲房翡翠寒。\n漏催千夜尽，宫锁一春残。\n芳岁惊流水，容华泣楚兰。\n谁怜愁坐意，新月在楼端。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '昭台怨二首' AND p.poem_author = '魏学礼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荼蕊花', '宋祁', '宋代', '媚丛无奈密，柔蔓不胜长。\n非邻粉自白，似侠骨中香。\n不分樱桃艳，名先播乐章。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荼蕊花' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望永安县诸山', '屈大均', '明代', '紫帘将白叶，双嶂隐藤萝。欲雨阴霞起，先秋暑气过。\n\n水嫌琴口小，山爱髻鬟多。明上乌禽岭，当如瀑布何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望永安县诸山' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泖口跨塘桥吊黄门陈卧子先生', '屈大均', '明代', '舟出吴淞烟水遥，黄门怀石此塘桥。三闾日月光相映，一剑乾坤恨未消。\n\n泖口莼鲈淹过客，云间风雅忆先朝。惭予后死空词赋，惯向江南放大招。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泖口跨塘桥吊黄门陈卧子先生' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋雨同子直', '王夫之', '明代', '秋阴何来飞雨淙，杜陵叹之后尧江。井桐已落不知数，水鸟无愁聊自双。\n\n游屐几曾过柳岸，青尊只少对兰缸。犹传锦字开幽独，湿月穿云上小窗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋雨同子直' AND p.poem_author = '王夫之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送殿干谯公暂归莆田', '曹勋', '宋代', '暂辍京尘扰扰间，一鞭行色冒春寒。\n梅花细雨资能赋，野水遥山好据鞍。\n引道颇闻辞魏阙，觅官况可近长安。\n掀髯西笑归宜早，应及莆闽荔子丹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送殿干谯公暂归莆田' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玄译观二首 其一', '黎贞', '明代', '舟过白沙驿，地转玄译湾。神仙境内境，烟霞山外山。\n\n星坛白日静，石室松风寒。鸣蜩号复止，老鹤去又还。\n\n忆昔旌阳令，威灵动尘寰。神剑斩蛟鳄，至今锁玄关。\n\n我有山水趣，视之自怡颜。停舟泊崖下，聊以一跻攀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玄译观二首 其一' AND p.poem_author = '黎贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饯乡守宋监丞二首 其二', '刘克庄', '宋代', '牛屋渔矶在履封，晚将身世托春风。荒原拾穗谁怜我，小队寻花屡屈公。\n\n耄有须眉如盖老，衰无歌诵美文翁。明时各遂飞潜性，去矣鞭鸾碧落中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饯乡守宋监丞二首 其二' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('初冬小园寓目', '张耒', '宋代', '独树翘寒色，闲云澹落晖。\n新霜黄菊重，久雨翠梧稀。\n暝雀鸣还啄，高乌定更飞。\n敝貂犹故在，卒岁免无衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '初冬小园寓目' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('极相思', '曹慎仪', '清代', '韶华愁度年年。都付断肠笺。几时得共，玉枰金盏，月底花边。\n\n香冷屏空心更怯，最恓惶、病起灯前。一点柔魂，十分瘦影，知倩谁怜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '极相思' AND p.poem_author = '曹慎仪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('代札寄张建辉老师二首 其二', '卢青山', '当代', '平生自笑半非人，仿佛千年谪客身。吟啸生涯差可比，屠沽小子讵为邻。\n\n挂松衣袂如悬帜，卧石杯壶胜列兵。待有长言和兽语，低低莫与世人听。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '代札寄张建辉老师二首 其二' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('红梅', '蔡沈', '宋代', '一树芳菲露短墙，彩霞千缕带斜阳。\n东君赋予知何意，剩与胭脂使嗇香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '红梅' AND p.poem_author = '蔡沈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏儒释道三教总赠程洁庵：儒理十五首 其五 惟精惟一', '李道纯', '元代', '天心体用妙玄机，舍妄从真便造微。精义入神惟定一，功深力到达希夷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏儒释道三教总赠程洁庵：儒理十五首 其五 惟精惟一' AND p.poem_author = '李道纯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赋得千山红树送姚园客还闽 其二', '潘之恒', '明代', '落叶萧萧路，秋风湖上波。到家红树少，不怨客愁多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赋得千山红树送姚园客还闽 其二' AND p.poem_author = '潘之恒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和裴少府怀京兄弟', '皎然', '唐代', '宦游三楚外，家在五陵原。凉夜多归梦，秋风满故园。 \n 北书无远信，西候独伤魂。空念青门别，殷勤岐路言。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和裴少府怀京兄弟' AND p.poem_author = '皎然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又雪同欧子直', '王夫之', '明代', '溪边林外转霏微，几处新莺禁不飞。即次青春欺白发，丁宁酒力试寒威。\n\n连天朔雪悲明月，昨日西清忆落晖。为报春光多蕴藉，来朝一倍报芳霏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又雪同欧子直' AND p.poem_author = '王夫之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('止所吴公挽歌辞 其一', '方凤', '宋代', '岳岳文豪共识名，归来风月恣弹评。竹阶过鹤窥棋局，花院流莺和乐声。\n\n灯酌萧閒期郑老，盆歌疏达慕庄生。何来排闼绯衣召，天上楼传白玉成。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '止所吴公挽歌辞 其一' AND p.poem_author = '方凤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杪冬登玉川门 其一', '释今严', '明代', '才过粤岭已闻名，漱石空怀两载情。乘兴顿忘冰雪色，望来渐觉骨神清。\n\n嵯峨石势危城出，澎湃溪声春雨平。心目屡分无可似，寒灯疏磬月微明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杪冬登玉川门 其一' AND p.poem_author = '释今严';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十蒸', '释函是', '明代', '山径横斜好共僧，孤云野鹤碧崚嶒。相看石上寒如此，坐到花残春未曾。\n\n澹影情疏应似我，晓风人外若为朋。纸窗竹屋凄清处，一片禅心不可胜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十蒸' AND p.poem_author = '释函是';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日游读书山怀元遗山先生四首 其三', '朱云骏', '清代', '性正气亦正，跌荡雄幽并。声名世耳食，知己惟一兄。\n\n四十五年闲，毁誉何轰轰。习俗安污流，所葆遂不贞。\n\n锱铢较利害，俯仰随重轻。所以贵壁立，君子岂好争。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日游读书山怀元遗山先生四首 其三' AND p.poem_author = '朱云骏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟古三首 其一', '黎景义', '明代', '沼下鸳鸯鸟，双居殊可怜。楼中佳丽人，独坐惜韶年。\n\n忆年十四五，与君相周旋。朝和鸡鸣诗，夕调凤曲弦。\n\n岂知顷刻欢，一别判两天。罗衣日以故，芳草日以鲜。\n\n仳离望云汉，修阻怨山川。桑弧志四方，知君未返辕。\n\n安得奇肱车，随风至君前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟古三首 其一' AND p.poem_author = '黎景义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('昔陈北山赵南塘二老各有观物十咏笔力高妙暮', '刘克庄', '宋代', '绛帕妖方士，青襟小茂才。\n集瓜讥汝否，止棘刺谁哉。\n倏忽寻声去，曾无濯足来。\n吾衰臂力短，驱去复飞回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '昔陈北山赵南塘二老各有观物十咏笔力高妙暮' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉陪郑驸马韦曲二首 其一', '杜甫', '唐代', '韦曲花无赖，家家恼杀人。绿尊虽尽日，白发好禁春。\n\n石角钩衣破，藤枝刺眼新。何时占丛竹，头戴小乌巾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉陪郑驸马韦曲二首 其一' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鲁少卿挽章', '吕祖谦', '宋代', '庆源衮衮接天流，老桂传香次第秋。\n人物西都九卿选，光华南国十州游。\n翛然径下滕王阁，已矣长怀范蠡舟。\n身后楚骚谁著录，灵光旧草合兼收。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鲁少卿挽章' AND p.poem_author = '吕祖谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠萧莲卿女史', '许南英', '清代', '旧闻林子语，空谷有婵娟。犹带看花眼，来吟咏絮篇。\n\n赏心能有几？觌面竟无缘！悟得生公法，毋为色相牵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠萧莲卿女史' AND p.poem_author = '许南英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('歌寄留英禅德', '释重显', '宋代', '当时临际辞黄檗，或指河南或河北。英禅此日下中峰，机案曾焚笑仍则。\n\n九包一角惭称瑞，导月观星亦非意。争似韶阳振古风，半途未肯还希冀。\n\n归去来，归去来，飞泉浩浩声如雷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '歌寄留英禅德' AND p.poem_author = '释重显';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自叙', '蔡槃', '宋代', '江湖间步几经年，穷似襄阳孟浩然。\n折简为求僧舍茗，典衣因欠酒家钱。\n真情尽向诗中见，归梦常于枕上圆。\n世路风波深可畏，结茅何日遂归田。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自叙' AND p.poem_author = '蔡槃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('儿子以诗酒送文伯起既而复继三诗予喜其用韵颇工为和五首 其三', '王寂', '金朝', '樽酒但能供北海，渔蓑安用钓西周。七言五字得谁髓，老杜工部韦苏州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '儿子以诗酒送文伯起既而复继三诗予喜其用韵颇工为和五首 其三' AND p.poem_author = '王寂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('放言五首 其四', '王松', '清代', '问天屈子离骚赋，斫地王郎托醉歌。东国圣师西国佛，南山鸟避北山罗。\n\n云深易觅还魂草，风劲难兴止水波！受辱不须逃胯下，无双品自引萧何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '放言五首 其四' AND p.poem_author = '王松';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浮生杂咏八十首 其二十四', '施蛰存', '近代', '鹅笼蚁穴事荒唐，红线黄衫各擅场。堪笑冬烘子不语，传奇志怪亦文章。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浮生杂咏八十首 其二十四' AND p.poem_author = '施蛰存';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丰年谣五首 其五', '王炎', '宋代', '稻如马尾覆沟塍，桑柘阴中鸡犬鸣。收穫登场便无事，输租人不入州城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丰年谣五首 其五' AND p.poem_author = '王炎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙 题山园遥青阁', '唐元观', '清代', '野径苔荒客少到，双扉春昼常关。朱栏曲曲水流湾。\n\n莺啼修竹里，犬吠白云间。\n\n远翠飞来白似练，望中碧浪青山。桃花烂漫竹成斑，杖藜沽酒出，麋鹿采芝还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙 题山园遥青阁' AND p.poem_author = '唐元观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('齐天乐·吴山望隔江霁雪', '厉鹗', '清代', '瘦筇如唤登临去，江平雪晴风小。湿粉楼台，酽寒城阙，不见春红吹到。徽茫越峤，但半沍云根，半销沙草。为问鸥边，而今可有晋时棹？\n清愁几番自遣，故人稀笑语，相忆多少！寂寂寥寥，朝朝暮暮，吟得梅花俱恼。将花插帽，向第一峰头，倚空长啸。忽展斜阳，玉龙天际绕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '齐天乐·吴山望隔江霁雪' AND p.poem_author = '厉鹗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵篇用李空同汉京篇韵', '龚鼎孳', '明代', '六代丛金粉，千门艳绮罗。笙歌横玉阙，楼阁傍银河。\n\n银河玉阙伤心丽，垂柳曾笼王谢第。朱门双燕自翩跹，琼树三山空掩蔽。\n\n杜鹃春望隔天津，璧月临春更有人。羽书禁闼床皆满，祠庙青溪祷不神。\n\n相府衙兵森子弟，戟门夜识金银气。秦宫貂珥逼将军，李广戈矛偿醉尉。\n\n夕烽飞过广陵城，小队传呼宫辇行。官里别驱黄幄去，六军亲倒翠旗迎。\n\n帘前墨敕夸行在，河上楼船陨将星。幡出石头王迹地，表书铁券世家名。\n\n繁华久触高明忌，满目新亭人似寐。长堑偏容鼓角过，斜阳最耐兴亡事。\n\n台城白日乱鸦号，复道香尘长野蒿。宝钿妆成云易散，珠扉花冷月空高。\n\n世事从来多反覆，沧桑眼底翻陵谷。当年刀笔太纵横，此日风云纷角逐。\n\n金陵萧瑟剧堪怜，旧内钟山本接连。不见五陵裘马外，麒麟还对玉衣眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵篇用李空同汉京篇韵' AND p.poem_author = '龚鼎孳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟次吉溪', '白玉蟾', '宋代', '十年三过吉溪滩，想被溪梅笑往还。\n尘暗壁间题迹旧，满斟杯酒慰寒山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟次吉溪' AND p.poem_author = '白玉蟾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一电四首 其四', '连横', '近代', '捭閤纵横说异同，那堪一国实三公。十年豹变藏妖雾，万里鹏抟待好风。\n\n功首罪魁今已定，圣人大盗本相通。白鱼朱鸟荒唐事，莫再吹来劫火红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '一电四首 其四' AND p.poem_author = '连横';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('善哉行', '曹睿', '魏晋', '赫赫大魏。王师徂征。冒暑讨乱。振耀威灵。泛舟黄河。\n\n随波潺湲。通渠回越。行路绵绵。彩旄蔽日。旗旒翳天。\n\n淫鱼瀺灂。游戏深渊。唯塘泊。从如流。不为单。握扬楚。\n\n心惆怅。歌采薇。心绵绵。在淮淝。愿君速节早旋归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '善哉行' AND p.poem_author = '曹睿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留别诸子还山 其一', '成鹫', '明代', '行行且莫怅离群，笑指前山日欲曛。此际谁为当去客，及时犹得少迟君。\n\n归僧箬笠全冲雪，老我茅堂半住云。别后故交劳远梦，夜钟无计遣相闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留别诸子还山 其一' AND p.poem_author = '成鹫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题松窗听雪卷', '史谨', '明代', '六出随风散紫冥，庭前俄失万松青。疏帘堕影觉微响，落叶有声无此清。\n\n万虑已空心似水，一尘不染色铺琼。晚来听罢呼童扫，要把长镵取茯苓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题松窗听雪卷' AND p.poem_author = '史谨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('狮峰寺次景澄韵', '何乔新', '明代', '象宇临幽境，猊峰竦异形。松云侵榻冷，竹露堕衣青。\n\n唳鹤惊晨鼓，啼莺乱昼铃。停车问民瘼，凄楚不堪听。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '狮峰寺次景澄韵' AND p.poem_author = '何乔新';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴亚森[忠匡]出纸索书余诗', '钱钟书', '当代', '吴生好古亲风雅，翰墨淋漓乞满家。\n见役吾非能事者，赏音子别会心耶。\n声如蚓出诗纤弱，迹比鸦涂字侧斜。\n也自千金珍敝帚，不求彩笔写簪花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴亚森[忠匡]出纸索书余诗' AND p.poem_author = '钱钟书';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('探梅 其一', '韩淲', '宋代', '探梅山路一杯亭，日澹风微远霭生。莫问古来寻古话，只知春近赏春情。\n\n几枝冷蕊吟方见，一点疏花画不成。我挟两儿同二友，老年酒外更何营。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '探梅 其一' AND p.poem_author = '韩淲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏綵堂', '解缙', '明代', '春风庭砌长兰苕，堂上慈亲冠凤翘。綵服尊前映朝日，回銮紫诰下青霄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏綵堂' AND p.poem_author = '解缙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西园雅集作 其四', '丘逢甲', '清代', '天上文昌气似珠，吟声万里合笙竽。黔云台雨姑苏月，写入西园雅集图。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西园雅集作 其四' AND p.poem_author = '丘逢甲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古十首', '释普岩', '宋代', '如是如何下法眼，蓦然突出破沙盆。\n依稀渭北春天树，仿佛江东日暮云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古十首' AND p.poem_author = '释普岩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('司徒工开府韩国富公挽辞四首', '司马光', '宋代', '天佑休明祚，时生俊杰臣。\n贤科首多士，宰府泽生民。\n焕烂三台正，冲融四海春。\n欲知甄冶力，试问白头人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '司徒工开府韩国富公挽辞四首' AND p.poem_author = '司马光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('太岳仙宫七咏 其六 遇真', '黎民表', '明代', '手把丹书侍玉宸，紫髯萧洒出风尘。青羊化后犹存石，白鹤归来尚幻身。\n\n药市当年曾隐姓，花源今日正迷津。可怜物色先朝事，应为苍生访隐沦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '太岳仙宫七咏 其六 遇真' AND p.poem_author = '黎民表';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同子永和贝元复春日韵 其一', '李洪', '宋代', '平生身计拙如鸠，更向周南怨滞留。无奈春风欺客病，蕙兰狼籍伴牢愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同子永和贝元复春日韵 其一' AND p.poem_author = '李洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('回銮作', '弘历', '清代', '榆柳青青驿路宽，新黄旧绿解迎銮。却思塞上风霜景，似展关仝画里看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '回銮作' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春夜世立携客过访息庐 其一', '李之世', '明代', '春光已过半，林卧未知春。闭户殊无趣，逢君最快人。\n\n敲诗釐韵谱，品水集茶宾。晏坐林方寂，潮声到耳新。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春夜世立携客过访息庐 其一' AND p.poem_author = '李之世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿山寺思归', '李端', '唐代', '僧房秋雨歇，愁卧夜更深。欹枕闻鸿雁，回灯见竹林。 \n 归萤入草尽，落月映窗沉。拭泪无人觉，长谣向壁阴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿山寺思归' AND p.poem_author = '李端';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吉林成淡堪龙沙感事诗遗墨乃易箦前所作其子属题二首 其二', '夏孙桐', '清代', '兴山黑水旧岩畺，翻近他人卧榻旁。谁解绸缪思未雨，伊川一叹早神伤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吉林成淡堪龙沙感事诗遗墨乃易箦前所作其子属题二首 其二' AND p.poem_author = '夏孙桐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('抵黄州', '祖之望', '清代', '百八江程一日驰，蒲帆叶叶渚风吹。三年再作黄州客，千里来参玉版师。\n\n西塞鱼肥新涨落，东坡草长旧矶移。中流叠鼓鸣笳处，赤壁城头日暮时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '抵黄州' AND p.poem_author = '祖之望';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('正月初四日听新乐成绝句 其三', '张镃', '宋代', '呜呜胡笛鹧鸪声，三叠鸣鼍舞袖轻。灯市花村旧欢醉，如今自厌邈无情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '正月初四日听新乐成绝句 其三' AND p.poem_author = '张镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书怀四绝 其三', '王世贞', '明代', '早闻金印出长安，诸将人人拟筑坛。却向乐通侯馆去，玉关双鬓不胜寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书怀四绝 其三' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题十二兄野堂', '韩元吉', '宋代', '少年行乐记乡关，月渚霞洲一梦间。\n为爱轩窗临野水，只疑风景是家山。\n荷香柳影情偏厚，竹色松声意自閒。\n堪笑主翁持节手，却来垂钓傍苍湾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题十二兄野堂' AND p.poem_author = '韩元吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽黄承事三首 其二', '廖行之', '宋代', '不用籯金侈厚藏，无烦农圃富耕桑。一经父子韦编训，馀庆阶庭玉树芳。\n\n道义固堪绵有后，功名浑把付诸郎。他年窦桂诜诜报，当信于今种德香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽黄承事三首 其二' AND p.poem_author = '廖行之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('《绮疏遗恨》之尺', '唐寅', '明代', '佛说空虚也可量，虚空比恨恨还长；\n银花宝钿金星尺，认得纤纤十指香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '《绮疏遗恨》之尺' AND p.poem_author = '唐寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('百字令 怀母氏故居', '范贞仪', '清代', '拈花弄蕊，记绿阴庭院，清幽如许。一带浓阴遮翠幕，绿映黛螺眉妩。\n\n红豆抛莺，春纨扑蝶，憨做娇儿女。珠帘晴卷，画堂春暖如雾。\n\n回首易换沧桑，而今重忆，总是伤情处。月转回廊花影飐，谁在儿家窗户。\n\n春草池边，可娱轩里，问东风谁主。铜仙多感，露和铅泪如注。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '百字令 怀母氏故居' AND p.poem_author = '范贞仪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿瓢城僧舍', '沈梧', '清代', '孤灯人意懒，暮鼓带愁声。寂寞关山梦，超然世俗情。\n\n西风深院树，凉月古瓢城。怊怅江南侣，飘零怨北征。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿瓢城僧舍' AND p.poem_author = '沈梧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古言', '佚名', '先秦', '墙有耳。伏寇在侧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古言' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵苏守金橘', '陈棣', '宋代', '孤根移植自秋山，长养潜私刺史天。\n青女染成金色浅，冯夷剖出蚌胎圆。\n惭非甘吉曾同传，耻与杨卢议并肩。\n况有词章传乐府，佳名从此入新编。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵苏守金橘' AND p.poem_author = '陈棣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄芝云亭主人', '顾敬', '明代', '云暖幽亭长紫芝，昔年曾许鹤来期。\n短筇空倚清江上，满目春愁两鬓丝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄芝云亭主人' AND p.poem_author = '顾敬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('广陵城（一作孟迟诗）', '赵嘏', '唐代', '红映高台绿绕城，城边春草傍墙生。 \n 隋家不向此中尽，汴水应无东去声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '广陵城（一作孟迟诗）' AND p.poem_author = '赵嘏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('棘闱事竣答别李士衡郡丞', '卢龙云', '明代', '西南天远净妖氛，佐郡风流此属君。刁斗村村秋里息，弦歌处处月中闻。\n\n识韩有客称司命，忆李他时隔论文。樽酒重逢殊未定，江东何地不停云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '棘闱事竣答别李士衡郡丞' AND p.poem_author = '卢龙云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴伯昭红莲绿幕图歌', '黄镇成', '元代', '乌君之山从西来，拔地万仞青崔嵬。划然磅礴下江浒，云麓隐隐栖楼台。\n\n上有飞萝罥挂古乔木，下有沧浪万顷青如苔。红莲绰约泛渚净，绿幕缥缈临湖开。\n\n云烟捲风岛屿没，窗户洗雨冰霜回。高人自是青云客，日向湖亭赏山色。\n\n昔年走马踏红尘，射杀南山双白额。今日纶巾羽扇閒，独面清泠饮冰蘖。\n\n壶箭收投胜负空，棋枰罢局机筹息。延陵公子昔称贤，画手复见今道玄。\n\n有声之画宜诗篇，为子作歌将画传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴伯昭红莲绿幕图歌' AND p.poem_author = '黄镇成';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('文石渔家', '王恭', '明代', '海国春鸿外，人烟尽木乡。潮生孤屿没，月出白沙凉。\n\n夜火邻鲛室，云帆拂蛎房。从来少耕种，辛苦坐沧浪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '文石渔家' AND p.poem_author = '王恭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题李文则画四首 其二 苏公赤壁', '张以宁', '明代', '赤壁江寒叶渐稀，黄泥坂静露斜飞。洞箫声里当时月，应照十年化鹤归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题李文则画四首 其二 苏公赤壁' AND p.poem_author = '张以宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题张宗苍山水画', '弘历', '清代', '搜题宗苍画，迩来略遍矣。盘中见是图，空白惜馀纸。\n\n觌面何处山，科头谁氏子。想彼有卓识，曰应隐於此。\n\n对之率尔言，思之至当理。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题张宗苍山水画' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和秦寿之喜雨', '王之道', '宋代', '云峰拥棱层，不动若顽石。\n追凉困无所，何当日云夕。\n挥箑汗如流，欲卧莫安席。\n云头从北来，微风动疏荻。\n滂沱一尺雨，旱魃惊辟易。\n巾屨获暂御，尊酒容复觅。\n谁怜贫长卿，空洞家四壁。\n熬熬炉炭中，万物同一息。\n明朝槁苗兴，农亩歌帝力。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和秦寿之喜雨' AND p.poem_author = '王之道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭故相王文恪公二首 其一', '林则徐', '清代', '才锡元圭告禹功，公归遵渚咏飞鸿。休休岂屑争他技，蹇蹇俄惊失匪躬。\n\n下马有坟悲董相，只鸡无路奠桥公。伤心知己千行泪，洒向平沙大幕风！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭故相王文恪公二首 其一' AND p.poem_author = '林则徐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵高寿朋殿直喜雪 其二', '释道潜', '宋代', '挟风穿箔打窗纱，窗里人看窗外花。喷玉流珠君岂羡，从来自是五侯家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵高寿朋殿直喜雪 其二' AND p.poem_author = '释道潜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('澄溪清隐图', '黎贞', '明代', '昔年少小耽嬉游，家君携我游冈州。冈州风景最奇胜，使我因之成久留。\n\n浔洋风高高百丈，群英拉我缘萝上。澄溪宛在金山阳，几欲寻幽不成往。\n\n归来城市惟梦思，寸心长挂金山涯。髫年之好别来久，至今郁郁嗟睽违。\n\n当时故旧多如雨，最爱澄溪李夫子。论交于我独忘年，况与家君素知己。\n\n闻君清隐澄溪头，虚檐曲槛临清流。当门一镜湛虚碧，清波不动长悠悠。\n\n兴来俯视真奇绝，云影天光共浮没。人间万类莫逃形，波底鱼龙见活泼。\n\n东风二月春正晴，绕堤碧柳啼金莺。闲同诗客觅佳句，更与渔人歌濯缨。\n\n濯缨歌声齐欸乃，万里乾坤一顾盻。瓮里香醪不用沽，溪头鲜鲤何须买。\n\n临溪脍鲜鲤，好友频相留。百年自得个中乐，一生不识人间忧。\n\n予爱李翁贤，复爱澄溪好。人生此乐真难逢，何须更觅蓬莱岛。\n\n谭君重姻义，索作澄溪诗。几回挥翰不敢赋，我才蹇劣将何为。\n\n共期泛扁舟，直抵金山曲。烦报澄溪清隐翁，早为开轩扫书屋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '澄溪清隐图' AND p.poem_author = '黎贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄题洋川与可学士公园十七首 其九 过溪亭', '吕陶', '宋代', '野亭傍幽溪，从此过溪去。平日已忘机，沙鸥何必惧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄题洋川与可学士公园十七首 其九 过溪亭' AND p.poem_author = '吕陶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登北固楼', '陈孚', '元代', '北固閒回首，荒城夕照中。烟光浮海阔，天影入楼空。\n\n星斗占吴分，江河见禹功。谁家两翁仲，无语立秋风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登北固楼' AND p.poem_author = '陈孚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和文太尉第一无双绝句', '苏颂', '宋代', '未遂退休时望系，再烦居守主恩优。\n自缘齿德高群牧，须在山河最上流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和文太尉第一无双绝句' AND p.poem_author = '苏颂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('楞枷山房二绝', '洪咨夔', '宋代', '八万猊床方丈室，九千书卷半边窗。\n儋翁句子无人问，流水泠泠度石矼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '楞枷山房二绝' AND p.poem_author = '洪咨夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢曹东圳跋吟卷', '武衍', '宋代', '十年湖海仰师儒，八斗衣传子建馀。袖里有诗须印證，句中无眼定趑趄。\n\n吹香玉唾清如许，刮膜金篦病已除。媪扇何曾求贵重，等閒中得会稽书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢曹东圳跋吟卷' AND p.poem_author = '武衍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('巫山一段云 庚子秋仲廪延道中', '周之琦', '清代', '野色侵衣袂，秋痕恼鬓丝。碧云无尽鸟飞迟。心事定谁知。\n\n忆别空馀梦，言归未有期。斜阳冉冉柳依依。长记出门时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '巫山一段云 庚子秋仲廪延道中' AND p.poem_author = '周之琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留别成父弟以贫贱亲戚离为韵五首', '赵蕃', '宋代', '我家如陶舍，幼稚有盈室。\n汝家亦十口，持去何可得。\n嗟我寡兄弟，至此得无戚。\n虽尔敢或忘，呴濡期沫湿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留别成父弟以贫贱亲戚离为韵五首' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重阳淳生日时年四十九矣', '楼钥', '宋代', '汝生四十九年春，犹记双亲喜得孙。\n当慕知非过能寡，敢言学易道弥尊。\n喜吾父子为知己，赖尔诗书遂满门。\n但得团栾长似此，年年萸菊醉清樽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重阳淳生日时年四十九矣' AND p.poem_author = '楼钥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游罗浮四首 其二', '湛若水', '明代', '飞云渺渺来空洞，洞口桃花虚映红。瑶笛长吹千里月，霓裳轻飏五铢风。\n\n玉堂回首即天府，黄石归来是赤松。静啸空山人不见，石楼烟袅麻姑峰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游罗浮四首 其二' AND p.poem_author = '湛若水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赋椿楸二树', '邓深', '宋代', '爱均召伯棠，名殊诸葛菜。\n轩槛顿辉光，东西相映带。\n此意存千年，其势当两大。\n梨枣况久生，於焉称内外。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赋椿楸二树' AND p.poem_author = '邓深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('粤州草堂春日试笔得歌字', '黎民表', '明代', '谢家宾从有羊何，春日池亭载酒过。紫气直从燕阙迥，青山还绕粤城多。\n\n花沾瑞露低唫幌，鸟啭芳林杂棹歌。闻道汉庭偏侧席，未须长恋钓鱼蓑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '粤州草堂春日试笔得歌字' AND p.poem_author = '黎民表';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哀魏方泉 其二', '武衍', '宋代', '诏下催归觐，人传便尹京。班才联从橐，庭忽舞铭旌。\n\n玉树悲中折，金丹圣莫生。泽多唯乳子，天道若无情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哀魏方泉 其二' AND p.poem_author = '武衍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和谢吏部铁字韵三十四首 其二', '邓肃', '宋代', '八斗一倾聊热耳，开匣时观三尺水。指天喝月使倒行，扬波直欲斩蛟子。\n\n安得知音吾党人，相看青眼不余嗔。笑驱八蛮有奇策，开怀聊与话诚真。\n\n可怜吐哺风流绝，乞巧未遑姑守拙。坐观明月侵虾蟆，空使玉川怀寸铁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和谢吏部铁字韵三十四首 其二' AND p.poem_author = '邓肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('初归', '高材', '明代', '照眼芙蕖薄宦回，欢迎稚子驾船来。携亲不敢携鱼鲊，裕后何妨剩砚台。\n\n漫说风波满平地，且呼朋旧共深杯。酒酣拔剑婆娑舞，自笑丹心老未灰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '初归' AND p.poem_author = '高材';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('恭王旧邸萃锦园海棠最盛心畬王孙数约看花至今岁始得践适值歇枝春寒花迟小萼而已', '陈曾寿', '清代', '台蚀朱栏水渴池，曲深萝径隐秾姿。晚春风日犹凄冷，绝世芳菲费护持。\n\n曾是忧勤疏胜事，只今追赏异清时。爇天香烬难通奏，烂漫催开傥待诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '恭王旧邸萃锦园海棠最盛心畬王孙数约看花至今岁始得践适值歇枝春寒花迟小萼而已' AND p.poem_author = '陈曾寿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小诗五首', '钱钟书', '当代', '难觅安必法，聊凭遮眼书。\n意传言以外，夜惜昼之馀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小诗五首' AND p.poem_author = '钱钟书';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送吴生南归', '欧阳修', '宋代', '自我得曾子，於兹二十年。\n今又得吴生，既得喜且叹。\n古士不◇出，百年犹比肩。\n区区彼江西，其产多材贤。\n吴生初自疑，所拟岂其伦。\n我始见曾子，文章初亦然。\n昆仑倾黄河，渺漫盈百川。\n决疏以道之，渐敛收横澜。\n东溟知所归，识路到不难。\n吴生始见我，袖藏新文篇。\n忽从布褐中，百宝写我前。\n明珠杂玑贝，磊砢或不圆。\n问生久怀此，奈何初无闻。\n吴生不自隐，欲吐羞俛颜。\n少也不自重，不为乡人怜。\n中虽知自悔，学问苦贱贫。\n自谓久而信，力行困弥坚。\n今来决疑惑，幸冀蒙洗湔。\n我笑谓吴生，尔其听我言。\n世所谓君子，何异於众人。\n众人为不善，积微成灭身。\n君子能自知，改过不逡巡。\n惟於斯二者，愚智遂以分。\n颜回不贰过，後世称其仁。\n孔子过而更，日月披浮云。\n子路初来时，鸡冠佩豭豚。\n斩蛟射白额，後卒为名臣。\n子既悔其往，人谁御其新。\n丑夫祀上帝，孟子岂不云。\n临行赠此言，庶可以书绅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送吴生南归' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花十绝 其五', '张昱', '元代', '一枝怜似玉，日暮正愁新。寂寞珍珠佩，天寒翠袖人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花十绝 其五' AND p.poem_author = '张昱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题画梅石 其二', '丘逢甲', '清代', '瘦石护寒梅，盎盎回春意。借君铁笛声，吹起群山睡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题画梅石 其二' AND p.poem_author = '丘逢甲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵杂兴二百首 其八十九', '苏泂', '宋代', '四十之年又过一，春光回施少年人。如丝杨柳看如絮，昼锦堂中又一春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵杂兴二百首 其八十九' AND p.poem_author = '苏泂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑子', '寇梦碧', '近代', '小荷才露尖尖角，翠嫩香柔。占断芳洲，怕有蜻蜓立上头。\n\n词禅参到芬陀利，无乐无忧。莫莫休休，不见春来怎见秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑子' AND p.poem_author = '寇梦碧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('香雪斋为郭张虚茂才赋', '胡应麟', '明代', '茆斋馀十尺，香雪绽雕栏。独树孤山老，千花大庾寒。\n\n高楼吹渐落，古驿寄仍残。欲唤娉婷语，师雄梦未阑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '香雪斋为郭张虚茂才赋' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄项秘监', '释元肇', '宋代', '吴中住岁馀，所乐在诗书。有句题幽石，无人识借居。\n\n蓬莱最高处，雅颂正关渠。此道能如古，今谁伴直庐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄项秘监' AND p.poem_author = '释元肇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读大唐西域记十三首 其一', '释函是', '明代', '世无转轮王，赡部有四主。人主南面尊，上下中规矩。\n\n象主清心累，声教流东土。刑名所勿逮，可以翼周鲁。\n\n贞淫通三世，功高于伯禹。生当仁义邦，复饮五天乳。\n\n一苇从西航，儿孙安足数。努力同斯人，毋宁负前古。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读大唐西域记十三首 其一' AND p.poem_author = '释函是';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('初住大通寄华林法属', '成鹫', '明代', '偶寻江介宿荒庵，回首城中见盍簪。烟雨有时迷穗石，风波无路阻鹅潭。\n\n木鸡老去慵司晓，白雁秋来早向南。家在华林归未得，欲酬恩遇愧同参。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '初住大通寄华林法属' AND p.poem_author = '成鹫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('细雨', '晁公溯', '宋代', '细雨真宜麦，轻阴似养花。\n人烟随土断，村径逐溪斜。\n大道能方轨，春泥欲溅车。\n归来洗*鞾袴，城郭未吹笳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '细雨' AND p.poem_author = '晁公溯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('炬长老请赞', '释法薰', '宋代', '刀不自截，水不自洗。\n我真我赞，成何道理。\n请之既坚，却之不已。\n有一句子，玄沙道底。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '炬长老请赞' AND p.poem_author = '释法薰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和李觏《送春绝句二首寄呈龙学》 其二', '祖无择', '宋代', '万树红芳落渐稀，浮荣能得几多时。孤根未识阳和力，春去春来两不知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和李觏《送春绝句二首寄呈龙学》 其二' AND p.poem_author = '祖无择';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('瓦官寺', '胡宿', '宋代', '紫色尝开国，金辉此界绳。火轮经坏劫，雪顶见残僧。\n\n狂薜缘秋壁，深松映晚灯。哀猿不可听，一一在岩藤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瓦官寺' AND p.poem_author = '胡宿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄葵花', '韩维', '宋代', '春花夏蕊已飘零，秀出秋芳一朵倾。\n禀赋定应全得土，遮围须合尽雕琼。\n鹄衣照水匀颜色，仙袂无尘莫壮名。\n应笑菊花妍意少，篱边冷落伴渊明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄葵花' AND p.poem_author = '韩维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天竺寺一首', '黄省曾', '明代', '窈窕招提境，何年阿育开。泉泉皆八绕，树树作双栽。\n\n雁刹青鸳出，珠函白马来。碧题看竺国，何异化城回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天竺寺一首' AND p.poem_author = '黄省曾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日', '陈藻', '宋代', '独上谯楼日一廻，春风桃李满城开。\n狂夫欲语无人听，呼取闲云共酒杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日' AND p.poem_author = '陈藻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送盛顺伯归丹阳', '龚鼎孳', '明代', '人雒相看鬓发苍，十年踪迹阻沧桑。畏途自懒嵇中散，古道难忘盛孝章。\n\n龙卧东京留党锢，乌啼北寺共星霜。樽前欲别重牵袂，辇路长秋过夕阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送盛顺伯归丹阳' AND p.poem_author = '龚鼎孳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与郑时敏登楼把酒书二绝 其二', '王十朋', '宋代', '登楼能赋非王粲，沽酒忘形有郑虔。千里相从文字饮，不辞费尽杖头钱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与郑时敏登楼把酒书二绝 其二' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙 其一', '刘辰翁', '宋代', '睡过花阴一丈，愁深酒力千钟。梦魂不得似游蜂。\n\n瓶花无密约，到处自神通。\n\n天上西湖似锦，人间骄马如龙。今年不与去年同。\n\n飘零终不恨，难与故人逢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙 其一' AND p.poem_author = '刘辰翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('为谢良翰题玉山草堂', '陈枨', '明代', '众壑结苍翠，一峰淩紫云。传云昔达人，于此避垢氛。\n\n山空无鹤驭，石老空苔纹。之子构草堂，长年慕清芬。\n\n松风夜谡谡，萝月秋纷纷。种木缘古崖，翻书落香芸。\n\n门无俗客到，榻许山人分。兹晨鸰鹗荐，远谢麋鹿群。\n\n为赴苍生期，奚惭北山文。公馀睇旧隐，云气还氤氲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '为谢良翰题玉山草堂' AND p.poem_author = '陈枨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送赵安伯县丞之任婺源', '范浚', '宋代', '邑丞清操如臞儒，人言帝宗千里驹。燃膏夜绝学更苦，下笔欲命骚为奴。\n\n往年给札试西省，堵墙学士纷惊呼。归来汀草乱袍色，上食日向庭闱趋。\n\n君家先烈今谁如，江州黄州忠义俱。绿林豪客为蒲伏，刮肠洗胃投戈殳。\n\n我方三叹揖盛事，欲纪劲节惭才芜。君其努力济世美，倘登要路须捐躯。\n\n春流起柂花芬敷，取别草草如惊凫。君逢后日南来客，莫忘书札贻潜夫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送赵安伯县丞之任婺源' AND p.poem_author = '范浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大佛寺 其二', '姚佳', '当代', '三生开圣迹，百感此登临。契阔王摩诘，逍遥支道林。\n\n白云能悟道，明月最知心。铁帚无情甚，至今何处寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大佛寺 其二' AND p.poem_author = '姚佳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵怀古', '骆成骧', '近代', '芦荻萧萧万古秋，金陵佳丽帝王州。江从汉口横京口，人立山头望石头。\n\n西塞波涛无险阻，南朝宰相有风流。只应拊断曹公掌，谁复生儿似仲谋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵怀古' AND p.poem_author = '骆成骧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日杂咏二十三首 其二十三 咏边塞', '孙承恩', '明代', '穷边秋气早，六月飞霜华。胡儿弓力强，马蹄蹴风沙。\n\n黄云连白草，极目天无涯。孤城控险阨，令严寂不哗。\n\n凄风传画角，落日悲鸣笳。征人于此际，谁不动思家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日杂咏二十三首 其二十三 咏边塞' AND p.poem_author = '孙承恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题谢孔昭画山水和邵师圣韵', '龚诩', '明代', '懒逐诸公入省台，分甘无用老岩隈。凭君说向清风道，莫放红尘到此来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题谢孔昭画山水和邵师圣韵' AND p.poem_author = '龚诩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送春', '黄公辅', '明代', '何处送春酒一杯，风为信使雨为媒。有期难作攀留计，莫语空登寂寞台。\n\n蝶绕篱边深缱绻，花浮水面重徘徊。相思直待梅花发，又是东君一度来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送春' AND p.poem_author = '黄公辅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庐山白莲社', '释怀悟', '宋代', '才高孰谓文中龙，返使伊人思谢公。\n烟飞露滴玉池空，雪莲蘸影摇秋风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庐山白莲社' AND p.poem_author = '释怀悟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题画小景', '张玉娘', '元代', '山合云初尽，溪阴下夕阳。贪看无限好，柳底坐秋光。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题画小景' AND p.poem_author = '张玉娘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题秋山访隐图', '蓝仁', '元代', '遥峰苍苍白云白，红树黄花间秋色。三径曾寻蒋诩居，一区尚忆扬雄宅。\n\n十年不见鹤田翁，远水长山入梦中。凉飙散荣远林静，微雨湿衣空翠浓。\n\n先生见客幡然出，发短眉长眼如漆。穷高极厚作千年，虚往实归凡几日。\n\n画图绝似鹤田秋，不许同行只独游。黄绮正须天子召，巢由底用世人求。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题秋山访隐图' AND p.poem_author = '蓝仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('倪云林秋林山色图', '弘历', '清代', '元称四大家，逸品推倪迂。师承自北苑，笔与造化俱。\n\n小景夙所见，秋林位置殊。一扫了了习，不失太古初。\n\n峣峰既隐轸，雄霓时卷舒。疑有风吹林，已见波绉湖。\n\n不宁供游历，此中乃可居。画禅大法眼，岂伊邪许徒。\n\n因忆乔林乔，未识渔庄渔。得陇而望蜀，知足其谁乎。\n\n呵冻志长言，聊以适三馀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '倪云林秋林山色图' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春·静寿先生', '张榘', '宋代', '静寿先生，笑傲四并，醉眠孄窝。甚一枰棋壤，掉头不顾，同舟风紧，袖手高歌。太白词华，更生忠愤，为问山林老得麽。须知道，有淮碑未作，浯石当磨。年来君子无多。试屈指、如公能几何。况刍荛公论，新曾推许，冕旒异眷，行见搜罗。泽润生民，洗清兵甲，待挽钱塘江上波。功名就，访蟠桃把玩，铜狄摩挲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春·静寿先生' AND p.poem_author = '张榘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠拔可', '黄浚', '近代', '谓君未老成秃翁，谓君已老心尚童。頩颜不酒生醉红，饮博揎臂如疾风。\n\n摄衣昨上始馨峰，能忍恐怖为趫雄。奇怀妙手骇雨工，搏注九瀑森天龙。\n\n果然雕句挚且丰，谁信乃出坦荡胸。小车犯雨白下逢，一抚叔病药有功。\n\n还君书仓辉南东，万卷络绎异国供。规志勇锐众口同，曷克致之朴以忠。\n\n我惭多斲伤烧桐，食贫为官百态攻。墨巢蓊郁惟君宫，绿阴敷榻酒一中。\n\n得蠲世事愿永从，以诗寻医期击蒙，君倘念我言由衷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠拔可' AND p.poem_author = '黄浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('文宣王及其弟子赞 其三十五', '赵构', '宋代', '在昔石邑，能知所尊。懋依有德，克述无言。鼓箧槐市，扬名里门。\n\n此道久视，彼美长存。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '文宣王及其弟子赞 其三十五' AND p.poem_author = '赵构';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同社诸公出郊看花至东山寺', '欧大任', '明代', '报我江头花已开，披榛墟曲兴偏催。桥从饮马塘边过，策向呼鸾道上来。\n\n春草先传康乐句，暮云谁似惠休才。芳尊不是攒眉客，记取东林一度回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同社诸公出郊看花至东山寺' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赋得甘露台赠胡明府', '欧大任', '明代', '山邑分符政已成，筑台甘露表贤声。铜盘八月分双阙，玉树三危注五城。\n\n南海总歌明主瑞，西京曾识使君名。臣清本是胡家事，不少中原揽辔情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赋得甘露台赠胡明府' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆东林精舍寄示华生云', '邵宝', '明代', '东林寺里旧书堂，三十年来野草荒。百啭未忘初鸟韵，一株犹剩晚柑香。\n\n山怀龙阜神俱远，水问梅村脉故长。寄语云生为磨石，客中新记已成章。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆东林精舍寄示华生云' AND p.poem_author = '邵宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('广州三首 其三', '释函是', '明代', '万里悲笳朔气深，故园摇落倍沾襟。登楼漫拟刘琨啸，出郭谁为梁甫吟。\n\n普天丘墓无新旧，近海云山有古今。去国岂须怜郑谷，徘徊鸥鸟是知音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '广州三首 其三' AND p.poem_author = '释函是';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟过望亭三首', '杨万里', '宋代', '常州尽处是望亭，已离常州第四程。\n柳线绊船知不住，却教飞絮送侬行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟过望亭三首' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晓离杨梅驿', '韦骧', '宋代', '长坡峻阪足崎岖，晓出杨梅古驿孤。山腹带云如曳练，稻梢垂露欲流珠。\n\n穿篱鸭脚深深碧，近水鸡冠小小株。行役虽劳遇佳境，且将幽句慰瘏痡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晓离杨梅驿' AND p.poem_author = '韦骧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('发孔镇晨炊漆桥道中纪行十首', '杨万里', '宋代', '雨入秋空细复轻，松梢积得太多生。\n忽然落点拳来大，偏作行人滴伞声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '发孔镇晨炊漆桥道中纪行十首' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙 今年国庆，适值中秋，佳节团圞，万方同乐，纪兹盛况，辄复倚声。', '黄驾白', '近代', '淡淡银汉涌玉盘。人间天上共团圞。神州大陆正腾欢。\n\n一统山河欣在望，万端经纬蔚奇现。金瓯无缺壮瀛寰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙 今年国庆，适值中秋，佳节团圞，万方同乐，纪兹盛况，辄复倚声。' AND p.poem_author = '黄驾白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秦中怀古 其三', '于式枚', '清代', '东井西河辟上都，文谟武烈递乘除。云霓赤帝三章法，日月苍姬六典书。\n\n栖凤何年来白虏，伏龙从古护皇图。金戈铁马纵横地，放眼千秋几丈夫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秦中怀古 其三' AND p.poem_author = '于式枚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('许二烈女 其一', '屈大均', '明代', '双雏随阿母，游戏在芝田。正鼓湘灵瑟，俄惊老上弦。\n\n银瓶齐坠井，玉镜不当天。百尺寒浆里，连枝产白莲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '许二烈女 其一' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送乡友之扬州', '卢龙云', '明代', '木叶催寒序，他乡动客愁。君方随旅雁，我独怅鸣驺。\n\n斗下分雄剑，霜前怯敝裘。暮云将鹤去，何日到扬州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送乡友之扬州' AND p.poem_author = '卢龙云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('州宅杂咏 竹', '王十朋', '宋代', '郡斋谁种竹，绿荫未多浓。我欲添清閟，殷勤护箨龙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '州宅杂咏 竹' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庆宫春 七月返湖庐', '陈曾寿', '清代', '莎隐虫声，苇低萤点，再来秋遽如许。湿透寒香，泠泠露下，袭襟疑是过雨。\n\n鹭乡曾惯，甚今度、悽魂触绪。依稀留梦，别院回灯，案尘重抚。\n\n年时艳冶春光，纵酒心情，断烟无据。萧疏至此都难说，似蹇尽、人天言语。\n\n素波摇瞑，尚萦惹、残霞一缕。那容消受，恨水颦山，镇长伴住。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庆宫春 七月返湖庐' AND p.poem_author = '陈曾寿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六幕山访南宋宫入斜 其一', '文静玉', '清代', '从古蛾眉怨入宫，长门老死后庭空。几堆浅土秋阴里，无数残碑暮雨中。\n\n晋代玉弓惊谢奂，汉家金碗失卢充。江山半壁朝廷小，一样怜香葬落红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六幕山访南宋宫入斜 其一' AND p.poem_author = '文静玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寒悰 其二', '王彦泓', '明代', '岁晏无聊别绪盈，一枝梅萼寄卿卿。浣纱衫袖年年湿，碧玉梳奁事事清。\n\n调态几曾因病减，鲜妍多是称情生。自怜身世凄凉足，单占名花第一名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寒悰 其二' AND p.poem_author = '王彦泓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送彦与孙兄赴廷对', '刘宰', '宋代', '捷书夜到古朱方，之子登名甲乙行。\n伟行向来高月旦，遗经端合破天荒。\n公孙对策风云会，董子留名日月光。\n趋向一分燕越异，赠言惟有用心刚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送彦与孙兄赴廷对' AND p.poem_author = '刘宰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('钟南平祠像', '吕南公', '宋代', '天禄空虚土运崩，匹夫徒手起欃枪。还将有限骁雄力，换得无穷跋扈名。\n\n已是用心贪祸乱，尚何颜面见升平。丹青此日凝埃色，尚似忧惭问罪兵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '钟南平祠像' AND p.poem_author = '吕南公';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('仲春三衢道中', '胡宿', '宋代', '隔闰年芳早，天风泛暖晖。酒香迎社重，村语向蚕稀。\n\n林际新莺出，楹间故燕归。湖头春在否，人去柳花飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '仲春三衢道中' AND p.poem_author = '胡宿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('承濂泉和章就用韵答之', '黄淮', '明代', '里闬间关千里隔，客边邂逅片言同。子应扫兔才华健，我亦雕虫末技工。\n\n襟抱共开沧海量，交情期振古人风。且须守道相磨砺，岂学区区叹转蓬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '承濂泉和章就用韵答之' AND p.poem_author = '黄淮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵答刘克勤', '云峰住公', '明代', '老来轩冕不须期，还慕林泉岁月迟。\n双眼长青惟爱客，满头都白苦缘诗。\n尚传天禄书千卷，犹对青藜杖一枝。\n无事闲来依佛日，白云深处启禅扉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵答刘克勤' AND p.poem_author = '云峰住公';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春夜过时济饮', '薛蕙', '明代', '露净开樽处，天青岸帻时。\n素云将月上，香雾任风吹。\n为乐常苦晏，含情复待谁。\n径须成一醉，莫遣酒行迟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春夜过时济饮' AND p.poem_author = '薛蕙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登城古咏', '王序宾', '清代', '楼台高下入清秋，林木萧萧叶有声。回首西风几兴废，夕阳古寺是梁城。\n\n吴时风景楚郊原，终古青山对郭门。舰浦萧条陈郡废，寒鸦数点集孤村。\n\n子城仍是旧时军，雉堞参差锁暮云。惆怅九原不可作，刘伶坟对杜康坟。\n\n遥塘飒飒响寒芦，觌面双峰近可呼。独自归云庵外立，一钩新月照前湖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登城古咏' AND p.poem_author = '王序宾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和赵类庵灯花', '陆深', '明代', '诵君灯花篇，值我灯花灿。旖旎欲浮香，敷披似春半。\n\n圆朵竞霞呈，岐枝误星散。娱玩夜三更，迟回肠九转。\n\n献祥谅无私，凉德歌有腼。南郊礼将成，预兆明庭宴。\n\n无藉春风吹，偶见春风面。影摇画屏斜，蕊堕银檠乱。\n\n君才本天妙，况复论交淡。游戏赋灯花，膏馥人犹厌。\n\n丽藻凌六朝，高风驾前彦。倘许望后尘，铅椠从兹办。\n\n寒灯复作花，政尔从人愿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和赵类庵灯花' AND p.poem_author = '陆深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('齐天乐 湘潭黄君修杞以其先人忠壮公双鱼图诗遗墨徵题，填此以应', '刘鹏年', '近代', '波痕绿上潇湘岸，丝丝柳风吹鬓。巨海鞭鲸，长江饮马，生恐壮怀消尽。\n\n吟边剑影。怅芳草天涯，锦鳞无信。绢素谁描，唼花戏藻碧潭静。\n\n匆匆旧游似梦，记画船烟雨，鲜脍初进。桃水深情，濠梁逸致，并入奚囊佳咏。\n\n将星夜陨。更碧化三年，图寒八阵。破壁龙飞，恍闻笳鼓竞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '齐天乐 湘潭黄君修杞以其先人忠壮公双鱼图诗遗墨徵题，填此以应' AND p.poem_author = '刘鹏年';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秦州杂诗二十首 其五', '杜甫', '唐代', '南使宜天马，由来万匹强。浮云连阵没，秋草遍山长。\n\n闻说真龙种，仍残老骕骦。哀鸣思战斗，迥立向苍苍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秦州杂诗二十首 其五' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('呈潘潭州十首', '赵蕃', '宋代', '梅花初出炯如冰，未许余花似我能。\n太息天公不加意，放教风雨苦侵陵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '呈潘潭州十首' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈', '释慧印', '宋代', '韶石渡头，舟横野水。汾阳浪里，棹发孤烟。云月无私，溪山岂异。\n\n一言合辙，千里同风。八千弟子今何在，万里山河属帝家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈' AND p.poem_author = '释慧印';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重经漂母祠', '戴梓', '清代', '漂母祠犹在，凄然日欲西。义惟轻一饭，名已重三齐。\n\n白马垂纶岸，清江浣苧溪。望中人不见，荒草雉还飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重经漂母祠' AND p.poem_author = '戴梓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桂殿秋 冬夜有怀兄妹', '丁淑媛', '清代', '鱼信断，雁行疏。腊梅香里岁将徂。停针自起推窗望，寒照亭亭恰午馀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桂殿秋 冬夜有怀兄妹' AND p.poem_author = '丁淑媛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('至日怀罗国宾', '仇远', '宋代', '群阴剥尽一阳回，霜日烘晴宿雾开。\n闭户读书差自乐，载肴问字莫须来。\n荣枯易了观芸草，冷暖相忘付酒杯。\n得似山居酬应少，昼长閒坐看寒梅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '至日怀罗国宾' AND p.poem_author = '仇远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠兖州朱十四 其二', '屈大均', '明代', '嗟君闾里侠，金尽欲如何。乱后田园少，愁中鼓角多。\n\n将军无细柳，渔父且沧波。怀有遗书在，行行避紫驼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠兖州朱十四 其二' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归田乐 又题渡江词', '翁瑞恩', '清代', '旗亭唱罢赓酬句。吟到邗江烟树。山色与波光，都写行装彩毫助。\n\n金焦两点看飞渡。远浦忽惊鸥鹭。风饱一帆悬，莼羹鲈脍人归去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归田乐 又题渡江词' AND p.poem_author = '翁瑞恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满替在眼即景赋二首 其二', '董嗣杲', '宋代', '菊向篱阴老，松连石影交。山梨寒脱树，溪鸟晚投巢。\n\n欲把肩舆卸，先将手版抛。是时柴户月，任客带吟敲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满替在眼即景赋二首 其二' AND p.poem_author = '董嗣杲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大同春吟己丑作四首 其四', '湛若水', '明代', '天道玄同是，群分自作家。春诗拈未出，春信已开花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大同春吟己丑作四首 其四' AND p.poem_author = '湛若水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高阳台·右台埽墓，郁郁悲怀。绵绵细雨，坟前留连久坐，不禁泪下', '许禧身', '清代', '草色含春，梅枝带露，数行垂柳眉生。凹凸云山，观来翠黛千层。\n\n疏篱茅屋闻厖吠，听流泉、断续低鸣。墓门横。触目伤情，何日能平。\n\n秋心结就何时解，叹朝朝暮暮，只自眉颦。绞结中肠，丝丝欲理难清。\n\n纷纷细雨催归去，却一肩、绕遍深林。几牵萦。青冢巍巍，渺渺仙軿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高阳台·右台埽墓，郁郁悲怀。绵绵细雨，坟前留连久坐，不禁泪下' AND p.poem_author = '许禧身';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽李漕二首', '洪咨夔', '宋代', '翰墨多推毂，功名早着鞭，\n风行青草外，春到白盐边。\n老去心犹壮，归来意正便，\n如何天不憗，烟雨閟新阡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽李漕二首' AND p.poem_author = '洪咨夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅影', '吕宏基', '清代', '笑颜曾向步檐开，几许传心鹤梦回。今夜小园人半醉，澹烟疏月送君来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅影' AND p.poem_author = '吕宏基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一眺石', '傅伯寿', '宋代', '一眺人间万事非，海鸥山鸟便忘机。林端髣髴见帆影，知有扁舟天际归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '一眺石' AND p.poem_author = '傅伯寿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再和寇十一二首 其二', '陈师道', '宋代', '与世相违孰自量，资身无策漫多方。逢场作戏真呈拙，误笔成蝇岂所长。\n\n名字不归青史笔，形容终老白云乡。可须五斗轻千里，赖有斯人未肯忘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再和寇十一二首 其二' AND p.poem_author = '陈师道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题成倅小筑', '陈造', '宋代', '主人领客竟成迟，闲杀林园此段奇。\n胜日阿莲须后乘，即今佳菊尚东篱。\n肯来雪壁题诗处，许继华堂堕帻时。\n醉后与渠同起舞，一庭花影月迷离。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题成倅小筑' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('除夜', '佚名', '唐代', '荒城何独泪潸然，闻说今宵是改年。亲故睽携长已矣，幽缧寂寞镇愁煎。\n\n更深肠绝谁人念，夜永心伤空自怜。为恨漂零无计力，空知日夕仰穹天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '除夜' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬夜和逸老八首 其三', '陈永正', '当代', '旷荡川原草木髡，珠江声咽晚潮昏。稍寒云意绵绵去，欲倦风情漠漠黁。\n\n屑泪拈花谁索笑，微霜侵指发堪扪。万缘纷纠清宵坐，待看春生古石根。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬夜和逸老八首 其三' AND p.poem_author = '陈永正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('正月十四日大雪上信国公冢', '赵文', '宋代', '哭得愁云转不晴，山风吹泪欲成冰。\n两年不过西州路，今日来登下马陵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '正月十四日大雪上信国公冢' AND p.poem_author = '赵文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泛黄河自宁夏达包头镇舟行杂咏 其十', '俞明震', '清代', '家似离巢燕，身如出塞云。窥天终自幸，垂老厌多闻。\n\n河尽东南转，山从朔漠分。纪行聊复尔，大地本无垠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泛黄河自宁夏达包头镇舟行杂咏 其十' AND p.poem_author = '俞明震';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('食菜作二首', '廖行之', '宋代', '吾儒不羡能方丈，彼相胡为食万钱。\n谁识春来有珍味，乐如疏食曲肱眠。\n园中菜把勤能致，曹掾莼羹美未专。\n便作远谋胜肉食，他年无愧作诗篇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '食菜作二首' AND p.poem_author = '廖行之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('捣练子 咏愁', '王夫之', '明代', '刚有绪，又无端。细雨千丝月半弯。一寸眉棱千障压，不教人放片时閒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '捣练子 咏愁' AND p.poem_author = '王夫之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送林大参上京贺太后尊号 其二', '祁顺', '明代', '圣母尊崇万国钦，贺章驰献见忠忱。青霄红日瞻依近，湛露需云宠渥深。\n\n暂别忍裁知己赋，遄归期慰小民心。使旌重过湖湘路，旧憩甘棠绿满林。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送林大参上京贺太后尊号 其二' AND p.poem_author = '祁顺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登南雄塔', '庞嵩', '明代', '玉笋凌千仞，虹轮跨九霄。拂衣红日近，回首白云遥。\n\n树色通阛阆，山光入画描。暂同登眺乐，心已在明朝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登南雄塔' AND p.poem_author = '庞嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄题刁经臣润州园亭', '梅尧臣', '宋代', '新作城边圃，陂原上下斜。\n竹多刘裕宅，松接戴顒家。\n山色不须买，江流何处涯。\n但邀东海月，莫听五更鸦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄题刁经臣润州园亭' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东海', '华镇', '宋代', '谁谓沧溟远，吾家曲槛东。灵潮随月长，积水与天通。\n\n白鸟长沙外，青峰薄雾中。星槎在何处，屈指待秋风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东海' AND p.poem_author = '华镇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题蘖庄图卷五首 其一', '汪精卫', '近代', '儒家重饰终，墨子论薄葬。事人与明鬼，于义各有当。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题蘖庄图卷五首 其一' AND p.poem_author = '汪精卫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泛舟过金家埂赠卖薪王翁', '陆游', '宋代', '水生浦漵多浮鸭，风急汀洲有断鸿。\n渺渺江天无限景，一时分付与樵翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泛舟过金家埂赠卖薪王翁' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同谊夫国才饯季然于普门院取壁间五字诗各探一句为韵赋五诗某得共饮碧苔畔 其四', '王灼', '宋代', '尘榻为子下，柴扉为子开。从今断还往，一室长莓苔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同谊夫国才饯季然于普门院取壁间五字诗各探一句为韵赋五诗某得共饮碧苔畔 其四' AND p.poem_author = '王灼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送柳城幕长古绍先', '陈琏', '明代', '酌别溪亭上，薰风拂面凉。绿披蕉叶嫩，红绽藕花香。\n\n衡岳连天远，湘江入海长。相逢定何日，客思转茫茫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送柳城幕长古绍先' AND p.poem_author = '陈琏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洛阳有愚叟', '白居易', '唐代', '洛阳有愚叟，白黑无分别。浪迹虽似狂，谋身亦不拙。 \n 点检盘中饭，非精亦非粝。点检身上衣，无馀亦无阙。 \n 天时方得所，不寒复不热。体气正调和，不饥仍不渴。 \n 闲将酒壶出，醉向人家歇。野食或烹鲜，寓眠多拥褐。 \n 抱琴荣启乐，荷锸刘伶达。放眼看青山，任头生白发。 \n 不知天地内，更得几年活。从此到终身，尽为闲日月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洛阳有愚叟' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('灌口秋涨', '王翥', '宋代', '所向愁无地，穷源欲上天。\n蛟龙胡尔怒，鸥鹭更谁怜。\n万里朝宗意，群凶跋扈年。\n生涯秋色裹，独立问渔船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '灌口秋涨' AND p.poem_author = '王翥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('许州赠颜守木', '李濂', '明代', '汝病三辞印，吾来两驻车。\n雪堂留倡和，秋榻共琴书。\n堕泪看归雁，谋身作老渔。\n行藏惭颇似，把袂各踌躇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '许州赠颜守木' AND p.poem_author = '李濂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丁亥秋事六章 其四 秋气', '添雪斋', '当代', '精金当大冶，万籁倏缃赪。霜起夜寒渐，气衰银露生。\n\n空巢惊老燕，黯者拥孤声。天地不仁矣，由来作别情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丁亥秋事六章 其四 秋气' AND p.poem_author = '添雪斋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桂花', '邹浩', '宋代', '丹桂从来未发花，今年花发众惊嗟。盈盈簇盖真珠细，片片笼车美玉斜。\n\n阊阖携香熏席绮，嫦娥流影动窗纱。乾坤着意欣逢遇，收得风光向北誇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桂花' AND p.poem_author = '邹浩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送行人蔡英夫奉旨颁流求国王印宝就与国王之来享者二人同驾海舟自福建起柁', '谢肃', '明代', '五虎门西叠鼓挝，行人承诏自皇家。刻金鸟篆颁王号，建节龙骧戛海霞。\n\n两国夷君归绝岛，万年天子御中华。预知奉使旋京日，浩荡秋涛涌月槎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送行人蔡英夫奉旨颁流求国王印宝就与国王之来享者二人同驾海舟自福建起柁' AND p.poem_author = '谢肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭李景温架阁', '刘克庄', '宋代', '挟策说荆州，那知亦暗投。\n漫招温处士，几杀杜参谋。\n出幕有清议，还乡空白头。\n人间容不得，下与阿翁游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭李景温架阁' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('醉春风', '王微', '明代', '谁劝郎先醉，窗冷灯儿背。抛琴抱婢倚香帏。睡。睡。\n\n睡。暗忖欢情，争如贪着，醉乡滋味。\n\n惭愧鞋儿谜，耽搁鸳鸯被。问郎曾否脱罗衣。未。未。\n\n未。想应神女，见时也怕，别时容易。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '醉春风' AND p.poem_author = '王微';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九月四日刘子见过二首 其二', '何景明', '明代', '汝病稀相见，高诗久不闻。侧思金石奏，喜挹蕙兰芬。\n\n细菊妍霜昼，繁砧乱朔云。萧萧秋日兴，对尔忆离群。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九月四日刘子见过二首 其二' AND p.poem_author = '何景明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桓野王画像', '周文璞', '宋代', '胡床三弄清溪笛，叹息欷歔太极筝。\n怊怅斯人风味减，江花江草不胜情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桓野王画像' AND p.poem_author = '周文璞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵通明叟晚春二十七首 其五', '释德洪', '宋代', '居近幽林复碧江，水光林翠到西窗。鹧鸪啼竹声相应，鸂鶒眠沙只一双。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵通明叟晚春二十七首 其五' AND p.poem_author = '释德洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏儒释道三教总赠程洁庵：道教十四首 其四 损之又损', '李道纯', '元代', '艮兑交重山泽损，戒人惩忿绝嗔痴。损之又损无惩窒，绝学无为入圣基。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏儒释道三教总赠程洁庵：道教十四首 其四 损之又损' AND p.poem_author = '李道纯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和侯利建运使朝请', '彭汝砺', '宋代', '当年置酒岘山亭，公作新诗我载赓。疾病尚怜忧似醉，文章还看美如英。\n\n伤哉无复老莱戏，久矣不闻韶乐声。饥鹄欲飞嗟已老，谬烦江汉借修程。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和侯利建运使朝请' AND p.poem_author = '彭汝砺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上林春令·十一月三十日见雪', '毛滂', '宋代', '蝴蝶初翻帘绣。万玉女、齐回舞袖。落花飞絮蒙蒙，长忆著、灞桥别后。 \n浓香斗帐自永漏。任满地、月深云厚。夜寒不近流苏，只怜他、后庭梅瘦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上林春令·十一月三十日见雪' AND p.poem_author = '毛滂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('下邳寻圯桥授书处', '欧大任', '明代', '黄石书何在，斯人竟不还。门低浊河树，家远谷城山。\n\n百战宁虞楚，孤军蚤入关。空悲泗亭水，日夜自潺湲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '下邳寻圯桥授书处' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋夜', '黄庚', '宋代', '十分秋色满轩窗，景物凄清夜气凉。\n筛月帘栊金琐碎，捣霜砧杵玉丁珰。\n井梧叶脱无多影，岩桂花稠不断香。\n坐到更深吟兴动，砚池滴露写诗狂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋夜' AND p.poem_author = '黄庚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日闲坐', '朱淑真', '宋代', '社燕归来春正浓，摧花雨晴一番风。\n倚楼闲省经由处，月馆云藏望眼中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日闲坐' AND p.poem_author = '朱淑真';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('捕鱼词', '张昱', '元代', '渔家无别业，衣食惟罟网。生长风波中，舟楫惯来往。\n\n江平风波静，天静榔板响。得鱼固所欲，忖心辄内怏。\n\n群生各有命，吾宁受其养？敢恣口实求，而绝生意盎。\n\n遐思放麑翁，乃属中山相。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '捕鱼词' AND p.poem_author = '张昱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题四兰 其一 风', '释绍昙', '宋代', '深藏岩谷里，初不要人知。苦是香难掩，春风得意吹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题四兰 其一 风' AND p.poem_author = '释绍昙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄郭', '真山民', '宋代', '烟波秋草外，活计一渔篷。淡月明寒苇，新霜醉晓枫。\n\n身虽殊出处，道岂有穷通。俯仰看人面，何如数过鸿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄郭' AND p.poem_author = '真山民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('淳祐丙午讲礼记毕锡宴秘书省赐侍读少师郑清之以下', '赵昀', '宋代', '鳌极开先已降衷，上天下泽礼居中。三才义理维持力，万世纲常建立功。\n\n孔圣法言多纂辑，汉儒师学共修崇。经帷讲彻资群彦，克己工夫在广充。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '淳祐丙午讲礼记毕锡宴秘书省赐侍读少师郑清之以下' AND p.poem_author = '赵昀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满城道中', '郝经', '元代', '十二西郎缥缈中，颜行壁立插晴空。欲携天地诸山去，不逐秦鞭过海东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满城道中' AND p.poem_author = '郝经';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('芹溪八咏', '叶善夫', '宋代', '芹溪处士古人风，宝剑尘埋未化龙。\n旧隐至今名不朽，扁题元出紫阳翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '芹溪八咏' AND p.poem_author = '叶善夫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪', '杨孚', '两汉', '鸟象雌鸡，自名鹧鸪。其志怀南，不思北徂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪' AND p.poem_author = '杨孚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春贴子词 其五', '周麟之', '宋代', '凤盖龙车玉作轮，北临紫畤谒三神。已将福酒添眉寿，更祝椒觞一万春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春贴子词 其五' AND p.poem_author = '周麟之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送李容甫归北都', '释斯植', '宋代', '先生读书不下堂，堂上有客语浪浪。\n弟子出观如堵墙，怪君眉彩生光芒。\n北都晁夫子，一别久相望。\n君来道信问，使我开肺肠。\n三日不改服，犹觉芝兰香。\n平生寡投分，一笑且云乐。\n殷勤发黄卷，钝吻悭应酢。\n大杵撞哑钟，已厌音响恶。\n更惭河伯观，未易穷海若。\n索寞岁华晚，飕飕黄叶秋。\n归心剧流水，忽忽不可留。\n固知此鲈鲸，肯托寻常沟。\n直须见老聃，可化南荣俦。\n海州岁有冲天鹄，卵如萍实光琢玉，\n蜀鸡眇然何敢伏。羽成不须求日浴，\n一举将惊万人目。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送李容甫归北都' AND p.poem_author = '释斯植';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舍陆就汀舟喜见家乡在即三首 其三', '郭之奇', '明代', '青山频过不知名，但忆乡关此地迎。昨夜归魂先识路，秋风吹向绿榕城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舍陆就汀舟喜见家乡在即三首 其三' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('简艮斋', '曾丰', '宋代', '得古濂溪派，惟今谢艮斋。\n冥搜穷骨髓，燕坐黜形骸。\n晚景登乌府，秋风立玉阶。\n狐狸无暇问，阊阖莫空排。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '简艮斋' AND p.poem_author = '曾丰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和韵送陆员外', '王翰', '元代', '邂逅梁园始识君，喜瞻眉宇胜空闻。胸中泉石元无价，笔底珠玑迥不群。\n\n一曲离歌迷汴水，满襟归兴隔江云。何时共贳金陵酒，对景新题兴更分。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和韵送陆员外' AND p.poem_author = '王翰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山中', '方岳', '宋代', '寂寞空山久掩扉，残书谁与解重围。\n推豗时作橐驼坐，恍惚化为蝴蝶飞。\n春事已归双雪鬓，生涯尽在一荷衣。\n夜寒扣角悲声壮，但得牛肥道亦肥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山中' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又湖州作（四首。书寄班恕齐。试温生笔，写', '杨维桢', '元代', '三月三日雨新晴，相邀春伴冶西城。\n即倩山妻纱帽办，更烦小将犊车轻。\n好语啼春秦吉了，仙姿当酒董双成。\n凭君多唱嬉春曲，老子江南最有情。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又湖州作（四首。书寄班恕齐。试温生笔，写' AND p.poem_author = '杨维桢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅山', '姜特立', '宋代', '欲识梅山境，回环列万峰。\n朱门依绿水，粉堵出青松。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅山' AND p.poem_author = '姜特立';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·春院绣帘垂', '魏了翁', '宋代', '春院绣帘垂??，一天风月横陈。慈亲初度纪嘉名。每从歌舞地，犹记杰魁人。大句忽随乌鹊至，恍如前岁逢春。只祈岁岁及兹辰。天风吹宝唾，华彩动文星。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·春院绣帘垂' AND p.poem_author = '魏了翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('圣秋寄诗并双管', '释函可', '明代', '一缄珍重寄辽东，诗卷仍将双管同。旧砚已焚无所用，祇应新句伴寒风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '圣秋寄诗并双管' AND p.poem_author = '释函可';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('【双调】折桂令_想为官枉了', '张养浩', '元代', '想为官枉了贪图，正直清廉，自有亨衢。暗室亏心，纵想致富，天意何如？白图甚身心受苦，急回头暮景桑榆。婢妾妻孥，玉帛珍珠，都是过眼的风光，总是空虚。\n\n功名事一笔都勾，千里归来，两鬓惊秋。我自无能，谁言有道，勇退中流。柴门外春风五柳，竹篱边野水孤舟。绿蚁新篘，瓦钵磁瓯，直共青山，醉倒方休。功名百尺竿头，自古及今，有几个干休？一个悬首城门，一个和衣东市，一个抱恨湘流。一个十大功亲戚不留，一个万言策贬窜忠州。一个无罪监收，一个自抹咽喉。仔细寻思，都不如一叶扁舟。\n\n过金山寺\n\n长江浩浩西来，水面云山，山上楼台。山水相连，楼台相对，天与安排。诗句成风烟动色，酒杯倾天地忘怀。醉眼睁开，遥望蓬莱，一半儿云遮，一半儿烟霾。\n\n中秋\n\n一轮飞镜谁磨？照彻乾坤，印透山河。玉露冷冷，洗秋空银汉无波。比常夜清光更多，尽无碍桂影婆娑。老子高歌，为问嫦娥，良夜恹恹，不醉如何？\n\n凿池\n\n殷勤凿破苍苔，把湖泺风烟，中半分开。满意清香，尽都是千叶莲栽。看镜里红妆弄色，引沙头白鸟飞来。老子方才，陶写吟怀，忽见波光，摇动亭台。\n\n咏胡琴\n\n八音中最妙惟弦，塞上新声，字字清圆。锦树啼莺，朝阳鸣凤，空谷流泉。引玉杖轻笼慢捻，赛歌喉倾倒宾筵。常记当年，香案之前，一曲春生，四海名传。\n\n通州巡舟\n\n呼童解缆开船，见绿树青天，两岸回旋。欹枕篷窗，觉风波只在头边。桂棹举摇开翠烟，竹弹斜界破平川。老子狂颠，高咏诗篇，行过沙头，惊的些白鸟翩翩。\n\n白莲隐括〔木兰花慢〕\n\n幽花带露池塘，恨太华峰高，身世相妨。脉脉盈盈，何须解语，已断柔肠。羡公子风标异常，尽一生何限清香。华发沧浪，夜月壶觞，明日新声，付与秋娘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '【双调】折桂令_想为官枉了' AND p.poem_author = '张养浩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('君子有所思行', '胡直', '明代', '黄茂信嘉谷，焉用杂稂莠。稂莠何足言，蟊贼竟长亩。\n\n所以九苞羽，翱翔千仞霄。岂与鹳雀辈，争路鸣嘐嘐。\n\n我愿裁锦字，寄声于清飙。为我语神禽，无然困山椒。\n\n孤竹归西伯，尼父无停镳。轩皇本神圣，阿阁当来巢。\n\n但恐良媒隔，寂寂谁相招。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '君子有所思行' AND p.poem_author = '胡直';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('步虚词二十三章 其十五', '沈鍊', '明代', '将门应学道，仙法自通兵。宝剑神灵授，真符虎豹行。\n\n仁风随后殿，浩气是先声。义动三光合，机深五岳倾。\n\n本心期济世，谁羡列侯名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '步虚词二十三章 其十五' AND p.poem_author = '沈鍊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浮云', '罗隐', '唐代', '溶溶曳曳自舒张，不向苍梧即帝乡。 \n 莫道无心便无事，也曾愁杀楚襄王。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浮云' AND p.poem_author = '罗隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六弟有美才恐其荒于嬉也漫赋相勖', '毕自严', '明代', '彦士吾宗少，才名逊尔先。胜情酣一石，雄藻洒千篇。\n\n幽谷须腾翼，青云蚤著鞭。无为抱楚璞，沦落怨流年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六弟有美才恐其荒于嬉也漫赋相勖' AND p.poem_author = '毕自严';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东台赵中宪以手册三图委题分韵奉和四首 其二 雪溪图', '区元晋', '明代', '狐貉深藏雪意骄，小将渔艇系山腰。问渠东郭穿双履，诗思何如在坝桥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东台赵中宪以手册三图委题分韵奉和四首 其二 雪溪图' AND p.poem_author = '区元晋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔父子送齐明二化士 其一', '释子淳', '宋代', '凛凛严风彻骨寒，扁舟轻泛碧波澜。金线直，玉钩端，锦鳞无限，踊跃上琅玕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔父子送齐明二化士 其一' AND p.poem_author = '释子淳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游史馆张大卿致政李少卿史馆傅兵部济上郊园', '文彦博', '宋代', '畴昔常闻处士庄，林泉胜景甲山阳。一渠寒水流清济，千仞浓岚耸太行。\n\n枋口云归穿古木，燕川风过入脩篁。前贤旧业何人继，分与三贤作醉乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游史馆张大卿致政李少卿史馆傅兵部济上郊园' AND p.poem_author = '文彦博';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五微', '释函是', '明代', '堆压横桥山径微，寒林霁色一僧归。閒杀五陵贵公子，醉骑白马去如飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五微' AND p.poem_author = '释函是';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('初十夕', '屈大均', '明代', '开春初十夕，儿女八人齐。火树烧云乱，珠灯拂月低。\n\n渊明欢稚子，奉倩玩贤妻。共作藏彄戏，嬉娱到曙鸡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '初十夕' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '释仲休', '宋代', '护塔云偏重。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '释仲休';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登凌云山绝顶', '叶升', '宋代', '崔巍万仞俨危梯，蹑履多凭一杖藜。\n老宦跻崖冲斗动，高朋立顶惹同啼。\n振衣远望乾坤小，举首回看日月低。\n自是登天疑有路，云山缥缈夕阳西。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登凌云山绝顶' AND p.poem_author = '叶升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('园步杂兴', '张镃', '宋代', '池心谁话叶舟横，莲蘤还如入夏生。\n病起一天云意好，浅波閒让鹿先行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '园步杂兴' AND p.poem_author = '张镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感旧二首 其二', '蒋延鋐', '清代', '习静长翻《般若经》，每依月观与风亭。自从环佩无消息，檐马丁冬不忍听。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感旧二首 其二' AND p.poem_author = '蒋延鋐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('北锁巷', '沙曾达', '近代', '巷口曾将古井穿，中藏铁鍊涌深泉。署名北锁知非误，邑乘章章纪旧编。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '北锁巷' AND p.poem_author = '沙曾达';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湖上', '宋伯仁', '宋代', '一泓寒玉浸青山，妆点楼台夕照间。\n歌管满船春未懒，惜无人伴白鸥闲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湖上' AND p.poem_author = '宋伯仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('住石莲洞赠念庵先生四首 其一', '胡直', '明代', '石洞何寥廓，石莲朵更奇。窍从天地凿，花是鬼神为。\n\n山曲藏兰若，云深见肉芝。种田真避世，渔父尚无知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '住石莲洞赠念庵先生四首 其一' AND p.poem_author = '胡直';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('有怀 其四', '韩淲', '宋代', '山庵风雨夜，莫惜细论文。友直惟家学，僧清岂世氛。\n\n随宜粥饭好，奚止搢绅云。磬歇香灯上，词场自策勋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '有怀 其四' AND p.poem_author = '韩淲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三梦 其一', '卢青山', '当代', '古黛苍苍横，落月茫茫冱。系缆枯树根，独辟荒崖住。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三梦 其一' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('效阴铿安乐宫体十首 其一 甘泉宫', '胡应麟', '明代', '绀殿明丹壑，朱栏丽碧空。金芝丛紫翠，玉树翳青葱。\n\n阊阖千门度，罘罳万户通。鱼龙吟太液，鸡犬咽新丰。\n\n后乘双飞燕，蹁跹豹尾中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '效阴铿安乐宫体十首 其一 甘泉宫' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王仲房游金陵却归南原茶隐赠以四诗 其三', '欧大任', '明代', '燕赵齐梁一蒯缑，边关裘马五陵游。渴羌不解羔儿酒，只注茶经作隐侯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王仲房游金陵却归南原茶隐赠以四诗 其三' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日写怀 其二', '王渐逵', '明代', '溪横南北护清虚，花映前堤柳半疏。田父不知春思好，隔邻呼酒说菑畬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日写怀 其二' AND p.poem_author = '王渐逵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('分蝗食', '章甫', '宋代', '田园政尔无多子，连岁旱荒饥欲死。\n今年何幸风雨时，岂意蝗虫乃如此。\n麦秋飞从淮北过，遗子满野何其多。\n扑灭焚瘗能几何，羽翼已长如飞蛾。\n天公生尔为民害，尔如不食焉逃罪。\n老夫寒饿悲恼缠，分而食之天或怜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '分蝗食' AND p.poem_author = '章甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阮郎归', '汤传楹', '明代', '玉台晓镜试轻凉，薄施秋水妆。空庭对影怯昏黄，微风吹雾裳。\n\n佩洛浦，髻巫阳，凭阑问海棠。夜深多露倚谁旁，折来伴绮窗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阮郎归' AND p.poem_author = '汤传楹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送高记室广州幕', '宋祁', '宋代', '楚国王孙后，梁台赋客贤。\n贪磨盾鼻檄，重冠玳簪筵。\n去路南溟地，离魂北斗天。\n庾鲑三种嫩，虞璧一双鲜。\n飓影风争怒，珠胎月对圆。\n慎持斋疾意，密启伫详延。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送高记室广州幕' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出北流望勾漏洞 其二', '欧必元', '明代', '岩洞俱勾曲，仙家二二峰。有山俱罨画，无岫不芙蓉。\n\n渐与星辰近，将相鸾鹤从。无人同结侣，藜杖觅孤踪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出北流望勾漏洞 其二' AND p.poem_author = '欧必元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东风第一枝 情人节赋水仙用梅溪韵', '熊东遨', '当代', '雪借天山，波分洛水，南园初识风土。未将素眼窥人，莫放清霜入户。\n\n蜂媒蝶使，飞不到、画堂深处。听竹阴、一曲禽弦，撩动乱愁千缕。\n\n多少事、欲题无句；多少梦、欲寻无绪。闲常都说神仙，若个真成眷侣？\n\n西湖怜我，早许着、宜晴宜雨。问几时、得与荷邻，相伴钓舟归去？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东风第一枝 情人节赋水仙用梅溪韵' AND p.poem_author = '熊东遨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望湖亭', '薛蕙', '明代', '阴磴穿云上，天窗绮雾中。苍茫玉泉水，指点翠微东。\n\n坐石牵萝蔓，攀崖憩桂丛。何当避炎暑，几杖待秋风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望湖亭' AND p.poem_author = '薛蕙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杨极父挽诗', '魏了翁', '宋代', '高堂元佑脚，下泽少游乡。\n自得林泉趣，不登声利场。\n年方荣四豆，日已下三商。\n有子翁无咎，存心味更长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杨极父挽诗' AND p.poem_author = '魏了翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽曾秬光荐', '金幼孜', '明代', '力期科第继前人，岂料青云志莫伸。白日悲风来万里，故乡凶问及三春。\n\n青山雨冷封黄壤，旧馆灯残掩素尘。可柰双亲成永诀，空馀涕泪洒衣巾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽曾秬光荐' AND p.poem_author = '金幼孜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('马上望江南诸峰', '张翥', '元代', '浮云散尽暮天空，遥见江南数十峰。安得夸娥两神力，为分苍翠过淮东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '马上望江南诸峰' AND p.poem_author = '张翥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诉衷情·寒食', '仲殊', '宋代', '涌金门外小瀛洲。寒食更风流。红船满湖歌吹，花外有高楼。晴日暖，淡烟浮。恣嬉游。三千粉黛，十二阑干，一片云头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诉衷情·寒食' AND p.poem_author = '仲殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送颜评事入京', '岑参', '唐代', '颜子人叹屈，宦游今未迟。伫闻明主用，岂负青云姿。 \n 江柳秋吐叶，山花寒满枝。知君客愁处，月满巴川时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送颜评事入京' AND p.poem_author = '岑参';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭顾平甫前韵', '钱时', '宋代', '郊原几度踏春晴，此日空山草木春。泪尽两行悲不尽，眼前安得见斯人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭顾平甫前韵' AND p.poem_author = '钱时';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('唐夫人五解 其四', '陆深', '明代', '细草催寒食，孤坟对阖庐。年年城下路，双鬓已萧疏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '唐夫人五解 其四' AND p.poem_author = '陆深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('莪默绝句集译笺乙集 其五十五', '伯昏子', '当代', '难寄此身安乐乡，运交华盖又何妨。手擎真道引吾向，但请长斟此夜光。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '莪默绝句集译笺乙集 其五十五' AND p.poem_author = '伯昏子';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归与', '祝允明', '明代', '炎洲闭户赋归与，县尹何妨委巷居。夺禄浪言耕有代，旅行谁信出无车。\n\n空惭河上深藏贾，却笑关门强著书。莫道文章误公事，文章今误复何如。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归与' AND p.poem_author = '祝允明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九月十三日董君天狂招饮于天香楼，席散偕兆惇、兆恩二老同志浣纱村畅叙，归后得一律报之', '洪传经', '近代', '十年风雨冷深杯，各有虫鱼覆辙哀。寥落江湖存我辈，迷离云狗费人猜。\n\n填胸垒块宜浇酒，盖世文章岂论才。共上高楼忘主客，笑谈犹得尽欢回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九月十三日董君天狂招饮于天香楼，席散偕兆惇、兆恩二老同志浣纱村畅叙，归后得一律报之' AND p.poem_author = '洪传经';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('许家港夜泊', '朱逵吉', '清代', '模糊夜色辨柴关，泷急崎平又几湾。击鼓遥知村赛社，打钟近识寺藏山。\n\n惊飞宿鸟渔镫里，絮语寒蛩草露间。指点荒芦残月上，弋阳塔影见孱颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '许家港夜泊' AND p.poem_author = '朱逵吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送赖廷穆经卫之湖广', '林文俊', '明代', '落落才名迥出群，紫髯又见作参军。书生莫道不知武，记室从来要有文。\n\n别路共伤千里月，怀人知隔数重云。三湘春近多来雁，却要音书别后闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送赖廷穆经卫之湖广' AND p.poem_author = '林文俊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('镫勒', '孙承恩', '明代', '连山忽崖断，萧条见村墟。古驿但有名，篱落同民居。\n\n驿吏跪沙际，颜色惨不舒。自言为禄仕，寄迹豺虎区。\n\n乾坤有界限，天角与地暌。瘴厉日惨毒，鬼妖日睢盱。\n\n使事岂不荣，客怀日忧虞。经行我犹然，为尔增郁纡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '镫勒' AND p.poem_author = '孙承恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉酬吴洪二公三和之什 其一', '刘克庄', '宋代', '千层坠为一毫差，还了鱼须脱革华。数尺了无怀内锦，三斤空有话头麻。\n\n早曾谒帝吟薰殿，晚欲逃儒入墨家。自笑老人心尚骏，故吾不换换新花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉酬吴洪二公三和之什 其一' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登玉山诸峰，偶至悟真寺', '钱起', '唐代', '郭南云水佳，讼简野情发。紫芝每相引，黄绶不能绁。 \n 稍入石门幽，始知灵境绝。冥搜未寸晷，仙径俄九折。 \n 蟠木盖石梁，崩岩露云穴。数峰拔昆仑，秀色与空澈。 \n 玉气交晴虹，桂花留曙月。半岩采珉者，一点如片雪。 \n 真赏无前程，奇观宁暂辍。更闻东林磬，可听不可说。 \n 兴中寻觉化，寂尔诸象灭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登玉山诸峰，偶至悟真寺' AND p.poem_author = '钱起';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('烟雨馆晚对', '葛绍体', '宋代', '一片斜阳天北角，半痕初月水东湾。\n浮烟更拥云峰起，全似西湖远近山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '烟雨馆晚对' AND p.poem_author = '葛绍体';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('圣祖仁皇帝挽辞 其三', '顾成天', '清代', '銮舆六度接穷檐，日角天颜惕仰瞻。此日鼎湖龙已去，空教昂首望龙髯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '圣祖仁皇帝挽辞 其三' AND p.poem_author = '顾成天';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绍定庚寅纪事 其二', '萧澥', '宋代', '稻粱平地寇难防，到处搬为塞上粮。路险林深多脱谷，东风绿偃满山秧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绍定庚寅纪事 其二' AND p.poem_author = '萧澥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵王文甫先生二首', '陈著', '宋代', '富贵谁能讯女星，得师自分满平生。\n河汾他日书成后，王魏中閒亦有名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵王文甫先生二首' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风幡竞辨', '释重顯', '宋代', '不是幡兮不是风，衲僧于此作流通。\n渡河用筏寻常事，南山烧炭北山红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风幡竞辨' AND p.poem_author = '释重顯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('放言四首', '何良俊', '明代', '已拚千日千场，宁辞一饮一石。\n天子放我还家，主人留臣送客。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '放言四首' AND p.poem_author = '何良俊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠吕肖卿三首 其三', '方回', '宋代', '知己身俱老，逢君泪欲倾。不时思令舅，无可报难兄。\n\n湓浦稀鱼素，阳山杳雁程。平安只消息，聊此慰羁情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠吕肖卿三首 其三' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上巳寄南康太守廖昆湖', '释函是', '明代', '泬寥春色近何如，花落寒梢影自疏。藉草远过江浦岸，烧畬还课北山锄。\n\n波光几岁摇高岭，云气从朝覆敝庐。此日独怀彭蠡守，袖中存有故人书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上巳寄南康太守廖昆湖' AND p.poem_author = '释函是';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秣陵怀古', '陈维崧', '清代', '红板桥头，锦衣仓北，金陵从古皇州。\n记离宫墙外，年少曾游。\n忽听九重仙乐，东风细细度龙楼。\n依稀认，宁王玉笛，贺老箜篌。\n悠悠，南朝风景，看几遍桃红，白了人头。\n算刘郎易老，嬴女难留。\n三十六宫何在？斜阳外、隐隐离愁。\n伤心极，后湖菱蔓，一片渔舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秣陵怀古' AND p.poem_author = '陈维崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送南中尉', '吏部选人', '唐代', '羡君初拜职，嗟我独无名。且是正员尉，全胜兼试卿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送南中尉' AND p.poem_author = '吏部选人';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('昭君怨', '吴龙翰', '宋代', '汉家金屋贮蛾眉，六宫何啻三千姬。\n中有一姬倾国色，可怜不到君王知。\n毛生笔下真少恩，玉颜黑子迷妍媸。\n君王按图不入眼，出身远嫁单于妻。\n盈盈泪眼边月照，萧萧愁鬓胡风吹。\n不忧死作龙城鬼，贞魂长在深宫里。\n犹胜男儿未贵时，咫尺金门如万里。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '昭君怨' AND p.poem_author = '吴龙翰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重游虎邱寺', '成廷圭', '元代', '海涌峰头行径微，芒屦欲趁孤云飞。风高木客作人语，月出天王骑虎归。\n\n杰阁重楼递隐见，寒泉古木相因依。荒邱王气岂消歇，干将莫耶千载稀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重游虎邱寺' AND p.poem_author = '成廷圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('借虚谷太博狂吟十诗韵书怀并呈太博 其二', '杨公远', '宋代', '竹马才抛又是翁，年来自觉转疏慵。欲开竹下三三径，还借毫端六六峰。\n\n处世竟无非理事，对人那有可惭容。浮沈聊尔从吾好，却笑南阳说卧龙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '借虚谷太博狂吟十诗韵书怀并呈太博 其二' AND p.poem_author = '杨公远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早朝诗（十四首）', '杨子器', '明代', '禁门开始入，城观迥难攀。\n仗马矜骖乘，宫鸦学卷班。\n曙云藏北斗，晴雪见西山。\n肃穆垆烟外，珊珊响佩环。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早朝诗（十四首）' AND p.poem_author = '杨子器';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冲雨投宿石佛院次季承留题韵二首 其一', '赵蕃', '宋代', '尘埃彷佛前朝寺，客子今缘避雨来。欲访当时漫亡得，绿丛蕉并野花开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冲雨投宿石佛院次季承留题韵二首 其一' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('建溪舟行', '黄裳', '宋代', '两岸青山倒影浓，一江秋色两山中。扁舟不怯溯流水，天意借人帆上风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '建溪舟行' AND p.poem_author = '黄裳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李小湖先生视学期满，乞假省墓，诗以送之二首 其一', '夏炜如', '清代', '药笼参苓已尽收，尚虞葑菲弃遐陬。劲风谡谡汉元礼，仙骨珊珊唐邺侯。\n\n气节文章千古业，家门邦国万端忧。星轺六载巡江海，卧辙何因得暂留。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李小湖先生视学期满，乞假省墓，诗以送之二首 其一' AND p.poem_author = '夏炜如';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古意 其三', '邹汉勋', '清代', '心绪如乱丝，纠结不可解。一日空复过，谁能念千载。\n\n便守瓶瓴声，穷村恣击揩。顾念咸䪧备，宁复无人采。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古意 其三' AND p.poem_author = '邹汉勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('太上閤端午帖子 其三', '许及之', '宋代', '柈献千年实，杯行九节蒲。至尊亲上寿，家庆列成图。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '太上閤端午帖子 其三' AND p.poem_author = '许及之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵斯远见寄', '赵蕃', '宋代', '春今半历未知春，可奈昏昏昼复晨。药裹岂能知许病，诗囊亦觉顿成贫。\n\n羲和送日何其怯，天女司花不解神。何但子行无所诣，我怀端亦在湖漘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵斯远见寄' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五月六日约诸友游北山舟已具而予偶不能出诸', '高斯得', '宋代', '区中无由舒眼界，欲上云峰观九派。\n颇闻黄龙擅奇特，傥得窥临真一快。\n清苕一线仅委蛇，具区万顷何滂湃。\n又闻法华两招提，清旷夐绝人境隘。\n池光潋滟镜无台，山色清寒身不壤。\n石林幻出三玲珑，万虎千罴断雄怪。\n幽贞叶策天相之，梅雨初晴白日晒。\n州家幸肯借官船，亟馔鱼虾菹韭薤。\n奈何欲往竟不谐，徒羡诸公脱天械。\n归来争发古锦囊，令予伎疗如爬疥。\n嵇康本自不羁人，况复时屯方翮铩。\n终当於此结菁茅，庶可偿渠猿鹤债。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五月六日约诸友游北山舟已具而予偶不能出诸' AND p.poem_author = '高斯得';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游升真道院', '郭奎', '明代', '兵火经馀岁，琳宫结搆新。山重溪接屋，松古鹤为邻。\n\n试药封丹鼎，飞书报玉宸。浮云身外事，惟有学升真。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游升真道院' AND p.poem_author = '郭奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('友人寄白话诗见怀试袭其意约为一律', '吴金水', '当代', '晨曦微现晓星残，半卷湘帘独倚栏。往事暗凝花上露，韶华空叹镜中鸾。\n\n几回蝶梦云山隔，一夜瑶筝玉指寒。遥望南天天尽处，昨宵月色可同看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '友人寄白话诗见怀试袭其意约为一律' AND p.poem_author = '吴金水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人 其一 题二十四番花信风笺纸', '樊增祥', '清代', '东风次第来无尽。盼煞红桥信。崔娘梦里自呼名。越是有头无尾越分明。\n\n阑干十二花枝午。数了还重数。海棠睡后说魂消。安得年年二月闰花朝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人 其一 题二十四番花信风笺纸' AND p.poem_author = '樊增祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('砑蠡', '陆游', '宋代', '古者贝为货，庶物赖以通；後世贵铜臭，退处书几中。\n楮生借光辉，文字传亡穷。\n言利古所羞，孰谓汝不逢？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '砑蠡' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪楼程御史次方山房韵见寄用韵答赋三首 其二', '何梦桂', '宋代', '青楼有蛾眉，翳袖渺独处。日暮赋摽梅，愧我求彼士。\n\n谁家操孤鸾，感此中夜起。明河落天西，玉绳低欲轾。\n\n结言藉媒劳，恩重报无地。明珠在罗襦，谁能谅心事。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪楼程御史次方山房韵见寄用韵答赋三首 其二' AND p.poem_author = '何梦桂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹子滩逢广漕张公诩二首 其二', '郭祥正', '宋代', '会合嗟无酒，留连漫索茶。晚云随落日，归雁集寒沙。\n\n自达聊安命，多言任指瑕。吾宗有令弟，恩复出君家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹子滩逢广漕张公诩二首 其二' AND p.poem_author = '郭祥正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上京杂诗十首 其八', '周伯琦', '元代', '水草饶刍牧，生涯富远氓。旃帘连雪屋，马酒溢琼罂。\n\n烂醉无怀氏，狂歌太古声。后车倾国色，艳服更珠缨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上京杂诗十首 其八' AND p.poem_author = '周伯琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔父家风', '张元干', '宋代', '八年不见荔枝红。肠断故园东。风枝露叶新采，怅望冷香浓。 \n 冰透骨，玉开容。想筠笼。今宵归去，满颊天浆，更御冷风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔父家风' AND p.poem_author = '张元干';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄金台', '刘因', '元代', '燕山不改色，易水无新声。谁知数尺台，中有万古情。\n\n区区后世人，犹爱黄金名。黄金亦何物？能为贤重轻。\n\n德辉照九仞，凤鸟才一鸣。伊谁腐鼠弃，坐见饥鸢争。\n\n周道日东渐，二老皆西行。养民以致贤，王业自此成。\n\n黄金与山平，不救兵纵横。落日下荒台，山水有馀清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄金台' AND p.poem_author = '刘因';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三高祠三首 其一 范蠡', '高启', '明代', '功成不恋上将军，一舸归游笠泽云。载去西施岂无意，恐留倾国更迷君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三高祠三首 其一 范蠡' AND p.poem_author = '高启';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送新酒糟蟹与贾之奇五首 其二', '曹勋', '宋代', '陋巷何能有玉醅，闲人正以鄙惟罍。捣香筛辣宜相送，似胜骑鲸月下杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送新酒糟蟹与贾之奇五首 其二' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又赠谓之 其一', '司马光', '宋代', '文藻兼名理，三吴第一贤。乡心几千里，飞雁满秋天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又赠谓之 其一' AND p.poem_author = '司马光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄山二首 其二', '郭祥正', '宋代', '秋晚陟浮丘，西临古渡头。钟声沉断岸，桥影散中流。\n\n雪让芦花密，云排稻穗稠。乾坤均帝力，草木岂能酬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄山二首 其二' AND p.poem_author = '郭祥正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寒泉濯足', '石宝', '明代', '翩翩黄发翁，濯足岩下水。吾志在清波，世事如脱屣。\n\n青山长悠悠，白石亦齿齿。千古孺子歌，谁能契斯理。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寒泉濯足' AND p.poem_author = '石宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古三首 其三', '释宝印', '宋代', '学佛人人被佛瞒，拨尘见得几何般。狂风卷地云吹散，独立栏干宇宙宽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古三首 其三' AND p.poem_author = '释宝印';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题赵千里夜潮图', '周假庵', '宋代', '烟苍苍，江茫茫，\n明月夜挂天中央。奔潮不尽当日恨，\n金波怒，卷虯龙。\n长浦口，秋飞扬，\n鸥雁不眠声周间。风高沙涨望难到，\n羽翰但逐潮低昂。窗间帘炷香，\n开卷有素商。何须八月上钱唐，\n对此秋涛生锦囊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题赵千里夜潮图' AND p.poem_author = '周假庵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大小沙陀 其二', '彭汝砺', '宋代', '大小沙陀深没膝，车不留踪马无迹。曲折多途胡亦惑，自上高冈认南北。\n\n大风吹沙成瓦砾，头面疮痍手皴坼，下带长烟蔽深驿。\n\n层冰峨峨霜雪白，狼顾鸟行愁覆溺。一日不能行一驿，吾闻治生莫如啬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大小沙陀 其二' AND p.poem_author = '彭汝砺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九月三十日登石景山最高处', '黄浚', '近代', '青山如幄裹河声，𥥆窕秋原十里明。欲掷积哀人境外，当头落日尚峥嵘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九月三十日登石景山最高处' AND p.poem_author = '黄浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三月四日玩园花小集', '宋祁', '宋代', '中园爱客重游陪，三月林花落复开。镂管喜传吟处笔，白波催卷醉时杯。\n\n欢襟已快邀风度，舞地犹宽放雪回。不是年芳相假借，使君兼乏斐然才。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三月四日玩园花小集' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和江进之寒山寺之作 其一', '袁宏道', '明代', '山寺依人境，乘闲且杖藜。好花营地种，熟鸟认枝栖。\n\n洗钵防茶老，开轩碍竹低。西来空有义，记取鹁鸠蹄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和江进之寒山寺之作 其一' AND p.poem_author = '袁宏道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('启霞冰壶亭', '楼钥', '宋代', '拍拍新漪彻底清，两山写照翠光凝。笑看风动縠纹起，坐我玉壶春夜冰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '启霞冰壶亭' AND p.poem_author = '楼钥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('太行山', '沈用济', '清代', '山作潼关险，艰哉势独雄。千盘拔河内，一折走辽东。\n\n大壑云雷伏，阴崖日月通。巍巍天下脊，元气结鸿濛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '太行山' AND p.poem_author = '沈用济';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('刘觐国馈菜酬以酒', '邓云霄', '明代', '应念庾郎贫，贻来菜甲新。偏怜摘鲜趣，欲作灌园人。\n\n添我伊蒲馔，酬君曲米春。西风万里客，此夕不思莼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '刘觐国馈菜酬以酒' AND p.poem_author = '邓云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清波引 勿幕亭、酌泉亭在连州巾山麓', '朱祖谋', '清代', '小澜不整。是当日、流杯佳境。翠茵偎冷。野风荡愁醒。\n\n玉濑散空响，定有餐霞人听。自怜才净闻根，又飘落、午时磬。\n\n孤游惯领。倚危岫、云意未定。地炉供茗，对烟绪摇暝。\n\n清泠在山性，肯负辘轳修绠。坐恐一片奁冰，鉴人尘影。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清波引 勿幕亭、酌泉亭在连州巾山麓' AND p.poem_author = '朱祖谋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游黄梁祠即景杂咏 其四', '申佳允', '明代', '行行古道问仙踪，驴背驮来睡眼矇。莫道仙缘非易结，仙乡今在睡乡中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游黄梁祠即景杂咏 其四' AND p.poem_author = '申佳允';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('罗浮何君佑夫相访惠诗又出所作水墨鱼戏题卷', '李昴英', '宋代', '山头钓引千钧鱼，铁桥曾逢稚川奴。\n风波平地误点额，戏取墨汗翻模糊。\n纵观濠上契妙趣，浩浩胸次涵江湖。\n墨云忽从砚池起，拨剌跳出形模殊。\n大鱼腾骧撼风雨，小鱼琐碎游荇蒲。\n技如元放几许奇，金盘一个松江鲈。\n试张亭前涨波影，舂锄飞下傍睢盱。\n世间画史少活笔，描写终类鲋肆枯。\n文溪一湾浮钓徒，欠得龙眠为严濑羊裘图。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '罗浮何君佑夫相访惠诗又出所作水墨鱼戏题卷' AND p.poem_author = '李昴英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上元三绝 其二', '张耒', '宋代', '沽酒垆边人若市，算商亭下浪连天。张君官况今如此，岂有工夫作醉眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上元三绝 其二' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('越日雨中饮复醉叠前韵示诸君 其二', '姚燮', '清代', '蓬莱万仞高，境先混沌凿。皎月如龙珠，横箫且骑鹤。\n\n沃焦有大渊，尧时已为壑。昆崙与扶桑，相对永漠漠。\n\n皇极持寸心，毋今丧我橐。当使风骨存，峻于两厓削。\n\n空宇无滞云，枯林不留萚。一握东海杯，飞来掌中落。\n\n仙叟赌玉尘，但解橘隐乐。焉知天外弧，夜影警神鹗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '越日雨中饮复醉叠前韵示诸君 其二' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行香子 时三鼓矣，欹枕不寐，感旧成章，凄绝之音，几难卒读', '高旭', '清代', '春在谁边。人在谁边。更东风、吹向谁边。迢迢山海，觅遍涯巅。\n\n是奈何花，奈何酒，奈何天。比翼难连。镜影难圆。柳丝丝、枉自缠绵。\n\n向楼头怅望，一缕情牵。奈月如魂，魂如梦，梦如烟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行香子 时三鼓矣，欹枕不寐，感旧成章，凄绝之音，几难卒读' AND p.poem_author = '高旭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('松寺', '卢延让', '唐代', '山寺取凉当夏夜，共僧蹲坐石阶前。两三条电欲为雨， \n 七八个星犹在天。衣汗稍停床上扇，茶香时拨涧中泉。 \n 通宵听论莲华义，不藉松窗一觉眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '松寺' AND p.poem_author = '卢延让';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与子真诸人饮求仁不与作怨诗因戏答', '晁补之', '宋代', '结习徐看荡劫灰，天花从自落空阶。\n似闻满室唯澄水，投砾何因出定来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与子真诸人饮求仁不与作怨诗因戏答' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠萧世英', '解缙', '明代', '十九年中别更逢，逢君又别意重重。煎茶扫地同明月，相对弹琴到晓钟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠萧世英' AND p.poem_author = '解缙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄送方山人归歙州 其一', '李攀龙', '明代', '河水悠悠雁影长，长安回首泪成行。可怜三十年前客，明日扁舟是故乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄送方山人归歙州 其一' AND p.poem_author = '李攀龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('芙蓉道间二首 其二', '赵蕃', '宋代', '芙蓉山下芙蓉渡，历尽崔嵬何物路。更观溪水突人来，令我诗情杂欣惧。\n\n舆夫重说松原山，如此积雨应生湍。从来潢潦无根源，水收石露须臾间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '芙蓉道间二首 其二' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泰和八景 其六 田东暮雨', '胡奎', '明代', '戴笠出东郊，白云如海涛。前村风雨急，溪水晚来高。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泰和八景 其六 田东暮雨' AND p.poem_author = '胡奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题画', '胡俨', '明代', '米老画图真绝俗，后来房山继其躅。意匠经营入渺茫，一见令人豁心目。\n\n秖今此图作者谁，笔意髣髴房山为。层峦日出翠将敛，深谷雨过云生迟。\n\n流泉涓涓落浅滩，茆堂六月清风寒。绿阴满户不收暑，上有好鸟鸣闲关。\n\n读书长年不知老，白首为儒空潦倒。下帷独坐懒窥园，落花只遣苍头扫。\n\n瓮中酒熟今朝开，故人有约应须来，无令行径生青苔。\n\n有酒可斟书可读，于人不求贫亦足。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题画' AND p.poem_author = '胡俨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谒禹庙', '宋之问', '唐代', '夏王乘四载，兹地发金符。峻命终不易，报功畴敢渝。 \n 先驱总昌会，后至伏灵诛。玉帛空天下，衣冠照海隅。 \n 旋闻厌黄屋，更道出苍梧。林表祠转茂，山阿井讵枯。 \n 舟迁龙负壑，田变鸟芸芜。旧物森如在，天威肃未殊。 \n 玄夷届瑶席，玉女侍清都。奕奕扃闱邃，轩轩仗卫趋。 \n 气青连曙海，云白洗春湖。猿啸有时答，禽言常自呼。 \n 灵歆异蒸糈，至乐匪笙竽。茅殿今文袭，梅梁古制无。 \n 运遥日崇丽，业盛答昭苏。伊昔力云尽，而今功尚敷。 \n 揆材非美箭，精享愧生刍。郡职昧为理，邦空宁自诬。 \n 下车霰已积，摄事露行濡。人隐冀多祐，曷唯沾薄躯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谒禹庙' AND p.poem_author = '宋之问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('述怀三首 其一', '费墨娟', '清代', '俗虑多多累我忙，诗书文字已全荒。羞随邻女夸娇艳，懒向旁人说短长。\n\n历遍尘途知险阻，尝深世味感炎凉。闲愁满抱凭谁遣，听雨看花倚石床。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '述怀三首 其一' AND p.poem_author = '费墨娟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('云庵觅诗', '陈藻', '宋代', '百级危阶上翠峦，四边山色自低环。\n海乡无限萧条景，收到楼前是美观。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '云庵觅诗' AND p.poem_author = '陈藻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其一', '杨备', '宋代', '云窦穿银井，冰甃贮玉浆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其一' AND p.poem_author = '杨备';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水墨海棠', '真山民', '宋代', '不将翠袖捲纱红，怪得陈玄夺化工。想是太真春睡足，梦魂正在黑甜中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水墨海棠' AND p.poem_author = '真山民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('神宗皇帝挽辞 其五', '黄裳', '宋代', '忽自明庭去，风高帝所寒。有期修玉检，无处觅仙丹。\n\n与子基图远，开天数度宽。锦标何以报，空展赐诗看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '神宗皇帝挽辞 其五' AND p.poem_author = '黄裳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨后观涨', '冯伯规', '宋代', '闻得江头汹涌声，不知何处雨盆倾。\n两涯牛马那容辨，一夕蛟龙怒不平。\n涩尽横汀孤树在，微琥顽翳夕阳明。\n尽饶河伯乘秋旺，潦涸霜寒水自清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨后观涨' AND p.poem_author = '冯伯规';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长相思', '朱敦儒', '宋代', '海云黄。橘洲霜。如箭滩流石似羊。溪船十丈长。 \n 人难量。水难量。过险方知著甚忙。归休老醉乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长相思' AND p.poem_author = '朱敦儒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游滁山二十咏 其六 酿泉', '郭之奇', '明代', '潺潺泻出两峰间，刮尽云根破石悭。香冽寻尝归众口，清辉独洗醉翁颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游滁山二十咏 其六 酿泉' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('廛中佛事', '释惟一', '宋代', '几回几巷复穿衢，货卖南方镇海珠。\n一栲栳都倾出了，不知酬价有人无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '廛中佛事' AND p.poem_author = '释惟一';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('翠蛟峰', '胡矩', '宋代', '像耸奇形曰翠蛟，不须牙爪谩徒劳。须臾变化非难事，况有飞泉作怒涛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '翠蛟峰' AND p.poem_author = '胡矩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉笥山中有白鹤花顶翅宛然类鹤王兰友作诗送至用韵二首 其二', '刘诜', '元代', '千载苏仙上帝乡，空馀琪草似人长。夜凉环佩不知处，梦觉满山风露香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉笥山中有白鹤花顶翅宛然类鹤王兰友作诗送至用韵二首 其二' AND p.poem_author = '刘诜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西湖曲 其三', '何绛', '明代', '千株杨柳数家村，茅屋檐前鹊噪喧。竟日了无他客至，荷花空自绕柴门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西湖曲 其三' AND p.poem_author = '何绛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('遍题朱惟四增置诸胜十二首 其一 仙源', '邓云霄', '明代', '高循石磴踏罡风，寻得仙源杳霭中。怪底寒光浸星月，涟漪疑与绛河通。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '遍题朱惟四增置诸胜十二首 其一 仙源' AND p.poem_author = '邓云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('关南上桥寺候黄观察善卿殡不至漫占催装诗奉', '汤显祖', '明代', '薤露将晞早食前，如何报说五更天。\n因风寄与鸡鸣枕，则为长眠废短眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '关南上桥寺候黄观察善卿殡不至漫占催装诗奉' AND p.poem_author = '汤显祖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郊庙歌辞。五郊乐章。雍和', '佚名', '唐代', '律应西成，气躔南吕。珪币咸列，笙竽备举。 \n 苾苾兰羞，芬芬桂醑。式资宴贶，用调霜序。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郊庙歌辞。五郊乐章。雍和' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚步归而有作', '佟绍弼', '近代', '闲行能及灭灯前，聊胜端居坐榻穿。习乱群情耽醉饱，污人残市带腥膻。\n\n忧来不遣新风雅，物有难齐见后先。独伴晚怀惟月在，晴窗一片白茫然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚步归而有作' AND p.poem_author = '佟绍弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五月五日诗', '崔巨伦', '南北朝', '五月五日时，天气已大热。狗便呀欲死，牛复吐出舌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五月五日诗' AND p.poem_author = '崔巨伦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八月十六日与客同游西湖', '郭谏臣', '明代', '芒鞋同上泛湖船，万顷波光一镜圆。日映诸峰浮水面，云扶高塔倚山巅。\n\n幽花曲渚横秋色，疏柳长堤起暮烟。准拟今宵明月夜，与君潦倒不须眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八月十六日与客同游西湖' AND p.poem_author = '郭谏臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('日本杂事诗 其九十一', '黄遵宪', '清代', '绛蜡高烧照别离，乌衣换毕出门时。小时怜母今怜婿，宛转双头绾色丝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '日本杂事诗 其九十一' AND p.poem_author = '黄遵宪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('精膳郎中侯纶母张宜人寿七十', '顾清', '明代', '五丝蹙云双帔长，珠冠翠蕤明两珰。早年身侍两姑傍，良人执戟戍边方。\n\n齐眉举按上高堂，夜灯课子青藜光。良人已矣诸孤昌，大者名在六郡良。\n\n小者南省尚书郎，诸孙阶下俨成行。瑶环瑜珥间珩璜，花前迭进奉霞觞。\n\n花枝拂帘风日香，人间总谓天茫茫。有如人斯天岂忘，新年七十鬓微霜。\n\n药饵不御身康强，门前晋水春洋洋。谓君酿取酒千缸，君家此乐殊未央。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '精膳郎中侯纶母张宜人寿七十' AND p.poem_author = '顾清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('后圃侍郎芍药酴醾三花竞发戴时可载酒来同酌醉中', '陈著', '宋代', '前日对花赋三诗，醉后谁复记当时。雪溪公子忽呈似，一见如梦中见之。\n\n世閒何事非虚妄，啸里著句岂狂痴。富公园有凌霄树，独立不蔓今古希。\n\n碧鸡坊头海棠花，花开如屋树丈围。洛与蜀，今已非，虽欲胜赏将何归。\n\n我家贫极花未厌，我亦未敢轻抛离。茶一盏，酒数卮，邀朋命友长娱嬉。\n\n今日何日晴且暖，三花相得心自知。旁观索赋不须讶，要问底蕴自有造物儿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '后圃侍郎芍药酴醾三花竞发戴时可载酒来同酌醉中' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题画册十七首 其九', '戴亨', '清代', '群峰云上立，乱石风前走。荡胸岚气生，看山背两手。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题画册十七首 其九' AND p.poem_author = '戴亨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和嘉本初夜泊枫桥韵', '沈周', '明代', '风流张继忆当年，一夜留题百世传。桥带人家斜倚寺，月笼沙水淡生烟。\n\n火知渔子仍村外，舟载诗僧又客边。我愧不能同此宿，却因新韵偶联篇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和嘉本初夜泊枫桥韵' AND p.poem_author = '沈周';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('生日示闻诗闻礼', '王十朋', '宋代', '哀哀父母生我劳，生日不见徒悲号。今年偶然梦三刀，二千石向鄱阳叨。\n\n身虽五马已二毛，烹羊击鲜斫蟹螯。殷勤为寿劳尔曹，愿尔它年著綵袍。\n\n二亲无恙年俱高，更与诸孙持寿醪。满堂宾客来英豪，会看醉脸如仙桃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '生日示闻诗闻礼' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十月朔日蒙御史台颁至洪武九年历日十六喜而有赋', '刘崧', '明代', '洪武九年春，仪台宝历新。远从乌府送，如见凤图陈。\n\n万国同正朔，千官仰北辰。彤廷先进早，犹忆侍班晨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十月朔日蒙御史台颁至洪武九年历日十六喜而有赋' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题信果观壁', '李建勋', '唐代', '春来涨水流而活，晓色西山势似行。 \n 玉洞主人经劫在，携竿步步就长生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题信果观壁' AND p.poem_author = '李建勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春·幼椿先生写示卅七年前养病青岛劳山新诗一首，嘱谱入乐府', '王韶生', '近代', '门外青松，枕畔涛声，客梦夕酣。看新阳杲杲，齐烟点点，朝来观海，日落还山。\n\n幽涧风生，寒波叶下，吹律谁温溪谷寒。晴阴改，叹丹崖灶冷，白袷衣单。\n\n閒眠。废了芸编。抬眼望亲交各一天。对林深暝色，云封片石，穷探造化，悬想推迁。\n\n物候非秋，英灵笑我，忘却烦忧且尽年。狂澜起，不平为平也，怒吼当前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春·幼椿先生写示卅七年前养病青岛劳山新诗一首，嘱谱入乐府' AND p.poem_author = '王韶生';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丁亥秋事六章 其一 秋雨', '添雪斋', '当代', '谁将秋夜雨，淅沥遍倾之。悬影千灯窅，窥吾一芥悲。\n\n依稀人已远，愔翳梦而知。忆此幂天下，惊雷共那时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丁亥秋事六章 其一 秋雨' AND p.poem_author = '添雪斋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟中重阳次至德韵', '陈繗', '明代', '舟泊渡头别路长，况逢重九寓他乡。一江波影依谁碧，两岸菊花为我黄。\n\n凉露沾衣唫里句，轻风落帽醉边觞。客中也得清平乐，万岁惟应祝圣王。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟中重阳次至德韵' AND p.poem_author = '陈繗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('有访', '储雄文', '清代', '未遇幽人又独还，贪看落日立溪湾。隔溪几处炊烟动，遮断寒林数叠山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '有访' AND p.poem_author = '储雄文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宋履中学士挽词二首', '孔武仲', '宋代', '朝论方知子，哀哉疾不瘳。\n歌闻湘浦些，魂返岱宗游。\n文雅承三世，渊源见九流。\n音容如可接，图像在瀛洲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宋履中学士挽词二首' AND p.poem_author = '孔武仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('太庙乐章·皇帝阁六首', '周麟之', '宋代', '凤盖龙车玉作轮，兹临紫畦谒三神。\n已将福酒添眉寿，更祝椒觞一万春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '太庙乐章·皇帝阁六首' AND p.poem_author = '周麟之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自问', '白居易', '唐代', '依仁台废悲风晚，履信池荒宿草春。 \n 自问老身骑马出，洛阳城里觅何人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自问' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七月二十夜临湘不寐观星作', '卢青山', '当代', '馀热怏怏气未平，夏虫聒唱已消沉。窗外默梧如我立，心中哗语与谁倾？\n\n灿灿明星光远大，悠悠尘世事阴昏。安得骑萤化汝去，灏流终古寄蒙冥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七月二十夜临湘不寐观星作' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('楚甸江头望雪晴二首 其二', '冯时行', '宋代', '晴天开泽国，江渚匝烟围。鹭静萧萧立，梅孤默默飞。\n\n岸荒群虎过，村迥一人归。愁绪如相恼，帆收径典衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '楚甸江头望雪晴二首 其二' AND p.poem_author = '冯时行';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('聚星堂前紫薇花', '欧阳修', '宋代', '亭亭紫薇花，向我如有意。\n高烟晚溟蒙，清露晨点缀。\n岂无阳春月，所得时节异。\n静女不争宠，幽姿如自喜。\n将期谁顾眄，独伴我憔悴。\n而我不强饮，繁英行亦坠。\n相看两寂寞，孤咏聊自慰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '聚星堂前紫薇花' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鄂王墓', '陈允平', '宋代', '鄂王墓在栖霞岭，一片忠魂万古存。\n镜里赤心悬日月，剑边英气塞乾坤。\n苍苔雨暗龙蛇壁，老树烟凝虎豹旛。\n独倚东风挥客泪，大堪回首望中原。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鄂王墓' AND p.poem_author = '陈允平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十二时 其五', '释咸静', '宋代', '食时辰，掌钵徒劳入市巡。若将心受檀那饭，也似无功食禄人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十二时 其五' AND p.poem_author = '释咸静';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日过龙兴观墨池', '李翔', '唐代', '独登仙馆欲从谁，闻有王君旧墨池。苔藓已侵行履迹，洼坳犹是古来规。\n\n竹梢声认挥毫日，殿角阴疑洗砚时。叹倚坛边红叶树，霜钟欲尽下山迟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日过龙兴观墨池' AND p.poem_author = '李翔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨中花 题秋海棠遗画', '孔宪英', '清代', '腕底酸红冷翠，写出秋容如醉。恨煞西风情太恶，吹作冰天泪。\n\n忍把画图当晤对。看小样、红妆憔悴。耳根内似闻蛩语，哽咽更教人心碎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨中花 题秋海棠遗画' AND p.poem_author = '孔宪英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送吴太守之韶阳 其二', '刘崧', '明代', '白下东门柳，当年手种成。行行当别路，叶叶是离情。\n\n解缆惊秋雨，扬镳送晚晴。春风榕馆静，好在听啼莺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送吴太守之韶阳 其二' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('万岁山', '潘伯脩', '元代', '龙首冈前玉树林，丹青万点紫烟深。广寒台殿秋如水，太液波涛晚向阴。\n\n西北云山凉冉冉，东南星海气湛湛。麟帘不卷空良夜，水鹤翛翛警露心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '万岁山' AND p.poem_author = '潘伯脩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('关山月', '宋构', '宋代', '关山月，关山月，千里寒光射冰雪。\n一声羌管裂青云，陇上行人肠断绝。\n肠断绝兮将奈何，为君把酒问常娥。\n冰轮桂魄圆时少，应似人间离别多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '关山月' AND p.poem_author = '宋构';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('平声四韵 其十四', '许国佐', '明代', '深夜相怜忆，寥寥岭外寒。司空刁笔疏，我友惠文冠。\n\n臂指偏能大，犬羊犹尚残。深惭蒲柳质，往亦过惊湍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '平声四韵 其十四' AND p.poem_author = '许国佐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大司马吴公惠田赋此奉答 其二', '屈大均', '明代', '繇来仁者粟，方与养亲宜。更受山田赐，弥惭石父知。\n\n自今为黍早，不惜采兰迟。勤动同妻子，长怀粒我私。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大司马吴公惠田赋此奉答 其二' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵红白莲间生', '周必大', '宋代', '閒花不遣倚门墙，独挹芙蕖冉冉香。艳质施朱窥宋玉，冰姿傅粉试何郎。\n\n青茎翠盖元相映，缟袂霞裾各自芳。闻道金銮行豹直，炬莲先已兆嘉祥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵红白莲间生' AND p.poem_author = '周必大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿青城板桥寺', '李新', '宋代', '村落萧萧烟雨收，鹑衣寒竖挽归牛。\n平生脚力未到处，当路贵人安肯游。\n蹶牛马蹄无限恐，荒凉僧墅不胜愁。\n北窗季弟还知否，一夜秋声已白头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿青城板桥寺' AND p.poem_author = '李新';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜凉亭', '吴机', '宋代', '小亭新筑藕花边，为爱陂塘五月天。\n最好一番风雨过，琼珠无数落清泉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜凉亭' AND p.poem_author = '吴机';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('经海子', '常伦', '明代', '积水明人眼，蒹葭十里秋。\n西风摇雉榘，晴日丽妆楼。\n柳径斜通马，荷丛暗度舟。\n东邻如可问，早晚卜清幽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '经海子' AND p.poem_author = '常伦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早行', '胡仲弓', '宋代', '曙色微分星渐稀，迎人犬吠出疎篱。\n轻车稳坐谁知我，不是坡翁戴笠时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早行' AND p.poem_author = '胡仲弓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉台体', '利登', '宋代', '浓绿千竿湑欲流，春风疑只在池头。\n相思一夕天相似，望断西南四百州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉台体' AND p.poem_author = '利登';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋怀八首 其四', '李梦阳', '明代', '苑西辽后洗妆楼，槛外芳湖静不流。乱世君臣那在眼，异时松柏自深愁。\n\n雕阑玉桂留天女，锦石秋花隐御舟。万古中华还此地，我皇亲为扫神州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋怀八首 其四' AND p.poem_author = '李梦阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无题五首 其一', '华蘅芳', '清代', '宛转清歌不忍闻，酒痕无恙旧罗裙。香飘月窟应思桂，梦到高唐总是云。\n\n箧里尚留金蔽甲，书中空寄锦回文。可怜昨夜看牛女，银汉迢迢漏已分。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无题五首 其一' AND p.poem_author = '华蘅芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('燕邸同王道坚醉后限韵戏为子夜离歌捉笔纵书命侍童击缶促之倡和迭就顷刻盈壁亦一快也 其四', '谢与思', '明代', '别欢童稚年，沈忧顿颜槁。侬若见欢时，罗襦系萱草。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '燕邸同王道坚醉后限韵戏为子夜离歌捉笔纵书命侍童击缶促之倡和迭就顷刻盈壁亦一快也 其四' AND p.poem_author = '谢与思';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登定山和光岳 其一', '庄昶', '明代', '万事人间偶唤醒，数椽我屋傍秋藤。醉眠老石三千丈，知在青天第几层。\n\n望外虚名何我敢，眼前门户是君撑。十年面壁收心坐，祇好平生去一矜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登定山和光岳 其一' AND p.poem_author = '庄昶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴市', '李楷', '清代', '朝游吴市门，夕眺太湖云。梅尉已仙去，龙威不可群。\n\n陂塘翔宿鹜，城郭入斜曛。壮士专诸里，萧然少见闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴市' AND p.poem_author = '李楷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('生查子 其二', '添雪斋', '当代', '第一别离歌，落落梧桐下。正是漠然时，正是相思罢。\n\n痴绝不成章，前事由他谢。初雪即凄凉，止在江南夜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '生查子 其二' AND p.poem_author = '添雪斋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黎拾遗昕裴秀才迪见过秋夜对雨之作', '王维', '唐代', '促织鸣已急，轻衣行向重。寒灯坐高馆，秋雨闻疏钟。 \n 白法调狂象，玄言问老龙。何人顾蓬径，空愧求羊踪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黎拾遗昕裴秀才迪见过秋夜对雨之作' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题朱元顺浯溪图', '张孝祥', '宋代', '去年过浯溪，王事有期程。夜半度湘水，但见天上星。\n\n平生中兴碑，梦入紫翠屏。已办北归时，十日穷攀登。\n\n今朝复何朝，忽此短轴横。历历眼中见，湘山无数青。\n\n白云著山腰，楼阁秋气明。便欲扶短策，下濯沧浪缨。\n\n主人山水仙，妙处心自评。元顺骨已冷，千载交盖倾。\n\n赏音寄幅纸，益见忠孝情。题诗疥公画，托我不朽名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题朱元顺浯溪图' AND p.poem_author = '张孝祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('午坐', '陆游', '宋代', '茶杯凝细孔，香岫起微云。\n树影窗间见，禽声屋角闻。\n流年易抛掷，旧学失锄耘。\n师友今零落，何人为运斤？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '午坐' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和萧侍中子显春别诗四首 其四', '萧纲', '南北朝', '桃红李白若朝妆，羞持憔悴比新芳。不惜暂住君前死，愁无西国更生香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和萧侍中子显春别诗四首 其四' AND p.poem_author = '萧纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江城子 寄张世杰', '马需庵', '元代', '年华都逐水流东。再相逢。一衰翁。不道而今，豪气减元龙。白发青衫人老矣，才又向，舞雩风。片帆烟雨淡溟蒙。渺孤鸿。太匆匆。谁似髯参，依旧醉颜红。明日九重仙诏下，还又见，紫泥封。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江城子 寄张世杰' AND p.poem_author = '马需庵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠戴龙台之任惠州二守', '庞嵩', '明代', '水月江天万里清，浣江携月送君行。遐封惠渥新沾沐，对榻经纶旧讲明。\n\n白鹤忽看峰自在，青霞犹记洞中横。长安草色分岐路，聊付东风寄此情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠戴龙台之任惠州二守' AND p.poem_author = '庞嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆昔', '韦庄', '唐代', '昔年曾向五陵游，子夜歌清月满楼。\n银烛树前长似昼，露桃花里不知秋。\n西园公子名无忌，南国佳人号莫愁。\n今日乱离俱是梦，夕阳唯见水东流！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆昔' AND p.poem_author = '韦庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贻刘伯敏', '郭钰', '元代', '江海归来少梦思，论文犹恨识君迟。雪鸿竟去空留迹，天马长鸣不受羁。\n\n每日想君池上酌，有时和我壁间诗。满林秋色风烟晚，甚欲相过未有期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贻刘伯敏' AND p.poem_author = '郭钰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('馀干赠别张二十二侍御（一作馀干别张侍御）', '权德舆', '唐代', '芜城陌上春风别，干越亭边岁暮逢。 \n 驱车又怆南北路，返照寒江千万峰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '馀干赠别张二十二侍御（一作馀干别张侍御）' AND p.poem_author = '权德舆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大梁 其二', '范天烈', '近代', '十日平江九确山，轮蹄几瘁尚间关。强餐麦饭求粗饱，怕到泥涂涉更艰。\n\n僮仆少年偏善病，功名老大最羞颜。陶公毕竟归来好，犹剩门前柳一湾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大梁 其二' AND p.poem_author = '范天烈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵斯远晨起见示', '赵蕃', '宋代', '云行日日候西东，更卜林啼与穴宫。\n乍见天边成四合，不知山脚本来空。\n岂惟吾辈忧艰食，更说军储傒屡丰。\n诏旨已闻汤自责，缺然谏纸疏由衷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵斯远晨起见示' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观贾元放书迹寄其弟季承', '赵蕃', '宋代', '古寺荒凉客寓居，闭门百事付乘除。\n学知定力贫非病，诗见新功乐有余。\n化鹤已空今已矣，骑鲸何处问何如。\n追怀存没伤零落，底事秋来音讯疏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观贾元放书迹寄其弟季承' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗三首 其二', '陆深', '明代', '古井春无泉，槁木夏无枝。仲尼叹粪土，诗人咏德基。\n\n中夕起坐叹，叹息将奚为。去者日己远，来者安可期。\n\n不见令名士，监古乃得师。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗三首 其二' AND p.poem_author = '陆深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花二首 其一', '黄浚', '近代', '嚼尽红绒羞倚柱。偷放帘钩，遮断云来路。却手为琶谁顾误。\n\n羁郎弦上同声谱。\n\n检点旧衣无著处。阿姊东来，乞与黄金缕。还道薄情邀一顾。\n\n不辞比翼青鸾去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花二首 其一' AND p.poem_author = '黄浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋宫词', '邓云霄', '明代', '夜来风雨六宫愁，人自伤心水自流。但羡舞腰偏入掌，谁怜团扇正迎秋。\n\n黄金不买相如赋，青鸟虚随阿母游。基酌姮娥奔月后，何如桑女陌东头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋宫词' AND p.poem_author = '邓云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('失题十二首 其十二', '张弼', '明代', '庭槐风静午阴多，睡起西窗日影过。自笑老来无复梦，漫看庭蚁上南柯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '失题十二首 其十二' AND p.poem_author = '张弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东阁试春日喜雨', '石宝', '明代', '西山多积雪，日暮呈清光。协风自东来，吹绿到池塘。\n\n池塘昨夜春草生，群鸦哑哑含春情。遥听宫车藉千亩，辘轳声转轻雷鸣。\n\n青帝勾芒驱白衣，中天倏忽晦复明。六街无尘见甘雨，谁将万斛珠玑倾。\n\n曾见珠玑雨下土，无食无衣竟何补。但愿淋漓浸田垄，垄头不独商羊舞。\n\n小儿拍手歌太平，老人援枹击土鼓。西窗兀坐兴有馀，阴阴草色侵庭除。\n\n披衣登高发长啸，王家膏泽真随车。北望银山气葱郁，乔松老柏青扶疏。\n\n青扶疏，雨如液。农夫荷耒正南行，桑柘无烟芳草碧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东阁试春日喜雨' AND p.poem_author = '石宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('太上皇后合端午帖子词', '汪应辰', '宋代', '上古遗书究治终，长编通鉴更参同。\n端居坐照无穷事，何用江心百鍊铜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '太上皇后合端午帖子词' AND p.poem_author = '汪应辰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饮酒歌四首 其四', '傅义', '当代', '每逢佳节更思乡，昼夜欢腾中国腔。散场工人最忙碌，空瓶满野大车装。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饮酒歌四首 其四' AND p.poem_author = '傅义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄题钓台', '丘浚', '明代', '祚终四百巳无汉，滩历千年尚姓严。终古祠堂钓台侧，水光山色拥高檐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄题钓台' AND p.poem_author = '丘浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('涵虚阁四咏 其二 听泉', '孙传庭', '明代', '众籁溪边寂，泉声枕上通。急来知带雨，远至想随风。\n\n宛转危桥下，清凄乱石中。拂琴聊一曲，流水调堪同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '涵虚阁四咏 其二 听泉' AND p.poem_author = '孙传庭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七月三十一日夜作 其一', '魏新河', '当代', '身在长安阅客频，这番别意过于真。情如草色遥方觉，人似歌声忆更亲。\n\n枝幸得同花后果，根何能择蕊前因。事非人力非天力，多恐如来眉也颦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七月三十一日夜作 其一' AND p.poem_author = '魏新河';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日载园刺史约同人游瑕邱作', '张晋', '清代', '行乐无古今，陵谷有变迁。风流不歇绝，赖此文字传。\n\n斯邱载《檀弓》，遗迹幸未湮。主人约嘉客，选胜追昔贤。\n\n登顿忽忘疲，周览开心颜。是时雨初霁，林木含朝烟。\n\n微风荡空翠，扑我襟袖间。千里纵远目，平楚何苍然。\n\n恨不起往哲，执手同周旋。主人发高唱，实从挥锦笺。\n\n修禊咏《兰亭》，雅集记《西园》。以今而视昔，夫复何让焉。\n\n斜阳欲西匿，去去还流连。谁是后来者，一笑摇归鞭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日载园刺史约同人游瑕邱作' AND p.poem_author = '张晋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('续董子温咏陶潜诗八首 其七', '刘攽', '宋代', '贵生未必全，徇名良自贼。区中共兹患，形影相与惑。\n\n神释乃超然，道真于此得。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '续董子温咏陶潜诗八首 其七' AND p.poem_author = '刘攽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鲁国图诗', '谢翱', '宋代', '秋风岳下城，海客见图新。树入舞雩里，水来浮磬滨。\n\n东封馀辇路，西狩问虞人。被发逢夫子，狂歌作放民。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鲁国图诗' AND p.poem_author = '谢翱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书罗氏屏风四绝 其二', '李之仪', '宋代', '鼓声绝罢香烟起，涌出潮音满座寒。为问如何第一义，等閒拈却面前山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书罗氏屏风四绝 其二' AND p.poem_author = '李之仪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('海滨书所见', '郑善夫', '明代', '北里万馀户，渔樵更种田。打鱼乘水得，伐木上山便。\n\n禾黍栖南亩，牛羊被远阡。生涯未为少，何意尽颠连。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '海滨书所见' AND p.poem_author = '郑善夫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古十六首', '释道宁', '宋代', '一片虚空亘古今，鳞龙头角竞疏亲。\n坐亡立脱知多少，铁树花开别是春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古十六首' AND p.poem_author = '释道宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('彭泽', '邓雅', '明代', '山通彭泽县，天设海门关。万水潴清浊，千艘渡险艰。\n\n望洋今日叹，承诏几时还。欲访陶潜宅，闻风有愧颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '彭泽' AND p.poem_author = '邓雅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天 邓英翘有鹧鸪天词数十阕，皆述珠江旧游，名之为樱桥绮语。乞题', '汪东', '清代', '为忆前游感不禁。鹧鸪词好费沈吟。一编绮语三生债，几曲阑干万里心。\n\n兰棹急，越江深。恼人春色梦重寻。木棉开处花如血，化作啼痕染客襟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天 邓英翘有鹧鸪天词数十阕，皆述珠江旧游，名之为樱桥绮语。乞题' AND p.poem_author = '汪东';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('追昔感事八首（出世周手稿，集本不载）', '王伯稠', '明代', '高枕青山计未贫，空林幽鸟伴吟身。\n谁能更抱齐门瑟，老觅长安解听人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '追昔感事八首（出世周手稿，集本不载）' AND p.poem_author = '王伯稠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('纸被行', '王炎', '宋代', '瑶姬不触麒麟红，金壶潋滟琥珀逍。\n狐裘公子喜夜永，杯行暖玉烦春葱。\n檐头雪花大如掌，洞房但觉春融融。\n岂知有客方贪睡，漏尽更阑不能寐。\n花红玉白不相随，赖有楮生为伴侣。\n生家住处近麻姑，亦能幻出冰肌肤。\n绝嫌墨客蝇头污，懒入官黄藏蠹鱼。\n宁随人意任舒卷，虽则软美非脂韦。\n风姨霜女皆退舍，稍觉和气生氍毹。\n梅花破雪催寒去，春回人向花前醉。\n女郎雾縠试轻衫，至此失时因坐废。\n绿槐影底夏日长，人间只要一味凉。\n青奴元自不妩媚，居然负恃能专房。\n秋风一夜来消息，又却见渠先弃掷。\n冬来复挽楮生归，属付苍头轻拂拭。\n用则铺张舍则藏，喜愠未尝形玉色。\n世事乘除无不然，安用动心三叹息。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '纸被行' AND p.poem_author = '王炎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和许表民湔江驿四题', '李新', '宋代', '笋成森碧玉，麦熟敛黄云。\n村酒不堪酌，一杯能易醺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和许表民湔江驿四题' AND p.poem_author = '李新';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题敬亭琵琶行填词后二首 其二', '敦敏', '清代', '红牙翠管写离愁，商妇琵琶湓浦秋。读罢乐章频怅怅，青衫不独湿江州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题敬亭琵琶行填词后二首 其二' AND p.poem_author = '敦敏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天•寄', '董以宁', '明代', '两小无猜直到今。丙寅鹊脑惯同斟。鸳鸯向午常交颈，豆蔻多时始见心。\n\n曾赋别，几嗣音。天涯南北雁难寻。归来朱鸟窗前看，应有蛛丝网画琴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天•寄' AND p.poem_author = '董以宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望云中塞', '谢榛', '明代', '几年欲向塞门游，北渡桑乾重旅愁。画角悲凉孤馆夜，黄榆摇落九边秋。\n\n壮心未掷班生笔，浪迹堪怜季子裘。回首江湖任鸥鸟，谩嗟华发滞燕州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望云中塞' AND p.poem_author = '谢榛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('嘲鹭', '方岳', '宋代', '曾有诗矜白鹭閒，一生诗眼乞山漫。\n朝来更觉忙於我，雪沍苍溪不道寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '嘲鹭' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('厓山吊古 其二', '张同祁', '明代', '朝事艰危转见遭，只将哀些重挥毫。肉缘赵氏孤应切，目满遗弓远自劳。\n\n乱世君臣虚石画，青天龙虎散旌旄。只今窑鳖滋苔藓，日落苍茫寒暮涛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '厓山吊古 其二' AND p.poem_author = '张同祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送沈广文之侯官', '胡应麟', '明代', '日暮河梁畔，归帆趁北风。一毡初就日，双剑旧如虹。\n\n驿路蒹葭外，斋头苜蓿中。飘飘幔亭宴，霞色近人红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送沈广文之侯官' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游西子湖至平湖秋月', '方仁渊', '清代', '白公堤上暖云蒸，春水平湖澈底澄。山色晴飞满楼翠，天光倒影一壶冰。\n\n盘中胜味呼烹鲤，柳下清歌听采菱。安得雪消明月夜，一樽浊酒此间凭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游西子湖至平湖秋月' AND p.poem_author = '方仁渊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('嘉鱼 其一', '屈大均', '明代', '十月小湘峡，嘉鱼出穴多。爱寒餐雪水，乘暖下烟波。\n\n作鲙宜长至，分甘与玉珂。殷勤渔父意，岁岁此牂柯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '嘉鱼 其一' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和景彝诮扶出者', '王圭', '宋代', '天子重论秀，待之以公卿。志士抱奇节，犹或场屋轻。\n\n学能苦自琢，诗书腹纵横。胡为怀袖间，挟册角群生。\n\n诃卒窥其旁，执衣来叩楹。狂狙就新缚，跳突哀且鸣。\n\n岂不念寒孤，顾有素令明。利禄非可苟，辱甚舍弗烹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和景彝诮扶出者' AND p.poem_author = '王圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红 第二体。和张元干《芦川词》', '顾太清', '清代', '绿惨红愁，东风里、杜鹃声恶。春去也、小楼人寂，雨声偏作。\n\n弱柳难将春思系，泪珠长向花前落。问天涯、归梦几时来。\n\n随风泊。\n\n春寒重，罗衣薄。音书断，情无著。对残灯顾影，共谁斟酌。\n\n昨夜雨睛知骤暖，等闲负了三春约。卷珠帘、一望碧天长，山如削。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红 第二体。和张元干《芦川词》' AND p.poem_author = '顾太清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('棣华堂', '韩维', '宋代', '锦衣赍钺耀当年，心在王家迹在边。\n论议每先诸将勇，规模仍袭仲兄贤。\n一朝华栋飞翚动，四坐清觞插羽传。\n欲赋酬章惭懦氏，白头终日诵尘编。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '棣华堂' AND p.poem_author = '韩维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('招赵友饮禅院', '张煌言', '明代', '清酒今朝买百壶，拟邀佳客醉屠苏；玉山倒处人争看，可有连城一璧无？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '招赵友饮禅院' AND p.poem_author = '张煌言';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜雨诗 其二', '张昭远', '宋代', '祷旱何妨抵死求，分明在处有神湫。只消一念精诚格，立使风雷布九州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜雨诗 其二' AND p.poem_author = '张昭远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赐枢密院楼炤', '宋高宗', '宋代', '联念邦家历万几，幸卿相与久维持。\n孜孜广道诹询处，蹇蹇封章纳诲时。\n半世奇勋惟我重，一生忠节自天知。\n南归奚事将为赠，金石诗篇壮羽仪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赐枢密院楼炤' AND p.poem_author = '宋高宗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郊坛燕集', '马汝骥', '明代', '北极冠缨紫气分，南郊楼阁坐氤氲。\n莺啼苑树琼筵合，燕蹴坛花锦瑟闻。\n二月衣沾星殿雨，九天杯覆露盘云。\n莫言词赋甘泉绝，欲向仙都诵赤文。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郊坛燕集' AND p.poem_author = '马汝骥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('国清振锡桥', '释慧远', '宋代', '五峰翠挼蓝，双涧声振锡。\n中有老频螺，倒吹无孔笛。\n不许行云作伴归，谁来踏破苍苔迹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '国清振锡桥' AND p.poem_author = '释慧远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早发上东门', '綦毋潜', '唐代', '十五能行西入秦，三十无家作路人。 \n 时命不将明主合，布衣空染洛阳尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早发上东门' AND p.poem_author = '綦毋潜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('茂林居士忆琴百二绝句 其二十九', '吴玉如', '近代', '弱腕扶郎思强步，床前咫尺晕垂头。明知撑扎缘何事，欲减郎心一段愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '茂林居士忆琴百二绝句 其二十九' AND p.poem_author = '吴玉如';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王仪伯参政见和郊字韵诗复用韵叙谢二首 其二', '虞集', '元代', '圣远言湮感垫昏，河汾千载最知恩。垂绅论道称前古，束发明经奉至尊。\n\n车骑身从游汗漫，庭闱心在视寒温。朝回未觉归途晚，斗柄西移揭角根。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王仪伯参政见和郊字韵诗复用韵叙谢二首 其二' AND p.poem_author = '虞集';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('开平书事 其二', '梵琦', '元代', '绝域秋风早，殊方使客还。河冲秦日塞，地接汉时关。\n\n万古悲青冢，兼程过黑山。从容陪国论，咫尺近天颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '开平书事 其二' AND p.poem_author = '梵琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('步蟾宫·绿华翦碎娇云瘦', '蒋捷', '宋代', '绿华翦碎娇云瘦。剩妆点、菊前蓉後。娟娟月也染成香，何况、纤罗襟袖。秋窗一夜西风骤。翠奁锁、琼珠花镂。人间富贵总腥膻，且和露、攀花三嗅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '步蟾宫·绿华翦碎娇云瘦' AND p.poem_author = '蒋捷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('会稽三贤祠诗 旌忠庙', '王十朋', '宋代', '国家往往艰难中，搢绅节义扫地空。靖康有一忠悯公，建炎独有唐侯忠。\n\n唐侯爵位何曾隆，身居行伍侪罴熊。平生经史漫不通，严霜烈日蕴在衷。\n\n愤然一奋不顾躬，太尉夺笏嗟匆匆。子房铁椎计已穷，张巡就缚气尚雄。\n\n杲卿锯解骂未终，忠血义肉涂地红。烈气英魂薄苍穹，事惊朝野闻帝聪。\n\n立庙旌忠浙江东，睢阳双庙同高风。名书青史等岱崧，当时开门谁纳戎，贻臭千古如蛆虫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '会稽三贤祠诗 旌忠庙' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和姚令威春晚即事', '许志仁', '宋代', '卧看游丝媚远天，起寻幽径却茫然。\n句成落絮飞花里，心在残霞夕照边。\n无复双鱼传尺素，空余宝瑟思华年。\n老来情味人应笑，白首伤春只醉眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和姚令威春晚即事' AND p.poem_author = '许志仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('第二十六鸡栖凤巢颂', '释义青', '宋代', '无伴石人衣入山，云笼红顶绿衣寒。喝开劫兆三峰顶，捧出金栏对日看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '第二十六鸡栖凤巢颂' AND p.poem_author = '释义青';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('思佳客', '邓嘉缜', '近代', '自遣新愁自不支。蓬山迢递问归期。欢情似水春韶四，客感如云夜漏迟。\n\n羁彩凤，托灵犀。就中心事有谁知。常时对面成辜负，何必天涯是别离。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '思佳客' AND p.poem_author = '邓嘉缜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('都昌沿檄黟歙遇春一首', '王阮', '宋代', '忽忽年华换，悠悠客路长。\n春声先水响，山气欲花香。\n何补公家事，空随吏役忙。\n白云知此意，一片直都昌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '都昌沿檄黟歙遇春一首' AND p.poem_author = '王阮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送李华西太守二首 其一', '陈恭尹', '明代', '归去人皆惜，歌声满峡中。吏才推悃愊，文体仰宗工。\n\n不以和伤介，能将雅变风。一时诸五马，德重总输公。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送李华西太守二首 其一' AND p.poem_author = '陈恭尹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乌使君', '林宗放', '宋代', '始听歌来暮，还闻说去思。\n但知忧国计，那肯问家为。\n跨竹儿童集，携书父子随。\n谢在攀恋处，争作画图披。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乌使君' AND p.poem_author = '林宗放';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山溪', '陈忠平', '当代', '山溪流且缓，阻石更迂行。岁月磨无角，烟霞濡有声。\n\n经寒不曾冻，返景自然清。莫比江河阔，江河此处生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山溪' AND p.poem_author = '陈忠平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元旦', '边贡', '明代', '岁首江南久客身，宦情寥落道情深。极知佳丽非吾土，且喜逢迎有故人。\n\n城上雪痕经腊在，水边梅蕊觑年新。呼童早蜡登山屐，莫负陶家漉酒巾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元旦' AND p.poem_author = '边贡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春·虱辩', '陆震', '清代', '虱告主人，臣罪当烹，幸缓须臾。恰憎予贪甚，诚然无状，念兹蠢尔，焉用深诛。\n\n造化从来，多钟物害，攫者豺狼射者狐。公真误，总鸱张不问，翻谴区区。\n\n公能为蹠之徒。敢群处、裈中慁起居。奈绣衣云烂，生无而分，锦衾香暖，命不人如。\n\n独类嵇生，性耽懒慢，盥洗都慵发怕梳。还相宥，愿长依敝裤，终惠微躯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春·虱辩' AND p.poem_author = '陆震';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('简茂秦', '王世贞', '明代', '飘梗真难系，垂杨未可攀。君名去留外，吾道是非间。\n\n且白人前眼，凭苍客后颜。萧然一长揖，诗句满春山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '简茂秦' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临汝书院成潘水部赠独脚歌次韵奉答', '周瑛', '明代', '大冶铄物抟阴阳，青春去我何堂堂。西偏小搆亦颇良，不施黝垩横白杗。\n\n捲帘正对五羊冈，树木拂檐交青苍。祥烟紫气相回翔，坐令白日迷晶光。\n\n文采弸彪来省郎，为我艺苑芟秽荒。铿然制作称大方，利觜长距独擅场。\n\n嗟予苦学未成章，点缀牺樽青与黄。六经窟穴漱馀香，拍拍春意觉满腔。\n\n与君对织云锦裳，著向风前聊徜徉。欲骖麟凤游帝乡，又笑目眩心未忘。\n\n小吏抱牍来仓皇，谓耽文字颇有妨。广陆无车川无梁，出门万里道路长，使君局面宜更张。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临汝书院成潘水部赠独脚歌次韵奉答' AND p.poem_author = '周瑛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('眼儿媚（寄赠）', '史达祖', '宋代', '潘郎心老不成春。风味隔花尘。帘波浸笋，窗纱分柳，还过天津。 \n 近时无觅湘云处，不记是行人。楼高望远，应将秦镜，多照施颦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '眼儿媚（寄赠）' AND p.poem_author = '史达祖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀嵩亭', '华镇', '宋代', '嵩高维神岳，峻极上霄汉。临登信舍地，庶入朝夕观。\n\n垂檐碧云低，带户前山乱。何日见愚公，神栖梦轻断。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀嵩亭' AND p.poem_author = '华镇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄别王澹庵迁秩建南道', '黄公辅', '明代', '四载埙篪共合簪，洞庭不似两情深。清宵有月频疑色，妙曲无弦倍赏音。\n\n白鹤峰头天渐远，碧云楼畔树芳森。并州父老如相问，倦雨惟知向茂林。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄别王澹庵迁秩建南道' AND p.poem_author = '黄公辅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄家庄', '林逋', '宋代', '黄家庄畔一维舟，总是沿流好宿头。\n野兴几多寻竹径，风情些小上茶楼。\n遥村雨暗鸣寒犊，浅溆沙平下晚鸥。\n更有锦帆荒荡事，茫茫随分起诗愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄家庄' AND p.poem_author = '林逋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋兴次韵', '张渊', '明代', '识来三十四年非，珍重山林短后衣。\n龟背刮毛惭我拙，虎头食肉任人飞。\n老亲种种垂秋发，旧屋萧萧淡夕晖。\n办得浮家明日去，五湖处处是渔矶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋兴次韵' AND p.poem_author = '张渊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王才臣 其五 松庵', '周必大', '宋代', '冬与滕六宜，夏与赵盾敌。更有茯苓功，保君千岁质。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王才臣 其五 松庵' AND p.poem_author = '周必大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('减字木兰花 其二 复用韵，有所寄', '汪东', '清代', '姮娥自语。不肯广寒宫里住。特破云围。举酒相邀一问之。\n\n眉痕初秀。金镜亏时那见有。露湿裳衣。一夕团圞众已知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '减字木兰花 其二 复用韵，有所寄' AND p.poem_author = '汪东';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂二十一首 其十三', '释智愚', '宋代', '夫蛊者最灵通，不期而会，不约而同。拶著崖崩石裂，抛出金圈栗蓬。\n\n惊倒露柱，嚇煞灯笼。不知何处毒种，元来门里有虫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂二十一首 其十三' AND p.poem_author = '释智愚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('芳沚亭', '郑侠', '宋代', '澄流良湜湜，幽藻还漪漪。\n不是采蘩手，芬芳长自持。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '芳沚亭' AND p.poem_author = '郑侠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻蝉五绝句奉呈诸幕友 其一', '曾丰', '宋代', '炎帝乘风驭气行，前驱警跸羽仙轻。胸中一部钧天乐，吐作衙官唱道星。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻蝉五绝句奉呈诸幕友 其一' AND p.poem_author = '曾丰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浮邱八景 其七 听笙亭', '邓时雨', '明代', '缥缈云中若有声，恍疑王子学吹笙。孤亭寂寞浮舄畔，千载犹传伊洛名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浮邱八景 其七 听笙亭' AND p.poem_author = '邓时雨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆旧八首 其六', '金朝觐', '清代', '吾慕李约亭，老吏著芳型。论事有先见，立言持正经。\n\n金银清夜气，仁寿出祥刑。几忆亲甘苦，居然两鬓星。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆旧八首 其六' AND p.poem_author = '金朝觐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贺孝公被挞二首 其一', '释函可', '明代', '狱吏何妨溺死灰，独将鸡肋抵轰雷。翻嫌昔日王孙饿，宁受尊拳不受哀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贺孝公被挞二首 其一' AND p.poem_author = '释函可';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东园招孙中叔', '郑獬', '宋代', '花路横梢已碍马，断无人迹赏年芳。\n绿杨成穗点著地，蝴蝶作团飞过墙。\n不禁梦回多黯郁，长因酒后得凄凉。\n期君待与春翁约，买取东风任醉乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东园招孙中叔' AND p.poem_author = '郑獬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日客怀二首 其一', '于谦', '明代', '马上春如梦，空嗟岁月长。天涯无限路，芳草自斜阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日客怀二首 其一' AND p.poem_author = '于谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂兴五首 其四', '艾性夫', '宋代', '蚁国槐为穴，蜂衙蜜作房。采花与旋磨，辛苦知尊王。\n\n胡为枭獍生，思食父母肠。彼微有尊卑，此大相灭亡。\n\n物情有不齐，使我心忧伤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂兴五首 其四' AND p.poem_author = '艾性夫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('禅人并化主写真求赞 其三二九', '释正觉', '宋代', '规圆矩方，凫短鹤长。落日烟村牧笛，平湖月夜鱼榔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '禅人并化主写真求赞 其三二九' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('瑞鹤仙才人河满赋此慰之', '陈洵', '清代', '暗尘惊转烛。送华堂归客，春波如麴。笙箫咽寒玉。\n\n有明妆窈窕，自伤幽独。庭花簌簌。夜潮生、东风又促。\n\n算游丝、飞絮牵萦，天远泪痕相续。\n\n枨触。长门买赋，词客千金，此情谁属。蛾眉漫蹙。今古事，几歌哭。\n\n但飘零休恨，天涯看遍，芳草无人更绿。问伊家、除了周郎，为谁误曲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瑞鹤仙才人河满赋此慰之' AND p.poem_author = '陈洵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏舞妓诗', '何逊', '南北朝', '管清罗荐合。\n弦惊雪袖迟。\n逐唱回纤手。\n听曲动蛾眉。\n凝情眄堕珥。\n微睇托含辞。\n日暮留嘉客。\n相看爱此时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏舞妓诗' AND p.poem_author = '何逊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天关讲学示诸生', '杨起元', '明代', '南域精华回岭海，白云情色照仙城。烘花日暖蔷薇丽，掠燕风生杨柳轻。\n\n定坐已忘尘俗念，咏歌犹浃冠童情。千年遗范瞻先哲，万古斯文畏后生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天关讲学示诸生' AND p.poem_author = '杨起元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('滇海曲 其十一', '杨慎', '明代', '煮海鹾郎暝漉沙，避风估客夜乘槎。雪浮粳稻压春酒，霞嚼槟榔呼早茶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '滇海曲 其十一' AND p.poem_author = '杨慎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('厌于行役感梅赋诗', '林季仲', '宋代', '归袖曾攀墙外子，征鞍又拂雪中花。往来应被江梅笑，笑我经年不在家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '厌于行役感梅赋诗' AND p.poem_author = '林季仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('钱舜举木芙蓉', '卢琦', '元代', '红妆初映酒杯酣，斜倚西风转不堪。霜后池塘秋欲尽，令人惆怅忆江南。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '钱舜举木芙蓉' AND p.poem_author = '卢琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游灵山护国禅院作 其九', '丘逢甲', '清代', '閒向山僧理旧闻，佛楼携客话秋云。谁知八部天龙力，曾护昌黎谏佛文。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游灵山护国禅院作 其九' AND p.poem_author = '丘逢甲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苦寒作', '王冕', '元代', '昨日风寒枯木折，今日五更霜似雪。河伯泉仙惊怪言，冻杀深潭三足鳖。\n\n南海一平行大舆，五尺之冰千古无。珊瑚树死日色薄，老翁破冻叉僵鱼。\n\n凤凰不出鸲鹆语，秃鹙飞啼血如雨。驼马交驰入不毛，兜鍪不惮饥寒苦。\n\n豺狼夹道狐兔骄，白草万里蛮烟焦。纷纷赤子在炮炙，三士何缘争二桃。\n\n君不见江南古客颇痴懒，养得一双青白眼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苦寒作' AND p.poem_author = '王冕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贫女吟四首 其四', '文天祥', '宋代', '巧梳手欲冰，小颦为寒怯。有时衿肘露，颇与雪争洁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贫女吟四首 其四' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过邵伯湖', '张履', '清代', '水行意如仙，苍波去浩渺。朗然空色中，物我同了了。\n\n湖外复有湖，断续疏林绕。风帆隔浦多，渔舍回洲小。\n\n微云交日光，澹澹浮虚杳。时见枯芦间，决起数沙鸟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过邵伯湖' AND p.poem_author = '张履';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清明后一日下沙', '刘摰', '宋代', '微风吹□幸阴晴，笑侧吟鞭十里行。时节早蚕生谷雨，人家新火接清明。\n\n衮衣犊鼻均无物，篱鴳云鹏各有情。欲挹浮丘挽春驭，尊罍定得泻东瀛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清明后一日下沙' AND p.poem_author = '刘摰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄新衡阳徐使君左司山长', '赵汝腾', '宋代', '醉墨淋漓天地间，谁知大德不逾闲。\n世无孔子今希孔，国有颜渊易铸颜。\n多士龙门一乔岳，斯文牛耳两名山。\n暮春九曲峰前水，一笑风雩气象还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄新衡阳徐使君左司山长' AND p.poem_author = '赵汝腾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八尺湖夜泊怀李与熙张子环', '徐熥', '明代', '八尺湖边月上迟，相逢犹记去年时。一从落魄长安后，三处飘零各不知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八尺湖夜泊怀李与熙张子环' AND p.poem_author = '徐熥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜泊虞山下', '王世贞', '明代', '明当向城府，维舟此山足。奚必遂登临，聊以驱吾俗。\n\n初月未拟规，浮云更成璞。酒罢独何为，移书就残烛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜泊虞山下' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游苏仙山', '萧立之', '宋代', '坛下松声江上潮，坛前天近北风高。山腰洞黑藏丹灶，云顶秋深落石桃。\n\n逆理偷生虽世论，离群独立亦人豪。仙家尽有青精饭，不与吟翁绿鬓毛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游苏仙山' AND p.poem_author = '萧立之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄内', '王泰偕', '清代', '山杏溪桃烂似霞，风光应已遍天涯。客游枉被东风笑，如此花时不在家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄内' AND p.poem_author = '王泰偕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('友山李道士抱琴来为予作三曲请诗各为之操·', '姚勉', '宋代', '若有人兮江之干，志在流水兮必观其澜。\n清风萧萧兮水声潺潺。吁嗟乎，\n世道江河兮谁底其间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '友山李道士抱琴来为予作三曲请诗各为之操·' AND p.poem_author = '姚勉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上册宝十三首 亚、终献用《和安》。', '郊庙朝会歌辞', '宋代', '望高六宫，位应四星。辅佐君子，警戒相成。袆衣褒崇，琛册追荣。\n\n于以奠之，有椒其馨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上册宝十三首 亚、终献用《和安》。' AND p.poem_author = '郊庙朝会歌辞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('方平道中 其二', '段克己', '金朝', '病怯春衫薄，衰怜葛屦轻。平芜迷旧迹，幽鸟变新声。\n\n兴与云俱远，心同水共清。胶胶还扰扰，回首笑浮生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '方平道中 其二' AND p.poem_author = '段克己';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('永昭陵挽词三首 其三', '欧阳修', '宋代', '行殿沉沉画翣重，凄凉挽铎出深宫。攀号不悟龙胡远，侍从犹穿豹尾中。\n\n日薄山川长起雾，天寒松柏自生风。斯民四十年涵煦，耕凿安知荷帝功。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '永昭陵挽词三首 其三' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉使契丹二十八首 春日寄内', '苏辙', '宋代', '春到燕山冰亦消，归骖迎日喜嫖姚。\n久行胡地生华发，初试东风脱敝貂。\n插髻小幡应正尔，点盘生菜为谁挑。\n附书勤扫东园雪，到日青梅未满条。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉使契丹二十八首 春日寄内' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满庭芳 欲脱家', '王哲', '元代', '既欲修行，终全＊谧，出离尘俗相当。莫凭外坐，朝暮起心香。须是损妻舍事，违乡土、＊却儿娘。常归一，民安国富，战胜又兵强。长长。潇洒做，搜寻玄妙，认取清凉。又凭空渺邈，大道无方。只在圆光自照，明来后、堪用衡量。重阳子，迎霜金菊，独许满庭芳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满庭芳 欲脱家' AND p.poem_author = '王哲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题墨梅', '陶宗仪', '元代', '花光三昧幻冰魂，满纸春风带墨痕。好似孤山亭子上，一枝斜映月黄昏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题墨梅' AND p.poem_author = '陶宗仪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答顾司勋二首 其一', '欧大任', '明代', '宸居钜丽观，建业维旧京。省寺夹阊阖，宫阙槩泰清。\n\n人文盛斯日，鸣环猎冠缨。顾生起吴会，握管逢休明。\n\n修嫭宛珠润，清馥含兰馨。通方极丘索，辨古分淄渑。\n\n诗从四始正，曲合九奏成。何哉铨衡地，洵有箕颖情。\n\n结佩岂不美，折麻殊自荣。余岂茂陵客，跌宕东方生。\n\n申章谢嘉藻，辗转怀同声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答顾司勋二首 其一' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('朝陵遇雨 其二', '区大相', '明代', '言避崤陵雨，翻行大壑云。微风清树气，积润洗山文。\n\n银海春波阔，龙池细涧分。九陵松柏路，香霭日氤氲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '朝陵遇雨 其二' AND p.poem_author = '区大相';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('彭城怀古', '王佐（汝学）', '明代', '满目山河霸业荒，西风烟草正茫茫。沐猴人去成终古，戏马台前自夕阳。\n\n只把仁残分汉楚，何曾百二藉金汤。韩生浪说关中好，秦在关中亦已亡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '彭城怀古' AND p.poem_author = '王佐（汝学）';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮·霜天不管青山瘦', '佚名', '宋代', '霜天不管青山瘦。轻云浅拂修眉皱。烟树隔潇湘。隔帆吹异香。影残春恨小。淡墨敧斜倒。无处著消愁。笛寒人倚楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮·霜天不管青山瘦' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天', '吴怀凤', '清代', '几许情怀恨未完。花枝常向病中看。渐依人面春云薄，欲拾榆钱夜月残。\n\n愁没绪，思无端。低徊镇日自凭栏。东风芳草浑无赖，弱质偏教耐晚寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天' AND p.poem_author = '吴怀凤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题徐工部节孝册二首 其一', '王以悟', '明代', '天祸东扬日，孝儿独有名。丹心青史在，九死一毛轻。\n\n挝鼓声争烈，服砒意更倾。令人思蔡顺，厚遣赤眉营。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题徐工部节孝册二首 其一' AND p.poem_author = '王以悟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和真珠花二首 其一', '廖行之', '宋代', '琼林玉女职司花，装缀珠玑泣露华。妙手有神俄点化，灵根何日下天涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和真珠花二首 其一' AND p.poem_author = '廖行之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶题六绝 其五', '李之仪', '宋代', '不觉六月初八日，还是去年瓜熟时。鞭藉竟谁能致曲，定自昭昭终可期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶题六绝 其五' AND p.poem_author = '李之仪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴趋行', '佚名', '魏晋', '茧满盖重帘，唯有远相思。藕叶清朝钏，何见早归时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴趋行' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山城月夜自和东行集句韵', '陈循', '明代', '蟾光如水浸清秋，防塞将军在戍楼。\n千里无尘烽火寂，夜深犹起看旄头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山城月夜自和东行集句韵' AND p.poem_author = '陈循';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九日二首次九峰韵 其一', '钟芳', '明代', '晓霁凝孤眺，凭高挹翠寒。任渠秋色老，且爱菊英团。\n\n地控舆图尽，峰攒冕黼端。时清惭独拙，应负旧儒冠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九日二首次九峰韵 其一' AND p.poem_author = '钟芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('壬寅春正四日晋郡小憩道中古庵信笔书此 其三', '何士循', '清代', '自我来太平，十日五巡乡。一到松门城，六夜宿箬簧。\n\n凡再至三至，新河及新场。足迹遍东南，更涉大陈航。\n\n乘风破海浪，百里犯重洋。兼至隘顽城，除夕食不遑。\n\n鸣琴易鸣笳，谁云不下堂。每每督队出，有如事戎行。\n\n前行列营哨，到处联团防。炮声雷訇匉，旗影风飞扬。\n\n冒雨群如沐，犯雪冻欲僵。我劳民未安，中夜起徬徨。\n\n且喜入新年，暂可息尘忙。行行复至郡，乃为迎送忙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '壬寅春正四日晋郡小憩道中古庵信笔书此 其三' AND p.poem_author = '何士循';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('悼亡', '王涣', '唐代', '春来得病夏来加，深掩妆窗卧碧纱。为怯暗藏秦女扇， \n 怕惊愁度阿香车。腰肢暗想风欺柳，粉态难忘露洗花。 \n 今日青门葬君处，乱蝉衰草夕阳斜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '悼亡' AND p.poem_author = '王涣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('思乡', '张鹏翮', '清代', '久宦思乡岁月深，几回归梦抵千金。门前江色依然绿，槛外莺声尚满林。\n\n漫说申家新使者，更夸乔令旧知音。曙钟乍动惊魂觉，谁识愁人一片心？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '思乡' AND p.poem_author = '张鹏翮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日书怀寄白宾客', '刘禹锡', '唐代', '州远雄无益，年高健亦衰。兴情逢酒在，筋力上楼知。 \n 蝉噪芳意尽，雁来愁望时。商山紫芝客，应不向秋悲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日书怀寄白宾客' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('生查子（收灯日次李举之韵）', '洪适', '宋代', '廉纤小雨来，噤罥轻寒乍。丝竹送迎时，灯火阑珊夜。 \n 铜壶漏故迟，银烛花频灺。怀我独醒人，健笔方飞洒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '生查子（收灯日次李举之韵）' AND p.poem_author = '洪适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('斋居怀林逸人', '黄玄', '明代', '累月不出户，阶前空绿苔。如何归雁后，不见故人来。\n\n野竹连书幌，寒山对酒杯。閒居能著述，端愧子云才。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '斋居怀林逸人' AND p.poem_author = '黄玄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梵动经 其三', '钟锦', '当代', '我及世间终漫存，枉从劫内计根源。若将观察穷无际，天地绵绵孰可论？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梵动经 其三' AND p.poem_author = '钟锦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和张王臣', '廖行之', '宋代', '词伯今犹从事衫，追风才轶谢羸骖。\n浪传齐己声江左，不见弥明隐岳南。\n骚读正堪供痛饮，箎音那许接高谈。\n君家况有輶轩法，乞与新编得细参。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和张王臣' AND p.poem_author = '廖行之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花 巴陵山行', '顾璘', '明代', '秋色那知行近远。翠竹丹榆，递换撩人眼。导骑才随山麓转。\n\n渔舟又渡溪流浅。\n\n数过奇峰千万点。野兴疏狂，转逗身轻健。悬崖绝涧皆平坦。\n\n寰中只奈人心险。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花 巴陵山行' AND p.poem_author = '顾璘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十三澳诗', '胡健', '清代', '沙回港绕锦相联，海阔银河落九天。鼎峙中分庐上下，湾开四面地方圆。\n\n潭边月载求鱼艇，水淈人耕立鹤田。礼让易兴缘俗朴，书声时听和春弦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十三澳诗' AND p.poem_author = '胡健';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古四十四首', '释法泰', '宋代', '鸡寒上树，鸭寒下水。\n三百馀会不能宣，九年面壁徒瞌睡。\n休瞌睡，上是天兮下是地。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古四十四首' AND p.poem_author = '释法泰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花开到九分', '叶燮', '清代', '亚枝低拂碧窗纱，镂月烘霞日日加。祝汝一分留作伴，可怜处士已无家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花开到九分' AND p.poem_author = '叶燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题湖堂长春风堂', '陈宓', '宋代', '柯翰由来元气同，要须壮岁似儿童。\n君家友爱谁能比，一榻长如二月中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题湖堂长春风堂' AND p.poem_author = '陈宓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江头十日雨', '陆游', '宋代', '江头十日雨，雨止春已尽。\n残红如扫空，草木皆绿润。\n村墟樱笋闹，节物团粽近。\n可怜笠泽翁，百忧集双鬓。\n赋诗空自清，学道了不进。\n林间一瓯茶，晤语君勿吝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江头十日雨' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送春', '许炯', '明代', '二十四番春事忙，东君已驾欲回乡。杜鹃枝上偏啼血，金谷楼前易断肠。\n\n芳草有情还绊马，落花无泪可沾裳。明年更有来时节，桃李相迎整旧妆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送春' AND p.poem_author = '许炯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题桃花珍禽图', '刘崧', '明代', '山桃花开红满枝，珍禽啄花光陆离。袅袅欲立不自持，吴堤十里锦作帷。\n\n忆昔半醉倒接䍦，走马挟弹归来时，还见踏翻红雪飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题桃花珍禽图' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟花间十八首 其十五 八拍蛮·阎选', '汪东', '清代', '轻锁雕笼囚凤鸟，故抛红豆散鸳鸯。闺里若应知此恨，背人偷揾泪千行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟花间十八首 其十五 八拍蛮·阎选' AND p.poem_author = '汪东';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天平山', '苏舜钦', '宋代', '吴会括众山，戢戢不可数。其间号天平，突兀为之主。\n\n杰然镇西南，群岭争拱辅。吾知造物意，必以屏大府。\n\n清溪至其下，仰视势飞舞。伟石如长人，坚立欲言语。\n\n扪萝缘险磴，烂漫松竹古。中腰有危亭，前对绀壁举。\n\n石窦落玉泉，泠泠四时雨。源生白云间，颜色若粉乳。\n\n旱年或播洒，润可足九土。奈何但泓澄，未为应龙取。\n\n予方弃尘中，岩壑素自许。盘桓择雄胜，至此快心膂。\n\n庶得耳目清，终甘死于虎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天平山' AND p.poem_author = '苏舜钦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和退之李昂四首 其四', '陈伟', '当代', '万古寥天一鹗空，烹来猛士又歌风。擎杯不尽兴亡恨，消得残阳几度红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和退之李昂四首 其四' AND p.poem_author = '陈伟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天', '俞陛云', '清代', '淰淰柔波拍舵鸣。小诗都半客中成。新丝上市喧人语，香稻连畦晒晚晴。\n\n乡梦稳，布帆轻。髫年犹及见承平。山川淳朴流民少，午夜行舟总不惊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天' AND p.poem_author = '俞陛云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三闾庙', '戴叔伦', '唐代', '沅湘流不尽，屈宋怨何深。\n日暮秋烟起，萧萧枫树林。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三闾庙' AND p.poem_author = '戴叔伦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七峰诗序 碧云峰', '李纲', '宋代', '落日衔山隐半轮，桑榆残照起游氛。佳人怅望何时见，万里平凝合碧云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七峰诗序 碧云峰' AND p.poem_author = '李纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题严公祠', '李处权', '宋代', '挂席上桐庐，溪山似画图。\n斯人不复见，吾道一何孤。\n谁入非熊梦，真成失马从。\n清风端未泯，犹可激贪夫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题严公祠' AND p.poem_author = '李处权';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十二月二日腊祭前一日致斋惠照呈清叟察院三绝 其一', '郑刚中', '宋代', '峨冠执法公宜整，端冕临祠我亦严。深炷炉香通问讯，小寒清坐隔疏帘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十二月二日腊祭前一日致斋惠照呈清叟察院三绝 其一' AND p.poem_author = '郑刚中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浯溪行', '严永华', '清代', '昔读磨崖碑，已耳浯溪名。今向岭西游，快作《浯溪行》。\n\n浯溪之水清千尺，浯溪之石更奇特。次山文字平原书，万古光芒烛奎壁。\n\n嗣皇灵武成中兴，元戎两京显殊绩。惜哉张、李乱纪纲，我览斯文增叹息。\n\n当时不识颜真卿，天生汾阳为社稷。壮士解衣吁可危，槛车就逮寒无色。\n\n若非仙李识奇才，那得冲风起云异。纵令厮养皆英雄，要伏词臣大识力。\n\n苍茫怀古意无限，老枫无言山自碧。更将揽胜登𢈪台，遗址荒凉不可得。\n\n记委符节归江湖，剩有窊樽涵月魄。振衣四顾浩悲歌，行人指点漫郎宅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浯溪行' AND p.poem_author = '严永华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅山宗老惠近诗明日自山中来访余尧城驿二首 其二', '周紫芝', '宋代', '参得诗中句外禅，颇知经岁杜禅关。要须觌面亲分付，不免烦君一下山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅山宗老惠近诗明日自山中来访余尧城驿二首 其二' AND p.poem_author = '周紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('去年十一月十二日致宏如秦州仆饯之余口复到', '张嵲', '宋代', '忆昔游河梁，对床三夜语。\n平生慷慨心，远别颜亦苦。\n朔风黄叶深，尚记躯车去。\n君行已映林，我首犹屡顾。\n重经分手地，物色宛如许。\n怀人感河山，抚节惊寒暑。\n别来世事多，琐细不足数。\n惟有绿林徒，跳梁犹若故。\n汉南十二州，一半为盗据。\n向之西来师，猛鸷类熊虎。\n从以万马群，旌旃蔽村坞。\n惟知口打贼，未辨狸搏鼠。\n徵求徒浚民，万分一无补。\n空令贫者毙，复使富室窭。\n去年粟如金，艰食古未睹。\n今春濒汉州，秋种不入土。\n如何十万师，不办一朝貯。\n传闻许汝郊，平民尽俘掳。\n秋高马首南，跬足仰谁御。\n栖山无定居，处邑复多惧。\n无资忧殍踣，有粟畏攘取。\n怀安昔所戒，随众谋远举。\n第恐向他州，未保终安堵。\n悠悠四海间，托身定何所。\n忧来如鼎燋，意乱若棼缕。\n君家聚族多，巢幙多风雨。\n胡为事远游，遄归莫容与。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '去年十一月十二日致宏如秦州仆饯之余口复到' AND p.poem_author = '张嵲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜迁莺', '王恽', '元代', '五更残梦。听绿窗莺语，罗衾香拥。百啭多情，娇啼无泪，枕上一声时送。\n\n真成翠鬟双笋，当户玉琴初弄。欲谁共。趁风和求友，乔林烟蓊。\n\n春动。花气重。暗度垂杨，暖人酴醾洞。倦客芳悰。佳人幽思，愁满彩笺金凰。\n\n自怜比来心事，两翅果谁搏控。听指纵。望高城落日，黄尘飞鞚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜迁莺' AND p.poem_author = '王恽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江黄二州谒白尚书苏端明祠有感', '王世贞', '明代', '白傅佐浔阳，匡庐落其手。苏公谪宜黄，游踪寄樊口。\n\n物情岂相为，天意良不偶。挥泪对青衫，垂腰厌黄绶。\n\n是时二公年，四十加八九。飞腾在俄顷，纶綍相先后。\n\n而我同兹岁，楚宪起南亩。却顾所佩章，叨窃惭已久。\n\n椒浆荐落日，馀沥自为寿。髫年弄笔墨，老至忘其丑。\n\n颇谙游戏禅，更贪声闻酒。别业娄水傍，岁功良亦厚。\n\n园多履道竹，门种杭堤柳。功名善愚人，人生好自负。\n\n造物亦苦悭，安能令多取。真乐随形无，虚名背身有。\n\n洛下醉朱唇，天南摇白首。明年定挂冠，不蓄赵瑟妇。\n\n以此叩二公，公其默许否。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江黄二州谒白尚书苏端明祠有感' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('朝丹霞', '高似孙', '宋代', '杳倏驾兮潜青宜，舞刚风兮鹄分翎。\n上何有兮无能名，老积气兮寒泠泠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '朝丹霞' AND p.poem_author = '高似孙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登庐峰二首 其二', '朱熹', '宋代', '佳友纷来集，欣然会宿心。风泉陪徙倚，云月共窥临。\n\n雅唱情俱胜，微言思独深。兹游非逸豫，邂逅得良箴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登庐峰二首 其二' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('昨日王德父何昭德回后曝背于庵后大山上甚乐', '何梦桂', '宋代', '碧旻收云兮，秋气肃甭。\n万籁声沉兮，秋日晶荧。\n青山崯崯兮，白石瑛瑛。\n麋鹿跂跂兮出高陵，野鸟活活兮两岑对鸣。\n黄犍湿湿羝群，或讹或寝兮野于坰。\n吾忘吾独兮，吾与禽兽兮为邻。\n违市朝兮不与世撄，利名不入兮宠辱忘惊。\n聊遗吾形兮放吾情，美背曝兮不可以遗君。\n时分吾席坐兮，采樵负苓。\n吾其徜徉乎此山以终吾生兮，其乐无央。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '昨日王德父何昭德回后曝背于庵后大山上甚乐' AND p.poem_author = '何梦桂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过卜克达坂', '弘历', '清代', '常岁迤东猎，迤西此重寻。廿围倏蒇事，二竖待成擒。\n\n缵武惟勤已，运筹更悉心。贞符如卜克，愿即递佳音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过卜克达坂' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('对菊四首 其四', '郑思肖', '宋代', '三径今非昔，多愁老此身。谁知陶靖节，只是晋朝人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '对菊四首 其四' AND p.poem_author = '郑思肖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古五十七首', '释道昌', '宋代', '舌头不出口，三三成九九。\n算到香台还，彼此落人后。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古五十七首' AND p.poem_author = '释道昌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过太清道院有感', '孙承恩', '明代', '竹楼曾为习诗章，卷里犹看墨色光。作者主人半零落，空馀苍翠拂云长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过太清道院有感' AND p.poem_author = '孙承恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('醉归', '陆游', '宋代', '十亩春芜手自犁，瓜牛庐在镜湖西。\n禅心每笑弹棋局，道眼长捐刮膜篦。\n绝食就官分鹤料，无车免客笑鸡栖。\n旗亭酒贱秋风近，夜夜归来醉似泥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '醉归' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('邀凉亭五首', '彭龟年', '宋代', '凉风不肯来，偃蹇如相要。\n悠悠天地间，舍我从谁邀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '邀凉亭五首' AND p.poem_author = '彭龟年';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酒泉子·庭树霜凋', '冯延巳', '唐代', '庭树霜凋，\n一夜愁人窗下睡。\n绣帏风，兰烛焰，梦遥遥。\n\n金笼鹦鹉怨长宵，\n笼畔玉筝弦断。\n陇头云，桃源路，两魂消。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酒泉子·庭树霜凋' AND p.poem_author = '冯延巳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('学宫诸生饮邀予与予野同之二首', '袁说友', '宋代', '少日峨冠英俊场，课余觞饮共徜徉。\n孰知薄宦江湖去，频梦炉亭饼{托扌换饣}香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '学宫诸生饮邀予与予野同之二首' AND p.poem_author = '袁说友';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送刁绎从事自龙舒西赴青城宰', '宋庠', '宋代', '东别群舒国，西踰二剑天。才高邺都檄，政伫武城弦。\n\n莋马征蹄苦，岩鸡瑞羽鲜。离愁知远近，万里到桥边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送刁绎从事自龙舒西赴青城宰' AND p.poem_author = '宋庠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三用韵自警', '童冀', '明代', '诗亡然后春秋作，灾异不独书雨雹。一朝夹谷会强齐，片言立使莱兵却。\n\n当时门人谁好学，陋巷独称颜氏乐。后人往往学术偏，自谓圣贤堪比肩。\n\n董贾犹存二三策，荀扬其然岂其然。易经王弼诗郑玄，春秋何休礼服虔。\n\n东南之美仅竹箭，肃慎楛矢何曾见。千载之下得程朱，梦见圣人犹觌面。\n\n六经自此昭日星，伊洛未觉洙泗远。我生独后此数公，望道未见心忡忡。\n\n秋霜暗添短鬓白，春酒不借衰颜红。忧来中夜恒叹慨，犹幸平生守三戒。\n\n志勤道远力已微，夙兴夜寐心长在。春风花开秋叶飞，岁不待人知不知。\n\n青年幸从君子学，白头庶免小人归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三用韵自警' AND p.poem_author = '童冀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王世赏大参以途间诗六首索和次韵如左 其三 衡阳', '张吉', '明代', '十年前事偶心忆，棹拂衡湘醉始醒。不到先生唫望日，芙蓉秋后为谁青。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王世赏大参以途间诗六首索和次韵如左 其三 衡阳' AND p.poem_author = '张吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头（再用前韵答任令尹）', '向子諲', '宋代', '飘飘任公子，爽气欲横秋。向日携诗过我，知不是凡流。筑室清江西畔，巧占一川佳处，剩士日追游。邀我出门去，柱月上新楼。 \n 烂银盘，从树杪，出云头。好是风流从事，同醉入青州。须信人生如幻，七十古来稀有，销得几狐裘。谁似芗林老，无喜亦无忧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头（再用前韵答任令尹）' AND p.poem_author = '向子諲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻西省赏酴醾芍药戏成小诗奉简泰之侍讲舍人年兄并以丁香橄榄百枚助筵却求残花数枝 其二', '周必大', '宋代', '满架冰肌合碧云，翻阶翠袖映红裙。玉堂只有金沙在，伴直明朝又属君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻西省赏酴醾芍药戏成小诗奉简泰之侍讲舍人年兄并以丁香橄榄百枚助筵却求残花数枝 其二' AND p.poem_author = '周必大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄旧友二首', '宋伯仁', '宋代', '微官宁得似穷儒，挽首逢迎气不舒。\n便是伐薪能煮海，何如烧叶自观书。\n半逢寒雨苕溪酒，一线西风震泽鱼。\n但得此身无系束，江南有地着顽疏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄旧友二首' AND p.poem_author = '宋伯仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绵扇偶吟一首', '苏籀', '宋代', '拏云擘茧写兰亭，洴絖娃宫箑柄成。\n皎洁中规捐月斧，清雄消暍并桃笙。\n玉毫躔内乘鸾女，冰鉴光中墨客卿。\n爱惜御冬充便面，辟寒抚勉燠屯营。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绵扇偶吟一首' AND p.poem_author = '苏籀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('跋张功父通判直阁所惠约斋诗乙藁', '杨万里', '宋代', '句里勤分似，灯前得细尝。孤芳后山种，一瓣放翁香。\n\n苦处霜争涩，臞来鹤校强。不应穷活计，公子也忙忙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '跋张功父通判直阁所惠约斋诗乙藁' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('潮州喜晤温慕柳同年别后却寄三首 其一', '丘逢甲', '清代', '故人今洞主，雄镇古瀛州。白鹿经犹讲，红羊劫未收。\n\n秋城明落照，孤塔枕寒流。独客来天末，相思倚柁楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '潮州喜晤温慕柳同年别后却寄三首 其一' AND p.poem_author = '丘逢甲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又次韵帅初诸前七首', '陈著', '宋代', '三閒老屋坐屏山，梅影横斜细竹斑。\n寡欲自能坚铁脊，长生何必问金丹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又次韵帅初诸前七首' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白云安尉出戍至夔州', '冯时行', '宋代', '戍鼓黄云外，征夫白帝东。\n风林行啸虎，雨夜飒哀鸿。\n路入山光静，村含晚色空。\n岚烟欺眼力，不见鹿皮翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白云安尉出戍至夔州' AND p.poem_author = '冯时行';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大水叹五首 其一', '沈树本', '清代', '戊子春徂夏，时若雨旸风。种苗行方遍，铺田渐芃芃。\n\n农夫顾之喜，谓今岁其丰。如何欻遘患，霪雨无终穷。\n\n西吴百万亩，化作鼋鼍宫。灾殃其数然，讵敢怨苍穹。\n\n所嗟民无食，何以及岁终。作诗维告哀，声比寒号虫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大水叹五首 其一' AND p.poem_author = '沈树本';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('民谣', '尤侗', '明代', '急丈田，长洲县。田几何，百馀万。奉部文，一年限。朝廷丈田除浮粮，浮粮若除须补亡。\n\n下跨河水上山冈，菜畦菱荡都抵当。插旗四角周中央，男奔女走群慞惶。\n\n上官督县令，县令责里正。里正不识弓尺寸，转雇狙狯代持筹，长短方圆一手定。\n\n一手定，一手更。私田缩，官田盈。移重挪轻无不有，田主瞠眼不敢争。\n\n县家覆丈岂能遍，但取溢额可考成。急丈田，限一年。\n\n官经票，吏索钱。官田未见增什一，民钱已闻费万千。\n\n君不见一县图书七百四十一，日造黄册堆积高于山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '民谣' AND p.poem_author = '尤侗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('石州慢 蜀中红叶李沪上玉兰已放，帝乡亦日煖，而扬州地气江梅犹在', '石任之', '当代', '浅梦非真，娥绿未颦，楼外谁折。薄寒比玉堪磨，一尾鱼衔香没。\n\n当时京洛，银锭桥侧微澜，嫣嫣几豆能生蝶。初学制新词，是何年三月。\n\n人曰。隔江清泚，开到辛夷，送梅仙阙。冷淡东风，慢耦扬州丘垤。\n\n测花昨夜，花深乍破三蠡，已添愁海飞红孽。未呕绪吴蚕，食春阴如叶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '石州慢 蜀中红叶李沪上玉兰已放，帝乡亦日煖，而扬州地气江梅犹在' AND p.poem_author = '石任之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('仆射庙', '吴廷铨', '近代', '汉代纯臣史册彰，胥山仆射两名扬。马封兽石埋千古，鸡卜豚蹄荐一方。\n\n屋故藤萝绿画壁，德高墓庙不沧桑。乐神剧罢人归后，雀噪鸦栖半夕阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '仆射庙' AND p.poem_author = '吴廷铨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塞上杂诗二首 其二', '李梦阳', '明代', '胡儿追野马，迸蹄若惊鸿。一马带双箭，堕我边壕中。\n\n敢望不敢近，踟蹰各按弓。抽身复北去，天寒沙碛风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塞上杂诗二首 其二' AND p.poem_author = '李梦阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('载月用旧作秋夜泛湖赋唐文皇爽气澄兰沼得诗五首原韵 其二', '弘历', '清代', '俯仰仲夏徂，上伏又云既。山霭夕送凉，谁云秋尚未。\n\n际此银蟾辉，所遇欣为贵。谢赋兴邈然，那染雕虫气。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '载月用旧作秋夜泛湖赋唐文皇爽气澄兰沼得诗五首原韵 其二' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三洲岩闻虎', '陈献章', '明代', '草动云飞十里风，三洲岩下吼声雄。先生自对山灵笑，不道前身是远公。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三洲岩闻虎' AND p.poem_author = '陈献章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出郭', '潘遵祁', '清代', '出郭刚乘雨后天，芳林如画草如烟。波痕乍长三篙活，日影微烘一笠圆。\n\n世事不来寻老圃，人生只合泛轻船。含情独向春江立，流尽桃花望渺然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出郭' AND p.poem_author = '潘遵祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵子椿五首 其五', '李之仪', '宋代', '附见谁为邹湛，奖成无复山涛。岂敢遽名此地，不如且醉归舠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵子椿五首 其五' AND p.poem_author = '李之仪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('钟山法云彦上人留中餐罢游草堂寺', '贺铸', '宋代', '弭楫秦淮尾，登临殊兴回。难销蔬饭饱，更过草堂来。\n\n日转岩扉暝，风披蕙帐开。吾非海盐令，猿鸟莫相猜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '钟山法云彦上人留中餐罢游草堂寺' AND p.poem_author = '贺铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴姬曲五首', '戴表元', '宋代', '吴姬歌，歌声宛宛歌情多。\n当尊一阕且呼酒，酒遍余声无奈何。\n春风颠狂亦如我，坐见花外遥湖波。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴姬曲五首' AND p.poem_author = '戴表元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('嘲解十首 其四', '王迈', '宋代', '孤士每蒙丞相嗔，人心不泯是非真。瓘为苦语攻奸蔡，铨出危言忤老秦。\n\n此事古来曾有样，如今天下几无人。西山夫子深穷理，能以逢干作保身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '嘲解十首 其四' AND p.poem_author = '王迈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和杨节使登径山', '释元肇', '宋代', '阊阖门西湖水临，深深院落见春心。梨花风弄影来去，燕子日长谈古今。\n\n起早每缘朝玉阙，归迟多是宴琼林。肯将吹竹弹丝耳，来听重云钟鼓音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和杨节使登径山' AND p.poem_author = '释元肇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游石陵谒倪文卿先生墓', '朱兴悌', '清代', '草莽书生依宋土，北望中原思艺祖。宫车泪洒牟驼冈，雪耻不忘缚金虏。\n\n袖中拟上中兴书，满壁张图森部伍。布衣老不挂朝缨，慷慨大声咤广武。\n\n天涯沦落莽萧萧，谁其知者陈同甫。石陵原上高士坟，伫立苍茫为怀古。\n\n风流消歇七百年，万树秋声啼杜宇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游石陵谒倪文卿先生墓' AND p.poem_author = '朱兴悌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('热河三十六景诗 其十一 西岭晨霞', '玄烨', '清代', '雨歇更阑斗柄东，成霞聚散四方风。时光岂在凌云句，寡过清谈宜守中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '热河三十六景诗 其十一 西岭晨霞' AND p.poem_author = '玄烨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泉州贡院举梁八咏 其七', '真德秀', '宋代', '簪橐联辉三大老，节旄相映四贤侯。作成后进须先进，引领时流作胜流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泉州贡院举梁八咏 其七' AND p.poem_author = '真德秀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观袁修侍郎涨新池', '卢纶', '唐代', '引水香山近，穿云复绕林。才闻篱外响，已觉石边深。 \n 满处侵苔色，澄来见柳阴。微风月明夜，知有五湖心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观袁修侍郎涨新池' AND p.poem_author = '卢纶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谒孟庙', '韩日缵', '明代', '古庙前朝创，遗言圣代崇。七篇开众瞆，绝系绍□蒙。\n\n教岂三迁后，泽仍五世中。荆榛谁自辟，环辙□终穷。\n\n道性尊尧行，閒邪媲禹功。人禽分夜气，行尼信苍穹。\n\n顾讵安诸子，谈应藐七雄。蹊间宁竟□，□路若为通。\n\n五百期虚应，千秋祀独隆。低回俎豆□，馀铎振松风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谒孟庙' AND p.poem_author = '韩日缵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋兴用宋推府韵 其二', '郑真', '明代', '风生濠上碧流湍，日照金鸡五色翰。枫岸晴看霜锦烂，菊篱香挹露珠寒。\n\n附书每欲随玄雁，绾诰何因识紫鸾。沧海东归怜骥子，吴江应已过淮安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋兴用宋推府韵 其二' AND p.poem_author = '郑真';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪湖八景次瞿宗吉韵 其三 巢古雪阁', '凌云翰', '元代', '人间蓬岛是孤山，高阁清虚类广寒。木处恐颠从此稳，僧居疑小较来宽。\n\n瑶花琪树绿边绕，玉宇琼楼向上安。里外湖光明似镜，有梅花处好凭阑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪湖八景次瞿宗吉韵 其三 巢古雪阁' AND p.poem_author = '凌云翰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉次徽王韵赠毕亚卿豫荆凶荒黎民阻饥朝廷简命亚卿毕公兼都宪来膺赈恤重任王有诗嘉赠因次韵少申颂期之意', '林光', '明代', '中原万姓岂愁饥，天遣公来任抚绥。在处流亡俱引领，会看愁苦变雍熙。\n\n甘霖终慰群生望，草芥能忘一日知。野史大书消几句，汉江那用更沉碑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉次徽王韵赠毕亚卿豫荆凶荒黎民阻饥朝廷简命亚卿毕公兼都宪来膺赈恤重任王有诗嘉赠因次韵少申颂期之意' AND p.poem_author = '林光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酹江月/念奴娇', '赵师侠', '宋代', '韶华婉娩，正和风迟日，喧妍清昼。紫燕黄鹂争巧语，催老芬芳花柳。灼灼花王，盈盈娇艳，独殿春光後。鹤翎初拆，露沾香沁珠溜。遥想京洛风流，姚黄魏紫，间绿如铺纤。小盖低回雕栏曲，车马纷驰圆囿。天雨曼珠，玉盘金束，占得声名久。留连朝暮，赏心不压芳酒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酹江月/念奴娇' AND p.poem_author = '赵师侠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('续古二十九首', '陈陶', '唐代', '大尧登宝位，麟凤焕宸居。海曲沾恩泽，还生比目鱼。 \n 生值揖逊历，长歌东南春。钓鳌年三十，未见天子巡。 \n 轩辕承化日，群凤戏池台。大朴衰丧后，仲尼生不来。 \n 大道归孟门，萧兰日争长。想得巢居时，碧江应无浪。 \n 矻矻蓬舍下，慕君麒麟阁。笑杀王子乔，寥天乘白鹤。 \n 杳杳巫峡云，悠悠汉江水。愁杀几少年，春风相忆地。 \n 吴洲采芳客，桂棹木兰船。日晚欲有寄，裴回春风前。 \n 仙家风景晏，浮世年华速。邂逅汉武时，蟠桃海东熟。 \n 南国珊瑚树，好裁天马鞭。鱼龙不解语，海曲空蝉娟。 \n 周穆恣游幸，横天驱八龙。宁知泰山下，日日望登封。 \n 秦国饶罗网，中原绝麟凤。万乘巡海回，鲍鱼空相送。 \n 秦家无庙略，遮虏续长城。万姓陇头死，中原荆棘生。 \n 秦作东海桥，中州鬼辛苦。纵得跨蓬莱，群仙亦飞去。 \n 隋炀弃中国，龙舟巡海涯。春风广陵苑，不见秦宫花。 \n 范子相句践，灭吴成大勋。虽然五湖去，终愧磻溪云。 \n 麟凤识翔蛰，圣贤明卷舒。哀哉嵇叔夜，智不及鶢鶋。 \n 战地三尺骨，将军一身贵。自古若吊冤，落花少于泪。 \n 楚国千里旱，土龙日已多。九谷竟枯死，好云闲嵯峨。 \n 汉家三殿色，恩泽若飘风。今日黄金屋，明朝长信宫。 \n 南园杏花发，北渚梅花落。吴女妒西施，容华日消铄。 \n 山鸡理毛羽，自言胜乌鸢。一朝逢鸑鷟，羞死南海边。 \n 秦家卷衣贵，本是倡家子。金殿一承恩，貂蝉满乡里。 \n 魏宫薛家女，秀色倾三殿。武帝鼎湖归，一身似秋扇。 \n 婵娟越机里，织得双栖凤。慰此殊世花，金梭忽停弄。 \n 学古三十载，犹依白云居。每览班超传，令人慵读书。 \n 雄剑久濩落，夜吟秋风起。不是懒为龙，此非延平水。 \n 朝为杨柳色，暮作芙蓉好。春风若有情，江山相逐老。 \n 景龙临太极，五凤当庭舞。谁信壁间梭，升天作云雨。 \n 曾梦诸侯笑，康囚议脱枷。千根池底藕，一朵火中花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '续古二十九首' AND p.poem_author = '陈陶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送鲁有开中大知洺州次子瞻韵', '苏辙', '宋代', '仲连虽不仕，而非绮与园。\n逡巡笑谈间，屡解战斗繁。\n子敬识二孙，长揖鼓鼙喧。\n意气感周郎，振策起江村。\n二贤继英风，千载为高门。\n曾孙事仁祖，风义夙所敦。\n台阁余故事，父老称遗言。\n白发识公子，十载友元昆。\n婆娑久不试，俯仰色愈温。\n五马忽嘶鸣，朱轮夹征轩。\n旌旄隔河至，部曲几人存。\n铜虎不可留，刍狗行当燔。\n秋潦决河防，遗黎化惊魂。\n忧心念千里，何暇把一樽。\n西城叩门别，南风吹帽翻。\n嗟我限出竭，未敢逾短垣。\n新晴水尚壮，想见民惊奔。\n安得万丈堤，止此百里浑。\n姑尔救一境，谁当理其源。\n百闻贵一见，尺书为我论。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送鲁有开中大知洺州次子瞻韵' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('老去', '郑孝胥', '清代', '平生无他长，不受世束缚。贫贱与富贵，殊未改其乐。\n\n造物欲穷之，相戏亦颇虐。守边向南荒，建国就朔漠。\n\n三年气难挫，一举若孤鹤。蚁封水曲间，驰骋等寥廓。\n\n何曾顾鸿鹄，况乃语燕雀。惟老不可避，俯首羁朽索。\n\n老去终未甘，无使怀抱恶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '老去' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏苜蓿', '梅尧臣', '宋代', '苜蓿来西或，蒲萄亦既随。\n胡人初未惜，汉使始能持。\n宛马当求日，离宫旧种时。\n黄花今自发，撩乱牧牛陂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏苜蓿' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和答余以贞佥宪见寄韵言怀二首 其二', '黄仲昭', '明代', '误含雨意出山来，枯槁难将一滴培。便欲陈情乞骸骨，荷锄归理旧田垓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和答余以贞佥宪见寄韵言怀二首 其二' AND p.poem_author = '黄仲昭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送陈瑞卿之临清兵备', '王鏊', '明代', '北来作镇重才猷，齐鲁权兼坐上游。官职朝廷犹耳目，地形中国是咽喉。\n\n搴帷尚记来时面，借箸应烦席上筹。春入四郊狐兔灭，月明还上庾公楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送陈瑞卿之临清兵备' AND p.poem_author = '王鏊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('门前柳', '姜特立', '宋代', '一桁门前柳，亭亭翠插空。\n悲秋宋玉宅，学舞楚王宫。\n夜映楼台月，朝牵鞭荇风。\n多情二三月，乱絮扑房栊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '门前柳' AND p.poem_author = '姜特立';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送孙积中同年赴任陕府', '张舜民', '宋代', '劭农使者岭南回，上佐题舆陕道开。河水已随浮世去，条山应喜故人来。\n\n雨摧苦笋催羹臛，风飐樱桃落酒杯。我欲函关更西去，不知令尹肯相陪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送孙积中同年赴任陕府' AND p.poem_author = '张舜民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绍兴以后祀五方帝六十首', '佚名', '隋代', '辰牡孔硕，奉牲以告。\n秘祝非祈，丰年宜报。\n至意昭良，交乎神明。\n降福穰穰，用燕群生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绍兴以后祀五方帝六十首' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬至展先母罗太安人漕坪陇有感 其二', '邹元标', '明代', '矗矗云山壮，阴阴草木稠。昔年曾瑞鹤，此地见眠牛。\n\n地胜疑天意，人和岂力谋。先慈多隐德，佳气正千秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬至展先母罗太安人漕坪陇有感 其二' AND p.poem_author = '邹元标';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和钝庵岁暮杂感 其一', '宋实颖', '清代', '年少才名也自雄，老来城北半飘蓬。闭门种菜浑闲事，输与人间霹雳弓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和钝庵岁暮杂感 其一' AND p.poem_author = '宋实颖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同黄季主金伯韶两生过伯符宅时傅明府先在坐', '胡应麟', '明代', '残雪初回万井春，一尊官舍暮留宾。抽毫太液多名士，击筑长安尽酒人。\n\n惨淡骥心逢处老，飞扬龙剑合来神。盘中苜蓿犹堪饱，莫放仙凫去紫宸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同黄季主金伯韶两生过伯符宅时傅明府先在坐' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病中午后登山閒步遥见园亭有以帟张栏处久而', '岳珂', '宋代', '满山桃李闹红霞，曾约香山白鹿车。\n堪笑东风欺病客，搀先且到别人家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病中午后登山閒步遥见园亭有以帟张栏处久而' AND p.poem_author = '岳珂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送参寥师归钱塘', '苏过', '宋代', '我先大夫东南游，六年云水穷抉搜。吹嘘人物到方外，伯乐未忍轻骅骝。\n\n老师一见心相投，气味要是同薰莸。尘埃岂解埋珠玉，自有宝气干斗牛。\n\n作诗为文尽馀事，劲节凛凛横九秋。俗子欲交辄掉头，我友天下第一流。\n\n虽遭谤骂不少避，年世久已同浮沤。我昨南来自炎州，师亦方解钟仪囚。\n\n握手流涕古汴沟，生死骨肉我未瘳。众人见弃谁相休，累然独处空山幽。\n\n忽闻剥啄师唤我，洒扫茅堂三日留。行行吴越有旧隐，明年当泛西湖舟。\n\n赠言乃是朋友义，敢效儿女空绸缪。夜光明月宜自收，虎文豹缬非身谋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送参寥师归钱塘' AND p.poem_author = '苏过';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重阳二首 其二', '陶安', '明代', '客居正有大龙山，又有黄花古市阛。九日何缘无节意，一身犹自远乡关。\n\n亲交对景应相忆，僚佐离家尽不闲。莫道明年谁尚健，茱萸已笑鬓毛斑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重阳二首 其二' AND p.poem_author = '陶安';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('淮上舟夜', '邵咏', '清代', '淮南雨晴夜，初夏似新秋。月色兼凉起，河声入梦流。\n\n艰难依蹇仆，飘泊信孤舟。应识回家日，惊心念旧游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '淮上舟夜' AND p.poem_author = '邵咏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过严子陵钓台二首 其二', '苏葵', '明代', '不从草昧助诛新，争肯时平拜谏臣。天上功名非强厌，山中情性本来真。\n\n可怜汉业频更主，只有严滩未属人。岁岁钓台烟雨外，白鸥无恙水潾潾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过严子陵钓台二首 其二' AND p.poem_author = '苏葵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居诗三首呈诸道侣 其三', '丁鹤年', '元代', '懒散形骸不自持，黄冠聊束鬓边丝。频来猿鹤浑相识，久混龙蛇竟不知。\n\n养拙最宜情澹泊，全生深藉德支离。看云本自忘饥渴，况有冰泉与石芝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居诗三首呈诸道侣 其三' AND p.poem_author = '丁鹤年';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十一月二十六日南至天色佳甚', '孙应时', '宋代', '天心应喜一阳来，万里寒阴晓自开。\n消息早传从嶰竹，发生先合到江梅。\n遥瞻双阙吴云瑞，正想三宫舞寿杯。\n草森微情共时节。思亲南望独徘徊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十一月二十六日南至天色佳甚' AND p.poem_author = '孙应时';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄潘上林二首 其一', '胡应麟', '明代', '廿载长安陌，君能忆酒狂。片鸿来庾岭，双鲤到钱塘。\n\n赋草新藜阁，诗篇旧柏梁。春明退朝晚，掷果遍奚囊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄潘上林二首 其一' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再用前韵四首', '郭印', '宋代', '残日衔西岭，轻烟幕晚村。\n朝宗奔众水，设险壮重门。\n恍惚襄王梦，凄凉蜀相魂。\n山川长不改，人意自朝昏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再用前韵四首' AND p.poem_author = '郭印';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿段处士', '苏仲', '明代', '传得人间不老方，朗吟风景是行藏。碧桃洞里寻幽迹，翠柳阴中卧石床。\n\n放鹤有时随杖屦，傍花无日不壶觞。崆峒莫访长生诀，静处须知自履常。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿段处士' AND p.poem_author = '苏仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀旧', '陆游', '宋代', '青城之西溪谷深，道翁巢居独鼓琴。\n一杯松留我宿，夜半虎啸风生林。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀旧' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赋赠东山子祷雨端阳有应三首 其三', '张煌言', '明代', '「繁露」春秋说大雩，谁怜五日欲无襦！杯中似有栾巴酒，洒作千家摄水符。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赋赠东山子祷雨端阳有应三首 其三' AND p.poem_author = '张煌言';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上元即景灯词八首 其五', '弘历', '清代', '鸾翔鹤舞势毰毸，星月光中雪色皑。归帐成诗诸内翰，何如张说看灯回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上元即景灯词八首 其五' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿彭詹事先生五十次诸翰林韵', '李东阳', '明代', '彭铿家世本神仙，异代长生复此筵。朝罢文鹓班始散，宴回青鸟信方传。\n\n东宫地近恩兼渥，南陆天长景正延。记取八千从半百，是公重到玉堂年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿彭詹事先生五十次诸翰林韵' AND p.poem_author = '李东阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和同官问耳疾六首', '曹勋', '宋代', '中原困戎马，久欲谒明时。\n文轨虽非昔，英雄似未知。\n寰中无好汉，帐下得猪儿。\n慨念燕然勒，终还吉甫诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和同官问耳疾六首' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大湖于役 其一', '张鳦生', '近代', '剑津振臂奋偏师，但见如风铁骑驰。谷裂岩崩惊虎豹，云翻雷怒走龙蛇。\n\n骨骸争为山河碎，姓字无求宇宙垂。战罢玄黄浑似梦，屠鲸终数汉家儿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大湖于役 其一' AND p.poem_author = '张鳦生';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('牡丹', '梅尧臣', '宋代', '洛阳牡丹名品多，自谓天下无能过。及来江南花亦好，绛紫浅红如舞娥。\n\n竹阴水照增颜色，春服帖妥裁轻罗。时结游朋去寻玩，香吹酒面生红波。\n\n粉英不忿付狂蝶，白发强插成悲歌。明年更开余已去，风雨吹残可奈何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '牡丹' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉次柏轩先生韵为梅所徵君寿', '林弼', '明代', '忆我昔日游吴东，陈迹曾访孤山翁。梅花千树湖水曲，茅堂半亩梅花中。\n\n别来岁月几流易，一见梅花兴无极。东山东畔西湖西，千载清风只如一。\n\n不须此地感今昨，且向南枝观复剥。野桥石出水未生，江路云凝雪初阁。\n\n主人自是神仙者，藜杖葛巾花树下。寒英疏映霜菊明，老干斜依风竹亚。\n\n天生嘉植真瑰奇，古来幽士多爱之。今人已追古人躅，后人行复今人追。\n\n梅花于人元耐久，百年对花当对酒。愿倾北斗为君觞，更指东山祝君寿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉次柏轩先生韵为梅所徵君寿' AND p.poem_author = '林弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('将往琼南口占别司香者 其三', '屈大均', '明代', '花田昔作花农去，香市今成香估来。黎女定多油速好，金钱数数笑颜开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将往琼南口占别司香者 其三' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同正思叔重发潭溪度梅岭用前韵', '程洵', '宋代', '山行已凄迷，而况步脩岭。飞仙不可见，谁复抚我顶。\n\n怀人云峤长，倦憩石磴冷。樵斧忽丁丁，弥觉清昼永。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同正思叔重发潭溪度梅岭用前韵' AND p.poem_author = '程洵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送人上京', '揭祐民', '元代', '天上吟仙笑相觅，松间坐客饭青精。真游不知白日晚，身世相与浮云轻。\n\n冥冥落花啼鸟静，窅窅风磴寒泉鸣。丈夫邂逅志万里，沧浪水清宜濯缨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送人上京' AND p.poem_author = '揭祐民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长相思 其一 在郡寓作', '洪炳文', '清代', '订归期。误归期。一片乡心托子规。侬情人不知。\n\n柳如眉。月如眉。怪底天涯鲤信迟。光阴梅熟时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长相思 其一 在郡寓作' AND p.poem_author = '洪炳文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送人入蜀', '林鸿', '明代', '把酒长歌蜀道行，高堂千里见君情。微霜半落青枫树，曙月平临白帝城。\n\n挂席不离江雁影，沾衣多向峡猿声。锦城莫道无知己，何限居人识马卿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送人入蜀' AND p.poem_author = '林鸿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日病中咏怀诗二十一章 其八', '姚燮', '清代', '散漫不可收，收之等一粟。飞埃如太山，谁谓天地局？\n\n嗟余所见微，得蠡遂矜足。英英元圃田，种有万仞玉。\n\n其气云吉祥，随风化春绿。所酝由寸几，能使大象缛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日病中咏怀诗二十一章 其八' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送李莽之制干东归探韵得今字', '度正', '宋代', '万卷胸中贮古今，西游蜀道手扪参。\n宝彝残刻窥心画，清庙遗音振学林。\n雅行琼瑰珠慰我，每陪樽俎定论心。\n飘飘衣袂青云去，伫立东风听惠音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送李莽之制干东归探韵得今字' AND p.poem_author = '度正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨不止', '顾清', '明代', '细雨久不止，江皋泥渐深。出门妨散步，隐几独长吟。\n\n柳重墙头压，苔添石面侵。烟云方满眼，花鸟莫关心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨不止' AND p.poem_author = '顾清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题石勒参佛图澄手卷六首 其四', '叶颙', '元代', '推恩忘怨沤麻池，便是刘郎就缚时。成败当年人尽识，未应惟有一僧知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题石勒参佛图澄手卷六首 其四' AND p.poem_author = '叶颙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送程步虞监税', '李流谦', '宋代', '吾来真漫尔，识面喜周旋。\n两月连墙住，孤帆别袂牵。\n人生同宇宙，官学各风烟。\n把酒知何日，临流一惘然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送程步虞监税' AND p.poem_author = '李流谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晓晴 其二', '白玉蟾', '宋代', '月落松方暗，花蜚鸟正啼。青山春窈窕，碧草晓凄迷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晓晴 其二' AND p.poem_author = '白玉蟾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荅杨奉礼', '韦应物', '唐代', '多病守山郡，自得接嘉宾。不见三四日，旷若十馀旬。\n\n临觞独无味，对榻已生尘。一咏舟中作，洒雪忽惊新。\n\n烟波见栖旅，景物具昭陈。秋塘唯落叶，野寺不逢人。\n\n白事廷吏简，闲居文墨亲。高天池阁静，寒菊霜露频。\n\n应当整孤棹，归来展殷勤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荅杨奉礼' AND p.poem_author = '韦应物';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('横逆自广三绝 其三', '陈淳', '宋代', '仁人方寸万机空，片逆何能介此中。视尔恰如风动竹，在予安有竹嫌风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '横逆自广三绝 其三' AND p.poem_author = '陈淳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('立春 其四', '虞俦', '宋代', '腊雪初消柳眼寒，春风才入酒杯宽。一年佳节知多少，屈指从今是履端。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '立春 其四' AND p.poem_author = '虞俦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和徐之才喜雨', '冯山', '宋代', '悯雨何须事祷祈，霈然未足便晴晖。润通垄亩麦禾起，香遍园林樱笋肥。\n\n浮藻水生鱼聚戏，落花泥熟燕交飞。民谣已洽丰年望，惟恐使车将北归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和徐之才喜雨' AND p.poem_author = '冯山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('范参政自建康得资政宫祠六诗寄呈', '赵蕃', '宋代', '细思不是乞身难，政为贫贤不放閒。\n奏疏比闻频叩阙，诏恩今见许还山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '范参政自建康得资政宫祠六诗寄呈' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答杜相公惠诗', '欧阳修', '宋代', '药苗本是山家味，茶具偏於野客宜。\n敢以微诚将薄物，少资清兴入新诗。\n言无俗韵精而劲，笔有神锋老更奇。\n二宝收藏传百世，岂惟荣耀托当时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答杜相公惠诗' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题画', '缪公恩', '清代', '家山好处正依稀，蝴蝶空劳梦里飞。孤负草堂春树绿，落花啼鸟未曾归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题画' AND p.poem_author = '缪公恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('滩上人家', '邓云霄', '明代', '鸟道云生石，人家水绕门。滩淙时乱听，鸡犬不闻喧。\n\n沙蜮窥渔网，山魈啸猎原。畏途逢九折，归思逐波翻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '滩上人家' AND p.poem_author = '邓云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉和鲁望白鸥诗', '皮日休', '唐代', '雪羽䙰褷半惹泥，海云深处旧巢迷。池无飞浪争教舞，洲少轻沙若遣栖。\n\n烟外失群惭雁鹜，波中得志羡凫鹥。主人恩重真难遇，莫为心孤忆旧溪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉和鲁望白鸥诗' AND p.poem_author = '皮日休';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七夕咏璇玑图', '屈大均', '明代', '佳人织锦按河图，天上璇玑得似无。文字能令琴瑟好，风流悔使蕙兰孤。\n\n牵牛此夕逢天女，白兔他家忆故夫。手爪如君皆巧绝，更谁山上采蘼芜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七夕咏璇玑图' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('《西湖杂感》二十首 其十九', '钱谦益', '明代', '东风依旧起青蘋，不为红梅浣北尘。鼓箧儒生陈玉历，开堂禅子祝金轮。\n\n青衣苦效侏离语，红粉欣看回鹘人。他日西湖志风土，故应独少宋遗民。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '《西湖杂感》二十首 其十九' AND p.poem_author = '钱谦益';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三月晦日偶题', '秦观', '宋代', '节物相催各自新，痴心儿女挽留春。\n芳菲歇去何须恨，夏木阴阴正可人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三月晦日偶题' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('间情四首 其四', '吴敬梓', '清代', '香熏透骨有谁知，谪向尘凡冰雪姿。昼永春残人乍别，态浓意远泪偷垂。\n\n曾闻名士多寥落，何事佳人亦仳离。安得与卿登玉版，大罗天上看书碑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '间情四首 其四' AND p.poem_author = '吴敬梓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄张子直 其二', '彭汝砺', '宋代', '性质迂回趣向卑，此身敢望圣门归。趋时已愧雕虫陋，学古还忧画虎非。\n\n材近蓬蒿难自立，目无松柏竟谁依。重嗟踪迹匏瓜系，翻羡苍蝇附尾飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄张子直 其二' AND p.poem_author = '彭汝砺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('武昌春色', '韩元吉', '宋代', '樊山宫殿已成陈，烟雨阴晴到处春。\n花柳不知兴废事，隔江相倚斗时亲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '武昌春色' AND p.poem_author = '韩元吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('子夜四时歌 春歌 二', '萧衍', '南北朝', '兰叶始满地。\n梅花已落枝。\n持此可怜意。\n摘以寄心知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '子夜四时歌 春歌 二' AND p.poem_author = '萧衍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同马水部蒋农部吴山晚眺', '游朴', '明代', '隔江遥送夕阳舂，并马吴山第一峰。东挹扶桑沧海接，西招天竺翠微重。\n\n城鸦渐满来时路，野鹤空留去后踪。莫以登临生感慨，芳尊乍可破尘容。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同马水部蒋农部吴山晚眺' AND p.poem_author = '游朴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂剧·感天动地窦娥冤', '关汉卿', '元代', '楔子\n\n（卜儿蔡婆上，诗云）花有重开日，人无再少年。不须长富贵，安乐是神仙。老身蔡婆婆是也。楚州人氏，嫡亲三口儿家属。不幸夫主亡逝已过，止有一个孩儿，年长八岁。俺娘儿两个，过其日月。家中颇有些钱财。这里一个窦秀才，从去年问我借了二十两银子，如今本利该银四十两。我数次索取，那窦秀才只说贫难，没得还我。他有一个女儿，今年七岁，生得可喜，长得可爱。我有心看上他，与我家做个媳妇，就准了这四十两银子，岂不两得其便！他说今日好日辰，亲送女儿到我家来。老身且不索钱去，专在家中等候。这早晚窦秀才敢待来也。（冲末扮窦天章，引正里扮端云上，诗云）读尽缥缃万卷书，可怜贫煞马相如。汉庭一日承恩召，不说当垆说子虚。小生姓窦，名天章，祖贯长安京兆人也。幼习儒业，饱有文章。争夺时运不通，功名未遂。不幸挥家亡化已过，撇下这个女孩儿，小字端云。从三岁上亡了他母亲，如今孩儿七岁了也。小生一贫如洗，流落在这楚州居住。此间一个蔡婆婆，他家广有钱物；小生因无盘缠，曾借了他二十两银子，到今本利该对还他四十两。他数次问小生索取。教我把甚么还他？谁想禁婆婆常常着人来说，要小生女孩儿做他儿媳妇。况如今春榜动，选场开，正特上朝取应，又苦盘缠缺少。小生出于无奈，只得将女孩儿端云送与蔡婆婆做儿媳妇去。（做叹科，云）嗨！这个那里是做媳妇？分明是卖与他一般。就准了他那先借的四十两银子，分外但得些少东西，勾小生应举之费，便也过望了。说话之间，早来到他家门首。婆婆在家么？（卜儿上，云）秀才，请家里坐，老身等候多时也。（做相见科，窦天章云）小生今日一任的将女孩儿送来与婆婆，怎敢说做媳妇，只与婆婆早晚使用。小生日下就要上朝进取功名去，留下女孩儿在此，只望婆婆看觑则个！（卜儿云）这等，你是我亲家了。你本利少我四十两银子，兀的是借钱的文书，还了你；再送与你十两银子做盘缠。亲家，你休嫌轻少。（窦天章做谢科，云）多谢了婆婆！先少你许多银子，都不要我还了，今又送我盘缠，此恩异日必当重报。婆婆，女孩儿早晚呆痴，看小生薄面，看觑女孩儿咱！（卜儿云）亲家，这不消你嘱咐。令爱到我家，就做亲女儿一般看承他，你只管放心的去。（窦天章云）婆婆，端云孩儿该打呵，看小生面则骂几句；当骂呵，则处分几句。孩儿，你也不比在我跟前，我是你亲爷，将就的你。你如今在这里，早晚若顽劣呵，你只讨那打骂吃。儿口乐，我也是出于无奈！（做悲科）（唱）\n\n【仙吕】【赏花时】我也只为尤计营生四壁贫，因此上割舍得亲儿在两处分。从今日远践洛阳尘，又不知归期定准，则落的无语暗消魂。（下）（卜儿云）窦秀才留下他这女孩儿与我做媳妇儿，他一径上朝应举去了。（正旦做悲科，云）爹爹，你直下的撇了我孩儿去也！（卜儿云）媳妇儿，你在我家，我是亲婆，你是亲媳妇，只当自家骨肉一般。你不要啼哭，跟着老身前后执料去来。（同下）\n\n\n第一折\n\n（净扮赛卢医上，诗云）行医有斟酌，下药依《本草》。死的医不活，活的医死了。自家姓卢，人道我一手好医，都叫做赛卢医。在这山阳县南门开着生药局。在城有个蔡婆婆，我问他借了十两银子，本利该还他二十两；数次来讨这银子，我又无的还他。若不来便罢，若来呵，我自有个主意！我且在这药铺中坐下，看有甚么人来。（卜儿上，云）老身蔡婆婆。我一向搬在山阳县居住，尽也静办。自十三年前窦天章秀才留下端云孩儿与我做儿媳妇，改了他小名，唤做窦娥。自成亲之后，不上二年，不想我这孩儿害弱症死了。媳妇儿守寡，又早三个年头，服孝将除了也。我和媳妇儿说知，我往城外赛卢医家索钱去也。（做行科，云）葛过隅头，转过屋角，早来到他家门首。赛卢医在家么？（卢医云）婆婆，家里来。（卜儿云）我这两个银子长远了，你还了我罢。（卢医云）婆婆，我家里无银子，你跟我庄上去取银子还你。（卜儿云）我跟你去。（做行科）（卢医云）来到此处，东也无人，西也无人，这里不下手，等甚么？我随身带的有绳子。兀那婆婆，谁唤你哩？（卜儿云）在那里？（做勒卜儿科。孛老同副净张驴儿冲上，赛卢医慌走下。孛老救卜儿科）（张驴儿云）爹，是个婆婆，争些勒杀了。（孛老云）兀那婆婆，你是那里人氏？姓甚名谁了因甚着这个人将你勒死？（卜儿云）老身姓蔡，在城人氏，止有个寡媳妇儿，相守过日。因为赛卢医少我二十两银子，今日与他取讨；谁想他嫌我到无人去处，要勒死我；赖这银于。若不是遇着老的和哥哥呵，那得老身性命来！（张驴儿云）爹，你听的他说么？他家还有个媳妇哩！救了他性命，他少不得要谢我。不若你要这婆子，我要他媳妇儿，何等两便？你和他说去。（孛老云）兀那婆婆，你无丈夫，我无浑家，你肯与我做个老婆，意下如何？（卜儿云）是何言语！待我回家，多备些钱钞相谢。（张驴儿云）你敢是不肯，故意将钱钞哄我？赛卢医的绳子还在，我仍旧勒死了你罢。（做拿绳科）（卜儿云）哥哥，待我慢慢地寻思咱！（张驴儿云）你寻思些甚么？你随我老子，我便要你媳妇儿。（卜儿背云）我不依他，他又勒杀我。罢、罢、罢，你爷儿两个，随我到家中去来。（同下）（正旦上，云）妾身姓窦，小字端云，祖居楚州人氏。我三岁上亡了母亲，七岁上离了父亲。俺父亲将我嫁与蔡婆婆为儿媳妇，改名窦娥，至十七岁与夫成亲。不幸丈夫亡化，可早三年光景，我今二十岁也。这南门外有个赛卢医，他少俺婆婆银子，本利该二十两，数次索取不还。今日俺婆婆亲自索取去了。窦娥也，\n你这命好苦也呵！（唱）\n\n【仙吕】【点绛唇】满腹闲愁，数年禁受，天知否？天若是知我情由，怕不待和天瘦。\n\n【混江龙】则问那黄昏白昼，两般儿忘餐废寝几时休？大都来昨宵梦里，和着这今日心头。催人泪的是锦烂熳花枝横绣闼，断人肠的是剔团圝月色挂妆楼。长则是急煎煎按不住意中焦，闷沉沉展不彻眉尖皱，越觉的情怀冗冗，心绪悠悠。\n\n（云）似这等忧愁，不知几时是了也呵！（唱）\n\n【油葫芦】莫不是八字儿该载着一世忧？谁似我无尽头！须知道人心不似水长流。我从三岁母亲身亡后，到七岁与父分离久。嫁的个同住人，他可又拔着短筹；撇的俺婆妇每都把空房守，端的个有谁问，有谁瞅？\n\n【天下乐】莫不是前世里烧香不到头，今也波生招祸尤？劝今人早将来世修。我将这婆侍养，我将这服孝守，我言词须应口。\n\n（云）婆婆索钱去了，怎生这早晚不见回来？（卜儿同孛老、张驴儿上）（卜儿云）你爷儿两个且在门首，等我先进去。（张驴儿云）奶奶，你先进去，就说女婿在门首哩。（卜儿见正旦科）（正旦云）奶奶回来了。你吃饭么？（卜儿做哭科，云）孩儿也，你教我怎生说波！（正旦唱）\n\n【一半儿】为甚么泪漫漫不住点儿流？莫不是为索债与人家惹争斗？我这里连忙迎接慌问候，他那里要说缘由。（卜儿云）羞人答答的，教我怎生说波！（正旦唱）则见他一半儿徘徊一半儿丑。\n\n（云）婆婆，你为甚么烦恼啼哭那？（卜儿云）我问赛卢医讨银子去，他赚我到无人去处，行起凶来，要勒死我。亏了一个张老并他儿子张驴儿，救得我性命。那张老就要我招他做丈夫，因这等烦恼。（正旦云）婆婆，这个怕不中么！你再寻思咱：俺家里又不是没有饭吃，没有衣穿，又不是少欠钱债，被人催逼不过；况你年纪高大，六十以外的人，怎生又招丈夫那？（卜儿云）孩儿也，你说的岂不是！但是我的性命全亏他这爷儿两个救的。我也曾说道：待我到家，多将些钱物酬谢你救命之恩。不知他怎生知道我家里有个媳妇儿，道我婆媳妇又没老公，他爷儿两个又没老婆，正是天缘天对。若不随顺他，依旧要勒死我。那时节我就慌张了，莫说自己许了他，连你也许了他。儿也，这也是出于无奈。（正旦云）婆婆，你听我说波。（唱）\n\n【后庭花】避凶神要择好日头，拜家堂要将香火修。梳着个霜雪般白鬏髻，怎将这云霞般锦帕兜？怪不的"女大不中留"。你如今六旬左右，可不道到中年万事休！旧恩爱一笔勾，新夫妻两意投，枉教人笑破口！\n\n（卜儿云）我的性命都是他爷儿两个救的，事到如今，也顾不得别人笑话了。（正旦唱）\n\n【青哥儿】你虽然是得他、得他营救，须不是笋条、笋条年幼，刬的便巧画蛾眉成配偶？想当初你夫主遗留，替你图谋，置下田畴，早晚羹粥，寒暑衣裘。满望你鳏寡孤独，无捱无靠，母子每到白头。公公也，则落得干生受！\n\n（卜儿云）孩儿也，他如今只待过门。喜事匆匆的，教我怎生回得他去？（正旦唱）\n\n【寄生草】你道他匆匆喜，我替你倒细细愁：愁则愁兴阑珊咽不下交欢酒，愁则愁眼昏腾扭不上同心扣，愁则愁意朦胧睡不稳芙蓉褥。你待要笙歌引至画堂前，我道这姻缘敢落在他人后。\n\n（卜儿云）孩儿也，再不要说我了。他爷儿两个都在门首等候，事已至此，不若连你也招了女婿罢！（正旦云）婆婆，你要招你自招，我并然不要女婿。（卜儿云）那个是要女婿的？争奈他爷儿两个自家捱过门来，教我如何是好？（张驴儿云）我们今日招过门去也。帽儿光光，今日做个新郎；袖儿窄窄，今日做个娇客。好女婿，好女婿，不枉了，不枉了。（同孛老入拜科）(正旦做不礼科，云)兀那厮，靠后！（唱）\n\n【赚煞】我想这妇人每休信那男儿口。婆婆也，怕没的贞心儿自守，到今日招着个村老子，领着个半死囚。（张驴儿做嘴脸料，云）你看我爷儿两个这等身段，尽也选得女婿过，你不要错过了好时辰，我和你早些儿拜堂罢。（正旦不礼科，唱）则被你坑杀人燕侣莺俦。婆婆也，你岂不知羞！俺公公撞府冲州，挣扎的铜斗儿家缘百事有。想着俺公公置就，怎忍教张驴儿情受？（张驴儿做扯正旦拜科，正旦推跌科，唱）兀的不是俺没丈夫的妇女下场头！（下）（卜儿云）你老人家不要恼躁。难道你有活命之恩，我岂不思量报你？只是我那媳妇儿气性最不好惹的，既是他不肯招你儿子，教我怎好招你老人家？我如今拚的好酒好饭，养你爷儿两个在家，待我慢慢的劝化俺媳妇儿。待他有个回心转意，再作区处。（张驴儿云）这歪剌骨！便是黄花女儿，刚刚扯的一把，也不消这等使性，平空的推了我一交，我肯干罢！就当面赌个誓与你：我今生今世不要他做老婆，我也不算好男子！（词云）美妇人我见过万千向外，不似这小妮子生得十分惫赖。我救了你老性命死里重生，怎割舍得不肯把肉身陪待？（同下）\n\n\n第二折\n\n（赛卢医上，诗云）小子太医出身，也不知道医死多人。何尝怕人告发，关了一日店门？在城有个蔡家婆子，刚少的他二十两花银，屡屡亲来索取，争些捻断脊筋。也是我一时智短，将他赚到荒村，撞见两个不识姓名男子，一声嚷道："浪荡乾坤，怎敢行凶撒泼，擅自勒死平民！"吓得我丢了绳索，放开脚步飞奔。虽然一夜无事，终觉失精落魂；方知人命关天关地，如何看做壁上灰尘？从今改过行业，要得灭罪修因。将以前医死的性命，一个个都与他一卷超度的经文。小子赛卢医的便是。只为要赖蔡婆婆二十两银子，赚他到荒僻去处，正待勒死他，谁想遇见两个汉子，救了他去。若是再来讨债时节，教我怎生见他？常言道的好："三十六计，走为上计。"喜得我是孤身，又无家小连累；不若收拾了细软行李，打个包儿，悄悄的躲到别处，另做营生，岂不干净！（张驴儿上，云）自家张驴儿。可奈那窦娥百般的不肯随顺我；如今那老婆子害病，我讨服毒药与他吃了，药死那老婆子，这小妮子好歹做我的老婆。（做行科，云）且住，城里人耳目广，口舌多，倘见我讨毒药，可不嚷出事来？我前日看见南门外有个药铺，此处冷静，正好讨药。（做到科，叫云）太医哥哥，我来讨药的。（赛卢医云）你讨甚么药？（张驴儿云）我讨服毒药。（赛卢医云）谁敢合毒药与你？这厮好大胆也！（张驴儿云）你真个不肯与我药么？（赛卢医云）我不与你，你就怎地我？（张驴儿做拖卢云）好呀，前日谋死蔡婆婆的不是你来！你说我不认的你哩，我拖你见官去！（赛卢医做慌科，云）大哥，你放我，有药，有药。（做与药科，张驴儿云）既然有了药，且饶你罢。正是："得放手时须放手，得饶人处且饶人。"（下）（赛卢医云）可不晦气！刚刚讨药的这人，就是救那婆子的。我今日与了他这服毒药去了，以后事发，越越要连累我。趁早几儿关上药铺，到涿州卖老鼠药去也。（下）（卜儿上，做病伏几科）（孛老同张驴儿上，云）老汉自到蔡婆婆家来，本望做个接脚，却被他媳妇坚执不从。那婆婆一向收留俺爷儿两个在家同住，只说"好事不在忙"，等慢慢里劝转他媳妇；谁想那婆婆又害起病来。孩儿，你可曾算我两个的八字，红鸾天喜几时到命哩？（张驴儿云）要看甚么天喜到命！只赌本事，做得去，自去做。（孛老云）孩儿也，蔡婆婆害病好几日了，我与你去问病波。（做见卜儿问科，云）婆婆，你今日病体如何？（卜儿云）我身子十分不快哩。（孛老云）你可想些甚么吃？（卜儿云）我思量些羊肚儿汤吃。（孛老云）孩儿，你对窦娥说，做些羊肚儿汤与婆婆吃。（张驴儿向古门云）窦娥，婆婆想羊肚儿汤吃，快安排将来。（正旦持汤上，云）妾身窦娥是也。有俺婆婆不快，想羊肚汤吃，我亲自安排了与婆婆吃去。婆婆也，我这寡妇人家，凡事也要避些嫌疑，怎好收留那张驴儿父子两个？非亲非眷的，一家儿同住，岂不惹外人谈议？婆婆也，你莫要背地里许了他亲事，连我也累做不清不洁的。我想这妇人心，好难保也呵！（唱）\n\n【南吕】【一枝花】他则待一生鸳帐眠，那里肯半夜空房睡；他本是张郎妇，又做了李郎妻。有一等妇女每相随，并不说家克计，则打听些闲是非；说一会不明白打风的机关，使了些调虚嚣捞龙的见识。\n\n【梁州第七】这一个似卓氏般当垆涤器，这一个似孟光般举案齐眉，说的来藏头盖脚多伶俐！道着难晓，做出才知。旧恩忘却，新爱偏宜；坟头上土脉犹湿，架儿上又换新衣。那里有奔丧处哭倒长城？那里有浣纱时甘投大水？那里有上山来便化顽石？可悲，可耻！妇人家直恁的无仁义。多淫奔，少志气，亏杀前人在那里，更休说百步相随。\n\n（云）婆婆，羊肚儿汤做成了，你吃些儿波。（张驴儿云）等我拿去。（做接尝科，云）这里面少些盐醋，你去取来。（正旦下）（张驴儿放药科）（正旦上，云）这不是盐醋！（张驴儿云）你倾下些。（正旦唱）\n\n【隔尾】你说道少盐欠醋无滋味，加料添椒才脆美。但愿娘亲早痊济，饮羹汤一杯，胜甘露灌体，得一个身子平安倒大来喜。\n\n（孛老云）孩儿，羊肚汤有了不曾？（张驴儿云）汤有了，你拿过去。（孛老将汤云）婆婆，你吃些汤儿。（卜儿云）有累你。（做呕科，云）我如今打呕，不要这汤吃了，你老人家吃罢。（孛老云）这汤特做来与你吃的，便不要吃，也吃一口儿。（卜儿云）我不吃了，你老人家请吃。（孛老吃科）（正旦唱）\n\n【贺新郎】一个道你请吃，一个道婆先吃，这言语听也难听，我可是气也不气！想他家与咱家有甚的亲和戚？怎不记旧日夫妻情意，也曾有百纵千随？婆婆也，你莫不为"黄金浮世宝，白发故人稀"，因此上把旧恩情，全不比新知契？则待要百年同墓穴，那里肯千里送寒衣？\n\n（孛老云）我吃下这汤去，怎觉昏昏沉沉的起来？（做倒科）（卜儿慌科，云）你老人家放精细着，你挣扎着些儿。（做哭科，云）兀的不是死了也！（正旦唱）\n\n【斗虾蟆】空悲戚，没理会，人生死，是轮回。感着这般病疾，值着这般时势，可是风寒暑湿，或是饥饱劳役，各人症候自知。人命关天关地，别人怎生替得？寿数非干今世。相守三朝五夕，说甚一家一计？又无羊酒缎匹，又无花红财礼；把手为活过日，撒手如同休弃。不是窦娥忤逆，生怕旁人论议。不如听咱劝你，认个自家晦气，割舍的一具棺材停置，几件布帛收拾，出了咱家门里，送入他家坟地。这不是你那从小儿年纪指脚的夫妻。我其实不关亲，无半点忄西惶泪。休得要心如醉，意似痴，便这等嗟嗟怨怨，哭哭啼啼。\n\n（张驴儿云）好也啰！你把我老子药死了，更待干罢！（卜儿云）孩儿，这事怎了也？（正旦云）我有甚么药在那里？都是他要盐醋时，自家倾在汤儿里的。（唱）\n\n【隔尾】这厮搬调咱老母收留你，自药死亲爷待要唬吓谁？（张驴儿云）我家的老子，倒说是我做儿子的药死了，人也不信。（做叫科，云）四邻八舍听着：窦娥药杀我家老子哩！（卜儿云）罢么，你不要大惊小怪的，吓杀我也！（张驴儿云）你可怕么？（卜儿云）可知怕哩。（张驴儿云）你要饶么？（卜儿云）可知要饶哩。（张驴儿云）你教窦娥随顺了我，叫我三声嫡嫡亲亲的丈夫，我便饶了他。（卜儿云）孩儿也，你随顺了他罢。（正旦云）婆婆，你怎说这般言语！（唱）我一马难将两鞍鞴，想男儿在日曾两年匹配，却教我改嫁别人，其实做不得。\n\n（张驴儿云）窦娥，你药杀了俺老子，你要官休？要私休？（正旦云）怎生是官休？怎生是私休？（张驴儿云）你要官休呵，拖你到官司，把你三推六问！你这等瘦弱身子，当不过拷打，怕你不招认药死我老子的罪犯！你要私休呵，你早些与我做了老婆，倒也便宜了你。（正旦云）我又不曾药死你老子，情愿和你见官去来。（张驴儿拖正旦、卜儿下）（净扮孤引祗候上，诗云）我做官人胜别人，告状来的要金银。若是上司当刷卷，在家推病不出门。下官楚州太守桃杌是也。今早升厅坐衙，左右，喝撺厢。（祗候幺喝科）（张驴儿拖正旦、卜儿上，云）告状，告状！（祗候云）拿过来。（做跪见，孤亦跪科，云）请起。（祗候云）相公，他是告状的，怎生跪着他？（孤云）你不知道，但来告状的，就是我衣食父母。（祗候幺喝科，孤云）那个是原告？那个是被告？从实说来！（张驴儿云）小人是原告张驴儿，告这媳妇儿，唤做窦娥，合毒药下在羊肚汤儿里，药死了俺的老子。这个唤做蔡婆婆，就是俺的后母。望大人与小人做主咱！（孤云）是那一个下的毒药？（正旦云）不干小妇人事。（卜儿云）也不干老妇人事。（张驴儿云）也不干我事。（孤云）都不是，敢是我下的毒药未？（正旦云）我婆婆也不是他后母，他自姓张，我家姓蔡。我婆婆因为与赛卢医索钱，被他赚到郊外，勒死我婆婆；却得他爷儿两个救了性命。因此我婆婆收留他爷儿两个在家，养膳终身，报他的恩德。谁知他两个倒起不良之心，冒认婆婆做了接脚，要逼勒小妇人做他媳妇。小妇人元是有丈夫的，服孝未满，坚执不从。适值我婆婆患病，着小妇人安排羊肚汤儿吃。不知张驴儿那里讨得毒药在身，接过汤来，只说少些盐醋，支转小妇人，暗地倾下毒药。也是天幸，我婆婆忽然呕吐，不要汤吃。让与他老子吃；才吃的几口便死了，与小妇人并无干涉。只望大人高抬明镜，替小妇人做主咱！（唱）\n\n【牧羊关】大人你明如镜，清似水，照妾身肝胆虚实。那羹本五味俱全，除了外百事不知。他推道尝滋味，吃下去便昏迷。不是妾讼庭上胡支对，大人也，却教我平白地说甚的？\n\n（张驴儿云）大人详情：他自姓蔡，我自姓张。他婆婆不招俺父亲接脚，他养我父子两个在家做甚么？这媳妇儿年纪虽小，极是个赖骨顽皮，不怕打的。（孤云）人是贱虫，不打不招。左右，与我选大棍子打着！（祗候打正旦，三次喷水科）（正旦唱）\n\n【骂玉郎】这无情棍棒教我捱不的。婆婆也，须是你自做下，怨他谁？劝普天下前婚后嫁婆娘每，都看取我这般傍州例。\n\n【感皇恩】呀！是谁人唱叫扬疾，不由我不魄散魂飞。恰消停，才苏醒，又昏迷。捱千般打拷，万种凌逼，一杖下，一道血，一层皮。\n\n【采茶歌】打的我肉都飞，血淋漓，腹中冤枉有谁知！则我这小妇人毒药来从何处也？天那，怎么的覆盆不照太阳晖！\n\n（孤云）你招也不招？（正旦云）委的不是小妇人下毒药来。(孤云）既然不是，你与我打那婆子！（正旦忙云）住、住、住，休打我婆婆。情愿我招了罢，是我药死公公来。（孤云）既然招了，着他画了伏状，将枷来枷上，下在死囚牢里去。到来日判个"斩"字，押付市曹典刑。（卜儿哭科，云）窦娥孩儿，这都是我送了你性命。兀的不痛杀我也！（正旦唱）\n\n【黄锺尾】我做了个衔冤负屈没头鬼，怎肯便放了你好包荒淫漏面贼！想人心不可欺，冤枉事天地知，争到头，竞到底，到如今待怎的？情愿认药杀公公，与了招罪。婆婆也，我若是不死呵，如何救得你？（随祗候押下）\n\n（张驴儿做叩头科，云）谢青天老爷做主！明日杀了窦娥，才与小人的老子报的冤。（卜儿哭科，云）明日市曹中杀窦娥孩儿也，兀的不痛煞我也！（孤云）张驴儿、蔡婆婆，都取保状，着随衙听侯。左右，打散堂鼓，将马来，回私宅去也。（同下）\n\n\n第三折\n\n（外扮监斩官上，云）下官监斩官是也。今日处决犯人，着做公的把住巷口，休放往来人闲走。（净扮公人鼓三通、锣三下科。刽子磨旗、提刀，押正旦带枷上）（刽子云）行动些，行动些，监斩官去法场上多时了！（正旦唱）\n\n【正宫】【端正好】没来由犯王法，不堤防遭刑宪，叫声屈动地惊天！顷刻间游魂先赴森罗殿，怎不将天地也生埋怨？\n\n【滚绣球】有日月朝暮悬，有鬼神掌著生死权，天地也，只合把清浊分辨，可怎生糊突了盗跖、颜渊？为善的受贫穷更命短，造恶的享富贵又寿延。天地也，做得个怕硬欺软，却元来也这般顺水推船。地也，你不分好歹何为地？天也，你错勘贤愚枉做天！哎，只落得两泪涟涟。\n\n（刽子云）快行动些，误了时辰也。（正旦唱）\n\n【倘秀才】则被这枷扭的我左侧右偏，人拥的我前合后偃，我窦娥向哥哥行有句言。（刽子云）你有甚么话说？（正旦唱）前街里去心怀恨，后街里去死无冤，休推辞路远。\n\n（刽子云）你如今到法场上面，有甚么亲眷要见的，可教他过来，见你一面也好。（正旦唱）\n\n【叨叨令】可怜我孤身只影无亲眷，则落的吞声忍气空嗟怨。（刽子云）难道你爷娘家也没的？（正旦云）止有个爹爹，十三年前上朝取应去了，至今杳无音信。（唱）早已是十年多不睹爹爹面。（刽子云）你适才要我往后街里去，是甚么主意？（正旦唱）怕则怕前街里被我婆婆见。（刽子云）你的性命也顾不得，怕他见怎的？（正旦云）俺婆婆若见我披枷带锁赴法场餐刀去呵，（唱）枉将他气杀也么哥，枉将他气杀也么哥！告哥哥，临危好与人行方便。（卜儿哭上科，云）天那，兀的不是我媳妇儿！（刽子云）婆子靠后！（正旦云）既是俺婆婆来了，叫他来，待我嘱付他几句话咱。（刽子云）那婆子，近前来，你媳妇要嘱付你话哩。（卜儿云）孩儿，痛杀我也！（正旦云）婆婆，那张驴儿把毒药放在羊肚儿汤里，实指望药死了你，要霸占我为妻。不想婆婆让与他老子吃，倒把他老子药死了。我怕连累婆婆，屈招了药死公公，今日赴法场典刑。婆婆，此后遇着冬时年节，月一十五，有瀽不了的浆水饭，瀽半碗儿与我吃；烧不了的纸钱，与窦娥烧一陌儿。则是看你死的孩儿面上！（唱）\n\n【快活三】念窦娥葫芦提当罪愆，念窦娥身首不完全，念窦娥从前已往干家缘。婆婆也，你只看窦娥少爷无娘面。\n\n【鲍老儿】念窦娥伏侍婆婆这几年，遇时节将碗凉浆奠；你去那受刑法尸骸上烈些纸钱，只当把你亡化的孩儿荐。（卜儿哭科，云）孩儿放心，这个老身都记得。天那，兀的不痛杀我也！（正旦唱）婆婆也，再也不要啼啼哭哭，烦烦恼恼，怨气冲天。这都是我做窦娥的没时没运，不明不暗，负屈衔冤。（刽子做喝科，云）兀那婆子靠后，时辰到了也。（正旦跪科）（刽子开枷科）（正旦云）窦娥告监斩大人，有一事肯依窦娥，便死而无怨。（监斩官云）你有甚么事？你说。（正旦云）要一领净席，等我窦娥站立；又要丈二白练，挂在旗枪上：若是我窦娥委实冤枉，刀过处头落，一腔热血休半点儿沾在地下，都飞在白练上者。（监斩官云）这个就依你，打甚么不紧。（刽子做取席站科，又取白练挂旗上科）（正旦唱）\n\n【耍孩儿】不是我窦娥罚下这等无头愿，委实的冤情不浅；若没些儿灵圣与世人传，也不见得湛湛青天。我不要半星热血红尘洒，都只在八尺旗枪素练悬。等他四下里皆瞧见，这就是咱苌弘化碧，望帝啼鹃。\n\n（刽子云）你还有甚的说话？此时不对监斩大人说，几时说那？（正旦再跪科，云）大人，如今是三伏天道，若窦娥委实冤枉，身死之后，天降三尺瑞雪，遮掩了窦娥尸首。（监斩官云）这等三伏天道，你便有冲天的怨气，也召不得一片雪来，可不胡说！（正旦唱）\n\n【二煞】你道是暑气暄，不是那下雪天；岂不闻飞霜六月因邹衍？若果有一腔怨气喷如火，定要感的六出冰花滚似绵，免着我尸骸现；要什么素车白马，断送出古陌荒阡！\n\n（正里再跪科，云）大人，我窦娥死的委实冤枉，从今以后，着这楚州亢旱三年！（监斩官云）打嘴！那有这等说话！（正旦唱）\n\n【一煞】你道是天公不可期，人心不可怜，不知皇天也肯从人愿。做甚么三年不见甘霖降？也只为东海曾经孝妇冤，如今轮到你山阳县。这都是官吏每无心正法，使百姓有口难言！\n\n（刽子做磨旗科，云）怎么这一会儿天色阴了也？（内做风科，刽子云）好冷风也！（正旦唱）\n\n【煞尾】浮云为我阴，悲风为我旋，三桩儿誓愿明题遍。（做哭科，云）婆婆也，直等待雪飞六月，亢旱三年呵，（唱）那其间才把你个屈死的冤魂这窦娥显！\n\n（刽子做开刀，正旦倒科）（监斩官惊云）呀，真个下雪了，有这等异事！（刽子云）我也道平日杀人，满地都是鲜血，这个窦娥的血都飞在那丈二白练上，并无半点落地，委实奇怪。（监斩官云）这死罪必有冤枉。早两桩儿应验了，不知亢旱三年的说话，准也不准？且看后来如何。左右，也不必等待雪睛，便与我抬他尸首，还了那蔡婆婆去罢。（众应科，抬尸下）\n\n\n第四折\n\n（窦天章冠带引丑张千、祗从上，诗云）独立空堂思黯然，高峰月出满林烟。非关有事人难睡。自是惊魂夜不眠。老夫窦天章是也。自离了我那端云孩儿，可早十六年光景。老夫自到京师，一举及第，官拜参知政事。只因老夫廉能清正，节操坚刚，谢圣恩可怜，加老夫两淮提刑肃正廉访使之职，随处审囚刷卷，体察滥官污吏，容老夫先斩后奏。老夫一喜一悲：喜呵，老夫身居台省，职掌刑名，势剑金牌，威权万里；悲呵，有端云孩儿，七岁上与了蔡婆婆为儿媳妇。老夫自得官之后，使人往楚州问蔡婆婆家。他邻里街坊道：自当年蔡婆婆不知搬在那里去了，至今音信皆无。老夫为端云孩儿，啼哭的眼目昏花，忧愁的须发斑白。今日来到这淮南地面，不知这楚州为何三年不雨？老夫今在这州厅安歇。张千，说与那州中大小属官，今日免参，明日早见。（张千向古门云）一应大小属官：今日免参，明日早见。（窦天章云）张千，说与那六房吏典：但有合刷照文卷，都将来，待老夫灯下看几宗波。（张千送文卷科）（窦天章云）张千，你与我掌上灯。你每都辛苦了，自去歇息罢。我唤你便来，不唤你休来。（张千点灯，同祗从下）（窦天章云）我将这文卷看几宗咱。"一起犯人窦娥，将毒药致死公公。……"我才看头一宗文卷，就与老夫同姓；这药死公公的罪名，犯在十恶不赦。俺同姓之人，也有不畏法度的。这是问结了文书，不看他罢。我将这文卷压在底下，别看一宗咱。（做打呵欠科，云）不觉的一阵昏沉上来，皆因老夫年纪高大，鞍马劳困之故。待我搭伏定书案，歇息些儿咱。（做睡科。魂旦上，唱）\n\n【双调】【新水令】我每日哭啼啼守住望乡台，急煎煎把仇人等待，慢腾腾昏地里走，足律律旋风中来。则被这雾锁云埋，撺掇的鬼魂快。\n\n（魂旦望科，云）门神户尉不放我进去。我是廉访使窦天章女孩儿。因我屈死，父亲不知，特来托一梦与他咱。（唱）\n\n【沉醉东风】我是那提刑的女孩，须不比现世的妖怪。怎不容我到灯影前，却拦截在门木呈外？（做叫科，云）我那爷爷呵，（唱）枉自有势剑金牌，把俺这屈死三年的腐骨骸，怎脱离无边苦海？（做入见哭科，窦天章亦哭科，云）端云孩儿，你在那里来？（魂旦虚下）（窦天章做醒科，云）好是奇怪也！老夫才合眼去，梦见端云孩儿，恰便似来我跟前一般；如今在那里？我且再看这文卷咱。（魂旦上，做弄灯科）（窦天章云）奇怪，我正要看文卷，怎生这灯忽明忽灭的？张千也睡着了，我自己剔灯咱。（做剔灯，魂旦翻文卷科）（窦天章云）我剔的这灯明了也，再看几宗文卷。一起犯人窦娥，药死公公。……（做疑怪科，云）这一宗文卷，我为头看过，压在文卷底下，怎生又在这上头？这几时问结了的，还压在底下，我别看一宗文卷波。（魂旦再弄灯科）（窦天章云）怎么这灯又是半明半暗的？我再剔这灯咱。（做剔灯，魂旦再翻文卷科。窦天章云）我剔的这灯明了，我另拿一宗文卷看咱。一起犯人窦娥，药死公公。……呸！好是奇怪！我才将这文书分明压在底下，刚剔了这灯，怎生又翻在面上？莫不是楚州后厅里有鬼么？便无鬼呵，这桩事必有冤枉。将这文卷再压在底上，待我另看一宗如何？（魂旦又弄灯科）（窦天章云）怎么这灯又不明了，敢有鬼弄这灯？我再剔一剔去。（做剔灯科，魂旦上，做撞见科，窦天章举剑击桌科，云）呸！我说有鬼！兀那鬼魂：老夫是朝廷钦差，带牌走马肃政廉访使。你向前来，一剑挥之两段。张千，亏你也睡的着！快起来，有鬼，有鬼。兀的不吓杀老夫也！（魂旦唱）\n\n【乔牌儿】则见他疑心儿胡乱猜，听了我这哭声儿转惊骇。哎，你个窦天章直恁的威风大，且受你孩儿窦娥这一拜。\n\n　　〔窦天章云〕兀那鬼魂，你道窦天章是你父亲，受你孩儿窦娥拜，你敢错认了也！我的女儿叫做端云，七岁上与了蔡婆婆为儿媳妇。你是窦娥，名字差了，怎生是我女孩儿？〔魂旦云〕父亲，你将我与了蔡婆婆家，改名做窦娥了也。〔窦天章云〕你便是端云孩儿，我不问你别的，这药死公公，是你不是？〔魂旦云〕是你孩儿来。〔窦天章云〕噤声，你这小妮子，老夫为你啼哭的眼也花了，忧愁的头也白了，你刬地犯了十恶大罪，受了典刑。我今日官居台省，职掌刑名，来此两淮审囚刷卷，体察滥官污吏，你是我亲生之女，老夫将你治不的，怎治他人？我当初将你嫁与他家呵，要你三从四德：三从者，在家从父，出嫁从夫，夫死从子。四德者，事公姑，敬夫主，和妯娌，睦街坊。今三从四德全无，刬地犯了十恶大罪。我窦家三辈无犯法之男，五世无再婚之女，到今日被你辱没祖宗世德，又连累我的清名。你快与其我细吐真情，不要虚言支对，若说的有半厘差错，牒发你城隍祠内，着你永世不得人身，罚在阴山，永为饿鬼。〔魂旦云〕父亲停嗔息怒，暂罢狼虎之威，听你孩儿慢慢的说一遍咱。我三岁上亡了母亲，七岁上离了父亲，你将我送与蔡婆婆做儿媳妇。至十七岁与夫配合，才得两年，不幸儿夫亡化，和俺婆婆守寡。这山阳县南门外有个赛卢医，他少俺婆婆二十两银子。俺婆婆去取讨，被他赚到郊外，要将婆婆勒死，不想撞见张驴儿父子两个，救了俺婆婆性命。那张驴儿知道我家有个守寡的媳妇，便道：“你婆儿媳妇既无丈夫，不若招我父子两个。”俺婆婆初也不肯，那张驴儿道：“你若不肯，我依旧勒死你。”俺婆婆惧怕，不得已含糊许了。只得将他父子两个领到家中，养他过世。有张驴儿数次调戏你女孩儿，我坚执不从。那一日俺婆婆身子不快，想羊肚儿汤吃，你孩儿安排了汤。适值张驴儿父子两个问病，道：“将汤来我尝一尝。”说：“汤便好，只少些盐醋。”赚的我去取盐醋，他就暗地里下了毒药，实指望药杀俺婆婆，要强逼我成亲。不想俺婆婆偶然发呕，不要汤吃，却让与老张吃，随即七窍流血药死了。张驴儿便道：“窦娥药死了俺老子，你要官休要私休？”我便道：“怎生是官休？怎生是私休？”他道：“要官休，告到官司，你与俺老子偿命。若私休，你便与我做老婆。”你孩儿便道：“好马不备双鞍，烈女不更二夫，我至死不与你做媳妇，我请愿和你见官去。”他将你孩儿拖到官中，受尽三推六问，吊拷绷扒，便打死孩儿也不肯认。怎当州官见你孩儿不认，便要拷打俺婆婆；我怕婆婆年老，受刑不起，只得屈认了。因此押赴法场．将我典刑。你孩儿对天发下三桩誓愿：第一桩要丈二白练挂在旗枪上，若系冤枉，刀过头落，一腔热血休滴在地下，都飞在白练上；第二桩，现今三伏天道，下三尺瑞雪，遮掩你孩儿尸首；第三桩，着他楚州大旱三年。果然血飞上白练，六月下雪，三年不雨，都是为你孩儿来。〔诗云〕不告官司只告天，心中怨气口难言，防他老母遭刑宪，情愿无辞认罪愆。三尺琼花骸骨掩，一腔热血练旗悬，岂独霜飞邹衍屈，今朝方表窦娥冤。〔唱〕\n\n【雁儿落】你看这文卷曾道来不道来，则我这冤枉要忍耐如何耐？我不肯顺他人，倒着我赴法场；我不肯辱祖上，倒把我残生坏。\n\n【得胜令】呀，今日个搭伏定摄魂台，一灵儿怨哀哀。父亲也，你现拿着刑名事，亲蒙圣主差。端详这文册，那厮乱纲常，合当败。便万剐了乔才，还道报冤仇不畅怀！\n\n（窦天章做泣科，云）哎，我那屈死的儿，则被你痛杀我也！我且问你：这楚州三年不雨，可真个是为你来？（魂旦云）是为你孩儿来。（窦天章云）有这等事！到来朝，我与你做主。（诗云）白头亲苦痛哀哉，屈杀了你个青春女孩。只恐怕天明了，你且回去，到来日我将文卷改正明白。（魂旦暂下）（窦天章云）呀，天色明了也。张千，我昨日看几宗文卷，中间有一鬼魂来诉冤枉。我唤你好几次，你再也不应，直恁的好睡那？（张千云）我小人两个鼻于孔一夜不曾闭，并不听见女鬼诉甚么冤状，也不曾听见相公呼唤。（窦天章做叱科，云）口退！今早升厅坐衙，张千，喝撺厢者。（张千做幺喝科，云）在衙人马平安！抬书案！（禀云）州官见。（外扮州官入参科）（张千云）该房吏典见。（丑扮吏入参见科）（窦天章问云）你这楚州一郡，三年不雨，是为着何来？（州官云）这个是天道亢旱，楚州百姓之灾，小官等不知其罪。（窦天章做怒云）你等不知罪么？那山阳县，有用毒药谋死公公犯妇窦娥，他问斩之时曾发愿道："若是果有冤枉，着你楚州三年不雨，寸草不生。"可有这件事来？（州官云）这罪是前升任桃州守问成的，现有文卷。（窦天章云）这等糊涂的官，也着他升去！你是继他任的，三年之中，可曾祭这冤妇么？（州官云）此犯系十恶大罪，元不曾有祠，所以不曾祭得。（窦天章云）昔日汉朝有一孝妇守寡，其姑自缢身死，其姑女告孝妇杀姑，东海太守将孝妇斩了。只为一妇含冤，致令三年不雨。后于公治狱，仿佛见孝妇抱卷哭于厅前。于公将文卷改正，亲祭孝妇之墓，天乃大雨。今日你楚州大旱，岂不正与此事相类？张千，分付该房签牌下山阳县，着拘张驴儿、赛卢医、蔡婆婆一起人犯人速解审，毋得违误片刻者。（张千云）理会得。（下）（丑扮解子，押张驴儿、蔡婆婆同张千上。禀云）山阳县解到审犯听点。(窦天章云)张驴儿。(张驴儿云）有。（窦天章云）蔡婆婆。（蔡婆婆云）有。(窦天章云）怎么赛卢医是紧要人犯不到？（解子云）赛卢医三年前在逃，一面着广捕批缉拿去了，待获日解审。（窦天章云）张驴儿，那蔡婆婆是你的后母么？（张驴儿云）母亲好冒认的？委实是。（窦天章云）这药死你父亲的毒药，卷上不见有合药的人，是那个合的毒药？（张驴儿云）是窦娥自合就的毒药。（窦天章云）这毒药必有一个卖药的医铺。想窦娥是个少年寡妇，那里讨这药来？张驴儿，敢是你合的毒药么？（张驴儿云）若是小人合的毒药，不药别人，倒药死自家老子？（窦天章云）我那屈死的儿口乐，这一节是紧\n要公案，你不自来折辩，怎得一个明白？你如今冤魂却在那里？（魂旦上，云）张驴儿，这药不是你合的，是那个合的？（张驴儿做怕科，云）有鬼，有鬼，撮盐入水。太上老君急急如律令，敕！（魂旦云）张驴儿，你当日下毒药在羊肚儿汤里，本意药死俺婆婆，要逼勒我做浑家。不想俺婆婆不吃，让与你父亲吃，被药死了。你今日还敢赖哩！（唱）\n\n【川拨掉】猛见了你这吃敲材，我只问你这毒药从何处来？你本意待暗里栽排，要逼勒我和谐，倒把你亲爷毒害，怎教咱替你耽罪责！\n\n（魂旦做打张驴儿科）（张驴儿做避科，云）太上老君，急急如律今，敕！大人说这毒药．必有个卖药的医铺，若寻得这卖药的人来和小人折对，死也无词。（丑扮解子解赛卢医上，云）山阳县续解到犯人一名赛卢医。（张千喝云）当面。（窦天章云）你三年前要勒死蔡婆婆，赖他银子，这事怎么说？（赛卢医叩头科，云）小的要赖蔡婆婆银子的情是有的。当被两个汉子救了，那婆婆并不曾死。（窦天章云）这两个汉子，你认的他叫做甚么名姓？（赛卢医云）小的认便认得，慌忙之际可不曾问的他名姓。（窦天章云）现有一个在阶下，你去认来。（窦卢医做下认科，云）这个是蔡婆婆。(指张驴儿云)想必这毒药事发了。(上云）是这一个。容小的诉禀；当日要勒死蔡婆婆时，正遇见他爷儿两个救了那婆婆去。过得几日，他到小的铺中讨服毒药。小的是念佛吃斋人，不敢做昧心的事。说道："铺中只有官料药，并无甚么毒药。"他就睁着眼道："你昨日在郊外要勒死蔡婆婆，我拖你见官去！"小的一生最怕的是见官，只得将一服毒药与了他去。小的见他生相是个恶的，一定拿这药去药死了人，久后败露，必然连累。小的一向逃在涿州地方，卖些老鼠药。刚刚是老鼠被药杀了好几个，药死人的药其实再也不曾合。（魂旦唱）\n\n【七弟兄】你只为赖财，放乖，要当灾。（带云）这毒药呵，（唱）原来是你赛卢医出卖，张驴儿买，没来由填做我犯由牌，到今日官去衙门在。（窦天章云）带那蔡婆婆上来！我看你也六十外人了，家中又是有钱钞的，如何又嫁了老张，做出这等事来？（蔡婆婆云）老妇人因为他爷儿两个救了我的性命，收留他在家养膳过世。那张驴儿常说要将他老子接脚进来，老妇人并不曾许他。（窦天章云）这等说，你那媳妇就不该认做药死公公了。（魂旦云）当日问官要打俺婆婆，我怕他年老，受刑不起，因此咱认做药死公公，委实是屈招个！（唱）\n\n【梅花酒】你道是咱不该，这招状供写的明白。本一点孝顺的心怀，倒做了惹祸的胚胎。我只道官吏每还覆勘，怎将咱屈斩首在长街！第一要素旗枪鲜血洒，第二要三尺雪将死尸埋，第三要三年旱示天灾：咱誓愿委实大。\n\n【收江南】呀，这的是"衙门从古向南开，就中无个不冤哉"！痛杀我娇姿弱体闭泉台，早三年以外，则落的悠悠流恨似长淮。\n\n（窦天章云）端云儿也，你这冤枉我已尽知，你且回去。待我将这一起人犯并原问官吏另行定罪。改日做个水陆道场，超度你生天便了。（魂旦拜科，唱）\n\n【鸳鸯煞尾】从今后把金牌势剑从头摆，将滥官污吏都杀坏，与天子分忧，万民除害。（云）我可忘了一件：爹爹，俺婆婆年纪高大，无人侍养，你可收恤家中，替你孩儿尽养生送死之礼，我便九泉之下，可也瞑目。（窦天章云）好孝顺的儿也！（魂旦唱）嘱付你爹爹，收养我奶奶。要怜他无妇无儿，谁管顾年衰迈！再将那文卷舒开，（带云）爹爹，也把我窦娥名下，（唱）屈死的招伏罪名儿改。（下）（窦天章云）唤那蔡婆婆上来。你可认的我么？（蔡婆婆云）老妇人眼花了，不认的。（窦天章云）我便是窦天章。这才的鬼魂，便是我屈死的女孩儿端云。你这一行人，听我下断：张驴儿毒杀亲爷，谋占寡妇，合拟凌迟，押付市曹中，钉上木驴，剐一百二十刀处死。升任州守桃杌并该房吏典，刑名违错，各杖一百，永不叙用。赛卢医不合赖钱，勒死平民；又不合修合毒药，致伤人命，发烟瘴地面，永远充军。蔡婆婆我家收养。窦娥罪改正明白。（词云）莫道我念亡女与他又罪消愆，也只可怜见楚州郡大旱三年。昔于公曾表白东海孝妇，果然是感召得灵雨如泉。岂可便推诿道天灾代有，竟不想人之意感应通天。今日个将文卷重行改正，方显的王家法不使民冤。\n\n题目秉鉴持衡廉访法\n\n正名感天动地窦娥冤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂剧·感天动地窦娥冤' AND p.poem_author = '关汉卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('裸人丛笑篇 其十', '孙元衡', '清代', '尔之生也，悬刀代弧；尔之壮也，畜犬为徒。柔筌以卧肉以脯，纵横猛气凌殷虞；\n\n奋狋㹜𤜜不可呼，争先奚翅当百夫。功多齿钝弃匪辜，日暮累累嗥路隅！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '裸人丛笑篇 其十' AND p.poem_author = '孙元衡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汉阳舟次读张南山大令听松庐诗集题此奉赠', '周启运', '清代', '我舟发襄阳，适逢蜀西客。为谭船山诗，卓荦多奇格。\n\n昨过汉江署，又遇诗中伯。一见心已倾，盛名久赫赫。\n\n君家诗有源，曲江体堪式。二公实继声，粤蜀气不隔。\n\n肯念苔岑缘，贻我松庐册。盥露出琅编，一读一寻绎。\n\n古调能独弹，灵境皆新辟。精如丽水金，润如蓝田璧。\n\n清如霜鹤音，健如云鹏融。大声发水上，蛟龙丧魂魄。\n\n读罢烛花残，不知东方白。齿余兰芬多，眼觉沧溟窄。\n\n以兹集众誉，实得非幸获。近今作家众，人人据吟席。\n\n四离或不闻，六迷良未释。华丽涉虚浮，高澹邻迂僻。\n\n岂知思无邪，一言蔽三百。老杜忠爱心，即此温厚泽。\n\n君才不可量，君行固无慝。笃实有光辉，允承千年脉。\n\n具此玉堂器，宜通金闺籍。如何佛已成，转同仙偶谪。\n\n赤壁鹤曳轮，黄州凫飞舄。梦得自多才，韩愈非可惜。\n\n天教政学兼，咏歌通保赤。人生不朽三，德言功并饬。\n\n宓琴有遗音，言弦岂小术。所望大雅材，风流追古昔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汉阳舟次读张南山大令听松庐诗集题此奉赠' AND p.poem_author = '周启运';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送孙叔静', '李之仪', '宋代', '浮云无定着，乍合还分离。廓开万里天，好是无云时。\n\n我怀苦萧屑，多感不自拾。奈何情所亲，容易成南飞。\n\n秦人虽受宝，睨柱谁瑕疵。空能九宾赏，终负连城归。\n\n此道固有命，如君应未迟。且从淮上游，霜浓蟹螯肥。\n\n载取一樽酒，里门相扶携。笑语欲难背，古人良可期。\n\n开编若对面，谑浪尤相宜。皎皎澄汉月，森森琼树枝。\n\n燕地重郭隗，吴儿轻陆机。晓来犹薄露，会见高风披。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送孙叔静' AND p.poem_author = '李之仪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('平步楼', '陈藻', '宋代', '主翁面貌不堪夸，却是书中意味华。\n因地成楼平似陟，开林见树直仍斜。\n竟日清幽来佛寺，有时问答觉人家。\n厌随权势贪情话，算杀把鸡愧满车。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '平步楼' AND p.poem_author = '陈藻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日偶过亳村故居', '陈维崧', '清代', '前村里，落梅阵阵风起。\n旧家池馆暂经过，玉栏漫倚。\n粉英也为主人来，雨中和泪梳洗。\n画檐损，月榭圮。\n蘼芜蛱蝶盈砌。\n颓垣败井剧关心，那能遣此。\n赚人连夜卸烟帆，半篙埋怨春水。\n一天丝雨洒不止，总难忘旧日邻里。\n只有点波燕子，上雕梁、絮语墨花帘底，似话王家当年事。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日偶过亳村故居' AND p.poem_author = '陈维崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵梅山弟醉吟七首', '陈著', '宋代', '隐处是甪里先生，放游是司马子长。\n试问梅山老居士，判断两家谁最香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵梅山弟醉吟七首' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('念奴娇二十六首 其十', '蒋士铨', '清代', '闲闲十亩，看花如、菘韭吏如莺燕。夕露朝霞，供采摘、买断绿愁红怨。\n\n老树维驹，残葩炙肉，杂沓笙歌宴。芳丛鹤盖，一年几度相见。\n\n独有偃地虬松，孤樘傲骨，横卧如人倦。剔藓扪苔，无醉墨、我向壁闲寻遍。\n\n谱继扬州，种分京雊，也算河阳县。城中万户，岂无高士庭院。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '念奴娇二十六首 其十' AND p.poem_author = '蒋士铨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重别李评事', '陈䞇', '明代', '酒尽离杯欲别难，秖凭书札报平安。明宵何处孤舟泊，露湿蒹葭月色寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重别李评事' AND p.poem_author = '陈䞇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨晴二首 其一', '李辕', '明代', '松日照人春雨收，杖藜徐步桥东头。桃花夹岸似霞染，云气出山如水流。\n\n身高仰羡不下鹤，眼明忽见双飞鸥。纡朱拖紫乃馀事，得及吾侬心迹幽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨晴二首 其一' AND p.poem_author = '李辕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杨白花', '陈子升', '明代', '可怜杨白花，飞似海青鸟。鸟衔花不来，空见他花嬲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杨白花' AND p.poem_author = '陈子升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蔡氏藏先世诰敕', '吴当', '元代', '无复前朝旧典型，百年文物尽凋零。蔡家孙子风流在，爱惜黄麻似六经。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蔡氏藏先世诰敕' AND p.poem_author = '吴当';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('田舍即事十首', '刘克庄', '宋代', '凋邑租符紧，荒祠木偶新。\n吏谈长官健，巫托社公嗔。\n烹犬看承客，吹螺降送神。\n二豪怀肉返，去诳别村人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '田舍即事十首' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('减字木兰花·清尊白发', '陈师道', '宋代', '清尊白发。曾是登临年少客。不似当年。人与黄花两并妍。来愁去恨。十载相看情不尽。莫更思量。梦破春回枉断肠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '减字木兰花·清尊白发' AND p.poem_author = '陈师道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题王俭撰褚渊碑文', '弘历', '清代', '资父以事君，本天经地义。彦回以孝称，胡甘二姓事。\n\n可怜石头城，口碑有公议。仲宝树绰楔，乃复腾文字。\n\n光辅五君同，寅亮二代逮。将为直笔书，抑为同恶济。\n\n昭明但选文，取裁失节制。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题王俭撰褚渊碑文' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙', '黄侃', '近代', '夜雨秋魂频断，夕阳孤影空归。恨深愁浅两难知。\n\n小楼人静后，疏幕月明时。\n\n若道此情谁解，那应空说相思。最怜幽梦觉来迟。\n\n残灯留冷焰，还照泪双垂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙' AND p.poem_author = '黄侃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('北山诗三十八首 其二', '赵熙', '清代', '数株榕树客门遮，缓下山坳石级斜。大好春光元野外，薄游风味似天涯。\n\n贫挑石炭怜崖户，雨渴秧田念水车。指点去秋闻雁处，虎崖疏竹宿人家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '北山诗三十八首 其二' AND p.poem_author = '赵熙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜居二首 其二', '丁鹤年', '元代', '小村虽僻俗敦庞，背负崇山面俯江。月冷灵虬潜绝壑，雨晴仙犬吠流淙。\n\n缊袍御腊辞纨裤，瓦瓮浮春谢玉缸。偶为清羸聊采药，亦非窃比鹿门庞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜居二首 其二' AND p.poem_author = '丁鹤年';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古四十四首 其三十五', '释师范', '宋代', '一掷神杯定吉凶，再占重卜转灵通。分明见了今年事，却说明年事不同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古四十四首 其三十五' AND p.poem_author = '释师范';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽章朋举', '高翥', '宋代', '相逢便拜十年兄，自此交游得尽情。\n草纸抄书传遁甲，竹筩沽酒命添丁。\n他时结屋期来往，今日登门隔死生。\n从此苕溪明月夜，小舟不复为君停。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽章朋举' AND p.poem_author = '高翥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏和玉山韵', '陈基', '元代', '西子湖边苏小宅，锦官城里薛涛家。来时豆蔻初含蕊，别后菖蒲又著花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏和玉山韵' AND p.poem_author = '陈基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谷日立春喜晴次和谭芝云翰林', '陈三立', '近代', '春动枝头鸟语催，晓风暖坼雪残梅。\n九垓震荡留吟几，万象低昂映酒杯。\n藩镇兵犹乘衅起，海邦使播歃盟回。\n腐儒把玩微阳复，莫问饥肠破疾雷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谷日立春喜晴次和谭芝云翰林' AND p.poem_author = '陈三立';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄楼子山云栖上人', '刘得仁', '唐代', '一室凿崔嵬，危梯叠藓苔。永无尘事到，时有至人来。 \n 涧谷冬深静，烟岚日午开。修身知得地，京寺未言回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄楼子山云栖上人' AND p.poem_author = '刘得仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十一日', '赵蕃', '宋代', '老眼看花抵雾中，寥寥鼻观与香能。\n水仙蜕去梅成实，只有山礬印此风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十一日' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和李端叔大夫从参寥子游许昌西湖十绝', '李廌', '宋代', '几处秋千愁日暮，一声鶗鴃唤春归。\n红稀绿尽寻常事，不用长绳系落晖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和李端叔大夫从参寥子游许昌西湖十绝' AND p.poem_author = '李廌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春宵', '朱诚泳', '明代', '宫壶传漏刻，刻刻价非轻。杨柳风初软，梨花月正明。\n\n秋千微有影，檀板寂无声。怪底长门内，通宵梦不成。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春宵' AND p.poem_author = '朱诚泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('道中四绝', '郑刚中', '宋代', '败箧冲霜思往岁，旧游如梦慨平生。\n鬓华已逐心事老，溪水祗如前日清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '道中四绝' AND p.poem_author = '郑刚中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同赵使君雨中登大云绝顶夜饮见一楼题', '胡应麟', '明代', '缥缈危梯望目萦，微茫秋色半江城。苍龙掣电千禾立，白鸟栖烟万树明。\n\n北浦鱼竿誇旧涨，西郊农锸快新成。携壶不尽追游思，剪烛虚堂听夜鸣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同赵使君雨中登大云绝顶夜饮见一楼题' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('柳絮', '钱惟演', '宋代', '三月江南花渐稀，春阴漠漠雪霏霏。\n章台街里翩轻吹，灞水桥边送落晖。\n陆凯传精梅暗落，韩凭遗恨蝶争飞。\n诏书漫道吹纶薄，谁见纷纷上客衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '柳絮' AND p.poem_author = '钱惟演';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('函谷关', '汪广洋', '明代', '树木阴森虎夜号，行人愁杀路峣岰。谁家鸡唱寒烟里，举首东方太白高。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '函谷关' AND p.poem_author = '汪广洋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送徐洞清秀才入道', '叶适', '宋代', '方老昔为儒，仁义自愁煎。\n决策从道士，摆落科场缘。\n神仙事茫昧，良得日高眠。\n徐生嗣其风，永谢负郭田。\n白襕已回施，黄氅犹索钱。\n书籍弃尘案，笙磬来钧天。\n看镜胡独难，超俗谅非少。\n异花改林秀，孤翮移汉矫。\n月华满庭芜，阒沉霜宇峭。\n亲交生离绝，空叹真游杳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送徐洞清秀才入道' AND p.poem_author = '叶适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赋得「相逢俱是岁寒人」', '张煌言', '明代', '相逢俱是岁寒人，迟暮偏惊摇落辰。鸿雁接天关塞影，渔樵满地雪霜身。\n\n论交四海惭兄弟，抗迹千秋泣鬼神。此日炎趋应不少，道旁裘马正纷纶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赋得「相逢俱是岁寒人」' AND p.poem_author = '张煌言';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题禹庙二首 其二', '张镃', '宋代', '为人心切屡忘家，力量方知有等差。莫信空山葬冠剑，且吟古屋画龙蛇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题禹庙二首 其二' AND p.poem_author = '张镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('林子中知府挽诗', '虞俦', '宋代', '畴昔因难弟，夤缘幸识君。\n宦途俱别日，苕水再披云。\n劳苦惊多病，悲凉惜离群。\n斗金峰下路，铎挽不堪闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '林子中知府挽诗' AND p.poem_author = '虞俦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和李光化秋咏四首其四·夜', '范仲淹', '宋代', '春色人皆醉，秋光独不眠。\n君看明月下，何似落花前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和李光化秋咏四首其四·夜' AND p.poem_author = '范仲淹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜陆养和督汎', '张嗣纲', '明代', '双旌冉冉自天来，银岛金门郁气开。海色昔时浑似雾，风声今日迅如雷。\n\n谈兵夜静鱼龙泣，击剑光寒鬼魅催。江左未应轻借寇，还期推毂重边台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜陆养和督汎' AND p.poem_author = '张嗣纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄唐伯华', '蒋超伯', '清代', '洺水连鸡泽，还从钜鹿行。回波无止处，如我望君情。\n\n又见门丞换，何尝吠犬惊。新年当把襼，五马向春明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄唐伯华' AND p.poem_author = '蒋超伯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月', '王哲', '元代', '常把内真频看，休教外景长侵。尖竿尖上细搜寻。\n\n正见婴儿弄影。\n\n雅咏高吟叫笑，清风皓月吹临。分开传作紫共金。\n\n艳迸斗花万锦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月' AND p.poem_author = '王哲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('何凝生投赠新诗赋答', '邓云霄', '明代', '清风朗月正怀人，忽寄诗筒托雁臣。共道贾生才弱冠，却疑长吉是前身。\n\n孤高鹤警三天露，宛转莺啼万谷春。试问词源几深浅，与君同探浣花津。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '何凝生投赠新诗赋答' AND p.poem_author = '邓云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('子夜四时歌 其九', '佚名', '魏晋', '暑盛静无风，夏云薄暮起。携手密叶下，浮瓜沈朱李。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '子夜四时歌 其九' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和所盘端午韵', '丘葵', '宋代', '槐夏阴中鬓已秋，天风吹梦堕江头。\n水应难洗湘累恨，山岂能为柳子囚。\n尘世不知几端午，人生大抵一虚舟。\n愁来细把君诗看，压倒当时赵倚楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和所盘端午韵' AND p.poem_author = '丘葵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('己巳猪日子锋招饮不赴马日东河小集罚以留芳茶社韵 其三', '秦鸿', '当代', '欲弹长铗断，欲出恨无车。犹记台城会，清吟白日斜。\n\n兴来须对酒，梦寐忽还家。谈笑高楼上，寒波淡似茶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '己巳猪日子锋招饮不赴马日东河小集罚以留芳茶社韵 其三' AND p.poem_author = '秦鸿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('癸卯除夕直北曹作', '皇甫涍', '明代', '独马向寒烟，青阳眷明发。\n霜净肃兰池，云沈迥丹阙。\n林阡麇易聚，江天雁难没。\n风物怅徂阴，芳菲讵久歇。\n纷庭默多惧，岩皞坐愁越。\n夙心愧盈尊，含情非华发。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '癸卯除夕直北曹作' AND p.poem_author = '皇甫涍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送北京学生曹慈明秀才之京师', '晁补之', '宋代', '魏武子孙今寂莫，唐来只有画将军。\n邺城初见黄须面，尚喜登堂词若云。\n乃公白首图籍里，小心恐惧教其子。\n文章锦心仍绣腑，屠龙殚家安用许。\n半年系船康海门，官忙不共持一樽。\n冈头黎花吹欲尽，淮口汴流来正浑。\n鄙夫日欲向吴越，官满一封飞魏阙。\n着书虎观未敢言，蔽身蝉叶真痴绝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送北京学生曹慈明秀才之京师' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜过芳村', '朱帆', '近代', '花香依旧袭行人，灯火楼台望未真。今夜芳村舒老眼，白鹅潭上月如银。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜过芳村' AND p.poem_author = '朱帆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('开岁连日有阴雨', '孙嵩', '宋代', '老杜诗章五百年，为吾替写早春篇。\n恰从元日逾人日，重有阴阴冷落天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '开岁连日有阴雨' AND p.poem_author = '孙嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('醉落魄（赋石榴花）', '程垓', '宋代', '夏围初结。绿深深处红千叠。杜鹃过尽芳菲歇。只道无春，满意春犹惬。 \n 折来一点如猩血。透明冠子轻盈帖。芳心蹙破情忧切。不管花残，犹自拣双叶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '醉落魄（赋石榴花）' AND p.poem_author = '程垓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('代人寄梦子', '屈大均', '明代', '少别成千岁，悲歌了不闻。老龙犹下土，雏凤已高云。\n\n词赋微言在，经纶艳色分。怜才知不浅，有泪湿罗裙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '代人寄梦子' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再过赤溪呈邓元白', '魏禧', '清代', '相见意不已，不寐竟达旦。振衣出南郭，露草凄以漫。\n\n轻烟幕平林，村村鸡犬散。初日多好光，主人适朝饭。\n\n人生不知心，何用更谋面。我生十一岁，窃希范张传。\n\n素心六七人，异姓而同干。涂氏贤父子，君之旧友善。\n\n语我与林子，奇才不易见。天下昔无君，黎阳初构乱。\n\n城虎不择肉，党恶以千万。君督南乡兵，机密发不缓。\n\n黎明驻南郊，群凶寝方燕。踉跄出门斗，前死后者窜。\n\n一日杀千人，万家获安奠。死者骨肉亲，至今不敢怨。\n\n乡兵骄成功，虎死狼为患。君更用市人，疾若摧枯蔓。\n\n用人人不疑，杀人人不叛。事己身不与，超然如飞翰。\n\n前日同涂林，访君读书院。路经校射场，指是君所践。\n\n怀哉李太白，风月此遗墠。昔读袁州碑，高文垂孔殿。\n\n字字关人伦，儒术尊不贱。夹溪千树桃，白沙空断岸。\n\n怜君多白须，喜君老尚健。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再过赤溪呈邓元白' AND p.poem_author = '魏禧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读明太祖本纪有感其语', '司炳煃', '清代', '元虽起北狄，主中国百年。后王纵不才，先帝德未谖。\n\n我祖与若宗，为民而受廛。渥受教养恩，太平享安全。\n\n一朝至顺帝，淫昏异祖先。英雄起草泽，四宇皆狼烟。\n\n明祖乃崛兴，宝位授于天。独夫放塞外，和林妻孥完。\n\n中山识此意，明言臣舍旃。上启圣仁心，宸衷矜且怜。\n\n诏书戒夸大，臣民禁哗喧。讵因子孙愚，诋毁宗祖贤。\n\n大哉开国主，谟训垂简篇。气象迈汉唐，度量包垓埏。\n\n至今诵其语，令人生慨然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读明太祖本纪有感其语' AND p.poem_author = '司炳煃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵 其一', '萨都剌', '元代', '之子慇勤何处来，清谈煮茗不论杯。五更门外过风雨，四月街头买杏梅。\n\n喜客有情窗动竹，吟诗无兴砚生苔。君家白酒何时熟，病起应须去不回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵 其一' AND p.poem_author = '萨都剌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('下第寄知己', '曹邺', '唐代', '长安孟春至，枯树花亦发。忧人此时心，冷若松上雪。 \n 自知才不堪，岂敢频泣血。所痛无罪者，明时屡遭刖。 \n 故山秋草多，一卷成古辙。夜来远心起，梦见潇湘月。 \n 大贤冠盖高，何事怜屑屑。不令伤弓鸟，日暮飞向越。 \n 闻知感激语，胸中如有物。举头望青天，白日头上没。 \n 归来通济里，开户山鼠出。中庭广寂寥，但见薇与蕨。 \n 无虑数尺躯，委作泉下骨。唯愁揽清镜，不见昨日发。 \n 愿怜闺中女，晚嫁唯守节。勿惜四座言，女巧难自说。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '下第寄知己' AND p.poem_author = '曹邺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天姥峰', '郑善夫', '明代', '天姥崚嶒不可招，云岩雪壑傍丹霄。天台四万八千丈，俯看飞虹度石桥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天姥峰' AND p.poem_author = '郑善夫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登邠州城楼', '文同', '宋代', '试此望摇落，秋襟成惘然。\n客怀伤薄莫，节物感穷边。\n断烧侵高垒，微阳入晚川。\n年来旧山意，常与雁翩翩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登邠州城楼' AND p.poem_author = '文同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题赵与㑾贽卷', '刘克庄', '宋代', '身已明农老一丘，屡空何以答珍投。新腔高处古乐府，警句当家小倚楼。\n\n此笔生花尤组丽，彼风吹箨漫轻浮。从前作者皆勤苦，萤雪功夫更讲求。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题赵与㑾贽卷' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬裴端公八月十五日夜对月见怀', '权德舆', '唐代', '凉夜清秋半，空庭皓月圆。动摇随积水，皎洁满晴天。 \n 多病嘉期阻，深情丽曲传。偏怀赏心处，同望庾楼前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬裴端公八月十五日夜对月见怀' AND p.poem_author = '权德舆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重阳后菊花二首', '范成大', '宋代', '寂莫东篱湿露华，依前金魇照泥沙。\n世情儿女无高韵，只看重阳一日花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重阳后菊花二首' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('立春和姚东桥二首 其一', '黄衷', '明代', '朝衣湖上两鞭春，绵力初交谢百钧。风雨试灯逢粤客，羔豚祈岁赛芒神。\n\n渐知槐目将舒暖，却妒云姿解弄新。庾信经年归未得，江南佳丽少诗人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '立春和姚东桥二首 其一' AND p.poem_author = '黄衷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晓坐（一云后閤）', '李商隐', '唐代', '后閤罢朝眠，前墀思黯然。梅应未假雪，柳自不胜烟。 \n 泪续浅深绠，肠危高下弦。红颜无定所，得失在当年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晓坐（一云后閤）' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄永丰教谕戴正心', '邓雅', '明代', '戴君掌教恩江上，正是皇朝全盛时。文化今渐极南北，才名久著浙东西。\n\n云霄万里瞻丹阙，庠序三年坐绛帷。但使英才登俊造，莫嗟微禄久淹迟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄永丰教谕戴正心' AND p.poem_author = '邓雅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三用韵奉酬', '杨公远', '宋代', '龙蛇满纸势如飞，净几明窗得句时。\n一阵好风吹过我，吟余束手笠降旗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三用韵奉酬' AND p.poem_author = '杨公远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阅兵给赉', '袁说友', '宋代', '小臣衔命入云屯，圣主如天诏语温。\n万甲冲风隆士气，一言挟纩荷君恩。\n颇惊霹雳烧残垒，更想蒙冲上海门。\n欲挽长江问豪杰，岂无击楫叹中原。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阅兵给赉' AND p.poem_author = '袁说友';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游丝', '秦善', '明代', '旧游曾入桑间路，惹袖沾裾思未休。纤绠依稀烟外没，群珠蹙续雨中浮。\n\n晴牵草树萦春恨，暝倚花窗织夜愁。只恐惊风吹散去，残丝零乱不堪收。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游丝' AND p.poem_author = '秦善';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哀弃儿', '许有壬', '元代', '雪霜载途风裂肌，有儿鹑结行且啼。问儿何事乃尔悲，父母弃之前欲追。\n\n木皮食尽岁又饥，夫妇行乞甘流离。负儿远道力已疲，势难俱生灼可推。\n\n与其疐尾莫我随，不如忍割从所之。今夕旷野儿安归，明朝道殣非儿谁。\n\n父兮母兮岂不慈，天伦遽绝天实为。卜年执政虽咸腓，发廪有议常坚持。\n\n昔闻而知今见之，仓皇援手无所施。儿行不顾寒日西，哭声已远犹依稀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哀弃儿' AND p.poem_author = '许有壬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居次韵六首用起句题 其六', '虞堪', '明代', '好山看不尽，一望一番登。崖险森如戟，泉甘冷若冰。\n\n鸣钟传下界，著屐上高层。不是石桥客，何由识老僧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居次韵六首用起句题 其六' AND p.poem_author = '虞堪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('路傍堠（以下四篇并元和十四年出为潮州作）', '韩愈', '唐代', '堆堆路傍堠，一双复一只。迎我出秦关，送我入楚泽。 \n 千以高山遮，万以远水隔。吾君勤听治，照与日月敌。 \n 臣愚幸可哀，臣罪庶可释。何当迎送归，缘路高历历。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '路傍堠（以下四篇并元和十四年出为潮州作）' AND p.poem_author = '韩愈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题粤中遗迹画 其二 榴花塔', '丘逢甲', '清代', '蛟奋龙拿石上文，天留此塔表将军。江山不改亭亭影，落日空村鹘叫云。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题粤中遗迹画 其二 榴花塔' AND p.poem_author = '丘逢甲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送权上人兼东谅虚白讲师', '袁华', '明代', '释书经律论，中分大小乘。繇汉历唐宋，翻译卷帙增。\n\n微义浩河沙，究竟谅未曾。权师未识面，闻誉如云腾。\n\n兹登雨花堂，闻妙心源澄。庭眠惠远鹅，臂驾支遁鹰。\n\n天池九万里，扶摇自此升。为言虚白翁，归休理寒镫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送权上人兼东谅虚白讲师' AND p.poem_author = '袁华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('君马黄', '欧必元', '明代', '君马黄，臣马赤，须臾驰骋周八极。度昆崙，秣流沙。\n\n宴王母，枣如瓜。奄有诸夏，辞彼东土。将子无死来见汝，徘佪三叹为君舞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '君马黄' AND p.poem_author = '欧必元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('钗头凤 冬闺', '吴绮', '清代', '灯花滴。炉香熄。屏风静掩遥山碧。箫谁弄。衾长空。\n\n五更帘幕，月和霜重。冻。冻。冻。\n\n闲寻觅。无消息。泪痕冰惹红绵湿。愁难送。情还种。\n\n巫云昨夜，同骑双凤。梦。梦。梦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '钗头凤 冬闺' AND p.poem_author = '吴绮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古风', '丁岳', '明代', '麒麟四灵长，群兽孰敢当。\n木精著文彩，肉角仁且良。\n生草既不折，生虫亦不伤。\n在鲁何成悲，来周乃致祥。\n一去余千载，中原有豺狼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古风' AND p.poem_author = '丁岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟孟郊', '陈曾寿', '清代', '世味有酸辛，酸辛殊昔今。有母酸在口，无母酸在心。\n\n我于失母年，无语已成瘖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟孟郊' AND p.poem_author = '陈曾寿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('迎五十七杂感 其九', '何永沂', '当代', '愿人长久共婵娟，过了明天又一年。难得糊涂肝胆雪，不如归去口头禅。\n\n五湖已被官家占，多士曾蒙霸主鞭。友尽与时俱进者，岭南诗酒对红棉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '迎五十七杂感 其九' AND p.poem_author = '何永沂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜迁莺·莫寻玄妙', '佚名', '宋代', '莫寻玄妙。我分明说破，修行关窍。战睡敌魔，忘情绝念，此是圣贤正教。饮食则定除疑，每日勤修觉照。莫差了。待无眠无睡，心方合道。别有玄和妙。炼气成神，自有金光罩。五气朝元，三花聚顶，水火运行颠倒。九阳结就还丹，射透灵台八表。功行了。向长生路上，闲游三岛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜迁莺·莫寻玄妙' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈', '印首座', '宋代', '丘师伯莫晓，寂寂明皎皎。日午打三更，谁人打得了。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈' AND p.poem_author = '印首座';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古意', '姜特立', '宋代', '共绾同心结，那知有别离。\n对人争忍说，不敢画蛾眉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古意' AND p.poem_author = '姜特立';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桃叶曲', '胡宗仁', '明代', '桃叶渡头桃叶春，家家桃叶斗妆新。\n不知何处初来客，未省吴姬会笑人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桃叶曲' AND p.poem_author = '胡宗仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六月十六日观洗象', '郑孝胥', '清代', '宣南洗象迎初伏，万骑千车夹水看。法驾旧仪从卤簿，玉泉新涨试波澜。\n\n蒲甘国破封难复，莽氏民存业遂残。留汝南荒遗老在，可堪有齿已先寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六月十六日观洗象' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('甘凉途中杂咏 其一', '罗文俊', '清代', '闇门列戍拥飞沙，毳幕毡裘久一家。饮马长城天似盖，乱红开遍战场花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '甘凉途中杂咏 其一' AND p.poem_author = '罗文俊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东斋杂书', '陆游', '宋代', '吾贫无时醒，日月忽遄迈。\n空林春采葚，荒垄秋种稗。\n孤学有自来，饥死奚足怪。\n著书充栋宇，一字不肯卖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东斋杂书' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('端午二首 其一', '添雪斋', '当代', '一旦斯心为世摧，唯闻邑野式歌徊。钧天强遂逆民骨，末代堪承盗火灰。\n\n难释真红逢旰日，终于暗黑掩琼瑰。独来此夜颓风里，有汝精魂动暴雷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '端午二首 其一' AND p.poem_author = '添雪斋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重过燕子岩题前诗', '牛焘', '清代', '石上扫云归碧落，松枝作字蘸红泥。书成半壁龙蛇幻，风雨惊人四望迷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重过燕子岩题前诗' AND p.poem_author = '牛焘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李起宗舍人悠然亭', '楼钥', '宋代', '远游蜀道历艰难，径上甘泉豹尾间。\n荷橐忽思辞北省，拂衣自喜见南山。\n当时旁舍基犹在，回首垂髫鬓已斑。\n先友脾阴尽陈迹，寒空依旧湿烟鬟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李起宗舍人悠然亭' AND p.poem_author = '楼钥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归家前一日雨有怀逸庐', '黄仁基', '近代', '已得看山十日闲，每从幽处写诗还。可能冲雨如前约，同看溪南未尽山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归家前一日雨有怀逸庐' AND p.poem_author = '黄仁基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬日偶成', '善住', '元代', '清霜欲重小春天，杨柳萧疏带晓烟。无奈东皇苦多事，又传春信到梅边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬日偶成' AND p.poem_author = '善住';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古砚送赵明府', '许棐', '宋代', '一片端州古砚砖，翁孙相授当良田。寒梅涧下和冰洗，秋桂窗前滴露研。\n\n学字不工空费纸，吟诗虽苦未成编。赠君携去薇花畔，草诏闲时枕匣眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古砚送赵明府' AND p.poem_author = '许棐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('孔教授张法曹以曾论荐特示长笺', '曾巩', '宋代', '绿发朱颜两少年，出伦清誉每相无。\n壁中字为时人圪，圯上书从老父传。\n泮水笑谈邀法饮，高斋闲燕属佳篇。\n衰翁厚幸怀双璧，更起狂心慕荐贤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '孔教授张法曹以曾论荐特示长笺' AND p.poem_author = '曾巩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('如归亭 其四', '许申', '宋代', '寻常高讽散人歌，傲睨天随奈尔何。即问松江旧庐舍，羽真来往洞庭波。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '如归亭 其四' AND p.poem_author = '许申';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('老将', '罗邺', '唐代', '百战辛勤归帝乡，南班班里最南行。弓欺猿臂秋无力， \n 剑泣虬髯晓有霜。千古耻非书玉帛，一心犹自向河湟。 \n 年年宿卫天颜近，曾把功勋奏建章。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '老将' AND p.poem_author = '罗邺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吊卢殷 其四', '孟郊', '唐代', '登封草木深，登封道路微。日月不与光，莓苔空生衣。\n\n可怜无子翁，蚍蜉缘病肌。挛卧岁时长，涟涟但幽噫。\n\n幽噫虎豹闻，此外相访稀。至亲唯有诗，抱心死有归。\n\n河南韩先生，后君作因依。磨一片嵌岩，书千古光辉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吊卢殷 其四' AND p.poem_author = '孟郊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉题董端明渔父醉乡烧香图十六首 渔父七首 其二', '陈克', '宋代', '鲙缕丝丝雪色鱼，碧筒香细引村沽。江天此乐谁无分，不问官家乞鉴湖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉题董端明渔父醉乡烧香图十六首 渔父七首 其二' AND p.poem_author = '陈克';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题扇头', '郯韶', '元代', '洞庭木落山月低，出门秋色风凄凄。客行忆过黄陵庙，谷口青猿一个啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题扇头' AND p.poem_author = '郯韶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诏授同州刺史，病不赴任，因咏所怀', '白居易', '唐代', '同州慵不去，此意复谁知。诚爱俸钱厚，其如身力衰。 \n 可怜病判案，何似醉吟诗。劳逸悬相远，行藏决不疑。 \n 徒烦人劝谏，只合自寻思。白发来无限，青山去有期。 \n 野心惟怕闹，家口莫愁饥。卖却新昌宅，聊充送老资。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诏授同州刺史，病不赴任，因咏所怀' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('广陵怀古 其三', '史鉴', '明代', '龙舟行乐到芜城，极侈何愁四海兵。神器共传归李子，乐章先识去宫声。\n\n凤池有水鸥常下，萤苑无人草自生。寂寞西园明月夜，只今惟有草虫鸣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '广陵怀古 其三' AND p.poem_author = '史鉴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟游洞庭', '王恭', '明代', '微风孤棹洞庭游，千里沧波一镜秋。连雁远钟云梦泽，断猿残笛岳阳楼。\n\n巴陵雨霁君山出，蜀道冰消楚水流。欲吊重瞳何处是，苍梧瑶瑟不胜愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟游洞庭' AND p.poem_author = '王恭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('弋阳道中', '龚敩', '明代', '偶乘小蹇度山阿，记得当年旧所过。云护早霜晴不稳，路穿阴嶂湿还多。\n\n野人生计浑全薄，行客乡音一半讹。满眼黄蒿能几辟，边头何苦用干戈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '弋阳道中' AND p.poem_author = '龚敩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送徐太守仲敬致仕', '杨荣', '明代', '圣皇御宝历，图治臻雍熙。守令慎选举，务使安群黎。\n\n大守姑熟来，循良时所推。方书龚黄政，力以印绶辞。\n\n自陈七帙多，志耄精神疲。有母百馀岁，康强尚未衰。\n\n乞身遂归养，庶得尽其私。宠恩倏涣颁，五马不可羁。\n\n长揖别交友，矧子为故知。忆昔永乐中，宫僚并命时。\n\n一朝饯出守，会少多睽违。兹焉谢事去，把袂惊分携。\n\n黄鹄逝翩翩，遥望清江湄。重结紫霞想，不负青山期。\n\n乐哉戏彩服，眉寿应同跻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送徐太守仲敬致仕' AND p.poem_author = '杨荣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题李伯时仕女图 其一 妾心不忆交河冷，手冷难裁金剪刀', '钱宰', '元代', '海棠半拆银烛辉，春愁且莫剪春衣。下阶立得花阴没，如此月明人未归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题李伯时仕女图 其一 妾心不忆交河冷，手冷难裁金剪刀' AND p.poem_author = '钱宰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('到南昌呈宋愿父伯仲黄子鲁诸丈 其一', '戴复古', '宋代', '一秋无便寄平安，新雁声声报早寒。昨夜检衣开故箧，去年家信把来看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '到南昌呈宋愿父伯仲黄子鲁诸丈 其一' AND p.poem_author = '戴复古';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹溪寺', '陈廷璧', '清代', '金阙松间映碧溪，石阶层累绿园西。丝桐响动珠林地，竹树声喧宝殿鸡。\n\n匏酒薰蒸欢客对，土山秀拔望云齐。革皮画鼓空中震，木落烟销宿鸟啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹溪寺' AND p.poem_author = '陈廷璧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('飞燕', '李溥', '明代', '年年来去为谁忙，偏恋晴春引兴长。杨柳池塘窥日暖，杏花门巷落泥香。\n\n孤飞带雨寻华屋，双翼随风过粉墙。王谢旧游云海阔，秋深离恨转凄凉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '飞燕' AND p.poem_author = '李溥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠吴惇仁', '许景衡', '宋代', '尘埃簿领判悠悠，瘦马寻春到海头。已是二毛侵老境，尚能一笑得英游。\n\n谁言前辈风流尽，我觉名家世业优。但得此心常了了，岂知州县是淹留。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠吴惇仁' AND p.poem_author = '许景衡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西陵 其一', '傅作楫', '清代', '怅望平原思不胜，可怜南渡竟无凭。秋深摇落冬青冷，烟雨萧萧泣六陵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西陵 其一' AND p.poem_author = '傅作楫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦刘公瑞', '张宁', '明代', '形影久云绝，连宵频梦君。布衣仍潦倒，病发乱缤纷。\n\n似别惊相见，将言悄不闻。平生最深契，梦断一销魂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梦刘公瑞' AND p.poem_author = '张宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('损戒二首', '洪咨夔', '宋代', '河魨行水底，志在全其生。\n缒绠激使怒，拍浮拾彭亨。\n触来不自制，天君失和平。\n惩忿当如山，一静弭百争。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '损戒二首' AND p.poem_author = '洪咨夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郭圣竑见访，出诗相示；依韵酬之', '张煌言', '明代', '谁云仲蔚长蒿莱，白板双扉随意开。扫石我饶笼翠兴，磨岚君擅草玄才。\n\n杖头时挂千峰月，箧里争鸣万壑雷。自是主人能慰客，顿忘鸿雁已南回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郭圣竑见访，出诗相示；依韵酬之' AND p.poem_author = '张煌言';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秀州门外泊舟', '范成大', '宋代', '拍岸清波扑岸埃，黑头霜鬓几徘徊。\n禾兴门外官杨柳，又见扁舟上堰来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秀州门外泊舟' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋怀', '丘逢甲', '清代', '斜阳围听说场词，我亦曾驱十万师。破碎河山开国史，飘零风雨出军诗。\n\n海中故部沈苍兕，云里残旌失素蜺。岁自周天天自醉，红墙银汉隔秋思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋怀' AND p.poem_author = '丘逢甲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('褫高', '韩琦', '宋代', '山脚林成簇舍窠，门前流水养嘉禾。森森松柏围先陇，濈濈牛羊满近坡。\n\n官赋已供馀岁备，村歌无节得天和。安全尽责廉平吏，三岁齐民更孰过。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '褫高' AND p.poem_author = '韩琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('延福坊李太博乞园池诗', '邵雍', '宋代', '宣威十九次高牙，奕叶功臣旧将家。\n清世辞荣归里第，白头行乐过年华。\n杯盈香醑浮春水，曲度新声出靓花。\n如此园池如此寿，儿孙满眼庆无涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '延福坊李太博乞园池诗' AND p.poem_author = '邵雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和文与可洋川园池三十首 横湖', '苏轼', '宋代', '贪看翠盖拥红妆，不觉湖边一夜霜。\n卷却天机云锦段，従教匹练写秋光。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和文与可洋川园池三十首 横湖' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨中初泛西湖 其九', '李洸', '近代', '兰桡桂棹欲何之，正是荒江暮雨时。归路茫茫风又急，却怜漂泊在天涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨中初泛西湖 其九' AND p.poem_author = '李洸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游华山四绝 其三', '赵秉文', '金朝', '仙人仙去有仙掌，袖中掷下青芙蓉。遗与杨羲书一纸，暂留笙鹤驻中峰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游华山四绝 其三' AND p.poem_author = '赵秉文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('旧剑', '郑用锡', '清代', '补缀原关中阃事，莫邪不用太无聊。牵衣我欲持三尺，斩此安昌答圣朝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '旧剑' AND p.poem_author = '郑用锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙 冬闺', '陈尔士', '清代', '闲坐房栊看日斜。帘风阵阵峭寒加。自携金鸭款梅花。\n\n冻水一方休洗砚，轻烟几缕任煎茶。锦书无奈忆天涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙 冬闺' AND p.poem_author = '陈尔士';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留题周文王庙 其一', '宋京', '宋代', '征西将帅念君王，刻石巴山事渺茫。□载衣冠付冥寞，路人无语奠椒浆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留题周文王庙 其一' AND p.poem_author = '宋京';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('征人归乡', '戎昱', '唐代', '三月江城柳絮飞，五年游客送人归。 \n 故将别泪和乡泪，今日阑干湿汝衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '征人归乡' AND p.poem_author = '戎昱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二十初度', '周文', '宋代', '作恶春风二十年，愁眉常到镜台前。\n去年杨柳为谁折，今岁梅花黯自怜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二十初度' AND p.poem_author = '周文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陈安止孟东挽诗', '龚诩', '明代', '幸接芳邻并早孤，如鱼同队长东吴。余岂远作逋逃客，公已高登贵显途。\n\n故里菊松三径在，归舟囊橐一钱无。澄思七十年前旧，泪眼何曾为老枯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陈安止孟东挽诗' AND p.poem_author = '龚诩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('隔浦莲 田居', '丁澎', '清代', '菰芦风动蔌蔌。云里藏茅屋。晌夕农事少。羔初炙，酒方漉。\n\n乘兴寻樵牧。疏林暮。罢钓归山鼠。\n\n弄修竹。蓬门如许，灌园老叟何物。秋畦半亩，满眼昏鸦古木。\n\n一枕松风床下菊，知足。山家清景偏独。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '隔浦莲 田居' AND p.poem_author = '丁澎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西晋永嘉砖铭', '佚名', '魏晋', '永嘉世，九州荒。余广州，平且康。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西晋永嘉砖铭' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('呈吕使君留卿', '方回', '宋代', '大门昔有谣，吕氏一千中。\n华胄所自出，恭惟齐太公。\n君伯先郡王，张韩刘岳同。\n百战护诸将，易名称武忠。\n武忠棣华众，皆有远祖风。\n分阃伏斧钺，威望真非熊。\n子姓几百人，人人俱英雄。\n人人俱智慧，人人俱疏通。\n三衢今使君，尤其明且聪。\n剑光夜冲斗，玉气日贯虹。\n好士出天性，坐满樽不空。\n民怀吏胆落，于物大有功。\n驿马走中原，蹇蹇臣匪躬。\n北上夏云赤，南还春花红。\n割牲饤鮓脯，邂逅孤山东。\n念此门下士，陋巷甘固穷。\n昨者诸彦集，长裾织青葱。\n岂谓龙虎阁，著此垂翅鸿。\n高怀极恋恋，莫景殊匆匆。\n愿言一转手，西江挂飞蓬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '呈吕使君留卿' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('池州和同官咏梅花 其四', '张道洽', '宋代', '疏疏竹外枝，短短水边篱。南雪若相避，东风殊不知。\n\n兰荃皆弱植，桃杏总凡姿。坐叹逋仙远，清宵费梦思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '池州和同官咏梅花 其四' AND p.poem_author = '张道洽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙 其一 即事', '姚鹓雏', '近代', '欹帻微吟试散行。江南春事在啼莺。绮怀更逗小桃明。\n\n断简间寻思蠹迹，暖帘昼卷放蜂行。绿阴庭院嫩凉生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙 其一 即事' AND p.poem_author = '姚鹓雏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长荡舟行', '郭谏臣', '明代', '芦苇烟消两岸青，湖光浩荡水云平。晴波远弄青山色，绿柳新添黄鸟声。\n\n浊酒贳来缘有约，残英落尽自无情。西山此去偏多兴，薇蕨离离绕涧生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长荡舟行' AND p.poem_author = '郭谏臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元夕雨中见雁', '费密', '清代', '野云片片接桥西，可惜年华负柳堤。江上雨来催书暝，沙中雁起觉城低。\n\n寒边无信传春翮，荒圃宜归理旧畦。浊酒一杯和泪洒，看镫犹记浣花溪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元夕雨中见雁' AND p.poem_author = '费密';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚春', '郭印', '宋代', '三月韶华破，东君谁送归。\n浮空新绿涨，舞砌乱红飞。\n柳絮风初定，桃花水渐肥。\n羲和无计挽，独立又斜晖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚春' AND p.poem_author = '郭印';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻县文教局将聘余修正音乐，以诗谢之 其一', '刘凤梧', '近代', '美人迟嫁尚含羞，况复征歌到白头。忍抱铜琶弹别调，怕携檀板唱梁州。\n\n已抛丝竹中年后，更谢铅华半世秋。漫道周郎能顾曲，宫商不叶老伶愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻县文教局将聘余修正音乐，以诗谢之 其一' AND p.poem_author = '刘凤梧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('还自南邑潮过不及渡因宿江上书所见', '许景衡', '宋代', '漫刺辞主人，迟迟驾短辕。郭外人烟晚，鸡犬自啾喧。\n\n客事足俯仰，世涂多险艰。行役亦云劳，未抵浪拘缠。\n\n潮汐真无情，敛去如绝弦。解衣试槃礴，旅雁方联翩。\n\n天末线缕动，钲鼓俄阗阗。稍看黄金盘，吞吐洪涛间。\n\n歘然洲渚失，浩荡连云天。平生喜江海，岂但眼界宽。\n\n飘流二十载，龌龊百忧煎。今夕复何夕，玉壶俯人寰。\n\n造物虽汝厄，宁不略汝怜。清风一帆去，鼓柂馀高眠。\n\n佳处良在兹，畴昔劳永叹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '还自南邑潮过不及渡因宿江上书所见' AND p.poem_author = '许景衡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书斋春日', '吕南公', '宋代', '花困蜂莺柳困风，年年春恨渺无穷。已添病格忧诗债，未破愁城忆酒功。\n\n日月正居劳苦上，山川长在梦魂中。游鞍赏席今多少，想见浓阴替乱红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书斋春日' AND p.poem_author = '吕南公';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('会饮吴石湖精舍次前韵四首 其一', '孙承恩', '明代', '吴子幽栖地，闲来荷胜招。玉舟浮白堕，翠釜映红消。\n\n菜长雨馀荚，禾抽壅后苗。知君轻俗累，雅志在耕樵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '会饮吴石湖精舍次前韵四首 其一' AND p.poem_author = '孙承恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠陶琴师', '白玉蟾', '宋代', '一雨濯旱秋滴滴，西风吹破苍苔色。\n松坛月冷夜三更，乌鹊无声露华白。\n鳌宫饮散酒杯空，万籁萧骚天变黑。\n惠然为我鼓长琴，声里胡笳十八拍。\n凄凄呜呜寒蝉鸣，黯然古涧泉琤琤。\n挑拢撚抹缓复急，远听近听如猿声。\n我生飘泊何云萍，故国关山万里程。\n君将三叠入吾耳，调中话出吾平生。\n曲罢空歌笙鹤，直欲腾身归碧落。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠陶琴师' AND p.poem_author = '白玉蟾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玄度以诗责偿卜筑之约用来韵答之', '张萱', '明代', '卖文曾办买邻金，故国移居始自今。欲向烟霞寻旧侣，况逢山水有清音。\n\n飞鸿踏雪仍留迹，倦鸟移巢却择林。莫怪绕枝犹未定，啜醨渔父已知心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玄度以诗责偿卜筑之约用来韵答之' AND p.poem_author = '张萱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('遣歌妓', '杨玢', '唐代', '垂老无端用意乖，谁知道侣厌清斋。 \n 如今又采蘼芜去，辜负张君绣靸鞋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '遣歌妓' AND p.poem_author = '杨玢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬王履震游园林见贻', '张九龄', '唐代', '宅生惟海县，素业守郊园。中览霸王说，上徼明主恩。 \n 一行罢兰径，数载历金门。既负潘生拙，俄从周任言。 \n 逶迤恋轩陛，萧散反丘樊。旧径稀人迹，前池耗水痕。 \n 并看芳树老，唯觉敝庐存。自我栖幽谷，逢君翳覆盆。 \n 孟轲应有命，贾谊得无冤。江上行伤远，林间偶避喧。 \n 地偏人事绝，时霁鸟声繁。独善心俱闭，穷居道共尊。 \n 乐因南涧藻，忧岂北堂萱。幽意加投漆，新诗重赠轩。 \n 平生徇知己，穷达与君论。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬王履震游园林见贻' AND p.poem_author = '张九龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偕张总干章帅机同游檀溪登极目和韵 其一', '李曾伯', '宋代', '底须风景叹新亭，且听樽前贱子陈。拚却玉山颓绿醑，莫将银海眩黄尘。\n\n山容似画屏环立，世事如棋局几新。惟有东风不今古，露花烟柳一般春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偕张总干章帅机同游檀溪登极目和韵 其一' AND p.poem_author = '李曾伯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送张文潜之淮南', '孔武仲', '宋代', '瀛馆登仙俊，金闺引籍优。\n辞班见天子，行色动诸侯。\n楚日篮舆暖，淮南画舸遒，\n归时春已好，迟子曲江头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送张文潜之淮南' AND p.poem_author = '孔武仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书仁里族侄佐时家庆卷后八绝 其二', '程敏政', '明代', '古来耕读两相循，立志谁堪慕有莘。闻说一犁春雨后，绿阴长作带经人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书仁里族侄佐时家庆卷后八绝 其二' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四伯父生朝集老杜句二十韵', '项安世', '宋代', '三月三日天气新，著处繁华矜是日。明日萧条尽醉醒，碧窗宿雾濛濛湿。\n\n南极老人自有星，挂君高堂之素壁。仙人玉女回云车，万草千花动凝碧。\n\n奇祥异瑞争来送，麟角凤嘴世莫识。酒肉如山又一时，满堂宾客皆叹息。\n\n正是江南好风景，苑中万物生颜色。遮莫邻鸡下五更，且将款曲终今夕。\n\n独惭投汉阁，出守吾家侄。懒慢无堪不出村，生无所成头皓白。\n\n朋知来问腆我颜，汝伯何由发如漆。红颜白面花映肉，秋水为神玉为骨。\n\n元圃苍洲莽空阔，神仙中人不易得。在于甫也何由羡，扶持自是神明力。\n\n君不见大儿聪明到，越罗蜀锦金粟尺。裁缝云雾成御衣，朝廷记忆蒙禄秩。\n\n小儿心孔开，射策君门期第一。今春喜气满乾坤，朱绂即看随画鹢。\n\n丈夫生儿有如此，百年未见欢娱毕。南极老人应寿昌，人生欢会岂有极。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四伯父生朝集老杜句二十韵' AND p.poem_author = '项安世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日游灵谷寺', '苏民怀', '明代', '一雨送微凉，千山静如沐。萧萧松桧秋，露气多芬馥。\n\n窈窕入前林，天籁应虚谷。僧梵落松涛，磬声出疏竹。\n\n陵寝压山椒，郊坛绕其麓。郁葱佳气浮，苍翠团黄屋。\n\n白鸟江上来，黑鹰下乔木。日暮返重城，兹焉想薖轴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日游灵谷寺' AND p.poem_author = '苏民怀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送人下第归吴', '寇准', '宋代', '莺老计还失，负书归故乡。\n杏园无近路，泽国有高堂。\n白鸟迷幽浦，寒猿叫夕阳。\n离怀休堕泪，春草正茫茫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送人下第归吴' AND p.poem_author = '寇准';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乱后送人归越', '朱升', '明代', '百战一身存，生还独有君。\n越山临海尽，吴地到江分。\n暮郭留晴霭，荒林翳夕曛。\n归途当岁晚，霜叶落纷纷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乱后送人归越' AND p.poem_author = '朱升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送董长史', '薛瑄', '明代', '白发交情四十春，声名又喜逐年新。江都正学师前哲，洛下长才忆古人。\n\n北阙从龙天广大，西山跋马玉嶙峋。云中到日多清兴，应有新诗寄我频。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送董长史' AND p.poem_author = '薛瑄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽祭酒胡俨母徐恭人', '胡奎', '明代', '萧峡何年挽鹿车，恭人懿德满京华。泷冈表出欧阳氏，太学文传祭酒家。\n\n夜月琴床悲别鹤，秋风宰树感慈鸦。梁园一掬宗人泪，洒向北堂萱草花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽祭酒胡俨母徐恭人' AND p.poem_author = '胡奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('览余尧辅诗因成七言四韵', '李觏', '宋代', '少年心苦向毛锥，老大生涯只有诗。哀乐万端成画缋，江山太半入炉锤。\n\n格如平易人多爱，意到幽深鬼未知。白发尚新才不尽，几时吟兴是衰时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '览余尧辅诗因成七言四韵' AND p.poem_author = '李觏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题梧桐折枝翎毛图', '刘基', '元代', '琼柯碧叶两参差，又是西风白露时。凤鸟不来嘉实晚，小禽衔上最高枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题梧桐折枝翎毛图' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('文会堂为姑苏唐以敏题', '韩雍', '明代', '新筑茅堂傍竹林，茅堂隐隐竹森森。朋簪累盍薰陶久，丽泽相资造诣深。\n\n明月半窗无俗侣，清风一曲有知音。何时归棹吴江上，共挹沧浪洗渴心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '文会堂为姑苏唐以敏题' AND p.poem_author = '韩雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游仙诗六首再寄王长公 其六', '胡应麟', '明代', '咫尺瑶坛上界分，自携真诀傍氲氤。龙蛇大陆飞丹灶，鸡犬全家住白云。\n\n种得神芝遗桂父，携将灵药寄茅君。华阳瞬息乘风到，一鹤能无洞口闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游仙诗六首再寄王长公 其六' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('朱佑', '徐钧', '宋代', '万死逃生陷敌回，功能掩过亦良才。\n君恩不是南阳旧，事业多从讲学来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '朱佑' AND p.poem_author = '徐钧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鸳鸯湖棹歌 其八十四', '朱彝尊', '清代', '仲圭旧里足淹徊，曲径横桥一水隈。小？春风认酹酒。\n\n佛香长和墓门梅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鸳鸯湖棹歌 其八十四' AND p.poem_author = '朱彝尊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('灵凤篇', '蓝仁', '元代', '鸣凤出丹穴，五采耀晴旭。朝饮瑶池流，暮栖昆山木。\n\n和声六律备，灵德百禽伏。重华去已久，淳风何由复。\n\n不闻夔乐谐，但复楚歌促。梧枝霜不蕃，竹实冬未熟。\n\n愧彼梁间燕，双双托华屋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '灵凤篇' AND p.poem_author = '蓝仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('可叹', '李商隐', '唐代', '幸会东城宴未回，年华忧共水相催。\n梁家宅里秦宫入，赵后楼中赤凤来。\n冰簟且眠金镂枕，琼筵不醉玉交杯。\n宓妃愁坐芝田馆，用尽陈王八斗才。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '可叹' AND p.poem_author = '李商隐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('聚星楼观海 其一', '林朝崧', '清代', '无数归帆趁晚潮，渔歌起处海门遥。鲻鱼秋尽将分子，更约楼头酒一瓢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '聚星楼观海 其一' AND p.poem_author = '林朝崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无题拟李商隐（四首）', '袁华', '未知', '环佩珊珊下汉皋，琼楼风度郁轮袍。\n琴心寄调传孤凤，华意留情属小桃。\n金粟柱移筝上雁，玉莲杯举掌中醪。\n乘鸾一去无消息，肠断神山梦寐劳。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无题拟李商隐（四首）' AND p.poem_author = '袁华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵怀古四首 其二', '王安石', '宋代', '天兵南下此桥江，敌国当时指顾降。山水雄豪空复在，君王神武自难双。\n\n留连落日频回首，想像馀墟独倚窗。却怪夏阳才一苇，汉家何事费罂缸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵怀古四首 其二' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次常父著作曝书之韵', '黄裳', '宋代', '内閤儒方集，先朝事不忘。曝书开绮席，偃武敛牙璋。\n\n签轴陈千古，金朱萃一堂。日华窥鸟迹，冰艳照金觞。\n\n已扫断简蠹，更增东壁光。士高閒粹语，天近览幽香。\n\n见博思唐库，恩新仰舜廊。名山才向晓，振鹭已成行。\n\n官职尘劳少，朋从语笑长。但惭甘若醴，宁恨冷如浆。\n\n小说诛瀰漫，雄文荐炜煌。培风谁有志，从此好南翔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次常父著作曝书之韵' AND p.poem_author = '黄裳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜访沧玉、锡祺寓斋作 其二', '林朝崧', '清代', '萧斋听雨夜眠迟，拈韵灯前课小诗。重叠钵声催纳卷，俨然风味棘闱时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜访沧玉、锡祺寓斋作 其二' AND p.poem_author = '林朝崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('缘识 其十', '赵炅', '宋代', '浮生人怕死，蝼蚁命何轻。福业随缘寂，慈悲响善名。\n\n在家行孝爱，食禄尽忠贞。天道不移改，佛心化有情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '缘识 其十' AND p.poem_author = '赵炅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望江南 其三', '张克家', '近代', '南市好，电影最堪娱。漆室何妨句绣舄，女墙不碍解罗襦。\n\n颜赭撤围初。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望江南 其三' AND p.poem_author = '张克家';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人 将到家作', '邹祗谟', '清代', '好风吹送蒲帆影。却把前期省。怕伊细数恁归迟。却问牡丹花剩几多枝。\n\n小楼昨夜灯花好。今日归来了。知侬生性爱天涯。便到杜鹃啼罢又离家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人 将到家作' AND p.poem_author = '邹祗谟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('许相公挽词二首 其二', '叶适', '宋代', '行露空多晓色催，夜香烧断作飞埃。松江鲙好凭谁忆，金谷花浓只自开。\n\n玉女云中应尽去，仙人雾里更重来。千年一判禁销得，涕掩寒塘错莫回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '许相公挽词二首 其二' AND p.poem_author = '叶适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过乌石大小二浪滩俗呼浪为郎因戏作竹枝歌二首 其二', '杨万里', '宋代', '小郎滩下大郎滩，伯仲分司水府关。谁为行媒教作赘，大姑山与小姑山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过乌石大小二浪滩俗呼浪为郎因戏作竹枝歌二首 其二' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天津纪乱十二首 其六', '黄遵宪', '清代', '广募楼罗历，夸强曳落河。摩云飞白燕，出地叫苍鹅。\n\n空手婆猴技，齐声天马歌。赤流呜咽水，犹逞剑横磨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天津纪乱十二首 其六' AND p.poem_author = '黄遵宪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('除夕留子上伯玉子西小酌', '杨万里', '宋代', '诸弟山行归意忙，老夫雪卧病身僵。维风及雨岁云暮，不醉无归夜未央。\n\n五盏更搀三盏么，四更偏觉五更长。也知柏酒明朝近，且为梅花尽此觞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '除夕留子上伯玉子西小酌' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('建茶 其二', '罗拯', '宋代', '草木英华聚，楼台紫翠重。山形仙苑凤，泉脉御池龙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '建茶 其二' AND p.poem_author = '罗拯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚春卧病寄张八', '孟浩然', '唐代', '南陌春将晚，北窗犹卧病。林园久不游，草木一何盛。 \n 狭迳花障迷，闲庭竹扫净。翠羽戏兰苕，赪鳞动荷柄。 \n 念我平生好，江乡远从政。云山阻梦思，衾枕劳歌咏。 \n 歌咏复何为，同心恨别离。世途皆自媚，流俗寡相知。 \n 贾谊才空逸，安仁鬓欲丝。遥情每东注，奔晷复西驰。 \n 常恐填沟壑，无由振羽仪。穷通若有命，欲向论中推。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚春卧病寄张八' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四月二日再补客司二首 其二', '郭之奇', '明代', '莫道含香旧，依然束带初。中原方羽檄，四海尚车书。\n\n典属虽无似，和容庶有馀。圣朝收敝帚，犹诏锦窠居。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四月二日再补客司二首 其二' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百二十三首 其五', '释祖钦', '宋代', '济北之道，出乎平常。语默动静，脱体全彰。三玄三要，松直棘曲。\n\n四宾四主，凫短鹤长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百二十三首 其五' AND p.poem_author = '释祖钦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('珊知浴求颂', '释正觉', '宋代', '妙触宣明不洗尘，楞严会上悟心人。\n潜鳞窟宅半篙水，枯木形骸一杓春。\n涓滴量同法界性，发毛垢净虚空身。\n南国应问聊弹指，用处绵绵谷有神。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '珊知浴求颂' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('先天易吟三十首 其二十三', '方回', '宋代', '神农尝毒药，轩后设难经。认取卦中意，仁心救未形。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '先天易吟三十首 其二十三' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过黄州', '陶安', '明代', '云窍日光红散缕，山根雾气白浮烟。黄州地暖如春半，不道今朝腊月天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过黄州' AND p.poem_author = '陶安';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次钱文伯题云林诗韵', '沈应', '明代', '红叶桥边草舍低，半滩斜照水平溪。\n旧时曾记求诗过，疏雨桐花幽鸟啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次钱文伯题云林诗韵' AND p.poem_author = '沈应';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陵祀 其二', '王世贞', '明代', '回合宫墙出，分趍礼数同。夜归千嶂里，春度百花中。\n\n列宿俱垂野，洪涛并在空。出游神意肃，石马自鸣风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陵祀 其二' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬日独醉书感八章用少陵秋兴韵 其四', '姚燮', '清代', '敢道东山少胜棋，从亡子弟已堪悲。须知毳帐听弦夕，正值冰天盼纩时。\n\n捆饷疲驴行橐橐，过云哀雁恋迟迟。荒途几处亲朋在，不耐孤灯掩泪思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬日独醉书感八章用少陵秋兴韵 其四' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('即事', '孙觌', '宋代', '落日投林去，低云贴水飞。江翻半嶂倒，帆健一风肥。\n\n酒重倾蛮榼，歌清绕妓衣。城南多胜事，何必阆中稀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '即事' AND p.poem_author = '孙觌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山村经行因施药', '陆游', '宋代', '闲行偶复到山村，父老遮留共一尊。\n曩日见公孙未晬，如今已解牧鸡豚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山村经行因施药' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送陈唐卿尉繁昌二首 其二', '周孚', '宋代', '老笔倦场屋，今年方自如。无为堕丹墨，可便废诗书。\n\n妙质嗟谁似，修涂记此初。摩挲和氏璧，吾语亦礛诸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送陈唐卿尉繁昌二首 其二' AND p.poem_author = '周孚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东园新种杂树', '刘攽', '宋代', '青苔翠竹吾人好，穿径诛茅野老家。岂为素封增橘树，还知避世种桃花。\n\n会因丛桂留骚客，却忆安榴逐汉槎。已有风光催物色，定甘羁旅待年华。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东园新种杂树' AND p.poem_author = '刘攽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('摸鱼儿·望关河', '苏泂', '宋代', '望关河、试穷遥眼，新愁似丝千缕。刘郎豪气今何在，应是九疑三楚。堪恨处。便拚得、一生寂寞长羁旅。无人寄语。但吊麦伤桃，边松倚竹，空忆旧诗句。文章事，到底将身自误。功名难料迟暮。鹑衣箪食年年瘦，受侮世间儿女。君信否。尽县簿高门，岁晚谁青顾。何如引起。任槎上张骞，山中李广，商略尽风度。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '摸鱼儿·望关河' AND p.poem_author = '苏泂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('景祐以后乐章六首 其三 章懿皇太后室奠瓒用《报安》。', '郊庙朝会歌辞', '宋代', '青金玉瓒，祼将于京。永怀罔极，夙夜齐明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '景祐以后乐章六首 其三 章懿皇太后室奠瓒用《报安》。' AND p.poem_author = '郊庙朝会歌辞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉酬鲁望夏日四声四首。平去声', '皮日休', '唐代', '怡神时高吟，快意乍四顾。村深啼愁鹃，浪霁醒睡鹭。 \n 书疲行终朝，罩困卧至暮。吁嗟当今交，暂贵便异路。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉酬鲁望夏日四声四首。平去声' AND p.poem_author = '皮日休';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山中雨望 其四', '弘历', '清代', '岩枝涧叶总沾濡，那计平畴渥也无。便是霏空势徐止，经乔木下镇垂珠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山中雨望 其四' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜起', '汪学金', '清代', '羁人起夜半，残月在四野。天风吹孤云，明星欲西下。\n\n远道苦阻艰，太息视羸马。独立黯自伤，谁念远游者。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜起' AND p.poem_author = '汪学金';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('发端州初入西江', '宋之问', '唐代', '问我将何去，清晨溯越溪。翠微悬宿雨，丹壑饮晴霓。 \n 树影捎云密，藤阴覆水低。潮回出浦驶，洲转望乡迷。 \n 人意长怀北，江行日向西。破颜看鹊喜，拭泪听猿啼。 \n 骨肉初分爱，亲朋忽解携。路遥魂欲断，身辱理能齐。 \n 畴日三山意，于兹万绪暌。金陵有仙馆，即事寻丹梯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '发端州初入西江' AND p.poem_author = '宋之问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戊辰中秋日得舍弟归信已至江口', '张宁', '明代', '宦迹茫无际，归期定已闻。素怀同月满，积思共秋分。\n\n汉傅功名异，眉翁骨肉存。白头俱永感，临见却销魂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戊辰中秋日得舍弟归信已至江口' AND p.poem_author = '张宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬日旅怀', '罗邺', '唐代', '乌焰才沈桂魄生，霜阶拥褐暂吟行。闲思江市白醪满， \n 静忆僧窗绿绮横。尘土自怜长失计，云帆尤觉有归情。 \n 几多怅望无穷事，空画炉灰坐到明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬日旅怀' AND p.poem_author = '罗邺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送潘德久使蓟门', '陆游', '宋代', '昆仑东分一枝浑，奔蹴砥柱经龙门。\n羲皇受图抚上古，神禹治水开中原。\n三灵实扶艺祖业，万国共仰东都尊。\n群儿撞坏吁可叹，顾使残虏今游魂。\n因君试求出师路，孟津白马应如故；不须更议系河桥，北风正可乘冰渡。\n颇闻卢龙已数尽，复道飞狐合屯戍；辕门倘驻拂云祠，烽火应过明妃墓。\n君归解鞍藉芳草，细谈塞北忘予老。\n读书饮酒待贼平，万丈旄头方下扫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送潘德久使蓟门' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读赵翼论诗篇有感，用原韵亦成五首 其一', '杨民仁', '近代', '一入歧途便不同，盈篇累牍总难工。迷蒙莫辨桃源渡，西去何时返棹东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读赵翼论诗篇有感，用原韵亦成五首 其一' AND p.poem_author = '杨民仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈倾一百三十三首', '释法薰', '宋代', '长沙见处虽亲用处粗，仰山口裹相呼肚裹狡。\n灼然好个大虫，可惜已伤牙爪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈倾一百三十三首' AND p.poem_author = '释法薰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上岑水岭二首 其一', '杨万里', '宋代', '危峰上面更危峰，特地无梯上碧空。遥望白云生绝顶，如今身在白云中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上岑水岭二首 其一' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋窗遣兴 其三', '吕本中', '宋代', '朝拥群书坐，所乐常自足。圣贤重出处，理本无偏曲。\n\n志行道合尊，安贫未为辱。压架富卷帙，纵情无蹐局。\n\n穷达各有时，此意当勉勖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋窗遣兴 其三' AND p.poem_author = '吕本中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('衣带岭', '刘崧', '明代', '朝辞桃源溪，暮宿衣带岭。心同秋水净，思与群山永。\n\n白云松际来，日入鸡犬静。苔藓依古垣，薜萝罥深井。\n\n天清露气肃，衣袂忽已冷。明晨当远发，我驾思夙整。\n\n西上挹高霞，蚕尖纵幽骋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '衣带岭' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上海', '赵熙', '清代', '五十年前东海滨，县门荒浦吊春申。一朝曼衍鱼龙戏，碧眼胡儿胜化人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上海' AND p.poem_author = '赵熙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('补东坡遗真姜唐佐秀才饮书其扇', '释德洪', '宋代', '此生身世两茫茫，醉里因君到故乡。沧海何曾断地脉，白袍从此破天荒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '补东坡遗真姜唐佐秀才饮书其扇' AND p.poem_author = '释德洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('瞻礼能祖肉身二首 其二', '何吾驺', '明代', '我迟未千载，不及祖生时。得接真如偈，都堪引导师。\n\n佛光犹在面，法宝可应私。倘使投针芥，传灯已在兹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瞻礼能祖肉身二首 其二' AND p.poem_author = '何吾驺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('皇太子释奠诗', '何胤', '南北朝', '灵象既分，神皇握枢。其降曰命，有书有图。化彰礼乐，教光典谟。\n\n五经夤序，七纬重敷。\n\n保氏述艺，乐正奠师。良玉缘琢，务德由咨。雅沿俗化，风移运迟。\n\n道不云远，否终则夷。\n\n下武增辉，烝哉体圣。三极彝伦，九服骘政。文以止戈，学以流镜。\n\n国崇上庠，人思下竞。\n\n昭昭储后，悊秀克明。徽若稽古，体睿申情。往行内洁，前言外清。\n\n纡光隆业，让龈胶庭。\n\n敷奥折文，悦书敦史。六诗开滞，三易机理。光耀程辉，华翻丽起。\n\n尊圣明贤，释兹敬礼。\n\n仪形初盥，容祗荐陈。罍鬯清飨，俎实芳礼。登歌奏阕，有司告神。\n\n以介景福，庆无不臻。\n\n祝史赞撤，敛圭轩燕。笙镛列阶，展声宿县。舞节金石，歌依越练。\n\n交袖折羽，流龠清殿。\n\n傧仪接贽，相诏初筵。峨峨台弁，灼灼藩蝉。时英整笏，胄子端篇。\n\n大观在上，于斯盛焉。\n\n云行雨施，品物甄流。敷荣散春，兰芬曜秋。道洽虽均，蒙固难周。\n\n进垂智效，退惭山丘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '皇太子释奠诗' AND p.poem_author = '何胤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('木瓜 其一', '金衍宗', '清代', '梨一益百损，楙一损百益。所以古之人，投之俾有获。\n\n苞苴之礼行，岂曰报可责。幡幡者惟瓠，戋戋者有帛。\n\n承筐亦几何，要在情不隔。能令受者心，生死感其德。\n\n琼琚于木瓜，奚啻过十百。敢曰报礼然，期以身许国。\n\n聊比玉之华，贡此一心赤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '木瓜 其一' AND p.poem_author = '金衍宗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六月朔得谔斋弟书 其一', '顾奎光', '清代', '闻道慈闱健，平安得汝书。别来儿女大，深忆弟兄孤。\n\n边徼犹羁宦，家山未定居。今宵归梦好，暂遣旅愁除。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六月朔得谔斋弟书 其一' AND p.poem_author = '顾奎光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和世元亲家五十自寿原韵', '刘凤梧', '近代', '归田仍是旧缁衣，辜负当年下绛帷。落拓半生同蠖屈，扶摇万里羡鹏飞。\n\n惊心明月沉沧海，回首清风在翠微。迩日京华冠盖满，几人裘马共轻肥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和世元亲家五十自寿原韵' AND p.poem_author = '刘凤梧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠海公道兄诗', '屈修', '明代', '春风吹弱柳，卧起听莺声。愁向寂中入，身从懒处成。\n\n经年蔬水味，寒夜酒杯情。别后聊搔首，无端白发生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠海公道兄诗' AND p.poem_author = '屈修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('均州南川春日三首 其三', '张舜民', '宋代', '宦名生事日悠悠，问道参禅已白头。自笑攀缘犹未断，每逢佳处即迟留。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '均州南川春日三首 其三' AND p.poem_author = '张舜民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏作', '邹浩', '宋代', '作自我作，止自我止。莫被傍人，推倒扶起。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏作' AND p.poem_author = '邹浩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题幼眉鸥水草堂诗即用留别', '曹寿铭', '清代', '我初读君诗，与君未识面。谓是古人作，舌咋目先眩。\n\n昔昔思见之，未由觌青盼。邂逅忽相遇，愕眙疑梦幻。\n\n貌疏神愈亲，象忘意无间。西陵树若荠，镜湖水如靛。\n\n东西遥相忘，伯劳与飞燕。会余来东皋，假馆比群彦。\n\n风骚嗣前轨，东中盛坛坫。君尤横无敌，跳荡恣白战。\n\n赤手搏修蛇，耿天倚长剑。意行无危途，遁状慑物变。\n\n老干芟繁条，古藻谢今艳。俗儒喜缘饰，往往肆讥讪。\n\n介然一是争，卓尔千春券。与余独神契，两载结欢忭。\n\n诗论穷毫芒，危言苦针砭。学殖愧荒落，芜秽资锄铲。\n\n砻玉攻纤瑕，锻金砺微欠。道义古所敦，方兹信不忝。\n\n所冀无乖离，昕夕共樽宴。苒苒惊流光，二曜迅飞电。\n\n揽镜搔短鬓，发容羡童丱。壮志非畴曩，頫首事薄宦。\n\n别袖发耶溪，征车指畿甸。出门愁惘惘，风雪冻两骭。\n\n飞沙欺天光，层冰滑磴栈。落日羸马嘶，荒驿敝裘绽。\n\n岂不乐朋簪，驱驰坐贫贱。何当脱尘缚，联襼遂初愿。\n\n掩卷一长嗟，遥天唳征雁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题幼眉鸥水草堂诗即用留别' AND p.poem_author = '曹寿铭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('琵琶洲', '方信孺', '宋代', '仿佛琵琶海上洲，年年常与水沉浮。\n客船昨夜西风起，应有江头商妇愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '琵琶洲' AND p.poem_author = '方信孺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵汪卿', '方岳', '宋代', '霜洗梅花春满握，夜寒吹老城头角。\n琐窗砚作离骚香，吐句不教花莫落。\n裁量要是修月手，我欲追随惭笔阁。\n平生万事不挂口，爱诗苦未厌溪壑。\n有人肯筑风骚坛，敢不束甲三距跃。\n当时只料孤凤凰，不与鸡群同抱啄。\n拔旗赵壁决此胜，金鼓俄惊自天落。\n一嗔纵得马辟易，已觉楚歌声四薄。\n夜光明月以暗投，心甚爱之颜有怍。\n公诗端似大国晋，玉帛诸侯赖联络。\n倘令吴楚主夏盟，获麟正恐春秋作。\n歙州虽小水如练，沤鸟亦知文字乐。\n此盟定自不可寒，把住梅花更商确。\n夜窗或许时过从，莫问圣清与贤浊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵汪卿' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('周宗庙歌 皇夏', '庾信', '南北朝', '雄图属天造。\n宏略遇羣飞。\n风云犹听命。\n龙跃遂乘机。\n百二当天险。\n三分拒乐推。\n函谷风尘散。\n河阳氛雾晞。\n济弱沦风起。\n扶危颓运归。\n地纽崩还正。\n天枢落更追。\n原祠乍超忽。\n毕陇或绵微。\n终封三尺剑。\n长卷一戎衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '周宗庙歌 皇夏' AND p.poem_author = '庾信';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过田家宅', '杜牧', '唐代', '安邑南门外，谁家板筑高。奉诚园里地，墙缺见蓬蒿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过田家宅' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送杨方叔还山二首', '姜特立', '宋代', '可人自是难招唤，此去相从定几时。\n来岁春风暖行色，隐侯楼上要题诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送杨方叔还山二首' AND p.poem_author = '姜特立';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('举罽宾国王问师子尊者蕴空公案颂', '释鉴', '宋代', '尊者何曾得蕴空，罽宾徒自斩春风。\n桃花雨后已零落，染得一溪流水红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '举罽宾国王问师子尊者蕴空公案颂' AND p.poem_author = '释鉴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋见月寄子瞻', '苏辙', '宋代', '西风吹暑天益高，明月耿耿分秋毫。\n彭城闭门青嶂合，卧听百步鸣飞涛。\n使君携客登燕子，月色着人冷如水。\n筵前不设鼓与钟，处处笛声相应起。\n浮云卷尽流金丸，戏马台西山郁蟠。\n杯中渌酒一时尽，衣上白露三更寒。\n扁舟明日浮古汴，回首逡巡陵谷变。\n河吞巨野入长淮，城没黄流只三版。\n明年筑城城似山，伐木为堤堤更坚。\n黄楼未成河已退，空有遗迹令人看。\n城头见月应更好，河流深处今生草。\n子孙幸免鱼鳖食，歌舞聊宽使君老。\n南都従事老更贫，羞见青天月照人。\n飞鹤投笼不能出，曾是彭城坐中客。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋见月寄子瞻' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书言母丁夫人传后', '郑孝胥', '清代', '积诚能动天，此理难悉究。疗疾既无策，刲股岂能救？\n\n事急天亦穷，神识转昏瞀。谬云诚可格，愚孝空蒙诟。\n\n夫人有高才，智出妇女右。胡为屡出此，不脱儒者陋。\n\n智尽诚乃见，至行世罕觏。莫疑天无知，食报在其后。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书言母丁夫人传后' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早出左掖过刘太史衍亨观经筵越裳二赋郊祀庆成诸诗', '欧大任', '明代', '银鞍初系马，爱客一筵同。袖出河东赋，杯行碣石宫。\n\n辛盘花并綵，藜杖火犹红。何日看重席，谈经汉侍中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早出左掖过刘太史衍亨观经筵越裳二赋郊祀庆成诸诗' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送朱丞', '王十朋', '宋代', '一片秋怀似乱云，不堪行客话离群。红莲绿水尚留我，钜竹老槐深忆君。\n\n千里从今遥共月，一樽何日更论文。好将平昔家传学，勉力登朝立世勋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送朱丞' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '武允蹈', '宋代', '露萱钳宿蝶，风木撼鸣鸠。\n屋头风过雁，灯背月移窗。\n霜林五色锦，烟渡一萦丝。\n午簟展风供睡课，夜窗扃雨办诗逋。\n眼昏书字不著纸，耳重听言常问人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '武允蹈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜渡湘水', '童珮', '明代', '若为乘夜渡，贪涉此山川。\n水自三湘合，云知七泽连。\n蛩声暗秋色，雁语杂寒烟。\n莫问黄陵庙，门前断客船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜渡湘水' AND p.poem_author = '童珮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('海夷八首 其五', '王稚登', '明代', '金陵亦是开基地，虎踞龙盘旧业存。先帝寝园犹白鹿，功臣甲第自朱门。\n\n冶城烟垒秋风肃，淮水金铙片月昏。太傅元勋藏上册，肯令妖祲近中原。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '海夷八首 其五' AND p.poem_author = '王稚登';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟古寄何大卿六首 其二', '谢翱', '宋代', '雄雌双碧鸡，所食琪树蘤。来栖药洞中，当春怕乳子。\n\n其雌秋别时，守此唯雄耳。可怜衔子归，万里渡海水。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟古寄何大卿六首 其二' AND p.poem_author = '谢翱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菜圃', '杨万里', '宋代', '此圃何其窄，於侬已自华。\n看人浇白菜，分水及黄花。\n霜熟天殊暖，风微旆亦斜。\n笑摩挑竹杖，何日拄还家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菜圃' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('用梁斗南韵', '耶律楚材', '元代', '丁年学道道难成，却得中原浪播名。否德自惭调鼎鼐，微才不可典玑衡。\n\n谁知东海潜姜望，好向南阳起孔明。收拾琴书作归计，玉泉佳处老馀生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '用梁斗南韵' AND p.poem_author = '耶律楚材';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('伤春曲', '许棐', '宋代', '日日望郎郎未归，玉肌宽尽缕金衣。春心撩乱强拘束，碎剪红绡补旧枝。\n\n红绡才向枝头住，残花又逐东风去。愿花飞入笑筵中，莫入愁人断肠处。\n\n愁人见花人自羞，花见愁人花也愁。花飞有尽愁无尽，柳外一声黄栗留。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '伤春曲' AND p.poem_author = '许棐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行住坐卧三十二颂', '释印肃', '宋代', '几番舒卷济群迷，马祖升堂百丈知。\n由是那时通一红，而今收放莫令迟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行住坐卧三十二颂' AND p.poem_author = '释印肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高中毕业聚餐会后口占三绝 其三', '叶嘉莹', '当代', '握别灯阑夜已分，一弯斜月送归人。他年若作儿时忆，回梦春风此最真。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高中毕业聚餐会后口占三绝 其三' AND p.poem_author = '叶嘉莹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游精思观回，王白云在后', '孟浩然', '唐代', '出谷未停午，到家日已曛。回瞻下山路，但见牛羊群。 \n 樵子暗相失，草虫寒不闻。衡门犹未掩，伫立望夫君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游精思观回，王白云在后' AND p.poem_author = '孟浩然';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送谢元吉御史赴南陵丞二首 其一', '周瑛', '明代', '风雪飘摇满帝城，老鸦台上噤无声。南陵草色春长满，疋马徐行好问耕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送谢元吉御史赴南陵丞二首 其一' AND p.poem_author = '周瑛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩提寺', '罗公升', '宋代', '一亩方池几劫灰，哭声未了笑声催。\n六桥烟桥相逢处，半是菩提拭泪来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩提寺' AND p.poem_author = '罗公升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戊寅初度', '黄公辅', '明代', '且得烽烟息，官闲心亦闲。悠悠岁月里，卓卓利名关。\n\n谢客看莪蓼，戏孙弄彩斑。情随鸥鸟去，无日不溪湾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戊寅初度' AND p.poem_author = '黄公辅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('齐天乐五十首 其十三', '端木埰', '清代', '小窗虚幌明于画，幽栖别饶佳胜。斜汉流天，纤云让月，三五流星耿耿。\n\n苔阶翠冷，又风飐流萤。一灯青映。渐有蛩吟，秋意悄然出莎径。\n\n更筹听过四转，镇澄思息虑，宛入禅定。万籁无声，三霄自碧，一味新凉初迎。\n\n甘芳沁茗。早浣尽尘襟，太虚同净。为相词仙，素心应共领。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '齐天乐五十首 其十三' AND p.poem_author = '端木埰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('华元洞', '卢龙云', '明代', '一入华元洞，方知境界清。荆榛何代辟，门户总天成。\n\n地迥尘难到，室虚白亦生。野僧能供佛，那得罢逢迎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '华元洞' AND p.poem_author = '卢龙云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十五日云阴凉尤甚再赋长句', '陆游', '宋代', '褦襶京尘触热行，岂知世有野堂清。\n磑茶落雪睡魔退，激水跳珠凉意生。\n亹亹清风随麈柄，悠悠长日付棋枰。\n小舟先向苹汀泊，浴罢还须泛月明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十五日云阴凉尤甚再赋长句' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题明轩', '华镇', '宋代', '两楹开处面纯离，题作明轩得事宜。计利已居人会地，征商还是日中时。\n\n平持刀尺无心用，高倚权衡莫我欺。达识主人元有大，谁知细故亦无遗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题明轩' AND p.poem_author = '华镇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵少稷梅花', '韩元吉', '宋代', '君不见江城梅花春欲动，剪冰仙人作花供。\n客来酒尽甘啜醨，常恨公田无秫种。\n雪晴梅蕊更可爱，百匝来看地犹冻。\n杖藜一笑答春风，岂必鸣鸾与歌凤。\n幽香要自己心情，冷艳不禁还目送。\n兴来往往得佳句，落纸挥毫字尤纵。\n却惊车阵有勍敌，旋结赵叟盟衡雍。\n孤芳未省须刻画，百卉应先厌嘲弄。\n我如蟋蟀鸣甘迟，君似骅骝骤难控。\n相如上林晚奏雅，灵均喜橘工记讽。\n不妨聊继广平公，东阁疏枝与君共。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵少稷梅花' AND p.poem_author = '韩元吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出塞', '杨炯', '唐代', '塞外欲纷纭，雌雄犹未分。明堂占气色，华盖辨星文。 \n 二月河魁将，三千太乙军。丈夫皆有志，会见立功勋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出塞' AND p.poem_author = '杨炯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('双鱼谣', '贾岛', '唐代', '天河堕双鲂，飞我庭中央。掌握尺余雪，劈开肠有璜。\n见令馋舌短，烹绕邻舍香。一得古诗字，与玉含异藏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '双鱼谣' AND p.poem_author = '贾岛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人 和彊村先生韵', '王理孚', '近代', '云边多少楼台起。谁惜三弓地。飘萧华发不胜簪。倚遍阑干曲曲是何心。\n\n痴情愿向花间老。蓦地生烦恼。迷离蝶梦几曾真。偏逐东风似虎送残春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人 和彊村先生韵' AND p.poem_author = '王理孚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋兴三首 其二', '苏轼', '宋代', '故里依然一梦前，相携重上钓鱼船。尝陪大幕全陈迹，谬忝承明愧昔年。\n\n报国无成空白首，退耕何处有名田。黄鸡白酒云山约，此计当时已浩然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋兴三首 其二' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('保宁勇和尚赞', '释智遇', '宋代', '怀燥衲僧，佒佯座主。\n抹过村草步头，直下挨肩佛祖。\n杨岐其师，白云其侣。\n一鸣凤台，凌跨今古。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '保宁勇和尚赞' AND p.poem_author = '释智遇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送吴推官', '韩淲', '宋代', '执友曹器远，高才步瑶京。许予非词伯，只字罔敢轻。\n\n因君官玉溪，乃曰能诗声。梦寐于苏黄，处家义利明。\n\n尺书既宛转，满纸仍丁宁。自是得往还，吟边亦飞觥。\n\n苦值公事劳，无暇详考评。但知醉言舞，谈谐到忘形。\n\n忽焉秩满归，岁月流电经。怀抱信舒卷，物态何枯荣。\n\n新凉起风樯，石浅滩濑清。推蓬试踌躇，正尔候虫鸣。\n\n行行钱塘湖，悠哉故人情。器远如相忘，为说华发生。\n\n君之赵子野，惜未同鸥盟。所赋定益奇，南北两山横。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送吴推官' AND p.poem_author = '韩淲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('途中次子烜韵 其二', '张以宁', '明代', '微官与志违，空负圣明时。对酒怀彭泽，题诗愧渼陂。\n\n遥天和树尽，断岸逐舟移。杨柳黄金色，随春入砚池。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '途中次子烜韵 其二' AND p.poem_author = '张以宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋夜同友人话旧', '谭用之', '唐代', '露下银河雁度频，囊中垆火几时真。数茎白发生浮世， \n 一盏寒灯共故人。云外簟凉吟峤月，岛边花暖钓江春。 \n 何当归去重携手，依旧红霞作近邻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋夜同友人话旧' AND p.poem_author = '谭用之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('后凯歌词九首 其四 翁科', '耶律铸', '元代', '蜂屯蚕簇乱山窝，蚁动鹑居乱草坡。沾体露形千万指，恳祈天语许降和。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '后凯歌词九首 其四 翁科' AND p.poem_author = '耶律铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十二月一日三首', '杜甫', '唐代', '今朝腊月春意动，云安县前江可怜。一声何处送书雁， \n 百丈谁家上水船。未将梅蕊惊愁眼，要取楸花媚远天。 \n 明光起草人所羡，肺病几时朝日边。 \n 寒轻市上山烟碧，日满楼前江雾黄。负盐出井此溪女， \n 打鼓发船何郡郎。新亭举目风景切，茂陵著书消渴长。 \n 春花不愁不烂漫，楚客唯听棹相将。 \n 即看燕子入山扉，岂有黄鹂历翠微。短短桃花临水岸， \n 轻轻柳絮点人衣。春来准拟开怀久，老去亲知见面稀。 \n 他日一杯难强进，重嗟筋力故山违。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十二月一日三首' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹', '朱放', '唐代', '青林何森然，沈沈独曙前。出墙同淅沥，开户满婵娟。 \n 箨卷初呈粉，苔侵乱上钱。疏中思水过，深处若山连。 \n 叠夜常栖露，清朝乍有蝉。砌阴迎缓策，檐翠对欹眠。 \n 迸笋双分箭，繁梢一向偏。月过惊散雪，风动极闻泉。 \n 幽谷添诗谱，高人欲制篇。萧萧意何恨，不独往湘川。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹' AND p.poem_author = '朱放';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五贶诗。华顶杖', '皮日休', '唐代', '金庭仙树枝，道客自携持。探洞求丹粟，挑云觅白芝。 \n 量泉将濯足，阑鹤把支颐。以此将为赠，惟君尽得知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五贶诗。华顶杖' AND p.poem_author = '皮日休';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('漫书五首 其二', '司空图', '唐代', '溪边随事有桑麻，尽日山程十数家。莫怪行人频怅望，杜鹃不是故乡花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '漫书五首 其二' AND p.poem_author = '司空图';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('后割肉诗为汪孝妇作', '屈大均', '明代', '新妇前割肉，割肉为翁痡。翁苦膈食人，腹中粒米无。\n\n门前十万寇，杀人肝脑涂。无从乞针药，鬼伯方呜呜。\n\n救死何所有，所有惟肌肤。翁命系新妇，气绝只须臾。\n\n抽刀向左臂，虽羸犹膏腴。一脔大逾寸，重可二十铢。\n\n非方亦非圆，圭璧良不殊。血裹若绛雪，猩猩红不如。\n\n聂切作和羹，翁食能无馀。胸膈忽荡开，病瘳不待晡。\n\n贼众闻却走，毋犯孝妇闾。邻里竞来视，各请翁所需。\n\n馈食悉精美，餍饫翁不臞。夫时在邗沟，亲友皆来趋。\n\n夫名以妇知，称妇因称夫。不知夫视妇，芬芳长与俱。\n\n无何先朝露，夫溘归黄垆。讣闻不欲生，欲殉忧诸孤。\n\n呱呱尚可弃，堂上有舅姑。舅姑岂盘石，身衰同秋蒲。\n\n匍匐灵柩前，奠馔无蒸雏。抽刀再割肉，右臂白如瓠。\n\n左臂创末平，刀口成痈疽。疗翁未死前，割肉犹不辜。\n\n夫既已奄逝，割肉何所图。肉岂惊精丸，刀圭魂昭苏。\n\n三日苟不生，神即幽酆都。割之等泥土，祗自戕罗敷。\n\n念己活君舅，天理庶不诬。为夫惜一脔，恩义何次且。\n\n报生复报死，所捐非全躯。腥臊不足食，差胜充庖厨。\n\n皇天令不死，五十犹勤劬。二男已成立，干禄知读书。\n\n母肉尚馀几，一身半菀枯。在母如鸿毛，宁如惨自屠。\n\n在舅如泰山，返魂因彼姝。在夫即牲牷，肥腯逾羊酥。\n\n吁嗟夫在外，不得亲口珠。尊章与藁砧，骨肉何亲疏。\n\n九泉歆此羹，味淡同瓜菹。十年不同食，所嗜忘其初。\n\n忍死更几时，同穴宁踟蹰。为寿讵忍言，儿女徒欢娱。\n\n未忘至百岁，蜉蝣归其居。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '后割肉诗为汪孝妇作' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('即事呈斯远三首', '赵蕃', '宋代', '一花固觉有余香，况此寒梢数尺长。\n怪底诗来总清绝，始知逸韵与相当。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '即事呈斯远三首' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('斜径', '王安石', '宋代', '斜径偶通南埭路，数家遥对北山岑。草头蛱蝶黄花晚，菱角蜻蜓翠蔓深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '斜径' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽陈巡检', '吴芾', '宋代', '夫君端是一时豪，排难捐躯不惮劳。\n忠义自能全里社，姓名那肯辱铨曹。\n一生倜傥心常逸，五世团栾寿更主。\n瞑目定知无可憾，九原风树漫悲号。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽陈巡检' AND p.poem_author = '吴芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再领宫祠', '李正民', '宋代', '流落天涯任转蓬，三千窃禄愧无功。身游乌帽黄尘外，名在丹台紫府中。\n\n赖有俸钱优白傅，且教閒处着司空。挥毫拟就归田赋，检点山资苦未丰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再领宫祠' AND p.poem_author = '李正民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雷门吟', '赵黻', '清代', '余姚有余霖，四十老一衿。谒我蕺山麓，涕出悲不任。\n\n谓公今诗史，乞为雷门吟。我兄名曰震，雷门乃其字。\n\n霖生托遗腹，母老欲见弃。兄嫂争乳之，兄怙嫂则恃。\n\n母亡霖六龄，九龄兄授经。霖愚复多病，支拄求蔘苓。\n\n病则夺书笈，愈则还镫檠。欲继先子业，恐伤予季情。\n\n回忆七龄时，兄子同病疡。戒嫂善视叔，叔愈他何伤。\n\n日夕嫂抱持，兄子掷在床。我啼嫂则泣，我笑兄则欢。\n\n三十授弟室，黾勉庠序间。嗟我衣上线，嫂泪存斑斑。\n\n嗟我笥中书，手泽兄丹铅。兄嫂六十没，合葬上林村。\n\n南山宋家隩，有我兄嫂坟。兄以贫废学，为医活千人。\n\n活者恸兄死，安得赎其身。霖困蓬蒿中，惧掩兄嫂贤。\n\n椎心泣血辞，愿公采斯言。我为一一书，孝义至斯止。\n\n愧彼尺布谣，用以资国史。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雷门吟' AND p.poem_author = '赵黻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '陈宓', '宋代', '君自成龙我成道。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '陈宓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同乐天和微之深春二十首 其八', '刘禹锡', '唐代', '何处深春好，春深刺史家。夜阑犹命乐，雨甚亦寻花。\n\n傲客多凭酒，新姬苦上车。公门吏散后，风摆戟衣斜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同乐天和微之深春二十首 其八' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送张升之四首 其三', '项安世', '宋代', '昔年常恨李白杜甫不相从，又见韩愈孟郊恨不如云龙。\n\n我今与子别，正与二子同。我在大江北，君归五湖东。\n\n我犹作楚客，君复为吴侬。江湖吴楚休相忆，青云有路各努力。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送张升之四首 其三' AND p.poem_author = '项安世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴淞道中', '杨寿杓', '近代', '十年浪迹类萍花，九渡沧溟兴未赊。满眼江南桑苧好，樱桃时节又天涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴淞道中' AND p.poem_author = '杨寿杓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄陈正已', '曾极', '宋代', '十载忧近发半华，东山有意净胡沙。\n公车战策三千牍，腹笥兵书五十家。\n好佩青萍光夺月，莫惊赤羽气成霞。\n嗟予本亦轻生者，欲渡黄海掷马挝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄陈正已' AND p.poem_author = '曾极';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('魏昭父惠新刻李西台诸公帖二首 其二', '赵蕃', '宋代', '翰墨要知真有种，怪来下笔每多姿。不如家学相传授，玉轴锦囊皆得师。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '魏昭父惠新刻李西台诸公帖二首 其二' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('生查子 自题秋夜图', '葛秀英', '清代', '残夜碧天明，月挂梧桐井。小院寂无人，满地芭蕉影。\n\n银汉已横斜，独立衣裳冷。不忍负良宵，自煮天池茗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '生查子 自题秋夜图' AND p.poem_author = '葛秀英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '杨维桢', '元代', '安危岂料关天步，生死犹能系俗情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '杨维桢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('齐天乐', '周岸登', '清代', '好词绝妙中郎字，输他外孙勤护。凤纸收香，乌丝渍墨，寥落丁年词赋。\n\n花閒剩语。更休说承平，断歌零舞。便有千秋，半埋尘箧半侵蠹。\n\n遗编曾读晚学，故乡归去久，仙掌成墓。赣水游踪，黄山坠魄，应觅滁槎奇句。\n\n灵风且驻。料当日楹书，未传娇女。望古茫茫，怨吟邀梦雨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '齐天乐' AND p.poem_author = '周岸登';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('守岁侍宴应制', '杜审言', '唐代', '季冬除夜接新年，帝子王孙捧御筵。宫阙星河低拂树， \n 殿廷灯烛上薰天。弹弦奏节梅风入，对局探钩柏酒传。 \n 欲向正元歌万寿，暂留欢赏寄春前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '守岁侍宴应制' AND p.poem_author = '杜审言';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('月下果饮七首 其二', '杨万里', '宋代', '酒边无物伴长瓶，一颗新莲一段冰。月下不风终是爽，烛光何罪也堪憎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '月下果饮七首 其二' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('除夜张功父惠诗索荆溪集次韵送往', '杨万里', '宋代', '早往荆溪集，应无桂隐诗。梅边五字律，管底一斑窥。\n\n新岁来朝是，流年去浪移。谁能守除夕，妨我梦归时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '除夜张功父惠诗索荆溪集次韵送往' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏怀呈诸同社 其三', '佘翔', '明代', '夙昔飞扬态，年华去不留。七星空佩剑，五月尚披裘。\n\n翰墨非长技，稻粱那自谋。江潭天地意，枯槁未应愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏怀呈诸同社 其三' AND p.poem_author = '佘翔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新会张明府惕庵以予将去粤有诸生无福之叹予皇恐不敢当也 其一', '全祖望', '清代', '泰山不作文昭逝，方信人师绝世无。自分衰残天所废，散耽栈豆误生徒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新会张明府惕庵以予将去粤有诸生无福之叹予皇恐不敢当也 其一' AND p.poem_author = '全祖望';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观陵', '项安世', '宋代', '晚艇村村载，秋原处处收。\n年来尤爱此，一熟缓千尤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观陵' AND p.poem_author = '项安世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自题履错集赠王伟东', '秦鸿', '当代', '盘磐石径如波漾，司命杳茫安可访。记取春山脚底寒，与君并坐松风上。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自题履错集赠王伟东' AND p.poem_author = '秦鸿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长汀即事', '高元之', '宋代', '杨花剩得晴方好，榆荚其如世上分。\n花向喜中看更好，分明春色解欺人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长汀即事' AND p.poem_author = '高元之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('锦堂春慢', '添雪斋', '当代', '青墨云笺，新词古调，禅心蝶梦兼收。记取人间，肠断未必于秋。\n\n薄倖自风吹入，故苑花底难留。换一川碧水，老尽垂杨，残月如钩。\n\n我因词中悲语，尽空成乱呓，始托无忧。君又痴情何苦？\n\n更惹眉愁。且看西窗烛影，在此夜、焚却还休。纵有千般泪咽，而后从今，不向人流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '锦堂春慢' AND p.poem_author = '添雪斋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('台城路 春草，和玉林、咏雩', '黄祝蕖', '近代', '平芜一带寒烟抹。啼螀怕闻凄咽。燕子归来，芹泥依旧，何处六朝宫阙。\n\n斜阳似血。剩几寸残山，烧痕明灭。旧日王孙，青青两鬓渐成雪。\n\n清明又过几日。更黄昏细雨，教人愁杀。金粟堆边，玉钩斜畔，怎自年年不绝。\n\n归心欲折。便绿到天涯，倍添悽切。南浦萋萋，只供人赋别。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '台城路 春草，和玉林、咏雩' AND p.poem_author = '黄祝蕖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠别李子翀之金陵七首 其四', '刘崧', '明代', '龙蟠梵王宅，钟阜出南东。一水天光限，诸峰雾气通。\n\n幡幢低晚树，钟磬下晴空。茆屋如堪赋，能忘讯已公。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠别李子翀之金陵七首 其四' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('明季咏史十三首 其一', '张笃庆', '清代', '倦勤当日说神宗，高卧深严秘九重。玉辇经时登汉阙，鸾章隔岁下尧封。\n\n千官补缺虚龙衮，四海军储废大农。纵使养痈终必溃，乾坤无恙且从容。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '明季咏史十三首 其一' AND p.poem_author = '张笃庆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻曾幼度近况于陈择之作二诗觅使寄之', '赵蕃', '宋代', '夜醉江天阁，赋诗殊未央。\n自兹悲契阔，谁复慰凄凉。\n有抱何由写，因诗得寄将。\n丁宁赣江水，莫惮溯流长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻曾幼度近况于陈择之作二诗觅使寄之' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送都大茶马入觐八绝句 其一', '项安世', '宋代', '六月长江白水秋，夜寒银汉入江流。台星直下穿云梦，知是西来使者舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送都大茶马入觐八绝句 其一' AND p.poem_author = '项安世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七言和陈和叔秘阁会话', '沈遘', '宋代', '群玉嵯峨压石渠，我初通籍预雠书。三年未压承明直，一日更从俗吏居。\n\n对案不堪文墨弊，离群长恨笑言疏。紫宸蚤退春朝永，时得期君过旧庐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七言和陈和叔秘阁会话' AND p.poem_author = '沈遘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('剑歌行', '严羽', '宋代', '剑歌行，借君剑，为君舞。自古英雄重结交，樽酒相逢气相许。\n\n爱君倜傥不可羁，与君一见心无疑。疏眉大颡长七尺，神彩照耀仍虬髭。\n\n雄词落纸走山岳，霹雳绕壁蛟龙随。如何十载困羁旅，此心独未时人知。\n\n去年从军杀强虏，举鞭直解扬州围。论功不及骠骑幕，失路羞逐边城儿。\n\n归来宝刀挂空壁，白光夜夜惊虹蜺。椎牛酾酒且高会，酣歌击筑焉能悲。\n\n百年快意当若此，迂儒拳局徒尔为。我亦摧藏江海客，重气轻生无所惜。\n\n关河漂荡一身存，宇宙茫茫双鬓白。到处犹吟然诺心，平时错负纵横策。\n\n海内交游四五人，近来得尔情相亲。情相亲，两相托，生死交情无厚薄。\n\n别君去，还留连，愿剖肝胆致君前。人生感激在知己，男儿性命焉足怜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '剑歌行' AND p.poem_author = '严羽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('近事诚答南国诗友', '张月宇', '当代', '何得工余趁此闲，只缘颦效老童顽。言沉游侠胸中垒，词赠佳人鬓上环。\n\n一剑易穿吴帝甲，五丁难破蜀都山。屏前自识吾情性，大笑三声天地宽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '近事诚答南国诗友' AND p.poem_author = '张月宇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九日香港太平山上', '潘受', '近代', '独客他山逢九日，了无人共菊花杯。云争子美胸前荡，秋自安仁鬓畔来。\n\n一舸南浮思赤道，中原北望但黄埃。凭高始信鸥波阔，未羡鱼龙曼衍才。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九日香港太平山上' AND p.poem_author = '潘受';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吊齐斋先生尚书文节倪公 其四', '程公许', '宋代', '风尘日骚屑，耆哲晨星稀。九原不可作，斯文今谁归。\n\n临风想孤标，把酒哦落晖。扁刻见尚友，雪堂密传衣。\n\n归帆拂蘋波，晴烟抹松扉。满箧贮宝刻，展诵省昨非。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吊齐斋先生尚书文节倪公 其四' AND p.poem_author = '程公许';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('紫云洞', '员兴宗', '宋代', '君不见茂州长史文章翁，生平姓字悬天东，\n英言撼帝帝不从，建隆以来无此忠。\n今焉栖神寓玄躬，道在翳嘶峰外之高峰。\n是间真趣排天胸，指顾可了荆岱嵩，\n迩年秋练春光融，离离渡汉舒溟蒙。\n状殊宋车非越龙，亦非石壁浮青红。\n望之云远讨其踪，类风飘烟欺雾浓，\n直排阊阖贯紫宫。父老语我昭我聋，\n疑是先生不掩之精雄。自尔支拄琼崖中，\n要把英爽飞摩空。有如韩王结襦腾腾化异气，\n亦如卫生食昂叠叠欺长虹。诚於斯民有愿力，\n此段奇特将无同。先生英名无有尽，\n乃云无心洞无穷。或云砻凿发天秘，\n不知的的胜事符阿戎。劝君不必昆阆通，\n五云之祥由李宗。君家种义昭玄穹，\n可隶黄字驱青童。扫洒愿勿俗子容，\n斗酒为嗔王无功。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '紫云洞' AND p.poem_author = '员兴宗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过客相寻', '杜甫', '唐代', '穷老真无事，江山已定居。地幽忘盥栉，客至罢琴书。 \n 挂壁移筐果，呼儿问煮鱼。时闻系舟楫，及此问吾庐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过客相寻' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('枫桥夜泊', '董纪', '明代', '野店沽来酒欠浓，客愁今夜又相逢。江枫渔火都禁得，只怕寒山寺里钟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '枫桥夜泊' AND p.poem_author = '董纪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('都竹道中', '韦骧', '宋代', '阴平才过万山重，路指江油栈阁通。峰顶云收馀夕雪，马蹄尘少带春风。\n\n一溪水色琉璃碧，几坞梅花锦绣红。莫谓奔驰足劳苦，目前佳趣亦无穷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '都竹道中' AND p.poem_author = '韦骧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寒食出郊', '谢薖', '宋代', '水晴鸥弄影，沙软马惊尘。密竹斜侵径，幽花乱逼人。\n\n深行听格磔，倦憩倚轮囷。往事悲青冢，年年芳草新。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寒食出郊' AND p.poem_author = '谢薖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('燕京绝句 其二', '梵琦', '元代', '漆园山下葬车尘，冷水潭边拜扫人。一种白杨千万叶，空令儿女泪沾巾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '燕京绝句 其二' AND p.poem_author = '梵琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽黄行中检讨', '杨士奇', '明代', '霜霰零琼树，天寒一夕摧。竟如东逝水，无复却西回。\n\n世数金闺彦，人思玉署才。旧时来往路，重过不胜哀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽黄行中检讨' AND p.poem_author = '杨士奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题萧佥宪君亲觐省卷', '林光', '明代', '纲常任重寄吾身，上有明君下有亲。一事却求兼二美，寸心端合质诸神。\n\n绯袍待转金门漏，舞袖翻回蜀道春。点检平生扶善意，更将忠孝许何人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题萧佥宪君亲觐省卷' AND p.poem_author = '林光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('仁老寄墨梅 其三', '邹浩', '宋代', '前年谪向新州去，岭上寒梅正作花。今日霜缣玩标格，宛然风外数枝斜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '仁老寄墨梅 其三' AND p.poem_author = '邹浩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔栖辞', '刘崧', '明代', '苍林兮碧溪，我渔兮我栖。朝鸣榔于中泽兮，夕余济于澨西。\n\n波洄沿兮不可以倏迷，路窈窕兮风凄凄。反予遵兮故蹊，云鳞鳞兮不可以隮。\n\n漱白石兮藉芳荑，悄空谷其无人兮，见翩翩之凫鹥。\n\n志逸而嬉兮得丧以齐，纶不必施兮彼笭箵又焉足赍。\n\n乐哉洋洋兮，吾乌知尔之为鲦鲿为鲸鲵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔栖辞' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二月二日作', '温训', '清代', '雨歇静群绿，微风向晚柔。野村寒瓦湿，炊烟郁不流。\n\n都养亦何事，鹤立望江头。沙平白若雪，水净碧于油。\n\n竹坞喧栖鸟，樵径见归牛。几年劳远役，及兹始息陬。\n\n素心澹无著，山斋洁以幽。拟伴荷锄老，社事宴春秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二月二日作' AND p.poem_author = '温训';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题金耑居为陈羽伯画竹居图次张观复先生韵', '龚诩', '明代', '明月清风境界宽，不栽凡卉只琅玕。庭除剩有三湘意，枕簟能无六月寒。\n\n时见啄苔来缟鹤，每惊拂石舞青鸾。故人诗画俱清绝，可得频过一借看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题金耑居为陈羽伯画竹居图次张观复先生韵' AND p.poem_author = '龚诩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鱼篮观音赞', '释智朋', '宋代', '徒整春风两鬓垂，子规啼遍落花枝。龙门上客家家是，锦鲤携来卖与谁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鱼篮观音赞' AND p.poem_author = '释智朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元日送客归西湖', '释居简', '宋代', '采笔春消御柳边，棹歌忽听采菱船。三贤见说迁居了，只寄梅花问水仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元日送客归西湖' AND p.poem_author = '释居简';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四月二十日书二首 其二', '张耒', '宋代', '久将醉眼视群儿，只与旁观作笑嘻。赋芋狙公曾未悟，牵丝木偶几多时。\n\n云间炎景人方畏，地下微阴谁得知。荣谢古今同此理，老翁端坐但忘机。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四月二十日书二首 其二' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('初夏走笔和湘灵', '沈天孙', '明代', '旖旎薰风柳乍醒，榴花刺眼媚遥汀。\n傍人桐树枝枝绿，出水荷钱叶叶青。\n陇外乔桑飞雊雉，阶前茂草隐新萤。\n春从杜宇声中去，空翠浓阴又满庭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '初夏走笔和湘灵' AND p.poem_author = '沈天孙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古乐府 其一', '程垣', '宋代', '长安花如锦，不堪制郎衣。拾得并州剪，剪花花忽飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古乐府 其一' AND p.poem_author = '程垣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题赵仲穆小景', '王称', '明代', '疏烟淡月大堤傍，远树连墙接水乡。子夜吴歌惊宿鹭，风流宛似赵家庄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题赵仲穆小景' AND p.poem_author = '王称';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送吴二少陆归洞庭山省亲 其二', '谢榛', '明代', '鹤发相辉堂上人，吴天遥望瑞云新。洞庭酒熟梅花发，同醉沙村几树春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送吴二少陆归洞庭山省亲 其二' AND p.poem_author = '谢榛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('柳梢青', '周密', '宋代', '万雪千霜。禁持不过，玉雪生光。水部情多，杜郎老去，空恼愁肠。 \n 天寒野屿空廓。静倚竹、无人自香。一笑相逢，江南江北，竹屋山窗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '柳梢青' AND p.poem_author = '周密';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题雪窗兰蕙同芳图', '张以宁', '明代', '春来骚意满江干，转蕙风光更泛兰。睡起老禅闲一笑，月明香雪竹窗寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题雪窗兰蕙同芳图' AND p.poem_author = '张以宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('草堂前芙蓉正吐口占数绝为别 其五', '朱浙', '明代', '不耐清秋怀远途，草堂坐觉旅怀孤。捲帘月上芙蓉影，便是人间送别图。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '草堂前芙蓉正吐口占数绝为别 其五' AND p.poem_author = '朱浙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('映碧园产并头莲三十首 其十五 十四盐', '孙传庭', '明代', '俱饶清远致，相并不相嫌。目岂学鱼比，翼非效鸟鹣。\n\n总缘头角异，奚但色香兼。若作芙蓉锷，应劳紫气占。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '映碧园产并头莲三十首 其十五 十四盐' AND p.poem_author = '孙传庭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题扇次倪良弼稽勋韵', '李东阳', '明代', '渚兰汀芷思芳年，多在秋风白露前。欲把青溪溪上笛，夜凉吹遍泬寥天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题扇次倪良弼稽勋韵' AND p.poem_author = '李东阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('壮心', '彭汝砺', '宋代', '锐气销磨一水平，壮心非欲避功名。穷通有属都天意，忧乐无端自物情。\n\n拂地延留山月影，褰帘收拾水风声。清吟又得松陵侣，谁惜花前酒重倾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '壮心' AND p.poem_author = '彭汝砺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('道中书事', '陈与义', '宋代', '临老伤行役，篮舆岁月奔。\n客愁无处避，世事不堪论。\n白道含秋色，青山带雨痕。\n坏梁斜斗水，乔木密藏村。\n易破还家梦，难招去国魂。\n一身从白首，随意答乾坤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '道中书事' AND p.poem_author = '陈与义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泊楚州锁外六首', '张耒', '宋代', '莫愁家住大堤边，朱阁青楼映暮川。\n斜映清淮一梳月，晚妆相对斗婵娟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泊楚州锁外六首' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨中入桃源', '吴妍因', '清代', '不见桃花芳满林，载途风雨怅秋深。犹闻鸡犬疑真假，便访溪山认古今。\n\n耕织本来难自给，干戈焉往不相寻。贻谋欲怪秦先世，避乱曾无戡乱心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨中入桃源' AND p.poem_author = '吴妍因';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('琴曲歌辞十二操 其一 将归操', '添雪斋', '当代', '洪桐槐兮青白蕊。坡坎窑兮瘠骨颜黴。天赫赫兮上听不得，地遥遥兮下蔽其私。\n\n殆民兢兢兮安归儿？思归思归，咎戾靡盬兮瘅恶以悲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '琴曲歌辞十二操 其一 将归操' AND p.poem_author = '添雪斋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('公肃在东南三有书来未报闻其除司直以诗寄贺', '史尧弼', '宋代', '小试犹为天下平，惠文柱后要无刑。\n从今准拟子张传，吾世常司汗简青。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '公肃在东南三有书来未报闻其除司直以诗寄贺' AND p.poem_author = '史尧弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春感十首次丘仓海韵 其七', '胡云飞', '当代', '窥江胡马惯冯流，鸣镝接兵国始忧。时局无人非一日，江山有辱待从头。\n\n乌云不雨倍沉闷，赤子借光多远游。相忍制衡谁可忍，德宗肝胆最温柔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春感十首次丘仓海韵 其七' AND p.poem_author = '胡云飞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('走笔送韩昕伯谒任广文', '刘宰', '宋代', '芹宫竞说广文贤，姓字高县衮绿边。\n八十老翁无失德，三千弟子尽推先。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '走笔送韩昕伯谒任广文' AND p.poem_author = '刘宰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('【中吕】上小楼　客情', '景元启', '元代', '欲黄昏梅梢月明，动离愁酒阑人静。则被他檐铁声寒，翠被难温，致令得倦\n客伤情。听山城，又起更，角声幽韵，想他绣帏中和我一般孤另。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '【中吕】上小楼　客情' AND p.poem_author = '景元启';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠前宪副汤惕庵', '释今沼', '明代', '箨冠麻服混埃尘，座上犹钦峤岳身。千里海津逢故吏，一肩行橐倩邻人。\n\n殊方案牍谁相问，旧国瓜园且自贫。庐顶蒿茆吾欲剪，浔阳踪迹可能频。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠前宪副汤惕庵' AND p.poem_author = '释今沼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏日饮煦上人房 其一', '王世贞', '明代', '野人无一事，爱尔云床眠。缓带松风集，开樽江月悬。\n\n僧仍解中圣，客亦喜逃禅。欲问西来意，难从醒者传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏日饮煦上人房 其一' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贻妄怒', '梅尧臣', '宋代', '饮食无远近，所美贵甘{左车右耍}。\n南方食虾蟆，密捕向清畎。\n齿咀口且讳，闻语辄忿喘。\n此物何丑恶，犹胜螺蛳蚬。\n西蜀亦取之，水田名谷犬。\n彼士不为惭，吴人休独愐。\n岂须若中州，牛羊烹大脔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贻妄怒' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆秦娥', '王庭', '宋代', '梅花发。夜寒吹笛千山月。千山月。此时愁听，龙吟幽噎。 \n 数枝飞尽南枝雪。风光又作年时别。年时别。江头心绪，乱丝千结。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆秦娥' AND p.poem_author = '王庭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('季冬立春五绝 其二 岭外', '郭之奇', '明代', '岭外春光早，阶前气色多。庭花知我意，呼类引阳和。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '季冬立春五绝 其二 岭外' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东园遣兴再赋十绝句 其八', '李梦阳', '明代', '呼童刈草栽吾菊，夹径分行补种葵。怕认野人为鲁相，旋刚修竹起东篱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东园遣兴再赋十绝句 其八' AND p.poem_author = '李梦阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塞上', '赵延寿', '唐代', '黄沙风卷半空抛，云动阴山雪满郊。探水人回移帐就， \n 射雕箭落著弓抄。鸟逢霜果饥还啄，马渡冰河渴自跑。 \n 占得高原肥草地，夜深生火折林梢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塞上' AND p.poem_author = '赵延寿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆小儿', '蔡戡', '宋代', '中年再举子，可喜亦可怜。半晬已知父，举手拊我肩。\n\n欲别不忍去，离怀重悽然。儿生苦多病，此念有拳拳。\n\n江声鏖旅枕，展转不得眠。恍若闻儿声，常如在目前。\n\n我思不能已，汝病何当痊。王事相促迫，平明又加鞭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆小儿' AND p.poem_author = '蔡戡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴阊', '玄烨', '清代', '鸣銮独上高城望，巷陌遥通水寺斜。土俗惟知斗歌舞，闾阎不解种桑麻。\n\n鸟啼茂苑千年树，霜冷吴宫十月花。声教四方犹未讫，愿将淳朴变繁华。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴阊' AND p.poem_author = '玄烨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丁卯寒食前一日汪辇云滕王阁分赋', '赵由仪', '清代', '萧然怀抱欲悲秋，古树荒烟出荻洲。如此山川常作客，平生心事在登楼。\n\n文章有气精魂在，牛斗无光剑影愁。不尽天涯今日意，江风吹尔秣陵舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丁卯寒食前一日汪辇云滕王阁分赋' AND p.poem_author = '赵由仪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('待读王文公挽歌二首', '司马光', '宋代', '石室书编富，金华讲席重。\n芦绅归博洽，鸣玉称雍容。\n贰复累囚象，尸臣古瑑纵。\n老成今已矣，咨访欲谁从。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '待读王文公挽歌二首' AND p.poem_author = '司马光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题墨萱', '边贡', '明代', '华发当年倚笑看，北堂春色映朱阑。披图彷佛慈颜在，零落霜风夜雨寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题墨萱' AND p.poem_author = '边贡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋无月肯堂邀小酌赋三五七言', '邓深', '宋代', '雨飘零，风凄清。\n坐念今夕月，知从何处明。\n未须无月更作恶，但愿有酒常同倾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋无月肯堂邀小酌赋三五七言' AND p.poem_author = '邓深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢新恩 归五云峰故居', '袁思古', '当代', '闲阶寂寞苔痕透，蓬门虽设常关。吟筇倚听水潺潺。\n\n此身无恙，仍寄五云山。\n\n风情老大今何有，归来白发皆新。幽吟献啸自成春。\n\n了无尤怨，莫道是骚人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢新恩 归五云峰故居' AND p.poem_author = '袁思古';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵张䇓见寄', '高斯得', '宋代', '掀髯一笑天地间，八代文衰谁为起。夷陵丹砂空自光，中山老■不可使。\n\n一从麦秀获麟台，二千馀载无文字。谪仙岂无希圣心，谁其起予二三子。\n\n张君忽赠白云句，墨妙笔精真可喜。宗师奇涩费吟噍，三读方能得其意。\n\n奋髯苍鼠色无冤，吐气黑蛟云可致。恨子初筵我旅酬，妙处安能为摽指。\n\n惧遭掎摭不哦诗，畏触祸刑宁作史。翰林主人子墨卿，昔也同盟今趣异。\n\n不见当年圣德诗，犹被他人呼怪鬼。惭君问我乞馀丸，安得锦囊出怀里。\n\n丈夫盖棺事始定，斯文固应付后死。试问涪翁馀七言，松苓臭味固相似。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵张䇓见寄' AND p.poem_author = '高斯得';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('遣兴示彦博', '李流谦', '宋代', '尊酒谁相劝，诗篇子可酬。\n临汉惊老大，倚杖笑穷愁。\n雨足鸠初歇，风狂蝶未休。\n化工专一气，挽首听沉浮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '遣兴示彦博' AND p.poem_author = '李流谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉楼春', '晏几道', '宋代', '当年信道情无价。桃叶尊前论别夜。脸红心绪学梅妆，眉翠工夫如月画。 \n 来时醉倒旗亭下。知是阿谁扶上马。忆曾挑尽五更灯，不记临分多少话。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉楼春' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('从军行 其二', '罗颀', '明代', '山行穷深林，林深人迹稀。五里一荒村，十里无涧溪。\n\n路逢饥老翁，投杖向我啼。宣言盗贼暴，民庶久流离。\n\n我惜为徒卒，对之空伤悲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '从军行 其二' AND p.poem_author = '罗颀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠曾如鉴山人', '刘崧', '明代', '君平岭上两松树，秀色参天五百春。喜有孙枝承世泽，独窥玄秘启神珍。\n\n漆灯何代明金雁，华表谁家拥石麟。我有先茔翳烟草，残年风雨倍伤神。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠曾如鉴山人' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '晏殊', '宋代', '巧缀雕琼绽色丝，三千宫面宿胭脂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '晏殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读从兄南安令崇祯太平曲有感', '王跂', '明代', '洗眼乾坤正，回头日月新。\n百年垂半日，千载中兴辰。\n凤下辉堪揽，河清颂好陈。\n真逢击壤乐，犹欲叩阍申。\n忆昨衣冠祸，将舒刀锯嗔。\n风云资腐质，霜露落饕唇。\n兰狖三宫拟，桐封五等频。\n倾储窃弓玉，空厩赐麒麟。\n金虎通严寝，城狐列要津。\n貔貅符悉绾，鹰隼翅虚振。\n对簿陈公老，收赀萧傅贫。\n忠肝涂赤石，义骨莽黄尘。\n独座生令喜，诸生死效颦。\n山河青海并，俎豆素王邻。\n不愧曹嵩假，宁忧王莽真。\n遣弓安霡业，凭几密丝纶。\n光夏传家吉，从商及弟亲。\n三灵呵玺绂，九庙集吟呻。\n呼吸皇图巩，张弛祖德遵。\n威弧入手劲，衢酌匠心匀。\n艾捷三年效，丛收七日神。\n天恩正稠叠，霆断不逡巡。\n豕肆然灯腹，翚经衣宝身。\n剥肤消积甲，按月辇亡珍。\n一洗宫庭孽，惟余旃厦寅。\n山龙蠲泽国，简蠹课严宸。\n花静崆峒昼，云遥雒水春。\n乙书延伟论，甲第伫勋臣。\n幽魄含彪炳，明姿出暧堙。\n望云同梦寐，吟泽破酸辛。\n饭瓮家家备，酺觞个个醇。\n黄龙神雀降，丹甑白环臻。\n斯世皆醰粹，吾兄尚隐沦。\n西川豪杰士，南国放流人。\n拔薤威谁匹，吟花语绝伦。\n偷金逢怨口，酌水别遗民。\n强项违廷简，冥心惬野莼。\n声非《五噫》激，文似《九歌》驯。\n黼黻皇猷烂，丹青帝德纯。\n如无青史采，定下紫泥询。\n朴簌终相倚，浮华蚤见甄。\n飘零伤物役，衰谢困躬畇。\n鉏止公畦棱，行穷墅渎滨。\n扣舷随泛泛，持翳入蓁蓁。\n筒洒时牵鲫，竿投夜揭。\n龟巢知足雨，鸟食卜盈囷。\n小赋夸乌柿，遐瞻陟白絺。\n时清襜里隐，主圣务光踆。\n壤室琴声满，绳枢辙迹湮。\n因歌太平曲，停酒拭乌巾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读从兄南安令崇祯太平曲有感' AND p.poem_author = '王跂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出城', '董嗣杲', '宋代', '骤暄试单衣，出城看荒圃。满径郁纤茸，药苗青可数。\n\n篱花渐吐艳，艳盛如织组。人烟聚营屋，随事历勤苦。\n\n春沙落飞鸟，春水上层浦。行子晚未憩，贫樵出深坞。\n\n孤生真蜉蝣，顷刻即终古。归途多上灯，沽店半扃户。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出城' AND p.poem_author = '董嗣杲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('正月八日至十二日雪不止和施仲任韵', '郭印', '宋代', '天雨宝花呈上瑞，不同常岁旋能乾。\n痴儿诧见盐成糁，戏仆圆搓玉作团。\n漏屋茅檐垂欲压，华筵酒椀正禁寒。\n悬知片片非他物，落处应须子细看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '正月八日至十二日雪不止和施仲任韵' AND p.poem_author = '郭印';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙（甲子中秋微雨，闻施君家宴，戏赠）', '李光', '宋代', '画栋朱楼凌缥缈，全家住在层城。中秋风露助凄清。香凝燕寝，遮莫下帘旌。 \n 佳节喜逢今夕月，后房重按新声。姮娥端解妒娉婷。微云点缀，不放十分明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙（甲子中秋微雨，闻施君家宴，戏赠）' AND p.poem_author = '李光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('仪真 其一', '毛珝', '宋代', '频年岁稔少干戈，到处人能贩五河。只道鹾舟偏辐辏，玉杯泾段近年多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '仪真 其一' AND p.poem_author = '毛珝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乞茶', '黄裳', '宋代', '未终七椀似卢仝，解跨骎骎两腋风。北苑鎗旗应满箧，可能为惠向诗翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乞茶' AND p.poem_author = '黄裳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凤阳晓征', '邓云霄', '明代', '侵星晓发渡淮河，落叶迎霜拂马过。远山残烧明如月，旷野浮烟涌似波。\n\n潘岳正伤年鬓改，杨朱堪叹路岐多。劳劳半世成何事，欲向岩栖制薜萝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凤阳晓征' AND p.poem_author = '邓云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('义上人归自武林戏作四偈 其一', '刘应时', '宋代', '十载江湖寄此身，足香惯踏软红尘。梦回一笑知何有，稳卧家山寂寞滨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '义上人归自武林戏作四偈 其一' AND p.poem_author = '刘应时';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('董贞妇', '丁复', '元代', '灵凤怀远音，梧枝伤早枯。孤凤栖故林，哀鸣哺其雏。\n\n妾身固有死，岂不有舅姑。朝采陌上桑，暮辟闺中纑。\n\n蚕缫杂丝纩，纺织充裙襦。家尊足纤温，妾衣自粗疏。\n\n怡问审寒燠，敬进备鲜腴。生事一以尽，葬祭无违踰。\n\n桓桓树董宗，黾黾鞠子劬。谆谆贤者从，臻臻圣人徒。\n\n不幸妾有身，不幸妾有夫。有夫不终老，有身徒区区。\n\n所幸妾有子，不愿表门闾。膏沐不为施，素发今被□。\n\n妾身亦有死，妾今知免夫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '董贞妇' AND p.poem_author = '丁复';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('盩厔县北楼望山', '白居易', '唐代', '一为趋走吏，尘土不开颜。孤负平生眼，今朝始见山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '盩厔县北楼望山' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白帝城晚眺', '史谨', '明代', '城郭荒凉秋气深，江山如画一登临。中原自有刘文叔，应笑公孙错用心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白帝城晚眺' AND p.poem_author = '史谨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绍兴享先农十一首', '佚名', '隋代', '制为量币，厚意是将。\n求之以类，各因其方。\n于以奠之，精诚允彩。\n神其享止，惠我无疆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绍兴享先农十一首' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('端午日奉皇太后观竞渡', '弘历', '清代', '宿雨初晴霁景鲜，承欢行庆荅芳年。惟欣爱日临任辇，讵拟薰风入舜弦。\n\n画鹢飞波迅於鸟，綵縆界道直如弦。远人许预天中赏，欲使重瀛盛事宣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '端午日奉皇太后观竞渡' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('逢中别李景和', '陈钧', '明代', '客邸相逢不尽欢，倥偬别我壮心寒。可无鱼水应难比，纵有莺花也倦看。\n\n廿载刘蕡犹下第，三湘贾谊未还官。丈夫本是刚肠者，对此呻吟泪已弹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '逢中别李景和' AND p.poem_author = '陈钧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('肚山漫兴 其一', '陈肇兴', '清代', '岁岁干戈里，争雄气未残。普天皆赤子，何地得贤官。\n\n海熟鱼虾贱，山空鼠雀寒。茫茫百川水，只手障狂澜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '肚山漫兴 其一' AND p.poem_author = '陈肇兴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送刘茂实赴连江丞二首 其一', '许及之', '宋代', '三山七闽右，千竹二松间。官地今为乐，官名丞更閒。\n\n离支明夏谷，格磔响秋山。收拾吟哦课，湘中寄一斑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送刘茂实赴连江丞二首 其一' AND p.poem_author = '许及之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉同曾郎中题石瓮寺得嵌韵', '王建', '唐代', '寺门连内绕丹岩，下界云开数过帆。 \n 遥指上皇翻曲处，百官题字满西嵌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉同曾郎中题石瓮寺得嵌韵' AND p.poem_author = '王建';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陈伯孺兄弟水明楼春宵听雨歌', '徐熥', '明代', '我家有斋名绿玉，斋前种得千竿竹。君家亦有水明楼，半亩方塘山影流。\n\n君频访我鳌山麓，我每寻君溪水曲。与君来往十年馀，到此楼中几回宿。\n\n今春买棹来相寻，峡江风起波涛深。楼中宾主黯相对，四山阴翳生淫霖。\n\n檐前坐听声声雨，聊把琴书供笑语。烛尽犹然兴未阑，诗成自觉心相许。\n\n潇潇风雨莫深愁，百尺楼中且暂留。凭君貌出巴山夜，一幅丹青当卧游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陈伯孺兄弟水明楼春宵听雨歌' AND p.poem_author = '徐熥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赴大宁司理贽俞帅 其一', '阳枋', '宋代', '见说三关息虎貔，风高白帝卷旌旗。擎天砥柱瞿唐险，保蜀规模阵石奇。\n\n誓出祁山禽仲达，肯屯汉口学姜维。枕戈心事闻鸡起，未必閒眠听竹枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赴大宁司理贽俞帅 其一' AND p.poem_author = '阳枋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天雄道中 其二', '王世贞', '明代', '场中刈新谷，屋后晒软枣。儿女贪看客，群栖下相恼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天雄道中 其二' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('后秋兴八首辛丑二月初四日，夜宴述古堂，酒罢而作 其七', '钱谦益', '明代', '旄头摧灭岂人功，太白新占应月中。扫荡沈灰元夕火，吹残朔所早春风。\n\n揭空铙鼓催花白，搅海鱼龙避酒红。从此撑犁辞别号，也应飞盏贺天翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '后秋兴八首辛丑二月初四日，夜宴述古堂，酒罢而作 其七' AND p.poem_author = '钱谦益';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送杰老住仙游', '唐士耻', '宋代', '中庭可明月，况此方扬辉。\n霏谭隔千里，使我几忘归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送杰老住仙游' AND p.poem_author = '唐士耻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晦日', '刘敞', '宋代', '是月佳游胜，兹辰旧俗同。会须陶一醉，相与送诸穷。\n\n江柳参差绿，林花点染红。春期犹大半，作意竞东风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晦日' AND p.poem_author = '刘敞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨沙', '张泰', '明代', '老鲲呼乾北溟水，烛龙衔火烧余滓。\n一片狂沙乘断飙，飞度江南数千里。\n谁言天上无行人，空中乱落车马尘。\n青皇严令禁不得，掩却人间明媚春。\n羲和想迷西崦路，午景徘徊愁作暮。\n鼎湖神后拟重来，鬼蚩妒口吹黄雾。\n阴气野霾韬百灵，烟埃眯眼花冥冥。\n海天月浪洗一夜，明朝水绿山还青。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨沙' AND p.poem_author = '张泰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚集江园会者五人黄叔鱼林平父黄文若刁黄叔与仆也以暝色带飞鸟为韵余得色字', '周紫芝', '宋代', '少小谋一邱，老大犹未得。幽园固佳处，入眼自叹息。\n\n赖此千载人，相逢共京国。追凉坐花阴，持杯饮湖色。\n\n斜阳入疏林，晚色忽复逼。忽忽行语离，两别遂南北。\n\n日落未可归，山高更须陟。佳会岂易逢，莼鲙不须忆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚集江园会者五人黄叔鱼林平父黄文若刁黄叔与仆也以暝色带飞鸟为韵余得色字' AND p.poem_author = '周紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送张叔亨侍御巡按云南二首 其一', '程敏政', '明代', '才整朝簪拂岭岚，又骑骢马出滇南。足轻万里心何壮，法本三章老正谙。\n\n金齿儿童迎宪节，碧溪山水落诗函。归来便作经年约，远大功名是美谈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送张叔亨侍御巡按云南二首 其一' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹊巢', '王洋', '宋代', '今年结巢不近地，门户人言解知岁。\n了知积累功力劳，投伴鸤鸠无此智。\n闾里争如恶少年，不持弹射操空拳。\n挥巢取子尽居室，旁观禁止无由缘。\n父翔母噪力不加，小雏在手鸣楂楂。\n群儿不逞至若此，增巢不得安生涯。\n汉家春夏禁采捕，诏书非止行三辅。\n可怜科罪挂墙壁，国家禁绝非不预。\n郭居熙熙太古民，就令规巢不用嗔。\n同游馀啄不相害，海上鸥飞不避人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹊巢' AND p.poem_author = '王洋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪二首 其二', '李石', '宋代', '岁事频年恶，心知一饱难。只愁无此雪，得句不言寒。\n\n酒薄何妨圣，梅清合进官。老兵怜我意，赤脚唱平安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪二首 其二' AND p.poem_author = '李石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵汪宰见寄', '方岳', '宋代', '半世青灯眼欲昏，谁知曾亦望中原。\n雨荒塞草秋如洗，雪拥春蓑夜自温。\n宠辱易生分别想，是非政可鹘仑吞。\n不论茅屋锄犁外，但守平生六二坤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵汪宰见寄' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红 再汎南荡，晚花向残，以南吕宫旧谱歌之。', '郑文焯', '清代', '绀海文漪，荡不尽、花意万千。销魂又、断桥西堍，零落歌钿。\n\n白捲酒波双袖雪，绿浮诗梦一船山。听闹红深处玉箫沉，风露寒。\n\n秋灯外，柔橹边。载香去，放愁还。散袜罗馀绮，乱点蘋烟。\n\n吴网难收残霸局，越云犹作丽娃鬟。剩两三鸥迹，话芳尘，明镜閒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红 再汎南荡，晚花向残，以南吕宫旧谱歌之。' AND p.poem_author = '郑文焯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('老野狐', '李光', '宋代', '变化形容似老儒，南来权作白髭须。祗应坐上无鹰犬，走作人间老野狐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '老野狐' AND p.poem_author = '李光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早行寄田七', '刘摰', '宋代', '鞍马三更梦，江湖万里心。辨途听犬吠，占晓望横参。\n\n浩露濡衰鬓，微风动醉襟。输君正酣寝，鼾鼻沸雷音。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早行寄田七' AND p.poem_author = '刘摰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乍归九首', '刘克庄', '宋代', '孚若如天马，轩昂不可羁。\n为贫疏饮客，因病出名姬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乍归九首' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送陆山人华甫还吴中', '李英', '明代', '抱病怜君去，销魂不可言。飘然归茂苑，念我卧祇园。\n\n水国莼羹美，秋阴桂树繁。扁舟还有约，江上访柴门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送陆山人华甫还吴中' AND p.poem_author = '李英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('记杂画 □□□', '刘克庄', '宋代', '君耳污□□，□□□□湾。首阳落第二，前已有箕山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '记杂画 □□□' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郊居岁暮因书所怀', '权德舆', '唐代', '养拙方去諠，深居绝人事。返耕忘帝力，乐道疏代累。\n\n翛然衡茅下，便有江海意。宁知肉食尊，自觉儒衣贵。\n\n烟霜当暮节，水石多幽致。三径日闲安，千峰对深邃。\n\n策藜出村渡，岸帻寻古寺。月魄清夜琴，猿声警朝寐。\n\n地偏芝桂长，境胜烟霞异。独鸟带晴光，疏篁净寒翠。\n\n窗前风叶下，枕上溪云至。散发对农书，斋心看道记。\n\n清言覈名理，开卷穷精义。求誉观朵颐，危身陷芳饵。\n\n纷吾守孤直，世业常恐坠。就学缉韦编，铭心对欹器。\n\n元和畅万物，动植咸使遂。素履期不渝，永怀丘中志。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郊居岁暮因书所怀' AND p.poem_author = '权德舆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乙酉元日立春试笔时五十一', '倪谦', '明代', '年华荏苒鬓如银，甲子今朝过五旬。成化新正初改岁，大钧元日正回春。\n\n九原先垄关心切，千里乡山入梦频。只待河开便归去，江村耕钓老吾身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乙酉元日立春试笔时五十一' AND p.poem_author = '倪谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠邻居陈焕处士', '张舜民', '宋代', '福唐陈处士，与我对门居。\n生死一炉药，尘埃数箧书。\n但知尊有酒，莫叹食无鱼。\n若论浮生事，浮生事总虚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠邻居陈焕处士' AND p.poem_author = '张舜民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诗（金陵黄进士梦遇台城故妓，自云今为吴神乐部）', '故台城妓', '唐代', '歌罢玉楼月，舞残金缕衣。匀钿收迸节，敛黛别重闱。 \n 网断蛛犹织，梁春燕不归。那堪回首处，江步野棠飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诗（金陵黄进士梦遇台城故妓，自云今为吴神乐部）' AND p.poem_author = '故台城妓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('曾裘父寄二绝并呈审知一再次韵前以寄曾后寄', '赵蕃', '宋代', '向来共和有羊何，今见公才十倍过。\n可念此身如垢镜，要须著手为揩磨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '曾裘父寄二绝并呈审知一再次韵前以寄曾后寄' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归自须江泊舟于湖舟中书事', '周紫芝', '宋代', '一自胡尘起，飘零十载过。危情窘荆棘，老眼暗干戈。\n\n草草真聊尔，栖栖可奈何。功名麟阁晚，兴在鹿门多。\n\n避地依淮浦，伤心听楚歌。边烽明夕峤，戍鼓击寒波。\n\n江控曹公坞，山连冶父坡。凭高怀更远，吊古事应讹。\n\n久客横归棹，长年着短蓑。风高饱帆腹，潮稳转山阿。\n\n渐喜乡音似，还成醉脸酡。凄凉想茅屋，留滞厌江沱。\n\n井邑疏星火，津亭长薜萝。连樯自来往，坏壁本嵯峨。\n\n蜂目今何在，黄须迹巳磨。馀生能几屐，急景付飞梭。\n\n岁熟如堪隐，诗成可自哦。平生南亩愿，无地与婆娑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归自须江泊舟于湖舟中书事' AND p.poem_author = '周紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词 其十三', '江源', '明代', '寂静长门尽日封，傍人教妾强为容。不知宠辱都由命，只合深宫咏菲葑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词 其十三' AND p.poem_author = '江源';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵帅初浙西回及得新居三首 其一', '陈著', '宋代', '闻得胥江尚涨沙，往来虽便重嗟嗟。旧游怕说铜驼棘，遗曲难听玉树花。\n\n满目山川谁是客，无情天地若为家。栖栖又入西峰下，踏破山鞋几两麻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵帅初浙西回及得新居三首 其一' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观瀑图', '陈颢', '明代', '碧落无尘秋气高，白云捲空如海涛。山人避俗事幽讨，眼明八极穷秋毫。\n\n就中匡庐有佳色，飞流倒泻三千尺。初惊白虹饮涧泉，又疑玉龙挂岩壁。\n\n万里长风吹不收，坐令毛骨寒飕飕。漆园傲吏去已远，长庚仙人今在不。\n\n我生素志亦丘壑，苦因笔砚相缠缚。何当卜邻如此图，听水看山一生乐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观瀑图' AND p.poem_author = '陈颢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酒海吾饮器也', '郭祥正', '宋代', '红浪滔天玉海春，方壶有路可藏真。长鲸一吸桑田变，知是人间几岁人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酒海吾饮器也' AND p.poem_author = '郭祥正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('田园吟', '戴复古', '宋代', '自古田园活计长，醉敲牛角取宫商。催耕啼后新秧绿，锻磨鸣时大麦黄。\n\n桐树著花茶户富，梅林无实秫田荒。狂夫本是农家子，抛却一犁游四方。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '田园吟' AND p.poem_author = '戴复古';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和陶彭泽归田园居 其一', '童轩', '明代', '归来寡人事，被褐游青山。芳草满径生，又阅新岁年。\n\n云飞返层岩，鱼跃当深渊。长松夹幽户，新秫垂高田。\n\n俯仰自无愧，笑傲林壑间。数卷积案头，一觞倒花前。\n\n飞飞布谷鸟，蔼蔼桑树烟。红尘绝外想，白雪任盈颠。\n\n贫穷岂不念，栖迟有馀闲。清风北窗来，聊复乐自然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和陶彭泽归田园居 其一' AND p.poem_author = '童轩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六月廿日永昌病卧', '杨慎', '明代', '凉风却暑换秋清，滇国星回旧有名。巳把跳虫秉炎火，又驱白鸟静雷声。\n\n老夫病眼浑无睡，四壁鼾吟胜打更。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六月廿日永昌病卧' AND p.poem_author = '杨慎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阮师旦希圣彻垣开轩而东湖仙亭射的诸山如在掌上予为之名曰新轩盖取景物变态新新无穷之义赋十绝句 其六', '郭祥正', '宋代', '一湖绿水当窗净，百里青山卷箔开。只恐夕阳催客去，不嫌幽鸟趁人来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阮师旦希圣彻垣开轩而东湖仙亭射的诸山如在掌上予为之名曰新轩盖取景物变态新新无穷之义赋十绝句 其六' AND p.poem_author = '郭祥正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水龙吟', '汪莘', '宋代', '当年剪彩垂髫，超然便欲为仙去。世间俗状，人心狡计，不堪同住。\n\n每坐空山，独临古涧，神闲意寓。想瀛洲鸡犬，蓬莱猿鹤，应怅望，门前路。\n\n自昔侯王将相，几番成、落花飞絮。仰天醉眼，兴云妙手，年华迟暮。\n\n长揖烟尘，静朝日月，谁知幽素。正风清麟背，星垂海角，晓钟初寤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水龙吟' AND p.poem_author = '汪莘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('织女虫', '黄大受', '宋代', '灏气逼星河，佳期匝眼过。\n草间闻织急，天上想寒多。\n烛里颦挑锦，边头冷枕戈。\n终宵弄机杼，柰此月明何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '织女虫' AND p.poem_author = '黄大受';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寒梅赓韵寄友人姜贵宪 其一', '李贤（原德）', '明代', '松篁为友自相亲，弄月迎风楚水滨。数点嫩含窗外雪，一枝香散岭头春。\n\n寒分酒力传杯满，清挹吟怀得句新。盛世终需调鼎具，遭时岂必竟无因。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寒梅赓韵寄友人姜贵宪 其一' AND p.poem_author = '李贤（原德）';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('叹古人读书二首 其二', '胡居仁', '明代', '刺股悬梁枉自勤，岂知心在检其身。只因未遇程夫子，苦杀当年多少人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '叹古人读书二首 其二' AND p.poem_author = '胡居仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵题澹山岩', '释德洪', '宋代', '华屋张灯展画屏，当年纤手指岩扃。宦游那料重湖隔，醉里空惊叠嶂青。\n\n绣口词章人复见，笔华声价梦通灵。诗成独立西风晚，满眼归心插羽翎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵题澹山岩' AND p.poem_author = '释德洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('【双调】夜行船_酒病花愁何', '马致远', '元代', '酒病花愁何日彻，劣冤家省可里随斜。见气顺的心疼，脾和的眼热，休没前程外人行言说。\n\n【幺】但有半米儿亏伊天觑者，图个甚意断恩绝。你既不弃旧怜新，休想我等闲心趄，合受这场抛撇。\n\n【鸳鸯煞】据他有魂灵宜赛多情社，俺心合受这相思业。牵惹情杯，愁恨千叠，唱道但得半米儿有担擎底九千纸教天赦。怕有半米儿心别，教不出的房门化做血。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '【双调】夜行船_酒病花愁何' AND p.poem_author = '马致远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读义山诗', '黄浚', '近代', '中原屠解困强兵，走马长楸叹此生。隐诀上清怜小谪，沧波下苑托新盟。\n\n所哀轻幰长无道，常恐非烟画不成。愿乞西帘闲抱日，微吟君句伴天明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读义山诗' AND p.poem_author = '黄浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自述', '陆游', '宋代', '意望天公本自廉，甘餐美睡偶容兼。\n一生忧患如山重，此日安闲抵蜜甜。\n拙宦虽无齐虏舌，早归亦免楚人钳。\n但余一味疏慵在，储药千斤未易砭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自述' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚泊鸭栏矶', '俞明震', '清代', '一灯红起寒流外，身世无端接混茫。不信星辰随地转，独怜鸿雁入天荒。\n\n雄风作势吞云梦，清角流哀下岳阳。远望低吟总无奈，中原落日即沧桑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚泊鸭栏矶' AND p.poem_author = '俞明震';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苏幕遮', '吴藻', '清代', '曲栏干，深院宇。依旧春来，依旧春来去。一片残红无著处。\n\n绿遍天涯，绿遍天涯树。\n\n柳花飞，萍叶聚。梅子黄时，梅子黄时雨。小令翻香词太絮。\n\n句句愁人，句句愁人语。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苏幕遮' AND p.poem_author = '吴藻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题刘知宫愚圃三首 其二', '王炎', '宋代', '不羡苏秦六印，不贪范蠡千金。身住神仙窟宅，当无一点机心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题刘知宫愚圃三首 其二' AND p.poem_author = '王炎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丛祠梅', '夏鍭', '明代', '乱石托孤根，群槎避清芬。空山人不到，花照玉晨君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丛祠梅' AND p.poem_author = '夏鍭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风入松·清明日雨，用介民韵', '王用宾', '近代', '疾风寒雨过清明。迁客若为情。哀时再写江南赋，怕文章、老更无成。\n\n柳线牵愁曼舞，桐花破冻狂生。\n\n欲携柑酒听黄莺。烟雾锁空庭。何当尽卷顽云去，咄嗟间、野净天晴。\n\n遮莫燥红飞散，依然湿翠争荣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风入松·清明日雨，用介民韵' AND p.poem_author = '王用宾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和子瞻戏书伯时画好头赤', '黄庭坚', '宋代', '李侯画骨不画肉，笔下马生如破竹。\n秦驹虽入天仗图，犹恐真龙在空谷。\n精神权奇汗沟赤，有头赤乌能逐日。\n安得身为汉都护，三十六城看历历。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和子瞻戏书伯时画好头赤' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('客中闻攻石内兄死耗', '黄福基', '近代', '冷雨涩穷檐，叩门来不速。跫然喜乡音，启口眉忽蹙。\n\n初闻语吐吞，惊疑诘反覆。岂期平生欢，死别摧我腹。\n\n君丛骨肉悲，世乱又相促。后死命如丝，而君梦已觉。\n\n抽身江海归，语我天地窄。山居抗群嚣，流靡见崖脊。\n\n我曾避蛙黾，憩子藏山宅。撷茗及春晴，敲诗竟秋夕。\n\n夷险两置之，与子适其适。杪秋别子行，舍我竟长隔。\n\n岩阿不得归，即归岂如昔。痛逝行自念，魂摇短檠碧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '客中闻攻石内兄死耗' AND p.poem_author = '黄福基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天 纪所见', '戴延介', '清代', '一树黄梅亚阁东。梅边人影隐房栊。翠禽小语银蟾澹，午夜帘开不为风。\n\n香乍灺，漏初终。炉明鸂鶒被池红。相思吹入冬郎梦，融提春心似酒浓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天 纪所见' AND p.poem_author = '戴延介';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨后对月怀斯远', '赵蕃', '宋代', '旱后虽逢月，方忧未觉佳。\n雨余当委照，此趣熟能加。\n更觉湖边宅，遥知海上槎。\n绝嗟同味少，莫遣寸心遐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨后对月怀斯远' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送王洪德入蜀', '王廷陈', '明代', '落落幽并客，栖栖荆楚颜。遥知问卜去，或是泛槎还。\n\n云雨经三峡，风烟犯百蛮。看君壮游志，去矣杳难攀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送王洪德入蜀' AND p.poem_author = '王廷陈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三月十一日，遣家人还舍奉侍，值雨。十四日，值晴作', '范梈', '元代', '具船闻解缆，想象系朝昏。到日初收雨，沿流定达村。\n\n初生南涧藻，好近北堂萱。载感飘零意，清江是故园。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三月十一日，遣家人还舍奉侍，值雨。十四日，值晴作' AND p.poem_author = '范梈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('客舟两月王春又一矣而凉雱不已诗以懊之 其二', '郭之奇', '明代', '试借莺花慰客心，羁情犹自费搜寻。玄冥即便欺春软，平白时光尽夺侵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '客舟两月王春又一矣而凉雱不已诗以懊之 其二' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('齐天乐 蓟门寒食', '朱晞颜', '元代', '青烟一夜传宫烛，朝来管弦都试。宝扇传歌，银瓶索酒，柳下骄骢曾系。\n\n怜红妩翠。任栲栳量珠，伴春俱醉。不道无情，花残春老顿容易。\n\n人生几何适意，甚前时风度，今番情味。楚褐凝尘，涛笺封泪，愁在断鸿声里。\n\n情丝恨绮。尽付与风檐，燕儿论理。不似流红，解随东去水。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '齐天乐 蓟门寒食' AND p.poem_author = '朱晞颜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观迎春四首 其二', '卢龙云', '明代', '东郊淑气接长干，帝里春还万户欢。几向寒梅问消息，今朝得与众同看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观迎春四首 其二' AND p.poem_author = '卢龙云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('禅人并化主写真求赞 其一七○', '释正觉', '宋代', '妙处难传，明明像先。光凝雪月，秋连水天。百亿分身随应事，更嫌何处不周旋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '禅人并化主写真求赞 其一七○' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别霍子勉衷召补鄞尹四首 其三', '庞嵩', '明代', '玉河夙泂酌，天关叩堂室。鄞水文献邦，天真浚源窟。\n\n大道不尔孤，同心应超忽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别霍子勉衷召补鄞尹四首 其三' AND p.poem_author = '庞嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和余汝霖雪七绝 其二', '胡寅', '宋代', '虽无谐谑去相携，且乏舆梁济涉溪。之子惠然须痛饮，醉眠应梦镇帏犀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和余汝霖雪七绝 其二' AND p.poem_author = '胡寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('月夜听琴偶作', '童轩', '明代', '空山明月夜，有客坐弦琴。细把清商调，弹成太古音。\n\n花深胡燕语，木落楚猿吟。此意钟期解，寥寥千载心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '月夜听琴偶作' AND p.poem_author = '童轩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答太原从军杨员外送别', '马戴', '唐代', '君将海月珮，赠之光我行。见知言不浅，怀报意非轻。 \n 反照临岐思，中年未达情。河梁人送别，秋汉雁相鸣。 \n 衰柳摇边吹，寒云冒古城。西游还献赋，应许托平生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答太原从军杨员外送别' AND p.poem_author = '马戴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塞上四首 其四', '赵秉文', '金朝', '树霭连山郭，林烟接塞垣。断崖悬屋势，涨水没沙痕。\n\n烽火云间戍，牛羊岭外村。太平闲檄手，文字付清樽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塞上四首 其四' AND p.poem_author = '赵秉文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('云门俱字', '释重顯', '宋代', '百草头，何太极，\n重与禅徒下锥刺。云门俱字好参详，\n雪峰辊毬亦端的。黛非青兮蓝一色，\n辰锦砂兮敢言赤。紫罗帐里有真珠，\n曹溪路上生荆棘。还会麽，\n此时若不究根源，直向当来问弥勒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '云门俱字' AND p.poem_author = '释重顯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过李氏澹塘别墅', '沈辽', '宋代', '渊明昔已爱吾庐，我亦悁悁忆故居。君有东皋千束稻，山前更望澹塘湖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过李氏澹塘别墅' AND p.poem_author = '沈辽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泗上奉送相公', '赵嘏', '唐代', '语堪铭座默含春，西汉公卿绝比伦。 \n 今日抱辕留不得，欲挥双涕学舒人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泗上奉送相公' AND p.poem_author = '赵嘏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过刘村江', '杨万里', '宋代', '波走痕痕日，江呈岸岸秋。\n清流堪数石，浅涉不须舟。\n野菊知何喜，迎风舞未休。\n归涂愁欲暮，未暮我何愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过刘村江' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('恭奉皇太后幸避暑山庄晓秋启驾 其二', '弘历', '清代', '诸部行将奉属车，岩关古北是门闾。朝家武备超千古，顾语儿孙慎守诸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '恭奉皇太后幸避暑山庄晓秋启驾 其二' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵和寄', '刘敞', '宋代', '讲业儒林璧水开，望亲云下想徘徊。平原日暖歌鸰在，横陇风高听雁来。\n\n隐几郡斋閒主诺，荐羞家府乐循陔。何时乞得归宁告，对袭班衣捧庆杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵和寄' AND p.poem_author = '刘敞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('眉州燕游杂咏十首 其六 起文堂', '晁公溯', '宋代', '天地有万籁，中存韶濩音。斯文未尝废，但见古犹今。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '眉州燕游杂咏十首 其六 起文堂' AND p.poem_author = '晁公溯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('李皋试诗', '何仲举', '唐代', '似玉来投狱，抛家去就枷。可怜两片木，夹却一枝花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '李皋试诗' AND p.poem_author = '何仲举';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('论项', '贾似道', '宋代', '青项堆青钿，白毛根闪青。\n朱砂火盆底，桃皮等类形。\n白腐冬瓜大，宽臊垒起星。\n毛丁有，入手不当轻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '论项' AND p.poem_author = '贾似道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦横塘·替卢梦邯赞府蕉窗忆梦图', '杨葆光', '清代', '乱蛩如絮，旧燕来窥，个侬心事犹昔。嫩绿芭蕉，卷不尽、新愁盈尺。\n\n被恋余熏，袜留纤影，客怀空积。道云和再鼓，曲罢人遥，窗前雨，声声滴。\n\n君家有个卢生，在邯郸道上，一枕轻掷。省识家风，偏又阅、蓟燕陈迹。\n\n只须向、炉边醉到，使者氤氲更谁觅。此境迷离，耐人寻味，问何时醒得。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梦横塘·替卢梦邯赞府蕉窗忆梦图' AND p.poem_author = '杨葆光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('到农家', '赵汝燧', '宋代', '难得官人到，茅檐且驻车。自携锄掘笋，更取网求鱼。\n\n一媪来斟酒，诸童竞挽裾。须臾对吾泣，科役苦追胥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '到农家' AND p.poem_author = '赵汝燧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哀鸿嗷', '黄益增', '清代', '官家饭肉丘陇积，玉渍珠膏污瓴甓。长廊江海深百尺，后门永闭前门辟。\n\n日曝雨淋走阛阛，抛砖击石血流臂。无人识得歌哭意，鹅眼线环不忍弃。\n\n有时晴翻眦裂匮，头掷形色不及嗟来食。于戏！天昏地塞云蒙蒙，刀矛戈戟殷血红。\n\n鸷鸟饥鹰出樊笼，此辈嗷嗷尚哀鸿。君不见江南江北气郁郁，爨灶生蛙狐狸搰，朱门大厦无人乞。\n\n又不见桃武前年虏火焚，取金攫帛如家人，钱船万斛沈江津。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哀鸿嗷' AND p.poem_author = '黄益增';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('憩连岭店', '杨万里', '宋代', '此馆初明眼，前山正接眉。\n热嫌连日甚，凉惜两朝迟。\n雨竹何其重，风鸥不自持。\n庭闱犹百里，早已豁愁思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '憩连岭店' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王右军稚恭', '米芾', '宋代', '混沌破，龙蛇出。大荒子，鼓神物。纵变怪，造恍忽。起洪水，稽天骨。\n\n大道惊，戮狂勃。时蛰引，无惮率。神禹符，镇罅窟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王右军稚恭' AND p.poem_author = '米芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('隋宫', '陈子升', '明代', '浪结同心嗣太平，一朝閒梦决东征。红颜泣尽宫谁守，白骨流多殿自行。\n\n仙李根深摇柳色，后庭花谢到芜城。横波若久留人住，还望江南无限情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '隋宫' AND p.poem_author = '陈子升';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五弟新卜园居余笑曰柰物力不敷何社中遂以为韵作诗嘲之仍限四章各四韵 其一', '袁宏道', '明代', '斫红裁粉竽，作意缀春物。长短称身难，贫儿贷朱绂。\n\n百畹贮虚空，买破秋烟郁。莫似杂花林，卜庵典古佛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五弟新卜园居余笑曰柰物力不敷何社中遂以为韵作诗嘲之仍限四章各四韵 其一' AND p.poem_author = '袁宏道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '杜耒', '宋代', '不画涪翁画李翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '杜耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塞下曲二首 其二', '王恭', '明代', '登埤望烽火，落日烟尘紫。百战久不归，空闺泪如水。\n\n汉兵十万馀，尽没长城死。城下有精灵，啾啾月明里。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塞下曲二首 其二' AND p.poem_author = '王恭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题庐山瀑布图', '蒲庵禅师', '明代', '庐山瀑布天下闻，白河倒泻千丈云。\n长风吼石吹不断，一洗浩劫消尘氛。\n我昔浔阳看五老，探湫直上青龙夌。\n六月飞涛喷雨来，洒作冰花满晴昊。\n是时谪仙邀我锦叠屏，山瓢共酌夸中氵霝。\n冷光直疑山骨裂，清味不作蛟涎腥。\n尔来漫游身已倦，归老芝岩寄淮甸。\n枕流三峡杳莫期，高寒每向图中见。\n可怜问津之子徒纷纭，高深谁得穷真源。\n大千溟渤敛一滴，污潢绝港焉足论。\n我知山中有泉无若此，便欲临渊弄清泚。\n是非不到烟萝关，两耳尘空何必洗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题庐山瀑布图' AND p.poem_author = '蒲庵禅师';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('展江亭海棠四首 其四', '韩维', '宋代', '人避寒风与暖曦，年年长此探花期。如今太守尤珍爱，只许官娃带一枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '展江亭海棠四首 其四' AND p.poem_author = '韩维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵东坡上元扈从三绝', '秦观', '宋代', '赭黄繖底望龙章，不断惟闻蜡炬香。\n一片韶音归复道，重瞳左右列英皇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵东坡上元扈从三绝' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦中和句', '任玠', '唐代', '故国路遥归去来，春风天远望不尽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梦中和句' AND p.poem_author = '任玠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泉州南郭二首', '刘克庄', '宋代', '闽人务本亦知书，若不耕樵必业儒。\n惟有桐城南郭外，朝为原宪莫陶朱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泉州南郭二首' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬日怀竟陵管氏梅桥四首 其三', '张耒', '宋代', '他日华陵迹已陈，嘉辰怀旧一销魂。小园幽径谁相念，应有新梅觅故人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬日怀竟陵管氏梅桥四首 其三' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('池上', '释智圆', '宋代', '沤生复沤灭，水湿元无异。\n尽日倚栏看，无人知此意。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '池上' AND p.poem_author = '释智圆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟过当涂', '彭汝砺', '宋代', '悠悠章江柁，复自姑孰北。此身与此水，日夜俱无息。\n\n关关林中鸟，软语如相识。杨柳枝叶长，青青祇如昔。\n\n惟予鬓间发，种种添新白。开尊泛溪水，宛转随山色。\n\n四方本予志，夷险非我恻。挂帆出长江，万里追鹏翼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟过当涂' AND p.poem_author = '彭汝砺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉女迎春慢', '汪东', '清代', '高阁凌虚，烟霏宿、寂寂回廊深处。十丈幡竿自舞。\n\n几簇金铃丛语。连宵风苦。便自恐、一春迟误。花开花落，回忆去年，嘉会堪数。\n\n飞来粉蝶轻盈，如寻旧约，绿阴低护。未识芜园野景，尽作瑶台碧柱。\n\n倦游情绪。任逐渐、看花成雾。倚枕閒停，错落数声钟度。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉女迎春慢' AND p.poem_author = '汪东';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闺怨一百二十首 其五十三', '孙蕡', '明代', '新愁旧恨积如林，欲诉还羞复不禁。安得越禽秦吉了，替人终日道劳心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闺怨一百二十首 其五十三' AND p.poem_author = '孙蕡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诗', '曹丕', '魏晋', '蜘蛛网户牖。\n野草当阶生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诗' AND p.poem_author = '曹丕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十二文', '释函是', '明代', '荒原人影寂，孤雁不堪闻。惟有一枝秀，乘风寄白云。\n\n黄尘初夜静，素色晓霜芬。珍重冰棱意，前山日未昕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十二文' AND p.poem_author = '释函是';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦中感遇', '傅子馀', '近代', '资生无术尚差池，百感都从枕上支。一梦略知春色减，孤芳宁恨夕阳迟。\n\n人于久别相逢处，天在将阴未雨时。强欲与言今日意，寂寥天地更何之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梦中感遇' AND p.poem_author = '傅子馀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('下岩寺二首 其一', '喻汝砺', '宋代', '径向山腰转，门从水面开。片云岩下宿，一钵朔方来。\n\n落日鸟冲树，轻云花覆苔。惟应荔枝熟，时蹑白云回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '下岩寺二首 其一' AND p.poem_author = '喻汝砺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贤者之孝二百四十首·何蕃', '林同', '宋代', '五载莫归省，双亲孰问安。\n固云亲有命，不谓我何颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贤者之孝二百四十首·何蕃' AND p.poem_author = '林同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送陆伯顺年兄', '范景文', '明代', '王师张挞伐，四处大徵兵。枵腹焉能战，所忧在呼庚。\n\n中帑不可问，何贵举朝争。便宜取济事，古人亦有行。\n\n金花数十万，三军色肉生。矫诏非无罪，久矣权重轻。\n\n圣怒原不测，严谴翻为荣。岂其爱阿堵，想为尊朝廷。\n\n外人那得知，微意恐不明。未免损圣德，成我臣子名。\n\n此处应介介，君何以为情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送陆伯顺年兄' AND p.poem_author = '范景文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绝句四首 其二', '陈师道', '宋代', '芒鞋竹杖最关身，散发披衣不待人。三两作邻堪共活，五千插架未为贫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绝句四首 其二' AND p.poem_author = '陈师道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百零二首 其九十二', '释绍昙', '宋代', '庄上吃油糍，鬼精魂罢休拈弄。雁影沉寒水，穷伎俩何用施呈。\n\n虽云博饭栽田，何似归堂向火，静悄悄，暖烘烘。不劳共话无宾主，衲被蒙头万境空，死水何曾有活龙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百零二首 其九十二' AND p.poem_author = '释绍昙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('灵照女赞', '释法薰', '宋代', '恶种草，行冤家。\n笊篱定价，分文不差。\n末梢犹尀耐，机先不让爷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '灵照女赞' AND p.poem_author = '释法薰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('椒轩', '何景明', '明代', '春开轩地引红椒，锦树西江望不遥。当户疏帘看结实，背冈茅屋忆行条。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '椒轩' AND p.poem_author = '何景明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五更', '张耒', '宋代', '岁事先教蟋蟀催，暮云楼阙殷轻雷。\n五更庭叶惊残梦，知有清秋犯雨来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五更' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·夏初，喜得方君璧香港来书', '龙榆生', '近代', '留得馀生惟自愧，泪痕终古长新。几人相忆见情亲。\n\n西州门外路，悽断故时春。\n\n青鸟为传归信早，开缄喜及芳辰。蔷薇谢后草如茵。\n\n画图辉禹域，珍重有为身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·夏初，喜得方君璧香港来书' AND p.poem_author = '龙榆生';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过段平章墓', '冯诚', '明代', '田横五百剑孤身，转眼关山半委尘。白阙玉楼招客记，南滇彩璧说诗人。\n\n苍山夜黑云遮月，金马天寒鸟怨春。共说平章迷绣幕，至今应乐水声频。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过段平章墓' AND p.poem_author = '冯诚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠远', '屈大均', '明代', '美人如花飞，玉佩冰绡衣。长风吹欲堕，揽带前相持。\n\n问子游何处，笑含碧云姿。言我华阳来，将从勾曲栖。\n\n麻姑久相待，去去与我辞。语卿且莫辞，我有芙蓉池。\n\n鸳鸯戏碧叶，翡翠巢金枝。愿将天上月，长照双蛾眉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠远' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无题', '王彦泓', '明代', '不合将才赋宓妃，烹阿安敢怨燃箕。豢龙谁氏能烧燕，畜鸭何人肯饭狸。\n\n岂惮谗唇工贝锦，尚甘诗骨堕泥犁。明珠海底终探取，莫间骊龙有睡时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无题' AND p.poem_author = '王彦泓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢宣赐御草书急就章并朱邸旧集歌', '王禹偁', '宋代', '臣闻伏羲画卦朴且淳，苍颉迼字初有文。\n大篆小篆八分体，楷隶章草何纷纭。\n因兹八法各有要，遂使六艺区以分。\n其中最难惟草圣，玄妙功夫自天性。\n又闻关雎本王化，四始洋洋风化下。\n比兴赋颂六义分，乃有变风兼变雅。\n仲尼删後屈平作，郢客李陵斗名价。\n古来诗道难得人，其唱弥高和弥寡。\n如今草圣与雅言，尽在吾皇万机暇。\n元年十月近乾明，崇文院静寒霜晴。\n直庐日午雠书罢，闲曳朱衣遶砌行。\n中使传宣来上界，忙把鱼须下阶拜。\n宝函钿轴光陆离，御札文书御制诗。\n折腰汗流魄骇聊一窥。\n急就章，何纵横，\n蓝田种玉苗初成。雪花洒破烟岚壁，\n黑云漏出天汉星。乍似鲛人泣下珠无数，\n错落晶荧满盘贮。又似大鲸吞尽沧海波，\n查牙露出珊瑚树。朱邸集，\n何清奇，仙风撼动琼林枝。\n汉皇休道白云句，穆满虚吟黄竹诗。\n乍似三春直上伯阳台，熙熙物华当眼开。\n又似十洲夜伴王母宴，鸶歌凤吟次第来。\n小臣再拜受一轴，捣纸抄诗抄未足。\n焚香朝向天日看，执简夜对星辰读。\n臣见高宗飞帛亦有名，笛迹往往颁公卿。\n所得不过三五字，当时臣子犹为荣。\n又见玄宗诗什颇留意，吟咏时时成御制。\n属和止于一两篇，至今史册犹为贵。\n若徵往事比明时，万分之一徒尔为。\n未如我四十三纸圣人作，一百二章天子诗。\n永为家宝藏书箧，岂让西方贝多叶。\n且教世世传子孙，长与皇家作臣妾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢宣赐御草书急就章并朱邸旧集歌' AND p.poem_author = '王禹偁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('相见欢 其一 寄国武', '单人耘', '近代', '而今咫尺非遥，旧江皋。一夜秋来红叶又萧萧。\n\n山阳酒，经纶手，忆迢迢。起弄霜天明瑟月轮高。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '相见欢 其一 寄国武' AND p.poem_author = '单人耘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋水 读湖海楼词', '沈轶刘', '近代', '消尽半生湖海疹。酒悲起，红箫喷。奈茶花未髓，古烟谁爨，只剩与、苦捣珊瑚盈寸。\n\n爇锦菊、空余短烬。豪泻哀丝，凭铸就、竹山孤愤。心事旧家阑楯。\n\n老怀长绝，故园樱笋。恁庾郎萧瑟，鬓边词赋，尽孤负、席畔南朝金粉。\n\n但醉倒青楼休问。放却颠狂，还看取、梦里须眉齐奋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋水 读湖海楼词' AND p.poem_author = '沈轶刘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻夫子将回驻西安书寄', '张印', '清代', '戎马问关未了期，一春如梦耐人思。唐陵西去吹沙暗，秦岭东回出雾迟。\n\n诗句会成穷事业，年光几换旧须眉。归来看取青尊在，留意公馀话片时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻夫子将回驻西安书寄' AND p.poem_author = '张印';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('承天潜师画赞', '林之奇', '宋代', '金刚圈裹翻身过，栗棘蓬莱满口吞。\n领得杨岐端的句，却嫌蒸饼大餫饨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '承天潜师画赞' AND p.poem_author = '林之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('皇后阁端午贴子词五首 其四', '真德秀', '宋代', '水晶帘捲午风轻，万壑清寒凌室冰。閒奏薰弦思解愠，肯教人世独炎蒸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '皇后阁端午贴子词五首 其四' AND p.poem_author = '真德秀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙 春闺', '沈宜修', '明代', '淡薄轻阴拾翠天。细腰柔似柳飞绵。吹箫闲向画屏前。\n\n诗句半缘芳草断，鸟啼多为杏花残。夜寒红露湿鞦韆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙 春闺' AND p.poem_author = '沈宜修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('香奁八咏 其一 翠袖啼痕', '黄伯旸', '元代', '石竹绣罗双袂单，绮窗日暮笼轻寒。秋波滉漾落铅水，相思几点春斑斑。\n\n脂浓粉腻半尘土，玉臂娇柔懒轻举。东风十日吹不乾，六曲阑边海棠雨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '香奁八咏 其一 翠袖啼痕' AND p.poem_author = '黄伯旸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花', '来鹄', '唐代', '枝枝倚槛照池冰，粉薄香残恨不胜。 \n 占得早芳何所利，与他霜雪助威棱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花' AND p.poem_author = '来鹄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东门行', '张载', '宋代', '古风出东门，我行乐巾綦。\n今歌乐门行，牵衣强留甘餔糜。\n仗剑去，忽如遗，\n时清君去予心哀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东门行' AND p.poem_author = '张载';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('入秋无事案头偶有纸笔随意辄书如风扫华不伦不理故曰杂题 其十五', '王世贞', '明代', '大毁弥天来，今生夙生事。差胜买虚名，尸居长抱愧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '入秋无事案头偶有纸笔随意辄书如风扫华不伦不理故曰杂题 其十五' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题王制机新楼', '戴复古', '宋代', '绿云图上新轮奂，弹压江山气势豪。\n手拍危栏拂星斗，目穷沧海见波涛。\n人间何处望不到，天下有楼无此高。\n俯视河阳桃李巷，清风吹断市尘嚣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题王制机新楼' AND p.poem_author = '戴复古';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('相和歌辞。从军行六首', '刘长卿', '唐代', '回看虏骑合，城下汉兵稀。白刃两相向，黄云愁不飞。 \n 手中无尺铁，徒欲突重围。 \n 落日更萧条，北方动枯草。将军追虏骑，夜失阴山道。 \n 战败仍树勋，韩彭但空老。 \n 草枯秋塞上，望见渔阳郭。胡马嘶一声，汉兵泪双落。 \n 谁为吮痈者，此事令人薄。 \n 目极雁门道，青青边草春。一身事征战，匹马同辛勤。 \n 末路成白首，功归天下人。 \n 倚剑白日暮，望乡登戍楼。北风吹羌笛，此夜关山愁。 \n 回首不无意，滹河空自流。 \n 黄沙一万里，白首无人怜。报国剑已折，归乡身幸全。 \n 单于古台下，边色寒苍然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '相和歌辞。从军行六首' AND p.poem_author = '刘长卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹡鸰野棘', '王恭', '明代', '野棘荒原日又残，萧条孤影夜栖寒。如今已遂连枝好，又恐分飞在急难。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹡鸰野棘' AND p.poem_author = '王恭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古一百则 其五十五', '释正觉', '宋代', '末后句，会也无，德山父子太含胡。座中亦有江南客，莫向人前唱鹧鸪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古一百则 其五十五' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三月初晚晴寄高缙之三首', '陈造', '宋代', '东风扫积阴，残雨不敢漂。\n坏云裂裳帛，倒挂磴岭腰。\n鸟影不作暝，夕阳明山椒。\n安得上上头，风露永清宵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三月初晚晴寄高缙之三首' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过访吕巾石翁值其大耋寿用韵三首 其二', '庞嵩', '明代', '廿年违缩地，千里庆登台。蟾桂丛丛发，绥桃岁岁开。\n\n称觞霞共割，觅句雨初来。欲缵南山什，赓歌愧有莱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过访吕巾石翁值其大耋寿用韵三首 其二' AND p.poem_author = '庞嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('零陵寺井栏赞', '郭通', '唐代', '此是南山石，将来造井栏。流传千万代，各结佛家缘。\n\n尽意修功德，应无朽坏年。同沾胜福者，超于弥勒前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '零陵寺井栏赞' AND p.poem_author = '郭通';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泛月', '弘历', '清代', '秋月无不宜，最宜中秋月。乃多值塞上，林隙延蟾窟。\n\n今秋御园度，时节不可忽。生魄光欲流，澄池波更活。\n\n试泛木兰舟，真在水精阙。岸虫声正繁，盆桂香偏馞。\n\n广寒乍飞来，倚吟逸兴勃。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泛月' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵友人山居秋日就述鄙怀八首 其四', '王祎', '元代', '明珠有照乘，其焰百尺长。如何污涂泥，世人不得将。\n\n终然有时出，夺月争夜光。至宝非可私，献之天子傍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵友人山居秋日就述鄙怀八首 其四' AND p.poem_author = '王祎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('任承制挽辞刘校勘槩求作', '晁补之', '宋代', '生业清谈外，浮名痛饮馀。谁令力如虎，坐使食无鱼。\n\n壁冷犹鸣剑，床空未卷书。呻吟待河润，秋柏只遗墟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '任承制挽辞刘校勘槩求作' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日感怀 其二', '蔡国琳', '清代', '鸠居暂获一枝安，湖海飘零泪未乾。春草池塘康乐梦，秋郊茅屋杜陵寒。\n\n过江名士悲司马，赁庑馀生学伯鸾。留得故园松菊在，清风两袖不嫌单。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日感怀 其二' AND p.poem_author = '蔡国琳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('入销夏湾', '王宠', '明代', '千山玩回转，双阙开嶙峋。围作玉镜潭，流水桃花春。\n\n鸡犬自甲子，衣冠乃秦民。表里重湖阻，丹青四望匀。\n\n孤峰表日观，群嶂摩天垠。波光别骀荡，霞采相鲜新。\n\n疑觞西王池，误攀织女津。海鸥戏兰薄，游鯈莹心神。\n\n牙樯悲昔年，玉辇罢今巡。荣华无常玩，山水有天真。\n\n尘缨聊以濯，惭尔棹歌人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '入销夏湾' AND p.poem_author = '王宠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('潞河途中感怀', '饶相', '明代', '策骑出尘寰，飞花点醉颜。十年成幻梦，一夕落清班。\n\n□海风涛险，仙山日月间。何当拂衣去，高卧白云间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '潞河途中感怀' AND p.poem_author = '饶相';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花 其三', '程颂万', '清代', '待得侬来郎又去。底事帘钩，一桁愔愔暮。不是迷藏花底路。\n\n中庭枉种相思树。\n\n梁燕一双痴共语。省识春归，不道卿知否。昨夜江头轻似絮。\n\n绕船明月人何处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花 其三' AND p.poem_author = '程颂万';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阆中蒲氏园亭十咏 其八 鱼池', '冯山', '宋代', '活水停无滓，嘉鱼养不惊。休言濠上意，秋鲙与春羹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阆中蒲氏园亭十咏 其八 鱼池' AND p.poem_author = '冯山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('燕京十六夜曲四首 其一', '何景明', '明代', '御河桥畔千尺台，燕京女儿踏歌来。台上歌钟日夕起，桥头酒垆深夜开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '燕京十六夜曲四首 其一' AND p.poem_author = '何景明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史（四首）', '王偁', '未知', '达人志莫测，变化犹鹏鹍。\n倏忽翔九万，虞罗空见存。\n庄生挥楚璧，仲连却秦军。\n峻武薄层汉，高情寄浮云。\n昔过聊城侧，复经濮水濆。\n余风尚不泯，肃肃来清芬。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史（四首）' AND p.poem_author = '王偁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽黄岩赵郎中二首 其二', '刘克庄', '宋代', '青衫昔作督邮时，赏鉴除公更有谁。勘狱不嫌人守法，撰文常对众称奇。\n\n筑台虚辱生前意，穿冢难酬地下知。欲写哀思传挽者，身今戎服不能诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽黄岩赵郎中二首 其二' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('朝中措 其二', '张克家', '近代', '那堪拍膝叹蹉跎。粲粲鬓毛皤。大长蛮夷赵尉，饶他岁月如梭。\n\n锯人夹板，请君入瓮，老子婆娑。充户常流碧血，何知柱国阎罗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '朝中措 其二' AND p.poem_author = '张克家';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答赵温甫见谢茶瓯韵', '彭汝砺', '宋代', '我昔曾涉昌江滨，故人指我观陶钧。庞眉老匠矜捷手，为我百转雕舆轮。\n\n镌刓刻画走风雨，须臾万态增鲜新。盘龙飞凤满日月，细花密叶生瑶珉。\n\n轻浮儿女爱奇崛，舟浮辇运倾金银。我盂不野亦不文，浑然美璞含天真。\n\n光沉未入世人爱，德洁诚为天下珍。朅来东江欲学古，喜听英杰参吾伦。\n\n谨持清白与子共，敢因泥土邀仁恩。空言见复非所欲，再拜谢子之殷勤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答赵温甫见谢茶瓯韵' AND p.poem_author = '彭汝砺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('刘觐国宪副自楚入祝万寿圣节奉恩纶南归称太夫人觞即返武昌赋别', '邓云霄', '明代', '嵩呼环佩染天香。新捧鸾章上北堂。家庆正看誇昼锦，王程又报促轻装。\n\n青骢旧识垂棠路，黄鹤重迎醉月觞。我亦湖南曾吏隐，梦随行客到潇湘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '刘觐国宪副自楚入祝万寿圣节奉恩纶南归称太夫人觞即返武昌赋别' AND p.poem_author = '邓云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬日即事', '多敏', '清代', '寒色逼虚幌，深闺暮掩门。堕来凉月影，写出晚愁痕。\n\n永夜镫疑雪，微烟夕敛昏。不须嗟缟袂，金鸭手重温。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬日即事' AND p.poem_author = '多敏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('韩持国见访', '王安石', '宋代', '余生非匏瓜，於世不无求。\n弱力惮耕稼，衣食当周流。\n起家始二十，南北今白头。\n愁伤意已败，罢病恐难瘳。\n江湖把一节，屡乞东南州。\n治民岂吾能，闲僻庶可偷。\n谬恩当徂冬，黾勉始今秋。\n岂敢事高蹇，茫然乖本谋。\n抚心私自怜，仰屋窃叹愀。\n强骑黄饥马，欲语将谁投。\n赖此城下宅，数蒙故人留。\n揽衣坐中庭，仰视白云浮。\n白云御西风，一一向沧洲。\n安得两黄鹄，跨之与云游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '韩持国见访' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诸子作病僧诗予以为非有道之病僧光半因请予赋一律', '释今无', '明代', '蒲团添絮月添寒，窗外花枝不耐看。识断浮沤难觅剑，珠然风火不留盘。\n\n鸡鸣潮上蓬头湿，人寂更阑夜语乾。宝镜果曾偷听得，木蛇空挂碧云端。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诸子作病僧诗予以为非有道之病僧光半因请予赋一律' AND p.poem_author = '释今无';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵黄户曹问讯二首 其一', '刘克庄', '宋代', '理窟骚坛两罢休，倒持麈柄让名流。向来袒裼欲暴虎，老去短衣聊饮牛。\n\n敛退始知颜巷乐，迂疏空抱杞天忧。名山何处无灵药，长笑痴人入海求。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵黄户曹问讯二首 其一' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送永昌萧赞府', '宋之问', '唐代', '柳变曲江头，送君函谷游。弄琴宽别意，酌醴醉春愁。 \n 恋本亦何极，赠言微所求。莫令金谷水，不入故园流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送永昌萧赞府' AND p.poem_author = '宋之问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诗一首', '晃逈', '宋代', '宜城徵美醖，汉水得佳鲂。\n登岘思前哲，游池醉夕阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诗一首' AND p.poem_author = '晃逈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('悲秋 其四', '钱曾', '清代', '卷然双鬓感秋蓬，十四年来昔梦中。放鹤亭南寻处士，操蛇山北笑愚公。\n\n新愁汴水烟花绿，旧恨樊楼灯火红。苦爱青州从事好，醉乡端合老无功。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '悲秋 其四' AND p.poem_author = '钱曾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人（怀金华九日寄叶丞相）', '韩元吉', '宋代', '登临自古骚人事。惨忄栗天涯意。金华峰顶做重阳。月地千寻风里、万枝香。 \n 相君携客相应记。几处容狂醉。双溪明月乱山青。飞梦时时犹在、最高亭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人（怀金华九日寄叶丞相）' AND p.poem_author = '韩元吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岁暮归里', '郭风惠', '近代', '东海送寒汐，朔云翳午晖。草短风如剪，梅瘦雪为衣。\n\n物候惊客心，归思不可挥。望儿有双亲，爱孙有重闱。\n\n到家百事娇，出门一身微。寄语同学子，岁暮胡不归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岁暮归里' AND p.poem_author = '郭风惠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('台阳八景诗', '钱琦', '清代', '宿雨初收夜气妍，空灵色相妙难诠。澄来止水壶中月，洗净浮云水底天。\n\n鲛女静开霜匣照，骊龙冷抱宝珠眠。冰心彻底谁怜取，留得清光在海边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '台阳八景诗' AND p.poem_author = '钱琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀桂林', '屈大均', '明代', '太华儿孙在桂林，参天笋石总森森。东西柱向穿山出，左右江连峤水深。\n\n光禄堂前曾酌酒，伏波岩上复鸣琴。军书一卷留苔藓，他日思从洞口寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀桂林' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜郭骙臣秀才见访索赠 其一', '释今无', '明代', '朔风吹海寺门凉，喜有宗雷到上方。游里定编高士传，衣间全带薜萝香。\n\n行从花县分襟短，吟向冰崖出峡长。我久忘形君有道，便从今日契空王。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜郭骙臣秀才见访索赠 其一' AND p.poem_author = '释今无';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望夫山', '李白', '唐代', '□望临碧空。【禺页】\n怨情感离别。\n江草不知愁。\n岩花但争发。\n云山万重隔。\n音信千里绝。\n春去秋复来。\n相思几时歇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望夫山' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('瑞龙吟', '金问泗', '当代', '图南路。可有处士梅花，逸民桃树。连年孤岛辛勤，征轺暂驻，薰风起处。\n\n料延伫。长忆越王栖甲，楚人三户。君歌金石成声，我尤爱听，中兴吉语。\n\n遥想秦淮官柳，毵毵晴日，因风低舞。却怪上天无情，春色如故。\n\n归欤怕赋，最是伤心句。诗词好，屯田待制，八义七步。\n\n拙稿商量去。排铅误夺，殊无意绪。欲印思千缕。何况是、吾诗纤如秋雨。\n\n散如落叶，轻如飞絮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瑞龙吟' AND p.poem_author = '金问泗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('疏梅二首 其二', '张耒', '宋代', '我贫受寒欺，帖帖为不出。积雨远市声，幽居近芳物。\n\n时禽过我柳，清喙动鸣瑟。客去门复扃，低参映林没。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '疏梅二首 其二' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('顾司勋斋中二咏 其一 锄', '欧大任', '明代', '烟客以铁耕，霞起赤城日。泰山老父来，共种中林木。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '顾司勋斋中二咏 其一 锄' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题画廿四首', '唐寅', '明代', '山亭寥落接人稀，泥补柴门叶补衣。\n不起竹床头似雪，已无心去问襌机。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题画廿四首' AND p.poem_author = '唐寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次杨监簿新辟小西湖韵', '姚勉', '宋代', '搜奇抉异三十载，此湖如玉韫而待。发源远自锦江来，汇流近与柴门对。\n\n山川融结自古有，造物扃藏深意在。瘦筇曾作日寻讨，一见便觉天广大。\n\n两山宛似南北峰，况有层塔相映带。芰荷十里萼绿华，雪月三千银色界。\n\n深藏最有君子意，自衒殊非小人态。西湖每遇苏雪堂，妙句尚忆秦淮海。\n\n此湖端为旧游发，㘲重未信吾州隘。铁庵蜀珍坡仙派，下笔作诗风雨快。\n\n从今新瑞次古杭，敢贺此湖贡庆会。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次杨监簿新辟小西湖韵' AND p.poem_author = '姚勉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洞仙歌 其二 题肃忠亲王旅顺书册', '奭良', '清代', '荒寒野处，问如何遣日。手擘涛笺墨华碧。有山禽格𡏝，路草斑烂，凭眺处、都化作湘累叹吒。\n\n天乎胡此醉，阁笔沈思，往事匆匆不堪忆。旧恨怎消磨，泽畔行吟，犹延望、断鸿天北。\n\n当庄生、哀吟一般看，任苏海韩潮，莫摅胸臆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洞仙歌 其二 题肃忠亲王旅顺书册' AND p.poem_author = '奭良';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绍兴淳熙分命馆职定撰十七首', '佚名', '隋代', '[黄钟为角]合宫盛礼，金商令时。\n务成熙事，蒐扬上余。\n骏奔在庭，精意肃祗。\n来享嘉成，神灵燕娭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绍兴淳熙分命馆职定撰十七首' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贫居自述 其八十九', '李孔修', '明代', '贫居喜得有芳邻，早晚盘桓道味亲。数盏香醪同伴酌，半篮嫩笋共尝新。\n\n算来饱暖人赢我，论到清閒我胜人。词客有情相顾盼，扫开花径每迎宾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贫居自述 其八十九' AND p.poem_author = '李孔修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('入谷马上 其二', '文同', '宋代', '乱竹围清密，垂萝荫屈盘。晴林风色淡，晚水日光寒。\n\n树石因谁好，烟云只自漫。群峰若相待，满眼碧巑岏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '入谷马上 其二' AND p.poem_author = '文同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题少师建安杨先生行乐图 其一', '杨士奇', '明代', '圣明图治任忠良，正倚纯诚柱庙堂。画史但知尘外意，青山为写午桥庄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题少师建安杨先生行乐图 其一' AND p.poem_author = '杨士奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长洲种牡丹', '王禹偁', '宋代', '偶学豪家种牡丹，数枝擎露出朱栏。\n晚来低面开檀口，似笑穷愁病长官。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长洲种牡丹' AND p.poem_author = '王禹偁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭袁大玉符卿 其二', '李云龙', '明代', '以嗔为佛事，棒喝是慈悲。未去已先辨，重来不可知。\n\n中郎空有女，伯道竟无儿。地下应含笑，荣名无尽期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭袁大玉符卿 其二' AND p.poem_author = '李云龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和子瞻焦山', '苏辙', '宋代', '金山游遍入焦山，舟轻帆急须臾间。\n涉江已远风浪阔，游人到此皆争还。\n山头冉冉万竿竹，楼阁不见门长关。\n金山共此一江水，只有胜绝无此闲。\n野僧终日饱一饭，与世相视如髦蛮。\n门无舟楫断还往，说法教化鼋鼍顽。\n偶然客至话乡国，西望落日低铜镮。\n岷峨正在日入处，想象积雪堆青鬟。\n稻田一顷良自给，仕宦不返知谁扳。\n久安禄廪农事发，强弓一弛无由弯。\n行逢佳处辄叹息，想见茅屋藏榛菅。\n我知此地便堪隐，稻苗旆旆鱼斑斑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和子瞻焦山' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('请告杜门大司成张公少宗伯赵公学士余公携觞见枉分韵得桑字', '王世贞', '明代', '病起闲门日自长，晚云珍树郁苍苍。驺呵并枉乌衣巷，簪盍聊呼白玉堂。\n\n此别孤踪各朝野，只今何事不沧桑。诸贤莫厌飞觞紧，万拆声中满路霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '请告杜门大司成张公少宗伯赵公学士余公携觞见枉分韵得桑字' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天台道中', '刘宰', '宋代', '花重朝霏散，鸟啼春意深。\n风光自流转，行役负登临。\n涧水流新绿，山云卷夕阴。\n病容兼白鬓，漂泊此时心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天台道中' AND p.poem_author = '刘宰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送似都宪大器巡抚畿北', '程敏政', '明代', '宪节煌煌出帝州，一时风采属君侯。姓名已副苍生望，筹策应分圣主忧。\n\n六郡锄犁思乐岁，三关兵甲待防秋。行台咫尺红尘近，先听封章达冕旒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送似都宪大器巡抚畿北' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('季长赏梅使侍儿歌作诗因次韵', '释德洪', '宋代', '年来槁项皤须发，世眼憎嫌遭栈绝。君独照人如冰轮，洗尽宿云寒皎洁。\n\n今日层楼空独倚，天高衮衮飞鸿灭。掉头哦此赏梅诗，如对北窗香喷雪。\n\n爱君语妙蜕尘埃，道骨自能逃岁月。玉儿岂是解清唱，想见笑中呵手折。\n\n嗅看应作小颦娇，关心不与年时别。一欢纷然云雨散，落英满地蛙声歇。\n\n可怜城郭都不知，新诗一出人争说。和羹他日愿如君，长红袅花歌寿阕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '季长赏梅使侍儿歌作诗因次韵' AND p.poem_author = '释德洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('幽居夙兴', '葛胜仲', '宋代', '宴安毒于鸩，嗜睡真成蛇。揽衣待明发，是味岂不佳。\n\n天宇自澄穆，群嚣肃无哗。喔咿鸡一鸣，众星犹撒沙。\n\n皂荚颒头目，杨枝清齿牙。炉中结愿香，净几对名花。\n\n澄怀睹道秘，浮念无由邪。欠伸起三昧，云锦升朝霞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '幽居夙兴' AND p.poem_author = '葛胜仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('保大五年元日大雪同太弟景遂汪王景逖齐王…登楼赋', '李璟', '唐代', '珠帘高卷莫轻遮，往往相逢隔岁华。春气昨宵飘律管， \n 东风今日放梅花。素姿好把芳姿掩，落势还同舞势斜。 \n 坐有宾朋尊有酒，可怜清味属侬家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '保大五年元日大雪同太弟景遂汪王景逖齐王…登楼赋' AND p.poem_author = '李璟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送谢四之桃源 其二', '丘逢甲', '清代', '昔者陶靖节，为文工寓言。凿空出渔人，飞花满仙村。\n\n遂使啖名者，处处名桃源。蓬莱古仙岛，清浅生沙痕。\n\n沧桑一转瞬，变迁安足论？变迁犹自可，况复成沉沦？\n\n龙伯钓鳌后，三山今无存。恐君到桃源，已异昔所闻。\n\n租税遍桑麻，丁役及子孙。桃花斫为薪，渔舟觅无门。\n\n君当废然返，就我同灌园。送君古渡头，黯然为销魂。\n\n颢气海上来，莽莽风尘昏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送谢四之桃源 其二' AND p.poem_author = '丘逢甲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('岳阳记游 其三', '彭靖', '近代', '飘泊西南天地间，洞庭秋水照苍颜。最怜老病孤舟里，戎马关山泪不乾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '岳阳记游 其三' AND p.poem_author = '彭靖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻警', '李希圣', '清代', '覆盎门边乌鹊栖，建章烽火辽水西。九攻九守会亡宋，三沐三薰能霸齐。\n\n云雨手中有翻覆，瑀璜腰下无解携。羊灯兔月照歌舞，五夜军书来刺闺。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻警' AND p.poem_author = '李希圣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江上', '雪山法师', '明代', '寂历云天色，流观据晚闲。\n野黄潮起树，江黑雨藏山。\n楚甸蒹葭外，夷风瘴疠间。\n儿童相叫笑，直是语绵蛮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江上' AND p.poem_author = '雪山法师';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('正气歌为节妇王母单孺人作', '戴亨', '清代', '乾坤有正气，絪缊磅礴无终始。铸人形，载人理。纲常不立，熙熙攘攘，如此而已。\n\n天地虚生亦虚死。兹气之所钟，不独在男子。黄鹄思故雄，柏舟悲天只。\n\n铁骨坚刚火莫镕，玉质晶莹泥不滓。死者复生，生者弗耻。\n\n精诚可以变天地，梁山一哭城崩圮。絅先之妇单孺人，矢心砺节无乃是。\n\n结缡岁甫更，良人命忽倾。愿随地下袪蝼蚁，不愿局蹐贪馀生。\n\n腹中有子难决绝，大义不合鸿毛轻。夫死三月儿出腹，一线呱呱延似续。\n\n手作口哺傍穗帏，鬼语吹窗枭夜哭。抚畜廿四年，辛勤难备述。\n\n儿成母责终，贞魂含笑归幽谷。事达九重苦节彰，寒泉幽壤褒天章，阴灵皓月同辉光。\n\n君不见木槿花，朝始娇娆暮泥沙。君不见新杨柳，濯濯春条倏枯朽。\n\n陇畔有乔松，亭亭翠盖无春冬。涧底有磐石，怒涛崩奔不改色。\n\n人生百年瞬息间，砥节不如此，天地虚生亦虚死。\n\n呜呼不及此女子。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '正气歌为节妇王母单孺人作' AND p.poem_author = '戴亨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('枕上二首 其一', '陆游', '宋代', '青丝玉井辘轳声，露叶风枝鹎鵊鸣。造物未容闲到死，又从枕上得诗情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '枕上二首 其一' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('更漏子', '姜文载', '清代', '昨宵情，今夜又。岂是等閒能彀。须忍耐，细温存。趁灯儿未昏。\n\n美满。更初转。爱煞绿娇红软。待别后，想而今。相思知更深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '更漏子' AND p.poem_author = '姜文载';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('集唐奉和内兄孙赤城五十自寿元韵十首 其一', '瞿士雅', '清代', '出众风流旧有名，可怜才调最纵横。\n\n右军书画深传髓，庾信文章老更成。\n\n一向花前看白发，七言诗里寄深情。\n\n阳春曲调高难和，觅句难于下赵城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '集唐奉和内兄孙赤城五十自寿元韵十首 其一' AND p.poem_author = '瞿士雅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头', '京镗', '宋代', '为郡邑之光。辄勉继严韵，以谢万分。 \n 百堞龟城北，江势远连空。杠梁济涉，浑似溪涧饮长虹。覆以翚飞华宇，载以鱼浮叠石，守护有神龙。好看发源水，滚滚尽流东。 \n 司马氏，凌云气，盖群公。当年题柱，从此奏赋动天容。果驾轺车使蜀，能致诸蛮臣汉，邛笮道仍通。寄语登桥者，努力继前功。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头' AND p.poem_author = '京镗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('织图二十三首 其九 炙箔', '胤禛', '清代', '温扇花信风，寒酝麦秋雨。葭帘张蟹舍，松盆暖蚕户。\n\n香生雪茧明，光吐银丝缕。门忌少人踪，语燕喧衡宇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '织图二十三首 其九 炙箔' AND p.poem_author = '胤禛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜归', '赵福云', '清代', '疏雨歇残响，凉月澄清辉。步屟出萝径，微寒生客衣。\n\n沙堤一痕白，积水摇参差。野花送微馨，夜静方得知。\n\n幽居隔尘境，兴尽还柴扉。秋声打门急，落叶随人归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜归' AND p.poem_author = '赵福云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮　 集句', '刘基', '元代', '林中独酌邻家酒，门前学种先生柳。灌木自悲吟，风泉清道心。\n\n独行潭底影，蝉噪林逾静。渡口欲黄昏，残阳归掩门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮　 集句' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偕王章甫陈公弼登黄鹤楼 其一', '袁宏道', '明代', '江流千顷蹙云烟，楼阁虽高不似前。画板朱檐遮取尽，争教容纳好山川。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偕王章甫陈公弼登黄鹤楼 其一' AND p.poem_author = '袁宏道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汶川', '顾复初', '清代', '绵虒西去导江东，土俗华夷控御同。山色秾堆牛背上，溪声乱入马蹄中。\n\n绳桥官路通区脱，板屋人家似小戎。今日车书皆混一，无人更说赞皇功。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汶川' AND p.poem_author = '顾复初';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('斋居呈陈二高三兼似故人黄玄林敏及从弟', '周玄', '明代', '槐叶阴阴杨柳垂，高斋独坐日斜时。\n地经积雨多秋竹，鸟惜残花恋故枝。\n卧病山城非中酒，旧游洛社总能诗。\n相从每过扬雄宅，一曲阳春慰所思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '斋居呈陈二高三兼似故人黄玄林敏及从弟' AND p.poem_author = '周玄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荷花', '白玉蟾', '宋代', '小桥划水剪荷花，两岸西风晕晚霞。\n恍似瑶池初宴罢，万妃醉脸沁铅华。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荷花' AND p.poem_author = '白玉蟾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乙亥生日病中作 其一', '屈大均', '明代', '未殉黄泉忍有身，劬劳此日益沾巾。生辰岂复知重九，明发空然念二人。\n\n蒿蔚忧思成贱草，蜉蝣变化本微尘。自今不惜先朝露，有愧瓶罍是鲜民。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乙亥生日病中作 其一' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬娄秀才将之淮南见赠之什（娄秀才，图南也）', '柳宗元', '唐代', '远弃甘幽独，谁云值故人。好音怜铩羽，濡沫慰穷鳞。 \n 困志情惟旧，相知乐更新。浪游轻费日，醉舞讵伤春。 \n 风月欢宁间，星霜分益亲。已将名是患，还用道为邻。 \n 机事齐飘瓦，嫌猜比拾尘。高冠余肯赋，长铗子忘贫。 \n 晼晚惊移律，暌携忽此辰。开颜时不再，绊足去何因。 \n 海上销魂别，天边吊影身。只应西涧水，寂寞但垂纶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬娄秀才将之淮南见赠之什（娄秀才，图南也）' AND p.poem_author = '柳宗元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次志军兄贺岷社成立', '姜军', '当代', '久绝铎声南陌头，竹枝近俗亦非俦。岷山今斫梧桐木，一片清音接素秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次志军兄贺岷社成立' AND p.poem_author = '姜军';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同玄昶上人观山榴', '李咸用', '唐代', '病随支遁偶行行，正见榴花独满庭。 \n 瘦竹成林人不看，却应著得强青青。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同玄昶上人观山榴' AND p.poem_author = '李咸用';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古贤图四绝为临塘婿范樟题 其四 严光', '程敏政', '明代', '一竿名重子陵滩，风景真宜入画看。却恐禄多归计好，羊裘零落钓矶寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古贤图四绝为临塘婿范樟题 其四 严光' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次牧《翁六月七日迎河东君于云间喜而有述》诗 其一', '林云凤', '清代', '天上秋期尚缪悠，先从九夏慰离愁。垂来柳眼窥帘额，绣出花心粲枕头。\n\n翠管双吹谐唳鹤，雕阑并倚笑牵牛。准知宿世蓝桥侣，即在今宵谷水舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次牧《翁六月七日迎河东君于云间喜而有述》诗 其一' AND p.poem_author = '林云凤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与曹学佺林古度过孔雀庵访韫辉上人', '吴兆', '明代', '竹日下清晖，林深一径微。\n萧然瓢室静，可息道人机。\n汲井鸟冲出，开篱蝶绕飞。\n复过邻寺去，留兴月明归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与曹学佺林古度过孔雀庵访韫辉上人' AND p.poem_author = '吴兆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('对雪二首 其一', '顾璘', '明代', '千峰急雪洒茅檐，久旱微阴冷亦堪。独赖诸公忧冻馁，不劳明主顾东南。\n\n高标一任寒梅得，馀润偏宜宿麦含。薄暮倚栏看絮舞，鬓丝相伴两鬖鬖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '对雪二首 其一' AND p.poem_author = '顾璘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史下·曹丕', '陈普', '宋代', '鹊构觚棱偶似诗，鸡栖庭树已当时。\n公车坐使诸侯急，却是奸人篡夺资。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史下·曹丕' AND p.poem_author = '陈普';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('为痴绝和尚赞初祖达磨并马大师画象 其二', '释居简', '宋代', '金鸡毒，一粒粟，未踏杀人，已先跌足。一十八滩兮障回死水，八十四人兮淹浸弗死。\n\n洪都兮泐潭，宗风兮肆凌厉。一波动兮万波起，派兮支兮滔滔者皆是。\n\n更无一个识玄旨，只有归宗较些子。捡点将来，玄沙道底。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '为痴绝和尚赞初祖达磨并马大师画象 其二' AND p.poem_author = '释居简';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题黄溪壁二首', '赵蕃', '宋代', '此邦茶品固多有，闻说黄溪独未尝。\n何日敲门辱持赠，更须高诵碧云章。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题黄溪壁二首' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('佛窟寺', '杨备', '宋代', '曩事何人为证明，白云深锁翠微坑。\n已闻过去辟支佛，未见如来弥勒生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '佛窟寺' AND p.poem_author = '杨备';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭琼州教授印初', '林占梅', '清代', '京邸从游道谊长，遥闻恶耗倍心伤。平生有累惭高足，此劫无辜更断肠。\n\n冷宦家风性朴素，硕儒学术本循良。可怜垂老还乡日，嚼齿含糊为国殇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭琼州教授印初' AND p.poem_author = '林占梅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('霜天晓角　遗镜', '屈大均', '明代', '流尘久入，点点残脂湿。莺影至今犹在，凭香露，掩馀泣。\n\n独立花半执。月中追不及。蟾兔料应相伴，桂树下，敛裙褶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '霜天晓角　遗镜' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次虞枢密九日登高韵', '王质', '宋代', '满拟重阳醉菊觞，花时多已过重阳。年来莫是无知己，未遇渊明不肯香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次虞枢密九日登高韵' AND p.poem_author = '王质';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题清芬阁', '沈长卿', '宋代', '元英以隐名，名德以仕显。\n人言不同调，是说一何浅。\n丈夫生世间，出处各有意。\n仕以行其道，隐以求其志。\n一以隐为高，伊吕当不起。\n一以仕为乐，夷齐不饿死。\n我观二子心，舒卷如春云。\n邂逅作霖雨，本是版筑君。\n乃祖想子陵，桐江饱风月。\n乃孙拥麾幢，遗爱浃闽粤。\n相望二百年，家学留青编。\n冥鸿与栖凤，进退两俱贤。\n秋冬享烝尝，瞻像不泚颡。\n独抱元成经，肯作世南匠。\n种田刈禾黍，种圃收兰芝。\n请诵裳华篇，有之以似之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题清芬阁' AND p.poem_author = '沈长卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和吴盐丞雪中湖上访梅四首', '杨万里', '宋代', '闻君蹈雪访梅花，不怕苏堤十里赊。\n老子怯寒那敢出，地炉榾柮是生涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和吴盐丞雪中湖上访梅四首' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('花铁书镇', '韦骧', '宋代', '铁尺平如砥，银花贴软枝。成由巧匠手，持以镇书为。\n\n弹压全繄尔，推迁实在台。不能柔绕指，方册最相宜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '花铁书镇' AND p.poem_author = '韦骧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('罗汉石', '曾季貍', '宋代', '吾闻大幻师，种种示方便。\n虽於土石中，神力亦周遍。\n君看此翠琅，乃有罗汉面。\n殷勤作礼相，形质皆可辨。\n初观顶相殊，次观双足现，\n僧袍如轻绡，风举势转旋。\n得非方广尊，影落此石片。\n千年磨不尽，若坚金百炼。\n我来一瞻敬，赞叹未曾见。\n摩挲谛玩久，欲去反留恋。\n叮咛善守护，尊者俱神变。\n会当清夜阑，神光照金殿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '罗汉石' AND p.poem_author = '曾季貍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古十七首 其二', '释大观', '宋代', '自是兵家贵伐谋，鏖锋擒敌未为优。沈沈刁斗三更月，玉帐威行紫塞秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古十七首 其二' AND p.poem_author = '释大观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('于晦若上舍招饮寓园', '陈良玉', '清代', '懊恼林鸠故故啼，小园春尽得招携。平池骤涨漂花雨，幽屐新黏迸笋泥。\n\n野水鹭鸥芳墅外，夕阳楼阁断虹西。一樽怀抱聊倾倒，扶杖归来径欲迷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '于晦若上舍招饮寓园' AND p.poem_author = '陈良玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九日夷陵道中', '苏葵', '明代', '旋教篱落种黄花，恰好花时已别家。送酒不闻来水际，寻诗偏恨倚天涯。\n\n渣滩波急诸峰峭，阊阖风高一雁斜。莫道欲归归便得，也曾封事乞烟霞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九日夷陵道中' AND p.poem_author = '苏葵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮（六军阅罢，犒饮兵将官）', '王安中', '宋代', '中军玉帐旌旗绕。吴钩锦带明霜晓。铁马去追风。弓声惊塞鸿。 \n 分兵闲细柳。金字回飞奏。犒饮上恩浓。燕然思勒功。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮（六军阅罢，犒饮兵将官）' AND p.poem_author = '王安中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐 张泽夜宿', '秦鸿', '当代', '巷空车杳。暗寂沈为沼。远市灯华腾野烧。巷口人过光搅。\n\n微阳薄雾微腥。村墟缥似回声。假寐一街衰草，风来小撼馀酲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐 张泽夜宿' AND p.poem_author = '秦鸿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '杨凫', '唐代', '背日流泉生冻早，逆风归鸟入巢迟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '杨凫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七月六日二首', '张耒', '宋代', '雨洗秋城碧玉天，暮云吹尽月娟娟。\n寂寥谁是清宵伴，只有姮娥最可怜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七月六日二首' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('懒融祖师堂二首 其一', '王弘诲', '明代', '为爱幽栖谒慧公，庄严色相半空中。人间底事堪忙甚，一到堂前意已融。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '懒融祖师堂二首 其一' AND p.poem_author = '王弘诲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送张教授子彝之成都', '解缙', '明代', '之官远向锦官城，不用金牛役五丁。庠序贤才古邹鲁，献王声誉汉东平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送张教授子彝之成都' AND p.poem_author = '解缙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日山居好十首 其七', '舒岳祥', '宋代', '春日山居好，柴门爱客过。连朝恣泥饮，随意有山歌。\n\n句小从人学，才衰觉气和。情怀依分足，好景不须多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日山居好十首 其七' AND p.poem_author = '舒岳祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再游南华临出门书记妙莹献绝句索留题赋两篇谢之 其一', '曾丰', '宋代', '诗数江西派，禅归岭表宗。他宁无出手，终莫敢当锋。\n\n欠子广长舌，资吾磊块胸。打包随牒迹，岂料适相逢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再游南华临出门书记妙莹献绝句索留题赋两篇谢之 其一' AND p.poem_author = '曾丰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('瓶花', '孙承宗', '明代', '高牙风峭戟枝寒，杏蕊新香春未阑。\n却忆韦家花树会，关城初向一瓶看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瓶花' AND p.poem_author = '孙承宗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五十又一初度酬李烟客陈冲玄见赠之作', '邓云霄', '明代', '新剪春萝制野衣，烦君芳讯到柴扉。百年坐叹驹过隙，三仕还如鹢退飞。\n\n世外烟霞堪结侣，山中甲子总忘机。平生傲骨终难下，一笑从前事事非。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五十又一初度酬李烟客陈冲玄见赠之作' AND p.poem_author = '邓云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宜男草', '陈三聘', '宋代', '摇落丹枫素秋后。舞长亭、尚余衰柳。别梦回、忆得霜柑分我，应自有、浓香噀手。 \n 宿酲谁解三杯酒。晓山横、望中衔斗。人去也、纵得相逢似旧，问当日、红颜在否。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宜男草' AND p.poem_author = '陈三聘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('之官新定同年李郎中以诗赋别即事感怀次韵上答', '张伯玉', '宋代', '雨后惊涛激箭催，为君停棹把离杯。宦游向老令人笑，别恨伤春触处来。\n\n故国未归江令宅，全家且上子陵台。如今遇酒伸眉醉，休问多才与不才。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '之官新定同年李郎中以诗赋别即事感怀次韵上答' AND p.poem_author = '张伯玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂咏一百首·宁王', '刘克庄', '宋代', '智出建成上，贤于子纠多。\n至今称让帝，当日唤宁哥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂咏一百首·宁王' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('子夜四时歌十六首 冬歌四首 其十三', '萧衍', '南北朝', '寒闺动黻帐，密筵重锦席。卖眼拂长袖，含笑留上客。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '子夜四时歌十六首 冬歌四首 其十三' AND p.poem_author = '萧衍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜雨和秦宗伯', '严嵩', '明代', '焦枯何计讹吹嘘，一雨全胜万斛珠。看舞商羊应得意，听鞭蜥蜴最怜渠。\n\n凉开竹簟眠方稳，日饭盘蔬味自腴。志喜有诗传画省，巴人惭和郢歌馀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜雨和秦宗伯' AND p.poem_author = '严嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('从驾游山诗', '袁奭', '南北朝', '天游响仙跸，春望动神衷。涧水含初溜，山花发早丛。\n\n玉舆明淑景，珠旗转瑞风。平原与上路，佳气远葱葱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '从驾游山诗' AND p.poem_author = '袁奭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('迎仓使李监丞八绝 其四', '曾丰', '宋代', '二十馀年两度来，来宾莲幕主霜台。今吾犹是故吾尔，白眼岂须青眼哉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '迎仓使李监丞八绝 其四' AND p.poem_author = '曾丰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭杨主事', '顾炎武', '清代', '吴下多经儒，杨君实宗匠。方其对策时，已负人伦望。\n\n未得侍承明，西京俄沦丧。五马遂南来，汪黄位丞相。\n\n几同陈东狱，幸遇明主放。牧马饮江南，真龙起芒砀。\n\n首献大横占，并奏东胡状。是日天颜㢠，喜气浮綵仗。\n\n御笔授二官，天墨春俱盎。鱼丽笠泽兵，乌合松陵将。\n\n灭迹遂躬耕，犹为义声唱。松江再蹉跌，搜伏穷千嶂。\n\n竟入南冠囚，一死神慨忼。往秋夜中论，指事并吁怅。\n\n我慕凌御史，仓卒当绝吭。齐蠋与楚龚，相期各风尚。\n\n君今果不食，天日情已谅。陨首芦墟村，喷血胥门浪。\n\n唯有大节存，亦足酬帝贶。洒涕见羊昙，停毫默悽怆。\n\n他日大鸟来，同会华阴葬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭杨主事' AND p.poem_author = '顾炎武';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春秋战国门。王后', '周昙', '唐代', '连环要解解非难，忽碎瑶阶一旦间。 \n 两国相持兵不解，会应俱碎似连环。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春秋战国门。王后' AND p.poem_author = '周昙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高阳台 丁雁水招同观庄纬云目天卫公韬汝及仲儿集八境分赋 其二', '吴绮', '清代', '霜柚垂金，烟霞泛碧，人间又满清秋。怀古登高，一时身在他州。\n\n逋臣望阙肠应断，叹眉山、老泪难收。向西风搔首，而今白发盈头。\n\n何当飞盖携游。有建安才子，正始英流。欲采芙蓉，徒怜渺渺芳洲。\n\n江关岭海皆陈迹，算还输、沙际双鸥。且同教、倚醉凭栏，长啸登楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高阳台 丁雁水招同观庄纬云目天卫公韬汝及仲儿集八境分赋 其二' AND p.poem_author = '吴绮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝇骥', '吕南公', '宋代', '超超飞骥尾，猎猎苍蝇翼。托止如雅素，主之无避色。\n\n相从辄腾蹋，稳望千里益。朝刍雁田粟，夕饮龙渊液。\n\n天山峻杳缭，过若影撩隙。神官下旁闯，展折形叹惜。\n\n为言螴蜳类，命自臭秽得。胡然谬携载，浼尔云天骼。\n\n是时决骤次，何莫怀辟易。骎骎骅骝前，拟越穷发北。\n\n仙风响琳琅，忽遇九方伯。殷勤致羁绊，审按题肉力。\n\n咨嗟绝尘足，恨乏轶群德。悲此中道骥，愤死秀冈侧。\n\n苍蝇试回首，海雾光圛圛。进途当此穷，退路安可识。\n\n寄声人间世，远致毋近测。栖翔度材分，勿妄希彩色。\n\n永鉴蝇骥穷，无妨每相择。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝇骥' AND p.poem_author = '吕南公';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄龚十三', '朱槔', '宋代', '支颐独揖北窗风，怪事从今咄咄空。\n简策不知春色晚，山川浑落战尘中。\n花瓢茵席三生净，草入池塘一句工。\n想见楚龚怀我处，扁舟遨荡夕阳红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄龚十三' AND p.poem_author = '朱槔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵张秘校喜雪三首', '黄庭坚', '宋代', '落月烟沙静渺然，好风吹雪下平田。\n琼瑶万里酒增价，桂玉一炊人少钱。\n学子已占秋食麦，广文何憾客无毡。\n睡余强起还诗债，腊里春初未隔年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵张秘校喜雪三首' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙 读向东君雪后初晴诗后作', '顾敏燕', '当代', '雪后初晴山色明，身临高处少人行。春风心事北风听。\n\n难得贪杯留醉意，也思借景写深情。何如飞雪舞轻盈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙 读向东君雪后初晴诗后作' AND p.poem_author = '顾敏燕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('北槛', '陆游', '宋代', '北槛近中堂，缘阶物自芳。\n晨清花拱露，地僻藓侵廊。\n坐久时闲卷，吟余或炷香。\n终朝无客至，一枕到羲皇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '北槛' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其一', '林大声', '宋代', '南徐江山天下雄，沿江一水如蟠龙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其一' AND p.poem_author = '林大声';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次潘德久韵', '陈造', '宋代', '沉沉王侯居，列屋皆妖妍。\n性斧糜春葱，日诧歌舞筵。\n孰知山泽儒，超然广文毡。\n野花供妩媚，山月献连娟。\n潘郎真吾徒，常加视后鞭。\n居无鲍生马，红粉风蓬旋。\n张公为石奴，处仲政复贤。\n继今看远业，贱子当留年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次潘德久韵' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('帝京篇十首 其二', '李世民', '隋代', '岩廊罢机务，崇文聊驻辇。玉匣启龙图，金绳披凤篆。\n\n韦编断仍续，缥帙舒还卷。对此乃淹留，欹案观坟典。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '帝京篇十首 其二' AND p.poem_author = '李世民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('张参戎园十首 其十', '顾璘', '明代', '将军池下水，洗砚变成玄。地觉风流胜，人疑造化偏。\n\n龙蟠云共黑，鹅戏雪矜妍。报尔山阴县，王家旧事传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '张参戎园十首 其十' AND p.poem_author = '顾璘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游山阳十首', '陈造', '宋代', '会看亭下水涵空，菡萏香中理钓筒。\n北道主人吾有托，不应独飨北窗风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游山阳十首' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('羊城王公子有小史秀儆绝伦远别还家以纨扇素挥去燕并题赠之', '张穆', '明代', '今年别似去年时，海国秋花散绿漪。轻薄共怜王谢客，蹁跹如见赵家姨。\n\n难留珠箔霜前影，肯负红丝社后期。惆怅送伊何日返，不应容易傍人篱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '羊城王公子有小史秀儆绝伦远别还家以纨扇素挥去燕并题赠之' AND p.poem_author = '张穆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('云谷杂诗十二首 其十一 下山', '朱熹', '宋代', '行随流水声，步出哀壑底。绿树枝相樛，白涧石齿齿。\n\n树石无穷年，流水日千里。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '云谷杂诗十二首 其十一 下山' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('废圃蜀葵盛开，偶成七绝', '王润生', '清代', '年年废圃我葵放，浅紫深红艳若何。一丈高枝花百朵，被人嫌处只缘多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '废圃蜀葵盛开，偶成七绝' AND p.poem_author = '王润生';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜算子 其二 楼', '俞士彪', '清代', '近水碧窗明，隔柳珠帘细。残月看看又过西，有个人儿倚。\n\n燕子已空来，红粉曾轻坠。藏得离愁有万千，天末浮云起。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜算子 其二 楼' AND p.poem_author = '俞士彪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('甲午闰重阳', '熊东遨', '当代', '一年两度遇重阳，前值清霜后白霜。天道有时无秩序，人心从此费猜详。\n\n三千好梦成何事，九十慈亲尚在堂。些小私怀言不得，登高只为望家乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '甲午闰重阳' AND p.poem_author = '熊东遨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄题阳居士高节轩', '洪朋', '宋代', '中条阳亢宗，高义照千古。婵嫣不无人，闻风吾已许。\n\n平生知味处，潇洒送寒暑。敏树印此心，柯叶傲风雨。\n\n岑夜入天籁，韵作太上语。一切得入律，真成众香树。\n\n贤者早求仁，行李遍八宇。归来林丘下，岁寒色如故。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄题阳居士高节轩' AND p.poem_author = '洪朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辛亥除夕三首 其三', '戴良', '元代', '移居湖水上，已是一年期。客路频辞岁，家山忘别时。\n\n庭寒无鹊噪，春近有梅知。此夜伤情极，椒觞懒独持。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辛亥除夕三首 其三' AND p.poem_author = '戴良';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵道辅丈荆州吟四首', '吴则礼', '宋代', '田园岁晚欲榛芜，短褐苍颜与世疏。\n华屋徒惊栖万卷，伤心投老已捐书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵道辅丈荆州吟四首' AND p.poem_author = '吴则礼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读四家诗选四首 其三 退之', '李纲', '宋代', '昌黎文章伯，乃是圣人耦。传道自孟轲，渊源极师友。\n\n雄词障百川，伟论挂众口。馀事付诗篇，雅健古无有。\n\n尤工用险韵，妥贴等妍丑。毅然倔强姿，挥此摩天手。\n\n立朝著大节，去作潮阳守。驱扫云雾开，约束鲛鳄走。\n\n位虽不称德，妙誉垂不朽。譬犹观泰山，群岭皆培塿。\n\n又如众星中，错落仰北斗。籍湜何足云，齐名岂其柳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读四家诗选四首 其三 退之' AND p.poem_author = '李纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('钱塘怀古', '郑珞', '明代', '双龙北去归辽海，匹马南来叹寂寥。一代兴亡吴苑月，千年感慨浙江潮。\n\n岳王墓上松声惨，伍子祠前剑气消。游女不知行客恨，夜深湖上更吹箫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '钱塘怀古' AND p.poem_author = '郑珞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('息影二律 其一', '刘家传', '近代', '息影江城自在身，香飞兰芷日相亲。生无媚骨难谐俗，死有残书可抵贫。\n\n室陋何妨知我客，诗豪不和背时人。雨天伫盼晴来早，好探郊原浩荡春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '息影二律 其一' AND p.poem_author = '刘家传';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭黄应初山人二首 其一', '王慎中', '明代', '碧山长在人何处，豪气杯中恍可寻。灵魄应随辽海鹤，遗风犹寄广陵琴。\n\n同盟猿狖惊多梦，旧抚松筠怨独阴。佳句卷中时把玩，堪嗟已是古人唫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭黄应初山人二首 其一' AND p.poem_author = '王慎中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游玉隆宫四', '曹勋', '宋代', '至日西山道路长，逍遥暂喜息奔忙。\n无人共饮山村酒，只对清虚一炷香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游玉隆宫四' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题画', '边贡', '明代', '空江夕烟敛，日色沙上明。轻涟漾兰楫，袅袅秋风生。\n\n白云满层阿，林光带高城。姬文去已远，讵辨垂纶情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题画' AND p.poem_author = '边贡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丁巳元宵韩炅庵送灯', '杨慎', '明代', '多病新春减醉狂，元宵作剧懒逢场。华灯珍重劳相赠，绣佛前头礼定光。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丁巳元宵韩炅庵送灯' AND p.poem_author = '杨慎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('客秋偶憩西子湖皆令携幼女过访发方覆额遂能诵诗写法帖楚楚可人今依然梦想间并裁小诗似之', '朱中楣', '清代', '瑟瑟轻罗澹澹妆，柳梢莺语乍调簧。乌云应拂春山小，红蕊初含夜雨香。\n\n鸳水毓灵多鲍谢，蝇头妙楷逼钟王。梦回犹记殷勤别，几欲笺诗燕子忙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '客秋偶憩西子湖皆令携幼女过访发方覆额遂能诵诗写法帖楚楚可人今依然梦想间并裁小诗似之' AND p.poem_author = '朱中楣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('右揆邹公由齐入闽齐人有华泉子者与公友抱病不获出饯作诗以遗之三首 其二', '边贡', '明代', '黄鹂鸣树颠，嘤嘤求友声。佳人远言迈，牵我幽思情。\n\n思情何绵绵，绵绵复萦萦。出门望轩盖，道阻不可征。\n\n霭霭山气浮，晶晶川云平。鸿雁方北飞，谁哉达中诚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '右揆邹公由齐入闽齐人有华泉子者与公友抱病不获出饯作诗以遗之三首 其二' AND p.poem_author = '边贡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('道中即事 其八', '方岳', '宋代', '上到春山顶𩕳头，更携烟雨入吾州。梅花便作乡人看，飞落酒杯相劝酬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '道中即事 其八' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登雅宜山', '李延兴', '元代', '鸡犬柴扉竹里开，仙人别住好楼台。松声忽向琴心起，云气遥从涧口来。\n\n六代衣冠随水去，百年天地逐轮回。兴亡总付登临外，烂醉春风卧碧苔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登雅宜山' AND p.poem_author = '李延兴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送处度赴试', '释道潜', '宋代', '异哉曲阜几世孙，白玉受性良且温。诗书礼义祖家学，扰扰自馀何足论。\n\n良辰往往专吟讽，远压曹刘攀屈宋。\n\n肯与齐梁作后尘，秋月春花恣嘲弄。我方杖策过西州，指点云山结胜游。\n\n已有诏书催去兴，岂宜泉石更淹留。征车晓送登长陌，月没参横河汉白。\n\n期君安稳上龙门，不怕临流遭点额。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送处度赴试' AND p.poem_author = '释道潜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('柳枝词', '吴鼎芳', '明代', '绿阴如雨万条斜，啼罢朝莺又晚鸦。\n尽日春风无别意，只吹花点过西家。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '柳枝词' AND p.poem_author = '吴鼎芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送任寿朋赴襄阳令', '项安世', '宋代', '潭心山顶碑何在，凤翥龙翔梦亦非。\n野锸狼烟参井亩，城开雁坡入江圻。\n蟠胸橐帙千年当，手到鸡锋一映微。\n应待经行阡陌偏，唤登文石问兵机。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送任寿朋赴襄阳令' AND p.poem_author = '项安世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高士咏。郑子真张仲蔚', '吴筠', '唐代', '子真岩石下，仲蔚蓬蒿居。礼聘终不屈，清贫长晏如。 \n 心情在耕艺，养寿资玄虚。至乐非外物，道冥欢有馀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高士咏。郑子真张仲蔚' AND p.poem_author = '吴筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏吟', '张继先', '宋代', '落魄正当年，人皆笑我颠。\n乾坤时运动，沦海渺无边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏吟' AND p.poem_author = '张继先';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄陈柱尊 乙卯', '冯振', '近代', '君本岑寂士，我亦清閒人。孜孜岂为利，戚戚非畏贫。\n\n虽存救世念，何尝忘隐沦。志同愿亦等，莫逆相交亲。\n\n谓言学成日，与世同一新。然后赋归来，相将干白云。\n\n肆志山水间，麋鹿以为群。得失不复知，理乱非所闻。\n\n放浪形骸外，惟有酒一尊。君已得所愿，我犹牵俗尘。\n\n出处类参商，言笑难为因。宇宙为蘧芦，万里犹比邻。\n\n何必同一室，然后尽殷勤。瑟瑟生悲风，惨惨兴愁云。\n\n弱肉强之食，一屈难再伸。纵有桃源地，宁能避暴秦。\n\n岂宜慕原宪，方当效终军。閒居非今日，盍共拯斯民。\n\n功成归田去，长揖当途人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄陈柱尊 乙卯' AND p.poem_author = '冯振';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秣陵 其一', '仇远', '宋代', '凿山疏水出长江，王气如何可厌禳。后五百年依旧在，空教晋帝笑秦皇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秣陵 其一' AND p.poem_author = '仇远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('集李绝句十八首 其十 登泗水亭', '程敏政', '明代', '青山行尽入红尘，古木亭边夜向晨。书未隔年难得报，我来登望倍凝神。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '集李绝句十八首 其十 登泗水亭' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄守坚觉初二僧', '苏舜钦', '宋代', '曾携旧书卷，来宿古禅林。方外求知性，诗中得赏音。\n\n炉开山夜静，门掩雪天阴。杌上一寒砚，灯前三苦吟。\n\n韵强颜汗落，句切鬓丝侵。玉就还重琢，河穷更远寻。\n\n穴争探乳虎，沙独拣良金。字稳天星转，篇终海月沈。\n\n唱酬同记录，得失暗规箴。木铎不徇路，薰风难和琴。\n\n半生谁引手，中道比分襟。分野三吴阔，年华二纪深。\n\n师方传祖印，我欲谢朝簪。岭外烟岚地，湖边云水心。\n\n情悰张翰鲙，梦想陆机禽。松下莓苔石，何年重访临。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄守坚觉初二僧' AND p.poem_author = '苏舜钦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寂历古关道二首 其二', '李廌', '宋代', '寂历古关道，晓烟寒未分。愁情满秋草，归思隔黄云。\n\n客路自多感，宿酲犹带醺。萧萧倦游意，况乃久离群。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寂历古关道二首 其二' AND p.poem_author = '李廌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雁影三首 其二', '李祁', '近代', '江南词客作幽囚，玉砌雕阑念旧游。我亦泪痕常被面，难将绮句写深愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雁影三首 其二' AND p.poem_author = '李祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风雨驻太湖作茶池亭记又诗四绝 其二', '杨起元', '明代', '芭蕉几树萎阶楹，已遇深春寒未生。却喜嘘枯有时雨，不妨征幰暂停行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风雨驻太湖作茶池亭记又诗四绝 其二' AND p.poem_author = '杨起元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洞庭秋三十首 其二十六', '王夫之', '明代', '鹧鸪声断西日浮，君山未愁黄陵愁。白浪几何倾楚塞，金风既展讫神州。\n\n萧飒万个撼斑管，迢递千古疑胶舟。贾至张说尔何物，落拓欲牵万里忧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洞庭秋三十首 其二十六' AND p.poem_author = '王夫之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谒遗爱王祠二首 其二', '岳珂', '宋代', '大帝开江左，谋臣守四方。兴邦有乔木，遗爱尚甘棠。\n\n日月扶声烈，山川诧郁苍。中原知极目，应慨旧封疆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谒遗爱王祠二首 其二' AND p.poem_author = '岳珂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天台梵才师长吉在都数以诗笔见授因答以转句 其七', '宋祁', '宋代', '比来缁侣颇言文，局促啁啾宁足论。私地蛙鸣徒聒耳，长沙国小仅回身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天台梵才师长吉在都数以诗笔见授因答以转句 其七' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卿怜小影三首 其二', '夏孙桐', '清代', '堕混飘茵总逝波，春花秋月几销磨。长安棋局朝朝变，两度沧桑不算多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卿怜小影三首 其二' AND p.poem_author = '夏孙桐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('持钵 其二', '释居简', '宋代', '乐岁持盂尚许艰，有求那解破人悭。立残穰草堆头日，撑尽苹芜断处湾。\n\n钟鼓敢嫌贫指众，斗筲庸恤老腰顽。归舟只载华亭月，不作华亭误夹山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '持钵 其二' AND p.poem_author = '释居简';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绍隆院池上五首 其一', '韩维', '宋代', '细雨疏烟冒广池，危亭晨坐冷侵衣。秋风不作羁人便，波面萧萧柳叶飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绍隆院池上五首 其一' AND p.poem_author = '韩维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('下章安杜渎七首 其二', '姚宽', '宋代', '帆落秋风泊暮滩，月生潮上客心閒。海门南望天侵水，左直金鳌驻跸山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '下章安杜渎七首 其二' AND p.poem_author = '姚宽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('伤张荫麟', '钱钟书', '当代', '清晨起读报，失声惊子死。\n天翻大地覆，波云正谲诡。\n绝知无佳讯，未忍置不视。\n赫然阿堵中，子占一角纸。\n大事记馀墨，为子书名字。\n厥生固未荣，死哀斯亦止。\n犹蒙稽古力，匪然胡及此。\n吴先斋头饭，识子当时始。\n南荒复再面，阔别遂万里。\n赋诗久忆删，悲子亦不起。\n夙昔矜气隆，齐名心勿喜。\n舜钦负诗字，未屑梅周比。\n时人那得知，语借颇中理。\n忽焉今闻耗，增我哀时涕。\n气类惜惺惺，量才抑末矣。\n子学综以博，出入玄与史。\n生前言考证，斤斤务求是。\n乍死名乃讹，荫蔓订鱼豕。[沪报皆作张蔓麟]\n翻成校雠资，待人辨疑似。\n子道治子身，好还不少俟。\n造化固好弄，非徒夺命尔。\n吾徒甘殉学，吁嗟视此士。\n龙场丞有言，吾与汝犹彼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '伤张荫麟' AND p.poem_author = '钱钟书';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题鄱湖兄山水小幅', '熊盛元', '当代', '石罅清泉流，仙源翠云锁。幽人性恬淡，携樽松阴坐。\n\n影落深涧中，不辩物与我。何为憺忘归，此间无秦火。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题鄱湖兄山水小幅' AND p.poem_author = '熊盛元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晓发碛礇枕上口占', '郭谏臣', '明代', '残酒初醒后，寒灯欲灭时。霜飞蓬户早，月落戍楼迟。\n\n未解闻鸡舞，徒兴梦鹿思。诗成还稳睡，此意少人知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晓发碛礇枕上口占' AND p.poem_author = '郭谏臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过东庄看梅 其三', '吴之振', '清代', '北户新除径，相随偩竹登。周遭莺语滑，荡漾水痕增。\n\n过雨移茶种，添流间麦塍。无心阶下草，散发任鬅鬙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过东庄看梅 其三' AND p.poem_author = '吴之振';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('醉歌行赠夏叔干', '乌斯道', '明代', '昨日江上沙，东头涨起西头倒。今日江上沙，西头渐高东头少。\n\n子少我方壮，子壮我衰老，气义还如旧时好。我昔南回凌瘴烟，恶风掀𥳽西江船。\n\n归来无处采薇蕨，自向江头弄明月。隔江美人招我游，白沙翠竹明月舟。\n\n天风潇潇落寒水，一去便为三日留。回头看人世，人世可长叹。\n\n赠人不有锦绣段，谁肯报之青玉案。子独爱我春草青，我独爱子双眼明。\n\n凹镜那知玉颜好，急弦始见枯桐清。莫信飞鸿书可寄，莫信盟鸥不相弃。\n\n不如浇密向饧中，到底甘甜复联缀。子有酒浮玉缸我，有诗充锦囊我醉。\n\n子酒子歌我诗诗，馀酒醉春阳熙熙。醉里乾坤漫颠倒，梨花乱发流莺啼。\n\n莺啼不须歇，梨花不须落，古道千年只如昨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '醉歌行赠夏叔干' AND p.poem_author = '乌斯道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹闲亭 曲水亭', '林旦', '宋代', '岩溜抱山急，传觞何太频。回看野客醉，还笑浊醪醇。\n\n汉曲人方远，兰亭迹已陈。劳生无足校，酣放即天真。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹闲亭 曲水亭' AND p.poem_author = '林旦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('承示会稽大资政公思归篇辄次元韵', '沈辽', '宋代', '进退不辱古已稀，能如二疏盖有数。中间已辞五鼎食，今年欲洁一身去。\n\n引身欲去强辞老，东部聊复颁宽诏。人间万事如一梦，何人颠倒真可笑。\n\n红梅夜发新春枝，黄堂晏坐赋思归。已知无心更无碍，青山历历孤云飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '承示会稽大资政公思归篇辄次元韵' AND p.poem_author = '沈辽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟达黄溪', '姚燧', '元代', '草木随寒暑，殊方荣悴同。苇花兼露白，柽叶未霜红。\n\n日月双飞鸟，江湖一病翁。晚来沙屿上，愁坐独书空。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟达黄溪' AND p.poem_author = '姚燧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('回岐道中', '陈献章', '明代', '回岐接水树冥冥，又是朝京一日程。两耳如闻重译语，几时不见五仙城。\n\n朝无儿稚歌行酒，夜有巡船卧打更。欲识羁情多少在，昆崙深处白云生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '回岐道中' AND p.poem_author = '陈献章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百二十三首 其七十四', '释普度', '宋代', '不钉桃符，不悬艾虎。驾铁牛机，击涂毒鼓。千妖百怪尽潜踪，灵鹫峰高日卓午。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百二十三首 其七十四' AND p.poem_author = '释普度';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋风', '唐鼎元', '近代', '秋风吹锦水，万里客何依。涕泗关山阔，心胸雷电飞。\n\n死生望汉将，寇虏殛天威。豁见康衢出，此身胡不归？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋风' AND p.poem_author = '唐鼎元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('双调望江南 其八', '董元恺', '清代', '湖上舫，红粉漾晴空。绣幕微褰清影里，纱窗半启碧波中。\n\n小泊断桥东。\n\n凭栏望，心事暗惺忪。六曲银屏妆镜晓，一帘春水黛痕浓。\n\n摇入藕花丛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '双调望江南 其八' AND p.poem_author = '董元恺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舂暮与行书记过师子林', '姚道衍', '明代', '偶同看竹过林庐，素抱欣从此日舒。\n浅碧云虚泉落后，孤红霞澹涧芳余。\n放禅时至钟鸣室，施食人回鸟下除。\n胜地每嫌山水隔，不因乘兴到应疏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舂暮与行书记过师子林' AND p.poem_author = '姚道衍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '杜去轻', '宋代', '缘曾分明种，故发入云香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '杜去轻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑子', '易顺鼎', '清代', '缃桃花下留春住，春又忽忽。嫩翠憨红。消得帘钩昨夜风。\n\n楼阴压梦无寻处，闲了游骢。冷了吟。蜂。险被春愁误煞侬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑子' AND p.poem_author = '易顺鼎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感寓 其十八', '刘弇', '宋代', '昔人泣昆崙，泣使变清流。嫠妇不恤纬，琐琐悲宗周。\n\n薄蚀叔辄号，负阻愚公愁。曾无百年身，浪自遗私忧。\n\n野马袭日观，蚍蜉控岑楼。齐客有高蹈，箕山无辍耰。\n\n足己不累物，一毛轻九牛。寄言悠悠子，毋贻尸祝羞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感寓 其十八' AND p.poem_author = '刘弇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('壶天园歌', '耶律铸', '元代', '三十六洞天，七十二福地。共春长在一壶中，尽可浮游与沈醉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '壶天园歌' AND p.poem_author = '耶律铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('刘方伯邀游风洞二首 其二', '黄镐', '明代', '朝宴虚堂晚未休，满前风景快双眸。好山万叠浓如黛，新水一湾清似油。\n\n奉使情怀输旷达，校文诗句费啁啾。兴阑不记人扶醉，犹自题诗纪胜游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '刘方伯邀游风洞二首 其二' AND p.poem_author = '黄镐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗二十二首 其二十二', '曹于汴', '明代', '浩歌复浩歌，人世奈心何。心心山海隔，心心筹算多。\n\n相隔生睊忿，多算少安和。我生灵万类，寸心更靡它。\n\n胡为翻自苦，憧憧起干戈。吾将驱此心，委诸东流波。\n\n不分秦与楚，不知唯与阿。可使眉无促，可使鬓无皤。\n\n百年能几日，浩歌复浩歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗二十二首 其二十二' AND p.poem_author = '曹于汴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('修褉日入金陵', '邓云霄', '明代', '垂柳临清水，风光动褉辰。湖山如待客，花木总宜春。\n\n细草偏承履，游轩不染尘。繁华今古事，惆怅六朝人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '修褉日入金陵' AND p.poem_author = '邓云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浪淘沙·赋虞美人草', '辛弃疾', '宋代', '不肯过江东。玉帐匆匆。至今草木忆英雄。唱著虞兮当日曲，便舞春风。 \n儿女此情同。往事朦胧。湘娥竹上泪痕浓。舜盖重瞳堪痛恨，羽又重瞳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浪淘沙·赋虞美人草' AND p.poem_author = '辛弃疾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自大散以往深林密竹磴道盘曲四五十里至黄牛岭见黄花川', '王维', '唐代', '危径几万转，数里将三休。\n回环见徒侣，隐映隔林丘。\n飒飒松上雨，潺潺石中流。\n静言深溪里，长啸高山头。\n望见南山阳，白露霭悠悠。\n青皋丽已净，绿树郁如浮。\n曾是厌蒙密，旷然销人忧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自大散以往深林密竹磴道盘曲四五十里至黄牛岭见黄花川' AND p.poem_author = '王维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('懊侬歌十四首 其十三', '佚名', '魏晋', '山头草。欢少四面风。趋使侬颠倒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '懊侬歌十四首 其十三' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪庭，为龙华阁康上人赋', '张昱', '元代', '请教雪庭谁是雪，雪消应始我初心。问知达摩来东土，唯有神光在少林。\n\n清净观空三昩见，吉祥风软六花深。半空挂在羚羊角，踪迹无因向下寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪庭，为龙华阁康上人赋' AND p.poem_author = '张昱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南楼晚望', '李弥逊', '宋代', '海角长安望尔赊，日边云影更横斜。\n身闲梦觉俱成蝶，眼病朝昏只见花。\n可但陶潜能避俗，不应范蠡便浮家。\n君恩未报惊华发，目断飞鸿水四涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南楼晚望' AND p.poem_author = '李弥逊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阳春曲 熏笼', '赵熙', '清代', '织香筠，煨宿火，椒眼巧于珠络。消受十分春，银荷外，镇日相守翠云幕。\n\n不成孤酌。新上脸桃花浓萼。同是一片冰心，者温存小红方觉。\n\n坐清漏南宫，罗巾单薄。谁化得春冰泪落。窗前馀灰拨处，印鞋尖缓步妆阁。\n\n猧儿解伴寂寞。甚暗里钻人裙角。秪深夜撇了冬郎抱，怎生睡著。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阳春曲 熏笼' AND p.poem_author = '赵熙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阳春梁飘兄赠蜡石', '陈永正', '当代', '冻玉玲珑出涧川，亿年摩荡极天然。谁能悟得无言意，即入南宗最上禅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阳春梁飘兄赠蜡石' AND p.poem_author = '陈永正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其一', '元绛', '宋代', '九重侍从三明主，四纪乾坤一老臣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其一' AND p.poem_author = '元绛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('朱致祥教谕饮酒奕棋与仆略相上下不见旬日作二诗招之 其二', '李光', '宋代', '老罢无人断送秋，惟凭一酌散千忧。莫嫌白酒难成醉，尚有黄花插满头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '朱致祥教谕饮酒奕棋与仆略相上下不见旬日作二诗招之 其二' AND p.poem_author = '李光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐 靳仲云年八十，自河南来。江翼云、徐森玉觞之于锦江楼上，仲云即席索词，为赠', '汪东', '清代', '黄河奔越。洒尽头边雪。形势中原推第一。雅称诗情飙发。\n\n飘然杖屦南来。高楼同赆霞杯。笑问梁园宾客，如今谁是邹枚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐 靳仲云年八十，自河南来。江翼云、徐森玉觞之于锦江楼上，仲云即席索词，为赠' AND p.poem_author = '汪东';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四时般若', '释法泰', '宋代', '林木萧条复本根，严霜冻雪鏁松门。\n地炉煨火通身暖，寒暑到来休更论。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四时般若' AND p.poem_author = '释法泰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贺新郎·知彼须知此', '冯取洽', '宋代', '知彼须知此。问筹边、攻守规模，云何则是。景色愔愔犹日暮，壮士无由吐气。又安得、将如廉李。燕坐江沱甘自蹙，笑腐儒、枉楦朝家紫。用与舍，徒为耳。黄芦白苇迷千里。叹长淮、篱落空疏，仅馀残垒。读父兵书宁足恃，击楫谁盟江水。有识者、知其庸矣。多少英雄沈草野，岂堂堂、吾国无君子。起诸葛，总戎事。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贺新郎·知彼须知此' AND p.poem_author = '冯取洽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蓼花和韵', '苏仲', '明代', '挥毫曾记昔年游，每爱幽葩傍素秋。可是水仙遗骨骼，只随烟月伴沧洲。\n\n江山识面扁舟客，天地无心老钓裘。我亦分明湖海士，轻红留照木兰舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蓼花和韵' AND p.poem_author = '苏仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晒蓑亭 其二', '赵蕃', '宋代', '冰玉溪山近与邻，我舟来往故成频。眼边风物浑如旧，只欠行吟采若人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晒蓑亭 其二' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('消夏二首得歌字 其一 旧史', '张中行', '近代', '天心庙略定如何，百世谁闻击壤歌。故纸商周仍礼乐，深宫父子亦干戈。\n\n岂无汗简传高手，应有閒庭设雀罗。束带嵩呼多少事，几人归去老烟蓑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '消夏二首得歌字 其一 旧史' AND p.poem_author = '张中行';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七夕口占', '张镃', '宋代', '凉生金井未飘桐，月户星楼记古风。\n乞巧频年但成拙，懒将祈请效儿童。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七夕口占' AND p.poem_author = '张镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('淮阴侯', '梅尧臣', '宋代', '功既高天下，身何不自防。\n已能成汉业，无复假齐王。\n复耻哙为伍，安知吕所忘。\n空名流未竭，淮水共汤汤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '淮阴侯' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过临平二首 其二', '汪藻', '宋代', '睡起凉生岸，钩帘坐小窗。麦风能起柁，梅雨不鸣江。\n\n往事心长折，归涂影自双。依然蒲柳地，人老故先降。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过临平二首 其二' AND p.poem_author = '汪藻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('箜篌谣二首寄季长少卿', '陆游', '宋代', '少壮离别时，回顾日月长；会合终有期，何恨天一方。\n我齿如败屐，君发如新霜，余日复几何，万里遥相望。\n欲泣老无泪，欲梦不可常。\n寄书何时到？江汉春茫茫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '箜篌谣二首寄季长少卿' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东湖即景 其二', '林庆旺', '清代', '一苇舟行游兴阑，锦鳞磅礡共垂竿。萍依泽畔岸连袂，星覆津头矶戴冠。\n\n籹牖云斜梳曲鬓，烟波日落镜悬盘。东湖今作西湖赏，也许骚人极目看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东湖即景 其二' AND p.poem_author = '林庆旺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题李少府别业', '唐求', '唐代', '寻得仙家不姓梅，马嘶人语出尘埃。竹和庭上春烟动， \n 花带溪头晓露开。绕岸白云终日在，傍松黄鹤有时来。 \n 何年亦作围棋伴，一到松间醉一回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题李少府别业' AND p.poem_author = '唐求';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和张直可投诗十首 其九', '王洋', '宋代', '楚楚才名六尺身，此间襟度有殊珍。瓶无馀粟难论富，箧有风光不似贫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和张直可投诗十首 其九' AND p.poem_author = '王洋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('逍遥咏 其二', '赵炅', '宋代', '遁迹深岩谷，身闲未是闲。研穷堪语默，寂静杳冥间。\n\n秘密逢邪见，难开大道关。金丹无效用，弗可返童颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '逍遥咏 其二' AND p.poem_author = '赵炅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('癸卯寓杭戏写目送飞鸿手挥五弦图潦草为婢子所笑因题与女玉祥收为刘氏清话', '张宁', '明代', '九月十五住杭州，潇潇风雨生离愁。閒寻败笔作图画，生纸烂墨伤昏眸。\n\n小鬟立侍笑欲倒，走入幽闺向娘道。山头颓似土灰堆，树根乱若蓬蒿草。\n\n空中四鸟飞横斜，笔浓大如赤老鸦。乌纱素服一閒客，坐看去鸟弹琵琶。\n\n我生不是丹青者，适兴投情恣挥写。等閒涂抹岂足言，便有旁观说高下。\n\n何况嵇康妙绝伦，清谈旷视能容身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '癸卯寓杭戏写目送飞鸿手挥五弦图潦草为婢子所笑因题与女玉祥收为刘氏清话' AND p.poem_author = '张宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜读离骚', '华岳', '宋代', '楮衾封冷白凝霜，展转无眠夜未央。\n风欲送愁先卷帐，雨嫌多梦故敲窗。\n自惭鼓瑟投齐好，谩接歌舆效楚狂。\n起把离骚读幽闷，楚词还似楚江长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜读离骚' AND p.poem_author = '华岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀内二首 其一', '张家玉', '明代', '闺中昨日起离愁，杨柳青青送客舟。今夕凄凉又何处，半帆烟雨楚江秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀内二首 其一' AND p.poem_author = '张家玉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('效古十九首 其十一', '黄仲昭', '明代', '驱车早言旋，胡为事远游。韶华如昨日，金风复飕飗。\n\n百年驹过隙，人生难久留。惟思早立身，可以传千秋。\n\n光阴苟蹉跎，倏忽委山丘。去去从此始，弩力慎勿休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '效古十九首 其十一' AND p.poem_author = '黄仲昭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八月八日在舟中作', '林朝崧', '清代', '桂落三山开琐院，群雄此日校文战。邹、郭同分市骏金，由基独试吟猿箭。\n\n有人抱璞涉风波，云是当年旧卞和。怅望玉门难自献，回思刖足一高歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八月八日在舟中作' AND p.poem_author = '林朝崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乙丑中秋与山 其五', '史尧弼', '宋代', '海门湖上东畔开，海东飞仙呼不来。乘桴便欲径浮去，无人从我复空回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乙丑中秋与山 其五' AND p.poem_author = '史尧弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('莪默绝句集译笺乙集 其一四九', '伯昏子', '当代', '旧欢惟剩假名存，旧友于今剩酒浑。倾盖相逢当悃款，除非对盏乐何论。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '莪默绝句集译笺乙集 其一四九' AND p.poem_author = '伯昏子';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐·春风依旧', '赵令畤', '宋代', '春风依旧，著意隋堤柳。搓得鹅儿黄欲就，天气清明时候。\n去年紫陌青门，今宵雨魄云魂。断送一生憔悴，只消几个黄昏？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐·春风依旧' AND p.poem_author = '赵令畤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题绣君女史百花卷子', '管筠', '清代', '云裳月佩各清华，斑管凝香绚彩霞。知我性耽禅悦惯，毫端多写妙莲花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题绣君女史百花卷子' AND p.poem_author = '管筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('兵马俑 其二', '姚佳', '当代', '六国未连横，醒时尽杀声。哀其伤病死，换得度量衡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '兵马俑 其二' AND p.poem_author = '姚佳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('熊主簿示梅花十绝诗至梅花已过因观海棠辄次', '刘克庄', '宋代', '海棠洞下醉忘归，岁月如驰不可追。\n想得千株今合抱，此生未卜再游时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '熊主簿示梅花十绝诗至梅花已过因观海棠辄次' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '李先', '宋代', '宁舍济川航。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '李先';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重登滕王阁', '李涉', '唐代', '滕王阁上唱伊州，二十年前向此游。 \n 半是半非君莫问，好山长在水长流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重登滕王阁' AND p.poem_author = '李涉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('方公说通直见示与小子京和答棋诗四篇因次本韵继蒙宠惠前后凡十五篇牵强奉答 其三', '苏颂', '宋代', '久从閒僻向沧池，忽见嘉宾喜可知。触热正烦思美荫，卧疴方苦遘良师。\n\n欲留尽兴时须饮，要取忘忧祗有棋。二者已欣陪造适，解颐仍得鼎来诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '方公说通直见示与小子京和答棋诗四篇因次本韵继蒙宠惠前后凡十五篇牵强奉答 其三' AND p.poem_author = '苏颂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('尹楼岩久留华亭', '朱南杰', '宋代', '风雷昨夜揭窗纱，未信楼岩不忆家。\n和靖山头春到了，莫因寻鹤负梅花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '尹楼岩久留华亭' AND p.poem_author = '朱南杰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('集聂游戏', '何永沂', '当代', '你是何人我是谁，早非亚子献章时。\n\n昔时朋友今时帝，万众归心吻地皮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '集聂游戏' AND p.poem_author = '何永沂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('试院次韵答吴草庐先生', '贡奎', '元代', '暂客留应喜，微官去恨迟。竹高当户直，花重向帘垂。\n\n对酒惊人别，看诗感岁移。山中足幽事，猿鹤旧曾期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '试院次韵答吴草庐先生' AND p.poem_author = '贡奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东林庵', '荣汝楫', '清代', '东林名胜夙神驰，院外僧庵庵外祠。剩有箭河环一水，更无乔木翳千枝。\n\n大儒高衲成同传，幽草闲门动远思。惆怅风流王学士，寒宵谁续咏梅诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东林庵' AND p.poem_author = '荣汝楫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感事 其三', '张洵佳', '清代', '忆从庚子肇兵端，膏血民间吸已完。白刃盟坛要约易，黄金土块铸成难。\n\n欲惩贪墨提中饱，先责清廉到上官。我本局中今局外，公鸡无膳一心安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感事 其三' AND p.poem_author = '张洵佳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山中避难作', '来鹄', '唐代', '山头烽火水边营，鬼哭人悲夜夜声。 \n 唯有碧天无一事，日还西下月还明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山中避难作' AND p.poem_author = '来鹄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采薇（二首）', '蔡羽', '明代', '采薇南山下，忽忆千里人。\n岂无临歧言，一别今几春。\n旧交容易新，新交容易亲。\n缄书重复启，曲折情难陈。\n勿陈逢彼怒，人心不逮故。\n愿言秉子德，千秋爱贞素。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采薇（二首）' AND p.poem_author = '蔡羽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('万年欢', '苏氏', '宋代', '日暖霜红，画戟门开，锦筵歌振梁尘。正是慈闱熙熙，庆诞佳辰。象服鱼轩灿烂，喜高年、福禄长新。承颜处，朱紫相将，更兼华胄诜诜。家声未论王谢，有禁中颇牧，江左机云。雁字鸳行，雍容高步金门。况有子孙侍列，拥阶庭、玉洁兰薰。持芳醑，满酌瑶觞，竞祝遐寿千春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '万年欢' AND p.poem_author = '苏氏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泛镜湖□□', '王贞白', '唐代', '我泛镜湖日，未生千里莼。时无贺宾客，谁识谪仙人。 \n 吟对四时雪，忆游三岛春。恶闻亡越事，洗耳大江滨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泛镜湖□□' AND p.poem_author = '王贞白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('左目痛六言九首', '刘克庄', '宋代', '深碧非少林祖，暴赤疑归宗僧。\n何须近青藜杖，不愿如紫石棱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '左目痛六言九首' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和菊潭玉泉韵', '施枢', '宋代', '不是灵源透碧虚，可容六六化龙鱼。\n讲经人去前湖暝，翻手为霖自有余。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和菊潭玉泉韵' AND p.poem_author = '施枢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚登保安城西望小顶山', '佟凤彩', '清代', '碧嶂青青翠色横，夕阳直射古荒城。乱峰烟锁层层秀，瀑水晴悬的的明。\n\n鸟弄余辉缘树语，樵迷幽径带云行。停骖西望饶佳致，远隔关山忆帝京。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚登保安城西望小顶山' AND p.poem_author = '佟凤彩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏郡斋壁画片云（得归字）', '岑参', '唐代', '云片何人画，尘侵粉色微。未曾行雨去，不见逐风归。 \n 只怪偏凝壁，回看欲惹衣。丹青忽借便，移向帝乡飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏郡斋壁画片云（得归字）' AND p.poem_author = '岑参';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诸家牡丹已谢小圃忽开两朵皆大如斗戏题二绝 其一', '刘克庄', '宋代', '地荒岂有雕栏护，日烈元无绣幕遮。九十种俱开谢了，末稍开到后村花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诸家牡丹已谢小圃忽开两朵皆大如斗戏题二绝 其一' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南辕杂诗一百八章 其五十四', '姚燮', '清代', '齐藩重北杏，卫隘联桃邱。纡行觅厓略，山径升崒崷。\n\n山洼匿孤县，俯见人烟稠。烟气浮上山，山云平与纠。\n\n我疑云中君，天半骖鸾游。挥云可成雨，下灌千里畴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南辕杂诗一百八章 其五十四' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题合肥驿', '王之道', '宋代', '重来岁月恍如飞，但怪芜城壁四围。千里漫推新政善，几人能遂故园归。\n\n云蒸残暑催登谷，风作新凉戒授衣。小驿滞留朋旧绝，何妨白昼掩朱扉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题合肥驿' AND p.poem_author = '王之道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('露', '弘历', '清代', '应节如垂玉，晞阳欲起烟。润馀霏晚卉，凉始到前川。\n\n莎阪愁蛩语，兰皋迟客鞭。名言思祭义，触景倍悽然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '露' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陈帐管尊公挽诗', '方岳', '宋代', '不独於书癖，论边语亦奇。\n丘园身竟老，场屋世谁知。\n客下陈蕃榻，人传窦谏碑。\n九华山翠外，烟草正离离。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陈帐管尊公挽诗' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜坐', '缪公恩', '清代', '银汉清澄白露凉，西廊月影转东廊。怀人耿耿不成寐，远雁数声秋夜长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜坐' AND p.poem_author = '缪公恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('不忧死四首 其一', '释函是', '明代', '吾病不忧死，死关大法衰。于今行古道，舍我其为谁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '不忧死四首 其一' AND p.poem_author = '释函是';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('伤心诗', '钱秉镫', '清代', '着眼空花一刻徂，苍天何意夺童乌？\n玉台已碎怀中镜，明月还沉掌上珠。\n早信灵氛逃大劫，难将因果问浮屠。\n平生儿女钟情甚，此际黄泉舐犊无？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '伤心诗' AND p.poem_author = '钱秉镫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '李师中', '宋代', '对面好峰横翠幕，绕城垂柳拂清涟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '李师中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙 寄友', '姜书阁', '当代', '记得当年三月暮，小桥携手同游，古今中外话无休。\n\n落花飞点点，流水去悠悠。\n\n转眼已如春梦杳，往事莫任淹留。别来多病又多愁！\n\n断鸿荒浦上，新月柳梢头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙 寄友' AND p.poem_author = '姜书阁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('得外子南安书作此解慰', '杨浣芬', '清代', '南天睽隔盼归鸿，沈滞音书匝月中。一纸平安深慰藉，千丝情绪暂消融。\n\n蛮方民俗难为治，乱世财源渐告穷。治谱承家宜勉力，好凭清德化顽蒙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '得外子南安书作此解慰' AND p.poem_author = '杨浣芬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归括苍和杨嗣之吏部烟雨楼韵四首', '姜特立', '宋代', '绝唱从前恨未多，骚人墨客浪经过。\n直须吏部杨夫子，始奈楼中烟雨何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归括苍和杨嗣之吏部烟雨楼韵四首' AND p.poem_author = '姜特立';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('落成会咏一首', '陈元光', '唐代', '泉潮天万里，一镇屹天中。筮宅龙钟地，承恩燕翼宫。 \n 环堂巍岳秀，带砺大江雄。轮奂云霄望，晶华日月通。 \n 凌烟乔木茂，献宝介圭崇。昆俊歌常棣，民和教即戎。 \n 盘庚迁美土，陶侃效兼庸。设醴延张老，开轩礼吕蒙。 \n 无孤南国仰，庶补圣皇功。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '落成会咏一首' AND p.poem_author = '陈元光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵邓正字慎思秋日同文馆九首 其六', '晁补之', '宋代', '忆卧蓬莱阁，同听午唱鸡。星辰望天北，簪组隔城西。\n\n几日宣鱼钥，长驱响月题。更凭催邓子，要剸玉如泥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵邓正字慎思秋日同文馆九首 其六' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别诸禅众 其二', '向宗道', '宋代', '古殿琅珰木鱼响，匆匆策马长松间。回头却恨归时早，月淡烟昏不见山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别诸禅众 其二' AND p.poem_author = '向宗道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('惟寅治第于甃石中得大禹岣嵝碑因函置壁间赋此纪事是日同观者王行父汪明生', '胡应麟', '明代', '十丈穹窿照海湄，玄圭犹忆告成时。不缘奇字中郎识，那得灵文大夏遗。\n\n雾拥蛟鼍晴挂壁，星攒科斗夜临池。他年手勒燕然碣，万古银钩对陆离。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '惟寅治第于甃石中得大禹岣嵝碑因函置壁间赋此纪事是日同观者王行父汪明生' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忠谠凝岚', '黄琏', '明代', '亭亭宝盖紫云屯，域内群山此独尊。白鹭池高天作鉴，苍龙峡静帝为门。\n\n读书台已称今古，遗俗人犹诵状元。八桂尚留风土记，忠言谠论至今存。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忠谠凝岚' AND p.poem_author = '黄琏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜宿坑口公馆母夫人喜见新月赋此', '张萱', '明代', '春霖弥月客行难，此夕停车暂倚栏。纤魄已能披宿雾，微明尚觉带馀寒。\n\n霜浮鹊彩晴犹湿，雨蚀珠胎影未完。笑唤儿孙下阶拜，慈闱今亦举头看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜宿坑口公馆母夫人喜见新月赋此' AND p.poem_author = '张萱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送陆武选文量之浙江参政', '李东阳', '明代', '天上风云拥俊豪，海边鱼鸟识旌旄。心悬紫禁千门月，气压层江百丈涛。\n\n高论有人传谏草，清时无事说兵曹。极知民社关忧乐，未放山川入醉毫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送陆武选文量之浙江参政' AND p.poem_author = '李东阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送丁指挥', '顾清', '明代', '丁将军，家习武，身好文，一生读书思致君。君门射策不得意，俛著兜鍪发如猬。\n\n男儿岂必皆明经，叔皮定远俱成名。阴山尚有强梁客，听我秋弓霹雳声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送丁指挥' AND p.poem_author = '顾清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('入山谒怡然上人因成短篇皆书即时事', '强至', '宋代', '行穿六松阴，鸟语逢人寂。\n林僧洗山缽，正了寒堂食。\n揖我喜满颜，吟窗半轩辟。\n凤凰不无情，天外送佳色。\n春风动花雨，枝上或涓滴。\n羡师得安住，我亦有闲适。\n出门懒鞍马，把袂步幽石。\n石尽浮泥深，恰恰露双屐。\n临别心徘徊，野店更一息。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '入山谒怡然上人因成短篇皆书即时事' AND p.poem_author = '强至';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读史 其七', '孔祥淑', '清代', '画虎状狰狞，遥望犹悚惧。况在小儿女，何敢与之遇。\n\n父为虎所曳，杨香赫然怒。奋臂不顾身，搏虎如搏兔。\n\n扼颈虽靡牙，俯伏驰若鹜。笑彼逐虎者，色变失故步。\n\n善撄如冯妇，负嵎犹四顾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读史 其七' AND p.poem_author = '孔祥淑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南歌子 其十', '程滨', '当代', '一向心如水，新来臆渐怦。关雎之乱绕秦筝。对面两相无语目成情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南歌子 其十' AND p.poem_author = '程滨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头·天宇正高爽', '吴潜', '宋代', '天宇正高爽，更蹑最高楼。长风为我驱驾，极目海山头。不用牛山孟浩，不用齐山杜牧，人景自堪酬。举酒酹空阔，汗漫与为游。 \n 捻黄花，怜白首，恨难收。颓龄使汝能制，何待更封留。眼底朱甍画栋，往往人非物是，蟋蟀自鸣秋。万里一搔首，无处著萧飕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头·天宇正高爽' AND p.poem_author = '吴潜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同姬人饮酒竟日得诗五章 其四', '姚燮', '清代', '高风自栗烈，挹之吾知和。沄沄玉镜光，摇动春江波。\n\n开窗放天影，莹若新濯罗。澄想有馀隽，写以低声哦。\n\n两心各夷惠，爱正情无阿。酒尽不识醉，宁复思其他。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同姬人饮酒竟日得诗五章 其四' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑子', '晏殊', '宋代', '红英一树春来早，独占芳时。我有心期。把酒攀条惜绛蕤。 \n 无端一夜狂风雨，暗落繁枝。蝶怨莺悲。满眼春愁说向谁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑子' AND p.poem_author = '晏殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题孟浩然霜晓吟行图', '戴表元', '宋代', '霜风飒飒搅吟鞍，童怖驴愁作许难。\n便使玉堂遭遇去，朝参更是五更寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题孟浩然霜晓吟行图' AND p.poem_author = '戴表元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游仙窟诗 别文成', '崔五嫂', '唐代', '此时经一去，谁知隔几年。双凫伤别绪，独鹤惨离弦。\n\n怨起移酲后，愁生落醉前。若使人心密，莫惜马蹄穿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游仙窟诗 别文成' AND p.poem_author = '崔五嫂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('览秀亭诗', '范仲淹', '宋代', '南阳有绝胜，城下百花洲。\n谢公创危亭，屹在高城头。\n尽览洲中秀，历历销人忧。\n作诗刻金石，意垂千载休。\n我来亭早坏，何以待英游。\n试观荆棘繁，欲步瓦砾稠。\n嗟嗟命良工，美材肆尔求。\n曰基复曰搆，落成会中秋。\n开樽揖明月，席上皆应刘。\n敏速迭唱和，醺酣争献酬。\n老子素不浅，预兹年少俦。\n九日重登临，凉空氛气收。\n风来雁声度，云去山色留。\n西郊有潭菊，满以金船浮。\n雅为郡子寿，外物真悠悠。\n过则与春期，春时良更优。\n焰焰众卉明，衮衮新泉流。\n箫鼓动地喧，罗绮倾城游。\n五马不行乐，州人为之羞。\n亭焉讵可废，愿此多贤侯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '览秀亭诗' AND p.poem_author = '范仲淹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗四首 其三', '王之望', '宋代', '龟肉不可食，蟹螯不中卜。龟以壳自戕，蟹以味见戮。\n\n所养殊毅豹，所亡等臧谷。一足致患害，内外皆鸩毒。\n\n嵇康坐才死，霍禹以势族。乐哉蟹螯中，贮此老龟肉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗四首 其三' AND p.poem_author = '王之望';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('媒问嫠', '胡次焱', '宋代', '媒问嫠，汝何伤。汝为闺秀时，辛苦事蚕桑。僩瑟顺为正，婉娩礼自将。\n\n笥中有练裙，衣上无明珰。贫女古难嫁，卖犬办资装。\n\n中年得夫婿，憧憧拜姑嫜。肃容采蘋藻，洗手供羹汤。\n\n良人正少年，相期家道昌。良缘天所妒，夫婿奄云亡。\n\n自从夫婿亡，十年守空房。素帷代锦帱，苫席易牙床。\n\n孤眠耿夜半，单立黯昏黄。茕茕影徘徊，鞅鞅情彷徨。\n\n皓月照枕衾，暴雨颓垣墙。独寤谁呼唤，独语谁交相。\n\n如凌空失翼，如涉川无梁。嫠来吾语汝，琴瑟贵更张。\n\n汝箧既单薄，汝门复凄凉。汝寒何以衣，汝饥何以粮。\n\n纺绩终难给，舂汲劳欲僵。死者不复起，生者宜自详。\n\n邻有美丈夫，颙颙更昂昂。牛羊量用谷，金玉堆满堂。\n\n画梁青琐闼，珠帘毹氍厢。雕户金弹丸，宝鞍青丝缰。\n\n旌旗明晚霞，剑戟磨秋霜。奴隶厌绮纨，犬猫弃餦餭。\n\n门下粲珠履，庭前沸笙簧。出则专城居，入则侍明光。\n\n一呼千夫诺，一指万夫张。一笑生羽翼，一怒起锋芒。\n\n吾慕昔蹇修，与汝解佩纕。以此窈窕妇，配彼组绘郎。\n\n花树戏蛱蝶，莲浦浴鸳鸯。无烦赋藕花，且喜华枯杨。\n\n何妨鸾舞镜，应彼凤求凰。人无百岁人，倏忽如风狂。\n\n莫将泡影身，徒置冰炭场。死后留名节，身朽魂茫茫。\n\n生前受富贵，志得意洋洋。人生行乐尔，二者试裁量。\n\n蔬食不日给，孰与饫膏粱。荆钗不自谋，孰与云霞裳。\n\n年滔滔不反，貌骎骎已苍。败棋须换局，作戏且逢场。\n\n文君慕相如，恢女唤江郎。有发可重结，有耳何自戕。\n\n试问东夷子，何如声伯娘。信书不如无，未必有共姜。\n\n鬼妻变人妇，毋作老死孀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '媒问嫠' AND p.poem_author = '胡次焱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄严文炳', '陈造', '宋代', '赵侯当赐环，倔强耻媚灶。\n张侯鸣琴手，戍期几时到。\n何郎偕贤书，论价未足道。\n多烦问何如，好语君一报。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄严文炳' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送吕霞卿吕当世弃官而出家今为道士', '周紫芝', '宋代', '得钱梦秽官梦尸，等为臭腐焉用为。世人爱官如爱命，君独弃官如弃泥。\n\n道人胸中少荆棘，一色但种枣与梨。华名自毁不足取，高位疾颠无乃危。\n\n鱼须忽复入君手，三命循墙急须走。朝持玉磬诵琅函，夜着黄冠朝北斗。\n\n天上云车久未来，壶中日月空长久。吴山楚泽两西东，与子一笑殊匆匆。\n\n会当握手五百载，摩挲金狄还相逢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送吕霞卿吕当世弃官而出家今为道士' AND p.poem_author = '周紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('追和汪先生腊梅', '傅子馀', '近代', '一缕幽香纸上传，故家风味久茫然。日烘霜染知何世，玉质金裳已自仙。\n\n犹记得名双井后，不曾呵手六宫前。先生最是多情者，倚笔危栏欲雪天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '追和汪先生腊梅' AND p.poem_author = '傅子馀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金莲出玉华', '王丹桂', '元代', '罗庄一境。曲水环山相掩映。地秀人贤。慕道崇真种善缘。邀予至此。供养殷勤心不止。报德无方。惟愿家家福寿昌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金莲出玉华' AND p.poem_author = '王丹桂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和中甫吕氏园亭', '沈遘', '宋代', '长日阴阴雨与风，病夫高卧一舟中。少年欢气谁能遏，纵走名园看落红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和中甫吕氏园亭' AND p.poem_author = '沈遘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠孙广伯', '吕本中', '宋代', '人皆笑君拙，我独喜君直。拙则世所无，直则未易识。\n\n昔者中丞公，事主以一德。从容进退间，多士所取则。\n\n朝廷九鼎重，冠冕万夫特。尘埃困大路，此老难再得。\n\n至今门下士，必以身许国。孰知强弩末，而有百钧力。\n\n贤孙后来秀，见我好颜色。收功却扫中，欲任门内责。\n\n空弮入善阵，匹马见勍敌。不嫌不识察，但恨无此获。\n\n欲赤莫如丹，欲黑莫如墨。吾常持此言，以辨主与贼。\n\n苟无牛羊害，则有天地塞。君能但拙直，亦莫忘黑白。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠孙广伯' AND p.poem_author = '吕本中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卓女怨', '卢仝', '唐代', '妾本怀春女，春愁不自任。迷魂随凤客，娇思入琴心。 \n 托援交情重，当垆酌意深。谁家有夫婿，作赋得黄金。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卓女怨' AND p.poem_author = '卢仝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('何叔京挽章二首', '吕祖谦', '宋代', '倾盖黄亭夜，翛然涧壑姿。\n倚天唯直干，到地绝旁枝。\n亹亹今何许，悠悠只自知。\n寒碑卧风雨，千载有深期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '何叔京挽章二首' AND p.poem_author = '吕祖谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又和早行', '范纯仁', '宋代', '拂曙征人各向方，乍明林野更青苍。云头漏日开秋色，马足翻沙破晓霜。\n\n时事罕闻心愈静，故人不见恨空长。怜君素爱还乡乐，行役虽劳肯暂忘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又和早行' AND p.poem_author = '范纯仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('会昌劝农', '曾丰', '宋代', '官不劝农农亦耕，诏书那可废常行。\n烟霞自避旌旗色，鱼鸟相疑金鼓声。\n蝶急岂遑追梦觉，鸠闲犹强管阴晴。\n忙中偷得须臾暇，聊借江山答太平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '会昌劝农' AND p.poem_author = '曾丰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送二子从子宜读书', '刘翼', '宋代', '三代读书无寸功，又将此法教儿童。\n旁人笑我背时好，不背旁人背乐翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送二子从子宜读书' AND p.poem_author = '刘翼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自讼', '薛季宣', '宋代', '学问非干禄，宦游端为贫。生惭挽船令，羞杀采芝人。\n\n求牧知平陆，无浆卖棘津。读书心愧否，何日是来春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自讼' AND p.poem_author = '薛季宣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读同学吴稚晖欧战意见书有感二首 其一', '龚锡圭', '近代', '西风杀气遒，暝色满高楼。狮梦先惊破，鱼书入望愁。\n\n雄心争霸业，壮志瞰全欧。一别相思苦，东西隔二洲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读同学吴稚晖欧战意见书有感二首 其一' AND p.poem_author = '龚锡圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('明道元年章献明肃皇太后朝会十五首', '佚名', '隋代', '礼均孝慈，乐合韶武。\n至德光矣，鸿恩亦溥。\n上下和济，华夷乐湑。\n栈斝在行，盛停斯举。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '明道元年章献明肃皇太后朝会十五首' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元旦早朝', '孙勋', '明代', '绛阙双瞻碧玉空，衮衣遥拜紫宸宫。瑞光总映千门曙，淑气同看万国丰。\n\n禁柳厚笼仙掌露，炉烟轻散御帘风。幸随簪笏称华祝，忽睹云车驾六龙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元旦早朝' AND p.poem_author = '孙勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观张功父南湖海棠杖藜走笔三首 其三', '杨万里', '宋代', '天工信手洒明霞，若遣停匀未必佳。却得数株多叶底，殷勤衬出密边花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观张功父南湖海棠杖藜走笔三首 其三' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登渭桥诗', '宗羁', '南北朝', '仲山朝饮马，还坐渭桥中。南瞻临别馆，北望尽离宫。\n\n四面衣裾合，三条冠盖通。兰香想和季，云起忆成公。\n\n圯上相知早，鸡鸣幸共同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登渭桥诗' AND p.poem_author = '宗羁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春帖子词·皇后阁十首', '宋祁', '宋代', '谁道春从何处来，只从金阙遍瑶台。\n苍龙便入时巡仗，玉液还飞行庆杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春帖子词·皇后阁十首' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史三十一首 其十七', '黄毓祺', '清代', '珍重侍中血，溅衣勿浣也。孝惠且知之，何况进此者。\n\n今人多泰准，七尺肯轻舍。安危难可期，所恃有佳马。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史三十一首 其十七' AND p.poem_author = '黄毓祺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('代寿诗得韭字', '徐庸', '明代', '邵伯甘棠世稀有，侯寔雪仍继其后。一官不忝旧声华，百里今称贤父母。\n\n治民民乐去苛政，恺悌从容德弥厚。平生忠悃萃诸心，到处歌谣出于口。\n\n芳春此日遇生申，玳瑁筵开会僚友。东风吹影动炉香，南极分光照杯酒。\n\n松椿祝寿拟无算，竹帛垂名期不朽。他时黼黻上虞廷，康宁为服尧时韭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '代寿诗得韭字' AND p.poem_author = '徐庸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏梅次韵二首 其二', '张孝祥', '宋代', '天与孤标不受尘，生憎桃李斗芳新。诗成名下无虚士，花在身边当丽人。\n\n只恐素英欺白发，试烦纤手插乌巾。风流今代神仙尉，管得河阳县里春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏梅次韵二首 其二' AND p.poem_author = '张孝祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('剪彩', '张九龄', '唐代', '姹女矜容色，为花不让春。既争芳意早，谁待物华真。 \n 叶作参差发，枝从点缀新。自然无限态，长在艳阳晨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '剪彩' AND p.poem_author = '张九龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人·宝檀金缕鸳鸯枕', '毛文锡', '唐代', '宝檀金缕鸳鸯枕，绶带盘官锦。夕阳低映小窗明，南园绿树语莺莺，梦难成。\n玉炉香暖频添炷，满地飘轻絮。珠帘不卷度沉烟，庭前闲立画秋千，艳阳天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人·宝檀金缕鸳鸯枕' AND p.poem_author = '毛文锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('期陈明府子野晚过', '欧大任', '明代', '君岂陈惊座，邀欢满汉都。懒朝仍傲吏，纵饮亦吾徒。\n\n夕苑千花暗，春沟片月孤。糟床堪一斗，乘兴肯来无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '期陈明府子野晚过' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭伯先 其二', '柳亚子', '清代', '寻常巷陌奈君何，忍唱尊前青兕歌。海岛田横心自壮，天门陶侃翼空摩。\n\n千秋北府兵无敌，一水南徐夜有波。何日黄龙奠杯酒，髑髅饮器发横拖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭伯先 其二' AND p.poem_author = '柳亚子';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('严陵独钓', '王立道', '明代', '汉持太阿授新室，炎光黯然光欲灭。风尘倾洞天地昏，猰㺄竞食苍氓血。\n\n猗与光武起舂陵，司隶威仪耆老泣。昆阳一鼓虎豹奔，罔魑解首欃枪匿。\n\n虹霓扫除日月开，赤精复吐山川色。君臣会遇良有机，乾坤整顿无倒倾。\n\n先生兀然独坐钓，羊裘蒙茸对空泽。亦知天子即故人，不与四海俱臣妾。\n\n翩翩长揖还富春，狂奴不住公卿列。江流夜转鼋鼍寒，山气暝连风雨白。\n\n吁嗟贤士各有志，相助岂必能相屈。古来节义何代无，西京诸子今犹烈。\n\n九鼎宁论汉家重，一丝何止千钧力。画图彷佛清风生，尽濯贪颜洗顽骨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '严陵独钓' AND p.poem_author = '王立道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江上二首 其二', '张耒', '宋代', '纷纷浑是梦，黯黯只消魂。江上浪无限，舟中酒一樽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江上二首 其二' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵黄秀才秋兴（二首）', '滕毅', '明代', '虎战龙争二十秋，江波日夜自东流。\n道傍无语王孙泣，天际含颦帝子愁。\n苜蓿风烟空壁垒，蒹葭霜露满汀洲。\n古来惟有西山月，永夜依依照白头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵黄秀才秋兴（二首）' AND p.poem_author = '滕毅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游罗浮至冲虚观万象森然真洞天境界', '吴琏', '明代', '四百耸耸峰插天，一观万树青苍连。白头道士对棋局，碧眼小童鸣管弦。\n\n丹灶古泥浮紫气，修篁符叶霭苍烟。仙禽似有相留意，啼伴山房几觉眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游罗浮至冲虚观万象森然真洞天境界' AND p.poem_author = '吴琏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题巨商壁', '靓禅师', '宋代', '去年巢穴书梁边，春暖双双绕槛前。\n莫讶主人帘不卷，恐术泥土污花砖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题巨商壁' AND p.poem_author = '靓禅师';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀长卿 其一', '邹浩', '宋代', '香醅新拨一尊浓，准拟君来笑语同。缘底留连过初约，凭栏日日望归蓬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀长卿 其一' AND p.poem_author = '邹浩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('腊日宣诏幸上苑 / 催花诗', '武则天', '唐代', '明朝游上苑，火速报春知。\n花须连夜发，莫待晓风吹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '腊日宣诏幸上苑 / 催花诗' AND p.poem_author = '武则天';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('画工李友直为余作冰天桂海二图，冰天画使', '范成大', '宋代', '许国无功浪著鞭，天教饱识汉山川。\n酒边蛮舞花低帽，梦里胡笳雪没鞯。\n收拾桑榆身老矣，追随萍梗意茫然。\n明朝重上归田奏，更放岷江万里船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '画工李友直为余作冰天桂海二图，冰天画使' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('堂上歌行', '高启', '明代', '堂上歌，歌南山，主人为欢仰客颜。\n翠帷夜卷出两鬟，移尊更饮花树间。\n花树间，有明月。\n客不醉，歌不歇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '堂上歌行' AND p.poem_author = '高启';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古一百二十一首 其四十', '释宗杲', '宋代', '出门握手话分携，古路迢迢去莫追。却笑波心遗剑者，区区空记刻舟时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古一百二十一首 其四十' AND p.poem_author = '释宗杲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与郑少融、赵养民二使者访古訾家洲，归憩松', '范成大', '宋代', '飘飘竹雨润轻裘，嫋嫋松风系小舟。\n安得从容兴废手，越人重上訾家洲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与郑少融、赵养民二使者访古訾家洲，归憩松' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('访客舟中', '陈宪章', '明代', '船中酒多少，船尾阁春沙。\n恰到溪穷处，山山枳壳花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '访客舟中' AND p.poem_author = '陈宪章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陈光禄惟顺迎暾书舍四首 其二 寺钟', '陆深', '明代', '蒲牢吼萧寺，明星出东方。动息各有会，随风远飘飏。\n\n唤起巫山梦，缥缈赋高堂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陈光禄惟顺迎暾书舍四首 其二 寺钟' AND p.poem_author = '陆深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题石室藏书图', '刘文如', '清代', '开匣拜遗容，凄然心暗伤。未及见慈亲，惟见图卷长。\n\n夫子秉遗教，显亲早名扬。当年课夜读，教以古文章。\n\n治家似钟郝，半典嫁时裳。聚得千卷书，训以石室藏。\n\n夫子成德器，终天忆北堂。四祭陈五鼎，举爵每徬徨。\n\n哀哉寸草心，难报春晖光。于今选楼上，即是古墨庄。\n\n圣恩酬母德，更图一品妆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题石室藏书图' AND p.poem_author = '刘文如';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题壁 其三', '和庵主', '宋代', '黄皮裹骨一常僧，坏衲蒙头百虑澄。年老懒能频对客，攀萝又上一崚嶒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题壁 其三' AND p.poem_author = '和庵主';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵惜范生', '黄庭坚', '宋代', '范侯躯干小，实有四海心。\n稍臞疑内热，不怒见勇沉。\n沽玉市无价，汲泉井方深。\n得失有毫末，明年斧可寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵惜范生' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('焦山', '徐渭', '明代', '徵君祠庙碧山隈，僧舍中流面面开。全楚客帆遮浦下，广陵涛色漫窗来。\n\n曝鼋何事当牛触，养鹤翻劳刻石埋。隔取深泥题不得，空持黄绢立磨厓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '焦山' AND p.poem_author = '徐渭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江城子 其四 之子于归', '蔡淑萍', '当代', '夕阳轻笼小山村，挂鞭鸣，报佳音。东邻嫁女，贵客早扎亲。\n\n坐罢歌堂看电影，新风蔚，古风存。\n\n红日鸡声催出亲。父叮咛，母叮咛。含羞带笑，却又泪光莹。\n\n路转山回人不见，听宛转，唢呐声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江城子 其四 之子于归' AND p.poem_author = '蔡淑萍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七月二十八日蒲大受仲明举偶来会宿三首 其二', '郭印', '宋代', '少城能款曲，敝馆辱留连。未搅秋风思，还同夜雨眠。\n\n烟尘惊绝塞，草木验流年。斗酒君须醉，新诗看百篇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七月二十八日蒲大受仲明举偶来会宿三首 其二' AND p.poem_author = '郭印';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋霁（西湖十咏·平湖秋月）', '陈允平', '宋代', '千顷玻璃，远送目斜阳，渐下林阗。题叶人归，采菱舟散，望中水天一色。碾空桂魄。玉绳低转云无迹。有素鸥，闲伴夜深，呼棹过环碧。 \n 相思万里，顿隔婵媛，几回琼台，同驻鸾翼。对西风、凭谁问取，人间那得有今夕。应笑广寒宫殿窄。露冷烟淡，还看数点残星，两行新雁，倚楼横笛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋霁（西湖十咏·平湖秋月）' AND p.poem_author = '陈允平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元日晏起书怀', '谢榛', '明代', '轮蹄遍九陌，此日独高眠。疏懒终何事，飘零又长年。\n\n地寒疑腊在，窗午觉春偏。短杖閒中侣，浮云醉里天。\n\n昨孤儿女望，今复岁时迁。起坐看明镜，苍苍鬓飒然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元日晏起书怀' AND p.poem_author = '谢榛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋同儿侄登宝峰亭', '王之望', '宋代', '绝顶凭栏思有余，沧江下眺眇三隅。\n月光此夜十分满，风色今朝一点无。\n乡国不须悲楚蜀，庭阶且喜集封胡。\n史君邂逅分鲜鲫，斫脍还成逸少图。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋同儿侄登宝峰亭' AND p.poem_author = '王之望';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日感怀', '孔武仲', '宋代', '万山松色锁蝉呜，日透林阴上下清。\n霜压蒹葭连地白，风吹河汉满天声。\n穹庐夜动阴山虏，玉甲朝屯紫塞兵。\n愿漱单于一杯血，心随鵰鹗过长城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日感怀' AND p.poem_author = '孔武仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂德上贾常侍', '贾岛', '唐代', '边臣说使朝天子，发语轰然激夏雷。高节羽书期独传， \n 分符绛郡滞长材。啁啾鸟恐鹰鹯起，流散人归父母来。 \n 自顾此身无所立，恭谈祖德朵颐开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂德上贾常侍' AND p.poem_author = '贾岛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和陈及之 其五', '孙应时', '宋代', '吾非斯人谁与群，覆手翻手知交情。天南海北有离合，此生此意无寒盟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和陈及之 其五' AND p.poem_author = '孙应时';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻谭长公之官宜山暴卒于苍梧作此志恨', '庞尚鹏', '明代', '梦断宜山路，轻车叹陆沉。梧门秋日暗，竹马白云深。\n\n风雨孤臣泪，乾坤万里心。独馀龙剑在，凝涕倍沾襟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻谭长公之官宜山暴卒于苍梧作此志恨' AND p.poem_author = '庞尚鹏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('呈蔡元德二首', '王之道', '宋代', '别来閒计日，一日似三秋。\n顾我无能老，逢君始欲愁。\n诗情今转胜，交契久还稠。\n学问神龟似，当年继践猷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '呈蔡元德二首' AND p.poem_author = '王之道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感事述怀，集杜二十首 其十', '陈肇兴', '清代', '苦负平生志，经书满腹中。与时安反侧，驾驭必英雄。\n\n天下兵皆满，关河信不通。烟尘独长望，愁坐正书空。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感事述怀，集杜二十首 其十' AND p.poem_author = '陈肇兴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('招社友游梅陇', '郑岳', '明代', '梅陇昔年曾枉驾，山川草木倍光辉。里祠临水增新构，石径移墙辟旧闱。\n\n共喜筋骸犹健浪，况堪时节正芳菲。木兰倚棹须乘兴，汛扫茆堂望翠微。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '招社友游梅陇' AND p.poem_author = '郑岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古一百二十一首', '释宗杲', '宋代', '瑟瑟风松，萧萧雨桧。\n师子咬人，韩{左犭右卢}逐瑰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古一百二十一首' AND p.poem_author = '释宗杲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('涂山', '郑善夫', '明代', '浲水东行沧海回，衣冠玉帛万方来。后期独有防风氏，君看涂山戮将台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '涂山' AND p.poem_author = '郑善夫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏茶十二韵', '齐己', '唐代', '百草让为灵，功先百草成。甘传天下口，贵占火前名。 \n 出处春无雁，收时谷有莺。封题从泽国，贡献入秦京。 \n 嗅觉精新极，尝知骨自轻。研通天柱响，摘绕蜀山明。 \n 赋客秋吟起，禅师昼卧惊。角开香满室，炉动绿凝铛。 \n 晚忆凉泉对，闲思异果平。松黄干旋泛，云母滑随倾。 \n 颇贵高人寄，尤宜别匮盛。曾寻修事法，妙尽陆先生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏茶十二韵' AND p.poem_author = '齐己';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和符倅上范相喜雨', '卷刚中', '宋代', '圣诏谦慈类禹汤，云台得蹇破骄阳。\n三秋正此忧焦窘，万室今咸共喜康。\n袁扇风清端有助，庾莲水渌但知凉。\n东都岂是留裴地，公亦相从早趣装。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和符倅上范相喜雨' AND p.poem_author = '卷刚中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('方处士挽诗二首 其二', '戴表元', '宋代', '不比他人死，何诗可挽君。渊明元懒仕，东野别攻文。\n\n沧海诸公泪，青山处士坟。相看莫浪哭，私谥有前闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '方处士挽诗二首 其二' AND p.poem_author = '戴表元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄陈独秀狱中', '吴虞', '近代', '早年谈易记儒生，意气翻惊四海横。党锢固应关国计，罪言犹足见神明。\n\n尽知大胆如王雅，何必高文似马卿。万古江河真不废，新书还望狱中成。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄陈独秀狱中' AND p.poem_author = '吴虞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荔枝五首 其四', '李纲', '宋代', '荔子蛮方也自丹，不如闽岭为微酸。玉盘磊珂三千颗，犹忆甘芳绕齿寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荔枝五首 其四' AND p.poem_author = '李纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汉宫春', '何中', '元代', '君不见汉宫六六多佳丽，露花半染云裾翠。少翁招得夫人魂，孤鸾夜啼月波坠。\n\n赵家姊妹专风流，双蛾不识人生愁。芙蓉并蒂敧一朵，西风青鸟徒离忧。\n\n飞龙翩翩上天去，云幕椒房土花雨。堕腻埋胭恨未消，香魂尚寄寒茎舞。\n\n人间炎日焦众芳，肯随葵藿来倾阳。柔情幽怨透地脉，烟帏寂寞彊成妆。\n\n谁吹旧曲缘云切，寸寸婉婉应愁绝。绿罗几叠御赐衣，红绡半点守宫血。\n\n凄兮媚脸栖馀妍，遥忆羊车望幸年。至今一片巫山雨，化为飞烟空潸然。\n\n故家陵苑孤云外，绿树如云草如海。殷勤唯有虞美人，同向墙阴弄晴霭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汉宫春' AND p.poem_author = '何中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('维则庵追凉题月湖屏间诗后', '史弥宁', '宋代', '淋淳醉墨洒屏间，逃暑祗园闯一斑。\n小阮诗怀饱丘壑，可无只句饷江山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '维则庵追凉题月湖屏间诗后' AND p.poem_author = '史弥宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小饮即事呈申伯', '李纲', '宋代', '夜凉同咏古人诗，新月娟娟照酒卮。一醉且忻军寇退，扁舟似与菊花期。\n\n衔杯乐圣真吾事，泛宅浮家漫尔为。归去云山最深处，隔江千里幸相思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小饮即事呈申伯' AND p.poem_author = '李纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早归', '李覯', '宋代', '病马不妨骑，出门常便归。\n见人无事说，是物与心违。\n通塞元关命，驱驰转觉非。\n莫教尘里汗，坏却箧中衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早归' AND p.poem_author = '李覯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诸友饮怡老园分韵得春字', '王鏊', '明代', '题诗昨日送残春，桃李阴阴入夏新。风动渐惊红落莫，雨馀犹爱碧嶙峋。\n\n敢期事业同夔卨，且可壶觞引白申。独有江湖忧未歇，北来消息苦难真。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诸友饮怡老园分韵得春字' AND p.poem_author = '王鏊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天宫', '白居易', '唐代', '洛城秋霁后，梵阁暮登时。此日风烟好，今秋节候迟。\n\n霞光红泛艳，树影碧参差。莫虑言归晚，牛家有宿期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天宫' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('龙翔寺赠缝人 其二', '梁寅', '元代', '山客麻衣岁月多，朔风吹裂奈愁何。若为访我清江上，倩子云中制芰荷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '龙翔寺赠缝人 其二' AND p.poem_author = '梁寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('邵氏园亭', '于石', '宋代', '曲曲亭台日月春，人间荣辱两无闻。梅边读易分明月，松下敲棋碎白云。\n\n东里先生新酿酒，北山逋客旧移文。家传应得青门趣，手种园瓜手自耘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '邵氏园亭' AND p.poem_author = '于石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄家闸南数里地旷多盗丁卯北行阁浅三宿是日风帆迅疾家童指示其处为之怃然', '顾清', '明代', '此地曾三宿，重来尚眼明。寒泉高岸下，还似昔时清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄家闸南数里地旷多盗丁卯北行阁浅三宿是日风帆迅疾家童指示其处为之怃然' AND p.poem_author = '顾清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('如梦令', '徐灿', '清代', '杨柳丝丝青纵。烟护晶帘无缝。不信玉阑干，偏得月华珍重。\n\n如梦。如梦，梦到江南春仲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '如梦令' AND p.poem_author = '徐灿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长亭怨慢·和忍盦春尽书怀之作，即题春蛰吟后', '吴昌绶', '清代', '漫回首、东华尘土。采笔零星，赋秋如许。病酒寒欺，梦中呜咽向春语。\n\n蝶昏莺晓，僝僽损，风和雨。苑柳不成眠，却化作、天涯飞絮。\n\n迟暮。恨芬菲世界，刬地乱红无数。分香瘦减，问谁遣、欢盟轻误。\n\n凝望眼、绣幕深深，想依旧、玉京眉妩。待诉与相思，弹入钿筝哀柱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长亭怨慢·和忍盦春尽书怀之作，即题春蛰吟后' AND p.poem_author = '吴昌绶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郡檄子肃检视旱田以诗寄之', '赵蕃', '宋代', '是邦且熟无多收，况于水旱相为忧。\n使君奏课避非实，檄公按视临田畴。\n民闻公来相告语，活国忧民公自许。\n平时爱我如恐伤，今胡不能为轻赋。\n人生衣食固有端，作苦宁敢求自安。\n分当戮力给公上，何意年岁逢艰难。\n吾君德盛过文景，诏书屡下民惟省。\n公其为我谢使君，考虽下下民安枕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郡檄子肃检视旱田以诗寄之' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿史刑使', '赵汝腾', '宋代', '岷峨储英贤，一例皆家食。\n公亦淹海角，麾节犹赫奕，\n七闽政多幸，福星照南极。\n轻裘镇铃阁，使斧光卫戟。\n门弧初度临，和气遍阡陌。\n宿雨洗瘴氛，朔云报寒色。\n前期为重九，后期为至日。\n中间产蜀珍，天意扶阳脉。\n原言爱刚健，他日寿王国。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿史刑使' AND p.poem_author = '赵汝腾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南禅师圆寂日偈二首 其一', '释祖心', '宋代', '去年三月十有七，一夜春风撼筹室。三角麒麟入海中，空馀片月波心出。\n\n真不掩伪，曲不藏直。谁人为和雪中吟，万古知音是今日。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南禅师圆寂日偈二首 其一' AND p.poem_author = '释祖心';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次致明泉石轩诗韵', '刘子翚', '宋代', '天怀迥与尘器背，蓬莱屡踏金鳌背。\n闲披白袷过清湖，爽气涵空渺无外。\n澹然爱此一泓奇，散发逍遥漱华滋。\n尚嫌林影太凋薄，斜阳射破碧琉璃。\n遥知宣室虚前席，良裘固非一狐腋。\n他时归梦想南飞，环词已为磨崖石。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次致明泉石轩诗韵' AND p.poem_author = '刘子翚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋日泛泖因读先师莫中江之什忽又十五年感旧怀贤再赋呈唐明府君公 其一', '董其昌', '明代', '秋风牛渚不堪过，回首游踪感怆多。名手自传裙练在，壮心其柰佩刀何。\n\n广陵无复闻流水，华表空知怨逝波。稍解当年招隐意，湖天渺渺一渔蓑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋日泛泖因读先师莫中江之什忽又十五年感旧怀贤再赋呈唐明府君公 其一' AND p.poem_author = '董其昌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴开府', '岳珂', '宋代', '豫章之东湖，有公之居。西山荐图，咮凤滴蜍。伊波之馀，而无以昌其书。\n\n呜呼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴开府' AND p.poem_author = '岳珂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九日自台南至打狗作 其一', '林朝崧', '清代', '台南南去蔗园青，此路平生尚未经。聊把新诗记鸿爪，不关水秀与山明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九日自台南至打狗作 其一' AND p.poem_author = '林朝崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿村舍', '杜荀鹤', '唐代', '野人于我有何情，半掩柴门向月明。 \n 深夜欲眠眠未著，一丛寒木一猿声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿村舍' AND p.poem_author = '杜荀鹤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答及甫见和二首', '洪咨夔', '宋代', '我爱湖南客，从横正复奇。\n短裳甘制芰，破斧懒燃萁。\n愤世惟堪饮，忧边不到诗。\n最怜孤寂甚，欲为唤罗龟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答及甫见和二首' AND p.poem_author = '洪咨夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·丁卯上元。用东坡密州上元原调并韵。东坡此词不胜今昔之感，予之所感，重足哀者', '魏元戴', '清代', '宝炬华灯城不夜。手板天街，不用严安画。光满银蟾香散麝。\n\n骄嘶倦控深宵马。\n\n旧事蓬莱如梦也。收泣新亭，中酒逃莲社。袖手祈年灯影下。\n\n东风拂面来平野。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·丁卯上元。用东坡密州上元原调并韵。东坡此词不胜今昔之感，予之所感，重足哀者' AND p.poem_author = '魏元戴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题炖煌太守裴岑纪功碑拓本', '杨炳春', '清代', '提兵三千人，立功万里外。裴公信桓桓，与汉除灾害。\n\n嗟哉窃禄徒，养尊幸时泰。履常恣欺谩，蹈险丧狡狯。\n\n国仇仓卒逢，未战先狼狈。微躯不如草，荀活向敌丐。\n\n古人不畏死，所以功名大。古人傥畏死，姓氏久尘壒。\n\n我读裴公碑，英风想旌旆。裴公不复生，呼酒为公酹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题炖煌太守裴岑纪功碑拓本' AND p.poem_author = '杨炳春';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西江月（和张文伯腊日席上）', '王之道', '宋代', '北陆藏冰欲竟，东风解冻非遥。一时芳意巧相撩。入眼绿娇红小。 \n 柳色轻摇弱线，梅英纷缀枯梢。觥筹醉里赖君饶。归去斜阳尚早。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西江月（和张文伯腊日席上）' AND p.poem_author = '王之道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读三国志', '薛季宣', '宋代', '左角蛮攻触，南柯檀伐槐。徘谐记名字，人物委尘埃。\n\n锦里昔曾到，樊川今此来。遗风不可见，观古意悠哉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读三国志' AND p.poem_author = '薛季宣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自戏三绝句。心重答身', '白居易', '唐代', '因我疏慵休罢早，遣君安乐岁时多。 \n 世间老苦人何限，不放君闲奈我何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自戏三绝句。心重答身' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九张机', '南宋无名', '宋代', '一张机，采桑陌上试春衣。风晴日暖慵无力，桃花枝上，啼莺言语，不肯放人归。\n\n两张机，行人立马意迟迟。深心未忍轻分付，回头一笑，花间归去，只恐被花知。\n\n三张机，吴蚕已老燕雏飞。东风宴罢长洲苑，轻绡催趁，馆娃宫女，要换舞时衣。\n\n四张机，咿哑声里暗颦眉。回梭织朵垂莲子，盘花易绾，愁心难整，脉脉乱如丝。\n\n五张机，横纹织就沈郎诗。中心一句无人会，不言愁恨，不言憔悴，只恁寄相思。\n\n六张机。行行都是耍花儿。花间更有双蝴蝶，停梭一晌，闲窗影里。\n\n独自看多时。七张机，鸳鸯织就又迟疑。只恐被人轻裁剪，分飞两处，一场离恨，何计再相随？\n\n八张机。回纹知是阿谁诗。织成一片凄凉意。行行读遍，厌厌无语，不忍更寻思。\n\n九张机，双花双叶又双枝。薄情自古多离别，从头到底，将心萦系，穿过一条丝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九张机' AND p.poem_author = '南宋无名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登杓江楼感事 其七', '朱青长', '清代', '药谱茶经共一囊，寂无人处自添香。楚辞系肘寻山鬼，巴舞弓腰媚竹王。\n\n国事已成三变局，乾坤还可一挥觞。金沙水浅鱼龙细，不用移文责夜郎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登杓江楼感事 其七' AND p.poem_author = '朱青长';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郊庙歌辞。祀风师乐章。奠币登歌', '包佶', '唐代', '旨酒告絜，青蘋应候。礼陈瑶币，乐献金奏。 \n 弹弦自昔，解冻惟旧。仰瞻肸蚃，群祥来凑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郊庙歌辞。祀风师乐章。奠币登歌' AND p.poem_author = '包佶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('涂中寄城中诸公', '晁说之', '宋代', '孤飞弱羽真难可，作底徘徊去住间。\n柳影生风归曲渚，雷声送雨过前山。\n庾郎有待复何待，白傅求闲而得闲。\n回首玳筵醒醉伴，曾将幽愤唱阳关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '涂中寄城中诸公' AND p.poem_author = '晁说之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('接伴书怀', '曹勋', '宋代', '客路空过桃李春，塞尘温遍马蹄痕。\n荠花如雪苔苗老，应有垂杨绿荫门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '接伴书怀' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('惜花春起早 本意', '顾太清', '清代', '晓禽呜，透纱窗、黯黯淡淡花影。小楼昨宵听尽夜雨，为著花事惊醒。\n\n千红万紫，生怕他、随风不定。便匆匆、自启绣帘看，寻遍芳径。\n\n阶前细草濛茸，承宿露涓涓，香土微泞。今番为花起早，更不惜、缕金鞋冷。\n\n雕栏画槛，归去来、闲庭幽静。卖花声、趁东风，恰恰催人临镜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '惜花春起早 本意' AND p.poem_author = '顾太清';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江上登望', '陆深', '明代', '江流何渺渺，孤帆澹秋晖。遥知三山近，复送百川归。\n\n蜃楼横碧落，龙湫临翠微。徘徊那可极，返照上人衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江上登望' AND p.poem_author = '陆深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄鹤年', '戴良', '明代', '衡门之下可栖迟，且抱遗经住海涯。\n东汉已编《高士传》，西方仍诵美人诗。\n衰年避地方蓬转，故国伤心忽黍离。\n天末秋风正潇瑟，一鸿声彻暮云悲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄鹤年' AND p.poem_author = '戴良';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟师谒祠回天风已霁信若有感姑以二绝道其事 其一', '李弥逊', '宋代', '长芦山下隐龙宫，沥酒船回落照中。已有龟纹为传卜，不劳乌尾更占风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟师谒祠回天风已霁信若有感姑以二绝道其事 其一' AND p.poem_author = '李弥逊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题瞿令人册为茂才绍曾', '胡应麟', '明代', '妇惟丁生母，卓行超人寰。笄岁适名门，婉若蕙与兰。\n\n结缡讵云久，灾氛岌相缠。良人遘奇疾，百体纷摧残。\n\n心神忽眩瞑，手足时颠连。欢娱掷中道，畴不虞红颜。\n\n母也执高节，涕泗如流泉。呼天誓同穴，肯析双飞翰。\n\n一身委床笫，药物长周旋。肝肠绝怨怼，面目忘媸妍。\n\n仰事头白姑，頫鞠黄口男。家徒四壁立，辟纑夜灯前。\n\n拮据度荒馑，永昼怀饥寒。彼苍鉴明德，绕膝森鹓鸾。\n\n矫矫汗血驹，励志游天闲。劬劳念母氏，赋咏蒐名贤。\n\n我闻载叹息，踊跃操如椽。偷生信为易，蹈死亮非难。\n\n厄哉斯人遇，毕世罹忧患。贞心既不毁，淑问仍终完。\n\n夫存子亦树，晚节聊蝉联。宁知处困怀，荼毒穷当年。\n\n凛凛铁石肠，兴彼懦与顽。裁诗颂令哲，史笔千秋传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题瞿令人册为茂才绍曾' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送刘君传扶兄榇南还', '徐溥', '明代', '南风自滴蔷薇露，试向离筵一赋诗。望断蘼芜天际色，折残杨柳道旁枝。\n\n半年共讶言旋早，千里休教问讯迟。独有西堂春草梦，鹡鸰飞处不胜悲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送刘君传扶兄榇南还' AND p.poem_author = '徐溥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送陈睦赴河中幕', '郑獬', '宋代', '紫皇初放第三榜，中有英豪绝世无。天厩本生骐骥子，云霄又得凤凰雏。\n\n不须虎斗终全赵，自是龙骧首破吴。虽作莲花帐前客，丹台到了姓名殊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送陈睦赴河中幕' AND p.poem_author = '郑獬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过南陆山中', '刘崧', '明代', '鸟过平原霜草齐，雉飞兔走各东西。何由掣取腰间剑，细割肥鲜酒自携。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过南陆山中' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉赠石□大参之任云南因示南津太参四诗用韵 其三', '符锡', '明代', '攀梅望乡邑，画舸及春行。亲识欢相迓，旌旄惯不惊。\n\n怀哉庙堂具，介尔丘园情。大业期终集，千秋垂令名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉赠石□大参之任云南因示南津太参四诗用韵 其三' AND p.poem_author = '符锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送孙处士默还黄山', '朱彝尊', '清代', '芜城客散乱乌啼，别业黄山路不迷。后夜相思秋色远，月明三十二峰西。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送孙处士默还黄山' AND p.poem_author = '朱彝尊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('从端州采砚归有作 其一', '屈大均', '明代', '风帆朝别七星冈，路自羚羊向五羊。二水合为三水大，西江流比北江长。\n\n木棉树树如烽火，山雉飞飞过石梁。采得紫云东洞石，归来书案有辉光。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '从端州采砚归有作 其一' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绣释迦像并十八罗汉赞 第九戍博迦尊者', '释德洪', '宋代', '此琉璃瓶，中迸五色。是功德聚，善慈根力。僧俗俨然，殊迹同道。\n\n即事之理，一体三宝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绣释迦像并十八罗汉赞 第九戍博迦尊者' AND p.poem_author = '释德洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出郭閒步', '李昭玘', '宋代', '城市不在眼，始知天宇宽。田园休岁事，风物似江干。\n\n茅屋上斜照，水烟生晚寒。径须追野老，笑语暂盘桓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出郭閒步' AND p.poem_author = '李昭玘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蔡村', '张鸿', '近代', '炎风烈日屈足坐，冷雨凄烟缩项眠。持校帝城流血夜，此中犹是燄摩天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蔡村' AND p.poem_author = '张鸿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题译学张提举乃尊开封府尹张彦亨所藏郭熙盘', '方回', '宋代', '车轣辘，牛觳觫。\n积雪皑皑，飞雪蔌蔌。\n前车上岭后车续，老牛服箱顾寒犊。\n高雪弥山，低雪满谷。\n戴笠执鞭，冻腰跼油。\n画师画此何年事，关塞远征挽刍粟。\n莫道牛疲项领秃，人疲于牛痛欲哭。\n峻岭之下旧村落，萧酒人烟知几簇。\n莫道饷车过门外，门内田家眠正熟。\n百车千车过不已，敲门乞索何时足。\n牛岂不需藁一束，人岂不取一匙粥。\n鸡犬不可保，妻子或窜伏。\n画中水阁尔整齐，焉知不是逃亡屋。\n我闻造化心至公，人间乃有两般风。\n庶民雌风扇臭秽，何独楚王之风雄。\n天地山川同一雪，眼见雪同心各别。\n梁园才子简欲授，栘监老臣毡自齧。\n贫人闭户洛阳卧，壮士衔枚蔡州灭。\n红炉锦帐羔酒斟，岂识盘车图中意愁绝。\n春日陌上花，同遨掷果车，\n不尔鳏翁嫠妇对花成咨嗟。秋夜楼上月，\n同醉生尘袜，不尔羁臣逐客对月翻凄咽。\n鸣呼身在雪岭盘车图，还知世有子猷访戴无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题译学张提举乃尊开封府尹张彦亨所藏郭熙盘' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三六桥属题双凤砚砚有成容若朱竹垞铭周青士跋', '黄浚', '近代', '平生酷爱金风长，尤物曾摩玉带生。又见竹垆留雅伴，想吟柽伞有新铭。\n\n销沈文采材安用，淘洗兴亡眼暂明。今日丹山非故翼，为君郑重赋连城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三六桥属题双凤砚砚有成容若朱竹垞铭周青士跋' AND p.poem_author = '黄浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('真州杂赋', '文天祥', '宋代', '四十羲娥落虎狼，今朝骑马入真阳。\n山川莫道非吾土，一见衣冠是故乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '真州杂赋' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题方元吉诗卷', '刘克庄', '宋代', '古来名世者，一字费吟哦。\n物贵常因少，诗传不在多。\n词人三影句，处士五噫歌。\n子壮吾衰矣，无因共琢磨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题方元吉诗卷' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游洞霄山', '裴相如', '宋代', '人间三十六洞天，各有邃道通神仙。\n兹山九锁路曲折，中开五洞栖云烟。\n东游大涤望天柱，西登石室观飞泉。\n穷幽讨胜足未倦，明月忽堕青崖颠。\n山中道士借一榻，夜半猿鹤惊人眠。\n明朝又复出山去，白云回首空凄然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游洞霄山' AND p.poem_author = '裴相如';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏怀 其七十', '阮籍', '魏晋', '天网弥四野，六翮掩不舒。随波纷纶客，汎汎若浮凫。\n\n生命无期度，朝夕有不虞。列仙停脩龄，养志在冲虚。\n\n飘飖云日间，邈与世路殊。荣名非己宝，声色焉足娱。\n\n采药无旋返，神仙志不符。逼此良可惑，令我久踌躇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏怀 其七十' AND p.poem_author = '阮籍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读故许昌薛尚书诗集', '郑谷', '唐代', '篇篇高且真，真为国风陈。澹薄虽师古，纵横得意新。 \n 翦裁成几箧，唱和是谁人。华岳题无敌，黄河句绝伦。 \n 吟残荔枝雨，咏彻海棠春。李白欺前辈，陶潜仰后尘。 \n 难忘嵩室下，不负蜀江滨。属思看山眼，冥搜倚树身。 \n 楷模劳梦想，讽诵爽精神。落笔空追怆，曾蒙借斧斤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读故许昌薛尚书诗集' AND p.poem_author = '郑谷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('撷芳亭夜话', '李之世', '明代', '闻亭秋气早，芳树晚留飔。爱此槐阴月，清光来入池。\n\n微吟穿竹径，对语隔花枝。渐觉明河没，城头晓漏迟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '撷芳亭夜话' AND p.poem_author = '李之世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('车中即事五首 其一 朝夕', '郭之奇', '明代', '计日尘容惯客，沿堤柳色迷天。朝暾马右分旭，夕照襟西送烟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '车中即事五首 其一 朝夕' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丁未元日吟', '湛若水', '明代', '八十二回寒暑更，渭川同钓不同情。老夫独捲丝纶坐，坐到东溟月又生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丁未元日吟' AND p.poem_author = '湛若水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('醉歌三首', '仇远', '宋代', '清狂歌窈窕，微醉困瞢腾。\n酒薄多疑水，官閒一似僧。\n已知灯即火，不愿谷为陵。\n百事俱能了，惟余饮未能。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '醉歌三首' AND p.poem_author = '仇远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采芡', '梅尧臣', '宋代', '猬毛苍苍磔不死，铜盘矗矗钉头生。吴鸡斗败绛帻碎，海蚌抉出真珠明。\n\n磨沙漉水莩壳滑，斫桂煮釜风波声。齿如编贝嚼明月，曼倩不复饥肠鸣。\n\n莫论一斛贵与贱，堂上狼藉无由行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采芡' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵仲平十八日观潮', '周紫芝', '宋代', '吴儿轻生命如线，赤脚翻身踏江练。南人惯看心不惊，北客平生眼希见。\n\n海上潮来雪不如，中郎诗成锦初烂。句法岂但窥澄江，壮士何从挽天汉。\n\n飞流溅沫不足论，万壑千岩此为冠。解言越峤翠摩空，岁与浪花争隐见。\n\n我亦苍颜阅九州，始问江神得奇玩。六年东望西兴云，岁月崩奔一飞箭。\n\n拟将匹练作江图，归与故人誇伟观。倘从江海识波涛，分逐秋篷共流转。\n\n试令海若语冯夷，惭色自应须满面。谁当更草海潮篇，词采风流付王翰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵仲平十八日观潮' AND p.poem_author = '周紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和慎思秋日同文馆 其二', '商倚', '宋代', '秋日同文馆，何人独擅场。养莪方在沚，琢玉已成章。\n\n笔列千锋阵，庭焚一炷香。得贤从此始，岂特致民康。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和慎思秋日同文馆 其二' AND p.poem_author = '商倚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贞白祠', '宗臣', '明代', '华阳山前贞白祠，贞白先生骑赤螭。白云茫茫去不返，天门秋冷双虹垂。\n\n吾来山头寻紫芝，紫芝萧索令人饥。出门白石烂如泥，切来好煮青松衼。\n\n与君大餐各五斗，千山万山随所之。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贞白祠' AND p.poem_author = '宗臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄祭酒林先生 其一', '庄昶', '明代', '狂谬无端似病风，少年此处几人同。如今万事消磨尽，甘做乾坤一病翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄祭酒林先生 其一' AND p.poem_author = '庄昶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大除夕为本生父身后百日书以志痛二首 其二', '曹家达', '清代', '漫从叔宝问心肝，红烛沉沉向夜阑。忍记昔年风雨夜，尊前温语劝加餐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大除夕为本生父身后百日书以志痛二首 其二' AND p.poem_author = '曹家达';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行路难 其五十七', '钱澄之', '清代', '自是多生风障深，才抛稚子又关心。出山送尔寻舟去，指与江头枫树林。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行路难 其五十七' AND p.poem_author = '钱澄之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送别', '刘基', '元代', '送别江头日欲沉，落湳风急鸟归林。秋云恰似人情薄，秋水还同客恨深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送别' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和林子长送芡实诗韵 其一', '虞俦', '宋代', '芡实尝新又一年，溪堂风物想依然。软温初剥浑如旧，只欠高谈惊四筵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和林子长送芡实诗韵 其一' AND p.poem_author = '虞俦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐', '晏几道', '宋代', '波纹碧皱。曲水清明后。折得疏梅香满袖。暗喜春红依旧。 \n 归来紫陌东头。金钗换酒消愁。柳影深深细路，花梢小小层楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('仿杜工部同谷七歌 其一', '虞淳熙', '明代', '有客有客吟泽畔，短墙缺岸蓬蒿乱。妖鱼拨剌白蛇横，横皮塔下无昏旦。\n\n我生胡为在旷野，盲风夜号尘满案。鹿门无妻獠奴走，皮骨空留肠已断。\n\n呜呼一歌兮思傍徨，高天为我零寒霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '仿杜工部同谷七歌 其一' AND p.poem_author = '虞淳熙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题耕图二十三首 其十三 第十三图', '玄烨', '清代', '䆉稏盈畦日正长，复勤穮蓘下方塘。堪怜曝背炎蒸下，惟冀青畴发紫芒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题耕图二十三首 其十三 第十三图' AND p.poem_author = '玄烨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词 其十六', '赵佶', '宋代', '仙韶总角籍严宫，初学吹笙性格聪。十指近才能按字，纤纤双捧紫筠丛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词 其十六' AND p.poem_author = '赵佶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿洋川李守昌谔二首 其一', '陈天麟', '宋代', '桂子风高瑞霭浮，晓来无处不欢讴。共怀襦裤歌廉范，更指龟蒙祝鲁侯。\n\n风月莫辜三十咏，星霜行阅八千秋。皇家正重惟良寄，衮服归公正黑头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿洋川李守昌谔二首 其一' AND p.poem_author = '陈天麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花', '龚自珍', '清代', '酒压春愁春卷絮。燕子归来，苦说年华误。半晌怀人搔首伫。\n\n落梅风急闲庭暮。\n\n辛苦痴怀何用诉。曲曲香痕，曲到无凭据。安顿惜花心事处。\n\n谢他昨夜风和雨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花' AND p.poem_author = '龚自珍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('罗思纯鹤斃为四韵吊之', '王禹偁', '宋代', '雪乾朱澹殒仙姿，千岁无徵事可悲。\n埋瘗肯饶鹦鹉冢，飞鸣不到凤凰池。\n遗翎尚在飘松迳，旧迹犹存傍槿篱。\n应得羽人尸解术，夜来何处啄灵芝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '罗思纯鹤斃为四韵吊之' AND p.poem_author = '王禹偁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟行杂咏四首 其二', '承培元', '清代', '鬖鬟覆额小渔娃，雨立船头唤卖虾。湿透单衣浑不觉，一枝擎出水犀花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟行杂咏四首 其二' AND p.poem_author = '承培元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('奉教和资中八景 其二 醮坛云梯', '王绅', '明代', '仙家咫尺隔尘凡，寂寞当年古石坛。苍藓重封层磴足，白云深锁石梯端。\n\n眼前日月弹丸急，脚底烟霞图画闲。欲访安期问真诀，置身此地杳冥间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '奉教和资中八景 其二 醮坛云梯' AND p.poem_author = '王绅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('武山十四境 其十四 石鼓', '刘崧', '明代', '片石上嵯峨，春风覆薜萝。何人踏龙尾，白日撼灵鼍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '武山十四境 其十四 石鼓' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风流子 其三 别妓', '王之望', '宋代', '柳花飞絮，又还是、清明寂寞时节。洞府人间嗟素手，今日匆匆分拆。\n\n巧笑难成，含情谁解，顾影无颜色。风流满面，却成春恨凄恻。\n\n云鬓从亸金蝉，纷纷红泪，千点胭脂湿。聚调轻盈离调惨，声入低空愁碧。\n\n祖帐将收，骊驹欲驾，去也劳相忆。伤心南浦，断肠芳草如积。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风流子 其三 别妓' AND p.poem_author = '王之望';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史上·商鞅', '陈普', '宋代', '此天此地此经文，学者何尝溺所闻。\n尽道李斯焚典籍，不知吹火是商君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史上·商鞅' AND p.poem_author = '陈普';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和幽居', '赵希逢', '宋代', '不因搜句不曾忙，尽日柴门闭短墙。\n寄傲北窗闲着眼，任他书卷展风床。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和幽居' AND p.poem_author = '赵希逢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题山水画卷', '尹廷高', '元代', '身在山水间，心在山水外。世无钟子期，白云兀相对。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题山水画卷' AND p.poem_author = '尹廷高';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿诗', '郭奎', '明代', '惟天生俊杰，济世属英豪。间气钟华岳，元勋压巨鳌。\n\n东山文物旧，南极寿星高。公族嗟麟趾，儒林起凤毛。\n\n郎官前甲胄，使节左旌旄。细柳回兵仗，香芸辟武韬。\n\n珥貂先见擢，汗马岂辞劳。谈笑三军却，喑呜万骑逃。\n\n运筹期管乐，立业比萧曹。画戟行当道，彤弓忆载櫜。\n\n独专方叔任，重佩吕虔刀。此日祥初应，当年庆可褒。\n\n玉阶浮宝树，金母进蟠桃。瑞霭迎双鹤，清声被九皋。\n\n嘉宾来騕袅，童子献蒲萄。锦瑟尊前鼓，瑶琴席上操。\n\n银丝鲜鲙鲤，翠釜晓烹羔。醉倚青油幕，晴熏白锦袍。\n\n升堂闻拜颂，入府咏游遨。永祝三千岁，钱塘望海涛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿诗' AND p.poem_author = '郭奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵社集诗', '曹学佺', '明代', '法曹清杀大堤傍，路入荷花不觉长。\n为惜六朝余绮丽，还邀群彦醉壶觞。\n烟轻故罩新开粉，风细时吹不断香。\n彩躭底须愁荡却，文鸳偏自解成行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵社集诗' AND p.poem_author = '曹学佺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙·与客湖上饮归', '叶梦得', '宋代', '不见跳鱼翻曲港，湖边特地经过。萧萧疏雨乱风荷。微云吹散，凉月堕平波。\n白酒一杯还径醉，归来散发婆娑。无人能唱采莲歌。小轩欹枕，檐影挂星河。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙·与客湖上饮归' AND p.poem_author = '叶梦得';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陶弘景', '徐钧', '宋代', '缚屋倚松志本清，援图成趣若为情。\n预闻国政无虚日，笑杀山中宰相名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陶弘景' AND p.poem_author = '徐钧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('陇头', '姚宽', '宋代', '下陇流水咽，上陇征人别。\n秦树暗秋云，燕鸿隔春雪。\n闪倏见胡骑，翩翩传汉节。\n戍客起愁心，心与飞蓬折。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '陇头' AND p.poem_author = '姚宽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南乡子　雪中飞过灞水', '魏新河', '当代', '风雪灞桥头，驴背吟诗孰与俦。我在云端翻旧谱，箜篌，听取仙人十二楼。\n\n河汉水西流，待把诗囊括斗牛。携得精芒十万丈，归休，要把光明散九州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南乡子　雪中飞过灞水' AND p.poem_author = '魏新河';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丙午新正书怀十首', '范成大', '宋代', '穷巷闲门本然，强将爆竹聒阶前。\n人情旧雨非今雨，老境增年是减年。\n口不两匙休足縠，身能几屐莫言钱。\n扫除一室空诸有，庞老家人总解禅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丙午新正书怀十首' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬裴员外以诗代书', '高适', '唐代', '少时方浩荡，遇物犹尘埃。脱略身外事，交游天下才。 \n 单车入燕赵，独立心悠哉。宁知戎马间，忽展平生怀。 \n 且欣清论高，岂顾夕阳颓。题诗碣石馆，纵酒燕王台。 \n 北望沙漠垂，漫天雪皑皑。临边无策略，览古空裴回。 \n 乐毅吾所怜，拔齐翻见猜。荆卿吾所悲，适秦不复回。 \n 然诺多死地，公忠成祸胎。与君从此辞，每恐流年催。 \n 如何俱老大，始复忘形骸。兄弟真二陆，声名连八裴。 \n 乙未将星变，贼臣候天灾。胡骑犯龙山，乘舆经马嵬。 \n 千官无倚著，万姓徒悲哀。诛吕鬼神动，安刘天地开。 \n 奔波走风尘，倏忽值云雷。拥旄出淮甸，入幕征楚材。 \n 誓当剪鲸鲵，永以竭驽骀。小人胡不仁，谗我成死灰。 \n 赖得日月明，照耀无不该。留司洛阳宫，詹府唯蒿莱。 \n 是时扫氛祲，尚未歼渠魁。背河列长围，师老将亦乖。 \n 归军剧风火，散卒争椎埋。一夕瀍洛空，生灵悲曝腮。 \n 衣冠投草莽，予欲驰江淮。登顿宛叶下，栖遑襄邓隈。 \n 城池何萧条，邑屋更崩摧。纵横荆棘丛，但见瓦砾堆。 \n 行人无血色，战骨多青苔。遂除彭门守，因得朝玉阶。 \n 激昂仰鹓鹭，献替欣盐梅。驱传及远蕃，忧思郁难排。 \n 罢人纷争讼，赋税如山崖。所思在畿甸，曾是鲁宓侪。 \n 自从拜郎官，列宿焕天街。那能访遐僻，还复寄琼瑰。 \n 金玉本高价，埙篪终易谐。朗咏临清秋，凉风下庭槐。 \n 何意寇盗间，独称名义偕。辛酸陈侯诔，叹息季鹰杯。 \n 白日屡分手，青春不再来。卧看中散论，愁忆太常斋。 \n 酬赠徒为尔，长歌还自咍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬裴员外以诗代书' AND p.poem_author = '高适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汎昆明池至近华浦大观楼', '郑珍', '清代', '云南正月半，杨柳青满湖。浮舟出郡郭，逌然如画图。\n\n汪汪千顷波，晴沙畅平铺。和风弄舞燕，微澜漾浮凫。\n\n赤脚两桨女，妙称樗散徒。踏舷唱小梅，浩气淩八区。\n\n沐氏旧西园，宛在似篷壶。早树发初绿，粉墙明精庐。\n\n诸渔集门曲，幽清无鸟呼。何人构层楼，倒映水府居。\n\n凭阑纵周眺，心目乃以舒。群山从北来，柘城烟有无。\n\n九十九水窦，足锸十万夫。夕阳转西山，岩观正模糊。\n\n何处昆阳州，风帆尽南趋。俯仰一杯酒，襟怀千载馀。\n\n霸业垂扫尽，苍茫留此潴。海风送黄鹤，思便朝清都。\n\n弟妹各牵衣，白云不可呼。长啸动归桡，月上东城隅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汎昆明池至近华浦大观楼' AND p.poem_author = '郑珍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和陶渊明归田园居六诗', '陈造', '宋代', '种禾摭其实，即穊乃可稀。\n儒吏瞢不长，竟为老农归。\n萋芸儿可犂，称力食且衣。\n平生睎庞翁，此意今不违。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和陶渊明归田园居六诗' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂兴六首', '陆游', '宋代', '故交零落形吊影，陈迹凄凉口语心。\n辛苦一生成底事，祈招空解诵愔愔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂兴六首' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('野眺', '张宇初', '明代', '山谷寒应早，幽怀绝垢氛。\n白波双涧雨，红树半坳云。\n啼鸟欺新冷，潜鱼傍夕曛。\n寂寥何所慰，先哲有遗文。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '野眺' AND p.poem_author = '张宇初';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('齐天乐五十首 其二', '端木埰', '清代', '万家香霭腾金阙，余寒酿成春意。爆竹催年，铭椒献岁，又是阳和将至。\n\n流光逝水，怅催老英雄，者般容易。后饮屠苏，有人犹抱少年志。\n\n平生豪气未减，记萧斋读月，长剑孤倚。碧海屠鲸，青天饲鹤，少日心情空记，新来更喜。\n\n幸留得儿时，夜灯书味。为问梅华，可容同调比。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '齐天乐五十首 其二' AND p.poem_author = '端木埰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寓兴二首 其二', '黄衷', '明代', '诸天缥缈入云门，浪遣华镳踏市喧。梦里和南多旧侣，壁间留偈总真言。\n\n长松石隐维摩室，蔓草金微舍利园。法眼只堪观物幻，道身宁为坐花尊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寓兴二首 其二' AND p.poem_author = '黄衷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄范十九', '刘敞', '宋代', '君毋走马君竟走，走马蹶块伤君手。蹭蹬翻成折臂翁，世间肯要三公否。\n\n西郊虏骑非常壮，年年犯边杀边将。劲弓长剑如君徒，始堪追逐青海上。\n\n功名弃置时未可，意气激昂人所望。侧身万里风雪寒，无由赠子黄金丹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄范十九' AND p.poem_author = '刘敞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洛水铭', '李尤', '两汉', '洛出熊耳，东流会集。夏禹导疏，经於洛邑。元龟赤字，汉符是立。\n\n帝都通路，建国南乡。万乘终济，造舟为梁。三都五州，贡篚万方。\n\n广视远听，审任贤良。元首昭明，庶物是康。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洛水铭' AND p.poem_author = '李尤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题聂松厓印谱', '戴亨', '清代', '君不能身佩长剑趋明光，又不能手提孟劳开八荒。\n\n郁郁蓬荜不得志，慨然嗜古穷轩苍。一艺精专可千古，何须奔走荣名场。\n\n但持昆吾五寸铁，直探隆古龟龙穴。阴晴寒暑四十年，心摹手拟精神结。\n\n天不雨金鬼夜哭，魂招斯籀来奔谒。长安文苑多英奇，挥毫洒墨咸繇□。\n\n偶得邀君为篆刻，便觉名姓生光辉。陋我逢君苦不早，晤言欢若平生好。\n\n为我购石镌数方，但觉鸿黄气邃窈。印谱传为希世珍，谱中人识辽东老。\n\n文三桥，何雪渔，高名已并前贤驱。劝君怀宝且归去，烟霞啸傲栖蓬庐。\n\n蓬庐之乐乐莫比，琬琰休向街头市。君谓绝技可赢饶，千里辞家客燕邸。\n\n时方重利较锱铢，真赏于今竟谁是。况君负郭有良田，丰歉不至啼妻子。\n\n劝君早赋归去来，我实饥寒不得已。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题聂松厓印谱' AND p.poem_author = '戴亨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('逍遥咏 其六', '赵炅', '宋代', '何处堪依仗，经心便皱眉。世情多诡诈，业重信愚痴。\n\n取次招他谤，违非不自知。貌恭无德行，祸福在修持。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '逍遥咏 其六' AND p.poem_author = '赵炅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('碧云寺', '钱谦益', '清代', '丹青台殿起层层，玉砌雕闹取次登。\n禁近恩波蒙葬地，内家香火傍掸灯。\n丰碑巨刻书元宰，碧海红尘问老僧。\n礼罢空王三叹息，自穿萝径拄孤藤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '碧云寺' AND p.poem_author = '钱谦益';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬日', '释函是', '明代', '厌闹思投老，甘心堕小乘。时危村寺稳，道替竹林增。\n\n适意惟高枕，清谈共数僧。海门红日下，危坐剔孤灯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬日' AND p.poem_author = '释函是';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('时宰生日诗三十绝 其二十二', '周紫芝', '宋代', '黄金新铸景钟鸣，公作铭诗纪告成。从此圣朝郊祀典，文章无复数西京。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '时宰生日诗三十绝 其二十二' AND p.poem_author = '周紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠西平侯沐英', '解缙', '明代', '彩凤有遗雏，喤喤泣载途。神龙亲哺育，跃马赞皇图。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠西平侯沐英' AND p.poem_author = '解缙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('为建昌南城包显道题光风霁月之阁', '项安世', '宋代', '扁以槐堂之钜笔，铭以云谷之高辞。镇以平园之签帙，照以太极之肝脾。\n\n千岩万壑转芳气，青天碧海流清规。春晨画出舞雩咏，夜景看成彭泽诗。\n\n勉哉此事要真积，昔者所闻无坐驰。愿追策骥予陶子，勿但嘐嘐如牧皮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '为建昌南城包显道题光风霁月之阁' AND p.poem_author = '项安世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('予居云溪七载，岁岁皆有灯花，今乃得见之。同者数人，李智国命作诗。时正月十四之夜，立春之次日也', '卢青山', '当代', '折首枯茅仰爪丫，闻春昨至隐谁家？且抬世界灰尘眼，暂看天空幻想花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '予居云溪七载，岁岁皆有灯花，今乃得见之。同者数人，李智国命作诗。时正月十四之夜，立春之次日也' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟行舣韶下石夜听', '曾丰', '宋代', '江响合蛮吹，鸟声谐越吟。\n仍收南郭籁，并入大韶音。\n纚纚听于耳，徐徐写以琴。\n倘犹有作韵，着语付何阴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟行舣韶下石夜听' AND p.poem_author = '曾丰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('从驾游内苑应制', '岳飞', '宋代', '敕报游西内，春光霭上林。\n花围千朵锦，柳捻万株金。\n燕绕龙旗舞，莺随凤辇吟。\n君王多雨露，化育一人心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '从驾游内苑应制' AND p.poem_author = '岳飞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('园林瞻眺同仲木作二首 其二', '康海', '明代', '膏雨既周彻，田工粗可期。黾勉命童仆，篮舆诣东菑。\n\n欣此麰麦遂，坐令芳意弥。业岁望丰衍，行乐值晴熙。\n\n况与良士同，更惬山水思。击筑发古调，弹筝奋新词。\n\n夜以继白日，潇洒孰可追。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '园林瞻眺同仲木作二首 其二' AND p.poem_author = '康海';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五禽言五首，并叙 其二', '苏轼', '宋代', '昨夜南山雨，西溪不可渡。溪边布谷儿，劝我脱破裤。\n\n不辞脱裤溪水寒，水中照见催租瘢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五禽言五首，并叙 其二' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('妙音方丈', '黄彦平', '宋代', '弥勒同龛夕，难摩示病情。\n炉残文武火，灯暗短长檠。\n耿介游良苦，温柔梦不成。\n颦眉挑锦字，相忆恨高城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '妙音方丈' AND p.poem_author = '黄彦平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('击蛇笏', '白珽', '宋代', '孔明庙前柏，手版贼其枝。\n枯秭无生气，众目炫一时。\n何如孔公笏，铁面含霜姿。\n虺蛇何足道，正气屡奸欺。\n祥符庆历间，岂无纤人斯。\n闻之胆为落，不在彼在兹。\n圣学亿万年，圣源浩无涯。\n八传得巨源，愤学求似之。\n遗经与遗物，保护如婴儿。\n万里去复远，见者咸赍咨。\n况此一尺槐，千载孔林思。\n非无原壤杖，非无少正铍。\n用舍各有时，小大各有施。\n畴能起段公，共赋甘堂诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '击蛇笏' AND p.poem_author = '白珽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红（甲辰岁盘门外寓居过重午）', '吴文英', '宋代', '结束萧仙，啸梁鬼、依还未灭。荒城外、无聊闲看，野烟一抹。梅子未黄愁夜雨，榴花不见簪秋雪。又重罗、红字写香词，年时节。 \n 帘底事，凭燕说。合欢缕，双条脱。自香消红臂，旧情都别。湘水离魂菰叶怨，扬州无梦铜华阙。倩卧箫、吹裂晚天云，看新月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红（甲辰岁盘门外寓居过重午）' AND p.poem_author = '吴文英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋怀二首选一', '林散之', '近代', '自辟五亩园，辛苦二十稔。虽无长者车，孤游供息寝。\n\n江上易气象，日月殊光景。物换何匆匆，几醒庐生枕。\n\n版图惊战祸，一十九行省。城郭与池台，多半劫灰烬。\n\n小人与君子，多半沙虫影。念兹散木堂，犹能在人境。\n\n偶然亦天意，物存真自幸。年年秋风至，松竹色明靓。\n\n风雨又今年，寒绿更凄紧。友朋时过从，儿女有朝请。\n\n余生话灯火，尘缘暂相屏。功名细事耳，死生乃俄顷。\n\n陆沉慨神州，闰余羞蛙黾。不荷娲皇宠，谁能补完整。\n\n东山思太傅，西湖念和靖。疏梅共豪竹，天性各有秉。\n\n辜负诚可怜，转侧秋江冷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋怀二首选一' AND p.poem_author = '林散之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋朝览镜', '薛稷', '唐代', '客心惊落木，夜坐听秋风。朝日看容鬓，生涯在镜中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋朝览镜' AND p.poem_author = '薛稷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渡海歌', '成鹫', '明代', '天地之大夫如何，谛观沧海成叵罗。垂云大翼驾与鹅，乘风巨舰机中梭。\n\n蛟龙戏水蛇旋涡，江豚拜浪豕涉波。我生七尺胡足多，聚散珠转风中荷。\n\n今朝渡海天气和，柔风吹席行蹉跎。天空海阔无复他，眼前有景不得歌。\n\n沧波极目殊山河，朱明回首荒烟萝。登高望远无斧柯，老眼一日三摩挲。\n\n白云缥缈山嵯峨，东乌西匿虚阳戈。终朝形役暮则那，停舟见月扬纤蛾。\n\n古镜出匣尘未磨，微光照客寝复吪。三更隔水闻枯螺，千家海市枕灵鼍。\n\n晓来登岸人肩摩，风景恍惚曾经过。天涯走杀老头陀，江边笑倒春梦婆。\n\n呵呵呵，天涯走杀老头陀，江边笑倒春梦婆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渡海歌' AND p.poem_author = '成鹫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('朝斗坛', '胡衍', '宋代', '不见铜龙何处飞，空馀芳草旧台基。月明风冷禽声碎，疑是仙人佩玉归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '朝斗坛' AND p.poem_author = '胡衍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大热二首', '欧阳修', '宋代', '阳晖烁四野，万里纤云收。\n羲和困路远，正午当空留。\n枝条不动影，草木皆含愁。\n深林虎不啸，卧喘如吴牛。\n蜩蝉一何微，嗟尔徒啾啾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大热二首' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('日本杂事诗 其一二二', '黄遵宪', '清代', '抟花作饭胜胡麻，嚼蕊流酥更点茶。费尽挼莎才结果，果然团子贵于花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '日本杂事诗 其一二二' AND p.poem_author = '黄遵宪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('伤春', '张耒', '宋代', '山城夜来雨，卧病惜残春。\n暗暗鸟啼树，飘飘花去人。\n地偏佳客断，官冷酒钱贫。\n乘兴还骑马，田家乐更真。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '伤春' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠僧宗佑', '黄彦臣', '宋代', '潇潇丰姿迥不同，少年来住此禅丛。\n谁知今日佑和尚，便是当年钟令公。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠僧宗佑' AND p.poem_author = '黄彦臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('徵招　挽择庐翁', '寇梦碧', '近代', '西风唤笛江城晚，凄凉顿添秋绪。薤唱冷烟沽，问鸥盟谁主。\n\n夜台悲碎语。抵多少、断宫零羽。剪碧词怀，听风吟兴，一暝终古。\n\n前度。溯追游，怜才意，题襟许陪尊俎。玄赏负深期，叹年华空误。\n\n素弦今独抚。剩依黯、云谣新谱。断魂远，拟叩灵阍，奈梦边无路。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '徵招　挽择庐翁' AND p.poem_author = '寇梦碧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('看病二首 其二', '释函是', '明代', '余心不得已，静想亦奚为。续命非关药，劳形只是痴。\n\n百年同旦夕，转盼忽支离。独坐空长啸，人天何太迟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '看病二首 其二' AND p.poem_author = '释函是';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感寓 其二十', '刘弇', '宋代', '疾雷疑车音，出门乃知非。抱影长自明，流萤点霜帏。\n\n罗带剪秋水，黄金缕春衣。持看清夜阑，愁无故时辉。\n\n食葵心知倾，茹腊肠虚肥。纂纂枣下歌，惜此岁月违。\n\n因声劝语侬，忽复迟迟归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感寓 其二十' AND p.poem_author = '刘弇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杭正月十三夜', '方回', '宋代', '歌鼓犹闻治世音，逃喧爱寂自沈吟。九衢翠钿春□□，一室青灯夜独深。\n\n岂不冻云开霁月，其如老眼异童心。□□变幻凉州梦，便觉繁华胜似今。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杭正月十三夜' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜坐感怀', '唐庚', '宋代', '声断钟楼月，文书对坐时。破窗灯焰走，冻砚笔锋迟。\n\n名利发将鹤，风霜手欲龟。何当一蓑雨，披晓剪莼丝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜坐感怀' AND p.poem_author = '唐庚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜坐', '赠钰', '明代', '庭虚初月上，树响微风入。栖鹊听犹惊，流萤堕还拾。\n\n沉沉寒漏滴，隐隐余钟急。坐久不知疲，凉衣露吹湿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜坐' AND p.poem_author = '赠钰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜迁莺·顿消缘虑', '佚名', '宋代', '顿消缘虑。觉梦蝶劳生，鹑居蓬户。饭蚁醯鸡，尘衫风帽，赢得百年虚度。利如断霞残照，名若落花飞絮。岂坚固。似风中秉烛，枝头垂露。谁悟。独归去。收拾水云，高卧曹溪路。竹外流泉，篱边丛菊，妆点野棠闲趣。五柳槛前吟醉，一笑人间今古。欲分付。叹烟波渺渺，知音何处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜迁莺·顿消缘虑' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送何济川为庞公使庆阳席上探得冬字', '司马光', '宋代', '幕府遥三舍，传车乘一封。\n忠深轻远道，醉暖朱严冬。\n圁水犹飞檄，芦关未灭烽。\n贤侯虽喜士，人得久从容。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送何济川为庞公使庆阳席上探得冬字' AND p.poem_author = '司马光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词', '杨皇后', '宋代', '缺月流光入绮疏，金壶傅箭梦回初。\n秦台彩凤无消息，桂影空闲十二除。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词' AND p.poem_author = '杨皇后';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪纱 其十一', '程颂万', '清代', '闻雨伤春梦不成。客中谁最有风情。\n\n武陵一曲想南征。\n\n蜀纸麝煤添笔媚，风帘残烛隔霜清。\n\n已携孤剑事离程。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪纱 其十一' AND p.poem_author = '程颂万';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('莪默绝句集译笺乙集 其四八四', '伯昏子', '当代', '翼仙拂曙御风临，奉爵拟邀同啸吟。且唱雄王化尘土，年轮月毂碾骎骎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '莪默绝句集译笺乙集 其四八四' AND p.poem_author = '伯昏子';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('好事近 赋朱庵台桂，桂为明季一老尼手植，枝柯四周蟉结，累八九层，如浮屠状，庵在秀州南堰', '朱祖谋', '清代', '遗世广寒仙，香界别开蟾户。一例恒沙劫换，比月盘松古。\n\n色身不碍被黄絁，糁地碎天布。遮莫穷檐薪尽，供箨龙斤斧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '好事近 赋朱庵台桂，桂为明季一老尼手植，枝柯四周蟉结，累八九层，如浮屠状，庵在秀州南堰' AND p.poem_author = '朱祖谋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('兵乱后自嬄杂诗 其六', '吕本中', '宋代', '叛将斩关入，通衢列众兵。军声逐飞瓦，杀气暗前旌。\n\n事定愁方剧，身危梦尚惊。乾坤空纳纳，何处寄馀生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '兵乱后自嬄杂诗 其六' AND p.poem_author = '吕本中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙 其一', '汪东', '清代', '羸病新知白发增。未妨春气透疏棂。小园梅蕊已含馨。\n\n伏枥尚存千里志，培风终拟九霄行。莫将修短论余生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙 其一' AND p.poem_author = '汪东';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早朝诗', '杨子器', '明代', '平旦曈昽瑞霭浮，曙星送月下西楼。画衣遥入迎仙跸，黄伞高擎覆采旒。\n\n鸾帚拂尘花雨霁，霓旌曳影柳风柔。太平无事春如海，天保歌长乐未休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早朝诗' AND p.poem_author = '杨子器';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('悬崖菊', '陈永正', '当代', '谁令此花热，衣香盈古丘。倒悬消几日，相望是何秋。\n\n无主偏增媚，临波始欲愁。名园尘暗动，不待雨风收。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '悬崖菊' AND p.poem_author = '陈永正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一箩金 题扬州女子静怜月底修箫谱障子', '郑文焯', '清代', '镜里愁妆熏麝苦。细玉参差，却替花魂语。人瘦于花花尚妒。\n\n冷香吹雪开庭暮。\n\n罗袂禁寒谁伴汝。曲曲阑干，曲到无凭处。满把春星和梦数。\n\n旧情红老东风树。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '一箩金 题扬州女子静怜月底修箫谱障子' AND p.poem_author = '郑文焯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵明叔九日见怀', '周紫芝', '宋代', '准拟重阳共一杯，幅巾临水复登台。飞花扑面君相送，落叶满山人未回。\n\n故国只凭幽梦到，断肠频寄尺书来。此生终向江湖老，黄菊红萸笑谩催。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵明叔九日见怀' AND p.poem_author = '周紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('又和宋侯三首', '刘克庄', '宋代', '铃斋教令得民和，月色今宵十倍多。\n节物人家俱插柳，霁华田舍可鞭禾。\n坐中客醉僛僛舞，陌上花开缓缓歌。\n老子尚堪牵率在，夜归已有木鱼过。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '又和宋侯三首' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋词', '萨都剌', '元代', '清夜宫车出建章，紫衣小队两三行。\n石阑干畔银灯过，照见芙蓉叶上霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋词' AND p.poem_author = '萨都剌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望江南十三首 其七 旅窗杂忆', '丁宁', '近代', '幽栖好，吾自爱吾庐。满院金风朝试剑，一帘凉月夜摊书。\n\n曾几感离居。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望江南十三首 其七 旅窗杂忆' AND p.poem_author = '丁宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('牧大同原杨林坑即事', '吴与弼', '明代', '既辍黄岚游，却入同原嬉。三阳时向交，暖律回春晖。\n\n人情惜旧好，物熊含新辉。悠哉四圣心，静向林间窥。\n\n单骑日日来，飘飘澹忘归。偶携二三子，丽泽同箴规。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '牧大同原杨林坑即事' AND p.poem_author = '吴与弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满庭芳', '赵令', '宋代', '玉枕生凉，金缸传晓，败叶飞破清秋。雨余翻浪，渺渺阻行舟。暂系汀洲侧畔，风夜起、荻叶添愁。银屏远，龙香渐尽，还是梦扬州。 \n 更筹。何太永，当年情事，今日堪酬。最苦恨红楼，笑我飘浮。为寄相思细字，教字字、愁蹙眉头。凄凉久，渔人唱晓，随月过横沟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满庭芳' AND p.poem_author = '赵令';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚晴书事呈同舍', '陆游', '宋代', '鱼复城边夕照红，物华偏解恼衰翁。\n巴莺有恨啼芳树，野水无情人故宫。\n许国渐疏悲壮志，读书多忘媿新功。\n因君共语增惆怅，京洛交游欲半空。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚晴书事呈同舍' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('念三日酉时立秋晚对感叹', '郭之奇', '明代', '忽值西来爽，薄暮洒幽窗。轻烟团桂影，细霭拂漓江。\n\n百年衰变感，自疑蓬鬓双。飒飒同人世，悲凉满血腔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '念三日酉时立秋晚对感叹' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('僧园秋集同田生二首 其一', '李梦阳', '明代', '榴竹晴相媚，秋光满给孤。微风捎果重，残暑入林无。\n\n宝塔金杯映，青天白鹤呼。不须谈浩劫，吾醉亦忘吾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '僧园秋集同田生二首 其一' AND p.poem_author = '李梦阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('厅前柏', '苏辙', '宋代', '稚柏如婴儿，冉冉三尺长。移根出涧石，植干对华堂。\n\n重露恣膏沐，清风时抑扬。我老不耐寒，怜汝堪风霜。\n\n朝夕望尔长，尺寸常度量。知非老人伴，可入诸孙行。\n\n想见十年后，檐前蔚苍苍。人来顾汝笑，诵我此诗章。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '厅前柏' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花 秋夜不寐，枕上口占', '陈嘉', '清代', '银汉无声珠露湿。一抹秋痕，沁透诗人骨。冰簟凉生清梦惬。\n\n枕边茉莉花如雪。\n\n风飏罗帷灯欲灭。切切凄凄，向曙啼蛩急。远寺钟鸣催落月。\n\n纱窗微透东方白。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花 秋夜不寐，枕上口占' AND p.poem_author = '陈嘉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题郑承事所作惠兰三首', '陈鉴之', '宋代', '兰如君子蕙如士，此评吾得这涪翁。\n有余不足姑勿率，毕竟清幽气类同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题郑承事所作惠兰三首' AND p.poem_author = '陈鉴之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽云屋徐侍郎 其一', '王义山', '宋代', '阖朝奔逸荡无关，夜半潇潇风雨寒。世乱争先寻活路，时贫输与做穷官。\n\n平生自谓学无事，一死谅非君所难。到此徬徨犹不忍，国亡那敢计身安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽云屋徐侍郎 其一' AND p.poem_author = '王义山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿蒋山栖霞寺', '俞紫芝', '宋代', '独坐清谈久亦劳，碧松燃火暖衾袍。夜深童子唤不起，猛虎一声山月高。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿蒋山栖霞寺' AND p.poem_author = '俞紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江乡', '郑文康', '明代', '江乡酒熟黍离离，莼菜鲈鱼正及时。堪笑同行门外客，月明乌鹊叹无枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江乡' AND p.poem_author = '郑文康';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题高房山夜山图', '张逢原', '宋代', '地位清高眼界宽，尽收风景入豪端。废宫台榭和烟锁，隔岸江山对月看。\n\n一水中分吴越近，层楼低接斗牛寒。有声画意吟难了，更把瑶琴膝上弹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题高房山夜山图' AND p.poem_author = '张逢原';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浪淘沙 海上初秋快晴，楼望', '何振岱', '清代', '楼阁上初阳。净绝秋光。晨清万影辨微茫。一叶飞过瞒不得，如蝶飘黄。\n\n节候已新凉。倚槛天长。神游五岳梦三湘。却展道书成晏坐，小炷炉香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浪淘沙 海上初秋快晴，楼望' AND p.poem_author = '何振岱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酒泉子', '温庭筠', '唐代', '花映柳条，闲向绿萍池上。凭栏干，窥细浪，雨萧萧¤ \n 近来音信两疏索，洞房空寂寞。掩银屏，垂翠箔，度春宵。 \n 日映纱窗，金鸭小屏山碧。故乡春，烟霭隔，背兰釭¤ \n 宿妆惆怅倚高阁，千里云影薄。草初齐，花又落，燕双飞。 \n 楚女不归，楼枕小河春水。月孤明，风又起，杏花稀¤ \n 玉钗斜篸云鬟重，裙上金缕凤。八行书，千里梦，雁南飞。 \n 罗带惹香，犹系别时红豆。泪痕新，金缕旧，断离肠¤ \n 一双娇燕语雕梁，还是去年时节。绿杨浓，芳草歇， \n 柳花狂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酒泉子' AND p.poem_author = '温庭筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('双调忆江南', '梁羽生', '当代', '秋夜静，独自对残灯。\n啼笑非非谁识我，坐行梦梦皆缘君，何所慰消沉。\n风卷雨，雨复卷侬心。\n心似欲随风雨去，茫茫大海任浮沉。\n无爱亦无憎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '双调忆江南' AND p.poem_author = '梁羽生';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵杂兴二百首 其七十四', '苏泂', '宋代', '缚屋牵牛旋旋归，淮边绿野尽耕犁。弓刀武备何曾识，只是当初田舍儿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵杂兴二百首 其七十四' AND p.poem_author = '苏泂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题盛懋秋林萧散图', '弘历', '清代', '佳荫之下铺芳蘅，是何处兮曰蓬瀛。青鸾白鹤两不藉，飘飘旬五御风行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题盛懋秋林萧散图' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红·柬开周', '陆震', '清代', '屋漏床床，是杜老、当年诗句。却今日、任生屋内，也无乾处。\n\n四壁篱颓浑不葺，三重茅去凭谁补。恼天公、昨夜又飘摇，桃花雨。\n\n或栖止，山中树。或岸上，牵船住。算古来如此，君无太苦。\n\n海现晴虹当户挂，瓮馀浊酒呼儿取。试寻他、王谢旧时门，馀荒土。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红·柬开周' AND p.poem_author = '陆震';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庆魏伯广寿', '徐庸', '明代', '中吴山水多清淑，峰峦涌翠波浮绿。虞山琴川尤出奇，种秀山川有名族。\n\n魏君伯广号慎轩，古貌古心异流俗。襟怀夷坦绝崖岸，德能润身富润屋。\n\n有田千顷阅人耕，有书五车教子读。稻禾𥝧稏连三区，云子岁收仓廪足。\n\n礼贤下士存恭敬，恤匮赒穷罄金玉。声誉馨香比蕙兰，岁寒操守侔松竹。\n\n筑堤捍水功尤大，郡侯赞美诗盈轴。高风如此追古贤，青史无惭为褒录。\n\n年推甲子月仲冬，蓂留五荚清传馥。画堂开宴庆生申，洞天正喜蟠桃熟。\n\n九叠光浮翡翠屏，连枝绣展芙蓉褥。碧落行云遏不飞，朱唇皓齿歌新曲。\n\n兽□清燃龙脑香，鸾刀细切驼峰肉。高人硕士总称贤，衣冠济济来相续。\n\n臞樵先生仙之徒，丘壑峥嵘饱胸腹。蓬莱阆苑入挥洒，万里扶桑连若木。\n\n金银宫阙驻群仙，半衣冰绡半霞縠。瑞鸟珍禽鸣古涧，紫芝瑶草蕃深谷。\n\n莲叶长巢不老龙，琪花乱点长生鹿。丹青神妙夺造化，意匠经营成大辐。\n\n玉堂学士松雪翁，伟世高名得追逐。图成装潢为持献，按图邀我题诗祝。\n\n我闻老子出关图，千载传誇人刮目。古今虽异事乃同，若合符节犹式谷。\n\n紫霞杯香进春酒，膝前戏舞斑斓服。八千寿算比庄椿，健步从容跻百福。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庆魏伯广寿' AND p.poem_author = '徐庸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('安乡县西晚泊', '范成大', '宋代', '水阔鸟乌倦，墟寒童仆饥。\n一湾村县过，百折暮江迟。\n晓梦孤灯见，春阴病骨知。\n简书宁不畏，旅力奈先疲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '安乡县西晚泊' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('云门大师赞', '释智遇', '宋代', '掉发睦州，脱赚灵树。\n赤体露金风，清波无透路。\n阿师脚跛不能行，休对乾峰南岳去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '云门大师赞' AND p.poem_author = '释智遇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('仙塘', '利登', '宋代', '一椽自著此山幽，芦苇萧萧绕屋头。\n野老屡来询姓字，社人相约赛春秋。\n寒山此去无飞燕，白水初传有远鸥。\n病起偶然成独往，冷烟斜照使人愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '仙塘' AND p.poem_author = '利登';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观物吟', '邵雍', '宋代', '时有代谢，物有枯荣。\n人有衰盛，事有废兴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观物吟' AND p.poem_author = '邵雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵刘明远移家', '徐玑', '宋代', '躬耕儒者事，甘苦自能便。\n叩角吟山际，休锄坐竹边。\n长年多涉沥，丰岁少尤煎。\n一一旧所好，知君能弃捐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵刘明远移家' AND p.poem_author = '徐玑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨中读韩致光诗偶池上鹿葱盛开因效其体 其一', '周紫芝', '宋代', '曲栏干外水平阶，池上朱扉绕翠苔。燕子飞来人不到，鹿葱花在雨中开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨中读韩致光诗偶池上鹿葱盛开因效其体 其一' AND p.poem_author = '周紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮', '朱庸斋', '近代', '人人共说东风好。人人共向东风道。花胜去年红。定教年更丰。\n\n綵狮腾旭日。瑞气呈阡陌。何以报春阳。稻云连社香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮' AND p.poem_author = '朱庸斋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('将次项城阻风舟不能进', '梅尧臣', '宋代', '逆水寒风急，轻舟晚不前。\n因来泊古渡，聊且上平田。\n草软行方稳，鹑惊去瞥然。\n却寻孤岸远，吹帻乱华颠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将次项城阻风舟不能进' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐 七夕口占', '梁启勋', '清代', '巧如可乞。更有何人拙。垂地银河自清澈。亘古不闻呜咽。\n\n纱窗已入新凉。流萤明灭低昂。庭树远连天阔，双星徐度红墙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐 七夕口占' AND p.poem_author = '梁启勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄山中诸子', '成鹫', '明代', '山缘渐密世缘疏，敢望良朋远寄书。地僻不知曾有雁，水清宁复叹无鱼。\n\n梦回冷榻闻钟后，僧老空林落叶初。一盏孤灯伴禅定，岂知人世有乘除。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄山中诸子' AND p.poem_author = '成鹫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送吴辩叔知巩县', '梅尧臣', '宋代', '言为西邑宰，本是洛阳人。\n送馹往归魏，迎车来入秦。\n山川成巩固，陵庙壮威神。\n好学河阳政，栽花作县春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送吴辩叔知巩县' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋浦登舟，阻风泊池口', '杨万里', '宋代', '牛眼化蝶化未成，梦中澒洞发大声。\n军鼙雷鼓百千面，援桴齐下作一鸣。\n起来推窗无一物，海潮打入齐山窟。\n数洲翻覆相荡摩，四山动摇皆突兀。\n钱塘潮来声惊天，金陵潮来声寂然。\n此去金陵一千里，郡得潮声来到此。\n长年三老笑复嘲，云是波声不是潮。\n清溪波头高过屋，大江波头发日毂。\n清溪去江一步地，大江可望不可至。\n北风向晚动地来，跳出银峰万万堆。\n侬船莫管行不得，且看银峰永今夕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋浦登舟，阻风泊池口' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠朱象先处士十韵', '刘季孙', '宋代', '前身应画师，摩诘初自许。咫尺论万里，宰也少陵与。\n\n朱翁趣岂凡，山水忘羁旅。晴窗布风云，夏木回炎暑。\n\n坐来摧虎头，兴尽秃鸡矩。况其尘外怀，出门皆胜侣。\n\n一画不轻付，俗子吾避汝。能令希世迹，千载得处所。\n\n斯人定何如，箧有东坡语。画以适其意，能文不求举。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠朱象先处士十韵' AND p.poem_author = '刘季孙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上丁斋宿', '张孝祥', '宋代', '青衿陪祀忆初年，老矣斋居重慨然。俎豆不知鹅鹳事，牲牢空荐犬羊膻。\n\n北来被发车连野，东去乘槎浪接天。汲汲两宫常旰食，受膰归去泪如川。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上丁斋宿' AND p.poem_author = '张孝祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏萤', '于季子', '唐代', '卉草诚幽贱，枯朽绝因依。忽逢借羽翼，不觉生光辉。 \n 直念恩华重，长嗟报效微。方思助日月，为许愿曾飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏萤' AND p.poem_author = '于季子';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('览先祖太傅留题国清寺继和', '赵抃', '宋代', '得谢殊狂客，无言愧净名。心观潭月白，梵听海潮声。\n\n晓色开华顶，秋晖照赤城。公诗播人口，冰玉未为清。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '览先祖太傅留题国清寺继和' AND p.poem_author = '赵抃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游梅冈和石亭韵', '王韦', '明代', '将军埋甲处，登望一凄然。江映杯光动，岚消剑气悬。\n\n郊坰摧草树，时序变风烟。惟有翻经阁，还开落照边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游梅冈和石亭韵' AND p.poem_author = '王韦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书与士瞻上人十首 其八', '仇远', '宋代', '倦游懒著小乌巾，短发丝丝雪满簪。信手拈书聊慰眼，转头忘事太无心。\n\n笑他杜老频看镜，爱我昭文不鼓琴。喜有山林方外友，时携佳纸索新吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书与士瞻上人十首 其八' AND p.poem_author = '仇远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庐陵乐府十首 其二', '郭祥正', '宋代', '鸿雁殊未来，思君一弹琴。泠泠别鹤语，折尽幽兰心。\n\n蛛丝漫相续，难系骅骝足。白日无时停，云鬓宁长绿。\n\n年华要不老，不若丹青好。对之虽无言，犹胜种萱草。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庐陵乐府十首 其二' AND p.poem_author = '郭祥正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('醉石', '史尧弼', '宋代', '有时醉浊清，随意眠小大。\n何须酒池中，始了一生课。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '醉石' AND p.poem_author = '史尧弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题喻景山大飞书房', '陈宓', '宋代', '仙溪七十里，半世祇闻名。一日见山色，千年怀友情。\n\n古匏浮美醁，清水照尘缨。霜月亭亭白，连床语到明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题喻景山大飞书房' AND p.poem_author = '陈宓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠吕希曾', '王佐', '元代', '十里长堤旧筑沙，桥林犹自拥高牙。九霄鸡犬神仙宅，七叶貂蝉宰相家。\n\n徐榻清风挥麈尾，谢庭春雨长兰芽。辉煌不独金符重，紫诰千函灿墨花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠吕希曾' AND p.poem_author = '王佐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂诗 其十七', '李复', '宋代', '权利为祸根，苟合非纯士。嗟哉凭轼生，行见烹齐市。\n\n晴鸠不逐妇，猛虎不食子。魏国将乐羊，齐人疑吴起。\n\n凶险甚鸟兽，妻子自烹死。呜呼天壤间，亲无骨肉比。\n\n残毒就功名，于君安可恃。中山昔置相，尝取放麑翁。\n\n异类犹有恩，事君必致忠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂诗 其十七' AND p.poem_author = '李复';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湖山堂再修仅有', '方回', '宋代', '飞鸟穿堂柱半欹，春晴犹不似春时。\n上梁文记临邛魏，天目洪家却立碑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湖山堂再修仅有' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次瑶攴石望鞋山', '陈谟', '元代', '舟移瑶攴下，遥望石如屣。舟人云是大姑娘，一掬弓弯曾堕此。\n\n吾闻古有巨人迹，姜嫄履之生后稷，神灵奇踪此其一。\n\n水仙罗袜凌波轻，安取盘囷如此石。又闻大禹乘四载，浚川来经彭蠡滨，遗此表徵千万春。\n\n江神呵禁畴敢登，偶一践踏风雷惊。导河自昆崙，砥柱碣石壮本根。\n\n瞿塘滟滪堆，舟航不敢争飞奔。长江钜石天意存，此其小者疑屣云。\n\n君不见小姑健儿女将军，剑峰屹立当海门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次瑶攴石望鞋山' AND p.poem_author = '陈谟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('仙桥渡', '郑一统', '明代', '金碧丛中芳未歇，天风淅淅东井冽。道人一醉紫霞归，双眼玲珑弄秋月。\n\n双眼玲珑弄秋月，渔声何处施罛濊。便将野渡作星槎，直泛银河访机织。\n\n一水盈盈异悲悦，我欲万丈驾云梁，无劳太史虚饶舌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '仙桥渡' AND p.poem_author = '郑一统';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题梅仙坛', '刘霆午', '宋代', '吏隐清风几百年，长松脩竹满坛前。汉皇若听三书谏，未必先生便肯仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题梅仙坛' AND p.poem_author = '刘霆午';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮·秋堂积雨新凉入', '郭应祥', '宋代', '秋堂积雨新凉入。今宵雅乘鹏飞集。劲翮会高风。功名欬唾中。笔头元有准。快写平生蕴。何日捷书来。重阳把一杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮·秋堂积雨新凉入' AND p.poem_author = '郭应祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归怀', '区大相', '明代', '已约还山伴，春深定采芝。如何拂衣日，又过秋风期。\n\n疲马倦长路，栖禽思故枝。因声寄松桂，莫笑我归迟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归怀' AND p.poem_author = '区大相';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('季夏仝李郁林卢省潜卢静虚刘建侯郊外泛舟归饮贾襄一书舍', '申佳允', '明代', '乘兴飘摇一叶舟，阆仙许我过斋头。青毡趺坐翻书帙，白眼斜看醉酒瓯。\n\n树隐蝉声方噪暑，风生羽扇忽惊秋。归来不尽登临意，何日联翩续壮游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '季夏仝李郁林卢省潜卢静虚刘建侯郊外泛舟归饮贾襄一书舍' AND p.poem_author = '申佳允';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('邸中种竹十二首 其六', '何吾驺', '明代', '静落叶有声，晓吹竿作响。寄书订七贤，让我称林长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '邸中种竹十二首 其六' AND p.poem_author = '何吾驺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('木棉花歌 其五', '李云龙', '明代', '长林风起絮飞多，昨日朱颜鬓已皤。尽去尊前舞红袖，好风容易醉中过。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '木棉花歌 其五' AND p.poem_author = '李云龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '鲜于能', '宋代', '金山一拳石，石髻出溟涨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '鲜于能';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜算子·张在初观察席上分咏，余得蒲草', '潘飞声', '清代', '嫩绿点云根，雨后涵春气。戏谑金钱作小名，不是寒窗味。\n\n短剑剪微风，砚北闻香细。待洗寒泉白石盘，供养倪高士。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜算子·张在初观察席上分咏，余得蒲草' AND p.poem_author = '潘飞声';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南郊大礼诗', '王禹偁', '宋代', '彩城残月带微霜，版奏中严夜未央。\n三献欲终侵曙色，百神齐下散天香。\n珠旒微乱埙篪韵，迤燎轻笼剑佩光。\n此夕商山对何物，猿啼鸟哭树苍苍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南郊大礼诗' AND p.poem_author = '王禹偁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清思诗五首 其一', '江淹', '南北朝', '赵后未至丽，阴妃非美极。情理傥可论，形有焉足识。\n\n帝女在河洲，晦映西海侧。阴阳无定光，杂错千万色。\n\n终岁如琼草，红华长翕赩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清思诗五首 其一' AND p.poem_author = '江淹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送钤辖馆使王公', '姚涣', '宋代', '家传勋力世能贤，四载坤维领帅权。南诏酋豪弥款附，西州士庶赖蕃宣。\n\n输忠感慨由诚府，接下恩勤自意筌。月夕过从多命席，花时酬唱旋成编。\n\n雅歌馀暇军容肃，陟状升闻帝愿延。驰驿遽趋三召节，执圭俄觐九重天。\n\n汉廷仪卫咸祗若，蜀郡朋僚共黯然。赐封定应留晷刻，畴庸当便进班联。\n\n圣神倚注期蕃锡，宥密崇高待九迁。下客尘劳遇知己，愿言攀附跂英躔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送钤辖馆使王公' AND p.poem_author = '姚涣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大衍易吟四十首', '方回', '宋代', '易乃一量秤，铢铢分重轻。\n百千亿万事，义理是权衡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大衍易吟四十首' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('先父生日将归而雨', '卢青山', '当代', '天宇幂兮雨缤纷，飙风激兮搜丛林。瞻六合兮唯阴冥，惨吾怀兮阻吾程。\n\n言将归兮福寿阴，陵如鼓兮渊渚清。环屋竹兮绕渠衡，苔缀壁兮脊茅生。\n\n人虽去兮故物存，嗟秽草兮衣孤坟。望不得见兮徒辗转于吾心，仰而问兮天何以不仁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '先父生日将归而雨' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游崆峒四绝 其四', '赵秉文', '金朝', '万松声里暮涛寒，尽在参云一望间。只欠悬流二千尺，天风吹下翠屏山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游崆峒四绝 其四' AND p.poem_author = '赵秉文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄少仪弟', '秦观', '宋代', '一隔音尘月屡迁，忽收来问涕潸然。\n栖迟册府吾如昨，流落江村汝可怜。\n梦里漫成池草句，愁来空诵棣华篇。\n卑飞暂尔无多恨，会有高风送上天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄少仪弟' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晓雨', '陆游', '宋代', '东风吹雨送残春，冉冉年光次第新。\n君看枝头如许绿，争教桃李不成尘！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晓雨' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花　秋夜三章 其三', '卢青山', '当代', '我有魂兮离体起，独舞清秋，明月光华里。明月为裳光洗洗，江河为奏弦千里。\n\n地狱天堂皆幻拟，嗟我魂兮，毕竟归何地？生死山川长袖底，茫茫明月光无已。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花　秋夜三章 其三' AND p.poem_author = '卢青山';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢王拾遗见访兼寄篇什', '齐己', '唐代', '竹里安禅处，生涯一印灰。经年乞食过，昨日谏臣来。 \n 愧把黄梅偈，曾酬白雪才。因令识鸟迹，重叠在苍苔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢王拾遗见访兼寄篇什' AND p.poem_author = '齐己';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题幽鸟', '张宁', '明代', '上苑花如锦，雕笼翡翠新。脩篁邻野树，啼鸟一般春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题幽鸟' AND p.poem_author = '张宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('史翁七十诗二首 其二', '尹台', '明代', '玉阳新阁绕千峦，秀挹仙霞卧可餐。紫壁度云移锦绣，青芝过雨长琅玕。\n\n金房定启千函秘，玉灶应成九转丹。黄发后车还拟载，钓璜入卜迓西磻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '史翁七十诗二首 其二' AND p.poem_author = '尹台';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋兴和郑希大 其二', '黄衷', '明代', '空庭读易夜如年，秋潦仍荒种朮田。海鹤临霞终野逸，山鸡照水自华鲜。\n\n直修古道通延閤，欲趁回潮解钓船。君若有期先讯问，好怀多是菊花边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋兴和郑希大 其二' AND p.poem_author = '黄衷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('近吟', '卫宗武', '宋代', '晚年打透利名关，十载尤欣老得閒。\n拟约绮园为隐侣，却愁无处觅商山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '近吟' AND p.poem_author = '卫宗武';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日偶成', '萨都剌', '元代', '踏马归来过早春，空阶已见草如茵。东风吹绿青溪柳，马上轻寒不著人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日偶成' AND p.poem_author = '萨都剌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荒村', '韩上桂', '明代', '荒村馀落照，岛屿澹微明。病马嘶不得，哀蝉无限声。\n\n桑麻时雨过，橘柚绿烟萦。物理经行得，因之去住轻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荒村' AND p.poem_author = '韩上桂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天 晋城道中二阕 其一', '傅义', '当代', '不畏风尘白发侵，飞车横野复扪参。纵穿地脉几无间，才见天光忽又阴。\n\n山络绎，洞幽深。崖危径窄气萧森。凭栏偏爱观奇险，履险如夷最称心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天 晋城道中二阕 其一' AND p.poem_author = '傅义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南沙宿知微房奉忆', '邵宝', '明代', '信宿山中未得陪，老僧独为供茶杯。一时欠事庭无月，五里馀情野有梅。\n\n文会又从今日起，书评还待后人来。卧云字在南岩石，好谓知微莫遣苔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南沙宿知微房奉忆' AND p.poem_author = '邵宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('均州乐二首', '器封', '明代', '临江贾人黄篾船，涴涴青油篙刺天。\n下船上岸买鱼酒，二八当垆夸数钱。\n烟萦罗幌春将晚，白日衔山不思返。\n珠帘红袖影傞俄，楼上明妆楼下波。\n沙棠树上娇春鸟，月出平江齐唱歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '均州乐二首' AND p.poem_author = '器封';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谨步陈唯生先生花甲寿原韵四章 其三', '薛昂若', '清代', '杖藜随处乐盘桓，更作风流王谢看。笔下生花堪并李，才高能识尚思韩。\n\n是翁矍铄多诗兴，惟颔仪容应问安。共向颍川开盛宴，琼筵醉酒却春寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谨步陈唯生先生花甲寿原韵四章 其三' AND p.poem_author = '薛昂若';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自高梁桥泛舟过万寿寺至昆明湖之作', '弘历', '清代', '夹岸轻笼绿柳阴，进舟川路霁烟沈。有时送响新蝉急，无碍沿洄涨水深。\n\n古寺小年付僧领，西山秀色待人寻。近耽湖上风光好，雨后空明尽畅吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自高梁桥泛舟过万寿寺至昆明湖之作' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('叠前游山韵示诸生兼答介溪太宰', '湛若水', '明代', '暮春暮矣春事微，看花时复惜春晖。明年未卜今年健，十度相期九度违。\n\n山中闭户梅千发，都下移居燕一飞。自是明时久贪恋，拂衣争得赋来归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '叠前游山韵示诸生兼答介溪太宰' AND p.poem_author = '湛若水';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清明陪祀西陵二首 其二', '程敏政', '明代', '已将微雨湿尘缨，更息寒风待礼成。万口共誇天气好，四山惟见月华明。\n\n寝园夜下更声促，辇道沙乾马足轻。一任朝陵常属我，新诗题遍永安城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清明陪祀西陵二首 其二' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南歌子·灵腑诸尘净', '王吉昌', '元代', '灵腑诸尘净，民山一气生。三田昼夜铁牛耕。鼓润风雷，金井长琼英。火力凭加减，冰肌应候烹。圆明方寸鬼神惊。悦畅仙童，饵讫恣飞行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南歌子·灵腑诸尘净' AND p.poem_author = '王吉昌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐 新都道中', '唐圭璋', '近代', '郊原平旷。竹树千家障。极目不逢山色朗。满路独轮车响。\n\n渐行渐远尘侵。归鸦密点寒林。向晚无人野渡，落霞红透波心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐 新都道中' AND p.poem_author = '唐圭璋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙 其十二 同纫兰四妹作，即呈雪兰大姊、蘅芳、蓉岑两妹，并怀顾羽素表妹，无锡王畹兰五妹', '杨芸', '清代', '记得酿寒过二月，更阑石叶香焦。闲将韵字带愁挑。\n\n寄情凭绿绮，缄怨付红绡。\n\n拾翠寻香怀旧侣，汀洲何处兰苕。天青海碧路迢迢。\n\n不应耽慧业，此恨几时消。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙 其十二 同纫兰四妹作，即呈雪兰大姊、蘅芳、蓉岑两妹，并怀顾羽素表妹，无锡王畹兰五妹' AND p.poem_author = '杨芸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别吴而待 其二', '黎民表', '明代', '恋阙心仍在，还家路不迷。凄凉吊古意，疲马入青齐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别吴而待 其二' AND p.poem_author = '黎民表';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题自怜待月湘帘下银烛烟多怕点镫诗意便面 其一', '锁瑞芝', '清代', '天风飒飒起银河，但觉帘阴次第过。曾记梨花时节雨，西窗剪烛夜寒多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题自怜待月湘帘下银烛烟多怕点镫诗意便面 其一' AND p.poem_author = '锁瑞芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九溪十八涧', '周文璞', '宋代', '九溪十八涧，冷见帝青苔。洗足僧书石，临流客放杯。\n\n案头松叶响，身畔野花开。百六辞歌吹，清游始一回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九溪十八涧' AND p.poem_author = '周文璞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汉宫春（三和）', '刘克庄', '宋代', '酷爱名花，本不贪妖艳，惟赏幽姿。乌台旧案累汝，牵惹随司。冰层雪积，独伊家、点绛凝脂。应冷笑，海棠醉睡，牡丹未免丰肌。 \n 舞殿歌台此际，各新涂妆额，别画宫眉。那知有人淡泊，不识虫儿。春莺去也，玉参差、分付谁吹。空传得，暗香疏影，琐窗卷了还披。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汉宫春（三和）' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('双桥西溪昆仲别号', '张天赋', '明代', '溪有西兮便有东，桥非双建总难通。化龙川上桃花浪，吹面桥边杨柳风。\n\n莫讶齐驱无等第，应知济美共成功。月明鸡唱霜蹄早，驰骋天衢六合空。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '双桥西溪昆仲别号' AND p.poem_author = '张天赋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏怀 其十三', '孙元衡', '清代', '修饰乃窥镜，容辉讵自然。托意匪膏沐，飞蓬良亦妍。\n\n黄鹄振六翮，素衣仪九天。骐骥释珠络，莽苍生云烟。\n\n如何性情事，与俗相因缘。坟典彰媚好，冠冕文拘挛。\n\n守真谅不察，脉脉向婵娟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏怀 其十三' AND p.poem_author = '孙元衡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送少年禅师二首', '贯休', '唐代', '秀眉青目树花衣，一钵随缘智不知。 \n 佛与轮王嫌不作，世间刚有个痴儿。 \n 万水千山一鹤飞，岂愁游子暮何之。 \n 古今此著无人会，王积新输更不疑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送少年禅师二首' AND p.poem_author = '贯休';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白鸠讴', '曹植', '魏晋', '班班者鸠。\n爰素其质。\n昔翔殷邦。\n今为魏出。\n朱目丹趾。\n灵姿诡类。\n载飞载鸣。\n彰我皇懿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白鸠讴' AND p.poem_author = '曹植';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('点绛唇 题辅之叔“醉墨图”', '孙云凤', '清代', '座上春风，卷帘炉篆飘窗牖。娱清昼。墨花香透。滋味浓于酒。\n\n满纸淋漓，一试挥毫手。披图久。砚池波皱。腕底烟云走。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '点绛唇 题辅之叔“醉墨图”' AND p.poem_author = '孙云凤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏日平居奉寄崔伯易兼简朱元弼 其一', '王令', '宋代', '天风变春和，昼日差夏永。门阑闭无事，燕雀去益静。\n\n纷翻诗书帙，弃散懒收整。时来就枕卧，复可取窥省。\n\n心恬逐物闲，迹阔与世屏。鲜鲜南山暖，秀色在脩岭。\n\n苟嫌安坐慵，还可远游骋。自缘智能薄，反得闲暇幸。\n\n交朋久相远，疏懒欲谁警。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏日平居奉寄崔伯易兼简朱元弼 其一' AND p.poem_author = '王令';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七月十日大雨晓霁登碧落堂', '杨万里', '宋代', '青天送归云，整如劳还师。颜行有喜色，厮役争奔随。\n\n晨曦映疏雨，宝灯贯银丝。落面何曾湿，洒空不胜微。\n\n老夫锐登山，半岭惊欲归。仰视得奇观，徙倚为久之。\n\n谁言李成巧，此画天下稀。却登碧落堂，四面天风吹。\n\n葛制忍秋寒，前夕酷暑时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七月十日大雨晓霁登碧落堂' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('太常引', '宋先生', '宋代', '金丹只在自身中。真水火、炼成功。因遇吕仙公。识返本、还元祖宗。阳全阴尽，神光现处，认得自真容。名姓列仙宫。已跳出、乾坤世笼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '太常引' AND p.poem_author = '宋先生';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('采桑子·年年此夕东城见', '晏几道', '宋代', '年年此夕东城见，\n欢意匆匆。\n明日还重，\n却在楼台缥缈中。\n\n垂螺拂黛清歌女，\n曾唱相逢。\n秋月春风，\n醉枕香衾一岁同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '采桑子·年年此夕东城见' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵莘老初至汤泉', '秦观', '宋代', '夹路山重复，参天树老苍。一区成小市，数埒引温汤。\n\n洗沐同幽客，餔餐就梵坊。未输朝市子，斗酒得西凉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵莘老初至汤泉' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵和王文明绝句漫兴十八首 其七', '刘基', '元代', '天边云气来须女，湖上轻雷起少男。一阵微凉疏雨过，满池莲蕊绿如簪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵和王文明绝句漫兴十八首 其七' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏春笋', '杜甫', '唐代', '无数春笋满林生，柴门密掩断行人。\n会须上番看成竹，客至从嗔不出迎。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏春笋' AND p.poem_author = '杜甫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玲珑四犯 题画', '饶宗颐', '近代', '稊柳搴帘，有绣幕丛花，围住春艳。欲倩东君，貌出镜奁妆脸。\n\n还恐岸曲蘋风，又忍把、嫩条吹乱。更酿愁雾敛星换。\n\n前事几回曾见。\n\n画塘谁把鸳鸯荐。望疏窗、蕙葱兰茜。长绳试系西趖日，佳气舒心眼。\n\n才见打桨燕归，剪浪蕊，寒波万点。正拂云欲坠，风卷叶、频惊散。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玲珑四犯 题画' AND p.poem_author = '饶宗颐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿李阁老先生', '傅圭', '明代', '绮席春深泛紫霞，分明相府是仙家。调元正捧云中日，结实还看海上花。\n\n千载文光瞻北斗，九重恩渥叠黄麻。疏慵幸接龙门早，一曲南飞思未涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿李阁老先生' AND p.poem_author = '傅圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('平坡', '何景明', '明代', '晚眺平坡上，苍茫万壑前。一僧行树杪，诸客到寒天。\n\n险骇将崩石，清怜乍坼泉。翠华公主塔，缥缈碧山巅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '平坡' AND p.poem_author = '何景明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游宋皇陵二首 其一', '陶益', '明代', '郊原望望皆禾黍，寝庙萧萧哭杜宇。藓碑读罢俯閒阶，月明初照青枫树。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游宋皇陵二首 其一' AND p.poem_author = '陶益';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南歌子 其五', '程滨', '当代', '点雨淋头乍，游丝惹面频。珍珠额上自鳞沦。渐渐化为新泪渥檀唇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南歌子 其五' AND p.poem_author = '程滨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('癸酉九秋下浣菊宴赠诗十四首 其十一 赠周姻世长雪昆', '祝廷华', '清代', '江上新诗友，城西老布衣。订交能略分，共话每投机。\n\n品隽情尤介，文豪笔欲飞。濂溪遗泽远，道学懔尼微。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '癸酉九秋下浣菊宴赠诗十四首 其十一 赠周姻世长雪昆' AND p.poem_author = '祝廷华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('以坡公君如大江日千里我如此水千山底为韵作', '赵蕃', '宋代', '游从二年中，离阔三百日。\n政自迹如疏，不妨心故密。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '以坡公君如大江日千里我如此水千山底为韵作' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹林书屋', '张泰', '明代', '竹里巢栖隐，萧然君子居。清风蒋生径，古意邺侯书。\n\n凤宿寒灯外，芸香春笋馀。惟应过三益，著论辟玄虚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹林书屋' AND p.poem_author = '张泰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠谈阴阳者二首 其一', '萧立之', '宋代', '葬书丑唾窭与贱，只为人间觅贵饶。试问胡椒八百斛，何如陋巷一箪瓢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠谈阴阳者二首 其一' AND p.poem_author = '萧立之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿陈唯生', '祝书根', '清代', '凭阶鞠𦜕敞华筵，虎瑟龙笙福禄骈。比算桑增株八百，曳珠客进履三千。\n\n充闾瑞气惊臣朔，累代清芬媲孟坚。人世期颐刚有半，难兄难弟此称贤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿陈唯生' AND p.poem_author = '祝书根';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五月九日甲子至月望庚午大雨水不已十首 其二', '方回', '宋代', '波浪冒原田，群鱼不自全。返常真足怪，行险绝堪怜。\n\n骤作乘时快，遄成失势颠。儿童拾鳗鳝，争著柳枝穿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五月九日甲子至月望庚午大雨水不已十首 其二' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和周公予呈向宰', '王庭圭', '宋代', '夜闻急雨洗氛埃，庆泽仍从天上回。寰海自应遵诏旨，管弦何用费诗催。\n\n东风渐著金丝柳，和气潜飞玉琯灰。遥想慈宁动新乐，禁门清晓拂云开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和周公予呈向宰' AND p.poem_author = '王庭圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次东原先生与其甥魏公美画诗韵', '屠滽', '明代', '苍苍笔力似荆关，白发图书老不闲。未许羊昙乞西墅，画中分与旧溪山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次东原先生与其甥魏公美画诗韵' AND p.poem_author = '屠滽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('海藏楼杂诗 其七', '郑孝胥', '清代', '幼时学为文，独喜柳子厚。《断刑》与《时令》，熟读常在口。\n\n近人尚桐城，其论深抑柳。阳湖实支派，相袭亦已久。\n\n柳文彼所轻，学柳更何有。奇人吾炜士，爱我忘其丑。\n\n咨嗟愧室辞，沈至信高手。子亦毗陵宗，胡不惮众诟？\n\n损名勿轻言，意子适被酒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '海藏楼杂诗 其七' AND p.poem_author = '郑孝胥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('使粤道出益阳雨后口占 其三', '黎民衷', '明代', '久客萧然万虑轻，殊方遥指使星明。山头杜宇声何急，翻动江南行乐情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '使粤道出益阳雨后口占 其三' AND p.poem_author = '黎民衷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梦中作游山绝句', '陆游', '宋代', '寺楼已断暮钟声，照佛琉璃一点明。\n不道溪深待船久，老僧惊怪太迟生。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梦中作游山绝句' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一犁春雨图', '何异', '宋代', '负郭先畴二顷余，饱看雨后著耕夫。\n软红尘里家山梦，却就君家阅画图。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '一犁春雨图' AND p.poem_author = '何异';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绵州', '汪元量', '宋代', '绵州八月秋气深，芙蓉溪上花阴阴。\n使君唤船复载酒，书生快意仍长吟。\n击鼓吹笙欢客饮，脱巾露发看日沈。\n归来不知其所往，但见月高松树林。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绵州' AND p.poem_author = '汪元量';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和氅云见赠', '易顺鼎', '清代', '诗篇李峤真才子，飞鹤横汾感慨多。闽海泪枯唐日月，燕云心死宋山河。\n\n赤眉故国通天表，青眼高楼斫地歌。二百馀年应有此，先皇雨露在菁莪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和氅云见赠' AND p.poem_author = '易顺鼎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过卢明府有赠', '高适', '唐代', '良吏不易得，古人今可传。静然本诸己，以此知其贤。 \n 我行挹高风，羡尔兼少年。胸怀豁清夜，史汉如流泉。 \n 明日复行春，逶迤出郊坛。登高见百里，桑野郁芊芊。 \n 时平俯鹊巢，岁熟多人烟。奸猾唯闭户，逃亡归种田。 \n 回轩自郭南，老幼满马前。皆贺蚕农至，而无徭役牵。 \n 君观黎庶心，抚之诚万全。何幸逢大道，愿言烹小鲜。 \n 能奏明廷主，一试武城弦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过卢明府有赠' AND p.poem_author = '高适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('龙游吴宰因劝农过寓居 其一', '范浚', '宋代', '令君剖剧久推贤，人谓贤如百里天。最绩已优恩已洽，讼堂无事日鸣弦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '龙游吴宰因劝农过寓居 其一' AND p.poem_author = '范浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和黄农部尖叉韵 其一', '郑翰谟', '清代', '悄悄羁怀烛影纤，更听诗令戒申严。春风已啜醲膏粥，冬雪初消著水盐。\n\n塞北征辀尘满袖，巷南门幰树捎檐。巴音愧和峨洋曲，虚把瑶琴弄玉尖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和黄农部尖叉韵 其一' AND p.poem_author = '郑翰谟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('代拟无题七首', '钱钟书', '当代', '风里孤蓬不自由，住应无益况难留。\n勿勿得晤先忧别，汲汲为欢转赚愁。\n雪被冰床仍永夜，云阶月地忽新秋。\n此情徐甲凭传语，成骨成灰恐未休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '代拟无题七首' AND p.poem_author = '钱钟书';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送张法曹', '宋祁', '宋代', '驶骑柳枝鞭，春逵望雒廛。\n赋才宾右俊，掾诺府中贤。\n宫楯含樱密，王渠泛醳联。\n胜期资一笑，刑矢措周年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送张法曹' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送刁节推归江南此君辟孙并州幕府府罢遂弃官 其一', '刘攽', '宋代', '长平幕府可张罗，谁见当时宾客多。还有任安如砥柱，故山归卧恣颓波。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送刁节推归江南此君辟孙并州幕府府罢遂弃官 其一' AND p.poem_author = '刘攽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋山行客图', '朱诚泳', '明代', '凉生疏树雨初收，山气沾衣翠欲流。何物骑驴痴老子，摇鞭吟断一天秋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋山行客图' AND p.poem_author = '朱诚泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿迁道中 其二', '张穆', '明代', '小雨霏微野更青，湖田界出亩从横。馌耕健妇仍蓑笠，喜直朝晴又晚晴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿迁道中 其二' AND p.poem_author = '张穆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨坐读史记忆子中兄茆堂已开北渠赋此奉呈三绝 其一', '刘崧', '明代', '中园风雨一茆茨，土壁沾濡叹地卑。昨日开渠北檐下，已通流水过南池。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨坐读史记忆子中兄茆堂已开北渠赋此奉呈三绝 其一' AND p.poem_author = '刘崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和陶渊明饮酒二十首 其九', '方回', '宋代', '高台翳榛棘，荷锸冈路开。振衣陟云端，朗然豁秋怀。\n\n言念半死树，类我晚节乖。风雷劈半腹，叶落禽不栖。\n\n幸不为薪槱，烧之化尘泥。谓可材为琴，于调恐不谐。\n\n醉抱作此感，暝色南北迷。下山不可急，小僮扶我回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和陶渊明饮酒二十首 其九' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('初夏', '王镃', '宋代', '杜鹃啼老万山红，天气于春便不同。\n半壁蕉云收暑雨，一帘絮雪扑晴风。\n燕巢子出雕梁暖，蚕茧蛾生翠箔空。\n闲却香车无采处，欲随簑笠看田翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '初夏' AND p.poem_author = '王镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('安福院二首', '刘敞', '宋代', '溪流婉转树蒙龙，复阁虚廊小径通。\n下马解鞍一长啸，便疑身已出尘中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '安福院二首' AND p.poem_author = '刘敞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吴江夜泊（三首）', '周文', '宋代', '愁人几点泪，不许秋风吹。\n吹入吴江里，江流无尽时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吴江夜泊（三首）' AND p.poem_author = '周文';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵无斁偶作二首', '陈师道', '宋代', '肩耸三峰峻，眉厖八字横。\n玄谈人绝倒，家法句新清。\n八俊先张子，诸公少贾生。\n已传乌鹊喜，欲听鶺鴒声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵无斁偶作二首' AND p.poem_author = '陈师道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('孟享仰瞻圣驾', '邓克中', '宋代', '辇路春风锦绣张，裁红剪绿斗芬芳。黄罗伞底瞻天表，万叠明霞捧太阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '孟享仰瞻圣驾' AND p.poem_author = '邓克中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十三夜叠前韵', '程嘉燧', '明代', '云軿月驾要人收，合着亭台在上头。曳影轩窗含远瀑，行空阿阁俯高秋。\n\n招延风物争人胜，揽驻湖山放月流。何得更言官酝美，世间应笑鹤扬州。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十三夜叠前韵' AND p.poem_author = '程嘉燧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('环佩重来轩为槐塘程文实赋 其二', '唐文凤', '明代', '何年斲就峄阳桐，律吕音谐指下工。相业当时勤燮理，心同虞舜鼓南风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '环佩重来轩为槐塘程文实赋 其二' AND p.poem_author = '唐文凤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卜算子 谒友不遇', '王哲', '元代', '曩者见张公，索写词中信。王哲今朝故故来，甚没个人相近。回首跨清飚，随足云霞趁。却入全真复旧堂，把一点灵明认。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卜算子 谒友不遇' AND p.poem_author = '王哲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鼓浪屿宿陈秋园桐荫楼盖君昆仲奉母起居之所也', '潘受', '近代', '妻课茶经子酒经，梧桐长为荫园庭。夕阳楼接千山叶，大海波环一屿青。\n\n雨后板兴呼鹤去，云间藜杖送鸿冥。维舟来下陈蕃榻，高议金门傥许听。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鼓浪屿宿陈秋园桐荫楼盖君昆仲奉母起居之所也' AND p.poem_author = '潘受';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题立斋天台图 其二', '王柏', '宋代', '出处于人不偶然，当时已报赤城缘。丹青有笔谁能画，圣则堂前月满川。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题立斋天台图 其二' AND p.poem_author = '王柏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高士谦竹为崇安知县金怀赋四首 其二 晴', '陈琏', '明代', '闲歌淇澳步虚庭，一炷炉烟绕翠屏。试写潇湘秋半幅，砚池浮动墨花馨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高士谦竹为崇安知县金怀赋四首 其二 晴' AND p.poem_author = '陈琏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('纪怀，赠李六户曹、崔二十功曹五十韵', '元稹', '唐代', '昔冠诸生首，初因三道征。公卿碧墀会，名姓白麻称。 \n 日月光遥射，烟霄志渐弘。荣班联锦绣，谏纸赐笺藤。 \n 便欲呈肝胆，何言犯股肱。椎埋冲斗剑，消碎莹壶冰。 \n 赤县才分务，青骢已迥乘。因骑度海鹘，拟杀蔽天鹏。 \n 缚虎声空壮，连鳌力未胜。风翻波竟蹙，山压势逾崩。 \n 僇辱徒相困，苍黄性不能。酣歌离岘顶，负气入江陵。 \n 华表当蟾魄，高楼挂玉绳。角声悲掉荡，城影暗棱层。 \n 军幕威容盛，官曹礼数兢。心虽出云鹤，身尚触笼鹰。 \n 竦足良甘分，排衙苦未曾。通名参将校，抵掌见亲朋。 \n 喣沫求涓滴，沧波怯斗升。荒居邻鬼魅，羸马步殑fF. \n 白草堂檐短，黄梅雨气蒸。沾黏经汗席，飐闪尽油灯。 \n 夜怯餐肤蚋，朝烦拂面蝇。过从愁厌贱，专静畏猜仍。 \n 旅寓谁堪托，官联自可凭。甲科崔并骛，柱史李齐升。 \n 共展排空翼，俱遭激远矰.他乡元易感，同病转相矜。 \n 投分多然诺，忘言少爱憎。誓将探肺腑，耻更辨淄渑。 \n 会宿形骸远，论交意气增。一心吞渤澥，戮力拔嵩恒。 \n 语到磨圭角，疑消破弩症。吹嘘期指掌，患难许檐簦。 \n 鎩翮鸾栖棘，藏锋箭在弸。雪中方睹桂，木上莫施罾。 \n 且泛夤沿水，兼过被病僧。有时鞭款段，尽日醉懵僜. \n 蹑屐看秧稻，敲船和采菱。叉鱼江火合，唤客谷神应。 \n 啸傲虽开口，幽忧复满膺。望云鳍拨剌，透匣色腾凌。 \n 每想潢池寇，犹稽赤族惩。夔龙劳算画，貔虎带威棱。 \n 逐鸟忠潜奋，悬旌意远凝。弢弓思彻札，绊骥闷牵縆. \n 运甓调辛苦，闻鸡屡寝兴。闲随人兀兀，梦听鼓冬冬。 \n 班笔行看掷，黄陂莫漫澄。骐驎高阁上，须及壮时登。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '纪怀，赠李六户曹、崔二十功曹五十韵' AND p.poem_author = '元稹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏旱四首', '刘克庄', '宋代', '沟堪揭厉难车水，雨怕讥征不入城。\n沃野燥刚妨种艺，老农歌哭不成声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏旱四首' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('示周道士', '白玉蟾', '宋代', '人行秋色里，诗入画图中。\n笑指白云顶，猿啼第一峰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '示周道士' AND p.poem_author = '白玉蟾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辇下春望', '寇准', '宋代', '独向东门凝目望，园林无处不啼莺。乡心已似杨花乱，归路那堪野草生。\n\n紫陌尽应趋胜地，红尘谁肯受闲名。年来却羡沧江叟，长在湖山听浪声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辇下春望' AND p.poem_author = '寇准';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送同年伊翕庵中丞巡抚云南 其二', '王士禛', '清代', '柏台新命帝亲除，重译西南罢羽书。雒将朱鸢皆内属，越人黄屋竟何如。\n\n赐来天厩飞龙马，行避中丞赤棒车。荒服祇今劳睿虑，要令绝域化耕锄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送同年伊翕庵中丞巡抚云南 其二' AND p.poem_author = '王士禛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('楚余生千里过访乞诗四绝以赠其行 其一', '胡应麟', '明代', '握手新知话未央，狂歌深夜舞鱼肠。兰陵百斛犹堪醉，莫指宜城忆故乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '楚余生千里过访乞诗四绝以赠其行 其一' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('点绛唇（同前）', '晁补之', '宋代', '回雁风微，养花浓淡天容好。似春知道。吉梦佳辰到。 \n 共乐春台，携手蓬莱小。同倾祷。愿春不老。岁岁寻芳草。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '点绛唇（同前）' AND p.poem_author = '晁补之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿乔平章三首', '程公许', '宋代', '屋老当奈何，风雨撼四壁。\n主公志细营。所赖有匠石。\n度材林薮幽，计土帑廥积。\n心思妙规制，指授契绳尺。\n逮其万间具，夫岂一人力。\n柱天纪元功，眉寿永无极。\n周宣当中兴，拜手歌考室。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿乔平章三首' AND p.poem_author = '程公许';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西历元日观西人操兵', '陈宝琛', '清代', '晓月尚挂户，趣起观操兵。千骑空市出，铠仗初阳明。\n\n今日西元日，岁例谁实程？整旅将司令，大豪以众并。\n\n亦如赴敌时，捆载随之行。隆隆台炮作，枪队连珠鸣。\n\n乐止忽雷动，欢呼群贺正。卫民国所事，众志宁非城？\n\n尚武乃有备，勖哉吾侨氓！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西历元日观西人操兵' AND p.poem_author = '陈宝琛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人第二体', '齐景云', '明代', '双涡红晕檀霞满。钿镜横波远。宿妆无奈是春前。\n\n刘郎洞口谢娘船。思无边。\n\n鹌鹑啄破赪桐叶。云掩圆蟾截。小楼回首绿烟迷。\n\n微风半夜揭珠帏。认郎归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人第二体' AND p.poem_author = '齐景云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('点绛唇', '傅熊湘', '清代', '翠歇红销，高楼尽日伤凝睇。云山无际。天远迷烟水。\n\n屠狗无惊，谁识英雄意。成何计。宝刀空厉。掷向西风里。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '点绛唇' AND p.poem_author = '傅熊湘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题金廷标写意秋英十八种 其十二 翠菊', '弘历', '清代', '蓓蕾初舒翡翠英，绿蕉叶衬似铺琼。佛螺拟议非唐突，物物毗卢顶上行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题金廷标写意秋英十八种 其十二 翠菊' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蜀中寄李宗易宫论', '王廷相', '明代', '驱车西川道，幽胜一何偏。江源下裔徼，峡势蹴高天。\n\n我游形神适，宛宛飞云仙。鸣琴答山水，志兴良可宣。\n\n岁晏思故交，道拙怀高贤。君从九霄居，阿阁华景悬。\n\n养素回沕穆，陈力扶危颠。十载隔山海，宿心念鹓鸾。\n\n讵惜鱼锦字，慰此蹉跎年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蜀中寄李宗易宫论' AND p.poem_author = '王廷相';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二日野望作', '林希逸', '宋代', '麦垄高低一样青，淡云笼昼雨丝轻。梅花烂漫开将尽，松叶稀疏落又生。\n\n遥企钧天知梦断，欣闻玉陛庆熙成。人人尽说新年好，除夕无风岁旦晴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二日野望作' AND p.poem_author = '林希逸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶寄林夫', '沈辽', '宋代', '南山雪未消，秋浦春太早。柳萼为谁开，梅花同我老。\n\n少年薄游意，落日晴空杳。林下寂无人，烟外啼幽鸟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶寄林夫' AND p.poem_author = '沈辽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送曾继先赴山阴路钤', '陈傅良', '宋代', '胡髯白尽犹强饭，髀肉添多未跨鞍。\n不向胡沙亲矢石，却来桥冢护衣冠。\n归舟自此长相背，荐墨于今尚未乾。\n只恐燕然他日事，独无名字可同刊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送曾继先赴山阴路钤' AND p.poem_author = '陈傅良';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('麦', '弘历', '清代', '今年天惠均，春膏近远同。适以武功就，展谒驾言东。\n\n渔阳四境间，二麦皆芃芃。绿意含风新，生机饱露浓。\n\n屈指十三年，此景得未逢。饼饵或可期，仓箱讵易充。\n\n乐岁志云慰，忧民心曷穷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '麦' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄曾省之', '陈恭尹', '明代', '分居岭北南，异地幸同心。匪石能攻玉，如兰即断金。\n\n君从卜肆隐，予卧海门深。春别不曾送，秋风劳夜吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄曾省之' AND p.poem_author = '陈恭尹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宋才夫作诗自言作县之况以冷官为可乐戏用韵答之', '李流谦', '宋代', '云霄自许当比肩，岂料坎壈逢针毡。求鱼乃欲从沮洳，吞舟见之定冁然。\n\n诸生但解笑便腹，好事谁肯与酒钱。吹寒固自乏暖律，使物又恨无神鞭。\n\n君方踏筵观艳舞，我正闭户甘草玄。閒忙亦复分苦乐，温醲淡泊无非缘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宋才夫作诗自言作县之况以冷官为可乐戏用韵答之' AND p.poem_author = '李流谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天台隐者', '林景熙', '宋代', '俗驾不曾到，瘦筇时复携。\n肺肝清涧饮，鬓发老岩栖。\n野巷犹鸡犬，春城自鼓鞞。\n未应人世外，别有武陵溪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天台隐者' AND p.poem_author = '林景熙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('将发还乡示诸弟', '张九龄', '唐代', '岁阳亦颓止，林意日萧摵。云胡当此时，缅迈复为客。 \n 至爱孰能舍，名义来相迫。负德良不赀，输诚靡所惜。 \n 一木逢厦构，纤尘愿山益。无力主君恩，宁利客卿璧。 \n 去去荣归养，怃然叹行役。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '将发还乡示诸弟' AND p.poem_author = '张九龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('已亥杂诗 306', '龚自珍', '清代', '家园黄熟半林柑，抛向筠笼载两三。\n风雪迎裾好持赠，预教诗婢识江南。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '已亥杂诗 306' AND p.poem_author = '龚自珍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赵师雄梅阴乍觉三首 其二', '黎景义', '明代', '奇缘疑梦转疑真，眼底梅花意底人。昨夜酒家疑隔世，此时林下祇孤身。\n\n石图疏影当琼枕，苔衬残英代锦茵。春色枝横自幽绝，依稀犹在对花神。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赵师雄梅阴乍觉三首 其二' AND p.poem_author = '黎景义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('广济城楼宴集追和云田宪副韵呈熊府尊时筠寇初平扳筑方就 其一', '符锡', '明代', '时危城守缮于年，童子能歌郡伯贤。累石层台云汉出，滨江飞槛凤洲连。\n\n委蛇退食开尊暇，徙倚晴空放睫便。反侧自堪清净理，淮阳几许借高眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '广济城楼宴集追和云田宪副韵呈熊府尊时筠寇初平扳筑方就 其一' AND p.poem_author = '符锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('出郭望西山诸寺二首 其二', '胡应麟', '明代', '西山四百寺，寺寺金银台。莫言去天远，回首见蓬莱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '出郭望西山诸寺二首 其二' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('霓裳中序第一 宋德寿宫芙蓉石在南榷署', '厉鹗', '清代', '墙阴拥翠浪。搔首繁华成俯仰。藤络苔皴草长，是亲见光尧，蓬莱无恙。\n\n香销玉葬。怕夜深、山鬼来往。凄凉处、奉华旧阁，记否捲帘赏。\n\n惆怅。疏蛬藏响。雨洗净、嶙峋十丈。芙蓉孤倚月幌。\n\n问点额宫梅，已归天上。冷衙蜂乍放。不照到、铜沟腻涨。\n\n青芜里、宣和金字，也是此情况。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '霓裳中序第一 宋德寿宫芙蓉石在南榷署' AND p.poem_author = '厉鹗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿云开堂', '顾璘', '明代', '难逢魏母彩鸾车，聊试弥明石鼎茶。\n翠羽金支云缥缈，紫厓丹洞石\n<山含>\n 岈。\n 五峰黛色消晴雪，万木灵晖散晚霞。\n 愿借双公玄鹤羽，月明骑上太清家。 \n</山含>', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿云开堂' AND p.poem_author = '顾璘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青山', '郑昆', '明代', '把酒对崔嵬，青山颜亦开。吾嗟不如女，曾见古人来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青山' AND p.poem_author = '郑昆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('静宜园二十八景诗 其五 璎珞岩', '弘历', '清代', '滴滴更潺潺，琴音大地间。东阳原有乐，月面却无山。\n\n忘耳听云梵，栖心揖黛鬟。饮光如悟此，不复破微颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '静宜园二十八景诗 其五 璎珞岩' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('幽兰禅院柬西莲禅师', '陈谋道', '清代', '连云高阁郁峥嵘，俯接澄潭百尺盈。竹映帘前分晓色，泉流石畔起秋声。\n\n初闻仙梵空堂细，却听疏钟下界清。为爱当年飞锡地，中宵长对月华明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '幽兰禅院柬西莲禅师' AND p.poem_author = '陈谋道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送襄阳成统制移建康', '项安世', '宋代', '日日梦长干，真成下碧湍。\n雍郊辞鹿隐，钟阜看龙蟠。\n百胜傅家学，三司践世官。\n谁知弓剑里，曾带腐儒酸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送襄阳成统制移建康' AND p.poem_author = '项安世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六言诗十首 其一', '嵇康', '两汉', '惟上古尧舜。二人功德齐均。不以天下私亲。高尚简朴慈顺。宁济四海蒸民。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六言诗十首 其一' AND p.poem_author = '嵇康';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('绮罗香', '郭则沄', '清代', '钿萼笼香，奁波漾梦，㡘外閒莺休妒。瘦损花魂，怕听四弦金缕。\n\n认心事、几曲阑干，斜阳影、暗留春住。记年时、手种垂杨，绿阴遮遍画楼路。\n\n兰成同是倦旅。愁说閒鸳旧约，江湖归去。冷鬓偎烟，换了酒怀琴绪。\n\n便殷勤、扶起蔫红，还担尽、夜来风雨。剩空阶、细拾香尘，断肠闻杜宇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '绮罗香' AND p.poem_author = '郭则沄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮 扑蝶', '陆蓉佩', '清代', '红阑曲折通幽径。海棠带雨梨花病。蓦地见斜飞。轻轻纨扇挥。\n\n临风闲自弄。春去浑如梦。无力下阶行。林深何处寻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮 扑蝶' AND p.poem_author = '陆蓉佩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乐归田园十咏 其五 农人告余以春及至曷不委心任去留', '宗林', '明代', '闻得农夫说，春回畎亩间。舟车无枉迹，草木有荣颜。\n\n寻壑穿云去，径丘踏月还。百年宁几日，能不放心闲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乐归田园十咏 其五 农人告余以春及至曷不委心任去留' AND p.poem_author = '宗林';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无心', '顾逢', '宋代', '世态真堪笑，机深祸亦深。\n多谋还损己，有寿必无心。\n呕肺因诗苦，开怀遇酒斟。\n平生随造物，不暇问升沉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无心' AND p.poem_author = '顾逢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵王克明三首 其二', '林弼', '明代', '江岭孤臣抱寸忠，风雷何日起潜踪。海连辽碣八千里，山隔燕云百万重。\n\n近喜金滩涌鸂鶒，旧闻绿水泛芙蓉。自惭点额桃花浪，每羡神鱼作应龙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵王克明三首 其二' AND p.poem_author = '林弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吕彦贞以诗见寄江舍次韵奉答 其二', '虞堪', '明代', '白石先生多逸情，寄来好句如弥明。空江落木秋正下，流水行云日自生。\n\n神人忽张洞庭乐，老将复捷燕山兵。雄深雅健何可得，我一把咏身如轻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吕彦贞以诗见寄江舍次韵奉答 其二' AND p.poem_author = '虞堪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('柬法忍', '苏曼殊', '近代', '来醉茎深露，胭脂画牡丹。\n落花深一尺，不用带蒲团。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '柬法忍' AND p.poem_author = '苏曼殊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七峰草堂移梅歌', '全祖望', '清代', '大江以北少梅花，相传降作杏六命。我疑陶山语未然，难缘橘户为左证。\n\n棱棱百花头上姿，肯逐黄尘易素性。迁之无道种无术，坐教嘉植困㱥𣩟。\n\n马郎兄弟双玉雪，魂与梅花同清净。有庄明瑟如篮田，有客看花满蒋径。\n\n暗香入梦意无厌，觅遍古欢穷绝嶝。秦淮大有槎牙种，十里江行足吟兴。\n\n园官小试移山手，飞度七峰疑不胫。寂寥小雪霜叶凋，峥嵘几点春牙劲。\n\n新寒未消九九期，徵风已动番番胜。乡心犹为石头悬，羁贯已随瓜步更。\n\n花王之富数花对，恰与今年梧叶称。昨闻连舟度东关，榷吏惊迓纷相侦。\n\n好事敢辞花税哆，佳话应为官阁咏。招邀更喜值同声，叩钵齐催诗思竞。\n\n我家勾馀东复东，宝岩千树苍云映。当归枨触鹪鹩枝，叉手樽前醉眼瞪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七峰草堂移梅歌' AND p.poem_author = '全祖望';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('芳草', '罗邺', '唐代', '芳草和烟暖更青。\n闲门要路一时连。\n年年点简人间事。\n唯有春负不世情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '芳草' AND p.poem_author = '罗邺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏日', '冒德娟', '清代', '芭蕉深绿映疏窗，高柳蝉鸣昼景长。闷卷珠帘看日影，鸳鸯相并立池塘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏日' AND p.poem_author = '冒德娟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('城居夜坐四首 其一', '张月宇', '当代', '阴霾弥漫月昏昏，小隐城隅铁作门。二十八年身久蛰，千零一夜梦犹存。\n\n文章哭我蝇头字，粱稻怜谁犊鼻裈。待旦赁居肱垫枕，何时归卧晚香村。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '城居夜坐四首 其一' AND p.poem_author = '张月宇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('午睡', '戴亨', '清代', '熏风清枕簟，娇睡晕潮生。微笑朱唇启，应知梦里情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '午睡' AND p.poem_author = '戴亨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同徐监簿作水始冰', '刘攽', '宋代', '霜落岁将晏，风生水始冰。犹残夏虫怪，初比玉壶凝。\n\n气袭璇源洁，光摇宝鉴澄。涵虚同凛凛，履薄乍兢兢。\n\n鱼鳖悲潜伏，江湖息沸腾。淩阴如献纳，会是却炎蒸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同徐监簿作水始冰' AND p.poem_author = '刘攽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再和天予二首 其二', '吴芾', '宋代', '中秋花月共徘徊，正喜相逢笑口开。君既不留吾亦去，何时又向此间来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再和天予二首 其二' AND p.poem_author = '吴芾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和璞斋题岐南书舍', '朱浙', '明代', '小斋空坐思悠哉，心远乾坤景自开。忧国几馀华发在，逢人先觅菊花栽。\n\n宦囊两世惟书卷，尘事无端付酒杯。避俗底须方外去，杖藜随处破苍苔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和璞斋题岐南书舍' AND p.poem_author = '朱浙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晓枕不寐书所感三首 其二', '周紫芝', '宋代', '南市津头忆买船，花姑溪上钓晴烟。老来安得孤篷夜，横枕蓑衣听雨眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晓枕不寐书所感三首 其二' AND p.poem_author = '周紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜子春至用前韵', '邵宝', '明代', '千里天台客，重来喜柰何。郡传一手劄，寺问两头陀。\n\n野史操无简，山人卧有蓑。隔年期故在，不放仲春过。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜子春至用前韵' AND p.poem_author = '邵宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吊蝶', '张至龙', '宋代', '数日偎红翅力慵，化成长梦别春风。却怜蚁为埋香玉，舁入残花土穴中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吊蝶' AND p.poem_author = '张至龙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('府君辞世一月忽焉入梦', '陈仁德', '当代', '遥看仿佛旧行装，仆仆风尘两鬓霜。梦里不知泉壤隔，倚门犹自话衷肠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '府君辞世一月忽焉入梦' AND p.poem_author = '陈仁德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('义交堂', '钟芳', '明代', '丈夫慎所处，谊合志乃孚。丹漆有遗训，习染良不诬。\n\n哓哓竞声利，此道成榛芜。机阱隐歌笑，亲洽伤中疏。\n\n眷言薜氏堂，交衢通两都。博延岂不贵，所求在朋徒。\n\n郑贾匪我庐，蜀珍匪我居。开轩揖宾友，满座多钜儒。\n\n遗音启玄瑟，清辉照前除。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '义交堂' AND p.poem_author = '钟芳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('皂河化险为平', '张鹏翮', '清代', '高挂蒲帆巨浪中，青山如画水溶溶。势翻云汉飞霖雨，影息蛟龙靖北风。\n\n两岸桑麻随棹碧，一天皓月印潭空。欲寻当日封堆处，极目田禾翠色浓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '皂河化险为平' AND p.poem_author = '张鹏翮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐 天梅得里中钱氏所藏何猿叟致张诗舲手札，嘱题', '高燮', '清代', '东洲居士。妙语清无比。戏媵霜豪团扇底。十枝聊代精婢。\n\n寥寥三札留遗。楚弓楚得谁知。图卷游山盒子，羡他佳兴离披。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐 天梅得里中钱氏所藏何猿叟致张诗舲手札，嘱题' AND p.poem_author = '高燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('太真 其一', '许南英', '清代', '舍身为遣六军行，掩面君王太不情！比翼鸟分连理折，负他有殿号「长生」！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '太真 其一' AND p.poem_author = '许南英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽叶琼章甥女二首 其二', '沈媛', '明代', '十七龄来聚沫馀，芙蓉城冷待爰居。臂文朱缕他年识，祇恐天都署掌书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽叶琼章甥女二首 其二' AND p.poem_author = '沈媛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('邹谦所孝思堂', '杨士奇', '明代', '墓筑芜湖县，因之托数椽。却思严谴日，感泣更生年。\n\n十口今谁在，孤身秪自怜。朝朝松柏地，拜跽荐寒泉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '邹谦所孝思堂' AND p.poem_author = '杨士奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湖上', '陈师道', '宋代', '湖上难为别，梅梢已著春。\n林喧乌啄啄，风过水鳞鳞。\n缘有三年尽，情无一日亲。\n白头厌奔走，何地与为邻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湖上' AND p.poem_author = '陈师道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送京运使赴召二首', '赵蕃', '宋代', '不官不恨落羇縻，正谓边头狱讼稀。\n但有胶胶还扰扰，略无是是与非非。\n诗书旧学浑忘却，梦寐衡祠放得归。\n邂逅两台俱趣召，莼鲈于此合知几。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送京运使赴召二首' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('石湖草堂', '姚鼐', '清代', '昔为祠宇记，今访石湖园。烟水长如此，风流向古论。\n\n堂开悬石趾，潭隐曲岩门。满谷芳幽桂，虬枝谁与援。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '石湖草堂' AND p.poem_author = '姚鼐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('集句七言绝句诗 其十三', '孙蕡', '明代', '白袷玉郎寄桃叶，金鞍骏马呼小妾。翠眉蝉鬓生别离，南园绿草飞蝴蝶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '集句七言绝句诗 其十三' AND p.poem_author = '孙蕡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('画梅（二首）', '竹庵禅师', '明代', '瑶台夕承月，玉砌晓凝霜。\n花映含章发，枝横禁御长。\n春风似相识，偏惜寿阳妆。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '画梅（二首）' AND p.poem_author = '竹庵禅师';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七月三十日祖母初度时年八十九', '杨基', '明代', '白发青瞳寿者身，每逢佳节话咸淳。\n百年未尽四千日，来岁还周九十春。\n迁客无家空望拜，孤臣有表竟谁陈。\n今朝风雨茅茨底，应对儿孙说远人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七月三十日祖母初度时年八十九' AND p.poem_author = '杨基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('信笔戒子种花木 其八', '许及之', '宋代', '买石为山任笑痴，痴翁真个似童儿。奇峰峭石勤收拾，莫使他年一篑亏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '信笔戒子种花木 其八' AND p.poem_author = '许及之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('厓山吊古 其三', '何治', '明代', '庙门高倚夕阳开，古木苍藤猿啸哀。金阙汴京何处所，慈元宫殿长蒿莱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '厓山吊古 其三' AND p.poem_author = '何治';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观蜀鹃啼剧有感 其二', '吴伟业', '明代', '江关萧瑟片帆留，策马俄成万里游。失计未能全爱子，端居何用觅封侯。\n\n云山已断中宵梦，弦管犹开旧日楼。二月东风吹水调，鹡鸰原上使人愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观蜀鹃啼剧有感 其二' AND p.poem_author = '吴伟业';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水龙吟 春游即目赋得侍儿堪感路旁人', '陈维崧', '清代', '花间一辆雕轮，绣帏袅尽东风细。龙幡压角，翠钿㔩叶，流苏百琲。\n\n暗想其中，宫黄蕃锦，不过端丽。纵玉环丰艳，金堂娇贵，瑶池侣，休凝睇。\n\n忽见花枝徙倚。是谁家、穿帘燕子。忍当春冷，抛他幔后，坐他车尾。\n\n彩笔飘蓬，青衣沦贱，古来如此。料归时、浅导银灯，转那个，屏风底。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水龙吟 春游即目赋得侍儿堪感路旁人' AND p.poem_author = '陈维崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和姚燮喜潘丈迟归二章 其一', '潘德舆', '清代', '明越倚沧海，混茫元气间。高城独立处，傥见三神山。\n\n白日照金阙，天风吹佩环。琪花不可采，尘土上愁颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和姚燮喜潘丈迟归二章 其一' AND p.poem_author = '潘德舆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送顾台州', '邵宝', '明代', '君从西南来，复向东南去。会稽望九疑，愁云蔽江渚。\n\n禹穴阒无声，欲与神灵语。台州海冥冥，金城独高据。\n\n双旌动文星，共识君来处。君来何所将，东风共时雨。\n\n寄语台州人，君归愿无遽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送顾台州' AND p.poem_author = '邵宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('有惠诗求酒者和答二首赠以两榼 其二', '吕陶', '宋代', '愁肠思得浊醪浇，浑似春苗旱欲焦。洗瓮已于坊禁碍，典琴谁向息钱饶。\n\n醒心未免嗟牢落，醉眼偏宜望泬寥。酩酊到来须画寝，信知毕卓胜边韶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '有惠诗求酒者和答二首赠以两榼 其二' AND p.poem_author = '吕陶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吏隐堂', '胡铨', '宋代', '微风稍披冻，芳萌亦吐林。\n百鸟感春阳，钩辀弄其音。\n振策遵城曲，逍遥写烦襟。\n爱此堂下石，青润挺琅琳。\n中坳贮清泉，测之不盈簪。\n纤鳞候暖戏，寂历自浮沉。\n墨视澹忘虑，白日为移阴。\n人生本虚静，垢浊无自侵。\n忽为外物牵，至性不可寻。\n於焉得所监，一洗尘中心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吏隐堂' AND p.poem_author = '胡铨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春草斋遣兴', '谢蕙', '清代', '久甘冷澹作生涯，閒倚阑干感岁华。一架蔷薇高似屋，几丛芍药烂于霞。\n\n梵香缱绻思前哲，赌墅风流忆故家。我比张衡愁更甚，春衣人瘦饭难加。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春草斋遣兴' AND p.poem_author = '谢蕙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冥会诗', '宫嫔', '唐代', '争不逢人话此身，此身长夜不知春。 \n 自从国破家亡后，陇上惟添芳草新。 \n 休说人间恨恋多，况逢佳客此相过。 \n 堂中纵有千般乐，争及阳春一曲歌。 \n 幽谷穷花似妾身，纵怀香艳吐无因。 \n 多情公子能相访，应解回风暂借春。 \n 恩情未足晓光催，数朵眠花未得开。 \n 却羡一双金扼臂，得随人世出将来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冥会诗' AND p.poem_author = '宫嫔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送马天禄给事赴云南佥事', '程敏政', '明代', '禁钟晓初歇，骑出城东门。惜君有远役，相携荐芳尊。\n\n君本琐闼彦，忠言动天阍。起居今十载，廷谢初蒙恩。\n\n西南万馀里，滇江浩沄沄。轺车足时雨，宪节明朝暾。\n\n丈夫挟壮气，抚此岁月奔。红芳漫春色，青松自霜根。\n\n迢遥古南服，慷慨扶风孙。行台知有道，后会须重论。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送马天禄给事赴云南佥事' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('还李彀士雄卷', '张舜民', '宋代', '河汾之会，韩晋之津。\n在昔王马今何人，青衫木笏排风尘。\n面如桃花髭如银，长篇大字妙入神。\n关辅后辈谁等伦，四方仕宦足邅迍。\n归老阌乡玉涧滨，云为友兮山为邻。\n森森绿槊万霜筠，汩汩清涟飞两轮。\n亭上何所见，荆山早暮来相亲。\n斋中何所有，新旧歌诗千百首。\n细大搜罗万象劳，放开日月东西走。\n世上儿女徒纷纷，作者须教归老手。\n君不见古往今来富贵人，灿灿金章悬紫绶。\n金珠初入宠方深，骨肉未消名已朽。\n又不见李杜死来三百年，至今仰望如星斗。\n一联一句挂齿牙，便同金石垂长久。\n乃知皇天造万物，独於吾辈偏加厚。\n还翁诗卷翁细思，岂是生平都不偶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '还李彀士雄卷' AND p.poem_author = '张舜民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋十四日夜对月上南平主人', '齐己', '唐代', '今宵前夕皆堪玩，何必圆时始竭才。空说轮中有天子， \n 不知何处是楼台。终忧明夜云遮却，且扫闲居坐看来。 \n 玉兔银蟾似多意，乍临棠树影裴回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋十四日夜对月上南平主人' AND p.poem_author = '齐己';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿淮阴南楼酬常伯能', '皇甫冉', '唐代', '淮阴日落上南楼，乔木荒城古渡头。浦外野风初入户， \n 窗中海月早知秋。沧波一望通千里，画角三声起百忧。 \n 伫立分宵绝来客，烦君步屐忽相求。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿淮阴南楼酬常伯能' AND p.poem_author = '皇甫冉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望家书', '李媞', '清代', '自离慈母膝，镜里鬓何如。难缩千程水，惟凭尺素书。\n\n苦无双鲤至，倏又产年馀。况是前番札，曾云病未除。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望家书' AND p.poem_author = '李媞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('立春', '陆游', '宋代', '采花枝上宝旛新，看遍秦山楚水春。\n村舍不知时节换，傍檐百舌苦撩人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '立春' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苏幕遮 李公实索慵轩词', '马钰', '元代', '不梳头，不洗面。馁在其中，吃饭心怀倦。无病闲眠身懒转。有客来寻，问著仍慵喘。不烧香，不礼念。落魄婪耽，酬了今生愿。日用不勤功怎见。紫诏来宣，大道无为显。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苏幕遮 李公实索慵轩词' AND p.poem_author = '马钰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送僧东归', '释文珦', '宋代', '今朝送君处，草色如许新。\n后会既难定，别愁那易陈。\n分手限吴越，烟波渺无津。\n云山更重叠，归与何峰邻。\n凭人问消息，或恐非其真。\n不如早重来。勿使山猿嗔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送僧东归' AND p.poem_author = '释文珦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送李季允侍郎归蜀五绝用禅房花竹幽为韵 其三', '刘宰', '宋代', '淮海身如系，岷峨路去赊。相思冰雪里，却立嗅梅花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送李季允侍郎归蜀五绝用禅房花竹幽为韵 其三' AND p.poem_author = '刘宰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('纪先人旧游三首 其三', '薛瑄', '明代', '秖愿庭椿过百龄，宁知奄忽便摧零。旧游山水皆悲思，昔住园庐荩惨情。\n\n菽水有欢成昨梦，衣冠无计睹平生。孙儿指点经行处，清泪如泉散漫倾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '纪先人旧游三首 其三' AND p.poem_author = '薛瑄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日书怀二首 其一', '王炎', '宋代', '杜门值春初，出门已春莫。子规日夜啼，为我诉春去。\n\n萋然草弥望，绿暗溪皋路。百尺游丝高，摇摇引心绪。\n\n归来坐窗底，有句不能吐。唤取黄奶来，且尝黑甜味。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日书怀二首 其一' AND p.poem_author = '王炎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送李友路秀才赴举', '刘禹锡', '唐代', '谁怜相门子，不语望秋山。生长绮纨内，辛勤笔砚间。 \n 荣亲在名字，好学弃官班。伫俟明年桂，高堂开笑颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送李友路秀才赴举' AND p.poem_author = '刘禹锡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪纱 其二', '陈锐', '清代', '一掷年芳等急梭。欢愉时少别时多。相思如水不堪搓。\n\n倚去未妨松两鬓，啼来兀自紧双蛾。今宵愁极奈明何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪纱 其二' AND p.poem_author = '陈锐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天', '杨玉衔', '清代', '筋力登楼讵未知。山高何况入云微。虬龙许有随缘坐，猿鹤宁无入梦思。\n\n层嶂合，一节支。人方逸老我饥驱。打包行脚前生定，拄杖归来梦亦蘧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天' AND p.poem_author = '杨玉衔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送李员外院长分司东都', '韩愈', '唐代', '去年秋露下，羁旅逐东征。今岁春光动，驱驰别上京。 \n 饮中相顾色，送后独归情。两地无千里，因风数寄声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送李员外院长分司东都' AND p.poem_author = '韩愈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('泛浈江至脩仁水寻范云饮水赋诗处', '欧大任', '明代', '陆陟心苦艰，江行意超忽。扬舲恣击汰，理榜欣乘筏。\n\n昔闻范内史，于焉自怡悦。赋诗散郁陶，饮水辨清淈。\n\n今游属暮春，远放遵南粤。三枫睇已遥，五渡嗟应没。\n\n爰思雊雉驯，尚想甘棠茇。命驾税山椒，弭盖依林樾。\n\n明霞带远峦，瑞霭屯崇碣。樊薄粲朱樱，原陵苞绿蕨。\n\n感兹时物迁，惧尔芳馨歇。代更道岂殊，事往迹空揭。\n\n凄凄怀古吟，心赏不可越。鸱夷迥泛湖，子牟怅怀阙。\n\n采兰向中洲，眷此何由达。沿洄发棹讴，愉乐陶嘉月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '泛浈江至脩仁水寻范云饮水赋诗处' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阴廉宪见过', '欧大任', '明代', '滕王阁倚楚天长，秋宪相寻上短航。十载门徒文蜀郡，一时宾客杜当阳。\n\n匡床长啸鄱湖月，绣斧先飞粤海霜。归赴内台应独坐，建章春色望鹓行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阴廉宪见过' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戊戌初度二首', '袁宏道', '明代', '闲居心似夹冰鱼，雪里轮蹄亦自疏。\n研酒和来香泛帖，瓶花吹落湿沾书。\n艰深乍觉诗如谶，消散方知道是虚。\n一卷杂华繙未了，被人邀得过僧庐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戊戌初度二首' AND p.poem_author = '袁宏道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('齐安行', '张耒', '宋代', '黄州楚国分三户，葛蔓为城当楼橹。\n江边市井数十家，城中平田无一步。\n土冈瘦竹青复黄，引水种稻官街旁。\n客樯朝集暮四散，夷言啁哳来湖湘。\n使君丽谯涂垩赭，门狭不能行两马。\n满城蛙噪乱更声，谷风谷谷黄鸦鸣。\n最愁三伏热如甑，北客十人八九病。\n百年生死向中州，千金莫作齐安游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '齐安行' AND p.poem_author = '张耒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂一百则 其九十八', '释重显', '宋代', '明珠在掌，有功者赏。胡汉不来，全无伎俩。伎俩既无，波旬失途。\n\n瞿昙瞿昙，识我也无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂一百则 其九十八' AND p.poem_author = '释重显';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('易上', '姚燮', '清代', '击筑更谁歌，荒原落日多。舆图犹督亢，壮士失荆轲。\n\n莽莽关前树，萧萧易上波。无端千载下，有客为滂沱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '易上' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送宁朔', '耶律铸', '元代', '说从薛烛授吹毛，从事孙吴与六韬。应策腾空调赤电，惊弦裂石试乌号。\n\n鼎鱼幕燕由西极，侵气游魂在北郊。击惰捣虚原有策，必须先直取窠巢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送宁朔' AND p.poem_author = '耶律铸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵方文敏秋兴五首 其一', '贝琼', '明代', '地拱皇陵松柏深，君王法驾几时临。汉宫甘露曾闻昔，周室丰年岂自今。\n\n太史已删金匮录，词臣应制凤台吟。忆陪仙仗千官入，春日新莺在柳阴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵方文敏秋兴五首 其一' AND p.poem_author = '贝琼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄旧居邻友', '齐己', '唐代', '别后知何趣，搜奇少客同。几层山影下，万树雪声中。 \n 晚鼎烹茶绿，晨厨爨粟红。何时携卷出，世代有名公。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄旧居邻友' AND p.poem_author = '齐己';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八咏警戒 其五', '吴处厚', '宋代', '无私仍克己，克己又无私。一事兼修饰，终身在省思。\n\n公清多敛怨，高亢易招危。更切循卑退，方应履坦夷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八咏警戒 其五' AND p.poem_author = '吴处厚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寒云轻重色', '张仲素', '唐代', '佳期当可许，托思望云端。鳞影朝犹落，繁阴暮自寒。 \n 因风方袅袅，间石已漫漫。隐映看鸿度，霏微觉树攒。 \n 凝空多似黛，引素乍如纨。每向愁中览，含毫欲状难。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寒云轻重色' AND p.poem_author = '张仲素';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('明月海棠图', '朱谏', '明代', '太液池边月欲坠，海棠花下杨妃醉。月照金闺春夜长，花近玉阑娇欲睡。\n\n东风淡荡沈香亭，花间恐有流莺鸣。玉笛声随落花去，月明不见牵牛星。\n\n玉人巳去春无主，御沟春暖空流水。旧时明月空自圆，花若含羞向谁语。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '明月海棠图' AND p.poem_author = '朱谏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏贫士 其五', '陶渊明', '魏晋', '袁安困积雪，邈然不可干。\n阮公见钱入，即日弃其官。\n刍槁有常温，采莒足朝餐。\n岂不实辛苦，所惧非饥寒。\n贫富常交战，道胜无戚颜。\n至德冠邦闾，清节映西关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏贫士 其五' AND p.poem_author = '陶渊明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和酬入内赵供奉见赠', '魏野', '宋代', '出入宫闱侍从官，再过林下信温颜。\n朝天驻足因临水，驰馹迴头入望山。\n捧诏正当趋杜殿，寄诗那忽到松关。\n老来诗思尤枯竭，莫怪阳春不旋还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和酬入内赵供奉见赠' AND p.poem_author = '魏野';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('台城路 庚寅上巳丰城雅集，时玉树方闻震警', '王蛰堪', '当代', '一天花雨催春暮，魂销剑池诗酒。座上陈蕃，樽前孺子，神接兰亭时候。\n\n龙光射斗。尽箫客才人，曲星文宿。自古风流，漫将词笔话江右。\n\n京尘懒开倦眼，阴晴关冷暖，天意难叩。嫩约前盟，今鸿旧雨，泪惹相逢衫袖。\n\n霜毫看取。正韵逐尖叉，展缣题就。别有伤怀，劫边惊地吼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '台城路 庚寅上巳丰城雅集，时玉树方闻震警' AND p.poem_author = '王蛰堪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('燕京四时乐四首 其一', '王世贞', '明代', '城南韦曲春可怜，侯家铺埒黄金钱。即妨蹀𨇾要归去，十五搊筝杨柳烟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '燕京四时乐四首 其一' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪纱 次韩致尧韵', '吴湖帆', '清代', '酒晕双红烛影摇。恍然妩媚楚宫腰。漏迟无语暗心焦。\n\n明月侵阶情脉脉，湘帘簸梦思迢迢。枕香衾暖奈无憀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪纱 次韩致尧韵' AND p.poem_author = '吴湖帆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('中秋湖上看月', '虞堪', '明代', '楼台超有界，风月到无边。说幻难逃佛，凭虚已是仙。\n\n玄洲生碧草，净土出青莲。我爱杯中物，来随社里缘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '中秋湖上看月' AND p.poem_author = '虞堪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题蒋溥雪中梅竹', '弘历', '清代', '楼雪檐晞暖未融，争春香色品量中。看来㡧里依筼绿，讶似盆间破萼红。\n\n即景适堪供静赏，传神应识有家风。三希重展添佳快，王氏风流若与同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题蒋溥雪中梅竹' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长清道中二首 其二', '王樵', '明代', '我忆茅山下，营居碧树团。饱书堪万卷，睡日到三竿。\n\n有用心常乐，无挠梦亦安。何如风雪道，只跨旧征鞍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长清道中二首 其二' AND p.poem_author = '王樵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟行三章', '刘学箕', '宋代', '桂櫂兮兰桨，泝流兮沿回。\n天迦兮空明，湍激兮声哀。\n水落兮石出，路转兮溪回。\n鸥飞兮山净，鱼戏兮藻开。\n淹留兮何为，盍赋兮归来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟行三章' AND p.poem_author = '刘学箕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('楼上', '洪亮吉', '清代', '楼上疏灯彻夜明，营前击柝断人行。宵严都尉亲巡栅，岁歉村农罕入城。\n\n岘首一书愁未报，淮南十月更孤征。霜寒不是无衣苦，凄瑟难为负米情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '楼上' AND p.poem_author = '洪亮吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀故乡', '释文珦', '宋代', '家住潜溪云万里，别来四十九春风。\n无田种秫不归去，梦落山光水色中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀故乡' AND p.poem_author = '释文珦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八归 辛巳腊月十九日，郭筠仙“寿苏”集饮', '王闿运', '清代', '年年雅会，处处新诗，谁知暗里催老。散仙勘破人间世，付与将来好事，家家东道。\n\n湘上平安多福地，把海内、风流占了。更有峨眉归客。\n\n戏著雪鸿爪。借问寿苏故事，自覃溪去后，唯有杨家酒好。\n\n三年梦里，八仙局外，又见尊前一笑。想文章嬉骂，空洞胸怀可同调。\n\n且较量，红烛光中，绿梅花外，甚处得春早。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八归 辛巳腊月十九日，郭筠仙“寿苏”集饮' AND p.poem_author = '王闿运';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东平道中有感', '冯彬', '明代', '晓发东平道，淅沥风露秋。道旁有古坟，累累翳荆丘。\n\n翁仲互倾侧，隧路狐狸游。询之道上人，阅代公与侯。\n\n忆昔全盛时，赐葬承恩优。松楸蔽天日，碑板蟠龙虬。\n\n一朝陵谷变，名姓不可求。悠悠百年身，旦夕同蜉蝣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东平道中有感' AND p.poem_author = '冯彬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂七十八首', '释正觉', '宋代', '习习春风，丝丝春雨。\n一等沾濡，十方周普。\n甘草得之甜，黄连得之苦。\n天意发丛林，檐声闹窗户。\n古德尝云已不迷，等闲教坏人男女。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂七十八首' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('青玉案', '杨慎', '明代', '盈盈春水桃根渡。问芳信、来何暮。青翰舟上，锦鸳波底，总是关情处。\n\n合欢新种中庭树。相思欲寄云南句。为问佳期何日许。\n\n飞鸿洲渚，流萤院宇。银汉双星渡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '青玉案' AND p.poem_author = '杨慎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨中过镇海寺访别庵上人', '吴瞻泰', '清代', '林樾散清阴，积翠沾凉露。濛濛光曦峰，下有化人住。\n\n绀宇新峥嵘，鸽王长布濩。锡飞自夔州，海角传杯渡。\n\n听法驯鱼龙，忘机狎鸥鹭。昨夜雨霏微，瀑洒寒泉树。\n\n濡足就支公，示我沧洲路。回径溜雨桥，瘦杖孤云去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨中过镇海寺访别庵上人' AND p.poem_author = '吴瞻泰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠道省亲', '王恭', '明代', '独鸐下三天，吹笙度紫烟。道心飞鸟外，亲舍白云边。\n\n丹脉调香饭，霞衣拂寿筵。更教人代里，何处觅神仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠道省亲' AND p.poem_author = '王恭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江陵送僧还蜀', '宋登春', '明代', '烟树寒云楚水西，残瓢破衲独行迟。心无一事即相见，千里何须叹别离。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江陵送僧还蜀' AND p.poem_author = '宋登春';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花集句 其四十九', '李龏', '宋代', '暗香时复过窗纱，不是桃花与李花。试问花枝何处好，病来帘外是天涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花集句 其四十九' AND p.poem_author = '李龏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('那呵滩 其六', '佚名', '魏晋', '百思缠中心，憔悴为所欢。与子结终始，折约在金兰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '那呵滩 其六' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饮酒十八', '添雪斋', '当代', '秦虢开夜宴，紫垣谁自得。长醉发中梦，呼圣众不惑。\n\n宣文郑卫饰，敖辟例充塞。鼎食金丹丸，上国并你国。\n\n鱼皮久足贵，新元冷幽默。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饮酒十八' AND p.poem_author = '添雪斋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读史怀友', '唐泾', '宋代', '羞登广式议英雄，匣却吴钩弢却弓。\n幕下清谈王太尉，门前白马褚司空。\n一编袞斧风尘表，千古纲常天壤中。\n说与华阴扪虱老，何曾正朔在江东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读史怀友' AND p.poem_author = '唐泾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送林光宇文学同高吴二茂才还闽四绝句 其四', '王世贞', '明代', '高子波澜自老成，吴郎神彩独纵横。他年并出延津剑，遥见星文动洛城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送林光宇文学同高吴二茂才还闽四绝句 其四' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宋少府东溪泛舟', '李频', '唐代', '登岸还入舟，水禽惊笑语。晚叶低众色，湿云带繁暑。 \n 落日乘醉归，溪流复几许。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宋少府东溪泛舟' AND p.poem_author = '李频';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满庭芳', '王处一', '元代', '暂别东牟，西游登郡。万灵遥列金乡。无穷仙眷，空外总呈祥。\n\n休道蓬莱路远，诸真圣、都会芝阳。星坛下，凉天静夜，云宴礼虚皇。\n\n十方同法会，丹诚对圣，出罪行香。度九幽离苦，悉睹三光。\n\n见在俱蒙福祐，沾甘露、同免灾殃。逍遥乐，圆坛罢散，齐唱满庭芳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满庭芳' AND p.poem_author = '王处一';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬金部王郎中省中春日见寄', '卢纶', '唐代', '南宫树色晓森森，虽有春光未有阴。鹤侣正疑芳景引， \n 玉人那为簿书沈。山含瑞气偏当日，莺逐轻风不在林。 \n 更有阮郎迷路处，万株红树一溪深。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬金部王郎中省中春日见寄' AND p.poem_author = '卢纶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病客吟', '孟郊', '唐代', '主人夜呻吟，皆入妻子心。客子昼呻吟，徒为虫鸟音。 \n 妻子手中病，愁思不复深。僮仆手中病，忧危独难任。 \n 丈夫久漂泊，神气自然沉。况于滞疾中，何人免嘘eS. \n 大海亦有涯，高山亦有岑。沉忧独无极，尘泪互盈襟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病客吟' AND p.poem_author = '孟郊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('景阳宫井', '胡仲弓', '宋代', '隋师已迫长江浒，玉树庭花曲未终。千古龙鸾有遗恨，胭脂井上至今红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '景阳宫井' AND p.poem_author = '胡仲弓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过建宁县', '卢琦', '元代', '蓝舆度林杪，还向此中过。县古人家少，山深秋意多。\n\n民风原俭啬，官事只催科。赖有二三友，相从共啸歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过建宁县' AND p.poem_author = '卢琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春水', '黄邛', '清代', '春水门前过，落花天上来。竹竿丝袅袅，长倚钓鱼台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春水' AND p.poem_author = '黄邛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('扬州三首', '杜牧', '唐代', '炀帝雷塘土，迷藏有旧楼。谁家唱水调，明月满扬州。 \n 骏马宜闲出，千金好旧游。喧阗醉年少，半脱紫茸裘。 \n 秋风放萤苑，春草斗鸡台。金络擎雕去，鸾环拾翠来。 \n 蜀船红锦重，越橐水沈堆。处处皆华表，淮王奈却回。 \n 街垂千步柳，霞映两重城。天碧台阁丽，风凉歌管清。 \n 纤腰间长袖，玉珮杂繁缨。拖轴诚为壮，豪华不可名。 \n 自是荒淫罪，何妨作帝京。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '扬州三首' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('台城路 题谢椒石观察小苏潭词后', '叶绍本', '清代', '一编艳制明于锦，羡煞仙才如许。禁苑文章，襜帷事业，都付檀槽金缕。\n\n铜驼俊侣。况公子西园，兰芽玉树。滴粉搓酥，就中多少断肠句。\n\n花间草堂谁数，爱风情宛转，歌翻白纻。十里横塘，一溪香雪，留得骚人且住。\n\n旧怀触迕。记赁庑皋桥，鸿泥前度。往事如云，乘香萦梦缕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '台城路 题谢椒石观察小苏潭词后' AND p.poem_author = '叶绍本';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忠厚吟', '邵雍', '宋代', '小人斯须，君子长久。\n斯须倾邪，长久忠厚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忠厚吟' AND p.poem_author = '邵雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠医士刘怀川', '邝思诰', '明代', '几年修炼谢尘寰，大事因缘出世间。自养黄芽居紫府，人栽红杏遍青山。\n\n济生何用肱三折，不死全凭药九还。我亦云中曾煮石，逢君同得驻朱颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠医士刘怀川' AND p.poem_author = '邝思诰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寓言十首 其一', '胡奎', '明代', '客从海上来，探彼明月珠。下沈无底谷，不惜千金躯。\n\n得之骊龙颔，行险何其愚。君子保明哲，荣名安可趋。\n\n求鱼不投饵，待兔当守株。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寓言十首 其一' AND p.poem_author = '胡奎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵钱倅诸公睡香花四首 其二', '陈造', '宋代', '幽人睡为乡，长日踵纳息。天香唤醒然，颇复费诗力。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵钱倅诸公睡香花四首 其二' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('平原道中见牧豕者', '尹嘉宾', '明代', '天门室宿郁如虹，海上萧条牧豕翁。\n会得平津开阁意，一竿寒日野田中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '平原道中见牧豕者' AND p.poem_author = '尹嘉宾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谒明祖孝陵', '周龙藻', '清代', '郁郁复苍苍，园陵气渺茫。城回江独涌，云散殿空凉。\n\n攒乱功初震，开基德倍昌。断蛇无剑化，铸鼎有弓藏。\n\n隧道悬钟鼓，明楼带阜冈。乌朝分早暮，芝产辨阴阳。\n\n象设规模壮，祠官礼数详。岂期休运厄，忽使寇氛攘。\n\n率土成猿鹤，弥天纵虎狼。燕京旋改玉，沧海遂栽桑。\n\n门欲罘罳坏，庭谁謦欬扬。中珰头总白。遗户业俱荒。\n\n亭破抛宫瓦，碑残压御墙。樵余松柏秃，烧后黍禾长。\n\n尚喜龙回驭，重闻骑捧香。烝尝修异世，肸蚃动今皇。\n\n登拜仪严肃，宣传语炜煌。共惊唐六典，犹重汉三章。\n\n故国游仍到，新亭感可忘。衣冠原庙尽，抔土何须惜，家居苦自亡。\n\n画难追贾、邓，史忍读宣、光。乍对铜驼泣，还凭石马伤，蒋山形胜在，落日半昏黄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谒明祖孝陵' AND p.poem_author = '周龙藻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十三绝句 其十', '王鏊', '明代', '三顾频繁亦未閒，金陵东下是金山。分明铁瓮头边路，载得贤人与共还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十三绝句 其十' AND p.poem_author = '王鏊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题仿石涛墨竹', '余菊庵', '当代', '石涛写竹本天才，我岂邯郸学步哉。偶尔兴来遏不住，淋漓泼墨写将来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题仿石涛墨竹' AND p.poem_author = '余菊庵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游八关寺后池上', '陈与义', '宋代', '落日生春色，微澜动古池。\n柳林横绝野，藜杖去寻诗。\n不有今年谪，争成此段奇。\n殷勤雪颅老，随客转荒陂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游八关寺后池上' AND p.poem_author = '陈与义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('快活吟第三笔示诸儿', '陈著', '宋代', '小儿求我第三笔，醉中言语不择出。\n老怀空空无他肠，汝祖心事须当毕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '快活吟第三笔示诸儿' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('每日文渊阁閒思李翰林不知迁太学谁共坐论心', '杨士奇', '明代', '欲赠岁寒意，托之淇上竿。亭亭君子节，长似玉堂看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '每日文渊阁閒思李翰林不知迁太学谁共坐论心' AND p.poem_author = '杨士奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元方用韵寄若拙弟邀同赋元方将托若拙觅颜渊之五十亩故诗中见意', '陈与义', '宋代', '梦中与世极周流，错认三刀是得州。拟学耕田给公上，要为同社燕春秋。\n\n囊间已办青芒屦，桑间想闻黄栗留。傥有幽人咨出处，为言无况莫来休。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元方用韵寄若拙弟邀同赋元方将托若拙觅颜渊之五十亩故诗中见意' AND p.poem_author = '陈与义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻边报贡虏有变', '陈万言', '明代', '我曾建节天雄军，赵魏良家负弩群。鸣弦跃马乐战斗，邯郸易水思前人。\n\n号召材官教五伐，愿言出塞护燕云。我官六月被移徙，上书幕府等空文。\n\n关西太史王槐野，文章纪述怀慇勤。三郡邦畿不设卫，豪雄寂寞为编民。\n\n上恬下熙博胜负，谁排阊阖一敷陈。穆皇践祚改元日，东夷西虏何纷纷。\n\n匈奴饮马潞河水，沧州一老射绝伦。掌中主客兵十万，不遗一矢徒逡巡。\n\n昨日报称虏远道，今朝槌岩鏖战频。东山张君真将种，饮血帐下期策勋。\n\n长驱跳堑冲虏阵，射雕先锋翳荆榛。橐驼人马相枕藉，傍岩百仞翻车轮。\n\n后军割级献枢府，皇恩犹贷贲军臣。诏从边外封京观，威震穹庐千万春。\n\n天生纠纠谭襄敏，都护横戈起七闽。遂拟筑台扼胡吭，累累相丽齿与唇。\n\n二十年来氛祲熄，谁云市马犬戎亲。偎予分竹都城下，谭公召饮酒数巡。\n\n抵掌高谈理燕蓟，我兵凭高战技新。书生借箸前画策，何不建置于西秦。\n\n公云马价入兵府，财力裕蓟应及邻。顺义虎视图西市，羌戎茶马沾皇仁。\n\n假虞伐虢乃其计，吾兵不守边城闉。遂致折将虏士女，西人洒泪空沾巾。\n\n明明天子见万里，求贤易将纷丝纶。吾友郑君负奇气，十年勋业动旒宸。\n\n一朝统驭连八镇，扯勒夫妇走恂恂。蹲刀衔土誓终服，外攘内治静边尘。\n\n杞人忧天斗西揭，安得长殳西海滨。粤南海上渔樵侣，欲作铙歌寄雁宾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻边报贡虏有变' AND p.poem_author = '陈万言';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和吴大史', '殷葆诚', '清代', '敢说同岑不异苔，尊前一揖笑颜开。方忻卿月常分照，讵料罡风又折回。\n\n白雪词高难续和，黄花秋好赋归来。他年双节移吴会，尽日看山再作陪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和吴大史' AND p.poem_author = '殷葆诚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('即事题小亭 其一', '王世贞', '明代', '过雨山城绿欲齐，一群娇鸟踏枝低。不知谢豹今何处，应在春明门外啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '即事题小亭 其一' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答殷尧藩赠罢泾源记室', '沈亚之', '唐代', '劳君辍雅话，听说事疆场。提笔从征虏，飞书始伏羌。 \n 河流辞马岭，节卧听龙骧。孤负平生剑，空怜射斗光。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答殷尧藩赠罢泾源记室' AND p.poem_author = '沈亚之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题谢娘秋影照 其三', '孙原湘', '清代', '秦淮昔梦散如尘，太傅池台宿草新。我是东山旧宾客，可堪重对卷中人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题谢娘秋影照 其三' AND p.poem_author = '孙原湘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西湖十景册为唐饬轩题 其八 延祥清晓', '孙承恩', '明代', '日出烟霏开，湖上散清霁。采采芙蓉花，怀人渺何处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西湖十景册为唐饬轩题 其八 延祥清晓' AND p.poem_author = '孙承恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('巢云', '李吕', '宋代', '幽栖寄山隈，欣赏亦何有。\n时许巢白云，纷然入窗牖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '巢云' AND p.poem_author = '李吕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和秀实别寄二篇 其二', '王洋', '宋代', '香火社闲棋度日，溪山伴静酒为年。碧霄鹤唳诗情远，湖院僧知茶梦圆。\n\n常喜春锄行佚老，每嫌棋路尚争先。平湖草岸经行好，后夜延缘刺钓船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和秀实别寄二篇 其二' AND p.poem_author = '王洋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('抵家后口占 其二', '胡煦', '清代', '日日亲知少送迎，不堪回首问平生。儿童老大髭须白，强半登堂说小名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '抵家后口占 其二' AND p.poem_author = '胡煦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题叶清甫绿波楼', '卢琦', '元代', '主人能拔俗，每自捲珠帘。野水春生浦，山云日傍檐。\n\n陶家唯酿酒，邺架尽悬签。相见波光好，秋来绿又添。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题叶清甫绿波楼' AND p.poem_author = '卢琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('莫君楚生以吾家绣谷老人药园诗稿见示用族祖瓯亭翁于京师重获瓶花斋旧藏丁卯集得长律三首韵酬之 其三', '吴昌绶', '清代', '掇拾丛残慰寂寥，短檠无寐倚寒宵。亡书积岁犹心恋，煮字长年笑腹枵。\n\n梦里奇编搜宛委，画中别业负渔樵。结邻幸复追皮陆，诗事同寻临顿桥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '莫君楚生以吾家绣谷老人药园诗稿见示用族祖瓯亭翁于京师重获瓶花斋旧藏丁卯集得长律三首韵酬之 其三' AND p.poem_author = '吴昌绶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十一二用喜雪韵四首', '吴潜', '宋代', '只堪闭户著潜虚，欲作遨头畏简书。\n乍密乍稀云冻后，半融半落雨收初。\n封条正恐观梅错，渍谷犹疑学稼疎。\n却喜明朝春税驾，气苏{巢果换禺}{巢果换禺}与狙狙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十一二用喜雪韵四首' AND p.poem_author = '吴潜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂曲歌辞 其五', '李廓', '唐代', '遨游携艳妓，装束似男儿。杯酒逢花住，笙歌簇马吹。\n\n莺声催曲急，春色讶归迟。不以闻街鼓，华筵待月移。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂曲歌辞 其五' AND p.poem_author = '李廓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('踏莎行', '谭处端', '元代', '才见春花，又逢秋月。春花秋月何时彻。劝君速悟勿蹉跎，壶中别有佳时节。\n\n断爱超尘，当须猛烈。元阳固炼搜玄诀。神珠磨炼莫交昏，无来不去超生灭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '踏莎行' AND p.poem_author = '谭处端';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重游玉屏山三著　并引 其一', '黄光宗', '明代', '二十馀年又一过，岩花犹对旧山河。重来尚作萧条客，四十登临感慨多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重游玉屏山三著　并引 其一' AND p.poem_author = '黄光宗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('官舍', '白居易', '唐代', '高树换新叶，阴阴覆地隅。何言太守宅，有似幽人居。 \n 太守卧其下，闲慵两有馀。起尝一瓯茗，行读一卷书。 \n 早梅结青实，残樱落红珠。稚女弄庭果，嬉戏牵人裾。 \n 是日晚弥静，巢禽下相呼。啧啧护儿鹊，哑哑母子乌。 \n 岂唯云鸟尔，吾亦引吾雏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '官舍' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('海棠四首 其四', '杨万里', '宋代', '吾诗多为海棠哦，花意依前怨不多。已拆未开浑是韵，乍浓还淡总由它。\n\n留连春色能销底，请托东风定肯么。岂是少陵无句子，少陵未见欲如何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '海棠四首 其四' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('有怀前人', '赵抃', '宋代', '却忆东舟去若仙，江亭分袂忽经年。春风境上无多地，夜月湖中共一天。\n\n海阁坐观涛拥鹭，山堂吟听漏移莲。新诗往复交情见，巨集成来已百篇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '有怀前人' AND p.poem_author = '赵抃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题自画赠王德中', '朱同', '明代', '月出城东头，团团上明镜。古树倚朱楼，栖乌惊未定。\n\n小星淡已无，大星远相映。草露发夜光，荷盘拭秋净。\n\n良朋喜同游，清赏寄高咏。安得白玉绳，为人系清影。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题自画赠王德中' AND p.poem_author = '朱同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('口号', '周馨桂', '清代', '不树名场帜，悠悠已卅年。少惭班氏笔，老愧祖生鞭。\n\n远浦垂纶坐，空山枕石眠。闲来无一事，且以让时贤。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '口号' AND p.poem_author = '周馨桂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题相如题柱图', '谢迁', '明代', '凌云气槩欲何如，万里桥边驷马车。词赋偶缘杨得意，却将负弩诧乡闾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题相如题柱图' AND p.poem_author = '谢迁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠别陈县丞纶', '梁兰', '明代', '三载哦松间，一如下车初。政事岂不烦，才力自有馀。\n\n兹晨当弃去，轩盖盈交衢。父老谷中至，再拜倾酒壶。\n\n各言恒具瞻，莫若贤大夫。龙飞抚昌运，仁明迈唐虞。\n\n引领希重来，善保千金躯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠别陈县丞纶' AND p.poem_author = '梁兰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三月廿日邀同任伯卿施祓堂游曾氏园林归饮署斋即事 其二', '朱景英', '清代', '细路逶迤入，城南访辟疆。竹疏三径辟，树暗一扉藏。\n\n款客虚厨具，谭诗剩草堂。不妨留少选，幽意引春阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三月廿日邀同任伯卿施祓堂游曾氏园林归饮署斋即事 其二' AND p.poem_author = '朱景英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七夕宫词四首 其三', '何吾驺', '明代', '前殿初传乞巧词，月光如练印瑶池。常时一片悲秋思，未许牵牛织女知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七夕宫词四首 其三' AND p.poem_author = '何吾驺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题杨妃出浴图 其一', '陈肇兴', '清代', '玉貌花颜金步摇，一番澡洗倍夭娇。起来似不胜罗帔，倚定宫娥整翠翘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题杨妃出浴图 其一' AND p.poem_author = '陈肇兴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('《足荣杯》评审事毕偕诸公赴雷州颁奖车中有作', '熊东遨', '当代', '少借鸥盟意，同车向海行。诗多经眼录，水梦出山清。\n\n前路仍风雨，馀年减性情。嘤鸣破寥寂，只要两三声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '《足荣杯》评审事毕偕诸公赴雷州颁奖车中有作' AND p.poem_author = '熊东遨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽王端之', '程敏政', '明代', '君来古歙曾过我，寒日松梅话小轩。我到钱塘还访子，暖风花竹宴名园。\n\n笑谈追想如三宿，魂梦那知隔九原。哀些慰君君莫恨，紫霄雏凤待高鶱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽王端之' AND p.poem_author = '程敏政';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花', '张道洽', '宋代', '孤芳嫌杀浑群芳，雪满山坳月满塘。\n韵士不随今世态，仙姝犹作古时妆。\n雪羞洁白常回避，春忌清高不主张。\n地僻何妨绝供给，饥来只用宴寒香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花' AND p.poem_author = '张道洽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和贡觉除夕原韵 其二', '许南英', '清代', '岁晚看人忙不了，先生自在辑芸编。又亲风雅为羁客，曾咏霓裳会众仙。\n\n太息年光留不住，何来诗债苦相缠！效颦得句羞人后，他日骚坛愿执鞭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和贡觉除夕原韵 其二' AND p.poem_author = '许南英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀往（二首）', '徐祯卿', '明代', '穴虫测序改，客鸟知时宴。\n严风振中野，凝霜薄飞观。\n褰裳启东户，河星出有灿。\n耿耿不遑寐，沉思遂回乱。\n何以终遥夕，明灯且濡翰。\n自我违之子，苑藻绝流玩。\n郢斤不存目，流俗耻垩墁。\n块处空堂中，谁为发言粲。\n感慨申微词，伫立倚长叹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀往（二首）' AND p.poem_author = '徐祯卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湖州道中四首 其二 横山堂', '孙觌', '宋代', '苍云千亩荫平宽，露叶风枝绕舍寒。莫遣先生赋归去，且令小吏报平安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湖州道中四首 其二 横山堂' AND p.poem_author = '孙觌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观雪二首 其二', '杨万里', '宋代', '坐看深来尺许强，偏于薄暮发寒光。半空舞倦居然懒，一点风来特地忙。\n\n落尽琼花天不惜，封它梅蕊玉无香。倩谁细撚成汤饼，换却人间烟火肠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观雪二首 其二' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵题冷泉亭', '陈镒', '元代', '我游灵隐山，木落素秋景。廓然得遐观，万象分驰逞。\n\n古石啮水痕，寒山荡云影。投果拈白猿，扪萝陟苍岭。\n\n回憩泉上亭，载瀹山中茗。浊根已疏雪，至味方隽永。\n\n不知尘世中，有此清凉境。缅怀白使君，千载名不冷。\n\n摩挲石上诗，岁月发深省。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵题冷泉亭' AND p.poem_author = '陈镒';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('嘉兴九日寄丹阳亲故', '权德舆', '唐代', '穷年路岐客，西望思茫茫。积水曾南渡，浮云失旧乡。 \n 海边寻别墅，愁里见重阳。草露荷衣冷，山风菊酒香。 \n 独谣看坠叶，远目遍秋光。更羡登攀处，烟花满练塘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '嘉兴九日寄丹阳亲故' AND p.poem_author = '权德舆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丞相马挽章', '黎廷瑞', '宋代', '平生甚似洪文惠，暮景惜不如盘洲。纤儿何人竟误晋，大夫此日空非周。\n\n长夜漫漫不复旦，芳草凄凄其奈秋。遗书堕泪付千载，往从后轩云间游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丞相马挽章' AND p.poem_author = '黎廷瑞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄州周二选部居忧作此寄之君故以星变言事忤贵人见谪 其二', '王世贞', '明代', '占星疏草胜君房，匡鼎揶揄石显忙。今日中天蒙气尽，可能无意向明光。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄州周二选部居忧作此寄之君故以星变言事忤贵人见谪 其二' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古二十首 其十二', '释了一', '宋代', '礼佛无端撞赵州，却将知见作冤雠。如今四海平如掌，云自高飞水自流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古二十首 其十二' AND p.poem_author = '释了一';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('少年游 宫词，拟小山', '杨玉衔', '清代', '霓裳腰舞簇云罗。丝柳织莺梭。一片毡毹，钗摇钿坠，落比花多。\n\n有时太液恩波共，春宴付銮坡。昭阳天外，广寒宵半，缥缈闻歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '少年游 宫词，拟小山' AND p.poem_author = '杨玉衔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送人游江南', '晁冲之', '宋代', '涌金门外断红尘，衣锦城边着白蘋。不到西湖看山色，定应未可作诗人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送人游江南' AND p.poem_author = '晁冲之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('瓜州阻风忆贾丈汉庭 其二', '缪公恩', '清代', '二十年前访荜门，春风携我锦春园。只今宿草无人问，何处冬青锁断魂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '瓜州阻风忆贾丈汉庭 其二' AND p.poem_author = '缪公恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('惠州西湖九咏苏堤 其一', '陈永正', '当代', '苏堤柳色界天青，丰乐桥边眼自明。最爱碧桃三月浪，轻烟如梦惠州城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '惠州西湖九咏苏堤 其一' AND p.poem_author = '陈永正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登清风台谒夷齐庙', '萧惟豫', '清代', '我立永丰巅，首阳向我峙。遂之清风台，以访墨胎氏。\n\n郁郁松柏林，悠悠滦漆水。雨洗春色深，人入清风里。\n\n未食蕨与薇，安知肉食鄙。为顽与为廉，百年同一死。\n\n吁嗟黄虞人，在此不在彼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登清风台谒夷齐庙' AND p.poem_author = '萧惟豫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南山即事', '胡宏', '宋代', '南山崇崇几千丈，今晨忽被蛮烟蜑雾埋其高。安得万里飘风一吹散，见巍峨苍翠解我心郁陶。\n\n郁陶心匪他，为爱南山高。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南山即事' AND p.poem_author = '胡宏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江城子 方壹过冬', '尹志平', '元代', '严冬共喜小方壶。称幽居。论元初。话到三更，皆似觉清虚。万事有心求不得，凭象罔，获玄珠。一言了了性如如。乐无为。驾云车。朝拜高真，功满赴仙都。速悟人人俱有分，听予劝，莫痴愚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江城子 方壹过冬' AND p.poem_author = '尹志平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赭山', '嵇曾筠', '清代', '沧江括地维，瀛海包天根。赭山驾长虹，校与他山尊。\n\n秦王昔驱石，一一皆东奔。鞭此不为动，骨立余殷痕。\n\n祇今数千年，独喜岿然存。潮汐靡不由，终古相吐吞。\n\n伊余董蔬导，出入宜穷源。拿舟涉洪波，周历惊心魂。\n\n幸使井里安，夷险非所论。努力凌绝顶，列宿高可扪。\n\n大江自西来，潮势互飞翻。坡陀触潆洄，水石声相喧。\n\n于兹悟治理，扼要先蛟门。登顿跨龙脊，不觉烟岚昏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赭山' AND p.poem_author = '嵇曾筠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梧州归至龙门驿寄诸同志', '蓝智', '元代', '江转龙门一擢轻，归心不为杜鹃声。斜风细雨催离别，剩水残山管送迎。\n\n但使百蛮称镇静，久知四海望澄清。碧云日暮苍梧远，不尽怀人渺渺情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梧州归至龙门驿寄诸同志' AND p.poem_author = '蓝智';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杏林', '王鏊', '明代', '陆家园里千株杏，处处花开不待春。种树由来还种德，枝头颗颗总含仁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杏林' AND p.poem_author = '王鏊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书东寮壁', '吴与弼', '明代', '云卧东寮夜，寒装北返时。欲留他日迹，素壁更题诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书东寮壁' AND p.poem_author = '吴与弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('点绛唇 寄兴', '曹溶', '明代', '斜掩红窗，影迷前日桃花路。送春三度，只有人如故。\n\n瘦减腰围，每被征衫诉。归心误，雨声深处，江上扁舟暮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '点绛唇 寄兴' AND p.poem_author = '曹溶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('纳凉明', '刘敞', '宋代', '榻移随树影，杯侧见山岑。白鸟渴求水，玄蝉清噪林。\n\n道书无近语，天籁有遗音。向北新开径，行苔过竹阴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '纳凉明' AND p.poem_author = '刘敞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辛亥重九会安正堂', '韩琦', '宋代', '斯堂曾许占风光，须到重阳复命觞。坐上半非前岁客，杯中无改旧花香。\n\n初晴已过登高水，散虑宜趋自得场。唯有一时诗酒战，愿开强户振雄铓。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辛亥重九会安正堂' AND p.poem_author = '韩琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清河晓发', '金学莲', '清代', '城墙侵晓噪乌鸦，芦荻连天屋外斜。水落黄河全改岸，风晴白野半飞沙。\n\n车声绕路二三辆，酒店垂旗四五家。咫尺浊流犹待渡，褰裳依约上星查。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清河晓发' AND p.poem_author = '金学莲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和微之药名劝酒', '王安石', '宋代', '赤车使者锦帐郎，从客珂马留闲坊。\n紫芝眉宇倾一坐，笑语但闻鸡舌香。\n药名劝酒诗实好，陟厘为我书数行。\n真珠的皪鸣槽床，金罂琥珀正可尝。\n史君子细看流光，莫惜觅醉衣淋浪。\n独醒至死诚可伤，欢华易尽悲酸早，人间没药能医老。\n寄言歌管众少年，趁取乌头未白前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和微之药名劝酒' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题菊乡亭', '陈杰', '宋代', '晋朝徵士种菊处，满地苍云无古今。\n漫喜孤亭初结构，每怀高节此登临。\n南山日入输佳气，北阙天长驰寸心。\n瞻眺徘徊徒感慨，清风帘底坐鸣琴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题菊乡亭' AND p.poem_author = '陈杰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南墅十二诗 其九 山阴溪曲', '廖大圭', '元代', '清溪流绕碧㠝岏，便作山阴一样看。今日戴公何处在，满船风雪不知寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南墅十二诗 其九 山阴溪曲' AND p.poem_author = '廖大圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荆渚中流，回望巫山，无复一点，戏成短歌', '范成大', '宋代', '千峰万峰巴峡里，不信人间有平地。\n渚宫回望水连天，却疑平地元无山。\n山川相迎复相送，转头变灭都如梦。\n归程万里今三千，几梦即到石湖边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荆渚中流，回望巫山，无复一点，戏成短歌' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金陵其二', '李白', '唐代', '地拥金陵势。\n城回江水流。\n当时百万户。\n夹道起朱楼。\n亡国生春草。\n离宫没古丘。\n空余後湖月。\n波上对江洲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金陵其二' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('澳洲观感', '傅义', '当代', '南荒僻远岛，土著少而贫。与昔共驩辈，化如尧舜民。\n\n海风送恬梦，山木荫长春。猫犬承欢宠，依偎乐近人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '澳洲观感' AND p.poem_author = '傅义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三代门。又吟', '周昙', '唐代', '千妖万态逞妍姿，破国亡家更是谁。 \n 匡政必能除苟媚，去邪当断勿狐疑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三代门。又吟' AND p.poem_author = '周昙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游仙四首 其一', '郑学醇', '明代', '宫阙玲珑向晓开，有人云此是瑶台。梦中不记仙凡隔，听得鸾笙几奏回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游仙四首 其一' AND p.poem_author = '郑学醇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('扫花游·九日怀归', '周密', '宋代', '江蓠怨碧，早过了霜花，锦空洲渚。孤蛩暗语。正长安乱叶，万家砧杵。尘染秋衣，谁念西风倦旅。恨无据。怅望极归舟，天际烟树。\n心事曾细数。怕水叶沉红，梦云离去。情丝恨缕。倩回文为织，那时愁句。雁字无多，写得相思几许。暗凝伫。近重阳、满城风雨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '扫花游·九日怀归' AND p.poem_author = '周密';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('田舍视穫夕归', '欧大任', '明代', '明农及兹日，谷口出荆扉。夜柝传餐去，秋场获稻归。\n\n黄鸡啼月早，紫蟹受霜肥。最是村砧急，天寒木叶飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '田舍视穫夕归' AND p.poem_author = '欧大任';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沜东宴集值风雷大作', '王九思', '明代', '日暮俄吹万里风，西原牛马下巃嵷。震雷挟雨千峰黑，高岸飞花一涧红。\n\n扫兴顿教棋局散，停歌非为酒樽空。须臾玉宇还开霁，皓月留人意未穷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沜东宴集值风雷大作' AND p.poem_author = '王九思';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自清华西行村落间殊胜平畴流水果园竹径骤作乡思', '陆深', '明代', '燕麦青青柿叶肥，江南回首正依依。千竿新竹消苍雪，一带遥山深翠微。\n\n閒任野禽啼樾坞，细分流水绕柴扉。那知身是乘骢客，疑向花前跨鹤归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自清华西行村落间殊胜平畴流水果园竹径骤作乡思' AND p.poem_author = '陆深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵曾都曹喜雨', '黄庭坚', '宋代', '水旱国代有，人神理本通。\n偏雩祠小大，敢指蜺雌雄。\n地厌焚惔极，天回顾盼中。\n蛟龙起乖卧，星斗晦澄空。\n云挟雷声走，江翻电脚红。\n宠光归稼穑，滴沥在梧桐。\n詖讼犹相及，时霖恐未丰。\n洁斋蕲得岁，同病托诸公。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵曾都曹喜雨' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送李青归南叶', '李白', '唐代', '伯阳仙家子，容色如青春。日月秘灵洞，云霞辞世人。\n\n化心养精魄，隐几窅天真。莫作千年别，归来城郭新。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送李青归南叶' AND p.poem_author = '李白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵昌龄西园十咏 其七 杉', '王十朋', '宋代', '记得先人手自栽，森然千尺尽成材。翠丝结作思人树，它日儿孙岂忍摧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵昌龄西园十咏 其七 杉' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感事述怀，集杜二十首 其五', '陈肇兴', '清代', '乱离知又甚，留滞敢辞劳！壮惜身名晚，悲怜子女号。\n\n一旬半雷雨，八水散风涛。生死论交地，寸心铭佩牢。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感事述怀，集杜二十首 其五' AND p.poem_author = '陈肇兴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('竹坡丘知府哭子以偈寄之', '释居简', '宋代', '绝杨合为扬雄叹，无子当于伯道哀。尚有曾元养曾子，少宽夫子哭颜回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '竹坡丘知府哭子以偈寄之' AND p.poem_author = '释居简';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题画', '杨光仪', '清代', '一篱秋色印寒沙，风味柴桑处士家。不耐骑驴城里去，屋南山下踏槐花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题画' AND p.poem_author = '杨光仪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古意 其二', '屈大均', '明代', '风流水杨柳，宜水复宜风。莫即为花絮，飘飏西复东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古意 其二' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过鲁港驿和贯酸斋题壁', '萨都剌', '元代', '吴姬水调新腔改，马上郎君好风采。玉郎一去春草深，谩有狂名满江海。\n\n歌诗呼酒江上亭，墨花飞雨江不晴。江风吹破蛾眉月，我亦东南西北征。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过鲁港驿和贯酸斋题壁' AND p.poem_author = '萨都剌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('毛贞夫参政别予笼一白鹤与丹书一函见遗即席戏成二首答之 其二', '孙一元', '明代', '半世徒誇万卷功，埋头今作蠹鱼虫。元知天上多文字，云篆烟书更不同。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '毛贞夫参政别予笼一白鹤与丹书一函见遗即席戏成二首答之 其二' AND p.poem_author = '孙一元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感怀十首 其六', '崔荣江', '当代', '此身无骨重燕台，心与形骸并劫灰。浑璞曾经开璧玉，栋梁也许斫樗才。\n\n行藏悖世当多舛，白袷蒙尘自久哀。抽茧平生丝已乱，何机织就又重裁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感怀十首 其六' AND p.poem_author = '崔荣江';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梁园赏花四首 其一', '张弼', '明代', '鲜飙破阴阴复霁，柏屏槐盖凝花气。牡丹阑珊芍药芳，锦云遮花留青帝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梁园赏花四首 其一' AND p.poem_author = '张弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('下摄市', '乐雷发', '宋代', '吟到湘潭一叶黄，贾胡踪迹正悲凉。\n抱琴沽酒异乡客，打鼓发船何郡郎。\n楚女越商相杂沓，淮盐浙楮自低昂。\n尘埃市井无人识，濯足江头望八荒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '下摄市' AND p.poem_author = '乐雷发';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠友人游太学归东广', '黄廷用', '明代', '折柳怜春暮，调兰爱日长。燕云如点缀，粤树更微茫。\n\n双剑冲南斗，孤帆下夕阳。谈经曾壁水，梦寐圣宫墙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠友人游太学归东广' AND p.poem_author = '黄廷用';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题李淩洲为陈雨三画美人纨扇', '许南英', '清代', '淩洲道人老曹掾，丘壑胸中千万变。从来名士悦倾城，道人下笔开生面。\n\n肥环瘦燕是前身，石上含香想旧因。莫是汉宫同伴妒，昨宵谪贬落风尘？\n\n陈子无端生艳羡，乞画蛾眉入纨扇。祗爱空中见色身，岂真肉髅堪系恋？\n\n自从小劫历沧桑，廿年自据一胡床。美眷如花间列屋，好龙竟似沈诸梁。\n\n我正与君反比例，乞图作佛书揭谛。忏除结习净尘根，寡过未能思强制。\n\n目中有色心中无，如君亦自非凡夫！情丝到处如罗网，谁脱人间地狱图？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题李淩洲为陈雨三画美人纨扇' AND p.poem_author = '许南英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭内 其二', '许相卿', '明代', '偕老旧盟废，半生清影单。好名吾独累，分谤子能贤。\n\n泪咽垂髫女，吞声执手言。间关句曲路，忆著便潸然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭内 其二' AND p.poem_author = '许相卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归梦', '吴之章', '清代', '东南归路将千里，高滩急峡石齿齿。昼夜狂澜吼雷霆，客子坠心惊不已。\n\n舴艋戒严旬有余，及至抵家差足喜。昨夜扁舟何太轻，乘风破浪独扬舲。\n\n出江入江须顷刻，依稀叱驭驾长鲸。式遏倒卷乱流争，瘴烟净尽天廓清。\n\n到门稚子欢前迎，入觐庭闱喜不胜。山妻呼酒酌中庭，庭下黄花照眼明。\n\n绿醅酷带寒香冽，酣饮闻鸡催晓月。西风半夜撼树巅，惊悟方知梦飞越。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归梦' AND p.poem_author = '吴之章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('召伯水落', '孔平仲', '宋代', '朝落一寸水，暮落一寸水。卷水去入湖，更值南风起。\n\n舟行意虽急，滞碍乃如此。矗矗在吾前，千艘正衔尾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '召伯水落' AND p.poem_author = '孔平仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题进士郑良所藏画二首 其一 折梅枝', '邓林', '明代', '春到江南几许时，东风未报故人知。陇头便使何当发，欲折馨香寄一枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题进士郑良所藏画二首 其一 折梅枝' AND p.poem_author = '邓林';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游青城山', '杨可弼', '宋代', '我笑羊叔子，岘首矜一生。\n又怪谢阿客，伐山觅峥嵘。\n岂如铜梁守，出门便赤城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游青城山' AND p.poem_author = '杨可弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送叶尚书奉祠二首 其二', '刘克庄', '宋代', '身于七邑最孤寒，每辱黄堂刮眼看。乍可郡无九年蓄，要令民受一分宽。\n\n公闲去伴种司谏，我懒思寻靖长官。曾出龙门称弟子，感知惟有寸心丹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送叶尚书奉祠二首 其二' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日书怀', '王缜', '明代', '迟日轻风淑气融，柳花飞白小桃红。泛观万物全于我，细数三春半在公。\n\n修褉事阑知俗异，浴沂人远许谁同。年年东阁门墙里，一寸时光一寸功。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日书怀' AND p.poem_author = '王缜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('移兰', '释居简', '宋代', '莸劣薰优只自强，寄林亦足称孤芳。故应纫佩成春服，不为无人閟国香。\n\n移傍瘦筠同雨露，怕随行苇践牛羊。客非九畹同心事，莫反离骚吊碧湘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '移兰' AND p.poem_author = '释居简';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二月朔于鳞招饮二首 其二', '许邦才', '明代', '城头柳色望成堆，随送春风入酒杯。知己百年谁好在，花边那忍独醒回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二月朔于鳞招饮二首 其二' AND p.poem_author = '许邦才';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玄真院题画二首 其一', '张宁', '明代', '金阙琼楼虎豹关，蓬莱方丈五云间。登高一望秋无际，徐福楼船几日还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玄真院题画二首 其一' AND p.poem_author = '张宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('钦和御制江东桥诗 其一', '释宗泐', '明代', '玉作阑干石作梁，银河清夜共辉光。经营自出天工妙，锼琢仍归匠者良。\n\n大驾亲临观气象，群臣载拜献词章。谁知千古不磨迹，地久天长转更彰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '钦和御制江东桥诗 其一' AND p.poem_author = '释宗泐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宋九青给谏将联诗社诗以商之三首 其三', '郭之奇', '明代', '移风真首务，观世本文心。历探情声始，返思得失林。\n\n欲求人尽我，不令古无今。一往同孤尚，千秋讵可禁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宋九青给谏将联诗社诗以商之三首 其三' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游潘墺魏都冶墓庵', '舒岳祥', '宋代', '弄日微阴驾笋舆，柴桑五子共携扶。\n云门钟鼓先朝赐，丞相门庭近日殊。\n绿树两行溪贯串，青峦百摺路萦纡。\n惟余守冢鹰窠在，采捕令严无牧刍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游潘墺魏都冶墓庵' AND p.poem_author = '舒岳祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('简胡祭酒 其一', '杨士奇', '明代', '重阳醉后又三日，想见黄花绽始多。门巷深沈无俗客，高斋清坐养天和。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '简胡祭酒 其一' AND p.poem_author = '杨士奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寡妇诗', '曹植', '魏晋', '高坟郁兮巍巍。\n松柏森兮成行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寡妇诗' AND p.poem_author = '曹植';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('塞上', '曹松', '唐代', '边寒来所阔，今日复明朝。河凌坚通马，胡云缺见雕。 \n 砂中程独泣，乡外隐谁招。回首若经岁，灵州生柳条。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '塞上' AND p.poem_author = '曹松';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宿', '林季仲', '宋代', '万壑千岩簇马蹄，羞将尘鬓照清溪。晚云带雨东风急，无数飞花过竹西。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宿' AND p.poem_author = '林季仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('养心殿晚坐', '弘历', '清代', '园亭多水木，自是气清凉。宫禁翡翠瓦，五雉围红墙。\n\n夏候所弗宜，暖气蒸炎阳。朝仪讵可阙，适已宁云臧。\n\n兹来乃迥别，竟日爽风飏。立秋迟三日，律先报白藏。\n\n晨从郊外来，多稼云将黄。既欣望岁稔，且免筹边章。\n\n九州奏书达，云时若雨旸。诸凡皆顺吉，惟是敬不遑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '养心殿晚坐' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和柳子玉官舍十首之思山斋', '黄庭坚', '宋代', '吴儿心著吴山深，满目终南不开慰。\n有时蝉蜕书几边，梦到五湖千里外。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和柳子玉官舍十首之思山斋' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('太常引·广寒宫殿五云边', '汪元量', '宋代', '广寒宫殿五云边。看天上、烛金莲。香袅御炉烟。拥彩仗、千官肃然。世间王母，月中仙子，花甲一周天。乐指沸华年，更福寿，千年万年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '太常引·广寒宫殿五云边' AND p.poem_author = '汪元量';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('象州道中二首 其一', '李纲', '宋代', '路入春山春日长，穿林渡水意徜徉。溪环石笋横舟小，风落林花扑面香。\n\n山鸟不知兴废恨，岭云自觉去来忙。炎荒景物随时好，何必深悲瘴疠乡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '象州道中二首 其一' AND p.poem_author = '李纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵学士兄春日谩成', '李弥逊', '宋代', '飘泊悲生事，人情翻手云，\n习闲真似懒，补拙谩知勤。\n老作渔樵计，梦观钟鼎动。\n成亏皆一戏，不复问斯文。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵学士兄春日谩成' AND p.poem_author = '李弥逊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谷雨江右诗社周年萍乡小石源雅集 其四 游孽龙洞有感其更名为义龙洞用进退格', '陈忠平', '当代', '一洞幽深鱼贯行，眼前顽石幻奇形。或为虾鳖依崖立，曾佐龙蛇倒海惊。\n\n过处阴风犹凛冽，当年恶迹渐零星。也无轻怪后来者，竟把妖邪冠义名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谷雨江右诗社周年萍乡小石源雅集 其四 游孽龙洞有感其更名为义龙洞用进退格' AND p.poem_author = '陈忠平';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠别陈子', '申佳允', '明代', '悠悠滏水梦，落落剡溪舟。竹乱连床雨，灯悬一榻秋。\n\n奚囊诗草黯，客舍墨香浮。前路谁知己，天涯破阮愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠别陈子' AND p.poem_author = '申佳允';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵晚香西兴', '缪祐孙', '清代', '鼓吹夕阳天，迎宾小驿船。云容垂远溆，人语隔秋烟。\n\n柝击长街肃，镫悬使馆圆。独欣前事在，郭李说登仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵晚香西兴' AND p.poem_author = '缪祐孙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题欧阳炳文真止亭', '刘才邵', '宋代', '前浪与后浪，推引不自休。谁知桥下水，终古何曾流。\n\n喧寂两俱遣，已自非良谋。避喧趋寂者，岂免一处收。\n\n吾人识真际，不向中边求。聊复起小亭，对此竹桧幽。\n\n云烟互明灭，草木自春秋。诸法如露电，乾坤一浮沤。\n\n试看究竟处，还有起灭不。想当隐几时，萧然任天游。\n\n不同习枯禅，兀兀守一丘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题欧阳炳文真止亭' AND p.poem_author = '刘才邵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('张用宜丹房十咏 其八 丹灶', '徐庸', '明代', '炼就芙蓉丹，满灶春如海。我欲到君家，分来驻颜彩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '张用宜丹房十咏 其八 丹灶' AND p.poem_author = '徐庸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水龙吟 和郑彦章韵', '王沂', '元代', '画檐疏雨才收，酒醒凝掩篷窗卧。薰炉火冷，余香犹在，拥衾清坐。\n\n点鬓霜明，窥人月小，短擎花堕。想吴山越水，楼台缥缈，应曾有，飞鸿过。\n\n寂寞文园病后，旧心情、苦无些个。多君调我，幽兰新句，纹笺玉唾。\n\n花落元都，鹤归华表，梦谁擎破。待莼鲈江上，高歌小梅，扣舷相和。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水龙吟 和郑彦章韵' AND p.poem_author = '王沂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日郊行 其六', '弘历', '清代', '烟磴盘盘夹树斜，离宫邻是梵王家。桃花也解将迎意，对客先霏岭上霞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日郊行 其六' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠枢上人', '陈宓', '宋代', '心期极乐三千界，世事怀安二十年。顾我未能从学道，祇将寂寞当幽禅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠枢上人' AND p.poem_author = '陈宓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东坡八首，并叙 其二', '苏轼', '宋代', '荒田虽浪莽，高庳各有适。下隰种粳稌，东原莳枣栗。\n\n江南有蜀士，桑果已许乞。好竹不难栽，但恐鞭横逸。\n\n仍须卜佳处，规以安我室。家僮烧枯草，走报暗井出。\n\n一饱未敢期，瓢饮已可必。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东坡八首，并叙 其二' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郊居', '朱硕熏', '明代', '结屋临溪水，悠然心自闲。泉分杯底月，云共枕前山。\n\n芳树经春合，幽禽薄暮还。邻人借渔钓，嗑尔款柴关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郊居' AND p.poem_author = '朱硕熏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄丰叔良（二首）', '陶安', '明代', '阿咸九月到，寄我尺书看。\n尽日不释手，空江频倚栏。\n乡山微雨外，客梦一窗寒。\n遥想林泉胜，无忧寝食安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄丰叔良（二首）' AND p.poem_author = '陶安';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('胡家窝铺', '戴亨', '清代', '险溺胡家铺，行人莫不闻。地顽常带卤，山蠢不生云。\n\n草滑埋蛇穴，风腥过虎群。往来经此处，踯躅畏斜曛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '胡家窝铺' AND p.poem_author = '戴亨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古二十四首', '释宗演', '宋代', '今朝十月十五，有误诸人来此。\n山僧口似匾担，说禅烦拄杖子。\n一击忘所知，更不假修持。\n黑蛇当大路，狮子逞全威。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古二十四首' AND p.poem_author = '释宗演';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('用韵答游司直见寄', '洪咨夔', '宋代', '道在皇王帝霸间，古今同是一人寰。\n不愁垂白三千丈，独喜飞黄十二闲。\n晚桂荐花熏鼎古，寒松堕子茗瓯斑。\n山中风味无人会，赖得新诗起老顽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '用韵答游司直见寄' AND p.poem_author = '洪咨夔';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南斋竹三绝 其三', '苏辙', '宋代', '里中佳客旧孙陈，我自疏慵不见人。目倦细书长掩卷，心游法界四无邻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南斋竹三绝 其三' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游灵岩山', '陈伟强', '当代', '吴王宫化梵王宫，古木森森落晚钟。凤屧不来香径冷，野蜂飞上玉芙蓉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游灵岩山' AND p.poem_author = '陈伟强';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过应山县吊杨忠烈公', '乔莱', '清代', '呜呼！有明神宗之季国卼臲，光宗继之更短折。维时先生官给事，顾命乃与大臣列。\n\n防微肩巨定大计，选侍移宫一朝决。再起中丞赴双阙，大柄已被阉人窃。\n\n干儿义孙满庙廊，二十四罪愤所切。赤县争高宦者祠，彤庭遍染中丞血。\n\n讵有婪赃杨大洪，舍人宁死心如铁。或言汉之厨顾洁其名，唐之牛李营其穴。\n\n宋之洛蜀明东林，党祸纷纷蹈覆辙。封疆已被门户误，遂讥先生太激烈。\n\n我谓此言殊不然，藉口保身附明哲。假使当年稍媕婀，张禹孔光更何别？\n\n君子岂能误国家，目为党人正气绝。呜呼！正气绝，国乃灭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过应山县吊杨忠烈公' AND p.poem_author = '乔莱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吕城待闸得陈魏二生晤语', '陈造', '宋代', '吕城望奔牛，道里不作远。\n徙倚不容前，奈此河流浅。\n窘步客怀恶，痴坐仆夫倦。\n班荆得两生，晤语忘旦晚。\n文卷得细披，汤饼亦粗办。\n生须朋从乐，时亦慰连蹇。\n长吟行路难，回首偶耕原。\n卜邻傥君等，老我幸无怨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吕城待闸得陈魏二生晤语' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('示学人三十首 其二十二', '释函可', '明代', '江海本无波，飙风不停吹。我心与境接，日夜纷交驰。\n\n若了心境幻，彼此不相知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '示学人三十首 其二十二' AND p.poem_author = '释函可';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其二', '蒲宗孟', '宋代', '圣名不敢居，民誉日益美。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其二' AND p.poem_author = '蒲宗孟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送杜方伯入觐 其三', '霍与瑕', '明代', '暮春三月，东征孔棘。方伯维之，饷馈有绎。四月之夏，柘林为逆。\n\n薄于城下，民罹其贼。脂民肝骨，远迩躅踯。峨峨大舰，烧焚靡孑。\n\n方伯图之，毕举群策。以佐元老，驱除荡涤。是底嘉绩，危城以磐石。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送杜方伯入觐 其三' AND p.poem_author = '霍与瑕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戏方仁声四绝句 其三', '叶梦得', '宋代', '不惜囊钱信手空，荒田却拟望年丰。天公可是怜风月，判遣诗人一例穷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戏方仁声四绝句 其三' AND p.poem_author = '叶梦得';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('斋居感兴二十首 其十二', '林光', '明代', '诸儒喜著述，兀兀研谬讹。至近而神驰，精彩日消磨。\n\n赋生本有涯，无涯将奈何。元首易丛脞，试听虞廷歌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '斋居感兴二十首 其十二' AND p.poem_author = '林光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('白纻歌九首 其一', '张率', '南北朝', '歌儿流唱声欲清。舞女趁节体自轻。歌舞并妙会人情。\n\n依弦度曲婉盈盈。扬蛾为态谁目成。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '白纻歌九首 其一' AND p.poem_author = '张率';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('史丞相生辰 其一', '喻良能', '宋代', '姓名久已覆金瓯，一品师臣德业优。黼扆尚询黄发旧，衮衣难伴赤松游。\n\n松筠劲节高三事，桃李浓阴遍九州。萧叶杨门端可继，只今衮衮富公侯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '史丞相生辰 其一' AND p.poem_author = '喻良能';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('己亥腊月朔自匡庐之九江', '祁顺', '明代', '彭蠡通南北，开篷见万艘。雪消山翠重，水落石痕高。\n\n吴楚风烟阔，江湖岁月劳。往来吟思苦，赢得鬓刁骚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '己亥腊月朔自匡庐之九江' AND p.poem_author = '祁顺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨后', '马一浮', '现代', '三伏炎蒸一雨收，应驱少昊早行秋。\n深山石上看飞瀑，多少鱼龙据下流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨后' AND p.poem_author = '马一浮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四月望再游西湖十首 其一', '陈造', '宋代', '前时小舫冒氛昏，重到轻桡破曲尘。湖面风烟饱姿态，一番到眼一番新。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四月望再游西湖十首 其一' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('太庙灵芝产于仁宗皇帝英宗皇帝两室前楹芝上有文成王字臣叨陪政府得预荣观谨课成律诗二首 其一', '张纲', '宋代', '吾皇圣德绍先猷，清庙华芝屡降休。道盛百王神画验，祥开两室化功侔。\n\n牺尊影照彤云聚，藻棁光连瑞气浮。愿诏乐章歌伟迹，更从来岁荐郊丘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '太庙灵芝产于仁宗皇帝英宗皇帝两室前楹芝上有文成王字臣叨陪政府得预荣观谨课成律诗二首 其一' AND p.poem_author = '张纲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('简陆务观史君编修二首', '杨万里', '宋代', '闻道云间陆士龙，钓台绝顶啸清风。\n却将半掬催诗雨，洒入山村作岁丰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '简陆务观史君编修二首' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题刘真君祠', '洪朋', '宋代', '冠挂谢埃雾，云乘上杳冥。棠阴空五马，榆彩杂繁星。\n\n圜叶馀神界，华林隐翠屏。锦帏渺经纬，宝舄绝仪形。\n\n旧井金丹閟，层坛玉露零。千秋想灵气，何许仰天庭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题刘真君祠' AND p.poem_author = '洪朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('息虑轩诗', '饶节', '宋代', '雨暗藤经屋，春深草到门。客来非问字，鹤老不乘轩。\n\n花气翻诗思，松声撼醉魂。呼儿换香鼎，趺坐竟黄昏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '息虑轩诗' AND p.poem_author = '饶节';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题邓寨周氏小园', '王之望', '宋代', '径草荒春绿作堆，东风深入小园来。\n可怜几阵嫣香裹，立尽庭前数树梅。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题邓寨周氏小园' AND p.poem_author = '王之望';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题沈氏酒垆四首 其二', '蒋春霖', '清代', '玉钗金缕都抛却，烽火仓皇道路閒。自是何郎轻国事，教人愁听念家山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题沈氏酒垆四首 其二' AND p.poem_author = '蒋春霖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵宋尚书山居十五咏 其七 茶岩', '方岳', '宋代', '壑底云香不等雷，便携石鼎与俱来。鹁鸠唤得西溪雨，顿得春从齿颊回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵宋尚书山居十五咏 其七 茶岩' AND p.poem_author = '方岳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('林均州招饮沧浪亭席上口占同席王杨两孝廉余门人东官黄于广', '叶春及', '明代', '路迷江汉百愁生，亭入沧浪一棹轻。鼓枻偶闻渔父唱，濯缨宁比使君清。\n\n层崖雨过芙蓉湿，曲岸烟开翡翠明。尘满素衣归未得，石泉空负故山盟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '林均州招饮沧浪亭席上口占同席王杨两孝廉余门人东官黄于广' AND p.poem_author = '叶春及';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('漫书呈仲谋', '黄庭坚', '宋代', '漫来从宦著青衫，秣马何尝解辔衔。\n眼见人情如格五，心知外物等朝三。\n经时道上冲风雨，几日樽前得笑谈。\n赖有同僚慰羁旅，不然吾已过江南。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '漫书呈仲谋' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其四', '薛瑄', '明代', '万家城郭通州市，十里帆樯潞水船。清晓登舻望京国，凤凰楼阁五云边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其四' AND p.poem_author = '薛瑄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('除夕', '刘诜', '元代', '疏雨孤灯夜，相看又岁除。江山犹寓客，亲友绝来书。\n\n新酒初堪酌，长愁未暂疏。艰难吾敢恨，百岁定何如。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '除夕' AND p.poem_author = '刘诜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再用韵三首贻文举训导 其三', '郑真', '明代', '皋比掌教本非才，苜蓿盘空几席埃。帝阙仰瞻三殿出，仙山遥望五云开。\n\n多烦上客公车过，共迓先生聘币来。藻頖生香冠佩集，锦篇新儗柏梁台。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再用韵三首贻文举训导 其三' AND p.poem_author = '郑真';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('踏莎行　半梦庐饯新河分韵得燕字', '寇梦碧', '近代', '月底箫沉，梅边笛换，独将冷拍支残艳。新红翻作殿春花，旧巢犹有衔泥燕。\n\n饯梦杯深，题香烛短，白头惜别情无限。明朝准拟赋游仙，紫鸿双驾淩云汉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '踏莎行　半梦庐饯新河分韵得燕字' AND p.poem_author = '寇梦碧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵弟观过黄山', '陈著', '宋代', '晓雨才收数点轻，江云未放十分晴。舟行曲港难为纤，峰有佳山莫问程。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵弟观过黄山' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东轩小室即事五首', '曾几', '宋代', '卷书坐东轩，有竹甚魁伟。\n清风过其间，戛戛鸣不已。\n写之以素琴，音节淡如水。\n不惜为人弹，临流须洗耳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东轩小室即事五首' AND p.poem_author = '曾几';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和许太常道中家园成趣轩韵', '郭登', '明代', '君家三径几时开，千个长松绕屋栽。\n把钓每从溪上去，题诗还傍竹间来。\n梦阑石枕月相对，花落柴关风自推。\n有约频过寻贺老，莫教空棹酒船回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和许太常道中家园成趣轩韵' AND p.poem_author = '郭登';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄蒋攸县砺二首', '赵蕃', '宋代', '君家三径开来久，不待弦歌始得资。\n傥欲赋归归便得，湘山越岭匪逶迟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄蒋攸县砺二首' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟中杂兴 其十四', '王洪', '明代', '墟里郁相望，田家多荜门。牧豕向大泽，维舟来远村。\n\n麦苗沙上秀，烟火雨中昏。赖有同袍者，幽怀喜共言。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟中杂兴 其十四' AND p.poem_author = '王洪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留别江陵王少府', '张籍', '唐代', '迢迢山上路，病客独行迟。况此分手处，当君失意时。 \n 寒林远路驿，晚烧过荒陂。别后空回首，相逢未有期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留别江陵王少府' AND p.poem_author = '张籍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('甲午除夜', '元好问', '元代', '暗中人事忽推迁，坐守寒灰望复燃。\n已恨太官余曲饼，争教汉水入胶船？\n神功圣德三千牍，大定明昌五十年。\n甲子两周今日尽，空将衰泪洒吴天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '甲午除夜' AND p.poem_author = '元好问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚泊鸥潭', '韩日缵', '明代', '偶此泊鸥潭。矶头傍古岩。鸥群閒自戏，潭影净于蓝。\n\n远渚晴岚润，孤舟夕照衔。机忘相上下，狎尔羽毵毵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚泊鸥潭' AND p.poem_author = '韩日缵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿冯北部', '颜太初', '宋代', '五百年终遘圣朝，相门何日降英髦。\n星杓影射金枢正，月魄光浮碧汉高。\n三世密传张颢印，贰车新得吕虔刀。\n他年善继良弓慕，金字重重有赐袍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿冯北部' AND p.poem_author = '颜太初';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪溪仙隐', '楼钥', '宋代', '君之生兮天之西，望雪山兮名之以雪溪。君之游兮海之湄，隐于雪窦兮杳然何归。\n\n子从其父兮孙访吾祖，子志不遂兮孙之心良苦。\n\n嗟嗟，阆中君兮弃家而远游，蹇胡为乎不久留。其遂蝉蜕尘埃而仙耶，其亦肥遁得道不死而隐于四窗之幽耶。\n\n扪萝以寻于烂平兮既不可见，莽白云之廿里兮欲进兮焉求。\n\n青棂兮实繁，莎罗兮花稠。鞠侯兮相与群，白鹇兮啸其俦。\n\n谓为远兮何景物之良是，谓在迩耶将径之何由。\n\n肖君像兮兹堂，谨奉尝兮良畴。君其来兮庶几其见之，君之不来兮徒相羊以夷犹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪溪仙隐' AND p.poem_author = '楼钥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答兄平原诗', '陆云', '魏晋', '悠悠涂可极。\n别促怨会长。\n衔思恋行迈。\n兴言在临觞。\n南津有绝济。\n北渚无河梁。\n神往同逝感。\n形留悲参商。\n衡轨若殊迹。\n牵牛非服箱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答兄平原诗' AND p.poem_author = '陆云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('张迪功携诗见过次韵谢之二首', '陈与义', '宋代', '黄纸红旗意未阑，青衫俱不救饥寒。\n久荒三径未得返，偶有一钱何足看。\n世事岂能磨铁砚，诗盟聊吉歃铜盘。\n不嫌野外时迂盖，政要相从叩两端。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '张迪功携诗见过次韵谢之二首' AND p.poem_author = '陈与义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('双雁儿', '汪东', '清代', '淙淙雪水溜阶渠。晓日淡，晚风粗。闭门閒读道家书。\n\n精中观，摄万珠。\n\n运行无极亦须臾。仗斗酒，到华胥。置身浑似邃皇初。\n\n任峥嵘，岁又除。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '双雁儿' AND p.poem_author = '汪东';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('滇南胜境', '许湜', '清代', '振顿心神碎，林峦忽霁颜。天开松岭小，家近马蹄间。\n\n落日低平楚，飞鸦度远山。昨宵风雨客，黯淡宿黔关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '滇南胜境' AND p.poem_author = '许湜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋早出太平堤', '卢宁', '明代', '城外长堤散九皋，西风跨马看鸿毛。玄湖日破浪花出，钟阜烟晞气彩高。\n\n绿拥双林迷册府，清分三路入秋曹。化深南国无多讼，按辔逍遥拽锦袍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋早出太平堤' AND p.poem_author = '卢宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闺怨一百二十首 其一一七', '孙蕡', '明代', '春铅数日不曾施，贴翠涂黄只半时。为报小环休写月，且教留着澹双眉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闺怨一百二十首 其一一七' AND p.poem_author = '孙蕡';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百二十三首 其七十七', '释普度', '宋代', '露滴滴，风凄凄。黄花香满路，何独在东篱。高低普应，步步相随。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百二十三首 其七十七' AND p.poem_author = '释普度';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('至第四铺二首', '梅尧臣', '宋代', '轻舟已过第四铺，忆著阳关末尾声。\n怊惆杜公行底急，白醪何处得同倾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '至第四铺二首' AND p.poem_author = '梅尧臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和介溪赏莲', '陆深', '明代', '雨气自天香冉冉，风光临水碧飔飔。移来玉井仙人掌，开傍金波太液池。\n\n本为怜芳衙散早，翻因解语酒行迟。新欢旧赏年华里，倚遍阑干有所思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和介溪赏莲' AND p.poem_author = '陆深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('孟尝君度关图', '郑思肖', '宋代', '狐白裘边事若难，孟尝门下亦何颜。若无意智翻身去，半夜焉能度此关。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '孟尝君度关图' AND p.poem_author = '郑思肖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('望江南', '黄公绍', '宋代', '思晴好，春透海棠枝。刻惜许多过时了，可怜生是我来迟。不见软红时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '望江南' AND p.poem_author = '黄公绍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('贤者之孝二百四十首 其一四八 许孜', '林同', '宋代', '能感猛鸷类，都无搏噬心。同游至鹿虎，共宿有鸠鹰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '贤者之孝二百四十首 其一四八 许孜' AND p.poem_author = '林同';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄史允叟', '袁桷', '元代', '故国王孙佩碧兰，春去凉月倚朱阑。\n玉箫曲趁莺声转，金鼎香随蝶梦残。\n碧沚波清堪把钓，黄尘风急倦弹冠。\n外家文采惟君在，笑我冰髭跨晓鞍。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄史允叟' AND p.poem_author = '袁桷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('朱明洞景八首 其六 种菊东篱', '卢龙云', '明代', '自爱篱边菊，餐英待晚芳。盈樽多秫酒，客坐但传觞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '朱明洞景八首 其六 种菊东篱' AND p.poem_author = '卢龙云';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚望', '周权', '元代', '帖帖平畴稻未黄，疏烟老树带秋光。山钟敲断前村雨，一两归鸦背夕阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚望' AND p.poem_author = '周权';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('承田地曹见邀先至西湖保叔寺候任侍御张冬官偶赋', '林光', '明代', '肩舆轧轧傍湖弦，贪爱春光在客先。山色忽开心里景，湖波摇荡镜中天。\n\n梅花惯识林和靖，樽酒堪呼李谪仙。一勺山腰泉未试，迫人诗思满云烟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '承田地曹见邀先至西湖保叔寺候任侍御张冬官偶赋' AND p.poem_author = '林光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('留别吴门诸子二首 其二', '严启煜', '清代', '背花宁待管弦终，归卧云林半亩宫。世外渔樵有真趣，山间鸡犬尽淳风。\n\n采松袖染秋岚碧，捣药窗留夜火红。他日皋桥明月里，故人应共念梁鸿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '留别吴门诸子二首 其二' AND p.poem_author = '严启煜';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('汉光武庙', '韩元吉', '宋代', '涿郡渔阳此呼分，用兵诸将总如神。\n白头浪说关中事，邓禹当年已笑人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '汉光武庙' AND p.poem_author = '韩元吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟中', '李流谦', '宋代', '帆风不饱橹声迟，正是波平月上时。\n今夜不知何处泊，买鱼枯酒犒舟师。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟中' AND p.poem_author = '李流谦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('建炎己酉十二月五日避乱鸽湖山十绝句 其六', '王庭圭', '宋代', '洞里花开透碧霄，溪横三绕赤栏桥。他年桥断人迷路，咫尺山源万里遥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '建炎己酉十二月五日避乱鸽湖山十绝句 其六' AND p.poem_author = '王庭圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同坐客赋席牡丹酴醿海棠三首', '李弥逊', '宋代', '品题芳事有春工，姚魏风流胜浅红。\n莫傍沉香亭北看，只宜卮酒对山翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同坐客赋席牡丹酴醿海棠三首' AND p.poem_author = '李弥逊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自和山房十咏 其三', '李曾伯', '宋代', '坡翁昔爱是山中，我以何人敢比踪。筑室买田居此了，闭门读易保吾终。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自和山房十咏 其三' AND p.poem_author = '李曾伯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄吴少溪宫录七十 其三 寄送林太华民部报命北上', '于慎行', '明代', '倾盖长安意颇亲，山城重枉驻征轮。两河使节归仙吏，一代家声属世臣。\n\n路入五云关树晓，赋成双管禁林春。郎曹纵自多文雅，谁许青箱事可陈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄吴少溪宫录七十 其三 寄送林太华民部报命北上' AND p.poem_author = '于慎行';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('第一百六十七', '文天祥', '宋代', '阴风千里来，惊浪满吴楚。\n世事两茫茫，飘泊欲谁诉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '第一百六十七' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('落花诗三十首 其七 七虞', '邓云霄', '明代', '石家别业洛城隅，昔日风光近有无。不见留欢围锦障，但闻如意碎珊瑚。\n\n香消谷口春泉冷，人堕楼头夜月孤。试过遗基望残景，数株芳树带平芜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '落花诗三十首 其七 七虞' AND p.poem_author = '邓云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵和梁才甫与曾叔夏喜雨', '王安中', '宋代', '金节经过玉帐开，初筵风雨烛花摧。凤凰池外浓云合，獬豸冠前爽气来。\n\n已洗郊原秋淡荡，不妨星月夜昭回。拾遗说尹村村到，盛看丰年社酒杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵和梁才甫与曾叔夏喜雨' AND p.poem_author = '王安中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闲居 其五', '释行海', '宋代', '绕岸奇峰半没烟，满窗凉影竹涓涓。双鸠并睡枯桑上，一鹭闲行白水边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闲居 其五' AND p.poem_author = '释行海';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二十二日玉笥梦', '罗伦', '明代', '关山一只雁，霄汉两三峰。借问门前水，依然万折东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二十二日玉笥梦' AND p.poem_author = '罗伦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('醉乡', '陈献章', '明代', '管勾仙家碧酒春，醉乡今日属何人。天高地迥无人到，试就陶潜一问津。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '醉乡' AND p.poem_author = '陈献章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自嘲', '林大春', '明代', '翠竹迎风舞，山童见客呼。如何清夜月，清兴半分无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自嘲' AND p.poem_author = '林大春';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('少游荆湘因有是题', '沈佺期', '唐代', '岘北焚蛟浦，巴东射雉田。岁时宜楚俗，耆旧在襄川。 \n 忆昨经过处，离今二十年。因君访生死，相识几人全。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '少游荆湘因有是题' AND p.poem_author = '沈佺期';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏秦始皇兵马俑', '何满子', '近代', '六合已横扫，何须地下军。干戈区宇息，图匕梦魂惊。\n\n嗣子鹿迷马，遗尸臭杂腥。徒凭黔首力，奇迹世无伦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏秦始皇兵马俑' AND p.poem_author = '何满子';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题东西二梁山三首', '杨万里', '宋代', '传道临春昔丽华，不从陈帝入隋家。\n独将亡国千年恨，留下双颦寄岸花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题东西二梁山三首' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('村居 其三', '董兆熊', '清代', '东冈有田舍，云是隐君门。障日借邻树，避人居远村。\n\n用悭囊讳涩，汲少井难浑。吾欲从之往，相依长子孙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '村居 其三' AND p.poem_author = '董兆熊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夫人閤端午帖子 其二', '胡宿', '宋代', '天家饶物采，华节有光辉。明月裁歌扇，轻霞剪舞衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夫人閤端午帖子 其二' AND p.poem_author = '胡宿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花 其一 次韵少游二乔观书图', '王士禄', '清代', '倾鬓颓云肩亸玉。髹几光凝，双映修蛾绿。仿佛风光屏外足。\n\n摊书停却寻春躅。\n\n炉里双烟青断续。玉砌红帘，不似牵萝屋。公瑾伯符皆不俗。\n\n知无一事萦心曲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花 其一 次韵少游二乔观书图' AND p.poem_author = '王士禄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过济宁怀李白', '谢廷柱', '明代', '清风楼上客，独忆谪仙人。海岳元无恙，文章自有神。\n\n倾樽一吊古，搔首几迷津。忽动乘槎兴，飘然遍八垠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过济宁怀李白' AND p.poem_author = '谢廷柱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登湖光亭', '韩维', '宋代', '雪尽尘消径露沙，公家池馆似山家。\n翠痕满地初生草，红气通林夫放花。\n匝岸平波清照雁，压城危榭斗回鸦。\n自惭白首犹圭组，此地年年常物华。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登湖光亭' AND p.poem_author = '韩维';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('古寺老松', '齐己', '唐代', '百岁禅师说，先师指此松。小年行道绕，早见偃枝重。 \n 月槛移孤影，秋亭卓一峰。终当因夜电，拏攫从云龙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '古寺老松' AND p.poem_author = '齐己';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春雪早朝和沈编校', '刘攽', '宋代', '晓寒初怪客衣重，隐约钟声长乐宫。出户万家横雪里，止车双阙秀云中。\n\n退朝禁柳迎人绿，寓直庭花向日红。纵使著书嘲尚白，会应华发兆非熊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春雪早朝和沈编校' AND p.poem_author = '刘攽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('无事自遣', '宋辅仁', '近代', '独坐藤阴院，无聊自检书。瓮头新酒熟，问有客来无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '无事自遣' AND p.poem_author = '宋辅仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('独漉篇', '赵南星', '明代', '独漉独漉，波腾鱼伏。\n鱼伏欲起，波腾不已。\n翩翩孤鸿，徘徊云汉。\n我欲折芦，为子周患。\n远望长林，林木有枝。\n客子无言，中心则悲。\n干将绣涩，时时自鸣。\n宵练在掌，过者不惊。\n猛虎入邑，其粮以人。\n劲弩櫜藏，请之鬼神。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '独漉篇' AND p.poem_author = '赵南星';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂一百五十首 其一四八', '释心月', '宋代', '溪山送别出门日，云水相迎得路时。七佛轨仪持钵去，满船载得月明归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂一百五十首 其一四八' AND p.poem_author = '释心月';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('发新安后途中寄卢中丞二首', '赵嘏', '唐代', '楼上风流庾使君，笙歌曾醉此中闻。 \n 目前已是陵阳路，回首丛山满眼云。 \n 晚树萧萧促织愁，风帘似水满床秋。 \n 千山不碍笙歌月，谁伴羊公上夜楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '发新安后途中寄卢中丞二首' AND p.poem_author = '赵嘏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('归自东山', '缪公恩', '清代', '驱车入平陆，人在万山西。野旷飘风急，云昏落日低。\n\n孤烟横远坞，古渡锁寒溪。遥指高城近，疏镫树影迷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '归自东山' AND p.poem_author = '缪公恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('亲友冯仪之运干挽章三首 其二', '曹彦约', '宋代', '有学关时用，无心与物驰。已称黄发老，犹似綵衣时。\n\n世道空机阱，襟期自坦夷。只今风月夜，犹足想清规。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '亲友冯仪之运干挽章三首 其二' AND p.poem_author = '曹彦约';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵酬吴天彝太守惠笋', '谢迁', '明代', '急电催雷起蛰龙，龙孙无数湿云笼。渭川已在封疆外，嶰谷须归律吕中。\n\n玉版拟参开石路，锦绷初解散林风。分甘多谢清贫守，满荐春盘压晚菘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵酬吴天彝太守惠笋' AND p.poem_author = '谢迁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蝶恋花·碧落秋风吹玉树', '晏几道', '宋代', '碧落秋风吹玉树，\n翠节红旌，晚过银河路。\n休笑星机停弄杼，凤帏已在云深处。\n\n楼上金针穿绣缕，\n谁管天边，隔岁分飞苦。\n试等夜阑寻别绪，泪痕千点罗衣露。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蝶恋花·碧落秋风吹玉树' AND p.poem_author = '晏几道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉楼春 其二 八月宿姜真源宪使后院夜饮同小农汝旦作', '毛奇龄', '清代', '红蕖小幕开深槛。微雨乍收凉漏浅。酒淹垆火带霜吹，风搅浊油和烟剪。\n\n银船交泛明河转，玉树当轩共婉娈。夜深空忆广陵涛，水绕曲江知近远。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉楼春 其二 八月宿姜真源宪使后院夜饮同小农汝旦作' AND p.poem_author = '毛奇龄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送蜀郡李掾', '岑参', '唐代', '饮酒俱未醉，一言聊赠君。功曹善为政，明主还应闻。 \n 夜宿剑门月，朝行巴水云。江城菊花发，满道香氛氲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送蜀郡李掾' AND p.poem_author = '岑参';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('听罗道士琴 其二', '文天祥', '宋代', '吾闻泗滨磬，暗含角与徵。又闻天乐泉，净洗筝笛耳。\n\n如何碧一泓，乃此并二美。蓝田沧海意，请问玉溪子。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '听罗道士琴 其二' AND p.poem_author = '文天祥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('潮春攻城解围志感 其三', '赖时辉', '清代', '义勇堪嘉锡县名，自前众志已成城。连攻不落惟斯邑，屡困能通赖众擎。\n\n更有褒忠乡媲美，尽多赏恤泽荣膺。重重浩劫疲奔命，谱入新诗老泪横。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '潮春攻城解围志感 其三' AND p.poem_author = '赖时辉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('草阁', '申颋', '清代', '草阁著书罢，长林秋色闲。尘喧不到处，庭户若空山。\n\n片雨随风过，残云带鸟还。萧然无所事，双手纳怀闲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '草阁' AND p.poem_author = '申颋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题齐安城楼', '杜牧', '唐代', '呜轧江楼角一声，微阳潋潋落寒汀。\n不用凭栏苦回首，故乡七十五长亭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题齐安城楼' AND p.poem_author = '杜牧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和梅花百咏诗 其二十一 别梅', '王夫之', '明代', '离筵及早酌屠苏，留看镫宵待得无。知有前期霜信后，小窗人奈雪侵须。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和梅花百咏诗 其二十一 别梅' AND p.poem_author = '王夫之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其一', '范百禄', '宋代', '携月入上清，一览无馀山。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其一' AND p.poem_author = '范百禄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题春江送别图', '郭钰', '元代', '君上孤舟妾上楼，望中烟雨意中愁。江波若会离情苦，一夜东风水倒流。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题春江送别图' AND p.poem_author = '郭钰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('崧高诗为九江赵使君寿', '杨冠卿', '宋代', '柔惠且直，小心翼翼。\n王亲命之，南国是式。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '崧高诗为九江赵使君寿' AND p.poem_author = '杨冠卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('铁珊瑚', '吴德功', '清代', '铁树生苍古，槎枒数尺高。枝柯盘柱砥，骨干类珊瑚。\n\n屈曲叉文笔，崚嶒击唾壶。陶镕逢世用，沧海网遗珠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '铁珊瑚' AND p.poem_author = '吴德功';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答杨式公', '成鹫', '明代', '红尘紫陌偶相期，蹑屐登龙快所思。山径有云归路晚，市门斜日下楼迟。\n\n漫劳轩盖遥相问，暂寄茅堂只在兹。他日幽栖还有计，千峰平处一峰奇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答杨式公' AND p.poem_author = '成鹫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('黄去非先生以四川县令内升比部主事进京相晤话旧感成长句', '敦敏', '清代', '百里何能滞祖鞭，徵书群识汝南贤。剑关远自七千里，燕市重逢十四年。\n\n清级曹纲新紫绶，遗编蠹简旧青毡。虎门绛帐遥回首，深愧传经负郑玄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '黄去非先生以四川县令内升比部主事进京相晤话旧感成长句' AND p.poem_author = '敦敏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和施通判以诗惠茶', '王庭圭', '宋代', '綵笔题誇北苑春，南来草木始称珍。江湖风味极不浅，翰墨篇章老更新。\n\n落日清吟招恶客，此时佳境属闲人。惭无好语酬高咏，东望云山意莫陈。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和施通判以诗惠茶' AND p.poem_author = '王庭圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('卓牌儿 夏日咏闺人斗叶子', '陈维崧', '清代', '遥窥两重门，群掩映、凝烟碧幌。卐字槅底，凭肩语笑，冰纹廊后，亸鬟沈想。\n\n风流小南唐，金叶子、描鸾小样。斑几滑笏玲珑，蜡笺纤脆轻盈，打来偏响。\n\n七红四赏。更花戳、京城新创。兰闺似掌。俨楚汉情状。\n\n赢得帘西红鹦鹉，也隔屏山注望。私讲。笑粉装刘项。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '卓牌儿 夏日咏闺人斗叶子' AND p.poem_author = '陈维崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天（番禺齐安郡王席上赠故人）', '向子諲', '宋代', '台埭初逢两妙年。瑶林玉树倚风前。疏梅影里春同醉，红芰香中月一船。 \n 长怅恨，短因缘。空余胡蝶梦相连。谁知瘴雨蛮烟地，重上襄王玳瑁筵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天（番禺齐安郡王席上赠故人）' AND p.poem_author = '向子諲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('新湾', '刘子翚', '宋代', '苒苒寒生水面烟，吴歌唱罢月微偏。\n停桡又向湾前宿，一夜西风浪打船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '新湾' AND p.poem_author = '刘子翚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读备遗录', '郑善夫', '明代', '神尧无信史，谁纪革除年。龙虎风云上，山河涕泪边。\n\n夷齐偏守死，王魏总知权。三复春秋传，微词今不传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读备遗录' AND p.poem_author = '郑善夫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('都梁八首 其七', '陈造', '宋代', '向来经世蕴，每作负山驰。鬓发不留黑，京尘惭旧缁。\n\n生涯黄卷在，心事白鸥知。回首林泉癖，穷吾不为诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '都梁八首 其七' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵尧明贡院诗', '吕本中', '宋代', '忍穷不能归，强饭亦良计。东风频报春，草木可次第。\n\n厌为龙头缩，宁作龟尾曳。从来翰墨场，即有闻见滞。\n\n譬如已耕田，更欲深种艺。或蒙卤莽报，未肯即卖弃。\n\n不闻太仓粟，亦校毫发细。王卿固倦游，秽浊有蝉蜕。\n\n声名动时人，我实托末契。泥涂倒屐齿，尘埃涴衣裌。\n\n要为无用用，乃作不事事。下马旧战场，午日在庭戺。\n\n向来槁木枝，忽有红绿缀。来非偶然住，去亦无所诣。\n\n聚蚊著瓯中，得听此鹤唳。窗前有馀馥，胜韵入松桂。\n\n扁舟下淮南，闾里思少憩。熟观昔所历，请与居士戏。\n\n江湖要同归，不假木兰枻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵尧明贡院诗' AND p.poem_author = '吕本中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高宗皇帝挽词五首', '宋孝宗', '宋代', '草昧千龄旦，飚回九县尘。\n皇天开我宋，丹极下真人。\n指顾山河定，欢呼历数新。\n断鳌重立极，更与物为春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高宗皇帝挽词五首' AND p.poem_author = '宋孝宗';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长安杂诗十首 其七', '王祎', '元代', '群经载圣道，昭揭如日星。秦火一何烈，烧燔灭其形。\n\n汉儒事掇拾，区区补残零。虽然有遗阙，其功亦已宏。\n\n唐世尚文学，君臣益留情。琬琰刻文字，后先十三经。\n\n谓兹金石坚，不与竹帛并。自从东都后，此刻最为精。\n\n罗列黉舍内，奎壁映晶莹。我言金与石，有时亦销崩。\n\n有形必有弊，斯理讵难徵。安知圣人道，所托非所凭。\n\n天地其终始，猗欤罔能名。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长安杂诗十首 其七' AND p.poem_author = '王祎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('元会二首', '严嵩', '明代', '正元钟鼓动长安，率土朝天若会湍。瑞气先浮百子殿，晴光欲上五辛盘。\n\n梅风应律韶年丽，蔀屋迎阳圣泽宽。先向御帘陈贺表，缪司邦礼备春官。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '元会二首' AND p.poem_author = '严嵩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('德孺五丈和之字诗韵难而愈工辄复和成可发一', '黄庭坚', '宋代', '且然聊尔耳，得也自知之。\n独笑真成梦，狂歌或似诗。\n照滩禽郭索，烧野得伊尼。\n早晚来同醉，僧窗卧虎皮。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '德孺五丈和之字诗韵难而愈工辄复和成可发一' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('醉吟', '戴复古', '宋代', '一狂兼一懒，穷到白头年。\n客路偏耽酒，诗囊不贮钱。\n吟边忘世故，醉里乐吾天。\n不答诸公问，何如孟浩然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '醉吟' AND p.poem_author = '戴复古';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙 天安门诗抄', '佚名', '当代', '哭别亲人泪未消，山精出洞变人妖，\n装腔作势调门高。\n\n有意重研擒鬼法，无心轻信狗皮膏，\n留神拭泪认花招。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙 天安门诗抄' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('史记引逸诗', '佚名', '先秦', '得人者兴。\n失人者崩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '史记引逸诗' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('后秋兴八首中秋十九日，暂回村庄而作 其八', '钱谦益', '明代', '孤篷信宿且逶迤，白水柴门返故陂。丹桂月舒新结子，苍梧云护旧封枝。\n\n歌阑长夜秋方盛，语到胥闾日每移。小饮折花重剪烛，参旗长并酒旗垂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '后秋兴八首中秋十九日，暂回村庄而作 其八' AND p.poem_author = '钱谦益';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谨次功成短项翁佳篇之韵', '钟孝国', '宋代', '君不见中山毛颖生，纂录百氏编群经。\n又不见革华祖都尉，殿上承恩举足耳。\n二物名誉由韩公，无乃衮褒俱中理。\n君家酒罍依图书，短项独喜觞吾儒。\n我加翁名乃率尔，诸公过听欢有馀。\n翁名称意仰来前，再拜不愿封酒泉。\n倾怀解贾吟笔勇，注想只愁客杯乾。\n主人冥心通与穷，从渠自引琉璃钟。\n醉中琢句千古废，醒后逢人四海空。\n林间日日吹春风，孛窣愿卜重相逢。\n长江小艇新雨后，一杯相属会稽翁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谨次功成短项翁佳篇之韵' AND p.poem_author = '钟孝国';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('琉球难夷遭风到境加意抚恤照例护送诗以纪事', '董正官', '清代', '得生众命赖渔船，恭顺中山天亦怜。破艇底能漂海上，大龟屿恰属兰边。\n\n馆餐仰体怀柔远，额手欣看顶礼虔。此与琉球深夙契，前年护送又今年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '琉球难夷遭风到境加意抚恤照例护送诗以纪事' AND p.poem_author = '董正官';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题三山天庆观 其二', '白玉蟾', '宋代', '紫琼飞清都，翠云护绛阙。不见有星辰，俯视但日月。\n\n下世二千年，不敢向人说。吾已成金丹，留下飞仙诀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题三山天庆观 其二' AND p.poem_author = '白玉蟾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('调云岑', '郑清之', '宋代', '佛法方当恶剧时，偃溪笑裹袖钳锤。\n不教管领千云衲，打彻头关更问谁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '调云岑' AND p.poem_author = '郑清之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪纱二首 其一 答子退', '林散之', '近代', '退墨零笺笔不停，寒窗辛苦十年灯，此中消息得天能。\n\n用色由来如用墨，生枯燥湿验虚灵，炼成炉火自纯青。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪纱二首 其一 答子退' AND p.poem_author = '林散之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次临封八景韵 其七 景星夜月', '蒙尧佐', '明代', '星名古寺遗踪远，月挂空山分外明。竹影却疑蟠影动，松声时带磬声清。\n\n光分郊野昏如画，照彻浅崖险亦平。谁使传灯来此处，清辉今已彻专城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次临封八景韵 其七 景星夜月' AND p.poem_author = '蒙尧佐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春词', '李建勋', '唐代', '日高闲步下堂阶，细草春莎没绣鞋。 \n 折得玫瑰花一朵，凭君簪向凤凰钗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春词' AND p.poem_author = '李建勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别秀亭五首 其一', '方回', '宋代', '秀亭亭上果何似，两水万山图画开。霜入川原疏草木，烟销城市出楼台。\n\n半空鹭点客愁破，何许笛吹诗句来。异日梦魂应历历，醉僧同此藉莓苔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别秀亭五首 其一' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鲁桥热', '陆深', '明代', '赤日行空正当午，老夫畏热如畏虎。计程归路三千七，值我行年六十五。\n\n昨过任城旧酒楼，山川信美非吾土。仲宣太白俱仙才，安得并载黄龙浦。\n\n此日池塘杨柳风，此时庭院芭蕉雨。牙缃架插馀万卷，衮钺心传破千古。\n\n满座时看羽扇摇，半酣起拂吴钩舞。已约清风成故人，更须霖雨歌明主。\n\n回瞻殿阁忆微凉，却向园庐依茂树。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鲁桥热' AND p.poem_author = '陆深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送蔡季良', '曹伯启', '元代', '盛世官规量材职，逢掖仍须肆刀笔。猥予南北阅人多，彼此技能相得失。\n\n江东复一季良出，姓字相闻不相识。同事同星几研亲，得觇干局无俦匹。\n\n简书衮衮笑谈了，政事优优儒道饰。忽惊奏最觐天庭，万里秋风动颜色。\n\n英雄不下儿女泪，著脚云衢先努力。除书消息待春开，何处豺狼当屏迹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送蔡季良' AND p.poem_author = '曹伯启';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游墺门宿普济禅院赠云胜师', '成鹫', '明代', '珠林遥隔水云村，百里寻僧日欲昏。行逐鲛人趁番市，渐闻鴃舌杂华言。\n\n山钟近接三巴寺，海气晴分十字门。到处不妨吾道在，岛夷今识法王尊。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游墺门宿普济禅院赠云胜师' AND p.poem_author = '成鹫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史一百三十首 其一一九 沈光文', '连横', '近代', '扁舟东海去，文献启台湾。诗礼传荒服，番黎拜杏坛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史一百三十首 其一一九 沈光文' AND p.poem_author = '连横';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('慈圣光献皇后挽辞七首 其四', '苏颂', '宋代', '越从景祐至元丰，俪极坤仪四纪中。复辟先朝尊启母，助勤熙旦广尧聪。\n\n深居高拱收渊默，盛德成功绝比隆。太史方修长信注，续诗应首二南风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '慈圣光献皇后挽辞七首 其四' AND p.poem_author = '苏颂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵高子勉十首', '黄庭坚', '宋代', '沙上步微暖，思君剩欲招。\n蒌蒿穿雪动，杨柳索春饶。\n枉驾时逢出，新诗若见撩。\n樽前远湖树，来饮莫辞遥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵高子勉十首' AND p.poem_author = '黄庭坚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丹元子步天歌 其五 北方七宿', '王希明', '唐代', '危，三星不直旧先知。危上五黑号人星，人畔三五杵臼形。\n\n人上七乌号车府，府上天钩九黄晶。钩上五鸦字造父，危下四星号坟墓。\n\n墓下四星斜虚梁，十个天钱梁下黄。墓傍两星能盖屋，身著黑衣危下宿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丹元子步天歌 其五 北方七宿' AND p.poem_author = '王希明';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('祝英台近', '葛长庚', '宋代', '月如酥，天似玉，长啸弄孤影。十二楼台，昨梦暗寻省。自怜露满衣襟，风吹毛发，浑无寐、寒宵漏永。 \n 捧香鼎。翻起一片龙涎，梅花对人冷。庭户冰清，何处鹤声警。少时烛暗梧窗，烟生苔砌，晓钟动。忽然心醒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '祝英台近' AND p.poem_author = '葛长庚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送进士陈峣往睦州谒冯郎中', '章孝标', '唐代', '孤帆几日程，投刺水边城。倚棹逢春老，登筵见月生。 \n 饮酣杯有浪，棋散漏无声。太守怜才者，从容礼不轻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送进士陈峣往睦州谒冯郎中' AND p.poem_author = '章孝标';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凤凰山', '温革', '宋代', '惯作山林客，聊游戏剧场。\n栗花收作烛，柏子采为香。\n且放高情适，都无俗事妨。\n人间正扰扰，只得叩空王。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凤凰山' AND p.poem_author = '温革';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乙巳邵武建宁夜坐书呈诸公', '陈普', '宋代', '敬身天不宽曾子，白眼人当杀嗣宗。\n林下脱巾仍露脚，青云白石肯相容。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乙巳邵武建宁夜坐书呈诸公' AND p.poem_author = '陈普';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渊明祠', '宋濂', '明代', '官航晚泊浔阳郭，把酒长怀靖节贤。\n折腰竟辞彭泽米，攒眉宁种远公莲。\n归来松菊开三径，老去柴桑受一廛。\n晋代衣冠谁避世，刘家社稷自书年。\n虽云富贵非吾愿，已有清高独尔伟。\n千载令人吊遗迹，好山青立县门前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渊明祠' AND p.poem_author = '宋濂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江门夜泊', '邱云霄', '明代', '城抱江流急，沙回浪势安。烟云归树暝，风雪酿梅寒。\n\n客梦随更转，溪声入夜残。渔翁相傍宿，应笑欲弹冠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江门夜泊' AND p.poem_author = '邱云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春贴子词·夫人阁四首', '司马光', '宋代', '圣主终朝勤万机，燕居专事养希夷。\n千门永书春岑寂，不用车前插竹枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春贴子词·夫人阁四首' AND p.poem_author = '司马光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬朱适园访见诗', '潘玙', '宋代', '曾同山友过江湄，何处清游晚未归。\n沽酒□羊来好语，开笼放鹤在何时。\n云方卷叶收春雨，柳未吹花点客衣。\n京洛相逢宜少驻，东风杖屦好追随。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬朱适园访见诗' AND p.poem_author = '潘玙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('冬至斋宫二首 其一', '胤禛', '清代', '晨曦炯炯洁斋宫，一缕炉烟散绮栊。暖气潜回葭琯律，早梅先绽玉阶风。\n\n中孚默契天人理，来复明彰造化功。漫道书云成故事，精禋惟藉寸心通。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '冬至斋宫二首 其一' AND p.poem_author = '胤禛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('同元复初饮许仲文别墅', '张养浩', '元代', '晓日楼台海市仙，春风歌吹酒家天。五云分彩来琼岛，两鹤联飞下玉田。\n\n流水故将尘隔断，好花都被雨开全。人生佳处无何国，钟鼎山林恐未然。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '同元复初饮许仲文别墅' AND p.poem_author = '张养浩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清明', '黄文琛', '清代', '淡淡湖风弄雨丝，纸灰飞上绿杨枝。三年不过归元寺，肠断清明上冢时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清明' AND p.poem_author = '黄文琛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨中呈石末公', '刘基', '明代', '去年三冬暖不雨，今年孟春寒有余。\n大云垂垂压宇宙，密雪兖兖飘庭除。\n安排白水与泛舸，酝酿青泥容没车。\n辛苦陌头杨柳树，含颦等待大阳舒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨中呈石末公' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('连日祷雨犹未应也数语漫述皇恐之意呈簿尉', '虞俦', '宋代', '小儿曼倩儘狂奸，试掉雷车与破悭。\n慰我农民须早计，怜渠岁事颇相关。\n斋盂并日浑忘味，诗债如山只欠还。\n谢令冥顽推不去世，毫丝无补亦胡颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '连日祷雨犹未应也数语漫述皇恐之意呈簿尉' AND p.poem_author = '虞俦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赋得时人不识予心乐', '玄烨', '清代', '恩波遍布首邦畿，爱此佳时绿尚微。血耗养衰心益壮，神烦物扰体无违。\n\n暮年筋骨犹能强，半世忧劳幸免非。老惯豫游山水处，傍人那得识天机。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赋得时人不识予心乐' AND p.poem_author = '玄烨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南归杂诗 其六 黄浦江', '孙玄常', '近代', '黄浦今犹昔，朝朝送远人。淩波人不见，波上岂留痕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南归杂诗 其六 黄浦江' AND p.poem_author = '孙玄常';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('村居即事', '刘雪崖', '宋代', '数声鸡犬自相闻，借得茅庐住水濆。\n梅欲黄时常是雨，稻才青处便如云。\n忧时每欢朝廷远，学稼方知畎亩勤。\n若使徵书到岩谷，北山又恐动移文。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '村居即事' AND p.poem_author = '刘雪崖';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('风竹', '唐璧', '明代', '琅玕亭亭耸高节，飒遝凉飙舞苍雪。未从天上制箫韶，且向人间洗炎热。\n\n千崖万壑寒飕飕，五月六月疑清秋。凤鸾欲下栖不稳，飘然飞上青云头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '风竹' AND p.poem_author = '唐璧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赋得山水图长歌赠潘太守瑞徵', '谢榛', '明代', '华岳上逼层霄，可窥星斗之真迹。黄河来自西极，长送昆崙之正脉。\n\n绮霞彩虹灿一色，枫林岂让柿叶赤。光映石岩好登陟，眼中胜景谁尽得。\n\n薄暮翠岚藏秀月又黑，姑射仙子夜游信能识。天与元精豁胸臆，后园独种蟠桃核。\n\n仙果熟时未敢食，欲献圣皇咀味跻寿域。汾水朝宗流不息，上方龙剑到手除荆棘。\n\n更刬长安路平通，万国直臣共佐唐虞德。渔樵各生计，官吏不虚职，澶州正对燕京北。\n\n欲命良工写此图，高挂不出乎半间之壁。主人坐赏最珍惜，神游中宵乘彼苍凉片月白。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赋得山水图长歌赠潘太守瑞徵' AND p.poem_author = '谢榛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题豫章宋德父游湘诗卷', '乐雷发', '宋代', '醉呼仙叟共浮湘，稛载风烟满锦囊，\n名似浦云山雨起，诗连沅芷沣兰香。\n好吟秋月招元结，莫赋朝云恼楚襄。\n吴巨老仙今寂寞，行人还解识珩璜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题豫章宋德父游湘诗卷' AND p.poem_author = '乐雷发';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山中即事', '薛始亨', '明代', '石径无泥滓，雨过一渠清。返照摇庭宇，寒烟起槛楹。\n\n废书人宴坐，得食鹤徐行。借问经秋事，萧萧竹籁鸣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山中即事' AND p.poem_author = '薛始亨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('众鸟', '王令', '宋代', '鸦鸦枝上鸣，欲下飞复屡。\n忽投群辈先，以我弃肉去。\n群鸟起争攫，既失反亲慕。\n饿鸱盘且下，欲夺进复惧。\n群鹊何轩轩，聚噪如骂怒。\n鸠鸽恨不逮，回旋自号呼。\n庭雀审细微，知非已能预。\n跳梁暮堂下，不舍稗粒顾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '众鸟' AND p.poem_author = '王令';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('王季海求父宣义挽词二首 其二', '苏籀', '宋代', '里仁巾几寂，遗懿满瞻听。济美圭璋质，流芳琬琰铭。\n\n纸灰霏似雪，巷泣洒将冰。念念存伽释，超超拔九冥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '王季海求父宣义挽词二首 其二' AND p.poem_author = '苏籀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('后天易吟三十首', '方回', '宋代', '始屯终未济，世故信多艰。\n维坎刚中吉，周旋险难间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '后天易吟三十首' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送大行李浔江使齐归省 其五', '黄廷用', '明代', '三月青门柳色新，西郊相送转情亲。知君使节经过地，楚水吴山俱是春。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送大行李浔江使齐归省 其五' AND p.poem_author = '黄廷用';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再用韵题翠壁', '朱熹', '宋代', '孤亭一目尽天涯，俯瞰烟村八九家。翠壁何年悬布水，绿阴经雨堕危花。\n\n杖藜徙倚凝春望，觅句淹留到晚衙。珍重诗翁莫相恼，枯肠搅断鬓丝华。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再用韵题翠壁' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('客中夜坐', '袁凯', '明代', '落叶萧萧淮水长，故园归路更微茫。\n一声新雁三更雨，何处行人不断肠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '客中夜坐' AND p.poem_author = '袁凯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题卢五旧居', '李颀', '唐代', '物在人亡无见期，闲庭系马不胜悲。窗前绿竹生空地， \n 门外青山如旧时。怅望秋天鸣坠叶，巑岏枯柳宿寒鸱。 \n 忆君泪落东流水，岁岁花开知为谁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题卢五旧居' AND p.poem_author = '李颀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('常宁寺', '弘历', '清代', '兰若静朝晖，苔侵碑篆古。泠泠水到阶，落落松当户。\n\n龙鳞俨欲张，虬枝自撑拄。谯邑多古迹，爱此琳宫宇。\n\n依稀梵呗声，彷佛天花雨。意香参即离，静室坐久许。\n\n适然获常宁，顿忘安心所。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '常宁寺' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九日壁墩和杜牧之韵 其一', '贺一弘', '明代', '近野高林鸟倦飞，远村烟火隔川微。随风霜叶飘还堕，映水岩云静自归。\n\n浊酒登台怜子美，澄江如练忆玄晖。何人早出樊笼外，千仞冈头独振衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九日壁墩和杜牧之韵 其一' AND p.poem_author = '贺一弘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登九成台', '乌斯道', '明代', '重华不见独登台，台倚孤城日月开。似听箫韶千载上，虚疑凤鸟九霄来。\n\n乱山北起迷烟树，双涧南流浸绿苔。回首苍梧天咫尺，南巡曾带跸尘回。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登九成台' AND p.poem_author = '乌斯道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙十首 其七 成都和友人', '唐圭璋', '近代', '消尽芸香写尽词。日长人懒似游丝。一襟幽怨只天知。\n\n和寡不思温旧曲，寒深谁复问添业。斩来病骨亦支离。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙十首 其七 成都和友人' AND p.poem_author = '唐圭璋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山中漫题', '蓝智', '明代', '读书期有用，闭户耻无能。\n落叶空山雨，疏钟独夜灯。\n人称樗里子，住近石门僧。\n静坐观诗妙，须参最上乘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山中漫题' AND p.poem_author = '蓝智';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('五色鹦鹉黄鹦鹉并是圣母所驯各赋 其一', '徐渭', '明代', '白燕往时呈翰苑，锦鹦今日贡宸居。万年枝上栖偏丽，百鸟图中态未如。\n\n豢养固知天意在，语言长得圣颜舒。何因五色鲜成染，自是娲皇炼石馀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '五色鹦鹉黄鹦鹉并是圣母所驯各赋 其一' AND p.poem_author = '徐渭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('席上题黄莺', '李江', '明代', '满眼柔香嫩绿时，东风和雨柳丝丝。一梭便是经纶术，半舌还应律吕奇。\n\n振翅出于幽谷处，着身飞上打头枝。平生不爱多言语，一叫春风天下知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '席上题黄莺' AND p.poem_author = '李江';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赋萧爽檐蔔戏岩叟', '陈文蔚', '宋代', '且喜花时雨不妨，凭阑闲与细平间。\n一池交映月添白，六出同妍雪逊香。\n素有书痴缘病懒，不知诗兴为渠忙。\n道人雅好惟清供，却恐花神索酒觞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赋萧爽檐蔔戏岩叟' AND p.poem_author = '陈文蔚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春 病中作', '奭良', '清代', '荆棘余生，忧来百端，病亦戏予。忆髫年羸弱，时亲药裹，名场毷氉，空逐公车。\n\n门荫除官，牵丝黄绶，窃禄东都十载余。因风便，便频登启事，渐即康衢。\n\n乘边竞重储胥。愧曲突徙薪计尚疏。笑鸥波浩荡，几同传舍，蠹鱼纠结，又校官书。\n\n少也多愁，老而善病，七十光阴过隙驹。酸甜味，倘逢人巧算，细与乘除。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春 病中作' AND p.poem_author = '奭良';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('前汉书十七首 其十二 梅福', '郑学醇', '明代', '为官岂择南州尉，轺传空劳疏屡陈。天路冥冥鸿鹄远，不忍长作市门人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '前汉书十七首 其十二 梅福' AND p.poem_author = '郑学醇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('有网友名青藤葫芦者其人诙谐喜谈禅以诗调之', '李梦唐', '当代', '细牵飞蔓粗缠藤，点染青皮随意风。大道说来句句小，文章都在两圆中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '有网友名青藤葫芦者其人诙谐喜谈禅以诗调之' AND p.poem_author = '李梦唐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('诗一首', '本之', '宋代', '一篙春水滑无声，一叶轻舟过短亭。\n飞蔼晚楼迷紫翠，夕阳孤塔认丹青。\n怀人远折三花树，何日相携双玉瓶。\n欲唤渔郎问风色，凫鹥飞处酒初醒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '诗一首' AND p.poem_author = '本之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沙湖道中', '许有壬', '元代', '城居如坐井，出郭始知春。草色才翻烧，禽声便可人。\n\n远山来逦迤，羸马去逡巡。唤醒三年梦，东华足软尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沙湖道中' AND p.poem_author = '许有壬';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('双溪', '范成大', '宋代', '冷风骚骚木叶低，洞渊阻深生怪奇。\n碧琳双涧黑无底，中有玉龙相对飞。\n雷轰雪卷入林樾，化为一龙潭底没。\n摩尼斗罢四山空，时有宝光岩下发。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '双溪' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵僧自文见赠四首', '方回', '宋代', '莫诧横磨剑，宁为没字碑。\n问花惊兔麦，赋药护羊蓍。\n今我都无事，非公不作诗。\n夜窗各坚坐，两地月明知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵僧自文见赠四首' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('述愤一十七首弘治乙丑年四月作是时坐劾寿宁侯逮诏狱 其十', '李梦阳', '明代', '青青庙中槐，交交一双禽。为巢育其儿，结构良苦辛。\n\n一朝惊弹罗，移栖向高林。我行适见之，叹息空弥襟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '述愤一十七首弘治乙丑年四月作是时坐劾寿宁侯逮诏狱 其十' AND p.poem_author = '李梦阳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('祀五帝于明堂乐歌十一首 其二 高明乐', '佚名', '隋代', '祖德光，国图昌。祗上帝，礼四方。辟紫宫，动华阙。龙虎奋，风云发。\n\n飞朱雀，从玄武。携日月，带雷雨。耀宇内，溢区中。眷帝道，感皇风。\n\n帝道康，皇风扇。粢盛列，椒醑荐。神且宁，会五精。归福禄，幸闾亭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '祀五帝于明堂乐歌十一首 其二 高明乐' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丁稚璜宫保丈节署燕集谈次及山陕近事感赋 其一', '张百熙', '清代', '觥觥宫保秉壮猷，森列兵卫拥八驺。开轩坐我为我语，鲁酒不解苍生忧。\n\n去年山东多难民，今年山西人食人。安得输粮太原道，五百万人同一饱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丁稚璜宫保丈节署燕集谈次及山陕近事感赋 其一' AND p.poem_author = '张百熙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('草书歌', '铁保', '清代', '苍颉不识篆，虫鸟开天荒。史籀不识楷，古法遗钟王。\n\n圣人作书祖造物，天地不得留微茫。草书有名理，盛自汉与唐。\n\n杜度埒崔瑗，狂素阶颠张。心法授受纵奇变，牢笼百态惊愚盲。\n\n譬如彼苍铸万类，物具一体无相妨。飞潜动植各有势，短长肥瘦谁能量。\n\n又如将军坐帷幄，运筹百万网在纲。韩信兵多多益善，指挥方位争趋跄。\n\n方其执笔时，意静神飞扬。洪炉火激迸列缺，晶盘冰滑流珠芒。\n\n苍鹰盘云缩爪甲，奇石攫壁春硠硠。阴阳姤接作向背，子母孕化交纵横。\n\n枯槎百围卧瀚海，女萝千丈萦扶桑。忽然墨冷笔华涩，陡接渤澥波澜狂。\n\n书成不快意，大叫周回廊。举头天尺五，云物相低昂。\n\n欲碾太山为研石，欲抉东海为墨庄。凌铄大块写生态，睥睨云汉摹天章。\n\n二十八宿走且僵，帝女大笑挥霞觞。丈夫师古但师意，安能描头画脚忍与朽骨争媸嫱。\n\n我歌草书歌未央，飘风骤雨来虚堂。依稀不晓神灵意，莫向蛟龙攫处藏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '草书歌' AND p.poem_author = '铁保';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谒二祖', '孙继皋', '明代', '古殿依晴嶂，慈云对夕禅。衲从初祖授，灯自上方悬。\n\n大法还谁悟，真空不可传。惟馀洞中雪，寂历洒诸天。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谒二祖' AND p.poem_author = '孙继皋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠淳于公归养', '朱台符', '宋代', '通籍悬车不待车，彩衣归去奉晨昏。\n倚门且慰慈亲望，恋阙空衔圣主恩。\n天上芝泥新诰敕，海边芜没旧田园。\n会须引退追高躅，宦路悠悠岂足论。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠淳于公归养' AND p.poem_author = '朱台符';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('立春晓起', '姚燮', '清代', '桑曦照帏室，尘薄散宿昏。引杯试春酌，盎然得微醺。\n\n众荄藐含绿，生理足内存。妷霭在空阔，触处寓欢欣。\n\n化尔沈愤气，还诸浩荡仁。行歌满衢市，谁非羲皇民？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '立春晓起' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂九十三首 其四十三', '释梵琮', '宋代', '求道如求雨，乾枯日夜愁。忽然风雨至，万壑尽争流。\n\n直得天下万物沾润，三井龙王出头。云南如劈箭，云北似倾湫。\n\n激石怒雷吼，翻空雪浪浮。忽然风雨息，平地一时休。\n\n衲僧家，骑个水牯牛。多快活，百无忧。健即行，困即歇。\n\n布袋头，亲解结。钉打钉，铁打铁。寒道寒，热道热。此是诸佛心宗，亦名单提妙诀。\n\n七峰峰顶滑如苔，寒山拾得相拖拽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂九十三首 其四十三' AND p.poem_author = '释梵琮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词', '张公庠', '宋代', '萱草初长花未开，共知青帝领春回。\n珠帘卷上琼钩稳，不碍薰风满殿来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词' AND p.poem_author = '张公庠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('大本堂（二首）', '魏观', '明代', '六斋帝子联龙衮，三岛神仙列雁行。\n绣毂青鸾金羽盖，锦鞯白马紫游缰。\n御沟细柳云生暖，禁御飞花雨送凉。\n郑国书闻能一一，玉炉清昼为分香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '大本堂（二首）' AND p.poem_author = '魏观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偶题云边', '刘宰', '宋代', '桃花山下水流长，花不长开水自香。\n此地正须招隐上，山庵聊复对崇罔。\n屏帏缭绕竹千个，旌纛森岩柏两行。\n士会不生今已矣，不妨閒处且徜徉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偶题云边' AND p.poem_author = '刘宰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('伏蒙知县县尉二寮友以夏旱得雨赓石徂徕喜雨韵见贶不可虚辱复嗣其韵书谢仍命儿曹同赋', '王之道', '宋代', '绿槐阴外听蝉吟，节过分龙夏已深。千里亢阳忧岁旱，一时甘雨快人心。\n\n养禾不害连朝曀，沃暑应容数日霖。多谢同寮怜老拙，双南佳句竞铿金。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '伏蒙知县县尉二寮友以夏旱得雨赓石徂徕喜雨韵见贶不可虚辱复嗣其韵书谢仍命儿曹同赋' AND p.poem_author = '王之道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题清远峡飞来寺', '汪广洋', '明代', '峡里金银佛寺开，老僧传是昔飞来。菩提子落云间石，薝卜香飘月下台。\n\n江涌灵源通海峤，山横古翠接蓬莱。愿询往事观碑刻，閒向松阴扫绿苔。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题清远峡飞来寺' AND p.poem_author = '汪广洋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻叶初秀才东归', '林逋', '宋代', '高鸿多北向，极目雨余天。\n春满吴山树，人登汴水船。\n吟生千里月，醉尽一囊钱。\n肯便怀乡邑，时清复少年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻叶初秀才东归' AND p.poem_author = '林逋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书灵隐上人册', '李之世', '明代', '秋叶与秋云，的的当阶坠。家僮误扫叶，惊散秋云去。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书灵隐上人册' AND p.poem_author = '李之世';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春夜过银锭桥在禁城外北海子', '胡直', '明代', '都城佳丽地，春夜喜重经。巨浸通银汉，长桥挂碧汀。\n\n云移千树月，冰坼半湖星。缥缈闻仙吹，祈坛近苑亭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春夜过银锭桥在禁城外北海子' AND p.poem_author = '胡直';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('玉麟堂会诸司观牡丹酴醾三绝 其一', '范成大', '宋代', '东风微峭护馀春，红紫香中酒自温。不用忙催银烛上，酴醾如雪照黄昏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '玉麟堂会诸司观牡丹酴醾三绝 其一' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻郭怡有诗未及见因赋此以寄恨', '郭钰', '元代', '一襟老泪点苍苔，谁信愁肠日九回。豪杰虚名多自误，弟兄急难竟谁来。\n\n桥分溪路桃花落，门闭山房燕语哀。祸福情知相倚伏，浮云蔽日几时开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻郭怡有诗未及见因赋此以寄恨' AND p.poem_author = '郭钰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东轩', '吴讷', '元代', '孤客凭危正惘然，江南春尽落花天。海门黑送千艘雨，城郭青炊万灶烟。\n\n烧药金炉犹伏火，射潮铁箭久离弦。伍员白马今何在？几处荒台野鹿眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东轩' AND p.poem_author = '吴讷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雨中桃花', '李昌祺', '明代', '霢霂过芳园，枝枝积泪痕。色怜开处淡，香爱坠时闻。\n\n采倦蜂须湿，衔多鸟咮芬。东风解人意，吹片到衡门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雨中桃花' AND p.poem_author = '李昌祺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菜根吟', '陈振家', '当代', '层云萦郁隐青林，听彼好禽鸣木阴。松骨咬崖如铁铸，藤筋陷壁绕峰深。\n\n寂寥不改丘岩志，闲静渐忘湖海心。翻觉贫穷倍亲切，从兹喜作菜根吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菜根吟' AND p.poem_author = '陈振家';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游春十二首 其五', '姚合', '唐代', '疏顽无异事，随例但添年。旧历藏深箧，新衣薄絮绵。\n\n暖风浑酒色，晴日畅琴弦。同伴无辞困，游春贵在先。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游春十二首 其五' AND p.poem_author = '姚合';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵邢敦夫秋怀十首', '秦观', '宋代', '蝮蛇初螫手，壮士断其腕。\n岂不悲毁伤，所恤在躯干。\n西羌沙卤地，置戍或烦汉。\n鸡肋不足云，阿瞒妙思算。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵邢敦夫秋怀十首' AND p.poem_author = '秦观';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偕诸年丈游清凉台 其一', '李孙宸', '明代', '未尽登临意，相携上玉台。云山千嶂合，井里万家开。\n\n日落寒原迥，风生暮壑哀。迟回江月上，似涌夜珠来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偕诸年丈游清凉台 其一' AND p.poem_author = '李孙宸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谁园即事八首 其四', '张瑞玑', '近代', '作意东皇雨露新，山花野草亦精神。狂来诗酒无馀子，老去须眉几故人。\n\n花谱树经书好趣，雨蓑雪笠画中身。樽前莫话前朝事，京洛衣冠付劫尘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谁园即事八首 其四' AND p.poem_author = '张瑞玑';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和王宣义买菊栽二首 其一', '毛滂', '宋代', '秋风有好色，寄在菊花团。弛担知新主，临池得细看。\n\n金房迎日秀，玉露作香寒。独负东篱意，年来漉酒乾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和王宣义买菊栽二首 其一' AND p.poem_author = '毛滂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵龄叟招石秀叔', '陈著', '宋代', '久知难久别，飞约到柴门。\n唤起雨窗困，踏开岚径昏。\n世情忙外看，交道淡中存。\n何日巳公屋，新诗得共论。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵龄叟招石秀叔' AND p.poem_author = '陈著';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('沁园春 次韵林南金赋愁', '陈人杰', '宋代', '抚剑悲歌，纵有杜康，可能解忧。为修名不立，此身易老，古心自许，与世多尤。平子诗中，庾生赋里，满目江山无限愁。关情处，是闻鸡半夜，击楫中流。澹烟衰草连秋。听鸣鴂声声相应酬。叹霸才重耳，泥涂在楚，雄心元德，岁月依刘。梦落莼边，神游菊外，已分他年专一丘。长安道，且身如王粲，时复登楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '沁园春 次韵林南金赋愁' AND p.poem_author = '陈人杰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天', '张翥', '元代', '一曲吴歌酒半酣。声声字字是江南。书凭仙苑青鸾递，花助妆楼粉蝶衔。\n\n飞燕瘦，宝儿憨。已妍还慧更岩岩。无因剪得湘江水，与蘸春云作舞衫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天' AND p.poem_author = '张翥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('文宣王及其弟子赞 其六十三', '赵构', '宋代', '侁侁申周，四科与俦。逸驾文圃，鼓枻儒流。冠佩既燕，言动允休。\n\n邵陵得封，可想清修。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '文宣王及其弟子赞 其六十三' AND p.poem_author = '赵构';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢崇上人惠新茶', '曹勋', '宋代', '春入闽溪草木香，灵芽一夕一丝长。\n上人自是春风手，分与闲人齿颊芳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢崇上人惠新茶' AND p.poem_author = '曹勋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽孟侍郎鉴', '何乔新', '明代', '华胄承驺鲁，宏才迈俊英。麟经曾擅业，虎榜蚤登名。\n\n英荡风声远，黄门地位清。含香趋琐闼，拥笏导霓旌。\n\n奏对承殊渥，超迁位列卿。朔方劳转饷，南海藉治兵。\n\n区脱狼烟息，沧溟蜃雾晴。赐归蒙圣眷，徵起惬舆情。\n\n勋业追先哲，威仪式后生。白鸡俄入梦，黄阁竟辞荣。\n\n当宁嗟杨绾，同朝惜孔明。芳声垂汗简，懋绩纪桓楹。\n\n旧业荒烟暝，新阡宿草萦。临风歌楚些，悽怆泪沾缨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽孟侍郎鉴' AND p.poem_author = '何乔新';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('观音岩', '郑世元', '清代', '粤山山山奇，兹岩益奇绝。嵌空有神功，壁立淬寒铁。\n\n晻㫲山精藏，灵秀真宰泄。赤日万古阴，江雾昼常结。\n\n飞楼骑危驾，石隙透微穴。拾级如盘螺，堂隍忽开列。\n\n僧梵响出云，钟乳倒垂雪。南罗罗浮佳，北与大庾别。\n\n目谋觏斯奇，殊使羁心悦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '观音岩' AND p.poem_author = '郑世元';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄华山司空图二首 其二', '虚中', '唐代', '逍遥短褐成，一剑动精灵。白昼梦仙岛，清晨礼道经。\n\n黍苗侵野径，桑椹污闲庭。肯要为邻者，西南太华青。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄华山司空图二首 其二' AND p.poem_author = '虚中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('许云村舟过勾溪欲访溪翁为帆急不相见而去寄诗致其情溪翁和答有见嘲意予为作二绝句解之 其一', '朱朴', '明代', '结交头白总忘年，相见无因事偶然。绝胜当时风雪夜，到门空返剡溪船。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '许云村舟过勾溪欲访溪翁为帆急不相见而去寄诗致其情溪翁和答有见嘲意予为作二绝句解之 其一' AND p.poem_author = '朱朴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花集句 其二○一', '李龏', '宋代', '渔舸汀鸿外，霜天似水清。更无花上月，新句与谁评。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花集句 其二○一' AND p.poem_author = '李龏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和王褒咏摘花', '宇文毓', '南北朝', '玉椀承花落，花落椀中芳。酒浮花不没，花含酒更香。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和王褒咏摘花' AND p.poem_author = '宇文毓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('抛球乐 中秋荔湾待月', '陈洵', '清代', '罨画溪流叠翠屏。晚罨颦黛自然生。闻香露叶清吟地，摇梦风灯旧霸城。\n\n佳约无端暗，水调依稀最有情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '抛球乐 中秋荔湾待月' AND p.poem_author = '陈洵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洛阳桥', '林朝崧', '清代', '横天渴虹长万尺，下饮沧江化为石。鞭之叱之成此桥，桐城太守莆中客。\n\n往时欲渡川无梁，行人海葬蛟蜺宅。自从天堑变康庄，无复风涛阻形役。\n\n我生飘泊一飞鸿，缘在重留雪泥迹。手摩苔藓读遗碑，百五十字凝古色。\n\n碑中空记倡义人，岁久谁能识王实？将军下海语荒唐，流俗相传偏啧啧。\n\n古人利济同一心，或传或否堪太息！沈吟此事意难平，斜凭危栏日将夕。\n\n汀洲橹唱催人归，几阵松风洒巾帻。匆匆作诗别江神，何日重来看潮汐？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洛阳桥' AND p.poem_author = '林朝崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('海棠', '姜特立', '宋代', '绚丽繁霞綵，荧煌瑞锦堆。夜深疑睡去，日暖怕慵来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '海棠' AND p.poem_author = '姜特立';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄兄玉老', '储泳', '宋代', '雷阳路迢递，回首亦关心。\n重别因轻诺，远行多近吟。\n客怀秋色早，归梦岭云深。\n莫以书无益，人来惜万金。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄兄玉老' AND p.poem_author = '储泳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('敬题吕曜初先生画像 其二', '林朝崧', '清代', '岂有儒生怀侠骨，几闻草野报皇恩。壮君独抱匡时志，令我思招入海魂。\n\n养士郇厨传食谱，娱亲莱采舞梨园。一衿断送当年惜，馀庆谁知在子孙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '敬题吕曜初先生画像 其二' AND p.poem_author = '林朝崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宫词 其四十九', '王仲修', '宋代', '楼台雪霁晓阴阴，珠网屏风御幄深。和气先春宫掖暖，凤钗不用辟寒金。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宫词 其四十九' AND p.poem_author = '王仲修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虎牢关', '陈见智', '清代', '百战成皋地，中原第一关。大河回九曲，少室互重山。\n\n风雨崤函外，人烟巩洛间。往来凭眺处，回首已苍颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虎牢关' AND p.poem_author = '陈见智';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('甘州　和晋如', '刘斯翰', '当代', '共沙鸥片片逐潮来，水阁又秋风。正天涯流落，梦回搔首，月地朦胧。\n\n最恨悠悠玉笛，吹断水犹东。谁寄香山叶，亲付冥鸿。\n\n梦断京华春夜，听鼓楼岑寂，檐滴初融。把纤纤寒玉，呵罢意还慵。\n\n忍图南、伊人抛撇；却相思、泪堕满江红。回阑倚，珠娘歌里，拍遍玲珑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '甘州　和晋如' AND p.poem_author = '刘斯翰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清静经', '白玉蟾', '宋代', '大地山河一卷经，拈来题目甚分明。\n山花野草皆谈说，蠢动含灵侧耳听。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清静经' AND p.poem_author = '白玉蟾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵赵司理山甫', '杨弘道', '元代', '身喜沾皇化，心惭赞老成。青衫初借著，白发已潜生。\n\n会计唯期当，康宁未暇营。如何清夜梦，常绕大堤行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵赵司理山甫' AND p.poem_author = '杨弘道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读浮休诗有感', '廖行之', '宋代', '二十年间儿女諠，糟糠勤苦不堪论。\n如今八载君身后，儿已登科又长孙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读浮休诗有感' AND p.poem_author = '廖行之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赴南都登太岳二首 其一', '杨巍', '明代', '驻马登东岳，凭高辨四溟。始知人世小，不断此山青。\n\n楼阁秋孤出，川原昼杳冥。将寻孙复隐，忽忘有严程。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赴南都登太岳二首 其一' AND p.poem_author = '杨巍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('颂古四十五首', '释慧远', '宋代', '饶君舌拄梵天，我也令行一半。\n赵州头戴草鞵，也是新繁轹鑽。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '颂古四十五首' AND p.poem_author = '释慧远';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('勉诸生习小学四首 其二', '林光', '明代', '搜穷经传几年馀，谁把神明信此书。除却寻常伦理外，更将何事称为儒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '勉诸生习小学四首 其二' AND p.poem_author = '林光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('妙智寺', '陈白', '宋代', '八重峰顶望群山，百谷东流去不还。\n惟有右军遗迹在，月波时落墨池间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '妙智寺' AND p.poem_author = '陈白';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂咏一百首 其二十二 婴臼', '刘克庄', '宋代', '贤矣两家臣，存孤极苦辛。后来有曹马，亦是受遗人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂咏一百首 其二十二 婴臼' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏无住观中物四首 其四 朱鱼', '王世贞', '明代', '猩红数点媚清泠，暖藻香萍度此生。莫向江湖贪广阔，近来鱼网大纵横。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏无住观中物四首 其四 朱鱼' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游木渎钱氏园三章 其一', '姚燮', '清代', '妙构极自然，疑非人意造。颇嫌短晷催，未容恣探讨。\n\n云缛廊有苔，露酽径多草。绮石如美人，坐阅万花老。\n\n百绺枯藤缠，疑尔青鬓槁。潭镜千尺泓，残荷一茎袅。\n\n遂使静止天，玉芬溢龙脑。何以蜻蛉红，但媚水阴蓼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游木渎钱氏园三章 其一' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('刘主簿许饷苦笋未至 其一', '周紫芝', '宋代', '苦竹冈头竹似云，刘郎何事不挥斤。杯盘倘使同吴俗，荼荠谁能作楚文。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '刘主簿许饷苦笋未至 其一' AND p.poem_author = '周紫芝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三月再还家', '蔡襄', '宋代', '晓树乡关路，春衣使者轺。\n江眠闻落霰，野饭掇新苗。\n入里威稜减，宁亲喜气饶。\n勤勤父师教，民病若为消。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三月再还家' AND p.poem_author = '蔡襄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('双峰寺', '弘历', '清代', '度壑穿林才片刻，双峰一榻恰怡神。回头拟向如来问，彼此伊谁是主宾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '双峰寺' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清平乐 其十一', '吴湖帆', '清代', '敷文尽去。隽语无嫌絮。醉意狂情禁不住。争似谁家深处。\n\n窗前月色微昏。更阑悄掩重门。正好相倾肺腑，胜于真个销魂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清平乐 其十一' AND p.poem_author = '吴湖帆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('悼周镐 其二', '陈献章', '明代', '一双玉树出东溟，岂意先随晓露倾。三十六年惟一女，老夫垂泪写铭旌。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '悼周镐 其二' AND p.poem_author = '陈献章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('都城初秋和赵京府', '朱浚', '宋代', '从来美玉价连城，结佩乘风十二京。\n携上峥嵘今有约，好留彩笔调清平。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '都城初秋和赵京府' AND p.poem_author = '朱浚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喜省中王秀才至', '陶益', '明代', '入港趋潮急，随风觉棹轻。乍疑诸客舫，欣见一儒生。\n\n剑气妆残雨，书囊推画城。岂徒通世务，还有下帷情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喜省中王秀才至' AND p.poem_author = '陶益';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送刘少尹赴兴州经历三首 其三', '卢楠', '明代', '大府元戎骑，长驱引万群。共迎刘记室，喜得郤参军。\n\n燕月排弓影，边霜缀铠文。知君娴庙略，一啸洒天氛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送刘少尹赴兴州经历三首 其三' AND p.poem_author = '卢楠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游方山宿李道士房', '徐铉', '唐代', '从来未面李先生，借我西窗卧月明。 \n 二十三家同愿识，素骡何日暂还城。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游方山宿李道士房' AND p.poem_author = '徐铉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夜游宫', '文廷式', '清代', '疏雨困眠孤馆。薄衾冷、漏签时断。湿羽投林鸟已倦。\n\n敛秋心，白云岩，黄槲岘。\n\n瑟瑟湘波远。动吟思、楚歌声怨。浊酒深杯且自劝。\n\n渺关河，意难忘，君试忖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夜游宫' AND p.poem_author = '文廷式';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重过独乐寺', '弘历', '清代', '山郡寒烟里，祗园粉堞边。禅房有花木，向日记留连。\n\n颓废嗟如是，施檀亦偶然。邑民似相识，瞥眼十馀年。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重过独乐寺' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怀仙桥', '林表民', '宋代', '晴雷书夜激奔湍，涧草岩花亦耐寒。\n刘阮茫茫空仰止，恐乘风月一鞭鸾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怀仙桥' AND p.poem_author = '林表民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四月出关道中感赋', '陈曾寿', '清代', '次第看花已作尘，出关烟景似初春。东风又绿先畴土，血染谁哀让畔人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四月出关道中感赋' AND p.poem_author = '陈曾寿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('依韵和范景仁内翰', '王圭', '宋代', '门前车马走尘埃，偶到东园眼暂开。鳌岭凤池人去后，不知载酒又谁来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '依韵和范景仁内翰' AND p.poem_author = '王圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('扶沟知县周职方录示白鹤宫苏才翁子美赠黄道', '欧阳修', '宋代', '能棋好饮一道士，醉墨狂吟二谪仙。\n道士不闻乘白鹤，谪仙今已揜黄泉。\n古来豪杰皆如此，谁拂尘埃为惘然。\n华发郎官才调美，更将新句续遗篇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '扶沟知县周职方录示白鹤宫苏才翁子美赠黄道' AND p.poem_author = '欧阳修';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('拟东武曲二首', '宋祁', '宋代', '我家世世山西士，二十期门从天子。\n始随骠骑破祁连，晚逐楼船下{特寺換羊}水。\n汉北雰雰飞雪暗，海中跕跕翔鸢坠。\n归来武库祭蚩尤，得从甘泉参豹尾。\n何意一朝兵后期，簿责侵诬属军吏。\n黄金纳赎为庶人，白首还家事田里。\n结发从军七十战，利镞金痍犹可记。\n龙钟虽入玉关门，止呵还遇灞陵尉。\n不及金张藉旧勋，七叶华貂长富贵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '拟东武曲二首' AND p.poem_author = '宋祁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('槃隐', '释居简', '宋代', '考得幽栖地，怡然胜美除。未归已彭泽，不梦亦华胥。\n\n绿绕清分远，红稀碧间疏。渔樵莫争席，不是野人居。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '槃隐' AND p.poem_author = '释居简';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山中杂诗', '罗洪先', '明代', '问我家何在，山深多白云。\n岩前泉溜下，对语不相闻。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山中杂诗' AND p.poem_author = '罗洪先';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('禾熟三首 其二', '孔平仲', '宋代', '丰年气象慰人心，鸟雀啾嘲亦好音。玉食儿郎岂知此，田家粒粒是黄金。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '禾熟三首 其二' AND p.poem_author = '孔平仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次颐伯韵', '章以荣', '近代', '旧国烽烟里，新亭涕泪中。山河犹失色，未敢厌兵戎。\n\n且莫悲商老，应须问塞翁。谁将戢羽翼，一举会高风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次颐伯韵' AND p.poem_author = '章以荣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句 其二', '吴涛', '宋代', '窗间常作三独坐，琴上时弹一再行。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句 其二' AND p.poem_author = '吴涛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('建炎庚戌溃兵狂襄汉寒食阻趋光作拜扫追慕痛', '张嵲', '宋代', '上庸寒食已无花，山木青青吐嫩芽。\n此日伤心九原路，想无鸡犬只鸣鸦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '建炎庚戌溃兵狂襄汉寒食阻趋光作拜扫追慕痛' AND p.poem_author = '张嵲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山楼对雨却寄京国诸同人', '李锴', '清代', '古情脉脉终何极，老鬓萧萧不耐秋。八月关河横暮色，四山风雨入危楼。\n\n残书过眼愁深解，荒稼侵寒任晚收。好我故人休系念，知吾身世付虚舟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山楼对雨却寄京国诸同人' AND p.poem_author = '李锴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天（时夫人寿）', '崔敦礼', '宋代', '本是瑶台月里仙。笑麾鸾鹤住人间。蟠桃一熟三千岁，剩对春风日月闲。 \n 缡绶结，彩衣斑。孙枝相应傍门阑。年年同上长生酒，得见沧溟几度干。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天（时夫人寿）' AND p.poem_author = '崔敦礼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('感事四首 其二', '连横', '近代', '拒楚宾秦计早成，竞传韩魏是同盟。已闻古佛生天竺，复见蚩尤出汉城。\n\n南极一星朝北斗，东风万里接西溟。烂柯山上傍观懒，胜负纷纷判此枰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '感事四首 其二' AND p.poem_author = '连横';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('附：李助为章武赋', '李助', '唐代', '石沈辽海阔，剑别楚天长。会合知无日，离心满夕阳。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '附：李助为章武赋' AND p.poem_author = '李助';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('登黄鹤楼作（有序）', '林章', '明代', '望里山川是楚乡，美人何处水茫茫。\n祢衡作客留江夏，赵壹辞家出汉阳。\n鹤去未知芳草暗，雁来先觉白云凉。\n倚楼无限西风意，堪与千秋一断肠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '登黄鹤楼作（有序）' AND p.poem_author = '林章';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵申泮宫直宿早秋四首 其一', '傅察', '宋代', '新秋爽气溢长空，弦诵低昂月映栊。济济青衿成鲁变，洋洋泮水咏洙风。\n\n群儒篆刻空章句，百氏纷纭赖折中。何日拔才空冀北，如今高誉满山东。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵申泮宫直宿早秋四首 其一' AND p.poem_author = '傅察';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('见花', '黄淮', '明代', '乞得花枝洒泪看，满怀愁绪万千端。故园亦有繁桃李，门掩东风暮雨寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '见花' AND p.poem_author = '黄淮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('戴宾有意山书屋谈次偶成时宾有举子', '马凤翥', '清代', '意山书屋我曾过，无句堪题邵子窝。卖赋近闻车辙满，乞钱常致酒材多。\n\n檐前绿竹添新笋，石上盘根长旧柯。莫笑客为汤饼至，携尊高唱待如何。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '戴宾有意山书屋谈次偶成时宾有举子' AND p.poem_author = '马凤翥';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('别樊时中廉使', '余阙', '元代', '光禄桥西惜解携，春星欲傍露盘低。自来官柳多离思，更著城乌在上啼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '别樊时中廉使' AND p.poem_author = '余阙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('惜红衣 神武门残荷，和茧庐', '周岸登', '清代', '草长红心，鹃啼恨魄，梦残凝碧。寸藕长丝，娟娟露桥北。\n\n金仙泪洒，曾惯听、枯鱼泉泣。沾臆。露佩水裳，哭秋风归客。\n\n湘灵鼓瑟。哀怨如闻，宫沟送潮汐。余姿婉娈自惜。\n\n映寒日。冷入粉云凉翠，不似井华颜色。怕坠房欹盖，犹怯薄铅偷滴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '惜红衣 神武门残荷，和茧庐' AND p.poem_author = '周岸登';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋怀 其七', '王邦畿', '明代', '剑术雌雄自有神，负恩元是报恩人。辘轳暗转银床晓，輘轹轻移玉宇春。\n\n不信丹丘为有种，须知黄道即良因。蓬山多少名仙籍，曾把云旗向北辰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋怀 其七' AND p.poem_author = '王邦畿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八声甘州 客有言西江近事者感而赋此', '陈维崧', '清代', '说西江、近事最销魂，啼断竹林猿。叹灌婴城下，章江门外，玉碎珠残。\n\n争拥红妆北去，何日遂生还。寂寞词人句，南浦西山。\n\n谁向长生宫殿，对君王试鼓，别鹄离鸾。怕未终此曲，先已惨天颜。\n\n只小姑、端然未去，伴彭郎、烟水月明间。终古是，银涛雪浪，雾鬓风鬟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八声甘州 客有言西江近事者感而赋此' AND p.poem_author = '陈维崧';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('举第四子阿豫 其二', '屈大均', '明代', '花褓人争送，欢生满月时。月娥金粟种，天帝玉兰枝。\n\n上有三兄小，中多一母私。羽毛成立日，吾已杖朝期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '举第四子阿豫 其二' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和王巩见寄三首 其一', '苏辙', '宋代', '南迁春及秋，江湖未云半。逮此归路长，始悟行日远。\n\n幽忧脱沉痼，清梦惊婉娩。行行逢故人，笑语杂悲泫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和王巩见寄三首 其一' AND p.poem_author = '苏辙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乙未除夕为稽古诸传未竣漫吟五律 其一', '郭之奇', '明代', '岁云暮矣暮怀多，老病相从似小苛。蒿目千秋供探索，抽思一管付编摩。\n\n禹阴夙继无终食，汤日新铭有寤歌。此际骊珠凭独采，人间驹隙漫相过。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乙未除夕为稽古诸传未竣漫吟五律 其一' AND p.poem_author = '郭之奇';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('游石钟山寄匡云上人', '邝露', '明代', '钟山窍奇石，金奏蕴璠玙。微波媾灵牝，噌吰含龙鱼。\n\n神涛窥日母，鳀壑潜灵居。天声谢人巧，习坎均吹嘘。\n\n流目桑钦传，钟情伯翳书。弱龄敦夙好，岁晏孰华余。\n\n是时秋月中，初对惟匡庐。何渠山中人，白社过篮舆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '游石钟山寄匡云上人' AND p.poem_author = '邝露';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('信士画真请赞 其六', '释印肃', '宋代', '易尽世间颜色，普庵顶相奚为。等大虚空一体，雾露云霞表衣。\n\n眼观不见，耳听不知。惺惺不昧，了了何亏。自解拈花知起处，冷笑达磨更西归。\n\n用晦隐显无劳失，亘古亘今也大奇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '信士画真请赞 其六' AND p.poem_author = '释印肃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹧鸪天', '刘学箕', '宋代', '梦绕天涯去意浓。客愁春恨两匆匆。绿波初涨桃花浪，画鹢轻随柳絮风。 \n 无笔力，判虚空。关山千里两心同。鱼书雁字都休问，只看啼痕翠袖红。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹧鸪天' AND p.poem_author = '刘学箕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('隆中遇雨', '林光', '明代', '隆中留胜迹，冒雨我能来。树洗层层翠，溪喧滚滚雷。\n\n草深诸葛庙，云罩简王台。安得长风扫，阴霾拨未开。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '隆中遇雨' AND p.poem_author = '林光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('与群公分地赋诗得京口', '郑经', '明代', '京口瓜州指顾间，春风几度到钟山。迷离绿遍江南地，千里怀人去不还。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '与群公分地赋诗得京口' AND p.poem_author = '郑经';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏日出池上', '宋庠', '宋代', '节候春虽往，年华暑未残。\n莲香开佛座，竹老退刘冠。\n戏渚藏頳尾，鸣皋濯素翰。\n堇葵红不一，蒲稗绿多端。\n宜物心无对，深根气自完。\n功名俱画饼，虚玷拥旄官。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏日出池上' AND p.poem_author = '宋庠';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重过泰山 其一', '葛昕', '明代', '几年今复过名山，石磴苔深鸟道宽。万壑行云千里树，尘寰俯瞰倚危栏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重过泰山 其一' AND p.poem_author = '葛昕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('萧寺寻僧图', '谢晋', '明代', '极目萧山寺，岧峣在越溪。风传钟远近，云接树高低。\n\n别去情无己，重寻路不迷。何时乘老兴，登眺策青藜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '萧寺寻僧图' AND p.poem_author = '谢晋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋雨', '陆游', '宋代', '吾庐多美荫，最茂楸与梧。\n百鸟集其间，下上更鸣呼。\n秋风忽动地，摇落日日疏。\n何如涧底松，终岁无荣枯？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋雨' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杏花天 寿杨经历七十一', '史鉴', '明代', '杏花开遍东风里。爱春色、年年相似。仙翁试把朱颜比。不是等閒桃李。\n\n借问胡麻和石髓。怎能比、子孙甘旨。古来七十人能几。过了从头数起。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杏花天 寿杨经历七十一' AND p.poem_author = '史鉴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵俞仲基对雨二首 其一', '董纪', '明代', '田家信五行，甲子只祈晴。柱础俄先润，天瓢忽屡倾。\n\n水声寒汨汨，云气白英英。缩手防揫敛，农人奈此情。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵俞仲基对雨二首 其一' AND p.poem_author = '董纪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('松石行窝', '张宁', '明代', '静老山林故有期，行轩移凿是何时。阴连绝壁云孤峭，枝压浮峰雨半欹。\n\n十载风霜寒士节，万间梁础大方姿。陶潜已去元章远，岁晏斋空只自怡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '松石行窝' AND p.poem_author = '张宁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('松江金泽寺四首 其二', '唐顺之', '明代', '三江抱处势如环，野客探奇住不还。一望楼台疑海上，稍闻鸡犬觉人间。\n\n幸无渔父知名姓，且与山僧共闭关。自笑归来张季子，春时莼叶未堪攀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '松江金泽寺四首 其二' AND p.poem_author = '唐顺之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高宗纯皇帝御制平定两金川凯歌三十章乾隆四十一年 其二十四', '弘历', '清代', '准部回城定五年，金川小寇亦如前。嘉予将士久敌忾，不觉对之增恻焉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高宗纯皇帝御制平定两金川凯歌三十章乾隆四十一年 其二十四' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('昌溪水', '杜如篪', '宋代', '险绝昌溪水，如何亦问津。\n命分毫发地，利役古今人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '昌溪水' AND p.poem_author = '杜如篪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('海音诗', '刘家谋', '清代', '迎年饯腊事休论，爆竹声中欲断魂。争得城西黄太学，一囊夜半忽敲门。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '海音诗' AND p.poem_author = '刘家谋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长须国驸马咏妻', '长须国驸马', '唐代', '花无叶不妍，女无须亦丑。丈人试遣惣无，未必不如惣有。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长须国驸马咏妻' AND p.poem_author = '长须国驸马';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送默然上人归天台', '王镃', '宋代', '孤云不定心，持缽度寒林。\n野饭青蒲洁，秋程黄叶深。\n海风潮水发，山雨晓烟沉。\n归到石桥日，应看瀑布吟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送默然上人归天台' AND p.poem_author = '王镃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病中初见梅花驰送季申枢密并以二绝', '李弥逊', '宋代', '病眼逢药不忍窥，飞奴走送已嫌迟。\n定知着意怜纤瘦，不放春心落别枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病中初见梅花驰送季申枢密并以二绝' AND p.poem_author = '李弥逊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('抵平彝', '戴絅孙', '清代', '未肯因人热，宵长拥敝裘。寒风支酒力，旧雨絮乡愁。\n\n垒石山为障，清溪水自流。帝京今万里，新纪少年游。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '抵平彝' AND p.poem_author = '戴絅孙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('七鲲身', '钱琦', '清代', '海中有鲲夜化鹏，将飞似堕忽伏蹲。浸作千年老云根，分排玉立如弟昆。\n\n蛟宫千丈姿雄跨，鳄浪万里供馋吞。壮气已作长虹吐，远势欲挟孤鸾骞。\n\n如砥狂澜留柱石，时挝天鼓殷雷门。左控安平右鹿耳，襟带众汇如缭垣。\n\n当年蛙龟争雄处，犀甲百万齐云屯。一声海吼白骨枯，潮头战血交流浑。\n\n自从归我版图后，恬波息浪清乾坤。升平大业垂万古，异域往往叨殊恩。\n\n祇今穷崖绝壑地，已成紫蟹黄鱼村。我来正值三月暮，裌衣习习春风温。\n\n他山可望不可即，远见一片苍烟痕。天地沧桑本变幻，古今兴废如朝昏。\n\n况复浮生一泡影，忍令岁月逐尘奔。眼中俗客难为论，黯然默默销神魂。\n\n安得如尔息健翮，坐受晚露与朝暾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '七鲲身' AND p.poem_author = '钱琦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('四威仪', '释师范', '宋代', '山中坐，习闲成懒惰。\n少献花，但见猿偷果。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '四威仪' AND p.poem_author = '释师范';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题西村陈氏所藏高待诏水墨四幅 其二', '王恭', '明代', '春水重林旧草庐，半村残雨带归渔。空山不是无猿鹤，惆怅何人更隐居。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题西村陈氏所藏高待诏水墨四幅 其二' AND p.poem_author = '王恭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('逢道者', '张蠙', '唐代', '纵意出山无远近，还如孤鹤在空虚。昔年亲种树皆老， \n 此世相逢人自疏。野叶细苞深洞药，岩萝闲束古仙书。 \n 只寻隐迹归何处，方说烟霞不定居。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '逢道者' AND p.poem_author = '张蠙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '张嵲', '宋代', '此堂纵逐人俱废，亦有阳冰篆字存。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '张嵲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('郊庙歌辞。释奠文宣王乐章。舒和', '佚名', '唐代', '隼集龟开昭圣烈，龙蹲凤跱肃神仪。 \n 尊儒敬业宏图阐，纬武经文盛德施。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '郊庙歌辞。释奠文宣王乐章。舒和' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('阆州', '汪元量', '宋代', '阆州城南海棠溪，客子不可无新诗。正嫌风搅浪花碎，更被雨冲云叶垂。\n\n野鸥出没底心性，山禽飞舞犹威仪。江南或问阆州景，锦屏山水天下奇。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '阆州' AND p.poem_author = '汪元量';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('苏幕遮', '王哲', '元代', '道无言，禅没说。两道白光，唯许红霞设。真玉山头常摆拽。\n\n泼滟滟兮，返照灵峰雪。\n\n愈玲珑，元皎洁。射透晴空，莹莹神光别。到此玄玄玄妙彻。\n\n一朵金花，里面金丹结。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '苏幕遮' AND p.poem_author = '王哲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('晚至平望驿欲行阻风有怀吴中所知', '梁以蘅', '明代', '江云漠漠水迢迢，去越孤舟逐浪摇。微月尚堪乘晚棹，回风故遣息寒桡。\n\n正思吴地人方迩，为问枫桥路岂遥。此夜客肠翻欲结，高栖几处莫吹箫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '晚至平望驿欲行阻风有怀吴中所知' AND p.poem_author = '梁以蘅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('董逃行', '陆游', '宋代', '汉末盗贼如牛毛，千戈万槊更相鏖。\n两都宫殿摩云高，坐见霜露生蓬蒿。\n渠魁赫赫起临洮，僵尸自照脐中膏。\n危难继作如崩涛，王朝荒秽谁复薅？踰城散走坠空壕，扶老将幼山中号。\n昔者群枉根株牢，众愤不能损秋毫；谁知此乱亦不遭，名虽放斥实遁逃。\n平民踣死声嗷嗷，今兹受祸乃我曹！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '董逃行' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题余芳谷左右修竹图', '安伟', '清代', '爱竹能留客，无君不可居。相亲思德茂，得意左心虚。\n\n坐啸谐清韵，行吟动翠裾。请看佳士照，左右尽林于。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题余芳谷左右修竹图' AND p.poem_author = '安伟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏禹', '王十朋', '宋代', '洪流浩浩浸寰区，民杂蛇龙鸟兽居。长叹当时微帝力，苍生今日尽为鱼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏禹' AND p.poem_author = '王十朋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('舟行青溪道中入歙十二首 其十一', '方回', '宋代', '蕨拳欲动茗抽芽，节近清明路近家。五日缓行三百里，夹溪随处有桃花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '舟行青溪道中入歙十二首 其十一' AND p.poem_author = '方回';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辰玉应试留都赋此赠之兼赠孟孺 其一', '王世贞', '明代', '欲识操觚业，为之无以为。熟若转丸蜣，专则抱卵鸡。\n\n灵台仅一寸，武火安所施。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辰玉应试留都赋此赠之兼赠孟孺 其一' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽戴彦诚通判三首 其三', '刘才邵', '宋代', '贾鵩由来忌，应曾为废书。始终归有数，善庆岂无馀。\n\n贤嗣真兰玉，令名惊里闾。他年定通显，跃马从金舆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽戴彦诚通判三首 其三' AND p.poem_author = '刘才邵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南天门揽胜轩作', '弘历', '清代', '盘纡石路陟嶙峋，揽胜还欣回出尘。何必森严卫虎豹，居然尺五俯星辰。\n\n云轩峰岭延遥近，梵宇香花悦静真。大士如如无色相，却看历历往来人。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南天门揽胜轩作' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('以诗句咏梅 十年花送诗人老', '方蒙仲', '宋代', '花老几人来，人老花常少。安得似花人，年年陪一笑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '以诗句咏梅 十年花送诗人老' AND p.poem_author = '方蒙仲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和散木韵 其六', '袁宏道', '明代', '落叶蔽秋矶，残霞雨洗晖。弹花蝉虎匿，掠竹水鹰飞。\n\n白足遗棕屦，青娥送道衣。庖童觅鲙去，兼买紫姜归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和散木韵 其六' AND p.poem_author = '袁宏道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('三花斛三首右兰花', '杨万里', '宋代', '雪径偷开浅碧花，永根乱吐小红芽。\n生无桃李春风面，名在山林处士家。\n政坐国香到朝市，不容霜节老云霞。\n江蓠圃蕙非吾耦，付与骚人定等差。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '三花斛三首右兰花' AND p.poem_author = '杨万里';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('行香子 七夕', '许德蘋', '清代', '阶下秋蛩。井畔疏桐。正今宵牛女情浓。经年别绪，愁诉重重。\n\n料星桥南，星桥北，喜相逢。\n\n人间乞巧，好陈瓜果，也怜他离恨无穷。银湾斜转，砧杵声中。\n\n剩一炉烟，一钩月，一帘风。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '行香子 七夕' AND p.poem_author = '许德蘋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('积翠楼', '危和', '宋代', '著我高远堂，恍若非人世。一榻卧白云，清寒不成寐。\n\n松竹四山秋，飕飕惊客耳。谁在隔窗中，朱弦写流水。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '积翠楼' AND p.poem_author = '危和';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江雨来', '邵宝', '明代', '西津渡头江雨来，雨点入江江水回。云飞逐风沙走石，咫尺不见东冈台。\n\n台树丛丛还可望，台上看江更奔放。明朝拟下鄱阳船，月色浮江水微浪。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江雨来' AND p.poem_author = '邵宝';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('乙巳岁郊天后作', '魏野', '宋代', '万物尽熙熙，郊天礼毕时，\n安边文教远，过海赦书迟。\n南牧虽无也，东封合有之。\n茅堂自歌咏，何必向丹墀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '乙巳岁郊天后作' AND p.poem_author = '魏野';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春尽日', '赵蕃', '宋代', '山密风蟠木，檐疏雨著窗。\n拥衣憎旧絮，酌酒爱新缸。\n放意初无累，冥观久已降。\n一春今日尽，归梦渺三江。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春尽日' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('闻二十八日之报喜而成诗七首 其四', '朱熹', '宋代', '渡淮诸将已争驰，兔脱鹰扬不会期。杀尽残胡方反旆，里闾元未有人知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '闻二十八日之报喜而成诗七首 其四' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '赵湘', '宋代', '十度花残一觉眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '赵湘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丹霞舍利塔', '释函是', '明代', '心光彻内外，如珠入五色。珠与色无性，非离亦非即。\n\n非即超形骸，非离浃营卫。月在千波中，波波摇青霁。\n\n凡圣唯一心，湛昏成二谛。示生死涅槃，而实无坚脆。\n\n脆以别生死，坚光表性义。本从心生色，迷色乃有二。\n\n蚌含明月珠，体合百骸粹。领纳镜中像，想即妙观智。\n\n流注皆真常，分别非明记。如是五蕴身，与法身何异。\n\n秖因一念迷，情生分秽净。净秽悟由心，当念绝邪正。\n\n佛以此智證，法化无同别。示现别中同，同中别自晰。\n\n光耀百千年，福被我遗教。神光触金轮，仰瞻如梦觉。\n\n栖贤发瑰异，感激当其运。移光照岭南，慈曜无远近。\n\n佛子学聚沙，燔土紫金斓。崔巍海螺巅，晶晶逼霄汉。\n\n举目道与会，布发形俱泮。见闻起遐情，究此未来际。\n\n念念尽圆明，身与心毋戾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丹霞舍利塔' AND p.poem_author = '释函是';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('有赠 其四 黎益之、杨永权', '刘斯奋', '当代', '才人珠海说黎杨，三日谈诗未举觞。何不放舟兵气夜，红醪浓注一湖霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '有赠 其四 黎益之、杨永权' AND p.poem_author = '刘斯奋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('区民部熊孝廉赵山人雨后同集旅寓', '李孙宸', '明代', '雨过庭前长绿苔，青尊旬日未曾开。偶逢南国高人集，便挟西山爽气来。\n\n懒性自知难和世，宦情真冷不然灰。周南留滞吾今似，深愧龙门一代才。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '区民部熊孝廉赵山人雨后同集旅寓' AND p.poem_author = '李孙宸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄酬致政赵少师五首 其五', '赵抃', '宋代', '天台雁荡去寻真，往复秋冬过七旬。不是君恩山岳重，肯教归作自由身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄酬致政赵少师五首 其五' AND p.poem_author = '赵抃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄滕县李奉议', '陈师道', '宋代', '滕大夫伯阳父孙，烹小鲜治大国原。\n一得何用五千言，弛灾决狱人不冤。\n盛气走讼畏讨论，终岁敛吏不到门。\n子弟无赖皆西奔，外吏畏惧过乃尊。\n踵门父老如云屯，拊髀跳踉走儿孙。\n绛幡翠节歌呗喧，画盆戴顶烟如焚。\n绣褾彩轴箱帕繁，曲躬叉手前致言。\n畜眼未见耳不闻，暮年何以答此恩，\n请诵华严寿我君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄滕县李奉议' AND p.poem_author = '陈师道';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('刘德明彦集祝弟以夏云多奇峰为韵赋诗戏成五绝 其一', '朱熹', '宋代', '出山几何时，归来便长夏。端居心不怡，散策长林下。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '刘德明彦集祝弟以夏云多奇峰为韵赋诗戏成五绝 其一' AND p.poem_author = '朱熹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('海陵岁暮 其一', '孙应时', '宋代', '地气长江北，云容古戍边。层冰明薄日，积雪了穷年。\n\n乡远劳羁梦，官閒足晏眠。客来相劳苦，不责坐无毡。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '海陵岁暮 其一' AND p.poem_author = '孙应时';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蠡湖行', '王鉴', '明代', '山苍苍，水泱泱，湖天一钓青茫茫。云是范蠡扁舟之归路，湖田绿雨，两岸浸垂杨。\n\n千丝万丝蘸波面，年年逝水随流光。老渔醉不醒，醒起满船霜。\n\n霜风叫寒鹰，一字横吴江。沼吴人去鸥拍拍，天澹云闲几狂客。\n\n狂客大笑何为乎，夫差一醉亡其国。又复感慨贤豪闲，范蠡归来欲谋食。\n\n彼诚不必登西山而采蕨薇，亦奚不先严陵而坐磐石。\n\n噫嘻乎，千金或可谋，幼子亦可惜。积财不散天厌之，山亦欲崩海亦溢。\n\n我歌蠡湖行，声与秋云翔。秋云无定忽变灭，水底分明见湖月。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蠡湖行' AND p.poem_author = '王鉴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('小字', '孙原湘', '清代', '谢公最小女偏怜，小字呼来定绛仙。一月回悬珠树朗，百花都让玉梅妍。\n\n疗饥自喜忘并日，消渴何辞为损年。每向画眉窗下见，匡庐只在镜台前。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '小字' AND p.poem_author = '孙原湘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠湘南易淑南 其二', '李锴', '清代', '怀香何处问芳荪，文藻风流宋玉存。万里惊波漂断梗，不堪摇落赋招魂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠湘南易淑南 其二' AND p.poem_author = '李锴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('旅兴 其四十四', '刘基', '元代', '日落天气凉，逍遥步庭墀。蟋蟀巳在宇，鸿雁来何迟。\n\n少壮轻远游，衰老伤别离。念我亲与友，各在天一涯。\n\n音容两契阔，悲欢绝相知。铩羽怀旧林，葺繗思故池。\n\n百年能几何，逝者无还期。俛仰增感叹，有怀当语谁。\n\n殷勤托宵梦，聊用慰所思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '旅兴 其四十四' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('一剪梅·唱到阳关第四声', '刘仙伦', '宋代', '唱到阳关第四声。香带轻分。罗带轻分。杏花时节雨纷纷。山绕孤村。水绕孤村。\n更没心情共酒尊。春衫香满，空有啼痕。一般离思两销魂。马上黄昏。楼上黄昏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '一剪梅·唱到阳关第四声' AND p.poem_author = '刘仙伦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清湘城西飞来峰 其二', '曾丰', '宋代', '三处飞来一样奇，佛无所择我何辞。重轻较到毫釐处，鸣雁行中此白眉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清湘城西飞来峰 其二' AND p.poem_author = '曾丰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄长乐尉廖声玉', '成鹫', '明代', '吏隐如君得自然，多生曾结衲僧缘。春风怅别同为客，故国言归老此禅。\n\n前路一投孤店宿，居人尽说长官贤。自从识得齐昌尉，始信梅生是人仙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄长乐尉廖声玉' AND p.poem_author = '成鹫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('每见村农野老不识不知天然自得孝弟发于至性朴诚不事文辞故美其实而取先进之意赋七言一律', '玄烨', '清代', '昼夜徬徨利禄间，奚如鄙里野人閒。诗书不解穷通事，名姓无闻士宦班。\n\n孔颜乐处箪瓢在，孝弟真情稚子关。可笑文章少实据，空将浮伪玷青纶。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '每见村农野老不识不知天然自得孝弟发于至性朴诚不事文辞故美其实而取先进之意赋七言一律' AND p.poem_author = '玄烨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('听蓼庵处士弹汉宫秋', '吕师濂', '清代', '雪云垂幕风飕飂，天荒地老客倦游。多君开手抚玉轸，凄清弹出《汉宫秋》。\n\n初如洞庭下木叶，复如滟滪泻寒流。得无酒徒击别筑，得无嫠妇泣孤舟。\n\n又疑猿啼向空谷，又疑雁叫落高楼。借问此曲声何悲，令我忽忆国破时。\n\n先帝有琴曰翔凤，玉熙宫里常携随。时当中秋开夕宴，袁妃敛衽弹《关雎》。\n\n意静指闲人月下，商流羽激声云飞。星河斜度仙人掌，鸾鹤齐鸣百子池。\n\n玉槃进酒葡萄暖，一挥再鼓天颜怡。须臾寇盗肆窃发，衣宵食旰筹征伐。\n\n无复重闻《金缕衣》，何曾还对丝桐月。翔凤无端霹雳鸣，朱弦一一如刀截。\n\n至尊惨澹竟攒眉，宫妾惊惶群吐舌。事在甲申春之初，传其说者中涓吴。\n\n不道三月十九日，乾翻坤陷龙鼎湖。峄阳之桐识治乱，八音遏密钟虚换。\n\n金枝玉叶坐彫残，凤尾谁怜应出爨。吾民从此忆薰风，师旷师襄逐断蓬。\n\n臣本恨人闻苦调，依稀泪带甲申红。翔凤而今安在哉，手琴囊锁亦休开。\n\n亟须满饮三百杯，将愁遣去无使来。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '听蓼庵处士弹汉宫秋' AND p.poem_author = '吕师濂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('洞仙歌 其一 念台先生海天旭日砚，裔孙海门绘图，属题', '奭良', '清代', '韩陵片石，去名贤未远。且做人閒鼎彝看。忒煞坚、耐他磨了还磨，谁比似、只玉带遥遥作伴。\n\n留传都有意，付与云礽，慷慨乘城伴危难。拂拭莫开帘，咫尺图中，海波沸、日光幽黯。\n\n属木石、吴儿莫轻题，怕青针穿时，素笺难浣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '洞仙歌 其一 念台先生海天旭日砚，裔孙海门绘图，属题' AND p.poem_author = '奭良';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪沙（席上别王巨济。先是，两姬免冠，王夺两秩，继以章罢）', '洪适', '宋代', '丹桂飘香已四番。杖藜携手自今难。黯然离恨满江干。 \n 壁上两冠元是谶，花前双韵几时弹。中秋后夜与谁看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪沙（席上别王巨济。先是，两姬免冠，王夺两秩，继以章罢）' AND p.poem_author = '洪适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('天仙子', '张振', '清代', '画阁雕栏春暗渡。行来罗袜苍苔护。日长人倦不胜情，香满炷。\n\n风吹幕。啼莺却在花深处。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '天仙子' AND p.poem_author = '张振';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('对酒', '薛蕙', '明代', '畏涂有千虑，劳生无寸隙。\n唯余对酒时，暂作伸眉客。\n妖姬杂睇笑，欢友连衿舄。\n相逢判一醉，钱刀非所惜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '对酒' AND p.poem_author = '薛蕙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('凉州词二首 其一', '邓云霄', '明代', '城高楼角近旄头，边月胡风早送秋。不信凉州多猛将，还听稚子说封侯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '凉州词二首 其一' AND p.poem_author = '邓云霄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桂州 其四', '陶弼', '宋代', '旧策扫开浪泊雾，新诗装就桂林春。相离水色秋前老，独秀岚光霁后匀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桂州 其四' AND p.poem_author = '陶弼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十四日 其一', '韩淲', '宋代', '淡淡春晴晚，窗前燕子飞。酒杯谁共饮，诗笔自孤挥。\n\n上冢家山远，下湖仙苑稀。空多冶游者，扶醉赶门归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十四日 其一' AND p.poem_author = '韩淲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('清江引 其二', '孙承恩', '明代', '篷窗雨来人未寝。早已知寒信。暂借酒留春，无奈霜堆鬓。\n\n兰缸幽幽频落烬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '清江引 其二' AND p.poem_author = '孙承恩';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春游与谢都尉二首 其一', '张元凯', '明代', '柳市裁春服，花郊费酒钱。家贫不事事，行乐自年年。\n\n黄鸟催提榼，青衣佐刺船。未须投逆旅，芳草正堪眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春游与谢都尉二首 其一' AND p.poem_author = '张元凯';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春晴', '任翻', '唐代', '楚国多春雨，柴门喜晚晴。幽人临水坐，好鸟隔花鸣。 \n 野色临空阔，江流接海平。门前到溪路，今夜月分明。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春晴' AND p.poem_author = '任翻';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送人之蜀郡守', '王称', '明代', '闻道蚕丛国，西连汉陇平。三年怀紫袖，万里慰苍生。\n\n夜月巴川静，秋风锦水清。请看霜锷试，莫使雪山倾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送人之蜀郡守' AND p.poem_author = '王称';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('失题', '佚名', '魏晋', '鹓彼鸣鹣。在严山之唫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '失题' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史 其三', '孙应时', '宋代', '拊髀平生志八区，暮年家国付夷吾。谁言子女能相豢，可笑周郎浅丈夫。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史 其三' AND p.poem_author = '孙应时';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('求酒赵评事', '赵崇滋', '宋代', '半老情怀睡不能，小檐霜月当寒灯。无人来问相如渴，敲碎梅花一夜冰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '求酒赵评事' AND p.poem_author = '赵崇滋';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春日怀京华诸友', '郑善夫', '明代', '闻说神龙起，群贤一网提。中原刑白马，南国且黄鹂。\n\n夜楫谁同击，春江他自迷。无能逐公子，锡宴上林西。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春日怀京华诸友' AND p.poem_author = '郑善夫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('早出小东门至藕渠镇', '方仁渊', '清代', '晨起驾柔橹，宿雾犹冥冥。晓日冲波白，遥山带郭青。\n\n鱼盐喧小市，鹜雁聚寒汀。自笑谋生拙，孤舟未敢停。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '早出小东门至藕渠镇' AND p.poem_author = '方仁渊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('暗室', '丘葵', '宋代', '一几善恶未分时，善本无为莫伪为。\n暗室休言人不见，此心才动鬼神知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '暗室' AND p.poem_author = '丘葵';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('己酉新春二首', '吴梦旸', '明代', '自拟今春怀抱开，林扉时复扫荒苔。\n沙头鸥鸟休飞去，野外梅花许折来。\n多少误人空识字，从容留客不衔杯。\n题书遍问诸名胜，肯入庐山般若台。¤', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '己酉新春二首' AND p.poem_author = '吴梦旸';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('茶园别朱伯言郭公葵', '刘基', '元代', '细水吹烟送客舟，离情恰似水东流。此时对酒难为乐，何处寻春可纵游。\n\n去雨来云天渺渺，轻蜂乱蝶日悠悠。绝怜短发无聊赖，一夜如丝白满头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '茶园别朱伯言郭公葵' AND p.poem_author = '刘基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('歧路行', '陆寅', '清代', '出门竟何之，东西南北皆路歧。仆夫执辔马踯躅，骊歌一声声最悲。\n\n道傍桃李似惜别，飞花故扑金屈卮。人生目前贵适意，不如还逐屠沽儿。\n\n兄袁盎，弟灌夫，相逢自负高阳徒，樗蒱百万能呼卢。\n\n朝金张，暮许史，拔剑欲为知己死，眼前谁是严仲子？', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '歧路行' AND p.poem_author = '陆寅';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('宝应朱公曾乞蒲团于僧润归榇江州润乃买舟赴葬挂树而去', '盛时泰', '明代', '生前曾与结幽期，身后冥交独有师。为挂蒲团思往日，因弹锡杖忆当时。\n\n泪随雪片应难尽，情断风灯总自持。法力护来还不灭，年年慧树长新枝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '宝应朱公曾乞蒲团于僧润归榇江州润乃买舟赴葬挂树而去' AND p.poem_author = '盛时泰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('雪中独行湖上三首 其三', '李冰若', '近代', '孤山处处屐曾经，最爱林家放鹤亭。休问梅花开也未，雪中乍见柳条青。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '雪中独行湖上三首 其三' AND p.poem_author = '李冰若';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('喻邦相即署中建楼题曰信美索诗为赋四绝 其一', '胡应麟', '明代', '胡床明月坐高秋，碧瓦朱甍大海头。十二危阑宾从满，一时传作庾公楼。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '喻邦相即署中建楼题曰信美索诗为赋四绝 其一' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吊赤水李先生', '徐夤', '唐代', '三年悲过隙，一室类销冰。妻病入仙观，子穷随岳僧。 \n 荒丘寒有雨，古屋夜无灯。往日清猷著，金门几欲征。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吊赤水李先生' AND p.poem_author = '徐夤';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花十绝句', '赵蕃', '宋代', '十里荆溪溪上梅，故人几日寄诗来。\n相应载酒裴回次，忆我去年同此杯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花十绝句' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('菩萨蛮', '饶宗颐', '近代', '带愁眉萼阑干曲。春风吹上裙腰绿。去水木兰舟。分愁压翠楼。\n\n黄衫催马发。楼下花如雪。花雪莫分看。昨宵风雨寒。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '菩萨蛮' AND p.poem_author = '饶宗颐';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题张雪湖吴山煖暧', '释居简', '宋代', '山藏晻霭树藏云，十驾难追欲去春。鳞砌古愁千万绪，因君开卷又重新。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题张雪湖吴山煖暧' AND p.poem_author = '释居简';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂二百零五首', '释正觉', '宋代', '不问维摩经，看底甚麽经，\n大千卷出破尘情。水中盐味，\n色里胶青，机前有路妙难名。\n才形言像迢然去，又是泥团换眼睛。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂二百零五首' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('荆轲山', '弘历', '清代', '白云红叶遮横峦，策骑忽过荆轲山。燕南自古多义侠，至今遗迹犹班班。\n\n嬴秦久矣失其鹿，何须怒臂誇燕丹。吁嗟世多耳食流，传闻傅会葬衣冠。\n\n持短入长空有术，投鼠忌器垂大闲。由来尺八不足恃，衍水匿迹馀悲叹。\n\n秋风九月拂征鞍，想像萧萧易水寒。当时壮士不复返，安得若斧留山巅。\n\n徒令千秋吊古人，恨不终从鞠武言。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '荆轲山' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('水调歌头', '陈敷', '宋代', '明月双溪上，胜景号金华。当年此夕，多少鸾凤杂云霞。共拥飘摇倦伯，来作人间英杰，王谢旧名家。纶綍妙文采，帷幄富忠嘉。 \n 圣天子，形梦寐。眷尤加。麒麟烟上早晚，丹陛听宣麻。鼎袖无穷勋业，岁岁薰风日永，萱秀北堂花。潋滟绮筵酒，寿算等胡沙。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '水调歌头' AND p.poem_author = '陈敷';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('九日期登大慈恩寺阁不果寄献吉', '徐祯卿', '明代', '怅忆青莲宇，今朝黄菊开。遥知远公笑，不见白衣来。\n\n窈窕人天阁，峥嵘日月回。山川纷楚望，城阙动秋哀。\n\n岘首羊公石，淮阴戏马台。风烟那可即，逸兴杳难裁。\n\n强负登楼作，虚传落帽才。此时遥独酌，念尔重悠哉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '九日期登大慈恩寺阁不果寄献吉' AND p.poem_author = '徐祯卿';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虞美人', '冯时行', '宋代', '芳菲不是浑无据。只是春收取。都将酝造晚风光。百尺瑶台、吹下半天香。 \n 多愁多病疏慵意。也被香扶起。微吟小酌送花飞。更拼小屏幽梦、到开时。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虞美人' AND p.poem_author = '冯时行';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('省中二首 其二', '王安石', '宋代', '大梁春雪满城泥，一马常瞻落日归。身世自知还自笑，悠悠三十九年非。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '省中二首 其二' AND p.poem_author = '王安石';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠寻贤赵相士', '王柏', '宋代', '赤脚佯聋术有神，贤才未必要贤寻。\n寻贤牌子非贤物，自是君王坐右箴。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠寻贤赵相士' AND p.poem_author = '王柏';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('桐柏山黄法师斋', '高似孙', '宋代', '羽人归丹丘，轻房冒苍顶。\n云飞北斗坛，瀑洗洪崖井。\n三更火交坎，八十雪垂领。\n深香熨玉斧，淑气回丹鼎。\n彼空此亦无，物动我自静。\n灼知乔松辈，元涉义老境。\n一来受清涤，内悟开微儆。\n请添无为香，上有萧台景。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '桐柏山黄法师斋' AND p.poem_author = '高似孙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('金菊对芙蓉 抵家', '赵熙', '清代', '雁外青山，马头黄叶，嘉州两日三荣。算程程归梦，节节离声。\n\n菊花催老悲秋客，误几人、身后诗名。一鞭残照，中原北望，前世西清。\n\n无策消遣馀生。集锦江耆旧，各各渊明。唱迷阳旧曲，有恨谁听。\n\n行装一卸鸦先喜，向枝头、如唤樵青。寸心遥夜，屋梁月落，山火寒星。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '金菊对芙蓉 抵家' AND p.poem_author = '赵熙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('念奴娇·病起', '黄之隽', '清代', '屏低六扇，耐朝来、惯度药炉烟影。著背寒生帘不捲，阴雪瓦棱犹剩。\n\n炙炭才红，呵毫未黑，懒趣唯耽静。谁来寻伴，小窗天气初暝。\n\n同是千里依人，柔情绕指，为惜天涯病。流水年光如梦里，孤负灯前人醒。\n\n串断喉珠，字消心篆，绣被多时冷。笑拈图画，一团梅竹相映。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '念奴娇·病起' AND p.poem_author = '黄之隽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寓舍偶题', '甘瑾', '明代', '四海戎麾满，中原汗马疲。\n龙蛇伤纪岁，麟凤叹非时。\n土贡包茅废，边防羽檄驰。\n杜陵忧国念，蒦闷强裁诗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寓舍偶题' AND p.poem_author = '甘瑾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('点绛唇 闺思', '王寂', '元代', '疏雨池塘，一番雨过香成阵。海榴红褪。燕语低相问。冰簟纱ε，玉骨凉生润。沈烟喷。日长人困。枕破斜红晕。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '点绛唇 闺思' AND p.poem_author = '王寂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('庐山道中 其三', '李彭', '宋代', '三年不饮虎溪水，一笑来尝鹰爪芽。岑寂仲堪谈易地，祇馀苍藓藉残花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '庐山道中 其三' AND p.poem_author = '李彭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('落花五十首 其二', '沈周', '明代', '飘飘荡荡复悠悠，树底追寻到树头。赵武泥涂知辱雨，秦宫脂粉惜随流。\n\n痴情恋酒粘红袖，急意穿帘泊玉钩。欲拾残芳捣为药，伤春难疗个中愁。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '落花五十首 其二' AND p.poem_author = '沈周';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('京口阻雨', '林寿图', '清代', '苍然寒色暮烟横，跕跕飞鸢与水平。三日塔铃呼断渡，一江帆叶贴依城。\n\n远钟自出南朝寺，晓角如鏖北府兵。破费千钱京口酒，醉看高浪驾长鲸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '京口阻雨' AND p.poem_author = '林寿图';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南天窝授竹影题用徐天池香烟韵七首 其五', '王夫之', '明代', '凭阑觌面不相知，邂逅晴窗瞥见时。浅黛斜分临晓镜，落花轻惹上蛛丝。\n\n萍开绿水鱼情得，叶坠幽光鸟梦奇。活色暗香难举似，浮沤目醉共清嬉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南天窝授竹影题用徐天池香烟韵七首 其五' AND p.poem_author = '王夫之';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('江行杂咏十首 其六', '江源', '明代', '路长寄书少，水涸归舟迟。渔子团栾乐，焉知人别离。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '江行杂咏十首 其六' AND p.poem_author = '江源';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('重阳', '王懋德', '元代', '拂却京尘理去舟，閒云千里水悠悠。醉来欲落龙山帽，犹恐黄花笑白头。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '重阳' AND p.poem_author = '王懋德';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题沈周写生二十四种 其十二 葱', '弘历', '清代', '岭久传西域，盘仍佐五辛。巳知根似玉，谁辨下生银。\n\n标倩含朝露，纽芽报早春。可怜洛阳狱，陆续独思亲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题沈周写生二十四种 其十二 葱' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('亲戚小集', '范成大', '宋代', '避湿违寒不出门，一冬未省正冠巾。\n月从雪后皆奇夜，天向梅边有别春。\n秉烛登临空语旧，拥炉情味莫怀新。\n荣华势利输人惯，赢得尊前现在身。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '亲戚小集' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('镫下', '陈梓', '清代', '积阴镫下焰，独坐冷添衣。江阔书难度，峰高梦不归。\n\n耳听寒食近，发为故园稀。莫是愁城恼，多缘酒力微。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '镫下' AND p.poem_author = '陈梓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寿王仲锡臬宪 其十四', '释今无', '明代', '智珠抛掷古皇前，精白为心自永年。不羡阆风餐石脑，邦之司直足人传。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寿王仲锡臬宪 其十四' AND p.poem_author = '释今无';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('长相思 无题', '史鉴', '明代', '花满枝。蝶满枝。客舍恹恹卧病时。愁闻春鸟啼。\n\n为相思。苦相思。相别常多相见稀。缠绵无了期。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '长相思 无题' AND p.poem_author = '史鉴';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浣溪纱', '吕碧城', '清代', '风籁鸣哀起翠条，撩人心绪涨秋潮，仙源回望转无聊。\n\n去去莫教重顾影，行行何必更停桡，愁山怨水一身遥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浣溪纱' AND p.poem_author = '吕碧城';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('六合别俞邦诚', '庄昶', '明代', '孤舟一雨带秋开，何处弓旌万里来。已分深山甘朽木，岂知优诏起非才。\n\n人间百事添霜鬓，老去虚名愧钓台。把手欲将离别句，不胜千古送秋怀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '六合别俞邦诚' AND p.poem_author = '庄昶';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('灵芝观上人房植紫竹一本覆屋其上以庇朝日顾', '毛滂', '宋代', '阶前紫玉似人长，可怪龙孙久未骧。\n第放烟梢出檐去，此君初不畏风霜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '灵芝观上人房植紫竹一本覆屋其上以庇朝日顾' AND p.poem_author = '毛滂';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红 其五 赠潘原白兼题新居，五叠前韵', '董元恺', '清代', '烂漫才华，惊人句、潘江涌出。尽少年、狂歌作达，外疏中密。\n\n红粉一生三妇艳，黄庭五色千枝笔。更清泉、白石寓经纶，谁堪匹。\n\n楹与桷，施丹漆。亭与阁，凌云日。恰满樽桑落，堆盘芋栗。\n\n招隐小山俱是桂，高吟药圃宁须术。人诸君、击剑复弹棋，纵横术。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红 其五 赠潘原白兼题新居，五叠前韵' AND p.poem_author = '董元恺';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('日本谣十二首 其五', '郁达夫', '近代', '名隶昭阳供奉班，宫词巧制念家山。劫来源氏人争说，曾使君王一破颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '日本谣十二首 其五' AND p.poem_author = '郁达夫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽杨子美侍郎 其一', '孙应时', '宋代', '游刃刀无缺，韬光玉自温。世途犹砥柱，士论亦龙门。\n\n仁者宜三寿，天乎遽九原。老成周雅叹，此事更谁论。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽杨子美侍郎 其一' AND p.poem_author = '孙应时';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过秦楼 寄秦都御史屿湖', '夏言', '明代', '徐孺亭边，滕王阁畔，旧识中丞开府。燕雀春闲，鱼龙夜静，白昼满城箫鼓。\n\n时看节钺临戎，宫墙较士，笑谈樽俎。有邦人报道，十郡兵销，九江度虎。\n\n望故园、宝泽楼成，琼恩堂启，轮奂翚飞百堵。仰荷皇恩，钦承帝敕，经画有烦地主。\n\n庐阜风烟，灵峰云气，壮观大江今古。今非才遭际，合家岂堪霖雨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过秦楼 寄秦都御史屿湖' AND p.poem_author = '夏言';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('八月二十二日嘉州大阅', '陆游', '宋代', '陌上弓刀拥寓公，水边旌旆卷秋风。\n书生又试戎衣窄，山郡新添画角雄。\n早事枢庭虚画策，晚游幕府媿无功。\n草间鼠辈何劳磔，要挽天河洗洛嵩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '八月二十二日嘉州大阅' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('挽胡团王先生诗 其二', '韩淲', '宋代', '著述钦成说，叮咛忆绪言。不期捐几杖，无复贲丘园。\n\n行旐村前路，丰碑屋外原。形容惭识浅，相挽只馨吞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '挽胡团王先生诗 其二' AND p.poem_author = '韩淲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渔父词', '王庭圭', '宋代', '冥冥江雨湿蓑衣，夜上高岩宿翠微。梦断一声烟草绿，遥闻款乃扣舷归。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渔父词' AND p.poem_author = '王庭圭';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红', '卢炳', '宋代', '碧眼真仙，算元住、蓬莱宫里。记当日、等闲跨鹤，人间游戏。要把忠勋扶帝业，更将姓字联宗系。拥朱轮、特地为民来，诗书帅。 \n 千里地，都和气。十万户，生欢喜。祝黄堂眉寿，歌谣鼎沸。莫惜春醅供燕豆，便承芝检朝天陛。看云屏、隔坐并貂蝉，双清贵。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红' AND p.poem_author = '卢炳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('朱太史元价以巧夕后五日社集斋头时沴异弥数旬矣是夕雨月交飞阴晴递换诸同好皆有愁霖之赋余得短律二章 其一', '张萱', '明代', '星联杓极北，天漏日华东。下马歌匏叶，逢人问菊藭。\n\n雷声犹破块，蟾影却吹风。变幻由来事，阴晴一瞬中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '朱太史元价以巧夕后五日社集斋头时沴异弥数旬矣是夕雨月交飞阴晴递换诸同好皆有愁霖之赋余得短律二章 其一' AND p.poem_author = '张萱';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('石门', '元好问', '元代', '两崖横绝倚山垠，草径低迷未可分。\n潭影乍从明处见，竹香偏向静中闻。\n石林万古不知暑，茅屋四邻惟有云。\n曳杖行歌羡樵叟，此生何计得随君。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '石门' AND p.poem_author = '元好问';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('歌', '江淹', '南北朝', '芳洲之草行谷暮。\n桂水之波不可渡。\n绝世独立兮报君子之一顾。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '歌' AND p.poem_author = '江淹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上外祖李竹坡先生致尚宝政二十四韵', '王慎中', '明代', '国运开贞泰，今王礼旧耆。颁旌招野伏，惊代擅雄姿。\n\n邦俊推公望，朝章属令仪。丘樊驰束帛，海峤动纶丝。\n\n玉署初移宠，金扉后命贻。西垣瞻日殿，内阙切云司。\n\n雨露青冥润，弁缨象纬疑。秪言翔岳鷟，讵意曳涂龟。\n\n道大经徇禄，几先果避时。竟忘魏阙眷，不废考槃词。\n\n临组惟三揖，封章恳一辞。皇心揆赤悃，温诏下彤墀。\n\n计决群贤早，名高一代垂。沧波薄赤绂，黄发狎青鹥。\n\n栖谷情自得，还山迹信追。直嗤少室出，谁赋北山移。\n\n茑户琴书暇，筠庄岁月迟。江天疏远目，花鸟怯新诗。\n\n傲世南阳蠖，寻仙绮里芝。瑶兰湘畹纫，玉树谢庭枝。\n\n峻节元齐杜，养真亦寻雌。登龙汉士慕，歌凤楚狂悲。\n\n尚想篇翰接，终虚几杖随。因风敷此曲，遥望碧云涯。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上外祖李竹坡先生致尚宝政二十四韵' AND p.poem_author = '王慎中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('彭府君夫人罗氏挽诗 其一', '李弥逊', '宋代', '擢秀芝兰畹，来嫔诗礼庭。好羞贫更洁，寿发短犹青。\n\n秦号封方宠，蓬瀛驾不停。天风助哀怨，吹雨湿丹铭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '彭府君夫人罗氏挽诗 其一' AND p.poem_author = '李弥逊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('辛卯重阳前一日风雨', '傅义', '当代', '正愁风雨近重阳，日课难维千步强。多谢天公犹恤老，教将斗室作康庄。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '辛卯重阳前一日风雨' AND p.poem_author = '傅义';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠别查韬荒 其九', '屈大均', '明代', '岂敢多求友，交君已不孤。谗言从贝锦，清鉴自冰壶。\n\n菡萏双峰出，云霞一气敷。繇来不离别，有道在虚无。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠别查韬荒 其九' AND p.poem_author = '屈大均';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('示同志', '刘克庄', '宋代', '旋入洛中新保社，稍增汾曲旧田庐。\n市朝幸免髠钳我，尸祝何烦俎豆予。\n静看芭蕉身不实，健忘椰子腹无书。\n故人远致郫筒饷，待约邻翁共破除。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '示同志' AND p.poem_author = '刘克庄';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('湘中四咏 其三 鹧鸪', '杨基', '明代', '湘江两岸无茅宇，湘竹阴阴覆江渚。春来未听一声莺，只有鹧鸪啼暮雨。\n\n怜渠亦是他乡客，苦向人啼行不得。纵教行得也消魂，那个行人不头白。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '湘中四咏 其三 鹧鸪' AND p.poem_author = '杨基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('饮仲诚㭨瓢', '刘因', '元代', '君家瓠落无所容，江湖谁辨平生胸。海南佳气久郁塞，滟滪似喜今相逢。\n\n前年对酒面发红，今年对酒气如虹。江山万古骚人国，跬步便与华胥通。\n\n河间古儒病我枸，闻我一饮喜气浓。平生得意南湖张，此意颇与河间同。\n\n太古洼尊老无底，一朝倾倒何由供。醉乡千年有此客，鸟歌蝶舞春濛濛。\n\n醉翁之意不在酒，宛如琴意非丝桐。太和风境无酩酊，洛阳楼阁高玲珑。\n\n泠然仙驭一杯水，眼中渺渺无极翁。西家伯伦瞽且聋，东家醉死王无功。\n\n酒中醒境渠未识，冰壶秋月昆崙峰。举杯唤月来胸中，人间白日浮云空。\n\n五岭山高云几重，朱崖灭没南飞鸿。玄鹤翩翩渺何许？操瓢径访眉山公。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '饮仲诚㭨瓢' AND p.poem_author = '刘因';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('琐窗寒 空闺', '姚燮', '清代', '绿又阴阴，重帘静窣，奈无人个。蟏尘罥网，尚飐几丝绒唾。\n\n认分明、花朝梦回，贴奁解鬓提梳坐。恁小桃待绽，风鹃声紧，丽韶催过。\n\n无那。金鱼锁。任蠹蚀鞋香，雁抛钿朵。残棉断粒，最苦狸寒莺饿。\n\n罨银床、秋梧自鸣，更无杼柚相应和。怕眠时、独影凄凉，掩却霜篝火。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '琐窗寒 空闺' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南斋病卧', '刘敞', '宋代', '香卷风飘幌，灯昏雨映帘。客愁浑不寐，更觉漏声添。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南斋病卧' AND p.poem_author = '刘敞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('谢蔚宗木棉', '沈辽', '宋代', '峤南地熟气如烟，木华蒙茸散为绵。使君作紬远相寄，表似夷锦红欲燃。\n\n病士榻上残青毡，山中苦寒多破穿。使君相赠何可言，困来不妨伸脚眠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '谢蔚宗木棉' AND p.poem_author = '沈辽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东邻二首 其一', '唐庚', '宋代', '即今乐事属墙东，岁晚何曾酒盏空。白蜜已输仍节近，红藤未动况年丰。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东邻二首 其一' AND p.poem_author = '唐庚';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寓斋', '李吕', '宋代', '萍梗天地间，初不异万物。\n可能发深省，惟有一事实。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寓斋' AND p.poem_author = '李吕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送王允常佥事之广东', '王鏊', '明代', '柳叶桄榔五岭南，使君曾此驻帷襜。法冠直指新峨廌，包匦生黎旧贡蚺。\n\n不信鳄鱼还作恶，只应泉水便名廉。殊方风土须珍重，莫为溪山久滞淹。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送王允常佥事之广东' AND p.poem_author = '王鏊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('致一斋述事', '范成大', '宋代', '文书烟海困浮沉，不觉盘跚百病侵。\n偶问客年惊我老，忽闻莺语叹春深。\n今朝麦粒黄堪麪，几日秧田绿似针。\n除却一＊春雨足，眼前无物可关心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '致一斋述事' AND p.poem_author = '范成大';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南内朝贺归呈同官', '韩愈', '唐代', '薄云蔽秋曦，清雨不成泥。罢贺南内衙，归凉晓凄凄。 \n 绿槐十二街，涣散驰轮蹄。余惟戆书生，孤身无所赍。 \n 三黜竟不去，致官九列齐。岂惟一身荣，佩玉冠簪犀。 \n 滉荡天门高，著籍朝厥妻。文才不如人，行又无町畦。 \n 问之朝廷事，略不知东西。况于经籍深，岂究端与倪。 \n 君恩太山重，不见酬稗稊。所职事无多，又不自提撕。 \n 明庭集孔鸾，曷取于凫鹥.树以松与柏，不宜间蒿藜。 \n 婉娈自媚好，几时不见挤。贪食以忘躯，鲜不调盐醯。 \n 法吏多少年，磨淬出角圭。将举汝愆尤，以为己阶梯。 \n 收身归关东，期不到死迷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南内朝贺归呈同官' AND p.poem_author = '韩愈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('赠伯澜', '丘逢甲', '清代', '乘兴曾游大海东，樱花开处唱秦风。归来小试经纶手，一卷周官补考工。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '赠伯澜' AND p.poem_author = '丘逢甲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西瓜', '顾逢', '宋代', '多自淮乡得，天然碧玉团。破来肌体莹，嚼处齿牙寒。\n\n清敌炎威退，凉生酒量宽。东门无此种，雪片簇冰盘。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西瓜' AND p.poem_author = '顾逢';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哀江南八首 其八', '谢榛', '明代', '氛祲频年动，东南尽处看。海摇千舰出，兵犯七闽寒。\n\n杀伐宁无定，凭陵信有端。遥闻日本使，犹自贡长安。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哀江南八首 其八' AND p.poem_author = '谢榛';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('句', '孙月境', '宋代', '莫欺春到荼醾尽，更有杨花落后飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '句' AND p.poem_author = '孙月境';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('忆袁氏姊', '黄仁基', '近代', '炮声晚未休，云自苏山北。老姐招不来，守此山中宅。\n\n避寇互来往，久聚忘主客。熟知寇未至，我与姐复隔。\n\n去年六月晨，倚涧方朝汲。奔雷赴其前，巨弹背后坼。\n\n跳波溅衣襟，两耳为之塞。至今水边石，有铁尚深黑。\n\n性命才脱遗，悲愤又横臆。独坐对苍茫，倾耳待其寂。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '忆袁氏姊' AND p.poem_author = '黄仁基';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('食荠有感二首 其二', '韩雍', '明代', '宦辙驱驰二十霜，迁官今喜到南荒。消閒遂我吟诗兴，取乐留宾索酒尝。\n\n薇省漫言勋业减，金瓯谁覆姓名香。食前方丈成何用，不若贫家菜味长。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '食荠有感二首 其二' AND p.poem_author = '韩雍';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('双楠送何致远归陕西二首 其一', '张嵲', '宋代', '乱后生涯似转蓬，何堪送客值秋风。含悽试看东归路，只见青山绕汉中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '双楠送何致远归陕西二首 其一' AND p.poem_author = '张嵲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和春深二十首 其十', '白居易', '唐代', '何处春深好，春深经业家。唯求太常第，不管曲江花。\n\n折桂名惭郤，收萤志慕车。官场泥补处，最怕寸阴斜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和春深二十首 其十' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬纪伯紫即送其之晋阳', '杨思圣', '明代', '大江势浩浩，南北错舆舱。往往异人出，结交在一言。\n\n我家漳水涯，子居白下门。素心各有托，意气自孤骞。\n\n相逢长安陌，双眼望朝暾。长安多王侯，第宅若云屯。\n\n绮筵罗珍食，朱缨驰华轩。宾从纷遝沓，附势如灼薰。\n\n静交有吾徒，冥然绝世喧。不就唐生决，肯借金张援。\n\n时时顾蓬径，樽酒共讨论。落日登高台，慷慨天为昏。\n\n击筑声泪下，重招烈士魂。忽整晋阳驾，贻诗重玙璠。\n\n以俪魏给事，无乃非其伦。感君安所赠，此意贵永敦。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬纪伯紫即送其之晋阳' AND p.poem_author = '杨思圣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('寄叶解元', '韩淲', '宋代', '醉中曾写雪色壁，非此主人无此客。夜寒烟雨池阁深，秉烛看梅忘堕帻。\n\n春来相望鹅湖边，桃花满地松拂天。抱琴挟书过飘泉，想君风度尤翩翩。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '寄叶解元' AND p.poem_author = '韩淲';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('眼儿媚', '赵桓', '宋代', '宸传三百旧京华。仁孝自名家。一旦奸邪，倾天拆地，忍听琵琶。 \n 如今在外多萧索，迤逦近胡沙。家邦万里，伶仃父子，向晓霜花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '眼儿媚' AND p.poem_author = '赵桓';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('涿郡览古 其五', '弘历', '清代', '琼楼边洞乘云去，璧水琴高跨鲤来。此事今胡艰目睹，列仙传记果真哉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '涿郡览古 其五' AND p.poem_author = '弘历';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('萧洒桐庐郡十绝 其四', '范仲淹', '宋代', '萧洒桐庐郡，公馀午睡浓。人生安乐处，谁复问千钟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '萧洒桐庐郡十绝 其四' AND p.poem_author = '范仲淹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('上黄端明寿诗以竚期三入后一品见玄孙为韵', '李吕', '宋代', '骨秀类天人，神清若岩电。\n寿与山岳齐，造物兹可见。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '上黄端明寿诗以竚期三入后一品见玄孙为韵' AND p.poem_author = '李吕';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('初夏别墅', '林表民', '宋代', '池馆春方谢，连朝雨似烟。\n乱荷藏睡鹭，繁木集嘶蝉。\n地僻观书乐，心清得句玄。\n野僧时过我，携手弄云泉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '初夏别墅' AND p.poem_author = '林表民';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杂感六首 其二', '陆游', '宋代', '士生诵二典，恍若生唐虞。升降奉玉帛，可否闻吁俞。\n\n阙里得其传，功与造化俱。孰知千载后，乃尊重译书。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杂感六首 其二' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('书韩隐人壁', '赵湘', '宋代', '雨黑径垂莎，全家在薜萝。\n树高穿井出，门掩烧痕过。\n写易澌生砚，悬壶月上柯。\n近来山屐老，枯齿旅无多。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '书韩隐人壁' AND p.poem_author = '赵湘';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵蔡叔清六言二首其', '赵蕃', '宋代', '陶潜必遗俗患，侯喜新有诗声。\n容我深藏蹇步，看君大展修程。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵蔡叔清六言二首其' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('夏日游永光寺', '李英', '明代', '石径经行处，禅堂爱客吟。残花含雨落，新竹入园深。\n\n松偃苔能上，山高日易沈。僧来同把袂，半偈去尘心。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '夏日游永光寺' AND p.poem_author = '李英';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('浮邱八景 其四 大雅堂', '邓时雨', '明代', '太史藏书开石室，超然云构傍丹邱。追思雅颂成周日，海内争誇共唱酬。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '浮邱八景 其四 大雅堂' AND p.poem_author = '邓时雨';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('即事', '张穆', '明代', '门前溪水接平湖，酒舍渔家共一区。莲舫载书疑太乙，羊裘垂钓笑潜夫。\n\n蘋风不定蜻蜓立，柳色难分翡翠俱。沧海新来说深浅，他年将更问麻姑。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '即事' AND p.poem_author = '张穆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题诗意图', '陶宗仪', '元代', '杖藜访友趁萧閒，采药山深待未还。流水石桥松影合，溪童指点乱云间。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题诗意图' AND p.poem_author = '陶宗仪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('东郊', '郭祥正', '宋代', '东郊怅望惜春归，颇觉年来万事非。不奈离愁须觅酒，得闻歌响却沾衣。\n\n蜜蜂捕蕊穿花去，巢燕寻泥拍水飞。物态风光能几许，老无忧患世人稀。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '东郊' AND p.poem_author = '郭祥正';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('咏史二十二首 其十八 后梁太祖', '赵戣', '宋代', '未必黄明在，终令丑口亡。难教疏网漏，不直败毡藏。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '咏史二十二首 其十八 后梁太祖' AND p.poem_author = '赵戣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('虎丘寺同子与孔嘉淳父公瑕伯龙舍弟送别袁鲁望张伯起会试北上得阳字', '王世贞', '明代', '绝巘精蓝半夕阳，清尊别思倚苍茫。凭栏顿喜云霄近，结驷毋惊道路长。\n\n池拥双龙元是剑，天回北斗尽成章。因窥雁塔岧峣里，似有题名在上方。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '虎丘寺同子与孔嘉淳父公瑕伯龙舍弟送别袁鲁望张伯起会试北上得阳字' AND p.poem_author = '王世贞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('袷乡回升楼', '佚名', '隋代', '涣号爰发，皇敷至仁。\n幽隐尽达，洪德日新。\n国容肃穆，天宇晏温。\n惠浃四远，富寿无垠。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '袷乡回升楼' AND p.poem_author = '佚名';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('临江仙 其三用欧阳永叔夏景韵', '龚鼎孳', '明代', '谁遣封姨吹画楫，晴湖蹴作涛声。轻寒罗袖最分明。\n\n催花落尽。此别太生生。\n\n薄福东君应自悔，一春云幔风旌。双蛾小皱縠纹平。\n\n夕阳无赖，不管钿钗横。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '临江仙 其三用欧阳永叔夏景韵' AND p.poem_author = '龚鼎孳';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('刘太尉琨伤乱', '江淹', '南北朝', '皇晋遘阳九，天下横氛雾。\n秦赵值薄蚀，幽并逢虎据。\n伊余荷宠灵，感激狥驰骛。\n虽无六奇术，冀与张韩遇。\n宁戚扣角歌，桓公遭乃举。\n荀息冒险难，实以忠贞故。\n空令日月逝，愧无古人度。\n饮马出城濠，北望沙漠路。\n千里何萧条，白日隐寒树。\n投袂既愤懑，抚枕怀百虑。\n功名惜未立，玄发已改素。\n时哉苟有会，治乱惟冥数。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '刘太尉琨伤乱' AND p.poem_author = '江淹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自安仁至豫章途中杂兴十九首 其三', '赵蕃', '宋代', '极目荒陂十里馀，坏塍依约旧犁锄。问言业薄无牛力，更说州家催积租。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自安仁至豫章途中杂兴十九首 其三' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂二百零五首 其二十一', '释正觉', '宋代', '深明无底，灵异无根。案山行尽，不见有家。识浪沥乾，不见有己。\n\n石女掣开金锁钥，木人拨动玉轮机。方信道从佛口生，法化生得佛法分。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂二百零五首 其二十一' AND p.poem_author = '释正觉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('有鸟二十章 其十', '元稹', '唐代', '有鸟有鸟名为鸮，深藏孔穴难动摇。鹰鹯绕树探不得，随珠弹尽声转娇。\n\n主人烦惑罢擒取，许占神林为物妖。当时幸有燎原火，何不鼓风连夜烧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '有鸟二十章 其十' AND p.poem_author = '元稹';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('答瘿公', '黄节', '清代', '直知无俚惟听曲，已笑何缘却赠词。贺老琵琶李谟笛，不堪重为念奴悲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '答瘿公' AND p.poem_author = '黄节';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鳙溪行', '王炎', '宋代', '小溪一曲山四合，溪边杨柳藏门阑。\n当时玉人在花下，对花窈窕矜红颜。\n一双白璧不可聘，许我结佩乘青鸾。\n我时年少气方锐，自负落笔翻波澜。\n谓趁春风上霄汉，可以终老同清欢。\n不知辛苦得一第，始见崎岖行路难。\n有如萍草无根蒂，二纪流落江湖间。\n莫年通籍入金马，虎豹嗔人窥九关。\n天边失脚身堕地，春风破浪扁舟还。\n云軿未几舍我去，空委玉骨埋青山。\n重来溪上事皆变，惆怅齐眉难再见。\n王母麻姑安在哉，过眼百年皆露电。\n老身老子恩义深，不为向来花映面。\n花枝一谢明年开，玉人一去何时回。\n人今不见花亦尽，至此终日空徘徊。\n百川宁有西流水，万古滔滔同一轨。\n不堪回首细绎思，临没之言犹在耳。\n蜀乡有凤空求凰，秦树无乌共将子。\n年来年去春复冬，眩生有尽情无穷。\n一泓清泪洒不断，四山萧飒来悲风。\n惟有老人老更健，年过九十如霜松。\n尊则吾母舅，亲又吾妇翁。\n收泪相劳问，停车少从容。\n悲思无益不自禁，暂时借酒浇心胸。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鳙溪行' AND p.poem_author = '王炎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('酬韩质舟行阻冻', '韦应物', '唐代', '晨坐枉嘉藻，持此慰寝兴。中获辛苦奏，长河结阴冰。 \n 皓曜群玉发，凄清孤景凝。至柔反成坚，造化安可恒。 \n 方舟未得行，凿饮空兢兢。寒苦弥时节，待泮岂所能。 \n 何必涉广川，荒衢且升腾。殷勤宣中意，庶用达吾朋。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '酬韩质舟行阻冻' AND p.poem_author = '韦应物';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题信州半月岩', '程公许', '宋代', '岩际半轮月，神工幻怪奇。\n本来无显晦，何自有盈亏。\n岚雾凝蟾彩，藤萝影桂枝。\n能令万里客，为尔忆峨眉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题信州半月岩' AND p.poem_author = '程公许';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('渡淮即事', '萨都剌', '元代', '杨花点点冲帆过，燕子双双掠水飞。淮上渔人閒不得，船头对结绿蓑衣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '渡淮即事' AND p.poem_author = '萨都剌';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('邵公济求泰定山房十诗·松门', '苏籀', '宋代', '昼扃熟鹿守，晨启素鸦驯。\n延陵挂孤剑，吴月照峩岷。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '邵公济求泰定山房十诗·松门' AND p.poem_author = '苏籀';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('哭夫诗百首', '薄少君', '明代', '海内风流一瞬倾，彼苍难问古今争。哭君莫作秋闺怨，《薤露》须歌铁板声。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '哭夫诗百首' AND p.poem_author = '薄少君';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('自宜兴过溧阳', '赵蕃', '宋代', '荆溪路入白云径，势与松江相并宽。政以楫轻忧逆浪，忽逢风转起飞翰。\n\n须臾又报一舍过，转盻应无百里难。却恨铜官易成远，不容双目细留看。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '自宜兴过溧阳' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('遣兴十二首 其八', '林大钦', '明代', '已见繁华悲眼前，又闻陵谷变桑田。南州野士居郑谷，不吃鱼粱吃紫烟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '遣兴十二首 其八' AND p.poem_author = '林大钦';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再登斗野亭路旧韵寄太虚', '李之仪', '宋代', '北舟揽黄氏，楚楚不自平。故步聊低回，新月微风清。\n\n蛙声语莫下，泡涌浮修甍。何在超世游，翳路情难倾。\n\n西堂梦不到，春草还复生。长年浸枯蘖，有时怀层城。\n\n适从吴儿炊，又作淮人烹。皇皇遍诸侯，吾人愧安行。\n\n独抱照乘姿，花枝似相明。拂衣归待旦，南州逢顾荣。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再登斗野亭路旧韵寄太虚' AND p.poem_author = '李之仪';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送边将', '李咸用', '唐代', '天骄频犯塞，铁骑又征西。臣节轻乡土，雄心生鼓鼙。 \n 地寒花不艳，沙远日难低。渐喜秋弓健，雕翻白草齐。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送边将' AND p.poem_author = '李咸用';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('春帖子词', '苏轼', '宋代', '草木渐知春，萌芽处处新。\n从今八千岁，合抱是灵椿。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '春帖子词' AND p.poem_author = '苏轼';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('吊陈鲁斋兄丈', '许传霈', '清代', '携杖萝岩下，高风羡岸然。青蓝联旧契，葭莩托良缘。\n\n孰意今把袂，为时未届年。大风一曲后，遽尔渺云烟。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '吊陈鲁斋兄丈' AND p.poem_author = '许传霈';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈颂六十首 其三十三', '释昙华', '宋代', '西天四七，唐土二三。尽向者里钉桩摇橹，新东林为你诸人解缆放船。\n\n未说超宗异目，若得齐眉共瞩。亦可明窗下安排，未免栏腮掴出。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈颂六十首 其三十三' AND p.poem_author = '释昙华';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('怨诗', '孟郊', '唐代', '试妾与君泪，两地滴池水。\n看取芙蓉花，今年为谁死！', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '怨诗' AND p.poem_author = '孟郊';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('偈二首 其一', '释法因', '宋代', '天上月圆，人间月半。七八是数，事却难算。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '偈二首 其一' AND p.poem_author = '释法因';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('秋途暮息', '曾丰', '宋代', '密密初秋雨，蒙蒙欲暮天。\n牛羊争欲下，车马敢求前。\n蟋蟀挑孤咏，梧桐搅独眠。\n及身无一事，梦到汗漫边。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '秋途暮息' AND p.poem_author = '曾丰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('西湖明月引/江城梅花引', '刘埙', '宋代', '江村烟雨暗萧萧。涨寒潮。送春桡。目断京尘，何日听鸾箫。金雀觚棱千里外，指天际，碧云深，魂欲飘。薰炉炷愁烟尽销。酒孤斟、谁与招。满怀情思，任吟笺、赋笔难描。惆怅山风、吹梦老秋宵。绿漾湖心波影阔，终待到，借垂杨、月半桥。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '西湖明月引/江城梅花引' AND p.poem_author = '刘埙';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('杀羊岩', '姚燮', '清代', '旷尽险重发，目眩心不持。杀羊名其岩，于义竟难知。\n\n殷红抛暗云，林果偶离枝。跳涧来碧猴，急攫无少迟。\n\n穷天寡悦象，生气蚀已亏。好杀不屠狼，残忍终奚为？\n\n初平百卷石，鞭血犹丝丝。要媚山鬼妆，泼草成胭脂。\n\n薄袖难障风，似有微腥吹。且就乌桕坪，一晞阳阿晖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '杀羊岩' AND p.poem_author = '姚燮';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送顾军咨归梁溪', '高启', '明代', '新柳休攀短短条，离愁似雪未能销。\n春回废苑还芳草，人渡空江正落潮。\n德曜宅前今独去，平津门下旧相招。\n重来莫在花开后，拟听狂歌醉几朝。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送顾军咨归梁溪' AND p.poem_author = '高启';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题日出雨脚图二首', '韩元吉', '宋代', '绝壑春林映绿，半山晓雾迷红。\n长忆西岩梦觉，小舟欸乃声中。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题日出雨脚图二首' AND p.poem_author = '韩元吉';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('山居杂咏 其十七 折藕', '成鹫', '明代', '浮生聊寄迹，决绝复奚辞。一洗尘根净，方知涅不缁。\n\n可堪盈手赠，偏与素心宜。大地同饥渴，于君有所思。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '山居杂咏 其十七 折藕' AND p.poem_author = '成鹫';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('华阳吟三十首', '白玉蟾', '宋代', '片饷工夫炼汞池，一炉猛火夜烧天。\n忽然神水落金井，打合灵砂月样圆。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '华阳吟三十首' AND p.poem_author = '白玉蟾';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('十月九日与客饮忽记去年此时自锦屏归山南道', '陆游', '宋代', '去年纵猎韩坛侧，玉鞭自探南山雪。\n今年痛饮蜀江边，金杯却吸峨眉月。\n竹枝歌舞新教成，凄怨传得三巴声。\n城头筑观出云雨，峨眉正与阑干平。\n酒酣诗就掷杯去，醉蹋玻璃江上路。\n悬知幽涧断桥边，已有梅花开半树。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '十月九日与客饮忽记去年此时自锦屏归山南道' AND p.poem_author = '陆游';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('送曹应则归省', '如兰', '明代', '壮志欲飞腾，扶摇北海鹏。双亲俱未老，一弟已为僧。\n\n远水浮春棹，虚窗坐夜灯。明朝望乡国，遥指白云层。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '送曹应则归省' AND p.poem_author = '如兰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('梅花 其二', '司马光', '宋代', '塞北为君戍，江南是妾家。遥知关外雪，只似岭头花。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '梅花 其二' AND p.poem_author = '司马光';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('南阳春日十首 其四', '陈舜俞', '宋代', '花前惆怅转难平，屈指光阴已半生。犹把此身尝患难，不知何日得功名。\n\n未安去住千丝乱，已去悲欢一梦惊。拟入醉乡销此恨，快风无故析春酲。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '南阳春日十首 其四' AND p.poem_author = '陈舜俞';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('二风诗。治风诗五篇。至正', '元结', '唐代', '（古有正王，能正慎恭和以安上下，故为《至正》之诗 \n 一章四韵八句） \n 为君之道，何以为明？功不滥赏，罪不滥刑； \n 谠言则听，谄言不听；王至是然，可为明焉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '二风诗。治风诗五篇。至正' AND p.poem_author = '元结';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次俞子中病起韵', '凌云翰', '元代', '桐江清隐客，头白太平时。每唱紫芝曲，闲临碧落碑。\n\n无愁何用解，示病不须医。恐有登高兴，先期报我知。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次俞子中病起韵' AND p.poem_author = '凌云翰';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('和雁湖先生病起自警八章', '程公许', '宋代', '葆光悟老子说，游仙续景纯诗。\n木铣可使石透，盘水犹严手持。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '和雁湖先生病起自警八章' AND p.poem_author = '程公许';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('丰城送成父弟还玉山三首 其一', '赵蕃', '宋代', '溪上同舟送，江头独步归。秋风方落木，客路要添衣。\n\n故旧询安否，形容话瘠肥。吾行犹许远，尔去复谁依。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '丰城送成父弟还玉山三首 其一' AND p.poem_author = '赵蕃';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('读次文渼陂诗', '王安中', '宋代', '白发郎潜旧令君，东轩携酒几回登。当初天上化凫舄，今日人间下马陵。\n\n边地久无能赋笔，县斋新有读书灯。昔游零落岑参在，故语流传许十称。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '读次文渼陂诗' AND p.poem_author = '王安中';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('过天津访万中丞伯修四首 其四', '胡应麟', '明代', '玉帐梅花照叵罗，南楼吹笛夜如何。中丞节钺行三辅，大将楼船出九河。\n\n赤日桑乾穷兕虎，青天蒲类息蛟鼍。燕然片碣题铭处，万丈穷崖绝顶磨。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '过天津访万中丞伯修四首 其四' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('练川杂诗四首 其四', '张仲深', '元代', '江深风物异，归计每逡巡。有酒愁难破，吟诗兴自神。\n\n枯萑晴似雪，独鹤夜如人。遁世当无闷，行藏一任真。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '练川杂诗四首 其四' AND p.poem_author = '张仲深';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('除夕伍汝真用待隐园韵即席次答五首 其一', '王守仁', '明代', '一年今又去，独客尚无归。人世伤多难，亲庭叹久违。\n\n壮心都欲尽，衰病特相依。旅馆聊随俗，桃符换早扉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '除夕伍汝真用待隐园韵即席次答五首 其一' AND p.poem_author = '王守仁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('鹤冲天 次柳屯田韵', '吴湖帆', '清代', '明蟾海上。比目颙凝望。离会两难期，还相向。爱浪恩波送，秋碧顿回春荡。\n\n名无关得丧。红粉禅心，漫道色生空相。芳盟暗忆，消息风魔情障。\n\n画里唤真真，如亲访。许似桐花凤，秦楼愿，箫吹畅。\n\n凭阑争一饷。好景流连，便尔倚偎随唱。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '鹤冲天 次柳屯田韵' AND p.poem_author = '吴湖帆';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('满江红·题淩云《长沙妓》传奇', '黄之隽', '清代', '似我缘悭，浑不信、当年淮海。人老去、尚招烟月，粉恩香爱。\n\n一管罗浮仙史笔，写生墨沈随风洒。使怜才、一点翠楼心，居然在。\n\n珠十斛，谁堪买。花四照，谁能采。有燕姬梦向，玉堂人拜。\n\n绣虎始知多巧遇，彩鸾端合酬情债。笑樊川、空手写扬州，无聊赖。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '满江红·题淩云《长沙妓》传奇' AND p.poem_author = '黄之隽';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('病目初起汪象先太学以玉簪十二馈我即取小军持承露分贮几上觉茅斋秋色种种撩人报以口号二 其二', '胡应麟', '明代', '荏苒秋光遍六街，玉妃联袂到空斋。军持满插文园露，何似华堂十二钗。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '病目初起汪象先太学以玉簪十二馈我即取小军持承露分贮几上觉茅斋秋色种种撩人报以口号二 其二' AND p.poem_author = '胡应麟';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('再次韵赵帅见寄三首', '陈造', '宋代', '倏晴骤雨寒犹在，约勒群芳未尽开。\n销得燕堂千杖鼓，旋看锦缬裹条枚。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '再次韵赵帅见寄三首' AND p.poem_author = '陈造';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('蜀道', '宗臣', '明代', '蜀道之难自古今，岂令华发独能任。思家多少玄猿泪，解绶徘徊赤子心。\n\n秋落舟航巫峡险，人言风雪锦江深。坐来万里谁消息，明月关山处处砧。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '蜀道' AND p.poem_author = '宗臣';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('发长安堰', '叶绍翁', '宋代', '夏老虫声切，晨兴草气香。\n买瓜依绿树，出水{左氵右旱}青身。\n船聚知村近，牛闲觉昼长，\n双凫莲叶荡，无雨故生凉。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '发长安堰' AND p.poem_author = '叶绍翁';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('济源上枉舒员外两篇因酬六韵', '白居易', '唐代', '歇手不判案，举头仍见山。\n虽来鞍马上，不离诗酒间。\n济源三临泛，王屋一登攀。\n犹嫌百里近，祇得十日闲。\n明朝却归府，尘事如循环。\n犹听瑶华曲，稍开风土颜。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '济源上枉舒员外两篇因酬六韵' AND p.poem_author = '白居易';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('题柳山人壁二首', '叶适', '宋代', '水北柳六一，家传掷卦灵。\n秋清演渔曲，春近著牛经。\n掩肆花竹秀，排门柑橘馨。\n应怜喜功者，虚要岘山铭。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '题柳山人壁二首' AND p.poem_author = '叶适';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('次韵友人山居秋日就述鄙怀八首 其五', '王祎', '元代', '忆昔天子都，三载竟忘归。谓将拾功名，所志非轻肥。\n\n翻然忽自悔，自售古所讥。归来山中居，坐看双轮飞。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '次韵友人山居秋日就述鄙怀八首 其五' AND p.poem_author = '王祎';
INSERT IGNORE INTO edu_poem (poem_title, poem_author, poem_dynasty, poem_content, poem_difficulty) VALUES ('高士颂九十一首 其六十八 梁鸿', '黄省曾', '明代', '伯鸾者何，脩远之子。介耻攀龙，贫资畜豕。仰颂逸民，庶追芳趾。\n\n贞配孟光，骨埋吴土。', 2);
INSERT IGNORE INTO edu_poem_grade (poem_id, grade_level, `grade`) SELECT p.poem_id, '初中', NULL FROM edu_poem p WHERE p.poem_title = '高士颂九十一首 其六十八 梁鸿' AND p.poem_author = '黄省曾';
